export const hanThuSentences: Sentence[] = [
  {"id":"s_work_han_thu_1_1","chapterId":"ch_work_han_thu_1","textTraditional":"師古曰：「紀，理也，統理眾事而繫之於年月者也。」","sentenceOrder":1},
  {"id":"s_work_han_thu_1_2","chapterId":"ch_work_han_thu_1","textTraditional":"高祖，〔一〕沛豐邑中陽里人也，〔二〕姓劉氏。〔三〕母媼〔四〕嘗息大澤之陂，〔五〕夢與神遇。〔六〕是時雷電晦冥，〔七〕父太公往視，則見交龍於上。已而有娠，〔八〕遂產高祖。","sentenceOrder":2},
  {"id":"s_work_han_thu_1_3","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　荀悅曰：「諱邦，字季。邦之字曰國。」張晏曰：「禮諡法無『高』，以為功最高而為漢帝之太祖，故特起名焉。」師古曰：「邦之字曰國者，臣下所避以相代也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_1_4","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　應劭曰：「沛，縣也。豐，其鄉也。」孟康曰：「後沛為郡而豐為縣。」師古曰：「沛者，本秦泗水郡之屬縣。豐者，沛之聚邑耳。方言高祖所生，故舉其本稱以說之也。此下言『縣鄉邑告喻之』，故知邑繫於縣也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_1_5","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「本出劉累，而范氏在秦者又為劉，因以為姓。」","sentenceOrder":5},
  {"id":"s_work_han_thu_1_6","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　文穎曰：「幽州及漢中皆謂老嫗為媼。」孟康曰：「媼，母別名，音烏老反。」師古曰：「媼，女老稱也，孟音是矣。史家不詳著高祖母之姓氏，無得記之，故取當時相呼稱號而言也。其下王媼之屬，意義皆同。至如皇甫謐等妄引讖記，好奇騁博，強為高祖父母名字，皆非正史所說，蓋無取焉。寧有劉媼本姓實存，史遷肯不詳載？即理而言，斷可知矣。他皆類此。」","sentenceOrder":6},
  {"id":"s_work_han_thu_1_7","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　師古曰：「蓄水曰陂。蓋於澤陂隄塘之上休息而寢寐也。陂音彼皮反。」","sentenceOrder":7},
  {"id":"s_work_han_thu_1_8","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　師古曰：「遇，會也。不期而會曰遇。」","sentenceOrder":8},
  {"id":"s_work_han_thu_1_9","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　師古曰：「晦冥皆謂暗也。言大雷電而雲霧晝暗。」","sentenceOrder":9},
  {"id":"s_work_han_thu_1_10","chapterId":"ch_work_han_thu_1","textTraditional":"〔八〕　應劭曰：「娠，動，懷任之意。左傳曰邑姜方娠。」孟康曰：「娠音身，漢史身多作娠，古今字也。」師古曰：「孟說是也。漢書皆以娠為任身字。『邑姜方震』，自為震動之字，不作娠。」","sentenceOrder":10},
  {"id":"s_work_han_thu_1_11","chapterId":"ch_work_han_thu_1","textTraditional":"高祖為人，隆準而龍顏，〔一〕美須髯，〔二〕左股有七十二黑子。〔三〕寬仁愛人，意豁如也。〔四〕常有大度，不事家人生產作業。及壯，試吏，〔五〕為泗上亭長，〔六〕廷中吏無所不狎侮〔七〕。好酒及色。常從王媼、武負貰酒，〔八〕時飲醉臥，武負、王媼見其上常有怪。高祖每酤留飲，酒讎數倍。〔九〕及見怪，歲竟，此兩家常折券棄責。〔一０〕","sentenceOrder":11},
  {"id":"s_work_han_thu_1_12","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　服虔曰：「準音拙。」應劭曰：「隆，高也。準，頰權準也。顏，頟顙也。」李斐曰：「準，鼻也。」文穎曰：「音準的之準。」晉灼曰：「戰國策云『眉目準（頰）〔頞〕權衡』，史記秦始皇蜂目長準。李說文音是也。」師古曰：「頰權〈出頁〉字，豈當借準為之？服音應說皆失之。」","sentenceOrder":12},
  {"id":"s_work_han_thu_1_13","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「在頤曰須，在頰曰髯。髯音人占反。」","sentenceOrder":13},
  {"id":"s_work_han_thu_1_14","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「今中國通呼為黶子，吳楚俗謂之誌。誌者，記也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_1_15","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「豁然開大之貌，音呼活反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_1_16","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　應劭曰：「試用補吏。」","sentenceOrder":16},
  {"id":"s_work_han_thu_1_17","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　師古曰：「秦法十里一亭。亭長者，主亭之吏也。亭謂停留行旅宿食之館。」","sentenceOrder":17},
  {"id":"s_work_han_thu_1_18","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　師古曰：「廷中，郡府廷之中。廷音定。他皆類此。」","sentenceOrder":18},
  {"id":"s_work_han_thu_1_19","chapterId":"ch_work_han_thu_1","textTraditional":"〔八〕　如淳曰：「武，姓也。俗謂老大母為阿負。」師古曰：「劉向列女傳云『魏曲沃負者，魏大夫如耳之母也』。此則古語謂老母為負耳。王媼，王家之媼也。武負，武家之母也。貰，賒也，李登、呂忱並音式制反，而今之讀者謂與射同，乃引地名射陽其字作貰以為證驗，此說非也。假令地名為射，自是假借，亦猶鮦陽音紂，蓮勺音酌，當時所呼，別有意義，豈得即定其字以為正音乎？」","sentenceOrder":19},
  {"id":"s_work_han_thu_1_20","chapterId":"ch_work_han_thu_1","textTraditional":"〔九〕　如淳曰：「讎，亦售也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_1_21","chapterId":"ch_work_han_thu_1","textTraditional":"〔一０〕師古曰：「以簡牘為契券，既不徵索，故折毀之，棄其所負。」","sentenceOrder":21},
  {"id":"s_work_han_thu_1_22","chapterId":"ch_work_han_thu_1","textTraditional":"高祖常繇咸陽，〔一〕縱觀秦皇帝，〔二〕喟然大息，曰：「嗟乎，大丈夫當如此矣！」〔三〕","sentenceOrder":22},
  {"id":"s_work_han_thu_1_23","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　應劭曰：「繇者，役也。」文穎曰：「咸陽，今渭北渭城是也。」師古曰：「咸陽，秦所都。繇讀曰傜，古通用字。」","sentenceOrder":23},
  {"id":"s_work_han_thu_1_24","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「縱，放也。天子出行，放人令觀。觀音工喚反。」","sentenceOrder":24},
  {"id":"s_work_han_thu_1_25","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「喟，歎息貌。大息言其歎息之大。喟音丘位反。」","sentenceOrder":25},
  {"id":"s_work_han_thu_1_26","chapterId":"ch_work_han_thu_1","textTraditional":"單父人呂公〔一〕善沛令，辟仇，從之客，因家焉。〔二〕沛中豪傑吏聞令有重客，皆往賀。〔三〕蕭何為主吏，〔四〕主進，〔五〕令諸大夫曰：「進不滿千錢，坐之堂下。」〔六〕高祖為亭長，素易諸吏，〔七〕乃紿為謁曰「賀錢萬」，〔八〕實不持一錢。謁入，呂公大驚，起，迎之門。〔九〕呂公者，好相人，見高祖狀貌，因重敬之，引入坐上坐。〔一０〕蕭何曰：「劉季固多大言，少成事。」高祖因狎侮諸客，遂坐上坐，無所詘。〔一一〕酒闌，〔一二〕呂公因目固留高祖。〔一三〕竟酒，後。呂公曰：「臣少好相人，〔一四〕相人多矣，無如季相，願季自愛。臣有息女，願為箕帚妾。」〔一五〕酒罷，呂媼怒呂公曰：「公始常欲奇此女，與貴人。〔一六〕沛令善公，求之不與，何自妄許與劉季？」呂公曰：「此非兒女子所知。」卒與高祖。〔一七〕呂公女即呂后也，生孝惠帝、魯元公主〔一八〕。","sentenceOrder":26},
  {"id":"s_work_han_thu_1_27","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　孟康曰：「單音善。父音甫。」師古曰：「地理志山陽縣也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_1_28","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「與沛令相善，因辟仇亡匿，初就為客，後遂家沛也。仇，讎也，音求。」","sentenceOrder":28},
  {"id":"s_work_han_thu_1_29","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「以禮物相慶曰賀。」","sentenceOrder":29},
  {"id":"s_work_han_thu_1_30","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　孟康曰：「主吏，功曹也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_1_31","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　文穎曰：「主賦斂禮進，為之帥也。」鄭氏曰：「主賦斂禮錢也。」師古曰：「進者，會禮之財也。字本作賮，又作贐，音皆同耳。古字假借，故轉而為進。賮又音才忍反。陳遵傳云陳遂與宣帝博，數負進，帝後詔云可以償博進未。其進雖有別解，然而所賭者之財疑充會食，義又與此通。」","sentenceOrder":31},
  {"id":"s_work_han_thu_1_32","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　師古曰：「令，號令也。大夫，客之貴者總稱耳。」","sentenceOrder":32},
  {"id":"s_work_han_thu_1_33","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　師古曰：「素，故也，謂舊時也。易，輕也，音弋豉（也）〔反〕。」","sentenceOrder":33},
  {"id":"s_work_han_thu_1_34","chapterId":"ch_work_han_thu_1","textTraditional":"〔八〕　應劭曰：「紿，欺也。」師古曰：「為謁者，書刺自言爵里，若今參見尊貴而通名也。蓋當時自陳姓名，并列賀錢數耳。紿音徒在反。」","sentenceOrder":34},
  {"id":"s_work_han_thu_1_35","chapterId":"ch_work_han_thu_1","textTraditional":"〔九〕　師古曰：「以其錢多，故特禮之。」","sentenceOrder":35},
  {"id":"s_work_han_thu_1_36","chapterId":"ch_work_han_thu_1","textTraditional":"〔一０〕師古曰：「上坐，尊處也。令於尊處坐。上坐音才臥反，次下亦同。」","sentenceOrder":36},
  {"id":"s_work_han_thu_1_37","chapterId":"ch_work_han_thu_1","textTraditional":"〔一一〕師古曰：「詘，曲懾也，音丘勿反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_1_38","chapterId":"ch_work_han_thu_1","textTraditional":"〔一二〕文穎曰：「闌言希也。謂飲酒者半罷半在，謂之闌。」","sentenceOrder":38},
  {"id":"s_work_han_thu_1_39","chapterId":"ch_work_han_thu_1","textTraditional":"〔一三〕師古曰：「不欲對坐者顯言，故動目而留之。」","sentenceOrder":39},
  {"id":"s_work_han_thu_1_40","chapterId":"ch_work_han_thu_1","textTraditional":"〔一四〕張晏曰：「古人相與語多自稱臣，自卑下之道也，若今人相與言自稱僕也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_1_41","chapterId":"ch_work_han_thu_1","textTraditional":"〔一五〕師古曰：「息，生也。言己所生之女。」","sentenceOrder":41},
  {"id":"s_work_han_thu_1_42","chapterId":"ch_work_han_thu_1","textTraditional":"〔一六〕師古曰：「奇，異也。謂顯而異之，而嫁於貴人。」","sentenceOrder":42},
  {"id":"s_work_han_thu_1_43","chapterId":"ch_work_han_thu_1","textTraditional":"〔一七〕師古曰：「卒，終也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_1_44","chapterId":"ch_work_han_thu_1","textTraditional":"〔一八〕服虔曰：「元，長也。食邑於魯。」韋昭曰：「元，諡也。」師古曰：「公主，惠帝之姊也，以其最長，故號曰元。呂后謂高帝曰張王以魯元故不宜有謀，齊悼惠王尊魯元公主為太后，當時並已謂之元，不得為諡也。韋說失之。」","sentenceOrder":44},
  {"id":"s_work_han_thu_1_45","chapterId":"ch_work_han_thu_1","textTraditional":"高祖嘗告歸之田。〔一〕呂后與兩子居田中，有一老父過請飲，呂后因餔之。〔二〕老父相后曰：「夫人天下貴人也。」令相兩子，見孝惠帝，曰：「夫人所以貴者，乃此男也。」〔三〕相魯元公主，亦皆貴。老父已去，高祖適從旁舍來，呂后具言客有過，相我子母皆大貴。高祖問，曰：「未遠。」乃追及，問老父。老父曰：「鄉者夫人兒子皆以君，〔四〕君相貴不可言。」高祖乃謝曰：「誠如父言，不敢忘德。」〔五〕及高祖貴，遂不知老父處。","sentenceOrder":45},
  {"id":"s_work_han_thu_1_46","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　服虔曰：「告音如嗥呼之嗥。」李斐曰：「休謁之名，吉曰告，凶曰寧。」孟康曰：「古者名吏休假曰告。告又音嚳。漢律，吏二千石有予告，有賜告。予告者，在官有功最，法所當得也。賜告者，病滿三月當免，天子優賜其告，使得帶印綬將官屬歸家治病。至成帝時，郡國二千石賜告不得歸家。至和帝時，予賜皆絕。」師古曰：「告者，請謁之言，謂請休耳。或謂之謝，謝亦告也。假為嗥嚳二音，並無別義，固當依本字以讀之。左氏傳曰『韓獻子告老』，禮記曰『若不得謝』。漢書諸云謝病皆同義。」","sentenceOrder":46},
  {"id":"s_work_han_thu_1_47","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「餔食之餔，屈原曰『餔其糟』是也。以食食人亦謂之餔，國語曰『國中童子無不餔也』，呂氏春秋曰『下壺飧以餔之』，是也。父本請飲，后因食之，故言餔也。餔音必胡反。」","sentenceOrder":47},
  {"id":"s_work_han_thu_1_48","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「言因有此男，故大貴。」","sentenceOrder":48},
  {"id":"s_work_han_thu_1_49","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　如淳曰：「言并得君之貴相也。以或作似。」師古曰：「如說非也。言夫人及兒子以君之故，因得貴耳，不當作似也。鄉讀曰嚮。」","sentenceOrder":49},
  {"id":"s_work_han_thu_1_50","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　師古曰：「誠，實也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_1_51","chapterId":"ch_work_han_thu_1","textTraditional":"高祖為亭長，乃〈古“以”字，形似吕〉竹皮為冠，令求盜之薛治，〔一〕時時冠之，〔二〕及貴常冠，所謂「劉氏冠」也。〔三〕","sentenceOrder":51},
  {"id":"s_work_han_thu_1_52","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　應劭曰：「以竹始生皮作冠，今鵲尾冠是也。求盜者，亭卒。舊時亭有兩卒，一為亭父，掌開閉埽除，一為求盜，掌逐捕盜賊。薛，魯國縣也，有作冠師，故往治之。」文穎曰：「高祖居貧志大，取其約省，與眾有異。」韋昭曰：「竹皮，竹筠也。今南夷取竹幼時績以為帳。」師古曰：「之，往也。竹皮，筍皮，謂筍上所解之籜耳，非竹筠也。今人亦往往為筍皮巾，古之遺制也。韋說失之。〈古“以”字，形似吕〉，古以字。籜音托。」","sentenceOrder":52},
  {"id":"s_work_han_thu_1_53","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「愛珍此冠，休息之暇則冠之。」","sentenceOrder":53},
  {"id":"s_work_han_thu_1_54","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「後遂號為『劉氏冠』者，即此冠也。後詔曰『爵非公乘以上不得冠劉氏冠』者。即此冠。」","sentenceOrder":54},
  {"id":"s_work_han_thu_1_55","chapterId":"ch_work_han_thu_1","textTraditional":"高祖以亭長為縣送徒驪山，〔一〕徒多道亡。自度比至皆亡之，〔二〕到豐西澤中亭，止飲，〔三〕夜皆解縱所送徒。〔四〕曰：「公等皆去，吾亦從此逝矣！」〔五〕徒中壯士願從諸十餘人。高祖被酒，〔六〕夜徑澤中，〔七〕令一人行前。〔八〕行前者還報曰：「前有大蛇當徑，願還。」高祖醉，曰：「壯士行，何畏！」乃前，拔劍斬蛇。蛇分為兩，道開。行數里，醉困臥。後人來至蛇所，有一老嫗夜哭。人問嫗何哭，嫗曰：「人殺吾子。」人曰：「嫗子何為見殺？」嫗曰：「吾子，白帝子也，化為蛇，當道，今者赤帝子斬之〔九〕，故哭。」人乃以嫗為不誠，〔一０〕欲苦之，〔一一〕嫗因忽不見。〔一二〕後人至，高祖覺。〔一三〕告高祖，高祖乃心獨喜，自負。〔一四〕諸從者日益畏之。","sentenceOrder":55},
  {"id":"s_work_han_thu_1_56","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　應劭曰：「秦始皇葬於驪山，故郡國送徒士往作。」文穎曰：「在新豐南。」項氏曰：「故驪戎國也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_1_57","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「度音徒各反。比音必寐反。他皆類此。」","sentenceOrder":57},
  {"id":"s_work_han_thu_1_58","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「豐邑之西，其亭在澤中，因以為名。」","sentenceOrder":58},
  {"id":"s_work_han_thu_1_59","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「縱，放也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_1_60","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　師古曰：「逝，往也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_1_61","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　師古曰：「被，加也。被酒者，為酒所加。被音皮義反。」","sentenceOrder":61},
  {"id":"s_work_han_thu_1_62","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　師古曰：「徑，小道也。言從小道而行，於澤中過，故其下曰有大蛇當徑。」","sentenceOrder":62},
  {"id":"s_work_han_thu_1_63","chapterId":"ch_work_han_thu_1","textTraditional":"〔八〕　師古曰：「行，案行也，音胡更反。」","sentenceOrder":63},
  {"id":"s_work_han_thu_1_64","chapterId":"ch_work_han_thu_1","textTraditional":"〔九〕　應劭曰：「秦襄公自以居西，主少昊之神，作西畤，祠白帝。至獻公時櫟陽雨金，以為瑞，又作畦畤，祠白帝。少昊，金德也。赤帝堯後，謂漢也。殺之者，明漢當滅秦也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_1_65","chapterId":"ch_work_han_thu_1","textTraditional":"〔一０〕師古曰：「謂所言不實。」","sentenceOrder":65},
  {"id":"s_work_han_thu_1_66","chapterId":"ch_work_han_thu_1","textTraditional":"〔一一〕蘇林曰：「欲困苦辱之。」師古曰：「今書苦字或作笞。笞，擊也，音丑之反。」","sentenceOrder":66},
  {"id":"s_work_han_thu_1_67","chapterId":"ch_work_han_thu_1","textTraditional":"〔一二〕師古曰：「見音胡電反。他皆類此。」","sentenceOrder":67},
  {"id":"s_work_han_thu_1_68","chapterId":"ch_work_han_thu_1","textTraditional":"〔一三〕師古曰：「覺謂寢寐而寤也，音功效反。」","sentenceOrder":68},
  {"id":"s_work_han_thu_1_69","chapterId":"ch_work_han_thu_1","textTraditional":"〔一四〕應劭曰：「負，恃也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_1_70","chapterId":"ch_work_han_thu_1","textTraditional":"秦始皇帝嘗曰「東南有天子氣」，於是東游以猒當之。〔一〕高祖隱於芒、碭山澤間，〔二〕呂后與人俱求，常得之。高祖怪問之。呂后曰：「季所居上常有雲氣，故從往常得季。」〔三〕高祖又喜。沛中子弟或聞之，多欲附者矣。","sentenceOrder":70},
  {"id":"s_work_han_thu_1_71","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　師古曰：「猒，塞也，音一涉反。」","sentenceOrder":71},
  {"id":"s_work_han_thu_1_72","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　應劭曰：「芒屬沛國，碭屬梁國，二縣之界有山澤之固，故隱其間。」蘇林曰：「芒音忙遽之忙。碭音唐。」師古曰：「碭亦音宕。所言屬沛國、梁國者，皆是注釋之人據見在所屬，非必本當時稱號境界。他皆類此。」","sentenceOrder":72},
  {"id":"s_work_han_thu_1_73","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「言隨雲氣所在而求得之。」","sentenceOrder":73},
  {"id":"s_work_han_thu_1_74","chapterId":"ch_work_han_thu_1","textTraditional":"秦二世元年〔一〕秋七月，陳涉起蘄，〔二〕至陳，自立為楚王，〔三〕遣武臣、張耳、陳餘略趙地。〔四〕八月，武臣自立為趙王。郡縣多殺長吏以應涉。九月，沛令欲以沛應之。掾、主吏蕭何、曹參曰：〔五〕「君為秦吏，今欲背之，帥沛子弟，恐不聽。願君召諸亡在外者，〔六〕可得數百人，因以劫眾，〔七〕眾不敢不聽。」乃令樊噲召高祖。〔八〕高祖之眾已數百人矣。","sentenceOrder":74},
  {"id":"s_work_han_thu_1_75","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　應劭曰：「始皇欲以一至萬，示不相襲。始者一，故稱二世。」","sentenceOrder":75},
  {"id":"s_work_han_thu_1_76","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　蘇林曰：「蘄音機，縣名，屬沛國。」","sentenceOrder":76},
  {"id":"s_work_han_thu_1_77","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　李奇曰：「秦滅楚，楚人怨秦，故涉因民之欲，自稱楚王，從民望也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_1_78","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「凡言略地者，皆謂行而取之，用功力少。」","sentenceOrder":78},
  {"id":"s_work_han_thu_1_79","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　師古曰：「曹參為掾，蕭何為主吏。」","sentenceOrder":79},
  {"id":"s_work_han_thu_1_80","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　師古曰：「時苦秦虐政，賦役煩多，故有逃亡辟吏。」","sentenceOrder":80},
  {"id":"s_work_han_thu_1_81","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　師古曰：「劫謂威脅之。」","sentenceOrder":81},
  {"id":"s_work_han_thu_1_82","chapterId":"ch_work_han_thu_1","textTraditional":"〔八〕　師古曰：「噲音快。」","sentenceOrder":82},
  {"id":"s_work_han_thu_1_83","chapterId":"ch_work_han_thu_1","textTraditional":"於是樊噲從高祖來。沛令後悔，恐其有變，乃閉城城守，〔一〕欲誅蕭、曹。蕭、曹恐，踰城保高祖。〔二〕高祖乃書帛射城上，與沛父老曰：「天下同苦秦久矣。今父老雖為沛令守，諸侯並起，今屠沛。〔三〕沛今共誅令，擇可立立之，以應諸侯，即室家完。〔四〕不然，父子俱屠，無為也。」父老乃帥子弟共殺沛令，開城門迎高祖，欲以為沛令。高祖曰：「天下方擾，諸侯並起，〔五〕（令）〔今〕置將不善，一敗塗地。〔六〕吾非敢自愛，恐能薄，〔七〕不能完父兄子弟。〔八〕此大事，願（吏）〔更〕擇可者。」蕭、曹（等）皆文吏，自愛，恐事不就，〔九〕後秦種族其家，〔一０〕盡讓高祖。諸父老皆曰：「平生所聞劉季奇怪，當貴，且卜筮之，莫如劉季最吉。」高祖數讓。眾莫肯為，〔一一〕高祖乃立為沛公。〔一二〕祠黃帝，祭蚩尤於沛廷，〔一三〕而釁鼓旗。〔一四〕幟皆赤，〔一五〕由所殺蛇白帝子，（所）殺者赤帝子故也。於是少年豪吏如蕭、曹、樊噲等皆為收沛子弟，得三千人。","sentenceOrder":83},
  {"id":"s_work_han_thu_1_84","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　師古曰：「城守者，守其城也。守音狩。他皆類此。」","sentenceOrder":84},
  {"id":"s_work_han_thu_1_85","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「保，安也，就高祖以自安。」","sentenceOrder":85},
  {"id":"s_work_han_thu_1_86","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「屠謂破取城邑，誅殺其人，如屠六畜然。」","sentenceOrder":86},
  {"id":"s_work_han_thu_1_87","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「完，全也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_1_88","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　師古曰：「擾，亂也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_1_89","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　師古曰：「一見破敗，即當肝腦塗地。」","sentenceOrder":89},
  {"id":"s_work_han_thu_1_90","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　師古曰：「能謂材也。能本獸名，形似熊，足似鹿，為物堅中而強力，故人之有賢材者，皆謂之能。」","sentenceOrder":90},
  {"id":"s_work_han_thu_1_91","chapterId":"ch_work_han_thu_1","textTraditional":"〔八〕　師古曰：「鄉邑之人，老及長者父兄之行，少及幼者子弟之黨，故總而言之。」","sentenceOrder":91},
  {"id":"s_work_han_thu_1_92","chapterId":"ch_work_han_thu_1","textTraditional":"〔九〕　師古曰：「就，成也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_1_93","chapterId":"ch_work_han_thu_1","textTraditional":"〔一０〕師古曰：「誅及種族也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_1_94","chapterId":"ch_work_han_thu_1","textTraditional":"〔一一〕師古曰：「數音所角反。他皆類此。」","sentenceOrder":94},
  {"id":"s_work_han_thu_1_95","chapterId":"ch_work_han_thu_1","textTraditional":"〔一二〕孟康曰：「楚舊僭稱王，其縣宰為公。陳涉為楚王，沛公起應涉，故從楚制，稱曰公。」","sentenceOrder":95},
  {"id":"s_work_han_thu_1_96","chapterId":"ch_work_han_thu_1","textTraditional":"〔一三〕應劭曰：「黃帝戰於阪泉，以定天下。蚩尤亦古天子，好五兵，故祠祭之，求福祥也。」臣瓚曰：「孔子三朝記云蚩尤庶人之貪者，非天子也。管仲曰『割廬山發而出水，金從之出，蚩尤受之以作劍戟』也。」師古曰：「瓚所引者同是大戴禮，出用兵篇，而非三朝記也。其餘則如應說。沛廷，沛縣之廷。」","sentenceOrder":96},
  {"id":"s_work_han_thu_1_97","chapterId":"ch_work_han_thu_1","textTraditional":"〔一四〕應劭曰：「釁，祭也。殺牲以血塗鼓釁呼為釁。」臣瓚曰：「禮記及大戴禮有釁廟之禮，皆無祭事。」師古曰：「許慎云『釁，血祭也』，然即凡殺牲以血祭者皆為釁，安在其無祭事乎？又古人新成鐘鼎，亦必釁之，豈取釁呼為義？應氏之說亦未允也。呼音火亞反。」","sentenceOrder":97},
  {"id":"s_work_han_thu_1_98","chapterId":"ch_work_han_thu_1","textTraditional":"〔一五〕師古曰：「幟，慓也，音式志反。旗旂之屬，幟即總稱焉，史家字或作識，或作志，音義皆同。」","sentenceOrder":98},
  {"id":"s_work_han_thu_1_99","chapterId":"ch_work_han_thu_1","textTraditional":"是月，項梁與兄子羽起吳。田儋與從弟榮、橫起齊，〔一〕自立為齊王。韓廣自立為燕王。魏咎自立為魏王。陳涉之將周章西入關，至戲，〔二〕秦將章邯距破之。〔三〕","sentenceOrder":99},
  {"id":"s_work_han_thu_1_100","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　服虔曰：「儋音負擔之擔。」師古曰：「音丁甘反。」","sentenceOrder":100},
  {"id":"s_work_han_thu_1_101","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　應劭曰：「章字文，陳人也。戲，弘農湖縣西界也。」孟康曰：「水名也。」蘇林曰：「在新豐東南三十里。」師古曰：「戲在新豐東，今有戲水驛。其水本出藍田北界橫嶺，至此而北流入渭。孟、蘇說是。東越鄭及華陰數百里，然始至湖西界，應說大失之矣。戲音許宜反。」","sentenceOrder":101},
  {"id":"s_work_han_thu_1_102","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　蘇林曰：「邯音酒酣之酣。」師古曰：「音下甘反。」","sentenceOrder":102},
  {"id":"s_work_han_thu_1_103","chapterId":"ch_work_han_thu_1","textTraditional":"秦二年十月，〔一〕沛公攻胡陵、〔二〕方與，〔三〕還守豐。秦泗川監平將兵圍豐。〔四〕二日，出與戰，破之。令雍齒守豐。十一月，沛公引兵之薜。秦泗川守壯兵敗於薛，〔五〕走至戚，〔六〕沛公左司馬得殺之。〔七〕沛公還軍亢父，〔八〕至方與。趙王武臣為其將所殺。十二月，楚王陳涉為其御莊賈所殺。魏人周市略地豐沛，使人謂雍齒曰：「豐，故梁徙也，〔九〕今魏地已定者數十城。齒今下魏，魏以齒為侯守豐；〔一０〕不下，且屠豐。」雍齒雅不欲屬沛公，〔一一〕及魏招之，即反為魏守豐。〔一二〕沛公攻豐，不能取。沛公還之沛，怨雍齒與豐子弟畔之。","sentenceOrder":103},
  {"id":"s_work_han_thu_1_104","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　文穎曰：「十月，秦正月。始皇即位，周火德，以五勝之法勝火者水，秦文公獲黑龍，此水德之瑞，於是更名河為「德水」，十月為正月，謂建亥之月水得位，故以為歲首。」","sentenceOrder":104},
  {"id":"s_work_han_thu_1_105","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　鄧展曰：「屬山陽，章帝元和年改為胡陵。」","sentenceOrder":105},
  {"id":"s_work_han_thu_1_106","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　鄭氏曰：「音房預，屬山陽郡。」","sentenceOrder":106},
  {"id":"s_work_han_thu_1_107","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　文穎曰：「泗川，今沛郡也，高祖更名沛。秦時御史監郡，若今刺史。平，其名也。」師古曰：「泗川郡川字或為水，其實一也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_1_108","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　如淳曰：「秦并天下為三十六郡，置守、尉、監。此泗川有監有守。壯，其名也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_1_109","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　鄭氏曰：「音憂戚之戚。」如淳曰：「音將毒反。」師古曰：「東海之縣也，讀如本字。」","sentenceOrder":109},
  {"id":"s_work_han_thu_1_110","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　師古曰：「得者，司馬之名。」","sentenceOrder":110},
  {"id":"s_work_han_thu_1_111","chapterId":"ch_work_han_thu_1","textTraditional":"〔八〕　鄭氏曰：「亢音人相抗答，父音甫，屬任城郡。」","sentenceOrder":111},
  {"id":"s_work_han_thu_1_112","chapterId":"ch_work_han_thu_1","textTraditional":"〔九〕　文穎曰：「晉大夫畢萬封魏，今河東河北縣是也。其後為秦所逼徙都，今魏郡魏縣是也。至文侯孫惠王，畏秦，復徙都大梁，今浚儀縣大梁亭是也。故世或言魏惠王，或言梁惠王。至孫假為秦所滅，轉東徙於豐，故曰豐故梁徙也。」臣瓚曰：「史記及世本畢萬居魏，昭子徙安邑，文侯亦居之。汲郡古文云惠王之六年自安邑遷於大梁。」師古曰：「魏不常都於魏郡魏縣，瓚說是也。其他則如文氏之釋。」","sentenceOrder":112},
  {"id":"s_work_han_thu_1_113","chapterId":"ch_work_han_thu_1","textTraditional":"〔一０〕師古曰：「封為侯，因令守豐。」","sentenceOrder":113},
  {"id":"s_work_han_thu_1_114","chapterId":"ch_work_han_thu_1","textTraditional":"〔一一〕蘇林曰：「雅，素也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_1_115","chapterId":"ch_work_han_thu_1","textTraditional":"〔一二〕師古曰：「為音于偽反。」","sentenceOrder":115},
  {"id":"s_work_han_thu_1_116","chapterId":"ch_work_han_thu_1","textTraditional":"正月，張耳等立趙後趙歇為趙王。〔一〕東陽甯君、秦嘉立景駒為楚王，〔二〕在留。〔三〕沛公往從之，道得張良，遂與俱見景駒，請兵以攻豐。時章邯從陳，別將〔四〕司馬{尸二}將兵北定楚地，〔五〕屠相，〔六〕至碭。東陽甯君、沛公引兵西，與戰蕭西，〔七〕不利，還收兵聚留。二月，攻碭，三日拔之。〔八〕收碭兵，得六千人，與故合九千人。三月，攻下邑，拔之。〔九〕還擊豐，不下。四月，項梁擊殺景駒、秦嘉，止薛，沛公往見之。項梁益沛公卒五千人，五大夫將十人。〔一０〕沛公還，引兵攻豐，拔之。雍齒奔魏。","sentenceOrder":116},
  {"id":"s_work_han_thu_1_117","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　鄭氏曰：「歇音遏絕之遏。」蘇林曰：「歇音毒歇。」師古曰：「依本字以讀之，不當借音。」","sentenceOrder":117},
  {"id":"s_work_han_thu_1_118","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　文穎曰：「秦嘉，東陽郡人，為甯縣君。景駒，楚族。景，氏；駒，名也。」晉灼曰：「東陽，縣也。」臣瓚曰：「陳勝傳云『凌人秦嘉』，然即嘉非東陽人。嘉初起於郯，號大司馬，又不為甯縣君。東陽甯君自一人，秦嘉又一人。」師古曰：「東陽甯君及秦嘉二人是也。東陽者，為其所屬縣名。甯君者，姓甯，時號為君。」","sentenceOrder":118},
  {"id":"s_work_han_thu_1_119","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「留，縣名。」","sentenceOrder":119},
  {"id":"s_work_han_thu_1_120","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　如淳曰：「從陳涉將也。涉在陳，其將相別在他許，皆稱陳。」師古曰：「從謂追討也。尚書曰『夏師敗績，湯遂從之』。」","sentenceOrder":120},
  {"id":"s_work_han_thu_1_121","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　如淳曰：「{尸二}，章邯司馬。」師古曰：「{尸二}，古夷字。」","sentenceOrder":121},
  {"id":"s_work_han_thu_1_122","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　師古曰：「相，縣名。」","sentenceOrder":122},
  {"id":"s_work_han_thu_1_123","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　師古曰：「蕭縣之西。」","sentenceOrder":123},
  {"id":"s_work_han_thu_1_124","chapterId":"ch_work_han_thu_1","textTraditional":"〔八〕　師古曰：「拔者，破城邑而取之，言若拔樹木，並得其根本也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_1_125","chapterId":"ch_work_han_thu_1","textTraditional":"〔九〕　師古曰：「下邑，縣名。」","sentenceOrder":125},
  {"id":"s_work_han_thu_1_126","chapterId":"ch_work_han_thu_1","textTraditional":"〔一０〕蘇林曰：「五大夫，弟九爵名。以五大夫為將，凡十人。」","sentenceOrder":126},
  {"id":"s_work_han_thu_1_127","chapterId":"ch_work_han_thu_1","textTraditional":"五月，項羽拔襄城還。項梁盡召別將。〔一〕六月，沛公如薛，〔二〕與項梁共立楚懷王孫心為楚懷王。〔三〕章邯破殺魏王咎、齊王田儋於臨濟。〔四〕七月，大霖雨。〔五〕沛公攻亢父。章邯圍田榮於東阿。沛公與項梁共救田榮，大破章邯東阿。田榮歸，沛公、項羽追北，〔六〕至城陽，攻屠其城。軍濮陽東，復與章邯戰，又破之。","sentenceOrder":127},
  {"id":"s_work_han_thu_1_128","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　師古曰：「別將，謂小將別在他所者。」","sentenceOrder":128},
  {"id":"s_work_han_thu_1_129","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「如，往也。他皆類此。」","sentenceOrder":129},
  {"id":"s_work_han_thu_1_130","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　應劭曰：「六國為秦所并，楚最無罪，為百姓所思，故求其後，立為楚懷王，以祖諡為號，順民望也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_1_131","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「破其軍而殺其身。」","sentenceOrder":131},
  {"id":"s_work_han_thu_1_132","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　師古曰：「雨三日以上為霖。」","sentenceOrder":132},
  {"id":"s_work_han_thu_1_133","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　服虔曰：「師敗曰北。」韋昭曰：「古背字也，背去而走也。」師古曰：「北，陰幽之處，故謂退敗奔走者為北。老子曰『萬物向陽而負陰』。許慎說文解字云『北，乖也』。史記樂書曰『紂為朝歌北鄙之音』，『朝歌者不時，北者敗也，鄙者陋也』。是知北即訓乖，訓敗，無勞借音。韋昭之徒並為妄矣。」","sentenceOrder":133},
  {"id":"s_work_han_thu_1_134","chapterId":"ch_work_han_thu_1","textTraditional":"章邯復振，〔一〕守濮陽，環水。〔二〕沛公、項羽去攻定陶。八月，田榮立田儋子市為齊王。定陶未下，沛公與項羽西略地至雍丘，與秦軍戰，大敗之，斬三川守李由。〔三〕還攻外黃，外黃未下。","sentenceOrder":134},
  {"id":"s_work_han_thu_1_135","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　李奇曰：「振，整也。」如淳曰：「振，起也，收散卒自振迅而起。」晉灼曰：「左氏云『振廢滯』，如說是也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_1_136","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　文穎曰：「決水以自環守為固也。」張晏曰：「依河水以自環繞作壘。」師古曰：「文說是也。環音宦。」","sentenceOrder":136},
  {"id":"s_work_han_thu_1_137","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　應劭曰：「三川，今河南郡也。由，李斯子。」韋昭曰：「有河、洛、伊，故曰三川也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_1_138","chapterId":"ch_work_han_thu_1","textTraditional":"項梁再破秦軍，有驕色。宋義諫，不聽。秦益章邯兵。九月，章邯夜銜枚擊項梁定陶，〔一〕大破之，殺項梁。時連雨自七月至九月。沛公、項羽方攻陳留，聞梁死，士卒恐，乃與將軍呂臣引兵而東，徙懷王自盱台都彭城。〔二〕呂臣軍彭城東，項羽軍彭城西，沛公軍碭。魏咎弟豹自立為魏王。後九月，〔三〕懷王并呂臣、項羽軍自將之。以沛公為碭郡長，〔四〕封武安侯，將碭郡兵。以羽為魯公，封長安侯，呂臣為司徒，其父呂青為令尹。〔五〕","sentenceOrder":138},
  {"id":"s_work_han_thu_1_139","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　師古曰：「銜枚者，止言語讙囂，欲令敵人不知其來也。周官有銜枚氏。枚狀如箸，橫銜之，繣絜於項。繣者，結礙也。絜，繞也。蓋為結紐而繞項也。繣音獲。絜音頡。」","sentenceOrder":139},
  {"id":"s_work_han_thu_1_140","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　鄭氏曰：「音昫怡。」師古曰：「昫音許于反。」","sentenceOrder":140},
  {"id":"s_work_han_thu_1_141","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　文穎曰：「即閏九月也。時律曆廢，不知閏，謂之後九月。」如淳曰：「時因秦以十月為歲首，至九月則歲終。後九月即閏月。」師古曰：「文說非也。若以律曆廢不知閏者，則當徑謂之十月，不應有後九月。蓋秦之曆法，應置閏者總致之於歲末。觀其此意，當取左傳所謂歸餘於終耳。何以明之？據漢書表及史記，漢未改秦曆之前，迄至高后、文帝，屢書後九月，是知故然，非曆廢也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_1_142","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　蘇林曰：「長如郡守也。」韋昭曰：「秦名曰守，是時改曰長。」","sentenceOrder":142},
  {"id":"s_work_han_thu_1_143","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　應劭曰：「天子曰師尹，諸侯曰令尹。時去六國尚近，故置令尹。」臣瓚曰：「諸侯之卿，唯楚稱令尹，其餘國稱相。時立楚之後，故置官司皆如楚舊也。」師古曰：「瓚說得之。」","sentenceOrder":143},
  {"id":"s_work_han_thu_1_144","chapterId":"ch_work_han_thu_1","textTraditional":"章邯已破項梁，以為楚地兵不足憂，乃渡河北擊趙王歇，大破之。歇保鉅鹿城，秦將王離圍之。趙數請救，懷王乃以宋義為上將，項羽為次將，范增為末將，北救趙。","sentenceOrder":144},
  {"id":"s_work_han_thu_1_145","chapterId":"ch_work_han_thu_1","textTraditional":"初，懷王與諸將約，先入定關中者王之。〔一〕當是時，秦兵彊，常乘勝逐北，諸將莫利先入關。〔二〕獨羽怨秦破項梁，奮勢〔三〕，願與沛公西入關。懷王諸老將皆曰：「項羽為人慓悍禍賊，〔四〕嘗攻襄城，襄城無噍類，〔五〕所過無不殘滅。且楚數進取，〔六〕前陳王、項梁皆敗，〔七〕不如更遣長者扶義而西，〔八〕告諭秦父兄。秦父兄苦其主久矣，今誠得長者往，毋侵暴，宜可下。項羽不可遣，獨沛公素寬大長者。」卒不許羽，而遣沛公西收陳王、項梁散卒。乃道碭〔九〕至（陽城）〔城陽〕與杠里，〔一０〕攻秦軍壁，破其二軍。","sentenceOrder":145},
  {"id":"s_work_han_thu_1_146","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　師古曰：「約，要也，謂言契也。自函谷關以西總名關中。」","sentenceOrder":146},
  {"id":"s_work_han_thu_1_147","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「不以入關為利，言畏秦也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_1_148","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　晉灼曰：「憤激也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_1_149","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「慓，疾也。悍，勇也。禍賊者，好為禍害而殘賊也。慓音頻妙反，又匹妙反。悍音胡旦反。」","sentenceOrder":149},
  {"id":"s_work_han_thu_1_150","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　如淳曰：「噍音祚笑反。無復有活而噍食者也。青州俗呼無孑遺為無噍類。」","sentenceOrder":150},
  {"id":"s_work_han_thu_1_151","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　如淳曰：「楚謂陳涉。數進取，多所攻取也。」師古曰：「楚者，總言楚兵，陳涉、項梁皆是。」","sentenceOrder":151},
  {"id":"s_work_han_thu_1_152","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　孟康曰：「前陳王，陳涉也。」師古曰：「孟說非也。此言前者陳王及項梁皆敗，今須得長者往，非謂涉為前陳王也，安有後陳王乎？」","sentenceOrder":152},
  {"id":"s_work_han_thu_1_153","chapterId":"ch_work_han_thu_1","textTraditional":"〔八〕　師古曰：「扶，助也，以義自助也。扶字或作杖，杖亦倚任之意。」","sentenceOrder":153},
  {"id":"s_work_han_thu_1_154","chapterId":"ch_work_han_thu_1","textTraditional":"〔九〕　孟康曰：「道由碭。」","sentenceOrder":154},
  {"id":"s_work_han_thu_1_155","chapterId":"ch_work_han_thu_1","textTraditional":"〔一０〕孟康曰：「二縣名也。」師古曰：「杠音江。」","sentenceOrder":155},
  {"id":"s_work_han_thu_1_156","chapterId":"ch_work_han_thu_1","textTraditional":"秦三年十月，齊將田都畔田榮，將兵助項羽救趙。沛公攻破東郡尉於成武。〔一〕十一月，項羽殺宋義，并其兵渡河，自立為上將軍，諸將黥布等皆屬。十二月，沛公引兵至栗，〔二〕遇剛武侯，〔三〕奪其軍四千餘人，并之，與魏將皇欣、武滿軍合，攻秦軍，破之。故齊王建孫田安〔四〕下濟北，從項羽救趙。羽大破秦軍鉅鹿下，虜王離，走章邯。〔五〕","sentenceOrder":156},
  {"id":"s_work_han_thu_1_157","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　孟康曰：「尉，郡都尉也。」師古曰：「本謂之郡尉，至景帝時乃改曰都尉。」","sentenceOrder":157},
  {"id":"s_work_han_thu_1_158","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　韋昭曰：「栗，沛郡縣名也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_1_159","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　應劭曰：「楚懷王將也。功臣表棘蒲剛侯陳武。武一姓柴。剛武侯宜為剛侯武，魏將也。」孟康曰：「功臣表柴武以將軍起薛，至霸上，入漢中，非懷王將，又非魏將也，例未有稱諡者。」師古曰：「史失其名姓，唯識其爵號，不知誰也。不當改剛武侯為剛侯武。應氏以為懷王將，又云魏將，無所據矣。」","sentenceOrder":159},
  {"id":"s_work_han_thu_1_160","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「建，齊襄王子也，立四十四年為秦兵所擊，以兵降秦。秦虜之，遷建於河內，遂滅齊。」","sentenceOrder":160},
  {"id":"s_work_han_thu_1_161","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　師古曰：「章邯被破而走。」","sentenceOrder":161},
  {"id":"s_work_han_thu_1_162","chapterId":"ch_work_han_thu_1","textTraditional":"二月，沛公從碭北攻昌邑，遇彭越。越助攻昌邑，未下。沛公西過高陽，〔一〕酈食其為里監門，〔二〕曰：「諸將過此者多，吾視沛公大度。」乃求見沛公。沛公方踞床，使兩女子洗。〔三〕酈生不拜，長揖曰：〔四〕「足下必欲誅無道秦，不宜踞見長者。」於是沛公起，攝衣謝之，延上坐。食其說沛公襲陳留。〔五〕沛公以為廣野君，以其弟商為將，將陳留兵。三月，攻開封，未拔。〔六〕西與秦將楊熊會戰白馬，〔七〕又戰曲遇東，〔八〕大破之。楊熊走之滎陽，〔九〕二世使使斬之以徇。〔一０〕四月，南攻潁川，屠之。因張良遂略韓地。〔一一〕","sentenceOrder":162},
  {"id":"s_work_han_thu_1_163","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　文穎曰：「聚邑名，屬陳留圉。」臣瓚曰：「陳留傳在雍丘西南。」","sentenceOrder":163},
  {"id":"s_work_han_thu_1_164","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　服虔曰：「音歷異基。」蘇林曰：「監門，門卒也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_1_165","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「踞，反企也。洗，洗足也。踞音據。洗音先典反。」","sentenceOrder":165},
  {"id":"s_work_han_thu_1_166","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「長揖者，手自上而極下。」","sentenceOrder":166},
  {"id":"s_work_han_thu_1_167","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　臣瓚曰：「輕行無鐘鼓曰襲。」","sentenceOrder":167},
  {"id":"s_work_han_thu_1_168","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　師古曰：「開封，縣名，屬滎陽。」","sentenceOrder":168},
  {"id":"s_work_han_thu_1_169","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　師古曰：「白馬亦縣名，屬東郡。」","sentenceOrder":169},
  {"id":"s_work_han_thu_1_170","chapterId":"ch_work_han_thu_1","textTraditional":"〔八〕　文穎曰：「地名也。」蘇林曰：「曲音齲。遇音顒。」師古曰：「齲音丘羽反。」","sentenceOrder":170},
  {"id":"s_work_han_thu_1_171","chapterId":"ch_work_han_thu_1","textTraditional":"〔九〕　師古曰：「西走也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_1_172","chapterId":"ch_work_han_thu_1","textTraditional":"〔一０〕師古曰：「徇，行示也。司馬法曰『斬以徇』，言使人將行遍示眾士以為戒。」","sentenceOrder":172},
  {"id":"s_work_han_thu_1_173","chapterId":"ch_work_han_thu_1","textTraditional":"〔一一〕文穎曰：「河南新鄭南至潁川南北，皆韓地也。以良累世相韓，故因之。」","sentenceOrder":173},
  {"id":"s_work_han_thu_1_174","chapterId":"ch_work_han_thu_1","textTraditional":"時趙別將司馬卬〔一〕方欲渡河入關，沛公乃北攻平陰，〔二〕絕河津。南，戰雒陽東，軍不利，從轘轅〔三〕至陽城，收軍中馬騎。六月，與南陽守齮戰犨東，〔四〕（大）破之。略南陽郡，南陽守走，保城守宛。〔五〕沛公引兵過宛西。〔六〕張良諫曰：「沛公雖欲急入關，秦兵尚眾，距險。〔七〕今不下宛，宛從後擊，彊秦在前，此危道也。」於是沛公乃夜引軍從他道還，偃旗幟，遲明，圍宛城三匝。〔八〕南陽守欲自剄，〔九〕其舍人陳恢曰：〔一０〕「死未晚也。」乃踰城見沛公，曰：「臣聞足下約先入咸陽者王之，今足下留守宛。宛郡縣連城數十，其吏民自以為降必死，故皆堅守乘城〔一一〕。今足下盡日止攻，士死傷者必多；引兵去宛，宛必隨足下。足下前則失咸陽之約，後有彊宛之患。為足下計，莫若約降，〔一二〕封其守，因使止守，〔一三〕引其甲卒與之西。諸城未下者，聞聲爭開門而待足下，足下通行無所累。」〔一四〕沛公曰：「善。」七月，南陽守齮降，封為殷侯，封陳恢千戶。引兵西，無不下者。至丹水，高武侯鰓、襄侯王陵降。〔一五〕還攻胡陽，遇番君別將梅鋗〔一六〕，與偕攻析、酈，〔一七〕皆降。所過毋得鹵掠，〔一八〕秦民喜。遣魏人甯昌使秦。是月章邯舉軍降項羽，羽以為雍王。瑕丘申陽下河南。〔一九〕","sentenceOrder":174},
  {"id":"s_work_han_thu_1_175","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　師古曰：「卬音五剛反。」","sentenceOrder":175},
  {"id":"s_work_han_thu_1_176","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　孟康曰：「縣名也，屬河南。魏文帝改曰河陰。」","sentenceOrder":176},
  {"id":"s_work_han_thu_1_177","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　臣瓚曰：「險道名也，在緱氏東南。」師古曰：「直渡曰絕。轘音環。」","sentenceOrder":177},
  {"id":"s_work_han_thu_1_178","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「犨，縣名也。齮音蟻。犨音昌由反。」","sentenceOrder":178},
  {"id":"s_work_han_thu_1_179","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　師古曰：「宛，南陽之縣也，音於元反。」","sentenceOrder":179},
  {"id":"s_work_han_thu_1_180","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　師古曰：「未拔宛城而兵過宛城西出。」","sentenceOrder":180},
  {"id":"s_work_han_thu_1_181","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　師古曰：「依險阻而自固以距敵。」","sentenceOrder":181},
  {"id":"s_work_han_thu_1_182","chapterId":"ch_work_han_thu_1","textTraditional":"〔八〕　服虔曰：「欲天疾明也。」文穎曰：「遲，未（明）也。天未明之頃已圍其城矣。」晉灼曰：「文說是也。」師古曰：「文、晉二家得其大意耳。此言圍城事畢，然後天明，明遲於事，故曰遲明。變為去聲，音丈二反。漢書諸言遲某事者，義皆類此。史記遲字作邌，亦徐緩之意也，音黎。」","sentenceOrder":182},
  {"id":"s_work_han_thu_1_183","chapterId":"ch_work_han_thu_1","textTraditional":"〔九〕　鄭氏曰：「剄音姑鼎反。以刀割頸為剄。」","sentenceOrder":183},
  {"id":"s_work_han_thu_1_184","chapterId":"ch_work_han_thu_1","textTraditional":"〔一０〕文穎曰：「主廄內小吏，官名也。」蘇林曰：「藺相如為宦者令舍人。韓信為侯，亦有舍人。」師古曰：「舍人，親近左右之通稱也，後遂以為私屬官號。恢音口回反。」","sentenceOrder":184},
  {"id":"s_work_han_thu_1_185","chapterId":"ch_work_han_thu_1","textTraditional":"〔一一〕師古曰：「乘，登也，謂上城而守也。春秋左氏傳曰『授兵登陴』。」","sentenceOrder":185},
  {"id":"s_work_han_thu_1_186","chapterId":"ch_work_han_thu_1","textTraditional":"〔一二〕師古曰：「共為要約，許其降也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_1_187","chapterId":"ch_work_han_thu_1","textTraditional":"〔一三〕師古曰：「封其郡守為侯，即令守其郡。」","sentenceOrder":187},
  {"id":"s_work_han_thu_1_188","chapterId":"ch_work_han_thu_1","textTraditional":"〔一四〕師古曰：「累音力瑞反。」","sentenceOrder":188},
  {"id":"s_work_han_thu_1_189","chapterId":"ch_work_han_thu_1","textTraditional":"〔一五〕蘇林曰：「鰓音魚鰓之鰓。」晉灼曰：「功臣表戚鰓也。王陵，安國侯王陵也。」韋昭曰：「漢封王陵為安國侯，初起兵時在南陽。南陽有穰縣，疑襄當為穰，而無禾，字省耳。」臣瓚曰：「時韓成封穰侯，江夏有襄，是陵所封也。」師古曰：「戚鰓初從即為郎，以都尉守蘄城，非至丹水乃降也。此自一人耳，不知其姓。王陵亦非安國侯者。晉說非也。韋氏改襄為穰者，蓋亦穿鑿也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_1_190","chapterId":"ch_work_han_thu_1","textTraditional":"〔一六〕蘇林曰：「番，音婆，豫章番陽縣。」韋昭曰：「吳芮初為番令，故號曰番君。鋗音呼玄反。」","sentenceOrder":190},
  {"id":"s_work_han_thu_1_191","chapterId":"ch_work_han_thu_1","textTraditional":"〔一七〕蘇林曰：「酈音蹢躅之蹢。」如淳曰：「音持益反。」師古曰：「析、酈，二縣名。蘇、如兩音並同耳。析縣今內鄉。酈即菊潭縣也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_1_192","chapterId":"ch_work_han_thu_1","textTraditional":"〔一八〕應劭曰：「鹵與虜同。」師古曰：「毋，止之辭也，音與無同。他皆類此。掠音力向反，謂略奪也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_1_193","chapterId":"ch_work_han_thu_1","textTraditional":"〔一九〕服虔曰：「瑕丘，縣名。申，姓；陽，名也。」文穎曰：「姓瑕丘，字申陽。」臣瓚曰：「項羽傳瑕丘公申陽，是瑕丘縣公也。」師古曰：「文說非也。此申陽即項羽所封河南王者耳，何云姓瑕丘乎？」","sentenceOrder":193},
  {"id":"s_work_han_thu_1_194","chapterId":"ch_work_han_thu_1","textTraditional":"八月，沛公攻武關，〔一〕入秦。秦相趙高恐，乃殺二世，使人來，欲約分王關中，〔二〕沛公不許。九月，趙高立二世兄子子嬰為秦王。子嬰誅滅趙高，遣將將兵距嶢關。〔三〕沛公欲擊之，張良曰：「秦兵尚彊，未可輕。願先遣人益張旗幟於山上為疑兵，〔四〕使酈食其、陸賈往說秦將，啗以利。」〔五〕秦將果欲連和，沛公欲許之。張良曰：「此獨其將欲叛，恐其士卒不從，不如因其怠懈擊之。」沛公引兵繞嶢關，踰蕢山，〔六〕擊秦軍，大破之藍田南。遂至藍田，又戰其北，秦兵大敗。","sentenceOrder":194},
  {"id":"s_work_han_thu_1_195","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　應劭曰：「武關，秦南關，通南陽。」文穎曰：「武關在析西百七十里。」","sentenceOrder":195},
  {"id":"s_work_han_thu_1_196","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「自與沛公中分關中之地。」","sentenceOrder":196},
  {"id":"s_work_han_thu_1_197","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　應劭曰：「嶢音堯。嶢山之關。」李奇曰：「在上洛北，藍田南，武關之西。」","sentenceOrder":197},
  {"id":"s_work_han_thu_1_198","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「益，多也。多張旗幟，過其人數，令敵疑有多兵。」","sentenceOrder":198},
  {"id":"s_work_han_thu_1_199","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　師古曰：「啗者，本謂食啗耳，音徒敢反。以食餧人，令其啗食，音則改變為徒濫反。今言以利誘之，取食為譬。他皆類此。」","sentenceOrder":199},
  {"id":"s_work_han_thu_1_200","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　鄭氏曰：「蕢音匱。」蘇林曰：「蕢音蒯。」師古曰：「蘇音是也，丘怪反。」","sentenceOrder":200},
  {"id":"s_work_han_thu_1_201","chapterId":"ch_work_han_thu_1","textTraditional":"元年冬十月，〔一〕五星聚于東井。〔二〕沛公至霸上。〔三〕秦王子嬰素車白馬，係頸以組，〔四〕封皇帝璽符節，〔五〕降枳道旁。〔六〕諸將或言誅秦王，沛公曰：「始懷王遣我，固以能寬容，且人已服降，殺之不祥。」乃以屬吏。〔七〕遂西入咸陽，欲止宮休舍，〔八〕樊噲、張良諫，乃封秦重寶財物府庫，還軍霸上。蕭何盡收秦丞相府圖籍文書。十一月，召諸縣豪桀曰：「父老苦秦苛法久矣，〔九〕誹謗者族，耦語者棄市。〔一０〕吾與諸侯約，先入關者王之，吾當王關中。與父老約，法三章耳：殺人者死，傷人及盜抵罪。〔一一〕餘悉除去秦法。吏民皆按堵如故。〔一二〕凡吾所以來，為父兄除害，非有所侵暴，毋恐！且吾所以軍霸上，待諸侯至而定要束耳。」〔一三〕乃使人與秦吏行至縣鄉邑告諭之。〔一四〕秦民大喜，爭持牛羊酒食獻享軍士。沛公讓不受，曰：「倉粟多，不欲費民。」民又益喜，唯恐沛公不為秦王。","sentenceOrder":201},
  {"id":"s_work_han_thu_1_202","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　如淳曰：「張（倉）〔蒼〕傳云以高祖十月至霸上，故因秦以十月為歲首。」","sentenceOrder":202},
  {"id":"s_work_han_thu_1_203","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　應劭曰：「東井，秦之分野。五星所在，其下當有聖人以義取天下。占見天文志。」","sentenceOrder":203},
  {"id":"s_work_han_thu_1_204","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　應劭曰：「霸上，地名，在長安東三十里，古曰滋水，秦穆公更名霸。」師古曰：「霸水上，故曰霸上，即今所謂霸頭。」","sentenceOrder":204},
  {"id":"s_work_han_thu_1_205","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　應劭曰：「子嬰不敢襲帝號，但稱王耳。素車白馬，喪人之服。組者，天子韍也。係頸者，言欲自殺也。」師古曰：「此組謂綬也，所以帶璽也。韍音弗。」","sentenceOrder":205},
  {"id":"s_work_han_thu_1_206","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　應劭曰：「璽，信也，古者尊卑共之。左傳襄公在楚，季武子使公冶問璽書，追而與之。秦漢尊者以為信，群下乃避之。」師古曰：「符謂諸所合符以為契者也。節以毛為之，上下相重，取象竹節，因以為名，將命者持之以為信。」","sentenceOrder":206},
  {"id":"s_work_han_thu_1_207","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　蘇林曰：「亭名也，在長安東十三里。」師古曰：「枳音軹。軹道亭在霸成觀西四里。」","sentenceOrder":207},
  {"id":"s_work_han_thu_1_208","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　師古曰：「屬，委也，音之欲反。」","sentenceOrder":208},
  {"id":"s_work_han_thu_1_209","chapterId":"ch_work_han_thu_1","textTraditional":"〔八〕　師古曰：「舍，息也，於殿中休息也。一曰舍謂屋舍也。」","sentenceOrder":209},
  {"id":"s_work_han_thu_1_210","chapterId":"ch_work_han_thu_1","textTraditional":"〔九〕　師古曰：「苛，細也，音何。」","sentenceOrder":210},
  {"id":"s_work_han_thu_1_211","chapterId":"ch_work_han_thu_1","textTraditional":"〔一０〕應劭曰：「秦法禁民聚語。耦，對也。」師古曰：「族謂誅及其族也。棄市者，取刑人於市，與眾棄之。」","sentenceOrder":211},
  {"id":"s_work_han_thu_1_212","chapterId":"ch_work_han_thu_1","textTraditional":"〔一一〕服虔曰：「隨輕重制法也。」李奇曰：「傷人有曲直，盜臧有多少，罪名不可豫定，故凡言抵罪，未知抵何罪也。」師古曰：「抵，至也，當也。服、李二說，意並得之，自外諸家，皆妄解釋，故不取也。抵音丁禮反。」","sentenceOrder":212},
  {"id":"s_work_han_thu_1_213","chapterId":"ch_work_han_thu_1","textTraditional":"〔一二〕應劭曰：「按，按次第。堵，牆堵也。」師古曰：「言不遷動也。堵音睹。」","sentenceOrder":213},
  {"id":"s_work_han_thu_1_214","chapterId":"ch_work_han_thu_1","textTraditional":"〔一三〕師古曰：「要亦約。」","sentenceOrder":214},
  {"id":"s_work_han_thu_1_215","chapterId":"ch_work_han_thu_1","textTraditional":"〔一四〕師古曰：「軍中遣人與秦吏相隨，遍至諸縣鄉邑而告諭也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_1_216","chapterId":"ch_work_han_thu_1","textTraditional":"或說沛公曰：「秦富十倍天下，地形彊。今聞章邯降項羽，羽號曰雍王，王關中。即來，沛公恐不得有此。可急使守函谷關，〔一〕毋內諸侯軍，稍徵關中兵以自益，距之。」沛公然其計，從之。十二月，項羽果帥諸侯兵欲西入關，關門閉。聞沛公已定關中，羽大怒，使黥布等攻破函谷關，遂至戲下。沛公左司馬曹毋傷聞羽怒，欲攻沛公，使人言羽曰：「沛公欲王關中，令子嬰相，珍寶盡有之。」欲以求封。亞父范增說羽曰：〔二〕「沛公居山東時，貪財好色，今聞其入關，珍物無所取，婦女無所幸，此其志不小。吾使人望其氣，皆為龍，成五色，此天子氣。急擊之，勿失。」於是饗士，旦日合戰〔三〕。是時，羽兵四十萬，號百萬。沛公兵十萬，號二十萬，〔四〕力不敵。會羽季父左尹項伯素善張良，〔五〕夜馳見張良，具告其實，欲與俱去，毋特俱死。〔六〕良曰：「臣為韓王送沛公，不可不告，亡去不義。」乃與項伯俱見沛公。沛公與伯約為婚姻，曰：「吾入關，秋豪無所敢取，〔七〕籍吏民，封府庫，待將軍。〔八〕所以守關者，備他盜也。日夜望將軍到，豈敢反邪！願伯明言不敢背德。」項伯許諾，即夜復去。戒沛公曰：「旦日不可不早自來謝。」項伯還，具以沛公言告羽，因曰：「沛公不先破關中兵，公巨能入乎？〔九〕且人有大功，擊之不祥，不如因善之。」羽許諾。","sentenceOrder":216},
  {"id":"s_work_han_thu_1_217","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　文穎曰：「是時關在弘農縣衡嶺，今移東，在河南穀城縣。」師古曰：「今桃林縣南有洪溜澗水，即古所謂函谷也。其水北流入河，夾河之岸尚有舊關餘跡焉。穀城即新安。」","sentenceOrder":217},
  {"id":"s_work_han_thu_1_218","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　如淳曰：「亞，次也。尊敬之次父，猶管仲為仲父。」","sentenceOrder":218},
  {"id":"s_work_han_thu_1_219","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「饗謂飲食也。旦日，明旦也。」","sentenceOrder":219},
  {"id":"s_work_han_thu_1_220","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「兵家之法，不言實數，皆增之。」","sentenceOrder":220},
  {"id":"s_work_han_thu_1_221","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　師古曰：「伯者，其字也，名纏。」","sentenceOrder":221},
  {"id":"s_work_han_thu_1_222","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　文穎曰：「特，獨也。無為獨與沛公俱死。」蘇林曰：「特，但也。」師古曰：「蘇說是也。但，空也，空死而無成名。」","sentenceOrder":222},
  {"id":"s_work_han_thu_1_223","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　文穎曰：「豪，秋乃成好，舉盛而言也。」師古曰：「豪成之時，端極纖細，適足諭小，非言其盛。」","sentenceOrder":223},
  {"id":"s_work_han_thu_1_224","chapterId":"ch_work_han_thu_1","textTraditional":"〔八〕　師古曰：「籍謂為簿籍。」","sentenceOrder":224},
  {"id":"s_work_han_thu_1_225","chapterId":"ch_work_han_thu_1","textTraditional":"〔九〕　服虔曰：「巨音渠，猶未應得入也。」師古曰：「服說非也。巨讀曰詎，詎猶豈也。」","sentenceOrder":225},
  {"id":"s_work_han_thu_1_226","chapterId":"ch_work_han_thu_1","textTraditional":"沛公旦日從百餘騎見羽鴻門，〔一〕謝曰：「臣與將軍戮力攻秦，〔二〕將軍戰河北，臣戰河南，不自意先入關，能破秦，與將軍復相見。〔三〕今者有小人言，令將軍與臣有隙。」〔四〕羽曰：「此沛公左司馬曹毋傷言之，不然，籍何以（生）〔至〕此？」羽因留沛公飲。范增數目羽擊沛公，〔五〕羽不應。范增起，出謂項莊曰：「君王為人不忍，〔六〕汝入以劍舞，因擊沛公，殺之。不者，汝屬且為所虜。」莊入為壽。〔七〕壽畢，曰：「軍中無以為樂，請以劍舞。」因拔劍舞。項伯亦起舞，常以身翼蔽沛公。樊噲聞事急，直入，怒甚。羽壯之，賜以酒。噲因譙讓羽。〔八〕有頃，沛公起如廁，招樊噲出，置車官屬，〔九〕獨騎，與樊噲、靳彊、滕公、紀成步，從間道走軍，〔一０〕使張良留謝羽。羽問：「沛公安在？」〔一一〕曰：「聞將軍有意督過之，〔一二〕脫身去，間至軍，〔一三〕故使臣獻璧。」羽受之。又獻玉斗范增。增怒，撞其斗，起曰：「吾屬今為沛公虜矣！」〔一四〕","sentenceOrder":226},
  {"id":"s_work_han_thu_1_227","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　孟康曰：「在新豐東十七里，舊大道北下阪口名。」","sentenceOrder":227},
  {"id":"s_work_han_thu_1_228","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「戮力，并力也，音力竹反，又力周反。」","sentenceOrder":228},
  {"id":"s_work_han_thu_1_229","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「意不自謂得然。」","sentenceOrder":229},
  {"id":"s_work_han_thu_1_230","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「隙謂間隙，言乖離不合。」","sentenceOrder":230},
  {"id":"s_work_han_thu_1_231","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　師古曰：「動目以諭之。」","sentenceOrder":231},
  {"id":"s_work_han_thu_1_232","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　師古曰：「莊，項羽從弟。」","sentenceOrder":232},
  {"id":"s_work_han_thu_1_233","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　師古曰：「凡言為壽，謂進爵於尊者，而獻無疆之壽。」","sentenceOrder":233},
  {"id":"s_work_han_thu_1_234","chapterId":"ch_work_han_thu_1","textTraditional":"〔八〕　師古曰：「譙讓，以辭相責也。譙音才笑反。」","sentenceOrder":234},
  {"id":"s_work_han_thu_1_235","chapterId":"ch_work_han_thu_1","textTraditional":"〔九〕　師古曰：「置，留也，不以自隨。」","sentenceOrder":235},
  {"id":"s_work_han_thu_1_236","chapterId":"ch_work_han_thu_1","textTraditional":"〔一０〕晉灼曰：「紀成，紀通父也。」服虔曰：「走音奏。」師古曰：「間，空也，投空隙而行，不公顯也。走謂趣向也，服音是矣。凡此之類，音義皆同。」","sentenceOrder":236},
  {"id":"s_work_han_thu_1_237","chapterId":"ch_work_han_thu_1","textTraditional":"〔一一〕師古曰：「安在，何在也。他皆類此。」","sentenceOrder":237},
  {"id":"s_work_han_thu_1_238","chapterId":"ch_work_han_thu_1","textTraditional":"〔一二〕師古曰：「督謂視責也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_1_239","chapterId":"ch_work_han_thu_1","textTraditional":"〔一三〕師古曰：「脫，免也，不敢謁辭，苟自免而去，間行以至軍也。脫音他活反。」","sentenceOrder":239},
  {"id":"s_work_han_thu_1_240","chapterId":"ch_work_han_thu_1","textTraditional":"〔一四〕師古曰：「撞音丈江反。」","sentenceOrder":240},
  {"id":"s_work_han_thu_1_241","chapterId":"ch_work_han_thu_1","textTraditional":"沛公歸數日，羽引兵西屠咸陽，殺秦降王子嬰，燒秦宮室，所過無不殘滅。秦民大失望。羽使人還報懷王，懷王曰：「如約。」〔一〕羽怨懷王不肯令與沛公俱西入關，而北救趙，後天下約。乃曰：「懷王者，吾家所立耳，非有功伐，何以得專主約！〔二〕本定天下，諸將與籍也。」春正月，〔三〕陽尊懷王為義帝，實不用其命。","sentenceOrder":241},
  {"id":"s_work_han_thu_1_242","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　師古曰：「謂令沛公王關中。」","sentenceOrder":242},
  {"id":"s_work_han_thu_1_243","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「積功曰伐。春秋左氏傳曰『大夫稱伐』。」","sentenceOrder":243},
  {"id":"s_work_han_thu_1_244","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　如淳曰：「以十月為歲首，而正月更為三時之月。」服虔曰：「漢正月也。」師古曰：「凡此諸月號，皆太初正曆之後，記事者追改之，非當時本稱也。以十月為歲首，即謂十月為正月。今此真正月，當時謂之四月耳。他皆類此。」","sentenceOrder":244},
  {"id":"s_work_han_thu_1_245","chapterId":"ch_work_han_thu_1","textTraditional":"二月，羽自立為西楚霸王，〔一〕王梁、楚地九郡，都彭城。背約，更立沛公為漢王，王巴、蜀、漢中四十一縣，都南鄭。〔二〕三分關中，立秦三將：章邯為雍王，都廢丘；〔三〕司馬欣為塞王〔四〕，都櫟陽；〔五〕董翳為翟王，〔六〕都高奴。〔七〕楚將瑕丘申陽為河南王，都洛陽。趙將司馬卬為殷王，都朝歌。〔八〕當陽君英布為九江王，都六。〔九〕懷王柱國共敖為臨江王，〔一０〕都江陵。〔一一〕番君吳芮為衡山王，都邾。〔一二〕故齊王建孫田安為濟北王。徙魏王豹為西魏王，都平陽。徙燕王韓廣為遼東王。燕將臧荼為燕王，〔一三〕都薊。〔一四〕徙齊王田市為膠東王。齊將田都為齊王，都臨菑。〔一五〕徙趙王歇為代王。趙相張耳為常山王。漢王怨羽之背約，欲攻之，丞相蕭何諫，乃止。〔一六〕","sentenceOrder":245},
  {"id":"s_work_han_thu_1_246","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　文穎曰：「史記貨殖傳曰淮以北沛、陳、汝南、南郡為西楚，彭城以東東海、吳、廣陵為東楚，衡山、九江、江南、豫章、長沙為南楚。羽欲都彭城，故自稱西楚。」孟康曰：「舊名江陵為南楚，吳為東楚，彭城為西楚。」師古曰：「孟說是也。」","sentenceOrder":246},
  {"id":"s_work_han_thu_1_247","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「即今之梁州南鄭縣。」","sentenceOrder":247},
  {"id":"s_work_han_thu_1_248","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　孟康曰：「縣名，今槐里是。」韋昭曰：「即周時犬丘，懿王所都，秦欲廢之，更名廢丘。」","sentenceOrder":248},
  {"id":"s_work_han_thu_1_249","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　韋昭曰：「在長安東，名桃林塞。」師古曰：「取河、華之固為阨塞耳，非桃林也。塞音先代反。」","sentenceOrder":249},
  {"id":"s_work_han_thu_1_250","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　蘇林曰：「櫟音藥。」師古曰：「即今之櫟陽縣是其地。」","sentenceOrder":250},
  {"id":"s_work_han_thu_1_251","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　文穎曰：「本上郡，秦所置，項羽以董翳為王，更名為翟。」","sentenceOrder":251},
  {"id":"s_work_han_thu_1_252","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　師古曰：「今在鄜州界。」","sentenceOrder":252},
  {"id":"s_work_han_thu_1_253","chapterId":"ch_work_han_thu_1","textTraditional":"〔八〕　師古曰：「即今之朝歌縣也。」","sentenceOrder":253},
  {"id":"s_work_han_thu_1_254","chapterId":"ch_work_han_thu_1","textTraditional":"〔九〕　師古曰：「六者，縣名，本古國，皋陶之後。」","sentenceOrder":254},
  {"id":"s_work_han_thu_1_255","chapterId":"ch_work_han_thu_1","textTraditional":"〔一０〕應劭曰：「柱國，上卿官也，若相國矣。共敖，其姓名也。」孟康曰：「本南郡，改為臨江國。」師古曰：「共音龔。」","sentenceOrder":255},
  {"id":"s_work_han_thu_1_256","chapterId":"ch_work_han_thu_1","textTraditional":"〔一一〕師古曰：「即今之荊州江陵縣。」","sentenceOrder":256},
  {"id":"s_work_han_thu_1_257","chapterId":"ch_work_han_thu_1","textTraditional":"〔一二〕文穎曰：「邾音朱，縣名，屬江夏。」","sentenceOrder":257},
  {"id":"s_work_han_thu_1_258","chapterId":"ch_work_han_thu_1","textTraditional":"〔一三〕鄭氏曰：「荼音荼毒之荼。」如淳曰：「音舒。」師古曰：「鄭音是也，音大胡反。」","sentenceOrder":258},
  {"id":"s_work_han_thu_1_259","chapterId":"ch_work_han_thu_1","textTraditional":"〔一四〕師古曰：「薊即幽州薊縣。」","sentenceOrder":259},
  {"id":"s_work_han_thu_1_260","chapterId":"ch_work_han_thu_1","textTraditional":"〔一五〕師古曰：「在今青州。」","sentenceOrder":260},
  {"id":"s_work_han_thu_1_261","chapterId":"ch_work_han_thu_1","textTraditional":"〔一六〕服虔曰：「稱丞相者，錄事追言之。」","sentenceOrder":261},
  {"id":"s_work_han_thu_1_262","chapterId":"ch_work_han_thu_1","textTraditional":"夏四月，諸侯罷戲下，各就國。〔一〕羽使卒三萬人從漢王，楚子、諸侯人之慕從者數萬人，〔二〕從杜南入蝕中。〔三〕張良辭歸韓，漢王送至褒中，〔四〕因說漢王燒絕棧道，〔五〕以備諸侯盜兵，亦視項羽無東意。〔六〕","sentenceOrder":262},
  {"id":"s_work_han_thu_1_263","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　師古曰：「戲謂軍之旌麾也，音許宜反，亦讀曰麾。先是，諸侯從項羽入關者，各帥其軍，聽命於羽，今既受封爵，各使就國，故總言罷戲下也。一說云時從項羽在戲水之上，故言罷戲下，此說非也。項羽見高祖於鴻門，已過戲矣。又入秦燒秦宮室，不復在戲也。漢書通以戲為麾字，義見竇田灌韓傳。」","sentenceOrder":263},
  {"id":"s_work_han_thu_1_264","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　文穎曰：「楚子，猶言楚人也。諸侯人，猶諸侯國人。」","sentenceOrder":264},
  {"id":"s_work_han_thu_1_265","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　李奇曰：「蝕音力，在杜南。」如淳曰：「蝕，入漢中道川谷名。」","sentenceOrder":265},
  {"id":"s_work_han_thu_1_266","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「即今梁州之褒縣也。舊曰褒中，言居褒谷之中。隋室諱忠，改為褒內。」","sentenceOrder":266},
  {"id":"s_work_han_thu_1_267","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　師古曰：「棧即閣也，今謂之閣道。」","sentenceOrder":267},
  {"id":"s_work_han_thu_1_268","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　如淳曰：「視音示。」師古曰：「言令羽知漢王更無東出之意也。漢書多以視為示，古通用字。」","sentenceOrder":268},
  {"id":"s_work_han_thu_1_269","chapterId":"ch_work_han_thu_1","textTraditional":"漢王既至南鄭，諸將及士卒皆歌謳思東歸，〔一〕多道亡還者。〔二〕韓信為治粟都尉，亦亡去，蕭何追還之，因薦於漢王，曰：「必欲爭天下，非信無可與計事者。」於是漢王齊戒設壇場，〔三〕拜信為大將軍，問以計策。信對曰：「項羽背約而王君王於南鄭，〔四〕是遷也。〔五〕吏卒皆山東之人，日夜企而望歸，〔六〕及其鋒而用之，可以有大功。天下已定，民皆自寧，不可復用。〔七〕不如決策東向。」因陳羽可圖〔八〕三秦易并之計。〔九〕漢王大說，〔一０〕遂聽信策，部署諸將。〔一一〕留蕭何收巴蜀租，給軍〔糧〕食。","sentenceOrder":269},
  {"id":"s_work_han_thu_1_270","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　師古曰：「謳，齊歌也，謂齊聲而歌，或曰齊地之歌。謳音一侯反。」","sentenceOrder":270},
  {"id":"s_work_han_thu_1_271","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「未至南鄭，在道即亡歸。」","sentenceOrder":271},
  {"id":"s_work_han_thu_1_272","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「齊讀曰齋。築土而高曰壇，除地為場。」","sentenceOrder":272},
  {"id":"s_work_han_thu_1_273","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「上王音于放反。」","sentenceOrder":273},
  {"id":"s_work_han_thu_1_274","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　如淳曰：「秦法，有罪遷徙之於蜀漢。」","sentenceOrder":274},
  {"id":"s_work_han_thu_1_275","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　師古曰：「企謂舉足而竦身。」","sentenceOrder":275},
  {"id":"s_work_han_thu_1_276","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　師古曰：「寧，安也，各安其處。」","sentenceOrder":276},
  {"id":"s_work_han_thu_1_277","chapterId":"ch_work_han_thu_1","textTraditional":"〔八〕　師古曰：「圖謂謀而取之。」","sentenceOrder":277},
  {"id":"s_work_han_thu_1_278","chapterId":"ch_work_han_thu_1","textTraditional":"〔九〕　應劭曰：「章邯為雍王，司馬欣為塞王，董翳為翟王，分王秦地，故曰三秦。」","sentenceOrder":278},
  {"id":"s_work_han_thu_1_279","chapterId":"ch_work_han_thu_1","textTraditional":"〔一０〕師古曰：「說讀曰悅。」","sentenceOrder":279},
  {"id":"s_work_han_thu_1_280","chapterId":"ch_work_han_thu_1","textTraditional":"〔一一〕師古曰：「分部而署置。」","sentenceOrder":280},
  {"id":"s_work_han_thu_1_281","chapterId":"ch_work_han_thu_1","textTraditional":"五月，漢王引兵從故道〔一〕出襲雍。雍王邯迎擊漢陳倉，雍兵敗，還走；戰好畤，〔二〕又大敗，走廢丘。漢王遂定雍地。東如咸陽，引兵圍雍王廢丘，而遣諸將略地。","sentenceOrder":281},
  {"id":"s_work_han_thu_1_282","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　孟康曰：「縣名，屬武都。」","sentenceOrder":282},
  {"id":"s_work_han_thu_1_283","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　孟康曰：「畤音止，神靈之所止也。好畤，縣名，屬右扶風。」師古曰：「即今雍州好畤縣。」","sentenceOrder":283},
  {"id":"s_work_han_thu_1_284","chapterId":"ch_work_han_thu_1","textTraditional":"田榮聞羽徙齊王市於膠東而立田都為齊王，大怒，以齊兵迎擊田都。都走降楚。六月，田榮殺田市，自立為齊王。時彭城在鉅野〔一〕，眾萬餘人，無所屬。榮與越將軍印，因令反梁地。越擊殺濟北王安，榮遂并三齊之地。〔二〕燕王韓廣亦不肯徙遼東。秋八月，臧荼殺韓廣，并其地。塞王欣、翟王翳皆降漢。","sentenceOrder":284},
  {"id":"s_work_han_thu_1_285","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　師古曰：「鉅野，澤名，因以為縣，今屬鄆州。」","sentenceOrder":285},
  {"id":"s_work_han_thu_1_286","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　服虔曰：「齊與濟北、膠東。」","sentenceOrder":286},
  {"id":"s_work_han_thu_1_287","chapterId":"ch_work_han_thu_1","textTraditional":"初，項梁立韓後公子成為韓王，張良為韓司徒。羽以良從漢王，韓王成又無功，故不遣就國，與俱至彭城，殺之。及聞漢王并關中，而齊、梁畔之，羽大怒，乃以故吳令鄭昌為韓王，距漢。令蕭公角擊彭越，〔一〕越敗角兵。時張良徇韓地，〔二〕遺羽書曰：「漢欲得關中，如約即止，不敢復東。」羽以故無西意，而北擊齊。","sentenceOrder":287},
  {"id":"s_work_han_thu_1_288","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　蘇林曰：「蕭公，官號也。」孟康曰：「蕭令也，時令皆稱公。」師古曰：「孟說是也。」","sentenceOrder":288},
  {"id":"s_work_han_thu_1_289","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　蘇林曰：「徇音巡，撫其民人也。」孟康曰：「徇，略也。」師古曰：「孟說是。音辭峻反。」","sentenceOrder":289},
  {"id":"s_work_han_thu_1_290","chapterId":"ch_work_han_thu_1","textTraditional":"九月，漢王遣將軍薛歐、王吸出武關，〔一〕因王陵兵，〔二〕從南陽迎太公、呂后於沛。羽聞之，發兵距之陽夏，〔三〕不得前。","sentenceOrder":290},
  {"id":"s_work_han_thu_1_291","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　師古曰：「歐音烏垢反。吸音翕。」","sentenceOrder":291},
  {"id":"s_work_han_thu_1_292","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　如淳曰：「王陵亦聚黨數千人，居南陽。」","sentenceOrder":292},
  {"id":"s_work_han_thu_1_293","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　鄭氏曰：「音假借之假。」師古曰：「即今亳州陽夏縣。」","sentenceOrder":293},
  {"id":"s_work_han_thu_1_294","chapterId":"ch_work_han_thu_1","textTraditional":"二年冬十月，項羽使九江王布殺義帝於郴。〔一〕陳餘亦怨羽獨不王己，從田榮藉助兵，〔二〕以擊常山王張耳。耳敗走降漢，漢王厚遇之。陳餘迎代王歇還趙，歇立餘為代王。張良自韓間行歸漢，漢王以為成信侯。","sentenceOrder":294},
  {"id":"s_work_han_thu_1_295","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　文穎曰：「郴，縣名，屬桂陽。」如淳曰：「郴音綝。」師古曰：「說者或以為史記本紀及漢注云衡山、臨江王殺之江中，謂漢書言黥布殺之為錯。然今據史記黥布傳四月陰令九江王等行擊義帝，其八月布使將追殺之郴，又與漢書項羽、英布傳相合，是則衡山、臨江與布同受羽命，而殺之者布也。非班氏之錯。郴綝二字並音丑林反。」","sentenceOrder":295},
  {"id":"s_work_han_thu_1_296","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「藉，借也。」","sentenceOrder":296},
  {"id":"s_work_han_thu_1_297","chapterId":"ch_work_han_thu_1","textTraditional":"漢王如陝，〔一〕鎮撫關外父老。〔二〕河南王申陽降，置河南郡。使韓太尉韓信擊韓，韓王鄭昌降。十一月，立韓太尉信為韓王。漢王還歸，都櫟陽，使諸將略地，拔隴西。以萬人若一郡降者，封萬戶。〔三〕繕治河上塞。〔四〕故秦苑囿園池，令民得田之。〔五〕","sentenceOrder":297},
  {"id":"s_work_han_thu_1_298","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　師古曰：「陝，今陝州陝縣也，音式冉反。」","sentenceOrder":298},
  {"id":"s_work_han_thu_1_299","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「鎮，安也。撫，慰也。」","sentenceOrder":299},
  {"id":"s_work_han_thu_1_300","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「若者，豫及之辭，言以萬人或以一郡降者，皆封萬戶。」","sentenceOrder":300},
  {"id":"s_work_han_thu_1_301","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　晉灼曰：「晁錯傳秦北攻胡，築河上塞。」師古曰：「繕，補也。」","sentenceOrder":301},
  {"id":"s_work_han_thu_1_302","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　師古曰：「養鳥獸曰苑，苑有垣曰囿，所以種植謂之園。田謂耕作也。囿音宥。」","sentenceOrder":302},
  {"id":"s_work_han_thu_1_303","chapterId":"ch_work_han_thu_1","textTraditional":"春正月，羽擊田榮城陽，榮敗走平原，平原民殺之。齊皆降楚，楚焚其城郭，齊人復畔之。諸將拔北地，虜雍王弟章平。赦罪人。二月癸未，令民除秦社稷，立漢社稷。施恩德，賜民爵。〔一〕蜀漢民給軍事勞苦，復勿租稅二歲。〔二〕關中卒從軍者，復家一歲。舉民年五十以上，有脩行，能帥眾為善，置以為三老，鄉一人。擇鄉三老一人為縣三老，與縣令丞尉以事相教，復勿繇戍。〔三〕以十月賜酒肉。","sentenceOrder":303},
  {"id":"s_work_han_thu_1_304","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　臣瓚曰：「爵者，祿位。民賜爵，有罪得以減也。」","sentenceOrder":304},
  {"id":"s_work_han_thu_1_305","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「復者，除其賦役也，音方目反。其下並同。」","sentenceOrder":305},
  {"id":"s_work_han_thu_1_306","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「繇讀曰傜。」","sentenceOrder":306},
  {"id":"s_work_han_thu_1_307","chapterId":"ch_work_han_thu_1","textTraditional":"三月，漢王自臨晉渡河，〔一〕魏王豹降，將兵從。下河內，虜殷王卬，置河內郡。至脩武，陳平亡楚來降。漢王與語，說之，〔二〕使參乘，監諸將。南渡平陰津，〔三〕至洛陽，新城三老董公遮說漢王曰：「臣聞『順德者昌，逆德者亡』，『兵出無名，事故不成』。〔四〕故曰：『明其為賊，敵乃可服。』〔五〕項羽為無道，放殺其主，〔六〕天下之賊也。夫仁不以勇，義不以力，〔七〕三軍之眾為之素服，以告之諸侯，為此東伐，〔八〕四海之內莫不仰德。此三王之舉也。」〔九〕漢王曰：「善，非夫子無所聞。」於是漢王為義帝發喪，袒而大哭，〔一０〕哀臨三日。〔一一〕發使告諸侯曰：「天下共立義帝，北面事之。今項羽放殺義帝江南，大逆無道。寡人親為發喪，兵皆縞素。〔一二〕悉發關中兵，收三河士，〔一三〕南浮江漢以下，願從諸侯王〔一四〕擊楚之殺義帝者。」","sentenceOrder":307},
  {"id":"s_work_han_thu_1_308","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　師古曰：「舊縣名，其地居河之西濱，東臨晉境，本列國時秦所名也，即今之同州朝邑縣界也。」","sentenceOrder":308},
  {"id":"s_work_han_thu_1_309","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":309},
  {"id":"s_work_han_thu_1_310","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　蘇林曰：「在河陰。」","sentenceOrder":310},
  {"id":"s_work_han_thu_1_311","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　蘇林曰：「名者，伐有罪。」","sentenceOrder":311},
  {"id":"s_work_han_thu_1_312","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　應劭曰：「為音無為之為。布告天下，言項羽殺義帝，明其為賊亂，舉兵征之，乃可服也。」鄭氏曰：「為音人相為之為。」師古曰：「應說是也。」","sentenceOrder":312},
  {"id":"s_work_han_thu_1_313","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　師古曰：「殺讀曰弒。諸弒君者，其例皆同。」","sentenceOrder":313},
  {"id":"s_work_han_thu_1_314","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　李奇曰：「彼有仁，我不能以勇服；彼有義，我不能以力服。」文穎曰：「以，用也。己有仁，天下歸之，可不用勇而天下自服；己有義，天下奉之，可不用力而天下自定。」師古曰：「為義帝發喪，此為行仁義，不用勇力，文說是也。」","sentenceOrder":314},
  {"id":"s_work_han_thu_1_315","chapterId":"ch_work_han_thu_1","textTraditional":"〔八〕　師古曰：「為並音于偽反。」","sentenceOrder":315},
  {"id":"s_work_han_thu_1_316","chapterId":"ch_work_han_thu_1","textTraditional":"〔九〕　師古曰：「三王：夏、殷、周也。言以德義取天下，則可比蹤於三王。」","sentenceOrder":316},
  {"id":"s_work_han_thu_1_317","chapterId":"ch_work_han_thu_1","textTraditional":"〔一０〕如淳曰：「袒亦如禮袒踊也。」師古曰：「袒謂脫衣之袖也，音徒旱反。」","sentenceOrder":317},
  {"id":"s_work_han_thu_1_318","chapterId":"ch_work_han_thu_1","textTraditional":"〔一一〕師古曰：「眾哭曰臨，音力禁反。」","sentenceOrder":318},
  {"id":"s_work_han_thu_1_319","chapterId":"ch_work_han_thu_1","textTraditional":"〔一二〕師古曰：「縞，白素也，音工老反。」","sentenceOrder":319},
  {"id":"s_work_han_thu_1_320","chapterId":"ch_work_han_thu_1","textTraditional":"〔一三〕韋昭曰：「河南、河東、河內也。」","sentenceOrder":320},
  {"id":"s_work_han_thu_1_321","chapterId":"ch_work_han_thu_1","textTraditional":"〔一四〕服虔曰：「漢名王為諸侯王。」師古曰：「服說非也。當時漢未有此稱號，直言諸侯及王耳。自謙言隨諸侯王之後也。」","sentenceOrder":321},
  {"id":"s_work_han_thu_1_322","chapterId":"ch_work_han_thu_1","textTraditional":"夏四月，田榮弟橫收得數萬人，立榮子廣為齊王。羽雖聞漢東，既擊齊，欲遂破之而後擊漢，漢王以故得劫五諸侯兵，〔一〕東伐楚。到外黃，彭越將三萬人歸漢。漢王拜越為魏相國，令定梁地。漢王遂入彭城，收羽美人貨賂，置酒高會。〔二〕羽聞之，令其將擊齊，而自以精兵三萬人從魯出胡陵，至蕭，晨擊漢軍，大戰彭城靈壁東〔三〕睢水上，〔四〕大破漢軍，多殺士卒，睢水為之不流。〔五〕圍漢王三匝。大風從西北起，折木發屋，揚砂石，晝晦，〔六〕楚軍大亂，而漢王得與數十騎遁去。過沛，使人求室家，室家亦已亡，不相得。漢王道逢孝惠、魯元，載行。楚騎追漢王，漢王急，推墮二子。滕公下收載，遂得脫。〔七〕審食其從太公、呂后間行，反遇楚軍，〔八〕羽常置軍中以為質。諸侯見漢敗，皆亡去。塞王欣、翟王翳降楚，殷王卬死。","sentenceOrder":322},
  {"id":"s_work_han_thu_1_323","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　應劭曰：「雍、翟、塞、殷、韓也。」如淳曰：「塞、翟、魏、殷、河南也。」韋昭曰：「塞、翟、韓、殷、魏也。雍時已敗。」師古曰：「諸家之說皆非也。張良遺羽書云：『漢欲得關中，如約即止，不敢復東。』東謂出關之東。今羽聞漢東之時，漢固已得三秦矣。五諸侯者，謂常山、河南、韓、魏、殷也。此年十月，常山王張耳降，河南王申陽降，韓王鄭昌降。（二）〔三〕月，魏王豹降，虜殷王卬。皆在漢東之後，故知謂此為五諸侯。時雖未得常山之地，據功臣表云張耳棄國，與大臣歸漢，則亦有士卒也。又叔孫通傳云二年漢王從五諸侯入彭城。爾時雍王猶在廢丘被圍，即非五諸侯之數也。尋此紀文昭然可曉，前賢注釋，並失指趣。」","sentenceOrder":323},
  {"id":"s_work_han_thu_1_324","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　服虔曰：「大會也。」","sentenceOrder":324},
  {"id":"s_work_han_thu_1_325","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　孟康曰：「故小縣，在彭城南。」","sentenceOrder":325},
  {"id":"s_work_han_thu_1_326","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「睢音雖。」","sentenceOrder":326},
  {"id":"s_work_han_thu_1_327","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　師古曰：「殺人既多，填於睢水。」","sentenceOrder":327},
  {"id":"s_work_han_thu_1_328","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　師古曰：「晦，暗也。」","sentenceOrder":328},
  {"id":"s_work_han_thu_1_329","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　鄭氏曰：「滕公，夏侯嬰也。」師古曰：「脫音他活反。」","sentenceOrder":329},
  {"id":"s_work_han_thu_1_330","chapterId":"ch_work_han_thu_1","textTraditional":"〔八〕　師古曰：「此審食其及武帝時趙食其讀皆與酈食其同，音異基。而近代學者，酈則為異基，審則為食基，趙則食其，非也。同是人名，更無別義，就中舛駮，何所據依？且荀悅漢紀三者並為異基字，斷可知矣。太公、呂后本避楚軍，乃反與之遇，而見拘執。」","sentenceOrder":330},
  {"id":"s_work_han_thu_1_331","chapterId":"ch_work_han_thu_1","textTraditional":"呂后兄周呂侯〔一〕將兵居下邑，〔二〕漢王往從之。稍收士卒，軍碭。","sentenceOrder":331},
  {"id":"s_work_han_thu_1_332","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　蘇林曰：「以姓名侯也。」晉灼曰：「外戚表周呂令武侯澤也。呂，縣名，封於呂以為國。」師古曰：「周呂，封名；令武，其諡也。蘇云以姓名侯，非也。」","sentenceOrder":332},
  {"id":"s_work_han_thu_1_333","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「縣名也。」","sentenceOrder":333},
  {"id":"s_work_han_thu_1_334","chapterId":"ch_work_han_thu_1","textTraditional":"漢王西過梁地，至虞，〔一〕謂謁者隨何曰：「公能說九江王布使舉兵畔楚，項王必留擊之。得留數月，吾取天下必矣。」隨何往說布，果使畔楚。","sentenceOrder":334},
  {"id":"s_work_han_thu_1_335","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　師古曰：「即今宋州虞城縣。」","sentenceOrder":335},
  {"id":"s_work_han_thu_1_336","chapterId":"ch_work_han_thu_1","textTraditional":"五月，漢王屯滎陽，蕭何發關中老弱未傅者悉詣軍。〔一〕韓信亦收兵與漢王會，兵復大振。與楚戰滎陽南京、索間，破之。〔二〕築甬道，屬河，〔三〕以取敖倉粟。〔四〕魏王豹謁歸視親疾。〔五〕至則絕河津，反為楚。〔六〕","sentenceOrder":336},
  {"id":"s_work_han_thu_1_337","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　服虔曰：「傅音附。」孟康曰：「古者二十而傅，三年耕有一年儲，故二十三而後役之。」如淳曰：「律，年二十三傅之疇官，各從其父疇學之，高不滿六尺二寸以下為罷癃。漢儀注云民年二十三為正，一歲為衛士，一歲為材官騎士，習射御騎馳戰陳。又曰年五十六衰老，乃得免為庶民，就田里。今老弱未嘗傅者皆發之。未二十三為弱，過五十六為老。」師古曰：「傅，著也。言著名籍，給公家徭役也。服音是。」","sentenceOrder":337},
  {"id":"s_work_han_thu_1_338","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　應劭曰：「京，縣名。今有大索、小索亭。」晉灼曰：「音冊。」師古曰：「音求索之索。」","sentenceOrder":338},
  {"id":"s_work_han_thu_1_339","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　應劭曰：「恐敵鈔輜重，故築垣牆如街巷也。」鄭氏曰：「甬音踊。」師古曰：「屬，聯也，音之欲反。」","sentenceOrder":339},
  {"id":"s_work_han_thu_1_340","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　孟康曰：「敖，地名，在滎陽西北，山上臨河有大倉。」","sentenceOrder":340},
  {"id":"s_work_han_thu_1_341","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　師古曰：「謁，請也。親謂母也。」","sentenceOrder":341},
  {"id":"s_work_han_thu_1_342","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　師古曰：「斷其津濟以距漢軍。為音于偽反。」","sentenceOrder":342},
  {"id":"s_work_han_thu_1_343","chapterId":"ch_work_han_thu_1","textTraditional":"六月，漢王還櫟陽。壬午，立太子，赦罪人。令諸侯子在關中者皆集櫟陽為衛。引水灌廢丘，廢丘降，章邯自殺。雍（州）〔地〕定，八十餘縣，置河上、渭南、中地、隴西、上郡。〔一〕令祠官祀天地四方上帝山川，以時祠之。興關中卒乘邊塞。〔二〕關中大飢，米斛萬錢，〔三〕人相食。令民就食蜀漢。","sentenceOrder":343},
  {"id":"s_work_han_thu_1_344","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　服虔曰：「河上，即左馮翊也。渭南，京兆也。中地，右扶風也。」師古曰：「凡新置五郡。」","sentenceOrder":344},
  {"id":"s_work_han_thu_1_345","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　李奇曰：「乘，守也。」師古曰：「乘，登也。登而守之，義與上乘城同。」","sentenceOrder":345},
  {"id":"s_work_han_thu_1_346","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「一斛直萬錢。」","sentenceOrder":346},
  {"id":"s_work_han_thu_1_347","chapterId":"ch_work_han_thu_1","textTraditional":"秋八月，漢王如滎陽，謂酈食其曰：「緩頰往說魏王豹，〔一〕能下之，以魏地萬戶封生。」〔二〕食其往，豹不聽。漢王以韓信為左丞相，與曹參、灌嬰俱擊魏。食其還，漢王問：「魏大將誰也？」對曰：「柏直。」王曰：「是口尚乳臭，不能當韓信。〔三〕騎將誰也？」曰：「馮敬。」曰：「是秦將馮無擇子也，雖賢，不能當灌嬰。步卒將誰也？」曰：「項它。」〔四〕曰：「是不能當曹參。吾無患矣。」九月，信等虜豹，傳詣滎陽。定魏地，置河東、太原、上黨郡。信使人請兵三萬人，願以北舉燕趙，東擊齊，南絕楚糧道。漢王與之。","sentenceOrder":347},
  {"id":"s_work_han_thu_1_348","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　張晏曰：「緩頰，徐言引譬喻也。」","sentenceOrder":348},
  {"id":"s_work_han_thu_1_349","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「生猶言先生。他皆類此。」","sentenceOrder":349},
  {"id":"s_work_han_thu_1_350","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「乳臭，言其幼少。」","sentenceOrder":350},
  {"id":"s_work_han_thu_1_351","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「它字與他同，並音徒何反。」","sentenceOrder":351},
  {"id":"s_work_han_thu_1_352","chapterId":"ch_work_han_thu_1","textTraditional":"三年冬十月，韓信、張耳東下井陘擊趙，〔一〕斬陳餘，獲趙王歇。置常山、代郡。甲戌晦，日有食之。十一月癸卯晦，日有食之。","sentenceOrder":352},
  {"id":"s_work_han_thu_1_353","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　服虔曰：「井陘，山名，在常山，今為縣。」師古曰：「陘音形。」","sentenceOrder":353},
  {"id":"s_work_han_thu_1_354","chapterId":"ch_work_han_thu_1","textTraditional":"隨何既說黥布，布起兵攻楚。楚使項聲、龍且攻布，〔一〕布戰不勝。十二月，布與隨何間行歸漢。漢王分之兵，與俱收兵至成皋。","sentenceOrder":354},
  {"id":"s_work_han_thu_1_355","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　韋昭曰：「且音子閭反。」","sentenceOrder":355},
  {"id":"s_work_han_thu_1_356","chapterId":"ch_work_han_thu_1","textTraditional":"項羽數侵奪漢甬道，漢軍乏食，與酈食其謀橈楚權。〔一〕食其欲立六國後以樹黨，〔二〕漢王刻印，將遣食其立之。以問張良，良發八難。漢王輟飯吐哺，〔三〕曰：「豎儒〔四〕幾敗乃公事！〔五〕」令趨銷印。〔六〕又問陳平，乃從其計，與平黃金四萬斤，以間疏楚君臣。〔七〕","sentenceOrder":356},
  {"id":"s_work_han_thu_1_357","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　服虔曰：「橈，弱也。」師古曰：「音女教（而）〔反〕，其字從木。」","sentenceOrder":357},
  {"id":"s_work_han_thu_1_358","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「樹，立也。」","sentenceOrder":358},
  {"id":"s_work_han_thu_1_359","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「輟，止也。哺，口中所含食也。飯音扶晚反。哺音步。」","sentenceOrder":359},
  {"id":"s_work_han_thu_1_360","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「言其賤劣無智，若童豎也。」","sentenceOrder":360},
  {"id":"s_work_han_thu_1_361","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　師古曰：「幾，近也。乃，汝也。公，漢王自謂也。幾音鉅依反。」","sentenceOrder":361},
  {"id":"s_work_han_thu_1_362","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　師古曰：「趨讀曰促。促，速也。他皆類此。」","sentenceOrder":362},
  {"id":"s_work_han_thu_1_363","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　師古曰：「間音居莧反。次下反間，其音亦同。」","sentenceOrder":363},
  {"id":"s_work_han_thu_1_364","chapterId":"ch_work_han_thu_1","textTraditional":"夏四月，項羽圍漢滎陽，漢王請和，割滎陽以西者為漢。亞父勸項羽急攻滎陽，漢王患之。陳平反間既行，羽果疑亞父。亞父大怒而去，發病死。","sentenceOrder":364},
  {"id":"s_work_han_thu_1_365","chapterId":"ch_work_han_thu_1","textTraditional":"五月，將軍紀信曰：「事急矣！臣請誑楚，可以間出。」於是陳平夜出女子東門二千餘人，楚因四面擊之。紀信乃乘王車，黃屋左纛，〔二〕曰：「食盡，漢王降楚。」楚皆呼萬歲，之城東觀，以故漢王得與數十騎出西門遁。令御史大夫周苛、魏豹、樅公守滎陽。〔三〕羽見紀信，問：「漢王安在？」曰：「已出去矣。」羽燒殺信。而周苛、樅公相謂曰：「反國之王，難與守城。」〔四〕因殺魏豹。","sentenceOrder":365},
  {"id":"s_work_han_thu_1_366","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　師古曰：「間出，投間隙私出，若言間行微行耳。紀信詐為漢王，而王出西門遁，是私出也。」","sentenceOrder":366},
  {"id":"s_work_han_thu_1_367","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　李斐曰：「天子車以黃繒為蓋裏。纛，毛羽幢也，在乘輿車衡左方上注之。蔡邕曰以犛牛尾為之，如斗，或在騑頭，或在衡。」應劭曰：「雉尾為之，在左驂，當鑣上。」師古曰：「纛音毒，又徒到反。應說非也。」","sentenceOrder":367},
  {"id":"s_work_han_thu_1_368","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　應劭曰：「樅公者，不知其名，故曰公。」蘇林曰：「音樅木之樅。」師古曰：「音千容反。」","sentenceOrder":368},
  {"id":"s_work_han_thu_1_369","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「謂豹先已經畔漢。」","sentenceOrder":369},
  {"id":"s_work_han_thu_1_370","chapterId":"ch_work_han_thu_1","textTraditional":"漢王出滎陽，至成皋。自成皋入關，收兵欲復東。轅生說漢王〔一〕曰：「漢與楚相距滎陽數歲，漢常困。願君王出武關，項王必引兵南走，〔二〕王深壁，令滎陽成皋間且得休息。使韓信等得輯河北趙地，〔三〕連燕齊，君王乃復走滎陽。如此，則楚所備者多，力分。漢得休息，復與之戰，破之必矣。」漢王從其計，出軍宛葉間〔四〕，與黥布行收兵。","sentenceOrder":370},
  {"id":"s_work_han_thu_1_371","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　文穎曰：「轅姓，生謂諸生。」","sentenceOrder":371},
  {"id":"s_work_han_thu_1_372","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「走亦謂趨，嚮也，音奏。次後亦同。」","sentenceOrder":372},
  {"id":"s_work_han_thu_1_373","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「輯與集同，謂和合也。詩序曰『勞來還定安集之』。春秋左氏傳曰『群臣輯睦』。他皆類此。」","sentenceOrder":373},
  {"id":"s_work_han_thu_1_374","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「葉，縣名，古葉公之國，音式涉反。宛縣葉縣之間也。」","sentenceOrder":374},
  {"id":"s_work_han_thu_1_375","chapterId":"ch_work_han_thu_1","textTraditional":"羽聞漢王在宛，果引兵南，漢王堅壁不與戰。是月，彭越渡睢，〔一〕與項聲、薛公戰下邳，破殺薛公。羽使終公守成皋，而自東擊彭越。漢王引兵北，擊破終公，復軍成皋。六月，羽已破走彭越〔二〕，聞漢復軍成皋，乃引兵西拔滎陽城，生得周苛。羽謂苛：「為我將，以公為上將軍，封三萬戶。」周苛罵曰：「若不趨降漢，今為虜矣！〔三〕若非漢王敵也。」羽亨周苛，〔四〕并殺樅公，而虜韓王信，遂圍成皋。漢王跳，〔五〕獨與滕公共車出成皋玉門，〔六〕北渡河，宿小脩武。〔七〕自稱使者，晨馳入張耳、韓信壁，而奪之軍。乃使張耳北收兵趙地。","sentenceOrder":375},
  {"id":"s_work_han_thu_1_376","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　師古曰：「過睢水也。睢音雖。」","sentenceOrder":376},
  {"id":"s_work_han_thu_1_377","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「破之而令遁走。」","sentenceOrder":377},
  {"id":"s_work_han_thu_1_378","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「若，汝也。趨讀曰促。」","sentenceOrder":378},
  {"id":"s_work_han_thu_1_379","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「亨謂煮而殺之，音普庚反。他皆類此。」","sentenceOrder":379},
  {"id":"s_work_han_thu_1_380","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　如淳曰：「跳音逃，謂走也。史記作逃。」晉灼曰：「跳，獨出意也。」師古曰：「晉說是也，音徒彫反。」","sentenceOrder":380},
  {"id":"s_work_han_thu_1_381","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　張晏曰：「成皋北門。」","sentenceOrder":381},
  {"id":"s_work_han_thu_1_382","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　晉灼曰：「在大脩武城東。」","sentenceOrder":382},
  {"id":"s_work_han_thu_1_383","chapterId":"ch_work_han_thu_1","textTraditional":"秋七月，有星孛于大角。〔一〕漢王得韓信軍，復大振。八月，臨河南鄉，〔二〕軍小脩武，欲復戰。郎中鄭忠說止漢王，高壘深塹勿戰。漢王聽其計，使盧綰、劉賈將卒二萬人，騎數百，〔三〕渡白馬津入楚地，佐彭越燒楚積聚，〔四〕復擊破楚軍燕郭西，〔五〕攻下睢陽、外黃十七城。九月，羽謂海春侯大司馬曹咎曰：「謹守成皋。即漢王欲挑戰，慎勿與戰，〔六〕勿令得東而已。我十五日必定梁地，復從將軍。」〔七〕羽引兵東擊彭越。","sentenceOrder":383},
  {"id":"s_work_han_thu_1_384","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　李奇曰：「孛，彗類也，是謂妖星，所以除舊布新也。」師古曰：「孛音步內反。」","sentenceOrder":384},
  {"id":"s_work_han_thu_1_385","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":385},
  {"id":"s_work_han_thu_1_386","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　蘇林曰：「綰音以繩綰結物之綰。」師古曰：「音烏板反。」","sentenceOrder":386},
  {"id":"s_work_han_thu_1_387","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「所畜軍糧芻稿之屬也。積音子賜反。聚音才喻反。」","sentenceOrder":387},
  {"id":"s_work_han_thu_1_388","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　師古曰：「燕，縣名，古南燕國。」","sentenceOrder":388},
  {"id":"s_work_han_thu_1_389","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　李奇曰：「挑音徒了反。」臣瓚曰：「挑戰，擿嬈敵求戰也，古謂之致師。」師古曰：「李音瓚說是。擿音他歷反。嬈音乃了反。」","sentenceOrder":389},
  {"id":"s_work_han_thu_1_390","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　師古曰：「從，就也。」","sentenceOrder":390},
  {"id":"s_work_han_thu_1_391","chapterId":"ch_work_han_thu_1","textTraditional":"漢王使酈食其說齊王田廣，罷守兵與漢和。","sentenceOrder":391},
  {"id":"s_work_han_thu_1_392","chapterId":"ch_work_han_thu_1","textTraditional":"四年冬十月，韓信用蒯通計，襲破齊。齊王亨酈生，東走高密。項羽聞韓信破齊，且欲擊楚，使龍且救齊。","sentenceOrder":392},
  {"id":"s_work_han_thu_1_393","chapterId":"ch_work_han_thu_1","textTraditional":"漢果數挑成皋戰，楚軍不出，使人辱之數日，大司馬咎怒，渡兵汜水。〔一〕士卒半渡，漢擊之，大破楚軍，盡得楚國金玉貨賂。大司馬咎、長史欣皆自剄汜水上。漢王引兵渡河，復取成皋，軍廣武，〔二〕就敖倉食。","sentenceOrder":393},
  {"id":"s_work_han_thu_1_394","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　張晏曰：「汜水在濟陰界。」如淳曰：「汜音祀。左傳曰『鄙在鄭地汜』。」臣瓚曰：「高祖攻曹咎於成皋，咎渡汜水而戰，今成皋城東汜水是也。」師古曰：「瓚說得之，此水不在濟陰也。『鄙在鄭地汜』，釋者又云在襄城，則非此也。此水舊讀音凡，今彼鄉人呼之音祀。」","sentenceOrder":394},
  {"id":"s_work_han_thu_1_395","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　孟康曰：「於滎陽築兩城而相對，名為廣武城，在敖倉西三室山上。」","sentenceOrder":395},
  {"id":"s_work_han_thu_1_396","chapterId":"ch_work_han_thu_1","textTraditional":"羽下梁地十餘城，聞海春侯破，乃引兵還。漢軍方圍鍾離眜於滎陽東，〔一〕聞羽至，盡走險阻。〔二〕羽亦軍廣武，與漢相守。丁壯苦軍旅，老弱罷轉餉。〔三〕漢王、羽相與臨廣武之間而語。羽欲與漢王獨身挑戰，漢王數羽曰：〔四〕「吾始與羽俱受命懷王，曰先定關中者王之。羽負約，王我於蜀漢，罪一也。羽矯殺卿子冠軍，自尊，罪二也。〔五〕羽當以救趙還報，〔六〕而擅劫諸侯兵入關，罪三也。懷王約入秦無暴掠，羽燒秦宮室，掘始皇帝冢，收私其財，罪四也。〔七〕又彊殺秦降王子嬰，罪五也。詐阬秦子弟新安二十萬，王其將，〔八〕罪六也。皆王諸將善地，而徙逐故主，令臣下爭畔逆，罪七也。出逐義帝彭城，自都之，奪韓王地，并王梁楚，多自與，罪八也。使人陰殺義帝江南，罪九也。夫為人臣而殺其主，殺其已降，為政不平，主約不信，天下所不容，大逆無道，罪十也。吾以義兵從諸侯誅殘賊，使刑餘罪人擊公，〔九〕何苦乃與公挑戰！」羽大怒，伏弩射中漢王。漢王傷胸，乃捫足曰：「虜中吾指！」〔一０〕漢王病創臥，張良彊請漢王起行勞軍，以安士卒，〔一一〕毋令楚乘勝。漢王出行軍，疾甚，因馳入成皋。","sentenceOrder":396},
  {"id":"s_work_han_thu_1_397","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　師古曰：「眜音莫葛反。其字從本末之末。」","sentenceOrder":397},
  {"id":"s_work_han_thu_1_398","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「走音奏。」","sentenceOrder":398},
  {"id":"s_work_han_thu_1_399","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　師古曰：「罷讀曰疲。轉，運；餉，饋也，音式向反。」","sentenceOrder":399},
  {"id":"s_work_han_thu_1_400","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「數，責其罪也，音所具反。」","sentenceOrder":400},
  {"id":"s_work_han_thu_1_401","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　如淳曰：「卿者，卿大夫之號。子者，子男之爵。冠軍，人之首也。」文穎曰：「卿子，時人相褒尊之辭，猶言公子也。時上將，故言冠軍。」師古曰：「矯，託也，託懷王命而殺之也。卿子冠軍，文說是也。」","sentenceOrder":401},
  {"id":"s_work_han_thu_1_402","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　李奇曰：「前受命於懷王往救趙，當還反報。」","sentenceOrder":402},
  {"id":"s_work_han_thu_1_403","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　師古曰：「掘而發之，收取其財以私自有也。掘音其勿反。」","sentenceOrder":403},
  {"id":"s_work_han_thu_1_404","chapterId":"ch_work_han_thu_1","textTraditional":"〔八〕　李奇曰：「章邯等為王。」","sentenceOrder":404},
  {"id":"s_work_han_thu_1_405","chapterId":"ch_work_han_thu_1","textTraditional":"〔九〕　師古曰：「言輕賤也。」","sentenceOrder":405},
  {"id":"s_work_han_thu_1_406","chapterId":"ch_work_han_thu_1","textTraditional":"〔一０〕師古曰：「捫，摸也。傷胸而捫足者，以安眾也。捫音門。中音竹仲反。」","sentenceOrder":406},
  {"id":"s_work_han_thu_1_407","chapterId":"ch_work_han_thu_1","textTraditional":"〔一一〕師古曰：「行音下更反。其下亦同。」","sentenceOrder":407},
  {"id":"s_work_han_thu_1_408","chapterId":"ch_work_han_thu_1","textTraditional":"十一月，韓信與灌嬰擊破楚軍，殺楚將龍且，追至城陽，虜齊王廣。齊相田橫自立為齊王，奔彭越。漢立張耳為趙王。","sentenceOrder":408},
  {"id":"s_work_han_thu_1_409","chapterId":"ch_work_han_thu_1","textTraditional":"漢王疾瘉，〔一〕西入關，至櫟陽，存問父老，置酒。梟故塞王欣頭櫟陽市。〔二〕留四日，復如軍，軍廣武。關中兵益出，而彭越、田橫居梁地，往來苦楚兵，絕其糧食。","sentenceOrder":409},
  {"id":"s_work_han_thu_1_410","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　師古曰：「瘉與愈同。愈，差也。」","sentenceOrder":410},
  {"id":"s_work_han_thu_1_411","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「梟，縣首於木上。」","sentenceOrder":411},
  {"id":"s_work_han_thu_1_412","chapterId":"ch_work_han_thu_1","textTraditional":"韓信已破齊，使人言曰：「齊邊楚，〔一〕權輕，不為假王，恐不能安齊。」漢王怒，欲攻之。張良曰：「不如因而立之，使自為守。」春二月，遣張良操印，立韓信為齊王。〔二〕秋七月，立黥布為淮南王。八月，初為算賦。〔三〕北貉、燕人來致梟騎助漢。〔四〕漢王下令：〔五〕軍士不幸死者，吏為衣衾棺斂，〔六〕轉送其家。〔七〕四方歸心焉。〔八〕","sentenceOrder":412},
  {"id":"s_work_han_thu_1_413","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　師古曰：「邊，共為邊界。」","sentenceOrder":413},
  {"id":"s_work_han_thu_1_414","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「操，持也，音千高反。」","sentenceOrder":414},
  {"id":"s_work_han_thu_1_415","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　如淳曰：「漢儀注民年十五以上至五十六出賦錢，人百二十為一算，為治庫兵車馬。」","sentenceOrder":415},
  {"id":"s_work_han_thu_1_416","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　應劭曰：「北貉，國也。梟，健也。」張晏曰：「梟，勇也，若六博之梟也。」師古曰：「貉在東北方，三韓之屬皆貉類也，音莫客反。」","sentenceOrder":416},
  {"id":"s_work_han_thu_1_417","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　師古曰：「令，教命也。下音胡嫁反。他皆類此。」","sentenceOrder":417},
  {"id":"s_work_han_thu_1_418","chapterId":"ch_work_han_thu_1","textTraditional":"〔六〕　師古曰：「棺音工喚反。斂音力贍反。與作衣衾而斂尸於棺。」","sentenceOrder":418},
  {"id":"s_work_han_thu_1_419","chapterId":"ch_work_han_thu_1","textTraditional":"〔七〕　師古曰：「轉，傳送也。」","sentenceOrder":419},
  {"id":"s_work_han_thu_1_420","chapterId":"ch_work_han_thu_1","textTraditional":"〔八〕　師古曰：「以仁愛故。」","sentenceOrder":420},
  {"id":"s_work_han_thu_1_421","chapterId":"ch_work_han_thu_1","textTraditional":"項羽自知少助食盡，韓信又進兵擊楚，羽患之。漢遣陸賈說羽，請太公，羽弗聽。漢復使侯公說羽，羽乃與漢約，中分天下，割鴻溝以西為漢，〔一〕以東為楚。九月，歸太公、呂后，軍皆稱萬歲。乃封侯公為平國君。〔二〕羽解而東歸。漢王欲西歸，張良、陳平諫曰：「今漢有天下太半，〔三〕而諸侯皆附，楚兵罷食盡，〔四〕此天亡之時，不因其幾而遂取之，〔五〕所謂養虎自遺患也。」漢王從之。","sentenceOrder":421},
  {"id":"s_work_han_thu_1_422","chapterId":"ch_work_han_thu_1","textTraditional":"〔一〕　應劭曰：「在滎陽東南二十里。」文穎曰：「於滎陽下引河東南為鴻溝，以通宋、鄭、陳、蔡、曹、衛，與濟、汝、淮、泗會於楚，即今官渡水也。」","sentenceOrder":422},
  {"id":"s_work_han_thu_1_423","chapterId":"ch_work_han_thu_1","textTraditional":"〔二〕　師古曰：「以其善說，能平和邦國。」","sentenceOrder":423},
  {"id":"s_work_han_thu_1_424","chapterId":"ch_work_han_thu_1","textTraditional":"〔三〕　韋昭曰：「凡數三分有二為（大）〔太〕半，有一分為少半。」","sentenceOrder":424},
  {"id":"s_work_han_thu_1_425","chapterId":"ch_work_han_thu_1","textTraditional":"〔四〕　師古曰：「罷讀曰疲。」","sentenceOrder":425},
  {"id":"s_work_han_thu_1_426","chapterId":"ch_work_han_thu_1","textTraditional":"〔五〕　鄭氏曰：「幾，微也。」師古曰：「幾，危也。」","sentenceOrder":426},
  {"id":"s_work_han_thu_1_427","chapterId":"ch_work_han_thu_1","textTraditional":"校勘記","sentenceOrder":427},
  {"id":"s_work_han_thu_1_428","chapterId":"ch_work_han_thu_1","textTraditional":"二頁一二行　眉目準（頰）〔頞〕權衡，　景祐、汲古、殿、局本都作「頞」，王先謙說作「頞」是。","sentenceOrder":428},
  {"id":"s_work_han_thu_1_429","chapterId":"ch_work_han_thu_1","textTraditional":"四頁一四行　音弋豉（也）〔反〕。　景祐、殿、局本都作「反」。王先謙說作「反」是。","sentenceOrder":429},
  {"id":"s_work_han_thu_1_430","chapterId":"ch_work_han_thu_1","textTraditional":"一０頁　一行　（令）〔今〕置將不善，　景祐、殿本都作「今」。王先謙說作「今」是。","sentenceOrder":430},
  {"id":"s_work_han_thu_1_431","chapterId":"ch_work_han_thu_1","textTraditional":"一０頁　二行　願（吏）〔更〕擇可者。　景祐、殿本都作「更」。王先謙說作「更」是。","sentenceOrder":431},
  {"id":"s_work_han_thu_1_432","chapterId":"ch_work_han_thu_1","textTraditional":"一０頁　二行　蕭、曹（等）皆文吏，　景祐本無「等」字。楊樹達說無「等」字是。","sentenceOrder":432},
  {"id":"s_work_han_thu_1_433","chapterId":"ch_work_han_thu_1","textTraditional":"一０頁　四行　祭蚩尤於沛廷，而釁鼓旗。〔一四〕幟皆赤，注〔一四〕原在「鼓」字下，明顏讀「釁鼓」句絕。吳仁傑據封禪書「祠蚩尤，釁鼓旗」之文，以為「旗」字當屬上句。王先謙、楊樹達都說吳讀是。","sentenceOrder":433},
  {"id":"s_work_han_thu_1_434","chapterId":"ch_work_han_thu_1","textTraditional":"一０頁　五行　（所）殺者赤帝子故也。　王念孫說下「所」字涉上「所」字而衍。","sentenceOrder":434},
  {"id":"s_work_han_thu_1_435","chapterId":"ch_work_han_thu_1","textTraditional":"一七頁　二行　至（陽城）〔城陽〕　齊召南據史記及曹參傳改。王先謙說齊說是。","sentenceOrder":435},
  {"id":"s_work_han_thu_1_436","chapterId":"ch_work_han_thu_1","textTraditional":"一九頁一一行　（大）破之。　景祐本無「大」字，史說亦無。王念孫說係後人所加。","sentenceOrder":436},
  {"id":"s_work_han_thu_1_437","chapterId":"ch_work_han_thu_1","textTraditional":"二０頁一三行　遲，未（明）也。　景祐、殿本都無「明」字。王先謙說無「明」字是。","sentenceOrder":437},
  {"id":"s_work_han_thu_1_438","chapterId":"ch_work_han_thu_1","textTraditional":"二三頁　七行　張（倉）〔蒼〕傳云　殿本作「蒼」。王先謙說作「蒼」是。","sentenceOrder":438},
  {"id":"s_work_han_thu_1_439","chapterId":"ch_work_han_thu_1","textTraditional":"二六頁　三行　籍何以（生）〔至〕此？　錢大昭說明南監、閩本都作「至」。　王念孫據史記項羽紀、高祖紀及通鑑漢紀，以為「生」當為「至」字之誤。","sentenceOrder":439},
  {"id":"s_work_han_thu_1_440","chapterId":"ch_work_han_thu_1","textTraditional":"三０頁一二行　給軍〔糧〕食。　景祐、殿本及通鑑都有「糧」字。","sentenceOrder":440},
  {"id":"s_work_han_thu_1_441","chapterId":"ch_work_han_thu_1","textTraditional":"三六頁　九行　（二）〔三〕月，　景祐、汲古、殿、局本都作「三」。王先謙說作「三」是。","sentenceOrder":441},
  {"id":"s_work_han_thu_1_442","chapterId":"ch_work_han_thu_1","textTraditional":"三八頁　九行　雍（州）〔地〕　王先謙說「州」字誤，當為「地」。按通鑑亦作「地」。","sentenceOrder":442},
  {"id":"s_work_han_thu_1_443","chapterId":"ch_work_han_thu_1","textTraditional":"四０頁　三行　音女教（而）〔反〕，　景祐、殿本都作「反」。王先謙說作「反」是。","sentenceOrder":443},
  {"id":"s_work_han_thu_1_444","chapterId":"ch_work_han_thu_1","textTraditional":"四七頁　七行　為（大）〔太〕半，　景祐、汲古、殿、局本都作「太」。","sentenceOrder":444},
  {"id":"s_work_han_thu_2_1","chapterId":"ch_work_han_thu_2","textTraditional":"五年冬十月，漢王追項羽至陽夏南〔一〕止軍，與齊王信、魏相國越期會擊楚，至固陵，〔二〕不會。楚擊漢軍，大破之。漢王復入壁，深塹而守。謂張良曰：「諸侯不從，柰何？」良對曰：「楚兵且破，未有分地，〔三〕其不至固宜。〔四〕君王能與共天下，可立致也。〔五〕齊王信之立，非君王意，信亦不自堅。〔六〕彭越本定梁地，始君王以魏豹故，拜越為相國。今豹死，越亦望王，而君王不早定。今能取睢陽以北至穀城皆以王彭越，〔七〕從陳以東傅海與齊王信，〔八〕信家在楚，其意欲復得故邑。能出捐此地以許兩人，〔九〕使各自為戰，則楚易敗也。」於是漢王發使使韓信、彭越。至，皆引兵來。","sentenceOrder":1},
  {"id":"s_work_han_thu_2_2","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「夏音工雅反，已解於上。」","sentenceOrder":2},
  {"id":"s_work_han_thu_2_3","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　晉灼曰：「即固始也。」師古曰：「後改為固始耳。地理志固始屬淮陽。」","sentenceOrder":3},
  {"id":"s_work_han_thu_2_4","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　李奇曰：「信、越等未有益地之分。」師古曰：「分音扶問反。」","sentenceOrder":4},
  {"id":"s_work_han_thu_2_5","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　師古曰：「理宜然也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_2_6","chapterId":"ch_work_han_thu_2","textTraditional":"〔五〕　師古曰：「共有天下之地，割而封之。」","sentenceOrder":6},
  {"id":"s_work_han_thu_2_7","chapterId":"ch_work_han_thu_2","textTraditional":"〔六〕　師古曰：「因信自請為假王，乃立之耳，故曰非君王意。」","sentenceOrder":7},
  {"id":"s_work_han_thu_2_8","chapterId":"ch_work_han_thu_2","textTraditional":"〔七〕　師古曰：「睢音雖。」","sentenceOrder":8},
  {"id":"s_work_han_thu_2_9","chapterId":"ch_work_han_thu_2","textTraditional":"〔八〕　師古曰：「傅讀曰附。」","sentenceOrder":9},
  {"id":"s_work_han_thu_2_10","chapterId":"ch_work_han_thu_2","textTraditional":"〔九〕　師古曰：「捐，棄也，音弋全反。」","sentenceOrder":10},
  {"id":"s_work_han_thu_2_11","chapterId":"ch_work_han_thu_2","textTraditional":"十一月，劉賈入楚地，圍壽春。漢亦遣人誘楚大司馬周殷。殷畔楚，以舒屠六，〔一〕舉九江兵迎黥布，並行屠城父，〔二〕隨劉賈皆會。","sentenceOrder":11},
  {"id":"s_work_han_thu_2_12","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　如淳曰：「以舒之眾屠破六縣。」師古曰：「六者，縣名，即上所謂九江王都六者也，後屬廬江郡。」","sentenceOrder":12},
  {"id":"s_work_han_thu_2_13","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　如淳曰：「並行，並擊也。」師古曰：「城父，縣名。父音甫。」","sentenceOrder":13},
  {"id":"s_work_han_thu_2_14","chapterId":"ch_work_han_thu_2","textTraditional":"十二月，圍羽垓下。〔一〕羽夜聞漢軍四面皆楚歌，〔二〕知盡得楚地，羽與數百騎走，是以兵大敗。灌嬰追斬羽東城。〔三〕楚地悉定，獨魯不下。漢王引天下兵欲屠之，為其守節禮義之國，乃持羽頭示其父兄，魯乃降。初，懷王封羽為魯公，及死，魯又為之堅守，故以魯公葬羽於穀城。〔四〕漢王為發（葬）〔喪〕，哭臨而去〔五〕。封項伯等四人為列侯，賜姓劉氏。〔六〕諸民略在楚者皆歸之。漢王還至定陶，馳入齊王信壁，奪其軍。初項羽所立臨江王共敖前死，子尉嗣立為王，不降。遣盧綰、劉賈擊虜尉。","sentenceOrder":14},
  {"id":"s_work_han_thu_2_15","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　應劭曰：「垓音該。」李奇曰：「沛洨縣聚邑名也。」師古曰：「洨音衡交反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_2_16","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　應劭曰：「楚歌者，雞鳴歌也。漢已略得其地，故楚歌者多雞鳴時歌也。」師古曰：「楚歌者，為楚人之歌，猶言吳歈越吟耳。若以雞鳴為歌曲之名，於理則可，不得云雞鳴時也。高祖令戚夫人楚舞，自為作楚歌，豈亦雞鳴時乎？」","sentenceOrder":16},
  {"id":"s_work_han_thu_2_17","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　晉灼曰：「九江縣。」","sentenceOrder":17},
  {"id":"s_work_han_thu_2_18","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　師古曰：「即濟北穀城。」","sentenceOrder":18},
  {"id":"s_work_han_thu_2_19","chapterId":"ch_work_han_thu_2","textTraditional":"〔五〕　師古曰：「臨音力禁反。」","sentenceOrder":19},
  {"id":"s_work_han_thu_2_20","chapterId":"ch_work_han_thu_2","textTraditional":"〔六〕　師古曰：「皆羽之族，先有功於漢者。」","sentenceOrder":20},
  {"id":"s_work_han_thu_2_21","chapterId":"ch_work_han_thu_2","textTraditional":"春正月，追尊兄伯號曰武哀侯。〔一〕下令曰：「楚地已定，義帝亡後，欲存恤楚眾，以定其主。齊王信習楚風俗，更立為楚王〔二〕，王淮北，都下邳。魏相國建城侯彭越勤勞魏民，卑下士卒，〔三〕常以少擊眾，數破楚軍，其以魏故地王之，號曰梁王，都定陶。」又曰：「兵不得休八年，萬民與苦甚，〔四〕今天下事畢，其赦天下殊死以下。」〔五〕","sentenceOrder":21},
  {"id":"s_work_han_thu_2_22","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　應劭曰：「兄伯早亡，追諡之。」","sentenceOrder":22},
  {"id":"s_work_han_thu_2_23","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「更，改也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_2_24","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　師古曰：「言安輯魏地，保其人眾也。下音胡稼反。」","sentenceOrder":24},
  {"id":"s_work_han_thu_2_25","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　如淳曰：「與音相干與之與。」師古曰：「音弋庶反。」","sentenceOrder":25},
  {"id":"s_work_han_thu_2_26","chapterId":"ch_work_han_thu_2","textTraditional":"〔五〕　如淳曰：「死罪之明白也。左傳曰斬其木而弗殊。」韋昭曰：「殊死，斬刑也。」師古曰：「殊，絕也，異也，言其身首離絕而異處也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_2_27","chapterId":"ch_work_han_thu_2","textTraditional":"於是諸侯上疏曰：「楚王韓信、韓王信、淮南王英布、梁王彭越、故衡山王吳芮、〔一〕趙王張敖、燕王臧荼昧死再拜言，〔二〕大王陛下：〔三〕先時秦為亡道，天下誅之。大王先得秦王，定關中，於天下功最多。存亡定危，救敗繼絕，以安萬民，功盛德厚。又加惠於諸侯王有功者，使得立社稷。地分已定，而位號比儗，亡上下之分，〔四〕大王功德之著，於後世不宣。〔五〕昧死再拜上皇帝尊號。」漢王曰：「寡人聞帝者賢者有也，〔六〕虛言亡實之名，非所取也。今諸侯王皆推高寡人，將何以處之哉？」諸侯王皆曰：「大王起於細微，滅亂秦，威動海內。又以辟陋之地，〔七〕自漢中行威德，誅不義，立有功，平定海內，功臣皆受地食邑，非私之也。大王德施四海，諸侯王不足以道之，居帝位甚實宜，願大王以幸天下。」〔八〕漢王曰：「諸侯王幸以為便於天下之民，則可矣。」於是諸侯王及太尉長安侯臣綰等三百人，〔九〕與博士稷嗣君叔孫通〔一０〕謹擇良日二月甲午，上尊號。漢王即皇帝位于氾水之陽。〔一一〕尊王后曰皇后，太子曰皇太子，追尊先媼曰昭靈夫人。","sentenceOrder":27},
  {"id":"s_work_han_thu_2_28","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　張晏曰：「漢元年，項羽立芮為衡山王，後又奪之地，謂之番君，是以曰故。」","sentenceOrder":28},
  {"id":"s_work_han_thu_2_29","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　張晏曰：「秦以為人臣上書當言昧犯死罪而言，漢遂遵之。」","sentenceOrder":29},
  {"id":"s_work_han_thu_2_30","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　應劭曰：「陛者，升堂之陛。王者必有執兵陳於階陛之側，群臣與至尊言，不敢指斥，故呼在陛下者而告之，因卑以達尊之意也。若今稱殿下、閣下、侍者、執事，皆此類也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_2_31","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　師古曰：「言大王與臣等並稱王，是為比類相儗，無尊卑之差別也。地分音扶問反。」","sentenceOrder":31},
  {"id":"s_work_han_thu_2_32","chapterId":"ch_work_han_thu_2","textTraditional":"〔五〕　師古曰：「言位號不殊，則功德之著明者，不宣於後世也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_2_33","chapterId":"ch_work_han_thu_2","textTraditional":"〔六〕　師古曰：「言賢德之人乃可有帝號。」","sentenceOrder":33},
  {"id":"s_work_han_thu_2_34","chapterId":"ch_work_han_thu_2","textTraditional":"〔七〕　師古曰：「辟讀曰僻。」","sentenceOrder":34},
  {"id":"s_work_han_thu_2_35","chapterId":"ch_work_han_thu_2","textTraditional":"〔八〕　晉灼曰：「漢儀注民臣被其德以為僥倖也。」師古曰：「倖者，吉而免凶，可慶幸也，故福喜之事皆稱為幸，而死謂之不幸。」","sentenceOrder":35},
  {"id":"s_work_han_thu_2_36","chapterId":"ch_work_han_thu_2","textTraditional":"〔九〕　師古曰：「綰，盧綰也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_2_37","chapterId":"ch_work_han_thu_2","textTraditional":"〔一０〕孟康曰：「稷嗣，邑名。」","sentenceOrder":37},
  {"id":"s_work_han_thu_2_38","chapterId":"ch_work_han_thu_2","textTraditional":"〔一一〕張晏曰：「在濟陰界，取其氾愛弘大而潤下也。」師古曰：「據叔孫通傳曰為皇帝於定陶，則此水在濟陰是也。音敷劍反。」","sentenceOrder":38},
  {"id":"s_work_han_thu_2_39","chapterId":"ch_work_han_thu_2","textTraditional":"詔曰：〔一〕「故衡山王吳芮與子二人、兄子一人，從百粵之兵，〔二〕以佐諸侯，誅暴秦，有大功，諸侯立以為王。項羽侵奪之地，謂之番君。〔三〕其以長沙、豫章、象郡、桂林、南海立番君芮為長沙王。」〔四〕又曰：「故粵王亡諸世奉粵祀，秦侵奪其地，使其社稷不得血食。〔五〕諸侯伐秦，亡諸身帥閩中兵以佐滅秦，〔六〕項羽廢而弗立。今以為閩粵王，王閩中地，勿使失職。」","sentenceOrder":39},
  {"id":"s_work_han_thu_2_40","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　如淳曰：「詔，告也。自秦漢以下，唯天子獨稱之。」","sentenceOrder":40},
  {"id":"s_work_han_thu_2_41","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　服虔曰：「非一種，若今言百蠻也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_2_42","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　師古曰：「番音蒲何反。」","sentenceOrder":42},
  {"id":"s_work_han_thu_2_43","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　臣瓚曰：「茂陵書象郡治臨塵，去長安萬七千五百里。」文穎曰：「桂林，今鬱林也。」師古曰：「桂林，今之桂州境界左右皆是其地，非鬱林也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_2_44","chapterId":"ch_work_han_thu_2","textTraditional":"〔五〕　師古曰：「祭者尚血腥，故曰血食也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_2_45","chapterId":"ch_work_han_thu_2","textTraditional":"〔六〕　如淳曰：「閩音緡。」應劭曰：「音文飾之文。」師古曰：「閩越，今泉州建安是其地也。其人本蛇種，故其字從虫。如音是也。虫音許尾反。」","sentenceOrder":45},
  {"id":"s_work_han_thu_2_46","chapterId":"ch_work_han_thu_2","textTraditional":"帝乃西都洛陽。夏五月，兵皆罷歸家。詔曰：「諸侯子在關中者，復之十二歲，〔一〕其歸者半之。〔二〕民前或相聚保山澤，不書名數，〔三〕今天下已定，令各歸其縣，復故爵田宅，〔四〕吏以文法教訓辨告，勿笞辱。〔五〕民以飢餓自賣為人奴婢者，皆免為庶人。軍吏卒會赦，其亡罪而亡爵及不滿大夫者，皆賜爵為大夫。〔六〕故大夫以上賜爵各一級，〔七〕其七大夫以上，皆令食邑，〔八〕非七大夫以下，皆復其身及戶，勿事。」〔九〕又曰：「七大夫、公乘以上，皆高爵也。〔一０〕諸侯子及從軍歸者，甚多高爵，吾數詔吏先與田宅，及所當求於吏者，亟與。〔一一〕爵或人君，上所尊禮，〔一二〕久立吏前，曾不為決，〔一三〕甚亡謂也。〔一四〕異日秦民爵公大夫以上，令丞與亢禮。〔一五〕今吾於爵非輕也，吏獨安取此！〔一六〕且法以有功勞行田宅，〔一七〕今小吏未嘗從軍者多滿，〔一八〕而有功者顧不得，〔一九〕背公立私，守尉長吏教訓甚不善。〔二０〕其令諸吏善遇高爵，稱吾意。〔二一〕且廉問，有不如吾詔者，以重論之。」〔二二〕","sentenceOrder":46},
  {"id":"s_work_han_thu_2_47","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「復音方目反。」","sentenceOrder":47},
  {"id":"s_work_han_thu_2_48","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「各已還其本土者，復六歲也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_2_49","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　師古曰：「保，守也，安也。守而安之，以避難也。名數，謂戶籍也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_2_50","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　師古曰：「復，還也，音扶目反。」","sentenceOrder":50},
  {"id":"s_work_han_thu_2_51","chapterId":"ch_work_han_thu_2","textTraditional":"〔五〕　師古曰：「辨告者，分別義理以曉喻之。」","sentenceOrder":51},
  {"id":"s_work_han_thu_2_52","chapterId":"ch_work_han_thu_2","textTraditional":"〔六〕　如淳曰：「軍吏卒會赦，得免罪，及本無罪而亡爵級者，皆賜爵為大夫。」師古曰：「大夫，第五爵也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_2_53","chapterId":"ch_work_han_thu_2","textTraditional":"〔七〕　師古曰：「就加之也。級，等也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_2_54","chapterId":"ch_work_han_thu_2","textTraditional":"〔八〕　臣瓚曰：「秦制，列侯乃得食邑，今七大夫以上皆食邑，所以寵之也。」師古曰：「七大夫，公大夫也，爵第七，故謂之七大夫。」","sentenceOrder":54},
  {"id":"s_work_han_thu_2_55","chapterId":"ch_work_han_thu_2","textTraditional":"〔九〕　應劭曰：「不輸戶賦也。」如淳曰：「事謂役使也。」師古曰：「復其身及一戶之內皆不徭賦也。復音扶目反。」","sentenceOrder":55},
  {"id":"s_work_han_thu_2_56","chapterId":"ch_work_han_thu_2","textTraditional":"〔一０〕師古曰：「公乘，第八爵。」","sentenceOrder":56},
  {"id":"s_work_han_thu_2_57","chapterId":"ch_work_han_thu_2","textTraditional":"〔一一〕師古曰：「亟，急也，音居力反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_2_58","chapterId":"ch_work_han_thu_2","textTraditional":"〔一二〕師古曰：「爵高有國邑者，則自君其人，故云或人君也。上謂天子。」","sentenceOrder":58},
  {"id":"s_work_han_thu_2_59","chapterId":"ch_work_han_thu_2","textTraditional":"〔一三〕師古曰：「有辨（說）〔訟〕及陳請者，不早為決斷。」","sentenceOrder":59},
  {"id":"s_work_han_thu_2_60","chapterId":"ch_work_han_thu_2","textTraditional":"〔一四〕師古曰：「亡謂者，失於事宜，不可以訓。」","sentenceOrder":60},
  {"id":"s_work_han_thu_2_61","chapterId":"ch_work_han_thu_2","textTraditional":"〔一五〕應劭曰：「言從公大夫以上，民與令丞亢禮。亢禮者，長揖不拜。」師古曰：「異日，猶言往日也。亢者，當也，言高下相當，無所卑屈，不獨謂揖拜也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_2_62","chapterId":"ch_work_han_thu_2","textTraditional":"〔一六〕師古曰：「於何得此輕爵之法也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_2_63","chapterId":"ch_work_han_thu_2","textTraditional":"〔一七〕蘇林曰：「行音行酒之行，猶付與也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_2_64","chapterId":"ch_work_han_thu_2","textTraditional":"〔一八〕如淳曰：「多自滿足也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_2_65","chapterId":"ch_work_han_thu_2","textTraditional":"〔一九〕師古曰：「顧猶反也，言若人反顧然。」","sentenceOrder":65},
  {"id":"s_work_han_thu_2_66","chapterId":"ch_work_han_thu_2","textTraditional":"〔二０〕師古曰：「守，郡守也。尉，郡尉也。長吏，謂縣之令長。」","sentenceOrder":66},
  {"id":"s_work_han_thu_2_67","chapterId":"ch_work_han_thu_2","textTraditional":"〔二一〕師古曰：「稱，副也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_2_68","chapterId":"ch_work_han_thu_2","textTraditional":"〔二二〕師古曰：「廉，察也。廉字本作覝，其音同耳。」","sentenceOrder":68},
  {"id":"s_work_han_thu_2_69","chapterId":"ch_work_han_thu_2","textTraditional":"帝置酒雒陽南宮。上曰：〔一〕「通侯諸將〔二〕毋敢隱朕〔三〕，皆言其情。吾所以有天下者何？項氏之所以失天下者何？」高起、王陵對曰：〔四〕「陛下嫚而侮人，〔五〕項羽仁而敬人。然陛下使人攻城略地，所降下者，因以與之，與天下同利也。項羽妒賢嫉能，有功者害之，賢者疑之，戰勝而不與人功，得地而不與人利，此其所以失天下也。」上曰：「公知其一，未知其二。夫運籌帷幄之中，決勝千里之外，吾不如子房；填國家，撫百姓，給餉餽，不絕糧道，吾不如蕭何；〔六〕連百萬之眾，戰必勝，攻必取，吾不如韓信。三者皆人傑，吾能用之，〔七〕此吾所以取天下者也。項羽有一范增而不能用，此所以為我禽也。」群臣說服。〔八〕","sentenceOrder":69},
  {"id":"s_work_han_thu_2_70","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　如淳曰：「蔡邕云上者尊位所在也。但言上，不敢言尊號耳。」","sentenceOrder":70},
  {"id":"s_work_han_thu_2_71","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　應劭曰：「舊曰徹侯，避武帝諱曰通侯。通亦徹也。通者，言其功德通於王室也。」張晏曰：「後改為列侯。列者，見序列也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_2_72","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　如淳曰：「朕，我也。蔡邕曰古者上下共之。咎繇與帝舜言稱朕，屈原曰『朕皇考』，至秦獨以為尊稱，漢遂因之而不改也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_2_73","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　張晏曰：「詔使高官者起，故陵先對。」孟康曰：「姓高，名起。」臣瓚曰：「漢帝年紀高帝時有信平侯臣陵、都武侯臣起。魏相、邴吉高帝時奏事有將軍臣陵、臣起。」師古曰：「張說非也。若言高官者起，則丞相蕭何、太尉盧綰及張良、陳平之屬時皆在陵上，陵不得先對也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_2_74","chapterId":"ch_work_han_thu_2","textTraditional":"〔五〕　師古曰：「嫚，易也，讀與慢同。」","sentenceOrder":74},
  {"id":"s_work_han_thu_2_75","chapterId":"ch_work_han_thu_2","textTraditional":"〔六〕　師古曰：「填與鎮同。鎮，安也。餽亦饋字。」","sentenceOrder":75},
  {"id":"s_work_han_thu_2_76","chapterId":"ch_work_han_thu_2","textTraditional":"〔七〕　師古曰：「傑言桀然獨出也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_2_77","chapterId":"ch_work_han_thu_2","textTraditional":"〔八〕　師古曰：「說讀曰悅。」","sentenceOrder":77},
  {"id":"s_work_han_thu_2_78","chapterId":"ch_work_han_thu_2","textTraditional":"初，田橫歸彭越。項羽已滅，橫懼誅，與賓客亡入海。上恐其久為亂，遣使者赦橫，曰：「橫來，大者王，小者侯；　〔一〕不來，且發兵加誅。」橫懼，乘傳詣雒陽，〔二〕未至三十里，自殺。上壯其節，為流涕，發卒二千人，以王禮葬焉。","sentenceOrder":78},
  {"id":"s_work_han_thu_2_79","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「大者，謂其長率，即橫身也。小者，其徒屬也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_2_80","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　如淳曰：「律，四馬高足為置傳，四馬中足為馳傳，四馬下足為乘傳，一馬二馬為軺傳。急者乘一乘傳。」師古曰：「傳者，若今之驛，古者以車，謂之傳車，其後又單置馬，謂之驛騎。傳音張戀反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_2_81","chapterId":"ch_work_han_thu_2","textTraditional":"戍卒婁敬求見，說上曰：「陛下取天下與周異，而都雒陽，不便，不如入關，據秦之固。」上以問張良，良因勸上。是日，車駕西都長安。〔一〕拜婁敬為奉春君，〔二〕賜姓劉氏。六月壬辰，大赦天下。","sentenceOrder":81},
  {"id":"s_work_han_thu_2_82","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「凡言車駕者，謂天子乘車而行，不敢指斥也。是日，即其日也。著是日者，言從善之速也。長安本秦之鄉名，高祖作都焉。」","sentenceOrder":82},
  {"id":"s_work_han_thu_2_83","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　張晏曰：「春，歲之始也，今婁敬發事之始，故號曰奉春君也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_2_84","chapterId":"ch_work_han_thu_2","textTraditional":"秋七月，燕王臧荼反，上自將征之。九月，虜荼。詔諸侯王視有功者立以為燕王。荊王臣信等十人〔一〕皆曰：「太尉長安侯盧綰功最多，請立以為燕王。」使丞相噲將兵平代地。","sentenceOrder":84},
  {"id":"s_work_han_thu_2_85","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　如淳曰：「荊亦楚也。」賈逵曰：「秦莊襄王名楚，故改諱荊，遂行於世。」晉灼曰：「詩曰『奮伐荊楚』，自秦之先故以稱荊也。」師古曰：「晉說是也。左傳又云『荊尸而舉』，亦已久矣。」","sentenceOrder":85},
  {"id":"s_work_han_thu_2_86","chapterId":"ch_work_han_thu_2","textTraditional":"利幾反，上自擊破之。利幾者，項羽將。羽敗，利幾為陳令，降，上侯之潁川。上至雒陽，舉通侯籍召之，〔一〕而利幾恐，反〔二〕。","sentenceOrder":86},
  {"id":"s_work_han_thu_2_87","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　蘇林曰：「都以侯籍召之。」","sentenceOrder":87},
  {"id":"s_work_han_thu_2_88","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「普召通侯，而利幾自以項羽將，故恐懼而反也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_2_89","chapterId":"ch_work_han_thu_2","textTraditional":"後九月，徙諸侯子關中。治長樂宮。","sentenceOrder":89},
  {"id":"s_work_han_thu_2_90","chapterId":"ch_work_han_thu_2","textTraditional":"六年冬十月，令天下縣邑城。〔一〕","sentenceOrder":90},
  {"id":"s_work_han_thu_2_91","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　張晏曰：「皇后、公主所食曰邑。令各自築其城也。」師古曰：「縣之與邑，皆令築城。」","sentenceOrder":91},
  {"id":"s_work_han_thu_2_92","chapterId":"ch_work_han_thu_2","textTraditional":"人告楚王信謀反，上問左右，左右爭欲擊之。用陳平計，乃偽游雲夢。〔一〕十二月，會諸侯于陳，楚王信迎謁，因執之。詔曰：「天下既安，豪桀有功者封侯，新立，未能盡圖其功。〔二〕身居軍九年，或未習法令，或以其故犯法，〔三〕大者死刑，吾甚憐之。其赦天下。」田肯賀上曰：「甚善，陛下得韓信，又治秦中。〔四〕秦，形勝之國也，〔五〕帶河阻山，縣隔千里，〔六〕持戟百萬，秦得百二焉。〔七〕地勢便利，其以下兵於諸侯，譬猶居高屋之上建瓴水也。〔八〕夫齊，東有琅邪、即墨之饒，〔九〕南有泰山之固，西有濁河之限，〔一０〕北有勃海之利，地方二千里，持戟百萬，縣隔千里之外，齊得十二焉。〔一一〕此東西秦也。非親子弟，莫可使王齊者。」上曰：「善。」賜金五百斤。上還至雒陽，赦韓信，封為淮陰侯。","sentenceOrder":92},
  {"id":"s_work_han_thu_2_93","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　韋昭曰：「在南郡之華容也。」師古曰：「夢讀如本字，又音莫風反。」","sentenceOrder":93},
  {"id":"s_work_han_thu_2_94","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「新立，言新即帝位也。圖謂謀而賞之。」","sentenceOrder":94},
  {"id":"s_work_han_thu_2_95","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　韋昭曰：「言未習知法令而犯之者，有司因以故犯法之罪罪之，故帝愍焉。」師古曰：「此說非也。言以未習法令之故，不知避罪，遂致犯刑，帝原其本情，故加憐之。」","sentenceOrder":95},
  {"id":"s_work_han_thu_2_96","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　師古曰：「治謂都之也。秦中謂關中，秦地也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_2_97","chapterId":"ch_work_han_thu_2","textTraditional":"〔五〕　張晏曰：「得形勢之勝便也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_2_98","chapterId":"ch_work_han_thu_2","textTraditional":"〔六〕　鄭氏曰：「縣音懸。」師古曰：「此本古之懸字耳，後人轉用為州縣字，乃更加心以別之，非當借音。他皆類此。」","sentenceOrder":98},
  {"id":"s_work_han_thu_2_99","chapterId":"ch_work_han_thu_2","textTraditional":"〔七〕　應劭曰：「言河山之險，與諸侯相縣隔，絕千里也。所以能禽諸侯者，得天下之利百二也。」李斐曰：「河山之險，由地勢高，順流而下易，故天下於秦縣隔千里也。持戟百萬，秦得百二焉。」蘇林曰：「百二，得百中之二，二萬人也。秦地險固，二萬人足當諸侯百萬人也。」師古曰：「縣隔千里，李、應得之。秦得百二，蘇說是也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_2_100","chapterId":"ch_work_han_thu_2","textTraditional":"〔八〕　如淳曰：「瓴，盛水瓶也。居高屋之上而幡瓴水，言其向下之勢易也。建音謇。」蘇林曰：「瓴讀曰鈴。」師古曰：「如、蘇音說皆是。建音居偃反。」","sentenceOrder":100},
  {"id":"s_work_han_thu_2_101","chapterId":"ch_work_han_thu_2","textTraditional":"〔九〕　師古曰：「二縣近海，財用之所出。」","sentenceOrder":101},
  {"id":"s_work_han_thu_2_102","chapterId":"ch_work_han_thu_2","textTraditional":"〔一０〕晉灼曰：「齊西有平原，河水東北過高唐。高唐即平原也。孟津號黃河，故曰濁河也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_2_103","chapterId":"ch_work_han_thu_2","textTraditional":"〔一一〕應劭曰：「齊得十之二耳，故愍王稱東帝，後復歸之，卒為秦所滅者，利鈍之勢異也。」李斐曰：「齊有山河之限，地方二千里，是與天下縣隔也。設有持戟百萬之眾，齊得十中之二焉。百萬十分之二，亦二十萬也。但文相避，故言東西秦，其勢敵也。」蘇林曰：「十二，得十中之二，二十萬人當百萬。言齊雖固，不如秦二萬乃當百萬也。」晉灼曰：「案文攷義，蘇說是也。」師古曰：「蘇、晉之釋得其意也。秦得百二者，二萬人當諸侯百萬人也。齊得十二者，二十萬人當諸侯百萬也。所以言縣隔千里之外者，除去秦地，而齊乃與諸侯計利便也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_2_104","chapterId":"ch_work_han_thu_2","textTraditional":"甲申，始剖符封功臣曹參等為通侯。〔一〕詔曰：「齊，古之建國也，今為郡縣，其復以為諸侯。〔二〕將軍劉賈數有大功，及擇寬惠脩絜者，王齊、荊地。」春正月丙午，韓王信等奏請以故東陽郡、鄣郡、吳郡五十三縣立劉賈為荊王，〔三〕以碭郡、薛郡、郯郡三十六縣立弟文信君交為楚王。〔四〕壬子，以雲中、鴈門、代郡五十三縣立兄宜信侯喜為代王，以膠東、膠西、臨淄、濟北、博陽、城陽郡七十三縣立子肥為齊王，以太原郡三十一縣為韓國，徙韓王信都晉陽。","sentenceOrder":104},
  {"id":"s_work_han_thu_2_105","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「剖，破也，與其合符而分授之也。剖音普口反。」","sentenceOrder":105},
  {"id":"s_work_han_thu_2_106","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「為國以封諸侯王。」","sentenceOrder":106},
  {"id":"s_work_han_thu_2_107","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　文穎曰：「東陽，今下邳也。鄣郡，今丹（楊）〔陽〕也。吳郡，本會稽也。」韋昭曰：「鄣郡，今故鄣縣也，後郡徙丹（楊）〔陽〕，轉以為縣，故謂之故鄣也。」師古曰：「鄣音章。」","sentenceOrder":107},
  {"id":"s_work_han_thu_2_108","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　文穎曰：「薛郡，今魯國是也。郯郡，今東海郡也。」師古曰：「郯音談。」","sentenceOrder":108},
  {"id":"s_work_han_thu_2_109","chapterId":"ch_work_han_thu_2","textTraditional":"上已封大功臣（三）〔二〕十餘人，其餘爭功，未得行封。上居南宮，從復道上〔一〕見諸將往往耦語，以問張良。良曰：「陛下與此屬共取天下，今已為天子，而所封皆故人所愛，所誅皆平生仇怨。今軍吏計功，以天下為不足用遍封，〔二〕而恐以過失及誅，故相聚謀反耳。」上曰：「為之奈何？」良曰：「取上素所不快，〔三〕計群臣所共知最甚者一人，先封以示群臣。」三月，上置酒，封雍齒，因趣丞相急定功行封。〔四〕罷酒，群臣皆喜，曰：「雍齒且侯，吾屬亡患矣！」","sentenceOrder":109},
  {"id":"s_work_han_thu_2_110","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　如淳曰：「復音複，上下有道，故謂之復。」","sentenceOrder":110},
  {"id":"s_work_han_thu_2_111","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「言有功者多，而土地少。」","sentenceOrder":111},
  {"id":"s_work_han_thu_2_112","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　師古曰：「言有舊嫌者也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_2_113","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　師古曰：「趣讀曰促。」","sentenceOrder":113},
  {"id":"s_work_han_thu_2_114","chapterId":"ch_work_han_thu_2","textTraditional":"上歸櫟陽，五日一朝太公。太公家令說太公曰：「天亡二日，土亡二王。皇帝雖子，人主也；太公雖父，人臣也。奈何令人主拜人臣！如此，則威重不行。」後上朝，太公擁彗，〔一〕迎門卻行。〔二〕上大驚，下扶太公。太公曰：「帝，人主，奈何以我亂天下法！」於是上心善家令言，〔三〕賜黃金五百斤。夏五月丙午，詔曰：「人之至親，莫親於父子，故父有天下傳歸於子，子有天下尊歸於父，此人道之極也。前日天下大亂，兵革並起，萬民苦殃，朕親被堅執銳，〔四〕自帥士卒，犯危難，平暴亂，立諸侯，偃兵息民，天下大安，此皆太公之教訓也。諸王、通侯、將軍、群卿、大夫已尊朕為皇帝，而太公未有號。今上尊太公曰太上皇。」〔五〕","sentenceOrder":114},
  {"id":"s_work_han_thu_2_115","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　李奇曰：「為恭也，如今卒持帚也。」師古曰：「彗者，所以埽也，音似歲反。」","sentenceOrder":115},
  {"id":"s_work_han_thu_2_116","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「卻退而行也，音丘略反。」","sentenceOrder":116},
  {"id":"s_work_han_thu_2_117","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　師古曰：「晉太子庶子劉寶云善其發悟己心，因得尊崇父號，非善其令父敬己。」","sentenceOrder":117},
  {"id":"s_work_han_thu_2_118","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　師古曰：「被堅謂甲冑也。執銳謂利兵也。被音皮義反。」","sentenceOrder":118},
  {"id":"s_work_han_thu_2_119","chapterId":"ch_work_han_thu_2","textTraditional":"〔五〕　師古曰：「太上，極尊之稱也。皇，君也。天子之父，故號曰皇。不預治國，故不言帝也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_2_120","chapterId":"ch_work_han_thu_2","textTraditional":"秋九月，匈奴圍韓王信於馬邑，信降匈奴。","sentenceOrder":120},
  {"id":"s_work_han_thu_2_121","chapterId":"ch_work_han_thu_2","textTraditional":"七年冬十月，上自將擊韓王信於銅鞮，〔一〕斬其將。信亡走匈奴，（與）其將曼丘臣、王黃〔二〕共立故趙後趙利為王，〔三〕收信散兵，與匈奴共距漢。上從晉陽連戰，乘勝逐北，至樓煩，會大寒，士卒墮指者什二三。〔四〕遂至平城，為匈奴所圍，七日，用陳平祕計得出。〔五〕使樊噲留定代地。","sentenceOrder":121},
  {"id":"s_work_han_thu_2_122","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「縣名也。鞮音丁奚反。」","sentenceOrder":122},
  {"id":"s_work_han_thu_2_123","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「姓曼丘，名臣也。曼丘、母丘本一姓也，語有緩急耳。曼音萬。」","sentenceOrder":123},
  {"id":"s_work_han_thu_2_124","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　師古曰：「故趙，六國時趙也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_2_125","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　師古曰：「十人之中，二三墮指。」","sentenceOrder":125},
  {"id":"s_work_han_thu_2_126","chapterId":"ch_work_han_thu_2","textTraditional":"〔五〕　應劭曰：「陳平使畫工圖美女，間遣人遺閼氏，云漢有美女如此，今皇帝困厄，欲獻之。閼氏畏其奪己寵，因謂單于曰：『漢天子亦有神靈，得其土地，非能有也。』於是匈奴開其一角，得突出。」鄭氏曰：「以計鄙陋，故祕不傳。」師古曰：「應氏之說出桓譚新論，蓋譚以意測之，事當然耳，非紀傳所說也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_2_127","chapterId":"ch_work_han_thu_2","textTraditional":"十二月，上還過趙，不禮趙王。是月，匈奴攻代，代王喜棄國，自歸雒陽，赦為合陽侯。辛卯，立子如意為代王。","sentenceOrder":127},
  {"id":"s_work_han_thu_2_128","chapterId":"ch_work_han_thu_2","textTraditional":"春，令郎中有罪耐以上，請之。〔一〕民產子，復勿事二歲〔二〕。","sentenceOrder":128},
  {"id":"s_work_han_thu_2_129","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　應劭曰：「輕罪不至于髡，完其耏鬢，故曰耏。古耐字從彡，髮膚之意也。杜林以為法度之字皆從寸，後改如是。言耐罪已上，皆當先請也。耐音若能。」如淳曰：「耐猶任也，任其事也。」師古曰：「依應氏之說，耏當音而，如氏之解則音乃代反，其義亦兩通。（而）〔耏〕謂頰旁毛也。彡，毛髮貌也，音所廉反，又先廉反。而功臣侯表宣曲侯通耏為鬼薪，則應氏之說斯為長矣。」","sentenceOrder":129},
  {"id":"s_work_han_thu_2_130","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「勿事，不役使也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_2_131","chapterId":"ch_work_han_thu_2","textTraditional":"二月，至長安。蕭何治未央宮，立東闕、北闕、前殿、武庫、大倉。〔一〕上見其壯麗，甚怒，謂何曰：「天下匈匈，勞苦數歲，成敗未可知，〔二〕是何治宮室過度也！」何曰：「天下方未定，故可因以就宮室。〔三〕且夫天子以四海為家，非令壯麗亡以重威，且亡令後世有以加也。」上說。〔四〕自櫟陽徙都長安。置宗正（宮）〔官〕以序九族。夏四月，行如雒陽。〔五〕","sentenceOrder":131},
  {"id":"s_work_han_thu_2_132","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「未央殿雖南嚮，而上書奏事謁見之徒皆詣北闕，公車司馬亦在北焉。是則以北闕為正門，而又有東門、東闕。至於西南兩面，無門闕矣。蓋蕭何初立未央宮，以厭勝之術，理宜然乎？」","sentenceOrder":132},
  {"id":"s_work_han_thu_2_133","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「匈匈，喧擾之意。」","sentenceOrder":133},
  {"id":"s_work_han_thu_2_134","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　師古曰：「就，成也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_2_135","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　師古曰：「說讀曰悅。」","sentenceOrder":135},
  {"id":"s_work_han_thu_2_136","chapterId":"ch_work_han_thu_2","textTraditional":"〔五〕　師古曰：「如，往也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_2_137","chapterId":"ch_work_han_thu_2","textTraditional":"八年冬，上東擊韓信餘寇於東垣。〔一〕還過趙，趙相貫高等恥上不禮其王，陰謀欲弒上。上欲宿，心動，問「縣名何？」曰：「柏人。」上曰：「柏人者，迫於人也。」去弗宿。","sentenceOrder":137},
  {"id":"s_work_han_thu_2_138","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　孟康曰：「真定也。」師古曰：「垣音轅。」","sentenceOrder":138},
  {"id":"s_work_han_thu_2_139","chapterId":"ch_work_han_thu_2","textTraditional":"十一月，令士卒從軍死者為槥，〔一〕歸其縣，縣給衣衾棺葬具，〔二〕祠以少牢，長吏視葬。十二月，行自東垣至。〔三〕","sentenceOrder":139},
  {"id":"s_work_han_thu_2_140","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　服虔曰：「槥音衛。」應劭曰：「小棺也，今謂之櫝。」","sentenceOrder":140},
  {"id":"s_work_han_thu_2_141","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　如淳曰：「棺音貫，謂棺斂之服也。」臣瓚曰：「初以槥致其尸於家，縣官更給棺衣更斂之也。金布令曰『不幸死，死所為櫝，傳歸所居縣，賜以衣棺』也。」師古曰：「初為槥櫝，至縣更給衣及棺，備其葬具耳。不勞改讀音為貫也。金布者，令篇（者）〔名〕，若今言倉庫令也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_2_142","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　師古曰：「至京師。」","sentenceOrder":142},
  {"id":"s_work_han_thu_2_143","chapterId":"ch_work_han_thu_2","textTraditional":"春三月，行如雒陽。令吏卒從軍至平城及守城邑者〔一〕皆復終身勿事。〔二〕爵非公乘以上毋得冠劉氏冠。〔三〕賈人毋得衣錦繡綺縠絺紵剡，操兵，乘騎馬。〔四〕秋八月，吏有罪未發覺者，赦之。九月，行自雒陽至，淮南王、梁王、趙王、楚王皆從。","sentenceOrder":143},
  {"id":"s_work_han_thu_2_144","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　如淳曰：「平城左右諸城能堅守（也）〔者〕。」","sentenceOrder":144},
  {"id":"s_work_han_thu_2_145","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「復音方目反。」","sentenceOrder":145},
  {"id":"s_work_han_thu_2_146","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　文穎曰：「即竹皮冠也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_2_147","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　師古曰：「賈人，坐販賣者也。綺，文繒也，即今之細綾也。稀，細葛也。紵，織紵為布及疏也。剡，織毛若今毼及氍毹之類也。操，持也。兵，凡兵器也。乘，駕車也。騎，單騎也。賈音古。絺音丑知反。紵音佇。剡音居例反。操音千高反。」","sentenceOrder":147},
  {"id":"s_work_han_thu_2_148","chapterId":"ch_work_han_thu_2","textTraditional":"九年冬十月，淮南王、梁王、趙王、楚王朝未央宮，置酒前殿。上奉玉卮〔一〕為太上皇壽，〔二〕曰：「始大人常以臣亡賴，〔三〕不能治產業，不如仲力。〔四〕今某之業所就孰與仲多？」〔五〕殿上群臣皆稱萬歲，大笑為樂。","sentenceOrder":148},
  {"id":"s_work_han_thu_2_149","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　應劭曰：「飲酒禮器也，古以角作，受四升。古卮字作觝。」晉灼曰：「音支。」師古曰：「卮，飲酒圓器也，今尚有之。」","sentenceOrder":149},
  {"id":"s_work_han_thu_2_150","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「進酒而獻壽也，已解於上。」","sentenceOrder":150},
  {"id":"s_work_han_thu_2_151","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　應劭曰：「賴者，恃也。」晉灼曰：「許慎云『賴，利也』，無利入於家也。或曰江淮之間謂小兒多詐狡獪為亡賴。」師古曰：「晉說是也。獪音工外反。」","sentenceOrder":151},
  {"id":"s_work_han_thu_2_152","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　服虔曰：「力，勤力也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_2_153","chapterId":"ch_work_han_thu_2","textTraditional":"〔五〕　師古曰：「就，成也。與亦如也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_2_154","chapterId":"ch_work_han_thu_2","textTraditional":"十一月，徙齊楚大族昭氏、屈氏、景氏、懷氏、田氏五姓關中，與利田宅。〔一〕十二月，行如雒陽。","sentenceOrder":154},
  {"id":"s_work_han_thu_2_155","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「利謂便好也。屈音九勿反。」","sentenceOrder":155},
  {"id":"s_work_han_thu_2_156","chapterId":"ch_work_han_thu_2","textTraditional":"貫高等謀逆發覺，逮捕高等，〔一〕并捕趙王敖下獄。詔敢有隨王，罪三族。〔二〕郎中田叔、孟舒等十人自髡鉗為王家奴，〔三〕從王就獄。王實不知其謀。春正月，廢趙王敖為宣平侯。徙代王如意為趙王，王趙國。丙寅，前有罪殊死以下，皆赦之。","sentenceOrder":156},
  {"id":"s_work_han_thu_2_157","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「逮捕，謂事相連及者皆捕之也。一曰，在道守禁，相屬不絕，若今之傳送囚耳。」","sentenceOrder":157},
  {"id":"s_work_han_thu_2_158","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　張晏曰：「父母兄弟妻子也。」如淳曰：「父族、母族、妻族也。」師古曰：「如說是也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_2_159","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　師古曰：「鉗，以鐵束頸也，音其炎反。」","sentenceOrder":159},
  {"id":"s_work_han_thu_2_160","chapterId":"ch_work_han_thu_2","textTraditional":"二月，行自雒陽至。賢趙臣田叔、孟舒等十人，召見與語，漢廷臣無能出其右者。〔一〕上說，〔二〕盡拜為郡守、諸侯相。","sentenceOrder":160},
  {"id":"s_work_han_thu_2_161","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「古諸以右為尊，言材用無能過之者，故云不出其右也。他皆類此。」","sentenceOrder":161},
  {"id":"s_work_han_thu_2_162","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":162},
  {"id":"s_work_han_thu_2_163","chapterId":"ch_work_han_thu_2","textTraditional":"夏六月乙未晦，日有食之。","sentenceOrder":163},
  {"id":"s_work_han_thu_2_164","chapterId":"ch_work_han_thu_2","textTraditional":"十年冬十月，淮南王、燕王、荊王、梁王、楚王、齊王、長沙王來朝。","sentenceOrder":164},
  {"id":"s_work_han_thu_2_165","chapterId":"ch_work_han_thu_2","textTraditional":"夏五月，太上皇后崩。〔一〕秋七月癸卯，太上皇崩，葬萬年。〔二〕赦櫟陽囚死罪以下。〔三〕八月，令諸侯王皆立太上皇廟于國都。","sentenceOrder":165},
  {"id":"s_work_han_thu_2_166","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　如淳曰：「王陵傳楚取太上皇、呂后為質。又項羽歸太公、呂后，不見歸媼也。又上五年追尊母媼為昭靈夫人，高后時乃追尊為昭靈后耳。漢儀注高帝母兵起時死小黃北，後於小黃作陵廟。以此二者推之，不得有太上皇后崩也。」李奇曰：「高祖後母也。」晉灼曰：「五年，追尊先媼曰昭靈夫人，言追尊，則明其已亡。史記十年春夏無事，七月太上皇崩，葬櫟陽宮，明此長『夏五月太上皇后崩』八字也。又漢儀注先媼已葬陳留小黃。」師古曰：「如、晉二說皆得之，無此太上皇后也。諸家之說更有異端，適為煩穢，不足采也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_2_167","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「三輔黃圖云高祖初居櫟陽，故太上皇因在櫟陽。十年太上皇崩，葬其北原，起萬年邑，置長丞也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_2_168","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　臣瓚曰：「萬年陵在櫟陽縣界，故特赦之。」","sentenceOrder":168},
  {"id":"s_work_han_thu_2_169","chapterId":"ch_work_han_thu_2","textTraditional":"九月，代相國陳豨反。〔一〕上曰：「豨嘗為吾使，甚有信。〔二〕代地吾所急，故封豨為列侯，以相國守代，今乃與王黃等劫掠代地！吏民非有罪也，能去豨、黃來歸者，皆赦之。」〔三〕上自東，至邯鄲。上喜曰：「豨不南據邯鄲而阻漳水，吾知其亡能為矣。」趙相周昌奏常山二十五城亡其二十城，請誅守尉。〔四〕上曰：「守尉反乎？」對曰：「不。」上曰：「是力不足，亡罪。」上令周昌選趙壯士可令將者，白見四人。〔五〕上嫚罵曰：〔六〕「豎子能為將乎！」四人慚，皆伏地。上封各千戶，以為將。左右諫曰：「從入蜀漢，伐楚，賞未遍行，今封此，何功？」上曰：「非汝所知。陳豨反，趙代地皆豨有。吾以羽檄徵天下兵，未有至者，〔七〕今計唯獨邯鄲中兵耳。吾何愛四千戶，不以慰趙子弟！」皆曰：「善。」又求「樂毅有後乎？」〔八〕得其孫叔，封之樂鄉，號華成君。問豨將，皆故賈人。上曰：「吾知與之矣。」〔九〕乃多以金購豨將，〔一０〕豨將多降。","sentenceOrder":169},
  {"id":"s_work_han_thu_2_170","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　鄧展曰：「東海人名豬曰豨。」師古曰：「豨音許豈反。」","sentenceOrder":170},
  {"id":"s_work_han_thu_2_171","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「為音于偽反。」","sentenceOrder":171},
  {"id":"s_work_han_thu_2_172","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　師古曰：「去謂棄離之而來也。」","sentenceOrder":172},
  {"id":"s_work_han_thu_2_173","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　師古曰：「守者，郡守；尉者，郡尉也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_2_174","chapterId":"ch_work_han_thu_2","textTraditional":"〔五〕　師古曰：「白於天子而召見也。」","sentenceOrder":174},
  {"id":"s_work_han_thu_2_175","chapterId":"ch_work_han_thu_2","textTraditional":"〔六〕　師古曰：「嫚者，渫汙也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_2_176","chapterId":"ch_work_han_thu_2","textTraditional":"〔七〕　師古曰：「檄者，以木簡為書，長尺二寸，用徵召也。其有急事，則加以鳥羽插之，示速疾也。魏武奏事云今邊有警，輒露檄插羽。檄音胡歷反。」","sentenceOrder":176},
  {"id":"s_work_han_thu_2_177","chapterId":"ch_work_han_thu_2","textTraditional":"〔八〕　師古曰：「樂毅，戰國時燕將也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_2_178","chapterId":"ch_work_han_thu_2","textTraditional":"〔九〕　師古曰：「與，如也，言能如之何也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_2_179","chapterId":"ch_work_han_thu_2","textTraditional":"〔一０〕師古曰：「購，設賞募也，〔音搆〕。」","sentenceOrder":179},
  {"id":"s_work_han_thu_2_180","chapterId":"ch_work_han_thu_2","textTraditional":"十一年冬，上在邯鄲。豨將侯敞將萬餘人游行，王黃將騎千餘軍曲逆，〔一〕張春將卒萬餘人度河攻聊城。〔二〕漢將軍郭蒙與齊將擊，大破之。太尉周勃道太原入定代地，〔三〕至馬邑，馬邑不下，攻殘之。〔四〕豨將趙利守東垣，高祖攻之不下。卒罵，上怒。城降，卒罵者斬之。諸縣堅守不降反寇者，復租賦三歲。","sentenceOrder":180},
  {"id":"s_work_han_thu_2_181","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　文穎曰：「今中山蒲陰是也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_2_182","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「即今博州聊城縣。」","sentenceOrder":182},
  {"id":"s_work_han_thu_2_183","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　師古曰：「道由太原也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_2_184","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　師古曰：「殘謂多所殺戮也。」","sentenceOrder":184},
  {"id":"s_work_han_thu_2_185","chapterId":"ch_work_han_thu_2","textTraditional":"春正月，淮陰侯韓信謀反長安，夷三族。將軍柴武斬韓王信於參合。〔一〕","sentenceOrder":185},
  {"id":"s_work_han_thu_2_186","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「代之縣也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_2_187","chapterId":"ch_work_han_thu_2","textTraditional":"上還雒陽。詔曰：「代地居常山之北，與夷狄邊，趙乃從山南有之，遠，數有胡寇，難以為國。頗取山南太原之地益屬代，〔一〕代之雲中以西為雲中郡，則代受邊寇益少矣。王、相國、通侯、吏二千石擇可立為代王者。」燕王綰、相國何等三十三人皆曰：「子恆賢知溫良，請立以為代王，都晉陽。」〔二〕大赦天下。","sentenceOrder":187},
  {"id":"s_work_han_thu_2_188","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「少割以益之，不盡取也。頗音普我反。後皆類此。」","sentenceOrder":188},
  {"id":"s_work_han_thu_2_189","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　如淳曰：「文紀言都中都，又文帝過太原，復晉陽、中都二歲，似遷都於中都也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_2_190","chapterId":"ch_work_han_thu_2","textTraditional":"二月，詔曰：「欲省賦甚。〔一〕今獻未有程，〔二〕吏或多賦以為獻，而諸侯王尤多，民疾之。〔三〕令諸侯王、通侯常以十月朝獻，及郡各以其口數率，〔四〕人歲六十三錢，以給獻費。」又曰：「蓋聞王者莫高於周文，伯者莫高於齊桓，〔五〕皆待賢人而成名。今天下賢者智能豈特古之人乎？〔六〕患在人主不交故也，士奚由進！〔七〕今吾以天之靈，賢士大夫定有天下，以為一家，欲其長久，世世奉宗廟亡絕也。賢人已與我共平之矣，而不與吾共安利之，可乎？賢士大夫有肯從我游者，吾能尊顯之。布告天下，使明知朕意。御史大夫昌下相國，〔八〕相國酇侯下諸侯王，〔九〕御史中執法下郡守，〔一０〕其有意稱明德者，必身勸，為之駕，〔一一〕遣詣相國府，署行、義、年。〔一二〕有而弗言，覺，免。年老癃病，勿遣。」〔一三〕","sentenceOrder":190},
  {"id":"s_work_han_thu_2_191","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「意甚欲省賦斂也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_2_192","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「程，法式也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_2_193","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　師古曰：「諸侯王賦其國中，以為獻物，又多於郡，故百姓疾苦之。」","sentenceOrder":193},
  {"id":"s_work_han_thu_2_194","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　師古曰：「率，計也。」","sentenceOrder":194},
  {"id":"s_work_han_thu_2_195","chapterId":"ch_work_han_thu_2","textTraditional":"〔五〕　師古曰：「伯讀曰霸。」","sentenceOrder":195},
  {"id":"s_work_han_thu_2_196","chapterId":"ch_work_han_thu_2","textTraditional":"〔六〕　師古曰：「特，獨也。」","sentenceOrder":196},
  {"id":"s_work_han_thu_2_197","chapterId":"ch_work_han_thu_2","textTraditional":"〔七〕　師古曰：「奚，何也。」","sentenceOrder":197},
  {"id":"s_work_han_thu_2_198","chapterId":"ch_work_han_thu_2","textTraditional":"〔八〕　臣瓚曰：「周昌已為趙相，御史大夫是趙堯耳。」","sentenceOrder":198},
  {"id":"s_work_han_thu_2_199","chapterId":"ch_work_han_thu_2","textTraditional":"〔九〕　臣瓚曰：「茂陵書何封國在南陽。酇音贊。」師古曰：「瓚說是也。而或云何封沛郡酇縣，音才何反，非也。案地理志南陽酇縣云侯國，沛酇縣不云侯國也。又南陽酇者，本是春秋時陰國，所謂遷陰于下陰者也。今為襄州陰城縣，有酇城，城西見有蕭何廟。彼土又有筑水，筑水之陽古曰筑陽縣，與酇側近連接。據何本傳，何薨之後子祿無嗣，高后封何夫人同為酇侯，小子延為筑陽侯。孝文罷同，更封延為酇侯。是知何封酇國兼得筑陽，此明驗也。但酇字別有〈虚阝〉音，是以沛之〈虚阝〉縣，史記、漢書皆作酇字，明其音同也。班固泗水亭碑以蕭何相國所封，與何同韻，於義無爽。然其封邑實在南陽，非沛縣也。且地理志云王莽改沛酇曰贊治，然則沛酇亦有贊音。〈虚阝〉、酇相亂，無所取信也。說者又引江統徂淮賦以為證，此乃統之疏謬，不可考覈，亦猶潘岳西征以陝之曲沃為成師所居耳。斯例甚多，不可具載。」","sentenceOrder":199},
  {"id":"s_work_han_thu_2_200","chapterId":"ch_work_han_thu_2","textTraditional":"〔一０〕晉灼曰：「中執法，中丞也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_2_201","chapterId":"ch_work_han_thu_2","textTraditional":"〔一一〕文穎曰：「有賢者，郡守身自往勸勉，令至京師，駕車遣之。」","sentenceOrder":201},
  {"id":"s_work_han_thu_2_202","chapterId":"ch_work_han_thu_2","textTraditional":"〔一二〕蘇林曰：「行狀年紀也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_2_203","chapterId":"ch_work_han_thu_2","textTraditional":"〔一三〕師古曰：「癃，疲病也，音隆。」","sentenceOrder":203},
  {"id":"s_work_han_thu_2_204","chapterId":"ch_work_han_thu_2","textTraditional":"三月，梁王彭越謀反，夷三族。〔一〕詔曰：「擇可以為梁王、淮陽王者。」燕王綰、相國何等請立子恢為梁王，子友為淮陽王。罷東郡，頗益梁；罷潁川郡，頗益淮陽。","sentenceOrder":204},
  {"id":"s_work_han_thu_2_205","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「夷，平也，謂盡誅除之。」","sentenceOrder":205},
  {"id":"s_work_han_thu_2_206","chapterId":"ch_work_han_thu_2","textTraditional":"夏四月，行自雒陽至。令豐人徙關中者皆復終身。〔一〕","sentenceOrder":206},
  {"id":"s_work_han_thu_2_207","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　應劭曰：「太上皇思（上）欲歸豐，高祖乃更築城寺市里如豐縣，號曰新豐，徙豐民以充實之。」師古曰：「徙豐人所居，即今之新豐古城是其處。復音方目反。」","sentenceOrder":207},
  {"id":"s_work_han_thu_2_208","chapterId":"ch_work_han_thu_2","textTraditional":"五月，詔曰：「粵人之俗，好相攻擊，前時秦徙中縣之民南方三郡，〔一〕使與百粵雜處。〔二〕會天下誅秦，南海尉它居南方長治之，〔三〕甚有文理，中縣人以故不耗減，〔四〕粵人相攻擊之俗益止，俱賴其力。今立它為南粵王。」使陸賈即授璽綬。〔五〕它稽首稱臣。","sentenceOrder":208},
  {"id":"s_work_han_thu_2_209","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　如淳曰：「中縣之民，中國縣民也。秦始皇略取彊梁地以為桂林、象郡、南海郡，故曰三郡。」","sentenceOrder":209},
  {"id":"s_work_han_thu_2_210","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　李奇曰：「欲以介其間，使不相攻擊也。」","sentenceOrder":210},
  {"id":"s_work_han_thu_2_211","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　晉灼曰：「長音長吏之長。」師古曰：「它，古佗字也，書本亦或作他，並音徒何反。它者，南海尉之名也，姓趙。長治，謂為之長（治）〔帥〕而治理之也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_2_212","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　師古曰：「耗，損也，音火到反。」","sentenceOrder":212},
  {"id":"s_work_han_thu_2_213","chapterId":"ch_work_han_thu_2","textTraditional":"〔五〕　師古曰：「即，就也，就其所居而立之。」","sentenceOrder":213},
  {"id":"s_work_han_thu_2_214","chapterId":"ch_work_han_thu_2","textTraditional":"六月，令士卒從入蜀、漢、關中者皆復終身。〔一〕","sentenceOrder":214},
  {"id":"s_work_han_thu_2_215","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「復音方目反。」","sentenceOrder":215},
  {"id":"s_work_han_thu_2_216","chapterId":"ch_work_han_thu_2","textTraditional":"秋七月，淮南王布反。上問諸將，滕公言故楚令尹薛公有籌策。上（見公）〔召見〕，薛公言布形勢，上善之，封薛公千戶。詔王、相國擇可立為淮南王者，群臣請立子長為王。上乃發上郡、北地、隴西車騎，巴蜀材官及中尉卒三萬人〔一〕為皇太子衛，軍霸上。布果如薛公言，東擊殺荊王劉賈，劫其兵，度淮擊楚，楚王交走入薛。上赦天下死罪以下，皆令從軍；徵諸侯兵，上自將以擊布。","sentenceOrder":216},
  {"id":"s_work_han_thu_2_217","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　應劭曰：「材官，有材力者。」張晏曰：「材官、騎士習射御騎馳戰陳，常以八月，太守、都尉、令、長、丞會都試，課殿最。水處則習船，邊郡將萬騎行障塞。光武時省。」韋昭曰：「中尉即執金吾也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_2_218","chapterId":"ch_work_han_thu_2","textTraditional":"十二年冬十月，上破布軍于會缶，〔一〕布走，令別將追之。","sentenceOrder":218},
  {"id":"s_work_han_thu_2_219","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　孟康曰：「音儈保，邑名，屬沛國蘄縣。」蘇林曰：「缶音否。」晉灼曰：「蘄縣鄉名也。」師古曰：「會音工外反。缶音丈瑞反。蘇音是也。此字本作否，而轉寫者誤為缶字耳。音保，非也。黥布傳則正作否字，此足明其不作缶也。」","sentenceOrder":219},
  {"id":"s_work_han_thu_2_220","chapterId":"ch_work_han_thu_2","textTraditional":"上還，過沛，留，置酒沛宮，悉召故人父老子弟佐酒。〔一〕發沛中兒得百二十人，教之歌。酒酣，〔二〕上擊筑，〔三〕自歌曰：「大風起兮雲飛揚，威加海內兮歸故鄉，安得猛士兮守四方！」令兒皆和習之。〔四〕上乃起舞，忼慨傷懷，〔五〕泣數行下。〔六〕謂沛父兄曰：「游子悲故鄉。〔七〕吾雖都關中，萬歲之後吾魂魄猶思（樂）沛。且朕自沛公以誅暴逆，遂有天下，其以沛為朕湯沐邑〔八〕，復其民，世世無有所與。」〔九〕沛父老諸母故人日樂飲極歡，道舊故為笑樂。〔一０〕十餘日，上欲去，沛父兄固請。上曰：「吾人眾多，父兄不能給。」乃去。沛中空縣皆之邑西獻。〔一一〕上留止，張飲三日。〔一二〕沛父兄皆頓首曰：「沛幸得復，豐未得，唯陛下哀矜。」上曰：「豐者，吾所生長，極不忘耳。〔一三〕吾特以其為雍齒故反我為魏。」沛父兄固請之，乃并復豐，比沛。","sentenceOrder":220},
  {"id":"s_work_han_thu_2_221","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　應劭曰：「助行酒。」","sentenceOrder":221},
  {"id":"s_work_han_thu_2_222","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「酣，洽也，音胡甘反。」","sentenceOrder":222},
  {"id":"s_work_han_thu_2_223","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　鄧展曰：「筑音竹。」應劭曰：「狀似琴而大，頭安弦，以竹擊之，故名曰筑。」師古曰：「今筑形似瑟而細頸也。」","sentenceOrder":223},
  {"id":"s_work_han_thu_2_224","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　師古曰：「和音胡臥反。」","sentenceOrder":224},
  {"id":"s_work_han_thu_2_225","chapterId":"ch_work_han_thu_2","textTraditional":"〔五〕　師古曰：「忼音口朗反。慨音口代反。」","sentenceOrder":225},
  {"id":"s_work_han_thu_2_226","chapterId":"ch_work_han_thu_2","textTraditional":"〔六〕　師古曰：「泣，目中淚也。」","sentenceOrder":226},
  {"id":"s_work_han_thu_2_227","chapterId":"ch_work_han_thu_2","textTraditional":"〔七〕　師古曰：「游子，行客也。悲謂顧念也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_2_228","chapterId":"ch_work_han_thu_2","textTraditional":"〔八〕　師古曰：「凡言湯沐邑者，謂以其賦稅供湯沐之具也。」","sentenceOrder":228},
  {"id":"s_work_han_thu_2_229","chapterId":"ch_work_han_thu_2","textTraditional":"〔九〕　師古曰：「復音方目反。與讀曰豫。」","sentenceOrder":229},
  {"id":"s_work_han_thu_2_230","chapterId":"ch_work_han_thu_2","textTraditional":"〔一０〕師古曰：「言日日樂飲也。樂並音來各反。」","sentenceOrder":230},
  {"id":"s_work_han_thu_2_231","chapterId":"ch_work_han_thu_2","textTraditional":"〔一一〕如淳曰：「獻牛酒也。」師古曰：「之，往也。皆往邑西，競有所獻，故縣中空無人。」","sentenceOrder":231},
  {"id":"s_work_han_thu_2_232","chapterId":"ch_work_han_thu_2","textTraditional":"〔一二〕張晏曰：「張，帷帳也。」師古曰：「張音竹亮反。」","sentenceOrder":232},
  {"id":"s_work_han_thu_2_233","chapterId":"ch_work_han_thu_2","textTraditional":"〔一三〕師古曰：「極，至也。至念之不忘也。」","sentenceOrder":233},
  {"id":"s_work_han_thu_2_234","chapterId":"ch_work_han_thu_2","textTraditional":"漢別將擊布軍洮水南北，〔一〕皆大破之，追斬布番陽。〔二〕","sentenceOrder":234},
  {"id":"s_work_han_thu_2_235","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　蘇林曰：「洮音兆。」","sentenceOrder":235},
  {"id":"s_work_han_thu_2_236","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「番音蒲何反。」","sentenceOrder":236},
  {"id":"s_work_han_thu_2_237","chapterId":"ch_work_han_thu_2","textTraditional":"周勃定代，斬陳豨於當城。〔一〕","sentenceOrder":237},
  {"id":"s_work_han_thu_2_238","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　韋昭曰：「代郡縣也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_2_239","chapterId":"ch_work_han_thu_2","textTraditional":"詔曰：「吳，古之建國也，日者荊王兼有其地，〔一〕今死亡後。朕欲復立吳王，其議可者。」長沙王臣等言：〔二〕「沛侯濞重厚，〔三〕請立為吳王。」已拜，上召謂濞曰：「汝狀有反相。」因拊其背，曰：「漢後五十年東南有亂，豈汝邪？〔四〕然天下同姓一家，汝慎毋反。」濞頓首曰：「不敢。」","sentenceOrder":239},
  {"id":"s_work_han_thu_2_240","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「日者，猶往日也。」","sentenceOrder":240},
  {"id":"s_work_han_thu_2_241","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「臣者，長沙王之名，吳芮之子也。今書本或臣下有芮字者，流俗妄加也。」","sentenceOrder":241},
  {"id":"s_work_han_thu_2_242","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　服虔曰：「濞音滂濞。」師古曰：「音普懿反。」","sentenceOrder":242},
  {"id":"s_work_han_thu_2_243","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　應劭曰：「高祖有聰略，反相徑可知。至於東南有亂，克期五十，占者所知也。若秦始皇東巡以厭氣，後劉項起東南，疑當如此耳。」如淳曰：「度其貯積足用為難，又吳楚世不賓服。」師古曰：「應說是也。拊謂摩循之。」","sentenceOrder":243},
  {"id":"s_work_han_thu_2_244","chapterId":"ch_work_han_thu_2","textTraditional":"十一月，行自淮南還。過魯，以大牢祠孔子。","sentenceOrder":244},
  {"id":"s_work_han_thu_2_245","chapterId":"ch_work_han_thu_2","textTraditional":"十二月，詔曰：「秦皇帝、楚隱王、〔一〕魏安釐王、〔二〕齊愍王、〔三〕趙悼襄王〔四〕皆絕亡後。其與秦始皇帝守冢二十家，楚、魏、齊各十家，趙及魏公子亡忌各五家，〔五〕令視其冢，復亡與它事。」〔六〕","sentenceOrder":245},
  {"id":"s_work_han_thu_2_246","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「陳勝也。」","sentenceOrder":246},
  {"id":"s_work_han_thu_2_247","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「昭王之子也。釐讀曰僖。漢書僖諡及福禧字，例多為釐。」","sentenceOrder":247},
  {"id":"s_work_han_thu_2_248","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　師古曰：「宣王之子，為淖齒所殺。」","sentenceOrder":248},
  {"id":"s_work_han_thu_2_249","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　師古曰：「孝成王之子。」","sentenceOrder":249},
  {"id":"s_work_han_thu_2_250","chapterId":"ch_work_han_thu_2","textTraditional":"〔五〕　師古曰：「亡忌即信陵君也。」","sentenceOrder":250},
  {"id":"s_work_han_thu_2_251","chapterId":"ch_work_han_thu_2","textTraditional":"〔六〕　師古曰：「復音方目反。與讀曰豫。」","sentenceOrder":251},
  {"id":"s_work_han_thu_2_252","chapterId":"ch_work_han_thu_2","textTraditional":"陳豨降將言豨反時燕王盧綰使人之豨所陰謀。〔一〕上使辟陽侯審食其迎綰，〔二〕綰稱疾。食其言綰反有端。春二月，使樊噲、周勃將兵擊綰。詔曰：「燕王綰與吾有故，愛之如子，聞與陳豨有謀，吾以為亡有，故使人迎綰。綰稱疾不來，謀反明矣。燕吏民非有罪也，賜其吏六百石以上爵各一級。與綰居，去來歸者，赦之，〔三〕加爵亦一級。」詔諸侯王議可立為燕王者，長沙王臣等請立子建為燕王。","sentenceOrder":252},
  {"id":"s_work_han_thu_2_253","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「之，往也。」","sentenceOrder":253},
  {"id":"s_work_han_thu_2_254","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「辟音必亦反。食其音異基。」","sentenceOrder":254},
  {"id":"s_work_han_thu_2_255","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　師古曰：「先與綰居，今能去之來歸漢者，赦其罪。」","sentenceOrder":255},
  {"id":"s_work_han_thu_2_256","chapterId":"ch_work_han_thu_2","textTraditional":"詔曰：「南武侯織亦粵之世也，立以為南海王。」〔一〕","sentenceOrder":256},
  {"id":"s_work_han_thu_2_257","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　文穎曰：「高祖五年，以象郡、桂林、南海、長沙立吳芮為長沙王。象郡、桂林、南海屬尉佗，佗未降，遙虛奪以封芮耳。後佗降漢，十一年，更立佗為南越王，自此王三郡。芮唯得長沙、桂林、零陵耳。今復封織為南海王，復遙奪佗一郡，織未得王之。」","sentenceOrder":257},
  {"id":"s_work_han_thu_2_258","chapterId":"ch_work_han_thu_2","textTraditional":"三月，詔曰：「吾立為天子，帝有天下，十二年于今矣。與天下之豪士賢大夫共定天下，同安輯之。〔一〕其有功者上致之王，次為列侯，下乃食邑。〔二〕而重臣之親，或為列侯，皆令自置吏，得賦斂，女子公主。〔三〕為列侯食邑者，皆佩之印，賜大第室。〔四〕吏二千石，徙之長安，受小第室。入蜀漢定三秦者，皆世世復。〔五〕吾於天下賢士功臣，可謂亡負矣。其有不義背天子擅起兵者，與天下共伐誅之。〔六〕布告天下，使明知朕意。」","sentenceOrder":258},
  {"id":"s_work_han_thu_2_259","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「輯與集同。」","sentenceOrder":259},
  {"id":"s_work_han_thu_2_260","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「謂非列侯而特賜食邑者。」","sentenceOrder":260},
  {"id":"s_work_han_thu_2_261","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　如淳曰：「公羊傳曰『天子嫁女於諸侯，必使諸侯同姓者主之』，故謂之公主。百官表『列侯所食曰國，皇后、公主所食曰邑』。帝姊妹曰長公主，諸王女曰翁主。」師古曰：「如說得之。天子不親主婚，故謂之公主。諸王即自主婚，故其女曰翁主。翁者，父也，言父主其婚也。亦曰王主，言王自主其婚也。高祖答項羽曰『吾翁即若翁也』。揚雄方言云『周、晉、秦、隴謂父曰翁』。而臣瓚、王楙或云公者比於上爵，或云主者婦人尊稱，皆失之。」","sentenceOrder":261},
  {"id":"s_work_han_thu_2_262","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　孟康曰：「有甲乙次第，故曰第也。」","sentenceOrder":262},
  {"id":"s_work_han_thu_2_263","chapterId":"ch_work_han_thu_2","textTraditional":"〔五〕　師古曰：「復音方目反。」","sentenceOrder":263},
  {"id":"s_work_han_thu_2_264","chapterId":"ch_work_han_thu_2","textTraditional":"〔六〕　師古曰：「擅，專也，音上戰反。他皆類此。」","sentenceOrder":264},
  {"id":"s_work_han_thu_2_265","chapterId":"ch_work_han_thu_2","textTraditional":"上擊布時，為流矢所中，行道疾。疾甚，呂后迎良醫。醫入見，上問醫。曰：「疾可治（不醫曰可治）。」於是上嫚罵之，曰：「吾以布衣提三尺取天下，〔一〕此非天命乎？命乃在天，雖扁鵲何益！」〔二〕遂不使治疾，賜黃金五十斤，罷之。呂后問曰：「陛下百歲後，蕭相國既死，誰令代之？」上曰：「曹參可。」問其次，曰：「王陵可，然少戇，〔三〕陳平可以助之。陳平知有餘，然難獨任。周勃重厚少文，然安劉氏者必勃也，可令為太尉。」呂后復問其次，上曰：「此後亦非乃所知也。」〔四〕","sentenceOrder":265},
  {"id":"s_work_han_thu_2_266","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「三尺，劍也。下韓安國傳所云三尺亦同，而流俗書本或云提三尺劍，劍字後人所加耳。」","sentenceOrder":266},
  {"id":"s_work_han_thu_2_267","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　韋昭曰：「泰山盧人也。名越人，魏桓侯時醫也。」臣瓚曰：「史記云齊勃海人也，魏無桓侯。」師古曰：「瓚說是也。扁音步典反。」","sentenceOrder":267},
  {"id":"s_work_han_thu_2_268","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　師古曰：「戇，愚也，古音下紺反，今則竹巷反。」","sentenceOrder":268},
  {"id":"s_work_han_thu_2_269","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　師古曰：「乃，汝也。言自此之後，汝亦終矣，不復知之。」","sentenceOrder":269},
  {"id":"s_work_han_thu_2_270","chapterId":"ch_work_han_thu_2","textTraditional":"盧綰與數千人居塞下候伺，幸上疾愈，自入謝。〔一〕夏四月甲辰，帝崩于長樂宮。〔二〕盧綰聞之，遂亡入匈奴。","sentenceOrder":270},
  {"id":"s_work_han_thu_2_271","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「冀得上疾愈，自入謝以為己身之幸也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_2_272","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　臣瓚曰：「帝年四十二即位，即位十二年，壽五十三。」","sentenceOrder":272},
  {"id":"s_work_han_thu_2_273","chapterId":"ch_work_han_thu_2","textTraditional":"呂后與審食其謀曰：「諸將故與帝為編戶民，〔一〕北面為臣，心常鞅鞅，〔二〕今乃事少主，非盡族是，天下不安。」〔三〕以故不發喪。人或聞，以語酈商。酈商見審食其曰：「聞帝已崩，四日不發喪，欲誅諸將。誠如此，天下危矣。陳平、灌嬰將十萬守滎陽，樊噲、周勃將二十萬定燕代，此聞帝崩，諸將皆誅，必連兵還鄉，以攻關中。〔四〕大臣內畔，諸將外反，亡可蹻足待也。」〔五〕審食其入言之，乃以丁未發喪，大赦天下。","sentenceOrder":273},
  {"id":"s_work_han_thu_2_274","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　師古曰：「編戶者，言列次名籍也。編音鞭。」","sentenceOrder":274},
  {"id":"s_work_han_thu_2_275","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　師古曰：「鞅鞅，不滿足也，音於亮反。他皆類此。」","sentenceOrder":275},
  {"id":"s_work_han_thu_2_276","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　師古曰：「族謂族誅之。是亦此也。」","sentenceOrder":276},
  {"id":"s_work_han_thu_2_277","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　師古曰：「鄉讀曰嚮。還嚮，猶言反嚮、內嚮也。」","sentenceOrder":277},
  {"id":"s_work_han_thu_2_278","chapterId":"ch_work_han_thu_2","textTraditional":"〔五〕　文穎曰：「蹻猶翹也。」如淳曰：「蹻音如今作樂蹻行之蹻。」晉灼曰：「許慎云『蹻，舉足小高也』，音矯。」師古曰：「晉說是也。」","sentenceOrder":278},
  {"id":"s_work_han_thu_2_279","chapterId":"ch_work_han_thu_2","textTraditional":"五月丙寅，葬長陵。〔一〕已下，〔二〕皇太子群臣皆反至太上皇廟。群臣曰：「帝起細微，撥亂世反之正，〔三〕平定天下，為漢太祖，功最高。」上尊號曰高皇帝。〔四〕","sentenceOrder":279},
  {"id":"s_work_han_thu_2_280","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　臣瓚曰：「自崩至葬凡二十三日。長陵在長安北四十里。」","sentenceOrder":280},
  {"id":"s_work_han_thu_2_281","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　蘇林曰：「下音下書之下。」鄭氏曰：「已下棺也。」師古曰：「蘇音鄭說是也。下音胡亞反。」","sentenceOrder":281},
  {"id":"s_work_han_thu_2_282","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　師古曰：「反，還也，還之於正道。」","sentenceOrder":282},
  {"id":"s_work_han_thu_2_283","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　師古曰：「尊號，諡也。」","sentenceOrder":283},
  {"id":"s_work_han_thu_2_284","chapterId":"ch_work_han_thu_2","textTraditional":"初，高祖不脩文學，而性明達，好謀，能聽，自監門戍卒，見之如舊。初順民心作三章之約。天下既定，命蕭何次律令，韓信申軍法，張蒼定章程，〔一〕叔孫通制禮儀，陸賈造新語。又與功臣剖符作誓，〔二〕丹書鐵契，金匱石室，〔三〕藏之宗廟。雖日不暇給，規摹弘遠矣。〔四〕","sentenceOrder":284},
  {"id":"s_work_han_thu_2_285","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　如淳曰：「章，曆數之章術也。程者，權衡丈尺斗斛之平法也。」師古曰：「程，法式也。」","sentenceOrder":285},
  {"id":"s_work_han_thu_2_286","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　如淳曰：「謂功臣表誓『使河如帶，泰山若厲，國乃滅絕』。」","sentenceOrder":286},
  {"id":"s_work_han_thu_2_287","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　如淳曰：「金匱，猶金縢也。」師古曰：「以金為匱，以石為室，重緘封之，保慎之義。」","sentenceOrder":287},
  {"id":"s_work_han_thu_2_288","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　鄧展曰：「若畫工規模物之摹。」韋昭曰：「正員之器曰規。摹者，如畫工未施采事摹之矣。」師古曰：「取喻規摹，謂立制垂範也。給，足也。日不暇足，言眾事繁多，常汲汲也。」","sentenceOrder":288},
  {"id":"s_work_han_thu_2_289","chapterId":"ch_work_han_thu_2","textTraditional":"贊曰：春秋晉史蔡墨有言，陶唐氏既衰，〔一〕其後有劉累，學擾龍，事孔甲，〔二〕范氏其後也。〔三〕而大夫范宣子亦曰：「祖自虞以上為陶唐氏，〔四〕在夏為御龍氏，〔五〕在商為豕韋氏〔六〕，在周為唐杜氏，〔七〕晉主夏盟為范氏。」范氏為晉士師，〔八〕魯文公世奔秦。〔九〕後歸于晉，其處者為劉氏。〔一０〕劉向云戰國時劉氏自秦獲於魏。〔一一〕秦滅魏，遷大梁，〔一二〕都于豐，故周巿說雍齒曰「豐，故梁徙也」。是以頌高祖云：「漢帝本系，出自唐帝。降及于周，在秦作劉。涉魏而東，遂為豐公。」〔一三〕豐公，蓋太上皇父。其遷日淺，墳墓在豐鮮焉。〔一四〕及高祖即位，置祠祀官，則有秦、晉、梁、荊之巫，〔一五〕世祠天地，綴之以祀，豈不信哉！〔一六〕由是推之，漢承堯運，德祚已盛，斷蛇著符，旗幟上赤，協于火德，自然之應，得天統矣。〔一七〕","sentenceOrder":289},
  {"id":"s_work_han_thu_2_290","chapterId":"ch_work_han_thu_2","textTraditional":"〔一〕　荀悅曰：「唐者，帝堯有天下號。陶，發聲也。」韋昭曰：「陶唐皆國名，猶湯稱殷商矣。」臣瓚曰：「堯初居於唐，後居陶，故曰陶唐也。」師古曰：「三家之說皆非也。許慎說文解字云：『陶，丘再成也，在濟陰。夏書曰東至陶丘。陶丘有堯城，堯嘗居之，後居於唐，故堯號陶唐氏。』斯得之矣。」","sentenceOrder":290},
  {"id":"s_work_han_thu_2_291","chapterId":"ch_work_han_thu_2","textTraditional":"〔二〕　應劭曰：「擾，馴也，能順養得其嗜欲也。孔甲，夏天子也。」師古曰：「擾音繞，又音饒。」","sentenceOrder":291},
  {"id":"s_work_han_thu_2_292","chapterId":"ch_work_han_thu_2","textTraditional":"〔三〕　師古曰：「晉司空士蒍之孫士會為晉大夫，食采於范，因號范氏。」","sentenceOrder":292},
  {"id":"s_work_han_thu_2_293","chapterId":"ch_work_han_thu_2","textTraditional":"〔四〕　師古曰：「范宣子即士會之孫士匄也。」","sentenceOrder":293},
  {"id":"s_work_han_thu_2_294","chapterId":"ch_work_han_thu_2","textTraditional":"〔五〕　師古曰：「即劉累也。」","sentenceOrder":294},
  {"id":"s_work_han_thu_2_295","chapterId":"ch_work_han_thu_2","textTraditional":"〔六〕　師古曰：「豕韋，國名，在東郡白馬縣東南。」","sentenceOrder":295},
  {"id":"s_work_han_thu_2_296","chapterId":"ch_work_han_thu_2","textTraditional":"〔七〕　師古曰：「唐、杜，二國名也。殷末豕韋徙國於唐，周成王滅唐，遷之於杜，為杜伯。杜伯之子隰叔奔晉。士會即隰叔之玄孫也。唐，太原晉陽縣也。杜，京兆杜縣也。」","sentenceOrder":296},
  {"id":"s_work_han_thu_2_297","chapterId":"ch_work_han_thu_2","textTraditional":"〔八〕　師古曰：「言晉為霸，主諸夏之盟，而范氏為晉正卿。」","sentenceOrder":297},
  {"id":"s_work_han_thu_2_298","chapterId":"ch_work_han_thu_2","textTraditional":"〔九〕　師古曰：「文公六年，晉襄公卒，士會與先蔑如秦逆公子雍，欲以為嗣。七年，以秦師納雍，而趙宣子立靈公，與秦師戰，敗之于刳首。先蔑奔秦，士會從之。」","sentenceOrder":298},
  {"id":"s_work_han_thu_2_299","chapterId":"ch_work_han_thu_2","textTraditional":"〔一０〕師古曰：「文十三年，晉人使魏壽餘偽以魏畔，誘士會而納之。秦之歸其帑，其別族留在秦者既無官邑，而乃復劉累之姓也。」","sentenceOrder":299},
  {"id":"s_work_han_thu_2_300","chapterId":"ch_work_han_thu_2","textTraditional":"〔一一〕文穎曰：「六國時，秦伐魏，劉氏隨軍為魏所獲，故得復居魏也。」師古曰：「春秋之後，周室卑微，諸侯彊盛，交相攻伐，故總謂之戰國。」","sentenceOrder":300},
  {"id":"s_work_han_thu_2_301","chapterId":"ch_work_han_thu_2","textTraditional":"〔一二〕師古曰：「秦昭王伐魏，魏惠王棄安邑，東徙大梁，更號曰梁，非始皇滅六國之時。」","sentenceOrder":301},
  {"id":"s_work_han_thu_2_302","chapterId":"ch_work_han_thu_2","textTraditional":"〔一三〕晉灼曰：「涉猶入也。」","sentenceOrder":302},
  {"id":"s_work_han_thu_2_303","chapterId":"ch_work_han_thu_2","textTraditional":"〔一四〕師古曰：「鮮，少也，音先淺反。」","sentenceOrder":303},
  {"id":"s_work_han_thu_2_304","chapterId":"ch_work_han_thu_2","textTraditional":"〔一五〕應劭曰：「先人所在之國，悉致祠巫祝，博求神靈之意也。」文穎曰：「巫，掌神之位次者也。范氏世仕於晉，故祠祀有晉巫。范會支庶，留秦為劉氏，故有秦巫。劉氏隨魏都大梁，故有梁巫。後徙豐，豐屬荊，故有荊巫也。」","sentenceOrder":304},
  {"id":"s_work_han_thu_2_305","chapterId":"ch_work_han_thu_2","textTraditional":"〔一六〕師古曰：「綴，言不絕也。」","sentenceOrder":305},
  {"id":"s_work_han_thu_2_306","chapterId":"ch_work_han_thu_2","textTraditional":"〔一七〕孟康曰：「十一月天統，物萌色赤，故云得天統也。」臣瓚曰：「漢承堯緒，為火德。秦承周後，以火代木，得天之統序，故曰得天統。漢初因秦正，至太初元年始用夏正，不用十一月為正也。」師古曰：「瓚說得之。」","sentenceOrder":306},
  {"id":"s_work_han_thu_2_307","chapterId":"ch_work_han_thu_2","textTraditional":"校勘記","sentenceOrder":307},
  {"id":"s_work_han_thu_2_308","chapterId":"ch_work_han_thu_2","textTraditional":"五０頁一四行　漢王為發（葬）〔喪〕，　景祐、汲古、殿本都作「喪」。王先謙說作「喪」是。","sentenceOrder":308},
  {"id":"s_work_han_thu_2_309","chapterId":"ch_work_han_thu_2","textTraditional":"五五頁一五行　有辨（說）〔訟〕及陳請者，　景祐、殿本都作「訟」。王先謙說作「訟」是。","sentenceOrder":309},
  {"id":"s_work_han_thu_2_310","chapterId":"ch_work_han_thu_2","textTraditional":"六一頁　七行　丹（楊）〔陽〕　景祐、殿本都作「陽」。","sentenceOrder":310},
  {"id":"s_work_han_thu_2_311","chapterId":"ch_work_han_thu_2","textTraditional":"六一頁一０行　上已封大功臣（三）〔二〕十餘人，　周壽昌說高帝功臣表六年正月以前封二十七人，合韓信二十八人，「三」是「二」之誤。王先謙說通鑑亦作「二十餘人」，此積畫傳寫之誤。","sentenceOrder":311},
  {"id":"s_work_han_thu_2_312","chapterId":"ch_work_han_thu_2","textTraditional":"六三頁　二行　（與）其將曼丘臣、王黃共立故趙後趙利為王，　朱子文說「與」字衍。王先謙說朱說是。","sentenceOrder":312},
  {"id":"s_work_han_thu_2_313","chapterId":"ch_work_han_thu_2","textTraditional":"六四頁　三行　（而）〔耏〕謂頰旁毛也。　景祐、殿本都作「耏」。按下句云「彡，毛髮貌也」，是釋「耏」字所從，則作「耏」是。","sentenceOrder":313},
  {"id":"s_work_han_thu_2_314","chapterId":"ch_work_han_thu_2","textTraditional":"六四頁　九行　置宗正（宮）〔官〕　景祐、殿、局本都作「官」。錢大昭說「宮」當作「官」。","sentenceOrder":314},
  {"id":"s_work_han_thu_2_315","chapterId":"ch_work_han_thu_2","textTraditional":"六五頁　九行　金布者，令篇（者）〔名〕，　景祐、汲古、殿、局本都作「名」。","sentenceOrder":315},
  {"id":"s_work_han_thu_2_316","chapterId":"ch_work_han_thu_2","textTraditional":"六五頁一四行　能堅守（也）〔者〕。　殿本作「者」。王先謙說作「者」是。","sentenceOrder":316},
  {"id":"s_work_han_thu_2_317","chapterId":"ch_work_han_thu_2","textTraditional":"六九頁一三行　購，設賞募也，〔音搆〕。　景祐、殿本都多「音搆」二字。","sentenceOrder":317},
  {"id":"s_work_han_thu_2_318","chapterId":"ch_work_han_thu_2","textTraditional":"七二頁一五行　太上皇思（上）欲歸豐，　殿、局本「上」作「土」。景祐本無此字。","sentenceOrder":318},
  {"id":"s_work_han_thu_2_319","chapterId":"ch_work_han_thu_2","textTraditional":"七三頁　七行　謂為之長（治）〔帥〕而治理之也。　景祐、殿、局本都作「帥」。王先謙說作「帥」是。","sentenceOrder":319},
  {"id":"s_work_han_thu_2_320","chapterId":"ch_work_han_thu_2","textTraditional":"七三頁一二行　上（見公）〔召見〕，　景祐、殿本都作「召見」。","sentenceOrder":320},
  {"id":"s_work_han_thu_2_321","chapterId":"ch_work_han_thu_2","textTraditional":"七四頁一０行　吾魂魄猶思（樂）沛。　景祐本無「樂」字。","sentenceOrder":321},
  {"id":"s_work_han_thu_2_322","chapterId":"ch_work_han_thu_2","textTraditional":"七九頁　一行　（不醫曰可治）　宋祁說舊本及越本並無「不醫曰可治」五字。王念孫說景祐本無五字是。","sentenceOrder":322},
  {"id":"s_work_han_thu_3_1","chapterId":"ch_work_han_thu_3","textTraditional":"孝惠皇帝，〔一〕高祖太子也，母曰呂皇后。帝年五歲，高祖初為漢王。二年，立為太子。十二年四月，高祖崩。五月丙寅，太子即皇帝位，尊皇后曰皇太后。賜民爵一級。〔二〕中郎、郎中滿六歲爵三級，四歲二級。〔三〕外郎滿六歲二級。〔四〕中郎不滿一歲一級。外郎不滿二歲賜錢萬。〔五〕宦官尚食比郎中。〔六〕謁者、執楯、執戟、武士、騶比外郎。〔七〕太子御驂乘賜爵五大夫，舍人滿五歲二級。〔八〕賜給喪事者，二千石錢二萬，六百石以上萬，五百石、二百石以下至佐史五千。〔九〕視作斥上者，將軍四十金，〔一０〕二千石二十金，六百石以上六金，五百石以下至佐史二金。減田租，復十五稅一。〔一一〕爵五大夫、吏六百石以上及宦皇帝而知名者有罪當盜械者，皆頌繫。〔一二〕上造以上及內外公孫耳孫有罪當刑及當為城旦舂者，皆耐為鬼薪白粲。〔一三〕民年七十以上若不滿十歲有罪當刑者，皆完之。〔一四〕又曰：「吏所以治民也，能盡其治則民賴之，故重其祿，所以為民也。〔一五〕今吏六百石以上父母妻子與同居，及故吏嘗佩將軍都尉印將兵及佩二千石官印者，家唯給軍賦，他無有所與。〔一六〕","sentenceOrder":1},
  {"id":"s_work_han_thu_3_2","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　荀悅曰：「諱盈之字曰滿。」應劭曰：「禮諡法『柔質慈民曰惠』。」師古曰：「孝子善述父之志，故漢家之諡，自惠帝巳下皆稱孝也。臣下以滿字代盈者，則知帝諱盈也。他皆類此。」","sentenceOrder":2},
  {"id":"s_work_han_thu_3_3","chapterId":"ch_work_han_thu_3","textTraditional":"〔二〕　師古曰：「帝初即位為恩惠也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_3_4","chapterId":"ch_work_han_thu_3","textTraditional":"〔三〕　蘇林曰：「中郎，省中郎也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_3_5","chapterId":"ch_work_han_thu_3","textTraditional":"〔四〕　蘇林曰：「外郎，散郎也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_3_6","chapterId":"ch_work_han_thu_3","textTraditional":"〔五〕　張晏曰：「不滿一歲，謂不滿四歲之一歲，作郎三歲也。不滿二歲，謂不滿六歲之二歲，作郎四歲也。」師古曰：「此說非也。直謂作郎未經一歲二歲耳。」","sentenceOrder":6},
  {"id":"s_work_han_thu_3_7","chapterId":"ch_work_han_thu_3","textTraditional":"〔六〕　應劭曰：「宦官，閽寺也。尚，主也。舊有五尚。尚冠、尚帳、尚衣、尚席亦是。」如淳曰：「主天子物曰尚，主文書曰尚書，又有尚符璽郎也。漢儀注省中有五尚，而內官婦人有諸尚也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_3_8","chapterId":"ch_work_han_thu_3","textTraditional":"〔七〕　應劭曰：「執楯、執戟，親近陛衛也。武士，力士也，高祖使武士縛韓信是也。騶，騶騎也。」師古曰：「騶本廄之馭者，後又令為騎，因謂騶騎耳。」","sentenceOrder":8},
  {"id":"s_work_han_thu_3_9","chapterId":"ch_work_han_thu_3","textTraditional":"〔八〕　師古曰：「武士、騶以上，皆舊侍從天子之人也。舍人以上，太子之官屬。」","sentenceOrder":9},
  {"id":"s_work_han_thu_3_10","chapterId":"ch_work_han_thu_3","textTraditional":"〔九〕　如淳曰：「律有斗食、佐史。」韋昭曰：「若今曹史書佐也。」師古曰：「自五百石以下至於佐史皆賜五千。今又言二百石者，審備其等也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_3_11","chapterId":"ch_work_han_thu_3","textTraditional":"〔一０〕服虔曰：「斥上，壙上也。」如淳曰：「斥，開也。開土地為冢壙，故以開斥言之。」鄭氏曰：「四十金，四十斤金也。」晉灼曰：「近上二千石賜錢二萬，此言四十金，實金也。下凡言黃金，真金也。不言黃，謂錢也。食貨志黃金一斤直萬錢。」師古曰：「諸賜言黃金者，皆與之金。不言黃者，一金與萬錢也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_3_12","chapterId":"ch_work_han_thu_3","textTraditional":"〔一一〕鄧展曰：「漢家初十五稅一，儉於周十稅一也。中間廢，今復之也。」如淳曰：「秦作阿房之宮，收太半之賦，遂行，至此乃復十五而稅一。」師古曰：「鄧說是也。復音房目反。」","sentenceOrder":12},
  {"id":"s_work_han_thu_3_13","chapterId":"ch_work_han_thu_3","textTraditional":"〔一二〕文穎曰：「言皇帝者，以別仕諸王國也。」張晏曰：「時諸侯治民，新承六國之後，咸慕鄉邑，或貪逸豫，樂仕諸侯，今特為京師作優裕法也。」如淳曰：「知名，謂宦人教帝書學，亦可表異者也。盜者逃也，恐其逃亡，故著械也。頌者容也，言見寬容，但處曹吏舍，不入（陛）〔狴〕牢也。」師古曰：「諸家之說皆非也。宦皇帝而知名者，謂雖非五大夫爵、六百石吏，而早事惠帝，特為所知，故亦優之，所以云及耳，非謂凡在京師異於諸王國，亦不必在於宦人教書學也。左官之律起自武帝，此時未有。禮記曰『宦學事師』，謂凡仕宦，非閹寺也。盜械者，凡以罪著械皆得稱焉，不必逃亡也。據山海經，貳負之臣、相柳之尸皆云盜械，其義是也。古者頌與容同。五大夫，第九爵也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_3_14","chapterId":"ch_work_han_thu_3","textTraditional":"〔一三〕應劭曰：「上造，爵滿十六者也。內外公孫謂王侯內外孫也。耳孫者，玄孫之子也，言去其曾高益遠，但耳聞之也。今以上造有功勞，內外孫有骨血屬〈女連〉，施德布惠，故事從其輕也。城旦者，旦起行治城；舂者，婦人不豫外徭，但舂作米：皆四歲刑也。今皆就鬼薪白粲。取薪給宗廟為鬼薪，坐擇米使正白為白粲，皆三歲刑也。」李斐曰：「耳孫，曾孫也。」張晏曰：「公孫，宗室侯王之孫也。」晉灼曰：「耳孫，玄孫之曾孫也，諸侯王表在八世。」師古曰：「上造，第二爵名也。內外公孫，國家宗室及外戚之孫也。耳孫，諸說不同。據平紀及諸侯王表說『梁孝王玄孫之（子）耳孫〔音〕』。耳音仍。又匈奴傳說握衍朐鞮單于，云『烏維單于耳孫』。以此參之，李云曾孫是也。然漢書諸處又皆云曾孫非一，不應雜兩稱而言。據爾雅『曾孫之子為玄孫，玄孫之子為來孫，來孫之子為昆孫，昆孫之子為仍孫』，從己而數，是為八葉，則與晉說相同。仍、耳聲相近，蓋一號也。但班氏唯存古名，而計其葉數則錯也。〈女連〉音連。」","sentenceOrder":14},
  {"id":"s_work_han_thu_3_15","chapterId":"ch_work_han_thu_3","textTraditional":"〔一四〕孟康曰：「不加肉刑髡{髟剔}也。」師古曰：「若，預及之言也。謂七十以上及不滿十歲以下，皆完之也。{髟剔}音他計反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_3_16","chapterId":"ch_work_han_thu_3","textTraditional":"〔一五〕師古曰：「為音于偽反。」","sentenceOrder":16},
  {"id":"s_work_han_thu_3_17","chapterId":"ch_work_han_thu_3","textTraditional":"〔一六〕師古曰：「同居，謂父母妻子之外若兄弟及兄弟之子等見與同居業者，若今言同籍及同財也。無有所與，與讀曰豫。」","sentenceOrder":17},
  {"id":"s_work_han_thu_3_18","chapterId":"ch_work_han_thu_3","textTraditional":"令郡諸侯王立高廟。〔一〕","sentenceOrder":18},
  {"id":"s_work_han_thu_3_19","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　師古曰：「諸郡及諸侯王國皆立廟也。今書本郡下或有國字者，流俗不曉妄加之。」","sentenceOrder":19},
  {"id":"s_work_han_thu_3_20","chapterId":"ch_work_han_thu_3","textTraditional":"元年冬十二月，趙隱王如意薨。民有罪，得買爵三十級以免死罪。〔一〕賜民爵，戶一級。","sentenceOrder":20},
  {"id":"s_work_han_thu_3_21","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　應劭曰：「一級直錢二千，凡為六萬，若今贖罪入三十疋縑矣。」師古曰：「令出買爵之錢以贖罪。」","sentenceOrder":21},
  {"id":"s_work_han_thu_3_22","chapterId":"ch_work_han_thu_3","textTraditional":"春正月，城長安。","sentenceOrder":22},
  {"id":"s_work_han_thu_3_23","chapterId":"ch_work_han_thu_3","textTraditional":"二年冬十月，齊悼惠王來朝，獻城陽郡以益魯元公主邑，尊公主為太后。〔一〕","sentenceOrder":23},
  {"id":"s_work_han_thu_3_24","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　如淳曰：「張敖子偃為魯王，故公主得為太后。」師古曰：「此說非也。蓋齊王憂不得脫，故從內史之言，請尊公主為齊太后，以母禮事之，用悅媚呂太后耳。若魯元以子為魯王，自合稱太后，何待齊王尊之乎？據張耳傳『高后元年魯元太后薨，後六年宣平侯敖薨，呂太后立敖子偃為王，以母為太后故也』，是則偃因母為齊王太后而得王，非母因偃乃為太后也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_3_25","chapterId":"ch_work_han_thu_3","textTraditional":"春正月癸酉，有兩龍見蘭陵家人井中，〔一〕乙亥夕而不見。隴西地震。","sentenceOrder":25},
  {"id":"s_work_han_thu_3_26","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　師古曰：「家人，言庶人之家。」","sentenceOrder":26},
  {"id":"s_work_han_thu_3_27","chapterId":"ch_work_han_thu_3","textTraditional":"夏旱。郃陽侯仲薨。〔一〕秋七月辛未，相國何薨。〔二〕","sentenceOrder":27},
  {"id":"s_work_han_thu_3_28","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　師古曰：「高帝之兄，吳王濞父也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_3_29","chapterId":"ch_work_han_thu_3","textTraditional":"〔二〕　師古曰：「蕭何也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_3_30","chapterId":"ch_work_han_thu_3","textTraditional":"三年春，發長安六百里內男女十四萬六千人城長安，三十日罷。〔一〕","sentenceOrder":30},
  {"id":"s_work_han_thu_3_31","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　鄭氏曰：「城一面，故速罷。」","sentenceOrder":31},
  {"id":"s_work_han_thu_3_32","chapterId":"ch_work_han_thu_3","textTraditional":"以宗室女為公主，嫁匈奴單于。","sentenceOrder":32},
  {"id":"s_work_han_thu_3_33","chapterId":"ch_work_han_thu_3","textTraditional":"夏五月，立閩越君搖為東海王。〔一〕","sentenceOrder":33},
  {"id":"s_work_han_thu_3_34","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　應劭曰：「搖，越王句踐之苗裔也，帥百越之兵助高祖，故封。東海，在吳郡東南濱海云。」師古曰：「即今泉州是其地。」","sentenceOrder":34},
  {"id":"s_work_han_thu_3_35","chapterId":"ch_work_han_thu_3","textTraditional":"六月，發諸侯王、列侯徒隸二萬人城長安。","sentenceOrder":35},
  {"id":"s_work_han_thu_3_36","chapterId":"ch_work_han_thu_3","textTraditional":"秋七月，都廄災。南越王趙佗稱臣奉貢。〔一〕","sentenceOrder":36},
  {"id":"s_work_han_thu_3_37","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　師古曰：「佗音徒何反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_3_38","chapterId":"ch_work_han_thu_3","textTraditional":"四年冬十月壬寅，立皇后張氏。〔一〕","sentenceOrder":38},
  {"id":"s_work_han_thu_3_39","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　師古曰：「張敖之女也。史記及漢書無名字，皇甫謐作帝王世紀皆為惠帝張后及孝文薄后已下別制名焉，至於薄父之徒亦立名字，何從而得之乎？雖欲示博聞，不知陷於穿鑿。」","sentenceOrder":39},
  {"id":"s_work_han_thu_3_40","chapterId":"ch_work_han_thu_3","textTraditional":"春正月，舉民孝弟力田者復其身。〔一〕","sentenceOrder":40},
  {"id":"s_work_han_thu_3_41","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　師古曰：「弟者，言能以順道事其兄也。弟音徒計力。復音方目反。」","sentenceOrder":41},
  {"id":"s_work_han_thu_3_42","chapterId":"ch_work_han_thu_3","textTraditional":"三月甲子，皇帝冠，赦天下。省法令妨吏民者；除挾書律。〔一〕長樂宮鴻臺災。宜陽雨血。","sentenceOrder":42},
  {"id":"s_work_han_thu_3_43","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　應劭曰：「挾，藏也。」張晏曰：「秦律敢有挾書者族。」","sentenceOrder":43},
  {"id":"s_work_han_thu_3_44","chapterId":"ch_work_han_thu_3","textTraditional":"秋七月乙亥，未央宮凌室災；〔一〕丙子，織室災。〔二〕","sentenceOrder":44},
  {"id":"s_work_han_thu_3_45","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　師古曰：「凌室，藏冰之室也。豳詩七月之篇曰『納于凌陰』。」","sentenceOrder":45},
  {"id":"s_work_han_thu_3_46","chapterId":"ch_work_han_thu_3","textTraditional":"〔二〕　師古曰：「主織作繒帛之處。」","sentenceOrder":46},
  {"id":"s_work_han_thu_3_47","chapterId":"ch_work_han_thu_3","textTraditional":"五年冬十月，靁；桃李華，棗實。","sentenceOrder":47},
  {"id":"s_work_han_thu_3_48","chapterId":"ch_work_han_thu_3","textTraditional":"春正月，復發長安六百里內男女十四萬五千人城長安，三十日罷。","sentenceOrder":48},
  {"id":"s_work_han_thu_3_49","chapterId":"ch_work_han_thu_3","textTraditional":"夏，大旱。","sentenceOrder":49},
  {"id":"s_work_han_thu_3_50","chapterId":"ch_work_han_thu_3","textTraditional":"秋八月己丑，相國參薨。〔一〕","sentenceOrder":50},
  {"id":"s_work_han_thu_3_51","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　師古曰：「曹參也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_3_52","chapterId":"ch_work_han_thu_3","textTraditional":"九月，長安城成。賜民爵，戶一級。〔一〕","sentenceOrder":52},
  {"id":"s_work_han_thu_3_53","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　師古曰：「家長受也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_3_54","chapterId":"ch_work_han_thu_3","textTraditional":"六年冬十月辛丑，齊王肥薨。","sentenceOrder":54},
  {"id":"s_work_han_thu_3_55","chapterId":"ch_work_han_thu_3","textTraditional":"令民得賣爵。女子年十五以上至三十不嫁，五算。〔一〕","sentenceOrder":55},
  {"id":"s_work_han_thu_3_56","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　應劭曰：「國語越王勾踐令國中女子年十七不嫁者父母有罪，欲人民繁息也。漢律人出一算，算百二十錢，唯賈人與奴婢倍算。今使五算，罪謫之也。」孟康曰：「或云復之也。」師古曰：「應說是。」","sentenceOrder":56},
  {"id":"s_work_han_thu_3_57","chapterId":"ch_work_han_thu_3","textTraditional":"夏六月，舞陽侯噲薨。〔一〕","sentenceOrder":57},
  {"id":"s_work_han_thu_3_58","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　師古曰：「樊噲也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_3_59","chapterId":"ch_work_han_thu_3","textTraditional":"起長安西巿，修敖倉。","sentenceOrder":59},
  {"id":"s_work_han_thu_3_60","chapterId":"ch_work_han_thu_3","textTraditional":"七年冬十月，發車騎、材官詣滎陽，〔一〕太尉灌嬰將。","sentenceOrder":60},
  {"id":"s_work_han_thu_3_61","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　師古曰：「車，常擬軍興者，若近代之戍車也。騎，常所養馬，并其人使行充騎，若今武馬及所養者主也。材官，解在高紀。」","sentenceOrder":61},
  {"id":"s_work_han_thu_3_62","chapterId":"ch_work_han_thu_3","textTraditional":"春正月辛丑朔，日有蝕之。夏五月丁卯，日有蝕之，既。〔一〕","sentenceOrder":62},
  {"id":"s_work_han_thu_3_63","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　師古曰：「既，盡也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_3_64","chapterId":"ch_work_han_thu_3","textTraditional":"秋八月戊寅，帝崩于未央宮。〔一〕九月辛丑，葬安陵。〔二〕","sentenceOrder":64},
  {"id":"s_work_han_thu_3_65","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　臣瓚曰：「帝年十七即位，即位七年，壽二十（四）〔三〕。」","sentenceOrder":65},
  {"id":"s_work_han_thu_3_66","chapterId":"ch_work_han_thu_3","textTraditional":"〔二〕　臣瓚曰：「自崩至葬凡二十四日。安陵在長安北三十五里。」師古曰：「三輔黃圖云去長陵十里。」","sentenceOrder":66},
  {"id":"s_work_han_thu_3_67","chapterId":"ch_work_han_thu_3","textTraditional":"贊曰：孝惠內修親親，外禮宰相，優寵齊悼、趙隱，恩敬篤矣。〔一〕聞叔孫通之諫則懼然，〔二〕納曹相國之對而心說，〔三〕可謂寬仁之主。遭呂太后虧損至德，〔四〕悲夫！","sentenceOrder":67},
  {"id":"s_work_han_thu_3_68","chapterId":"ch_work_han_thu_3","textTraditional":"〔一〕　師古曰：「篤，厚也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_3_69","chapterId":"ch_work_han_thu_3","textTraditional":"〔二〕　蘇林曰：「諫復道乘衣冠道也。」師古曰：「懼讀曰瞿。瞿然，失守貌，音居具反。」","sentenceOrder":69},
  {"id":"s_work_han_thu_3_70","chapterId":"ch_work_han_thu_3","textTraditional":"〔三〕　蘇林曰：「對修高帝制度、蕭何法也。」師古曰：「說讀曰悅。」","sentenceOrder":70},
  {"id":"s_work_han_thu_3_71","chapterId":"ch_work_han_thu_3","textTraditional":"〔四〕　師古曰：「謂殺趙王，戮戚夫人，因以憂疾不聽政而崩。」","sentenceOrder":71},
  {"id":"s_work_han_thu_3_72","chapterId":"ch_work_han_thu_3","textTraditional":"校勘記","sentenceOrder":72},
  {"id":"s_work_han_thu_3_73","chapterId":"ch_work_han_thu_3","textTraditional":"八七頁　六行　不入（陛）〔狴〕牢也。　殿、局本都作「狴」。王先謙說作「狴」是。","sentenceOrder":73},
  {"id":"s_work_han_thu_3_74","chapterId":"ch_work_han_thu_3","textTraditional":"八七頁一五行　梁孝王玄孫之（子）耳孫〔音〕。　景祐本無「子」字，有「音」字，與平紀文合。諸侯王表「王音以孝王玄孫之曾孫紹封」，故下文說「以此參之，李云曾孫是也」。","sentenceOrder":74},
  {"id":"s_work_han_thu_3_75","chapterId":"ch_work_han_thu_3","textTraditional":"九二頁　四行　壽二十（四）〔三〕。　史記集解引皇甫謐曰「帝以秦始皇三十七年生，崩時年二十三」。王先謙說瓚說誤。","sentenceOrder":75},
  {"id":"s_work_han_thu_4_1","chapterId":"ch_work_han_thu_4","textTraditional":"高皇后呂氏，〔一〕生惠帝。佐高祖定天下，父兄及高祖而侯者三人。〔二〕惠帝即位，尊呂后為太后。太后立帝姊魯元公主女為皇后，無子，取後宮美人子名之以為太子。惠帝崩，太子立為皇帝，年幼，太后臨朝稱制，〔三〕大赦天下。乃立兄子呂台、產、祿、台子通四人為王，〔四〕封諸呂六人為列侯。語在外戚傳。","sentenceOrder":1},
  {"id":"s_work_han_thu_4_2","chapterId":"ch_work_han_thu_4","textTraditional":"〔一〕　荀悅曰：「諱雉之字曰野雞。」應劭曰：「禮，婦人從夫諡，故稱高也。」師古曰：「呂后名雉，字娥姁，故臣下諱雉也。姁音許于反。」","sentenceOrder":2},
  {"id":"s_work_han_thu_4_3","chapterId":"ch_work_han_thu_4","textTraditional":"〔二〕　師古曰：「父謂臨泗侯呂公也。兄謂周呂侯澤、建成侯釋之。」","sentenceOrder":3},
  {"id":"s_work_han_thu_4_4","chapterId":"ch_work_han_thu_4","textTraditional":"〔三〕　師古曰：「天子之言一曰制書，二曰詔書。制書者，謂為制度之命也，非皇后所得稱。今呂太后臨朝行天子事，斷決萬機，故稱制詔。」","sentenceOrder":4},
  {"id":"s_work_han_thu_4_5","chapterId":"ch_work_han_thu_4","textTraditional":"〔四〕　蘇林曰：「台音胞胎。」","sentenceOrder":5},
  {"id":"s_work_han_thu_4_6","chapterId":"ch_work_han_thu_4","textTraditional":"元年春正月，詔曰：「前日孝惠皇帝言欲除三族罪、妖言令〔一〕，議未決而崩，今除之。」二月，賜民爵，戶一級。初置孝弟力田二千石者一人。〔二〕夏五月丙申，趙王宮叢臺災。〔三〕立孝惠後宮子強為淮陽王，〔四〕不疑為恆山王，〔五〕弘為襄城侯，朝為軹侯，〔六〕武為壺關侯。秋，桃李華。","sentenceOrder":6},
  {"id":"s_work_han_thu_4_7","chapterId":"ch_work_han_thu_4","textTraditional":"〔一〕　師古曰：「罪之重者戮及三族，過誤之語以為妖言，今謂重酷，皆除之。」","sentenceOrder":7},
  {"id":"s_work_han_thu_4_8","chapterId":"ch_work_han_thu_4","textTraditional":"〔二〕　師古曰：「特置孝弟力田官而尊其秩，欲以勸厲天下，令各敦行務本。」","sentenceOrder":8},
  {"id":"s_work_han_thu_4_9","chapterId":"ch_work_han_thu_4","textTraditional":"〔三〕　師古曰：「連聚非一，故名叢臺。蓋本六國時趙王故臺也，在邯鄲城中。」","sentenceOrder":9},
  {"id":"s_work_han_thu_4_10","chapterId":"ch_work_han_thu_4","textTraditional":"〔四〕　如淳曰：「外戚恩澤侯表曰皆呂氏子也，以孝惠子侯。」晉灼曰：「漢注名長。」韋昭曰：「今陳留郡。」","sentenceOrder":10},
  {"id":"s_work_han_thu_4_11","chapterId":"ch_work_han_thu_4","textTraditional":"〔五〕　如淳曰：「今常山也，因避文帝諱改曰常。」","sentenceOrder":11},
  {"id":"s_work_han_thu_4_12","chapterId":"ch_work_han_thu_4","textTraditional":"〔六〕　師古曰：「軹音只。」","sentenceOrder":12},
  {"id":"s_work_han_thu_4_13","chapterId":"ch_work_han_thu_4","textTraditional":"二年春，詔曰：「高皇帝匡飭天下，〔一〕諸有功者皆受分地為列侯，〔二〕萬民大安，莫不受休德。〔三〕朕思念至於久遠而功名不著，亡以尊大誼，施後世。今欲差次列侯功以定朝位，〔四〕臧于高廟，世世勿絕，嗣子各襲其功位。其與列侯議定奏之。」丞相臣平言：〔五〕「謹與絳侯臣勃、〔六〕曲周侯臣商、〔七〕潁陰侯臣嬰、〔八〕安國侯臣陵等議，〔九〕列侯幸得賜餐錢奉邑，〔一０〕陛下加惠，以功次定朝位，〔一一〕臣請臧高廟。」奏可。春正月乙卯，地震，羌道、〔一二〕武都道山崩。〔一三〕夏六月丙戌晦，日有蝕之。秋七月，恆山王不疑薨。行八銖錢。〔一四〕","sentenceOrder":13},
  {"id":"s_work_han_thu_4_14","chapterId":"ch_work_han_thu_4","textTraditional":"〔一〕　師古曰：「匡，正也。飭，整也。飭讀與敕同，其字從力。」","sentenceOrder":14},
  {"id":"s_work_han_thu_4_15","chapterId":"ch_work_han_thu_4","textTraditional":"〔二〕　師古曰：「分音扶問反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_4_16","chapterId":"ch_work_han_thu_4","textTraditional":"〔三〕　師古曰：「休，美也，音虛虯反。他皆類此。」","sentenceOrder":16},
  {"id":"s_work_han_thu_4_17","chapterId":"ch_work_han_thu_4","textTraditional":"〔四〕　師古曰：「以功之高下為先後之次。」","sentenceOrder":17},
  {"id":"s_work_han_thu_4_18","chapterId":"ch_work_han_thu_4","textTraditional":"〔五〕　師古曰：「陳平。」","sentenceOrder":18},
  {"id":"s_work_han_thu_4_19","chapterId":"ch_work_han_thu_4","textTraditional":"〔六〕　師古曰：「周勃。」","sentenceOrder":19},
  {"id":"s_work_han_thu_4_20","chapterId":"ch_work_han_thu_4","textTraditional":"〔七〕　師古曰：「酈商。」","sentenceOrder":20},
  {"id":"s_work_han_thu_4_21","chapterId":"ch_work_han_thu_4","textTraditional":"〔八〕　師古曰：「灌嬰。」","sentenceOrder":21},
  {"id":"s_work_han_thu_4_22","chapterId":"ch_work_han_thu_4","textTraditional":"〔九〕　師古曰：「王陵。」","sentenceOrder":22},
  {"id":"s_work_han_thu_4_23","chapterId":"ch_work_han_thu_4","textTraditional":"〔一０〕應劭曰：「餐與飡同。諸侯四時皆得賜餐錢。」文穎曰：「飡，邑中更名算錢，如今長吏食奉，自復媵錢，即租奉也。」韋昭曰：「熟食曰飡，酒肴曰錢，粟米曰奉。稅租奉祿，正所食也。四時得閒賜，是為飡錢。飡，小食也。」師古曰：「餐、飡同一字耳，音（于）〔千〕安反。飡，所謂吞食物也。餐錢，賜廚膳錢也。奉邑，本所食邑也。奉音扶用反。」","sentenceOrder":23},
  {"id":"s_work_han_thu_4_24","chapterId":"ch_work_han_thu_4","textTraditional":"〔一一〕如淳曰：「功大者位在上。功臣侯表有第一、第二之次。」","sentenceOrder":24},
  {"id":"s_work_han_thu_4_25","chapterId":"ch_work_han_thu_4","textTraditional":"〔一二〕服虔曰：「縣有夷蠻曰道。」師古曰：「羌道屬隴西郡。」","sentenceOrder":25},
  {"id":"s_work_han_thu_4_26","chapterId":"ch_work_han_thu_4","textTraditional":"〔一三〕師古曰：「武都道屬武都郡。」","sentenceOrder":26},
  {"id":"s_work_han_thu_4_27","chapterId":"ch_work_han_thu_4","textTraditional":"〔一四〕應劭曰：「本秦錢，質如周錢，文曰『半兩』，重如其文，即八銖也。漢以其太重，更鑄莢錢，今民間名榆莢錢是也。民患其太輕，至此復行八銖錢。」","sentenceOrder":27},
  {"id":"s_work_han_thu_4_28","chapterId":"ch_work_han_thu_4","textTraditional":"三年夏，江水、〔漢水〕溢，流民四千餘家。〔一〕秋，星晝見。","sentenceOrder":28},
  {"id":"s_work_han_thu_4_29","chapterId":"ch_work_han_thu_4","textTraditional":"〔一〕　師古曰：「水所漂沒也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_4_30","chapterId":"ch_work_han_thu_4","textTraditional":"四年夏，少帝自知非皇后子，出怨言，皇太后幽之永巷。〔一〕詔曰：「凡有天下治萬民者，蓋之如天，容之如地；上有驩心以使百姓，百姓欣然以事其上，驩欣交通而天下治。今皇帝疾久不已，乃失惑昏亂，不能繼嗣奉宗廟，守祭祀，不可屬天下。〔二〕其議代之。」群臣皆曰：「皇太后為天下計，所以安宗廟社稷甚深。頓首奉詔。」五月丙辰，立恆山王弘為皇帝。〔三〕","sentenceOrder":30},
  {"id":"s_work_han_thu_4_31","chapterId":"ch_work_han_thu_4","textTraditional":"〔一〕　如淳曰：「列女傳周宣姜后脫簪珥，待罪永巷，後改為掖庭。」師古曰：「永，長也。本謂宮中之長巷也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_4_32","chapterId":"ch_work_han_thu_4","textTraditional":"〔二〕　師古曰：「屬，委也，音之欲反。」","sentenceOrder":32},
  {"id":"s_work_han_thu_4_33","chapterId":"ch_work_han_thu_4","textTraditional":"〔三〕　晉灼曰：「史記惠帝元年，子不疑為常山王，子山為襄城侯。二年，常山王薨，即不疑也。以弟襄城侯山為常山王，更名義。丙辰，立常山王義為帝。義更名弘。漢書一之，書弘以為正也。」師古曰：「即元年所立弘為襄城侯者，晉說是也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_4_34","chapterId":"ch_work_han_thu_4","textTraditional":"五年春，南粵王尉佗自稱南武帝。〔一〕秋八月，淮陽王彊薨。九月，發河東、上黨騎屯北地。","sentenceOrder":34},
  {"id":"s_work_han_thu_4_35","chapterId":"ch_work_han_thu_4","textTraditional":"〔一〕　韋昭曰：「生以武為號，不稽古也。」師古曰：「此說非也。成湯曰『吾武甚』，因自號武王。佗言武帝亦猶是耳，何謂其不稽古乎？」","sentenceOrder":35},
  {"id":"s_work_han_thu_4_36","chapterId":"ch_work_han_thu_4","textTraditional":"六年春，星晝見。夏四月，赦天下。秩長陵令二千石。〔一〕六月，城長陵。〔二〕匈奴寇狄道，攻阿陽。〔三〕行五分錢。〔四〕","sentenceOrder":36},
  {"id":"s_work_han_thu_4_37","chapterId":"ch_work_han_thu_4","textTraditional":"〔一〕　應劭曰：「長陵，高祖陵，尊之，故增其令秩也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_4_38","chapterId":"ch_work_han_thu_4","textTraditional":"〔二〕　張晏曰：「起縣邑，故築城也。」師古曰：「此說非也。黃圖云長陵城周七里百八十步，因為殿垣，門四出，及便殿掖庭諸官寺皆在中。是即就陵為城，非止謂邑居也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_4_39","chapterId":"ch_work_han_thu_4","textTraditional":"〔三〕　師古曰：「狄道屬隴西。阿陽，天水之縣也。今流俗書本或作河陽者，非也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_4_40","chapterId":"ch_work_han_thu_4","textTraditional":"〔四〕　應劭曰：「所謂莢錢者。」","sentenceOrder":40},
  {"id":"s_work_han_thu_4_41","chapterId":"ch_work_han_thu_4","textTraditional":"七年冬十二月，匈奴寇狄道，略二千餘人。春正月丁丑，趙王友幽死于邸。己丑晦，日有蝕之，既。以梁王呂產為相國，趙王祿為上將軍。立營陵侯劉澤為琅邪王。夏五月辛未，詔曰：「昭靈夫人，太上皇妃也；武哀侯、〔一〕宣夫人，高皇帝兄姊也。〔二〕號諡不稱，其議尊號。」丞相臣平等請尊昭靈夫人曰昭靈后，武哀侯曰武哀王，宣夫人曰昭哀后。六月，趙王恢自殺。秋九月，燕王建薨。南越侵盜長沙，遣隆慮侯灶將兵擊之。〔三〕","sentenceOrder":41},
  {"id":"s_work_han_thu_4_42","chapterId":"ch_work_han_thu_4","textTraditional":"〔一〕　張晏曰：「高帝兄伯也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_4_43","chapterId":"ch_work_han_thu_4","textTraditional":"〔二〕　如淳曰：「皆追諡。」","sentenceOrder":43},
  {"id":"s_work_han_thu_4_44","chapterId":"ch_work_han_thu_4","textTraditional":"〔三〕　應劭曰：「灶姓周，高祖功臣也。隆慮，今林慮也，後避殤帝諱，故改之。」師古曰：「慮音廬。」","sentenceOrder":44},
  {"id":"s_work_han_thu_4_45","chapterId":"ch_work_han_thu_4","textTraditional":"八年春，封中謁者張釋卿為列侯。〔一〕諸中官、宦者令丞皆賜爵關內侯，食邑。〔二〕夏，江水、漢水溢，流萬餘家。","sentenceOrder":45},
  {"id":"s_work_han_thu_4_46","chapterId":"ch_work_han_thu_4","textTraditional":"〔一〕　孟康曰：「宦官也。」如淳曰：「百官表謁者掌賓贊受事。灌嬰為中謁者，後常以閹人為之。諸官加中者，多閹人也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_4_47","chapterId":"ch_work_han_thu_4","textTraditional":"〔二〕　如淳曰：「列侯出關就國，關內侯但爵耳。其有加（愚）〔異〕者，與之關內之邑，食其租稅。宣紀曰『德、武食邑』是也。」師古曰：「諸中官，凡閹人給事於中者皆是也。宦者令丞，宦者署之令丞。」","sentenceOrder":47},
  {"id":"s_work_han_thu_4_48","chapterId":"ch_work_han_thu_4","textTraditional":"秋七月辛巳，皇太后崩于未央宮。遺詔賜諸侯王各千金，將相列侯下至郎吏各有差。大赦天下。","sentenceOrder":48},
  {"id":"s_work_han_thu_4_49","chapterId":"ch_work_han_thu_4","textTraditional":"上將軍祿、相國產顓兵秉政，〔一〕自知背高皇帝約，〔二〕恐為大臣諸侯王所誅，因謀作亂。時齊悼惠王子朱虛侯章在京師，以祿女為婦，知其謀，乃使人告兄齊王，令發兵西。章欲與太尉勃、丞相平為內應，以誅諸呂。齊王遂發兵，又詐琅邪王澤發其國兵，并將而西。產、祿等遣大將軍灌嬰將兵擊之。嬰至滎陽，使人諭齊王與連和，待呂氏變而共誅之。〔三〕","sentenceOrder":49},
  {"id":"s_work_han_thu_4_50","chapterId":"ch_work_han_thu_4","textTraditional":"〔一〕　師古曰：「顓讀與專同。」","sentenceOrder":50},
  {"id":"s_work_han_thu_4_51","chapterId":"ch_work_han_thu_4","textTraditional":"〔二〕　師古曰：「非劉氏而王，非有功而侯。」","sentenceOrder":51},
  {"id":"s_work_han_thu_4_52","chapterId":"ch_work_han_thu_4","textTraditional":"〔三〕　師古曰：「變謂發動也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_4_53","chapterId":"ch_work_han_thu_4","textTraditional":"太尉勃與丞相平謀，以曲周侯酈商子寄與祿善，使人劫商令寄紿說祿〔一〕曰：「高帝與呂后共定天下，劉氏所立九王，呂氏所立三王，皆大臣之議。事（以）〔已〕布告諸侯王，諸侯王以為宜。今太后崩，帝少，足下不急之國守藩，〔二〕乃為上將將兵留此，為大臣諸侯所疑。何不速歸將軍印，以兵屬太尉，〔三〕請梁王亦歸相國印，與大臣盟而之國？齊兵必罷，大臣得安，足下高枕而王千里，此萬世之利也。」祿然其計，使人報產及諸呂老人。或以為不便，計猶豫〔四〕未有所決。祿信寄，與俱出遊，過其姑呂嬃。〔五〕嬃怒曰：「奴為將而棄軍，呂氏今無處矣！」〔六〕乃悉出珠玉寶器散堂下，曰：「無為它人守也！」","sentenceOrder":53},
  {"id":"s_work_han_thu_4_54","chapterId":"ch_work_han_thu_4","textTraditional":"〔一〕　師古曰：「紿，誑也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_4_55","chapterId":"ch_work_han_thu_4","textTraditional":"〔二〕　師古曰：「之，往也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_4_56","chapterId":"ch_work_han_thu_4","textTraditional":"〔三〕　師古曰：「屬音之欲反。」","sentenceOrder":56},
  {"id":"s_work_han_thu_4_57","chapterId":"ch_work_han_thu_4","textTraditional":"〔四〕　師古曰：「猶，獸名也。爾雅曰『猶如{鹿旨}，善登木』。此獸性多疑慮，常居山中，忽聞有聲，即恐有人且來害之，每豫上樹，久之無人，然後敢下，須臾又上。如此非一，故不決者稱猶豫焉。一曰隴西俗謂犬子為猶，犬隨人行，每豫在前，待人不得，又來迎候，故云猶豫也。{鹿旨}音几。」","sentenceOrder":57},
  {"id":"s_work_han_thu_4_58","chapterId":"ch_work_han_thu_4","textTraditional":"〔五〕　張晏曰：「嬃音須。」師古曰：「呂后妹。」","sentenceOrder":58},
  {"id":"s_work_han_thu_4_59","chapterId":"ch_work_han_thu_4","textTraditional":"〔六〕　師古曰：「言見誅滅，無處所也。處字或作類，言無種類也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_4_60","chapterId":"ch_work_han_thu_4","textTraditional":"八月庚申，平陽侯窋行御史大夫事，〔一〕見相國產計事。郎中令賈壽使從齊來，因數產〔二〕曰：「王不早之國，今雖欲行，尚可得邪？」具以灌嬰與齊楚合從狀告產。〔三〕平陽侯窋聞其語，馳告丞相平、太尉勃。勃欲入北軍，不得入。襄平侯紀通尚符節，〔四〕乃令持節矯內勃北軍。〔五〕勃復令酈寄、典客劉揭說祿，〔六〕曰：「帝使太尉守北軍，欲令足下之國，急歸將軍印辭去。不然，禍且起。」祿遂解印屬典客，〔七〕而以兵授太尉勃。勃入軍門，行令軍中曰：「為呂氏右袒，為劉氏左袒。」〔八〕軍皆左袒。勃遂將北軍。然尚有南軍，丞相平召朱虛侯章佐勃。勃令章監軍門，令平陽侯告衛尉，毋內相國產殿門。產不知祿已去北軍，入未央宮欲為亂。殿門弗內，徘徊往來。〔九〕平陽侯馳語太尉勃，勃尚恐不勝，未敢誦言誅之，〔一０〕乃謂朱虛侯章曰：「急入宮衛帝。」章從勃請卒千人，入未央宮掖門，〔一一〕見產廷中。日餔時，遂擊產。產走。天大風，從官亂，莫敢鬥者。逐產，殺之郎中府吏舍廁中。〔一二〕","sentenceOrder":60},
  {"id":"s_work_han_thu_4_61","chapterId":"ch_work_han_thu_4","textTraditional":"〔一〕　師古曰：「窋，曹參子也，音竹出反。」","sentenceOrder":61},
  {"id":"s_work_han_thu_4_62","chapterId":"ch_work_han_thu_4","textTraditional":"〔二〕　師古曰：「數，責之也，音數具反。」","sentenceOrder":62},
  {"id":"s_work_han_thu_4_63","chapterId":"ch_work_han_thu_4","textTraditional":"〔三〕　師古曰：「齊楚俱在山東，連兵西向，欲誅諸呂，亦猶六國為從以敵秦，故言合從也。從音子容反。」","sentenceOrder":63},
  {"id":"s_work_han_thu_4_64","chapterId":"ch_work_han_thu_4","textTraditional":"〔四〕　張晏曰：「紀通，信子也。尚，主也，今符節令也。」晉灼曰：「紀信焚死，不見其後。功臣表云紀通紀成之子，以成死事，故封侯。」師古曰：「晉說是也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_4_65","chapterId":"ch_work_han_thu_4","textTraditional":"〔五〕　師古曰：「矯，詐也，詐以天子之命也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_4_66","chapterId":"ch_work_han_thu_4","textTraditional":"〔六〕　應劭曰：「典客，今大鴻臚也。」師古曰：「揭音竭。」","sentenceOrder":66},
  {"id":"s_work_han_thu_4_67","chapterId":"ch_work_han_thu_4","textTraditional":"〔七〕　師古曰：「屬音之欲反。」","sentenceOrder":67},
  {"id":"s_work_han_thu_4_68","chapterId":"ch_work_han_thu_4","textTraditional":"〔八〕　師古曰：「袒，脫衣袖而肉袒也。左右者，偏脫其一耳。袒音徒旱反。」","sentenceOrder":68},
  {"id":"s_work_han_thu_4_69","chapterId":"ch_work_han_thu_4","textTraditional":"〔九〕　師古曰：「徘徊猶傍偟，不進之意也。徘音裴。」","sentenceOrder":69},
  {"id":"s_work_han_thu_4_70","chapterId":"ch_work_han_thu_4","textTraditional":"〔一０〕鄧展曰：「誦言，公言也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_4_71","chapterId":"ch_work_han_thu_4","textTraditional":"〔一一〕師古曰：「非正門而在兩旁，若人之臂掖也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_4_72","chapterId":"ch_work_han_thu_4","textTraditional":"〔一二〕如淳曰：「百官表郎中令掌宮殿門戶，故其府在宮中，後轉為光祿勳。」","sentenceOrder":72},
  {"id":"s_work_han_thu_4_73","chapterId":"ch_work_han_thu_4","textTraditional":"章已殺產，帝令謁者持節勞章。〔一〕章欲奪節，謁者不肯，章乃從與載，因節信馳斬長樂衛尉呂更始。〔二〕還入北軍，復報太尉勃。勃起拜賀章，曰：「所患獨產，今已誅，天下定矣。」辛酉，（殺）〔斬〕呂祿，笞殺呂嬃。分部悉捕諸呂男女，無少長皆斬之〔三〕。","sentenceOrder":73},
  {"id":"s_work_han_thu_4_74","chapterId":"ch_work_han_thu_4","textTraditional":"〔一〕　師古曰：「慰問之。」","sentenceOrder":74},
  {"id":"s_work_han_thu_4_75","chapterId":"ch_work_han_thu_4","textTraditional":"〔二〕　師古曰：「因謁者所持之節，用為信也。章與謁者同車，故為門者所信，得入長樂宮。」","sentenceOrder":75},
  {"id":"s_work_han_thu_4_76","chapterId":"ch_work_han_thu_4","textTraditional":"〔三〕　師古曰：「分音扶問反。」","sentenceOrder":76},
  {"id":"s_work_han_thu_4_77","chapterId":"ch_work_han_thu_4","textTraditional":"大臣相與陰謀，以為少帝及三弟為王者皆非孝惠子，復共誅之，尊立文帝。語在周勃、高五王傳。","sentenceOrder":77},
  {"id":"s_work_han_thu_4_78","chapterId":"ch_work_han_thu_4","textTraditional":"贊曰：孝惠、高后之時，海內得離戰國之苦，君臣俱欲無為，故惠帝拱己，〔一〕高后女主制政，不出房闥，〔二〕而天下晏然，刑罰罕用，民務稼穡，衣食滋殖。〔三〕","sentenceOrder":78},
  {"id":"s_work_han_thu_4_79","chapterId":"ch_work_han_thu_4","textTraditional":"〔一〕　師古曰：「垂拱而治。」","sentenceOrder":79},
  {"id":"s_work_han_thu_4_80","chapterId":"ch_work_han_thu_4","textTraditional":"〔二〕　師古曰：「闥，宮中小門，音他曷反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_4_81","chapterId":"ch_work_han_thu_4","textTraditional":"〔三〕　師古曰：「滋，益也。殖，生也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_4_82","chapterId":"ch_work_han_thu_4","textTraditional":"校勘記","sentenceOrder":82},
  {"id":"s_work_han_thu_4_83","chapterId":"ch_work_han_thu_4","textTraditional":"九七頁一三行　音（于）〔千〕安反。　景祐、殿本都作「千」。王先謙說作「千」是。","sentenceOrder":83},
  {"id":"s_work_han_thu_4_84","chapterId":"ch_work_han_thu_4","textTraditional":"九八頁　二行　江水、〔漢水〕溢。　錢大昭說「江水」下脫「漢水」二字。按景祐、殿本都有，通鑑亦有。","sentenceOrder":84},
  {"id":"s_work_han_thu_4_85","chapterId":"ch_work_han_thu_4","textTraditional":"一００頁一０行　其有加（愚）〔異〕者，　景祐、殿、局本都作「異」。王先謙說作「異」是。","sentenceOrder":85},
  {"id":"s_work_han_thu_4_86","chapterId":"ch_work_han_thu_4","textTraditional":"一０一頁　七行　事（以）〔已〕布告諸侯王，　景祐、汲古、殿、局本都作「已」。","sentenceOrder":86},
  {"id":"s_work_han_thu_4_87","chapterId":"ch_work_han_thu_4","textTraditional":"一０三頁一五行　（殺）〔斬〕呂祿，　景祐、殿本都作「斬」。","sentenceOrder":87},
  {"id":"s_work_han_thu_5_1","chapterId":"ch_work_han_thu_5","textTraditional":"孝文皇帝，〔一〕高祖中子也，母曰薄姬。〔二〕高祖十一年，誅陳豨，定代地，立為代王，都中都。十七年秋，高后崩，〔三〕諸呂謀為亂，欲危劉氏。丞相陳平、太尉周勃、朱虛侯劉章等共誅之，謀立代王。語在高后紀、高五王傳。","sentenceOrder":1},
  {"id":"s_work_han_thu_5_2","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　荀悅曰：「諱恒之字曰常。」應劭曰：「諡法『慈惠愛民曰文』。」","sentenceOrder":2},
  {"id":"s_work_han_thu_5_3","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　如淳曰：「姬音怡，眾妾之總稱。漢官儀曰姬妾數百，外戚傳亦曰幸姬戚夫人。」臣瓚曰：「漢秩祿令及茂陵書姬並內官也，秩比二千石，位次婕妤下，在八子上。」師古曰：「姬者，本周之姓，貴於眾國之女，所以婦人美號皆稱姬焉。故左氏傳曰：『雖有姬、姜，無棄蕉萃。』姜亦大國女也。後因總謂眾妾為姬。史記云『高祖居山東時好美姬』是也。若姬是官號，不應云幸姬戚夫人，且外戚傳備列后妃諸官，無姬職也。如云眾妾總稱，則近之。不當音怡，宜依字讀耳。瓚說謬也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_5_4","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　張晏曰：「代王之十七年也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_5_5","chapterId":"ch_work_han_thu_5","textTraditional":"大臣遂使人迎代王。郎中令張武等議，皆曰：「漢大臣皆故高帝時將，習兵事，多謀詐，其屬意非止此也，〔一〕特畏高帝、呂太后威耳。今已誅諸呂，新喋血京師，〔二〕以迎大王為名，實不可信。願稱疾無往，以觀其變。」中尉宋昌進曰：「群臣之議皆非也。夫秦失其政，豪傑並起，人人自以為得之者以萬數，然卒踐天子位者，劉氏也，〔三〕天下絕望，一矣。高帝王子弟，地犬牙相制，所謂盤石之宗也，〔四〕天下服其彊，二矣。漢興，除秦煩苛，約法令，施德惠，〔五〕人人自安，難動搖，三矣。夫以呂太后之嚴，立諸呂為三王，擅權專制，然而太尉以一節入北軍，一呼〔六〕士皆袒左，為劉氏，畔諸呂，卒以滅之。此乃天授，非人力也。今大臣雖欲為變，百姓弗為使，〔七〕其黨寧能專一邪？內有朱虛、東牟之親，外畏吳、楚、淮南、琅邪、齊、代之彊。方今高帝子獨淮南王與大王，大王又長，賢聖仁孝，聞於天下，故大臣因天下之心而欲迎立大王，大王勿疑也。」代王報太后，計猶豫未定。卜之，兆得大橫。〔八〕占曰：「大橫庚庚，余為天王，夏啟以光。」〔九〕代王曰：「寡人固已為王，又何王乎？」卜人曰：「所謂天王者，乃天子也。」於是代王乃遣太后弟薄昭見太尉勃，勃等具言所以迎立王者。〔一０〕昭還報曰：「信矣，無可疑者。」代王笑謂宋昌曰：「果如公言。」乃令宋昌驂乘，〔一一〕張武等六人乘六乘傳〔一二〕詣長安。至高陵止，而使宋昌先之長安觀變。","sentenceOrder":5},
  {"id":"s_work_han_thu_5_6","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「言常有異志也。屬意，猶言注意也。屬音之欲反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_5_7","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　服虔曰：「喋音蹀屣履之蹀。」如淳曰：「殺人流血滂沱為喋血。」師古曰：「喋音大頰反，本字當作蹀。蹀謂履涉之耳。」","sentenceOrder":7},
  {"id":"s_work_han_thu_5_8","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　師古曰：「卒，終也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_5_9","chapterId":"ch_work_han_thu_5","textTraditional":"〔四〕　師古曰：「犬牙，言地形如犬之牙交相入也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_5_10","chapterId":"ch_work_han_thu_5","textTraditional":"〔五〕　師古曰：「約，省也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_5_11","chapterId":"ch_work_han_thu_5","textTraditional":"〔六〕　師古曰：「呼，叫也，音火故反。他皆類此。」","sentenceOrder":11},
  {"id":"s_work_han_thu_5_12","chapterId":"ch_work_han_thu_5","textTraditional":"〔七〕　師古曰：「為音于偽反。」","sentenceOrder":12},
  {"id":"s_work_han_thu_5_13","chapterId":"ch_work_han_thu_5","textTraditional":"〔八〕　應劭曰：「龜曰兆，筮曰卦。卜以荊灼龜，文正橫也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_5_14","chapterId":"ch_work_han_thu_5","textTraditional":"〔九〕　服虔曰：「庚庚，橫貌也。」李奇曰：「庚庚，其繇文也。占謂其繇也。」張晏曰：「先是五帝官天下，老則嬗賢，至夏啟始傳嗣，能光先君之業。文帝亦襲父跡，言似啟也。」師古曰：「繇音丈救反，本作籀。籀，書也，謂讀卜詞。」","sentenceOrder":14},
  {"id":"s_work_han_thu_5_15","chapterId":"ch_work_han_thu_5","textTraditional":"〔一０〕師古曰：「說所以迎代王之意也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_5_16","chapterId":"ch_work_han_thu_5","textTraditional":"〔一一〕師古曰：「乘車之法，尊者居左，御者居中，又有一人處車之右，以備傾側。是以戎事則稱車右，其餘則曰驂乘。驂者，三也，蓋取三人為名義耳。」","sentenceOrder":16},
  {"id":"s_work_han_thu_5_17","chapterId":"ch_work_han_thu_5","textTraditional":"〔一二〕張晏曰：「傳車六乘也。」師古曰：「傳音張戀反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_5_18","chapterId":"ch_work_han_thu_5","textTraditional":"昌至渭橋，〔一〕丞相已下皆迎。昌還報，代王乃進至渭橋。群臣拜謁稱臣，代王下拜。太尉勃進曰：「願請間。」〔二〕宋昌曰：「所言公，公言之；所言私，王者無私。」太尉勃乃跪上天子璽。代王謝曰：「至邸而議之。」〔三〕","sentenceOrder":18},
  {"id":"s_work_han_thu_5_19","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　蘇林曰：「在長安北三里。」","sentenceOrder":19},
  {"id":"s_work_han_thu_5_20","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　師古曰：「間，容也，猶今言中間也。請容暇之頃，當有所陳，不欲於眾顯論也。他皆類此。」","sentenceOrder":20},
  {"id":"s_work_han_thu_5_21","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　師古曰：「郡國朝宿之舍，在京師者率名邸。邸，至也，言所歸至也，音丁禮反。他皆類此。」","sentenceOrder":21},
  {"id":"s_work_han_thu_5_22","chapterId":"ch_work_han_thu_5","textTraditional":"閏月己酉，入代邸。群臣從至，上議曰：「丞相臣平、太尉臣勃、大將軍臣武、〔一〕御史大夫臣蒼、〔二〕宗正臣郢、〔三〕朱虛侯臣章、東牟侯臣興居、典客臣揭〔四〕再拜言大王足下：子弘等皆非孝惠皇帝子，〔五〕不當奉宗廟。臣謹請陰安侯、〔六〕頃王后、〔七〕琅邪王、〔八〕列侯、吏二千石議，大王高皇帝子，宜為嗣。願大王即天子位。」代王曰：「奉高帝宗廟，重事也。寡人不佞〔九〕，不足以稱。〔一０〕願請楚王計宜者，〔一一〕寡人弗敢當。」群臣皆伏，固請。代王西鄉讓者三，南鄉讓者再。〔一二〕丞相平等皆曰：「臣伏計之，大王奉高祖宗廟最宜稱，雖天下諸侯萬民皆以為宜。臣等為宗廟社稷計，不敢忽。〔一三〕願大王幸聽臣等。臣謹奉天子璽符再拜上。」代王曰：「宗室將相王列侯以為（其）〔莫〕宜寡人，寡人不敢辭。」遂即天子位。群臣以次侍。〔一四〕使太僕嬰、東牟侯興居先清宮，〔一五〕奉天子法駕迎代邸。〔一六〕皇帝即日夕入未央宮。夜拜宋昌為衛將軍，領南北軍，張武為郎中令，行殿中。〔一七〕還坐前殿，下詔曰：「制詔丞相、太尉、御史大夫：間者諸呂用事擅權，〔一八〕謀為大逆，欲危劉氏宗廟，賴將相列侯宗室大臣誅之，皆伏其辜。朕初即位，其赦天下，賜民爵一級，女子百戶牛酒，〔一九〕酺五日。」〔二０〕","sentenceOrder":22},
  {"id":"s_work_han_thu_5_23","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　服虔曰：「柴武。」","sentenceOrder":23},
  {"id":"s_work_han_thu_5_24","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　文穎曰：「張蒼。」","sentenceOrder":24},
  {"id":"s_work_han_thu_5_25","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　文穎曰：「劉郢。」","sentenceOrder":25},
  {"id":"s_work_han_thu_5_26","chapterId":"ch_work_han_thu_5","textTraditional":"〔四〕　蘇林曰：「劉揭也。」師古曰：「揭音竭。」","sentenceOrder":26},
  {"id":"s_work_han_thu_5_27","chapterId":"ch_work_han_thu_5","textTraditional":"〔五〕　師古曰：「不詳其有爵位，故總謂之子。」","sentenceOrder":27},
  {"id":"s_work_han_thu_5_28","chapterId":"ch_work_han_thu_5","textTraditional":"〔六〕　蘇林曰：「高帝兄伯妻，羹頡侯母，丘嫂也。」晉灼曰：「若蕭何夫人封為酇侯也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_5_29","chapterId":"ch_work_han_thu_5","textTraditional":"〔七〕　蘇林曰：「高帝兄仲妻也。仲名喜，為代王，後廢為郃陽侯。子濞為吳王，故追諡為頃王。」如淳曰：「王子侯表曰合陽侯喜以子濞為王，追諡為頃王。頃王后封陰安侯，時呂嬃為林光侯，蕭何夫人亦為酇侯。又宗室侯表此時無陰安侯，知其為頃王后也。案漢祠令，陰安侯高帝嫂也。」師古曰：「諸諡為傾者，漢書例作頃字，讀皆曰傾。」","sentenceOrder":29},
  {"id":"s_work_han_thu_5_30","chapterId":"ch_work_han_thu_5","textTraditional":"〔八〕　文穎曰：「劉澤也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_5_31","chapterId":"ch_work_han_thu_5","textTraditional":"〔九〕　師古曰：「不佞，不材也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_5_32","chapterId":"ch_work_han_thu_5","textTraditional":"〔一０〕師古曰：「稱，副也，音尺孕反。其下皆同。」","sentenceOrder":32},
  {"id":"s_work_han_thu_5_33","chapterId":"ch_work_han_thu_5","textTraditional":"〔一一〕蘇林曰：「楚王名交，高帝弟也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_5_34","chapterId":"ch_work_han_thu_5","textTraditional":"〔一二〕如淳曰：「讓群臣也。或曰賓主位東西面，君臣位南北面，故西鄉坐三讓不受，群臣猶稱宜，乃更南鄉坐，示變即君位之漸也。」師古曰：「鄉讀曰嚮。」","sentenceOrder":34},
  {"id":"s_work_han_thu_5_35","chapterId":"ch_work_han_thu_5","textTraditional":"〔一三〕師古曰：「忽，怠忘也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_5_36","chapterId":"ch_work_han_thu_5","textTraditional":"〔一四〕師古曰：「各依職位。」","sentenceOrder":36},
  {"id":"s_work_han_thu_5_37","chapterId":"ch_work_han_thu_5","textTraditional":"〔一五〕應劭曰：「舊典，天子行幸所至，必遣靜室令先案行清淨殿中，以虞非常。」","sentenceOrder":37},
  {"id":"s_work_han_thu_5_38","chapterId":"ch_work_han_thu_5","textTraditional":"〔一六〕如淳曰：「法駕者，侍中驂乘，奉車郎御，屬車三十六乘。」","sentenceOrder":38},
  {"id":"s_work_han_thu_5_39","chapterId":"ch_work_han_thu_5","textTraditional":"〔一七〕師古曰：「行謂案行也，音下更反。」","sentenceOrder":39},
  {"id":"s_work_han_thu_5_40","chapterId":"ch_work_han_thu_5","textTraditional":"〔一八〕師古曰：「間者，猶言中間之時也。他皆倣此。」","sentenceOrder":40},
  {"id":"s_work_han_thu_5_41","chapterId":"ch_work_han_thu_5","textTraditional":"〔一九〕蘇林曰：「男賜爵，女子賜牛酒。」師古曰：「賜爵者，謂一家之長得之也。女子謂賜爵者之妻也。率百戶共得牛若干頭，酒若干石，無定數也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_5_42","chapterId":"ch_work_han_thu_5","textTraditional":"〔二０〕服虔曰：「酺音蒲。」文穎曰：「音步。漢律，三人以上無故群飲酒，罰金四兩，今詔橫賜得令會聚飲食五日也。」師古曰：「酺之為言布也，王德布於天下而合聚飲食為酺。服音是也。字或作脯，音義同。」","sentenceOrder":42},
  {"id":"s_work_han_thu_5_43","chapterId":"ch_work_han_thu_5","textTraditional":"元年冬十月辛亥，皇帝見于高廟。遣車騎將軍薄昭迎皇太后于代。詔曰：「前呂產自置為相國，呂祿為上將軍，擅遣將軍灌嬰將兵擊齊，欲代劉氏。嬰留滎陽，與諸侯合謀以誅呂氏。呂產欲為不善，丞相平與太尉勃等謀奪產等軍。朱虛侯章首先捕斬產。太尉勃身率襄平侯通持節承詔入北軍。典客揭奪呂祿印。其益封太尉勃邑萬戶，賜金五千斤。丞相平、將軍嬰邑各三千戶，金二千斤。朱虛侯章、襄平侯通邑各二千戶，金千斤。封典客揭為陽信侯，賜金千斤。」","sentenceOrder":43},
  {"id":"s_work_han_thu_5_44","chapterId":"ch_work_han_thu_5","textTraditional":"十二月，立趙幽王子遂為趙王，徙琅邪王澤為燕王。呂氏所奪齊楚地皆歸之。盡除收帑相坐律令。〔一〕","sentenceOrder":44},
  {"id":"s_work_han_thu_5_45","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　應劭曰：「帑，子也。秦法，一人有罪，并其室家。今除此律。」師古曰：「帑讀與奴同，假借字也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_5_46","chapterId":"ch_work_han_thu_5","textTraditional":"正月，有司請蚤建太子，〔一〕所以尊宗廟也。詔曰：「朕既不德，上帝神明未歆饗也，天下人民未有{匧心}志。〔二〕今縱不能博求天下賢聖有德之人而嬗天下焉，〔三〕而曰豫建太子，是重吾不德也。〔四〕謂天下何？〔五〕其安之。」〔六〕有司曰：「豫建太子，所以重宗廟社稷，不忘天下也。」上曰：「楚王，季父也，春秋高，閱天下之義理多矣，〔七〕明於國家之體。吳王於朕，兄也；淮南王，弟也：皆秉德以陪朕，〔八〕豈為不豫哉！諸侯王宗室昆弟有功臣，多賢及有德義者，若舉有德以陪朕之不能終，是社稷之靈，天下之福也。今不選舉焉，而曰必子，〔九〕人其以朕為忘賢有德者而專於子，非所以憂天下也。朕甚不取。」〔一０〕有司固請曰：「古者殷周有國，治安皆且千歲，〔一一〕有天下者莫長焉，〔一二〕用此道也。〔一三〕立嗣必子，所從來遠矣。高帝始平天下，建諸侯，為帝者太祖。諸侯王列侯始受國者亦皆為其國祖。子孫繼嗣，世世不絕，天下之大義也。故高帝設之以撫海內。〔一四〕今釋宜建〔一五〕而更選於諸侯宗室，非高帝之志也。更議不宜。〔一六〕子啟最長，〔一七〕敦厚慈仁，請建以為太子。」上乃許之。因賜天下民當為父後者爵一級。〔一八〕封將軍薄昭為軹侯。〔一九〕","sentenceOrder":46},
  {"id":"s_work_han_thu_5_47","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「蚤，古以為早晚字也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_5_48","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　應劭曰：「{匧心}音篋。{匧心}，滿也。」師古曰：「{匧心}，快也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_5_49","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　晉灼曰：「嬗，古禪字。」","sentenceOrder":49},
  {"id":"s_work_han_thu_5_50","chapterId":"ch_work_han_thu_5","textTraditional":"〔四〕　師古曰：「重謂增益也，音直用反。他皆類此。」","sentenceOrder":50},
  {"id":"s_work_han_thu_5_51","chapterId":"ch_work_han_thu_5","textTraditional":"〔五〕　師古曰：「猶言何以稱天下之望。」","sentenceOrder":51},
  {"id":"s_work_han_thu_5_52","chapterId":"ch_work_han_thu_5","textTraditional":"〔六〕　師古曰：「安猶徐也，言不宜汲汲耳。」","sentenceOrder":52},
  {"id":"s_work_han_thu_5_53","chapterId":"ch_work_han_thu_5","textTraditional":"〔七〕　如淳曰：「閱猶更歷也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_5_54","chapterId":"ch_work_han_thu_5","textTraditional":"〔八〕　文穎曰：「陪，輔也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_5_55","chapterId":"ch_work_han_thu_5","textTraditional":"〔九〕　師古曰：「必將傳位於子。」","sentenceOrder":55},
  {"id":"s_work_han_thu_5_56","chapterId":"ch_work_han_thu_5","textTraditional":"〔一０〕師古曰：「不取，猶言不用此為善也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_5_57","chapterId":"ch_work_han_thu_5","textTraditional":"〔一一〕師古曰：「治安，言治理而且安寧也。治音丈吏反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_5_58","chapterId":"ch_work_han_thu_5","textTraditional":"〔一二〕師古曰：「言上古以來，國祚長久，無及殷周者也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_5_59","chapterId":"ch_work_han_thu_5","textTraditional":"〔一三〕師古曰：「所以能爾者，以承嗣相傳故也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_5_60","chapterId":"ch_work_han_thu_5","textTraditional":"〔一四〕師古曰：「設，置立也，謂立此法也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_5_61","chapterId":"ch_work_han_thu_5","textTraditional":"〔一五〕師古曰：「釋，捨也。宜建，謂適嗣。」","sentenceOrder":61},
  {"id":"s_work_han_thu_5_62","chapterId":"ch_work_han_thu_5","textTraditional":"〔一六〕師古曰：「不當更議。」","sentenceOrder":62},
  {"id":"s_work_han_thu_5_63","chapterId":"ch_work_han_thu_5","textTraditional":"〔一七〕文穎曰：「景帝名。」","sentenceOrder":63},
  {"id":"s_work_han_thu_5_64","chapterId":"ch_work_han_thu_5","textTraditional":"〔一八〕師古曰：「雖非己生正嫡，但為後者即得賜爵。」","sentenceOrder":64},
  {"id":"s_work_han_thu_5_65","chapterId":"ch_work_han_thu_5","textTraditional":"〔一九〕師古曰：「軹音只。」","sentenceOrder":65},
  {"id":"s_work_han_thu_5_66","chapterId":"ch_work_han_thu_5","textTraditional":"三月，有司請立皇后。皇太后曰：「立太子母竇氏為皇后。」","sentenceOrder":66},
  {"id":"s_work_han_thu_5_67","chapterId":"ch_work_han_thu_5","textTraditional":"詔曰：「方春和時，草木群生之物皆有以自樂，而吾百姓鰥寡孤獨窮困之人或阽於死亡，〔一〕而莫之省憂。〔二〕為民父母將何如？其議所以振貸之。」〔三〕又曰：「老者非帛不煖，非肉不飽〔四〕。今歲首，不時使人存問長老，〔五〕又無布帛酒肉之賜，將何以佐天下子孫孝養其親？今聞吏稟當受鬻者，或以陳粟，〔六〕豈稱養老之意哉！具為令。」〔七〕有司請令縣道，〔八〕年八十已上，賜米人月一石，肉二十斤，酒五斗。其九十已上，又賜帛人二疋，絮三斤。〔九〕賜物及當稟鬻米者，長吏閱視，丞若尉致。〔一０〕不滿九十，嗇夫、令史致。二千石遣都吏循行，〔一一〕不稱者督之〔一二〕。刑者及有罪耐以上，不用此令。〔一三〕","sentenceOrder":67},
  {"id":"s_work_han_thu_5_68","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　服虔曰：「阽音反坫之坫。」孟康曰：「阽音屋檐之檐。」如淳曰：「阽，近邊欲墮之意。」師古曰：「服、孟二音並通。」","sentenceOrder":68},
  {"id":"s_work_han_thu_5_69","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　師古曰：「省，視也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_5_70","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　師古曰：「振，起也，為給貸之，令其存立也。諸振救、振贍，其義皆同。今流俗作字從貝者非也，自別有訓。貸音吐戴反。」","sentenceOrder":70},
  {"id":"s_work_han_thu_5_71","chapterId":"ch_work_han_thu_5","textTraditional":"〔四〕　師古曰：「煖，溫也，音乃短反。」","sentenceOrder":71},
  {"id":"s_work_han_thu_5_72","chapterId":"ch_work_han_thu_5","textTraditional":"〔五〕　師古曰：「存，省視也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_5_73","chapterId":"ch_work_han_thu_5","textTraditional":"〔六〕　師古曰：「稟，給也。鬻，淖糜也。給米使為糜鬻也。陳，久舊也。小雅甫田之詩曰『我取其陳』。鬻音之六反。淖，溺也，音女教反。」","sentenceOrder":73},
  {"id":"s_work_han_thu_5_74","chapterId":"ch_work_han_thu_5","textTraditional":"〔七〕　師古曰：「使其備為條制。」","sentenceOrder":74},
  {"id":"s_work_han_thu_5_75","chapterId":"ch_work_han_thu_5","textTraditional":"〔八〕　師古曰：「或縣或道，皆用此制也。有蠻夷曰道。」","sentenceOrder":75},
  {"id":"s_work_han_thu_5_76","chapterId":"ch_work_han_thu_5","textTraditional":"〔九〕　師古曰：「絮，綿也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_5_77","chapterId":"ch_work_han_thu_5","textTraditional":"〔一０〕師古曰：「長吏，縣之令長也。若者，豫及之詞。致者，送至也。或丞或尉，自致之也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_5_78","chapterId":"ch_work_han_thu_5","textTraditional":"〔一一〕蘇林曰：「取其都吏有德也。」如淳曰：「律說，都吏今督郵是也。閑惠曉事，即為文無害都吏。」師古曰：「如說是也。行音下孟反。」","sentenceOrder":78},
  {"id":"s_work_han_thu_5_79","chapterId":"ch_work_han_thu_5","textTraditional":"〔一二〕師古曰：「循行有不如詔意者，二千石察視責罰之。」","sentenceOrder":79},
  {"id":"s_work_han_thu_5_80","chapterId":"ch_work_han_thu_5","textTraditional":"〔一三〕蘇林曰：「一歲為罰作，二歲刑以上為耐。耐，能任其罪也。」師古曰：「刑謂先被刑也。有罪，在吏未決者也。言八十、九十之人雖合加賜，其中有被刑罪者，不在此賜物令條中也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_5_81","chapterId":"ch_work_han_thu_5","textTraditional":"楚元王交薨。","sentenceOrder":81},
  {"id":"s_work_han_thu_5_82","chapterId":"ch_work_han_thu_5","textTraditional":"四月，齊楚地震，二十九山同日崩，大水潰出。〔一〕","sentenceOrder":82},
  {"id":"s_work_han_thu_5_83","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「旁決曰潰，上湧曰出。」","sentenceOrder":83},
  {"id":"s_work_han_thu_5_84","chapterId":"ch_work_han_thu_5","textTraditional":"六月，令郡國無來獻。施惠天下，諸侯四夷遠近驩洽。乃脩代來功。〔一〕詔曰：「方大臣誅諸呂迎朕，朕狐疑，皆止朕，〔二〕唯中尉宋昌勸朕，朕（已）〔以〕得保宗廟。已尊昌為衛將軍，〔三〕其封昌為壯武侯。諸從朕六人，官皆至九卿。」〔四〕又曰：「列侯從高帝入蜀漢者六十八人益邑各三百戶。吏二千石以上從高帝潁川守尊等十人食邑六百戶，淮陽守申屠嘉等十人五百戶，衛尉足等十人四百戶。」封淮南王舅趙兼為周陽侯，齊王舅駟鈞為靖郭侯，〔五〕故常山丞相蔡兼為樊侯。","sentenceOrder":84},
  {"id":"s_work_han_thu_5_85","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「自代來時有功者。」","sentenceOrder":85},
  {"id":"s_work_han_thu_5_86","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　師古曰：「狐之為獸，其性多疑，每渡冰河，且聽且渡。故言疑者，而稱狐疑。」","sentenceOrder":86},
  {"id":"s_work_han_thu_5_87","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　師古曰：「尊，高也，高其官秩。」","sentenceOrder":87},
  {"id":"s_work_han_thu_5_88","chapterId":"ch_work_han_thu_5","textTraditional":"〔四〕　師古曰：「張武等。」","sentenceOrder":88},
  {"id":"s_work_han_thu_5_89","chapterId":"ch_work_han_thu_5","textTraditional":"〔五〕　如淳曰：「邑名也，六國時齊有靖郭君。靖音靜。」師古曰：「外戚恩澤侯表云鄔侯駟鈞以齊王舅侯，今此云靖郭，豈初封靖郭後改為鄔乎？鄔音一戶反，又音於（度）〔庶〕反。」","sentenceOrder":89},
  {"id":"s_work_han_thu_5_90","chapterId":"ch_work_han_thu_5","textTraditional":"二年冬十月，丞相陳平薨。詔曰：「朕聞古者諸侯建國千餘，各守其地，以時入貢，民不勞苦，上下驩欣，靡有違德。今列侯多居長安，邑遠，〔一〕吏卒給輸費苦，而列侯亦無繇教訓其民。〔二〕其令列侯之國，為吏及詔所止者，遣太子。」〔三〕","sentenceOrder":90},
  {"id":"s_work_han_thu_5_91","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「所食之邑去長安遠。」","sentenceOrder":91},
  {"id":"s_work_han_thu_5_92","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　師古曰：「繇讀與由同。」","sentenceOrder":92},
  {"id":"s_work_han_thu_5_93","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　李奇曰：「為吏，謂為卿大夫者。詔所止，特以恩愛見留者。」","sentenceOrder":93},
  {"id":"s_work_han_thu_5_94","chapterId":"ch_work_han_thu_5","textTraditional":"十一月癸卯晦，日有食之。詔曰：「朕聞之，天生民，為之置君以養治之。人主不德，布政不均，則天示之災以戒不治。〔一〕乃十一月晦，日有食之，適見于天，〔二〕災孰大焉！〔三〕朕獲保宗廟，以微眇之身託于士民君王之上，天下治亂，在予一人，唯二三執政猶吾股肱也。朕下不能治育群生，上以累三光之明，〔四〕其不德大矣。令至，其悉思朕之過失，〔五〕及知見之所不及，匄以啟告朕。〔六〕及舉賢良方正能直言極諫者，以匡朕之不逮。〔七〕因各敕以職任，務省繇費以便民。〔八〕朕既不能遠德，故〈忄間〉然念外人之有非，〔九〕是以設備未息。今縱不能罷邊屯戍，又飭兵厚衛，〔一０〕其罷衛將軍軍。太僕見馬遺財足，〔一一〕餘皆以給傳置。」〔一二〕","sentenceOrder":94},
  {"id":"s_work_han_thu_5_95","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「治音直吏反。」","sentenceOrder":95},
  {"id":"s_work_han_thu_5_96","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　師古曰：「適讀曰謫，責也，音張革反。見音胡電反。」","sentenceOrder":96},
  {"id":"s_work_han_thu_5_97","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　師古曰：「災莫大於此。」","sentenceOrder":97},
  {"id":"s_work_han_thu_5_98","chapterId":"ch_work_han_thu_5","textTraditional":"〔四〕　師古曰：「三光，日、月、星也。累音力瑞反。」","sentenceOrder":98},
  {"id":"s_work_han_thu_5_99","chapterId":"ch_work_han_thu_5","textTraditional":"〔五〕　師古曰：「令謂此詔書。」","sentenceOrder":99},
  {"id":"s_work_han_thu_5_100","chapterId":"ch_work_han_thu_5","textTraditional":"〔六〕　師古曰：「匄音蓋。匄亦乞也。啟，開也。言以過失開告朕躬，是則於朕為恩惠也。商書說命曰『啟乃心，沃朕心』。」","sentenceOrder":100},
  {"id":"s_work_han_thu_5_101","chapterId":"ch_work_han_thu_5","textTraditional":"〔七〕　師古曰：「匡，正也。逮，及也。不逮者，意慮所不及。」","sentenceOrder":101},
  {"id":"s_work_han_thu_5_102","chapterId":"ch_work_han_thu_5","textTraditional":"〔八〕　師古曰：「省，減也，音所領反。繇讀曰徭。」","sentenceOrder":102},
  {"id":"s_work_han_thu_5_103","chapterId":"ch_work_han_thu_5","textTraditional":"〔九〕　蘇林曰：「〈忄間〉，寢視不安貌也。」孟康曰：「〈忄間〉猶介然也。非，姦非也。」師古曰：「孟說是也。〈忄間〉音下板反。」","sentenceOrder":103},
  {"id":"s_work_han_thu_5_104","chapterId":"ch_work_han_thu_5","textTraditional":"〔一０〕師古曰：「飭，整也，讀與敕同。」","sentenceOrder":104},
  {"id":"s_work_han_thu_5_105","chapterId":"ch_work_han_thu_5","textTraditional":"〔一一〕師古曰：「遺，留也。財與纔同。纔，少也。太僕見在之馬今當減，留纔足充事而已。」","sentenceOrder":105},
  {"id":"s_work_han_thu_5_106","chapterId":"ch_work_han_thu_5","textTraditional":"〔一二〕師古曰：「傳音張戀反。置者，置傳驛之所，因名置也。他皆類此。」","sentenceOrder":106},
  {"id":"s_work_han_thu_5_107","chapterId":"ch_work_han_thu_5","textTraditional":"春正月丁亥，詔曰：「夫農，天下之本也，其開藉田，〔一〕朕親率耕，以給宗廟粢盛。〔二〕民謫作縣官及貸種食未入、入未備者，皆赦之。」〔三〕","sentenceOrder":107},
  {"id":"s_work_han_thu_5_108","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　應劭曰：「古者天子耕藉田（十）〔千〕畝，為天下先。藉者，帝王典藉之常也。」韋昭曰：「藉，借也。借民力以治之，以奉宗廟，且以勸率天下，使務農也。」臣瓚曰：「景帝詔曰『朕親耕，后親桑，為天下先』，本以躬親為義，不得以假借為稱也。藉謂蹈藉也。」師古曰：「瓚說是也。國語曰『宣王即位，不藉千畝，虢文公諫』。斯則藉非假借明矣。」","sentenceOrder":108},
  {"id":"s_work_han_thu_5_109","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　師古曰：「黍稷曰粢，在器曰盛。粢音咨。」","sentenceOrder":109},
  {"id":"s_work_han_thu_5_110","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　師古曰：「種者，五穀之種也。食者，所以為糧食也。貸音吐戴反。種音之勇反。」","sentenceOrder":110},
  {"id":"s_work_han_thu_5_111","chapterId":"ch_work_han_thu_5","textTraditional":"三月，有司請立皇子為諸侯王。詔曰：「前趙幽王幽死，朕甚憐之，已立其太子遂為趙王。遂弟辟彊〔一〕及齊悼惠王子朱虛侯章、東牟侯興居有功，可王。」乃（遂）立辟彊為河間王，章為城陽王，興居為濟北王。因立皇子武為代王，參為太原王，揖為梁王。","sentenceOrder":111},
  {"id":"s_work_han_thu_5_112","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「辟彊，言辟禦彊梁者，亦猶辟兵辟非耳。辟音必亦反。彊音其良反。一說辟讀曰闢，彊讀曰疆。闢疆，言開土地也。賈誼書曰：『衛侯朝於周，周行人問其名，衛侯曰辟彊。行人還之曰：「啟彊、辟彊，天子之號也，諸侯弗得用。」更其名曰燬。』則其義兩說並通。他皆類此。」","sentenceOrder":112},
  {"id":"s_work_han_thu_5_113","chapterId":"ch_work_han_thu_5","textTraditional":"五月，詔曰：「古之治天下，朝有進善之旌，〔一〕誹謗之木，〔二〕所以通治道而來諫者也。今法有誹謗訞言之罪，〔三〕是使眾臣不敢盡情，而上無由聞過失也。將何以來遠方之賢良？其除之。民或祝詛上，以相約而後相謾，〔四〕吏以為大逆，其有他言，吏又以為誹謗。此細民之愚，無知抵死，〔五〕朕甚不取。自今以來，有犯此者勿聽治。」","sentenceOrder":113},
  {"id":"s_work_han_thu_5_114","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　應劭曰：「旌，幡也，堯設之五達之道，令民進善也。」如淳曰：「欲有進者，立於旌下言之。」","sentenceOrder":114},
  {"id":"s_work_han_thu_5_115","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　服虔曰：「堯作之，橋梁交午柱頭也。」應劭曰：「橋梁邊板，所以書政治之愆失也。至秦去之，今乃復施也。」師古曰：「應說是也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_5_116","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　師古曰：「高后元年詔除妖言之令，今此又有訞言之罪，是則中間曾重復設此條也。訞與妖同。」","sentenceOrder":116},
  {"id":"s_work_han_thu_5_117","chapterId":"ch_work_han_thu_5","textTraditional":"〔四〕　師古曰：「謾，欺也。初為要約，共行祝詛，後相欺誑，中道而止，無實事也。謾音慢，又音莫連反。」","sentenceOrder":117},
  {"id":"s_work_han_thu_5_118","chapterId":"ch_work_han_thu_5","textTraditional":"〔五〕　師古曰：「抵，觸也，亦至也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_5_119","chapterId":"ch_work_han_thu_5","textTraditional":"九月，初與郡守為銅虎符、竹使符。〔一〕","sentenceOrder":119},
  {"id":"s_work_han_thu_5_120","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　應劭曰：「銅虎符第一至第五，國家當發兵遣使者，至郡合符，符合乃聽受之。竹使符皆以竹箭五枚，長五寸，鐫刻篆書，第一至第五。」張晏曰：「符以代古之圭璋，從簡易也。」師古曰：「與郡守為符者，謂各分其半，右留京師，左以與之。使音所吏反。」","sentenceOrder":120},
  {"id":"s_work_han_thu_5_121","chapterId":"ch_work_han_thu_5","textTraditional":"詔曰：「農，天下之大本也，民所恃以生也，而民或不務本而事末，故生不遂。〔一〕朕憂其然，故今茲親率群臣農以勸之。其賜天下民今年田租之半。」〔二〕","sentenceOrder":121},
  {"id":"s_work_han_thu_5_122","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「衣食（之）〔乏〕絕，致有夭喪，故不遂其生。」","sentenceOrder":122},
  {"id":"s_work_han_thu_5_123","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　師古曰：「免不收之。」","sentenceOrder":123},
  {"id":"s_work_han_thu_5_124","chapterId":"ch_work_han_thu_5","textTraditional":"三年冬十月丁酉晦，日有食之。十一月丁卯晦，日有蝕之。","sentenceOrder":124},
  {"id":"s_work_han_thu_5_125","chapterId":"ch_work_han_thu_5","textTraditional":"詔曰：「前日詔遣列侯之國，辭未行。丞相朕之所重，其為（遂）〔朕〕率列侯之國。」遂免丞相勃，遣就國。十二月，太尉潁陰侯灌嬰為丞相。罷太尉官，屬丞相。","sentenceOrder":125},
  {"id":"s_work_han_thu_5_126","chapterId":"ch_work_han_thu_5","textTraditional":"夏四月，城陽王章薨。淮南王長殺辟陽侯審食其。〔一〕","sentenceOrder":126},
  {"id":"s_work_han_thu_5_127","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「殺之於其家。」","sentenceOrder":127},
  {"id":"s_work_han_thu_5_128","chapterId":"ch_work_han_thu_5","textTraditional":"五月，匈奴入居北地、河南為寇。〔一〕上幸甘泉，〔二〕遣丞相灌嬰擊匈奴，匈奴去。發中尉材官屬衛將軍，軍長安。","sentenceOrder":128},
  {"id":"s_work_han_thu_5_129","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「北地郡之北，黃河之南，即白羊所居。」","sentenceOrder":129},
  {"id":"s_work_han_thu_5_130","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　如淳曰：「蔡邕云天子車駕所至，民臣以為僥幸，故曰幸。見令長三老官屬，親臨軒作樂，賜以酒食帛葛越巾佩帶之屬，民爵有級數，或賜田租之半，故因謂之幸也。」師古曰：「甘泉在雲陽，本秦林光宮。」","sentenceOrder":130},
  {"id":"s_work_han_thu_5_131","chapterId":"ch_work_han_thu_5","textTraditional":"上自甘泉之高奴，〔一〕因幸太原，見故群臣，皆賜之。舉功行賞，諸民里賜牛酒。〔二〕復晉陽、中都民三歲租。〔三〕留游太原十餘日。","sentenceOrder":131},
  {"id":"s_work_han_thu_5_132","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「之，往也。高奴，上郡之縣。」","sentenceOrder":132},
  {"id":"s_work_han_thu_5_133","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　師古曰：「里別率賜之。」","sentenceOrder":133},
  {"id":"s_work_han_thu_5_134","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　師古曰：「復音方目反。」","sentenceOrder":134},
  {"id":"s_work_han_thu_5_135","chapterId":"ch_work_han_thu_5","textTraditional":"濟北王興居聞帝之代，欲自擊匈奴，乃反，發兵欲襲滎陽。於是詔罷丞相兵，以棘蒲侯柴武為大將軍，〔一〕將四將軍十萬眾擊之。祁侯繒賀為將軍，軍滎陽。秋七月，上自太原至長安。詔曰：「濟北王背德反上，詿誤吏民，〔二〕為大逆。濟北吏民兵未至先自定及以軍城邑降者，皆赦之，復官爵。〔三〕與王興居去來者，亦赦之。」〔四〕八月，虜濟北王興居，自殺。赦諸與興居反者。","sentenceOrder":135},
  {"id":"s_work_han_thu_5_136","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　臣瓚曰：「漢帝年紀為陳武，此云柴武，為有二姓。」","sentenceOrder":136},
  {"id":"s_work_han_thu_5_137","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　師古曰：「詿亦誤也，音卦。」","sentenceOrder":137},
  {"id":"s_work_han_thu_5_138","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　師古曰：「復音扶目反。」","sentenceOrder":138},
  {"id":"s_work_han_thu_5_139","chapterId":"ch_work_han_thu_5","textTraditional":"〔四〕　師古曰：「雖始與興居共反，今棄之去而來降者，亦赦。」","sentenceOrder":139},
  {"id":"s_work_han_thu_5_140","chapterId":"ch_work_han_thu_5","textTraditional":"四年冬十二月，丞相灌嬰薨。","sentenceOrder":140},
  {"id":"s_work_han_thu_5_141","chapterId":"ch_work_han_thu_5","textTraditional":"夏五月，復諸劉有屬籍，家無所與。〔一〕賜諸侯王子邑各二千戶。","sentenceOrder":141},
  {"id":"s_work_han_thu_5_142","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「復音方目反。與讀曰豫。」","sentenceOrder":142},
  {"id":"s_work_han_thu_5_143","chapterId":"ch_work_han_thu_5","textTraditional":"秋九月，封齊悼惠王子七人為列侯。","sentenceOrder":143},
  {"id":"s_work_han_thu_5_144","chapterId":"ch_work_han_thu_5","textTraditional":"絳侯周勃有罪，逮詣廷尉詔獄。","sentenceOrder":144},
  {"id":"s_work_han_thu_5_145","chapterId":"ch_work_han_thu_5","textTraditional":"作顧成廟。〔一〕","sentenceOrder":145},
  {"id":"s_work_han_thu_5_146","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　服虔曰：「廟在長安城南，文帝作。還顧見城，故名之。」應劭曰：「文帝自為廟，制度卑狹，若顧望而成，猶文王靈臺不日成之，故曰顧成。賈誼曰：『因顧成之廟，為天下太宗，與漢無極。』」如淳曰：「身存而為廟，若尚書之顧命也。景帝廟號德陽，武帝廟號龍淵，昭帝廟號徘徊，宣帝廟號樂游，元帝廟號長壽，成帝廟號陽池。」師古曰：「以還顧見城，因即為名，於義無取。又書本不作城郭字，應說近之。」","sentenceOrder":146},
  {"id":"s_work_han_thu_5_147","chapterId":"ch_work_han_thu_5","textTraditional":"五年春二月，地震。","sentenceOrder":147},
  {"id":"s_work_han_thu_5_148","chapterId":"ch_work_han_thu_5","textTraditional":"夏四月，除盜鑄錢令。〔一〕更造四銖錢。〔二〕","sentenceOrder":148},
  {"id":"s_work_han_thu_5_149","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　應劭曰：「聽民放鑄也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_5_150","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　應劭曰：「文帝以五分錢太輕小，更作四銖錢，文亦曰『半兩』，今民間半兩錢最輕小者是也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_5_151","chapterId":"ch_work_han_thu_5","textTraditional":"六年冬十月，桃李華。","sentenceOrder":151},
  {"id":"s_work_han_thu_5_152","chapterId":"ch_work_han_thu_5","textTraditional":"十一月，淮南王長謀反，廢遷蜀嚴道，死雍。〔一〕","sentenceOrder":152},
  {"id":"s_work_han_thu_5_153","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「遷於蜀郡之嚴道，行至扶風雍縣，在道而死也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_5_154","chapterId":"ch_work_han_thu_5","textTraditional":"七年冬十月，令列侯太夫人、夫人、諸侯王子及吏二千石無得擅徵捕。〔一〕","sentenceOrder":154},
  {"id":"s_work_han_thu_5_155","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　如淳曰：「列侯之妻稱夫人。列侯死，子復為列侯，乃得稱太夫人，子不為列侯不得稱也。」夏四月，赦天下。","sentenceOrder":155},
  {"id":"s_work_han_thu_5_156","chapterId":"ch_work_han_thu_5","textTraditional":"六月癸酉，未央宮東闕罘罳災。〔一〕","sentenceOrder":156},
  {"id":"s_work_han_thu_5_157","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　如淳曰：「東闕與其兩旁罘罳皆災也。」晉灼曰：「東闕之罘罳獨災也。」師古曰：「罘罳，謂連闕曲閣也，以覆重刻垣墉之處，其形罘罳然，一曰屏也。罘音浮。」","sentenceOrder":157},
  {"id":"s_work_han_thu_5_158","chapterId":"ch_work_han_thu_5","textTraditional":"八年夏，封淮南厲王長子四人為列侯。","sentenceOrder":158},
  {"id":"s_work_han_thu_5_159","chapterId":"ch_work_han_thu_5","textTraditional":"有長星出于東方。〔一〕","sentenceOrder":159},
  {"id":"s_work_han_thu_5_160","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　文穎曰：「孛、彗、長三星，其占略同，然其形象小異。孛星光芒短，其光四出蓬蓬孛孛也。彗星光芒長，參參如埽彗。長星光芒有一直指，或竟天，或十丈，或三丈，或二丈，無常也。大法，孛、彗星多為除舊布新，火災，長星多為兵革事。」","sentenceOrder":160},
  {"id":"s_work_han_thu_5_161","chapterId":"ch_work_han_thu_5","textTraditional":"九年春，大旱。","sentenceOrder":161},
  {"id":"s_work_han_thu_5_162","chapterId":"ch_work_han_thu_5","textTraditional":"十年冬，行幸甘泉。","sentenceOrder":162},
  {"id":"s_work_han_thu_5_163","chapterId":"ch_work_han_thu_5","textTraditional":"將軍薄昭死。〔一〕","sentenceOrder":163},
  {"id":"s_work_han_thu_5_164","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　鄭氏曰：「昭殺漢使者，文帝不忍加誅，使公卿從之飲酒，欲令自引分。昭不肯，使群臣喪服往哭之，乃自殺。有罪，故言死。」如淳曰：「一說昭與文帝博不勝，當飲酒，侍郎酌，為昭少，一侍郎譴呵之。時此郎下沐，昭使人殺之，是以文帝使自殺。」師古曰：「外戚恩澤侯表云坐殺漢使者自殺。鄭說是也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_5_165","chapterId":"ch_work_han_thu_5","textTraditional":"十一年冬十一月，行幸代。春正月，上自代還。","sentenceOrder":165},
  {"id":"s_work_han_thu_5_166","chapterId":"ch_work_han_thu_5","textTraditional":"夏六月，梁王揖薨。","sentenceOrder":166},
  {"id":"s_work_han_thu_5_167","chapterId":"ch_work_han_thu_5","textTraditional":"匈奴寇狄道。","sentenceOrder":167},
  {"id":"s_work_han_thu_5_168","chapterId":"ch_work_han_thu_5","textTraditional":"十二年冬十二月，河決東郡。","sentenceOrder":168},
  {"id":"s_work_han_thu_5_169","chapterId":"ch_work_han_thu_5","textTraditional":"春正月，賜諸侯王女邑各二千戶。","sentenceOrder":169},
  {"id":"s_work_han_thu_5_170","chapterId":"ch_work_han_thu_5","textTraditional":"二月，出孝惠皇帝後宮美人，令得嫁。","sentenceOrder":170},
  {"id":"s_work_han_thu_5_171","chapterId":"ch_work_han_thu_5","textTraditional":"三月，除關無用傳。〔一〕","sentenceOrder":171},
  {"id":"s_work_han_thu_5_172","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　張晏曰：「傳，信也，若今過所也。」如淳曰：「兩行書繒帛，分持其一，出入關，合之乃得過，謂之傳也。」李奇曰：「傳，棨也。」師古曰：「張說是也。古者或用棨，或用繒帛。棨者，刻木為合符也。傳音張戀反。棨音啟。」","sentenceOrder":172},
  {"id":"s_work_han_thu_5_173","chapterId":"ch_work_han_thu_5","textTraditional":"詔曰：「道民之路，在於務本。朕親率天下農，十年于今，而野不加辟，〔一〕歲一不登，民有飢色，〔二〕是從事焉尚寡，而吏未加務也。〔三〕吾詔書數下，歲勸民種樹，〔四〕而功未興，是吏奉吾詔不勤，而勸民不明也。且吾農民甚苦，而吏莫之省，〔五〕將何以勸焉？其賜農民今年租稅之半。」","sentenceOrder":173},
  {"id":"s_work_han_thu_5_174","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「辟讀曰闢。闢，開也。」","sentenceOrder":174},
  {"id":"s_work_han_thu_5_175","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　師古曰：「登，成也。言五穀一歲不成則眾庶飢餒，是無蓄積故也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_5_176","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　師古曰：「從事，從農事也。」","sentenceOrder":176},
  {"id":"s_work_han_thu_5_177","chapterId":"ch_work_han_thu_5","textTraditional":"〔四〕　師古曰：「樹，謂藝殖也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_5_178","chapterId":"ch_work_han_thu_5","textTraditional":"〔五〕　師古曰：「省，視也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_5_179","chapterId":"ch_work_han_thu_5","textTraditional":"又曰：「孝悌，天下之大順也。力田，為生之本也。三老，眾民之師也。廉吏，民之表也。朕甚嘉此二三大夫之行。今萬家之縣，云無應令，〔一〕豈實人情？是吏舉賢之道未備也。其遣謁者勞賜三老、孝者帛人五匹，悌者、力田二匹，廉吏二百石以上率百石者三匹。〔二〕及問民所不便安，而以戶口率置三老孝悌力田常員，〔三〕令各率其意以道民焉。」〔四〕","sentenceOrder":179},
  {"id":"s_work_han_thu_5_180","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「無孝悌力田之人可應察舉之令。」","sentenceOrder":180},
  {"id":"s_work_han_thu_5_181","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　師古曰：「自二百石以上，每百石加三匹。」","sentenceOrder":181},
  {"id":"s_work_han_thu_5_182","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　師古曰：「計戶口之數以率之，增置其員，廣教化也。」","sentenceOrder":182},
  {"id":"s_work_han_thu_5_183","chapterId":"ch_work_han_thu_5","textTraditional":"〔四〕　師古曰：「道讀曰導。」","sentenceOrder":183},
  {"id":"s_work_han_thu_5_184","chapterId":"ch_work_han_thu_5","textTraditional":"十三年春二月甲寅，詔曰：「朕親率天下農耕以供粢盛，皇后親桑以奉祭服，其具禮儀。」〔一〕","sentenceOrder":184},
  {"id":"s_work_han_thu_5_185","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「令立耕桑之禮制也。」","sentenceOrder":185},
  {"id":"s_work_han_thu_5_186","chapterId":"ch_work_han_thu_5","textTraditional":"夏，除祕祝，〔一〕語在郊祀志。五月，除肉刑法，語在刑法志。","sentenceOrder":186},
  {"id":"s_work_han_thu_5_187","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　應劭曰：「祕祝之官，移過于下，國家諱之，故曰祕也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_5_188","chapterId":"ch_work_han_thu_5","textTraditional":"六月，詔曰：「農，天下之本，務莫大焉。今廑身從事，〔一〕而有租稅之賦，是謂本末者無以異也，〔二〕其於勸農之道未備。其除田之租稅。賜天下孤寡布帛絮各有數。」","sentenceOrder":188},
  {"id":"s_work_han_thu_5_189","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　晉灼曰：「廑，古勤字。」","sentenceOrder":189},
  {"id":"s_work_han_thu_5_190","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　李奇曰：「本，農也。末，賈也。言農與賈俱出租，無異也，故除田租。」","sentenceOrder":190},
  {"id":"s_work_han_thu_5_191","chapterId":"ch_work_han_thu_5","textTraditional":"十四年冬，匈奴寇邊，殺北地都尉卬。〔一〕遣三將軍軍隴西、北地、上郡，中尉周舍為衛將軍，郎中令張武為車騎將軍，軍渭北，車千乘，騎卒十萬人。上親勞軍，勒兵，申教令，〔二〕賜吏卒。自欲征匈奴，群臣諫，不聽。皇太后固要上，乃止。〔三〕於是以東陽侯張相如為大將軍，建成侯董赫、內史欒布皆為將軍，擊匈奴。匈奴走。","sentenceOrder":191},
  {"id":"s_work_han_thu_5_192","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「功臣表云缾侯孫單以父北地都尉卬力戰死事，文帝十四年封，與此正合。然則卬姓孫，而徐廣乃云姓段，說者因曰段會宗即卬之玄孫，無所據也。會宗，漢書有傳，班固不云是卬後，何從而知之乎？」","sentenceOrder":192},
  {"id":"s_work_han_thu_5_193","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　師古曰：「申謂約束之。」","sentenceOrder":193},
  {"id":"s_work_han_thu_5_194","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　文穎曰：「要（卻）〔劫〕也，哀痛祝誓之言。」","sentenceOrder":194},
  {"id":"s_work_han_thu_5_195","chapterId":"ch_work_han_thu_5","textTraditional":"春，詔曰：「朕獲執犧牲珪幣以事上帝宗廟，十四年于今。歷日彌長，以不敏不明〔一〕而久撫臨天下，朕甚自媿。〔二〕其廣增諸祀壇場珪幣。〔三〕昔先王遠施不求其報，望祀不祈其福，右賢左戚，〔四〕先民後己，至明之極也。今吾聞祠官祝釐，〔五〕皆歸福於朕躬，不為百姓，朕甚媿之。夫以朕之不德，而專鄉獨美其福，百姓不與焉，〔六〕是重吾不德也。〔七〕其令祠官致敬，無有所祈。」","sentenceOrder":195},
  {"id":"s_work_han_thu_5_196","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「敏，材識捷疾。」","sentenceOrder":196},
  {"id":"s_work_han_thu_5_197","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　師古曰：「媿，古愧字。」","sentenceOrder":197},
  {"id":"s_work_han_thu_5_198","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　師古曰：「築土為壇，除地為場。幣，祭神之帛。」","sentenceOrder":198},
  {"id":"s_work_han_thu_5_199","chapterId":"ch_work_han_thu_5","textTraditional":"〔四〕　師古曰：「以賢為上，然後及親也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_5_200","chapterId":"ch_work_han_thu_5","textTraditional":"〔五〕　如淳曰：「釐，福也。賈誼傳『受釐坐宣室』是也。」師古曰：「釐，本字作禧，假借用耳，同音僖。」","sentenceOrder":200},
  {"id":"s_work_han_thu_5_201","chapterId":"ch_work_han_thu_5","textTraditional":"〔六〕　師古曰：「與讀曰豫。」","sentenceOrder":201},
  {"id":"s_work_han_thu_5_202","chapterId":"ch_work_han_thu_5","textTraditional":"〔七〕　師古曰：「重音直用反。」","sentenceOrder":202},
  {"id":"s_work_han_thu_5_203","chapterId":"ch_work_han_thu_5","textTraditional":"十五年春，黃龍見於成紀。〔一〕上乃下詔議郊祀。公孫臣明服色，新垣平設五廟。〔二〕語在郊祀志。夏四月，上幸雍，始郊見五帝，赦天下，修名山大川嘗祀而絕者，有司以歲時致禮。","sentenceOrder":203},
  {"id":"s_work_han_thu_5_204","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「成紀，隴西縣。」","sentenceOrder":204},
  {"id":"s_work_han_thu_5_205","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　文穎曰：「公孫臣，魯人也。」應劭曰：「新垣平，趙人也。」師古曰：「五廟，即下渭陽五帝之廟也。」","sentenceOrder":205},
  {"id":"s_work_han_thu_5_206","chapterId":"ch_work_han_thu_5","textTraditional":"九月，詔諸侯王公卿郡守舉賢良能直言極諫者，上親策之，傅納以言。〔一〕語在晁錯傳。〔二〕","sentenceOrder":206},
  {"id":"s_work_han_thu_5_207","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「傅讀曰敷，敷陳其言而納用之。」","sentenceOrder":207},
  {"id":"s_work_han_thu_5_208","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　師古曰：「錯音千故反。」","sentenceOrder":208},
  {"id":"s_work_han_thu_5_209","chapterId":"ch_work_han_thu_5","textTraditional":"十六年夏四月，上郊祀五帝于渭陽。〔一〕","sentenceOrder":209},
  {"id":"s_work_han_thu_5_210","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　韋昭曰：「在渭城。」師古曰：「郊祀志云在長安東北，非渭城也。韋說謬矣。」","sentenceOrder":210},
  {"id":"s_work_han_thu_5_211","chapterId":"ch_work_han_thu_5","textTraditional":"五月，立齊悼惠王子六人、淮南厲王子三人皆為王。","sentenceOrder":211},
  {"id":"s_work_han_thu_5_212","chapterId":"ch_work_han_thu_5","textTraditional":"秋九月，得玉杯，〔一〕刻曰「人主延壽」。令天下大酺，明年改元。","sentenceOrder":212},
  {"id":"s_work_han_thu_5_213","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　應劭曰：「新垣平詐令人獻之。」","sentenceOrder":213},
  {"id":"s_work_han_thu_5_214","chapterId":"ch_work_han_thu_5","textTraditional":"後元年〔一〕冬十月，新垣平詐覺，謀反，〔二〕夷三族。","sentenceOrder":214},
  {"id":"s_work_han_thu_5_215","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　張晏曰：「新垣平候日再中，以為吉祥，故改元年，以求延年之祚也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_5_216","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　師古曰：「以詐事發覺，自恐被誅，因謀反也。」","sentenceOrder":216},
  {"id":"s_work_han_thu_5_217","chapterId":"ch_work_han_thu_5","textTraditional":"春三月，孝惠皇后張氏薨。〔一〕","sentenceOrder":217},
  {"id":"s_work_han_thu_5_218","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　張晏曰：「后黨於呂氏，廢處北宮，故不曰崩。」","sentenceOrder":218},
  {"id":"s_work_han_thu_5_219","chapterId":"ch_work_han_thu_5","textTraditional":"詔曰：「間者數年比不登，〔一〕又有水旱疾疫之災，朕甚憂之。愚而不明，未達其咎。意者朕之政有所失而行有過與？〔二〕乃天道有不順，地利或不得，人事多失和，鬼神廢不享與？何以致此？將百官之奉養或費，無用之事或多與？何其民食之寡乏也！夫度田非益寡，而計民未加益，〔三〕以口量地，其於古猶有餘，而食之甚不足者，其咎安在？無乃百姓之從事於末以害農者蕃，〔四〕為酒醪以靡穀者多，〔五〕六畜之食焉者眾與？細大之義，吾未能得其中。〔六〕其與丞相列侯吏二千石博士議之，有可以佐百姓者，率意遠思，無有所隱。」","sentenceOrder":219},
  {"id":"s_work_han_thu_5_220","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「比猶頻也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_5_221","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　師古曰：「與讀曰歟，音弋於反。下皆類此。」","sentenceOrder":221},
  {"id":"s_work_han_thu_5_222","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　師古曰：「度謂量計之，音徒各反。」","sentenceOrder":222},
  {"id":"s_work_han_thu_5_223","chapterId":"ch_work_han_thu_5","textTraditional":"〔四〕　師古曰：「末謂工商之業也。蕃亦多也，音扶元反。」","sentenceOrder":223},
  {"id":"s_work_han_thu_5_224","chapterId":"ch_work_han_thu_5","textTraditional":"〔五〕　師古曰：「醪，汁滓酒也。靡，散也。醪音來高反。靡音糜。」","sentenceOrder":224},
  {"id":"s_work_han_thu_5_225","chapterId":"ch_work_han_thu_5","textTraditional":"〔六〕　師古曰：「中音竹仲反。」","sentenceOrder":225},
  {"id":"s_work_han_thu_5_226","chapterId":"ch_work_han_thu_5","textTraditional":"二年夏，行幸雍棫陽宮。〔一〕","sentenceOrder":226},
  {"id":"s_work_han_thu_5_227","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　蘇林曰：「棫音域。」張晏曰：「秦昭王所作也。」晉灼曰：「黃圖在扶風。」","sentenceOrder":227},
  {"id":"s_work_han_thu_5_228","chapterId":"ch_work_han_thu_5","textTraditional":"六月，代王參薨。匈奴和親。詔曰：「朕既不明，不能遠德，使方外之國或不寧息。夫四荒之外不安其生，〔一〕封圻之內勤勞不處，〔二〕二者之咎，皆自於朕之德薄而不能達遠也。間者累年，匈奴並暴邊境，多殺吏民，邊臣兵吏（入）〔又〕不能諭其內志，以重吾不德。〔三〕夫久結難連兵，中外之國將何以自寧？今朕夙興夜寐，勤勞天下，憂苦萬民，為之惻怛不安，〔四〕未嘗一日忘於心，故遣使者冠蓋相望，結徹於道，〔五〕以諭朕志於單于。〔六〕今單于反古之道，〔七〕計社稷之安，便萬民之利，新與朕俱棄細過，偕之大道，〔八〕結兄弟之義，以全天下元元之民。〔九〕和親以定，始于今年。」","sentenceOrder":228},
  {"id":"s_work_han_thu_5_229","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「戎狄荒服，故曰四荒，言其荒忽去來無常也。爾雅曰『孤竹、北戶、西王母、日下謂之四荒』。」","sentenceOrder":229},
  {"id":"s_work_han_thu_5_230","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　師古曰：「圻亦畿字。王畿千里。不處者，不獲安居。」","sentenceOrder":230},
  {"id":"s_work_han_thu_5_231","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　師古曰：「諭，曉告也。重音直用反。」","sentenceOrder":231},
  {"id":"s_work_han_thu_5_232","chapterId":"ch_work_han_thu_5","textTraditional":"〔四〕　師古曰：「惻，痛也。怛，恨也。怛音丁曷反。」","sentenceOrder":232},
  {"id":"s_work_han_thu_5_233","chapterId":"ch_work_han_thu_5","textTraditional":"〔五〕　韋昭曰：「使車往還，故徹如結也。」","sentenceOrder":233},
  {"id":"s_work_han_thu_5_234","chapterId":"ch_work_han_thu_5","textTraditional":"〔六〕　師古曰：「單于，匈奴天子之號也。單音蟬。」","sentenceOrder":234},
  {"id":"s_work_han_thu_5_235","chapterId":"ch_work_han_thu_5","textTraditional":"〔七〕　師古曰：「（返）〔反〕，還也。」","sentenceOrder":235},
  {"id":"s_work_han_thu_5_236","chapterId":"ch_work_han_thu_5","textTraditional":"〔八〕　師古曰：「偕亦俱也。之，往也，趣也。」","sentenceOrder":236},
  {"id":"s_work_han_thu_5_237","chapterId":"ch_work_han_thu_5","textTraditional":"〔九〕　師古曰：「元元，善意也。」","sentenceOrder":237},
  {"id":"s_work_han_thu_5_238","chapterId":"ch_work_han_thu_5","textTraditional":"三年春二月，行幸代。","sentenceOrder":238},
  {"id":"s_work_han_thu_5_239","chapterId":"ch_work_han_thu_5","textTraditional":"四年夏四月丙寅晦，日有蝕之。五月，赦天下。免官奴婢為庶人。行幸雍。","sentenceOrder":239},
  {"id":"s_work_han_thu_5_240","chapterId":"ch_work_han_thu_5","textTraditional":"五年春正月，行幸隴西。三月，行幸雍。秋七月，行幸代。","sentenceOrder":240},
  {"id":"s_work_han_thu_5_241","chapterId":"ch_work_han_thu_5","textTraditional":"六年冬，匈奴三萬騎入上郡，三萬騎入雲中。以中大夫令免為車騎將軍屯飛狐，〔一〕故楚相蘇意為將軍屯句注，〔二〕將軍張武屯北地，河內太守周亞夫為將軍次細柳，〔三〕宗正劉禮為將軍次霸上，祝茲侯徐厲為將軍次棘門，〔四〕以備胡。","sentenceOrder":241},
  {"id":"s_work_han_thu_5_242","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　如淳曰：「在代郡。」師古曰：「中大夫，官名，其人姓令名免耳。此諸將軍下至徐厲，皆書姓，而徐廣以為中大夫令是官名，此說非也。據百官表，景帝初改衛尉為中大夫令，文帝時無此官。而中大夫是郎中令屬官，秩比二千石。」","sentenceOrder":242},
  {"id":"s_work_han_thu_5_243","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　應劭曰：「山險名也，在鴈門陰館。」師古曰：「句音章句之句。」","sentenceOrder":243},
  {"id":"s_work_han_thu_5_244","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　服虔曰：「在長安西北。」如淳曰：「長安細柳倉在渭北，近石徼。」張揖曰：「在昆明池南，今有柳市是也。」臣瓚曰：「一宿曰宿，再宿曰信，過信為次。」師古曰：「匈奴傳云『置三將軍，軍長安西細柳、渭北棘門、霸上』。此則細柳不在渭北，揖說是也。」","sentenceOrder":244},
  {"id":"s_work_han_thu_5_245","chapterId":"ch_work_han_thu_5","textTraditional":"〔四〕　孟康曰：「在長安北，秦時宮門也。」如淳曰：「三輔黃圖棘門在橫門外也。」","sentenceOrder":245},
  {"id":"s_work_han_thu_5_246","chapterId":"ch_work_han_thu_5","textTraditional":"夏四月，大旱，蝗。〔一〕令諸侯無入貢。弛山澤。〔二〕減諸服御。損郎吏員。發倉庾〔三〕以振民。民得賣爵。","sentenceOrder":246},
  {"id":"s_work_han_thu_5_247","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「蝗即螽也，食苗為災，今俗呼為簸蝩。蝗音胡光反。蝩音鍾。」","sentenceOrder":247},
  {"id":"s_work_han_thu_5_248","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　師古曰：「弛，解也，解而不禁，與眾庶同其利。」","sentenceOrder":248},
  {"id":"s_work_han_thu_5_249","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　應劭曰：「水漕倉曰庾。胡公曰『在邑曰倉，在野曰庾』。」","sentenceOrder":249},
  {"id":"s_work_han_thu_5_250","chapterId":"ch_work_han_thu_5","textTraditional":"七年夏六月己亥，帝崩于未央宮。〔一〕遺詔曰：「朕聞之，蓋天下萬物之萌生，靡不有死。〔二〕死者天地之理，物之自然，奚可甚哀！〔三〕當今之世，咸嘉生而惡死，厚葬以破業，重服以傷生，吾甚不取。且朕既不德，無以佐百姓；今崩，又使重服久臨，〔四〕以罹寒暑之數，〔五〕哀人父子，傷長老之志，損其飲食，絕鬼神之祭祀，以重吾不德，〔六〕謂天下何！朕獲保宗廟，以眇眇之身託于天下君王之上，〔七〕二十有餘年矣。賴天之靈，社稷之福，方內安寧，〔八〕靡有兵革。〔九〕朕既不敏，常畏過行，以羞先帝之遺德；〔一０〕惟年之久長，懼于不終。今乃幸以天年得復供養于高廟，朕之不明與嘉之，其奚哀念之有！〔一一〕其令天下吏民，令到出臨三日，皆釋服。〔一二〕無禁取婦嫁女祠祀飲酒食肉。自當給喪事服臨者，皆無踐。〔一三〕（姪）〔絰〕帶無過三寸。無布車及兵器。〔一四〕無發民哭臨宮殿中。殿中當臨者，皆以旦夕各十五舉音，禮畢罷。非旦夕臨時，禁無得擅哭（臨）。以下，〔一五〕服大紅十五日，小紅十四日，纖七日，釋服。〔一六〕它不在令中者，皆以此令比類從事。〔一七〕布告天下，使明知朕意。霸陵山川因其故，無有所改。〔一八〕歸夫人以下至少使。」〔一九〕令中尉亞夫為車騎將軍，屬國悍為將屯將軍，〔二０〕郎中令張武為復土將軍，〔二一〕發近縣卒萬六千人，發內史卒萬五千人，臧郭穿復土屬將軍武。〔二二〕賜諸侯王以下至孝悌力田金錢帛各有數。乙巳，葬霸陵。〔二三〕","sentenceOrder":250},
  {"id":"s_work_han_thu_5_251","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　臣瓚曰：「帝年二十三即位，即位二十三年，壽四十六也。」","sentenceOrder":251},
  {"id":"s_work_han_thu_5_252","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　師古曰：「始生者曰萌。」","sentenceOrder":252},
  {"id":"s_work_han_thu_5_253","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　師古曰：「奚，何也。」","sentenceOrder":253},
  {"id":"s_work_han_thu_5_254","chapterId":"ch_work_han_thu_5","textTraditional":"〔四〕　師古曰：「臨，哭也，音力禁反。下云服臨、當臨者，音並同也。」","sentenceOrder":254},
  {"id":"s_work_han_thu_5_255","chapterId":"ch_work_han_thu_5","textTraditional":"〔五〕　師古曰：「罹音離，遭也。」","sentenceOrder":255},
  {"id":"s_work_han_thu_5_256","chapterId":"ch_work_han_thu_5","textTraditional":"〔六〕　師古曰：「重音直用反。」","sentenceOrder":256},
  {"id":"s_work_han_thu_5_257","chapterId":"ch_work_han_thu_5","textTraditional":"〔七〕　師古曰：「眇眇，猶言細末也。」","sentenceOrder":257},
  {"id":"s_work_han_thu_5_258","chapterId":"ch_work_han_thu_5","textTraditional":"〔八〕　臣瓚曰：「方，四方也。內，中也。猶云中外。」師古曰：「此說非也，直謂（四）方之內耳。」","sentenceOrder":258},
  {"id":"s_work_han_thu_5_259","chapterId":"ch_work_han_thu_5","textTraditional":"〔九〕　師古曰：「靡，無也。」","sentenceOrder":259},
  {"id":"s_work_han_thu_5_260","chapterId":"ch_work_han_thu_5","textTraditional":"〔一０〕師古曰：「過行，行有過失也。羞謂忝辱也。行音下更反。」","sentenceOrder":260},
  {"id":"s_work_han_thu_5_261","chapterId":"ch_work_han_thu_5","textTraditional":"〔一一〕如淳曰：「得卒天年，已善矣。」晉灼曰：「若以朕不明，當嘉善朕之儉約，何哀念之有也。」師古曰：「如、晉之說非也。與讀曰歟，音弋於反。帝自言或者豈朕見之不明乎，以不可嘉為嘉耳。然朕自謂得終天年，供養高廟，為可嘉之事，無所哀念也。今俗語猶然，其意可曉矣。」","sentenceOrder":261},
  {"id":"s_work_han_thu_5_262","chapterId":"ch_work_han_thu_5","textTraditional":"〔一二〕師古曰：「令謂此詔文也。」","sentenceOrder":262},
  {"id":"s_work_han_thu_5_263","chapterId":"ch_work_han_thu_5","textTraditional":"〔一三〕伏儼曰：「踐，翦也，謂無斬衰也。」孟康曰：「踐，跣也。」晉灼曰：「漢語作跣。跣，徒跣也。」師古曰：「孟、晉二說是也。」","sentenceOrder":263},
  {"id":"s_work_han_thu_5_264","chapterId":"ch_work_han_thu_5","textTraditional":"〔一四〕應劭曰：「無以布衣車及兵器也。」服虔曰：「不施輕車介士也。」師古曰：「應說是也。」","sentenceOrder":264},
  {"id":"s_work_han_thu_5_265","chapterId":"ch_work_han_thu_5","textTraditional":"〔一五〕師古曰：「為下棺也。音義與高紀同。」","sentenceOrder":265},
  {"id":"s_work_han_thu_5_266","chapterId":"ch_work_han_thu_5","textTraditional":"〔一六〕服虔曰：「皆當言大功、小功布也。纖，細布衣也。」應劭曰：「紅者，中祥、大祥以紅為領緣。纖者，禫也。凡三十六日而釋服矣。此以日易月也。」晉灼曰：「漢書例以紅為功也。」師古曰：「紅與功同。服、晉二說是也。此喪制者，文帝自率己意創而為之，非有取於周禮也，何為以日易月乎！三年之喪，其實二十七月，豈有三十六月之文！禫又無七月也。應氏既失之於前，而近代學者因循謬說，未之思也。」","sentenceOrder":266},
  {"id":"s_work_han_thu_5_267","chapterId":"ch_work_han_thu_5","textTraditional":"〔一七〕師古曰：「言此詔中無文者，皆以類比而行事。」","sentenceOrder":267},
  {"id":"s_work_han_thu_5_268","chapterId":"ch_work_han_thu_5","textTraditional":"〔一八〕應劭曰：「因山為藏，不復起墳，山下川流不遏絕，就其水名以為陵號。」","sentenceOrder":268},
  {"id":"s_work_han_thu_5_269","chapterId":"ch_work_han_thu_5","textTraditional":"〔一九〕應劭曰：「夫人以下有美人、良人、八子、七子、長使、少使，皆遣歸家，重絕人類。」","sentenceOrder":269},
  {"id":"s_work_han_thu_5_270","chapterId":"ch_work_han_thu_5","textTraditional":"〔二０〕師古曰：「典屯軍以備非常。」","sentenceOrder":270},
  {"id":"s_work_han_thu_5_271","chapterId":"ch_work_han_thu_5","textTraditional":"〔二一〕如淳曰：「主穿壙窴瘞事也。」師古曰：「穿壙，出土下棺也。已而窴之，又即以為墳，故云復土。復，反還也，音扶目反。」","sentenceOrder":271},
  {"id":"s_work_han_thu_5_272","chapterId":"ch_work_han_thu_5","textTraditional":"〔二二〕師古曰：「即張武也。」","sentenceOrder":272},
  {"id":"s_work_han_thu_5_273","chapterId":"ch_work_han_thu_5","textTraditional":"〔二三〕師古曰：「自崩至葬凡七日也。霸陵在長安東南。」","sentenceOrder":273},
  {"id":"s_work_han_thu_5_274","chapterId":"ch_work_han_thu_5","textTraditional":"贊曰：孝文皇帝即位二十三年，宮室苑囿車騎服御無所增益。有不便，輒弛以利民。〔一〕嘗欲作露臺，召匠計之，直百金。上曰：「百金，中人十家之產也。〔二〕吾奉先帝宮室，常恐羞之，何以臺為！」〔三〕身衣弋綈，〔四〕所幸慎夫人衣不曳地，帷帳無文繡，以示敦朴，為天下先。治霸陵，皆瓦器，不得以金銀銅錫為飾，因其山，不起墳。南越尉佗自立為帝，召貴佗兄弟，以德懷之，佗遂稱臣。與匈奴結和親，後而背約入盜，令邊備守，不發兵深入，恐煩百姓。吳王詐病不朝，賜以几杖。群臣袁盎等諫說雖切，常假借納用焉。〔五〕張武等受賂金錢，覺，更加賞賜，以媿其心。專務以德化民，是以海內殷富，興於禮義，斷獄數百，幾致刑措。〔六〕嗚呼，仁哉！","sentenceOrder":274},
  {"id":"s_work_han_thu_5_275","chapterId":"ch_work_han_thu_5","textTraditional":"〔一〕　師古曰：「弛，廢弛，音式爾反。」","sentenceOrder":275},
  {"id":"s_work_han_thu_5_276","chapterId":"ch_work_han_thu_5","textTraditional":"〔二〕　師古曰：「中謂不富不貧。」","sentenceOrder":276},
  {"id":"s_work_han_thu_5_277","chapterId":"ch_work_han_thu_5","textTraditional":"〔三〕　師古曰：「今新豐縣南驪山之頂有露臺鄉，極為高顯，猶有文帝所欲作臺之處。」","sentenceOrder":277},
  {"id":"s_work_han_thu_5_278","chapterId":"ch_work_han_thu_5","textTraditional":"〔四〕　如淳曰：「弋，皂也。賈誼曰『身衣皂綈』。」師古曰：「弋，黑色也。綈，厚繒。綈音大奚反。」","sentenceOrder":278},
  {"id":"s_work_han_thu_5_279","chapterId":"ch_work_han_thu_5","textTraditional":"〔五〕　蘇林曰：「假音休假。借音以物借人之借。」","sentenceOrder":279},
  {"id":"s_work_han_thu_5_280","chapterId":"ch_work_han_thu_5","textTraditional":"〔六〕　應劭曰：「措，置也。民不犯法，無所刑也。」師古曰：「斷獄數百者，言普天之下死罪人不過數百。幾，近也，音巨衣反。」","sentenceOrder":280},
  {"id":"s_work_han_thu_5_281","chapterId":"ch_work_han_thu_5","textTraditional":"校勘記","sentenceOrder":281},
  {"id":"s_work_han_thu_5_282","chapterId":"ch_work_han_thu_5","textTraditional":"一０八頁一０行　宗室將相王列侯以為（其）〔莫〕宜寡人，　王念孫說「其」字文義不順，當依史記作「莫」。楊樹達說王校是。","sentenceOrder":282},
  {"id":"s_work_han_thu_5_283","chapterId":"ch_work_han_thu_5","textTraditional":"一一四頁一五行　朕（已）〔以〕得保宗廟。　蘇輿說史記作「以」，依本書例，作「以」為合。","sentenceOrder":283},
  {"id":"s_work_han_thu_5_284","chapterId":"ch_work_han_thu_5","textTraditional":"一一五頁　九行　又音於（度）〔庶〕反。　景祐、殿本都作「庶」。王先謙說作「庶」是。","sentenceOrder":284},
  {"id":"s_work_han_thu_5_285","chapterId":"ch_work_han_thu_5","textTraditional":"一一七頁　六行　古者天子耕藉田（十）〔千〕畝，　景祐、殿本都作「千」，史記集解同。","sentenceOrder":285},
  {"id":"s_work_han_thu_5_286","chapterId":"ch_work_han_thu_5","textTraditional":"一一七頁一二行　乃（遂）立辟彊為河間王，　王先謙說「遂」字涉上文而衍。按史記無「遂」字。","sentenceOrder":286},
  {"id":"s_work_han_thu_5_287","chapterId":"ch_work_han_thu_5","textTraditional":"一一九頁　一行　衣食（之）〔乏〕絕，　景祐、殿本都作「乏」。王先謙說作「乏」是。","sentenceOrder":287},
  {"id":"s_work_han_thu_5_288","chapterId":"ch_work_han_thu_5","textTraditional":"一一九頁　四行　其為（遂）〔朕〕率列侯之國。　景祐、殿本都作「朕」，史記同。","sentenceOrder":288},
  {"id":"s_work_han_thu_5_289","chapterId":"ch_work_han_thu_5","textTraditional":"一二六頁　六行　要（卻）〔劫〕也，　景祐、殿、局本都作「劫」，通鑑注引同。","sentenceOrder":289},
  {"id":"s_work_han_thu_5_290","chapterId":"ch_work_han_thu_5","textTraditional":"一二六頁　九行　右賢左戚，〔四〕先民後己，　注〔四〕原在「後己」下，王先謙說當在「左戚」下。","sentenceOrder":290},
  {"id":"s_work_han_thu_5_291","chapterId":"ch_work_han_thu_5","textTraditional":"一二九頁　九行　邊臣兵吏（入）〔又〕不能諭其內志，　景祐、殿本都作「又」，史記同。王先謙說作「又」是。","sentenceOrder":291},
  {"id":"s_work_han_thu_5_292","chapterId":"ch_work_han_thu_5","textTraditional":"一三０頁　五行　（返）〔反〕，還也。　景祐、殿本都作「反」。","sentenceOrder":292},
  {"id":"s_work_han_thu_5_293","chapterId":"ch_work_han_thu_5","textTraditional":"一三二頁　七行　（姪）〔絰〕帶無過三寸。　景祐、殿、局本都作「絰」，史記同。","sentenceOrder":293},
  {"id":"s_work_han_thu_5_294","chapterId":"ch_work_han_thu_5","textTraditional":"一三二頁　九行　禁無得擅哭（臨）。　李慈銘說史記無「臨」字，此誤衍。","sentenceOrder":294},
  {"id":"s_work_han_thu_5_295","chapterId":"ch_work_han_thu_5","textTraditional":"一三三頁　六行　直謂（四）方之內耳。　景祐、殿本都無「四」字。","sentenceOrder":295},
  {"id":"s_work_han_thu_6_1","chapterId":"ch_work_han_thu_6","textTraditional":"孝景皇帝，〔一〕文帝太子也。母曰竇皇后。後七年六月，文帝崩。丁未，太子即皇帝位，尊皇太后薄氏曰太皇太后，皇后曰皇太后。","sentenceOrder":1},
  {"id":"s_work_han_thu_6_2","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　荀悅曰：「諱啟之字曰開。」應劭曰：「禮諡法『布義行剛曰景』。」","sentenceOrder":2},
  {"id":"s_work_han_thu_6_3","chapterId":"ch_work_han_thu_6","textTraditional":"九月，有星孛于西方。","sentenceOrder":3},
  {"id":"s_work_han_thu_6_4","chapterId":"ch_work_han_thu_6","textTraditional":"元年冬十月，詔曰：「蓋聞古者祖有功而宗有德，〔一〕制禮樂各有由。歌者，所以發德也；舞者，所以明功也。高廟酎，〔二〕奏武德、文始、五行之舞。〔三〕孝惠廟酎，奏文始、五行之舞。孝文皇帝臨天下，通關梁，不異遠方；〔四〕除誹謗，去肉刑，賞賜長老，收恤孤獨，以遂群生；〔五〕減耆欲，不受獻，〔六〕罪人不帑，〔七〕不誅亡罪，不私其利也；除宮刑，出美人，重絕人之世也。朕既不敏，弗能勝識。〔八〕此皆上世之所不及，而孝文皇帝親行之。〔九〕德厚侔天地，利澤施四海，〔一０〕靡不獲福。明象乎日月，而廟樂不稱，朕甚懼焉。〔一一〕其為孝文皇帝廟為昭德之舞，〔一二〕以明休德。〔一三〕然后祖宗之功德，施于萬世，永永無窮，朕甚嘉之。其與丞相、列侯、中二千石、禮官具禮儀奏。」丞相臣嘉等奏曰：〔一四〕「陛下永思孝道，立昭德之舞以明孝文皇帝之盛德，皆臣嘉等愚所不及。臣謹議：世功莫大於高皇帝，德莫盛於孝文皇帝。高皇帝廟宜為帝者太祖之廟，孝文皇帝廟宜為帝諸太宗之廟。天子宜世世獻祖宗之廟。郡國諸侯宜各為孝文皇帝立太宗之廟。諸侯王列侯使者侍祠天子所獻祖宗之廟。〔一五〕請宣布天下。」制曰「可」。","sentenceOrder":4},
  {"id":"s_work_han_thu_6_5","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　應劭曰：「始取天下者為祖，高帝稱高祖是也。始治天下者為宗，文帝稱太宗是也。」師古曰：「應說非也。祖，始也，始受命也。宗，尊也，有德可尊。」","sentenceOrder":5},
  {"id":"s_work_han_thu_6_6","chapterId":"ch_work_han_thu_6","textTraditional":"〔二〕　張晏曰：「正月旦作酒，八月成，名曰酎。酎之言純也。至武帝時，因八月嘗酎會諸侯廟中，出金助祭，所謂酎金也。」師古曰：「酎，三重釀，醇酒也，味厚，故以薦宗廟。酎音直救反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_6_7","chapterId":"ch_work_han_thu_6","textTraditional":"〔三〕　孟康曰：「武德，高祖所作也。文始，舜舞也。五行，周舞也。武德者，其舞人執干戚。文始舞執羽籥。五行舞冠冕，衣服法五行色。見禮樂志。」","sentenceOrder":7},
  {"id":"s_work_han_thu_6_8","chapterId":"ch_work_han_thu_6","textTraditional":"〔四〕　張晏曰：「孝文十二年，除關不用傳，令遠近若一。」","sentenceOrder":8},
  {"id":"s_work_han_thu_6_9","chapterId":"ch_work_han_thu_6","textTraditional":"〔五〕　師古曰：「遂，成也，達也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_6_10","chapterId":"ch_work_han_thu_6","textTraditional":"〔六〕　師古曰：「耆讀曰嗜。」","sentenceOrder":10},
  {"id":"s_work_han_thu_6_11","chapterId":"ch_work_han_thu_6","textTraditional":"〔七〕　蘇林曰：「刑不及妻子。」師古曰：「帑讀與孥同。」","sentenceOrder":11},
  {"id":"s_work_han_thu_6_12","chapterId":"ch_work_han_thu_6","textTraditional":"〔八〕　師古曰：「敏，材智速疾也。勝識，盡知之。」","sentenceOrder":12},
  {"id":"s_work_han_thu_6_13","chapterId":"ch_work_han_thu_6","textTraditional":"〔九〕　師古曰：「上世，謂古昔之帝王也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_6_14","chapterId":"ch_work_han_thu_6","textTraditional":"〔一０〕師古曰：「侔，等也，音牟。」","sentenceOrder":14},
  {"id":"s_work_han_thu_6_15","chapterId":"ch_work_han_thu_6","textTraditional":"〔一一〕師古曰：「稱，副也，音尺孕反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_6_16","chapterId":"ch_work_han_thu_6","textTraditional":"〔一二〕師古曰：「昭，明也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_6_17","chapterId":"ch_work_han_thu_6","textTraditional":"〔一三〕師古曰：「休，美也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_6_18","chapterId":"ch_work_han_thu_6","textTraditional":"〔一四〕師古曰：「申屠嘉。」","sentenceOrder":18},
  {"id":"s_work_han_thu_6_19","chapterId":"ch_work_han_thu_6","textTraditional":"〔一五〕張晏曰：「王及列侯歲時遣使詣京師侍祠助祭。」如淳曰：「若光武廟在章陵，南陽太守稱使者往祭是也。不使侯王祭者，諸侯不得祖天子。凡臨祭宗廟皆為侍祭。」師古曰：「張說是也。既云天子所獻祖宗之廟，非謂郡國之廟也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_6_20","chapterId":"ch_work_han_thu_6","textTraditional":"春正月，詔曰：「間者歲比不登，民多乏食，夭絕天年，朕甚痛之。郡國或磽陿，無所農桑〈擊，去“手”〉畜；〔一〕或地饒廣，薦草莽，水泉利，而不得徙。〔二〕其議民欲徙寬大地者，聽之。」","sentenceOrder":20},
  {"id":"s_work_han_thu_6_21","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　師古曰：「磽謂磽埆瘠薄也。陿謂褊隘也。〈擊，去“手”〉謂食養之。畜謂牧放也。磽音苦交反。陿音狹。〈擊，去“手”〉古繫字。」","sentenceOrder":21},
  {"id":"s_work_han_thu_6_22","chapterId":"ch_work_han_thu_6","textTraditional":"〔二〕　如淳曰：「莊周云麋鹿食曰薦。一曰草稠曰薦，深曰莽。」","sentenceOrder":22},
  {"id":"s_work_han_thu_6_23","chapterId":"ch_work_han_thu_6","textTraditional":"夏四月，赦天下。賜民爵一級。","sentenceOrder":23},
  {"id":"s_work_han_thu_6_24","chapterId":"ch_work_han_thu_6","textTraditional":"遣御史大夫青翟至代下與匈奴和親。〔一〕","sentenceOrder":24},
  {"id":"s_work_han_thu_6_25","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　文穎曰：「姓嚴，諱青翟。」臣瓚曰：「此陶青也。莊青翟乃自武帝時人，此紀誤。」師古曰：「後人傳習不曉，妄增翟字耳，非本作紀之誤。」","sentenceOrder":25},
  {"id":"s_work_han_thu_6_26","chapterId":"ch_work_han_thu_6","textTraditional":"五月，令田半租。","sentenceOrder":26},
  {"id":"s_work_han_thu_6_27","chapterId":"ch_work_han_thu_6","textTraditional":"秋七月，詔曰：「吏受所監臨，以飲食免，重；受財物，賤買貴賣，論輕。〔一〕廷尉與丞相更議著令。」〔二〕廷尉信謹與丞相議曰：〔三〕「吏及諸有秩受其官屬所監、所治、所行、所將，〔四〕其與飲食計償費，勿論。〔五〕它物，若買故賤，賣故貴，皆坐臧為盜，沒入臧縣官。〔六〕吏遷徙免罷，受其故官屬所將監治送財物，奪爵為士伍，免之。〔七〕無爵，罰金二斤，令沒入所受。有能捕告，畀其所受臧。」〔八〕","sentenceOrder":27},
  {"id":"s_work_han_thu_6_28","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　師古曰：「帝以為當時律條吏受所監臨賂遺飲食，即坐免官爵，於法太重，而受所監臨財物及賤買貴賣者，論決太輕，故令更議改之。」","sentenceOrder":28},
  {"id":"s_work_han_thu_6_29","chapterId":"ch_work_han_thu_6","textTraditional":"〔二〕　蘇林曰：「著音著幘之著。」師古曰：「蘇音非也。著音著作之著，音竹箸反。」","sentenceOrder":29},
  {"id":"s_work_han_thu_6_30","chapterId":"ch_work_han_thu_6","textTraditional":"〔三〕　師古曰：「丞相申屠嘉。」","sentenceOrder":30},
  {"id":"s_work_han_thu_6_31","chapterId":"ch_work_han_thu_6","textTraditional":"〔四〕　師古曰：「行謂按察也，音下更反。」","sentenceOrder":31},
  {"id":"s_work_han_thu_6_32","chapterId":"ch_work_han_thu_6","textTraditional":"〔五〕　師古曰：「計其所費，而償其直，勿論罪也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_6_33","chapterId":"ch_work_han_thu_6","textTraditional":"〔六〕　師古曰：「它物，謂非飲食者。」","sentenceOrder":33},
  {"id":"s_work_han_thu_6_34","chapterId":"ch_work_han_thu_6","textTraditional":"〔七〕　李奇曰：「有爵者奪之，使為士伍，有位者免官也。」師古曰：「此說非也。謂奪其爵，令為士伍，又免其官職，即今律所謂除名也。謂之士伍者，言從士卒之伍也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_6_35","chapterId":"ch_work_han_thu_6","textTraditional":"〔八〕　師古曰：「畀，與也，以所受之臧與捕告者也。畀音必寐反。」","sentenceOrder":35},
  {"id":"s_work_han_thu_6_36","chapterId":"ch_work_han_thu_6","textTraditional":"二年冬十二月，有星孛于西南。","sentenceOrder":36},
  {"id":"s_work_han_thu_6_37","chapterId":"ch_work_han_thu_6","textTraditional":"令天下男子年二十始傅。〔一〕","sentenceOrder":37},
  {"id":"s_work_han_thu_6_38","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　師古曰：「舊法二十三，今此二十，更為異制也。傅讀曰附。解在高紀。」","sentenceOrder":38},
  {"id":"s_work_han_thu_6_39","chapterId":"ch_work_han_thu_6","textTraditional":"春三月，立皇子德為河間王，閼為臨江王，〔一〕餘為淮陽王，非為汝南王，彭祖為廣川王，發為長沙王。","sentenceOrder":39},
  {"id":"s_work_han_thu_6_40","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　師古曰：「閼音一曷反。」","sentenceOrder":40},
  {"id":"s_work_han_thu_6_41","chapterId":"ch_work_han_thu_6","textTraditional":"夏四月壬午，太皇太后崩。〔一〕","sentenceOrder":41},
  {"id":"s_work_han_thu_6_42","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　服虔曰：「文帝母薄太后也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_6_43","chapterId":"ch_work_han_thu_6","textTraditional":"六月，丞相嘉薨。","sentenceOrder":43},
  {"id":"s_work_han_thu_6_44","chapterId":"ch_work_han_thu_6","textTraditional":"封故相國蕭何孫係為列侯。〔一〕","sentenceOrder":44},
  {"id":"s_work_han_thu_6_45","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　師古曰：「係音胡計反。」","sentenceOrder":45},
  {"id":"s_work_han_thu_6_46","chapterId":"ch_work_han_thu_6","textTraditional":"秋，與匈奴和親。","sentenceOrder":46},
  {"id":"s_work_han_thu_6_47","chapterId":"ch_work_han_thu_6","textTraditional":"三年冬十二月，詔曰：「襄平侯嘉〔一〕子恢說不孝，謀反，欲以殺嘉，大逆無道。〔二〕其赦嘉為襄平侯，及妻子當坐者復故爵。〔三〕論恢說及妻子如法。」","sentenceOrder":47},
  {"id":"s_work_han_thu_6_48","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　晉灼曰：「紀通子也。功臣表襄平侯紀通以父功侯，孝景三年，康侯相夫嗣。推其封薨，正與此合，豈更名嘉乎？」","sentenceOrder":48},
  {"id":"s_work_han_thu_6_49","chapterId":"ch_work_han_thu_6","textTraditional":"〔二〕　晉灼曰：「恢說言嘉知反情，而實不知也。」師古曰：「此解非也。恢說有私怨於其父，而自謀反，欲令其父坐死也。說讀曰悅。」","sentenceOrder":49},
  {"id":"s_work_han_thu_6_50","chapterId":"ch_work_han_thu_6","textTraditional":"〔三〕　如淳曰：「律，大逆不道，父母妻子同產皆棄市。今赦其餘子不與恢說謀者，復其故爵。」","sentenceOrder":50},
  {"id":"s_work_han_thu_6_51","chapterId":"ch_work_han_thu_6","textTraditional":"春正月，淮陽王宮正殿災。","sentenceOrder":51},
  {"id":"s_work_han_thu_6_52","chapterId":"ch_work_han_thu_6","textTraditional":"吳王濞、膠西王卬、楚王戊、趙王遂、濟南王辟光、〔一〕菑川王賢、膠東王雄渠皆舉兵反。大赦天下。遣太尉亞夫、〔二〕大將軍竇嬰將兵擊之。斬御史大夫晁錯以謝七國。〔三〕","sentenceOrder":52},
  {"id":"s_work_han_thu_6_53","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　師古曰：「辟音壁，又音闢，其義兩通。」","sentenceOrder":53},
  {"id":"s_work_han_thu_6_54","chapterId":"ch_work_han_thu_6","textTraditional":"〔二〕　師古曰：「周亞夫。」","sentenceOrder":54},
  {"id":"s_work_han_thu_6_55","chapterId":"ch_work_han_thu_6","textTraditional":"〔三〕　晉灼曰：「錯音錯置之錯。」師古曰：「晁，古朝字。」","sentenceOrder":55},
  {"id":"s_work_han_thu_6_56","chapterId":"ch_work_han_thu_6","textTraditional":"二月壬子晦，日有食之。","sentenceOrder":56},
  {"id":"s_work_han_thu_6_57","chapterId":"ch_work_han_thu_6","textTraditional":"諸將破七國，斬首十餘萬級。追斬吳王濞於丹徒。膠西王卬、楚王戊、趙王遂、濟南王辟光、菑川王賢、膠東王雄渠皆自殺。夏六月，詔曰：「乃者吳王濞等為逆，起兵相脅，詿誤吏民，吏民不得已。〔一〕今濞等已滅，吏民當坐濞等及逋逃亡軍者，皆赦之。楚元王子蓺等與濞等為逆，〔二〕朕不忍加法，除其籍，毋令汙宗室。」立平陸侯劉禮為楚王，續元王後。〔三〕立皇子端為膠西王，勝為中山王。賜民爵一級。","sentenceOrder":57},
  {"id":"s_work_han_thu_6_58","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　師古曰：「已，止也，言不得止而從之，非本心也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_6_59","chapterId":"ch_work_han_thu_6","textTraditional":"〔二〕　師古曰：「蓺音藝。」","sentenceOrder":59},
  {"id":"s_work_han_thu_6_60","chapterId":"ch_work_han_thu_6","textTraditional":"〔三〕　孟康曰：「禮，元王子也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_6_61","chapterId":"ch_work_han_thu_6","textTraditional":"四年春，復置諸關用傳出入。〔一〕","sentenceOrder":61},
  {"id":"s_work_han_thu_6_62","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　應劭曰：「文帝十二年除關無用傳，至此復用傳。以七國新反，備非常。」","sentenceOrder":62},
  {"id":"s_work_han_thu_6_63","chapterId":"ch_work_han_thu_6","textTraditional":"夏四月己巳，立皇子榮為皇太子，徹為膠東王。","sentenceOrder":63},
  {"id":"s_work_han_thu_6_64","chapterId":"ch_work_han_thu_6","textTraditional":"六月，赦天下，賜民爵一級。","sentenceOrder":64},
  {"id":"s_work_han_thu_6_65","chapterId":"ch_work_han_thu_6","textTraditional":"秋七月，臨江王閼薨。","sentenceOrder":65},
  {"id":"s_work_han_thu_6_66","chapterId":"ch_work_han_thu_6","textTraditional":"十月戊戌晦，日有蝕之。","sentenceOrder":66},
  {"id":"s_work_han_thu_6_67","chapterId":"ch_work_han_thu_6","textTraditional":"五年春正月，作陽陵邑。〔一〕夏，募民徙陽陵，賜錢二十萬。","sentenceOrder":67},
  {"id":"s_work_han_thu_6_68","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　張晏曰：「景帝作壽陵，起邑。」","sentenceOrder":68},
  {"id":"s_work_han_thu_6_69","chapterId":"ch_work_han_thu_6","textTraditional":"遣公主嫁匈奴單于。","sentenceOrder":69},
  {"id":"s_work_han_thu_6_70","chapterId":"ch_work_han_thu_6","textTraditional":"六年冬十二月，雷，霖雨。","sentenceOrder":70},
  {"id":"s_work_han_thu_6_71","chapterId":"ch_work_han_thu_6","textTraditional":"秋九月，皇后薄氏廢。","sentenceOrder":71},
  {"id":"s_work_han_thu_6_72","chapterId":"ch_work_han_thu_6","textTraditional":"七年冬十一月庚寅晦，日有蝕之。","sentenceOrder":72},
  {"id":"s_work_han_thu_6_73","chapterId":"ch_work_han_thu_6","textTraditional":"春正月，廢皇太子榮為臨江王。","sentenceOrder":73},
  {"id":"s_work_han_thu_6_74","chapterId":"ch_work_han_thu_6","textTraditional":"二月，罷太尉官。","sentenceOrder":74},
  {"id":"s_work_han_thu_6_75","chapterId":"ch_work_han_thu_6","textTraditional":"夏四月乙巳，立皇后王氏。","sentenceOrder":75},
  {"id":"s_work_han_thu_6_76","chapterId":"ch_work_han_thu_6","textTraditional":"丁巳，立膠東王徹為皇太子。賜民為父後者爵一級。","sentenceOrder":76},
  {"id":"s_work_han_thu_6_77","chapterId":"ch_work_han_thu_6","textTraditional":"中元年夏四月，赦天下，賜民爵一級。封故御史大夫周苛、周昌孫子為列侯。〔一〕","sentenceOrder":77},
  {"id":"s_work_han_thu_6_78","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　師古曰：「封苛之孫及昌之子也。苛、昌皆嘗為御史大夫而從昆弟也，故總言之。」","sentenceOrder":78},
  {"id":"s_work_han_thu_6_79","chapterId":"ch_work_han_thu_6","textTraditional":"二年春二月，令諸侯王薨、列侯初封及之國，大鴻臚奏諡、誄、策。〔一〕列侯薨及諸侯太傅初除之官，大行奏諡、誄、策。〔二〕王薨，遣光祿大夫弔襚祠賵，〔三〕視喪事，因立嗣子。列侯薨，遣大中大夫弔祠，視喪事，因立嗣。其（薨）葬，國得發民輓喪，穿復土，治墳無過三百人畢事。〔四〕","sentenceOrder":79},
  {"id":"s_work_han_thu_6_80","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　應劭曰：「皇帝延諸侯王，賓王諸侯，皆屬大鴻臚。故其薨，奏其行跡，賜與諡及哀策誄文也。」臣瓚曰：「景帝此年已置大鴻臚，而百官表云武帝太初元年更以大行為大鴻臚，與此錯。」師古曰：「誄者，述累德行之文，音力水反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_6_81","chapterId":"ch_work_han_thu_6","textTraditional":"〔二〕　如淳曰：「凡言除者，除故官就新官也。」晉灼曰：「禮有大行人、小行人，主諡官，故以此名之。」臣瓚曰：「大行是官名，掌九儀之制以賓諸侯者。」師古曰：「大鴻臚者，本名典客，後改曰大鴻臚。大行令者，本名行人，即典客之屬官也，後改曰大行令。故事之尊重者遣大鴻臚，而輕賤者遣大行也。據此紀文，則景帝已改典客為大鴻臚，改行人為大行矣。而百官公卿表乃云景帝中六年更名典客為大行令，武帝太初元年更名大行令為大鴻臚，更名行人為大行令。當是表誤。」","sentenceOrder":81},
  {"id":"s_work_han_thu_6_82","chapterId":"ch_work_han_thu_6","textTraditional":"〔三〕　應劭曰：「衣服曰襚。祠，飲食也。車馬曰賵。」師古曰：「襚音遂。賵音芳鳳反。」","sentenceOrder":82},
  {"id":"s_work_han_thu_6_83","chapterId":"ch_work_han_thu_6","textTraditional":"〔四〕　師古曰：「輓謂引車也。畢事，畢葬事也。輓音晚。」","sentenceOrder":83},
  {"id":"s_work_han_thu_6_84","chapterId":"ch_work_han_thu_6","textTraditional":"匈奴入燕。","sentenceOrder":84},
  {"id":"s_work_han_thu_6_85","chapterId":"ch_work_han_thu_6","textTraditional":"改磔曰棄市，〔一〕勿復磔。","sentenceOrder":85},
  {"id":"s_work_han_thu_6_86","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　應劭曰：「先此諸死刑皆磔於市，今改曰棄市，自非妖逆不復磔也。」師古曰：「磔謂張其尸也。棄市，殺之於市也。謂之棄市者，取刑人於市，與眾棄之也。磔音竹客反。」","sentenceOrder":86},
  {"id":"s_work_han_thu_6_87","chapterId":"ch_work_han_thu_6","textTraditional":"三月，臨江王榮坐侵太宗廟地，徵詣中尉，自殺。","sentenceOrder":87},
  {"id":"s_work_han_thu_6_88","chapterId":"ch_work_han_thu_6","textTraditional":"夏四月，有星孛于西北。","sentenceOrder":88},
  {"id":"s_work_han_thu_6_89","chapterId":"ch_work_han_thu_6","textTraditional":"立皇子越為廣川王，寄為膠東王。","sentenceOrder":89},
  {"id":"s_work_han_thu_6_90","chapterId":"ch_work_han_thu_6","textTraditional":"秋七月，更郡守為太守，郡尉為都尉。〔一〕","sentenceOrder":90},
  {"id":"s_work_han_thu_6_91","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　師古曰：「更謂改其號。」","sentenceOrder":91},
  {"id":"s_work_han_thu_6_92","chapterId":"ch_work_han_thu_6","textTraditional":"九月，封故楚、趙傅相內史前死事者四人子〔一〕皆為列侯。","sentenceOrder":92},
  {"id":"s_work_han_thu_6_93","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　文穎曰：「楚相張尚，太傅趙夷吾。趙相建德，內史王悍。此四人各諫其王無使反，不聽，皆殺之，故封其子。」","sentenceOrder":93},
  {"id":"s_work_han_thu_6_94","chapterId":"ch_work_han_thu_6","textTraditional":"甲戌晦，日有蝕之。","sentenceOrder":94},
  {"id":"s_work_han_thu_6_95","chapterId":"ch_work_han_thu_6","textTraditional":"三年冬十一月，罷諸侯御史大夫官。〔一〕","sentenceOrder":95},
  {"id":"s_work_han_thu_6_96","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　師古曰：「所以抑損其權。」","sentenceOrder":96},
  {"id":"s_work_han_thu_6_97","chapterId":"ch_work_han_thu_6","textTraditional":"春正月，皇太后崩。〔一〕","sentenceOrder":97},
  {"id":"s_work_han_thu_6_98","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　文穎曰：「景帝母竇太后，以帝崩後六年乃亡。凡立五十一年，武帝建元六年崩。今此言皇太后崩，誤耳。」孟康曰：「此太后崩，史記無也。」臣瓚曰：「王楙云景帝薄后以此年死，疑是也。當言廢后，而言太后，誤也。」師古曰：「孟說是也。廢后死不書，又不言崩。瓚解為謬。」","sentenceOrder":98},
  {"id":"s_work_han_thu_6_99","chapterId":"ch_work_han_thu_6","textTraditional":"夏旱，禁酤酒。〔一〕秋九月，蝗。有星孛于西北。戊戌晦，日有蝕之。","sentenceOrder":99},
  {"id":"s_work_han_thu_6_100","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　師古曰：「酤謂賣酒也，音工護反。」","sentenceOrder":100},
  {"id":"s_work_han_thu_6_101","chapterId":"ch_work_han_thu_6","textTraditional":"立皇子乘為清河王。","sentenceOrder":101},
  {"id":"s_work_han_thu_6_102","chapterId":"ch_work_han_thu_6","textTraditional":"四年春三月，起德陽宮。〔一〕","sentenceOrder":102},
  {"id":"s_work_han_thu_6_103","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　臣瓚曰：「是景帝廟也。帝自作之，諱不言廟，故言宮。西京故事云景帝廟為德陽。」","sentenceOrder":103},
  {"id":"s_work_han_thu_6_104","chapterId":"ch_work_han_thu_6","textTraditional":"立皇子乘為清河王。","sentenceOrder":104},
  {"id":"s_work_han_thu_6_105","chapterId":"ch_work_han_thu_6","textTraditional":"御史大夫綰奏禁馬高五尺九寸以上，齒未平，不得出關。〔一〕","sentenceOrder":105},
  {"id":"s_work_han_thu_6_106","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　服虔曰：「綰，衛綰也。馬十歲，齒下平。」","sentenceOrder":106},
  {"id":"s_work_han_thu_6_107","chapterId":"ch_work_han_thu_6","textTraditional":"夏，蝗。","sentenceOrder":107},
  {"id":"s_work_han_thu_6_108","chapterId":"ch_work_han_thu_6","textTraditional":"秋，赦徒作陽陵者死罪；欲腐者，許之。〔一〕","sentenceOrder":108},
  {"id":"s_work_han_thu_6_109","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　蘇林曰：「宮刑，其創腐臭，故曰腐也。」如淳曰：「腐，宮刑也。丈夫割勢，不能復生子，如腐木不生實。」師古曰：「如說是。腐音輔。」","sentenceOrder":109},
  {"id":"s_work_han_thu_6_110","chapterId":"ch_work_han_thu_6","textTraditional":"十月戊午，日有蝕之。","sentenceOrder":110},
  {"id":"s_work_han_thu_6_111","chapterId":"ch_work_han_thu_6","textTraditional":"五年夏，立皇子舜為常山王。六月，赦天下，賜民爵一級。","sentenceOrder":111},
  {"id":"s_work_han_thu_6_112","chapterId":"ch_work_han_thu_6","textTraditional":"秋八月己酉，未央宮東闕災。","sentenceOrder":112},
  {"id":"s_work_han_thu_6_113","chapterId":"ch_work_han_thu_6","textTraditional":"更名諸侯丞相為相。〔一〕","sentenceOrder":113},
  {"id":"s_work_han_thu_6_114","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　師古曰：「亦所以抑黜之，令異於漢朝。」","sentenceOrder":114},
  {"id":"s_work_han_thu_6_115","chapterId":"ch_work_han_thu_6","textTraditional":"九月，詔曰：「法令度量，所以禁暴止邪也。獄，人之大命，死者不可復生。吏或不奉法令，以貨賂為市，朋黨比周，〔一〕以苛為察，以刻為明，令亡罪者失職，朕甚憐之。〔二〕有罪者不伏罪，姦法為暴，甚亡謂也。諸獄疑，若雖文致於法而於人心不厭者，輒讞之。」〔三〕","sentenceOrder":115},
  {"id":"s_work_han_thu_6_116","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　師古曰：「比音頻寐反。」","sentenceOrder":116},
  {"id":"s_work_han_thu_6_117","chapterId":"ch_work_han_thu_6","textTraditional":"〔二〕　師古曰：「職，常也。失其常理也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_6_118","chapterId":"ch_work_han_thu_6","textTraditional":"〔三〕　師古曰：「厭，服也，音一贍反。讞，平議也，音魚列反。」","sentenceOrder":118},
  {"id":"s_work_han_thu_6_119","chapterId":"ch_work_han_thu_6","textTraditional":"六年冬十月，行幸雍，郊五畤。","sentenceOrder":119},
  {"id":"s_work_han_thu_6_120","chapterId":"ch_work_han_thu_6","textTraditional":"十二月，改諸官名。定鑄錢偽黃金棄市律。〔一〕","sentenceOrder":120},
  {"id":"s_work_han_thu_6_121","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　應劭曰：「文帝五年，聽民放鑄，律尚未除。先時多作偽金，偽金終不可成，而徒損費，轉相誑耀，窮則起為盜賊，故定其律也。」孟康曰：「民先時多作偽金，故其語曰『金可作，世可度』。費損甚多而終不成。民亦稍知其意，犯者希，因此定律也。」師古曰：「應說是。」","sentenceOrder":121},
  {"id":"s_work_han_thu_6_122","chapterId":"ch_work_han_thu_6","textTraditional":"春三月，雨雪。〔一〕","sentenceOrder":122},
  {"id":"s_work_han_thu_6_123","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　師古曰：「雨音于具反。」","sentenceOrder":123},
  {"id":"s_work_han_thu_6_124","chapterId":"ch_work_han_thu_6","textTraditional":"夏四月，梁王薨，分梁為五國，立孝王子五人皆為王。","sentenceOrder":124},
  {"id":"s_work_han_thu_6_125","chapterId":"ch_work_han_thu_6","textTraditional":"五月，詔曰：「夫吏者，民之師也，車駕衣服宜稱。〔一〕吏六百石以上，皆長吏也，〔二〕亡度者或不吏服，出入閭里，與民亡異。令長吏二千石車朱兩轓，〔三〕千石至六百石朱左轓。車騎從者不稱其官衣服，下吏出入閭巷亡吏體者，二千石上其官屬，三輔舉不如法令者，〔四〕皆上丞相御史請之。」先是吏多軍功，車服尚輕，故為設禁。又惟酷吏奉憲失中，乃詔有司減笞法，定箠令。語在刑法志。〔五〕","sentenceOrder":125},
  {"id":"s_work_han_thu_6_126","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　師古曰：「稱其官也，音尺孕反。」","sentenceOrder":126},
  {"id":"s_work_han_thu_6_127","chapterId":"ch_work_han_thu_6","textTraditional":"〔二〕　張晏曰：「長，大也。六百石，位大夫。」","sentenceOrder":127},
  {"id":"s_work_han_thu_6_128","chapterId":"ch_work_han_thu_6","textTraditional":"〔三〕　應劭曰：「車耳反出，所以為之藩屏，翳塵泥也。二千石雙朱，其次乃偏其左。〈車反〉以簟為之，或用革。」如淳曰：「轓音反，小車兩屏也。」師古曰：「據許慎、李登說，轓，車之蔽也。左氏傳云『以藩載欒盈』，即是有鄣蔽之車也。言車耳反出，非矣。轓音甫元反。〈車反〉音方遠反。」","sentenceOrder":128},
  {"id":"s_work_han_thu_6_129","chapterId":"ch_work_han_thu_6","textTraditional":"〔四〕　應劭曰：「京兆尹、左馮翊、右扶風共治長安城中，是為三輔。」師古曰：「時未有京兆、馮翊、扶風之名。此三輔者，謂主爵中尉及左右內史也。應說失之。」","sentenceOrder":129},
  {"id":"s_work_han_thu_6_130","chapterId":"ch_work_han_thu_6","textTraditional":"〔五〕　師古曰：「箠音止蘂反。」","sentenceOrder":130},
  {"id":"s_work_han_thu_6_131","chapterId":"ch_work_han_thu_6","textTraditional":"六月，匈奴入鴈門，至武泉，入上郡，取苑馬。〔一〕吏卒戰死者二千人。","sentenceOrder":131},
  {"id":"s_work_han_thu_6_132","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　如淳曰：「漢儀注太僕牧師諸苑三十六所，分布北邊、西邊。以郎為苑監，官奴婢三萬人，養馬三十萬疋。」師古曰：「武泉，雲中之縣也。養鳥獸者通名為苑，故謂牧馬處為苑。」","sentenceOrder":132},
  {"id":"s_work_han_thu_6_133","chapterId":"ch_work_han_thu_6","textTraditional":"秋七月辛亥晦，日有蝕之。","sentenceOrder":133},
  {"id":"s_work_han_thu_6_134","chapterId":"ch_work_han_thu_6","textTraditional":"後元年春正月，詔曰：「獄，重事也。人有智愚，官有上下。獄疑者讞有司。有司所不能決，移廷尉。有令讞而後不當，讞者不為失。〔一〕欲令治獄者務先寬。」三月，赦天下，賜民爵一級，中二千石諸侯相爵右庶長。〔二〕夏，大酺五日，民得酤酒。","sentenceOrder":134},
  {"id":"s_work_han_thu_6_135","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　師古曰：「假令讞訖，其理不當，所讞之人不為罪失。」","sentenceOrder":135},
  {"id":"s_work_han_thu_6_136","chapterId":"ch_work_han_thu_6","textTraditional":"〔二〕　如淳曰：「雖有尊官未必有高爵，故數有賜爵。」師古曰：「右庶長，第十二爵也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_6_137","chapterId":"ch_work_han_thu_6","textTraditional":"五月，地震。秋七月乙巳晦，日有蝕之。","sentenceOrder":137},
  {"id":"s_work_han_thu_6_138","chapterId":"ch_work_han_thu_6","textTraditional":"條侯周亞夫下獄死。","sentenceOrder":138},
  {"id":"s_work_han_thu_6_139","chapterId":"ch_work_han_thu_6","textTraditional":"二年冬十月，省徹侯之國。〔一〕","sentenceOrder":139},
  {"id":"s_work_han_thu_6_140","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　晉灼曰：「文紀遣列侯之國，今省之。」師古曰：「省音所領反。」","sentenceOrder":140},
  {"id":"s_work_han_thu_6_141","chapterId":"ch_work_han_thu_6","textTraditional":"春，匈奴入鴈門，太守馮敬與戰死。發車騎材官屯。〔一〕","sentenceOrder":141},
  {"id":"s_work_han_thu_6_142","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　師古曰：「屯鴈門。」","sentenceOrder":142},
  {"id":"s_work_han_thu_6_143","chapterId":"ch_work_han_thu_6","textTraditional":"春，以歲不登，禁內郡食馬粟，沒入之。〔一〕","sentenceOrder":143},
  {"id":"s_work_han_thu_6_144","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　師古曰：「食讀曰飤。沒入者，沒入其馬。」","sentenceOrder":144},
  {"id":"s_work_han_thu_6_145","chapterId":"ch_work_han_thu_6","textTraditional":"夏四月，詔曰：「雕文刻鏤，傷農事者也；錦繡纂組，害女紅者也。〔一〕農事傷則飢之本也，女紅害則寒之原也。夫飢寒並至，而能亡為非者寡矣。朕親耕，后親桑，以奉宗廟粢盛祭服，為天下先；不受獻，減太官，省繇賦，〔二〕欲天下務農蠶，素有畜積，以備災害。〔三〕彊毋攘弱，眾毋暴寡，〔四〕老耆以壽終，幼孤得遂長。〔五〕今歲或不登，民食頗寡，其咎安在？或詐偽為吏，〔六〕吏以貨賂為市，漁奪百姓，侵牟萬民。〔七〕縣丞，長吏也，奸法與盜盜，甚無謂也。〔八〕其令二千石修其職；不事官職耗亂者，丞相以聞，請其罪。〔九〕布告天下，使明知朕意。」","sentenceOrder":145},
  {"id":"s_work_han_thu_6_146","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　應劭曰：「纂，今五采屬綷是也。組者，今綬紛絛是也。」臣瓚曰：「許慎云『纂，赤組也』。」師古曰：「瓚說是也。綷，會也。會五綵者，今謂之錯綵，非纂也。紅讀曰功。綷音子內反。絛音它牢反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_6_147","chapterId":"ch_work_han_thu_6","textTraditional":"〔二〕　師古曰：「省音所領反。繇讀曰傜。」","sentenceOrder":147},
  {"id":"s_work_han_thu_6_148","chapterId":"ch_work_han_thu_6","textTraditional":"〔三〕　師古曰：「畜讀曰蓄。」","sentenceOrder":148},
  {"id":"s_work_han_thu_6_149","chapterId":"ch_work_han_thu_6","textTraditional":"〔四〕　師古曰：「攘，取也，音人羊反。」","sentenceOrder":149},
  {"id":"s_work_han_thu_6_150","chapterId":"ch_work_han_thu_6","textTraditional":"〔五〕　師古曰：「遂，成也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_6_151","chapterId":"ch_work_han_thu_6","textTraditional":"〔六〕　張晏曰：「以詐偽人為吏也。」臣瓚曰：「律所謂矯枉以為吏者也。」師古曰：「二說並非也。直謂詐自稱吏耳。」","sentenceOrder":151},
  {"id":"s_work_han_thu_6_152","chapterId":"ch_work_han_thu_6","textTraditional":"〔七〕　李奇曰：「牟，食苗根蟲也。侵牟食民，比之蛑賊也。」師古曰：「漁言若漁獵之為也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_6_153","chapterId":"ch_work_han_thu_6","textTraditional":"〔八〕　李斐曰：「奸法，因法作奸也。」文穎曰：「與盜，謂盜者當治，而知情反佐與之，是則共盜無異也。」師古曰：「與盜盜者，共盜為盜耳。」","sentenceOrder":153},
  {"id":"s_work_han_thu_6_154","chapterId":"ch_work_han_thu_6","textTraditional":"〔九〕　師古曰：「耗，不明也，讀與眊同，音莫報反。」","sentenceOrder":154},
  {"id":"s_work_han_thu_6_155","chapterId":"ch_work_han_thu_6","textTraditional":"五月，詔曰：「人不患其不知，患其為詐也；不患其不勇，患其為暴也；不患其不富，患其亡厭也。其唯廉士，寡欲易足。今訾算十以上乃得宦，〔一〕廉士算不必眾。有市籍不得宦，無訾又不得宦，朕甚愍之。訾算四得宦，亡令廉士久失職，貪夫長利。」〔二〕","sentenceOrder":155},
  {"id":"s_work_han_thu_6_156","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　服虔曰：「訾萬錢，算百二十七也。」應劭曰：「古者疾吏之貪，衣食足知榮辱，限訾十算乃得為吏。十算，十萬也。賈人有財不得為吏，廉士無訾又不得宦，故減訾四算得宦矣。」師古曰：「訾讀與貲同。他皆類此。」","sentenceOrder":156},
  {"id":"s_work_han_thu_6_157","chapterId":"ch_work_han_thu_6","textTraditional":"〔二〕　師古曰：「長利，長獲其利。」","sentenceOrder":157},
  {"id":"s_work_han_thu_6_158","chapterId":"ch_work_han_thu_6","textTraditional":"秋，大旱。","sentenceOrder":158},
  {"id":"s_work_han_thu_6_159","chapterId":"ch_work_han_thu_6","textTraditional":"三年春正月，詔曰：「農，天下之本也。黃金珠玉，飢不可食，寒不可衣，以為幣用，不識其終始。〔一〕間歲或不登，意為末者眾，農民寡也。其令郡國務勸農桑，益種樹，可得衣食物。〔二〕吏發民若取庸采黃金珠玉者，坐臧為盜。〔三〕二千石聽者，與同罪。」","sentenceOrder":159},
  {"id":"s_work_han_thu_6_160","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　師古曰：「幣者，所以通有無，易貴賤也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_6_161","chapterId":"ch_work_han_thu_6","textTraditional":"〔二〕　師古曰：「樹，殖也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_6_162","chapterId":"ch_work_han_thu_6","textTraditional":"〔三〕　韋昭曰：「發民，用其民。取庸，用其資以顧庸。」","sentenceOrder":162},
  {"id":"s_work_han_thu_6_163","chapterId":"ch_work_han_thu_6","textTraditional":"皇太子冠，賜民為父後者爵一級。","sentenceOrder":163},
  {"id":"s_work_han_thu_6_164","chapterId":"ch_work_han_thu_6","textTraditional":"甲子，帝崩于未央宮。〔一〕遺詔賜諸侯王列侯馬二駟，〔二〕吏二千石黃金二斤，吏民戶百錢。出宮人歸其家，復終身。〔三〕二月癸酉，葬陽陵。〔四〕","sentenceOrder":164},
  {"id":"s_work_han_thu_6_165","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　臣瓚曰：「帝年三十二即位，即位十六年，壽四十八。」","sentenceOrder":165},
  {"id":"s_work_han_thu_6_166","chapterId":"ch_work_han_thu_6","textTraditional":"〔二〕　師古曰：「八匹也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_6_167","chapterId":"ch_work_han_thu_6","textTraditional":"〔三〕　師古曰：「復音方目反。」","sentenceOrder":167},
  {"id":"s_work_han_thu_6_168","chapterId":"ch_work_han_thu_6","textTraditional":"〔四〕　臣瓚曰：「自崩及葬凡十日。陽陵在長安東北四十五里。」","sentenceOrder":168},
  {"id":"s_work_han_thu_6_169","chapterId":"ch_work_han_thu_6","textTraditional":"贊曰：孔子稱「斯民，三代之所以直道而行也」，〔一〕信哉！周秦之敝，罔密文峻，而姦軌不勝。〔二〕漢興，掃除煩苛，與民休息。至于孝文，加之以恭儉，孝景遵業，五六十載之間，至於移風易俗，黎民醇厚。〔三〕周云成康，漢言文景，美矣！","sentenceOrder":169},
  {"id":"s_work_han_thu_6_170","chapterId":"ch_work_han_thu_6","textTraditional":"〔一〕　師古曰：「此論語載孔子之辭也。言此今時之人，亦夏、殷、周之所馭，以政化淳壹，故能直道而行。傷今不然。」","sentenceOrder":170},
  {"id":"s_work_han_thu_6_171","chapterId":"ch_work_han_thu_6","textTraditional":"〔二〕　師古曰：「不可勝。」","sentenceOrder":171},
  {"id":"s_work_han_thu_6_172","chapterId":"ch_work_han_thu_6","textTraditional":"〔三〕　師古曰：「黎，眾也。醇，不澆雜。」","sentenceOrder":172},
  {"id":"s_work_han_thu_6_173","chapterId":"ch_work_han_thu_6","textTraditional":"校勘記","sentenceOrder":173},
  {"id":"s_work_han_thu_6_174","chapterId":"ch_work_han_thu_6","textTraditional":"一四五頁　三行　其（薨）葬，　王念孫說「薨」字涉上文四「薨」字而衍。薨事已見上文，此文則專指葬事，故師古云「畢事，畢葬事也」。","sentenceOrder":174},
  {"id":"s_work_han_thu_7_1","chapterId":"ch_work_han_thu_7","textTraditional":"孝武皇帝，〔一〕景帝中子也，母曰王美人。〔二〕年四歲立為膠東王。七歲為皇太子，母為皇后。十六歲，後三年正月，景帝崩。〔三〕甲子，太子即皇帝位，尊皇太后竇氏曰太皇太后，皇后曰皇太后。三月，封皇太后同母弟田蚡、勝皆為列侯。〔四〕","sentenceOrder":1},
  {"id":"s_work_han_thu_7_2","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　荀悅曰：「諱徹之字曰通。」應劭曰：「禮諡法『威強叡德曰武』。」","sentenceOrder":2},
  {"id":"s_work_han_thu_7_3","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「外戚傳美人比二千石，視少上造。」","sentenceOrder":3},
  {"id":"s_work_han_thu_7_4","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　張晏曰：「武帝以景帝元年生，七歲為太子，為太子十歲而景帝崩，時年十六矣。」師古曰：「後三年，景帝後三年也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_7_5","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　蘇林曰：「蚡音鼢鼠之鼢。」師古曰：「蚡亦鼢鼠字也，音扶粉反。」","sentenceOrder":5},
  {"id":"s_work_han_thu_7_6","chapterId":"ch_work_han_thu_7","textTraditional":"建元元年〔一〕冬十月，詔丞相、御史、列侯、中二千石、二千石、諸侯相舉賢良方正直言極諫之士。丞相綰〔二〕奏：「所舉賢良，或治申、商、韓非、蘇秦、張儀之言，〔三〕亂國政，請皆罷。」奏可。","sentenceOrder":6},
  {"id":"s_work_han_thu_7_7","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「自古帝王未有年號，始起於此。」","sentenceOrder":7},
  {"id":"s_work_han_thu_7_8","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「衛綰也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_7_9","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　應劭曰：「申不害，韓昭侯相也。衛公孫鞅為秦孝公相，封於商，號商君。韓非，韓諸公子，非，名也。蘇秦為關東從長。張儀為秦昭王相，為衡說以抑諸侯。」李奇曰：「申不害書執術。商鞅為法，賞不失卑，刑不諱尊，然深刻無恩德。韓非兼行申、商之術。」師古曰：「從音子容反。」","sentenceOrder":9},
  {"id":"s_work_han_thu_7_10","chapterId":"ch_work_han_thu_7","textTraditional":"春二月，赦天下，賜民爵一級。年八十復二算，九十復甲卒〔一〕。行三銖錢。〔二〕","sentenceOrder":10},
  {"id":"s_work_han_thu_7_11","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　張晏曰：「二算，復二口之算也。復甲卒，不豫革車之賦也。」師古曰：「復音方目反。」","sentenceOrder":11},
  {"id":"s_work_han_thu_7_12","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「新壞四銖錢造此錢也，重如其文。見食貨志。」","sentenceOrder":12},
  {"id":"s_work_han_thu_7_13","chapterId":"ch_work_han_thu_7","textTraditional":"夏四月己巳，詔曰：「古之立教，鄉里以齒，朝廷以爵，扶世導民，莫善於德。然則於鄉里先耆艾，奉高年，古之道也。〔一〕今天下孝子順孫願自竭盡以承其親，外迫公事，內乏資財，是以孝心闕焉。朕甚哀之。民年九十以上，已有受鬻法，〔二〕為復子若孫，令得身帥妻妾遂其供養之事。」〔三〕","sentenceOrder":13},
  {"id":"s_work_han_thu_7_14","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「六十曰耆，五十曰艾。」","sentenceOrder":14},
  {"id":"s_work_han_thu_7_15","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「給米粟以為糜鬻。鬻音之六反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_7_16","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　師古曰：「若者，豫及之辭也。有子即復子，無子即復孫也。遂，（中）〔申〕也。復音方目反。」","sentenceOrder":16},
  {"id":"s_work_han_thu_7_17","chapterId":"ch_work_han_thu_7","textTraditional":"五月，詔曰：「河海潤千里，其令祠官修山川之祠，為歲事〔一〕，曲加禮。」〔二〕","sentenceOrder":17},
  {"id":"s_work_han_thu_7_18","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　孟康曰：「為農祈也。於此造之，歲以為常，故曰為歲事也。」師古曰：「歲以為常是也。總致敬耳，非止祈農。」","sentenceOrder":18},
  {"id":"s_work_han_thu_7_19","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　如淳曰：「祭禮有所加益。」","sentenceOrder":19},
  {"id":"s_work_han_thu_7_20","chapterId":"ch_work_han_thu_7","textTraditional":"赦吳楚七國帑輸在官者。〔一〕","sentenceOrder":20},
  {"id":"s_work_han_thu_7_21","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「吳楚七國反時，其首事者妻子沒入為官奴婢，武帝哀焉，皆赦遣之也。」師古曰：「帑讀與孥同。」","sentenceOrder":21},
  {"id":"s_work_han_thu_7_22","chapterId":"ch_work_han_thu_7","textTraditional":"秋七月，詔曰：「衛士轉置送迎二萬人，〔一〕其省萬人。罷苑馬，以賜貧民。」〔二〕","sentenceOrder":22},
  {"id":"s_work_han_thu_7_23","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　鄭氏曰：「去故置新，常二萬人。」","sentenceOrder":23},
  {"id":"s_work_han_thu_7_24","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「養馬之苑，舊禁百姓不得芻牧采樵，今罷之。」","sentenceOrder":24},
  {"id":"s_work_han_thu_7_25","chapterId":"ch_work_han_thu_7","textTraditional":"議立明堂。遣使者安車蒲輪，束帛加璧，徵魯申公。〔一〕","sentenceOrder":25},
  {"id":"s_work_han_thu_7_26","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「以蒲裹輪，取其安也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_7_27","chapterId":"ch_work_han_thu_7","textTraditional":"二年冬十月，御史大夫趙綰坐請毋奏事太皇太后，及郎中令王臧皆下獄，自殺。〔一〕丞相嬰、太尉蚡免。〔二〕","sentenceOrder":27},
  {"id":"s_work_han_thu_7_28","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「禮，婦人不豫政事，時帝已自躬省萬機。王臧儒者，欲立明堂辟雍。太后素好黃老術，非薄五經。因欲絕奏事太后，太后怒，故殺之。」","sentenceOrder":28},
  {"id":"s_work_han_thu_7_29","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「竇嬰、田蚡。」","sentenceOrder":29},
  {"id":"s_work_han_thu_7_30","chapterId":"ch_work_han_thu_7","textTraditional":"春二月丙戌朔，日有蝕之。夏四月戊申，有如日夜出。","sentenceOrder":30},
  {"id":"s_work_han_thu_7_31","chapterId":"ch_work_han_thu_7","textTraditional":"初置茂陵邑。〔一〕","sentenceOrder":31},
  {"id":"s_work_han_thu_7_32","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「武帝自作陵也。」師古曰：「本槐里（之縣）〔縣之〕茂鄉，故曰茂陵。」","sentenceOrder":32},
  {"id":"s_work_han_thu_7_33","chapterId":"ch_work_han_thu_7","textTraditional":"三年春，河水溢于平原，大飢，人相食。〔一〕","sentenceOrder":33},
  {"id":"s_work_han_thu_7_34","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「河溢之處損害田畝，故大飢。」","sentenceOrder":34},
  {"id":"s_work_han_thu_7_35","chapterId":"ch_work_han_thu_7","textTraditional":"賜徙茂陵者戶錢二十萬，田二頃。初作便門橋。〔一〕","sentenceOrder":35},
  {"id":"s_work_han_thu_7_36","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　蘇林曰：「去長安四十里。」服虔曰：「在長安西北，茂陵東。」師古曰：「便門，長安城北面西頭門，即平門也。古者平便皆同字。於此道作橋，跨渡渭水以趨茂陵，其道易直，即今所謂便橋是其處也。便讀如本字。」","sentenceOrder":36},
  {"id":"s_work_han_thu_7_37","chapterId":"ch_work_han_thu_7","textTraditional":"秋七月，有星孛于西北。","sentenceOrder":37},
  {"id":"s_work_han_thu_7_38","chapterId":"ch_work_han_thu_7","textTraditional":"濟川王明坐殺太傅、中傅廢遷防陵。〔一〕","sentenceOrder":38},
  {"id":"s_work_han_thu_7_39","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「中傅，宦者也。」師古曰：「防陵，漢中縣也，今謂之房州。」","sentenceOrder":39},
  {"id":"s_work_han_thu_7_40","chapterId":"ch_work_han_thu_7","textTraditional":"閩越圍東甌，〔一〕東甌告急。遣中大夫嚴助持節發會稽兵，浮海救之。未至，閩越走，兵還。","sentenceOrder":40},
  {"id":"s_work_han_thu_7_41","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「高祖五年立無諸為閩越王。惠帝立搖為東海王，都東甌，故號東甌。」師古曰：「甌音一侯反。」","sentenceOrder":41},
  {"id":"s_work_han_thu_7_42","chapterId":"ch_work_han_thu_7","textTraditional":"九月丙子晦，日有蝕之。","sentenceOrder":42},
  {"id":"s_work_han_thu_7_43","chapterId":"ch_work_han_thu_7","textTraditional":"四年夏，有風赤如血。六月，旱。秋九月，有星孛于東北。","sentenceOrder":43},
  {"id":"s_work_han_thu_7_44","chapterId":"ch_work_han_thu_7","textTraditional":"五年春，罷三銖錢，行半兩錢。〔一〕","sentenceOrder":44},
  {"id":"s_work_han_thu_7_45","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「又新鑄作也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_7_46","chapterId":"ch_work_han_thu_7","textTraditional":"置五經博士。","sentenceOrder":46},
  {"id":"s_work_han_thu_7_47","chapterId":"ch_work_han_thu_7","textTraditional":"夏四月，平原君薨。〔一〕","sentenceOrder":47},
  {"id":"s_work_han_thu_7_48","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　服虔曰：「王太后之母，武帝外祖母。」","sentenceOrder":48},
  {"id":"s_work_han_thu_7_49","chapterId":"ch_work_han_thu_7","textTraditional":"五月，大蝗。","sentenceOrder":49},
  {"id":"s_work_han_thu_7_50","chapterId":"ch_work_han_thu_7","textTraditional":"秋八月，廣川王越、清河王乘皆薨。","sentenceOrder":50},
  {"id":"s_work_han_thu_7_51","chapterId":"ch_work_han_thu_7","textTraditional":"六年春二月乙未，遼東高廟災。夏四月壬子，高園便殿火。〔一〕上素服五日。","sentenceOrder":51},
  {"id":"s_work_han_thu_7_52","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「凡言便殿、便室、便坐者，皆非正大之處，所以就便安也。園者，於陵上作之，既有正寢以象平生正殿，又立便殿為休息閑宴之處耳。說者不曉其意，乃解云便殿、便室皆是正名，斯大惑矣。尋石建、韋玄成、孔光等傳，其義可知。便讀如本字。」","sentenceOrder":52},
  {"id":"s_work_han_thu_7_53","chapterId":"ch_work_han_thu_7","textTraditional":"五月丁亥，太皇太后崩。","sentenceOrder":53},
  {"id":"s_work_han_thu_7_54","chapterId":"ch_work_han_thu_7","textTraditional":"秋八月，有星孛于東方，長竟天。","sentenceOrder":54},
  {"id":"s_work_han_thu_7_55","chapterId":"ch_work_han_thu_7","textTraditional":"閩越王郢攻南越。遣大行王恢將兵出豫章，大司農韓安國出會稽，擊之。未至，越人殺郢降，兵還。","sentenceOrder":55},
  {"id":"s_work_han_thu_7_56","chapterId":"ch_work_han_thu_7","textTraditional":"元光元年〔一〕冬十一月，初令郡國舉孝廉各一人。〔二〕","sentenceOrder":56},
  {"id":"s_work_han_thu_7_57","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　臣瓚曰：「以長星見，故為元光。」","sentenceOrder":57},
  {"id":"s_work_han_thu_7_58","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「孝謂善事父母者。廉謂清潔有廉隅者。」","sentenceOrder":58},
  {"id":"s_work_han_thu_7_59","chapterId":"ch_work_han_thu_7","textTraditional":"衛尉李廣為驍騎將軍屯雲中，中尉程不識為車騎將軍屯鴈門，六月罷。","sentenceOrder":59},
  {"id":"s_work_han_thu_7_60","chapterId":"ch_work_han_thu_7","textTraditional":"夏四月，赦天下，賜民長子爵一級。復七國宗室前絕屬者。〔一〕","sentenceOrder":60},
  {"id":"s_work_han_thu_7_61","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「此等宗室前坐七國反，故絕屬。今加恩赦之，更令上屬籍於宗正也。復音扶目反。」","sentenceOrder":61},
  {"id":"s_work_han_thu_7_62","chapterId":"ch_work_han_thu_7","textTraditional":"五月，詔賢良曰：「朕聞昔在唐虞，畫象而民不犯，〔一〕日月所燭，莫不率俾。〔二〕周之成康，刑錯不用，〔三〕德及鳥獸，教通四海。海外肅眘，〔四〕北發渠搜，〔五〕氐羌徠服。〔六〕星辰不孛，日月不蝕，山陵不崩，川谷不塞；麟鳳在郊藪，河洛出圖書。嗚虖，何施而臻此與！〔七〕今朕獲奉宗廟，夙興以求，夜寐以思，〔八〕若涉淵水，未知所濟。猗與偉與！〔九〕何行而可以章先帝之洪業休德，〔一０〕上參堯舜，下配三王！〔一一〕朕之不敏，不能遠德，〔一二〕此子大夫之所睹聞也。〔一三〕賢良明於古今王事之體，受策察問，咸以書對，著之於篇，〔一四〕朕親覽焉。」於是董仲舒、公孫弘等出焉。","sentenceOrder":62},
  {"id":"s_work_han_thu_7_63","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「二帝但畫衣冠，異章服，而民不敢犯也。」師古曰：「白虎通云『畫象者，其衣服象五刑也。犯墨者蒙巾，犯劓者以赭著其衣，犯髕者以墨蒙其髕象而畫之，犯宮者屝，犯大辟者布衣無領。』墨謂以墨黥其面也。劓，截其鼻也。髕，去膝蓋骨也。宮，割其陰也。屝，草屨也。劓音牛冀反，字或作〈臬刂〉，其音同耳。髕音頻忍反。屝音扶味反。」","sentenceOrder":63},
  {"id":"s_work_han_thu_7_64","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「燭，照也。率，循也。俾，使也。言皆循其貢職而可使也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_7_65","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　師古曰：「錯，置也，音千故反。」","sentenceOrder":65},
  {"id":"s_work_han_thu_7_66","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　晉灼曰：「東夷傳今挹婁地是也，在夫餘之東北千餘里大海之濱。」師古曰：「周書序云『成王既伐東夷，肅眘來賀』，即謂此。」","sentenceOrder":66},
  {"id":"s_work_han_thu_7_67","chapterId":"ch_work_han_thu_7","textTraditional":"〔五〕　服虔曰：「地名也。」應劭曰：「禹貢析支、渠搜屬雍州，在金城河關之西，西戎也。」晉灼曰：「王恢傳『北發、月支可得而臣』，似國名也。地理志朔方有渠搜縣。」臣瓚曰：「孔子三朝記云『北發渠搜，南撫交阯』，此舉北以南為對也。禹貢渠搜在雍州西北。渠搜在朔方。」師古曰：「北發，非國名也，言北方即可徵發渠搜而役屬之。瓚說近是。」","sentenceOrder":67},
  {"id":"s_work_han_thu_7_68","chapterId":"ch_work_han_thu_7","textTraditional":"〔六〕　師古曰：「徠，古往來之字也。氐音丁奚反。」","sentenceOrder":68},
  {"id":"s_work_han_thu_7_69","chapterId":"ch_work_han_thu_7","textTraditional":"〔七〕　師古曰：「虖讀曰呼。嗚呼，歎辭也。臻，至也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_7_70","chapterId":"ch_work_han_thu_7","textTraditional":"〔八〕　師古曰：「夙興，早起也。夜寐，夜久方寐也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_7_71","chapterId":"ch_work_han_thu_7","textTraditional":"〔九〕　師古曰：「猗，美也。偉，大也。與，辭也。言美而且大也。與讀曰歟，音弋於反。」","sentenceOrder":71},
  {"id":"s_work_han_thu_7_72","chapterId":"ch_work_han_thu_7","textTraditional":"〔一０〕師古曰：「章，明也。洪，大也。休，美也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_7_73","chapterId":"ch_work_han_thu_7","textTraditional":"〔一一〕師古曰：「三王，夏、殷、周。」","sentenceOrder":73},
  {"id":"s_work_han_thu_7_74","chapterId":"ch_work_han_thu_7","textTraditional":"〔一二〕師古曰：「言德不及遠也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_7_75","chapterId":"ch_work_han_thu_7","textTraditional":"〔一三〕師古曰：「子者，人之嘉稱。大夫，舉官稱也。志在優賢，故謂之子大夫也。睹，古睹字。」","sentenceOrder":75},
  {"id":"s_work_han_thu_7_76","chapterId":"ch_work_han_thu_7","textTraditional":"〔一四〕師古曰：「篇謂竹簡也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_7_77","chapterId":"ch_work_han_thu_7","textTraditional":"秋七月癸未，日有蝕之。","sentenceOrder":77},
  {"id":"s_work_han_thu_7_78","chapterId":"ch_work_han_thu_7","textTraditional":"二年冬十月，行幸雍，祠五畤。〔一〕","sentenceOrder":78},
  {"id":"s_work_han_thu_7_79","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「五帝之畤也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_7_80","chapterId":"ch_work_han_thu_7","textTraditional":"春，詔問公卿曰：「朕飾子女以配單于，金幣文繡賂之甚厚，單于待命加嫚，侵盜亡已。〔一〕邊境被害，朕甚閔之。今欲舉兵攻之，何如？」大行王恢建議宜擊。夏六月，御史大夫韓安國為護軍將軍，衛尉李廣為驍騎將軍，太僕公孫賀為輕車將軍，大行王恢為將屯將軍，（大）〔太〕中大夫李息為材官將軍，將三十萬眾屯馬邑谷中，誘致單于，欲襲擊之。單于入塞，覺之，走出。六月，軍罷。將軍王恢坐首謀不進，下獄死。〔二〕","sentenceOrder":80},
  {"id":"s_work_han_thu_7_81","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「待命，謂承詔命也。嫚與慢同。」","sentenceOrder":81},
  {"id":"s_work_han_thu_7_82","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「首為此謀，而反不進擊匈奴輜重。」","sentenceOrder":82},
  {"id":"s_work_han_thu_7_83","chapterId":"ch_work_han_thu_7","textTraditional":"秋九月，令民大酺五日。","sentenceOrder":83},
  {"id":"s_work_han_thu_7_84","chapterId":"ch_work_han_thu_7","textTraditional":"三年春，河水徙，從頓丘東南流入勃海。〔一〕","sentenceOrder":84},
  {"id":"s_work_han_thu_7_85","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「頓丘，丘名，因以為縣，本衛地也。地理志屬東郡，今則在魏州界也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_7_86","chapterId":"ch_work_han_thu_7","textTraditional":"夏五月，封高祖功臣五人後為列侯。","sentenceOrder":86},
  {"id":"s_work_han_thu_7_87","chapterId":"ch_work_han_thu_7","textTraditional":"河水決濮陽，氾郡十六。〔一〕發卒十萬救決河。起龍淵宮〔二〕。","sentenceOrder":87},
  {"id":"s_work_han_thu_7_88","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「濮陽，東郡之縣也。水所氾及，凡十六郡界也。氾音敷劍反。」","sentenceOrder":88},
  {"id":"s_work_han_thu_7_89","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　服虔曰：「宮在長安西，作銅飛龍，故以冠名也。」如淳曰：「三輔黃圖云有龍淵宮，今長安城西有其處。溝洫志救河決亦起龍淵宮於其傍。」孟康曰：「在西平界，其水可用淬刀劍，特堅利。古龍淵之劍取於此水。」師古曰：「黃圖云龍淵廟在茂陵東，不言宮也。此言救決河，起龍淵宮，則宮不在長安之西矣。又漢章帝賜尚書韓稜龍淵劍。孟說是也。淬音千內反。」","sentenceOrder":89},
  {"id":"s_work_han_thu_7_90","chapterId":"ch_work_han_thu_7","textTraditional":"四年冬，魏其侯竇嬰有罪，棄巿。〔一〕","sentenceOrder":90},
  {"id":"s_work_han_thu_7_91","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「以黨灌夫也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_7_92","chapterId":"ch_work_han_thu_7","textTraditional":"春三月乙卯，丞相蚡薨。","sentenceOrder":92},
  {"id":"s_work_han_thu_7_93","chapterId":"ch_work_han_thu_7","textTraditional":"夏四月，隕霜殺草。五月，地震。赦天下。","sentenceOrder":93},
  {"id":"s_work_han_thu_7_94","chapterId":"ch_work_han_thu_7","textTraditional":"五年春正月，河間王德薨。","sentenceOrder":94},
  {"id":"s_work_han_thu_7_95","chapterId":"ch_work_han_thu_7","textTraditional":"夏，發巴蜀治南夷道，又發卒萬人治雁門阻險。〔一〕","sentenceOrder":95},
  {"id":"s_work_han_thu_7_96","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「所以為固，用止匈奴之寇。」","sentenceOrder":96},
  {"id":"s_work_han_thu_7_97","chapterId":"ch_work_han_thu_7","textTraditional":"秋七月，大風拔木。","sentenceOrder":97},
  {"id":"s_work_han_thu_7_98","chapterId":"ch_work_han_thu_7","textTraditional":"乙巳，皇后陳氏廢。捕為巫蠱者，皆梟首。","sentenceOrder":98},
  {"id":"s_work_han_thu_7_99","chapterId":"ch_work_han_thu_7","textTraditional":"八月，螟。〔一〕","sentenceOrder":99},
  {"id":"s_work_han_thu_7_100","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「食苗心之蟲也，音莫經反。」","sentenceOrder":100},
  {"id":"s_work_han_thu_7_101","chapterId":"ch_work_han_thu_7","textTraditional":"徵吏民有明當時之務習先聖之術者，縣次續食，令與計偕。〔一〕","sentenceOrder":101},
  {"id":"s_work_han_thu_7_102","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「計者，上計簿使也，郡國每歲遣詣京師上之。偕者，俱也。令所徵之人與上計者俱來，而縣次給之食。後世訛誤，因承此語，遂總謂上計為計偕。闞駰不詳，妄為解說，云秦漢謂諸侯朝使曰計偕。偕，次也。晉代有計偕簿。又改偕為階，失之彌遠，致誤後學。」","sentenceOrder":102},
  {"id":"s_work_han_thu_7_103","chapterId":"ch_work_han_thu_7","textTraditional":"六年冬，初算商車。〔一〕","sentenceOrder":103},
  {"id":"s_work_han_thu_7_104","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　李奇曰：「始稅商賈車船，令出算。」","sentenceOrder":104},
  {"id":"s_work_han_thu_7_105","chapterId":"ch_work_han_thu_7","textTraditional":"春，穿漕渠通渭。〔一〕","sentenceOrder":105},
  {"id":"s_work_han_thu_7_106","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　如淳曰：「水轉運曰漕。」師古曰：「音才到反。」","sentenceOrder":106},
  {"id":"s_work_han_thu_7_107","chapterId":"ch_work_han_thu_7","textTraditional":"匈奴入上谷，殺略吏民。遣車騎將軍衛青出上谷，騎將軍公孫敖出代，輕車將軍公孫賀出雲中，驍騎將軍李廣出雁門。青至龍城〔一〕，獲首虜七百級。廣、敖失師而還。詔曰：「夷狄無義，所從來久。間者匈奴數寇邊境，故遣將撫師。古者治兵振旅，因遭虜之方入，將吏新會，上下未輯，〔二〕代郡將軍敖、雁門將軍廣所任不肖〔三〕，校尉又背義妄行，棄軍而北，少吏犯禁。〔四〕用兵之法：不勤不教，將率之過也；教令宣明，不能盡力，士卒之罪也。將軍已下廷尉，使理正之，〔五〕而又加法於士卒，二者並行，非仁聖之心。朕閔眾庶陷害，欲刷恥改行，〔六〕復奉正（議）〔義〕，厥路亡繇。〔七〕其赦雁門、代郡軍士不循法者。」〔八〕","sentenceOrder":107},
  {"id":"s_work_han_thu_7_108","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「匈奴單于祭天，大會諸國，名其處為龍城。」","sentenceOrder":108},
  {"id":"s_work_han_thu_7_109","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　晉灼曰：「入猶還也。不得已而用兵，言師不踰時也。入或作人，因其習俗土地之宜而教革之也。」師古曰：「晉說非也。詔言古者出則治兵，入則振旅，素練其眾，不虧戎律。今之出師，因遭寇虜方入為害，而將吏新會，上下未和，故校尉棄軍而奔北也。輯與集同。」","sentenceOrder":109},
  {"id":"s_work_han_thu_7_110","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　師古曰：「肖，似也。不肖者，言無所象類，謂不材之人也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_7_111","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　文穎曰：「少吏，小吏也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_7_112","chapterId":"ch_work_han_thu_7","textTraditional":"〔五〕　師古曰：「下謂以身付廷尉也。理，法也，言以法律處正其罪。下音胡嫁反。他皆類此。」","sentenceOrder":112},
  {"id":"s_work_han_thu_7_113","chapterId":"ch_work_han_thu_7","textTraditional":"〔六〕　師古曰：「刷，除也，音所劣反。」","sentenceOrder":113},
  {"id":"s_work_han_thu_7_114","chapterId":"ch_work_han_thu_7","textTraditional":"〔七〕　師古曰：「一陷重刑，無因復從正道也。繇讀與由同。」","sentenceOrder":114},
  {"id":"s_work_han_thu_7_115","chapterId":"ch_work_han_thu_7","textTraditional":"〔八〕　師古曰：「循，從也，由也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_7_116","chapterId":"ch_work_han_thu_7","textTraditional":"夏，大旱，蝗。","sentenceOrder":116},
  {"id":"s_work_han_thu_7_117","chapterId":"ch_work_han_thu_7","textTraditional":"六月，行幸雍。","sentenceOrder":117},
  {"id":"s_work_han_thu_7_118","chapterId":"ch_work_han_thu_7","textTraditional":"秋，匈奴盜邊。遣將軍韓安國屯漁陽。","sentenceOrder":118},
  {"id":"s_work_han_thu_7_119","chapterId":"ch_work_han_thu_7","textTraditional":"元朔元年〔一〕冬十一月，詔曰：「公卿大夫，所使總方略，壹統類，廣教化，美風俗也。夫本仁祖義，褒德祿賢，勸善刑暴，〔二〕五帝三王所繇昌也。〔三〕朕夙興夜寐，嘉與宇內之士臻於斯路。〔四〕故旅耆老，復孝敬，〔五〕選豪俊，講文學，〔六〕稽參政事，祈進民心，〔七〕深詔執事，興廉舉孝，庶幾成風，紹休聖緒〔八〕。夫十室之邑，必有忠信；三人並行，厥有我師。〔九〕今或至闔郡而不薦一人，〔一０〕是化不下究，而積行之君子雍於上聞也〔一一〕。二千石官長紀綱人倫，〔一二〕將何以佐朕燭幽隱，勸元元，〔一三〕厲蒸庶，〔一四〕崇鄉黨之訓哉？且進賢受上賞，蔽賢蒙顯戮，古之道也。其與中二千石、禮官、博士議不舉者罪。」有司奏議曰：「古者，諸侯貢士，壹適謂之好德，〔一五〕再適謂之賢賢，三適謂之有功，乃加九錫；〔一六〕不貢士，壹則黜爵，再則黜地，三而黜爵地畢矣。〔一七〕夫附下罔上者死，附上罔下者刑，與聞國政而無益於民者斥，〔一八〕在上位而不能進賢者退，此所以勸善黜惡也。今詔書昭先帝聖緒，令二千石舉孝廉，所以化元元，移風易俗也。不舉孝，不奉詔，當以不敬論。〔一九〕不察廉，不勝任也，當免。」〔二０〕奏可。","sentenceOrder":119},
  {"id":"s_work_han_thu_7_120","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「朔，蘇也。孟軻曰『后來其蘇』。蘇，息也，言萬民品物大繁息也。」師古曰：「朔猶始也，言更為初始也。蘇息之息，非息生義，應說失之。」","sentenceOrder":120},
  {"id":"s_work_han_thu_7_121","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「本仁祖義，謂以仁義為本始。」","sentenceOrder":121},
  {"id":"s_work_han_thu_7_122","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　師古曰：「五帝，伏羲、神農、黃帝、堯、舜也。三王，夏、殷、周也。繇讀與由同。」","sentenceOrder":122},
  {"id":"s_work_han_thu_7_123","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　師古曰：「天地四方為宇。臻，至也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_7_124","chapterId":"ch_work_han_thu_7","textTraditional":"〔五〕　師古曰：「旅耆老者，加惠於耆老之人，若賓旅也。復孝敬者，謂優復孝弟之人也。復音方目反。」","sentenceOrder":124},
  {"id":"s_work_han_thu_7_125","chapterId":"ch_work_han_thu_7","textTraditional":"〔六〕　師古曰：「講謂和習之。」","sentenceOrder":125},
  {"id":"s_work_han_thu_7_126","chapterId":"ch_work_han_thu_7","textTraditional":"〔七〕　師古曰：「祈，求也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_7_127","chapterId":"ch_work_han_thu_7","textTraditional":"〔八〕　師古曰：「休，美也。緒，業也。言紹先聖之休緒也。故下言昭先帝聖緒。」","sentenceOrder":127},
  {"id":"s_work_han_thu_7_128","chapterId":"ch_work_han_thu_7","textTraditional":"〔九〕　師古曰：「論語稱孔子云：『十室之邑，必有忠信如丘者焉。』又曰：『三人行，必有我師焉。擇其善者而從之，其不善者而改之。』故詔引焉。」","sentenceOrder":128},
  {"id":"s_work_han_thu_7_129","chapterId":"ch_work_han_thu_7","textTraditional":"〔一０〕師古曰：「闔，閉也。總〔一〕郡之中，故云闔郡。」","sentenceOrder":129},
  {"id":"s_work_han_thu_7_130","chapterId":"ch_work_han_thu_7","textTraditional":"〔一一〕師古曰：「究，竟也。言見壅遏，不得聞（雍）〔達〕於天子也。雍讀曰壅。」","sentenceOrder":130},
  {"id":"s_work_han_thu_7_131","chapterId":"ch_work_han_thu_7","textTraditional":"〔一二〕師古曰：「謂郡之守尉，縣之令長。」","sentenceOrder":131},
  {"id":"s_work_han_thu_7_132","chapterId":"ch_work_han_thu_7","textTraditional":"〔一三〕師古曰：「燭，照也。元元，善意。」","sentenceOrder":132},
  {"id":"s_work_han_thu_7_133","chapterId":"ch_work_han_thu_7","textTraditional":"〔一四〕師古曰：「蒸，眾也。」","sentenceOrder":133},
  {"id":"s_work_han_thu_7_134","chapterId":"ch_work_han_thu_7","textTraditional":"〔一五〕服虔曰：「適，得其人。」","sentenceOrder":134},
  {"id":"s_work_han_thu_7_135","chapterId":"ch_work_han_thu_7","textTraditional":"〔一六〕應劭曰：「一曰車馬，二曰衣服，三曰樂器，四曰朱戶，五曰納陛，六曰虎賁百人，七曰鈇鉞，八曰弓矢，九曰秬鬯。此皆天子制度，尊之，故事事錫與，但數少耳。」張晏曰：「九錫，經本無文，周禮以為九命，春秋說有之。」臣瓚曰：「九錫備物，伯者之盛禮，齊桓、晉文猶不能備，今三進賢便受之，似不然也。當受進賢之一錫。尚書大傳云『三適謂之有功，賜以車服弓矢』是也。」師古曰：「總列九錫，應說是也。進賢一錫，瓚說是也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_7_136","chapterId":"ch_work_han_thu_7","textTraditional":"〔一七〕李奇曰：「爵地俱削盡。」","sentenceOrder":136},
  {"id":"s_work_han_thu_7_137","chapterId":"ch_work_han_thu_7","textTraditional":"〔一八〕師古曰：「與讀曰豫。斥謂棄逐之。」","sentenceOrder":137},
  {"id":"s_work_han_thu_7_138","chapterId":"ch_work_han_thu_7","textTraditional":"〔一九〕張晏曰：「謂其不勤求士報國。」","sentenceOrder":138},
  {"id":"s_work_han_thu_7_139","chapterId":"ch_work_han_thu_7","textTraditional":"〔二０〕張晏曰：「當率身化下，今親宰牧而無賢人，為不勝任也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_7_140","chapterId":"ch_work_han_thu_7","textTraditional":"十二月，江都王非薨。","sentenceOrder":140},
  {"id":"s_work_han_thu_7_141","chapterId":"ch_work_han_thu_7","textTraditional":"春三月甲子，立皇后衛氏。詔曰：「朕聞天地不變，不成施化；陰陽不變，物不暢茂。〔一〕易曰『通其變，使民不倦』。〔二〕詩云『九變復貫，知言之選』。〔三〕朕嘉唐虞而樂殷周，據舊以鑒新。〔四〕其赦天下，與民更始。諸逋貸及辭訟在孝景後三年以前，皆勿聽治。」〔五〕","sentenceOrder":141},
  {"id":"s_work_han_thu_7_142","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「暢，通也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_7_143","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　應劭曰：「黃帝、堯、舜祖述伏羲、神農，結網耒耜，以日中為市。交易之業，因其所利，變而通之，使民知之，不苦倦也。」師古曰：「此易下繫之辭也。言通物之變，故能樂其器用，不解倦也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_7_144","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　應劭曰：「逸詩也。陽數九，人君當陽，言變政復禮，合於先王舊貫。知言之選，選，善也。」孟康曰：「貫，道也。選，數也。極天之變而不失道者，知言之數也。」臣瓚曰：「先王創制易教，以救流弊也，是以三王之教有文有質。九，數之多也。」師古曰：「貫，事也。選，擇也。論語曰『仍舊貫』，此言文質不同，寬猛殊用，循環復舊，擇善而從之。瓚說近之也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_7_145","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　師古曰：「追觀舊跡，以知新政，而為鑒戒。」","sentenceOrder":145},
  {"id":"s_work_han_thu_7_146","chapterId":"ch_work_han_thu_7","textTraditional":"〔五〕　師古曰：「逋，亡也。久負官物亡匿不還者，皆謂之逋。逋音布胡反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_7_147","chapterId":"ch_work_han_thu_7","textTraditional":"秋，匈奴入遼西，殺太守；入漁陽、雁門，敗都尉，殺略三千餘人。遣將軍衛青出雁門，將軍李息出代，獲首虜數千級。","sentenceOrder":147},
  {"id":"s_work_han_thu_7_148","chapterId":"ch_work_han_thu_7","textTraditional":"東夷薉君南閭等〔一〕口二十八萬人降，為蒼海郡。","sentenceOrder":148},
  {"id":"s_work_han_thu_7_149","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　服虔曰：「穢貊在辰韓之北，高句麗沃沮之南，東窮于大海。」晉灼曰：「薉，古穢字。」師古曰：「南閭者，薉君之名。」","sentenceOrder":149},
  {"id":"s_work_han_thu_7_150","chapterId":"ch_work_han_thu_7","textTraditional":"魯王餘、長沙王發皆薨。","sentenceOrder":150},
  {"id":"s_work_han_thu_7_151","chapterId":"ch_work_han_thu_7","textTraditional":"二年冬，賜淮南王、菑川王几杖，毋朝。〔一〕","sentenceOrder":151},
  {"id":"s_work_han_thu_7_152","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「淮南王安、菑川王志皆武帝諸父列也，故賜几杖焉。」","sentenceOrder":152},
  {"id":"s_work_han_thu_7_153","chapterId":"ch_work_han_thu_7","textTraditional":"春正月，詔曰：「梁王、城陽王親慈同生，〔一〕願以邑分弟，其許之。諸侯王請與子弟邑者，朕將親覽，使有列位焉。」於是藩國始分，而子弟畢侯矣。","sentenceOrder":153},
  {"id":"s_work_han_thu_7_154","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　文穎曰：「慈，愛也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_7_155","chapterId":"ch_work_han_thu_7","textTraditional":"匈奴入上谷、漁陽，殺略吏民千餘人。遣將軍衛青、李息出雲中，至高闕，〔一〕遂西至符離，〔二〕獲首虜數千級。數河南地，置朔方、五原郡。","sentenceOrder":155},
  {"id":"s_work_han_thu_7_156","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「山名也，一曰塞名也，在朔方之北。」","sentenceOrder":156},
  {"id":"s_work_han_thu_7_157","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「幕北塞名也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_7_158","chapterId":"ch_work_han_thu_7","textTraditional":"三月乙亥晦，日有蝕之。","sentenceOrder":158},
  {"id":"s_work_han_thu_7_159","chapterId":"ch_work_han_thu_7","textTraditional":"夏，募民徙朔方十萬口。又徙郡國豪傑及訾三百萬以上于茂陵。","sentenceOrder":159},
  {"id":"s_work_han_thu_7_160","chapterId":"ch_work_han_thu_7","textTraditional":"秋，燕王定國有罪，自殺。","sentenceOrder":160},
  {"id":"s_work_han_thu_7_161","chapterId":"ch_work_han_thu_7","textTraditional":"三年春，罷蒼海郡。三月，詔曰：「夫刑罰所以防姦也，內長文所以見愛也；〔一〕以百姓之未洽于教化，朕嘉與士大夫日新厥業，祗而不解。〔二〕其赦天下。」","sentenceOrder":161},
  {"id":"s_work_han_thu_7_162","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　晉灼曰：「長音長吏之長。」張晏曰：「長文，長文德也。」師古曰：「詔言有文德者，即親內而崇長之，所以見仁愛之道。見謂顯示也，音胡電反。」","sentenceOrder":162},
  {"id":"s_work_han_thu_7_163","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「解讀曰懈。」","sentenceOrder":163},
  {"id":"s_work_han_thu_7_164","chapterId":"ch_work_han_thu_7","textTraditional":"夏，匈奴入代，殺太守；入雁門，殺略千餘人。","sentenceOrder":164},
  {"id":"s_work_han_thu_7_165","chapterId":"ch_work_han_thu_7","textTraditional":"六月庚午，皇太后崩。","sentenceOrder":165},
  {"id":"s_work_han_thu_7_166","chapterId":"ch_work_han_thu_7","textTraditional":"秋，罷西南夷，城朔方城。令民大酺五日。","sentenceOrder":166},
  {"id":"s_work_han_thu_7_167","chapterId":"ch_work_han_thu_7","textTraditional":"四年冬，行幸甘泉。","sentenceOrder":167},
  {"id":"s_work_han_thu_7_168","chapterId":"ch_work_han_thu_7","textTraditional":"夏，匈奴入代、定襄、上郡，殺略數千人。","sentenceOrder":168},
  {"id":"s_work_han_thu_7_169","chapterId":"ch_work_han_thu_7","textTraditional":"五年春，大旱。大將軍衛青將六將軍兵十餘萬人出朔方、高闕，獲首虜萬五千級。","sentenceOrder":169},
  {"id":"s_work_han_thu_7_170","chapterId":"ch_work_han_thu_7","textTraditional":"夏六月，詔曰：「蓋聞導民以禮，風之以樂，〔一〕今禮壞樂崩，朕甚閔焉。故詳延天下方聞之士，咸薦諸朝。〔二〕其令禮官勸學，講議洽聞，舉遺興禮，以為天下先。〔三〕太常其議予博士弟子，崇鄉黨之化，以厲賢材焉。」〔四〕丞相弘請為博士置弟子員，〔五〕學者益廣。","sentenceOrder":170},
  {"id":"s_work_han_thu_7_171","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「風，教也。詩序曰『上以風化下』。」","sentenceOrder":171},
  {"id":"s_work_han_thu_7_172","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「詳，悉也。延，引也。方，道也。聞，博聞也。言悉引有道博聞之士而進於朝也。禮記曰『隆禮由禮，謂之有方之士』。又曰『博聞強識而讓，謂之君子』。一曰方謂方正也。」","sentenceOrder":172},
  {"id":"s_work_han_thu_7_173","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　師古曰：「舉遺逸之文而興禮學。」","sentenceOrder":173},
  {"id":"s_work_han_thu_7_174","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　師古曰：「為博士置弟子，既得崇化於鄉黨，又以獎厲賢材之人。」","sentenceOrder":174},
  {"id":"s_work_han_thu_7_175","chapterId":"ch_work_han_thu_7","textTraditional":"〔五〕　師古曰：「公孫弘。」","sentenceOrder":175},
  {"id":"s_work_han_thu_7_176","chapterId":"ch_work_han_thu_7","textTraditional":"秋，匈奴入代，殺都尉。","sentenceOrder":176},
  {"id":"s_work_han_thu_7_177","chapterId":"ch_work_han_thu_7","textTraditional":"六年春二月，大將軍衛青將六將軍兵十餘萬騎出定襄，斬首三千餘級。還，休士馬于定襄、雲中、鴈門。赦天下。","sentenceOrder":177},
  {"id":"s_work_han_thu_7_178","chapterId":"ch_work_han_thu_7","textTraditional":"夏四月，衛青復將六將軍絕幕，〔一〕大克獲。前將軍趙信軍敗，降匈奴。右將軍蘇建亡軍，獨身脫還，贖為庶人。","sentenceOrder":178},
  {"id":"s_work_han_thu_7_179","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「幕，沙幕，匈奴之南界也。」臣瓚曰：「沙土曰幕。直度曰絕。」師古曰：「應、瓚二說皆是也，而說者或云是塞外地名，非矣。幕者，即今之突厥中磧耳。李陵歌曰『徑萬里兮渡沙幕』。」","sentenceOrder":179},
  {"id":"s_work_han_thu_7_180","chapterId":"ch_work_han_thu_7","textTraditional":"六月，詔曰：「朕聞五帝不相復禮，三代不同法，所繇殊路而建德一也。〔一〕蓋孔子對定公以徠遠，〔二〕哀公以論臣，〔三〕景公以節用，〔四〕非期不同，所急異務也。〔五〕今中國一統而北邊未安，朕甚悼之。日者大將軍巡朔方，征匈奴，斬首虜萬八千級，諸禁錮及有過者，咸蒙厚賞，得免減罪。〔六〕今大將軍仍復克獲〔七〕，斬首虜萬九千級，受爵賞而欲移賣者，無所流貤。〔八〕其議為令。」有司奏請置武功賞官，以寵戰士。","sentenceOrder":180},
  {"id":"s_work_han_thu_7_181","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「復，因也，音扶目反。繇讀與由同。」","sentenceOrder":181},
  {"id":"s_work_han_thu_7_182","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　臣瓚曰：「論語及韓子皆言葉公問政於孔子，孔子答以悅近徠遠。今云定公，與二書異。」","sentenceOrder":182},
  {"id":"s_work_han_thu_7_183","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　如淳曰：「韓非云哀公問政，仲尼曰政在選賢。」","sentenceOrder":183},
  {"id":"s_work_han_thu_7_184","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　如淳曰：「韓非云齊景公問政，仲尼曰政在節財。」","sentenceOrder":184},
  {"id":"s_work_han_thu_7_185","chapterId":"ch_work_han_thu_7","textTraditional":"〔五〕　李奇曰：「期，要也。非要當必不同，所急異務，不得不然。」","sentenceOrder":185},
  {"id":"s_work_han_thu_7_186","chapterId":"ch_work_han_thu_7","textTraditional":"〔六〕　師古曰：「有罪者，或被釋免，或得減輕。」","sentenceOrder":186},
  {"id":"s_work_han_thu_7_187","chapterId":"ch_work_han_thu_7","textTraditional":"〔七〕　師古曰：「仍，頻也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_7_188","chapterId":"ch_work_han_thu_7","textTraditional":"〔八〕　應劭曰：「貤音移。言軍吏士斬首虜，爵級多無所移與，今為置武功賞官，爵多者分與父兄子弟及賣與他人也。」師古曰：「此說非也。許慎說文解字云『貤，物之重次第也』。此詔言欲移賣爵者，無有差次，不得流行，故為置官級也。貤音弋賜反。今俗猶謂凡物一重為一貤也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_7_189","chapterId":"ch_work_han_thu_7","textTraditional":"元狩元年〔一〕冬十月，行幸雍，祠五畤。獲白麟，〔二〕作白麟之歌。","sentenceOrder":189},
  {"id":"s_work_han_thu_7_190","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「獲白麟，因改元曰元狩也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_7_191","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「麟，麋身，牛尾，馬足，黃色，圜蹄，一角，角端有肉。」","sentenceOrder":191},
  {"id":"s_work_han_thu_7_192","chapterId":"ch_work_han_thu_7","textTraditional":"十一月，淮南王安、衡山王賜謀反，誅。黨與死者數萬人。","sentenceOrder":192},
  {"id":"s_work_han_thu_7_193","chapterId":"ch_work_han_thu_7","textTraditional":"十二月，大雨雪，民凍死。〔一〕","sentenceOrder":193},
  {"id":"s_work_han_thu_7_194","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「雨音于具反。」","sentenceOrder":194},
  {"id":"s_work_han_thu_7_195","chapterId":"ch_work_han_thu_7","textTraditional":"夏四月，赦天下。","sentenceOrder":195},
  {"id":"s_work_han_thu_7_196","chapterId":"ch_work_han_thu_7","textTraditional":"丁卯，立皇太子。賜中二千石爵右庶長，〔一〕民為父後者一級。詔曰：「朕聞咎繇對禹，曰在知人，知人則哲，惟帝難之。〔二〕蓋君者心也，民猶支體，支體傷則心憯怛。〔三〕日者淮南、衡山修文學，流貨賂，兩國接壤，怵於邪說，〔四〕而造篡弒，此朕之不德。詩云：『憂心慘慘，念國之為虐。』〔五〕已赦天下，滌除與之更始。朕嘉孝弟力田，哀夫老眊孤寡鰥獨〔六〕或匱於衣食，甚憐愍焉。其遣謁者巡行天下，存問致賜。〔七〕曰『皇帝使謁者〔八〕賜縣三老、孝者帛，人五匹；鄉三老、弟者、力田帛，人三匹；年九十以上及鰥寡孤獨帛，人二匹，絮三斤；八十以上米，人三石。有冤失職，使者以聞。〔九〕縣鄉即賜，毋贅聚』。」〔一０〕","sentenceOrder":196},
  {"id":"s_work_han_thu_7_197","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「第十一等爵。」","sentenceOrder":197},
  {"id":"s_work_han_thu_7_198","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「尚書咎繇謨載咎繇之辭也。帝謂堯也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_7_199","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　師古曰：「憯，痛也。怛，悼也。憯音千感反。怛音丁曷反。」","sentenceOrder":199},
  {"id":"s_work_han_thu_7_200","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　服虔曰：「怵音裔。」應劭曰：「狃〈忄犬〉也。」如淳曰：「怵音怵惕，見誘怵於邪說也。」師古曰：「作〈忄犬〉者非。如說云見誘怵，其義是也，而音怵惕，又非也。怵或體訹字耳。訹者，誘也，音如戌亥之戌。南越傳曰『不可怵好語入朝』。諸如此例，音義同耳。今俗猶云相謏訹，而說者或改為鉥導之鉥，蓋穿鑿也。謏音先誘反。鉥音述。」","sentenceOrder":200},
  {"id":"s_work_han_thu_7_201","chapterId":"ch_work_han_thu_7","textTraditional":"〔五〕　師古曰：「小雅正月之詩也。慘慘，憂戚之貌。」","sentenceOrder":201},
  {"id":"s_work_han_thu_7_202","chapterId":"ch_work_han_thu_7","textTraditional":"〔六〕　師古曰：「眊，古耄字。八十曰耄。耄，老稱也。一曰眊，不明之貌。」","sentenceOrder":202},
  {"id":"s_work_han_thu_7_203","chapterId":"ch_work_han_thu_7","textTraditional":"〔七〕　師古曰：「致，送至也。行音下更反。」","sentenceOrder":203},
  {"id":"s_work_han_thu_7_204","chapterId":"ch_work_han_thu_7","textTraditional":"〔八〕　師古曰：「謁者令使者宣詔書之文。」","sentenceOrder":204},
  {"id":"s_work_han_thu_7_205","chapterId":"ch_work_han_thu_7","textTraditional":"〔九〕　師古曰：「職，常也。失職者，失其常業及常理也。」","sentenceOrder":205},
  {"id":"s_work_han_thu_7_206","chapterId":"ch_work_han_thu_7","textTraditional":"〔一０〕如淳曰：「贅，會也。令勿擅徵召贅聚三老孝弟力田也。」師古曰：「即，就也。各遣就其所居而賜之，勿會聚也。贅音之銳反。」","sentenceOrder":206},
  {"id":"s_work_han_thu_7_207","chapterId":"ch_work_han_thu_7","textTraditional":"五月乙巳晦，日有蝕之。","sentenceOrder":207},
  {"id":"s_work_han_thu_7_208","chapterId":"ch_work_han_thu_7","textTraditional":"匈奴入上谷，殺數百人。","sentenceOrder":208},
  {"id":"s_work_han_thu_7_209","chapterId":"ch_work_han_thu_7","textTraditional":"二年冬十月，行幸雍，祠五畤。","sentenceOrder":209},
  {"id":"s_work_han_thu_7_210","chapterId":"ch_work_han_thu_7","textTraditional":"春三月戊寅，丞相弘薨。","sentenceOrder":210},
  {"id":"s_work_han_thu_7_211","chapterId":"ch_work_han_thu_7","textTraditional":"遣驃騎將軍霍去病出隴西，至皋蘭，〔一〕斬首八千餘級。","sentenceOrder":211},
  {"id":"s_work_han_thu_7_212","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「在隴西白石縣，塞外河名也。」孟康曰：「山關名也。」師古曰：「皋蘭，山名也。霍去病傳云『過焉支山千有餘里，合短兵鏖皋蘭下』，則此山也，非河名也。白石縣在金城，又不屬隴西。應說並失之。鏖音烏曹反。」","sentenceOrder":212},
  {"id":"s_work_han_thu_7_213","chapterId":"ch_work_han_thu_7","textTraditional":"夏，馬生余吾水中。〔一〕南越獻馴象、〔二〕能言鳥。〔三〕","sentenceOrder":213},
  {"id":"s_work_han_thu_7_214","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「在朔方北也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_7_215","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　應劭曰：「馴者，教能拜起周章，從人意也。」師古曰：「馴音巡，謂擾也。應說是也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_7_216","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　師古曰：「即鸚鵡也，今隴西及南海並有之。萬震南州異物志云有三種，一種白，一種青，一種五色。交州以南諸國盡有之。白及五色者，其性尤慧解，蓋謂此也。隋開皇十八年，林邑國獻白鸚鵡，時以為異。是歲貢士咸試賦之。聖皇馭歷，屢有茲獻。上以幽遐勞費，撫慰弗受。」","sentenceOrder":216},
  {"id":"s_work_han_thu_7_217","chapterId":"ch_work_han_thu_7","textTraditional":"將軍去病、公孫敖出北地二千餘里，過居延，〔一〕斬首虜三萬餘級。","sentenceOrder":217},
  {"id":"s_work_han_thu_7_218","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「居延，匈奴中地名也，韋昭以為張掖縣，失之。張掖所置居延縣者，以安處所獲居延人而置此縣。」","sentenceOrder":218},
  {"id":"s_work_han_thu_7_219","chapterId":"ch_work_han_thu_7","textTraditional":"匈奴入鴈門，殺略數百人。遣衛尉張騫、郎中令李廣皆出右北平。廣殺匈奴三千餘人，盡亡其軍四千人，獨身脫還，及公孫敖、張騫皆後期，當斬，贖為庶人。","sentenceOrder":219},
  {"id":"s_work_han_thu_7_220","chapterId":"ch_work_han_thu_7","textTraditional":"江都王建有罪，自殺。膠東王寄薨。","sentenceOrder":220},
  {"id":"s_work_han_thu_7_221","chapterId":"ch_work_han_thu_7","textTraditional":"秋，匈奴昆邪王殺休屠王，〔一〕并將其眾合四萬餘人來降，置五屬國以處之。〔二〕以其地為武威、酒泉郡。〔三〕","sentenceOrder":221},
  {"id":"s_work_han_thu_7_222","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「昆音下門反。屠音儲。」","sentenceOrder":222},
  {"id":"s_work_han_thu_7_223","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「凡言屬國者，存其國號而屬漢朝，故曰屬國。」","sentenceOrder":223},
  {"id":"s_work_han_thu_7_224","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　師古曰：「武威，今涼州也。酒泉，今肅州。」","sentenceOrder":224},
  {"id":"s_work_han_thu_7_225","chapterId":"ch_work_han_thu_7","textTraditional":"三年春，有星孛于東方。夏五月，赦天下。立膠東康王少子慶為六安王。封故相國蕭何曾孫慶為列侯。","sentenceOrder":225},
  {"id":"s_work_han_thu_7_226","chapterId":"ch_work_han_thu_7","textTraditional":"秋，匈奴入右北平、定襄，殺略千餘人。","sentenceOrder":226},
  {"id":"s_work_han_thu_7_227","chapterId":"ch_work_han_thu_7","textTraditional":"遣謁者勸有水災郡種宿麥。〔一〕舉吏民能假貸貧民者以名聞。〔二〕","sentenceOrder":227},
  {"id":"s_work_han_thu_7_228","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「秋冬種之，經歲乃熟，故云宿麥。」","sentenceOrder":228},
  {"id":"s_work_han_thu_7_229","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「貸音吐戴反。」","sentenceOrder":229},
  {"id":"s_work_han_thu_7_230","chapterId":"ch_work_han_thu_7","textTraditional":"減隴西、北地、上郡戍卒半。","sentenceOrder":230},
  {"id":"s_work_han_thu_7_231","chapterId":"ch_work_han_thu_7","textTraditional":"發謫吏穿昆明池。〔一〕","sentenceOrder":231},
  {"id":"s_work_han_thu_7_232","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　如淳曰：「食貨志以舊吏弄法，故謫使穿池，更發有貲者為吏也。」臣瓚曰：「西南夷傳有越嶲、昆明國，有滇池，方三百里。漢使求身毒國，而為昆明所閉。今欲伐之，故作昆明池象之，以習水戰，在長安西南，周回四十里。食貨志又曰時越欲與漢用船戰，遂乃大修昆明池也。」師古曰：「謫吏，吏有罪者，罰而役之。滇音顛。」","sentenceOrder":232},
  {"id":"s_work_han_thu_7_233","chapterId":"ch_work_han_thu_7","textTraditional":"四年冬，有司言關東貧民徙隴西、北地、西河、上郡、會稽凡七十二萬五千口，縣官衣食振業，用度不足，請收銀錫造白金及皮幣以足用。〔一〕初算緡錢。〔二〕","sentenceOrder":233},
  {"id":"s_work_han_thu_7_234","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「時國用不足，以白鹿皮為幣，朝覲以薦璧。又造銀錫為白金。見食貨志。」","sentenceOrder":234},
  {"id":"s_work_han_thu_7_235","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　李斐曰：「緡，絲也，以貫錢也。一貫千錢，出算二十也。」臣瓚曰：「茂陵書諸賈人末作貰貸，置居邑儲積諸物，及商以取利者，雖無市籍，各以其物自占，率緡錢二千而一算。此緡錢是儲錢也。故隨其用所施，施於（吏）〔利〕重者，其算亦多也。」師古曰：「謂有儲積錢者，計其緡貫而稅之。李說為是。緡音武巾反。」","sentenceOrder":235},
  {"id":"s_work_han_thu_7_236","chapterId":"ch_work_han_thu_7","textTraditional":"春，有星孛于東北。","sentenceOrder":236},
  {"id":"s_work_han_thu_7_237","chapterId":"ch_work_han_thu_7","textTraditional":"夏，有長星出于西北。","sentenceOrder":237},
  {"id":"s_work_han_thu_7_238","chapterId":"ch_work_han_thu_7","textTraditional":"大將軍衛青將四將軍出定襄，將軍去病出代，各將五萬騎。步兵踵軍後數十萬人。〔一〕青至幕北圍單于，斬首萬九千級，至闐顏山乃還。〔二〕去病與左賢王戰，斬獲首虜七萬餘級，封狼居胥山乃還。〔三〕兩軍士（戰）死者數萬人。前將軍廣、後將軍食其皆後期。廣自殺，食其贖死。〔四〕","sentenceOrder":238},
  {"id":"s_work_han_thu_7_239","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「踵，接也，猶言躡其踵。」","sentenceOrder":239},
  {"id":"s_work_han_thu_7_240","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　鄧展曰：「音填塞之填。」","sentenceOrder":240},
  {"id":"s_work_han_thu_7_241","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　師古曰：「登山祭天，築土為封，刻石紀事，以彰漢功。」","sentenceOrder":241},
  {"id":"s_work_han_thu_7_242","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　如淳曰：「李廣傳『引兵與右將軍食其合軍，出東道』。又曰『廣自剄，右將軍下吏當死，贖為庶人』。霍去病傳亦云趙食其為右將軍，平陽侯襄為後將軍。此紀為誤也。」師古曰：「傳寫者誤以右為後。食其，音異基。」","sentenceOrder":242},
  {"id":"s_work_han_thu_7_243","chapterId":"ch_work_han_thu_7","textTraditional":"五年春三月甲午，丞相李蔡有罪，自殺。〔一〕","sentenceOrder":243},
  {"id":"s_work_han_thu_7_244","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　文穎曰：「李廣從弟，坐侵陵壖地。」","sentenceOrder":244},
  {"id":"s_work_han_thu_7_245","chapterId":"ch_work_han_thu_7","textTraditional":"天下馬少，平牡馬匹二十萬。〔一〕","sentenceOrder":245},
  {"id":"s_work_han_thu_7_246","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　如淳曰：「貴平牡馬賈，欲使人競畜馬。」","sentenceOrder":246},
  {"id":"s_work_han_thu_7_247","chapterId":"ch_work_han_thu_7","textTraditional":"罷半兩錢，行五銖錢。","sentenceOrder":247},
  {"id":"s_work_han_thu_7_248","chapterId":"ch_work_han_thu_7","textTraditional":"徙天下姦猾吏民於邊。〔一〕","sentenceOrder":248},
  {"id":"s_work_han_thu_7_249","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「猾，狡也，音乎八反。」","sentenceOrder":249},
  {"id":"s_work_han_thu_7_250","chapterId":"ch_work_han_thu_7","textTraditional":"六年冬十月，賜丞相以下至吏二千石金，千石以下至乘從者帛，〔一〕蠻夷錦各有差。","sentenceOrder":250},
  {"id":"s_work_han_thu_7_251","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　晉灼曰：「乘騎諸從者也。」師古曰：「流俗書本乘上或有公字，非也，後人妄加之。」","sentenceOrder":251},
  {"id":"s_work_han_thu_7_252","chapterId":"ch_work_han_thu_7","textTraditional":"雨水亡冰。〔一〕","sentenceOrder":252},
  {"id":"s_work_han_thu_7_253","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「雨音于具反。」","sentenceOrder":253},
  {"id":"s_work_han_thu_7_254","chapterId":"ch_work_han_thu_7","textTraditional":"夏四月乙巳，廟立皇子閎為齊王，旦為燕王，胥為廣陵王。〔一〕初作誥。〔二〕","sentenceOrder":254},
  {"id":"s_work_han_thu_7_255","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「於廟中策命之。」","sentenceOrder":255},
  {"id":"s_work_han_thu_7_256","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　服虔曰：「誥敕王，如尚書諸誥也。」李斐曰：「今敕封拜諸侯王策文亦是也。見武五子傳。」","sentenceOrder":256},
  {"id":"s_work_han_thu_7_257","chapterId":"ch_work_han_thu_7","textTraditional":"六月，詔曰：「日者有司以幣輕多姦，〔一〕農傷而末眾，〔二〕又禁（以）〔兼〕并之塗，〔三〕故改幣以約之。〔四〕稽諸往古，制宜於今。〔五〕廢期有月，〔六〕而山澤之民未諭。〔七〕夫仁行而從善，義立則俗易，意奉憲者所以導之未明與？〔八〕將百姓所安殊路，而撟虔吏因乘勢以侵蒸庶邪？〔九〕何紛然其擾也！〔一０〕今遣博士大等六人分循行天下，〔一一〕存問鰥寡廢疾，無以自振業者貸與之。〔一二〕諭三老孝弟以為民師，舉獨行之君子，徵詣行在所。〔一三〕朕嘉賢者，樂知其人。廣宣厥道，士有特招，使者之任也。〔一四〕詳問隱處亡位，及冤失職，〔一五〕姦猾為害，野荒治苛者，舉奏。〔一六〕郡國有所以為便者，上丞相、御史以聞。」","sentenceOrder":257},
  {"id":"s_work_han_thu_7_258","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　李奇曰：「幣，錢也。輕者，若一馬直二十萬，是為幣輕而物重也。重難得，則用不足而姦生。」","sentenceOrder":258},
  {"id":"s_work_han_thu_7_259","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「末謂工商也。」","sentenceOrder":259},
  {"id":"s_work_han_thu_7_260","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　李奇曰：「謂大家兼役小民，富者兼役貧民，欲平之也。」文穎曰：「兼并者，食祿之家不得治產，兼取小民之利；商人雖富，不得復兼畜田宅，作客耕農也。」師古曰：「李說是。」","sentenceOrder":260},
  {"id":"s_work_han_thu_7_261","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　李奇曰：「更去半兩錢，行五銖錢、皮幣，以檢約姦邪。」","sentenceOrder":261},
  {"id":"s_work_han_thu_7_262","chapterId":"ch_work_han_thu_7","textTraditional":"〔五〕　師古曰：「稽，考也，音工奚反。」","sentenceOrder":262},
  {"id":"s_work_han_thu_7_263","chapterId":"ch_work_han_thu_7","textTraditional":"〔六〕　應劭曰：「禁半兩錢及餘幣物，禁之有期月而民未悉從也。」如淳曰：「期音期。自往年三月至今年四月，期有餘月矣。」師古曰：「如說是。」","sentenceOrder":263},
  {"id":"s_work_han_thu_7_264","chapterId":"ch_work_han_thu_7","textTraditional":"〔七〕　師古曰：「未諭者，未曉告示之意。」","sentenceOrder":264},
  {"id":"s_work_han_thu_7_265","chapterId":"ch_work_han_thu_7","textTraditional":"〔八〕　師古曰：「與讀曰歟。」","sentenceOrder":265},
  {"id":"s_work_han_thu_7_266","chapterId":"ch_work_han_thu_7","textTraditional":"〔九〕　孟康曰：「虔，固也。矯稱上命以貨賄用為固。尚書曰『敓攘矯虔』。」韋昭曰：「凡稱詐為矯，強取為虔。左傳曰『虔劉我邊垂』。」師古曰：「撟與矯同，其字從手。矯，託也。虔，固也。妄託上命而堅固為邪惡者也。蒸，眾也。」","sentenceOrder":266},
  {"id":"s_work_han_thu_7_267","chapterId":"ch_work_han_thu_7","textTraditional":"〔一０〕師古曰：「擾，煩也。」","sentenceOrder":267},
  {"id":"s_work_han_thu_7_268","chapterId":"ch_work_han_thu_7","textTraditional":"〔一一〕師古曰：「褚大也。行音下更反。」","sentenceOrder":268},
  {"id":"s_work_han_thu_7_269","chapterId":"ch_work_han_thu_7","textTraditional":"〔一二〕師古曰：「貸音土戴反。」","sentenceOrder":269},
  {"id":"s_work_han_thu_7_270","chapterId":"ch_work_han_thu_7","textTraditional":"〔一三〕如淳曰：「蔡雍云天子以天下為家，自謂所居為行在所，言今雖在京師，行所在至耳。」師古曰：「此說非也。天子或在京師，或出巡狩，不可豫定，故言行在所耳。不得亦謂京師為行在也。」","sentenceOrder":270},
  {"id":"s_work_han_thu_7_271","chapterId":"ch_work_han_thu_7","textTraditional":"〔一四〕李奇曰：「設士有殊才異行，當特招者，任在使者分別之。」","sentenceOrder":271},
  {"id":"s_work_han_thu_7_272","chapterId":"ch_work_han_thu_7","textTraditional":"〔一五〕師古曰：「無位，不被任用也。冤，屈也。失職，失其常業也。」","sentenceOrder":272},
  {"id":"s_work_han_thu_7_273","chapterId":"ch_work_han_thu_7","textTraditional":"〔一六〕師古曰：「野荒，言田畝不闢也。治苛，為政尚細刻。」","sentenceOrder":273},
  {"id":"s_work_han_thu_7_274","chapterId":"ch_work_han_thu_7","textTraditional":"秋九月，大司馬驃騎將軍去病薨。","sentenceOrder":274},
  {"id":"s_work_han_thu_7_275","chapterId":"ch_work_han_thu_7","textTraditional":"元鼎元年〔一〕夏五月，赦天下，大酺五日。","sentenceOrder":275},
  {"id":"s_work_han_thu_7_276","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「得寶鼎故，因是改元。」","sentenceOrder":276},
  {"id":"s_work_han_thu_7_277","chapterId":"ch_work_han_thu_7","textTraditional":"得鼎汾水上。","sentenceOrder":277},
  {"id":"s_work_han_thu_7_278","chapterId":"ch_work_han_thu_7","textTraditional":"濟東王彭離有罪，廢徙上庸。〔一〕","sentenceOrder":278},
  {"id":"s_work_han_thu_7_279","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「春秋時庸國。」","sentenceOrder":279},
  {"id":"s_work_han_thu_7_280","chapterId":"ch_work_han_thu_7","textTraditional":"二年冬十一月，御史大夫張湯有罪，自殺。十二月，丞相青翟下獄死。〔一〕","sentenceOrder":280},
  {"id":"s_work_han_thu_7_281","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「莊青翟。」","sentenceOrder":281},
  {"id":"s_work_han_thu_7_282","chapterId":"ch_work_han_thu_7","textTraditional":"春，起柏梁臺。〔一〕","sentenceOrder":282},
  {"id":"s_work_han_thu_7_283","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　服虔曰：「用百頭梁作臺，因名焉。」師古曰：「三輔舊事云以香柏為之。今書字皆作柏。服說非。」","sentenceOrder":283},
  {"id":"s_work_han_thu_7_284","chapterId":"ch_work_han_thu_7","textTraditional":"三月，大雨雪。〔一〕夏，大水，關東餓死者以千數。","sentenceOrder":284},
  {"id":"s_work_han_thu_7_285","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「雨音于具反。」","sentenceOrder":285},
  {"id":"s_work_han_thu_7_286","chapterId":"ch_work_han_thu_7","textTraditional":"秋九月，詔曰：「仁不異遠，義不辭難。〔一〕今京師雖未為豐年，山林池澤之饒與民共之。今水潦移於江南，迫隆冬至，朕懼其飢寒不活。江南之地，火耕水耨，〔二〕方下巴蜀之粟致之江陵，遣博士中等分循行，〔三〕諭告所抵，無令重困。〔四〕吏民有振救飢民免其厄者，具舉以聞。」","sentenceOrder":286},
  {"id":"s_work_han_thu_7_287","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「遠近如一，是為仁也。不憚艱難，是為義也。」","sentenceOrder":287},
  {"id":"s_work_han_thu_7_288","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　應劭曰：「燒草下水種稻。草與稻並生，高七八寸，因悉芟去，復下水灌之，草死，獨稻長，所謂火耕水耨。」","sentenceOrder":288},
  {"id":"s_work_han_thu_7_289","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　師古曰：「行音下更反。」","sentenceOrder":289},
  {"id":"s_work_han_thu_7_290","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　師古曰：「抵，至也。重音直用反。」","sentenceOrder":290},
  {"id":"s_work_han_thu_7_291","chapterId":"ch_work_han_thu_7","textTraditional":"三年冬，徙函谷關於新安。〔一〕以故關為弘農縣。","sentenceOrder":291},
  {"id":"s_work_han_thu_7_292","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「時樓船將軍楊僕數有大功，恥為關外民，上書乞徙東關，以家財給其用度。武帝意亦好廣闊，於是徙關於新安，去弘農三百里。」","sentenceOrder":292},
  {"id":"s_work_han_thu_7_293","chapterId":"ch_work_han_thu_7","textTraditional":"十一月，令民告緡者以其半與之。〔一〕","sentenceOrder":293},
  {"id":"s_work_han_thu_7_294","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　孟康曰：「有不輸稅，令民得告言，以半與之。」","sentenceOrder":294},
  {"id":"s_work_han_thu_7_295","chapterId":"ch_work_han_thu_7","textTraditional":"正月戊子，陽陵園火。夏四月，雨雹，〔一〕關東郡國十餘飢，人相食。","sentenceOrder":295},
  {"id":"s_work_han_thu_7_296","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「雨音于具反。」","sentenceOrder":296},
  {"id":"s_work_han_thu_7_297","chapterId":"ch_work_han_thu_7","textTraditional":"常山王舜薨。子〈勃，中“力改攵”〉嗣立，有罪，廢徙房陵。","sentenceOrder":297},
  {"id":"s_work_han_thu_7_298","chapterId":"ch_work_han_thu_7","textTraditional":"四年冬十月，行幸雍，祠五畤。賜民爵一級，女子百戶牛酒。行自夏陽，東幸汾陰。〔一〕十一月甲子，立后土祠于汾陰脽上。〔二〕禮畢，行幸滎陽。還至洛陽，詔曰：「祭地冀州，〔三〕瞻望河洛，巡省豫州，觀于周室，邈而無祀。〔四〕詢問耆老，乃得孽子嘉。其封嘉為周子南君，〔五〕以奉周祀。」","sentenceOrder":298},
  {"id":"s_work_han_thu_7_299","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「夏陽，馮翊之縣也。汾陰屬河東。汾音扶云反。」","sentenceOrder":299},
  {"id":"s_work_han_thu_7_300","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　蘇林曰：「脽音誰。」如淳曰：「脽者，河之東岸特堆掘，長四五里，廣（一）〔二〕里餘，高十餘丈。汾陰縣治脽之上，后土祠在縣西。汾在脽之北，西流與河合。」師古曰：「二說皆是也。脽者，以其形高起如人尻脽，故以名云。一說此臨汾水之上，地本名鄈，音與葵同，彼鄉人呼葵音如誰，故轉而為脽字耳，故漢舊儀云葵上。」","sentenceOrder":300},
  {"id":"s_work_han_thu_7_301","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　服虔曰：「后土祠在汾陰。汾陰本冀州地也。周時乃分為并州。爾雅曰『兩河間曰冀州』。」","sentenceOrder":301},
  {"id":"s_work_han_thu_7_302","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　師古曰：「邈，遠絕之意。」","sentenceOrder":302},
  {"id":"s_work_han_thu_7_303","chapterId":"ch_work_han_thu_7","textTraditional":"〔五〕　臣瓚曰：「汲冢古文謂衛將軍文子為子南彌牟。其後有子南固、子南勁。紀年勁朝于魏，後惠成王如衛，命子南為侯。秦并六國，衛最後亡。疑嘉是衛後，故氏子南而稱君也。初元五年為周承休侯，元始四年為鄭公，建武十三年（此）〔封〕于觀為衛公。」師古曰：「子南，其封邑之號，以為周後，故總言周子南君。瓚說非也。例不先言姓而後稱君，且自嘉已下皆姓姬氏，著在史傳。」","sentenceOrder":303},
  {"id":"s_work_han_thu_7_304","chapterId":"ch_work_han_thu_7","textTraditional":"春二月，中山王勝薨。","sentenceOrder":304},
  {"id":"s_work_han_thu_7_305","chapterId":"ch_work_han_thu_7","textTraditional":"夏，封方士欒大為樂通侯，位上將軍。","sentenceOrder":305},
  {"id":"s_work_han_thu_7_306","chapterId":"ch_work_han_thu_7","textTraditional":"六月，得寶鼎后土祠旁。秋，馬生渥洼水中。〔一〕作寶鼎、天馬之歌。","sentenceOrder":306},
  {"id":"s_work_han_thu_7_307","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　李斐曰：「南陽新野有暴利長，當武帝時遭刑，屯田敦煌界，數於此水旁見群野馬中有奇（異）者，與凡馬〔異〕，來飲此水。利長先作土人，特勒靽於水旁。後馬玩習，久之代土人特勒靽收得其馬，獻之。欲神異此馬，云從水中出。」蘇林曰：「洼音窐曲之窐。」師古曰：「渥音握。洼音於佳反。」","sentenceOrder":307},
  {"id":"s_work_han_thu_7_308","chapterId":"ch_work_han_thu_7","textTraditional":"立常山憲王子商為泗水王。","sentenceOrder":308},
  {"id":"s_work_han_thu_7_309","chapterId":"ch_work_han_thu_7","textTraditional":"五年冬十月，行幸雍，祠五畤。遂踰隴，〔一〕登空同，〔二〕西臨祖厲河而還。〔三〕","sentenceOrder":309},
  {"id":"s_work_han_thu_7_310","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「隴，隴阺阪也。」師古曰：「即今之隴山，阺音丁禮反。」","sentenceOrder":310},
  {"id":"s_work_han_thu_7_311","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　應劭曰：「山名也。」","sentenceOrder":311},
  {"id":"s_work_han_thu_7_312","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　李斐曰：「音嗟賴。」","sentenceOrder":312},
  {"id":"s_work_han_thu_7_313","chapterId":"ch_work_han_thu_7","textTraditional":"十一月辛巳朔旦，冬至。立泰畤于甘泉。天子親郊見，〔一〕朝日夕月。〔二〕詔曰：「朕以眇身託于王侯之上，〔三〕德未能綏民，〔四〕民或飢寒，故巡祭后土以祈豐年。冀州脽壤乃顯文鼎，獲（祭）〔薦〕於廟。〔五〕渥洼水出馬，朕其御焉。戰戰兢兢，懼不克任，思昭天地，內惟自新。詩云：『四牡翼翼，以征不服。』親省邊垂，用事所極。〔六〕望見泰一，修天文襢。〔七〕辛卯夜，若景光十有二明。易曰：『先甲三日，後甲三日。』〔八〕朕甚念年歲未咸登，〔九〕飭躬齋戒，〔一０〕丁酉，拜況于郊。」〔一一〕","sentenceOrder":313},
  {"id":"s_work_han_thu_7_314","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「祠太一也。見音胡電反。」","sentenceOrder":314},
  {"id":"s_work_han_thu_7_315","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　應劭曰：「天子春朝日，秋夕月。朝日以朝，夕月以夕。」臣瓚曰：「漢儀注郊泰畤，皇帝平旦出竹宮，東向揖日，其夕，西南向揖月，便用郊日，不用春秋也。」師古曰：「春朝朝日，秋暮夕月，蓋常禮也。郊泰畤而揖日月，此又別儀。」","sentenceOrder":315},
  {"id":"s_work_han_thu_7_316","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　師古曰：「眇，細末也。」","sentenceOrder":316},
  {"id":"s_work_han_thu_7_317","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　師古曰：「綏，安也。」","sentenceOrder":317},
  {"id":"s_work_han_thu_7_318","chapterId":"ch_work_han_thu_7","textTraditional":"〔五〕　師古曰：「得鼎祠旁，祠在脽上，故云脽壤。壤謂土也。文鼎，言其有刻鏤之文。」","sentenceOrder":318},
  {"id":"s_work_han_thu_7_319","chapterId":"ch_work_han_thu_7","textTraditional":"〔六〕　李斐曰：「極，至也，所至者輒祭也。」師古曰：「逸詩也。」","sentenceOrder":319},
  {"id":"s_work_han_thu_7_320","chapterId":"ch_work_han_thu_7","textTraditional":"〔七〕　文穎曰：「襢，祭也。」晉灼曰：「襢，古禪字也。」臣瓚曰：「此年初祭太畤於甘泉，此祭天於文襢也。祭天則天文從，故曰修天文襢也。」師古曰：「文、晉二說是也。朝日夕月，即天文襢之謂也。」","sentenceOrder":320},
  {"id":"s_work_han_thu_7_321","chapterId":"ch_work_han_thu_7","textTraditional":"〔八〕　應劭曰：「先甲三日，辛也。後甲三日，丁也。言王者齊戒必自新，臨事必自丁寧。」師古曰：「此易蠱卦之辭。」","sentenceOrder":321},
  {"id":"s_work_han_thu_7_322","chapterId":"ch_work_han_thu_7","textTraditional":"〔九〕　師古曰：「登謂百穀成。」","sentenceOrder":322},
  {"id":"s_work_han_thu_7_323","chapterId":"ch_work_han_thu_7","textTraditional":"〔一０〕師古曰：「飭，整也，讀與敕同。」","sentenceOrder":323},
  {"id":"s_work_han_thu_7_324","chapterId":"ch_work_han_thu_7","textTraditional":"〔一一〕師古曰：「況，賜也。辛夜有光，是先甲三日也。丁日拜況，是後甲三日也。故詔引易文。」","sentenceOrder":324},
  {"id":"s_work_han_thu_7_325","chapterId":"ch_work_han_thu_7","textTraditional":"夏四月，南越王相呂嘉反，殺漢使者及其王、王太后。赦天下。","sentenceOrder":325},
  {"id":"s_work_han_thu_7_326","chapterId":"ch_work_han_thu_7","textTraditional":"丁丑晦，日有蝕之。","sentenceOrder":326},
  {"id":"s_work_han_thu_7_327","chapterId":"ch_work_han_thu_7","textTraditional":"秋，鼃、蝦蟆鬥。〔一〕","sentenceOrder":327},
  {"id":"s_work_han_thu_7_328","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「鼃，黽也，似蝦蟆而長腳，其色青，音下媧反。蝦音遐。蟆音麻。黽音莫幸反。」","sentenceOrder":328},
  {"id":"s_work_han_thu_7_329","chapterId":"ch_work_han_thu_7","textTraditional":"遣伏波將軍路博德出桂陽，下湟水；樓船將軍楊僕出豫章，下湞水；〔一〕歸義越侯嚴為戈船將軍，出零陵，下離水；〔二〕甲為下瀨將軍，下蒼梧。〔三〕皆將罪人，江淮以南樓船十萬人。越馳義侯遺〔四〕別將巴蜀罪人，發夜郎兵，下牂柯江，咸會番禺。〔五〕","sentenceOrder":329},
  {"id":"s_work_han_thu_7_330","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　鄭氏曰：「湞音檉。」孟康曰：「湞音貞。」蘇林曰：「湞音摚柱之摚。」師古曰：「蘇音是也。音丈庚反。」","sentenceOrder":330},
  {"id":"s_work_han_thu_7_331","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　張晏曰：「嚴故越人，降為歸義侯。越人於水中負人船，又有蛟龍之害，故置戈於船下，因以為名也。」臣瓚曰：「伍子胥書有戈船，以載干戈，因謂之戈船也。離水出零陵。」師古曰：「以樓船之例言之，則非為載干戈也。此蓋船下安戈戟以御蛟鼉水蟲之害。張說近之。」","sentenceOrder":331},
  {"id":"s_work_han_thu_7_332","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　服虔曰：「甲，故越人歸漢者也。」臣瓚曰：「瀨，湍也，吳越謂之瀨，中國謂之磧。伍子胥書有下瀨船。」師古曰：「瀨音賴。」","sentenceOrder":332},
  {"id":"s_work_han_thu_7_333","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　應劭曰：「亦越人也。」","sentenceOrder":333},
  {"id":"s_work_han_thu_7_334","chapterId":"ch_work_han_thu_7","textTraditional":"〔五〕　如淳曰：「音潘（禺）〔愚〕，尉佗所都。」師古曰：「即今之廣州。」","sentenceOrder":334},
  {"id":"s_work_han_thu_7_335","chapterId":"ch_work_han_thu_7","textTraditional":"九月，列侯坐獻黃金酎祭宗廟不如法奪爵者百六人，丞相趙周下獄死。〔一〕樂通侯欒大坐誣罔要斬。","sentenceOrder":335},
  {"id":"s_work_han_thu_7_336","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　服虔曰：「因八月獻酎祭宗廟時使諸侯各獻金來助祭也。」如淳曰：「漢儀注諸侯王歲以戶口酎黃金於漢廟，皇帝臨受獻金，金少不如斤兩，色惡，王削縣，侯免國。」臣瓚曰：「食貨志南越反時卜式上書願死之。天子下詔褒揚，布告天下，天下莫應。列侯以百數，莫求從軍。至酎飲酒，少府省金，而列侯坐酎金失侯者百餘人。而表云趙周坐為丞相知列侯酎金輕下獄自殺。然則知其輕而不糾擿之也。」師古曰：「酎，三重釀醇酒也，音丈救反。」","sentenceOrder":336},
  {"id":"s_work_han_thu_7_337","chapterId":"ch_work_han_thu_7","textTraditional":"西羌眾十萬人反，與匈奴通使，攻故安，圍枹罕。〔一〕匈奴入五原，殺太守。","sentenceOrder":337},
  {"id":"s_work_han_thu_7_338","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　鄧展曰：「枹音鈇。罕音漢。」師古曰：「枹罕，金城之縣也。罕讀如本字。」","sentenceOrder":338},
  {"id":"s_work_han_thu_7_339","chapterId":"ch_work_han_thu_7","textTraditional":"六年冬十月，發隴西、天水、安定騎士及中尉，河南、河內卒十萬人，遣將軍李息、郎中令（一）〔徐〕自為征西羌，平之。","sentenceOrder":339},
  {"id":"s_work_han_thu_7_340","chapterId":"ch_work_han_thu_7","textTraditional":"行東，將幸緱氏，〔一〕至左邑桐鄉，〔二〕聞南越破，以為聞喜縣。春，至汲新中鄉，〔三〕得呂嘉首，以為獲嘉縣。馳義侯遺兵未及下，上便令征西南夷，平之。〔四〕遂定越地，以為南海、蒼梧、鬱林、合浦、交阯、九真、日南、珠崖、儋耳郡。〔五〕定西南夷，以為武都、牂柯、越嶲、沈黎、文山郡。〔六〕","sentenceOrder":340},
  {"id":"s_work_han_thu_7_341","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「河南縣也。緱音工侯反。」","sentenceOrder":341},
  {"id":"s_work_han_thu_7_342","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「左邑，河東之縣也。桐鄉，其鄉名也。」","sentenceOrder":342},
  {"id":"s_work_han_thu_7_343","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　師古曰：「汲，河內縣。新中，其鄉名。」","sentenceOrder":343},
  {"id":"s_work_han_thu_7_344","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　師古曰：「便音頻面反。」","sentenceOrder":344},
  {"id":"s_work_han_thu_7_345","chapterId":"ch_work_han_thu_7","textTraditional":"〔五〕　應劭曰：「二郡在大海中崖岸之邊。出真珠，故曰珠崖。儋耳者，種大耳。渠率自謂王者耳尤緩，下肩三寸。」張晏曰：「異物志二郡在海中，東西千里，南北五百里。珠崖，言珠若崖矣。儋耳之云，鏤其頰皮，上連耳匡，分為數支，狀似雞腸，累耳下垂。」臣瓚曰：「茂陵書珠崖郡治瞫都，去長安七千三百一十四里。儋耳去長安七千三百六十八里，領縣五。」師古曰：「儋音丁甘反，字本作瞻。瞫音審。」","sentenceOrder":345},
  {"id":"s_work_han_thu_7_346","chapterId":"ch_work_han_thu_7","textTraditional":"〔六〕　孟康曰：「嶲音髓，本邛都。」服虔曰：「今蜀郡北部都尉所治，本笮都也。」臣瓚曰：「茂陵書沈黎治笮都，去長安三千三百三十五里，領縣二十一。」應劭曰：「文山，今蜀郡瑉山，本冉駹是也。」","sentenceOrder":346},
  {"id":"s_work_han_thu_7_347","chapterId":"ch_work_han_thu_7","textTraditional":"秋，東越王餘善反，攻殺漢將吏。遣橫海將軍韓說、中尉王溫舒出會稽，〔一〕樓船將軍楊僕出豫章，擊之。又遣浮沮將軍公孫賀出九原，〔二〕匈河將軍趙破奴出令居，〔三〕皆二千餘里，不見虜而還。乃分武威、酒泉地置張掖、敦煌郡，〔四〕徙民以實之。","sentenceOrder":347},
  {"id":"s_work_han_thu_7_348","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":348},
  {"id":"s_work_han_thu_7_349","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　臣瓚曰：「浮沮，井名，在匈奴中，去九原二千里，見漢輿地圖。」師古曰：「沮音子閭反。」","sentenceOrder":349},
  {"id":"s_work_han_thu_7_350","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　臣瓚曰：「匈河，水名，在匈奴中，去令居千里，見匈奴傳。」師古曰：「令音鈴。」","sentenceOrder":350},
  {"id":"s_work_han_thu_7_351","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　師古曰：「敦音徒門反。」","sentenceOrder":351},
  {"id":"s_work_han_thu_7_352","chapterId":"ch_work_han_thu_7","textTraditional":"元封元年〔一〕冬十月，詔曰：「南越、東甌咸伏其辜，西蠻北夷頗未輯睦，〔二〕朕將巡邊垂，擇兵振旅，躬秉武節，置十二部將軍，親帥師焉。」行自雲陽，北歷上郡、西河、五原，出長城，北登單于臺，至朔方，臨北河。勒兵十八萬騎，旌旗徑千餘里，威震匈奴。遣使者告單于曰：「南越王頭已縣於漢北闕矣。單于能戰，天子自將待邊；不能，亟來臣服。〔三〕何但亡匿幕北寒苦之地為！」匈奴讋焉。〔四〕還，祠黃帝於橋山，〔五〕乃歸甘泉。","sentenceOrder":352},
  {"id":"s_work_han_thu_7_353","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「始封泰山，故改年。」","sentenceOrder":353},
  {"id":"s_work_han_thu_7_354","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「輯與集同。集，和也。」","sentenceOrder":354},
  {"id":"s_work_han_thu_7_355","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　師古曰：「亟，急也，音居力反。」","sentenceOrder":355},
  {"id":"s_work_han_thu_7_356","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　師古曰：「讋，失氣也，音之涉反。」","sentenceOrder":356},
  {"id":"s_work_han_thu_7_357","chapterId":"ch_work_han_thu_7","textTraditional":"〔五〕　應劭曰：「在上郡，周陽縣有黃帝冢。」","sentenceOrder":357},
  {"id":"s_work_han_thu_7_358","chapterId":"ch_work_han_thu_7","textTraditional":"東越殺王餘善降。詔曰：「東越險阻反覆，為後世患，遷其民於江淮間。」遂虛其地。","sentenceOrder":358},
  {"id":"s_work_han_thu_7_359","chapterId":"ch_work_han_thu_7","textTraditional":"春正月，行幸緱氏。詔曰：「朕用事華山，至於中嶽，〔一〕獲駮麃，見夏后啟母石。〔二〕翌日親登嵩高，〔三〕御史乘屬，在廟旁吏卒咸聞呼萬歲者三。〔四〕登禮罔不答。〔五〕其令祠官加增太室祠，〔六〕禁無伐其草木。以山下戶三百為之奉邑，名曰崇高〔七〕，獨給祠，復亡所與。」〔八〕行，遂東巡海上。","sentenceOrder":359},
  {"id":"s_work_han_thu_7_360","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　文穎曰：「嵩高也，在潁川陽城縣。」","sentenceOrder":360},
  {"id":"s_work_han_thu_7_361","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　應劭曰：「啟生而母化為石。」文穎曰：「在嵩高山下。」師古曰：「啟，夏禹子也。其母塗山氏女也。禹治鴻水，通轘轅山，化為熊，謂塗山氏曰：『欲餉，聞鼓聲乃來。』禹跳石，誤中鼓。塗山氏往，見禹方作熊，慚而去，至嵩高山下化為石，方生啟。禹曰：『歸我子。』石破北方而啟生。事見淮南子。景帝諱啟，今此詔云啟母，蓋史追書之，非當時文。」","sentenceOrder":361},
  {"id":"s_work_han_thu_7_362","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　應劭曰：「翌，明也。」","sentenceOrder":362},
  {"id":"s_work_han_thu_7_363","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　服虔曰：「乘，同乘。屬，官屬也。」如淳曰：「漢儀注御史亦有屬。」晉灼曰：「天子出，御史除二人為乘曹，護車駕。」荀悅曰：「萬歲，山神稱之也。」應劭曰：「嵩高縣有上中下萬歲里。」師古曰：「乘屬，如、晉二說是也。乘音食證反。」","sentenceOrder":363},
  {"id":"s_work_han_thu_7_364","chapterId":"ch_work_han_thu_7","textTraditional":"〔五〕　師古曰：「罔，無也。言登禮於神，無不答應。」","sentenceOrder":364},
  {"id":"s_work_han_thu_7_365","chapterId":"ch_work_han_thu_7","textTraditional":"〔六〕　韋昭曰：「嵩高山有太室、少室之山，山有石室，故以名云。」","sentenceOrder":365},
  {"id":"s_work_han_thu_7_366","chapterId":"ch_work_han_thu_7","textTraditional":"〔七〕　師古曰：「謂之崇者，示尊崇之。奉音扶用反。」","sentenceOrder":366},
  {"id":"s_work_han_thu_7_367","chapterId":"ch_work_han_thu_7","textTraditional":"〔八〕　師古曰：「復音方目反。與讀曰預。」","sentenceOrder":367},
  {"id":"s_work_han_thu_7_368","chapterId":"ch_work_han_thu_7","textTraditional":"夏四月癸卯，上還，登封泰山，〔一〕降坐明堂。〔二〕詔曰：「朕以眇身承至尊，〔三〕兢兢焉惟德菲薄，不明于禮樂，〔四〕故用事八神。〔五〕遭天地況施，〔六〕著見景象，〈佾，中“亻改尸”〉然如有聞。〔七〕震于怪物，欲止不敢，遂登封泰山，至於梁父，然後升襢肅然〔八〕。自新，嘉與士大夫更始，其以十月為元封元年。行所巡至，博、奉高、蛇丘，歷城、梁父，〔九〕民田租逋賦貸，已除。〔一０〕加年七十以上孤寡帛，人二匹。四縣無出今年算。〔一一〕賜天下民爵一級，女子百戶牛酒。」","sentenceOrder":368},
  {"id":"s_work_han_thu_7_369","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　孟康曰：「王者功成治定，告成功於天。封，崇也，助天之高也。刻石紀號，有金策石函金泥玉檢之封焉。」應劭曰：「封者，壇廣十二丈，高二丈，階三等，封於其上，示增高也。刻石，紀績也。立石三丈一尺，其辭曰：『事天以禮，立身以義。事親以孝，育民以仁。四守之內莫不為郡縣，四夷八蠻咸來貢職，與天無極。人民蕃息，天祿永得。』尚玄酒而俎生魚。下禪梁父，祀地主，示增廣。（比）〔此〕古制也。武帝封廣丈二尺，高九尺，其下則有縢書，祕。語在郊祀志。」","sentenceOrder":369},
  {"id":"s_work_han_thu_7_370","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　臣瓚曰：「郊祀志『初，天子封泰山，泰山東北阯古時有明堂處』，則此所坐者也。明年秋乃作明堂耳。」","sentenceOrder":370},
  {"id":"s_work_han_thu_7_371","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　師古曰：「眇，微細也。」","sentenceOrder":371},
  {"id":"s_work_han_thu_7_372","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　師古曰：「菲，亦薄也，音敷尾反，又音靡。」","sentenceOrder":372},
  {"id":"s_work_han_thu_7_373","chapterId":"ch_work_han_thu_7","textTraditional":"〔五〕　文穎曰：「武帝祭太一，並祭名山於太壇西南，開除八通鬼道，故言用事八神也。一曰八方之神。」","sentenceOrder":373},
  {"id":"s_work_han_thu_7_374","chapterId":"ch_work_han_thu_7","textTraditional":"〔六〕　應劭曰：「況，賜也。施，與也。言天地神靈乃賜我瑞應。」","sentenceOrder":374},
  {"id":"s_work_han_thu_7_375","chapterId":"ch_work_han_thu_7","textTraditional":"〔七〕　臣瓚曰：「聞呼萬歲者三是也。」","sentenceOrder":375},
  {"id":"s_work_han_thu_7_376","chapterId":"ch_work_han_thu_7","textTraditional":"〔八〕　服虔曰：「增天之高，歸功於天。禪，闡也，廣土地也。肅然，山名也，在梁父。」張晏曰：「天高不可及，於泰山上立封，又禪而祭之，冀近神靈也。」師古曰：「父讀曰甫。」","sentenceOrder":376},
  {"id":"s_work_han_thu_7_377","chapterId":"ch_work_han_thu_7","textTraditional":"〔九〕　鄭氏曰：「蛇音移。」","sentenceOrder":377},
  {"id":"s_work_han_thu_7_378","chapterId":"ch_work_han_thu_7","textTraditional":"〔一０〕師古曰：「逋賦，未出賦者也。逋貸，官以物貸之，而未還也。貸音吐戴反。」","sentenceOrder":378},
  {"id":"s_work_han_thu_7_379","chapterId":"ch_work_han_thu_7","textTraditional":"〔一一〕師古曰：「自博至梁父凡五縣，今云四縣毋出算者，奉高一縣素以供神，非算限也。」","sentenceOrder":379},
  {"id":"s_work_han_thu_7_380","chapterId":"ch_work_han_thu_7","textTraditional":"行自泰山，復東巡海上，至碣石。〔一〕自遼西歷北邊九原，歸于甘泉。","sentenceOrder":380},
  {"id":"s_work_han_thu_7_381","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　文穎曰：「在遼西絫縣。絫縣今罷，屬臨榆。此石著海旁。」師古曰：「碣，碣然特立之貌也，音其列反。」","sentenceOrder":381},
  {"id":"s_work_han_thu_7_382","chapterId":"ch_work_han_thu_7","textTraditional":"秋，有星孛于東井，又孛于三台。","sentenceOrder":382},
  {"id":"s_work_han_thu_7_383","chapterId":"ch_work_han_thu_7","textTraditional":"齊王閎薨。","sentenceOrder":383},
  {"id":"s_work_han_thu_7_384","chapterId":"ch_work_han_thu_7","textTraditional":"二年冬十月，行幸雍，祠五畤。春，幸緱氏，遂至東萊。夏四月，還祠泰山。至瓠子，臨決河，〔一〕命從臣將軍以下皆負薪塞河隄，作瓠子之歌。赦所過徒，賜孤獨高年米，人四石。還，作甘泉通天臺、長安飛廉館。〔二〕","sentenceOrder":384},
  {"id":"s_work_han_thu_7_385","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　服虔曰：「瓠子，隄名也，在東郡白馬。」蘇林曰：「在鄄城以南，濮陽以北，廣百步，深五丈。」","sentenceOrder":385},
  {"id":"s_work_han_thu_7_386","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　應劭曰：「飛廉，神禽能致風氣者也。明帝永平五年，至長安迎取飛廉并銅馬，置上西門外，名平樂館。董卓悉銷以為錢。」晉灼曰：「身似鹿，頭如爵，有角而蛇尾，文如豹文。」師古曰：「通天臺者，言此臺高，上通於天也。漢舊儀云高三十丈，望見長安城。」","sentenceOrder":386},
  {"id":"s_work_han_thu_7_387","chapterId":"ch_work_han_thu_7","textTraditional":"朝鮮王攻殺遼東都尉，乃募天下死罪擊朝鮮。","sentenceOrder":387},
  {"id":"s_work_han_thu_7_388","chapterId":"ch_work_han_thu_7","textTraditional":"六月，詔曰：「甘泉宮內中產芝，九莖連葉。〔一〕上帝博臨，不異下房，賜朕弘休。〔二〕其赦天下，賜雲陽都百戶牛酒。」〔三〕作芝房之歌。","sentenceOrder":388},
  {"id":"s_work_han_thu_7_389","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「芝，芝草也，其葉相連。」如淳曰：「瑞應圖王者敬事耆老，不失舊故，則芝草生。」師古曰：「內中，謂後庭之室也，故云不異下房。」","sentenceOrder":389},
  {"id":"s_work_han_thu_7_390","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「上帝，天也。博，廣也。弘，大也。休，美也。言天廣臨，不以下房為幽側而隔異之，賜以此芝，是大美也。」","sentenceOrder":390},
  {"id":"s_work_han_thu_7_391","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　晉灼曰：「雲陽、甘泉，黃帝以來祭天圓丘處也。武帝常以避暑，有宮觀，故稱都也。」師古曰：「此說非也。都謂縣之所居在宮側者耳。賜不遍其境內，故指稱其都，非謂天子之都也。若以有宮觀稱都，則非止雲陽矣。」","sentenceOrder":391},
  {"id":"s_work_han_thu_7_392","chapterId":"ch_work_han_thu_7","textTraditional":"秋，作明堂于泰山下。","sentenceOrder":392},
  {"id":"s_work_han_thu_7_393","chapterId":"ch_work_han_thu_7","textTraditional":"遣樓船將軍楊僕、左將軍荀彘將應募罪人擊朝鮮。〔一〕又遣將軍郭昌、中郎將衛廣發巴蜀兵平西南夷未服者，以為益州郡。","sentenceOrder":393},
  {"id":"s_work_han_thu_7_394","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「樓船者，時欲擊越，非水不至，故作大船，上施樓也。」","sentenceOrder":394},
  {"id":"s_work_han_thu_7_395","chapterId":"ch_work_han_thu_7","textTraditional":"三年春，作角抵戲，〔一〕三百里內皆（來）觀。","sentenceOrder":395},
  {"id":"s_work_han_thu_7_396","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「角者，角技也。抵者，相抵觸也。」文穎曰：「名此樂為角抵者，兩兩相當角力，角技藝射御，故名角抵，蓋雜技樂也。巴俞戲、魚龍蔓延之屬也。漢後更名平樂觀。」師古曰：「抵者，當也。非謂抵觸。文說是也。」","sentenceOrder":396},
  {"id":"s_work_han_thu_7_397","chapterId":"ch_work_han_thu_7","textTraditional":"夏，朝鮮斬其王右渠降，〔一〕以其地為樂浪、臨屯、玄菟、真番郡。〔二〕","sentenceOrder":397},
  {"id":"s_work_han_thu_7_398","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「右渠，朝鮮王名。」","sentenceOrder":398},
  {"id":"s_work_han_thu_7_399","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　臣瓚曰：「茂陵書臨屯郡治東暆縣，去長安六千一百三十八里，十五縣；真番郡治霅縣，去長安七千六百四十里，十五縣。」師古曰：「樂音洛。浪音郎。番音普安反。暆音弋支反。霅音丈甲反。」","sentenceOrder":399},
  {"id":"s_work_han_thu_7_400","chapterId":"ch_work_han_thu_7","textTraditional":"樓船將軍楊僕坐失亡多免為庶民，左將軍荀彘坐爭功棄市。〔一〕","sentenceOrder":400},
  {"id":"s_work_han_thu_7_401","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「棄市，殺之於市也。解在景紀。」","sentenceOrder":401},
  {"id":"s_work_han_thu_7_402","chapterId":"ch_work_han_thu_7","textTraditional":"秋七月，膠西王端薨。","sentenceOrder":402},
  {"id":"s_work_han_thu_7_403","chapterId":"ch_work_han_thu_7","textTraditional":"武都氐人反，分徙酒泉郡。〔一〕","sentenceOrder":403},
  {"id":"s_work_han_thu_7_404","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「不盡徙。」","sentenceOrder":404},
  {"id":"s_work_han_thu_7_405","chapterId":"ch_work_han_thu_7","textTraditional":"四年冬十月，行幸雍，祠五畤。通回中道，〔一〕遂北出蕭關，〔二〕歷獨鹿、鳴澤，〔三〕自代而還，幸河東。春三月，祠后土。詔曰：「朕躬祭后土地祇，見光集于靈壇，一夜三燭。〔四〕幸中都宮，殿上見光。〔五〕其赦汾陰、夏陽、中都死罪以下，賜三縣及楊氏皆無出今年租賦。」〔六〕","sentenceOrder":405},
  {"id":"s_work_han_thu_7_406","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「回中在安定高平，有險阻，蕭關在其北，通治至長安也。」孟康曰：「回中在北地，有山險，武帝故宮。」如淳曰：「三輔黃圖云回中宮在〈氵幵〉也。」師古曰：「回中在安定，北通蕭關。應說是也。而云治道至長安，非也。蓋自回中通道以出蕭關。孟、如二家皆失之矣。回中宮在汧者，或取安定回中為名耳，非今所通道。」","sentenceOrder":406},
  {"id":"s_work_han_thu_7_407","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　如淳曰：「匈奴傳『入朝〈舟阝〉蕭關』，蕭關在安定朝〈舟阝〉縣也。」","sentenceOrder":407},
  {"id":"s_work_han_thu_7_408","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　服虔曰：「獨鹿，山名也。鳴澤，澤名也。皆在涿郡遒縣北界也。」","sentenceOrder":408},
  {"id":"s_work_han_thu_7_409","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　服虔曰：「燭音注。」師古曰：「燭謂照也，讀如本字。」","sentenceOrder":409},
  {"id":"s_work_han_thu_7_410","chapterId":"ch_work_han_thu_7","textTraditional":"〔五〕　師古曰：「中都在太原。」","sentenceOrder":410},
  {"id":"s_work_han_thu_7_411","chapterId":"ch_work_han_thu_7","textTraditional":"〔六〕　師古曰：「楊氏，河東聚邑名。」","sentenceOrder":411},
  {"id":"s_work_han_thu_7_412","chapterId":"ch_work_han_thu_7","textTraditional":"夏，大旱，民多暍死。〔一〕","sentenceOrder":412},
  {"id":"s_work_han_thu_7_413","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　如淳曰：「暍音謁。」師古曰：「中熱而死也。」","sentenceOrder":413},
  {"id":"s_work_han_thu_7_414","chapterId":"ch_work_han_thu_7","textTraditional":"秋，以匈奴弱，可遂臣服，乃遣使說之。單于使來，死京師。匈奴寇邊，遣拔胡將軍郭昌屯朔方。","sentenceOrder":414},
  {"id":"s_work_han_thu_7_415","chapterId":"ch_work_han_thu_7","textTraditional":"五年冬，行南巡狩，至于盛唐，〔一〕望祀虞舜于九嶷。〔二〕登灊天柱山，〔三〕自尋陽浮江，親射蛟江中，獲之。〔四〕舳艫千里，〔五〕薄樅陽而出，〔六〕作盛唐樅陽之歌。遂北至琅邪，並海，〔七〕所過禮祠其名山大川。春三月，還至泰山，增封。甲子，祠高祖于明堂，以配上帝，因朝諸侯王列侯，受郡國計。〔八〕夏四月，詔曰：「朕巡荊揚，輯江淮物，〔九〕會大海氣，〔一０〕以合泰山。〔一一〕上天見象，增修封禪。〔一二〕其赦天下。所幸縣毋出今年租賦，賜鰥寡孤獨帛，貧窮者粟。」還幸甘泉，郊泰畤。","sentenceOrder":415},
  {"id":"s_work_han_thu_7_416","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　文穎曰：「案地（里）〔理〕志不得，疑當在廬江左右，縣名也。」韋昭曰：「在南郡。」師古曰：「韋說是也。」","sentenceOrder":416},
  {"id":"s_work_han_thu_7_417","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　應劭曰：「舜葬蒼梧。九嶷，山名，今在零陵營道。」文穎曰：「九嶷山半在蒼梧，半在零陵。」如淳曰：「舜葬九嶷。九嶷在蒼梧馮乘縣，故或云舜葬蒼梧也。」師古曰：「文說是也。嶷音疑，其山九峰，形勢相似，故云九嶷山。」","sentenceOrder":417},
  {"id":"s_work_han_thu_7_418","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　應劭曰：「灊音若潛。南獄霍山在灊。灊，縣名，屬廬江。」文穎曰：「天柱山在灊縣南，有祠。灊音岑。」師古曰：「灊音與潛同。應說是。」","sentenceOrder":418},
  {"id":"s_work_han_thu_7_419","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　師古曰：「許慎云『蛟，龍屬也』。郭璞說其狀云似蛇而四腳，細頸，頸有白嬰，大者數圍，卵生，子如一二斛瓮，能吞人也。」","sentenceOrder":419},
  {"id":"s_work_han_thu_7_420","chapterId":"ch_work_han_thu_7","textTraditional":"〔五〕　李斐曰：「舳，船後持柂處也。艫，船前頭刺櫂處也。言其船多，前後相銜，千里不絕也。」師古曰：「舳音軸。艫音盧。」","sentenceOrder":420},
  {"id":"s_work_han_thu_7_421","chapterId":"ch_work_han_thu_7","textTraditional":"〔六〕　服虔曰：「縣名，屬廬江。」師古曰：「樅音千松反。」","sentenceOrder":421},
  {"id":"s_work_han_thu_7_422","chapterId":"ch_work_han_thu_7","textTraditional":"〔七〕　師古曰：「並讀曰傍。傍，依也，音步浪反。」","sentenceOrder":422},
  {"id":"s_work_han_thu_7_423","chapterId":"ch_work_han_thu_7","textTraditional":"〔八〕　師古曰：「計，若今之諸州計帳也。」","sentenceOrder":423},
  {"id":"s_work_han_thu_7_424","chapterId":"ch_work_han_thu_7","textTraditional":"〔九〕　如淳曰：「輯，合也。物猶神也，郊祀志所祭祀事也。」師古曰：「輯與集同。」","sentenceOrder":424},
  {"id":"s_work_han_thu_7_425","chapterId":"ch_work_han_thu_7","textTraditional":"〔一０〕鄭氏曰：「會合海神之氣，并祭之。」","sentenceOrder":425},
  {"id":"s_work_han_thu_7_426","chapterId":"ch_work_han_thu_7","textTraditional":"〔一一〕師古曰：「集江淮之神，會大海之氣，合致於太山，然後修封，總祭饗也。」","sentenceOrder":426},
  {"id":"s_work_han_thu_7_427","chapterId":"ch_work_han_thu_7","textTraditional":"〔一二〕師古曰：「見謂顯示也。」","sentenceOrder":427},
  {"id":"s_work_han_thu_7_428","chapterId":"ch_work_han_thu_7","textTraditional":"大司馬大將軍青薨。","sentenceOrder":428},
  {"id":"s_work_han_thu_7_429","chapterId":"ch_work_han_thu_7","textTraditional":"初置刺史部十三州。〔一〕名臣文武欲盡，詔曰：「蓋有非常之功，必待非常之人，故馬或奔踶而致千里，〔二〕士或有負俗之累而立功名。〔三〕夫泛駕之馬，〔四〕跅弛之士，〔五〕亦在御之而已。〔六〕其令州郡察吏民有茂材異等〔七〕可為將相及使絕國者。」〔八〕","sentenceOrder":429},
  {"id":"s_work_han_thu_7_430","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「漢（書）〔舊〕儀云初分十三州，假刺史印綬，有常治所。常以秋分行部，御史為駕四封乘傳。到所部，郡國各遣一吏迎之界上，所察六條。」","sentenceOrder":430},
  {"id":"s_work_han_thu_7_431","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「踶，蹋也。奔，走也。奔踶者，乘之即奔，立則踶人也。踶音徒計反。」","sentenceOrder":431},
  {"id":"s_work_han_thu_7_432","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　晉灼曰：「負俗，謂被世譏論也。」師古曰：「累音力瑞反。」","sentenceOrder":432},
  {"id":"s_work_han_thu_7_433","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　師古曰：「泛，覆也，音（力）〔方〕勇反。字本作覂，後通用耳。覆駕者，言馬有逸氣而不循軌轍也。」","sentenceOrder":433},
  {"id":"s_work_han_thu_7_434","chapterId":"ch_work_han_thu_7","textTraditional":"〔五〕　如淳曰：「跅（拓也）〔音拓〕。弛，廢也。士行有卓異，不入俗檢而見跅逐者也。」師古曰：「跅者，跅落無檢局也。弛者，放廢不遵禮度也。跅音土各反。弛音式爾反。」","sentenceOrder":434},
  {"id":"s_work_han_thu_7_435","chapterId":"ch_work_han_thu_7","textTraditional":"〔六〕　師古曰：「在人所以制御之。」","sentenceOrder":435},
  {"id":"s_work_han_thu_7_436","chapterId":"ch_work_han_thu_7","textTraditional":"〔七〕　應劭曰：「舊言秀才，避光武諱稱茂才。異等者，超等軼群不與凡同也。」師古曰：「茂，美也。」","sentenceOrder":436},
  {"id":"s_work_han_thu_7_437","chapterId":"ch_work_han_thu_7","textTraditional":"〔八〕　師古曰：「絕遠之國，謂聲教之外。」","sentenceOrder":437},
  {"id":"s_work_han_thu_7_438","chapterId":"ch_work_han_thu_7","textTraditional":"六年冬，行幸回中。春，作首山宮。〔一〕","sentenceOrder":438},
  {"id":"s_work_han_thu_7_439","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「首山在上郡，於其下立宮廟也。」文穎曰：「在河東蒲阪界。」師古曰：「尋此下詔文及依地理志，文說是。」","sentenceOrder":439},
  {"id":"s_work_han_thu_7_440","chapterId":"ch_work_han_thu_7","textTraditional":"三月，行幸河東，祠后土。詔曰：「朕禮首山，昆田出珍物，化或為黃金。〔一〕祭后土，神光三燭。其赦汾陰殊死以下，賜天下貧民布帛，人一匹。」","sentenceOrder":440},
  {"id":"s_work_han_thu_7_441","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「昆田，首山之下田也。武帝祠首山，故神為出珍物，化為黃金。」","sentenceOrder":441},
  {"id":"s_work_han_thu_7_442","chapterId":"ch_work_han_thu_7","textTraditional":"益州、昆明反，赦京師亡命令從軍，遣拔胡將軍郭昌將以擊之。","sentenceOrder":442},
  {"id":"s_work_han_thu_7_443","chapterId":"ch_work_han_thu_7","textTraditional":"夏，京師民觀角抵于上林平樂館。","sentenceOrder":443},
  {"id":"s_work_han_thu_7_444","chapterId":"ch_work_han_thu_7","textTraditional":"秋，大旱，蝗。","sentenceOrder":444},
  {"id":"s_work_han_thu_7_445","chapterId":"ch_work_han_thu_7","textTraditional":"太初元年〔一〕冬十月，行幸泰山。","sentenceOrder":445},
  {"id":"s_work_han_thu_7_446","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「初用夏正，以正月為歲首，故改年為太初也。」","sentenceOrder":446},
  {"id":"s_work_han_thu_7_447","chapterId":"ch_work_han_thu_7","textTraditional":"十一月甲子朔旦，冬至，祀上帝于明堂。","sentenceOrder":447},
  {"id":"s_work_han_thu_7_448","chapterId":"ch_work_han_thu_7","textTraditional":"乙酉，柏梁臺災。","sentenceOrder":448},
  {"id":"s_work_han_thu_7_449","chapterId":"ch_work_han_thu_7","textTraditional":"十二月，禪高里，〔一〕祠后土。東臨勃海，望祠蓬萊。春還，受計于甘泉。〔二〕","sentenceOrder":449},
  {"id":"s_work_han_thu_7_450","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　伏儼曰：「山名，在泰山下。」師古曰：「此高字自作高下之高，而死人之里謂之蒿里，或呼為下里者也，字則為蓬蒿之蒿。或者既見太山神靈之府，高里山又在其旁，即誤以高里為蒿里。混同一事，文學之士共有此謬，陸士衡尚不免，況其餘乎？今流俗書本此高字有作蒿者，妄加增耳。」","sentenceOrder":450},
  {"id":"s_work_han_thu_7_451","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「受郡國所上計簿也。若今之諸州計帳。」","sentenceOrder":451},
  {"id":"s_work_han_thu_7_452","chapterId":"ch_work_han_thu_7","textTraditional":"二月，起建章宮。〔一〕","sentenceOrder":452},
  {"id":"s_work_han_thu_7_453","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　文穎曰：「越巫名勇，謂帝曰越國有火災即復大起宮室以厭勝之，故帝作建章宮。」師古曰：「在未央宮西，今長安故城西俗所呼貞女樓者，即建章宮之闕也。」","sentenceOrder":453},
  {"id":"s_work_han_thu_7_454","chapterId":"ch_work_han_thu_7","textTraditional":"夏五月，正曆，以正月為歲首。〔一〕色上黃，數用五，〔二〕定官名，協音律。","sentenceOrder":454},
  {"id":"s_work_han_thu_7_455","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「謂以建寅之月為正也。未正曆之前謂建亥之月為正，今此言以正月為歲首者，史追正其月名。」","sentenceOrder":455},
  {"id":"s_work_han_thu_7_456","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　張晏曰：「漢據土德，土數五，故用五，謂印文也。若丞相曰『丞相之印章』，諸卿及守相印文不足五字者，以『之』足之。」","sentenceOrder":456},
  {"id":"s_work_han_thu_7_457","chapterId":"ch_work_han_thu_7","textTraditional":"遣因杅將軍公孫敖〔一〕築塞外受降城。","sentenceOrder":457},
  {"id":"s_work_han_thu_7_458","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　服虔曰：「匈奴地名，因所征以名將軍也。」師古曰：「杅音羽俱反。」","sentenceOrder":458},
  {"id":"s_work_han_thu_7_459","chapterId":"ch_work_han_thu_7","textTraditional":"秋八月，行幸安定。遣貳師將軍李廣利〔一〕發天下謫民西征大宛。〔二〕","sentenceOrder":459},
  {"id":"s_work_han_thu_7_460","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　張晏曰：「貳師，大宛城名。」","sentenceOrder":460},
  {"id":"s_work_han_thu_7_461","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「庶人之有罪謫者也。大宛，國名。宛音於元反。」","sentenceOrder":461},
  {"id":"s_work_han_thu_7_462","chapterId":"ch_work_han_thu_7","textTraditional":"蝗從東方飛至敦煌。","sentenceOrder":462},
  {"id":"s_work_han_thu_7_463","chapterId":"ch_work_han_thu_7","textTraditional":"二年春正月戊申，丞相慶薨。〔一〕","sentenceOrder":463},
  {"id":"s_work_han_thu_7_464","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「石慶也。」","sentenceOrder":464},
  {"id":"s_work_han_thu_7_465","chapterId":"ch_work_han_thu_7","textTraditional":"三月，行幸河東，祠后土。令天下大酺五日，膢五日，祠門戶，比臘。〔一〕","sentenceOrder":465},
  {"id":"s_work_han_thu_7_466","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　如淳曰：「膢音樓。漢儀注立秋貙膢。」伏儼曰：「膢音劉。劉，殺也。」蘇林曰：「膢，祭名也。貙，虎屬。常以立秋日祭獸王者，亦以此日出（臘）〔獵〕，還，以祭宗廟，故有貙膢之祭也。」師古曰：「續漢書作貙劉。膢、劉義各通耳。臘者，冬至後臘祭百神也。臘音來盍反。」","sentenceOrder":466},
  {"id":"s_work_han_thu_7_467","chapterId":"ch_work_han_thu_7","textTraditional":"夏四月，詔曰：「朕用事介山，祭后土，皆有光應。〔一〕其赦汾陰、安邑殊死以下。」","sentenceOrder":467},
  {"id":"s_work_han_thu_7_468","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　文穎曰：「介山在河東皮氏縣東南。其山特立，周七十里，高三十里。」","sentenceOrder":468},
  {"id":"s_work_han_thu_7_469","chapterId":"ch_work_han_thu_7","textTraditional":"五月，籍吏民馬，補車騎馬。〔一〕","sentenceOrder":469},
  {"id":"s_work_han_thu_7_470","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「籍者，總入籍錄而取之。」","sentenceOrder":470},
  {"id":"s_work_han_thu_7_471","chapterId":"ch_work_han_thu_7","textTraditional":"秋，蝗。遣浚稽將軍趙破奴〔一〕二萬騎出朔方擊匈奴，不還。","sentenceOrder":471},
  {"id":"s_work_han_thu_7_472","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「浚稽山在武威塞北，匈奴常（取）〔所〕以為障蔽。」師古曰：「浚音峻。稽音雞。」","sentenceOrder":472},
  {"id":"s_work_han_thu_7_473","chapterId":"ch_work_han_thu_7","textTraditional":"冬十二月，御史大夫兒寬卒。〔一〕","sentenceOrder":473},
  {"id":"s_work_han_thu_7_474","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「兒音五兮反。」","sentenceOrder":474},
  {"id":"s_work_han_thu_7_475","chapterId":"ch_work_han_thu_7","textTraditional":"三年春正月，行東巡海上。夏四月，還，修封泰山，禪石閭〔一〕。","sentenceOrder":475},
  {"id":"s_work_han_thu_7_476","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「石閭山在泰山下阯南方，方士言仙人閭也。」","sentenceOrder":476},
  {"id":"s_work_han_thu_7_477","chapterId":"ch_work_han_thu_7","textTraditional":"遣光祿勳徐自為築五原塞外列城，〔一〕西北至盧朐，〔二〕游擊將軍韓說將兵屯之。〔三〕強弩都尉路博德築居延。","sentenceOrder":477},
  {"id":"s_work_han_thu_7_478","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　晉灼曰：「地理志從五原棝陽縣北出石門鄣即得所築城。」師古曰：「棝音固。」","sentenceOrder":478},
  {"id":"s_work_han_thu_7_479","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　服虔曰：「匈奴地名。」張晏曰：「山名。」師古曰：「張說是也。朐音劬。」","sentenceOrder":479},
  {"id":"s_work_han_thu_7_480","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　師古曰：「說讀曰悅。」","sentenceOrder":480},
  {"id":"s_work_han_thu_7_481","chapterId":"ch_work_han_thu_7","textTraditional":"秋，匈奴入定襄、雲中，殺略數千人，行壞光祿諸亭障；〔一〕又入張掖、酒泉，殺都尉。","sentenceOrder":481},
  {"id":"s_work_han_thu_7_482","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「光祿勳徐自為所築列城，今匈奴從此往壞敗也。」師古曰：「漢制，每塞要處別築為城，置人鎮守，謂之候城，此即障也。音之向反。」","sentenceOrder":482},
  {"id":"s_work_han_thu_7_483","chapterId":"ch_work_han_thu_7","textTraditional":"四年春，貳師將軍廣利斬大宛王首，獲汗血馬來。〔一〕作西極天馬之歌。","sentenceOrder":483},
  {"id":"s_work_han_thu_7_484","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「大宛舊有天馬種，蹋石汗血。汗從前肩髆出，如血。號一日千里。」師古曰：「蹋石者，謂蹋石而有跡，言其蹄堅利。」","sentenceOrder":484},
  {"id":"s_work_han_thu_7_485","chapterId":"ch_work_han_thu_7","textTraditional":"秋，起明光宮。〔一〕","sentenceOrder":485},
  {"id":"s_work_han_thu_7_486","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「三輔黃圖云在城中。元后傳云成都侯商避暑借明光宮，蓋謂此。」","sentenceOrder":486},
  {"id":"s_work_han_thu_7_487","chapterId":"ch_work_han_thu_7","textTraditional":"冬，行幸回中。","sentenceOrder":487},
  {"id":"s_work_han_thu_7_488","chapterId":"ch_work_han_thu_7","textTraditional":"徙弘農都尉治武關，稅出入者以給關吏卒食。","sentenceOrder":488},
  {"id":"s_work_han_thu_7_489","chapterId":"ch_work_han_thu_7","textTraditional":"天漢元年〔一〕春正月，行幸甘泉，郊泰畤。三月，行幸河東，祠后土。","sentenceOrder":489},
  {"id":"s_work_han_thu_7_490","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「時頻年苦旱，故改元為天漢，以祈甘雨。」師古曰：「大雅有雲漢之詩，周（周）大夫仍叔所作也。以美宣王遇旱災修德勤政而能致雨，故依以為年號也。」","sentenceOrder":490},
  {"id":"s_work_han_thu_7_491","chapterId":"ch_work_han_thu_7","textTraditional":"匈奴歸漢使者，使使來獻。","sentenceOrder":491},
  {"id":"s_work_han_thu_7_492","chapterId":"ch_work_han_thu_7","textTraditional":"夏五月，赦天下。","sentenceOrder":492},
  {"id":"s_work_han_thu_7_493","chapterId":"ch_work_han_thu_7","textTraditional":"秋，閉城門大搜。〔一〕發謫戍屯五原。","sentenceOrder":493},
  {"id":"s_work_han_thu_7_494","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　臣瓚曰：「漢帝年記六月禁踰侈，七月閉城門大搜，則搜索踰侈者也。」李奇曰：「搜索巫蠱也。」師古曰：「時巫蠱未起，瓚說是也。踰侈者，踰法度而奢侈也。」","sentenceOrder":494},
  {"id":"s_work_han_thu_7_495","chapterId":"ch_work_han_thu_7","textTraditional":"二年春，行幸東海。還幸回中。","sentenceOrder":495},
  {"id":"s_work_han_thu_7_496","chapterId":"ch_work_han_thu_7","textTraditional":"夏五月，貳師將軍三萬騎出酒泉，與右賢王戰于天山，〔一〕斬首虜萬餘級。又遣因杅將軍出西河，騎都尉李陵將步兵五千人出居延北，與單于戰，斬首虜萬餘級。陵兵敗，降匈奴。","sentenceOrder":496},
  {"id":"s_work_han_thu_7_497","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　晉灼曰：「在西域，近蒲類國，去長安八千餘里。」師古曰：「即祁連山也。匈奴謂天為祁連。祁音巨夷反。今鮮卑語尚然。」","sentenceOrder":497},
  {"id":"s_work_han_thu_7_498","chapterId":"ch_work_han_thu_7","textTraditional":"秋，止禁巫祠道中者。〔一〕大搜。〔二〕","sentenceOrder":498},
  {"id":"s_work_han_thu_7_499","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　文穎曰：「始漢家於道中祠，排禍咎移之於行人百姓。以其不經，今止之也。」師古曰：「文說非也。祕祝移過，文帝久已除之。今此總禁百姓巫覡於道中祠祭者耳。」","sentenceOrder":499},
  {"id":"s_work_han_thu_7_500","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　臣瓚曰：「搜謂索姦人也。」晉灼曰：「搜巫蠱也。」師古曰：「瓚說是。」","sentenceOrder":500},
  {"id":"s_work_han_thu_7_501","chapterId":"ch_work_han_thu_7","textTraditional":"渠黎六國使使來獻。〔一〕","sentenceOrder":501},
  {"id":"s_work_han_thu_7_502","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　臣瓚曰：「渠黎，西域胡國名。」","sentenceOrder":502},
  {"id":"s_work_han_thu_7_503","chapterId":"ch_work_han_thu_7","textTraditional":"泰山、琅邪群盜徐〈勃，中“力改攵”〉等阻山攻城，〔一〕道路不通。遣直指使者暴勝之等衣繡衣杖斧分部逐捕。〔二〕刺史郡守以下皆伏誅。","sentenceOrder":503},
  {"id":"s_work_han_thu_7_504","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「阻山者，依山之險以自固也。」","sentenceOrder":504},
  {"id":"s_work_han_thu_7_505","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「杖斧，持斧也。謂建持之以為威也。分音扶問反。」","sentenceOrder":505},
  {"id":"s_work_han_thu_7_506","chapterId":"ch_work_han_thu_7","textTraditional":"冬十一月，詔關都尉曰：「今豪傑多遠交，依東方群盜。其謹察出入者。」","sentenceOrder":506},
  {"id":"s_work_han_thu_7_507","chapterId":"ch_work_han_thu_7","textTraditional":"三年春二月，御史大夫王卿有罪，自殺。","sentenceOrder":507},
  {"id":"s_work_han_thu_7_508","chapterId":"ch_work_han_thu_7","textTraditional":"初榷酒酤。〔一〕","sentenceOrder":508},
  {"id":"s_work_han_thu_7_509","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　如淳曰：「榷音較。」應劭曰：「縣官自酤榷賣酒，小民不復得酤也。」韋昭曰：「以木渡水曰榷。謂禁民酤釀，獨官開置，如道路設木為榷，獨取利也。」師古曰：「榷者，步渡橋，爾雅謂之石杠，今之略彴是也。禁閉其事，總利入官，而下無由以得，有若渡水之榷，因立名焉。韋說如音是也。酤音工護反。彴音酌。」","sentenceOrder":509},
  {"id":"s_work_han_thu_7_510","chapterId":"ch_work_han_thu_7","textTraditional":"三月，行幸泰山，修封，祀明堂，因受計。還幸北地，祠常山，瘞玄玉。〔一〕夏四月，赦天下。行所過毋出田租。","sentenceOrder":510},
  {"id":"s_work_han_thu_7_511","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　鄧展曰：「瘞，埋也。」師古曰：「爾雅曰『祭地曰瘞薶』。薶其物者，示歸于地也。瘞音於例反。」","sentenceOrder":511},
  {"id":"s_work_han_thu_7_512","chapterId":"ch_work_han_thu_7","textTraditional":"秋，匈奴入鴈門，太守坐畏愞棄市。〔一〕","sentenceOrder":512},
  {"id":"s_work_han_thu_7_513","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　如淳曰：「軍法，行逗留畏懦者要斬。愞音如掾反。」師古曰：「又音乃館反。」","sentenceOrder":513},
  {"id":"s_work_han_thu_7_514","chapterId":"ch_work_han_thu_7","textTraditional":"四年春正月，朝諸侯王于甘泉宮。發天下七科謫〔一〕及勇敢士，遣貳師將軍李廣利將六萬騎、步兵七萬人出朔方，因杅將軍公孫敖萬騎、步兵三萬人出鴈門，游擊將軍韓說〔二〕步兵三萬人出五原，強弩都尉路博德步兵萬餘人與貳師會。廣利與單于戰余吾水上連日，敖與左賢王戰不利，皆引還。","sentenceOrder":514},
  {"id":"s_work_han_thu_7_515","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　張晏曰：「吏有罪一，亡（人）〔命〕二，贅婿三，賈人四，故有市籍五，父母有市籍六，大父母有市籍七，凡七科也。」","sentenceOrder":515},
  {"id":"s_work_han_thu_7_516","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":516},
  {"id":"s_work_han_thu_7_517","chapterId":"ch_work_han_thu_7","textTraditional":"夏四月，立皇子髆為昌邑王。〔一〕","sentenceOrder":517},
  {"id":"s_work_han_thu_7_518","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　孟康曰：「髆音博。」晉灼曰：「許慎以為肩髆字。」","sentenceOrder":518},
  {"id":"s_work_han_thu_7_519","chapterId":"ch_work_han_thu_7","textTraditional":"秋九月，令死罪（人）〔入〕贖錢五十萬減死一等。","sentenceOrder":519},
  {"id":"s_work_han_thu_7_520","chapterId":"ch_work_han_thu_7","textTraditional":"太始元年〔一〕春正月，因杅將軍敖有罪，要斬。","sentenceOrder":520},
  {"id":"s_work_han_thu_7_521","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「言盪滌天下，與民更始，故以冠元。」","sentenceOrder":521},
  {"id":"s_work_han_thu_7_522","chapterId":"ch_work_han_thu_7","textTraditional":"徙郡國吏民豪桀于茂陵、雲陵。〔一〕","sentenceOrder":522},
  {"id":"s_work_han_thu_7_523","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「此當言雲陽，而轉寫者誤為陵耳。茂陵帝自所起，而雲陽甘泉所居，故總使徙豪桀也。鉤弋趙婕妤死，葬雲陽，至昭帝即位始尊為皇太后而起雲陵。武帝時未有雲陵。」","sentenceOrder":523},
  {"id":"s_work_han_thu_7_524","chapterId":"ch_work_han_thu_7","textTraditional":"夏六月，赦天下。","sentenceOrder":524},
  {"id":"s_work_han_thu_7_525","chapterId":"ch_work_han_thu_7","textTraditional":"二年春正月，行幸回中。","sentenceOrder":525},
  {"id":"s_work_han_thu_7_526","chapterId":"ch_work_han_thu_7","textTraditional":"三月，詔曰：「有司議曰，往者朕郊見上帝，西登隴首，獲白麟以饋宗廟，渥洼水出天馬，泰山見黃金，〔一〕宜改故名。今更黃金為麟趾褭蹄以協瑞焉。」〔二〕因以班賜諸侯王。","sentenceOrder":526},
  {"id":"s_work_han_thu_7_527","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「見音胡電反。」","sentenceOrder":527},
  {"id":"s_work_han_thu_7_528","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　應劭曰：「獲白麟，有馬瑞，故改鑄黃金如麟趾褭蹄以協嘉祉也。古有駿馬名要褭，赤喙黑身，一日行萬五千里也。」師古曰：「既云宜改故名，又曰更黃金為麟趾褭蹄，是則舊金雖以斤兩為名，而官有常形制，亦由今時吉字金挺之類矣。武帝欲表祥瑞，故普改鑄為麟足馬蹄之形以易舊法耳。今人往往於地中得馬蹄金，金甚精好，而形製巧妙。褭音奴了反。」","sentenceOrder":528},
  {"id":"s_work_han_thu_7_529","chapterId":"ch_work_han_thu_7","textTraditional":"秋，旱。九月，募死罪（人）〔入〕贖錢五十萬減死一等。","sentenceOrder":529},
  {"id":"s_work_han_thu_7_530","chapterId":"ch_work_han_thu_7","textTraditional":"御史大夫杜周卒。","sentenceOrder":530},
  {"id":"s_work_han_thu_7_531","chapterId":"ch_work_han_thu_7","textTraditional":"三年春正月，行幸甘泉宮，饗外國客。","sentenceOrder":531},
  {"id":"s_work_han_thu_7_532","chapterId":"ch_work_han_thu_7","textTraditional":"二月，令天下大酺五日。行幸東海，獲赤鴈，作朱鴈之歌。幸琅邪，禮日成山。〔一〕登之罘，〔二〕浮大海。山稱萬歲。冬，賜行所過戶五千錢，鰥寡孤獨帛人一匹。","sentenceOrder":532},
  {"id":"s_work_han_thu_7_533","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　孟康曰：「禮日，拜日也。」如淳曰：「祭日於成山也。」師古曰：「成山在東（來）〔萊〕不夜縣，斗入海。郊祀志作盛山，其音同。」","sentenceOrder":533},
  {"id":"s_work_han_thu_7_534","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　晉灼曰：「地理志東萊腄縣有之罘山祠。」師古曰：「罘音浮。腄音直瑞反。」","sentenceOrder":534},
  {"id":"s_work_han_thu_7_535","chapterId":"ch_work_han_thu_7","textTraditional":"四年春三月，行幸泰山。壬午，祀高祖于明堂，以配上帝，因受計。癸未，祀孝景皇帝于明堂。甲申，修封。丙戌，禪石閭。夏四月，幸不其，〔一〕祠神人于交門宮，〔二〕若有鄉坐拜者。〔三〕作交門之歌。夏五月，還幸建章宮，大置酒，赦天下。","sentenceOrder":535},
  {"id":"s_work_han_thu_7_536","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　如淳曰：「其音基。不其，山名，因以為縣。」應劭曰：「東萊縣也。」","sentenceOrder":536},
  {"id":"s_work_han_thu_7_537","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　應劭曰：「神人，蓬萊仙人之屬也。」晉灼曰：「琅邪縣有交門宮，武帝所造。」","sentenceOrder":537},
  {"id":"s_work_han_thu_7_538","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　師古曰：「如有神之景象嚮祠坐而拜也。漢注云神並見，且白且黑，且大且小，鄉坐三拜。鄉讀曰嚮。坐音才臥反。」","sentenceOrder":538},
  {"id":"s_work_han_thu_7_539","chapterId":"ch_work_han_thu_7","textTraditional":"秋七月，趙有蛇從郭外入邑，與邑中蛇群鬥孝文廟下，〔一〕邑中蛇死。","sentenceOrder":539},
  {"id":"s_work_han_thu_7_540","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　服虔曰：「趙所立孝文廟也。」","sentenceOrder":540},
  {"id":"s_work_han_thu_7_541","chapterId":"ch_work_han_thu_7","textTraditional":"冬十月甲寅晦，日有蝕之。","sentenceOrder":541},
  {"id":"s_work_han_thu_7_542","chapterId":"ch_work_han_thu_7","textTraditional":"十二月，行幸雍，祠五畤，西至安定、北地。","sentenceOrder":542},
  {"id":"s_work_han_thu_7_543","chapterId":"ch_work_han_thu_7","textTraditional":"征和元年〔一〕春正月，還，行幸建章宮。","sentenceOrder":543},
  {"id":"s_work_han_thu_7_544","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　應劭曰：「言征伐四夷而天下和平。」","sentenceOrder":544},
  {"id":"s_work_han_thu_7_545","chapterId":"ch_work_han_thu_7","textTraditional":"三月，趙王彭祖薨。","sentenceOrder":545},
  {"id":"s_work_han_thu_7_546","chapterId":"ch_work_han_thu_7","textTraditional":"冬十一月，發三輔騎士大搜上林，閉長安城門索，〔一〕十一日乃解。巫蠱起。","sentenceOrder":546},
  {"id":"s_work_han_thu_7_547","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　文穎曰：「簡車馬，數軍實也。」臣瓚曰：「搜謂索姦人也。上林苑周回數百里，故發三輔車騎入大搜索也。漢帝年記發三輔騎士大搜長安上林中，閉城門十五日，待詔北軍征官多餓死。然則皆搜索，非數軍實也。」師古曰：「文說非也。索音山客反。」","sentenceOrder":547},
  {"id":"s_work_han_thu_7_548","chapterId":"ch_work_han_thu_7","textTraditional":"二年春正月，丞相賀下獄死。","sentenceOrder":548},
  {"id":"s_work_han_thu_7_549","chapterId":"ch_work_han_thu_7","textTraditional":"夏四月，大風發屋折木。","sentenceOrder":549},
  {"id":"s_work_han_thu_7_550","chapterId":"ch_work_han_thu_7","textTraditional":"閏月，諸邑公主、陽石公主〔一〕皆坐巫蠱死。","sentenceOrder":550},
  {"id":"s_work_han_thu_7_551","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「諸邑，琅邪縣也，以封公主故謂之邑。陽石，北海縣也。（主）〔二〕公主皆衛皇后之女也。陽字或作羊。」","sentenceOrder":551},
  {"id":"s_work_han_thu_7_552","chapterId":"ch_work_han_thu_7","textTraditional":"夏，行幸甘泉。","sentenceOrder":552},
  {"id":"s_work_han_thu_7_553","chapterId":"ch_work_han_thu_7","textTraditional":"秋七月，（桉）〔按〕道侯韓說、〔一〕使者江充等掘蠱太子宮。壬午，太子與皇后謀斬充，以節發兵與丞相劉屈氂大戰長安，〔二〕死者數萬人。庚寅，太子亡，〔三〕皇后自殺。初置城門屯兵。更節加黃旄。〔四〕御史大夫暴勝之、司直田仁坐失縱，勝之自殺，仁要斬。八月辛亥，太子自殺于湖。〔五〕","sentenceOrder":553},
  {"id":"s_work_han_thu_7_554","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「即上游擊將軍韓說也。」","sentenceOrder":554},
  {"id":"s_work_han_thu_7_555","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「屈音丘勿反，又音其勿反。氂音力之反。」","sentenceOrder":555},
  {"id":"s_work_han_thu_7_556","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　師古曰：「謂逃匿也。」","sentenceOrder":556},
  {"id":"s_work_han_thu_7_557","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　應劭曰：「時太子亦發節以戰，故加其上黃以別之。」","sentenceOrder":557},
  {"id":"s_work_han_thu_7_558","chapterId":"ch_work_han_thu_7","textTraditional":"〔五〕　師古曰：「湖，縣名也，即今虢州閺鄉、湖城二縣皆其地。」","sentenceOrder":558},
  {"id":"s_work_han_thu_7_559","chapterId":"ch_work_han_thu_7","textTraditional":"癸亥，地震。","sentenceOrder":559},
  {"id":"s_work_han_thu_7_560","chapterId":"ch_work_han_thu_7","textTraditional":"九月，立趙敬肅王子偃為平〔干〕王。","sentenceOrder":560},
  {"id":"s_work_han_thu_7_561","chapterId":"ch_work_han_thu_7","textTraditional":"匈奴入上谷、五原，殺略吏民。","sentenceOrder":561},
  {"id":"s_work_han_thu_7_562","chapterId":"ch_work_han_thu_7","textTraditional":"三年春正月，行幸雍，至安定、北地。匈奴入五原、酒泉，殺兩都尉。三月，遣貳師將軍廣利將七萬人出五原，御史大夫商丘成二萬人出西河，重合侯馬通四萬騎出酒泉。成至浚稽山〔一〕與虜戰，多斬首。通至天山，虜引去，因降車師。皆引兵還。廣利敗，降匈奴。","sentenceOrder":562},
  {"id":"s_work_han_thu_7_563","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「音峻雞。」","sentenceOrder":563},
  {"id":"s_work_han_thu_7_564","chapterId":"ch_work_han_thu_7","textTraditional":"夏五月，赦天下。","sentenceOrder":564},
  {"id":"s_work_han_thu_7_565","chapterId":"ch_work_han_thu_7","textTraditional":"六月，丞相屈氂下獄要斬，妻（子）梟首。〔一〕","sentenceOrder":565},
  {"id":"s_work_han_thu_7_566","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　鄭氏曰：「妻作巫蠱，夫從坐，但要斬也。」師古曰：「屈氂亦坐與貳師將軍謀立昌邑王。」","sentenceOrder":566},
  {"id":"s_work_han_thu_7_567","chapterId":"ch_work_han_thu_7","textTraditional":"秋，蝗。","sentenceOrder":567},
  {"id":"s_work_han_thu_7_568","chapterId":"ch_work_han_thu_7","textTraditional":"九月，反者公孫勇、胡倩發覺，皆伏辜。〔一〕","sentenceOrder":568},
  {"id":"s_work_han_thu_7_569","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「倩音千見反。」","sentenceOrder":569},
  {"id":"s_work_han_thu_7_570","chapterId":"ch_work_han_thu_7","textTraditional":"四年春正月，行幸東萊，臨大海。","sentenceOrder":570},
  {"id":"s_work_han_thu_7_571","chapterId":"ch_work_han_thu_7","textTraditional":"二月丁酉，隕石于雍，二，〔一〕聲聞四百里。","sentenceOrder":571},
  {"id":"s_work_han_thu_7_572","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「雍，扶風之縣也。二者，石之數。」","sentenceOrder":572},
  {"id":"s_work_han_thu_7_573","chapterId":"ch_work_han_thu_7","textTraditional":"三月，上耕于鉅定。〔一〕還幸泰山，修封。庚寅，祀于明堂。癸巳，襢石閭。夏六月，還幸甘泉。","sentenceOrder":573},
  {"id":"s_work_han_thu_7_574","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　服虔曰：「地名也，近東海。」應劭曰：「齊國縣也。」晉灼曰：「案地理志，應說是。」","sentenceOrder":574},
  {"id":"s_work_han_thu_7_575","chapterId":"ch_work_han_thu_7","textTraditional":"秋八月辛酉晦，日有蝕之。","sentenceOrder":575},
  {"id":"s_work_han_thu_7_576","chapterId":"ch_work_han_thu_7","textTraditional":"後元元年春正月，行幸甘泉，郊泰畤，遂幸安定。","sentenceOrder":576},
  {"id":"s_work_han_thu_7_577","chapterId":"ch_work_han_thu_7","textTraditional":"昌邑王髆薨。","sentenceOrder":577},
  {"id":"s_work_han_thu_7_578","chapterId":"ch_work_han_thu_7","textTraditional":"二月，詔曰：「朕郊見上帝，〔一〕巡于北邊，見群鶴留止，以不羅罔，靡所獲獻。〔二〕薦于泰畤，光景並見。其赦天下。」","sentenceOrder":578},
  {"id":"s_work_han_thu_7_579","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「見音胡電反。次下光景並見亦同。」","sentenceOrder":579},
  {"id":"s_work_han_thu_7_580","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　如淳曰：「時春也，非用羅罔時，故無所獲也。」","sentenceOrder":580},
  {"id":"s_work_han_thu_7_581","chapterId":"ch_work_han_thu_7","textTraditional":"夏六月，御史大夫商丘成有罪自殺。〔一〕侍中僕射莽何羅與弟重合侯通謀反，〔二〕侍中駙馬都尉金日磾、奉車都尉霍光、騎都尉上官桀討之。〔三〕","sentenceOrder":581},
  {"id":"s_work_han_thu_7_582","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「坐於廟中醉而歌。」","sentenceOrder":582},
  {"id":"s_work_han_thu_7_583","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　孟康曰：「征和三年言重合侯馬通，今此言莽，明德馬后惡其先人有反，易姓莽。」師古曰：「莽音莫戶反。」","sentenceOrder":583},
  {"id":"s_work_han_thu_7_584","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　師古曰：「磾音丁奚反。」","sentenceOrder":584},
  {"id":"s_work_han_thu_7_585","chapterId":"ch_work_han_thu_7","textTraditional":"秋七月，地震，往往湧泉出。","sentenceOrder":585},
  {"id":"s_work_han_thu_7_586","chapterId":"ch_work_han_thu_7","textTraditional":"二年春正月，朝諸侯王于甘泉宮，賜宗室。","sentenceOrder":586},
  {"id":"s_work_han_thu_7_587","chapterId":"ch_work_han_thu_7","textTraditional":"二月，行幸盩厔五柞宮。〔一〕乙丑，立皇子弗陵為皇太子〔二〕。丁卯，帝崩于五柞宮，〔三〕入殯于未央宮前殿。三月甲申，葬茂陵。〔四〕","sentenceOrder":587},
  {"id":"s_work_han_thu_7_588","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　晉灼曰：「盩厔，扶風縣也。」張晏曰：「有五柞樹，因以名宮也。」師古曰：「盩音張流反。厔音竹乙反。」","sentenceOrder":588},
  {"id":"s_work_han_thu_7_589","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　張晏曰：「昭帝也。後但名弗，以二名難諱故。」","sentenceOrder":589},
  {"id":"s_work_han_thu_7_590","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　臣瓚曰：「帝年十七即位，即位五十四年，壽七十一。」","sentenceOrder":590},
  {"id":"s_work_han_thu_7_591","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　臣瓚曰：「自崩至葬凡十八日。茂陵在長安西北八十里也。」","sentenceOrder":591},
  {"id":"s_work_han_thu_7_592","chapterId":"ch_work_han_thu_7","textTraditional":"贊曰：漢承百王之弊，高祖撥亂反正，文景務在養民，至于稽古禮文之事，猶多闕焉。孝武初立，卓然罷黜百家，〔一〕表章六經。〔二〕遂疇咨海內，舉其俊茂，〔三〕與之立功。興太學，修郊祀，改正朔，定曆數，〔四〕協音律，作詩樂，建封禪，禮百神，紹周後，號令文章，煥焉可述。後嗣得遵洪業，而有三代之風。〔五〕如武帝之雄材大略，不改文景之恭儉以濟斯民，雖詩書所稱何有加焉〔六〕！","sentenceOrder":592},
  {"id":"s_work_han_thu_7_593","chapterId":"ch_work_han_thu_7","textTraditional":"〔一〕　師古曰：「百家，謂諸子雜說，違背六經。」","sentenceOrder":593},
  {"id":"s_work_han_thu_7_594","chapterId":"ch_work_han_thu_7","textTraditional":"〔二〕　師古曰：「六經，謂易、詩、書、春秋、禮、樂也。」","sentenceOrder":594},
  {"id":"s_work_han_thu_7_595","chapterId":"ch_work_han_thu_7","textTraditional":"〔三〕　師古曰：「疇，誰也。咨，謀也。言謀於眾人，誰可為事者也。」","sentenceOrder":595},
  {"id":"s_work_han_thu_7_596","chapterId":"ch_work_han_thu_7","textTraditional":"〔四〕　師古曰：「正音之成反。他皆類此。」","sentenceOrder":596},
  {"id":"s_work_han_thu_7_597","chapterId":"ch_work_han_thu_7","textTraditional":"〔五〕　師古曰：「三代，夏、殷、周。」","sentenceOrder":597},
  {"id":"s_work_han_thu_7_598","chapterId":"ch_work_han_thu_7","textTraditional":"〔六〕　師古曰：「美其雄材大略，而非其不恭儉也。」","sentenceOrder":598},
  {"id":"s_work_han_thu_7_599","chapterId":"ch_work_han_thu_7","textTraditional":"校勘記","sentenceOrder":599},
  {"id":"s_work_han_thu_7_600","chapterId":"ch_work_han_thu_7","textTraditional":"一五七頁　一行　遂，（中）〔申〕也。　景祐、汲古、殿、局本都作「申」。王先謙說作「申」是。","sentenceOrder":600},
  {"id":"s_work_han_thu_7_601","chapterId":"ch_work_han_thu_7","textTraditional":"一五八頁　四行　本槐里（之縣）〔縣之〕茂鄉，　景祐、殿本都作「縣之」。王先謙說作「縣之」是。","sentenceOrder":601},
  {"id":"s_work_han_thu_7_602","chapterId":"ch_work_han_thu_7","textTraditional":"一六三頁　一行　（大）〔太〕中大夫李息　景祐、汲古、殿、局本都作「太」。","sentenceOrder":602},
  {"id":"s_work_han_thu_7_603","chapterId":"ch_work_han_thu_7","textTraditional":"一六五頁一二行　復奉正（議）〔義〕，　景祐、殿本都作「義」。王先謙說作「義」是。","sentenceOrder":603},
  {"id":"s_work_han_thu_7_604","chapterId":"ch_work_han_thu_7","textTraditional":"一六八頁　三行　總〔一〕郡之中，　景祐、汲古、殿、局本都有「一」字。王先謙說有「一」字是。","sentenceOrder":604},
  {"id":"s_work_han_thu_7_605","chapterId":"ch_work_han_thu_7","textTraditional":"一六八頁　四行　不得聞（雍）〔達〕於天子也。　景祐、汲古、殿、局本都作「達」。王先謙說作「達」是。","sentenceOrder":605},
  {"id":"s_work_han_thu_7_606","chapterId":"ch_work_han_thu_7","textTraditional":"一七八頁　五行　施於（吏）〔利〕重者，　景祐、殿、局本都作「利」。王先謙說作「利」是。","sentenceOrder":606},
  {"id":"s_work_han_thu_7_607","chapterId":"ch_work_han_thu_7","textTraditional":"一七八頁一一行　兩軍士（戰）死者數萬人。　景祐本無「戰」字。王念孫說「戰」字後人所加，云死者數萬人則戰死可知。","sentenceOrder":607},
  {"id":"s_work_han_thu_7_608","chapterId":"ch_work_han_thu_7","textTraditional":"一八０頁　三行　又禁（以）〔兼〕并之塗，　景祐、汲古、殿、局本都作「兼」。","sentenceOrder":608},
  {"id":"s_work_han_thu_7_609","chapterId":"ch_work_han_thu_7","textTraditional":"一八四頁　三行　廣（一）〔二〕里餘，　景祐、殿、局本都作「二」。","sentenceOrder":609},
  {"id":"s_work_han_thu_7_610","chapterId":"ch_work_han_thu_7","textTraditional":"一八四頁一０行　十三年（此）〔封〕于觀為衛公。　景祐、殿、局本都作「封」。王先謙說作「封」是。","sentenceOrder":610},
  {"id":"s_work_han_thu_7_611","chapterId":"ch_work_han_thu_7","textTraditional":"一八四頁一五行　見群野馬中有奇（異）者，與凡馬〔異〕，　景祐本如此，與汲古、殿、局本都不同。","sentenceOrder":611},
  {"id":"s_work_han_thu_7_612","chapterId":"ch_work_han_thu_7","textTraditional":"一八五頁　九行　獲（祭）〔薦〕於廟。　景祐、殿本都作「薦」。王先謙說作「薦」是。","sentenceOrder":612},
  {"id":"s_work_han_thu_7_613","chapterId":"ch_work_han_thu_7","textTraditional":"一八七頁一０行　音潘（禺）〔愚〕，　殿、局本都作「愚」。王先謙說作「愚」是。","sentenceOrder":613},
  {"id":"s_work_han_thu_7_614","chapterId":"ch_work_han_thu_7","textTraditional":"一八八頁　四行　郎中令（一）〔徐〕自為　景祐、殿、局本都作「徐」。王先謙說作「徐」是。","sentenceOrder":614},
  {"id":"s_work_han_thu_7_615","chapterId":"ch_work_han_thu_7","textTraditional":"一九一頁一六行　（比）〔此〕古制也。　景祐、殿本都作「此」。王先謙說作「此」是。","sentenceOrder":615},
  {"id":"s_work_han_thu_7_616","chapterId":"ch_work_han_thu_7","textTraditional":"一九四頁　五行　三百里內皆（來）觀。　景祐本無「來」字。王念孫說後人所加。","sentenceOrder":616},
  {"id":"s_work_han_thu_7_617","chapterId":"ch_work_han_thu_7","textTraditional":"一九六頁　九行　案地（里）〔理〕志不得，　景祐、殿本都作「理」。","sentenceOrder":617},
  {"id":"s_work_han_thu_7_618","chapterId":"ch_work_han_thu_7","textTraditional":"一九七頁一四行　漢（書）〔舊〕儀云　景祐、殿本都作「舊」。王先謙說作「舊」是。","sentenceOrder":618},
  {"id":"s_work_han_thu_7_619","chapterId":"ch_work_han_thu_7","textTraditional":"一九八頁　二行　音（力）〔方〕勇反。　景祐、汲古、殿、局本都作「方」。","sentenceOrder":619},
  {"id":"s_work_han_thu_7_620","chapterId":"ch_work_han_thu_7","textTraditional":"一九八頁　三行　跅（拓也）〔音拓〕。　景祐、殿本都作「音拓」。王先謙說作「音拓」是。","sentenceOrder":620},
  {"id":"s_work_han_thu_7_621","chapterId":"ch_work_han_thu_7","textTraditional":"二００頁一三行　亦以此日出（臘）〔獵〕，　殿、局本都作「獵」。王先謙說作「獵」是。","sentenceOrder":621},
  {"id":"s_work_han_thu_7_622","chapterId":"ch_work_han_thu_7","textTraditional":"二０一頁　五行　匈奴常（取）〔所〕以為障蔽。　景祐、汲古、殿、局本都作「所」。王先謙說作「所」是。","sentenceOrder":622},
  {"id":"s_work_han_thu_7_623","chapterId":"ch_work_han_thu_7","textTraditional":"二０二頁一一行　周（周）大夫仍叔所作也。　景祐、殿本都無下「周」字，此衍。","sentenceOrder":623},
  {"id":"s_work_han_thu_7_624","chapterId":"ch_work_han_thu_7","textTraditional":"二０五頁　五行　亡（人）〔命〕二，　景祐、汲古、殿、局本都作「命」。","sentenceOrder":624},
  {"id":"s_work_han_thu_7_625","chapterId":"ch_work_han_thu_7","textTraditional":"二０五頁　九行　令死罪（人）〔入〕贖錢　景祐、殿本都作「入」。","sentenceOrder":625},
  {"id":"s_work_han_thu_7_626","chapterId":"ch_work_han_thu_7","textTraditional":"二０六頁一一行　募死罪（人）〔入〕贖錢　景祐本作「入」。","sentenceOrder":626},
  {"id":"s_work_han_thu_7_627","chapterId":"ch_work_han_thu_7","textTraditional":"二０七頁　二行　成山在東（來）〔萊〕不夜縣，　景祐、汲古、殿、局本都作「萊」。王先謙說作「萊」是。","sentenceOrder":627},
  {"id":"s_work_han_thu_7_628","chapterId":"ch_work_han_thu_7","textTraditional":"二０八頁一一行　（主）〔二〕公主皆衛皇后之女也。　景祐、殿本都作「二」。王先謙說作「二」是。","sentenceOrder":628},
  {"id":"s_work_han_thu_7_629","chapterId":"ch_work_han_thu_7","textTraditional":"二０八頁一三行　（桉）〔按〕道侯韓說　景祐、殿本都作「按」。王先謙說作「按」是。","sentenceOrder":629},
  {"id":"s_work_han_thu_7_630","chapterId":"ch_work_han_thu_7","textTraditional":"二０九頁一０行　偃為平〔干〕王。　景祐、殿、局本都有「干」字。","sentenceOrder":630},
  {"id":"s_work_han_thu_7_631","chapterId":"ch_work_han_thu_7","textTraditional":"二一０頁　三行　妻（子）梟首。　景祐本無「子」字。王念孫說「子」字乃後人依屈氂傳加之也。","sentenceOrder":631},
  {"id":"s_work_han_thu_8_1","chapterId":"ch_work_han_thu_8","textTraditional":"孝昭皇帝，〔一〕武帝少子也。母曰趙婕妤，〔二〕本以有奇異得幸，〔三〕及生帝，亦奇異。〔四〕語在外戚傳。武帝末，戾太子敗，燕王旦、廣陵王胥行驕嫚，〔五〕後元二年二月上疾病，〔六〕遂立昭帝為太子，年八歲。以侍中奉車都尉霍光為大司馬大將軍，受遺詔輔少主。明日，武帝崩。戊辰，太子即皇帝位，謁高廟。帝姊鄂邑公主〔七〕益湯沐邑，為長公主，〔八〕共養省中。〔九〕大將軍光秉政，領尚書事，車騎將軍金日磾、左將軍上官桀副焉。","sentenceOrder":1},
  {"id":"s_work_han_thu_8_2","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　荀悅曰：「諱弗之字曰不。」應劭曰：「禮諡法『聖聞周達曰昭』。」","sentenceOrder":2},
  {"id":"s_work_han_thu_8_3","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　師古曰：「婕，接幸也。妤，美稱也。故以名宮中婦官。婕音接。妤音余。字或並從女。」","sentenceOrder":3},
  {"id":"s_work_han_thu_8_4","chapterId":"ch_work_han_thu_8","textTraditional":"〔三〕　師古曰：「謂望氣者言有奇女天子氣。及召見，手指拳，上自披之，即時伸。」","sentenceOrder":4},
  {"id":"s_work_han_thu_8_5","chapterId":"ch_work_han_thu_8","textTraditional":"〔四〕　文穎曰：「十四月乃生。」","sentenceOrder":5},
  {"id":"s_work_han_thu_8_6","chapterId":"ch_work_han_thu_8","textTraditional":"〔五〕　師古曰：「行音下更反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_8_7","chapterId":"ch_work_han_thu_8","textTraditional":"〔六〕　師古曰：「疾甚曰病。」","sentenceOrder":7},
  {"id":"s_work_han_thu_8_8","chapterId":"ch_work_han_thu_8","textTraditional":"〔七〕　應劭曰：「鄂，縣名，屬江夏。公主所食曰邑。」師古曰：「鄂音五各反。」","sentenceOrder":8},
  {"id":"s_work_han_thu_8_9","chapterId":"ch_work_han_thu_8","textTraditional":"〔八〕　師古曰：「帝之姊妹則稱長公主，儀比諸王，又以供養天子，故益邑也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_8_10","chapterId":"ch_work_han_thu_8","textTraditional":"〔九〕　伏儼曰：「蔡邕云本為禁中，門閤有禁，非侍御之臣不得妄入。行道豹尾中亦為禁中。孝元皇后父名禁，避之，故曰省中。」師古曰：「省，察也，言入此中皆當察視，不可妄也。共讀曰供，音居用反。養音弋亮反。他皆類此。」","sentenceOrder":10},
  {"id":"s_work_han_thu_8_11","chapterId":"ch_work_han_thu_8","textTraditional":"夏六月，赦天下。","sentenceOrder":11},
  {"id":"s_work_han_thu_8_12","chapterId":"ch_work_han_thu_8","textTraditional":"秋七月，有星孛于東方。","sentenceOrder":12},
  {"id":"s_work_han_thu_8_13","chapterId":"ch_work_han_thu_8","textTraditional":"濟北王寬有罪，自殺。","sentenceOrder":13},
  {"id":"s_work_han_thu_8_14","chapterId":"ch_work_han_thu_8","textTraditional":"賜長公主及宗室昆弟各有差。追尊趙婕妤為皇太后，起雲陵〔一〕。","sentenceOrder":14},
  {"id":"s_work_han_thu_8_15","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　文穎曰：「婕妤先葬於雲陽，是以就雲陽為起雲陵。」","sentenceOrder":15},
  {"id":"s_work_han_thu_8_16","chapterId":"ch_work_han_thu_8","textTraditional":"冬，匈奴入朔方，殺略吏民。發軍屯西河，左將軍桀行北邊〔一〕。","sentenceOrder":16},
  {"id":"s_work_han_thu_8_17","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「行音下更反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_8_18","chapterId":"ch_work_han_thu_8","textTraditional":"始元元年春二月，黃鵠下建章宮太液池中。〔一〕公卿上壽。賜諸侯王、列侯、宗室金錢各有差。","sentenceOrder":18},
  {"id":"s_work_han_thu_8_19","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　如淳曰：「謂之液者，言天地和液之氣所為也。」臣瓚曰：「時漢用土德，服色尚黃，鵠色皆白，而今更黃，以為（上）〔土〕德之瑞，故紀之也。太液池，言承陰陽津液以作池也。」師古曰：「如、瓚之說皆非也。黃鵠，大鳥也，一舉千里者，非白鵠也。太液池者，言其津潤所及廣也。鵠音胡篤反。」","sentenceOrder":19},
  {"id":"s_work_han_thu_8_20","chapterId":"ch_work_han_thu_8","textTraditional":"己亥，上耕于鉤盾弄田。〔一〕","sentenceOrder":20},
  {"id":"s_work_han_thu_8_21","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　應劭曰：「時帝年九歲，未能親耕帝籍，鉤盾，宦者近署，故往試耕為戲弄也。」臣瓚曰：「西京故事弄田在未央宮中。」師古曰：「弄田為宴游之田，天子所戲弄耳，非為昭帝年幼創有此名。」","sentenceOrder":21},
  {"id":"s_work_han_thu_8_22","chapterId":"ch_work_han_thu_8","textTraditional":"益封燕王、廣陵王及鄂邑長公主各萬三千戶。","sentenceOrder":22},
  {"id":"s_work_han_thu_8_23","chapterId":"ch_work_han_thu_8","textTraditional":"夏，為太后起園廟雲陵。","sentenceOrder":23},
  {"id":"s_work_han_thu_8_24","chapterId":"ch_work_han_thu_8","textTraditional":"益州廉頭、姑繒、牂柯談指、同並二十四邑皆反。〔一〕遣水衡都尉呂破胡募吏民及發犍為、蜀郡奔命擊益州，大破之。〔二〕","sentenceOrder":24},
  {"id":"s_work_han_thu_8_25","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　蘇林曰：「皆西南夷別種名也。」師古曰：「並音伴。」","sentenceOrder":25},
  {"id":"s_work_han_thu_8_26","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　應劭曰：「舊時郡國皆有材官騎士以赴急難，今夷反，常兵不足以討之，故權選取精勇。聞命奔走，故謂之奔命。」李斐曰：「平居發者二十以上至五十為甲卒，今者五十以上六十以下為奔命。奔命，言急也。」師古曰：「應說是也。犇，古奔字耳。犍音虔，又音鉅言反。」","sentenceOrder":26},
  {"id":"s_work_han_thu_8_27","chapterId":"ch_work_han_thu_8","textTraditional":"有司請河內屬冀州，河東屬并州。〔一〕","sentenceOrder":27},
  {"id":"s_work_han_thu_8_28","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　文穎曰：「本屬司州。」師古曰：「蓋屬京師司隸所部。」","sentenceOrder":28},
  {"id":"s_work_han_thu_8_29","chapterId":"ch_work_han_thu_8","textTraditional":"秋七月，赦天下，賜民百戶牛酒。大雨，渭橋絕。","sentenceOrder":29},
  {"id":"s_work_han_thu_8_30","chapterId":"ch_work_han_thu_8","textTraditional":"八月，齊孝王孫劉澤謀反，欲殺青州刺史雋不疑，〔一〕發覺，皆伏誅。遷不疑為京兆尹，賜錢百萬。","sentenceOrder":30},
  {"id":"s_work_han_thu_8_31","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「雋音材兗反，又音辭兗反。」","sentenceOrder":31},
  {"id":"s_work_han_thu_8_32","chapterId":"ch_work_han_thu_8","textTraditional":"九月丙子，車騎將軍日磾薨。","sentenceOrder":32},
  {"id":"s_work_han_thu_8_33","chapterId":"ch_work_han_thu_8","textTraditional":"閏月，遣故廷尉王平等五人〔一〕持節行郡國，〔二〕舉賢良，問民所疾苦、冤、失職者。","sentenceOrder":33},
  {"id":"s_work_han_thu_8_34","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「前為此官今不居者，皆謂之故也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_8_35","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　師古曰：「行音下更反。」","sentenceOrder":35},
  {"id":"s_work_han_thu_8_36","chapterId":"ch_work_han_thu_8","textTraditional":"冬，無冰。","sentenceOrder":36},
  {"id":"s_work_han_thu_8_37","chapterId":"ch_work_han_thu_8","textTraditional":"二年春正月，大將軍光、左將軍桀皆以前捕斬反虜重合侯馬通功封，光為博陸侯，桀為安陽侯。","sentenceOrder":37},
  {"id":"s_work_han_thu_8_38","chapterId":"ch_work_han_thu_8","textTraditional":"以宗室毋在位者，舉茂才劉辟彊、劉長樂皆為光祿大夫，辟彊守長樂衛尉。〔一〕","sentenceOrder":38},
  {"id":"s_work_han_thu_8_39","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「長樂宮之衛尉也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_8_40","chapterId":"ch_work_han_thu_8","textTraditional":"三月，遣使者振貸貧民毋種、食者。〔一〕秋八月，詔曰：「往年災害多，今年蠶麥傷，所振貸種、食勿收責，毋令民出今年田租。」","sentenceOrder":40},
  {"id":"s_work_han_thu_8_41","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕師古曰：「貸音吐戴反。其下並同。」","sentenceOrder":41},
  {"id":"s_work_han_thu_8_42","chapterId":"ch_work_han_thu_8","textTraditional":"冬，發習戰射士詣朔方，調故吏將屯田張掖郡。〔一〕","sentenceOrder":42},
  {"id":"s_work_han_thu_8_43","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「調謂發選也。故吏，前為官職者。令其部率習戰射士於張掖為屯田也。調音徒釣反。將音子亮反。」","sentenceOrder":43},
  {"id":"s_work_han_thu_8_44","chapterId":"ch_work_han_thu_8","textTraditional":"三年春二月，有星孛于西北。","sentenceOrder":44},
  {"id":"s_work_han_thu_8_45","chapterId":"ch_work_han_thu_8","textTraditional":"秋，募民徙雲陵，賜錢田宅。","sentenceOrder":45},
  {"id":"s_work_han_thu_8_46","chapterId":"ch_work_han_thu_8","textTraditional":"冬十月，鳳皇集東海，遣使者祠其處。","sentenceOrder":46},
  {"id":"s_work_han_thu_8_47","chapterId":"ch_work_han_thu_8","textTraditional":"十一月壬辰朔，日有蝕之。","sentenceOrder":47},
  {"id":"s_work_han_thu_8_48","chapterId":"ch_work_han_thu_8","textTraditional":"四年春三月甲寅，立皇后上官氏。〔一〕赦天下。辭訟在後二年前，皆勿聽治。〔二〕夏六月，皇后見高廟。賜長公主、丞相、將軍、列侯、中二千石以下及郎吏宗室錢帛各有差。","sentenceOrder":48},
  {"id":"s_work_han_thu_8_49","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　文穎曰：「上官桀孫，安之女。」","sentenceOrder":49},
  {"id":"s_work_han_thu_8_50","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　孟康曰：「武帝後二年。」","sentenceOrder":50},
  {"id":"s_work_han_thu_8_51","chapterId":"ch_work_han_thu_8","textTraditional":"徙三輔富人雲陵，賜錢，戶十萬。","sentenceOrder":51},
  {"id":"s_work_han_thu_8_52","chapterId":"ch_work_han_thu_8","textTraditional":"秋七月，詔曰：「比歲不登，民匱於食，〔一〕流庸未盡還〔二〕，往時令民共出馬，其止勿出。諸給中都官者，且減之。」〔三〕","sentenceOrder":52},
  {"id":"s_work_han_thu_8_53","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「匱，空也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_8_54","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　師古曰：「流庸，謂去其本鄉而行為人庸作。」","sentenceOrder":54},
  {"id":"s_work_han_thu_8_55","chapterId":"ch_work_han_thu_8","textTraditional":"〔三〕　師古曰：「中都官，京師諸官府。」","sentenceOrder":55},
  {"id":"s_work_han_thu_8_56","chapterId":"ch_work_han_thu_8","textTraditional":"冬，遣大鴻臚田廣明擊益州。","sentenceOrder":56},
  {"id":"s_work_han_thu_8_57","chapterId":"ch_work_han_thu_8","textTraditional":"廷尉李种坐故縱死罪棄市。〔一〕","sentenceOrder":57},
  {"id":"s_work_han_thu_8_58","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「縱謂容放之。种音沖。」","sentenceOrder":58},
  {"id":"s_work_han_thu_8_59","chapterId":"ch_work_han_thu_8","textTraditional":"五年春正月，追尊皇太后父為順成侯。","sentenceOrder":59},
  {"id":"s_work_han_thu_8_60","chapterId":"ch_work_han_thu_8","textTraditional":"夏陽男子張延年〔一〕詣北闕，自稱衛太子，誣罔，要斬。","sentenceOrder":60},
  {"id":"s_work_han_thu_8_61","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「夏陽，馮翊之縣。」","sentenceOrder":61},
  {"id":"s_work_han_thu_8_62","chapterId":"ch_work_han_thu_8","textTraditional":"夏，罷天下亭母馬及馬弩關。〔一〕","sentenceOrder":62},
  {"id":"s_work_han_thu_8_63","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　應劭曰：「武帝數伐匈奴，再擊大宛，馬死略盡，乃令天下諸亭養母馬，欲令其繁孳，又作馬上弩機關，今悉罷之。」孟康曰：「舊馬高五尺六寸齒未平，弩十石以上，皆不得出關，今不禁也。」師古曰：「亭母馬，應說也；馬弩關，孟說是也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_8_64","chapterId":"ch_work_han_thu_8","textTraditional":"六月，封皇后父驃騎將軍上官安為桑樂侯。〔一〕","sentenceOrder":64},
  {"id":"s_work_han_thu_8_65","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「樂音來各反。」","sentenceOrder":65},
  {"id":"s_work_han_thu_8_66","chapterId":"ch_work_han_thu_8","textTraditional":"詔曰：「朕以眇身獲保宗廟，〔一〕戰戰栗栗，夙興夜寐，修古帝王之事，通保傅，傳孝經、論語、尚書，未云有明。〔二〕其令三輔、太常舉賢良各二人，郡國文學高第各一人。賜中二千石以下至吏民爵各有差。」","sentenceOrder":66},
  {"id":"s_work_han_thu_8_67","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「眇，微也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_8_68","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　文穎曰：「賈誼作保傅傳，在禮大戴記。言能通讀之也。」晉灼曰：「帝自謂通保傅傳，未能有所明也。」臣瓚曰：「帝自謂雖通舉此四書，皆未能有所明，此帝之謙也。」師古曰：「晉、瓚之說皆非也。帝自言雖通保傅傳，而孝經、論語、尚書猶未能明也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_8_69","chapterId":"ch_work_han_thu_8","textTraditional":"罷儋耳、真番郡。〔一〕","sentenceOrder":69},
  {"id":"s_work_han_thu_8_70","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「儋耳本南越地，真番本朝鮮地，皆武帝所置也。番音普安反。」","sentenceOrder":70},
  {"id":"s_work_han_thu_8_71","chapterId":"ch_work_han_thu_8","textTraditional":"秋，大鴻臚廣明、軍正王平擊益州，〔一〕斬首捕虜三萬餘人，獲畜產五萬餘頭。","sentenceOrder":71},
  {"id":"s_work_han_thu_8_72","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「廣明，田廣明。」","sentenceOrder":72},
  {"id":"s_work_han_thu_8_73","chapterId":"ch_work_han_thu_8","textTraditional":"六月春正月，上耕于上林。","sentenceOrder":73},
  {"id":"s_work_han_thu_8_74","chapterId":"ch_work_han_thu_8","textTraditional":"二月，詔有司問郡國所舉賢良文學民所疾苦。議罷鹽鐵榷酤〔一〕。","sentenceOrder":74},
  {"id":"s_work_han_thu_8_75","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　應劭曰：「武帝時，以國用不足，縣官悉自賣鹽鐵，酤酒。昭帝務本抑末，不與天下爭利，故罷之。」","sentenceOrder":75},
  {"id":"s_work_han_thu_8_76","chapterId":"ch_work_han_thu_8","textTraditional":"栘中監蘇武〔一〕前使匈奴，留單于庭十九歲乃還，奉使全節，以武為典屬國，〔二〕賜錢百萬。","sentenceOrder":76},
  {"id":"s_work_han_thu_8_77","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　蘇林曰：「栘音移，廄名也。」應劭曰：「栘，地名。監，其官也，掌鞍馬鷹犬射獵之具。」如淳曰：「栘，爾雅『唐棣，栘也』。栘園之中有馬廄也。」師古曰：「蘇音如說是。」","sentenceOrder":77},
  {"id":"s_work_han_thu_8_78","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　如淳曰：「以其久在外國，知邊事，故令典主諸屬國。」師古曰：「典屬國，本秦官，漢因之，掌歸義蠻夷，屬官有九譯令。後省，并大鴻臚。」","sentenceOrder":78},
  {"id":"s_work_han_thu_8_79","chapterId":"ch_work_han_thu_8","textTraditional":"夏，旱，大雩，大得舉火。〔一〕","sentenceOrder":79},
  {"id":"s_work_han_thu_8_80","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　臣瓚曰：「不得舉火，抑陽助陰也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_8_81","chapterId":"ch_work_han_thu_8","textTraditional":"秋七月，罷榷酤官，令民得以律占租，〔一〕賣酒升四錢。以邊塞闊遠，取天水、隴西、張掖郡各二縣置金城郡。","sentenceOrder":81},
  {"id":"s_work_han_thu_8_82","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　如淳曰：「律，諸當占租者家長身各以其物占，占不以實，家長不身自書，皆罰金二斤，沒入所不自占物及賈錢縣官也。」師古曰：「占謂自隱度其實，定其辭也。占音章贍反。下又言占名數，其義並同。今猶謂獄訟之辨曰占，皆其意也。蓋武帝時賦斂繁多，律外而取，今始復舊。」","sentenceOrder":82},
  {"id":"s_work_han_thu_8_83","chapterId":"ch_work_han_thu_8","textTraditional":"詔曰：「鉤町侯毋波〔一〕率其君長人民擊反者，斬首捕虜有功。其立毋波為鉤町王。大鴻臚廣明將率有功，賜爵關內侯，食邑。」","sentenceOrder":83},
  {"id":"s_work_han_thu_8_84","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　服虔曰：「鉤音左傳射兩軥之軥。」應劭曰：「町音若挺，西南夷也。毋波，其名也。今牂柯鉤町縣是也。」師古曰：「音劬挺。」","sentenceOrder":84},
  {"id":"s_work_han_thu_8_85","chapterId":"ch_work_han_thu_8","textTraditional":"元鳳元年春，〔一〕長公主共養勞苦，復以藍田益長公主湯沐邑。","sentenceOrder":85},
  {"id":"s_work_han_thu_8_86","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　應劭曰：「三年中，鳳皇比下東海海西樂鄉，於是以冠元焉。」","sentenceOrder":86},
  {"id":"s_work_han_thu_8_87","chapterId":"ch_work_han_thu_8","textTraditional":"泗水戴王前薨，以毋嗣，國除。後宮有遺腹子煖，〔一〕相、內史不奏言，上聞而憐之，立煖為泗水王。相、內史皆下獄。","sentenceOrder":87},
  {"id":"s_work_han_thu_8_88","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「煖音許遠反。」","sentenceOrder":88},
  {"id":"s_work_han_thu_8_89","chapterId":"ch_work_han_thu_8","textTraditional":"三月，賜郡國所選有行義者涿郡韓福等五人帛，人五十匹，遣歸。詔曰：「朕閔勞以官職之事，〔一〕其務修孝弟以教鄉里。令郡縣常以正月賜羊酒。有不幸者賜衣被一襲，祠以中牢。」〔二〕","sentenceOrder":89},
  {"id":"s_work_han_thu_8_90","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　鄧展曰：「閔哀韓福等，不忍勞役以官職之事。」","sentenceOrder":90},
  {"id":"s_work_han_thu_8_91","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　師古曰：「幸者，吉而免凶也，故死謂之不幸。一襲，一稱也，猶今言一副也。中牢即少牢，謂羊豕也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_8_92","chapterId":"ch_work_han_thu_8","textTraditional":"武都氐人反，〔一〕遣執金吾馬適建、龍頟侯韓增、〔二〕大鴻臚廣明將三輔、太常徒，皆免刑擊之。〔三〕","sentenceOrder":92},
  {"id":"s_work_han_thu_8_93","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「氐音丁奚反。」","sentenceOrder":93},
  {"id":"s_work_han_thu_8_94","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　師古曰：「姓馬適，名建也。龍頟，漢書本或作雒字。功臣侯表云弓高壯侯韓頹當子譊封龍雒侯，元鼎五年坐酎金免。後元元年譊弟子增紹封龍雒侯。而荀悅漢紀龍雒皆為頟字。」崔浩曰：「雒音洛。今河間龍雒村，與弓高相近。」然此既地名，無別指義，各依書字而讀之，斯則通矣。譊音女交反。」","sentenceOrder":94},
  {"id":"s_work_han_thu_8_95","chapterId":"ch_work_han_thu_8","textTraditional":"〔三〕　蘇林曰：「是時太常主諸陵縣治民也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_8_96","chapterId":"ch_work_han_thu_8","textTraditional":"夏六月，赦天下。","sentenceOrder":96},
  {"id":"s_work_han_thu_8_97","chapterId":"ch_work_han_thu_8","textTraditional":"秋七月乙亥晦，日有蝕之，既。","sentenceOrder":97},
  {"id":"s_work_han_thu_8_98","chapterId":"ch_work_han_thu_8","textTraditional":"八月，改始元為元鳳。","sentenceOrder":98},
  {"id":"s_work_han_thu_8_99","chapterId":"ch_work_han_thu_8","textTraditional":"九月，鄂邑長公主、燕王旦與左將軍上官桀、桀子票騎將軍安、御史大夫桑弘羊皆謀反，伏誅。初，桀、安父子與大將軍光爭權，欲害之，詐使人為燕王旦上書言光罪。時上年十四，〔一〕覺其詐。後有譖光者，上輒怒曰：「大將軍國家忠臣，先帝所屬，〔二〕敢有譖毀者，坐之。」光由是得盡忠。語在燕王、霍光傳。","sentenceOrder":99},
  {"id":"s_work_han_thu_8_100","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　張晏曰：「武帝崩時八歲，即位於今七歲，今年十五。」師古曰：「此云『初，桀、安父子與大將軍爭權，詐為燕王上書』，蓋追道前年事耳，非今歲也。張說（非）〔失〕之。」","sentenceOrder":100},
  {"id":"s_work_han_thu_8_101","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　師古曰：「屬音之欲反。」","sentenceOrder":101},
  {"id":"s_work_han_thu_8_102","chapterId":"ch_work_han_thu_8","textTraditional":"冬十月，詔曰：「左將軍安陽侯桀、票騎將軍桑樂侯安、御史大夫弘羊皆數以邪枉干輔政，〔一〕大將軍不聽，而懷怨望，與燕王通謀，置驛往來相約結。燕王遣壽西長、孫縱之等〔二〕賂遺長公主、丁外人、謁者杜延年、大將軍長史公孫遺等，交通私書，〔三〕共謀令長公主置酒，伏兵殺大將軍光，徵立燕王為天子，大逆毋道。故稻田使者燕倉先發覺，〔四〕以告大司農敞，〔五〕敞告諫大夫延年，〔六〕延年以聞。丞相徵事任宮手捕斬桀，〔七〕丞相少史王壽誘將安入府門，〔八〕皆已伏誅，吏民得以安。封延年、倉、宮、壽皆為列侯。」又曰：「燕王迷惑失道，前與齊王子劉澤等為逆，抑而不揚，望王反道自新，〔九〕今乃與長公主及左將軍桀等謀危宗廟。王及公主皆自伏辜。其赦王太子建、公主子文信及宗室子與燕王、上官桀等謀反父母同產當坐者，皆免為庶人。其吏為桀等所詿誤，未發覺在吏者，除其罪。」〔一０〕","sentenceOrder":102},
  {"id":"s_work_han_thu_8_103","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「枉，曲也，以邪曲之事而干求也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_8_104","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　蘇林曰：「壽西，姓也。長，名也。孫姓，縱之名。」","sentenceOrder":104},
  {"id":"s_work_han_thu_8_105","chapterId":"ch_work_han_thu_8","textTraditional":"〔三〕　服虔曰：「外人，主之所幸也。」晉灼曰：「漢語字少君。」師古曰：「此杜延年自別一人，非下諫大夫也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_8_106","chapterId":"ch_work_han_thu_8","textTraditional":"〔四〕　如淳曰：「特為諸稻田置使者，假與民收其稅入也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_8_107","chapterId":"ch_work_han_thu_8","textTraditional":"〔五〕　師古曰：「楊敞也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_8_108","chapterId":"ch_work_han_thu_8","textTraditional":"〔六〕　師古曰：「杜延年，杜周之子。」","sentenceOrder":108},
  {"id":"s_work_han_thu_8_109","chapterId":"ch_work_han_thu_8","textTraditional":"〔七〕　文穎曰：「徵事，丞相官屬，位差尊，掾屬也。」如淳曰：「時宮以時事召，待詔丞相府，故曰丞相徵事。」張晏曰：「漢儀注徵事比六百石。皆故吏二千石不以臧罪免者為徵事，絳衣奉朝賀正月。」師古曰：「張說是也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_8_110","chapterId":"ch_work_han_thu_8","textTraditional":"〔八〕　如淳曰：「漢儀注丞相、太尉、大將軍史秩四百石。武帝又置丞相少史，秩四百石。」","sentenceOrder":110},
  {"id":"s_work_han_thu_8_111","chapterId":"ch_work_han_thu_8","textTraditional":"〔九〕　師古曰：「所為邪僻，違失正道，欲其旋反而歸正，故云反道。」","sentenceOrder":111},
  {"id":"s_work_han_thu_8_112","chapterId":"ch_work_han_thu_8","textTraditional":"〔一０〕　師古曰：「其罪未發，未為吏所執持者。」","sentenceOrder":112},
  {"id":"s_work_han_thu_8_113","chapterId":"ch_work_han_thu_8","textTraditional":"二年夏四月，上自建章宮徙未央宮，大置酒。賜郎從官帛，及宗室子錢，人二十萬。吏民獻牛酒者賜帛，人一匹。","sentenceOrder":113},
  {"id":"s_work_han_thu_8_114","chapterId":"ch_work_han_thu_8","textTraditional":"六月，赦天下。詔曰：「朕閔百姓未贍，〔一〕前年減漕三百萬石。〔二〕頗省乘輿馬及（菀）〔苑〕馬，〔三〕以補邊郡三輔傳馬。〔四〕其令郡國毋斂今年馬口錢，〔五〕三輔、太常郡得以叔粟當賦。」〔六〕","sentenceOrder":114},
  {"id":"s_work_han_thu_8_115","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「贍，足也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_8_116","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　師古曰：「減省轉漕，所以休力役也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_8_117","chapterId":"ch_work_han_thu_8","textTraditional":"〔三〕　師古曰：「乘輿馬謂天子所自乘以駕車輿者。他皆類此。」","sentenceOrder":117},
  {"id":"s_work_han_thu_8_118","chapterId":"ch_work_han_thu_8","textTraditional":"〔四〕　張晏曰：「驛馬也。」師古曰：「傳音張戀反。」","sentenceOrder":118},
  {"id":"s_work_han_thu_8_119","chapterId":"ch_work_han_thu_8","textTraditional":"〔五〕　文穎曰：「往時有馬口出斂錢，今省。」如淳曰：「所謂租及六畜也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_8_120","chapterId":"ch_work_han_thu_8","textTraditional":"〔六〕　如淳曰：「百官表太常主諸陵，別治其縣，爵秩如三輔郡矣。元帝永光五年，令各屬在所郡也。」師古曰：「諸應出賦算租稅者，皆聽以叔粟當錢物也。叔，豆也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_8_121","chapterId":"ch_work_han_thu_8","textTraditional":"三年春正月，泰山有大石自起立，上林有柳樹枯僵自起生。〔一〕","sentenceOrder":121},
  {"id":"s_work_han_thu_8_122","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「僵，偃也，謂樹枯死偃臥在地者也。僵音紀良反。」","sentenceOrder":122},
  {"id":"s_work_han_thu_8_123","chapterId":"ch_work_han_thu_8","textTraditional":"罷中牟苑賦貧民。〔一〕詔曰：「乃者民被水災，頗匱於食，朕虛倉廩，〔二〕使使者振困乏。其止四年毋漕。三年以前所振貸，非丞相御史所請，邊郡受牛者勿收責。」〔三〕","sentenceOrder":123},
  {"id":"s_work_han_thu_8_124","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「在滎陽。」","sentenceOrder":124},
  {"id":"s_work_han_thu_8_125","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　師古曰：「倉，新穀所藏也。廩，穀所振入也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_8_126","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　應劭曰：「武帝始開三邊，徙民屯田，皆與犁牛。後丞相御史復間有所請。今敕自上所賜與勿收責，丞相所請乃令其顧稅耳。」","sentenceOrder":126},
  {"id":"s_work_han_thu_8_127","chapterId":"ch_work_han_thu_8","textTraditional":"夏四月，少府徐仁、廷尉王平、左馮翊賈勝胡皆坐縱反者，仁自殺，平、勝胡皆要斬。","sentenceOrder":127},
  {"id":"s_work_han_thu_8_128","chapterId":"ch_work_han_thu_8","textTraditional":"冬，遼東烏桓反，以中郎將范明友為度遼將軍，〔一〕將北邊七郡郡二千騎擊之。","sentenceOrder":128},
  {"id":"s_work_han_thu_8_129","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　應劭曰：「當度遼水往擊之，故以度遼為官號。」","sentenceOrder":129},
  {"id":"s_work_han_thu_8_130","chapterId":"ch_work_han_thu_8","textTraditional":"四年春正月丁亥，帝加元服，〔一〕見于高廟。賜諸侯王、丞相、大將軍、列侯、宗室下至吏民金帛牛酒各有差。賜中二千石以下及天下民爵。毋收四年、五年口賦。〔二〕三年以前逋更賦未入者，皆勿收。〔三〕令天下酺五日。","sentenceOrder":130},
  {"id":"s_work_han_thu_8_131","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　如淳曰：「元服，謂初冠加上服也。」師古曰：「如氏以為衣服之服，此說非也。元，首也。冠者，首之所著，故曰元服。其下汲黯傳序云『上正元服』，是知謂冠為元服。」","sentenceOrder":131},
  {"id":"s_work_han_thu_8_132","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　如淳曰：「漢儀注民年七歲至十四出口賦錢，人二十三。二十錢以食天子，其三錢者，武帝加口錢以補車騎馬。」","sentenceOrder":132},
  {"id":"s_work_han_thu_8_133","chapterId":"ch_work_han_thu_8","textTraditional":"〔三〕　如淳曰：「更有三品，有卒更，有踐更，有過更。古者正卒無常人，皆當迭為之，一月一更，是謂卒更也。貧者欲得顧更錢者，次直者出錢顧之，月二千，是謂踐更也。天下人皆直戍邊三日，亦名為更，律所謂繇戍也。雖丞相子亦在戍邊之調。不可人人自行三日戍，又行者當自戍三日，不可往便還，因便住一歲一更。諸不行者，出錢三百入官，官以給戍者，是謂過更也。律說，卒踐更者，居也，居更縣中五月乃更也。後從尉律，卒踐更一月，休十一月也。食貨志曰：『月為更卒，已復為正，一歲屯戍，一歲力役，三十倍於古。』此漢初因秦法而行之也。後遂改易，有謫乃戍邊一歲耳。逋，未出更錢者也。」師古曰：「更音工衡反。」","sentenceOrder":133},
  {"id":"s_work_han_thu_8_134","chapterId":"ch_work_han_thu_8","textTraditional":"甲戌，丞相千秋薨。〔一〕","sentenceOrder":134},
  {"id":"s_work_han_thu_8_135","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「田千秋。」","sentenceOrder":135},
  {"id":"s_work_han_thu_8_136","chapterId":"ch_work_han_thu_8","textTraditional":"夏四月，詔曰：「度遼將軍明友前以羌騎校尉將羌王侯君長以下擊益州反虜，後復率擊武都反氐，今破烏桓，斬虜獲生，有功。〔一〕其封明友為平陵侯。平樂監傅介子持節使，〔二〕誅斬樓蘭王安，歸首縣北闕，封義陽侯。」","sentenceOrder":136},
  {"id":"s_work_han_thu_8_137","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「既斬反虜，又獲生口也。俘取曰獲。」","sentenceOrder":137},
  {"id":"s_work_han_thu_8_138","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　師古曰：「持節而為使。」","sentenceOrder":138},
  {"id":"s_work_han_thu_8_139","chapterId":"ch_work_han_thu_8","textTraditional":"五月丁丑，孝文廟正殿火，上及群臣皆素服。發中二千石將五校作治，六日成。〔一〕太常及廟令丞郎吏皆劾大不敬，會赦，太常轑陽侯德免為庶人。〔二〕","sentenceOrder":139},
  {"id":"s_work_han_thu_8_140","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「率領五校之士以作治也。校音下教反。」","sentenceOrder":140},
  {"id":"s_work_han_thu_8_141","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　文穎曰：「轑音料。德，江德也。轑陽在魏郡清淵。」師古曰：「會六月赦耳。史終言之。」","sentenceOrder":141},
  {"id":"s_work_han_thu_8_142","chapterId":"ch_work_han_thu_8","textTraditional":"六月，赦天下。","sentenceOrder":142},
  {"id":"s_work_han_thu_8_143","chapterId":"ch_work_han_thu_8","textTraditional":"五年春正月，廣陵王來朝，益國萬一千戶，賜錢二千萬，黃金二百斤，劍二，安車一，乘馬二駟。〔一〕","sentenceOrder":143},
  {"id":"s_work_han_thu_8_144","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「八匹也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_8_145","chapterId":"ch_work_han_thu_8","textTraditional":"夏，大旱。","sentenceOrder":145},
  {"id":"s_work_han_thu_8_146","chapterId":"ch_work_han_thu_8","textTraditional":"六月，發三輔及郡國惡少年吏有告劾亡者，屯遼東。〔一〕","sentenceOrder":146},
  {"id":"s_work_han_thu_8_147","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　如淳曰：「告者，為人所告也。劾者，為人所劾也。」師古曰：「惡少年謂無賴子弟也。告劾亡者，謂被告劾而逃亡。」","sentenceOrder":147},
  {"id":"s_work_han_thu_8_148","chapterId":"ch_work_han_thu_8","textTraditional":"秋，罷象郡，分屬鬱林、牂柯。","sentenceOrder":148},
  {"id":"s_work_han_thu_8_149","chapterId":"ch_work_han_thu_8","textTraditional":"冬十一月，大雷。","sentenceOrder":149},
  {"id":"s_work_han_thu_8_150","chapterId":"ch_work_han_thu_8","textTraditional":"十二月庚戌，丞相訢薨。〔一〕","sentenceOrder":150},
  {"id":"s_work_han_thu_8_151","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「王訢也。訢亦欣字。」","sentenceOrder":151},
  {"id":"s_work_han_thu_8_152","chapterId":"ch_work_han_thu_8","textTraditional":"六年春正月，募郡國徒築遼東玄菟城。夏，赦天下。詔曰：「夫穀賤傷農，〔一〕今三輔、太常穀減賤，〔二〕其令以叔粟當今年賦。」〔三〕","sentenceOrder":152},
  {"id":"s_work_han_thu_8_153","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「糶多而錢少，是為傷也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_8_154","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　鄭氏曰：「減音減少之減。」","sentenceOrder":154},
  {"id":"s_work_han_thu_8_155","chapterId":"ch_work_han_thu_8","textTraditional":"〔三〕　應劭曰：「太常掌諸陵園，皆徙天下豪富民以充實之，後悉為縣，故與三輔同賦。」","sentenceOrder":155},
  {"id":"s_work_han_thu_8_156","chapterId":"ch_work_han_thu_8","textTraditional":"右將軍張安世宿衛忠謹，封富平侯。","sentenceOrder":156},
  {"id":"s_work_han_thu_8_157","chapterId":"ch_work_han_thu_8","textTraditional":"烏桓復犯塞，遣度遼將軍范明友擊之。","sentenceOrder":157},
  {"id":"s_work_han_thu_8_158","chapterId":"ch_work_han_thu_8","textTraditional":"元平元年春二月，詔曰：「天下以農桑為本。日者省用，罷不急官，〔一〕減外繇，〔二〕耕桑者益眾，而百姓未能家給，〔三〕朕甚愍焉。其減口賦錢。」有司奏請減什三，上許之。","sentenceOrder":158},
  {"id":"s_work_han_thu_8_159","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「謂非要職（官）〔者〕。」","sentenceOrder":159},
  {"id":"s_work_han_thu_8_160","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　師古曰：「繇讀曰傜。」","sentenceOrder":160},
  {"id":"s_work_han_thu_8_161","chapterId":"ch_work_han_thu_8","textTraditional":"〔三〕　師古曰：「給，足也。家家自給足，是（謂）〔為〕家給也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_8_162","chapterId":"ch_work_han_thu_8","textTraditional":"甲申，晨有流星，大如月，眾星皆隨西行。","sentenceOrder":162},
  {"id":"s_work_han_thu_8_163","chapterId":"ch_work_han_thu_8","textTraditional":"夏四月癸未，帝崩于未央宮。〔一〕六月壬申，葬平陵。〔二〕","sentenceOrder":163},
  {"id":"s_work_han_thu_8_164","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　臣瓚曰：「帝年九歲即位，即位十三年，壽二十二。」師古曰：「帝年八歲即位，明年改元，改元之後凡十三年，年二十一。」","sentenceOrder":164},
  {"id":"s_work_han_thu_8_165","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　臣瓚曰：「自崩至葬凡四十九日。平陵在長安西北七十里。」","sentenceOrder":165},
  {"id":"s_work_han_thu_8_166","chapterId":"ch_work_han_thu_8","textTraditional":"贊曰：昔周成以孺子繼統，而有管、蔡四國流言之變。〔一〕孝昭幼年即位，亦有燕、盍、上官逆亂之謀。成王不疑周公，孝昭委任霍光，各因其時以成名，大矣哉！承孝武奢侈餘敝師旅之後，海內虛耗，戶口減半，〔二〕光知時務之要，輕繇薄賦，與民休息。〔三〕至始元、元鳳之間，匈奴和親，百姓充實。舉賢良文學，問民所疾苦，議鹽鐵而罷榷酤，尊號曰「昭」，不亦宜乎！","sentenceOrder":166},
  {"id":"s_work_han_thu_8_167","chapterId":"ch_work_han_thu_8","textTraditional":"〔一〕　師古曰：「四國，謂管、蔡、商、奄也。流，放也。武王崩，成王幼弱，周公攝政，四國乃流言曰公將不利於孺子，遂致雷風之異。成王既見金縢之冊，乃不疑周公。事見豳詩及周書大誥。」","sentenceOrder":167},
  {"id":"s_work_han_thu_8_168","chapterId":"ch_work_han_thu_8","textTraditional":"〔二〕　師古曰：「耗，損也，音火到反。減讀為減省之減。」","sentenceOrder":168},
  {"id":"s_work_han_thu_8_169","chapterId":"ch_work_han_thu_8","textTraditional":"〔三〕　師古曰：「繇讀曰傜。」","sentenceOrder":169},
  {"id":"s_work_han_thu_8_170","chapterId":"ch_work_han_thu_8","textTraditional":"校勘記","sentenceOrder":170},
  {"id":"s_work_han_thu_8_171","chapterId":"ch_work_han_thu_8","textTraditional":"二一八頁一四行　以為（上）〔土〕德之瑞，　景祐、汲古、殿、局本都作「土」。王先謙說作「土」是。","sentenceOrder":171},
  {"id":"s_work_han_thu_8_172","chapterId":"ch_work_han_thu_8","textTraditional":"二二三頁　一行　通保傅，傳孝經、論語、尚書，未云有明。　舊注「保傅傳」連讀，以為是賈誼所作書名。李慈銘說，帝自謂雖通接保傅，傳授孝經、論語、尚書，皆未能有明，當以傅字絕句。王先謙、楊樹達都從李讀。","sentenceOrder":172},
  {"id":"s_work_han_thu_8_173","chapterId":"ch_work_han_thu_8","textTraditional":"二二六頁一一行　張說（非）〔失〕之。　景祐、殿本都作「失」。王先謙說作「失」是。","sentenceOrder":173},
  {"id":"s_work_han_thu_8_174","chapterId":"ch_work_han_thu_8","textTraditional":"二二八頁　四行　頗省乘輿馬及（菀）〔苑〕馬，　景祐、殿本都作「苑」。王先謙說作「苑」是。","sentenceOrder":174},
  {"id":"s_work_han_thu_8_175","chapterId":"ch_work_han_thu_8","textTraditional":"二三二頁一０行　謂非要職（官）〔者〕。　景祐本作「者」。","sentenceOrder":175},
  {"id":"s_work_han_thu_8_176","chapterId":"ch_work_han_thu_8","textTraditional":"二三二頁一二行　是（謂）〔為〕家給也。　景祐、殿本都作「為」。","sentenceOrder":176},
  {"id":"s_work_han_thu_9_1","chapterId":"ch_work_han_thu_9","textTraditional":"孝宣皇帝，〔一〕武帝曾孫，戾太子孫也。〔二〕太子納史良娣，〔三〕生史皇孫。〔四〕皇孫納王夫人，生宣帝，號曰皇曾孫。生數月，遭巫蠱事，太子、良娣、皇孫、王夫人皆遇害。語在太子傳。曾孫雖在襁褓，〔五〕猶坐收繫郡邸獄。〔六〕而邴吉為廷尉監〔七〕，治巫蠱於郡邸，憐曾孫之亡辜，使女徒復作淮陽趙徵卿、渭城胡組更乳養，〔八〕私給衣食，視遇甚有恩。","sentenceOrder":1},
  {"id":"s_work_han_thu_9_2","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　荀悅曰：「諱詢，字次卿。詢之字曰謀。」應劭曰：「諡法『聖善周聞曰宣』。」","sentenceOrder":2},
  {"id":"s_work_han_thu_9_3","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　韋昭曰：「以違戾擅發兵，故諡曰戾。」臣瓚曰：「太子誅江充以除讒賊，而事不見明。後武帝覺寤，遂族充家，宣帝不得以加惡諡也。董仲舒曰『有其功無其意謂之戾，無其功有其意謂之罪』。」師古曰：「瓚說是也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_9_4","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　服虔曰：「史，姓也。良娣，官也。」師古曰：「太子有妃，有良娣，有孺子，凡三等。娣音次第之第。」","sentenceOrder":4},
  {"id":"s_work_han_thu_9_5","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　師古曰：「以外家姓稱之，故曰史皇孫。」","sentenceOrder":5},
  {"id":"s_work_han_thu_9_6","chapterId":"ch_work_han_thu_9","textTraditional":"〔五〕　李奇曰：「襁，絡也，以繒布為之，絡負小兒。褓，小兒大藉也。」孟康曰：「褓，小兒被也。」師古曰：「襁即今之小兒繃也。褓，孟說是也。襁音居丈反。褓音保。繃音補耕反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_9_7","chapterId":"ch_work_han_thu_9","textTraditional":"〔六〕　如淳曰：「謂諸郡邸置獄也。」師古曰：「據漢舊儀，郡邸獄治天下郡國上計者，屬大鴻臚。此蓋巫蠱獄繁，收繫者眾，故曾孫寄在郡邸獄。」","sentenceOrder":7},
  {"id":"s_work_han_thu_9_8","chapterId":"ch_work_han_thu_9","textTraditional":"〔七〕　師古曰：「監者，廷尉之官屬。」","sentenceOrder":8},
  {"id":"s_work_han_thu_9_9","chapterId":"ch_work_han_thu_9","textTraditional":"〔八〕　李奇曰：「復作者，女徒也。謂輕罪，男子守邊一歲，女子軟弱不任守，復令作於官，亦一歲，故謂之復作徒也。」孟康曰：「復音服，謂弛刑徒也，有赦令詔書去其鉗釱赭衣。更犯事，不從徒加，與民為例，故當復為官作，滿其本罪年月日，律名為復作也。」師古曰：「孟說是也。趙徵卿淮陽人，胡組渭城人，皆女徒也。二人更遞乳養曾孫。而邴吉傳云郭徵卿。紀、傳不同，未知孰是。更音工衡反。」","sentenceOrder":9},
  {"id":"s_work_han_thu_9_10","chapterId":"ch_work_han_thu_9","textTraditional":"巫蠱事連歲不決。至後元二年，武帝疾，往來長楊、五柞宮〔一〕，望氣者言長安獄中有天子氣，上遣使者分條中都官獄〔二〕繫者，輕重皆殺之。內謁者令郭穰夜至郡邸獄，〔三〕吉拒閉，使者不得入，曾孫賴吉得全。因遭大赦，吉乃載曾孫送祖母史良娣家。語在吉及外戚傳。","sentenceOrder":10},
  {"id":"s_work_han_thu_9_11","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「長楊、五柞二宮並在盩厔，皆以樹名之。帝往來二宮之間也。柞字或作莋，其音同。」","sentenceOrder":11},
  {"id":"s_work_han_thu_9_12","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「中都官，凡京師諸官府也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_9_13","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　師古曰：「百官表云內者署屬少府。續漢書志云掌宮中布張諸褻物。丁孚漢官云令秩千石，蓋當時權為此使。」","sentenceOrder":13},
  {"id":"s_work_han_thu_9_14","chapterId":"ch_work_han_thu_9","textTraditional":"後有詔掖庭養視，上屬籍宗正。〔一〕時掖庭令張賀嘗事戾太子，思顧舊恩，〔二〕哀曾孫，奉養甚謹，以私錢供給教書。既壯，為取暴室嗇夫許廣漢女，〔三〕曾孫因依倚廣漢兄弟及祖母家史氏〔四〕。受詩於東海澓中翁，〔五〕高材好學，然亦喜游俠，〔六〕鬥雞走馬，具知閭里奸邪，吏治得失。數上下諸陵，〔七〕周遍三輔〔八〕，常困於蓮勺鹵中。〔九〕尤樂杜、鄠之間，〔一０〕率常在下杜。〔一一〕時會朝請，舍長安尚冠里，〔一二〕身足下有毛，臥居數有光燿。〔一三〕每買餅，所從買家輒大讎，〔一四〕亦以（自是）〔是自〕怪。","sentenceOrder":14},
  {"id":"s_work_han_thu_9_15","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　應劭曰：「掖庭，宮人之官，有令丞，宦者為之。詔敕掖庭養視之，始令宗正著其屬籍。」","sentenceOrder":15},
  {"id":"s_work_han_thu_9_16","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「顧，念也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_9_17","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　應劭曰：「暴室，宮人獄也，今曰薄室。許廣漢坐法腐為宦者，作嗇夫也。」師古曰：「暴室者，掖庭主織作染練之署，故謂之暴室，取暴曬為名耳。或云薄室者，薄亦暴也。今俗語亦云薄曬。蓋暴室職務既多，因為置獄主治其罪人，故往往云暴室獄耳。然本非獄名，應說失之矣。嗇夫者，暴室屬官，亦猶縣鄉之嗇夫也。曬音所懈反，又音所智反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_9_18","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　師古曰：「倚音於綺反。」","sentenceOrder":18},
  {"id":"s_work_han_thu_9_19","chapterId":"ch_work_han_thu_9","textTraditional":"〔五〕　服虔曰：「澓音馥。」師古曰：「東海人，姓澓，字中翁也。澓音房福反。中讀曰仲。」","sentenceOrder":19},
  {"id":"s_work_han_thu_9_20","chapterId":"ch_work_han_thu_9","textTraditional":"〔六〕　師古曰：「喜音許吏反。」","sentenceOrder":20},
  {"id":"s_work_han_thu_9_21","chapterId":"ch_work_han_thu_9","textTraditional":"〔七〕　師古曰：「諸陵皆據高敞地為之，縣即在其側。帝每周游往來諸陵縣，去則上，來則下，故言上下諸陵。」","sentenceOrder":21},
  {"id":"s_work_han_thu_9_22","chapterId":"ch_work_han_thu_9","textTraditional":"〔八〕　師古曰：「游行皆至其處。」","sentenceOrder":22},
  {"id":"s_work_han_thu_9_23","chapterId":"ch_work_han_thu_9","textTraditional":"〔九〕　如淳曰：「為人所困辱也。蓮勺縣有鹽池，縱廣十餘里，其鄉人名為鹵中。蓮音輦。勺音灼。」師古曰：「如說是也。鹵者，鹹地也，今在櫟陽縣東。其鄉人謂此中為鹵鹽池也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_9_24","chapterId":"ch_work_han_thu_9","textTraditional":"〔一０〕師古曰：「二縣之間也。杜屬京兆，鄠屬扶風。鄠音扈。」","sentenceOrder":24},
  {"id":"s_work_han_thu_9_25","chapterId":"ch_work_han_thu_9","textTraditional":"〔一一〕孟康曰：「在長安南。」師古曰：「率者，總計之言也。下杜即今之杜城。」","sentenceOrder":25},
  {"id":"s_work_han_thu_9_26","chapterId":"ch_work_han_thu_9","textTraditional":"〔一二〕文穎曰：「以屬弟尚親，故歲時隨宗室朝會也。」如淳曰：「春曰朝，秋曰請。」師古曰：「舍，止也。尚冠者，長安中里名。帝會朝請之時，即於此里中止息。請音才姓反。」","sentenceOrder":26},
  {"id":"s_work_han_thu_9_27","chapterId":"ch_work_han_thu_9","textTraditional":"〔一三〕師古曰：「遍身及足下皆有毛。」","sentenceOrder":27},
  {"id":"s_work_han_thu_9_28","chapterId":"ch_work_han_thu_9","textTraditional":"〔一四〕師古曰：「讎讀曰售。」","sentenceOrder":28},
  {"id":"s_work_han_thu_9_29","chapterId":"ch_work_han_thu_9","textTraditional":"元平元年四月，昭帝崩，毋嗣。大將軍霍光請皇后徵昌邑王。六月丙寅，王受皇帝璽綬，尊皇后曰皇太后。癸巳，光奏王賀淫亂，請廢。語在賀及光傳。","sentenceOrder":29},
  {"id":"s_work_han_thu_9_30","chapterId":"ch_work_han_thu_9","textTraditional":"秋七月，光奏議曰：「禮，人道親親故尊祖，尊祖故敬宗。大宗毋嗣，擇支子孫賢者為嗣。孝武皇帝曾孫病已，〔一〕有詔掖庭養視，至今年十八，師受詩、論語、孝經，操行節儉，慈仁愛人，可以嗣孝昭皇帝後，奉承祖宗，子萬姓。」〔二〕奏可。遣宗正德至曾孫尚冠里舍，洗沐，賜御府衣。太僕以軨獵車奉迎曾孫，〔三〕就齊宗正府。庚申，入未央宮，見皇太后，封為陽武侯。〔四〕已而群臣奉上璽綬，即皇帝位，謁高廟。","sentenceOrder":30},
  {"id":"s_work_han_thu_9_31","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「蓋以夙遭屯難而多病苦，故名病已，欲其速差也。後以為鄙，更改諱詢。」","sentenceOrder":31},
  {"id":"s_work_han_thu_9_32","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「天子以萬姓為子，故云子萬姓。」","sentenceOrder":32},
  {"id":"s_work_han_thu_9_33","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　文穎曰：「軨獵，小車，前有曲輿不衣也，近世謂之軨獵車也。」孟康曰：「今之載獵車也。前有曲軨，特高大，獵時立其中格射禽獸。」李奇曰：「蘭輿輕車也。」師古曰：「文、李二說皆是。時未備天子車駕，故且取其輕便耳，非藉高大也。孟說失之。軨音鈴。」","sentenceOrder":33},
  {"id":"s_work_han_thu_9_34","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　師古曰：「先封侯者，不欲立庶人為天子也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_9_35","chapterId":"ch_work_han_thu_9","textTraditional":"八月己巳，丞相敞薨。〔一〕","sentenceOrder":35},
  {"id":"s_work_han_thu_9_36","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「楊敞也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_9_37","chapterId":"ch_work_han_thu_9","textTraditional":"九月，大赦天下。","sentenceOrder":37},
  {"id":"s_work_han_thu_9_38","chapterId":"ch_work_han_thu_9","textTraditional":"十一月壬子，立皇后許氏。賜諸侯王以下金錢，至吏民鰥寡孤獨各有差。皇太后歸長樂宮。初置屯衛。","sentenceOrder":38},
  {"id":"s_work_han_thu_9_39","chapterId":"ch_work_han_thu_9","textTraditional":"本始元年春正月，募郡國吏民訾百萬以上徙平陵。〔一〕遣使者持節詔郡國二千石謹牧養民而風德化。〔二〕","sentenceOrder":39},
  {"id":"s_work_han_thu_9_40","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　文穎曰：「昭帝陵。」","sentenceOrder":40},
  {"id":"s_work_han_thu_9_41","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「以德化被於下，故云風也。詩序曰『上以風化下』。」","sentenceOrder":41},
  {"id":"s_work_han_thu_9_42","chapterId":"ch_work_han_thu_9","textTraditional":"大將軍光稽首歸政，上謙讓委任焉。論定策功，益封大將軍光萬七千戶，車騎將軍光祿勳富平侯安世萬戶。〔一〕詔曰：「故丞相安平侯敞等居位守職，與大將軍光、車騎將軍安世建議定策，以安宗廟，功賞未加而薨。其益封敞嗣子忠及丞相陽平侯義、〔二〕度遼將軍平陵侯明友、〔三〕前將軍龍雒侯增、〔四〕太僕建平侯延年、〔五〕太常蒲侯昌、〔六〕諫大夫宜春侯譚、〔七〕當塗侯平、〔八〕杜侯屠耆堂、〔九〕長信少府關內侯勝〔一０〕邑戶各有差。封御史大夫廣明為昌水侯，〔一一〕後將軍充國為營平侯，〔一二〕大司農延年為陽城侯，〔一三〕少府樂成為爰氏侯，〔一四〕光祿大夫遷為平丘侯。〔一五〕賜右扶風德、〔一六〕典屬國武、〔一七〕廷尉光、〔一八〕宗正德、〔一九〕大鴻臚賢、〔二０〕詹事畸、〔二一〕光祿大夫吉、〔二二〕京輔都尉廣漢〔二三〕爵皆關內侯。德、武食邑。」〔二四〕","sentenceOrder":42},
  {"id":"s_work_han_thu_9_43","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　李斐曰：「居光祿位，以車騎官號尊之，無車騎官屬。」","sentenceOrder":43},
  {"id":"s_work_han_thu_9_44","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「蔡義。」","sentenceOrder":44},
  {"id":"s_work_han_thu_9_45","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　師古曰：「范明友。」","sentenceOrder":45},
  {"id":"s_work_han_thu_9_46","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　師古曰：「韓增。」","sentenceOrder":46},
  {"id":"s_work_han_thu_9_47","chapterId":"ch_work_han_thu_9","textTraditional":"〔五〕　師古曰：「杜延年。」","sentenceOrder":47},
  {"id":"s_work_han_thu_9_48","chapterId":"ch_work_han_thu_9","textTraditional":"〔六〕　師古曰：「蘇昌。」","sentenceOrder":48},
  {"id":"s_work_han_thu_9_49","chapterId":"ch_work_han_thu_9","textTraditional":"〔七〕　師古曰：「王譚。」","sentenceOrder":49},
  {"id":"s_work_han_thu_9_50","chapterId":"ch_work_han_thu_9","textTraditional":"〔八〕　師古曰：「功臣表云魏不害以捕反者胡倩功封當塗侯，其子聖以定策功益封，凡二千二百戶。今此紀言當塗侯平，與表乖錯，未知孰是。或者有二名乎？」","sentenceOrder":50},
  {"id":"s_work_han_thu_9_51","chapterId":"ch_work_han_thu_9","textTraditional":"〔九〕　蘇林曰：「姓復陸，其祖父復陸支本匈奴胡也，歸義為屬國王從驃騎有功，乃更封也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_9_52","chapterId":"ch_work_han_thu_9","textTraditional":"〔一０〕師古曰：「夏侯勝。」","sentenceOrder":52},
  {"id":"s_work_han_thu_9_53","chapterId":"ch_work_han_thu_9","textTraditional":"〔一一〕師古曰：「田廣明。」","sentenceOrder":53},
  {"id":"s_work_han_thu_9_54","chapterId":"ch_work_han_thu_9","textTraditional":"〔一二〕師古曰：「趙充國。」","sentenceOrder":54},
  {"id":"s_work_han_thu_9_55","chapterId":"ch_work_han_thu_9","textTraditional":"〔一三〕師古曰：「田延年。」","sentenceOrder":55},
  {"id":"s_work_han_thu_9_56","chapterId":"ch_work_han_thu_9","textTraditional":"〔一四〕師古曰：「史樂成。」","sentenceOrder":56},
  {"id":"s_work_han_thu_9_57","chapterId":"ch_work_han_thu_9","textTraditional":"〔一五〕師古曰：「王遷。」","sentenceOrder":57},
  {"id":"s_work_han_thu_9_58","chapterId":"ch_work_han_thu_9","textTraditional":"〔一六〕師古曰：「周德。」","sentenceOrder":58},
  {"id":"s_work_han_thu_9_59","chapterId":"ch_work_han_thu_9","textTraditional":"〔一七〕師古曰：「蘇武。」","sentenceOrder":59},
  {"id":"s_work_han_thu_9_60","chapterId":"ch_work_han_thu_9","textTraditional":"〔一八〕師古曰：「李光。」","sentenceOrder":60},
  {"id":"s_work_han_thu_9_61","chapterId":"ch_work_han_thu_9","textTraditional":"〔一九〕師古曰：「楚元王之曾孫，劉辟彊子。」","sentenceOrder":61},
  {"id":"s_work_han_thu_9_62","chapterId":"ch_work_han_thu_9","textTraditional":"〔二０〕師古曰：「韋賢。」","sentenceOrder":62},
  {"id":"s_work_han_thu_9_63","chapterId":"ch_work_han_thu_9","textTraditional":"〔二一〕蘇林曰：「畸音踦隻之踦。」師古曰：「宋（踦）〔畸〕也。音居宜反。」","sentenceOrder":63},
  {"id":"s_work_han_thu_9_64","chapterId":"ch_work_han_thu_9","textTraditional":"〔二二〕師古曰：「丙吉。」","sentenceOrder":64},
  {"id":"s_work_han_thu_9_65","chapterId":"ch_work_han_thu_9","textTraditional":"〔二三〕師古曰：「趙廣漢也。三輔郡皆有都尉，如諸郡。左輔都尉治高陵，右輔都尉治郿，京輔都尉治華陰灌北。」","sentenceOrder":65},
  {"id":"s_work_han_thu_9_66","chapterId":"ch_work_han_thu_9","textTraditional":"〔二四〕張晏曰：「舊關內侯無邑也，以蘇武守節外國，劉德宗室俊彥，故特令食邑。」","sentenceOrder":66},
  {"id":"s_work_han_thu_9_67","chapterId":"ch_work_han_thu_9","textTraditional":"夏四月庚午，地震。詔內郡國舉文學高第各一人。〔一〕","sentenceOrder":67},
  {"id":"s_work_han_thu_9_68","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　韋昭曰：「中國為內郡，緣邊有夷狄障塞者為外郡。成帝（侍）〔時〕，內郡舉方正，北邊二十二郡舉勇猛士。」","sentenceOrder":68},
  {"id":"s_work_han_thu_9_69","chapterId":"ch_work_han_thu_9","textTraditional":"五月，鳳皇集膠東、千乘。赦天下。賜吏二千石、諸侯相、下至中都官、宦吏、六百石爵，各有差，〔一〕自左更至五大夫。〔二〕賜天下人爵各一級，孝者二級，女子百戶牛酒。租稅勿收。","sentenceOrder":69},
  {"id":"s_work_han_thu_9_70","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　如淳曰：「中都官宦吏，奄人為吏者也。」晉灼曰：「凡職在京師者也。」師古曰：「二說皆非也。中都官，謂在京師諸官也。宦吏，諸奄官也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_9_71","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「左更，第十二爵也。五大夫，第九爵也。更音工衡反。」","sentenceOrder":71},
  {"id":"s_work_han_thu_9_72","chapterId":"ch_work_han_thu_9","textTraditional":"六月，詔曰：「故皇太子在湖，未有號諡。〔一〕歲時祠，其議諡，置園邑。」語在太子傳。","sentenceOrder":72},
  {"id":"s_work_han_thu_9_73","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「湖，縣名也。死於湖，因即葬焉。」","sentenceOrder":73},
  {"id":"s_work_han_thu_9_74","chapterId":"ch_work_han_thu_9","textTraditional":"秋七月，詔立燕剌王太子建為廣陽王，〔一〕立廣陵王胥少子弘為高密王。","sentenceOrder":74},
  {"id":"s_work_han_thu_9_75","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「剌音來曷反。」","sentenceOrder":75},
  {"id":"s_work_han_thu_9_76","chapterId":"ch_work_han_thu_9","textTraditional":"二年春，以水衡錢為平陵，徙民起第宅。〔一〕","sentenceOrder":76},
  {"id":"s_work_han_thu_9_77","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　應劭曰：「水衡與少府皆天子私藏耳。縣官公作，當仰給司農，今出水衡錢，言宣帝即位為異政也。」晉灼曰：「食貨志：『初，大司農管鹽鐵，官布多，故置水衡，欲以主鹽鐵。及楊可告緡，上林財物眾，乃令水衡主上林。』上林三官，主鑄錢也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_9_78","chapterId":"ch_work_han_thu_9","textTraditional":"大司農陽城侯田延年有罪，自殺。〔一〕","sentenceOrder":78},
  {"id":"s_work_han_thu_9_79","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「坐增僦直而自入。」","sentenceOrder":79},
  {"id":"s_work_han_thu_9_80","chapterId":"ch_work_han_thu_9","textTraditional":"夏五月，詔曰：「朕以眇身奉承祖宗，夙夜惟念孝武皇帝躬履仁義，選明將，討不服，匈奴遠遁，平氐、羌、昆明、南越，百蠻鄉風，〔一〕款塞來享；〔二〕建太學，修郊祀，定正朔，協音律；封泰山，塞宣房，〔三〕符瑞應，寶鼎出，白麟獲。功德茂盛，不能盡宣，而廟樂未稱，〔四〕其議奏。」有司奏請宜加尊號。六月庚午，尊孝武廟為世宗廟，奏盛德、文始、五行之舞，〔五〕天子世世獻。武帝巡狩所幸之郡國，皆立廟。賜民爵一級，女子百戶牛酒。","sentenceOrder":80},
  {"id":"s_work_han_thu_9_81","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「鄉讀曰嚮也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_9_82","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　應劭曰：「款，叩也，皆叩塞門來服從也。」如淳曰：「款，寬也。請除守塞者，自保不為寇害也，故曰款五原塞。」師古曰：「應說是也。此汎說夷狄來賓之事，非呼韓邪保塞意也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_9_83","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　蘇林曰：「隄名，在東郡界。」李斐曰：「決河上宮名也。」張晏曰：「瓠子隄名。」師古曰：「蘇、張二說皆是。」","sentenceOrder":83},
  {"id":"s_work_han_thu_9_84","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　師古曰：「稱，副也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_9_85","chapterId":"ch_work_han_thu_9","textTraditional":"〔五〕　應劭曰：「宣帝復采昭德之舞為盛德舞，以尊世宗廟也。諸帝廟皆常奏文始、四時、五行舞也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_9_86","chapterId":"ch_work_han_thu_9","textTraditional":"匈奴數侵邊，又西伐烏孫。烏孫昆彌及公主因國使者上書，〔一〕言昆彌願發國精兵擊匈奴，唯天子哀憐，出兵以救公主。秋，大發興調關東輕車銳卒，〔二〕選郡國吏三百石伉健習騎射者，皆從軍。〔三〕御史大夫田廣明為祁連將軍，〔四〕後將軍趙充國為蒲類將軍，〔五〕雲中太守田順為虎牙將軍，及度遼將軍范明友、前將軍韓增，凡五將軍，兵十五萬騎，校尉常惠持節護烏孫兵，咸擊匈奴。","sentenceOrder":86},
  {"id":"s_work_han_thu_9_87","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「昆彌，烏孫王之號也。國使者，漢朝之使也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_9_88","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「調亦選也。銳，利也，言其勇利也。調音徒釣反。」","sentenceOrder":88},
  {"id":"s_work_han_thu_9_89","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　師古曰：「伉，強也，音口浪反。」","sentenceOrder":89},
  {"id":"s_work_han_thu_9_90","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　應劭曰：「祁連，匈奴中山名也。諸將分部，廣明值此山，因以為號也。」師古曰：「祁音上夷反。」","sentenceOrder":90},
  {"id":"s_work_han_thu_9_91","chapterId":"ch_work_han_thu_9","textTraditional":"〔五〕　應劭曰：「蒲類，匈奴中海名也，在敦煌北。」晉灼曰：「匈奴傳有蒲類澤。」師古曰：「晉說是也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_9_92","chapterId":"ch_work_han_thu_9","textTraditional":"三年春正月癸亥，皇后許氏崩。戊辰，五將軍師發長安。夏五月，軍罷。祁連將軍廣明、虎牙將軍順有罪，下有司，皆自殺。〔一〕校尉常惠將烏孫兵入匈奴右地，大克獲，封列侯。","sentenceOrder":92},
  {"id":"s_work_han_thu_9_93","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　晉灼曰：「田千秋子也。廣明坐逗留，順坐增虜獲。」","sentenceOrder":93},
  {"id":"s_work_han_thu_9_94","chapterId":"ch_work_han_thu_9","textTraditional":"大旱。郡國傷旱甚者，民毋出租賦。三輔民就賤者，且毋收事，盡四年。〔一〕","sentenceOrder":94},
  {"id":"s_work_han_thu_9_95","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　晉灼曰：「不給官役也。」師古曰：「收謂租賦也，事謂役使也。盡本始四年而止。」","sentenceOrder":95},
  {"id":"s_work_han_thu_9_96","chapterId":"ch_work_han_thu_9","textTraditional":"六月己丑，丞相義薨。〔一〕","sentenceOrder":96},
  {"id":"s_work_han_thu_9_97","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「蔡義。」","sentenceOrder":97},
  {"id":"s_work_han_thu_9_98","chapterId":"ch_work_han_thu_9","textTraditional":"四年春正月，詔曰：「蓋聞農者興德之本也，今歲不登，已遣使者振貸困乏。其令太官損膳省宰，〔一〕樂府減樂人，使歸就農業。丞相以下至都官令丞〔二〕上書入穀，輸長安倉，助貸貧民。民以車船載穀入關者，得毋用傳。」〔三〕","sentenceOrder":98},
  {"id":"s_work_han_thu_9_99","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「膳，具食也，食之善者也。宰為屠殺也。省，減也。漢儀注太宰令屠者七十二人，宰二百人。」","sentenceOrder":99},
  {"id":"s_work_han_thu_9_100","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「都官令丞，京師諸署之令丞。」","sentenceOrder":100},
  {"id":"s_work_han_thu_9_101","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　師古曰：「傳，傳符也。欲穀之多，故不問其出入也。傳音張戀反。」","sentenceOrder":101},
  {"id":"s_work_han_thu_9_102","chapterId":"ch_work_han_thu_9","textTraditional":"三月乙卯，立皇后霍氏。賜丞相以下至郎吏從官金錢帛各有差。赦天下。","sentenceOrder":102},
  {"id":"s_work_han_thu_9_103","chapterId":"ch_work_han_thu_9","textTraditional":"夏四月壬寅，郡國四十九地震，或山崩水出。詔曰：「蓋災異者，天地之戒也。朕承洪業，奉宗廟，託于士民之上，未能和群生。乃者地震北海、琅邪，壞祖宗廟，朕甚懼焉。丞相、御史其與列侯、中二千石博問經學之士，有以應變，〔一〕輔朕之不逮，毋有所諱。令三輔、太常、內郡國舉賢良方正各一人。律令有可蠲除以安百姓，條奏。被地震壞敗甚者，勿收租賦。」大赦天下。上以宗廟墮，素服，避正殿五日。〔二〕","sentenceOrder":103},
  {"id":"s_work_han_thu_9_104","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「謂禦塞災異也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_9_105","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「墮者，毀也，音火規反。」","sentenceOrder":105},
  {"id":"s_work_han_thu_9_106","chapterId":"ch_work_han_thu_9","textTraditional":"五月，鳳皇集北海安丘、淳于。〔一〕","sentenceOrder":106},
  {"id":"s_work_han_thu_9_107","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「二縣皆屬北海郡。」","sentenceOrder":107},
  {"id":"s_work_han_thu_9_108","chapterId":"ch_work_han_thu_9","textTraditional":"秋，廣川王吉有罪，廢遷上庸，自殺。","sentenceOrder":108},
  {"id":"s_work_han_thu_9_109","chapterId":"ch_work_han_thu_9","textTraditional":"地節元年〔一〕春正月，有星孛于西方。","sentenceOrder":109},
  {"id":"s_work_han_thu_9_110","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　應劭曰：「以先者地震，山崩水出，於是改年曰地節，欲令地得其節。」","sentenceOrder":110},
  {"id":"s_work_han_thu_9_111","chapterId":"ch_work_han_thu_9","textTraditional":"三月，假郡國貧民田。〔一〕","sentenceOrder":111},
  {"id":"s_work_han_thu_9_112","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕師古曰：「權以給之，不常與。」","sentenceOrder":112},
  {"id":"s_work_han_thu_9_113","chapterId":"ch_work_han_thu_9","textTraditional":"夏六月，詔曰：「蓋聞堯親九族，以和萬國。〔一〕朕蒙遺德，奉承聖業，惟念宗室屬未盡而以罪絕，若有賢材，改行勸善，其復屬，使得自新。」〔二〕","sentenceOrder":113},
  {"id":"s_work_han_thu_9_114","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「尚書堯典云：『克明俊德，以親九族。九族既睦，平章百姓。百姓昭明，協和萬邦。』故詔引之。」","sentenceOrder":114},
  {"id":"s_work_han_thu_9_115","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「復音扶目反。」","sentenceOrder":115},
  {"id":"s_work_han_thu_9_116","chapterId":"ch_work_han_thu_9","textTraditional":"冬十一月，楚王延壽謀反，自殺。","sentenceOrder":116},
  {"id":"s_work_han_thu_9_117","chapterId":"ch_work_han_thu_9","textTraditional":"十二月癸亥晦，日有蝕之。","sentenceOrder":117},
  {"id":"s_work_han_thu_9_118","chapterId":"ch_work_han_thu_9","textTraditional":"二年春三月庚午，大司馬大將軍光薨。詔曰：「大司馬大將軍博陸侯〔一〕宿衛孝武皇帝三十餘年，輔孝昭皇帝十有餘年，遭大難，躬秉義，率三公、諸侯、九卿、大夫定萬世策，以安宗廟。天下蒸庶，咸以康寧，〔二〕功德茂盛，朕甚嘉之。復其後世，疇其爵邑〔三〕，世世毋有所與。〔四〕功如蕭相國。」","sentenceOrder":118},
  {"id":"s_work_han_thu_9_119","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「尊之，故不名。」","sentenceOrder":119},
  {"id":"s_work_han_thu_9_120","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「蒸庶，眾人也。康，安也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_9_121","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　師古曰：「律，非始封，十減二。疇者，等也，言不復減也。」師古曰：「復音方目反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_9_122","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　師古曰：「與讀曰豫。」","sentenceOrder":122},
  {"id":"s_work_han_thu_9_123","chapterId":"ch_work_han_thu_9","textTraditional":"夏四月，鳳皇集魯郡，群鳥從之。〔一〕大赦天下。","sentenceOrder":123},
  {"id":"s_work_han_thu_9_124","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「今流俗書本此下云『戊申立皇太子』，而後年又有立皇太子事，此蓋以元紀云元帝二歲宣帝即位，八歲為皇太子，故後人妄於此書加之，舊本無也。據疏廣及丙吉傳並云地節三年立皇太子，此即明驗，而或者妄為臆說，乖於實矣。」","sentenceOrder":124},
  {"id":"s_work_han_thu_9_125","chapterId":"ch_work_han_thu_9","textTraditional":"五月，光祿大夫平丘侯王遷有罪，下獄死。","sentenceOrder":125},
  {"id":"s_work_han_thu_9_126","chapterId":"ch_work_han_thu_9","textTraditional":"上始親政事，又思報大將軍功德，乃復使樂平侯山領尚書事〔一〕，而令群臣得奏封事，以知下情。五日一聽事，〔自丞相〕以下各奉職奏事，以傅奏其言，〔二〕考試功能。侍中尚書功勞當遷及有異善，厚加賞賜，至于子孫，終不改易。〔三〕樞機周密，品式備具，上下相安，莫有苟且之意也。","sentenceOrder":126},
  {"id":"s_work_han_thu_9_127","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「霍山，光之兄孫。」","sentenceOrder":127},
  {"id":"s_work_han_thu_9_128","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　應劭曰：「敷，陳也。各自奏陳其言，然後試之以官，考其功德也。」師古曰：「傅讀曰敷。」","sentenceOrder":128},
  {"id":"s_work_han_thu_9_129","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　師古曰：「言各久其職事也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_9_130","chapterId":"ch_work_han_thu_9","textTraditional":"三年春三月，詔曰：「蓋聞有功不賞，有罪不誅，雖唐虞猶不能以化天下。今膠東相成勞來不怠，〔一〕流民自占八萬餘口，〔二〕治有異等。〔三〕其秩成中二千石，賜爵關內侯。」","sentenceOrder":130},
  {"id":"s_work_han_thu_9_131","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「王成也。勞來者，言慰勉而招延之也。小雅鴻鴈之詩序曰『勞來還定安集之』。勞音盧到反。來音盧代反。」","sentenceOrder":131},
  {"id":"s_work_han_thu_9_132","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「占者，謂自隱度其戶口而著名籍也。占音之贍反。」","sentenceOrder":132},
  {"id":"s_work_han_thu_9_133","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「政治異於常等。」","sentenceOrder":133},
  {"id":"s_work_han_thu_9_134","chapterId":"ch_work_han_thu_9","textTraditional":"又曰：「鰥寡孤獨高年貧困之民，朕所憐也。前下詔假公田，貨種、食。〔一〕其加賜鰥寡孤獨高年帛。二千石嚴教吏謹視遇，毋令失職。」〔二〕","sentenceOrder":134},
  {"id":"s_work_han_thu_9_135","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「貸音吐戴反。」","sentenceOrder":135},
  {"id":"s_work_han_thu_9_136","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「職，常也。失職，謂失其常業也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_9_137","chapterId":"ch_work_han_thu_9","textTraditional":"令內郡國舉賢良方正可親民者。","sentenceOrder":137},
  {"id":"s_work_han_thu_9_138","chapterId":"ch_work_han_thu_9","textTraditional":"夏四月戊申，立皇太子，大赦天下。賜御史大夫爵關內侯，中二千石爵右庶長，〔一〕天下當為父後者爵一級。賜廣陵王黃金千斤，諸侯王十五人黃金各百斤，列侯在國者八十七人黃金各二十斤。","sentenceOrder":138},
  {"id":"s_work_han_thu_9_139","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　張晏曰：「自公孫弘後，丞相常封列侯，第二十等爵。故賜御史大夫爵關內侯，第十九等爵也。右庶長，第十一等爵也。」師古曰：「張說非也。此以立皇太子國之大慶，故特賜御史大夫及中二千石爵耳，非常制也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_9_140","chapterId":"ch_work_han_thu_9","textTraditional":"冬十月，詔曰：「乃者九月壬申地震，朕甚懼焉。有能箴朕過失，〔一〕及賢良方正直言極諫之士以匡朕之不逮，〔二〕毋諱有司。〔三〕朕既不德，不能附遠，是以邊境屯戍未息。今復飭兵重屯，久勞百姓，〔四〕非所以綏天下也。其罷車騎將軍、右將軍屯兵。」又詔曰：「池籞未御幸者，假與貧民。〔五〕郡國宮館，勿復修治。流民還歸者，假公田，貸種、食，〔六〕且勿算事。」〔七〕","sentenceOrder":140},
  {"id":"s_work_han_thu_9_141","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「箴，戒也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_9_142","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「匡，正也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_9_143","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　李奇曰：「諱，避也。雖有司在顯職，皆言其過，勿避之。」","sentenceOrder":143},
  {"id":"s_work_han_thu_9_144","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　師古曰：「飭讀與敕同。飭，整也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_9_145","chapterId":"ch_work_han_thu_9","textTraditional":"〔五〕　蘇林曰：「折竹以繩綿連禁禦，使人不得往來，律名為籞。」服虔曰：「籞在池水中作室，可用棲鳥，鳥入中則捕之。」應劭曰：「池者，陂池也。籞者，禁苑也。」臣瓚曰：「籞者，所以養鳥也。設為藩落，周覆其上，令鳥不得出，猶苑之畜獸，池之畜魚也。」師古曰：「蘇、應二說是。」","sentenceOrder":145},
  {"id":"s_work_han_thu_9_146","chapterId":"ch_work_han_thu_9","textTraditional":"〔六〕　師古曰：「貸音吐戴反。種，五穀種也，音之勇反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_9_147","chapterId":"ch_work_han_thu_9","textTraditional":"〔七〕　師古曰：「不出算賦及給徭役。」","sentenceOrder":147},
  {"id":"s_work_han_thu_9_148","chapterId":"ch_work_han_thu_9","textTraditional":"十一月，詔曰：「朕既不逮，導民不明，〔一〕反側晨興，念慮萬方，不忘元元。唯恐羞先帝聖德，〔二〕故並舉賢良方正以親萬姓，歷載臻茲，然而俗化闕焉。〔三〕傳曰：『孝弟也者，其為仁之本與！』〔四〕其令郡國舉孝弟有行義聞于鄉里者各一人。」","sentenceOrder":148},
  {"id":"s_work_han_thu_9_149","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「不逮者，意慮不及也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_9_150","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「羞謂忝辱也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_9_151","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　師古曰：「多歷年載，迄至于今。」","sentenceOrder":151},
  {"id":"s_work_han_thu_9_152","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　師古曰：「論語載有若之言。與讀曰予。」","sentenceOrder":152},
  {"id":"s_work_han_thu_9_153","chapterId":"ch_work_han_thu_9","textTraditional":"十二月，初置廷尉平四人，秩六百石。","sentenceOrder":153},
  {"id":"s_work_han_thu_9_154","chapterId":"ch_work_han_thu_9","textTraditional":"省文山郡，并蜀。〔一〕","sentenceOrder":154},
  {"id":"s_work_han_thu_9_155","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「以其縣道隸蜀郡。」","sentenceOrder":155},
  {"id":"s_work_han_thu_9_156","chapterId":"ch_work_han_thu_9","textTraditional":"四年春二月，封外祖母博平君，故酇侯蕭何曾孫建世為侯。","sentenceOrder":156},
  {"id":"s_work_han_thu_9_157","chapterId":"ch_work_han_thu_9","textTraditional":"詔曰：「導民以孝，則天下順。今百姓或遭衰絰凶災，〔一〕而吏繇事，使不得葬，〔二〕傷孝子之心，朕甚憐之。自今諸有大父母﹐父母喪者勿繇事，使得收斂送終，盡其子道。」","sentenceOrder":157},
  {"id":"s_work_han_thu_9_158","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「衰音千回反。」","sentenceOrder":158},
  {"id":"s_work_han_thu_9_159","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「繇讀曰徭。事謂役使之。」","sentenceOrder":159},
  {"id":"s_work_han_thu_9_160","chapterId":"ch_work_han_thu_9","textTraditional":"夏五月，詔曰：「父子之親，夫婦之道，天性也。雖有患禍，猶蒙死而存之。〔一〕誠愛結于心，仁厚之至也，豈能違之哉！自今子首匿父母，妻匿夫，孫匿大父母，皆勿坐。〔二〕其父母匿子，夫匿妻，大父母匿孫，罪殊死，皆上請廷尉以聞。」","sentenceOrder":160},
  {"id":"s_work_han_thu_9_161","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「蒙，冒也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_9_162","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「凡首匿者，言為謀首而藏匿罪人。」","sentenceOrder":162},
  {"id":"s_work_han_thu_9_163","chapterId":"ch_work_han_thu_9","textTraditional":"立廣川惠王孫文為廣川王。","sentenceOrder":163},
  {"id":"s_work_han_thu_9_164","chapterId":"ch_work_han_thu_9","textTraditional":"秋七月，大司馬霍禹謀反。詔曰：「乃者，東織室令史張赦〔一〕使魏郡豪李竟〔二〕報冠陽侯霍雲謀為大逆，〔三〕朕以大將軍故，抑而不揚，冀其自新。今大司馬博陸侯禹與母宣成侯夫人顯及從昆弟冠陽侯雲、樂平侯山、〔四〕諸姊妹婿度遼將軍范明友、長信少府鄧廣漢、中郎將任勝、騎都尉趙平、長安男子馮殷等〔五〕謀為大逆。顯前又使女侍醫淳于衍進藥殺共哀后，〔六〕謀毒太子，欲危宗廟。逆亂不道，咸（服）〔伏〕其辜。諸為霍氏所詿誤未發覺在吏者，皆赦除之。」八月己酉，皇后霍氏廢。","sentenceOrder":164},
  {"id":"s_work_han_thu_9_165","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　應劭曰：「舊時有東西織室，織作文繡郊廟之服。令史，其主者吏。」","sentenceOrder":165},
  {"id":"s_work_han_thu_9_166","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　文穎曰：「有權勢豪右大家。」","sentenceOrder":166},
  {"id":"s_work_han_thu_9_167","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　如淳曰：「報，白也。」師古曰：「此說非也。謂張赦因李竟傳言於霍雲與共謀反耳，非告白其罪也。赦既為織室令史，身在京師，不須令李竟發之。據霍禹傳，其事明矣。」","sentenceOrder":167},
  {"id":"s_work_han_thu_9_168","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　師古曰：「據霍光傳，雲、山皆去病之孫，則於禹為子行也。今此紀言從昆弟，蓋轉寫者脫子字耳。當言從昆弟子也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_9_169","chapterId":"ch_work_han_thu_9","textTraditional":"〔五〕　晉灼曰：「漢語字子都。」","sentenceOrder":169},
  {"id":"s_work_han_thu_9_170","chapterId":"ch_work_han_thu_9","textTraditional":"〔六〕　師古曰：「殺讀曰弒。共讀曰恭。」","sentenceOrder":170},
  {"id":"s_work_han_thu_9_171","chapterId":"ch_work_han_thu_9","textTraditional":"九月，詔曰：「朕惟百姓失職不贍，遣使者循行郡國問民所疾苦。〔一〕吏或營私煩擾，不顧厥咎，朕甚閔之。今年郡國頗被水災，已振貸。〔二〕鹽，民之食，而賈咸貴，〔三〕眾庶重困。〔四〕其減天下鹽賈。」","sentenceOrder":171},
  {"id":"s_work_han_thu_9_172","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「行音下更反。」","sentenceOrder":172},
  {"id":"s_work_han_thu_9_173","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「貸音吐戴反。」","sentenceOrder":173},
  {"id":"s_work_han_thu_9_174","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　師古曰：「賈讀曰價。其下亦同。」","sentenceOrder":174},
  {"id":"s_work_han_thu_9_175","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　師古曰：「更增其困也。重音直用反。」","sentenceOrder":175},
  {"id":"s_work_han_thu_9_176","chapterId":"ch_work_han_thu_9","textTraditional":"又曰：「令甲，死者不可生，〔一〕刑者不可息。〔二〕此先帝之所重，而吏未稱。〔三〕今繫者或以掠辜若飢寒瘐死獄中，〔四〕何用心逆人道也！朕甚痛之。其令郡國歲上繫囚以掠笞若瘐死者所坐名、縣、爵、里，〔五〕丞相御史課殿最以聞。」〔六〕","sentenceOrder":176},
  {"id":"s_work_han_thu_9_177","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　文穎曰：「蕭何承秦法所作為律令，律經是也。天子詔所增損，不在律上者為令。令甲者，前帝第一令也。」如淳曰：「令有先後，故有令甲、令乙、令丙。」師古曰：「如說是也。甲乙者，若今之第一、第二篇耳。」","sentenceOrder":177},
  {"id":"s_work_han_thu_9_178","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　李斐曰：「息，滅也。若黥劓者，雖欲改過，其創瘢不可復滅也。」師古曰：「息謂生長也，言劓、刖、臏、割之徙不可更生長，亦猶謂子為息耳。李說非也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_9_179","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　師古曰：「稱，副也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_9_180","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　蘇林曰：「瘐，病也。囚徒病，律名為瘐。」如淳曰：「律，囚以飢寒而死曰瘐。」師古曰：「瘐，病，是也。此言囚或以掠笞及飢寒及疾病而死。如說非矣。瘐音庾，字或作瘉，其音亦同。」","sentenceOrder":180},
  {"id":"s_work_han_thu_9_181","chapterId":"ch_work_han_thu_9","textTraditional":"〔五〕　師古曰：「名，其人名也。縣，所屬縣也。爵，其身之官爵也。里，所居邑里也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_9_182","chapterId":"ch_work_han_thu_9","textTraditional":"〔六〕　師古曰：「凡言殿最者：殿，後也，課居後也；最，凡要之首也，課居先也。殿音丁見反。」","sentenceOrder":182},
  {"id":"s_work_han_thu_9_183","chapterId":"ch_work_han_thu_9","textTraditional":"十二月，清河王年有罪，廢遷房陵。","sentenceOrder":183},
  {"id":"s_work_han_thu_9_184","chapterId":"ch_work_han_thu_9","textTraditional":"元康元年春，以杜東原上為初陵，更名杜縣為杜陵。徙丞相、將軍、列侯、吏二千石、訾百萬者杜陵。","sentenceOrder":184},
  {"id":"s_work_han_thu_9_185","chapterId":"ch_work_han_thu_9","textTraditional":"三月，詔曰：「乃者鳳皇集泰山、陳留，甘露降未央宮。朕未能章先帝休烈，〔一〕協寧百姓，承天順地，調序四時，獲蒙嘉瑞，賜茲祉福，夙夜兢兢，靡有驕色，內省匪解，永惟罔極。〔二〕書不云乎？『鳳皇來儀，庶（不）〔尹〕允諧。』〔三〕其赦天下徒，賜勤事吏中二千石以下至六百石爵，自中郎吏至五大夫，〔四〕佐史以上二級，民一級，女子百戶牛酒。加賜鰥寡孤獨、三老、孝弟力田帛。所振貸勿收。」","sentenceOrder":185},
  {"id":"s_work_han_thu_9_186","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「章，明也。休，美也。烈，業也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_9_187","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「省，視也。永，長也。惟，思也。罔，無也。極，中也。帝言內自視察，不敢惰怠，長思正道，恐無其中也。解讀曰懈。」","sentenceOrder":187},
  {"id":"s_work_han_thu_9_188","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　師古曰：「虞書益稷之篇曰：『簫韶九成，鳳皇來儀，擊石拊石，百獸率舞，庶尹允諧。』言奏樂之和，鳳皇以其容儀來下，百獸相率舞蹈。是乃眾官之長，信皆和輯，故神人交暢。」","sentenceOrder":188},
  {"id":"s_work_han_thu_9_189","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　師古曰：「賜中郎吏爵得至五大夫。自此以上，每為等級而高賜也。五大夫，第九爵也。一日二千石至五大夫，自此以下而差降。」","sentenceOrder":189},
  {"id":"s_work_han_thu_9_190","chapterId":"ch_work_han_thu_9","textTraditional":"夏五月，立皇考廟。益奉明園戶為奉明縣。〔一〕","sentenceOrder":190},
  {"id":"s_work_han_thu_9_191","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「奉明園即皇考史皇孫之所葬也，本名廣明，後追改也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_9_192","chapterId":"ch_work_han_thu_9","textTraditional":"復高皇帝功臣絳侯周勃等百三十六人家子孫，令奉祭祀，〔一〕世世勿絕。其毋嗣者，復其次。","sentenceOrder":192},
  {"id":"s_work_han_thu_9_193","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「復音方目反。次下亦同。」","sentenceOrder":193},
  {"id":"s_work_han_thu_9_194","chapterId":"ch_work_han_thu_9","textTraditional":"秋八月，詔曰：「朕不明六藝，鬱于大道，〔一〕是以陰陽風雨未時。其博舉吏民，厥身修正，通文學，明於先王之術，宣究其意者，各二人，〔二〕中二千石各一人。」","sentenceOrder":194},
  {"id":"s_work_han_thu_9_195","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　孟康曰：「鬱，不通也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_9_196","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「究，盡也。」","sentenceOrder":196},
  {"id":"s_work_han_thu_9_197","chapterId":"ch_work_han_thu_9","textTraditional":"冬，置建章衛尉。","sentenceOrder":197},
  {"id":"s_work_han_thu_9_198","chapterId":"ch_work_han_thu_9","textTraditional":"二年春正月，詔曰：「書云『文王作罰，刑茲無赦』，〔一〕今吏修身奉法，未有能稱朕意，朕甚愍焉。其赦天下，與士大夫厲精更始。」〔二〕","sentenceOrder":198},
  {"id":"s_work_han_thu_9_199","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「周書康誥之辭也。言文王作法，罰其有亂常違教者，則刑之無放釋也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_9_200","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　李斐曰：「今吏已修身奉法矣，但不能稱上意耳，故赦之。」師古曰：「言文王作罰，有犯之者，皆刑無赦，今我意有所閔，閔吏修身奉法矣，而未稱其任，故特赦之，與更始耳。李說非也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_9_201","chapterId":"ch_work_han_thu_9","textTraditional":"二月乙丑，立皇后王氏。〔一〕賜丞相以下至郎從官錢帛各有差。","sentenceOrder":201},
  {"id":"s_work_han_thu_9_202","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「王奉光女。」","sentenceOrder":202},
  {"id":"s_work_han_thu_9_203","chapterId":"ch_work_han_thu_9","textTraditional":"三月，以鳳皇甘露降集，賜天下吏爵二級，民一級，女子百戶牛酒，鰥寡孤獨高年帛。","sentenceOrder":203},
  {"id":"s_work_han_thu_9_204","chapterId":"ch_work_han_thu_9","textTraditional":"夏五月，詔曰：「獄者萬民之命，所以禁暴止邪，養育群生也。能使生者不怨，死者不恨，則可謂文吏矣。今則不然。用法或持巧心，析律貳端，深淺不平，〔一〕增辭飾非，以成其罪。奏不如實，上亦亡繇知。〔二〕此朕之不明，吏之不稱，四方黎民將何仰哉！二千石各察官屬，勿用此人。吏務平法。或擅興繇役，飾廚傳，稱過使客，〔三〕越職踰法，以取名譽，譬猶踐薄冰以待白日，豈不殆哉〔四〕！今天下頗被疾疫之災，朕甚愍之。其令郡國被災甚者，毋出今年租賦。」","sentenceOrder":204},
  {"id":"s_work_han_thu_9_205","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「析，分也。謂分破律條，妄生端緒，以出入人罪。」","sentenceOrder":205},
  {"id":"s_work_han_thu_9_206","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「上者，天子自謂也。繇讀與由同。」","sentenceOrder":206},
  {"id":"s_work_han_thu_9_207","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　韋昭曰：「廚謂飲食，傳謂傳舍。言修飾意氣，以稱過使而已。」師古曰：「使人及賓客來者，稱其意而遣之，令過去也。稱音尺孕反。過者，過度之過也。」","sentenceOrder":207},
  {"id":"s_work_han_thu_9_208","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　師古曰：「殆，危也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_9_209","chapterId":"ch_work_han_thu_9","textTraditional":"又曰：「聞古天子之名，難知而易諱也。今百姓多上書觸諱以犯罪者，朕甚憐之。其更諱詢。諸觸諱在令前者，赦之。」〔一〕","sentenceOrder":209},
  {"id":"s_work_han_thu_9_210","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「令謂今詔書。」","sentenceOrder":210},
  {"id":"s_work_han_thu_9_211","chapterId":"ch_work_han_thu_9","textTraditional":"冬，京兆尹趙廣漢有罪，要斬。","sentenceOrder":211},
  {"id":"s_work_han_thu_9_212","chapterId":"ch_work_han_thu_9","textTraditional":"三年春，以神爵數集泰山，賜諸侯王、丞相、將軍、列侯、二千石金，郎從官帛，各有差。賜天下吏爵二級，民一級，女子百戶牛酒，鰥寡孤獨高年帛。","sentenceOrder":212},
  {"id":"s_work_han_thu_9_213","chapterId":"ch_work_han_thu_9","textTraditional":"三月，詔曰：「蓋聞象有罪，舜封之。〔一〕骨肉之親粲而不殊。〔二〕其封故昌邑王賀為海昏侯。」","sentenceOrder":213},
  {"id":"s_work_han_thu_9_214","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　應劭曰：「象者，舜弟也，日以殺舜為事。舜為天子，猶封之於有鼻之國。」","sentenceOrder":214},
  {"id":"s_work_han_thu_9_215","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「粲，明也。殊，絕也。當明於仁恩不離絕也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_9_216","chapterId":"ch_work_han_thu_9","textTraditional":"又曰：「朕微眇時，御史大夫丙吉、中郎將史曾、史玄、長樂衛尉許舜、侍中光祿大夫許延壽皆與朕有舊恩。及故掖庭令張賀輔導朕躬，修文學經術，恩惠卓異，厥功茂焉。詩不云乎？『無德不報。』〔一〕封賀所子弟子侍中中郎將彭祖為陽都侯，〔二〕追賜賀諡曰陽都哀侯。吉、曾、玄、舜、延壽皆為列侯。故人下至郡邸獄復作〔三〕嘗有阿保之功，〔四〕皆受官祿田宅財物，各以恩深淺報之。」","sentenceOrder":216},
  {"id":"s_work_han_thu_9_217","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「大雅抑之詩也。言受人之德必有報也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_9_218","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　如淳曰：「賀，張安世兄，有一子早死，故以彭祖為子。」師古曰：「所子者，言養弟子以為子。」","sentenceOrder":218},
  {"id":"s_work_han_thu_9_219","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　師古曰：「謂胡組、趙徵卿之輩也。復音扶目反。」","sentenceOrder":219},
  {"id":"s_work_han_thu_9_220","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　臣瓚曰：「阿，倚；保，養也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_9_221","chapterId":"ch_work_han_thu_9","textTraditional":"夏六月，詔曰：「前年夏，神爵集雍。〔一〕今春，五色鳥以萬數飛過屬縣，〔二〕翱翔而舞，欲集未下。其令三輔毋得以春夏擿巢探卵，彈射飛鳥。〔三〕具為令。」","sentenceOrder":221},
  {"id":"s_work_han_thu_9_222","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　晉灼曰：「漢注大如鷃爵，黃喉，白頸，黑背，腹斑文也。」師古曰：「鷃音晏。」","sentenceOrder":222},
  {"id":"s_work_han_thu_9_223","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「三輔諸縣也。」","sentenceOrder":223},
  {"id":"s_work_han_thu_9_224","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　師古曰：「擿音佗狄反。射音食亦反。」","sentenceOrder":224},
  {"id":"s_work_han_thu_9_225","chapterId":"ch_work_han_thu_9","textTraditional":"立皇子欽為淮陽王。","sentenceOrder":225},
  {"id":"s_work_han_thu_9_226","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「誣告人及殺傷人皆如舊法，其餘則不論。」","sentenceOrder":226},
  {"id":"s_work_han_thu_9_227","chapterId":"ch_work_han_thu_9","textTraditional":"遣大中大夫彊等十二人循行天下，〔一〕存問鰥寡，覽觀風俗，察吏治得失，舉茂材異倫之士。","sentenceOrder":227},
  {"id":"s_work_han_thu_9_228","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「行音下更反。」","sentenceOrder":228},
  {"id":"s_work_han_thu_9_229","chapterId":"ch_work_han_thu_9","textTraditional":"二月，河東霍徵史等謀反，誅。","sentenceOrder":229},
  {"id":"s_work_han_thu_9_230","chapterId":"ch_work_han_thu_9","textTraditional":"三月，詔曰：「乃者，神爵五采以萬數集長樂、未央、北宮、高寢、甘泉泰畤殿中及上林苑。朕之不逮，寡于德厚，屢獲嘉祥，非朕之任。其賜天下吏爵二級，民一級，女子百戶牛酒。加賜三老、孝弟力田帛，人二匹，鰥寡孤獨各一匹。」","sentenceOrder":230},
  {"id":"s_work_han_thu_9_231","chapterId":"ch_work_han_thu_9","textTraditional":"秋八月，賜故右扶風尹翁歸子黃金百斤，以奉其祭祀。又賜功臣適後〔一〕黃金，人二十斤。","sentenceOrder":231},
  {"id":"s_work_han_thu_9_232","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「適讀曰嫡，承嗣者也。或子或孫，不拘後裔，故總言後也。」","sentenceOrder":232},
  {"id":"s_work_han_thu_9_233","chapterId":"ch_work_han_thu_9","textTraditional":"丙寅，大司馬衛將軍安世薨。","sentenceOrder":233},
  {"id":"s_work_han_thu_9_234","chapterId":"ch_work_han_thu_9","textTraditional":"比年豐，穀石五錢。〔一〕","sentenceOrder":234},
  {"id":"s_work_han_thu_9_235","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「比，頻也。」","sentenceOrder":235},
  {"id":"s_work_han_thu_9_236","chapterId":"ch_work_han_thu_9","textTraditional":"神爵元年〔一〕春正月，行幸甘泉，郊泰畤。三月，行幸河東，祠后土。詔曰：「朕承宗廟，戰戰栗栗，惟萬事統，未燭厥理。〔二〕乃元康四年嘉穀玄稷降于郡國，〔三〕神爵仍集，〔四〕金芝九莖產于函德殿銅池中，〔五〕九真獻奇獸，〔六〕南郡獲白虎威鳳為寶。〔七〕朕之不明，震于珍物，〔八〕飭躬齋精，祈為百姓。〔九〕東濟大河，天氣清靜，神魚舞河。幸萬歲宮，神爵翔集。〔一０〕朕之不德，懼不能任。其以五年為神爵元年。賜天下勤事吏爵二級，民一級，女子百戶牛酒，鰥寡孤獨高年帛。所振貸物勿收。行所過毋出田租。」","sentenceOrder":236},
  {"id":"s_work_han_thu_9_237","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　應劭曰：「前年神爵集于長樂宮，故改年。」","sentenceOrder":237},
  {"id":"s_work_han_thu_9_238","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「惟，思也。統，緒也。燭，照也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_9_239","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　服虔曰：「玄稷，黑粟也。」","sentenceOrder":239},
  {"id":"s_work_han_thu_9_240","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　師古曰：「仍，頻也。」","sentenceOrder":240},
  {"id":"s_work_han_thu_9_241","chapterId":"ch_work_han_thu_9","textTraditional":"〔五〕　服虔曰：「金芝，色像金也。」如淳曰：「函亦含也。銅池，承霤也。」晉灼曰：「以銅作池也。」師古曰：「函德，殿名也。銅池，承霤是也，以銅為之。函讀與含同。」","sentenceOrder":241},
  {"id":"s_work_han_thu_9_242","chapterId":"ch_work_han_thu_9","textTraditional":"〔六〕　蘇林曰：「白象也。」晉灼曰：「漢注駒形，（鱗）〔麟〕色，牛角，仁而愛人。」師古曰：「非白象也，晉說是矣。」","sentenceOrder":242},
  {"id":"s_work_han_thu_9_243","chapterId":"ch_work_han_thu_9","textTraditional":"〔七〕　服虔曰：「威鳳，鳥名也。」晉灼曰：「鳳之有威儀者也，與尚書『鳳皇來儀』同意。」師古曰：「晉說是。」","sentenceOrder":243},
  {"id":"s_work_han_thu_9_244","chapterId":"ch_work_han_thu_9","textTraditional":"〔八〕　服虔曰：「震，驚也。」蘇林曰：「震，動也。珍物，瑞應也。」師古曰：「蘇說是也。獲珍物而心感動也。」","sentenceOrder":244},
  {"id":"s_work_han_thu_9_245","chapterId":"ch_work_han_thu_9","textTraditional":"〔九〕　師古曰：「飭與敕同。為音于偽反。」","sentenceOrder":245},
  {"id":"s_work_han_thu_9_246","chapterId":"ch_work_han_thu_9","textTraditional":"〔一０〕服虔曰：「萬歲宮在東郡平陽縣，今有津。」晉灼曰：「黃圖汾陰有萬歲宮，是時幸河東。」師古曰：「晉說是。」","sentenceOrder":246},
  {"id":"s_work_han_thu_9_247","chapterId":"ch_work_han_thu_9","textTraditional":"西羌反，發三輔、中都官徒弛刑，〔一〕及應募佽飛射士、〔二〕羽林孤兒，〔三〕胡、越騎，三河、潁川、沛郡、淮陽、汝南材官，金城、隴西、天水、安定、北地、上郡騎士、羌騎，詣金城。夏四月，遣後將軍趙充國、彊弩將軍許延壽擊西羌。","sentenceOrder":247},
  {"id":"s_work_han_thu_9_248","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　李奇曰：「弛，廢也。謂若今徒解鉗釱赭衣，置任輸作也。」師古曰：「中都官，京師諸官府也。漢儀注長安中諸官獄三十六所。弛刑，李說是也。若今徒囚但不枷鎖而責保散役之耳。弛音式爾反。」","sentenceOrder":248},
  {"id":"s_work_han_thu_9_249","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　服虔曰：「周時度江，越人在船下負船，將覆之。佽飛入水殺之。漢因以材力名官。」如淳曰：「呂氏春秋荊有茲非，得寶劍於干將。度江中流，兩蛟繞舟。茲非拔寶劍赴江刺兩蛟殺之。荊王聞之，任以執圭。後世以為勇力之官。茲、佽音相近。」臣瓚曰：「本秦左弋官也，武帝改曰佽飛官，有一令九丞，在上林苑中結矰繳以弋鳧鴈，歲萬頭，以供祀宗廟。許慎曰『佽，便利也』。便利矰繳以弋鳧鴈，故曰佽飛。詩曰『抉拾既佽』者也。」師古曰：「取古勇力人以名官，熊渠之類是也。亦因取其便利輕疾若飛，故號佽飛。弋鳧鴈事，自使佽飛為之，非取飛鳥為名。瓚說失之。佽音次。」","sentenceOrder":249},
  {"id":"s_work_han_thu_9_250","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　應劭曰：「天有羽林大將軍之星。林，喻若林木之盛。羽，羽翼鷙擊之意。故以名武官焉。」如淳曰：「百官表取從軍死事者之子養羽林，官教以五兵，號曰羽林孤兒，少壯令從軍。漢儀注羽林從官七百人。」","sentenceOrder":250},
  {"id":"s_work_han_thu_9_251","chapterId":"ch_work_han_thu_9","textTraditional":"六月，有星孛于東方。","sentenceOrder":251},
  {"id":"s_work_han_thu_9_252","chapterId":"ch_work_han_thu_9","textTraditional":"即拜酒泉太守辛武賢為破羌將軍，〔一〕與兩將軍並進。〔二〕詔曰：「軍旅暴露，轉輸煩勞，其令諸侯王、列侯、蠻夷王侯君長當朝二年者，皆毋朝。」〔三〕","sentenceOrder":252},
  {"id":"s_work_han_thu_9_253","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「即，就也。就酒泉而拜之，不徵入。」","sentenceOrder":253},
  {"id":"s_work_han_thu_9_254","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「兩將軍，即趙充國、許延壽。」","sentenceOrder":254},
  {"id":"s_work_han_thu_9_255","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　師古曰：「朝來年之正月。」","sentenceOrder":255},
  {"id":"s_work_han_thu_9_256","chapterId":"ch_work_han_thu_9","textTraditional":"秋，賜故大司農朱邑子黃金百斤，以奉祭祀。後將軍充國言屯田之計，語在充國傳。","sentenceOrder":256},
  {"id":"s_work_han_thu_9_257","chapterId":"ch_work_han_thu_9","textTraditional":"二年春二月，詔曰：「乃者正月乙丑，鳳皇甘露降集京師，群鳥從以萬數。朕之不德，屢獲天福，祗事不怠，其赦天下。」","sentenceOrder":257},
  {"id":"s_work_han_thu_9_258","chapterId":"ch_work_han_thu_9","textTraditional":"夏五月，羌虜降服，斬其首惡大豪楊玉、酋非首。〔一〕置金城屬國以處降羌。","sentenceOrder":258},
  {"id":"s_work_han_thu_9_259","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　文穎曰：「羌胡名大帥為酋，如中國言魁。非首，其名也。」如淳曰：「酋音酒（暂缺F682）熟。」師古曰：「文說失矣。酋者，自其魁帥之稱，而此酋不當其義也。蓋首惡者，唱首為惡也。大豪者，魁帥也。楊玉及酋非皆人名，言斬此二人之首級耳。既已言大豪，不當重言酋。且趙充國傳又云酋非、楊玉首，此其明驗也。酋音才由反。」","sentenceOrder":259},
  {"id":"s_work_han_thu_9_260","chapterId":"ch_work_han_thu_9","textTraditional":"秋，匈奴日逐王先賢撣〔一〕將人眾萬餘來降。使都護西域騎都尉鄭吉迎日逐，破車師，皆封列侯。","sentenceOrder":260},
  {"id":"s_work_han_thu_9_261","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　鄭氏曰：「撣音纏束之纏。」晉灼曰：「音田。」師古曰：「鄭音是也。」","sentenceOrder":261},
  {"id":"s_work_han_thu_9_262","chapterId":"ch_work_han_thu_9","textTraditional":"九月，司隸校尉蓋寬饒有罪，下有司，自殺。","sentenceOrder":262},
  {"id":"s_work_han_thu_9_263","chapterId":"ch_work_han_thu_9","textTraditional":"匈奴單于遣名王奉獻，〔一〕賀正月，始和親。〔二〕","sentenceOrder":263},
  {"id":"s_work_han_thu_9_264","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「名王者，謂有大名，以別諸小王也。」","sentenceOrder":264},
  {"id":"s_work_han_thu_9_265","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「賀來歲之正月。」","sentenceOrder":265},
  {"id":"s_work_han_thu_9_266","chapterId":"ch_work_han_thu_9","textTraditional":"三年春，起樂游苑。〔一〕","sentenceOrder":266},
  {"id":"s_work_han_thu_9_267","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「三輔黃圖云在杜陵西北。又關中記云宣帝立廟於曲池之北，號樂游。案其處則今之所呼樂游廟者是也。其餘基尚可識焉。蓋本為苑，後因立廟乎？樂音來各反。」","sentenceOrder":267},
  {"id":"s_work_han_thu_9_268","chapterId":"ch_work_han_thu_9","textTraditional":"三月丙午，丞相相薨。〔一〕","sentenceOrder":268},
  {"id":"s_work_han_thu_9_269","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「魏相。」","sentenceOrder":269},
  {"id":"s_work_han_thu_9_270","chapterId":"ch_work_han_thu_9","textTraditional":"秋八月，詔曰：「吏不廉平則治道衰。今小吏皆勤事，而奉祿薄，〔一〕欲其毋侵漁百姓，難矣。〔二〕其益吏百石以下奉十五。」〔三〕","sentenceOrder":270},
  {"id":"s_work_han_thu_9_271","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「奉音扶用反。其下亦同。」","sentenceOrder":271},
  {"id":"s_work_han_thu_9_272","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　如淳曰：「漁，奪也，謂奪其利便也。」晉灼曰：「許慎云捕魚之字也。」師古曰：「漁者，若言漁獵也。晉說是也。」","sentenceOrder":272},
  {"id":"s_work_han_thu_9_273","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　如淳曰：「律，百石奉月六百。」韋昭曰：「若食一斛，則益五斗。」","sentenceOrder":273},
  {"id":"s_work_han_thu_9_274","chapterId":"ch_work_han_thu_9","textTraditional":"四年春二月，詔曰：「乃者鳳皇甘露降集京師，嘉瑞並見。修興泰一、五帝、后土之祠，祈為百姓蒙祉福。〔一〕鸞鳳萬舉，蜚覽翱翔，集止于旁。〔二〕齋戒之暮，神光顯著。薦鬯之夕，神光交錯。〔三〕或降于天，或登于地，或從四方來集于壇。上帝嘉嚮，海內承福。〔四〕其赦天下，賜民爵一級，女子百戶牛酒，鰥寡孤獨高年帛。」","sentenceOrder":274},
  {"id":"s_work_han_thu_9_275","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「為音于偽反。」","sentenceOrder":275},
  {"id":"s_work_han_thu_9_276","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「萬舉，猶言舉以萬數也。蜚，古飛字也。言鸞鳳飛翔，覽觀都邑也。」","sentenceOrder":276},
  {"id":"s_work_han_thu_9_277","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　師古曰：「鬯，香酒，所以祭神。」","sentenceOrder":277},
  {"id":"s_work_han_thu_9_278","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　師古曰：「嚮讀曰饗。」","sentenceOrder":278},
  {"id":"s_work_han_thu_9_279","chapterId":"ch_work_han_thu_9","textTraditional":"夏四月，潁川太守黃霸以治行尤異秩中二千石，〔一〕賜爵關內侯，黃金百斤。及潁川吏民有行義者爵，人二級，力田一級，貞婦順女帛。","sentenceOrder":279},
  {"id":"s_work_han_thu_9_280","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　如淳曰：「太守雖號二千石，有千石、八百石居者。有功德茂異乃得滿秩。霸得中二千石，九卿秩也。」晉灼曰：「此直謂二千石增秩為中二千石耳，不謂滿不滿也。」師古曰：「如說非也。霸舊已二千石矣，今增為中二千石，以寵異之。此與地節三年增膠東相王成秩其事同耳。漢制，秩二千石者一歲得一千四百四十石，實不滿二千石也，其云中二千石者，一歲得二千一百六十石。舉成數言之，故曰中二千石。中者，滿也。」","sentenceOrder":280},
  {"id":"s_work_han_thu_9_281","chapterId":"ch_work_han_thu_9","textTraditional":"令內郡國舉賢良可親民者各一人。","sentenceOrder":281},
  {"id":"s_work_han_thu_9_282","chapterId":"ch_work_han_thu_9","textTraditional":"五月，匈奴單于遣弟呼留若王勝之來朝。〔一〕","sentenceOrder":282},
  {"id":"s_work_han_thu_9_283","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「呼留若者，王之號也，勝之其人名。」","sentenceOrder":283},
  {"id":"s_work_han_thu_9_284","chapterId":"ch_work_han_thu_9","textTraditional":"冬十月，鳳皇十一集杜陵。","sentenceOrder":284},
  {"id":"s_work_han_thu_9_285","chapterId":"ch_work_han_thu_9","textTraditional":"十一月，河南太守嚴延年有罪，棄巿。","sentenceOrder":285},
  {"id":"s_work_han_thu_9_286","chapterId":"ch_work_han_thu_9","textTraditional":"十二月，鳳皇集上林。","sentenceOrder":286},
  {"id":"s_work_han_thu_9_287","chapterId":"ch_work_han_thu_9","textTraditional":"五鳳元年〔一〕春正月，行幸甘泉，郊泰畤。","sentenceOrder":287},
  {"id":"s_work_han_thu_9_288","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　應劭曰：「先者鳳皇五至，因以改元云。」","sentenceOrder":288},
  {"id":"s_work_han_thu_9_289","chapterId":"ch_work_han_thu_9","textTraditional":"皇太子冠。皇太后賜丞相、將軍、列侯、中二千石帛，人百匹，大夫人八十匹，〔夫人六十匹〕。又賜列侯嗣子爵五大夫，男子為父後者爵一級。","sentenceOrder":289},
  {"id":"s_work_han_thu_9_290","chapterId":"ch_work_han_thu_9","textTraditional":"夏，赦徒作杜陵者。","sentenceOrder":290},
  {"id":"s_work_han_thu_9_291","chapterId":"ch_work_han_thu_9","textTraditional":"冬十二月乙酉朔，日有蝕之。","sentenceOrder":291},
  {"id":"s_work_han_thu_9_292","chapterId":"ch_work_han_thu_9","textTraditional":"左馮翊韓延壽有罪，棄巿。","sentenceOrder":292},
  {"id":"s_work_han_thu_9_293","chapterId":"ch_work_han_thu_9","textTraditional":"二年春三月，行幸雍，祠五畤。","sentenceOrder":293},
  {"id":"s_work_han_thu_9_294","chapterId":"ch_work_han_thu_9","textTraditional":"夏四月己丑，大司馬車騎將軍增薨。〔一〕","sentenceOrder":294},
  {"id":"s_work_han_thu_9_295","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「韓增。」","sentenceOrder":295},
  {"id":"s_work_han_thu_9_296","chapterId":"ch_work_han_thu_9","textTraditional":"秋八月，詔曰：「夫婚姻之禮，人倫之大者也；酒食之會，所以行禮樂也。今郡國二千石或擅為苛禁，禁民嫁娶不得具酒食相賀召。由是廢鄉黨之禮，令民亡所樂，非所以導民也。詩不云乎？『民之失德，乾餱以愆。』〔一〕勿行苛政。」","sentenceOrder":296},
  {"id":"s_work_han_thu_9_297","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「小雅伐木之詩也。餱，食也。愆，過也。言人無恩德，不相飲食，則闕乾餱之事，為過惡也。乾音干。餱音侯。」","sentenceOrder":297},
  {"id":"s_work_han_thu_9_298","chapterId":"ch_work_han_thu_9","textTraditional":"冬十一月，匈奴呼〈辶欶〉累單于帥眾來降，〔一〕封為列侯。","sentenceOrder":298},
  {"id":"s_work_han_thu_9_299","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「〈辶欶〉，古速字。累音力追（切）〔反〕。」","sentenceOrder":299},
  {"id":"s_work_han_thu_9_300","chapterId":"ch_work_han_thu_9","textTraditional":"十二月，平通侯（陽）〔楊〕惲〔一〕坐前為光祿勳有罪，免為庶人。不悔過，怨望，大逆不道，要斬。","sentenceOrder":300},
  {"id":"s_work_han_thu_9_301","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「惲音於吻反。」","sentenceOrder":301},
  {"id":"s_work_han_thu_9_302","chapterId":"ch_work_han_thu_9","textTraditional":"三年春正月癸卯，丞相吉薨。〔一〕","sentenceOrder":302},
  {"id":"s_work_han_thu_9_303","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「丙吉也。」","sentenceOrder":303},
  {"id":"s_work_han_thu_9_304","chapterId":"ch_work_han_thu_9","textTraditional":"三月，行幸河東，祠后土。詔曰：「往者匈奴數為邊寇，百姓被其害。朕承至尊，未能綏定匈奴。虛閭權渠單于請求和親，病死。右賢王屠耆堂代立。骨肉大臣立虛閭權渠單于子為呼韓邪單于，擊殺屠耆堂。諸王並自立，分為五單于，更相攻擊，〔一〕死者以萬數，畜產大耗什八九，〔二〕人民飢餓，相燔燒以求食，〔三〕因大乖亂。單于閼氏〔四〕子孫昆弟及呼〈辶欶〉累單于、名王、右伊秩訾、且渠、當戶以下〔五〕將眾五萬餘人來降歸義。單于稱臣，使弟奉珍朝賀正月，北邊晏然，靡有兵革之事。朕飭躬齊戒，〔六〕郊上帝，祠后土，神光並見，或興于谷，燭燿齊宮，十有餘刻。〔七〕甘露降，神爵集。已詔有司告祠上帝、宗廟。三月辛丑，鸞鳳又集長樂宮東闕中樹上，〔八〕飛下止地，文章五色，留十餘刻，吏民並觀。朕之不敏，懼不能任，婁蒙嘉瑞，獲茲祉福。〔九〕書不云乎？『雖休勿休，祗事不怠。』〔一０〕公卿大夫其勗焉。〔一一〕減天下口錢。赦殊死以下。賜民爵一級，女子百戶牛酒。大酺五日。加賜鰥寡孤獨高年帛。」","sentenceOrder":304},
  {"id":"s_work_han_thu_9_305","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「更音工衡反。」","sentenceOrder":305},
  {"id":"s_work_han_thu_9_306","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「耗，損也。言十損其八九也。耗音呼到反。」","sentenceOrder":306},
  {"id":"s_work_han_thu_9_307","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　師古曰：「燔，焚也，音扶元反。」","sentenceOrder":307},
  {"id":"s_work_han_thu_9_308","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　服虔曰：「閼氏音焉支。」","sentenceOrder":308},
  {"id":"s_work_han_thu_9_309","chapterId":"ch_work_han_thu_9","textTraditional":"〔五〕　師古曰：「伊秩訾、且渠、當戶，皆匈奴官號也。訾音子移反。且音子余反。」","sentenceOrder":309},
  {"id":"s_work_han_thu_9_310","chapterId":"ch_work_han_thu_9","textTraditional":"〔六〕　師古曰：「飭與敕同。」","sentenceOrder":310},
  {"id":"s_work_han_thu_9_311","chapterId":"ch_work_han_thu_9","textTraditional":"〔七〕　師古曰：「燭亦照也。刻者，以漏言時也。」","sentenceOrder":311},
  {"id":"s_work_han_thu_9_312","chapterId":"ch_work_han_thu_9","textTraditional":"〔八〕　張晏曰：「門外闕內（行）〔衡〕馬之裏樹也。」","sentenceOrder":312},
  {"id":"s_work_han_thu_9_313","chapterId":"ch_work_han_thu_9","textTraditional":"〔九〕　師古曰：「婁，古屢字。」","sentenceOrder":313},
  {"id":"s_work_han_thu_9_314","chapterId":"ch_work_han_thu_9","textTraditional":"〔一０〕師古曰：「周書呂刑之辭。言雖見（裒）〔褒〕美，勿自以為有德美，當敬於事，無怠（墮）〔惰〕也。」","sentenceOrder":314},
  {"id":"s_work_han_thu_9_315","chapterId":"ch_work_han_thu_9","textTraditional":"〔一一〕師古曰：「勗，勉也。」","sentenceOrder":315},
  {"id":"s_work_han_thu_9_316","chapterId":"ch_work_han_thu_9","textTraditional":"置西河、北地屬國以處匈奴降者。","sentenceOrder":316},
  {"id":"s_work_han_thu_9_317","chapterId":"ch_work_han_thu_9","textTraditional":"四年春正月，廣陵王胥有罪，自殺。","sentenceOrder":317},
  {"id":"s_work_han_thu_9_318","chapterId":"ch_work_han_thu_9","textTraditional":"匈奴單于稱臣，遣弟谷蠡王入侍。〔一〕以邊塞亡寇，減戍卒什二。","sentenceOrder":318},
  {"id":"s_work_han_thu_9_319","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　服虔曰：「谷音鹿。」韋昭曰：「蠡音如麗反。」師古曰：「谷，服音是也。蠡音落奚反。」","sentenceOrder":319},
  {"id":"s_work_han_thu_9_320","chapterId":"ch_work_han_thu_9","textTraditional":"大司農中丞耿壽昌奏設常平倉，以給北邊，〔一〕省轉漕。賜爵關內侯。","sentenceOrder":320},
  {"id":"s_work_han_thu_9_321","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　應劭曰：「壽昌奏令邊郡穀賤時增賈而糴，穀貴時減賈而糶，名曰常平倉。見食貨志。」","sentenceOrder":321},
  {"id":"s_work_han_thu_9_322","chapterId":"ch_work_han_thu_9","textTraditional":"夏四月辛丑晦，日有蝕之。詔曰：「皇天見異，以戒朕躬，是朕之不逮，吏之不稱也。〔一〕以前使使者問民所疾苦，復遣丞相、御史掾二十四人循行天下，〔二〕舉冤獄，察擅為苛禁深刻不改者。」","sentenceOrder":322},
  {"id":"s_work_han_thu_9_323","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「稱，副也。」","sentenceOrder":323},
  {"id":"s_work_han_thu_9_324","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「行音下更反。」","sentenceOrder":324},
  {"id":"s_work_han_thu_9_325","chapterId":"ch_work_han_thu_9","textTraditional":"甘露元年春正月，行幸甘泉，郊泰畤。","sentenceOrder":325},
  {"id":"s_work_han_thu_9_326","chapterId":"ch_work_han_thu_9","textTraditional":"匈奴呼韓邪單于遣子右賢王銖婁渠堂入侍。〔一〕","sentenceOrder":326},
  {"id":"s_work_han_thu_9_327","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「銖音殊。婁音力于反。」","sentenceOrder":327},
  {"id":"s_work_han_thu_9_328","chapterId":"ch_work_han_thu_9","textTraditional":"二月丁巳，大司馬車騎將軍延壽薨。〔一〕","sentenceOrder":328},
  {"id":"s_work_han_thu_9_329","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　文穎曰：「許延壽。」","sentenceOrder":329},
  {"id":"s_work_han_thu_9_330","chapterId":"ch_work_han_thu_9","textTraditional":"夏四月，黃龍見新豐。","sentenceOrder":330},
  {"id":"s_work_han_thu_9_331","chapterId":"ch_work_han_thu_9","textTraditional":"丙申，太上皇廟火。甲辰，孝文廟火。上素服五日。","sentenceOrder":331},
  {"id":"s_work_han_thu_9_332","chapterId":"ch_work_han_thu_9","textTraditional":"冬，匈奴單于遣弟左賢王來朝賀。","sentenceOrder":332},
  {"id":"s_work_han_thu_9_333","chapterId":"ch_work_han_thu_9","textTraditional":"二年春正月，立皇子囂為定陶王。〔一〕","sentenceOrder":333},
  {"id":"s_work_han_thu_9_334","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「囂音敖。」","sentenceOrder":334},
  {"id":"s_work_han_thu_9_335","chapterId":"ch_work_han_thu_9","textTraditional":"詔曰：「乃者鳳皇甘露降集，黃龍登興，醴泉滂流，枯槁榮茂，〔一〕神光並見，咸受禎祥。〔二〕其赦天下。減民算三十。〔三〕賜諸侯王、丞相、將軍、列侯、中二千石金錢各有差。賜民爵一級，女子百戶牛酒，鰥寡孤獨高年帛。」","sentenceOrder":335},
  {"id":"s_work_han_thu_9_336","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「槁音口老反。」","sentenceOrder":336},
  {"id":"s_work_han_thu_9_337","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「禎，正也。祥，福也。禎音貞。」","sentenceOrder":337},
  {"id":"s_work_han_thu_9_338","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　師古曰：「一算減錢三十也。」","sentenceOrder":338},
  {"id":"s_work_han_thu_9_339","chapterId":"ch_work_han_thu_9","textTraditional":"夏四月，遣護軍都尉祿將兵擊珠崖。","sentenceOrder":339},
  {"id":"s_work_han_thu_9_340","chapterId":"ch_work_han_thu_9","textTraditional":"秋九月，立皇子宇為東平王。","sentenceOrder":340},
  {"id":"s_work_han_thu_9_341","chapterId":"ch_work_han_thu_9","textTraditional":"冬十二月，行幸萯陽宮〔一〕屬玉觀。〔二〕","sentenceOrder":341},
  {"id":"s_work_han_thu_9_342","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　應劭曰：「宮在鄠，秦文王所起。」伏儼曰：「在扶風。」李斐曰：「萯音倍。」師古曰：「應說、李音是也。」","sentenceOrder":342},
  {"id":"s_work_han_thu_9_343","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　服虔曰：「以玉飾，因名焉，在扶風。」李奇曰：「屬玉音鸑鷟。其上有此鳥，因以為名。」晉灼曰：「屬玉，水鳥，似鵁鶄，以名觀也。」師古曰：「晉說是也。屬音之欲反。」","sentenceOrder":343},
  {"id":"s_work_han_thu_9_344","chapterId":"ch_work_han_thu_9","textTraditional":"匈奴呼韓邪單于款五原塞，〔一〕願奉國珍朝三年正月。〔一〕詔有司議。咸曰：「聖王之制，施德行禮，先京師而後諸夏，先諸夏而後夷狄。詩云：『率禮不越，遂視既發。相土烈烈，海外有〈雀戈〉。』〔三〕陛下聖德，充塞天地，光被四表。〔四〕匈奴單于鄉風慕義，〔五〕舉國同心，奉珍朝賀，自古未之有也。單于非正朔所加，王者所客也，禮儀宜如諸侯王，稱臣昧死再拜，位次諸侯王下。」詔曰：「蓋聞五帝三王，禮所不施，不及以政。〔六〕今匈奴單于稱北藩臣，朝正月，朕之不逮，德不能弘覆。其以客禮待之，位在諸侯王上。」","sentenceOrder":344},
  {"id":"s_work_han_thu_9_345","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「款，叩也。」","sentenceOrder":345},
  {"id":"s_work_han_thu_9_346","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「欲於甘露三年正月行朝禮。」","sentenceOrder":346},
  {"id":"s_work_han_thu_9_347","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　文穎曰：「遂，遍也。發，行也。言契能使其民率禮不越法度，遍承視其教令奉順而行也。相土，契孫也。烈烈，威也。〈雀戈〉，整齊也。威武之盛烈烈然，四海之外率服整齊也。」師古曰：「此商頌長發之詩。」","sentenceOrder":347},
  {"id":"s_work_han_thu_9_348","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　師古曰：「四表，四方之外也。」","sentenceOrder":348},
  {"id":"s_work_han_thu_9_349","chapterId":"ch_work_han_thu_9","textTraditional":"〔五〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":349},
  {"id":"s_work_han_thu_9_350","chapterId":"ch_work_han_thu_9","textTraditional":"〔六〕　師古曰：「言荒外之人非禮所設者，政刑亦不及。」","sentenceOrder":350},
  {"id":"s_work_han_thu_9_351","chapterId":"ch_work_han_thu_9","textTraditional":"三年春正月，行幸甘泉，郊泰畤。","sentenceOrder":351},
  {"id":"s_work_han_thu_9_352","chapterId":"ch_work_han_thu_9","textTraditional":"匈奴呼韓邪單于稽侯〈犭冊〉來朝，〔一〕贊謁稱藩臣而不名。賜以璽綬、冠帶、衣裳、安車、駟馬、黃金、錦繡、繒絮。使有司道單于〔二〕先行就邸長安，宿長平。上自甘泉宿池陽宮。上登長平阪，〔三〕詔單于毋謁。〔四〕其左右當戶之群皆列觀，〔五〕蠻夷君長王侯迎者數萬人，夾道陳。上登渭橋，咸稱萬歲。單于就邸。置酒建章宮，饗賜單于，觀以珍寶。〔六〕二月，單于罷歸。（之）〔遣〕長樂衛尉高昌侯忠、〔七〕車騎都尉昌、〔八〕騎都尉虎〔九〕將萬六千騎送單于。單于居幕南，保光祿城。〔一０〕詔北邊振穀食。郅支單于遠遁，〔一一〕匈奴遂定。","sentenceOrder":352},
  {"id":"s_work_han_thu_9_353","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　應劭曰：「〈犭冊〉音若訕。」李奇曰：「〈犭冊〉音山。」師古曰：「稽音古奚反。〈犭冊〉音刪，又音先安反。」","sentenceOrder":353},
  {"id":"s_work_han_thu_9_354","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「道讀曰導。導，引也。」","sentenceOrder":354},
  {"id":"s_work_han_thu_9_355","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　如淳曰：「阪名也，在池陽南。上原之阪有長平觀，去長安五十里。」師古曰：「涇水之南原，即今所謂眭城阪也。」","sentenceOrder":355},
  {"id":"s_work_han_thu_9_356","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　師古曰：「不拜見也。」","sentenceOrder":356},
  {"id":"s_work_han_thu_9_357","chapterId":"ch_work_han_thu_9","textTraditional":"〔五〕　孟康曰：「左右當戶，匈奴官名。」","sentenceOrder":357},
  {"id":"s_work_han_thu_9_358","chapterId":"ch_work_han_thu_9","textTraditional":"〔六〕　師古曰：「觀，示也。」","sentenceOrder":358},
  {"id":"s_work_han_thu_9_359","chapterId":"ch_work_han_thu_9","textTraditional":"〔七〕　晉灼曰：「功臣表董忠。」","sentenceOrder":359},
  {"id":"s_work_han_thu_9_360","chapterId":"ch_work_han_thu_9","textTraditional":"〔八〕　晉灼曰：「韓昌。」","sentenceOrder":360},
  {"id":"s_work_han_thu_9_361","chapterId":"ch_work_han_thu_9","textTraditional":"〔九〕　文穎曰：「不（異）〔知〕姓。」晉灼曰：「百官表唯記三輔、郡以上。若此皆不見姓，無從知之。」","sentenceOrder":361},
  {"id":"s_work_han_thu_9_362","chapterId":"ch_work_han_thu_9","textTraditional":"〔一０〕孟康曰：「前光祿徐自為所築城。」","sentenceOrder":362},
  {"id":"s_work_han_thu_9_363","chapterId":"ch_work_han_thu_9","textTraditional":"〔一一〕師古曰：「郅音質。」","sentenceOrder":363},
  {"id":"s_work_han_thu_9_364","chapterId":"ch_work_han_thu_9","textTraditional":"詔曰：「乃者鳳皇集新蔡，群鳥四面行列，皆鄉鳳皇立，以萬數。〔一〕其賜汝南太守帛百匹，新蔡長吏、三老、孝弟力田、鰥寡孤獨各有差。賜民爵二級。毋出今年租。」","sentenceOrder":364},
  {"id":"s_work_han_thu_9_365","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「行音胡郎反。鄉讀曰嚮。」","sentenceOrder":365},
  {"id":"s_work_han_thu_9_366","chapterId":"ch_work_han_thu_9","textTraditional":"三月己丑，丞相霸薨。〔一〕","sentenceOrder":366},
  {"id":"s_work_han_thu_9_367","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　文穎曰：「黃霸。」","sentenceOrder":367},
  {"id":"s_work_han_thu_9_368","chapterId":"ch_work_han_thu_9","textTraditional":"詔諸儒講五經同異，太子太傅蕭望之等平奏其議，上親稱制臨決焉。乃立梁丘易、大小夏侯尚書、穀梁春秋博士。","sentenceOrder":368},
  {"id":"s_work_han_thu_9_369","chapterId":"ch_work_han_thu_9","textTraditional":"冬，烏孫公主來歸。〔一〕","sentenceOrder":369},
  {"id":"s_work_han_thu_9_370","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　應劭曰：「楚王女解憂。」","sentenceOrder":370},
  {"id":"s_work_han_thu_9_371","chapterId":"ch_work_han_thu_9","textTraditional":"四年夏，廣川王海陽有罪，廢遷房陵。","sentenceOrder":371},
  {"id":"s_work_han_thu_9_372","chapterId":"ch_work_han_thu_9","textTraditional":"冬十月丁卯，未央宮宣室閣火。","sentenceOrder":372},
  {"id":"s_work_han_thu_9_373","chapterId":"ch_work_han_thu_9","textTraditional":"黃龍元年〔一〕春正月，行幸甘泉，郊泰畤。","sentenceOrder":373},
  {"id":"s_work_han_thu_9_374","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　應劭曰：「先是黃龍見新豐，因以冠元焉。」師古曰：「漢注云此年二月黃龍見廣漢郡，故改年。然則應說非也。見新豐者於此五載矣。」","sentenceOrder":374},
  {"id":"s_work_han_thu_9_375","chapterId":"ch_work_han_thu_9","textTraditional":"匈奴呼韓邪單于來朝，禮賜如初。二月，單于歸國。","sentenceOrder":375},
  {"id":"s_work_han_thu_9_376","chapterId":"ch_work_han_thu_9","textTraditional":"詔曰：「蓋聞上古之治，君臣同心，舉措曲直，各得其所。〔一〕是以上下和洽，海內康平，其德弗可及已。〔二〕朕既不明，數申詔公卿大夫務行寬大，〔三〕順民所疾苦，〔四〕將欲配三王之隆，明先帝之德也。今吏或以不禁姦邪為寬大，縱釋有罪為不苛，或以酷惡為賢，皆失其中。〔五〕奉詔宣化如此，豈不繆哉！方今天下少事，繇役省減，兵革不動，而民多貧，盜賊不止，其咎安在？上計簿，具文而已，〔六〕務為欺謾，以避其課。〔七〕三公不以為意，朕將何任？〔八〕諸請詔省卒徒自給者皆止。〔九〕御史察計簿，疑非實者，按之，使真偽毋相亂。」","sentenceOrder":376},
  {"id":"s_work_han_thu_9_377","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「措，置也，音千故反。」","sentenceOrder":377},
  {"id":"s_work_han_thu_9_378","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「已，語終辭。」","sentenceOrder":378},
  {"id":"s_work_han_thu_9_379","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　師古曰：「申，束也，謂約束之。」","sentenceOrder":379},
  {"id":"s_work_han_thu_9_380","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　師古曰：「知所疾苦，則順其意也。」","sentenceOrder":380},
  {"id":"s_work_han_thu_9_381","chapterId":"ch_work_han_thu_9","textTraditional":"〔五〕　師古曰：「中音竹仲反。」","sentenceOrder":381},
  {"id":"s_work_han_thu_9_382","chapterId":"ch_work_han_thu_9","textTraditional":"〔六〕　師古曰：「雖有其文，而實不副也。簿音步戶反。其下亦同。」","sentenceOrder":382},
  {"id":"s_work_han_thu_9_383","chapterId":"ch_work_han_thu_9","textTraditional":"〔七〕　師古曰：「謾，誑言也，音慢，又音莫連反。」","sentenceOrder":383},
  {"id":"s_work_han_thu_9_384","chapterId":"ch_work_han_thu_9","textTraditional":"〔八〕　師古曰：「言無所委任。」","sentenceOrder":384},
  {"id":"s_work_han_thu_9_385","chapterId":"ch_work_han_thu_9","textTraditional":"〔九〕　應劭曰：「時有請云，詔使出者省卒徒，以其直自給，不復取稟假。雖有進入於官，非舊章也，故絕之。」張晏曰：「先是武帝以用度不足，宜有以益官者。或奉使，求不受奉祿，自省其徒眾，以取其稟者或自給。於是姦吏緣以為利，所得多於本祿，故絕之。」如淳曰：「是時有所省卒徒，而群臣有請之以自給官府者。先時聽與之，今更悔之，不復聽也。」師古曰：「應、張二說是也。」","sentenceOrder":385},
  {"id":"s_work_han_thu_9_386","chapterId":"ch_work_han_thu_9","textTraditional":"三月，有星孛于王良、閣道，入紫宮。〔一〕","sentenceOrder":386},
  {"id":"s_work_han_thu_9_387","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　蘇林曰：「皆星名。」","sentenceOrder":387},
  {"id":"s_work_han_thu_9_388","chapterId":"ch_work_han_thu_9","textTraditional":"夏四月，詔曰：「舉廉吏，誠欲得其真也。吏六百石位大夫，有罪先請，秩祿上通，足以效其賢材，自今以來毋得舉。」〔一〕","sentenceOrder":388},
  {"id":"s_work_han_thu_9_389","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　韋昭曰：「吏六百石者不得復舉為廉吏也。」","sentenceOrder":389},
  {"id":"s_work_han_thu_9_390","chapterId":"ch_work_han_thu_9","textTraditional":"冬十二月甲戌，帝崩于未央宮。〔一〕癸巳，尊皇太后曰太皇太后。〔二〕","sentenceOrder":390},
  {"id":"s_work_han_thu_9_391","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　臣瓚曰：「帝年十八即位，即位二十五年，壽四十（八）〔三〕。」","sentenceOrder":391},
  {"id":"s_work_han_thu_9_392","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「於此已書尊太皇太后，而元紀之首又重書之。然尊太皇太后及皇太后宜同一時，則元紀為是，而此紀誤重之。」","sentenceOrder":392},
  {"id":"s_work_han_thu_9_393","chapterId":"ch_work_han_thu_9","textTraditional":"贊曰：孝宣之治，信賞必罰，〔一〕綜核名實，政事文學法理之士咸精其能，至于技巧工匠器械，自元、成間鮮能及之，〔二〕亦足以知吏稱其職，民安其業也。遭值匈奴乖亂，推亡固存，〔三〕信威北夷，〔四〕單于慕義，稽首稱藩。功光祖宗，業垂後嗣，可謂中興，侔德殷宗、周宣矣。〔五〕","sentenceOrder":393},
  {"id":"s_work_han_thu_9_394","chapterId":"ch_work_han_thu_9","textTraditional":"〔一〕　師古曰：「有功必賞，有罪必罰。」","sentenceOrder":394},
  {"id":"s_work_han_thu_9_395","chapterId":"ch_work_han_thu_9","textTraditional":"〔二〕　師古曰：「械者，器之總名也。一曰有盛為械，無盛為器。鮮，少也，言少有能及之者。鮮音先踐反。」","sentenceOrder":395},
  {"id":"s_work_han_thu_9_396","chapterId":"ch_work_han_thu_9","textTraditional":"〔三〕　李奇曰：「推亡者，若紂為無道，天下苦之，有滅亡之形，周武遂推而弊之。固存者，譬如鄰國以道涖民，上下一心，勢必能存，因就而堅固之。今匈奴內自奮爭有事，故宣帝能朝呼韓邪而固存之，走郅支單于使遠遁，是謂推亡也。」師古曰：「尚書仲虺之誥曰『推亡固存，邦乃其昌』。言有亡道者則推而滅之，有存道者則輔而固之。王者如此，國乃昌盛，故此贊引之。」","sentenceOrder":396},
  {"id":"s_work_han_thu_9_397","chapterId":"ch_work_han_thu_9","textTraditional":"〔四〕　師古曰：「信讀為申，古通用字。一說恩信及威並著北夷。」","sentenceOrder":397},
  {"id":"s_work_han_thu_9_398","chapterId":"ch_work_han_thu_9","textTraditional":"〔五〕　師古曰：「侔等殷之高宗及周宣王也。」","sentenceOrder":398},
  {"id":"s_work_han_thu_9_399","chapterId":"ch_work_han_thu_9","textTraditional":"校勘記","sentenceOrder":399},
  {"id":"s_work_han_thu_9_400","chapterId":"ch_work_han_thu_9","textTraditional":"二三七頁　四行　亦以（自是）〔是自〕怪。　景祐、殿、局本都作「是自」。","sentenceOrder":400},
  {"id":"s_work_han_thu_9_401","chapterId":"ch_work_han_thu_9","textTraditional":"二四一頁一二行　宋（踦）〔畸〕也。　殿本作「畸」。　王先謙說作「畸」是。","sentenceOrder":401},
  {"id":"s_work_han_thu_9_402","chapterId":"ch_work_han_thu_9","textTraditional":"二四一頁一七行　成帝（侍）〔時〕，　景祐、殿本「侍」都作「時」。","sentenceOrder":402},
  {"id":"s_work_han_thu_9_403","chapterId":"ch_work_han_thu_9","textTraditional":"二四七頁一五行　〔自丞相〕以下各奉職奏事，　景祐、殿本都有「自丞相」三字，通鑑同。","sentenceOrder":403},
  {"id":"s_work_han_thu_9_404","chapterId":"ch_work_han_thu_9","textTraditional":"二五一頁一四行　咸（服）〔伏〕其辜。　景祐、殿本都作「伏」。","sentenceOrder":404},
  {"id":"s_work_han_thu_9_405","chapterId":"ch_work_han_thu_9","textTraditional":"二五四頁　二行　庶（不）〔尹〕允諧。　景祐、汲古、殿、局本都作「尹」。","sentenceOrder":405},
  {"id":"s_work_han_thu_9_406","chapterId":"ch_work_han_thu_9","textTraditional":"二六０頁　七行　（鱗）〔麟〕色，　景祐、殿本都作「麟」。王先謙說作「麟」是。","sentenceOrder":406},
  {"id":"s_work_han_thu_9_407","chapterId":"ch_work_han_thu_9","textTraditional":"二六五頁　二行　大夫人八十匹，〔夫人六十匹〕。　景祐、殿本有此五字。","sentenceOrder":407},
  {"id":"s_work_han_thu_9_408","chapterId":"ch_work_han_thu_9","textTraditional":"二六六頁　三行　平通侯（陽）〔楊〕惲　景祐本作「揚」。殿、局本都作「楊」。王先謙說作「楊」是。","sentenceOrder":408},
  {"id":"s_work_han_thu_9_409","chapterId":"ch_work_han_thu_9","textTraditional":"二六七頁一二行　（行）〔衡〕馬之裏樹也。　景祐、殿本都作「衡」。","sentenceOrder":409},
  {"id":"s_work_han_thu_9_410","chapterId":"ch_work_han_thu_9","textTraditional":"二六七頁一四行　言雖見（裒）〔褒〕美，無怠（墮）〔惰〕也。　殿本作「褒」作「惰」。王先謙說作「褒」「惰」是。","sentenceOrder":410},
  {"id":"s_work_han_thu_9_411","chapterId":"ch_work_han_thu_9","textTraditional":"二七一頁　八行　（之）〔遣〕長樂衛尉高昌侯忠、　景祐、殿本都作「遣」。錢大昭說當作「遣」。","sentenceOrder":411},
  {"id":"s_work_han_thu_9_412","chapterId":"ch_work_han_thu_9","textTraditional":"二七二頁　三行　不（異）〔知〕姓。　景祐、殿、局本都作「知」。　王先謙說作「知」是。","sentenceOrder":412},
  {"id":"s_work_han_thu_9_413","chapterId":"ch_work_han_thu_9","textTraditional":"二七四頁一六行　壽四十（八）〔三〕。　景祐、殿本都作「三」，通鑑同。王鳴盛說「八」字誤。","sentenceOrder":413},
  {"id":"s_work_han_thu_10_1","chapterId":"ch_work_han_thu_10","textTraditional":"孝元皇帝，〔一〕宣帝太子也。母曰共哀許皇后，〔二〕宣帝微時生民間。年二歲，宣帝即位。八歲，立為太子。〔三〕壯大，柔仁好儒。見宣帝所用多文法吏，以刑名繩下，〔四〕大臣楊惲、（盍）〔蓋〕寬饒等坐刺譏辭語為罪而誅，〔五〕嘗侍燕從容言：〔六〕「陛下持刑太深，宜用儒生。」宣帝作色曰：〔七〕「漢家自有制度，本以霸王道雜之，奈何純（住）〔任〕德教，用周政乎！〔八〕且俗儒不達時宜，好是古非今，使人眩於名實，〔九〕不知所守，何足委任！」乃歎曰：「亂我家者，太子也！」繇是疏太子而愛淮陽王〔一０〕，曰：「淮陽王明察好法，宜為吾子。」而王母張婕妤尤幸。上有意欲用淮陽王代太子，然以少依許氏，俱從微起，故終不背焉。","sentenceOrder":1},
  {"id":"s_work_han_thu_10_2","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　荀悅曰：「諱奭之字曰盛。」應劭曰：「諡法『行義悅民曰元』。」師古曰：「奭音式亦反。」","sentenceOrder":2},
  {"id":"s_work_han_thu_10_3","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　張晏曰：「禮，婦人從夫諡。閔其見殺，故兼二諡。」師古曰：「共讀曰恭。」","sentenceOrder":3},
  {"id":"s_work_han_thu_10_4","chapterId":"ch_work_han_thu_10","textTraditional":"〔三〕　師古曰：「宣帝即位之明年改元曰本始。本始凡四年而改元曰地節。地節三年立皇太子。若初即位年二歲，則立為太子時年九歲矣。又宣帝以元平元年七月即位，而外戚傳云許后生元帝數月，宣帝立為帝。是則即位時太子未必二歲也。參校前後眾文，此紀進退為錯。」","sentenceOrder":4},
  {"id":"s_work_han_thu_10_5","chapterId":"ch_work_han_thu_10","textTraditional":"〔四〕　晉灼曰：「刑，刑家；名，名家也。太史公曰：『法家嚴而少恩，名家儉而善失真。』」師古曰：「晉說非也。劉向別錄云申子學號刑名。刑名者，以名責實，尊君卑臣，崇上抑下。宣帝好觀其君臣篇。繩謂彈治之耳。」","sentenceOrder":5},
  {"id":"s_work_han_thu_10_6","chapterId":"ch_work_han_thu_10","textTraditional":"〔五〕　師古曰：「惲音於吻反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_10_7","chapterId":"ch_work_han_thu_10","textTraditional":"〔六〕　師古曰：「從音千容反。」","sentenceOrder":7},
  {"id":"s_work_han_thu_10_8","chapterId":"ch_work_han_thu_10","textTraditional":"〔七〕　師古曰：「作，動也。意怒故動色。」","sentenceOrder":8},
  {"id":"s_work_han_thu_10_9","chapterId":"ch_work_han_thu_10","textTraditional":"〔八〕　師古曰：「姬周之政。」","sentenceOrder":9},
  {"id":"s_work_han_thu_10_10","chapterId":"ch_work_han_thu_10","textTraditional":"〔九〕　師古曰：「眩，亂視也，音胡眄反。」","sentenceOrder":10},
  {"id":"s_work_han_thu_10_11","chapterId":"ch_work_han_thu_10","textTraditional":"〔一０〕師古曰：「繇讀與由同。」","sentenceOrder":11},
  {"id":"s_work_han_thu_10_12","chapterId":"ch_work_han_thu_10","textTraditional":"黃龍元年十二月，宣帝崩。癸巳，太子即皇帝位，謁高廟。尊皇太后曰太皇太后，〔一〕皇后曰皇太后。〔二〕","sentenceOrder":12},
  {"id":"s_work_han_thu_10_13","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　蘇林曰：「上官后。」","sentenceOrder":13},
  {"id":"s_work_han_thu_10_14","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　文穎曰：「邛成王皇后，母養元帝者也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_10_15","chapterId":"ch_work_han_thu_10","textTraditional":"初元元年春正月辛丑，孝宣皇帝葬杜陵。〔一〕賜諸侯王、公主、列侯黃金，吏二千石以下錢帛，各有差。大赦天下。三月，封皇太后兄侍中中郎將王舜為安平侯。丙午，立皇后王氏。以三輔、太常、郡國公田及苑可省者振業貧民，〔二〕貲不滿千錢者賦貸種、食〔三〕。封外祖父平恩戴侯同產弟子中常侍許嘉為平恩侯，奉戴侯後〔四〕。","sentenceOrder":15},
  {"id":"s_work_han_thu_10_16","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　臣瓚曰：「自崩至葬凡二十八日。杜陵在長安南五十里也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_10_17","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　師古曰：「振起之，令有作業。」","sentenceOrder":17},
  {"id":"s_work_han_thu_10_18","chapterId":"ch_work_han_thu_10","textTraditional":"〔三〕　師古曰：「賦，給與之也。貸，假也。貸音土戴反。種音之勇反。」","sentenceOrder":18},
  {"id":"s_work_han_thu_10_19","chapterId":"ch_work_han_thu_10","textTraditional":"〔四〕　文穎曰：「戴侯，許廣漢。」","sentenceOrder":19},
  {"id":"s_work_han_thu_10_20","chapterId":"ch_work_han_thu_10","textTraditional":"夏四月，詔曰：「朕承先帝之聖緒，獲奉宗廟，戰戰兢兢。間者地數動而未靜，懼於天地之戒，不知所繇。〔一〕方田作時，朕憂蒸庶之失業，〔二〕臨遣光祿大夫褒等十二人〔三〕循行天下，〔四〕存問耆老鰥寡孤獨困乏失職之民，〔五〕延登賢俊，招顯側陋，因覽風俗之化。相守二千石誠能正躬勞力，〔六〕宣明教化，以親萬姓，則六合之內和親，庶幾虖無憂矣。書不云乎？『股肱良哉，庶事康哉！』〔七〕布告天下，使明知朕意。」又曰：「關東今年穀不登，民多困乏。其令郡國被災害甚者毋出租賦。江海陂湖園池屬少府者以假貧民，〔八〕勿租賦。賜宗室有屬籍者馬一匹至二駟，〔九〕三老、孝者帛五匹，弟者、力田三匹，鰥寡孤獨二匹，吏民五十戶牛酒。」〔一０〕","sentenceOrder":20},
  {"id":"s_work_han_thu_10_21","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「繇與由同。」","sentenceOrder":21},
  {"id":"s_work_han_thu_10_22","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　師古曰：「蒸，眾也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_10_23","chapterId":"ch_work_han_thu_10","textTraditional":"〔三〕　應劭曰：「自臨面約敕乃遣之。」","sentenceOrder":23},
  {"id":"s_work_han_thu_10_24","chapterId":"ch_work_han_thu_10","textTraditional":"〔四〕　師古曰：「行音下更反。」","sentenceOrder":24},
  {"id":"s_work_han_thu_10_25","chapterId":"ch_work_han_thu_10","textTraditional":"〔五〕　師古曰：「失職，失其常業。」","sentenceOrder":25},
  {"id":"s_work_han_thu_10_26","chapterId":"ch_work_han_thu_10","textTraditional":"〔六〕　師古曰：「相者，諸侯王相也。守，郡守也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_10_27","chapterId":"ch_work_han_thu_10","textTraditional":"〔七〕　師古曰：「虞書益稷之辭也。言君能任賢，股肱之臣皆得良善，則眾事安寧。」","sentenceOrder":27},
  {"id":"s_work_han_thu_10_28","chapterId":"ch_work_han_thu_10","textTraditional":"〔八〕　師古曰：「湖，深水。」","sentenceOrder":28},
  {"id":"s_work_han_thu_10_29","chapterId":"ch_work_han_thu_10","textTraditional":"〔九〕　師古曰：「二駟，八匹。」","sentenceOrder":29},
  {"id":"s_work_han_thu_10_30","chapterId":"ch_work_han_thu_10","textTraditional":"〔一０〕師古曰：「以五十戶為率，共賜之。」","sentenceOrder":30},
  {"id":"s_work_han_thu_10_31","chapterId":"ch_work_han_thu_10","textTraditional":"六月，以民疾疫，令大官損膳，減樂府員，省苑馬，以振困乏。","sentenceOrder":31},
  {"id":"s_work_han_thu_10_32","chapterId":"ch_work_han_thu_10","textTraditional":"秋八月，上郡屬國降胡萬餘人亡入匈奴。","sentenceOrder":32},
  {"id":"s_work_han_thu_10_33","chapterId":"ch_work_han_thu_10","textTraditional":"九月，關東郡國十一大水，饑，或人相食，轉旁郡錢穀以相救。詔曰：「間者陰陽不調，黎民饑寒，無以保治，〔一〕惟德淺薄，不足以充入舊貫之居。〔二〕其令諸宮館希御幸者勿繕治，〔三〕太僕減穀食馬，水衡省肉食獸。」〔四〕","sentenceOrder":33},
  {"id":"s_work_han_thu_10_34","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「保，安也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_10_35","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　應劭曰：「言己德淺薄，不足以充舊貫。舊貫者，常居也。」師古曰：「論語稱閔子騫云『仍舊貫』。帝自謙，言不足充入先帝之宮室，故引以為言也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_10_36","chapterId":"ch_work_han_thu_10","textTraditional":"〔三〕　師古曰：「繕，補也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_10_37","chapterId":"ch_work_han_thu_10","textTraditional":"〔四〕　師古曰：「減謂損其數。省者，全去之。」","sentenceOrder":37},
  {"id":"s_work_han_thu_10_38","chapterId":"ch_work_han_thu_10","textTraditional":"二年春正月，行幸甘泉，郊泰畤。賜雲陽民爵一級，女子百戶牛酒。","sentenceOrder":38},
  {"id":"s_work_han_thu_10_39","chapterId":"ch_work_han_thu_10","textTraditional":"立弟竟為清河王。","sentenceOrder":39},
  {"id":"s_work_han_thu_10_40","chapterId":"ch_work_han_thu_10","textTraditional":"三月，立廣陵厲王太子霸為王。","sentenceOrder":40},
  {"id":"s_work_han_thu_10_41","chapterId":"ch_work_han_thu_10","textTraditional":"詔罷黃門乘輿狗馬，〔一〕水衡禁囿、宜春下苑、〔二〕少府佽飛外池、〔三〕嚴籞池田〔四〕假與貧民。詔曰：「蓋聞賢聖在位，陰陽和，風雨時，日月光，星辰靜，黎庶康寧，考終厥命。〔五〕今朕恭承天地，託于公侯之上，明不能燭，德不能綏，災異並臻，連年不息。乃二月戊午，地震于隴西郡，毀落太上皇廟殿壁木飾，壞敗豲道縣城郭官寺及民室屋，壓殺人眾。〔六〕山崩地裂，水泉湧出。天惟降災，震驚朕師。〔七〕治有大虧，咎至於斯。夙夜兢兢，不通大變，深惟鬱悼，未知其序。〔八〕間者歲數不登，元元困乏，不勝饑寒，以陷刑辟，朕甚閔之。郡國被地動災甚者無出租賦。赦天下。有可蠲除減省以便萬姓者，條奏，毋有所諱。丞相、御史、中二千石舉茂材異等直言極諫之士，朕將親覽焉。」","sentenceOrder":41},
  {"id":"s_work_han_thu_10_42","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「黃門，近署也，故親幸之物屬焉。」","sentenceOrder":42},
  {"id":"s_work_han_thu_10_43","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　孟康曰：「宮名也，在杜縣東。」晉灼曰：「史記云葬二世杜南宜春苑中。」師古曰：「宜春下苑即今京城東南隅曲江池是。」","sentenceOrder":43},
  {"id":"s_work_han_thu_10_44","chapterId":"ch_work_han_thu_10","textTraditional":"〔三〕　如淳曰：「漢儀注佽飛具矰繳以射鳧鴈，給祭祀，是故有池也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_10_45","chapterId":"ch_work_han_thu_10","textTraditional":"〔四〕　蘇林曰：「嚴飾池上之屋及其地也。」晉灼曰：「嚴籞，射苑也。許慎曰：『嚴，弋射者所蔽也。』池田，苑中田也。」師古曰：「晉說是。」","sentenceOrder":45},
  {"id":"s_work_han_thu_10_46","chapterId":"ch_work_han_thu_10","textTraditional":"〔五〕　師古曰：「考，老也。言得壽考，終其天命。」","sentenceOrder":46},
  {"id":"s_work_han_thu_10_47","chapterId":"ch_work_han_thu_10","textTraditional":"〔六〕　師古曰：「豲道屬天水。凡府庭所在皆謂之寺。豲音完。壓音烏狎反。」","sentenceOrder":47},
  {"id":"s_work_han_thu_10_48","chapterId":"ch_work_han_thu_10","textTraditional":"〔七〕　師古曰：「師，眾也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_10_49","chapterId":"ch_work_han_thu_10","textTraditional":"〔八〕　師古曰：「鬱，不通之意也。序，次也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_10_50","chapterId":"ch_work_han_thu_10","textTraditional":"夏四月丁巳，立皇太子。賜御史大夫爵關內侯，中二千石右庶長，〔一〕天下當為父後者爵一級，列侯錢各二十萬，五大夫十萬〔二〕。","sentenceOrder":50},
  {"id":"s_work_han_thu_10_51","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「第十一爵。」","sentenceOrder":51},
  {"id":"s_work_han_thu_10_52","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　師古曰：「五大夫，第九爵。」","sentenceOrder":52},
  {"id":"s_work_han_thu_10_53","chapterId":"ch_work_han_thu_10","textTraditional":"六月，關東饑，齊地人相食。秋七月，詔曰：「歲比災害，民有菜色，〔一〕慘怛於心。〔二〕已詔吏虛倉廩，開府庫振救，賜寒者衣。今秋禾麥頗傷。一年中地再動。北海水溢，流殺人民。陰陽不和，其咎安在？公卿將何以憂之？其悉意陳朕過，靡有所諱。」〔三〕","sentenceOrder":53},
  {"id":"s_work_han_thu_10_54","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「五穀不收，人但食菜，故其顏色變惡。」","sentenceOrder":54},
  {"id":"s_work_han_thu_10_55","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　師古曰：「慘，痛也。怛，悼也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_10_56","chapterId":"ch_work_han_thu_10","textTraditional":"〔三〕　師古曰：「悉意，盡意也。靡，無也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_10_57","chapterId":"ch_work_han_thu_10","textTraditional":"冬，詔曰：「國之將興，尊師而重傅。故前將軍望之傅朕八年，道以經書，厥功茂焉。〔一〕其賜爵關內侯，食邑八百戶，朝朔望。」","sentenceOrder":57},
  {"id":"s_work_han_thu_10_58","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「茂，美也。道讀曰導。」","sentenceOrder":58},
  {"id":"s_work_han_thu_10_59","chapterId":"ch_work_han_thu_10","textTraditional":"十二月，中書令弘恭、石顯等譖望之，令自殺。","sentenceOrder":59},
  {"id":"s_work_han_thu_10_60","chapterId":"ch_work_han_thu_10","textTraditional":"三年春，令諸侯相位在郡守下。〔一〕","sentenceOrder":60},
  {"id":"s_work_han_thu_10_61","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「此諸侯謂諸侯王也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_10_62","chapterId":"ch_work_han_thu_10","textTraditional":"珠崖郡山南縣反，博謀群臣。待詔賈捐之以為宜棄珠崖，救民饑饉。〔一〕乃罷珠崖。","sentenceOrder":62},
  {"id":"s_work_han_thu_10_63","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「穀不熟為饑，蔬不熟為饉。蔬，菜也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_10_64","chapterId":"ch_work_han_thu_10","textTraditional":"夏四月乙未晦，茂陵白鶴館災。詔曰：「乃者火災降於孝武園館，朕戰栗恐懼。不燭變異，咎在朕躬。〔一〕群司又未肯極言朕過，以至於斯，將何以寤焉！百姓仍遭凶阨，無以相振，〔二〕加以煩擾虖苛吏，拘牽乎微文，不得永終性命，〔三〕朕甚閔焉。其赦天下。」","sentenceOrder":64},
  {"id":"s_work_han_thu_10_65","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「燭，照也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_10_66","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　師古曰：「仍，頻也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_10_67","chapterId":"ch_work_han_thu_10","textTraditional":"〔三〕　師古曰：「永，長也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_10_68","chapterId":"ch_work_han_thu_10","textTraditional":"夏，旱。立長沙煬王弟宗為王。〔一〕封故海昏侯賀子代宗為侯。","sentenceOrder":68},
  {"id":"s_work_han_thu_10_69","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　（師古）〔鄭氏〕曰：「煬音供養之養也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_10_70","chapterId":"ch_work_han_thu_10","textTraditional":"六月，詔曰：「蓋聞安民之道，本繇陰陽。〔一〕間者陰陽錯謬，風雨不時。朕之不德，庶幾群公有敢言朕之過者，今則不然。媮合苟從，未肯極言，〔二〕朕甚閔焉。永惟烝庶之饑寒，遠離父母妻子，勞於非業之作，衛於不居之宮，〔三〕恐非所以佐陰陽之道也。其罷甘泉、建章宮衛，令就農。百官各省費。〔四〕條奏毋有所諱。有司勉之，毋犯四時之禁。丞相御史舉天下明陰陽災異者各三人。」於是言事者眾，或進擢召見，人人自以得上意。〔五〕","sentenceOrder":70},
  {"id":"s_work_han_thu_10_71","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「繇與由同。」","sentenceOrder":71},
  {"id":"s_work_han_thu_10_72","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　師古曰：「媮與偷同。」","sentenceOrder":72},
  {"id":"s_work_han_thu_10_73","chapterId":"ch_work_han_thu_10","textTraditional":"〔三〕　師古曰：「不急之事，（古）〔故〕云非業也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_10_74","chapterId":"ch_work_han_thu_10","textTraditional":"〔四〕　師古曰：「費用之物務減省。」","sentenceOrder":74},
  {"id":"s_work_han_thu_10_75","chapterId":"ch_work_han_thu_10","textTraditional":"〔五〕　師古曰：「人人各自以當天子之意。」","sentenceOrder":75},
  {"id":"s_work_han_thu_10_76","chapterId":"ch_work_han_thu_10","textTraditional":"四年春正月，行幸甘泉，郊泰畤。三月，行幸河東，祠后土。赦汾陰徒。賜民爵一級，女子百戶牛酒，鰥寡高年帛。行所過無出租賦。","sentenceOrder":76},
  {"id":"s_work_han_thu_10_77","chapterId":"ch_work_han_thu_10","textTraditional":"五年春正月，以周子南君為周承休侯，〔一〕位次諸侯王。","sentenceOrder":77},
  {"id":"s_work_han_thu_10_78","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　文穎曰：「姓姬，名延年。其祖父姬嘉，本周後，武帝元鼎四年封為周子南君，令奉周（祠）〔祀〕。」師古曰：「承休國在潁川。」","sentenceOrder":78},
  {"id":"s_work_han_thu_10_79","chapterId":"ch_work_han_thu_10","textTraditional":"三月，行幸雍，祠五畤。","sentenceOrder":79},
  {"id":"s_work_han_thu_10_80","chapterId":"ch_work_han_thu_10","textTraditional":"夏四月，有星孛于參。詔曰：「朕之不逮，序位不明，〔一〕眾僚久懬，〔二〕未得其人。元元失望，上感皇天，陰陽為變，咎流萬民，朕甚懼之。乃者關東連遭災害，饑寒疾疫，夭不終命。詩不云乎？『凡民有喪，匍匐救之。』〔三〕其令太官毋日殺，〔四〕所具各減半。〔五〕乘輿秣馬，無乏正事而已。〔六〕罷角抵、上林宮館希御幸者、齊三服官、〔七〕北假田官、〔八〕鹽鐵官、常平倉。博士弟子毋置員，以廣學者。賜宗室子有屬籍者馬一匹至二駟，三老、孝者帛，人五匹，弟者、力田三匹，鰥寡孤獨二匹，吏民五十戶牛酒。」省刑罰七十餘事。除光祿大夫以下至郎中保父母同產之令。〔九〕令從官給事宮司馬中者，得為大父母父母兄弟通籍。〔一０〕","sentenceOrder":80},
  {"id":"s_work_han_thu_10_81","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「逮，及也。言官人之位失其次序。」","sentenceOrder":81},
  {"id":"s_work_han_thu_10_82","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　應劭曰：「懬音曠。」師古曰：「懬，古曠字。曠，空也。不得其人，則職事空廢。」","sentenceOrder":82},
  {"id":"s_work_han_thu_10_83","chapterId":"ch_work_han_thu_10","textTraditional":"〔三〕　師古曰：「邶國谷風之詩也。言見人有喪禍之事，則當盡力以救之。匍音步扶反。匐音步得反。」","sentenceOrder":83},
  {"id":"s_work_han_thu_10_84","chapterId":"ch_work_han_thu_10","textTraditional":"〔四〕　師古曰：「不得日日宰殺。」","sentenceOrder":84},
  {"id":"s_work_han_thu_10_85","chapterId":"ch_work_han_thu_10","textTraditional":"〔五〕　師古曰：「食具也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_10_86","chapterId":"ch_work_han_thu_10","textTraditional":"〔六〕　師古曰：「秣，養也，以粟秣食之也。正事謂駕供郊祀蒐狩之事，非游田者也。秣音末。」","sentenceOrder":86},
  {"id":"s_work_han_thu_10_87","chapterId":"ch_work_han_thu_10","textTraditional":"〔七〕　李斐曰：「齊國舊有三服之官。春獻冠幘縰為首服，紈素為冬服，輕綃為夏服，凡三。」如淳曰：「地理志曰齊冠帶天下。胡公曰服官主作文繡，以給袞龍之服。地理志襄邑亦有服官。」師古曰：「齊三服官，李說是也。縰與纚同，音山爾反，即今之方目紗也。紈素，今之絹也。輕綃，今之輕紗也。襄邑自出文繡，非齊三服也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_10_88","chapterId":"ch_work_han_thu_10","textTraditional":"〔八〕　李斐曰：「主假賃見官田與民，收其假稅也。故置田農之官。」晉灼曰：「匈奴傳秦始皇渡河據陽山北假中，王莽傳五原北假膏壤殖穀。北假，地名。」師古曰：「晉說是也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_10_89","chapterId":"ch_work_han_thu_10","textTraditional":"〔九〕　應劭曰：「舊時相保，一人有過，皆當坐之。」師古曰：「特為郎中以上除此令者，所以優之也。同產，謂兄弟也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_10_90","chapterId":"ch_work_han_thu_10","textTraditional":"〔一０〕應劭曰：「從官，謂宦者及虎賁、羽林、太醫、太官是也。司馬中者，宮內門也。司馬主武，兵禁之意也。籍者，為二尺竹牒，記其年紀名字物色，縣之宮門，案省相應，乃得入也。」師古曰：「應說非也。從官，親近天子常侍從者皆是也。故此下云科第郎、從官。司馬門者，宮之外門也。衛尉有八屯，衛候司馬主衛士徼巡宿衛。每面各二司馬，故謂宮之外門為司馬門。」","sentenceOrder":90},
  {"id":"s_work_han_thu_10_91","chapterId":"ch_work_han_thu_10","textTraditional":"冬十二月丁未，御史大夫貢禹卒。","sentenceOrder":91},
  {"id":"s_work_han_thu_10_92","chapterId":"ch_work_han_thu_10","textTraditional":"衛司馬谷吉使匈奴，不還。〔一〕","sentenceOrder":92},
  {"id":"s_work_han_thu_10_93","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「即衛尉八屯之衛司馬。」","sentenceOrder":93},
  {"id":"s_work_han_thu_10_94","chapterId":"ch_work_han_thu_10","textTraditional":"永光元年春正月，行幸甘泉，郊泰畤。赦雲陽徒。賜民爵一級，女子百戶牛酒，高年帛。行所過毋出租賦。","sentenceOrder":94},
  {"id":"s_work_han_thu_10_95","chapterId":"ch_work_han_thu_10","textTraditional":"二月，詔丞相、御史舉質樸敦厚遜讓有行者，光祿歲以此科第郎、從官。〔一〕","sentenceOrder":95},
  {"id":"s_work_han_thu_10_96","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「始令丞相、御史舉此四科人以擢用之。而見在郎及從官，又令光祿每歲依此科考校，定其第高下，用知其人賢否也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_10_97","chapterId":"ch_work_han_thu_10","textTraditional":"三月，詔曰：「五帝三王任賢使能，以登至平，而今不治者，豈斯民異哉？〔一〕咎在朕之不明，亡以知賢也。是故壬人在位，〔二〕而吉士雍蔽。〔三〕重以周秦之弊，民漸薄俗，〔四〕去禮義，觸刑法，豈不哀哉！繇此觀之，元元何辜？〔五〕其赦天下，令厲精自新，各務農畝。無田者皆假之，貨種、食如貧民。〔六〕賜吏六百石以上爵五大夫，勤事吏二級，為父後者民一級，女子百戶牛酒，鰥寡孤獨高年帛。」是月雨雪，〔七〕隕霜傷麥稼，秋罷。〔八〕","sentenceOrder":97},
  {"id":"s_work_han_thu_10_98","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「言今所治人，即五帝三王之眾庶。」","sentenceOrder":98},
  {"id":"s_work_han_thu_10_99","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　服虔曰：「壬人，佞人也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_10_100","chapterId":"ch_work_han_thu_10","textTraditional":"〔三〕　師古曰：「吉，善也。大雅卷阿之詩曰『藹藹王多吉士』。雍讀曰〔壅〕。」","sentenceOrder":100},
  {"id":"s_work_han_thu_10_101","chapterId":"ch_work_han_thu_10","textTraditional":"〔四〕　師古曰：「為薄俗所漸染也。重音直用反。」","sentenceOrder":101},
  {"id":"s_work_han_thu_10_102","chapterId":"ch_work_han_thu_10","textTraditional":"〔五〕　師古曰：「繇讀與由同。」","sentenceOrder":102},
  {"id":"s_work_han_thu_10_103","chapterId":"ch_work_han_thu_10","textTraditional":"〔六〕　師古曰：「此皆謂遇赦新免罪者也，故云如貧人。」","sentenceOrder":103},
  {"id":"s_work_han_thu_10_104","chapterId":"ch_work_han_thu_10","textTraditional":"〔七〕　師古曰：「雨音于具反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_10_105","chapterId":"ch_work_han_thu_10","textTraditional":"〔八〕　如淳曰：「當言罷某官某事，爛脫失之。」晉灼曰：「或無稼字，或稼字在秋下。稼或作（臧）〔桑〕，或作霖。五行志永光元年三月隕霜殺桑，九月二日隕霜殺稼，天下大饑。言傷麥稼，秋罷，是也。」師古曰：「晉說得之。秋者，謂秋時所收穀稼也。今俗猶謂麥豆之屬為雜稼。云秋罷者，言至秋時無所收也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_10_106","chapterId":"ch_work_han_thu_10","textTraditional":"二年春二月，詔曰：「蓋聞唐虞象刑而民不犯，〔一〕殷周法行而姦軌服。〔二〕今朕獲承高祖之洪業，託位公侯之上，夙夜戰栗，永惟百姓之急，未嘗有忘焉。然而陰陽未調，三光晻昧。〔三〕元元大困，流散道路，盜賊並興。有司又長殘賊，失牧民之術。是皆朕之不明，政有所虧。咎至於此，朕甚自恥。為民父母，若是之薄，謂百姓何！〔四〕其大赦天下，賜民爵一級，女子百戶牛酒，鰥寡孤獨高年、三老、孝弟力田帛。」又賜諸侯王、公主、列侯黃金，中二千石以下至中都官長吏各有差，吏六百石以上爵五大夫，勤事吏各二級。","sentenceOrder":106},
  {"id":"s_work_han_thu_10_107","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「象刑，解在武紀。」","sentenceOrder":107},
  {"id":"s_work_han_thu_10_108","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　師古曰：「軌與宄同。亂在外曰姦，在內曰軌。」","sentenceOrder":108},
  {"id":"s_work_han_thu_10_109","chapterId":"ch_work_han_thu_10","textTraditional":"〔三〕　師古曰：「晻與暗同，又音烏感反。」","sentenceOrder":109},
  {"id":"s_work_han_thu_10_110","chapterId":"ch_work_han_thu_10","textTraditional":"〔四〕　師古曰：「言何以撫臨百姓。」","sentenceOrder":110},
  {"id":"s_work_han_thu_10_111","chapterId":"ch_work_han_thu_10","textTraditional":"三月壬戌朔，日有蝕之。詔曰：「朕戰戰栗栗，夙夜思過失，不敢荒寧。〔一〕惟陰陽不調，未燭其咎。婁敕公卿，日望有效。〔二〕至今有司執政，未得其中，〔三〕施與禁切，未合民心。〔四〕暴猛之俗彌長，和睦之道日衰，百姓愁苦，靡所錯躬。〔五〕是以氛邪歲增，侵犯太陽，〔六〕正氣湛掩，日久奪光。〔七〕乃壬戌，日有蝕之。天見大異，以戒朕躬，〔八〕朕甚悼焉。其令內郡國舉茂材異等賢良直言之士各一人。」","sentenceOrder":111},
  {"id":"s_work_han_thu_10_112","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「荒，廢也。不敢廢事而自寧。」","sentenceOrder":112},
  {"id":"s_work_han_thu_10_113","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　師古曰：「婁，古屢字。其後亦同。」","sentenceOrder":113},
  {"id":"s_work_han_thu_10_114","chapterId":"ch_work_han_thu_10","textTraditional":"〔三〕　師古曰：「中音竹仲反。」","sentenceOrder":114},
  {"id":"s_work_han_thu_10_115","chapterId":"ch_work_han_thu_10","textTraditional":"〔四〕　師古曰：「施惠褊薄，禁令煩苛。」","sentenceOrder":115},
  {"id":"s_work_han_thu_10_116","chapterId":"ch_work_han_thu_10","textTraditional":"〔五〕　師古曰：「錯，置也，音千故反。」","sentenceOrder":116},
  {"id":"s_work_han_thu_10_117","chapterId":"ch_work_han_thu_10","textTraditional":"〔六〕　師古曰：「氛，惡氣也。邪者，言非正氣也。太陽，日也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_10_118","chapterId":"ch_work_han_thu_10","textTraditional":"〔七〕　師古曰：「湛讀與沈同。湛掩者，見掩而湛沒。」","sentenceOrder":118},
  {"id":"s_work_han_thu_10_119","chapterId":"ch_work_han_thu_10","textTraditional":"〔八〕　師古曰：「見，顯示。」","sentenceOrder":119},
  {"id":"s_work_han_thu_10_120","chapterId":"ch_work_han_thu_10","textTraditional":"夏六月，詔曰：「間者連年不收，四方咸困。元元之民，勞於耕耘，又亡成功，困於饑饉，亡以相救。朕為民父母，德不能覆，而有其刑，甚自傷焉。其赦天下。」","sentenceOrder":120},
  {"id":"s_work_han_thu_10_121","chapterId":"ch_work_han_thu_10","textTraditional":"秋七月，西羌反，遣右將軍馮奉世擊之。八月，以太常任千秋為奮威將軍，別將五校並進。〔一〕","sentenceOrder":121},
  {"id":"s_work_han_thu_10_122","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「別領五校之兵，而與右將軍並進。」","sentenceOrder":122},
  {"id":"s_work_han_thu_10_123","chapterId":"ch_work_han_thu_10","textTraditional":"三年春，西羌平，軍罷。","sentenceOrder":123},
  {"id":"s_work_han_thu_10_124","chapterId":"ch_work_han_thu_10","textTraditional":"三月，立皇子康為濟陽王。","sentenceOrder":124},
  {"id":"s_work_han_thu_10_125","chapterId":"ch_work_han_thu_10","textTraditional":"夏四月癸未，大司馬車騎將軍接薨。〔一〕","sentenceOrder":125},
  {"id":"s_work_han_thu_10_126","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「王接。」","sentenceOrder":126},
  {"id":"s_work_han_thu_10_127","chapterId":"ch_work_han_thu_10","textTraditional":"冬十一月，詔曰：「乃者己丑地動，中冬雨水，大霧，〔一〕盜賊並起。吏何不以時禁？各悉意對。」〔二〕","sentenceOrder":127},
  {"id":"s_work_han_thu_10_128","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「中讀曰仲。雨音于具反。」","sentenceOrder":128},
  {"id":"s_work_han_thu_10_129","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　師古曰：「時禁，謂月令所當禁斷者也。悉，盡也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_10_130","chapterId":"ch_work_han_thu_10","textTraditional":"冬，復鹽鐵官、博士弟子員。〔一〕以用度不足，民多復除〔二〕，無以給中外繇役。","sentenceOrder":130},
  {"id":"s_work_han_thu_10_131","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「復音扶目反。」","sentenceOrder":131},
  {"id":"s_work_han_thu_10_132","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　師古曰：「復音方目反。」","sentenceOrder":132},
  {"id":"s_work_han_thu_10_133","chapterId":"ch_work_han_thu_10","textTraditional":"四年春二月，詔曰：「朕承至尊之重，不能燭理百姓，婁遭凶咎。加以邊竟不安，師旅在外，〔一〕賦斂轉輸，元元騷動，窮困亡聊，犯法抵罪。夫上失其道而繩下以深刑，朕甚痛之。其赦天下，所貸貧民勿收責。」","sentenceOrder":133},
  {"id":"s_work_han_thu_10_134","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「婁讀曰屢。竟讀曰境。」","sentenceOrder":134},
  {"id":"s_work_han_thu_10_135","chapterId":"ch_work_han_thu_10","textTraditional":"三月，行幸雍，祠五畤。","sentenceOrder":135},
  {"id":"s_work_han_thu_10_136","chapterId":"ch_work_han_thu_10","textTraditional":"夏六月甲戌，孝宣園東闕災。","sentenceOrder":136},
  {"id":"s_work_han_thu_10_137","chapterId":"ch_work_han_thu_10","textTraditional":"戊寅晦，日有蝕之。詔曰：「蓋聞明王在上，忠賢布職，則群生和樂，方外蒙澤。今朕晻于王道，〔一〕夙夜憂勞，不通其理，靡瞻不眩，靡聽不惑，〔二〕是以政令多還，民心未得，〔三〕邪說空進，事亡成功。此天下所著聞也。公卿大夫好惡不同，〔四〕或緣姦作邪，侵削細民，元元安所歸命哉！乃六月晦，日有蝕之。詩不云虖？『今此下民，亦孔之哀！』〔五〕自今以來，公卿大夫其勉思天戒，慎身修永，以輔朕之不逮。〔六〕直言盡意，無有所諱。」","sentenceOrder":137},
  {"id":"s_work_han_thu_10_138","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「晻讀與暗同。」","sentenceOrder":138},
  {"id":"s_work_han_thu_10_139","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　師古曰：「靡，無也。眩，視亂也，音胡眄反。」","sentenceOrder":139},
  {"id":"s_work_han_thu_10_140","chapterId":"ch_work_han_thu_10","textTraditional":"〔三〕　李奇曰：「還，反也。易曰『渙汗其大號』，言王者發號施令如汗出，不可復反。」","sentenceOrder":140},
  {"id":"s_work_han_thu_10_141","chapterId":"ch_work_han_thu_10","textTraditional":"〔四〕　師古曰：「愛憎各異也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_10_142","chapterId":"ch_work_han_thu_10","textTraditional":"〔五〕　師古曰：「小雅十月之交之詩也。孔，甚也。言災異既多，百姓甚可哀愍。」","sentenceOrder":142},
  {"id":"s_work_han_thu_10_143","chapterId":"ch_work_han_thu_10","textTraditional":"〔六〕　師古曰：「虞書咎繇謨云『慎厥身修思永』，言當慎修其身，思為長久之道。故此詔云慎身修永也。今流俗書本永上有職字者，後人不曉，妄加之耳。」","sentenceOrder":143},
  {"id":"s_work_han_thu_10_144","chapterId":"ch_work_han_thu_10","textTraditional":"九月戊子，罷衛思后園〔一〕及戾園。冬十月乙丑，罷祖宗廟在郡國者。諸陵分屬三輔。〔二〕以渭城壽陵亭部原上為初陵。〔三〕詔曰：「安土重遷，黎民之性；〔四〕骨肉相附，人情所願也。頃者有司緣臣子之義，奏徙郡國民以奉園陵，令百姓遠棄先祖墳墓，破業失產，親戚別離，人懷思慕之心，家有不安之意。是以東垂被虛耗之害，關中有無聊之民，〔五〕非久長之策也。詩不云虖？『民亦勞止，迄可小康，惠此中國，以綏四方。』〔六〕今所為初陵者，勿置縣邑，使天下咸安土樂業，亡有動搖之心。布告天下，令明知之。」又罷先后父母奉邑。〔七〕","sentenceOrder":144},
  {"id":"s_work_han_thu_10_145","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　服虔曰：「戾太子母也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_10_146","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　師古曰：「先是諸陵總屬太常，今各依其地界屬三輔。」","sentenceOrder":146},
  {"id":"s_work_han_thu_10_147","chapterId":"ch_work_han_thu_10","textTraditional":"〔三〕　服虔曰：「元帝初置陵，未有名也，故曰初。」","sentenceOrder":147},
  {"id":"s_work_han_thu_10_148","chapterId":"ch_work_han_thu_10","textTraditional":"〔四〕　師古曰：「重，難也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_10_149","chapterId":"ch_work_han_thu_10","textTraditional":"〔五〕　師古曰：「耗，損也，音呼到反。」","sentenceOrder":149},
  {"id":"s_work_han_thu_10_150","chapterId":"ch_work_han_thu_10","textTraditional":"〔六〕　師古曰：「大雅民勞之詩也。止，語助也。迄，至也。康，安也。言人勞已久，至此可以小安逸之。施惠京師，以及四遠也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_10_151","chapterId":"ch_work_han_thu_10","textTraditional":"〔七〕　應劭曰：「先后為其父母置邑守冢，以奉祭祀，既已久遠，又非典制，故罷之。」師古曰：「奉邑，奉音扶用反。」","sentenceOrder":151},
  {"id":"s_work_han_thu_10_152","chapterId":"ch_work_han_thu_10","textTraditional":"五年春正月，行幸甘泉，郊泰畤。三月，上幸河東，祠后土。","sentenceOrder":152},
  {"id":"s_work_han_thu_10_153","chapterId":"ch_work_han_thu_10","textTraditional":"秋，潁川水出，流殺人民。吏、從官縣被害者與告。〔一〕士卒遣歸。","sentenceOrder":153},
  {"id":"s_work_han_thu_10_154","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　晉灼曰：「從官，猶從役從軍也。」臣瓚曰：「告，休假也。」師古曰：「晉說非也。從官，即上侍從之官也。言凡為吏為從官，其本縣有被害者，皆與休告。」","sentenceOrder":154},
  {"id":"s_work_han_thu_10_155","chapterId":"ch_work_han_thu_10","textTraditional":"冬，上幸長楊射熊館，〔一〕布車騎，大獵。","sentenceOrder":155},
  {"id":"s_work_han_thu_10_156","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「射音食亦反。」","sentenceOrder":156},
  {"id":"s_work_han_thu_10_157","chapterId":"ch_work_han_thu_10","textTraditional":"十二月乙酉，毀太上皇、孝惠皇帝寢廟園。","sentenceOrder":157},
  {"id":"s_work_han_thu_10_158","chapterId":"ch_work_han_thu_10","textTraditional":"建昭元年春三月，上幸雍，祠五畤。","sentenceOrder":158},
  {"id":"s_work_han_thu_10_159","chapterId":"ch_work_han_thu_10","textTraditional":"秋八月，有白蛾群飛蔽日，從東都門至枳道。〔一〕","sentenceOrder":159},
  {"id":"s_work_han_thu_10_160","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　如淳曰：「三輔黃圖長安城東面北頭門號曰宣平城門，其外郭曰東都門也。」師古曰：「蛾，若今之蠶蛾類也。音五何反。枳音只。枳道解在高紀。」","sentenceOrder":160},
  {"id":"s_work_han_thu_10_161","chapterId":"ch_work_han_thu_10","textTraditional":"冬，河間王元有罪，廢遷房陵。罷孝文太后、孝昭太后寢園。","sentenceOrder":161},
  {"id":"s_work_han_thu_10_162","chapterId":"ch_work_han_thu_10","textTraditional":"二年春正月，行幸甘泉，郊泰畤。三月，行幸河東，祠后土。益三河〔大〕郡太守秩。戶十二萬為大郡。","sentenceOrder":162},
  {"id":"s_work_han_thu_10_163","chapterId":"ch_work_han_thu_10","textTraditional":"夏四月，赦天下。","sentenceOrder":163},
  {"id":"s_work_han_thu_10_164","chapterId":"ch_work_han_thu_10","textTraditional":"六月，立皇子（興）〔輿〕為信都王。閏月丁酉，太皇太后上官氏崩。","sentenceOrder":164},
  {"id":"s_work_han_thu_10_165","chapterId":"ch_work_han_thu_10","textTraditional":"冬十一月，齊楚地震，大雨雪，〔一〕樹折屋壞。","sentenceOrder":165},
  {"id":"s_work_han_thu_10_166","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「雨音于具反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_10_167","chapterId":"ch_work_han_thu_10","textTraditional":"淮陽王舅張博、魏郡太守京房坐窺道諸侯王以邪意，漏泄省中語，〔一〕博要斬，房棄市。","sentenceOrder":167},
  {"id":"s_work_han_thu_10_168","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「道讀曰導。」","sentenceOrder":168},
  {"id":"s_work_han_thu_10_169","chapterId":"ch_work_han_thu_10","textTraditional":"三年夏，令三輔都尉、大郡都尉秩皆二千石。","sentenceOrder":169},
  {"id":"s_work_han_thu_10_170","chapterId":"ch_work_han_thu_10","textTraditional":"六月甲辰，丞相玄成薨。〔一〕","sentenceOrder":170},
  {"id":"s_work_han_thu_10_171","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「韋玄成。」","sentenceOrder":171},
  {"id":"s_work_han_thu_10_172","chapterId":"ch_work_han_thu_10","textTraditional":"秋，使護西域騎都尉甘延壽、副校尉陳湯〔一〕撟發戊己校尉屯田吏士及西域胡兵攻郅支單于。〔二〕冬，斬其首，傳詣京師，縣蠻夷邸門。〔三〕","sentenceOrder":172},
  {"id":"s_work_han_thu_10_173","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「言延壽及湯本充西域之使，故先言使而後序其官職及姓名。」","sentenceOrder":173},
  {"id":"s_work_han_thu_10_174","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　師古曰：「撟與矯同。矯，託也。實不奉詔，詐以上命發兵，故言矯發也。戊己校尉者，鎮安西域，無常治處，亦猶甲乙等各有方位，而戊與己四季寄王，故以名官也。時有戊校尉，又有己校尉。一說，戊己位在中央，今所置校尉處三十六國之中，故曰戊己也。郅音質。」","sentenceOrder":174},
  {"id":"s_work_han_thu_10_175","chapterId":"ch_work_han_thu_10","textTraditional":"〔三〕　師古曰：「縣，古懸字也。蠻夷邸，若今鴻臚客館。」","sentenceOrder":175},
  {"id":"s_work_han_thu_10_176","chapterId":"ch_work_han_thu_10","textTraditional":"四年春正月，以誅郅支單于告祠郊廟。赦天下。群臣上壽置酒，以其圖書示後宮貴人。〔一〕","sentenceOrder":176},
  {"id":"s_work_han_thu_10_177","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　服虔曰：「討郅支之圖書也。或曰單于土地山川之形書也。」師古曰：「或說非。」","sentenceOrder":177},
  {"id":"s_work_han_thu_10_178","chapterId":"ch_work_han_thu_10","textTraditional":"夏四月，詔曰：「朕承先帝之休烈，〔一〕夙夜栗栗，懼不克任。間者陰陽不調，五行失序，百姓饑饉。惟烝庶之失業，臨遣諫大夫博士賞等二十一人循行天下，〔二〕存問耆老鰥寡孤獨乏困失職之人，舉茂材特立之士。相將九卿，其帥意毋怠，使朕獲觀教化之流焉。」","sentenceOrder":178},
  {"id":"s_work_han_thu_10_179","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「休，美也。烈，業也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_10_180","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　師古曰：「行音下更反。」","sentenceOrder":180},
  {"id":"s_work_han_thu_10_181","chapterId":"ch_work_han_thu_10","textTraditional":"六月甲申，中山王竟薨。","sentenceOrder":181},
  {"id":"s_work_han_thu_10_182","chapterId":"ch_work_han_thu_10","textTraditional":"藍田地沙石雍霸水，安陵岸崩雍涇水，水逆流。〔一〕","sentenceOrder":182},
  {"id":"s_work_han_thu_10_183","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　孟康曰：「安陵岸，惠帝陵旁涇水岸也。」師古曰：「雍讀曰壅。」","sentenceOrder":183},
  {"id":"s_work_han_thu_10_184","chapterId":"ch_work_han_thu_10","textTraditional":"五年春三月，詔曰：「蓋聞明王之治國也，明好惡而定去就，崇敬讓而民興行，故法設而民不犯，令施而民從。今朕獲保宗廟，兢兢業業，匪敢解怠，〔一〕德薄明晻，教化淺微。〔二〕傳不云虖？『百姓有過，在予一人。』〔三〕其赦天下，賜民爵一級，女子百戶牛酒，三老、孝弟力田帛。」又曰：「方春農桑興，百姓（戮）〔勠〕力自盡之時也，故是月勞農勸民，無使後時。〔四〕今不良之吏，覆案小罪，〔五〕徵召證案，興不急之事，以妨百姓，使失一時之作，亡終歲之功，公卿其明察申敕之。」〔六〕","sentenceOrder":184},
  {"id":"s_work_han_thu_10_185","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「兢兢，慎也。業業，危也。解讀曰懈。」","sentenceOrder":185},
  {"id":"s_work_han_thu_10_186","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　師古曰：「晻讀與暗同。」","sentenceOrder":186},
  {"id":"s_work_han_thu_10_187","chapterId":"ch_work_han_thu_10","textTraditional":"〔三〕　師古曰：「論語載殷湯伐桀告天下之文也。言君天下者，當任其憂責。」","sentenceOrder":187},
  {"id":"s_work_han_thu_10_188","chapterId":"ch_work_han_thu_10","textTraditional":"〔四〕　師古曰：「勞農，謂慰勉之。勞音來到反。」","sentenceOrder":188},
  {"id":"s_work_han_thu_10_189","chapterId":"ch_work_han_thu_10","textTraditional":"〔五〕　師古曰：「覆音方目反。」","sentenceOrder":189},
  {"id":"s_work_han_thu_10_190","chapterId":"ch_work_han_thu_10","textTraditional":"〔六〕　師古曰：「申，重也，一曰約束之耳。」","sentenceOrder":190},
  {"id":"s_work_han_thu_10_191","chapterId":"ch_work_han_thu_10","textTraditional":"夏六月庚申，復戾園。","sentenceOrder":191},
  {"id":"s_work_han_thu_10_192","chapterId":"ch_work_han_thu_10","textTraditional":"壬申晦，日有蝕之。","sentenceOrder":192},
  {"id":"s_work_han_thu_10_193","chapterId":"ch_work_han_thu_10","textTraditional":"秋七月庚子，復太上皇寢廟園、原廟、〔一〕昭靈后、武哀王、昭哀后、衛思后園。〔二〕","sentenceOrder":193},
  {"id":"s_work_han_thu_10_194","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　文穎曰：「高祖已自有廟，在長安城中，惠帝更於渭北作廟，謂之原廟。爾雅曰原者再，再作廟也。」晉灼曰：「原，本也。始祖之廟，故曰本也。」師古曰：「文說是。」","sentenceOrder":194},
  {"id":"s_work_han_thu_10_195","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　師古曰：「昭靈后，高祖母也。武哀王，高祖兄也。昭哀后，高祖姊也。衛思后，戾太子母也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_10_196","chapterId":"ch_work_han_thu_10","textTraditional":"竟寧元年〔一〕春正月，匈奴虖韓邪單于來朝。詔曰：「匈奴郅支單于背叛禮義，既伏其辜，虖韓邪單于不忘恩德，鄉慕禮義，〔二〕復修朝賀之禮，願保塞傳之無窮，邊垂長無兵革之事。其改元為竟寧，賜單于待詔掖庭王檣為閼氏。」〔三〕","sentenceOrder":196},
  {"id":"s_work_han_thu_10_197","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　應劭曰：「虖韓邪單于願保塞，邊竟得以安寧，故以冠元也。」師古曰：「據如應說，竟讀為境。古之用字，境竟實同。但此詔云『邊垂長無兵革之事』，竟者終極之言，言永安寧也。既無兵革，中外安寧，豈止境上？若依本字而讀，義更弘通也。」","sentenceOrder":197},
  {"id":"s_work_han_thu_10_198","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":198},
  {"id":"s_work_han_thu_10_199","chapterId":"ch_work_han_thu_10","textTraditional":"〔三〕　應劭曰：「郡國獻女未御見，須命於掖庭，故曰待詔。王檣，王氏女，名檣，字昭君。」文穎曰：「本南郡秭歸人也。」蘇林曰：「閼氏音焉支，如漢皇后也。」師古曰：「秭音姊。」","sentenceOrder":199},
  {"id":"s_work_han_thu_10_200","chapterId":"ch_work_han_thu_10","textTraditional":"皇太子冠。賜列侯嗣子爵五大夫，〔一〕天下為父後者爵一級。","sentenceOrder":200},
  {"id":"s_work_han_thu_10_201","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「第九爵。」","sentenceOrder":201},
  {"id":"s_work_han_thu_10_202","chapterId":"ch_work_han_thu_10","textTraditional":"二月，御史大夫延壽卒。〔一〕","sentenceOrder":202},
  {"id":"s_work_han_thu_10_203","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　師古曰：「即繁延壽也。繁音蒲何反。」","sentenceOrder":203},
  {"id":"s_work_han_thu_10_204","chapterId":"ch_work_han_thu_10","textTraditional":"三月癸未，復孝惠皇帝寢廟園、孝文太后、孝昭太后寢園。","sentenceOrder":204},
  {"id":"s_work_han_thu_10_205","chapterId":"ch_work_han_thu_10","textTraditional":"夏，封騎都尉甘延壽為列侯。賜副校尉陳湯爵關內侯，黃金百斤。","sentenceOrder":205},
  {"id":"s_work_han_thu_10_206","chapterId":"ch_work_han_thu_10","textTraditional":"五月壬辰，帝崩于未央宮。〔一〕","sentenceOrder":206},
  {"id":"s_work_han_thu_10_207","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　臣瓚曰：「帝年二十七即位，即位十六年，壽四十三。」","sentenceOrder":207},
  {"id":"s_work_han_thu_10_208","chapterId":"ch_work_han_thu_10","textTraditional":"毀太上皇、孝惠、孝景皇帝廟。罷孝文、孝昭太后、昭靈后、武哀王、昭哀后寢園。","sentenceOrder":208},
  {"id":"s_work_han_thu_10_209","chapterId":"ch_work_han_thu_10","textTraditional":"秋七月丙戌，葬渭陵。〔一〕","sentenceOrder":209},
  {"id":"s_work_han_thu_10_210","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　臣瓚曰：「自崩及葬凡五十五日。渭陵在長安北五十六里也。」","sentenceOrder":210},
  {"id":"s_work_han_thu_10_211","chapterId":"ch_work_han_thu_10","textTraditional":"贊曰：臣外祖兄弟為元帝侍中，〔一〕語臣曰元帝多材藝，善史書。〔二〕鼓琴瑟，吹洞簫，〔三〕自度曲，被歌聲，〔四〕分刌節度，〔五〕窮極幼眇。〔六〕少而好儒，及即位，徵用儒生，委之以政，貢、薛、韋、匡迭為宰相。〔七〕而上牽制文義，優游不斷〔八〕，孝宣之業衰焉。然寬弘盡下，出於恭儉，號令溫雅，有古之風烈。","sentenceOrder":211},
  {"id":"s_work_han_thu_10_212","chapterId":"ch_work_han_thu_10","textTraditional":"〔一〕　應劭曰：「元、成帝紀皆班固父彪所作，臣則彪自說也。外祖，金敞也。」如淳曰：「班固外祖，樊叔皮也。」師古曰：「應說是。」","sentenceOrder":212},
  {"id":"s_work_han_thu_10_213","chapterId":"ch_work_han_thu_10","textTraditional":"〔二〕　應劭曰：「周宣王太史史籀所作大篆。」","sentenceOrder":213},
  {"id":"s_work_han_thu_10_214","chapterId":"ch_work_han_thu_10","textTraditional":"〔三〕　如淳曰：「簫之無底者。」","sentenceOrder":214},
  {"id":"s_work_han_thu_10_215","chapterId":"ch_work_han_thu_10","textTraditional":"〔四〕　應劭曰：「自隱度作新曲，因持新曲以為歌詩聲也。」荀悅曰：「被聲，能播樂也。」臣瓚曰：「度曲，謂歌終更授其次，謂之度曲。西京賦曰『度曲未終，雲起雪飛』。張衡舞賦亦曰『度終復位，次受二八』。」師古曰：「應、荀二說皆是也。度音大各反。被音皮義反。」","sentenceOrder":215},
  {"id":"s_work_han_thu_10_216","chapterId":"ch_work_han_thu_10","textTraditional":"〔五〕　蘇林曰：「刌，度也，知曲之終始節度也。」韋昭曰：「刌，切也，謂能分切句絕，為之節制也。」師古曰：「韋說是也。刌音千本反。」","sentenceOrder":216},
  {"id":"s_work_han_thu_10_217","chapterId":"ch_work_han_thu_10","textTraditional":"〔六〕　師古曰：「幼眇讀曰要妙。」","sentenceOrder":217},
  {"id":"s_work_han_thu_10_218","chapterId":"ch_work_han_thu_10","textTraditional":"〔七〕　師古曰：「貢禹、薛廣德、韋賢、匡衡迭互而為丞相也。迭音大結反。」","sentenceOrder":218},
  {"id":"s_work_han_thu_10_219","chapterId":"ch_work_han_thu_10","textTraditional":"〔八〕　師古曰：「為文義所牽制，故不斷決。」","sentenceOrder":219},
  {"id":"s_work_han_thu_10_220","chapterId":"ch_work_han_thu_10","textTraditional":"校勘記","sentenceOrder":220},
  {"id":"s_work_han_thu_10_221","chapterId":"ch_work_han_thu_10","textTraditional":"二七七頁　五行　（盍）〔蓋〕寬饒等　錢大昭說明南監、閩本作「蓋」。　按殿本作「蓋」，本傳同。","sentenceOrder":221},
  {"id":"s_work_han_thu_10_222","chapterId":"ch_work_han_thu_10","textTraditional":"二七七頁　六行　奈何純（住）〔任〕德教，　景祐、殿、局本都作「任」。　錢大昭說當作「任」。","sentenceOrder":222},
  {"id":"s_work_han_thu_10_223","chapterId":"ch_work_han_thu_10","textTraditional":"二八四頁　七行　（師古）〔鄭氏〕曰：　景祐、殿本都作「鄭氏」。","sentenceOrder":223},
  {"id":"s_work_han_thu_10_224","chapterId":"ch_work_han_thu_10","textTraditional":"二八四頁一五行　（古）〔故〕云非業也。　景祐、殿本都作「故」，通鑑注引同。","sentenceOrder":224},
  {"id":"s_work_han_thu_10_225","chapterId":"ch_work_han_thu_10","textTraditional":"二八五頁　五行　令奉周（祠）〔祀〕。　王先謙說殿本作「祀」是。按通鑑注亦作「祀」。","sentenceOrder":225},
  {"id":"s_work_han_thu_10_226","chapterId":"ch_work_han_thu_10","textTraditional":"二八八頁　二行　雍讀曰〔壅〕。　景祐、殿本都有「壅」字，此脫。","sentenceOrder":226},
  {"id":"s_work_han_thu_10_227","chapterId":"ch_work_han_thu_10","textTraditional":"二八八頁　七行　稼或作（臧）〔桑〕，　錢大昭說明南監、閩本作「桑」。　王先謙說殿本作「桑」是。","sentenceOrder":227},
  {"id":"s_work_han_thu_10_228","chapterId":"ch_work_han_thu_10","textTraditional":"二九四頁　四行　益三河〔大〕郡太守秩。　景祐本有「大」字。","sentenceOrder":228},
  {"id":"s_work_han_thu_10_229","chapterId":"ch_work_han_thu_10","textTraditional":"二九四頁　七行　立皇子（興）〔輿〕為信都王。　景祐本作「輿」。宋祁說作「輿」是。","sentenceOrder":229},
  {"id":"s_work_han_thu_10_230","chapterId":"ch_work_han_thu_10","textTraditional":"二九六頁　八行　百姓（戮）〔勠〕力　景祐、殿本都作「勠」。　王先謙說作「勠」是。","sentenceOrder":230},
  {"id":"s_work_han_thu_11_1","chapterId":"ch_work_han_thu_11","textTraditional":"孝成皇帝，〔一〕元帝太子也。母曰王皇后，元帝在太子宮生甲觀畫堂，〔二〕為世嫡皇孫。宣帝愛之，字曰太孫，常置左右。年三歲而宣帝崩，元帝即位，帝為太子。壯好經書，寬博謹慎。初居桂宮，〔三〕上嘗急召，太子出龍樓門，〔四〕不敢絕馳道，〔五〕西至直城門，〔六〕得絕乃度，還入作室門。上遲之，問其故，以狀對。上大說，〔七〕乃著令，令太子得絕馳道云。〔八〕其後幸酒，樂燕樂，〔九〕上不以為能。而定陶恭王有材藝，母傅昭儀又愛幸，上以故常有意欲以恭王為嗣。賴侍中史丹護太子家，輔助有力，上亦以先帝尤愛太子，故得無廢。","sentenceOrder":1},
  {"id":"s_work_han_thu_11_2","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　荀悅曰：「諱驁，字太孫。驁之字曰俊。」應劭曰：「諡法『安民立政曰成』。」師古曰：「驁音五到反。」","sentenceOrder":2},
  {"id":"s_work_han_thu_11_3","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　應劭曰：「甲觀在太子宮甲地，主用乳生也。畫堂畫九子母。」如淳曰：「甲觀，觀名。畫堂，堂名。三輔黃圖云太子宮有甲觀。」師古曰：「甲者，甲乙丙丁之次也。元后傳言見於丙殿，此其例也。而應氏以為在宮之甲地，謬矣。畫堂，但畫飾耳，豈必九子母乎？霍光止畫室中，是則宮殿中通有綵畫之堂室。」","sentenceOrder":3},
  {"id":"s_work_han_thu_11_4","chapterId":"ch_work_han_thu_11","textTraditional":"〔三〕　師古曰：「三輔黃圖桂宮在城中，近北宮，非太子宮。」","sentenceOrder":4},
  {"id":"s_work_han_thu_11_5","chapterId":"ch_work_han_thu_11","textTraditional":"〔四〕　張晏曰：「門樓上有銅龍，若白鶴、飛廉之為名也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_11_6","chapterId":"ch_work_han_thu_11","textTraditional":"〔五〕　應劭曰：「馳道，天子所行道也，若今之中道。」師古曰：「絕，橫度也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_11_7","chapterId":"ch_work_han_thu_11","textTraditional":"〔六〕　晉灼曰：「黃圖西出南頭第二門也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_11_8","chapterId":"ch_work_han_thu_11","textTraditional":"〔七〕　師古曰：「說讀曰悅。」","sentenceOrder":8},
  {"id":"s_work_han_thu_11_9","chapterId":"ch_work_han_thu_11","textTraditional":"〔八〕　師古曰：「言云者，此舉著令之文。」","sentenceOrder":9},
  {"id":"s_work_han_thu_11_10","chapterId":"ch_work_han_thu_11","textTraditional":"〔九〕　晉灼曰：「幸酒，好酒也。樂燕，沈讌也。」師古曰：「幸酒，晉說是也。樂燕樂者，論語稱孔子云『損者三樂：樂驕樂，樂逸遊，樂燕樂，損矣。』燕樂，燕私之樂也。上樂讀如本字，又音五孝反。下樂音來各反。今流俗本無下樂字，後人不曉輒去之。」","sentenceOrder":10},
  {"id":"s_work_han_thu_11_11","chapterId":"ch_work_han_thu_11","textTraditional":"竟寧元年五月，元帝崩。六月己未，太子即皇帝位，謁高廟。尊皇太后曰太皇太后，皇后曰皇太后。以元舅侍中衛尉陽平侯王鳳為大司馬大將軍，領尚書事。","sentenceOrder":11},
  {"id":"s_work_han_thu_11_12","chapterId":"ch_work_han_thu_11","textTraditional":"乙未，有司言：「乘輿車、牛馬、禽獸皆非禮，不宜以葬。」奏可。","sentenceOrder":12},
  {"id":"s_work_han_thu_11_13","chapterId":"ch_work_han_thu_11","textTraditional":"七月，大赦天下。","sentenceOrder":13},
  {"id":"s_work_han_thu_11_14","chapterId":"ch_work_han_thu_11","textTraditional":"建始元年春正月乙丑，皇曾祖悼考廟災。〔一〕","sentenceOrder":14},
  {"id":"s_work_han_thu_11_15","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　文穎曰：「宣帝父史皇孫廟。」","sentenceOrder":15},
  {"id":"s_work_han_thu_11_16","chapterId":"ch_work_han_thu_11","textTraditional":"立故河間王弟上郡庫令良為王。〔一〕","sentenceOrder":16},
  {"id":"s_work_han_thu_11_17","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　如淳曰：「漢官北邊郡庫，官之兵器所藏，故置令。」","sentenceOrder":17},
  {"id":"s_work_han_thu_11_18","chapterId":"ch_work_han_thu_11","textTraditional":"有星孛于營室。","sentenceOrder":18},
  {"id":"s_work_han_thu_11_19","chapterId":"ch_work_han_thu_11","textTraditional":"罷上林詔獄。〔一〕","sentenceOrder":19},
  {"id":"s_work_han_thu_11_20","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「漢舊儀云上林詔獄主治苑中禽獸宮館事，屬水衡。」","sentenceOrder":20},
  {"id":"s_work_han_thu_11_21","chapterId":"ch_work_han_thu_11","textTraditional":"二月，右將軍長史姚尹等使匈奴還，去塞百餘里，暴風火發，燒殺尹等七人。","sentenceOrder":21},
  {"id":"s_work_han_thu_11_22","chapterId":"ch_work_han_thu_11","textTraditional":"賜諸侯王、丞相、將軍、列侯、王太后、公主、王主、〔一〕吏二千石黃金，宗室諸官吏千石以下至二百石及宗室子有屬籍者、三老、孝弟力田、鰥寡孤獨錢帛，各有差，吏民五十戶牛酒。","sentenceOrder":22},
  {"id":"s_work_han_thu_11_23","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　張晏曰：「天子女曰公主，秩比公也。王主，王之女也。」師古曰：「王主則翁主也。王自主婚，故曰王主。」","sentenceOrder":23},
  {"id":"s_work_han_thu_11_24","chapterId":"ch_work_han_thu_11","textTraditional":"詔曰：「乃者火災降於祖廟，有星孛于東方，始正而虧，〔一〕咎孰大焉！〔二〕書云：『惟先假王正厥事。』〔三〕群公孜孜，帥先百寮，輔朕不逮。〔四〕崇寬大，長和睦，凡事恕己，毋行苛刻。〔五〕其大赦天下，使得自新。」","sentenceOrder":24},
  {"id":"s_work_han_thu_11_25","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　如淳曰：「言始即帝之正而有彗星之虧也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_11_26","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「孰有大於此者。孰，誰也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_11_27","chapterId":"ch_work_han_thu_11","textTraditional":"〔三〕　師古曰：「商書高宗肜日載武丁之臣祖己之辭也。假，至也。言先古至道之君遭遇災變，則正其行事，修德以應之。」","sentenceOrder":27},
  {"id":"s_work_han_thu_11_28","chapterId":"ch_work_han_thu_11","textTraditional":"〔四〕　師古曰：「孜孜，不怠之意。孜音茲。」","sentenceOrder":28},
  {"id":"s_work_han_thu_11_29","chapterId":"ch_work_han_thu_11","textTraditional":"〔五〕　師古曰：「恕者，仁也。恕己之心以度於物。」","sentenceOrder":29},
  {"id":"s_work_han_thu_11_30","chapterId":"ch_work_han_thu_11","textTraditional":"封舅諸吏光祿大夫關內侯王崇為安成侯。〔一〕賜舅王譚、商、立、根、逢時爵關內侯。","sentenceOrder":30},
  {"id":"s_work_han_thu_11_31","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　應劭曰：「百官表諸吏得舉法案劾，職如御史中丞。武帝初置，皆兼官所加，或列侯、將軍、卿大夫為之，無員也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_11_32","chapterId":"ch_work_han_thu_11","textTraditional":"夏四月，黃霧四塞，博問公卿大夫，無有所諱。六月，有青蠅無萬數〔一〕集未央宮殿中朝者坐。〔二〕","sentenceOrder":32},
  {"id":"s_work_han_thu_11_33","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「言其極多，雖欲以萬數計之而不可得，故云無萬數。」","sentenceOrder":33},
  {"id":"s_work_han_thu_11_34","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　服虔曰：「公卿以下朝會坐也。」晉灼曰：「內朝臣之朝坐也。」師古曰：「朝臣坐之在宮殿中者也，服說是矣。坐音才臥反。」","sentenceOrder":34},
  {"id":"s_work_han_thu_11_35","chapterId":"ch_work_han_thu_11","textTraditional":"秋，罷上林宮館希御幸者二十五所。","sentenceOrder":35},
  {"id":"s_work_han_thu_11_36","chapterId":"ch_work_han_thu_11","textTraditional":"八月，有兩月相承，晨見東方。〔一〕","sentenceOrder":36},
  {"id":"s_work_han_thu_11_37","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　服虔曰：「相承，在上下也。」應劭曰：「案京房易傳云『君弱如婦，為陰所乘，則兩月出』。」","sentenceOrder":37},
  {"id":"s_work_han_thu_11_38","chapterId":"ch_work_han_thu_11","textTraditional":"九月戊子，流星光燭地，長四五丈，委曲蛇形，貫紫宮。","sentenceOrder":38},
  {"id":"s_work_han_thu_11_39","chapterId":"ch_work_han_thu_11","textTraditional":"十二月，作長安南北郊，罷甘泉、汾陰祠。是日大風，拔甘泉畤中大木十韋以上。〔一〕郡國被災什四以上，毋收田租。〔二〕","sentenceOrder":39},
  {"id":"s_work_han_thu_11_40","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「韋與圍同。」","sentenceOrder":40},
  {"id":"s_work_han_thu_11_41","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「什四，謂田畝所收，十損其四。」","sentenceOrder":41},
  {"id":"s_work_han_thu_11_42","chapterId":"ch_work_han_thu_11","textTraditional":"二年春正月，罷雍五畤。辛巳，上始郊祀長安南郊。詔曰：「乃者徙泰畤、后土于南郊、北郊，朕親飭躬，郊祀上帝。〔一〕皇天報應，神光並見。三輔長無共張繇役之勞，〔二〕赦奉郊縣長安、長陵〔三〕及中都官耐罪徒。〔四〕減天下賦錢，算四十。」〔五〕","sentenceOrder":42},
  {"id":"s_work_han_thu_11_43","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「飭，整也，讀與敕同。」","sentenceOrder":43},
  {"id":"s_work_han_thu_11_44","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「共音居用反。張音竹亮反。謂供具張設。他皆類此。」","sentenceOrder":44},
  {"id":"s_work_han_thu_11_45","chapterId":"ch_work_han_thu_11","textTraditional":"〔三〕　應劭曰：「天郊在長安城南，地郊在長安城北長陵界中。二縣有奉郊之勤，故一切並赦之。」","sentenceOrder":45},
  {"id":"s_work_han_thu_11_46","chapterId":"ch_work_han_thu_11","textTraditional":"〔四〕　師古曰：「中都官，京師諸官府。」","sentenceOrder":46},
  {"id":"s_work_han_thu_11_47","chapterId":"ch_work_han_thu_11","textTraditional":"〔五〕　孟康曰：「本算百二十，今減四十，為八十。」","sentenceOrder":47},
  {"id":"s_work_han_thu_11_48","chapterId":"ch_work_han_thu_11","textTraditional":"閏月，以渭城延陵亭部為初陵。","sentenceOrder":48},
  {"id":"s_work_han_thu_11_49","chapterId":"ch_work_han_thu_11","textTraditional":"二月，詔三輔內郡舉賢良方正各一人。〔一〕","sentenceOrder":49},
  {"id":"s_work_han_thu_11_50","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「內郡，謂非邊郡。」","sentenceOrder":50},
  {"id":"s_work_han_thu_11_51","chapterId":"ch_work_han_thu_11","textTraditional":"三月，北宮井水溢出。","sentenceOrder":51},
  {"id":"s_work_han_thu_11_52","chapterId":"ch_work_han_thu_11","textTraditional":"辛丑，上始祠后土于北郊。","sentenceOrder":52},
  {"id":"s_work_han_thu_11_53","chapterId":"ch_work_han_thu_11","textTraditional":"丙午，立皇后許氏。〔一〕","sentenceOrder":53},
  {"id":"s_work_han_thu_11_54","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「許嘉女。」","sentenceOrder":54},
  {"id":"s_work_han_thu_11_55","chapterId":"ch_work_han_thu_11","textTraditional":"罷六廄、技巧官。〔一〕","sentenceOrder":55},
  {"id":"s_work_han_thu_11_56","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　服虔曰：「倡技巧者也。」師古曰：「謂巧藝之技耳，非倡樂之技也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_11_57","chapterId":"ch_work_han_thu_11","textTraditional":"夏，大旱。","sentenceOrder":57},
  {"id":"s_work_han_thu_11_58","chapterId":"ch_work_han_thu_11","textTraditional":"東平王宇有罪，削樊、亢父縣。〔一〕","sentenceOrder":58},
  {"id":"s_work_han_thu_11_59","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「樊及亢父，東平之二縣也。亢音抗。父音甫。」","sentenceOrder":59},
  {"id":"s_work_han_thu_11_60","chapterId":"ch_work_han_thu_11","textTraditional":"秋，罷太子博望苑，〔一〕以賜宗室朝請者。〔二〕減乘輿廄馬。","sentenceOrder":60},
  {"id":"s_work_han_thu_11_61","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　文穎曰：「武帝為衛太子作此苑，令受賓客也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_11_62","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「請音才性反。」","sentenceOrder":62},
  {"id":"s_work_han_thu_11_63","chapterId":"ch_work_han_thu_11","textTraditional":"三年春三月，赦天下徒。賜孝弟力田爵二級。諸逋租賦所振貸勿收。","sentenceOrder":63},
  {"id":"s_work_han_thu_11_64","chapterId":"ch_work_han_thu_11","textTraditional":"秋，關內大水。七月，虒上小女陳持弓聞大水至，走入橫城門，闌入尚方掖門，〔一〕至未央宮鉤盾中。吏民驚上城。九月，詔曰：「乃者郡國被水災，流殺人民，多至千數。京師無故訛言大水至〔二〕，吏民驚恐，奔走乘城。〔三〕殆苛暴深刻之吏未息，元元冤失職者眾。〔四〕遣諫大夫林等循行天下。」〔五〕","sentenceOrder":64},
  {"id":"s_work_han_thu_11_65","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　服虔曰：「虒音斯。」應劭曰：「虒上，地名，在渭水邊。陳，姓也。持弓，名也。無符籍妄入宮曰闌。掖門者，正門之傍小門也。」如淳曰：「橫音光。三輔黃圖北面西頭第一門。」師古曰：「掖門在兩傍，言如人臂掖也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_11_66","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「訛，偽言。」","sentenceOrder":66},
  {"id":"s_work_han_thu_11_67","chapterId":"ch_work_han_thu_11","textTraditional":"〔三〕　師古曰：「乘，登也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_11_68","chapterId":"ch_work_han_thu_11","textTraditional":"〔四〕　師古曰：「職，常也。失其常業。」","sentenceOrder":68},
  {"id":"s_work_han_thu_11_69","chapterId":"ch_work_han_thu_11","textTraditional":"〔五〕　師古曰：「行音下更反。」","sentenceOrder":69},
  {"id":"s_work_han_thu_11_70","chapterId":"ch_work_han_thu_11","textTraditional":"冬十二月戊申朔，日有蝕之。夜，地震未央宮殿中。詔曰：「蓋聞天生眾民，不能相治，為之立君以統理之。君道得，則草木昆蟲咸得其所；〔一〕人君不德，謫見天地，〔二〕災異婁發，以告不治。〔三〕朕涉道日寡，舉錯不中，〔四〕乃戊申日蝕地震，朕甚懼焉。公卿其各思朕過失，明白陳之。『女無面從，退有後言。』〔五〕丞相、御史與將軍、列侯、中二千石及內郡國舉賢良方正能直言極諫之士，詣公車，朕將覽焉。」","sentenceOrder":70},
  {"id":"s_work_han_thu_11_71","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「昆，眾也。昆蟲，言眾蟲也。又許慎說文云『二虫為〈虫虫〉，讀與昆同，謂蟲之總名，兩義並通。而鄭康成以昆蟲為明蟲，失之矣。虫音許尾反。」","sentenceOrder":71},
  {"id":"s_work_han_thu_11_72","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「言天地見變，所以責之。」","sentenceOrder":72},
  {"id":"s_work_han_thu_11_73","chapterId":"ch_work_han_thu_11","textTraditional":"〔三〕　師古曰：「婁，古屢字也。治音丈吏反。」","sentenceOrder":73},
  {"id":"s_work_han_thu_11_74","chapterId":"ch_work_han_thu_11","textTraditional":"〔四〕　師古曰：「中，當也，音竹仲反。」","sentenceOrder":74},
  {"id":"s_work_han_thu_11_75","chapterId":"ch_work_han_thu_11","textTraditional":"〔五〕　師古曰：「虞書益稷之篇云帝曰『予違汝弼，汝無面從，退有後言』。謂我有違道，汝當正之，無得對面則順從唯唯，退後則有謗讟之言也。故此詔引之。」","sentenceOrder":75},
  {"id":"s_work_han_thu_11_76","chapterId":"ch_work_han_thu_11","textTraditional":"越嶲山崩。","sentenceOrder":76},
  {"id":"s_work_han_thu_11_77","chapterId":"ch_work_han_thu_11","textTraditional":"四年春，罷中書宦官，〔一〕初置尚書員五人。〔二〕","sentenceOrder":77},
  {"id":"s_work_han_thu_11_78","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　臣瓚曰：「漢初中人有中謁者令。孝武加中謁者令為中書謁者令，置僕射。宣帝時，任中書官弘恭為令，石顯為僕射。元帝即位數年，恭死，顯代為中書令，專權用事。至成帝乃罷其官。」","sentenceOrder":78},
  {"id":"s_work_han_thu_11_79","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「漢舊儀云尚書四人為四曹：常侍尚書主丞相御史事，二千石尚書主刺史二千石事，戶曹尚書主庶人上書事，主客尚書主外國事。成帝置五人，有三公曹，主斷獄事。」","sentenceOrder":79},
  {"id":"s_work_han_thu_11_80","chapterId":"ch_work_han_thu_11","textTraditional":"夏四月，雨雪。〔一〕","sentenceOrder":80},
  {"id":"s_work_han_thu_11_81","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「雨音于具反。」","sentenceOrder":81},
  {"id":"s_work_han_thu_11_82","chapterId":"ch_work_han_thu_11","textTraditional":"五月，中謁者丞陳臨殺司隸校尉轅豐於殿中。〔一〕","sentenceOrder":82},
  {"id":"s_work_han_thu_11_83","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　應劭曰：「豐為長安令，治有能名，擢拜司隸校尉。臨素與豐有怨，見其尊顯，畏為己害，拜訖未出，使人刺殺。」","sentenceOrder":83},
  {"id":"s_work_han_thu_11_84","chapterId":"ch_work_han_thu_11","textTraditional":"秋，桃李實。大水，河決東郡金隄。〔一〕冬十月，御史大夫尹忠以河決不憂職，自殺。","sentenceOrder":84},
  {"id":"s_work_han_thu_11_85","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「金隄者，河隄之名，今在滑州界。」","sentenceOrder":85},
  {"id":"s_work_han_thu_11_86","chapterId":"ch_work_han_thu_11","textTraditional":"河平元年春三月，詔曰：「河決東郡，流漂二州，〔一〕校尉王延世隄塞輒平，其改元為河平。賜天下吏民爵，各有差。」","sentenceOrder":86},
  {"id":"s_work_han_thu_11_87","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「兗州、豫州之地。」","sentenceOrder":87},
  {"id":"s_work_han_thu_11_88","chapterId":"ch_work_han_thu_11","textTraditional":"夏四月己亥晦，日有蝕之，既。詔曰：「朕獲保宗廟，戰戰栗栗，未能奉稱。〔一〕傳曰：『男教不修，陽事不得，則日為之蝕。』天著厥異，辜在朕躬。公卿大夫其勉悉心，以輔不逮。〔二〕百寮各修其職，惇任仁人，退遠殘賊。〔三〕陳朕過失，無有所諱。」大赦天下。","sentenceOrder":88},
  {"id":"s_work_han_thu_11_89","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「謂不副先帝之業。」","sentenceOrder":89},
  {"id":"s_work_han_thu_11_90","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「悉，盡也。逮，及也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_11_91","chapterId":"ch_work_han_thu_11","textTraditional":"〔三〕　師古曰：「惇，厚也。遠，離也。遠音于萬反。」","sentenceOrder":91},
  {"id":"s_work_han_thu_11_92","chapterId":"ch_work_han_thu_11","textTraditional":"六月，罷典屬國并大鴻臚。","sentenceOrder":92},
  {"id":"s_work_han_thu_11_93","chapterId":"ch_work_han_thu_11","textTraditional":"秋九月，復太上皇寢廟園。","sentenceOrder":93},
  {"id":"s_work_han_thu_11_94","chapterId":"ch_work_han_thu_11","textTraditional":"二年春正月，沛郡鐵官冶鐵飛。語在五行志。","sentenceOrder":94},
  {"id":"s_work_han_thu_11_95","chapterId":"ch_work_han_thu_11","textTraditional":"夏六月，封舅譚、商、立、根、逢時皆為列侯。","sentenceOrder":95},
  {"id":"s_work_han_thu_11_96","chapterId":"ch_work_han_thu_11","textTraditional":"三年春二月丙戌，犍為地震山崩，〔一〕雍江水，水逆流。〔二〕","sentenceOrder":96},
  {"id":"s_work_han_thu_11_97","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「犍音其言反，又其連反。」","sentenceOrder":97},
  {"id":"s_work_han_thu_11_98","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「雍音壅。其下皆同。」","sentenceOrder":98},
  {"id":"s_work_han_thu_11_99","chapterId":"ch_work_han_thu_11","textTraditional":"秋八月乙卯晦，日有蝕之。","sentenceOrder":99},
  {"id":"s_work_han_thu_11_100","chapterId":"ch_work_han_thu_11","textTraditional":"光祿大夫劉向校中祕書。〔一〕謁者陳農使，使求遺書於天下。〔二〕","sentenceOrder":100},
  {"id":"s_work_han_thu_11_101","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「言中以別外。」","sentenceOrder":101},
  {"id":"s_work_han_thu_11_102","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「言令陳農為使，而（吏反下使）使之求遺書也。上使音所〔吏反，下使〕讀如本字。」","sentenceOrder":102},
  {"id":"s_work_han_thu_11_103","chapterId":"ch_work_han_thu_11","textTraditional":"四年春正月，匈奴單于來朝。","sentenceOrder":103},
  {"id":"s_work_han_thu_11_104","chapterId":"ch_work_han_thu_11","textTraditional":"赦天下徒，賜孝弟力田爵二級，諸逋租賦所振貸勿收。","sentenceOrder":104},
  {"id":"s_work_han_thu_11_105","chapterId":"ch_work_han_thu_11","textTraditional":"二月，單于罷歸國。","sentenceOrder":105},
  {"id":"s_work_han_thu_11_106","chapterId":"ch_work_han_thu_11","textTraditional":"三月癸丑朔，日有蝕之。","sentenceOrder":106},
  {"id":"s_work_han_thu_11_107","chapterId":"ch_work_han_thu_11","textTraditional":"遣光祿大夫博士嘉等十一人行舉瀕河之郡〔一〕水所毀傷困乏不能自存者，財振貸。〔二〕其為水所流壓死，不能自葬，令郡國給槥櫝葬埋。〔三〕已葬者與錢，人二千。避水它郡國，在所冗食之〔四〕，謹遇以文理，無令失職。〔五〕舉惇厚有行能直言之士。","sentenceOrder":107},
  {"id":"s_work_han_thu_11_108","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「巡行而舉其狀也。瀕，水厓也。瀕河，言傍河也。行音下更反。瀕音頻，又音賓。傍音步浪反。」","sentenceOrder":108},
  {"id":"s_work_han_thu_11_109","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「財與裁同，謂量其等差而振貸之。」","sentenceOrder":109},
  {"id":"s_work_han_thu_11_110","chapterId":"ch_work_han_thu_11","textTraditional":"〔三〕　師古曰：「槥櫝謂小棺。槥音衛。櫝音讀。」","sentenceOrder":110},
  {"id":"s_work_han_thu_11_111","chapterId":"ch_work_han_thu_11","textTraditional":"〔四〕　文穎曰：「冗，散也。散廩食使生活，不占著戶給役使也。」如淳曰：「散著人間給食之，官償其直也。」師古曰：「文說是也。冗音如勇反。食讀曰飤。」","sentenceOrder":111},
  {"id":"s_work_han_thu_11_112","chapterId":"ch_work_han_thu_11","textTraditional":"〔五〕　師古曰：「勿使失其常理。」","sentenceOrder":112},
  {"id":"s_work_han_thu_11_113","chapterId":"ch_work_han_thu_11","textTraditional":"壬申，長陵臨涇岸崩，雍涇水。","sentenceOrder":113},
  {"id":"s_work_han_thu_11_114","chapterId":"ch_work_han_thu_11","textTraditional":"夏六月庚戌，楚王囂薨。","sentenceOrder":114},
  {"id":"s_work_han_thu_11_115","chapterId":"ch_work_han_thu_11","textTraditional":"山陽火生石中，改元為陽朔。","sentenceOrder":115},
  {"id":"s_work_han_thu_11_116","chapterId":"ch_work_han_thu_11","textTraditional":"陽朔元年。〔一〕","sentenceOrder":116},
  {"id":"s_work_han_thu_11_117","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　應劭曰：「時陰盛陽微，故改元曰陽朔，欲陽之蘇息也。」師古曰：「應說非也。朔，始也。以火生石中，言陽氣之始。」","sentenceOrder":117},
  {"id":"s_work_han_thu_11_118","chapterId":"ch_work_han_thu_11","textTraditional":"春二月丁未晦，日有蝕之。","sentenceOrder":118},
  {"id":"s_work_han_thu_11_119","chapterId":"ch_work_han_thu_11","textTraditional":"三月，赦天下徒。","sentenceOrder":119},
  {"id":"s_work_han_thu_11_120","chapterId":"ch_work_han_thu_11","textTraditional":"冬，京兆尹王章有罪，下獄死。","sentenceOrder":120},
  {"id":"s_work_han_thu_11_121","chapterId":"ch_work_han_thu_11","textTraditional":"二年春，寒。詔曰：「昔在帝堯立羲、和之官，〔一〕命以四時之事，令不失其序。故書云『黎民於蕃時雍』，〔二〕明以陰陽為本也。今公卿大夫或不信陰陽，薄而小之，〔三〕所奏請多違時政〔四〕。傳以不知，周行天下，〔五〕而欲望陰陽和調，豈不謬哉！其務順四時月令。」","sentenceOrder":121},
  {"id":"s_work_han_thu_11_122","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　應劭曰：「尚書堯典曰『乃命羲、和』。羲氏、和氏世掌天地之官。」","sentenceOrder":122},
  {"id":"s_work_han_thu_11_123","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　應劭曰：「黎，眾也。時，是也。雍，和也。言眾民於是變化，用是太和也。」韋昭曰：「蕃，多也。」師古曰：「此虞書堯典之辭也。今尚書作變，而此紀作蕃，兩說並通。蕃音扶元反。」","sentenceOrder":123},
  {"id":"s_work_han_thu_11_124","chapterId":"ch_work_han_thu_11","textTraditional":"〔三〕　師古曰：「謂為輕小之事也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_11_125","chapterId":"ch_work_han_thu_11","textTraditional":"〔四〕　李奇曰：「時政，月令也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_11_126","chapterId":"ch_work_han_thu_11","textTraditional":"〔五〕　如淳曰：「在位者皆不知陰陽時政，轉轉相因，故令後人遂不知也。」師古曰：「如說非也。言遞相因循，以所不知之事施設教命，周遍天下。」","sentenceOrder":126},
  {"id":"s_work_han_thu_11_127","chapterId":"ch_work_han_thu_11","textTraditional":"三月，大赦天下。","sentenceOrder":127},
  {"id":"s_work_han_thu_11_128","chapterId":"ch_work_han_thu_11","textTraditional":"夏五月，除吏八百石、五百石秩。〔一〕","sentenceOrder":128},
  {"id":"s_work_han_thu_11_129","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　李奇曰：「除八百就六百，除五百就四百。」","sentenceOrder":129},
  {"id":"s_work_han_thu_11_130","chapterId":"ch_work_han_thu_11","textTraditional":"秋，關東大水，流民欲入函谷、天井、壺口、五阮關者，勿苛留。〔一〕遣諫大夫博士分行視。〔二〕","sentenceOrder":130},
  {"id":"s_work_han_thu_11_131","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　應劭曰：「天井在上黨高都。壺口在壺關。五阮在代郡。」如淳曰：「阮音近捲反。」師古曰：「苛，細刻也。阮音其遠反。苛音何。」","sentenceOrder":131},
  {"id":"s_work_han_thu_11_132","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「行音下更反。」","sentenceOrder":132},
  {"id":"s_work_han_thu_11_133","chapterId":"ch_work_han_thu_11","textTraditional":"八月甲申，定陶王康薨。","sentenceOrder":133},
  {"id":"s_work_han_thu_11_134","chapterId":"ch_work_han_thu_11","textTraditional":"九月，奉使者不稱。〔一〕詔曰：「古之立太學，將以傳先王之業，流化於天下也。儒林之官，四海淵原，宜皆明於古今，溫故知新，通達國體，〔二〕故謂之博士。否則學者無述焉，為下所輕，非所以尊道德也。『工欲善其事，必先利其器。』〔三〕丞相、御史其與中二千石、二千石雜舉可充博士位者，使卓然可觀。」〔四〕","sentenceOrder":134},
  {"id":"s_work_han_thu_11_135","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「不副上意。」","sentenceOrder":135},
  {"id":"s_work_han_thu_11_136","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「溫，厚也，謂厚積於故事也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_11_137","chapterId":"ch_work_han_thu_11","textTraditional":"〔三〕　師古曰：「論語載孔子之言也，故此詔引焉。」","sentenceOrder":137},
  {"id":"s_work_han_thu_11_138","chapterId":"ch_work_han_thu_11","textTraditional":"〔四〕　師古曰：「卓然，高遠之貌也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_11_139","chapterId":"ch_work_han_thu_11","textTraditional":"是歲，御史大夫張忠卒。〔一〕","sentenceOrder":139},
  {"id":"s_work_han_thu_11_140","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「史不記其月，故書之於歲末。其下王駿亦同。」","sentenceOrder":140},
  {"id":"s_work_han_thu_11_141","chapterId":"ch_work_han_thu_11","textTraditional":"三年春三月壬戌，隕石東郡，八。","sentenceOrder":141},
  {"id":"s_work_han_thu_11_142","chapterId":"ch_work_han_thu_11","textTraditional":"夏六月，潁川鐵官徒申屠聖等百八十人殺長吏，盜庫兵，自稱將軍，經歷九郡。遣丞相長史、御史中丞逐捕，以軍興從事，皆伏辜。〔一〕","sentenceOrder":142},
  {"id":"s_work_han_thu_11_143","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「逐捕之事須有發興，皆依軍法。」","sentenceOrder":143},
  {"id":"s_work_han_thu_11_144","chapterId":"ch_work_han_thu_11","textTraditional":"秋八月丁巳，大司馬大將軍王鳳薨。","sentenceOrder":144},
  {"id":"s_work_han_thu_11_145","chapterId":"ch_work_han_thu_11","textTraditional":"四年春正月，詔曰：「夫洪範八政，以食為首，〔一〕斯誠家給刑錯之本也。〔二〕先帝劭農，〔三〕薄其租稅，寵其彊力，〔四〕令與孝弟同科。〔五〕間者，民彌惰怠，鄉本者少，趨末者眾，將何以矯之？〔六〕方東作時，〔七〕其令二千石勉勸農桑，出入阡陌，致勞來之。〔八〕書不云乎？『服田力嗇，乃亦有秋。』〔九〕其勗之哉！」","sentenceOrder":145},
  {"id":"s_work_han_thu_11_146","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「洪範，尚書篇名，箕子為周武王所說。洪，大也。範，法也。八政一曰食，蓋王政之所先，故以為首。」","sentenceOrder":146},
  {"id":"s_work_han_thu_11_147","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「言倉廩充盈，則家家自足，人不犯禁，無所用刑也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_11_148","chapterId":"ch_work_han_thu_11","textTraditional":"〔三〕　蘇林曰：「劭音翹，精異之意也。」晉灼曰：「劭，勸勉也。」師古曰：「晉說是也。其字從力，音時召反。」","sentenceOrder":148},
  {"id":"s_work_han_thu_11_149","chapterId":"ch_work_han_thu_11","textTraditional":"〔四〕　師古曰：「謂優寵力田之人。」","sentenceOrder":149},
  {"id":"s_work_han_thu_11_150","chapterId":"ch_work_han_thu_11","textTraditional":"〔五〕　師古曰：「謂每同薦舉及加賜也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_11_151","chapterId":"ch_work_han_thu_11","textTraditional":"〔六〕　師古曰：「鄉讀曰嚮。矯，正也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_11_152","chapterId":"ch_work_han_thu_11","textTraditional":"〔七〕　應劭曰：「東作，耕也。」師古曰：「春位在東，耕者始作，故曰東作。虞書堯典曰『平秩東作』。」","sentenceOrder":152},
  {"id":"s_work_han_thu_11_153","chapterId":"ch_work_han_thu_11","textTraditional":"〔八〕　師古曰：「阡陌，田間道也，南北曰阡，東西曰陌，蓋秦時商鞅所開也。勞來，勸勉之意也。勞音郎到反。來音郎代反。」","sentenceOrder":153},
  {"id":"s_work_han_thu_11_154","chapterId":"ch_work_han_thu_11","textTraditional":"〔九〕　應劭曰：「農夫服田，厲其膂力，乃有秋收也。」師古曰：「此商書盤庚之辭。」","sentenceOrder":154},
  {"id":"s_work_han_thu_11_155","chapterId":"ch_work_han_thu_11","textTraditional":"二月，赦天下。","sentenceOrder":155},
  {"id":"s_work_han_thu_11_156","chapterId":"ch_work_han_thu_11","textTraditional":"秋九月壬申，東平王宇薨。","sentenceOrder":156},
  {"id":"s_work_han_thu_11_157","chapterId":"ch_work_han_thu_11","textTraditional":"閏月壬戌，御史大夫于永卒。〔一〕","sentenceOrder":157},
  {"id":"s_work_han_thu_11_158","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「于定國子。」","sentenceOrder":158},
  {"id":"s_work_han_thu_11_159","chapterId":"ch_work_han_thu_11","textTraditional":"鴻嘉元年春二月，詔曰：「朕承天地，獲保宗廟，明有所蔽，德不能綏，刑罰不中，眾冤失職，趨闕告訴者不絕。是以陰陽錯謬，寒暑失序，〔一〕日月不光，百姓蒙辜，朕甚閔焉。〔二〕書不云乎？『即我御事，罔克耆壽，咎在厥躬。』〔三〕方春生長時，臨遣諫大夫理等〔四〕舉三輔、三河、弘農冤獄。公卿大夫、部刺史明申敕守相，稱朕意焉。其賜天下民爵一級，女子百戶牛酒，加賜鰥寡孤獨高年帛。逋貸未入者勿收。」","sentenceOrder":159},
  {"id":"s_work_han_thu_11_160","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「序，次也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_11_161","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「蒙，被也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_11_162","chapterId":"ch_work_han_thu_11","textTraditional":"〔三〕　文穎曰：「此尚書文侯之命篇中辭也。言我周家用事者，無能有耆老賢者，使國之危亡，罪咎在其用事者也。」師古曰：「『咎在厥躬』，平王自謂，故帝引之以自責耳。文氏乃云咎在用事，斯失之矣。」","sentenceOrder":162},
  {"id":"s_work_han_thu_11_163","chapterId":"ch_work_han_thu_11","textTraditional":"〔四〕　師古曰：「天子自臨敕而遣。」","sentenceOrder":163},
  {"id":"s_work_han_thu_11_164","chapterId":"ch_work_han_thu_11","textTraditional":"壬午，行幸初陵，赦作徒。〔一〕以新豐戲鄉為昌陵縣，〔二〕奉初陵，賜百戶牛酒。","sentenceOrder":164},
  {"id":"s_work_han_thu_11_165","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「徒人之在陵作役者。」","sentenceOrder":165},
  {"id":"s_work_han_thu_11_166","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「戲水之鄉也，音許宜反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_11_167","chapterId":"ch_work_han_thu_11","textTraditional":"上始為微行出。〔一〕","sentenceOrder":167},
  {"id":"s_work_han_thu_11_168","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　張晏曰：「於後門出，從期門郎及私奴客十餘人。白衣組幘，單騎出入市里，不復警蹕，若微賤之所為，故曰微行。」","sentenceOrder":168},
  {"id":"s_work_han_thu_11_169","chapterId":"ch_work_han_thu_11","textTraditional":"冬，黃龍見真定。〔一〕","sentenceOrder":169},
  {"id":"s_work_han_thu_11_170","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「本趙國東垣縣也，高祖十一年更名真定。」","sentenceOrder":170},
  {"id":"s_work_han_thu_11_171","chapterId":"ch_work_han_thu_11","textTraditional":"二年春，行幸雲陽。","sentenceOrder":171},
  {"id":"s_work_han_thu_11_172","chapterId":"ch_work_han_thu_11","textTraditional":"三月，博士行飲酒禮，有雉蜚集于庭，歷階升堂而雊，〔一〕後集諸府，又集承明殿。〔二〕","sentenceOrder":172},
  {"id":"s_work_han_thu_11_173","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「蜚，古飛字也。歷階，謂以次而登也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_11_174","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「在未央宮中。」","sentenceOrder":174},
  {"id":"s_work_han_thu_11_175","chapterId":"ch_work_han_thu_11","textTraditional":"詔曰：「古之選賢，傅納以言，明試以功，〔一〕故官無廢事，下無逸民，〔二〕教化流行，風雨和時，百穀用成，眾庶樂業，咸以康寧。朕承鴻業十有餘年，數遭水旱疾疫之災，黎民婁困於飢寒〔三〕，而望禮義之興，豈不難哉！朕既無以率道，〔四〕帝王之道日以陵夷，〔五〕意乃招賢選士之路鬱滯而不通與，〔六〕將舉者未得其人也？其舉敦厚有行義能直言者，冀聞切言嘉謀，匡朕之不逮。」","sentenceOrder":175},
  {"id":"s_work_han_thu_11_176","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「傅讀曰敷。敷，陳也。令其陳言而省納之，乃試以事也。」","sentenceOrder":176},
  {"id":"s_work_han_thu_11_177","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「逸，遁也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_11_178","chapterId":"ch_work_han_thu_11","textTraditional":"〔三〕　師古曰：「婁，古屢字。」","sentenceOrder":178},
  {"id":"s_work_han_thu_11_179","chapterId":"ch_work_han_thu_11","textTraditional":"〔四〕　師古曰：「道讀曰導。」","sentenceOrder":179},
  {"id":"s_work_han_thu_11_180","chapterId":"ch_work_han_thu_11","textTraditional":"〔五〕　師古曰：「陵，丘陵也。夷，平也。言其頹替若丘陵之漸平也。又曰陵遲亦言如丘陵之逶遲，稍卑下也。他皆類此。」","sentenceOrder":180},
  {"id":"s_work_han_thu_11_181","chapterId":"ch_work_han_thu_11","textTraditional":"〔六〕　師古曰：「與讀曰歟。」","sentenceOrder":181},
  {"id":"s_work_han_thu_11_182","chapterId":"ch_work_han_thu_11","textTraditional":"夏，徙郡國豪傑貲五百萬以上五千戶于昌陵。賜丞相、御史、將軍、列侯、公主、中二千石冢地、第宅。〔一〕","sentenceOrder":182},
  {"id":"s_work_han_thu_11_183","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「並於昌陵賜之。」","sentenceOrder":183},
  {"id":"s_work_han_thu_11_184","chapterId":"ch_work_han_thu_11","textTraditional":"六月，立中山憲王孫雲客為廣德王。","sentenceOrder":184},
  {"id":"s_work_han_thu_11_185","chapterId":"ch_work_han_thu_11","textTraditional":"三年夏四月，赦天下。令吏民得買爵，賈級千錢。〔一〕","sentenceOrder":185},
  {"id":"s_work_han_thu_11_186","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「賈讀曰價。」","sentenceOrder":186},
  {"id":"s_work_han_thu_11_187","chapterId":"ch_work_han_thu_11","textTraditional":"大旱。","sentenceOrder":187},
  {"id":"s_work_han_thu_11_188","chapterId":"ch_work_han_thu_11","textTraditional":"秋八月乙卯，孝景廟闕災。","sentenceOrder":188},
  {"id":"s_work_han_thu_11_189","chapterId":"ch_work_han_thu_11","textTraditional":"冬十一月甲寅，皇后許氏廢。","sentenceOrder":189},
  {"id":"s_work_han_thu_11_190","chapterId":"ch_work_han_thu_11","textTraditional":"廣漢男子鄭躬等六十餘人攻官寺，篡囚徒，〔一〕盜庫兵，自稱山君。","sentenceOrder":190},
  {"id":"s_work_han_thu_11_191","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「逆取曰篡。」","sentenceOrder":191},
  {"id":"s_work_han_thu_11_192","chapterId":"ch_work_han_thu_11","textTraditional":"四年春正月，詔曰：「數敕有司，務行寬大，而禁苛暴，訖今不改。一人有辜，舉宗拘繫，農民失業，怨恨者眾，傷害和氣，水旱為災，關東流冗者眾，〔一〕青、幽、冀部尤劇，朕甚痛焉。未聞在位有惻然者，孰當助朕憂之！〔二〕已遣使者循行郡國。〔三〕被災害什四以上，民貲不滿三萬，勿出租賦。逋貸未入，皆勿收。流民欲入關，輒籍內。〔四〕所之郡國，謹遇以理，〔五〕務有以全活之，思稱朕意。」","sentenceOrder":192},
  {"id":"s_work_han_thu_11_193","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「冗，散失其事業也。冗音人勇反。」","sentenceOrder":193},
  {"id":"s_work_han_thu_11_194","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「孰，誰也。」","sentenceOrder":194},
  {"id":"s_work_han_thu_11_195","chapterId":"ch_work_han_thu_11","textTraditional":"〔三〕　師古曰：「行音下更反。」","sentenceOrder":195},
  {"id":"s_work_han_thu_11_196","chapterId":"ch_work_han_thu_11","textTraditional":"〔四〕　師古曰：「錄其名籍而內之。」","sentenceOrder":196},
  {"id":"s_work_han_thu_11_197","chapterId":"ch_work_han_thu_11","textTraditional":"〔五〕　師古曰：「之，往也。」","sentenceOrder":197},
  {"id":"s_work_han_thu_11_198","chapterId":"ch_work_han_thu_11","textTraditional":"秋，勃海、清河河溢，被災者振貸之。","sentenceOrder":198},
  {"id":"s_work_han_thu_11_199","chapterId":"ch_work_han_thu_11","textTraditional":"冬，廣漢鄭躬等黨與寖廣，〔一〕犯歷四縣，眾且萬人。拜河東都尉趙護為廣漢太守，發郡中及蜀郡合三萬人擊之。或相捕斬，除罪。〔二〕旬月平，遷護為執金吾，賜黃金百斤。","sentenceOrder":199},
  {"id":"s_work_han_thu_11_200","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「寖，古浸字。浸，漸也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_11_201","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「賊黨相捕斬而來者，赦其本罪。」","sentenceOrder":201},
  {"id":"s_work_han_thu_11_202","chapterId":"ch_work_han_thu_11","textTraditional":"永始元年春正月癸丑，太官凌室火。〔一〕戊午，戾后園闕火。","sentenceOrder":202},
  {"id":"s_work_han_thu_11_203","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「藏冰之室。」","sentenceOrder":203},
  {"id":"s_work_han_thu_11_204","chapterId":"ch_work_han_thu_11","textTraditional":"夏四月，封婕妤趙氏父臨為成陽侯。五月，封舅曼子侍中騎都尉光祿大夫王莽為新都侯。六月丙寅，立皇后趙氏。〔一〕大赦天下。","sentenceOrder":204},
  {"id":"s_work_han_thu_11_205","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「趙飛燕也，即上所謂婕妤趙氏。」","sentenceOrder":205},
  {"id":"s_work_han_thu_11_206","chapterId":"ch_work_han_thu_11","textTraditional":"秋七月，詔曰：「朕執德不固，謀不盡下，〔一〕過聽將作大匠萬年〔二〕言昌陵三年可成。作治五年，中陵、司馬殿門內尚未加功。〔三〕天下虛耗，〔四〕百姓罷勞，〔五〕客土疏惡，〔六〕終不可成。朕惟其難，怛然傷心。〔七〕夫『過而不改，是謂過矣。〔八〕』其罷昌陵，及故陵勿徙吏民，令天下毋有動搖之心。」立城陽孝王子俚為王。〔九〕","sentenceOrder":206},
  {"id":"s_work_han_thu_11_207","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「言不博謀於群下。」","sentenceOrder":207},
  {"id":"s_work_han_thu_11_208","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「過，誤也。萬年，解萬年也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_11_209","chapterId":"ch_work_han_thu_11","textTraditional":"〔三〕　如淳曰：「陵中有司馬殿門，如生時制也。」臣瓚曰：「天子之藏壙中無司馬殿門也。此謂陵上寢殿及司馬門也。時皆未作之，故曰尚未加功。」師古曰：「中陵，陵中正寢也。司馬殿門內，瓚說是也。」","sentenceOrder":209},
  {"id":"s_work_han_thu_11_210","chapterId":"ch_work_han_thu_11","textTraditional":"〔四〕　師古曰：「耗，損也，音呼到反。」","sentenceOrder":210},
  {"id":"s_work_han_thu_11_211","chapterId":"ch_work_han_thu_11","textTraditional":"〔五〕　師古曰：「罷讀曰疲。」","sentenceOrder":211},
  {"id":"s_work_han_thu_11_212","chapterId":"ch_work_han_thu_11","textTraditional":"〔六〕　服虔曰：「取他處土以增高，為客土也。」","sentenceOrder":212},
  {"id":"s_work_han_thu_11_213","chapterId":"ch_work_han_thu_11","textTraditional":"〔七〕　師古曰：「惟，思也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_11_214","chapterId":"ch_work_han_thu_11","textTraditional":"〔八〕　師古曰：「論語載孔子之言，故詔引之。」","sentenceOrder":214},
  {"id":"s_work_han_thu_11_215","chapterId":"ch_work_han_thu_11","textTraditional":"〔九〕　如淳曰：「俚音里。」","sentenceOrder":215},
  {"id":"s_work_han_thu_11_216","chapterId":"ch_work_han_thu_11","textTraditional":"八月丁丑，太皇太后王氏崩。〔一〕","sentenceOrder":216},
  {"id":"s_work_han_thu_11_217","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「宣帝王皇后也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_11_218","chapterId":"ch_work_han_thu_11","textTraditional":"二年春正月己丑，大司馬車騎將軍王音薨。","sentenceOrder":218},
  {"id":"s_work_han_thu_11_219","chapterId":"ch_work_han_thu_11","textTraditional":"二月癸未夜，星隕如雨。乙酉晦，日有蝕之。詔曰：「乃者，龍見于東萊，日有蝕之。天著變異，以顯朕郵，〔一〕朕甚懼焉。公卿申敕百寮，深思天誡，有可省減便安百姓者，條奏。所振貸貧民，勿收。」又曰：「關東比歲不登，〔二〕吏民以義收食貧民、入穀物助縣官振贍者，已賜直，〔三〕其百萬以上，加賜爵右更，〔四〕欲為吏補三百石，其吏也遷二等。〔五〕三十萬以上，賜爵五大夫，〔六〕吏亦遷二等，民補郎。十萬以上，家無出租賦三歲。萬錢以上，一年。」","sentenceOrder":219},
  {"id":"s_work_han_thu_11_220","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「郵與尤同，謂過也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_11_221","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「比，頻也。」","sentenceOrder":221},
  {"id":"s_work_han_thu_11_222","chapterId":"ch_work_han_thu_11","textTraditional":"〔三〕　如淳曰：「賜之爵，復租賦以為直。」師古曰：「此說非也。收食貧人，謂收取而養食之。助縣官振贍，謂出物以助郡縣之官也。已賜直，謂官賜其所費直也。今方更加爵及免賦耳。食讀曰飤。」","sentenceOrder":222},
  {"id":"s_work_han_thu_11_223","chapterId":"ch_work_han_thu_11","textTraditional":"〔四〕　師古曰：「第十四爵也。更音工行反。」","sentenceOrder":223},
  {"id":"s_work_han_thu_11_224","chapterId":"ch_work_han_thu_11","textTraditional":"〔五〕　師古曰：「先已為吏，則遷二等。」","sentenceOrder":224},
  {"id":"s_work_han_thu_11_225","chapterId":"ch_work_han_thu_11","textTraditional":"〔六〕　師古曰：「第九爵也。」","sentenceOrder":225},
  {"id":"s_work_han_thu_11_226","chapterId":"ch_work_han_thu_11","textTraditional":"冬十一月，行幸雍，祠五畤。","sentenceOrder":226},
  {"id":"s_work_han_thu_11_227","chapterId":"ch_work_han_thu_11","textTraditional":"十二月，詔曰：「前將作大匠萬年知昌陵卑下，不可為萬歲居，奏請營作，建置郭邑，妄為巧詐，積土增高，多賦斂繇役，興卒暴之作。〔一〕卒徒蒙辜，死者連屬，〔二〕百姓罷極，天下匱竭。〔三〕常侍閎前為大司農中丞，數奏昌陵不可成。〔四〕侍中衛尉長數白宜早止，徙家反故處。〔五〕朕以長言下閎章，〔六〕公卿議者皆合長計。〔長〕首建至策，閎典主省大費，〔七〕民以康寧。閎前賜爵關內侯，黃金百斤。其賜長爵關內侯，食邑千戶，閎五百戶。萬年佞邪不忠，毒流眾庶，海內怨望，至今不息，雖蒙赦令，不宜居京師。其徙萬年敦煌郡。」","sentenceOrder":227},
  {"id":"s_work_han_thu_11_228","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「卒讀曰（（暂缺F67B））〔猝〕，謂急也。」","sentenceOrder":228},
  {"id":"s_work_han_thu_11_229","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「屬音之欲反。」","sentenceOrder":229},
  {"id":"s_work_han_thu_11_230","chapterId":"ch_work_han_thu_11","textTraditional":"〔三〕　師古曰：「罷讀曰疲。匱，空也。竭，盡也。」","sentenceOrder":230},
  {"id":"s_work_han_thu_11_231","chapterId":"ch_work_han_thu_11","textTraditional":"〔四〕　師古曰：「閎，王閎也。」","sentenceOrder":231},
  {"id":"s_work_han_thu_11_232","chapterId":"ch_work_han_thu_11","textTraditional":"〔五〕　師古曰：「長，淳于長也。」","sentenceOrder":232},
  {"id":"s_work_han_thu_11_233","chapterId":"ch_work_han_thu_11","textTraditional":"〔六〕　如淳曰：「以衛尉長數白罷，故因下閎請奏罷作之章。」師古曰：「下音胡稼反。」","sentenceOrder":233},
  {"id":"s_work_han_thu_11_234","chapterId":"ch_work_han_thu_11","textTraditional":"〔七〕　師古曰：「司農中丞主錢穀顧庸，故云典主。」","sentenceOrder":234},
  {"id":"s_work_han_thu_11_235","chapterId":"ch_work_han_thu_11","textTraditional":"是歲，御史大夫王駿卒。〔一〕","sentenceOrder":235},
  {"id":"s_work_han_thu_11_236","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「王吉之子也。」","sentenceOrder":236},
  {"id":"s_work_han_thu_11_237","chapterId":"ch_work_han_thu_11","textTraditional":"三年春正月己卯晦，日有蝕之。詔曰：「天災仍重，朕甚懼焉。〔一〕惟民之失職，〔二〕臨遣大中大夫嘉等循行天下，〔三〕存問耆老，民所疾苦。其與部刺史舉惇樸遜讓有行義者各一人。」","sentenceOrder":237},
  {"id":"s_work_han_thu_11_238","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「仍，頻也。重音直用反。」","sentenceOrder":238},
  {"id":"s_work_han_thu_11_239","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「失其常業也。」","sentenceOrder":239},
  {"id":"s_work_han_thu_11_240","chapterId":"ch_work_han_thu_11","textTraditional":"〔三〕　師古曰：「行音下更反。」","sentenceOrder":240},
  {"id":"s_work_han_thu_11_241","chapterId":"ch_work_han_thu_11","textTraditional":"冬十月庚辰，皇太后詔有司復甘泉泰畤、汾陰后土、雍五畤、陳倉陳寶祠。〔一〕語在郊祀志。","sentenceOrder":241},
  {"id":"s_work_han_thu_11_242","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「陳寶祠在陳倉。」","sentenceOrder":242},
  {"id":"s_work_han_thu_11_243","chapterId":"ch_work_han_thu_11","textTraditional":"十一月，尉氏男子樊並等十三人謀反，〔一〕殺陳留太守，劫略吏民，自稱將軍。徒李譚等五人共格殺並等，皆封為列侯。","sentenceOrder":243},
  {"id":"s_work_han_thu_11_244","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「尉氏，陳留之縣。」","sentenceOrder":244},
  {"id":"s_work_han_thu_11_245","chapterId":"ch_work_han_thu_11","textTraditional":"十二月，山陽鐵官徒蘇令等二百二十八人攻殺長吏，盜庫兵，自稱將軍，經歷郡國十九，殺東郡太守、汝南都尉。遣丞相長史、御史中丞持節督趣逐捕。〔一〕汝南太守嚴訢捕斬令等。〔二〕遷訢為大司農，賜黃金百斤。","sentenceOrder":245},
  {"id":"s_work_han_thu_11_246","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「趣讀曰促。」","sentenceOrder":246},
  {"id":"s_work_han_thu_11_247","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「訢與欣同。令即蘇令。」","sentenceOrder":247},
  {"id":"s_work_han_thu_11_248","chapterId":"ch_work_han_thu_11","textTraditional":"四年春正月，行幸甘泉，郊泰畤，神光降集紫殿。大赦天下。賜雲陽吏民爵，女子百戶牛酒，鰥寡孤獨高年帛。三月，行幸河東，祠后土，賜吏民如雲陽，行所過無出田租。","sentenceOrder":248},
  {"id":"s_work_han_thu_11_249","chapterId":"ch_work_han_thu_11","textTraditional":"夏四月癸未，長樂臨華殿、未央宮東司馬門皆災。〔一〕","sentenceOrder":249},
  {"id":"s_work_han_thu_11_250","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「東面之司馬門也。」","sentenceOrder":250},
  {"id":"s_work_han_thu_11_251","chapterId":"ch_work_han_thu_11","textTraditional":"六月甲午，霸陵園門闕災。出杜陵諸未嘗御者歸家。詔曰：「乃者，地震京師，火災婁降，〔一〕朕甚懼之。有司其悉心明對厥咎，〔二〕朕將親覽焉。」","sentenceOrder":251},
  {"id":"s_work_han_thu_11_252","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「婁，古屢字。」","sentenceOrder":252},
  {"id":"s_work_han_thu_11_253","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「悉，盡也。」","sentenceOrder":253},
  {"id":"s_work_han_thu_11_254","chapterId":"ch_work_han_thu_11","textTraditional":"又曰：「聖王明禮制以序尊卑，異車服以章有德，雖有其財，而無其尊，不得踰制，故民興行，〔一〕上義而下利。〔二〕方今世俗奢僭罔極，〔三〕靡有厭足。公卿列侯親屬近臣，四方所則，〔四〕未聞修身遵禮，同心憂國者也。或乃奢侈逸豫，務廣第宅，治園池，多畜奴婢，被服綺穀，〔五〕設鐘鼓，備女樂，車服嫁娶葬埋過制。吏民慕效，〈寖，中“彐改帚”〉以成俗，〔六〕而欲望百姓儉節，家給人足，豈不難哉！詩不云乎？『赫赫師尹，民具爾瞻。』〔七〕其申敕有司，以漸禁之。〔八〕青綠民所常服，且勿止。〔九〕列侯近臣，各自省改〔一０〕。司隸校尉察不變者。」","sentenceOrder":254},
  {"id":"s_work_han_thu_11_255","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「行音下更反。」","sentenceOrder":255},
  {"id":"s_work_han_thu_11_256","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「以義為上，以利為下。」","sentenceOrder":256},
  {"id":"s_work_han_thu_11_257","chapterId":"ch_work_han_thu_11","textTraditional":"〔三〕　師古曰：「罔，無也。極，中也，一曰止也。」","sentenceOrder":257},
  {"id":"s_work_han_thu_11_258","chapterId":"ch_work_han_thu_11","textTraditional":"〔四〕　師古曰：「則，法也。」","sentenceOrder":258},
  {"id":"s_work_han_thu_11_259","chapterId":"ch_work_han_thu_11","textTraditional":"〔五〕　師古曰：「被音皮義反。」","sentenceOrder":259},
  {"id":"s_work_han_thu_11_260","chapterId":"ch_work_han_thu_11","textTraditional":"〔六〕　師古曰：「〈寖，中“彐改帚”〉，漸也。」","sentenceOrder":260},
  {"id":"s_work_han_thu_11_261","chapterId":"ch_work_han_thu_11","textTraditional":"〔七〕　師古曰：「小雅節南山之詩也。赫赫，盛貌也。師尹，尹氏為太師之官也。言居位甚高，備為眾庶所瞻仰。」","sentenceOrder":261},
  {"id":"s_work_han_thu_11_262","chapterId":"ch_work_han_thu_11","textTraditional":"〔八〕　師古曰：「謂約束也。」","sentenceOrder":262},
  {"id":"s_work_han_thu_11_263","chapterId":"ch_work_han_thu_11","textTraditional":"〔九〕　師古曰：「然則禁紅紫之屬。」","sentenceOrder":263},
  {"id":"s_work_han_thu_11_264","chapterId":"ch_work_han_thu_11","textTraditional":"〔一０〕師古曰：「省，視也。視而改之。論語稱曾子曰『吾日三省吾身』。」","sentenceOrder":264},
  {"id":"s_work_han_thu_11_265","chapterId":"ch_work_han_thu_11","textTraditional":"秋七月辛未晦，日有蝕之。","sentenceOrder":265},
  {"id":"s_work_han_thu_11_266","chapterId":"ch_work_han_thu_11","textTraditional":"元延元年春正月己亥朔，日有蝕之。","sentenceOrder":266},
  {"id":"s_work_han_thu_11_267","chapterId":"ch_work_han_thu_11","textTraditional":"三月，行幸雍，祠五畤。","sentenceOrder":267},
  {"id":"s_work_han_thu_11_268","chapterId":"ch_work_han_thu_11","textTraditional":"夏四月丁酉，無雲有雷，聲光耀耀，四面下至地，昏止。赦天下。","sentenceOrder":268},
  {"id":"s_work_han_thu_11_269","chapterId":"ch_work_han_thu_11","textTraditional":"秋七月，有星孛于東井。詔曰：「乃者，日蝕星隕，謫見于天，大異重仍。〔一〕在位默然，罕有忠言。今孛星見于東井，朕甚懼焉。公卿大夫、博士、議郎其各悉心，惟思變意，明以經對，無有所諱；與內郡國舉方正能直言極諫者各一人，〔二〕北邊二十二郡舉勇猛知兵法者各一人。」","sentenceOrder":269},
  {"id":"s_work_han_thu_11_270","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「仍，頻也。重音直用反。」","sentenceOrder":270},
  {"id":"s_work_han_thu_11_271","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「令公卿與內郡國各舉一人。」","sentenceOrder":271},
  {"id":"s_work_han_thu_11_272","chapterId":"ch_work_han_thu_11","textTraditional":"封蕭相國後喜為酇侯。","sentenceOrder":272},
  {"id":"s_work_han_thu_11_273","chapterId":"ch_work_han_thu_11","textTraditional":"冬十二月辛亥，大司馬大將軍王商薨。","sentenceOrder":273},
  {"id":"s_work_han_thu_11_274","chapterId":"ch_work_han_thu_11","textTraditional":"是歲，昭儀趙氏害後宮皇子。〔一〕","sentenceOrder":274},
  {"id":"s_work_han_thu_11_275","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「趙飛燕之妹。」","sentenceOrder":275},
  {"id":"s_work_han_thu_11_276","chapterId":"ch_work_han_thu_11","textTraditional":"二年春正月，行幸甘泉，郊泰畤。","sentenceOrder":276},
  {"id":"s_work_han_thu_11_277","chapterId":"ch_work_han_thu_11","textTraditional":"三月，行幸河東，祠后土。","sentenceOrder":277},
  {"id":"s_work_han_thu_11_278","chapterId":"ch_work_han_thu_11","textTraditional":"夏四月，立廣陵孝王子守為王。","sentenceOrder":278},
  {"id":"s_work_han_thu_11_279","chapterId":"ch_work_han_thu_11","textTraditional":"冬，行幸長楊宮，從胡客大校獵。〔一〕宿萯陽宮，〔二〕賜從官。","sentenceOrder":279},
  {"id":"s_work_han_thu_11_280","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　如淳曰：「合軍聚眾，有幡校擊鼓也。周禮校人掌王田獵之馬，故謂之校獵。」師古曰：「如說非也。此校謂以木自相貫穿為闌校耳。校人職云『六廄成校』，是則以遮闌為義也。校獵者，大為闌校以遮禽獸而獵取也。軍之幡旗雖有校名，本因部校，此無豫也。」","sentenceOrder":280},
  {"id":"s_work_han_thu_11_281","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「萯音倍。」","sentenceOrder":281},
  {"id":"s_work_han_thu_11_282","chapterId":"ch_work_han_thu_11","textTraditional":"三年春正月丙寅，蜀郡岷山崩，〔一〕雍江三日，江水竭。","sentenceOrder":282},
  {"id":"s_work_han_thu_11_283","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「岷音武巾反。」","sentenceOrder":283},
  {"id":"s_work_han_thu_11_284","chapterId":"ch_work_han_thu_11","textTraditional":"二月，封侍中衛尉淳于長為定陵侯。","sentenceOrder":284},
  {"id":"s_work_han_thu_11_285","chapterId":"ch_work_han_thu_11","textTraditional":"三月，行幸雍，祠五畤。","sentenceOrder":285},
  {"id":"s_work_han_thu_11_286","chapterId":"ch_work_han_thu_11","textTraditional":"四年春正月，行幸甘泉，郊泰畤。","sentenceOrder":286},
  {"id":"s_work_han_thu_11_287","chapterId":"ch_work_han_thu_11","textTraditional":"二月，罷司隸校尉官。","sentenceOrder":287},
  {"id":"s_work_han_thu_11_288","chapterId":"ch_work_han_thu_11","textTraditional":"三月，行幸河東，祠后土。","sentenceOrder":288},
  {"id":"s_work_han_thu_11_289","chapterId":"ch_work_han_thu_11","textTraditional":"甘露降京師，賜長安民牛酒。","sentenceOrder":289},
  {"id":"s_work_han_thu_11_290","chapterId":"ch_work_han_thu_11","textTraditional":"綏和元年春正月，大赦天下。","sentenceOrder":290},
  {"id":"s_work_han_thu_11_291","chapterId":"ch_work_han_thu_11","textTraditional":"二月癸丑，詔曰：「朕承太祖鴻業，奉宗廟二十五年，德不能綏理宇內，百姓怨望者眾。不蒙天祐，至今未有繼嗣，天下無所係心。觀于往古近事之戒，禍亂之萌，皆由斯焉。〔一〕定陶王欣於朕為子，慈仁孝順，可以承天序，繼祭祀。其立欣為皇太子。封中山王舅諫大夫馮參為宜鄉侯，益中山國三萬戶，以慰其意。〔二〕賜諸侯王、列侯金，天下當為父後者爵，三老、孝弟力田帛，各有差。」","sentenceOrder":291},
  {"id":"s_work_han_thu_11_292","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「始生曰萌。」","sentenceOrder":292},
  {"id":"s_work_han_thu_11_293","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「以不得繼統為帝之後，恐其怨恨。」","sentenceOrder":293},
  {"id":"s_work_han_thu_11_294","chapterId":"ch_work_han_thu_11","textTraditional":"又曰：「蓋聞王者必存二王之後，所以通三統也。〔一〕昔成湯受命，列為三代，〔二〕而祭祀廢絕。考求其後，莫正孔吉。〔三〕其封吉為殷紹嘉侯。」三月，進爵為公，及周承休侯皆為公，地各百里。","sentenceOrder":294},
  {"id":"s_work_han_thu_11_295","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「天、地、人是為三統。二王之後並己為三。」","sentenceOrder":295},
  {"id":"s_work_han_thu_11_296","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「夏、殷、周是為三代。」","sentenceOrder":296},
  {"id":"s_work_han_thu_11_297","chapterId":"ch_work_han_thu_11","textTraditional":"〔三〕　臣瓚曰：「無若孔吉最正也。」","sentenceOrder":297},
  {"id":"s_work_han_thu_11_298","chapterId":"ch_work_han_thu_11","textTraditional":"行幸雍，祠五畤。","sentenceOrder":298},
  {"id":"s_work_han_thu_11_299","chapterId":"ch_work_han_thu_11","textTraditional":"夏四月，以大司馬票騎（大）將軍（根）為大司馬，〔一〕罷將軍官。御史大夫為大司空，封為列侯。益大司馬、大司空奉如丞相。〔二〕","sentenceOrder":299},
  {"id":"s_work_han_thu_11_300","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　文穎曰：「王根也。」","sentenceOrder":300},
  {"id":"s_work_han_thu_11_301","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　如淳曰：「律，丞相、大司馬大將軍奉錢月六萬，御史大夫奉月四萬也。」","sentenceOrder":301},
  {"id":"s_work_han_thu_11_302","chapterId":"ch_work_han_thu_11","textTraditional":"秋八月庚戌，中山王興薨。","sentenceOrder":302},
  {"id":"s_work_han_thu_11_303","chapterId":"ch_work_han_thu_11","textTraditional":"冬十一月，立楚孝王孫景為定陶王。","sentenceOrder":303},
  {"id":"s_work_han_thu_11_304","chapterId":"ch_work_han_thu_11","textTraditional":"定陵侯淳于長大逆不道，下獄死。廷尉孔光使持節賜貴人許氏藥，飲藥死。〔一〕","sentenceOrder":304},
  {"id":"s_work_han_thu_11_305","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　師古曰：「即前所廢皇后許氏也。」","sentenceOrder":305},
  {"id":"s_work_han_thu_11_306","chapterId":"ch_work_han_thu_11","textTraditional":"十二月，罷部刺史，更置州牧，秩二千石。","sentenceOrder":306},
  {"id":"s_work_han_thu_11_307","chapterId":"ch_work_han_thu_11","textTraditional":"二年春正月，行幸甘泉，郊泰畤。","sentenceOrder":307},
  {"id":"s_work_han_thu_11_308","chapterId":"ch_work_han_thu_11","textTraditional":"二月壬子，丞相翟方進薨。","sentenceOrder":308},
  {"id":"s_work_han_thu_11_309","chapterId":"ch_work_han_thu_11","textTraditional":"三月，行幸河東，祠后土。","sentenceOrder":309},
  {"id":"s_work_han_thu_11_310","chapterId":"ch_work_han_thu_11","textTraditional":"丙戌，帝崩于未央宮。〔一〕皇太后詔有司復長安南北郊。四月己卯，葬延陵。〔二〕","sentenceOrder":310},
  {"id":"s_work_han_thu_11_311","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　臣瓚曰：「帝年二十即位，即位二十六年，壽四十五。」師古曰：「即位明年乃改元耳，壽四十六。」","sentenceOrder":311},
  {"id":"s_work_han_thu_11_312","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　臣瓚曰：「自崩至葬凡五十四日。延陵在扶風，去長安六十二里。」","sentenceOrder":312},
  {"id":"s_work_han_thu_11_313","chapterId":"ch_work_han_thu_11","textTraditional":"贊曰：臣之姑充後宮為婕妤，〔一〕父子昆弟侍帷幄，數為臣言成帝善修容儀，升車正立，不內顧，不疾言，不親指，〔二〕臨朝淵嘿，尊嚴若神，可謂穆穆天子之容者矣！〔三〕博覽古今，容受直辭。公卿稱職，奏議可述。〔四〕遭世承平，上下和睦。然湛于酒色，〔五〕趙氏亂內，外家擅朝，言之可為於邑。〔六〕建始以來，王氏始執國命，哀、平短祚，莽遂篡位，蓋其威福所由來者漸矣！","sentenceOrder":313},
  {"id":"s_work_han_thu_11_314","chapterId":"ch_work_han_thu_11","textTraditional":"〔一〕　晉灼曰：「班彪之姑也。」","sentenceOrder":314},
  {"id":"s_work_han_thu_11_315","chapterId":"ch_work_han_thu_11","textTraditional":"〔二〕　師古曰：「不內顧者，謂儼然端嚴，不迴眄也。不疾言者，為輕肆也。不親指者，為惑下也。此三句者，本論語鄉黨篇述孔子之事，故班氏引之以美成帝。今論語云：『車中不內顧，不疾言，不親指。』內顧者，說者以為前視不過衡軛，旁視不過輢較，與此不同。輢音於綺反。」","sentenceOrder":315},
  {"id":"s_work_han_thu_11_316","chapterId":"ch_work_han_thu_11","textTraditional":"〔三〕　師古曰：「禮記云『天子穆穆，諸侯皇皇，大夫濟濟，士蹌蹌』，故此贊引之。」","sentenceOrder":316},
  {"id":"s_work_han_thu_11_317","chapterId":"ch_work_han_thu_11","textTraditional":"〔四〕　師古曰：「稱職，克當其任也。可述，言有文采。」","sentenceOrder":317},
  {"id":"s_work_han_thu_11_318","chapterId":"ch_work_han_thu_11","textTraditional":"〔五〕　師古曰：「湛讀曰耽。」","sentenceOrder":318},
  {"id":"s_work_han_thu_11_319","chapterId":"ch_work_han_thu_11","textTraditional":"〔六〕　師古曰：「於邑，短氣貌，讀如本字。於又音烏。邑又音烏合反。他皆類此。」","sentenceOrder":319},
  {"id":"s_work_han_thu_11_320","chapterId":"ch_work_han_thu_11","textTraditional":"校勘記","sentenceOrder":320},
  {"id":"s_work_han_thu_11_321","chapterId":"ch_work_han_thu_11","textTraditional":"三一０頁　八行　言令陳農為使，而（吏反下使）使之求遺書也。上使音所〔吏反，下使〕讀如本字。　景祐、殿、局本都如此。","sentenceOrder":321},
  {"id":"s_work_han_thu_11_322","chapterId":"ch_work_han_thu_11","textTraditional":"三二二頁　五行　〔長〕首建至策，　李慈銘說「首建」上當更有「長」字。","sentenceOrder":322},
  {"id":"s_work_han_thu_11_323","chapterId":"ch_work_han_thu_11","textTraditional":"三二二頁　八行卒讀曰（（暂缺F67B））〔猝〕，　景祐、殿、局本都作「猝」。　王先謙說作「猝」是。","sentenceOrder":323},
  {"id":"s_work_han_thu_11_324","chapterId":"ch_work_han_thu_11","textTraditional":"三二九頁　三行　以大司馬票騎（大）將軍（根）為大司馬，　沈欽韓說「大」字衍，荀紀無。按景祐、殿本都無「根」字。","sentenceOrder":324},
  {"id":"s_work_han_thu_12_1","chapterId":"ch_work_han_thu_12","textTraditional":"孝哀皇帝，〔一〕元帝庶孫，定陶恭王子也。母曰丁姬。年三歲嗣立為王，長好文辭法律。〔二〕元延四年入朝，盡從傅、相、中尉。〔三〕時成帝少弟中山孝王亦來朝，獨從傅。上怪之，以問定陶王，對曰：「令，諸侯王朝，得從其國二千石。傅、相、中尉皆國二千石，故盡從之。」上令誦詩，通習，能說。〔四〕他日問中山王：「獨從傅在何法令？」不能對。令誦尚書，又廢。〔五〕及賜食於前，後飽；起下，韈係解。〔六〕成帝由此以為不能，而賢定陶王，數稱其材。時王祖母傅太后隨王來朝，私賂遺上所幸趙昭儀及帝舅票騎將軍曲陽侯王根。昭儀及根見上亡子，亦欲豫自結為長久計，皆更稱定陶王，〔七〕勸帝以為嗣。成帝亦自美其材，為加元服而遣之，〔八〕時年十七矣。明年，使執金吾任宏守大鴻臚，持節徵定陶王，立為皇太子。謝曰：「臣幸得繼父守藩為諸侯王，材質不足以假充太子之宮。〔九〕陛下聖德寬仁，敬承祖宗，奉順神祇，宜蒙福祐子孫千億之報。〔一０〕臣願且得留國邸，旦夕奉問起居，俟有聖嗣，歸國守藩。」書奏，天子報聞。後月餘，立楚孝王孫景為定陶王，奉恭王祀，所以獎厲太子專為後之誼。〔一一〕語在外戚傳。","sentenceOrder":1},
  {"id":"s_work_han_thu_12_2","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　荀悅曰：「諱欣之字曰喜。」應劭曰：「恭仁短折曰哀。」","sentenceOrder":2},
  {"id":"s_work_han_thu_12_3","chapterId":"ch_work_han_thu_12","textTraditional":"〔二〕　師古曰：「年長而好之。」","sentenceOrder":3},
  {"id":"s_work_han_thu_12_4","chapterId":"ch_work_han_thu_12","textTraditional":"〔三〕　師古曰：「三官皆從王入朝。」","sentenceOrder":4},
  {"id":"s_work_han_thu_12_5","chapterId":"ch_work_han_thu_12","textTraditional":"〔四〕　師古曰：「說其義。」","sentenceOrder":5},
  {"id":"s_work_han_thu_12_6","chapterId":"ch_work_han_thu_12","textTraditional":"〔五〕　師古曰：「中忘之。」","sentenceOrder":6},
  {"id":"s_work_han_thu_12_7","chapterId":"ch_work_han_thu_12","textTraditional":"〔六〕　師古曰：「食而獨在後飽，及起，又韈係解也。韈音武伐反。」","sentenceOrder":7},
  {"id":"s_work_han_thu_12_8","chapterId":"ch_work_han_thu_12","textTraditional":"〔七〕　師古曰：「更音工衡反。」","sentenceOrder":8},
  {"id":"s_work_han_thu_12_9","chapterId":"ch_work_han_thu_12","textTraditional":"〔八〕　師古曰：「為之冠。」","sentenceOrder":9},
  {"id":"s_work_han_thu_12_10","chapterId":"ch_work_han_thu_12","textTraditional":"〔九〕　師古曰：「謙不敢言為太子，故云假充，若言非正。」","sentenceOrder":10},
  {"id":"s_work_han_thu_12_11","chapterId":"ch_work_han_thu_12","textTraditional":"〔一０〕師古曰：「大雅假樂之詩曰『干祿百福，子孫千億』。言成王宜眾宜人，天所保祐，求得福祿，故子孫眾多也。十萬曰億。故此謝書引以為言。」","sentenceOrder":11},
  {"id":"s_work_han_thu_12_12","chapterId":"ch_work_han_thu_12","textTraditional":"〔一一〕師古曰：「獎，勸使也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_12_13","chapterId":"ch_work_han_thu_12","textTraditional":"綏和二年三月，成帝崩。四月丙午，太子即皇帝位，謁高廟。尊皇太后曰太皇太后，皇后曰皇太后。大赦天下。賜宗室王子有屬者馬各一駟，〔一〕吏民爵，百戶牛酒，三老、孝弟力田、鰥寡孤獨帛。太皇太后詔尊定陶恭王為恭皇。","sentenceOrder":13},
  {"id":"s_work_han_thu_12_14","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「有屬，謂親未盡，尚有服者。」","sentenceOrder":14},
  {"id":"s_work_han_thu_12_15","chapterId":"ch_work_han_thu_12","textTraditional":"五月丙戌，立皇后傅氏。〔一〕詔曰：「春秋『母以子貴』，尊定陶太后曰恭皇太后，丁姬曰恭皇后，各置左右詹事，食邑如長信宮、中宮。」〔二〕追尊傅父為崇祖侯、丁父為褒德侯。〔三〕封舅丁明為陽安侯，舅子滿為平周侯。追諡滿父忠為平周懷侯，皇后父晏為孔鄉侯，皇太后弟侍中光祿大夫趙欽為新成侯。","sentenceOrder":15},
  {"id":"s_work_han_thu_12_16","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「傅晏女。」","sentenceOrder":16},
  {"id":"s_work_han_thu_12_17","chapterId":"ch_work_han_thu_12","textTraditional":"〔二〕　應劭曰：「成帝母王太后居長信宮。」李奇曰：「傅姬如長信，丁姬如中宮也。」師古曰：「中宮，皇后之宮。」","sentenceOrder":17},
  {"id":"s_work_han_thu_12_18","chapterId":"ch_work_han_thu_12","textTraditional":"〔三〕　師古曰：「傅父，傅太后之父。丁父，丁太后之父。」","sentenceOrder":18},
  {"id":"s_work_han_thu_12_19","chapterId":"ch_work_han_thu_12","textTraditional":"六月，詔曰：「鄭聲淫而亂樂，〔一〕聖王所放，〔二〕其罷樂府。」","sentenceOrder":19},
  {"id":"s_work_han_thu_12_20","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「鄭國有溱、洧之水，男女亟於其間聚會，故俗亂而樂淫。」","sentenceOrder":20},
  {"id":"s_work_han_thu_12_21","chapterId":"ch_work_han_thu_12","textTraditional":"〔二〕　師古曰：「放，棄也。論語稱孔子曰『放鄭聲』。」","sentenceOrder":21},
  {"id":"s_work_han_thu_12_22","chapterId":"ch_work_han_thu_12","textTraditional":"曲陽侯根前以大司馬建社稷策，益封二千戶。〔一〕太僕安陽侯舜輔導有舊恩，益封五百戶，〔二〕及丞相孔光、大司空氾鄉侯何武益封各千戶。〔三〕","sentenceOrder":22},
  {"id":"s_work_han_thu_12_23","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「王根也，建議立哀帝為太子。」","sentenceOrder":23},
  {"id":"s_work_han_thu_12_24","chapterId":"ch_work_han_thu_12","textTraditional":"〔二〕　師古曰：「王舜。」","sentenceOrder":24},
  {"id":"s_work_han_thu_12_25","chapterId":"ch_work_han_thu_12","textTraditional":"〔三〕　師古曰：「氾音汎。」","sentenceOrder":25},
  {"id":"s_work_han_thu_12_26","chapterId":"ch_work_han_thu_12","textTraditional":"詔曰：「河間王良喪太后三年，為宗室儀表，〔一〕益封萬戶。」","sentenceOrder":26},
  {"id":"s_work_han_thu_12_27","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「儀表者，言為禮儀之表率。」","sentenceOrder":27},
  {"id":"s_work_han_thu_12_28","chapterId":"ch_work_han_thu_12","textTraditional":"又曰：「制節謹度以防奢淫，為政所先，百王不易之道也。〔一〕諸侯王、列侯、公主、吏二千石及豪富民多畜奴婢，田宅亡限，與民爭利，百姓失職，重困不足。〔二〕其議限列。」〔三〕有司條奏：「諸王、列侯得名田國中，列侯在長安及公主名田縣道，關內侯、吏民名田，皆無得過三十頃。〔四〕諸侯王奴婢二百人，列侯、公主百人，關內侯、吏民三十人。年六十以上，十歲以下，不在數中。賈人皆不得名田、為吏，〔五〕犯者以律論。諸名田畜奴婢過品，皆沒入縣官。齊三服官、諸官織綺繡，難成，害女紅之物，皆止，無作輸。〔六〕除任子令及誹謗詆欺法。〔七〕掖庭宮人年三十以下，出嫁之。官奴婢五十以上，免為庶人。禁郡國無得獻名獸。益吏三百石以下奉。〔八〕察吏殘賊酷虐者，以時退。有司無得舉赦前往事。博士弟子父母死，予寧三年。」〔九〕","sentenceOrder":28},
  {"id":"s_work_han_thu_12_29","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「言為常法，不可改易。」","sentenceOrder":29},
  {"id":"s_work_han_thu_12_30","chapterId":"ch_work_han_thu_12","textTraditional":"〔二〕　師古曰：「失職，失其常分也。重音直用反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_12_31","chapterId":"ch_work_han_thu_12","textTraditional":"〔三〕　師古曰：「令條列而為限禁。」","sentenceOrder":31},
  {"id":"s_work_han_thu_12_32","chapterId":"ch_work_han_thu_12","textTraditional":"〔四〕　如淳曰：「名田國中者，自其所食國中也，既收其租稅，又自得有私田三十頃。名田縣道者，令甲，諸侯在國，名田他縣，罰金二兩。今列侯有不之國者，雖遙食其國租稅，復自得田於他縣道，公主亦如之，不得過三十頃。」","sentenceOrder":32},
  {"id":"s_work_han_thu_12_33","chapterId":"ch_work_han_thu_12","textTraditional":"〔五〕　如淳曰：「市井子孫不得為吏，見食貨志。」","sentenceOrder":33},
  {"id":"s_work_han_thu_12_34","chapterId":"ch_work_han_thu_12","textTraditional":"〔六〕　如淳曰：「紅亦工也。其所作已成未成皆止，無復作，皆輸所近官府也。」師古曰：「如說非也。謂未成者不作，已成者不輸耳。」","sentenceOrder":34},
  {"id":"s_work_han_thu_12_35","chapterId":"ch_work_han_thu_12","textTraditional":"〔七〕　應劭曰：「任子令者，漢儀注吏二千石以上視事滿三年，得任同產若子一人為郎。不以德選，故除之。」師古曰：「任者，保也。詆，誣也，音丁禮反。」","sentenceOrder":35},
  {"id":"s_work_han_thu_12_36","chapterId":"ch_work_han_thu_12","textTraditional":"〔八〕　師古曰：「奉音扶用反。」","sentenceOrder":36},
  {"id":"s_work_han_thu_12_37","chapterId":"ch_work_han_thu_12","textTraditional":"〔九〕　師古曰：「寧謂處家持喪服。」","sentenceOrder":37},
  {"id":"s_work_han_thu_12_38","chapterId":"ch_work_han_thu_12","textTraditional":"秋，曲陽侯王根、成都侯王況皆有罪。根就國，況免為庶人，歸故郡。","sentenceOrder":38},
  {"id":"s_work_han_thu_12_39","chapterId":"ch_work_han_thu_12","textTraditional":"詔曰：「朕承宗廟之重，戰戰兢兢，懼失天心。間者日月亡光，五星失行，郡國比比地動。〔一〕乃者河南、穎川郡水出，流殺人民，壞敗廬舍。朕之不德，民反蒙辜，朕甚懼焉。已遣光祿大夫循行舉籍，〔二〕賜死者棺錢，人三千。〔三〕其令水所傷縣邑及他郡國災害什四以上，民貲不滿十萬，皆無出今年租賦。」〔四〕","sentenceOrder":39},
  {"id":"s_work_han_thu_12_40","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「比比，猶言頻頻也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_12_41","chapterId":"ch_work_han_thu_12","textTraditional":"〔二〕　師古曰：「舉其名籍也。行音下更反。」","sentenceOrder":41},
  {"id":"s_work_han_thu_12_42","chapterId":"ch_work_han_thu_12","textTraditional":"〔三〕　師古曰：「賜錢三千以充棺。」","sentenceOrder":42},
  {"id":"s_work_han_thu_12_43","chapterId":"ch_work_han_thu_12","textTraditional":"〔四〕　師古曰：「什四，謂十分損四。」","sentenceOrder":43},
  {"id":"s_work_han_thu_12_44","chapterId":"ch_work_han_thu_12","textTraditional":"建平元年春正月，赦天下。侍中騎都尉新成侯趙欽、成陽侯趙訢皆有罪，免為庶人，〔一〕徙遼西。","sentenceOrder":44},
  {"id":"s_work_han_thu_12_45","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「訢、欽皆趙昭儀之兄。」","sentenceOrder":45},
  {"id":"s_work_han_thu_12_46","chapterId":"ch_work_han_thu_12","textTraditional":"太皇太后詔外家王氏田非冢塋，皆以賦貧民。〔一〕","sentenceOrder":46},
  {"id":"s_work_han_thu_12_47","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「塋，冢域也。賦，給與也。塋音營。」","sentenceOrder":47},
  {"id":"s_work_han_thu_12_48","chapterId":"ch_work_han_thu_12","textTraditional":"二月，詔曰：「蓋聞聖王之治，以得賢為首。其與大司馬、列侯、將軍、中二千石、州牧、守、相舉孝弟惇厚能直言通政事，延于側陋可親民者，各一人。」〔一〕","sentenceOrder":48},
  {"id":"s_work_han_thu_12_49","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「言有孝弟惇厚直言通政事之人，雖在側陋，可延致而任者，皆令舉之。」","sentenceOrder":49},
  {"id":"s_work_han_thu_12_50","chapterId":"ch_work_han_thu_12","textTraditional":"三月，賜諸侯王、公主、列侯、丞相、將軍、中二千石、中都官郎吏金錢帛，各有差。","sentenceOrder":50},
  {"id":"s_work_han_thu_12_51","chapterId":"ch_work_han_thu_12","textTraditional":"冬，中山孝王太后媛、〔一〕弟宜鄉侯馮參有罪，皆自殺。","sentenceOrder":51},
  {"id":"s_work_han_thu_12_52","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「馮奉世之女也。媛音爰。」","sentenceOrder":52},
  {"id":"s_work_han_thu_12_53","chapterId":"ch_work_han_thu_12","textTraditional":"二年春三月，罷大司空，復御史大夫。〔一〕","sentenceOrder":53},
  {"id":"s_work_han_thu_12_54","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「復音扶目反。此下皆同。」","sentenceOrder":54},
  {"id":"s_work_han_thu_12_55","chapterId":"ch_work_han_thu_12","textTraditional":"夏四月，詔曰：「漢家之制，推親親以顯尊尊。〔一〕定陶恭皇之號不宜復稱定陶。尊恭皇太后曰帝太太后，稱永信宮；恭皇后曰帝太后，稱中安宮。立恭皇廟于京師。赦天下徒。」","sentenceOrder":55},
  {"id":"s_work_han_thu_12_56","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「天子之至親，當極尊號。」","sentenceOrder":56},
  {"id":"s_work_han_thu_12_57","chapterId":"ch_work_han_thu_12","textTraditional":"罷州牧，復刺史。","sentenceOrder":57},
  {"id":"s_work_han_thu_12_58","chapterId":"ch_work_han_thu_12","textTraditional":"六月庚申，帝太后丁氏崩。上曰：「朕聞夫婦一體。詩云：『穀則異室，死則同穴。』〔一〕昔季武子成寑，杜氏之殯在西階下，請合葬而許之。〔二〕附葬之禮，自周興焉。〔三〕『郁郁乎文哉！吾從周。』〔四〕孝子事亡如事存。帝太后宜起陵恭皇之園。」遂葬定陶。發陳留、濟陰近郡國五萬人穿復土。〔五〕","sentenceOrder":58},
  {"id":"s_work_han_thu_12_59","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「詩王風大車之篇也。穀，生也。穴，冢壙也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_12_60","chapterId":"ch_work_han_thu_12","textTraditional":"〔二〕　師古曰：「季武子，魯大夫季孫宿也。成寑，新為寑室也。事見禮記檀弓。」","sentenceOrder":60},
  {"id":"s_work_han_thu_12_61","chapterId":"ch_work_han_thu_12","textTraditional":"〔三〕　師古曰：「禮記稱孔子曰『合葬非古也，自周公以來未之有改也』。」","sentenceOrder":61},
  {"id":"s_work_han_thu_12_62","chapterId":"ch_work_han_thu_12","textTraditional":"〔四〕　師古曰：「論語稱孔子曰『周監於二代，郁郁乎文哉！吾從周』。言周觀視夏、殷之禮而損益之，典文大備，吾從周禮也。郁郁，文章貌。」","sentenceOrder":62},
  {"id":"s_work_han_thu_12_63","chapterId":"ch_work_han_thu_12","textTraditional":"〔五〕　師古曰：「為冢壙也。復音扶目反。」","sentenceOrder":63},
  {"id":"s_work_han_thu_12_64","chapterId":"ch_work_han_thu_12","textTraditional":"侍詔夏賀良等言赤精子之讖，〔一〕漢家曆運中衰，當再受命，宜改元易號。詔曰：「漢興二百載，曆數開元。皇天降非材之佑〔二〕，漢國再獲受命之符，朕之不德，曷敢不通！夫基事之元命，必與天下自新，〔三〕其大赦天下。以建平二年為太初元將元年。號曰陳聖劉太平皇帝。〔四〕漏刻以百二十為度。」〔五〕","sentenceOrder":64},
  {"id":"s_work_han_thu_12_65","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　應劭曰：「諸以材技徵召，未有正官，故曰待詔。夏，姓也。賀良，名也。高祖感赤龍而生，自謂赤帝之精，良等因是作此讖文。」","sentenceOrder":65},
  {"id":"s_work_han_thu_12_66","chapterId":"ch_work_han_thu_12","textTraditional":"〔二〕　應劭曰：「哀帝自言不材，天降之佑。」","sentenceOrder":66},
  {"id":"s_work_han_thu_12_67","chapterId":"ch_work_han_thu_12","textTraditional":"〔三〕　師古曰：「基，始也。元，大也。始為大事之命，謂改制度也。又曰更受天之大命。」","sentenceOrder":67},
  {"id":"s_work_han_thu_12_68","chapterId":"ch_work_han_thu_12","textTraditional":"〔四〕　李斐曰：「陳，道也。言得神道聖者劉也。」如淳曰：「陳，舜後。王莽，陳之後。謬語以明莽當篡立而不知。」韋昭曰：「敷陳聖劉之德也。」師古曰：「如、韋二說是也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_12_69","chapterId":"ch_work_han_thu_12","textTraditional":"〔五〕　師古曰：「舊漏晝夜共百刻，今增其二十。此本齊人甘忠可所造，今賀良等重言，遂施行之。事見李尋傳。」","sentenceOrder":69},
  {"id":"s_work_han_thu_12_70","chapterId":"ch_work_han_thu_12","textTraditional":"七月，以渭城西北原上永陵亭部為初陵。勿徙郡國民，使得自安。","sentenceOrder":70},
  {"id":"s_work_han_thu_12_71","chapterId":"ch_work_han_thu_12","textTraditional":"八月，詔曰：「（時）〔待〕詔夏賀良等建言改元易號，增益漏刻，可以永安國家。朕過聽賀良等言，〔一〕冀為海內獲福，卒亡嘉應。皆違經背古，不合時宜。六月甲子制書，非赦令也，皆蠲除之。〔二〕賀良等反道惑眾，下有司。」皆伏辜。","sentenceOrder":71},
  {"id":"s_work_han_thu_12_72","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「過，誤也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_12_73","chapterId":"ch_work_han_thu_12","textTraditional":"〔二〕　如淳曰：「悔前赦令不蒙其福，故收令還之。」臣瓚曰：「改元易號，大赦天下，以求延祚，而不蒙福，哀帝悔之，故更下制書，諸非赦罪事皆除之。謂改制易號，令皆復故也。」師古曰：「如釋非也，瓚說是矣。非赦令也，猶言自非赦令耳。也，語終辭也。而讀者不曉，輒改也為他字，失本文也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_12_74","chapterId":"ch_work_han_thu_12","textTraditional":"丞相博、御史大夫玄、孔鄉侯晏有罪。〔一〕博自殺，玄減死二等論，晏削戶四分之一。語在博傳。","sentenceOrder":74},
  {"id":"s_work_han_thu_12_75","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「博，朱博。玄，趙玄。晏，（何）〔傅〕晏。」","sentenceOrder":75},
  {"id":"s_work_han_thu_12_76","chapterId":"ch_work_han_thu_12","textTraditional":"三年春正月，立廣德夷王弟廣漢為廣平王。","sentenceOrder":76},
  {"id":"s_work_han_thu_12_77","chapterId":"ch_work_han_thu_12","textTraditional":"癸卯，帝太太后所居桂宮正殿火。","sentenceOrder":77},
  {"id":"s_work_han_thu_12_78","chapterId":"ch_work_han_thu_12","textTraditional":"三月己酉，丞相當薨。〔一〕有星孛于河鼓。","sentenceOrder":78},
  {"id":"s_work_han_thu_12_79","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「平當。」","sentenceOrder":79},
  {"id":"s_work_han_thu_12_80","chapterId":"ch_work_han_thu_12","textTraditional":"夏六月，立魯頃王子郚鄉侯閔為王。〔一〕","sentenceOrder":80},
  {"id":"s_work_han_thu_12_81","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　蘇林曰：「郚音魚，縣名也，屬東海。」師古曰：「又音吾。」","sentenceOrder":81},
  {"id":"s_work_han_thu_12_82","chapterId":"ch_work_han_thu_12","textTraditional":"冬十一月壬子，復甘泉泰畤、汾陰后土祠，罷南北郊。","sentenceOrder":82},
  {"id":"s_work_han_thu_12_83","chapterId":"ch_work_han_thu_12","textTraditional":"東平王雲、雲后謁、安成恭侯夫人放〔一〕皆有罪。雲自殺，謁、放棄市。","sentenceOrder":83},
  {"id":"s_work_han_thu_12_84","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　文穎曰：「恭侯王崇，王太后弟。」","sentenceOrder":84},
  {"id":"s_work_han_thu_12_85","chapterId":"ch_work_han_thu_12","textTraditional":"四年春，大旱。關東民傳行西王母籌，〔一〕經歷郡國，西入關至京師。民又會聚祠西王母，或夜持火上屋，〔二〕擊鼓號呼相驚恐。〔三〕","sentenceOrder":85},
  {"id":"s_work_han_thu_12_86","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「西王母，元后壽考之象。行籌，又言執國家籌策行於天下。」","sentenceOrder":86},
  {"id":"s_work_han_thu_12_87","chapterId":"ch_work_han_thu_12","textTraditional":"〔二〕　李奇曰：「皆陰為陽之象。」","sentenceOrder":87},
  {"id":"s_work_han_thu_12_88","chapterId":"ch_work_han_thu_12","textTraditional":"〔三〕　師古曰：「呼音火故反。」","sentenceOrder":88},
  {"id":"s_work_han_thu_12_89","chapterId":"ch_work_han_thu_12","textTraditional":"二月，封帝太太后從弟侍中傅商為汝昌侯，太后同母弟子侍中鄭業為陽信侯。","sentenceOrder":89},
  {"id":"s_work_han_thu_12_90","chapterId":"ch_work_han_thu_12","textTraditional":"三月，侍中駙馬都尉董賢、光祿大夫息夫躬、南陽太守孫寵皆以告東平王封列侯。語在賢傳。","sentenceOrder":90},
  {"id":"s_work_han_thu_12_91","chapterId":"ch_work_han_thu_12","textTraditional":"夏五月，賜中二千石至六百石及天下男子爵。","sentenceOrder":91},
  {"id":"s_work_han_thu_12_92","chapterId":"ch_work_han_thu_12","textTraditional":"六月，尊帝太太后為皇太太后。","sentenceOrder":92},
  {"id":"s_work_han_thu_12_93","chapterId":"ch_work_han_thu_12","textTraditional":"秋八月，恭皇園北門災。","sentenceOrder":93},
  {"id":"s_work_han_thu_12_94","chapterId":"ch_work_han_thu_12","textTraditional":"冬，詔將軍、中二千石舉明兵法有大慮者。〔一〕","sentenceOrder":94},
  {"id":"s_work_han_thu_12_95","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「慮謂策謀思慮。」","sentenceOrder":95},
  {"id":"s_work_han_thu_12_96","chapterId":"ch_work_han_thu_12","textTraditional":"元壽元年春正月辛丑朔，日有蝕之。詔曰：「朕獲保宗廟，不明不敏，宿夜憂勞，未皇寧息。〔一〕惟陰陽不調，元元不贍，〔二〕未睹厥咎。婁敕公卿，庶幾有望。〔三〕至今有司執法，未得其中，〔四〕或上暴虐，假勢獲名，溫良寬柔，陷於亡滅。是故殘賊彌長，和睦日衰，百姓愁怨，靡所錯躬。〔五〕乃正月朔，日有蝕之，厥咎不遠，在余一人。公卿大夫其各悉心勉帥百寮，〔六〕敦任仁人，黜遠殘賊，〔七〕期於安民。陳朕之過失，無有所諱。其與將軍、列侯、中二千石舉賢良方正能直言者各一人。大赦天下。」","sentenceOrder":96},
  {"id":"s_work_han_thu_12_97","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「皇，暇也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_12_98","chapterId":"ch_work_han_thu_12","textTraditional":"〔二〕　師古曰：「贍，足也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_12_99","chapterId":"ch_work_han_thu_12","textTraditional":"〔三〕　師古曰：「望其厲精為治。婁，古屢字。」","sentenceOrder":99},
  {"id":"s_work_han_thu_12_100","chapterId":"ch_work_han_thu_12","textTraditional":"〔四〕　師古曰：「中音竹仲反。」","sentenceOrder":100},
  {"id":"s_work_han_thu_12_101","chapterId":"ch_work_han_thu_12","textTraditional":"〔五〕　師古曰：「錯，置也，音千故反。」","sentenceOrder":101},
  {"id":"s_work_han_thu_12_102","chapterId":"ch_work_han_thu_12","textTraditional":"〔六〕　師古曰：「悉，盡也。寮，官也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_12_103","chapterId":"ch_work_han_thu_12","textTraditional":"〔七〕　師古曰：「敦，厚也。遠音（手）〔于〕萬反。」","sentenceOrder":103},
  {"id":"s_work_han_thu_12_104","chapterId":"ch_work_han_thu_12","textTraditional":"丁巳，皇太太后傅氏崩。","sentenceOrder":104},
  {"id":"s_work_han_thu_12_105","chapterId":"ch_work_han_thu_12","textTraditional":"三月，丞相嘉有罪，下獄死。〔一〕","sentenceOrder":105},
  {"id":"s_work_han_thu_12_106","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕師古曰：「王嘉。」","sentenceOrder":106},
  {"id":"s_work_han_thu_12_107","chapterId":"ch_work_han_thu_12","textTraditional":"秋九月，大司馬票騎將軍丁明免。","sentenceOrder":107},
  {"id":"s_work_han_thu_12_108","chapterId":"ch_work_han_thu_12","textTraditional":"孝元廟殿門銅龜蛇鋪首鳴。〔一〕","sentenceOrder":108},
  {"id":"s_work_han_thu_12_109","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　如淳曰：「門鋪首作龜蛇之形而鳴呼也。」師古曰：「門之鋪首，所以銜環者也。鋪音普胡反。」","sentenceOrder":109},
  {"id":"s_work_han_thu_12_110","chapterId":"ch_work_han_thu_12","textTraditional":"二年春正月，匈奴單于、烏孫大昆彌來朝。二月，歸國，單于不說。〔一〕語在匈奴傳。","sentenceOrder":110},
  {"id":"s_work_han_thu_12_111","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":111},
  {"id":"s_work_han_thu_12_112","chapterId":"ch_work_han_thu_12","textTraditional":"夏四月壬辰晦，日有蝕之。","sentenceOrder":112},
  {"id":"s_work_han_thu_12_113","chapterId":"ch_work_han_thu_12","textTraditional":"五月，正三公官分職。大司馬衛將軍董賢為大司馬，丞相孔光為大司徒，御史大夫彭宣為大司空，封長平侯。正司直、司隸，造司寇職，〔一〕事未定。","sentenceOrder":113},
  {"id":"s_work_han_thu_12_114","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「司直、司棣，漢舊有之，但改正其職掌。而司寇舊無，今特創置，故云造也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_12_115","chapterId":"ch_work_han_thu_12","textTraditional":"六月戊午，帝崩于未央宮。〔一〕秋九月壬寅，葬義陵。〔二〕","sentenceOrder":115},
  {"id":"s_work_han_thu_12_116","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　臣瓚曰：「帝年二十即位，即位六年，壽二十五。」師古曰：「即位明年乃改元，壽二十六。」","sentenceOrder":116},
  {"id":"s_work_han_thu_12_117","chapterId":"ch_work_han_thu_12","textTraditional":"〔二〕　臣瓚曰：「自崩至葬凡百五日。義陵在扶風，去長安四十六里。」","sentenceOrder":117},
  {"id":"s_work_han_thu_12_118","chapterId":"ch_work_han_thu_12","textTraditional":"贊曰：孝哀自為藩王及充太子之宮，文辭博敏，幼有令聞。〔一〕睹孝成世祿去王室，權柄外移，是故臨朝婁誅大臣，欲彊主威，以則武、宣。〔二〕雅性不好聲色，時覽卞射武戲。〔三〕即位痿痺，〔四〕末年寖劇。〔五〕饗國不永，哀哉！〔六〕","sentenceOrder":118},
  {"id":"s_work_han_thu_12_119","chapterId":"ch_work_han_thu_12","textTraditional":"〔一〕　師古曰：「博，廣也。敏，疾也。令，善也。聞，名也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_12_120","chapterId":"ch_work_han_thu_12","textTraditional":"〔二〕　師古曰：「則，法也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_12_121","chapterId":"ch_work_han_thu_12","textTraditional":"〔三〕　應劭曰：「卞射，皮卞而射也。」蘇林曰：「手搏為卞，角力為武戲也。」晉灼曰：「甘延壽傳『試卞為期門』。」師古曰：「蘇、晉二說是。」","sentenceOrder":121},
  {"id":"s_work_han_thu_12_122","chapterId":"ch_work_han_thu_12","textTraditional":"〔四〕　蘇林曰：「痿音萎枯之萎。」如淳曰：「痿音〈足煩〉踒弩。病兩足不能相過曰痿。」師古曰：「痿亦痺病也，音人佳反。痺音必寐反。〈足煩〉踒者，弩名，事見晉令。〈足煩〉音煩。踒音蕤。」","sentenceOrder":122},
  {"id":"s_work_han_thu_12_123","chapterId":"ch_work_han_thu_12","textTraditional":"〔五〕　師古曰：「寖，漸也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_12_124","chapterId":"ch_work_han_thu_12","textTraditional":"〔六〕　師古曰：「永，長也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_12_125","chapterId":"ch_work_han_thu_12","textTraditional":"校勘記","sentenceOrder":125},
  {"id":"s_work_han_thu_12_126","chapterId":"ch_work_han_thu_12","textTraditional":"三四０頁一四行　（時）〔待〕詔夏賀良等　錢大昭說「時」當作「待」。按景祐、殿、局本都作「待」。","sentenceOrder":126},
  {"id":"s_work_han_thu_12_127","chapterId":"ch_work_han_thu_12","textTraditional":"三四一頁　七行　晏，（何）〔傅〕晏。　景祐、殿、局本都作「傅」。","sentenceOrder":127},
  {"id":"s_work_han_thu_12_128","chapterId":"ch_work_han_thu_12","textTraditional":"三四三頁一四行　遠音（手）〔于〕萬反。　景祐、殿、局本都作「于」。王先謙說作「于」是。","sentenceOrder":128},
  {"id":"s_work_han_thu_13_1","chapterId":"ch_work_han_thu_13","textTraditional":"孝平皇帝，〔一〕元帝庶孫，中山孝王子也。母曰衛姬。年三歲嗣立為王。元壽二年六月，哀帝崩，太皇太后詔曰：「大司馬賢年少，不合眾心。〔二〕其上印綬，罷。」賢即日自殺。新都侯王莽為大司馬，領尚書事。秋七月，遣車騎將軍王舜、大鴻臚左咸使持節迎中山王。〔三〕辛卯，貶皇太后趙氏為孝成皇后，退居北宮，哀帝皇后傅氏退居桂宮。〔四〕孔鄉侯傅晏、少府董恭等皆免官爵，徙合浦。〔五〕九月辛酉，中山王即皇帝位，謁高廟，大赦天下。","sentenceOrder":1},
  {"id":"s_work_han_thu_13_2","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　荀悅曰：「諱衎之字曰樂。」應劭曰：「布綱治紀曰平。」師古曰：「衎音口旱反。」","sentenceOrder":2},
  {"id":"s_work_han_thu_13_3","chapterId":"ch_work_han_thu_13","textTraditional":"〔二〕　師古曰：「董賢。」","sentenceOrder":3},
  {"id":"s_work_han_thu_13_4","chapterId":"ch_work_han_thu_13","textTraditional":"〔三〕　師古曰：「為使而持節也。使音所吏反。」","sentenceOrder":4},
  {"id":"s_work_han_thu_13_5","chapterId":"ch_work_han_thu_13","textTraditional":"〔四〕　師古曰：「北宮及桂宮皆在城中，而非未央宮中也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_13_6","chapterId":"ch_work_han_thu_13","textTraditional":"〔五〕　師古曰：「恭，董賢之父。」","sentenceOrder":6},
  {"id":"s_work_han_thu_13_7","chapterId":"ch_work_han_thu_13","textTraditional":"帝年九歲，太皇太后臨朝，大司馬莽秉政，百官總己以聽於莽。〔一〕詔曰：「夫赦令者，將與天下更始，誠欲令百姓改行絜己，全其性命也。（性）〔往〕者有司多舉奏赦前事，累增罪過，誅陷亡辜，殆非重信慎刑，洒心自新之意也。〔二〕及選舉者，其歷職更事有名之士，則以為難保，〔三〕廢而弗舉，甚謬於赦小過舉賢材之義。〔四〕對諸有臧及內惡未發而薦舉者，皆勿案驗。〔五〕令士厲精鄉進，〔六〕不以小疵妨大材。〔七〕自今以來，有司無得陳赦前事置奏上。〔八〕有不如詔書為虧恩，以不道論。定著令，布告天下，使明知之。」","sentenceOrder":7},
  {"id":"s_work_han_thu_13_8","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　師古曰：「聚束曰總，音揔。」","sentenceOrder":8},
  {"id":"s_work_han_thu_13_9","chapterId":"ch_work_han_thu_13","textTraditional":"〔二〕　師古曰：「洒，滌也，音先禮反。」","sentenceOrder":9},
  {"id":"s_work_han_thu_13_10","chapterId":"ch_work_han_thu_13","textTraditional":"〔三〕　師古曰：「更，經也。難保者，言己嘗有罪過，不可保也。更音工衡反。」","sentenceOrder":10},
  {"id":"s_work_han_thu_13_11","chapterId":"ch_work_han_thu_13","textTraditional":"〔四〕　師古曰：「論語云仲弓問政，孔子對曰『赦小過，舉賢材』，故此詔引之。」","sentenceOrder":11},
  {"id":"s_work_han_thu_13_12","chapterId":"ch_work_han_thu_13","textTraditional":"〔五〕　師古曰：「有臧，謂以臧貨致罪。」","sentenceOrder":12},
  {"id":"s_work_han_thu_13_13","chapterId":"ch_work_han_thu_13","textTraditional":"〔六〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":13},
  {"id":"s_work_han_thu_13_14","chapterId":"ch_work_han_thu_13","textTraditional":"〔七〕　師古曰：「疵，病也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_13_15","chapterId":"ch_work_han_thu_13","textTraditional":"〔八〕　師古曰：「置，立也。置奏上，謂立文奏而上陳也。上音時掌反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_13_16","chapterId":"ch_work_han_thu_13","textTraditional":"元始元年春正月，越裳氏重譯獻白雉一，黑雉二，〔一〕詔使三公以薦宗廟。","sentenceOrder":16},
  {"id":"s_work_han_thu_13_17","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　師古曰：「越裳，南方遠國也。譯謂傳言也。道路絕遠，風俗殊隔，故累譯而後乃通。」","sentenceOrder":17},
  {"id":"s_work_han_thu_13_18","chapterId":"ch_work_han_thu_13","textTraditional":"群臣奏言大司馬莽功德比周公，賜號安漢公，及太師孔光等皆益封。語在莽傳。賜天下民爵一級，吏在位二百石以上，一切滿秩如真。〔一〕","sentenceOrder":18},
  {"id":"s_work_han_thu_13_19","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　如淳曰：「諸官吏初除，皆試守一歲乃為真，食全奉。平帝即位故賜真。」師古曰：「此說非也。時諸官有試守者，特加非常之恩，令如真耳。非凡除吏皆當試守也。一切者，權時之事，非經常也。猶如以刀切物，苟取整齊，不顧長短縱橫，故言一切。他皆放此。」","sentenceOrder":19},
  {"id":"s_work_han_thu_13_20","chapterId":"ch_work_han_thu_13","textTraditional":"立故東平王雲太子開明為王，故桃鄉頃侯子成都為中山王。封宣帝耳孫信等三十六人皆為列侯。太僕王惲等二十五人〔一〕前議定陶傅太后尊號，守經法，不阿指從邪，右將軍孫建爪牙大臣，大鴻臚咸前正議不阿，〔二〕後奉節使迎中山王，〔三〕及宗正劉不惡、執金吾任岑、中郎將孔永、尚書令烑恂、沛郡太守石詡，〔四〕皆以前與建策，東迎即位，〔五〕奉事周密勤勞，賜爵關內侯，食邑各有差。賜帝徵即位前所過縣邑吏二千石以下至佐史爵，各有差。又令諸侯王、公、列侯、關內侯亡子而有孫若子同產子者，皆得以為嗣。〔六〕公、列侯嗣子有罪，耐以上先請。宗室屬未盡而以罪絕者，復其屬。〔七〕其為吏舉廉佐史，補四百石。〔八〕天下吏比二千石以上年老致仕者，參分故祿，以一與之，終其身。〔九〕遣諫大夫行三輔〔一０〕，舉籍吏民，〔一一〕以元壽二年倉卒時橫賦斂者，償其直〔一二〕。義陵民冢不妨殿中者勿發。〔一三〕天下吏（舍）〔民〕亡得置什器儲偫。〔一四〕","sentenceOrder":20},
  {"id":"s_work_han_thu_13_21","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　師古曰：「惲音於吻反。」","sentenceOrder":21},
  {"id":"s_work_han_thu_13_22","chapterId":"ch_work_han_thu_13","textTraditional":"〔二〕　師古曰：「左咸。」","sentenceOrder":22},
  {"id":"s_work_han_thu_13_23","chapterId":"ch_work_han_thu_13","textTraditional":"〔三〕　師古曰：「謂奉持節而為使。」","sentenceOrder":23},
  {"id":"s_work_han_thu_13_24","chapterId":"ch_work_han_thu_13","textTraditional":"〔四〕　師古曰：「岑音士林反。恂音荀。詡音況羽反。」","sentenceOrder":24},
  {"id":"s_work_han_thu_13_25","chapterId":"ch_work_han_thu_13","textTraditional":"〔五〕　師古曰：「帝本在中山，出關而迎，故曰東迎。與讀曰豫。」","sentenceOrder":25},
  {"id":"s_work_han_thu_13_26","chapterId":"ch_work_han_thu_13","textTraditional":"〔六〕　師古曰：「子同產子者，謂養昆弟之子為子者。」","sentenceOrder":26},
  {"id":"s_work_han_thu_13_27","chapterId":"ch_work_han_thu_13","textTraditional":"〔七〕　師古曰：「復音扶目反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_13_28","chapterId":"ch_work_han_thu_13","textTraditional":"〔八〕　如淳曰：「宗室為吏及舉廉及佐史，皆補四百石。」師古曰：「此說非也。言宗室為吏者，皆令舉廉，各從本秩。而依廉吏遷之為佐史者，例補四百石。」","sentenceOrder":28},
  {"id":"s_work_han_thu_13_29","chapterId":"ch_work_han_thu_13","textTraditional":"〔九〕　師古曰：「參，三也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_13_30","chapterId":"ch_work_han_thu_13","textTraditional":"〔一０〕師古曰：「行音下更反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_13_31","chapterId":"ch_work_han_thu_13","textTraditional":"〔一一〕張晏曰：「舉錄賦斂之籍而（賞）〔償〕之。」","sentenceOrder":31},
  {"id":"s_work_han_thu_13_32","chapterId":"ch_work_han_thu_13","textTraditional":"〔一二〕師古曰：「卒讀曰猝。橫音胡孟反。」","sentenceOrder":32},
  {"id":"s_work_han_thu_13_33","chapterId":"ch_work_han_thu_13","textTraditional":"〔一三〕如淳曰：「陵上有宮牆，象生制度為殿屋，故曰殿中。」師古曰：「此說非也。殿中，謂壙中象正殿處。」","sentenceOrder":33},
  {"id":"s_work_han_thu_13_34","chapterId":"ch_work_han_thu_13","textTraditional":"〔一四〕師古曰：「軍法，五人為伍，二伍為什，則共其器物。故通謂生生之具為什器，亦猶今之從軍及作役者十人為火，共畜調度也。儲，積也。偫，具也。偫音丈紀反。」","sentenceOrder":34},
  {"id":"s_work_han_thu_13_35","chapterId":"ch_work_han_thu_13","textTraditional":"二月，置羲和官，秩二千石；外史、閭師，秩六百石。〔一〕班教化，禁淫祀，放鄭聲。","sentenceOrder":35},
  {"id":"s_work_han_thu_13_36","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　應劭曰：「周禮閭師掌四郊之民，時其徵賦也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_13_37","chapterId":"ch_work_han_thu_13","textTraditional":"乙未，義陵寑神衣在柙中，丙申旦，衣在外床上，〔一〕寑令以急變聞。〔二〕用太牢祠。","sentenceOrder":37},
  {"id":"s_work_han_thu_13_38","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　文穎曰：「哀帝陵也。衣在寑中，今自出在床上。」師古日：「柙，匱也，音狎。」","sentenceOrder":38},
  {"id":"s_work_han_thu_13_39","chapterId":"ch_work_han_thu_13","textTraditional":"〔二〕　師古曰：「非常之事，故云急變。」","sentenceOrder":39},
  {"id":"s_work_han_thu_13_40","chapterId":"ch_work_han_thu_13","textTraditional":"夏五月丁巳朔，日有蝕之。大赦天下。公卿、將軍、中二千石舉敦厚能直言者各一人。","sentenceOrder":40},
  {"id":"s_work_han_thu_13_41","chapterId":"ch_work_han_thu_13","textTraditional":"六月，使少傅左將軍豐〔一〕賜帝母中山孝王姬璽書，拜為中山孝王后。賜帝舅衛寶、寶弟玄爵關內侯。賜帝女弟四人號皆曰君，食邑各二千戶。","sentenceOrder":41},
  {"id":"s_work_han_thu_13_42","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　師古曰：「甄豐。」","sentenceOrder":42},
  {"id":"s_work_han_thu_13_43","chapterId":"ch_work_han_thu_13","textTraditional":"封周公後公孫相如為褒魯侯，孔子後孔均為褒成侯，奉其祀。追諡孔子曰褒成宣尼公。","sentenceOrder":43},
  {"id":"s_work_han_thu_13_44","chapterId":"ch_work_han_thu_13","textTraditional":"罷明光宮及三輔馳道。","sentenceOrder":44},
  {"id":"s_work_han_thu_13_45","chapterId":"ch_work_han_thu_13","textTraditional":"天下女徒已論，歸家，顧山錢月三百。〔一〕復貞婦，鄉一人。〔二〕置少府海丞、果丞各一人；〔三〕大司農部丞十三人，人部一州，勸農桑。","sentenceOrder":45},
  {"id":"s_work_han_thu_13_46","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　如淳曰：「已論者，罪已定也。令甲，女子犯罪，作如徒六月，顧山遣歸。說以為當於山伐木，聽使入錢顧功直，故謂之顧山。」應劭曰：「舊刑鬼薪，取薪於山以給宗廟，今使女徒出錢顧薪，故曰顧山也。」師古曰：「如說近之。謂女徒論罪已定，並放歸家，不親役之，但令一月出錢三百，以顧人也。為此恩者，所以行太皇太后之德，施惠政於婦人。」","sentenceOrder":46},
  {"id":"s_work_han_thu_13_47","chapterId":"ch_work_han_thu_13","textTraditional":"〔二〕　師古曰：「復音方目反。鄉一人，取其尤最者。」","sentenceOrder":47},
  {"id":"s_work_han_thu_13_48","chapterId":"ch_work_han_thu_13","textTraditional":"〔三〕　師古曰：「海丞，主海稅也。果丞，掌諸果實也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_13_49","chapterId":"ch_work_han_thu_13","textTraditional":"太皇太后省所食湯沐邑十縣，屬大司農，常別計其租入，以贍貧民。","sentenceOrder":49},
  {"id":"s_work_han_thu_13_50","chapterId":"ch_work_han_thu_13","textTraditional":"秋九月，赦天下徒。","sentenceOrder":50},
  {"id":"s_work_han_thu_13_51","chapterId":"ch_work_han_thu_13","textTraditional":"以中山苦陘縣為中山孝王后湯沐邑。〔一〕","sentenceOrder":51},
  {"id":"s_work_han_thu_13_52","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　師古曰：「陘音形。」","sentenceOrder":52},
  {"id":"s_work_han_thu_13_53","chapterId":"ch_work_han_thu_13","textTraditional":"二年春，黃支國獻犀牛。〔一〕","sentenceOrder":53},
  {"id":"s_work_han_thu_13_54","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　應劭曰：「黃支在日南之南，去京師三萬里。」師古曰：「犀狀如水牛，頭似豬而四足類象，黑色，一角當額前，鼻上又有小角。」","sentenceOrder":54},
  {"id":"s_work_han_thu_13_55","chapterId":"ch_work_han_thu_13","textTraditional":"詔曰：「皇帝二名，通于器物，〔一〕今更名，合於古制。〔二〕使太師光奉太牢告祠高廟。」","sentenceOrder":55},
  {"id":"s_work_han_thu_13_56","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　孟康曰：「平帝本名箕子，更名曰衎。箕，用器也，故云通于器物。」","sentenceOrder":56},
  {"id":"s_work_han_thu_13_57","chapterId":"ch_work_han_thu_13","textTraditional":"〔二〕　師古曰：「更，改也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_13_58","chapterId":"ch_work_han_thu_13","textTraditional":"夏四月，立代孝王玄孫之子如意為廣宗王，江都易王孫盱台侯宮為廣川王，〔一〕廣川惠王曾孫倫為廣德王。封故大司馬博陸侯霍光從父昆弟曾孫陽、宣平侯張敖玄孫慶忌、絳侯周勃玄孫共、舞陽侯樊噲玄孫之子章皆為列侯，復爵。〔二〕賜故曲周侯酈商等後玄孫酈明友等百一十三人爵關內侯，食邑各有差。","sentenceOrder":58},
  {"id":"s_work_han_thu_13_59","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　師古曰：「盱音許于反。台音怡。」","sentenceOrder":59},
  {"id":"s_work_han_thu_13_60","chapterId":"ch_work_han_thu_13","textTraditional":"〔二〕　師古曰：「共讀曰恭。復音扶福反。」","sentenceOrder":60},
  {"id":"s_work_han_thu_13_61","chapterId":"ch_work_han_thu_13","textTraditional":"郡國大旱，蝗，青州尤甚，民流亡。安漢公、四輔、三公、卿大夫、吏民為百〔姓〕困乏獻其田宅者二百三十人，〔一〕以口賦貧民。〔二〕遣使者捕蝗，民捕蝗詣吏，以石〈豆斗〉受錢。〔三〕天下民貲不滿二萬，及被災之郡不滿十萬，勿租稅。民疾疫者，舍空邸第，為置醫藥。〔四〕賜死者一家六尸以上葬錢五千，四尸以上三千，二尸以上二千。罷安定呼池苑，以為安民縣，〔五〕起官寺巿里，募徙貧民，縣次給食。至徙所，賜田宅什器，假與犁、牛、種、食。〔六〕又起五里於長安城中，〔七〕宅二百區，以居貧民。","sentenceOrder":61},
  {"id":"s_work_han_thu_13_62","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　張晏曰：「王莽為太傅，孔光為太師，王舜為太保，甄豐為少傅，是為四輔。莽復兼大司馬，馬宮為司徒，王崇為司空，是為三公。」","sentenceOrder":62},
  {"id":"s_work_han_thu_13_63","chapterId":"ch_work_han_thu_13","textTraditional":"〔二〕　師古曰：「計口而給其田宅。」","sentenceOrder":63},
  {"id":"s_work_han_thu_13_64","chapterId":"ch_work_han_thu_13","textTraditional":"〔三〕　師古曰：「量蝗多少而賞錢。」","sentenceOrder":64},
  {"id":"s_work_han_thu_13_65","chapterId":"ch_work_han_thu_13","textTraditional":"〔四〕　師古曰：「舍，止也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_13_66","chapterId":"ch_work_han_thu_13","textTraditional":"〔五〕　師古曰：「中山之安定也。池音大河反。」","sentenceOrder":66},
  {"id":"s_work_han_thu_13_67","chapterId":"ch_work_han_thu_13","textTraditional":"〔六〕　師古曰：「種音之勇反。」","sentenceOrder":67},
  {"id":"s_work_han_thu_13_68","chapterId":"ch_work_han_thu_13","textTraditional":"〔七〕　如淳曰：「民居之里。」","sentenceOrder":68},
  {"id":"s_work_han_thu_13_69","chapterId":"ch_work_han_thu_13","textTraditional":"秋，舉勇武有節明兵法，郡一人，詣公車。","sentenceOrder":69},
  {"id":"s_work_han_thu_13_70","chapterId":"ch_work_han_thu_13","textTraditional":"九月戊申晦，日有蝕之。赦天下徒。","sentenceOrder":70},
  {"id":"s_work_han_thu_13_71","chapterId":"ch_work_han_thu_13","textTraditional":"使謁者大司馬掾四十四人持節行邊兵。〔一〕","sentenceOrder":71},
  {"id":"s_work_han_thu_13_72","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　師古曰：「行音下更反。」","sentenceOrder":72},
  {"id":"s_work_han_thu_13_73","chapterId":"ch_work_han_thu_13","textTraditional":"遣執金吾候陳茂假以鉦鼓，〔一〕募汝南、南陽勇敢吏士三百人，諭說江湖賊成重等二百餘人皆自出，送家在所收事。〔二〕重徙雲陽，〔三〕賜公田宅。","sentenceOrder":73},
  {"id":"s_work_han_thu_13_74","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　晉灼曰：「百官表執金吾屬官有兩丞、候、司馬。」應劭曰：「將帥乃有鉦鼓，今茂官輕兵少，又但往諭曉之耳，所以假鉦鼓者，欲重其威也。鉦者，鐃也，似鈴，柄中上下通。」師古曰：「鉦音征。鐃音女交反。」","sentenceOrder":74},
  {"id":"s_work_han_thu_13_75","chapterId":"ch_work_han_thu_13","textTraditional":"〔二〕　如淳曰：「賊雖自出，得還其家而已，不得復除，尚當役作之也。」師古曰：「如說非也。言身既自出，又各送其家人詣本屬縣邑從賦役耳。」","sentenceOrder":75},
  {"id":"s_work_han_thu_13_76","chapterId":"ch_work_han_thu_13","textTraditional":"〔三〕　服虔曰：「重，成重也。作賊長帥，故徙之也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_13_77","chapterId":"ch_work_han_thu_13","textTraditional":"冬，中二千石舉治獄平，歲一人。〔一〕","sentenceOrder":77},
  {"id":"s_work_han_thu_13_78","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　李奇曰：「吏治獄平端也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_13_79","chapterId":"ch_work_han_thu_13","textTraditional":"三年春，詔有司為皇帝納采安漢公莽女。〔一〕語在莽傳。又詔光祿大夫劉歆等雜定婚禮。四輔、公卿、大夫、博士、郎、吏家屬皆以禮娶，親迎立軺併馬。〔二〕","sentenceOrder":79},
  {"id":"s_work_han_thu_13_80","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　師古曰：「婚禮有納采、問名之禮，謂采擇其可娶者。」","sentenceOrder":80},
  {"id":"s_work_han_thu_13_81","chapterId":"ch_work_han_thu_13","textTraditional":"〔二〕　服虔曰：「軺音謡，立乘小車也。併馬，驪駕也。」師古曰：「新定此制也。併音步鼎反。」","sentenceOrder":81},
  {"id":"s_work_han_thu_13_82","chapterId":"ch_work_han_thu_13","textTraditional":"夏，安漢公奏車服制度，吏民養生、送終、嫁娶、奴婢、田宅、器械之品。立官稷及學官。〔一〕郡國曰學，縣、道、邑、侯國曰校。校、學置經師一人。鄉曰庠，聚曰序。〔二〕序、庠置孝經師一人。","sentenceOrder":82},
  {"id":"s_work_han_thu_13_83","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　如淳曰：「郊祀志曰『已有官社，未有官稷，遂立官稷於官社之後』。」臣瓚曰：「漢初除秦社稷，立漢社稷，其後又立官社，配以夏禹，而不立官稷。至此始立官稷。光武之後，但有官社，不立官稷。」師古曰：「淳、瓚二說皆未盡也。初立官稷於官社之後，是為一處。今更創置建於別所，不相從也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_13_84","chapterId":"ch_work_han_thu_13","textTraditional":"〔二〕　張晏曰：「聚，邑落名也。」師古曰：「聚小於鄉。聚音才喻反。」","sentenceOrder":84},
  {"id":"s_work_han_thu_13_85","chapterId":"ch_work_han_thu_13","textTraditional":"陽陵任橫等自稱將軍，盜庫兵，攻官寺，出囚徒。大司徒掾督逐，皆伏辜。","sentenceOrder":85},
  {"id":"s_work_han_thu_13_86","chapterId":"ch_work_han_thu_13","textTraditional":"安漢公世子宇與帝外家衛氏有謀。宇下獄死，誅衛氏。","sentenceOrder":86},
  {"id":"s_work_han_thu_13_87","chapterId":"ch_work_han_thu_13","textTraditional":"四年春正月，郊祀高祖以配天，宗祀孝文以配上帝。","sentenceOrder":87},
  {"id":"s_work_han_thu_13_88","chapterId":"ch_work_han_thu_13","textTraditional":"改殷紹嘉公曰宋公，周承休公曰鄭公。","sentenceOrder":88},
  {"id":"s_work_han_thu_13_89","chapterId":"ch_work_han_thu_13","textTraditional":"詔曰：「蓋夫婦正則父子親，人倫定矣。前詔有司復貞婦，歸女徒，〔一〕誠欲以防邪辟，〔二〕全貞信。及眊悼之人〔三〕刑罰所不加，聖王之所制也。惟苛暴吏多拘繫犯法者親屬，婦女老弱，搆怨傷化，百姓苦之。〔四〕其明敕百寮，婦女非身犯法，及男子年八十以上七歲以下，家非坐不道，詔所名捕，它皆無得繫。〔五〕其當驗者，即驗問。〔六〕定著令。」","sentenceOrder":89},
  {"id":"s_work_han_thu_13_90","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　師古曰：「復音方目反。」","sentenceOrder":90},
  {"id":"s_work_han_thu_13_91","chapterId":"ch_work_han_thu_13","textTraditional":"〔二〕　師古曰：「辟讀曰僻。」","sentenceOrder":91},
  {"id":"s_work_han_thu_13_92","chapterId":"ch_work_han_thu_13","textTraditional":"〔三〕　師古曰：「八十曰眊，七年曰悼。眊者老稱，言其昏暗也。悼者，未成為人，於其死亡，可哀悼也。眊音莫報反。」","sentenceOrder":92},
  {"id":"s_work_han_thu_13_93","chapterId":"ch_work_han_thu_13","textTraditional":"〔四〕　師古曰：「搆，結也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_13_94","chapterId":"ch_work_han_thu_13","textTraditional":"〔五〕　張晏曰：「名捕，謂下詔特所捕也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_13_95","chapterId":"ch_work_han_thu_13","textTraditional":"〔六〕　師古曰：「就其所居而問。」","sentenceOrder":95},
  {"id":"s_work_han_thu_13_96","chapterId":"ch_work_han_thu_13","textTraditional":"二月丁未，立皇后王氏，大赦天下。","sentenceOrder":96},
  {"id":"s_work_han_thu_13_97","chapterId":"ch_work_han_thu_13","textTraditional":"遣太僕王惲等八人置副，假節，分行天下，覽觀風俗。〔一〕","sentenceOrder":97},
  {"id":"s_work_han_thu_13_98","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　師古曰：「行音下更反。」","sentenceOrder":98},
  {"id":"s_work_han_thu_13_99","chapterId":"ch_work_han_thu_13","textTraditional":"賜九卿已下至六百石、宗室有屬籍者爵，自五大夫以上各有差。〔一〕賜天下民爵一級，鰥寡孤獨高年帛。","sentenceOrder":99},
  {"id":"s_work_han_thu_13_100","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　師古曰：「五大夫，第九爵。」","sentenceOrder":100},
  {"id":"s_work_han_thu_13_101","chapterId":"ch_work_han_thu_13","textTraditional":"夏，皇后見于高廟。加安漢公號曰「宰衡」。〔一〕賜公太夫人號曰功顯君。封公子安、臨皆為列侯。","sentenceOrder":101},
  {"id":"s_work_han_thu_13_102","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　應劭曰：「周公為太宰，伊尹為阿衡，采伊、周之尊以加莽。」","sentenceOrder":102},
  {"id":"s_work_han_thu_13_103","chapterId":"ch_work_han_thu_13","textTraditional":"安漢公奏立明堂、辟廱。〔一〕尊孝宣廟為中宗，孝元廟為高宗，天子世世獻祭。","sentenceOrder":103},
  {"id":"s_work_han_thu_13_104","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　應劭曰：「明堂所以正四時，出教化。明堂上圜下方，八窗四達，布政之宮，在國之陽。上八窗法八風，四達法四時，九室法九州，十二重法十二月，三十六戶法三十六（雨）〔旬〕，七十二〈片庸〉法七十二（風）〔候〕。孝經曰：『宗祀文王於明堂，以配上帝。』上帝謂五時帝太昊之屬。黃帝曰合宮，有虞曰總章，殷曰陽館，周曰明堂。辟廱者，象璧圜，雍之以水，象教化流行。」","sentenceOrder":104},
  {"id":"s_work_han_thu_13_105","chapterId":"ch_work_han_thu_13","textTraditional":"置西海郡，徙天下犯禁者處之。","sentenceOrder":105},
  {"id":"s_work_han_thu_13_106","chapterId":"ch_work_han_thu_13","textTraditional":"梁王立有罪，自殺。","sentenceOrder":106},
  {"id":"s_work_han_thu_13_107","chapterId":"ch_work_han_thu_13","textTraditional":"分京師置前煇光、後丞烈二郡。更公卿、大夫、八十一元士官名位次〔一〕及十二州名。分界郡國所屬，罷置改易，天下多事，吏不能紀。","sentenceOrder":107},
  {"id":"s_work_han_thu_13_108","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　師古曰：「更，改也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_13_109","chapterId":"ch_work_han_thu_13","textTraditional":"冬，大風吹長安城東門屋瓦且盡。","sentenceOrder":109},
  {"id":"s_work_han_thu_13_110","chapterId":"ch_work_han_thu_13","textTraditional":"五年春正月，祫祭明堂。〔一〕諸侯王二十八人、列侯百二十人、宗室子九百餘人徵助祭。〔二〕禮畢，皆益戶，賜爵及金帛，增秩補吏，各有差。","sentenceOrder":110},
  {"id":"s_work_han_thu_13_111","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　應劭曰：「禮五年而再殷祭，壹禘壹祫。祫祭者，毀廟與未毀廟之主皆合食於太祖。」師古曰：「祫音洽。」","sentenceOrder":111},
  {"id":"s_work_han_thu_13_112","chapterId":"ch_work_han_thu_13","textTraditional":"〔二〕　師古曰：「徵，召也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_13_113","chapterId":"ch_work_han_thu_13","textTraditional":"詔曰：「蓋聞帝王以德撫民，其次親親以相及也。昔堯睦九族，舜惇敘之。〔一〕朕以皇帝幼年，且統國政，〔二〕惟宗室子皆太祖高皇帝子孫及兄弟吳頃、楚元之後，〔三〕漢元至今，十有餘萬人，雖有王侯之屬，莫能相糾，〔四〕或陷入刑罪，教訓不至之咎也。傳不云乎？『君子篤於親，則民興於仁。』〔五〕其為宗室自太上皇以來族親，各以世氏，郡國置宗師以糾之，致教訓焉。二千石選有德義者以為宗師。考察不從教令有冤失職者，宗師得因郵亭書言宗伯，請以聞。〔六〕常以歲正月賜宗師帛各十匹。」","sentenceOrder":113},
  {"id":"s_work_han_thu_13_114","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　師古曰：「虞書堯典云『昔在帝堯，克明峻德，以親九族，九族既睦，平章百姓』。咎繇謨曰『惇敘九族，庶明厲翼』。言堯能明峻德之士而任用之，以（陸）〔睦〕高祖玄孫之親，乃令百姓平和章明。舜又厚敘此親，使眾庶皆明其教，而自勉勵翼戴上命也。故此詔引之。」","sentenceOrder":114},
  {"id":"s_work_han_thu_13_115","chapterId":"ch_work_han_thu_13","textTraditional":"〔二〕　師古曰：「朕者，太皇太后自稱也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_13_116","chapterId":"ch_work_han_thu_13","textTraditional":"〔三〕　師古曰：「吳頃謂高帝之兄仲也。初為代王，後廢為合陽侯，而子濞封為吳王，故追諡仲為吳頃王。頃讀曰傾。」","sentenceOrder":116},
  {"id":"s_work_han_thu_13_117","chapterId":"ch_work_han_thu_13","textTraditional":"〔四〕　師古曰：「糾謂禁察也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_13_118","chapterId":"ch_work_han_thu_13","textTraditional":"〔五〕　師古曰：「此論語載孔子之辭也。言上能厚於親屬，則下皆化之，起為仁行也。以論語傳聖人之言，故（為）〔謂〕之傳。他皆類此。」","sentenceOrder":118},
  {"id":"s_work_han_thu_13_119","chapterId":"ch_work_han_thu_13","textTraditional":"〔六〕　晉灼曰：「宗伯，宗正也。」師古曰：「郵，行書舍也。言為書以付郵亭，令送至宗伯也。郵音尤。」","sentenceOrder":119},
  {"id":"s_work_han_thu_13_120","chapterId":"ch_work_han_thu_13","textTraditional":"羲和劉歆等四人使治明堂、辟廱，〔一〕令漢與文王靈臺、周公作洛同符。〔二〕太僕王惲等八人使行風俗，〔三〕宣明德化，萬國齊同。皆封為列侯。","sentenceOrder":120},
  {"id":"s_work_han_thu_13_121","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　師古曰：「為使者而典其事。」","sentenceOrder":121},
  {"id":"s_work_han_thu_13_122","chapterId":"ch_work_han_thu_13","textTraditional":"〔二〕　師古曰：「文王築靈臺，周公成雒邑，言與之符合。」","sentenceOrder":122},
  {"id":"s_work_han_thu_13_123","chapterId":"ch_work_han_thu_13","textTraditional":"〔三〕　師古曰：「行音下更反。」","sentenceOrder":123},
  {"id":"s_work_han_thu_13_124","chapterId":"ch_work_han_thu_13","textTraditional":"徵天下通知逸經、古記、天文、曆算、鍾律、小學、史篇、方術、本草及以五經、論語、孝經、爾雅教授者，在所為駕一封軺傳〔一〕，遣詣京師。至者數千人。","sentenceOrder":124},
  {"id":"s_work_han_thu_13_125","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　如淳曰：「律，諸當乘傳及發駕置傳者，皆持尺五寸木傳信，封以御史大夫印章。其乘傳參封之。參，三也。有期會累封兩端，端各兩封，凡四封也。乘置馳傳五封也，兩端各二，中央一也。軺傳兩馬再封之，一馬一封也。」師古曰：「以一馬駕軺車而乘傳。傳音張戀反。」","sentenceOrder":125},
  {"id":"s_work_han_thu_13_126","chapterId":"ch_work_han_thu_13","textTraditional":"閏月，立梁孝王玄孫之耳孫音為王。","sentenceOrder":126},
  {"id":"s_work_han_thu_13_127","chapterId":"ch_work_han_thu_13","textTraditional":"冬十二月丙午，帝崩于未央宮。〔一〕大赦天下。有司議曰：「禮，臣不殤君。皇帝年十有四歲，宜以禮斂，加元服。」〔二〕奏可。葬康陵。〔三〕詔曰：「皇帝仁惠，無不顧哀，〔四〕每疾一發，氣輒上逆，害於言語，故不及有遺詔。其出媵妾，皆歸家得嫁，如孝文時故事。」〔五〕","sentenceOrder":127},
  {"id":"s_work_han_thu_13_128","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　臣瓚曰：「帝年九歲即位，即位五年，壽十四。」師古曰：「漢注云帝春秋益壯，以母衛大后故怨不悅。莽自知益疏，篡殺之謀由是生，因到（獵）〔臘〕日上椒酒，置藥酒中。故翟義移書云『莽鴆弒孝平皇帝』。」","sentenceOrder":128},
  {"id":"s_work_han_thu_13_129","chapterId":"ch_work_han_thu_13","textTraditional":"〔二〕　師古曰：「斂音力贍反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_13_130","chapterId":"ch_work_han_thu_13","textTraditional":"〔三〕　臣瓚曰：「在長安北六十里。」","sentenceOrder":130},
  {"id":"s_work_han_thu_13_131","chapterId":"ch_work_han_thu_13","textTraditional":"〔四〕　師古曰：「言帝平生多所顧念哀憐。」","sentenceOrder":131},
  {"id":"s_work_han_thu_13_132","chapterId":"ch_work_han_thu_13","textTraditional":"〔五〕　師古曰：「媵妾，謂從皇后俱來者。媵之言送。媵音食證反，又音孕也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_13_133","chapterId":"ch_work_han_thu_13","textTraditional":"贊曰：孝平之世，政自莽出，褒善顯功，以自尊盛。觀其文辭，方外百蠻，亡思不服；〔一〕休徵嘉應，頌聲並作。〔二〕至乎變異見於上，民怨於下，莽亦不能文也。〔三〕","sentenceOrder":133},
  {"id":"s_work_han_thu_13_134","chapterId":"ch_work_han_thu_13","textTraditional":"〔一〕　師古曰：「大雅文王有聲之詩曰：『自（東）〔西〕自（西）〔東〕，自南自北，亡思不服。』言武王於鎬京行辟雍之禮，自四方來觀者皆感其德化，心無不歸服。故此贊引之。」","sentenceOrder":134},
  {"id":"s_work_han_thu_13_135","chapterId":"ch_work_han_thu_13","textTraditional":"〔二〕　師古曰：「休，美也。徵，證也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_13_136","chapterId":"ch_work_han_thu_13","textTraditional":"〔三〕　如淳曰：「不可復文飾也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_13_137","chapterId":"ch_work_han_thu_13","textTraditional":"校勘記","sentenceOrder":137},
  {"id":"s_work_han_thu_13_138","chapterId":"ch_work_han_thu_13","textTraditional":"三四八頁　二行　（性）〔往〕者有司多舉奏赦前事，　景祐、殿、局本都作「往」。錢大昭說「性」當作「往」。","sentenceOrder":138},
  {"id":"s_work_han_thu_13_139","chapterId":"ch_work_han_thu_13","textTraditional":"三五０頁　一行　天下吏（舍）〔民〕亡得置什器儲偫。　景祐、殿本都作「民」。周壽昌說作「民」是。","sentenceOrder":139},
  {"id":"s_work_han_thu_13_140","chapterId":"ch_work_han_thu_13","textTraditional":"三五０頁一三行　舉錄賦斂之籍而（賞）〔償〕之。　景祐、殿本都作「償」。王先謙說作「償」是。","sentenceOrder":140},
  {"id":"s_work_han_thu_13_141","chapterId":"ch_work_han_thu_13","textTraditional":"三五三頁　七行　為百〔姓〕困乏獻其田宅者　景祐、殿、局本都作「姓」字，此脫。","sentenceOrder":141},
  {"id":"s_work_han_thu_13_142","chapterId":"ch_work_han_thu_13","textTraditional":"三五七頁一一行　三十六戶法三十六（雨）〔旬〕，七十二牖法七十二（風）〔候〕。　宋祁說「雨」字舊作「旬」，「風」字舊作「候」，疑此本有誤。按景祐本正作「旬」作「候」。","sentenceOrder":142},
  {"id":"s_work_han_thu_13_143","chapterId":"ch_work_han_thu_13","textTraditional":"三五九頁　一行　以（陸）〔睦〕高祖玄孫之親，　景祐、殿、局本都作「睦」。","sentenceOrder":143},
  {"id":"s_work_han_thu_13_144","chapterId":"ch_work_han_thu_13","textTraditional":"三五九頁　六行　故（為）〔謂〕之傳。　錢大昭說「為」當作「謂」。按景祐、殿本都作「謂」。","sentenceOrder":144},
  {"id":"s_work_han_thu_13_145","chapterId":"ch_work_han_thu_13","textTraditional":"三六０頁　八行　因到（獵）〔臘〕日上椒酒，　錢大昭說「獵」當作「臘」。按景祐、殿本都作「臘」。","sentenceOrder":145},
  {"id":"s_work_han_thu_13_146","chapterId":"ch_work_han_thu_13","textTraditional":"三六０頁一五行　自（東）〔西〕自（西）〔東〕，　景祐本如此，與詩合。","sentenceOrder":146},
  {"id":"s_work_han_thu_14_1","chapterId":"ch_work_han_thu_14","textTraditional":"昔詩書述虞夏之際，舜禹受襢，〔一〕積德累功，洽於百姓，攝位行政，考之于天，〔二〕經數十年，然後在位。殷周之王，乃繇卨稷，〔三〕修仁行義，歷十餘世，至于湯武，然後放殺。〔四〕秦起襄公，章文、繆，獻、〔五〕孝、昭、嚴，稍蠶食六國，〔六〕百有餘載，至始皇，乃并天下。以德若彼，用力如此其（艱）〔囏〕難也。〔七〕","sentenceOrder":1},
  {"id":"s_work_han_thu_14_2","chapterId":"ch_work_han_thu_14","textTraditional":"〔一〕　師古曰：「古禪字，音上扇反。」","sentenceOrder":2},
  {"id":"s_work_han_thu_14_3","chapterId":"ch_work_han_thu_14","textTraditional":"〔二〕　師古曰：「謂在璿璣玉衡以齊七政。考之于天，知已合天心不也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_14_4","chapterId":"ch_work_han_thu_14","textTraditional":"〔三〕　師古曰：「繇讀與由同。」","sentenceOrder":4},
  {"id":"s_work_han_thu_14_5","chapterId":"ch_work_han_thu_14","textTraditional":"〔四〕　師古曰：「殺讀曰弒。它皆類此。」","sentenceOrder":5},
  {"id":"s_work_han_thu_14_6","chapterId":"ch_work_han_thu_14","textTraditional":"〔五〕　師古曰：「言奏之初大，起於襄公始為諸侯，至文公、繆公、獻公，更為章著也。襄公，莊公之子；文公，襄公之子也。繆公，德公之少子；獻公，靈公之子也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_14_7","chapterId":"ch_work_han_thu_14","textTraditional":"〔六〕　師古曰：「孝謂孝公也，即獻公之子。昭謂昭襄王，即惠王之子，武王之弟也。嚴謂莊襄王，即昭襄王之孫，孝文王之子也。後漢時避明帝諱，以莊為嚴，故漢書姓及諡本作莊者皆易為嚴也。它皆類此。蠶食，謂漸吞滅之，如蠶食葉也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_14_8","chapterId":"ch_work_han_thu_14","textTraditional":"〔七〕　師古曰：「囏，古艱字也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_14_9","chapterId":"ch_work_han_thu_14","textTraditional":"秦既稱帝，患周之敗，以為起於處士橫議，諸侯力爭，四夷交侵，以弱見奪。〔一〕於是削去五等，〔二〕墮城銷刃，〔三〕箝語燒書，〔四〕內鋤雄俊，外攘胡粵，〔五〕用壹威權，為萬世安。〔六〕然十餘年間，猛敵橫發乎不虞，〔七〕適戍彊於五伯，〔八〕閭閻偪於戎狄，〔九〕嚮應〈疒朁〉於謗議，〔一０〕奮臂威於甲兵。鄉秦之禁，適所以資豪桀而速自斃也。〔一一〕是以漢亡尺土之階，繇一劍之任，五載而成帝業。〔一二〕書傳所記，未嘗有焉。何則？古世相革，皆承聖王之烈，〔一三〕今漢獨收孤秦之弊。鐫金石者難為功，摧枯朽者易為力，〔一四〕其勢然也。故據漢受命，譜十八王，月而列之，天下一統，乃以年數。〔一五〕訖于孝文，異姓盡矣。","sentenceOrder":9},
  {"id":"s_work_han_thu_14_10","chapterId":"ch_work_han_thu_14","textTraditional":"〔一〕　服虔曰：「言因橫議而敗也。」應劭曰：「孟軻云『聖王不作，諸侯恣行，處士橫議』。」師古曰：「處士謂不官於朝而居家者也。橫音（朝）〔胡〕孟反。次下『橫發』，其音亦同也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_14_11","chapterId":"ch_work_han_thu_14","textTraditional":"〔二〕　應劭曰：「周制，公、侯、伯、子、男五等爵。」","sentenceOrder":11},
  {"id":"s_work_han_thu_14_12","chapterId":"ch_work_han_thu_14","textTraditional":"〔三〕　應劭曰：「壞其堅城，恐復阻以害己也。聚天下之兵，鑄以為銅人十二，不欲令民復逆命也。古者以銅為兵。」師古曰：「墮音火規反。」","sentenceOrder":12},
  {"id":"s_work_han_thu_14_13","chapterId":"ch_work_han_thu_14","textTraditional":"〔四〕　應劭曰：「禁民聚語，畏其謗己。箝，緘也。箝與鉗同。」晉灼曰：「許慎云『箝，籥也』。」師古曰：「晉說是也。謂箝籥其口，不聽妄言也，即所謂禁耦語者也。箝音（某）〔其〕占反。籥音躡。」","sentenceOrder":13},
  {"id":"s_work_han_thu_14_14","chapterId":"ch_work_han_thu_14","textTraditional":"〔五〕　師古曰：「攘，卻也。粵，古越字。」","sentenceOrder":14},
  {"id":"s_work_han_thu_14_15","chapterId":"ch_work_han_thu_14","textTraditional":"〔六〕　師古曰：「令威權壹歸於己。」","sentenceOrder":15},
  {"id":"s_work_han_thu_14_16","chapterId":"ch_work_han_thu_14","textTraditional":"〔七〕　師古曰：「虞，度也。意所不度，謂之不虞。」","sentenceOrder":16},
  {"id":"s_work_han_thu_14_17","chapterId":"ch_work_han_thu_14","textTraditional":"〔八〕　師古曰：「適讀曰謫。謫戍，謂陳勝、吳廣也。伯讀曰霸。五霸謂昆吾、大彭、豕韋、齊桓、晉文也。謫音陟厄反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_14_18","chapterId":"ch_work_han_thu_14","textTraditional":"〔九〕　應劭曰：「周禮二十五家為閭。閻音簷，門閭外旋下廕，謂之步簷也。閭閻民陳勝之屬，言其逼秦甚於戎狄也。」師古曰：「閭，里門也。閻，里中門也。陳勝、吳廣本起閭左之戍，故總言閭閻，應說非也。閭左解在陳勝傳。偪音逼。」","sentenceOrder":18},
  {"id":"s_work_han_thu_14_19","chapterId":"ch_work_han_thu_14","textTraditional":"〔一０〕服虔曰：「〈疒朁〉音慘。」應劭曰：「秦法，誹謗者族。今陳勝奮臂大呼，天下莫不嚮應，嚮應之害更〈疒朁〉烈於所謗議也。」師古曰：「嚮音響。響應者，如響之應聲。〈疒朁〉，痛也。服音是也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_14_20","chapterId":"ch_work_han_thu_14","textTraditional":"〔一一〕師古曰：「鄉讀曰嚮，謂曩時也。秦禁，謂墮城銷刃、箝語燒書之屬是也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_14_21","chapterId":"ch_work_han_thu_14","textTraditional":"〔一二〕師古曰：「繇讀與由同。任，用也，事也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_14_22","chapterId":"ch_work_han_thu_14","textTraditional":"〔一三〕師古曰：「革，變也。烈謂餘烈也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_14_23","chapterId":"ch_work_han_thu_14","textTraditional":"〔一四〕師古曰：「鐫，琢石也，音子全反。」","sentenceOrder":23},
  {"id":"s_work_han_thu_14_24","chapterId":"ch_work_han_thu_14","textTraditional":"〔一五〕應劭曰：「譜音補。項羽為西楚霸王，為天下主，命立十八王，王高祖於蜀漢。漢元年，諸王畢封各就國，始受命之元，故以冠表焉。」張晏曰：「時天下未定，參錯變易，不可以年紀，故列其月，五年誅籍，乃以年紀焉。」","sentenceOrder":24},
  {"id":"s_work_han_thu_14_25","chapterId":"ch_work_han_thu_14","textTraditional":"表1","sentenceOrder":25},
  {"id":"s_work_han_thu_14_26","chapterId":"ch_work_han_thu_14","textTraditional":"校勘記","sentenceOrder":26},
  {"id":"s_work_han_thu_14_27","chapterId":"ch_work_han_thu_14","textTraditional":"三六三頁　五行　秦起襄公，章文、繆，獻、〔五〕孝、昭、嚴，稍蠶食六國。　注〔五〕在「獻」下，明顏以「章文、繆、獻」斷句。王念孫說獻公在繆公之後十六世，而與文、繆並數，既為不倫，且上下句法，亦屬參差。當斷「章文、繆」為句，「獻、孝、昭、嚴」為句。王先謙說王說是。","sentenceOrder":27},
  {"id":"s_work_han_thu_14_28","chapterId":"ch_work_han_thu_14","textTraditional":"三六三頁　六行　其（艱）〔囏〕難也。　錢大昭說「艱」當作「囏」。按景祐、殿、局本都作「囏」。","sentenceOrder":28},
  {"id":"s_work_han_thu_14_29","chapterId":"ch_work_han_thu_14","textTraditional":"三六四頁一二行　橫音（朝）〔胡〕孟反。　景祐、汲古、殿、局本都作「胡」。","sentenceOrder":29},
  {"id":"s_work_han_thu_14_30","chapterId":"ch_work_han_thu_14","textTraditional":"三六五頁　一行　箝音（某）〔其〕占反。　景祐、汲古、局本都作「其」。","sentenceOrder":30},
  {"id":"s_work_han_thu_14_31","chapterId":"ch_work_han_thu_14","textTraditional":"三六六頁　二欄　十格「故齊將」，錢大昭說當作「齊王」。按景祐、殿本都作「齊王」。","sentenceOrder":31},
  {"id":"s_work_han_thu_14_32","chapterId":"ch_work_han_thu_14","textTraditional":"三六七頁　一欄　十五格「廿一」，景祐、本都作「卅一」。王先謙說作「卅一」是。","sentenceOrder":32},
  {"id":"s_work_han_thu_14_33","chapterId":"ch_work_han_thu_14","textTraditional":"三六七頁　二欄　二至十八格缺字據殿、局本補，十九格據局本補。","sentenceOrder":33},
  {"id":"s_work_han_thu_14_34","chapterId":"ch_work_han_thu_14","textTraditional":"三六七頁　三欄　缺字據殿、局本補。十六格「卅二」，景祐本作「廿二」。朱一新說作「廿二」是。","sentenceOrder":34},
  {"id":"s_work_han_thu_14_35","chapterId":"ch_work_han_thu_14","textTraditional":"三六七頁　四欄　缺字據殿、局本補。","sentenceOrder":35},
  {"id":"s_work_han_thu_14_36","chapterId":"ch_work_han_thu_14","textTraditional":"三六八頁　一欄　十六格「卅四」，景祐、殿、局本都作「廿四」。朱一新說作「廿四」是。","sentenceOrder":36},
  {"id":"s_work_han_thu_14_37","chapterId":"ch_work_han_thu_14","textTraditional":"三六八頁　二欄　十一格「七」字據殿本補。十四格「七」字據殿、局本補。　十八格八字原在十九格，據景祐、殿、局本移上。","sentenceOrder":37},
  {"id":"s_work_han_thu_14_38","chapterId":"ch_work_han_thu_14","textTraditional":"三六八頁　三欄　十四格「八」字據殿、局本補。","sentenceOrder":38},
  {"id":"s_work_han_thu_14_39","chapterId":"ch_work_han_thu_14","textTraditional":"三六九頁　二欄　七格「安成」，王先謙說殿本作「成安」是。","sentenceOrder":39},
  {"id":"s_work_han_thu_14_40","chapterId":"ch_work_han_thu_14","textTraditional":"三七０頁　二欄　原分作三欄，據王先謙說併。十七格，殿本作「十三」是。","sentenceOrder":40},
  {"id":"s_work_han_thu_14_41","chapterId":"ch_work_han_thu_14","textTraditional":"三七一頁　三欄　王先謙說九格「二」字衍。按景、汲古本有，殿、局本無。","sentenceOrder":41},
  {"id":"s_work_han_thu_14_42","chapterId":"ch_work_han_thu_14","textTraditional":"三七一頁　四欄　王先謙說九格「三」字衍。按景祐、汲古本有，殿、局本無。","sentenceOrder":42},
  {"id":"s_work_han_thu_14_43","chapterId":"ch_work_han_thu_14","textTraditional":"三七三頁　二欄　七格「十二」，景祐、汲古、殿、局本都作「十三」。","sentenceOrder":43},
  {"id":"s_work_han_thu_14_44","chapterId":"ch_work_han_thu_14","textTraditional":"三七三頁　三欄　五格「十一」據殿、局本補。","sentenceOrder":44},
  {"id":"s_work_han_thu_14_45","chapterId":"ch_work_han_thu_14","textTraditional":"三七三頁　四欄　四格「廿四」據殿、局本補。","sentenceOrder":45},
  {"id":"s_work_han_thu_14_46","chapterId":"ch_work_han_thu_14","textTraditional":"三七三頁　五欄　原分作二欄，殿本併為一欄。王先謙說殿本不誤。","sentenceOrder":46},
  {"id":"s_work_han_thu_14_47","chapterId":"ch_work_han_thu_14","textTraditional":"三七四頁　三欄　二格「漢圍」，景祐、殿、局本都作「圍漢」。","sentenceOrder":47},
  {"id":"s_work_han_thu_14_48","chapterId":"ch_work_han_thu_14","textTraditional":"三七六頁　六欄　五格，王先謙說「王」當為「國」，各本誤。","sentenceOrder":48},
  {"id":"s_work_han_thu_14_49","chapterId":"ch_work_han_thu_14","textTraditional":"三七七頁　四欄　五格，王先謙說「月」字衍。按景按本有，殿本無。","sentenceOrder":49},
  {"id":"s_work_han_thu_14_50","chapterId":"ch_work_han_thu_14","textTraditional":"三七九頁　一欄　一格，王先謙說「一」字衍。按汲古本有，景祐、殿、局本無。","sentenceOrder":50},
  {"id":"s_work_han_thu_14_51","chapterId":"ch_work_han_thu_14","textTraditional":"三七九頁　四欄　一格，景祐、殿本都無「帝」字。","sentenceOrder":51},
  {"id":"s_work_han_thu_14_52","chapterId":"ch_work_han_thu_14","textTraditional":"三八一頁　三欄　王先謙說五、七格「二」字衍。　按景祐本有，殿、局本無。八格「二」字據景祐、汲古、殿、局本補。","sentenceOrder":52},
  {"id":"s_work_han_thu_14_53","chapterId":"ch_work_han_thu_14","textTraditional":"三八二頁　一欄　王先謙說七格「三」字衍。按景祐、汲古本有，殿、局本無。","sentenceOrder":53},
  {"id":"s_work_han_thu_14_54","chapterId":"ch_work_han_thu_14","textTraditional":"三八二頁　二欄　王先謙說七格「四」字衍。按景祐、汲古本有，殿、局本無。","sentenceOrder":54},
  {"id":"s_work_han_thu_14_55","chapterId":"ch_work_han_thu_14","textTraditional":"三八二頁　三欄　八格十一字原在九格，汲古本同，王先謙說誤。據景祐、殿、局本移上。","sentenceOrder":55},
  {"id":"s_work_han_thu_15_1","chapterId":"ch_work_han_thu_15","textTraditional":"昔周監於二代，〔一〕三聖制法，〔二〕立爵五等，〔三〕封國八百，同姓五十有餘。周公、康叔建於魯、衛，各數百里；太公於齊，亦五侯九伯之地。〔四〕詩載其制曰：「介人惟藩，大師惟垣。大邦惟屏，大宗惟翰。懷德惟寧，宗子惟城。母俾城壞，毋獨斯畏。」〔五〕所以親親賢賢，褒表功德，〔六〕關諸盛衰，深根固本，為不可拔者也。故盛則周、邵相其治，致刑錯；衰則五伯扶其弱，與共守。〔七〕自幽、平之後，日以陵夷，〔八〕至虖阨〈阝區〉河洛之間，〔九〕分為二周，〔一０〕有逃責之臺，被竊鈇之言。〔一一〕然天下謂之共主，〔一二〕彊大弗之敢傾。〔一三〕歷載八百餘年，數極德盡，既於王赧，〔一四〕降為庶人，用天年終。號位已絕於天下，尚猶枝葉相持，莫得居其虛位，海內無主，三十餘年。〔一五〕","sentenceOrder":1},
  {"id":"s_work_han_thu_15_2","chapterId":"ch_work_han_thu_15","textTraditional":"〔一〕　師古曰：「監，視也。二代，夏、殷也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_15_3","chapterId":"ch_work_han_thu_15","textTraditional":"〔二〕　師古曰：「三聖謂文王、武王及周公也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_15_4","chapterId":"ch_work_han_thu_15","textTraditional":"〔三〕　師古曰：「公、侯、伯、子、男。」","sentenceOrder":4},
  {"id":"s_work_han_thu_15_5","chapterId":"ch_work_han_thu_15","textTraditional":"〔四〕　臣瓚曰：「禮記王制云：『五國以為屬，屬有長；二百一十國以為州，州有伯。』」　師古曰：「五侯，五等諸侯也。九伯，九州之伯也。伯，長也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_15_6","chapterId":"ch_work_han_thu_15","textTraditional":"〔五〕　師古曰：「大雅板之詩也。介，善也。藩，籬也。屏，蔽也。垣，牆也。翰，幹也。懷，和也。俾，使也。以善人為之藩籬，謂封周公、康叔於魯、衛；以大師為垣牆，謂封太公於齊也。大邦以為屏蔽，謂成國諸侯也；大宗以為楨幹，謂王之同姓也。能和其德則天下安寧，分建宗子則列城堅固。城不可使墮壞，宗不可使單獨。單獨墮壞，則畏懼斯至。」","sentenceOrder":6},
  {"id":"s_work_han_thu_15_7","chapterId":"ch_work_han_thu_15","textTraditional":"〔六〕　師古曰：「親賢俱封，功德並建。」","sentenceOrder":7},
  {"id":"s_work_han_thu_15_8","chapterId":"ch_work_han_thu_15","textTraditional":"〔七〕　師古曰：「伯讀曰霸。此五霸謂齊桓、宋襄、晉文、秦穆、吳夫差也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_15_9","chapterId":"ch_work_han_thu_15","textTraditional":"〔八〕　師古曰：「陵夷，言如山陵之漸平。夷謂頹替也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_15_10","chapterId":"ch_work_han_thu_15","textTraditional":"〔九〕　應劭曰：「阨者，狹也。〈阝區〉者，踦〈足區〉也。西迫強秦，東有韓魏，數見侵暴，踦〈足區〉不安也。」師古曰：「阨音於懈反。〈阝區〉音區。」","sentenceOrder":10},
  {"id":"s_work_han_thu_15_11","chapterId":"ch_work_han_thu_15","textTraditional":"〔一０〕師古曰：「謂東西二周也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_15_12","chapterId":"ch_work_han_thu_15","textTraditional":"〔一一〕服虔曰：「周赧王負責，無以歸之，主迫責急，乃逃於此臺，後人因以名之。」劉德曰：「洛陽南宮謻臺是也。」應劭曰：「竊鈇，謂出至路邊竊取人鈇也。」師古曰：「應說非也。鈇鉞，王者以為威，用斬戮也。言周室衰微，政令不行於天下，雖有鈇鉞，無所用之，是謂私竊隱藏之耳。被音皮義反。鈇音膚。謻音移，又音直移反。」","sentenceOrder":12},
  {"id":"s_work_han_thu_15_13","chapterId":"ch_work_han_thu_15","textTraditional":"〔一二〕如淳曰：「雖至微弱，猶共以為之主。」","sentenceOrder":13},
  {"id":"s_work_han_thu_15_14","chapterId":"ch_work_han_thu_15","textTraditional":"〔一三〕師古曰：「言諸侯雖彊大者，不敢傾滅周也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_15_15","chapterId":"ch_work_han_thu_15","textTraditional":"〔一四〕師古曰：「既亦盡也。赧，諡也，一曰名也，音女版反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_15_16","chapterId":"ch_work_han_thu_15","textTraditional":"〔一五〕師古曰：「秦昭襄王五十二年周初亡，五十六年昭襄王卒，孝文王立一年而卒，莊襄王立四年而卒，子政立二十六年而乃并天下，自號始皇帝。是為三十五年無主也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_15_17","chapterId":"ch_work_han_thu_15","textTraditional":"秦據勢勝之地，騁狙詐之兵，〔一〕蠶食山東，壹切取勝。〔二〕因矜其所習，自任私知，姍笑三代，盪滅古法，〔三〕竊自號為皇帝，而子弟為匹夫，內亡骨肉本根之輔，外亡尺土藩翼之衛。陳、吳奮其白挺，〔四〕劉、項隨而斃之。故曰，周過其曆，秦不及期，國勢然也。〔五〕","sentenceOrder":17},
  {"id":"s_work_han_thu_15_18","chapterId":"ch_work_han_thu_15","textTraditional":"〔一〕　應劭曰：「狙，伺也，因（聞）〔間〕伺隙出兵也。狙音若蛆反。」師古曰：「音千絮反。」","sentenceOrder":18},
  {"id":"s_work_han_thu_15_19","chapterId":"ch_work_han_thu_15","textTraditional":"〔二〕　師古曰；「蠶食，解在異姓諸侯王表。壹切，解在平紀也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_15_20","chapterId":"ch_work_han_thu_15","textTraditional":"〔三〕　師古曰：「姍，古訕字也。訕，謗也，音所諫反，又音刪。」","sentenceOrder":20},
  {"id":"s_work_han_thu_15_21","chapterId":"ch_work_han_thu_15","textTraditional":"〔四〕　應劭曰：「白挺，大杖也。孟子書曰『可使制挺以撻秦楚』是也。」師古曰：「挺音徒鼎反。」","sentenceOrder":21},
  {"id":"s_work_han_thu_15_22","chapterId":"ch_work_han_thu_15","textTraditional":"〔五〕　應劭曰：「武王克商，卜世三十，卜年七百，今乃三十六世，八百六十七歲，此謂過其曆者也。秦以諡法少，恐後世相襲，自稱始皇，子曰二世，欲以一迄萬，今至子而亡，此之為不及期也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_15_23","chapterId":"ch_work_han_thu_15","textTraditional":"漢興之初，海內新定，同姓寡少，懲戒亡秦孤立之敗，於是剖裂疆土，立二等之爵。〔一〕功臣侯者百有餘邑，尊王子弟，大啟九國。〔二〕自鴈門以東，盡遼陽，為燕、代。〔三〕常山以南，太行左轉，度河、濟，漸于海，為齊、趙。〔四〕穀、泗以往，奄有龜、蒙，為梁、楚。〔五〕東帶江、湖，薄會稽，為荊吳。〔六〕北界淮瀕，略廬、衡，為淮南。〔七〕波漢之陽，亙九嶷，為長沙。〔八〕諸侯（北）〔比〕境，周（市）〔匝〕三垂，外接胡越。〔九〕天子自有三河、東郡、潁川、南陽，〔一０〕自江陵以西至巴蜀，北自雲中至隴西，與京師內史凡十五郡，公主、列侯頗邑其中。〔一一〕而藩國大者夸州兼郡，連城數十，〔一二〕宮室百官同制京師，可謂撟枉過其正矣。〔一三〕雖然，高祖創業，日不暇給，孝惠享國又淺，高后女主攝位，而海內晏如，〔一四〕亡狂狡之憂，卒折諸呂之難，成太宗之業者，亦賴之於諸侯也。","sentenceOrder":23},
  {"id":"s_work_han_thu_15_24","chapterId":"ch_work_han_thu_15","textTraditional":"〔一〕　（項羽）〔韋昭〕曰：「漢封功臣，大者王，小者侯也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_15_25","chapterId":"ch_work_han_thu_15","textTraditional":"〔二〕　師古曰：「九國之數在下也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_15_26","chapterId":"ch_work_han_thu_15","textTraditional":"〔三〕　師古曰：「遼陽，遼水之陽也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_15_27","chapterId":"ch_work_han_thu_15","textTraditional":"〔四〕　師古曰：「太行，出名也。左轉，亦謂自太行而東也。漸，入也，一曰浸也。行音胡剛反。漸音子廉反，亦讀如本字。」","sentenceOrder":27},
  {"id":"s_work_han_thu_15_28","chapterId":"ch_work_han_thu_15","textTraditional":"〔五〕　晉灼曰：「水經云泗水出魯（下）〔卞〕縣。」臣瓚曰：「穀在彭城，泗之下流為穀水。」師古曰：「奄，覆也。龜、蒙，二山名。」","sentenceOrder":28},
  {"id":"s_work_han_thu_15_29","chapterId":"ch_work_han_thu_15","textTraditional":"〔六〕　文穎曰：「即今吳也。高帝六年為荊國，十年更名吳。」師古曰：「荊吳，同是一國也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_15_30","chapterId":"ch_work_han_thu_15","textTraditional":"〔七〕　師古曰：「瀕，水涯也，音頻，又音賓。廬、衡，二山名也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_15_31","chapterId":"ch_work_han_thu_15","textTraditional":"〔八〕　鄭氏曰：「波音陂澤之陂。」孟康曰：「亙，竟也，音古贈反。」師古曰：「漢之陽者，循漢水而往也。水北曰陽。（陂）〔波〕音彼皮反，又音彼義反。九嶷，山名，有九峰，在零陵營道。嶷音疑。」","sentenceOrder":31},
  {"id":"s_work_han_thu_15_32","chapterId":"ch_work_han_thu_15","textTraditional":"〔九〕　師古曰：「比謂相接次也。三垂，謂北東南也。比音頻寐反。」","sentenceOrder":32},
  {"id":"s_work_han_thu_15_33","chapterId":"ch_work_han_thu_15","textTraditional":"〔一０〕師古曰：「三河，河東、河南、河內也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_15_34","chapterId":"ch_work_han_thu_15","textTraditional":"〔一一〕師古曰：「十五郡中又往往有列侯、公主之邑。」","sentenceOrder":34},
  {"id":"s_work_han_thu_15_35","chapterId":"ch_work_han_thu_15","textTraditional":"〔一二〕師古曰：「夸音跨。」","sentenceOrder":35},
  {"id":"s_work_han_thu_15_36","chapterId":"ch_work_han_thu_15","textTraditional":"〔一三〕師古曰：「撟與矯同。枉，曲也。正曲曰矯。言矯秦孤立之敗而大封子弟，過於強盛，有失中也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_15_37","chapterId":"ch_work_han_thu_15","textTraditional":"〔一四〕師古曰：「晏如，安然也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_15_38","chapterId":"ch_work_han_thu_15","textTraditional":"然諸侯原本以大，末流濫以致溢，小者淫荒越法，大者睽孤橫逆，以害身喪國。〔一〕故文帝采賈生之議分齊、趙，景帝用晁錯之計削吳、楚。武帝施主父之冊，下推恩之令，使諸侯王得分戶邑以封子弟，不行黜陟，而藩國自析。自此以來，齊分為七〔二〕趙分為六，〔三〕梁分為五，〔四〕淮南分為三。〔五〕皇子始立者，大國不過十餘城。長城、燕、代雖有舊名，皆亡南北邊矣。〔六〕景遭七國之難，抑損諸侯，減黜其官。〔七〕武有衡山、淮南之謀，作左官之律，〔八〕設附益之法，〔九〕諸侯惟得衣食稅租，不與政事。〔一０〕","sentenceOrder":38},
  {"id":"s_work_han_thu_15_39","chapterId":"ch_work_han_thu_15","textTraditional":"〔一〕　師古曰：「易睽卦九四爻辭曰『睽孤，見豕負塗』。睽孤，乖刺之意。睽音工攜反。」","sentenceOrder":39},
  {"id":"s_work_han_thu_15_40","chapterId":"ch_work_han_thu_15","textTraditional":"〔二〕　師古曰：「謂齊、城陽、濟北、濟南、淄川、膠西、膠東也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_15_41","chapterId":"ch_work_han_thu_15","textTraditional":"〔三〕　師古曰：「謂趙、平原、真定、中山、廣川、河間也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_15_42","chapterId":"ch_work_han_thu_15","textTraditional":"〔四〕　師古曰：「謂梁、濟川、濟東、山陽、濟陰也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_15_43","chapterId":"ch_work_han_thu_15","textTraditional":"〔五〕　師古曰：「謂淮南、衡山、廬江。」","sentenceOrder":43},
  {"id":"s_work_han_thu_15_44","chapterId":"ch_work_han_thu_15","textTraditional":"〔六〕　如淳曰：「長沙之南更置郡，燕、代以北更置緣邊郡。其所有饒利、兵馬、器械，三國皆失之矣。」","sentenceOrder":44},
  {"id":"s_work_han_thu_15_45","chapterId":"ch_work_han_thu_15","textTraditional":"〔七〕　師古曰：「謂改丞相曰相，省御史大夫、廷尉、少府、宗正、博士，損大夫、謁者諸官長丞員等也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_15_46","chapterId":"ch_work_han_thu_15","textTraditional":"〔八〕　服虔曰：「仕於諸侯為左官，絕不得使仕於王侯也。」應劭曰：「人道上右，今舍天子而仕諸侯，故謂之左官也。」師古曰：「左官猶言左道也。皆僻左不正，應說是也。漢時依上古法，朝廷之列以右為尊，故謂降秩為左遷，仕諸侯為左官也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_15_47","chapterId":"ch_work_han_thu_15","textTraditional":"〔九〕　張晏曰：「律鄭氏說，封諸侯過限曰附益。或曰阿媚王侯，有重法也。」師古：「附益者，蓋取孔子云『求也為之聚斂而附益之』之義也，皆背正法而厚於私家也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_15_48","chapterId":"ch_work_han_thu_15","textTraditional":"〔一０〕師古曰：「與讀曰豫。」","sentenceOrder":48},
  {"id":"s_work_han_thu_15_49","chapterId":"ch_work_han_thu_15","textTraditional":"至於哀、平之際，皆繼體苗裔，親屬疏遠，〔一〕生於帷牆之中，不為士民所尊，勢與富室亡異。而本朝短世，國統三絕，〔二〕是故王莽知漢中外殫微，本末俱弱，〔三〕亡所忌憚，生其姦心；因母后之權，假伊周之稱，顓作威福廟堂之上，不降階序而運天下。〔四〕詐謀既成，遂據南面之尊，分遣五威之吏，馳傳天下，班行符命。漢諸侯王厥角稽首，〔五〕奉上璽韍，惟恐在後，〔六〕或乃稱美頌德，以求容媚，豈不哀哉！是以究其終始彊弱之變，明監戒焉。","sentenceOrder":49},
  {"id":"s_work_han_thu_15_50","chapterId":"ch_work_han_thu_15","textTraditional":"〔一〕　師古曰：「言非始封之君，皆其後裔也，故於天子益疏遠矣。」","sentenceOrder":50},
  {"id":"s_work_han_thu_15_51","chapterId":"ch_work_han_thu_15","textTraditional":"〔二〕　師古曰：「謂成、哀、平皆早崩，又無繼嗣。」","sentenceOrder":51},
  {"id":"s_work_han_thu_15_52","chapterId":"ch_work_han_thu_15","textTraditional":"〔三〕　師古曰：「殫，盡也，音單。」","sentenceOrder":52},
  {"id":"s_work_han_thu_15_53","chapterId":"ch_work_han_thu_15","textTraditional":"〔四〕　師古曰：「序謂東西廂。顓與專同。」","sentenceOrder":53},
  {"id":"s_work_han_thu_15_54","chapterId":"ch_work_han_thu_15","textTraditional":"〔五〕　應劭曰：「厥者，頓也。角者，頟角也。稽者，首至地也。言王莽漸漬威福日久，亦值漢之單弱，王侯見莽篡弒，莫敢怨望，皆頓角稽首至地而上其璽綬也。」晉灼曰：「厥猶豎也，叩頭則頟角豎。」師古曰：「應說是也。稽音口禮反，與稽同。」","sentenceOrder":54},
  {"id":"s_work_han_thu_15_55","chapterId":"ch_work_han_thu_15","textTraditional":"〔六〕　師古曰：「韍音弗，璽之組也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_15_56","chapterId":"ch_work_han_thu_15","textTraditional":"諸侯王表第二","sentenceOrder":56},
  {"id":"s_work_han_thu_15_57","chapterId":"ch_work_han_thu_15","textTraditional":"校勘記","sentenceOrder":57},
  {"id":"s_work_han_thu_15_58","chapterId":"ch_work_han_thu_15","textTraditional":"三九三頁　八行　因（聞）〔間〕伺隙出兵也。　朱一新說「聞」疑作「間」。按景祐、殿、局本都作「間」。","sentenceOrder":58},
  {"id":"s_work_han_thu_15_59","chapterId":"ch_work_han_thu_15","textTraditional":"三九四頁　二行　諸侯（北）〔比〕境，周（市）〔匝〕三垂，　景祐、殿本「北」都作「比」，「市」都作「匝」。王先謙說作「比」作「匝」是。","sentenceOrder":59},
  {"id":"s_work_han_thu_15_60","chapterId":"ch_work_han_thu_15","textTraditional":"三九四頁　七行　（項羽）〔韋昭〕曰：　朱一新說史表集解引作「韋昭」。","sentenceOrder":60},
  {"id":"s_work_han_thu_15_61","chapterId":"ch_work_han_thu_15","textTraditional":"三九四頁一二行　泗水出魯（下）〔卞〕縣。　景祐、汲古、殿、局本都作「卞」。朱一新說作「卞」是。","sentenceOrder":61},
  {"id":"s_work_han_thu_15_62","chapterId":"ch_work_han_thu_15","textTraditional":"三九四頁一六行　（陂）〔波〕音彼皮反。　景祐、殿本都作「波」。","sentenceOrder":62},
  {"id":"s_work_han_thu_15_63","chapterId":"ch_work_han_thu_15","textTraditional":"三九九頁　二欄　八格，王先謙說「二」當作「一」。　按景祐本作「一」。","sentenceOrder":63},
  {"id":"s_work_han_thu_15_64","chapterId":"ch_work_han_thu_15","textTraditional":"三九九頁　三欄　六格「元始」當作「永作」，據資治通鑑改。","sentenceOrder":64},
  {"id":"s_work_han_thu_15_65","chapterId":"ch_work_han_thu_15","textTraditional":"四０三頁　一欄　四格，王先謙說「四十二」當作「四十三」，史表不誤。","sentenceOrder":65},
  {"id":"s_work_han_thu_15_66","chapterId":"ch_work_han_thu_15","textTraditional":"四０三頁　二欄　四格，王先謙說「三十三」當作「四十三」。　按景祐本作「三十四」。","sentenceOrder":66},
  {"id":"s_work_han_thu_15_67","chapterId":"ch_work_han_thu_15","textTraditional":"四０五頁　三欄　四格，朱一新說文紀作「三月」，汪本亦作「三月」，此作「二月」誤。","sentenceOrder":67},
  {"id":"s_work_han_thu_15_68","chapterId":"ch_work_han_thu_15","textTraditional":"四０八頁　三欄　三格，殿本「七」作「二」。王先謙說作「二」是。","sentenceOrder":68},
  {"id":"s_work_han_thu_15_69","chapterId":"ch_work_han_thu_15","textTraditional":"四０九頁　一欄　三格，朱一新說汪本無「王」字是。　按景祐本無「王」字。","sentenceOrder":69},
  {"id":"s_work_han_thu_15_70","chapterId":"ch_work_han_thu_15","textTraditional":"四０九頁　三欄　七格，王先謙說「七」當作「三」。　按景祐本作「二」。","sentenceOrder":70},
  {"id":"s_work_han_thu_15_71","chapterId":"ch_work_han_thu_15","textTraditional":"四一一頁　二欄　二格，王先謙說「高」當作「景」。　按景祐、殿、局本都作「景」。","sentenceOrder":71},
  {"id":"s_work_han_thu_15_72","chapterId":"ch_work_han_thu_15","textTraditional":"四一二頁　三欄　五、六、七格原在六、七、八格，據錢大昭說及景祐、殿、局本提上。七格「嗣」字據殿、局本補。","sentenceOrder":72},
  {"id":"s_work_han_thu_15_73","chapterId":"ch_work_han_thu_15","textTraditional":"四一六頁　四欄　五格，王先謙說「四」字衍。　按景祐本「四」作「一」。","sentenceOrder":73},
  {"id":"s_work_han_thu_15_74","chapterId":"ch_work_han_thu_15","textTraditional":"四一七頁　四欄　六格，王先謙說「由」字閩本、汪本、殿本都作「申」。　按景祐本作「申」。又說「二十二年」當作「三十三年」。　按景祐本正作「三十三年」。","sentenceOrder":74},
  {"id":"s_work_han_thu_15_75","chapterId":"ch_work_han_thu_15","textTraditional":"四一九頁　一欄　三格「主」，景祐、殿、局本都作「坐」。王先謙說作「坐」是。","sentenceOrder":75},
  {"id":"s_work_han_thu_15_76","chapterId":"ch_work_han_thu_15","textTraditional":"四二０頁　二欄　四格，王先謙說「始元」誤倒作「元始」。　按景祐、殿、局本都作「始元」。","sentenceOrder":76},
  {"id":"s_work_han_thu_15_77","chapterId":"ch_work_han_thu_15","textTraditional":"四二０頁　三欄　錢大昭說「兄」當作「凡」。　按殿、局本都作「凡」。","sentenceOrder":77},
  {"id":"s_work_han_thu_15_78","chapterId":"ch_work_han_thu_15","textTraditional":"四二一頁　三欄　五格，殿、局本「烈」都作「列」。　王先謙說作「列」是。","sentenceOrder":78},
  {"id":"s_work_han_thu_15_79","chapterId":"ch_work_han_thu_15","textTraditional":"四二二頁　二欄　四格，王先謙說「十」上脫「二」字。　五格，王先謙說「子」字衍。　按景祐、殿、局本都無「子」字。","sentenceOrder":79},
  {"id":"s_work_han_thu_16_1","chapterId":"ch_work_han_thu_16","textTraditional":"大哉，聖祖之建業也！後嗣承序，以廣親親。至于孝武，以諸侯王疆土過制，或替差失軌，而子弟為匹夫，〔一〕輕重不相準，於是制詔御史：「諸侯王或欲推私恩分子弟邑者，令各條上，朕且臨定其號名。」自是支庶畢侯矣。詩云「文王孫子，本支百世」，〔二〕信矣哉！〔三〕","sentenceOrder":1},
  {"id":"s_work_han_thu_16_2","chapterId":"ch_work_han_thu_16","textTraditional":"〔一〕　師古曰：「疆亦壃字也。替，古僣字也。軌，法也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_16_3","chapterId":"ch_work_han_thu_16","textTraditional":"〔二〕　師古曰：「大雅文王之詩也。本，本宗也。支，支子也。言文王有明德，故天祚子，子孫嫡者為天子，支庶為諸侯，皆不絕也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_16_4","chapterId":"ch_work_han_thu_16","textTraditional":"〔三〕　師古曰：「侯所食邑，皆書其郡縣於下。其有不書者，史失之也。或但言某人嗣及直書薨，不具年月，皆闕文也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_16_5","chapterId":"ch_work_han_thu_16","textTraditional":"王子侯表第三上","sentenceOrder":5},
  {"id":"s_work_han_thu_16_6","chapterId":"ch_work_han_thu_16","textTraditional":"校勘記","sentenceOrder":6},
  {"id":"s_work_han_thu_16_7","chapterId":"ch_work_han_thu_16","textTraditional":"四二八頁　三欄　三格，錢大昭說「一百二十」當作「一百二十七」。　王先謙說史表正作「一百二十七」。「十年」，景祐、殿本都作「七年八月」。　四格「三」，景祐、殿本都作「二」。","sentenceOrder":7},
  {"id":"s_work_han_thu_16_8","chapterId":"ch_work_han_thu_16","textTraditional":"四三０頁　四欄　四格，錢大昭說「二年」當作「三年」。　王先謙說史表作「三年」。　按景祐本正作「三年」。","sentenceOrder":8},
  {"id":"s_work_han_thu_16_9","chapterId":"ch_work_han_thu_16","textTraditional":"四三一頁　三欄　四格，景祐、殿本「耐」作「削」。","sentenceOrder":9},
  {"id":"s_work_han_thu_16_10","chapterId":"ch_work_han_thu_16","textTraditional":"四三二頁　一欄　三格「齊」，景祐、殿、局本都作「濟」。","sentenceOrder":10},
  {"id":"s_work_han_thu_16_11","chapterId":"ch_work_han_thu_16","textTraditional":"四三三頁　三欄　一格「艮」，景祐、殿本都作「良」。　王先謙說「艮」字誤。","sentenceOrder":11},
  {"id":"s_work_han_thu_16_12","chapterId":"ch_work_han_thu_16","textTraditional":"四三四頁　一欄　四格，景祐本作「削」，殿本作「耐」。","sentenceOrder":12},
  {"id":"s_work_han_thu_16_13","chapterId":"ch_work_han_thu_16","textTraditional":"四三六頁　二欄　三格，王先謙說「己」當為「乙」。　按景祐、殿本正作「乙」。","sentenceOrder":13},
  {"id":"s_work_han_thu_16_14","chapterId":"ch_work_han_thu_16","textTraditional":"四三七頁　三欄　一格「楊」，景祐、殿本都作「陽」。","sentenceOrder":14},
  {"id":"s_work_han_thu_16_15","chapterId":"ch_work_han_thu_16","textTraditional":"四三九頁　二欄　三格，王先謙說「九」當為「五」。　按景祐、殿、局本都作「五」。","sentenceOrder":15},
  {"id":"s_work_han_thu_16_16","chapterId":"ch_work_han_thu_16","textTraditional":"四四０頁　二欄　五格「恭」，景祐、殿、局本都作「莽」。　王先謙說作「莽」是。","sentenceOrder":16},
  {"id":"s_work_han_thu_16_17","chapterId":"ch_work_han_thu_16","textTraditional":"四四一頁　二欄　四格「二十」，景祐本作「三十」。","sentenceOrder":17},
  {"id":"s_work_han_thu_16_18","chapterId":"ch_work_han_thu_16","textTraditional":"四四一頁　四欄　三格「五年」，景祐、殿、局本都作「五月」。　王先謙說作「五月」是。","sentenceOrder":18},
  {"id":"s_work_han_thu_16_19","chapterId":"ch_work_han_thu_16","textTraditional":"四四三頁　二欄　二格「弟」，殿、局本都作「子」。　王先謙說作「子」是，史表同。","sentenceOrder":19},
  {"id":"s_work_han_thu_16_20","chapterId":"ch_work_han_thu_16","textTraditional":"四五０頁　四欄　四格「容」，王先謙說閩本、汪本都作「客」，史表同。　按景祐本作「客」。","sentenceOrder":20},
  {"id":"s_work_han_thu_16_21","chapterId":"ch_work_han_thu_16","textTraditional":"四五一頁　一欄　三格，王先謙說「十年」當作「十月」。　按景祐本作「十月」。","sentenceOrder":21},
  {"id":"s_work_han_thu_16_22","chapterId":"ch_work_han_thu_16","textTraditional":"四五一頁　五欄　一格，殿本作「曜」，景祐本誤作「曜」。","sentenceOrder":22},
  {"id":"s_work_han_thu_16_23","chapterId":"ch_work_han_thu_16","textTraditional":"四五三頁　二欄　三格「新」，殿、局本都作「薪」。","sentenceOrder":23},
  {"id":"s_work_han_thu_16_24","chapterId":"ch_work_han_thu_16","textTraditional":"四五三頁　三欄　三格原在四格，據景祐、殿、局本提上。","sentenceOrder":24},
  {"id":"s_work_han_thu_16_25","chapterId":"ch_work_han_thu_16","textTraditional":"四五四頁　四欄　三格「五月」，景祐、殿本都作「正月」。　王先謙說作「正月」是。","sentenceOrder":25},
  {"id":"s_work_han_thu_16_26","chapterId":"ch_work_han_thu_16","textTraditional":"四六六頁　一欄　四格，王念孫說「三」字誤，景祐本作「二十五年」。　五格「一十九年」，景祐、殿本「一」作「二」。　王先謙說作「二」是。","sentenceOrder":26},
  {"id":"s_work_han_thu_16_27","chapterId":"ch_work_han_thu_16","textTraditional":"四六六頁　二欄　四、五格原在三、四格，據景祐、殿本改。","sentenceOrder":27},
  {"id":"s_work_han_thu_16_28","chapterId":"ch_work_han_thu_16","textTraditional":"四六七頁　四欄　三格，王先謙說汪本「二」作「三」、「三」作「二」，是。　按景祐、殿本同。","sentenceOrder":28},
  {"id":"s_work_han_thu_16_29","chapterId":"ch_work_han_thu_16","textTraditional":"四六七頁　五欄　七格「子」，景祐、殿本都作「予」。","sentenceOrder":29},
  {"id":"s_work_han_thu_16_30","chapterId":"ch_work_han_thu_16","textTraditional":"四六八頁　一欄　三格「二月」，景祐、殿本都作「三月」。","sentenceOrder":30},
  {"id":"s_work_han_thu_16_31","chapterId":"ch_work_han_thu_16","textTraditional":"四六八頁　二欄　三格「二月」，景祐、殿本都作「三月」。","sentenceOrder":31},
  {"id":"s_work_han_thu_16_32","chapterId":"ch_work_han_thu_16","textTraditional":"四六九頁　二欄　七格「社」，景祐、殿、局本都作「祉」。　朱一新說作「祉」是。","sentenceOrder":32},
  {"id":"s_work_han_thu_16_33","chapterId":"ch_work_han_thu_16","textTraditional":"四六九頁　三欄　三格「八月」，景祐、殿、局本都作「八年」。　王先謙說作「八年」是。","sentenceOrder":33},
  {"id":"s_work_han_thu_16_34","chapterId":"ch_work_han_thu_16","textTraditional":"四七四頁　四欄　一格「于」，景祐、殿本都作「丁」。　五格「永」，景祐、殿本都作「元」。","sentenceOrder":34},
  {"id":"s_work_han_thu_16_35","chapterId":"ch_work_han_thu_16","textTraditional":"四七五頁　三欄　三格「十兩」，景祐、殿、局本都作「八兩」。　四格，錢大昭說「始元」當作「元始」。","sentenceOrder":35},
  {"id":"s_work_han_thu_16_36","chapterId":"ch_work_han_thu_16","textTraditional":"四七九頁　四欄　一格，王先謙說「成」當作「城」。　按景祐、殿本都作「城」。","sentenceOrder":36},
  {"id":"s_work_han_thu_17_1","chapterId":"ch_work_han_thu_17","textTraditional":"孝元之世，亡王子侯者，盛衰終始，豈非命哉！元始之際，王莽擅朝，偽褒宗室，侯及王之孫焉；〔一〕居攝而愈多，非其正，故弗錄。〔二〕旋踵亦絕，悲夫！","sentenceOrder":1},
  {"id":"s_work_han_thu_17_2","chapterId":"ch_work_han_thu_17","textTraditional":"〔一〕　師古曰：「王之孫亦得封侯，謂承鄉侯閟以下是也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_17_3","chapterId":"ch_work_han_thu_17","textTraditional":"〔二〕　師古曰：「王莽所封，故不以為正也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_17_4","chapterId":"ch_work_han_thu_17","textTraditional":"王子侯表第三下","sentenceOrder":4},
  {"id":"s_work_han_thu_17_5","chapterId":"ch_work_han_thu_17","textTraditional":"校勘記","sentenceOrder":5},
  {"id":"s_work_han_thu_17_6","chapterId":"ch_work_han_thu_17","textTraditional":"四八三頁　二欄　五格，錢大昭說「（暂缺）」不成字，閩本作「（暂缺E61A）」。　按殿本作「緁」。　注「于」，殿本作「千」。","sentenceOrder":6},
  {"id":"s_work_han_thu_17_7","chapterId":"ch_work_han_thu_17","textTraditional":"四八七頁　二欄　三格「十」，景祐、殿本都作「七」。　朱一新說作「七」是。","sentenceOrder":7},
  {"id":"s_work_han_thu_17_8","chapterId":"ch_work_han_thu_17","textTraditional":"四八七頁　三欄　三格「二」，景祐、殿本都作「三」。","sentenceOrder":8},
  {"id":"s_work_han_thu_17_9","chapterId":"ch_work_han_thu_17","textTraditional":"四八七頁　三欄　三格「二」，景祐、殿本都作「三」。　王先謙說作「三」是。","sentenceOrder":9},
  {"id":"s_work_han_thu_17_10","chapterId":"ch_work_han_thu_17","textTraditional":"四八八頁　一欄　三格，錢大昭說「乙」當作「己」，下修故侯亦誤。　按殿本都作「己」。","sentenceOrder":10},
  {"id":"s_work_han_thu_17_11","chapterId":"ch_work_han_thu_17","textTraditional":"四八九頁　二欄　三格「三」，景祐、殿本都作「二」。　蘇輿說作「二」是。","sentenceOrder":11},
  {"id":"s_work_han_thu_17_12","chapterId":"ch_work_han_thu_17","textTraditional":"四九０頁　四欄　三格「四年」，景祐、殿、局本都作「四月」。","sentenceOrder":12},
  {"id":"s_work_han_thu_17_13","chapterId":"ch_work_han_thu_17","textTraditional":"四九二頁　一欄　一格「平」，景祐本作「年」，殿本脫。　注「力」，景祐、殿本都作「方」。","sentenceOrder":13},
  {"id":"s_work_han_thu_17_14","chapterId":"ch_work_han_thu_17","textTraditional":"四九三頁　一欄　三格，蘇輿說「二年」當作「三年」。　按景祐本作「三年」","sentenceOrder":14},
  {"id":"s_work_han_thu_17_15","chapterId":"ch_work_han_thu_17","textTraditional":"四九四頁　七欄　一格「王」，殿本作「壬」。　王先謙說作「壬」是。","sentenceOrder":15},
  {"id":"s_work_han_thu_17_16","chapterId":"ch_work_han_thu_17","textTraditional":"四九五頁　二欄　三格「二月」，景祐、殿本都作「三月」。　朱一新說作「三月」是。","sentenceOrder":16},
  {"id":"s_work_han_thu_17_17","chapterId":"ch_work_han_thu_17","textTraditional":"四九六頁　四欄　五格「固」，景祐、殿本都作「國」。","sentenceOrder":17},
  {"id":"s_work_han_thu_17_18","chapterId":"ch_work_han_thu_17","textTraditional":"四九八頁　七欄　四格「免」，景祐、殿、局本都作「嗣」。　朱一新說作「嗣」是。","sentenceOrder":18},
  {"id":"s_work_han_thu_17_19","chapterId":"ch_work_han_thu_17","textTraditional":"四九九頁　二欄　五格「欽」，錢大昭說閩本作「褒」，朱一新說注本作「褒」。　按景祐、殿本都作「煬」。","sentenceOrder":19},
  {"id":"s_work_han_thu_17_20","chapterId":"ch_work_han_thu_17","textTraditional":"五一一頁　一欄　四格，朱一新說注本「免」作「薨」。　按景祐、殿本都作「薨」。","sentenceOrder":20},
  {"id":"s_work_han_thu_17_21","chapterId":"ch_work_han_thu_17","textTraditional":"五二０頁　四欄　三格「免」，據景祐、殿、局本補。","sentenceOrder":21},
  {"id":"s_work_han_thu_17_22","chapterId":"ch_work_han_thu_17","textTraditional":"五二一頁　二欄　一格「成」，景祐、殿本都作「城」。","sentenceOrder":22},
  {"id":"s_work_han_thu_17_23","chapterId":"ch_work_han_thu_17","textTraditional":"五二三頁　一欄　一格，錢大昭說「連」不成字，汪本作「疌」。　按景祐、殿本都作「疌」。","sentenceOrder":23},
  {"id":"s_work_han_thu_18_1","chapterId":"ch_work_han_thu_18","textTraditional":"自古帝王之興，曷嘗不建輔弼之臣所與共成天功者乎！〔一〕漢興自秦二世元年之秋，楚陳之歲，〔二〕初以沛公總帥雄俊，三年然後西滅秦，立漢王之號，五年東克項羽，即皇帝位，八載而天下乃平，始論功而定封。訖十二年，侯者百四十有三人。時大城名都民人散亡，戶口可得而數裁什二三，〔三〕是以大侯不過萬家，小者五六百戶。封爵之誓曰：「使黃河如帶，泰山若厲，國以永存，爰及苗裔。」〔四〕於是申以丹書之信，重以白馬之盟，〔五〕又作十八侯之位次。〔六〕高后二年，復詔丞相陳平盡差列侯之功，錄弟下竟，臧諸宗廟，副在有司。〔七〕始未嘗不欲固根本，而枝葉稍落也。","sentenceOrder":1},
  {"id":"s_work_han_thu_18_2","chapterId":"ch_work_han_thu_18","textTraditional":"〔一〕　師古曰：「天功，天下之功業也。虞書舜典曰『欽哉，惟時亮天功』也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_18_3","chapterId":"ch_work_han_thu_18","textTraditional":"〔二〕　師古曰：「謂陳涉自稱楚王時也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_18_4","chapterId":"ch_work_han_thu_18","textTraditional":"〔三〕　師古曰：「裁與纔同，十分之內纔有二三也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_18_5","chapterId":"ch_work_han_thu_18","textTraditional":"〔四〕　應劭曰：「封爵之誓，國家欲使功臣傳祚無窮也。帶，衣帶也。厲，砥厲石也。河當何時如衣帶，山當何時如厲石，言如帶厲，國猶永存，以及後世之子孫也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_18_6","chapterId":"ch_work_han_thu_18","textTraditional":"〔五〕　師古曰：「丹書，解在高紀。白馬之盟，謂刑白馬歃其血以為盟也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_18_7","chapterId":"ch_work_han_thu_18","textTraditional":"〔六〕　孟康曰：「唯作元功蕭、曹等十八人位次耳。高后乃詔作位次下竟。」師古曰：「謂蕭何、曹參、張敖、周勃、樊噲、酈商、奚涓、夏侯嬰、灌嬰、傅寬、靳歙、王陵、陳武、王吸、薛歐、周昌、丁復、蟲達，從第一至十八也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_18_8","chapterId":"ch_work_han_thu_18","textTraditional":"〔七〕　師古曰：「副，貳也。其列侯功籍已藏於宗廟，副貳之本又在有司。」","sentenceOrder":8},
  {"id":"s_work_han_thu_18_9","chapterId":"ch_work_han_thu_18","textTraditional":"故逮文、景四五世間，流民既歸，戶口亦息，列侯大者至三四萬戶，小國自倍，〔一〕富厚如之。〔二〕子孫驕逸，忘其先祖之艱難，多陷法禁，隕命亡國，〔或〕（云）〔亡〕子孫。訖於孝武後元之年，靡有孑遺，耗矣。〔三〕罔亦少密焉。〔四〕故孝宣皇帝愍而錄之，乃開廟臧，覽舊籍，詔令有司求其子孫，咸出庸保之中，〔五〕並受復除，或加以金帛，〔六〕用章中興之德。","sentenceOrder":9},
  {"id":"s_work_han_thu_18_10","chapterId":"ch_work_han_thu_18","textTraditional":"〔一〕　師古曰：「自倍者，謂舊五百戶，今者至千也。曹參初封萬六百戶，至後嗣侯宗免時，有戶二萬三千，是為戶口蕃息故也。它皆類此。」","sentenceOrder":10},
  {"id":"s_work_han_thu_18_11","chapterId":"ch_work_han_thu_18","textTraditional":"〔二〕　師古曰：「言其貲財亦稍富厚，各如戶口之多也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_18_12","chapterId":"ch_work_han_thu_18","textTraditional":"〔三〕　孟康曰：「耗音毛。無有毛米在者也。」師古曰：「孟音是也，而解非也。孑然，獨立貌，言無有獨存者，至於耗盡也。今俗語猶謂無為耗，音毛。」","sentenceOrder":12},
  {"id":"s_work_han_thu_18_13","chapterId":"ch_work_han_thu_18","textTraditional":"〔四〕　服虔曰：「法罔差益密也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_18_14","chapterId":"ch_work_han_thu_18","textTraditional":"〔五〕　師古曰：「庸，〔賣〕功庸也；保，可安信也：皆賃作者也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_18_15","chapterId":"ch_work_han_thu_18","textTraditional":"〔六〕　師古曰：「復音方目反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_18_16","chapterId":"ch_work_han_thu_18","textTraditional":"降及孝成，復加卹問，稍益衰微，不絕如綫。〔一〕善乎，杜業之納說也！曰：「昔唐以萬國致時雍之政，〔二〕虞、夏以（之）多群后饗共己之治。〔三〕湯法三聖，殷氏太平。〔四〕周封八百，重譯來賀。〔五〕是以內恕之君樂繼絕世，隆名之主安立亡國，〔六〕至於不及下車，德念深矣。〔七〕成王察牧野之克，顧群后之勤，知其恩結於民心，功光於王府也，故追述先父之志，錄遺老之策，高其位，大其{宀禹}，〔八〕愛敬飭盡，命賜備厚。〔九〕大孝之隆，於是為至。至其沒也，世主歎其功，無民而不思。所息之樹且猶不伐，〔一０〕況其廟乎？是以燕、齊之祀與周並傳，子繼弟及，歷載不墮〔一一〕。豈無刑辟，繇祖之竭力，故支庶賴焉。〔一二〕跡漢功臣，亦皆割符世爵，受山河之誓，存以著其號，亡以顯其魂，賞亦不細矣。百餘年間而襲封者盡，或絕失姓，或乏無主，朽骨孤於墓，苗裔流於道，生為愍隸，死為轉屍。〔一三〕以往況今，甚可悲傷。〔一四〕聖朝憐閔，詔求其後，四方忻忻，靡不歸心。出入數年而不省察，恐議者不思大義，設言虛亡，則厚德掩息，遴柬布章，〔一五〕非所以視化勸後也。〔一六〕三人為眾，雖難盡繼，宜從尤功。」〔一七〕於是成帝復紹蕭何。","sentenceOrder":16},
  {"id":"s_work_han_thu_18_17","chapterId":"ch_work_han_thu_18","textTraditional":"〔一〕　晉灼曰：「綫，今線縷字也，音先戰反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_18_18","chapterId":"ch_work_han_thu_18","textTraditional":"〔二〕　師古曰：「雍，和也。堯典云『黎萌於變時雍』，故杜業引之也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_18_19","chapterId":"ch_work_han_thu_18","textTraditional":"〔三〕　師古曰：「群后謂諸侯也。恭己，無為也。孔子曰：『無為而治者，其舜也歟！夫何為哉？恭己正南面而已。』共讀曰恭。」","sentenceOrder":19},
  {"id":"s_work_han_thu_18_20","chapterId":"ch_work_han_thu_18","textTraditional":"〔四〕　師古曰：「三聖謂堯、舜、禹也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_18_21","chapterId":"ch_work_han_thu_18","textTraditional":"〔五〕　師古曰：「重譯謂越裳氏也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_18_22","chapterId":"ch_work_han_thu_18","textTraditional":"〔六〕　師古曰：「以立亡國之後為安泰也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_18_23","chapterId":"ch_work_han_thu_18","textTraditional":"〔七〕　張晏曰：「謂武王入殷，未及下車，封黃帝之後於薊，虞舜之後於陳也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_18_24","chapterId":"ch_work_han_thu_18","textTraditional":"〔八〕　師古曰：「{宀禹}謂啟土所居也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_18_25","chapterId":"ch_work_han_thu_18","textTraditional":"〔九〕　師古曰：「飭，謹也，讀與敕同。」","sentenceOrder":25},
  {"id":"s_work_han_thu_18_26","chapterId":"ch_work_han_thu_18","textTraditional":"〔一０〕師古曰：「謂召伯止於甘棠之下而聽訟，人思其德，不伐其樹，召南甘棠之詩是也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_18_27","chapterId":"ch_work_han_thu_18","textTraditional":"〔一一〕師古曰：「弟代兄位謂之及。墮，毀也，音火規反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_18_28","chapterId":"ch_work_han_thu_18","textTraditional":"〔一二〕師古曰：「言國家非無刑辟，而功臣子孫得不陷罪辜而能長存者，思其先人之力，令有續嗣也。繇讀與由同。」","sentenceOrder":28},
  {"id":"s_work_han_thu_18_29","chapterId":"ch_work_han_thu_18","textTraditional":"〔一三〕應劭曰：「死不能葬，故屍流轉在溝壑之中。」師古曰：「愍隸者，言為徒隸，可哀愍之也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_18_30","chapterId":"ch_work_han_thu_18","textTraditional":"〔一四〕師古曰：「況，譬也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_18_31","chapterId":"ch_work_han_thu_18","textTraditional":"〔一五〕晉灼曰：「許慎云『遴，難行也』。柬，古簡字也。簡，少也。言今難行封，則得繼絕者少，若然，此必布聞彰於天下也。」師古曰：「遴讀與吝同。」","sentenceOrder":31},
  {"id":"s_work_han_thu_18_32","chapterId":"ch_work_han_thu_18","textTraditional":"〔一六〕師古曰：「視讀與示同。」","sentenceOrder":32},
  {"id":"s_work_han_thu_18_33","chapterId":"ch_work_han_thu_18","textTraditional":"〔一七〕孟康曰：「言人三為眾，雖難盡繼，取其功尤高者（三）〔一〕人繼之，於名為眾矣。」服虔曰：「尤功，封重者一人也。」師古曰：「孟說是也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_18_34","chapterId":"ch_work_han_thu_18","textTraditional":"哀、平之世，增修曹參、周勃之屬，得其宜矣。以綴續前記，究其本末，并序位次，盡于孝文，以昭元功之候籍（云）。〔一〕","sentenceOrder":34},
  {"id":"s_work_han_thu_18_35","chapterId":"ch_work_han_thu_18","textTraditional":"〔一〕　師古曰：「籍謂名錄也，高紀所云通侯籍也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_18_36","chapterId":"ch_work_han_thu_18","textTraditional":"高惠高后文功臣表第四","sentenceOrder":36},
  {"id":"s_work_han_thu_18_37","chapterId":"ch_work_han_thu_18","textTraditional":"校勘記","sentenceOrder":37},
  {"id":"s_work_han_thu_18_38","chapterId":"ch_work_han_thu_18","textTraditional":"五二八頁　八行　隕命亡國，〔或〕（云）〔亡〕子孫。　錢大昭所見閩本、朱一新所見汪本都作「或亡子孫」。王先謙說閩、汪本是。","sentenceOrder":38},
  {"id":"s_work_han_thu_18_39","chapterId":"ch_work_han_thu_18","textTraditional":"五二九頁　一行　庸，〔賣〕功庸也；朱一新說汪本有「賣」字是。　按景祐、殿本都有。","sentenceOrder":39},
  {"id":"s_work_han_thu_18_40","chapterId":"ch_work_han_thu_18","textTraditional":"五二九頁　四行　虞、夏以（之）多群后饗共己之治。　王念孫說「以」下「之」字涉上下文而衍，漢紀孝成紀無。","sentenceOrder":40},
  {"id":"s_work_han_thu_18_41","chapterId":"ch_work_han_thu_18","textTraditional":"五三一頁　一行　取其功尤高者（三）〔一〕人繼之，景祐、殿本都作「一」。　王先謙說作「一」是。","sentenceOrder":41},
  {"id":"s_work_han_thu_18_42","chapterId":"ch_work_han_thu_18","textTraditional":"五三一頁　四行　錢大昭、朱一新說閩、汪本無「云」字。　按景祐本亦無。","sentenceOrder":42},
  {"id":"s_work_han_thu_18_43","chapterId":"ch_work_han_thu_18","textTraditional":"五三二頁　三欄　五格「本治」，錢大昭說當作「本始」。　按景祐、殿本都作「本始」。","sentenceOrder":43},
  {"id":"s_work_han_thu_18_44","chapterId":"ch_work_han_thu_18","textTraditional":"五三三頁　三欄　七格「元光三年」，景祐本作「二年」。朱一新說史記作「二年」是。下脫「婢」字，史表有。","sentenceOrder":44},
  {"id":"s_work_han_thu_18_45","chapterId":"ch_work_han_thu_18","textTraditional":"五三五頁　二欄　五格「二十四年」，景祐、殿本都作「二十二年」。六格「十二年」，景祐本作「二十二年」。","sentenceOrder":45},
  {"id":"s_work_han_thu_18_46","chapterId":"ch_work_han_thu_18","textTraditional":"五三七頁　三欄　三格，蘇輿說「六」字蓋「十八」二字之駮文。　按景祐本正作「十八」。","sentenceOrder":46},
  {"id":"s_work_han_thu_18_47","chapterId":"ch_work_han_thu_18","textTraditional":"五四０頁　二欄　四格，王先謙說「傳」是「得」之誤。　按景祐、殿、局本都作「得」。","sentenceOrder":47},
  {"id":"s_work_han_thu_18_48","chapterId":"ch_work_han_thu_18","textTraditional":"五四五頁　二欄　五格「後二年」，朱一新說汪本「二」作「三」是。　按景祐本作「三」。","sentenceOrder":48},
  {"id":"s_work_han_thu_18_49","chapterId":"ch_work_han_thu_18","textTraditional":"五四五頁　三欄　五格「後元元年」，朱一新說汪本作「後元年」是。　按景祐本作「後元年」。","sentenceOrder":49},
  {"id":"s_work_han_thu_18_50","chapterId":"ch_work_han_thu_18","textTraditional":"五四六頁　三欄　六格「老」，景祐、殿、局本都作「孝」。","sentenceOrder":50},
  {"id":"s_work_han_thu_18_51","chapterId":"ch_work_han_thu_18","textTraditional":"五五一頁　二欄　三格，景祐、殿本都作「三十年」。","sentenceOrder":51},
  {"id":"s_work_han_thu_18_52","chapterId":"ch_work_han_thu_18","textTraditional":"五五四頁　一欄　五格，蘇輿說「三」當作「二」。　按景祐本正作「二」。","sentenceOrder":52},
  {"id":"s_work_han_thu_18_53","chapterId":"ch_work_han_thu_18","textTraditional":"五五五頁　三欄　一格，景祐、殿本都作「如淳」。","sentenceOrder":53},
  {"id":"s_work_han_thu_18_54","chapterId":"ch_work_han_thu_18","textTraditional":"五五六頁　二欄　二格「一歲」，景祐本作「二歲」，史表同。「臨薔」，王鳴盛說監本作「臨菑」，「薔」字誤。按殿、局本都作「臨菑」。　三格「四十八年」，景祐、殿本都作「三十八年」。","sentenceOrder":54},
  {"id":"s_work_han_thu_18_55","chapterId":"ch_work_han_thu_18","textTraditional":"五五七頁　二欄　二格，王先謙說「公」字衍。按史表作「以舍人從至霸上」。　六格，王先謙說史作「逮御史大夫湯」，張湯也，此誤。","sentenceOrder":55},
  {"id":"s_work_han_thu_18_56","chapterId":"ch_work_han_thu_18","textTraditional":"五五八頁　三欄　五格，朱一新說汪本「一」作「二」是。　王先謙說「太」殿本作「大」是。　按景祐本正作「二」作「大」。","sentenceOrder":56},
  {"id":"s_work_han_thu_18_57","chapterId":"ch_work_han_thu_18","textTraditional":"五六三頁　一欄　五格，殿本有「家」字，此脫，景祐本亦脫。","sentenceOrder":57},
  {"id":"s_work_han_thu_18_58","chapterId":"ch_work_han_thu_18","textTraditional":"五六六頁　一欄　二格，王先謙說史表無「頃侯諸莊」四字，疑衍。","sentenceOrder":58},
  {"id":"s_work_han_thu_18_59","chapterId":"ch_work_han_thu_18","textTraditional":"五六六頁　二欄　五格原在六格，據景祐、殿、局本提上。","sentenceOrder":59},
  {"id":"s_work_han_thu_18_60","chapterId":"ch_work_han_thu_18","textTraditional":"五七一頁　一欄　二格，王先謙說「邑益」當作「益邑」。　按殿本作「益邑」。","sentenceOrder":60},
  {"id":"s_work_han_thu_18_61","chapterId":"ch_work_han_thu_18","textTraditional":"五七四頁　三欄　六格，王先謙說史表「中三年」作「中二年」。　按景祐本亦作「中二年」。","sentenceOrder":61},
  {"id":"s_work_han_thu_18_62","chapterId":"ch_work_han_thu_18","textTraditional":"五七五頁　二欄　二格，據史表校，「秋」當作「秩」。","sentenceOrder":62},
  {"id":"s_work_han_thu_18_63","chapterId":"ch_work_han_thu_18","textTraditional":"五七七頁　三欄　五格，王先謙說「侯」下奪「賀」字，史表「賀」字兩見。","sentenceOrder":63},
  {"id":"s_work_han_thu_18_64","chapterId":"ch_work_han_thu_18","textTraditional":"五七八頁　二欄　五格，朱一新說汪本「二」作「三」是。　按殿本作「三」。","sentenceOrder":64},
  {"id":"s_work_han_thu_18_65","chapterId":"ch_work_han_thu_18","textTraditional":"五七九頁　一欄　六格，殿本「三」作「五」。　齊召南說作「三」非。","sentenceOrder":65},
  {"id":"s_work_han_thu_18_66","chapterId":"ch_work_han_thu_18","textTraditional":"五八０頁　三欄　二格，「稅」字據史表集解引補。","sentenceOrder":66},
  {"id":"s_work_han_thu_18_67","chapterId":"ch_work_han_thu_18","textTraditional":"五八一頁　二欄　六格「十二年」，景祐、殿本都作「十三年」，史表同。","sentenceOrder":67},
  {"id":"s_work_han_thu_18_68","chapterId":"ch_work_han_thu_18","textTraditional":"五八七頁　二欄　六格「三十年」，景祐、殿本都作「十二年」。","sentenceOrder":68},
  {"id":"s_work_han_thu_18_69","chapterId":"ch_work_han_thu_18","textTraditional":"五八九頁　五欄　六格「文侯」，景祐、殿本都作「孝文」，此誤。","sentenceOrder":69},
  {"id":"s_work_han_thu_18_70","chapterId":"ch_work_han_thu_18","textTraditional":"五九二頁　一欄　八格，蘇輿說「二十九」當作「三十九」。　按景祐本正作「三十九」。","sentenceOrder":70},
  {"id":"s_work_han_thu_18_71","chapterId":"ch_work_han_thu_18","textTraditional":"五九二頁　二欄　五格，王念孫說「十二年」景祐本作「十三年」是。","sentenceOrder":71},
  {"id":"s_work_han_thu_18_72","chapterId":"ch_work_han_thu_18","textTraditional":"五九三頁　一欄　五格，「家」字據景祐、殿本補。","sentenceOrder":72},
  {"id":"s_work_han_thu_18_73","chapterId":"ch_work_han_thu_18","textTraditional":"六０七頁　二欄　五格，王先謙說殿本「一」作「二」是。","sentenceOrder":73},
  {"id":"s_work_han_thu_18_74","chapterId":"ch_work_han_thu_18","textTraditional":"六０九頁　三欄　二格，殿本「城」作「成」，王先謙說作「成」是。","sentenceOrder":74},
  {"id":"s_work_han_thu_18_75","chapterId":"ch_work_han_thu_18","textTraditional":"六一二頁　二欄　二格「拓」，景祐、殿本都作「柘」。","sentenceOrder":75},
  {"id":"s_work_han_thu_18_76","chapterId":"ch_work_han_thu_18","textTraditional":"六一四頁　三欄　二格，王先謙說「入」脫「漢」字，史表有。","sentenceOrder":76},
  {"id":"s_work_han_thu_18_77","chapterId":"ch_work_han_thu_18","textTraditional":"六一七頁　一欄　四格「五十一」，錢大昭說當從史表作「五十二」。　按景祐、殿本正作「五十二」。","sentenceOrder":77},
  {"id":"s_work_han_thu_18_78","chapterId":"ch_work_han_thu_18","textTraditional":"六一七頁　二欄　一格，景祐、殿本都作「鹵嚴侯」。","sentenceOrder":78},
  {"id":"s_work_han_thu_18_79","chapterId":"ch_work_han_thu_18","textTraditional":"六一八頁　三欄　四格，錢大昭說閩本作「百二十」是。　按景祐、殿本都作「百二十」。","sentenceOrder":79},
  {"id":"s_work_han_thu_18_80","chapterId":"ch_work_han_thu_18","textTraditional":"六二０頁　三欄　八格，朱一新說元鼎「四年」「二年」誤倒。　按局本不誤。","sentenceOrder":80},
  {"id":"s_work_han_thu_18_81","chapterId":"ch_work_han_thu_18","textTraditional":"六二二頁　二欄　一格，王先謙說史表「成」作「平」。　按景祐、殿本都作「平」。","sentenceOrder":81},
  {"id":"s_work_han_thu_18_82","chapterId":"ch_work_han_thu_18","textTraditional":"六二六頁　三欄　三格「二月」，景祐、殿本都作「三月」。","sentenceOrder":82},
  {"id":"s_work_han_thu_18_83","chapterId":"ch_work_han_thu_18","textTraditional":"六三０頁　三欄　六格「清安」，據景祐、殿、局本補，史表有。","sentenceOrder":83},
  {"id":"s_work_han_thu_18_84","chapterId":"ch_work_han_thu_18","textTraditional":"六三一頁　二行　管、氏（營）丘、營平錢大昕說王子侯表管一國，氏丘一國，營平一國，此「氏」","sentenceOrder":84},
  {"id":"s_work_han_thu_19_1","chapterId":"ch_work_han_thu_19","textTraditional":"昔書稱「蠻夷帥服」，〔一〕詩云「徐方既來」，〔二〕春秋列潞子之爵，許其慕諸夏也。〔三〕漢興至于孝文時，乃有弓高、襄城之封，〔四〕雖自外來，本功臣後。故至孝景始欲侯降者，丞相周亞夫守約而爭。〔五〕帝黜其議，初開封賞之科，〔六〕又有吳楚之事。武興胡越之伐，將帥受爵，應本約矣。〔七〕後（有）〔世〕承平，頗有勞臣，輯而序之，續元功次云。〔八〕","sentenceOrder":1},
  {"id":"s_work_han_thu_19_2","chapterId":"ch_work_han_thu_19","textTraditional":"〔一〕師古曰：「舜典之辭也。言王者德澤廣被，則四夷相率而降服也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_19_3","chapterId":"ch_work_han_thu_19","textTraditional":"〔二〕師古曰：「大雅常武之詩曰：『王猷允塞，徐方既　。』言周之王道信能充實，則徐方、淮夷並來朝也。俫，古來字。」","sentenceOrder":3},
  {"id":"s_work_han_thu_19_4","chapterId":"ch_work_han_thu_19","textTraditional":"〔三〕應劭曰：「潞子離狄內附，春秋嘉之，稱其爵，列諸盟會也。」師古曰：「潞音路。」","sentenceOrder":4},
  {"id":"s_work_han_thu_19_5","chapterId":"ch_work_han_thu_19","textTraditional":"〔四〕師古曰：「弓高侯穨當，襄城侯桀龍，皆從匈奴來降而得封也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_19_6","chapterId":"ch_work_han_thu_19","textTraditional":"〔五〕應劭曰：「景帝欲封王皇后兄信，亞夫對『高祖之約，非功臣不侯也』。」師古曰：「景帝欲封匈奴降者徐盧等，而亞夫爭之，以為不可。今表所稱，蓋謂此爾，不列王信事也。應說失之。」","sentenceOrder":6},
  {"id":"s_work_han_thu_19_7","chapterId":"ch_work_han_thu_19","textTraditional":"〔六〕師古曰：「不從亞夫之言，竟封也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_19_8","chapterId":"ch_work_han_thu_19","textTraditional":"〔七〕　師古曰：「應高祖非有功不得侯之約。」","sentenceOrder":8},
  {"id":"s_work_han_thu_19_9","chapterId":"ch_work_han_thu_19","textTraditional":"〔八〕　師古曰：「輯與集同。元功，謂佐興其帝業者也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_19_10","chapterId":"ch_work_han_thu_19","textTraditional":"景武昭宣元成功臣表第五","sentenceOrder":10},
  {"id":"s_work_han_thu_19_11","chapterId":"ch_work_han_thu_19","textTraditional":"校勘記","sentenceOrder":11},
  {"id":"s_work_han_thu_19_12","chapterId":"ch_work_han_thu_19","textTraditional":"六三五頁　六行　後（有）〔世〕承平，　景祐、殿本都作「世」。王先謙說作「世」是。","sentenceOrder":12},
  {"id":"s_work_han_thu_19_13","chapterId":"ch_work_han_thu_19","textTraditional":"六三六頁　三欄　三格，王先謙說「四年」當作「四月」。按景祐、殿、局本都作「四月」","sentenceOrder":13},
  {"id":"s_work_han_thu_19_14","chapterId":"ch_work_han_thu_19","textTraditional":"六三七頁　二欄　四格「獲」，景祐、殿本都作「復」。王先謙說作「復」是。","sentenceOrder":14},
  {"id":"s_work_han_thu_19_15","chapterId":"ch_work_han_thu_19","textTraditional":"六四０頁　二欄　一格「翕侯」，王先謙說史表作「易侯」是。按景祐、殿本都作「易侯」。","sentenceOrder":15},
  {"id":"s_work_han_thu_19_16","chapterId":"ch_work_han_thu_19","textTraditional":"六四０頁　四欄　二格，王先謙說「漢」當為「侯」。按殿、局本作「侯」，景祐本亦誤。","sentenceOrder":16},
  {"id":"s_work_han_thu_19_17","chapterId":"ch_work_han_thu_19","textTraditional":"六四一頁　二欄　四格，蘇輿說「後」下「元」字衍。按景祐本無。","sentenceOrder":17},
  {"id":"s_work_han_thu_19_18","chapterId":"ch_work_han_thu_19","textTraditional":"六四七頁　一欄　三格，王先謙說史表「上容」作「上谷」，「戈守」作「戍卒」，「計」上有「上」字，是。按景祐、殿本「谷」「卒」二字不誤，局本「卒」亦誤作「守」。","sentenceOrder":18},
  {"id":"s_work_han_thu_19_19","chapterId":"ch_work_han_thu_19","textTraditional":"六四七頁　三欄　二格，王先謙說史表作「得兩王子騎將功侯」，此表「子」誤「千」，又奪「將」字。三格「匈奴河」，史表無「奴」字。王說此衍。","sentenceOrder":19},
  {"id":"s_work_han_thu_19_20","chapterId":"ch_work_han_thu_19","textTraditional":"六五二頁　三欄　三格「六年」，景祐、殿本都作「六月」。五格「二」，景祐、殿、局本都作「上」。","sentenceOrder":20},
  {"id":"s_work_han_thu_19_21","chapterId":"ch_work_han_thu_19","textTraditional":"六五二頁　四欄　三格「六年」，景祐、殿本都作「六月」，史表同。","sentenceOrder":21},
  {"id":"s_work_han_thu_19_22","chapterId":"ch_work_han_thu_19","textTraditional":"六五三頁　三欄　三格，蘇輿說「三年」當作「三月」。按景祐、殿、局本都作「三月」。","sentenceOrder":22},
  {"id":"s_work_han_thu_19_23","chapterId":"ch_work_han_thu_19","textTraditional":"六五四頁　五欄　三格，王先謙說「五年」當為「五月」。按殿本作「五月」。","sentenceOrder":23},
  {"id":"s_work_han_thu_19_24","chapterId":"ch_work_han_thu_19","textTraditional":"六五六頁　二欄　七格「堵陽」，據景祐、殿本補。","sentenceOrder":24},
  {"id":"s_work_han_thu_19_25","chapterId":"ch_work_han_thu_19","textTraditional":"六五七頁　四欄　四烙「延和」當作「征和」。衛太子死於征和二年。漢無延和年號。","sentenceOrder":25},
  {"id":"s_work_han_thu_19_26","chapterId":"ch_work_han_thu_19","textTraditional":"六五九頁　三欄　一格，錢大昭說南監本、閩本「直」作「苴」。按景祐、殿、局本都作「苴」。","sentenceOrder":26},
  {"id":"s_work_han_thu_19_27","chapterId":"ch_work_han_thu_19","textTraditional":"六六一頁　四欄　二格，王先謙說「都」是「郁」傳寫之誤。按景祐、殿本都作「郁」。","sentenceOrder":27},
  {"id":"s_work_han_thu_19_28","chapterId":"ch_work_han_thu_19","textTraditional":"六六四頁　二欄　二格，王先謙說「李」乃「太子」二字合誤一字。按景祐、殿、局本都作「太子」。","sentenceOrder":28},
  {"id":"s_work_han_thu_19_29","chapterId":"ch_work_han_thu_19","textTraditional":"六六六頁　四欄　二格，朱一新說據傳，「三千」當作「二千」。按景祐、殿本都作「二千」。","sentenceOrder":29},
  {"id":"s_work_han_thu_19_30","chapterId":"ch_work_han_thu_19","textTraditional":"六七四頁　二欄　三格「煬」，景祐、殿本都作「鴻」。王先謙說作「鴻」是。","sentenceOrder":30},
  {"id":"s_work_han_thu_20_1","chapterId":"ch_work_han_thu_20","textTraditional":"自古受命及中興之君，必興滅繼絕，修廢舉逸，然後天下歸仁，四方之政行焉。〔一〕傳稱武王克殷，追存賢聖，至乎不及下車〔二〕。世代雖殊，其揆一也。高帝撥亂誅暴，庶事草創，日不暇給，然猶修祀六國，求聘四皓，過魏則寵無忌之墓，適趙則封樂毅之後〔三〕。及其行賞而授位也，爵以功為先後，官用能為次序。後嗣共己遵業，舊臣繼踵居位。〔四〕至乎孝武，元功宿將略盡。會上亦興文學，進拔幽隱，公孫弘自海瀕而登宰相，〔五〕於是寵以列侯之爵。又疇咨前代，詢問耆老，初得周後，復加爵邑。自是之後，宰相畢侯矣。元、成之間，晚得殷世，以備賓位。","sentenceOrder":1},
  {"id":"s_work_han_thu_20_2","chapterId":"ch_work_han_thu_20","textTraditional":"〔一〕　師古曰：「論語孔子陳帝王之法云『審法度，修廢官，四方之政行焉；興滅國，繼絕世，舉逸人，天下之人歸心焉。』故此序引之也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_20_3","chapterId":"ch_work_han_thu_20","textTraditional":"〔二〕　師古曰：「禮記云『武王克殷，未及下車，而封黃帝之後於薊，封帝堯之後於祝，封帝舜之後於陳。』此其事也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_20_4","chapterId":"ch_work_han_thu_20","textTraditional":"〔三〕　師古曰：「高紀十二年詔云：『秦皇帝、楚隱王、魏安釐王、齊愍王、趙悼襄王皆絕無後。其與秦皇帝守冢二十家，楚、魏、齊各十家，趙及魏公子無忌各五家。』張良傳高帝謂四人曰『吾求公，公避逃我，今公何自從吾兒游乎？』又高紀十年『求樂毅有後乎，得其孫叔，封之樂鄉，號華成君』也。楚、魏、齊、趙皆舊六國，故總云六國。四皓須眉皓白，故謂之四皓。稱號在王貢兩龔鮑傳。」","sentenceOrder":4},
  {"id":"s_work_han_thu_20_5","chapterId":"ch_work_han_thu_20","textTraditional":"〔四〕　師古曰：「共讀曰恭。」","sentenceOrder":5},
  {"id":"s_work_han_thu_20_6","chapterId":"ch_work_han_thu_20","textTraditional":"〔五〕　師古曰：「海瀕，謂近海之地。瀕音頻，又音賓。」","sentenceOrder":6},
  {"id":"s_work_han_thu_20_7","chapterId":"ch_work_han_thu_20","textTraditional":"漢興，外戚與定天下，侯者二人。〔一〕故誓曰：「非劉氏不王，若有亡功非上所置而侯者，天下共誅之。」是以高后欲王諸呂，王陵廷爭；孝景將侯王氏，脩侯犯色。〔二〕卒用廢黜。是後薄昭、竇嬰、上官、衛、霍之侯，以功受爵。其餘后父據春秋褒紀之義，〔三〕帝舅緣大雅申伯之意，〔四〕寖廣博矣。〔五〕是以別而敘之。","sentenceOrder":7},
  {"id":"s_work_han_thu_20_8","chapterId":"ch_work_han_thu_20","textTraditional":"〔一〕　服虔曰：「呂后兄周呂侯澤、建成侯釋之。」師古曰：「與讀曰豫，言豫其功也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_20_9","chapterId":"ch_work_han_thu_20","textTraditional":"〔二〕　師古曰：「脩音條。」","sentenceOrder":9},
  {"id":"s_work_han_thu_20_10","chapterId":"ch_work_han_thu_20","textTraditional":"〔三〕　應劭曰：「春秋，天子將納后於紀，紀本子爵也，故先褒為侯，言王者不取於小國。」","sentenceOrder":10},
  {"id":"s_work_han_thu_20_11","chapterId":"ch_work_han_thu_20","textTraditional":"〔四〕　應劭曰：「申伯，周宣王元舅也，為邑於謝。後世欲光寵外親者，緣申伯之恩，援此義以為諭也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_20_12","chapterId":"ch_work_han_thu_20","textTraditional":"〔五〕　師古曰：「寖，漸也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_20_13","chapterId":"ch_work_han_thu_20","textTraditional":"外戚恩澤侯表第六","sentenceOrder":13},
  {"id":"s_work_han_thu_20_14","chapterId":"ch_work_han_thu_20","textTraditional":"校勘記","sentenceOrder":14},
  {"id":"s_work_han_thu_20_15","chapterId":"ch_work_han_thu_20","textTraditional":"六八六頁　二欄　四格，王先謙說「蘭」當為「闌」，誤加艸。按各本都誤。","sentenceOrder":15},
  {"id":"s_work_han_thu_20_16","chapterId":"ch_work_han_thu_20","textTraditional":"六九一頁　一欄　四格，王先謙說「禺」當為「禹」。按景祐、殿、局本都作「禹」。","sentenceOrder":16},
  {"id":"s_work_han_thu_20_17","chapterId":"ch_work_han_thu_20","textTraditional":"六九一頁　二欄　四格原在五格，據殿本移上。","sentenceOrder":17},
  {"id":"s_work_han_thu_20_18","chapterId":"ch_work_han_thu_20","textTraditional":"六九一頁　三欄　六格，蘇輿說「十」字衍，是。","sentenceOrder":18},
  {"id":"s_work_han_thu_20_19","chapterId":"ch_work_han_thu_20","textTraditional":"六九二頁　二欄　一格，殿本考證說，敞姓楊，非姓陽，各本誤。","sentenceOrder":19},
  {"id":"s_work_han_thu_20_20","chapterId":"ch_work_han_thu_20","textTraditional":"六九二頁　三欄　四格「元侯」，景祐、殿、局本都作「元康」。王先謙說作「元康」是。","sentenceOrder":20},
  {"id":"s_work_han_thu_20_21","chapterId":"ch_work_han_thu_20","textTraditional":"六九五頁　二欄　一格「平」，景祐、殿、局本都作「年」，史表同。","sentenceOrder":21},
  {"id":"s_work_han_thu_20_22","chapterId":"ch_work_han_thu_20","textTraditional":"六九六頁　一欄　三格，朱一新說「二年」當作「三年」。　按景祐、殿本都作「三年」。","sentenceOrder":22},
  {"id":"s_work_han_thu_20_23","chapterId":"ch_work_han_thu_20","textTraditional":"六九七頁　三欄　四格，王念孫說景祐本無「十」字是。","sentenceOrder":23},
  {"id":"s_work_han_thu_20_24","chapterId":"ch_work_han_thu_20","textTraditional":"六九九頁　三欄　一格「魯」，景祐、殿、局本都作「曾」，史表同。王先謙說此形近致誤。","sentenceOrder":24},
  {"id":"s_work_han_thu_20_25","chapterId":"ch_work_han_thu_20","textTraditional":"七０一頁　二欄　四格「侯」字、五格「封」字，都據殿本補。","sentenceOrder":25},
  {"id":"s_work_han_thu_20_26","chapterId":"ch_work_han_thu_20","textTraditional":"七０二頁　三欄　四格，蘇輿說「四」字衍，是。","sentenceOrder":26},
  {"id":"s_work_han_thu_20_27","chapterId":"ch_work_han_thu_20","textTraditional":"七０七頁　四欄　七格「穰」字據景祐、殿本補。","sentenceOrder":27},
  {"id":"s_work_han_thu_20_28","chapterId":"ch_work_han_thu_20","textTraditional":"七一０頁　四欄　三格，王先謙說「莽」下脫「所」字。　按殿、局本都有。","sentenceOrder":28},
  {"id":"s_work_han_thu_20_29","chapterId":"ch_work_han_thu_20","textTraditional":"七一二頁　二欄　三格，錢大昭說「建元」當作「建平」。　按景祐、殿本都作「建平」。","sentenceOrder":29},
  {"id":"s_work_han_thu_20_30","chapterId":"ch_work_han_thu_20","textTraditional":"七一五頁　四欄　二格，王先謙說「魯」是「曾」之誤。","sentenceOrder":30},
  {"id":"s_work_han_thu_20_31","chapterId":"ch_work_han_thu_20","textTraditional":"七一六頁　二欄　二格，王先謙說「長安」誤，當作「長樂」。","sentenceOrder":31},
  {"id":"s_work_han_thu_20_32","chapterId":"ch_work_han_thu_20","textTraditional":"七一八頁　四欄　二格，錢大昭說威下脫「侯」字，閩本有。　按景祐、殿、局本都有。","sentenceOrder":32},
  {"id":"s_work_han_thu_21_1","chapterId":"ch_work_han_thu_21","textTraditional":"師古曰：「漢制，三公號稱萬石，其俸月各三百五十斛穀。其稱中二千石者月各百八十斛，二千石者百二十斛，比二千石者百斛，千石者九十斛，比千石者八十斛，六百石者七十斛，比六百石者六十斛，四百石者五十斛，比四百石者四十五斛，三百石者四十斛，比三百石者三十七斛，二百石者三十斛，比二百石者二十七斛，一百石者十六斛。」","sentenceOrder":1},
  {"id":"s_work_han_thu_21_2","chapterId":"ch_work_han_thu_21","textTraditional":"易敘宓羲、神農、（皇）〔黃〕帝作教化民，〔一〕而傳述其官，〔二〕以為宓羲龍師名官，〔三〕神農火師火名，〔四〕黃帝雲師雲名，〔五〕少昊鳥師鳥名。〔六〕自顓頊以來，為民師而命以民事，〔七〕有重黎、句芒、祝融、后土、蓐收、玄冥之官，然已上矣。〔八〕書載唐虞之際，命羲和四子〔九〕順天文，授民時；咨四岳，以舉賢材，揚側陃；〔一０〕十有二牧，柔遠能邇；〔一一〕禹作司空，平水土；〔一二〕棄作后稷，播百穀；〔一三〕卨作司徒，敷五教；〔一四〕咎繇作士，正五刑；〔一五〕垂作共工，利器用；〔一六〕〈古益字〉作朕虞，育草木鳥獸；〔一七〕伯夷作秩宗，典三禮；〔一八〕夔典樂，和神人；〔一九〕龍作納言，出入帝命。〔二０〕夏、殷亡聞焉，〔二一〕周官則備矣。〔二二〕天官冢宰，地官司徒，春官宗伯，夏官司馬，秋官司寇，各官司空，是為六卿，〔二三〕各有徒屬職分，用於百事。〔二四〕太師、太傅、太保，是為三公，〔二五〕蓋參天子，坐而議政，無不總統，故不以一職為官名。又立三少為之副，少師、少傅、少保，是為孤卿，與六卿為九焉。記曰三公無官，言有其人然後充之，〔二六〕舜之於堯，伊尹於湯，周公、召公於周，是也。或說司馬主天，司徒主人，司空主土，是為三公。四岳謂四方諸侯。自周衰，官失而百職亂，戰國並爭，各變異。秦兼天下，建皇帝之號，〔二七〕立百官之職。漢因循而不革，〔二八〕明簡易，隨時宜也。其後頗有所改。王莽篡位，慕從古官，而吏民弗安，亦多虐政，遂以亂亡。故略表舉大分，〔二九〕以通古今，備溫故知新之義云。〔三０〕","sentenceOrder":2},
  {"id":"s_work_han_thu_21_3","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　應劭曰：「宓羲氏始作八卦，神農氏為耒耜，黃帝氏作衣裳，神而化之，使民宜之。」師古曰；「見易下繫。宓音伏，字本作虙，轉寫訛謬耳。」","sentenceOrder":3},
  {"id":"s_work_han_thu_21_4","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　師古曰：「春秋左氏傳載郯子所說也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_21_5","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　應劭曰；「師者長也，以龍紀其官長，故為龍師。春官為青龍，夏官為赤龍，秋官為白龍，冬官為黑龍，中官為黃龍。」張晏曰：「庖羲將興，神龍負圖而至，因以名師與官也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_21_6","chapterId":"ch_work_han_thu_21","textTraditional":"〔四〕　應劭曰：「火德也，故為炎帝。春官為大火，夏官為鶉火，秋官為西火，各官為北火，中官為中火。」張晏曰：「神農有火星之瑞，因以名師與官也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_21_7","chapterId":"ch_work_han_thu_21","textTraditional":"〔五〕　應劭曰：「黃帝受命有雲瑞，故以雲紀事也。由是而言，故春官為青雲，夏官為縉雲，秋官為白雲，冬官為黑雲，中官為黃雲。」張晏曰：「黃帝有景雲之應，因以名師與官也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_21_8","chapterId":"ch_work_han_thu_21","textTraditional":"〔六〕　應劭曰：「金天氏，黃帝子青陽也。」張晏曰：「少昊之立，鳳鳥適至，因以名官。鳳鳥氏為歷正，玄鳥司分，伯趙司至，青鳥司開，丹鳥司閉。」師古曰：「玄鳥，燕也。伯趙，伯勞也。青鳥，鶬鴳也。丹鳥，鷩雉也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_21_9","chapterId":"ch_work_han_thu_21","textTraditional":"〔七〕　應劭曰：「顓頊氏代少昊者也，不能紀遠，始以職事命官也。春官為木正，夏官為火正，秋官為金正，冬官為水正，中官為土正。」師古曰：「自此以上皆郯子之辭也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_21_10","chapterId":"ch_work_han_thu_21","textTraditional":"〔八〕　應劭曰：「少昊有四叔，重為句芒，胲為蓐收，修及熙為玄冥。顓頊氏有子曰黎，為祝融。共工氏有子曰句龍，為后土。故有五行之官，皆封為上公，祀為貴神。」師古曰：「上謂其事久遠也。胲音該。」","sentenceOrder":10},
  {"id":"s_work_han_thu_21_11","chapterId":"ch_work_han_thu_21","textTraditional":"〔九〕　應劭曰：「堯命四子分掌四時之教化也。」張晏曰：「四子謂羲仲、羲叔、和仲、和叔也。」師古曰：「事見虞書堯典。」","sentenceOrder":11},
  {"id":"s_work_han_thu_21_12","chapterId":"ch_work_han_thu_21","textTraditional":"〔一０〕師古曰：「四嶽，分主四方諸侯者。」","sentenceOrder":12},
  {"id":"s_work_han_thu_21_13","chapterId":"ch_work_han_thu_21","textTraditional":"〔一一〕應劭曰：「牧，州牧也。」師古曰：「柔，安也，能，善也。邇，近也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_21_14","chapterId":"ch_work_han_thu_21","textTraditional":"〔一二〕師古曰：「空，穴也。古人穴居，主穿土為穴以居人也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_21_15","chapterId":"ch_work_han_thu_21","textTraditional":"〔一三〕應劭曰：「棄，臣名也。后，主也，為此稷官之主也。」師古曰：「播謂布種也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_21_16","chapterId":"ch_work_han_thu_21","textTraditional":"〔一四〕應劭曰：「五教，父義，母慈，兄友，弟恭，子孝也。」師古曰；「卨音先列反。」","sentenceOrder":16},
  {"id":"s_work_han_thu_21_17","chapterId":"ch_work_han_thu_21","textTraditional":"〔一五〕應劭曰：「土，獄官之長。」張晏曰：「五刑謂墨、刖、劓、剕、宮、大辟也。」師古曰：「咎音皋。繇音弋昭反。墨，鑿其頟而涅以墨也。刖，斷足也。劓，割鼻也。剕，去髕骨也。宮，陰刑也。大辟，殺之也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_21_18","chapterId":"ch_work_han_thu_21","textTraditional":"〔一六〕應劭曰：「垂，臣名也。為共工，理百工之事也。」師古曰：「共讀曰龔。」","sentenceOrder":18},
  {"id":"s_work_han_thu_21_19","chapterId":"ch_work_han_thu_21","textTraditional":"〔一七〕應劭曰：「〈古益字〉，伯益也。虞，掌山澤禽獸官名也。」師古曰：「〈古益字〉，古益字也。虞，度也，主商度山川之事。」","sentenceOrder":19},
  {"id":"s_work_han_thu_21_20","chapterId":"ch_work_han_thu_21","textTraditional":"〔一八〕應劭曰：「伯夷，臣名也。典天神、地祇、人鬼之禮也。」師古曰：「秩，次也；宗，尊也：主尊神之禮，可以次序也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_21_21","chapterId":"ch_work_han_thu_21","textTraditional":"〔一九〕應劭曰：「夔，臣名也。」師古曰：「夔音鉅龜反。」","sentenceOrder":21},
  {"id":"s_work_han_thu_21_22","chapterId":"ch_work_han_thu_21","textTraditional":"〔二０〕應劭曰：「龍，臣名也。納言，如今尚書，管王之喉舌也。」師古曰：「自此以上皆堯典之文。」","sentenceOrder":22},
  {"id":"s_work_han_thu_21_23","chapterId":"ch_work_han_thu_21","textTraditional":"〔二一〕師古曰：「言夏、殷置官事不見於書傳也。禮記明堂位曰『夏后氏官百，殷二百』，蓋言其大數而無職號統屬也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_21_24","chapterId":"ch_work_han_thu_21","textTraditional":"〔二二〕師古曰：「事見周書周官篇及周禮也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_21_25","chapterId":"ch_work_han_thu_21","textTraditional":"〔二三〕師古曰：「冢宰掌邦治，司徒掌邦教，宗伯掌邦禮，司馬掌邦政，司寇掌邦禁，司空掌邦土也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_21_26","chapterId":"ch_work_han_thu_21","textTraditional":"〔二四〕師古曰：「言百者，舉大數也。分音扶問反。」","sentenceOrder":26},
  {"id":"s_work_han_thu_21_27","chapterId":"ch_work_han_thu_21","textTraditional":"〔二五〕應劭曰：「師，訓也。傅，覆也。保，養也。」師古曰：「傅，相也」","sentenceOrder":27},
  {"id":"s_work_han_thu_21_28","chapterId":"ch_work_han_thu_21","textTraditional":"〔二六〕師古曰：「不必備員，有德者乃處之。」","sentenceOrder":28},
  {"id":"s_work_han_thu_21_29","chapterId":"ch_work_han_thu_21","textTraditional":"〔二七〕張晏曰：「五帝自以德不及三皇，故自去其皇號。三王又以德不及五帝，自損稱王。秦自以德褒二行，故兼稱之。」","sentenceOrder":29},
  {"id":"s_work_han_thu_21_30","chapterId":"ch_work_han_thu_21","textTraditional":"〔二八〕師古曰：「革，改也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_21_31","chapterId":"ch_work_han_thu_21","textTraditional":"〔二九〕師古曰：「分音扶問反。」","sentenceOrder":31},
  {"id":"s_work_han_thu_21_32","chapterId":"ch_work_han_thu_21","textTraditional":"〔三０〕師古曰：「論語稱孔子曰『溫故而知新，可以為師矣』。溫猶厚也，言厚蓄故事，多識於新，則可為師。」","sentenceOrder":32},
  {"id":"s_work_han_thu_21_33","chapterId":"ch_work_han_thu_21","textTraditional":"相國、丞相，〔一〕皆秦官，金印紫綬，掌丞天子助理萬機。秦有左右，〔二〕高帝即位，置一丞相，十一年更名相國，綠綬。孝惠、高后置左右丞相，文帝二年復置一丞相。有兩長史，秩千石。哀帝元壽二年更名大司徒。武帝元狩五年初置司直，秩比二千石，掌佐丞相舉不法。","sentenceOrder":33},
  {"id":"s_work_han_thu_21_34","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　應劭曰：「丞者，承也。相者，助也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_21_35","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　荀悅曰：「秦本次國，命卿二人，是以置左右丞相，無三公官。」","sentenceOrder":35},
  {"id":"s_work_han_thu_21_36","chapterId":"ch_work_han_thu_21","textTraditional":"太尉，秦官，〔一〕金印紫綬，掌武事。武帝建元二年省。元狩四年初置大司馬，〔二〕以冠將軍之號。〔三〕宣帝地節三年置大司馬，不冠將軍，亦無印綬官屬。成帝綏和元年賜大司馬金印紫綬，置官屬，祿比丞相，去將軍。哀帝建平二年復去大司馬印綬、官屬，冠將軍如故。元壽二年復賜大司馬印綬，置官屬，去將軍，位在司徒上。有長史，秩千石。","sentenceOrder":36},
  {"id":"s_work_han_thu_21_37","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　應劭曰：「自上安下曰尉，武官悉以為稱。」","sentenceOrder":37},
  {"id":"s_work_han_thu_21_38","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　應劭曰：「司馬，主武也，諸武官亦以為號。」","sentenceOrder":38},
  {"id":"s_work_han_thu_21_39","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　師古曰：「冠者，加於其上共為一官也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_21_40","chapterId":"ch_work_han_thu_21","textTraditional":"御史大夫，秦官，〔一〕位上卿，銀印青綬，掌副丞相。有兩丞，秩千石。一曰中丞，在殿中蘭臺，掌圖籍祕書，外督部刺史，內領侍御史員十五人，受公卿奏事，舉劾按章。成帝綏和元年更名大司空，金印紫綬，祿比丞相，置長史如中丞，官職如故。哀帝建平二年復為御史大夫，元壽二年復為大司空，御史中丞更名御史長史。侍御史有繡衣直指，〔二〕出討姦猾，治大獄，武帝所制，不常置。","sentenceOrder":40},
  {"id":"s_work_han_thu_21_41","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　應劭曰：「侍御史之率，故稱大夫云。」臣瓚曰：「茂陵書御史大夫秩中二千石。」","sentenceOrder":41},
  {"id":"s_work_han_thu_21_42","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　服虔曰：「指事而行，無阿私也。」師古曰：「衣以繡者，尊寵之也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_21_43","chapterId":"ch_work_han_thu_21","textTraditional":"太傅，古官，高后元年初置，金印紫綬。後省，八年復置。後省，哀帝元壽二年復置。位在三公上。","sentenceOrder":43},
  {"id":"s_work_han_thu_21_44","chapterId":"ch_work_han_thu_21","textTraditional":"太師、太保，皆古官，平帝元始元年皆初置，金印紫綬。太師位在太傅上，太保次太傅。","sentenceOrder":44},
  {"id":"s_work_han_thu_21_45","chapterId":"ch_work_han_thu_21","textTraditional":"前後左右將軍，皆周末官，秦因之，位上卿，金印紫綬。漢不常置，或有前後，或有左右，皆掌兵及四夷。有長史，秩千石。","sentenceOrder":45},
  {"id":"s_work_han_thu_21_46","chapterId":"ch_work_han_thu_21","textTraditional":"奉常，秦官，掌宗廟禮儀，有丞。景帝中六年更名太常。〔一〕屬官有太樂、太祝、太宰、太史、太卜、太醫六令丞，又均官、都水兩長丞，〔二〕又諸廟寢園食官令長丞，有廱太宰、太祝令丞，〔三〕五畤各一尉。又博士及諸陵縣皆屬焉。景帝中六年更名太祝為祠祀，武帝太初元年更曰廟祀，初置太卜。博士，秦官，掌通古今，秩比六百石，員多至數十人。武帝建元五年初置五經博士，宣帝黃龍元年稍增員十二人。元帝永光元年分諸陵邑屬三輔。王莽改太常曰秩宗。","sentenceOrder":46},
  {"id":"s_work_han_thu_21_47","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　應劭曰：「常，典也，掌典三禮也。」師古曰：「太常，王者旌旗也，畫日月焉，王有大事則建以行，禮官主奉持之，故曰奉常也。後改曰太常，尊大之（儀）〔義〕也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_21_48","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　服虔曰：「均官，主山陵上槁輸入之官也。」如淳曰：「律，都水治渠隄水門。三輔黃圖云三輔皆有都水也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_21_49","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　文穎曰：「廱，主熟食官。」如淳曰：「五畤在廱，故特置太宰以下諸官。」師古曰：「如說是也。雍，右扶風之縣也。太宰即是具食之官，不當復置饔人也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_21_50","chapterId":"ch_work_han_thu_21","textTraditional":"郎中令，秦官，〔一〕掌宮殿掖門戶，有丞。武帝太初元年更名光祿勳。〔二〕屬官有大夫、郎、謁者，皆秦官。又期門、羽林皆屬焉。〔三〕大夫掌論議，有太中大夫、中大夫、諫大夫，皆無員，多至數十人。武帝元狩五年初置諫大夫，秩比八百石，太初元年更名中大夫為光祿大夫，秩比二千石，太中大夫秩比千石如故。郎掌守門戶，出充車騎，有議郎、中郎、侍郎、郎中，皆無員，多至千人。議郎、中郎秩比六百石，侍郎比四百石，郎中比三百石。中郎有五官、左、右三將，秩皆比二千石。郎中有車、戶、騎三將，〔四〕秩皆比千石。謁者掌賓讚受事，員七十人，秩比六百石，有僕射，〔五〕秩比千石。期門掌執兵送從，武帝建元三年初置，比郎，無員，多至千人，有僕射，秩比千石。平帝元始元年更名虎賁郎，〔六〕置中郎將，秩比二千石。羽林掌送從，次期門，武帝太初元年初置，名曰建章營騎，後更名羽林騎。又取從軍死事之子孫養羽林，官教以五兵，號曰羽林孤兒。〔七〕羽林有令丞。宣帝令中郎將、騎都尉監羽林，秩比二千石。僕射，秦官，自侍中、尚書、博士、郎皆有。古者重武官，有主射以督課之，軍屯吏、騶、宰、永巷宮人皆有，取其領事之號。〔八〕","sentenceOrder":50},
  {"id":"s_work_han_thu_21_51","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　臣瓚曰：「主郎內諸官，故曰郎中令。」","sentenceOrder":51},
  {"id":"s_work_han_thu_21_52","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　應劭曰：「光者，明也。祿者，爵也。勳，功也。」如淳曰：「胡公曰勳之言閽也。閽者，古主門官也。光祿主宮門。」師古曰：「應說是也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_21_53","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　服虔曰：「與期門下以微行，後遂以名官。」師古曰：「羽林，亦宿衛之官，言其如羽之疾，如林之多也。一說羽所以為王者羽翼也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_21_54","chapterId":"ch_work_han_thu_21","textTraditional":"〔四〕　如淳曰：「主車曰車郎，主戶衛曰戶郎。漢儀注郎中令主郎中，左右車將主左右車郎，左右戶將主左右戶郎也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_21_55","chapterId":"ch_work_han_thu_21","textTraditional":"〔五〕　應劭曰：「謁，請也，白也。僕，主也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_21_56","chapterId":"ch_work_han_thu_21","textTraditional":"〔六〕　師古曰：「賁讀與奔同，言如猛獸之奔。」","sentenceOrder":56},
  {"id":"s_work_han_thu_21_57","chapterId":"ch_work_han_thu_21","textTraditional":"〔七〕　師古曰：「五兵謂弓矢、殳、矛、戈、戟也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_21_58","chapterId":"ch_work_han_thu_21","textTraditional":"〔八〕　孟康曰：「皆有僕射，隨所領之事以為號也。若軍屯吏則曰軍屯僕射，永巷則曰永巷僕射。」","sentenceOrder":58},
  {"id":"s_work_han_thu_21_59","chapterId":"ch_work_han_thu_21","textTraditional":"衛尉，秦官，掌宮門衛屯兵，〔一〕有丞。景帝初更名中大夫令，後元年復為衛尉。屬官有公車司馬、衛士、旅賁三令丞。〔二〕衛士三丞。又諸屯衛候、司馬二十二官皆屬焉。長樂、建章、甘泉衛尉皆掌其宮，〔三〕職略同，不常置。","sentenceOrder":59},
  {"id":"s_work_han_thu_21_60","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　師古曰：「漢舊儀云衛尉寺在宮內。胡廣云主宮闕之門內衛士，於周垣下為區廬。區廬者，若今之仗宿屋矣。」","sentenceOrder":60},
  {"id":"s_work_han_thu_21_61","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　師古曰：「漢官儀云公車司馬掌殿司馬門，夜徼宮中，天下上事及闕下凡所徵召皆總領之，令秩六百石。旅，眾也。賁與奔同，言為奔走之任也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_21_62","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　師古曰：「各隨所掌之宮以名官。」","sentenceOrder":62},
  {"id":"s_work_han_thu_21_63","chapterId":"ch_work_han_thu_21","textTraditional":"太僕，秦官，〔一〕掌輿馬，有兩丞。屬官有大廄、未央、家馬三令，各五丞一尉。〔二〕又車府、路軨、騎馬、駿馬四令丞；〔三〕又龍馬、閑駒、橐泉、騊駼、承華五監長丞；〔四〕又邊郡六牧師菀令，各三丞；〔五〕又牧橐、昆蹄令丞〔六〕皆屬焉。中太僕掌皇太后輿馬，不常置也。武帝太初元年更名家馬為挏馬，〔七〕初置路軨。","sentenceOrder":63},
  {"id":"s_work_han_thu_21_64","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　應劭曰：「周穆王所置也，蓋大御眾僕之長，中大夫也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_21_65","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　師古曰：「家馬者，主供天子私用，非大祀戎事軍國所須，故謂之家馬也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_21_66","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　伏儼曰：「主乘輿路車，又主凡小車。軨，今之小馬車曲輿也。」師古曰：「軨音零。」","sentenceOrder":66},
  {"id":"s_work_han_thu_21_67","chapterId":"ch_work_han_thu_21","textTraditional":"〔四〕　如淳曰：「橐泉廄在橐泉宮下。騊駼，野馬也。」師古曰：「閑，闌，養馬之所也，故曰閑駒。騊駼出北海中，其狀如馬，非野馬也。騊音徒高反。駼音塗。」","sentenceOrder":67},
  {"id":"s_work_han_thu_21_68","chapterId":"ch_work_han_thu_21","textTraditional":"〔五〕　師古曰：「漢官儀云牧師諸菀三十六所，分置北邊、西邊，分養馬三十萬頭。」","sentenceOrder":68},
  {"id":"s_work_han_thu_21_69","chapterId":"ch_work_han_thu_21","textTraditional":"〔六〕　應劭曰：「橐，橐佗。昆蹄，好馬名也。蹄音啼。」如淳曰：「爾雅曰『昆蹄研，善升甗』者也，因以為廄名。」師古曰：「牧橐，言牧養橐佗也。昆，獸名也。蹄研者，謂其蹄下平也。善升甗者，謂山形如甑，而能升之也。蹄即古蹄字耳。研音五見反。甗音言，又音牛偃反。」","sentenceOrder":69},
  {"id":"s_work_han_thu_21_70","chapterId":"ch_work_han_thu_21","textTraditional":"〔七〕　應劭曰：「主乳馬，取其汁挏治之，味酢可飲，因以名官也。」如淳曰：「主乳馬，以韋革為夾兜，受數斗，盛馬乳，挏取其上（把）〔肥〕，因名曰挏馬。禮樂志丞相孔光奏省樂官七十二人，給大官挏馬酒。今梁州亦名馬酪為馬酒。」晉灼曰：「挏音挺挏之挏。」師古曰：「晉音是也。挏音徒孔反。」","sentenceOrder":70},
  {"id":"s_work_han_thu_21_71","chapterId":"ch_work_han_thu_21","textTraditional":"廷尉，秦官，〔一〕掌刑辟，有正、左右監，秩皆千石。景帝中六年更名大理，武帝建元四年復為廷尉。宣帝地節三年初置左右平，秩皆六百石。哀帝元壽二年復為大理。王莽改曰作士。","sentenceOrder":71},
  {"id":"s_work_han_thu_21_72","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　應劭曰：「聽獄必質諸朝廷，與眾共之，兵獄同制，故稱廷尉。」師古曰：「廷，平也。治獄貴平，故以為號。」","sentenceOrder":72},
  {"id":"s_work_han_thu_21_73","chapterId":"ch_work_han_thu_21","textTraditional":"典客，秦官，掌諸歸義蠻夷，有丞。景帝中六年更名大行令，武帝太初元年更名大鴻臚。〔一〕屬官有行人、譯官、別火三令丞〔二〕及郡邸長丞。〔三〕武帝太初元年更名行人為大行令，初置別火。王莽改大鴻臚曰典樂。初，置郡國邸屬少府，中屬中尉，後屬大鴻臚。","sentenceOrder":73},
  {"id":"s_work_han_thu_21_74","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　應劭曰：「郊廟行禮讚九賓，鴻聲臚傳之也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_21_75","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　如淳曰：「漢儀注別火，獄令官，主治改火之事。」","sentenceOrder":75},
  {"id":"s_work_han_thu_21_76","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　師古曰：「主諸郡之邸在京師者也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_21_77","chapterId":"ch_work_han_thu_21","textTraditional":"宗正，秦官，〔一〕掌親屬，有丞。平帝元始四年更名宗伯。屬官有都司空令丞，〔二〕內官長丞。〔三〕又諸公主家令、門尉皆屬焉。王莽并其官於秩宗。初，內官屬少府，中屬主爵，後屬宗正。","sentenceOrder":77},
  {"id":"s_work_han_thu_21_78","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　應劭曰：「周成王之時彤伯入為宗正也。」師古曰：「彤伯為宗伯，不謂之宗正。」","sentenceOrder":78},
  {"id":"s_work_han_thu_21_79","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　如淳曰：「律，司空主水及罪人。賈誼曰『輸之司空，編之徒官』。」","sentenceOrder":79},
  {"id":"s_work_han_thu_21_80","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　師古曰：「律曆志主分寸尺丈也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_21_81","chapterId":"ch_work_han_thu_21","textTraditional":"治粟內史，秦官，掌穀貨，有兩丞。景帝後元年更名大農令，武帝太初元年更名大司農。屬官有太倉、均輸、平準、都內、籍田五令丞，〔一〕斡官、鐵市兩長丞。〔二〕又郡國諸倉農監、都水六十五官長丞皆屬焉。騪粟都尉，〔三〕武帝軍官，不常置。王莽改大司農曰羲和，後更為納言。初，斡官屬少府，中屬主爵，後屬大司農。","sentenceOrder":81},
  {"id":"s_work_han_thu_21_82","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　孟康曰：「均輸，謂諸當所有輸於官者，皆令輸其地土所饒，平其所在時賈，官更於佗處賣之，輸者既便，而官有利也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_21_83","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　如淳曰：「斡音筦，或作幹。斡，主也，主均輸之事，所謂斡鹽鐵而榷酒酤也。」晉灼曰：「此竹箭幹之官長也。均輸自有令。」師古曰：「如說近是也。縱作幹讀，當以幹持財貨之事耳，非謂箭幹也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_21_84","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　服虔曰：「騪音搜狩之搜。搜，索也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_21_85","chapterId":"ch_work_han_thu_21","textTraditional":"少府，秦官，掌山海池澤之稅，以給共養，〔一〕有六丞。屬官有尚書、符節、太醫、太官、湯官、導官、樂府、若盧、考工室、左弋、居室、甘泉居室、左右司空、東織、西織、東園匠十（二）〔六〕官令丞，〔二〕又胞人、都水、均官三長丞，〔三〕又上林中十池監，〔四〕又中書謁者、黃門、鉤盾、尚方、御府、永巷、內者、宦者（七）〔八〕官令丞。〔五〕諸僕射、署長、中黃門皆屬焉。〔六〕武帝太初元年更名考工室為考工，左弋為佽飛，居室為保宮，甘泉居室為昆臺，永巷為掖廷。佽飛掌弋射，有九丞兩尉，太官七丞，昆臺五丞，樂府三丞，掖廷八丞，宦者七丞，鉤盾五丞兩尉。成帝建始四年更名中書謁者令為中謁者令，初置尚書，員五人，有四丞。河平元年省東織，更名西織為織室。綏和二年，哀帝省樂府。王莽改少府曰共工。","sentenceOrder":85},
  {"id":"s_work_han_thu_21_86","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　應劭曰：「名曰禁錢，以給私養，自別為藏。少者，小也，故稱少府。」師古曰：「大司農供軍國之用，少府以養天子也。（供）〔共〕音居用反。養音弋亮反。」","sentenceOrder":86},
  {"id":"s_work_han_thu_21_87","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　服虔曰：「若盧，詔獄也。」鄧展曰：「舊洛陽兩獄，一名若盧，主受親戚婦女。」如淳曰：「若盧，官名也，藏兵器。品令曰若盧郎中二十人，主弩射。漢儀注有若盧獄令，主治庫兵將相大臣。」臣瓚曰：「冬官為考工，主作器械也。」師古曰：「太官主膳食，湯官主餅餌，導官主擇米。若盧，如說是也。左弋，地名。東園匠，主作陵內器物者也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_21_88","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　師古曰：「胞人，主掌宰割者也。胞與庖同。」","sentenceOrder":88},
  {"id":"s_work_han_thu_21_89","chapterId":"ch_work_han_thu_21","textTraditional":"〔四〕　師古曰：「三輔黃圖云上林中池上籞五所，而此云十池監，未詳其數。」","sentenceOrder":89},
  {"id":"s_work_han_thu_21_90","chapterId":"ch_work_han_thu_21","textTraditional":"〔五〕　師古曰：「鉤盾主近苑囿，尚方主作禁器物，御府主天子衣服也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_21_91","chapterId":"ch_work_han_thu_21","textTraditional":"〔六〕　師古曰：「中黃門，奄人居禁中在黃門之內給事者也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_21_92","chapterId":"ch_work_han_thu_21","textTraditional":"中尉，秦官，掌徼循京師，〔一〕有兩丞、候、司馬、千人〔二〕。武帝太初元年更名執金吾。〔三〕屬官有中壘、寺互、武庫、都船四令丞。〔四〕都船、武庫有三丞，中壘兩尉。又式道左右中候、候丞及左右京輔都尉、尉丞兵卒皆屬焉。〔五〕初，寺互屬少府，中屬主爵，後屬中尉。","sentenceOrder":92},
  {"id":"s_work_han_thu_21_93","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　如淳曰：「所謂遊徼，徼循禁備盜賊也。」師古曰：「徼謂遮繞也。徼音工釣反。」","sentenceOrder":93},
  {"id":"s_work_han_thu_21_94","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　師古曰：「候及司馬及千人皆官名也。屬國都尉云有丞、候、千人。西域都護云司馬、候、千人各二人。凡此千人，皆官名也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_21_95","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　應劭曰：「吾者，禦也，掌執金革以禦非常。」師古曰：「金吾，鳥名也，主辟不祥。天子出行，職主先導，以禦非常，故執此鳥之象，因以名官。」","sentenceOrder":95},
  {"id":"s_work_han_thu_21_96","chapterId":"ch_work_han_thu_21","textTraditional":"〔四〕　如淳曰：「漢儀注有寺互。都船獄令，治水官也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_21_97","chapterId":"ch_work_han_thu_21","textTraditional":"〔五〕　應劭曰：「式道凡三候，車駕出還，式道候持麾至宮門，門乃開。」師古曰：「式，表也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_21_98","chapterId":"ch_work_han_thu_21","textTraditional":"自太常至執金吾，秩皆中二千石，丞皆千石。","sentenceOrder":98},
  {"id":"s_work_han_thu_21_99","chapterId":"ch_work_han_thu_21","textTraditional":"太子太傅、少傅，古官。屬官有太子門大夫、〔一〕庶子、〔二〕先馬、〔三〕舍人。","sentenceOrder":99},
  {"id":"s_work_han_thu_21_100","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　應劭曰：「員五人，秩六百石。」","sentenceOrder":100},
  {"id":"s_work_han_thu_21_101","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　應劭曰：「員五人，秩六百石。」","sentenceOrder":101},
  {"id":"s_work_han_thu_21_102","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　張晏曰：「先馬，員十六人，秩比謁者。」如淳曰：「前驅也。國語曰句踐親為夫差先馬。先或作洗也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_21_103","chapterId":"ch_work_han_thu_21","textTraditional":"將作少府，秦官，掌治宮室，有兩丞、左右中候。景帝中六年更名將作大匠。屬官有石庫、東園主章、左右前後中校七令丞，〔一〕又主章長丞。〔二〕武帝太初元年更名東園主章為木工。成帝陽朔三年省中候及左右前後中校五丞。","sentenceOrder":103},
  {"id":"s_work_han_thu_21_104","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　如淳曰：「章謂大材也。舊將作大匠主材吏名章曹掾。」師古曰：「今所謂木鍾者，蓋章聲之轉耳。東園主章掌大材，以供東園大匠也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_21_105","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　師古曰：「掌凡大木也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_21_106","chapterId":"ch_work_han_thu_21","textTraditional":"詹事，秦官，〔一〕掌皇后、太子家，有丞。〔二〕屬官有太子率更、家令丞，僕、中盾、衛率、廚廄長丞，〔三〕又中長秋、私府、永巷、倉、廄、祠祀、食官令長丞。諸宦官皆屬焉。〔四〕成帝鴻嘉三年省詹事官，并屬大長秋。〔五〕長信詹事掌皇太后宮，景帝中六年更名長信少府，〔六〕平帝元始四年更名長樂少府。","sentenceOrder":106},
  {"id":"s_work_han_thu_21_107","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　應劭曰：「詹，省也，給也。」臣瓚曰：「茂陵書詹事秩真二千石。」","sentenceOrder":107},
  {"id":"s_work_han_thu_21_108","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　師古曰：「皇后、太子各置詹事，隨其所在以名官。」","sentenceOrder":108},
  {"id":"s_work_han_thu_21_109","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　張晏曰：「太子稱家，故曰家令。」臣瓚曰：「茂陵中書太子家令秩八百石。」應劭曰：「中盾主周衛徼道，秩四百石。」如淳曰：「漢儀注衛率主門衛，秩千石。」師古曰：「掌知漏刻，故曰率更。自此以上，太子之官也。更音工衡反。」","sentenceOrder":109},
  {"id":"s_work_han_thu_21_110","chapterId":"ch_work_han_thu_21","textTraditional":"〔四〕　師古曰：「自此以上，皆皇后之官。」","sentenceOrder":110},
  {"id":"s_work_han_thu_21_111","chapterId":"ch_work_han_thu_21","textTraditional":"〔五〕　師古曰：「省皇后詹事，總屬長秋也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_21_112","chapterId":"ch_work_han_thu_21","textTraditional":"〔六〕　張晏曰：「以太后所居宮為名也。居長信宮則曰長信少府，居長樂宮則曰長樂少府也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_21_113","chapterId":"ch_work_han_thu_21","textTraditional":"將行，秦官，〔一〕景帝中六年更名大長秋，〔二〕或用中人，或用士人。〔三〕","sentenceOrder":113},
  {"id":"s_work_han_thu_21_114","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　應劭曰：「皇后卿也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_21_115","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　師古曰：「秋者收成之時，長者恆久之義，故以為皇后官名。」","sentenceOrder":115},
  {"id":"s_work_han_thu_21_116","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　師古曰：「中人，奄人也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_21_117","chapterId":"ch_work_han_thu_21","textTraditional":"典屬國，秦官，掌蠻夷降者。武帝元狩三年昆邪王降，〔一〕復增屬國，置都尉、丞、候、千人。屬官，九譯令。成帝河平元年省并大鴻臚。","sentenceOrder":117},
  {"id":"s_work_han_thu_21_118","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　師古曰：「昆音下門反。」","sentenceOrder":118},
  {"id":"s_work_han_thu_21_119","chapterId":"ch_work_han_thu_21","textTraditional":"水衡都尉，〔一〕武帝元鼎二年初置，掌上林苑，有五丞。屬官有上林、均輸、御羞、禁圃、輯濯、鍾官、技巧、六廄、辯銅九官令丞。〔二〕又衡官、水司空、都水、農倉，又甘泉上林、都水七官長丞皆屬焉。上林有八丞十二尉，均輸四丞，御羞兩丞，都水三丞，禁圃兩尉，甘泉上林四丞。成帝建始二年省技巧、六廄官。王莽改水衡都尉曰予虞。初，御羞、上林、衡官及鑄錢皆屬少府。","sentenceOrder":119},
  {"id":"s_work_han_thu_21_120","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　應劭曰：「古山林之官曰衡。掌諸池苑，故稱水衡。」張晏曰：「主都水及上林苑，故曰水衡。主諸官，故曰都。有卒徒武事，故曰尉。」師古曰：「衡，平也，主平其稅入。」","sentenceOrder":120},
  {"id":"s_work_han_thu_21_121","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　如淳曰：「御羞，地名也，在藍田，其土肥沃，多出御物可進者，揚雄傳謂之御宿。三輔黃圖御羞、宜春皆苑名也。輯濯，船官也。鍾官，主鑄錢官也。辯銅，主分別銅之種類也。」師古曰：「御宿，則今長安城南御宿川也，不在藍田。羞、宿聲相近，故或云御羞，或云御宿耳。羞者，珍羞所出；宿者，止宿之義。輯讀與楫同，音集；濯音直孝反：皆所以行船也。漢舊儀云天子六廄，未央、承華、騊駼、騎馬、輅軨、大廄也，馬皆萬匹。據此表，大僕屬官以有大廄、未央、輅軨、騎馬、騊駼、承華，而水衡又云六廄技巧官，是則技巧之徒供六廄者，其官別屬水衡也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_21_122","chapterId":"ch_work_han_thu_21","textTraditional":"內史，周官，秦因之，掌治京師。景帝二年分置左〔右〕內史。〔一〕右內史武帝太初元年更名京兆尹，〔二〕屬官有長安市、廚兩令丞，又都水、鐵官兩長丞。左內史更名左馮翊，〔三〕屬官有廩犧令丞尉。〔四〕又左都水、鐵官、雲壘、長安四市四長丞皆屬焉。","sentenceOrder":122},
  {"id":"s_work_han_thu_21_123","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　師古曰：「地理志云武帝建元六年置左右內史，而此表云景帝二年分置，表志不同。又據史記，知志誤矣。」","sentenceOrder":123},
  {"id":"s_work_han_thu_21_124","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　張晏曰：「地絕高曰京。左傳曰『莫之與京』。十億曰兆。尹，正也。」師古曰：「京，大也。兆者，眾數。言大眾所在，故云京兆也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_21_125","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　張晏曰：「馮，輔也。翊，佐也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_21_126","chapterId":"ch_work_han_thu_21","textTraditional":"〔四〕　師古曰：「廩主藏穀，犧主養牲，皆所以供祭祀也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_21_127","chapterId":"ch_work_han_thu_21","textTraditional":"主爵中尉，秦官，掌列侯。景帝中六年更名都尉，武帝太初元年更名右扶風，〔一〕治內史右地。屬官有掌畜令丞。〔二〕又（有）〔右〕都水、鐵官、廄、廱廚四長丞皆屬焉。〔三〕與左馮翊、京兆尹是為三輔，〔四〕皆有兩丞。列侯更屬大鴻臚。元鼎四年更置（二）〔三〕輔都尉、都尉丞各一人。","sentenceOrder":127},
  {"id":"s_work_han_thu_21_128","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　張晏曰：「扶，助也。風，化也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_21_129","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　如淳曰：「尹翁歸傳曰『豪強有論罪，輸掌畜官，使斫莝』。東方朔曰『益為右扶風』，畜牧之所在也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_21_130","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　如淳曰：「五畤在廱，故有廚。」","sentenceOrder":130},
  {"id":"s_work_han_thu_21_131","chapterId":"ch_work_han_thu_21","textTraditional":"〔四〕　服虔曰：「皆治在長安城中。」師古曰：「三輔黃圖云京兆在尚冠前街東入，故中尉府，馮翊在太上皇廟西入，右扶風在夕陰街北入，故主爵府。長安以東為京兆，長陵以北為左馮翊，渭城以西為右扶風也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_21_132","chapterId":"ch_work_han_thu_21","textTraditional":"自太子太傅至右扶風，皆秩二千石，丞六百石。","sentenceOrder":132},
  {"id":"s_work_han_thu_21_133","chapterId":"ch_work_han_thu_21","textTraditional":"護軍都尉，秦官，武帝元狩四年屬大司馬，成帝綏和元年居大司馬府比司直，哀帝元壽元年更名司寇，平帝元始元年更名護軍。","sentenceOrder":133},
  {"id":"s_work_han_thu_21_134","chapterId":"ch_work_han_thu_21","textTraditional":"司隸校尉，周官，〔一〕武帝征和四年初置。持節，從中都官徒千二百人，〔二〕捕巫蠱，督大姦猾。〔三〕後罷其兵。察三輔、三河、弘農。元帝初元四年去節。成帝元延四年省。綏和二年，哀帝復置，但為司隸，冠進賢冠，屬大司空，比司直。","sentenceOrder":134},
  {"id":"s_work_han_thu_21_135","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　師古曰：「以掌徒隸而巡察，故云司隸。」","sentenceOrder":135},
  {"id":"s_work_han_thu_21_136","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　師古曰：「中都官，京師諸官府也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_21_137","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　師古曰：「督謂察視也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_21_138","chapterId":"ch_work_han_thu_21","textTraditional":"城門校尉掌京師城門屯兵，有司馬、〔一〕十二城門候。〔二〕中壘校尉掌北軍壘門內，外掌西域。〔三〕屯騎校尉掌騎士。步兵校尉掌上林苑門屯兵。越騎校尉掌越騎。〔四〕長水校尉掌長水宣曲胡騎。〔五〕又有胡騎校尉，掌池陽胡騎，不常置。〔六〕射聲校尉掌待詔射聲士。〔七〕虎賁校尉掌輕車。凡八校尉，皆武帝初置，有丞、司馬。〔八〕自司隸至虎賁校尉，秩皆二千石。西域都護加官，宣帝地節二年初置，以騎都尉、諫大夫使護西域三十六國，有副校尉，秩比二千石，丞一人，司馬、候、千人各二人。戊己校尉，元帝初元元年置，〔九〕有丞、司馬各一人，候五人，秩比六百石。","sentenceOrder":138},
  {"id":"s_work_han_thu_21_139","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　師古曰：「八屯各有司馬也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_21_140","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　師古曰：「門各有候，蕭望之署小苑東門候，亦其比也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_21_141","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　師古曰：「掌北軍壘門之內，而又外掌西域。」","sentenceOrder":141},
  {"id":"s_work_han_thu_21_142","chapterId":"ch_work_han_thu_21","textTraditional":"〔四〕　如淳曰：「越人內附，以為騎也。」晉灼曰：「取其材力超越也。」師古曰：「宣紀言佽飛射士、胡越騎，又此有胡騎校尉。如說是。」","sentenceOrder":142},
  {"id":"s_work_han_thu_21_143","chapterId":"ch_work_han_thu_21","textTraditional":"〔五〕　師古曰：「長水，胡名也。宣曲，觀名，胡騎之屯於宣曲者。」","sentenceOrder":143},
  {"id":"s_work_han_thu_21_144","chapterId":"ch_work_han_thu_21","textTraditional":"〔六〕　師古曰：「胡騎之屯池陽者也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_21_145","chapterId":"ch_work_han_thu_21","textTraditional":"〔七〕　服虔曰：「工射者也。冥冥中聞聲則中之，因以名也。」應劭曰：「須詔所命而射，故曰待詔射也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_21_146","chapterId":"ch_work_han_thu_21","textTraditional":"〔八〕　師古曰：「自中壘以下凡八校尉。城門不在此數中。」","sentenceOrder":146},
  {"id":"s_work_han_thu_21_147","chapterId":"ch_work_han_thu_21","textTraditional":"〔九〕　師古曰：「甲乙丙丁庚辛壬癸皆有正位，唯戊己寄治耳。今所置校尉亦無常居，故取戊己為名也。有戊校尉，有己校尉。一說戊己居中，鎮覆四方，今所置校尉亦處西域之中撫諸國也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_21_148","chapterId":"ch_work_han_thu_21","textTraditional":"奉軍都尉掌御乘輿車，駙馬都尉掌駙馬，〔一〕皆武帝初置，秩比二千石。侍中、左右曹、諸吏、散騎、中常侍，皆加官，〔二〕所加或列侯、將軍、卿大夫、將、都尉、尚書、太醫、太官令至郎中，亡員，〔三〕多至數十人。侍中、中常侍得入禁中，諸曹受尚書事，諸吏得舉法，散騎騎並乘輿車。〔四〕給事中亦加官，〔五〕所加或大夫、博士、議郎，掌顧問應對，位次中常侍。中黃門有給事黃門，位從將大夫。皆秦制。","sentenceOrder":148},
  {"id":"s_work_han_thu_21_149","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　師古曰：「駙，副馬也。非正駕車，皆為副馬。一曰駙，近也，疾也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_21_150","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　應劭曰：「入侍天子，故曰侍中。」晉灼曰：「漢儀注諸吏、給事中日上朝謁，平尚書奏事，分為左右曹。魏文帝合散騎、中常侍為散騎常侍也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_21_151","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　如淳曰：「將謂郎將以下也。自列侯下至郎中，皆得有散騎及中常侍加官。是時散騎及常侍各自一官，亡員也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_21_152","chapterId":"ch_work_han_thu_21","textTraditional":"〔四〕　師古曰：「並音步浪反。騎而散從，無常職也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_21_153","chapterId":"ch_work_han_thu_21","textTraditional":"〔五〕　師古曰：「漢官解詁云掌侍從左右，無員，常侍中。」","sentenceOrder":153},
  {"id":"s_work_han_thu_21_154","chapterId":"ch_work_han_thu_21","textTraditional":"爵：一級曰公士，〔一〕二上造，〔二〕三簪裊，〔三〕四不更，〔四〕五大夫，〔五〕六官大夫，七公大夫，〔六〕八公乘，〔七〕九五大夫，〔八〕十左庶長，十一右庶長，〔九〕十二左更，十三中更，十四右更，〔一０〕十五少上造，十六大上造，〔一一〕十七駟車庶長，〔一二〕十八大庶長，〔一三〕十九關內侯，〔一四〕二十徹侯。〔一五〕皆秦制，以賞功勞。徹侯金印紫綬，避武帝諱，曰通侯，或曰列侯，改所食國令長名相，又有家丞、門大夫、庶子。","sentenceOrder":154},
  {"id":"s_work_han_thu_21_155","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　師古曰：「言有爵命，異於士卒，故稱公士也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_21_156","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　師古曰：「造，成也，言有成命於上也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_21_157","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　師古曰：「以組帶馬曰裊。簪裊者，言飾此馬也。裊音乃了反。」","sentenceOrder":157},
  {"id":"s_work_han_thu_21_158","chapterId":"ch_work_han_thu_21","textTraditional":"〔四〕　師古曰：「言不豫更卒之事也。更音工衡反。」","sentenceOrder":158},
  {"id":"s_work_han_thu_21_159","chapterId":"ch_work_han_thu_21","textTraditional":"〔五〕　師古曰：「列位從大夫。」","sentenceOrder":159},
  {"id":"s_work_han_thu_21_160","chapterId":"ch_work_han_thu_21","textTraditional":"〔六〕　師古曰：「加官、公者，示稍尊也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_21_161","chapterId":"ch_work_han_thu_21","textTraditional":"〔七〕　師古曰：「言其得乘公家之車也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_21_162","chapterId":"ch_work_han_thu_21","textTraditional":"〔八〕　師古曰：「大夫之尊也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_21_163","chapterId":"ch_work_han_thu_21","textTraditional":"〔九〕　師古曰：「庶長，言為眾列之長也。」","sentenceOrder":163},
  {"id":"s_work_han_thu_21_164","chapterId":"ch_work_han_thu_21","textTraditional":"〔一０〕師古曰：「更言主領更卒，部其役使也。更音工衡反。」","sentenceOrder":164},
  {"id":"s_work_han_thu_21_165","chapterId":"ch_work_han_thu_21","textTraditional":"〔一一〕師古曰：「言皆主上造之士也。」","sentenceOrder":165},
  {"id":"s_work_han_thu_21_166","chapterId":"ch_work_han_thu_21","textTraditional":"〔一二〕師古曰：「言乘駟馬之車而為眾長也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_21_167","chapterId":"ch_work_han_thu_21","textTraditional":"〔一三〕師古曰：「又更尊也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_21_168","chapterId":"ch_work_han_thu_21","textTraditional":"〔一四〕師古曰：「言有侯號而居京畿，無國邑。」","sentenceOrder":168},
  {"id":"s_work_han_thu_21_169","chapterId":"ch_work_han_thu_21","textTraditional":"〔一五〕師古曰：「言其爵位上通於天子。」","sentenceOrder":169},
  {"id":"s_work_han_thu_21_170","chapterId":"ch_work_han_thu_21","textTraditional":"諸侯王，高帝初置，〔一〕金璽盭綬，〔二〕掌治其國。有太傅輔王，內史治國民，中尉掌武職，丞相統眾官，群卿大夫都官如漢朝。景帝中五年令諸侯王不得復治國，天子為置吏，改丞相曰相，省御史大夫、廷尉、少府、宗正、博士官，大夫、謁者、郎諸官長丞皆損其員。武帝改漢內史為京兆尹，中尉為執金吾，郎中令為光祿勳，故王國如故。損其郎中令，秩千石；改太僕曰僕，秩亦千石。成帝綏和元年省內史，更令相治民，如郡太守，中尉如郡都尉。","sentenceOrder":170},
  {"id":"s_work_han_thu_21_171","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　師古曰：「蔡邕云漢制皇子封為王，其實諸侯也。周末諸侯或稱王，漢天子自以皇帝為稱，故以王號加之，總名諸侯王也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_21_172","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　如淳曰：「盭音戾。盭，綠也，以綠為質。」晉灼曰：「盭，草名也，出琅邪平昌縣，似艾，可染綠，因以為綬名也。」師古曰：「晉說是也。璽之言信也。古者印璽通名，今則尊卑有別。漢舊儀云諸侯王黃金璽，橐佗鈕，文曰璽，謂刻云某王之璽。」","sentenceOrder":172},
  {"id":"s_work_han_thu_21_173","chapterId":"ch_work_han_thu_21","textTraditional":"監御史，秦官，掌監郡。漢省，丞相遣史分刺州，不常置。武帝元封五年初置部刺史，掌奉詔條察州，〔一〕秩六百石，員十三人。成帝綏和元年更名牧，秩二千石。哀帝建平二年復為刺史，元壽二年復為牧。","sentenceOrder":173},
  {"id":"s_work_han_thu_21_174","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　師古曰：「漢官典職儀云刺史班宣，周行郡國，省察治狀，黜陟能否，斷治冤獄，以六條問事，非條所問，即不省。一條，強宗豪右田宅踰制，以強淩弱，以眾暴寡。二條，二千石不奉詔書遵承典制，倍公向私，旁詔守利，侵漁百姓，聚斂為姦。三條，二千石不卹疑獄，風厲殺人，怒則任刑，喜則淫賞，煩擾刻暴，剝截黎元，為百姓所疾，山崩石裂，祅祥訛言。四條，二千石選署不平，苟阿所愛，蔽賢寵頑。五條，二千石子弟恃怙榮勢，請託所監。六條，二千〔石〕違公下比，阿附豪強，通行貨賂，割損正令也。」","sentenceOrder":174},
  {"id":"s_work_han_thu_21_175","chapterId":"ch_work_han_thu_21","textTraditional":"郡守，秦官，掌治其郡，秩二千石。有丞，邊郡又有長史，掌兵馬，秩皆六百石。景帝中二年更名太守。","sentenceOrder":175},
  {"id":"s_work_han_thu_21_176","chapterId":"ch_work_han_thu_21","textTraditional":"郡尉，秦官，掌佐守典武職甲卒，秩比二千石。有丞，秩皆六百石。景帝中二年更名都尉。","sentenceOrder":176},
  {"id":"s_work_han_thu_21_177","chapterId":"ch_work_han_thu_21","textTraditional":"關都尉，秦官。農都尉、屬國都尉，皆武帝初置。","sentenceOrder":177},
  {"id":"s_work_han_thu_21_178","chapterId":"ch_work_han_thu_21","textTraditional":"縣令、長，皆秦官，掌治其縣。萬戶以上為令，秩千石至六百石。減萬戶為長，秩五百石至三百石。皆有丞、尉，秩四百石至二百石，是為長吏。〔一〕百石以下有斗食、佐史之秩，〔二〕是為少吏。大率十里一亭，亭有長。十亭一鄉，鄉有三老、有秩、嗇夫、游徼。三老掌教化。嗇夫職聽訟，收賦稅。游徼徼循禁賊盜。縣大率方百里，其民稠則減，稀則曠，鄉、亭亦如之，皆秦制也。列侯所食縣曰國，皇太后、皇后、公主所食曰邑，有蠻夷曰道。凡縣、道、國、邑千五百八十七，鄉六千六百二十二，亭二萬九千六百三十五。","sentenceOrder":178},
  {"id":"s_work_han_thu_21_179","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　師古曰：「吏，理也，主理其縣內也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_21_180","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　師古曰：「漢官名秩簿云斗食月奉十一斛，佐史月奉八斛也。一說，斗食者，歲奉不滿百石，計日而食一斗二升，故云斗食也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_21_181","chapterId":"ch_work_han_thu_21","textTraditional":"凡吏秩比二千石以上，皆銀印青綬，〔一〕光祿大夫無。〔二〕秩比六百石以上，皆銅印黑綬，大夫、博士、御史、謁者、郎無〔三〕。其僕射、御史治書尚符璽者，有印綬。比二百石以上，皆銅印黃綬。〔四〕成帝陽朔二年除八百石、五百石秩。綏和元年，長、相皆黑綬。哀帝建平二年，復黃綬。吏員自佐史至丞相，十二萬二百八十五人。","sentenceOrder":181},
  {"id":"s_work_han_thu_21_182","chapterId":"ch_work_han_thu_21","textTraditional":"〔一〕　師古曰：「漢舊儀云銀印背龜鈕，其文曰章，謂刻曰某官之章也。」","sentenceOrder":182},
  {"id":"s_work_han_thu_21_183","chapterId":"ch_work_han_thu_21","textTraditional":"〔二〕　師古曰：「無印綬。」","sentenceOrder":183},
  {"id":"s_work_han_thu_21_184","chapterId":"ch_work_han_thu_21","textTraditional":"〔三〕　師古曰：「大夫以下亦無印綬。」","sentenceOrder":184},
  {"id":"s_work_han_thu_21_185","chapterId":"ch_work_han_thu_21","textTraditional":"〔四〕　師古曰：「漢舊儀云六百石、四百石至二百石以上皆銅印鼻鈕，文曰印。謂鈕但作鼻，不為蟲獸之形，而刻文云某官之印。」","sentenceOrder":185},
  {"id":"s_work_han_thu_21_186","chapterId":"ch_work_han_thu_21","textTraditional":"校勘記","sentenceOrder":186},
  {"id":"s_work_han_thu_21_187","chapterId":"ch_work_han_thu_21","textTraditional":"七二一頁　七行　（皇）〔黃〕帝　景祐、殿、局本都作「黃」。王先謙說作「黃」是。","sentenceOrder":187},
  {"id":"s_work_han_thu_21_188","chapterId":"ch_work_han_thu_21","textTraditional":"七二六頁一二行　博士，秦官，　此處本提行，景祐、汲古、局本並同，惟殿本連上。王先謙說博士屬太常，不提行是。","sentenceOrder":188},
  {"id":"s_work_han_thu_21_189","chapterId":"ch_work_han_thu_21","textTraditional":"七二七頁　二行　尊大之（儀）〔義〕也。　景祐、殿本都作「義」。王先謙說作「義」是。","sentenceOrder":189},
  {"id":"s_work_han_thu_21_190","chapterId":"ch_work_han_thu_21","textTraditional":"七二七頁　七行　大夫掌論議，　此處本提行，汲古本同，景祐、殿、局本連上。王先謙說此郎中令屬官，不提行是。","sentenceOrder":190},
  {"id":"s_work_han_thu_21_191","chapterId":"ch_work_han_thu_21","textTraditional":"七二八頁　一行　僕射，秦官，　此處本提行，而景祐、殿本連上。王先謙說不提行是。","sentenceOrder":191},
  {"id":"s_work_han_thu_21_192","chapterId":"ch_work_han_thu_21","textTraditional":"七三０頁　二行　挏取其上（把）〔肥〕，　景祐、殿本都作「肥」。王先謙說作「肥」是。","sentenceOrder":192},
  {"id":"s_work_han_thu_21_193","chapterId":"ch_work_han_thu_21","textTraditional":"七三一頁一四行　十（二）〔六〕官令丞，　錢大昭說「十二」疑是「十六」。按殿本作「十六」。王先謙說作「十六」是。","sentenceOrder":193},
  {"id":"s_work_han_thu_21_194","chapterId":"ch_work_han_thu_21","textTraditional":"七三一頁一六行　（七）〔八〕官令丞。　殿本「七」作「八」。王先謙說作「八」是。","sentenceOrder":194},
  {"id":"s_work_han_thu_21_195","chapterId":"ch_work_han_thu_21","textTraditional":"七三二頁　六行　（供）〔共〕音居用反。　景祐、殿本都作「共」。王先謙說作「共」是。","sentenceOrder":195},
  {"id":"s_work_han_thu_21_196","chapterId":"ch_work_han_thu_21","textTraditional":"七三六頁　三行　分置左〔右〕內史。　王念孫說脫「右」字，下文「右內史」、「左內史」皆承此句言之。","sentenceOrder":196},
  {"id":"s_work_han_thu_21_197","chapterId":"ch_work_han_thu_21","textTraditional":"七三六頁一二行　又（有）〔右〕都水、　劉攽說「有」當作「右」。上云「左都水」，此云「右都水」。","sentenceOrder":197},
  {"id":"s_work_han_thu_21_198","chapterId":"ch_work_han_thu_21","textTraditional":"七三六頁一三行　更置（二）〔三〕輔都尉、　錢大昭說「二」當作「三」。按景祐、殿本都作「三」。","sentenceOrder":198},
  {"id":"s_work_han_thu_21_199","chapterId":"ch_work_han_thu_21","textTraditional":"七四二頁　五行　二千〔石〕違公下比，　「石」字據景祐、殿、局本補。","sentenceOrder":199},
  {"id":"s_work_han_thu_22_1","chapterId":"ch_work_han_thu_22","textTraditional":"師古曰：「此表中記公卿姓名不具及但舉其官而無名或言若干年不載遷免死者，皆史之闕文，不可得知。」","sentenceOrder":1},
  {"id":"s_work_han_thu_22_2","chapterId":"ch_work_han_thu_22","textTraditional":"百官公卿表第七","sentenceOrder":2},
  {"id":"s_work_han_thu_22_3","chapterId":"ch_work_han_thu_22","textTraditional":"校勘記","sentenceOrder":3},
  {"id":"s_work_han_thu_22_4","chapterId":"ch_work_han_thu_22","textTraditional":"七五一頁　一欄　三格「十年」據景祐、殿本補。","sentenceOrder":4},
  {"id":"s_work_han_thu_22_5","chapterId":"ch_work_han_thu_22","textTraditional":"七五三頁　三欄　四格原在三格，據景祐、殿、局本移下。王先謙說「窋」訛「窟」。按局本作「窋」。","sentenceOrder":5},
  {"id":"s_work_han_thu_22_6","chapterId":"ch_work_han_thu_22","textTraditional":"七五四頁　三欄　四格原在五格，據景祐、殿、局本移上。","sentenceOrder":6},
  {"id":"s_work_han_thu_22_7","chapterId":"ch_work_han_thu_22","textTraditional":"七五九頁　三欄　二格「倉」，殿本作「蒼」。王先謙說作「蒼」是。","sentenceOrder":7},
  {"id":"s_work_han_thu_22_8","chapterId":"ch_work_han_thu_22","textTraditional":"七六二頁　一欄　六格「奉常」據景祐、殿本補。　王先謙說蓋盎免而殷代也。","sentenceOrder":8},
  {"id":"s_work_han_thu_22_9","chapterId":"ch_work_han_thu_22","textTraditional":"七六四頁　一欄　十三格，王先謙說中尉都三年方免，此處不應有「中尉」二字。","sentenceOrder":9},
  {"id":"s_work_han_thu_22_10","chapterId":"ch_work_han_thu_22","textTraditional":"七六五頁　三欄　二格，王先謙說「死」為「免」字之訛。　按殿本作「免」。四格，王先謙說「死」亦「免」之誤。","sentenceOrder":10},
  {"id":"s_work_han_thu_22_11","chapterId":"ch_work_han_thu_22","textTraditional":"七六六頁　四欄　二格，王先謙說「後」字蓋衍。","sentenceOrder":11},
  {"id":"s_work_han_thu_22_12","chapterId":"ch_work_han_thu_22","textTraditional":"七六九頁　一欄　九格，王先謙說「年」下脫「遷」字。　按各本都脫。","sentenceOrder":12},
  {"id":"s_work_han_thu_22_13","chapterId":"ch_work_han_thu_22","textTraditional":"七七一頁　一欄　八格，王先謙說「都」當為「衛」。　按景祐、殿本都作「衛」。","sentenceOrder":13},
  {"id":"s_work_han_thu_22_14","chapterId":"ch_work_han_thu_22","textTraditional":"七七五頁　二欄　十四格，王先謙說「陽」當為「楊」。　按景祐、殿本都作「楊」。","sentenceOrder":14},
  {"id":"s_work_han_thu_22_15","chapterId":"ch_work_han_thu_22","textTraditional":"七七九頁　二欄　十二格，王先謙說「為」字衍。　按景祐、殿本無。","sentenceOrder":15},
  {"id":"s_work_han_thu_22_16","chapterId":"ch_work_han_thu_22","textTraditional":"七八三頁　三欄　十三格，王先謙說「中尉」衍文。","sentenceOrder":16},
  {"id":"s_work_han_thu_22_17","chapterId":"ch_work_han_thu_22","textTraditional":"七八六頁　二欄　十五格原在十四格，據景祐、殿本移下。","sentenceOrder":17},
  {"id":"s_work_han_thu_22_18","chapterId":"ch_work_han_thu_22","textTraditional":"七九四頁　二欄　十格，王先謙說「道」是「首」之誤字。","sentenceOrder":18},
  {"id":"s_work_han_thu_22_19","chapterId":"ch_work_han_thu_22","textTraditional":"七九五頁　二欄　六格「夜郎」，景祐、殿本都作「郎夜」。　王先謙說「郎」在「夜」上是。","sentenceOrder":19},
  {"id":"s_work_han_thu_22_20","chapterId":"ch_work_han_thu_22","textTraditional":"七九七頁　一欄　二格，殿本考證說「相」上脫「丞」字。　按景祐本有。","sentenceOrder":20},
  {"id":"s_work_han_thu_22_21","chapterId":"ch_work_han_thu_22","textTraditional":"七九八頁　一欄　十格，殿本「加」作「邢」。","sentenceOrder":21},
  {"id":"s_work_han_thu_22_22","chapterId":"ch_work_han_thu_22","textTraditional":"八００頁　二欄　十五格，王先謙說「田」是「尹」之誤。　按景祐、局本都作「尹」。","sentenceOrder":22},
  {"id":"s_work_han_thu_22_23","chapterId":"ch_work_han_thu_22","textTraditional":"八０二頁　二欄　十四格，沈欽韓說「為」字衍。","sentenceOrder":23},
  {"id":"s_work_han_thu_22_24","chapterId":"ch_work_han_thu_22","textTraditional":"八０三頁　一欄　三格，錢大昭說「農」當為「馬」。　按景祐、殿、局本都作「馬」。","sentenceOrder":24},
  {"id":"s_work_han_thu_22_25","chapterId":"ch_work_han_thu_22","textTraditional":"八０九頁　二欄　四格據景祐、殿本補。錢大昭說閩本有。六格原在五格，八格原在七格，據景祐、殿本移下。","sentenceOrder":25},
  {"id":"s_work_han_thu_22_26","chapterId":"ch_work_han_thu_22","textTraditional":"八一一頁　三欄　二格「二」，景祐、殿本都作「三」。王先謙說作「三」是。","sentenceOrder":26},
  {"id":"s_work_han_thu_22_27","chapterId":"ch_work_han_thu_22","textTraditional":"八一二頁　三欄　十五格據景祐、殿本補。錢大昭說閩本有。","sentenceOrder":27},
  {"id":"s_work_han_thu_22_28","chapterId":"ch_work_han_thu_22","textTraditional":"八一三頁　二欄　十四格，殿本有「馮奉世」三字，考證說從宋本補。　按景祐本無此三字。","sentenceOrder":28},
  {"id":"s_work_han_thu_22_29","chapterId":"ch_work_han_thu_22","textTraditional":"八一七頁　一欄　十二格原在十一格，據景祐、殿、局本移下。","sentenceOrder":29},
  {"id":"s_work_han_thu_22_30","chapterId":"ch_work_han_thu_22","textTraditional":"八二０頁　四欄　四格，錢大昭說「光祿」下脫「勳」字。　按各本都脫。","sentenceOrder":30},
  {"id":"s_work_han_thu_22_31","chapterId":"ch_work_han_thu_22","textTraditional":"八二一頁　二欄　四格「縏」，王先謙說殿本作「繁」是。","sentenceOrder":31},
  {"id":"s_work_han_thu_22_32","chapterId":"ch_work_han_thu_22","textTraditional":"八二二頁　一欄　十四格「謂」，景祐、殿、局本都作「為」。","sentenceOrder":32},
  {"id":"s_work_han_thu_22_33","chapterId":"ch_work_han_thu_22","textTraditional":"八二二頁　三欄　四格，沈欽韓說史表作「三月」，「七月」是傳寫之誤。　按景祐本正作「三月」。","sentenceOrder":33},
  {"id":"s_work_han_thu_22_34","chapterId":"ch_work_han_thu_22","textTraditional":"八二三頁　三欄　十五格，「尊」字據景祐、殿本補。","sentenceOrder":34},
  {"id":"s_work_han_thu_22_35","chapterId":"ch_work_han_thu_22","textTraditional":"八三０頁　二欄　十三格，景祐、殿本都作「域」，「城」字誤。","sentenceOrder":35},
  {"id":"s_work_han_thu_22_36","chapterId":"ch_work_han_thu_22","textTraditional":"八三六頁　一欄　十五格「寵」，景祐、殿本都作「龐」。王先謙說作「龐」是。","sentenceOrder":36},
  {"id":"s_work_han_thu_22_37","chapterId":"ch_work_han_thu_22","textTraditional":"八四０頁　二欄　七格「亡」，景祐、殿本都作「玄」。","sentenceOrder":37},
  {"id":"s_work_han_thu_22_38","chapterId":"ch_work_han_thu_22","textTraditional":"八四一頁　二欄　八格「湯」，景祐、殿、局本都作「陽」。　王先謙說作「陽」。十三格「中陵」，景祐、殿本都作「平陵」。　王先謙說作「平陵」是。十四格「州」，景祐、殿本都作「水」。　王先謙說作「水」是。","sentenceOrder":38},
  {"id":"s_work_han_thu_22_39","chapterId":"ch_work_han_thu_22","textTraditional":"八四七頁　一欄　五格「嶠」，景祐、殿本都作「蟜」。","sentenceOrder":39},
  {"id":"s_work_han_thu_22_40","chapterId":"ch_work_han_thu_22","textTraditional":"八五０頁　二欄　一格，景祐、殿本無「二」字。","sentenceOrder":40},
  {"id":"s_work_han_thu_22_41","chapterId":"ch_work_han_thu_22","textTraditional":"八五二頁　一欄　一格「三」，景祐、殿本都作「二」。　周壽昌說孝哀崩於元壽二年，無三年。","sentenceOrder":41},
  {"id":"s_work_han_thu_22_42","chapterId":"ch_work_han_thu_22","textTraditional":"八五二頁　一欄　六格「都」，景祐、殿本都作「郡」。　王先謙說作「郡」是。","sentenceOrder":42},
  {"id":"s_work_han_thu_22_43","chapterId":"ch_work_han_thu_22","textTraditional":"八五五頁　二欄　四格，王先謙說「病」上「為」字衍，「府」當作「傅」。","sentenceOrder":43},
  {"id":"s_work_han_thu_23_1","chapterId":"ch_work_han_thu_23","textTraditional":"師古曰：「但次古人而不表今人者，其書未畢故也。」","sentenceOrder":1},
  {"id":"s_work_han_thu_23_2","chapterId":"ch_work_han_thu_23","textTraditional":"自書契之作，先民可得而聞者，經傳所稱，唐虞以上，帝王有號諡。輔佐不可得而稱矣，〔一〕而諸子頗言之，雖不考虖孔氏，然猶著在篇籍，歸乎顯善昭惡，勸戒後人，故博采焉。孔子曰：「若聖與仁，則吾豈敢？」〔二〕又曰：「何事於仁，必也聖乎！」〔三〕「未知，焉得仁？」〔四〕「生而知之者，上也；學而知之者，次也；困而學之，又其次也；困而不學，民斯為下矣。」〔五〕又曰：「中人以上，可以語上也。」〔六〕「唯上智與下愚不移。」〔七〕傳曰：譬如堯舜，禹、稷、卨與之為善則行，〔八〕鯀、讙兜欲與為惡則誅。〔九〕可與為善，不可與為惡，是謂上智。桀紂，龍逢、比干欲與之為善則誅，〔一０〕于莘、崇侯與之為惡則行。〔一一〕可與為惡，不可與為善，是謂下愚。齊桓公，管仲相之則霸，豎貂輔之則亂。〔一二〕可與為善，可與為惡，是謂中人。因茲以列九等之序，究極經傳，繼世相次，總備古今之略要云。〔一三〕","sentenceOrder":2},
  {"id":"s_work_han_thu_23_3","chapterId":"ch_work_han_thu_23","textTraditional":"〔一〕　文穎曰：「言遠，經傳不復稱序也。」師古曰：「契謂刻木以記事。自唐虞以上帝王有號見於經典，其臣佐不可得而稱記也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_23_4","chapterId":"ch_work_han_thu_23","textTraditional":"〔二〕　師古曰：「此孔子自謙，不敢當聖與仁也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_23_5","chapterId":"ch_work_han_thu_23","textTraditional":"〔三〕　師古曰：「言能博施於人而濟眾者，非止稱仁，乃為聖人也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_23_6","chapterId":"ch_work_han_thu_23","textTraditional":"〔四〕　師古曰：「言智者雖能利物，猶不及仁者所濟遠也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_23_7","chapterId":"ch_work_han_thu_23","textTraditional":"〔五〕　師古曰：「困謂有所不通也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_23_8","chapterId":"ch_work_han_thu_23","textTraditional":"〔六〕　師古曰：「言中庸之人漸於訓誨，可以知上智之所知也。","sentenceOrder":8},
  {"id":"s_work_han_thu_23_9","chapterId":"ch_work_han_thu_23","textTraditional":"〔七〕　師古曰：「言上智不染於惡，下愚雖教無成。自此已上皆見論語。凡引此者，蓋班氏自述所表先聖後仁乃智愚之次，皆依於孔子者也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_23_10","chapterId":"ch_work_han_thu_23","textTraditional":"〔八〕　師古曰：「傳謂解說經義者也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_23_11","chapterId":"ch_work_han_thu_23","textTraditional":"〔九〕　師古曰：「鯀，擣扤也。讙兜，渾敦也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_23_12","chapterId":"ch_work_han_thu_23","textTraditional":"〔一０〕師古曰：「關龍逢，桀之臣也；王子比干，紂之臣也：皆直諫而死也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_23_13","chapterId":"ch_work_han_thu_23","textTraditional":"〔一一〕師古曰：「于莘，桀之勇人也。崇侯，紂之佞臣也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_23_14","chapterId":"ch_work_han_thu_23","textTraditional":"〔一二〕師古曰：「豎貂，即寺人貂也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_23_15","chapterId":"ch_work_han_thu_23","textTraditional":"〔一三〕張晏曰：「老子玄默，仲尼所師，雖不在聖，要為大賢，文伯之母達於禮典，動為聖人所歎，言為後世所則，而在第四。田單以即墨孤城復強齊之大，魯連之博通，忽於榮利，藺子申威秦王，退讓廉頗，乃在第五。大姬巫怪，好祭鬼神，陳人化之，國多淫祀，寺人孟子違於大雅，以保其身，既被宮刑，怨刺而作，乃在第三。嫪毐上烝，昏亂禮度，惡不忍聞，乃在第七。其餘差違紛錯不少，略舉揚較，以起失謬。獨馳騖於數千歲之中，旁觀諸子，事業未究，而尋遇竇氏之難，使之然乎？」師古曰：「六家之論，輕重不同；百行所存，趣拾難壹。張氏輒申所見，掎摭班史，然其所論，又自差錯。且年代久遠，墳典隟亡，學者舛駮，師論分異，是以表載古人名氏，或與諸書不同。今則特有發明，用暢厥旨。自女媧以下，帝鴻以前，諸子傳記，互有舛駮，敘說不同，無所取正，大要知其古帝之號而已。諸人士見於史傳，彰灼可知者，無待解釋，其間幽昧者，時復及焉。」","sentenceOrder":15},
  {"id":"s_work_han_thu_23_16","chapterId":"ch_work_han_thu_23","textTraditional":"（表格，尚無資料）","sentenceOrder":16},
  {"id":"s_work_han_thu_23_17","chapterId":"ch_work_han_thu_23","textTraditional":"校勘記","sentenceOrder":17},
  {"id":"s_work_han_thu_23_18","chapterId":"ch_work_han_thu_23","textTraditional":"八七０頁　九格　「九黎」二字據景祐、殿本補。","sentenceOrder":18},
  {"id":"s_work_han_thu_23_19","chapterId":"ch_work_han_thu_23","textTraditional":"八七四頁　二格　景祐本「戮」作「飂」。齊召南說作「戮」刊本之誤。","sentenceOrder":19},
  {"id":"s_work_han_thu_23_20","chapterId":"ch_work_han_thu_23","textTraditional":"八七五頁　一格　「帝堯」二字據景祐、殿本補。","sentenceOrder":20},
  {"id":"s_work_han_thu_23_21","chapterId":"ch_work_han_thu_23","textTraditional":"八七八頁　九格　景祐本「嬌」作「蟜」。","sentenceOrder":21},
  {"id":"s_work_han_thu_23_22","chapterId":"ch_work_han_thu_23","textTraditional":"八八０頁　三格　景祐、殿、局本「支」都作「友」。局本「字」作「宇」。","sentenceOrder":22},
  {"id":"s_work_han_thu_23_23","chapterId":"ch_work_han_thu_23","textTraditional":"八八一頁　六格　王先謙說次「中」字當作「仲」。　按景祐、局本都作「仲」。","sentenceOrder":23},
  {"id":"s_work_han_thu_23_24","chapterId":"ch_work_han_thu_23","textTraditional":"八八二頁　五格　錢大昭說南監本、閩本有「杼子」二字。　按景祐、殿本都有。","sentenceOrder":24},
  {"id":"s_work_han_thu_23_25","chapterId":"ch_work_han_thu_23","textTraditional":"八九二頁　三格　「太」字據景祐、殿本補。","sentenceOrder":25},
  {"id":"s_work_han_thu_23_26","chapterId":"ch_work_han_thu_23","textTraditional":"八九二頁　六格　景祐、殿本「來」下有「朝」字。　王先謙說有「朝」字是。","sentenceOrder":26},
  {"id":"s_work_han_thu_23_27","chapterId":"ch_work_han_thu_23","textTraditional":"八九七頁　五格　景祐、殿本「建」作「疌」。　楊樹達說據錢大昭校閩本亦作「疌」，「建」字以形近而誤。下六格同。","sentenceOrder":27},
  {"id":"s_work_han_thu_23_28","chapterId":"ch_work_han_thu_23","textTraditional":"八九八頁　三格　宋弗父何本在上上格，錢大昭說南監本、閩本在上下。王先謙說殿本在上下，此誤。按景祐本亦在上下。","sentenceOrder":28},
  {"id":"s_work_han_thu_23_29","chapterId":"ch_work_han_thu_23","textTraditional":"八九八頁　八格　王先謙說「厲」當作「獻」。　按景祐本正作「獻」。","sentenceOrder":29},
  {"id":"s_work_han_thu_23_30","chapterId":"ch_work_han_thu_23","textTraditional":"八九九頁　五格　「子」字據景祐、殿、局本補。","sentenceOrder":30},
  {"id":"s_work_han_thu_23_31","chapterId":"ch_work_han_thu_23","textTraditional":"八九九頁　七格　王先謙說「幽」下脫「公」字。　按局本有。","sentenceOrder":31},
  {"id":"s_work_han_thu_23_32","chapterId":"ch_work_han_thu_23","textTraditional":"九００頁　八格　王先謙說「幽」下脫「伯」字。　按局本有。","sentenceOrder":32},
  {"id":"s_work_han_thu_23_33","chapterId":"ch_work_han_thu_23","textTraditional":"九０二頁　九格　景祐、局本「于」作「千」。","sentenceOrder":33},
  {"id":"s_work_han_thu_23_34","chapterId":"ch_work_han_thu_23","textTraditional":"九０三頁　三格　「宋正考父」據局本補。　殿本作「宋考正父」。景祐本無。","sentenceOrder":34},
  {"id":"s_work_han_thu_23_35","chapterId":"ch_work_han_thu_23","textTraditional":"九０五頁　九格　「桓公弟」三字據景祐、殿本補。","sentenceOrder":35},
  {"id":"s_work_han_thu_23_36","chapterId":"ch_work_han_thu_23","textTraditional":"九０六頁　五格　錢大昭說南監本、閩本「駐」作「騅」。　按景祐、殿、局本都作「騅」。","sentenceOrder":36},
  {"id":"s_work_han_thu_23_37","chapterId":"ch_work_han_thu_23","textTraditional":"九一０頁　四格　景祐、殿本都作「完」。　王先謙說作「完」是。","sentenceOrder":37},
  {"id":"s_work_han_thu_23_38","chapterId":"ch_work_han_thu_23","textTraditional":"九一二頁　七格　錢大昭說「叔」當作「射」。　按景祐、殿本都作「射」。","sentenceOrder":38},
  {"id":"s_work_han_thu_23_39","chapterId":"ch_work_han_thu_23","textTraditional":"九一五頁　三格　「嘉子」本作大字，誤，據局本改小。","sentenceOrder":39},
  {"id":"s_work_han_thu_23_40","chapterId":"ch_work_han_thu_23","textTraditional":"九一五頁　四格　「叔子」本作大字，誤，據局本改小。　錢大昕說鬥伯比已見前五等。","sentenceOrder":40},
  {"id":"s_work_han_thu_23_41","chapterId":"ch_work_han_thu_23","textTraditional":"九一六頁　八格　錢大昭說「失」當作「先」。　按景祐、殿、局本都作「先」。","sentenceOrder":41},
  {"id":"s_work_han_thu_23_42","chapterId":"ch_work_han_thu_23","textTraditional":"九二一頁　四格　錢大昭說「白」當作「向」。　按景祐、殿、局本都作「向」。","sentenceOrder":42},
  {"id":"s_work_han_thu_23_43","chapterId":"ch_work_han_thu_23","textTraditional":"九二二頁　五格　粱玉繩說各本「晉陽罕」三字誤分為二。「罕」乃「畢」之訛。陽畢，晉大夫，見晉語。","sentenceOrder":43},
  {"id":"s_work_han_thu_23_44","chapterId":"ch_work_han_thu_23","textTraditional":"九二六頁　七格　「齊景公杵臼嚴公弟」八字據景祐、殿本補。","sentenceOrder":44},
  {"id":"s_work_han_thu_23_45","chapterId":"ch_work_han_thu_23","textTraditional":"九三０頁　七格　「秦惠公哀公孫」六字據景祐、殿本補。","sentenceOrder":45},
  {"id":"s_work_han_thu_23_46","chapterId":"ch_work_han_thu_23","textTraditional":"九三五頁　七格　景祐、殿、局本「戚」都作「成」，「字」都作「子」。","sentenceOrder":46},
  {"id":"s_work_han_thu_23_47","chapterId":"ch_work_han_thu_23","textTraditional":"九四０頁　七格　衛慎公原在八等，據景祐、殿本移上。","sentenceOrder":47},
  {"id":"s_work_han_thu_23_48","chapterId":"ch_work_han_thu_23","textTraditional":"九四四頁　四格　景祐、殿本「鄭」都作「鄚」。","sentenceOrder":48},
  {"id":"s_work_han_thu_23_49","chapterId":"ch_work_han_thu_23","textTraditional":"九四六頁　八格　「顯王子」三字據景祐本補。","sentenceOrder":49},
  {"id":"s_work_han_thu_24_1","chapterId":"ch_work_han_thu_24","textTraditional":"師古曰：「志，記也，積記其事也。春秋左氏傳曰『前志有之』。」","sentenceOrder":1},
  {"id":"s_work_han_thu_24_2","chapterId":"ch_work_han_thu_24","textTraditional":"虞書曰「乃同律度量衡」，〔一〕所以齊遠近立民信也。自伏戲畫八卦，由數起，〔二〕至黃帝、堯、舜而大備。三代稽古，法度章焉。〔三〕周衰官失，孔子陳後王之法，曰：「謹權量，審法度，修廢官，舉逸民，四方之政行矣。」〔四〕漢興，北平侯張蒼首律曆事，〔五〕孝武帝時樂官考正。〔六〕至元始中王莽秉政，欲燿名譽，徵天下通知鐘律者百（餘）餘人，使羲和劉歆等典領條奏，言之最詳。故刪其偽辭，取正義，著于篇。〔七〕","sentenceOrder":2},
  {"id":"s_work_han_thu_24_3","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　師古曰：「虞書，舜典也。同謂齊等。」","sentenceOrder":3},
  {"id":"s_work_han_thu_24_4","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　師古曰：「萬物之數，因八卦而起也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_24_5","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　師古曰：「三代，夏、殷、周也。稽，考也。考於古事，而法度益明。」","sentenceOrder":5},
  {"id":"s_work_han_thu_24_6","chapterId":"ch_work_han_thu_24","textTraditional":"〔四〕　師古曰：「此論語載孔子述古帝王之政，以示後世。權謂斤兩也。量，斗斛也。法度，丈尺也。逸民，謂有德而隱處者。」","sentenceOrder":6},
  {"id":"s_work_han_thu_24_7","chapterId":"ch_work_han_thu_24","textTraditional":"〔五〕　師古曰：「首謂始定也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_24_8","chapterId":"ch_work_han_thu_24","textTraditional":"〔六〕　師古曰：「更質正其事。」","sentenceOrder":8},
  {"id":"s_work_han_thu_24_9","chapterId":"ch_work_han_thu_24","textTraditional":"〔七〕　師古曰：「班氏自云作志取劉歆之義也。自此以下訖於『用竹為引者，事之宜也』，則其辭焉。」","sentenceOrder":9},
  {"id":"s_work_han_thu_24_10","chapterId":"ch_work_han_thu_24","textTraditional":"一曰備數，二曰和聲，三曰審度，四曰嘉量，五曰權衡。參五以變，錯綜其數，稽之於古今，效之於氣物，和之於心耳，考之於經傳，咸得其實，靡不協同。","sentenceOrder":10},
  {"id":"s_work_han_thu_24_11","chapterId":"ch_work_han_thu_24","textTraditional":"數者，一、十、百、千、萬也，所以算數事物，順性命之理也。書曰：「先其算命。」〔一〕本起於黃鐘之數，始於一而三之，三三積之，〔二〕歷十二辰之數，十有七萬七千一百四十七，而五數備矣。〔三〕其算法用竹，徑一分，長六寸，二百七十一枚而成六觚，為一握。〔四〕徑象乾律黃鐘之一，而長象坤呂林鐘之長。〔五〕其數以易大衍之數五十，其用四十九，成陽六爻，得周流六虛之象也〔六〕。夫推曆生律〔七〕制器，規圜矩方，權重衡平，準繩嘉量，〔八〕探賾索隱，鉤深致遠，莫不用焉。〔九〕度長短者不失豪氂，〔一０〕量多少者不失圭撮，〔一一〕權輕重者不失黍絫。〔一二〕紀於一，協於十，長於百，大於千，衍於萬，其法在算術。宣於天下，小學是則。職在太史，羲和掌之。","sentenceOrder":11},
  {"id":"s_work_han_thu_24_12","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　師古曰：「逸書也。言王者統業，先立算數以命百事也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_24_13","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　孟康曰：「黃鐘，子之律也。子數一。泰極元氣含三為一，是以一數變而為三也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_24_14","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　孟康曰：「初以子一乘丑三，餘則轉因其成數以三乘之，歷十二辰，得是積數也。五行陰陽變化之數備於此矣。」","sentenceOrder":14},
  {"id":"s_work_han_thu_24_15","chapterId":"ch_work_han_thu_24","textTraditional":"〔四〕　蘇林曰：「六觚，六角也。度角至角，其度一寸，面容一分，算九枚，相因之數有十，正面之數實九，其表六九五十四，算中積凡得二百七十一枚。」","sentenceOrder":15},
  {"id":"s_work_han_thu_24_16","chapterId":"ch_work_han_thu_24","textTraditional":"〔五〕　張晏曰：「林鐘長六寸。」韋昭曰：「黃鍾管九寸，十分之一，得其一分也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_24_17","chapterId":"ch_work_han_thu_24","textTraditional":"〔六〕　孟康曰：「以四十九成陽六爻為乾，乾之策數二百一十六，以成六爻，是為周流六虛之象也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_24_18","chapterId":"ch_work_han_thu_24","textTraditional":"〔七〕　張晏曰：「推曆十二辰以生律呂也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_24_19","chapterId":"ch_work_han_thu_24","textTraditional":"〔八〕　張晏曰：「準，水平。量知多少，故曰嘉。」","sentenceOrder":19},
  {"id":"s_work_han_thu_24_20","chapterId":"ch_work_han_thu_24","textTraditional":"〔九〕　師古曰：「賾亦深也。索，求也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_24_21","chapterId":"ch_work_han_thu_24","textTraditional":"〔一０〕孟康曰：「豪，兔豪也。十豪為氂。」師古曰：「度音大各反。」","sentenceOrder":21},
  {"id":"s_work_han_thu_24_22","chapterId":"ch_work_han_thu_24","textTraditional":"〔一一〕應劭曰：「圭，自然之形，陰陽之始也。四圭曰撮，三指撮之也。」孟康曰：「六十四黍為圭。」師古曰：「撮音倉括反。」","sentenceOrder":22},
  {"id":"s_work_han_thu_24_23","chapterId":"ch_work_han_thu_24","textTraditional":"〔一二〕孟康曰：「絫音（墨）蠡。」應劭曰：「十黍為絫，十絫為一銖。」師古曰：「絫，孟音來戈反，此字讀亦音纍紲之纍。」","sentenceOrder":23},
  {"id":"s_work_han_thu_24_24","chapterId":"ch_work_han_thu_24","textTraditional":"聲者，宮、商、角、徵、羽也。所以作樂者，諧八音，蕩（降）〔滌〕人之邪意，全其正性，移風易俗也。八音：土曰塤，〔一〕匏曰笙，〔二〕皮曰鼓，〔三〕竹曰管，〔四〕絲曰絃，石曰磬，金曰鐘，木曰柷。〔五〕五聲和，八音諧，而樂成。商之為言章也，物成孰可章度也。〔六〕角，觸也，物觸地而出，戴芒角也。宮，中也，居中央，暢四方，唱始施生，為四聲綱也。徵，祉也，物盛大而緐祉也。羽，宇也，物聚臧宇覆之也。夫聲者，中於宮，觸於角，祉於徵，章於商，宇於羽，故四聲為宮紀也。協之五行，則角為木，五常為仁，五事為貌。商為金為義為言，徵為火為禮為視，羽為水為智為聽，宮為土為信為思。以君臣民事物言之，則宮為君，商為臣，角為民，徵為事，羽為物。唱和有象，故言君臣位事之體也。","sentenceOrder":24},
  {"id":"s_work_han_thu_24_25","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　應劭曰：「世本暴辛公作塤。」師古曰：「燒土為之，其形銳上而平底，六孔吹之。塤音許元反，字或作壎，其音同耳。」","sentenceOrder":25},
  {"id":"s_work_han_thu_24_26","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　應劭曰：「世本隨作笙。」師古曰：「匏，瓠也。列管瓠中，施簧管端。」","sentenceOrder":26},
  {"id":"s_work_han_thu_24_27","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　師古曰：「鼓者郭也，言郭張皮而為之。」","sentenceOrder":27},
  {"id":"s_work_han_thu_24_28","chapterId":"ch_work_han_thu_24","textTraditional":"〔四〕　孟康曰：「禮樂器記，管，漆竹，長一尺，六孔。尚書大傳，西王母來獻白玉琯。漢章帝時零陵文學奚景於泠道舜祠下得白玉琯。古以玉作，不但竹也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_24_29","chapterId":"ch_work_han_thu_24","textTraditional":"〔五〕　師古曰：「柷與俶同，俶，始也。樂將作，先鼓之，故謂之柷。狀如漆桶，中有椎，連底動之，令左右擊。音昌六反。」","sentenceOrder":29},
  {"id":"s_work_han_thu_24_30","chapterId":"ch_work_han_thu_24","textTraditional":"〔六〕　師古曰：「度音大各反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_24_31","chapterId":"ch_work_han_thu_24","textTraditional":"五聲之本，生於黃鐘之律。九寸為宮，或損或益，以定商、角、徵、羽。九六相生，陰陽之應也。律十有二，陽六為律，陰六為呂。律以統氣類物，一曰黃鐘，二曰太族，〔一〕三曰姑洗，四曰蕤賓，五曰夷則，六曰亡射。〔二〕呂以旅陽宣氣，一曰林鐘，二曰南呂，三曰應鐘，四曰大呂，五曰夾鐘，六曰中呂。〔三〕有三統之義焉。其傳曰，黃帝之所作也。黃帝使泠綸，〔四〕自大夏之西，〔五〕昆侖之陰，取竹之解谷〔六〕生，其竅厚均者，〔七〕斷兩節間而吹之，以為黃鐘之宮。〔八〕制十二筩以聽鳳之鳴，〔九〕其雄鳴為六，雌鳴亦六，比黃鐘之宮，而皆可以生之，是為律本。〔一０〕至治之世，天地之氣合以生風；天地之風氣正，十二律定。〔一一〕黃鐘：黃者，中之色，君之服也；鐘者，種也。天之中數五，〔一二〕五為聲，聲上宮，五聲莫大焉。地之中數六，〔一三〕六為律，律有形有色，色上黃，五色莫盛焉。故陽氣施種於黃泉，孳萌萬物，〔一四〕為六氣元也。以黃色名元氣律者，著宮聲也。宮以九唱六，〔一五〕變動不居，周流六虛。始於子，在十一月。大呂：呂，旅也，言陰大，旅助黃鐘（宮）〔宣〕氣而牙物也。位於丑，在十二月。太族：族，奏也，言陽氣大，奏地而達物也。〔一六〕位於寅，在正月。夾鐘，言陰夾助太族宣四方之氣而出種物也。位於卯，在二月。姑洗：洗，絜也，言陽氣洗物辜絜之也。〔一七〕位於辰，在三月。中呂，言微陰始起未成，著於其中旅助姑洗宣氣齊物也。位於巳，在四月。蕤賓：蕤，繼也，賓，導也，言陽始導陰氣使繼養物也。位於午，在五月。林鐘：林，君也，言陰氣受任，助蕤賓君主種物使長大楙盛也。〔一八〕位於未，在六月。夷則：則，法也，言陽氣正法度而使陰氣夷當傷之物也。〔一九〕位於申，在七月。南呂：南，任也，言陰氣旅助夷則任成萬物也。位於酉，在八月。亡射：射，厭也，言陽氣究物而使陰氣畢剝落之，終而復始，亡厭已也。位於戌，在九月。應鐘，言陰氣應亡射，該臧萬物而雜陽閡種也。〔二０〕位於亥，在十月。","sentenceOrder":31},
  {"id":"s_work_han_thu_24_32","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　師古曰：「族音千豆反。其下並同。」","sentenceOrder":32},
  {"id":"s_work_han_thu_24_33","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　師古曰：「亡讀曰無。射音亦石反。」","sentenceOrder":33},
  {"id":"s_work_han_thu_24_34","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　師古曰：「中讀曰仲。」","sentenceOrder":34},
  {"id":"s_work_han_thu_24_35","chapterId":"ch_work_han_thu_24","textTraditional":"〔四〕　師古曰：「泠音零。綸音倫也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_24_36","chapterId":"ch_work_han_thu_24","textTraditional":"〔五〕　應劭曰：「大夏，西戎之國也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_24_37","chapterId":"ch_work_han_thu_24","textTraditional":"〔六〕　孟康曰：「解，脫也。谷，竹溝也。取竹之脫無溝節者也。一說昆侖之北谷名也。」晉灼曰：「谷名是也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_24_38","chapterId":"ch_work_han_thu_24","textTraditional":"〔七〕　應劭曰：「生者，治也。竅，孔也。」孟康曰：「竹孔與肉薄厚等也。」晉灼曰：「取谷中之竹，生而（孔外肉）〔肉孔外內〕厚薄自然均者，截以為筩，不復加削刮也。」師古曰：「晉說是也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_24_39","chapterId":"ch_work_han_thu_24","textTraditional":"〔八〕　師古曰：「黃鐘之宮，律之最長者。」","sentenceOrder":39},
  {"id":"s_work_han_thu_24_40","chapterId":"ch_work_han_thu_24","textTraditional":"〔九〕　師古曰：「筩音大東反。」","sentenceOrder":40},
  {"id":"s_work_han_thu_24_41","chapterId":"ch_work_han_thu_24","textTraditional":"〔一０〕師古曰：「比，合也。可以生之，謂上下相生也，故謂之律本。比音頻寐反。」","sentenceOrder":41},
  {"id":"s_work_han_thu_24_42","chapterId":"ch_work_han_thu_24","textTraditional":"〔一一〕孟康曰：「律得風氣而成聲，風和乃律調也。」臣瓚曰：「風氣正則十二月之氣各應其律，不失其序。」","sentenceOrder":42},
  {"id":"s_work_han_thu_24_43","chapterId":"ch_work_han_thu_24","textTraditional":"〔一二〕韋昭曰：「一三在上，七九在下。」","sentenceOrder":43},
  {"id":"s_work_han_thu_24_44","chapterId":"ch_work_han_thu_24","textTraditional":"〔一三〕韋昭曰：「二四在上，八十在下。」","sentenceOrder":44},
  {"id":"s_work_han_thu_24_45","chapterId":"ch_work_han_thu_24","textTraditional":"〔一四〕師古曰：「孳讀與滋同，滋，益也。萌，始生。」","sentenceOrder":45},
  {"id":"s_work_han_thu_24_46","chapterId":"ch_work_han_thu_24","textTraditional":"〔一五〕孟康曰：「黃鐘陽九，林鐘陰六，言陽唱陰和。」","sentenceOrder":46},
  {"id":"s_work_han_thu_24_47","chapterId":"ch_work_han_thu_24","textTraditional":"〔一六〕師古曰：「奏，進也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_24_48","chapterId":"ch_work_han_thu_24","textTraditional":"〔一七〕孟康曰：「辜，必也，必使之絜也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_24_49","chapterId":"ch_work_han_thu_24","textTraditional":"〔一八〕師古曰：「種物，種生之物。楙，古茂字也。種音之勇反。」","sentenceOrder":49},
  {"id":"s_work_han_thu_24_50","chapterId":"ch_work_han_thu_24","textTraditional":"〔一九〕師古曰：「夷亦傷。」","sentenceOrder":50},
  {"id":"s_work_han_thu_24_51","chapterId":"ch_work_han_thu_24","textTraditional":"〔二０〕孟康曰：「（該）〔閡〕，臧塞也，陰雜陽氣，臧塞為萬物作種也。」晉灼曰：「外閉曰閡。」師古曰：「閡音胡待反。下言『該閡於亥』，音訓並同也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_24_52","chapterId":"ch_work_han_thu_24","textTraditional":"三統者，天施，地化，人事之紀也。〔一〕十一月，乾之初九，陽氣伏於地下，始著為一，萬物萌動，鐘於太陰，故黃鐘為天統，律長九寸。九者，所以究極中和，為萬物元也。易曰：「立天之道，曰陰與陽。」〔二〕六月，坤之初六，陰氣受任於太陽，繼養化柔，萬物生長，楙之於未，令種剛彊大，故林鐘為地統，律長六寸。六者，所以含陽之施，楙之於六合之內，令剛柔有體也。「立地之道，曰柔與剛。」〔三〕「乾知太始，坤作成物。」〔四〕正月，乾之九三，萬物棣通，〔五〕族出於寅，人奉而成之，仁以養之，義以行之，令事物各得其理。寅，木也，為仁；其聲，商也，為義。故太族為人統，律長八寸，象八卦，宓戲氏之所以順天地，通神明，類萬物之情也。〔六〕「立人之道，曰仁與義。」〔七〕「在天成象，在地成形。」〔八〕「后以裁成天地之道，輔相天地之宜，以左右民。」〔九〕此三律之謂矣，是為三統。","sentenceOrder":52},
  {"id":"s_work_han_thu_24_53","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　李奇曰：「統，緒也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_24_54","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　師古曰：「易說卦之辭。」","sentenceOrder":54},
  {"id":"s_work_han_thu_24_55","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　師古曰：「此亦說卦之辭也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_24_56","chapterId":"ch_work_han_thu_24","textTraditional":"〔四〕　師古曰：「此上繫之辭。」","sentenceOrder":56},
  {"id":"s_work_han_thu_24_57","chapterId":"ch_work_han_thu_24","textTraditional":"〔五〕　孟康曰：「棣謂通意也。」師古曰：「棣音替。」","sentenceOrder":57},
  {"id":"s_work_han_thu_24_58","chapterId":"ch_work_han_thu_24","textTraditional":"〔六〕　師古曰：「宓讀與伏同。」","sentenceOrder":58},
  {"id":"s_work_han_thu_24_59","chapterId":"ch_work_han_thu_24","textTraditional":"〔七〕　師古曰：「此說卦之辭。」","sentenceOrder":59},
  {"id":"s_work_han_thu_24_60","chapterId":"ch_work_han_thu_24","textTraditional":"〔八〕　師古曰：「此上繫之辭。」","sentenceOrder":60},
  {"id":"s_work_han_thu_24_61","chapterId":"ch_work_han_thu_24","textTraditional":"〔九〕　師古曰：「此泰卦象辭也。后，君也，謂王者也。左右，助也。左讀曰佐。右讀曰佑。」","sentenceOrder":61},
  {"id":"s_work_han_thu_24_62","chapterId":"ch_work_han_thu_24","textTraditional":"其於三正也，黃鐘子為天正，〔一〕林鐘未之衝丑為地正，太族寅為人正。三正正始，是以地正適其始紐於陽東北丑位。易曰「東北喪朋，乃終有慶」，〔二〕答應之道也。及黃鐘為宮，則太族、姑洗、林鐘、南呂皆以正聲應，無有忽微，〔三〕不復與它律為役者，同心一統之義也。非黃鐘而它律，雖當其月自宮者，則其和應之律有空積忽微，〔四〕不得其正。此黃鐘至尊，亡與並也。","sentenceOrder":62},
  {"id":"s_work_han_thu_24_63","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　師古曰：「正音之成反。下皆類此。」","sentenceOrder":63},
  {"id":"s_work_han_thu_24_64","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　孟康曰：「未在西南，陽也，陰而入陽，為失其類也。」師古曰：「此坤卦彖辭。」","sentenceOrder":64},
  {"id":"s_work_han_thu_24_65","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　孟康曰：「忽微，若有若無，細於髮者也。謂正聲無有殘分也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_24_66","chapterId":"ch_work_han_thu_24","textTraditional":"〔四〕　孟康曰：「十二月之氣各以其月之律為宮，非五音之正，則聲有高下差降也。空積，若鄭氏分一寸為數千。」","sentenceOrder":66},
  {"id":"s_work_han_thu_24_67","chapterId":"ch_work_han_thu_24","textTraditional":"易曰：「參天兩地而倚數。」〔一〕天之數始於一，終於二十有五。其義紀之以三，故置一得三，又二十五分之六，凡二十五置，終天之數，得八十一，以天地五位之合終於十者乘之，為八百一十分，應曆一統〔二〕千五百三十九歲之章數，黃鐘之實也。繇此之義〔三〕，起十二律之周徑。〔四〕地之數始於二，終於三十。其義紀之以兩，故置一得二，凡三十置，終地之數，得六十，以地中數六乘之，為三百六十分，當期之日，林鐘之實。〔五〕人者，繼天順地，序氣成物，統八卦，調八風，理八政，正八節，諧八音，舞八佾，監八方，被八荒，以終天地之功，故八八六十四。其義極天地之變，以天地五位之合終於十者乘之，為六百四十分，以應六十四卦，大族之實也。〔六〕書曰：「天功人其代之。」〔七〕天兼地，人則天，故以五位之合乘焉，「唯天為大，唯堯則之」之象也。〔八〕地以中數乘者，陰道理內，在中餽之象也。〔九〕三統相通，故黃鐘、林鐘、太族律長皆全寸而亡餘分也。","sentenceOrder":67},
  {"id":"s_work_han_thu_24_68","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　師古曰：「易說卦之辭也。倚，立也。參謂奇也，兩謂耦也。七九陽數，六八陰數。」","sentenceOrder":68},
  {"id":"s_work_han_thu_24_69","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　孟康曰：「十九歲為一章，一統凡八十一章。」","sentenceOrder":69},
  {"id":"s_work_han_thu_24_70","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　師古曰：「繇讀（為）〔與〕由同。由，用也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_24_71","chapterId":"ch_work_han_thu_24","textTraditional":"〔四〕　孟康曰：「律孔徑三分，參天之數也；圍九分，終天之數也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_24_72","chapterId":"ch_work_han_thu_24","textTraditional":"〔五〕　孟康曰：「林鐘長六寸，圍六分。以圍乘長，得積三百六十分也。」師古曰：「期音基。謂十二月為一期也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_24_73","chapterId":"ch_work_han_thu_24","textTraditional":"〔六〕　孟康曰：「大族長八寸，圍八分，為積六百四十分也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_24_74","chapterId":"ch_work_han_thu_24","textTraditional":"〔七〕　師古曰：「虞書咎繇謨也。言聖人稟天造化之功代而行之。」","sentenceOrder":74},
  {"id":"s_work_han_thu_24_75","chapterId":"ch_work_han_thu_24","textTraditional":"〔八〕　師古曰：「則，法也。論語稱孔子曰『大哉堯之為君也，唯天為大，唯堯則之』，美帝堯能法天而行化。」","sentenceOrder":75},
  {"id":"s_work_han_thu_24_76","chapterId":"ch_work_han_thu_24","textTraditional":"〔九〕　師古曰：「餽字與饋同。易家人卦六二爻辭曰『无攸遂，在中饋』，言婦人之道，取象於陰，無所必遂，但居中主饋食而已，故云然。」","sentenceOrder":76},
  {"id":"s_work_han_thu_24_77","chapterId":"ch_work_han_thu_24","textTraditional":"天之中數五，地之中數六，而二者為合。六為虛，五為聲，周流於六虛。虛者，爻律夫陰陽，登降運行，列為十二，而律呂和矣。太極元氣，函三為一。〔一〕極，中也。元，始也。行於十二辰，始動於子。參之於丑，得三。又參之於寅，得九。又參之於卯，得二十七。又參之於辰，得八十一。又參之於巳，得二百四十三。又參之於午，得七百二十九。又參之於未，得二千一百八十七。又參之於申，得六千五百六十一。又參之於酉，得萬九千六百八十三。又參之於戌，得五萬九千四十九。又參之於亥，得十七萬七千一百四十七。此陰陽合德，氣鐘於子，化生萬物者也。故孳萌於子，紐牙於丑，引達於寅，冒茆於卯，〔二〕振美於辰，已盛於巳，咢布於午，〔三〕昧薆於未，〔四〕申堅於申，留孰於酉，畢入於戌，該閡於亥。出甲於甲，奮軋於乙，〔五〕明炳於丙，大盛於丁，豐楙於戊，理紀於己，斂更於庚，悉新於辛，懷任於壬，陳揆於癸。故陰陽之施化，萬物之終始，既類旅於律呂，又經歷於日辰，而變化之情可見矣。","sentenceOrder":77},
  {"id":"s_work_han_thu_24_78","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　孟康曰：「元氣始起於子，未分之時，天地人混合為一，故子數獨一也。」師古曰：「函讀與含同。後皆類此。」","sentenceOrder":78},
  {"id":"s_work_han_thu_24_79","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　師古曰：「茆謂叢生也，音莫保反。」","sentenceOrder":79},
  {"id":"s_work_han_thu_24_80","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　蘇林曰：「咢音愕。」","sentenceOrder":80},
  {"id":"s_work_han_thu_24_81","chapterId":"ch_work_han_thu_24","textTraditional":"〔四〕　師古曰：「薆，蔽也，音愛。」","sentenceOrder":81},
  {"id":"s_work_han_thu_24_82","chapterId":"ch_work_han_thu_24","textTraditional":"〔五〕　師古曰：「軋音於黠反。」","sentenceOrder":82},
  {"id":"s_work_han_thu_24_83","chapterId":"ch_work_han_thu_24","textTraditional":"玉衡杓建，天之綱也；〔一〕日月初（纏）〔躔〕，星之紀也。〔二〕綱紀之交，以原始造設，合樂用焉。律呂唱和，以育生成化，歌奏用焉。指顧取象，然後陰陽萬物靡不條鬯該成。〔三〕故以成之數忖該之積，〔四〕如法為一寸，則黃鐘之長也。〔五〕參分損一，下生林鐘。〔六〕參分林鐘益一，上生太族。參分太族損一，下生南呂。參分南呂益一，上生姑洗。參分姑洗損一，下生應鐘。參分應鐘益一，上生蕤賓。參分蕤賓損一，下生大呂。參分大呂益一，上生夷則。參分夷則損一，下生夾鐘。參分夾鐘益一，上生亡射。參分亡射損一，下生中呂。陰陽相生，自黃鐘始而左旋，八八為伍。〔七〕其法皆用銅。職在大樂，太常掌之。","sentenceOrder":83},
  {"id":"s_work_han_thu_24_84","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　如淳曰：「杓音猋，斗端星也。」孟康曰：「斗在天中，周制四方，猶宮聲處中，為四聲綱也。」師古曰：「杓音必遙反。」","sentenceOrder":84},
  {"id":"s_work_han_thu_24_85","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　孟康曰：「（纏）〔躔〕，舍也。二十八舍列在四方，日月行焉，起於星紀，而又周之，猶四聲為宮紀也。」晉灼曰：「下言斗綱之端連貫營室，織女之紀指牽牛之初，以紀日月，故曰星紀。五星起其初，日月起其中。是謂天之綱紀也。」師古曰：「躔，踐也，音直連反。」","sentenceOrder":85},
  {"id":"s_work_han_thu_24_86","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　師古曰：「條，達也。鬯與暢同。」","sentenceOrder":86},
  {"id":"s_work_han_thu_24_87","chapterId":"ch_work_han_thu_24","textTraditional":"〔四〕　孟康曰：「成之數者，謂黃鐘之法數。該之積，為黃鐘變生十二辰積實之數也。忖，除也。言以法數除積得九寸，即黃鐘之長也。言該者，該眾律之數也。」師古曰：「忖音千本反。」","sentenceOrder":87},
  {"id":"s_work_han_thu_24_88","chapterId":"ch_work_han_thu_24","textTraditional":"〔五〕　孟康曰：「得一寸，則所謂得九寸也。言一者，張法辭。」","sentenceOrder":88},
  {"id":"s_work_han_thu_24_89","chapterId":"ch_work_han_thu_24","textTraditional":"〔六〕　張晏曰：「黃鐘長九寸，以二乘九得十八，以三除之，得林鐘六寸。其法率如此，推當算乃解。」晉灼曰：「蔡邕律曆記『凡陽生陰曰下，陰生陽曰上』也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_24_90","chapterId":"ch_work_han_thu_24","textTraditional":"〔七〕　孟康曰：「從子數辰至未得八，下生林鐘。數未至寅得八，上生太族。律上下相生，皆以此為率。伍，耦也，八八為耦。」","sentenceOrder":90},
  {"id":"s_work_han_thu_24_91","chapterId":"ch_work_han_thu_24","textTraditional":"度者，分、寸、尺、丈、引也，所以度長短也。〔一〕本起黃鐘之長。以子穀秬黍中者，〔二〕一黍之廣，度之九十分，黃鐘之長。一為一分，十分為寸，十寸為尺，十尺為丈，十丈為引，而五度審矣。其法用銅，高一寸，廣二寸，長一丈，而分寸尺丈存焉。用竹為引，高一分，廣六分，長十丈，其方法矩，高廣之數，陰陽之象也〔三〕。分者，自三微而成著，可分別也。寸者，忖也。尺者，蒦也〔四〕。丈者，張也。引者，信也。〔五〕夫度者，別於分，忖於寸，蒦於尺，張於丈，信於引。引者，信天下也。職在內官，〔六〕廷尉掌之。〔七〕","sentenceOrder":91},
  {"id":"s_work_han_thu_24_92","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　師古曰：「度音大各反。下皆類此。」","sentenceOrder":92},
  {"id":"s_work_han_thu_24_93","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　孟康曰：「子北方，北方黑，謂黑黍也。」師古曰：「此說非也。子穀猶言穀子耳，秬即黑黍，無取北方為號。中者，不大不小也。言取黑黍穀子大小中者，率為分寸也。秬音鉅。」","sentenceOrder":93},
  {"id":"s_work_han_thu_24_94","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　孟康曰：「高一分，廣六分。一為陽，六為陰也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_24_95","chapterId":"ch_work_han_thu_24","textTraditional":"〔四〕　師古曰：「蒦音約。」","sentenceOrder":95},
  {"id":"s_work_han_thu_24_96","chapterId":"ch_work_han_thu_24","textTraditional":"〔五〕　師古曰：「信讀曰伸，言其長。」","sentenceOrder":96},
  {"id":"s_work_han_thu_24_97","chapterId":"ch_work_han_thu_24","textTraditional":"〔六〕　師古曰：「內官，署名也。百官表云『內官長丞，初屬少府，中屬主爵，後屬宗正』。」","sentenceOrder":97},
  {"id":"s_work_han_thu_24_98","chapterId":"ch_work_han_thu_24","textTraditional":"〔七〕　師古曰：「法度所起，故屬廷尉也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_24_99","chapterId":"ch_work_han_thu_24","textTraditional":"量者，龠、合、升、斗、斛也，〔一〕所以量多少也。〔二〕本起於黃鐘之龠，用度數審其容，〔三〕以子穀秬黍中者千有二百實其龠，以井水準其概。〔四〕合龠為合，十合為升，十升為斗，十斗為斛，而五量嘉矣。〔五〕其法用銅，方尺而圜其外，旁有庣焉。〔六〕其上為斛，其下為斗。〔七〕左耳為升，右耳為合龠。其狀似爵，以縻爵祿。〔八〕上三下二，參天兩地，圜而函方，左一右二，陰陽之象也。其圜象規，其重二鈞，備氣物之數，合萬有一千五百二十。〔九〕聲中黃鐘，始於黃鐘而反覆焉，〔一０〕君制器之象也。龠者，黃鐘律之實也，躍微動氣而生物也。合者，合龠之量也。升者，登合之量也。斗者，聚升之量也。斛者，角斗平多少之量也。夫量者，躍於龠，合於合，登於升，聚於斗，角於斛也。職在太倉，大司農掌之。〔一一〕","sentenceOrder":99},
  {"id":"s_work_han_thu_24_100","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　師古曰：「龠音籥。合音閤。」","sentenceOrder":100},
  {"id":"s_work_han_thu_24_101","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　師古曰：「量音力張反。」","sentenceOrder":101},
  {"id":"s_work_han_thu_24_102","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　師古曰：「因度以生量也。其容，謂其中所容受之多少也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_24_103","chapterId":"ch_work_han_thu_24","textTraditional":"〔四〕　孟康曰：「概欲其直，故以水平之。井水清，清則平也。」師古曰：「概所以概平斗斛之上者也，音工代反，又音工內反。」","sentenceOrder":103},
  {"id":"s_work_han_thu_24_104","chapterId":"ch_work_han_thu_24","textTraditional":"〔五〕　師古曰：「嘉，善也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_24_105","chapterId":"ch_work_han_thu_24","textTraditional":"〔六〕　鄭氏曰：「庣音條桑之條。庣，過也。算方一尺，所受一斛，過九氂五豪，然後成斛。今尚方有王莽時銅斛，制盡與此同。」師古曰：「庣，不滿之處也，音吐彫反。」","sentenceOrder":105},
  {"id":"s_work_han_thu_24_106","chapterId":"ch_work_han_thu_24","textTraditional":"〔七〕　孟康曰：「其上謂仰斛也，其下謂覆斛之底，受一斗。」","sentenceOrder":106},
  {"id":"s_work_han_thu_24_107","chapterId":"ch_work_han_thu_24","textTraditional":"〔八〕　晉灼曰：「縻，散也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_24_108","chapterId":"ch_work_han_thu_24","textTraditional":"〔九〕　孟康曰：「三十斤為鈞，鈞萬一千五百二十銖。」","sentenceOrder":108},
  {"id":"s_work_han_thu_24_109","chapterId":"ch_work_han_thu_24","textTraditional":"〔一０〕孟康曰：「反斛聲中黃鐘，覆斛亦中黃鐘之宮，宮為君也。」臣瓚曰：「仰斛受一斛，覆斛受一斗，故曰反覆焉。」師古曰：「覆音芳目反。」","sentenceOrder":109},
  {"id":"s_work_han_thu_24_110","chapterId":"ch_work_han_thu_24","textTraditional":"〔一一〕師古曰：「米粟之量，故在太倉也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_24_111","chapterId":"ch_work_han_thu_24","textTraditional":"衡權者，衡，平也，權，重也，衡所以任權而均物平輕重也。其道如底，〔一〕以見準之正，繩之直，左旋見規，右折見矩。其在天也，佐助旋機，斟酌建指，以齊七政，〔二〕故曰玉衡。論語云：「立則見其參於前也，〔三〕在車則見其倚於衡也。」又曰：「齊之以禮。」此衡在前居南方之義也。","sentenceOrder":111},
  {"id":"s_work_han_thu_24_112","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　師古曰：「底，平也，謂以底石厲物令平齊也。底音指。」","sentenceOrder":112},
  {"id":"s_work_han_thu_24_113","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　師古曰：「七政，日、月、五星也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_24_114","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　孟康曰：「權、衡、量，三等為參。」","sentenceOrder":114},
  {"id":"s_work_han_thu_24_115","chapterId":"ch_work_han_thu_24","textTraditional":"權者，銖、兩、斤、鈞、石也，所以稱物平施，知輕重也。本起於黃鐘之重。一龠容千二百黍，重十二銖，兩之為兩。二十四銖為兩。十六兩為斤。三十斤為鈞。四鈞為石。忖為十八，易十有八變之象也。〔一〕五權之制，以義立之，以物鈞之，其餘小大之差，以輕重為宜。圜而環之，令之肉倍好者，〔二〕周旋無端，終而復始，無窮已也。銖者，物繇忽微始，至於成著，可殊異也。〔三〕兩者，兩黃鐘律之重也。〔四〕二十四銖而成兩者，二十四氣之象也。斤者，明也，三百八十四銖，易二篇之爻，陰陽變動之象也。十六兩成斤者，四時乘四方之象也。鈞者，均也，陽施其氣，陰化其物，皆得其成就平均也。權與物均，重萬一千五百二十銖，當萬物之象也。四百八十兩者，六旬行八節之象也。〔五〕三十斤成鈞者，一月之象也。石者，大也，權之大者也。始於銖，兩於兩，明於斤，均於鈞，終於石，物終石大也。四鈞為石者，四時之象也。重百二十斤者，十二月之象也。終於十二辰而復於子，黃鐘之象也。〔六〕千九百二十兩者，陰陽之數也。三百八十四爻，五行之象也。四萬六千八十銖者，萬一千五百二十物歷四時之象也。而歲功成就，五權謹矣。","sentenceOrder":115},
  {"id":"s_work_han_thu_24_116","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　孟康曰：「忖，度也，度其義有十八也。黃鐘、龠、銖、兩、鈞、斤、石凡七，與下十一象為十八也。」張晏曰：「象易三揲蓍而成一爻，十八變具六爻而成卦。」","sentenceOrder":116},
  {"id":"s_work_han_thu_24_117","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　孟康曰：「謂為（鐘）〔錘〕之形如環也。」如淳曰：「體為肉，孔為好。」師古曰：「錘者，稱之權也，音直垂反，又音直睡反。」","sentenceOrder":117},
  {"id":"s_work_han_thu_24_118","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　師古曰：「繇讀與由同。由，從也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_24_119","chapterId":"ch_work_han_thu_24","textTraditional":"〔四〕　李奇曰：「黃鐘之管重十二銖，兩十二得二十四也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_24_120","chapterId":"ch_work_han_thu_24","textTraditional":"〔五〕　孟康曰：「六甲為六旬，一歲有八節，六甲周行成歲，以六乘八節得之。」","sentenceOrder":120},
  {"id":"s_work_han_thu_24_121","chapterId":"ch_work_han_thu_24","textTraditional":"〔六〕　孟康曰：「稱之數始於銖，終於石。石重百二十斤，象十二月。銖之重本取於子。律，黃鐘一龠容千二百黍，為十二銖，故曰復於子，黃鐘之象也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_24_122","chapterId":"ch_work_han_thu_24","textTraditional":"權與物鈞而生衡，〔一〕衡運生規，規圜生矩，矩方生繩，繩直生準，〔二〕準正則平衡而鈞權矣。是為五則。規者，所以規圜器械，令得其類也。矩者，所以矩方器械，令不失其形也。規矩相須，陰陽位序，圜方乃成。準者，所以揆平取正也。繩者，上下端直，經緯四通也。準繩連體，衡權合德，百工繇焉，以定法式，〔三〕輔弼執玉，以翼天子。〔四〕詩云：「尹氏大師，秉國之鈞，四方是維，天子是毗，俾民不迷。」〔五〕咸有五象，其義一也。以陰陽言之，大陰者，北方。北，伏也，陽氣伏於下，於時為冬。冬，終也，物終臧，乃可稱。水潤下。知者謀，謀者重，故為權也。大陽者，南方。南，任也，陽氣任養物，於時為夏。夏，假也，物假大，乃宣平。火炎上。禮者齊，齊者平，故為衡也。少陰者，西方。西，遷也，陰氣遷落物，於時為秋。秋，{〈米隹〉〈韋火〉}也，〔六〕物{〈米隹〉〈韋火〉}斂，乃成孰。金從革，改更也。義者成，成者方，故為矩也。少陽者，東方。東，動也，陽氣動物，於時為春。春，蠢也，物蠢生，乃動運。木曲直。仁者生，生者圜，故為規也。中央者，陰陽之內，四方之中，經緯通達，乃能端直，於時為四季。土稼嗇蕃息。〔七〕信者誠，誠者直，故為繩也。五則揆物，有輕重圜方平直陰陽之義，四方四時之體，五常五行之象。厥法有品，各順其方而應其行。職在大行，鴻臚掌之。〔八〕","sentenceOrder":122},
  {"id":"s_work_han_thu_24_123","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　孟康曰：「謂錘與物鈞，所稱適停，則衡平也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_24_124","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　韋昭曰：「立準以望繩，以水為平。」","sentenceOrder":124},
  {"id":"s_work_han_thu_24_125","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　師古曰：「繇讀與由同。由，用也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_24_126","chapterId":"ch_work_han_thu_24","textTraditional":"〔四〕　師古曰：「翼，助也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_24_127","chapterId":"ch_work_han_thu_24","textTraditional":"〔五〕　師古曰：「小雅節南山之詩也。言尹氏居太師之官，執持國之權量，維制四方，輔翼天子，使下無迷惑也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_24_128","chapterId":"ch_work_han_thu_24","textTraditional":"〔六〕　師古曰：「{〈米隹〉〈韋火〉}音子由反。」","sentenceOrder":128},
  {"id":"s_work_han_thu_24_129","chapterId":"ch_work_han_thu_24","textTraditional":"〔七〕　師古曰：「蕃，多也。息，生也。蕃音扶元反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_24_130","chapterId":"ch_work_han_thu_24","textTraditional":"〔八〕　師古曰：「平均曲直，齊一遠近，故在鴻臚。」","sentenceOrder":130},
  {"id":"s_work_han_thu_24_131","chapterId":"ch_work_han_thu_24","textTraditional":"書曰：「予欲聞六律、五聲、八音、七始詠，以出內五言，女聽。」〔一〕予者，帝舜也。言以律呂和五聲，施之八音，合之成樂。七者，天地四時人之始也。順以歌詠五常之言，聽之則順乎天地，序乎四時，應人倫，本陰陽，原情性，風之以德，感之以樂，〔二〕莫不同乎一。唯聖人為能同天下之意，故帝舜欲聞之也。今廣延群儒，博謀講道，修明舊典，同律，審度，嘉量，平衡，鈞權，正準，直繩，立于五則，備數和聲，以利兆民，貞天下於一，同海內之歸。〔三〕凡律度量衡用銅者，名自名也，〔四〕所以同天下，齊風俗也。銅為物之至精，不為燥溼寒暑變其節，不為風雨暴露改其形，介然有常，有似於士君子之行，〔五〕是以用銅也。用竹為引者，事之宜也。〔六〕","sentenceOrder":131},
  {"id":"s_work_han_thu_24_132","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　師古曰：「虞書益稷篇所載舜與禹言。」","sentenceOrder":132},
  {"id":"s_work_han_thu_24_133","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　師古曰：「以德化之，以樂動之。詩序曰『上以風化下』。」","sentenceOrder":133},
  {"id":"s_work_han_thu_24_134","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　師古曰：「貞，正也。易下繫之辭曰『天下之動貞夫一者也』，言皆以一為正也。又曰『天下同歸而殊塗，一致而百慮』，言途雖殊其歸則同，慮雖百其致則一也，故志引之云爾。」","sentenceOrder":134},
  {"id":"s_work_han_thu_24_135","chapterId":"ch_work_han_thu_24","textTraditional":"〔四〕　師古曰：「取銅之名，以合於同也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_24_136","chapterId":"ch_work_han_thu_24","textTraditional":"〔五〕　師古曰：「介然，特異之意。」","sentenceOrder":136},
  {"id":"s_work_han_thu_24_137","chapterId":"ch_work_han_thu_24","textTraditional":"〔六〕　李奇曰：「引長十丈，高一分，廣六分，唯竹篾柔而堅為宜耳。」","sentenceOrder":137},
  {"id":"s_work_han_thu_24_138","chapterId":"ch_work_han_thu_24","textTraditional":"曆數之起上矣。傳述顓頊命南正重司天，火正黎司地，〔一〕其後三苗亂德，二官咸廢，〔二〕而閏餘乖次，〔三〕孟陬殄滅，〔四〕攝提失方。〔五〕堯復育重、黎之後，使纂其業，故書曰：「乃命羲、和，欽若昊天，曆象日月星辰，敬授民時。」「歲三百有六旬有六日，以閏月定四時成歲，允釐百官，眾功皆美。」〔六〕其後以授舜曰：「咨爾舜，天之曆數在爾躬。」「舜亦以命禹。」〔七〕至周武王訪箕子，〔八〕箕子言大法九章，而五紀明曆法。〔九〕故自殷周，皆創業改制，咸正曆紀，服色從之，順其時氣，以應天道。三代既沒，五伯之末史官喪紀，疇人子弟分散，〔一０〕或在夷狄，故其所記，有黃帝、顓頊、夏、殷、周及魯曆。戰國擾攘，秦兼天下，未皇暇也，亦頗推五勝，〔一一〕而自以為獲水德，乃以十月為正，色上黑。〔一二〕","sentenceOrder":138},
  {"id":"s_work_han_thu_24_139","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　臣瓚曰：「南正司天，則北正當司地，不得言火正也。古文火字與北相似，故遂誤耳。」師古曰：「此說非也。班固幽通賦云『玄黎醇耀於高辛』，是則黎為火正也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_24_140","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　師古曰：「三苗，國名，縉雲氏之後為諸侯者，即饕餮也。二官，重、黎也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_24_141","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　孟康曰：「以歲之餘日為閏，故曰閏餘。次，十二次也。史推曆失閏，則斗建與月名錯也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_24_142","chapterId":"ch_work_han_thu_24","textTraditional":"〔四〕　孟康曰：「正月為孟陬。曆紀廢絕，閏餘乖錯，不與正歲相值，謂之殄滅也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_24_143","chapterId":"ch_work_han_thu_24","textTraditional":"〔五〕　孟康曰：「攝提，星名，隨斗杓所指建十二月，若曆誤，春三月當指辰而乃指巳，是為失方也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_24_144","chapterId":"ch_work_han_thu_24","textTraditional":"〔六〕　師古曰：「此皆虞書堯典之辭也。欽，敬；若，順也。昊天，言天氣廣大也。星，四方之中星也。辰，日月所會也。羲氏、和氏，重、黎之後，以其繼掌天地，故堯命之，使敬順昊天，曆象星辰之分節，敬記天時，以授下人也。匝四時凡三百六十六日，而定一歲。十二月月三十日，正三百六十日，則餘六日矣。又除小月六日，是為歲有餘十二日，未盈三歲，便得一月，則置閏焉，以定四時之氣節，成一歲之曆象，則能信理百官，眾功皆美也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_24_145","chapterId":"ch_work_han_thu_24","textTraditional":"〔七〕　師古曰：「事見論語堯曰篇。」","sentenceOrder":145},
  {"id":"s_work_han_thu_24_146","chapterId":"ch_work_han_thu_24","textTraditional":"〔八〕　師古曰：「訪箕子，謂滅殷之後。」","sentenceOrder":146},
  {"id":"s_work_han_thu_24_147","chapterId":"ch_work_han_thu_24","textTraditional":"〔九〕　孟康曰：「歲月日星辰，是謂五紀也。」師古曰：「大法九章即洪範九疇也。其四曰協用五紀也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_24_148","chapterId":"ch_work_han_thu_24","textTraditional":"〔一０〕李奇曰：「同類之人俱明曆者也。」如淳曰：「家業世世相傳為疇。」師古曰：「如說是也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_24_149","chapterId":"ch_work_han_thu_24","textTraditional":"〔一一〕孟康曰：「五行相勝，秦以周為火，用水勝之。」","sentenceOrder":149},
  {"id":"s_work_han_thu_24_150","chapterId":"ch_work_han_thu_24","textTraditional":"〔一二〕師古曰：「獲水德，謂有黑龍之瑞。」","sentenceOrder":150},
  {"id":"s_work_han_thu_24_151","chapterId":"ch_work_han_thu_24","textTraditional":"漢興，方綱紀大基，庶事草創，襲秦正朔。以北平侯張蒼言，用顓頊曆，比於六曆，疏闊中最為微近。然正朔服色，未睹其真，而朔晦月見，弦望滿虧，多非是。","sentenceOrder":151},
  {"id":"s_work_han_thu_24_152","chapterId":"ch_work_han_thu_24","textTraditional":"至武帝元封七年，漢興百二歲矣，大中大夫公孫卿、壺遂、太史令司馬遷等言「曆紀壞廢，宜改正朔」。是時御史大夫兒寬明經術，〔一〕上乃詔寬曰：「與博士共議，今宜何以為正朔？服色何上？」寬與博士賜等議，皆曰：「帝王必改正朔，易服色，所以明受命於天也。創業變改，制不相復，〔二〕推傳序文，則今夏時也。臣等聞學褊陋，不能明。陛下躬聖發憤，昭配天地，〔三〕臣愚以為三統之制，後聖復前聖者，二代在前也。今二代之統絕而不序矣，唯陛下發聖德，宣考天地四時之極，則順陰陽以定大明之制，為萬世則。」於是乃詔御史曰：「乃者有司言曆未定，廣延宣問，以考星度，未能讎也。〔四〕蓋聞古者黃帝合而不死，名察發斂，定清濁，起五部，建氣物分數。〔五〕然則上矣。書缺樂弛，朕甚難之。〔六〕依違以惟，未能修明。〔七〕其以七年為元年。」〔八〕遂詔卿、遂、遷與侍郎尊、大典星射姓等〔九〕議造漢曆。乃定東西，立晷儀，下漏刻，以追二十八宿相距於四方，舉終以定朔晦分至，躔離弦望。〔一０〕乃以前曆上元泰初四千六百一十七歲，至於元封七年，復得閼逢攝提格之歲，中冬〔一一〕十一月甲子朔旦冬至，日月在建星，〔一二〕太歲在子，已得太初本星度新正。姓等奏不能為算，〔一三〕願募治曆者，更造密度，各自增減，以造漢太初曆。乃選治曆鄧平及長樂司馬可、酒泉候宜君、〔一四〕侍郎尊及與民間治曆者，凡二十餘人，方士唐都、巴郡落下閎與焉。〔一五〕都分天部，〔一六〕而閎運算轉曆。其法以律起曆，曰：「律容一龠，積八十一寸，則一日之分也。〔一七〕與長相終。律長九寸，百七十一分而終復。〔一八〕三復而得甲子。夫律陰陽九六，爻象所從出也。故黃鐘紀元氣之謂律。律，法也，莫不取法焉。」與鄧平所治同。於是皆觀新星度、日月行，更以算推，如閎、平法。法，一月之日二十九日八十一分日之四十三。先藉半日，名曰陽曆；不藉，名曰陰曆。所謂陽曆者，先朔月生；陰曆者，朔而後月乃生。平曰：「陽曆朔皆先旦月生，以朝諸侯王群臣便。」乃詔遷用鄧平所造八十一分律曆，罷廢尤疏遠者十七家，復使校曆律昏明。宦者淳于陵渠復覆太初曆晦朔弦望，皆最密，日月如合璧，五星如連珠。〔一九〕陵渠奏狀，遂用鄧平曆，以平為太史丞。","sentenceOrder":152},
  {"id":"s_work_han_thu_24_153","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　師古曰：「兒音五奚反。」","sentenceOrder":153},
  {"id":"s_work_han_thu_24_154","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　師古曰：「復，重也，因也，音扶目反。次下亦同。」","sentenceOrder":154},
  {"id":"s_work_han_thu_24_155","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　師古曰：「躬聖者，言身有聖德也。發憤，謂念正朔未定也。昭，明也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_24_156","chapterId":"ch_work_han_thu_24","textTraditional":"〔四〕　師古曰：「讎，相當。」","sentenceOrder":156},
  {"id":"s_work_han_thu_24_157","chapterId":"ch_work_han_thu_24","textTraditional":"〔五〕　應劭曰：「言黃帝造曆得仙，名節會，察寒暑，致啟分，發斂至，定清濁，起五部。五部，金、木、水、火、土也。建氣物分數，皆敘曆之意也。」孟康曰：「合，作也。黃帝作曆，曆終而復始，無窮已也，故曰不死。名春夏為發，秋冬為斂。清濁，謂律聲之清濁也。五部，謂五行也。天有四時，分為五行也。氣，二十四氣也。物，萬物也。分，曆數之分也。」晉灼曰：「蔡邕天文志『渾天名察發斂，以行日月，以步五緯』。」臣瓚曰：「黃帝聖德，與神靈合契，升龍登仙，故曰合而不死。題名宿度，候察進退。史記曰『名察宿度』，謂三辰之度，吉凶之驗也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_24_158","chapterId":"ch_work_han_thu_24","textTraditional":"〔六〕　師古曰：「弛，廢也。音式爾反。」","sentenceOrder":158},
  {"id":"s_work_han_thu_24_159","chapterId":"ch_work_han_thu_24","textTraditional":"〔七〕　師古曰：「依違，不決之意也。惟，思也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_24_160","chapterId":"ch_work_han_thu_24","textTraditional":"〔八〕　李奇曰：「改元封七年為太初元年。」","sentenceOrder":160},
  {"id":"s_work_han_thu_24_161","chapterId":"ch_work_han_thu_24","textTraditional":"〔九〕　師古曰：「姓射，名姓也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_24_162","chapterId":"ch_work_han_thu_24","textTraditional":"〔一０〕應劭曰：「躔，徑也。離，遠也。」臣瓚曰：「案離，歷也，日月之所歷也。」鄧展曰：「日月踐歷度次。」","sentenceOrder":162},
  {"id":"s_work_han_thu_24_163","chapterId":"ch_work_han_thu_24","textTraditional":"〔一一〕孟康曰：「言復得者，上元泰初時亦是閼逢之歲，歲在甲曰閼逢，在寅曰攝提格，此為甲寅之歲也。」師古曰：「中讀曰仲。」","sentenceOrder":163},
  {"id":"s_work_han_thu_24_164","chapterId":"ch_work_han_thu_24","textTraditional":"〔一二〕李奇曰：「古以建星為宿，今以牽牛為宿。」孟康曰：「建星在牽牛間。」晉灼曰：「賈逵論太初曆冬至日在牽牛初者，牽牛中星也。古曆皆在建星。建星即斗星也。太初曆四分法在斗二十六度。史官舊法，冬夏至常不及太初曆五度。四分法在斗二十一度，與行事候法天度相應。」","sentenceOrder":164},
  {"id":"s_work_han_thu_24_165","chapterId":"ch_work_han_thu_24","textTraditional":"〔一三〕師古曰：「姓即射姓也。」","sentenceOrder":165},
  {"id":"s_work_han_thu_24_166","chapterId":"ch_work_han_thu_24","textTraditional":"〔一四〕師古曰：「可者司馬之名也。宜君亦候之名也。候，官號也。故曰東南一尉，西北一候。」","sentenceOrder":166},
  {"id":"s_work_han_thu_24_167","chapterId":"ch_work_han_thu_24","textTraditional":"〔一五〕晉灼曰：「三人姓名也。史記曆書『唐都分天部，而巴郡落下閎運算推曆』。」師古曰：「姓唐，名都，方術之士也。姓落下名閎，巴郡人也。都與閎凡二人，言三人，非也。與讀曰豫。」","sentenceOrder":167},
  {"id":"s_work_han_thu_24_168","chapterId":"ch_work_han_thu_24","textTraditional":"〔一六〕孟康曰：「謂分部二十八宿為距度。」","sentenceOrder":168},
  {"id":"s_work_han_thu_24_169","chapterId":"ch_work_han_thu_24","textTraditional":"〔一七〕孟康曰：「黃鐘律長九寸，圍九分，以圍乘長，得積八十一寸也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_24_170","chapterId":"ch_work_han_thu_24","textTraditional":"〔一八〕師古曰：「復音扶目反。」","sentenceOrder":170},
  {"id":"s_work_han_thu_24_171","chapterId":"ch_work_han_thu_24","textTraditional":"〔一九〕孟康曰：「謂太初上元甲子夜半朔旦冬至時，七曜皆會聚斗、牽牛分度，夜盡如合璧連珠也。」師古曰：「言其應候不差也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_24_172","chapterId":"ch_work_han_thu_24","textTraditional":"後二十七年，元鳳三年，太史令張壽王上書言：「曆者天地之大紀，上帝所為。傳黃帝調律曆，漢元年以來用之。今陰陽不調，宜更曆之過也。」〔一〕詔下主曆使者鮮于妄人詰問，壽王不服。妄人請與治曆大司農中丞麻光等二十餘人雜候日月晦朔弦望、八節二十四氣，鈞校諸曆用狀。奏可。詔與丞相、御史、大將軍、右將軍史各一人雜候上林清臺，課諸曆疏密，凡十一家。以元鳳三年十一月朔旦冬至，盡五年十二月，各有第。壽王課疏遠。案漢元年不用黃帝調曆，壽王非漢曆，逆天道，非所宜言，大不敬。有詔勿劾。復候，盡六年。太初曆第一，即墨徐萬且、長安徐禹治太初曆亦第一。〔二〕壽王及待詔李信治黃帝調曆，課皆疏闊，又言黃帝至元鳳三年六千餘歲。丞相屬寶、長安單安國、安陵桮育治終始，〔三〕言黃帝以來三千六百二十九歲，不與壽王合。壽王又移帝王錄，舜、禹年歲不合人年。壽王言化益為天子代禹，〔四〕驪山女亦為天子，在殷周間，皆不合經術。壽王曆乃太史官殷曆也。壽王猥曰安得五家曆，〔五〕又妄言太初曆虧四分日之三，去小餘七百五分，以故陰陽不調，謂之亂世。劾壽王吏八百石，古之大夫，服儒衣，誦不詳之辭，作祅言欲亂制度，不道。奏可。壽王候課，比三年下，〔六〕終不服。再劾死，更赦勿劾，〔七〕遂不更言，誹謗益甚，竟以下吏。故曆本之驗在於天，自漢曆初起，盡元鳳六年，三十六歲，而是非堅定。","sentenceOrder":172},
  {"id":"s_work_han_thu_24_173","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　師古曰：「更，改也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_24_174","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　師古曰：「且音子余反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_24_175","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　蘇林曰：「桮音布回反。」師古曰：「姓桮，名育也。單音善。」","sentenceOrder":175},
  {"id":"s_work_han_thu_24_176","chapterId":"ch_work_han_thu_24","textTraditional":"〔四〕　師古曰：「化益即伯益。」","sentenceOrder":176},
  {"id":"s_work_han_thu_24_177","chapterId":"ch_work_han_thu_24","textTraditional":"〔五〕　師古曰：「猥，曲也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_24_178","chapterId":"ch_work_han_thu_24","textTraditional":"〔六〕　師古曰：「比，頻也。下，下獄也，音胡稼反。」","sentenceOrder":178},
  {"id":"s_work_han_thu_24_179","chapterId":"ch_work_han_thu_24","textTraditional":"〔七〕　師古曰：「更，經也，音工衡反。」","sentenceOrder":179},
  {"id":"s_work_han_thu_24_180","chapterId":"ch_work_han_thu_24","textTraditional":"至孝成世，劉向總六曆，列是非，作五紀論。向子歆究其微眇，〔一〕作三統曆及譜以說春秋，推法密要，故述焉。〔二〕","sentenceOrder":180},
  {"id":"s_work_han_thu_24_181","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　師古曰：「眇，細也，音莫小反，又讀曰妙。他皆類此。」","sentenceOrder":181},
  {"id":"s_work_han_thu_24_182","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　師古曰：「自此以下，皆班氏所述劉歆之說也。」","sentenceOrder":182},
  {"id":"s_work_han_thu_24_183","chapterId":"ch_work_han_thu_24","textTraditional":"夫曆春秋者，天時也，列人事而（目）〔因〕以天時。傳曰：「民受天地之中以生，所謂命也。〔一〕是故有禮誼動作威儀之則以定命也，能者養以之福，不能者敗以取禍。」〔二〕故列十二公二百四十二年之事，以陰陽之中制其禮。故春為陽中，萬物以生；秋為陰中，萬物以成。是以事舉其中，禮取其和，曆數以閏正天地之中，以作事厚生，皆所以定命也。易金火相革之卦曰「湯武革命，順乎天而應乎人」，〔三〕又曰「治曆明時」，〔四〕所以和人道也。","sentenceOrder":183},
  {"id":"s_work_han_thu_24_184","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　師古曰：「此春秋左氏傳周大夫劉康公之言也。中謂中和之氣也。」","sentenceOrder":184},
  {"id":"s_work_han_thu_24_185","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　師古曰：「之，往也，往就福也。自此以上，皆劉康公辭。」","sentenceOrder":185},
  {"id":"s_work_han_thu_24_186","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　師古曰：「離下兌上，故云金火相革。此革卦彖辭。」","sentenceOrder":186},
  {"id":"s_work_han_thu_24_187","chapterId":"ch_work_han_thu_24","textTraditional":"〔四〕　師古曰：「此革卦象辭。」","sentenceOrder":187},
  {"id":"s_work_han_thu_24_188","chapterId":"ch_work_han_thu_24","textTraditional":"周道既衰，幽王既喪，天子不能班朔，魯曆不正，以閏餘一之歲為蔀首。〔一〕故春秋刺「十一月乙亥朔，日有食之」。於是辰在申，〔二〕而司曆以為在建戌，史書建亥。哀十二年，亦以建申流火之月為建亥，〔三〕而怪蟄蟲之不伏也。自文公閏月不告朔，至此百有餘年，莫能正曆數。故子貢欲去其餼羊，孔子愛其禮，〔四〕而著其法於春秋。經曰：「冬十月朔，日有食之。」傳曰：「不書日，官失之也。天子有日官，諸侯有日御，日官居卿以厎日，禮也。〔五〕日御不失日以授百官於朝。」言告朔也。〔六〕元典曆始曰元。傳曰：「元，善之長也。」共養三德為善。〔七〕又曰：「元，體之長也。」合三體而為之原，故曰元。於春三月，每月書王，元之三統也。三統合於一元，故因元一而九三之以為法，〔八〕十一三之以為實〔九〕。實如法得一。黃鐘初九，律之首，陽之變也。因而六之，以九為法，得林鐘〔一０〕初六，呂之首，陰之變也。皆參天兩地之法也。〔一一〕上生六而倍之，下生六而損之，皆以九為法。九六，陰陽夫婦子母之道也。〔一二〕律娶妻〔一三〕而呂生子，〔一四〕天地之情也。六律六呂，而十二辰立矣。五聲清濁，而十日行矣。〔一五〕傳曰「天六地五」，數之常也。天有六氣，〔一六〕降生五味。〔一七〕夫五六者，天地之中合，〔一八〕而民所受以生也。故日有六甲，辰有五子，〔一九〕十一而天地之道畢，言終而復始。太極中央元氣，故為黃鐘，其實一龠，以其長自乘，故八十一為日法，所以生權衡度量，禮樂之所繇出也。〔二０〕經元一以統始，易太極之首也。春秋二以目歲，〔二一〕易兩儀之中也。於春每月書王，易三極之統也。於四時雖亡事必書時月，易四象之節也。時月以建分至啟閉之分，易八卦之位也。〔二二〕象事成敗，易吉凶之效也。朝聘會盟，易大業之本也。故易與春秋，天人之道也。傳曰：「龜，象也。筮，數也。物生而後有象，象而後有滋，滋而後有數。」〔二三〕","sentenceOrder":188},
  {"id":"s_work_han_thu_24_189","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　孟康曰：「當以閏盡歲為蔀首，今失正，未盡一歲便以為蔀首也。」師古曰：「蔀音剖，又音部。」","sentenceOrder":189},
  {"id":"s_work_han_thu_24_190","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　孟康曰：「辰謂斗建。」臣瓚曰：「日月之會為辰。」師古曰：「事在襄二十七年。」","sentenceOrder":190},
  {"id":"s_work_han_thu_24_191","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　張晏曰：「周之十二月，夏之十月也。再失閏，當為八月建酉，而云建申，誤也。仲尼曰：『火猶西流，司曆過也。』劉歆徒以詩『七月流火』為喻，不知八月火猶西流也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_24_192","chapterId":"ch_work_han_thu_24","textTraditional":"〔四〕　師古曰：「餼，生牲也。禮，人君每月告朔於廟，有祭事，故用牲。子貢見其禮廢而欲去其羊，孔子曰：『賜也，汝愛其羊，我愛其禮。』事見論語。」","sentenceOrder":192},
  {"id":"s_work_han_thu_24_193","chapterId":"ch_work_han_thu_24","textTraditional":"〔五〕　蘇林曰：「厎，致也。」師古曰：「音之履反。」","sentenceOrder":193},
  {"id":"s_work_han_thu_24_194","chapterId":"ch_work_han_thu_24","textTraditional":"〔六〕　師古曰：「劉家本有此語。」","sentenceOrder":194},
  {"id":"s_work_han_thu_24_195","chapterId":"ch_work_han_thu_24","textTraditional":"〔七〕　孟康曰：「謂三統之微氣也，當施育萬物，故謂之德。」師古曰：「共讀曰供。」","sentenceOrder":195},
  {"id":"s_work_han_thu_24_196","chapterId":"ch_work_han_thu_24","textTraditional":"〔八〕　孟康曰：「辰有十二，其三為天地人之統。老子曰『三生萬物』，是以餘九。辰得三氣，乃能施化。故每辰者，以三統之數乘之，是謂九三之法，得積萬九千六百八十三。」","sentenceOrder":196},
  {"id":"s_work_han_thu_24_197","chapterId":"ch_work_han_thu_24","textTraditional":"〔九〕　孟康曰：「以子數一乘丑三，餘次辰，亦每三乘之，周十一辰，得十七萬七千一百四十七。」","sentenceOrder":197},
  {"id":"s_work_han_thu_24_198","chapterId":"ch_work_han_thu_24","textTraditional":"〔一０〕孟康曰：「以六乘黃鐘之九，得五十四。」","sentenceOrder":198},
  {"id":"s_work_han_thu_24_199","chapterId":"ch_work_han_thu_24","textTraditional":"〔一一〕孟康曰：「三三而九，二三而六，參兩之義也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_24_200","chapterId":"ch_work_han_thu_24","textTraditional":"〔一二〕孟康曰：「異類為子母，謂黃鐘生林鐘也。同類為夫婦，謂黃鐘以大呂為妻也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_24_201","chapterId":"ch_work_han_thu_24","textTraditional":"〔一三〕如淳曰：「黃鐘生林鐘。」","sentenceOrder":201},
  {"id":"s_work_han_thu_24_202","chapterId":"ch_work_han_thu_24","textTraditional":"〔一四〕如淳曰：「林鐘生太族。」","sentenceOrder":202},
  {"id":"s_work_han_thu_24_203","chapterId":"ch_work_han_thu_24","textTraditional":"〔一五〕李奇曰：「聲一清一濁，合為二，五聲凡十，合於十日，從甲至癸也。」孟康曰：「謂東方甲乙、南方丙丁之屬，分在五方，故五聲屬焉。」","sentenceOrder":203},
  {"id":"s_work_han_thu_24_204","chapterId":"ch_work_han_thu_24","textTraditional":"〔一六〕張晏曰：「六氣，陰、陽、風、雨、晦、明也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_24_205","chapterId":"ch_work_han_thu_24","textTraditional":"〔一七〕孟康曰：「月令五方之味，酸鹹是也。」","sentenceOrder":205},
  {"id":"s_work_han_thu_24_206","chapterId":"ch_work_han_thu_24","textTraditional":"〔一八〕孟康曰：「天陽數奇，一三五七九，五在其中。地陰數耦，二四六八十，六在其中。故曰天地之中合。」","sentenceOrder":206},
  {"id":"s_work_han_thu_24_207","chapterId":"ch_work_han_thu_24","textTraditional":"〔一九〕孟康曰：「六甲之中唯甲寅無子，故有五子。」","sentenceOrder":207},
  {"id":"s_work_han_thu_24_208","chapterId":"ch_work_han_thu_24","textTraditional":"〔二０〕師古曰：「繇讀與由同。」","sentenceOrder":208},
  {"id":"s_work_han_thu_24_209","chapterId":"ch_work_han_thu_24","textTraditional":"〔二一〕鄧展曰：「春秋則為二矣。」孟康曰：「春為陽中，萬物以生；秋為陰中，萬物以成。舉春秋以目一歲。」","sentenceOrder":209},
  {"id":"s_work_han_thu_24_210","chapterId":"ch_work_han_thu_24","textTraditional":"〔二二〕張晏曰：「二至、二分、立春、立夏、立秋、立冬。」","sentenceOrder":210},
  {"id":"s_work_han_thu_24_211","chapterId":"ch_work_han_thu_24","textTraditional":"〔二三〕師古曰：「左氏傳載韓簡之言也。物生則有象，有象而滋益，滋益乃數起。龜以象告吉凶，筮以數示禍福。」","sentenceOrder":211},
  {"id":"s_work_han_thu_24_212","chapterId":"ch_work_han_thu_24","textTraditional":"是故元始有象一也，春秋二也，三統三也，四時四也，合而為十，成五體。以五乘十，大衍之數也，而道據其一，其餘四十九，所當用也，故蓍以為數。以象兩兩之，又以象三三之，又以象四四之，又歸奇象閏十九〔一〕及所據一加之，因以再扐兩之，〔二〕是為月法之實。如日法得一，則一月之日數也，而三辰之會交矣，是以能生吉凶。〔三〕故易曰：「天一地二，天三地四，天五地六，天七地八，天九地十。天數五，地數五，五位相得而各有合。天數二十有五，地數三十，凡天地之數五十有五，此所以成變化而行鬼神也。」〔四〕并終數為十九，易窮則變，故為閏法。〔五〕參天九，兩地十，是為會數。參天數二十五，兩地數三十，是為朔望之會。以會數乘之，則周於朔旦冬至，是為會月。〔六〕九會而復元，〔七〕黃鐘初九之數也。經於四時，雖亡事必書時月。時所以記啟閉也，月所以紀分至也。啟閉者，節也。分至者，中也。節不必在其月，故時中必在正數之月。故傳曰：「先王之正時也，履端於始，舉正於中，歸餘於終。履端於始，序則不愆；舉正於中，民則不惑；歸餘於終，事則不誖。」〔八〕此聖王之重閏也。以五位乘會數，而朔旦冬至，是為章月。四分月法，以其一乘章月，是為中法。參閏法為周至，以乘月法，以減中法而約之，則（六）〔七〕扐之數，為一月之閏法，其餘七分，此中朔相求之術也。朔不得中，是謂閏月，言陰陽雖交，不得中不生。故日法乘閏法，是為統歲。三統，是為元歲。元歲之閏，陰陽災，三統閏法。易九厄曰：初入元，百六，陽九；次三百七十四，陰九〔九〕；次四百八十，陽九；〔一０〕次七百二十，陰七；〔一一〕次七百二十，陽七；〔一二〕次六百，陰五；次六百，陽五；〔一三〕次四百八十，陰三；次四百八十，陽三。〔一四〕凡四千六百一十七歲，與一元終。經歲四千五百六十，災歲五十七。〔一五〕是以春秋曰：「舉正於中。」又曰：「閏月不告朔，非禮也。閏以正時，時以作事，事以厚生，〔一六〕生民之道於是乎在矣。不告閏朔，棄時正也，何以為民？」〔一七〕故善僖「五年春王正月辛亥朔，日南至，公既視朔，遂登觀臺以望，而書，禮也。凡分至啟閉，必書雲物，為備故也。」至昭二十年二月己丑，日南至，失閏，至在非其月。梓慎望氛氣而弗正，不履端於始也。故傳不曰冬至，而曰日南至。極於牽牛之初，日中之時景最長，以此知其南至也。斗綱之端連貫營室，織女之紀指牽牛之初，以紀日月，故曰星紀。五星起其初，日月起其中，凡十二次。日至其初為節，至其中斗建下為十二辰。視其建而知其次。故曰「制禮上物，不過十二，天之大數也」。經曰春王正月，傳曰周正月「火出，於夏為三月，商為四月，周為五月。夏數得天」〔一八〕，得四時之正也。三代各據一統，明三統常合，而迭為首，〔一九〕登降三統之首，周還五行之道也。〔二０〕故三五相包而生。天統之正，始施於子半，〔二一〕日萌色赤。地統受之於丑初，日肇化而黃，至丑半，日牙化而白。人統受之於寅初，日孽成而黑，至寅半，日生成而青。天施復於子，地化自丑畢於辰，〔二二〕人生自寅成於申。〔二三〕故曆數三統，天以甲子，〔二四〕地以甲辰，〔二五〕人以甲申。〔二六〕孟仲季迭用事為統首。三微之統既著，而五行自青始，其序亦如之。五行與三統相錯。傳曰「天有三辰，地有五行」，然則三統五星可知也。易曰：「參五以變，錯綜其數。通其變，遂成天下之文；極其數，遂定天下之象。」〔二七〕太極運三辰五星於上。而元氣轉三統五行於下。其於人，皇極統三德五事。故三辰之合於三統也，日合於天統，月合於地統，斗合於人統。五星之合於五行，水合於辰星，火合於熒惑，金合於太白，木合於歲星，土合於填星。三辰五星而相經緯也。天以一生水，地以二生火，天以三生木，地以四生金，天以五生土。五勝相乘，以生小周，以乘乾坤之策，而成大周。陰陽比類，交錯相成，故九六之變登降於六體。三微而成著，三著而成象，二象十有八變而成卦，四營而成易，為七十二，參三統兩四時相乘之數也。參之則得乾之策，兩之則得坤之策。〔二八〕以陽九九之，為六百四十八，以陰六六之，為四百三十二，凡一千八十，陰陽各一卦之微算策也。八之，為八千六百四十，而八卦小成。引而信之，〔二九〕又八之，為六萬九千一百二十，天地再之，為十三萬八千二百四十，然後大成。五星會終，觸類而長之，以乘章歲，為二百六十二萬六千五百六十，而與日月會。三會為七百八十七萬九千六百八十，而與三統會。三統二千三百六十三萬九千四十，而復於太極上元。九章歲而六之為法，太極上元為實，實如法得一，陰（一）陽各萬一千五百二十，當萬物氣體之數，天下之能事畢矣。","sentenceOrder":212},
  {"id":"s_work_han_thu_24_213","chapterId":"ch_work_han_thu_24","textTraditional":"〔一〕　孟康曰：「歲有閏分七，分滿十九，則為閏也。」師古曰：「奇音居宜反。」","sentenceOrder":213},
  {"id":"s_work_han_thu_24_214","chapterId":"ch_work_han_thu_24","textTraditional":"〔二〕　師古曰：「扐音勒。」","sentenceOrder":214},
  {"id":"s_work_han_thu_24_215","chapterId":"ch_work_han_thu_24","textTraditional":"〔三〕　孟康曰：「三辰，日月星也。軌道相錯，故有交會。交會即陰陽有干陵勝負，故生吉凶也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_24_216","chapterId":"ch_work_han_thu_24","textTraditional":"〔四〕　師古曰：「皆上繫之辭。」","sentenceOrder":216},
  {"id":"s_work_han_thu_24_217","chapterId":"ch_work_han_thu_24","textTraditional":"〔五〕　孟康曰：「天終數九，地終數十。窮，終也，言閏亦日之窮餘，故取二終之數以為義。」","sentenceOrder":217},
  {"id":"s_work_han_thu_24_218","chapterId":"ch_work_han_thu_24","textTraditional":"〔六〕　孟康曰：「會月，二十七章之月數也，得朔旦冬至日與歲復。」","sentenceOrder":218},
  {"id":"s_work_han_thu_24_219","chapterId":"ch_work_han_thu_24","textTraditional":"〔七〕　孟康曰：「謂四千六百一十七歲之月數也，所謂元月。」","sentenceOrder":219},
  {"id":"s_work_han_thu_24_220","chapterId":"ch_work_han_thu_24","textTraditional":"〔八〕　師古曰：「自此以上，左氏傳之辭也。履端於始，謂步曆之始，以為術之端首也。舉正於中，謂分一期為十二月，舉中氣以正月也。歸餘於終，謂有餘日，則歸於終，積而成閏也。誖，乖也，音布內反。」","sentenceOrder":220},
  {"id":"s_work_han_thu_24_221","chapterId":"ch_work_han_thu_24","textTraditional":"〔九〕　孟康曰：「易傳也。所謂陽九之厄，百六之會者也。初入元百六歲有厄者，則前元之餘氣也，若餘分為閏也。易爻有九六七八，百六與三百七十四，六乘八之數也，六八四十八，合為四百八十歲也。」","sentenceOrder":221},
  {"id":"s_work_han_thu_24_222","chapterId":"ch_work_han_thu_24","textTraditional":"〔一０〕孟康曰：「亦六乘八之數也，於易爻六有變，故再數也。」如淳曰：「六八四十八，為四百八十歲，有九年旱。」","sentenceOrder":222},
  {"id":"s_work_han_thu_24_223","chapterId":"ch_work_han_thu_24","textTraditional":"〔一一〕孟康曰：「〔亦〕九乘八之數也。八九七十二，為七百二十歲。」","sentenceOrder":223},
  {"id":"s_work_han_thu_24_224","chapterId":"ch_work_han_thu_24","textTraditional":"〔一二〕孟康曰：「亦九乘八之數也。於易爻九變，故再數也。」如淳曰：「八十歲紀一甲子冬至。以八乘九，八九七十二，故七百二十歲，乃有災也。」","sentenceOrder":224},
  {"id":"s_work_han_thu_24_225","chapterId":"ch_work_han_thu_24","textTraditional":"〔一三〕孟康曰：「七八爻乘八之數也。七乘八得五百六十歲，八乘八得六百四十歲，合千二百歲也。於易爻七八不變，氣不通，故合而數之，各得六百歲也。」如淳曰：「爻有七八，八八六十四，七八五十六，二爻之數，合千二百。滿純陰七八不變，故通其氣，使各六百歲，乃有災。」","sentenceOrder":225},
  {"id":"s_work_han_thu_24_226","chapterId":"ch_work_han_thu_24","textTraditional":"〔一四〕孟康曰：「此六乘八之數也。六既有變，又陰爻也，陽奇陰偶，故九再數，而六四數，七八不變，又無偶，各一數。一元之中，有五陽四陰，陽旱陰水，九七五三，皆陽數也，故曰陽九之厄。」如淳曰：「九六者，陽奇陰偶。偶，故重出，覆取上六八四十八，故同四百八十歲。正以九七五三為災者，從天奇數也。易天之數曰：『立天之道，曰陰與陽。』繫天故取其奇為災歲數。八十歲則甲子冬至，一甲子六十日，一歲三百六十日，八十歲，得四百八十甲子又五日。五八四十，為四百日又四分日之一。八十歲有八十分，八十分為二十日，凡四百八十日，得七十甲子。八十歲合四百八十七甲子，餘分皆盡，故八十歲則一甲子冬至也。」","sentenceOrder":226},
  {"id":"s_work_han_thu_24_227","chapterId":"ch_work_han_thu_24","textTraditional":"〔一五〕孟康曰：「經歲，從百六終陽三也，得災歲五十七，合為一元，四千六百一十七歲。」","sentenceOrder":227},
  {"id":"s_work_han_thu_24_228","chapterId":"ch_work_han_thu_24","textTraditional":"〔一六〕師古曰：「言四時漸差，則置閏以正之，因順時而命事，事得其序，則年穀豐熟。」","sentenceOrder":228},
  {"id":"s_work_han_thu_24_229","chapterId":"ch_work_han_thu_24","textTraditional":"〔一七〕師古曰：「自此以上，皆左氏傳之辭也。為，治也。」","sentenceOrder":229},
  {"id":"s_work_han_thu_24_230","chapterId":"ch_work_han_thu_24","textTraditional":"〔一八〕師古曰：「自此以上，左傳之辭。」","sentenceOrder":230},
  {"id":"s_work_han_thu_24_231","chapterId":"ch_work_han_thu_24","textTraditional":"〔一九〕師古曰：「迭，互也，音大結反。此下亦同。」","sentenceOrder":231},
  {"id":"s_work_han_thu_24_232","chapterId":"ch_work_han_thu_24","textTraditional":"〔二０〕師古曰：「還讀曰旋。」","sentenceOrder":232},
  {"id":"s_work_han_thu_24_233","chapterId":"ch_work_han_thu_24","textTraditional":"〔二一〕蘇林曰：「子之西，亥之東，其中間也。或曰於子半曰地統，受於丑初。」臣瓚曰：「謂分十二辰，各有上中下，言半，謂在中也，又受於寅初，此謂上也。」","sentenceOrder":233},
  {"id":"s_work_han_thu_24_234","chapterId":"ch_work_han_thu_24","textTraditional":"〔二二〕如淳曰：「地以十二月生萬物，三月乃畢。」","sentenceOrder":234},
  {"id":"s_work_han_thu_24_235","chapterId":"ch_work_han_thu_24","textTraditional":"〔二三〕如淳曰：「人功自正月至七月乃畢。」","sentenceOrder":235},
  {"id":"s_work_han_thu_24_236","chapterId":"ch_work_han_thu_24","textTraditional":"〔二四〕李奇曰：「夏正月朔日。」","sentenceOrder":236},
  {"id":"s_work_han_thu_24_237","chapterId":"ch_work_han_thu_24","textTraditional":"〔二五〕韋昭曰：「殷正月朔日。」","sentenceOrder":237},
  {"id":"s_work_han_thu_24_238","chapterId":"ch_work_han_thu_24","textTraditional":"〔二六〕李奇曰：「周正月朔日。」","sentenceOrder":238},
  {"id":"s_work_han_thu_24_239","chapterId":"ch_work_han_thu_24","textTraditional":"〔二七〕師古曰：「易上繫之辭。」","sentenceOrder":239},
  {"id":"s_work_han_thu_24_240","chapterId":"ch_work_han_thu_24","textTraditional":"〔二八〕蘇林曰：「策，數也。」","sentenceOrder":240},
  {"id":"s_work_han_thu_24_241","chapterId":"ch_work_han_thu_24","textTraditional":"〔二九〕師古曰：「信讀曰伸。」","sentenceOrder":241},
  {"id":"s_work_han_thu_24_242","chapterId":"ch_work_han_thu_24","textTraditional":"校勘記","sentenceOrder":242},
  {"id":"s_work_han_thu_24_243","chapterId":"ch_work_han_thu_24","textTraditional":"九五五頁　七行　百（餘）餘人，　景祐、殿、局本都不重「餘」字。","sentenceOrder":243},
  {"id":"s_work_han_thu_24_244","chapterId":"ch_work_han_thu_24","textTraditional":"九五六頁一０行　夫推曆生律〔七〕制器，　王先謙說「制器」二字上屬為句。","sentenceOrder":244},
  {"id":"s_work_han_thu_24_245","chapterId":"ch_work_han_thu_24","textTraditional":"九五七頁一四行　絫音（墨）蠡。　景祐本無「墨」字。","sentenceOrder":245},
  {"id":"s_work_han_thu_24_246","chapterId":"ch_work_han_thu_24","textTraditional":"九五七頁一五行　蕩（降）〔滌〕人之邪意，　景祐、殿、局本都作「滌」。","sentenceOrder":246},
  {"id":"s_work_han_thu_24_247","chapterId":"ch_work_han_thu_24","textTraditional":"九五九頁　三行　取竹之解谷〔六〕生，其竅厚均者，〔七〕斷兩節間而吹之，　注〔六〕在「解谷」下，明孟康以「生」字連下文讀。　陳浩說此於文義不順，當以「取竹之解谷生」為讀，「其竅均厚者」為句，於文始順。　王先謙說句讀當如陳說，猶言解谷所生耳。","sentenceOrder":247},
  {"id":"s_work_han_thu_24_248","chapterId":"ch_work_han_thu_24","textTraditional":"九五九頁　九行　言陰大，旅助黃鐘（宮）〔宣〕氣而牙物也。　景祐、殿本都作「宣」。","sentenceOrder":248},
  {"id":"s_work_han_thu_24_249","chapterId":"ch_work_han_thu_24","textTraditional":"九六０頁　九行　生而（孔外肉）〔肉孔外內〕厚薄自然均者，　據景祐、殿、局本改。","sentenceOrder":249},
  {"id":"s_work_han_thu_24_250","chapterId":"ch_work_han_thu_24","textTraditional":"九六一頁　六行　（該）〔閡〕，臧塞也。　景祐、殿本都作「閡」。　王先謙說作「閡」是。","sentenceOrder":250},
  {"id":"s_work_han_thu_24_251","chapterId":"ch_work_han_thu_24","textTraditional":"九六三頁一五行　繇讀（為）〔與〕由同。　景祐、殿本都作「與」。　王先謙說作「與」是。","sentenceOrder":251},
  {"id":"s_work_han_thu_24_252","chapterId":"ch_work_han_thu_24","textTraditional":"九六五頁　八行　日月初（纏）〔躔〕，　景祐、殿本都作「躔」，孟康注同。","sentenceOrder":252},
  {"id":"s_work_han_thu_24_253","chapterId":"ch_work_han_thu_24","textTraditional":"九七０頁　七行　謂為（鐘）〔錘〕之形如環也。　景祐、殿、局本都作「錘」。　王先謙說作「錘」是。","sentenceOrder":253},
  {"id":"s_work_han_thu_24_254","chapterId":"ch_work_han_thu_24","textTraditional":"九七九頁一二行　列人事而（目）〔因〕以天時。殿本作「因」，景祐本作「固」。","sentenceOrder":254},
  {"id":"s_work_han_thu_24_255","chapterId":"ch_work_han_thu_24","textTraditional":"九八三頁一五行　則（六）〔七〕扐之數，　錢大昕說「六」當作「七」。","sentenceOrder":255},
  {"id":"s_work_han_thu_24_256","chapterId":"ch_work_han_thu_24","textTraditional":"九八六頁　一行　實如法得一，陰（一）陽各萬一千五百二十，　張文虎說「實如法得一」當絕句，算家常語，淺人誤以「一陰」連屬，遂又於「陽」上亦增「一」字。","sentenceOrder":256},
  {"id":"s_work_han_thu_24_257","chapterId":"ch_work_han_thu_24","textTraditional":"九八六頁一五行　〔亦〕九乘八之數也。　「亦」字據景祐、殿本補。","sentenceOrder":257},
  {"id":"s_work_han_thu_25_1","chapterId":"ch_work_han_thu_25","textTraditional":"統母","sentenceOrder":1},
  {"id":"s_work_han_thu_25_2","chapterId":"ch_work_han_thu_25","textTraditional":"日法八十一。〔一〕元始黃鐘初九自乘，一龠之數，得日法。","sentenceOrder":2},
  {"id":"s_work_han_thu_25_3","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　孟康曰：「分一日為八十一分，為三統之本母也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_25_4","chapterId":"ch_work_han_thu_25","textTraditional":"閏法十九，因為章歲。合天地終數，得閏法。統法千五百三十九。以閏法乘日法，得統法。元法四千六百一十七。參統法，得元法。會數四十七。參天九，兩地十，得會數。章月二百三十五。五位乘會數，得章月。月法二千三百九十二。推大衍象，得月法。通法五百九十八。四分月法，得通法。中法十四萬五百三十。以章月乘通法，得中法。周天五十六萬二千一百二十。以章月乘月法，得周天。歲中十二。以三統乘四時，得歲中。月周二百五十四。以章月加閏法，得月周。朔望之會百三十五。參天數二十五，兩地數三十，得朔望之會。會月六千三百四十五。以會數乘朔望之會，得會月。統月萬九千三十五。參會月，得統月。元月五萬七千一百五。參統月，得元月。章中二百二十八。以閏法乘歲中，得章中。統中萬八千四百六十八。以日法乘章中，得統中。元中五萬五千四百四。參統中，得元中。策餘八千八十。什乘元中，以減周天，得策餘。周至五十七。參閏法，得周至。","sentenceOrder":4},
  {"id":"s_work_han_thu_25_5","chapterId":"ch_work_han_thu_25","textTraditional":"（統）〔紀〕母。","sentenceOrder":5},
  {"id":"s_work_han_thu_25_6","chapterId":"ch_work_han_thu_25","textTraditional":"木金相乘為十二，是為歲星小周。小周乘巛策，為千七百二十八，是為歲星歲數。","sentenceOrder":6},
  {"id":"s_work_han_thu_25_7","chapterId":"ch_work_han_thu_25","textTraditional":"見中分二萬七百三十六。積中十三，中餘百五十七。見中法千五百八十三。見數也。見閏分萬二千九十六。積月十三，月餘萬五千七十九。見月法三萬七十七。見中日法七百三十萬八千七百一十一。見月日法二百四十三萬六千二百三十七。","sentenceOrder":7},
  {"id":"s_work_han_thu_25_8","chapterId":"ch_work_han_thu_25","textTraditional":"金火相乘為八，又以火乘之為十六而小復。小復乘乾策，為三千四百五十六，是為太白歲數。","sentenceOrder":8},
  {"id":"s_work_han_thu_25_9","chapterId":"ch_work_han_thu_25","textTraditional":"見中分四萬一千四百七十二。積中十九，中餘四百一十三。見中法二千一百六十一。復數。見閏分二萬四千一百九十二。積月十九，月餘三萬二千三十九。見月法四萬一千五十九。晨中分二萬三千三百二十八。積中十，中餘千七百一十八。（「十」一作「七」）夕中分萬八千一百四十四。積中八，中餘八百五十六。晨閏分萬三千六百八。積月十一，月餘五千一百九十一。夕閏分萬五百八十四。積月八，月餘二萬六千八百四十八。見中日法九百九十七萬七千三百三十七。見月日法三百三十二萬五千七百七十九。","sentenceOrder":9},
  {"id":"s_work_han_thu_25_10","chapterId":"ch_work_han_thu_25","textTraditional":"土木相乘而合經緯為三十，是為鎮星小周。小周乘巛策，為四千三百二十，是為鎮星歲數。","sentenceOrder":10},
  {"id":"s_work_han_thu_25_11","chapterId":"ch_work_han_thu_25","textTraditional":"見中分五萬一千八百四十。積中十二，中餘千七百四十。見中法四千一百七十五。見數也。見閏分三萬二百四十。積月十二，月餘六萬三千三百。見月法七萬九千三百二十五。見中日法千九百二十七萬五千九百七十五。見月日法六百四十二萬五千三百二十五。","sentenceOrder":11},
  {"id":"s_work_han_thu_25_12","chapterId":"ch_work_han_thu_25","textTraditional":"火經特成，故二歲而過初，三十二過初為六十四歲而小周。小周乘乾策，則太陽大周，為萬三千八百二十四歲，是為熒惑歲數。","sentenceOrder":12},
  {"id":"s_work_han_thu_25_13","chapterId":"ch_work_han_thu_25","textTraditional":"見中分十六萬五千八百八十八。積中二十五，中餘四千一百六十三。見中法六千四百六十九。見數也。見閏分九萬六千七百六十八。積月二十六，月餘五萬二千九百五十四。見月法十二萬二千九百一十一。（「二千」一作「一千」）見中日法二千九百八十六萬七千三百七十三。見月日法九百九十五萬五千七百九十一。","sentenceOrder":13},
  {"id":"s_work_han_thu_25_14","chapterId":"ch_work_han_thu_25","textTraditional":"水經特成，故一歲而及初，六十四及初而小復。小復乘巛策，則太陰大周，為九千二百一十六歲，是為辰星歲數。","sentenceOrder":14},
  {"id":"s_work_han_thu_25_15","chapterId":"ch_work_han_thu_25","textTraditional":"見中分十一萬五百九十二。積中三，中餘三萬二千四百六十九。見中法二萬九千四十一。復數也。見閏分六萬四千五百一十二。積月三，月餘五十一萬四百二十三。見月法五十五萬一千七百七十九。晨中分六萬二千二百八。積中二，中餘四千一百二十六。夕中分四萬八千三百八十四。積中一，中餘萬九千三百四十三。晨閏分三萬六千二百八十八。積月二，月餘十一萬四千六百八十二。夕閏分二萬八千二百二十四。積月一，月餘三十九萬五千七百四十一。見中日法一億三千四百八萬二千二百九十七。見月日法四千四百六十九萬四千九十九。合太陰太陽之歲數而中分之，各萬一千五百二十。陽施其氣，陰成其物。以星行率減歲數，餘則見數也。東九西七乘歲數，并九七為法，得一，金、水晨夕歲數。以歲中乘歲數，是為星見中分。星見數，是為見中法。以歲閏乘歲數，是為星見閏分。以章歲乘見數，是為見月法。以元法乘見數，是為見中日法。以統法乘見數，是為見月日法。","sentenceOrder":15},
  {"id":"s_work_han_thu_25_16","chapterId":"ch_work_han_thu_25","textTraditional":"五步","sentenceOrder":16},
  {"id":"s_work_han_thu_25_17","chapterId":"ch_work_han_thu_25","textTraditional":"木，晨始見，去日半次。順，日行十一分度二，百二十一日。始留，二十五日而旋。逆，日行七分度一，八十四日。復留，二十四日三分而旋。復順，日行十一分度二，百一十一日有百八十二萬八千三百六十二分而伏。凡見三百六十五日有百八十二萬八千三百六十五分，除逆，定行星三十度百六十六萬一千二百八十六分。凡見一歲，行一次而後伏。日行不盈十一分度一。伏三十三日三百三十三萬四千七百三十七分，行星三度百六十七萬三千四百五十一（一作「三」）分。一見，三百九十八日五百一十六萬三千一百二分，行星三十三度三百三十三萬四千七百三十七分。通其率，故曰日行千七百二十八分度之百四十五。","sentenceOrder":17},
  {"id":"s_work_han_thu_25_18","chapterId":"ch_work_han_thu_25","textTraditional":"金，晨始見，去日半次。逆，日行二分度一，六日。始留，八日而旋。始順，日行四十六分度三十三，四十六日。順，疾，日行一度九十二分度十五，百八十四日而伏。凡見二百四十四日，除逆，定行星二百四十四度。伏，日行一度九十二分度三十三有奇。〔一〕伏八十三日，行星百一十三度四百三十六萬五千二百二十分。凡晨見、伏三百二十七日，行星三百五十七度四百三十六萬五千二百二十分。夕始見，去日半次。順，日行一度九十二分度十五，百八十一日百七分日四十五。順，遲，日行四十六分度三（一作「四」）十三，四十六日。始留，七日百七分日六十二分而旋。逆，日行二（一作「三」）分度一，六日而伏。凡見二百四十一日，除逆，定行星二百四十一度。伏，逆，日行八分度七有奇。伏十六（「一作六十」）日百二十九萬五千三百五十二分，行星十四度三百六萬九千八百六十八分。一凡夕見伏，二百五十七日百二十九萬五千三百五十二（一作「一」）分，行星二百二十六度六百九十萬七千四百六十九分。一復，五百八十四日百二十九萬五千三百五十二分。行星亦如之，故曰日行一度。","sentenceOrder":18},
  {"id":"s_work_han_thu_25_19","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　師古曰：「奇音居宜反。下皆類此。」","sentenceOrder":19},
  {"id":"s_work_han_thu_25_20","chapterId":"ch_work_han_thu_25","textTraditional":"土，晨始見，去日半次。順，日行十五分度一，八十七日，始留，三十四日而旋。逆，日行八十一分度五，百一日。復留，三十三日八十六萬二千四百五十五分而旋。復順，日行十五分度一，八十五日而伏。凡見三百四十日八十六萬二千四百五十五分，除逆，定（一多「餘」字）行星五度四百四十七萬三千九百三十分。伏，日行不盈十五分度三。（百）三十七日千七百一十七萬一百七十分，行星七度八百七十三萬六千五百七十分。一見，三百七十七日千八百三萬二千六百二十五分，行星十二度千三百二十一萬五百分。通其率，故曰日行四千三百二十分度之百四十五。","sentenceOrder":20},
  {"id":"s_work_han_thu_25_21","chapterId":"ch_work_han_thu_25","textTraditional":"火，晨始見，去日半次。順，日行九十二分度五十三，二百七十六日，始留，十日而旋。逆，日行六十二分度十七，六十二日。復留，十日而旋。復順，日行九十二分度五十三，二百七十六日而伏。凡見六百三十四日，除逆，定行星三百一度。伏，日行不盈九十二分度七十三（分），伏百四十六日千五百六十八萬九千七百分，行星百一十四度八百二十一萬八千五分。一見，七百八十日千五百六十八萬九千七百分，凡行星四百一十五度八百二十一萬八千五分。通其率，故曰日行萬三千八百二十四分度之七千三百五十五。","sentenceOrder":21},
  {"id":"s_work_han_thu_25_22","chapterId":"ch_work_han_thu_25","textTraditional":"水，晨始見，去日半次。逆，日行二度，一日。始留，二日而旋。順，日行七分度六，（一多「十」字）七日。順，疾，日行一度三分度一，（一多「一」字）十八日而伏。凡見二十八日，除逆，定行星二十八度。伏，日行一度九分度七有奇，三十七日一億二千二百二萬九千六百五分，行星六十八度四千六百六十一萬一百二十八分。凡晨見、伏，六十五日一億二千二百二萬九千六百五分，行星九十六度四千六百六十一萬一百二十八分。夕始見，去日半次。順，疾，日行一度三分度一，十六日二分日一。順，遲，日行七分度六，七（一作「十」）日。留，一日二分日一而旋。逆，日行二度，一日而伏。凡見二十六日，除逆，定行星二十六度。伏，逆，日行十五分度四有奇，二十四日，行星六度五千八百六十六萬二千八百二十分。凡夕見伏，五十日，行星十九度七千五百四十一萬九千四百七十七分。一復，百一十五日一億二千二百二萬九千六百五分。行星亦如之，故曰日行一度。","sentenceOrder":22},
  {"id":"s_work_han_thu_25_23","chapterId":"ch_work_han_thu_25","textTraditional":"統術","sentenceOrder":23},
  {"id":"s_work_han_thu_25_24","chapterId":"ch_work_han_thu_25","textTraditional":"推日月元統，置太極上元以來，外所求年，盈元法除之，餘不盈統者，則天統甲子以來年數也。盈統，除之，餘則地統甲辰以來年數也。又盈統，除之，餘則人統甲申以來年數也。各以其統首日為紀。","sentenceOrder":24},
  {"id":"s_work_han_thu_25_25","chapterId":"ch_work_han_thu_25","textTraditional":"推天正，以章月乘（人）〔入〕統歲數，盈章歲得一，名曰積月，不盈者名曰閏餘。閏餘十二以上，歲有閏。求地正，加積月一；求人正，加二。","sentenceOrder":25},
  {"id":"s_work_han_thu_25_26","chapterId":"ch_work_han_thu_25","textTraditional":"推正月朔，以月法乘積月，盈日法得一，名曰積日，不盈者名曰小餘。小餘三十八以上，其月大。積日盈六十，除之，不盈者名曰大餘。數從統首日起，算外，則朔日也。求其次月，加大餘二十九，小餘四十三。小餘盈日法得一，從大餘，數除如法。求弦，加大餘七，小餘三十一。求望，倍弦。","sentenceOrder":26},
  {"id":"s_work_han_thu_25_27","chapterId":"ch_work_han_thu_25","textTraditional":"推閏餘所在，以十二乘閏餘，加（十）〔七〕得一。盈章中，數所得，起冬至，算外，則中至終閏盈。中氣在朔若二日，則前月閏也。","sentenceOrder":27},
  {"id":"s_work_han_thu_25_28","chapterId":"ch_work_han_thu_25","textTraditional":"推冬至，以（算）〔策〕餘乘（人）〔入〕統歲數，盈統法得一，名曰大餘，不盈者名曰小餘。除數如法，則所求冬至日也。","sentenceOrder":28},
  {"id":"s_work_han_thu_25_29","chapterId":"ch_work_han_thu_25","textTraditional":"求八節，加大餘四十五，小餘千一（百）〔十〕。求二十四氣，三其小餘，加大餘十五，小餘千一十。","sentenceOrder":29},
  {"id":"s_work_han_thu_25_30","chapterId":"ch_work_han_thu_25","textTraditional":"推中部二十四氣，皆以元為法。","sentenceOrder":30},
  {"id":"s_work_han_thu_25_31","chapterId":"ch_work_han_thu_25","textTraditional":"推五行，其四行各七十三日，統（歲）〔法〕分之七十七。中央各十八日，統法分之四百四。冬至後，中央二十七日六百六分。","sentenceOrder":31},
  {"id":"s_work_han_thu_25_32","chapterId":"ch_work_han_thu_25","textTraditional":"推合晨所在星，置積日，以統法乘之，以十九乘小餘而并之。盈周天，除去之；不盈者，令盈統法得一度。數起牽牛，算外，則合晨所入星度也。","sentenceOrder":32},
  {"id":"s_work_han_thu_25_33","chapterId":"ch_work_han_thu_25","textTraditional":"推其日夜半所在星，以章歲乘月小餘，以減合晨度。小餘不足者，破全度。","sentenceOrder":33},
  {"id":"s_work_han_thu_25_34","chapterId":"ch_work_han_thu_25","textTraditional":"推其月夜半所在星，以月周乘月小餘，盈統法得一度，以減合晨度。","sentenceOrder":34},
  {"id":"s_work_han_thu_25_35","chapterId":"ch_work_han_thu_25","textTraditional":"推諸加時，以十二乘小餘為實，各盈分母為法，數起於子，算外，則所加辰也。","sentenceOrder":35},
  {"id":"s_work_han_thu_25_36","chapterId":"ch_work_han_thu_25","textTraditional":"推月食，置會餘歲積月，以二十三乘之，盈百三十五，除之。不盈者，加二十三得一月，盈百三十五，數所得，起其正，算外，則食月也。加時，在望日衝辰。","sentenceOrder":36},
  {"id":"s_work_han_thu_25_37","chapterId":"ch_work_han_thu_25","textTraditional":"紀術","sentenceOrder":37},
  {"id":"s_work_han_thu_25_38","chapterId":"ch_work_han_thu_25","textTraditional":"推五星見復，置太極上元以來，盡所求年，乘大統見復數，盈歲數得一，則定見復數也。不盈者名曰見復餘。見復餘盈其見復數，一以上見在往年，倍一以上，又在前往年，不盈者在今年也。","sentenceOrder":38},
  {"id":"s_work_han_thu_25_39","chapterId":"ch_work_han_thu_25","textTraditional":"推星所（一多「在」字）見中次，以見中分乘定見復數，盈見中法得一，則積中（法）也。不盈者名曰中餘。以元中除積中，餘則中元餘也。以章中除之，餘則入章中數也。以十二除之，餘則星見中次也。中數從冬至起，次數從星紀起，算外，則星所見中次也。","sentenceOrder":39},
  {"id":"s_work_han_thu_25_40","chapterId":"ch_work_han_thu_25","textTraditional":"推星見月，以閏分乘定見〔復數〕，以章歲乘中餘從之，盈見月法得一，并積中，則積月也。不盈者名曰月（中）餘。以元月除積月餘，名曰月元餘。以章月除月元餘，則入章月數也。以十二除之，至有閏之歲，除十三入章。三歲一閏，六歲二閏，九歲三閏，十一歲四閏，十四歲五閏，十七歲六閏，十九歲七閏。不盈者數起於天正，算外，則星所見月也。","sentenceOrder":40},
  {"id":"s_work_han_thu_25_41","chapterId":"ch_work_han_thu_25","textTraditional":"推至日，以中法乘中元餘，盈元法得一，名曰積日，不盈者名曰小餘。小餘盈二千五百九十七以上，中大。數除積日如法，算外，則冬至也。","sentenceOrder":41},
  {"id":"s_work_han_thu_25_42","chapterId":"ch_work_han_thu_25","textTraditional":"推朔日，以月法乘月元餘，盈日法得一，名曰積日，餘名曰小餘。小餘三十八以上，月大。數除積日如法，算外，則星見月朔日也。","sentenceOrder":42},
  {"id":"s_work_han_thu_25_43","chapterId":"ch_work_han_thu_25","textTraditional":"推入中次日度數，以中法乘中餘，以見中法乘其小餘并之，盈見中日法得一，則入中日入次度數也。中（次）〔以〕至日數，次以次初數，算外，則星所見及日所在度數也。求夕，在日後十五度。","sentenceOrder":43},
  {"id":"s_work_han_thu_25_44","chapterId":"ch_work_han_thu_25","textTraditional":"推入月日數，以月法乘月餘，以見月法乘其小餘并之，盈見月日法得一，則入月日數也。并之大餘，數除如法，則見日也。","sentenceOrder":44},
  {"id":"s_work_han_thu_25_45","chapterId":"ch_work_han_thu_25","textTraditional":"推後見中，加積中於中元餘，加後〔中〕餘於中餘，盈其法得一，從中元餘，〔除〕數如法，則〔後〕見〔中〕也。","sentenceOrder":45},
  {"id":"s_work_han_thu_25_46","chapterId":"ch_work_han_thu_25","textTraditional":"推後見月，加積月於月元餘，加後月餘於月餘，盈其法得一，從月元餘，除數如法，則後見月也。","sentenceOrder":46},
  {"id":"s_work_han_thu_25_47","chapterId":"ch_work_han_thu_25","textTraditional":"推至日及入中次度數，如上法。","sentenceOrder":47},
  {"id":"s_work_han_thu_25_48","chapterId":"ch_work_han_thu_25","textTraditional":"推朔日及入月數，如上法","sentenceOrder":48},
  {"id":"s_work_han_thu_25_49","chapterId":"ch_work_han_thu_25","textTraditional":"推晨見加夕，夕見加晨，皆如上法。","sentenceOrder":49},
  {"id":"s_work_han_thu_25_50","chapterId":"ch_work_han_thu_25","textTraditional":"推五步，置始見以來日數，至所求日，各以其行度數乘之。其星若日有分者，分子乘全為實，分母為法。其兩有分者，分母分度數乘全，分子從之，令相乘為實，分母相乘為法，實如法得一，名曰積度。數起星初見（星宿）所在宿度，算外，則星所在宿度也。","sentenceOrder":50},
  {"id":"s_work_han_thu_25_51","chapterId":"ch_work_han_thu_25","textTraditional":"歲術","sentenceOrder":51},
  {"id":"s_work_han_thu_25_52","chapterId":"ch_work_han_thu_25","textTraditional":"推歲所在，置上元以來，外所求年，盈歲數，除去之，不盈者以百四十五乘之，以百四十四為法，如法得一，名曰積次，不盈者名曰次餘。積次盈十二，除去之，不盈者名曰定次。數從星紀起，算盡之外，則所在次也。欲知太歲，以六十除（餘）積次，餘不盈者，數從丙子起，算盡之外，則太歲日也。","sentenceOrder":52},
  {"id":"s_work_han_thu_25_53","chapterId":"ch_work_han_thu_25","textTraditional":"贏縮。傳曰：「歲棄其次而旅於明年之次，以害鳥帑，〔一〕周楚惡之。」五星之（盈）〔贏〕縮不是過也。過次者殃大，過舍者災小，不過者亡咎。次度。六物者，歲時（數）日月星辰也。辰者，日月之會而建所指也。","sentenceOrder":53},
  {"id":"s_work_han_thu_25_54","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　師古曰：「帑與奴同。」","sentenceOrder":54},
  {"id":"s_work_han_thu_25_55","chapterId":"ch_work_han_thu_25","textTraditional":"星紀，初斗十二度，大雪。中牽牛初，冬至。於夏為十一月，商為十二月，周為正月。終於婺女七度。","sentenceOrder":55},
  {"id":"s_work_han_thu_25_56","chapterId":"ch_work_han_thu_25","textTraditional":"玄枵，初婺女八度，小寒。中危初，大寒。於夏為十二月，商為正月，周為二月。終於危十五度。","sentenceOrder":56},
  {"id":"s_work_han_thu_25_57","chapterId":"ch_work_han_thu_25","textTraditional":"諏訾，初危十六度，立春。中營室十四度，驚蟄。今曰雨水，於夏為正月，商為二月，周為三月。終於奎四度。","sentenceOrder":57},
  {"id":"s_work_han_thu_25_58","chapterId":"ch_work_han_thu_25","textTraditional":"降婁，初奎五度，雨水。今曰驚蟄。中婁四度，春分。於夏為二月，商為三月，周為四月。終於胃六度。","sentenceOrder":58},
  {"id":"s_work_han_thu_25_59","chapterId":"ch_work_han_thu_25","textTraditional":"大梁，初胃七度，穀雨。今曰清明。中昴八度，清明。今曰穀雨，於夏為三月，商為四月，周為五月。終於畢十一度。","sentenceOrder":59},
  {"id":"s_work_han_thu_25_60","chapterId":"ch_work_han_thu_25","textTraditional":"實沈、初畢十二度，立夏。中井初，小滿。於夏為四月，商為五月，周為六月。終於井十五度。","sentenceOrder":60},
  {"id":"s_work_han_thu_25_61","chapterId":"ch_work_han_thu_25","textTraditional":"鶉首，初井十六度，芒種。中井三十一度，夏至。於夏為五月，商為六月，周為七月。終於柳八度。","sentenceOrder":61},
  {"id":"s_work_han_thu_25_62","chapterId":"ch_work_han_thu_25","textTraditional":"鶉火，初柳九度，小暑。中張三度，大暑。於夏為六月，商為七月，周為八月。終於張十七度。","sentenceOrder":62},
  {"id":"s_work_han_thu_25_63","chapterId":"ch_work_han_thu_25","textTraditional":"鶉尾，初張十八度，立秋。中翼十五度，處暑。於夏為七月，商為八月，周為九月。終於軫十一度。","sentenceOrder":63},
  {"id":"s_work_han_thu_25_64","chapterId":"ch_work_han_thu_25","textTraditional":"壽星，初軫十二度，白露。中角十度，秋分。於夏為八月，商為九月，周為十月。終於氐四度。","sentenceOrder":64},
  {"id":"s_work_han_thu_25_65","chapterId":"ch_work_han_thu_25","textTraditional":"大火，初氐五度，寒露。中房五度，霜降。於夏為九月，商為十月，周為十一月。終於尾九度。","sentenceOrder":65},
  {"id":"s_work_han_thu_25_66","chapterId":"ch_work_han_thu_25","textTraditional":"析木，初尾十度，立冬。中箕七度，小雪。於夏為十月，商為十一月，周為十二月。終於斗十一度。","sentenceOrder":66},
  {"id":"s_work_han_thu_25_67","chapterId":"ch_work_han_thu_25","textTraditional":"角十二。　亢九。　氐十五。　房五。　心五。　尾十八。箕十一。東七十五度。斗二十六。牛八。女十二。虛十。危十七。營室十六。壁九。北九十八度。奎十六。婁十二。胃十四。昴十一。畢十六。觜二。參九。西八十度。井三十三。鬼四。柳十五。星七。張十八。翼十八。軫十七。南百一十二度。","sentenceOrder":67},
  {"id":"s_work_han_thu_25_68","chapterId":"ch_work_han_thu_25","textTraditional":"九章歲為百七十一歲，而九道小終。九終千五百三十九歲而大終。三終而與元終。進退於牽牛之前四度五分。九會。陽以九終，故日有九道。陰兼而成之，故月有十九道。陽名成功，故九會而終。四營而成易，故四歲中餘一，四章而朔餘一，為篇首，八十一章而終一統。","sentenceOrder":68},
  {"id":"s_work_han_thu_25_69","chapterId":"ch_work_han_thu_25","textTraditional":"一，甲子元首。漢太初元年。十，辛酉。　十九，己未。　二十八，丁巳。　三十七，乙卯。　四十六，壬子。　五十五，庚戌。　六十四，戊申。　七十三，丙午，中。","sentenceOrder":69},
  {"id":"s_work_han_thu_25_70","chapterId":"ch_work_han_thu_25","textTraditional":"甲辰二統。　辛丑。　己亥。　丁酉。　乙未。　壬辰。　庚寅。　戊子。　丙戌，季。","sentenceOrder":70},
  {"id":"s_work_han_thu_25_71","chapterId":"ch_work_han_thu_25","textTraditional":"甲申三統。　辛巳。　己卯。　丁丑。文王四十二年。　乙亥。微二十六年。　壬申。庚午。　戊辰。　丙寅，孟。愍二十二年。","sentenceOrder":71},
  {"id":"s_work_han_thu_25_72","chapterId":"ch_work_han_thu_25","textTraditional":"二，癸卯。　十一，辛丑。　二十，己亥。　二十九，丁酉。　（二）〔三〕十八，甲午。四十七，壬辰。　五十六，庚寅。　六十五，戊子。　七十四，乙酉，中。","sentenceOrder":72},
  {"id":"s_work_han_thu_25_73","chapterId":"ch_work_han_thu_25","textTraditional":"癸未。　辛巳。　己卯。　丁丑。　甲戌。　壬申。　庚午。　戊辰。　乙丑，季。","sentenceOrder":73},
  {"id":"s_work_han_thu_25_74","chapterId":"ch_work_han_thu_25","textTraditional":"癸亥。　辛酉。　己未。　丁巳。周公五年。　甲寅。　壬子。　庚戌。　戊申元四年。　乙巳，孟。","sentenceOrder":74},
  {"id":"s_work_han_thu_25_75","chapterId":"ch_work_han_thu_25","textTraditional":"三，癸未。　十二，辛巳。　二十一，己卯。　三十，丙子。　三十九，甲戌。　四十八，壬申。　五十七，庚子。　六十六，丁卯。　七十五，乙丑，中。","sentenceOrder":75},
  {"id":"s_work_han_thu_25_76","chapterId":"ch_work_han_thu_25","textTraditional":"癸亥。　辛酉。　己未。　丙辰。　甲寅。　壬子。　庚戌。　丁未。　乙巳，季。","sentenceOrder":76},
  {"id":"s_work_han_thu_25_77","chapterId":"ch_work_han_thu_25","textTraditional":"癸卯。　辛丑。　己亥。　丙申。　甲午。　壬辰。　庚寅。成十二年。　丁亥。乙酉，孟。","sentenceOrder":77},
  {"id":"s_work_han_thu_25_78","chapterId":"ch_work_han_thu_25","textTraditional":"四，癸亥。初元二年。　十三，辛酉。　二十二，戊午。　三十一，丙辰。　四十，甲寅。四十九，壬子。　五十八，己酉。　六十七，丁未。　七十六，乙巳，中。","sentenceOrder":78},
  {"id":"s_work_han_thu_25_79","chapterId":"ch_work_han_thu_25","textTraditional":"癸卯。　辛丑。　戊戌。　丙申。　甲午。　壬辰。　己丑。　丁亥。　乙酉，季。","sentenceOrder":79},
  {"id":"s_work_han_thu_25_80","chapterId":"ch_work_han_thu_25","textTraditional":"癸未。　辛巳。　戊寅。　丙子。　甲戌。　壬申。惠三十八年。　己巳。　丁卯。乙丑，孟。","sentenceOrder":80},
  {"id":"s_work_han_thu_25_81","chapterId":"ch_work_han_thu_25","textTraditional":"五，癸卯。河平元年。　十四，庚子。　二十三，戊戌。　三十二，丙申。　四十一，甲午。　五十，辛卯。　五十九，己丑。　六十八，丁亥。　七十七，乙酉，中。","sentenceOrder":81},
  {"id":"s_work_han_thu_25_82","chapterId":"ch_work_han_thu_25","textTraditional":"癸未。　庚辰。　戊寅。　丙子。　甲戌。　辛未。　己巳。　丁卯。　乙丑，季。商太甲元年。","sentenceOrder":82},
  {"id":"s_work_han_thu_25_83","chapterId":"ch_work_han_thu_25","textTraditional":"癸亥。　庚申。　戊午。　丙辰。　甲寅。獻十五年。　辛亥。　己酉。　丁未。乙巳，孟。楚元三年。","sentenceOrder":83},
  {"id":"s_work_han_thu_25_84","chapterId":"ch_work_han_thu_25","textTraditional":"六，壬午。　十五，庚辰。　二十四，戊寅。　三十三，丙子。　四十二，癸酉。　五十一，辛未。　六十，己巳。　六十九，丁卯。　七十八，甲子，中。","sentenceOrder":84},
  {"id":"s_work_han_thu_25_85","chapterId":"ch_work_han_thu_25","textTraditional":"壬戌。　庚申。　戊午。　丙辰。　癸丑。　辛亥。　己酉。　丁未。　甲辰，季。","sentenceOrder":85},
  {"id":"s_work_han_thu_25_86","chapterId":"ch_work_han_thu_25","textTraditional":"壬寅。　庚子。　戊戌。　丙申。煬二十四年。　癸巳。　辛卯。　己丑。　丁亥。康四年。　甲申，孟。","sentenceOrder":86},
  {"id":"s_work_han_thu_25_87","chapterId":"ch_work_han_thu_25","textTraditional":"七，壬戌。始建國三年。　十六，庚申。　二十五，戊午。　三十四，乙卯。　四十三，癸丑。　五十二，辛亥。　六十一，己酉。　七十，丙午。　七十九，甲辰，中。","sentenceOrder":87},
  {"id":"s_work_han_thu_25_88","chapterId":"ch_work_han_thu_25","textTraditional":"壬寅。　庚子。　戊戌。　乙未。　癸巳。　辛卯。　己丑。　丙戌。　甲申，季。","sentenceOrder":88},
  {"id":"s_work_han_thu_25_89","chapterId":"ch_work_han_thu_25","textTraditional":"壬午。　庚辰。　戊寅。　乙亥。　癸酉。　辛未。　己巳。定七年。　丙寅。　甲子，孟。","sentenceOrder":89},
  {"id":"s_work_han_thu_25_90","chapterId":"ch_work_han_thu_25","textTraditional":"八，壬寅。　十七，庚子。　二十六，丁酉。　三十五，乙未。　四十四，癸巳。　五十三，辛卯。　六十二，戊子。　七十一，丙戌。　八十，甲申，中。","sentenceOrder":90},
  {"id":"s_work_han_thu_25_91","chapterId":"ch_work_han_thu_25","textTraditional":"壬午。　庚辰。　丁丑。　乙亥。　癸酉。　辛未。　戊辰。　丙寅。　甲子，季。","sentenceOrder":91},
  {"id":"s_work_han_thu_25_92","chapterId":"ch_work_han_thu_25","textTraditional":"壬戌。　庚申。　丁巳。　乙卯。　癸丑。　辛亥。僖五年。　戊申。　丙午。甲辰，孟。","sentenceOrder":92},
  {"id":"s_work_han_thu_25_93","chapterId":"ch_work_han_thu_25","textTraditional":"九，壬午。　十八，己卯。　二十七，丁丑。　三十六，乙亥。　四十五，癸酉。　五十四，庚午。　六十三，戊辰。　七十二，丙寅。　八十一，甲子，中。","sentenceOrder":93},
  {"id":"s_work_han_thu_25_94","chapterId":"ch_work_han_thu_25","textTraditional":"壬戌。　己未。　丁巳。　乙卯。　癸丑。　庚戌。　戊申。　丙午。　甲辰，季。","sentenceOrder":94},
  {"id":"s_work_han_thu_25_95","chapterId":"ch_work_han_thu_25","textTraditional":"壬寅。　己亥。　丁酉。　乙未。　癸巳。　懿九年。　庚寅。　戊子。　丙戌。　甲申，孟。元朔六年。","sentenceOrder":95},
  {"id":"s_work_han_thu_25_96","chapterId":"ch_work_han_thu_25","textTraditional":"推章首朔旦冬至日，置大餘三十九，小餘六十一，數除如法，各從其統首起。求其後章，當加大餘三十九，小餘六十一，各盡其八十一章。","sentenceOrder":96},
  {"id":"s_work_han_thu_25_97","chapterId":"ch_work_han_thu_25","textTraditional":"推篇，大餘亦如之，小餘加一。求周至，加大餘五十九，小餘二十一。","sentenceOrder":97},
  {"id":"s_work_han_thu_25_98","chapterId":"ch_work_han_thu_25","textTraditional":"世經","sentenceOrder":98},
  {"id":"s_work_han_thu_25_99","chapterId":"ch_work_han_thu_25","textTraditional":"春秋昭公十七年「郯子來朝」，傳曰昭子問少昊氏鳥名何故〔一〕，對曰：「吾祖也，我知之矣。昔者，黃帝氏以雲紀，故為雲師而雲名；炎帝氏以火紀，故為火師而火名；共工氏以水紀，故為水師而水名；〔二〕太昊氏以龍紀，故為龍師而龍名。我高祖少昊（縶）〔摯〕之立也，鳳鳥適至，故紀於鳥，為鳥師而鳥名。」言郯子據少昊受黃帝，黃帝受炎帝，炎帝受共工，共工受太昊，故先言黃帝，上及太昊。稽之於易，炮犧、神農、黃帝相繼之世可知。〔三〕","sentenceOrder":99},
  {"id":"s_work_han_thu_25_100","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　師古曰：「郯，國名；子，其君之爵也。郯國即東海郯縣是也。朝，朝於魯也。昭子，魯大夫叔孫昭子也，名婼。」","sentenceOrder":100},
  {"id":"s_work_han_thu_25_101","chapterId":"ch_work_han_thu_25","textTraditional":"〔二〕　師古曰：「共讀曰龔。下皆類此。」","sentenceOrder":101},
  {"id":"s_work_han_thu_25_102","chapterId":"ch_work_han_thu_25","textTraditional":"〔三〕　師古曰：「炮與庖同也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_25_103","chapterId":"ch_work_han_thu_25","textTraditional":"太昊帝　易曰：「炮犧氏之王天下也。」言炮犧繼天而王，為百王先，首德始於木，故為帝太昊。作罔罟以田漁，取犧牲，〔一〕故天下號曰炮犧氏。祭典曰：「共工氏伯九域。」〔二〕言雖有水德，在火木之間，非其序也。任知刑以彊，故伯而不王。秦以水德，在周、漢木火之間。〔三〕周人〈興，中“八改仓”〉其行序，故易不載。〔四〕","sentenceOrder":103},
  {"id":"s_work_han_thu_25_104","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　師古曰：「罟音古。」","sentenceOrder":104},
  {"id":"s_work_han_thu_25_105","chapterId":"ch_work_han_thu_25","textTraditional":"〔二〕　師古曰：「祭典，即禮經祭法也。伯讀與霸同。下亦類此。」","sentenceOrder":105},
  {"id":"s_work_han_thu_25_106","chapterId":"ch_work_han_thu_25","textTraditional":"〔三〕　師古曰：「志言秦為閏位，亦猶共工不當五德之序。」","sentenceOrder":106},
  {"id":"s_work_han_thu_25_107","chapterId":"ch_work_han_thu_25","textTraditional":"〔四〕　鄧展曰：「〈興，中“八改仓”〉，去也，以其非次故去之。」師古曰：「此指謂共工也。〈興，中“八改仓”〉，古遷字。其下並同。」","sentenceOrder":107},
  {"id":"s_work_han_thu_25_108","chapterId":"ch_work_han_thu_25","textTraditional":"炎帝　易曰：「炮犧氏沒，神農氏作。」言共工伯而不王，雖有水德，非其序也。以火承木，故為炎帝。教民耕農，故天下號曰神農氏。","sentenceOrder":108},
  {"id":"s_work_han_thu_25_109","chapterId":"ch_work_han_thu_25","textTraditional":"黃帝　易曰：「神農氏沒，黃帝氏作。」火生土，故為土德。與炎帝之後戰於阪泉，遂王天下。始垂衣裳，有軒冕之服，〔一〕故天下號曰軒轅氏。","sentenceOrder":109},
  {"id":"s_work_han_thu_25_110","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　鄧展曰：「凡冠，前卑後高，故曰軒冕也。」師古曰：「此說非也。軒，軒車也。冕，冕服也。春秋左氏傳曰『服冕乘軒』。」","sentenceOrder":110},
  {"id":"s_work_han_thu_25_111","chapterId":"ch_work_han_thu_25","textTraditional":"少昊帝　考德曰少昊曰清。〔一〕清者，黃帝之子清陽也，是其子孫名摯立。土生金，故為金德，天下號曰金天氏。周〈興，中“八改仓”〉其樂，故易不載，序於行。","sentenceOrder":111},
  {"id":"s_work_han_thu_25_112","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　師古曰：「考德者，考五帝德之書也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_25_113","chapterId":"ch_work_han_thu_25","textTraditional":"顓頊帝　春秋外傳曰，少昊之衰，九黎亂德，顓頊受之，乃命重黎。蒼林昌意之子也。金生水，故為水德。天下號曰高陽氏。周〈興，中“八改仓”〉其樂，故易不載，序於行。","sentenceOrder":113},
  {"id":"s_work_han_thu_25_114","chapterId":"ch_work_han_thu_25","textTraditional":"帝嚳　春秋外傳曰，顓頊之所建，帝嚳受之。清陽玄囂之孫也。〔水〕生木（故），故為木德。天下號曰高辛氏。帝摯繼之，不知世數。周〈興，中“八改仓”〉其樂，故易不載。周人禘之。","sentenceOrder":114},
  {"id":"s_work_han_thu_25_115","chapterId":"ch_work_han_thu_25","textTraditional":"唐帝　帝系曰，帝嚳四妃，陳豐生帝堯，封於唐。蓋高辛氏衰，天下歸之。木生火，故為火德，天下號曰陶唐氏。讓天下於虞，使子朱處于丹淵為諸侯。即位七十載。","sentenceOrder":115},
  {"id":"s_work_han_thu_25_116","chapterId":"ch_work_han_thu_25","textTraditional":"虞帝　帝系曰，顓頊生窮蟬，五世而生瞽叟，瞽叟生帝舜，處虞之媯汭，〔一〕堯嬗以天下。〔二〕火生土，故為土德。天下號曰有虞氏。讓天下於禹，使子商均為諸侯。即位五十載。","sentenceOrder":116},
  {"id":"s_work_han_thu_25_117","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　師古曰：「媯，水名也。水曲曰汭，音人銳反。」","sentenceOrder":117},
  {"id":"s_work_han_thu_25_118","chapterId":"ch_work_han_thu_25","textTraditional":"〔二〕　師古曰：「嬗，古禪讓字也。其下亦同。」","sentenceOrder":118},
  {"id":"s_work_han_thu_25_119","chapterId":"ch_work_han_thu_25","textTraditional":"伯禹　帝系曰，顓頊五世而生鯀，鯀生禹，虞舜嬗以天下。土生金，故為金德。天下號曰夏后氏。繼世十七王，四百三十二歲。","sentenceOrder":119},
  {"id":"s_work_han_thu_25_120","chapterId":"ch_work_han_thu_25","textTraditional":"成湯　書經湯誓湯伐夏桀。金生水，故為水德。天下號曰商，後曰殷。〔一〕","sentenceOrder":120},
  {"id":"s_work_han_thu_25_121","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　孟康曰：「初契封商，湯居殷而受命，故二號。」","sentenceOrder":121},
  {"id":"s_work_han_thu_25_122","chapterId":"ch_work_han_thu_25","textTraditional":"三統，上元至伐桀之歲，十四萬一千四百八十歲，歲在大火房五度，故傳曰：「大火，閼伯之星也，實紀商人。」後為成湯，方即世崩沒之時，為天子用事十三年矣。商十二月乙丑朔旦冬至，故書序曰：「成湯既沒，太甲元年，使伊尹作伊訓。」伊訓篇曰：「惟太甲元年十有二月乙丑朔，伊尹祀于先王，誕資有牧方明。」言雖有成湯、太丁、外丙之服，以冬至越茀祀先王于方明〔一〕以配上帝，是朔旦冬至之歲也。後九十五歲，商十二月甲申朔旦冬至，亡餘分，是為孟統。自伐桀至武王伐紂，六百二十九歲，故傳曰殷「載祀六百」。","sentenceOrder":122},
  {"id":"s_work_han_thu_25_123","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　如淳曰：「覲禮，諸侯覲天子，為壇十有二尋，加方明于其上。」孟康曰：「方明者，神明之象也，以木為之，方四尺，畫六采，東青，西白，南赤，北黑，上玄，下黃。」","sentenceOrder":123},
  {"id":"s_work_han_thu_25_124","chapterId":"ch_work_han_thu_25","textTraditional":"殷曆曰，當成湯方即世用事十三年，十一月甲子朔旦冬至，終六府首。〔一〕當周公五年，則為距伐桀四百五十八歲，少百七十一歲，不盈六百二十九。又以夏時乙丑為甲子，計其年乃孟統後五章，癸亥朔旦冬至也。以為甲子府首，皆非是。凡殷世繼嗣三十一王，六百二十九歲。","sentenceOrder":124},
  {"id":"s_work_han_thu_25_125","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　師古曰：「府首即蔀首。」","sentenceOrder":125},
  {"id":"s_work_han_thu_25_126","chapterId":"ch_work_han_thu_25","textTraditional":"四分，上元至伐桀十三萬二千一百一十三歲，其八十八紀，甲子府首，入伐桀後百二十七歲。","sentenceOrder":126},
  {"id":"s_work_han_thu_25_127","chapterId":"ch_work_han_thu_25","textTraditional":"春秋曆，周文王四十二年十二月丁丑朔旦冬至，孟統之二會首也。後八歲而武王伐紂。","sentenceOrder":127},
  {"id":"s_work_han_thu_25_128","chapterId":"ch_work_han_thu_25","textTraditional":"武王　書經牧誓武王伐商紂。水生木，故為木德。天下號曰周室。","sentenceOrder":128},
  {"id":"s_work_han_thu_25_129","chapterId":"ch_work_han_thu_25","textTraditional":"三統，上元至伐紂之歲，十四萬二千一百九歲，歲在鶉火張十三度。文王受命九年而崩，再期，在大祥而代紂，故書序曰：「惟十有一年，武王伐紂，〔作〕太誓。」八百諸侯會。還歸二年，乃遂伐紂克殷，以箕子歸，十三年也。故書序曰：「武王克殷，以箕子歸，作洪範。」洪範篇曰：「惟十有三祀，王訪于箕子。」自文王受命而至此十三年，歲亦在鶉火，故傳曰：「歲在鶉火，則我有周之分野也。」師初發，以殷十一月戊子，日在析木箕七度，故傳曰：「日在析木。」是夕也，月在房五度。房為天駟，故傳曰：「月在天駟。」後三日得周正月辛卯朔，合辰在斗前一度，斗柄也，故傳曰：「辰在斗柄。」明日壬辰，晨星始見。〔一〕癸巳武王始發，丙午還師，戊午度于孟津。孟津去周九百里，師行三十里，故三十一日而度。明日己未冬至，〈臼辰〉星與婺女伏，歷建星及牽牛，至於婺女天黿之首，故傳曰：「星在天黿。」周書武成篇：「惟一月壬辰，旁死霸，〔二〕若翌日癸巳，武王乃朝步自周，于征伐紂。」序曰：「一月戊午，師度于孟津。」至庚申，二月朔日也。四日癸亥，至牧野，夜陳，甲子昧爽而合矣。故外傳曰：「王以二月癸亥夜陳。」武成篇曰：「粵若來三月，既死霸，粵五日甲子，咸劉商王紂。」〔三〕是歲也，閏數餘十八，正大寒中，在周二月己丑晦。明日閏月庚寅朔。三月二日庚申驚蟄。四月己丑朔死霸。死霸，朔也。生霸，望也。是月甲辰望，乙巳，旁之。故武成篇曰：「惟四月既旁生霸，粵六日庚戌，武王燎于周廟。翌日辛亥，祀于天位。粵五日乙卯，乃以庶國祀馘于周廟。」〔四〕文王十五而生武王，受命九年而崩，崩後四年而武王克殷。克殷之歲八十六矣，後七歲而崩。故禮記文王世子曰：「文王九十七而終，武王九十三而終。」凡武王即位十一年，周公攝政五年，正月丁巳朔旦冬至，殷曆以為六年戊午，距煬公七十六歲，入孟統二十九章首也。後二歲，得周公七年「復子明辟」之歲。是歲二月乙亥朔，庚寅望，後六日得乙未。故召誥曰：「惟二月既望，粵六日乙未。」又其三月甲辰朔，三日丙午。召誥曰：「惟三月丙午朏。」〔五〕古文月采篇曰「三日曰朏」。〔六〕是歲十二月戊辰晦，周公以反政。故洛誥篇曰：「戊辰，王在新邑，烝祭歲，命作策，惟周公誕保文武受命，惟七年。」","sentenceOrder":129},
  {"id":"s_work_han_thu_25_130","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　師古曰：「〈臼辰〉，古晨字也。其字從臼。臼音居玉反。」","sentenceOrder":130},
  {"id":"s_work_han_thu_25_131","chapterId":"ch_work_han_thu_25","textTraditional":"〔二〕　孟康曰：「月二日以往，月〔生〕魄死（死），故言死魄。魄，月質也。」師古曰：「霸，古魄字同。」","sentenceOrder":131},
  {"id":"s_work_han_thu_25_132","chapterId":"ch_work_han_thu_25","textTraditional":"〔三〕　師古曰：「今文尚書之辭。劉，殺也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_25_133","chapterId":"ch_work_han_thu_25","textTraditional":"〔四〕　師古曰：「亦今文尚書也。祀馘，獻于廟而告祀也。截耳曰馘，音居獲反。」","sentenceOrder":133},
  {"id":"s_work_han_thu_25_134","chapterId":"ch_work_han_thu_25","textTraditional":"〔五〕　孟康曰：「朏，月出也，音敷尾反。」","sentenceOrder":134},
  {"id":"s_work_han_thu_25_135","chapterId":"ch_work_han_thu_25","textTraditional":"〔六〕　師古曰：「月采說月之光采，其書則亡。」","sentenceOrder":135},
  {"id":"s_work_han_thu_25_136","chapterId":"ch_work_han_thu_25","textTraditional":"成王元年正月己巳朔，此命伯禽俾侯于魯之歲也。〔一〕後三十年四月庚戌朔，十五日甲子哉生霸。〔二〕故顧命曰「惟四月哉生霸，王有疾不豫，甲子，王乃洮沬水」，作顧命。〔三〕翌日乙丑，成王崩。康王十二年六月戊辰朔，三日庚午，故畢命豐刑曰：「惟十（月）〔有〕二年六月庚午朏，王命作策豐刑。」〔四〕","sentenceOrder":136},
  {"id":"s_work_han_thu_25_137","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　師古曰：「俾，使也。封之使為諸侯。」","sentenceOrder":137},
  {"id":"s_work_han_thu_25_138","chapterId":"ch_work_han_thu_25","textTraditional":"〔二〕　師古曰：「哉，始也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_25_139","chapterId":"ch_work_han_thu_25","textTraditional":"〔三〕　師古曰：「洮，盥手也。沬，洗面也。洮音徒高反。沬即頮字也，音呼內反。」","sentenceOrder":139},
  {"id":"s_work_han_thu_25_140","chapterId":"ch_work_han_thu_25","textTraditional":"〔四〕　孟康曰：「逸書篇名。」","sentenceOrder":140},
  {"id":"s_work_han_thu_25_141","chapterId":"ch_work_han_thu_25","textTraditional":"春秋、殷曆皆以殷，魯自周昭王以下亡年數，故據周公、伯禽以下為紀。魯公伯禽，推即位四十六年，至康王十六年而薨。故傳曰：「燮父、禽父並事康王」，〔一〕言晉侯燮、魯公伯禽俱事康王也。子考公就立，酋。〔二〕考公，世家即位四年，及煬公熙立。〔三〕煬公二十四年正月丙申朔旦冬至，殷曆以為丁酉，距微公七十六歲。〔四〕","sentenceOrder":141},
  {"id":"s_work_han_thu_25_142","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　師古曰：「燮父，晉唐叔虞之子。禽父，即伯禽也。父讀曰甫。甫者，男子之美稱。」","sentenceOrder":142},
  {"id":"s_work_han_thu_25_143","chapterId":"ch_work_han_thu_25","textTraditional":"〔二〕　師古曰：「又記此酋者，諸說不同，而名字或異也。下皆放此。酋音在由反。」","sentenceOrder":143},
  {"id":"s_work_han_thu_25_144","chapterId":"ch_work_han_thu_25","textTraditional":"〔三〕　師古曰：「及者，兄弟相及，非子繼父也。下皆類此。」","sentenceOrder":144},
  {"id":"s_work_han_thu_25_145","chapterId":"ch_work_han_thu_25","textTraditional":"〔四〕　師古曰：「煬音弋向反。」","sentenceOrder":145},
  {"id":"s_work_han_thu_25_146","chapterId":"ch_work_han_thu_25","textTraditional":"世家，煬公即位六十年，子幽公宰立。幽公，世家即位十四年，及微公茀立，〈氵費〉。〔一〕微公二十六年正月乙亥朔旦冬至，殷曆以為丙子，距獻公七十六歲。","sentenceOrder":146},
  {"id":"s_work_han_thu_25_147","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　師古曰：「茀音弗。〈氵費〉，古沸字。」","sentenceOrder":147},
  {"id":"s_work_han_thu_25_148","chapterId":"ch_work_han_thu_25","textTraditional":"世家，微公即位五十年，子厲公翟立，擢。厲公，世家即位三十七年，及獻公具立。獻公十五年正月甲寅朔旦冬至，殷曆以為乙卯，距懿公七十六歲。","sentenceOrder":148},
  {"id":"s_work_han_thu_25_149","chapterId":"ch_work_han_thu_25","textTraditional":"世家，獻公即位五十年，子慎公埶立，嚊。〔一〕慎公，世家即位三十年，及武公敖立。武公，世家即位二年，子懿公被立，戲〔二〕。懿公九年正月癸巳朔旦冬至，殷曆以為甲午，距惠公七十六歲。","sentenceOrder":149},
  {"id":"s_work_han_thu_25_150","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　師古曰：「嚊音皮祕反，又音吁器反。」","sentenceOrder":150},
  {"id":"s_work_han_thu_25_151","chapterId":"ch_work_han_thu_25","textTraditional":"〔二〕　師古曰：「戲音許宜反。」","sentenceOrder":151},
  {"id":"s_work_han_thu_25_152","chapterId":"ch_work_han_thu_25","textTraditional":"世家，懿公即位九年，兄子柏御立。柏御，世家即位十一年，叔父孝公稱立。孝公，世家即位二十七年，子惠公皇立。惠公三十八年正月壬申朔旦冬至，殷曆以為癸酉，距釐公七十六歲。〔一〕","sentenceOrder":152},
  {"id":"s_work_han_thu_25_153","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　師古曰：「釐讀曰僖。下皆類此。」","sentenceOrder":153},
  {"id":"s_work_han_thu_25_154","chapterId":"ch_work_han_thu_25","textTraditional":"世家，惠公即位四十六年，子隱公息立。","sentenceOrder":154},
  {"id":"s_work_han_thu_25_155","chapterId":"ch_work_han_thu_25","textTraditional":"凡伯禽至春秋，三百八十六年。","sentenceOrder":155},
  {"id":"s_work_han_thu_25_156","chapterId":"ch_work_han_thu_25","textTraditional":"春秋　隱公，春秋即位十一年，及桓公軌立。此元年上距伐紂四百歲。","sentenceOrder":156},
  {"id":"s_work_han_thu_25_157","chapterId":"ch_work_han_thu_25","textTraditional":"桓公，春秋即位十八年，子莊公同立。","sentenceOrder":157},
  {"id":"s_work_han_thu_25_158","chapterId":"ch_work_han_thu_25","textTraditional":"莊公，春秋即位三十二年，子愍公啟方立。","sentenceOrder":158},
  {"id":"s_work_han_thu_25_159","chapterId":"ch_work_han_thu_25","textTraditional":"愍公，春秋即位二年，及釐公申立。釐公五年正月辛亥朔旦冬至，殷曆以為壬子，距成公七十六歲。","sentenceOrder":159},
  {"id":"s_work_han_thu_25_160","chapterId":"ch_work_han_thu_25","textTraditional":"是歲距上元十四萬二千五百七十七歲，得孟統五十三章首。故傳曰：「五年春王正月辛亥朔，日南至。」「八月甲午，晉侯圍上陽。」（章）〔童〕謠云：「丙子之辰，龍尾伏辰，袀服振振，取虢之旂。〔一〕鶉之賁賁，天策焞焞，火中成軍，虢公其奔。」〔二〕卜偃曰：「其九月十月之交乎？丙子旦，日在尾，月在策，鶉火中，必是時也。」冬十二月丙子滅虢。言曆者以夏時，故周十二月，夏十月也。是歲，歲在大火。故傳曰晉侯使寺人披伐蒲，重耳奔狄。〔三〕董因曰：「君之行，歲在大火。」〔四〕後十二年，釐之十六歲，歲在壽星。故傳曰重耳處狄十二年而行，過衛五鹿，乞食於野人，野人舉塊而與之。子犯曰：「天賜也，後十二年，必獲此土。歲復於壽星，必獲諸侯。」後八歲，釐之二十四年也，歲在實沈，秦伯納之。故傳曰董因云：「君以辰出，而以參入，必獲諸侯。」","sentenceOrder":160},
  {"id":"s_work_han_thu_25_161","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　師古曰：「袀音均，又弋均反。振音之人反。」","sentenceOrder":161},
  {"id":"s_work_han_thu_25_162","chapterId":"ch_work_han_thu_25","textTraditional":"〔二〕　師古曰：「賁音奔。焞音徒門反，又土門反。」","sentenceOrder":162},
  {"id":"s_work_han_thu_25_163","chapterId":"ch_work_han_thu_25","textTraditional":"〔三〕　師古曰：「晉侯謂獻公也。寺人，奄人也，披其名也。蒲，晉邑也，公子重耳之所居。獻公用驪姬之讒，故令披伐之，而重耳懼罪出奔也。事見春秋左氏傳及國語。」","sentenceOrder":163},
  {"id":"s_work_han_thu_25_164","chapterId":"ch_work_han_thu_25","textTraditional":"〔四〕　師古曰：「董因，晉史也。本周太史辛有之後，以董主史官，故為董氏，因其名也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_25_165","chapterId":"ch_work_han_thu_25","textTraditional":"春秋，釐公即位三十三年，子文公興立。文公元年，距辛亥朔旦冬至二十九歲。是歲閏餘十三，正小雪，閏當在十一月後，而在三月，故傳曰「非禮也」。後五年，閏餘十，是歲亡閏，而置閏。閏，所以正中朔也。亡閏而置閏，又不告朔，故經曰「閏月不告朔」，言亡此月也。傳曰：「不告朔，非禮也。」","sentenceOrder":165},
  {"id":"s_work_han_thu_25_166","chapterId":"ch_work_han_thu_25","textTraditional":"春秋，文公即位十八年，子宣公倭立。〔一〕","sentenceOrder":166},
  {"id":"s_work_han_thu_25_167","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　師古曰：「倭音於危反。」","sentenceOrder":167},
  {"id":"s_work_han_thu_25_168","chapterId":"ch_work_han_thu_25","textTraditional":"宣公，春秋即位十八年，子成公黑肱立。成公十二年正月庚寅朔旦冬至，殷曆以為辛卯，距定公七年七十六歲。","sentenceOrder":168},
  {"id":"s_work_han_thu_25_169","chapterId":"ch_work_han_thu_25","textTraditional":"春秋，成公即位十八年，子襄公午立。襄公二十七年，距辛亥百九歲。九月乙亥朔，是建申之月也。魯史書：「十二月乙亥朔，日有食之。」傳曰：「冬十一月乙亥朔，日有食之，於是辰在申，司曆過也，再失閏矣。」言時實行以為十一月也，不察其建，不考之於天也。二十八年距辛亥百一十歲，歲在星紀，故經曰：「春無冰。」傳曰：「歲在星紀，而淫於玄枵。」三十年歲在娵訾。三十一年歲在降婁。是歲距辛亥百一十三年，二月有癸未，上距文公十一年會于承匡之歲夏正月甲子朔凡四百四十有五甲子，奇二十日，為日二萬六千六百有六旬。故傳曰絳縣老人曰：「臣生之歲，正月甲子朔，四百四十有五甲子矣。其季於今，三之一也。」師曠曰：「郤成子會于承匡之歲也，七十三年矣。」史趙曰：「亥有二首六身，下二如身，則其日數也。」〔一〕士文伯曰：「然則二萬六千六百有六旬也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_25_170","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　孟康曰：「下二畫使就身也。」師古曰：「杜預云『亥字二畫在上，併三六為身，如算之六也。下亥上二畫，竪置身旁』。」","sentenceOrder":170},
  {"id":"s_work_han_thu_25_171","chapterId":"ch_work_han_thu_25","textTraditional":"春秋，襄公即位三十一年，子昭公稠立。昭公八年歲在析木，十年歲在顓頊之虛，玄枵也。十八年距辛亥百三十一歲，五月有丙子、戊寅、壬午，火始昏見，宋、衛、陳、鄭火。二十年春王正月，距辛亥百三十三歲，是辛亥後八章首也。正月己丑朔旦冬至，失閏。故傳曰：「二月己丑，日南至。」三十二年，歲在星紀，距辛亥百四十五歲，盈一次矣。故傳曰：「越得歲，吳伐之，必受其咎。」","sentenceOrder":171},
  {"id":"s_work_han_thu_25_172","chapterId":"ch_work_han_thu_25","textTraditional":"春秋，昭公即位三十二年，及定公宋立。定公七年，正月己巳朔旦冬至，殷曆以為庚午，距元公七十六歲。","sentenceOrder":172},
  {"id":"s_work_han_thu_25_173","chapterId":"ch_work_han_thu_25","textTraditional":"春秋，定公即位十五年，子哀公（將）〔蔣〕立。哀公十二年冬十二月流火，非建戌之月也。是月也螽，故傳曰：「火伏而後蟄者畢，今火猶西流，司曆過也。」詩曰：「七月流火。」春秋，哀公即位二十七年。自春秋盡哀十四年，凡二百四十二年。","sentenceOrder":173},
  {"id":"s_work_han_thu_25_174","chapterId":"ch_work_han_thu_25","textTraditional":"六國　春秋哀公後十三年遜于邾，子悼公曼立，寧。悼公，世家即位三十七年，子元公嘉立。元公四年正月戊申朔旦冬至，殷曆以為己酉，距康公七十六歲。元公，世家即位二十一年，子穆公衍立，顯。穆公，世家即位三十三年，子恭公奮立。恭公，世家即位二十二年，子康公毛立。康公四年正月丁亥朔旦冬至，殷曆以為戊子，距緡公七十六歲。〔一〕康公，世家即位九年，子景公偃立。景公，世家即位二十九年，子平公旅立。平公，世家即位二十年，子緡公賈立。緡公二十二年正月丙寅朔旦冬至，殷曆以為丁卯，距楚元七十六歲。緡公，世家即位二十三年，子頃公讎立。頃公，表十八年，秦昭王之五十一年也，秦始滅周。周凡三十六王，八百六十七歲。","sentenceOrder":174},
  {"id":"s_work_han_thu_25_175","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　師古曰：「緡讀與愍同。下皆類此。」","sentenceOrder":175},
  {"id":"s_work_han_thu_25_176","chapterId":"ch_work_han_thu_25","textTraditional":"秦伯〔一〕昭（公）〔王〕，本紀無天子五年。孝文王，本紀即位一年。元年，楚考烈王滅魯頃公為家人，周滅後六年也。莊襄王，本紀即位三年。始皇，本紀即位三十七年。二世，本紀即位三年。凡秦伯五世，四十九歲。","sentenceOrder":176},
  {"id":"s_work_han_thu_25_177","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　師古曰：「伯讀曰霸。其下亦同。」","sentenceOrder":177},
  {"id":"s_work_han_thu_25_178","chapterId":"ch_work_han_thu_25","textTraditional":"漢高祖皇帝，著紀，伐秦繼周。木生火，故為火德。天下號曰漢。距上元年十四萬三千二十五歲，歲在大棣之東井二十二度，鶉首之六度也。故漢志曰歲在大棣，名曰敦牂，太歲在午。八年十一月乙巳朔旦冬至，楚元三年也。故殷曆以為丙午，距元朔七十六歲。著紀，高帝即位十二年。","sentenceOrder":178},
  {"id":"s_work_han_thu_25_179","chapterId":"ch_work_han_thu_25","textTraditional":"惠帝，著紀即位七年。","sentenceOrder":179},
  {"id":"s_work_han_thu_25_180","chapterId":"ch_work_han_thu_25","textTraditional":"高（帝）〔后〕，著紀即位八年。","sentenceOrder":180},
  {"id":"s_work_han_thu_25_181","chapterId":"ch_work_han_thu_25","textTraditional":"文帝，前十六年，後七年，著紀即位二十三年。","sentenceOrder":181},
  {"id":"s_work_han_thu_25_182","chapterId":"ch_work_han_thu_25","textTraditional":"景帝，前七年，中六年，後三年，著紀即位十六年。","sentenceOrder":182},
  {"id":"s_work_han_thu_25_183","chapterId":"ch_work_han_thu_25","textTraditional":"武帝建元、元光、元朔各六年。元朔六年十一月甲申朔旦冬至，殷曆以為乙酉，距初元七十六歲。元狩、元鼎、元封各六年。漢曆太初元年，距上元十四萬三千一百二十七歲。前十一月甲子朔旦冬至，歲在星紀婺女六度，故漢志曰歲名困敦，〔一〕正月歲星出婺女。太初、天漢、太始、征和各四年，後二年，著紀即位五十四年。","sentenceOrder":183},
  {"id":"s_work_han_thu_25_184","chapterId":"ch_work_han_thu_25","textTraditional":"〔一〕　師古曰：「敦音頓。」","sentenceOrder":184},
  {"id":"s_work_han_thu_25_185","chapterId":"ch_work_han_thu_25","textTraditional":"昭帝始元、元鳳各六年，元平一年，著紀即位十三年。","sentenceOrder":185},
  {"id":"s_work_han_thu_25_186","chapterId":"ch_work_han_thu_25","textTraditional":"宣帝本始、地節、元康、神爵、五鳳、甘露各四年，黃龍一年，著紀即位二十五年。元帝初元二年十一月癸亥朔旦冬至，殷曆以為甲子，以為紀首。是歲也，十月日食，非合辰之會，不得為紀首。距建武七十六歲。初元、永光、建昭各五年，竟寧一年，著紀即位十六年。","sentenceOrder":186},
  {"id":"s_work_han_thu_25_187","chapterId":"ch_work_han_thu_25","textTraditional":"成帝建始、河平、陽朔、鴻嘉、永始、元延各四年，綏和二年，著紀即位二十六年。","sentenceOrder":187},
  {"id":"s_work_han_thu_25_188","chapterId":"ch_work_han_thu_25","textTraditional":"哀帝建平四年，元壽二年，著紀即位六年。","sentenceOrder":188},
  {"id":"s_work_han_thu_25_189","chapterId":"ch_work_han_thu_25","textTraditional":"平帝，著紀即位元始五年，以宣帝玄孫嬰為嗣，謂之孺子。孺子，著紀新都侯王莽居攝三年，王莽居攝，盜襲帝位，竊號曰新室。始建國五年，天鳳六年，地皇三年，著紀盜位十四年。更始帝，著紀以漢宗室滅王莽，即位二年。赤眉賊立宗室劉盆子，滅更始帝。自漢元年訖更始二年，凡二百三十歲。","sentenceOrder":189},
  {"id":"s_work_han_thu_25_190","chapterId":"ch_work_han_thu_25","textTraditional":"光武皇帝，著紀以景帝後高祖九世孫受命中興復漢，改元曰建武，歲在鶉尾之張度。建武三十一年，中元二年，即位三十三年。","sentenceOrder":190},
  {"id":"s_work_han_thu_25_191","chapterId":"ch_work_han_thu_25","textTraditional":"校勘記","sentenceOrder":191},
  {"id":"s_work_han_thu_25_192","chapterId":"ch_work_han_thu_25","textTraditional":"九九二頁一四行　（統）〔紀〕母。　李銳說「統」是「紀」之誤。","sentenceOrder":192},
  {"id":"s_work_han_thu_25_193","chapterId":"ch_work_han_thu_25","textTraditional":"九九四頁　三行　積中十，中餘千七百一十八。（「十」一作「七」）　王先謙說「『十』一作『七』」四字乃後人校語，此下並同。　按景祐、殿本「十」作「七」。","sentenceOrder":193},
  {"id":"s_work_han_thu_25_194","chapterId":"ch_work_han_thu_25","textTraditional":"九九九頁　八行　（百）三十七日　錢大昕說「百」字衍。按景祐本無「百」字。","sentenceOrder":194},
  {"id":"s_work_han_thu_25_195","chapterId":"ch_work_han_thu_25","textTraditional":"九九九頁一四行　日行不盈九十二分度七十三（分）。　錢大昕說下「分」字衍。","sentenceOrder":195},
  {"id":"s_work_han_thu_25_196","chapterId":"ch_work_han_thu_25","textTraditional":"一００一頁　三行　以章月乘（人）（入）統歲數，　錢大昕說「人」當作「入」。","sentenceOrder":196},
  {"id":"s_work_han_thu_25_197","chapterId":"ch_work_han_thu_25","textTraditional":"一００一頁　九行　加（十）〔七〕得一。　錢大昕說「加十」當作「加七」。","sentenceOrder":197},
  {"id":"s_work_han_thu_25_198","chapterId":"ch_work_han_thu_25","textTraditional":"一００一頁一一行　以（算）〔策〕餘乘（人）（入）統歲數，　錢大昕說「算」當作「策」，「人」當作「入」。","sentenceOrder":198},
  {"id":"s_work_han_thu_25_199","chapterId":"ch_work_han_thu_25","textTraditional":"一００一頁一三行　小餘千一（百）〔十〕。　林文炳說當作「小餘千一十」。　按景祐本正作「一十」。","sentenceOrder":199},
  {"id":"s_work_han_thu_25_200","chapterId":"ch_work_han_thu_25","textTraditional":"一００二頁　一行　統（歲）〔法〕分之七十七。　錢大昕說「統歲」當作「統法」。　李銳說「統歲」即「統法」。","sentenceOrder":200},
  {"id":"s_work_han_thu_25_201","chapterId":"ch_work_han_thu_25","textTraditional":"一００二頁一四行　盈見中法得一，則積中（法）也。　錢大昕說下「法」字衍。","sentenceOrder":201},
  {"id":"s_work_han_thu_25_202","chapterId":"ch_work_han_thu_25","textTraditional":"一００三頁　三行　以閏分乘定見〔復數〕，　「復數」二字據李銳說增。","sentenceOrder":202},
  {"id":"s_work_han_thu_25_203","chapterId":"ch_work_han_thu_25","textTraditional":"一００三頁　四行　不盈者名曰月（中）餘。　錢大昕說「中」字衍。","sentenceOrder":203},
  {"id":"s_work_han_thu_25_204","chapterId":"ch_work_han_thu_25","textTraditional":"一００三頁一二行　中（次）〔以〕至日數，　錢大昕說「次」當作「以」。","sentenceOrder":204},
  {"id":"s_work_han_thu_25_205","chapterId":"ch_work_han_thu_25","textTraditional":"一００四頁　一行　加後〔中〕餘於中餘，盈其法得一，從中元餘，〔除〕數如法，則〔後〕見〔中〕也。　前「中」、「除」、「後」三字都據錢大昕說增，後「中」字據景祐、殿本增，原注有「一多『中』字」四字。","sentenceOrder":205},
  {"id":"s_work_han_thu_25_206","chapterId":"ch_work_han_thu_25","textTraditional":"一００四頁一０行　數起星初見（星宿）所在宿度，　李銳說「星宿」二字衍。","sentenceOrder":206},
  {"id":"s_work_han_thu_25_207","chapterId":"ch_work_han_thu_25","textTraditional":"一００四頁一四行　以六十除（餘）積次，　錢大昕說「餘」字衍。","sentenceOrder":207},
  {"id":"s_work_han_thu_25_208","chapterId":"ch_work_han_thu_25","textTraditional":"一００五頁　二行　五星之（盈）〔贏〕縮不是過也。　景祐、殿本都作「贏」。","sentenceOrder":208},
  {"id":"s_work_han_thu_25_209","chapterId":"ch_work_han_thu_25","textTraditional":"一００五頁　三行　歲時（數）日月星辰也。　錢大昕說「數」字衍。","sentenceOrder":209},
  {"id":"s_work_han_thu_25_210","chapterId":"ch_work_han_thu_25","textTraditional":"一００八頁　六行　（二）〔三〕十八，甲午。　景祐、殿、局本都作「三」。　王先謙說作「三」是。","sentenceOrder":210},
  {"id":"s_work_han_thu_25_211","chapterId":"ch_work_han_thu_25","textTraditional":"一０一一頁　八行　我高祖少昊（縶）〔摯〕之立也，　景祐、殿、局本都作「摯」。　王先謙說作「摯」是。","sentenceOrder":211},
  {"id":"s_work_han_thu_25_212","chapterId":"ch_work_han_thu_25","textTraditional":"一０一三頁　三行　〔水〕生木（故），　錢大昭說「生」上脫水「字」，「木」下衍「故」字。　按景祐、殿本都作「水生木」。","sentenceOrder":212},
  {"id":"s_work_han_thu_25_213","chapterId":"ch_work_han_thu_25","textTraditional":"一０一五頁　三行　武王伐紂，〔作〕太誓。　王先謙說以下文「故書序曰」至「作洪範」例之，「太誓」上當有「作」字。","sentenceOrder":213},
  {"id":"s_work_han_thu_25_214","chapterId":"ch_work_han_thu_25","textTraditional":"一０一六頁一０行　月〔生〕魄死（死），　景祐、殿本都作「月生魄死」。","sentenceOrder":214},
  {"id":"s_work_han_thu_25_215","chapterId":"ch_work_han_thu_25","textTraditional":"一０一七頁　二行　惟十（月）〔有〕二年六月庚午朏，　景祐、殿、局本都作「有」。　王先謙說作「有」是。","sentenceOrder":215},
  {"id":"s_work_han_thu_25_216","chapterId":"ch_work_han_thu_25","textTraditional":"一０一九頁　七行　（章）〔童〕謠云：　景祐、殿本都作「童」，此誤。","sentenceOrder":216},
  {"id":"s_work_han_thu_25_217","chapterId":"ch_work_han_thu_25","textTraditional":"一０二二頁　一行　子哀公（將）〔蔣〕立。　殿本作「蔣」。　王先謙說作「蔣」是。","sentenceOrder":217},
  {"id":"s_work_han_thu_25_218","chapterId":"ch_work_han_thu_25","textTraditional":"一０二二頁一三行　昭（公）〔王〕，本紀無天子五年。　景祐、殿本都作「王」。　王先謙說作「王」是。","sentenceOrder":218},
  {"id":"s_work_han_thu_25_219","chapterId":"ch_work_han_thu_25","textTraditional":"一０二三頁　七行　高（帝）后，　錢大昭說「帝」字誤。　按景祐、殿本都作「后」。","sentenceOrder":219},
  {"id":"s_work_han_thu_26_1","chapterId":"ch_work_han_thu_26","textTraditional":"六經之道同歸，而禮樂之用為急。〔一〕治身者斯須忘禮，則暴嫚入之矣；〔二〕為國者一朝失禮，則荒亂及之矣。人函天地陰陽之氣，有喜怒哀樂之情。〔三〕天稟其性而不能節也，〔四〕聖人能為之節而不能絕也，故象天地而制禮樂，所以通神明，立人倫，〔五〕正情性，節萬事者也。","sentenceOrder":1},
  {"id":"s_work_han_thu_26_2","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「六經謂易、詩、書、春秋、禮、樂也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_26_3","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「斯須，猶須臾。」","sentenceOrder":3},
  {"id":"s_work_han_thu_26_4","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「函，包容也，讀與含同。它皆類此。」","sentenceOrder":4},
  {"id":"s_work_han_thu_26_5","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「稟謂給授也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_26_6","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「倫，理也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_26_7","chapterId":"ch_work_han_thu_26","textTraditional":"人性有男女之情，妒忌之別，為制婚姻之禮；有交接長幼之序，為制鄉飲之禮；有哀死思遠之情，為制喪祭之禮；有尊尊敬上之心，為制朝覲之禮。哀有哭踊之節，樂有歌舞之容，〔一〕正人足以副其誠，邪人足以防其失。〔二〕故婚姻之禮廢，則夫婦之道苦，而淫辟之罪多；〔三〕鄉飲之禮廢，則長幼之序亂，而爭鬥之獄蕃；〔四〕喪祭之禮廢，則骨肉之恩薄，而背死忘先者眾；〔五〕朝聘之禮廢，則君臣之位失，而侵陵之漸起。故孔子曰：「安上治民，莫譱於禮；移風易俗，莫譱於樂。」〔六〕禮節民心，樂和民聲，政以行之，刑以防之。禮樂政刑四達而不誖，則王道備矣。〔七〕","sentenceOrder":7},
  {"id":"s_work_han_thu_26_8","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「踊，跳也。哀甚則踊。」","sentenceOrder":8},
  {"id":"s_work_han_thu_26_9","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「副，稱也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_26_10","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　孟康曰：「苦音盬。夫婦之道行盬不固也。」師古曰：「苦，惡也，不當假借。辟讀曰僻。」","sentenceOrder":10},
  {"id":"s_work_han_thu_26_11","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「蕃亦多也，音扶元反。他皆類此。」","sentenceOrder":11},
  {"id":"s_work_han_thu_26_12","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「先者，先人，謂祖考。」","sentenceOrder":12},
  {"id":"s_work_han_thu_26_13","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「此孝經載孔子之言也。譱，古善字。」","sentenceOrder":13},
  {"id":"s_work_han_thu_26_14","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　師古曰：「誖，乖也，音布內反。」","sentenceOrder":14},
  {"id":"s_work_han_thu_26_15","chapterId":"ch_work_han_thu_26","textTraditional":"樂以治內而為同，〔一〕禮以修外而為異；〔二〕同則和親，異則畏敬；和親則無怨，畏敬則不爭。揖讓而天下治者，禮樂之謂也。二者並行，合為一體。畏敬之意難見，則著之於享獻辭受，登降跪拜；〔三〕和親之說難形，則發之於詩歌詠言，鐘石筦弦。〔四〕蓋嘉其敬意而不及其財賄，美其歡心而不流其聲音。〔五〕故孔子曰：「禮云禮云，玉帛云乎哉？樂云樂云，鐘鼓云乎哉？」〔六〕此禮樂之本也。故曰：「知禮樂之情者能作，識禮樂之文者能述；作者之謂聖，述者之謂明。明聖者，述作之謂也。」〔七〕","sentenceOrder":15},
  {"id":"s_work_han_thu_26_16","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　李奇曰：「同於和樂也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_26_17","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　李奇曰：「尊卑為異也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_26_18","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「見謂彰顯也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_26_19","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「說讀曰悅。形亦見也。筦字與管同。」","sentenceOrder":19},
  {"id":"s_work_han_thu_26_20","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「流，移也。心不移溢於音聲也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_26_21","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「論語載孔子之言也。謂禮以節人為貴，樂以和人為本，玉帛鐘鼓乃其末也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_26_22","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　師古曰：「作謂有所興造也。述謂明辨其義而循行也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_26_23","chapterId":"ch_work_han_thu_26","textTraditional":"王者必因前王之禮，順時施宜，有所損益，即民之心，稍稍制作，〔一〕至太平而大備。周監於二代，禮文尤具，〔二〕事為之制，曲為之防，〔三〕故稱禮經三百，威儀三千。於是教化浹洽，〔四〕民用和睦，災害不生，禍亂不作，囹圄空虛，四十餘年。〔五〕孔子美之曰：「郁郁乎文哉！吾從周。」〔六〕及其衰也，諸侯踰越法度，惡禮制之害己，去其篇籍。遭秦滅學，遂以亂亡。","sentenceOrder":23},
  {"id":"s_work_han_thu_26_24","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「即，就也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_26_25","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「監，觀也。二代，夏、殷也。言周觀夏、殷之禮，而增損之也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_26_26","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「言每事立制，委曲防閑也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_26_27","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「浹，徹也。洽，霑也。浹音子牒反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_26_28","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　應劭曰：「囹圄，周獄名也。」師古曰：「囹，獄也。圄，守也。故總言囹圄，無繫於周。囹音來丁反。圄音牛呂反。」","sentenceOrder":28},
  {"id":"s_work_han_thu_26_29","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「論語載孔子之言也。郁郁，文章貌。」","sentenceOrder":29},
  {"id":"s_work_han_thu_26_30","chapterId":"ch_work_han_thu_26","textTraditional":"漢興，撥亂反正，日不暇給，〔一〕猶命叔孫通制禮儀，以正君臣之位。高祖說而歎曰：〔二〕「吾乃今日知為天子之貴也！」以通為奉常，遂定儀法，〔三〕未盡備而通終。","sentenceOrder":30},
  {"id":"s_work_han_thu_26_31","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「撥去亂俗而還之於正道也。給，足也。言事務殷多，日日修造，尚不能足，故無暇也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_26_32","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":32},
  {"id":"s_work_han_thu_26_33","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「奉常，則太常也。解在百官公卿表。」","sentenceOrder":33},
  {"id":"s_work_han_thu_26_34","chapterId":"ch_work_han_thu_26","textTraditional":"至文帝時，賈誼以為「漢承秦之敗俗，廢禮義，捐廉恥，今其甚者殺父兄，盜者取廟器，而大臣特以簿書不報期會為故，〔一〕至於風俗流溢，恬而不怪，〔二〕以為是適然耳。〔三〕夫移風易俗，使天下回心而鄉道，〔四〕類非俗吏之所能為也。夫立君臣，等上下，使綱紀有序，六親和睦，〔五〕此非天之所為，人之所設也。人之所設，不為不立，不修則壞。〔六〕漢興至今二十餘年，宜定制度，興禮樂，然後諸侯軌道，百姓素樸，獄訟衰息」。〔七〕乃草具其儀，〔八〕天子說焉。〔九〕而大臣絳、灌之屬害之，故其議遂寢。〔一０〕","sentenceOrder":34},
  {"id":"s_work_han_thu_26_35","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「特，但也。簿，文簿也。故謂大事也。言公卿但以文案簿書報答為事也。簿音步戶反。」","sentenceOrder":35},
  {"id":"s_work_han_thu_26_36","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「恬，安也，謂心以為安。」","sentenceOrder":36},
  {"id":"s_work_han_thu_26_37","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「言正當如此，非失道也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_26_38","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":38},
  {"id":"s_work_han_thu_26_39","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　如淳曰：「六親，賈誼書以為父也，子也，從父昆弟也，從祖昆弟也，曾祖昆弟也，族昆弟也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_26_40","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「為，作也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_26_41","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　師古曰：「軌道，言遵道，猶車行之依軌轍也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_26_42","chapterId":"ch_work_han_thu_26","textTraditional":"〔八〕　師古曰：「草謂創立其事也。它皆類此。」","sentenceOrder":42},
  {"id":"s_work_han_thu_26_43","chapterId":"ch_work_han_thu_26","textTraditional":"〔九〕　師古曰：「說讀曰悅。」","sentenceOrder":43},
  {"id":"s_work_han_thu_26_44","chapterId":"ch_work_han_thu_26","textTraditional":"〔一０〕師古曰：「舊說以為絳謂絳侯周勃也，灌謂灌嬰也。而楚漢春秋高祖之臣別有絳灌，疑昧之文，不可明也。此既言大臣，則當謂周勃、灌嬰也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_26_45","chapterId":"ch_work_han_thu_26","textTraditional":"至武帝即位，進用英雋，議立明堂，制禮服，以興太平。〔一〕會竇太后好黃老言，不說儒術，〔二〕其事又廢。後董仲舒對策言：「王者欲有所為，宜求其端於天。天道大者，在於陰陽。陽為德，陰為刑。天使陽常居大夏而以生育長養為事，陰常居大冬而積於空虛不用之處，以此見天之任德不任刑也。陽出布施於上而主歲功，陰入伏藏於下而時出佐陽。陽不得陰之助，亦不能獨成歲功。王者承天意以從事，故務德教而省刑罰。刑罰不可任以治世，猶陰之不可任以成歲也。今廢先王之德教，獨用執法之吏治民，而欲德化被四海，故難成也。是故古之王者莫不以教化為大務，立大學以教於國，設庠序以化於邑。〔三〕教化已明，習俗已成，天下嘗無一人之獄矣。至周末世，大為無道，以失天下。秦繼其後，又益甚之。自古以來，未嘗以亂濟亂，大敗天下如秦者也。〔四〕習俗薄惡，民人抵冒。〔五〕今漢繼秦之後，雖欲治之，無可柰何。法出而姦生，令下而詐起，一歲之獄以萬千數，如以湯止沸，沸俞甚而無益。〔六〕辟之琴瑟〔七〕不調，甚者必解而更張之，乃可鼓也。為政而不行，甚者必變而更化之，乃可理也。故漢得天下以來，常欲善治，而至今不能勝殘去殺者，失之當更化而不能更化也。古人有言：『臨淵羨魚，不如歸而結網。』今臨政而願治七十餘歲矣，不如退而更化。更化則可善治，而災害日去，福祿日來矣。」是時，上方征討四夷，銳志武功，〔八〕不暇留意禮文之事。","sentenceOrder":45},
  {"id":"s_work_han_thu_26_46","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「服謂衣服之色也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_26_47","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":47},
  {"id":"s_work_han_thu_26_48","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「庠序，行禮養老之處也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_26_49","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「濟，益也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_26_50","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「抵，忤也。冒，犯也。言無廉恥，不畏懼也。抵音丁禮反。」","sentenceOrder":50},
  {"id":"s_work_han_thu_26_51","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「俞，進也，音踰，又音愈。它皆類此。」","sentenceOrder":51},
  {"id":"s_work_han_thu_26_52","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　師古曰：「辟讀曰譬。」","sentenceOrder":52},
  {"id":"s_work_han_thu_26_53","chapterId":"ch_work_han_thu_26","textTraditional":"〔八〕　師古曰：「銳，利也。言一意進求，若兵刃之銳利。」","sentenceOrder":53},
  {"id":"s_work_han_thu_26_54","chapterId":"ch_work_han_thu_26","textTraditional":"至宣帝時，琅邪王吉為諫大夫，又上疏言：「欲治之主不世出，〔一〕公卿幸得遭遇其時，未有建萬世之長策，舉明主於三代之隆者也。其務在於簿書斷獄聽訟而已，此非太平之基也。今俗吏所以牧民者，非有禮義科指可世世通行者也，以意穿鑿，各取一切。〔二〕是以詐偽萌生，刑罰無極，質樸日消，恩愛寖薄。〔三〕孔子曰『安上治民，莫善於禮』，非空言也。願與大臣延及儒生，述舊禮，明王制，驅一世之民，濟之仁壽之域，〔四〕則俗何以不若成康？壽何以不若高宗？」〔五〕上不納其言，吉以病去。","sentenceOrder":54},
  {"id":"s_work_han_thu_26_55","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「言時時而一出，難常遇也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_26_56","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「苟順一時，非正道。」","sentenceOrder":56},
  {"id":"s_work_han_thu_26_57","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「寖，古浸字。浸，漸也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_26_58","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「言以仁道治之，皆得其性，則壽考也。域，界也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_26_59","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「成康，周之二王，太平之時也。高宗，殷王武丁也。有德可尊，故曰高宗。享國五十九年，故云壽。」","sentenceOrder":59},
  {"id":"s_work_han_thu_26_60","chapterId":"ch_work_han_thu_26","textTraditional":"至成帝時，犍為郡於水濱得古磬十六枚，〔一〕議者以為譱祥。劉向因是說上：「宜興辟雍，設庠序，陳禮樂，隆雅頌之聲，盛揖攘之容，〔二〕以風化天下。如此而不治者，未之有也。或曰，不能具禮。〔三〕禮以養人為本，如有過差，是過而養人也。〔四〕刑罰之過，或至死傷。今之刑，非皋陶之法也，而有司請定法，削則削，筆則筆，〔五〕救時務也。至於禮樂，則曰不敢，是敢於殺人不敢於養人也。為其俎豆筦弦之間小不備，因是絕而不為，是去小不備而就大不備，（大不備）或莫甚焉。〔六〕夫教化之比於刑法，刑法輕，是舍所重而急所輕也。〔七〕且教化，所恃以為治也，刑法所以助治也。今廢所恃而獨立其所助，非所以致太平也。自京師有誖逆不順之子孫，〔八〕至於陷大辟受刑戮者不絕，繇不習五常之道也。〔九〕夫承千歲之衰周，繼暴秦之餘敝，民漸漬惡俗，貪饕險詖，不閑義理，〔一０〕不示以大化，而獨敺以刑罰，終已不改。〔一一〕故曰：『導之以禮樂，而民和睦。』〔一二〕初，叔孫通將制定禮儀，見非於齊魯之士，然卒為漢儒宗，業垂後嗣，斯成法也。」成帝以向言下公卿議，會向病卒，丞相大司空奏請立辟雍。案行長安城南，〔一三〕營表未作，遭成帝崩，群臣引以定諡。〔一四〕","sentenceOrder":60},
  {"id":"s_work_han_thu_26_61","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「濱，水涯也，音賓。」","sentenceOrder":61},
  {"id":"s_work_han_thu_26_62","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「攘，古讓字。」","sentenceOrder":62},
  {"id":"s_work_han_thu_26_63","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「或曰者，劉向設為難者之言，而後答釋也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_26_64","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「過差，猶失錯也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_26_65","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　服虔曰：「言隨君意也。」師古曰：「削者，謂有所刪去，以刀削簡牘也。筆者，謂有所增益，以筆就而書也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_26_66","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「大不備者，事之虧失，莫甚於此。」","sentenceOrder":66},
  {"id":"s_work_han_thu_26_67","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　師古曰：「舍，廢也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_26_68","chapterId":"ch_work_han_thu_26","textTraditional":"〔八〕　師古曰：「誖，乖也，音布內反。」","sentenceOrder":68},
  {"id":"s_work_han_thu_26_69","chapterId":"ch_work_han_thu_26","textTraditional":"〔九〕　師古曰：「繇與由同。五常，仁、義、禮、智、信，人性所常行之也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_26_70","chapterId":"ch_work_han_thu_26","textTraditional":"〔一０〕師古曰：「貪甚曰饕。言行險曰詖。饕音吐高反。詖音彼義反。」","sentenceOrder":70},
  {"id":"s_work_han_thu_26_71","chapterId":"ch_work_han_thu_26","textTraditional":"〔一一〕師古曰：「敺與驅同。」","sentenceOrder":71},
  {"id":"s_work_han_thu_26_72","chapterId":"ch_work_han_thu_26","textTraditional":"〔一二〕師古曰：「孝經載孔子之言也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_26_73","chapterId":"ch_work_han_thu_26","textTraditional":"〔一三〕師古曰：「行音下更反。」","sentenceOrder":73},
  {"id":"s_work_han_thu_26_74","chapterId":"ch_work_han_thu_26","textTraditional":"〔一四〕孟康曰：「諡法曰『安民立政曰成』。帝欲立辟廱，未就而崩，群臣議諡，引為美，謂之成。」","sentenceOrder":74},
  {"id":"s_work_han_thu_26_75","chapterId":"ch_work_han_thu_26","textTraditional":"及王莽為宰衡，欲燿眾庶，遂興辟廱，因以篡位，海內畔之。世祖受命中興，撥亂反正，〔一〕改定京師于土中。〔二〕即位三十年，四夷賓服，百姓家給，政教清明，〔三〕乃營立明堂、辟廱。顯宗即位，〔四〕躬行其禮，宗祀光武皇帝于明堂，養三老五更於辟廱，〔五〕威儀既盛美矣。然德化未流洽者，禮樂未具，群下無所誦說，而庠序尚未設之故也。孔子曰：「辟如為山，未成一匱，止，吾止也。」〔六〕今叔孫通所撰禮儀，與律令同錄，臧於理官，〔七〕法家又復不傳。漢典寢而不著，民臣莫有言者。〔八〕又通沒之後，河間獻王采禮樂古事，稍稍增輯，至五百餘篇。〔九〕今學者不能昭見，但推士禮以及天子，說義又頗謬異，故君臣長幼交接之道〈寖，中“彐改帚”〉以不章。〔一０〕","sentenceOrder":75},
  {"id":"s_work_han_thu_26_76","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「謂後漢光武帝也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_26_77","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「謂都洛陽。」","sentenceOrder":77},
  {"id":"s_work_han_thu_26_78","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「給，足也，言家家皆足。」","sentenceOrder":78},
  {"id":"s_work_han_thu_26_79","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　李奇曰：「明帝曰顯宗。」","sentenceOrder":79},
  {"id":"s_work_han_thu_26_80","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　李奇曰：「王者父事三老，兄事五更。詩云『三壽作朋』。」鄧展曰：「漢直以一公為三老，用大夫為五更，（母常人）〔每常大〕行禮乃置。」師古曰：「鄭玄說云三老五更謂老人更知三德五事者也。更音工衡反。蔡邕以為更當為叟。叟，老人之稱也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_26_81","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「論語載孔子之言。匱者，織草為器，所以盛土也。言為山欲成，尚少一匱之土，止而不為，則其功終已不就。如斯之人，吾所不能教喻也。辟讀曰譬。」","sentenceOrder":81},
  {"id":"s_work_han_thu_26_82","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　師古曰：「古書懷藏之字本皆作臧，漢書例為臧耳。理官，即法官也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_26_83","chapterId":"ch_work_han_thu_26","textTraditional":"〔八〕　師古曰：「寢，息也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_26_84","chapterId":"ch_work_han_thu_26","textTraditional":"〔九〕　師古曰：「輯與集同。」","sentenceOrder":84},
  {"id":"s_work_han_thu_26_85","chapterId":"ch_work_han_thu_26","textTraditional":"〔一０〕師古曰：「〈寖，中“彐改帚”〉，漸也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_26_86","chapterId":"ch_work_han_thu_26","textTraditional":"樂者，聖人之所樂也，而可以善民心。其感人深，其移風易俗易，〔一〕故先王著其教焉。〔二〕","sentenceOrder":86},
  {"id":"s_work_han_thu_26_87","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「易音弋豉反。」","sentenceOrder":87},
  {"id":"s_work_han_thu_26_88","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「著，明也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_26_89","chapterId":"ch_work_han_thu_26","textTraditional":"夫民有血氣心知之性，而無哀樂喜怒之常，應感而動，然後心術形焉。〔一〕是以纖微癄瘁（一作「衰」）之音作，而民思憂；〔二〕闡諧嫚易之音作，而民康樂；〔三〕麤厲猛奮之音作，而民剛毅；〔四〕廉直正誠之音作，而民肅敬；寬裕和順之音作，而民慈愛〔五〕；流辟邪散之音作，而民淫亂。〔六〕先王恥其亂也，故制雅頌之聲，本之情性，稽之度數，制之禮儀，〔七〕合生氣之和，導五常之行，〔八〕使之陽而不散，陰而不集，〔九〕剛氣不怒，柔氣不懾，〔一０〕四暢交於中，而發作於外，〔一一〕皆安其位而不相奪（也），足以感動人之善心（而）〔也〕，不使邪氣得接焉，是先王立樂之方也。","sentenceOrder":89},
  {"id":"s_work_han_thu_26_90","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「言人之性感物則動也。術，道徑也。心術，心之所由也。形，見也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_26_91","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「癄瘁，謂減縮也，音子笑反。」","sentenceOrder":91},
  {"id":"s_work_han_thu_26_92","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「闡，廣也。諧，和也。嫚易，言不急刻也。易音弋豉反。」","sentenceOrder":92},
  {"id":"s_work_han_thu_26_93","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「麤厲，抗厲也。猛奮，發揚也。麤（古）〔作〕麄字，〔非是〕。」","sentenceOrder":93},
  {"id":"s_work_han_thu_26_94","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「裕，饒也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_26_95","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「辟讀曰僻。」","sentenceOrder":95},
  {"id":"s_work_han_thu_26_96","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　師古曰：「稽，考也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_26_97","chapterId":"ch_work_han_thu_26","textTraditional":"〔八〕　師古曰：「生氣，陰陽之氣也。導，引也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_26_98","chapterId":"ch_work_han_thu_26","textTraditional":"〔九〕　師古曰：「集謂聚滯也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_26_99","chapterId":"ch_work_han_thu_26","textTraditional":"〔一０〕師古曰：「懾，恐也，音之涉反。」","sentenceOrder":99},
  {"id":"s_work_han_thu_26_100","chapterId":"ch_work_han_thu_26","textTraditional":"〔一一〕師古曰：「暢，通達也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_26_101","chapterId":"ch_work_han_thu_26","textTraditional":"王者未作樂之時，因先王之樂以教化百姓，說樂其俗，〔一〕然後改作，以章功德。易曰：「先王以作樂崇德，殷薦之上帝，以配祖考。」〔二〕昔黃帝作咸池，顓頊作六莖，帝嚳作五英，〔三〕堯作大章，舜作招，〔四〕禹作夏，湯作濩，〔五〕武王作武，周公作勺。勺，言能勺先祖之道也。〔六〕武，言以功定天下也。濩，言救民也。夏，大承二帝也。〔七〕招，繼堯也。〔八〕大章，章之也〔九〕。五英，英華茂也。六莖，及根莖也。〔一０〕咸池，備矣。〔一一〕自夏以往，其流不可聞已，〔一二〕殷頌猶有存者。〔一三〕周詩既備，〔一四〕而其器用張陳，周官具焉。〔一五〕典者自卿大夫師瞽以下，皆選有道德之人，〔一六〕朝夕習業，以教國子。國子者，卿大夫之子弟也。皆學歌九德，〔一七〕誦六詩，〔一八〕習六舞、五聲、八音之和。〔一九〕故帝舜命夔曰：「女典樂，教冑子〔二０〕，直而溫，〔二一〕寬而栗，〔二二〕剛而無虐，〔二三〕簡而無敖。〔二四〕詩言志，歌詠言，〔二五〕聲依詠，律和聲，〔二六〕八音克諧。」〔二七〕此之謂也。又以外賞諸侯德盛而教尊者。其威儀足以充目，音聲足以動耳，詩語足以感心，故聞其音而德和，省其詩而志正，〔二八〕論其數而法立。是以薦之郊廟則鬼神饗，作之朝廷則群臣和，立之學官則萬民協。聽者無不虛己竦神，說而承流，〔二九〕是以海內遍知上德，被服其風，〔三０〕光煇日新，化上遷善，而不知所以然，至於萬物不夭，天地順而嘉應降。故詩曰：「鐘鼓鍠鍠，磬管鏘鏘，降福穰穰。」〔三一〕書云：「擊石拊石，百獸率舞。」〔三二〕鳥獸且猶感應，而況於人乎？況於鬼神乎？故樂者，聖人之所以感天地，通神明，安萬民，成性類者也。然自雅頌之興，而所承衰亂之音猶在，〔三三〕是謂淫過凶嫚之聲，為設禁焉。世衰民散，小人乘君子，〔三四〕心耳淺薄，則邪勝正。故書序「殷紂斷棄先祖之樂，乃作淫聲，用變亂正聲，以說婦人。」〔三五〕樂官師瞽抱其器而奔散，或適諸侯，或入河海。〔三六〕夫樂本情性，浹肌膚而臧骨髓，雖經乎千載，其遺風餘烈尚猶不絕。至春秋時，陳公子完奔齊。〔三七〕陳，舜之後，招樂存焉。故孔子適齊聞招，三月不知肉味，曰「不圖為樂之至於斯！」美之甚也。〔三八〕","sentenceOrder":101},
  {"id":"s_work_han_thu_26_102","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「說樂其俗，使和說而安樂也。說讀曰悅。樂音來各反。」","sentenceOrder":102},
  {"id":"s_work_han_thu_26_103","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「此豫卦象辭也。殷，盛大也。上帝，天也。言王者作樂，崇表其德，大薦於天，而以祖考配饗之也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_26_104","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「嚳音酷。」","sentenceOrder":104},
  {"id":"s_work_han_thu_26_105","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「招讀曰韶。下皆類此。」","sentenceOrder":105},
  {"id":"s_work_han_thu_26_106","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「濩音護。」","sentenceOrder":106},
  {"id":"s_work_han_thu_26_107","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「勺讀曰酌。酌，取也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_26_108","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　師古曰：「夏，大也。二帝謂堯、舜也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_26_109","chapterId":"ch_work_han_thu_26","textTraditional":"〔八〕　師古曰：「韶之言紹，故曰繼堯也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_26_110","chapterId":"ch_work_han_thu_26","textTraditional":"〔九〕　師古曰：「章，明也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_26_111","chapterId":"ch_work_han_thu_26","textTraditional":"〔一０〕師古曰：「澤及下也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_26_112","chapterId":"ch_work_han_thu_26","textTraditional":"〔一一〕師古曰：「咸，皆也。池，言其包容浸潤也。故云備矣。」","sentenceOrder":112},
  {"id":"s_work_han_thu_26_113","chapterId":"ch_work_han_thu_26","textTraditional":"〔一二〕師古曰：「言歌頌皆亡也。已，語終辭。」","sentenceOrder":113},
  {"id":"s_work_han_thu_26_114","chapterId":"ch_work_han_thu_26","textTraditional":"〔一三〕師古曰：「謂正考甫所得那以下是。」","sentenceOrder":114},
  {"id":"s_work_han_thu_26_115","chapterId":"ch_work_han_thu_26","textTraditional":"〔一四〕師古曰：「謂雅頌皆得其所。」","sentenceOrder":115},
  {"id":"s_work_han_thu_26_116","chapterId":"ch_work_han_thu_26","textTraditional":"〔一五〕師古曰：「謂大司樂以下諸官所掌。」","sentenceOrder":116},
  {"id":"s_work_han_thu_26_117","chapterId":"ch_work_han_thu_26","textTraditional":"〔一六〕師古曰：「師，樂工。瞽，無目者。」","sentenceOrder":117},
  {"id":"s_work_han_thu_26_118","chapterId":"ch_work_han_thu_26","textTraditional":"〔一七〕師古曰：「水火金木土穀謂之六府。正德、利用、厚生謂之三事。六府三事謂之九功。九功之德皆可歌也，故言九德也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_26_119","chapterId":"ch_work_han_thu_26","textTraditional":"〔一八〕應劭曰：「六詩者，詩有六義，一曰風，二曰賦，三曰比，四曰興，五曰雅，六曰頌。」","sentenceOrder":119},
  {"id":"s_work_han_thu_26_120","chapterId":"ch_work_han_thu_26","textTraditional":"〔一九〕師古曰：「六舞謂帗舞、羽舞、{羽王}舞、旄舞、干舞、人舞也。五聲，宮、商、角、徵、羽也。八音，金、石、絲、竹、匏、土、革、木。帗音弗。{羽王}音皇。」","sentenceOrder":120},
  {"id":"s_work_han_thu_26_121","chapterId":"ch_work_han_thu_26","textTraditional":"〔二０〕師古曰：「虞書舜典所載也。夔，舜臣名。冑子，即國子也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_26_122","chapterId":"ch_work_han_thu_26","textTraditional":"〔二一〕師古曰：「正直溫和也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_26_123","chapterId":"ch_work_han_thu_26","textTraditional":"〔二二〕師古曰：「寬大而敬栗。」","sentenceOrder":123},
  {"id":"s_work_han_thu_26_124","chapterId":"ch_work_han_thu_26","textTraditional":"〔二三〕師古曰：「剛毅而不害虐也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_26_125","chapterId":"ch_work_han_thu_26","textTraditional":"〔二四〕師古曰：「簡約而無傲慢也。敖讀曰傲。」","sentenceOrder":125},
  {"id":"s_work_han_thu_26_126","chapterId":"ch_work_han_thu_26","textTraditional":"〔二五〕師古曰：「咏，古詠字也。在心為志，發言為詩。詠，永也。永，長也，歌所以長言之。」","sentenceOrder":126},
  {"id":"s_work_han_thu_26_127","chapterId":"ch_work_han_thu_26","textTraditional":"〔二六〕師古曰：「依，助也。五聲所以助歌也，六律所以和聲也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_26_128","chapterId":"ch_work_han_thu_26","textTraditional":"〔二七〕師古曰：「諧亦和也。自此以上，皆帝舜之言。」","sentenceOrder":128},
  {"id":"s_work_han_thu_26_129","chapterId":"ch_work_han_thu_26","textTraditional":"〔二八〕師古曰：「省，視也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_26_130","chapterId":"ch_work_han_thu_26","textTraditional":"〔二九〕師古曰：「竦，敬也。說讀曰悅。」","sentenceOrder":130},
  {"id":"s_work_han_thu_26_131","chapterId":"ch_work_han_thu_26","textTraditional":"〔三０〕師古曰：「被音皮義反。言蒙其風化，若被而服之。」","sentenceOrder":131},
  {"id":"s_work_han_thu_26_132","chapterId":"ch_work_han_thu_26","textTraditional":"〔三一〕師古曰：「此周頌執競之詩也。鍠鍠，和也。鏘鏘，盛也。穰穰，多也。言周王祭祖考之廟，奏樂而八音和盛，則神降之福至多也。鍠音皇。穰音人羊反。」","sentenceOrder":132},
  {"id":"s_work_han_thu_26_133","chapterId":"ch_work_han_thu_26","textTraditional":"〔三二〕師古曰：「虞書舜典也。石謂磬也。言樂之和諧也，至於擊拊磬石，則百獸相率而舞也。」","sentenceOrder":133},
  {"id":"s_work_han_thu_26_134","chapterId":"ch_work_han_thu_26","textTraditional":"〔三三〕師古曰：「言若周時尚有殷紂之餘聲。」","sentenceOrder":134},
  {"id":"s_work_han_thu_26_135","chapterId":"ch_work_han_thu_26","textTraditional":"〔三四〕師古曰：「乘，陵也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_26_136","chapterId":"ch_work_han_thu_26","textTraditional":"〔三五〕師古曰：「今文周書泰誓之辭也。說讀曰悅。」","sentenceOrder":136},
  {"id":"s_work_han_thu_26_137","chapterId":"ch_work_han_thu_26","textTraditional":"〔三六〕師古曰：「犇，古奔字。論語云：『太師摯適齊，亞飯干適楚，三飯繚適蔡，四飯缺適秦，鼓方叔入於河，播鞉武入于漢，少師陽、擊磬襄入于海。』此志所云及古今人表所敘，皆謂是也。云諸侯者，追繫其地，非為當時已有國名。而說論語者乃以為（追）魯哀公時禮壞樂崩，樂人皆去，斯亦未允也。夫六經殘缺，學者異師，文義兢馳，各守所見。而馬、鄭群儒，皆在班、揚之後，向、歆博學，又居王、杜之前，校其是非，不可偏據。其漢書所引經文，與近代儒家往往乖別，既自成義指，即就而通之，庶免守株，以申賢達之意。非苟越異，理固然也。它皆類此。」","sentenceOrder":137},
  {"id":"s_work_han_thu_26_138","chapterId":"ch_work_han_thu_26","textTraditional":"〔三七〕師古曰：「完，陳厲公子，即敬仲也，莊二十二年遇難出奔齊也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_26_139","chapterId":"ch_work_han_thu_26","textTraditional":"〔三八〕師古曰：「事見論語。」","sentenceOrder":139},
  {"id":"s_work_han_thu_26_140","chapterId":"ch_work_han_thu_26","textTraditional":"周道始缺，怨刺之詩起。王澤既竭，而詩不能作。王官失業，雅頌相錯，〔一〕孔子論而定之，故曰：「吾自衛反魯，然後樂正，雅頌各得其所。」〔二〕是時，周室大壞，諸侯恣行，設兩觀，乘大路。〔三〕陪臣管仲、季氏之屬，〔四〕三歸雍徹，八佾舞廷。〔五〕制度遂壞，陵夷而不反，〔六〕桑間、濮上，鄭、衛、宋、趙之聲並出，〔七〕內則致疾損壽，外則亂政傷民。巧偽因而飾之，以營亂富貴之耳目。〔八〕庶人以求利，列國以相間。〔九〕故秦穆遺戎而由余去，〔一０〕齊人餽魯而孔子行。〔一一〕至於六國，魏文侯最為好古，〔一二〕而謂子夏曰：「寡人聽古樂則欲寐，及聞鄭、衛，余不知倦焉。」子夏辭而辨之，終不見納，〔一三〕自此禮樂喪矣。","sentenceOrder":140},
  {"id":"s_work_han_thu_26_141","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「錯，雜也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_26_142","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「事亦見論語。」","sentenceOrder":142},
  {"id":"s_work_han_thu_26_143","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　應劭曰：「觀，闕門邊兩觀也。禮，諸侯一觀。大路，天子之車。」","sentenceOrder":143},
  {"id":"s_work_han_thu_26_144","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「陪，重也。諸侯者，天子之臣，故其臣稱重臣也。季氏，魯桓公子季友之後，專執國政而奢僭也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_26_145","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「三歸，取三姓女也。婦人謂嫁曰歸，故曰三歸。蓋謂管仲耳。雍，樂詩也，徹饌奏之。八佾，八列之舞。皆僭天子禮也。此謂季氏耳。」","sentenceOrder":145},
  {"id":"s_work_han_thu_26_146","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「陵夷，漸頹替也。解在成帝紀及諸侯王表。」","sentenceOrder":146},
  {"id":"s_work_han_thu_26_147","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　應劭曰：「桑間，衛地，濮上，濮水之上，皆好新聲。」師古曰：「鄭、衛、宋、趙諸國，亦皆有淫聲。」","sentenceOrder":147},
  {"id":"s_work_han_thu_26_148","chapterId":"ch_work_han_thu_26","textTraditional":"〔八〕　師古曰：「營猶回繞也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_26_149","chapterId":"ch_work_han_thu_26","textTraditional":"〔九〕　師古曰：「間音居莧反。」","sentenceOrder":149},
  {"id":"s_work_han_thu_26_150","chapterId":"ch_work_han_thu_26","textTraditional":"〔一０〕應劭曰：「戎，西戎也。由余，其賢臣也。秦欲兼之，遺以女樂，由余諫而不聽，遂去入秦。」","sentenceOrder":150},
  {"id":"s_work_han_thu_26_151","chapterId":"ch_work_han_thu_26","textTraditional":"〔一一〕師古曰：「餽亦饋字。論語云『齊人餽女樂，季桓子受之，三日不朝，孔子行』也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_26_152","chapterId":"ch_work_han_thu_26","textTraditional":"〔一二〕師古曰：「魏文侯本晉大夫畢萬之後，僭諸侯者。」","sentenceOrder":152},
  {"id":"s_work_han_thu_26_153","chapterId":"ch_work_han_thu_26","textTraditional":"〔一三〕師古曰：「事見禮之樂記。」","sentenceOrder":153},
  {"id":"s_work_han_thu_26_154","chapterId":"ch_work_han_thu_26","textTraditional":"漢興，樂家有制氏，〔一〕以雅樂聲律世世在大樂官，但能紀其鏗鎗鼓舞，而不能言其義。〔二〕高祖時，叔孫通因秦樂人制宗廟樂。大祝迎神于廟門，奏嘉至，〔三〕猶古降神之樂也。皇帝入廟門，奏永至，以為行步之節，猶古采薺、肆夏也。〔四〕乾豆上，奏登歌，〔五〕獨上歌，不以筦弦亂人聲，欲在位者遍聞之，猶古清廟之歌也。登歌再終，下奏休成之樂，〔六〕美神明既饗也。皇帝就酒東廂，坐定，奏永安之樂，美禮已成也。又有房中祠樂，高祖唐山夫人所作也。〔七〕周有房中樂，至秦名曰壽人。凡樂，樂其所生，禮不忘本。高祖樂楚聲，故房中樂楚聲也。孝惠二年，使樂府令夏侯寬備其簫管，更名曰安世樂。","sentenceOrder":154},
  {"id":"s_work_han_thu_26_155","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　服虔曰：「魯人也，善樂事也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_26_156","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「鏗鎗，金石之聲也。鏗音丘耕反。鎗音初庚反。其下亦同。」","sentenceOrder":156},
  {"id":"s_work_han_thu_26_157","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　李奇曰：「嘉，善也，善神之至也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_26_158","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　劉德曰：「歌樂，在逸詩。」師古曰：「薺音才私反，禮經或作薋，又作茨，音並同耳。」","sentenceOrder":158},
  {"id":"s_work_han_thu_26_159","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「乾豆，脯羞之屬。」","sentenceOrder":159},
  {"id":"s_work_han_thu_26_160","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　服虔曰：「叔孫通所奏作也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_26_161","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　服虔曰：「高帝姬也。」韋昭曰：「唐山，姓也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_26_162","chapterId":"ch_work_han_thu_26","textTraditional":"高（祖）廟奏武德、文始、五行之舞；孝文廟奏昭德、文始、四時、五行之舞；孝武廟奏盛德、文始、四時、五行之舞。武德舞者，高祖四年作，以象天下樂己行武以除亂也。文始舞者，曰本舜招舞也，高祖六年更名曰文始，以示不相襲也。五行舞者，本周舞也，秦始皇二十六年更名曰五行也。四時舞者，孝文所作，以（明）示天下之安和也。蓋樂己所自作，明有制也；〔一〕樂先王之樂，明有法也。〔二〕孝景采武德舞以為昭德，以尊大宗廟。至孝宣，采昭德舞為盛德，以尊世宗廟。諸帝廟皆常奏文始、四時、五行舞云。高祖六年又作昭容樂、禮容樂。昭容者，猶古之昭夏也，主出武德舞。〔三〕禮容者，主出文始、五行舞。舞人無樂者，將至至尊之前不敢以樂也；出用樂者，言舞不失節，能以樂終也。大氐皆因秦舊事焉。〔四〕","sentenceOrder":162},
  {"id":"s_work_han_thu_26_163","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「言自制作也。」","sentenceOrder":163},
  {"id":"s_work_han_thu_26_164","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「遵前代之法。」","sentenceOrder":164},
  {"id":"s_work_han_thu_26_165","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　蘇林曰：「言昭容樂生於武德舞。」","sentenceOrder":165},
  {"id":"s_work_han_thu_26_166","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「氐，歸也，音丁禮反。其後字或作抵，音義並同。」","sentenceOrder":166},
  {"id":"s_work_han_thu_26_167","chapterId":"ch_work_han_thu_26","textTraditional":"初，高祖既定天下，過沛，與故人父老相樂，醉酒歡哀，作「風起」之詩，令沛中僮兒百二十人習而歌之。至孝惠時，以沛宮為原廟，〔一〕皆令歌兒習吹以相和，常以百二十人為員。文、景之間，禮官肄業而已。〔二〕至武帝定郊祀之禮，祠太一於甘泉，就乾位也；〔三〕祭后土於汾陰，澤中方丘也。〔四〕乃立樂府，〔五〕采詩夜誦，〔六〕有趙、代、秦、楚之謳。以李延年為協律都尉，多舉司馬相如等數十人造為詩賦，略論律呂，以合八音之調，作十九章之歌。以正月上辛用事甘泉圜丘，〔七〕使童男女七十人俱歌，昏祠至明。夜常有神光如流星止集于祠壇，天子自竹宮而望拜，〔八〕百官侍祠者數百人皆肅然動心焉。","sentenceOrder":167},
  {"id":"s_work_han_thu_26_168","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「原，重也。言已有正廟，更重立（之）〔也〕。」","sentenceOrder":168},
  {"id":"s_work_han_thu_26_169","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「肄，習也，音弋二反。」","sentenceOrder":169},
  {"id":"s_work_han_thu_26_170","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「言在京師之西北也。」","sentenceOrder":170},
  {"id":"s_work_han_thu_26_171","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「汾水之旁，土特堆起，是澤中方丘也。祭地，以方象地形。」","sentenceOrder":171},
  {"id":"s_work_han_thu_26_172","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「始置之也。樂府之名蓋起於此，哀帝時罷之。」","sentenceOrder":172},
  {"id":"s_work_han_thu_26_173","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「采詩，依古遒人徇路，采取百姓謳謠，以知政教得失也。夜誦者，其言辭或祕不可宣露，故於夜中歌誦也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_26_174","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　師古曰：「用上辛，用周禮郊天日也。辛，取齊戒自新之義也。為圜丘者，取象天形也。」","sentenceOrder":174},
  {"id":"s_work_han_thu_26_175","chapterId":"ch_work_han_thu_26","textTraditional":"〔八〕　韋昭曰：「以竹為宮，天子居中。」師古曰：「漢舊儀云竹宮去壇三里。」","sentenceOrder":175},
  {"id":"s_work_han_thu_26_176","chapterId":"ch_work_han_thu_26","textTraditional":"安世房中歌十七章，其詩曰：","sentenceOrder":176},
  {"id":"s_work_han_thu_26_177","chapterId":"ch_work_han_thu_26","textTraditional":"大孝備矣，休德昭清。高張四縣，樂充宮庭。〔一〕芬樹羽林，雲景杳冥，〔二〕金支秀華，庶旄翠旌。〔三〕","sentenceOrder":177},
  {"id":"s_work_han_thu_26_178","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　晉灼曰：「四縣，樂四縣也，天子宮縣。」師古曰：「謂設宮縣而高張之。縣，古懸字。」","sentenceOrder":178},
  {"id":"s_work_han_thu_26_179","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「言所樹羽葆，其盛若林，芬然眾多，仰視高遠，如雲日之杳冥也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_26_180","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　張晏曰：「金支，百二十支。秀華，中主有華豔也。旄，鍾之旄也。」文穎曰：「析羽為旌，翠羽為之也。」臣瓚曰：「樂上眾飾，有流遡羽葆，以黃金為支，其首敷散，若草木之秀華也。」師古曰：「金支秀華，瓚說是也。庶，眾也。庶旄翠旌，謂析五采羽，注翠旄之首而為旌耳。」","sentenceOrder":180},
  {"id":"s_work_han_thu_26_181","chapterId":"ch_work_han_thu_26","textTraditional":"七始華始，肅倡和聲。〔一〕神來宴娭，庶幾是聽。〔二〕粥粥音送，細齊人情。〔三〕忽乘青玄，熙事備成。〔四〕清思眑眑，經緯冥冥。〔五〕","sentenceOrder":181},
  {"id":"s_work_han_thu_26_182","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　孟康曰：「七始，天地四時人之始。華始，萬物英華之始也。以為樂名，如六英也。」師古曰：「肅，敬也。言歌者敬而倡諧和之聲。」","sentenceOrder":182},
  {"id":"s_work_han_thu_26_183","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「娭，戲也。言庶幾神來宴戲聽此樂也。娭音許其反。」","sentenceOrder":183},
  {"id":"s_work_han_thu_26_184","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　晉灼曰：「粥粥，敬懼貌也。細，微也。以樂送神，微感人情，使之齊肅也。」師古曰：「粥音弋六反。」","sentenceOrder":184},
  {"id":"s_work_han_thu_26_185","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「言還神禮畢，忽登青天而去，福熙之事皆備成也。熙與禧同。」","sentenceOrder":185},
  {"id":"s_work_han_thu_26_186","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　蘇林曰：「眑音窈。」師古曰：「眑眑，幽靜也。經緯，謂經緯天地。」","sentenceOrder":186},
  {"id":"s_work_han_thu_26_187","chapterId":"ch_work_han_thu_26","textTraditional":"我定曆數，人告其心。〔一〕敕身齊戒，施教申申。〔二〕乃立祖廟，敬明尊親。大矣孝熙，四極爰轃。〔三〕","sentenceOrder":187},
  {"id":"s_work_han_thu_26_188","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「言臣下各竭其心，致誠慤也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_26_189","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　應劭曰：「敕，謹敬之貌。」師古曰：「齊讀曰齋。」","sentenceOrder":189},
  {"id":"s_work_han_thu_26_190","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「熙亦福也。四極，四方極遠之處也。爾雅曰：『東至於泰遠，西至於邠國，南至於濮鉛，北至於祝栗，謂之四極。』邠音彬。轃字與臻同。」","sentenceOrder":190},
  {"id":"s_work_han_thu_26_191","chapterId":"ch_work_han_thu_26","textTraditional":"王侯秉德，其鄰翼翼，〔一〕顯明昭式。清明鬯矣，皇帝孝德。〔二〕竟全大功，撫安四極。","sentenceOrder":191},
  {"id":"s_work_han_thu_26_192","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「鄰，言德不孤必有鄰也。翼翼，恭敬也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_26_193","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「鬯，古暢字。暢，通也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_26_194","chapterId":"ch_work_han_thu_26","textTraditional":"海內有姦，紛亂東北。〔一〕詔撫成師，武臣承德。〔二〕行樂交逆，簫、勺群慝。〔三〕肅為濟哉，蓋定燕國。〔四〕","sentenceOrder":194},
  {"id":"s_work_han_thu_26_195","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「謂匈奴。」","sentenceOrder":195},
  {"id":"s_work_han_thu_26_196","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「成師，言各置（郊）〔部〕校，師出以律也。春秋左氏傳曰『成師以出』。」","sentenceOrder":196},
  {"id":"s_work_han_thu_26_197","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　晉灼曰：「簫，舜樂也。勺，周樂也。言以樂征伐也。」師古曰：「言制定新樂，教化流行，則逆亂之徒盡交歡也。慝，惡也。勺讀曰酌。」","sentenceOrder":197},
  {"id":"s_work_han_thu_26_198","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「匈奴服從，則燕國安靜無寇難也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_26_199","chapterId":"ch_work_han_thu_26","textTraditional":"大海蕩蕩水所歸，高賢愉愉民所懷。〔一〕大山崔，百卉殖。民何貴？貴有德。〔二〕","sentenceOrder":199},
  {"id":"s_work_han_thu_26_200","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　李奇曰：「愉愉，懌也。」師古曰：「蕩蕩，廣大貌也。愉愉，和樂貌也。懷，思也。言海以廣大之故，眾水歸之；王者有和樂之德，則人皆思附也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_26_201","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「言大山以崔嵬之故，能生養百卉；明君以崇高其德，故為萬姓所尊也。崔音才回反。」","sentenceOrder":201},
  {"id":"s_work_han_thu_26_202","chapterId":"ch_work_han_thu_26","textTraditional":"安其所，樂終產。〔一〕樂終產，世繼緒。〔二〕飛龍秋，游上天。〔三〕高賢愉，樂民人。〔四〕","sentenceOrder":202},
  {"id":"s_work_han_thu_26_203","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「萬物各安其所，而樂終其生也。」","sentenceOrder":203},
  {"id":"s_work_han_thu_26_204","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「言傳祚無窮。」","sentenceOrder":204},
  {"id":"s_work_han_thu_26_205","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　蘇林曰：「秋，飛貌也。」師古曰：「莊子有秋駕之法者，亦言駕馬騰驤，秋秋然也。揚雄賦曰『秋秋蹌蹌入西園』，其義亦同。讀者不曉秋義，或改此秋字為秫稷之秫，失之遠矣。」","sentenceOrder":205},
  {"id":"s_work_han_thu_26_206","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「言王者有愉愉之德，故使眾人皆安樂。」","sentenceOrder":206},
  {"id":"s_work_han_thu_26_207","chapterId":"ch_work_han_thu_26","textTraditional":"豐草葽，女羅施。〔一〕譱何如，誰能回！〔二〕大莫大，成教德；長莫長，被無極。〔三〕","sentenceOrder":207},
  {"id":"s_work_han_thu_26_208","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　孟康曰：「葽音『四月秀葽』。葽，盛貌也。」應劭曰：「女羅，兔絲也，延于松柏之上。異類而猶載之，況同姓，言族親不可不覆遇也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_26_209","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「回，亂也。言至德之善，上古帝皇皆不如之，而不可干亂。」","sentenceOrder":209},
  {"id":"s_work_han_thu_26_210","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「被音皮義反。次下亦同。」","sentenceOrder":210},
  {"id":"s_work_han_thu_26_211","chapterId":"ch_work_han_thu_26","textTraditional":"雷震震，電燿燿。明德鄉，治本約。〔一〕治本約，澤弘大。〔二〕加被寵，咸相保。〔三〕德施大，世曼壽。〔四〕","sentenceOrder":211},
  {"id":"s_work_han_thu_26_212","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　服虔曰：「與臣民之約。」師古曰：「鄉，方也。言王者之威，取象雷電，明示德義之方，而治政本之約。約讀曰要。」","sentenceOrder":212},
  {"id":"s_work_han_thu_26_213","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「政教有常，則恩惠溥洽。」","sentenceOrder":213},
  {"id":"s_work_han_thu_26_214","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「言德政所加，人被寵渥，則室家老幼皆相保也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_26_215","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「曼，延也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_26_216","chapterId":"ch_work_han_thu_26","textTraditional":"都荔遂芳，窅窊桂華。〔一〕孝奏天儀，若日月光。〔二〕乘玄四龍，回馳北行。羽旄殷盛，芬哉芒芒。〔三〕孝道隨世，我署文章。〔四〕　桂華。","sentenceOrder":216},
  {"id":"s_work_han_thu_26_217","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　蘇林曰：「窅音窅胅之窅。窊音窊下之窊。」孟康曰：「窅，出；窊，入。都良薜荔之香鼓動桂華也。」晉灼曰：「桂華似殿名，次下言『桂華馮馮翼翼，承天之則』，言樹此香草以絜齊其芳氣，乃達於宮殿也。」臣瓚曰：「茂陵中書歌都孋、桂英、美芳、鼓行，如此復不得為殿名。」師古曰：「諸家說皆未盡也。此言都良薜荔俱有芬芳，桂華之形窅窊然也。皆謂神宮所有耳。窅音一校反。窊音一瓜反。」","sentenceOrder":217},
  {"id":"s_work_han_thu_26_218","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「言以孝道進承於天，天神下降，故有光。」","sentenceOrder":218},
  {"id":"s_work_han_thu_26_219","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「芬亦謂眾多。芒芒，廣遠之貌。」","sentenceOrder":219},
  {"id":"s_work_han_thu_26_220","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「署猶分部也，一曰表也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_26_221","chapterId":"ch_work_han_thu_26","textTraditional":"馮馮翼翼，承天之則。〔一〕吾易久遠，燭明四極。〔二〕慈惠所愛，美若休德。〔三〕杳杳冥冥，克綽永福。〔四〕　美（芳）〔若〕。","sentenceOrder":221},
  {"id":"s_work_han_thu_26_222","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「馮馮，盛滿也。翼翼，眾貌也。」","sentenceOrder":222},
  {"id":"s_work_han_thu_26_223","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　晉灼曰：「易，疆易也。久，固也。武帝自言拓境廣遠安固也。」師古曰：「此說非也。久猶長也，自言疆易遠大耳。非武帝時也，不得云拓境。」","sentenceOrder":223},
  {"id":"s_work_han_thu_26_224","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「若，順也。休亦美也。」","sentenceOrder":224},
  {"id":"s_work_han_thu_26_225","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「綽，緩也，亦謂延長也。」","sentenceOrder":225},
  {"id":"s_work_han_thu_26_226","chapterId":"ch_work_han_thu_26","textTraditional":"磑磑即即，師象山則。〔一〕烏呼孝哉，案撫戎國。蠻夷竭歡，象來致福。〔二〕兼臨是愛，終無兵革。〔三〕","sentenceOrder":226},
  {"id":"s_work_han_thu_26_227","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　孟康曰：「磑磑，崇積也。即即，充實也。師，眾也。則，法也。積實之盛眾類於山也。」師古曰：「磑音五回反。」","sentenceOrder":227},
  {"id":"s_work_han_thu_26_228","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　李奇曰：「象，譯也。蠻夷遣（擇）〔譯〕致福貢也。」","sentenceOrder":228},
  {"id":"s_work_han_thu_26_229","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「兼臨，言在上位者普包容也。」","sentenceOrder":229},
  {"id":"s_work_han_thu_26_230","chapterId":"ch_work_han_thu_26","textTraditional":"嘉薦芳矣，告靈饗矣。告靈既饗，德音孔臧。〔一〕惟德之臧，建侯之常。承保天休，令問不忘。〔二〕","sentenceOrder":230},
  {"id":"s_work_han_thu_26_231","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「饗字合韻皆音鄉。孔，甚也。臧，善也。」","sentenceOrder":231},
  {"id":"s_work_han_thu_26_232","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「建侯，封建諸侯也。易屯卦曰『利建侯』。休，美也。令，善也。問，名也。」","sentenceOrder":232},
  {"id":"s_work_han_thu_26_233","chapterId":"ch_work_han_thu_26","textTraditional":"皇皇鴻明，蕩侯休德。〔一〕嘉承天和，伊樂厥福。〔二〕在樂不荒，惟民之則。〔三〕","sentenceOrder":233},
  {"id":"s_work_han_thu_26_234","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　服虔曰：「侯，惟也。」臣瓚曰：「天下蕩平，惟帝之休德。」","sentenceOrder":234},
  {"id":"s_work_han_thu_26_235","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「伊，是也。」","sentenceOrder":235},
  {"id":"s_work_han_thu_26_236","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「則，法也。」","sentenceOrder":236},
  {"id":"s_work_han_thu_26_237","chapterId":"ch_work_han_thu_26","textTraditional":"浚則師德，下民咸殖。令問在舊，孔容翼翼。〔一〕","sentenceOrder":237},
  {"id":"s_work_han_thu_26_238","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「浚，深也。師，眾也。則，法也。殖，生也。舊，久也。翼翼，敬也。言有深法眾德，故能生育群黎，久有善名，其容甚敬也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_26_239","chapterId":"ch_work_han_thu_26","textTraditional":"孔容之常，承帝之明。〔一〕下民之樂，子孫保光。〔二〕承順溫良，受帝之光。嘉薦令芳，壽考不忘。〔三〕","sentenceOrder":239},
  {"id":"s_work_han_thu_26_240","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「帝謂天也。下皆類此。」","sentenceOrder":240},
  {"id":"s_work_han_thu_26_241","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「言永保其光寵也。」","sentenceOrder":241},
  {"id":"s_work_han_thu_26_242","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「不忘，言長久也。」","sentenceOrder":242},
  {"id":"s_work_han_thu_26_243","chapterId":"ch_work_han_thu_26","textTraditional":"承帝明德，師象山則。〔一〕雲施稱民，永受厥福。〔二〕承容之常，承帝之明。下民安樂，受福無疆。〔三〕","sentenceOrder":243},
  {"id":"s_work_han_thu_26_244","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「眾象山而為法，言不騫不崩。」","sentenceOrder":244},
  {"id":"s_work_han_thu_26_245","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「言稱物平施，其澤如雲也。稱音尺孕反。」","sentenceOrder":245},
  {"id":"s_work_han_thu_26_246","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「疆，竟也。下皆類此。」","sentenceOrder":246},
  {"id":"s_work_han_thu_26_247","chapterId":"ch_work_han_thu_26","textTraditional":"郊祀歌十九章，其詩曰：","sentenceOrder":247},
  {"id":"s_work_han_thu_26_248","chapterId":"ch_work_han_thu_26","textTraditional":"練時日，侯有望，〔一〕〈火苪〉膋蕭，延四方。〔二〕九重開，靈之斿，〔三〕垂惠恩，鴻祜休。〔四〕靈之車，結玄雲，駕飛龍，羽旄紛。〔五〕靈之下，若風馬，〔六〕左倉龍，右白虎。〔七〕靈之來，神哉沛，〔八〕先以雨，般裔裔。〔九〕靈之至，慶陰陰〔一０〕，相放怫，震澹心。〔一一〕靈已坐，五音飭，〔一二〕虞至旦，承靈億。〔一三〕牲繭栗，粢盛香，尊桂酒，賓八鄉。〔一四〕靈安留，吟青黃，〔一五〕遍觀此，眺瑤堂。〔一六〕眾嫭並，綽奇麗，〔一七〕顏如荼，兆逐靡。〔一八〕被華文，廁霧縠，曳阿錫，佩珠玉。〔一九〕俠嘉夜，茝蘭芳，〔二０〕澹容與，獻嘉觴。〔二一〕練時日一","sentenceOrder":248},
  {"id":"s_work_han_thu_26_249","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「練，選也。」","sentenceOrder":249},
  {"id":"s_work_han_thu_26_250","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　李奇曰：「膋，腸間脂也。蕭，香蒿也。」師古曰：「以蕭〈火苪〉脂合馨香也。四方，四方之神也。膋音來彫反。〈火苪〉音人說反。」","sentenceOrder":250},
  {"id":"s_work_han_thu_26_251","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「天有九重，言皆開門而來降厥福。」","sentenceOrder":251},
  {"id":"s_work_han_thu_26_252","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「鴻，大也。祜，福也。休，美也。祜音怙。」","sentenceOrder":252},
  {"id":"s_work_han_thu_26_253","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「紛紛，言其多。」","sentenceOrder":253},
  {"id":"s_work_han_thu_26_254","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「言速疾也。」","sentenceOrder":254},
  {"id":"s_work_han_thu_26_255","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　師古曰：「以為衛。」","sentenceOrder":255},
  {"id":"s_work_han_thu_26_256","chapterId":"ch_work_han_thu_26","textTraditional":"〔八〕　師古曰：「沛，疾貌，音補蓋反。」","sentenceOrder":256},
  {"id":"s_work_han_thu_26_257","chapterId":"ch_work_han_thu_26","textTraditional":"〔九〕　師古曰：「先以雨，言神欲行，令雨先驅也。般讀與班同。班，布也。裔裔，飛流之貌。」","sentenceOrder":257},
  {"id":"s_work_han_thu_26_258","chapterId":"ch_work_han_thu_26","textTraditional":"〔一０〕師古曰：「言垂陰覆遍於下。」","sentenceOrder":258},
  {"id":"s_work_han_thu_26_259","chapterId":"ch_work_han_thu_26","textTraditional":"〔一一〕師古曰：「放怫猶髣彿也。澹，動也。放音昉。怫音沸。澹音大濫反。」","sentenceOrder":259},
  {"id":"s_work_han_thu_26_260","chapterId":"ch_work_han_thu_26","textTraditional":"〔一二〕師古曰：「飭讀與敕字同，謂整也。」","sentenceOrder":260},
  {"id":"s_work_han_thu_26_261","chapterId":"ch_work_han_thu_26","textTraditional":"〔一三〕師古曰：「虞，樂也。億，安也。」","sentenceOrder":261},
  {"id":"s_work_han_thu_26_262","chapterId":"ch_work_han_thu_26","textTraditional":"〔一四〕應劭曰：「桂酒，切桂置酒中也。」晉灼曰：「尊，大尊也。元帝時大宰丞李元記云『以水漬桂，為大尊酒』。」師古曰：「繭栗，言角之小如繭及栗之形也。八鄉，八方之神。」","sentenceOrder":262},
  {"id":"s_work_han_thu_26_263","chapterId":"ch_work_han_thu_26","textTraditional":"〔一五〕服虔曰：「吟音含。」師古曰：「服說非也。吟謂歌誦也。青黃，謂四時之樂也。」","sentenceOrder":263},
  {"id":"s_work_han_thu_26_264","chapterId":"ch_work_han_thu_26","textTraditional":"〔一六〕應劭曰：「眺，望也。瑤，石而似玉者也。」師古曰：「以瑤飾堂。瑤音遙。」","sentenceOrder":264},
  {"id":"s_work_han_thu_26_265","chapterId":"ch_work_han_thu_26","textTraditional":"〔一七〕孟康曰：「嫭音互。嫭，好也。」如淳曰：「嫭，美目貌。」晉灼曰：「嫭音坼罅之罅。」師古曰：「孟說是也。謂供神女樂，並好麗也。」","sentenceOrder":265},
  {"id":"s_work_han_thu_26_266","chapterId":"ch_work_han_thu_26","textTraditional":"〔一八〕應劭曰：「荼，野菅白華也。言此奇麗，白如荼也。」孟康曰：「兆逐靡者，兆民逐觀而猗靡也。」師古曰：「菅，茅也。言美女顏貌如茅荼之柔也。荼者，今俗所謂蒹錐也。荼音塗。菅音姦。靡，合韻音武義反。」","sentenceOrder":266},
  {"id":"s_work_han_thu_26_267","chapterId":"ch_work_han_thu_26","textTraditional":"〔一九〕如淳曰：「阿，細繒。錫，細布也。」師古曰：「廁，雜也。霧縠，言其輕細若雲霧也。」","sentenceOrder":267},
  {"id":"s_work_han_thu_26_268","chapterId":"ch_work_han_thu_26","textTraditional":"〔二０〕如淳曰：「佳、俠，皆美人之稱。嘉夜，芳草也。」師古曰：「俠與挾同，言懷挾芳草也。茝即今白芷。茝音昌改反。」","sentenceOrder":268},
  {"id":"s_work_han_thu_26_269","chapterId":"ch_work_han_thu_26","textTraditional":"〔二一〕師古曰：「澹，安也。容與，言閑舒也。澹音大濫反。」","sentenceOrder":269},
  {"id":"s_work_han_thu_26_270","chapterId":"ch_work_han_thu_26","textTraditional":"帝臨中壇，四方承宇，〔一〕繩繩意變，備得其所。〔二〕清和六合，制數以五。〔三〕海內安寧，興文匽武。〔四〕后土富媼，昭明三光。〔五〕穆穆優游，嘉服上黃。〔六〕帝臨二","sentenceOrder":270},
  {"id":"s_work_han_thu_26_271","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「言天神尊者來降中壇，四方之神各承四宇也。壇字或作襢，讀亦曰壇。字加示者，神靈之耳。下言紫壇、嘉壇，其義並同。」","sentenceOrder":271},
  {"id":"s_work_han_thu_26_272","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　應劭曰：「繩繩，謹敬更正意也。」孟康曰：「眾多也。」臣瓚曰：「爾雅曰『繩繩，戒也』。」師古曰：「瓚說是也。」","sentenceOrder":272},
  {"id":"s_work_han_thu_26_273","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　張晏曰：「此后土之歌也。土數五。」","sentenceOrder":273},
  {"id":"s_work_han_thu_26_274","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「匽，古偃字。」","sentenceOrder":274},
  {"id":"s_work_han_thu_26_275","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　張晏曰：「媼，老母稱也。坤為母，故稱媼。海內安定，富媼之功耳。」","sentenceOrder":275},
  {"id":"s_work_han_thu_26_276","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　孟康曰：「土色上黃也。」","sentenceOrder":276},
  {"id":"s_work_han_thu_26_277","chapterId":"ch_work_han_thu_26","textTraditional":"青陽開動，根荄以遂，〔一〕膏潤并愛，跂行畢逮。〔二〕霆聲發榮，壧處頃聽，〔三〕枯槁復產，乃成厥命。〔四〕眾庶熙熙，施及夭胎，〔五〕群生啿啿，惟春之祺。〔六〕","sentenceOrder":277},
  {"id":"s_work_han_thu_26_278","chapterId":"ch_work_han_thu_26","textTraditional":"青陽三　鄒子樂。","sentenceOrder":278},
  {"id":"s_work_han_thu_26_279","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　臣瓚曰：「春為青陽。」師古曰：「草根曰荄。遂者，言皆生出也。荄音該。」","sentenceOrder":279},
  {"id":"s_work_han_thu_26_280","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　孟康曰：「跂音岐。」師古曰：「并，兼也。逮，及也。凡有足而行者，稱跂行也。」","sentenceOrder":280},
  {"id":"s_work_han_thu_26_281","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　晉灼曰：「壧，穴也。謂蟄蟲驚聽也。」師古曰：「壧與巖同。言雷霆始發，草木舒榮，則蟄蟲處巖崖者，莫不頃聽而起。頃讀曰傾。」","sentenceOrder":281},
  {"id":"s_work_han_thu_26_282","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「枯槁，謂草木經冬零落者也。槁音口老反。」","sentenceOrder":282},
  {"id":"s_work_han_thu_26_283","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「熙熙，和樂貌也。施，延也。少長曰夭，在孕曰胎。施音弋豉反。夭音烏老反。」","sentenceOrder":283},
  {"id":"s_work_han_thu_26_284","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　服虔曰：「啿音『湛湛露斯』。」如淳曰：「祺，福也。」師古曰：「啿啿，豐厚之貌也，音徒感反。祺音其。」","sentenceOrder":284},
  {"id":"s_work_han_thu_26_285","chapterId":"ch_work_han_thu_26","textTraditional":"朱明盛長，旉與萬物，〔一〕桐生茂豫，靡有所詘。〔二〕敷華就實，既阜既昌，〔三〕登成甫田，百鬼迪嘗。〔四〕廣大建祀，肅雍不忘，神若宥之，傳世無疆。〔五〕","sentenceOrder":285},
  {"id":"s_work_han_thu_26_286","chapterId":"ch_work_han_thu_26","textTraditional":"朱明四　鄒子樂。","sentenceOrder":286},
  {"id":"s_work_han_thu_26_287","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　臣瓚曰：「夏為朱明。」師古曰：「旉，古敷字也。旉與，言開舒也。與音弋於反。」","sentenceOrder":287},
  {"id":"s_work_han_thu_26_288","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「桐讀為通。茂豫，美盛而光悅也。言草木皆通達而生，美悅光澤，各無所詘，皆申遂也。詘音丘物反。」","sentenceOrder":288},
  {"id":"s_work_han_thu_26_289","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「敷，布也。就，成也。阜，大也。昌，盛也。」","sentenceOrder":289},
  {"id":"s_work_han_thu_26_290","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「甫田，大田也。百鬼，百神也。迪，進也。嘗謂歆饗之也。言此粢盛，皆因大田而登成，進於祀所，而為百神所歆饗也。迪音大歷反。」","sentenceOrder":290},
  {"id":"s_work_han_thu_26_291","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「若，善也。宥，祐也。」","sentenceOrder":291},
  {"id":"s_work_han_thu_26_292","chapterId":"ch_work_han_thu_26","textTraditional":"西顥沆碭，秋氣肅殺，〔一〕含秀垂穎，續舊不廢。〔二〕姦偽不萌，祅孽伏息，隅辟越遠，四貉咸服。〔三〕既畏茲威，惟慕純德，附而不驕，正心翊翊。〔四〕","sentenceOrder":292},
  {"id":"s_work_han_thu_26_293","chapterId":"ch_work_han_thu_26","textTraditional":"西顥五　鄒子樂。","sentenceOrder":293},
  {"id":"s_work_han_thu_26_294","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　韋昭曰：「西方少昊也。」師古曰：「沆音胡浪反。碭音蕩。沆碭，白氣之貌也。」","sentenceOrder":294},
  {"id":"s_work_han_thu_26_295","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「五穀百草，秀穎成實，皆因舊苗，無廢絕也。不榮而實曰秀，葉末曰穎。廢合韻音發。」","sentenceOrder":295},
  {"id":"s_work_han_thu_26_296","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「四貉猶言四夷。辟讀曰僻。貉音莫客反。」","sentenceOrder":296},
  {"id":"s_work_han_thu_26_297","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「純，大也。言畏威懷德，皆來賓附，無敢驕怠，盡虔敬。」","sentenceOrder":297},
  {"id":"s_work_han_thu_26_298","chapterId":"ch_work_han_thu_26","textTraditional":"玄冥陵陰，蟄蟲蓋臧，〔一〕屮木零落，抵冬降霜。〔二〕易亂除邪，革正異俗，〔三〕兆民反本，抱素懷樸。條理信義，望禮五嶽。〔四〕籍斂之時，掩收嘉穀。〔五〕","sentenceOrder":298},
  {"id":"s_work_han_thu_26_299","chapterId":"ch_work_han_thu_26","textTraditional":"玄冥六　鄒子樂。","sentenceOrder":299},
  {"id":"s_work_han_thu_26_300","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「玄冥，北方之神也。」","sentenceOrder":300},
  {"id":"s_work_han_thu_26_301","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　孟康曰：「抵，至也，至冬而降霜，音底。」師古曰：「屮，古草字。」","sentenceOrder":301},
  {"id":"s_work_han_thu_26_302","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「易，變；革，改也。」","sentenceOrder":302},
  {"id":"s_work_han_thu_26_303","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「條，分也，暢也。」","sentenceOrder":303},
  {"id":"s_work_han_thu_26_304","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「籍斂，謂收籍田也。」","sentenceOrder":304},
  {"id":"s_work_han_thu_26_305","chapterId":"ch_work_han_thu_26","textTraditional":"惟泰元尊，媼神蕃釐，〔一〕經緯天地，作成四時。精建日月，星辰度理，陰陽五行，周而復始。雲風雷電，降甘露雨，百姓蕃滋，咸循厥緒。〔二〕繼統共勤，順皇之德，〔三〕鸞路龍鱗，罔不肸飾。〔四〕嘉籩列陳，庶幾宴享，〔五〕滅除凶災，（列）〔烈〕騰八荒。〔六〕鐘鼓竽笙，雲舞翔翔，招搖靈旗，九夷賓將。〔七〕","sentenceOrder":305},
  {"id":"s_work_han_thu_26_306","chapterId":"ch_work_han_thu_26","textTraditional":"惟泰元七　建始元年，丞相匡衡奏罷「鸞路龍鱗」，更定詩曰「涓選休成」。〔八〕","sentenceOrder":306},
  {"id":"s_work_han_thu_26_307","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　李奇曰：「元尊，天也。媼神，地也。祭天燔燎，祭地瘞埋也。」師古曰：「李說非也。泰元，天也。蕃，多也。釐，福也。言天神至尊，而地神多福也。蕃音扶元反。釐讀曰禧。」","sentenceOrder":307},
  {"id":"s_work_han_thu_26_308","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「蕃，多也。滋，益也。循，順也。緒，業也。」","sentenceOrder":308},
  {"id":"s_work_han_thu_26_309","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「共讀曰恭。皇，皇天也。此言天子繼承祖統，恭勤為心而順天也。」","sentenceOrder":309},
  {"id":"s_work_han_thu_26_310","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　蘇林曰：「肸音塈塗之塈。塈，飾也。」師古曰：「罔，無也。肸，振也。謂皆振整而飾之也。肸音許乙反。」","sentenceOrder":310},
  {"id":"s_work_han_thu_26_311","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「嘉籩，謂祭祀之籩實也。木曰豆，竹曰籩。享字合韻宜（因）〔音〕鄉。」","sentenceOrder":311},
  {"id":"s_work_han_thu_26_312","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「言威烈之盛，踰於八荒。」","sentenceOrder":312},
  {"id":"s_work_han_thu_26_313","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　師古曰：「畫招搖於旗以征伐，故稱靈旗。將猶從也。」","sentenceOrder":313},
  {"id":"s_work_han_thu_26_314","chapterId":"ch_work_han_thu_26","textTraditional":"〔八〕　臣瓚曰：「涓，除也。除惡選取美成者也。」","sentenceOrder":314},
  {"id":"s_work_han_thu_26_315","chapterId":"ch_work_han_thu_26","textTraditional":"天地並況，惟予有慕，〔一〕爰熙紫壇，思求厥路。〔二〕恭承禋祀，縕豫為紛，〔三〕黼繡周張，承神至尊。〔四〕千童羅舞成八溢，〔五〕合好效歡虞泰一。〔六〕九歌畢奏斐然殊，鳴琴竽瑟會軒朱。〔七〕璆磬金鼓，靈其有喜，〔八〕百官濟濟，各敬厥事。盛牲實俎進聞膏，〔九〕神奄留，臨須搖。〔一０〕長麗前掞光燿明〔一一〕，寒暑不忒況皇章。〔一二〕展詩應律鋗玉鳴，〔一三〕函宮吐角激徵清。發梁揚羽申以商，〔一四〕造茲新音永久長。聲氣遠條鳳鳥鴹，〔一五〕神夕奄虞蓋孔享。〔一六〕","sentenceOrder":315},
  {"id":"s_work_han_thu_26_316","chapterId":"ch_work_han_thu_26","textTraditional":"天地八　丞相匡衡奏罷「黼繡周張」，更定詩曰「肅若舊典」。〔一七〕","sentenceOrder":316},
  {"id":"s_work_han_thu_26_317","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「況，賜也。」","sentenceOrder":317},
  {"id":"s_work_han_thu_26_318","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「熙，興也。紫壇，壇紫色也。思求降神之路也。」","sentenceOrder":318},
  {"id":"s_work_han_thu_26_319","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　孟康曰：「積聚脩飾，為此紛華也。」師古曰：「縕音於粉反。」","sentenceOrder":319},
  {"id":"s_work_han_thu_26_320","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「白與黑畫為斧形謂之黼。」","sentenceOrder":320},
  {"id":"s_work_han_thu_26_321","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「溢與佾同。佾，列也。」","sentenceOrder":321},
  {"id":"s_work_han_thu_26_322","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「虞與娛同。」","sentenceOrder":322},
  {"id":"s_work_han_thu_26_323","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　師古曰：「軒朱即朱軒也。言總合音樂，會於軒檻之前。」","sentenceOrder":323},
  {"id":"s_work_han_thu_26_324","chapterId":"ch_work_han_thu_26","textTraditional":"〔八〕　師古曰：「璆，美玉名，以為磬也。喜，合韻音許吏反。」","sentenceOrder":324},
  {"id":"s_work_han_thu_26_325","chapterId":"ch_work_han_thu_26","textTraditional":"〔九〕　師古曰：「言以牲實俎，以蕭〈火苪〉脂，則其芬馨達於神所，故曰盛牲實俎進聞膏。」","sentenceOrder":325},
  {"id":"s_work_han_thu_26_326","chapterId":"ch_work_han_thu_26","textTraditional":"〔一０〕晉灼曰：「須搖，須臾也。」師古曰：「奄讀曰淹。」","sentenceOrder":326},
  {"id":"s_work_han_thu_26_327","chapterId":"ch_work_han_thu_26","textTraditional":"〔一一〕孟康曰：「欲令神宿留，言日雖暮，長更星在前扶助，常有光明也。掞或作扶。」晉灼曰：「掞即光炎字也。」臣瓚曰：「長麗，靈鳥也。故相如賦曰『前長麗而後矞皇』。舊說云鸞也。張衡思玄賦亦曰『前長麗使拂羽』。」師古曰：「晉、瓚二說是也。麗音離。掞音豔。」","sentenceOrder":327},
  {"id":"s_work_han_thu_26_328","chapterId":"ch_work_han_thu_26","textTraditional":"〔一二〕晉灼曰：「況，賜也。皇，君也。章，明也。言長更星終始不改其光，神永以此明賜君也。」臣瓚曰：「忒，差也。寒暑不差，言陰陽和也，以此賜君，章賢德也。」師古曰：「瓚說是也。」","sentenceOrder":328},
  {"id":"s_work_han_thu_26_329","chapterId":"ch_work_han_thu_26","textTraditional":"〔一三〕晉灼曰：「鋗，鳴玉聲也。」師古曰：「鋗音火玄反。」","sentenceOrder":329},
  {"id":"s_work_han_thu_26_330","chapterId":"ch_work_han_thu_26","textTraditional":"〔一四〕晉灼曰：「下有『梁黃鼓員四人』，似新造音樂者姓名也。」師古曰：「晉說非也。自函宮吐角以下，總言五聲之備耳。申，重也。發梁，歌聲繞梁也。函與含同。」","sentenceOrder":330},
  {"id":"s_work_han_thu_26_331","chapterId":"ch_work_han_thu_26","textTraditional":"〔一五〕師古曰：「條，達也。鴹，古翔字。」","sentenceOrder":331},
  {"id":"s_work_han_thu_26_332","chapterId":"ch_work_han_thu_26","textTraditional":"〔一六〕師古曰：「虞，樂也。蓋，語辭也。孔，甚也。享，合韻音鄉。」","sentenceOrder":332},
  {"id":"s_work_han_thu_26_333","chapterId":"ch_work_han_thu_26","textTraditional":"〔一七〕師古曰：「肅，敬也。若，順也。」","sentenceOrder":333},
  {"id":"s_work_han_thu_26_334","chapterId":"ch_work_han_thu_26","textTraditional":"日出入安窮？時世不與人同。〔一〕故春非我春，夏非我夏，秋非我秋，冬非我冬。泊如四海之池，遍觀是邪謂何？〔二〕吾知所樂，獨樂六龍，六龍之調，使我心若。〔三〕訾黃其何不徠下〔四〕！","sentenceOrder":334},
  {"id":"s_work_han_thu_26_335","chapterId":"ch_work_han_thu_26","textTraditional":"日出入九","sentenceOrder":335},
  {"id":"s_work_han_thu_26_336","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　晉灼曰：「日月無窮，，而人命有終，世長而壽短。」","sentenceOrder":336},
  {"id":"s_work_han_thu_26_337","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　晉灼曰：「言人壽不能安固如四海，遍觀是，乃知命甚促。謂何，當如之何也。」師古曰：「泊，水貌也，音步各反，又音魄。」","sentenceOrder":337},
  {"id":"s_work_han_thu_26_338","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　應劭曰：「易曰『時乘六龍以御天』。武帝願乘六龍，仙而升天，曰『吾所樂獨乘六龍然，御六龍得其調，使我心若』。」","sentenceOrder":338},
  {"id":"s_work_han_thu_26_339","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　應劭曰：「訾黃一名乘黃，龍翼而馬身，黃帝乘之而仙。武帝意欲得之，曰：『何不來邪？』」師古曰：「訾，嗟歎之辭也。黃，乘黃也。歎乘黃不來下也。訾音咨。」","sentenceOrder":339},
  {"id":"s_work_han_thu_26_340","chapterId":"ch_work_han_thu_26","textTraditional":"太一況，天馬下，〔一〕霑赤汗，沬流赭。〔二〕志俶儻，精權奇，籋浮雲，晻上馳。〔三〕體容與，迣萬里，〔四〕今安匹，龍為友。〔五〕　元狩三年馬生渥洼水中作。","sentenceOrder":340},
  {"id":"s_work_han_thu_26_341","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「言此天馬乃太一所賜，故來下也。」","sentenceOrder":341},
  {"id":"s_work_han_thu_26_342","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　應劭曰：「大宛馬汗血霑濡也，流沬如赭也。」李奇曰：「沬音靧面之靧。」晉灼曰：「沬，古靧字也。」師古曰：「沬、沫兩通。沬者，言被面如頮也，字從水傍午未之未，音呼內反。沫者，言汗流沫出也，字從水傍本末之末，音亦如之。然今書字多作沬面之沬也。」","sentenceOrder":342},
  {"id":"s_work_han_thu_26_343","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　蘇林曰：「籋音躡。言天馬上躡浮雲也。」師古曰：「晻音烏感反。言晻然而上馳。」","sentenceOrder":343},
  {"id":"s_work_han_thu_26_344","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　孟康曰：「迣音逝。」如淳曰：「迣，超踰也。」晉灼曰：「古迾字。」師古曰：「孟音非也。迣讀與厲同，言能厲渡萬里也。」","sentenceOrder":344},
  {"id":"s_work_han_thu_26_345","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「言今更無與匹者，唯龍可為之友耳。」","sentenceOrder":345},
  {"id":"s_work_han_thu_26_346","chapterId":"ch_work_han_thu_26","textTraditional":"天馬徠，從西極，涉流沙，九夷服。〔一〕天馬徠，出泉水，虎脊兩，化若鬼。〔二〕天馬徠，歷無草，徑千里，循東道。〔三〕天馬徠，執徐時，〔四〕將搖舉，誰與期？〔五〕天馬徠，開遠門，竦予身，逝昆侖。〔六〕天馬徠，龍之媒，〔七〕游閶闔，觀玉臺。〔八〕　太初四年誅宛王獲宛馬作。","sentenceOrder":346},
  {"id":"s_work_han_thu_26_347","chapterId":"ch_work_han_thu_26","textTraditional":"天馬十","sentenceOrder":347},
  {"id":"s_work_han_thu_26_348","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「言九夷皆服，故此馬遠來也。徠，古往來字也。」","sentenceOrder":348},
  {"id":"s_work_han_thu_26_349","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　應劭曰：「馬毛色如虎脊〔者〕有兩也。」師古曰：「言其變化若鬼神。」","sentenceOrder":349},
  {"id":"s_work_han_thu_26_350","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　張晏曰：「馬從西而來東也。」師古曰：「言馬從西來，經行磧鹵之地無草者，（幾）〔凡〕千里而至東道。」","sentenceOrder":350},
  {"id":"s_work_han_thu_26_351","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　應劭曰：「太歲在辰曰執徐。言得天馬時歲在辰也。」孟康曰：「東方震為龍，又青龍宿。言以其方來也。」師古曰：「應說是也。」","sentenceOrder":351},
  {"id":"s_work_han_thu_26_352","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　如淳曰：「遙，遠也。搖或作遙。」師古曰：「如說非也。言當奮搖高舉，不可與期也。」","sentenceOrder":352},
  {"id":"s_work_han_thu_26_353","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　應劭曰：「言天馬雖去人遠，當豫開門以待之也。」文穎曰：「言武帝好仙，常庶幾天馬來，當乘之往發昆侖也。」師古曰：「文說是也。」","sentenceOrder":353},
  {"id":"s_work_han_thu_26_354","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　應劭曰：「言天馬者乃神龍之類，今天馬已來，此龍必至之效也。」","sentenceOrder":354},
  {"id":"s_work_han_thu_26_355","chapterId":"ch_work_han_thu_26","textTraditional":"〔八〕　應劭曰：「閶闔，天門。玉臺，上帝之所居。」","sentenceOrder":355},
  {"id":"s_work_han_thu_26_356","chapterId":"ch_work_han_thu_26","textTraditional":"天門開，詄蕩蕩，〔一〕穆並騁，以臨饗。〔二〕光夜燭，德信著，〔三〕靈〈寖，中“彐改帚”〉（平而）鴻，長生豫。〔四〕大朱涂廣，夷石為堂，〔五〕飾玉梢以舞歌，體招搖若永望。〔六〕星留俞，塞隕光，〔七〕照紫幄，珠熉黃。〔八〕幡比翄回集，貳雙飛常羊。〔九〕月穆穆以金波，日華燿以宣明。〔一０〕假清風軋忽，激長至重觴。〔一一〕神裴回若留放，殣冀親以肆章。〔一二〕函蒙祉福常若期，〔一三〕寂漻上天知厥時。〔一四〕泛泛滇滇從高斿，〔一五〕殷勤此路臚所求。〔一六〕佻正嘉吉弘以昌，〔一七〕休嘉砰隱溢四方。〔一八〕專精厲意逝九閡，〔一九〕紛云六幕浮大海。〔二０〕","sentenceOrder":356},
  {"id":"s_work_han_thu_26_357","chapterId":"ch_work_han_thu_26","textTraditional":"天門十一","sentenceOrder":357},
  {"id":"s_work_han_thu_26_358","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　如淳曰：「詄讀如迭。詄蕩蕩，天體堅清之狀也。」師古曰：「詄音大結反。」","sentenceOrder":358},
  {"id":"s_work_han_thu_26_359","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「言眾神穆然方駕馳騁而臨祠祭。」","sentenceOrder":359},
  {"id":"s_work_han_thu_26_360","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「神光夜照，應誠而來，是德信著明。」","sentenceOrder":360},
  {"id":"s_work_han_thu_26_361","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「神靈德澤所浸，溥博無私，其福甚大，故我得長生之道而安豫也。」","sentenceOrder":361},
  {"id":"s_work_han_thu_26_362","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「涂，道路也。夷，平也。言通神之路，飾以朱丹，又甚廣大。平夷密石，累以為堂。」","sentenceOrder":362},
  {"id":"s_work_han_thu_26_363","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「梢，竿也，舞者所持。玉梢，以玉飾之也。招搖，申動之貌。永，長也。梢音所交反。招音韶。望，合韻音亡。」","sentenceOrder":363},
  {"id":"s_work_han_thu_26_364","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　師古曰：「俞，答也。言眾星留神，答我饗薦，降其光燿，四面充塞也。俞音踰。」","sentenceOrder":364},
  {"id":"s_work_han_thu_26_365","chapterId":"ch_work_han_thu_26","textTraditional":"〔八〕　如淳曰：「熉音殞，黃貌也。」師古曰：「紫幄，饗神之幄也。帳上四下而覆曰幄。言光照紫幄，故其珠色熉然而黃也。熉音云。」","sentenceOrder":365},
  {"id":"s_work_han_thu_26_366","chapterId":"ch_work_han_thu_26","textTraditional":"〔九〕　文穎曰：「舞者骨騰肉飛，如鳥之回翅而雙集也。」師古曰：「常羊，猶逍遙也。」","sentenceOrder":366},
  {"id":"s_work_han_thu_26_367","chapterId":"ch_work_han_thu_26","textTraditional":"〔一０〕師古曰：「言月光穆穆，若金之波流也。宣，遍也。」","sentenceOrder":367},
  {"id":"s_work_han_thu_26_368","chapterId":"ch_work_han_thu_26","textTraditional":"〔一一〕師古曰：「軋忽，長遠之貌也。重觴，謂累獻也。」","sentenceOrder":368},
  {"id":"s_work_han_thu_26_369","chapterId":"ch_work_han_thu_26","textTraditional":"〔一二〕孟康曰：「殣音覲。」師古曰：「言神靈裴回，留而不去，故我得覲見，冀以親附而陳誠意，遂章明之。」","sentenceOrder":369},
  {"id":"s_work_han_thu_26_370","chapterId":"ch_work_han_thu_26","textTraditional":"〔一三〕師古曰：「函，包也。蒙，被也。言為神所饗，故能包函蒙被祉福，應誠而至，有常期也。」","sentenceOrder":370},
  {"id":"s_work_han_thu_26_371","chapterId":"ch_work_han_thu_26","textTraditional":"〔一四〕應劭曰：「言天雖寂漻高遠，而知我饗薦之時也。漻音來朝反。」","sentenceOrder":371},
  {"id":"s_work_han_thu_26_372","chapterId":"ch_work_han_thu_26","textTraditional":"〔一五〕應劭曰：「泛泛，上浮之意也。滇滇，盛貌也。」晉灼曰：「滇音『振旅闐闐』。」師古曰：「音徒千反。」","sentenceOrder":372},
  {"id":"s_work_han_thu_26_373","chapterId":"ch_work_han_thu_26","textTraditional":"〔一六〕應劭曰：「臚，陳也。言所以殷勤此路，乃欲陳所求也。」師古曰：「臚音力於反。」","sentenceOrder":373},
  {"id":"s_work_han_thu_26_374","chapterId":"ch_work_han_thu_26","textTraditional":"〔一七〕如淳曰：「佻讀曰肇。肇，始也。」","sentenceOrder":374},
  {"id":"s_work_han_thu_26_375","chapterId":"ch_work_han_thu_26","textTraditional":"〔一八〕師古曰：「休，美也。嘉，慶也。砰音普萌反。砰隱，盛意。」","sentenceOrder":375},
  {"id":"s_work_han_thu_26_376","chapterId":"ch_work_han_thu_26","textTraditional":"〔一九〕如淳曰：「閡亦陔也。淮南子曰若士者謂盧敖曰『吾與汗漫期乎九陔之上』。陔，重也。謂九天之上也。」師古曰：「閡，合韻音改，又音亥。」","sentenceOrder":376},
  {"id":"s_work_han_thu_26_377","chapterId":"ch_work_han_thu_26","textTraditional":"〔二０〕師古曰：「紛云，興作之貌。六幕，猶言六合也。」","sentenceOrder":377},
  {"id":"s_work_han_thu_26_378","chapterId":"ch_work_han_thu_26","textTraditional":"景星顯見，信星彪列，〔一〕象載昭庭，日親以察。〔二〕參侔開闔，爰推本紀，〔三〕汾脽出鼎，皇祜元始。〔四〕五音六律，依韋饗昭，〔五〕雜變並會，雅聲遠姚。〔六〕空桑琴瑟結信成，〔七〕四興遞代八風生。〔八〕殷殷鐘石羽籥鳴。〔九〕河龍供鯉醇犧牲。〔一０〕百末旨酒布蘭生。〔一一〕泰尊柘漿析朝酲。〔一二〕微感心攸通修名，〔一三〕周流常羊思所并。〔一四〕穰穰復正直往甯，〔一五〕馮蠵切和疏寫平。〔一六〕上天布施后土成，穰穰豐年四時榮。","sentenceOrder":378},
  {"id":"s_work_han_thu_26_379","chapterId":"ch_work_han_thu_26","textTraditional":"景星十二　元鼎五年得鼎汾陰作。","sentenceOrder":379},
  {"id":"s_work_han_thu_26_380","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　如淳曰：「景星者，德星也，見無常，常出有道之國。鎮星為信星，居國益地。」師古曰：「謂彰著而為行列也。」","sentenceOrder":380},
  {"id":"s_work_han_thu_26_381","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「象謂縣象也。載，事也。縣象祕事，昭顯於庭，日來親近，甚明察也。」","sentenceOrder":381},
  {"id":"s_work_han_thu_26_382","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　應劭曰：「參，三也。言景星光明開闔，乃三於日月也。」晉灼曰：「侔，等也。開闔，猶開闢也。言今之鼎瑞，參等於上世。」師古曰：「晉說是。」","sentenceOrder":382},
  {"id":"s_work_han_thu_26_383","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「皇，大也。祜，福也。脽音誰。祜音怙。」","sentenceOrder":383},
  {"id":"s_work_han_thu_26_384","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「依韋，諧和不相乖離也。饗讀曰響。昭，明也，言聲響之明也。」","sentenceOrder":384},
  {"id":"s_work_han_thu_26_385","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「姚，僄姚，言飛揚也。」","sentenceOrder":385},
  {"id":"s_work_han_thu_26_386","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　張晏曰：「傳曰『空桑為瑟，一彈三歎』，祭天質故也。」師古曰：「空桑，地名也，出善木，可為琴瑟也。」","sentenceOrder":386},
  {"id":"s_work_han_thu_26_387","chapterId":"ch_work_han_thu_26","textTraditional":"〔八〕　應劭曰：「四時遞代成陰陽，八風以生也。」臣瓚曰：「舞者四縣代奏也。左氏傳曰『夫舞者，所以節八音而行八風』也。」師古曰：「瓚說是也。八方之風，謂東北曰條風，東方曰明庶風，東南曰清明風，南方曰景風，西南曰涼風，西方曰閶闔風，西北曰不周風，北方曰廣莫風。」","sentenceOrder":387},
  {"id":"s_work_han_thu_26_388","chapterId":"ch_work_han_thu_26","textTraditional":"〔九〕　師古曰：「殷殷，聲盛也。石謂磬也。羽籥，韶舞所持者也。殷音隱。」","sentenceOrder":388},
  {"id":"s_work_han_thu_26_389","chapterId":"ch_work_han_thu_26","textTraditional":"〔一０〕晉灼曰：「河龍，夏之所賜者也。供鯉，給廚祭也。」師古曰：「醇謂色不雜也。犧牲，牛羊全體者也。」","sentenceOrder":389},
  {"id":"s_work_han_thu_26_390","chapterId":"ch_work_han_thu_26","textTraditional":"〔一一〕張晏曰：「百末，末作之末也。」晉灼曰：「百日之末酒也，芬香布列，若蘭之生也。」師古曰：「百末，百草華之末也。旨，美也。以百草華末雜酒，故香且美也。事見春秋繁露。」","sentenceOrder":390},
  {"id":"s_work_han_thu_26_391","chapterId":"ch_work_han_thu_26","textTraditional":"〔一二〕應劭曰：「柘漿，取甘柘汁以為飲也。酲，病酒也。析，解也。言柘漿可以解朝酲也。」","sentenceOrder":391},
  {"id":"s_work_han_thu_26_392","chapterId":"ch_work_han_thu_26","textTraditional":"〔一三〕師古曰：「言精微所應，其心攸遠，故得通達成長久之名。」","sentenceOrder":392},
  {"id":"s_work_han_thu_26_393","chapterId":"ch_work_han_thu_26","textTraditional":"〔一四〕師古曰：「周流，猶周行也。常羊，猶逍遙也。思所并，思與神道合也，下言合所思是也。」","sentenceOrder":393},
  {"id":"s_work_han_thu_26_394","chapterId":"ch_work_han_thu_26","textTraditional":"〔一五〕師古曰：「穰穰，多也。復猶歸也。直，當也。甯，願也。言獲福既多，歸於正道，克當往日所願也。復音扶目反，甯合韻音寧。」","sentenceOrder":394},
  {"id":"s_work_han_thu_26_395","chapterId":"ch_work_han_thu_26","textTraditional":"〔一六〕晉灼曰：「馮，馮夷，河伯也。蠵，觜蠵，龜屬也。」師古曰：「言馮夷命靈蠵，使切厲諧和水神，令之疏導川潦，寫散平均，無災害也。蠵音弋隨反，又音攜。」","sentenceOrder":395},
  {"id":"s_work_han_thu_26_396","chapterId":"ch_work_han_thu_26","textTraditional":"齊房產草，九莖連葉，〔一〕宮童效異，披圖案諜。〔二〕玄氣之精，回復此都，〔三〕蔓蔓日茂，芝成靈華。〔四〕","sentenceOrder":396},
  {"id":"s_work_han_thu_26_397","chapterId":"ch_work_han_thu_26","textTraditional":"齊房十三　元封二年芝生甘泉齊房作。","sentenceOrder":397},
  {"id":"s_work_han_thu_26_398","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「齊讀曰齋。其下並同。」","sentenceOrder":398},
  {"id":"s_work_han_thu_26_399","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　臣瓚曰：「宮之童豎致此異瑞也。」蘇林曰：「諜，譜弟之也。」","sentenceOrder":399},
  {"id":"s_work_han_thu_26_400","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「玄，天也。言天氣之精，回旋反復於此雲陽之都，謂甘泉也。」","sentenceOrder":400},
  {"id":"s_work_han_thu_26_401","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「蔓蔓。言其長久，日以茂盛也。」","sentenceOrder":401},
  {"id":"s_work_han_thu_26_402","chapterId":"ch_work_han_thu_26","textTraditional":"后皇嘉壇，立玄黃服，〔一〕物發冀州，兆蒙祉福。〔二〕沇沇四塞，徦狄合處，〔三〕經營萬億，咸遂厥宇。〔四〕","sentenceOrder":402},
  {"id":"s_work_han_thu_26_403","chapterId":"ch_work_han_thu_26","textTraditional":"后皇十四","sentenceOrder":403},
  {"id":"s_work_han_thu_26_404","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「壇，祭壇也。服，祭服也。」","sentenceOrder":404},
  {"id":"s_work_han_thu_26_405","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　晉灼曰：「得寶鼎於汾陰也。」臣瓚曰：「汾陰屬冀州。」","sentenceOrder":405},
  {"id":"s_work_han_thu_26_406","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　孟康曰：「沇音兗。」師古曰：「沇沇，流行之貌也。徦狄，遠夷也。合處，內附也。徦即遐字耳，其字從彳。彳音丑益反。」","sentenceOrder":406},
  {"id":"s_work_han_thu_26_407","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「宇，居也。言我經營萬方億兆，故得咸遂其居。」","sentenceOrder":407},
  {"id":"s_work_han_thu_26_408","chapterId":"ch_work_han_thu_26","textTraditional":"華煜煜，固靈根。神之斿，過天門，車千乘，敦昆侖。〔一〕神之出，排玉房，周流雜，拔蘭堂。〔二〕神之行，旌容容，騎沓沓，般縱縱。〔三〕神之徠，泛翊翊，甘露降，慶雲集。〔四〕神之揄，臨壇宇，〔五〕九疑賓，夔龍舞。〔六〕神安坐，鴹吉時，〔七〕共翊翊，合所思。〔八〕神嘉虞，申貳觴，〔九〕福滂洋，邁延長。〔一０〕沛施祐，汾之阿，〔一一〕揚金光，橫泰河，〔一二〕莽若雲，增陽波。〔一三〕遍臚驩，騰天歌。〔一四〕","sentenceOrder":408},
  {"id":"s_work_han_thu_26_409","chapterId":"ch_work_han_thu_26","textTraditional":"華煜煜十五","sentenceOrder":409},
  {"id":"s_work_han_thu_26_410","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「敦讀曰屯。屯，聚也。」","sentenceOrder":410},
  {"id":"s_work_han_thu_26_411","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「拔。舍止也，音步曷反。」","sentenceOrder":411},
  {"id":"s_work_han_thu_26_412","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　孟康曰：「縱音總。」晉灼曰：「音人相傱勇作惡。」師古曰：「容容，飛揚之貌。沓沓，疾行也。般，相連也。縱縱，眾也。容音勇。縱音總。一曰容讀如本字，傱音才公反。」","sentenceOrder":412},
  {"id":"s_work_han_thu_26_413","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　如淳曰：「天文志云『若煙非煙，若雲非雲，郁郁紛紛，是謂慶雲』。」師古曰：「翊音弋入反，又音立。」","sentenceOrder":413},
  {"id":"s_work_han_thu_26_414","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「揄，引也。壇宇，謂祭祠壇場及宮室。言神引來降臨之也。揄音踰。」","sentenceOrder":414},
  {"id":"s_work_han_thu_26_415","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　如淳曰：「九疑，舜所葬。言以舜為賓客也。夔典樂，龍管納言，皆隨舜而來，舞以樂神。」","sentenceOrder":415},
  {"id":"s_work_han_thu_26_416","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　師古曰：「鴹，古翔字也。言神安坐回翔，皆趣吉時也。」","sentenceOrder":416},
  {"id":"s_work_han_thu_26_417","chapterId":"ch_work_han_thu_26","textTraditional":"〔八〕　師古曰：「共讀曰恭。翊翊，敬也。」","sentenceOrder":417},
  {"id":"s_work_han_thu_26_418","chapterId":"ch_work_han_thu_26","textTraditional":"〔九〕　師古曰：「虞，樂也。貳觴，猶重觴也。」","sentenceOrder":418},
  {"id":"s_work_han_thu_26_419","chapterId":"ch_work_han_thu_26","textTraditional":"〔一０〕師古曰：「滂洋，饒廣也。滂音普郎反。洋音羊，又音祥。」","sentenceOrder":419},
  {"id":"s_work_han_thu_26_420","chapterId":"ch_work_han_thu_26","textTraditional":"〔一一〕師古曰：「沛音普大反。沛然泛貌也。阿，水之曲隅。」","sentenceOrder":420},
  {"id":"s_work_han_thu_26_421","chapterId":"ch_work_han_thu_26","textTraditional":"〔一二〕師古曰：「橫，充滿也。泰河，大河也。」","sentenceOrder":421},
  {"id":"s_work_han_thu_26_422","chapterId":"ch_work_han_thu_26","textTraditional":"〔一三〕師古曰：「莽，雲貌。言光明之盛，莽莽然如雲也。」","sentenceOrder":422},
  {"id":"s_work_han_thu_26_423","chapterId":"ch_work_han_thu_26","textTraditional":"〔一四〕師古曰：「臚，陳也。騰，升也。言陳其歡慶，令歌上升於天。」","sentenceOrder":423},
  {"id":"s_work_han_thu_26_424","chapterId":"ch_work_han_thu_26","textTraditional":"五神相，包四鄰，〔一〕土地廣，揚浮雲。扢嘉壇，椒蘭芳，〔二〕璧玉精，垂華光。〔三〕益億年，美始興，〔四〕交於神，若有承。〔五〕廣宣延，咸畢觴，〔六〕靈輿位，偃蹇驤。〔七〕卉汨臚，析奚（道）〔遺〕？〔八〕淫淥澤，〈氵{山王}〉然歸。〔九〕","sentenceOrder":424},
  {"id":"s_work_han_thu_26_425","chapterId":"ch_work_han_thu_26","textTraditional":"五神十六","sentenceOrder":425},
  {"id":"s_work_han_thu_26_426","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　如淳曰：「五帝為太一相也。」師古曰：「包，含也。四鄰，四方。」","sentenceOrder":426},
  {"id":"s_work_han_thu_26_427","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　孟康曰：「扢，摩也。」師古曰：「音公忽反。謂摩拭其壇，加以椒蘭之芳。」","sentenceOrder":427},
  {"id":"s_work_han_thu_26_428","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「言禮神之璧乃玉之精英，故有光華也。」","sentenceOrder":428},
  {"id":"s_work_han_thu_26_429","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「言福慶方興起也。」","sentenceOrder":429},
  {"id":"s_work_han_thu_26_430","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「言神來降臨，故盡其肅恭。」","sentenceOrder":430},
  {"id":"s_work_han_thu_26_431","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「言遍延諸神，咸歆祭祀，畢盡觴爵也。」","sentenceOrder":431},
  {"id":"s_work_han_thu_26_432","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　師古曰：「神既畢饗，則嚴駕靈輿，引其侍從之位偃蹇高驤也。蹇音居偃反。」","sentenceOrder":432},
  {"id":"s_work_han_thu_26_433","chapterId":"ch_work_han_thu_26","textTraditional":"〔八〕　師古曰：「卉汨，疾意也。臚，陳也。析，分也。奚，何也。言速自陳列分散而歸，無所留也。汨音于筆反。」","sentenceOrder":433},
  {"id":"s_work_han_thu_26_434","chapterId":"ch_work_han_thu_26","textTraditional":"〔九〕　師古曰：「淫，久也。淥澤，澤名。言我饗神之後，久在淥澤，乃〈氵{山王}〉然而歸也。淥音綠。〈氵{山王}〉音烏黃反。」","sentenceOrder":434},
  {"id":"s_work_han_thu_26_435","chapterId":"ch_work_han_thu_26","textTraditional":"朝隴首，覽西垠，〔一〕靁電尞，獲白麟。〔二〕爰五止，顯黃德，〔三〕圖匈虐，熏鬻殛。〔四〕闢流離，抑不詳，〔五〕賓百僚，山河饗。〔六〕掩回轅，鬗長馳，〔七〕騰雨師，洒路陂〔八〕。流星隕，感惟風，籥歸雲，撫懷心。〔九〕","sentenceOrder":435},
  {"id":"s_work_han_thu_26_436","chapterId":"ch_work_han_thu_26","textTraditional":"朝隴首十七　元狩元年行幸雍獲白麟作。","sentenceOrder":436},
  {"id":"s_work_han_thu_26_437","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　臣瓚曰：「謂朝於隴首而覽西北也。」師古曰：「隴坻之首也。垠，厓也。坻音丁禮反。」","sentenceOrder":437},
  {"id":"s_work_han_thu_26_438","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　臣瓚曰：「尞祭五畤，皆有報應，聲若靁，光若電也。」師古曰：「尞，古燎字。」","sentenceOrder":438},
  {"id":"s_work_han_thu_26_439","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「爰，曰也，發語辭也。止，足也。時白麟足有五蹄。」","sentenceOrder":439},
  {"id":"s_work_han_thu_26_440","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　應劭曰：「熏鬻，匈奴本號也。」師古曰：「殛，窮也。一曰，殛，誅也，音居力反。」","sentenceOrder":440},
  {"id":"s_work_han_thu_26_441","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「流離不得其所者，為開道路，使之安集。違道不詳善者，則抑黜之，以申懲勸也。」","sentenceOrder":441},
  {"id":"s_work_han_thu_26_442","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「百僚，百神之官也。饗，合韻音鄉。」","sentenceOrder":442},
  {"id":"s_work_han_thu_26_443","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　如淳曰：「鬗音樠。鬗鬗，長貌也。」師古曰：「音武元反。」","sentenceOrder":443},
  {"id":"s_work_han_thu_26_444","chapterId":"ch_work_han_thu_26","textTraditional":"〔八〕　師古曰：「洒，灑也。路陂，路傍也。言使雨師灑道也。洒音灑，又音山豉反。」","sentenceOrder":444},
  {"id":"s_work_han_thu_26_445","chapterId":"ch_work_han_thu_26","textTraditional":"〔九〕　師古曰：「懷心，懷柔之心也。籋音躡。」","sentenceOrder":445},
  {"id":"s_work_han_thu_26_446","chapterId":"ch_work_han_thu_26","textTraditional":"象載瑜，白集西，〔一〕食甘露，飲榮泉。〔二〕赤鴈集，六紛員，〔三〕殊翁雜，五采文。〔四〕神所見，施祉福，登蓬萊，結無極。〔五〕","sentenceOrder":446},
  {"id":"s_work_han_thu_26_447","chapterId":"ch_work_han_thu_26","textTraditional":"象載瑜十八　太始三年行幸東海獲赤鴈作。","sentenceOrder":447},
  {"id":"s_work_han_thu_26_448","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　服虔曰：「象載，鳥名也。」師古曰：「此說非也。象載，象輿也。山出象輿，瑞應車也。瑜，美貌也。言此瑞車瑜然色白而出西方也。西，合韻音先。」","sentenceOrder":448},
  {"id":"s_work_han_thu_26_449","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「駕輿者之所飲食也。榮泉，言泉有光華。」","sentenceOrder":449},
  {"id":"s_work_han_thu_26_450","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「言六者，所獲赤鴈之數也。紛員，多貌也。言西獲象輿，東獲赤鴈，祥瑞多也。員音云。」","sentenceOrder":450},
  {"id":"s_work_han_thu_26_451","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　孟康曰：「翁，鴈頸也。言其文采殊異也。」","sentenceOrder":451},
  {"id":"s_work_han_thu_26_452","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「見，顯示也。蓬萊，神山也，在海中。結，成也。」","sentenceOrder":452},
  {"id":"s_work_han_thu_26_453","chapterId":"ch_work_han_thu_26","textTraditional":"赤蛟綏，黃華蓋，〔一〕露夜零，晝晻濭。〔二〕百君禮，六龍位，〔三〕勺椒漿，靈已醉。〔四〕靈既享，錫吉祥，芒芒極，降嘉觴。〔五〕靈殷殷，爛揚光，〔六〕延壽命，永未央。杳冥冥，塞六合，澤汪濊，輯萬國。〔七〕靈禗禗，象輿轙，〔八〕票然逝，旗逶蛇。〔九〕禮樂成，靈將歸，託玄德，長無衰。〔一０〕","sentenceOrder":453},
  {"id":"s_work_han_thu_26_454","chapterId":"ch_work_han_thu_26","textTraditional":"赤蛟十九","sentenceOrder":454},
  {"id":"s_work_han_thu_26_455","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「綏綏，赤蛟貌。黃華蓋，言其上有黃氣，狀若蓋也。」","sentenceOrder":455},
  {"id":"s_work_han_thu_26_456","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「晻音烏感反。濭音藹。晻濭，雲氣之貌。」","sentenceOrder":456},
  {"id":"s_work_han_thu_26_457","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「百君，亦謂百神也。」","sentenceOrder":457},
  {"id":"s_work_han_thu_26_458","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「勺讀曰酌。」","sentenceOrder":458},
  {"id":"s_work_han_thu_26_459","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「芒芒，廣大貌，音莫郎反。」","sentenceOrder":459},
  {"id":"s_work_han_thu_26_460","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「殷殷，盛也。爛，光貌。殷音隱。」","sentenceOrder":460},
  {"id":"s_work_han_thu_26_461","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　師古曰：「塞，滿也。輯，和也。天地四方謂之六合。汪濊，言饒多也。濊音於廢反，又音烏外反。輯與集同。」","sentenceOrder":461},
  {"id":"s_work_han_thu_26_462","chapterId":"ch_work_han_thu_26","textTraditional":"〔八〕　孟康曰：「禗音近枲，不安欲去也。轙，待也。」如淳曰：「轙，僕人嚴駕待發之意也。」師古曰：「禗，孟音是也。轙，如說是也。轙音儀。」","sentenceOrder":462},
  {"id":"s_work_han_thu_26_463","chapterId":"ch_work_han_thu_26","textTraditional":"〔九〕　師古曰：「票然，輕舉意也。逶蛇，旗貌也。票音匹遙反。蛇音移。」","sentenceOrder":463},
  {"id":"s_work_han_thu_26_464","chapterId":"ch_work_han_thu_26","textTraditional":"〔一０〕師古曰：「言託恃天德，冀獲長生，無衰竭也。」","sentenceOrder":464},
  {"id":"s_work_han_thu_26_465","chapterId":"ch_work_han_thu_26","textTraditional":"其餘巡狩福應之事，不序郊廟，故弗論。","sentenceOrder":465},
  {"id":"s_work_han_thu_26_466","chapterId":"ch_work_han_thu_26","textTraditional":"是時，河間獻王有雅材，亦以為治道非禮樂不成，因獻所集雅樂。天子下大樂官，常存肄之，〔一〕歲時以備數，然不常御，常御及郊廟皆非雅聲。然詩樂施於後嗣，猶得有所祖述。昔殷周之雅頌，乃上本有娀、姜原，〔二〕卨、稷始生，玄王、公劉、古公、大伯、王季、姜女、大任、太姒之德，〔三〕乃及成湯、文、武受命，武丁、成、康、宣王中興，〔四〕下及輔佐阿衡、周、召、太公、申伯、召虎、仲山甫之屬，〔五〕君臣男女有功德者，靡不褒揚。功德既信美矣，褒揚之聲盈乎天地之間，是以光名著於當世，遺譽垂於無窮也。今漢郊廟詩歌，未有祖宗之事，八音調均，又不協於鐘律，而內有掖庭材人，外有上林樂府，皆以鄭聲施於朝廷。","sentenceOrder":466},
  {"id":"s_work_han_thu_26_467","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「肄，習也。音弋二反。」","sentenceOrder":467},
  {"id":"s_work_han_thu_26_468","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　應劭曰：「簡狄，有娀之女，吞燕卵而生契。」師古曰：「姜嫄，后稷之母也。」","sentenceOrder":468},
  {"id":"s_work_han_thu_26_469","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「卨，殷之始祖。稷，周之始祖。玄王亦殷之先祖，承黑帝之後，故曰玄王。公劉，后稷之曾孫也。古公亶父，即豳公也。大伯，大王之子，王季之兄也。王季，文王之父也。姜女，亶甫之妃也。大任，文王之母也。太姒，文王之妃，武王之母也。毛、鄭說詩，以玄王即卨也。此志既言卨，又有玄王，則玄王非卨一人矣。」","sentenceOrder":469},
  {"id":"s_work_han_thu_26_470","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「武丁，殷王高宗也。周成王，武王之子也。康王，成王之子也。宣王，厲王之子。」","sentenceOrder":470},
  {"id":"s_work_han_thu_26_471","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「阿衡，伊尹職號也。周，周公旦也。召，召公奭也。太公，師尚父也。申伯、召虎、仲山甫，皆周宣王臣也。」","sentenceOrder":471},
  {"id":"s_work_han_thu_26_472","chapterId":"ch_work_han_thu_26","textTraditional":"至成帝時，謁者常山王禹世受（可）〔河〕間樂，能說其義，其弟子宋曅等上書言之，〔一〕下大夫博士平當等考試。當以為「漢承秦滅道之後，賴先帝聖德，博受兼聽，修廢官，立大學，河間獻王聘求幽隱，修興雅樂以助化。時，大儒公孫弘、董仲舒等皆以為音中正雅，立之大樂。春秋鄉射，作於學官，希闊不講。〔二〕故自公卿大夫觀聽者，但聞（鑑）〔鏗〕鎗，不曉其意，而欲以風諭眾庶，其道無由。〔三〕是以行之百有餘年，德化至今未成。今曅等守習孤學，大指歸於興助教化。衰微之學，興廢在人。宜領屬雅樂，以繼絕表微。〔四〕孔子曰：『人能弘道，非道弘人。』〔五〕河間區區，（不）〔小〕國藩臣，〔六〕以好學修古，能有所存，〔七〕民到于今稱之，況於聖主廣被之資，〔八〕修起舊文，放鄭近雅，述而不作，信而好古，於以風示海內，揚名後世，誠非小功小美也。」事下公卿，以為久遠難分明，當議復寢。","sentenceOrder":472},
  {"id":"s_work_han_thu_26_473","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「曅音于輒反。」","sentenceOrder":473},
  {"id":"s_work_han_thu_26_474","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「講謂論習也。」","sentenceOrder":474},
  {"id":"s_work_han_thu_26_475","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「風，化也。」","sentenceOrder":475},
  {"id":"s_work_han_thu_26_476","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「表，顯也。」","sentenceOrder":476},
  {"id":"s_work_han_thu_26_477","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「論語載孔子之言。」","sentenceOrder":477},
  {"id":"s_work_han_thu_26_478","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「區區，小貌也。」","sentenceOrder":478},
  {"id":"s_work_han_thu_26_479","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　師古曰：「存意於禮樂。」","sentenceOrder":479},
  {"id":"s_work_han_thu_26_480","chapterId":"ch_work_han_thu_26","textTraditional":"〔八〕　師古曰：「被猶覆也，音皮義反。」","sentenceOrder":480},
  {"id":"s_work_han_thu_26_481","chapterId":"ch_work_han_thu_26","textTraditional":"是時，鄭聲尤甚。黃門名倡丙彊、景武之屬富顯於世，貴戚五侯定陵、富平外戚之家〔一〕淫侈過度，至與人主爭女樂。哀帝自為定陶王時疾之，又性不好音，及即位，下詔曰：「惟世俗奢泰文巧，而鄭衛之聲興。夫奢泰則下不孫而國貧，〔二〕文巧則趨末背本者眾，〔三〕鄭衛之聲興則淫辟之化流，〔四〕而欲黎庶敦朴家給，猶濁其源而求其清流，〔五〕豈不難哉！孔子不云乎？『放鄭聲，鄭聲淫。』〔六〕其罷樂府官。郊祭樂及古兵法武樂，在經非鄭衛之樂者，條奏，別屬他官。」丞相孔光、大司空何武奏：「郊祭樂人員六十二人，給祠南北郊。大樂鼓員六人，嘉至鼓員十人，邯鄲鼓員二人，騎吹鼓員三人，江南鼓員二人，淮南鼓員四人，巴俞鼓員三十六人，〔七〕歌鼓員二十四人，楚嚴鼓員一人，梁皇鼓員四人，臨淮鼓員三十五人，茲邡鼓員三人，〔八〕凡鼓十二，員百二十八人，朝賀置酒陳殿下，應古兵法。外郊祭員十三人，諸族樂人兼雲招給祠南郊用六十七人，〔九〕兼給事雅樂用四人，夜誦員五人，剛、別柎員二人，〔一０〕給盛德主調篪員二人，〔一一〕聽工以律知日冬夏至一人，鐘工、磬工、簫工員各一人，僕射二人主領諸樂人，皆不可罷。竽工員三人，一人可罷。〔一二〕琴工員五人，三人可罷。柱工員二人，一人可罷。〔一三〕繩弦工員六人，四人可罷。〔一四〕鄭四會員六十二人，一人給事雅樂，六十一人可罷。張瑟員八人，七人可罷。安世樂鼓員二十人，十九人可罷。沛吹鼓員十二人，族歌鼓員二十七人，陳吹鼓員十三人，商樂鼓員十四人，東海鼓員十六人，長樂鼓員十三人，縵樂鼓員十三人，〔一五〕凡鼓八，員百二十八人，朝賀置酒，陳前殿房中，不應經法。治竽員五人，楚鼓員六人，常從倡三十人，常從象人四人，〔一六〕詔隨常從倡十六人，秦倡員二十九人，秦倡象人員三人，詔隨秦倡一人，雅大人員九人，朝賀置酒為樂。楚四會員十七人，巴四會員十二人，銚四會員十二人，〔一七〕齊四會員十九人，蔡謳員三人，齊謳員六人，竽瑟鐘磬員五人，皆鄭聲，可罷。師學百四十二人，其七十二人給大官挏馬酒，〔一八〕其七十人可罷。大凡八百二十九人，其三百八十八人不可罷，可領屬大樂，其四百四十一人不應經法，或鄭衛之聲，皆可罷。」奏可。然百姓漸漬日久，又不制雅樂有以相變，豪富吏民湛沔自若，〔一九〕陵夷壞于王莽。","sentenceOrder":481},
  {"id":"s_work_han_thu_26_482","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「五侯，王鳳以下也。定陵，淳于長也。富平，張放。」","sentenceOrder":482},
  {"id":"s_work_han_thu_26_483","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「孫讀曰遜。」","sentenceOrder":483},
  {"id":"s_work_han_thu_26_484","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「趨讀曰趣。趣，嚮也。」","sentenceOrder":484},
  {"id":"s_work_han_thu_26_485","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「辟讀曰僻也。」","sentenceOrder":485},
  {"id":"s_work_han_thu_26_486","chapterId":"ch_work_han_thu_26","textTraditional":"〔五〕　師古曰：「源，水泉之本。」","sentenceOrder":486},
  {"id":"s_work_han_thu_26_487","chapterId":"ch_work_han_thu_26","textTraditional":"〔六〕　師古曰：「論語載孔子之言。」","sentenceOrder":487},
  {"id":"s_work_han_thu_26_488","chapterId":"ch_work_han_thu_26","textTraditional":"〔七〕　師古曰：「巴，巴人也。俞，俞人也。當高祖初為漢王，得巴俞人，並趫捷善鬥，與之定三秦滅楚，因存其武樂也。巴俞之樂因此始也。巴即今之巴州，俞即今之（俞）〔渝〕州，各其本地。」","sentenceOrder":488},
  {"id":"s_work_han_thu_26_489","chapterId":"ch_work_han_thu_26","textTraditional":"〔八〕　晉灼曰：「邡音方。」","sentenceOrder":489},
  {"id":"s_work_han_thu_26_490","chapterId":"ch_work_han_thu_26","textTraditional":"〔九〕　師古曰：「招讀與翹同。」","sentenceOrder":490},
  {"id":"s_work_han_thu_26_491","chapterId":"ch_work_han_thu_26","textTraditional":"〔一０〕師古曰：「剛及別柎皆鼓名也。柎音膚。」","sentenceOrder":491},
  {"id":"s_work_han_thu_26_492","chapterId":"ch_work_han_thu_26","textTraditional":"〔一一〕師古曰：「篪以竹為之，七孔，亦笛之類也，音池。」","sentenceOrder":492},
  {"id":"s_work_han_thu_26_493","chapterId":"ch_work_han_thu_26","textTraditional":"〔一二〕師古曰：「竽，笙類也，三十六簧，音于。」","sentenceOrder":493},
  {"id":"s_work_han_thu_26_494","chapterId":"ch_work_han_thu_26","textTraditional":"〔一三〕師古曰：「柱工，主箏瑟之柱者。」","sentenceOrder":494},
  {"id":"s_work_han_thu_26_495","chapterId":"ch_work_han_thu_26","textTraditional":"〔一四〕師古曰：「弦，琴瑟之弦。繩言主糾合作之也。」","sentenceOrder":495},
  {"id":"s_work_han_thu_26_496","chapterId":"ch_work_han_thu_26","textTraditional":"〔一五〕師古曰：「縵樂，雜樂也，音漫。」","sentenceOrder":496},
  {"id":"s_work_han_thu_26_497","chapterId":"ch_work_han_thu_26","textTraditional":"〔一六〕孟康曰：「象人，若今戲蝦魚師子者也。」韋昭曰：「著假面者也。」師古曰：「孟說是。」","sentenceOrder":497},
  {"id":"s_work_han_thu_26_498","chapterId":"ch_work_han_thu_26","textTraditional":"〔一七〕李奇曰：「疑是鼗。」韋昭曰：「銚，國名，音繇。」師古曰：「韋說是也。銚音姚。」","sentenceOrder":498},
  {"id":"s_work_han_thu_26_499","chapterId":"ch_work_han_thu_26","textTraditional":"〔一八〕李奇曰：「以馬乳為酒，撞挏乃成也。」師古曰：「挏音動。馬酪味如酒，而飲之亦可醉，故呼馬酒也。」","sentenceOrder":499},
  {"id":"s_work_han_thu_26_500","chapterId":"ch_work_han_thu_26","textTraditional":"〔一九〕師古曰：「湛讀曰沈，又讀曰耽。自若，言自如故也。」","sentenceOrder":500},
  {"id":"s_work_han_thu_26_501","chapterId":"ch_work_han_thu_26","textTraditional":"今海內更始，民人歸本，戶口歲息，〔一〕平其刑辟，牧以賢良，至於家給，既庶且富，則須庠序禮樂之教化矣。〔二〕今幸有前聖遺制之威儀，誠可法象而補備之，經紀可因緣而存著也。孔子曰：「殷因於夏禮，所損益，可知也；周因於殷禮，所損益，可知也；其或繼周者，百世可知也。」〔三〕今大漢繼周，久曠大儀，未有立禮成樂，此賈（宜）〔誼〕、仲舒、王吉、劉向之徒所為發憤而增嘆也。〔四〕","sentenceOrder":501},
  {"id":"s_work_han_thu_26_502","chapterId":"ch_work_han_thu_26","textTraditional":"〔一〕　師古曰：「今謂班氏撰書時也。息，生也。」","sentenceOrder":502},
  {"id":"s_work_han_thu_26_503","chapterId":"ch_work_han_thu_26","textTraditional":"〔二〕　師古曰：「家給，解已在前。庶，眾也。論語云孔子曰：『庶矣哉！』冉有曰：『既庶矣，又何加焉？』曰：『富之。』曰：『既富矣，又何加焉？』曰：『教之。』故班氏引之也。」","sentenceOrder":503},
  {"id":"s_work_han_thu_26_504","chapterId":"ch_work_han_thu_26","textTraditional":"〔三〕　師古曰：「論語載孔子答子張之言也。」","sentenceOrder":504},
  {"id":"s_work_han_thu_26_505","chapterId":"ch_work_han_thu_26","textTraditional":"〔四〕　師古曰：「感嘆也。」","sentenceOrder":505},
  {"id":"s_work_han_thu_26_506","chapterId":"ch_work_han_thu_26","textTraditional":"校勘記","sentenceOrder":506},
  {"id":"s_work_han_thu_26_507","chapterId":"ch_work_han_thu_26","textTraditional":"一０三四頁　三行　（大不備）或莫甚焉。　王先謙說「大不備」三字誤衍。「或」古「惑」字。通鑑不重三字，「或」作「惑」，是所見本不誤。","sentenceOrder":507},
  {"id":"s_work_han_thu_26_508","chapterId":"ch_work_han_thu_26","textTraditional":"一０三六頁　四行　（母常人）〔每常大〕行禮乃置。　「母常人」，景祐本作「每常大」。殿本「常」作「當」。","sentenceOrder":508},
  {"id":"s_work_han_thu_26_509","chapterId":"ch_work_han_thu_26","textTraditional":"一０三七頁　七行　皆安其位而不相奪（也），足以感動人之善心（而）〔也〕，不使邪氣得接焉，　景祐本如此。","sentenceOrder":509},
  {"id":"s_work_han_thu_26_510","chapterId":"ch_work_han_thu_26","textTraditional":"一０三七頁一二行　麤（古）〔作〕麄字，〔非是〕。　景祐本如此。　按「麄」是「麤」之俗字，故說非是。","sentenceOrder":510},
  {"id":"s_work_han_thu_26_511","chapterId":"ch_work_han_thu_26","textTraditional":"一０四一頁一六行　而說論語者乃以為（追）魯哀公時禮壞樂崩，　景祐、殿本無「追」字。","sentenceOrder":511},
  {"id":"s_work_han_thu_26_512","chapterId":"ch_work_han_thu_26","textTraditional":"一０四四頁　七行　高（祖）廟奏武德、文始、五行之舞；　王念孫說「祖」字涉上下文而衍，景祐本作「高廟」，是也。","sentenceOrder":512},
  {"id":"s_work_han_thu_26_513","chapterId":"ch_work_han_thu_26","textTraditional":"一０四四頁一０行　以（明）示天下之安和也。　王念孫說「明」字涉下兩「明」字而衍，景祐本無。","sentenceOrder":513},
  {"id":"s_work_han_thu_26_514","chapterId":"ch_work_han_thu_26","textTraditional":"一０四五頁一０行　更重立（之）〔也〕。　景祐、殿本都作「也」。","sentenceOrder":514},
  {"id":"s_work_han_thu_26_515","chapterId":"ch_work_han_thu_26","textTraditional":"一０四七頁一六行　言各置（郊）〔部〕校，　景祐、殿、局本都作「部」。王先謙說作「部」是。","sentenceOrder":515},
  {"id":"s_work_han_thu_26_516","chapterId":"ch_work_han_thu_26","textTraditional":"一０四九頁一一行　桂華　錢大昭說，此二字是練時日、帝臨、青陽之類，所以記章數也。但存桂華、美若二章之名，其餘俱脫去耳。","sentenceOrder":516},
  {"id":"s_work_han_thu_26_517","chapterId":"ch_work_han_thu_26","textTraditional":"一０五０頁　四行　美（芳）〔若〕　劉奉世說，桂華、美芳皆二詩章名，本側注在前章之末，傳寫之誤，遂以冠後。後詞無「美芳」，亦當作「美若」矣。","sentenceOrder":517},
  {"id":"s_work_han_thu_26_518","chapterId":"ch_work_han_thu_26","textTraditional":"一０五０頁一三行　蠻夷遣（擇）〔譯〕致福貢也。　景祐、殿本都作「譯」。王先謙說作「譯」是。","sentenceOrder":518},
  {"id":"s_work_han_thu_26_519","chapterId":"ch_work_han_thu_26","textTraditional":"一０五七頁　四行　（列）〔烈〕騰八荒。　景祐、殿本都作「烈」。王先謙說作「烈」是。","sentenceOrder":519},
  {"id":"s_work_han_thu_26_520","chapterId":"ch_work_han_thu_26","textTraditional":"一０五七頁一二行　享字合韻宜（因）〔音〕鄉。　景祐、殿本都作「音」。王先謙說作「音」是。","sentenceOrder":520},
  {"id":"s_work_han_thu_26_521","chapterId":"ch_work_han_thu_26","textTraditional":"一０六一頁　五行　馬毛色如虎脊〔者〕有兩也。　「者」字據景祐、殿本補。","sentenceOrder":521},
  {"id":"s_work_han_thu_26_522","chapterId":"ch_work_han_thu_26","textTraditional":"一０六一頁　六行　（幾）〔凡〕千里而至東道。　景祐、殿本都作「凡」。王先謙說作「凡」是。","sentenceOrder":522},
  {"id":"s_work_han_thu_26_523","chapterId":"ch_work_han_thu_26","textTraditional":"一０六一頁一四行　靈〈寖，中“彐改帚”〉（平而）鴻，長生豫。　王先謙說，八字不成句義，「平而」二字當衍。顏注亦未為「平」字釋義，衍文明矣。","sentenceOrder":523},
  {"id":"s_work_han_thu_26_524","chapterId":"ch_work_han_thu_26","textTraditional":"一０六七頁一三行　析奚（道）〔遺〕？　景祐、殿、局本都作「遺」。王先謙說作「遺」是。","sentenceOrder":524},
  {"id":"s_work_han_thu_26_525","chapterId":"ch_work_han_thu_26","textTraditional":"一０七一頁一四行　世受（可）〔河〕間樂，　錢大昭說「可」當作「河」。按景祐、殿、局本都作「河」。","sentenceOrder":525},
  {"id":"s_work_han_thu_26_526","chapterId":"ch_work_han_thu_26","textTraditional":"一０七二頁　一行　但聞（鑑）〔鏗〕鎗，　景祐、殿、局本都作「鏗」。王先謙說作「鏗」是。","sentenceOrder":526},
  {"id":"s_work_han_thu_26_527","chapterId":"ch_work_han_thu_26","textTraditional":"一０七二頁　四行　（不）〔小〕國藩臣，　錢大昭說「不」疑「小」字之訛。按景祐、殿本都作「小」。","sentenceOrder":527},
  {"id":"s_work_han_thu_26_528","chapterId":"ch_work_han_thu_26","textTraditional":"一０七三頁　八行　剛、別柎員二人，〔一０〕給盛德主調篪員二人，　注〔一０〕原在「盛德」下。王先謙說「給盛德」三字當下屬。","sentenceOrder":528},
  {"id":"s_work_han_thu_26_529","chapterId":"ch_work_han_thu_26","textTraditional":"一０七四頁一四行　俞即今之（俞）〔渝〕州。　景祐、殿本都作「渝」。王先謙說作「渝」是。","sentenceOrder":529},
  {"id":"s_work_han_thu_26_530","chapterId":"ch_work_han_thu_26","textTraditional":"一０七五頁一四行　賈（宜）〔誼〕　景祐、殿本都作「誼」。王先謙說作「誼」是。","sentenceOrder":530},
  {"id":"s_work_han_thu_27_1","chapterId":"ch_work_han_thu_27","textTraditional":"夫人宵天地之〈豿，中“句改頁”〉，〔一〕懷五常之性，〔二〕聰明精粹，〔三〕有生之最靈者也。爪牙不足以供耆欲，趨走不足以避利害，〔四〕無毛羽以禦寒暑，必將役物以為養，任智而不恃力，此其所以為貴也。故不仁愛則不能群，不能群則不勝物，不勝物則養不足。群而不足，爭心將作，上聖卓然先行敬讓博愛之德者，眾心說而從之。〔五〕從之成群，是為君矣；歸而往之，是為王矣。〔六〕洪範曰：「天子作民父母，為天下王。」〔七〕聖人取類以正名，而謂君為父母，明仁愛德讓，王道之本也。愛待敬而不敗，德須威而久立，故制禮以崇敬，作刑以明威也。聖人既躬明悊之性，〔八〕必通天地之心，制禮作教，立法設刑，動緣民情，而則天象地。〔九〕故曰先王立禮，「則天之明，因地之性」也。〔一０〕刑罰威獄，以類天之震曜殺戮也；〔一一〕溫慈惠和，以效天之生殖長育也。書云「天秩有禮」，「天討有罪」。〔一二〕故聖人因天秩而制五禮，〔一三〕因天討而作五刑。〔一四〕大刑用甲兵，〔一五〕其次用斧鉞；〔一六〕中刑用刀鋸，〔一七〕其次用鑽鑿；〔一八〕薄刑用鞭扑。〔一九〕大者陳諸原野，〔二０〕小者致之市朝，〔二一〕其所繇來者上矣。〔二二〕","sentenceOrder":1},
  {"id":"s_work_han_thu_27_2","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　應劭曰：「宵，類也。頭圜象天，足方象地。」孟康曰：「宵，化也，言稟天地氣化而生也。」師古曰：「宵義與肖同，應說是也。故庸妄之人謂之不肖，言其狀〈豿，中“句改頁”〉無所象似也。〈豿，中“句改頁”〉，古貌字。」","sentenceOrder":2},
  {"id":"s_work_han_thu_27_3","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「五常，仁、義、禮、智、信。」","sentenceOrder":3},
  {"id":"s_work_han_thu_27_4","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「精，細也，言其識性細密也。粹，淳也，音先遂反。」","sentenceOrder":4},
  {"id":"s_work_han_thu_27_5","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　師古曰：「耆讀曰嗜。」","sentenceOrder":5},
  {"id":"s_work_han_thu_27_6","chapterId":"ch_work_han_thu_27","textTraditional":"〔五〕　師古曰：「說讀曰悅。」","sentenceOrder":6},
  {"id":"s_work_han_thu_27_7","chapterId":"ch_work_han_thu_27","textTraditional":"〔六〕　師古曰：「言爭往而歸之也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_27_8","chapterId":"ch_work_han_thu_27","textTraditional":"〔七〕　師古曰：「洪範，周書也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_27_9","chapterId":"ch_work_han_thu_27","textTraditional":"〔八〕　師古曰：「躬謂身親有之。」","sentenceOrder":9},
  {"id":"s_work_han_thu_27_10","chapterId":"ch_work_han_thu_27","textTraditional":"〔九〕　師古曰：「則，法也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_27_11","chapterId":"ch_work_han_thu_27","textTraditional":"〔一０〕師古曰：「春秋左氏傳載鄭大夫子太叔之辭也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_27_12","chapterId":"ch_work_han_thu_27","textTraditional":"〔一一〕師古曰：「震謂雷電也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_27_13","chapterId":"ch_work_han_thu_27","textTraditional":"〔一二〕師古曰：「此虞書咎繇謨之辭也。秩，敘也。言有禮者天則進敘之，有罪者天則討治之。」","sentenceOrder":13},
  {"id":"s_work_han_thu_27_14","chapterId":"ch_work_han_thu_27","textTraditional":"〔一三〕師古曰：「五禮，吉、凶、賓、軍、嘉。」","sentenceOrder":14},
  {"id":"s_work_han_thu_27_15","chapterId":"ch_work_han_thu_27","textTraditional":"〔一四〕師古曰：「其說在下也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_27_16","chapterId":"ch_work_han_thu_27","textTraditional":"〔一五〕張晏曰：「以六師誅暴亂。」","sentenceOrder":16},
  {"id":"s_work_han_thu_27_17","chapterId":"ch_work_han_thu_27","textTraditional":"〔一六〕韋昭曰：「斬刑也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_27_18","chapterId":"ch_work_han_thu_27","textTraditional":"〔一七〕韋昭曰：「刀，割刑。鋸，刖刑也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_27_19","chapterId":"ch_work_han_thu_27","textTraditional":"〔一八〕韋昭曰：「鑽，髕刑也。鑿，黥刑也。」師古曰：「鑽，鑽去其髕骨也。鑽音子端反。髕音頻忍反。」","sentenceOrder":19},
  {"id":"s_work_han_thu_27_20","chapterId":"ch_work_han_thu_27","textTraditional":"〔一九〕師古曰：「扑，杖也，音普木反。」","sentenceOrder":20},
  {"id":"s_work_han_thu_27_21","chapterId":"ch_work_han_thu_27","textTraditional":"〔二０〕師古曰：「謂征討所殺也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_27_22","chapterId":"ch_work_han_thu_27","textTraditional":"〔二一〕應劭曰：「大夫以上尸諸朝，士以下尸諸市。」","sentenceOrder":22},
  {"id":"s_work_han_thu_27_23","chapterId":"ch_work_han_thu_27","textTraditional":"〔二二〕師古曰：「繇讀與由同。」","sentenceOrder":23},
  {"id":"s_work_han_thu_27_24","chapterId":"ch_work_han_thu_27","textTraditional":"自黃帝有涿鹿之戰以定火災，〔一〕顓頊有共工之陳以定水害。〔二〕唐虞之際，至治之極，猶流共工，放讙兜，竄三苗，殛鯀，然後天下服。〔三〕夏有甘扈之誓，〔四〕殷、周以兵定天下矣。〔五〕天下既定，戢臧干戈，教以文德，〔六〕而猶立司馬之官，設六軍之眾，〔七〕因井田而制軍賦。地方一里為井，井十為通，通十為成，成方十里；成十為終，終十為同，同方百里；同十為封，封十為畿，畿方千里。有稅有（租）〔賦〕。〔八〕稅以足食，賦以足兵。故四井為邑，四邑為丘。丘，十六井也，有戎馬一匹，牛三頭。四丘為甸。甸，六十四井也，有戎馬四匹，兵車一乘，牛十二頭，甲士三人，卒七十二人，干戈備具，是謂乘馬之法。〔九〕一同百里，提封萬井，〔一０〕除山川沈斥，城池邑居，園囿術路，三千六百井，〔一一〕定出賦六千四百井，戎馬四百匹，兵車百乘，此卿大夫采地之大者也，〔一二〕是謂百乘之家。一封三百一十六里，提封十萬井，定出賦六萬四千井，戎馬四千匹，兵車千乘，此諸侯之大者也，是謂千乘之國。天子畿方千里，提封百萬井，定出賦六十四萬井，戎馬四萬匹，兵車萬乘，故稱萬乘之主。戎馬車徒干戈素具，春振旅以搜，夏拔舍以苗，秋治兵以獮，冬大閱以狩，〔一三〕皆於農隙以講事焉。〔一四〕五國為屬，屬有長；十國為連，連有帥；〔一五〕三十國為卒，卒有正；二百一十國為州，州有牧。連帥比年簡車，〔一六〕卒正三年簡徒，〔一七〕群牧五載大簡車徒，此先王為國立武足兵之大略也。","sentenceOrder":24},
  {"id":"s_work_han_thu_27_25","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　鄭氏曰：「涿鹿在彭城南。與炎帝戰，炎帝火行，故云火（炎）〔災〕。」李奇曰：「黃帝與炎帝戰於阪泉，今言涿鹿，地有二名也。」文穎曰：「國語云，黃帝，炎帝弟也。炎帝號神農，火行也，後子孫暴虐，黃帝伐之，故言以定火災。律曆志云『與炎帝後戰於阪泉』。涿鹿在上谷，今見有阪泉地黃帝祠。」師古曰：「文說是也。彭城者，上谷北別有彭城，非宋之彭城也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_27_26","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　文穎曰：「共工，主水官也，少昊氏衰，秉政作害，顓頊伐之。本主水官，因為水行也。」師古曰：「共讀曰龔。次下亦同。」","sentenceOrder":26},
  {"id":"s_work_han_thu_27_27","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「舜受堯禪而流共工于幽州，放讙兜于崇山，竄三苗于三危，殛鯀于羽山也。殛，誅也，音居力反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_27_28","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　師古曰：「謂啟與有扈戰于甘之野，作甘誓，事見夏書。扈國，今鄠縣是也。甘即甘水之上。」","sentenceOrder":28},
  {"id":"s_work_han_thu_27_29","chapterId":"ch_work_han_thu_27","textTraditional":"〔五〕　師古曰：「謂湯及武王。」","sentenceOrder":29},
  {"id":"s_work_han_thu_27_30","chapterId":"ch_work_han_thu_27","textTraditional":"〔六〕　師古曰：「戢，斂也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_27_31","chapterId":"ch_work_han_thu_27","textTraditional":"〔七〕　師古曰：「司馬，夏官卿，掌邦政，軍旅屬焉。萬二千五百人為軍，王則六軍也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_27_32","chapterId":"ch_work_han_thu_27","textTraditional":"〔八〕　師古曰：「稅者，田租也。賦謂發斂財也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_27_33","chapterId":"ch_work_han_thu_27","textTraditional":"〔九〕　鄭氏曰：「甲士在車上也。」師古曰：「乘音食證反。其下並同。」","sentenceOrder":33},
  {"id":"s_work_han_thu_27_34","chapterId":"ch_work_han_thu_27","textTraditional":"〔一０〕蘇林曰：「提音秪，陳留人謂舉田為秪。」李奇曰：「提，舉也，舉四封之內也。」師古曰：「李說是也。提讀如本字，蘇音非也。說者或以為積土而封謂之隄封，既改文字，又失義也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_27_35","chapterId":"ch_work_han_thu_27","textTraditional":"〔一一〕臣瓚曰：「沈斥，水田舄鹵也。」如淳曰：「術，大道也。」師古曰「川謂水之通流者也。沈謂居深水之下也。斥，鹹鹵之地。」","sentenceOrder":35},
  {"id":"s_work_han_thu_27_36","chapterId":"ch_work_han_thu_27","textTraditional":"〔一二〕師古曰：「采，官也。因官食地，故曰采地。爾雅曰『采、寮，官也』。說者不曉采地之義，因謂菜地，云以種菜，非也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_27_37","chapterId":"ch_work_han_thu_27","textTraditional":"〔一三〕師古曰：「振旅，整眾也。搜，搜擇不任孕者。拔舍，草止，不妨農也。苗，為苗除害也。治兵，觀威武也。獮，應殺氣也。大閱，簡車馬也。狩，火田。一曰，狩，守也，圍守而取之。拔音步末反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_27_38","chapterId":"ch_work_han_thu_27","textTraditional":"〔一四〕師古曰：「隙，空閑也。講，和習之也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_27_39","chapterId":"ch_work_han_thu_27","textTraditional":"〔一五〕師古曰：「長音竹兩反。帥音所類反。」","sentenceOrder":39},
  {"id":"s_work_han_thu_27_40","chapterId":"ch_work_han_thu_27","textTraditional":"〔一六〕師古曰：「比年，頻年也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_27_41","chapterId":"ch_work_han_thu_27","textTraditional":"〔一七〕師古曰：「徒，人眾。」","sentenceOrder":41},
  {"id":"s_work_han_thu_27_42","chapterId":"ch_work_han_thu_27","textTraditional":"周道衰，法度〈土隋〉，〔一〕至齊桓公任用管仲，而國富民安。公問行伯用師之道，〔二〕管仲曰：「公欲定卒伍，修甲兵，大國亦將修之，而小國設備，則難以速得志矣。」於是乃作內政而寓軍令焉〔三〕，故卒伍定虖里，而軍政成虖郊。連其什伍，〔四〕居處同樂，死生同憂，禍福共之，故夜戰則其聲相聞，晝戰則其目相見，緩急足以相死。其教已成，外攘夷狄，內尊天子，以安諸夏。〔五〕齊（威）〔桓〕既沒，晉文接之，亦先定其民，作被廬之法，〔六〕總帥諸侯，迭為盟主。〔七〕然其禮已頗僭差，又隨時苟合以求欲速之功，故不能充王制。二伯之後，寖以陵夷，〔八〕至魯成公作丘甲，〔九〕哀公用田賦，〔一０〕搜狩治兵大閱之事皆失其正。春秋書而譏之，以存王道。於是師旅亟動，百姓罷敝，〔一一〕無伏節死難之誼。孔子傷焉，曰：「以不教民戰，是謂棄之。」〔一二〕故稱子路曰：「由也，千乘之國，可使治其賦也。」而子路亦曰：「千乘之國，攝虖大國之間，加之以師旅，因之以饑饉，由也為之，比及三年，可使有勇，且知方也。」〔一三〕治其賦兵教以禮誼之謂也。","sentenceOrder":42},
  {"id":"s_work_han_thu_27_43","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「〈土隋〉即墮字。墮，毀也，音火規反。」","sentenceOrder":43},
  {"id":"s_work_han_thu_27_44","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「伯讀曰霸。」","sentenceOrder":44},
  {"id":"s_work_han_thu_27_45","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「寓，寄也，寄於內政而修軍令也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_27_46","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　師古曰：「五人為伍，二伍為什。」","sentenceOrder":46},
  {"id":"s_work_han_thu_27_47","chapterId":"ch_work_han_thu_27","textTraditional":"〔五〕　師古曰：「攘，卻也。諸夏，中國之諸侯也。夏，大也，言大於四夷也。攘音人羊反。」","sentenceOrder":47},
  {"id":"s_work_han_thu_27_48","chapterId":"ch_work_han_thu_27","textTraditional":"〔六〕　應劭曰：「搜於被廬之地，作執秩以為六官之法，因以名之也。」師古曰：「被廬，晉地也。被音皮義反。」","sentenceOrder":48},
  {"id":"s_work_han_thu_27_49","chapterId":"ch_work_han_thu_27","textTraditional":"〔七〕　師古曰：「迭，互也，音大結反。」","sentenceOrder":49},
  {"id":"s_work_han_thu_27_50","chapterId":"ch_work_han_thu_27","textTraditional":"〔八〕　師古曰：「寖，漸也。陵夷，頹替也。二伯，齊桓公、晉文公也。伯讀曰霸。」","sentenceOrder":50},
  {"id":"s_work_han_thu_27_51","chapterId":"ch_work_han_thu_27","textTraditional":"〔九〕　師古曰：「丘，十六井也，止出戎馬一匹，牛三頭。四丘為甸。甸，六十四井也，乃出戎馬四匹，兵車一乘，牛十二頭，甲士三人，卒七十二人耳。今乃使丘出甸賦，違常制也。一說，別令人為丘作甲也。士農工商四類異業，甲者非凡人所能為，而令作之，譏不正也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_27_52","chapterId":"ch_work_han_thu_27","textTraditional":"〔一０〕師古曰：「田賦者，別計田畝及家財各為一賦。言不依古制，役煩斂重也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_27_53","chapterId":"ch_work_han_thu_27","textTraditional":"〔一一〕師古曰：「亟，屢也，音丘吏反。罷讀曰疲。」","sentenceOrder":53},
  {"id":"s_work_han_thu_27_54","chapterId":"ch_work_han_thu_27","textTraditional":"〔一二〕師古曰：「論語載孔子之言也，非其不素習。」","sentenceOrder":54},
  {"id":"s_work_han_thu_27_55","chapterId":"ch_work_han_thu_27","textTraditional":"〔一三〕師古曰：「皆論語所載也。方，道也。比音必寐反。」","sentenceOrder":55},
  {"id":"s_work_han_thu_27_56","chapterId":"ch_work_han_thu_27","textTraditional":"春秋之後，滅弱吞小，並為戰國，稍增講武之禮，以為戲樂，用相夸視。〔一〕而秦更名角抵，〔二〕先王之禮沒於淫樂中矣。雄桀之士因勢輔時，作為權詐以相傾覆，吳有孫武，齊有孫臏，〔三〕魏有吳起，秦有商鞅，皆禽敵立勝，垂著篇籍。當此之時，合從連衡，〔四〕轉相攻伐，代為雌雄。〔五〕齊愍以技擊彊，〔六〕魏惠以武卒奮，〔七〕秦昭以銳士勝。〔八〕世方爭於功利，而馳說者以孫、吳為宗。時唯孫卿明於王道，〔九〕而非之曰：「彼孫、吳者，上勢利而貴變詐；施於暴亂昏嫚之國，君臣有間，〔一０〕上下離心，政謀不良，故可變而詐也。夫仁人在上，為下所卬，〔一一〕猶子弟之衛父兄，若手足之扞頭目，何可當也？〔一二〕鄰國望我，歡若親戚，芬若椒蘭，顧視其上，猶焚灼仇讎。人情豈肯為其所惡而攻其所好哉？故以桀攻桀，猶有巧拙；以桀詐堯，若卵投石，夫何幸之有〔一三〕！詩曰：『武王載旆，有虔秉鉞，如火烈烈，則莫我敢遏。〔一四〕』言以仁誼綏民者，無敵於天下也。若齊之技擊，得一首則受賜金。事小敵脃，則媮可用也；〔一五〕事鉅敵堅，則渙然離矣。〔一六〕是亡國之兵也。魏氏武卒，衣三屬之甲，〔一七〕操十二石之弩，負矢五十个，置戈其上，冠冑帶劍，贏三日之糧，〔一八〕日中而趨百里，〔一九〕中試則復其戶，利其田宅。〔二０〕如此，則其地雖廣，其稅必寡，其氣力數年而衰。是危國之兵也。秦人，其生民也陿阨，其使民也酷烈。〔二一〕劫之以勢，隱之以阨，〔二二〕狃之以賞慶，道之以刑罰，〔二三〕使其民所以要利於上者，非戰無由也。功賞相長，五甲首而隸五家，〔二四〕是最為有數，故能四世有勝於天下。然皆干賞蹈利之兵，庸徒鬻賣之道耳，〔二五〕未有安制矜節之理也。〔二六〕故雖地廣兵彊，鰓鰓常恐天下之一合而共軋己也。〔二七〕至乎齊桓、晉文之兵，可謂入其域而有節制矣，〔二八〕然猶未本仁義之統也。故齊之技擊不可以遇魏之武卒，魏之武卒不可以直秦之銳士，〔二九〕秦之銳士不可以當桓、文之節制，桓、文之節制不可以敵湯、武之仁義。」","sentenceOrder":56},
  {"id":"s_work_han_thu_27_57","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「視讀曰示。」","sentenceOrder":57},
  {"id":"s_work_han_thu_27_58","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「抵音丁禮反，解在武紀。」","sentenceOrder":58},
  {"id":"s_work_han_thu_27_59","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「臏音頻忍反。」","sentenceOrder":59},
  {"id":"s_work_han_thu_27_60","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　師古曰：「衡，橫也。戰國時，齊、楚、韓、魏、燕、趙為從，秦國為衡。從音子容反。謂其地形南北從長也。秦地形東西橫長，故為衡也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_27_61","chapterId":"ch_work_han_thu_27","textTraditional":"〔五〕　師古曰：「代亦迭也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_27_62","chapterId":"ch_work_han_thu_27","textTraditional":"〔六〕　孟康曰：「兵家之技巧。技巧者，習手足，便器械，積機關，以立攻守之勝。」","sentenceOrder":62},
  {"id":"s_work_han_thu_27_63","chapterId":"ch_work_han_thu_27","textTraditional":"〔七〕　師古曰：「奮，盛起。」","sentenceOrder":63},
  {"id":"s_work_han_thu_27_64","chapterId":"ch_work_han_thu_27","textTraditional":"〔八〕　師古曰：「銳，勇利。」","sentenceOrder":64},
  {"id":"s_work_han_thu_27_65","chapterId":"ch_work_han_thu_27","textTraditional":"〔九〕　師古曰：「孫卿，楚人也，姓荀字況，避漢宣帝之諱，故改曰孫卿。」","sentenceOrder":65},
  {"id":"s_work_han_thu_27_66","chapterId":"ch_work_han_thu_27","textTraditional":"〔一０〕師古曰：「言有間隙不諧和。」","sentenceOrder":66},
  {"id":"s_work_han_thu_27_67","chapterId":"ch_work_han_thu_27","textTraditional":"〔一一〕師古曰：「卬讀曰仰。」","sentenceOrder":67},
  {"id":"s_work_han_thu_27_68","chapterId":"ch_work_han_thu_27","textTraditional":"〔一二〕師古曰：「扞，禦難也，音下旦反。」","sentenceOrder":68},
  {"id":"s_work_han_thu_27_69","chapterId":"ch_work_han_thu_27","textTraditional":"〔一三〕師古曰：「言往必破碎。」","sentenceOrder":69},
  {"id":"s_work_han_thu_27_70","chapterId":"ch_work_han_thu_27","textTraditional":"〔一四〕師古曰：「殷頌長發之詩也。武王謂湯也。虔，敬也。遏，止也。言湯建號興師，本猶仁義，雖執戚鉞，以敬為先，故得如火之盛，無能止也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_27_71","chapterId":"ch_work_han_thu_27","textTraditional":"〔一五〕師古曰：「媮與偷同，謂苟且。」","sentenceOrder":71},
  {"id":"s_work_han_thu_27_72","chapterId":"ch_work_han_thu_27","textTraditional":"〔一六〕師古曰「鉅，大也。渙然，散貌。」","sentenceOrder":72},
  {"id":"s_work_han_thu_27_73","chapterId":"ch_work_han_thu_27","textTraditional":"〔一七〕服虔曰：「作大甲三屬，竟人身也。」蘇林曰：「兜鍪也，盆領也，髀褌也。」如淳曰：「上身一，髀褌一，陁繳一，凡三屬也。」師古曰：「如說是也。屬，聯也，音之欲反。髀音陛。陁即脛字。」","sentenceOrder":73},
  {"id":"s_work_han_thu_27_74","chapterId":"ch_work_han_thu_27","textTraditional":"〔一八〕師古曰：「个讀曰箇。箇，枚也。冑，兜鍪也。冠冑帶劍者，著兜鍪而又帶劍也。贏謂擔負也，音盈。」","sentenceOrder":74},
  {"id":"s_work_han_thu_27_75","chapterId":"ch_work_han_thu_27","textTraditional":"〔一九〕師古曰：「中，一日之中。」","sentenceOrder":75},
  {"id":"s_work_han_thu_27_76","chapterId":"ch_work_han_thu_27","textTraditional":"〔二０〕師古曰：「中試，試之而中科條也。復謂免其賦稅也。利田宅者，給其便利之處也。中音竹仲反。復音方目反。」","sentenceOrder":76},
  {"id":"s_work_han_thu_27_77","chapterId":"ch_work_han_thu_27","textTraditional":"〔二一〕師古曰：「陿，地小也。隘，險固也。酷，重厚也。烈，猛威也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_27_78","chapterId":"ch_work_han_thu_27","textTraditional":"〔二二〕鄭氏曰：「秦地多隘，臧隱其民於隘中也。」臣瓚曰：「秦政急峻，隱括其民於隘狹之法。」師古曰：「鄭說是也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_27_79","chapterId":"ch_work_han_thu_27","textTraditional":"〔二三〕師古曰：「狃，串習也，音女九反。道讀曰導。」","sentenceOrder":79},
  {"id":"s_work_han_thu_27_80","chapterId":"ch_work_han_thu_27","textTraditional":"〔二四〕服虔曰：「能得著甲者五人首，使得隸役五家也。」如淳曰：「役隸五家，是為相君長。」","sentenceOrder":80},
  {"id":"s_work_han_thu_27_81","chapterId":"ch_work_han_thu_27","textTraditional":"〔二五〕師古曰：「鬻音育。」","sentenceOrder":81},
  {"id":"s_work_han_thu_27_82","chapterId":"ch_work_han_thu_27","textTraditional":"〔二六〕師古曰：「矜，（特）〔持〕也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_27_83","chapterId":"ch_work_han_thu_27","textTraditional":"〔二七〕蘇林曰：「鰓音慎而無禮則葸之葸。鰓，懼貌也。」張晏曰：「軋，踐轢也。」師古曰：「鰓音先祀反。軋音於黠反。」","sentenceOrder":83},
  {"id":"s_work_han_thu_27_84","chapterId":"ch_work_han_thu_27","textTraditional":"〔二八〕孟康曰：「入王兵之域，而未盡善也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_27_85","chapterId":"ch_work_han_thu_27","textTraditional":"〔二九〕師古曰：「直亦當也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_27_86","chapterId":"ch_work_han_thu_27","textTraditional":"故曰：「善師者不陳，〔一〕善陳者不戰，善戰者不敗，善敗者不亡。」若夫舜修百僚，咎繇作士，〔二〕命以「蠻夷猾夏，寇賊姦軌」，〔三〕而刑無所用，所謂善師不陳者也。湯、武征伐，陳師誓眾，而放禽桀、紂，〔四〕所謂善陳不戰者也。齊桓南服彊楚，使貢周室，〔五〕北伐山戎，為燕開路，〔六〕存亡繼絕，功為伯首〔七〕，所謂善戰不敗者也。楚昭王遭闔廬之禍，國滅出亡，〔八〕父老送之。王曰：「父老反矣！何患無君？」父老曰：「有君如是其賢也！」〔九〕相與從之。或奔走赴秦，號哭請救，〔一０〕秦人（憐之謂）〔為〕之出兵。〔一一〕二國并力，遂走吳師，〔一二〕昭王返國，〔一三〕所謂善敗不亡者也。若秦因四世之勝，據河山之阻，任用白起、王翦豺狼之徒，奮其爪牙，禽獵六國，以并天下。〔一四〕窮武極詐，士民不附，卒隸之徒，還為敵讎，〔一五〕猋起雲合，果共軋之。〔一六〕斯為下矣。凡兵，所以存亡繼絕，救亂除害也。故伊、呂之將，子孫有國，與商周並。〔一七〕至於末世，苟任詐力，以快貪殘，爭城殺人盈城，爭地殺人滿野。孫、吳、商、白之徒，皆身誅戮於前，而（功）〔國〕滅亡於後。〔一八〕報應之勢，各以類至，其道然矣。","sentenceOrder":86},
  {"id":"s_work_han_thu_27_87","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「戰陳之義本因陳列為名，而音變耳，字則作陳，更無別體。而末代學者輒改其字旁從車，非經史之本文也。今宜依古，不從流俗也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_27_88","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「士師，理官，謂司寇之職也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_27_89","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「虞書舜典舜命咎繇之文也。猾，亂也。夏，諸夏也。寇謂攻剽，賊謂殺人。在外為姦，在內為軌。」","sentenceOrder":89},
  {"id":"s_work_han_thu_27_90","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　師古曰：「謂湯誓、泰誓、牧誓是也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_27_91","chapterId":"ch_work_han_thu_27","textTraditional":"〔五〕　師古曰：「謂僖四年伐楚，次于陘，責包茅不入，王祭不供也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_27_92","chapterId":"ch_work_han_thu_27","textTraditional":"〔六〕　師古曰：「謂莊三十年伐山戎，以其病燕故也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_27_93","chapterId":"ch_work_han_thu_27","textTraditional":"〔七〕　師古曰：「謂存三亡國，衛、邢、魯也。伯讀曰霸。」","sentenceOrder":93},
  {"id":"s_work_han_thu_27_94","chapterId":"ch_work_han_thu_27","textTraditional":"〔八〕　師古曰：「謂定四年吳入郢，楚子出，涉睢濟江，入于雲中也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_27_95","chapterId":"ch_work_han_thu_27","textTraditional":"〔九〕　師古曰：「言無有如此君者。」","sentenceOrder":95},
  {"id":"s_work_han_thu_27_96","chapterId":"ch_work_han_thu_27","textTraditional":"〔一０〕師古曰：「謂申包胥如秦乞師也。犇，古奔字。」","sentenceOrder":96},
  {"id":"s_work_han_thu_27_97","chapterId":"ch_work_han_thu_27","textTraditional":"〔一一〕師古曰：「謂秦子蒲、子武帥車五百乘以救楚也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_27_98","chapterId":"ch_work_han_thu_27","textTraditional":"〔一二〕師古曰：「謂子蒲大敗夫概王于沂，（遂）〔薳〕射之子從子西敗吳師於軍祥。」","sentenceOrder":98},
  {"id":"s_work_han_thu_27_99","chapterId":"ch_work_han_thu_27","textTraditional":"〔一三〕師古曰：「吳師已歸，楚子入郢。」","sentenceOrder":99},
  {"id":"s_work_han_thu_27_100","chapterId":"ch_work_han_thu_27","textTraditional":"〔一四〕師古曰：「言如獵之取獸。」","sentenceOrder":100},
  {"id":"s_work_han_thu_27_101","chapterId":"ch_work_han_thu_27","textTraditional":"〔一五〕師古曰：「謂陳勝、吳廣、英布之徒也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_27_102","chapterId":"ch_work_han_thu_27","textTraditional":"〔一六〕師古曰：「猋，疾風也。如猋之起，言其速也。如雲之合，言其盛也。猋音必遙反。」","sentenceOrder":102},
  {"id":"s_work_han_thu_27_103","chapterId":"ch_work_han_thu_27","textTraditional":"〔一七〕師古曰：「言其同盛衰也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_27_104","chapterId":"ch_work_han_thu_27","textTraditional":"〔一八〕師古曰：「孫武、孫臏、吳起、商鞅、白起也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_27_105","chapterId":"ch_work_han_thu_27","textTraditional":"漢興，高祖躬神武之材，行寬仁之厚，總攬英雄，以誅秦、項。任蕭、曹之文，用良、平之謀，騁陸、酈之辯，明叔孫通之儀，文武相配，大略舉焉。天下既定，踵秦而置材官於郡國，〔一〕京師有南北軍之屯。至武帝平百粵，內增七校，〔二〕外有樓船，皆歲時講肄，修武備云。〔三〕至元帝時，以貢禹議，始罷角抵，而未正治兵振旅之事也。","sentenceOrder":105},
  {"id":"s_work_han_thu_27_106","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「踵，因也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_27_107","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　晉灼曰：「百官表中壘、屯騎、步兵、越騎、長水、胡騎、射聲、虎賁，凡八校尉，胡騎不常置，故此言七也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_27_108","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「肄，習也，音弋二反。」","sentenceOrder":108},
  {"id":"s_work_han_thu_27_109","chapterId":"ch_work_han_thu_27","textTraditional":"古人有言：「天生五材，民並用之，〔一〕廢一不可，誰能去兵？」鞭扑不可弛於家，〔二〕刑罰不可廢於國，征伐不可偃於天下；用之有本末，行之有逆順耳。孔子曰：「工欲善其事，必先利其器。」〔三〕文德者，帝王之利器；威武者，文德之輔助也。夫文之所加者深，則武之所服者大；德之所施者博，則威之所制者廣。三代之盛，至於刑錯兵寢者，其本末有序，帝王之極功也。〔四〕","sentenceOrder":109},
  {"id":"s_work_han_thu_27_110","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「五材，金、木、水、火、土也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_27_111","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「弛，放也，音式爾反。」","sentenceOrder":111},
  {"id":"s_work_han_thu_27_112","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「論語載孔子之言。」","sentenceOrder":112},
  {"id":"s_work_han_thu_27_113","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　師古曰：「刑錯兵寢，皆謂置而弗用也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_27_114","chapterId":"ch_work_han_thu_27","textTraditional":"昔周之法，建三典以刑邦國，詰四方：〔一〕一曰，刑新邦用輕典；〔二〕二曰，刑平邦用中典；〔三〕三曰，刑亂邦用重典。〔四〕五刑，墨罪五百，劓罪五百，宮罪五百，刖罪五百，殺罪五百，所謂刑平邦用中典者也。〔五〕凡殺人者踣諸市，〔六〕墨者使守門，〔七〕劓者使守關，〔八〕宮者使守內，〔九〕刖者使守囿，〔一０〕完者使守積。〔一一〕其奴，男子入于罪隸，〔一二〕女子入舂槁。〔一三〕凡有爵者，與七十者，與未齔者，皆不為奴。〔一四〕","sentenceOrder":114},
  {"id":"s_work_han_thu_27_115","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「詰，責也，音口一反。字或作誥，音工到反。誥，謹也，以刑治之令謹敕也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_27_116","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「新闢地立君之國，其人未習於教，故用輕法。」","sentenceOrder":116},
  {"id":"s_work_han_thu_27_117","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「承平守成之國，則用中典常行之法也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_27_118","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　師古曰：「篡殺畔逆之國，化惡難移，則用重法誅殺之也。自此以上，（皆）〔大〕司寇所職也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_27_119","chapterId":"ch_work_han_thu_27","textTraditional":"〔五〕　師古曰：「墨，黥也，鑿其面以墨涅之。劓，截鼻也。宮，淫刑也，男子割腐，婦人幽閉。刖，斷足也。殺，死刑也。自此以上，司刑所職也。劓音牛冀反。刖音五刮反，又音月。」","sentenceOrder":119},
  {"id":"s_work_han_thu_27_120","chapterId":"ch_work_han_thu_27","textTraditional":"〔六〕　師古曰：「踣謂斃之也，音妨付反。」","sentenceOrder":120},
  {"id":"s_work_han_thu_27_121","chapterId":"ch_work_han_thu_27","textTraditional":"〔七〕　師古曰：「黥面之人不妨禁衛也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_27_122","chapterId":"ch_work_han_thu_27","textTraditional":"〔八〕　師古曰：「以其貌毀，故遠之。」","sentenceOrder":122},
  {"id":"s_work_han_thu_27_123","chapterId":"ch_work_han_thu_27","textTraditional":"〔九〕　師古曰：「人道既絕，於事便也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_27_124","chapterId":"ch_work_han_thu_27","textTraditional":"〔一０〕師古曰：「驅御禽獸，無足可也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_27_125","chapterId":"ch_work_han_thu_27","textTraditional":"〔一一〕師古曰：「完謂不虧其體，但居作也。積，積聚之物也。自此以上，掌戮所職也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_27_126","chapterId":"ch_work_han_thu_27","textTraditional":"〔一二〕李奇曰：「男女徒總名為奴。」","sentenceOrder":126},
  {"id":"s_work_han_thu_27_127","chapterId":"ch_work_han_thu_27","textTraditional":"〔一三〕孟康曰：「主暴燥舂之也。」韋昭曰：「舂，舂人；槁，槁人也。給此二官之役。」師古曰：「槁音古老反。」","sentenceOrder":127},
  {"id":"s_work_han_thu_27_128","chapterId":"ch_work_han_thu_27","textTraditional":"〔一四〕師古曰：「有爵，謂命士以上也。齔，毀齒，男子八歲，女子七歲，而毀齒矣。自此以上，司厲所職也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_27_129","chapterId":"ch_work_han_thu_27","textTraditional":"周道既衰，穆王眊荒，命甫侯度時作刑，以詰四方。〔一〕墨罰之屬千，劓罰之屬千，髕罰之屬五百，宮罰之屬三百，大辟之罰其屬二百。〔二〕五刑之屬三千，〔三〕蓋多於平邦中典五百章，所謂刑亂邦用重典者也。","sentenceOrder":129},
  {"id":"s_work_han_thu_27_130","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「穆王，昭王之子也，享國既百年，而王眊亂荒忽，乃命甫侯為司寇，商度時宜，而作刑之制，以治四方也。甫，國名也。眊音莫報反。度音大各反。」","sentenceOrder":130},
  {"id":"s_work_han_thu_27_131","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「髕罰，去膝頭骨。大辟，死刑也。髕音頻忍反。」","sentenceOrder":131},
  {"id":"s_work_han_thu_27_132","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「五者之刑凡三千。」","sentenceOrder":132},
  {"id":"s_work_han_thu_27_133","chapterId":"ch_work_han_thu_27","textTraditional":"春秋之時，王道寖壞，教化不行，〔一〕子產相鄭而鑄刑書〔二〕。晉叔嚮非之曰：〔三〕「昔先王議事以制，不為刑辟。〔四〕懼民之有爭心也，猶不可禁禦，是故閑之以誼，糾之以政，〔五〕行之以禮，守之以信，奉之以仁；〔六〕制為祿位以勸其從，〔七〕嚴斷刑罰以威其淫。〔八〕懼其未也，故誨之以忠，愯之以行，〔九〕教之以務，〔一０〕使之以和，〔一一〕臨之以敬，蒞之以彊，〔一二〕斷之以剛。猶求聖哲之上，明察之官，忠信之長，慈惠之師。〔一三〕民於是乎可任使也，而不生禍亂。民知有辟，則不忌於上，並有爭心，以徵於書，而徼幸以成之，弗可為矣。〔一四〕夏有亂政而作禹刑，商有亂政而作湯刑，周有亂政而作九刑。〔一五〕三辟之興，皆叔世也。〔一六〕今吾子相鄭國，制參辟，鑄刑書，〔一七〕將以靖民，不亦難乎！〔一八〕詩曰：『儀式刑文王之德，日靖四方。』〔一九〕又曰：『儀刑文王，萬邦作孚。』〔二０〕如是，何辟之有？〔二一〕民知爭端矣，將棄禮而徵於書。〔二二〕錐刀之末，將盡爭之，〔二三〕亂獄滋豐，貨賂並行。〔二四〕終子之世，鄭其敗虖！」子產報曰：「若吾子之言，僑不材，不能及子孫，吾以救世也。」〔二五〕媮薄之政，自是滋矣。孔子傷之，曰：「導之以德，齊之以禮，有恥且格；導之以政，齊之以刑，民免而無恥。」〔二六〕「禮樂不興，則刑罰不中；刑罰不中，則民無所錯手足。」〔二七〕孟氏使陽膚為士師，〔二八〕問於曾子，〔二九〕亦曰：「上失其道，民散久矣。如得其情，則哀矜而勿喜。」〔三０〕","sentenceOrder":133},
  {"id":"s_work_han_thu_27_134","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「寖，漸也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_27_135","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「子產，鄭大夫公孫僑也。鑄刑法於鼎，事在昭六年。」","sentenceOrder":135},
  {"id":"s_work_han_thu_27_136","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「叔嚮，晉大夫羊舌肸也。遺其書以非之。嚮音許兩反。」","sentenceOrder":136},
  {"id":"s_work_han_thu_27_137","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　李奇曰：「先議其犯事，議定然後乃斷其罪，不為一成之刑著於鼎也。」師古曰：「虞舜則象以典刑，流宥五刑。周禮則三典五刑，以詰邦國。非不豫設，但弗宣露使人知之。」","sentenceOrder":137},
  {"id":"s_work_han_thu_27_138","chapterId":"ch_work_han_thu_27","textTraditional":"〔五〕　師古曰：「閑，防也。糾，舉也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_27_139","chapterId":"ch_work_han_thu_27","textTraditional":"〔六〕　師古曰：「奉，養也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_27_140","chapterId":"ch_work_han_thu_27","textTraditional":"〔七〕　師古曰：「勸其從教之心也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_27_141","chapterId":"ch_work_han_thu_27","textTraditional":"〔八〕　師古曰：「淫，放也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_27_142","chapterId":"ch_work_han_thu_27","textTraditional":"〔九〕　晉灼曰：「愯，古竦字也。」師古曰：「愯謂獎也，又音所項反。」","sentenceOrder":142},
  {"id":"s_work_han_thu_27_143","chapterId":"ch_work_han_thu_27","textTraditional":"〔一０〕師古曰：「時所急。」","sentenceOrder":143},
  {"id":"s_work_han_thu_27_144","chapterId":"ch_work_han_thu_27","textTraditional":"〔一一〕師古曰：「悅以使人也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_27_145","chapterId":"ch_work_han_thu_27","textTraditional":"〔一二〕師古曰：「蒞謂監視也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_27_146","chapterId":"ch_work_han_thu_27","textTraditional":"〔一三〕師古曰：「上謂公侯也。官，卿佐也。長、師，皆列職之首也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_27_147","chapterId":"ch_work_han_thu_27","textTraditional":"〔一四〕師古曰：「辟，法也。為，治也。權移於法，故人不畏上，因危文以生詐妄，徼幸而成巧，則弗可治也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_27_148","chapterId":"ch_work_han_thu_27","textTraditional":"〔一五〕韋昭曰：「謂正刑五，及流、贖、鞭、扑也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_27_149","chapterId":"ch_work_han_thu_27","textTraditional":"〔一六〕師古曰：「叔世言晚時也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_27_150","chapterId":"ch_work_han_thu_27","textTraditional":"〔一七〕孟康曰：「謂夏、殷、周亂政所制三辟也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_27_151","chapterId":"ch_work_han_thu_27","textTraditional":"〔一八〕師古曰：「靖，安也，一曰治也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_27_152","chapterId":"ch_work_han_thu_27","textTraditional":"〔一九〕師古曰：「周頌我將之詩也。言法象文王之德，以為儀式，則四方日以安靖也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_27_153","chapterId":"ch_work_han_thu_27","textTraditional":"〔二０〕師古曰：「大雅文王詩也。孚，信也。又言法象文王，則萬國皆信順也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_27_154","chapterId":"ch_work_han_thu_27","textTraditional":"〔二一〕師古曰：「若詩所言，不宜制刑辟。」","sentenceOrder":154},
  {"id":"s_work_han_thu_27_155","chapterId":"ch_work_han_thu_27","textTraditional":"〔二二〕師古曰：「取證於刑書。」","sentenceOrder":155},
  {"id":"s_work_han_thu_27_156","chapterId":"ch_work_han_thu_27","textTraditional":"〔二三〕師古曰：「喻微細。」","sentenceOrder":156},
  {"id":"s_work_han_thu_27_157","chapterId":"ch_work_han_thu_27","textTraditional":"〔二四〕師古曰：「滋，益也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_27_158","chapterId":"ch_work_han_thu_27","textTraditional":"〔二五〕師古曰：「言雖非長久之法，且救當時之敝。」","sentenceOrder":158},
  {"id":"s_work_han_thu_27_159","chapterId":"ch_work_han_thu_27","textTraditional":"〔二六〕師古曰：「論語載孔子之言也。格，正也。言用德禮，則人有恥而自正；尚政刑，則下苟免而無恥。」","sentenceOrder":159},
  {"id":"s_work_han_thu_27_160","chapterId":"ch_work_han_thu_27","textTraditional":"〔二七〕師古曰：「亦論語所載孔子之言也。禮以治人，樂以易俗，二者不興，則刑罰濫矣。錯，置（矣）〔也〕。」","sentenceOrder":160},
  {"id":"s_work_han_thu_27_161","chapterId":"ch_work_han_thu_27","textTraditional":"〔二八〕師古曰：「亦論語所載。陽膚，曾子弟子也。士師，獄官。」","sentenceOrder":161},
  {"id":"s_work_han_thu_27_162","chapterId":"ch_work_han_thu_27","textTraditional":"〔二九〕師古曰：「問何以居此職也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_27_163","chapterId":"ch_work_han_thu_27","textTraditional":"〔三０〕師古曰：「此曾子對辭。（前）〔言〕萌俗澆離，輕犯於法，乃由上失其道，非下之過。今汝雖得獄情，當哀矜之，勿（自）喜也。」","sentenceOrder":163},
  {"id":"s_work_han_thu_27_164","chapterId":"ch_work_han_thu_27","textTraditional":"陵夷至於戰國，韓任申子，秦用商鞅，連相坐之法，造參夷之誅；〔一〕增加肉刑、大辟，有鑿顛、抽脅、鑊亨之刑。〔二〕","sentenceOrder":164},
  {"id":"s_work_han_thu_27_165","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「參夷，夷三族。」","sentenceOrder":165},
  {"id":"s_work_han_thu_27_166","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「鼎大而無足曰鑊，以鬻人也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_27_167","chapterId":"ch_work_han_thu_27","textTraditional":"至於秦始皇，兼吞戰國，遂毀先王之法，滅禮誼之官，專任刑罰，躬操文墨，〔一〕晝斷獄，夜理書，自程決事，日縣石之一。〔二〕而姦邪並生，赭衣塞路，囹圄成市，天下愁怨，潰而叛之。","sentenceOrder":167},
  {"id":"s_work_han_thu_27_168","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「躬，身也。操，執持也，音千高反。」","sentenceOrder":168},
  {"id":"s_work_han_thu_27_169","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　服虔曰：「縣，稱也。石，百二十斤也。始皇省讀文書，日以百二十斤為程。」","sentenceOrder":169},
  {"id":"s_work_han_thu_27_170","chapterId":"ch_work_han_thu_27","textTraditional":"漢興，高祖初入關，約法三章曰：「殺人者死，傷人及盜抵罪。」蠲削煩苛，兆民大說。〔一〕其後四夷未附，兵革未息，三章之法不足以禦姦，〔二〕於是相國蕭何攈摭秦法，〔三〕取其宜於時者，作律九章。","sentenceOrder":170},
  {"id":"s_work_han_thu_27_171","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":171},
  {"id":"s_work_han_thu_27_172","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「禦，止也。」","sentenceOrder":172},
  {"id":"s_work_han_thu_27_173","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「攈摭，謂收拾也。攈音九問反。摭音之石反。」","sentenceOrder":173},
  {"id":"s_work_han_thu_27_174","chapterId":"ch_work_han_thu_27","textTraditional":"當孝惠、高后時，百姓新免毒蠚，人欲長幼養老。〔一〕蕭、曹為相，填以無為，〔二〕從民之欲，而不擾亂，是以衣食滋殖，刑罰用稀。","sentenceOrder":174},
  {"id":"s_work_han_thu_27_175","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「蠚音呼各反。」","sentenceOrder":175},
  {"id":"s_work_han_thu_27_176","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「言以無為之法填安百姓也。填音竹刃反。」","sentenceOrder":176},
  {"id":"s_work_han_thu_27_177","chapterId":"ch_work_han_thu_27","textTraditional":"及孝文即位，躬脩玄默，勸趣農桑，減省租賦。而將相皆舊功臣，少文多質，懲惡亡秦之政，論議務在寬厚，恥言人之過失。化行天下，告訐之俗易。〔一〕吏安其官，民樂其業，畜積歲增，戶口寖息。〔二〕風流篤厚，禁罔疏闊。選張釋之為廷尉，罪疑者予民，〔三〕是以刑罰大省，至於斷獄四百，〔四〕有刑錯之風。","sentenceOrder":177},
  {"id":"s_work_han_thu_27_178","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「訐，面相斥罪也，音居謁反。」","sentenceOrder":178},
  {"id":"s_work_han_thu_27_179","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「畜讀曰蓄。寖，益也。息，生也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_27_180","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「從輕斷。」","sentenceOrder":180},
  {"id":"s_work_han_thu_27_181","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　師古曰：「謂普天之下重罪者也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_27_182","chapterId":"ch_work_han_thu_27","textTraditional":"即位十三年，齊太倉令淳于公有罪當刑，詔獄逮繫長安。〔一〕淳于公無男，有五女，當行會逮，罵其女曰：「生子不生男，緩急非有益（也）！」其少女緹縈，自傷悲泣，〔二〕乃隨其父至長安，上書曰：「妾父為吏，齊中皆稱其廉平，今坐法當刑。妾傷夫死者不可復生，刑者不可復屬，〔三〕雖後欲改過自新，其道亡繇也。〔四〕妾願沒入為官婢，以贖父刑罪，使得自新。」書奏天子，天子憐悲其意，遂下令曰：「制詔御史：蓋聞有虞氏之時，畫衣冠異章服以為戮，而民弗犯，何治之至也！今法有肉刑三，〔五〕而姦不止，其咎安在？非乃朕德之薄，而教不明與！〔六〕吾甚自愧。故夫訓道不純而愚民陷焉。〔七〕詩曰：『愷弟君子，民之父母。』〔八〕今人有過，教未施而刑已加焉，或欲改行為善，而道亡繇至，〔九〕朕甚憐之。夫刑至斷支體，刻肌膚，終身不息，〔一０〕何其刑之痛而不德也！豈稱為民父母之意哉？其除肉刑，有以易之；及令罪人各以輕重，不亡逃，有年而免。〔一一〕具為令。」〔一二〕","sentenceOrder":182},
  {"id":"s_work_han_thu_27_183","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「逮，及也。辭之所及，則追捕之，故謂之逮。一曰逮者，在道將送，防禦不絕，若今之傳送囚也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_27_184","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「緹縈，女名也。緹音他弟反。」","sentenceOrder":184},
  {"id":"s_work_han_thu_27_185","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「屬，聯也，音之欲反。」","sentenceOrder":185},
  {"id":"s_work_han_thu_27_186","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　師古曰：「繇讀與由同。由，從也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_27_187","chapterId":"ch_work_han_thu_27","textTraditional":"〔五〕　孟康曰：「黥、劓二，（則）〔刖〕左右趾合一，凡三也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_27_188","chapterId":"ch_work_han_thu_27","textTraditional":"〔六〕　師古曰：「與讀曰歟。」","sentenceOrder":188},
  {"id":"s_work_han_thu_27_189","chapterId":"ch_work_han_thu_27","textTraditional":"〔七〕　師古曰：「道讀曰導。」","sentenceOrder":189},
  {"id":"s_work_han_thu_27_190","chapterId":"ch_work_han_thu_27","textTraditional":"〔八〕　師古曰：「大雅泂酌之詩也。言君子有和樂簡易之德，則其下尊之如父，親之如母也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_27_191","chapterId":"ch_work_han_thu_27","textTraditional":"〔九〕　師古曰：「繇讀與由同。」","sentenceOrder":191},
  {"id":"s_work_han_thu_27_192","chapterId":"ch_work_han_thu_27","textTraditional":"〔一０〕師古曰：「息，生也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_27_193","chapterId":"ch_work_han_thu_27","textTraditional":"〔一一〕孟康曰：「其不亡逃者，滿其年數，得免為庶人。」","sentenceOrder":193},
  {"id":"s_work_han_thu_27_194","chapterId":"ch_work_han_thu_27","textTraditional":"〔一二〕師古曰：「使更為條制。」","sentenceOrder":194},
  {"id":"s_work_han_thu_27_195","chapterId":"ch_work_han_thu_27","textTraditional":"丞相張蒼、御史大夫馮敬奏言：「肉刑所以禁姦，所由來者久矣。陛下下明詔，憐萬民之一有過被刑者終身不息，及罪人欲改行為善而道亡繇至，於盛德，臣等所不及也。臣謹議請定律曰：諸當完者，完為城旦舂；〔一〕當黥者，髡鉗為城旦舂；當劓者，笞三百；當斬左止者，笞五百；當斬右止，及殺人先自告，及吏坐受賕枉法，守縣官財物而即盜之，已論命復有笞罪者，皆棄市。〔二〕罪人獄已決，完為城旦舂，滿三歲為鬼薪白粲。鬼薪白粲一歲，為隸臣妾。隸臣妾一歲，免為庶人。〔三〕隸臣妾滿二歲，為司寇。司寇一歲，及作如司寇二歲，皆免為庶人。〔四〕其亡逃及有罪耐以上，不用此令〔五〕。前令之刑城旦舂歲而非禁錮者，如完為城旦舂歲數以免。〔六〕臣昧死請。」制曰：「可。」是後，外有輕刑之名，內實殺人。斬右止者又當死。斬左止者笞五百，當劓者笞三百，率多死。〔七〕","sentenceOrder":195},
  {"id":"s_work_han_thu_27_196","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　臣瓚曰：「文帝除肉刑，皆有以易之，故以完易髡，以笞代劓，以釱左右止代刖。今既曰完矣，不復云以完代完也。此當言髡者完也。」","sentenceOrder":196},
  {"id":"s_work_han_thu_27_197","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　李奇曰：「命，逃亡也。復於論命中有罪也。」晉灼曰：「命者，名也，成其罪也。」師古曰：「止，足也。當斬右足者，以其罪次重，故從棄市也。殺人先自告，謂殺人而自首，得免罪者也。吏受賕枉法，謂曲公法而受賂者也。守縣官財物而即盜之，即今律所謂主守自盜者也。殺人害重，受賕盜物，贓汙之身，故此三罪已被論名而又犯笞，亦皆棄市也。今流俗書本『笞三百』『笞五百』之上及『劓者』之下有『籍笞』字，『復有笞罪』亦云『復有籍笞罪』，皆後人妄加耳，舊本無也。」","sentenceOrder":197},
  {"id":"s_work_han_thu_27_198","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「男子為隸臣，女子為隸妾。鬼薪白粲滿（三）〔一〕歲為隸臣，隸臣一歲免為庶人。隸妾亦然也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_27_199","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　如淳曰：「罪降為司寇，故一歲，正司寇，故二歲也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_27_200","chapterId":"ch_work_han_thu_27","textTraditional":"〔五〕　師古曰：「於本罪中又重犯者也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_27_201","chapterId":"ch_work_han_thu_27","textTraditional":"〔六〕　李奇曰：「謂文帝作此令之前有刑者。」","sentenceOrder":201},
  {"id":"s_work_han_thu_27_202","chapterId":"ch_work_han_thu_27","textTraditional":"〔七〕　師古曰：「斬右止者棄市，故入於死。以笞五百代斬左止，笞三百代劓，笞數既多，亦不活也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_27_203","chapterId":"ch_work_han_thu_27","textTraditional":"景帝元年，下詔曰：「加笞與重罪無異，〔一〕幸而不死，不可為人。〔二〕其定律：笞五百曰三百，笞三百曰二百。」猶尚不全。至中六年，又下詔曰：「加笞者，或至死而笞未畢，朕甚憐之。其減笞三百曰二百，笞二百曰一百。」又曰：「笞者，所以教之也，其定箠令。」〔三〕丞相劉舍、御史大夫衛綰請：「笞者，箠長五尺，其本大一寸，其竹也，末薄半寸，皆平其節。當笞者笞臀。〔四〕毋得更人，〔五〕畢一罪乃更人。」自是笞者得全，然酷吏猶以為威。死刑既重，而生刑又輕，民易犯之。","sentenceOrder":203},
  {"id":"s_work_han_thu_27_204","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　孟康曰：「重罪謂死刑。」","sentenceOrder":204},
  {"id":"s_work_han_thu_27_205","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「謂不能自起居也。」","sentenceOrder":205},
  {"id":"s_work_han_thu_27_206","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「箠，策也，所以擊者也，音止橤反。」","sentenceOrder":206},
  {"id":"s_work_han_thu_27_207","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　如淳曰：「然則先時笞背也。」師古曰：「臀音徒門反。」","sentenceOrder":207},
  {"id":"s_work_han_thu_27_208","chapterId":"ch_work_han_thu_27","textTraditional":"〔五〕　師古曰：「謂行笞者不更易人也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_27_209","chapterId":"ch_work_han_thu_27","textTraditional":"及至孝武即位，外事四夷之功，內盛耳目之好，徵發煩數，百姓貧耗，〔一〕窮民犯法，酷吏擊斷，姦軌不勝。於是招進張湯、趙禹之屬，條定法令，作見知故縱、監臨部主之法，〔二〕緩深故之罪，〔三〕急縱出之誅。〔四〕其後姦猾巧法，轉相比況，禁罔寖密〔五〕。律令凡三百五十九章，大辟四百九條，千八百八十二事，死罪決事比萬三千四百七十二事。〔六〕文書盈於几閣，典者不能遍睹。是以郡國承用者駮，〔七〕或罪同而論異。姦吏因緣為市，〔八〕所欲活則傅生議，所欲陷則予死比，〔九〕議者咸冤傷之。","sentenceOrder":209},
  {"id":"s_work_han_thu_27_210","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「耗，損也，音呼到反。」","sentenceOrder":210},
  {"id":"s_work_han_thu_27_211","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「見知人犯法不舉告為故縱，而所監臨部主有罪并連坐也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_27_212","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　孟康曰：「孝武欲急刑，吏深害及故入人罪者，皆寬緩。」","sentenceOrder":212},
  {"id":"s_work_han_thu_27_213","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　師古曰：「吏釋罪人，疑以為縱出，則急誅之。亦言尚酷。」","sentenceOrder":213},
  {"id":"s_work_han_thu_27_214","chapterId":"ch_work_han_thu_27","textTraditional":"〔五〕　師古曰：「寖，漸也。其下亦同。」","sentenceOrder":214},
  {"id":"s_work_han_thu_27_215","chapterId":"ch_work_han_thu_27","textTraditional":"〔六〕　師古曰：「比，以例相比況也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_27_216","chapterId":"ch_work_han_thu_27","textTraditional":"〔七〕　師古曰：「不曉其指，用意不同也。」","sentenceOrder":216},
  {"id":"s_work_han_thu_27_217","chapterId":"ch_work_han_thu_27","textTraditional":"〔八〕　師古曰：「弄法而受財，若市買之交易。」","sentenceOrder":217},
  {"id":"s_work_han_thu_27_218","chapterId":"ch_work_han_thu_27","textTraditional":"〔九〕　師古曰：「傅讀曰附。」","sentenceOrder":218},
  {"id":"s_work_han_thu_27_219","chapterId":"ch_work_han_thu_27","textTraditional":"宣帝自在閭閻而知其若此，及即尊位，廷史路溫舒上疏，言秦有十失，其一尚存，治獄之吏是也。語在溫舒傳。上深愍焉，乃下詔曰：「間者吏用法，巧文寖深，是朕之不德也。夫決獄不當，使有罪興邪，不辜蒙戮，〔一〕父子悲恨，朕甚傷之。今遣廷史與郡鞠獄，任輕祿薄，〔二〕其為置廷平，秩六百石，員四人。其務平之，以稱朕意。」於是選于定國為廷尉，求明察寬恕黃霸等以為廷平，季秋後請讞。時上常幸宣室，齋居而決事，〔三〕獄刑號為平矣。時涿郡太守鄭昌上疏言：「聖王置諫爭之臣者，非以崇德，防逸豫之生也；立法明刑者，非以為治，救衰亂之起也。今明主躬垂明聽，雖不置廷平，獄將自正；若開後嗣，不若刪定律令。〔四〕律令一定，愚民知所避，姦吏無所弄矣。今不正其本，而置廷平以理其末也，政衰聽怠，則廷平將招權而為亂首矣。」〔五〕宣帝未及修正。","sentenceOrder":219},
  {"id":"s_work_han_thu_27_220","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　晉灼曰：「當重而輕，使有罪者起邪惡之心也。」師古曰：「有罪者更興邪惡，無辜者反陷重刑，是決獄不平故。」","sentenceOrder":220},
  {"id":"s_work_han_thu_27_221","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　如淳曰：「廷史，廷尉史也。以囚辭決獄事為鞠，謂疑獄也。」李奇曰：「鞠，窮也，獄事窮竟也。」師古曰：「李說是也。」","sentenceOrder":221},
  {"id":"s_work_han_thu_27_222","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　如淳曰：「宣室，布政教之室也。重用刑，故齋戒以決事。」晉灼曰：「未央宮中有宣室殿。」師古曰：「晉說是也。賈誼傳亦云受釐坐宣室，蓋其殿在前殿之側也，齋則居之。」","sentenceOrder":222},
  {"id":"s_work_han_thu_27_223","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　師古曰：「刪，刊也。有不便者，則刊而除之。」","sentenceOrder":223},
  {"id":"s_work_han_thu_27_224","chapterId":"ch_work_han_thu_27","textTraditional":"〔五〕　蘇林曰：「招音翹。翹，舉也，猶賣弄也。」孟康曰：「招，求也，招致權著己也。」師古曰：「孟說是也。」","sentenceOrder":224},
  {"id":"s_work_han_thu_27_225","chapterId":"ch_work_han_thu_27","textTraditional":"至元帝初立，乃下詔曰：「夫法令者，所以抑暴扶弱，欲其難犯而易避也。今律令煩多而不約，自典文者不能分明，而欲羅元元之不逮，〔一〕斯豈刑中之意哉！〔二〕其議律令可蠲除輕減者，條奏，唯在便安萬姓而已。」","sentenceOrder":225},
  {"id":"s_work_han_thu_27_226","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「羅，網也。不逮，言意識所不及。」","sentenceOrder":226},
  {"id":"s_work_han_thu_27_227","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「中，當也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_27_228","chapterId":"ch_work_han_thu_27","textTraditional":"至成帝河平中，復下詔曰：「甫刑云『五刑之屬三千，大辟之罰其屬二百』，〔一〕今大辟之刑千有餘條，律令煩多，百有餘萬言，奇請它比，日以益滋，〔二〕自明習者不知所由，〔三〕欲以曉喻眾庶，不亦難乎！於以羅元元之民，夭絕亡辜，豈不哀哉！其與中二千石、二千石、博士及明習律令者議減死刑及可蠲除約省者，令較然易知，條奏。書不云乎？『惟刑之恤哉！』〔四〕其審核之，務準古法，〔五〕朕將盡心覽焉。」有司無仲山父將明之材，〔六〕不能因時廣宣主恩，建立明制，為一代之法，而徒鉤摭微細，毛舉數事，以塞詔而已。〔七〕是以大議不立，遂以至今。議者或曰，法難數變，此庸人不達，疑塞治道，聖智之所常患者也。〔八〕故略舉漢興以來，法令稍定而合古便今者。","sentenceOrder":228},
  {"id":"s_work_han_thu_27_229","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「甫刑，即周書呂刑。初為呂侯，號曰呂刑，後為甫侯，又稱甫刑。」","sentenceOrder":229},
  {"id":"s_work_han_thu_27_230","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「奇請，謂常文之外，主者別有所請以定罪也。它比，謂引它類以比附之，稍增律條也。奇音居宜反。」","sentenceOrder":230},
  {"id":"s_work_han_thu_27_231","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「由，從也。」","sentenceOrder":231},
  {"id":"s_work_han_thu_27_232","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　師古曰：「虞書舜典之辭。恤，憂也，言當憂刑也。」","sentenceOrder":232},
  {"id":"s_work_han_thu_27_233","chapterId":"ch_work_han_thu_27","textTraditional":"〔五〕　師古曰：「核，究其實也。」","sentenceOrder":233},
  {"id":"s_work_han_thu_27_234","chapterId":"ch_work_han_thu_27","textTraditional":"〔六〕　師古曰：「有司以下，史家之言也。大雅蒸人之詩曰：『肅肅王命，仲山父將之；邦國若否，仲山父明之。』將，行也。否，不善也。言王有誥命，則仲山父行之；邦國有不善之事，則仲山父明之。故引以為美，傷今不能然也。」","sentenceOrder":234},
  {"id":"s_work_han_thu_27_235","chapterId":"ch_work_han_thu_27","textTraditional":"〔七〕　師古曰：「毛舉，言舉毫毛之事，輕小之甚〔者〕。塞猶當（者）也。」","sentenceOrder":235},
  {"id":"s_work_han_thu_27_236","chapterId":"ch_work_han_thu_27","textTraditional":"〔八〕　師古曰：「塞謂不通也。」","sentenceOrder":236},
  {"id":"s_work_han_thu_27_237","chapterId":"ch_work_han_thu_27","textTraditional":"漢興之初，雖有約法三章，網漏吞舟之魚，〔一〕然其大辟，尚有夷三族之令。令曰：「當三族者，皆先黥，劓，斬左右止，笞殺之，梟其首，菹其骨肉於市。〔二〕其誹謗詈詛者，又先斷舌。」故謂之具五刑。彭越、韓信之屬皆受此誅。至高后元年，乃除三族罪、祅言令。孝文二年，又詔丞相、太尉、御史：「法者，治之正，所以禁暴而衛善人也。今犯法者已論，而使無罪之父母妻子同產坐之及收，朕甚弗取。其議。」左右丞相周勃、陳平奏言：「父母妻子同產相坐及收，所以累其心，使重犯法也。〔三〕收之之道，所由來久矣。臣之愚計，以為如其故便。」文帝復曰：「朕聞之，法正則民愨，罪當則民從。〔四〕且夫牧民而道之以善者，吏也；〔五〕既不能道，又以不正之法罪之，是法反害於民，為暴者也。〔六〕朕未見其便，宜孰計之。」平、勃乃曰：「陛下幸加大惠於天下，使有罪不收，無罪不相坐，甚盛德，臣等所不及也。臣等謹奉詔，盡除收律、相坐法。」其後，新垣平謀為逆，復行三族之誅。由是言之，風俗移易，人性相近而習相遠，信矣。〔七〕夫以孝文之仁，平、勃之知，猶有過刑謬論如此甚也，而況庸材溺於末流者乎？","sentenceOrder":237},
  {"id":"s_work_han_thu_27_238","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「言疏闊。吞舟，謂大魚也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_27_239","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「菹謂醢也。菹音側於反。」","sentenceOrder":239},
  {"id":"s_work_han_thu_27_240","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「重，難也。累音力瑞反。」","sentenceOrder":240},
  {"id":"s_work_han_thu_27_241","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　師古曰：「愨，謹也，音丘角反。」","sentenceOrder":241},
  {"id":"s_work_han_thu_27_242","chapterId":"ch_work_han_thu_27","textTraditional":"〔五〕　師古曰：「道讀曰導。以善導之也。」","sentenceOrder":242},
  {"id":"s_work_han_thu_27_243","chapterId":"ch_work_han_thu_27","textTraditional":"〔六〕　師古曰：「法害於人，是法為暴。」","sentenceOrder":243},
  {"id":"s_work_han_thu_27_244","chapterId":"ch_work_han_thu_27","textTraditional":"〔七〕　師古曰：「論語云孔子曰『性相近，習相遠』也，言人同稟五常之性，其所取舍本相近也，但所習各異，漸漬而移，則相遠矣。」","sentenceOrder":244},
  {"id":"s_work_han_thu_27_245","chapterId":"ch_work_han_thu_27","textTraditional":"周官有五聽、八議、三刺、三宥、三赦之法。〔一〕五聽：一曰辭聽，〔二〕二曰色聽，〔三〕三曰氣聽，〔四〕四曰耳聽，〔五〕五曰目聽。〔六〕八議：一曰議親，〔七〕二曰議故，〔八〕三曰議賢，〔九〕四曰議能，〔一０〕五曰議功，〔一一〕六曰議貴，〔一二〕七曰議勤，〔一三〕八曰議賓。〔一四〕三刺：一曰訊群臣，二曰訊群吏，三曰訊萬民。〔一五〕三宥：一曰弗識，二曰過失，三曰遺忘。〔一六〕三赦：一曰幼弱，二曰老眊，三曰憃愚。〔一七〕凡囚，「上罪梏拲而桎，中罪梏桎，下罪梏；王之同族拲，有爵者桎，以待弊。」〔一八〕高皇帝七年，制詔御史：「獄之疑者，吏或不敢決，有罪者久而不論，無罪者久繫不決。自今以來，縣道官獄疑者，各讞所屬二千石官，二千石官以其罪名當報之。〔一九〕所不能決者，皆移廷尉，廷尉亦當報之。廷尉所不能決，謹具為奏，傅所當比律令以聞。」〔二０〕上恩如此，吏猶不能奉宣。故孝景中五年復下詔曰：「諸獄疑，雖文致於法而於人心不厭者，輒讞之。」其後獄吏復避微文，遂其愚心。至後元年，又下詔曰：「獄，重事也。人有愚智，官有上下。獄疑者讞，有令讞者已報讞而後不當，讞者不為失。」〔二一〕自此之後，獄刑益詳，近於五聽三宥之意。三年復下詔曰：「高年老長，人所尊敬也；鰥寡不屬逮者，人所哀憐也。〔二二〕其著令：年八十以上，八歲以下，及孕者未乳，〔二三〕師、朱儒〔二四〕當鞠繫者，頌繫之。」〔二五〕至孝宣元康四年，又下詔曰：「朕念夫耆老之人，髮齒墮落，血氣既衰，亦無暴逆之心，今或羅于文法，執于囹圄，不得終其年命，朕甚憐之。自今以來，諸年八十非誣告殺傷人，它皆勿坐。」至成帝鴻嘉元年，定令：「年未滿七歲，賊鬥殺人及犯殊死者，上請廷尉以聞，得減死。」合於三赦幼弱老眊之人。此皆法令稍定，近古而便民者也。〔二六〕","sentenceOrder":245},
  {"id":"s_work_han_thu_27_246","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「刺，殺也。訊而有罪，則殺之也。宥，寬也。赦，舍也，謂釋置也。」","sentenceOrder":246},
  {"id":"s_work_han_thu_27_247","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「觀其出言，不直則煩。」","sentenceOrder":247},
  {"id":"s_work_han_thu_27_248","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「觀其顏色，不直則變。」","sentenceOrder":248},
  {"id":"s_work_han_thu_27_249","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　師古曰：「觀其氣息，不直則喘。」","sentenceOrder":249},
  {"id":"s_work_han_thu_27_250","chapterId":"ch_work_han_thu_27","textTraditional":"〔五〕　師古曰：「觀其聽聆，不直則惑。」","sentenceOrder":250},
  {"id":"s_work_han_thu_27_251","chapterId":"ch_work_han_thu_27","textTraditional":"〔六〕　師古曰：「觀其瞻視，不直則亂。」","sentenceOrder":251},
  {"id":"s_work_han_thu_27_252","chapterId":"ch_work_han_thu_27","textTraditional":"〔七〕　師古曰：「王之親族也。」","sentenceOrder":252},
  {"id":"s_work_han_thu_27_253","chapterId":"ch_work_han_thu_27","textTraditional":"〔八〕　師古曰：「王之故舊也。」","sentenceOrder":253},
  {"id":"s_work_han_thu_27_254","chapterId":"ch_work_han_thu_27","textTraditional":"〔九〕　師古曰：「有德行者也。」","sentenceOrder":254},
  {"id":"s_work_han_thu_27_255","chapterId":"ch_work_han_thu_27","textTraditional":"〔一０〕師古曰：「有道藝者。」","sentenceOrder":255},
  {"id":"s_work_han_thu_27_256","chapterId":"ch_work_han_thu_27","textTraditional":"〔一一〕師古曰：「有大勳力者。」","sentenceOrder":256},
  {"id":"s_work_han_thu_27_257","chapterId":"ch_work_han_thu_27","textTraditional":"〔一二〕師古曰：「爵位高者也。」","sentenceOrder":257},
  {"id":"s_work_han_thu_27_258","chapterId":"ch_work_han_thu_27","textTraditional":"〔一三〕師古曰：「謂盡悴事國者也。」","sentenceOrder":258},
  {"id":"s_work_han_thu_27_259","chapterId":"ch_work_han_thu_27","textTraditional":"〔一四〕師古曰：「謂前代之後，王所不臣者也。自五聽以下至此，皆小司寇所職也。」","sentenceOrder":259},
  {"id":"s_work_han_thu_27_260","chapterId":"ch_work_han_thu_27","textTraditional":"〔一五〕師古曰：「訊，問也，音信。」","sentenceOrder":260},
  {"id":"s_work_han_thu_27_261","chapterId":"ch_work_han_thu_27","textTraditional":"〔一六〕師古曰：「弗識，不審也。過失，非意也。遺忘，（勿）〔忽〕忘也。」","sentenceOrder":261},
  {"id":"s_work_han_thu_27_262","chapterId":"ch_work_han_thu_27","textTraditional":"〔一七〕師古曰：「幼弱，謂七歲以下。老眊，謂八十以上。憃愚，生而癡騃者。自三刺以下至此，皆司刺所職也。眊讀與耄同。憃音丑江反，又音貞巷反。」","sentenceOrder":262},
  {"id":"s_work_han_thu_27_263","chapterId":"ch_work_han_thu_27","textTraditional":"〔一八〕師古曰：「械在手曰梏，兩手同械曰拲，在足曰桎。弊，斷罪也。自此以上掌囚所職也。梏音古篤反。拲即拱字也。桎音之日反。弊音蔽。」","sentenceOrder":263},
  {"id":"s_work_han_thu_27_264","chapterId":"ch_work_han_thu_27","textTraditional":"〔一九〕師古曰：「當謂處斷也。」","sentenceOrder":264},
  {"id":"s_work_han_thu_27_265","chapterId":"ch_work_han_thu_27","textTraditional":"〔二０〕師古曰：「傅讀曰附。」","sentenceOrder":265},
  {"id":"s_work_han_thu_27_266","chapterId":"ch_work_han_thu_27","textTraditional":"〔二一〕師古曰：「解並在景紀。」","sentenceOrder":266},
  {"id":"s_work_han_thu_27_267","chapterId":"ch_work_han_thu_27","textTraditional":"〔二二〕師古曰：「屬音之欲反。」","sentenceOrder":267},
  {"id":"s_work_han_thu_27_268","chapterId":"ch_work_han_thu_27","textTraditional":"〔二三〕師古曰：「乳，產也，音人喻反。」","sentenceOrder":268},
  {"id":"s_work_han_thu_27_269","chapterId":"ch_work_han_thu_27","textTraditional":"〔二四〕如淳曰：「師，樂師盲瞽者。朱儒，短人不能走者。」","sentenceOrder":269},
  {"id":"s_work_han_thu_27_270","chapterId":"ch_work_han_thu_27","textTraditional":"〔二五〕師古曰：「頌讀曰容。容，寬容之，不桎梏。」","sentenceOrder":270},
  {"id":"s_work_han_thu_27_271","chapterId":"ch_work_han_thu_27","textTraditional":"〔二六〕師古曰：「近音其靳反。」","sentenceOrder":271},
  {"id":"s_work_han_thu_27_272","chapterId":"ch_work_han_thu_27","textTraditional":"孔子曰：「如有王者，必世而後仁；善人為國百年，可以勝殘去殺矣。」〔一〕言聖王承衰撥亂而起，被民以德教，〔二〕變而化之，必世然後仁道成焉；至於善人，不入於室，然猶百年勝殘去殺矣。〔三〕此為國者之程式也。今漢道至盛，歷世二百餘載，〔四〕考自昭、宣、元、成、哀、平六世之間，斷獄殊死，率歲千餘口而一人，〔五〕耐罪上至右止，三倍有餘。〔六〕古人有言：「滿堂而飲酒，有一人鄉隅而悲泣，〔七〕則一堂皆為之不樂。」王者之於天下，譬猶一堂之上也，故一人不得其平，為之悽愴於心。今郡國被刑而死者歲以萬數，天下獄二千餘所，其冤死者多少相覆，獄不減一人，此和氣所以未洽者也。","sentenceOrder":272},
  {"id":"s_work_han_thu_27_273","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「論語載孔子之言。此謂若有受命之王，必三十年仁政乃成也。勝殘，謂勝殘暴之人，使不為惡。去殺，不行殺戮也。」","sentenceOrder":273},
  {"id":"s_work_han_thu_27_274","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「被，加也，音皮義反。」","sentenceOrder":274},
  {"id":"s_work_han_thu_27_275","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「論語稱子張問善人之道，子曰：『不踐跡，亦不入于室也。』言善人不但修踐舊跡而已，固少自創制，然亦不能入聖人之室。」","sentenceOrder":275},
  {"id":"s_work_han_thu_27_276","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　師古曰：「今謂撰志時。」","sentenceOrder":276},
  {"id":"s_work_han_thu_27_277","chapterId":"ch_work_han_thu_27","textTraditional":"〔五〕　如淳曰：「率天下犯罪者千口而有一人死。」","sentenceOrder":277},
  {"id":"s_work_han_thu_27_278","chapterId":"ch_work_han_thu_27","textTraditional":"〔六〕　李奇曰：「耐從司寇以上至右止，為千口三人刑。」","sentenceOrder":278},
  {"id":"s_work_han_thu_27_279","chapterId":"ch_work_han_thu_27","textTraditional":"〔七〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":279},
  {"id":"s_work_han_thu_27_280","chapterId":"ch_work_han_thu_27","textTraditional":"原獄刑所以蕃若此者，〔一〕禮教不立，刑法不明，民多貧窮，豪桀務私，姦不輒得，獄豻不平之所致也。〔二〕書云「伯夷降典，悊民惟刑」，〔三〕言制禮以止刑，猶隄之防溢水也。今隄防凌遲，禮制未立；死刑過制，生刑易犯；饑寒並至，窮斯濫溢；豪桀擅私，為之囊橐，〔四〕姦有所隱，則狃而寖廣：〔五〕此刑之所以蕃也。孔子曰：「古之知法者能省刑，本也；今之知法者不失有罪，末矣。」〔六〕又曰：「今之聽獄者，求所以殺之；古之聽獄者，求所以生之。」與其殺不辜，寧失有罪。今之獄吏，上下相驅，以刻為明，深者獲功名，平者多後患。諺曰：「鬻棺者欲歲之疫。」〔七〕非憎人欲殺之，利在於人死也。今治獄吏欲陷害人，亦猶此矣。凡此五疾，獄刑所以尤多者也。","sentenceOrder":280},
  {"id":"s_work_han_thu_27_281","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「蕃，多也，音扶元反。」","sentenceOrder":281},
  {"id":"s_work_han_thu_27_282","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　服虔曰：「鄉亭之獄曰豻。」臣瓚曰：「獄岸，獄訟也。」師古曰：「小雅小宛之詩云『宜岸宜獄』。瓚說是也。」","sentenceOrder":282},
  {"id":"s_work_han_thu_27_283","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「周書甫刑之辭也。悊，知也。言伯夷下禮法以道人，人習知禮，然後用刑也。」","sentenceOrder":283},
  {"id":"s_work_han_thu_27_284","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　師古曰：「有底曰囊，無底曰橐。言容隱姦邪，若囊橐之盛物。」","sentenceOrder":284},
  {"id":"s_work_han_thu_27_285","chapterId":"ch_work_han_thu_27","textTraditional":"〔五〕　師古曰：「狃，串習也。寖，漸也。狃音女救反。」","sentenceOrder":285},
  {"id":"s_work_han_thu_27_286","chapterId":"ch_work_han_thu_27","textTraditional":"〔六〕　師古曰：「省謂減除之，絕於未然，故曰本也。不失有罪，事止聽訟，所以為末。」","sentenceOrder":286},
  {"id":"s_work_han_thu_27_287","chapterId":"ch_work_han_thu_27","textTraditional":"〔七〕　師古曰：「鬻，賣也。疫，癘病也。鬻音育。疫音役。」","sentenceOrder":287},
  {"id":"s_work_han_thu_27_288","chapterId":"ch_work_han_thu_27","textTraditional":"自建武、永平，民亦新免兵革之禍，人有樂生之慮，與高、惠之間同，而政在抑彊扶弱，朝無威福之臣，邑無豪桀之俠。以口率計，斷獄少於成、哀之間什八，可謂清矣。〔一〕然而未能稱意比隆於古者，以其疾未盡除，而刑本不正。","sentenceOrder":288},
  {"id":"s_work_han_thu_27_289","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「十少其八也。」","sentenceOrder":289},
  {"id":"s_work_han_thu_27_290","chapterId":"ch_work_han_thu_27","textTraditional":"善乎！孫卿之論刑也，曰：「世俗之為說者，以為治古者無肉刑，〔一〕有象刑墨黥之屬，菲履赭衣而不純，〔二〕是不然矣。以為治古，則人莫觸罪邪，豈獨無肉刑哉，亦不待象刑矣。〔三〕以為人或觸罪矣，而直輕其刑，是殺人者不死，而傷人者不刑也。罪至重而刑至輕，民無所畏，亂莫大焉。凡制刑之本，將以禁暴惡，且懲其（末）〔未〕也。〔四〕殺人者不死，傷人者不刑，是惠暴而寬惡也。故象刑非生〔於〕治古，方起於亂今也。〔五〕凡爵列官職，賞慶刑罰，皆以類相從者也。一物失稱，亂之端也。〔六〕德不稱位，能不稱官，賞不當功，刑不當罪，不祥莫大（矣）焉。夫征暴誅悖，治之威也。殺人者死，傷人者刑，是百王之所同也，未有知其所由來者也。故治則刑重，亂則刑輕，〔七〕犯治之罪固重，犯亂之罪固輕也。書云『刑罰世重世輕』，此之謂也。」〔八〕所謂「象刑惟明」者，言象天道而作刑，〔九〕安有菲屨赭衣者哉？","sentenceOrder":290},
  {"id":"s_work_han_thu_27_291","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　師古曰：「治古，謂上古至治之時也。治音丈吏反。」","sentenceOrder":291},
  {"id":"s_work_han_thu_27_292","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「菲，草履也。純，緣也。衣不加緣，示有恥也。菲音扶味反。純音之允反。」","sentenceOrder":292},
  {"id":"s_work_han_thu_27_293","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「人不犯法，則象刑無所施也。」","sentenceOrder":293},
  {"id":"s_work_han_thu_27_294","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　師古曰：「懲，止也。」","sentenceOrder":294},
  {"id":"s_work_han_thu_27_295","chapterId":"ch_work_han_thu_27","textTraditional":"〔五〕　如淳曰：「古無象刑也，所有象刑之言者，近起今人惡刑之重，故遂推言古之聖君但以象刑，天下自治。」","sentenceOrder":295},
  {"id":"s_work_han_thu_27_296","chapterId":"ch_work_han_thu_27","textTraditional":"〔六〕　師古曰：「稱，宜也，音尺孕反。」","sentenceOrder":296},
  {"id":"s_work_han_thu_27_297","chapterId":"ch_work_han_thu_27","textTraditional":"〔七〕　李奇曰：「世所以治者，乃刑重也；所以亂者，乃刑輕也。」","sentenceOrder":297},
  {"id":"s_work_han_thu_27_298","chapterId":"ch_work_han_thu_27","textTraditional":"〔八〕　師古曰：「周書甫刑之辭也。言刑罰輕重，各隨其時。」","sentenceOrder":298},
  {"id":"s_work_han_thu_27_299","chapterId":"ch_work_han_thu_27","textTraditional":"〔九〕　師古曰：「虞書益稷曰『咎繇方祗厥敘，方施象刑惟明』，言敬其次敘，施其法刑皆明白也。」","sentenceOrder":299},
  {"id":"s_work_han_thu_27_300","chapterId":"ch_work_han_thu_27","textTraditional":"孫卿之言既然，又因俗說而論之曰：禹承堯舜之後，自以德衰而制肉刑，湯武順而行之者，以俗薄於唐虞故也。今漢承衰周暴秦極敝之流，俗已薄於三代，而行堯舜之刑，是猶以鞿而御駻突，〔一〕違救時之宜矣。且除肉刑者，本欲以全民也，今去髡鉗一等，轉而入於大辟。以死罔民，失本惠矣。〔二〕故死者歲以萬數，刑重之所致也。至乎穿窬之盜，忿怒傷人，男女淫佚，吏為姦臧，〔三〕若此之惡，髡鉗之罰又不足以懲也。故刑者歲十萬數，民既不畏，又曾不恥，刑輕之所生也。故俗之能吏，公以殺盜為威，專殺者勝任，奉法者不治，亂名傷制，不可勝條。是以罔密而姦不塞，刑蕃而民愈嫚。〔四〕必世而未仁，百年而不勝殘，誠以禮樂闕而刑不正也。豈宜惟思所以清原正本之論，刪定律令，篹二百章，以應大辟。〔五〕其餘罪次，於古當生，今觸死者，皆可募行肉刑。〔六〕及傷人與盜，吏受賕枉法，男女淫亂，皆復古刑，為三千章。詆欺文致微細之法，悉蠲除。〔七〕如此，則刑可畏而禁易避，吏不專殺，法無二門，輕重當罪，民命得全，合刑罰之中，殷天人之和，〔八〕順稽古之制，成時雍之化。成康刑錯，雖未可致，孝文斷獄，庶幾可及。詩云「宜民宜人，受祿于天」。〔九〕書曰「立功立事，可以永年」。〔一０〕言為政而宜於民者，功成事立，則受天祿而永年命，所謂「一人有慶，萬民賴之」者也。〔一一〕","sentenceOrder":300},
  {"id":"s_work_han_thu_27_301","chapterId":"ch_work_han_thu_27","textTraditional":"〔一〕　孟康曰：「以繩縛馬口之謂鞿。」晉灼曰：「鞿，古羈字也。」如淳曰：「駻音捍。突，惡馬也。」師古曰：「馬絡頭曰羈也。」","sentenceOrder":301},
  {"id":"s_work_han_thu_27_302","chapterId":"ch_work_han_thu_27","textTraditional":"〔二〕　師古曰：「罔，謂羅網也。」","sentenceOrder":302},
  {"id":"s_work_han_thu_27_303","chapterId":"ch_work_han_thu_27","textTraditional":"〔三〕　師古曰：「佚讀與逸同。」","sentenceOrder":303},
  {"id":"s_work_han_thu_27_304","chapterId":"ch_work_han_thu_27","textTraditional":"〔四〕　師古曰：「塞，止也。蕃，多也，音扶元反。嫚與慢同。」","sentenceOrder":304},
  {"id":"s_work_han_thu_27_305","chapterId":"ch_work_han_thu_27","textTraditional":"〔五〕　孟康曰：「篹音撰。」","sentenceOrder":305},
  {"id":"s_work_han_thu_27_306","chapterId":"ch_work_han_thu_27","textTraditional":"〔六〕　李奇曰：「欲死邪，欲腐邪？」","sentenceOrder":306},
  {"id":"s_work_han_thu_27_307","chapterId":"ch_work_han_thu_27","textTraditional":"〔七〕　師古曰：「詆謂誣也，音丁禮反。」","sentenceOrder":307},
  {"id":"s_work_han_thu_27_308","chapterId":"ch_work_han_thu_27","textTraditional":"〔八〕　李奇曰：「殷亦中。」","sentenceOrder":308},
  {"id":"s_work_han_thu_27_309","chapterId":"ch_work_han_thu_27","textTraditional":"〔九〕　師古曰：「大雅假樂之詩也。蓋嘉成王之德云。」","sentenceOrder":309},
  {"id":"s_work_han_thu_27_310","chapterId":"ch_work_han_thu_27","textTraditional":"〔一０〕師古曰：「今文泰誓之辭也。永，長也。」","sentenceOrder":310},
  {"id":"s_work_han_thu_27_311","chapterId":"ch_work_han_thu_27","textTraditional":"〔一一〕師古曰：「呂刑之辭也。一人，天子也。言天子用刑詳審，有福慶之惠，則眾庶咸賴之也。」","sentenceOrder":311},
  {"id":"s_work_han_thu_27_312","chapterId":"ch_work_han_thu_27","textTraditional":"校勘記","sentenceOrder":312},
  {"id":"s_work_han_thu_27_313","chapterId":"ch_work_han_thu_27","textTraditional":"一０八一頁一二行　有稅有（租）〔賦〕。　王鳴盛說下文即云「稅以足食，賦以足兵」，證之顏注則合作「有稅有賦」。按景祐、殿本都作「有賦」。","sentenceOrder":313},
  {"id":"s_work_han_thu_27_314","chapterId":"ch_work_han_thu_27","textTraditional":"一０八二頁　七行　炎帝火行，故云火（炎）〔災〕。　景祐、殿本都作「災」。王先謙說作「災」是。","sentenceOrder":314},
  {"id":"s_work_han_thu_27_315","chapterId":"ch_work_han_thu_27","textTraditional":"一０八四頁　二行　齊（威）〔桓〕既沒，　景祐、殿本都作「桓」。","sentenceOrder":315},
  {"id":"s_work_han_thu_27_316","chapterId":"ch_work_han_thu_27","textTraditional":"一０八八頁　八行　矜，（特）〔持〕也。　景祐、殿本都作「持」。","sentenceOrder":316},
  {"id":"s_work_han_thu_27_317","chapterId":"ch_work_han_thu_27","textTraditional":"一０八九頁　一行　秦人（憐之謂）〔為〕之出兵。　景祐本無「憐之」二字。王念孫說通典亦無，疑後人所加。「謂」作「為」。","sentenceOrder":317},
  {"id":"s_work_han_thu_27_318","chapterId":"ch_work_han_thu_27","textTraditional":"一０八九頁　六行　而（功）〔國〕滅亡於後。　錢大昭說監本、閩本「功」作「國」。按景祐、殿本都作「國」。王先謙說作「國」是。","sentenceOrder":318},
  {"id":"s_work_han_thu_27_319","chapterId":"ch_work_han_thu_27","textTraditional":"一０九０頁　三行　（遂）〔薳〕射之子　王先謙說「遂」當為「薳」，各本皆誤。按景祐本作「薳」，不誤。","sentenceOrder":319},
  {"id":"s_work_han_thu_27_320","chapterId":"ch_work_han_thu_27","textTraditional":"一０九二頁　四行　自此以上，（皆）〔大〕司寇所職也。　景祐、殿本都作「大」。","sentenceOrder":320},
  {"id":"s_work_han_thu_27_321","chapterId":"ch_work_han_thu_27","textTraditional":"一０九五頁一六行　錯，置（矣）〔也〕。　景祐、殿、局本都作「也」。王先謙說作「也」是。","sentenceOrder":321},
  {"id":"s_work_han_thu_27_322","chapterId":"ch_work_han_thu_27","textTraditional":"一０九六頁　二行　（前）〔言〕萌俗澆離，　景祐本「前」作「言」。殿本「萌」作「民」。下「勿自喜也」，景祐本無「自」字。","sentenceOrder":322},
  {"id":"s_work_han_thu_27_323","chapterId":"ch_work_han_thu_27","textTraditional":"一０九七頁一六行　緩急非有益（也）！　宋祁說姚本「益也」刪去「也」字。按景祐本無「也」字。","sentenceOrder":323},
  {"id":"s_work_han_thu_27_324","chapterId":"ch_work_han_thu_27","textTraditional":"一０九八頁一三行　（則）〔刖〕左右趾合一，　景祐、殿、局本都作「刖」。王先謙說「則」乃「刖」之誤。","sentenceOrder":324},
  {"id":"s_work_han_thu_27_325","chapterId":"ch_work_han_thu_27","textTraditional":"一一００頁　五行　鬼薪白粲滿（三）〔一〕歲為隸臣　王先謙說「三歲」誤，當為「一歲」。","sentenceOrder":325},
  {"id":"s_work_han_thu_27_326","chapterId":"ch_work_han_thu_27","textTraditional":"一一０四頁　九行　言舉毫毛之事，輕小之甚〔者〕。塞猶當（者）也。　王先謙說「者」字當在「甚」字下。","sentenceOrder":326},
  {"id":"s_work_han_thu_27_327","chapterId":"ch_work_han_thu_27","textTraditional":"一一０七頁一六行　遺忘，（勿）〔忽〕忘也。　景祐、殿本作「忽」。王先謙說作「忽」是。","sentenceOrder":327},
  {"id":"s_work_han_thu_27_328","chapterId":"ch_work_han_thu_27","textTraditional":"一一一一頁　二行　且懲其（末）〔未〕也。　錢大昭說荀子作「未」。按殿本作「未」。","sentenceOrder":328},
  {"id":"s_work_han_thu_27_329","chapterId":"ch_work_han_thu_27","textTraditional":"一一一一頁　三行　故象刑非生〔於〕治古，　「於」字據景祐、殿本補。","sentenceOrder":329},
  {"id":"s_work_han_thu_27_330","chapterId":"ch_work_han_thu_27","textTraditional":"一一一一頁　五行　不祥莫大（矣）焉。　錢大昭說「矣」字衍。按殿本無。","sentenceOrder":330},
  {"id":"s_work_han_thu_28_1","chapterId":"ch_work_han_thu_28","textTraditional":"洪範八政，一曰食，二曰貨。食謂農殖嘉穀可食之物，〔一〕貨謂布帛可衣，〔二〕及金刀龜貝，所以分財布利通有無者也。〔三〕二者，生民之本，興自神農之世。「斲木為耜，煣木為耒，耒（〈古“以”字，形似吕〉）〔耨〕之利以教天下」，而食足；〔四〕「日中為市，致天下之民，聚天下之貨，交易而退，各得其所」，而貨通。〔五〕食足貨通，然後國實民富，而教化成。黃帝以下「通其變，使民不倦」。〔六〕堯命四子以「敬授民時」，〔七〕舜命后稷以「黎民祖飢」，〔八〕是為政首。禹平洪水，定九州，〔九〕制土田，各因所生遠近，賦入貢棐，〔一０〕楙遷有無，萬國作乂。〔一一〕殷周之盛，詩書所述，要在安民，富而教之。故易稱「天地之大德曰生，聖人之大寶曰位；何以守位曰仁，何以聚人曰財。」〔一二〕財者，帝王所以聚人守位，養成群生，奉順天德，治國安民之本也。故曰：「不患寡而患不均，不患貧而患不安；蓋均亡貧，和亡寡，安亡傾。」〔一三〕是以聖王域民，〔一四〕築城郭以居之，制廬井以均之，〔一五〕開市肆以通之，〔一六〕設庠序以教之；〔一七〕士農工商，四民有業。學以居位曰士，闢土殖穀曰農，作巧成器曰工，通財鬻貨曰商。〔一八〕聖王量能授事，四民陳力受職，故朝亡廢官，邑亡敖民，地亡曠土。〔一九〕","sentenceOrder":1},
  {"id":"s_work_han_thu_28_2","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「殖，生也。嘉，善也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_28_3","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「衣音於既反。」","sentenceOrder":3},
  {"id":"s_work_han_thu_28_4","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「金謂五色之金也。黃者曰金，白者曰銀，赤者曰銅，青者曰鉛，黑者曰鐵。刀謂錢幣也。龜以卜占，貝以表飾，故皆為寶貨也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_28_5","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　師古曰：「斲，斫也。煣，屈也。耒，手耕曲木也。耜，耒端木所以施金也。耨，耘田也。耜音似。煣音人九反。耒音來內反。耨音乃搆反。」","sentenceOrder":5},
  {"id":"s_work_han_thu_28_6","chapterId":"ch_work_han_thu_28","textTraditional":"〔五〕　師古曰：「自『斲木為耜』以至於此，事見易上繫辭。」","sentenceOrder":6},
  {"id":"s_work_han_thu_28_7","chapterId":"ch_work_han_thu_28","textTraditional":"〔六〕　李奇曰：「器幣有不便於時，則變更通利之，使民樂其業而不倦也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_28_8","chapterId":"ch_work_han_thu_28","textTraditional":"〔七〕　師古曰：「四子謂羲仲、羲叔、和仲、和叔也。事見虞書堯典也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_28_9","chapterId":"ch_work_han_thu_28","textTraditional":"〔八〕　孟康曰：「祖，始也。黎民始飢，命棄為稷官也。古文言阻。」師古曰：「事見〔虞書〕舜典。」","sentenceOrder":9},
  {"id":"s_work_han_thu_28_10","chapterId":"ch_work_han_thu_28","textTraditional":"〔九〕　師古曰：「九州謂冀、兗、青、徐、揚、荊、豫、梁、雍。」","sentenceOrder":10},
  {"id":"s_work_han_thu_28_11","chapterId":"ch_work_han_thu_28","textTraditional":"〔一０〕應劭曰：「棐，竹器也，所以盛。方曰筐，隋曰棐。」師古曰：「棐讀與匪同，禹貢所謂『厥貢漆絲，厥篚織文』之類是也。隋，圜而長也。隋音他果反。」","sentenceOrder":11},
  {"id":"s_work_han_thu_28_12","chapterId":"ch_work_han_thu_28","textTraditional":"〔一一〕師古曰：「楙與茂同，勉也。言勸勉天下，遷易有無，使之交足，則萬國皆治。」","sentenceOrder":12},
  {"id":"s_work_han_thu_28_13","chapterId":"ch_work_han_thu_28","textTraditional":"〔一二〕師古曰：「下繫之辭。」","sentenceOrder":13},
  {"id":"s_work_han_thu_28_14","chapterId":"ch_work_han_thu_28","textTraditional":"〔一三〕　師古曰：「論語載孔子之言。」","sentenceOrder":14},
  {"id":"s_work_han_thu_28_15","chapterId":"ch_work_han_thu_28","textTraditional":"〔一四〕　師古曰：「為邦域。」","sentenceOrder":15},
  {"id":"s_work_han_thu_28_16","chapterId":"ch_work_han_thu_28","textTraditional":"〔一五〕　師古曰：「井田之中為屋廬。」","sentenceOrder":16},
  {"id":"s_work_han_thu_28_17","chapterId":"ch_work_han_thu_28","textTraditional":"〔一六〕　師古曰：「肆，列也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_28_18","chapterId":"ch_work_han_thu_28","textTraditional":"〔一七〕　師古曰：「庠序，禮官養老之處。」","sentenceOrder":18},
  {"id":"s_work_han_thu_28_19","chapterId":"ch_work_han_thu_28","textTraditional":"〔一八〕　師古曰：「鬻，賣也。鬻音弋六反。」","sentenceOrder":19},
  {"id":"s_work_han_thu_28_20","chapterId":"ch_work_han_thu_28","textTraditional":"〔一九〕　師古曰：「敖謂逸游也。曠，空也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_28_21","chapterId":"ch_work_han_thu_28","textTraditional":"理民之道，地著為本。〔一〕故必建步立畝，正其經界。〔二〕六尺為步，步百為畝，畝百為夫，夫三為屋，屋三為井，井方一里，是為九夫。八家共之，各受私田百畝，公田十畝，是為八百八十畝，餘二十畝以為廬舍。〔三〕出入相友，守望相助，疾病（則）〔相〕救，民是以和睦，而教化齊同，力役生產可得而平也。","sentenceOrder":21},
  {"id":"s_work_han_thu_28_22","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「地著，謂安土也，音直略反。」","sentenceOrder":22},
  {"id":"s_work_han_thu_28_23","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「畮，古畝字也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_28_24","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「廬，田中屋也。春夏居之，秋冬則去。」","sentenceOrder":24},
  {"id":"s_work_han_thu_28_25","chapterId":"ch_work_han_thu_28","textTraditional":"民受田，上田夫百畝，中田夫二百畝，下田夫三百畝。歲耕種者為不易上田；休一歲者為一易中田；休二歲者為再易下田，三歲更耕之，自爰其處。〔一〕農民戶人己受田，其家眾男為餘夫，亦以口受田如比。〔二〕士工商家受田，五口乃當農夫一人。此謂平土可以為法者也。若山林藪澤原陵淳鹵之地，〔三〕各以肥磽多少為差。〔四〕有賦有稅。稅謂公田什一及工商衡虞之入也。〔五〕賦共車馬甲兵士徒之役，〔六〕充實府庫賜予之用。稅給郊社宗廟百神之祀，天子奉養百官祿食庶事之費。民年二十受田，六十歸田。七十以上，上所養也；十歲以下，上所長也；十一以上，上所強也。〔七〕種穀必雜五種，以備災害。〔八〕田中不得有樹，用妨五穀。力耕數耘，收穫如寇盜之至。〔九〕還廬樹桑，〔一０〕菜茹有畦，瓜瓠果蓏〔一一〕殖於疆易。〔一二〕雞豚狗彘毋失其時，〔一三〕女修蠶織，則五十可以衣帛，七十可以食肉。","sentenceOrder":25},
  {"id":"s_work_han_thu_28_26","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　孟康曰：「爰，於也。」師古曰：「更，互也，音工衡反。」","sentenceOrder":26},
  {"id":"s_work_han_thu_28_27","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「比，例也，音必寐反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_28_28","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　晉灼曰：「淳，盡也，舄鹵之田不生五穀也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_28_29","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　師古曰：「磽，磽确也，謂瘠薄之田也，音口交反。」","sentenceOrder":29},
  {"id":"s_work_han_thu_28_30","chapterId":"ch_work_han_thu_28","textTraditional":"〔五〕　師古曰：「賦謂計口發財，稅謂收其田入也。什一，謂十取其一也。工、商、衡、虞雖不墾殖，亦取其稅者，工有技巧之作，商有行販之利，衡虞取山澤之材產也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_28_31","chapterId":"ch_work_han_thu_28","textTraditional":"〔六〕　師古曰：「徒，眾也。共讀曰供。」","sentenceOrder":31},
  {"id":"s_work_han_thu_28_32","chapterId":"ch_work_han_thu_28","textTraditional":"〔七〕　師古曰：「勉強勸之，令習事也。強音其兩反。」","sentenceOrder":32},
  {"id":"s_work_han_thu_28_33","chapterId":"ch_work_han_thu_28","textTraditional":"〔八〕　師古曰：「歲月有宜，及水旱之利也。種即五穀，謂黍、稷、麻、麥、豆也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_28_34","chapterId":"ch_work_han_thu_28","textTraditional":"〔九〕　師古曰：「力謂勤作之也。如寇盜之至，謂促遽之甚，恐為風雨所損。」","sentenceOrder":34},
  {"id":"s_work_han_thu_28_35","chapterId":"ch_work_han_thu_28","textTraditional":"〔一０〕師古曰：「還，繞也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_28_36","chapterId":"ch_work_han_thu_28","textTraditional":"〔一一〕應劭曰：「木實曰果，草實曰蓏。」張晏曰：「有核曰果，無核曰蓏。」臣瓚曰：「案木上曰果，地上曰蓏也。」師古曰：「茹，所食之菜也。畦，區也。茹音人豫反。畦音胡圭反。蓏音來果反。」","sentenceOrder":36},
  {"id":"s_work_han_thu_28_37","chapterId":"ch_work_han_thu_28","textTraditional":"〔一二〕張晏曰：「至此易主，故曰易。」師古曰：「詩小雅信南山云『中田有廬，疆埸有瓜』，即謂此也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_28_38","chapterId":"ch_work_han_thu_28","textTraditional":"〔一三〕師古曰：「彘即豕。」","sentenceOrder":38},
  {"id":"s_work_han_thu_28_39","chapterId":"ch_work_han_thu_28","textTraditional":"在野曰廬，在邑曰里。〔一〕五家為鄰，五鄰為里，四里為族，五族為黨，五黨為州，五州為鄉。鄉，萬二千五百戶也。鄰長位下士，自此以上，稍登一級，至鄉而為卿也。於〔是〕里有序而鄉有庠。序以明教，庠則行禮而視化焉。〔二〕春令民畢出在野，冬則畢入於邑。其詩曰：「四之日舉止，同我婦子，饁彼南畮。」〔三〕又曰：「十月蟋蟀，入我床下，嗟我婦子，聿為改歲，入此室處。」〔四〕所以順陰陽，備寇賊，習禮文也。春，（秋）〔將〕出民，里胥平旦坐於右塾，鄰長坐於（右）〔左〕塾，〔五〕畢出然後歸，夕亦如之。〔六〕入者必持薪樵，輕重相分，班白不提挈。〔七〕冬，民既入，婦人同巷，相從夜績，女工一月得四十五日。〔八〕必相從者，所以省費燎火，同巧拙而合習俗也。〔九〕男女有不得其所者，因相與歌詠，各言其傷。〔一０〕","sentenceOrder":39},
  {"id":"s_work_han_thu_28_40","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「廬各在其田中，而里聚居也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_28_41","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「視讀為示也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_28_42","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「此豳詩七月之章也。饁，饋也。四之日，周之四月，夏之二月也。農人無不舉足而耕也，則其婦與子同以食來至南畮治田之處而饋之也。饁音于輒反。」","sentenceOrder":42},
  {"id":"s_work_han_thu_28_43","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　師古曰：「亦七月之章也。蟋蟀，蛬也，今謂之促織。聿，曰也。言寒氣既至，蟋蟀漸來，則婦子皆曰歲將改矣，而去田中入室處也。蛬音拱。」","sentenceOrder":43},
  {"id":"s_work_han_thu_28_44","chapterId":"ch_work_han_thu_28","textTraditional":"〔五〕　孟康曰：「里胥，如今里吏也。」師古曰：「門側之堂曰塾。坐於門側者，督促勸之，知其早晏，防怠惰也。塾音孰。」","sentenceOrder":44},
  {"id":"s_work_han_thu_28_45","chapterId":"ch_work_han_thu_28","textTraditional":"〔六〕　師古曰：「言里胥鄰長亦待入畢，然後歸也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_28_46","chapterId":"ch_work_han_thu_28","textTraditional":"〔七〕　師古曰：「班白者，謂髮雜色也。不提挈者，所以優老人也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_28_47","chapterId":"ch_work_han_thu_28","textTraditional":"〔八〕　服虔曰：「一月之中，又得夜半為十五日，凡四十五日也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_28_48","chapterId":"ch_work_han_thu_28","textTraditional":"〔九〕　師古曰：「省費燎火，省燎火之費也。燎所以為明，火所以為溫也。燎音力召反。」","sentenceOrder":48},
  {"id":"s_work_han_thu_28_49","chapterId":"ch_work_han_thu_28","textTraditional":"〔一０〕師古曰：「怨刺之詩也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_28_50","chapterId":"ch_work_han_thu_28","textTraditional":"是月，餘子亦在于序室。〔一〕八歲入小學，學六甲五方書計之事，〔二〕始知室家長幼之節。十五入大學，學先聖禮樂，而知朝廷君臣之禮。其有秀異者，移鄉學于庠序；庠序之異者，移國學于少學。諸侯歲貢少學之異者於天子，學于大學，命曰造士。〔三〕行同能偶，則別之以射，〔四〕然後爵命焉。","sentenceOrder":50},
  {"id":"s_work_han_thu_28_51","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　蘇林曰：「餘子，庶子也。或曰，未任役為餘子。」師古曰：「未任役者是也。幼童皆當受業，豈論嫡庶乎？」","sentenceOrder":51},
  {"id":"s_work_han_thu_28_52","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　蘇林曰：「五方之異書，如今祕書學外國書也。」臣瓚曰：「辨五方之名及書藝也。」師古曰：「瓚說是也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_28_53","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　李奇曰：「造，成也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_28_54","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　師古曰：「以射試之。」","sentenceOrder":54},
  {"id":"s_work_han_thu_28_55","chapterId":"ch_work_han_thu_28","textTraditional":"孟春之月，群居者將散，〔一〕行人振木鐸徇于路，以采詩〔二〕，獻之大師，比其音律，以聞於天子。〔三〕故曰王者不窺牖戶而知天下。","sentenceOrder":55},
  {"id":"s_work_han_thu_28_56","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「謂各趣農畮也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_28_57","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「行人，遒人也，主號令之官。鐸，大鈴也，以木為舌，謂之木鐸。徇，巡也。采詩，采取怨刺之詩也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_28_58","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「大師，掌音律之官，教六詩以六律為之音者。比謂次之也。比音頻二反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_28_59","chapterId":"ch_work_han_thu_28","textTraditional":"此先王制土處民富而教之之大略也。故孔子曰：「道千乘之國，敬事而信，節用而愛人，使民以時。」〔一〕故民皆勸功樂業，先公而後私。其詩曰：「有渰淒淒，興雲祁祁，雨我公田，遂及我私。」〔二〕民三年耕，則餘一年之畜。〔三〕衣食足而知榮辱，廉讓生而爭訟息，故三載考績。〔四〕孔子曰「苟有用我者，期月而已可也，三年有成」，成此功也。〔五〕三考黜陟，餘三年食，進業曰登〔六〕；再登曰平，餘六年食；三登曰泰平，二十七歲，遺九年食。然後（〈古“以”字，形似吕〉）〔至〕德流洽，禮樂成焉。故曰「如有王者，必世而後仁」，〔七〕繇此道也。」〔八〕","sentenceOrder":59},
  {"id":"s_work_han_thu_28_60","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「論語載孔子之言。道，治也。舉事必敬，施令必信，不為奢侈，愛養其民，無奪農時。」","sentenceOrder":60},
  {"id":"s_work_han_thu_28_61","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「小雅大田之詩也。渰，陰雲也。淒淒，雲起貌也。祁祁，徐也。言陰陽和，風雨時，民庶慶悅，喜其先雨公田，乃及私也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_28_62","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「畜讀曰蓄。其下並同。」","sentenceOrder":62},
  {"id":"s_work_han_thu_28_63","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　師古曰：「績，功也。言主治民者，三年一考其功也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_28_64","chapterId":"ch_work_han_thu_28","textTraditional":"〔五〕　師古曰：「論語載孔子之言也。用謂使為政，期月可以易俗，三年乃得成功也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_28_65","chapterId":"ch_work_han_thu_28","textTraditional":"〔六〕　鄭氏曰：「進上百工之業也。或曰進上農工諸事業，名曰登。」","sentenceOrder":65},
  {"id":"s_work_han_thu_28_66","chapterId":"ch_work_han_thu_28","textTraditional":"〔七〕　師古曰：「亦孔子之言也。解在刑法志。」","sentenceOrder":66},
  {"id":"s_work_han_thu_28_67","chapterId":"ch_work_han_thu_28","textTraditional":"〔八〕　師古曰：「繇讀與由同。由，用也，從也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_28_68","chapterId":"ch_work_han_thu_28","textTraditional":"周室既衰，暴君污吏慢其經界，〔一〕繇役橫作，〔二〕政令不信，上下相詐，公田不治。故魯宣公「初稅畝」，春秋譏焉。〔三〕於是上貪民怨，災害生而禍亂作。","sentenceOrder":68},
  {"id":"s_work_han_thu_28_69","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「污謂貪穢也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_28_70","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「繇讀曰徭。橫音胡孟反。」","sentenceOrder":70},
  {"id":"s_work_han_thu_28_71","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　孟康曰：「春秋謂之履畝，履踐民所種好者而取之，譏其貪也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_28_72","chapterId":"ch_work_han_thu_28","textTraditional":"陵夷至於戰國，貴詐力而賤仁誼，先富有而後禮讓。是時，李悝為魏文侯作盡地力之教，〔一〕以為地方百里，提封九萬頃，除山澤邑居參分去一，為田六百萬畝，治田勤謹則畝益三升，〔二〕不勤則損亦如之。地方百里之增減，輒為粟百八十萬石矣。又曰糴其貴傷民，〔三〕甚賤傷農；民傷則離散，農傷則國貧。故甚貴與甚賤，其傷一也。善為國者，使民毋傷而農益勸。今一夫挾五口，治田百畝，歲收畝一石半，為粟百五十石，除十一之稅十五石，餘百三十五石。食，人月一石半，五人終歲為粟九十石，餘有四十五石。石三十，為錢千三百五十，除社閭嘗新春秋之祠，用錢三百，餘千五十。衣，人率用錢三百，五人終歲用千五百，不足四百五十。〔四〕不幸疾病死喪之費，及上賦斂，又未與此。〔五〕此農夫所以常困，有不勸耕之心，而令糴至於甚貴者也。是故善平糴者，必謹觀歲有上中下孰。上孰其收自四，餘四百石；〔六〕中孰自三，餘三百石；〔七〕下孰自倍，餘百石。〔八〕小飢則收百石，〔九〕中飢七十石，〔一０〕大飢三十石。〔一一〕故大孰則上糴三而舍一，中孰則糴二，下孰則糴一，使民適足，賈平則止。〔一二〕小飢則發小孰之所斂，〔一三〕中飢則發中孰之所斂，大飢則發大孰之所斂，而糶之。故雖遇饑饉水旱，糴不貴而民不散，取有餘以補不足也。行之魏國，國以富彊。","sentenceOrder":72},
  {"id":"s_work_han_thu_28_73","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「李悝，文侯臣也。悝音恢。」","sentenceOrder":73},
  {"id":"s_work_han_thu_28_74","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　服虔曰：「與之三升也。」臣瓚曰：「當言三斗。謂治田勤，則畝加三斗也。」師古曰：「計數而言，字當為斗。瓚說是也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_28_75","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　韋昭曰：「此民謂士工商也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_28_76","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　師古曰：「少四百五十，不足也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_28_77","chapterId":"ch_work_han_thu_28","textTraditional":"〔五〕　師古曰：「與讀曰豫。」","sentenceOrder":77},
  {"id":"s_work_han_thu_28_78","chapterId":"ch_work_han_thu_28","textTraditional":"〔六〕　張晏曰：「平歲百畝收百五十石，今大孰四倍，收六百石，計民食終歲長四百石，官糴三百石，此為糴三舍一也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_28_79","chapterId":"ch_work_han_thu_28","textTraditional":"〔七〕　張晏曰：「自三，四百五十石也。終歲長三百石，官糴二百石，此為糴二而舍一也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_28_80","chapterId":"ch_work_han_thu_28","textTraditional":"〔八〕　張晏曰：「自倍，收三百石，終歲長百石，官糴其五十石，云下孰糴一，謂中分百石之一。」","sentenceOrder":80},
  {"id":"s_work_han_thu_28_81","chapterId":"ch_work_han_thu_28","textTraditional":"〔九〕　張晏曰：「平歲百畮之收，收百五十石，今小飢收百石，收三分之二也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_28_82","chapterId":"ch_work_han_thu_28","textTraditional":"〔一０〕張晏曰：「收二分之一。」","sentenceOrder":82},
  {"id":"s_work_han_thu_28_83","chapterId":"ch_work_han_thu_28","textTraditional":"〔一一〕張晏曰：「收五分之一也。以此準之，大小中飢之率也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_28_84","chapterId":"ch_work_han_thu_28","textTraditional":"〔一二〕師古曰：「賈讀曰價。」","sentenceOrder":84},
  {"id":"s_work_han_thu_28_85","chapterId":"ch_work_han_thu_28","textTraditional":"〔一三〕李奇曰：「官以斂臧出糶也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_28_86","chapterId":"ch_work_han_thu_28","textTraditional":"及秦孝公用商君，壞井田，開仟伯，〔一〕急耕戰之賞，雖非古道，猶以務本之故，傾鄰國而雄諸侯。然王制遂滅，僭差亡度。庶人之富者累鉅萬，〔二〕而貧者食糟糠；有國彊者兼州域，而弱者喪社稷。至於始皇，遂并天下，內興功作，外攘夷狄，收泰半之賦，〔三〕發閭左之戍。〔四〕男子力耕不足糧饟，〔五〕女子紡績不足衣服。竭天下之資財以奉其政，猶未足以澹其欲也。〔六〕海內愁怨，遂用潰畔。〔七〕","sentenceOrder":86},
  {"id":"s_work_han_thu_28_87","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「仟伯，田間之道也。南北曰仟，東西曰伯。伯音莫白反。」","sentenceOrder":87},
  {"id":"s_work_han_thu_28_88","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「鉅，大也。大萬，謂萬萬也。累者兼數，非止一也。言其貲財積累萬萬也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_28_89","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「泰半，三分取其二。」","sentenceOrder":89},
  {"id":"s_work_han_thu_28_90","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　應劭曰：「秦時以適發之，名適戍。先發吏有過及贅婿、賈人，後以嘗有市籍者發，又後以大父母、父母嘗有市籍者。戍者曹輩盡，復入閭，取其左發之，未及取右而秦亡。」師古曰：「閭，里門也。言居在（閭）〔里〕門之左者，一切發之。此閭左之釋，應最得之，諸家之義煩穢舛錯，故無所取也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_28_91","chapterId":"ch_work_han_thu_28","textTraditional":"〔五〕　師古曰：「饟，古餉字也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_28_92","chapterId":"ch_work_han_thu_28","textTraditional":"〔六〕　師古曰：「澹，古贍字也。贍，給也。其下並同。」","sentenceOrder":92},
  {"id":"s_work_han_thu_28_93","chapterId":"ch_work_han_thu_28","textTraditional":"〔七〕　師古曰：「下逃其上曰潰。」","sentenceOrder":93},
  {"id":"s_work_han_thu_28_94","chapterId":"ch_work_han_thu_28","textTraditional":"漢興，接秦之敝，諸侯並起，民失作業，而大饑饉。凡米石五千，人相食，死者過半。高祖乃令民得賣子，就食蜀漢。天下既定，民亡蓋臧，〔一〕自天子不能具醇駟，〔二〕而將相或乘牛車。〔三〕上於是約法省禁，輕田租，什五而稅一，量吏祿，度官用，以賦於民。〔四〕而山川園池市肆租稅之入，自天子以至封君湯沐邑，皆各為私奉養，不領於天子之經費。〔五〕漕轉關東粟以給中都官，歲不過數十萬石。〔六〕孝惠、高后之間，衣食滋殖。文帝即位，躬修儉節，思安百姓。時民近戰國，皆背本趨末，賈誼說上曰：","sentenceOrder":94},
  {"id":"s_work_han_thu_28_95","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　蘇林曰：「無物可蓋臧。」","sentenceOrder":95},
  {"id":"s_work_han_thu_28_96","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「醇，不雜也。無醇色之駟，謂四馬雜色也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_28_97","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「以牛駕車也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_28_98","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　師古曰：「纔取足。」","sentenceOrder":98},
  {"id":"s_work_han_thu_28_99","chapterId":"ch_work_han_thu_28","textTraditional":"〔五〕　師古曰：「言各收其所賦稅以自供，不入國朝之倉廩府庫也。經，常也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_28_100","chapterId":"ch_work_han_thu_28","textTraditional":"〔六〕　師古曰：「中都官，京師諸官府也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_28_101","chapterId":"ch_work_han_thu_28","textTraditional":"筦子曰「倉廩實而知禮節」。〔一〕民不足而可治者，自古及今，未之嘗聞。古之人曰：「一夫不耕，或受之飢；一女不織，或受之寒。」生之有時，而用之亡度，則物力必屈。〔二〕古之治天下，至孅至悉也，〔三〕故其畜積足恃。今背本而趨末，食者甚眾，是天下之大殘也；〔四〕淫侈之俗，日日以長，是天下之大賊也。殘賊公行，莫之或止；大命將泛，〔五〕莫之振救。〔六〕生之者甚少而靡之者甚多，〔七〕天下財產何得不蹶！〔八〕漢之為漢幾四十年矣，〔九〕公私之積猶可哀痛。〔一０〕失時不雨，民且狼顧；〔一一〕歲惡不入，請賣爵、子。〔一二〕既聞耳矣，〔一三〕安有為天下阽危者若是而上不驚者！〔一四〕","sentenceOrder":101},
  {"id":"s_work_han_thu_28_102","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「筦與管同。管子，管仲之書也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_28_103","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「屈，盡也。音其勿反。」","sentenceOrder":103},
  {"id":"s_work_han_thu_28_104","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「孅，細也。悉，盡其事也。孅與纖同。」","sentenceOrder":104},
  {"id":"s_work_han_thu_28_105","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　師古曰：「本，農業也。末，工商也。言人已棄農而務工商矣，其食米粟者又甚眾。殘謂傷害也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_28_106","chapterId":"ch_work_han_thu_28","textTraditional":"〔五〕　孟康曰：「泛音方勇反。泛，覆也。」師古曰：「字本作覂，此通用也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_28_107","chapterId":"ch_work_han_thu_28","textTraditional":"〔六〕　師古曰：「振，舉也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_28_108","chapterId":"ch_work_han_thu_28","textTraditional":"〔七〕　師古曰：「靡，散也，音縻。」","sentenceOrder":108},
  {"id":"s_work_han_thu_28_109","chapterId":"ch_work_han_thu_28","textTraditional":"〔八〕　應劭曰：「蹶，傾竭也。」師古曰：「蹶音厥。」","sentenceOrder":109},
  {"id":"s_work_han_thu_28_110","chapterId":"ch_work_han_thu_28","textTraditional":"〔九〕　師古曰：「幾，近也。音鉅衣反。」","sentenceOrder":110},
  {"id":"s_work_han_thu_28_111","chapterId":"ch_work_han_thu_28","textTraditional":"〔一０〕師古曰：「言年載已多，而無儲積。」","sentenceOrder":111},
  {"id":"s_work_han_thu_28_112","chapterId":"ch_work_han_thu_28","textTraditional":"〔一一〕鄭氏曰：「民欲有畔意，若狼之顧望也。」李奇曰：「狼性怯，走憙還顧。言民見天不雨，今亦恐也。」師古曰：「李說是也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_28_113","chapterId":"ch_work_han_thu_28","textTraditional":"〔一二〕如淳曰：「賣爵級又賣子也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_28_114","chapterId":"ch_work_han_thu_28","textTraditional":"〔一三〕如淳曰：「聞於天子之耳。」","sentenceOrder":114},
  {"id":"s_work_han_thu_28_115","chapterId":"ch_work_han_thu_28","textTraditional":"〔一四〕師古曰：「阽危，欲墜之意也。音閻，又音丁念反。」","sentenceOrder":115},
  {"id":"s_work_han_thu_28_116","chapterId":"ch_work_han_thu_28","textTraditional":"世之有飢穰，天之行也，〔一〕禹、湯被之矣。〔二〕即不幸有方二三千里之旱，國胡以相恤？〔三〕卒然邊境有急，數十百萬之眾，國胡以餽之？〔四〕兵旱相乘，天下大屈，〔五〕有勇力者聚徒而衡擊，〔六〕罷夫羸老易子而鞮其骨。〔七〕政治未畢通也，遠方之能疑者並舉而爭起矣，〔八〕乃駭而圖之，豈將有及乎？〔九〕","sentenceOrder":116},
  {"id":"s_work_han_thu_28_117","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　李奇曰：「天之行氣，不能常孰也。或曰，行，道也。」師古曰：「穰，豐也，音人常反。」","sentenceOrder":117},
  {"id":"s_work_han_thu_28_118","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「謂禹遭水，而湯遭旱也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_28_119","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「胡，何也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_28_120","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　師古曰：「卒讀曰猝。餽亦饋字也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_28_121","chapterId":"ch_work_han_thu_28","textTraditional":"〔五〕　師古曰：「屈音其勿反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_28_122","chapterId":"ch_work_han_thu_28","textTraditional":"〔六〕　師古曰：「衡，橫也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_28_123","chapterId":"ch_work_han_thu_28","textTraditional":"〔七〕　師古曰：「罷讀曰疲。鞮，齧也，音五巧反。」","sentenceOrder":123},
  {"id":"s_work_han_thu_28_124","chapterId":"ch_work_han_thu_28","textTraditional":"〔八〕　師古曰：「疑讀曰擬。擬，僭也，謂與天子相比擬。」","sentenceOrder":124},
  {"id":"s_work_han_thu_28_125","chapterId":"ch_work_han_thu_28","textTraditional":"〔九〕　師古曰：「圖謂謀也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_28_126","chapterId":"ch_work_han_thu_28","textTraditional":"夫積貯者，天下之大命也。苟粟多而財有餘，何為而不成？以攻則取，以守則固，以戰則勝。懷敵附遠，何招而不至？〔一〕今毆民而歸之農，皆著於本，〔二〕使天下各食其力，末技游食之民轉而緣南畝，〔三〕則畜積足而人樂其所矣。可以為富安天下，而直為此廩廩也，〔四〕竊為陛下惜之！","sentenceOrder":126},
  {"id":"s_work_han_thu_28_127","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「懷，來也，安也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_28_128","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「毆亦驅字。著音直略反。」","sentenceOrder":128},
  {"id":"s_work_han_thu_28_129","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「言皆趨農作也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_28_130","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　李奇曰：「廩廩，危也。」師古曰：「言務耕農，厚畜積，則天下富安，何乃不為，而常不足廩廩若此。」","sentenceOrder":130},
  {"id":"s_work_han_thu_28_131","chapterId":"ch_work_han_thu_28","textTraditional":"於是上感誼言，始開籍田，躬耕以勸百姓。晁錯復說上曰：","sentenceOrder":131},
  {"id":"s_work_han_thu_28_132","chapterId":"ch_work_han_thu_28","textTraditional":"聖王在上而民不凍飢者，非能耕而食之，織而衣之也，〔一〕為開其資財之道也。故堯、禹有九年之水，湯有七年之旱，而國亡捐瘠者，〔二〕以畜積多而備先具也。今海內為一，土地人民之眾不避湯、禹，加以亡天災數年之水旱，而畜積未及者，何也？地有遺利，民有餘力，生穀之土未盡墾，山澤之利未盡出也，游食之民未盡歸農也。民貧，則姦邪生。貧生於不足，不足生於不農，不農則不地著，不地著則離鄉輕家，民如鳥獸，雖有高城深池，嚴法重刑，猶不能禁也。","sentenceOrder":132},
  {"id":"s_work_han_thu_28_133","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「食讀曰飤。衣音於既反。」","sentenceOrder":133},
  {"id":"s_work_han_thu_28_134","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　孟康曰：「肉腐為瘠。捐，骨不埋者。或曰，捐謂民有飢相棄捐者。或謂貧乞者為捐。」蘇林曰：「瘠音漬。」師古曰：「瘠，瘦病也。言無相棄捐而瘦病者耳。不當音漬也。貧乞之釋，尤疏僻焉。」","sentenceOrder":134},
  {"id":"s_work_han_thu_28_135","chapterId":"ch_work_han_thu_28","textTraditional":"夫寒之於衣，不待輕煖；〔一〕飢之於食，不待甘旨；〔二〕飢寒至身，不顧廉恥。人情，一日不再食則飢，終歲不製衣則寒。夫腹飢不得食，膚寒不得衣，雖慈母不能保其子，君安能以有其民哉！明主知其然也，故務民於農桑，薄賦斂，廣畜積，以實倉廩，備水旱，故民可得而有也。","sentenceOrder":135},
  {"id":"s_work_han_thu_28_136","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「以禦風霜，不求靡麗也。煖音乃短反。」","sentenceOrder":136},
  {"id":"s_work_han_thu_28_137","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「旨，美也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_28_138","chapterId":"ch_work_han_thu_28","textTraditional":"民者，在上所以牧之，趨利如水走下，四方亡擇也。〔一〕夫珠玉金銀，飢不可食，寒不可衣，然而眾貴之者，以上用之故也。其為物輕微易臧，在於把握，可以周海內而亡飢寒之患。〔二〕此令臣輕背其主，而民易去其鄉，盜賊有所勸，亡逃者得輕資也。粟米布帛生於地，長於時，聚於力，非可一日成也；數石之重，中人弗勝，〔三〕不為姦邪所利，一日弗得而飢寒至。是故明君貴五穀而賤金玉。","sentenceOrder":138},
  {"id":"s_work_han_thu_28_139","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「走音奏。」","sentenceOrder":139},
  {"id":"s_work_han_thu_28_140","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「周謂周遍而游行。」","sentenceOrder":140},
  {"id":"s_work_han_thu_28_141","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「中人者，處強弱之中也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_28_142","chapterId":"ch_work_han_thu_28","textTraditional":"今農夫五口之家，其服役者不下二人，〔一〕其能耕者不過百畝，百畝之收不過百石。春耕夏耘，秋穫冬臧，伐薪樵，治官府，給繇役；春不得避風塵，夏不得避暑熱，秋不得避陰雨，冬不得避寒凍，四時之間亡日休息；又私自送往迎來，弔死問疾，養孤長幼在其中。勤苦如此，尚復被水旱之災，急政暴（虐）〔賦〕，賦斂不時，朝令而暮改。當具有者半賈而賣，〔二〕亡者取倍稱之息，〔三〕於是有賣田宅鬻子孫以償責者矣。而商賈大者積貯倍息，小者坐列販賣，〔四〕操其奇贏，日游都市，〔五〕乘上之急，所賣必倍。〔六〕故其男不耕耘，女不蠶織，衣必文采，食必（梁）〔粱〕肉；〔七〕亡農夫之苦，有仟伯之得。〔八〕因其富厚，交通王侯，力過吏勢，以利相傾；千里游敖，冠蓋相望，乘堅策肥，履絲曳縞。〔九〕此商人所以兼并農人，農人所以流亡者也。","sentenceOrder":142},
  {"id":"s_work_han_thu_28_143","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「服，事也，給公事之役也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_28_144","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「本直千錢者，止得五百也。賈讀曰價。」","sentenceOrder":144},
  {"id":"s_work_han_thu_28_145","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　如淳曰：「取一償二為倍稱。」師古曰：「稱，舉也，今俗所謂舉錢者也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_28_146","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　師古曰：「行賣曰商，坐販曰賈。列者，若今市中賣物行也。賈音古。」","sentenceOrder":146},
  {"id":"s_work_han_thu_28_147","chapterId":"ch_work_han_thu_28","textTraditional":"〔五〕　師古曰：「奇贏，謂有餘財而畜聚奇異之物也。一說，（字）〔奇〕謂殘餘物也，音居宜反。」","sentenceOrder":147},
  {"id":"s_work_han_thu_28_148","chapterId":"ch_work_han_thu_28","textTraditional":"〔六〕　師古曰：「上所急求，則其價倍貴。」","sentenceOrder":148},
  {"id":"s_work_han_thu_28_149","chapterId":"ch_work_han_thu_28","textTraditional":"〔七〕　師古曰：「（梁）〔粱〕，好粟也，即今之（梁）〔粱〕米。」","sentenceOrder":149},
  {"id":"s_work_han_thu_28_150","chapterId":"ch_work_han_thu_28","textTraditional":"〔八〕　師古曰：「仟謂千錢，伯謂百錢也。伯音莫白反。今俗猶謂百錢為一伯。」","sentenceOrder":150},
  {"id":"s_work_han_thu_28_151","chapterId":"ch_work_han_thu_28","textTraditional":"〔九〕　師古曰：「堅謂好車也。縞，皓素也，繒之精白者也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_28_152","chapterId":"ch_work_han_thu_28","textTraditional":"今法律賤商人，商人已富貴矣；尊農夫，農夫已貧賤矣。故俗之所貴，主之所賤也；吏之所卑，法之所尊也。上下相反，好惡乖迕，〔一〕而欲國富法立，不可得也。方今之務，莫若使民務農而已矣。欲民務農，在於貴粟；貴粟之道，在於使民以粟為賞罰。今募天下入粟縣官，得以拜爵，得以除罪。如此，富人有爵，農民有錢，粟有所渫。〔二〕夫能入粟以受爵，皆有餘者也；取於有餘，以供上用，則貧民之賦可損，〔三〕所謂損有餘補不足，令出而民利者也。順於民心，所補者三：一曰主用足，二曰民賦少，三曰勸農功。今令民有車騎馬一匹者，復卒三人。〔四〕車騎者，天下武備也，故為復卒。〔五〕神農之教曰：「有石城十仞，〔六〕湯池百步，〔七〕帶甲百萬，而亡粟，弗能守也。」以是觀之，粟者，王者大用，政之本務。令民入粟受爵至五大夫以上，乃復一人耳，〔八〕此其與騎馬之功相去遠矣。爵者，上之所擅，出於口而亡窮；〔九〕粟者，民之所種，生於地而不乏。夫得高爵與免罪，人之所甚欲也。使天下〔人〕入粟於邊，以受爵免罪，不過三歲，塞下之粟必多矣。","sentenceOrder":152},
  {"id":"s_work_han_thu_28_153","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「迕，違也。好音呼到反。惡音烏故反。迕音五故反。」","sentenceOrder":153},
  {"id":"s_work_han_thu_28_154","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「渫，散也，音先列反。此下亦同也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_28_155","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「損，減也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_28_156","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　如淳曰：「復三卒之算錢也。或曰，除三夫不作甲卒也。」師古曰：「當為卒者，免其三人；不為卒者，復其錢耳。復音方目反。」","sentenceOrder":156},
  {"id":"s_work_han_thu_28_157","chapterId":"ch_work_han_thu_28","textTraditional":"〔五〕　師古曰：「為音于偽反。」","sentenceOrder":157},
  {"id":"s_work_han_thu_28_158","chapterId":"ch_work_han_thu_28","textTraditional":"〔六〕　應劭曰：「仞，五尺六寸也。」師古曰：「此說非也。八尺曰仞，取人申臂之一尋也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_28_159","chapterId":"ch_work_han_thu_28","textTraditional":"〔七〕　師古曰：「池，城邊池也。以沸湯為池，不可輒近，喻嚴固之（基）〔甚〕。」","sentenceOrder":159},
  {"id":"s_work_han_thu_28_160","chapterId":"ch_work_han_thu_28","textTraditional":"〔八〕　師古曰：「五大夫，第九等爵也。復音方目反。」","sentenceOrder":160},
  {"id":"s_work_han_thu_28_161","chapterId":"ch_work_han_thu_28","textTraditional":"〔九〕　師古曰：「擅，專也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_28_162","chapterId":"ch_work_han_thu_28","textTraditional":"於是文帝從錯之言，令民入粟邊，六百石爵上造，〔一〕稍增至四千石為五大夫，〔二〕萬二千石為大庶長，〔三〕各以多少級數為差。錯復奏言：「陛下幸使天下入粟塞下以拜爵，甚大惠也。竊恐塞卒之食不足用大渫天下粟。邊食足以支五歲，可令入粟郡縣矣；〔四〕足支一歲以上，可時赦，勿收農民租。如此，德澤加於萬民，民俞勤農。〔五〕時有軍役，若遭水旱，民不困乏，天下安寧；歲孰且美，則民大富樂矣。」上復從其言，乃下詔賜民十二年租稅之半。明年，遂除民田之租稅。","sentenceOrder":162},
  {"id":"s_work_han_thu_28_163","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「上造，第二等爵也。」","sentenceOrder":163},
  {"id":"s_work_han_thu_28_164","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「五大夫，第九等爵。」","sentenceOrder":164},
  {"id":"s_work_han_thu_28_165","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「大庶長，第十八等爵也。」","sentenceOrder":165},
  {"id":"s_work_han_thu_28_166","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　師古曰：「入諸郡縣，以備凶災也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_28_167","chapterId":"ch_work_han_thu_28","textTraditional":"〔五〕　師古曰：「俞，進也，音踰，又音愈。」","sentenceOrder":167},
  {"id":"s_work_han_thu_28_168","chapterId":"ch_work_han_thu_28","textTraditional":"後十三歲，孝景二年，令民半出田租，三十而稅一也。其後，上郡以西旱，復修賣爵令，而裁其賈以招民；〔一〕及徒復作，得輸粟於縣官以除罪。〔二〕始造苑馬以廣用，〔三〕宮室列館車馬益增修矣。然婁敕有司以農為務，〔四〕民遂樂業。至武帝之初七十年間，國家亡事，非遇水旱，則民人給家足，都鄙廩庾盡滿，而府庫餘財。京師之錢累百鉅萬，貫朽而不可校。〔五〕太倉之粟陳陳相因，〔六〕充溢露積於外，腐敗不可食。眾庶街巷有馬，仟伯之間成群，〔七〕乘牸牝者擯而不得會聚。〔八〕守閭閻者食粱肉；為吏者長子孫；〔九〕居官者以為姓號。〔一０〕人人自愛而重犯法，〔一一〕先行誼而黜媿辱焉。〔一二〕於是罔疏而民富，役財驕溢，或至并兼豪黨之徒以武斷於鄉曲。〔一三〕宗室有土，公卿大夫以下爭於奢侈〔一四〕，室廬車服僭上亡限。物盛而衰，固其變也。","sentenceOrder":168},
  {"id":"s_work_han_thu_28_169","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「賈讀曰價。裁謂減省之也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_28_170","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「復音房目反。解在宣紀。」","sentenceOrder":170},
  {"id":"s_work_han_thu_28_171","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「苑馬，謂為苑以牧馬。」","sentenceOrder":171},
  {"id":"s_work_han_thu_28_172","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　師古曰：「婁，古屢字。」","sentenceOrder":172},
  {"id":"s_work_han_thu_28_173","chapterId":"ch_work_han_thu_28","textTraditional":"〔五〕　師古曰：「累百鉅萬，謂數百萬萬也。校謂計數也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_28_174","chapterId":"ch_work_han_thu_28","textTraditional":"〔六〕　師古曰：「陳謂久舊也。」","sentenceOrder":174},
  {"id":"s_work_han_thu_28_175","chapterId":"ch_work_han_thu_28","textTraditional":"〔七〕　師古曰：「謂田中之阡陌也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_28_176","chapterId":"ch_work_han_thu_28","textTraditional":"〔八〕　孟康曰：「皆乘父馬，有牝馬間其間則踶齧，故斥出不得會同。」師古曰：「言時富饒，故恥乘牸牝，不必以其踶齧也。踶，蹋也，音大奚反。」","sentenceOrder":176},
  {"id":"s_work_han_thu_28_177","chapterId":"ch_work_han_thu_28","textTraditional":"〔九〕　如淳曰：「時無事，吏不數轉，至於（長生）〔生長〕子孫而不轉職也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_28_178","chapterId":"ch_work_han_thu_28","textTraditional":"〔一０〕如淳曰：「貨殖傳倉氏、庾氏是也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_28_179","chapterId":"ch_work_han_thu_28","textTraditional":"〔一一〕師古曰：「重，難也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_28_180","chapterId":"ch_work_han_thu_28","textTraditional":"〔一二〕師古曰：「以行誼為先，以媿辱相黜也。行音下更反。」","sentenceOrder":180},
  {"id":"s_work_han_thu_28_181","chapterId":"ch_work_han_thu_28","textTraditional":"〔一三〕師古曰：「恃其饒富，則擅行威罰也。斷音丁喚反。」","sentenceOrder":181},
  {"id":"s_work_han_thu_28_182","chapterId":"ch_work_han_thu_28","textTraditional":"〔一四〕師古曰：「有土，謂國之宗姓受封邑土地者也。」","sentenceOrder":182},
  {"id":"s_work_han_thu_28_183","chapterId":"ch_work_han_thu_28","textTraditional":"是後，外事四夷，內興功利，役費並興，而民去本。董仲舒說上曰：「春秋它穀不書，至於麥禾不成則書之，以此見聖人於五穀最重麥與禾也。今關中俗不好種麥，是歲失春秋之所重，而損生民之具也。願陛下幸詔大司農，使關中民益種宿麥，令毋後時。」〔一〕又言：「古者稅民不過什一，其求易共；〔二〕使民不過三日，其力易足。民財內足以養老盡孝，外足以事上共稅，下足以畜妻子極愛，故民說從上。〔三〕至秦則不然，用商鞅之法，改帝王之制，除井田，民得賣買，富者田連仟伯，貧者亡立錐之地。又顓川澤之利，管山林之饒，〔四〕荒淫越制，踰侈以相高；邑有人君之尊，里有公侯之富，小民安得不困？又加月為更卒，已復為正，一歲屯戍，一歲力役，三十倍於古；〔五〕田租口賦，鹽鐵之利，二十倍於古。〔六〕或耕豪民之田，見稅什五。〔七〕故貧民常衣牛馬之衣，而食犬彘之食。重以貪暴之吏，刑戮妄加，〔八〕民愁亡聊，亡逃山林，轉為盜賊，赭衣半道，斷獄歲以千萬數。漢興，循而未改。古井田法雖難卒行，宜少近古，〔九〕限民名田，以澹不足，〔一０〕塞并兼之路。鹽鐵皆歸於民。去奴婢，除專殺之威。〔一一〕薄賦斂，省繇役，以寬民力。然後可善治也。」仲舒死後，功費愈甚，天下虛耗，人復相食〔一二〕。","sentenceOrder":183},
  {"id":"s_work_han_thu_28_184","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「宿麥，謂其苗經冬。」","sentenceOrder":184},
  {"id":"s_work_han_thu_28_185","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「共讀曰供。次下亦同。」","sentenceOrder":185},
  {"id":"s_work_han_thu_28_186","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「說讀曰悅也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_28_187","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　師古曰：「顓與專同。管，主也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_28_188","chapterId":"ch_work_han_thu_28","textTraditional":"〔五〕　師古曰：「更卒，謂給郡縣一月而更者也。正卒，謂給中都官者也。率計今人一歲之中，屯戍及力役之事三十倍多於古也。更音工衡反。」","sentenceOrder":188},
  {"id":"s_work_han_thu_28_189","chapterId":"ch_work_han_thu_28","textTraditional":"〔六〕　如淳曰：「秦賣鹽鐵貴，故下民受其困也。」師古曰：「既收田租，又出口賦，而官更奪鹽鐵之利。率計今人一歲之中，失其資產，二十倍多於古也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_28_190","chapterId":"ch_work_han_thu_28","textTraditional":"〔七〕　如淳曰：「十稅其五。」師古曰：「言下戶貧人，自無田而耕墾豪富家田，十分之中，以五輸本田主也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_28_191","chapterId":"ch_work_han_thu_28","textTraditional":"〔八〕　師古曰：「重音直用反。」","sentenceOrder":191},
  {"id":"s_work_han_thu_28_192","chapterId":"ch_work_han_thu_28","textTraditional":"〔九〕　師古曰：「卒讀曰猝。近音其靳反。」","sentenceOrder":192},
  {"id":"s_work_han_thu_28_193","chapterId":"ch_work_han_thu_28","textTraditional":"〔一０〕師古曰：「名田，占田也。各為立限，不使富者過制，則貧弱之家可足也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_28_194","chapterId":"ch_work_han_thu_28","textTraditional":"〔一一〕服虔曰：「不得專殺奴婢也。」","sentenceOrder":194},
  {"id":"s_work_han_thu_28_195","chapterId":"ch_work_han_thu_28","textTraditional":"〔一二〕師古曰：「耗音呼到反。」","sentenceOrder":195},
  {"id":"s_work_han_thu_28_196","chapterId":"ch_work_han_thu_28","textTraditional":"武帝末年，悔征伐之事，乃封丞相為富民侯。〔一〕下詔曰：「方今之務，在於力農。」以趙過為搜粟都尉。過能為代田，一畝三甽。〔二〕歲代處，故曰代田，〔三〕古法也。后稷始甽田，以二耜為耦，〔四〕廣尺深尺曰甽，長終畝。一畝三甽，一夫三百甽，而播種於甽中。〔五〕苗生葉以上，稍耨隴草，〔六〕因隤其土以附（根苗）〔苗根〕。〔七〕故其詩曰：「或芸或芓，黍稷儗儗。」〔八〕芸，除草也。（耔）〔芓〕，附根也。言苗稍壯，每耨輒附根，比盛暑，隴盡而根深，〔九〕能風與旱，〔一０〕故儗儗而盛也。其耕耘下種田器，皆有便巧。率十二夫為田一井一屋，故畮五頃，〔一一〕用耦犁，二牛三人，一歲之收常過縵田畮一斛以上，〔一二〕善者倍之。〔一三〕過使教田太常、三輔，〔一四〕大農置工巧奴與從事，為作田器。二千石遣令長、三老、力田及里父老善田者受田器，學耕種養苗狀。〔一五〕民或苦少牛，亡以趨澤，〔一六〕故平都令光教過以人輓犁。〔一七〕過奏光以為丞，教民相與庸輓犁。〔一八〕率多人者田日三十畝，少者十三畝，以故田多墾闢。過試以離宮卒田其宮壖地，〔一九〕課得穀皆多其旁田畝一斛以上。令命家田三輔公田，〔二０〕又教邊郡及居延城。〔二一〕是後邊城、河東、弘農、三輔、太常民皆便代田，用力少而得穀多。","sentenceOrder":196},
  {"id":"s_work_han_thu_28_197","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　韋昭曰：「沛蘄縣也。」師古曰：「欲百姓之殷實，故取其嘉名也。」","sentenceOrder":197},
  {"id":"s_work_han_thu_28_198","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「甽，壟也，音工犬反，字或作畎。」","sentenceOrder":198},
  {"id":"s_work_han_thu_28_199","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「代，易也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_28_200","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　師古曰：「併兩耜而耕。」","sentenceOrder":200},
  {"id":"s_work_han_thu_28_201","chapterId":"ch_work_han_thu_28","textTraditional":"〔五〕　師古曰：「播，布也。種謂穀子也。」","sentenceOrder":201},
  {"id":"s_work_han_thu_28_202","chapterId":"ch_work_han_thu_28","textTraditional":"〔六〕　師古曰：「耨，鉏也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_28_203","chapterId":"ch_work_han_thu_28","textTraditional":"〔七〕　師古曰：「隤謂下之也，音頹。」","sentenceOrder":203},
  {"id":"s_work_han_thu_28_204","chapterId":"ch_work_han_thu_28","textTraditional":"〔八〕　師古曰：「小雅甫田之詩。儗儗，盛貌。芸音云。芓音子。儗音擬。」","sentenceOrder":204},
  {"id":"s_work_han_thu_28_205","chapterId":"ch_work_han_thu_28","textTraditional":"〔九〕　師古曰：「比音必寐反。」","sentenceOrder":205},
  {"id":"s_work_han_thu_28_206","chapterId":"ch_work_han_thu_28","textTraditional":"〔一０〕師古曰：「能讀曰耐也。」","sentenceOrder":206},
  {"id":"s_work_han_thu_28_207","chapterId":"ch_work_han_thu_28","textTraditional":"〔一一〕鄧展曰：「九夫為井，三夫為屋。夫百畝，於古為十二頃。古百步為畝，漢時二百四十步為畝，古千二百畝，則得今五頃。」","sentenceOrder":207},
  {"id":"s_work_han_thu_28_208","chapterId":"ch_work_han_thu_28","textTraditional":"〔一二〕師古曰：「縵田，謂不為（畝）〔甽〕者也。縵音莫幹反。」","sentenceOrder":208},
  {"id":"s_work_han_thu_28_209","chapterId":"ch_work_han_thu_28","textTraditional":"〔一三〕師古曰：「善為甽者，又過縵田二斛以上也。」","sentenceOrder":209},
  {"id":"s_work_han_thu_28_210","chapterId":"ch_work_han_thu_28","textTraditional":"〔一四〕蘇林曰：「太常主諸陵，有民，故亦課田種也。」","sentenceOrder":210},
  {"id":"s_work_han_thu_28_211","chapterId":"ch_work_han_thu_28","textTraditional":"〔一五〕蘇林曰：「為法意狀也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_28_212","chapterId":"ch_work_han_thu_28","textTraditional":"〔一六〕師古曰：「趨讀曰趣。趣，及也。澤，雨之潤澤也。」","sentenceOrder":212},
  {"id":"s_work_han_thu_28_213","chapterId":"ch_work_han_thu_28","textTraditional":"〔一七〕師古曰：「輓，引也，音晚。」","sentenceOrder":213},
  {"id":"s_work_han_thu_28_214","chapterId":"ch_work_han_thu_28","textTraditional":"〔一八〕師古曰：「庸，功也，言（挽）〔換〕功共作也。義亦與庸賃同。」","sentenceOrder":214},
  {"id":"s_work_han_thu_28_215","chapterId":"ch_work_han_thu_28","textTraditional":"〔一九〕師古曰：「離宮，別處之宮，非天子所常居也。壖，餘也。宮壖地，謂外垣之內，內垣之外也。諸緣河壖地，廟垣壖地，其義皆同。守離宮卒，閑而無事，因令於壖地為田也。壖音而緣反。」","sentenceOrder":215},
  {"id":"s_work_han_thu_28_216","chapterId":"ch_work_han_thu_28","textTraditional":"〔二０〕李奇曰：「令，使也。命者，教也。令離宮卒教其家田公田也。」韋昭曰：「命謂爵命者。命家，謂受爵命一爵為公士以上，令得田公田，優之也。」師古曰：「令音力成反。」","sentenceOrder":216},
  {"id":"s_work_han_thu_28_217","chapterId":"ch_work_han_thu_28","textTraditional":"〔二一〕韋昭曰：「居延，張掖縣也。時有甲卒也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_28_218","chapterId":"ch_work_han_thu_28","textTraditional":"至昭帝時，流民稍還，田野益闢，頗有畜積。宣帝即位，用吏多選賢良，百姓安土，歲數豐穰，〔一〕穀至石五錢，農人少利。時大司農中丞耿壽昌以善為算能商功利〔二〕得幸於上，五鳳中奏言：「故事，歲漕關東穀四百萬斛以給京師，〔三〕用卒六萬人。宜糴三輔、弘農、河東、上黨、太原郡穀足供京師，可以省關東漕卒過半。」又白增海租三倍，天子皆從其計。御史大夫蕭望之奏言：「故御史屬徐宮〔四〕家在東萊，言往年加海租，魚不出。長老皆言武帝時縣官嘗自漁，海魚不出，後復予民，魚乃出。夫陰陽之感，物類相應，萬事盡然。今壽昌欲近糴漕關內之穀，築倉治船，費直二萬萬餘，〔五〕有動眾之功，恐生旱氣，民被其災。壽昌習於商功分銖之事，其深計遠慮，誠未足任，宜且如故。」上不聽。漕事果便，壽昌遂白令邊郡皆築倉，以穀賤時增其賈而糴，以利農，穀貴時減賈而糶，名曰常平倉。〔六〕民便之。上乃下詔，賜壽昌爵關內侯。而蔡癸以好農使勸郡國，至大官。〔七〕","sentenceOrder":218},
  {"id":"s_work_han_thu_28_219","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「數音所角反。穰音人常反。」","sentenceOrder":219},
  {"id":"s_work_han_thu_28_220","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「商，度也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_28_221","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「漕，水運。」","sentenceOrder":221},
  {"id":"s_work_han_thu_28_222","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　李奇曰：「御史大夫屬。」","sentenceOrder":222},
  {"id":"s_work_han_thu_28_223","chapterId":"ch_work_han_thu_28","textTraditional":"〔五〕　服虔曰：「萬萬，億也。」","sentenceOrder":223},
  {"id":"s_work_han_thu_28_224","chapterId":"ch_work_han_thu_28","textTraditional":"〔六〕　師古曰：「賈並讀曰價。」","sentenceOrder":224},
  {"id":"s_work_han_thu_28_225","chapterId":"ch_work_han_thu_28","textTraditional":"〔七〕　師古曰：「為使而勸郡國也。使音山（史）〔吏〕反。」","sentenceOrder":225},
  {"id":"s_work_han_thu_28_226","chapterId":"ch_work_han_thu_28","textTraditional":"元帝即位，天下大水，關東郡十一尤甚。二年，齊地飢，穀石三百餘，民多餓死，琅邪郡人相食。在位諸儒多言鹽鐵官及北假田官、常平倉可罷，〔一〕毋與民爭利。上從其議，皆罷之。又罷建章、甘泉宮衛，角抵，齊三服官，省禁苑以予貧民，減諸侯王廟衛卒半。又減關中卒五百人，轉穀振貸窮乏。其後用度不足，獨復鹽鐵官。","sentenceOrder":226},
  {"id":"s_work_han_thu_28_227","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　孟康曰：「北假，地名也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_28_228","chapterId":"ch_work_han_thu_28","textTraditional":"成帝時，天下亡兵革之事，號為安樂，然俗奢侈，不以畜聚為意。永始二年，梁國、平原郡比年傷水災，〔一〕人相食，刺史守相坐免。","sentenceOrder":228},
  {"id":"s_work_han_thu_28_229","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「比，頻也。」","sentenceOrder":229},
  {"id":"s_work_han_thu_28_230","chapterId":"ch_work_han_thu_28","textTraditional":"哀帝即位，師丹輔政，建言：「古之聖王莫不設井田，然後治乃可平。〔一〕孝文皇帝承亡周亂秦兵革之後，天下空虛，故務勸農桑，帥以節儉。民始充實，未有并兼之害，故不為民田及奴婢為限〔二〕。今累世承平，豪富吏民訾數鉅萬，而貧弱俞困。蓋君子為政，貴因循而重改作，〔三〕然所以有改者，將以救急也。亦未可詳，宜略為限。」〔四〕天子下其議。丞相孔光、大司空何武奏請：「諸侯王、列侯皆得名田國中。列侯在長安，公主名田縣道，及關內侯、吏民名田皆毋過三十頃。諸侯王奴婢二百人，列侯、公主百人，關內侯、吏民三十人。期盡三年，犯者沒入官。」時田宅奴婢賈為減賤，丁、傅用事，董賢隆貴，皆不便也。〔五〕詔書且須後，〔六〕遂寢不行。宮室苑囿府庫之臧已侈，百姓訾富雖不及文景，然天下戶口最盛矣。","sentenceOrder":230},
  {"id":"s_work_han_thu_28_231","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「建，立也，立其議也。」","sentenceOrder":231},
  {"id":"s_work_han_thu_28_232","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「不為作限制。上為音于偽反。」","sentenceOrder":232},
  {"id":"s_work_han_thu_28_233","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「重，難也。」","sentenceOrder":233},
  {"id":"s_work_han_thu_28_234","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　師古曰：「詳謂悉盡也。」","sentenceOrder":234},
  {"id":"s_work_han_thu_28_235","chapterId":"ch_work_han_thu_28","textTraditional":"〔五〕　師古曰：「丁、傅及董賢之家皆不便此事也。」","sentenceOrder":235},
  {"id":"s_work_han_thu_28_236","chapterId":"ch_work_han_thu_28","textTraditional":"〔六〕　師古曰：「須，待也。」","sentenceOrder":236},
  {"id":"s_work_han_thu_28_237","chapterId":"ch_work_han_thu_28","textTraditional":"平帝崩，王莽居攝，遂篡位。王莽因漢承平之業，匈奴稱藩，百蠻賓服，舟車所通，盡為臣妾，府庫百官之富，天下晏然。莽一朝有之，其心意未滿，〔一〕陿小漢家制度，以為疏闊。〔二〕宣帝始賜單于印璽，與天子同，而西南夷鉤町稱王。〔三〕莽乃遣使易單于印，貶鉤町王為侯。二方始怨，侵犯邊境。莽遂興師，發三十萬眾，欲同時十道並出，一舉滅匈奴；募發天下囚徒丁男甲卒轉委輸兵器，自負海江淮而至北邊，〔四〕使者馳傳督趣，〔五〕海內擾矣。又動欲慕古，不度時宜，〔六〕分裂州郡，改職作官，下令曰：「漢氏減輕田租，三十而稅一，常有更賦，罷癃咸出，〔七〕而豪民侵陵，分田劫假，〔八〕厥名三十，實什稅五也。富者驕而為邪，貧者窮而為姦，俱陷於辜，刑用不錯。〔九〕今更名天下田曰王田，奴婢曰私屬，皆不得賣買。其男口不滿八，而田過一井者，分餘田與九族鄉黨。」犯令，法至死，制度又不定，吏緣為姦，天下謷謷然，陷刑者眾〔一０〕。","sentenceOrder":237},
  {"id":"s_work_han_thu_28_238","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「謂愛惜之意未厭飽也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_28_239","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「莽以漢家制度為泰疏闊，而更之令陿小。」","sentenceOrder":239},
  {"id":"s_work_han_thu_28_240","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「鉤音鉅于反。町音大鼎反。」","sentenceOrder":240},
  {"id":"s_work_han_thu_28_241","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　如淳曰：「負，背也。」","sentenceOrder":241},
  {"id":"s_work_han_thu_28_242","chapterId":"ch_work_han_thu_28","textTraditional":"〔五〕　師古曰：「傳音張戀反。趣讀曰促。」","sentenceOrder":242},
  {"id":"s_work_han_thu_28_243","chapterId":"ch_work_han_thu_28","textTraditional":"〔六〕　師古曰：「度音大各反。」","sentenceOrder":243},
  {"id":"s_work_han_thu_28_244","chapterId":"ch_work_han_thu_28","textTraditional":"〔七〕　晉灼曰：「雖老病者，皆復出口算。」師古曰：「更音工衡反。罷讀曰疲。」","sentenceOrder":244},
  {"id":"s_work_han_thu_28_245","chapterId":"ch_work_han_thu_28","textTraditional":"〔八〕　師古曰：「分田，謂貧者無田而取富人田耕種，共分其所收也。假亦謂貧人賃富人之田也。劫者，富人劫奪其稅，侵欺之也。」","sentenceOrder":245},
  {"id":"s_work_han_thu_28_246","chapterId":"ch_work_han_thu_28","textTraditional":"〔九〕　師古曰：「錯，置也。」","sentenceOrder":246},
  {"id":"s_work_han_thu_28_247","chapterId":"ch_work_han_thu_28","textTraditional":"〔一０〕師古曰：「謷謷，眾口愁聲也，音敖。」","sentenceOrder":247},
  {"id":"s_work_han_thu_28_248","chapterId":"ch_work_han_thu_28","textTraditional":"後三年，莽知民愁，下詔諸食王田及私屬皆得賣買，勿拘以法。然刑罰深刻，它政誖亂。〔一〕邊兵二十餘萬人仰縣官衣食，〔二〕用度不足，數橫賦歛，〔三〕民俞貧困。常苦枯旱，亡有平歲，穀賈翔貴。〔四〕","sentenceOrder":248},
  {"id":"s_work_han_thu_28_249","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　師古曰：「誖，乖也，音布內反。」","sentenceOrder":249},
  {"id":"s_work_han_thu_28_250","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「仰音牛向反。」","sentenceOrder":250},
  {"id":"s_work_han_thu_28_251","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「數音所角反。橫（因）〔音〕胡孟反。」","sentenceOrder":251},
  {"id":"s_work_han_thu_28_252","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　晉灼曰：「翔音常。」師古曰：「晉說非也。翔言如鳥之回翔，謂不離于貴也。若暴貴，稱騰踊也。」","sentenceOrder":252},
  {"id":"s_work_han_thu_28_253","chapterId":"ch_work_han_thu_28","textTraditional":"末年，盜賊群起，發軍擊之，將吏放縱於外。北邊及青徐地人相食，雒陽以東米石二千。莽遣三公將軍開東方諸倉振貸窮乏，又分遣大夫謁者教民煮木為酪；〔一〕酪不可食，重為煩擾。〔二〕流民入關者數十萬人，置養澹官以稟之，吏盜其稟，〔三〕飢死者什七八。莽恥為政所致，乃下詔曰：「予遭陽九之阨，百六之會，〔四〕枯旱霜蝗，饑饉荐臻，蠻夷猾夏，寇賊姦軌，百姓流離。予甚悼之，害氣將究矣。」〔五〕歲為此言，以至於亡。","sentenceOrder":253},
  {"id":"s_work_han_thu_28_254","chapterId":"ch_work_han_thu_28","textTraditional":"〔一〕　服虔曰：「煮木實，或曰如今餌朮之屬也。」如淳曰：「作杏酪之屬也。」師古曰：「如說是也。」","sentenceOrder":254},
  {"id":"s_work_han_thu_28_255","chapterId":"ch_work_han_thu_28","textTraditional":"〔二〕　師古曰：「重音直用反。」","sentenceOrder":255},
  {"id":"s_work_han_thu_28_256","chapterId":"ch_work_han_thu_28","textTraditional":"〔三〕　師古曰：「稟，給也。盜其稟者，盜所給之物。稟音彼甚反。」","sentenceOrder":256},
  {"id":"s_work_han_thu_28_257","chapterId":"ch_work_han_thu_28","textTraditional":"〔四〕　師古曰：「此曆法應有災歲之期也。事在律曆志。」","sentenceOrder":257},
  {"id":"s_work_han_thu_28_258","chapterId":"ch_work_han_thu_28","textTraditional":"〔五〕　師古曰：「究，竟盡也。」","sentenceOrder":258},
  {"id":"s_work_han_thu_28_259","chapterId":"ch_work_han_thu_28","textTraditional":"校勘記","sentenceOrder":259},
  {"id":"s_work_han_thu_28_260","chapterId":"ch_work_han_thu_28","textTraditional":"一一一七頁　五行　耒（〈古“以”字，形似吕〉）〔耨〕之利以教天下，　王先謙說據顏注，作「耨」是。　按景祐、殿本都作「耨」。","sentenceOrder":260},
  {"id":"s_work_han_thu_28_261","chapterId":"ch_work_han_thu_28","textTraditional":"一一一八頁一二行　事見〔虞書〕舜典。　王先謙說唐寫本「事見」下有「虞書」二字。　按景祐本有。","sentenceOrder":261},
  {"id":"s_work_han_thu_28_262","chapterId":"ch_work_han_thu_28","textTraditional":"一一一九頁一０行　疾病（則）〔相〕救。　景祐、殿本都作「相」。　王先謙說作「相」是。","sentenceOrder":262},
  {"id":"s_work_han_thu_28_263","chapterId":"ch_work_han_thu_28","textTraditional":"一一二一頁　八行　於〔是〕里有序而鄉有庠；　宋祁說「於里有序」「於」字下當添「是」字。　按景祐本有「是」字。","sentenceOrder":263},
  {"id":"s_work_han_thu_28_264","chapterId":"ch_work_han_thu_28","textTraditional":"一一二一頁一一行　春，（秋）〔將〕出民，　張文虎說粵本「秋」作「將」，是。　按景祐、殿本都作「將」。","sentenceOrder":264},
  {"id":"s_work_han_thu_28_265","chapterId":"ch_work_han_thu_28","textTraditional":"一一二一頁一二行　鄰長坐於（右）〔左〕塾，　景祐、殿、局本都作「左」，此誤。","sentenceOrder":265},
  {"id":"s_work_han_thu_28_266","chapterId":"ch_work_han_thu_28","textTraditional":"一一二三頁一三行　然後（〈古“以”字，形似吕〉）〔至〕德流洽，　景祐本作「至」。　王先謙說作「至」是。","sentenceOrder":266},
  {"id":"s_work_han_thu_28_267","chapterId":"ch_work_han_thu_28","textTraditional":"一一二七頁　一行　言居在（閭）〔里〕門之左者，　景祐、殿本都作「里」。","sentenceOrder":267},
  {"id":"s_work_han_thu_28_268","chapterId":"ch_work_han_thu_28","textTraditional":"一一三二頁　九行　急政暴（虐）〔賦〕，　景祐本作「賦」。　王念孫說作「賦」是。　按通鑑亦作「賦」。","sentenceOrder":268},
  {"id":"s_work_han_thu_28_269","chapterId":"ch_work_han_thu_28","textTraditional":"一一三二頁一二行　食必（梁）〔粱〕肉，　景祐、殿、局本都作「粱」。　王先謙說作「粱」是。注同。","sentenceOrder":269},
  {"id":"s_work_han_thu_28_270","chapterId":"ch_work_han_thu_28","textTraditional":"一一三三頁　四行　一說，（字）〔奇〕謂殘餘物也，　景祐、殿、局本都作「奇」。　王先謙說作「奇」是。","sentenceOrder":270},
  {"id":"s_work_han_thu_28_271","chapterId":"ch_work_han_thu_28","textTraditional":"一一三四頁　三行　使天下〔人〕入粟於邊，　景祐、殿本都有「人」字，通鑑亦有。","sentenceOrder":271},
  {"id":"s_work_han_thu_28_272","chapterId":"ch_work_han_thu_28","textTraditional":"一一三四頁一二行　喻嚴固之（基）〔甚〕。　景祐、殿本都作「甚」。　王先謙說作「甚」是。","sentenceOrder":272},
  {"id":"s_work_han_thu_28_273","chapterId":"ch_work_han_thu_28","textTraditional":"一一三六頁一三行　至於（長生）〔生長〕子孫而不轉職也。　景祐、殿本都作「生長」。","sentenceOrder":273},
  {"id":"s_work_han_thu_28_274","chapterId":"ch_work_han_thu_28","textTraditional":"一一三九頁　一行　因隤其土以附（根苗）〔苗根〕。　景祐、殿本都作「苗根」。王先謙說作「苗根」是。","sentenceOrder":274},
  {"id":"s_work_han_thu_28_275","chapterId":"ch_work_han_thu_28","textTraditional":"一一三九頁　二行　（耔）〔芓〕，附根也。　王先謙說殿本「耔」作「芓」是。","sentenceOrder":275},
  {"id":"s_work_han_thu_28_276","chapterId":"ch_work_han_thu_28","textTraditional":"一一四０頁　六行　縵田，謂不為（畮）〔甽〕者也。　景祐、殿本都作「甽」。王先謙說作「甽」是。","sentenceOrder":276},
  {"id":"s_work_han_thu_28_277","chapterId":"ch_work_han_thu_28","textTraditional":"一一四０頁一二行　言（挽）〔換〕功共作也。　景祐、殿本都作「換」。王先謙說作「換」是。","sentenceOrder":277},
  {"id":"s_work_han_thu_28_278","chapterId":"ch_work_han_thu_28","textTraditional":"一一四二頁　二行　使音山（史）〔吏〕反。　景祐、殿本都作「吏」。王先謙說唐寫本同。","sentenceOrder":278},
  {"id":"s_work_han_thu_28_279","chapterId":"ch_work_han_thu_28","textTraditional":"一一四五頁　四行　橫（因）〔音〕胡孟反。　景祐、殿本都作「音」，此誤。","sentenceOrder":279},
  {"id":"s_work_han_thu_29_1","chapterId":"ch_work_han_thu_29","textTraditional":"凡貨，金錢布帛之用，夏殷以前其詳靡記云。太公為周立九府圜法：〔一〕黃金方寸，而重一斤；錢圜函方，〔二〕輕重以銖；〔三〕布帛廣二尺二寸為幅，長四丈為匹。故貨寶於金，利於刀，〔四〕流於泉，〔五〕布於布，〔六〕束於帛。〔七〕","sentenceOrder":1},
  {"id":"s_work_han_thu_29_2","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　李奇曰：「圜即錢也。圜一寸，而重九兩。」師古曰：「此說非也。周官太府、玉府、內府、外府、泉府、天府、職內、職金、職幣皆掌財幣之官，故云九府。圜謂均而通也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_29_3","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　孟康曰：「外圜而內孔方也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_29_4","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰「言黃金以斤為名，錢則以銖為重也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_29_5","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　如淳曰：「名錢為刀者，以其利於民也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_29_6","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　如淳曰：「流行如泉也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_29_7","chapterId":"ch_work_han_thu_29","textTraditional":"〔六〕　如淳曰：「布於民間。」","sentenceOrder":7},
  {"id":"s_work_han_thu_29_8","chapterId":"ch_work_han_thu_29","textTraditional":"〔七〕　李奇曰：「束，聚也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_29_9","chapterId":"ch_work_han_thu_29","textTraditional":"太公退，又行之于齊。至管仲相桓公，通輕重之權，曰：「歲有凶穰，故穀有貴賤；〔一〕令有緩急，故物有輕重。〔二〕人君不理，則畜賈游於市，〔三〕乘民之不給，百倍其本矣。〔四〕故萬乘之國必有萬金之賈，千乘之國必有千金之賈者，利有所并也。計本量委則足矣。〔五〕然而民有飢餓者，穀有所臧也。〔六〕民有餘則輕之，故人君斂之以輕；民不足則重之，故人君散之以重。〔七〕凡輕重斂散之以時，則準平。〔守準平〕，使萬室之邑必有萬鍾之臧，臧繈千萬；〔八〕千室之邑必有千鍾之臧，臧繈百萬。春以奉耕，夏以奉耘，〔九〕耒耜器械，種饟糧食，必取澹焉。〔一０〕故大賈畜家不得豪奪吾民矣。」桓公遂用區區之齊合諸侯，顯伯名。〔一二〕","sentenceOrder":9},
  {"id":"s_work_han_thu_29_10","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「穰音人常反。」","sentenceOrder":10},
  {"id":"s_work_han_thu_29_11","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　李奇曰：「上令急於求米則民重米，緩於求米則民輕米。」","sentenceOrder":11},
  {"id":"s_work_han_thu_29_12","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「畜讀曰蓄。蓄賈，謂賈人之多蓄積者。」","sentenceOrder":12},
  {"id":"s_work_han_thu_29_13","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　師古曰：「給，足也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_29_14","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　李奇曰：「委，積也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_29_15","chapterId":"ch_work_han_thu_29","textTraditional":"〔六〕　師古曰：「言富人多臧穀，故令貧者食不足也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_29_16","chapterId":"ch_work_han_thu_29","textTraditional":"〔七〕　李奇曰：「民輕之時，為斂糴之；重之時，官為散也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_29_17","chapterId":"ch_work_han_thu_29","textTraditional":"〔八〕　李奇曰：「繈，落也。」孟康曰：「六斛四斗為鍾。繈，錢貫也。管子曰『凶（戾）〔歲〕糴，釜十繈』。」師古曰：「孟說是也。繈音居兩反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_29_18","chapterId":"ch_work_han_thu_29","textTraditional":"〔九〕　師古曰：「奉謂供事也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_29_19","chapterId":"ch_work_han_thu_29","textTraditional":"〔一０〕師古曰：「種，五穀之種也。饟字與餉同，謂餉田之具也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_29_20","chapterId":"ch_work_han_thu_29","textTraditional":"〔一一〕師古曰：「畜讀曰蓄。豪謂輕侮之也，字本作{敖力}，蓋通用耳。」","sentenceOrder":20},
  {"id":"s_work_han_thu_29_21","chapterId":"ch_work_han_thu_29","textTraditional":"〔一二〕師古曰：「伯讀曰霸。」","sentenceOrder":21},
  {"id":"s_work_han_thu_29_22","chapterId":"ch_work_han_thu_29","textTraditional":"其後百餘年，周景王時患錢輕，將更鑄大錢，〔一〕單穆公曰：「不可。〔二〕古者天降災戾，〔三〕於是乎量資幣，權輕重，以救民。〔四〕民患輕，則為之作重幣以行之，於是有母權子而行，民皆得焉。〔五〕若不堪重，則多作輕而行之，亦不廢重，於是乎有子權母而行，小大利之。〔六〕今王廢輕而作重，民失其資，能無匱乎？民若匱，王用將有所乏；乏將厚取於民；〔七〕民不給，將有遠志，是離民也。〔八〕且絕民以實王府，猶塞川原為潢洿也，〔九〕竭亡日矣。王其圖之。」弗聽，卒鑄大錢，文曰「寶貨」，肉好皆有周郭，〔一０〕以勸農澹不足，百姓蒙利焉。〔一一〕","sentenceOrder":22},
  {"id":"s_work_han_thu_29_23","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　應劭曰：「大於舊錢，其價重也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_29_24","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「單穆公，周大夫單旗。單音善。」","sentenceOrder":24},
  {"id":"s_work_han_thu_29_25","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「戾，惡氣也。一曰，戾，至也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_29_26","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　應劭曰：「資，財也。量資幣多少有無，平其輕重也。」師古曰：「凡言幣者，皆所以通貨物，易有無也，故金之與錢，皆名為幣也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_29_27","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　應劭曰：「母，重也，其大倍，故為母也。子，輕也，其輕少半，故為子也。民患幣之輕而物貴，為重幣以平之，權時而行，以廢其輕。故曰母權子，猶言重權輕也。民皆得者，本末有無皆得其利也。」孟康曰：「重為母，輕為子，若市八十錢物，以母當五十，以子三十續之。」","sentenceOrder":27},
  {"id":"s_work_han_thu_29_28","chapterId":"ch_work_han_thu_29","textTraditional":"〔六〕　應劭曰：「民患幣重，則多作輕錢而行之，亦不廢去重者，言重者行其貴，輕者行其賤也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_29_29","chapterId":"ch_work_han_thu_29","textTraditional":"〔七〕　師古曰：「厚猶多也，重也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_29_30","chapterId":"ch_work_han_thu_29","textTraditional":"〔八〕　師古曰：「遠志，謂去其本居而散（忘）〔亡〕也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_29_31","chapterId":"ch_work_han_thu_29","textTraditional":"〔九〕　師古曰：「原謂水泉之本也。潢洿，停水也。潢音黃。洿音一胡反。」","sentenceOrder":31},
  {"id":"s_work_han_thu_29_32","chapterId":"ch_work_han_thu_29","textTraditional":"〔一０〕韋昭曰：「肉，錢形也。好，孔也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_29_33","chapterId":"ch_work_han_thu_29","textTraditional":"〔一一〕孟康曰：「單穆公曰『竭無日矣』，不得復云百姓蒙利焉。」臣瓚曰：「但是不聽不鑄大錢耳，猶自從其不廢輕，此言母子並用，故蒙其利也。」師古曰：「二說皆非也。單旗雖有此言，王終自鑄錢，果有便，故百姓蒙其利也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_29_34","chapterId":"ch_work_han_thu_29","textTraditional":"秦兼天下，幣為二等：黃金以溢為名，上幣；〔一〕銅錢質如周錢，〔二〕文曰「半兩」，重如其文。而珠玉龜貝銀錫之屬為器飾寶臧，不為幣，然各隨時而輕重無常。","sentenceOrder":34},
  {"id":"s_work_han_thu_29_35","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　孟康曰：「二十兩為溢。」師古曰：「改周一斤之制，更以溢為金之名數也。高祖初賜張良金百溢，此尚秦制也。上幣者，二等之中黃金為上而錢為下也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_29_36","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　臣瓚曰：「言錢之形質如周錢，唯文異耳。」","sentenceOrder":36},
  {"id":"s_work_han_thu_29_37","chapterId":"ch_work_han_thu_29","textTraditional":"漢興，以為秦錢重難用，更令民鑄莢錢。〔一〕黃金一斤。〔二〕而不軌逐利之民畜積餘贏以稽市物，痛騰躍，〔三〕米至石萬錢，馬至匹百金。天下已平，高祖乃令賈人不得衣絲乘車，重稅租以困辱之。〔四〕孝惠、高后時，為天下初定，復弛商賈之律，〔五〕然市井子孫亦不得（宦為吏）〔為官吏〕。孝文五年，為錢益多而輕，乃更鑄四銖錢，其文為「半兩」。除盜鑄錢令，使民放鑄。〔六〕賈誼諫曰：","sentenceOrder":37},
  {"id":"s_work_han_thu_29_38","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　如淳曰：「如榆莢也。」師古曰：「莢音頰。」","sentenceOrder":38},
  {"id":"s_work_han_thu_29_39","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「復周之制，更以斤名金。」","sentenceOrder":39},
  {"id":"s_work_han_thu_29_40","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　李奇曰：「稽，貯滯也。」晉灼曰：「痛，甚也。言計市物賤，豫益畜之，物貴而出賣，故使物甚騰躍也。」師古曰：「不軌，謂不循軌度者也。言以其贏餘以財蓄積群貨，使物稽滯在己，故市價甚騰貴。今書本痛字或作踊者，誤耳。踊、騰一也，不當重累言之。畜讀曰蓄。」","sentenceOrder":40},
  {"id":"s_work_han_thu_29_41","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　師古曰：「欲令務農。」","sentenceOrder":41},
  {"id":"s_work_han_thu_29_42","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　師古曰：「弛，解也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_29_43","chapterId":"ch_work_han_thu_29","textTraditional":"〔六〕　師古曰：「恣其私鑄。」","sentenceOrder":43},
  {"id":"s_work_han_thu_29_44","chapterId":"ch_work_han_thu_29","textTraditional":"法使天下公得顧租鑄銅錫為錢，敢雜以鉛鐵為它巧者，其罪黥。〔一〕然鑄錢之情，非殽雜為巧，則不可得贏；〔二〕而殽之甚微，為利甚厚。〔三〕夫事有召禍而法有起姦，今令細民人操造幣之勢，〔四〕各隱屏而鑄作，因欲禁其厚利微姦，雖黥罪日報，其勢不止。〔五〕乃者，民人抵罪，多者一縣百數，及吏之所疑，榜笞奔走者甚眾。夫縣法以誘民，〔六〕使入陷阱，孰積於此！〔七〕曩禁鑄錢，死罪積下；〔八〕今公鑄錢，黥罪積下。為法若此，上何賴焉？〔九〕","sentenceOrder":44},
  {"id":"s_work_han_thu_29_45","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「顧租，謂顧庸之直，或租其本。」","sentenceOrder":45},
  {"id":"s_work_han_thu_29_46","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「殽謂亂雜也。贏，餘利也。言不雜鉛鐵，則無利也。殽音爻。」","sentenceOrder":46},
  {"id":"s_work_han_thu_29_47","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「微謂精妙也。言殽雜鉛鐵，其術精妙，不可覺知，而得利甚厚，故令人輕犯之，姦不可止也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_29_48","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　師古曰：「操，持也。人人皆得鑄錢也。操音千高反。」","sentenceOrder":48},
  {"id":"s_work_han_thu_29_49","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　鄭氏曰：「報，論。」","sentenceOrder":49},
  {"id":"s_work_han_thu_29_50","chapterId":"ch_work_han_thu_29","textTraditional":"〔六〕　師古曰：「縣謂開立之。」","sentenceOrder":50},
  {"id":"s_work_han_thu_29_51","chapterId":"ch_work_han_thu_29","textTraditional":"〔七〕　師古曰：「阱，穿地以陷獸也。積，多也。阱音才性反。」","sentenceOrder":51},
  {"id":"s_work_han_thu_29_52","chapterId":"ch_work_han_thu_29","textTraditional":"〔八〕　蘇林曰：「下，報也，積累下報論之也。」張晏曰：「死罪者多，委積於下也。」師古曰：「蘇說是也。下音胡亞反。次後亦同。」","sentenceOrder":52},
  {"id":"s_work_han_thu_29_53","chapterId":"ch_work_han_thu_29","textTraditional":"〔九〕　師古曰：「賴，利也。一曰恃也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_29_54","chapterId":"ch_work_han_thu_29","textTraditional":"又民用錢，郡縣不同：或用錢輕，百加若干；〔一〕或用重錢，平稱不受。〔二〕法錢不立，〔三〕吏急而壹之虖，則大為煩苛，而力不能勝；縱而弗呵虖，〔四〕則市肆異用，錢文大亂。苟非其術，何鄉而可哉！〔五〕","sentenceOrder":54},
  {"id":"s_work_han_thu_29_55","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　應劭曰：「時錢重四銖，法錢百枚，當重一斤十六銖，輕則以錢足之若干枚，令滿平也。」師古曰：「若干，且設數之言也。干猶箇也，謂當如此箇數耳。而胡廣云『若，順也；干，求也』。當順所求而與之矣。」","sentenceOrder":55},
  {"id":"s_work_han_thu_29_56","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　應劭曰：「用重錢，則平稱有餘，不能受也。」臣瓚曰：「秦錢重半兩，漢初鑄莢錢，文帝更鑄四銖錢。秦錢與莢錢皆當廢，而故與四銖並行。民以其見廢，故用輕錢，則百加若干；用重錢，雖以一當一猶復不受之。是以郡縣不同也。」師古曰：「應說是也。稱音尺孕反。」","sentenceOrder":56},
  {"id":"s_work_han_thu_29_57","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「法錢，依法之錢也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_29_58","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　師古曰：「呵，責怒也，音火何反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_29_59","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":59},
  {"id":"s_work_han_thu_29_60","chapterId":"ch_work_han_thu_29","textTraditional":"今農事棄捐而采銅者日蕃，〔一〕釋其耒耨，冶鎔炊炭〔二〕，姦錢日多，五穀不為多。〔三〕善人怵而為姦邪，〔四〕愿民陷而之刑戮，〔五〕刑戮將甚不詳，奈何而忽！〔六〕國知患此，吏議必曰禁之。禁之不得其術，其傷必大。令禁鑄錢，則錢必重；〔七〕重則其利深，盜鑄如雲而起，〔八〕棄市之罪又不足以禁矣。姦數不勝而法禁數潰，銅使之然也。〔九〕故銅布於天下，其為禍博矣〔一０〕。","sentenceOrder":60},
  {"id":"s_work_han_thu_29_61","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「蕃，多也，音扶元反。其下亦同。」","sentenceOrder":61},
  {"id":"s_work_han_thu_29_62","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　應劭曰：「鎔，形容也，作錢模也。」師古曰：「鎔音容。」","sentenceOrder":62},
  {"id":"s_work_han_thu_29_63","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「言皆采銅鑄錢，廢其農業，故五穀不多也。為音於偽反。不為多，猶言為之不多也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_29_64","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　李奇曰：「怵，誘也，動心於姦邪也。」師古曰：「怵音先律反，又音黜。」","sentenceOrder":64},
  {"id":"s_work_han_thu_29_65","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　師古曰：「愿，謹也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_29_66","chapterId":"ch_work_han_thu_29","textTraditional":"〔六〕　師古曰：「詳，平也。忽，忽忘也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_29_67","chapterId":"ch_work_han_thu_29","textTraditional":"〔七〕　師古曰：「令謂法令也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_29_68","chapterId":"ch_work_han_thu_29","textTraditional":"〔八〕　師古曰：「言其多。」","sentenceOrder":68},
  {"id":"s_work_han_thu_29_69","chapterId":"ch_work_han_thu_29","textTraditional":"〔九〕　師古曰：「數，並音所角反。」","sentenceOrder":69},
  {"id":"s_work_han_thu_29_70","chapterId":"ch_work_han_thu_29","textTraditional":"〔一０〕師古曰：「博，大也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_29_71","chapterId":"ch_work_han_thu_29","textTraditional":"今博禍可除，而七福可致也。何謂七福？上收銅勿令布，則民不鑄錢，黥罪不積，一矣。偽錢不蕃，民不相疑，二矣。采銅鑄作者反於耕田，三矣。銅畢歸於上，上挾銅積以御輕重，〔一〕錢輕則以術斂之，重則以術散之，貨物必平，四矣。以作兵器，以假貴臣，多少有制，用別貴踐，五矣。〔二〕以臨萬貨，以調盈虛，以收奇羨，〔三〕則官富實而末民困，六矣。〔四〕制吾棄財，以與匈奴逐爭其民，其敵必懷，七矣。〔五〕故善為天下者，因禍而為福，轉敗而為功。今久退七福而行博禍，臣誠傷之。","sentenceOrder":71},
  {"id":"s_work_han_thu_29_72","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「銅積，謂多積銅也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_29_73","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　如淳曰：「古者以銅為兵，秦銷鋒鍉鑄金人十二，是也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_29_74","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「調，平均也。奇，殘餘也。羨，饒溢也。奇音居宜反。羨音弋戰反。」","sentenceOrder":74},
  {"id":"s_work_han_thu_29_75","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　師古曰：「末謂工商之業也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_29_76","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　師古曰：「末業既困，農人敦本，倉廩積實，布帛有餘，則招誘胡人，多來降附。故言制吾棄財逐爭其人也。棄財者，可棄之財。逐，競也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_29_77","chapterId":"ch_work_han_thu_29","textTraditional":"上不聽。是時，吳以諸侯即山鑄錢，富埒天子，〔一〕後卒叛逆。鄧通，大夫也，以鑄錢財過王者。故吳、鄧錢布天下。","sentenceOrder":77},
  {"id":"s_work_han_thu_29_78","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「即，就也。埒，等也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_29_79","chapterId":"ch_work_han_thu_29","textTraditional":"武帝因文、景之畜，忿胡、粵之害，〔一〕即位數年，嚴助、朱買臣等招徠東甌，事兩粵，江淮之間蕭然煩費矣。〔二〕唐蒙、司馬相如始開西南夷，鑿山通道千餘里，以廣巴蜀，巴蜀之民罷焉。〔三〕彭吳穿穢貊、朝鮮，置滄海郡，〔四〕則燕齊之間靡然發動。及王恢謀馬邑，匈奴絕和親，侵優北邊，兵連而不解，天下共其勞。〔五〕干戈日滋，行者齎，居者送，〔六〕中外騷擾相奉，百姓抏敝以巧法，〔七〕財賂衰耗而不澹。〔八〕入物者補官，出貨者除罪，選舉陵夷，廉恥相冒，〔九〕武力進用，法嚴令具，興利之臣自此而始。〔一０〕","sentenceOrder":79},
  {"id":"s_work_han_thu_29_80","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「畜讀曰蓄。」","sentenceOrder":80},
  {"id":"s_work_han_thu_29_81","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「蕭然猶騷然，勞動之貌。」","sentenceOrder":81},
  {"id":"s_work_han_thu_29_82","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「罷讀曰疲。」","sentenceOrder":82},
  {"id":"s_work_han_thu_29_83","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　師古曰：「彭吳，人姓名也。本皆荒梗，始開通之也，故言穿也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_29_84","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　師古曰：「共猶同。」","sentenceOrder":84},
  {"id":"s_work_han_thu_29_85","chapterId":"ch_work_han_thu_29","textTraditional":"〔六〕　師古曰：「齎謂將衣食之具以自隨也，音子奚反。」","sentenceOrder":85},
  {"id":"s_work_han_thu_29_86","chapterId":"ch_work_han_thu_29","textTraditional":"〔七〕　師古曰：「抏，訛也，謂摧挫也。巧法，為巧詐以避法也。抏音五官反。」","sentenceOrder":86},
  {"id":"s_work_han_thu_29_87","chapterId":"ch_work_han_thu_29","textTraditional":"〔八〕　師古曰：「耗，減也。澹，足也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_29_88","chapterId":"ch_work_han_thu_29","textTraditional":"〔九〕　師古曰：「冒，蒙也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_29_89","chapterId":"ch_work_han_thu_29","textTraditional":"〔一０〕師古曰：「謂桑弘羊、東郭咸陽、孔僅之屬也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_29_90","chapterId":"ch_work_han_thu_29","textTraditional":"其後，衛青歲以數萬騎出擊匈奴，遂取河南地，築朔方。時又通西南夷道，作者數萬人，千里負擔餽饟，〔一〕率十餘鍾致一石〔二〕，散幣於邛僰以輯之。〔三〕數歲而道不通，蠻夷因以數攻（吏），吏發兵誅之。悉巴蜀租賦不足以更之，〔四〕乃募豪民田南夷，入粟縣官，而內受錢於都內。〔五〕東置滄海郡，人徒之費疑於南夷。〔六〕又興十餘萬築衛朔方，〔七〕轉漕甚遠，自山東咸被其勞，費數十百鉅萬，〔八〕府庫並虛。乃募民能入奴婢得以終身復，為郎增秩，〔九〕及入羊為郎，始於此。","sentenceOrder":90},
  {"id":"s_work_han_thu_29_91","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「餽亦饋字。饟，古餉字。」","sentenceOrder":91},
  {"id":"s_work_han_thu_29_92","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「言其勞費用功重。」","sentenceOrder":92},
  {"id":"s_work_han_thu_29_93","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　應劭曰：「邛屬臨邛，僰屬犍為。」晉灼曰：「僰音蒲賊反。」師古曰：「本西南夷兩種也。邛，今邛州也。僰，今僰道縣也。輯與集同，謂安定也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_29_94","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　李奇曰：「不足用，終更其事也。」韋昭曰：「更，續也。」師古曰：「二說並非也。悉，盡也。更，償也。雖盡租賦不足償其功費也。更音庚。」","sentenceOrder":94},
  {"id":"s_work_han_thu_29_95","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　服虔曰：「入穀於外縣，而受粟錢於內府也。」師古曰：「此說非也。都內，京師主臧者也。百官公卿表大司農屬官有都內令丞也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_29_96","chapterId":"ch_work_han_thu_29","textTraditional":"〔六〕　師古曰：「疑讀曰儗。儗謂比也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_29_97","chapterId":"ch_work_han_thu_29","textTraditional":"〔七〕　師古曰：「既築其城，又守衛之。」","sentenceOrder":97},
  {"id":"s_work_han_thu_29_98","chapterId":"ch_work_han_thu_29","textTraditional":"〔八〕　師古曰：「數十萬乃至百萬萬。」","sentenceOrder":98},
  {"id":"s_work_han_thu_29_99","chapterId":"ch_work_han_thu_29","textTraditional":"〔九〕　師古曰：「庶人入奴婢則復終身，先為郎者就增其秩也。一曰入奴婢少者復終身，多者得為郎，舊為郎更增秩也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_29_100","chapterId":"ch_work_han_thu_29","textTraditional":"此後四年，衛青比歲十餘萬眾擊胡，〔一〕斬捕首虜之士受賜黃金二十餘萬斤，而漢軍士馬死者十餘萬，兵甲轉漕之費不與焉。〔二〕於是大司農陳臧錢經用，賦稅既竭，不足以奉戰士。〔三〕有司請令民得買爵及贖禁錮免（臧）〔減〕罪；請置賞官，名曰武功爵〔四〕。級十七萬，凡直三十餘萬金。諸買武功爵官首者試補吏，先除；千夫如五大夫；〔五〕其有罪又減二等；爵得至樂卿，〔六〕以顯軍功。軍功多用超等，大者封侯卿大夫，小者郎。吏道雜而多端，則官職秏廢。〔七〕","sentenceOrder":100},
  {"id":"s_work_han_thu_29_101","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「比歲，頻歲也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_29_102","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「與讀曰豫。」","sentenceOrder":102},
  {"id":"s_work_han_thu_29_103","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「陳謂列奏之。經，常也。既，盡也。言常用之錢及諸賦稅並竭盡也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_29_104","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　臣瓚曰：「茂陵中書有武功爵，一級曰造士，二級曰閑輿衛，三級曰良士，四級曰元戎士，五級曰官首，六級曰秉鐸，七級曰千夫，八級曰樂卿，九級曰執戎，十級曰政戾庶長，十一級曰軍衛。此武帝所制，以寵軍功。」師古曰：「此下云級十七萬，凡直三十餘萬金，今瓚所引茂陵中書止於十一級，則計數不足，與本文乖矣。或者茂陵書說之不盡也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_29_105","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　師古曰：「五大夫，舊二十等爵之第九級也。至此以上，始免徭役，故每先選以為吏。千夫者，武功十一等爵之第七也，亦得免役，今則先除為吏，比於五大夫也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_29_106","chapterId":"ch_work_han_thu_29","textTraditional":"〔六〕　師古曰：「樂卿者，武功爵第八等也。言買爵唯得至第八也。此文止論武功爵級，而作注者乃以舊二十等爵解之，失其本意，故刪而不取。」","sentenceOrder":106},
  {"id":"s_work_han_thu_29_107","chapterId":"ch_work_han_thu_29","textTraditional":"〔七〕　師古曰：「秏，亂也，音莫報反。」","sentenceOrder":107},
  {"id":"s_work_han_thu_29_108","chapterId":"ch_work_han_thu_29","textTraditional":"自〔公〕孫弘以春秋之義繩臣下取漢相，張湯以峻文決理為廷尉，於是見知之法生，而廢格沮誹窮治之獄用矣。〔一〕其明年，淮南、衡山、江都王謀反跡見，〔二〕而公卿尋端治之，竟其黨與，坐而死者數萬人，吏益慘急而法令察。〔三〕當是時，招尊方正賢良文學之士，或至公卿大夫。公孫弘以宰相，布被，食不重味，為下先，然而無益於俗，稍務於功利矣。","sentenceOrder":108},
  {"id":"s_work_han_thu_29_109","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　張晏曰：「吏見知不舉劾為故縱，官有所作，廢格沮敗誹謗，則窮治之也。」如淳曰：「廢格天子文法，使不行也。誹謂非上所行，若顏異反脣之比也。」師古曰：「沮，（上）〔止〕壞之，音材汝反。」","sentenceOrder":109},
  {"id":"s_work_han_thu_29_110","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「蹤跡顯見也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_29_111","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「慘，毒也。察，微視也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_29_112","chapterId":"ch_work_han_thu_29","textTraditional":"其明年，票騎仍再出擊胡，大克獲。〔一〕渾邪王率數萬眾來降，〔二〕於是漢發車三萬兩迎之。〔三〕既至，受賞，賜及有功之士。是歲費凡百餘鉅萬。","sentenceOrder":112},
  {"id":"s_work_han_thu_29_113","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「仍，頻也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_29_114","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「渾音胡昆反。」","sentenceOrder":114},
  {"id":"s_work_han_thu_29_115","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「一兩，一乘。」","sentenceOrder":115},
  {"id":"s_work_han_thu_29_116","chapterId":"ch_work_han_thu_29","textTraditional":"先是十餘歲，河決，灌梁、楚地，固已數困，而緣河之郡隄塞河，輒壞決，費不可勝計。其後番係欲省底柱之漕，〔一〕穿汾、河渠以為溉田；鄭當時為渭漕回遠，鑿漕直渠自長安至華陰；〔二〕而朔方亦穿溉渠。作者各數萬人，歷二三期而功未就，費亦各以鉅萬十數。〔三〕","sentenceOrder":116},
  {"id":"s_work_han_thu_29_117","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「番，姓；係，名也。番音普安反。係音工系反。」","sentenceOrder":117},
  {"id":"s_work_han_thu_29_118","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「回，曲繞也，音胡內反。」","sentenceOrder":118},
  {"id":"s_work_han_thu_29_119","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「謂十萬萬也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_29_120","chapterId":"ch_work_han_thu_29","textTraditional":"天子為伐胡故，盛養馬，馬之往來食長安者數萬匹，〔一〕卒掌者關中不足，乃調旁近郡。〔二〕而胡降者數萬人皆得厚賞，衣食仰給縣官，〔三〕縣官不給，〔四〕天子乃損膳，解乘輿駟，出御府禁臧以澹之。","sentenceOrder":120},
  {"id":"s_work_han_thu_29_121","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「食讀曰飤。」","sentenceOrder":121},
  {"id":"s_work_han_thu_29_122","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「調謂選發之也。調音徒釣反。」","sentenceOrder":122},
  {"id":"s_work_han_thu_29_123","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「仰音牛向反，次下亦同。」","sentenceOrder":123},
  {"id":"s_work_han_thu_29_124","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　師古曰：「給，足也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_29_125","chapterId":"ch_work_han_thu_29","textTraditional":"其明年，山東被水災，民多飢乏，於是天子遣使虛郡國倉廩以振貧。猶不足，又募豪富人相假貸。〔一〕尚不能相救，乃徙貧民於關以西，及充朔方以南新秦中，〔二〕七十餘萬口，衣食皆仰給於縣官。數歲，貸與產業，使者分部護，〔三〕冠蓋相望，費以億計，縣官大空。而富商賈或墆財役貧，〔四〕轉轂百數，〔五〕廢居居邑〔六〕，封君皆氐首仰給焉。〔七〕冶鑄煮鹽，財或累萬金，而不佐公家之急，黎民重困。〔八〕","sentenceOrder":125},
  {"id":"s_work_han_thu_29_126","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「貸音土戴反。次下亦同。」","sentenceOrder":126},
  {"id":"s_work_han_thu_29_127","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　應劭曰：「秦始皇遣蒙恬攘卻匈奴，得其河南造陽之北千里地甚好，於是為築城郭，徙民充之，名曰新秦。四方雜錯，奢儉不同，今俗名新富貴者為『新秦』，由是名也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_29_128","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「分音扶問反。」","sentenceOrder":128},
  {"id":"s_work_han_thu_29_129","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　孟康曰：「墆，停也。」晉灼曰：「墆音滯。」","sentenceOrder":129},
  {"id":"s_work_han_thu_29_130","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　李奇曰：「轂，車也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_29_131","chapterId":"ch_work_han_thu_29","textTraditional":"〔六〕　服虔曰：「居穀於邑也。」如淳曰：「居賤物於邑中以待貴也。」師古曰：「二說皆未盡也。此言或有所廢置，有所居蓄，而居於邑中，以乘時射利也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_29_132","chapterId":"ch_work_han_thu_29","textTraditional":"〔七〕　晉灼曰：「氐音抵距之抵。」服虔曰：「仰給於商賈，言百姓好末作也。」師古曰：「二說皆非也。封君，受封邑者，謂公主及列侯之屬也。氐首，猶俯首也。時公主、列侯雖有國邑而無餘財，其朝夕所須皆俯首而取給於富商大賈，後方以邑入償之。氐音丁奚反。」","sentenceOrder":132},
  {"id":"s_work_han_thu_29_133","chapterId":"ch_work_han_thu_29","textTraditional":"〔八〕　師古曰：「重音直用反。」","sentenceOrder":133},
  {"id":"s_work_han_thu_29_134","chapterId":"ch_work_han_thu_29","textTraditional":"於是天子與公卿議，更造錢幣以澹用，〔一〕而摧浮淫并兼之徒。是時禁苑有白鹿而少府多銀錫。自孝文更造四銖錢，至是歲四十餘年，從建元以來，用少，縣官往往即多銅山而鑄錢，〔二〕民亦盜鑄，不可勝數。錢益多而輕，〔三〕物益少而貴。〔四〕有司言曰：「古者皮幣，諸侯以聘享。金有三等，黃金為上，白金為中，赤金為下。〔五〕今半兩錢法重四銖，〔六〕而姦或盜摩錢質而取鋊，〔七〕錢益輕薄而物貴，則遠方用幣煩費不省。」乃以白鹿皮方尺，緣以繢，為皮幣，〔八〕直四十萬。王侯宗室朝覲聘享，必以皮幣薦璧，然後得行。","sentenceOrder":134},
  {"id":"s_work_han_thu_29_135","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「更，改也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_29_136","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「就多銅之山而鑄錢也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_29_137","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　臣瓚曰：「鑄錢者多，故錢輕。輕亦賤也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_29_138","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　如淳曰：「民但鑄錢，不作餘物故也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_29_139","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　孟康曰：「白金，銀也。赤金，丹陽銅也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_29_140","chapterId":"ch_work_han_thu_29","textTraditional":"〔六〕　鄭氏曰：「其文為半兩，實（為）〔重〕四銖也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_29_141","chapterId":"ch_work_han_thu_29","textTraditional":"〔七〕　如淳曰：「錢一面有文，一面幕，幕為質。民盜摩漫面而取其鋊，以更鑄作錢也。」臣瓚曰：「許慎云『鋊，銅屑也』。摩錢漫面以取其屑，更以鑄錢。西京黃圖叙曰『民摩錢取屑』是也。」師古曰：「鋊音浴。瓚說是也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_29_142","chapterId":"ch_work_han_thu_29","textTraditional":"〔八〕　師古曰：「繢，繡也，繪五綵而為之。」","sentenceOrder":142},
  {"id":"s_work_han_thu_29_143","chapterId":"ch_work_han_thu_29","textTraditional":"又造銀錫白金。〔一〕以為天用莫如龍，地用莫如馬，人用莫如龜，故白金三品：其一曰重八兩，圜之，其文龍，名「白撰」，直三千；二曰以重差小，方之，其文馬，直五百；〔二〕三曰復小，橢之，其文龜，直三百。〔三〕令縣官銷半兩錢，更鑄三誅錢，重如其文。盜鑄諸金錢罪皆死，而吏民之犯者不可勝數。","sentenceOrder":143},
  {"id":"s_work_han_thu_29_144","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　如淳曰：「雜鑄銀錫為白金。」","sentenceOrder":144},
  {"id":"s_work_han_thu_29_145","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　晉灼曰：「以半斤之重差為三品，此重六兩，則下品重四兩也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_29_146","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「橢，圜而長也，音佗果反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_29_147","chapterId":"ch_work_han_thu_29","textTraditional":"於是以東郭咸陽、孔僅為大農丞，〔一〕領鹽鐵事，而桑弘羊貴幸。咸陽，齊之大煮鹽，孔僅，南陽大冶，皆致產累千金，故鄭當時進言之。弘羊，洛陽賈人之子，以心計，〔二〕年十三侍中。故三人言利事析秋豪矣。","sentenceOrder":147},
  {"id":"s_work_han_thu_29_148","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「二人也，姓東郭名咸陽，姓孔名僅。僅音鉅刃反。」","sentenceOrder":148},
  {"id":"s_work_han_thu_29_149","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「不用籌算。」","sentenceOrder":149},
  {"id":"s_work_han_thu_29_150","chapterId":"ch_work_han_thu_29","textTraditional":"法既益嚴，吏多廢免。兵革數動，民多買復〔一〕及五大夫、千夫，徵發之士益鮮。〔二〕於是除千夫、五大夫為吏，不欲者出馬；〔三〕故吏皆適令伐棘上林，作昆明池。〔四〕","sentenceOrder":150},
  {"id":"s_work_han_thu_29_151","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「入財於官，以取優復。復音方目反。」","sentenceOrder":151},
  {"id":"s_work_han_thu_29_152","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「鮮，少也，音先淺反。」","sentenceOrder":152},
  {"id":"s_work_han_thu_29_153","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　如淳曰：「千夫、五大夫不欲為吏者，令之出馬也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_29_154","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　師古曰：「適讀曰謫。謫，責罰也，以其久為姦利。」","sentenceOrder":154},
  {"id":"s_work_han_thu_29_155","chapterId":"ch_work_han_thu_29","textTraditional":"其明年，大將軍、票騎大出擊胡，賞賜五十萬金，軍馬死者十餘萬匹，轉漕車甲之費不與焉。〔一〕是時財匱，〔二〕戰士頗不得祿矣。","sentenceOrder":155},
  {"id":"s_work_han_thu_29_156","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「與讀曰豫。」","sentenceOrder":156},
  {"id":"s_work_han_thu_29_157","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「匱，空也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_29_158","chapterId":"ch_work_han_thu_29","textTraditional":"有司言三銖錢輕，輕錢易作姦詐，乃更請郡國鑄五銖錢，周郭其質，令不可得摩取（鉛）〔鋊〕。〔一〕","sentenceOrder":158},
  {"id":"s_work_han_thu_29_159","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　孟康曰：「周匝為郭，文漫皆有。」","sentenceOrder":159},
  {"id":"s_work_han_thu_29_160","chapterId":"ch_work_han_thu_29","textTraditional":"大農上鹽鐵丞孔僅、咸陽言：〔一〕「山海，天地之臧，宜屬少府，陛下弗私，以屬大農佐賦。願募民自給費，因官器作煮鹽，官與牢盆。〔二〕浮食奇民欲擅斡山海之貨，以致富羨，〔三〕役利細民。其沮事之議，不可勝聽。敢私鑄鐵器煮鹽者，釱左趾，〔四〕沒入其器物。郡不出鐵者，置小鐵官，〔五〕使屬在所縣。」使僅、咸陽乘傳舉行天下鹽鐵，〔六〕作官府，〔七〕除故鹽鐵家富者為吏。吏益多賈人矣。","sentenceOrder":160},
  {"id":"s_work_han_thu_29_161","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「奏上其言也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_29_162","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　蘇林曰：「牢，價直也。今世人言顧手牢。」如淳曰：「牢，廩食也。古者名廩為牢。盆，煮鹽盆也。」師古曰：「牢，蘇說是也。〈鬻，中“米改者”〉，古煮字也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_29_163","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「斡謂主領也，讀與管同。羨，饒也，音弋戰反。」","sentenceOrder":163},
  {"id":"s_work_han_thu_29_164","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　師古曰：「釱，足鉗也，音徒計反。」","sentenceOrder":164},
  {"id":"s_work_han_thu_29_165","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　鄧展曰：「鑄故鐵。」","sentenceOrder":165},
  {"id":"s_work_han_thu_29_166","chapterId":"ch_work_han_thu_29","textTraditional":"〔六〕　師古曰：「舉，皆也，普天之下皆行之也。〔行〕音下更反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_29_167","chapterId":"ch_work_han_thu_29","textTraditional":"〔七〕　師古曰：「主煮鑄及出納之處也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_29_168","chapterId":"ch_work_han_thu_29","textTraditional":"商賈以幣之變，多積貨逐利。於是公卿言：「郡國頗被災害，貧民無產業者，募徙廣饒之地。陛下損膳省用，出禁錢以振元元，寬貸，而民不齊出南畝，〔一〕商賈滋眾。貧者畜積無有，皆仰縣官〔二〕。異時算軺車賈人之緍錢皆有差，〔三〕請算如故。諸賈人末作貰貸賣買，居邑貯積諸物，〔四〕及商以取利者，雖無市籍，各以其物自占，〔五〕率緍錢二千而算一。〔六〕諸作有租及鑄，〔七〕率緍錢四千算一。非吏比者、三老、北邊騎士，軺車一算；〔八〕商賈人軺車二算；〔九〕船五丈以上一算。匿不自占，占不悉，戍邊一歲，沒入緍錢。〔一０〕有能告者，以其半畀之。〔一一〕賈人有市籍，及家屬，皆無得名田，〔一二〕以便農。敢犯令，沒入田貨。」","sentenceOrder":168},
  {"id":"s_work_han_thu_29_169","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「言農人尚少，不皆務耕種也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_29_170","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「畜讀曰蓄。仰音牛向反。」","sentenceOrder":170},
  {"id":"s_work_han_thu_29_171","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「異時，言往時也。軺，小車也。緍謂錢貫也。軺音弋昭反。緍音武巾反。」","sentenceOrder":171},
  {"id":"s_work_han_thu_29_172","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　師古曰：「貰，賒也。貸，假與也。貰音式制反。貸音土戴反。」","sentenceOrder":172},
  {"id":"s_work_han_thu_29_173","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　師古曰：「占，隱度也，各隱度其財物多少，而為名簿送之於官也。占音之贍反。」","sentenceOrder":173},
  {"id":"s_work_han_thu_29_174","chapterId":"ch_work_han_thu_29","textTraditional":"〔六〕　師古曰：「率計有二千錢者則出一算。」","sentenceOrder":174},
  {"id":"s_work_han_thu_29_175","chapterId":"ch_work_han_thu_29","textTraditional":"〔七〕　如淳曰：「以手力所作而賣之者。」","sentenceOrder":175},
  {"id":"s_work_han_thu_29_176","chapterId":"ch_work_han_thu_29","textTraditional":"〔八〕　師古曰：「比，例也。身非為吏之例，非為三老，非為北邊騎士，而有軺車，皆令出一算。比音必寐反。」","sentenceOrder":176},
  {"id":"s_work_han_thu_29_177","chapterId":"ch_work_han_thu_29","textTraditional":"〔九〕　如淳曰：「商賈人有軺車，又使多出一算，重其賦。」","sentenceOrder":177},
  {"id":"s_work_han_thu_29_178","chapterId":"ch_work_han_thu_29","textTraditional":"〔一０〕師古曰：「悉，盡也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_29_179","chapterId":"ch_work_han_thu_29","textTraditional":"〔一一〕師古曰：「畀，與也，音必寐反。」","sentenceOrder":179},
  {"id":"s_work_han_thu_29_180","chapterId":"ch_work_han_thu_29","textTraditional":"〔一二〕師古曰：「一人有市籍，則身及家內皆不得有田也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_29_181","chapterId":"ch_work_han_thu_29","textTraditional":"是時，豪富皆爭匿財，唯卜式數求入財以助縣官。天子乃超拜式為中郎，賜爵左庶長，田十頃，布告天下，以風百姓。〔一〕初，式不願為官，上強拜之，稍遷至齊相。語自在其傳。孔僅使天下鑄作器，三年中至大司農，列於九卿。而桑弘羊為大司農中丞，管諸會計事，稍稍置均輸以通貨物。始令吏得入穀補官，郎至六百石。〔二〕","sentenceOrder":181},
  {"id":"s_work_han_thu_29_182","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「風讀曰諷。」","sentenceOrder":182},
  {"id":"s_work_han_thu_29_183","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「吏更遷補高官，郎又就增其秩，得至六百石也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_29_184","chapterId":"ch_work_han_thu_29","textTraditional":"自造白金五銖錢後五歲，而赦吏民之坐盜鑄金錢死者數十萬人。其不發覺相殺者，不可勝計。赦自出者百餘萬人。然不能半自出，天下大氐無慮皆鑄金錢矣。〔一〕犯法者眾，吏不能盡誅，於是遣博士褚大、徐偃等分行郡國，〔二〕舉并兼之徒守相為利者。〔三〕而御史大夫張湯方貴用事，減宣、杜周等為中丞，〔四〕義縱、尹齊、王溫舒等用急刻為九卿，直指夏蘭之屬始出。〔五〕而大農顏異誅矣。初，異為濟南亭長，以廉直稍遷至九卿。上與湯既造白鹿皮幣，問異。異曰：「今王侯朝賀以倉璧，直數千，而其皮薦反四十萬，本末不相稱。」天子不說。〔六〕湯又與異有隙，及人有告異以它議，事下湯治。異與客語，客語初令下有不便者，〔七〕異不應，微反脣〔八〕。湯奏當異九卿見令不便，不入言而腹非，〔九〕論死。自是後有腹非之法比，〔一０〕而公卿大夫多諂諛取容。","sentenceOrder":184},
  {"id":"s_work_han_thu_29_185","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「氐讀曰抵。抵，歸也。大歸猶言大凡也。無慮亦謂大率無小計慮耳。」","sentenceOrder":185},
  {"id":"s_work_han_thu_29_186","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「行音下更反。」","sentenceOrder":186},
  {"id":"s_work_han_thu_29_187","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「守，郡守也。相，諸侯相。」","sentenceOrder":187},
  {"id":"s_work_han_thu_29_188","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　師古曰：「減，姓也，音減省之減。」","sentenceOrder":188},
  {"id":"s_work_han_thu_29_189","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　蘇林曰：「夏蘭，人姓名。」","sentenceOrder":189},
  {"id":"s_work_han_thu_29_190","chapterId":"ch_work_han_thu_29","textTraditional":"〔六〕　師古曰：「說讀曰悅。」","sentenceOrder":190},
  {"id":"s_work_han_thu_29_191","chapterId":"ch_work_han_thu_29","textTraditional":"〔七〕　李奇曰：「異與客語，道詔令初下有不便處。」","sentenceOrder":191},
  {"id":"s_work_han_thu_29_192","chapterId":"ch_work_han_thu_29","textTraditional":"〔八〕　師古曰：「蓋非之。」","sentenceOrder":192},
  {"id":"s_work_han_thu_29_193","chapterId":"ch_work_han_thu_29","textTraditional":"〔九〕　師古曰：「當謂處斷其罪。」","sentenceOrder":193},
  {"id":"s_work_han_thu_29_194","chapterId":"ch_work_han_thu_29","textTraditional":"〔一０〕師古曰：「比，則例也，讀如字，又音必寐反。」","sentenceOrder":194},
  {"id":"s_work_han_thu_29_195","chapterId":"ch_work_han_thu_29","textTraditional":"天（下）〔子〕既下緍錢令而尊卜式，百姓終莫分財佐縣官，於是告緍錢縱矣。〔一〕","sentenceOrder":195},
  {"id":"s_work_han_thu_29_196","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「縱，放也，放令相告言也。」","sentenceOrder":196},
  {"id":"s_work_han_thu_29_197","chapterId":"ch_work_han_thu_29","textTraditional":"郡國鑄錢，民多姦鑄，〔一〕錢多輕，而公卿請令京師鑄官赤仄，〔二〕一當五，賦官用非赤仄不得行。〔三〕白金稍賤，民弗寶用，縣官以令禁之，無益，歲餘終廢不行。是歲，湯死而民不思。其後二歲，赤仄錢賤，民巧法用之，不便，又廢。於是悉禁郡國毋鑄錢，專令上林三官鑄。錢既多，而令天下非三官錢不得行，諸郡國前所鑄錢皆廢銷之，輸入其銅三官。而民之鑄錢益少，計其費不能相當〔四〕，唯真工大姦乃盜為之。〔五〕","sentenceOrder":197},
  {"id":"s_work_han_thu_29_198","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「謂巧鑄之，雜鉛錫。」","sentenceOrder":198},
  {"id":"s_work_han_thu_29_199","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　應劭曰：「所謂子紺錢也。」如淳曰：「以赤銅為其郭也。（令）〔今〕錢郭見有赤者，不知作法云何也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_29_200","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「充賦及給官用，皆令以赤仄。」","sentenceOrder":200},
  {"id":"s_work_han_thu_29_201","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　師古曰：「言無利。」","sentenceOrder":201},
  {"id":"s_work_han_thu_29_202","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　師古曰：「其術巧妙，故得利。」","sentenceOrder":202},
  {"id":"s_work_han_thu_29_203","chapterId":"ch_work_han_thu_29","textTraditional":"楊可告緍遍天下，〔一〕中家以上大氐皆遇告。杜周治之，獄少反者。〔二〕乃分遣御史廷尉正監分曹往，〔三〕（往）即治郡國緍錢，〔四〕得民財物以億計，奴婢以千萬數，田大縣數百頃，小縣百餘頃，宅亦如之。於是商賈中家以上大氐破，民媮甘食好衣，不事畜臧之業，〔五〕而縣官以鹽鐵緍錢之故，用少饒矣。益廣（開）〔關〕，置左右輔。","sentenceOrder":203},
  {"id":"s_work_han_thu_29_204","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　如淳曰：「告緍令楊可所告言也。」師古曰：「此說非也。楊可據令而發動之，故天下皆被告。」","sentenceOrder":204},
  {"id":"s_work_han_thu_29_205","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　如淳曰：「治匿緍之罪，其獄少有反者。」蘇林曰：「反音幡。」師古曰：「幡謂從輕而出。」","sentenceOrder":205},
  {"id":"s_work_han_thu_29_206","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　服虔曰：「分曹職案行也。」師古曰：「服說非也。曹，輩也，分輩而出為使也。」","sentenceOrder":206},
  {"id":"s_work_han_thu_29_207","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　師古曰：「就其所在而治也。」","sentenceOrder":207},
  {"id":"s_work_han_thu_29_208","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　師古曰：「媮，苟且也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_29_209","chapterId":"ch_work_han_thu_29","textTraditional":"初，大農（幹）〔斡〕鹽鐵官布多，置水衡，欲以主鹽鐵；及楊可告緍，上林財物眾，乃令水衡主上林。上林既充滿，益廣。是時粵欲與漢用船戰逐，〔一〕乃大修昆明池，列館環之。〔二〕治樓船，高十餘丈，旗織加其上，〔三〕甚壯。於是天子感之，乃作柏梁臺，高數十丈。宮室之修，繇此日麗。","sentenceOrder":209},
  {"id":"s_work_han_thu_29_210","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　孟康曰：「水戰相逐也。」","sentenceOrder":210},
  {"id":"s_work_han_thu_29_211","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「環，繞也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_29_212","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「織讀曰（熾）〔幟〕，音昌志反。」","sentenceOrder":212},
  {"id":"s_work_han_thu_29_213","chapterId":"ch_work_han_thu_29","textTraditional":"乃分緍錢諸官，而水衡、少府、太僕、大農各置農官，往往即郡縣比沒入田田之。〔一〕其沒入奴婢，分諸苑養狗馬禽獸，及與諸官。官益雜置多，〔二〕徒奴婢眾，而下河漕度四百萬石，及官自糴乃足。〔三〕","sentenceOrder":213},
  {"id":"s_work_han_thu_29_214","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「即，就也。比謂比者所沒入也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_29_215","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　如淳曰：「水衡、少府、太僕、司農皆有農官，是為多也。」師古曰：「此說非也。謂雜置官員分掌眾事耳，非農官也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_29_216","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「度，計也，音大各反。」","sentenceOrder":216},
  {"id":"s_work_han_thu_29_217","chapterId":"ch_work_han_thu_29","textTraditional":"所忠言：「世家子弟富人或鬥雞走狗馬，弋獵博戲，亂齊民。」〔一〕乃徵諸犯令，相引數千人，名曰「株送徒」。入財者得補郎，郎選衰矣。〔二〕","sentenceOrder":217},
  {"id":"s_work_han_thu_29_218","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　如淳曰：「世家，謂世世有祿秩家也。齊，等也。無有貴賤，謂之齊民，若今言平民矣。」晉灼曰：「中國被教齊整之民也。」師古曰：「所，姓也，忠，名也，武帝之近臣。郊祀志云『公孫卿因所忠言寶鼎』，石慶傳云『欲請詔近臣所忠』，廣川王傳云『言漢公卿及幸臣所忠』，司馬相如傳云『所忠往取書』。考其蹤跡，此並一人也。而說者或以為所忠信之人，此釋大謬。齊等之義，如說是也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_29_219","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　應劭曰：「株，根本也。送，致也。」如淳曰：「株，蔕也。諸坐博戲事決為徒者，能入錢，得補郎。」李奇曰：「先至者為魁株也。」師古曰：「言被牽引者為其根株所送當充徒役，而能入財者，即當補郎。」","sentenceOrder":219},
  {"id":"s_work_han_thu_29_220","chapterId":"ch_work_han_thu_29","textTraditional":"是時山東被河災，及歲不登數年，人或相食，方二三千里。天子憐之，令飢民得流就食江淮間，欲留，留處。〔一〕使者冠蓋相屬於道護之，〔二〕下巴蜀粟以振焉。","sentenceOrder":220},
  {"id":"s_work_han_thu_29_221","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「流謂恣其行移，若水之流。至所在，有欲（往）〔住〕者，亦留而處（之）〔也〕。」","sentenceOrder":221},
  {"id":"s_work_han_thu_29_222","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「屬，聯續也，音之欲反。」","sentenceOrder":222},
  {"id":"s_work_han_thu_29_223","chapterId":"ch_work_han_thu_29","textTraditional":"明年，天子始出巡郡國。東度河，河東守不意行至，不辯，自殺。行西踰隴，卒，〔一〕從官不得食，隴西守自殺。於是上北出蕭關，從數萬騎行獵新秦中，以勒邊兵而歸。新秦中或千里無亭徼，〔二〕於是誅北地太守以下，而令民得畜邊縣，〔三〕官假馬母，三歲而歸，及息什一，以除告緍，用充入新秦中。〔四〕","sentenceOrder":223},
  {"id":"s_work_han_thu_29_224","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　孟康曰：「踰，度也。卒，倉卒也。」","sentenceOrder":224},
  {"id":"s_work_han_thu_29_225","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　晉灼曰：「徼，塞也。」臣瓚曰：「既無亭候，又不徼循，無禦邊之備，故誅北地太守。」師古曰：「晉說是也。」","sentenceOrder":225},
  {"id":"s_work_han_thu_29_226","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　孟康曰：「令得畜牧於邊縣。」","sentenceOrder":226},
  {"id":"s_work_han_thu_29_227","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　李奇曰：「邊有官馬，今令民能畜官母馬者，滿三歲歸之，十母馬還官一駒，此為息什一也。」師古曰：「官得母馬之息，以給用度，得充實秦中人，故除告緍之令也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_29_228","chapterId":"ch_work_han_thu_29","textTraditional":"既得寶鼎，立后土、泰一祠，公卿白議封禪事，而郡國皆豫治道，修繕故宮，及當馳道縣，縣治宮儲，設共具，〔一〕而望幸。","sentenceOrder":228},
  {"id":"s_work_han_thu_29_229","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「共音居用反。」","sentenceOrder":229},
  {"id":"s_work_han_thu_29_230","chapterId":"ch_work_han_thu_29","textTraditional":"明年，南粵反，西羌侵邊。天子為山東不澹，赦天下囚，因南方樓船士二十餘萬人擊粵，發三河以西騎擊羌，又數萬人度河築令居。〔一〕初置張掖、酒泉郡，而上郡、朔方、西河、河西開田官，斥塞卒六十萬人戍田之。〔二〕中國繕道餽糧，遠者三千，近者千餘里，皆仰給大農。〔三〕邊兵不足，乃發武庫工官兵器以澹之。車騎馬乏，縣官錢少，買馬難得，乃著令，令封君以下至三百石吏以上差出（牡）〔牝〕馬天下亭，亭有畜字馬，歲課息。","sentenceOrder":230},
  {"id":"s_work_han_thu_29_231","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「令音零。」","sentenceOrder":231},
  {"id":"s_work_han_thu_29_232","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「開田，始開屯田也。斥塞，廣塞令卻。初置二郡，故塞更廣也。以開田之官廣塞之卒戍而田也。」","sentenceOrder":232},
  {"id":"s_work_han_thu_29_233","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「仰音牛向反。此下並同。」","sentenceOrder":233},
  {"id":"s_work_han_thu_29_234","chapterId":"ch_work_han_thu_29","textTraditional":"齊相卜式上書，願父子死南粵。天子下詔褒揚，賜爵關內侯，黃金四十斤，田十頃。布告天下，天下莫應。列侯以百數，皆莫求從軍。至飲酎，少府省金，〔一〕而列侯坐酎金失侯者百餘人。乃拜卜式為御史大夫。式既在位，見郡國多不便縣官作鹽鐵，器苦惡，〔二〕賈貴，〔三〕或彊令民買之。而船有算，商者少，物貴，乃因孔僅言船算事。上不說。〔四〕","sentenceOrder":234},
  {"id":"s_work_han_thu_29_235","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　李奇曰：「省，視也。至嘗酎飲宗廟時，少府視其金多少。」","sentenceOrder":235},
  {"id":"s_work_han_thu_29_236","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　如淳曰：「苦或作盬。盬，不攻嚴也。」臣瓚曰：「謂作鐵器，民患苦其不好也。」師古曰：「二說非也。鹽既味苦，器又脆惡，故總云苦惡也。」","sentenceOrder":236},
  {"id":"s_work_han_thu_29_237","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「鹽鐵並貴也。賈讀曰價。」","sentenceOrder":237},
  {"id":"s_work_han_thu_29_238","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　師古曰：「說音悅。」","sentenceOrder":238},
  {"id":"s_work_han_thu_29_239","chapterId":"ch_work_han_thu_29","textTraditional":"漢連出兵三歲，誅羌，滅兩粵，番禺以西至蜀南者置初郡十七，〔一〕且以其故俗治，無賦稅。南陽、漢中以往，各以地比給初郡吏卒奉食幣物，傳車馬被具。〔二〕而初郡又時時小反，殺吏，漢發南方吏卒往誅之，間歲萬餘人，〔三〕費皆仰大農。大農以均輸調鹽鐵助賦，故能澹之。然兵所過縣，縣以為訾給毋乏而已，不敢言輕賦法矣。","sentenceOrder":239},
  {"id":"s_work_han_thu_29_240","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　晉灼曰：「元鼎六年定越地以為南海、蒼梧、鬱林、合浦、交趾、九真、日南、珠厓、儋耳郡，定西南夷以為武都、牂柯、越嶲、沈黎、汶山郡，及地理志、西南夷傳所置犍為、零陵、益州郡，凡十七。」","sentenceOrder":240},
  {"id":"s_work_han_thu_29_241","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「地比，謂依其次第，自近及遠也。比音頻寐反。傳音張戀反。被音皮義反。」","sentenceOrder":241},
  {"id":"s_work_han_thu_29_242","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「間歲，隔一歲。」","sentenceOrder":242},
  {"id":"s_work_han_thu_29_243","chapterId":"ch_work_han_thu_29","textTraditional":"其明年，元封元年，卜式貶為太子太傅。而桑弘羊為治粟都尉，領大農，盡代僅斡天下鹽鐵。〔一〕弘羊以諸官各自市相爭，物以故騰躍，而天下賦輸或不償其僦費，〔二〕乃請置大農部丞數十人，分部主郡國，各往往置均輸鹽鐵官，令遠方各以其物如異時商賈所轉（貶）〔販〕者為賦，而相灌輸。置平準於京師，都受天下委輸。召工官治車諸器，皆仰給大農。大農諸官盡籠天下之貨物，貴則賣之，賤則買之。如此，富商大賈亡所牟大利，〔三〕則反本，而萬物不得騰躍。故抑天下之物，名曰「平準」。天子以為然而許之。於是天子北至朔方，東封泰山，巡海上，旁北邊以歸。〔四〕所過賞賜，用帛百餘萬匹，錢金以鉅萬計，皆取足大農。","sentenceOrder":243},
  {"id":"s_work_han_thu_29_244","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「代孔僅。」","sentenceOrder":244},
  {"id":"s_work_han_thu_29_245","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「僦，顧也，言所輸賦物不足償其餘顧庸之費也。僦音子就反。」","sentenceOrder":245},
  {"id":"s_work_han_thu_29_246","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　如淳曰：「牟，取也。」","sentenceOrder":246},
  {"id":"s_work_han_thu_29_247","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　師古曰：「旁音步浪反。」","sentenceOrder":247},
  {"id":"s_work_han_thu_29_248","chapterId":"ch_work_han_thu_29","textTraditional":"弘羊又請令民得入粟補吏，及罪以贖。令民入粟甘泉各有差，以復終身，〔一〕不復告緍。它郡各輸急處，而諸農各致粟，山東漕益歲六百萬石。一歲之中，太倉、甘泉倉滿。邊餘穀，諸均輸帛五百萬匹。民不益賦而天下用饒。於是弘羊賜爵左庶長，〔二〕黃金者再百焉。〔三〕","sentenceOrder":248},
  {"id":"s_work_han_thu_29_249","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「復音方目反。」","sentenceOrder":249},
  {"id":"s_work_han_thu_29_250","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「第十等爵。」","sentenceOrder":250},
  {"id":"s_work_han_thu_29_251","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「凡再賜百金。」","sentenceOrder":251},
  {"id":"s_work_han_thu_29_252","chapterId":"ch_work_han_thu_29","textTraditional":"是歲小旱，上令百官求雨。卜式言曰：「縣官當食租衣稅而已，〔一〕今弘羊令吏坐市列，販物求利。〔二〕亨弘羊，天乃雨。〔三〕」久之，武帝疾病，拜弘羊為御史大夫。","sentenceOrder":252},
  {"id":"s_work_han_thu_29_253","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「衣音於既反。」","sentenceOrder":253},
  {"id":"s_work_han_thu_29_254","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「市列，謂列肆。」","sentenceOrder":254},
  {"id":"s_work_han_thu_29_255","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「亨，鬻也，音普庚反。」","sentenceOrder":255},
  {"id":"s_work_han_thu_29_256","chapterId":"ch_work_han_thu_29","textTraditional":"昭帝即位六年，詔郡國舉賢良文學之士，問以民所疾苦，教化之要。皆對願罷鹽鐵酒（〈木寉〉）〔榷〕均輸官，毋與天下爭利，視以儉節，〔一〕然後教化可興。弘羊難，〔二〕以為此國家大業，所以制四夷，安邊足用之本，不可廢也。乃與丞相千秋共奏罷酒酤。弘羊自以為國興大利，伐其功，欲為子弟得官，怨望大將軍霍光，遂與上官桀等謀反，誅滅。","sentenceOrder":256},
  {"id":"s_work_han_thu_29_257","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「視讀曰示。」","sentenceOrder":257},
  {"id":"s_work_han_thu_29_258","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「詰難議者之言也。」","sentenceOrder":258},
  {"id":"s_work_han_thu_29_259","chapterId":"ch_work_han_thu_29","textTraditional":"宣、元、成、哀、平五世，亡所變改。元帝時嘗罷鹽鐵官，三年而復之。貢禹言：「鑄錢采銅，一歲十萬人不耕，民坐盜鑄陷刑者多。富人臧錢滿室，猶無厭足。民心動搖，棄本逐末，耕者不能半，姦邪不可禁，原起於錢。疾其末者絕其本，宜罷采珠玉金銀鑄錢之官，毋復以為幣，除其販賣租銖之律，〔一〕租稅祿賜皆以布帛及穀，使百姓壹意農桑。」議者以為交易待錢，布帛不可尺寸分裂。禹議亦寢。","sentenceOrder":259},
  {"id":"s_work_han_thu_29_260","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「租銖，謂計其所賣物價，平其錙銖而收租也。」","sentenceOrder":260},
  {"id":"s_work_han_thu_29_261","chapterId":"ch_work_han_thu_29","textTraditional":"自孝武元狩五年三官初鑄五銖錢，至平帝元始中，成錢二百八十億萬餘云。","sentenceOrder":261},
  {"id":"s_work_han_thu_29_262","chapterId":"ch_work_han_thu_29","textTraditional":"王莽居攝，變漢制，以周錢有子母相權，於是更造大錢，徑寸二分，重十二銖，文曰「大錢五十」。又造契刀、錯刀。契刀，其環如大錢，身形如刀，長二寸，文曰「契刀五百」。錯刀，以黃金錯其文，曰「一刀直五千」。〔一〕與五銖錢凡四品，並行。","sentenceOrder":262},
  {"id":"s_work_han_thu_29_263","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　張晏曰：「案今所見契刀、錯刀，形質如大錢，而肉好輪厚異於此。大錢形如大刀環矣，契刀身形圓，不長二寸也。其文左曰『契』，右曰『刀』，無『五百』字也。錯刀則刻之作字也，以黃金填其文，上曰『一』，下曰『刀』。二刀泉甚不與志相應也，似扎單差錯，文字磨滅故耳。」師古曰：「張說非也。王莽錢刀今並尚在，形質及文與志相合，無差錯也。」","sentenceOrder":263},
  {"id":"s_work_han_thu_29_264","chapterId":"ch_work_han_thu_29","textTraditional":"莽即真，以為書「劉」字有金刀，乃罷錯刀、契刀及五銖錢，而更作金、銀、龜、貝、錢、布之品，名曰「寶貨」。","sentenceOrder":264},
  {"id":"s_work_han_thu_29_265","chapterId":"ch_work_han_thu_29","textTraditional":"小錢徑六分，重一銖，文曰「小錢直一」。次七分，三銖，曰「錢一十」。〔一〕次八分，五銖，曰「幼錢二十」。次九分，七銖，曰「中錢三十」。次一寸，九銖，曰「壯錢四十」。因前「大錢五十」，是為錢貨六品，直各如其文。","sentenceOrder":265},
  {"id":"s_work_han_thu_29_266","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「幺，小也，音一堯反。」","sentenceOrder":266},
  {"id":"s_work_han_thu_29_267","chapterId":"ch_work_han_thu_29","textTraditional":"黃金重一斤，直錢萬。朱提銀重八兩為一流，直一千五百八十。〔一〕它銀一流直千。是為銀貨二品。","sentenceOrder":267},
  {"id":"s_work_han_thu_29_268","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「朱提，縣名，屬犍為，出善銀。朱音殊。提音上支反。」","sentenceOrder":268},
  {"id":"s_work_han_thu_29_269","chapterId":"ch_work_han_thu_29","textTraditional":"元龜岠冉長尺二寸，〔一〕直二千一百六十，為大貝十朋。〔二〕公龜九寸，直五百，為壯貝十朋。侯龜七寸以上，直三百，為幺貝十朋。子龜五寸以上，直百，為小貝十朋。是為龜寶四品。","sentenceOrder":269},
  {"id":"s_work_han_thu_29_270","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　孟康曰：「冉，龜甲緣也。岠，至也。度背兩邊緣尺二寸也。」臣瓚曰：「元，大也。」","sentenceOrder":270},
  {"id":"s_work_han_thu_29_271","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　蘇林曰：「兩貝為朋。朋直二百一十六，元龜十朋，故二千一百六十也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_29_272","chapterId":"ch_work_han_thu_29","textTraditional":"大貝四寸八分以上，二枚為一朋，直二百一十六。壯貝三寸六分以上，二枚為一朋，直五十。幺貝二寸四分以上，二枚為一朋，直三十。小貝寸二分以上，二枚為一朋，直十。不盈寸二分，漏度不得為朋，率枚直錢三。是為貝貨五品。","sentenceOrder":272},
  {"id":"s_work_han_thu_29_273","chapterId":"ch_work_han_thu_29","textTraditional":"大布、次布、弟布、壯布、中布、差布、厚布、幼布、幺布、小布。小布長寸五分，重十五銖，文曰「小布一百」。自小布以上，各相長一分，相重一銖，文各為其布名，直各加一百。上至大布，長二寸四分，重一兩，而直千錢矣。是為布貨十品。〔一〕","sentenceOrder":273},
  {"id":"s_work_han_thu_29_274","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「布亦錢耳。謂之布者，言其分布流行也。」","sentenceOrder":274},
  {"id":"s_work_han_thu_29_275","chapterId":"ch_work_han_thu_29","textTraditional":"凡寶貨五物，六名，二十八品。","sentenceOrder":275},
  {"id":"s_work_han_thu_29_276","chapterId":"ch_work_han_thu_29","textTraditional":"鑄作錢布皆用銅，殽以連錫，〔一〕文質周郭放漢五銖錢云〔二〕。其金銀與它物雜，色不純好，龜不盈五寸，貝不盈六分，皆不得為寶貨。元龜為蔡，非四民所得居，〔三〕有者，入大卜受直。","sentenceOrder":276},
  {"id":"s_work_han_thu_29_277","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　孟康曰：「連，錫之別名也。」李奇曰：「鉛錫璞名曰連。」應劭曰：「連似銅。」師古曰：「孟、李二說皆非也。許慎云『鏈，銅屬也』，然則以連及錫雜銅而為錢也。此下又云能采金銀銅連錫，益知連非錫矣。」","sentenceOrder":277},
  {"id":"s_work_han_thu_29_278","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「放，依也，音甫往反。」","sentenceOrder":278},
  {"id":"s_work_han_thu_29_279","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　如淳曰：「臧文仲居蔡，謂此也，說謂蔡國出大龜也。」臣瓚曰：「蔡是大龜之名也。書曰『九江納錫大龜』，大龜又不出蔡國也。若龜出楚，不可名龜為楚也。」師古曰：「瓚說非也。本以蔡出善龜，故因名大龜為蔡耳。」","sentenceOrder":279},
  {"id":"s_work_han_thu_29_280","chapterId":"ch_work_han_thu_29","textTraditional":"百姓憒亂，其貨不行。民私以五銖錢市買。莽患之，下詔：「敢非井田挾五銖錢者為惑眾，投諸四裔以御魑魅。」於是農商失業，食貨俱廢，民涕泣於市道。坐賣買田宅奴婢鑄錢抵罪者，自公卿大夫至庶人，不可稱數。莽知民愁，乃但行小錢直一，與大錢五十，二品並行，龜貝布屬且寢。","sentenceOrder":280},
  {"id":"s_work_han_thu_29_281","chapterId":"ch_work_han_thu_29","textTraditional":"莽性躁擾，不能無為，每有所興造，必欲依古得經文。國師公劉歆言周有泉府之官，收不讎，與欲得，〔一〕即易所謂「理財正辭，禁民為非」者也。〔二〕莽乃下詔曰：「夫周禮有賒貸，〔三〕樂語有五均，〔四〕傳記各有斡焉。今開賒貸，張五均，設諸斡者，所以齊眾庶，抑并兼也。」遂於長安及五都立五均官，更名長安東西市令及洛陽、邯鄲、臨甾、宛、成都市長皆為五均司市（稱）師。東市稱京，西市稱畿，洛陽稱中，餘四都各用東西南北為稱，皆置交易丞五人，錢府丞一人。工商能采金銀銅連錫登龜取貝者，〔五〕皆自占司市錢府，順時氣而取之。〔六〕","sentenceOrder":281},
  {"id":"s_work_han_thu_29_282","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「讎讀曰售。言賣不售者，官收取之；無而欲得者，官出與之。」","sentenceOrder":282},
  {"id":"s_work_han_thu_29_283","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「易下繫辭曰：『理財正辭，禁人為非曰義。』言財貨辭訟正，乃得人不為非，合事宜。」","sentenceOrder":283},
  {"id":"s_work_han_thu_29_284","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「周禮泉府之職曰：『凡賒者，祭祀無過旬日，喪紀無過三月。凡人之貸者，與其有司辨而授之，以國服為之息。』謂人以祭祀、喪紀故從官賒買物，不過旬日及三月而償之。其從官貸物者，以共其所屬吏定價而後與之。各以其國服事之稅而輸息，謂若受園廛之田而貸萬錢者，一期之月，出息五百。貸音土戴反。」","sentenceOrder":284},
  {"id":"s_work_han_thu_29_285","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　鄧展曰：「樂語，樂元語，河間獻王所傳，道五均事。」臣瓚曰：「其文云：『天子取諸侯之（士）〔土〕以立五均，則市無二賈，四民常均，彊者不得困弱，富者不得要貧，則公家有餘，恩及小民矣。』」","sentenceOrder":285},
  {"id":"s_work_han_thu_29_286","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　如淳曰：「登，進也。龜有靈，故言登。」","sentenceOrder":286},
  {"id":"s_work_han_thu_29_287","chapterId":"ch_work_han_thu_29","textTraditional":"〔六〕　師古曰：「各以其所采取之物自隱實於司市錢府也。占音之漸反。其下並同。」","sentenceOrder":287},
  {"id":"s_work_han_thu_29_288","chapterId":"ch_work_han_thu_29","textTraditional":"又以周官稅民：凡田不耕為不殖，出三夫之稅；城郭中宅不樹藝者為不毛，〔一〕出三夫之布；民浮游無事，出夫布一匹。其不能出布者，宂作，縣官衣食之。〔二〕諸取眾物鳥獸魚鱉百蟲於山林水澤及畜牧者，嬪婦桑蠶織紝紡績補縫，〔三〕工匠醫巫卜祝及它方技商販賈人坐肆列里區謁舍，〔四〕皆各自占所為於其在所之縣官，除其本，計其利，十一分之，而以其一為貢。敢不自占，自占不以實者，盡沒入所采取，而作縣官一歲。","sentenceOrder":288},
  {"id":"s_work_han_thu_29_289","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「樹藝，謂種樹果木及菜蔬。」","sentenceOrder":289},
  {"id":"s_work_han_thu_29_290","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「宂，散也，音人勇反。衣音於既反。食謂曰飤。」","sentenceOrder":290},
  {"id":"s_work_han_thu_29_291","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「機縷曰紝，音人禁反。」","sentenceOrder":291},
  {"id":"s_work_han_thu_29_292","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　如淳曰：「居處所在為區。謁舍，今之客舍也。」","sentenceOrder":292},
  {"id":"s_work_han_thu_29_293","chapterId":"ch_work_han_thu_29","textTraditional":"諸司市常以四時中月實定所掌，〔一〕為物上中下之賈，〔二〕各自用為其市平，毋拘它所。眾民賣買五穀布帛絲綿之物，周於民用而不讎者，〔三〕均官有以考檢厥實，用其本賈取之，毋令折錢〔四〕。萬物卬貴，過平一錢，則以平賈賣與民。〔五〕其賈氐賤減平者，聽民自相與市，〔六〕以防貴庾者。〔七〕民欲祭祀喪紀而無用者，錢府以所入工商之貢但賒之，〔八〕祭祀無過旬日，喪紀毋過三月。民或乏絕，欲貸以治產業者，均授之，除其費，計所得受息，毋過歲什一。〔九〕","sentenceOrder":293},
  {"id":"s_work_han_thu_29_294","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「中讀曰仲。」","sentenceOrder":294},
  {"id":"s_work_han_thu_29_295","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「賈讀曰價。其下並同。」","sentenceOrder":295},
  {"id":"s_work_han_thu_29_296","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「讎讀曰售。下亦類此也。」","sentenceOrder":296},
  {"id":"s_work_han_thu_29_297","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　師古曰：「折音上列反。」","sentenceOrder":297},
  {"id":"s_work_han_thu_29_298","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　師古曰：「卬，物價起，音五剛反，亦讀曰仰。」","sentenceOrder":298},
  {"id":"s_work_han_thu_29_299","chapterId":"ch_work_han_thu_29","textTraditional":"〔六〕　師古曰：「貴（既）〔即〕為卬。賤則為氐，音丁奚反。」","sentenceOrder":299},
  {"id":"s_work_han_thu_29_300","chapterId":"ch_work_han_thu_29","textTraditional":"〔七〕　師古曰：「庾，積也。以防民積物待貴也。」","sentenceOrder":300},
  {"id":"s_work_han_thu_29_301","chapterId":"ch_work_han_thu_29","textTraditional":"〔八〕　師古曰：「但，空也，徒也。言空賒與之，不取息利也。」","sentenceOrder":301},
  {"id":"s_work_han_thu_29_302","chapterId":"ch_work_han_thu_29","textTraditional":"〔九〕　師古曰：「均謂各依先後之次。除其費，謂衣食之費已用者也。」","sentenceOrder":302},
  {"id":"s_work_han_thu_29_303","chapterId":"ch_work_han_thu_29","textTraditional":"羲和魯匡言：「名山大澤，鹽鐵錢布帛，五均賒貸，斡在縣官，〔一〕唯酒酤獨未斡。酒者，天之美祿，帝王所以頤養天下，享祀祈福，扶衰養疾。百禮之會，非酒不行。故詩曰『無酒酤我』，〔二〕而論語曰『酤酒不食』，〔三〕二者非相反也。夫詩據承平之世，酒酤在官，和旨便人，可以相御也。〔四〕論語孔子當周衰亂，酒酤在民，薄惡不誠，是以疑而弗食。今絕天下之酒，則無以行禮相養；放而亡限，則費財傷民。請法古，令官作酒，以二千五百石為一均，率開一盧以賣，〔五〕讎五十釀為準。一釀用麤米二斛，麴一斛，得成酒六斛六斗。各以其市月朔米麴三斛，并計其賈而參分之，〔六〕以其一為酒一斛之平。除米麴本賈，計其利而什分之，以其七入官，其三及醩酨灰炭〔七〕給工器薪樵之費。」","sentenceOrder":303},
  {"id":"s_work_han_thu_29_304","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「斡謂主領也。」","sentenceOrder":304},
  {"id":"s_work_han_thu_29_305","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「小雅伐木之詩也。酤，買也。言王於族人恩厚，要在燕飫，無酒則買而飲之。」","sentenceOrder":305},
  {"id":"s_work_han_thu_29_306","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「鄉黨所說孔子齊之時也。」","sentenceOrder":306},
  {"id":"s_work_han_thu_29_307","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　師古曰：「旨，美也。御，進。」","sentenceOrder":307},
  {"id":"s_work_han_thu_29_308","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　如淳曰：「酒家開肆待客，設酒罏，故以罏名肆。」臣瓚曰：「盧，酒瓮也。言開一瓮酒也。趙廣漢入丞相府破盧瓮。」師古曰：「二說皆非也。盧者，賣酒之區也，以其一邊高，形如鍛家盧，故取名耳，非即謂火盧及酒瓮也。此言讎五十釀為準，豈一瓮乎？廣漢所破盧及罌盧，亦謂所居罌瓮之處耳。」","sentenceOrder":308},
  {"id":"s_work_han_thu_29_309","chapterId":"ch_work_han_thu_29","textTraditional":"〔六〕　師古曰：「參，三也。」","sentenceOrder":309},
  {"id":"s_work_han_thu_29_310","chapterId":"ch_work_han_thu_29","textTraditional":"〔七〕　師古曰：「酨，酢漿也，音才代反。」","sentenceOrder":310},
  {"id":"s_work_han_thu_29_311","chapterId":"ch_work_han_thu_29","textTraditional":"羲和置命士督五均六斡，郡有數人，皆用富賈。洛陽薛子仲、張長叔、臨菑姓偉等，〔一〕乘傳求利，交錯天下。〔二〕因與郡縣通姦，多張空簿，〔三〕府臧不實，百姓俞病。莽知民苦之，復下詔曰：「夫鹽，食肴之將；〔四〕酒，百藥之長，嘉會之好；鐵，（曰）〔田〕農之本；名山大澤，饒衍之臧；五均賒貸，百姓所取平，卬以給澹；〔五〕鐵布銅冶，通行有無，備民用也。此六者，非編戶齊民所能家作，〔六〕必卬於市，雖貴數倍，不得不買。豪民富賈，即要貧弱，先聖知其然也，故斡之。每一斡為設科條防禁，犯者罪至死。」姦吏猾民並侵，眾庶各不安生。","sentenceOrder":311},
  {"id":"s_work_han_thu_29_312","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　如淳曰：「姓姓名偉也。」","sentenceOrder":312},
  {"id":"s_work_han_thu_29_313","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「傳音張戀反。」","sentenceOrder":313},
  {"id":"s_work_han_thu_29_314","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「簿，計簿也，音步戶反。」","sentenceOrder":314},
  {"id":"s_work_han_thu_29_315","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　師古曰：「將，大也，一說為食肴之將帥。」","sentenceOrder":315},
  {"id":"s_work_han_thu_29_316","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　師古曰：「卬音牛向反。其下並同。」","sentenceOrder":316},
  {"id":"s_work_han_thu_29_317","chapterId":"ch_work_han_thu_29","textTraditional":"〔六〕　師古曰：「家謂家家自作也。」","sentenceOrder":317},
  {"id":"s_work_han_thu_29_318","chapterId":"ch_work_han_thu_29","textTraditional":"後五歲，天鳳元年，復申下金銀龜貝之貨，頗增減其賈直。而罷大小錢，改作貨布，長二寸五分，廣一寸，首長八分有奇，〔一〕廣八分，其圜好徑二分半，〔二〕足枝長八分，間廣二分，其文右曰「貨」，左曰「布」，重二十五銖，直貨泉二十五。貨泉徑一寸，重五銖，文右曰「貨」，左曰「泉」，枚直一，與貨布二品並行。又以大錢行久，罷之，恐民挾不止，乃令民且獨行大錢，與新貨泉俱枚直一，並行盡六年，毋得復挾大錢矣。每壹易錢，民用破業，而大陷刑。莽以私鑄錢死，及非沮寶貨投四裔，犯法者多，不可勝行，乃更輕其法：私鑄作泉布者，與妻子沒入為官奴婢；吏及比伍，知而不舉告，與同罪；〔三〕非沮寶貨，民罰作一歲，吏免官。犯者俞眾，及五人相坐皆沒入，郡國檻車鐵鎖，傳送長安鍾官，〔四〕愁苦死者什六七。","sentenceOrder":318},
  {"id":"s_work_han_thu_29_319","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「奇音居宜反，謂有餘也。」","sentenceOrder":319},
  {"id":"s_work_han_thu_29_320","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「好，孔也。」","sentenceOrder":320},
  {"id":"s_work_han_thu_29_321","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「比音頻寐反。」","sentenceOrder":321},
  {"id":"s_work_han_thu_29_322","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　師古曰：「鍾官，主鑄錢者。」","sentenceOrder":322},
  {"id":"s_work_han_thu_29_323","chapterId":"ch_work_han_thu_29","textTraditional":"作貨布六年後，匈奴侵寇甚，莽大募天下囚徒人奴，名曰豬突豨勇，〔一〕壹切稅吏民，訾三十而取一。又令公卿以下至郡縣黃綬吏，皆保養軍馬，吏盡復以與民。〔三〕民搖手觸禁，不得耕桑，繇役煩劇，〔四〕而枯旱蝗蟲相因。又用制作未定，上自公侯，下至小吏，皆不得奉祿，而私賦斂，貨賂上流，獄訟不決。吏用苛暴立威，旁緣莽禁，侵刻小民。〔五〕富者不得自保，貧者無以自存，起為盜賊，依阻山澤，吏不能禽而覆蔽之，浸淫日廣，〔六〕於是青、徐、荊楚之地往往萬數。戰鬥死亡，緣邊四夷所係虜，陷罪，飢疫，人相食，及莽未誅，而天下戶口減半矣。","sentenceOrder":323},
  {"id":"s_work_han_thu_29_324","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　服虔曰：「豬性觸突人，故取以喻。」師古曰：「東方名豕曰豨。一曰，豨，豕走也，音許豈反。」","sentenceOrder":324},
  {"id":"s_work_han_thu_29_325","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　師古曰：「保者，不許其死傷。」","sentenceOrder":325},
  {"id":"s_work_han_thu_29_326","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「轉令百姓養之。」","sentenceOrder":326},
  {"id":"s_work_han_thu_29_327","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　師古曰：「繇讀曰傜也。」","sentenceOrder":327},
  {"id":"s_work_han_thu_29_328","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　師古曰：「旁，依也，音步浪反。」","sentenceOrder":328},
  {"id":"s_work_han_thu_29_329","chapterId":"ch_work_han_thu_29","textTraditional":"〔六〕　師古曰：「浸淫，猶漸染也。它皆類此。」","sentenceOrder":329},
  {"id":"s_work_han_thu_29_330","chapterId":"ch_work_han_thu_29","textTraditional":"自發豬突豨勇後四年，而漢兵誅莽。後二年，世祖受命，盪滌煩苛，復五銖錢，與天下更始。","sentenceOrder":330},
  {"id":"s_work_han_thu_29_331","chapterId":"ch_work_han_thu_29","textTraditional":"贊曰：易稱「裒多益寡，稱物平施」，〔一〕書云「楙遷有無」，〔二〕周有泉府之官，〔三〕而孟子亦非「狗彘食人之食不知斂，〔四〕野有餓〈菜，中“木改又”〉而弗知發」。〔五〕故管氏之輕重，〔六〕李悝之平糴，弘羊均輸，壽昌常平，亦有從徠。〔七〕顧古為之有數，吏良而令行，〔八〕故民賴其利，萬國作乂。〔九〕及孝武時，國用饒給，而民不益賦，其次也。至于王莽，制度失中，姦軌弄權，官民俱竭，亡次矣。","sentenceOrder":331},
  {"id":"s_work_han_thu_29_332","chapterId":"ch_work_han_thu_29","textTraditional":"〔一〕　師古曰：「謙卦象辭。裒，取也。言取於多者以益少者，故萬物皆稱而施與平也。裒音薄侯反。」","sentenceOrder":332},
  {"id":"s_work_han_thu_29_333","chapterId":"ch_work_han_thu_29","textTraditional":"〔二〕　應劭曰：「楙，勉也。遷，徙也。言天下食貨有無相通足也。」師古曰：「虞書益稷之辭。言勸勉天下遷徙有無，使相通也。」","sentenceOrder":333},
  {"id":"s_work_han_thu_29_334","chapterId":"ch_work_han_thu_29","textTraditional":"〔三〕　師古曰：「司徒之屬官也，掌市之征布，斂市貨之不讎，貨之滯於人用者，以其價買之。」","sentenceOrder":334},
  {"id":"s_work_han_thu_29_335","chapterId":"ch_work_han_thu_29","textTraditional":"〔四〕　應劭曰：「養狗彘者使食人之食，而不知以法度斂之也。」師古曰：「孟子，孟軻之書。言歲豐孰，菽粟饒多，狗彘食人之食，此時可斂之也。」","sentenceOrder":335},
  {"id":"s_work_han_thu_29_336","chapterId":"ch_work_han_thu_29","textTraditional":"〔五〕　鄭氏曰：「〈菜，中“木改又”〉音『蔈有梅』之蔈。〈菜，中“木改又”〉，零落也。人有餓死零落者，不知發倉廩貸之也。」師古曰：「〈菜，中“木改又”〉音頻小反。諸書或作殍字，音義亦同。」","sentenceOrder":336},
  {"id":"s_work_han_thu_29_337","chapterId":"ch_work_han_thu_29","textTraditional":"〔六〕　服虔曰：「作輕重貨，在管子書。」","sentenceOrder":337},
  {"id":"s_work_han_thu_29_338","chapterId":"ch_work_han_thu_29","textTraditional":"〔七〕　師古曰：「言所從徠久矣。」","sentenceOrder":338},
  {"id":"s_work_han_thu_29_339","chapterId":"ch_work_han_thu_29","textTraditional":"〔八〕　師古曰：「顧，思念。」","sentenceOrder":339},
  {"id":"s_work_han_thu_29_340","chapterId":"ch_work_han_thu_29","textTraditional":"〔九〕　師古曰：「乂，治也。」","sentenceOrder":340},
  {"id":"s_work_han_thu_29_341","chapterId":"ch_work_han_thu_29","textTraditional":"校勘記","sentenceOrder":341},
  {"id":"s_work_han_thu_29_342","chapterId":"ch_work_han_thu_29","textTraditional":"一一五０頁　五行　則準平。〔守準平〕，　王念孫說景祐本「則準平」下有「守準平」三字，是也。","sentenceOrder":342},
  {"id":"s_work_han_thu_29_343","chapterId":"ch_work_han_thu_29","textTraditional":"一一五０頁一五行　凶（戾）〔歲〕糴，釜十繈。　景祐、殿本都作「歲」。王先謙說作「歲」是。","sentenceOrder":343},
  {"id":"s_work_han_thu_29_344","chapterId":"ch_work_han_thu_29","textTraditional":"一一五二頁　六行　謂去其本居而散（忘）〔亡〕也。　景祐、殿本都作「亡」。王先謙說作「亡」是。","sentenceOrder":344},
  {"id":"s_work_han_thu_29_345","chapterId":"ch_work_han_thu_29","textTraditional":"一一五三頁　二行　然市井子孫亦不得（宦為吏）〔為官吏〕。　景祐、殿本都作「為官吏」。","sentenceOrder":345},
  {"id":"s_work_han_thu_29_346","chapterId":"ch_work_han_thu_29","textTraditional":"一一五八頁　九行　蠻夷因以數攻（吏），　景祐、殿本都無「吏」字，平準書亦無。","sentenceOrder":346},
  {"id":"s_work_han_thu_29_347","chapterId":"ch_work_han_thu_29","textTraditional":"一一五九頁一一行　贖禁錮免（臧）〔減〕罪；　王先謙說「臧」當作「減」，平準書作「減」。","sentenceOrder":347},
  {"id":"s_work_han_thu_29_348","chapterId":"ch_work_han_thu_29","textTraditional":"一一六０頁一一行　自〔公〕孫弘以春秋之義繩臣下取漢相，　「公」字據景祐、殿、局本補。","sentenceOrder":348},
  {"id":"s_work_han_thu_29_349","chapterId":"ch_work_han_thu_29","textTraditional":"一一六０頁一六行　沮，（上）〔止〕壞之，　景祐、殿本都作「止」。王先謙說作「止」是。","sentenceOrder":349},
  {"id":"s_work_han_thu_29_350","chapterId":"ch_work_han_thu_29","textTraditional":"一一六四頁　二行　實（為）〔重〕四銖也。　景祐、殿本都作「重」。王先謙說作「重」是。","sentenceOrder":350},
  {"id":"s_work_han_thu_29_351","chapterId":"ch_work_han_thu_29","textTraditional":"一一六五頁一二行　令不可得摩取（鉛）〔鋊〕。　錢大昭說「鉛」當作「鋊」。按景祐、殿本都作「鋊」。","sentenceOrder":351},
  {"id":"s_work_han_thu_29_352","chapterId":"ch_work_han_thu_29","textTraditional":"一一六六頁一０行　〔行〕音下更反。　朱一新說「音」上脫「行」字。按各本都脫。","sentenceOrder":352},
  {"id":"s_work_han_thu_29_353","chapterId":"ch_work_han_thu_29","textTraditional":"一一六九頁　九行　天（下）〔子〕既下緍錢令而尊卜式，　錢大昭說「天下」之「下」字疑是「子」字。王先謙說錢說是。按景祐、殿本都作「子」。","sentenceOrder":353},
  {"id":"s_work_han_thu_29_354","chapterId":"ch_work_han_thu_29","textTraditional":"一一七０頁　一行　（令）〔今〕錢郭見有赤者，　殿本考證說「令」當作「今」。按平準書集解作「今」。","sentenceOrder":354},
  {"id":"s_work_han_thu_29_355","chapterId":"ch_work_han_thu_29","textTraditional":"一一七０頁　五行　乃分遣御史廷尉正監分曹往，〔三〕（往）即治郡國緍錢，　注〔三〕原在「分曹」下。王先謙說平準書不重「往」字，「往」字當屬上句，其重文蓋衍。","sentenceOrder":355},
  {"id":"s_work_han_thu_29_356","chapterId":"ch_work_han_thu_29","textTraditional":"一一七０頁　八行　益廣（開）〔關〕，置左右輔。　何焯說當從平準書作「益廣關」，「開」字誤。","sentenceOrder":356},
  {"id":"s_work_han_thu_29_357","chapterId":"ch_work_han_thu_29","textTraditional":"一一七０頁一四行　大農（幹）〔斡〕鹽鐵官布多，　王先謙說「幹」字誤，當作「斡」，平準書作「筦」，同。","sentenceOrder":357},
  {"id":"s_work_han_thu_29_358","chapterId":"ch_work_han_thu_29","textTraditional":"一一七一頁　四行　織讀曰（熾）〔幟〕，　殿本作「幟」。　王先謙說作「幟」是。","sentenceOrder":358},
  {"id":"s_work_han_thu_29_359","chapterId":"ch_work_han_thu_29","textTraditional":"一一七二頁　六行　至所在，有欲（往）〔住〕者，亦留而處（之）〔也〕。　王先謙說「往」疑作「住」。宋祁說「處之」當改「處也」。按景祐本「往」正作「住」，「之」正作「也」。","sentenceOrder":359},
  {"id":"s_work_han_thu_29_360","chapterId":"ch_work_han_thu_29","textTraditional":"一一七三頁　八行　差出（牡）〔牝〕馬　錢大昭說「牡」當作「牝」，昭帝始元元年罷天下亭母馬是也。按平準書亦作「牝」。","sentenceOrder":360},
  {"id":"s_work_han_thu_29_361","chapterId":"ch_work_han_thu_29","textTraditional":"一一七四頁一六行　令遠方各以其物如異時商賈所轉（貶）〔販〕者為賦，　景祐、殿、局本都作「販」。","sentenceOrder":361},
  {"id":"s_work_han_thu_29_362","chapterId":"ch_work_han_thu_29","textTraditional":"一一七六頁　五行　皆對願罷鹽鐵酒（〈木寉〉）〔榷〕均輸官，　景祐、殿本都作「榷」。","sentenceOrder":362},
  {"id":"s_work_han_thu_29_363","chapterId":"ch_work_han_thu_29","textTraditional":"一一八０頁　三行　皆為五均司市（稱）師。　王念孫說「稱」字涉下文四「稱」字而衍。","sentenceOrder":363},
  {"id":"s_work_han_thu_29_364","chapterId":"ch_work_han_thu_29","textTraditional":"一一八０頁一一行　天子取諸侯之（士）〔土〕以立五均，　景祐、殿本都作「土」。王先謙說作「土」是。","sentenceOrder":364},
  {"id":"s_work_han_thu_29_365","chapterId":"ch_work_han_thu_29","textTraditional":"一一八二頁　三行　貴（既）〔即〕為卬。　王先謙說殿本「既」作「即」，是。","sentenceOrder":365},
  {"id":"s_work_han_thu_29_366","chapterId":"ch_work_han_thu_29","textTraditional":"一一八三頁一０行　鐵，（曰）〔田〕農之本；　錢大昭說「曰」疑當作「田」。按殿、局本都作「田」。","sentenceOrder":366},
  {"id":"s_work_han_thu_30_1","chapterId":"ch_work_han_thu_30","textTraditional":"洪範八政，三曰祀。〔一〕祀者，所以昭孝事祖，通神明也。旁及四夷，莫不修之；下至禽獸，豺獺有祭。〔二〕是以聖王為之典禮。民之精爽不貳，齊肅聰明者，神或降之，〔三〕在男曰覡，在女曰巫，〔四〕使制神之處位，為之牲器。使先聖之後，能知山川，敬於禮儀，明神之事者，以為祝；能知四時犧牲，壇場上下，氏姓所出者，以為宗。〔五〕故有神民之官，各司其序，不相亂也。民神異業，敬而不黷，〔六〕故神降之嘉生，〔七〕民以物序，〔八〕災禍不至，所求不匱。〔九〕","sentenceOrder":1},
  {"id":"s_work_han_thu_30_2","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「祀謂祭祀也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_30_3","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「禮記月令：『季秋之月，豺祭獸。』『孟春之月，獺祭魚。』豺，摯搏之獸，形似狗。獺，水居而食魚。祭者，謂殺之而布列，以祭其先也。豺音仕皆反。獺音吐曷反。」","sentenceOrder":3},
  {"id":"s_work_han_thu_30_4","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「爽，明也。齊讀曰齋。齋肅，莊敬也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_30_5","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「巫覡亦通稱耳。覡音下狄反。」","sentenceOrder":5},
  {"id":"s_work_han_thu_30_6","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　應劭曰：「上下，謂天地之屬神也。氏姓，王族之別也。宗，大宗也。」臣瓚曰：「宗，宗伯也。」師古曰：「二說皆非也。祝謂主祭之贊詞者。積土為壇，平地為場。氏姓，謂神本所出，及見所當為主者也。宗，宗人，主神之列位尊卑者也。春秋左氏傳曰『虢公使祝應宗區享神』也，又云『祝宗用馬于四墉』，並非宗伯及大宗也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_30_7","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　師古曰：「黷，汙渫也。黷音讀。」","sentenceOrder":7},
  {"id":"s_work_han_thu_30_8","chapterId":"ch_work_han_thu_30","textTraditional":"〔七〕　應劭曰：「嘉穀也。」師古曰：「嘉生，謂眾瑞。」","sentenceOrder":8},
  {"id":"s_work_han_thu_30_9","chapterId":"ch_work_han_thu_30","textTraditional":"〔八〕　孟康曰：「各有分敘也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_30_10","chapterId":"ch_work_han_thu_30","textTraditional":"〔九〕　師古曰：「匱，乏也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_30_11","chapterId":"ch_work_han_thu_30","textTraditional":"及少昊之衰，九黎亂德，〔一〕民神雜擾，不可放物。〔二〕家為巫史，享祀無度，黷齊明而神弗蠲。〔三〕嘉生不降，禍災荐臻，莫盡其氣。〔四〕顓頊受之，乃命南正重司天以屬神，命火正黎司地以屬民，〔五〕使復舊常，亡相侵黷。","sentenceOrder":11},
  {"id":"s_work_han_thu_30_12","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　孟康曰：「少昊時諸侯作亂者也。」韋昭曰：「黎氏九人也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_30_13","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「放，依也。物，事也。放音甫往反。」","sentenceOrder":13},
  {"id":"s_work_han_thu_30_14","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「齊讀曰齋。蠲，絜也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_30_15","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「言不究其性命也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_30_16","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　應劭曰：「黎，陰官也。火數二，二，地數也，故火正司地以屬萬民。」師古曰：「屬，委也，以其事委之也。屬音之欲反。」","sentenceOrder":16},
  {"id":"s_work_han_thu_30_17","chapterId":"ch_work_han_thu_30","textTraditional":"自共工氏霸九州，其子曰句龍，能平水土，死為社祠。〔一〕有烈山氏王天下，其子曰柱，能殖百穀，死為稷祠。〔二〕故郊祀社稷，所從來尚矣。〔三〕","sentenceOrder":17},
  {"id":"s_work_han_thu_30_18","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「共工氏在太昊、炎帝之間。無祿而王，故謂之霸。句讀曰鉤。」","sentenceOrder":18},
  {"id":"s_work_han_thu_30_19","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「烈山氏，炎帝。」","sentenceOrder":19},
  {"id":"s_work_han_thu_30_20","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「尚，上也。謂起於上古。」","sentenceOrder":20},
  {"id":"s_work_han_thu_30_21","chapterId":"ch_work_han_thu_30","textTraditional":"虞書曰，舜在璿璣玉衡，以齊七政。〔一〕遂類于上帝，禋于六宗，〔二〕望秩于山川，遍于群神。〔三〕揖五瑞，〔四〕擇吉月日，見四嶽諸牧，班瑞。〔五〕歲二月，東巡狩，至于岱宗。〔六〕岱宗，泰山也。柴，望秩于山川。〔七〕遂見東后。東后者，諸侯也。〔八〕合時月正日，同律度量衡，〔九〕修五禮五樂，〔一０〕三帛二生一死為贄。〔一一〕五月，巡狩至南嶽。南嶽者，衡山也。八月，巡狩至西嶽。西嶽者，華山也。十一月，巡狩至北嶽。北嶽者，恆山也。皆如岱宗之禮。中嶽，嵩高也。五載一巡狩。〔一二〕","sentenceOrder":21},
  {"id":"s_work_han_thu_30_22","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「虞書舜典也。在，察也。璿，美玉也。璣轉而衡平。以玉為璣衡，謂渾天儀也。七政，日、月、五星也。言舜觀察璣衡，以齊同日、月、五星之政，度合天意。」","sentenceOrder":22},
  {"id":"s_work_han_thu_30_23","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　孟康曰：「六宗，星、辰、風伯、雨師、司中、司命。一說云乾坤六子。又一說：天宗三，日、月、星辰；地宗三，泰山、河、海。或曰天地間游神也。」師古曰：「類，以類祭也。上帝，天也。絜精以祀謂之禋。六宗之義，說者多矣。乾坤六子，其最通乎。」","sentenceOrder":23},
  {"id":"s_work_han_thu_30_24","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「望，謂在遠者望而祭之。秩，次也。群神，丘陵墳衍之屬。」","sentenceOrder":24},
  {"id":"s_work_han_thu_30_25","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「揖與輯同。揖，合也。五瑞，公、侯、伯、子、男之瑞玉。」","sentenceOrder":25},
  {"id":"s_work_han_thu_30_26","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　師古曰：「四嶽諸牧，謂四方諸侯也。班，布也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_30_27","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　師古曰：「狩，守也。諸侯為天子守土，故巡行。」","sentenceOrder":27},
  {"id":"s_work_han_thu_30_28","chapterId":"ch_work_han_thu_30","textTraditional":"〔七〕　師古曰：「柴，積柴而燔。」","sentenceOrder":28},
  {"id":"s_work_han_thu_30_29","chapterId":"ch_work_han_thu_30","textTraditional":"〔八〕　師古曰：「后，君也。東方諸侯，故謂之東后也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_30_30","chapterId":"ch_work_han_thu_30","textTraditional":"〔九〕　師古曰：「時，四時也。月，十二月也。日，三百六十日。律，六律也。度，尺丈也。量，斛斗也。衡，斤兩也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_30_31","chapterId":"ch_work_han_thu_30","textTraditional":"〔一０〕師古曰：「五禮，吉、凶、賓、軍、嘉也。五樂，謂春則琴瑟，夏則笙竽，季夏則鼓，秋則鐘，冬則磬也。五樂，尚書作五玉，今志亦有作五玉者。五玉即五瑞。」","sentenceOrder":31},
  {"id":"s_work_han_thu_30_32","chapterId":"ch_work_han_thu_30","textTraditional":"〔一一〕師古曰：「三帛，玄、纁、黃也。二牲，羔、鴈也。一死，雉也。贄者，所執以為禮也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_30_33","chapterId":"ch_work_han_thu_30","textTraditional":"〔一二〕師古曰：「此以上皆舜典所載。」","sentenceOrder":33},
  {"id":"s_work_han_thu_30_34","chapterId":"ch_work_han_thu_30","textTraditional":"禹遵之。後十三世，至帝孔甲，淫德好神，神黷，二龍去之〔一〕。其後十三世，湯伐桀，欲〈遷，去辶〉夏社，不可，作夏社。〔二〕乃〈遷，去辶〉烈山子柱，而以周棄代為稷祠。後八世，帝太戊有桑穀生於廷，一暮大拱，〔三〕懼。伊陟曰：「祅不勝德。」〔四〕太戊修德，桑穀死。伊陟贊巫咸。〔五〕後十三世，帝武丁得傅說為相，〔六〕殷復興焉，稱高宗。有雉登鼎耳而雊，〔七〕武丁懼。祖己曰：「修德。」武丁從之，位以永寧。〔八〕後五世，帝乙嫚神而震死。〔九〕後三世，帝紂淫亂，武王伐之。由是觀之，始未嘗不肅祇，後稍怠嫚也。","sentenceOrder":34},
  {"id":"s_work_han_thu_30_35","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　應劭曰：「夏帝孔甲，天賜之乘龍，河漢各二，其後媟黷嫚神，故龍去之。」","sentenceOrder":35},
  {"id":"s_work_han_thu_30_36","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　應劭曰：「遭大旱七年，明德以薦，而旱不止，故遷社，以棄代為稷。欲遷句龍，德莫能繼，故作夏社，說不可遷之義也。」師古曰：「〈遷，去辶〉，古遷字。夏社，尚書篇名，今則序在而書亡逸。」","sentenceOrder":36},
  {"id":"s_work_han_thu_30_37","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「穀即今之楮樹也，其字從木。合兩手曰拱。」","sentenceOrder":37},
  {"id":"s_work_han_thu_30_38","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「伊陟，太戊臣，伊尹之子。」","sentenceOrder":38},
  {"id":"s_work_han_thu_30_39","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　孟康曰：「巫咸，殷賢臣。贊，說也，謂伊陟說其意也。」師古曰：「因此作咸乂四篇。事見商書序，其篇亦亡逸也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_30_40","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　師古曰：「說讀曰悅。」","sentenceOrder":40},
  {"id":"s_work_han_thu_30_41","chapterId":"ch_work_han_thu_30","textTraditional":"〔七〕　師古曰：「雊，雉鳴，音工豆反。」","sentenceOrder":41},
  {"id":"s_work_han_thu_30_42","chapterId":"ch_work_han_thu_30","textTraditional":"〔八〕　師古曰：「事見商書說命及高宗肜日。祖己，殷之賢臣。」","sentenceOrder":42},
  {"id":"s_work_han_thu_30_43","chapterId":"ch_work_han_thu_30","textTraditional":"〔九〕　師古曰：「帝乙，武乙也，為韋囊盛血，仰而射之，號曰射天，後遇雷震而死。」","sentenceOrder":43},
  {"id":"s_work_han_thu_30_44","chapterId":"ch_work_han_thu_30","textTraditional":"周公相成王，王道大洽，制禮作樂，天子曰明堂辟雍，〔一〕諸侯曰泮宮。〔二〕郊祀后稷以配天，宗祀文王於明堂以配上帝。〔三〕四海之內各以其職來助祭。天子祭天下名山大川，懷柔百神，咸秩無文。〔四〕五嶽視三公，四瀆視諸侯。〔五〕而諸侯祭其疆內名山大川，〔六〕大夫祭門、戶、井、灶、中霤五祀。〔七〕士庶人祖考而已。各有典禮，而淫祀有禁。","sentenceOrder":44},
  {"id":"s_work_han_thu_30_45","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「明堂辟雍，解在平紀。」","sentenceOrder":45},
  {"id":"s_work_han_thu_30_46","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「泮之言半也。制度半於天子之辟雍也。泮音普半反。」","sentenceOrder":46},
  {"id":"s_work_han_thu_30_47","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「郊祀，祀於郊也。后稷，周之始祖也。宗，尊也。文王，周始受命之王。上帝，太微五帝也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_30_48","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「懷，來也。柔，安也。言招來百神而安處之也。稱百者，言其多也。秩，序也。舊無禮文者，皆以次序而祭之。」","sentenceOrder":48},
  {"id":"s_work_han_thu_30_49","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　師古曰：「江、河、淮、濟為四瀆。瀆者，發源而注海者也。視謂其禮物之數也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_30_50","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　師古曰：「疆，境也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_30_51","chapterId":"ch_work_han_thu_30","textTraditional":"〔七〕　韋昭曰：「古者穴居，故名室中為中霤。」","sentenceOrder":51},
  {"id":"s_work_han_thu_30_52","chapterId":"ch_work_han_thu_30","textTraditional":"後十三世，世益衰，禮樂廢。幽王無道，為犬戎所敗，平王東徙雒邑。秦襄公攻戎救周，列為諸侯，而居西，自以為主少昊之神，作西畤，祠白帝，其牲用騮駒黃牛羝羊各一云。〔一〕","sentenceOrder":52},
  {"id":"s_work_han_thu_30_53","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「騮，赤馬黑鬛尾也。羝，牡羊也。騮音留。羝音丁奚反。」","sentenceOrder":53},
  {"id":"s_work_han_thu_30_54","chapterId":"ch_work_han_thu_30","textTraditional":"其後十四年，秦文公東獵汧渭之間，〔一〕卜居之而吉。文公（薨）〔夢〕黃蛇自天下屬地，〔二〕其口止於鄜衍。〔三〕文公問史敦，〔四〕敦曰：「此上帝之徵，君其祠之。」於是作鄜畤，用三牲郊祭白帝焉。","sentenceOrder":54},
  {"id":"s_work_han_thu_30_55","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「汧渭，二水名。汧音牽。」。","sentenceOrder":55},
  {"id":"s_work_han_thu_30_56","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「屬，著也，音之欲反。」","sentenceOrder":56},
  {"id":"s_work_han_thu_30_57","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　李奇曰：「鄜音孚。三輔謂山阪間為衍。」晉灼曰：「左馮翊鄜縣之衍也。」師古曰：「今之鄜州蓋取名於此也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_30_58","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「秦之太史也。敦其名也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_30_59","chapterId":"ch_work_han_thu_30","textTraditional":"自未作鄜畤，而雍旁故有吳陽武畤，〔一〕雍東有好畤，皆廢無祀。或曰：「自古以雍州積高，神明之隩，〔二〕故立畤郊上帝，諸神祠皆聚云。蓋黃帝時嘗用事，雖晚周亦郊焉。」〔三〕其語不經見，縉紳者弗道。〔四〕","sentenceOrder":59},
  {"id":"s_work_han_thu_30_60","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　李奇曰：「於旁有吳陽地也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_30_61","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「土之可居者曰隩，音於六反。」","sentenceOrder":61},
  {"id":"s_work_han_thu_30_62","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「晚謂末時也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_30_63","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　李奇曰：「縉，插也，插笏於紳。紳，大帶也。」臣瓚曰：「縉，赤白色也。紳，大帶也。左氏傳有縉雲氏。」師古曰：「李云縉插是也。字本作搢，插笏於大帶與革帶之間耳，非插於大帶也。或作薦紳者，亦謂薦笏於紳帶之間，其義同。」","sentenceOrder":63},
  {"id":"s_work_han_thu_30_64","chapterId":"ch_work_han_thu_30","textTraditional":"作鄜畤後九年，文公獲若石云，于陳倉北阪城祠之。〔一〕其神或歲不至，或歲數。來也常以夜，光輝若流星，從東方來，集於祠城，若雄雉，其聲殷殷云，野雞夜鳴。〔二〕以一牢祠之，名曰陳寶。〔三〕","sentenceOrder":64},
  {"id":"s_work_han_thu_30_65","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　蘇林曰：「質如石，似肝。」師古曰：「陳倉之北阪上城中也。云，語辭也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_30_66","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「殷殷，聲也。云，傳聲之亂也。野雞，亦雉也，避呂后諱，故曰野雞。言陳寶若來而有聲，則野雞皆鳴以應之也。上言雄雉，下言野雞，史駮文也。殷音隱。」","sentenceOrder":66},
  {"id":"s_work_han_thu_30_67","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　臣瓚曰：「陳倉縣有寶夫人祠，或一歲二歲與葉君合。葉君神來時，天為之殷殷雷鳴，雉為之雊也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_30_68","chapterId":"ch_work_han_thu_30","textTraditional":"作陳寶祠後七十一年，秦德公立，卜居雍。〔一〕子孫飲馬於河，遂都雍。雍之諸祠自此興。用三百牢於鄜畤。作伏祠。〔二〕磔狗邑四門，以御蠱災。","sentenceOrder":68},
  {"id":"s_work_han_thu_30_69","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「即今之雍縣。」","sentenceOrder":69},
  {"id":"s_work_han_thu_30_70","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　孟康曰：「六月伏日也。周時無，至此乃有之。」師古曰：「伏者，謂陰氣將起，迫於殘陽而未得升，故為臧伏，因名伏日也。立秋之後，以金代火，金畏於火，故至庚日必伏。庚，金也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_30_71","chapterId":"ch_work_han_thu_30","textTraditional":"後四年，秦宣公作密畤於渭南，祭青帝。","sentenceOrder":71},
  {"id":"s_work_han_thu_30_72","chapterId":"ch_work_han_thu_30","textTraditional":"後十三年，秦穆公立，病臥五日不寤；〔一〕寤，乃言夢見上帝，〔二〕上帝命穆公平晉亂。史書而藏之府。〔三〕而後世皆曰上天。","sentenceOrder":72},
  {"id":"s_work_han_thu_30_73","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「寤，覺也。覺音公孝反。」","sentenceOrder":73},
  {"id":"s_work_han_thu_30_74","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「上帝謂天也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_30_75","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「府，臧書之處。」","sentenceOrder":75},
  {"id":"s_work_han_thu_30_76","chapterId":"ch_work_han_thu_30","textTraditional":"穆公立九年，齊桓公既霸，會諸侯於葵丘，而欲封禪。〔一〕管仲曰：「古者封泰山禪梁父者七十二家，〔二〕而夷吾所記者十有二焉。昔無懷氏封泰山，禪云云；〔三〕虙羲封泰山，禪云云；〔四〕神農氏封泰山，禪云云；炎帝封泰山，禪云云；〔五〕黃帝封泰山，禪亭亭；〔六〕顓頊封泰山，禪云云；帝嚳封泰山，禪云云；堯封泰山，禪云云；舜封泰山，禪云云；禹封泰山，禪會稽；湯封泰山，禪云云；周成王封泰山，禪於社首：〔七〕皆受命然後得封禪。」桓公曰：「寡人北伐山戎，過孤竹；〔八〕西伐，束馬縣車，上卑耳之山；〔九〕南伐至召陵，〔一０〕登熊耳山，以望江漢。〔一一〕兵車之會三，乘車之會六，九合諸侯，一匡天下，〔一二〕諸侯莫違我。昔三代受命，亦何以異乎？」於是管仲睹桓公不可窮以辭，因設之以事，曰：「古之封禪，鄗上黍，北里禾，所以為盛；〔一三〕江淮間一茅三脊，所以為藉也。〔一四〕東海致比目之魚，〔一五〕西海致比翼之鳥。〔一六〕然後物有不召而自至者十有五焉。今鳳皇麒麟不至，嘉禾不生，而蓬蒿藜莠茂，鴟梟群翔，〔一七〕而欲封禪，無乃不可乎？」於是桓公乃止。","sentenceOrder":76},
  {"id":"s_work_han_thu_30_77","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「葵丘會在僖九年。葵丘在陳留外黃縣東。封禪者，封土於山而禪祭於地也。禪音上戰反，解在武紀。」","sentenceOrder":77},
  {"id":"s_work_han_thu_30_78","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「父音甫。」","sentenceOrder":78},
  {"id":"s_work_han_thu_30_79","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　鄭氏曰：「無懷氏，古之王者，在伏羲前，見莊子。」服虔曰：「云云在梁父東，山名也。」晉灼曰：「云云山在蒙陰縣故城東北，下有云云亭。」","sentenceOrder":79},
  {"id":"s_work_han_thu_30_80","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「虙讀曰伏。」","sentenceOrder":80},
  {"id":"s_work_han_thu_30_81","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　李奇曰：「炎帝，神農後。」","sentenceOrder":81},
  {"id":"s_work_han_thu_30_82","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　服虔曰：「亭亭山在牟陰。」晉灼曰：「地理志鉅平有亭亭山。」師古曰：「晉說是也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_30_83","chapterId":"ch_work_han_thu_30","textTraditional":"〔七〕　應劭曰：「山名，在博縣。」晉灼曰：「在鉅平南十二里。」師古曰：「晉說是也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_30_84","chapterId":"ch_work_han_thu_30","textTraditional":"〔八〕　應劭曰：「伯夷國也，在遼西令支。」師古曰：「令音郎定反。支音神祇之祇。」","sentenceOrder":84},
  {"id":"s_work_han_thu_30_85","chapterId":"ch_work_han_thu_30","textTraditional":"〔九〕　韋昭曰：「將上山，纏束其馬，縣鉤其車也。卑耳即齊語所謂辟耳。」","sentenceOrder":85},
  {"id":"s_work_han_thu_30_86","chapterId":"ch_work_han_thu_30","textTraditional":"〔一０〕師古曰：「召陵，楚地也，在汝南。召讀曰劭。」","sentenceOrder":86},
  {"id":"s_work_han_thu_30_87","chapterId":"ch_work_han_thu_30","textTraditional":"〔一一〕師古曰：「熊耳山在順陽北益陽縣東，非禹貢所云『導洛自熊耳』者也。其山兩峰，狀亦若熊耳，因以為名也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_30_88","chapterId":"ch_work_han_thu_30","textTraditional":"〔一二〕師古曰：「兵車之會三，謂莊十三年會於北杏以平宋亂，僖四年侵蔡，蔡潰，遂伐楚，次於陘，六年伐鄭圍新城也。乘車之會六，謂莊十四年會於鄄，十五年又會於鄄，十六年同盟於幽，僖五年會於首止，八年盟於洮，九年會於葵丘也。匡，正也。一匡天下，謂定襄王為天子之位也。一說謂陽穀之會令諸侯云『無障谷，無貯粟，無以妾為妻』，天下皆從，故云一匡者也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_30_89","chapterId":"ch_work_han_thu_30","textTraditional":"〔一三〕應劭曰：「鄗音臛。」蘇林曰：「鄗上、北里，皆地名也。」師古曰：「盛謂以實簠簋。」","sentenceOrder":89},
  {"id":"s_work_han_thu_30_90","chapterId":"ch_work_han_thu_30","textTraditional":"〔一四〕服虔曰：「茅草有三脊也。」張晏曰：「謂靈茅也。」師古曰：「藉，以藉地也，音才夜反。」","sentenceOrder":90},
  {"id":"s_work_han_thu_30_91","chapterId":"ch_work_han_thu_30","textTraditional":"〔一五〕師古曰：「爾雅云『東方有比目魚焉，不比不行，其名謂之鰈』，音土盍反。」","sentenceOrder":91},
  {"id":"s_work_han_thu_30_92","chapterId":"ch_work_han_thu_30","textTraditional":"〔一六〕師古曰：「山海經云『崇吾之山有鳥狀如鳧，而一翼一目，相得乃飛，其名曰鸞』。爾雅曰『南方有比翼鳥焉，不比飛，其名謂之鶼鶼』。而管仲乃云西海，其說異也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_30_93","chapterId":"ch_work_han_thu_30","textTraditional":"〔一七〕師古曰：「蓬蒿藜莠，皆穢惡之草。梟，不祥之鳥也。鴟，蓋今所謂角鴟也。梟，土梟也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_30_94","chapterId":"ch_work_han_thu_30","textTraditional":"是歲，秦穆公納晉君夷吾。其後三置晉國之君，平其亂。〔一〕穆公立三十九年而卒。","sentenceOrder":94},
  {"id":"s_work_han_thu_30_95","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「三立其君，謂惠公、懷公、文公。」","sentenceOrder":95},
  {"id":"s_work_han_thu_30_96","chapterId":"ch_work_han_thu_30","textTraditional":"後五十年，周靈王即位。時諸侯莫朝周，萇弘乃明鬼神事，〔一〕設射不來。不來者，諸侯之不來朝者也。依物怪，欲以致諸侯。諸侯弗從，而周室愈微。後二世，至敬王時，晉人殺萇弘。〔二〕","sentenceOrder":96},
  {"id":"s_work_han_thu_30_97","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「萇弘，周大夫。」","sentenceOrder":97},
  {"id":"s_work_han_thu_30_98","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　李奇曰：「周為晉殺之也。」師古曰：「春秋左氏傳哀公三年傳稱『劉氏、范氏世為婚姻，萇弘事劉文公，故周與范氏趙鞅以為討，周人殺萇弘』也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_30_99","chapterId":"ch_work_han_thu_30","textTraditional":"是時，季氏專魯，旅於泰山，仲尼譏之。〔一〕","sentenceOrder":99},
  {"id":"s_work_han_thu_30_100","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「旅，陳也，陳禮物而祭之也。陪臣祭泰山，僭諸侯之禮。孔子非之曰：『嗚乎，曾謂泰山不如林放乎！』事見論語。」","sentenceOrder":100},
  {"id":"s_work_han_thu_30_101","chapterId":"ch_work_han_thu_30","textTraditional":"自秦宣公作密畤後二百五十年，而秦靈公於吳陽作上畤，祭黃帝；作下畤，祭炎帝。","sentenceOrder":101},
  {"id":"s_work_han_thu_30_102","chapterId":"ch_work_han_thu_30","textTraditional":"後四十八年，周太史儋見秦獻公〔一〕曰：「周始與秦國合而別，別五百載當復合，〔二〕合七十年而伯王出焉。」〔三〕儋見後七年，櫟陽雨金，獻公自以為得金瑞，故作畦畤櫟陽，而祀白帝。〔四〕","sentenceOrder":102},
  {"id":"s_work_han_thu_30_103","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　孟康曰：「太史儋謂老子也。」師古曰：「此亦周之太史名，非必老聃。老聃非秦獻公時。儋音丁甘反，又吐甘反。」","sentenceOrder":103},
  {"id":"s_work_han_thu_30_104","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　應劭曰：「秦，伯翳之後也。始周孝王封非子為附庸，邑諸秦。平王東遷洛邑，襄公以兵衛之，嘉其勳力，列為侯伯，與周別五百載矣。昭王時，西周君自歸受罪，盡獻其邑三十六城，此復合也。」孟康曰：「謂周封秦為別，秦并周為合。此襄王為霸，始皇為王也。」韋昭曰：「周封秦為始別，謂秦仲也。五百歲，謂從秦仲至孝公彊大，顯王致伯，與之親合也。」師古曰：「諸家之說皆非也。自非子至西周獻邑，凡六百五十三歲，自仲至顯王二十六年孝公稱伯，止有四百二十六歲，皆不合五百之數也。按史記秦本紀及年表，並云周平王封襄公，始列為諸侯，於是始與諸侯通。又周本紀及吳、齊、晉、楚諸系家皆言幽王為犬戎所殺，秦始列為諸侯，正與此志符會，是乃為別。至昭襄王五十二年，西周君自歸獻邑，凡五百一十六年，是為合也。言五百者，舉其成數也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_30_105","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　韋昭曰：「武王、昭王皆伯，至始皇而王天下。」師古曰：「七十當為十七，今史記舊本皆作十七字。伯王者，指謂始皇。始皇初立，政在太后、嫪毐，未得稱伯。自昭王滅周後，至始皇九年誅嫪毐，止十七年。本紀年表其義顯，而韋氏乃合武王、昭王為數，失之遠矣。伯讀曰霸。」","sentenceOrder":105},
  {"id":"s_work_han_thu_30_106","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「畦畤者，如種韭畦之形，而畤於畦中各為一土封也。畦音下圭反。」","sentenceOrder":106},
  {"id":"s_work_han_thu_30_107","chapterId":"ch_work_han_thu_30","textTraditional":"後百一十歲，周赧王卒，九鼎入於秦。或曰，周顯王之四十二年，宋大丘社亡，〔一〕而鼎淪沒於泗水彭城下。","sentenceOrder":107},
  {"id":"s_work_han_thu_30_108","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「爾雅云『左陵泰丘』，謂丘左有陵者其名泰丘也。郭璞云『宋有泰丘』，蓋以丘名此地也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_30_109","chapterId":"ch_work_han_thu_30","textTraditional":"自赧王卒後七年，秦莊襄王滅東周，周祀絕。後二十八年，秦并天下，稱皇帝。","sentenceOrder":109},
  {"id":"s_work_han_thu_30_110","chapterId":"ch_work_han_thu_30","textTraditional":"秦始皇帝既即位，或曰：「黃帝得土德，黃龍地螾見。〔一〕夏得木德，青龍止於郊，草木鬯茂。〔二〕殷得金德，銀自山溢。〔三〕周得火德，有赤烏之符。〔四〕今秦變周，水德之時。昔文公出（臘）〔獵〕，獲黑龍，此其水德之瑞。」於是秦更名河曰「德水」，以冬十月為年首，色尚黑，度以六為名，〔五〕音上大呂，〔六〕事統上法。〔七〕","sentenceOrder":110},
  {"id":"s_work_han_thu_30_111","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　應劭曰：「螾，丘蚓也。黃帝土德，故地見其神，蚓大五六圍，長十餘丈。」如淳曰：「呂氏春秋云黃帝之時天先見大螻大螾，黃帝曰土氣勝，故其色尚黃。」師古曰：「螾音蚓。螻音樓，謂螻蛄也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_30_112","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「鬯與暢同。」","sentenceOrder":112},
  {"id":"s_work_han_thu_30_113","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　蘇林曰：「流出也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_30_114","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「謂武王伐紂師渡孟津之時也。尚書中候曰『有火自天止於王屋，流為赤烏，五至，以穀俱來』。」","sentenceOrder":114},
  {"id":"s_work_han_thu_30_115","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　張晏曰：「水北方黑，終數六，故以方六寸為符，六尺為步。」","sentenceOrder":115},
  {"id":"s_work_han_thu_30_116","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　師古曰：「大呂，陰律之始也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_30_117","chapterId":"ch_work_han_thu_30","textTraditional":"〔七〕　服虔曰：「政尚法令也。」臣瓚曰：「水陰，陰主刑殺，故上法。」","sentenceOrder":117},
  {"id":"s_work_han_thu_30_118","chapterId":"ch_work_han_thu_30","textTraditional":"即帝位三年，東巡狩郡縣，祠騶嶧山，〔一〕頌功業。〔二〕於是從齊魯之儒生博士七十人，至於泰山下。諸儒生或議曰：「古者封禪為蒲車，惡傷山之土石草木；〔三〕掃地而祠，席用苴稭，〔四〕言其易遵也。」始皇聞此議各乖異，難施用，由此黜儒生。〔五〕而遂除車道，上自泰山陽。至顛，立石頌德，明其得封也。從陰道下，〔六〕禪於梁父。其禮頗采泰祝之祀雍上帝所用，而封臧皆祕之，世不得而記也。","sentenceOrder":118},
  {"id":"s_work_han_thu_30_119","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　蘇林曰：「騶，魯縣也。」臣瓚曰：「嶧山在北。」師古曰：「嶧音亦。」","sentenceOrder":119},
  {"id":"s_work_han_thu_30_120","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「謂刻石自著功業。」","sentenceOrder":120},
  {"id":"s_work_han_thu_30_121","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「蒲車，以蒲裹輪。」","sentenceOrder":121},
  {"id":"s_work_han_thu_30_122","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　應劭曰：「稭，藁本也，去皮以為席。」如淳曰：「苴讀如租。稭讀如戛。」晉灼曰：「苴，藉也。」師古曰：「茅藉也。苴字本作葅，假借用。」","sentenceOrder":122},
  {"id":"s_work_han_thu_30_123","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　師古曰：「黜，退也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_30_124","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　師古曰：「山南曰陽，山北曰陰。」","sentenceOrder":124},
  {"id":"s_work_han_thu_30_125","chapterId":"ch_work_han_thu_30","textTraditional":"始皇之上泰山，中阪遇暴風雨，休於大樹下。諸儒既黜，不得與封禪，〔一〕聞始皇遇風雨，即譏之。","sentenceOrder":125},
  {"id":"s_work_han_thu_30_126","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「與讀曰豫也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_30_127","chapterId":"ch_work_han_thu_30","textTraditional":"於是始皇遂東遊海上，行禮祠名山川及八神，（來）〔求〕僊人羨門之屬。〔一〕八神將自古而有之；或曰太公以來作之。齊所以為齊，以天齊也。〔二〕其祀絕，莫知起時。八神，一曰天主，祠天齊。天齊淵水，居臨菑南郊山下下者。〔三〕二曰地主，祠泰山梁父。蓋天好陰，祠之必於高山之下畤，命曰「畤」；〔四〕地貴陽，祭之必於澤中圜丘云。三曰兵主，祠蚩尤。蚩尤在東平陸監鄉，齊之西竟也。〔五〕四曰陰主，祠三山；〔六〕五曰陽主，祠之罘山；〔七〕六曰月主，祠（之）萊山：〔八〕皆在齊北，並勃海。〔九〕七曰日主，祠盛山。盛山斗入海，〔一０〕最居齊東北陽，以迎日出云。八曰四時主，祠琅邪。琅邪在齊東北，蓋歲之所始。〔一一〕皆各用牢具祠，而巫祝所損益，圭幣雜異焉。〔一二〕","sentenceOrder":127},
  {"id":"s_work_han_thu_30_128","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　應劭曰：「羨門名子高，古仙人也。」師古曰：「古亦以僊為仙字。下皆類此。」","sentenceOrder":128},
  {"id":"s_work_han_thu_30_129","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　蘇林曰：「當天中央齊也。」師古曰：「謂其眾神異，如天之腹齊也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_30_130","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「下下，謂最下者。臨菑城南有天齊水，五泉並出，蓋謂此也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_30_131","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「名其祭處曰畤也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_30_132","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　師古曰：「東平陸，縣名也。監，其縣之鄉名也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_30_133","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　師古曰：「三山，即下所謂三神山。」","sentenceOrder":133},
  {"id":"s_work_han_thu_30_134","chapterId":"ch_work_han_thu_30","textTraditional":"〔七〕　韋昭曰：「之罘山在東萊腄縣。」師古曰：「罘音浮。腄音直瑞反。」","sentenceOrder":134},
  {"id":"s_work_han_thu_30_135","chapterId":"ch_work_han_thu_30","textTraditional":"〔八〕　韋昭曰：「在東萊長廣也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_30_136","chapterId":"ch_work_han_thu_30","textTraditional":"〔九〕　師古曰：「並音步浪反。」","sentenceOrder":136},
  {"id":"s_work_han_thu_30_137","chapterId":"ch_work_han_thu_30","textTraditional":"〔一０〕韋昭曰：「盛山在東萊不夜縣，斗入海也。」師古曰：「斗，絕也。盛音成。」","sentenceOrder":137},
  {"id":"s_work_han_thu_30_138","chapterId":"ch_work_han_thu_30","textTraditional":"〔一一〕師古曰：「山海經云琅邪臺在勃海間，謂臨海有山形如臺也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_30_139","chapterId":"ch_work_han_thu_30","textTraditional":"〔一二〕師古曰：「言八神牲牢皆同，而圭幣各異也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_30_140","chapterId":"ch_work_han_thu_30","textTraditional":"自齊威、宣時，騶子之徒論著終始五德之運，〔一〕及秦帝而齊人奏之，故始皇采用之。而宋毋忌、正伯僑、元尚、羨門高最後，皆燕人，為方僊道，〔二〕形解銷化，〔三〕依於鬼神之事。騶衍以陰陽主運〔四〕顯於諸侯，而燕齊海上之方士傳其術不能通，然則怪迂阿諛苟合之徒自此興，不可勝數也。〔五〕","sentenceOrder":140},
  {"id":"s_work_han_thu_30_141","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　如淳曰：「今其書有五德終始。五德各以所勝為行。秦謂周為火德，滅火者水，故自謂水德。」師古曰：「騶子即騶衍。」","sentenceOrder":141},
  {"id":"s_work_han_thu_30_142","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　韋昭曰：「皆慕古人之名，效為神仙者也。」師古曰：「自宋毋忌至最後，皆其人姓名也，凡五人。」","sentenceOrder":142},
  {"id":"s_work_han_thu_30_143","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　服虔曰：「尸解也。」張晏曰：「人老而解去，故骨如變化也。今山中有龍骨，世人謂之龍解骨化去。」應劭曰：「列仙傳曰崔文子學仙於王子喬，〔王子喬〕化為白蜺，文子驚，引戈擊之，俯而見之，王子喬之尸也，須臾則為大鳥飛而去。」師古曰：「服、張二說是也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_30_144","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　晉灼曰：「燕昭王築宮師之，故作主運之篇也。」如淳曰：「今其書有（王）〔主〕運。五行相次轉用事，隨方（而）〔面〕為服也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_30_145","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　師古曰：「迂謂回遠也，音于。」","sentenceOrder":145},
  {"id":"s_work_han_thu_30_146","chapterId":"ch_work_han_thu_30","textTraditional":"自威、宣、燕昭使人入海求蓬萊、方丈、瀛洲。此三神山者，其傳在勃海中，〔一〕去人不遠。蓋嘗有至者，諸僊人及不死之藥皆在焉。其物禽獸盡白，而黃金銀為宮闕。未至，望之如雲；及到，三神山反居水下，水臨之。患且至，則風輒引船而去，終莫能至云。世主莫不甘心焉。〔二〕","sentenceOrder":146},
  {"id":"s_work_han_thu_30_147","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　服虔曰：「其傳書云爾。」臣瓚曰：「世人相傳云爾。」師古曰：「瓚說是也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_30_148","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「甘心，言貪嗜之心不能已也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_30_149","chapterId":"ch_work_han_thu_30","textTraditional":"及秦始皇至海上，則方士爭言之。始皇如恐弗及，使人齎童男女入海求之。船交海中，皆以風為解，〔一〕曰未能至，望見之焉。其明年，始皇復游海上，至琅邪，過恆山，從上黨歸。後三年，游碣石，考入海方士，〔二〕從上郡歸。後五年，始皇南至湘山，遂登會稽，並海上，〔三〕幾遇海中三神山之奇藥。〔四〕不得，還到沙丘崩。〔五〕","sentenceOrder":149},
  {"id":"s_work_han_thu_30_150","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「自解說云為風不得至。」","sentenceOrder":150},
  {"id":"s_work_han_thu_30_151","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「考，校其虛實也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_30_152","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「附海而上也。並音步浪反。上音時掌反。」","sentenceOrder":152},
  {"id":"s_work_han_thu_30_153","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「幾讀曰冀。」","sentenceOrder":153},
  {"id":"s_work_han_thu_30_154","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　臣瓚曰：「沙丘在鉅鹿縣東北也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_30_155","chapterId":"ch_work_han_thu_30","textTraditional":"二世元年，東巡碣石，並海，〔一〕南歷泰山，至會稽，皆禮祠之，而刻勒始皇所立石書旁，以章始皇之功德。〔二〕其秋，諸侯叛秦。三年而二世弒死。","sentenceOrder":155},
  {"id":"s_work_han_thu_30_156","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「並音步浪反。」","sentenceOrder":156},
  {"id":"s_work_han_thu_30_157","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「今此諸山皆有始皇所刻石及胡亥重刻，其文並具存焉。」","sentenceOrder":157},
  {"id":"s_work_han_thu_30_158","chapterId":"ch_work_han_thu_30","textTraditional":"始皇封禪之後十二年而秦亡。諸儒生疾秦焚詩書，誅滅文學，百姓怨其法，天下叛之，皆說曰：「始皇上泰山，為風雨所擊，不得封禪云。」此豈所謂無其德而用其事者邪？","sentenceOrder":158},
  {"id":"s_work_han_thu_30_159","chapterId":"ch_work_han_thu_30","textTraditional":"昔三代之居皆河洛之間，〔一〕故嵩高為中嶽，而四嶽各如其方，四瀆咸在山東。至秦稱帝，都咸陽，則五嶽、四瀆皆并在東方。自五帝以至秦，迭興迭衰，〔二〕名山大川或在諸侯，或在天子，其禮損益世殊，不可勝記。〔三〕及秦并天下，令祠官所常奉天地名山大川鬼神可得而序也。","sentenceOrder":159},
  {"id":"s_work_han_thu_30_160","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「謂夏都安邑，殷都朝歌，周都洛陽。」","sentenceOrder":160},
  {"id":"s_work_han_thu_30_161","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「迭，互也，音大結反。」","sentenceOrder":161},
  {"id":"s_work_han_thu_30_162","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「代代殊異，故不可盡記。」","sentenceOrder":162},
  {"id":"s_work_han_thu_30_163","chapterId":"ch_work_han_thu_30","textTraditional":"於是自崤以東，名山五，大川祠二。〔一〕曰太室。太室，嵩高也。恆山，泰山，會稽，湘山。水曰泲，曰淮。〔二〕春以脯酒為歲禱，因泮凍；〔三〕秋涸凍；〔四〕冬塞禱祠。〔五〕其牲用牛犢各一，牢具圭幣各異。自華以西，名山七，名川四。曰華山，薄山。薄山者，襄山也。〔六〕岳山，岐山，吳山，鴻冢，瀆山。瀆山，蜀之岷山也。〔七〕水曰河，祠臨晉；〔八〕沔，祠漢中；〔九〕湫淵，祠朝那；〔一０〕江水，祠蜀。亦春秋泮涸禱塞如東方山川；而牲亦牛犢牢具圭幣各異。而四大冢鴻、岐、吳、嶽，皆有嘗禾。〔一一〕陳寶節來祠，〔一二〕其河加有嘗醪。此皆雍州之域，近天子都，故加車一乘，騮駒四。霸、產、豐、澇、涇、渭、長水，皆不在大山川數，〔一三〕以近咸陽，盡得比山川祠，而無諸加。〔一四〕汧、洛二淵，鳴澤、蒲山、嶽婿山之屬，〔一五〕為小山川，亦皆禱塞泮涸祠，禮不必同。而雍有日、月、參、辰、南北斗、熒惑、太白、歲星、填星、辰星、二十八宿、風伯、雨師、四海、九臣、十四臣、諸布、諸嚴、諸逐之屬，百有餘廟。〔一六〕西亦有數十祠。於湖有周天子祠。於下邽有天神。豐、鎬有昭明、天子辟池。於杜、亳有五杜主之祠、壽星祠；〔一七〕而雍、菅廟祠亦有杜主。〔一八〕杜主，故周之右將軍，〔一九〕其在秦中最小鬼之神者也。〔二０〕各以歲時奉祠。","sentenceOrder":163},
  {"id":"s_work_han_thu_30_164","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「崤即今之陝州二崤也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_30_165","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「泲音子禮反，此本濟水之字。」","sentenceOrder":165},
  {"id":"s_work_han_thu_30_166","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　服虔曰：「解凍也。」師古曰：「泮音普半反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_30_167","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「涸讀與沍同。沍，凝也，音下故反。春則解之，秋則凝之。春秋左氏傳曰『固陰沍寒』。禮記月令曰『孟冬行春令則凍閉不密』。」","sentenceOrder":167},
  {"id":"s_work_han_thu_30_168","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　師古曰：「塞謂報其所祈也，音先代反。下並同也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_30_169","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　師古曰：「說者云薄山在河東，一曰在潼關北十餘里，而此志云自華以西者，則今閺鄉之南山連延西出，並得華山之名。」","sentenceOrder":169},
  {"id":"s_work_han_thu_30_170","chapterId":"ch_work_han_thu_30","textTraditional":"〔七〕　師古曰：「周禮職方氏：『雍州，其山曰岳。』爾雅亦云『河西曰岳』。說者咸云岳即吳岳也。今志有岳，又有吳山，則吳岳非一山之名，但未詳岳之所在耳。徐廣云：『岳山在武功。』據地理志，武功但有垂山，無岳山也。岐山即在今之岐山縣，其山兩岐，俗呼為箭括嶺。吳山在今隴州吳山縣。鴻冢，釋在下。岷山在湔氐道。」","sentenceOrder":170},
  {"id":"s_work_han_thu_30_171","chapterId":"ch_work_han_thu_30","textTraditional":"〔八〕　師古曰：「即今之同州朝邑縣界。」","sentenceOrder":171},
  {"id":"s_work_han_thu_30_172","chapterId":"ch_work_han_thu_30","textTraditional":"〔九〕　師古曰：「沔，漢水之上名也。漢中，今梁州是也。沔音彌善反。」","sentenceOrder":172},
  {"id":"s_work_han_thu_30_173","chapterId":"ch_work_han_thu_30","textTraditional":"〔一０〕蘇林曰：「湫淵在安定朝那縣，方四十里，停水不流，冬夏不增不減，不生草木。湫音將蓼反。」師古曰：「此水今在涇州界，清澈可愛，不容穢濁，或諠污，輒興雲雨。土俗亢旱，每於此求之，相傳云龍之所居也。而天下山川隈曲，亦往往有之。湫音子由反。」","sentenceOrder":173},
  {"id":"s_work_han_thu_30_174","chapterId":"ch_work_han_thu_30","textTraditional":"〔一一〕孟康曰：「以新穀祭之。」","sentenceOrder":174},
  {"id":"s_work_han_thu_30_175","chapterId":"ch_work_han_thu_30","textTraditional":"〔一二〕服虔曰：「陳寶神應節來也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_30_176","chapterId":"ch_work_han_thu_30","textTraditional":"〔一三〕師古曰：「霸、產出藍田。豐、澇出鄠。長水者，言其源流長也。澇音勞。」","sentenceOrder":176},
  {"id":"s_work_han_thu_30_177","chapterId":"ch_work_han_thu_30","textTraditional":"〔一四〕師古曰：「加謂車及騮駒之屬。」","sentenceOrder":177},
  {"id":"s_work_han_thu_30_178","chapterId":"ch_work_han_thu_30","textTraditional":"〔一五〕蘇林曰：「婿音胥。」韋昭曰：「音蘇計反。」師古曰：「韋說是也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_30_179","chapterId":"ch_work_han_thu_30","textTraditional":"〔一六〕師古曰：「風伯，飛廉也。雨師，屏翳也，一曰屏號。而說者乃謂風伯箕星也，雨師畢星也。此志既言二十八宿，又有風伯、雨師，則知非箕、畢也。九臣、十四臣，不見名數所出。諸布、諸嚴、諸逐，未聞其義。逐字或作逑，音求。屏並音步丁反。」","sentenceOrder":179},
  {"id":"s_work_han_thu_30_180","chapterId":"ch_work_han_thu_30","textTraditional":"〔一七〕韋昭曰：「亳音薄，湯所都也。」臣瓚曰：「濟陰薄縣是也。」師古曰：「杜即京兆杜縣也。此亳非湯都也，不在濟陰。徐廣云京兆杜縣有薄亭，斯近之矣。」","sentenceOrder":180},
  {"id":"s_work_han_thu_30_181","chapterId":"ch_work_han_thu_30","textTraditional":"〔一八〕李奇曰：「菅，茅也。」師古曰：「菅音姦。」","sentenceOrder":181},
  {"id":"s_work_han_thu_30_182","chapterId":"ch_work_han_thu_30","textTraditional":"〔一九〕師古曰：「墨子云周宣王殺杜伯不以罪，後宣王田於圃田，見杜伯執弓矢射，宣王伏弓衣而死，故周人尊其鬼而右之，蓋謂此也。」","sentenceOrder":182},
  {"id":"s_work_han_thu_30_183","chapterId":"ch_work_han_thu_30","textTraditional":"〔二０〕師古曰：「其鬼雖小而有神靈也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_30_184","chapterId":"ch_work_han_thu_30","textTraditional":"唯雍四（時）〔畤〕上帝為尊，其光景動人民，唯陳寶。故雍四畤，春以為歲祠禱，因泮凍，秋涸凍，冬賽祠，五月嘗駒，及四中之月月祠，〔一〕若陳寶節來一祠。春夏用騂，〔二〕秋冬用騮。畤駒四匹，〔三〕木寓龍一駟，〔四〕木寓車馬一駟，各如其帝色。黃犢羔各四，圭幣各有數，皆生瘞埋，無俎豆之具。三年一郊。秦以十月為歲首，故常以十月上宿郊見，〔五〕通權火，〔六〕拜於咸陽之旁，而衣上白，其用如經祠云。〔七〕西畤、畦畤，祠如其故，上不親往。諸此祠皆太祝常主，以歲時奉祠之。至如它名山川諸神及八神之屬，上過則祠，去則已。郡縣遠方祠者，民各自奉祠，不領於天子之祝官。祝官有祕祝，即有災祥，輒祝祠移過於下。","sentenceOrder":184},
  {"id":"s_work_han_thu_30_185","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「中讀曰仲。謂四時之仲月皆祠之。」","sentenceOrder":185},
  {"id":"s_work_han_thu_30_186","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「騂，純赤色也，音先營反。」","sentenceOrder":186},
  {"id":"s_work_han_thu_30_187","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「每畤用駒四匹，而春秋異色。」","sentenceOrder":187},
  {"id":"s_work_han_thu_30_188","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　李奇曰：「寓，寄也，寄生龍形於木也。」師古曰：「一駟亦四龍也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_30_189","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　李奇曰：「上宿，上齋戒也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_30_190","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　張晏曰：「權火，烽火也，狀若井挈皋矣。其法類稱，故謂之權火。欲令光明遠照，通於祀所也。漢祀五畤於雍，五十里一烽火。」如淳曰：「權，舉也。」師古曰：「凡祭祀通舉火者，或以天子不親至祠所而望拜，或以眾祠各處，欲其一時薦饗，宜知早晏，故以火為之節度也。它皆類此。」","sentenceOrder":190},
  {"id":"s_work_han_thu_30_191","chapterId":"ch_work_han_thu_30","textTraditional":"〔七〕　服虔曰：「經，常也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_30_192","chapterId":"ch_work_han_thu_30","textTraditional":"漢興，高祖初起，殺大蛇，有物曰：「蛇，白帝子，而殺者赤帝子也。」〔一〕及高祖禱豐枌榆社，〔二〕侚沛，為沛公，則祀蚩尤，釁鼓旗。遂以十月至霸上，立為漢王。因以十月為年首，色上赤。","sentenceOrder":192},
  {"id":"s_work_han_thu_30_193","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「物謂鬼神也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_30_194","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　鄭氏曰：「枌榆，鄉名也。社在枌榆。」晉灼曰：「枌，白榆也。社在豐東北十五里。」師古曰：「以此樹為社神，因立名也。枌音符云反。」","sentenceOrder":194},
  {"id":"s_work_han_thu_30_195","chapterId":"ch_work_han_thu_30","textTraditional":"二年（冬），東擊項籍而還入關，問：「故秦時上帝祠何帝也？」對曰：「四帝，有白、青、黃、赤帝之祠。」高祖曰：「吾聞天有五帝，而四，何也？」莫知其說。於是高祖曰：「吾知之矣，乃待我而具五也。」乃立黑帝祠，名曰北畤。有司進祠，上不親往。悉召故秦祀官，復置太祝、太宰，如其故儀禮。因令縣為公社。〔一〕下詔曰：「吾甚重祠而敬祭。今上帝之祭及山川諸神當祠者，各以其時禮祠之如故。」","sentenceOrder":195},
  {"id":"s_work_han_thu_30_196","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　李奇曰：「猶官社。」","sentenceOrder":196},
  {"id":"s_work_han_thu_30_197","chapterId":"ch_work_han_thu_30","textTraditional":"後四歲，天下已定，詔御史令豐治枌榆社，常以時，春以羊彘祠之。令祝立蚩尤之祠於長安。長安置祠祀官、女巫。其梁巫祠天、地、天社、天水、房中、（當）〔堂〕上之屬；晉巫祠五帝、東君、雲中君、巫社、巫祠、族人炊之屬；〔一〕秦巫祠杜主、巫保、族纍之屬；〔二〕荊巫祠堂下、巫先、司命、施糜之屬；〔三〕九天巫祠九天：〔四〕皆以歲時祠宮中。其河巫祠河於臨晉，而南山巫祠南山、秦中。秦中者，二世皇帝也。〔五〕各有時日。","sentenceOrder":197},
  {"id":"s_work_han_thu_30_198","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　服虔曰：「東君以下皆神名也。」師古曰：「東君，日也。雲中君謂雲神也。巫社、巫祠，皆古巫之神也。族人炊，古主炊母之神也。炊謂饎爨也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_30_199","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「杜主即上所云五杜主也。巫保、族纍，二神名。纍音力追反。」","sentenceOrder":199},
  {"id":"s_work_han_thu_30_200","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「堂下，在堂之下。巫先，巫之最先者也。司命，說者云文昌第四星也。施糜，其先常施設糜鬻者也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_30_201","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「九天者，謂中央鈞天，東方蒼天，東北旻天，北方玄天，西北幽天，西方浩天，西南朱天，南方炎天，東南陽天也。其說見淮南子。一說云東方旻天，東南陽天，南方赤天，西南朱天，西方成天，西北幽天，北方玄天，東北變天，中央鈞天也。」","sentenceOrder":201},
  {"id":"s_work_han_thu_30_202","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　張晏曰：「以其彊死，魂魄為厲，故祠之。成帝時匡衡奏罷之。」","sentenceOrder":202},
  {"id":"s_work_han_thu_30_203","chapterId":"ch_work_han_thu_30","textTraditional":"其後二歲，或言曰周興而邑立后稷之祠，〔一〕至今血食天下。〔二〕於是高祖制詔御史：「其令天下立靈星祠，〔三〕常以歲時祠以牛。」","sentenceOrder":203},
  {"id":"s_work_han_thu_30_204","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「以其有播種之功，故令天下諸邑皆祠之。」","sentenceOrder":204},
  {"id":"s_work_han_thu_30_205","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「祭有牲牢，故言血食遍天下也。」","sentenceOrder":205},
  {"id":"s_work_han_thu_30_206","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　張晏曰：「龍星左角曰天田，則農祥也。（晨）〔辰〕見而祭之。」","sentenceOrder":206},
  {"id":"s_work_han_thu_30_207","chapterId":"ch_work_han_thu_30","textTraditional":"高祖十年春，有司請令縣常以春二月及臘祠稷以羊彘，民里社各自裁以祠。〔一〕制曰：「可。」","sentenceOrder":207},
  {"id":"s_work_han_thu_30_208","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「隨其祠具之豐儉也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_30_209","chapterId":"ch_work_han_thu_30","textTraditional":"文帝即位十三年，下詔曰：「祕祝之官移過於下，朕甚弗取，其除之。」","sentenceOrder":209},
  {"id":"s_work_han_thu_30_210","chapterId":"ch_work_han_thu_30","textTraditional":"始名山大川在諸侯，諸侯祝各自奉祠，天子官不領。及齊、淮南國廢，令太祝盡以歲時致禮如故。","sentenceOrder":210},
  {"id":"s_work_han_thu_30_211","chapterId":"ch_work_han_thu_30","textTraditional":"明年，以歲比登，〔一〕詔有司增雍五畤路車各一乘，駕被具；〔二〕西畤、畦畤寓車各一乘，寓馬四匹，駕被具；河、湫、漢水，玉加各二；及諸祀皆廣壇場，圭幣俎豆以差加之。","sentenceOrder":211},
  {"id":"s_work_han_thu_30_212","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「年穀頻孰也。」","sentenceOrder":212},
  {"id":"s_work_han_thu_30_213","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「駕車被馬之飾皆具也。被音皮義反。下亦同。」","sentenceOrder":213},
  {"id":"s_work_han_thu_30_214","chapterId":"ch_work_han_thu_30","textTraditional":"魯人公孫臣上書曰：「始秦得水德，及漢受之，推終始傳，〔一〕則漢當土德，土德之應黃龍見。宜改正朔，服色上黃。」時丞相張蒼好律曆，以為漢乃水德之時，河決金隄，其符也。年始冬十月，色外黑內赤，〔二〕與德相應。公孫臣言非是，罷之。明年，黃龍見成紀。〔三〕文帝召公孫臣，拜為博士，與諸生申明土德，草改曆服色事。〔四〕其夏，下詔曰：「有異物之神見於成紀，毋害於民，歲以有年。朕幾郊祀上帝諸神，〔五〕禮官議，毋諱以朕勞。」〔六〕有司皆曰：「古者天子夏親郊祀上帝於郊，故曰郊。」〔七〕於是夏四月，文帝始幸雍郊見五畤，祠衣皆上赤。","sentenceOrder":214},
  {"id":"s_work_han_thu_30_215","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　鄭氏曰：「音亭傳。」師古曰：「音張戀反。謂轉次之。」","sentenceOrder":215},
  {"id":"s_work_han_thu_30_216","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　服虔曰：「十月陰氣在外，〔故外〕黑；陽氣尚伏在地，故內赤也。或曰，十月百草外黑內赤也。」","sentenceOrder":216},
  {"id":"s_work_han_thu_30_217","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「天水之縣也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_30_218","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「草謂創造之。後例皆同也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_30_219","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　師古曰：「幾讀曰冀。」","sentenceOrder":219},
  {"id":"s_work_han_thu_30_220","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　師古曰：「無諱以朕為勞，自言不以為勞也。」晉灼曰：「諱，忌難也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_30_221","chapterId":"ch_work_han_thu_30","textTraditional":"〔七〕　師古曰：「邑外謂之郊。」","sentenceOrder":221},
  {"id":"s_work_han_thu_30_222","chapterId":"ch_work_han_thu_30","textTraditional":"趙人新垣平以望氣見上，言「長安東北有神氣，成五采，若人冠冕焉。或曰東北神明之舍，西方神明之墓也。〔一〕天瑞下，宜立祠上帝，以合符應。」於是作渭陽五帝廟，同宇，〔二〕帝一殿，面五門，各如其帝色。祠所用及儀亦如雍五畤。","sentenceOrder":222},
  {"id":"s_work_han_thu_30_223","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　張晏曰：「神明，日也。日出東北，舍謂陽谷。日沒於西，故曰墓。墓，濛谷也。」師古曰：「此說非也。蓋總言凡神明以東北為居，西方為冢墓之所，故立廟於渭陽者也。」","sentenceOrder":223},
  {"id":"s_work_han_thu_30_224","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「宇謂屋之覆也。言同一屋之下而別為五廟，各立門室也。廟記云五帝廟在長安東北也。」","sentenceOrder":224},
  {"id":"s_work_han_thu_30_225","chapterId":"ch_work_han_thu_30","textTraditional":"明年夏四月，文帝親拜霸渭之會，〔一〕以郊見渭陽五帝。五帝廟臨渭，其北穿蒲池溝水。〔二〕權火舉而祠，若光煇然屬天焉〔三〕。於是貴平至上大夫，賜累千金。而使博士諸生刺六經中作王制，〔四〕謀議巡狩封禪事。","sentenceOrder":225},
  {"id":"s_work_han_thu_30_226","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　如淳曰：「二水之合也。」","sentenceOrder":226},
  {"id":"s_work_han_thu_30_227","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「蒲池，為池而種蒲。蒲字或作滿，言其水滿也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_30_228","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「屬，聯也，音之欲反。」","sentenceOrder":228},
  {"id":"s_work_han_thu_30_229","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「刺，采取之也，音千賜反。」","sentenceOrder":229},
  {"id":"s_work_han_thu_30_230","chapterId":"ch_work_han_thu_30","textTraditional":"文帝出長門，〔一〕若見五人於道北，遂因其直立五帝壇，〔二〕祠以五牢。","sentenceOrder":230},
  {"id":"s_work_han_thu_30_231","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　如淳曰：「亭名也。」","sentenceOrder":231},
  {"id":"s_work_han_thu_30_232","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　鄭氏曰：「因其所立處以立祠也。」師古曰：「直猶當也，當其處。」","sentenceOrder":232},
  {"id":"s_work_han_thu_30_233","chapterId":"ch_work_han_thu_30","textTraditional":"其明年，平使人持玉杯，上書闕下獻之。平言上曰：「闕下有寶玉氣來者。」已視之，果有獻玉杯者，刻曰「人主延壽」。平又言「臣候日再中」。居頃之，日卻復中。於是始更以十七年為元年，令天下大酺。平言曰：「周鼎亡在泗水中，今河決通於泗，臣望東北汾陰直有金寶氣，〔一〕意周鼎其出乎？兆見不迎則不至。」於是上使使治廟汾陰南，臨河，欲祠出周鼎。人有上書告平所言皆詐也。下吏治，誅夷平。〔二〕是後，文帝怠於改正服鬼神之事，〔三〕而渭陽、長門五帝使祠官領，以時致禮，不往焉。","sentenceOrder":233},
  {"id":"s_work_han_thu_30_234","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「汾陰直，謂正當汾陰也。」","sentenceOrder":234},
  {"id":"s_work_han_thu_30_235","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「夷者，平也，謂盡平除其家室宗族。」","sentenceOrder":235},
  {"id":"s_work_han_thu_30_236","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「正，正朔也。服，服色也。正音之成反。」","sentenceOrder":236},
  {"id":"s_work_han_thu_30_237","chapterId":"ch_work_han_thu_30","textTraditional":"明年，匈奴數入邊，〔一〕興兵守御。後歲少不登。數歲而孝景即位。十六年，祠官各以歲時祠如故，無有所興。","sentenceOrder":237},
  {"id":"s_work_han_thu_30_238","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「數音所角反。」","sentenceOrder":238},
  {"id":"s_work_han_thu_30_239","chapterId":"ch_work_han_thu_30","textTraditional":"武帝初即位，尤敬鬼神之祀。漢興已六十餘歲矣，天下艾安〔一〕，縉紳之屬皆望天子封禪改正度也，〔二〕而上鄉儒術，〔三〕招賢良。趙綰、王臧等以文學為公卿，欲議古立明堂城南，以朝諸侯，草巡狩封禪改曆服色事未就。〔四〕竇太后不好儒術，使人微伺趙綰等姦利事，按綰、臧，綰、臧自殺，諸所興為皆廢。六年，竇太后崩。其明年，徵文學之士。","sentenceOrder":239},
  {"id":"s_work_han_thu_30_240","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「艾讀曰乂。乂，治也。漢書皆以艾為乂，其義類此也。」","sentenceOrder":240},
  {"id":"s_work_han_thu_30_241","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「正亦正朔。度，度量也。服色度量，互言之耳。」","sentenceOrder":241},
  {"id":"s_work_han_thu_30_242","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":242},
  {"id":"s_work_han_thu_30_243","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「就，成也。」","sentenceOrder":243},
  {"id":"s_work_han_thu_30_244","chapterId":"ch_work_han_thu_30","textTraditional":"明年，上初至雍，郊見五畤。後常三歲一郊。是時上求神君，舍之上林中磃氏館。〔一〕神君者，長陵女子，以乳死，見神於先後宛若。〔二〕宛若祠之其室，民多往祠。平原君亦往祠，其後子孫以尊顯。〔三〕及上即位，則厚禮置祠之內中。聞其言，不見其人云。","sentenceOrder":244},
  {"id":"s_work_han_thu_30_245","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　如淳曰：「磃音蹄。」鄭氏曰：「音斯。」師古曰：「鄭音是也。其字從石從虒。」","sentenceOrder":245},
  {"id":"s_work_han_thu_30_246","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　孟康曰：「產乳而死也。兄弟妻相謂先後。宛若，字也。」師古曰：「先音蘇見反。後音胡搆反。古謂之娣姒，今關中俗呼為先後，吳楚俗呼之為妯娌，音軸里。」","sentenceOrder":246},
  {"id":"s_work_han_thu_30_247","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　應劭曰：「平原君，武帝外祖母也。」","sentenceOrder":247},
  {"id":"s_work_han_thu_30_248","chapterId":"ch_work_han_thu_30","textTraditional":"是時，李少君亦以祠灶、穀道、卻老方見上，〔一〕上尊之。少君者，故深澤侯人，主方。〔二〕匿其年及所生長。〔三〕常自謂七十，能使物，卻老。〔四〕其游以方遍諸侯。無妻子。人聞其能使物及不死，更餽遺之，〔五〕常餘金錢衣食。人皆以為不治產業而饒給，〔六〕又不知其何所人，愈信，爭事之。少君資好方，善為巧發奇中。〔七〕常從武安侯宴，坐中有年九十餘老人，少君乃言與其大父游射處，老人為兒從其大父，識其處，〔八〕一坐盡驚。少君見上，上有故銅器，問少君。少君曰：「此器齊桓公十年陳於柏寢。」〔九〕已而按其刻，果齊桓公器。〔一０〕一宮盡駭，以為少君神，數百歲人也。少君言上：「祠灶皆可致物，〔一一〕致物而丹沙可化為黃金，黃金成以為飲食器則益壽，益壽而海中蓬萊僊者乃可見之，以封禪則不死，黃帝是也。臣嘗游海上，見安期生，〔一二〕安期生食臣棗，大如瓜。〔一三〕安期生僊者，通蓬萊中，合則見人，不合則隱。」〔一四〕於是天子始親祠灶，遣方士入海求蓬萊安期生之屬，而事化丹沙諸藥齊為黃金矣。〔一五〕久之，少君病死。天子以為化去不死也，使黃錘史寬舒受其方，〔一六〕而海上燕齊怪迂之方士多更來言神事矣。〔一七〕","sentenceOrder":248},
  {"id":"s_work_han_thu_30_249","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　如淳曰：「祠灶可以致福。」李奇曰：「穀道，辟穀不食之道也。」","sentenceOrder":249},
  {"id":"s_work_han_thu_30_250","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　如淳曰：「侯家人，主方藥也。」","sentenceOrder":250},
  {"id":"s_work_han_thu_30_251","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「生長，謂其郡縣所屬及居止處。」","sentenceOrder":251},
  {"id":"s_work_han_thu_30_252","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　如淳曰：「物謂鬼物也。」","sentenceOrder":252},
  {"id":"s_work_han_thu_30_253","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　師古曰：「更音工衡反。」","sentenceOrder":253},
  {"id":"s_work_han_thu_30_254","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　師古曰：「給，足也。」","sentenceOrder":254},
  {"id":"s_work_han_thu_30_255","chapterId":"ch_work_han_thu_30","textTraditional":"〔七〕　如淳曰：「時時發言有所中。」師古曰：「中音竹仲反。」","sentenceOrder":255},
  {"id":"s_work_han_thu_30_256","chapterId":"ch_work_han_thu_30","textTraditional":"〔八〕　師古曰：「識，記也，音式志反。」","sentenceOrder":256},
  {"id":"s_work_han_thu_30_257","chapterId":"ch_work_han_thu_30","textTraditional":"〔九〕　臣瓚曰：「晏子書柏寢，臺名也。」師古曰：「以柏木為寢室於臺之上。」","sentenceOrder":257},
  {"id":"s_work_han_thu_30_258","chapterId":"ch_work_han_thu_30","textTraditional":"〔一０〕師古曰：「刻謂器上所銘記。」","sentenceOrder":258},
  {"id":"s_work_han_thu_30_259","chapterId":"ch_work_han_thu_30","textTraditional":"〔一一〕師古曰：「物亦謂鬼物。」","sentenceOrder":259},
  {"id":"s_work_han_thu_30_260","chapterId":"ch_work_han_thu_30","textTraditional":"〔一二〕服虔曰：「古之真人也。」師古曰：「列仙傳云安期生琅邪人，賣藥東海邊，時人皆言千歲也。」","sentenceOrder":260},
  {"id":"s_work_han_thu_30_261","chapterId":"ch_work_han_thu_30","textTraditional":"〔一三〕師古曰：「食讀曰飤。」","sentenceOrder":261},
  {"id":"s_work_han_thu_30_262","chapterId":"ch_work_han_thu_30","textTraditional":"〔一四〕師古曰：「合謂道相合。」","sentenceOrder":262},
  {"id":"s_work_han_thu_30_263","chapterId":"ch_work_han_thu_30","textTraditional":"〔一五〕師古曰：「齊，藥之分齊也，音才計反。」","sentenceOrder":263},
  {"id":"s_work_han_thu_30_264","chapterId":"ch_work_han_thu_30","textTraditional":"〔一六〕孟康曰：「二人皆方士也。」師古曰：「錘音直垂反。」","sentenceOrder":264},
  {"id":"s_work_han_thu_30_265","chapterId":"ch_work_han_thu_30","textTraditional":"〔一七〕師古曰：「更音工衡反。」","sentenceOrder":265},
  {"id":"s_work_han_thu_30_266","chapterId":"ch_work_han_thu_30","textTraditional":"亳人謬忌奏祠泰一方，〔一〕曰：「天神貴者泰一，泰一佐曰五帝。〔二〕古者天子以春秋祭泰一東南郊，日一太牢，七日，〔三〕為壇開八通之鬼道。」於是，天子令太祝立其祠長安城東南郊，常奉祠如忌方。其後，人上書言「古者天子三年一用太牢祠三一：天一、地一、泰一。」天子許之，令太祝領祠之於忌泰一壇上，如其方。後人復有言「古天子常以春解祠，祠黃帝用一梟、破鏡；〔四〕冥羊用羊祠；馬行用一青牡馬；泰一、皋山山君用牛；武夷君用乾魚；陰陽使者以一牛。」〔五〕令祠官領之如其方，而祠泰一於忌泰一壇旁。","sentenceOrder":266},
  {"id":"s_work_han_thu_30_267","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　如淳曰：「亳亦薄也，下所謂薄忌也。」晉灼曰：「濟陰薄縣人也。」","sentenceOrder":267},
  {"id":"s_work_han_thu_30_268","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「謂青帝靈威仰，赤帝赤熛怒，白帝白招矩，黑帝協光紀，黃帝含樞紐也。一說蒼帝名靈府，赤帝名文祖，白帝名顯紀，黑帝名玄矩，黃帝名神斗。」","sentenceOrder":268},
  {"id":"s_work_han_thu_30_269","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「每日以一太牢，凡七日祭也。」","sentenceOrder":269},
  {"id":"s_work_han_thu_30_270","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　張晏曰：「黃帝，五帝之首也，歲之始也。梟，惡逆之鳥。方士虛誕，云以歲始祓除凶災，令神仙之帝食惡逆之物，使天下為逆者破滅訖竟，無有遺育也。」孟康曰：「梟，鳥名，食母。破鏡，獸名，食父。黃帝欲絕其類，使百吏祠皆用之。破鏡如貙而虎眼。」如淳曰：「漢使東郡送梟，五月五日作梟羹以賜百官。以其惡鳥，故食之也。」師古曰：「解祠者，謂祠祭以解罪求福。」","sentenceOrder":270},
  {"id":"s_work_han_thu_30_271","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　孟康曰：「陰陽之神也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_30_272","chapterId":"ch_work_han_thu_30","textTraditional":"後二年，郊雍，獲一角獸，若麃然。〔一〕有司曰：「陛下肅祗郊祀，上帝報享，錫一角獸，蓋麟云。」於是以薦五畤，畤加一牛以燎。賜諸侯白金，以風符應合於天也。〔二〕於是濟北王以為天子且封禪，上書獻泰山及其旁邑，天子以它縣償之。常山王有罪，〈興，中“八改仓”〉〔三〕，天子封其弟真定，以續先王祀，而以常山為郡。然後五嶽皆在天子之郡。","sentenceOrder":272},
  {"id":"s_work_han_thu_30_273","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「麃，鹿屬也，形似獐，牛尾，一角，音蒲交反。」","sentenceOrder":273},
  {"id":"s_work_han_thu_30_274","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　晉灼曰：「符，瑞也。」臣瓚曰：「風示諸侯以此符瑞之應也。」","sentenceOrder":274},
  {"id":"s_work_han_thu_30_275","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「〈興，中“八改仓”〉與遷同也。」","sentenceOrder":275},
  {"id":"s_work_han_thu_30_276","chapterId":"ch_work_han_thu_30","textTraditional":"明年，齊人少翁以方見上。上有所幸李夫人，夫人卒，少翁以方蓋夜致夫人及灶鬼之貌云，天子自帷中望見焉。乃拜少翁為文成將軍，賞賜甚多，以客禮禮之。文成言：「上即欲與神通，宮室被服非象神，神物不至。」乃作畫雲氣車，及各以勝日〔一〕駕車辟惡鬼。又作甘泉宮，中為臺室，畫天地泰一諸鬼神，而置祭具以致天神。居歲餘，其方益衰，神不至。乃為帛書以飯牛，〔二〕陽不知，言此牛腹中有奇（書）。殺視得書，書言甚怪。天子識其手，〔三〕問之，果為書。於是誅文成將軍，隱之。","sentenceOrder":276},
  {"id":"s_work_han_thu_30_277","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　服虔曰：「甲乙五行相克之日。」如淳曰：「如火勝金，用丙丁日，不用庚辛也。」","sentenceOrder":277},
  {"id":"s_work_han_thu_30_278","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「謂雜草以飯牛也，音扶晚反。」","sentenceOrder":278},
  {"id":"s_work_han_thu_30_279","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「手謂所書手跡。」","sentenceOrder":279},
  {"id":"s_work_han_thu_30_280","chapterId":"ch_work_han_thu_30","textTraditional":"其後又作柏梁、銅柱、承露僊人掌之屬矣。〔一〕","sentenceOrder":280},
  {"id":"s_work_han_thu_30_281","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　蘇林曰：「仙人以手掌擎盤承甘露。」師古曰：「三輔故事云建章宮承露盤高二十丈，大七圍，以銅為之，上有仙人掌承露，和玉屑飲之。蓋張衡西京賦所云『立修莖之仙掌，承雲表之清露，屑瓊蕊以朝餐，必性命之可度』也。」","sentenceOrder":281},
  {"id":"s_work_han_thu_30_282","chapterId":"ch_work_han_thu_30","textTraditional":"文成死明年，天子病鼎湖甚，〔一〕巫醫無所不致。游水發根言上郡有巫，病而鬼下之。〔二〕上召置祠之甘泉。及病，使人問神君，神君言曰：「天子無憂病。病少瘉，強與我會甘泉。」於是上病瘉，遂起，幸甘泉，病良已。〔三〕大赦，置壽宮神君。〔四〕神君最貴者曰太一，其佐曰太禁、司命之屬，皆從之。非可得見，聞其言，言與人音等。時去時來，來則風肅然。居室帷中，時晝言，然常以夜。天子祓，然後入。〔五〕因巫為主人，關飲食，所欲言，行下〔六〕。又置壽宮、北宮，張羽旗，設共具，〔七〕以禮神君。神君所言，上使受書，其名曰「畫法」。〔八〕其所言，世俗之所知也，無絕殊者，而天子心獨憙。其事祕，世莫知也。〔九〕","sentenceOrder":282},
  {"id":"s_work_han_thu_30_283","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　晉灼曰：「黃圖宮名，在京兆。地理志，湖本在京兆，後分屬弘農也。」","sentenceOrder":283},
  {"id":"s_work_han_thu_30_284","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　服虔曰：「游水，縣名。發根，人姓名。」晉灼曰：「地理志游水，水名，在臨淮淮浦也。」師古曰：「二說皆非也。游水，姓也。發根，名也。蓋因水為姓也。本嘗遇病，而鬼下之，故為巫也。」","sentenceOrder":284},
  {"id":"s_work_han_thu_30_285","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　孟康曰：「良已，善已，謂瘉也。」","sentenceOrder":285},
  {"id":"s_work_han_thu_30_286","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　孟康曰：「更立此宮也。」臣瓚曰：「壽宮，奉神之宮也。楚辭曰『蹇將澹兮壽宮』也。」","sentenceOrder":286},
  {"id":"s_work_han_thu_30_287","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　孟康曰：「崇絜自除祓，然後入也。」師古曰：「祓音發勿反。」","sentenceOrder":287},
  {"id":"s_work_han_thu_30_288","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　李奇曰：「神所欲言，上輒為下之也。」晉灼曰：「神君所言行下於巫。」師古曰：「晉說是也。」","sentenceOrder":288},
  {"id":"s_work_han_thu_30_289","chapterId":"ch_work_han_thu_30","textTraditional":"〔七〕　師古曰：「共讀曰供，音居用反。」","sentenceOrder":289},
  {"id":"s_work_han_thu_30_290","chapterId":"ch_work_han_thu_30","textTraditional":"〔八〕　孟康曰：「策畫之法也。」","sentenceOrder":290},
  {"id":"s_work_han_thu_30_291","chapterId":"ch_work_han_thu_30","textTraditional":"〔九〕　師古曰：「憙讀曰喜。喜，好也，音許吏反。」","sentenceOrder":291},
  {"id":"s_work_han_thu_30_292","chapterId":"ch_work_han_thu_30","textTraditional":"後三年，有司言元宜以天瑞，不宜以一二數。〔一〕一元曰「建」，〔二〕二元以長星曰「光」，〔三〕今郊得一角獸曰「狩」云。〔四〕","sentenceOrder":292},
  {"id":"s_work_han_thu_30_293","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　蘇林曰：「得諸瑞以名年。」","sentenceOrder":293},
  {"id":"s_work_han_thu_30_294","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　蘇林曰：「建元元年是。」","sentenceOrder":294},
  {"id":"s_work_han_thu_30_295","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　蘇林曰：「以有長星之光，故曰元光元年。」","sentenceOrder":295},
  {"id":"s_work_han_thu_30_296","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　如淳曰：「改元狩元年。」","sentenceOrder":296},
  {"id":"s_work_han_thu_30_297","chapterId":"ch_work_han_thu_30","textTraditional":"其明年，天子郊雍，曰：「今上帝朕親郊，而后土無祀，則禮不答也。」〔一〕有司與太史令談、祠官寬舒議：〔二〕「天地牲，角繭栗。〔三〕今陛下親祠后土，后土宜於澤中圜丘為五壇，壇一黃犢牢具。已祠盡瘞，而從祠衣上黃。」〔四〕於是天子東幸汾陰。汾陰男子公孫滂洋等見汾旁有光如絳，〔五〕上遂立后土祠於汾陰脽上，〔六〕如寬舒等議。上親望拜，如上帝禮。禮畢，天子遂至滎陽。還過雒陽，下詔封周後，令奉其祀。語在武紀。上始巡幸郡縣，寖尋於泰山矣。〔七〕","sentenceOrder":297},
  {"id":"s_work_han_thu_30_298","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「答，對也。郊天而不祀地，失對偶之義。一曰，闕地祇之祀，故不為神所答應也。」","sentenceOrder":298},
  {"id":"s_work_han_thu_30_299","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「談即司馬談也。」","sentenceOrder":299},
  {"id":"s_work_han_thu_30_300","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「牛角之形或如繭，或如栗，言其小。」","sentenceOrder":300},
  {"id":"s_work_han_thu_30_301","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「侍祠之人皆著黃衣也。」","sentenceOrder":301},
  {"id":"s_work_han_thu_30_302","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　師古曰：「滂音普郎反。洋音羊也。」","sentenceOrder":302},
  {"id":"s_work_han_thu_30_303","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　師古曰：「脽音誰。解在武紀。」","sentenceOrder":303},
  {"id":"s_work_han_thu_30_304","chapterId":"ch_work_han_thu_30","textTraditional":"〔七〕　鄭玄曰：「尋，用也。」晉灼曰：「尋，遂往之意也。」師古曰：「二說皆非也。寖，漸也。尋，就也。」","sentenceOrder":304},
  {"id":"s_work_han_thu_30_305","chapterId":"ch_work_han_thu_30","textTraditional":"其春，樂成侯（登）上書言欒大。欒大，膠東宮人，〔一〕故嘗與文成將軍同師，已而為膠東王尚方。〔二〕而樂成侯姊為康王后，〔三〕無子。王死，它姬子立為王，而康后有淫行，與王不相中，相危以法。〔四〕康后聞文成死，而欲自媚於上，乃遣欒大入，因樂成侯求見言方。〔五〕天子既誅文成，後悔其方不盡，及見欒大，大說。〔六〕大為人長美，〔七〕言多方略，而敢為大言，處之不疑。大言曰：「臣常往來海中，見安期、羨門之屬，顧以臣為賤，不信臣。〔八〕又以為康王諸侯耳，不足與方。臣數以言康王，康王又不用臣。臣之師曰：『黃金可成，而河決可塞，不死之藥可得，僊人可致也。』然臣恐效文成，則方士皆掩口，惡敢言方哉！」〔九〕上曰：「文成食馬肝死耳。子誠能修其方，我何愛乎！」大曰：「臣師非有求人，人者求之。陛下必欲致之，則貴其使者，令為親屬，以客禮待之，勿卑，使各佩其信印，乃可使通言於神人。神人尚肯邪不邪，尊其使然後可致也。」於是上使驗小方，鬥棋，棋自相觸擊。","sentenceOrder":305},
  {"id":"s_work_han_thu_30_306","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　服虔曰：「王家人。」","sentenceOrder":306},
  {"id":"s_work_han_thu_30_307","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「主方藥。」","sentenceOrder":307},
  {"id":"s_work_han_thu_30_308","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　孟康曰：「膠東王后也。」","sentenceOrder":308},
  {"id":"s_work_han_thu_30_309","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「不相可也。相危以法，謂以罪法相欲傾危也。中音竹仲反。」","sentenceOrder":309},
  {"id":"s_work_han_thu_30_310","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　師古曰：「言神仙之方。」","sentenceOrder":310},
  {"id":"s_work_han_thu_30_311","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　師古曰：「說讀曰悅。」","sentenceOrder":311},
  {"id":"s_work_han_thu_30_312","chapterId":"ch_work_han_thu_30","textTraditional":"〔七〕　師古曰：「善為甘美之言也。」","sentenceOrder":312},
  {"id":"s_work_han_thu_30_313","chapterId":"ch_work_han_thu_30","textTraditional":"〔八〕　師古曰：「顧，念也。」","sentenceOrder":313},
  {"id":"s_work_han_thu_30_314","chapterId":"ch_work_han_thu_30","textTraditional":"〔九〕　師古曰：「惡音烏，謂於何也。」","sentenceOrder":314},
  {"id":"s_work_han_thu_30_315","chapterId":"ch_work_han_thu_30","textTraditional":"是時，上方憂河決而黃金不就，〔一〕乃拜大為五利將軍。居月餘，得四印；得天士將軍、地士將軍、大通將軍印。制詔御史：「昔禹疏九河，決四瀆。間者，河溢皋陸，隄繇不息。〔二〕朕臨天下二十有八年，天若遺朕士而大通焉。乾稱『飛龍』，『鴻漸于般』〔三〕，朕意庶幾與焉。〔四〕其以二千戶封地士將軍大為樂通侯。」賜列侯甲第，童千人。乘輿斥車馬帷帳器物以充其家。〔五〕又以衛長公主妻之，〔六〕齎金十萬斤，更名其邑曰當利公主。天子親如五利之弟，使者存問共給，相屬於道。〔七〕自大主將相以下，皆置酒其家，〔八〕獻遺之。天子又刻玉印曰「天道將軍」，使使衣羽衣，夜立白茅上，五利將軍亦衣羽衣，立白茅上受印，以視不臣也。〔九〕而佩「天道」者，且為天子道天神也。〔一０〕於是五利常夜祠其家，欲以下神。後裝治行，東入海求其師云。大見數月，佩六印，貴震天下，而海上燕齊之間，莫不搤掔〔一一〕而自言有禁方能神僊矣。","sentenceOrder":315},
  {"id":"s_work_han_thu_30_316","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「鑄黃金不成。」","sentenceOrder":316},
  {"id":"s_work_han_thu_30_317","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「皋，水旁地。廣平曰陸。言水汎溢，自皋及陸，而築作隄防，徭役甚多，不暇休息。」","sentenceOrder":317},
  {"id":"s_work_han_thu_30_318","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　孟康曰：「般，水涯堆也。漸，進也。武帝云得欒大如鴻進於般，一舉千里。得道若飛龍在天。」師古曰：「飛龍在天，乾卦九五爻辭也。鴻漸于般，漸卦六二爻辭也。般，山石之安者。」","sentenceOrder":318},
  {"id":"s_work_han_thu_30_319","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「與讀曰豫。」","sentenceOrder":319},
  {"id":"s_work_han_thu_30_320","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　師古曰：「斥，不用者也。」","sentenceOrder":320},
  {"id":"s_work_han_thu_30_321","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　孟康曰：「衛太子妺。」如淳曰：「衛太子姊也。」師古曰：「外戚傳云子夫生三女，元朔三年生男據。是則太子之姊也。孟說非也。」","sentenceOrder":321},
  {"id":"s_work_han_thu_30_322","chapterId":"ch_work_han_thu_30","textTraditional":"〔七〕　師古曰：「共讀曰供。屬，及也，音之欲反。」","sentenceOrder":322},
  {"id":"s_work_han_thu_30_323","chapterId":"ch_work_han_thu_30","textTraditional":"〔八〕　韋昭曰：「大主，武帝姑，竇太后之女也。」","sentenceOrder":323},
  {"id":"s_work_han_thu_30_324","chapterId":"ch_work_han_thu_30","textTraditional":"〔九〕　師古曰：「羽衣，以鳥羽為衣，取其神僊飛翔之意也。視讀曰示。」","sentenceOrder":324},
  {"id":"s_work_han_thu_30_325","chapterId":"ch_work_han_thu_30","textTraditional":"〔一０〕師古曰：「為音于偽反。道天神，道讀曰導。」","sentenceOrder":325},
  {"id":"s_work_han_thu_30_326","chapterId":"ch_work_han_thu_30","textTraditional":"〔一一〕師古曰：「搤，捉持也。掔，古手腕之字也。搤音厄。」","sentenceOrder":326},
  {"id":"s_work_han_thu_30_327","chapterId":"ch_work_han_thu_30","textTraditional":"其夏六月，汾陰巫錦〔一〕為民祠魏脽后土營旁，〔二〕見地如鉤狀，掊視得鼎。〔三〕鼎大異於眾鼎，文鏤無款識，〔四〕怪之，言吏。吏告河東太守勝，勝以聞。天子使驗問巫得鼎無姦詐，乃以禮祠，迎鼎至甘泉，從上行，薦之。〔五〕至中山，晏溫，〔六〕有黃雲焉。有鹿過，上自射之，因之以祭云。至長安，公卿大夫皆議尊寶鼎。天子曰：「間者河溢，歲數不登，故巡祭后土，祈為百姓育穀。今年豐楙未報，鼎曷為出哉？」〔七〕有司皆言：「聞昔泰帝興神鼎一，〔八〕一者一統，天地萬物所繫象也。黃帝作寶鼎三，象天地人。禹收九牧之金，〔九〕鑄九鼎，象九州。皆嘗鬺享上帝鬼神。〔一０〕其空足曰鬲，〔一一〕以象三德，〔一二〕饗承天祜。〔一三〕夏德衰，鼎遷於殷；殷德衰，鼎遷於周；周德衰，鼎遷於秦；秦德衰，宋之社亡，鼎乃淪伏而不見。周頌曰：『自堂徂基，自羊徂牛，鼐鼎及鼒；不吴不敖，胡考之休。』〔一四〕今鼎至甘泉，以光潤龍變，承休無疆。合茲中山，有黃白雲降，〔一五〕蓋若獸為符，〔一六〕路弓乘矢，集獲壇下，〔一七〕報祠大亨。唯受命而帝者心知其意而合德焉。〔一八〕鼎宜視宗禰（廣）〔廟〕，臧於帝庭，以合明應。」〔一九〕制曰：「可。」","sentenceOrder":327},
  {"id":"s_work_han_thu_30_328","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　應劭曰：「錦，巫名。」","sentenceOrder":328},
  {"id":"s_work_han_thu_30_329","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　應劭曰：「魏，故魏國也。」師古曰：「汾脽本魏地之境，故云魏脽也。營謂祠之兆域也。」","sentenceOrder":329},
  {"id":"s_work_han_thu_30_330","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「掊謂手杷土也，音蒲溝反。杷音蒲巴反，其字從木。」","sentenceOrder":330},
  {"id":"s_work_han_thu_30_331","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　韋昭曰：「款，刻也。」師古曰：「識，記也，音式志反。其下美陽鼎亦同也。」","sentenceOrder":331},
  {"id":"s_work_han_thu_30_332","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　如淳曰：「以鼎從行上甘泉，將薦之於天。」師古曰：「上音時掌反。」","sentenceOrder":332},
  {"id":"s_work_han_thu_30_333","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　如淳曰：「三輔謂日出清濟為晏。晏而溫，乃有黃雲，故為異也。」師古曰：「中讀曰仲。即今雲陽之中山也。下云『合茲中山』，亦同也。」","sentenceOrder":333},
  {"id":"s_work_han_thu_30_334","chapterId":"ch_work_han_thu_30","textTraditional":"〔七〕　師古曰：「楙，美也，言稼穡美也。未報者，獲年豐而未報賽也。一曰，雖祈穀而未獲年豐之（穀）〔報〕也。其下張敞引此詔文云『穀嗛未報』，嗛者，少也。」","sentenceOrder":334},
  {"id":"s_work_han_thu_30_335","chapterId":"ch_work_han_thu_30","textTraditional":"〔八〕　師古曰：「泰帝者，即泰昊伏羲氏也。」","sentenceOrder":335},
  {"id":"s_work_han_thu_30_336","chapterId":"ch_work_han_thu_30","textTraditional":"〔九〕　師古曰：「九牧，九州之牧也。」","sentenceOrder":336},
  {"id":"s_work_han_thu_30_337","chapterId":"ch_work_han_thu_30","textTraditional":"〔一０〕服虔曰：「以享祀上帝也。」師古曰：「鬺亨一也。鬺亨，煮而祀也。韓詩采蘋曰：『于以鬺之，唯錡及釜。』亨音普庚反。」","sentenceOrder":337},
  {"id":"s_work_han_thu_30_338","chapterId":"ch_work_han_thu_30","textTraditional":"〔一一〕蘇林曰：「鬲音歷。足中空不實者，名曰鬲也。」","sentenceOrder":338},
  {"id":"s_work_han_thu_30_339","chapterId":"ch_work_han_thu_30","textTraditional":"〔一二〕如淳曰：「鼎有三足故也。三德，三正之德。」師古曰：「如說非也。三德，一曰正直，二曰剛克，三曰柔克。事見周書洪範。」","sentenceOrder":339},
  {"id":"s_work_han_thu_30_340","chapterId":"ch_work_han_thu_30","textTraditional":"〔一三〕師古曰：「祜，福也，音怙。」","sentenceOrder":340},
  {"id":"s_work_han_thu_30_341","chapterId":"ch_work_han_thu_30","textTraditional":"〔一四〕師古曰：「周頌絲衣之詩也。基，門塾之基也。鼎絕大者謂之鼐，圜弇上謂之鼒。吴，讙譁也。敖，慢也。考，壽也。休，美也。言執祭事者，或升堂室，或之門塾，視羊牛之牲，及舉大小之鼎，告其致絜，神降之福，故獲壽考之美，曰何壽之美！何壽之美者，歎之之言也。鼐音乃代反。鼒音茲。敖讀曰傲。」","sentenceOrder":341},
  {"id":"s_work_han_thu_30_342","chapterId":"ch_work_han_thu_30","textTraditional":"〔一五〕師古曰：「言鼎至甘泉之後，光潤變見，若龍之神，能幽能明，能小能大，乘此休福，無窮竟也。有黃白雲降，與初至仲山黃雲之瑞相合也。」","sentenceOrder":342},
  {"id":"s_work_han_thu_30_343","chapterId":"ch_work_han_thu_30","textTraditional":"〔一六〕服虔曰：「雲若獸在車蓋也。」晉灼曰：「蓋，辭也。符謂鹿也。」師古曰：「二說非也。蓋，發語辭也。言甘泉之雲又若獸形，以為符瑞也。」","sentenceOrder":343},
  {"id":"s_work_han_thu_30_344","chapterId":"ch_work_han_thu_30","textTraditional":"〔一七〕李奇曰：「宜言盧弓。」韋昭曰：「路，大也。四矢曰乘。」師古曰：「韋說是也。又於壇下獲弓矢之應。」","sentenceOrder":344},
  {"id":"s_work_han_thu_30_345","chapterId":"ch_work_han_thu_30","textTraditional":"〔一八〕服虔曰：「高祖受命知之，宜見鼎於其廟也。」師古曰：「合德，謂與天合德。」","sentenceOrder":345},
  {"id":"s_work_han_thu_30_346","chapterId":"ch_work_han_thu_30","textTraditional":"〔一九〕師古曰：「視讀曰示。宗謂先帝有德可尊者也。禰，父廟也。帝庭，甘泉天神之庭。」","sentenceOrder":346},
  {"id":"s_work_han_thu_30_347","chapterId":"ch_work_han_thu_30","textTraditional":"入海求蓬萊者，言蓬萊不遠，而不能至者，殆不見其氣。上乃遣望氣佐候其氣云。","sentenceOrder":347},
  {"id":"s_work_han_thu_30_348","chapterId":"ch_work_han_thu_30","textTraditional":"其秋，上雍，且郊。〔一〕或曰「五帝，泰一之佐也，宜立泰一而上親郊之」。上疑未定。","sentenceOrder":348},
  {"id":"s_work_han_thu_30_349","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「雍地形高，故云上也，音時掌反。」","sentenceOrder":349},
  {"id":"s_work_han_thu_30_350","chapterId":"ch_work_han_thu_30","textTraditional":"齊人公孫卿曰：「今年得寶鼎，其冬辛巳朔旦冬至，與黃帝時等。」〔一〕卿有札書〔二〕曰：「黃帝得寶鼎冕候，問於鬼臾區〔三〕，鬼臾區對曰：『黃帝得寶鼎神策，是歲己酉朔旦冬至，得天之紀，終而復始。』於是黃帝迎日推策，〔四〕後率二十歲復朔旦冬至，凡二十推，三百八十年，黃帝僊登于天。」卿因所忠欲奏之。〔五〕所忠視其書不經，〔六〕疑其妄言，謝曰：「寶鼎事已決矣。尚何以為！」〔七〕卿因嬖人奏之。上大說，〔八〕乃召問卿。對曰：「受此書申公，申公已死。」上曰：「申公何人也？」卿曰：「齊人，與安期生通，受黃帝言，無書，獨有此鼎書。曰『漢興復當黃帝之時。』曰『漢之聖者，在高祖之孫且曾孫也。寶鼎出而與神通，封禪。封禪七十二王，唯黃帝得上泰山封。』申公曰：『漢帝亦當上封（禪），〔上〕封（禪）則能僊登天矣。黃帝萬諸侯，而神靈之封君七千。〔九〕天下名山八，而三在蠻夷，五在中國。中國華山、首山、太室山、泰山、東萊山，此五山黃帝之所常游，與神會。黃帝且戰且學僊，患百姓非其道，乃斷斬非鬼神者。百餘歲然後得與神通。黃帝郊雍上帝，宿三月。鬼臾區號大鴻，死葬雍，故鴻冢是也。〔一０〕其後黃帝接萬靈明庭。明庭者，甘泉也。所謂寒門者，谷口也。〔一一〕黃帝采首山銅，鑄鼎於荊山下。〔一二〕鼎既成，有龍垂胡敘下迎黃帝。〔一三〕黃帝上騎，群臣後宮從上龍七十餘人，龍乃〔上〕去。餘小臣不得上，乃悉持龍敘，龍敘拔，墯，墯黃帝之弓。百姓卬望〔一四〕黃帝既上天，乃抱其弓與龍敘號，故後世因名其處曰鼎湖，其弓曰烏號。』」於是天子曰：「嗟乎！誠得如黃帝，吾視去妻子如脫屣耳。」〔一五〕拜卿為郎，使東候神於太室。","sentenceOrder":350},
  {"id":"s_work_han_thu_30_351","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「等，同也。」","sentenceOrder":351},
  {"id":"s_work_han_thu_30_352","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「札，木簡之薄小者也。」","sentenceOrder":352},
  {"id":"s_work_han_thu_30_353","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「鬼臾區，黃帝臣也。藝文志云鬼容區，而此志作臾區，臾、容聲相近，蓋一也。今流俗書本臾字作申，非也。」","sentenceOrder":353},
  {"id":"s_work_han_thu_30_354","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　晉灼曰：「迎，數之也。」臣瓚曰：「日月朔望未來而推之，故曰迎日。」","sentenceOrder":354},
  {"id":"s_work_han_thu_30_355","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　師古曰：「所忠，人姓名也。解在食貨志。」","sentenceOrder":355},
  {"id":"s_work_han_thu_30_356","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　師古曰：「不合經典也。」","sentenceOrder":356},
  {"id":"s_work_han_thu_30_357","chapterId":"ch_work_han_thu_30","textTraditional":"〔七〕　師古曰：「謂不須更言之。」","sentenceOrder":357},
  {"id":"s_work_han_thu_30_358","chapterId":"ch_work_han_thu_30","textTraditional":"〔八〕　師古曰：「說讀曰悅。」","sentenceOrder":358},
  {"id":"s_work_han_thu_30_359","chapterId":"ch_work_han_thu_30","textTraditional":"〔九〕　應劭曰：「黃帝時，諸侯會封禪者七千人也。」李奇曰：「說仙道得封者七千國也。」張晏曰：「神靈之封，謂山川之守也。」師古曰：「張說是也。山川之守謂尊山川之神令主祭祀也，即國語所云『汪芒氏之君守封嵎之山』也。」","sentenceOrder":359},
  {"id":"s_work_han_thu_30_360","chapterId":"ch_work_han_thu_30","textTraditional":"〔一０〕蘇林曰：「今雍有鴻冢。」","sentenceOrder":360},
  {"id":"s_work_han_thu_30_361","chapterId":"ch_work_han_thu_30","textTraditional":"〔一一〕服虔曰：「黃帝升仙之處也。」師古曰：「谷口，仲山之谷口也，漢時為縣，今呼之治谷是也。以仲山之北寒涼，故謂此谷為寒門也。」","sentenceOrder":361},
  {"id":"s_work_han_thu_30_362","chapterId":"ch_work_han_thu_30","textTraditional":"〔一二〕晉灼曰：「地理志首山屬河東蒲阪，荊山在馮翊懷德縣也。」","sentenceOrder":362},
  {"id":"s_work_han_thu_30_363","chapterId":"ch_work_han_thu_30","textTraditional":"〔一三〕師古曰：「胡謂頸下垂肉也。敘，其毛也，音人占反。」","sentenceOrder":363},
  {"id":"s_work_han_thu_30_364","chapterId":"ch_work_han_thu_30","textTraditional":"〔一四〕師古曰：「卬讀曰仰。」","sentenceOrder":364},
  {"id":"s_work_han_thu_30_365","chapterId":"ch_work_han_thu_30","textTraditional":"〔一五〕師古曰：「屣，小履。脫屣者，言其便易，無所顧也。屣音山爾反。」","sentenceOrder":365},
  {"id":"s_work_han_thu_30_366","chapterId":"ch_work_han_thu_30","textTraditional":"上遂郊雍，至隴西，登空桐，幸甘泉。令祠官寬舒等具泰一祠壇，祠壇放亳忌泰一壇，三陔。〔一〕五帝壇環居其下，各如其方。黃帝西南，除八通鬼道。〔二〕泰一所用，如雍一畤物，而加醴棗脯之屬，殺一氂牛〔三〕以為俎豆牢具。而五帝獨有俎豆醴進。〔四〕其下四方地，為腏，食群神從者及北斗云。〔五〕已祠，胙餘皆燎之。〔六〕其牛色白，白鹿居其中，彘在鹿中，鹿中水而酒之。〔七〕祭日以牛，祭月以羊彘特。〔八〕泰一祝宰則衣紫及繡。五帝各如其色，日赤，月白。","sentenceOrder":366},
  {"id":"s_work_han_thu_30_367","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「陔，重也。三陔，三重壇也。音該。」","sentenceOrder":367},
  {"id":"s_work_han_thu_30_368","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　服虔曰：「坤位在未，黃帝從土位。」","sentenceOrder":368},
  {"id":"s_work_han_thu_30_369","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　李奇曰：「音貍。」師古曰：「西南夷長尾髦之牛也。一音茅。」","sentenceOrder":369},
  {"id":"s_work_han_thu_30_370","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「具俎豆酒醴而進之。一曰，進謂雜物之具，所以加禮也。」","sentenceOrder":370},
  {"id":"s_work_han_thu_30_371","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　師古曰：「腏字與餟同，謂聯續而祭也，音竹芮反。食讀曰飤。」","sentenceOrder":371},
  {"id":"s_work_han_thu_30_372","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　師古曰：「胙謂祭餘酒肉也。」","sentenceOrder":372},
  {"id":"s_work_han_thu_30_373","chapterId":"ch_work_han_thu_30","textTraditional":"〔七〕　服虔曰：「水，玄酒；酒，真酒也。」晉灼曰：「此言合牲物而燎之也。」師古曰：「言以白鹿內牛中，以彘內鹿中，又以水及酒合內鹿中。」","sentenceOrder":373},
  {"id":"s_work_han_thu_30_374","chapterId":"ch_work_han_thu_30","textTraditional":"〔八〕　師古曰：「若牛，若羊，若彘，止一牲也。」","sentenceOrder":374},
  {"id":"s_work_han_thu_30_375","chapterId":"ch_work_han_thu_30","textTraditional":"十一月辛巳朔旦冬至，昒爽，〔一〕天子始郊拜泰一。朝朝日，夕夕月，〔二〕則揖；而見泰一如雍郊禮。其贊饗曰：「天始以寶鼎神策授皇帝，朔而又朔，終而復始，皇帝敬拜見焉。」〔三〕而衣上黃。其祠列火滿壇，壇旁亨炊具。有司云「祠上有光」。公卿言「皇帝始郊見泰一雲陽，有司奉瑄玉〔四〕嘉牲薦饗，〔五〕是夜有美光，及晝，黃氣上屬天。」〔六〕太史令談、祠官寬舒等曰：「神靈之休，祐福兆祥，宜因此地光域立泰畤壇以明應。〔七〕令太祝領，秋及臘間祠。（二）〔三〕歲天子壹郊見。」","sentenceOrder":375},
  {"id":"s_work_han_thu_30_376","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「昒爽，謂日尚冥，蓋未明之時也。昒音忽。」","sentenceOrder":376},
  {"id":"s_work_han_thu_30_377","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「以朝旦拜日為朝。下朝音丈昭反。」","sentenceOrder":377},
  {"id":"s_work_han_thu_30_378","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「贊饗謂祝辭。」","sentenceOrder":378},
  {"id":"s_work_han_thu_30_379","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　孟康曰：「璧大六寸謂之瑄。」","sentenceOrder":379},
  {"id":"s_work_han_thu_30_380","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　師古曰：「漢舊儀云祭天養牛五歲，至三千斤也。」","sentenceOrder":380},
  {"id":"s_work_han_thu_30_381","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　師古曰：「屬音之欲反。」","sentenceOrder":381},
  {"id":"s_work_han_thu_30_382","chapterId":"ch_work_han_thu_30","textTraditional":"〔七〕　師古曰：「明著美光及黃氣之祥應。」","sentenceOrder":382},
  {"id":"s_work_han_thu_30_383","chapterId":"ch_work_han_thu_30","textTraditional":"其秋，為伐南越，告禱泰一，以牡荊畫幡日月北斗登龍，以象太一三星，為泰一鏠（旗），〔一〕命曰「靈旗」。為兵禱，則太史奉以指所伐國。而五利將軍使不敢入海，之泰山祠。上使人隨驗，實無所見。五利妄言見其師，其方盡，多不讎。〔二〕上乃誅五利。","sentenceOrder":383},
  {"id":"s_work_han_thu_30_384","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　李奇曰：「牡荊作幡柄也。」如淳曰：「牡荊，荊之無子者，皆絜齋之道。」晉灼曰：「牡，節間不相當也，月暈刻之為券以畏病者。天文志：『天極星，其一明者，太一也；旁三星，三公也。』畫一星在後，三星在前，為泰一鏠（旗）也。」師古曰：「李、晉二說是也。以牡荊為幡竿，而畫幡為日月龍及星。」","sentenceOrder":384},
  {"id":"s_work_han_thu_30_385","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「讎，應當也。不讎，無驗也。」","sentenceOrder":385},
  {"id":"s_work_han_thu_30_386","chapterId":"ch_work_han_thu_30","textTraditional":"其冬，公孫卿候神河南，言見僊人跡緱氏城上，有物如雉，往來城上。天子親幸緱氏視跡，問卿：「得毋效文成、五利乎？」卿曰：「僊者非有求人主，人主者求之。其道非少寬暇，神不來。言神事，如迂誕，〔一〕積以歲，乃可致。」於是郡國各除道，繕治宮館名山神祠所，以望幸矣。","sentenceOrder":386},
  {"id":"s_work_han_thu_30_387","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「迂，回遠也。誕，大言也。」","sentenceOrder":387},
  {"id":"s_work_han_thu_30_388","chapterId":"ch_work_han_thu_30","textTraditional":"其春，既滅南越，嬖臣李延年以好音見。上善之，下公卿議，曰：「民間祠有鼓舞樂，今郊祀而無樂，豈稱乎？」公卿曰：「古者祠天地皆有樂，而神祇可得而禮。」或曰：「泰帝使素女鼓五十絃瑟，悲，帝禁不止，〔一〕故破其瑟為二十五絃。」於是塞南越，禱祠泰一、后土，始用樂舞。益召歌兒，〔二〕作二十五絃及空侯瑟自此起。〔三〕","sentenceOrder":388},
  {"id":"s_work_han_thu_30_389","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「泰帝亦謂泰昊也。不止，謂不能自止也。」","sentenceOrder":389},
  {"id":"s_work_han_thu_30_390","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「益，多也。」","sentenceOrder":390},
  {"id":"s_work_han_thu_30_391","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　蘇林曰：「作空侯與瑟。」","sentenceOrder":391},
  {"id":"s_work_han_thu_30_392","chapterId":"ch_work_han_thu_30","textTraditional":"其來年冬，上議曰：「古者先振兵釋旅，然後封禪。」乃遂北巡朔方，勒兵十餘萬騎，還祭黃帝冢橋山，釋兵敘如。〔一〕上曰：「吾聞黃帝不死，有冢，何也？」或對曰：「黃帝以僊上天，群臣葬其衣冠。」既至甘泉，為且用事泰山，先類祠泰一。〔二〕","sentenceOrder":392},
  {"id":"s_work_han_thu_30_393","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　李奇曰：「地名也。」","sentenceOrder":393},
  {"id":"s_work_han_thu_30_394","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「且，猶將也。類祠，謂以事類而祭也。」","sentenceOrder":394},
  {"id":"s_work_han_thu_30_395","chapterId":"ch_work_han_thu_30","textTraditional":"自得寶鼎，上與公卿諸生議封禪。封禪用希曠絕，莫知其儀體，而群儒采封禪尚書、周官、王制之望祀射牛事。〔一〕齊人丁公年九十餘，曰：「封禪者，古不死之名也。秦皇帝不得上封。陛下必欲上，稍上〔二〕即無風雨，遂上封矣。」上於是乃令諸儒習射牛，草封禪儀。數年，至且行。天子既聞公孫卿及方士之言，黃帝以上封禪皆致怪物與神通，欲放黃帝〔三〕以接神人蓬萊，高世比德於九皇〔四〕，而頗采儒術以文之。群儒既已不能辯明封禪事，又拘於詩書古文而不敢騁。上為封祠器視群儒，〔五〕群儒或曰「不與古同」，徐偃又曰「太常諸生行禮不如魯善」，〔六〕周霸屬圖封事，〔七〕於是上黜偃、霸，而盡罷諸儒弗用。","sentenceOrder":395},
  {"id":"s_work_han_thu_30_396","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「天子有事宗廟，必自射牲，蓋示親殺也。事見國語也。」","sentenceOrder":396},
  {"id":"s_work_han_thu_30_397","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「稍，漸也。」","sentenceOrder":397},
  {"id":"s_work_han_thu_30_398","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「放，依也，音甫往反。」","sentenceOrder":398},
  {"id":"s_work_han_thu_30_399","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　張晏曰：「三皇之前有人皇，九首。」韋昭曰：「上古有人皇者九人。」師古曰：「韋說是也。」","sentenceOrder":399},
  {"id":"s_work_han_thu_30_400","chapterId":"ch_work_han_thu_30","textTraditional":"〔五〕　師古曰：「視讀曰示。」","sentenceOrder":400},
  {"id":"s_work_han_thu_30_401","chapterId":"ch_work_han_thu_30","textTraditional":"〔六〕　師古曰：「徐偃，博士姓名。」","sentenceOrder":401},
  {"id":"s_work_han_thu_30_402","chapterId":"ch_work_han_thu_30","textTraditional":"〔七〕　服虔曰：「屬，會也，會諸儒圖封事也。」師古曰：「周霸，亦人姓名也。屬音之欲反。」","sentenceOrder":402},
  {"id":"s_work_han_thu_30_403","chapterId":"ch_work_han_thu_30","textTraditional":"三月，乃東幸緱氏，禮登中嶽太室。從官在山上聞若有言「萬歲」云。問上，上不言；問下，下不言。乃令祠官加增太室祠，禁毋伐其山木，以山下戶凡三百封崈高，為之奉邑，〔一〕獨給祠，復無有所與。〔二〕上因東上泰山，〔三〕泰山草木未生，乃令人上石立之泰山顛。〔四〕","sentenceOrder":403},
  {"id":"s_work_han_thu_30_404","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「崈，古崇字耳。以崇奉嵩高之山，故謂之崈高奉邑。奉音扶用反。」","sentenceOrder":404},
  {"id":"s_work_han_thu_30_405","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「復音方目反。與讀曰預。」","sentenceOrder":405},
  {"id":"s_work_han_thu_30_406","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　如淳曰：「言易上也。泰山從南面直上，步道三十里，車道百里。」","sentenceOrder":406},
  {"id":"s_work_han_thu_30_407","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「從山下轉石而上。」","sentenceOrder":407},
  {"id":"s_work_han_thu_30_408","chapterId":"ch_work_han_thu_30","textTraditional":"上遂東巡海上，行禮祠八神。齊人之上疏言神怪奇方者以萬數，乃益發船，令言海中神山者數千人求蓬萊神人。公孫卿持節常先行候名山，至東萊，言夜見大人，長數丈，就之則不見，見其跡甚大，類禽獸云。群臣有言見一老父牽狗，言「吾欲見鉅公」，〔一〕已忽不見。上既見大跡，未信，及群臣又言老父，則大以為僊人也。宿留海上，〔二〕與方士傳車〔三〕及間使求神僊人以千數。〔四〕","sentenceOrder":408},
  {"id":"s_work_han_thu_30_409","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　鄭氏曰：「天子也。」張晏曰：「天子為天下父，故曰鉅公也。」師古曰：「鉅，大也。」","sentenceOrder":409},
  {"id":"s_work_han_thu_30_410","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「宿留，謂有所須待也。宿音先欲反。留音力就反。它皆類此。」","sentenceOrder":410},
  {"id":"s_work_han_thu_30_411","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「傳音張戀反。」","sentenceOrder":411},
  {"id":"s_work_han_thu_30_412","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「間，微也，隨間隙而行也。」","sentenceOrder":412},
  {"id":"s_work_han_thu_30_413","chapterId":"ch_work_han_thu_30","textTraditional":"四月，還至奉高。上念諸儒及方士言封禪人殊，不經，難施行。〔一〕天子至梁父，禮祠地主。至乙卯，令侍中儒者皮弁縉紳，射牛行事。封泰山下東方，如郊祠泰一之禮。封廣丈二尺，高九尺，其下則有玉牒書，書祕。禮畢，天子獨與侍中奉車子侯上泰山，〔二〕亦有封。其事皆禁。明日，下陰道。丙辰，禪泰山下阯東北肅然山〔三〕，如祭后土禮。天子皆親拜見，衣上黃而盡用樂焉。江淮間一茅三脊為神藉。五色土益雜封。縱遠方奇獸飛禽及白雉諸物，頗以加祠。兕牛象犀之屬不用。皆至泰山，然後去。封禪祠，其夜若有光，晝有白雲出封中。〔四〕","sentenceOrder":413},
  {"id":"s_work_han_thu_30_414","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「人人殊異，又不合經，故難以施行。」","sentenceOrder":414},
  {"id":"s_work_han_thu_30_415","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　服虔曰：「子侯，霍去病子也。」","sentenceOrder":415},
  {"id":"s_work_han_thu_30_416","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「阯者，山之基足，音止。」","sentenceOrder":416},
  {"id":"s_work_han_thu_30_417","chapterId":"ch_work_han_thu_30","textTraditional":"〔四〕　師古曰：「白雲出於所封之中。」","sentenceOrder":417},
  {"id":"s_work_han_thu_30_418","chapterId":"ch_work_han_thu_30","textTraditional":"天子從禪還，坐明堂，群臣更上壽。〔一〕下詔改元為元封。語在武紀。又曰：「古者天子五載一巡狩，用事泰山，諸侯有朝宿地。其令諸侯各治邸泰山下。」","sentenceOrder":418},
  {"id":"s_work_han_thu_30_419","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「更，互也，音工衡反。」","sentenceOrder":419},
  {"id":"s_work_han_thu_30_420","chapterId":"ch_work_han_thu_30","textTraditional":"天子既已封泰山，無風雨，而方士更言蓬萊諸神〔一〕若將可得，於是上欣然庶幾遇之，復東至海上望焉。奉車子侯暴病，一日死。上乃遂去，並海上，〔二〕北至碣石，巡自遼西，歷北邊至九原。五月，乃至甘泉，周萬八千里云。","sentenceOrder":420},
  {"id":"s_work_han_thu_30_421","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「更音工衡反。」","sentenceOrder":421},
  {"id":"s_work_han_thu_30_422","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「並音步浪反。上音時掌反。」","sentenceOrder":422},
  {"id":"s_work_han_thu_30_423","chapterId":"ch_work_han_thu_30","textTraditional":"其秋，有星孛於東井。後十餘日，有星孛於三能。〔一〕望氣王朔言：「候獨見填星出如瓜，食頃，復入。」有司皆曰：「陛下建漢家封禪，天其報德星云。」〔二〕","sentenceOrder":423},
  {"id":"s_work_han_thu_30_424","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「能讀曰台。」","sentenceOrder":424},
  {"id":"s_work_han_thu_30_425","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「德星，即填星也。言天以德星報於帝。」","sentenceOrder":425},
  {"id":"s_work_han_thu_30_426","chapterId":"ch_work_han_thu_30","textTraditional":"其來年冬，郊雍五帝。還，拜祝祠泰一。〔一〕贊饗曰：「德星昭衍，厥維休祥。〔二〕壽星仍出，淵燿光明。信星昭見，皇帝敬拜泰祝之享。」","sentenceOrder":426},
  {"id":"s_work_han_thu_30_427","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　師古曰：「拜而祠之，加祝辭。」","sentenceOrder":427},
  {"id":"s_work_han_thu_30_428","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　師古曰：「昭，明；衍，大；休，美也。」","sentenceOrder":428},
  {"id":"s_work_han_thu_30_429","chapterId":"ch_work_han_thu_30","textTraditional":"其春，公孫卿言見神人東萊山，若云「欲見天子」。天子於是幸緱氏城，拜卿為中大夫。遂至東萊，宿，留之數日，毋所見，見大人跡云。復遣方士求神人采藥以千數。是歲旱。天子既出亡名，乃禱萬里沙，〔一〕過祠泰山。〔二〕還至瓠子，自臨塞決河，留二日，湛祠而去。〔三〕","sentenceOrder":429},
  {"id":"s_work_han_thu_30_430","chapterId":"ch_work_han_thu_30","textTraditional":"〔一〕　應劭曰：「萬里沙，神祠也，在東萊曲城。」如淳曰：「故禱萬里沙以為名也。」","sentenceOrder":430},
  {"id":"s_work_han_thu_30_431","chapterId":"ch_work_han_thu_30","textTraditional":"〔二〕　鄭氏曰：「泰山東自復有小泰山。」臣瓚曰：「即今之泰山也。」師古曰：「瓚說是也。」","sentenceOrder":431},
  {"id":"s_work_han_thu_30_432","chapterId":"ch_work_han_thu_30","textTraditional":"〔三〕　師古曰：「湛讀曰沈，謂沈祭具於水中也。爾雅曰『祭川曰浮沈』。」","sentenceOrder":432},
  {"id":"s_work_han_thu_30_433","chapterId":"ch_work_han_thu_30","textTraditional":"校勘記","sentenceOrder":433},
  {"id":"s_work_han_thu_30_434","chapterId":"ch_work_han_thu_30","textTraditional":"一一九四頁一三行　文公（薨）〔夢〕黃蛇自天下屬地，　景祐、殿、局本都作「夢」。朱一新說作「夢」是，封禪書同。","sentenceOrder":434},
  {"id":"s_work_han_thu_30_435","chapterId":"ch_work_han_thu_30","textTraditional":"一二００頁一五行　昔文公出（臘）〔獵〕，　景祐、殿、局本都作「獵」。王先謙說作「獵」是。","sentenceOrder":435},
  {"id":"s_work_han_thu_30_436","chapterId":"ch_work_han_thu_30","textTraditional":"一二０二頁一０行　（來）〔求〕僊人羨門之屬。　景祐、殿本都作「求」。朱一新說作「求」是，封禪書同。","sentenceOrder":436},
  {"id":"s_work_han_thu_30_437","chapterId":"ch_work_han_thu_30","textTraditional":"一二０二頁一五行　六曰月主，祠（之）萊山：　王先謙說「之」字不當有，緣上「之」字而衍。","sentenceOrder":437},
  {"id":"s_work_han_thu_30_438","chapterId":"ch_work_han_thu_30","textTraditional":"一二０三頁一五行　羨門高最後，皆燕人，　王鳴盛說，案服虔、司馬貞說，最後者，自是謂其在騶子之後耳，非姓名。其實止四人。顏注謬。","sentenceOrder":438},
  {"id":"s_work_han_thu_30_439","chapterId":"ch_work_han_thu_30","textTraditional":"一二０四頁　六行　〔王子喬〕化為白蜺，　「王子喬」三字據景祐、殿本補。","sentenceOrder":439},
  {"id":"s_work_han_thu_30_440","chapterId":"ch_work_han_thu_30","textTraditional":"一二０四頁　八行　今其書有（王）〔主〕運。　五行相次轉用事，隨方（而）〔面〕為服也。景祐、殿本「王」都作「主」，「而」都作「面」，封禪書集解引同。","sentenceOrder":440},
  {"id":"s_work_han_thu_30_441","chapterId":"ch_work_han_thu_30","textTraditional":"一二０九頁　二行　唯雍四（時）〔畤〕上帝為尊，　景祐、殿、局本都作「畤」。王先謙說作「畤」是。","sentenceOrder":441},
  {"id":"s_work_han_thu_30_442","chapterId":"ch_work_han_thu_30","textTraditional":"一二一０頁　三行　（侚）〔狥〕沛，為沛公。　王先謙說殿本作「狥」是。","sentenceOrder":442},
  {"id":"s_work_han_thu_30_443","chapterId":"ch_work_han_thu_30","textTraditional":"一二一０頁　八行　二年（冬），　王念孫說景祐本無「冬」字是也。按封禪書亦無「冬」字。","sentenceOrder":443},
  {"id":"s_work_han_thu_30_444","chapterId":"ch_work_han_thu_30","textTraditional":"一二一一頁　一行　（當）〔堂〕上之屬；　景祐、殿、局本都作「堂」。","sentenceOrder":444},
  {"id":"s_work_han_thu_30_445","chapterId":"ch_work_han_thu_30","textTraditional":"一二一二頁　一行　（晨）〔辰〕見而祭之。　王先謙說殿本「晨」作「辰」是。","sentenceOrder":445},
  {"id":"s_work_han_thu_30_446","chapterId":"ch_work_han_thu_30","textTraditional":"一二一三頁　六行　〔故外〕黑；　「故外」二字據景祐、殿本補。","sentenceOrder":446},
  {"id":"s_work_han_thu_30_447","chapterId":"ch_work_han_thu_30","textTraditional":"一二一九頁一六行　言此牛腹中有奇（書）。　景祐本無「書」字，封禪書亦無。王念孫說無「書」字是。","sentenceOrder":447},
  {"id":"s_work_han_thu_30_448","chapterId":"ch_work_han_thu_30","textTraditional":"一二二二頁一二行　樂成侯（登）上書言欒大。　王先謙說「登」字蓋衍。","sentenceOrder":448},
  {"id":"s_work_han_thu_30_449","chapterId":"ch_work_han_thu_30","textTraditional":"一二二二頁一五行　大為人長美，〔七〕言多方略，　注〔七〕原在「言」字下，明顏以「長美言」連讀。武億說「言」字當連下「多方略」為句。楊樹達說顏注非，武讀是。","sentenceOrder":449},
  {"id":"s_work_han_thu_30_450","chapterId":"ch_work_han_thu_30","textTraditional":"一二二六頁　一行　鼎宜視宗禰（廣）〔廟〕，　景祐、殿、局本都作「廟」。","sentenceOrder":450},
  {"id":"s_work_han_thu_30_451","chapterId":"ch_work_han_thu_30","textTraditional":"一二二六頁一０行　雖祈穀而未獲年豐之（穀）〔報〕也。　景祐、殿本都作「報」。朱一新說作「報」是。","sentenceOrder":451},
  {"id":"s_work_han_thu_30_452","chapterId":"ch_work_han_thu_30","textTraditional":"一二二八頁　七行　漢帝亦當上封（禪），〔上〕封（禪）則能僊登天矣。　據景祐本改。王念孫說景祐本是。","sentenceOrder":452},
  {"id":"s_work_han_thu_30_453","chapterId":"ch_work_han_thu_30","textTraditional":"一二二八頁一三行　龍乃〔上〕去。　景祐、殿本都有「上」字。朱一新說史記同，此脫。","sentenceOrder":453},
  {"id":"s_work_han_thu_30_454","chapterId":"ch_work_han_thu_30","textTraditional":"一二三一頁　六行　（二）〔三〕歲天子壹郊見。　景祐、殿本都作「三」。王先謙說封禪書、通鑑作「三」是，此誤。","sentenceOrder":454},
  {"id":"s_work_han_thu_30_455","chapterId":"ch_work_han_thu_30","textTraditional":"一二三一頁一四行　為泰一鏠（旗），　王念孫說「鏠旗」之「旗」後人以意加之也。景祐本無「旗」字，注同。","sentenceOrder":455},
  {"id":"s_work_han_thu_31_1","chapterId":"ch_work_han_thu_31","textTraditional":"是時既滅兩粵，粵人勇之乃言「粵人俗鬼，〔一〕而其祠皆見鬼，數有效。昔東甌王敬鬼，壽百六十歲。後世怠嫚，故衰耗。」〔二〕乃命粵巫立粵祝祠，安臺無壇，亦祠天神帝百鬼，〔三〕而以雞卜。〔四〕上信之，粵祠雞卜自此始用。〔五〕","sentenceOrder":1},
  {"id":"s_work_han_thu_31_2","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「勇之，越人名也。俗鬼，言其土俗尚鬼神之事。」","sentenceOrder":2},
  {"id":"s_work_han_thu_31_3","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「耗，減也，音火到反。」","sentenceOrder":3},
  {"id":"s_work_han_thu_31_4","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「天帝之神及百鬼。」","sentenceOrder":4},
  {"id":"s_work_han_thu_31_5","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　李奇曰：「持雞骨卜，如鼠卜。」","sentenceOrder":5},
  {"id":"s_work_han_thu_31_6","chapterId":"ch_work_han_thu_31","textTraditional":"〔五〕　師古曰：「言國家始用。」","sentenceOrder":6},
  {"id":"s_work_han_thu_31_7","chapterId":"ch_work_han_thu_31","textTraditional":"公孫卿曰：「僊人可見，上往常遽，以故不見。〔一〕今陛下可為館如緱氏城，〔二〕置脯棗，神人宜可致。且僊人好樓居。」於是上令長安則作飛廉、桂館，〔三〕甘泉則作益壽、延壽館，〔四〕使卿持節設具而候神人。乃作通天臺，〔五〕置祠具其下，將招來神僊之屬。於是甘泉更置前殿，始廣諸宮室。夏，有芝生甘泉殿房內中。天子為塞河，興通天，若有光云，〔六〕乃下詔赦天下。","sentenceOrder":7},
  {"id":"s_work_han_thu_31_8","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「遽，速也，音其庶反。」","sentenceOrder":8},
  {"id":"s_work_han_thu_31_9","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「依其制度也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_31_10","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「飛廉館及桂館二名也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_31_11","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　師古曰：「益壽、延壽，亦二館名。」","sentenceOrder":11},
  {"id":"s_work_han_thu_31_12","chapterId":"ch_work_han_thu_31","textTraditional":"〔五〕　師古曰：「漢舊儀云臺高三十丈，望見長安城。」","sentenceOrder":12},
  {"id":"s_work_han_thu_31_13","chapterId":"ch_work_han_thu_31","textTraditional":"〔六〕　師古曰：「為塞河及造通天臺而有神光之應，故赦天下也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_31_14","chapterId":"ch_work_han_thu_31","textTraditional":"其明年，伐朝鮮。夏，旱。公孫卿曰：「黃帝時封則天旱，乾封三年。」〔一〕上乃下詔：「天旱，意乾封乎？〔二〕其令天下尊祠靈星焉。」","sentenceOrder":14},
  {"id":"s_work_han_thu_31_15","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「三歲不雨，暴所封之土令乾也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_31_16","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　鄭氏曰：「言適新封則致旱，天欲乾我所封乎？」","sentenceOrder":16},
  {"id":"s_work_han_thu_31_17","chapterId":"ch_work_han_thu_31","textTraditional":"明年，上郊雍五畤，通回中道，遂北出蕭關，歷獨鹿、鳴澤〔一〕，自西河歸，幸河東祠后土。","sentenceOrder":17},
  {"id":"s_work_han_thu_31_18","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「解並在武紀。」","sentenceOrder":18},
  {"id":"s_work_han_thu_31_19","chapterId":"ch_work_han_thu_31","textTraditional":"明年冬，上巡南郡，至江陵而東。登禮灊之天柱山，號曰南嶽。〔一〕浮江，自潯陽出樅陽，〔二〕過彭蠡，禮其名山川。北至琅邪，並海上。〔三〕四月，至奉高修封焉。","sentenceOrder":19},
  {"id":"s_work_han_thu_31_20","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「灊，廬江縣也，天柱山在焉。武帝以天柱山為南嶽。灊音潛。」","sentenceOrder":20},
  {"id":"s_work_han_thu_31_21","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「樅音千庸反。」","sentenceOrder":21},
  {"id":"s_work_han_thu_31_22","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「並音步浪反。上音時掌反。」","sentenceOrder":22},
  {"id":"s_work_han_thu_31_23","chapterId":"ch_work_han_thu_31","textTraditional":"初，天子封泰山，泰山東北阯古時有明堂處，處險不敞。〔一〕上欲治明堂奉高旁，未曉其制度。濟南人公玉帶上黃帝時明堂圖〔二〕。明堂中有一殿，四面無壁，以茅蓋，通水，水圜宮垣，〔三〕為復道，上有樓，從西南入，〔四〕名曰昆侖，天子從之入，以拜祀上帝焉。於是上令奉高作明堂汶上，如帶圖。〔五〕及是歲修封，則祠泰一、五帝於明堂上坐，〔六〕合高皇帝祠坐對之。〔七〕祠后土於下房，以二十太牢。天子從昆侖道入，始拜明堂如郊禮。畢，尞堂下。〔八〕而上又上泰山，自有祕祠其顛。而泰山下祠五帝，各如其方，黃帝并赤帝所，〔九〕有司侍祠焉。山上舉火，下悉應之。還幸甘泉，郊泰畤。春幸汾陰，祠后土。","sentenceOrder":23},
  {"id":"s_work_han_thu_31_24","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「言其阻阨不顯敞。」","sentenceOrder":24},
  {"id":"s_work_han_thu_31_25","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「公玉，姓也。帶，名也。呂氏春秋齊有公玉丹，此蓋其舊族。而說者讀公玉為宿，非也。單姓玉者，後漢司徒玉況，自音宿耳。」","sentenceOrder":25},
  {"id":"s_work_han_thu_31_26","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「圜，繞也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_31_27","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　師古曰：「復讀曰複也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_31_28","chapterId":"ch_work_han_thu_31","textTraditional":"〔五〕　師古曰：「汶，水名也，出琅邪朱虛。作明堂於汶水之上也。帶圖，公玉帶所上明堂圖。汶音問。」","sentenceOrder":28},
  {"id":"s_work_han_thu_31_29","chapterId":"ch_work_han_thu_31","textTraditional":"〔六〕　師古曰：「坐音才臥反。」","sentenceOrder":29},
  {"id":"s_work_han_thu_31_30","chapterId":"ch_work_han_thu_31","textTraditional":"〔七〕　服虔曰：「漢是時未以高祖配天，故言對。光武以來乃配之。」","sentenceOrder":30},
  {"id":"s_work_han_thu_31_31","chapterId":"ch_work_han_thu_31","textTraditional":"〔八〕　師古曰：「尞，古燎字。」","sentenceOrder":31},
  {"id":"s_work_han_thu_31_32","chapterId":"ch_work_han_thu_31","textTraditional":"〔九〕　師古曰：「與赤帝同處。」","sentenceOrder":32},
  {"id":"s_work_han_thu_31_33","chapterId":"ch_work_han_thu_31","textTraditional":"明年，幸泰山，以十一月甲子朔旦冬至日祀上帝於明堂，（後每）〔毋〕修封。其贊饗曰：「天增授皇帝泰元神策，周而復始。皇帝敬拜泰一。」〔一〕東至海上，考入海及方士求神者，莫驗，然益遣，幾遇之。〔二〕乙酉，柏梁災。十二月甲午朔，上親禪高里，〔三〕祠后土。臨勃海，將以望祀蓬萊之屬，幾至殊庭焉。〔四〕","sentenceOrder":33},
  {"id":"s_work_han_thu_31_34","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「自此以上，贊祝者辭。」","sentenceOrder":34},
  {"id":"s_work_han_thu_31_35","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「益，多也。幾讀曰冀。言更遣人求之，冀必遇也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_31_36","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「高里，山名。解在武紀。」","sentenceOrder":36},
  {"id":"s_work_han_thu_31_37","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　師古曰：「殊庭，蓬萊中仙人庭也。幾讀曰冀。」","sentenceOrder":37},
  {"id":"s_work_han_thu_31_38","chapterId":"ch_work_han_thu_31","textTraditional":"上還，以柏梁災故，受計甘泉。公孫卿曰：「黃帝就青靈臺，十二日燒，〔一〕黃帝乃治明庭。明庭，甘泉也。」方士多言古帝王有都甘泉者。其後天子又朝諸侯甘泉，甘泉作諸侯邸。勇之乃曰：「粵俗有火災，復起屋，必以大，用勝服之。」於是作建章宮，度為千門萬戶。前殿度高未央。〔二〕其東則鳳闕，高二十餘丈。〔三〕其西則商中，數十里虎圈。〔四〕其北治大池，漸臺高二十餘丈，名曰泰液，〔五〕池中有蓬萊、方丈、瀛州、壺梁，象海中神山龜魚之屬。〔六〕其南有玉堂璧門大鳥之屬。〔七〕立神明臺、井幹樓，高五十丈，輦道相屬焉。〔八〕","sentenceOrder":38},
  {"id":"s_work_han_thu_31_39","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「就，成也，造臺適成，經十二日即遇火燒。」","sentenceOrder":39},
  {"id":"s_work_han_thu_31_40","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「度並音大各反。」","sentenceOrder":40},
  {"id":"s_work_han_thu_31_41","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「三輔故事云其闕圜上有銅鳳凰。」","sentenceOrder":41},
  {"id":"s_work_han_thu_31_42","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　如淳曰：「商中，商庭也。」師古曰：「商，金也。於序在秋，故謂西方之庭為商庭，言廣數十里。於菟亦西方之獸，故於此置其圈也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_31_43","chapterId":"ch_work_han_thu_31","textTraditional":"〔五〕　師古曰：「漸，浸也。臺在池中，為水所浸，故曰漸臺。一音子廉反。三輔黃圖或為瀸字，瀸亦浸耳。」","sentenceOrder":43},
  {"id":"s_work_han_thu_31_44","chapterId":"ch_work_han_thu_31","textTraditional":"〔六〕　師古曰：「三輔故事云池北岸有石魚，長二丈，高五尺，西岸有石鱉三枚，長六尺。」","sentenceOrder":44},
  {"id":"s_work_han_thu_31_45","chapterId":"ch_work_han_thu_31","textTraditional":"〔七〕　師古曰：「立大鳥象也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_31_46","chapterId":"ch_work_han_thu_31","textTraditional":"〔八〕　師古曰：「漢宮閣疏云神明臺高五十丈，上有九室，恆置九天道士百人。然則神明、井幹俱高五十丈也。井幹樓積木而高，為樓若井幹之形也。井幹者，井上木欄也，其形或四角，或八角。張衡西京賦云『井幹疊而百層』，即謂此樓也。幹或作韓，其義並同。」","sentenceOrder":46},
  {"id":"s_work_han_thu_31_47","chapterId":"ch_work_han_thu_31","textTraditional":"夏，漢改曆，以正月為歲首，而色上黃，官更印章以五字，〔一〕因為太初元年。是歲，西伐大宛，蝗大起。丁夫人、雒陽虞初等〔二〕以方祠詛匈奴、大宛焉。","sentenceOrder":47},
  {"id":"s_work_han_thu_31_48","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「解在武紀。」","sentenceOrder":48},
  {"id":"s_work_han_thu_31_49","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　應劭曰：「丁夫人，其先丁復，本越人，封陽都侯。夫人其後，以詛軍為功。」韋昭曰：「丁，姓；夫人，名也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_31_50","chapterId":"ch_work_han_thu_31","textTraditional":"明年，有司言雍五畤無牢孰具，芬芳不備。乃令祠官進畤犢牢具，色食所勝，〔一〕而以木寓馬代駒云。及諸名山川用駒者，悉以木寓馬代。獨行過親祠，乃用駒，它禮如故。","sentenceOrder":50},
  {"id":"s_work_han_thu_31_51","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　孟康曰：「若火勝金，則祠赤帝以白牲也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_31_52","chapterId":"ch_work_han_thu_31","textTraditional":"明年，東巡海上，考神僊之屬，未有驗者。方士有言黃帝時為五城十二樓，〔一〕以候神人於執期，〔二〕名曰迎年。〔三〕上許作之如方，名曰明年。〔四〕上親禮祠，上犢黃焉。","sentenceOrder":52},
  {"id":"s_work_han_thu_31_53","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　應劭曰：「昆侖玄圃五城十二樓，仙人之所常居。」","sentenceOrder":53},
  {"id":"s_work_han_thu_31_54","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　鄭氏曰：「地名也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_31_55","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「迎年，若云祈年。」","sentenceOrder":55},
  {"id":"s_work_han_thu_31_56","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　師古曰：「言明其得延年也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_31_57","chapterId":"ch_work_han_thu_31","textTraditional":"公玉帶曰：「黃帝時雖封泰山，然風后、封鉅、岐伯令黃帝封東泰山，〔一〕禪凡山，〔二〕合符，然後不死。」天子既令設祠具，至東泰山，東泰山卑小，不稱其聲，乃令祠官禮之，而不封焉。其後令帶奉祠候神物。復還泰山，修五年之禮如前，而加禪祠石閭。石閭者，在泰山下阯南方，〔三〕方士言僊人閭也，故上親禪焉。","sentenceOrder":57},
  {"id":"s_work_han_thu_31_58","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　韋昭曰：「風后、封鉅、岐伯皆黃帝臣也。」臣瓚曰：「東泰山在琅邪朱虛界，中有小泰山是。」","sentenceOrder":58},
  {"id":"s_work_han_thu_31_59","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「凡山在朱虛縣，見地理志也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_31_60","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「下基之南面。」","sentenceOrder":60},
  {"id":"s_work_han_thu_31_61","chapterId":"ch_work_han_thu_31","textTraditional":"其後五年，復至泰山修封，還過祭恆山。","sentenceOrder":61},
  {"id":"s_work_han_thu_31_62","chapterId":"ch_work_han_thu_31","textTraditional":"自封泰山後，十三歲而周遍於五嶽、四瀆矣。","sentenceOrder":62},
  {"id":"s_work_han_thu_31_63","chapterId":"ch_work_han_thu_31","textTraditional":"後五年，復至泰山修封。東幸琅邪，禮日成山，登之罘，浮大海，用事八神延年。〔一〕又祠神人於交門宮，若有鄉坐拜者云。〔二〕","sentenceOrder":63},
  {"id":"s_work_han_thu_31_64","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「解並在武紀。延年，即上所謂迎年者。」","sentenceOrder":64},
  {"id":"s_work_han_thu_31_65","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「如有神人景象嚮祠坐而拜也。事具在武紀。鄉讀與嚮同。」","sentenceOrder":65},
  {"id":"s_work_han_thu_31_66","chapterId":"ch_work_han_thu_31","textTraditional":"後五年，上復修封於泰山。東游東萊，臨大海。是歲，雍縣無雲如靁者三，〔一〕或如虹氣蒼黃，若飛鳥集棫陽宮南，〔二〕聲聞四百里。隕石二，黑如黳，有司以為美祥，以薦宗廟。而方士之候神入海求蓬萊者終無驗，公孫卿猶以大人之跡為解。〔三〕天子猶羈縻不絕，〔四〕幾遇其真。〔五〕","sentenceOrder":66},
  {"id":"s_work_han_thu_31_67","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「靁，古雷字也。空有雷聲也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_31_68","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「棫音域。」","sentenceOrder":68},
  {"id":"s_work_han_thu_31_69","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「言見大人之跡，以自解說也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_31_70","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　師古曰：「羈縻，繫聯之意。馬絡頭曰羈也。牛靷曰縻。」","sentenceOrder":70},
  {"id":"s_work_han_thu_31_71","chapterId":"ch_work_han_thu_31","textTraditional":"〔五〕　師古曰：「幾讀曰冀。」","sentenceOrder":71},
  {"id":"s_work_han_thu_31_72","chapterId":"ch_work_han_thu_31","textTraditional":"諸所興，如薄忌泰一及三一、冥羊、馬行、赤星，五（床）。寬舒之祠（宮）〔官〕〔一〕以歲時致禮。凡六祠，皆大祝領之。至如八神，諸明年、凡山它名祠，行過則祠，去則已。方士所興祠，各自主，其人終則已，祠官不主。它祠皆如故。甘泉泰一、汾陰后土，三年親郊祠，而泰山五年一修封。武帝凡五修封。昭帝即位，富於春秋，未嘗親巡祭云。","sentenceOrder":72},
  {"id":"s_work_han_thu_31_73","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　李奇曰：「皆祠名。」","sentenceOrder":73},
  {"id":"s_work_han_thu_31_74","chapterId":"ch_work_han_thu_31","textTraditional":"宣帝即位，由武帝正統興，故立三年，尊孝武廟為世宗，行所巡狩郡國皆立廟。告祠世宗廟日，有白鶴集後庭。以立世宗廟告祠孝昭寢，有鴈五色集殿前。西河築世宗廟，神光興於殿旁，有鳥如白鶴，前赤後青。神光又興於房中，如燭狀。廣川國世宗廟殿上有鍾音，門戶大開，夜有光，殿上盡明。上乃下詔赦天下。","sentenceOrder":74},
  {"id":"s_work_han_thu_31_75","chapterId":"ch_work_han_thu_31","textTraditional":"時，大將軍霍光輔政，上共己正南面，〔一〕非宗廟之祀不出。十二年，乃下詔曰：「蓋聞天子尊事天地，修祀山川，古今通禮也。間者，上帝之祠闕而不親十有餘年，朕甚懼焉。朕親飭躬齊戒，親奉祀，為百姓蒙嘉氣，獲豐年焉。」","sentenceOrder":75},
  {"id":"s_work_han_thu_31_76","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「共讀曰恭。」","sentenceOrder":76},
  {"id":"s_work_han_thu_31_77","chapterId":"ch_work_han_thu_31","textTraditional":"明年正月，上始幸甘泉，郊見泰畤，數有美祥。修武帝故事，盛車服，敬齊祠之禮，頗作詩歌。","sentenceOrder":77},
  {"id":"s_work_han_thu_31_78","chapterId":"ch_work_han_thu_31","textTraditional":"其三月，幸河東，祠后土，有神爵集，改元為神爵。制詔太常：「夫江海，百川之大者也，今闕焉無祠。其令祠官以禮為歲事，〔一〕以四時祠江海雒水，祈為天下豐年焉。」自是五嶽、四瀆皆有常禮。東嶽泰山於博，中嶽泰室於嵩高，南嶽灊山於灊，〔二〕西嶽華山於華陰，北嶽常山於上曲陽，〔三〕河於臨晉，〔四〕江於江都〔五〕，淮於平氏，〔六〕濟於臨邑界中，〔七〕皆使者持節侍祠。唯泰山與河歲五祠，江水四，餘皆一禱而三祠云。","sentenceOrder":78},
  {"id":"s_work_han_thu_31_79","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「言每歲常祠之。」","sentenceOrder":79},
  {"id":"s_work_han_thu_31_80","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「灊與潛同也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_31_81","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「上曲陽，常山郡之縣也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_31_82","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　師古曰：「馮翊之縣也，臨河西岸。」","sentenceOrder":82},
  {"id":"s_work_han_thu_31_83","chapterId":"ch_work_han_thu_31","textTraditional":"〔五〕　師古曰：「廣陵之縣也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_31_84","chapterId":"ch_work_han_thu_31","textTraditional":"〔六〕　師古曰：「南陽之縣也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_31_85","chapterId":"ch_work_han_thu_31","textTraditional":"〔七〕　師古曰：「東郡之縣也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_31_86","chapterId":"ch_work_han_thu_31","textTraditional":"時，南郡獲白虎，獻其皮牙爪，上為立祠。又以方士言，為隨侯、劍寶、玉寶璧、周康寶鼎立四祠於未央宮中。又祠太室山於即墨，三戶山於下密，〔一〕祠天封苑火井於鴻門。〔二〕又立歲星、辰星、太白、熒惑、南斗祠於長安城旁。又祠參山八神於曲城，〔三〕蓬山石社石鼓於臨朐，〔四〕之罘山於腄，成山於不夜，萊山於黃〔五〕。成山祠日，萊山祠月。又祠四時於琅邪，蚩尤於壽良。〔六〕京師近縣鄠，則有勞谷、五床山、日月、五帝、僊人、玉女祠。雲陽有徑路神祠，祭休屠王也。〔七〕又立五龍山僊人祠及黃帝、天神、帝原水，凡四祠於膚施。〔八〕","sentenceOrder":86},
  {"id":"s_work_han_thu_31_87","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「即墨、下密皆膠東之縣也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_31_88","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　如淳曰：「地理志西河鴻門縣有天封苑火井祠，火從地中出。」","sentenceOrder":88},
  {"id":"s_work_han_thu_31_89","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「東萊之縣也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_31_90","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　師古曰：「臨朐，齊郡縣也。朐音劬。地理志蓬山作達山也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_31_91","chapterId":"ch_work_han_thu_31","textTraditional":"〔五〕　應劭曰：「腄音甀。」晉灼曰：「腄、不夜、黃縣皆屬東萊。」師古曰：「腄音丈瑞反。」","sentenceOrder":91},
  {"id":"s_work_han_thu_31_92","chapterId":"ch_work_han_thu_31","textTraditional":"〔六〕　師古曰：「東郡之縣也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_31_93","chapterId":"ch_work_han_thu_31","textTraditional":"〔七〕　師古曰：「休屠，匈奴王號也。徑路神，本匈奴之祠也。休音許虯反。屠音除。」","sentenceOrder":93},
  {"id":"s_work_han_thu_31_94","chapterId":"ch_work_han_thu_31","textTraditional":"〔八〕　師古曰：「膚施，上郡之縣也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_31_95","chapterId":"ch_work_han_thu_31","textTraditional":"或言益州有金馬碧雞之神，〔一〕可醮祭而致，於是遣諫大夫王褒使持節而求之。","sentenceOrder":95},
  {"id":"s_work_han_thu_31_96","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　如淳曰：「金形似馬，碧形似雞。」","sentenceOrder":96},
  {"id":"s_work_han_thu_31_97","chapterId":"ch_work_han_thu_31","textTraditional":"大夫劉更生獻淮南枕中洪寶苑祕之方，〔一〕令尚方鑄作。事不驗，更生坐論。京兆尹張敞上疏諫曰：「願明主時忘車馬之好，斥遠方士之虛語，〔二〕游心帝王之術，太平庶幾可興也。」後尚方待詔皆罷。","sentenceOrder":97},
  {"id":"s_work_han_thu_31_98","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「洪，大也。苑祕者，言祕術之苑囿也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_31_99","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「遠音於萬反。」","sentenceOrder":99},
  {"id":"s_work_han_thu_31_100","chapterId":"ch_work_han_thu_31","textTraditional":"是時，美陽得鼎，獻之。〔一〕下有司議，多以為宜薦見宗廟，如元鼎時故事。張敞好古文字，桉鼎銘勒而上議曰：「臣聞周祖始乎后稷，后稷封於斄，〔二〕公劉發跡於豳，〔三〕大王建國於廄梁，〔四〕文武興於酆鎬。〔五〕由此言之，則廄梁豐鎬之間周舊居也，固宜有宗廟壇場祭祀之臧。今鼎出於廄東，中有刻書曰：『王命尸臣：「官此栒邑，〔六〕賜爾旂鸞黼黻琱戈。」〔七〕尸臣拜手稽首曰：「敢對揚天子丕顯休命。」』〔八〕臣愚不足以跡古文，〔九〕竊以傳記言之，此鼎殆周之所以褒賜大臣，大臣子孫刻銘其先功，臧之於宮廟也。昔寶鼎之出於汾脽也，河東太守以聞，詔曰：『朕巡祭后土，祈為百姓蒙豐年，〔一０〕今穀嗛未報，〔一一〕鼎焉為出哉？』博問耆老，意舊臧與？〔一二〕誠欲考得事實也。有司驗脽上非舊臧處，鼎大八尺一寸，高三尺六寸，殊異於眾鼎。今此鼎細小，又有款識，〔一三〕不宜薦見於宗廟。」制曰：「京兆尹議是。」","sentenceOrder":100},
  {"id":"s_work_han_thu_31_101","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「美陽，扶風之縣也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_31_102","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「斄讀與邰同，今武功故城是。」","sentenceOrder":102},
  {"id":"s_work_han_thu_31_103","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「今豳州是也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_31_104","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　師古曰：「梁山在岐山之東，九嵕之西，非夏陽之梁山也。廄，古岐字。」","sentenceOrder":104},
  {"id":"s_work_han_thu_31_105","chapterId":"ch_work_han_thu_31","textTraditional":"〔五〕　師古曰：「酆，今長安城西豐水上也。鎬在昆明池北。」","sentenceOrder":105},
  {"id":"s_work_han_thu_31_106","chapterId":"ch_work_han_thu_31","textTraditional":"〔六〕　師古曰：「尸臣，主事之臣也。栒邑，即豳地是也。栒音荀。」","sentenceOrder":106},
  {"id":"s_work_han_thu_31_107","chapterId":"ch_work_han_thu_31","textTraditional":"〔七〕　師古曰：「交龍為旂。鸞謂有鸞之車也。黼黻，冕服也。琱戈，刻鏤之戈也。琱與凋同。」","sentenceOrder":107},
  {"id":"s_work_han_thu_31_108","chapterId":"ch_work_han_thu_31","textTraditional":"〔八〕　師古曰：「拜手，首至於手也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_31_109","chapterId":"ch_work_han_thu_31","textTraditional":"〔九〕　師古曰：「尋其文跡。」","sentenceOrder":109},
  {"id":"s_work_han_thu_31_110","chapterId":"ch_work_han_thu_31","textTraditional":"〔一０〕師古曰：「為音於偽反。」","sentenceOrder":110},
  {"id":"s_work_han_thu_31_111","chapterId":"ch_work_han_thu_31","textTraditional":"〔一一〕師古曰：「嗛，少意也。言穀稼尚少，未獲豐年也。嗛音苦簟反。」","sentenceOrder":111},
  {"id":"s_work_han_thu_31_112","chapterId":"ch_work_han_thu_31","textTraditional":"〔一二〕服虔曰：「言鼎豈舊臧於此地。」師古曰：「與讀曰歟。」","sentenceOrder":112},
  {"id":"s_work_han_thu_31_113","chapterId":"ch_work_han_thu_31","textTraditional":"〔一三〕師古曰：「款，刻也。識，記也，音式志反。」","sentenceOrder":113},
  {"id":"s_work_han_thu_31_114","chapterId":"ch_work_han_thu_31","textTraditional":"上自幸河東之明年正月，鳳皇集祋祤，〔一〕於所集處得玉寶，起步壽宮，乃下詔赦天下。後間歲，鳳皇神爵甘露降集京師，〔二〕赦天下。其冬，鳳皇集上林，乃作鳳皇殿，以答嘉瑞。〔三〕明年正月，復幸甘泉，郊泰畤，改元曰五鳳。明年，幸雍祠五畤。其明年春，幸河東，祠后土，赦天下。後間歲，改元為甘露。正月，上幸甘泉，郊泰畤。其夏，黃龍見新豐。建章、未央、長樂宮鍾虡銅人皆生毛，長一寸所，〔四〕時以為美祥。後間歲正月，上郊泰畤，因朝單于於甘泉宮。後間歲，改元為黃龍。正月，復幸甘泉，郊泰畤，又朝單于於甘泉宮。至冬而崩。鳳皇下郡國凡五十餘所。","sentenceOrder":114},
  {"id":"s_work_han_thu_31_115","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「祋祤，馮翊之縣也。祋音丁活反，又丁外反。祤音況矩反。」","sentenceOrder":115},
  {"id":"s_work_han_thu_31_116","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「間歲，隔一歲也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_31_117","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「答，應也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_31_118","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　師古曰：「虡，神獸名也，縣鍾之木刻飾為之，因名曰虡也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_31_119","chapterId":"ch_work_han_thu_31","textTraditional":"元帝即位，遵舊儀，間歲正月，一幸甘泉郊泰畤，又東至河東祠后土，西至雍祠五畤。凡五奉泰畤、后土之祠。亦施恩澤，時所過毋出田租，賜百戶牛酒，〔一〕或賜爵，赦罪人。","sentenceOrder":119},
  {"id":"s_work_han_thu_31_120","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「言有時如此，不常然也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_31_121","chapterId":"ch_work_han_thu_31","textTraditional":"元帝好儒，貢禹、韋玄成、匡衡等相繼為公卿。禹建言漢家宗廟祭祀多不應古禮，上是其言。後韋玄成為丞相，議罷郡國廟，自太上皇、孝惠帝諸園寢廟皆罷。後元帝寢疾，夢神靈譴罷諸廟祠，上遂復焉。後或罷或復，至哀、平不定。語在韋玄成傳。","sentenceOrder":121},
  {"id":"s_work_han_thu_31_122","chapterId":"ch_work_han_thu_31","textTraditional":"成帝初即位，丞相衡、御史大夫譚〔一〕奏言：「帝王之事莫大乎承天之序，承天之序莫重於郊祀，故聖王盡心極慮以建其制。祭天於南郊，就陽之義也；瘞地於北郊，即陰之象也。〔二〕天之於天子也，因其所都而各饗焉。往者，孝武皇帝居甘泉宮，即於雲陽立泰畤，祭於宮南。今行常幸長安，郊見皇天反北之泰陰，祠后土反東之少陽，事與古制殊。又至雲陽，行谿谷中，阨陝且百里，汾陰則渡大川，有風波舟楫之危，〔三〕皆非聖主所宜數乘。郡縣治道共張，吏民困苦，〔四〕百官煩費。勞所保之民，行危險之地，〔五〕難以奉神靈而祈福祐，殆未合於承天子民之意。昔者周文武郊於豐鄗，成王郊於雒邑。由此觀之，天隨王者所居而饗之，可見也。甘泉泰畤、河東后土之祠宜可徙置長安，合於古帝王。願與群臣議定。」奏可。大司馬車騎將軍許嘉等八人以為所從來久遠，宜如故。右將軍王商、博士師丹、議郎翟方進等五十人以為禮記曰「燔柴於太壇，祭天也；瘞薶於大折，祭地也。」〔六〕兆於南郊，所以定天位也。〔七〕祭地於大折，在北郊，就陰位也。郊處各在聖王所都之南北。書曰「越三日丁巳，用牲於郊，牛二。」〔八〕周公加牲，告徙新邑，定郊禮於雒。明王聖主，事天明，事地察。天地明察，神明章矣。天地以王者為主，故聖王制祭天地之禮必於國郊。長安，聖主之居，皇天所觀視也。甘泉、河東之祠非神靈所饗，宜徙就正陽大陰之處。違俗復古，循聖制，定天位，如禮便。於是衡、譚奏議曰：「陛下聖德，怱明上通，〔九〕承天之大，典覽群下，使各悉心盡慮，議郊祀之處，天下幸甚。臣聞廣謀從眾，則合於天心，故洪範曰『三人占，則從二人言』，〔一０〕言少從多之義也。論當往古，宜於萬民，則依而從之〔一一〕；違道寡與，則廢而不行。今議者五十八人，其五十人言當徙之義，皆著於經傳，同於上世，便於吏民；八人不案經藝，考古制，而以為不宜，無法之議，難以定吉凶。太誓曰：『正稽古立功立事，可以永年，丕天之大律。』〔一二〕詩曰『毋曰高高在上，陟降厥士，日監在茲』，〔一三〕言天之日監王者之處也。又曰『乃眷西顧，此維予宅』，〔一四〕言天以文王之都為居也。宜於長安定南北郊，為萬世基。」天子從之。","sentenceOrder":122},
  {"id":"s_work_han_thu_31_123","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「衡，匡衡。譚，張譚。」","sentenceOrder":123},
  {"id":"s_work_han_thu_31_124","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「祭地曰瘞薶，故云瘞地也。即，就也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_31_125","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「楫音集。其字從木。」","sentenceOrder":125},
  {"id":"s_work_han_thu_31_126","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　師古曰：「共讀曰供，音居用反。張音竹亮反。下皆類此。」","sentenceOrder":126},
  {"id":"s_work_han_thu_31_127","chapterId":"ch_work_han_thu_31","textTraditional":"〔五〕　師古曰：「保，養也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_31_128","chapterId":"ch_work_han_thu_31","textTraditional":"〔六〕　韋昭曰：「大折，謂為壇於昭晰地也。」師古曰：「折，曲也。言方澤之形，四曲折也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_31_129","chapterId":"ch_work_han_thu_31","textTraditional":"〔七〕　鄧展曰：「除地為營埒，有形兆也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_31_130","chapterId":"ch_work_han_thu_31","textTraditional":"〔八〕　師古曰：「周書洛誥之辭。」","sentenceOrder":130},
  {"id":"s_work_han_thu_31_131","chapterId":"ch_work_han_thu_31","textTraditional":"〔九〕　師古曰：「怱與聰同。」","sentenceOrder":131},
  {"id":"s_work_han_thu_31_132","chapterId":"ch_work_han_thu_31","textTraditional":"〔一０〕師古曰：「洪範，周書也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_31_133","chapterId":"ch_work_han_thu_31","textTraditional":"〔一一〕師古曰：「論，議也，音來頓反。」","sentenceOrder":133},
  {"id":"s_work_han_thu_31_134","chapterId":"ch_work_han_thu_31","textTraditional":"〔一二〕師古曰：「今文泰誓，周書也。稽，考也。永，長也。丕，奉也。律，法也。言正考古道而立事，則可長年享有天下，是則奉天之大法也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_31_135","chapterId":"ch_work_han_thu_31","textTraditional":"〔一三〕師古曰：「詩周頌敬之詩也。陟，升也。士，事也。言無謂天之高而又高，遠在上而不加敬，天乃上下升降，日日監觀於此，視人之所為者耳。」","sentenceOrder":135},
  {"id":"s_work_han_thu_31_136","chapterId":"ch_work_han_thu_31","textTraditional":"〔一四〕師古曰：「大雅皇矣之詩也。宅，居也。言天眷然西顧，以周國為居也。商紂在東，故謂周為西也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_31_137","chapterId":"ch_work_han_thu_31","textTraditional":"既定，衡言：「甘泉泰畤紫壇，八觚宣通象八方。〔一〕五帝壇周環其下，又有群神之壇。以尚書禋六宗、望山川、遍群神之義，紫壇有文章采鏤黼黻之飾及玉、女樂，〔二〕石壇、僊人祠，瘞鸞路、騂駒、寓龍馬，不能得其象於古。臣聞郊（紫壇）〔柴〕饗帝之義，埽地而祭，上質也。歌大呂舞雲門以俟天神，歌太蔟舞咸池以俟地祇，〔三〕其牲用犢，其席槁稭，其器陶匏，〔四〕皆因天地之性，貴誠上質，不敢修其文也。以為神祇功德至大，雖修精微而備庶物，猶不足以報功，唯至誠為可，（致）〔故〕上質不飾，以章天德。紫壇偽飾女樂、鸞路、騂駒、龍馬、石壇之屬，宜皆勿修。」","sentenceOrder":137},
  {"id":"s_work_han_thu_31_138","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　服虔曰：「八觚，如今社壇也。」師古曰：「觚，角也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_31_139","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「漢舊儀云祭天用六綵綺席六重，用玉几玉飾器凡七十。女樂，即禮樂志所云『使童男童女俱歌』也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_31_140","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「此周禮也。大呂合於黃鍾。黃鍾，陽聲之首也。雲門，黃帝樂也。太蔟，陽聲次二者也。咸池，堯樂也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_31_141","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　師古曰：「陶，瓦器；匏，瓠也。稭音戛。」","sentenceOrder":141},
  {"id":"s_work_han_thu_31_142","chapterId":"ch_work_han_thu_31","textTraditional":"衡又言：「王者各以其禮制事天地，非因異世所立而繼之。〔一〕今雍鄜、密、上下畤，〔二〕本秦侯各以其意所立，非禮之所載術也。漢興之初，儀制未及定，即且因秦故祠，復立北畤。今既稽古，建定天地之大禮，郊見上帝，青赤白黃黑五方之帝皆畢陳，各有位饌，祭祀備具。諸侯所妄造，王者不當長遵。及北畤，未定時所立〔三〕，不宜復修。」天子皆從焉。及陳寶祠，由是皆罷。","sentenceOrder":142},
  {"id":"s_work_han_thu_31_143","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「異世，謂前代。」","sentenceOrder":143},
  {"id":"s_work_han_thu_31_144","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　晉灼曰：「秦文公、宣公所立畤也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_31_145","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「謂高祖之初，禮儀未定。」","sentenceOrder":145},
  {"id":"s_work_han_thu_31_146","chapterId":"ch_work_han_thu_31","textTraditional":"明年，上始祀南郊，赦奉郊之縣及中都官耐罪囚徒。〔一〕是歲衡、譚復條奏：「長安廚官縣官給祠郡國候神方士使者所祠，凡六百八十三所，其二百八所應禮，及疑無明文，可奉祠如故。其餘四百七十五所不應禮，或復重，〔二〕請皆罷。」奏可。本雍舊祠二百三所，唯山川諸星十五所為應禮云。若諸布、諸嚴、諸逐，皆罷。杜主有五祠，置其一。又罷高祖所立梁、晉、秦、荊巫、九天、南山、萊中之屬，及孝文渭陽、孝武薄忌泰一、三一、黃帝、冥羊、馬行、泰一、皋山山君、武夷、夏后啟母石、萬里沙、八神、延年之屬，及孝宣參山、蓬山、之罘、成山、萊山、四時、蚩尤、勞谷、五床、僊人、玉女、徑路、黃帝、天神、原水之屬，皆罷。候神方士使者副佐、本草待詔七十餘人皆歸家。〔三〕","sentenceOrder":146},
  {"id":"s_work_han_thu_31_147","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「中都官，京師諸官府也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_31_148","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「復音扶目反。重音丈庸反。」","sentenceOrder":148},
  {"id":"s_work_han_thu_31_149","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「本草待詔，謂以方藥本草而待詔者。」","sentenceOrder":149},
  {"id":"s_work_han_thu_31_150","chapterId":"ch_work_han_thu_31","textTraditional":"明年，匡衡坐事免官爵。眾庶多言不當變動祭祀者。又初罷甘泉泰畤作南郊日，大風壞甘泉竹宮，折拔畤中樹大十圍以上百餘。天子異之，以問劉向。對曰：「家人尚不欲絕種祠，〔一〕況於國之神寶舊畤！且甘泉、汾陰及雍五畤始立，皆有神祇感應，然後營之，非苟而已也。武、宣之世，奉此三神，禮敬敕備，〔二〕神光尤著。祖宗所立神祇舊位，誠未易動。及陳寶祠，自秦文公至今七百餘歲矣，漢興世世常來，光色赤黃，長四五丈，直祠而息，音聲砰隱，野雞皆雊。〔三〕每見雍太祝祠以太牢，遣候者乘一乘傳馳詣行在所，〔四〕以為福祥。高祖時五來，文帝二十六來，武帝七十五來，宣帝二十五來，初元元年以來亦二十來，此陽氣舊祠也。及漢宗廟之禮，不得擅議，皆祖宗之君與賢臣所共定。古今異制，經無明文，至尊至重，難以疑說正也。前始納貢禹之議，後人相因，多所動搖。易大傳曰：『誣神者殃及三世。』恐其咎不獨止禹等。」上意恨之。〔五〕","sentenceOrder":150},
  {"id":"s_work_han_thu_31_151","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「家人，謂庶人之家也。種祠，繼嗣所傳祠也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_31_152","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「敕，整也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_31_153","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「直，當也。息，止也。當祠處而止也。砰音普萌反。」","sentenceOrder":153},
  {"id":"s_work_han_thu_31_154","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　師古曰：「報神之來也。傳音張戀反。」","sentenceOrder":154},
  {"id":"s_work_han_thu_31_155","chapterId":"ch_work_han_thu_31","textTraditional":"〔五〕　師古曰：「恨，悔也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_31_156","chapterId":"ch_work_han_thu_31","textTraditional":"後上以無繼嗣故，今皇太后詔有司曰：「蓋聞王者承事天地，交接泰一，尊莫著於祭祀。孝武皇帝大聖通明，始建上下之祀，〔一〕營泰畤於甘泉，定后土於汾陰，而神祇安之，饗國長久，子孫蕃滋，〔二〕累世遵業，福流於今。今皇帝寬仁孝順，奉循聖緒，靡有大愆，而久無繼嗣。思其咎職，殆在徙南北郊，〔三〕違先帝之制，改神祇舊位，失天地之心，以妨繼嗣之福。春秋六十，未見皇孫，〔四〕食不甘味，寢不安席，朕甚悼焉。春秋大復古，善順祀。〔五〕其復甘泉泰畤，汾陰后土如故，及雍五畤、陳寶祠在陳倉者。」天子復親郊禮如前。又復長安、雍及郡國祠著明者且半。","sentenceOrder":156},
  {"id":"s_work_han_thu_31_157","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「上下，謂天地。」","sentenceOrder":157},
  {"id":"s_work_han_thu_31_158","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「蕃音扶元反。」","sentenceOrder":158},
  {"id":"s_work_han_thu_31_159","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「職，主也，咎過主於此也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_31_160","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　師古曰：「皇太后自謂。」","sentenceOrder":160},
  {"id":"s_work_han_thu_31_161","chapterId":"ch_work_han_thu_31","textTraditional":"〔五〕　師古曰：「以復古為大，以順祀為善也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_31_162","chapterId":"ch_work_han_thu_31","textTraditional":"成帝末年頗好鬼神，亦以無繼嗣故，多上書言祭祀方術者，皆得待詔，祠祭上林苑中長安城旁，費用甚多，然無大貴盛者，谷永說上曰：「臣聞明於天地之性，不可或以神怪；知萬物之情，不可罔以非類。〔一〕諸背仁義之正道，不遵五經之法言，而盛稱奇怪鬼神，廣崇祭祀之方，求報無福之祠，及言世有僊人，服食不終之藥，〈辶{夕言}〉興輕舉，〔二〕登遐倒景，〔三〕覽觀縣圃，浮游蓬萊，〔四〕耕耘五德，朝種暮穫，〔五〕與山石無極，〔六〕黃冶變化，〔七〕堅冰淖溺，〔八〕化色五倉之術者，〔九〕皆姦人惑眾，挾左道，懷詐偽，以欺罔世主。〔一０〕聽其言，洋洋滿耳，若將可遇；〔一一〕求之，盪盪如係風捕景，終不可得。〔一二〕是以明王距而不聽，聖人絕而不語。〔一三〕昔周史萇弘欲以鬼神之術輔尊靈王會朝諸侯，而周室愈微，諸侯愈叛。楚懷王隆祭祀，事鬼神，欲以獲福助，卻秦師〔一四〕，而兵挫地削，身辱國危。秦始皇初并天下，甘心於神僊之道，遣徐福、韓終之屬多齎童男童女入海求神采藥，因逃不還，天下怨恨。漢興，新垣平、齊人少翁、公孫卿、欒大等，皆以僊人黃冶祭祠事鬼使物入海求神采藥貴幸，賞賜累千金。大尤尊盛，至妻公主，爵位重絫，震動海內。〔一五〕元鼎、元封之際，燕齊之間方士瞋目扼掔，言有神僊祭祀致福之術者以萬數。其後，平等皆以術窮詐得，誅夷伏辜。〔一六〕至初元中，有天淵玉女、鉅鹿神人、轑陽侯師張宗之姦，紛紛復起。〔一七〕夫周秦之末，三五之隆，〔一八〕已嘗專意散財，厚爵祿，竦精神，舉天下以求之矣。曠日經年，靡有毫氂之驗，足以揆今。經曰：『享多儀，儀不及物，惟曰不享。』〔一九〕論語說曰：『子不語怪神。』〔二０〕唯陛下距絕此類，毋令姦人有以窺朝者。」上善其言。","sentenceOrder":162},
  {"id":"s_work_han_thu_31_163","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「罔猶蔽。」","sentenceOrder":163},
  {"id":"s_work_han_thu_31_164","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　如淳曰：「〈辶{夕言}〉，遠也。興，舉也。」師古曰：「〈辶{夕言}〉，古遙字也。興，起也。謂起而遠去也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_31_165","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　如淳曰：「在日月之上，反從下照，故其景倒。」師古曰：「遐亦遠也。」","sentenceOrder":165},
  {"id":"s_work_han_thu_31_166","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　李奇曰：「昆侖九成，上有縣圃，縣圃之上即閶闔天門。」","sentenceOrder":166},
  {"id":"s_work_han_thu_31_167","chapterId":"ch_work_han_thu_31","textTraditional":"〔五〕　晉灼曰：「翼氏風角，五德東方甲，南方丙，西方庚，北方壬，中央戊。種五色禾於（北）〔此〕地而耕耘也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_31_168","chapterId":"ch_work_han_thu_31","textTraditional":"〔六〕　師古曰：「言獲長壽，比於山石無窮也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_31_169","chapterId":"ch_work_han_thu_31","textTraditional":"〔七〕　晉灼曰：「黃者，鑄黃金也。道家言冶丹沙令變化，可鑄作黃金也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_31_170","chapterId":"ch_work_han_thu_31","textTraditional":"〔八〕　晉灼曰：「方士詐以藥石若陷冰丸投之冰上，冰即消液，因假為神仙道使然也。或曰，謂冶金令可餌也。」師古曰：「或說非也。淖，濡甚也，音女教反。」","sentenceOrder":170},
  {"id":"s_work_han_thu_31_171","chapterId":"ch_work_han_thu_31","textTraditional":"〔九〕　李奇曰：「思身中有五色，腹中有五倉神；五色存則不死，五倉存則不飢。」","sentenceOrder":171},
  {"id":"s_work_han_thu_31_172","chapterId":"ch_work_han_thu_31","textTraditional":"〔一０〕師古曰：「左道，邪僻之道，非正義也。」","sentenceOrder":172},
  {"id":"s_work_han_thu_31_173","chapterId":"ch_work_han_thu_31","textTraditional":"〔一一〕師古曰：「洋洋，美盛之貌也。洋音羊，又音祥。」","sentenceOrder":173},
  {"id":"s_work_han_thu_31_174","chapterId":"ch_work_han_thu_31","textTraditional":"〔一二〕師古曰：「盪盪，空曠之貌也。盪音蕩。」","sentenceOrder":174},
  {"id":"s_work_han_thu_31_175","chapterId":"ch_work_han_thu_31","textTraditional":"〔一三〕師古曰：「謂孔子不語怪神。」","sentenceOrder":175},
  {"id":"s_work_han_thu_31_176","chapterId":"ch_work_han_thu_31","textTraditional":"〔一四〕師古曰：「卻，退。音丘略反。」","sentenceOrder":176},
  {"id":"s_work_han_thu_31_177","chapterId":"ch_work_han_thu_31","textTraditional":"〔一五〕師古曰：「絫，古累字。」","sentenceOrder":177},
  {"id":"s_work_han_thu_31_178","chapterId":"ch_work_han_thu_31","textTraditional":"〔一六〕師古曰：「詐得，謂主上得其詐偽之情。」","sentenceOrder":178},
  {"id":"s_work_han_thu_31_179","chapterId":"ch_work_han_thu_31","textTraditional":"〔一七〕師古曰：「轑陽侯，江仁也，元帝時坐使家丞上印綬隨宗學仙免官。轑音遼。」","sentenceOrder":179},
  {"id":"s_work_han_thu_31_180","chapterId":"ch_work_han_thu_31","textTraditional":"〔一八〕師古曰：「三謂三皇，五謂五帝也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_31_181","chapterId":"ch_work_han_thu_31","textTraditional":"〔一九〕師古曰：「周書洛誥之辭也。言祭享之道，唯以絜誠，若多其容儀，而不及禮物，則不為神所享也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_31_182","chapterId":"ch_work_han_thu_31","textTraditional":"〔二０〕師古曰：「說謂論語之說也。」","sentenceOrder":182},
  {"id":"s_work_han_thu_31_183","chapterId":"ch_work_han_thu_31","textTraditional":"後成都侯王商為大司馬衛將軍輔政，杜鄴說商曰：「『東鄰殺牛，不如西鄰之瀹祭』，〔一〕言奉天之道，貴以誠質大得民心也。行穢祀豐，猶不蒙祐；德修薦薄，吉必大來。古者壇場有常處，尞禋有常用，〔二〕贊見有常禮；犧牲玉帛雖備而財不匱，車輿臣役雖動而用不勞。是故每（奉）〔舉〕其禮，助者歡說，〔三〕大路所歷，黎元不知。〔四〕今甘泉、河東天地郊祀，咸失方位，違陰陽之宜。及雍五畤皆曠遠，奉尊之役休而復起，繕治共張無解已時，皇天著象殆可略知。前上甘泉，先敺失道；〔五〕禮月之夕，奉引復迷。〔六〕祠后土還，臨河當渡，疾風起波，船不可御。又雍大雨，壞平陽宮垣。乃三月甲子，震電災林光宮門。〔七〕祥瑞未著，咎徵仍臻。跡三郡所奏，皆有變故。〔八〕不答不饗，何以甚此！〔九〕詩曰『率由舊章』。〔一０〕舊章，先王法度，文王以之，交神于祀，子孫千億。宜如異時公卿之議，復還長安南北郊。」","sentenceOrder":183},
  {"id":"s_work_han_thu_31_184","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「此易既濟九五爻辭也。東鄰，謂商紂也。西鄰，周文王也。瀹祭，謂瀹煮新菜以祭。言祭祀之道莫盛修德，故紂之牛牲，不如文王之蘋藻也。瀹音籥。」","sentenceOrder":184},
  {"id":"s_work_han_thu_31_185","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「尞，古燎字。」","sentenceOrder":185},
  {"id":"s_work_han_thu_31_186","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「助謂助祭也。說讀曰悅。」","sentenceOrder":186},
  {"id":"s_work_han_thu_31_187","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　師古曰：「大路，天子祭天所乘之車也。黎元不知，言無（偽）〔徭〕費，不勞於下也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_31_188","chapterId":"ch_work_han_thu_31","textTraditional":"〔五〕　師古曰：「敺與驅字同。」","sentenceOrder":188},
  {"id":"s_work_han_thu_31_189","chapterId":"ch_work_han_thu_31","textTraditional":"〔六〕　韋昭曰：「奉引，前導引車。」","sentenceOrder":189},
  {"id":"s_work_han_thu_31_190","chapterId":"ch_work_han_thu_31","textTraditional":"〔七〕　孟康曰：「甘泉一名林光。」師古曰：「林光，秦離宮名也。漢又於其旁起甘泉宮，非一名也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_31_191","chapterId":"ch_work_han_thu_31","textTraditional":"〔八〕　師古曰：「跡謂觀其事跡也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_31_192","chapterId":"ch_work_han_thu_31","textTraditional":"〔九〕　師古曰：「不答，不當天意。不饗，不為天所饗也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_31_193","chapterId":"ch_work_han_thu_31","textTraditional":"〔一０〕師古曰：「大雅假樂之詩也。率，循也。由，用也。循用舊典之文章也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_31_194","chapterId":"ch_work_han_thu_31","textTraditional":"後數年，成帝崩，皇太后詔有司曰：「皇帝即位，思順天心，遵經義，定郊禮，天下說憙。〔一〕懼未有皇孫，故復甘泉泰畤、汾陰后土，庶幾獲福。皇帝恨難之，卒未得其祐。其復南北郊長安如故，以順皇帝之意也。」","sentenceOrder":194},
  {"id":"s_work_han_thu_31_195","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":195},
  {"id":"s_work_han_thu_31_196","chapterId":"ch_work_han_thu_31","textTraditional":"哀帝即位，寢疾，博徵方術士，京師諸縣皆有侍祠使者，盡復前世所常興諸神祠官，凡七百餘所，一歲三萬七千祠云。","sentenceOrder":196},
  {"id":"s_work_han_thu_31_197","chapterId":"ch_work_han_thu_31","textTraditional":"明年，復令太皇太后詔有司曰：「皇帝孝順，奉承聖業，靡有解怠，〔一〕而久疾未瘳。夙夜唯思，殆繼體之君不宜改作。其復甘泉泰畤、汾陰后土祠如故。」上亦不能親至，遣有司行事而禮祠焉。後三年，哀帝崩。","sentenceOrder":197},
  {"id":"s_work_han_thu_31_198","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「解讀曰懈。」","sentenceOrder":198},
  {"id":"s_work_han_thu_31_199","chapterId":"ch_work_han_thu_31","textTraditional":"平帝元始五年，大司馬王莽奏言：「王者父事天，故爵稱天子。孔子曰：『人之行莫大於孝，孝莫大於嚴父，嚴父莫大於配天。〔一〕』王者尊其考，欲以配天，緣考之意，欲尊祖，推而上之，遂及始祖。是以周公郊祀后稷以配天，宗祀文王於明堂以配上帝。禮記天子祭天地及山川，歲遍。春秋穀梁傳以十二月下辛卜，正月上辛郊〔二〕。高皇帝受命，因雍四畤起北畤，而備五帝，未共王地之祀。〔三〕孝文十六年用新垣平，初起渭陽五帝廟，祭泰一、地祇，以太祖高皇帝配。日冬至祠泰一，夏至祠地祇，皆并祠五帝，而共一牲，上親郊拜。後平伏誅，乃不復自親，而使有司行事。孝武皇帝祠雍，曰：『今上帝朕親郊，而后土無祠，則禮不答也。』於是元鼎四年十一月甲子始立后土祠於汾陰。或曰，五帝，泰一之佐，宜立泰一。五年十一月癸未始立泰一祠於甘泉，二歲一郊，與雍更祠，〔四〕亦以高祖配，不歲事天，皆未應古制。建始元年，徙甘泉泰畤、河東后土於長安南北郊。永始元年三月，以未有皇孫，復甘泉、河東祠。綏和二年，以卒不獲祐，復長安南北郊。建平三年，懼孝哀皇帝之疾未瘳，復甘泉、汾陰祠，竟復無福。臣謹與太師孔光、長樂少府平晏、大司農左咸、中壘校尉劉歆、太中大夫朱陽、博士薛順、議郎國由等六十七人議，皆曰宜如建始時丞相衡等議，復長安南北郊如故。」","sentenceOrder":199},
  {"id":"s_work_han_thu_31_200","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「孝經載孔子之言。」","sentenceOrder":200},
  {"id":"s_work_han_thu_31_201","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「豫卜郊之日。」","sentenceOrder":201},
  {"id":"s_work_han_thu_31_202","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「共讀曰恭。」","sentenceOrder":202},
  {"id":"s_work_han_thu_31_203","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　師古曰：「更音工衡反。」","sentenceOrder":203},
  {"id":"s_work_han_thu_31_204","chapterId":"ch_work_han_thu_31","textTraditional":"莽又頗改其祭禮，曰：「周官天墬之祀，〔一〕樂有別有合。其合樂曰『以六律、六鐘、五聲、八音、六舞大合樂』，祀天神，祭墬祇，祀四望，祭山川，享先妣先祖。〔二〕凡六樂，奏六歌，而天墬神祇之物皆至。〔三〕四望，蓋謂日月星海也。三光高而不可得親，海廣大無限界，故其樂同。祀天則天文從。祭墬則墬理從。三光，天文也。山川，地理也。天地合祭，先祖配天，先妣配墬，其誼一也。天墬合精，夫婦判合。祭天南郊，則以墬配，一體之誼也。天墬位皆南鄉，同席，〔四〕墬在東，共牢而食。高帝、高后配於壇上，西鄉，后在北，亦同席共牢。牲用繭栗，〔五〕玄酒陶匏。禮記曰天子籍田千畮以事天墬，〔六〕繇是言之，宜有黍稷。〔七〕天地用牲一，燔尞瘞薶用牲一，高帝、高后用牲一。天用牲左，及黍稷燔尞南郊；墬用牲右，及黍稷瘞於北郊。其旦，東鄉再拜朝日；其夕，西鄉再拜夕月。然後孝弟之道備，而神衹嘉享，萬福降輯。〔八〕此天墬合祀，以祖妣配者也。其別樂曰『冬日至，於墬上之圜丘奏樂六變，則天神皆降；夏日至，於澤中之方丘奏樂八變，則墬衹皆出。』〔九〕天墬有常位，不得常合，此其各特祀者也。陰陽之別於日冬夏至，其會也以孟春正月上辛若丁。天子親合祀天墬於南郊，以高帝、高后配。陰陽有離合，易曰『分陰分陽，迭用柔剛』。〔一０〕以日冬至使有司奉祠南郊，高帝配而望群陽，日夏至使有司奉祭北郊，高后配而望群陰，皆以助致微氣，通道幽弱。〔一一〕當此之時，后不省方〔一二〕，故天子不親而遣有司，所以正承天順地，復聖王之制，顯太祖之功也。渭陽祠勿復修。群望未定悉定，定復奏。」奏可。三十餘年間，天地之祠五徙焉。","sentenceOrder":204},
  {"id":"s_work_han_thu_31_205","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「墬，古地字也。下皆類此。」","sentenceOrder":205},
  {"id":"s_work_han_thu_31_206","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「此周禮春官大司樂之職也。六律，合陽聲者。六鐘，以六律六鐘之均也。五聲，宮、商、角、徵、羽。八音，金、石、絲、竹、匏、土、革、木。六舞，雲門、咸池、大韶、大夏、大護、大武也。大合樂者，遍作之也。先妣，姜嫄也。先祖，先王先公也。」","sentenceOrder":206},
  {"id":"s_work_han_thu_31_207","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「謂一變而致羽物及川澤之祇，再變而致（嬴）〔臝〕物及山林之祇，三變而致鱗物及丘陵之祇，四變而致毛物及墳衍之祇，五變而致介物及地祇，六變而致象物及天神。」","sentenceOrder":207},
  {"id":"s_work_han_thu_31_208","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　師古曰：「鄉讀曰嚮。其下並同。」","sentenceOrder":208},
  {"id":"s_work_han_thu_31_209","chapterId":"ch_work_han_thu_31","textTraditional":"〔五〕　師古曰：「謂牛角如繭及栗者，牛之小也。」","sentenceOrder":209},
  {"id":"s_work_han_thu_31_210","chapterId":"ch_work_han_thu_31","textTraditional":"〔六〕　師古曰：「畮，古畝字。」","sentenceOrder":210},
  {"id":"s_work_han_thu_31_211","chapterId":"ch_work_han_thu_31","textTraditional":"〔七〕　師古曰：「繇讀與由同。」","sentenceOrder":211},
  {"id":"s_work_han_thu_31_212","chapterId":"ch_work_han_thu_31","textTraditional":"〔八〕　師古曰：「輯與集同。」","sentenceOrder":212},
  {"id":"s_work_han_thu_31_213","chapterId":"ch_work_han_thu_31","textTraditional":"〔九〕　師古曰：「此亦春官大司樂之職也。天神之樂：圜鍾為宮，黃鍾為角，太蔟為徵，姑洗為羽，雷鼓雷鼗，孤竹之管，雲和之琴瑟，雲門之舞。地祇之樂，函鍾為宮，太蔟為角，姑洗為徵，南呂為羽，靈鼓靈鼗，孫竹之管，空桑之琴瑟，咸池之舞，先奏是樂，以致其神，禮之以玉，然後合樂而祭。」","sentenceOrder":213},
  {"id":"s_work_han_thu_31_214","chapterId":"ch_work_han_thu_31","textTraditional":"〔一０〕師古曰：「易說卦之辭也。陽為剛，陰為柔，陰陽既分，則剛柔迭用也。迭，互也，音大結反。」","sentenceOrder":214},
  {"id":"s_work_han_thu_31_215","chapterId":"ch_work_han_thu_31","textTraditional":"〔一一〕師古曰：「道讀曰導。」","sentenceOrder":215},
  {"id":"s_work_han_thu_31_216","chapterId":"ch_work_han_thu_31","textTraditional":"〔一二〕師古曰：「謂冬夏日至之時。后，君也。方，常也。不視常務。」","sentenceOrder":216},
  {"id":"s_work_han_thu_31_217","chapterId":"ch_work_han_thu_31","textTraditional":"後莽又奏言：「書曰『類於上帝，禋于六宗』。〔一〕歐陽、大小夏侯三家說六宗，皆曰上不及天，下不及墬，旁不及四方，在六者之間，助陰陽變化，實一而名六，名實不相應。禮記祀典，功施於民則祀之。天文日月星辰，所昭仰也；地理山川海澤，所生殖也。易有八卦，乾坤六子，水火不相逮，雷風不相誖，山澤通氣，然後能變化，既成萬物也。〔二〕臣前奏徙甘泉泰畤、汾陰后土皆復於南北郊。謹案周官『兆五帝於四郊』，山川各因其方，〔三〕今五帝兆居在雍五畤，不合於古。又日月雷風山澤，易卦六子之尊氣，所謂六宗也。星辰水火溝瀆，皆六宗之屬也。今或未特祀，或無兆居。謹與太師光、大司徒宮、羲和歆等八十九人議，皆曰天子父事天，母事墬，今稱天神曰皇天上帝，泰一兆曰泰畤，而稱地祇曰后土，與中央黃靈同，又兆北郊未有尊稱。宜令地祇稱皇墬后祇，兆曰廣畤。易曰『方以類聚，物以群分』。〔四〕分群神以類相從為五部，兆天墬之別神：中央帝黃靈后土畤及日廟、北辰、北斗、填星、中宿中宮於長安城之未墬兆；東方帝太昊青靈勾芒畤及雷公、風伯廟、歲星、東宿東宮於東郊兆；南方炎帝赤靈祝融畤及熒惑星、南宿南宮於南郊兆；西方帝少皞白靈蓐收畤及太白星、西宿西宮於西郊兆；北方帝顓頊黑靈玄冥畤及月廟、雨師廟、辰星、北宿北宮於北郊兆。」奏可。於是長安旁諸廟兆畤甚盛矣。","sentenceOrder":217},
  {"id":"s_work_han_thu_31_218","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「虞書舜典也。並已解於上。」","sentenceOrder":218},
  {"id":"s_work_han_thu_31_219","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「乾為父，坤為母。震為長男，巽為長女，坎為中男，離為中女，艮為少男，兌為少女，故云六子也。水火，坎離也。雷風，震巽也。山澤，艮兌也。逮，及。誖，亂也。既，盡也。靁，古雷字也。誖音布內反。」","sentenceOrder":219},
  {"id":"s_work_han_thu_31_220","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「春官小宗伯之職也。兆謂為壇之營域也。五帝於四郊，謂青帝於東郊，赤帝及黃帝於南郊，白帝於西郊，黑帝於北郊也。各因其方，謂順其所在也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_31_221","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　師古曰：「易上繫之辭也。方謂所向之地。」","sentenceOrder":221},
  {"id":"s_work_han_thu_31_222","chapterId":"ch_work_han_thu_31","textTraditional":"莽又言：「帝王建立社稷，百王不易。社者，土也。宗廟，王者所居。稷者，百穀之王，所以奉宗廟，共粢盛，〔一〕人所食以生活也。王者莫不尊重親祭，自為之主，禮如宗廟。詩曰『乃立冢土』。〔二〕又曰『以御田祖，以祈甘雨』。〔三〕禮記曰『唯祭宗廟社稷，為越紼而行事』。〔四〕聖漢興，禮儀稍定，已有官社，未立官稷。」〔五〕遂於官社後立官稷，以夏禹配食官社，后稷配食官稷。稷種穀樹。〔六〕徐州牧歲貢五色土各一斗。","sentenceOrder":222},
  {"id":"s_work_han_thu_31_223","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「共讀與供同。」","sentenceOrder":223},
  {"id":"s_work_han_thu_31_224","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　師古曰：「大雅綿之詩也。冢，大也。土，土神，謂太社也。」","sentenceOrder":224},
  {"id":"s_work_han_thu_31_225","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「小雅甫田之詩也。田祖，稷神也。言設樂以御祭於神，為農求甘雨也。」","sentenceOrder":225},
  {"id":"s_work_han_thu_31_226","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　李奇曰：「引棺車謂之紼。當祭天地五祀，則越紼而行事，不以私喪廢公祀。」師古曰：「紼，引車索也。音弗。」","sentenceOrder":226},
  {"id":"s_work_han_thu_31_227","chapterId":"ch_work_han_thu_31","textTraditional":"〔五〕　臣瓚曰：「高帝除秦社稷，立漢社稷，禮所謂太社也。時又立官社，配以夏禹，所謂王社也。見漢祀令。而未立官稷，至此始立之。世祖中興，不立官稷，相承至今也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_31_228","chapterId":"ch_work_han_thu_31","textTraditional":"〔六〕　師古曰：「穀樹，楮樹也。其子類穀，故於稷種。」","sentenceOrder":228},
  {"id":"s_work_han_thu_31_229","chapterId":"ch_work_han_thu_31","textTraditional":"莽篡位二年，興神僊事，以方士蘇樂言，起八風臺於宮中。臺成萬金，〔一〕作樂其上，順風作液湯。〔二〕又種五粱禾於殿中〔三〕，各順色置其方面，先煮鶴齔、毒冒、犀玉二十餘物漬種，〔四〕計粟斛成一金，言此黃帝穀僊之術也。以樂為黃門郎，令主之。莽遂崇鬼神淫祀，〔五〕至其末年，自天地六宗以下至諸小鬼神，凡千七百所，用三牲鳥獸三千餘種。後不能備，乃以雞當鶩鴈，犬當麋鹿。數下詔自以當僊，語在其傳。","sentenceOrder":229},
  {"id":"s_work_han_thu_31_230","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　師古曰：「費直萬金也。」","sentenceOrder":230},
  {"id":"s_work_han_thu_31_231","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　如淳曰：「藝文志有液湯經，其義未聞也。」","sentenceOrder":231},
  {"id":"s_work_han_thu_31_232","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「（玉）〔五〕色禾也，谷永所謂耕耘五德也。」","sentenceOrder":232},
  {"id":"s_work_han_thu_31_233","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　師古曰：「〈鬻，中“米改者”〉，古煮字也。齔，古髓字也。謂煮取汁以漬穀子也。毒音代，冒音莫內反。」","sentenceOrder":233},
  {"id":"s_work_han_thu_31_234","chapterId":"ch_work_han_thu_31","textTraditional":"〔五〕　師古曰：「崈，古崇字。」","sentenceOrder":234},
  {"id":"s_work_han_thu_31_235","chapterId":"ch_work_han_thu_31","textTraditional":"贊曰：漢興之初，庶事草創，唯一叔孫生略定朝廷之儀。若乃正朔服色郊望之事，數世猶未章焉。至於孝文，始以夏郊，而張倉據水德，公孫臣、賈誼更以為土德，卒不能明。孝武之世，文章為盛，太初改制，而兒寬、司馬遷等猶從臣、誼之言，〔一〕服色數度，遂順黃德。彼以五德之傳從所不勝，〔二〕秦在水德，故謂漢據土而克之。劉向父子以為帝出於震，故包羲氏始受木德，〔三〕其後以母傳子，終而復始，自神農、黃帝下歷唐虞三代而漢得火焉。故高祖始起，神母夜號，著赤帝之符，旗章遂赤，自得天統矣。〔四〕昔共工氏以水德間於木火，〔五〕與秦同運，非其次序，故皆不永。由是言之，祖宗之制蓋有自然之應，順時宜矣。究觀方士祠官之變，谷永之言，不亦正乎！不亦正乎！","sentenceOrder":235},
  {"id":"s_work_han_thu_31_236","chapterId":"ch_work_han_thu_31","textTraditional":"〔一〕　李奇曰：「公孫臣、賈誼。」","sentenceOrder":236},
  {"id":"s_work_han_thu_31_237","chapterId":"ch_work_han_thu_31","textTraditional":"〔二〕　服虔曰：「音亭傳之傳。五帝相承代，常以金木水火相勝之法，若火滅金，便以火代金。」師古曰：「傳音張戀反。」","sentenceOrder":237},
  {"id":"s_work_han_thu_31_238","chapterId":"ch_work_han_thu_31","textTraditional":"〔三〕　師古曰：「包讀曰庖。」","sentenceOrder":238},
  {"id":"s_work_han_thu_31_239","chapterId":"ch_work_han_thu_31","textTraditional":"〔四〕　鄧展曰：「向父子雖有此議，時不施行，至光武建武二年，乃用火德，色尚赤耳。」","sentenceOrder":239},
  {"id":"s_work_han_thu_31_240","chapterId":"ch_work_han_thu_31","textTraditional":"〔五〕　師古曰：「共讀曰龔。間音工莧反。」","sentenceOrder":240},
  {"id":"s_work_han_thu_31_241","chapterId":"ch_work_han_thu_31","textTraditional":"校勘記","sentenceOrder":241},
  {"id":"s_work_han_thu_31_242","chapterId":"ch_work_han_thu_31","textTraditional":"一二四三頁一０行　畢，尞堂下。〔八〕而上又上泰山，　注〔八〕原在「而上」下。劉敞說「而上」字屬下句。","sentenceOrder":242},
  {"id":"s_work_han_thu_31_243","chapterId":"ch_work_han_thu_31","textTraditional":"一二四四頁　七行　（後每）〔毋〕修封。　宋祁說越本「每」作「毋」，新本無「後」字，但云「毋修封」。按景祐本作「毋修封。」","sentenceOrder":243},
  {"id":"s_work_han_thu_31_244","chapterId":"ch_work_han_thu_31","textTraditional":"一二四八頁　三行　諸所興，如薄忌泰一及三一、冥羊、馬行、赤星，五（床）。寬舒之祠（宮）〔官〕以歲時致禮。王先謙說「床」字疑後人誤加，封禪書、孝武紀並無。「宮」字封禪書、孝武紀並作「官」，是，此誤。","sentenceOrder":244},
  {"id":"s_work_han_thu_31_245","chapterId":"ch_work_han_thu_31","textTraditional":"一二五六頁　九行　臣聞郊（紫壇）〔柴〕饗帝之義，　何焯說以文義求之，作「柴」為是，亦不當有「壇」字。按景祐、殿本「紫」都作「柴」，無「壇」字。","sentenceOrder":245},
  {"id":"s_work_han_thu_31_246","chapterId":"ch_work_han_thu_31","textTraditional":"一二五六頁一二行　（致）〔故〕上質不飾，　景祐、殿本都作「故」。朱一新說作「故」是。","sentenceOrder":246},
  {"id":"s_work_han_thu_31_247","chapterId":"ch_work_han_thu_31","textTraditional":"一二六一頁　九行　種五色禾於（北）〔此〕地而耕耘也。　景祐、殿本都作「此」。朱一新說作「此」是。","sentenceOrder":247},
  {"id":"s_work_han_thu_31_248","chapterId":"ch_work_han_thu_31","textTraditional":"一二六二頁一三行　是故每（奉）〔舉〕其禮，　景祐、殿本都作「舉」。朱一新說作「舉」是。","sentenceOrder":248},
  {"id":"s_work_han_thu_31_249","chapterId":"ch_work_han_thu_31","textTraditional":"一二六三頁　七行　言無（偽）〔徭〕費，　景祐、殿本都作「徭」。朱一新說作「徭」是。","sentenceOrder":249},
  {"id":"s_work_han_thu_31_250","chapterId":"ch_work_han_thu_31","textTraditional":"一二六七頁　四行　再變而致（嬴）〔臝〕物　朱一新說「嬴」當作「臝」。按景祐、殿本都作「臝」。","sentenceOrder":250},
  {"id":"s_work_han_thu_31_251","chapterId":"ch_work_han_thu_31","textTraditional":"一二七０頁　八行　（玉）〔五〕色禾也，　景祐、殿、局本都作「五」。王先謙說作「五」是。","sentenceOrder":251},
  {"id":"s_work_han_thu_32_1","chapterId":"ch_work_han_thu_32","textTraditional":"凡天文在圖籍昭昭可知者，經星常宿中外官凡百一十八名，積數七百八十三星，皆有州國官宮物類之象。其伏見蚤晚，邪正存亡，虛實闊陿，〔一〕及五星所行，合散犯守，陵歷鬥食，〔二〕彗孛飛流，日月薄食，〔三〕暈適背穴，抱珥{工虫}蜺，〔四〕迅雷風祅，怪雲變氣：此皆陰陽之精，其本在地，而上發于天者也。政失於此，則變見於彼，猶景之象形，鄉之應聲。〔五〕是以明君睹之而寤，飭身正事，思其咎謝，則禍除而福至，自然之符也。","sentenceOrder":1},
  {"id":"s_work_han_thu_32_2","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「伏見蚤晚，謂五星也。日月五星下道為邪。存謂列宿不虧也，亡謂恆星不見。虛實，若天牢星實則囚多，虛則開出之屬也。闊陿，若三台星相去遠近也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_32_3","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　孟康曰：「合，同舍也。散，五星有變則其精散為祅星也。犯，七寸以內光芒相及也。陵，相冒過也。食，星月相陵，不見者則所蝕也。」韋昭曰：「自下往觸之曰犯，居其宿曰守，經之為歷，突掩為陵，星相擊為鬥也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_32_4","chapterId":"ch_work_han_thu_32","textTraditional":"〔三〕　張晏曰：「彗所以除舊布新也。孛氣似彗。飛流謂飛星流星也。」孟康曰：「飛，絕跡而去也。流，光跡相連也。日月無光曰薄。京房易傳曰日月赤黃為薄。或曰不交而食曰薄。」韋昭曰：「氣往迫之為薄，虧毀曰食也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_32_5","chapterId":"ch_work_han_thu_32","textTraditional":"〔四〕　孟康曰：「（皆）〔暈〕，日旁氣也。適，日之將食先有黑之變也。背，形如背字也。穴多作鐍，其形如玉鐍也。抱，氣向日也。珥，形點黑也。」如淳曰：「暈讀曰運。{工虫}或作虹。蜺讀曰齧。螮蝀謂之{工虫}，表云雄為{工虫}，雌為蜺。凡氣（食）〔在〕日上為冠為戴，在旁直對為珥，在旁如半環向日為抱，向外為背。有氣剌日為鐍。鐍，抉傷也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_32_6","chapterId":"ch_work_han_thu_32","textTraditional":"〔五〕　師古曰：「鄉讀曰響。」","sentenceOrder":6},
  {"id":"s_work_han_thu_32_7","chapterId":"ch_work_han_thu_32","textTraditional":"中宮天極星，其一明者，泰一之常居也，旁三星三公，或曰子屬。後句四星，末大星正妃，餘三星後（官）〔宮〕之屬也。環之匡衛十二星，藩臣。皆曰紫宮。","sentenceOrder":7},
  {"id":"s_work_han_thu_32_8","chapterId":"ch_work_han_thu_32","textTraditional":"前列直斗口三星，隨北耑銳，若見若不見，曰陰德，或曰天一。紫宮左三星曰天槍，右四星曰天棓。〔一〕後十七星絕漢抵營室，曰閣道。","sentenceOrder":8},
  {"id":"s_work_han_thu_32_9","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　蘇林曰：「音棓打之棓。」師古曰：「棓音白講反。」","sentenceOrder":9},
  {"id":"s_work_han_thu_32_10","chapterId":"ch_work_han_thu_32","textTraditional":"北斗七星，所謂「旋、璣、玉衡以齊七政」。杓攜龍角，〔一〕衡殷南斗，魁枕參首。〔二〕用昏建者杓；杓，自華以西南。〔三〕夜半建者衡；衡，殷中州河、濟之間。〔四〕平旦建者魁；魁，海岱以東北也。〔五〕斗為帝車，運于中央，臨制四海。分陰陽，建四時，均五行，移節度，定緒紀，皆繫於斗。","sentenceOrder":10},
  {"id":"s_work_han_thu_32_11","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「杓，斗柄也。龍角，東方宿也。攜，連也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_32_12","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　晉灼曰：「衡，斗之中央。殷，中也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_32_13","chapterId":"ch_work_han_thu_32","textTraditional":"〔三〕　孟康曰：「傳曰『斗第七星法太白，主杓，斗之尾也』。尾為陰，又其用昏，昏陰，位在西方，故主西南。」","sentenceOrder":13},
  {"id":"s_work_han_thu_32_14","chapterId":"ch_work_han_thu_32","textTraditional":"〔四〕　孟康曰：「假令杓昏建寅，衡夜半亦建寅也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_32_15","chapterId":"ch_work_han_thu_32","textTraditional":"〔五〕　孟康曰：「傳曰『斗魁第一星法為日，主齊』。魁，斗之首；首，陽也，又其用在明，陽與明，德在東方，故主東北方。」","sentenceOrder":15},
  {"id":"s_work_han_thu_32_16","chapterId":"ch_work_han_thu_32","textTraditional":"斗魁戴筐六星，曰文昌宮：〔一〕一曰上將，二曰次將，三曰貴相，四曰司命，五曰司祿，六曰司災。在魁中，貴人之牢。〔二〕魁下六星兩兩而比者，曰三能。〔三〕三能色齊，君臣和；不齊，為乖戾。柄輔星，〔四〕明近，輔臣親彊；斥小，疏弱。〔五〕","sentenceOrder":16},
  {"id":"s_work_han_thu_32_17","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　晉灼曰：「似筐，故曰戴筐。」","sentenceOrder":17},
  {"id":"s_work_han_thu_32_18","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　孟康曰：「傳曰『天理四星在斗魁中』。貴人牢名曰天理也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_32_19","chapterId":"ch_work_han_thu_32","textTraditional":"〔三〕　蘇林曰：「能音台。」","sentenceOrder":19},
  {"id":"s_work_han_thu_32_20","chapterId":"ch_work_han_thu_32","textTraditional":"〔四〕　孟康曰：「在北斗第六星旁。」","sentenceOrder":20},
  {"id":"s_work_han_thu_32_21","chapterId":"ch_work_han_thu_32","textTraditional":"〔五〕　蘇林曰：「斥，遠也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_32_22","chapterId":"ch_work_han_thu_32","textTraditional":"杓端有兩星：一內為矛，招搖；〔一〕一外為盾，天蜂。〔二〕有句圜十五星，屬杓，曰賤人之牢。牢中星實則囚多，虛則開出。","sentenceOrder":22},
  {"id":"s_work_han_thu_32_23","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「近北斗者招搖，招搖為天矛。」晉灼曰：「梗河三星，天矛、鋒、招搖，一星耳。」","sentenceOrder":23},
  {"id":"s_work_han_thu_32_24","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　晉灼曰：「外，遠北斗也。在招搖南，一名天蜂。」","sentenceOrder":24},
  {"id":"s_work_han_thu_32_25","chapterId":"ch_work_han_thu_32","textTraditional":"天一、槍、棓、矛、盾動搖，角大，兵起。〔一〕","sentenceOrder":25},
  {"id":"s_work_han_thu_32_26","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　李奇曰：「角，芒角。」","sentenceOrder":26},
  {"id":"s_work_han_thu_32_27","chapterId":"ch_work_han_thu_32","textTraditional":"東宮蒼龍，房、心。心為明堂，大星天王，前後星子屬。不欲直；直，王失計。房為天府，曰天駟。其陰，右驂。旁有兩星曰衿。衿北一星曰牽。〔一〕東北曲十二星曰旗。旗中四星曰天市。天市中星眾者實，其中虛則耗。房南眾星曰騎官。","sentenceOrder":27},
  {"id":"s_work_han_thu_32_28","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　晉灼曰：「牽，古轄字。」","sentenceOrder":28},
  {"id":"s_work_han_thu_32_29","chapterId":"ch_work_han_thu_32","textTraditional":"左角，理；右角，將。大角者，天王帝坐廷。其兩旁各有三星，鼎足句之，曰攝提。〔一〕攝提者，直斗杓所指，以建時節，故曰「攝提格」。亢為宗廟，主疾。其南北兩大星，曰南門。氐為天根，主疫。尾為九子，曰君臣；斥絕，不和。箕為敖客，后妃之府，曰口舌。火犯守角，則有（戟）〔戰〕。房、心，王者惡之。","sentenceOrder":29},
  {"id":"s_work_han_thu_32_30","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　晉灼曰：「如鼎足之句曲也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_32_31","chapterId":"ch_work_han_thu_32","textTraditional":"南宮朱鳥，權、衡。〔一〕衡、太微，三光之廷。筐衛十二星，藩臣：西，將；東，相；南四星，執法；中，端門；左右，掖門。掖門內六星，諸侯。其內五星，五帝坐。後聚十五星，曰哀烏郎位；旁一大星，將位也。月、五星順入，軌道，司其出，所守，天子所誅也。其逆入，若不軌道，以所犯名之；中坐，成形，〔二〕皆群下不從謀也。金、火尤甚。廷藩西有隨星四，名曰少微，士大夫。權，軒轅，黃龍體。〔三〕前大星，女主象；旁小星，御者後宮屬。月、五星守犯者，如衡占。","sentenceOrder":31},
  {"id":"s_work_han_thu_32_32","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「軒轅為權，太微為衡也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_32_33","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　晉灼曰：「中坐，犯帝坐也。成形，禍福之形見。」","sentenceOrder":33},
  {"id":"s_work_han_thu_32_34","chapterId":"ch_work_han_thu_32","textTraditional":"〔三〕　孟康曰：「形如騰龍。」","sentenceOrder":34},
  {"id":"s_work_han_thu_32_35","chapterId":"ch_work_han_thu_32","textTraditional":"東井為水事。火入之，一星居其左右，天子且以火為敗。東井西曲星曰戉；北，北河；南，南河；兩河、天闕間為關梁。輿鬼，鬼祠事；中白者為質。〔一〕火守南北河，兵起，穀不登。故德成衡，觀成潢，〔二〕傷成戉，〔三〕禍成井，〔四〕誅成質。〔五〕","sentenceOrder":35},
  {"id":"s_work_han_thu_32_36","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　晉灼曰：「輿鬼五星，其中白者為質。」","sentenceOrder":36},
  {"id":"s_work_han_thu_32_37","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　晉灼曰：「日、月、五星不軌道也。衡，太微廷也。觀，占也。潢，五潢，五帝車舍也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_32_38","chapterId":"ch_work_han_thu_32","textTraditional":"〔三〕　晉灼曰：「賊傷之占，先成形於戉。」","sentenceOrder":38},
  {"id":"s_work_han_thu_32_39","chapterId":"ch_work_han_thu_32","textTraditional":"〔四〕　晉灼曰：「東井主水事，水入，一星居其旁，天子且以火敗，故曰禍也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_32_40","chapterId":"ch_work_han_thu_32","textTraditional":"〔五〕　晉灼曰：「熒惑入輿鬼天質，占曰大臣有誅。」","sentenceOrder":40},
  {"id":"s_work_han_thu_32_41","chapterId":"ch_work_han_thu_32","textTraditional":"柳為鳥喙，主木草。七星，頸，為員宮，主急事。張，嗉，為廚，主觴客。翼為羽翮，主遠客。","sentenceOrder":41},
  {"id":"s_work_han_thu_32_42","chapterId":"ch_work_han_thu_32","textTraditional":"軫為車，主風。其旁有一小星，曰長沙，星星不欲明；明與四星等，若五星入軫中，兵大起。軫南眾星曰天庫，庫有五車。車星角，若益眾，及不具，亡處車馬。","sentenceOrder":42},
  {"id":"s_work_han_thu_32_43","chapterId":"ch_work_han_thu_32","textTraditional":"西宮咸池，曰天五潢。五潢，五帝車舍。火入，旱；金，兵；水，水。中有三柱；柱不具，兵起。","sentenceOrder":43},
  {"id":"s_work_han_thu_32_44","chapterId":"ch_work_han_thu_32","textTraditional":"奎曰封豨，為溝瀆。婁為聚眾。胃為天倉。其南眾星曰廥積〔一〕。","sentenceOrder":44},
  {"id":"s_work_han_thu_32_45","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　如淳曰：「芻稿積為廥也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_32_46","chapterId":"ch_work_han_thu_32","textTraditional":"昴曰旄頭，胡星也，為白衣會。畢曰罕車，為邊兵，主弋獵。其大星旁小星為附耳。附耳搖動，有讒亂臣在側。昴、畢間為天街。其陰，陰國；陽，陽國。〔一〕","sentenceOrder":46},
  {"id":"s_work_han_thu_32_47","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「陰，西南，象坤維，河山已北國也。陽，河山已南國也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_32_48","chapterId":"ch_work_han_thu_32","textTraditional":"參為白虎。三星直者，是為衡石。〔一〕下有三星，銳，曰罰，〔二〕為斬艾事。其外四星，左右肩股也。小三星隅置，曰觜觿，為虎首，主葆旅事。〔三〕其南有四星，曰天廁。天廁下一星，曰天矢。矢黃則吉；青、白、黑，凶。其西有句曲九星，三處羅列：一曰天旗，二曰天苑，三曰九斿。其東有大星曰狼，狼角變色，多盜賊。下有四星曰弧，直狼。比地有大星，曰南極老人。〔四〕老人見，治安；不見，兵起。常以秋分時候之南郊。","sentenceOrder":48},
  {"id":"s_work_han_thu_32_49","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「參三星者，白虎宿中，東西直，似稱衡也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_32_50","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　孟康曰：「在參間，上小下大，故曰銳。」晉灼曰：「三星小邪列，無銳形也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_32_51","chapterId":"ch_work_han_thu_32","textTraditional":"〔三〕　如淳曰：「關中俗謂桑榆櫱生為葆。」晉灼曰：「禾野生曰旅，今之飢民采旅也。」宋均曰：「葆，守也。旅，軍旅也。言佐參伐斬艾除凶也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_32_52","chapterId":"ch_work_han_thu_32","textTraditional":"〔四〕　晉灼曰：「比地，近地也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_32_53","chapterId":"ch_work_han_thu_32","textTraditional":"北宮玄武，虛、危。危為蓋屋；〔一〕虛為哭泣之事。〔二〕其南有眾星，曰羽林天軍。〔三〕軍西為壘，或曰戉。旁一大星，北落。北落若微亡，軍星動角益稀，及五星犯北落，入軍，軍起。火、金、水尤甚。火入，軍憂；水，水患；木、土，軍吉。〔四〕危東六星，兩兩而比，曰司寇。","sentenceOrder":53},
  {"id":"s_work_han_thu_32_54","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　宋均曰：「危上一星高，旁兩星下，似蓋屋也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_32_55","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　宋均曰：「蓋屋之下中無人，但空虛，似乎殯宮，故主哭泣也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_32_56","chapterId":"ch_work_han_thu_32","textTraditional":"〔三〕　宋均曰：「虛、危、營室，陰陽終始之處，際會之間，恆多姦邪，故設羽林為軍衛。」","sentenceOrder":56},
  {"id":"s_work_han_thu_32_57","chapterId":"ch_work_han_thu_32","textTraditional":"〔四〕　孟康曰：「木星、土星入北落，軍則吉也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_32_58","chapterId":"ch_work_han_thu_32","textTraditional":"營室為清廟，曰離宮、閣道。漢中四星，曰天駟。旁一星，曰王梁。王梁策馬，車騎滿野。旁有八星，絕漢，曰天橫。天橫旁，江星。江星動，以人涉水。","sentenceOrder":58},
  {"id":"s_work_han_thu_32_59","chapterId":"ch_work_han_thu_32","textTraditional":"杵、臼四星，在危南。匏瓜，有青黑星守之，魚鹽貴。","sentenceOrder":59},
  {"id":"s_work_han_thu_32_60","chapterId":"ch_work_han_thu_32","textTraditional":"南斗為廟，其北建星。建星者，旗也。牽牛為犧牲，其北河鼓。河鼓大星，上將；左，左將；右，右將。婺女，其北織女。織女，天女孫也。","sentenceOrder":60},
  {"id":"s_work_han_thu_32_61","chapterId":"ch_work_han_thu_32","textTraditional":"歲星〔一〕曰東方春木，於人五常仁也，五事貌也。仁虧貌失，逆春令，傷木氣，罰見歲星。歲星所在，國不可伐，可以伐人。超舍而前為贏，退舍為縮。贏，其國有兵不復；縮，其國有憂，其將死，國傾敗。所去，失地；所之，得地。一曰，當居不居，國亡；所之，國昌；已居之，又東西去之，國凶，不可舉事用兵。安靜中度，吉。出入不當其次，必有天祅見其舍也。","sentenceOrder":61},
  {"id":"s_work_han_thu_32_62","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　晉灼曰：「太歲在四仲，則歲行三宿；太歲在四孟、四季，則歲行二宿。二八十六，三四十二，而行二十八宿。十二歲而周天。」","sentenceOrder":62},
  {"id":"s_work_han_thu_32_63","chapterId":"ch_work_han_thu_32","textTraditional":"歲星贏而東南，〔一〕石氏「見彗星」，甘氏「不出三月乃生彗，本類星，末類彗，長二丈」。贏東北，石氏「見覺星」，甘氏「不出三月乃生天棓，本類星，末銳，長四尺」。縮西南，〔二〕石氏「見欃雲，如牛」，〔三〕甘氏「不出三月乃生天槍，左右銳，長數丈」。縮西北，石氏「見槍雲，如馬」，甘氏「不出三月乃生天欃，本類星，末銳，長數丈」。石氏「槍、欃、棓、彗異狀，其殃一也，必有破國亂君，伏死其辜，餘殃不盡，為旱、凶、飢、暴疾」。至日行一尺，出二十餘日乃入，甘氏「其國凶，不可舉事用兵」。出而易，「所當之國，是受其殃」。又曰「祅星，不出三年，其下有軍，及失地，若國君喪」。","sentenceOrder":63},
  {"id":"s_work_han_thu_32_64","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「五星東行，天西轉。歲星晨見東方，行疾則不見，不見則變為祅星。」","sentenceOrder":64},
  {"id":"s_work_han_thu_32_65","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　孟康曰：「歲星當伏西方，行遲早沒，變為祅星也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_32_66","chapterId":"ch_work_han_thu_32","textTraditional":"〔三〕　韋昭曰：「欃音參差之參。」","sentenceOrder":66},
  {"id":"s_work_han_thu_32_67","chapterId":"ch_work_han_thu_32","textTraditional":"熒惑〔一〕曰南方夏火，禮也，視也。禮虧視失，逆夏令，傷火氣，罰見熒惑。逆行一舍二舍為不祥，居之三月國有殃，五月受兵，七月國半亡地，九月地太半亡。因與俱出入，國絕祀。熒惑為亂為（成）〔賊〕，為疾為喪，為飢為兵，所居之宿國受殃。殃還至者，雖大當小；居之久殃乃至者，當小反大。已去復還居之，若居之而角者，若動者，繞環之，及乍前乍後，乍左乍右，殃愈甚。一曰，熒惑出則有大兵，入則兵散。周還止息，乃為其死喪。寇亂在其野者亡地，以戰不勝。東行疾則兵聚于東方，西行疾則兵聚于西方；其南為丈夫喪，北為女子喪。熒惑，天子理也，故曰雖有明天子，必視熒惑所在。","sentenceOrder":67},
  {"id":"s_work_han_thu_32_68","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　晉灼曰：「常以十月入太微，受制而出，行列宿，司無道，出入無常也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_32_69","chapterId":"ch_work_han_thu_32","textTraditional":"太白〔一〕曰西方秋金，義也，言也。義虧言失，逆秋令，傷金氣，罰見太白。日方南太白居其南，日方北太白居其北，為贏，侯王不寧，用兵進吉退凶。日方南太白居其北，日方北太白居其南，為縮，侯王有憂，用兵退吉進凶。當出不出，當入不入，為失舍，不有破軍，必有死王之墓，有亡國。一曰，天下匽兵，野有兵者，所當之國大凶。當出不出，未當入而入，天下匽兵，兵在外，入。未當出而出，當入而不入，天下起兵，有至破國。未當出而出，未當入而入，天下舉兵，所當之國亡。當期而出，其國昌。出東為東方，入為北方；出西為西方，入為南方。所居久，其國利；易，其鄉凶。〔二〕入七日復出，將軍戰死。入十日復出，相死之。入又復出，人君惡之。已出三日而復微入，三日乃復盛出，是為耎而伏，〔三〕其下國有軍，其眾敗將北。已入三日，又復微出，三日乃復盛入，其下國有憂，帥師雖眾，敵食其糧，用其兵，虜其帥。出西方，失其行，夷狄敗；出東方，失其行，中國敗。一曰，出蚤為月食，晚為天祅及彗星，將發於亡道之國。","sentenceOrder":69},
  {"id":"s_work_han_thu_32_70","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　晉灼曰：「常以正月甲寅與熒惑晨出東方，二百四十日而入。入四十日又出西方，二百四十日而入。入三十五日而復出東方。出以寅戌，入以丑未也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_32_71","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　蘇林曰：「疾過也。一說，易鄉而出入也。」晉灼曰：「上言『出而易』，言疾過是也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_32_72","chapterId":"ch_work_han_thu_32","textTraditional":"〔三〕　晉灼曰：「耎，退也。不進而伏，伏不見也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_32_73","chapterId":"ch_work_han_thu_32","textTraditional":"太白出而留桑榆間，病其下國。〔一〕上而疾，未盡期日過參天，病其對國。〔二〕太白經天，天下革，民更王，〔三〕是為亂紀，人民流亡。晝見與日爭明，彊國弱，小國彊，女主昌。","sentenceOrder":73},
  {"id":"s_work_han_thu_32_74","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　晉灼曰：「行遲而下也。正出，舉目平正。出桑榆上，餘二千里也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_32_75","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　晉灼曰：「三分天過其一，此戌酉之間也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_32_76","chapterId":"ch_work_han_thu_32","textTraditional":"〔三〕　孟康曰：「謂出東入西，出西入東也。太白，陰星，出東當伏東，出西當伏西，過午為經天。」晉灼曰：「日，陽也；日出則星亡。晝見午上為經天。」","sentenceOrder":76},
  {"id":"s_work_han_thu_32_77","chapterId":"ch_work_han_thu_32","textTraditional":"太白，兵象也。出而高，用兵深吉淺凶；埤，淺吉深凶。行疾，用兵疾吉遲凶；行遲，用兵遲吉疾凶。角，敢戰吉，不敢戰凶；擊角所指吉，逆之凶。進退左右，用兵進退左右吉，靜凶。圜以靜，用兵靜吉趮凶。出則兵出，入則兵入。象太白吉，反之凶。赤角，戰。","sentenceOrder":77},
  {"id":"s_work_han_thu_32_78","chapterId":"ch_work_han_thu_32","textTraditional":"太白者，猶軍也，而熒惑，憂也。故熒惑從太白，軍憂；離之，軍舒。出太白之陰，有分軍；出其陽，有偏將之戰。當其行，太白還之，破軍殺將。","sentenceOrder":78},
  {"id":"s_work_han_thu_32_79","chapterId":"ch_work_han_thu_32","textTraditional":"辰星，殺伐之氣，戰鬥之象也。與太白俱出東方，皆赤而角，夷狄敗，中國勝；與太白俱出西方，皆赤而角，中國敗，夷狄勝。","sentenceOrder":79},
  {"id":"s_work_han_thu_32_80","chapterId":"ch_work_han_thu_32","textTraditional":"五星分天之中，積于東方，中國大利；積于西方，夷狄用兵者利。","sentenceOrder":80},
  {"id":"s_work_han_thu_32_81","chapterId":"ch_work_han_thu_32","textTraditional":"辰星不出，太白為客；辰星出，太白為主人。辰星與太白不相從，雖有軍不戰。辰星出東方，太白出西方。若辰星出西方，太白出東方，為格，野雖有兵，不戰。辰星入太白中，五日乃出，及入而上出，破軍殺將，客勝；下出，客亡地。辰星來抵，太白不去，將死。正其上出，破軍殺將，客勝；下出，客亡地。視其所指，以名破軍。辰星繞環太白，若鬥，大戰，客勝，主人吏死。辰星過太白，間可椷劍，小戰，客勝；〔一〕居太白前旬三日，軍罷；出太白左，小戰；歷太白右，數萬人戰，主人吏死；出太白右，去三尺，軍急約戰。","sentenceOrder":81},
  {"id":"s_work_han_thu_32_82","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　蘇林曰：「椷音函。函，容也，其間可容一劍也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_32_83","chapterId":"ch_work_han_thu_32","textTraditional":"凡太白所出所直之辰，其國為得位，得位者戰勝。所直之辰順其色而角者勝，其色害者敗。〔一〕太白白比狼，赤比心，黃比參右肩，青比參左肩，黑比奎大星。色勝位，〔二〕行勝色，〔三〕行得盡勝之。〔四〕","sentenceOrder":83},
  {"id":"s_work_han_thu_32_84","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　晉灼曰：「鄭色黃，而赤蒼，小敗；宋色黃，而赤黑，小敗；楚色赤，黑小敗；燕色黑，黃小敗。皆大角勝也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_32_85","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　晉灼曰：「有色勝得位也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_32_86","chapterId":"ch_work_han_thu_32","textTraditional":"〔三〕　晉灼曰：「太白行得度，勝有色也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_32_87","chapterId":"ch_work_han_thu_32","textTraditional":"〔四〕　晉灼曰：「行應天度，雖有色得位，行盡勝之，行重而色位輕。星經傳得字作德。」","sentenceOrder":87},
  {"id":"s_work_han_thu_32_88","chapterId":"ch_work_han_thu_32","textTraditional":"辰星〔一〕曰北方冬水，知也，聽也。知虧聽失，逆冬令，傷水氣，罰見辰星。出蚤為月食，晚為彗星及天祅。一時不出，其時不和；四時不出，天下大饑。失其時而出，為當寒反溫，當溫反寒。當出不出，是謂擊卒，兵大起。與它星遇而鬥，天下大亂。〔二〕出於房、心間，地動。","sentenceOrder":88},
  {"id":"s_work_han_thu_32_89","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　晉灼曰：「常以二月春分見奎、婁，五月夏至見東井，八月秋分見角、亢，十一月冬至見牽牛。出以辰戌，入以丑未，二旬而入。晨候之東方，夕候之西方也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_32_90","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　晉灼曰：「祅星彗孛之屬也，一曰五星。」","sentenceOrder":90},
  {"id":"s_work_han_thu_32_91","chapterId":"ch_work_han_thu_32","textTraditional":"填星〔一〕曰中央季夏土，信也，思心也。仁義禮智以信為主，貌言視聽以心為正，故四星皆失，填星乃為之動。填星所居，國吉。未當居而居之，若已去而復還居之，國得土，不乃得女子。當居不居，既已居之，又東西去之，國失土，不乃失女，不，有土事若女之憂。居宿久，國福厚；易，福薄。當居不居，為失填，其下國可伐；得者，不可伐。其贏，為王不寧；縮，有軍不復。一曰，既已居之又東西去之，其國凶，不可舉事用兵。失次而上一舍三舍，有王命不成，不乃大水；失次而下二舍，有后慼，其歲不復，不乃天裂若地動。","sentenceOrder":91},
  {"id":"s_work_han_thu_32_92","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　晉灼曰：「常以甲辰元始建斗之歲填行一宿，二十八歲而周天也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_32_93","chapterId":"ch_work_han_thu_32","textTraditional":"凡五星，歲與填合則為內亂，與辰合則為變謀而更事，與熒惑合則為飢，為旱，與太白合則為白衣之會，為水。太白在南，歲在北，名曰（牡）〔牝〕牡，〔一〕年穀大孰。太白在北，歲在南，年或有或亡。熒惑與太白合則為喪，不可舉事用兵；與填合則為憂，主孽卿；與辰合則為北軍，用兵舉事大敗。填與辰合則將有覆軍下師；與太白合則為疾，為內兵。辰與太白合則為變謀，為兵憂。凡歲、熒惑、填、太白四星與辰鬥，皆為戰，兵不在外，皆為內亂。一曰，火與水合為淬，〔二〕與金合為鑠，不可舉事用兵。土與金合國亡地，與木合則國饑，與水合為雍沮，〔三〕不可舉事用兵。木與金合鬥，國有內亂。同舍為合，相陵為鬥。二星相近者其殃大，二星相遠者殃無傷也，從七寸以內必之。〔四〕","sentenceOrder":93},
  {"id":"s_work_han_thu_32_94","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　晉灼曰：「歲，陽也，太白，陰也，故曰（牡）〔牝〕牡。」","sentenceOrder":94},
  {"id":"s_work_han_thu_32_95","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　晉灼曰：「火入水，故曰淬也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_32_96","chapterId":"ch_work_han_thu_32","textTraditional":"〔三〕　晉灼曰：「沮音沮溼之沮。水性雍而潛土，故曰雍沮。一曰，雍，填也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_32_97","chapterId":"ch_work_han_thu_32","textTraditional":"〔四〕　韋昭曰：「必有禍也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_32_98","chapterId":"ch_work_han_thu_32","textTraditional":"凡月食五星，其國（必）〔皆〕亡：〔一〕歲以飢，熒惑以亂，填以殺，太白彊國以戰，辰以女亂。月食大角，王者惡之。","sentenceOrder":98},
  {"id":"s_work_han_thu_32_99","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　李奇曰：「謂其分野之國。」","sentenceOrder":99},
  {"id":"s_work_han_thu_32_100","chapterId":"ch_work_han_thu_32","textTraditional":"凡五星所聚宿，其國王天下：從歲以義，從熒惑以禮，從填以重，〔一〕從太白以兵，從辰以法。以法者，以法致天下也。三星若合，是謂驚立絕行，〔二〕其國外內有兵與喪，民人乏飢，改立王公。四星若合，是謂大湯，〔三〕其國兵喪並起，君子憂，小人流。五星若合，是謂易行：有德受慶，改立王者，掩有四方，子孫蕃昌；亡德受罰，離其國家，滅其宗廟，〔四〕百姓離去，被滿四方。五星皆大，其事亦大；皆小，其事亦小也。","sentenceOrder":100},
  {"id":"s_work_han_thu_32_101","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　韋昭曰：「謂以威重得。」","sentenceOrder":101},
  {"id":"s_work_han_thu_32_102","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　晉灼曰：「有兵喪，故驚，改王，故曰絕也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_32_103","chapterId":"ch_work_han_thu_32","textTraditional":"〔三〕　晉灼曰：「湯猶盪滌也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_32_104","chapterId":"ch_work_han_thu_32","textTraditional":"〔四〕　晉灼曰：「宗祖廟也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_32_105","chapterId":"ch_work_han_thu_32","textTraditional":"凡五星色：皆圜，白為喪為旱，赤中不平為兵，青為憂為水，黑為疾為多死，黃吉；皆角，赤犯我城，黃地之爭，白哭泣之聲，青有兵憂，黑水。五星同色，天下匽兵，百姓安寧，歌舞以行，不見災疾，五穀蕃昌。","sentenceOrder":105},
  {"id":"s_work_han_thu_32_106","chapterId":"ch_work_han_thu_32","textTraditional":"凡五星，歲，緩則不行，急則過分，逆則占。熒惑，緩則不出，急則不入，違道則占。填，緩則不建，急則過舍，逆則占。太白，緩則不出，急則不入，逆則占。辰，緩則不出，急則不入，非時則占。五星不失行，則年穀豐昌。","sentenceOrder":106},
  {"id":"s_work_han_thu_32_107","chapterId":"ch_work_han_thu_32","textTraditional":"凡以宿星通下之變者，維星散，句星信，則地動。〔一〕有星守三淵，天下大水，地動，海魚出。紀星散者山崩，不即有喪。龜、鱉星不居漢中，川有易者。辰星入五車，大水。熒惑入積水，水，兵起；入積薪，旱，兵起；守之，亦然。極後有四星，名曰句星。斗杓後有三星，名曰維星。散者，不相從也。〔二〕三淵，蓋五車之三柱也。〔三〕天紀屬貫索。積薪在北戍西北。積水在北戍東北。","sentenceOrder":107},
  {"id":"s_work_han_thu_32_108","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「散在尾北。」韋昭曰：「信音申。」","sentenceOrder":108},
  {"id":"s_work_han_thu_32_109","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　孟康曰：「散，不復行列而聚也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_32_110","chapterId":"ch_work_han_thu_32","textTraditional":"〔三〕　晉灼曰：「柱音注解之注。」","sentenceOrder":110},
  {"id":"s_work_han_thu_32_111","chapterId":"ch_work_han_thu_32","textTraditional":"角、亢、氐，沇州。房、心，豫州。尾、箕，幽州。斗，江、湖。牽牛、婺女，揚州。虛、危，青州。營室、東壁，并州。奎、婁、胃，徐州。昂、畢，冀州。觜觿、參，益州。東井、輿鬼，雍州。柳、七星、張，三河。翼、軫，荊州。","sentenceOrder":111},
  {"id":"s_work_han_thu_32_112","chapterId":"ch_work_han_thu_32","textTraditional":"甲乙，海外，日月不占。〔一〕丙丁，江、淮、海、岱。戊己，中州河、濟。庚辛，華山以西。壬癸，常山以北。一曰，甲齊，乙東夷，丙楚，丁南夷，戊魏，己韓，庚秦，辛西夷，壬燕、趙，癸北夷。子周，丑翟，寅趙，卯鄭，辰邯鄲，巳衛，午秦，未中山，申齊，酉魯，戌吳、越，亥燕、代。","sentenceOrder":112},
  {"id":"s_work_han_thu_32_113","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　晉灼曰：「海外遠，甲乙日時，不以占之。」","sentenceOrder":113},
  {"id":"s_work_han_thu_32_114","chapterId":"ch_work_han_thu_32","textTraditional":"秦之疆，候太白，占狼、弧。吳、楚之疆，候熒惑，占鳥衡。燕、齊之疆，候辰星，占虛、危。宋、鄭之疆，候歲星，占房、心。晉之疆，亦候辰星，占參、罰。及秦并吞三晉、燕、代，自河、山以南者中國。中國於四海內則在東南，為陽，陽則日、歲星、熒惑、填星，占於街南，畢主之。其西北則胡、貉、月氏旃裘引弓之民，為陰，陰則月、太白、辰星，占於街北，昴主之。故中國山川東北流，其維，首在隴、蜀，尾沒於勃海碣石。是以秦、晉好用兵，〔一〕復占太白。太白主中國，而胡、貉數侵掠，獨占辰星。辰星出入趮疾，常主夷狄，其大經也。","sentenceOrder":114},
  {"id":"s_work_han_thu_32_115","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「秦、晉西南維之北為陰，與胡、貉引弓之民同，故好用兵。」","sentenceOrder":115},
  {"id":"s_work_han_thu_32_116","chapterId":"ch_work_han_thu_32","textTraditional":"凡五星，早出為贏，贏為客；晚出為縮，縮為主人。五星贏縮，必有天應見杓。","sentenceOrder":116},
  {"id":"s_work_han_thu_32_117","chapterId":"ch_work_han_thu_32","textTraditional":"太歲在寅曰攝提格。歲星正月晨出東方，石氏曰名監德，在斗、牽牛。失次，杓，早水，晚旱。甘氏在建星、婺女。太初曆在營室、東壁。","sentenceOrder":117},
  {"id":"s_work_han_thu_32_118","chapterId":"ch_work_han_thu_32","textTraditional":"在卯曰單閼。二月出，石氏曰名降入，在婺女、虛、危。甘氏在虛、危。失次，杓，有水災。太初在奎、婁。","sentenceOrder":118},
  {"id":"s_work_han_thu_32_119","chapterId":"ch_work_han_thu_32","textTraditional":"在辰曰執徐。三月出，石氏曰名青章，在營室、東壁。失次，杓，早旱，晚水。甘氏同。太初在胃、昴。","sentenceOrder":119},
  {"id":"s_work_han_thu_32_120","chapterId":"ch_work_han_thu_32","textTraditional":"在巳曰大荒落。四月出，石氏曰名路踵，在奎、婁。甘氏同。太初在參、罰。","sentenceOrder":120},
  {"id":"s_work_han_thu_32_121","chapterId":"ch_work_han_thu_32","textTraditional":"在午曰敦牂。五月出，石氏曰名啟明，在胃、昴、畢。失次，杓，早旱，晚水。甘氏同。太初在東井、輿鬼。","sentenceOrder":121},
  {"id":"s_work_han_thu_32_122","chapterId":"ch_work_han_thu_32","textTraditional":"在未曰協洽。六月出，石氏曰名長烈，在觜觿、參。甘氏在參、罰。太初在注、張、七星。","sentenceOrder":122},
  {"id":"s_work_han_thu_32_123","chapterId":"ch_work_han_thu_32","textTraditional":"在申曰涒灘。七月出。石氏曰名天晉，在東井、輿鬼。甘氏在弧。太初在翼、軫。","sentenceOrder":123},
  {"id":"s_work_han_thu_32_124","chapterId":"ch_work_han_thu_32","textTraditional":"在酉曰作詻。（爾雅作作噩。）八月出，石氏曰名長壬，在柳、七星、張。失次，杓，有女喪、民疾。甘氏在注、張。失次，杓，有火。太初在角、亢。","sentenceOrder":124},
  {"id":"s_work_han_thu_32_125","chapterId":"ch_work_han_thu_32","textTraditional":"在戌曰掩茂。九月出，石氏曰名天睢，在翼、軫。失次，杓，水。甘氏在七星、翼。太初在氐、房、心。","sentenceOrder":125},
  {"id":"s_work_han_thu_32_126","chapterId":"ch_work_han_thu_32","textTraditional":"在亥曰大淵獻。十月出，石氏曰名天皇，在角、亢始。甘氏在軫、角、亢。太初在尾、箕。","sentenceOrder":126},
  {"id":"s_work_han_thu_32_127","chapterId":"ch_work_han_thu_32","textTraditional":"在子曰困敦。十一月出，石氏曰名天宗，在氐、房始。甘氏同。太初在建星、牽牛。","sentenceOrder":127},
  {"id":"s_work_han_thu_32_128","chapterId":"ch_work_han_thu_32","textTraditional":"在丑曰赤奮若。十二月出，石氏曰名天昊，在尾、箕。甘氏在心、尾。太初在婺女、虛、危。","sentenceOrder":128},
  {"id":"s_work_han_thu_32_129","chapterId":"ch_work_han_thu_32","textTraditional":"甘氏、太初曆所以不同者，以星贏縮在前，各錄後所見也。其四星亦略如此。","sentenceOrder":129},
  {"id":"s_work_han_thu_32_130","chapterId":"ch_work_han_thu_32","textTraditional":"古曆五星之推，亡逆行者，至甘氏、石氏經，以熒惑、太白為有逆行。夫曆者，正行也。古人有言曰：「天下太平，五星循度，亡有逆行。日不食朔，月不食望。」夏氏日月傳曰：「日月食盡，主位也；不盡，臣位也。」星傳曰：「日者德也，月者刑也，故曰日食修德，月食修刑。」然而曆紀推月食，與二星之逆亡異。熒惑主內亂，太白主兵，月主刑。自周室衰，亂臣賊子師旅數起，刑罰失中，雖其亡亂臣賊子師旅之變，內臣猶不治，四夷猶不服，兵革猶不寢，刑罰猶不錯，故二星與月為之失度，三變常見；及有亂臣賊子伏尸流血之兵，大變乃出。甘、石氏見其常然，因以為紀，皆非正行也。詩云：「彼月而食，則惟其常；此日而食，于何不臧？」詩傳曰：「月食非常也，比之日食猶常也，日食則不臧矣。」謂之小變，可也；謂之正行，非也。故熒惑必行十六舍，去日遠而顓恣。太白出西方，進在日前，氣盛乃逆行。及月必食於望，亦誅盛也。","sentenceOrder":130},
  {"id":"s_work_han_thu_32_131","chapterId":"ch_work_han_thu_32","textTraditional":"國皇星，大而赤，狀類南極。所出，其下起兵。兵彊，其衝不利。〔一〕","sentenceOrder":131},
  {"id":"s_work_han_thu_32_132","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「歲星之精散所為也。五星之精散為六十四變，志記不盡也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_32_133","chapterId":"ch_work_han_thu_32","textTraditional":"昭明星，大而白，無角，乍上乍下。所出國，起兵多變。〔一〕","sentenceOrder":133},
  {"id":"s_work_han_thu_32_134","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「形如三足几，几上有九彗上向，熒惑之精也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_32_135","chapterId":"ch_work_han_thu_32","textTraditional":"五殘星，出正東，東方之星。其狀類辰，去地可六丈，大而黃。〔一〕","sentenceOrder":135},
  {"id":"s_work_han_thu_32_136","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「星表有青氣如暈，有毛，填星之精。」","sentenceOrder":136},
  {"id":"s_work_han_thu_32_137","chapterId":"ch_work_han_thu_32","textTraditional":"六賊星，出正南，南方之星。去地可六丈，大而赤，數動，有光。〔一〕","sentenceOrder":137},
  {"id":"s_work_han_thu_32_138","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「形如彗，芒九角，太白之精。」","sentenceOrder":138},
  {"id":"s_work_han_thu_32_139","chapterId":"ch_work_han_thu_32","textTraditional":"司詭星，出正西，西方之星。去地可六丈，大而白，類太白〔一〕。","sentenceOrder":139},
  {"id":"s_work_han_thu_32_140","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「星大而有尾，兩角，熒惑之精也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_32_141","chapterId":"ch_work_han_thu_32","textTraditional":"咸漢星，出正北，北方之星。去地可六丈，大而赤，數動，察之中青。〔一〕","sentenceOrder":141},
  {"id":"s_work_han_thu_32_142","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「一名獄漢星，青中赤表，下有三彗從橫，亦填星之精也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_32_143","chapterId":"ch_work_han_thu_32","textTraditional":"此四星所出非其方，其下有兵，衝不利。","sentenceOrder":143},
  {"id":"s_work_han_thu_32_144","chapterId":"ch_work_han_thu_32","textTraditional":"四填星，出四隅，去地可四丈。地維臧光，亦出四隅，去地可二丈，若月始出。所見下，有亂者亡，有德者昌。","sentenceOrder":144},
  {"id":"s_work_han_thu_32_145","chapterId":"ch_work_han_thu_32","textTraditional":"燭星，狀如太白，其出也不行，見則滅。所燭，城邑亂。〔一〕","sentenceOrder":145},
  {"id":"s_work_han_thu_32_146","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「星上有三彗上出，亦填星之精也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_32_147","chapterId":"ch_work_han_thu_32","textTraditional":"如星非星，如雲非雲，名曰歸邪。〔一〕歸邪出，必有歸國者。","sentenceOrder":147},
  {"id":"s_work_han_thu_32_148","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　李奇曰：「邪音蛇。」孟康曰：「星有兩赤彗上向，上有蓋狀氣，下連星。」","sentenceOrder":148},
  {"id":"s_work_han_thu_32_149","chapterId":"ch_work_han_thu_32","textTraditional":"星者，金之散氣，其本曰人。〔一〕星眾，國吉，少則凶。漢者，亦金散氣，其本曰水。星多，多水，少則旱，〔二〕其大經也。","sentenceOrder":149},
  {"id":"s_work_han_thu_32_150","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「星，石也，金石相生，人與星氣相應也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_32_151","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　孟康曰：「漢，河漢也。水生於金。多少，謂漢中星也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_32_152","chapterId":"ch_work_han_thu_32","textTraditional":"天鼓，有音如雷非雷，音在地而下及地。其所住者，兵發其下。","sentenceOrder":152},
  {"id":"s_work_han_thu_32_153","chapterId":"ch_work_han_thu_32","textTraditional":"天狗，狀如大流星，〔一〕有聲，（共）〔其〕下止地，類狗。所墜及，望之如火光炎炎中天。其下圜如數頃田處，上銳見則有黃色，千里破軍殺將。","sentenceOrder":153},
  {"id":"s_work_han_thu_32_154","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「星有尾，旁有彗，下有如狗形者，亦太白之精。」","sentenceOrder":154},
  {"id":"s_work_han_thu_32_155","chapterId":"ch_work_han_thu_32","textTraditional":"格澤者，如炎火之狀，黃白，起地而上，下大上銳。其見也，不種而穫。不有土功，必有大客。","sentenceOrder":155},
  {"id":"s_work_han_thu_32_156","chapterId":"ch_work_han_thu_32","textTraditional":"蚩尤之旗，類彗而後曲，象旗。〔一〕見則王者征伐四方。","sentenceOrder":156},
  {"id":"s_work_han_thu_32_157","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「熒惑之精也。」晉灼曰：「呂氏春秋云其色黃上白下也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_32_158","chapterId":"ch_work_han_thu_32","textTraditional":"旬始，出於北斗旁，狀如雄雞。其怒，青黑色，象伏鱉。〔一〕","sentenceOrder":158},
  {"id":"s_work_han_thu_32_159","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　李奇曰：「怒當（首）〔言〕帑。」晉灼曰：「帑，雌也。或曰怒則色青。」宋均曰：「怒謂芒角刺出。」","sentenceOrder":159},
  {"id":"s_work_han_thu_32_160","chapterId":"ch_work_han_thu_32","textTraditional":"枉矢，狀類大流星，蛇行而倉黑，望如有毛目然。","sentenceOrder":160},
  {"id":"s_work_han_thu_32_161","chapterId":"ch_work_han_thu_32","textTraditional":"長庚，廣如一匹布著天。此星見，起兵。","sentenceOrder":161},
  {"id":"s_work_han_thu_32_162","chapterId":"ch_work_han_thu_32","textTraditional":"星〈礈，去辶〉至地，則石也。〔一〕","sentenceOrder":162},
  {"id":"s_work_han_thu_32_163","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　如淳曰：「〈礈，去辶〉亦墜也。」","sentenceOrder":163},
  {"id":"s_work_han_thu_32_164","chapterId":"ch_work_han_thu_32","textTraditional":"天暒而見景星。〔一〕景星者，德星也，其狀無常，常出於有道之國。","sentenceOrder":164},
  {"id":"s_work_han_thu_32_165","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「暒，精明也。有赤方氣與青方氣相連，赤方中有兩黃星，青方中有一黃星，凡三星合為景星也。」","sentenceOrder":165},
  {"id":"s_work_han_thu_32_166","chapterId":"ch_work_han_thu_32","textTraditional":"日有中道，月有九行。","sentenceOrder":166},
  {"id":"s_work_han_thu_32_167","chapterId":"ch_work_han_thu_32","textTraditional":"中道者，黃道，一曰光道。光道北至東井，去北極近；南至牽牛，去北極遠；東至角，西至婁，去極中。夏至至於東井，北近極，故晷短；立八尺之表，而晷景長尺五寸八分。冬至至於牽牛，遠極，故晷長；立八尺之表，而晷景長丈三尺一寸四分。春秋分日至婁、角，去極中，而晷中；立八尺之表，而晷景長七尺三寸六分。此日去極遠近之差，晷景長短之制也。去極遠近難知，要以晷景。晷景者，所以知日之南北也。日，陽也。陽用事則日進而北，晝進而長，陽勝，故為溫暑；陰用事則日退而南，晝退而短，陰勝，故為涼寒也。故日進為暑，退為寒。若日之南北失節，晷過而長為常寒，退而短為常燠。此寒燠之表也。故曰為寒暑。一曰，晷長為潦，短為旱，奢為扶〔一〕。扶者，邪臣進而正臣疏，君子不足，姦人有餘。","sentenceOrder":167},
  {"id":"s_work_han_thu_32_168","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　鄭氏曰：「扶當為蟠，齊魯之間聲如酺。酺扶聲近。蟠，止不行也。」蘇林曰：「景形奢大也。」晉灼曰：「扶，附也，小臣佞媚附近君子之側也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_32_169","chapterId":"ch_work_han_thu_32","textTraditional":"月有九行者：黑道二，出黃道北；赤道二，出黃道南；白道二，出黃道西；青道二，出黃道東。立春、春分，月東從青道；立秋，秋分，西從白道；立冬、冬至，北從黑道；立夏、夏至，南從赤道。然用之，一決房中道。青赤出陽道，白黑出陰道。若月失節度而妄行，出陽道則旱風，出陰道則陰雨。","sentenceOrder":169},
  {"id":"s_work_han_thu_32_170","chapterId":"ch_work_han_thu_32","textTraditional":"凡君行急則日行疾，君行緩則日行遲。日行不可指而知也，故以二至二分之星為候。日東行，星西轉。冬至昏，奎八度中；夏至，氐十三度中；春分，柳一度中；秋分，牽牛三度七分中：此其正行也。日行疾，則星西轉疾，事勢然也。故過中則疾，君行急之感也；不及中則遲，君行緩之象也。","sentenceOrder":170},
  {"id":"s_work_han_thu_32_171","chapterId":"ch_work_han_thu_32","textTraditional":"至月行，則以晦朔決之。日冬則南，夏則北；冬至於牽牛，夏至於東井。日之所行為中道，月、五星皆隨之也。","sentenceOrder":171},
  {"id":"s_work_han_thu_32_172","chapterId":"ch_work_han_thu_32","textTraditional":"箕星為風，東北之星也。東北地事，天位也，〔一〕故易曰「東北喪朋」。及巽在東南，為風；風，陽中之陰，大臣之象也，其星，軫也。月去中道，移而東北入箕，若東南入軫，，則多風。西方為雨；雨，少陰之位也。月去中道，移而西入畢，則多雨。故詩云「月離于畢，俾滂沱矣」，言多雨也。星傳曰「月入畢則將相有以家犯罪者」，言陰盛也。書曰「星有好風，星有好雨，月之從星，則以風雨」，言失中道而東西也。故星傳曰「月南入牽牛南戒，民間疾疫；月北入太微，出坐北，若犯坐，則下人謀上。」","sentenceOrder":172},
  {"id":"s_work_han_thu_32_173","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「東北陽，日、月、五星起於牽牛，故為天位。坤在西南，紐於陽，為地統，故為地事也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_32_174","chapterId":"ch_work_han_thu_32","textTraditional":"一曰月為風雨，日為寒溫。冬至日南極，晷長，南不極則溫為害；夏至日北極，晷短，北不極則寒為害。故書曰「日月之行，則有冬有夏」也。政治變於下，日月運於上矣。（日）〔月〕出房北，為雨為陰，為亂為兵；出房南，為旱為夭喪。水旱至衝而應，及五星之變，必然之效也。","sentenceOrder":174},
  {"id":"s_work_han_thu_32_175","chapterId":"ch_work_han_thu_32","textTraditional":"兩軍相當，日暈等，力均；厚長大，有勝；薄短小，亡勝。重抱大破亡。抱為和，背為不和，為分離相去。直為自立，立兵破軍，若曰殺將。抱且戴，有喜。圍在中，中勝；在外，外勝。青外赤中，以和相去；赤外青中，以惡相去。氣暈先至而後去，居軍勝。先至先去，前有利，後有病；後至後去，前病後利；後至先去，前後皆病，居軍不勝。見而去，其後發疾，雖勝亡功。見半日以上，功（太）〔大〕。白{工虫}屈短，上下銳，〔一〕有者下大流血。日暈制勝，近期三十日，遠期六十日。","sentenceOrder":175},
  {"id":"s_work_han_thu_32_176","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　李奇曰：「屈或為尾。」韋昭曰：「短而直者也。或曰短屈之虹。」","sentenceOrder":176},
  {"id":"s_work_han_thu_32_177","chapterId":"ch_work_han_thu_32","textTraditional":"其食，食所不利；復生，生所利；不然，食盡為主位。以其直及日所躔加日時，用名其國。","sentenceOrder":177},
  {"id":"s_work_han_thu_32_178","chapterId":"ch_work_han_thu_32","textTraditional":"凡望雲氣，仰而望之，三四百里；平望，在桑榆上，千餘里，二千里；登高而望之，下屬地者居三千里。雲氣有（戰）〔獸〕居上者，勝。","sentenceOrder":178},
  {"id":"s_work_han_thu_32_179","chapterId":"ch_work_han_thu_32","textTraditional":"自華以南，氣下黑上赤。嵩高、三河之郊，氣正赤。常山以北，氣下黑上青。勃、碣、海、岱之間，氣皆黑。江、淮之間，氣皆白。","sentenceOrder":179},
  {"id":"s_work_han_thu_32_180","chapterId":"ch_work_han_thu_32","textTraditional":"徒氣白。土功氣黃。車氣乍高乍下，往往而聚。騎氣卑而布。卒氣摶。〔一〕前卑而後高者，疾；前方而後高者，銳；後銳而卑者，卻。其氣平者其行徐。前高後卑者，不止而反。氣相遇者，卑勝高，銳勝方。氣來卑而循車道者，不過三四日，去之五六里見。氣來高七八尺者，不過五六日，去之十餘二十里見。氣來高丈餘二丈者，不過三四十日，去之五六十里見。","sentenceOrder":180},
  {"id":"s_work_han_thu_32_181","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　如淳曰：「摶，專也。摶音徒端反。」","sentenceOrder":181},
  {"id":"s_work_han_thu_32_182","chapterId":"ch_work_han_thu_32","textTraditional":"捎雲精白者，其將悍，〔一〕其士怯。其大根而前絕遠者，戰。精白，其芒低者，戰勝；其前赤而卬者，戰不勝。陳雲如立垣。杼雲類杼。柚雲摶而耑銳。杓雲如繩者，居前竟天，其半半天。蜺雲者，類鬥旗故。（銳）鉤雲句曲。諸此雲見，以五色占。而澤摶密，其見動人，乃有占；兵必起。（占）〔合〕鬥其直。","sentenceOrder":182},
  {"id":"s_work_han_thu_32_183","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　晉灼曰：「捎音霄。」韋昭曰：「音髾。」","sentenceOrder":183},
  {"id":"s_work_han_thu_32_184","chapterId":"ch_work_han_thu_32","textTraditional":"王朔所候，決於日旁。日旁雲氣，人主象。皆如其形以占。","sentenceOrder":184},
  {"id":"s_work_han_thu_32_185","chapterId":"ch_work_han_thu_32","textTraditional":"故北夷之氣如群畜穹閭，南夷之氣類舟船幡旗。大水處，敗軍場，破國之虛，下有積泉，金寶上，皆有氣，不可不察。海旁蜃氣象樓臺，廣野氣成宮闕然。雲氣各象其山川人民所聚積。故侯息秏者，入國邑，視封疆田疇之整治，〔一〕城郭室屋門戶之潤澤，次至車服畜產精華。實息者吉，虛秏者凶。","sentenceOrder":185},
  {"id":"s_work_han_thu_32_186","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　如淳曰：「蔡邕云麻田曰疇。」","sentenceOrder":186},
  {"id":"s_work_han_thu_32_187","chapterId":"ch_work_han_thu_32","textTraditional":"若煙非煙，若雲非雲，郁郁紛紛，蕭索輪囷，是謂慶雲。慶雲見，喜氣也。若霧非霧，衣冠不濡，見則其城被甲而趨。","sentenceOrder":187},
  {"id":"s_work_han_thu_32_188","chapterId":"ch_work_han_thu_32","textTraditional":"夫雷電、赮{工虫}、辟歷、夜明者，陽氣之動者也，春夏則發，秋冬則藏，故候書者亡不司。","sentenceOrder":188},
  {"id":"s_work_han_thu_32_189","chapterId":"ch_work_han_thu_32","textTraditional":"天開縣物，〔一〕地動坼絕。山崩及陁，川塞谿垘；〔二〕水澹地長，澤竭見象。城郭門閭，潤息槁枯；宮廟廊第，人民所次。謠俗車服，觀民飲食。五穀草木，觀其所屬。倉府廄庫，四通之路。六畜禽獸，所產去就；魚鱉鳥鼠，觀其所處。鬼哭若謼，與人逢遌。訛言，誠然。","sentenceOrder":189},
  {"id":"s_work_han_thu_32_190","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「謂天裂而見物象也。天開示縣象。」","sentenceOrder":190},
  {"id":"s_work_han_thu_32_191","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　孟康曰：「垘音羅菔，謂谿垘崩也。」蘇林曰：「垘音伏。伏流也。」如淳曰：「垘，填塞不通也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_32_192","chapterId":"ch_work_han_thu_32","textTraditional":"凡候歲美惡，謹候歲始。歲始或冬至日，產氣始萌。臘明日，人眾卒歲，壹會飲食，發陽氣，故曰初歲。正月旦，王者歲首；立春，四時之始也。四始者，候之日。","sentenceOrder":192},
  {"id":"s_work_han_thu_32_193","chapterId":"ch_work_han_thu_32","textTraditional":"而漢魏鮮集臘明正月旦決八風。〔一〕風從南，大旱；西南，小旱；西方，有兵；西北，戎叔為，〔二〕小雨，趣兵；北方，為中歲；東北，為上歲；〔三〕東方，大水；東南，民有疾疫，歲惡。故八風各與其衝對，課多者為勝。多勝少，久勝亟，疾勝徐。旦至食，為麥；食至日跌，為（疾）〔稷〕；跌至晡，為黍；晡至下晡，為叔；下晡至日入，為麻。欲終日有雲，有風，有日，當其時，深而多實；亡雲，有風日，當其時，淺而少實；有雲風，亡日，當其時，深而少實；有日，亡雲，不風，當其時者稼有敗。如食頃，小敗；孰五斗米頃，大敗。風復起，有雲，其稼復起。各以其時用雲色占種所宜。雨雪，寒，歲惡。","sentenceOrder":193},
  {"id":"s_work_han_thu_32_194","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「魏鮮，人姓名，作占候者也。」","sentenceOrder":194},
  {"id":"s_work_han_thu_32_195","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　孟康曰：「戎叔，胡豆也。為，成也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_32_196","chapterId":"ch_work_han_thu_32","textTraditional":"〔三〕　韋昭曰：「上歲，大穰。」","sentenceOrder":196},
  {"id":"s_work_han_thu_32_197","chapterId":"ch_work_han_thu_32","textTraditional":"是日光明，聽都邑人民之聲。聲宮，則歲美，吉；商，有兵；徵，旱；羽，水；角，歲惡。","sentenceOrder":197},
  {"id":"s_work_han_thu_32_198","chapterId":"ch_work_han_thu_32","textTraditional":"或從正月旦比數雨。率日食一升，至七升而極；〔一〕過之，不占。數至十二日，直其月，占水旱。〔二〕為其環域千里內占，即為天下候，竟正月。〔三〕月所離列宿，日、風、雲，占其國。然必察太歲所在。金，穰；水，毀；木，飢；火，旱。此其大經也。","sentenceOrder":198},
  {"id":"s_work_han_thu_32_199","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「正月一日雨而民有一升之食，二日雨民有二升之食，如此至七日已來驗也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_32_200","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　孟康曰：「一日雨，正月水也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_32_201","chapterId":"ch_work_han_thu_32","textTraditional":"〔三〕　孟康曰：「月三十日周天歷二十八宿，然後可占天下。」","sentenceOrder":201},
  {"id":"s_work_han_thu_32_202","chapterId":"ch_work_han_thu_32","textTraditional":"正月上甲，風從東方來，宜蠶；從西方來，若旦有黃雲，惡。","sentenceOrder":202},
  {"id":"s_work_han_thu_32_203","chapterId":"ch_work_han_thu_32","textTraditional":"冬至短極，縣土炭，〔一〕炭動，麋鹿解角，蘭根出，泉水踊，略以知日至，要決晷景。","sentenceOrder":203},
  {"id":"s_work_han_thu_32_204","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「先冬至三日，縣土炭於衡兩端，輕重適均，冬至而陽氣至則炭重，夏至陰氣至則土重。」晉灼曰：「蔡邕曆律記『候鍾律權土炭，冬至陽氣應黃鍾通，土炭輕而衡仰，夏至陰氣應蕤賓通，土炭重而衡低。進退先後，五日之中』。」","sentenceOrder":204},
  {"id":"s_work_han_thu_32_205","chapterId":"ch_work_han_thu_32","textTraditional":"夫天運三十歲一小變，百年中變，五百年大變，三大變一紀，三紀而大備，此其大數也。","sentenceOrder":205},
  {"id":"s_work_han_thu_32_206","chapterId":"ch_work_han_thu_32","textTraditional":"春秋二百四十二年間，日食三十六，彗星三見，夜常星不見，夜中星隕如雨者各一。當是時，禍亂輒應，周室微弱，上下交怨，殺君三十六，亡國五十二，諸侯奔走不得保其社稷者不可勝數。自是之後，眾暴寡，大并小。秦、楚、吳、粵，夷狄也，為彊伯。田氏篡齊，三家分晉，並為戰國，爭於攻取，兵革遞起，城邑數屠，因以飢饉疾疫愁苦，臣主共憂患，其察禨祥候星氣尤急。〔一〕近世十二諸侯七國相王，言從橫者繼踵，而占天文者因時務論書傳，故其占驗鱗雜米鹽，亡可錄者。","sentenceOrder":206},
  {"id":"s_work_han_thu_32_207","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　如淳曰：「呂氏春秋『荊人鬼、越人禨』，今之巫祝禱祠淫祀之比也。」晉灼曰：「禨音珠璣之璣。」","sentenceOrder":207},
  {"id":"s_work_han_thu_32_208","chapterId":"ch_work_han_thu_32","textTraditional":"周卒為秦所滅。始皇之時，十五年間彗星四見，久者八十日，長或竟天。後秦遂以兵內兼六國，外攘四夷，死人如亂麻。又熒惑守心，及天市芒角，色赤如雞血。始皇既死，適庶相殺，二世即位，殘骨肉，戮將相，太白再經天。因以張楚並興，兵相跆籍，〔一〕秦遂以亡。","sentenceOrder":208},
  {"id":"s_work_han_thu_32_209","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　蘇林曰：「跆音臺，登躡也，或作蹈。」","sentenceOrder":209},
  {"id":"s_work_han_thu_32_210","chapterId":"ch_work_han_thu_32","textTraditional":"項羽救鉅鹿，枉矢西流，枉矢所觸，天下之所伐射，滅亡象也。物莫直於矢，今蛇行不能直而枉者，執矢者亦不正，以象項羽執政亂也。羽遂合從，阬秦人，屠咸陽。凡枉矢之流，以亂伐亂也。","sentenceOrder":210},
  {"id":"s_work_han_thu_32_211","chapterId":"ch_work_han_thu_32","textTraditional":"漢元年十月，五星聚於東井，以曆推之，從歲星也。〔一〕此高皇帝受命之符也。故客謂張耳曰：「東（并）〔井〕秦地，漢王入秦，五星從歲星聚，當以義取天下。」秦王子嬰降於枳道，漢王以屬吏，寶器婦女亡所取，閉宮封門，還軍次于霸上，以候諸侯。與秦民約法三章，民亡不歸心者，可謂能行義矣，天之所予也。五年遂定天下，即帝位。此明歲星之崇義，東井為秦之地明效也。","sentenceOrder":211},
  {"id":"s_work_han_thu_32_212","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　李奇曰：「歲星得其正度，其四星隨比常正行，故曰從也。」孟康曰：「歲星先至，先至為主也。」","sentenceOrder":212},
  {"id":"s_work_han_thu_32_213","chapterId":"ch_work_han_thu_32","textTraditional":"三年秋，太白出西方，有光幾中，〔一〕乍北乍南，過期乃入。辰星出四孟。〔二〕是時，項羽為楚王，而漢已定三秦，與相距滎陽。太白出西方，有光幾中，是秦地戰將勝，而漢國將興也。辰星出四孟，易主之表也。後二年，漢滅楚。","sentenceOrder":213},
  {"id":"s_work_han_thu_32_214","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　晉灼曰：「幾中，近踰身。」","sentenceOrder":214},
  {"id":"s_work_han_thu_32_215","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　韋昭曰：「法當出四仲，出四孟，為易主之象也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_32_216","chapterId":"ch_work_han_thu_32","textTraditional":"七年，月暈，圍參、畢七重。占曰：「畢、昴間，天街也；街北，胡也；街南，中國也。昴為匈奴，參為趙，畢為邊兵。」是歲高皇帝自將兵擊匈奴，至平城，為冒頓單于所圍，七日乃解。","sentenceOrder":216},
  {"id":"s_work_han_thu_32_217","chapterId":"ch_work_han_thu_32","textTraditional":"十二年春，熒惑守心。〔一〕四月，宮車晏駕。〔二〕","sentenceOrder":217},
  {"id":"s_work_han_thu_32_218","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　李奇曰：「心為天王也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_32_219","chapterId":"ch_work_han_thu_32","textTraditional":"〔二〕　應劭曰：「天子當晨起早作，而方崩殞，故稱晏駕云。」韋昭曰：「凡初崩為晏駕者，臣子之心，猶（為）〔謂〕宮車當駕而出耳。」","sentenceOrder":219},
  {"id":"s_work_han_thu_32_220","chapterId":"ch_work_han_thu_32","textTraditional":"孝惠二年，天開東北，廣十餘丈，長二十餘丈。地動，陰有餘；天裂，陽不足：皆下盛彊將害上之變也。其後有呂氏之亂。","sentenceOrder":220},
  {"id":"s_work_han_thu_32_221","chapterId":"ch_work_han_thu_32","textTraditional":"孝文後二年正月壬寅，天欃夕出西南。〔一〕占曰：「為兵喪亂。」其六年十一月，匈奴入上郡、雲中，漢起三軍以衛京師。其四月乙巳，水、木、火三合於東井。占曰：「外內有兵與喪，改立王公。東井，秦也。」八月，天狗下梁野，是歲誅反者周殷長安市。其七年六月，文帝崩。其十一月戊戌，土、水合於危。占曰：「為雍沮，所當之國不可舉事用兵，必受其殃。一曰將覆軍。危，齊也。」其七月，火東行，行畢陽，環畢東北，出而西，逆行至昴，即南乃東行。占曰：「為喪死寇亂。畢、昴，趙也。」","sentenceOrder":221},
  {"id":"s_work_han_thu_32_222","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「歲星之精。」","sentenceOrder":222},
  {"id":"s_work_han_thu_32_223","chapterId":"ch_work_han_thu_32","textTraditional":"孝景元年正月癸酉，金、水合於婺女。占曰：「為變謀，為兵憂。婺女，粵也，又為齊。」其七月乙丑，金、木、水三合於張。占曰：「外內有兵與喪，改立王公。張，周地，今之河南也，又為楚。」其二年七月丙子，火與水晨出東方，因守斗。占曰：「其國絕祀。」至其十二月，水、火合於斗。占曰：「為淬，不可舉事用兵，必受其殃。」一曰：「為北軍，用兵舉事大敗。斗，吳也，又為粵。」是歲彗星出西南。其三月，立六皇子為王，〔王〕淮陽、汝南、河間、臨江、長沙、廣川。其三年，吳、楚、膠西、膠東、淄川、濟南、趙七國反。吳、楚兵先至攻梁，膠西、膠東、淄川三國攻圍齊。漢遣大將軍周亞夫等戍止河南，以候吳楚之敝，遂敗之。吳王亡走粵，粵攻而殺之。平陽侯敗三國之師于齊，咸伏其辜，齊王自殺。漢兵以水攻趙城，城壞，王自殺。六月，立皇子二人、楚元王子一人為王，王膠西、中山、楚。徙濟北為淄川王，淮陽為魯王，汝南為江都王。七月，兵罷。天狗下，占為：「破軍殺將。狗又守禦類也，天狗所降，以戒守禦。」吳、楚攻梁，梁堅城守，遂伏尸流血其下。","sentenceOrder":223},
  {"id":"s_work_han_thu_32_224","chapterId":"ch_work_han_thu_32","textTraditional":"三年，填星在婁，幾入，還居奎。奎，魯也。占曰：「其國得地為得填。」是歲魯為國。","sentenceOrder":224},
  {"id":"s_work_han_thu_32_225","chapterId":"ch_work_han_thu_32","textTraditional":"四年七月癸未，火入東井，行陰，又以九月己未入輿鬼，戊寅出。占曰：「為誅罰，又為火災。」後二年，有栗氏事。其後未央東闕災。","sentenceOrder":225},
  {"id":"s_work_han_thu_32_226","chapterId":"ch_work_han_thu_32","textTraditional":"中元年，填星當在觜觿、參，去居東井。占曰：「亡地，不乃有女憂。」其（三）〔二〕年正月丁亥，金、木合於觜觿，為白衣之會。三月丁酉，彗星夜見西北，色白，長丈，在觜觿，且去益小，十五日不見。占曰：「必有破國亂君，伏死其辜。觜觿，梁也。」其五月甲午，金、木俱在東井。（戉）〔戊戌〕，金去木留，守之二十日。占曰：「傷成於戉。木為諸侯，誅將行於諸侯也。」其六月壬戌，蓬星見西南，在房南，去房可二丈，大如二斗器，色白；癸亥，在心東北，可長丈所；甲子，在尾北，可六丈；丁卯，在箕北，近漢，稍小，且去時，大如桃。壬申去，凡十日。占曰：「蓬星出，必有亂臣。房、心間，天子宮也。」是時梁王欲為漢嗣，使人殺漢爭臣袁盎。漢桉誅梁大臣，斧戉用。梁王恐懼，布車入關，伏斧戉謝罪，然後得免。","sentenceOrder":226},
  {"id":"s_work_han_thu_32_227","chapterId":"ch_work_han_thu_32","textTraditional":"中三年十一月庚午夕，金、火合於虛，相去一寸。占曰：「為鑠，為喪。虛，齊也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_32_228","chapterId":"ch_work_han_thu_32","textTraditional":"四年四月丙申，金、木合於東井。占曰：「為白衣之會。（非）〔井〕，秦也。」其五年四月乙巳，水、火合於參。占曰：「國不吉。參，梁也。」其六年四月，梁孝王死。五月，城陽王、濟陰王死。六月，成陽公主死。出入三月，天子四衣白，臨邸第。","sentenceOrder":228},
  {"id":"s_work_han_thu_32_229","chapterId":"ch_work_han_thu_32","textTraditional":"後元年五月壬午，火、金合於輿鬼之東北，不至柳，出輿鬼北可五寸。占曰：「為鑠，有喪。輿鬼，秦也。」丙戌，地大動，鈴鈴然，民大疫死，棺貴，至秋止。","sentenceOrder":229},
  {"id":"s_work_han_thu_32_230","chapterId":"ch_work_han_thu_32","textTraditional":"孝武建元三年三月，有星孛於注、張，歷太微，干紫宮，至於天漢。春秋「星孛於北斗，齊、（魯）〔宋〕、晉之君皆將死亂」。今星孛歷五宿，其後濟東、膠西、江都王皆坐法削黜自殺，淮陽、衡山謀反而誅。","sentenceOrder":230},
  {"id":"s_work_han_thu_32_231","chapterId":"ch_work_han_thu_32","textTraditional":"三年四月，有星孛於天紀，至織女。占曰：「織女有女變，天紀為地震。」至四年十月而地動，其後陳皇后廢。","sentenceOrder":231},
  {"id":"s_work_han_thu_32_232","chapterId":"ch_work_han_thu_32","textTraditional":"六年，熒惑守輿鬼。占曰：「為火變，有喪。」是歲高園有火災，竇太后崩。","sentenceOrder":232},
  {"id":"s_work_han_thu_32_233","chapterId":"ch_work_han_thu_32","textTraditional":"元光元年六月，客星見于房。占曰：「為兵起。」其二年十一月，單于將十萬騎入武州，漢遣兵三十餘萬以待之。","sentenceOrder":233},
  {"id":"s_work_han_thu_32_234","chapterId":"ch_work_han_thu_32","textTraditional":"元光中，天星盡搖，上以問候星者。對曰：「星搖者，民勞也。」後伐四夷，百姓勞于兵革。","sentenceOrder":234},
  {"id":"s_work_han_thu_32_235","chapterId":"ch_work_han_thu_32","textTraditional":"元鼎五年，太白入于天苑。占曰：「將以馬起兵也。」一曰：「馬將以軍而死秏。」其後以天馬故誅大宛，馬大死於軍。","sentenceOrder":235},
  {"id":"s_work_han_thu_32_236","chapterId":"ch_work_han_thu_32","textTraditional":"元鼎中，熒惑守南斗。占曰：「熒惑所守，為亂賊喪兵；守之久，其國絕祀。南斗，越分也。」其後越相呂嘉殺其王及太后，漢兵誅之，滅其國。","sentenceOrder":236},
  {"id":"s_work_han_thu_32_237","chapterId":"ch_work_han_thu_32","textTraditional":"元封中，星孛于河戍。占曰：「南戍為越門，北戍為胡門。」其後漢兵擊拔朝鮮，以為樂浪、玄菟郡。朝鮮在海中，越之象也；居北方，胡之域也。","sentenceOrder":237},
  {"id":"s_work_han_thu_32_238","chapterId":"ch_work_han_thu_32","textTraditional":"太初中，星孛于招搖。〔星〕傳曰：「客星守招搖，蠻夷有亂，民死君。」其後漢兵擊大宛，斬其王。招搖，遠夷之分也。","sentenceOrder":238},
  {"id":"s_work_han_thu_32_239","chapterId":"ch_work_han_thu_32","textTraditional":"孝昭始元中，漢宦者梁成恢及燕王候星者吳莫如見蓬星出西方天市東門，行過河鼓，入營室中。恢曰：「蓬星出六十日，不出三年，下有亂臣戮死於市。」後太白出西方，下行一舍，復上行二舍而下去。太白主兵，上復下，將有戮死者。後太白出東方，入咸池，東下入東井。人臣不忠，有謀上者。後太白入太微西藩第一星，北出東藩第一星，北東下去。太微者，天廷也，太白行其中，宮門當閉，大將被甲兵，邪臣伏誅。熒惑在婁，逆行至奎，法曰「當有兵」。後太白入昴。莫如曰：「蓬星出西方，當有大臣戮死者。太白星入東井、太微廷，出東門，漢有死將。」後熒惑出東方，守太白。兵當起，主人不勝。後流星下燕萬載宮極，東去，〔一〕法曰「國恐，有誅」。其後左將軍桀、票騎將軍安與長公主、燕剌王謀亂，咸伏其辜。兵誅烏桓。","sentenceOrder":239},
  {"id":"s_work_han_thu_32_240","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　李奇曰：「極，屋梁也，三輔間名為極。或曰，極，棟也，三輔間名棟為極。尋棟東去也。（廷）〔延〕篤謂之堂前闌楯也。」","sentenceOrder":240},
  {"id":"s_work_han_thu_32_241","chapterId":"ch_work_han_thu_32","textTraditional":"元鳳四年九月，客星在紫宮中斗樞極間。占曰：「為兵。」其五年六月，發三輔郡國少年詣北軍。五年四月，燭星見奎、婁間。占曰「有土功，胡人死，邊城和。」其六年正月，築遼東、玄菟城。二月，度遼將軍范明友擊烏桓還。","sentenceOrder":241},
  {"id":"s_work_han_thu_32_242","chapterId":"ch_work_han_thu_32","textTraditional":"元平元年正月庚子，日出時有黑雲，狀如（焱）〔猋〕風亂鬊，〔一〕轉出西北，東南行，轉而西，有頃亡。占曰：「有雲如眾風，是謂風師，法有大兵。」其後兵起烏孫，五將征匈奴。","sentenceOrder":242},
  {"id":"s_work_han_thu_32_243","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　〔師古曰〕：「音舜。」","sentenceOrder":243},
  {"id":"s_work_han_thu_32_244","chapterId":"ch_work_han_thu_32","textTraditional":"二月甲申，晨有大星如月，有眾星隨而西行。乙酉，牂雲如狗，赤色，長尾三枚，夾漢西行。大星如月，大臣之象，眾星隨之，眾皆隨從也。天文以東行為順，西行為逆，此大臣欲行權以安社稷。占曰：「太白散為天狗，為卒起。卒起見，禍無時，臣運柄。牂雲為亂君。」到其四月，昌邑王賀行淫辟，立二十七日，大將軍霍光白皇太后廢賀。","sentenceOrder":244},
  {"id":"s_work_han_thu_32_245","chapterId":"ch_work_han_thu_32","textTraditional":"三月丙戌，流星出翼、軫東北，干太微，入紫宮。始出小，且入大，有光。入有頃，聲如雷，三鳴止。占曰：「流星入紫宮，天下大凶。」其四月癸未，宮車晏駕。","sentenceOrder":245},
  {"id":"s_work_han_thu_32_246","chapterId":"ch_work_han_thu_32","textTraditional":"孝宣本始元年四月壬戌甲夜，辰星與參出西方。其二年七月辛亥夕，辰星與翼出，皆為蚤。占曰：「大臣誅。」其後熒惑守房之鉤鈐。鉤鈐，天子之御也。〔一〕占曰：「不太僕，則奉車，不黜即死也。房、心，天子宮也。房為將相，心為子屬也。其地宋，今楚彭城也。」四年七月甲辰，辰星在翼，月犯之。占曰：「兵起，上卿死，將相也。」是日，熒惑入輿鬼天質。占曰：「大臣有誅者，名曰天賊在大人之側。」","sentenceOrder":246},
  {"id":"s_work_han_thu_32_247","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　晉灼曰：「上言房為天駟，其陰右驂，旁有二星曰鈐，故曰天子御也。」","sentenceOrder":247},
  {"id":"s_work_han_thu_32_248","chapterId":"ch_work_han_thu_32","textTraditional":"地節元年正月戊午乙夜，月食熒惑，〔一〕熒惑在角、亢。占曰：「憂在宮中，非賊而盜也。有內亂，讒臣在旁。」其辛酉，熒惑入氐中。氐，天子之宮，熒惑入之，有賊臣。其六月戊戌甲夜，客星又居左右角間，東南指，長可二尺，色白。占曰：「有姦人在宮廷間。」其丙寅，又有客星見貫索東北，南行，至七月癸酉夜入天市，芒炎東南指，其色白。占曰：「有戮卿。」一曰：「有戮王。期皆一年，遠二年。」是時，楚王延壽謀逆自殺。四年，故大將軍霍光夫人顯、將軍霍禹、范明友、奉車霍山及諸昆弟賓婚為侍中、諸曹、九卿、郡守皆謀反，咸伏其辜。","sentenceOrder":248},
  {"id":"s_work_han_thu_32_249","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「凡星入月，見月中，為星食月；月奄星，星滅，為月食星。」","sentenceOrder":249},
  {"id":"s_work_han_thu_32_250","chapterId":"ch_work_han_thu_32","textTraditional":"黃龍元年三月，客星居王梁東北可九尺，長丈餘，西指，出閣道間，至紫宮。其十二月，宮車晏駕。","sentenceOrder":250},
  {"id":"s_work_han_thu_32_251","chapterId":"ch_work_han_thu_32","textTraditional":"元帝初元元年四月，客星大如瓜，色青白，在南斗第二星東可四尺。占曰：「為水飢。」其五月，勃海水大溢。六月，關東大飢，民多餓死，琅邪郡人相食。","sentenceOrder":251},
  {"id":"s_work_han_thu_32_252","chapterId":"ch_work_han_thu_32","textTraditional":"二年五月，客星見昴分，居卷舌東可五尺，青白色，炎長三寸。占曰：「天下有妄言者。」其十二月，鉅鹿都尉謝君男詐為神人，論死，父免官。〔一〕","sentenceOrder":252},
  {"id":"s_work_han_thu_32_253","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　孟康曰：「姓謝，名君。男者兒也，不記其名，直言男耳。」","sentenceOrder":253},
  {"id":"s_work_han_thu_32_254","chapterId":"ch_work_han_thu_32","textTraditional":"五年四月，彗星出西北，赤黃色，長八尺所，後數日長丈餘，東北指，在參分。後二歲餘，西羌反。","sentenceOrder":254},
  {"id":"s_work_han_thu_32_255","chapterId":"ch_work_han_thu_32","textTraditional":"孝成建始元年九月戊子，有流星出文昌，色白，光燭地，長可四丈，大一圍，動搖如龍蛇形。有頃，長可五六丈，大四圍所，詘折委曲，貫紫宮西，在斗西北子亥間。後詘如環，北方不合，留一（合）〔刻〕所。占曰：「文昌為上將貴相。」是時帝舅王鳳為大將軍，其後宣帝舅子王商為丞相，皆貴重任政。鳳妒商，譖而罷之。商自殺，親屬皆廢黜。","sentenceOrder":255},
  {"id":"s_work_han_thu_32_256","chapterId":"ch_work_han_thu_32","textTraditional":"四年七月，熒惑隃歲星，居其東北半寸所如連李。時歲星在關星西四尺所，熒惑初從畢口大星東東北往，數日至，往疾去遲。占曰：「熒惑與歲星鬥，有病君飢歲。」至河平元年三月，旱，傷麥，民食榆皮。二年十二月壬申，太皇太后避時昆明東觀。〔一〕","sentenceOrder":256},
  {"id":"s_work_han_thu_32_257","chapterId":"ch_work_han_thu_32","textTraditional":"〔一〕　如淳曰：「食貨志武帝修昆明池，列觀環之。或曰，即病謝君男，故避其時。」","sentenceOrder":257},
  {"id":"s_work_han_thu_32_258","chapterId":"ch_work_han_thu_32","textTraditional":"十一月乙卯，月食填星，星不見，時在輿鬼西北八九尺所。占曰：「月食填星，流民千里。」河平元年三月，流民入函谷關。","sentenceOrder":258},
  {"id":"s_work_han_thu_32_259","chapterId":"ch_work_han_thu_32","textTraditional":"河平二年十月下旬，填星在東井軒轅南耑大星尺餘，歲星在其西北尺所，熒惑在其西北二尺所，皆從西方來。填星貫輿鬼，先到歲星次，熒惑亦貫輿鬼。十一月上旬，歲星、熒惑西去填星，皆西北逆行。占曰：「三星若合，是謂驚位，是謂絕行，外內有兵與喪，改立王公。」其十一月丁巳，夜郎王歆大逆不道，牂柯太守立捕殺歆。三年九月甲戌，東郡莊平男子侯母辟兄弟五人群黨為盜，攻燔官寺，縛縣長吏，盜取印綬，自稱將軍。三月辛卯，左將軍千秋卒，右將軍史丹為左將軍。四年四月戊申，梁王賀薨。","sentenceOrder":259},
  {"id":"s_work_han_thu_32_260","chapterId":"ch_work_han_thu_32","textTraditional":"陽朔元年七月壬子，月犯心星。占曰：「其國有憂，若有大喪。房、心為宋，今楚地。」十一月辛未，楚王友薨。","sentenceOrder":260},
  {"id":"s_work_han_thu_32_261","chapterId":"ch_work_han_thu_32","textTraditional":"四夫閏月庚午，飛星大如缶，出西南，入斗下。占曰：「漢使匈奴。」明年，鴻嘉元年正月，匈奴單于雕陶莫皋死。五月甲午，遣中郎將楊興使弔。","sentenceOrder":261},
  {"id":"s_work_han_thu_32_262","chapterId":"ch_work_han_thu_32","textTraditional":"永始二年二月癸未夜，東方有赤色，大三四圍，長二三丈，索索如樹，南方有大四五圍，下行十餘丈，皆不至地滅。占曰：「東方客之變氣，狀如樹木，以此知四方欲動者。」明年十二月己卯，尉氏男子樊並等謀反，賊殺陳留太守嚴普及吏民，出囚徒，取庫兵，劫略令丞，自稱將軍，皆誅死。庚子，山陽鐵官亡徒蘇令等殺傷吏民，篡出囚徒，取庫兵，聚黨數百人為大賊，踰年經歷郡國四十餘。一日有兩氣同時起，並見，而並、令等同月俱發也。","sentenceOrder":262},
  {"id":"s_work_han_thu_32_263","chapterId":"ch_work_han_thu_32","textTraditional":"元延元年四月丁酉日餔時，天暒晏，殷殷如雷聲，有流星頭大如缶，長十餘丈，皎然赤白色，從日下東南去。四面或大如盂，或如雞子，燿燿如雨下，至昏止。郡國皆言星隕。春秋星隕如雨為王者失勢諸侯起伯之異也。其後王莽遂顓國柄。王氏之興萌於成帝〔時〕，是以有星隕之變。後莽遂篡國。","sentenceOrder":263},
  {"id":"s_work_han_thu_32_264","chapterId":"ch_work_han_thu_32","textTraditional":"綏和元年正月辛未，有流星從東南入北斗，長數十丈，二刻所息。占曰：「大臣有繫者。」其年十一月庚子，定陵侯淳于長坐執左道下獄死。","sentenceOrder":264},
  {"id":"s_work_han_thu_32_265","chapterId":"ch_work_han_thu_32","textTraditional":"二年春，熒惑守心。二月乙丑，丞相翟方進欲塞災異，自殺。（二）〔三〕月丙戌，宮車晏駕。","sentenceOrder":265},
  {"id":"s_work_han_thu_32_266","chapterId":"ch_work_han_thu_32","textTraditional":"哀帝建平元年正月丁未日出時，有著天白氣，廣如一匹布，長十餘丈，西南行，讙如雷，西南行一刻而止，名曰天狗。傳曰：「言之不從，則有犬禍詩妖。」到其四年正月、二月、三月，民相驚動，讙譁奔走，傳行詔籌祠西王母，又曰「從目人當來」。十二月，白氣出西南，從地上至天，出參下，貫天廁，廣如一疋布，長十餘丈，十餘日去。占曰：「天子有陰病。」其三年十一月壬子，太皇太后詔曰：「皇帝寬仁孝順，奉承聖緒，靡有解怠，而久病未瘳。夙夜惟思，殆繼體之君不宜改作。春秋大復古，其復甘泉泰畤、汾陰后土如故。」","sentenceOrder":266},
  {"id":"s_work_han_thu_32_267","chapterId":"ch_work_han_thu_32","textTraditional":"二年二月，彗星出牽牛七十餘日。傳曰：「彗所以除舊布新也。牽牛，日、月、五星所從起，曆數之元，三正之始。彗而出之，改更之象也。其出久者，為其事大也。」其六月甲子，夏賀良等建言當改元易號，增漏刻。詔書改建平二年為太初（元將）元年，號曰陳聖劉太平皇帝，刻漏以百二十為度。八月丁巳，悉復蠲除之，賀良及黨與皆伏誅流放。其後卒有王莽篡國之禍。","sentenceOrder":267},
  {"id":"s_work_han_thu_32_268","chapterId":"ch_work_han_thu_32","textTraditional":"元壽元年十一月，歲星入太微，逆行干右執法。占曰：「大臣有憂，執法者誅，若有罪。」二年十月戊寅，高安侯董賢免大司馬位，歸第自殺。","sentenceOrder":268},
  {"id":"s_work_han_thu_32_269","chapterId":"ch_work_han_thu_32","textTraditional":"校勘記","sentenceOrder":269},
  {"id":"s_work_han_thu_32_270","chapterId":"ch_work_han_thu_32","textTraditional":"一二七四頁　一行　（皆）〔暈〕，日旁氣也。　殿本考證說，「暈」監本訛「皆」，從宋本改。按景祐、汲古、局本都作「皆」，文義為長，但史記天官書「日月暈適」句裴駰集解引作「暈」，則不得作「皆」。","sentenceOrder":270},
  {"id":"s_work_han_thu_32_271","chapterId":"ch_work_han_thu_32","textTraditional":"一二七四頁　三行　凡氣（食）〔在〕日上為冠為戴，　景祐、殿本都作「在」。朱一新說作「在」是。","sentenceOrder":271},
  {"id":"s_work_han_thu_32_272","chapterId":"ch_work_han_thu_32","textTraditional":"一二七四頁　六行　餘三星後（官）〔宮〕之屬也。　景祐、殿本都作「宮」。朱一新說作「宮」是。","sentenceOrder":272},
  {"id":"s_work_han_thu_32_273","chapterId":"ch_work_han_thu_32","textTraditional":"一二七六頁　九行　火犯守角，則有（戟）〔戰〕　景祐、殿本都作「戰」。王先謙說作「戰」是。","sentenceOrder":273},
  {"id":"s_work_han_thu_32_274","chapterId":"ch_work_han_thu_32","textTraditional":"一二八一頁　八行　熒惑為亂為（成）〔賊〕，　景祐、殿、局本都作「賊」。朱一新說作「賊」是。","sentenceOrder":274},
  {"id":"s_work_han_thu_32_275","chapterId":"ch_work_han_thu_32","textTraditional":"一二八六頁　一行　名曰（牡）〔牝〕牡，　景祐、殿本都作「牝」，注同。朱一新說作「牝」是。","sentenceOrder":275},
  {"id":"s_work_han_thu_32_276","chapterId":"ch_work_han_thu_32","textTraditional":"一二八六頁一二行　其國（必）〔皆〕亡：　景祐、殿本都作「皆」。","sentenceOrder":276},
  {"id":"s_work_han_thu_32_277","chapterId":"ch_work_han_thu_32","textTraditional":"一二九０頁　六行　（爾雅作作噩）　王先謙說「爾雅」五字漢書無此例，非班自注，蓋校書者誤加之。","sentenceOrder":277},
  {"id":"s_work_han_thu_32_278","chapterId":"ch_work_han_thu_32","textTraditional":"一二九三頁　五行　（共）〔其〕下止地，類狗。　景祐、殿、局本都作「其」。王先謙說作「其」是。","sentenceOrder":278},
  {"id":"s_work_han_thu_32_279","chapterId":"ch_work_han_thu_32","textTraditional":"一二九三頁一三行　怒當（首）〔言〕帑。　景祐、殿本都作「言」。","sentenceOrder":279},
  {"id":"s_work_han_thu_32_280","chapterId":"ch_work_han_thu_32","textTraditional":"一二九六頁　五行　（日）〔月〕出房北，　景祐、殿本都作「月」。王先謙說作「月」是。","sentenceOrder":280},
  {"id":"s_work_han_thu_32_281","chapterId":"ch_work_han_thu_32","textTraditional":"一二九六頁一一行　見半日以上，功（太）〔大〕。　沈欽韓說「大」誤為「太」。按景祐、殿、局本都作「大」。","sentenceOrder":281},
  {"id":"s_work_han_thu_32_282","chapterId":"ch_work_han_thu_32","textTraditional":"一二九七頁　三行　雲氣有（戰）〔獸〕居上者，勝。　王念孫說「戰」當依天官書作「獸」。按殿本作「獸」。","sentenceOrder":282},
  {"id":"s_work_han_thu_32_283","chapterId":"ch_work_han_thu_32","textTraditional":"一二九七頁一四行　（銳）鉤雲句曲。　王先謙說「銳」字衍，天官書、晉、隋志皆無。","sentenceOrder":283},
  {"id":"s_work_han_thu_32_284","chapterId":"ch_work_han_thu_32","textTraditional":"一二九八頁　一行　兵必起，（占）〔合〕鬥其直。　王先謙說天官書「占」作「合」是。","sentenceOrder":284},
  {"id":"s_work_han_thu_32_285","chapterId":"ch_work_han_thu_32","textTraditional":"一二九九頁　七行　食至日跌，為（疾）〔稷〕，　景祐、殿本都作「稷」。朱一新說作「稷」是。","sentenceOrder":285},
  {"id":"s_work_han_thu_32_286","chapterId":"ch_work_han_thu_32","textTraditional":"一三０一頁一五行　東（并）〔井〕秦地，　景祐、殿、局本都作「井」。王先謙說作「井」是。","sentenceOrder":286},
  {"id":"s_work_han_thu_32_287","chapterId":"ch_work_han_thu_32","textTraditional":"一三０二頁一五行　臣子之心，猶（為）〔謂〕宮車當駕而出耳。　景祐、殿本都作「謂」。","sentenceOrder":287},
  {"id":"s_work_han_thu_32_288","chapterId":"ch_work_han_thu_32","textTraditional":"一三０三頁一五行　立六皇子為王，〔王〕淮陽　「王」字原缺，據景祐、殿、局本補。","sentenceOrder":288},
  {"id":"s_work_han_thu_32_289","chapterId":"ch_work_han_thu_32","textTraditional":"一三０四頁一０行　其（三）〔二〕年正月丁亥，　王念孫說中三年在下文，則此「三年」當作「二年」。","sentenceOrder":289},
  {"id":"s_work_han_thu_32_290","chapterId":"ch_work_han_thu_32","textTraditional":"一三０四頁一三行　（戉）〔戊戌〕，金去木留，　殿本作「戊戌」。朱一新說作「戊戌」是，自甲午至戊戌凡五日。","sentenceOrder":290},
  {"id":"s_work_han_thu_32_291","chapterId":"ch_work_han_thu_32","textTraditional":"一三０五頁　四行　（非）〔井〕，秦也。　景祐、殿本都作「井」。","sentenceOrder":291},
  {"id":"s_work_han_thu_32_292","chapterId":"ch_work_han_thu_32","textTraditional":"一三０五頁一０行　齊、（魯）〔宋〕、晉之君皆將死亂。　王先慎說「魯」為「宋」字之誤。　按左傳文十四年作「宋、齊、晉之君」。","sentenceOrder":292},
  {"id":"s_work_han_thu_32_293","chapterId":"ch_work_han_thu_32","textTraditional":"一三０六頁一０行　〔星〕傳曰：　朱一新說汪本有「星」字，此脫。　按景祐、殿本都有「星」字。","sentenceOrder":293},
  {"id":"s_work_han_thu_32_294","chapterId":"ch_work_han_thu_32","textTraditional":"一三０七頁　六行　（廷）〔延〕篤謂之堂前闌楯也。　景祐、殿本都作「延」。朱一新說作「延」是。","sentenceOrder":294},
  {"id":"s_work_han_thu_32_295","chapterId":"ch_work_han_thu_32","textTraditional":"一三０七頁一一行　狀如（焱）〔猋〕風亂鬊，　王先謙說當從三「犬」。「猋」，「飆」之通借字。","sentenceOrder":295},
  {"id":"s_work_han_thu_32_296","chapterId":"ch_work_han_thu_32","textTraditional":"一三０七頁一三行　〔師古曰〕：音舜。　葉德輝說疑此音上奪「師古曰」三字。","sentenceOrder":296},
  {"id":"s_work_han_thu_32_297","chapterId":"ch_work_han_thu_32","textTraditional":"一三０九頁一四行　留一（合）〔刻〕所。　景祐、殿本都作「刻」。朱一新說作「刻」是。","sentenceOrder":297},
  {"id":"s_work_han_thu_32_298","chapterId":"ch_work_han_thu_32","textTraditional":"一三一一頁　九行　王氏之興萌於成帝〔時〕，　景祐、殿本都有「時」字。","sentenceOrder":298},
  {"id":"s_work_han_thu_32_299","chapterId":"ch_work_han_thu_32","textTraditional":"一三一一頁一三行　（二）〔三〕月丙戌，　景祐、殿本都作「三」。　朱一新說作「三」是。","sentenceOrder":299},
  {"id":"s_work_han_thu_32_300","chapterId":"ch_work_han_thu_32","textTraditional":"一三一二頁　七行　詔書改建平二年為太初（元將）元年，　景祐、殿本都無「元將」二字，通鑑亦無。","sentenceOrder":300},
  {"id":"s_work_han_thu_33_1","chapterId":"ch_work_han_thu_33","textTraditional":"易曰：「天垂象，見吉凶，聖人象之；河出圖，雒出書，聖人則之。」〔一〕劉歆以為虙羲氏繼天而王，〔二〕受河圖，則而畫之，八卦是也；〔三〕禹治洪水，賜雒書，法而陳之，洪範是也。〔四〕聖人行其道而寶其真。降及于殷，箕子在父師位而典之。〔五〕周既克殷，以箕子歸，武王親虛己而問焉。故經曰：「惟十有三祀，王訪于箕子，〔六〕王乃言曰：『烏呼，箕子！惟天陰騭下民，相協厥居，我不知其彝倫逌敘。』〔七〕箕子乃言曰：『我聞在昔，鯀陻洪水，汨陳其五行，〔八〕帝乃震怒，弗畀洪範九疇，彝倫逌斁。〔九〕鯀則殛死，禹乃嗣興，〔一０〕天乃錫禹洪範九疇，彝倫逌敘。』」〔一一〕此武王問雒書於箕子，箕子對禹得雒書之意也。","sentenceOrder":1},
  {"id":"s_work_han_thu_33_2","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「上繫之辭也。則，效也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_33_3","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「虙讀與伏同。」","sentenceOrder":3},
  {"id":"s_work_han_thu_33_4","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「放效河圖而畫八卦也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_33_5","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「取法雒書而陳洪範也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_33_6","chapterId":"ch_work_han_thu_33","textTraditional":"〔五〕　師古曰：「父師，即太師，殷之三公也。箕子，紂之諸父而為太師，故曰父師。」","sentenceOrder":6},
  {"id":"s_work_han_thu_33_7","chapterId":"ch_work_han_thu_33","textTraditional":"〔六〕　師古曰：「祀，年也。商曰祀。自此以下皆周書洪範之文。」","sentenceOrder":7},
  {"id":"s_work_han_thu_33_8","chapterId":"ch_work_han_thu_33","textTraditional":"〔七〕　服虔曰：「騭音陟也。」應劭曰：「陰，覆也。陟，升也。相，助也。協，和也。倫，理也。攸，所也。言天覆下民，王者當助天居，我不知居天常理所次序也。」師古曰：「騭音質。騭，定也。協，和也。天不言而默定下人，助合其居。」","sentenceOrder":8},
  {"id":"s_work_han_thu_33_9","chapterId":"ch_work_han_thu_33","textTraditional":"〔八〕　應劭曰：「陻，塞也。汨，亂也。水性流行，而鯀障塞之，失其本性，其餘所陳列皆亂，故曰亂陳五行也。」師古曰：「汨音骨。」","sentenceOrder":9},
  {"id":"s_work_han_thu_33_10","chapterId":"ch_work_han_thu_33","textTraditional":"〔九〕　師古曰：「帝謂上帝，即天也。震，動也。畀，與也。疇，類也。九類即九章也。斁，敗也，音丁故反。」","sentenceOrder":10},
  {"id":"s_work_han_thu_33_11","chapterId":"ch_work_han_thu_33","textTraditional":"〔一０〕師古曰：「殛，誅也，見（殛）〔誅〕而死。殛音居力反。」","sentenceOrder":11},
  {"id":"s_work_han_thu_33_12","chapterId":"ch_work_han_thu_33","textTraditional":"〔一二〕師古曰：「自此以上，洪範之文。」","sentenceOrder":12},
  {"id":"s_work_han_thu_33_13","chapterId":"ch_work_han_thu_33","textTraditional":"「初一曰五行；〔一〕次二曰羞用五事；〔二〕次三曰農用八政；〔三〕次四曰旪用五紀；〔四〕次五曰建用皇極；〔五〕次六曰艾用三德；〔六〕次七曰明用稽疑；〔七〕次八曰念用庶徵；〔八〕次九曰嚮用五福，畏用六極。」〔九〕凡此六十五字，皆雒書本文，所謂天乃錫禹大法九章常事所次者也。以為河圖、雒書相為經緯，八卦、九章相為表裏。昔殷道弛，文王演周易；〔一０〕周道敝，孔子述春秋。則乾坤之陰陽，效洪範之咎徵，天人之道粲然著矣。","sentenceOrder":13},
  {"id":"s_work_han_thu_33_14","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「謂之行者，言順天行氣。」","sentenceOrder":14},
  {"id":"s_work_han_thu_33_15","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「羞，進也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_33_16","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　張晏曰：「農，食之本，食為八政首，故以農為名也。」師古曰：「此說非也。農，厚也。羞用義例皆同，非田農之義也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_33_17","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　應劭曰：「旪，合也，合成五行，為之條紀也。」師古曰：「旪讀曰協，和也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_33_18","chapterId":"ch_work_han_thu_33","textTraditional":"〔五〕　應劭曰：「皇，大；極，中也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_33_19","chapterId":"ch_work_han_thu_33","textTraditional":"〔六〕　應劭曰：「艾，治也。治大中之道用三德也。」師古曰：「艾讀曰乂。」","sentenceOrder":19},
  {"id":"s_work_han_thu_33_20","chapterId":"ch_work_han_thu_33","textTraditional":"〔七〕　應劭曰：「疑事明考之於蓍龜。」","sentenceOrder":20},
  {"id":"s_work_han_thu_33_21","chapterId":"ch_work_han_thu_33","textTraditional":"〔八〕　師古曰：「念，思也。庶，眾也。徵，應也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_33_22","chapterId":"ch_work_han_thu_33","textTraditional":"〔九〕　應劭曰：「天所以嚮樂人，用五福；所以畏懼人，用六極。」","sentenceOrder":22},
  {"id":"s_work_han_thu_33_23","chapterId":"ch_work_han_thu_33","textTraditional":"〔一０〕師古曰：「演，廣也，更廣其文也。演音弋善反。」","sentenceOrder":23},
  {"id":"s_work_han_thu_33_24","chapterId":"ch_work_han_thu_33","textTraditional":"漢興，承秦滅學之後，景、武之世，董仲舒治公羊春秋，始推陰陽，為儒者宗。宣、元之後，劉向治穀梁春秋，數其禍福，傳以洪範，〔一〕與仲舒錯。〔二〕至向子歆治左氏傳，其春秋意亦已乖矣；言五行傳，又頗不同。是以〈扌監〉仲舒，別向、歆，〔三〕傳載眭孟、夏侯勝、京房、谷永、李尋之徒所陳行事，〔四〕訖於王莽，舉十二世，以傅春秋，著於篇。〔五〕","sentenceOrder":24},
  {"id":"s_work_han_thu_33_25","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「旤，古文禍字。以洪範義傳而說之。傳字或作傅，讀曰附，謂附著。」","sentenceOrder":25},
  {"id":"s_work_han_thu_33_26","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「錯，互不同也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_33_27","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「〈扌監〉字與攬同，謂引取之。〈扌監〉音來敢反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_33_28","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「眭音息規反。說在眭孟傳。」","sentenceOrder":28},
  {"id":"s_work_han_thu_33_29","chapterId":"ch_work_han_thu_33","textTraditional":"〔五〕　師古曰：「傅讀曰附，謂比附其事。」","sentenceOrder":29},
  {"id":"s_work_han_thu_33_30","chapterId":"ch_work_han_thu_33","textTraditional":"經曰：「初一曰五行。五行：一曰水，二曰火，三曰木，四曰金，五曰土。水曰潤下，火曰炎上，〔一〕木曰曲直，〔二〕金曰從革，〔三〕土爰稼穡。」〔四〕","sentenceOrder":30},
  {"id":"s_work_han_thu_33_31","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「皆水火自然之性也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_33_32","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「言可揉而曲，可矯而直。」","sentenceOrder":32},
  {"id":"s_work_han_thu_33_33","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　張晏曰：「革，更也，可更銷鑄也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_33_34","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「爰亦曰也。一說爰，於也，可於其上稼穡也。種之曰稼。收聚曰穡。」","sentenceOrder":34},
  {"id":"s_work_han_thu_33_35","chapterId":"ch_work_han_thu_33","textTraditional":"傳曰：「田獵不宿，〔一〕飲食不享，〔二〕出入不節，奪民農時，及有姦謀，〔三〕則木不曲直。」","sentenceOrder":35},
  {"id":"s_work_han_thu_33_36","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　服虔曰：「不得其時也。或曰，不豫戒曰不宿，不戒以其時也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_33_37","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「不行享獻之禮也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_33_38","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　李奇曰：「姦謀，增賦履畝之事也。」臣瓚曰：「姦謀，邪謀也。」師古曰：「即下所謂作為姦詐以奪農時。李說是。」","sentenceOrder":38},
  {"id":"s_work_han_thu_33_39","chapterId":"ch_work_han_thu_33","textTraditional":"說曰：木，東方也。於易，地上之木為觀。〔一〕其於王事，威儀容貌亦可觀者也。故行步有佩玉之度，〔二〕登車有和鸞之節〔三〕，田狩有三驅之制，〔四〕飲食有享獻之禮，〔五〕出入有名，使民以時，務在勸農桑，謀在安百姓：如此，則木得其性矣。若乃田獵馳騁不反宮室，飲食沈湎不顧法度，〔六〕妄興繇役以奪民時，作為姦詐以傷民財，則木失其性矣。蓋工匠之為輪矢者多傷敗，〔七〕及木為變怪，〔八〕是為木不曲直。","sentenceOrder":39},
  {"id":"s_work_han_thu_33_40","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「坤下巽上，觀。巽為木，故云地上之木也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_33_41","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「玉佩上有雙衡，下有雙璜，琚瑀以雜之，（衡）〔衝〕牙（玭）〔蚍〕珠以納其間。右徵角而左宮羽，進則掩之，退則揚之，然後玉鏘鳴焉。是為行步之節度也。璜音黃。琚音居。瑀音禹。蚍音步千反。」","sentenceOrder":41},
  {"id":"s_work_han_thu_33_42","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「和，鈴也，以金為之，施於衡上。鸞亦以金為鸞鳥而銜鈴焉，施於鑣上。動皆有聲，以為舒疾之（疾）〔節〕也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_33_43","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「謂田獵三驅也。三驅之禮，一為乾豆，二為賓客，三為充君之庖也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_33_44","chapterId":"ch_work_han_thu_33","textTraditional":"〔五〕　師古曰：「以禮飲食謂之享，進爵於前謂之獻。」","sentenceOrder":44},
  {"id":"s_work_han_thu_33_45","chapterId":"ch_work_han_thu_33","textTraditional":"〔六〕　師古曰：「沈湎，謂溺於酒食。湎音彌善反。」","sentenceOrder":45},
  {"id":"s_work_han_thu_33_46","chapterId":"ch_work_han_thu_33","textTraditional":"〔七〕　如淳曰：「揉輪不曲，矯矢不直也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_33_47","chapterId":"ch_work_han_thu_33","textTraditional":"〔八〕　臣瓚曰：「梓柱更生及變為人形是也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_33_48","chapterId":"ch_work_han_thu_33","textTraditional":"春秋成公十六年「正月，雨，木冰」。劉歆以為上陽施不下通，下陰施不上達，故雨，而木為之冰，雰氣寒，〔一〕木不曲直也。劉向以為冰者陰之盛而水滯者也，木者少陽，貴臣卿大夫之象也。此人將有害，則陰氣（協）〔脅〕木，木先寒，故得雨而冰也。是時叔孫喬如出奔，公子偃誅死。〔二〕一曰，時晉執季孫行父，又執公，此執辱之異。〔三〕或曰，今之長老名木冰為「木介」。介者，甲。甲，兵象也。是歲晉有鄢陵之戰，楚王傷目而敗。〔四〕屬常雨也。","sentenceOrder":48},
  {"id":"s_work_han_thu_33_49","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「雰音紛。」","sentenceOrder":49},
  {"id":"s_work_han_thu_33_50","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「叔孫喬如，叔孫宣伯也，通於宣公夫人穆姜，謀欲作亂，不克而出奔齊。公子偃，宣公庶子，成公弟也，豫喬如之謀，故見誅。事並在十六年冬。」","sentenceOrder":50},
  {"id":"s_work_han_thu_33_51","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「行父，季文子也。十六年秋，公會晉侯于沙隨，晉受喬如之譖而止公。是年九月，又信喬如之譖而執行父也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_33_52","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「晉楚戰于鄢陵，呂錡射恭王中目。鄢陵，鄭地。」","sentenceOrder":52},
  {"id":"s_work_han_thu_33_53","chapterId":"ch_work_han_thu_33","textTraditional":"傳曰：「棄法律，逐功臣，殺太子，以妾為妻，則火不炎上。」","sentenceOrder":53},
  {"id":"s_work_han_thu_33_54","chapterId":"ch_work_han_thu_33","textTraditional":"說曰：火，南方，揚光煇為明者也。其於王者，南面鄉明而治。〔一〕書云：「知人則悊，能官人。」〔二〕故堯舜舉群賢而命之朝，〔三〕遠四佞而放諸野。〔四〕孔子曰：「浸潤之譖、膚受之訴不行焉，可謂明矣。」〔五〕賢佞分別，官人有序，帥由舊章，〔六〕敬重功勳，殊別適庶，〔七〕如此則火得其性矣。若乃信道不篤〔八〕，或燿虛偽，讒夫昌，邪勝正，則火失其性矣。自上而降，及濫炎妄起，〔九〕災宗廟，燒宮館，雖興師眾，弗能救也，是為火不炎上。","sentenceOrder":54},
  {"id":"s_work_han_thu_33_55","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":55},
  {"id":"s_work_han_thu_33_56","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「虞書咎繇謨之辭。悊，智也。能知其材則能官之，所以為智也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_33_57","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「謂稷、卨以下。」","sentenceOrder":57},
  {"id":"s_work_han_thu_33_58","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「四佞，即四凶也。遠，離也。野，古野字。」","sentenceOrder":58},
  {"id":"s_work_han_thu_33_59","chapterId":"ch_work_han_thu_33","textTraditional":"〔五〕　師古曰：「論語載孔子之言也。浸潤，言積漸也。膚受，謂初入皮膚以至骨髓也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_33_60","chapterId":"ch_work_han_thu_33","textTraditional":"〔六〕　師古曰：「帥，循也。由，從也，用也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_33_61","chapterId":"ch_work_han_thu_33","textTraditional":"〔七〕　師古曰：「適讀曰嫡。」","sentenceOrder":61},
  {"id":"s_work_han_thu_33_62","chapterId":"ch_work_han_thu_33","textTraditional":"〔八〕　師古曰：「篤，厚也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_33_63","chapterId":"ch_work_han_thu_33","textTraditional":"〔九〕　師古曰：「炎讀曰燄。」","sentenceOrder":63},
  {"id":"s_work_han_thu_33_64","chapterId":"ch_work_han_thu_33","textTraditional":"春秋桓公十四年「八月壬申，御廩災」。董仲舒以為先是四國共伐魯，大破之於龍門。〔一〕百姓傷者未瘳，怨咎未復，而君臣俱惰，內怠政事，外侮四鄰，非能保守宗廟終其天年者也，故天災御廩以戒之。劉向以為御廩，夫人八妾所舂米之臧以奉宗廟者也，〔二〕時夫人有淫行，〔三〕挾逆心，〔四〕天戒若曰，夫人不可以奉宗廟。桓不寤，與夫人俱會齊，〔五〕夫人譖桓公於齊侯，〔六〕齊侯殺桓公。〔七〕劉歆以為御廩，公所親耕籍田以奉粢盛者也，〔八〕棄法度亡禮之應也。","sentenceOrder":64},
  {"id":"s_work_han_thu_33_65","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　韋昭曰：「魯郭門。」","sentenceOrder":65},
  {"id":"s_work_han_thu_33_66","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「一娶九女，正嫡一人，餘者妾也，故云八妾。」","sentenceOrder":66},
  {"id":"s_work_han_thu_33_67","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「謂通於齊侯。」","sentenceOrder":67},
  {"id":"s_work_han_thu_33_68","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「謂欲弒桓公。」","sentenceOrder":68},
  {"id":"s_work_han_thu_33_69","chapterId":"ch_work_han_thu_33","textTraditional":"〔五〕　師古曰：「十八年春，公會齊侯于濼，公與夫人姜氏遂如齊也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_33_70","chapterId":"ch_work_han_thu_33","textTraditional":"〔六〕　師古曰：「言世子同非吾子，齊侯之子。」","sentenceOrder":70},
  {"id":"s_work_han_thu_33_71","chapterId":"ch_work_han_thu_33","textTraditional":"〔七〕　師古曰：「齊侯享公，公醉，使公子彭生乘公，拉其幹而殺之。公薨於車。」","sentenceOrder":71},
  {"id":"s_work_han_thu_33_72","chapterId":"ch_work_han_thu_33","textTraditional":"〔八〕　師古曰：「黍稷曰粢，在器曰盛也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_33_73","chapterId":"ch_work_han_thu_33","textTraditional":"嚴公二十年「夏，齊大災」。〔一〕劉向以為齊桓好色，聽女口，以妾為妻，適庶數更，〔二〕故致（太）〔大〕災。桓公不寤，及死，適庶分爭，九月不得葬。〔三〕公羊傳曰，大災，疫也。董仲舒以為魯夫人淫於齊，齊桓姊妹不嫁者七人。國君，民之父母；夫婦，生化之本。本傷則末夭，故天災所予也。〔二〕","sentenceOrder":73},
  {"id":"s_work_han_thu_33_74","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「嚴公，謂莊公也，避明帝諱，故改曰嚴。凡漢書載諡姓為嚴者，皆類此。」","sentenceOrder":74},
  {"id":"s_work_han_thu_33_75","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「更，改也，桓公之夫人三，王姬、徐嬴、蔡姬，皆無子。而桓公好內多寵，內嬖如夫人者六人：長衛姬，生公子無虧，即武孟也；少衛姬，生惠公；鄭姬生孝公；葛嬴生昭公；密姬生懿公；宋華子生公子雍。公與管仲屬孝公於宋襄公，以為太子。易牙有寵於衛恭姬，因寺人貂以薦羞於公，請立武孟。公許之。管仲卒，五公子皆求立。適讀曰嫡，下亦同。數音所角反。」","sentenceOrder":75},
  {"id":"s_work_han_thu_33_76","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「魯僖十七年，齊桓公卒，易牙入，因內寵以殺群吏，立無虧。孝公奔宋。十八年，齊立孝公，不勝（曰）〔四〕公子之徒，遂與宋人戰，敗齊師于甗，立孝公而還。八月，葬桓公，是為過於九月乃得葬也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_33_77","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　李奇曰：「以為疫殺其民人。」","sentenceOrder":77},
  {"id":"s_work_han_thu_33_78","chapterId":"ch_work_han_thu_33","textTraditional":"釐公二十年「五月（己酉）〔乙巳〕，西宮災」。〔一〕穀梁以為愍公宮也，以諡言之則若疏，故謂之西宮。劉向以為釐立妾母為夫人以入宗廟，〔二〕故天災愍宮，若曰，去其卑而親者，將害宗廟之正禮。〔三〕董仲舒以為釐娶於楚，而齊媵之，脅公使立以為夫人。〔四〕西宮者，小寢，夫人之居也。若曰，妾何為此宮！誅去之意也。以天災之，故大之曰西宮也。左氏以為西宮者，公宮也。言西，知有東。東宮，太子所居。言宮，舉區皆災也。","sentenceOrder":78},
  {"id":"s_work_han_thu_33_79","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「釐讀曰僖。後皆類此。」","sentenceOrder":79},
  {"id":"s_work_han_thu_33_80","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「僖公之母，謂成風也。本非正嫡，僖既為君，而母遂同夫人禮。文四年經書『夫人風氏薨』，五年『王使榮叔歸含且賵』，是也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_33_81","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「愍公於僖公為弟，故云卑。」","sentenceOrder":81},
  {"id":"s_work_han_thu_33_82","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「僖公初聘楚女為嫡，齊女為媵。時齊先致其女，脅魯使立為夫人。事見公羊、穀梁傳。」","sentenceOrder":82},
  {"id":"s_work_han_thu_33_83","chapterId":"ch_work_han_thu_33","textTraditional":"宣公十六年「夏，成周宣榭火」。〔一〕榭者，所以臧樂器，宣其名也。董仲舒、劉向以為十五年王札子殺召伯、毛伯，〔二〕天子不能誅。天戒若曰，不能行政令，何以禮樂為而臧之？左氏經曰：「成周宣榭火，人火也。人火曰火，天火曰災。」榭者，講武之坐屋。","sentenceOrder":83},
  {"id":"s_work_han_thu_33_84","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「公羊經也。成周，洛陽也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_33_85","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「王札子即王子捷也。召伯、毛伯，周二大夫也。召讀曰邵。後皆類此。」","sentenceOrder":85},
  {"id":"s_work_han_thu_33_86","chapterId":"ch_work_han_thu_33","textTraditional":"成公三年「二月甲子，新宮災」。穀梁以為宣宮，不言諡，恭也。劉向以為時魯三桓子孫始執國政，宣公欲誅之，恐不能，使大夫公孫歸父如晉謀。未反，宣公死。三家譖歸父於成公。成公父喪未葬，聽讒而逐其父之臣，使奔齊，〔一〕故天災宣宮，明不用父命之象也。一曰，三家親而亡禮，猶宣公殺子赤而立。〔二〕亡禮而親，天災宣廟，欲示去三家也。董仲舒以為成居喪亡哀戚心，數興兵戰伐〔三〕，故天災其父廟，示失子道，不能奉宗廟也。一曰，宣殺君而立，不當列於群祖也。","sentenceOrder":86},
  {"id":"s_work_han_thu_33_87","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「三桓，謂孟孫、叔孫、季孫三家，俱出桓公之子也。公孫歸父，東門襄仲之子也。歸父欲去三桓以張公室，與宣公謀，而聘于晉，欲以晉人去之。而宣公薨，成公即位，季文子及臧宣叔乃逐東門氏。歸父還，復命於介，遂出奔齊。」","sentenceOrder":87},
  {"id":"s_work_han_thu_33_88","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「赤，文公太子，即子惡也。宣公，文公之庶子，襄仲殺赤而立宣公。」","sentenceOrder":88},
  {"id":"s_work_han_thu_33_89","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「謂元年作丘甲，二年季孫行父帥師會晉郤克及齊侯戰于鞍，三年叔孫僑如帥師圍棘。」","sentenceOrder":89},
  {"id":"s_work_han_thu_33_90","chapterId":"ch_work_han_thu_33","textTraditional":"襄公九年「春，宋災」。劉向以為先是宋公聽讒，逐其大夫華弱，出奔魯。〔一〕左氏傳曰，宋災，樂喜為司城，〔二〕先使火所未至徹小屋，〔三〕塗大屋，〔四〕陳畚輂，〔五〕具綆缶，〔六〕備水器，〔七〕畜水潦，積土塗，〔八〕繕守備，〔九〕表火道，〔一０〕儲正徒。〔一一〕郊保之民，使奔火所。〔一二〕又飭眾官，各慎其職。〔一三〕晉侯聞之，問士弱曰：〔一四〕「宋災，於是乎知有天道，何故？」對曰：「古之火正，或食於心，或食於咮，以出入火。〔一五〕是故咮為鶉火，心為大火。陶唐氏之火正閼伯，居商丘，祀大火，而火紀時焉。相土因之，故商主大火。商人閱其禍敗之釁必始於火，是以知有天道。」公曰：「可必乎？」對曰：「在道。國亂亡象，不可知也。」〔一六〕說曰：古之火正，謂火官也，掌祭火星，行火政。季春昏，心星出東方，而咮、七星、鳥首正在南方，則用火；季秋，星入，則止火，以順天時，救民疾。帝嚳則有祝融，堯時有閼伯，民賴其德，死則以為火祖，配祭火星，故曰「或食於心，或食於咮也」。相土，商祖契之曾孫，〔一七〕代閼伯後主火星。宋，其後也。世司其占，故先知火災。賢君見變，能修道以除凶；亂君亡象，天不譴告，故不可必也。","sentenceOrder":90},
  {"id":"s_work_han_thu_33_91","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「華弱，華耦之孫也，與樂轡少相狎，長相優，又相謗。轡以弓梏弱于朝，宋平公怒，逐之，遂來奔。事在襄六年。」","sentenceOrder":91},
  {"id":"s_work_han_thu_33_92","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「司城，本司空，避武公之諱，故改其官為司城。」","sentenceOrder":92},
  {"id":"s_work_han_thu_33_93","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「恐火及之，故徹去。」","sentenceOrder":93},
  {"id":"s_work_han_thu_33_94","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「大屋難徹，故以泥塗之，令火至不可焚。」","sentenceOrder":94},
  {"id":"s_work_han_thu_33_95","chapterId":"ch_work_han_thu_33","textTraditional":"〔五〕　應劭曰：「畚，草籠也，讀與本同。輂，所以輿土也。」師古曰：「輂音居玉反。」","sentenceOrder":95},
  {"id":"s_work_han_thu_33_96","chapterId":"ch_work_han_thu_33","textTraditional":"〔六〕　師古曰：「綆，汲索也。缶即盎也。綆音工杏反。」","sentenceOrder":96},
  {"id":"s_work_han_thu_33_97","chapterId":"ch_work_han_thu_33","textTraditional":"〔七〕　師古曰：「罃瓮之屬也。許氏說文解字曰『罃備火，（金）〔今〕之長頸缾也』。」","sentenceOrder":97},
  {"id":"s_work_han_thu_33_98","chapterId":"ch_work_han_thu_33","textTraditional":"〔八〕　師古曰：「潦，行潦也。畜讀曰蓄。蓄謂障遏聚之也。塗，泥也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_33_99","chapterId":"ch_work_han_thu_33","textTraditional":"〔九〕　師古曰：「繕謂補修之也。修守禦之備，恐因火有它故也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_33_100","chapterId":"ch_work_han_thu_33","textTraditional":"〔一０〕師古曰：「火之所起之道皆立標記也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_33_101","chapterId":"ch_work_han_thu_33","textTraditional":"〔一一〕師古曰：「儲，偫也。正徒，役徒也。偫音丈紀反。」","sentenceOrder":101},
  {"id":"s_work_han_thu_33_102","chapterId":"ch_work_han_thu_33","textTraditional":"〔一二〕師古曰：「郊保之民，謂郊野之外保聚者也。使奔火所，共救災也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_33_103","chapterId":"ch_work_han_thu_33","textTraditional":"〔一三〕師古曰：「飭讀與（赤）〔敕〕同。」","sentenceOrder":103},
  {"id":"s_work_han_thu_33_104","chapterId":"ch_work_han_thu_33","textTraditional":"〔一四〕師古曰：「士弱，晉大夫士莊伯。」","sentenceOrder":104},
  {"id":"s_work_han_thu_33_105","chapterId":"ch_work_han_thu_33","textTraditional":"〔一五〕師古曰：「咮音竹救反。」","sentenceOrder":105},
  {"id":"s_work_han_thu_33_106","chapterId":"ch_work_han_thu_33","textTraditional":"〔一六〕韋昭曰：「大亂之君，天（下）〔不〕復告，故無象。」","sentenceOrder":106},
  {"id":"s_work_han_thu_33_107","chapterId":"ch_work_han_thu_33","textTraditional":"〔一七〕師古曰：「契讀曰偰，音先列反。字或作卨，其用同耳。據諸典籍，相土即卨之孫，今云曾孫，未詳其意。」","sentenceOrder":107},
  {"id":"s_work_han_thu_33_108","chapterId":"ch_work_han_thu_33","textTraditional":"三十年「五月甲午，宋災」。董仲舒以為伯姬如宋五年，宋恭公卒，〔一〕伯姬幽居守節三十餘年，又憂傷國家之患禍，積陰生陽，故火生災也。劉向以為先是宋公聽讒而殺太子痤，〔二〕應火不炎上之罰也。","sentenceOrder":108},
  {"id":"s_work_han_thu_33_109","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「伯姬，魯宣公女恭姬也。成九年歸于宋，十五年而宋公卒。今云如宋五年，則是轉寫誤。」","sentenceOrder":109},
  {"id":"s_work_han_thu_33_110","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「痤，宋平公太子也。寺人惠牆伊戾譖太子，云與楚（各）〔客〕盟，平公殺之。事在襄二十六年。痤音在戈反。」","sentenceOrder":110},
  {"id":"s_work_han_thu_33_111","chapterId":"ch_work_han_thu_33","textTraditional":"左氏傳昭公六年「六月丙戌，鄭災」。是春三月，鄭人鑄刑書。士文伯曰：「火見，鄭其火乎？〔一〕火未出而作火以鑄刑器，臧爭辟焉。〔二〕火而象之，不火何為？」說曰：火星出於周五月，而鄭以三月作火鑄鼎，刻刑辟書，以為民約，是為刑器爭辟。故火星出，與五行之火爭明為災，其象然也，又棄法律之占也。不書於經，時不告魯也。","sentenceOrder":111},
  {"id":"s_work_han_thu_33_112","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「士文伯，晉大夫伯瑕也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_33_113","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「著刑於鼎，故稱刑器。法設下爭，故云爭辟。」","sentenceOrder":113},
  {"id":"s_work_han_thu_33_114","chapterId":"ch_work_han_thu_33","textTraditional":"九年「夏四月，陳火」。〔一〕董仲舒以為陳夏徵舒殺君，楚嚴王託欲為陳討賊，陳國闢門而待之，至因滅陳。〔二〕陳臣子尤毒恨甚，極陰生陽，故致火災。劉向以為先是陳侯弟招殺陳太子偃師〔三〕，皆外事，不因其宮館者，略之也。八年十月壬午，楚師滅陳〔四〕，春秋不與蠻夷滅中國，故復書陳火也。〔五〕左氏經曰「陳災」。傳曰「鄭裨灶曰：『五年，陳將復封，〔六〕封五十二年而遂亡。』子產問其故，對曰：『陳，水屬也。火，水妃也，而楚所相也。今火出而火陳，逐楚而建陳也。妃以五（陳）〔成〕，故曰五年。歲五及鶉火，而後陳卒亡，楚克有之，天之道也。』」說曰：顓頊以水王，陳其族也。〔七〕今茲歲在星紀，後五年在大梁。大梁，昴也。金為水宗，得其宗而昌，故曰「五年陳將復封」。楚之先為火正，故曰「楚所相也」。天以一生水，地以二生火，天以三生木，地以四生金，天以五生土。五位皆以五而合，而陰陽易位，故曰「妃以五成」。然則水之大數六，火七，木八，金九，土十。故水以天一為火二牡，木以天三為土十牡，土以天五為水六牡，火以天七為金四牡，金以天九為木八牡。陽奇為牡，陰耦為妃。〔八〕故曰「水，火之牡也；火，水妃也」。於易，坎為水，為中男，離為火，為中女，蓋取諸此也。自大梁四歲而及鶉火，四周四十八歲，凡五及鶉火，五十二年而陳卒亡。火盛水衰，故曰「天之道也」。哀公十七年七月己卯，楚滅陳。","sentenceOrder":114},
  {"id":"s_work_han_thu_33_115","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「公羊（傳）〔經〕。」","sentenceOrder":115},
  {"id":"s_work_han_thu_33_116","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「夏徵舒，陳卿夏南，即少西氏也。徵舒之母通于靈公，靈公飲酒于夏氏，徵舒射而殺之。楚子為夏氏亂故伐陳，謂陳人無動，將討於少西氏，遂入陳，殺夏徵舒，轘諸栗門，因縣陳。事在宣公十一年。」","sentenceOrder":116},
  {"id":"s_work_han_thu_33_117","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「招謂陳哀公之弟。偃師即哀公子也。哀公有廢疾，招殺太子而立公子留。事在昭八年。招音韶。」","sentenceOrder":117},
  {"id":"s_work_han_thu_33_118","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「莊王初雖縣陳，納申叔時之諫，乃復封陳，至此時陳又為楚靈王所滅。」","sentenceOrder":118},
  {"id":"s_work_han_thu_33_119","chapterId":"ch_work_han_thu_33","textTraditional":"〔五〕　師古曰：「九年火時，陳已為楚縣，猶追書陳國者，以楚蠻夷，不許其滅中夏之國。」","sentenceOrder":119},
  {"id":"s_work_han_thu_33_120","chapterId":"ch_work_han_thu_33","textTraditional":"〔六〕　師古曰：「裨灶，鄭大夫。」","sentenceOrder":120},
  {"id":"s_work_han_thu_33_121","chapterId":"ch_work_han_thu_33","textTraditional":"〔七〕　師古曰：「陳，舜後也。舜本出顓頊。」","sentenceOrder":121},
  {"id":"s_work_han_thu_33_122","chapterId":"ch_work_han_thu_33","textTraditional":"〔八〕　師古曰：「奇音居宜反。」","sentenceOrder":122},
  {"id":"s_work_han_thu_33_123","chapterId":"ch_work_han_thu_33","textTraditional":"昭十八年「五月壬午，宋、衛、陳、鄭災」。董仲舒以為象王室將亂，天下莫救，故災四國，言亡四方也。又宋、衛、陳、鄭之君皆荒淫於樂，不恤國政，與周室同行。陽失節則火災出，是以同日災也。劉向以為宋、陳，王者之後，〔一〕衛、鄭，周同姓也。〔二〕時周景王老，劉子、單子事王子猛，〔三〕尹氏、召伯、毛伯事王子晁。〔四〕子晁，楚之出也。〔五〕及宋、衛、陳、鄭亦皆外附於楚，亡尊周室之心。後三年，景王崩，王室亂，故天災四國。天戒若曰，不救周，反從楚，廢世子，立不正，以害王室，明同罪也。","sentenceOrder":123},
  {"id":"s_work_han_thu_33_124","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「宋微子啟本出殷，陳胡公滿有虞苗裔，皆王者之後。」","sentenceOrder":124},
  {"id":"s_work_han_thu_33_125","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「衛康叔，文王之子。鄭桓公，宣王之弟。」","sentenceOrder":125},
  {"id":"s_work_han_thu_33_126","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「劉子，劉獻公摯也。單子，穆公旗也。皆周大夫也。猛，景王太子。單音善。」","sentenceOrder":126},
  {"id":"s_work_han_thu_33_127","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「尹氏，文公圉也。召伯，莊公奐也。毛伯，毛得也。皆周太夫也。子晁，景王庶子也。晁，古朝字。」","sentenceOrder":127},
  {"id":"s_work_han_thu_33_128","chapterId":"ch_work_han_thu_33","textTraditional":"〔五〕　師古曰：「姊妹之子曰出。」","sentenceOrder":128},
  {"id":"s_work_han_thu_33_129","chapterId":"ch_work_han_thu_33","textTraditional":"定公二年「五月，雉門及兩觀災」。〔一〕董仲舒、劉向以為此皆奢僭過度者也。先是，季氏逐昭公，昭公死于外。〔二〕定公即位，既不能誅季氏，又用其邪說，淫於女樂，而退孔子。〔三〕天戒若曰，去高顯而奢僭者。一曰，門闕，號令所由出也，今舍大聖而縱有罪，亡以出號令矣。京房易傳曰：「君不思道，厥妖火燒宮。」","sentenceOrder":129},
  {"id":"s_work_han_thu_33_130","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「雉門，公宮南門也。兩觀謂闕。」","sentenceOrder":130},
  {"id":"s_work_han_thu_33_131","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「謂薨于乾侯。」","sentenceOrder":131},
  {"id":"s_work_han_thu_33_132","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「齊人歸女樂，季桓子勸定公受之，君臣相與觀之，廢朝禮三日，孔子乃行。」","sentenceOrder":132},
  {"id":"s_work_han_thu_33_133","chapterId":"ch_work_han_thu_33","textTraditional":"哀公三年「五月辛卯，桓、釐宮災」。董仲舒、劉向以為此二宮不當立，違禮者也。哀公又以季氏之故不用孔子。孔子在陳聞魯災，曰：「其桓、釐之宮乎！」以為桓，季氏之所出，釐，使季氏世卿者也。","sentenceOrder":133},
  {"id":"s_work_han_thu_33_134","chapterId":"ch_work_han_thu_33","textTraditional":"四年「六月辛丑，亳社災」。〔一〕董仲舒、劉向以為亡國之社，所以為戒也。〔二〕天戒若曰，國將危亡，不用戒矣。春秋火災，屢於定、哀之間，不用聖人而縱驕臣，將以亡國，不明甚也。一曰，天生孔子，非為定、哀也，蓋失禮不明，火災應之，自然象也。","sentenceOrder":134},
  {"id":"s_work_han_thu_33_135","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「亳社，殷社也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_33_136","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「存其社者，欲使君常思敬慎，懼危亡也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_33_137","chapterId":"ch_work_han_thu_33","textTraditional":"高后元年五月丙申，趙叢臺災。劉向以為是時呂氏女為趙王后，嫉妒，將為讒口以害趙王。王不寤焉，卒見幽殺。","sentenceOrder":137},
  {"id":"s_work_han_thu_33_138","chapterId":"ch_work_han_thu_33","textTraditional":"惠帝四年十月乙亥，未央宮凌室災；〔一〕丙子，織室災。〔二〕劉向以為元年呂太后殺趙王如意，殘戮其母戚夫人。是歲十月壬寅，太后立帝姊魯元公主女為皇后。其乙亥，凌室災。明日，織室災。凌室所以供養飲食，織室所以奉宗廟衣服，與春秋御廩同義。天戒若曰，皇后亡奉宗廟之德，將絕祭祀。其後，皇后亡子，後宮美人有男，太后使皇后名之，而殺其母。惠帝崩，嗣子立，有怨言，太后廢之，更立呂氏子弘為少帝。賴大臣共誅諸呂而立文帝，惠后幽廢。","sentenceOrder":138},
  {"id":"s_work_han_thu_33_139","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「臧冰之室也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_33_140","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「織作之室。」","sentenceOrder":140},
  {"id":"s_work_han_thu_33_141","chapterId":"ch_work_han_thu_33","textTraditional":"文帝七年六月癸酉，未央宮東闕罘思災。〔一〕劉向以為東闕所以朝諸侯之門也，罘思在其外，諸侯之象也。漢興，大封諸侯王，連城數十。文帝即位，賈誼等以為違古制度，必將叛逆。先是，濟北、淮南王皆謀反，其後吳楚七國舉兵而誅。","sentenceOrder":141},
  {"id":"s_work_han_thu_33_142","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「罘思，闕之屏也。解具在文紀。」","sentenceOrder":142},
  {"id":"s_work_han_thu_33_143","chapterId":"ch_work_han_thu_33","textTraditional":"景帝中五年八月己酉，未央宮東闕災。先是，栗太子廢為臨江王，〔一〕以罪徵詣中尉，自殺。丞相條侯周亞夫以不合旨稱疾免，後二年下獄死。","sentenceOrder":143},
  {"id":"s_work_han_thu_33_144","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「景帝太子，栗姬所生，謂之栗太子。」","sentenceOrder":144},
  {"id":"s_work_han_thu_33_145","chapterId":"ch_work_han_thu_33","textTraditional":"武帝建元六年六月丁酉，遼東高廟災。四月壬子，高園便殿火。董仲舒對曰：「春秋之道舉往以明來，是故天下有物，視春秋所舉與同比者，〔一〕精微眇以存其意，通倫類以貫其理，天地之變，國家之事，粲然皆見，亡所疑矣。按春秋魯定公、哀公時，季氏之惡已孰，〔二〕而孔子之聖方盛。夫以盛聖而易孰惡，季孫雖重，魯君雖輕，其勢可成也。故定公二年五月兩觀災。兩觀，僭禮之物，〔三〕天災之者，若曰，僭禮之臣可以去。已見罪徵，而後告可去，此天意也。定公不知省。〔四〕至哀公三年五月，桓宮、釐宮災。二者同事，所為一也，若曰燔貴而去不義云爾。〔五〕哀公未能見，故四年六月亳社災。兩觀、桓、釐廟、亳社，四者皆不當立，天皆燔其不當立者以示魯，欲其去亂臣而用聖人也。季氏亡道久矣，前是天不見災者，魯未有賢聖臣，雖欲去季孫，其力不能，昭公是也。〔六〕至定、哀乃見之，其時可也。不時不見，天之道也。今高廟不當居遼東，高園殿不當居陵旁，於禮亦不當立，與魯所災同。其不當立久矣，至於陛下時天乃災之者，殆亦其時可也。昔秦受亡周之敝，而亡以化之；漢受亡秦之敝，又亡以化之。夫繼二敝之後，承其下流，兼受其猥，難治甚矣。〔七〕又多兄弟親戚骨肉之連，驕揚奢侈〔八〕恣睢者眾，〔九〕所謂重難之時者也。陛下正當大敝之後，又遭重難之時，甚可憂也。故天災若語陛下：『當今之世，雖敝而重難，非以太平至公，不能治也。視親戚貴屬在諸侯遠正最甚者，忍而誅之，〔一０〕如吾燔遼〔東〕高廟乃可；視近臣在國中處旁仄及貴而不正者，忍而誅之，〔一一〕如吾燔高園殿乃可』云爾。在外而不正者，雖貴如高廟，猶災燔之，況諸侯乎！在內不正者，雖貴如高園殿，猶燔災之，況大臣乎！此天意也。罪在外者天災外，罪在內者天災內，燔甚罪當重，燔簡罪當輕，承天意之道也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_33_146","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「比，類也，音必寐反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_33_147","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「孰，成也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_33_148","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「兩觀，天子之制也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_33_149","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「省，察也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_33_150","chapterId":"ch_work_han_thu_33","textTraditional":"〔五〕　師古曰：「燔音煩。」","sentenceOrder":150},
  {"id":"s_work_han_thu_33_151","chapterId":"ch_work_han_thu_33","textTraditional":"〔六〕　師古曰：「前是，謂此時之前也。見，顯示也，音胡電反。次下並同。」","sentenceOrder":151},
  {"id":"s_work_han_thu_33_152","chapterId":"ch_work_han_thu_33","textTraditional":"〔七〕　師古曰：「猥，積也，謂積敝也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_33_153","chapterId":"ch_work_han_thu_33","textTraditional":"〔八〕　師古曰：「揚，謂振揚張大也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_33_154","chapterId":"ch_work_han_thu_33","textTraditional":"〔九〕　服虔曰：「自恣意怒貌也。」師古曰：「睢音呼季反。」","sentenceOrder":154},
  {"id":"s_work_han_thu_33_155","chapterId":"ch_work_han_thu_33","textTraditional":"〔一０〕師古曰：「遠，離也，謂離正道者也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_33_156","chapterId":"ch_work_han_thu_33","textTraditional":"〔一一〕師古曰：「仄，古側字。」","sentenceOrder":156},
  {"id":"s_work_han_thu_33_157","chapterId":"ch_work_han_thu_33","textTraditional":"先是，淮南王安入朝，始與帝舅太尉武安侯田蚡有逆言。其後膠西于王、趙敬肅王、常山憲王皆數犯法，或至夷滅人家，藥殺二千石，而淮南、衡山王遂謀反。膠東、江都王皆知其謀，陰治兵弩，欲以應之。至元朔六年，乃發覺而伏辜。時田蚡已死，不及誅。上思仲舒前言，使仲舒弟子呂步舒持斧鉞治淮南獄，以春秋誼顓斷於外，不請。〔一〕既還奏事，上皆是之。","sentenceOrder":157},
  {"id":"s_work_han_thu_33_158","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「顓與專同。不請者，不奏待報。」","sentenceOrder":158},
  {"id":"s_work_han_thu_33_159","chapterId":"ch_work_han_thu_33","textTraditional":"太初元年十一月乙酉，未央宮柏梁臺災。先是，大風發其屋，夏侯始昌先言其災日。後有江充巫蠱衛太子事。","sentenceOrder":159},
  {"id":"s_work_han_thu_33_160","chapterId":"ch_work_han_thu_33","textTraditional":"征和二年春，涿郡鐵官鑄鐵，鐵銷，皆飛上去，此火為變使之然也。其三月，涿郡太守劉屈釐為丞相。後月，巫蠱事興，帝女諸邑公主、陽石公主、〔一〕丞相公孫賀、子太僕敬聲、平陽侯曹宗等皆下獄死。七月，使者江充掘蠱太子宮，太子與母皇后議，恐不能自明，乃殺充，舉兵與丞相劉屈釐戰，死者數萬人，太子敗走，至湖自殺。〔二〕明年，屈釐復坐祝謯要斬，〔三〕妻梟首也。成帝河平二年正月，沛郡鐵官鑄鐵，鐵不下，隆隆如雷聲，又如鼓音，工十三人驚走。音止，還視地，地陷數尺，鑪分為十，一鑪中銷鐵散如流星，皆上去，與征和二年同象。其夏，帝舅五人封列侯，號五侯。〔四〕元舅王鳳為大司馬大將軍秉政。後二年，丞相王商與鳳有隙，鳳譖之，免官，自殺。明年，京兆尹王章訟商忠直，言鳳顓權，鳳誣章以大逆罪，下獄死，妻子徙合浦。後許皇后坐巫蠱廢，而趙飛燕為皇后，妹為昭儀，賊害皇子，成帝遂亡嗣。皇后﹐昭儀皆伏辜。一曰，鐵飛屬金不從革。","sentenceOrder":160},
  {"id":"s_work_han_thu_33_161","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「諸，琅邪之縣也。公主所食曰邑，故謂之諸邑。陽石，北海之縣，字亦作羊。」","sentenceOrder":161},
  {"id":"s_work_han_thu_33_162","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「湖，縣名也。即今閺鄉、湖城二縣界。」","sentenceOrder":162},
  {"id":"s_work_han_thu_33_163","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「謯，古詛字也，音側據反。」","sentenceOrder":163},
  {"id":"s_work_han_thu_33_164","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「譚、商、立、根、逢時，凡五人。」","sentenceOrder":164},
  {"id":"s_work_han_thu_33_165","chapterId":"ch_work_han_thu_33","textTraditional":"昭帝元鳳元年，燕城南門災。劉向以為時燕王使邪臣通於漢，為讒賊，謀逆亂。南門者，通漢道也。天戒若曰，邪臣往來，為姦讒於漢，絕亡之道也。燕王不寤，卒伏其辜。","sentenceOrder":165},
  {"id":"s_work_han_thu_33_166","chapterId":"ch_work_han_thu_33","textTraditional":"元鳳四年五月丁丑，孝文廟正殿災。劉向以為孝文，太宗之君，與成周宣榭火同義。先是，皇后父車騎將軍上官安、安父左將軍桀謀為逆，大將軍霍光誅之。皇后以光外孫，年少不知，居位如故。光欲后有子，因上侍疾醫言，禁內後宮皆不得進，唯皇后顓寢。皇后年六歲而立，十三年而昭帝崩，遂絕繼嗣。光執朝政，猶周公之攝也。是歲正月，上加元服，〔一〕通詩、尚書，有明悊之性。光亡周公之德，秉政九年，久於周公，上既已冠而不歸政，將為國害。故正月加元服，五月而災見。古之廟皆在城中，孝文廟始出居外，天戒若曰，去貴而不正者。宣帝既立，光猶攝政，驕溢過制，至妻顯殺許皇后，光聞而不討，後遂誅滅。","sentenceOrder":166},
  {"id":"s_work_han_thu_33_167","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「謂冠也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_33_168","chapterId":"ch_work_han_thu_33","textTraditional":"宣帝甘露元年四月丙申，中山太上皇廟災。甲辰，孝文廟災。元帝初元三年四月乙未，孝武園白鶴館災。劉向以為先是前將軍蕭望之、光祿大夫周堪輔政，為佞臣石顯、許章等所譖，望之自殺，堪廢黜。明年，白鶴館災。園中五里馳逐走馬之館，〔一〕不當在山陵昭穆之地。天戒若曰，去貴近逸遊不正之臣，將害忠良。後章坐走馬上林下烽馳逐，免官。〔二〕","sentenceOrder":168},
  {"id":"s_work_han_thu_33_169","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「五里者，言其周迴五里。」","sentenceOrder":169},
  {"id":"s_work_han_thu_33_170","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　孟康曰：「夜於上林苑下舉火馳射也。烽或作｛逢火｝。」晉灼曰：「冠首曰烽。競走曰逐。」師古曰：「孟說是。」","sentenceOrder":170},
  {"id":"s_work_han_thu_33_171","chapterId":"ch_work_han_thu_33","textTraditional":"永光四年六月甲戌，孝宣杜陵園東闕南方災。劉向以為先是上復徵用周堪為光祿勳，及堪弟子張猛為太中大夫，石顯等復譖毀之，皆出外遷。是歲，上復徵堪領尚書，猛給事中，石顯等終欲害之。園陵小於朝廷，闕在司馬門中，內臣石顯之象也。孝宣，親而貴；闕，法令所從出也。天戒若曰，去法令，內臣親而貴者必為國害。後堪希得進見，因顯言事，事決顯口。堪病不能言。顯誣告張猛，自殺於公車。成帝即位，顯卒伏辜。","sentenceOrder":171},
  {"id":"s_work_han_thu_33_172","chapterId":"ch_work_han_thu_33","textTraditional":"成帝建始元年正月乙丑，皇考廟災。初，宣帝為昭帝後而立父廟，於禮不正。是時大將軍王鳳顓權擅朝，甚於田蚡，將害國家，故天於元年正月而見象也。其後寖盛，〔一〕五將世權，遂以亡道。〔二〕","sentenceOrder":172},
  {"id":"s_work_han_thu_33_173","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「寖，古浸字。浸，漸也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_33_174","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　孟康曰：「謂王五大司馬也。」師古曰：「謂鳳、音、商、根、莽也。」","sentenceOrder":174},
  {"id":"s_work_han_thu_33_175","chapterId":"ch_work_han_thu_33","textTraditional":"鴻嘉三年八月乙卯，孝景廟北闕災。十一月甲寅，許皇后廢。","sentenceOrder":175},
  {"id":"s_work_han_thu_33_176","chapterId":"ch_work_han_thu_33","textTraditional":"永始元年正月癸丑，大官凌室災。戊午，戾后園南闕災。是時，趙飛燕大幸，許后既廢，上將立之，故天見象於凌室，與惠帝四年同應。戾后，衛太子妾，遭巫蠱之禍，宣帝既立，追加尊號，於禮不正。又戾后起於微賤，與趙氏同〔應〕。天戒若曰，微賤亡德之人不可以奉宗廟，將絕祭祀，有凶惡之禍至。其六月丙寅，趙皇后遂立，姊妺驕妒，賊害皇子，卒皆受誅。","sentenceOrder":176},
  {"id":"s_work_han_thu_33_177","chapterId":"ch_work_han_thu_33","textTraditional":"永始四年四月癸未，長樂宮臨華殿及未央宮東司馬門災。六月甲午，孝文霸陵園東闕南方災。長樂宮，成帝母王太后之所居也。未央宮，帝所居也。霸陵，太宗盛德園也。是時，太后三弟相續秉政〔一〕，舉宗居位，充塞朝廷，兩宮親屬將害國家，〔二〕故天象仍見。〔三〕明年，成都侯商薨，弟曲陽侯根代為大司馬秉政。後四年，根乞骸骨，薦兄子新都侯莽自代，遂覆國焉。","sentenceOrder":177},
  {"id":"s_work_han_thu_33_178","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「謂陽平侯鳳、安陽侯音、成都侯商相代為大司馬。」","sentenceOrder":178},
  {"id":"s_work_han_thu_33_179","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「謂太后家王氏，皇后家趙氏，故云兩宮親屬。」","sentenceOrder":179},
  {"id":"s_work_han_thu_33_180","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「仍，重也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_33_181","chapterId":"ch_work_han_thu_33","textTraditional":"哀帝建平三年正月癸卯，桂宮鴻寧殿災，帝祖母傅太后之所居也。時，傅太后欲與成帝母等號齊尊，大臣孔光、師丹等執政，以為不可，太后皆免官爵，遂稱尊號。後三年，帝崩，傅氏誅滅。","sentenceOrder":181},
  {"id":"s_work_han_thu_33_182","chapterId":"ch_work_han_thu_33","textTraditional":"平帝元始五年七月己亥，高皇帝原廟殿門災盡。〔一〕高皇帝廟在長安城中，後以叔孫通譏復道，故復起原廟於渭北，非正也。是時平帝幼，成帝母王太后臨朝，委任王莽，將篡絕漢，墮高祖宗廟〔二〕，故天象見也。其冬，平帝崩。明年，莽居攝，因以篡國，後卒夷滅。","sentenceOrder":182},
  {"id":"s_work_han_thu_33_183","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「原廟，重廟也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_33_184","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「墮，毀也，音火規反。」","sentenceOrder":184},
  {"id":"s_work_han_thu_33_185","chapterId":"ch_work_han_thu_33","textTraditional":"傳曰：「治宮室，飾臺榭，〔一〕內淫亂，犯親戚，侮父兄，則稼穡不成。」","sentenceOrder":185},
  {"id":"s_work_han_thu_33_186","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「臺有室曰榭。」","sentenceOrder":186},
  {"id":"s_work_han_thu_33_187","chapterId":"ch_work_han_thu_33","textTraditional":"說曰：土，中央，生萬物者也。其於王者，為內事。宮室、夫婦、親屬，亦相生者也。古者天子諸侯，宮廟大小高卑有制，后夫人媵妾多少進退有度，九族親疏長幼有序。孔子曰：「禮，與其奢也，寧儉。」〔一〕故禹卑宮室，〔二〕文王刑于寡妻，〔三〕此聖人之所以昭教化也。〔四〕如此則土得其性矣。若乃奢淫驕慢，則土失其性。亡水旱之災而草木百穀不孰，是為稼穡不成。","sentenceOrder":187},
  {"id":"s_work_han_thu_33_188","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「論語載孔子之言也。若不得禮之中而失於奢，則不如儉。」","sentenceOrder":188},
  {"id":"s_work_han_thu_33_189","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「論語載孔子曰：『禹，吾無間然矣，卑宮室而盡力乎溝洫。』謂勤於治水而所居狹陋也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_33_190","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「大雅思齊之詩云：『刑于寡妻，至于兄弟，以御于家邦。』刑，法也。寡妻，謂正嫡也。御，治也。此美文王以禮法接待其妻，旁及兄弟宗族，又廣以政教治家邦。」","sentenceOrder":190},
  {"id":"s_work_han_thu_33_191","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「昭，明也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_33_192","chapterId":"ch_work_han_thu_33","textTraditional":"嚴公二十八年「冬，大（水）亡麥禾」。董仲舒以為夫人哀姜淫亂，〔一〕逆陰氣，故大水也。劉向以為水旱當書，不書水旱而曰「大亡麥禾」者，土氣不養，稼穡不成者也。是時，夫人淫於二叔，內外亡別，〔二〕又因凶飢，一年而三築臺，〔三〕故應是而稼穡不成，飾臺榭內淫亂之罰云。遂不改寤，四年而死，〔四〕禍流二世〔五〕，奢淫之患也。","sentenceOrder":192},
  {"id":"s_work_han_thu_33_193","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「哀姜，莊公夫人，齊女也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_33_194","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「二叔，謂莊公二弟仲慶父及叔牙。」","sentenceOrder":194},
  {"id":"s_work_han_thu_33_195","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「謂三十一年春築臺于郎，夏築臺于薛，秋築臺于秦也。郎、薛、秦，皆魯地也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_33_196","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「莊公三十二年薨，距大（水）無麥禾，凡四歲也。」","sentenceOrder":196},
  {"id":"s_work_han_thu_33_197","chapterId":"ch_work_han_thu_33","textTraditional":"〔五〕　師古曰：「謂子般及閔公，皆殺死。」","sentenceOrder":197},
  {"id":"s_work_han_thu_33_198","chapterId":"ch_work_han_thu_33","textTraditional":"傳曰：「好戰攻，輕百姓，飾城郭，侵邊境，則金不從革。」","sentenceOrder":198},
  {"id":"s_work_han_thu_33_199","chapterId":"ch_work_han_thu_33","textTraditional":"說曰：金，西方，萬物既成，殺氣之始也。故立秋而鷹隼擊，秋分而微霜降。其於王事，出軍行師，把旄杖鉞，誓士眾，抗威武，所以征畔逆止暴亂也。詩云：「有虔秉鉞，如火烈烈。」〔一〕又曰：「載戢干戈，載櫜弓矢。」〔二〕動靜應誼，「說以犯難，民忘其死。」〔三〕〔如此則〕金得其性矣。若乃貪欲恣睢，務立威勝，〔四〕不重民命，則金失其性。蓋工冶鑄金鐵，金鐵冰滯涸堅，不成者眾，〔五〕及為變怪，是為金不從革。","sentenceOrder":199},
  {"id":"s_work_han_thu_33_200","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「商頌長發之詩也。虔，固也。此美殷湯興師出征，固持其鉞，以誅有罪，威力猛盛，如火熾烈。」","sentenceOrder":200},
  {"id":"s_work_han_thu_33_201","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「周頌時邁之詩也。戢，聚也。櫜，韜也。言天下太平，兵不復用，故戢斂而韜臧也。」","sentenceOrder":201},
  {"id":"s_work_han_thu_33_202","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「言以和悅使人，（難）〔雖〕犯危難，不顧其生也。易兌卦彖曰『說以犯難，人忘其死』，故引之也。說讀曰悅。」","sentenceOrder":202},
  {"id":"s_work_han_thu_33_203","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「睢音呼季反。」","sentenceOrder":203},
  {"id":"s_work_han_thu_33_204","chapterId":"ch_work_han_thu_33","textTraditional":"〔五〕　師古曰：「涸讀與沍同。沍，（疑）〔凝〕也，音下故反。春秋左氏傳曰『固陰沍寒』。」","sentenceOrder":204},
  {"id":"s_work_han_thu_33_205","chapterId":"ch_work_han_thu_33","textTraditional":"左氏傳曰昭公八年「春，石言於晉」。晉平公問於師曠，〔一〕對曰；「石不能言，神或馮焉。作事不時，怨讟動於民，〔二〕則有非言之物而言。今宮室崇侈，民力彫盡，怨讟並興，莫信其性，〔三〕石之言不宜乎！」於是晉侯方築虒祁之宮。〔四〕叔向曰：「君子之言，信而有徵。」〔五〕劉歆以為金石同類，是為金不從革，失其性也。劉向以為石白色為主，屬白祥。","sentenceOrder":205},
  {"id":"s_work_han_thu_33_206","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「晉掌樂大夫。」","sentenceOrder":206},
  {"id":"s_work_han_thu_33_207","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「讟，痛怨之言也，音讀。」","sentenceOrder":207},
  {"id":"s_work_han_thu_33_208","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「信猶保也。性，生也。一說，信讀曰申，言不得申其性命也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_33_209","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「虒祁，地在絳西，臨汾水。虒音斯。」","sentenceOrder":209},
  {"id":"s_work_han_thu_33_210","chapterId":"ch_work_han_thu_33","textTraditional":"〔五〕　師古曰：「叔向，晉大夫羊舌肸也。向音許兩反，字亦作嚮，其音同。」","sentenceOrder":210},
  {"id":"s_work_han_thu_33_211","chapterId":"ch_work_han_thu_33","textTraditional":"成帝鴻嘉三年五月乙亥，天水冀南山大石鳴，〔一〕聲隆隆如雷，有頃止，聞平襄二百四十里，〔二〕野雞皆鳴。〔三〕石長丈三尺，廣厚略等，〔四〕旁著岸脅，去地二百餘丈，民俗名曰石鼓。石鼓鳴，有兵。是歲，廣漢鉗子謀攻牢，〔五〕篡死罪囚鄭躬等，盜庫兵，劫略吏民，衣繡衣，自號曰山君，黨與〈寖，中“彐改帚”〉廣。〔六〕明年冬，乃伏誅，自歸者三千餘人。後四年，尉氏樊並等謀反，殺陳留太守嚴普，自稱將軍，山陽亡徒蘇令等黨與數百人盜取庫兵，經歷郡國四十餘，皆踰年乃伏誅。是時起昌陵，作者數萬人，徙郡國吏民五千餘戶以奉陵邑。作治五年不成，乃罷昌陵，還徙家。〔七〕石鳴，與晉石言同應，師曠所謂「民力彫盡」，傳云「輕百姓」者也。虒祁離宮去絳都四十里，昌陵亦在郊野，皆與城郭同占。城郭屬金，宮室屬土，外內之別云。","sentenceOrder":211},
  {"id":"s_work_han_thu_33_212","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「天水之冀縣南山也。」","sentenceOrder":212},
  {"id":"s_work_han_thu_33_213","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　韋昭曰：「天水縣。」","sentenceOrder":213},
  {"id":"s_work_han_thu_33_214","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「雉也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_33_215","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「廣及厚皆如其長。」","sentenceOrder":215},
  {"id":"s_work_han_thu_33_216","chapterId":"ch_work_han_thu_33","textTraditional":"〔五〕　師古曰：「鉗子，謂鉗徒也。牢，繫重囚之處。」","sentenceOrder":216},
  {"id":"s_work_han_thu_33_217","chapterId":"ch_work_han_thu_33","textTraditional":"〔六〕　師古曰：「〈寖，中“彐改帚”〉，漸也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_33_218","chapterId":"ch_work_han_thu_33","textTraditional":"〔七〕　師古曰：「初徙人陪昌陵者，令皆還其本居。」","sentenceOrder":218},
  {"id":"s_work_han_thu_33_219","chapterId":"ch_work_han_thu_33","textTraditional":"傳曰：「簡宗廟，不禱祠，廢祭祀，逆天時，則水不潤下。」","sentenceOrder":219},
  {"id":"s_work_han_thu_33_220","chapterId":"ch_work_han_thu_33","textTraditional":"說曰：水，北方，終臧萬物者也。其於人道，命終而形臧，精神放越，聖人為之宗廟以收魂氣，春秋祭祀，以終孝道。王者即位，必郊祀天地，禱祈神祇，望秩山川，懷柔百神，亡不宗事。〔一〕慎其齊戒，致其嚴敬，鬼神歆饗，多獲福助。此聖王所以順事陰氣，和神人也。至發號施令，亦奉天時。十二月咸得其氣，則陰陽調而終始成。如此則水得其性矣。若乃不敬鬼神，（致）〔政〕令逆時，則水失其性。霧水暴出，百川逆溢，壞鄉邑，溺人民，及淫雨傷稼穡，是為水不潤下。京房易傳曰：「顓事有知，誅罰絕理，厥災水，其水也，雨殺人以隕霜，大風天黃。飢而不損茲謂泰，厥災水，水殺人。辟遏有德茲謂狂，〔二〕厥災水，水流殺人，已水則地生蟲。歸獄不解，茲謂追非，〔三〕厥水寒，殺人。追誅不解，茲謂不理，厥水五穀不收。大敗不解，茲謂皆陰。解，舍也，王者於大敗，誅首惡，赦其眾，不則皆函陰氣，〔四〕厥水流入國邑，隕霜殺（穀）〔叔草〕。」","sentenceOrder":220},
  {"id":"s_work_han_thu_33_221","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「懷，來也。柔，安也。謂招來而祭祀之，使其安也。宗，尊也。」","sentenceOrder":221},
  {"id":"s_work_han_thu_33_222","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　應劭曰：「辟，天子也。有德者雍遏不見用也。」師古曰：「遏音一曷反。」","sentenceOrder":222},
  {"id":"s_work_han_thu_33_223","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　李奇曰：「歸罪過於民，不罪己也。」張晏曰：「謂釋有罪之人而歸無辜者也。解，止也。追非，遂非也。」","sentenceOrder":223},
  {"id":"s_work_han_thu_33_224","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「函讀與含同。」","sentenceOrder":224},
  {"id":"s_work_han_thu_33_225","chapterId":"ch_work_han_thu_33","textTraditional":"桓公元年「秋，大水」。董仲舒、劉向以為桓弒兄隱公，民臣痛隱而賤桓。後宋督弒其君，〔一〕諸侯會，將討之，〔二〕桓受宋賂而歸，〔三〕又背宋。諸侯由是伐魯，仍交兵結讎，伏尸流血，百姓愈怨，〔四〕故十三年夏復大水。一曰，夫人驕淫，將弒君，陰氣盛，桓不寤，卒弒死。〔五〕劉歆以為桓易許田，不祀周公，〔六〕廢祭祀之罰也。","sentenceOrder":225},
  {"id":"s_work_han_thu_33_226","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「宋華父督為太宰，弒殤公，事在桓公二年。」","sentenceOrder":226},
  {"id":"s_work_han_thu_33_227","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「謂齊、陳、鄭也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_33_228","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「謂郜大鼎。」","sentenceOrder":228},
  {"id":"s_work_han_thu_33_229","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「桓會宋公者五，與宋公、燕人盟，已而背盟伐宋。宋公、燕人怨而求助，齊、衛助之。桓公懼，而會紀侯、鄭伯及四國之師大戰。」","sentenceOrder":229},
  {"id":"s_work_han_thu_33_230","chapterId":"ch_work_han_thu_33","textTraditional":"〔五〕　師古曰：「已解於上也。」","sentenceOrder":230},
  {"id":"s_work_han_thu_33_231","chapterId":"ch_work_han_thu_33","textTraditional":"〔六〕　師古曰：「許田，魯朝宿之邑，而有周公別（號）〔廟〕。桓既篡位，遂以許田與鄭，而取鄭之祊田，故云不祀周公。」","sentenceOrder":231},
  {"id":"s_work_han_thu_33_232","chapterId":"ch_work_han_thu_33","textTraditional":"嚴公七年「秋，大水，亡麥苗」。董仲舒、劉向以為嚴母文姜與兄齊襄公淫，共殺（威）〔桓〕公，嚴釋父讎，復取齊女，未入，先與之淫，一年再出，會於道逆亂，臣下賤之之應也。","sentenceOrder":232},
  {"id":"s_work_han_thu_33_233","chapterId":"ch_work_han_thu_33","textTraditional":"十一年「秋，宋大水」。董仲舒以為時魯、宋比年為乘丘、鄑之戰，〔一〕百姓愁怨，陰氣盛，故二國俱水。劉向以為時宋愍公驕慢，睹災不改，明年與其臣宋萬博戲，婦人在側，矜而罵萬，萬殺公之應。〔二〕","sentenceOrder":233},
  {"id":"s_work_han_thu_33_234","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「比年，頻年也。莊十年，公敗宋師于乘丘。十一年，公敗宋師于鄑。乘丘、鄑，魯地。鄑音子移反。」","sentenceOrder":234},
  {"id":"s_work_han_thu_33_235","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「萬，宋大夫也。戰敗獲于魯，復歸宋，又為大夫，與愍公博，婦人在側。萬曰：『甚矣，魯侯之淑，魯侯之美！天下諸侯宜為君者唯魯侯耳。』愍公矜此婦人，妒其言，顧曰：『此虜也。爾虜焉故魯侯之美惡乎至！』萬怒，搏愍公，絕其脰而死。事在莊十二年。」","sentenceOrder":235},
  {"id":"s_work_han_thu_33_236","chapterId":"ch_work_han_thu_33","textTraditional":"二十四年，「大水」。董仲舒以為夫人哀姜淫亂不婦，陰氣盛也。劉向以為哀姜初入，公使大夫宗婦見，用幣，〔一〕又淫於二叔，公弗能禁。臣下賤之，故是歲、明年仍大水。〔二〕劉歆以為先是嚴飾宗廟，刻桷丹楹，以夸夫人，〔三〕簡宗廟之罰也。〔四〕","sentenceOrder":236},
  {"id":"s_work_han_thu_33_237","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「宗婦，同姓之婦也。大夫妻及宗婦見夫人者，皆令執幣，是踰禮也。」","sentenceOrder":237},
  {"id":"s_work_han_thu_33_238","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「仍，頻也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_33_239","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　臣瓚曰：「桷，榱也。」韋昭曰：「楹，柱也。」師古曰：「莊公二十三年丹桓宮楹，二十四年刻桓宮桷。將迎夫人，故為盛飾。」","sentenceOrder":239},
  {"id":"s_work_han_thu_33_240","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「簡，慢也。」","sentenceOrder":240},
  {"id":"s_work_han_thu_33_241","chapterId":"ch_work_han_thu_33","textTraditional":"宣公十年「秋大水，飢」。董仲舒以為時比伐邾取邑，〔一〕亦見報復，兵讎連結，百姓愁怨。劉向以為宣公殺子赤而立，子赤，齊出也，〔二〕故懼，以濟西田賂齊。〔三〕邾子貜且亦齊出也，〔四〕而宣比與邾交兵。〔五〕臣下懼齊之威，創邾之禍，〔六〕皆賤公行而非其正也。","sentenceOrder":241},
  {"id":"s_work_han_thu_33_242","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「比，頻也。九年秋，取根牟。公羊傳曰：『根牟者何？邾婁之邑也。』十年，公孫歸父帥師伐邾取繹，故云比年也。」","sentenceOrder":242},
  {"id":"s_work_han_thu_33_243","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「赤母姜氏。赤死，姜氏大歸，齊市人皆哭，魯人謂之哀姜。」","sentenceOrder":243},
  {"id":"s_work_han_thu_33_244","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「宣既即位，與齊侯會于平州，以定其位。元年六月，齊人取濟西田，為立公故，以賂齊也。」","sentenceOrder":244},
  {"id":"s_work_han_thu_33_245","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「貜且，邾文公之子邾定公也。亦齊女所生。貜音俱碧反，又音钁。且音子余反。」","sentenceOrder":245},
  {"id":"s_work_han_thu_33_246","chapterId":"ch_work_han_thu_33","textTraditional":"〔五〕　師古曰：「比，頻也。」","sentenceOrder":246},
  {"id":"s_work_han_thu_33_247","chapterId":"ch_work_han_thu_33","textTraditional":"〔六〕　師古曰：「創，懲艾也，音初亮反。」","sentenceOrder":247},
  {"id":"s_work_han_thu_33_248","chapterId":"ch_work_han_thu_33","textTraditional":"成公五年「秋，大水」。董仲舒、劉向以為時成幼弱，政在大夫，前此一年再用師，〔一〕明年復城鄆以彊私家，〔二〕仲孫蔑、叔孫僑如顓會宋、晉，陰勝陽。〔三〕","sentenceOrder":248},
  {"id":"s_work_han_thu_33_249","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「成三年春，公會晉侯、宋公、衛侯、曹伯伐鄭，秋，叔孫僑如帥師圍棘，是也。」","sentenceOrder":249},
  {"id":"s_work_han_thu_33_250","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「四年城鄆。鄆，季氏邑，音運。」","sentenceOrder":250},
  {"id":"s_work_han_thu_33_251","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「仲孫蔑，孟獻子也。成五年春，仲孫蔑如宋。夏，叔孫僑如會晉荀首于穀。顓與專同，專者，不秉命于公。」","sentenceOrder":251},
  {"id":"s_work_han_thu_33_252","chapterId":"ch_work_han_thu_33","textTraditional":"襄公二十四年「秋，大水」。董仲舒以為先是一年齊伐晉，襄使大夫帥師救晉，〔一〕後又侵齊，〔二〕國小兵弱，數敵彊大，百姓愁怨，陰氣盛。劉向以為先是襄慢鄰國，是以邾伐其南，〔三〕齊伐其北，〔四〕莒伐其東，〔五〕百姓騷動，後又仍犯彊齊也。〔六〕大水，饑，穀不成，其災甚也。","sentenceOrder":252},
  {"id":"s_work_han_thu_33_253","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「襄二十三年秋，齊伐衛，遂伐晉。八月，叔孫豹帥師救晉，次于雍榆。」","sentenceOrder":253},
  {"id":"s_work_han_thu_33_254","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「二十四年，仲孫羯帥師侵齊。」","sentenceOrder":254},
  {"id":"s_work_han_thu_33_255","chapterId":"ch_work_han_thu_33","textTraditional":"〔三〕　師古曰：「十五年，邾人伐我南鄙是也。」","sentenceOrder":255},
  {"id":"s_work_han_thu_33_256","chapterId":"ch_work_han_thu_33","textTraditional":"〔四〕　師古曰：「十六年，齊人伐我北鄙是也。」","sentenceOrder":256},
  {"id":"s_work_han_thu_33_257","chapterId":"ch_work_han_thu_33","textTraditional":"〔五〕　師古曰：「十二年，莒人伐我東鄙是也。」","sentenceOrder":257},
  {"id":"s_work_han_thu_33_258","chapterId":"ch_work_han_thu_33","textTraditional":"〔六〕　師古曰：「十八年，公會晉侯、宋公、衛侯、鄭伯同圍齊。二十三年救晉，二十四年又侵齊，是重犯也。」","sentenceOrder":258},
  {"id":"s_work_han_thu_33_259","chapterId":"ch_work_han_thu_33","textTraditional":"高后三年夏，漢中、南郡大水，水出流四千餘家。四年秋，河南大水，伊、雒流千六百餘家，汝水流八百餘家。八年夏，漢中、南郡水復出，流六千餘家。南陽沔水流萬餘家。〔一〕是時女主獨治，諸呂相王。","sentenceOrder":259},
  {"id":"s_work_han_thu_33_260","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「沔，漢水之上也，音彌善反。」","sentenceOrder":260},
  {"id":"s_work_han_thu_33_261","chapterId":"ch_work_han_thu_33","textTraditional":"文帝後三年秋，大雨，晝夜不絕三十五日。藍田山水出，流九百餘家。（燕）〔漢水出〕，壞民室八千餘所，殺三百餘人。先是，趙人新垣平以望氣得幸，為上立渭陽五帝廟，欲出周鼎，以夏四月，郊見上帝。〔一〕歲餘懼誅，謀為逆，發覺，要斬，夷三族。是時，比再遣公主配單于，賂遺甚厚，〔二〕匈奴愈驕，侵犯北邊，殺略多至萬餘人，漢連發軍征討戍邊。","sentenceOrder":261},
  {"id":"s_work_han_thu_33_262","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「事並見郊祀志。」","sentenceOrder":262},
  {"id":"s_work_han_thu_33_263","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「比，頻也。高祖使劉敬奉宗室女翁主為冒頓單于閼氏。冒頓死，其子老上單于初立，文帝復遣宗人女為單于閼氏。」","sentenceOrder":263},
  {"id":"s_work_han_thu_33_264","chapterId":"ch_work_han_thu_33","textTraditional":"元帝永光五年夏及秋，大水。潁川、汝南、淮陽、廬江雨，壞鄉聚民舍，及水流殺人。先是一年有司奏罷郡國廟，是歲又定迭毀〔一〕，罷太上皇、孝惠帝寢廟，皆無復修，通儒以為違古制。刑臣石顯用事。〔二〕","sentenceOrder":264},
  {"id":"s_work_han_thu_33_265","chapterId":"ch_work_han_thu_33","textTraditional":"〔一〕　師古曰：「親盡則毀，故云迭毀。事在韋玄成傳。迭音大結反。」","sentenceOrder":265},
  {"id":"s_work_han_thu_33_266","chapterId":"ch_work_han_thu_33","textTraditional":"〔二〕　師古曰：「石顯宦者，故曰刑臣。」","sentenceOrder":266},
  {"id":"s_work_han_thu_33_267","chapterId":"ch_work_han_thu_33","textTraditional":"成帝建始三年夏，大水，三輔霖雨三十餘日，郡國十九雨，山谷水出，凡殺四千餘人，壞官寺民舍八萬三千餘所。元年，有司奏徙甘泉泰畤、河東后土于長安南北郊。二年，又罷雍五畤、郡國諸舊祀，凡六所。","sentenceOrder":267},
  {"id":"s_work_han_thu_33_268","chapterId":"ch_work_han_thu_33","textTraditional":"校勘記","sentenceOrder":268},
  {"id":"s_work_han_thu_33_269","chapterId":"ch_work_han_thu_33","textTraditional":"一三一六頁一０行　見（殛）〔誅〕而死。　景祐、殿本都作「誅」。朱一新說作「誅」是。","sentenceOrder":269},
  {"id":"s_work_han_thu_33_270","chapterId":"ch_work_han_thu_33","textTraditional":"一三一九頁　六行　（衡）〔衝〕牙（玭）〔蚍〕珠以納其間。「衡」，景祐、殿本都作「衝」。「玭」，景祐本作「蚍」。","sentenceOrder":270},
  {"id":"s_work_han_thu_33_271","chapterId":"ch_work_han_thu_33","textTraditional":"一三一九頁　八行　以為舒疾之（疾）〔節〕也。　景祐、殿、局本都作「節」。朱一新說作「節」是。","sentenceOrder":271},
  {"id":"s_work_han_thu_33_272","chapterId":"ch_work_han_thu_33","textTraditional":"一三二０頁　一行　則陰氣（協）〔脅〕木，　景祐、殿本都作「脅」。","sentenceOrder":272},
  {"id":"s_work_han_thu_33_273","chapterId":"ch_work_han_thu_33","textTraditional":"一三二二頁　九行　故致（太）〔大〕災。　景祐、殿本都作「大」。","sentenceOrder":273},
  {"id":"s_work_han_thu_33_274","chapterId":"ch_work_han_thu_33","textTraditional":"一三二三頁　一行　不勝（曰）〔四〕公子之徒，　景祐、殿本都作「四」，此誤。","sentenceOrder":274},
  {"id":"s_work_han_thu_33_275","chapterId":"ch_work_han_thu_33","textTraditional":"一三二三頁　四行　釐公二十年五月（己酉）〔乙巳〕，西宮災。　景祐、殿本都作「乙巳」，與春秋經同。","sentenceOrder":275},
  {"id":"s_work_han_thu_33_276","chapterId":"ch_work_han_thu_33","textTraditional":"一三二六頁　二行　（金）〔今〕之長頸缾也。　景祐、殿本都作「今」。朱一新說作「今」是。","sentenceOrder":276},
  {"id":"s_work_han_thu_33_277","chapterId":"ch_work_han_thu_33","textTraditional":"一三二六頁　八行　飭讀與（赤）〔敕〕同。　景祐、殿本都作「敕」。朱一新說作「敕」是。","sentenceOrder":277},
  {"id":"s_work_han_thu_33_278","chapterId":"ch_work_han_thu_33","textTraditional":"一三二六頁一一行　天（下）〔不〕復告，　景祐、殿本都作「不」。朱一新說作「不」是。","sentenceOrder":278},
  {"id":"s_work_han_thu_33_279","chapterId":"ch_work_han_thu_33","textTraditional":"一三二七頁　一行　云與楚（各）〔客〕盟，　景祐、殿、局本都作「客」。朱一新說作「客」是。","sentenceOrder":279},
  {"id":"s_work_han_thu_33_280","chapterId":"ch_work_han_thu_33","textTraditional":"一三二七頁一四行　妃以五（陳）〔成〕，　景祐、殿、局本都作「成」。","sentenceOrder":280},
  {"id":"s_work_han_thu_33_281","chapterId":"ch_work_han_thu_33","textTraditional":"一三二八頁　八行　公羊（傳）〔經〕。　景祐、殿本都作「經」。","sentenceOrder":281},
  {"id":"s_work_han_thu_33_282","chapterId":"ch_work_han_thu_33","textTraditional":"一三三二頁一三行　如吾燔遼〔東〕高廟乃可；　「東」字據景祐、殿本補。","sentenceOrder":282},
  {"id":"s_work_han_thu_33_283","chapterId":"ch_work_han_thu_33","textTraditional":"一三三七頁　二行　與趙氏同〔應〕。　景祐、殿本都有「應」字。","sentenceOrder":283},
  {"id":"s_work_han_thu_33_284","chapterId":"ch_work_han_thu_33","textTraditional":"一三三九頁　四行　大（水）亡麥禾。　景祐本無「水」字，春秋經亦無。注同。","sentenceOrder":284},
  {"id":"s_work_han_thu_33_285","chapterId":"ch_work_han_thu_33","textTraditional":"一三四０頁　一行　〔如此則〕金得其性矣。　殿本有「如此則」三字。王先謙說此脫。按景祐本亦無。","sentenceOrder":285},
  {"id":"s_work_han_thu_33_286","chapterId":"ch_work_han_thu_33","textTraditional":"一三四０頁　六行　（難）〔雖〕犯危難，　景祐、殿本都作「雖」。蘇輿說作「雖」是。","sentenceOrder":286},
  {"id":"s_work_han_thu_33_287","chapterId":"ch_work_han_thu_33","textTraditional":"一三四０頁　九行　沍，（疑）〔凝〕也。　景祐、殿本都作「凝」。朱一新說作「凝」是。","sentenceOrder":287},
  {"id":"s_work_han_thu_33_288","chapterId":"ch_work_han_thu_33","textTraditional":"一三四二頁　七行　（致）〔政〕令逆時，　景祐本作「政」。朱一新說作「政」是。","sentenceOrder":288},
  {"id":"s_work_han_thu_33_289","chapterId":"ch_work_han_thu_33","textTraditional":"一三四二頁一二行　隕霜殺（穀）〔叔草〕。　宋祁說「穀」當作「菽」。按景祐本作「叔草」。楊樹達說中之下卷亦云「隕霜殺叔草」。","sentenceOrder":289},
  {"id":"s_work_han_thu_33_290","chapterId":"ch_work_han_thu_33","textTraditional":"一三四三頁一三行　而有周公別（號）〔廟〕。　景祐、殿本都作「廟」。朱一新說作「廟」是。","sentenceOrder":290},
  {"id":"s_work_han_thu_33_291","chapterId":"ch_work_han_thu_33","textTraditional":"一三四三頁一四行　共殺（威）〔桓〕公，　景祐、殿本都作「桓」。錢大昭說作「桓」是。","sentenceOrder":291},
  {"id":"s_work_han_thu_33_292","chapterId":"ch_work_han_thu_33","textTraditional":"一三四六頁一三行　（燕）〔漢水出〕，壞民室八千餘所，　王念孫據漢紀孝文紀改。","sentenceOrder":292},
  {"id":"s_work_han_thu_34_1","chapterId":"ch_work_han_thu_34","textTraditional":"經曰：「羞用五事。五事：一曰貌，二曰言，三曰視，四曰聽，五曰思。〔一〕貌曰恭，言曰從，視曰明，聽曰聰，思曰睿。〔二〕恭作肅，從作艾，〔三〕明作悊，聰作謀，〔四〕睿作聖。〔五〕休徵：〔六〕曰肅，時雨若；〔七〕艾，時陽若；〔八〕悊，時奧若；〔九〕謀，時寒若；聖，時風若。〔一０〕咎徵：〔一一〕曰狂，恆雨若；僭，恆陽若；〔一二〕舒，恆奧若；急，恆寒若；霿，恆風若。」〔一三〕","sentenceOrder":1},
  {"id":"s_work_han_thu_34_2","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　應劭曰：「思，思慮。」","sentenceOrder":2},
  {"id":"s_work_han_thu_34_3","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　應劭曰：「〈睿，中“目改口”〉，通也，古文作睿。」","sentenceOrder":3},
  {"id":"s_work_han_thu_34_4","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「艾讀曰乂。乂，治也。其下亦同。」","sentenceOrder":4},
  {"id":"s_work_han_thu_34_5","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　應劭曰：「上聰則下謀，故聰為謀也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_34_6","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　張晏曰：「睿通達以至於聖。」","sentenceOrder":6},
  {"id":"s_work_han_thu_34_7","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　孟康曰：「善行之驗也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_34_8","chapterId":"ch_work_han_thu_34","textTraditional":"〔七〕　應劭曰：「居上而敬，則雨順之。」","sentenceOrder":8},
  {"id":"s_work_han_thu_34_9","chapterId":"ch_work_han_thu_34","textTraditional":"〔八〕　應劭曰：「君政治，則陽順之。」","sentenceOrder":9},
  {"id":"s_work_han_thu_34_10","chapterId":"ch_work_han_thu_34","textTraditional":"〔九〕　應劭曰：「悊，明也。」師古曰：「奧讀曰燠。燠，溫也，音於六反。其下亦同。」","sentenceOrder":10},
  {"id":"s_work_han_thu_34_11","chapterId":"ch_work_han_thu_34","textTraditional":"〔一０〕師古曰：「凡言時者，皆謂行得其道，則寒暑風雨以時應而順之。」","sentenceOrder":11},
  {"id":"s_work_han_thu_34_12","chapterId":"ch_work_han_thu_34","textTraditional":"〔一一〕師古曰：「言惡行之驗。」","sentenceOrder":12},
  {"id":"s_work_han_thu_34_13","chapterId":"ch_work_han_thu_34","textTraditional":"〔一二〕應劭曰：「僭，僭差。」","sentenceOrder":13},
  {"id":"s_work_han_thu_34_14","chapterId":"ch_work_han_thu_34","textTraditional":"〔一三〕服虔曰：「霿音人傋霿。」應劭曰：「人君瞉霿鄙吝，則風不順之也。」師古曰：「凡言恆者，謂所行者失道，則寒暑風雨不時，而恆久為災也。霿音莫豆反。傋〈嗀，中“口改月”〉，並音構，又音寇。」","sentenceOrder":14},
  {"id":"s_work_han_thu_34_15","chapterId":"ch_work_han_thu_34","textTraditional":"傳曰：「貌之不恭，是謂不肅，厥咎狂，厥罰恆雨，厥極惡。時則有服妖，時則有龜孽，〔一〕時則有雞禍，〔二〕時則有下體生上之痾，〔三〕時則有青眚青祥。〔四〕唯金沴（水）〔木〕。」〔五〕","sentenceOrder":15},
  {"id":"s_work_han_thu_34_16","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「孽音魚列反。其下並同。」","sentenceOrder":16},
  {"id":"s_work_han_thu_34_17","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「禍與禍同。」","sentenceOrder":17},
  {"id":"s_work_han_thu_34_18","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　韋昭曰：「若牛之足反出背上，下欲伐上之禍也。」師古曰：「痾音阿。」","sentenceOrder":18},
  {"id":"s_work_han_thu_34_19","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　李奇曰：「內曰眚，外曰祥。」","sentenceOrder":19},
  {"id":"s_work_han_thu_34_20","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　服虔曰：「沴，害也。」如淳曰：「沴音拂戾之戾，義亦同。」","sentenceOrder":20},
  {"id":"s_work_han_thu_34_21","chapterId":"ch_work_han_thu_34","textTraditional":"說曰：凡草物之類謂之妖。妖猶夭胎，言尚微。〔一〕蟲豸之類謂之孽。〔二〕孽則牙孽矣。及六畜，謂之禍，言其著也。及人，謂之痾。痾，病貌，言浸深也。〔三〕甚則異物生，謂之眚；自外來，謂之祥。祥猶禎也。氣相傷，謂之沴。沴猶臨蒞，不和意也。每一事云「時則」以絕之，言非必俱至，或有或亡，或在前或在後也。","sentenceOrder":21},
  {"id":"s_work_han_thu_34_22","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「夭音烏老反。」","sentenceOrder":22},
  {"id":"s_work_han_thu_34_23","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「有足謂之蟲，無足謂之豸。」","sentenceOrder":23},
  {"id":"s_work_han_thu_34_24","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「浸，漸也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_34_25","chapterId":"ch_work_han_thu_34","textTraditional":"孝武時，夏侯始昌通五經，善推五行傳，以傳族子夏侯勝，下及許商，皆以教所賢弟子。其傳與劉向同，唯劉歆傳獨異。貌之不恭，是謂不肅。肅，敬也。內曰恭，外曰敬。人君行己，體貌不恭，怠慢驕蹇，則不能敬萬事，失在狂易，故其咎狂也。〔一〕上嫚下暴，則陰氣勝，故其罰常雨也。水傷百穀，衣食不足，則姦軌並作，故其極惡也。一曰，民多被刑，或形貌醜惡，亦是也。風俗狂慢，變節易度，則為剽輕奇怪之服，〔二〕故有服妖。水類動，故有龜孽。〔三〕於易，巽為雞，雞有冠距文武之貌。不為威儀，貌氣毀，故有雞禍。一曰，水歲雞多死及為怪，亦是也。上失威儀，則下有彊臣害君上者，故有下體生於上之痾。木色青，故有青眚青祥。凡貌傷者病木氣，木氣病則金沴之，衝氣相通也。於易，震在東方，為春為木也；兌在西方，為秋為金也；離在南方，為夏為火也；坎在北方，為冬為水也。春與秋，日夜分，寒暑平，是以金木之氣易以相變，故貌傷則致秋陰常雨，言傷則致春陽常旱也。至於冬夏，日夜相反，寒暑殊絕，水火之氣不得相併，故視傷常奧，聽傷常寒者，其氣然也。逆之，其極曰惡；順之，其福曰攸好德。〔四〕劉歆貌傳曰有鱗蟲之孽，羊禍，鼻痾。說以為於天文東方辰為龍星，故為鱗蟲；於易兌為羊，木為金所病，故致羊禍，與常雨同應。此說非是。春與秋，氣陰陽相敵，木病金盛，故能相并，唯此一事耳。禍與妖痾祥眚同類，不得獨異。","sentenceOrder":25},
  {"id":"s_work_han_thu_34_26","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「狂易，謂狂而易其常性。」","sentenceOrder":26},
  {"id":"s_work_han_thu_34_27","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「剽音匹妙反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_34_28","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　如淳曰：「河魚大上，以為魚孽之比。」","sentenceOrder":28},
  {"id":"s_work_han_thu_34_29","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　孟康曰：「政不順則致妖，順則致福也。」師古曰：「攸，所也，所好者德也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_34_30","chapterId":"ch_work_han_thu_34","textTraditional":"史記〔一〕成公十六年，公會諸侯于周，單襄公見晉厲公視遠步高，〔二〕告公曰：「晉將有亂。」魯侯曰：「敢問天道也？抑人故也？」〔三〕對曰：「吾非瞽史，〔四〕焉知天道？吾見晉君之容，殆必禍者也。夫君子目以定體，足以從之，〔五〕是以觀其容而知其心矣。目以處誼，足以步目。〔六〕晉侯視遠而足高，目不在體，而足不步目，其心必異矣。目體不相從，何以能久？夫合諸侯，民之大事也，於是虖觀存亡。故國將無咎，其君在會，步言視聽必皆無謫，則可以知德矣。〔七〕視遠，曰絕其誼；足高，曰棄其德；言爽，曰反其信；〔八〕聽淫，曰離其名。〔九〕夫目以處誼，足以踐德〔一０〕，口以庇信，〔一一〕耳以聽名者也，故不可不慎。偏喪有咎；〔一二〕既喪，則國從之。〔一三〕晉侯爽二，吾是以云。」〔一四〕後二年，晉人殺厲公。凡此屬，皆貌不恭之咎云。","sentenceOrder":30},
  {"id":"s_work_han_thu_34_31","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「此志凡稱史記者，皆謂司馬遷所撰也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_34_32","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「單襄公，周卿士單子朝也。晉厲公，景公之子也，名州蒲。單音善。」","sentenceOrder":32},
  {"id":"s_work_han_thu_34_33","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「抑，發語辭也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_34_34","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「瞽，樂太師。史，太史。」","sentenceOrder":34},
  {"id":"s_work_han_thu_34_35","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「體定則目安，足之進退皆無違也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_34_36","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　師古曰：「視瞻得其宜，行步中其節也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_34_37","chapterId":"ch_work_han_thu_34","textTraditional":"〔七〕　師古曰：「謫，責也。無謫，謂得其義理無可咎責也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_34_38","chapterId":"ch_work_han_thu_34","textTraditional":"〔八〕　師古曰：「爽，差也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_34_39","chapterId":"ch_work_han_thu_34","textTraditional":"〔九〕　師古曰：「淫，邪也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_34_40","chapterId":"ch_work_han_thu_34","textTraditional":"〔一０〕師古曰：「踐，履也，所履皆德行也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_34_41","chapterId":"ch_work_han_thu_34","textTraditional":"〔一一〕師古曰：「庇，覆也。言行相覆則為信矣。」","sentenceOrder":41},
  {"id":"s_work_han_thu_34_42","chapterId":"ch_work_han_thu_34","textTraditional":"〔一二〕師古曰：「苟喪其一，則有咎。」","sentenceOrder":42},
  {"id":"s_work_han_thu_34_43","chapterId":"ch_work_han_thu_34","textTraditional":"〔一三〕師古曰：「既，盡也。若盡喪之，則國亦亡。」","sentenceOrder":43},
  {"id":"s_work_han_thu_34_44","chapterId":"ch_work_han_thu_34","textTraditional":"〔一四〕張晏曰：「視遠一也，步高二也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_34_45","chapterId":"ch_work_han_thu_34","textTraditional":"左氏（使）〔傳〕桓公十三年，楚屈瑕伐羅，鬥伯比送之，〔一〕還謂其馭曰：「莫囂必敗，〔二〕舉止高，心不固矣。」〔三〕遽見楚子以告。〔四〕楚子使賴人追之，弗及。莫囂行，遂無次，且不設備。〔五〕及羅，羅人軍之，大敗。莫囂縊死。","sentenceOrder":45},
  {"id":"s_work_han_thu_34_46","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「屈瑕即莫囂也。鬥伯比，楚大夫。羅，國名，在南郡枝江西。」","sentenceOrder":46},
  {"id":"s_work_han_thu_34_47","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「莫囂，楚官名也。字或作敖，其音同。」","sentenceOrder":47},
  {"id":"s_work_han_thu_34_48","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「止，足也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_34_49","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「遽，速也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_34_50","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「無次，不為次列也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_34_51","chapterId":"ch_work_han_thu_34","textTraditional":"釐公十一年，周使內史過賜晉惠公命，〔一〕受玉，惰。〔二〕過歸告王曰：「晉侯其無後乎！王賜之命，而惰於受瑞，先自棄也已，其何繼之有！禮，國之幹也；敬，禮之輿也。〔三〕不敬則禮不行，禮不行則上下昏，何以長世！」二十一年，晉惠公卒，子懷公立，晉人殺之，更立文公。","sentenceOrder":51},
  {"id":"s_work_han_thu_34_52","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「內史過，周大夫。晉惠公，夷吾也。諸侯即位，天子則賜命圭以為瑞。」","sentenceOrder":52},
  {"id":"s_work_han_thu_34_53","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「不敬其事也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_34_54","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「無禮，則國不立，故謂之幹。無敬，則禮不行，故比之於輿。」","sentenceOrder":54},
  {"id":"s_work_han_thu_34_55","chapterId":"ch_work_han_thu_34","textTraditional":"成公十三年，晉侯使郤錡乞師于魯，將事不敬。〔一〕孟獻子曰：「郤氏其亡乎！〔二〕禮，身之幹也；敬，身之基也。〔三〕郤子無基。且先君之嗣卿也，受命以求師，將社稷是衛，而惰棄君命也，不亡何為！」十七年，郤氏亡。","sentenceOrder":55},
  {"id":"s_work_han_thu_34_56","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「郤錡，晉大夫駒伯也。乞師，欲以伐秦也。將事，致其君命也。錡音牛爾反。」","sentenceOrder":56},
  {"id":"s_work_han_thu_34_57","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「孟獻子，仲孫蔑。」","sentenceOrder":57},
  {"id":"s_work_han_thu_34_58","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「無禮，則身不立；不敬，則身不安也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_34_59","chapterId":"ch_work_han_thu_34","textTraditional":"成公十三年，諸侯朝王，遂從劉康公伐秦。成肅公受（賑）〔脤〕于社，不敬。〔一〕劉子曰：「吾聞之曰，民受天地之中以生，所謂命也。〔二〕是以有禮義動作威儀之則，以定命也。能者養以之福，不能者敗以取禍，〔三〕是故君子勤禮，小人盡力。勤禮莫如致敬，盡力莫如惇篤。敬在養神，篤在守業。國之大事，在祀與戎。祀有執膰，戎有受賑，〔四〕神之大節也。〔五〕今成子惰，棄其命矣，其不反虖！」五月，成肅公卒。","sentenceOrder":59},
  {"id":"s_work_han_thu_34_60","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　服虔曰：「脤，祭社之肉也，盛以〈唇，中“口改〈虫虫〉”〉器，故謂之脤。」師古曰：「劉康公、成肅公，皆周大夫也。脤讀與〈唇，中“口改〈虫虫〉”〉同。以出師而祭社謂之宜。脤者，即宜社之肉也。〈唇，中“口改〈虫虫〉”〉，大蛤也，音上忍反。」","sentenceOrder":60},
  {"id":"s_work_han_thu_34_61","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「劉子即康公也。中謂中和之氣。」","sentenceOrder":61},
  {"id":"s_work_han_thu_34_62","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「之，往也。能養生者，則定禮義威儀，自致於福；不能者，則喪之以取禍亂。」","sentenceOrder":62},
  {"id":"s_work_han_thu_34_63","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　應劭曰：「膰，祭肉也。」師古曰：「膰音扶元反。」","sentenceOrder":63},
  {"id":"s_work_han_thu_34_64","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「交神之節。」","sentenceOrder":64},
  {"id":"s_work_han_thu_34_65","chapterId":"ch_work_han_thu_34","textTraditional":"成公十四年，衛定公享苦成叔，甯惠子相。〔一〕苦成叔敖〔二〕，甯子曰：「苦成家其亡虖！古之為享食也，以觀威儀省禍福也。〔三〕故詩曰：『兕觥其觩，旨酒思柔，匪儌匪傲，萬福來求。』今夫子傲，取禍之道也。」後三年，苦成家亡。〔五〕","sentenceOrder":65},
  {"id":"s_work_han_thu_34_66","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「定公名臧。苦成叔，晉大夫郤犨也。晉使卻犨如衛，故定公享之。惠子，衛大夫甯殖也。相謂贊相其禮。」","sentenceOrder":66},
  {"id":"s_work_han_thu_34_67","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「敖讀曰傲。其下並同。」","sentenceOrder":67},
  {"id":"s_work_han_thu_34_68","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「食讀曰飤。」","sentenceOrder":68},
  {"id":"s_work_han_thu_34_69","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　張晏曰：「觥，罰爵也。飲酒和柔，無失禮可罰，罰爵徒觩然而已。」應劭曰：「言在位者不儌訐不倨傲也。」師古曰：「小雅桑扈之詩也。儌謂儌倖也。萬福，言其多也。謂飲酒者不儌倖，不傲慢，則福祿就而求之也。觩音虯。儌音工堯反。」","sentenceOrder":69},
  {"id":"s_work_han_thu_34_70","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「十七年，晉攻郤氏，長魚矯以戈殺郤錡、郤犨、郤至，而滅其家。」","sentenceOrder":70},
  {"id":"s_work_han_thu_34_71","chapterId":"ch_work_han_thu_34","textTraditional":"襄公七年，衛孫文子聘于魯，君登亦登。〔一〕叔孫穆子相〔二〕，趨進曰：「諸侯之會，寡君未嘗後衛君，今吾子不後寡君，寡君未知所過，吾子其少安！」〔三〕孫子亡辭，亦亡悛容。〔四〕穆子曰：「孫子必亡。為臣而君，過而不悛，亡之本也。」十四年，孫子逐其君而外叛。〔五〕","sentenceOrder":71},
  {"id":"s_work_han_thu_34_72","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「文子，衛大夫孫林父也。禮之登階，臣後君一等。」","sentenceOrder":72},
  {"id":"s_work_han_thu_34_73","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「穆子，叔孫豹。」","sentenceOrder":73},
  {"id":"s_work_han_thu_34_74","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「安，徐也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_34_75","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「悛，改也，音千全反。」","sentenceOrder":75},
  {"id":"s_work_han_thu_34_76","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「逐其君，謂衛獻公出奔齊也。外叛，謂以戚叛之。」","sentenceOrder":76},
  {"id":"s_work_han_thu_34_77","chapterId":"ch_work_han_thu_34","textTraditional":"襄公二十八年，蔡景侯歸自晉，入于鄭。〔一〕鄭伯享之，不敬。子產曰：「蔡君其不免虖！〔二〕日其過此也，君使子展往勞于東門，而敖。〔三〕吾曰：『猶將更之。』〔四〕今還，受享而惰，乃其心也。〔五〕君小國，事大國，〔六〕而惰敖以為己心，將得死虖？君若不免，必由其子。淫而不父，〔七〕如是者必有子禍。」三十年，為世子般所殺。〔八〕","sentenceOrder":77},
  {"id":"s_work_han_thu_34_78","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「景侯名固，文侯之子也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_34_79","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「言不免於禍。」","sentenceOrder":79},
  {"id":"s_work_han_thu_34_80","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「日謂往日，始適晉之時也。子展，鄭大夫公孫舍之。」","sentenceOrder":80},
  {"id":"s_work_han_thu_34_81","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「更，改也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_34_82","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「言心之所常行也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_34_83","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　師古曰：「言身為小國之君，而事於大國。」","sentenceOrder":83},
  {"id":"s_work_han_thu_34_84","chapterId":"ch_work_han_thu_34","textTraditional":"〔七〕　師古曰：「通太子之妻。」","sentenceOrder":84},
  {"id":"s_work_han_thu_34_85","chapterId":"ch_work_han_thu_34","textTraditional":"〔八〕　師古曰：「般讀與班同。」","sentenceOrder":85},
  {"id":"s_work_han_thu_34_86","chapterId":"ch_work_han_thu_34","textTraditional":"襄公三十一年，公薨。季武子將立公子裯，〔一〕穆叔曰：「是人也，居喪而不哀，在慼而有嘉容，是謂不度。不度之人，鮮不為患，〔二〕若果立，必為季氏憂。」武子弗聽，卒立之。比及葬，三易衰，衰衽如故衰。〔三〕是為昭公。立二十五年，聽讒攻季氏。兵敗，出奔，死于外。〔四〕","sentenceOrder":86},
  {"id":"s_work_han_thu_34_87","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「裯，襄公之子，齊歸所生。裯音直留反。」","sentenceOrder":87},
  {"id":"s_work_han_thu_34_88","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「穆叔，即叔孫穆子也。不度，不遵禮度也。鮮，少也，音先淺反。」","sentenceOrder":88},
  {"id":"s_work_han_thu_34_89","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「衣前曰衽。言游戲無已也。比音必寐反。衰音千回反。衽音人禁反。」","sentenceOrder":89},
  {"id":"s_work_han_thu_34_90","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「謂薨于乾侯。」","sentenceOrder":90},
  {"id":"s_work_han_thu_34_91","chapterId":"ch_work_han_thu_34","textTraditional":"襄公三十一年，衛北宮文子見楚令尹圍之儀，〔一〕言於衛侯曰：「令尹似君矣，將有它志；〔二〕雖獲其志，弗能終也。」公曰：「子何以知之？」對曰：「詩云『敬慎威儀，惟民之則』，令尹無威儀，民無則焉。民所不則，以在民上，不可以終。〔四〕","sentenceOrder":91},
  {"id":"s_work_han_thu_34_92","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「北宮文子，衛大夫也，名佗。令尹圍即公子圍，楚恭王之子也，時為令尹。文子從衛侯在楚，故見之。」","sentenceOrder":92},
  {"id":"s_work_han_thu_34_93","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「謂有為君之心，言語視瞻非其常。」","sentenceOrder":93},
  {"id":"s_work_han_thu_34_94","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「大雅抑之詩也。則，法也。言君能慎其威儀，乃臣下所法效之。」","sentenceOrder":94},
  {"id":"s_work_han_thu_34_95","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「遂以殺君篡國，而取敗於乾谿也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_34_96","chapterId":"ch_work_han_thu_34","textTraditional":"昭公十一年夏，周單子會於戚，〔一〕視下言徐。〔二〕晉叔向曰：「單子其死虖！〔三〕朝有著定，〔四〕會有表，〔五〕衣有襘，帶有結。〔六〕會朝之言必聞于表著之位，所以昭事序也；〔七〕視不過結襘之中，所以道容貌也。〔八〕言以命之，容貌以明之，失則有闕。今單子為王官伯，〔九〕而命事於會，視不登帶，言不過步，貌不道容而言不昭矣。不道不恭，不昭不從，無守氣矣。」〔一０〕十二月，單成公卒。","sentenceOrder":96},
  {"id":"s_work_han_thu_34_97","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「單子，周大夫單成公也。戚，衛地。」","sentenceOrder":97},
  {"id":"s_work_han_thu_34_98","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　應劭曰：「視下，視不登帶。言徐，不聞於表著。」","sentenceOrder":98},
  {"id":"s_work_han_thu_34_99","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「叔向，晉大夫羊舌肸也。向音許兩反。」","sentenceOrder":99},
  {"id":"s_work_han_thu_34_100","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「朝內列位有定處，所謂表著者也。著音直庶反，又音除。」","sentenceOrder":100},
  {"id":"s_work_han_thu_34_101","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「會於野，設表以為位。」","sentenceOrder":101},
  {"id":"s_work_han_thu_34_102","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　師古曰：「襘，領之交會也。結，紳，紳帶之結也。襘音工外反。」","sentenceOrder":102},
  {"id":"s_work_han_thu_34_103","chapterId":"ch_work_han_thu_34","textTraditional":"〔七〕　師古曰：「昭，明也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_34_104","chapterId":"ch_work_han_thu_34","textTraditional":"〔八〕　師古曰：「道讀曰導。其下並同。」","sentenceOrder":104},
  {"id":"s_work_han_thu_34_105","chapterId":"ch_work_han_thu_34","textTraditional":"〔九〕　師古曰：「伯，長也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_34_106","chapterId":"ch_work_han_thu_34","textTraditional":"〔一０〕師古曰：「貌正曰恭，言正曰從。」","sentenceOrder":106},
  {"id":"s_work_han_thu_34_107","chapterId":"ch_work_han_thu_34","textTraditional":"昭公二十一年三月，葬蔡平公，蔡太子朱失位，位在卑。〔一〕魯大夫送葬者歸告昭子。〔二〕昭子歎曰：「蔡其亡虖！若不亡，是君也必不終。詩曰『不解於位，民之攸塈。』〔三〕今始即位而適卑，身將從之。」十月，蔡侯朱出奔楚。","sentenceOrder":107},
  {"id":"s_work_han_thu_34_108","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「不在正嫡之位，而以長幼序之。」","sentenceOrder":108},
  {"id":"s_work_han_thu_34_109","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「昭子，叔孫婼。」","sentenceOrder":109},
  {"id":"s_work_han_thu_34_110","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「大雅假樂之詩也。塈，息也。言在上者能率位不怠，則其臣下恃以安息也。解讀曰懈。塈音許既反。」","sentenceOrder":110},
  {"id":"s_work_han_thu_34_111","chapterId":"ch_work_han_thu_34","textTraditional":"晉魏舒合諸侯之大夫于翟泉，〔一〕將以城成周。魏子蒞政〔二〕，衛彪傒曰：「將建天子，而易位以令，非誼也。〔三〕大事奸誼，必有大咎。〔四〕晉不失諸侯，魏子其不免虖！」是行也，魏獻子屬役於韓簡子，〔五〕而田於大陸，焚焉而死。〔六〕","sentenceOrder":111},
  {"id":"s_work_han_thu_34_112","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　應劭曰：「水名，今洛陽是也。」師古曰：「魏舒，晉卿魏獻子也。事在定公元年。志不書者，蓋闕文。」","sentenceOrder":112},
  {"id":"s_work_han_thu_34_113","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「謂代天子大夫為政，以臨其事。」","sentenceOrder":113},
  {"id":"s_work_han_thu_34_114","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「傒，衛大夫。建天子，謂立天子之居也。傒音奚。」","sentenceOrder":114},
  {"id":"s_work_han_thu_34_115","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「奸，犯也，音干。」","sentenceOrder":115},
  {"id":"s_work_han_thu_34_116","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「簡子，亦晉卿韓不信。以城周之功役委簡子也。屬音之欲反。」","sentenceOrder":116},
  {"id":"s_work_han_thu_34_117","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　師古曰：「高平曰陸。因放火田獵而見燒殺也。說者或以為大陸即鉅鹿北大陸澤也。據會於狄泉，則其所田處固當在近，非大陸澤也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_34_118","chapterId":"ch_work_han_thu_34","textTraditional":"定公十五年，邾隱公朝於魯，執玉高，其容仰。公受玉卑，其容俯。〔一〕子贛觀焉，〔二〕曰：「以禮觀之，二君者皆有死亡焉。夫禮，死生存亡之體也。將左右周旋，進退俯仰，於是虖取之；朝祀喪戎，於是虖觀之。今正月相朝，而皆不度，心已亡矣。〔三〕嘉事不體，何以能久？〔四〕高仰，驕也；卑俯，替也。〔五〕驕近亂，替近疾。君為主，其先亡虖！」〔六〕","sentenceOrder":118},
  {"id":"s_work_han_thu_34_119","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「隱公，邾子益也。玉，謂朝者之贄。」","sentenceOrder":119},
  {"id":"s_work_han_thu_34_120","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「子贛，孔子弟子端木賜也。贛音貢。」","sentenceOrder":120},
  {"id":"s_work_han_thu_34_121","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「不度，不合法度。」","sentenceOrder":121},
  {"id":"s_work_han_thu_34_122","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「嘉事，嘉禮之事，謂朝祀也。不體，不得身體之節。」","sentenceOrder":122},
  {"id":"s_work_han_thu_34_123","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「替，廢惰也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_34_124","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　師古曰：「是年五月，定公薨。哀公七年秋，伐邾，以邾子益來也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_34_125","chapterId":"ch_work_han_thu_34","textTraditional":"庶徵之恆雨，劉歆以為春秋大雨也，劉向以為大水。","sentenceOrder":125},
  {"id":"s_work_han_thu_34_126","chapterId":"ch_work_han_thu_34","textTraditional":"隱公九年「三月癸酉，大雨，震電；庚辰，大雨雪」。〔一〕大雨，雨水也；〔二〕震，雷也。劉歆以為三月癸酉，於曆數春分後一日，始震電之時也，當雨，而不當大雨。大雨，常雨之罰也。於始震電八日之間而大雨雪，常寒之罰也。劉向以為周三月，今正月也，當雨水，雪雜雨，雷電未可以發也。既已發也，則雪不當復降。皆失節，故謂之異。於易，雷以二月出，其卦日豫，〔三〕言萬物隨雷出地，皆逸豫也。以八月入，其卦曰歸妹，〔四〕言雷復歸。入地則孕毓根核，保藏蟄蟲，〔五〕避盛陰之害；出地則養長華實，發揚隱伏，宣盛陽之德。入能除害，出能興利，人君之象也。是時，隱以弟桓幼，代而攝立。公子翬見隱居位已久，勸之遂立。〔六〕隱既不許，翬懼而易其辭，〔七〕遂與桓共殺隱。天見其將然，故正月大雨水而雷電。是陽不閉陰，出涉危難而害萬物。天戒若曰，為君失時，賊弟佞臣將作亂矣。後八日大雨雪，陰見間隙而勝陽，篡殺之禍將成也。公不寤，後二年而殺。","sentenceOrder":126},
  {"id":"s_work_han_thu_34_127","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「雨雪，雨音于具反。」","sentenceOrder":127},
  {"id":"s_work_han_thu_34_128","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「下雨音于具反。後類並同。」","sentenceOrder":128},
  {"id":"s_work_han_thu_34_129","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「坤下震上也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_34_130","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「兌下震上也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_34_131","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「毓字與育同。核亦荄字也。草根曰荄，音該。」","sentenceOrder":131},
  {"id":"s_work_han_thu_34_132","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　師古曰：「公子翬，魯大夫羽父也。勸殺（威）〔桓〕公，己求為太宰。翬音揮。」","sentenceOrder":132},
  {"id":"s_work_han_thu_34_133","chapterId":"ch_work_han_thu_34","textTraditional":"〔七〕　師古曰：「反謂桓公云隱欲殺之。」","sentenceOrder":133},
  {"id":"s_work_han_thu_34_134","chapterId":"ch_work_han_thu_34","textTraditional":"昭帝始元元年七月，大水雨，自七月至十月。成帝建始三年秋，大雨三十餘日；四年九月，大雨十餘日。","sentenceOrder":134},
  {"id":"s_work_han_thu_34_135","chapterId":"ch_work_han_thu_34","textTraditional":"左氏傳愍公二年，晉獻公使太子申生帥師，〔一〕公衣之偏衣，佩之金玦。〔二〕狐突歎曰：「時，事之徵也；衣，身之章也；佩，衷之旗也。〔三〕故敬其事，則命以始；〔四〕服其身，則衣之純；〔五〕用其衷，則佩之度。〔六〕今命以時卒，閟其事也；〔七〕衣以尨服，遠其躬也；〔八〕佩以金玦，棄其衷也。服以遠之，時以閟之，尨涼冬殺，金寒玦離，胡可恃也！」〔九〕梁餘子養曰：「帥師者，受命于廟，受脤於社，有常服矣。〔一０〕弗獲而尨，命可知也。死而不孝，不如逃之。」罕夷曰：「尨奇無常，金玦不復，君有心矣。」〔一一〕後四年，申生以讒自殺。近服妖也。","sentenceOrder":135},
  {"id":"s_work_han_thu_34_136","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「以伐東山皋落氏。」","sentenceOrder":136},
  {"id":"s_work_han_thu_34_137","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「偏衣，謂左右異色，其半象公之服也。金玦，以金為玦也。半環曰玦。」","sentenceOrder":137},
  {"id":"s_work_han_thu_34_138","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「狐突，晉大夫伯行，時為太子御戎也。徵，（澄）〔證〕也。章，明也。旗，表也。衣所以明貴賤，佩所以表中心。」","sentenceOrder":138},
  {"id":"s_work_han_thu_34_139","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「賞以春夏。」","sentenceOrder":139},
  {"id":"s_work_han_thu_34_140","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「壹其色。」","sentenceOrder":140},
  {"id":"s_work_han_thu_34_141","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　師古曰：「佩玉者，君子之常度。」","sentenceOrder":141},
  {"id":"s_work_han_thu_34_142","chapterId":"ch_work_han_thu_34","textTraditional":"〔七〕　應劭曰：「卒，盡也。閟，閉也。謂十二月盡時也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_34_143","chapterId":"ch_work_han_thu_34","textTraditional":"〔八〕　師古曰：「尨，雜色也，謂偏衣也。遠音于萬反。其下並同。」","sentenceOrder":143},
  {"id":"s_work_han_thu_34_144","chapterId":"ch_work_han_thu_34","textTraditional":"〔九〕　師古曰：「涼，薄也。尨色不能純，故曰薄也。冬主殺氣，金行在西，是謂之寒。玦形半缺，故云離。」","sentenceOrder":144},
  {"id":"s_work_han_thu_34_145","chapterId":"ch_work_han_thu_34","textTraditional":"〔一０〕師古曰：「梁餘子養，晉大夫也，時為下軍御。軍之常服則韋弁。」","sentenceOrder":145},
  {"id":"s_work_han_thu_34_146","chapterId":"ch_work_han_thu_34","textTraditional":"〔一一〕應劭曰：「奇，奇怪非常意。復，反也。金玦，猶（玦）〔決〕去，不反意也。」師古曰：「罕夷，晉大夫，時為下軍卿也。有心，害太子之心也。復音扶目反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_34_147","chapterId":"ch_work_han_thu_34","textTraditional":"左氏傳曰，鄭子臧好聚鷸冠，〔一〕鄭文公惡之，使盜殺之〔二〕。劉向以為近服妖者也。一曰，非獨為子臧之身，亦文公之戒也。初，文公不禮晉文，〔三〕又犯天子命而伐滑，〔四〕不尊尊敬上。其後晉文伐鄭，幾亡國。〔五〕","sentenceOrder":147},
  {"id":"s_work_han_thu_34_148","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　張晏曰：「鷸鳥赤足黃文，以其毛飾冠。」韋昭曰：「鷸，今翠鳥也。」師古曰：「子臧，鄭文公子也。鷸，大鳥，即戰國策所云啄蚌者也。天之將雨，鷸則知之。翠鳥自有鷸名，而此飾冠，非翠鳥也。逸周書曰『知天文者冠鷸冠』，蓋以鷸鳥知天時故也。禮圖謂之『術氏冠』。鷸音聿，又音術。」","sentenceOrder":148},
  {"id":"s_work_han_thu_34_149","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「時已得罪出奔宋，故使盜殺之於陳、宋之間。」","sentenceOrder":149},
  {"id":"s_work_han_thu_34_150","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「晉文公之為公子也，避驪姬之難而出奔，欲之楚，過鄭，鄭不禮焉。」","sentenceOrder":150},
  {"id":"s_work_han_thu_34_151","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「僖二十四年，鄭公子士〔洩〕及堵俞彌帥師伐滑。王使伯服游、孫伯如鄭請滑，鄭伯不聽而執二子。」","sentenceOrder":151},
  {"id":"s_work_han_thu_34_152","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「僖三十年，晉侯、秦伯圍鄭，佚之狐曰：『國危矣！』使燭之武見秦伯，師乃退也。幾音鉅依反。」","sentenceOrder":152},
  {"id":"s_work_han_thu_34_153","chapterId":"ch_work_han_thu_34","textTraditional":"昭帝時，昌邑王賀遣中大夫之長安，多治仄注冠，〔一〕以賜大臣，又以冠奴。劉向以為近服妖也。時王賀狂悖，〔二〕聞天子不豫，〔三〕弋獵馳騁如故，與騶奴宰人游居娛戲，驕嫚不敬。〔四〕冠者尊服，奴者賤人，賀無故好作非常之冠，暴尊象也。以冠奴者，當自至尊墜至賤也。〔五〕其後帝崩，無子，漢大臣徵賀為嗣。即位，狂亂無道，縛戮諫者夏侯勝等。於是大臣白皇太后，廢賀為庶人。賀為王時，又見大白狗冠方山冠而無尾，〔六〕此服妖，亦犬禍也。賀以問郎中令龔遂，遂曰：「此天戒，言在仄者盡冠狗也。〔七〕去之則存，不去則亡矣。」賀既廢數年，宣帝封之為列侯，復有罪，死不得置後，又犬禍無尾之效也。京房易傳曰：「行不順，厥咎人奴冠，天下亂，辟無適，〔八〕妾子拜。」〔九〕又曰：「君不正，臣欲篡，厥妖狗冠出朝門。」","sentenceOrder":153},
  {"id":"s_work_han_thu_34_154","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　應劭曰：「今法冠是也。」李奇曰：「一曰高山冠，本齊冠也，謁者服之。」師古曰：「仄，古側字也。謂之側注者，言形側立而下注也。蔡邕云高九（尺）〔寸〕，鐵為卷，非法冠及高山也。卷音去權反。」","sentenceOrder":154},
  {"id":"s_work_han_thu_34_155","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「悖，惑也，音布內反。」","sentenceOrder":155},
  {"id":"s_work_han_thu_34_156","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「言有疾不悅豫也。周書顧命曰『王有疾，不豫』。」","sentenceOrder":156},
  {"id":"s_work_han_thu_34_157","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「騶，廄御也。宰人，主膳者也。娛，樂也。戲音僖。」","sentenceOrder":157},
  {"id":"s_work_han_thu_34_158","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「墜，墮也，音直類反。」","sentenceOrder":158},
  {"id":"s_work_han_thu_34_159","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　鄧展曰：「方山冠以五采縠為之，樂舞人所服。」","sentenceOrder":159},
  {"id":"s_work_han_thu_34_160","chapterId":"ch_work_han_thu_34","textTraditional":"〔七〕　師古曰：「言王左右侍側之人不識禮義，若狗而著冠者耳。冠音工喚反。其下亦同。」","sentenceOrder":160},
  {"id":"s_work_han_thu_34_161","chapterId":"ch_work_han_thu_34","textTraditional":"〔八〕　如淳曰：「辟，君也。適，適子也。」師古曰：「辟音壁。適讀曰嫡。」","sentenceOrder":161},
  {"id":"s_work_han_thu_34_162","chapterId":"ch_work_han_thu_34","textTraditional":"〔九〕　如淳曰：「無適子故也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_34_163","chapterId":"ch_work_han_thu_34","textTraditional":"成帝鴻嘉、永始之間，好為微行出游，選從期門郎有材力者，及私奴客，多至十餘，少五六人，皆白衣袒幘，〔一〕帶持刀劍。或乘小車，御者在茵上，〔二〕或皆騎，出入市里郊野，遠至旁縣。時，大臣車騎將軍王音及劉向等數以切諫。谷永曰：「易稱『得臣無家』，〔三〕言王者臣天下，無私家也。今陛下棄萬乘之至貴，樂家人之賤事；厭高美之尊稱，好匹夫之卑字；〔四〕崇聚票輕無誼之人，以為私客；〔五〕置私田於民間，畜私奴車馬於北宮；數去南面之尊，離深宮之固，挺身獨與小人晨夜相隨，〔六〕烏集醉飽吏民之家〔七〕，亂服共坐，溷肴亡別，〔八〕閔勉遯樂，晝夜在路。〔九〕典門戶奉宿衛之臣執干戈守空宮，公卿百寮不知陛下所在，積數年矣。昔虢公為無道，有神降曰『賜爾土田』，〔一０〕言將以庶人受土田也。諸侯夢得土田，為失國祥，〔一一〕而況王者畜私田財物，為庶人之事乎！」","sentenceOrder":163},
  {"id":"s_work_han_thu_34_164","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「袒幘，不加上冠。」","sentenceOrder":164},
  {"id":"s_work_han_thu_34_165","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　蘇林曰：「茵，車上蓐也。御者錯亂，更在茵上坐也。」師古曰：「車小，故御者不得迴避，而在天子茵上也。茵音因。」","sentenceOrder":165},
  {"id":"s_work_han_thu_34_166","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「損卦上九爻辭。」","sentenceOrder":166},
  {"id":"s_work_han_thu_34_167","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　如淳曰：「稱張放家人，是為卑字。」師古曰：「為微行，故變易姓名。」","sentenceOrder":167},
  {"id":"s_work_han_thu_34_168","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「票音匹妙反，又音頻妙反。」","sentenceOrder":168},
  {"id":"s_work_han_thu_34_169","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　師古曰：「挺，引也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_34_170","chapterId":"ch_work_han_thu_34","textTraditional":"〔七〕　師古曰：「乍合乍離，如烏之集。」","sentenceOrder":170},
  {"id":"s_work_han_thu_34_171","chapterId":"ch_work_han_thu_34","textTraditional":"〔八〕　師古曰：「溷肴，謂雜亂也。溷音胡困反。」","sentenceOrder":171},
  {"id":"s_work_han_thu_34_172","chapterId":"ch_work_han_thu_34","textTraditional":"〔九〕　師古曰：「閔勉猶黽勉，言不息也。遯樂，言流遯為樂也。」","sentenceOrder":172},
  {"id":"s_work_han_thu_34_173","chapterId":"ch_work_han_thu_34","textTraditional":"〔一０〕師古曰：「春秋左氏傳莊公三十二年有神降於莘，虢公使祝應、宗區、史（囂）〔嚚〕享焉。神賜之土田。史（囂）〔嚚〕曰：『虢其亡乎！』」","sentenceOrder":173},
  {"id":"s_work_han_thu_34_174","chapterId":"ch_work_han_thu_34","textTraditional":"〔一一〕師古曰：「僖五年，晉滅虢，虢公醜奔京師。」","sentenceOrder":174},
  {"id":"s_work_han_thu_34_175","chapterId":"ch_work_han_thu_34","textTraditional":"左氏傳曰，周景王時大夫賓起見雄雞自斷其尾。〔一〕劉向以為近雞禍也。是時，王有愛子子晁，王與賓起陰謀欲立之。〔二〕田于北山，將因兵眾殺適子之黨，〔三〕未及而崩。三子爭國，王室大亂。其後，賓起誅死，〔四〕子晁奔楚而敗。〔五〕京房易傳曰：「有始無終，厥妖雄雞自齧斷其尾。」","sentenceOrder":175},
  {"id":"s_work_han_thu_34_176","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「賓起即賓孟。」","sentenceOrder":176},
  {"id":"s_work_han_thu_34_177","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「子晁，王之庶長子。」","sentenceOrder":177},
  {"id":"s_work_han_thu_34_178","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「適讀曰嫡。嫡子王子猛，（反）〔及〕後為悼王。子猛之黨謂劉獻公、單穆公。」","sentenceOrder":178},
  {"id":"s_work_han_thu_34_179","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「三子，謂子晁、子猛及子猛弟敬王丐也。劉子遂攻賓起，殺之。事並在昭公二十二年。」","sentenceOrder":179},
  {"id":"s_work_han_thu_34_180","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「昭二十六年，邵伯盈逐王子晁，子晁奔楚。定公五年，王人殺之於楚。」","sentenceOrder":180},
  {"id":"s_work_han_thu_34_181","chapterId":"ch_work_han_thu_34","textTraditional":"宣帝黃龍元年，未央殿輅軨中雌雞化為雄，〔一〕毛衣變化而不鳴，不將，無距。〔二〕元帝初元中，丞相府史家雌雞伏子，漸化為雄，〔三〕冠距鳴將。永光中，有獻雄雞生角者。京房易傳曰：「雞知時，知時者當死。」房以為己知時，恐當之。劉向以為房失雞占。雞者小畜，主司時，起居人，〔四〕小臣執事為政之象也。言小臣將秉君威，以害正事，猶石顯也。竟寧元年，石顯伏辜，此其效也。一曰，石顯何足以當此？昔武王伐殷，至于牧野，誓師曰：「古人有言曰『牝雞無晨；牝雞之晨，惟家之索。』今殷王紂惟婦言用。」〔五〕繇是論之，〔六〕黃龍、初元、永光雞變，乃國家之占，妃后象也。孝元王皇后以甘露二年生男，立為太子。妃，王禁女也。黃龍元年，宣帝崩，太子立，是為元帝。王妃將為皇后，故是歲未央殿中雌雞為雄，明其占在正宮也。不鳴不將無距，貴始萌而尊未成也。至元帝初元元年，將立王皇后，先以為婕妤。三月癸卯制書曰：「其封婕妤父丞相少史王禁為陽平侯，位特進。」丙午，立王婕妤為皇后。明年正月，立皇后子為太子。故應是，丞相府史家雌雞為雄，其占即丞相少史之女也。伏子者，明已有子也。冠距鳴將者，尊已成也。永光二年，陽平頃侯禁薨，子鳳嗣侯，為侍中衛尉。元帝崩，皇太子立，是為成帝。尊皇后為皇太后，以后弟鳳為大司馬大將軍，領尚書事，上委政，無所與。〔七〕王氏之權自鳳起，故於鳳始受爵位時，雄雞有角，明視作威〔八〕顓君害上〔九〕危國者，從此人始也。其後群弟世權，以至於莽，遂篡天下。即位五年，王太后乃崩，此其效也。京房易傳曰：「賢者居明夷之世，知時而傷，〔一０〕或眾在位，〔一一〕厥妖雞生角。雞生角，時主獨。」又曰：「婦人顓政，國不靜；牝雞雄鳴，主不榮。」故房以為己亦在占中矣。","sentenceOrder":181},
  {"id":"s_work_han_thu_34_182","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　孟康曰：「輅軨，廄名也。」師古曰：「百官表太僕屬官有輅軨丞。輅與路同。軨音零。」","sentenceOrder":182},
  {"id":"s_work_han_thu_34_183","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「將謂率領其群也。距，雞附足骨，鬥時所用刺之。」","sentenceOrder":183},
  {"id":"s_work_han_thu_34_184","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「初尚伏子，後乃稍稍化為雄也。伏音房富反。」","sentenceOrder":184},
  {"id":"s_work_han_thu_34_185","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「至時而鳴，以為人起居之節。」","sentenceOrder":185},
  {"id":"s_work_han_thu_34_186","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「周書牧誓之辭。晨謂晨時鳴也。索，盡也。言婦人為政，猶雌雞而代雄鳴，是喪家之道也。索音思各反。」","sentenceOrder":186},
  {"id":"s_work_han_thu_34_187","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　師古曰：「繇讀與由同。」","sentenceOrder":187},
  {"id":"s_work_han_thu_34_188","chapterId":"ch_work_han_thu_34","textTraditional":"〔七〕　師古曰：「與讀曰豫。言政皆出鳳，天子不豫。」","sentenceOrder":188},
  {"id":"s_work_han_thu_34_189","chapterId":"ch_work_han_thu_34","textTraditional":"〔八〕　師古曰：「視讀曰示。」","sentenceOrder":189},
  {"id":"s_work_han_thu_34_190","chapterId":"ch_work_han_thu_34","textTraditional":"〔九〕　師古曰：「顓與專同。其下類此。」","sentenceOrder":190},
  {"id":"s_work_han_thu_34_191","chapterId":"ch_work_han_thu_34","textTraditional":"〔一０〕師古曰：「易之明夷卦曰：『明入地中，明夷。』夷，傷也，離下坤上，言日在地中，傷其明也。知時，謂知天時者也。賢而被傷，故取明夷之義。」","sentenceOrder":191},
  {"id":"s_work_han_thu_34_192","chapterId":"ch_work_han_thu_34","textTraditional":"〔一一〕師古曰：「言虛偽無實之人矯惑於眾在職位也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_34_193","chapterId":"ch_work_han_thu_34","textTraditional":"成公七年「正月，鼷鼠食郊牛角；〔一〕改卜牛，又食其角」。劉向以為近青祥，亦牛禍也，不敬而傋霿之所致也。昔周公制禮樂，成周道，故成王命魯郊祀天地，以尊周公。至成公時，三家始顓政，魯將從此衰。天愍周公之德，痛其將有敗亡之禍，故於郊祭而見戒云。鼠，小蟲，性盜竊，鼷又其小者也。牛，大畜，祭天尊物也。角，兵象，在上，君威也。小小鼷鼠，食至尊之牛角，象季氏乃陪臣盜竊之人，將執國命以傷君威而害周公之祀也。改卜牛，鼷鼠又食其角，天重語之也。〔二〕成公怠慢昏亂，遂君臣更執于晉。〔三〕至于襄公，晉為溴梁之會，〔四〕天下大夫皆奪君政。〔五〕其後三家逐昭公，卒死于外，〔六〕幾絕周公之祀。〔七〕董仲舒以為鼷鼠食郊牛，皆養牲不謹也。京房易傳曰：「祭天不慎，厥妖鼷鼠齧郊牛角。」","sentenceOrder":193},
  {"id":"s_work_han_thu_34_194","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「鼷，小鼠也，即今所謂甘鼠者，音奚。」","sentenceOrder":194},
  {"id":"s_work_han_thu_34_195","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「重音直用反。」","sentenceOrder":195},
  {"id":"s_work_han_thu_34_196","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「更，互也。十年秋，公如晉，晉人以公為貳於楚，故止公，至十一年三月乃得歸。十六年秋，公會晉侯於沙隨，晉受叔孫僑如之譖而止公。是年九月，又信僑如之譖，執季孫行父，舍之於苕丘，十二月乃得歸。故云君臣更執也。更音工衡反。」","sentenceOrder":196},
  {"id":"s_work_han_thu_34_197","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「襄十六年，晉平公會諸侯于溴梁。溴梁者，溴水之梁也。溴水出河內軹縣東南，至溫入河。溴音工覓反。」","sentenceOrder":197},
  {"id":"s_work_han_thu_34_198","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「溴梁之會，諸侯皆在，而魯叔孫豹、晉荀偃、宋向戌、衛甯殖、鄭公孫蠆、小邾之大夫盟，是奪其君政也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_34_199","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　師古曰：「已解於上。」","sentenceOrder":199},
  {"id":"s_work_han_thu_34_200","chapterId":"ch_work_han_thu_34","textTraditional":"〔七〕　師古曰：「幾音鉅衣反。」","sentenceOrder":200},
  {"id":"s_work_han_thu_34_201","chapterId":"ch_work_han_thu_34","textTraditional":"定公十五年「正月，鼷鼠食郊牛，牛死」。劉向以為定公知季氏逐昭公，罪惡如彼，親用孔子為夾谷之會，齊人來歸鄆、讙、龜陰之田，〔一〕聖德如此，反用季桓子，淫於女樂，而退孔子，無道甚矣。〔二〕詩曰：「人而亡儀，不死何為！」〔三〕是歲五月，定公薨，牛死之應也。京房易傳曰：「子不子，鼠食其郊牛。」","sentenceOrder":201},
  {"id":"s_work_han_thu_34_202","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「夾谷，齊地也，一名祝其。定公十年，公與齊侯會於夾谷，齊侯欲使萊人以兵劫公。孔子以公退，命士眾兵之，齊侯乃止。又欲以盟要公，孔子不欲，使茲無還以辭對。又欲詐享公，孔子又距而不受。於是齊人乃服。先是季氏之臣陽貨以鄆、讙、龜陰之田奔齊，至此會，乃以歸我。鄆、讙，二邑名。龜陰，龜山之陰。夾音頰。讙音驩。」","sentenceOrder":202},
  {"id":"s_work_han_thu_34_203","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「桓子，季平子之子季孫斯也。女樂已解於上。」","sentenceOrder":203},
  {"id":"s_work_han_thu_34_204","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「衛詩相鼠之篇也。（無）〔亡〕儀，無禮儀也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_34_205","chapterId":"ch_work_han_thu_34","textTraditional":"哀公元年「正月，鼷鼠食郊牛」。劉向以為天意汲汲於用聖人，逐三家，故復見戒也。〔一〕哀公年少，不親見昭公之事，故見敗亡之異。已而哀不寤，身奔於粵，此其效也。〔二〕","sentenceOrder":205},
  {"id":"s_work_han_thu_34_206","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「聖人，孔子也。見，顯也。」","sentenceOrder":206},
  {"id":"s_work_han_thu_34_207","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「哀二十七年，公欲以越伐魯而去三桓，公如公孫有山氏，因遜于邾，遂如越。國人施罪於公孫有山氏，而立哀公之子悼公。」","sentenceOrder":207},
  {"id":"s_work_han_thu_34_208","chapterId":"ch_work_han_thu_34","textTraditional":"昭帝元鳳元年九月，燕有黃鼠銜其尾舞王宮端門中，〔一〕王往視之，鼠舞如故。王使吏以酒脯祠，鼠舞不休，一日一夜死。近黃祥，時燕剌王旦謀反將死之象也。其月，發覺伏辜。京房易傳曰：「誅不原情，厥妖鼠舞門。」〔二〕","sentenceOrder":208},
  {"id":"s_work_han_thu_34_209","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「宮之正門。」","sentenceOrder":209},
  {"id":"s_work_han_thu_34_210","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「不原情者，不得其本情。」","sentenceOrder":210},
  {"id":"s_work_han_thu_34_211","chapterId":"ch_work_han_thu_34","textTraditional":"成帝建始四年九月，長安城南有鼠銜黃蒿、柏葉，上民冢柏及榆樹上為巢，桐柏尤多。〔一〕巢中無子，皆有乾鼠矢數十。時議臣以為恐有水災。鼠，盜竊小蟲，夜出晝匿；今晝去穴而登木，象賤人將居顯貴之位也。桐柏，衛思后園所在也。其後，趙皇后自微賤登至尊，與衛后同類。趙后終無子而為害。明年，有鳶焚巢，殺子之異也。〔二〕天象仍見，甚可畏也。〔三〕一曰，皆王莽竊位之象云。京房易傳曰：「臣私祿罔辟，厥妖鼠巢。」","sentenceOrder":211},
  {"id":"s_work_han_thu_34_212","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「桐柏，本亭名，衛思后於其地葬也。」","sentenceOrder":212},
  {"id":"s_work_han_thu_34_213","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「鳶，鴟也，音弋全反。」","sentenceOrder":213},
  {"id":"s_work_han_thu_34_214","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「仍，頻也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_34_215","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　李奇曰：「辟，君也。擅私爵祿，誣罔其君。」","sentenceOrder":215},
  {"id":"s_work_han_thu_34_216","chapterId":"ch_work_han_thu_34","textTraditional":"文公十三年，「大室屋壞」。近金沴木，木動也。先是，冬，釐公薨，十六月乃作主。〔一〕後六月，又吉禘於太廟而致釐公，〔二〕春秋譏之。經曰：「大事於太廟，躋釐公。」〔三〕左氏說曰：太廟，周公之廟，饗有禮義者也；祀，國之大事也。惡其亂國之大事於太廟，故言大事也。躋，登也，登釐公於愍公上，逆祀也。釐雖愍之庶兄，嘗為愍臣，臣子一例，不得在愍上。又未三年而吉禘，前後亂賢父聖祖之大禮，內為貌不恭而狂，外為言不從而僭。故是歲自十二月不雨，至于秋七月。後年，若是者三，而太室屋壞矣。前堂曰太廟，中央曰太室；屋，其上重屋尊高者也，象魯自是陵夷，將墮周公之祀也。〔四〕穀梁、公羊經曰，世室，魯公伯禽之廟也。周公稱太廟，魯公稱世室。大事者，祫祭也。〔五〕躋釐公者，先禰後祖也。","sentenceOrder":216},
  {"id":"s_work_han_thu_34_217","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「主，廟主也。僖公三十三年十二月薨，至文二年二月乃作主，間有一閏，故十六月也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_34_218","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「禘，祭也，（二）〔一一〕而祭之。文二年八月而禘，距作主六月也。致謂（外）〔升〕其主於廟。」","sentenceOrder":218},
  {"id":"s_work_han_thu_34_219","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「躋音子奚反，又音子詣反。」","sentenceOrder":219},
  {"id":"s_work_han_thu_34_220","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「墮，毀也，音火規反。」","sentenceOrder":220},
  {"id":"s_work_han_thu_34_221","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「祫，合也。毀廟及未毀廟之主，皆合祭於太祖。」","sentenceOrder":221},
  {"id":"s_work_han_thu_34_222","chapterId":"ch_work_han_thu_34","textTraditional":"景帝三年十二月，吳二城門自傾，大船自覆。劉向以為近金沴木，木動也。先是，吳王濞以太子死於漢，稱疾不朝，陰與楚王戊謀為逆亂。城猶國也，其一門名曰楚門，一門曰魚門。吳地以船為家，以魚為食。天戒若曰，與楚所謀，傾國覆家。吳王不寤，正月，與楚俱起兵，身死國亡。京房易傳曰：「上下咸誖，厥妖城門壞。」〔一〕","sentenceOrder":222},
  {"id":"s_work_han_thu_34_223","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「誖，惑也，音布內反。」","sentenceOrder":223},
  {"id":"s_work_han_thu_34_224","chapterId":"ch_work_han_thu_34","textTraditional":"宣帝時，大司馬霍禹所居第門自壞。時禹內不順，外不敬，見戒不改，卒受滅亡之誅。","sentenceOrder":224},
  {"id":"s_work_han_thu_34_225","chapterId":"ch_work_han_thu_34","textTraditional":"哀帝時，大司馬董賢第門自壞。時賢以私愛居大位，賞賜無度，驕嫚不敬，大失臣道，見戒不改。後賢夫妻自殺，家徙合浦。","sentenceOrder":225},
  {"id":"s_work_han_thu_34_226","chapterId":"ch_work_han_thu_34","textTraditional":"傳曰：「言之不從，是謂不艾，〔一〕厥咎僭，厥罰恆陽，厥極憂。時則有詩妖，時則有介蟲之孽，時則有犬禍，時則有口舌之痾，時則有白眚白祥。惟木沴金。」","sentenceOrder":226},
  {"id":"s_work_han_thu_34_227","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「艾讀曰乂。」","sentenceOrder":227},
  {"id":"s_work_han_thu_34_228","chapterId":"ch_work_han_thu_34","textTraditional":"「言之不從」，從，順也。「是謂不乂」，乂，治也。孔子曰：「君子居其室，出其言不善，則千里之外違之，況其邇者虖！」〔一〕詩云：「如蜩如螗，如沸如羹。」〔二〕言上號令不順民心，虛譁憒亂，則不能治海內，失在過差，故其咎僭。僭，差也。刑罰妄加，群陰不附，則陽氣勝，故其罰常陽也。旱傷百穀，則有寇難，上下俱憂，故其極憂也。君炕陽而暴虐，〔三〕臣畏刑而柑口，〔四〕則怨謗之氣發於歌謠，故有詩妖。介蟲孽者，謂小蟲有甲飛揚之類，陽氣所生也，於春秋為螽，今謂之蝗，皆其類也。於易，兌為口，犬以吠守，而不可信，言氣毀故有犬禍。一曰，旱歲犬多狂死及為怪，亦是也。及人，則多病口喉欬者，故有口舌痾。金色白，故有白眚白祥。凡言傷者，病金氣；金氣病，則木沴之。其極憂者，順之，其福曰康寧，劉歆言傳曰時有毛蟲之孽。說以為於天文西方參為虎星，故為毛蟲。","sentenceOrder":228},
  {"id":"s_work_han_thu_34_229","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「易上繫之辭也。邇，近也。」","sentenceOrder":229},
  {"id":"s_work_han_thu_34_230","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「大雅蕩之詩也。蜩，蟬也。螗，蝘也，即虭蟟也。謂政無文理，虛言蹲沓，如蜩螗之鳴，湯之沸涫，羹之將孰也。蜩音調。螗音唐。蝘音偃。虭音貂。蟟音聊。涫音下館反。」","sentenceOrder":230},
  {"id":"s_work_han_thu_34_231","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「凡言炕陽者，枯涸之意，謂無惠澤於下也。炕音口浪反。」","sentenceOrder":231},
  {"id":"s_work_han_thu_34_232","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「柑，籋也，音其廉反。籋音女涉反。」","sentenceOrder":232},
  {"id":"s_work_han_thu_34_233","chapterId":"ch_work_han_thu_34","textTraditional":"史記周單襄公與晉郤錡、郤犨、郤至、齊國佐語，〔一〕告魯成公曰：「晉將有亂，三郤其當之虖！夫郤氏，晉之寵人也，（二）〔三〕卿而五大夫，可以戒懼矣。高位實疾顛，厚味實腊毒。〔二〕今郤伯之語犯，叔迂，季伐。〔三〕犯則陵人，迂則誣人，伐則掩人。有是寵也，而益之以三怨，其誰能忍之！雖齊國子亦將與焉。〔四〕立於淫亂之國，而好盡言以招人過，〔五〕怨之本也。唯善人能受盡言，齊其有虖？」〔六〕十七年，晉殺三郤。十八年，齊殺國佐。凡此屬，皆言不從之咎云。","sentenceOrder":233},
  {"id":"s_work_han_thu_34_234","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「單襄公，解已在前。郤錡，駒伯也。郤犨，苦成叔也。郤至，昭子，即溫季也。國佐，齊大夫國武子也。」","sentenceOrder":234},
  {"id":"s_work_han_thu_34_235","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「顛，仆也。腊，久也。言位高者必速顛仆也，味厚者為毒久。」","sentenceOrder":235},
  {"id":"s_work_han_thu_34_236","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「伯，駒伯也。叔，苦成叔也。季，溫季也。犯，侵也。迂，夸誕也。伐，矜尚也。」","sentenceOrder":236},
  {"id":"s_work_han_thu_34_237","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「與讀曰豫。豫於禍。」","sentenceOrder":237},
  {"id":"s_work_han_thu_34_238","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　蘇林曰：「招音翹。招，舉也。」師古曰：「盡言，猶極言也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_34_239","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　師古曰：「言無善人不能受盡言。」","sentenceOrder":239},
  {"id":"s_work_han_thu_34_240","chapterId":"ch_work_han_thu_34","textTraditional":"晉穆侯以條之役生太子，名之曰仇；〔一〕其弟以千畝之戰生，名之曰成師。〔二〕師服曰：「異哉，君之名子也！〔三〕夫名以制誼，誼以出禮，〔四〕禮以體政，政以正民，〔五〕是以政成而民聽；易則生亂。〔六〕嘉耦曰妃，怨耦曰仇，古之命也。〔七〕今君名太子曰仇，弟曰成師，始兆亂矣，兄其替虖！」〔八〕及仇嗣立，是為文侯。文侯卒，子昭侯立，封成師于曲沃，號桓叔。〔九〕後晉人殺昭侯而納桓叔，不克。〔一０〕復立昭侯子孝侯，桓叔子嚴伯殺之。晉人立其弟鄂侯。鄂侯生哀侯，嚴伯子武公復殺哀侯及其弟，滅之，而代有晉國。〔一一〕","sentenceOrder":240},
  {"id":"s_work_han_thu_34_241","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「穆侯，僖侯之孫也。條，晉地也。蓋以敵來侵己，當戰時而生，故取仇忿之義以名子。」","sentenceOrder":241},
  {"id":"s_work_han_thu_34_242","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「太子之弟，即桓叔也。畮，古畝字也。千畝亦地名，意取能成其師眾也。」","sentenceOrder":242},
  {"id":"s_work_han_thu_34_243","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「師服，晉大夫。」","sentenceOrder":243},
  {"id":"s_work_han_thu_34_244","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「先制義理然後立名。義理既定，禮由之出。」","sentenceOrder":244},
  {"id":"s_work_han_thu_34_245","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「政以禮成，俗所以正。」","sentenceOrder":245},
  {"id":"s_work_han_thu_34_246","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　師古曰：「反易禮義，則亂生也。」","sentenceOrder":246},
  {"id":"s_work_han_thu_34_247","chapterId":"ch_work_han_thu_34","textTraditional":"〔七〕　師古曰：「本自古昔而有此名。」","sentenceOrder":247},
  {"id":"s_work_han_thu_34_248","chapterId":"ch_work_han_thu_34","textTraditional":"〔八〕　師古曰：「替，廢也。」","sentenceOrder":248},
  {"id":"s_work_han_thu_34_249","chapterId":"ch_work_han_thu_34","textTraditional":"〔九〕　師古曰：「昭侯國亂身危，不能自安，故封成師為曲沃伯也。桓，諡也。昭侯叔父，故謂之叔也。」","sentenceOrder":249},
  {"id":"s_work_han_thu_34_250","chapterId":"ch_work_han_thu_34","textTraditional":"〔一０〕師古曰：「事不遂。」","sentenceOrder":250},
  {"id":"s_work_han_thu_34_251","chapterId":"ch_work_han_thu_34","textTraditional":"〔一一〕師古曰：「武始并晉國，故稱公也。事在桓三年。」","sentenceOrder":251},
  {"id":"s_work_han_thu_34_252","chapterId":"ch_work_han_thu_34","textTraditional":"宣公六年，鄭公子曼滿與王子伯廖語，欲為卿。〔一〕伯廖告人曰：「無德而貪，其在周易豐之離，〔二〕弗過之矣。」〔三〕間一歲，鄭人殺之。〔四〕","sentenceOrder":252},
  {"id":"s_work_han_thu_34_253","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「曼滿、伯廖，皆鄭大夫也。廖音聊。」","sentenceOrder":253},
  {"id":"s_work_han_thu_34_254","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　張晏曰：「離下震上，豐。上六變而之離，曰『豐其屋，蔀其家』也。」","sentenceOrder":254},
  {"id":"s_work_han_thu_34_255","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「言無道德而大其屋，不過三歲，必滅亡也。」","sentenceOrder":255},
  {"id":"s_work_han_thu_34_256","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「間一歲者，中間隔一歲。」","sentenceOrder":256},
  {"id":"s_work_han_thu_34_257","chapterId":"ch_work_han_thu_34","textTraditional":"襄公二十九年，齊高子容與宋司徒見晉知伯，汝齊相禮。〔一〕賓出，汝齊語知伯曰：「二子皆將不免！子容專，司徒侈，皆亡家之主也。〔二〕專則速及，侈將以其力敝，專則人實敝之，將及矣。」九月，高子出奔燕。","sentenceOrder":257},
  {"id":"s_work_han_thu_34_258","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「高子容，齊大夫高止也。宋司徒，華定。知伯，晉大夫荀盈也。汝齊，晉大夫司馬侯也。」","sentenceOrder":258},
  {"id":"s_work_han_thu_34_259","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「專，自是也。侈，奢泰。」","sentenceOrder":259},
  {"id":"s_work_han_thu_34_260","chapterId":"ch_work_han_thu_34","textTraditional":"襄公三十一年正月，魯穆叔會晉歸，告孟孝伯曰：「趙孟將死矣！〔一〕其語偷，不似民主；〔二〕且年未盈五十，而諄諄焉如八九十者，弗能久矣。〔三〕若趙孟死，為政者其韓子虖？〔四〕吾子盍與季孫言之？可以樹善，君子也。」〔五〕孝伯曰：「民生幾何，誰能毋偷！〔六〕朝不及夕，將焉用樹！」穆叔告人曰：「孟孫將死矣！吾語諸趙孟之偷也，而又甚焉。」九月，孟孝伯卒。","sentenceOrder":260},
  {"id":"s_work_han_thu_34_261","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「穆叔，即叔孫穆子也。孟孝伯，魯大夫仲孫羯也。趙孟，晉卿趙文子也，名武。前年十月，穆叔與武同會澶泉，至此年正月乃歸。」","sentenceOrder":261},
  {"id":"s_work_han_thu_34_262","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「偷，苟且。」","sentenceOrder":262},
  {"id":"s_work_han_thu_34_263","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「諄諄，重頓之貌也，諄音之閏反。」","sentenceOrder":263},
  {"id":"s_work_han_thu_34_264","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「韓子，韓宣子也，名起。」","sentenceOrder":264},
  {"id":"s_work_han_thu_34_265","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「季孫，謂季武子也，名宿。言韓起有君子之德，方執晉政，可素厚之，以立善也。」","sentenceOrder":265},
  {"id":"s_work_han_thu_34_266","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　師古曰：「幾何，言無多時也。幾音居豈反。」","sentenceOrder":266},
  {"id":"s_work_han_thu_34_267","chapterId":"ch_work_han_thu_34","textTraditional":"昭公元年，周使劉定公勞晉趙孟，〔一〕因曰：「子弁冕以臨諸侯，盍亦遠績禹功，而大庇民乎？」〔二〕對曰：「老夫罪戾是懼，焉能恤遠？吾儕偷食，朝不謀夕，何其長也？」〔三〕劉子歸，以語王曰：「諺所謂老將知而耄及之者，其趙孟之謂虖！〔四〕為晉正卿以主諸侯，而儕于隸人，朝不謀夕，棄神人矣。神怒民畔，何以能久？〔五〕趙孟不復年矣！」〔六〕是歲，秦景公弟后子奔晉，〔七〕趙孟問：「秦君何如？」對曰：「無道。」趙孟曰：「亡虖？」對曰：「何為？一世無道，國未艾也。〔八〕國于天地，有與立焉，〔九〕不數世淫，弗能敝也。」趙孟曰：「（天）〔夭〕虖？」對曰：「有焉。」趙孟曰：「其幾何？」〔一０〕對曰：「鍼聞國無道而年穀和孰，天贊之也，鮮不五稔。」〔一一〕趙孟視蔭，曰：「朝夕不相及，誰能待五？」〔一二〕后子出而告人曰：「趙孟將死矣！主民玩歲而愒日，其與幾何？」〔一三〕冬，趙孟卒。昭五年，秦景公卒。","sentenceOrder":267},
  {"id":"s_work_han_thu_34_268","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「周，周景王也。劉定公，周卿也，食邑於劉，名夏。是時，孟與諸侯會於虢，故就而勞之。」","sentenceOrder":268},
  {"id":"s_work_han_thu_34_269","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「時館於洛汭，因見河洛而美禹功，故言之也。弁冕，冠也。言今服冠冕有國家，何不追績禹功，而庇蔭其人乎？」","sentenceOrder":269},
  {"id":"s_work_han_thu_34_270","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「儕，等也。言且得食而已，苟免目前，不能念其長久也。儕音仕皆反。」","sentenceOrder":270},
  {"id":"s_work_han_thu_34_271","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「諺，俗所傳言也。八十曰耄，亂也。言人年老閱歷既多，謂將益智，而又耄亂也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_34_272","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「言其自比賤隸，而無恤下之心，人為神主，故神人皆去也。」","sentenceOrder":272},
  {"id":"s_work_han_thu_34_273","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　師古曰：「謂其即死，不復見明年。」","sentenceOrder":273},
  {"id":"s_work_han_thu_34_274","chapterId":"ch_work_han_thu_34","textTraditional":"〔七〕　師古曰：「后子，即公子鍼。」","sentenceOrder":274},
  {"id":"s_work_han_thu_34_275","chapterId":"ch_work_han_thu_34","textTraditional":"〔八〕　師古曰：「艾讀曰刈。刈，絕也。」","sentenceOrder":275},
  {"id":"s_work_han_thu_34_276","chapterId":"ch_work_han_thu_34","textTraditional":"〔九〕　師古曰：「言在天地之間，多欲輔助，相與共成立之。」","sentenceOrder":276},
  {"id":"s_work_han_thu_34_277","chapterId":"ch_work_han_thu_34","textTraditional":"〔一０〕師古曰：「言當幾時也。音居豈反。」","sentenceOrder":277},
  {"id":"s_work_han_thu_34_278","chapterId":"ch_work_han_thu_34","textTraditional":"〔一一〕師古曰：「贊，佐助之也。鮮，少也。稔，孰也。穀孰為一稔。言少尚當五年，多則或不啻也。稔音人甚反。」","sentenceOrder":278},
  {"id":"s_work_han_thu_34_279","chapterId":"ch_work_han_thu_34","textTraditional":"〔一二〕師古曰：「蔭謂日之蔭影也。趙孟自以年暮，朝不及夕，故言五年不可待也。蔭讀與陰同。」","sentenceOrder":279},
  {"id":"s_work_han_thu_34_280","chapterId":"ch_work_han_thu_34","textTraditional":"〔一三〕師古曰：「玩，愛也。愒，貪也。與幾何，言不能久也。愒音口蓋反。」","sentenceOrder":280},
  {"id":"s_work_han_thu_34_281","chapterId":"ch_work_han_thu_34","textTraditional":"昭公元年，楚公子圍會盟，〔一〕設服離衛。〔二〕魯叔孫穆子曰：「楚公子美矣君哉！」〔三〕伯州犁曰：「此行也，辭而假之寡君。」〔四〕鄭行人子羽曰：「假不反矣。」〔五〕伯州犁曰：「子姑憂子晢之欲背誕也。」〔六〕子羽曰：「假而不反，子其無憂虖？」〔七〕齊國子曰：「吾代二子閔矣。」〔八〕陳公子招曰：「不憂何成？二子樂矣！」衛齊子曰：「苟或知之，雖憂不害。」〔一０〕退會，子羽告人曰：「齊、衛、陳大夫其不免乎！國子代人憂，子招樂憂，齊子雖憂弗害。夫弗及而憂，與可憂而樂，與憂而弗害，皆取憂之道也。〔一一〕太誓曰：『民之所欲，天必從之。』〔一二〕三大夫兆憂矣，能無至乎！〔一三〕言以知物，其是之謂矣。」〔一四〕","sentenceOrder":281},
  {"id":"s_work_han_thu_34_282","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「圍，楚恭王之子也。時為楚令尹，與齊、宋、衛、陳、蔡、鄭會于虢。」","sentenceOrder":282},
  {"id":"s_work_han_thu_34_283","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　張晏曰：「設服者，設人君之服。離衛者，二人執戈在前也。」師古曰：「離列人君之侍衛也。」","sentenceOrder":283},
  {"id":"s_work_han_thu_34_284","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「穆子，叔孫豹也。言其服美似人君也。」","sentenceOrder":284},
  {"id":"s_work_han_thu_34_285","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「伯州犁，楚太宰也。言受楚王之命，假以此禮耳。蓋為其令尹文過。」","sentenceOrder":285},
  {"id":"s_work_han_thu_34_286","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「行人，官名。子羽，公孫揮字也。假不反矣，言將遂為君。」","sentenceOrder":286},
  {"id":"s_work_han_thu_34_287","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　應劭曰：「子晢攻殺伯有，今又背盟，欲復作亂也。」師古曰：「子晢，鄭大夫公孫黑也。背誕者，背命放誕，欲為亂也。子且自憂此，無憂令尹不反戈也。」","sentenceOrder":287},
  {"id":"s_work_han_thu_34_288","chapterId":"ch_work_han_thu_34","textTraditional":"〔七〕　師古曰：「言令尹將圖為君，則楚國有難，子亦有憂也。」","sentenceOrder":288},
  {"id":"s_work_han_thu_34_289","chapterId":"ch_work_han_thu_34","textTraditional":"〔八〕　應劭曰：「閔，憂也。二子，伯州犁，行人子羽也。」師古曰：「國子，齊大夫國弱也。二子，謂王子圍及伯州犁也。圍以是年篡位，而不能令終，州犁亦為圍所殺，故言可閔。應說非也。」","sentenceOrder":289},
  {"id":"s_work_han_thu_34_290","chapterId":"ch_work_han_thu_34","textTraditional":"〔九〕　應劭曰：「言國有憂，己乃得以成功也。」師古曰：「招，陳公子，哀公弟也。言因憂以成事，事成而樂也。招音韶。」","sentenceOrder":290},
  {"id":"s_work_han_thu_34_291","chapterId":"ch_work_han_thu_34","textTraditional":"〔一０〕師古曰：「齊子，衛大夫齊惡也。言先知為備，雖有憂難，無所損害。」","sentenceOrder":291},
  {"id":"s_work_han_thu_34_292","chapterId":"ch_work_han_thu_34","textTraditional":"〔一一〕師古曰：「弗及而憂，謂憂不及己而妄憂也。」","sentenceOrder":292},
  {"id":"s_work_han_thu_34_293","chapterId":"ch_work_han_thu_34","textTraditional":"〔一二〕師古曰：「太誓，周書也。」","sentenceOrder":293},
  {"id":"s_work_han_thu_34_294","chapterId":"ch_work_han_thu_34","textTraditional":"〔一三〕師古曰：「兆憂，謂開憂兆也。」","sentenceOrder":294},
  {"id":"s_work_han_thu_34_295","chapterId":"ch_work_han_thu_34","textTraditional":"〔一四〕師古曰：「物，類也。察其所言，以知禍福之類。」","sentenceOrder":295},
  {"id":"s_work_han_thu_34_296","chapterId":"ch_work_han_thu_34","textTraditional":"昭公十五年，晉籍談如周葬穆后，〔一〕既除喪而燕，〔二〕王曰：「諸侯皆有以填撫王室，晉獨無有，何也？」〔三〕籍談對曰：「諸侯之封也，皆受明器於王室，故能薦彝器。〔四〕晉居深山，戎翟之與鄰，拜戎不暇，其何以獻器？」王曰：「叔氏其忘諸乎！〔五〕叔父唐叔，成王之母弟，其反亡分乎？〔六〕昔而高祖司晉之典籍，〔七〕以為大正，故曰籍氏。女，司典之後也，何故忘之？」籍談不能對。賓出，王曰：「籍父其無後乎！數典而忘其祖。」〔八〕籍談歸，以語叔嚮。叔嚮曰：「王其不終乎！吾聞所樂必卒焉。〔九〕今王樂憂，若卒以憂，不可謂終。王一歲而有三年之喪二焉，〔一０〕於是乎以喪賓燕，又求彝器，樂憂甚矣。三年之喪，雖貴遂服，禮也。〔一一〕王雖弗遂，燕樂已早。〔一二〕禮，王之大經也；一動而失二禮，無大經矣。〔一三〕言以考典，典以志經。〔一四〕忘經而多言舉典，將安用之！」","sentenceOrder":296},
  {"id":"s_work_han_thu_34_297","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「籍談，晉大夫也。穆后，周景王之后諡穆也。」","sentenceOrder":297},
  {"id":"s_work_han_thu_34_298","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「燕與宴同。」","sentenceOrder":298},
  {"id":"s_work_han_thu_34_299","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「填撫王室，謂獻器物也。填音竹刃反。」","sentenceOrder":299},
  {"id":"s_work_han_thu_34_300","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「明器，明德之器也。彝器，常可寶用之器也。」","sentenceOrder":300},
  {"id":"s_work_han_thu_34_301","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「叔，籍談字也。一曰叔父之使，故謂之叔氏也。」","sentenceOrder":301},
  {"id":"s_work_han_thu_34_302","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　師古曰：「分音扶問反。」","sentenceOrder":302},
  {"id":"s_work_han_thu_34_303","chapterId":"ch_work_han_thu_34","textTraditional":"〔七〕　師古曰：「而亦汝。」","sentenceOrder":303},
  {"id":"s_work_han_thu_34_304","chapterId":"ch_work_han_thu_34","textTraditional":"〔八〕　師古曰：「忘祖業。」","sentenceOrder":304},
  {"id":"s_work_han_thu_34_305","chapterId":"ch_work_han_thu_34","textTraditional":"〔九〕　師古曰：「言志之所樂，終於此事。」","sentenceOrder":305},
  {"id":"s_work_han_thu_34_306","chapterId":"ch_work_han_thu_34","textTraditional":"〔一０〕師古曰：「為太子三年，妻死三年乃娶，達子之志。言三年之喪，二后及太子也。」","sentenceOrder":306},
  {"id":"s_work_han_thu_34_307","chapterId":"ch_work_han_thu_34","textTraditional":"〔一一〕師古曰：「遂猶竟。」","sentenceOrder":307},
  {"id":"s_work_han_thu_34_308","chapterId":"ch_work_han_thu_34","textTraditional":"〔一二〕師古曰：「天子除喪，當在卒哭，今適既葬，故譏其早也。」","sentenceOrder":308},
  {"id":"s_work_han_thu_34_309","chapterId":"ch_work_han_thu_34","textTraditional":"〔一三〕師古曰：「經謂常法也。既不遂服，又即宴樂，是失二禮。」","sentenceOrder":309},
  {"id":"s_work_han_thu_34_310","chapterId":"ch_work_han_thu_34","textTraditional":"〔一四〕師古曰：「考，成也。志，記也。」","sentenceOrder":310},
  {"id":"s_work_han_thu_34_311","chapterId":"ch_work_han_thu_34","textTraditional":"哀公十六年，孔丘卒，公誄之曰：「（昊）〔旻〕天不弔，不憖遺一老，俾屏予一人。」〔一〕子贛曰：「君其不歿於魯乎？夫子之言曰：『禮失則昏，名失則愆。』〔二〕失志為昏，失所（謂）〔為〕愆。生弗能用，死而誄之，非禮也；稱『予一人』，非名也。〔三〕君兩失之。」二十七年，公孫于邾，〔四〕遂死於越。〔五〕","sentenceOrder":311},
  {"id":"s_work_han_thu_34_312","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　應劭曰：「憖，且辭也。言（昊）〔旻〕天不善於魯，不且遺一老，使屏蔽我一人也。」師古曰：「憖音魚覲反。」","sentenceOrder":312},
  {"id":"s_work_han_thu_34_313","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「夫子謂孔子也。昏謂惑也。愆，過也。」","sentenceOrder":313},
  {"id":"s_work_han_thu_34_314","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「天子自稱曰『予一人』，非諸侯之號，故云非名。」","sentenceOrder":314},
  {"id":"s_work_han_thu_34_315","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「孫讀曰遜。」","sentenceOrder":315},
  {"id":"s_work_han_thu_34_316","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「已解於上。」","sentenceOrder":316},
  {"id":"s_work_han_thu_34_317","chapterId":"ch_work_han_thu_34","textTraditional":"庶徵之恆陽，劉向以為春秋大旱也。其夏旱雩祀，謂之大雩。不傷二穀，謂之不雨。京房易傳曰：「欲德不用茲謂張，〔一〕厥災荒。荒，旱也，其旱陰雲不雨，變而赤，因而除。師出過時茲謂廣〔二〕，其旱不生。上下皆蔽茲謂隔，其旱天赤三月，時有雹殺飛禽。上緣求妃茲謂僭，〔三〕其旱三月大溫亡雲。居高臺府，茲謂犯陰侵陽，其旱萬物根死，數有火災。庶位踰節茲謂僭，其旱澤物枯，為火所傷。」","sentenceOrder":317},
  {"id":"s_work_han_thu_34_318","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　孟康曰：「欲得賢者而不用，人君徒張此意。」","sentenceOrder":318},
  {"id":"s_work_han_thu_34_319","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　李奇曰：「廣音曠。」韋昭曰：「謂怨曠也。」","sentenceOrder":319},
  {"id":"s_work_han_thu_34_320","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「緣，歷也。言歷眾處而求妃妾也。」","sentenceOrder":320},
  {"id":"s_work_han_thu_34_321","chapterId":"ch_work_han_thu_34","textTraditional":"釐公二十一年「夏，大旱」。董仲舒、劉向以為齊（威）〔桓〕既死，諸侯從楚，釐尤得楚心。楚來獻捷，釋宋之執。〔一〕外倚彊楚，炕陽失眾，又作南門，勞民興役。〔二〕諸雩旱不雨，略皆同說。","sentenceOrder":321},
  {"id":"s_work_han_thu_34_322","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「謂此年楚執宋公以伐宋，冬使宜申來獻捷，十二月盟于薄，釋宋公也。」","sentenceOrder":322},
  {"id":"s_work_han_thu_34_323","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「南門本名稷門，更改高大而作之。事在二十年。」","sentenceOrder":323},
  {"id":"s_work_han_thu_34_324","chapterId":"ch_work_han_thu_34","textTraditional":"宣公七年「秋，大旱」。是夏，宣與齊侯伐萊。〔一〕","sentenceOrder":324},
  {"id":"s_work_han_thu_34_325","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「萊國即東萊黃縣也。」","sentenceOrder":325},
  {"id":"s_work_han_thu_34_326","chapterId":"ch_work_han_thu_34","textTraditional":"襄公五年「秋，大雩」。先是宋魚石奔楚，〔一〕楚伐宋，取彭城以封魚石。〔二〕鄭畔于中國而附楚，〔三〕襄與諸侯共圍彭城，〔四〕城鄭虎牢以禦楚。〔五〕是歲鄭伯使公子發來聘，〔六〕使大夫會吳于善道。〔七〕外結二國，內得鄭聘，有炕陽動眾之應。","sentenceOrder":326},
  {"id":"s_work_han_thu_34_327","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「犇，古奔字也。事在成十五年。魚石，宋左師也，公子目夷之曾孫也。」","sentenceOrder":327},
  {"id":"s_work_han_thu_34_328","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「事在成十八年。」","sentenceOrder":328},
  {"id":"s_work_han_thu_34_329","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「自鄢陵戰後，鄭遂不服，故諸侯屢侵伐之。」","sentenceOrder":329},
  {"id":"s_work_han_thu_34_330","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「謂襄元年使仲孫蔑會晉欒黶、宋華元、衛甯殖、曹人、莒人、邾人、滕人、薛人圍彭城。」","sentenceOrder":330},
  {"id":"s_work_han_thu_34_331","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「事在二年。武牢本鄭邑，時已屬晉，蓋追言之。」","sentenceOrder":331},
  {"id":"s_work_han_thu_34_332","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　師古曰：「公子發，鄭穆公之子，子產之父也，字子國。」","sentenceOrder":332},
  {"id":"s_work_han_thu_34_333","chapterId":"ch_work_han_thu_34","textTraditional":"〔七〕　師古曰：「使仲孫蔑會吳也。善道，地名。」","sentenceOrder":333},
  {"id":"s_work_han_thu_34_334","chapterId":"ch_work_han_thu_34","textTraditional":"八年「九月，大雩」。時作三軍，季氏盛。〔一〕","sentenceOrder":334},
  {"id":"s_work_han_thu_34_335","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「萬二千五百人為軍。魯本立上下二軍，皆屬於公，有事則三卿遞帥之而征伐。今季氏欲專其人，故增立中軍，三卿各主其一也。事在十一年。」","sentenceOrder":335},
  {"id":"s_work_han_thu_34_336","chapterId":"ch_work_han_thu_34","textTraditional":"二十八年「八月，大雩」。先是，比年晉使荀吳、齊使慶封來聘，〔一〕是夏邾子來朝。襄有炕陽自大之應。","sentenceOrder":336},
  {"id":"s_work_han_thu_34_337","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「比年，頻年也。荀吳，晉大夫，即荀偃之子也，二十六年晉侯使來聘。慶封，齊大夫也，二十七年齊侯使來聘。」","sentenceOrder":337},
  {"id":"s_work_han_thu_34_338","chapterId":"ch_work_han_thu_34","textTraditional":"昭公三年「八月，大雩」。劉歆以為昭公即位年十九矣，猶有童心，居喪不哀，炕陽失眾。","sentenceOrder":338},
  {"id":"s_work_han_thu_34_339","chapterId":"ch_work_han_thu_34","textTraditional":"六年「九月，大雩」。先是莒牟夷以二邑來奔，〔一〕莒怒伐魯，叔弓帥師，距而敗之，昭得入晉。〔二〕外和大國，內獲二邑，取勝鄰國，有炕陽動眾之應。","sentenceOrder":339},
  {"id":"s_work_han_thu_34_340","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「事在五年。牟夷，莒大夫也。二邑，謂牟婁及防茲也。」","sentenceOrder":340},
  {"id":"s_work_han_thu_34_341","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「叔弓，魯大夫。時昭公適欲朝晉，而遇莒人來討，將不果行。叔弓既敗莒師，公乃得去。故傳云成禮大國，以為援好也。」","sentenceOrder":341},
  {"id":"s_work_han_thu_34_342","chapterId":"ch_work_han_thu_34","textTraditional":"十六年「九月，大雩」。先是昭公母夫人歸氏薨，昭不慼，又大蒐于比蒲。〔一〕晉叔嚮曰：「魯有大喪而不廢蒐。國不恤喪，不忌君也；君亡慼容，不顧親也。殆其失國。」與三年同占。","sentenceOrder":342},
  {"id":"s_work_han_thu_34_343","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「事在昭十一年。歸氏，胡國之女。歸姓，即齊歸也。齊，諡也。蒐謂聚而眾田獵也。比蒲，魯地名。比音毘。」","sentenceOrder":343},
  {"id":"s_work_han_thu_34_344","chapterId":"ch_work_han_thu_34","textTraditional":"二十四年「八月，大雩」。劉歆以為左氏傳二十三年邾師城翼，還經魯地，〔一〕魯襲取邾師，獲其三大夫。〔二〕邾人愬于晉，晉人執我行人叔孫婼，〔三〕是春乃歸之。","sentenceOrder":344},
  {"id":"s_work_han_thu_34_345","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「翼，邾邑也。經者，道出其中也。魯地，謂武城也。」","sentenceOrder":345},
  {"id":"s_work_han_thu_34_346","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「謂徐鉏、丘弱、茅地也。」","sentenceOrder":346},
  {"id":"s_work_han_thu_34_347","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「叔孫昭子也。婼音丑略反。」","sentenceOrder":347},
  {"id":"s_work_han_thu_34_348","chapterId":"ch_work_han_thu_34","textTraditional":"二十五年「七月上辛大雩，季辛又雩」，旱甚也。劉歆以為時后氏與季氏有隙。〔一〕又季氏之族有淫妻為讒，使季平子與族人相惡，皆共譖平子。〔二〕子家駒諫曰：「讒人以君徼幸，不可。」〔三〕昭公遂伐季氏，為所敗，出奔齊。","sentenceOrder":348},
  {"id":"s_work_han_thu_34_349","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「后氏，郈昭伯也。季氏，季平子也。季、郈之雞鬥，季氏芥其雞，郈子為之金距。平子怒，益宮於郈氏，且責讓之，故郈昭伯怨之。」","sentenceOrder":349},
  {"id":"s_work_han_thu_34_350","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「謂平子庶叔父公鳥之妻季姒與雍人檀通，而譖季氏之族人季公亥、公思展，故平子殺思展，以故族人皆怨之。」","sentenceOrder":350},
  {"id":"s_work_han_thu_34_351","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「子家駒即子家懿伯，莊公之玄孫也，一名羈。」","sentenceOrder":351},
  {"id":"s_work_han_thu_34_352","chapterId":"ch_work_han_thu_34","textTraditional":"定公（十）〔七〕年「九月，大雩」。先是定公自將侵鄭，歸而城中城。二大夫帥師圍鄆。〔一〕","sentenceOrder":352},
  {"id":"s_work_han_thu_34_353","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「事並在六年。中城，魯之邑也。二大夫謂季孫斯、仲孫何忌。」","sentenceOrder":353},
  {"id":"s_work_han_thu_34_354","chapterId":"ch_work_han_thu_34","textTraditional":"嚴公三十一年「冬，不雨」。是歲，一年而三築臺，〔一〕奢侈不恤民。","sentenceOrder":354},
  {"id":"s_work_han_thu_34_355","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「是年春築臺于郎，夏築臺于薛，秋築臺于秦。秦、郎、薛，皆魯地。」","sentenceOrder":355},
  {"id":"s_work_han_thu_34_356","chapterId":"ch_work_han_thu_34","textTraditional":"釐公二年「冬十月不雨」，三年「春正月不雨，夏四月不雨」，「六月雨」。先是者，嚴公夫人與公子慶父淫，而殺二君。〔一〕國人攻之，夫人遜于邾，慶父奔莒。釐公即位，南敗邾，〔二〕東敗莒，獲其大夫。〔三〕有炕陽之應。","sentenceOrder":356},
  {"id":"s_work_han_thu_34_357","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「慶公，桓公之子，莊公弟也。二君，謂子般及閔公。」","sentenceOrder":357},
  {"id":"s_work_han_thu_34_358","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「謂元年公敗邾師于偃。」","sentenceOrder":358},
  {"id":"s_work_han_thu_34_359","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「謂元年公子友帥師敗莒師于酈，獲莒挐也。」","sentenceOrder":359},
  {"id":"s_work_han_thu_34_360","chapterId":"ch_work_han_thu_34","textTraditional":"文公二年，「自十有二月不雨，至于秋七月」。文公即位，天子使叔服會葬，〔一〕毛伯賜命。〔二〕又會晉侯于戚。〔三〕公子遂如齊納幣。〔四〕又與諸侯盟。〔五〕上得天子，外得諸侯，沛然自大。〔六〕躋釐公主。大夫始顓事。〔七〕","sentenceOrder":360},
  {"id":"s_work_han_thu_34_361","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「叔服，周之內史也，叔氏，服字。會葬，葬僖公。」","sentenceOrder":361},
  {"id":"s_work_han_thu_34_362","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「亦天子使之也。毛伯，周之卿士。毛，國；伯，爵也。賜命者，賜以命圭為瑞信也。」","sentenceOrder":362},
  {"id":"s_work_han_thu_34_363","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「謂大夫公孫敖會之也。戚，衛邑，在頓丘衛縣西。」","sentenceOrder":363},
  {"id":"s_work_han_thu_34_364","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「納玄纁之幣，謂公為婚於齊。」","sentenceOrder":364},
  {"id":"s_work_han_thu_34_365","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「謂公孫敖會宋公、陳侯、鄭伯、晉士縠盟于垂隴也。垂隴，鄭地。」","sentenceOrder":365},
  {"id":"s_work_han_thu_34_366","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　師古曰：「沛音普大反。」","sentenceOrder":366},
  {"id":"s_work_han_thu_34_367","chapterId":"ch_work_han_thu_34","textTraditional":"〔七〕　師古曰：「謂季孫行父也。顓讀與專同。」","sentenceOrder":367},
  {"id":"s_work_han_thu_34_368","chapterId":"ch_work_han_thu_34","textTraditional":"十年，「自正月不雨，至于秋七月」。先是公子遂會四國而救鄭。〔一〕楚使越椒來聘。〔二〕秦人歸襚。〔三〕有炕陽之應。","sentenceOrder":368},
  {"id":"s_work_han_thu_34_369","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「謂九年楚人伐鄭，公子遂會晉人、宋人、衛人、許人以救之。」","sentenceOrder":369},
  {"id":"s_work_han_thu_34_370","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「越椒，楚大夫名也。事亦在九年。」","sentenceOrder":370},
  {"id":"s_work_han_thu_34_371","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「謂九年秦人來歸僖公及成風之襚也。凡問喪者，衣服曰襚。成風，僖公之母也。成，諡也。風，姓也。襚音遂。」","sentenceOrder":371},
  {"id":"s_work_han_thu_34_372","chapterId":"ch_work_han_thu_34","textTraditional":"十三年，「自正月不雨，至于秋七月」。先是曹伯、杞伯、滕子來朝，〔一〕郕伯來奔，〔二〕秦伯使遂來聘，〔三〕季孫行父城諸及鄆。〔四〕二年之間，五國趨之，內城二邑。炕陽失眾。一曰，不雨而五穀皆孰，異也。文公時，大夫始顓盟會，公孫敖會晉侯，又會諸侯盟于垂隴。故不雨而生者，陰不出氣而私自行，以象施不由上出，臣下作福而私自成。一曰，不雨近常陰之罰，君弱也。","sentenceOrder":372},
  {"id":"s_work_han_thu_34_373","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「十一年曹伯來朝，十二年杞伯、滕子來朝。」","sentenceOrder":373},
  {"id":"s_work_han_thu_34_374","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「事在十二年。郕，國；伯，爵也。」","sentenceOrder":374},
  {"id":"s_work_han_thu_34_375","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「事在十二年。遂，秦大夫名，即左氏所謂西乞術。」","sentenceOrder":375},
  {"id":"s_work_han_thu_34_376","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「事在十二年。諸、鄆，二邑名也。諸即琅邪諸縣也。」","sentenceOrder":376},
  {"id":"s_work_han_thu_34_377","chapterId":"ch_work_han_thu_34","textTraditional":"惠帝五年夏，大旱，江河水少，谿谷絕。先是發民男女十四萬六千人城長安，是歲城乃成。","sentenceOrder":377},
  {"id":"s_work_han_thu_34_378","chapterId":"ch_work_han_thu_34","textTraditional":"文帝三年秋，天下旱。是歲夏，匈奴右賢王寇侵上郡，詔丞相灌嬰發車騎士八萬五千人詣高奴，〔一〕擊右賢王走出塞。其秋，濟北王興居反，使大將軍討之，皆伏誅。","sentenceOrder":378},
  {"id":"s_work_han_thu_34_379","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「即上郡之縣。」","sentenceOrder":379},
  {"id":"s_work_han_thu_34_380","chapterId":"ch_work_han_thu_34","textTraditional":"後六年春，天下大旱。先是發車騎材官屯廣昌，〔一〕是歲二月復發材官屯隴西。後匈奴大入上郡、雲中，烽火通長安，三將軍屯邊，〔二〕又三將軍屯京師。〔三〕","sentenceOrder":380},
  {"id":"s_work_han_thu_34_381","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「武都之縣。」","sentenceOrder":381},
  {"id":"s_work_han_thu_34_382","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「謂以中大夫令免為車騎將軍屯飛狐，故楚相蘇意為將軍屯句注，將軍張武屯北地。」","sentenceOrder":382},
  {"id":"s_work_han_thu_34_383","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「謂河內太守周亞夫為將軍次細柳，宗正劉禮為將軍次霸上，祝茲侯徐厲為將軍次棘門。」","sentenceOrder":383},
  {"id":"s_work_han_thu_34_384","chapterId":"ch_work_han_thu_34","textTraditional":"景帝中三年秋，大旱。","sentenceOrder":384},
  {"id":"s_work_han_thu_34_385","chapterId":"ch_work_han_thu_34","textTraditional":"武帝元光六年夏，大旱。是歲，四將軍征匈奴。〔一〕","sentenceOrder":385},
  {"id":"s_work_han_thu_34_386","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「謂車騎將軍衛青出上谷，騎將軍公孫敖出代，輕車將軍公孫賀出雲中，驍騎將軍李廣出鴈門。」","sentenceOrder":386},
  {"id":"s_work_han_thu_34_387","chapterId":"ch_work_han_thu_34","textTraditional":"元朔五年春，大旱。是歲，六將軍眾十餘萬征匈奴。〔一〕","sentenceOrder":387},
  {"id":"s_work_han_thu_34_388","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「謂衛青將六將軍兵也。六將軍者，衛尉蘇建為游擊將軍，左內史李沮為彊弩將軍，大僕公孫賀為騎將軍，代相李蔡為輕車將軍，俱出朔方；大行李息、岸頭侯張次公為將軍，出右北平。」","sentenceOrder":388},
  {"id":"s_work_han_thu_34_389","chapterId":"ch_work_han_thu_34","textTraditional":"元狩三年夏，大旱。是歲發天下故吏伐棘上林，穿昆明池。","sentenceOrder":389},
  {"id":"s_work_han_thu_34_390","chapterId":"ch_work_han_thu_34","textTraditional":"天漢元年夏，大旱；其三年夏，大旱。先是貳師將軍征大宛還。天漢元年，發適民。〔一〕二年夏，三將軍征匈奴，〔二〕李陵沒不還。","sentenceOrder":390},
  {"id":"s_work_han_thu_34_391","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「適讀曰謫。」","sentenceOrder":391},
  {"id":"s_work_han_thu_34_392","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「謂貳師將軍三萬騎出酒泉，因杅將軍出西河，騎都尉李陵將步兵五千人出居延北也。」","sentenceOrder":392},
  {"id":"s_work_han_thu_34_393","chapterId":"ch_work_han_thu_34","textTraditional":"征和元年夏，大旱。是歲發三輔騎士閉長安城門，大搜，始治巫蠱。明年，衛皇后、太子敗。","sentenceOrder":393},
  {"id":"s_work_han_thu_34_394","chapterId":"ch_work_han_thu_34","textTraditional":"昭帝始元六年，大旱。先是大鴻臚田廣明征益州，暴師連年。","sentenceOrder":394},
  {"id":"s_work_han_thu_34_395","chapterId":"ch_work_han_thu_34","textTraditional":"宣帝本始三年夏，大旱，東西數千里。先是五將軍眾二十萬征匈奴。〔一〕","sentenceOrder":395},
  {"id":"s_work_han_thu_34_396","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「本始三年，御史大夫田廣明為祁連將軍，後將軍趙充國為蒲類將軍，雲中太守田順為武牙將軍，及渡遼將軍范明友、前將軍韓增，凡五將軍，兵十五萬騎。校尉常惠持節護烏孫兵，咸擊匈奴，是為二十萬眾也。」","sentenceOrder":396},
  {"id":"s_work_han_thu_34_397","chapterId":"ch_work_han_thu_34","textTraditional":"神爵元年秋，大旱。是歲，後將軍趙充國征西羌。","sentenceOrder":397},
  {"id":"s_work_han_thu_34_398","chapterId":"ch_work_han_thu_34","textTraditional":"成帝永始三年、四年夏，大旱。","sentenceOrder":398},
  {"id":"s_work_han_thu_34_399","chapterId":"ch_work_han_thu_34","textTraditional":"左氏傳晉獻公時童謠曰：「丙〔子〕之晨，龍尾伏辰，袀服振振，取虢之旂。〔一〕鶉之賁賁，天策焞焞，火中成軍，虢公其奔。」〔二〕是時虢為小國，介夏陽之阨，怙虞國之助，〔三〕亢衡于晉，有炕陽之節，失臣下之心。晉獻伐之，問於卜偃曰：「吾其濟乎？」〔四〕偃以童謠對曰：「克之。十月朔丙子旦，日在尾，月在策，鶉火中，必此時也。」冬十二月丙子朔，晉師滅虢，虢公醜奔周。周十二月，夏十月也。言天者以夏正。","sentenceOrder":399},
  {"id":"s_work_han_thu_34_400","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「徒歌曰謠。袀服，黑衣。振振，袀服之貌也。袀音（勻）〔均〕，又音弋春反。振音只人反。」","sentenceOrder":400},
  {"id":"s_work_han_thu_34_401","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「（犇）〔賁〕音奔。焞音吐敦反，又音敦。犇，古奔字。」","sentenceOrder":401},
  {"id":"s_work_han_thu_34_402","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「介，隔也。」","sentenceOrder":402},
  {"id":"s_work_han_thu_34_403","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「卜偃，晉大夫主卜者。」","sentenceOrder":403},
  {"id":"s_work_han_thu_34_404","chapterId":"ch_work_han_thu_34","textTraditional":"史記晉惠公時童謠曰：「恭太子更葬兮，後十四年，晉亦不昌，昌乃在其兄。」是時，惠公賴秦力得立，立而背秦，內殺二大夫〔一〕，國人不說。〔二〕及更葬其兄恭太子申生而不敬，故詩妖作也。後與秦戰，為秦所獲，立十四年而死。晉人絕之，更立其兄重耳，是為文公，遂伯諸侯。〔三〕","sentenceOrder":404},
  {"id":"s_work_han_thu_34_405","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「謂里克、丕鄭。」","sentenceOrder":405},
  {"id":"s_work_han_thu_34_406","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":406},
  {"id":"s_work_han_thu_34_407","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「伯讀曰霸。」","sentenceOrder":407},
  {"id":"s_work_han_thu_34_408","chapterId":"ch_work_han_thu_34","textTraditional":"左氏傳文、成之世童謠曰：「鴝之鵒之，公出辱之。〔一〕鴝鵒之羽，公在外野，往饋之馬。〔二〕鴝鵒跦跦，公在乾侯，〔三〕徵褰與襦。〔四〕鴝鵒之巢，遠哉搖搖，〔五〕裯父喪勞，宋父以驕。〔六〕鴝鵒鴝鵒，往歌來哭。」〔七〕至昭公時，有鴝鵒來巢。公攻季氏，敗，出奔齊，居外野，次乾侯。八年，死于外，歸葬魯。昭公名裯。公子宋立，是為定公。","sentenceOrder":408},
  {"id":"s_work_han_thu_34_409","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「鴝音劬。鵒音欲。」","sentenceOrder":409},
  {"id":"s_work_han_thu_34_410","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「饋亦餽字。」","sentenceOrder":410},
  {"id":"s_work_han_thu_34_411","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　臣瓚曰：「乾侯，在魏郡斥丘縣。」師古曰：「跦跦，跳行貌也。跦音誅。乾音干。」","sentenceOrder":411},
  {"id":"s_work_han_thu_34_412","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「徵，求也。褰，袴也。言公出外求袴襦之服。」","sentenceOrder":412},
  {"id":"s_work_han_thu_34_413","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「搖搖，不安之貌。」","sentenceOrder":413},
  {"id":"s_work_han_thu_34_414","chapterId":"ch_work_han_thu_34","textTraditional":"〔六〕　師古曰：「父讀曰甫。甫者，男子之通號，故云裯甫、宋甫也。言昭公欲去季氏，不遂而出，故曰喪勞。定公無德於下，坐致君位，故曰以驕。」","sentenceOrder":414},
  {"id":"s_work_han_thu_34_415","chapterId":"ch_work_han_thu_34","textTraditional":"〔七〕　師古曰：「謂昭公生時出奔，死乃以喪歸之。」","sentenceOrder":415},
  {"id":"s_work_han_thu_34_416","chapterId":"ch_work_han_thu_34","textTraditional":"元帝時童謠曰：「井水溢，滅灶煙，灌玉堂，流金門。」至成帝建始二年三月戊子，北宮中井泉稍上，溢出南流，象春秋時先有鴝鵒之謠，而後有來巢之驗。井水，陰也；灶煙，陽也；玉堂、金門，至尊之居：象陰盛而滅陽，竊有宮室之應也。王莽生於元帝初元四年，至成帝封侯，為三公輔政，因以篡位。","sentenceOrder":416},
  {"id":"s_work_han_thu_34_417","chapterId":"ch_work_han_thu_34","textTraditional":"成帝時童謠曰：「燕燕尾涎涎，〔一〕張公子，時相見。木門倉琅根，燕飛來，啄皇孫，皇孫死，燕啄矢。」其後帝為微行出遊，常與富平侯張放俱稱富平侯家人，過（河陽）〔陽阿〕主作樂，見舞者趙飛燕而幸之，故曰「燕燕尾涎涎」，美好貌也。張公子謂富平侯也。「木門倉琅根」，謂宮門銅鍰，〔二〕言將尊貴也。後遂立為皇后。弟昭儀賊害後宮皇子，卒皆伏辜，所謂「燕飛來，啄皇孫，皇孫死，燕啄矢」者也。","sentenceOrder":417},
  {"id":"s_work_han_thu_34_418","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「涎涎，光澤貌也，音徒見反。」","sentenceOrder":418},
  {"id":"s_work_han_thu_34_419","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「門之鋪首及銅鍰也。銅色青，故曰倉琅。鋪首銜環，故謂之根。鍰讀與環同。」","sentenceOrder":419},
  {"id":"s_work_han_thu_34_420","chapterId":"ch_work_han_thu_34","textTraditional":"成帝時歌謠又曰：「邪徑敗良田，讒口亂善人。桂樹華不實，黃爵巢其顛。故為人所羨，今為人所憐。」桂，赤色，漢家象。華不實，無繼嗣也。王莽自謂黃象，黃爵巢其顛也。","sentenceOrder":420},
  {"id":"s_work_han_thu_34_421","chapterId":"ch_work_han_thu_34","textTraditional":"嚴公十七年「冬，多麋」。劉歆以為毛蟲之孽為災。劉向以為麋色青，近青祥也。麋之為言迷也，蓋牝獸之淫者也。是時，嚴公將取齊之淫女，其象先見，天戒若曰，勿取齊女，淫而迷國。嚴不寤，遂取之。夫人既入，淫於二叔，終皆誅死，〔一〕幾亡社稷。〔二〕董仲舒指略同。京房易傳曰：「廢正作淫，大不明，國多麋。」又曰：「震遂泥，〔三〕厥咎國多麋。」","sentenceOrder":421},
  {"id":"s_work_han_thu_34_422","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「謂慶父縊死，叔牙鴆卒，齊人殺哀姜也。」","sentenceOrder":422},
  {"id":"s_work_han_thu_34_423","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「謂子般、閔公前後見殺，而齊侯欲取魯國也。幾音鉅依反。」","sentenceOrder":423},
  {"id":"s_work_han_thu_34_424","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　李奇曰：「從三至五，有坎象。坎為水，四為泥在水中，故曰震遂泥。泥者，泥溺於水，不能自拔，道未光也。或以為溺於淫女，故其妖多麋。麋，迷也。」師古曰：「此易震卦九四爻辭也。泥音乃計反。」","sentenceOrder":424},
  {"id":"s_work_han_thu_34_425","chapterId":"ch_work_han_thu_34","textTraditional":"昭帝時，昌邑王賀聞人聲曰「熊」，視而見大熊。左右莫見，以問郎中令龔遂，遂曰：「熊，山野之獸，而來入宮室，王獨見之，此天戒大王，恐宮室將空，危亡象也。」賀不改寤，後卒失國。","sentenceOrder":425},
  {"id":"s_work_han_thu_34_426","chapterId":"ch_work_han_thu_34","textTraditional":"左氏傳襄公十七年十一月甲午，宋國人逐狾狗，〔一〕狾狗入於華臣氏，〔二〕國人從之。臣懼，遂奔陳。先是臣兄閱為宋卿，〔三〕閱卒，臣使賊殺閱家宰，遂就其妻。宋平公聞之，曰：「臣不唯其宗室是暴，大亂宋國之政。」欲逐之。左師向戌曰：「大臣不順，國之恥也，不如蓋之。」〔四〕公乃止。華臣炕暴失義，內不自安，故犬禍至，以奔亡也。","sentenceOrder":426},
  {"id":"s_work_han_thu_34_427","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「狾，狂也，音征例反。」","sentenceOrder":427},
  {"id":"s_work_han_thu_34_428","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「華臣，華元之子也。」","sentenceOrder":428},
  {"id":"s_work_han_thu_34_429","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「為右師。」","sentenceOrder":429},
  {"id":"s_work_han_thu_34_430","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「向戌，宋桓公曾孫也。蓋謂覆掩其事也。」","sentenceOrder":430},
  {"id":"s_work_han_thu_34_431","chapterId":"ch_work_han_thu_34","textTraditional":"高后八年三月，祓霸上，〔一〕還過枳道，見物如倉狗，橶高后掖，〔二〕忽而不見。卜之，趙王如意為祟。遂病掖傷而崩。先是高后鴆殺如意，支斷其母戚夫人手足，搉其（服）〔眼〕以為人彘〔三〕。","sentenceOrder":431},
  {"id":"s_work_han_thu_34_432","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「祓者，除惡之祭也，音廢。」","sentenceOrder":432},
  {"id":"s_work_han_thu_34_433","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「橶謂拘持之也。橶音戟。拘音居足反。」","sentenceOrder":433},
  {"id":"s_work_han_thu_34_434","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「搉謂敲擊去其精也。搉音口角反。凡言彘者，皆豕之別名。」","sentenceOrder":434},
  {"id":"s_work_han_thu_34_435","chapterId":"ch_work_han_thu_34","textTraditional":"文帝後五年六月，齊雍城門外有狗生角。〔一〕先是帝兄齊悼惠王亡後，帝分齊地，立其庶子七人皆為王。〔二〕兄弟並彊，有炕陽心，故犬禍見也。犬守御，角兵象，在前而上鄉者也。〔三〕犬不當生角，猶諸侯不當舉兵鄉京師也。天之戒人蚤矣，〔四〕諸侯不寤。後六年，吳、楚畔，濟南、膠西、膠東三國應之，舉兵至齊。齊王猶與城守，〔五〕三國圍之。會漢破吳、楚，因誅四王。故天狗下梁而吳、楚攻梁，狗生角於齊而三國圍齊。漢卒破吳、楚於梁，誅四王於齊。京房易傳曰：「執政失，下將害之，厥妖狗生角。君子苟免，小人陷之，厥妖狗生角。」","sentenceOrder":435},
  {"id":"s_work_han_thu_34_436","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「雍城門者，齊門名也。春秋左氏傳平陽之役，趙武及秦周伐雍門之（荻）〔萩〕是也。」","sentenceOrder":436},
  {"id":"s_work_han_thu_34_437","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「謂齊孝王將閭、濟北王志、菑川王賢、膠東王雄渠、膠西王卬、濟南王辟光，并城陽恭王喜，是謂七王。」","sentenceOrder":437},
  {"id":"s_work_han_thu_34_438","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「鄉讀曰嚮。次下亦同。」","sentenceOrder":438},
  {"id":"s_work_han_thu_34_439","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「蚤，古早字。」","sentenceOrder":439},
  {"id":"s_work_han_thu_34_440","chapterId":"ch_work_han_thu_34","textTraditional":"〔五〕　師古曰：「與讀曰豫。」","sentenceOrder":440},
  {"id":"s_work_han_thu_34_441","chapterId":"ch_work_han_thu_34","textTraditional":"景帝三年二月，邯鄲狗與彘交。悖亂之氣，近犬豕之禍也。〔一〕是時趙王遂悖亂，與吳、楚謀為逆，遣使匈奴求助兵，卒伏其辜。犬，兵革失眾之占；〔二〕豕，北方匈奴之象。逆言失聽，交於異類，以生害也。京房易傳曰：「夫婦不嚴，厥妖狗與豕交。茲謂反德，國有兵革。」","sentenceOrder":441},
  {"id":"s_work_han_thu_34_442","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「悖，惑也，音布內反。此下亦同。」","sentenceOrder":442},
  {"id":"s_work_han_thu_34_443","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　如淳曰：「犬吠守，似兵革外附它類，失眾也。」","sentenceOrder":443},
  {"id":"s_work_han_thu_34_444","chapterId":"ch_work_han_thu_34","textTraditional":"成帝河平元年，長安男子石良、劉音相與同居，〔一〕有如人狀在其室中，擊之，為狗，走出。去後有數人被甲持兵弩至良家，良等格擊，或死或傷，皆狗也。自二月至六月乃止。","sentenceOrder":444},
  {"id":"s_work_han_thu_34_445","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「二人共止一室。」","sentenceOrder":445},
  {"id":"s_work_han_thu_34_446","chapterId":"ch_work_han_thu_34","textTraditional":"鴻嘉中，狗與彘交。","sentenceOrder":446},
  {"id":"s_work_han_thu_34_447","chapterId":"ch_work_han_thu_34","textTraditional":"左氏昭公二十四年十月癸酉，王子晁以成周之寶圭湛于河，〔一〕幾以獲神助。〔二〕甲戌，津人得之河上，陰不佞取將賣之，則為石。〔三〕是時王子晁篡天子位，萬民不鄉，號令不從，〔四〕故有玉變，近白祥也。癸酉入而甲戌出，神不享之驗云。玉化為石，貴將為賤也。後二年，子晁奔楚而死。","sentenceOrder":447},
  {"id":"s_work_han_thu_34_448","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「以祭河也。爾雅曰：『祭川曰浮沈。』湛讀曰沈。後皆類此。」","sentenceOrder":448},
  {"id":"s_work_han_thu_34_449","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「幾讀曰冀。」","sentenceOrder":449},
  {"id":"s_work_han_thu_34_450","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　師古曰：「陰不佞，周大夫也。」","sentenceOrder":450},
  {"id":"s_work_han_thu_34_451","chapterId":"ch_work_han_thu_34","textTraditional":"〔四〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":451},
  {"id":"s_work_han_thu_34_452","chapterId":"ch_work_han_thu_34","textTraditional":"史記秦始皇帝三十六年，鄭客從關東來，至華陰，望見素車白馬從華山上下，知其非人，道住止而待之。遂至，〔一〕持璧與客曰：「為我遺鎬池君。」〔二〕因言「今年祖龍死」。〔三〕忽不見。鄭客奉璧，即始皇二十八年過江所湛璧也。與周子晁同應。是歲，石隕于東郡，民或刻其石曰：「始皇死而地分。」此皆白祥，炕陽暴虐，號令不從，孤陽獨治，群陰不附之所致也。一曰，石，陰類也，陰持高節，臣將危君，趙高、李斯之象也。始皇不畏戒自省，反夷滅其旁民，而燔燒其石。是歲始皇死，後三年而秦滅。","sentenceOrder":452},
  {"id":"s_work_han_thu_34_453","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「於道上住而待此車馬。」","sentenceOrder":453},
  {"id":"s_work_han_thu_34_454","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　張晏曰：「武王居鎬，鎬池君則武王也。武王伐商，故神云始皇荒淫若紂矣，今亦可伐也。」孟康曰：「長安西南有鎬池。」師古曰：「鎬池在昆明池北。此直江神告鎬池之神，云始皇將死耳，無豫於武王也。張說失矣。」","sentenceOrder":454},
  {"id":"s_work_han_thu_34_455","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　蘇林曰：「祖，始也。龍，人君象。謂始皇也。」","sentenceOrder":455},
  {"id":"s_work_han_thu_34_456","chapterId":"ch_work_han_thu_34","textTraditional":"孝昭元鳳三年正月，泰山萊蕪山南匈匈有數千人聲。民視之，有大石自立，高丈五尺，大四十八圍，入地深八尺，三石為足。石立處，有白烏數千集其旁。眭孟以為石陰類，下民象，泰山岱宗之嶽，王者易姓告代之處，當有庶人為天子者。孟坐伏誅。京房易傳曰：「『復，崩來無咎。』〔一〕自上下者為崩，厥應泰山之石顛而下，〔二〕聖人受命人君虜。」又曰：「石立如人，庶士為天下雄。立於山，同姓；平地，異姓。立於水，聖人；於澤，小人。」","sentenceOrder":456},
  {"id":"s_work_han_thu_34_457","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「復卦之辭也。今易崩字作朋也。」","sentenceOrder":457},
  {"id":"s_work_han_thu_34_458","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　師古曰：「顛，墜也。」","sentenceOrder":458},
  {"id":"s_work_han_thu_34_459","chapterId":"ch_work_han_thu_34","textTraditional":"天漢元年三月，天雨白毛；三年八月，天雨白氂。〔一〕京房易傳曰：「前樂後憂，厥妖天雨羽。」又曰：「邪人進，賢人逃，天雨毛。」","sentenceOrder":459},
  {"id":"s_work_han_thu_34_460","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　師古曰：「凡言氂者，毛之強曲者也，音力之反。」","sentenceOrder":460},
  {"id":"s_work_han_thu_34_461","chapterId":"ch_work_han_thu_34","textTraditional":"史記周威烈王二十三年，九鼎震。〔一〕金震，木動之也。是時周室衰微，刑重而虐，號令不從，以亂金氣。鼎者，宗廟之寶器也。宗廟將廢，寶鼎將遷，故震動也。是歲晉三卿韓、魏、趙篡晉君而分其地，威烈王命以為諸侯。天子不恤同姓，而爵其賊臣，天下不附矣。後三世，周致德祚於秦。〔二〕其後秦遂滅周，而取九鼎。九鼎之震，木沴金，失眾甚。","sentenceOrder":461},
  {"id":"s_work_han_thu_34_462","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　孟康曰：「威烈，一王之諡也，六國時也。」師古曰：「即赧王之高祖也。」","sentenceOrder":462},
  {"id":"s_work_han_thu_34_463","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　晉灼曰：「赧王奔秦，獻其邑，此謂致德祚也。」","sentenceOrder":463},
  {"id":"s_work_han_thu_34_464","chapterId":"ch_work_han_thu_34","textTraditional":"成帝元延元年正月，長安章城門門牡自亡，〔一〕函谷關次門牡亦自亡。〔二〕京房易傳曰：「飢而不損茲謂泰，厥災水，厥咎牡亡。」妖辭曰：「關動牡飛，辟為亡道臣為非，厥咎亂臣謀篡。」〔三〕故谷永對曰：「章城門通路寢之路，函谷關距山東之險，城門關守國之固，固將去焉，故牡飛也。」","sentenceOrder":464},
  {"id":"s_work_han_thu_34_465","chapterId":"ch_work_han_thu_34","textTraditional":"〔一〕　晉灼曰：「西出南頭第一門也。牡是出籥者。」師古曰：「牡所以下閉者也，亦以鐵為之，非出籥也。」","sentenceOrder":465},
  {"id":"s_work_han_thu_34_466","chapterId":"ch_work_han_thu_34","textTraditional":"〔二〕　韋昭曰：「函谷關邊小門也。」師古曰：「非行人出入所由，蓋關司曹府所在之門也。」","sentenceOrder":466},
  {"id":"s_work_han_thu_34_467","chapterId":"ch_work_han_thu_34","textTraditional":"〔三〕　李奇曰：「易妖變傳辭。」","sentenceOrder":467},
  {"id":"s_work_han_thu_34_468","chapterId":"ch_work_han_thu_34","textTraditional":"校勘記","sentenceOrder":468},
  {"id":"s_work_han_thu_34_469","chapterId":"ch_work_han_thu_34","textTraditional":"一三五二頁　九行　唯金沴（水）〔木〕。　景祐、殿本都作「木」。朱一新說作「木」是。","sentenceOrder":469},
  {"id":"s_work_han_thu_34_470","chapterId":"ch_work_han_thu_34","textTraditional":"一三五六頁　五行　左氏（使）〔傳〕桓公十三年，　景祐、殿、局本都作「傳」，此誤。","sentenceOrder":470},
  {"id":"s_work_han_thu_34_471","chapterId":"ch_work_han_thu_34","textTraditional":"一三五七頁一０行　成肅公受（賑）〔脤〕于社，　景祐、殿本都作「脤」，此誤，局本亦誤。","sentenceOrder":471},
  {"id":"s_work_han_thu_34_472","chapterId":"ch_work_han_thu_34","textTraditional":"一三六四頁一三行　勸殺（威）〔桓〕公，　景祐、殿本都作「桓」。","sentenceOrder":472},
  {"id":"s_work_han_thu_34_473","chapterId":"ch_work_han_thu_34","textTraditional":"一三六五頁　九行　徵，（澄）〔證〕也。　景祐、殿、局本都作「證」。朱一新說作「證」是。","sentenceOrder":473},
  {"id":"s_work_han_thu_34_474","chapterId":"ch_work_han_thu_34","textTraditional":"一三六六頁　三行　猶（玦）〔決〕去，不反意也。　景祐、殿本都作「決」。王先謙說作「決」是。","sentenceOrder":474},
  {"id":"s_work_han_thu_34_475","chapterId":"ch_work_han_thu_34","textTraditional":"一三六六頁一三行　鄭公子士〔洩〕　殿本有「洩」字。朱一新說有「洩」字是。按景祐本無，楊樹達以為不當有。","sentenceOrder":475},
  {"id":"s_work_han_thu_34_476","chapterId":"ch_work_han_thu_34","textTraditional":"一三六七頁　九行　高九（尺）〔寸〕，景祐、殿本都作「寸」。朱一新說作「寸」是。","sentenceOrder":476},
  {"id":"s_work_han_thu_34_477","chapterId":"ch_work_han_thu_34","textTraditional":"一三六九頁　五行　史（囂）〔嚚〕　殿本作「嚚」。王先謙說作「嚚」是。","sentenceOrder":477},
  {"id":"s_work_han_thu_34_478","chapterId":"ch_work_han_thu_34","textTraditional":"一三六九頁一四行　（反）〔及〕後為悼王。　景祐、殿本都作「及」。　朱一新說「反」「及」均誤，當作「也」。","sentenceOrder":478},
  {"id":"s_work_han_thu_34_479","chapterId":"ch_work_han_thu_34","textTraditional":"一三七三頁一四行　（無）〔亡〕儀，無禮儀也。　景祐、殿本都作「亡」。王先謙說作「亡」是。","sentenceOrder":479},
  {"id":"s_work_han_thu_34_480","chapterId":"ch_work_han_thu_34","textTraditional":"一三七五頁一一行　（二）〔一一〕而祭之。致謂（外）〔升〕其主於廟。　朱一新說汪本「二」作「一一」，「外」作「升」，是。按景祐、殿本同汪本。","sentenceOrder":480},
  {"id":"s_work_han_thu_34_481","chapterId":"ch_work_han_thu_34","textTraditional":"一三七七頁一三行　（二）〔三〕卿而五大夫，　景祐本作「三」。朱一新說作「三」是。","sentenceOrder":481},
  {"id":"s_work_han_thu_34_482","chapterId":"ch_work_han_thu_34","textTraditional":"一三八一頁　六行　（天）〔夭〕虖？　王念孫說當從景祐本作「夭」，下文「其幾何」正承「夭」字言之。","sentenceOrder":482},
  {"id":"s_work_han_thu_34_483","chapterId":"ch_work_han_thu_34","textTraditional":"一三八五頁　六行　（昊）〔旻〕天不弔，　景祐、殿本都作「旻」，注同。按左傳作「旻」。","sentenceOrder":483},
  {"id":"s_work_han_thu_34_484","chapterId":"ch_work_han_thu_34","textTraditional":"一三八五頁　七行　失所（謂）〔為〕愆。　景祐、殿本都作「為」。","sentenceOrder":484},
  {"id":"s_work_han_thu_34_485","chapterId":"ch_work_han_thu_34","textTraditional":"一三八六頁　八行　齊（威）〔桓〕既死，　景祐、殿本都作「桓」。","sentenceOrder":485},
  {"id":"s_work_han_thu_34_486","chapterId":"ch_work_han_thu_34","textTraditional":"一三八九頁　八行　定公（十）〔七〕年　蘇輿說據春秋經，定十年無大雩事。其書「九月大雩」，在定七年。「十」疑「七」之誤。","sentenceOrder":486},
  {"id":"s_work_han_thu_34_487","chapterId":"ch_work_han_thu_34","textTraditional":"一三九三頁　九行　丙〔子〕之晨，　景祐本有「子」字。王念孫說景祐本是。","sentenceOrder":487},
  {"id":"s_work_han_thu_34_488","chapterId":"ch_work_han_thu_34","textTraditional":"一三九三頁一四行　袀音（勻）〔均〕，　景祐、殿本都作「均」。","sentenceOrder":488},
  {"id":"s_work_han_thu_34_489","chapterId":"ch_work_han_thu_34","textTraditional":"一三九四頁　一行　（犇）〔賁〕音奔。　殿本作「賁」。　王先謙說作「賁」是。","sentenceOrder":489},
  {"id":"s_work_han_thu_34_490","chapterId":"ch_work_han_thu_34","textTraditional":"一三九五頁一二行　過（河陽）〔陽阿〕主作樂，　何焯、王念孫都說當作「陽阿」。","sentenceOrder":490},
  {"id":"s_work_han_thu_34_491","chapterId":"ch_work_han_thu_34","textTraditional":"一三九七頁一０行　搉其（服）〔眼〕以為人彘。　錢大昭說「服」當作「眼」。按景祐、殿本都作「眼」。","sentenceOrder":491},
  {"id":"s_work_han_thu_34_492","chapterId":"ch_work_han_thu_34","textTraditional":"一三九八頁　七行　伐雍門之（荻）〔萩〕是也。　朱一新說汪本作「萩」是。按左傳襄十八年文作「萩」。","sentenceOrder":492},
  {"id":"s_work_han_thu_35_1","chapterId":"ch_work_han_thu_35","textTraditional":"傳曰：「視之不明，是謂不悊，厥咎舒，厥罰恆奧，〔一〕厥極疾。〔二〕時則有草妖，時則有蠃蟲之孽，〔三〕時則有羊禍，時則有目痾，時則有赤眚赤祥。惟水沴火。」","sentenceOrder":1},
  {"id":"s_work_han_thu_35_2","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「奧讀曰燠。燠，〈日耎〉也，音於六反。其下並同。」","sentenceOrder":2},
  {"id":"s_work_han_thu_35_3","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　韋昭曰：「以疾為罰。」","sentenceOrder":3},
  {"id":"s_work_han_thu_35_4","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「螽、螟之類無鱗甲毛羽，故謂之蠃蟲也。音郎果反。」","sentenceOrder":4},
  {"id":"s_work_han_thu_35_5","chapterId":"ch_work_han_thu_35","textTraditional":"「視之不明，是謂不悊」，悊，知也。詩云：「爾德不明，以亡陪亡卿；不明爾德，以亡背亡仄。」〔一〕言上不明，暗昧蔽惑，則不能知善惡，親近習，長同類，〔二〕亡功者受賞，有罪者不殺，百官廢亂，失在舒緩，故其咎舒也。盛夏日長，暑以養物，政弛緩，故其罰常奧也。奧則冬溫，春夏不和，傷病民人，故極疾也。誅不行則霜不殺草，繇臣下則殺不以時，〔三〕故有草妖。凡妖，貌則以服，言則以詩，聽則以聲。視則以色者，五色物之大分也，在於眚祥，故聖人以為草妖，失秉之明者也。〔四〕溫奧生蟲，故有蠃蟲之孽，謂螟螣之類〔五〕當死不死，未當生而生，或多於故而為災也。劉歆以為屬思心不容。於易，剛而包柔為離，〔六〕離為火為目。羊上角下（號）〔蹄〕，剛而包柔，羊大目而不精明，視氣毀故有羊禍。一曰，暑歲羊多疫死，及為怪，亦是也。及人，則多病目者，故有目痾。火色赤，故有赤眚赤祥。凡視傷者病火氣，火氣傷則水沴之。其極疾者，順之，其福曰壽。〔七〕劉歆視傳曰有羽蟲之孽，雞禍。說以為於天文南方喙為鳥星，故為羽蟲；禍亦從羽，故為雞；雞於易自在巽。說非是。庶徵之恆奧，劉向以為春秋亡冰也。小奧不書，無冰然後書，舉其大者也。京房易傳曰：「祿不遂行茲謂欺，厥咎奧，雨雪四至而溫。臣安祿樂逸茲謂亂，奧而生蟲。知罪不誅茲謂舒，其奧，夏則暑殺人，冬則物華實。重過不誅，茲謂亡徵，其咎當寒而奧六日也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_35_6","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「大雅蕩之詩也。言不別善惡，有逆背傾仄者，有堪為卿大夫者，皆不知之也。仄，古側字。」","sentenceOrder":6},
  {"id":"s_work_han_thu_35_7","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「習，狎也。近狎者則親愛之，同類者則長益也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_35_8","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「繇讀與由同，言誅罰由於臣下。」","sentenceOrder":8},
  {"id":"s_work_han_thu_35_9","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「謂失所執之權也。音彼命反。」","sentenceOrder":9},
  {"id":"s_work_han_thu_35_10","chapterId":"ch_work_han_thu_35","textTraditional":"〔五〕　師古曰：「螟食苗心，螣食苗葉之蟲也。螟音冥。螣音徒得反。」","sentenceOrder":10},
  {"id":"s_work_han_thu_35_11","chapterId":"ch_work_han_thu_35","textTraditional":"〔六〕　師古曰：「兩陽居外，一陰在內，故云剛包柔。」","sentenceOrder":11},
  {"id":"s_work_han_thu_35_12","chapterId":"ch_work_han_thu_35","textTraditional":"〔七〕　李奇曰：「於六極之中為疾者，逆火氣，致疾病也。能順火氣，則禍更為福。」","sentenceOrder":12},
  {"id":"s_work_han_thu_35_13","chapterId":"ch_work_han_thu_35","textTraditional":"桓公十五年「春，亡冰」。劉向以為周春，今冬也。先是連兵鄰國，三戰而再敗也，〔一〕內失百姓，外失諸侯，不敢行誅罰，鄭伯突篡兄而立，公與相親，〔二〕長養同類，不明善惡之罰也。〔三〕董仲舒以為象夫人不正，陰失節也。〔四〕","sentenceOrder":13},
  {"id":"s_work_han_thu_35_14","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「三戰者，謂十年齊侯、衛侯、鄭伯來戰于郎，十二年與鄭師伐宋戰于宋，十三年會紀侯、鄭伯及齊侯、宋公、衛侯、燕人戰也。再敗者，謂郎之戰，穀梁傳曰『以吾敗也』，又宋之戰，穀梁亦曰『諱敗，舉其可道者也』。據左氏傳、公羊、穀梁，亦曰無冰，並在十四年，今此云十五年，未詳其意。」","sentenceOrder":14},
  {"id":"s_work_han_thu_35_15","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「突，鄭莊公子，即厲公也。兄謂太子忽，即昭公也。莊公既卒，突因宋莊公之寵而得立，遂使昭公奔衛，故云篡兄也。公與相親者，謂十五年突為祭仲所逐奔蔡，遂居櫟，而昭公入，公再與諸侯伐鄭，謀納厲公。」","sentenceOrder":15},
  {"id":"s_work_han_thu_35_16","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「言桓篡立，與突志同，故曰長養同類。」","sentenceOrder":16},
  {"id":"s_work_han_thu_35_17","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「夫人姜氏通于齊侯，故云不正。」","sentenceOrder":17},
  {"id":"s_work_han_thu_35_18","chapterId":"ch_work_han_thu_35","textTraditional":"成公元年「二月，無冰」。董仲舒以為方有宣公之喪，君臣無悲哀之心，而炕陽，作丘甲。〔一〕劉向以為時公幼弱，政舒緩也。","sentenceOrder":18},
  {"id":"s_work_han_thu_35_19","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「時宣公薨始踰年，故云有喪也。丘甲，解在刑法志。」","sentenceOrder":19},
  {"id":"s_work_han_thu_35_20","chapterId":"ch_work_han_thu_35","textTraditional":"襄公二十八年「春，無冰」。劉向以為先是公作三軍，有侵陵用武之意，〔一〕於是鄰國不和，伐其三鄙，〔二〕被兵十有餘年，因之以饑饉，百姓怨望，臣下心離，公懼而弛緩，不敢行誅罰，〔三〕楚有夷狄行，公有從楚心，不明善惡之應。〔四〕董仲舒指略同。一曰，水旱之災，寒暑之變，天下皆同，故曰「無冰」，天下異也。桓公殺兄弒君，外成宋亂，與鄭易邑，背畔周室。〔五〕成公時，楚橫行中國，〔六〕王札子殺召伯、毛伯，〔七〕晉敗天子之師于貿戎，〔八〕天子皆不能討。襄公時，天下諸侯之大夫皆執國權，〔九〕君不能制。漸將日甚，善惡不明，誅罰不行。周失之舒，秦失之急，故周衰亡寒歲，秦滅亡奧年。","sentenceOrder":20},
  {"id":"s_work_han_thu_35_21","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「作三軍者，季氏欲專其權，非公本意，此說非也。侵陵用武者，謂入鄆取邿也。邿音詩。」","sentenceOrder":21},
  {"id":"s_work_han_thu_35_22","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「謂十二年三月，十四年夏，莒人伐我東鄙。十五年夏，齊侯伐我北鄙。秋，邾人伐我南鄙。十六年三月，齊侯伐我北鄙。」","sentenceOrder":22},
  {"id":"s_work_han_thu_35_23","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「弛，放也，音式爾反。」","sentenceOrder":23},
  {"id":"s_work_han_thu_35_24","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「有從楚心，謂二十八年公朝于楚。」","sentenceOrder":24},
  {"id":"s_work_han_thu_35_25","chapterId":"ch_work_han_thu_35","textTraditional":"〔五〕　師古曰：「隱攝公位，又桓之兄，故云殺兄弒君也。成宋亂者，謂宋華父督弒其君殤公及其大夫孔父，以郜大鼎賂公，公會齊侯、鄭伯于稷而平其亂也。與鄭易邑，謂以太山之田易許田也。許田者，魯朝宿之邑也，而以與鄭，明魯之不朝於王，故云背畔周室。」","sentenceOrder":25},
  {"id":"s_work_han_thu_35_26","chapterId":"ch_work_han_thu_35","textTraditional":"〔六〕　師古曰：「謂成二年楚師侵衛，遂侵我，師于蜀。六年七月，楚公子嬰齊帥師伐鄭。九年，嬰齊帥師伐莒。十五年，楚子伐鄭。十六年，楚子與晉侯、鄭伯戰于鄢陵。十八年，楚子伐宋。」","sentenceOrder":26},
  {"id":"s_work_han_thu_35_27","chapterId":"ch_work_han_thu_35","textTraditional":"〔七〕　師古曰：「王札子，即王子捷也。召伯、毛伯，皆周大夫也。今春秋經王札子殺召伯、毛伯事在宣十五年，而此言成公時，未達其說。召讀曰邵。」","sentenceOrder":27},
  {"id":"s_work_han_thu_35_28","chapterId":"ch_work_han_thu_35","textTraditional":"〔八〕　師古曰：「貿戎，戎別種也。公羊傳成元年：『王師敗績于貿戎。孰敗之？蓋晉敗之。』貿音莫候反。」","sentenceOrder":28},
  {"id":"s_work_han_thu_35_29","chapterId":"ch_work_han_thu_35","textTraditional":"〔九〕　師古曰：「謂襄十六年會于溴梁，諸侯之大夫盟皆類此。」","sentenceOrder":29},
  {"id":"s_work_han_thu_35_30","chapterId":"ch_work_han_thu_35","textTraditional":"武帝元狩六年冬，亡冰。先是，比年遣大將軍衛青、霍去病攻祁連，絕大幕，〔一〕窮追單于，斬首十餘萬級，還，大行慶賞。乃閔海內勤勞，是歲遣博士褚大等六人持節巡行天下，〔二〕存賜鰥寡，假與乏困，舉遺逸獨行君子詣行在所。郡國有以為便宜者，上丞相、御史以聞。天下咸喜。","sentenceOrder":30},
  {"id":"s_work_han_thu_35_31","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「比，頻也。祁連，山名也。幕，沙磧也。直度曰絕，祁音上夷反。」","sentenceOrder":31},
  {"id":"s_work_han_thu_35_32","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「行音下更反。」","sentenceOrder":32},
  {"id":"s_work_han_thu_35_33","chapterId":"ch_work_han_thu_35","textTraditional":"昭帝始元二年冬，亡冰。是時上年九歲，大將軍霍光秉政，始行寬緩，欲以說下。","sentenceOrder":33},
  {"id":"s_work_han_thu_35_34","chapterId":"ch_work_han_thu_35","textTraditional":"僖公三十三年「十二月，隕霜不殺草」。劉歆以為草妖也。劉向以為今十月，周十二月。於易，五為天位，（為）君位，九月陰氣至，五通於天位，其卦為剝，〔一〕剝落萬物，始大殺矣，明陰從陽命，臣受君令而後殺也。今十月隕霜而不能殺草，此君誅不行，舒緩之應也。是時公子遂顓權，〔二〕三桓始世官，〔三〕天戒若曰，自此之後，將皆為亂矣。文公不寤，其後遂殺子赤，三家逐昭公。〔四〕董仲舒指略同。京房易傳曰：「臣有緩茲謂不順，厥異霜不殺也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_35_35","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「坤下艮上。」","sentenceOrder":35},
  {"id":"s_work_han_thu_35_36","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「公子遂，莊公之子，即東門襄仲也，時為卿，專執國政也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_35_37","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「謂父子相繼為卿也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_35_38","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「並已解於上。」","sentenceOrder":38},
  {"id":"s_work_han_thu_35_39","chapterId":"ch_work_han_thu_35","textTraditional":"書序曰：「伊（涉）〔陟〕相太戊，亳有祥桑穀共生。」〔一〕傳曰：「俱生乎朝，七日而大拱。〔二〕伊陟戒以修德，而木枯。」劉向以為殷道既衰，高宗承敝而起，盡涼陰之哀，天下應之，〔三〕既獲顯榮，怠於政事，國將危亡，故桑穀之異見。桑猶喪也，穀猶生也，殺生之秉失而在下，〔四〕近草妖也。一曰，野木生朝而暴長，小人將暴在大臣之位，危亡國家，象朝將為虛之應也。〔五〕","sentenceOrder":39},
  {"id":"s_work_han_thu_35_40","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「商書咸乂之序也。其書亡。伊陟，伊尹子也。大戊，太甲孫也。亳，殷所都也。桑、穀二木，合而共生。穀音彀。」","sentenceOrder":40},
  {"id":"s_work_han_thu_35_41","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「兩手合為拱，音久勇反。」","sentenceOrder":41},
  {"id":"s_work_han_thu_35_42","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「涼，信也。陰，默也。言居哀信默，三年不言也。涼讀曰諒。一說，涼陰謂居喪之廬也。謂三年處於廬中不言。涼音力羊反。據今尚書及諸傳記，太戊卒，子仲丁立，卒，弟何亶甲立，卒，子祖乙立，卒，子盤庚立，卒，小乙之子武丁立，是為高宗。桑穀自太戊時生，涼陰乃高宗之事。而此云桑穀即高宗時出，其說與尚書大傳不同，未詳其義也。或者伏生差謬。」","sentenceOrder":42},
  {"id":"s_work_han_thu_35_43","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「秉音彼命反。」","sentenceOrder":43},
  {"id":"s_work_han_thu_35_44","chapterId":"ch_work_han_thu_35","textTraditional":"〔五〕　師古曰：「虛讀曰墟。」","sentenceOrder":44},
  {"id":"s_work_han_thu_35_45","chapterId":"ch_work_han_thu_35","textTraditional":"書序又曰：「高宗祭成湯，有蜚雉登鼎耳而雊。」〔一〕祖己曰：「惟先假王，正厥事。」〔二〕劉向以為雉雊鳴者雄也，以赤色為主。於易，離為雉，雉，南方，近赤祥也。劉歆以為羽蟲之孽。易有鼎卦，〔三〕鼎，宗廟之器，主器奉宗廟者長子也。野鳥自外來，入為宗廟器主，是繼嗣將易也。一曰，鼎三足，三公象，而以耳行〔四〕。野鳥居鼎耳，小人將居公位，敗宗廟之祀。野木生朝，野鳥入廟，敗亡之異也。武丁恐駭，謀於忠賢，修德而正事，內舉傅說，授以國政，〔五〕外伐鬼方，以安諸夏，〔六〕故能攘木鳥之妖，致百年之壽，〔七〕所謂「六沴作見，若是共御，五福乃降，用章于下」者也。〔八〕一曰，金沴木曰木不曲直。","sentenceOrder":45},
  {"id":"s_work_han_thu_35_46","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「商書高宗肜日之序也。蜚，古飛字。雊音工豆反。」","sentenceOrder":46},
  {"id":"s_work_han_thu_35_47","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「祖己，殷賢臣。假，大也。言先代大道之王，能正其事，而災異銷也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_35_48","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「巽下離上也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_35_49","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「鼎非舉耳不得行，故云以耳行。」","sentenceOrder":49},
  {"id":"s_work_han_thu_35_50","chapterId":"ch_work_han_thu_35","textTraditional":"〔五〕　師古曰：「武丁夢得賢相，乃以所夢之像使求之，得於傅巖，立以為相，作說命三篇。說讀曰悅。」","sentenceOrder":50},
  {"id":"s_work_han_thu_35_51","chapterId":"ch_work_han_thu_35","textTraditional":"〔六〕　師古曰：「鬼方，絕遠之地，一曰國名。夏，大也。中國大於戎狄，故曰諸夏。」","sentenceOrder":51},
  {"id":"s_work_han_thu_35_52","chapterId":"ch_work_han_thu_35","textTraditional":"〔七〕　師古曰：「攘，卻也，音人羊反。」","sentenceOrder":52},
  {"id":"s_work_han_thu_35_53","chapterId":"ch_work_han_thu_35","textTraditional":"〔八〕　師古曰：「共讀曰恭。御讀曰禦。言恭己以禦災也。一說，御，治也，恭治其事也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_35_54","chapterId":"ch_work_han_thu_35","textTraditional":"僖公三十三年「十二月，李梅實」。劉向以為周十二月，今十月也，李梅當剝落，今反華實，近草妖也。先華而後實，不書華，舉重者也。陰成陽事，象臣顓君作威福。一曰，冬當殺，反生，象驕臣當誅，不行其罰也。故冬（華）華者，象臣邪謀有端而不成，至於實，則成矣。是時僖公死，公子遂顓權，文公不寤，後有子赤之變。一曰，君舒緩甚，奧氣不臧，則華實復生。董仲舒以為李梅實，臣下彊也。記曰：「不當華而華，易大夫；不當實而實，易相室。」〔一〕冬，水王，木相，故象大臣。劉歆以為庶徵皆以蟲為孽，思心蠃蟲孽也。李梅實，屬草妖。","sentenceOrder":54},
  {"id":"s_work_han_thu_35_55","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　應劭曰：「冬，水王，木相，故象大臣。冬實者，變置丞相與宮室也。但華，則變大夫也。」師古曰：「相室猶言相國，謂宰相也。合韻故言相室。相室者，相王室。」","sentenceOrder":55},
  {"id":"s_work_han_thu_35_56","chapterId":"ch_work_han_thu_35","textTraditional":"惠帝五年十月，桃李華，棗實。昭帝時，上林苑中大柳樹斷仆地，一朝起立，生枝葉，有蟲食其葉，成文字，曰「公孫病已立」。又昌邑王國社有枯樹復生枝葉。眭孟以為木陰類，下民象，當有故廢之家公孫氏從民間受命為天子者。昭帝富於春秋，霍光秉政，以孟妖言，誅之。後昭帝崩，無子，徵昌邑王賀嗣位，狂亂失道，光廢之，更立昭帝兄衛太子之孫，是為宣帝。帝本名病已。京房易傳曰：「枯楊生稊，〔一〕枯木復生，人君亡子。」","sentenceOrder":56},
  {"id":"s_work_han_thu_35_57","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「大過九二爻辭也。稊，楊秀之始生者，音徒奚反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_35_58","chapterId":"ch_work_han_thu_35","textTraditional":"元帝初元四年，皇后曾祖父濟南東平陵王伯墓門梓柱卒生枝葉，上出屋。〔一〕劉向以為王氏貴盛將代漢家之象也。後王莽篡位，自說之曰：「初元四年，莽生之歲也，當漢九世火德之厄，而有此祥興於高祖考之門。門為開通，梓猶子也，言王氏當有賢子開通祖統，起於柱石大臣之位，受命而王之符也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_35_59","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　孟康曰：「王伯，莽之祖也。」師古曰：「莽高祖父也。故下云高祖考。卒讀曰猝。猝，暴也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_35_60","chapterId":"ch_work_han_thu_35","textTraditional":"建昭五年，兗州刺史浩賞禁民私所自立社。〔一〕山陽橐茅鄉社有大槐樹，〔二〕吏伐斷之，其夜樹復立其故處。成帝永始元年二月，河南街郵樗樹生支如人頭，〔三〕眉目須皆具，亡髮耳。哀帝建平三年十月，汝南西平遂陽鄉柱仆地，生支如人形，〔四〕身青黃色，面白，頭有頿髮，稍長大，凡長六寸一分。京房易傳曰：「王德衰，下人將起，則有木生為人狀。」","sentenceOrder":60},
  {"id":"s_work_han_thu_35_61","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　張晏曰：「民間三月九月又社，號曰私社。」臣瓚曰：「舊制二十五家為一社，而民或十家五家共為田社，是私社。」師古曰：「瓚說是。」","sentenceOrder":61},
  {"id":"s_work_han_thu_35_62","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「橐，縣名也，屬山陽郡。茅鄉，橐縣之鄉也。橐音拓。」","sentenceOrder":62},
  {"id":"s_work_han_thu_35_63","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「郵謂行書之舍。樗樹似杶。樗音丑余反。杶音丑倫反。」","sentenceOrder":63},
  {"id":"s_work_han_thu_35_64","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「仆，頓也，音赴。」","sentenceOrder":64},
  {"id":"s_work_han_thu_35_65","chapterId":"ch_work_han_thu_35","textTraditional":"哀帝建平三年，零陵有樹僵地，〔一〕圍丈六尺，長十丈七尺。民斷其本，長九尺餘，皆枯。三月，樹卒自立故處。〔二〕京房易傳曰：「棄正作淫，厥妖木斷自屬。〔三〕妃后有顓，木仆反立，斷枯復生。〔四〕天辟惡之。」〔五〕","sentenceOrder":65},
  {"id":"s_work_han_thu_35_66","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「僵，偃也，音疆。」","sentenceOrder":66},
  {"id":"s_work_han_thu_35_67","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「卒讀曰猝。」","sentenceOrder":67},
  {"id":"s_work_han_thu_35_68","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「屬，連續也。音之欲反。」","sentenceOrder":68},
  {"id":"s_work_han_thu_35_69","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「顓謂專寵。」","sentenceOrder":69},
  {"id":"s_work_han_thu_35_70","chapterId":"ch_work_han_thu_35","textTraditional":"〔五〕　如淳曰：「天辟，謂天子也。」師古曰：「辟音壁。」","sentenceOrder":70},
  {"id":"s_work_han_thu_35_71","chapterId":"ch_work_han_thu_35","textTraditional":"元帝永光二年八月，天雨草，而葉相摎結，大如彈丸。〔一〕平帝元始三年正月，天雨草，狀如永光時。京房易傳曰：「君吝於祿，信衰賢去，厥妖天雨草。」","sentenceOrder":71},
  {"id":"s_work_han_thu_35_72","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「摎，繞也。樛音居虯反。」","sentenceOrder":72},
  {"id":"s_work_han_thu_35_73","chapterId":"ch_work_han_thu_35","textTraditional":"昭公二十五年「夏，有鴝鵒來巢」。劉歆以為羽蟲之孽，其色黑，又黑祥也，視不明聽不聰之罰也。劉向以為有蜚有{或虫}不言來者，氣所生，所謂眚也；〔一〕鴝鵒言來者，氣所致，所謂祥也。鴝鵒，夷狄穴藏之禽，來至中國，不穴而巢，陰居陽位，〔二〕象季氏將逐昭公，去宮室而居外野也。鴝鵒白羽，旱之祥也；穴居而好水，黑色，為主急之應也。天戒若曰，既失眾，不可急暴；急暴，陰將持節陽以逐爾，去宮室而居外野矣。昭不寤，而舉兵圍季氏，為季氏所敗，出奔于齊，遂死于外野。董仲舒指略同。","sentenceOrder":73},
  {"id":"s_work_han_thu_35_74","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「此蜚，謂負蠜也，其為蟲臭。{或虫}，短弧，即今所謂水弩也。隱元年有蜚，莊十八年有{或虫}。蜚音翡。{或虫}音域。蜚亦作蜰，其音同耳。」","sentenceOrder":74},
  {"id":"s_work_han_thu_35_75","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「今之鴝鵒，中國皆有，依周官而言，但不踰濟水耳。左氏以為魯所常無，故異而書之。而此云夷狄禽，未喻其意。又此鳥本亦巢居，不皆穴處也。書巢者，著其居止字乳，不即去也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_35_76","chapterId":"ch_work_han_thu_35","textTraditional":"景帝三年十一月，有白頸烏與黑烏群鬥楚國呂縣，白頸不勝，墮泗水中，死者數千。劉向以為近白黑祥也。時楚王戊暴逆無道，〔一〕刑辱申公，與吳王謀反。烏群鬥者，師戰之象也。白頸者小，明小者敗也。墮於水者，將死水地。王戊不寤，遂舉兵應吳，與漢大戰，兵敗而走，至於丹徒，為越人所斬，墮死於水之效也。京房易傳曰：「逆親親，厥妖白黑烏鬥於國。」","sentenceOrder":76},
  {"id":"s_work_han_thu_35_77","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「戊，楚元王之孫也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_35_78","chapterId":"ch_work_han_thu_35","textTraditional":"昭帝元鳳元年，有烏與鵲鬥燕王宮中池上，烏墮池死，近黑祥也。時燕王旦謀為亂，遂不改寤，伏辜而死。楚、燕皆骨肉藩臣，以驕怨而謀逆，俱有烏鵲鬥死之祥，行同而占合，此天人之明表也。燕一烏鵲鬥於宮中而黑者死，楚以萬數鬥於野外而白者死，象燕陰謀未發，獨王自殺於宮，故一烏水色者死，楚炕陽舉兵，軍師大敗於野，故眾烏金色者死，天道精微之效也。京房易傳曰：「專征劫殺，厥妖烏鵲鬥。」","sentenceOrder":78},
  {"id":"s_work_han_thu_35_79","chapterId":"ch_work_han_thu_35","textTraditional":"昭帝時有鵜鶘或曰禿鶖，〔一〕集昌邑王殿下，王使人射殺之。劉向以為水鳥色青，青祥也。時王馳騁無度，慢侮大臣，不敬至尊，有服妖之象，〔二〕故青祥見也。野鳥入處，宮室將空。王不寤，卒以亡。京房易傳曰：「辟退有德，厥咎狂，厥妖水鳥集于國中。〔三〕」","sentenceOrder":79},
  {"id":"s_work_han_thu_35_80","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「鵜鶘即汙澤也，一名淘河，腹下胡大如數升囊，好群入澤中，抒水食魚，因名禿鶖，亦水鳥也。鵜音大奚反。鶘音胡。鶖音秋。」","sentenceOrder":80},
  {"id":"s_work_han_thu_35_81","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「謂多治仄注冠，又以冠奴也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_35_82","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「辟，君也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_35_83","chapterId":"ch_work_han_thu_35","textTraditional":"成帝河平元年二月庚子，泰山山桑谷有〈截，中“隹改鳥”〉焚其巢。〔一〕男子孫通等聞山中群鳥〈截，中“隹改鳥”〉鵲聲，往視，見巢{難灬}，盡墮地中，〔二〕有三〈截，中“隹改鳥”〉鷇燒死。〔三〕樹大四圍，巢去地五丈五尺。太守平以聞。〈截，中“隹改鳥”〉色黑，近黑祥，貪虐之類也。易曰：「鳥焚其巢，旅人先笑後號咷。」〔四〕泰山，岱宗，五嶽之長，王者易姓告代之處也。天戒若曰，勿近貪虐之人，聽其賊謀，將生焚巢自害其子絕世易姓之禍。其後趙蜚燕得幸，立為皇后，弟為昭儀，姊妹專寵，聞後宮許美人、曹偉能生皇子也，〔五〕昭儀大怒，令上奪取而殺之，皆并殺其母。成帝崩，昭儀自殺，事乃發覺，趙后坐誅。此焚巢殺子後號咷之應也。一曰，王莽貪虐而任社稷之重，卒成易姓之禍云。京房易傳曰：人君暴虐，鳥焚其舍。」","sentenceOrder":83},
  {"id":"s_work_han_thu_35_84","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「〈截，中“隹改鳥”〉，鴟也，音緣。」","sentenceOrder":84},
  {"id":"s_work_han_thu_35_85","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「{難灬}，古然字。」","sentenceOrder":85},
  {"id":"s_work_han_thu_35_86","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「鳥子新生而哺者曰鷇，音口豆反，又音工豆反。」","sentenceOrder":86},
  {"id":"s_work_han_thu_35_87","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「旅卦上九爻辭也。咷音逃。」","sentenceOrder":87},
  {"id":"s_work_han_thu_35_88","chapterId":"ch_work_han_thu_35","textTraditional":"〔五〕　師古曰：「曹偉能，宮人姓名也。偉能一名宮，見外戚傳。」","sentenceOrder":88},
  {"id":"s_work_han_thu_35_89","chapterId":"ch_work_han_thu_35","textTraditional":"鴻嘉二年三月，博士行大射禮，有飛雉集于庭，歷階登堂而雊。後雉又集太常、宗正、丞相、御史大夫、大司馬車騎將軍之府，又集未央宮承明殿屋上。時大司馬車騎將軍王音、待詔寵等上言：「天地之氣，以類相應，〔一〕譴告人君，甚微而著。雉者聽察，先聞雷聲，故月令以紀氣。〔二〕經載高宗雊雉之異，〔三〕以明轉禍為福之驗。今雉以博士行禮之日大眾聚會，飛集於庭，歷階登堂，萬眾睢睢，〔四〕驚怪連日。徑歷三公之府，太常宗正典宗廟骨肉之官，然後入宮。其宿留告曉人，具備深切，〔五〕雖人道相戒，何以過是！」後帝使中常侍晁閎詔音曰：「聞捕得雉，毛羽頗摧折，類拘執者，得無人為之？」〔六〕音復對曰：「陛下安得亡國之語？不知誰主為佞諂之計，〔七〕誣亂聖德如此者！左右阿諛甚眾，不待臣音復諂而足。〔八〕公卿以下，保位自守，莫有正言。如令陛下覺寤，懼大禍且至身，深責臣下，繩以聖法，臣音當先受誅，豈有以自解哉！今即位十五年，繼嗣不立，日日駕車而出，泆行流聞，〔九〕海內傳之，甚於京師。外有微行之害，內有疾病之憂，皇天數見災異，〔一０〕欲人變更，終已不改。天尚不能感動陛下，臣子何望？獨有極言待死，命在朝暮而已。如有不然，老母安得處所，尚何皇太后之有！高祖天下當以誰屬乎！〔一一〕宜謀於賢知，克己復禮，以求天意，繼嗣可立，災變尚可銷也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_35_90","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「以經術待詔，其人名寵，不記姓也。流浴書本寵上輒加孫字，非也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_35_91","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「謂季冬之月云『雉雊雞乳』也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_35_92","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「已解於上。」","sentenceOrder":92},
  {"id":"s_work_han_thu_35_93","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「睢睢，仰目視貌也。音呼惟反。」","sentenceOrder":93},
  {"id":"s_work_han_thu_35_94","chapterId":"ch_work_han_thu_35","textTraditional":"〔五〕　師古曰：「宿音先就反。留音力救反。」","sentenceOrder":94},
  {"id":"s_work_han_thu_35_95","chapterId":"ch_work_han_thu_35","textTraditional":"〔六〕　師古曰：「言人放此雉，故欲為變異者。」","sentenceOrder":95},
  {"id":"s_work_han_thu_35_96","chapterId":"ch_work_han_thu_35","textTraditional":"〔七〕　師古曰：「讇，古諂（也）〔字〕。」","sentenceOrder":96},
  {"id":"s_work_han_thu_35_97","chapterId":"ch_work_han_thu_35","textTraditional":"〔八〕　師古曰：「足，益也，音子喻反。」","sentenceOrder":97},
  {"id":"s_work_han_thu_35_98","chapterId":"ch_work_han_thu_35","textTraditional":"〔九〕　師古曰：「言帝行多驕泆，醜惡流布，聞於遠方也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_35_99","chapterId":"ch_work_han_thu_35","textTraditional":"〔一０〕師古曰：「見，顯示。」","sentenceOrder":99},
  {"id":"s_work_han_thu_35_100","chapterId":"ch_work_han_thu_35","textTraditional":"〔一一〕如淳曰：「老母，音之老母也，當隨己受罪誅也。又謂己言深切，觸悟人主，積恚而死，必行之誅，不能復顧太后也。」師古曰：「如說非也。此言總屬於成帝耳。不然者，謂不如所諫而自修改也。老母，帝之母，即太后也。言帝不自修改，國家危亡，太后不知處所，高祖天下無所付屬也。屬音之欲反。」","sentenceOrder":100},
  {"id":"s_work_han_thu_35_101","chapterId":"ch_work_han_thu_35","textTraditional":"成帝綏和二年三月，天水平襄有燕生爵，哺食至大，俱飛去〔一〕。京房易傳曰：「賊臣在國，厥咎燕生爵，諸侯銷。」一曰，生非其類，子不嗣世。","sentenceOrder":101},
  {"id":"s_work_han_thu_35_102","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「哺音蒲固反。食讀曰飤。謂與母俱去。」","sentenceOrder":102},
  {"id":"s_work_han_thu_35_103","chapterId":"ch_work_han_thu_35","textTraditional":"史記魯定公時，季桓子穿井，得土缶，中得蟲若羊，〔一〕近羊禍也。羊者，地上之物，幽於土中，象定公不用孔子而聽季氏，暗昧不明之應也。一曰，羊去野外而拘土缶者，象魯君失其所而拘於季氏，季氏亦將拘於家臣也。是歲季氏家臣陽虎囚季桓子。後三年，陽虎劫公伐孟氏，兵敗，竊寶玉大弓而出亡。〔二〕","sentenceOrder":103},
  {"id":"s_work_han_thu_35_104","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「缶，盎也，即今之盆。」","sentenceOrder":104},
  {"id":"s_work_han_thu_35_105","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「寶玉謂夏后氏之璜，大弓謂封父之繁弱，皆魯始封之分器，所受於周也。定八年，陽虎作亂不克，竊之而入讙陽關以叛。」","sentenceOrder":105},
  {"id":"s_work_han_thu_35_106","chapterId":"ch_work_han_thu_35","textTraditional":"左氏傳魯襄公時，宋有生女子赤而毛，棄之隄下，宋平公母共姬之御者見而收之，〔一〕因名曰棄。長而美好，納之平公，生子曰佐。後宋臣伊戾讒太子痤而殺之。〔二〕先是，大夫華元出奔晉，〔三〕華弱奔魯，〔四〕華臣奔陳，〔五〕華合比奔衛。〔六〕劉向以為時則火災赤眚之明應也。京房易傳曰：「尊卑不別，厥妖女生赤毛。」","sentenceOrder":106},
  {"id":"s_work_han_thu_35_107","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「平公，宋共公之子也，名成。共讀曰恭。」","sentenceOrder":107},
  {"id":"s_work_han_thu_35_108","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「事在襄二十六年。痤音才戈反。」","sentenceOrder":108},
  {"id":"s_work_han_thu_35_109","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「華元奔在成十五年。」","sentenceOrder":109},
  {"id":"s_work_han_thu_35_110","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「事在襄六年。」","sentenceOrder":110},
  {"id":"s_work_han_thu_35_111","chapterId":"ch_work_han_thu_35","textTraditional":"〔五〕　師古曰：「事在襄十七年。」","sentenceOrder":111},
  {"id":"s_work_han_thu_35_112","chapterId":"ch_work_han_thu_35","textTraditional":"〔六〕　師古曰：「事在昭六年。據今春秋，合比奔在殺太子痤後，而志總言先是，未詳其意。」","sentenceOrder":112},
  {"id":"s_work_han_thu_35_113","chapterId":"ch_work_han_thu_35","textTraditional":"惠帝二年，天雨血於宜陽，一頃所，劉向以為赤眚也。時又冬雷，桃李華，常奧之罰也。是時政舒緩，諸呂用事，讒口妄行，殺三皇子，建立非嗣，〔一〕及不當立之王，〔二〕退王陵、趙堯、周昌。〔三〕呂太后崩，大臣共誅滅諸呂，僵尸流血。京房易傳曰：「歸獄不解，茲謂追非，厥咎天雨血；茲謂不親，民有怨心，不出三年，無其宗人。」又曰：「佞人祿，功臣僇，天雨血。」〔四〕","sentenceOrder":113},
  {"id":"s_work_han_thu_35_114","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「三皇子，謂趙隱王如意、趙幽王友、趙恭王恢，皆高帝子也。建立非嗣，謂立後宮美人子為嗣。」","sentenceOrder":114},
  {"id":"s_work_han_thu_35_115","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　孟康曰：「呂氏三王也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_35_116","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「惠帝六年，王陵為右丞相。惠帝崩，呂后欲廢陵，遷為太傅，實奪之相權。高祖以趙堯為御史大夫，高后元年怨堯前定趙王如意之策，乃抵堯罪。周昌為趙相，趙王見鴆殺，昌謝病不朝見，三歲而薨。」","sentenceOrder":116},
  {"id":"s_work_han_thu_35_117","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「僇，古戮字。」","sentenceOrder":117},
  {"id":"s_work_han_thu_35_118","chapterId":"ch_work_han_thu_35","textTraditional":"哀帝建平四年四月，山陽湖陵雨血，廣三尺，長五尺，大者如錢，小者如麻子。後二年，帝崩，王莽擅朝，誅貴戚丁、傅，大臣董賢等皆放徙遠方，與諸呂同（眾）〔象〕。誅死者少，雨血亦少。","sentenceOrder":118},
  {"id":"s_work_han_thu_35_119","chapterId":"ch_work_han_thu_35","textTraditional":"傳曰：「聽之不聰，是謂不謀，厥咎急，厥罰恆寒，厥極貧。時則有鼓妖，時則有魚孽，時則有豕禍，時則有耳痾，時則有黑眚黑祥。惟火沴水。」","sentenceOrder":119},
  {"id":"s_work_han_thu_35_120","chapterId":"ch_work_han_thu_35","textTraditional":"「聽之不聰，是謂不謀」，言上偏聽不聰，下情隔塞，則不能謀慮利害，失在嚴急，故其咎急也。盛冬日短，寒以殺物，政促迫，故其罰常寒也。寒則不生百穀，上下俱貧，故其極貧也。君嚴猛而閉下，臣戰栗而塞耳，則妄聞之氣發於音聲，故有鼓妖。寒氣動，故有魚孽。雨以龜為孽，〔一〕龜能陸處，非極陰也；魚去水而死，極陰之孽也。於易坎為豕，豕大耳而不聰察，聽氣毀，故有豕禍也。一曰，寒歲豕多死，及為怪，亦是也。及人，則多病耳者，故有耳痾。水色黑，故有黑眚黑祥。凡聽傷者病水氣，水氣病則火沴之。其極貧者，順之，其福曰富。劉歆聽傳曰有介蟲孽也，庶徵之恆寒。劉向以為春秋無其應，周之末世舒緩微弱，政在臣下，奧煖而已，故籍秦以為驗。〔二〕秦始皇帝即位尚幼，委政太后，太后淫於呂不韋及嫪毐〔三〕，封毐為長信侯，以太原郡為毐國，宮室苑囿自恣，政事斷焉。故天冬雷，以見陽不禁閉，以涉危害，舒奧迫近之變也。始皇既冠，毐懼誅作亂，始皇誅之，斬首數百級，大臣二十人，皆車裂以徇，夷滅其宗，遷四千餘家於房陵。是歲四月，寒，民有凍死者。數年之間，緩急如此，寒奧輒應，此其效也。劉歆以為大雨雪，及未當雨雪而雨雪，及大雨雹，隕霜殺叔草，皆常寒之罰也。劉向以為常雨屬貌不恭。京房易傳曰：「有德遭險，茲謂逆命，厥異寒。誅過深，當奧而寒，盡六日，亦為雹。害正不誅，茲謂養賊，寒七十二日，殺蜚禽〔四〕。道人始去茲謂傷，〔五〕其寒物無霜而死，涌水出。戰不量敵，茲謂辱命，其寒雖雨物不茂。聞善不予，厥咎聾。」","sentenceOrder":120},
  {"id":"s_work_han_thu_35_121","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　服虔曰：「多雨則龜多出。」","sentenceOrder":121},
  {"id":"s_work_han_thu_35_122","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「籍，假借。」","sentenceOrder":122},
  {"id":"s_work_han_thu_35_123","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「嫪或音居虯反。嫪，姓也。毐，名也。許慎說以為『嫪毐，士之無行者』。嫪音郎到反。毐音烏改反。與今史記、漢書本文不同，且摎樂之姓，又非嫪也，故當依本字以讀。」","sentenceOrder":123},
  {"id":"s_work_han_thu_35_124","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「蜚讀曰飛。」","sentenceOrder":124},
  {"id":"s_work_han_thu_35_125","chapterId":"ch_work_han_thu_35","textTraditional":"〔五〕　服虔曰：「有道之人去。」","sentenceOrder":125},
  {"id":"s_work_han_thu_35_126","chapterId":"ch_work_han_thu_35","textTraditional":"桓公八年「十月，雨雪」。周十月，今八月也，未可以雪，劉向以為時夫人有淫齊之行，而桓有妒（媚）〔媢〕之心，〔一〕夫人將殺，其象見也。〔二〕桓不覺寤，後與夫人俱如齊而殺死。凡雨，陰也，雪又雨之陰也，出非其時，迫近象也。董仲舒以為象（大）〔夫〕人專恣，陰氣盛也。","sentenceOrder":126},
  {"id":"s_work_han_thu_35_127","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「媢謂夫妒婦也。音莫報反。」","sentenceOrder":127},
  {"id":"s_work_han_thu_35_128","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「謂欲殺桓公。」","sentenceOrder":128},
  {"id":"s_work_han_thu_35_129","chapterId":"ch_work_han_thu_35","textTraditional":"釐公十年「冬，大雨雪」。劉向以為先是釐公立妾為夫人，陰居陽位，陰氣盛也。公羊經曰「大雨雹」。董仲舒以為公脅於齊桓公，立妾為夫人，不敢進群妾，〔一〕故專壹之象見諸雹，皆為有所漸脅也，〔二〕行專壹之政云。","sentenceOrder":129},
  {"id":"s_work_han_thu_35_130","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「已解於上。」","sentenceOrder":130},
  {"id":"s_work_han_thu_35_131","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　孟康曰：「謂陰氣漸脅。」","sentenceOrder":131},
  {"id":"s_work_han_thu_35_132","chapterId":"ch_work_han_thu_35","textTraditional":"昭公四年「正月，大雨雪」。劉向以為昭取於吳而為同姓，謂之吳孟子。〔一〕君行於上，臣非於下。又三家已彊，皆賤公行，慢〈亻母〉之心生。〔二〕董仲舒以為季孫宿任政，陰氣盛也。〔三〕","sentenceOrder":132},
  {"id":"s_work_han_thu_35_133","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「魯與吳俱姬也。周禮同姓不為婚，故諱不稱吳姬，而云孟子也。取讀曰娶。」","sentenceOrder":133},
  {"id":"s_work_han_thu_35_134","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「〈亻母〉，古侮字。」","sentenceOrder":134},
  {"id":"s_work_han_thu_35_135","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「季孫宿，季武子也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_35_136","chapterId":"ch_work_han_thu_35","textTraditional":"文帝四年六月，大雨雪。後三歲，淮南王長謀反，發覺，遷，道死。〔一〕京房易傳曰：「夏雨雪，戒臣為亂。」","sentenceOrder":136},
  {"id":"s_work_han_thu_35_137","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「遷於蜀，未至而死於雍，故曰道死。」","sentenceOrder":137},
  {"id":"s_work_han_thu_35_138","chapterId":"ch_work_han_thu_35","textTraditional":"景帝中六年三月，雨雪。其六月，匈奴入上郡取苑馬，吏卒戰死者二千餘人。明年，條侯周亞夫下獄死。","sentenceOrder":138},
  {"id":"s_work_han_thu_35_139","chapterId":"ch_work_han_thu_35","textTraditional":"武帝元狩元年十二月，大雨雪，民多凍死。是歲淮南、衡山王謀反，發覺，皆自殺。使者行郡國，治黨與，〔一〕坐死者數萬人。","sentenceOrder":139},
  {"id":"s_work_han_thu_35_140","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「行音下更反。」","sentenceOrder":140},
  {"id":"s_work_han_thu_35_141","chapterId":"ch_work_han_thu_35","textTraditional":"元鼎二年三月，雪，平地厚五尺。是歲御史大夫張湯有罪自殺，丞相嚴青翟坐與三長史謀陷湯，〔一〕青翟自殺，三長史皆棄市。","sentenceOrder":141},
  {"id":"s_work_han_thu_35_142","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「謂朱買臣為丞相長史，王朝及邊通皆守丞相長史也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_35_143","chapterId":"ch_work_han_thu_35","textTraditional":"元鼎三年三月水冰，四月雨雪，關東十餘郡人相食。是歲，民不占緡錢有告者，以半畀之。〔一〕","sentenceOrder":143},
  {"id":"s_work_han_thu_35_144","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「言政急刻也。占音之贍反。」","sentenceOrder":144},
  {"id":"s_work_han_thu_35_145","chapterId":"ch_work_han_thu_35","textTraditional":"元帝建昭二年十一月，齊楚地大雪，深五尺。是歲魏郡太守京房為石顯所告，坐與妻父淮陽王舅張博、博弟光勸視淮陽王以不義〔一〕，博要斬，光、房棄市，御史大夫鄭弘坐免為庶人。成帝即位，顯伏辜，淮陽王上書冤博，辭語增加，〔二〕家屬徙者復得還。","sentenceOrder":145},
  {"id":"s_work_han_thu_35_146","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「視讀曰示。」","sentenceOrder":146},
  {"id":"s_work_han_thu_35_147","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「言博本為石顯所冤，增加其語故陷罪。」","sentenceOrder":147},
  {"id":"s_work_han_thu_35_148","chapterId":"ch_work_han_thu_35","textTraditional":"建昭四年三月，雨雪，燕多死。谷永對曰：「皇后桑蠶以治祭服，共事天地宗廟，〔一〕正以是日疾風自西北，大寒雨雪，壞敗其功，以章不鄉。〔二〕宜齊戒辟寢，以深自責，〔三〕請皇后就宮，鬲閉門戶，毋得擅上。〔四〕且令眾妾人人更進，以時博施。皇天說喜，〔五〕庶幾可以得賢明之嗣。即不行臣言，災異俞甚，天變成形，臣雖欲復捐身關策，不及事已。」〔六〕其後許后坐祝詛廢。","sentenceOrder":148},
  {"id":"s_work_han_thu_35_149","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「共讀曰恭。」","sentenceOrder":149},
  {"id":"s_work_han_thu_35_150","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「言不當天心。鄉讀曰嚮。」","sentenceOrder":150},
  {"id":"s_work_han_thu_35_151","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「齊讀曰齋。辟讀曰避。」","sentenceOrder":151},
  {"id":"s_work_han_thu_35_152","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「鬲與隔同。擅上，謂輒至御所也。上音時掌反。一曰，擅，專也。上謂天子也，讀如本字。勿令皇后專固天子。」","sentenceOrder":152},
  {"id":"s_work_han_thu_35_153","chapterId":"ch_work_han_thu_35","textTraditional":"〔五〕　師古曰：「更音工衡反。說讀曰悅。」","sentenceOrder":153},
  {"id":"s_work_han_thu_35_154","chapterId":"ch_work_han_thu_35","textTraditional":"〔六〕　師古曰：「言雖欲棄捐其身，不懷顧慮，極陳計策，關說天子，亦無所及。」","sentenceOrder":154},
  {"id":"s_work_han_thu_35_155","chapterId":"ch_work_han_thu_35","textTraditional":"陽朔四年四月，雨雪，燕雀死。後十六年，許皇后自殺。","sentenceOrder":155},
  {"id":"s_work_han_thu_35_156","chapterId":"ch_work_han_thu_35","textTraditional":"定公元年「十月，隕霜殺菽」。〔一〕劉向以為周十月，今八月也，消卦為觀，〔二〕陰氣未至君位而殺，誅罰不由君出，在臣下之象也。是時季氏逐昭公，公死于外，定公得立，故天見災以視公也。〔三〕釐公二年「十月，隕霜不殺草」，為嗣君微，失秉事之象也。〔四〕其後卒在臣下，則災為之生矣。異故言草，災故言菽，重殺穀。〔五〕一曰菽，草之難殺者也，言殺菽，知草皆死也；言不殺草，知菽亦不死也。董仲舒以為菽，草之彊者，天戒若曰，加誅於彊臣。言菽，以微見季氏之罰也。","sentenceOrder":156},
  {"id":"s_work_han_thu_35_157","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「菽，大豆。」","sentenceOrder":157},
  {"id":"s_work_han_thu_35_158","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「坤下巽上也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_35_159","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「視讀曰示。」","sentenceOrder":159},
  {"id":"s_work_han_thu_35_160","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「謂襄仲專權，殺嫡立庶，公室遂弱。秉音彼命反。」","sentenceOrder":160},
  {"id":"s_work_han_thu_35_161","chapterId":"ch_work_han_thu_35","textTraditional":"〔五〕　師古曰：「以其事為重，不比於殺草也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_35_162","chapterId":"ch_work_han_thu_35","textTraditional":"武帝元光四年四月，隕霜殺草木。先是二年，遣五將軍三十萬眾伏馬邑下，〔一〕欲襲單于，單于覺之而去。自是始征伐四夷，師出三十餘年，天下戶口減半。京房易傳曰：「興兵妄誅，茲謂亡法，厥災霜，夏殺五穀，冬殺麥。誅不原情，茲謂不仁，其霜，夏先大雷風，冬先雨，乃隕霜，有芒角。賢聖遭害，其霜附木不下地。佞人依刑，茲謂私賊，其霜在草根土隙間。不教而誅茲謂虐，其霜反在草下。」","sentenceOrder":162},
  {"id":"s_work_han_thu_35_163","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「謂御史大夫韓安國為護軍將軍，衛尉李廣為驍騎將軍，太僕公孫賀為輕車將軍，大行王恢為將屯將軍，太中大夫李息為材官將軍。」","sentenceOrder":163},
  {"id":"s_work_han_thu_35_164","chapterId":"ch_work_han_thu_35","textTraditional":"元帝永光元年三月，隕霜殺桑；九月二日，隕霜殺稼，天下大飢。是時中書令石顯用事專權，與春秋定公時隕霜同應。成帝即位，顯坐作威福誅。","sentenceOrder":164},
  {"id":"s_work_han_thu_35_165","chapterId":"ch_work_han_thu_35","textTraditional":"釐公二十九年「秋，大雨雹」。劉向以為盛陽雨水，溫煖而湯熱，陰氣脅之不相入，則轉而為雹；盛陰雨雪，凝滯而冰寒，陽氣薄之不相入，則散而為霰。〔一〕故沸湯之在閉器，而湛於寒泉，則為冰，〔二〕及雪之銷，亦冰解而散，此其驗也。故雹者陰脅陽也，霰者陽脅陰也，春秋不書霰者，猶月食也。釐公末年信用公子遂，遂專權自恣，將至於殺君，故陰脅陽之象見。釐公不寤，遂終專權，後二年殺子赤，立宣公。〔三〕左氏傳曰：「聖人在上無雹，雖有不為災。」說曰：凡物不為災不書，書大，言為災也。凡雹，皆冬之愆陽，夏之伏陰也。〔四〕","sentenceOrder":165},
  {"id":"s_work_han_thu_35_166","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「霰，雨雪雜下，音先見反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_35_167","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　孟康曰：「投湯器中，以沈寒泉而成也。」師古曰：「湛讀曰沈。」","sentenceOrder":167},
  {"id":"s_work_han_thu_35_168","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「公子遂，東門襄仲也。赤，文公太子，即惡也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_35_169","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「愆，過也。過陽，冬溫也。伏陰，夏寒也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_35_170","chapterId":"ch_work_han_thu_35","textTraditional":"昭公三年，「大雨雹」。是時季氏專權，脅君之象見。昭公不寤，後季氏卒逐昭公。","sentenceOrder":170},
  {"id":"s_work_han_thu_35_171","chapterId":"ch_work_han_thu_35","textTraditional":"元封三年十二月，雷雨雹，大如馬頭。宣帝地節四年五月，山陽濟陰雨雹如雞子，深二尺五寸，殺二十人，蜚鳥皆死。〔一〕其十月，大司馬霍禹宗族謀反，誅，霍皇后廢。","sentenceOrder":171},
  {"id":"s_work_han_thu_35_172","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「蜚讀曰飛。」","sentenceOrder":172},
  {"id":"s_work_han_thu_35_173","chapterId":"ch_work_han_thu_35","textTraditional":"成帝河平二年四月，楚國雨雹，大如斧，蜚鳥死。","sentenceOrder":173},
  {"id":"s_work_han_thu_35_174","chapterId":"ch_work_han_thu_35","textTraditional":"左傳曰釐公三十二年十二月己卯，晉文公卒，庚辰，將殯于曲沃，出絳，柩有聲如牛。劉向以為近鼓妖也。喪，凶事；聲如牛，怒象也。將有急怒之謀，以生兵革之禍。是時，秦穆公遣兵襲鄭而不假道，還，晉大夫先軫謂襄公曰，秦師過不假塗，請擊之。〔一〕遂要崤阨，〔二〕以敗秦師，匹馬觭輪無反者，〔三〕操之急矣。〔四〕晉不惟舊，而聽虐謀，結怨彊國，四被秦寇，禍流數世，凶惡之效也。〔五〕","sentenceOrder":174},
  {"id":"s_work_han_thu_35_175","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「先軫即原軫。」","sentenceOrder":175},
  {"id":"s_work_han_thu_35_176","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「即今之二崤山也。」","sentenceOrder":176},
  {"id":"s_work_han_thu_35_177","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　服虔曰：「觭音奇偶之奇。」師古曰：「觭，隻也。言盡虜獲之。觭音居宜反。」","sentenceOrder":177},
  {"id":"s_work_han_thu_35_178","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「操，持也。謂執持所虜獲也。操音千高反。」","sentenceOrder":178},
  {"id":"s_work_han_thu_35_179","chapterId":"ch_work_han_thu_35","textTraditional":"〔五〕　師古曰：「舊者，謂晉襄之父文公本為秦所納而得國，是舊恩也。虐謀，先軫之計也。四被秦寇，謂魯文二年秦孟明視帥師伐晉，三年秦伯伐晉濟河焚舟取王官及郊，十年秦伯伐晉取北徵，十二年秦伯伐晉取羈馬。禍流，謂自襄公至厲公，凡五君與秦構難也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_35_180","chapterId":"ch_work_han_thu_35","textTraditional":"哀帝建平二年四月乙亥朔，御史大夫朱博為丞相，少府趙玄為御史大夫，臨延登受策，有大聲如鍾鳴，〔一〕殿中郎吏陛者皆聞焉。〔二〕上以問黃門侍郎揚雄、李尋，尋對曰：「洪範所謂鼓妖者也。師法以為人君不聰，為眾所惑，空名得進，則有聲無形，不知所從生。其傳曰歲月日之中，則正卿受之。今以四月日加辰巳有異，是為中焉。正卿謂執政大臣也。宜退丞相、御史，以應天變。然雖不退，不出期年，其人自蒙其咎。」〔三〕揚雄亦以為鼓妖，聽失之象也。朱博為人彊毅多權謀，宜將不宜相，恐有凶惡亟疾之怒。〔四〕八月，博、玄坐為姦謀，博自殺，玄減死論。京房易傳曰：「令不修本，下不安，金毋故自動，若有音。」","sentenceOrder":180},
  {"id":"s_work_han_thu_35_181","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「延入而登殿也。漢舊儀云丞相御史大夫初拜，皇帝延登親詔也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_35_182","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「陛者，謂執兵列於陛側。」","sentenceOrder":182},
  {"id":"s_work_han_thu_35_183","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「期年，十二月也。蒙猶被也。期音基。」","sentenceOrder":183},
  {"id":"s_work_han_thu_35_184","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「亟，急也，音居力反。」","sentenceOrder":184},
  {"id":"s_work_han_thu_35_185","chapterId":"ch_work_han_thu_35","textTraditional":"史記秦二世元年，天無雲而雷。劉向以為雷當託於雲，猶君託於臣，陰陽之合也。二世不恤天下，萬民有怨畔之心。是歲陳勝起，天下畔，趙高作亂，秦遂以亡。一曰，易震為雷，為貌不恭也。","sentenceOrder":185},
  {"id":"s_work_han_thu_35_186","chapterId":"ch_work_han_thu_35","textTraditional":"史記秦始皇八年，河魚大上。劉向以為近魚孽也。是歲，始皇弟長安君將兵擊趙，反，死屯留，軍吏皆斬，遷其民於臨洮。〔一〕明年有嫪（毒）〔毐〕之誅。魚陰類，民之象，逆流而上者，民將不從君令為逆行也。其在天文，魚星中河而處，車騎滿野。至于二世，暴虐愈甚，終用急亡。京房易傳曰：「眾逆同志，厥妖河魚逆流上。」","sentenceOrder":186},
  {"id":"s_work_han_thu_35_187","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「本使長安君擊趙，至屯留而謀反作亂，故賜長安君死，斬其軍吏，遷其黔首也。屯留，上黨縣也。臨洮，即今之洮州也。屯音純。洮音土高反。」","sentenceOrder":187},
  {"id":"s_work_han_thu_35_188","chapterId":"ch_work_han_thu_35","textTraditional":"武帝元鼎五年秋，蛙與蝦蟆群鬥。〔一〕是歲，四將軍眾十萬征南越，〔二〕開九郡。〔三〕","sentenceOrder":188},
  {"id":"s_work_han_thu_35_189","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「蛙音胡媧反。蝦音遐。蟆音麻。」","sentenceOrder":189},
  {"id":"s_work_han_thu_35_190","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「謂伏波將軍路博德出桂陽下皇水，樓船將軍楊僕出豫章下湞水，歸義越侯嚴為戈船將軍出零陵下離水，田甲為下瀨將軍下蒼梧。」","sentenceOrder":190},
  {"id":"s_work_han_thu_35_191","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「謂得越地以為南海、蒼梧、鬱林、合浦、交趾、九真、日南、珠崖、儋耳郡也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_35_192","chapterId":"ch_work_han_thu_35","textTraditional":"成帝鴻嘉四年秋，雨魚于信都，長五寸以下。成帝永始元年春，北海出大魚，長六丈，高一丈，四枚。哀帝建平三年，東萊平度出大魚，〔一〕長八丈，高丈一尺，七枚，皆死。京房易傳曰：「海數見巨魚，邪人進，賢人疏。」〔二〕","sentenceOrder":192},
  {"id":"s_work_han_thu_35_193","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「平度，東萊之縣。」","sentenceOrder":193},
  {"id":"s_work_han_thu_35_194","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「數音所角反。」","sentenceOrder":194},
  {"id":"s_work_han_thu_35_195","chapterId":"ch_work_han_thu_35","textTraditional":"桓公五年「秋，螽」。〔一〕劉歆以為貪虐取民則螽，介蟲之孽也，與魚同占。劉向以為介蟲之孽屬言不從。是歲，公獲二國之聘，取鼎易邑，〔二〕興役起城。〔三〕諸螽略皆從董仲舒說云。","sentenceOrder":195},
  {"id":"s_work_han_thu_35_196","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「螽即阜螽，即今之蝩蟲也。螽音終。蝩音之庸反。」","sentenceOrder":196},
  {"id":"s_work_han_thu_35_197","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「二國，宋、鄭也。宋以郜鼎賂公，鄭以泰山之田易許田也。」","sentenceOrder":197},
  {"id":"s_work_han_thu_35_198","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「謂五年夏城祝丘也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_35_199","chapterId":"ch_work_han_thu_35","textTraditional":"嚴公二十九年「有蜚」。劉歆以為負蠜也，性不食穀，食穀為災，介蟲之孽。〔一〕劉向以為蜚色青，近青眚也，非中國所有。南越盛暑，男女同川澤，淫風所生，為蟲臭惡。〔二〕是時嚴公取齊淫女為夫人，既入，淫於兩叔，故蜚至。天戒若曰，今誅絕之尚及，不將生臭惡，聞於四方。嚴不寤，其後夫人與兩叔作亂，二嗣以殺，〔三〕卒皆被辜。〔四〕董仲舒指略同。","sentenceOrder":199},
  {"id":"s_work_han_thu_35_200","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「蜚音伏味反。蠜音煩。」","sentenceOrder":200},
  {"id":"s_work_han_thu_35_201","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「蜚者，中國所有，非南越之蟲，未詳向所說。」","sentenceOrder":201},
  {"id":"s_work_han_thu_35_202","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「二嗣，謂子般及閔公也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_35_203","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「謂二叔、哀姜皆不得其死也。已解於上。」","sentenceOrder":203},
  {"id":"s_work_han_thu_35_204","chapterId":"ch_work_han_thu_35","textTraditional":"釐公十五年「八月，螽」。劉向以為先是釐有鹹之會，後城緣陵，〔一〕是歲復以兵車為牡丘會，使公孫敖帥師，及諸侯大夫救徐，〔二〕兵比三年在外。〔三〕","sentenceOrder":204},
  {"id":"s_work_han_thu_35_205","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「僖十（二）〔三〕年，公會齊侯、宋公、陳侯、衛侯、鄭伯、許男、曹伯于鹹。鹹，衛地。十四年而與諸侯城緣陵。緣陵，杞邑也。」","sentenceOrder":205},
  {"id":"s_work_han_thu_35_206","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「十五年公會齊侯、宋公、陳侯、衛侯、鄭伯、許男、曹伯，盟于牡丘，遂次于匡。公孫敖帥師，及諸侯之大夫救徐。公孫敖，孟穆伯也。諸侯之大夫，即所與會諸侯也。時楚伐徐，故救之。」","sentenceOrder":206},
  {"id":"s_work_han_thu_35_207","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「比，頻也。」","sentenceOrder":207},
  {"id":"s_work_han_thu_35_208","chapterId":"ch_work_han_thu_35","textTraditional":"文公三年「秋，雨螽于宋」。劉向以為先是宋殺大夫而無罪〔一〕，有暴虐賦斂之應。〔二〕穀梁傳曰上下皆合，言甚。〔三〕董仲舒以為宋三世內取，〔四〕大夫專恣，殺生不中，〔五〕故螽先死而至。劉歆以為螽為穀災，卒遇賊陰，墜而死也。","sentenceOrder":208},
  {"id":"s_work_han_thu_35_209","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「謂僖二十五年經書『宋殺其大夫』，不書名，以其無罪。」","sentenceOrder":209},
  {"id":"s_work_han_thu_35_210","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「謂宋昭公也。」","sentenceOrder":210},
  {"id":"s_work_han_thu_35_211","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「上下皆合，螽之多。」","sentenceOrder":211},
  {"id":"s_work_han_thu_35_212","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「三世，謂襄公、成公、昭公也。內取於國之大夫也。事見公羊傳。取讀曰娶。」","sentenceOrder":212},
  {"id":"s_work_han_thu_35_213","chapterId":"ch_work_han_thu_35","textTraditional":"〔五〕　師古曰：「中音竹仲反。」","sentenceOrder":213},
  {"id":"s_work_han_thu_35_214","chapterId":"ch_work_han_thu_35","textTraditional":"八年「十月，螽」。時公伐邾取須朐，城郚。〔一〕","sentenceOrder":214},
  {"id":"s_work_han_thu_35_215","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「須朐，邾邑；郚，魯邑也。事並在文七年。朐音鉅俱反。郚音吾。」","sentenceOrder":215},
  {"id":"s_work_han_thu_35_216","chapterId":"ch_work_han_thu_35","textTraditional":"宣公六年「八月，螽」。劉向以為先是時宣伐莒向，〔一〕後比再如齊，謀伐萊。〔二〕","sentenceOrder":216},
  {"id":"s_work_han_thu_35_217","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「事在四年。向，莒邑也。向音餉。」","sentenceOrder":217},
  {"id":"s_work_han_thu_35_218","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「比，頻也。謂四年秋及五年春公如齊，七年公會齊侯伐萊是也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_35_219","chapterId":"ch_work_han_thu_35","textTraditional":"十三年「秋，螽」。公孫歸父會齊伐莒。〔一〕","sentenceOrder":219},
  {"id":"s_work_han_thu_35_220","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「事在十一年。歸父，東門襄仲子也，字子家。父讀曰甫。」","sentenceOrder":220},
  {"id":"s_work_han_thu_35_221","chapterId":"ch_work_han_thu_35","textTraditional":"十五年「秋，螽」。宣亡熟歲，數有軍旅。","sentenceOrder":221},
  {"id":"s_work_han_thu_35_222","chapterId":"ch_work_han_thu_35","textTraditional":"襄公七年「八月，螽」。劉向以為先是襄興師救陳，〔一〕滕子、郯子、小邾子皆來朝。〔二〕夏，城費。〔三〕","sentenceOrder":222},
  {"id":"s_work_han_thu_35_223","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「謂五年楚伐陳，公會晉侯、宋公、衛侯、鄭伯、齊太子光救陳也。」","sentenceOrder":223},
  {"id":"s_work_han_thu_35_224","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「六年滕子來朝，七年郯子、小邾子來朝。」","sentenceOrder":224},
  {"id":"s_work_han_thu_35_225","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「亦七年之夏。費，魯邑也。音祕。」","sentenceOrder":225},
  {"id":"s_work_han_thu_35_226","chapterId":"ch_work_han_thu_35","textTraditional":"哀公十二年「十二月，螽」。是時哀用田賦。〔一〕劉向以為春用田賦，冬而螽。","sentenceOrder":226},
  {"id":"s_work_han_thu_35_227","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「言重斂也。解在刑法志。」","sentenceOrder":227},
  {"id":"s_work_han_thu_35_228","chapterId":"ch_work_han_thu_35","textTraditional":"十三年「九月，螽；十二月，螽」。比三螽，虐取於民之效也。〔一〕劉歆以為周十二月，夏十月也，火星既伏，蟄蟲皆畢，天之見變，因物類之宜，不得以螽，是歲再失閏矣。周九月，夏七月，故傳曰「火猶西流，司曆過也」。","sentenceOrder":228},
  {"id":"s_work_han_thu_35_229","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「比，頻也。」","sentenceOrder":229},
  {"id":"s_work_han_thu_35_230","chapterId":"ch_work_han_thu_35","textTraditional":"宣公十五年「冬，蝝生」。〔一〕劉歆以為蝝，螕〈蠹，中“石改{缶木}”〉之有翼者，〔二〕食穀為災，黑眚也。董仲舒、劉向以為蝝，螟始生也，一曰（螟）〔蝗〕始生。是時民患上力役，解於公田。〔三〕宣是時初稅畝。稅畝，就民田畝擇美者稅其什一，亂先王制而為貪利，故應是而蝝生，屬蠃蟲之孽。","sentenceOrder":230},
  {"id":"s_work_han_thu_35_231","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「爾雅曰『蝝，蝮蜪』，說者以為螽蝗之類。蝮音蒲北反，又音服。蜪音徒高反。」","sentenceOrder":231},
  {"id":"s_work_han_thu_35_232","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　孟康曰：「螕〈蠹，中“石改{缶木}”〉，音蚍蜉。」","sentenceOrder":232},
  {"id":"s_work_han_thu_35_233","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「解讀曰懈。」","sentenceOrder":233},
  {"id":"s_work_han_thu_35_234","chapterId":"ch_work_han_thu_35","textTraditional":"景帝中三年秋，蝗。先是匈奴寇邊，中尉不害將車騎材官士屯代高柳。〔一〕","sentenceOrder":234},
  {"id":"s_work_han_thu_35_235","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「魏不害。」","sentenceOrder":235},
  {"id":"s_work_han_thu_35_236","chapterId":"ch_work_han_thu_35","textTraditional":"武帝元光五年秋，螟；六年夏，蝗。先是，五將軍眾三十萬伏馬邑，欲襲單于也。〔一〕是歲，四將軍征匈奴。〔二〕","sentenceOrder":236},
  {"id":"s_work_han_thu_35_237","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「已解于上。」","sentenceOrder":237},
  {"id":"s_work_han_thu_35_238","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「謂車騎將軍衛青出上谷，騎將軍公孫敖出代，輕車將軍公孫賀出雲中，驍騎將軍李廣出雁門也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_35_239","chapterId":"ch_work_han_thu_35","textTraditional":"元鼎五年秋，蝗。是歲，四將軍征南越〔一〕及西南夷，〔二〕開十餘郡。〔三〕","sentenceOrder":239},
  {"id":"s_work_han_thu_35_240","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「已解於上。」","sentenceOrder":240},
  {"id":"s_work_han_thu_35_241","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「越（騎）〔馳〕義侯遺將巴蜀罪人發夜郎兵征西南夷，平之。」","sentenceOrder":241},
  {"id":"s_work_han_thu_35_242","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「定越地為九郡，定西南夷為武都、牂柯、越嶲、沈黎、汶山郡，凡十四郡。」","sentenceOrder":242},
  {"id":"s_work_han_thu_35_243","chapterId":"ch_work_han_thu_35","textTraditional":"元封六年秋，蝗。先是，兩將軍征朝鮮，〔一〕開三郡。〔二〕","sentenceOrder":243},
  {"id":"s_work_han_thu_35_244","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「二年，樓船將軍楊僕、左將軍荀彘將應募罪人擊之。」","sentenceOrder":244},
  {"id":"s_work_han_thu_35_245","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「武紀云以其地為樂浪、臨屯、玄菟、真番郡，是四郡也，而此云三，蓋傳寫志者誤。」","sentenceOrder":245},
  {"id":"s_work_han_thu_35_246","chapterId":"ch_work_han_thu_35","textTraditional":"太初元年夏，蝗從東方蜚至敦煌；〔一〕三年秋，復蝗。元年貳師將軍征大宛，天下奉其役連年。","sentenceOrder":246},
  {"id":"s_work_han_thu_35_247","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「蜚讀曰飛。」","sentenceOrder":247},
  {"id":"s_work_han_thu_35_248","chapterId":"ch_work_han_thu_35","textTraditional":"征和三年秋，蝗；四年夏，蝗。先是一年，三將軍眾十餘萬征匈奴。〔一〕征和三年，貳師七萬人沒不還。","sentenceOrder":248},
  {"id":"s_work_han_thu_35_249","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「謂三年貳師將軍廣利將七萬人出五原，御史大夫商丘成二萬人出西河，重合侯馬通四萬騎出酒泉。」","sentenceOrder":249},
  {"id":"s_work_han_thu_35_250","chapterId":"ch_work_han_thu_35","textTraditional":"平帝元始二年秋，蝗，遍天下。是時王莽秉政。","sentenceOrder":250},
  {"id":"s_work_han_thu_35_251","chapterId":"ch_work_han_thu_35","textTraditional":"左氏傳曰嚴公八年齊襄公田于貝丘，〔一〕見豕。從者曰：「公子彭生也。」公怒曰：「射之！」豕人立而啼，公懼，墜車，傷足喪屨。劉向以為近豕禍也。先是，齊襄淫於妹魯桓公夫人，使公子彭生殺（威）〔桓〕公，又殺彭生以謝魯。公孫無知有寵於先君，襄公絀之，〔二〕無知帥怨恨之徒攻襄於田所，〔三〕襄匿其戶間，足見於戶下，遂殺之。傷足喪屨，卒死於足，虐急之效也。","sentenceOrder":251},
  {"id":"s_work_han_thu_35_252","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「貝丘，齊地。」","sentenceOrder":252},
  {"id":"s_work_han_thu_35_253","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「無知，僖公弟，夷仲年之子也，於襄公從父昆弟。先君即僖公。」","sentenceOrder":253},
  {"id":"s_work_han_thu_35_254","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「怨恨之徒，謂連稱、管至父久戍葵丘也。」","sentenceOrder":254},
  {"id":"s_work_han_thu_35_255","chapterId":"ch_work_han_thu_35","textTraditional":"昭帝元鳳元年，燕王宮永巷中豕出圂，壞都灶，〔一〕銜其釜六七枚置殿前。〔二〕劉向以為近豕禍也。時燕王旦與長公主、左將軍謀為大逆，誅殺諫者，暴急無道。灶者，生養之本，豕而敗灶，陳釜於庭，釜灶將不用，宮室將廢辱也。燕王不改，卒伏其辜。京房易傳曰：「眾心不安君政，厥妖豕入居室。」","sentenceOrder":255},
  {"id":"s_work_han_thu_35_256","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「圂者，養豕之牢也。都灶，烝炊之大灶也。圂音胡頓反。」","sentenceOrder":256},
  {"id":"s_work_han_thu_35_257","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　晉灼曰：「鬴，古文釜字。」","sentenceOrder":257},
  {"id":"s_work_han_thu_35_258","chapterId":"ch_work_han_thu_35","textTraditional":"史記魯襄公二十三年，穀、洛水鬥，將毀王宮。劉向以為近火沴水也。周靈王將擁之，有司諫曰：「不可。長民者不崇藪，不墮山，不防川，不竇澤。〔一〕今吾執政毋乃有所辟，〔二〕而滑夫二川之神，〔三〕使至于爭明，〔四〕以防王宮室，王而飾之，毋乃不可乎！〔五〕懼及子孫，王室愈卑。」王卒擁之。以傳推之，以四瀆比諸侯，穀、洛其次，卿大夫之象也，〔六〕為卿大夫將分爭以危亂王室也。是時世卿專權，儋括將有篡殺之謀，〔七〕如靈王覺寤，匡其失政，〔八〕懼以承戒，則災禍除矣。不聽諫謀，簡嫚大異，〔九〕任其私心，塞埤擁下，〔一０〕以逆水勢而害鬼神。後數年有黑如日者五。是歲蚤霜，靈王崩。景王立二年，儋括欲殺王，而立王弟佞夫。佞夫不知，景王并誅佞夫。〔一一〕及景王死，五大夫爭權，或立子猛，或立子朝，王室大亂。〔一二〕京房易傳曰：「天子弱，諸侯力政，〔一三〕厥異水鬥。」","sentenceOrder":258},
  {"id":"s_work_han_thu_35_259","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　師古曰：「長萌為萌之長也。崇，聚也。藪謂澤之無水者。墮，毀也。防，止也。竇，穴也。墮音火規反。」","sentenceOrder":259},
  {"id":"s_work_han_thu_35_260","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　服虔曰：「音邪辟之辟。」","sentenceOrder":260},
  {"id":"s_work_han_thu_35_261","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「滑，亂也，音骨。」","sentenceOrder":261},
  {"id":"s_work_han_thu_35_262","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　臣瓚曰：「明，水道也。」師古曰：「明謂神靈。」","sentenceOrder":262},
  {"id":"s_work_han_thu_35_263","chapterId":"ch_work_han_thu_35","textTraditional":"〔五〕　師古曰：「言為欲防固王宮，使水不得毀，故遏飾二川。」","sentenceOrder":263},
  {"id":"s_work_han_thu_35_264","chapterId":"ch_work_han_thu_35","textTraditional":"〔六〕　師古曰：「穀、洛皆大水，故為四瀆之次。」","sentenceOrder":264},
  {"id":"s_work_han_thu_35_265","chapterId":"ch_work_han_thu_35","textTraditional":"〔七〕　師古曰：「儋括，儋季之子，簡王之孫也。篡殺之謀，謂除喪服，將見靈王，過庭而歎曰『嗚呼，必有此夫！』」","sentenceOrder":265},
  {"id":"s_work_han_thu_35_266","chapterId":"ch_work_han_thu_35","textTraditional":"〔八〕　師古曰：「匡，正也。」","sentenceOrder":266},
  {"id":"s_work_han_thu_35_267","chapterId":"ch_work_han_thu_35","textTraditional":"〔九〕　師古曰：「諫謀，謂單公子愆旗聞儋括之言，恐必為害，請殺之，王不聽也。簡嫚大異，謂不憂穀、洛。」","sentenceOrder":267},
  {"id":"s_work_han_thu_35_268","chapterId":"ch_work_han_thu_35","textTraditional":"〔一０〕師古曰：「埤，卑也，音婢。」","sentenceOrder":268},
  {"id":"s_work_han_thu_35_269","chapterId":"ch_work_han_thu_35","textTraditional":"〔一一〕師古曰：「事在襄三十年。」","sentenceOrder":269},
  {"id":"s_work_han_thu_35_270","chapterId":"ch_work_han_thu_35","textTraditional":"〔一二〕師古曰：「五大夫，謂劉子、單子、尹氏、召伯、毛伯也。已解於上。」","sentenceOrder":270},
  {"id":"s_work_han_thu_35_271","chapterId":"ch_work_han_thu_35","textTraditional":"〔一三〕師古曰：「政亦征也，言專以武力相征討。一說，諸侯之政，當以德禮，今王室微弱，文教不行，遂乃以力為政，相攻伐也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_35_272","chapterId":"ch_work_han_thu_35","textTraditional":"史記曰，秦武王三年渭水赤者三日，昭王三十四年渭水又赤三日。劉向以為近火沴水也。秦連相坐之法，棄灰於道者黥，〔一〕罔密而刑虐，加以武伐橫出，殘賊鄰國，至於變亂五行，氣色謬亂。天戒若曰，勿為刻急，將致敗亡。秦遂不改，至始皇滅六國，二世而亡。昔三代居三河，河洛出圖書，〔二〕秦居渭陽，而渭水數赤，〔三〕瑞異應德之效也。京房易傳曰：「君湎于酒，淫于色，〔四〕賢人潛，國家危，厥異流水赤也。」","sentenceOrder":272},
  {"id":"s_work_han_thu_35_273","chapterId":"ch_work_han_thu_35","textTraditional":"〔一〕　孟康曰：「商鞅為政，以棄灰於道必坋人，坋人必鬥，故設黥刑以絕其原也。」臣瓚曰：「棄灰或有火，火則燔廬舍，故刑之也。」師古曰：「孟說是也。坋音蒲頓反。」","sentenceOrder":273},
  {"id":"s_work_han_thu_35_274","chapterId":"ch_work_han_thu_35","textTraditional":"〔二〕　師古曰：「謂夏即安邑，即河東也；殷都朝歌，即河內也；周都洛陽，即河南也。」","sentenceOrder":274},
  {"id":"s_work_han_thu_35_275","chapterId":"ch_work_han_thu_35","textTraditional":"〔三〕　師古曰：「數音山角反。」","sentenceOrder":275},
  {"id":"s_work_han_thu_35_276","chapterId":"ch_work_han_thu_35","textTraditional":"〔四〕　師古曰：「湎，流也，音莫踐反。」","sentenceOrder":276},
  {"id":"s_work_han_thu_35_277","chapterId":"ch_work_han_thu_35","textTraditional":"校勘記","sentenceOrder":277},
  {"id":"s_work_han_thu_35_278","chapterId":"ch_work_han_thu_35","textTraditional":"一四０六頁　三行　羊上角下（號）〔蹄〕，　景祐、殿本都作「蹄」。","sentenceOrder":278},
  {"id":"s_work_han_thu_35_279","chapterId":"ch_work_han_thu_35","textTraditional":"一四０九頁一一行　五為天位，（為）君位。　景祐本無下「為」字。","sentenceOrder":279},
  {"id":"s_work_han_thu_35_280","chapterId":"ch_work_han_thu_35","textTraditional":"一四一０頁　四行　伊（涉）〔陟〕相太戊，　景祐、殿、局本都作「陟」。王先謙說作「陟」是。","sentenceOrder":280},
  {"id":"s_work_han_thu_35_281","chapterId":"ch_work_han_thu_35","textTraditional":"一四一二頁　三行　故冬（華）華者，　王念孫說景祐本作「故冬華者」是也。「華」字不宜疊。","sentenceOrder":281},
  {"id":"s_work_han_thu_35_282","chapterId":"ch_work_han_thu_35","textTraditional":"一四一八頁一二行　讇，古諂（也）〔字〕。　朱一新說汪本「也」作「字」，是。按殿本作「字也」。","sentenceOrder":282},
  {"id":"s_work_han_thu_35_283","chapterId":"ch_work_han_thu_35","textTraditional":"一四二一頁　五行　與諸呂同（眾）〔象〕。　景祐、殿本都作「象」。朱一新說作「象」是。","sentenceOrder":283},
  {"id":"s_work_han_thu_35_284","chapterId":"ch_work_han_thu_35","textTraditional":"一四二三頁　四行　而桓有妒（媚）〔媢〕之心，景祐、殿、局本都作「媢」。葉德輝說作「媢」是。","sentenceOrder":284},
  {"id":"s_work_han_thu_35_285","chapterId":"ch_work_han_thu_35","textTraditional":"一四二三頁　五行　董仲舒以為象（大）〔夫〕人專恣，　景祐、殿本都作「夫」。王先謙說作「夫」是。","sentenceOrder":285},
  {"id":"s_work_han_thu_35_286","chapterId":"ch_work_han_thu_35","textTraditional":"一四二六頁　五行　釐公二年　按左、公、穀經都在僖公三十三年。","sentenceOrder":286},
  {"id":"s_work_han_thu_35_287","chapterId":"ch_work_han_thu_35","textTraditional":"一四三０頁　七行　明年有嫪（毒）〔毐〕之誅。　景祐、殿本都作「毐」，此誤。","sentenceOrder":287},
  {"id":"s_work_han_thu_35_288","chapterId":"ch_work_han_thu_35","textTraditional":"一四三二頁一０行　僖十（二）〔三〕年，　景祐、殿本都作「三」，左傳亦作「三」。","sentenceOrder":288},
  {"id":"s_work_han_thu_35_289","chapterId":"ch_work_han_thu_35","textTraditional":"一四三四頁一一行　一曰（螟）〔蝗〕始生。　葉德輝說「螟」為「蝗」之誤，既云「一曰」，則非「螟」明矣。","sentenceOrder":289},
  {"id":"s_work_han_thu_35_290","chapterId":"ch_work_han_thu_35","textTraditional":"一四三五頁　八行　越（騎）〔馳〕義侯遺景祐、殿本都作「馳」。王先謙說作「馳」是。","sentenceOrder":290},
  {"id":"s_work_han_thu_35_291","chapterId":"ch_work_han_thu_35","textTraditional":"一四三六頁　六行　殺（威）〔桓〕公，　景祐、殿本都作「桓」。","sentenceOrder":291},
  {"id":"s_work_han_thu_36_1","chapterId":"ch_work_han_thu_36","textTraditional":"傳曰：「思心之不睿，是謂不聖，厥咎霿，〔一〕厥罰恆風，厥極凶短折。時則有脂夜之妖，時則有華孽，時則有牛禍，時則有心腹之痾，時則有黃眚黃祥，時則有金木水火沴土。」","sentenceOrder":1},
  {"id":"s_work_han_thu_36_2","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「霿音莫豆反。」","sentenceOrder":2},
  {"id":"s_work_han_thu_36_3","chapterId":"ch_work_han_thu_36","textTraditional":"「思心之不睿，是謂不聖。」思心者，心思慮也；睿，寬也。孔子曰：「居上不寬，吾何以觀之哉！」〔一〕言上不寬大包容臣下，則不能居聖位。貌言視聽，以心為主，四者皆失，則區霿無識，〔二〕故其咎霿也。雨旱寒奧，亦以風為本，〔三〕四氣皆亂，故其罰常風也。常風傷物，故其極凶短折也。傷人曰凶，禽獸曰短，屮木曰折。〔四〕一曰，凶，夭也；兄喪弟曰短，父喪子曰折。在人腹中，肥而包裹心者脂也，心區霿則冥晦，故有脂夜之妖。〔五〕一曰，有脂物而夜為妖，若脂水夜汙人衣，淫之象也。一曰，夜妖者，雲風並起而杳冥，故與常風同象也。溫而風則生螟螣，〔六〕有裸蟲之孽〔七〕。劉向以為於易巽為風為木，卦在三月四月，繼陽而治，主木之華實。風氣盛，至秋冬木復華，故有華孽。一曰，地氣盛則秋冬復華。一曰，華者色也，土為內事，為女孽也。於易坤為土為牛，牛大心而不能思慮，思心氣毀，故有牛禍。一曰，牛多死及為怪，亦是也。及人，則多病心腹者，故有心腹之痾。土色黃，故有黃眚黃祥。凡思心傷者病土氣，土氣病則金木水火沴之，故曰「時則有金木水火沴土」。不言「惟」而獨曰「時則有」者，非一衝氣所沴，明其異大也。其極曰凶短折，順之，其福曰考終命。〔八〕劉歆思心傳曰時則有臝蟲之孽，謂螟螣之屬也。庶徵之常風，劉向以為春秋無其應。","sentenceOrder":3},
  {"id":"s_work_han_thu_36_4","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「論語載孔子之言。」","sentenceOrder":4},
  {"id":"s_work_han_thu_36_5","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「區音口豆反。霿音莫豆反。其下並同。」","sentenceOrder":5},
  {"id":"s_work_han_thu_36_6","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「奧音於六反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_36_7","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　師古曰：「屮，古草字。」","sentenceOrder":7},
  {"id":"s_work_han_thu_36_8","chapterId":"ch_work_han_thu_36","textTraditional":"〔五〕　師古曰：「脂妖及夜妖。」","sentenceOrder":8},
  {"id":"s_work_han_thu_36_9","chapterId":"ch_work_han_thu_36","textTraditional":"〔六〕　師古曰：「螣音徒得反。」","sentenceOrder":9},
  {"id":"s_work_han_thu_36_10","chapterId":"ch_work_han_thu_36","textTraditional":"〔七〕　師古曰：「裸亦臝字也，從衣果聲。」","sentenceOrder":10},
  {"id":"s_work_han_thu_36_11","chapterId":"ch_work_han_thu_36","textTraditional":"〔八〕　師古曰：「壽考而終其命。」","sentenceOrder":11},
  {"id":"s_work_han_thu_36_12","chapterId":"ch_work_han_thu_36","textTraditional":"釐公十六年「正月，六鶂退蜚，過宋都」。〔一〕左氏傳曰「風也」。劉歆以為風發於它所，至宋而高，鶂高蜚而逢之，則退。經以見者為文，故記退蜚；傳以實應著，言風，常風之罰也。象宋襄公區霿自用，不容臣下，逆司馬子魚之諫，而與彊楚爭盟，〔二〕後六年為楚所執，〔三〕應六鶂之數云。京房易傳曰：「潛龍勿用，〔四〕眾逆同志，至德乃潛，厥異風。其風也，行不解物，不長，〔五〕雨小而傷。政悖德隱茲謂亂，厥風先風不雨，大風暴起，發屋折木。守義不進茲謂耄，厥風與雲俱起，折五穀莖。臣易上政，茲謂不順，厥風大焱發屋。〔六〕賦斂不理茲謂禍，厥風絕經（紀）〔緯〕，〔七〕止即溫，溫即蟲。侯專封茲謂不統，厥風疾，而樹不搖，穀不成。辟不思道利，茲謂無澤，〔八〕厥風不搖木，旱無雲，傷禾。公常於利茲謂亂，〔九〕厥風微而溫，生蟲蝗，害五穀。棄正作淫茲謂惑，厥風溫，螟蟲起，害有益人之物。侯不朝茲謂叛，厥風無恆，地變赤而殺人。」","sentenceOrder":12},
  {"id":"s_work_han_thu_36_13","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「鶂音五狄反。」","sentenceOrder":13},
  {"id":"s_work_han_thu_36_14","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「子魚，公子目夷也，桓公之子，而為司馬。爭盟，謂為鹿上之盟，以求諸侯於楚。子魚諫曰：『小國爭盟，禍也。』公不聽之。」","sentenceOrder":14},
  {"id":"s_work_han_thu_36_15","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「僖二十一年，楚執宋公以伐宋，距六鶂退飛凡六年。」","sentenceOrder":15},
  {"id":"s_work_han_thu_36_16","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　師古曰：「乾初九爻辭。」","sentenceOrder":16},
  {"id":"s_work_han_thu_36_17","chapterId":"ch_work_han_thu_36","textTraditional":"〔五〕　師古曰：「不解物，謂物逢之而不解散也。不長，所起者近也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_36_18","chapterId":"ch_work_han_thu_36","textTraditional":"〔六〕　師古曰：「焱，疾風也，音必遙反。」","sentenceOrder":18},
  {"id":"s_work_han_thu_36_19","chapterId":"ch_work_han_thu_36","textTraditional":"〔七〕　如淳曰：「有所破壞，絕匹帛之屬也。」晉灼曰：「南北為經，東西為緯，絲因風暴，亂不端理也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_36_20","chapterId":"ch_work_han_thu_36","textTraditional":"〔八〕　師古曰：「道讀曰導，不思導示於下而安利之。」","sentenceOrder":20},
  {"id":"s_work_han_thu_36_21","chapterId":"ch_work_han_thu_36","textTraditional":"〔九〕　師古曰：「公，上爵也。常於利，謂心常求利也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_36_22","chapterId":"ch_work_han_thu_36","textTraditional":"文帝二年六月，淮南王都壽春大風毀民室，殺人。劉向以為是歲南越反，攻淮南邊，淮南王長破之，後年入朝，殺漢故丞相辟陽侯，上赦之，歸聚姦人謀逆亂，自稱東帝，見異不寤，後遷于蜀，道死廱。","sentenceOrder":22},
  {"id":"s_work_han_thu_36_23","chapterId":"ch_work_han_thu_36","textTraditional":"文帝五年，吳暴風雨，壞城官府民室。時吳王濞謀為逆亂，天戒數見，終不改寤，後卒誅滅。","sentenceOrder":23},
  {"id":"s_work_han_thu_36_24","chapterId":"ch_work_han_thu_36","textTraditional":"五年十月，楚王都彭城大風從東南來，毀巿門，殺人。是月王戊初嗣立，後坐淫削國，與吳王謀反，刑僇諫者。〔一〕吳在楚東南，天戒若曰，勿與吳為惡，將敗巿朝。王戊不寤，卒隨吳亡。","sentenceOrder":24},
  {"id":"s_work_han_thu_36_25","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「謂楚相張尚、太傅趙夷吾也。僇，古戮字。下皆類此。」","sentenceOrder":25},
  {"id":"s_work_han_thu_36_26","chapterId":"ch_work_han_thu_36","textTraditional":"昭帝元鳳元年，燕王都薊大風雨，〔一〕拔宮中樹七圍以上十六枚，壞城樓。燕王旦不寤，謀反發覺，卒伏其辜。","sentenceOrder":26},
  {"id":"s_work_han_thu_36_27","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「薊，縣名，燕國之所都。」","sentenceOrder":27},
  {"id":"s_work_han_thu_36_28","chapterId":"ch_work_han_thu_36","textTraditional":"釐公十五年「九月己卯晦，震夷伯之廟」。〔一〕劉向以為晦，暝也；震，雷也。夷伯，世大夫，正（書）〔晝〕雷，其廟獨冥〔二〕。天戒若曰，勿使大夫世官，將專事暝晦。明年，公子季友卒，果世官，〔三〕政在季氏。至成公十六年「六月甲午晦」，正晝皆暝，陰為陽，臣制君也。成公不寤，其冬季氏殺公子偃。〔四〕季氏萌於釐公，〔五〕大於成公，此其應也。董仲舒以為夷伯，季氏之孚也，〔六〕陪臣不當有廟。震者雷也，晦暝，雷擊其廟，明當絕去僭差之類也。向又以為此皆所謂夜妖者也。劉歆以為春秋及朔言朔，及晦言晦，人道所不及，則天震之。展氏有隱慝，故天加誅於其祖夷伯之廟以譴告之也。","sentenceOrder":28},
  {"id":"s_work_han_thu_36_29","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「夷伯，司空無駭之後，本魯公族也，號展氏。」","sentenceOrder":29},
  {"id":"s_work_han_thu_36_30","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「冥，暗也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_36_31","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「謂季友之孫行父仍執政專國，自此以後常為卿。」","sentenceOrder":31},
  {"id":"s_work_han_thu_36_32","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　師古曰：「為季文子所殺也。已解於上。」","sentenceOrder":32},
  {"id":"s_work_han_thu_36_33","chapterId":"ch_work_han_thu_36","textTraditional":"〔五〕　師古曰：「萌，喻草木始生也。言其始有（成）〔威〕權。」","sentenceOrder":33},
  {"id":"s_work_han_thu_36_34","chapterId":"ch_work_han_thu_36","textTraditional":"〔六〕　師古曰：「孚，信也。所信任之臣也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_36_35","chapterId":"ch_work_han_thu_36","textTraditional":"成公十六年「六月甲午晦，晉侯及楚子、鄭伯戰于鄢陵」。皆月晦云。","sentenceOrder":35},
  {"id":"s_work_han_thu_36_36","chapterId":"ch_work_han_thu_36","textTraditional":"隱公五年「秋，螟」。董仲舒、劉向以為時公觀漁于棠，貪利之應也。〔一〕劉歆以為又逆臧釐伯之諫，〔二〕貪利區霿，以生臝蟲之孽也。","sentenceOrder":36},
  {"id":"s_work_han_thu_36_37","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「棠，魯地也。陳漁者之事而觀之也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_36_38","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「臧僖伯，公子彄也，孝公之子，諫觀漁。」","sentenceOrder":38},
  {"id":"s_work_han_thu_36_39","chapterId":"ch_work_han_thu_36","textTraditional":"八年「九月，螟」。時鄭伯以邴將易許田，〔一〕有貪利心。京房易傳曰：「臣安祿茲謂貪，厥災蟲，蟲食根。德無常茲謂煩，蟲食葉。不絀無德，蟲食本。與東作爭，茲謂不時，〔二〕蟲食節。蔽惡生孽，蟲食心。」〔三〕","sentenceOrder":39},
  {"id":"s_work_han_thu_36_40","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「〔邴〕，鄭祀泰山之邑也，音彼命反。已解於上。」","sentenceOrder":40},
  {"id":"s_work_han_thu_36_41","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「奪農時也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_36_42","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「蔽謂惡人蔽君之明（謂）〔為〕災孽也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_36_43","chapterId":"ch_work_han_thu_36","textTraditional":"嚴公六年「秋，螟」。董仲舒、劉向以為先是衛侯朔出奔齊，齊侯會諸侯納朔，〔一〕許諸侯賂。〔二〕齊人歸衛寶，魯受之，〔三〕貪利應也。","sentenceOrder":43},
  {"id":"s_work_han_thu_36_44","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「朔謂惠公也。桓十六年，以左公子（涸）〔泄〕、右公子職立公子黔牟，故惠公奔齊。至莊五年，會齊人、宋人、蔡人伐衛而納惠公也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_36_45","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「諸國各有賂。」","sentenceOrder":45},
  {"id":"s_work_han_thu_36_46","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「以伐衛所獲之寶來歸魯。」","sentenceOrder":46},
  {"id":"s_work_han_thu_36_47","chapterId":"ch_work_han_thu_36","textTraditional":"文帝後六年秋，螟。是歲匈奴大入上郡、雲中，烽火通長安，遣三將軍屯邊，三將軍屯京師。〔一〕","sentenceOrder":47},
  {"id":"s_work_han_thu_36_48","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「並已解於上。」","sentenceOrder":48},
  {"id":"s_work_han_thu_36_49","chapterId":"ch_work_han_thu_36","textTraditional":"宣公三年，「郊牛之口傷，改卜牛，牛死」。劉向以為近牛禍也。是時宣公與公子遂謀共殺子赤而立，〔一〕又以喪娶，〔二〕區霿昏亂。亂成於口，幸有季文子得免於禍，天猶惡之，生則不饗其祀，〔三〕死則災燔其廟。〔四〕董仲舒指略同。","sentenceOrder":49},
  {"id":"s_work_han_thu_36_50","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「已解於上也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_36_51","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「宣元年正月，公子遂如齊逆女。三月，遂以夫人婦姜至自齊，時（成）〔文〕公喪制未除。」","sentenceOrder":51},
  {"id":"s_work_han_thu_36_52","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「謂郊牛傷死，是天不欲饗其祀。」","sentenceOrder":52},
  {"id":"s_work_han_thu_36_53","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　師古曰：「成三年，新宮災。新宮者，宣之廟也，以其新成，故謂之新宮。」","sentenceOrder":53},
  {"id":"s_work_han_thu_36_54","chapterId":"ch_work_han_thu_36","textTraditional":"秦孝文王五年，斿朐衍，有獻五足牛者。〔一〕劉向以為近牛禍也。先是文惠王初都咸陽，廣大宮室，南臨渭，北臨涇，思心失，逆土氣。足者止也，戒秦建止奢泰，將致危亡。〔二〕秦遂不改，至於離宮三百，復起阿房，未成而亡。一曰，牛以力為人用，足所以行也。其後秦大用民力轉輸，起負海至北邊，〔三〕天下叛之。京房易傳曰：「興繇役，奪民時，厥妖牛生五足。」","sentenceOrder":54},
  {"id":"s_work_han_thu_36_55","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「朐衍，地名，在北地。朐音許于反。」","sentenceOrder":55},
  {"id":"s_work_han_thu_36_56","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　如淳曰：「建立基止。泰，奢泰。」","sentenceOrder":56},
  {"id":"s_work_han_thu_36_57","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「負海，猶言背海也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_36_58","chapterId":"ch_work_han_thu_36","textTraditional":"景帝中六年，梁孝王田北山，有獻牛，足上出背上。劉向以為近牛禍。先是孝王驕奢，起苑方三百里，宮館閣道相連三十餘里。納於邪臣羊勝之計，欲求為漢嗣，刺殺議臣爰盎，事發，負斧歸死。既退歸國，猶有恨心，內則思慮霿亂，外則土功過制，故牛禍作。足而出於背，下奸上之象也。〔一〕猶不能自解，發疾暴死，又凶短之極也。","sentenceOrder":58},
  {"id":"s_work_han_thu_36_59","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「奸，犯也，音干。」","sentenceOrder":59},
  {"id":"s_work_han_thu_36_60","chapterId":"ch_work_han_thu_36","textTraditional":"左氏傳昭公二十一年春，周景王將鑄無〈身矢〉鍾，〔一〕泠州鳩曰：〔二〕「王其以心疾死乎！夫天子省風以作樂，〔三〕小者不窕，大者不摦。〔四〕摦則不容，心是以感，感實生疾。今鍾摦矣，王心弗（（暂缺F609））〔〈式，中“工改今”〉〕，〔五〕其能久乎？」劉向以為是時景王好聽淫聲，適庶不明，〔六〕思心霿亂，明年以心疾崩，近心腹之痾，凶短之極者也。","sentenceOrder":60},
  {"id":"s_work_han_thu_36_61","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「鍾聲中無〈身矢〉之律也。〈身矢〉音弋石反。」","sentenceOrder":61},
  {"id":"s_work_han_thu_36_62","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　應劭曰：「泠，官也。州鳩，名也。」師古曰：「樂官曰泠，後遂以為氏。泠音零，其字從水。」","sentenceOrder":62},
  {"id":"s_work_han_thu_36_63","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　應劭曰：「風，土地風俗也。省中和之風以作樂，然後可移惡風易惡俗也。」臣瓚曰：「省風俗之流遁，作樂以救其敝也。」師古曰：「應說是也。省，觀也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_36_64","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　師古曰：「窕，輕小也。摦，橫大也。窕音它堯反。摦音胡化反。」","sentenceOrder":64},
  {"id":"s_work_han_thu_36_65","chapterId":"ch_work_han_thu_36","textTraditional":"〔五〕　孟康曰：「古堪字。」","sentenceOrder":65},
  {"id":"s_work_han_thu_36_66","chapterId":"ch_work_han_thu_36","textTraditional":"〔六〕　師古曰：「適讀曰嫡。謂太子壽卒，王立子猛為嗣，後又欲立子朝也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_36_67","chapterId":"ch_work_han_thu_36","textTraditional":"昭二十五年春，魯叔孫昭子聘于宋，元公與燕，飲酒樂，語相泣也。〔一〕樂祈佐，〔二〕告人曰：「今茲君與叔孫其皆死乎！吾聞之，哀樂而樂哀，皆喪心也。〔三〕心之精爽，是謂魂魄；魂魄去之，何以能久？」冬十月，叔孫昭子死；十一月，宋元公卒。","sentenceOrder":67},
  {"id":"s_work_han_thu_36_68","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「昭子，叔孫婼也。元公，宋平公子也。相泣，相對而俱泣也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_36_69","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「樂祈，宋司城子梁也。佐，佐酒。」","sentenceOrder":69},
  {"id":"s_work_han_thu_36_70","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「哀樂，可樂而反哀也。樂哀，可哀而反樂也。喪，失之也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_36_71","chapterId":"ch_work_han_thu_36","textTraditional":"昭帝元鳳元年九月，燕有黃鼠銜其尾舞王宮端門中，往視之，鼠舞如故。王使夫人以酒脯祠，鼠舞不休，夜死。黃祥也。時燕剌王旦謀反將敗，死亡象也。其月，發覺伏辜。京房易傳曰：「誅不原情，厥妖鼠舞門。」","sentenceOrder":71},
  {"id":"s_work_han_thu_36_72","chapterId":"ch_work_han_thu_36","textTraditional":"成帝建始元年四月辛丑夜，西北有如火光。壬寅晨，大風從西北起，雲氣赤黃，四塞天下，終日夜下著地者黃土塵也。是歲，帝元舅大司馬大將軍王鳳始用事；又封鳳母弟崇為安成侯，食邑萬戶；庶弟譚等五人賜爵關內侯，食邑三千戶。〔一〕復益封鳳五千戶，悉封譚等為列侯，是為五侯。哀帝即位，封外屬丁氏、傅氏、周氏、鄭氏凡六人為列侯。〔二〕楊宣對曰：「五侯封日，天氣赤黃，丁、傅復然。〔三〕此殆爵土過制，傷亂土氣之祥也。」京房易傳曰：「經稱『觀其生』，〔四〕言大臣之義，當觀賢人，知其性行，推而貢之，否則為聞善不與，茲謂不知，〔五〕厥異黃，厥咎聾，厥災不嗣。黃者，日上黃光不散如火然，有黃濁氣四塞天下。蔽賢絕道，故災異至絕世也。經曰『良馬逐』。〔六〕逐，進也，言大臣得賢者謀，當顯進其人，否則為下相攘善，〔七〕茲謂盜明，厥咎亦不嗣，至於身僇家絕。」〔八〕","sentenceOrder":72},
  {"id":"s_work_han_thu_36_73","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「譚、商、音、根、逢時凡五人。」","sentenceOrder":73},
  {"id":"s_work_han_thu_36_74","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰；「外戚傳傅太后弟子喜封高武侯，晏封孔鄉侯，商封汝昌侯，同母弟子鄭業為陽信侯，丁太后兄明封陽安侯，子滿封平周侯。傅氏、鄭氏侯者四人，丁氏侯者二人。今此言六人為列侯，其數是也。傅氏、丁氏、鄭氏則有之，而不見周氏所出。志傳不同，未詳其意。」","sentenceOrder":74},
  {"id":"s_work_han_thu_36_75","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　服虔曰：「楊宣，諫大夫也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_36_76","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　師古曰：「易觀卦上九爻辭。」","sentenceOrder":76},
  {"id":"s_work_han_thu_36_77","chapterId":"ch_work_han_thu_36","textTraditional":"〔五〕　師古曰：「徒知之而已，不能進助也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_36_78","chapterId":"ch_work_han_thu_36","textTraditional":"〔六〕　師古曰：「此易大畜九三爻辭。」","sentenceOrder":78},
  {"id":"s_work_han_thu_36_79","chapterId":"ch_work_han_thu_36","textTraditional":"〔七〕　師古曰：「攘，卻也。言不進達之也。一曰攘，因也。因而竊取曰攘。音人羊反。」","sentenceOrder":79},
  {"id":"s_work_han_thu_36_80","chapterId":"ch_work_han_thu_36","textTraditional":"〔八〕　師古曰：「僇，古戮字。」","sentenceOrder":80},
  {"id":"s_work_han_thu_36_81","chapterId":"ch_work_han_thu_36","textTraditional":"史記周幽王二年，周三川皆震。〔一〕劉向以為金木水火沴土者也。伯陽甫曰：〔二〕「周將亡矣！天地之氣不過其序；若過其序，民亂之也。陽伏而不能出，陰迫而不能升，〔三〕於是有地震。今三川實震，是陽失其所而填陰也。〔四〕陽失而在陰，原必塞；〔五〕原塞，國必亡。夫水，土演而民用也；〔六〕土無所演，而民乏財用，不亡何待？昔伊雒竭而夏亡，河竭而商亡，今周德如二代之季，其原又塞，塞必竭；川竭，山必崩。夫國必依山川，山崩川竭，亡之徵也。若國亡，不過十年，數之紀也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_36_82","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　應劭曰：「震，地震三川竭也。」師古曰：「三川，涇、渭、洛也。洛即漆沮也。川自震耳，故將壅塞，非地震也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_36_83","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　服虔曰：「周太史。」","sentenceOrder":83},
  {"id":"s_work_han_thu_36_84","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　應劭曰：「迫，陰迫陽，使不能升也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_36_85","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　應劭曰：「失其所，失其道也。填陰，為陰所填不得升也。」師古曰：「填音竹刃反。」","sentenceOrder":85},
  {"id":"s_work_han_thu_36_86","chapterId":"ch_work_han_thu_36","textTraditional":"〔五〕　師古曰：「原謂水泉之本也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_36_87","chapterId":"ch_work_han_thu_36","textTraditional":"〔六〕　應劭曰：「演，引也，所以引出土氣者也。」師古曰：「演音衍。」","sentenceOrder":87},
  {"id":"s_work_han_thu_36_88","chapterId":"ch_work_han_thu_36","textTraditional":"是歲（二）〔三〕川竭，岐山崩。劉向以為陽失在陰者，謂火氣來煎枯水，故川竭也。山川連體，下竭上崩，事勢然也。時幽王暴虐，妄誅伐，不聽諫，迷於褒姒，廢其正后，〔一〕廢后之父申侯與犬戎共攻殺幽王。一曰，其在天文，水為辰星，辰星為蠻夷。月食辰星，國以女亡。幽王之敗，女亂其內，夷攻其外。京房易傳曰：「君臣相背，厥異名水絕。」〔二〕","sentenceOrder":88},
  {"id":"s_work_han_thu_36_89","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「褒姒，褒人所獻之女也。正后，申后也。蓋白華之詩所為作也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_36_90","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「有名之水。」","sentenceOrder":90},
  {"id":"s_work_han_thu_36_91","chapterId":"ch_work_han_thu_36","textTraditional":"文公九年「九月癸酉，地震」。劉向以為先是時，齊桓、晉文、魯釐二伯賢君新沒，〔一〕周襄王失道，〔二〕楚穆王殺父，〔三〕諸侯皆不肖，權傾於下，天戒若曰，臣下彊盛者將動為害。後宋、魯、晉、莒、鄭、陳、齊皆殺君。〔四〕諸震，略皆從董仲舒說也。京房易傳曰：「臣事雖正，專必震，其震，於水則波，於木則搖，於屋則瓦落。大經在辟而易臣，茲謂陰動，〔五〕厥震搖政宮。大經搖政，茲謂不陰，厥震搖山，山出涌水。嗣子無德專祿，茲謂不順，厥震動丘陵，涌水出。」","sentenceOrder":91},
  {"id":"s_work_han_thu_36_92","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「齊桓、晉文，二伯也。魯僖，賢君也。伯讀曰霸。」","sentenceOrder":92},
  {"id":"s_work_han_thu_36_93","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「謂避叔帶之難而出奔，失為君之道。」","sentenceOrder":93},
  {"id":"s_work_han_thu_36_94","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「穆王，商臣也，殺其父成王也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_36_95","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　師古曰：「文十六年宋人殺其君杵臼，十八年襄仲殺惡，宣二年晉趙盾殺其君夷皋，文十八年莒弒其君庶其，宣四年鄭公子歸生弒其君夷，十年陳夏徵舒殺其君平國，文十八年齊人殺其君商人。」","sentenceOrder":95},
  {"id":"s_work_han_thu_36_96","chapterId":"ch_work_han_thu_36","textTraditional":"〔五〕　服虔曰：「經，常也。辟音刑辟之辟。」蘇林曰：「大經，五行之常經也。在辟，眾陰犯殺其上也。」師古曰：「辟讀曰僻，謂常法僻壞而易臣也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_36_97","chapterId":"ch_work_han_thu_36","textTraditional":"襄公十六年「五月甲子，地震」。劉向以為先是雞澤之會，諸侯盟，大夫又盟。〔一〕是歲三月，諸侯為溴梁之會，而大夫獨相與盟，〔二〕五月地震矣。其後崔氏專齊，欒盈亂晉，良霄傾鄭，閽殺吳子，燕逐其君，楚滅陳、蔡。〔三〕","sentenceOrder":97},
  {"id":"s_work_han_thu_36_98","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「雞澤，衛地也。襄三年，公會單子、晉侯、宋公、衛侯、鄭伯、莒子、邾子、齊世子光，己未，同盟于雞澤。陳侯使袁僑如會，戊寅，叔孫豹及諸侯大夫及陳袁僑盟也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_36_99","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「經書諸大夫盟，謂晉、宋、衛、鄭、曹、莒、邾、薛、杞、小邾之大夫。」","sentenceOrder":99},
  {"id":"s_work_han_thu_36_100","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「崔氏，齊卿崔杼也。欒盈，晉大夫欒桓子之子懷子也，二十一年奔楚，二十三年復入于晉而作亂。良霄，鄭大夫伯有也。三十年，子晳以駟氏之甲伐而焚之，伯有奔廱梁，遂奔許，晨自墓門之竇入，介于襄庫，以伐舊北門。駟帶率國人伐之，伯有死于羊肆。閽，守門者也。吳子，餘祭也。吳人伐越，獲俘焉，以為閽，使守舟。二十九年，餘祭觀舟，閽以刀殺之。燕，北燕國也。昭三年冬，燕大夫殺公之外嬖，公懼奔齊。昭八年，楚師滅陳。十一年，楚滅蔡也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_36_101","chapterId":"ch_work_han_thu_36","textTraditional":"昭公十九年「五月己卯，地震」。劉向以為是時季氏將有逐君之變。其後宋三臣、曹會皆以地叛，〔一〕蔡、莒逐其君，吳敗中國殺二君。〔二〕","sentenceOrder":101},
  {"id":"s_work_han_thu_36_102","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「二十年，宋華亥、向寧、華定出奔陳，二十一年自陳入于宋南里以叛。曹會，大夫公孫會也，二十年自鄸出奔宋。穀梁傳曰『自鄸者，專鄸也』。鄸，會之邑也。鄸音莫風反。」","sentenceOrder":102},
  {"id":"s_work_han_thu_36_103","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「昭二十一年，蔡人信費無極之言，出蔡侯朱，朱出奔楚。二十三年，莒子庚輿虐而好劍，國人患之。秋七月，烏存帥國人以逐之，庚輿出奔魯。戊辰，吳敗楚、頓、胡、沈、蔡、陳、許之師於雞父，胡子髡、沈子逞滅，是也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_36_104","chapterId":"ch_work_han_thu_36","textTraditional":"二十三年「八月乙未，地震」。劉向以為是時周景王崩，劉、單立王子猛，尹氏立子朝。〔一〕其後季氏逐昭公，黑肱叛邾，〔二〕吳殺其君僚，〔三〕宋五大夫、晉二大夫皆以地叛。〔四〕","sentenceOrder":104},
  {"id":"s_work_han_thu_36_105","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「已解於上。」","sentenceOrder":105},
  {"id":"s_work_han_thu_36_106","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「黑肱，邾大夫也。三十一年，經書『邾黑肱以濫來奔』。濫，邾邑。」","sentenceOrder":106},
  {"id":"s_work_han_thu_36_107","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「二十七年，吳公子光使專設諸抽劍刺王是也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_36_108","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　師古曰：「定十年，宋公之弟辰暨仲它、石彄出奔陳。十一年春，辰及仲它、石彄、公子地自陳入於蕭以叛。秋，宋樂大心自曹入於蕭。十三年，晉荀寅、士吉射入朝歌以叛。」","sentenceOrder":108},
  {"id":"s_work_han_thu_36_109","chapterId":"ch_work_han_thu_36","textTraditional":"哀公三年「四月甲午，地震」。劉向以為是時諸侯皆信邪臣，莫能用仲尼，盜殺蔡侯，齊陳乞弒君。〔一〕","sentenceOrder":109},
  {"id":"s_work_han_thu_36_110","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「哀四年，經書『盜殺蔡侯申』。左氏傳曰：『蔡昭侯將如吳，諸大夫恐其又遷也，公孫翩逐而射之，入於家人而卒。』陳乞，齊大夫陳僖子也。六年，乞殺其君荼。荼，景公之子安孺子也。荼音大胡反。」","sentenceOrder":110},
  {"id":"s_work_han_thu_36_111","chapterId":"ch_work_han_thu_36","textTraditional":"惠帝二年正月，地震隴西，厭四百餘家。〔一〕武帝征和二年八月癸亥，地震，厭殺人。宣帝本始四年四月壬寅，地震河南以東四十九郡，北海琅邪壞祖宗廟城郭，殺六千餘人。元帝永光三年冬，地震。綏和二年九月丙辰，地震，自京師至北邊郡國三十餘壞城郭，凡殺四百一十五人。","sentenceOrder":111},
  {"id":"s_work_han_thu_36_112","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「厭音一甲反。次下亦同。」","sentenceOrder":112},
  {"id":"s_work_han_thu_36_113","chapterId":"ch_work_han_thu_36","textTraditional":"釐公十四年「秋八月辛卯，沙麓崩」。穀梁傳曰：「林屬於山曰麓，〔一〕沙其名也。」劉向以為臣下背叛，散落不事上之象也。先是，齊桓行伯道，會諸侯，〔二〕事周室。管仲既死，桓德日衰，天戒若曰，伯道將廢，諸侯散落，政逮大夫，陪臣執命，臣下不事上矣。桓公不寤，天子蔽晦。〔三〕及齊（威）〔桓〕死，天下散而從楚。王札子殺二大夫，〔四〕晉敗天子之師，〔五〕莫能征討，從是陵遲。公羊以為沙麓，河上邑也。董仲舒說略同。一曰，河，大川象；齊，大國；桓德衰，伯道將移於晉文，故河為徙也。左氏以為沙麓，晉地；沙，山名也；地震而麓崩，不書震，舉重者也。伯陽甫所謂「國必依山川，山崩川竭，亡之徵也；不過十年，數之紀也。」至二十四年，晉懷公殺於高梁。〔六〕京房易傳曰：「小人剝廬，〔七〕厥妖山崩，茲謂陰乘陽，弱勝彊。」","sentenceOrder":113},
  {"id":"s_work_han_thu_36_114","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「屬，聯也，音之欲反。」","sentenceOrder":114},
  {"id":"s_work_han_thu_36_115","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「伯讀曰霸。其下亦同。」","sentenceOrder":115},
  {"id":"s_work_han_thu_36_116","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「被，掩蔽而暗也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_36_117","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　師古曰：「二大夫，召伯、毛伯也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_36_118","chapterId":"ch_work_han_thu_36","textTraditional":"〔五〕　師古曰：「謂敗之於貿戎也。已解於上也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_36_119","chapterId":"ch_work_han_thu_36","textTraditional":"〔六〕　師古曰：「懷公謂子圉，惠公之子也。文公入國而使殺之。高梁，晉地。」","sentenceOrder":119},
  {"id":"s_work_han_thu_36_120","chapterId":"ch_work_han_thu_36","textTraditional":"〔七〕　師古曰：「剝卦上九爻之辭。」","sentenceOrder":120},
  {"id":"s_work_han_thu_36_121","chapterId":"ch_work_han_thu_36","textTraditional":"成公五年「夏，梁山崩」。穀梁傳曰廱河三日不流，〔一〕晉君帥群臣而哭之，乃流。〔二〕劉向以為山陽，君也，水陰，民也，天戒若曰，君道崩壞，下亂，百姓將失其所矣。哭然後流，喪亡象也。梁山在晉地，自晉始而及天下也。後晉暴殺三卿，厲公以弒。〔三〕溴梁之會，天下大夫皆執國政，〔四〕其後孫、甯出衛獻，〔五〕三家逐魯昭，單、尹亂王室。〔六〕董仲舒說略同。劉歆以為梁山，晉望也；崩，弛崩也。〔七〕古者三代命祀，祭不越望，吉凶禍福，不是過也。國主山川，山崩川竭，亡之徵也，美惡周必復。〔八〕是歲歲在鶉火，至十七年復在鶉火，欒書、中行偃殺厲公而立悼公。","sentenceOrder":121},
  {"id":"s_work_han_thu_36_122","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「廱讀曰壅。」","sentenceOrder":122},
  {"id":"s_work_han_thu_36_123","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「從伯宗用輦者之言。」","sentenceOrder":123},
  {"id":"s_work_han_thu_36_124","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「三卿謂郤犨、郤錡、郤至也。厲公殺之，而欒書、中行偃又弒厲公。事在成十七年。」","sentenceOrder":124},
  {"id":"s_work_han_thu_36_125","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　師古曰：「已解於上。」","sentenceOrder":125},
  {"id":"s_work_han_thu_36_126","chapterId":"ch_work_han_thu_36","textTraditional":"〔五〕　師古曰：「孫，孫林父，甯，甯殖，皆衛大夫也。衛獻公，定公之子也，名衎。獻公戒二子食，日旰不召，而射鴻於囿，二子怒，因作亂。公如鄄，遂出奔齊。孫氏追之，敗公徒於柯澤。事在襄十四年。」","sentenceOrder":126},
  {"id":"s_work_han_thu_36_127","chapterId":"ch_work_han_thu_36","textTraditional":"〔六〕　師古曰：「並解於上。」","sentenceOrder":127},
  {"id":"s_work_han_thu_36_128","chapterId":"ch_work_han_thu_36","textTraditional":"〔七〕　師古曰：「言漸解散也。弛音式爾反。」","sentenceOrder":128},
  {"id":"s_work_han_thu_36_129","chapterId":"ch_work_han_thu_36","textTraditional":"〔八〕　師古曰：「復音扶目反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_36_130","chapterId":"ch_work_han_thu_36","textTraditional":"高后二年正月，武都山崩，殺七百六十人，地震至八月乃止。文帝元年四月，齊楚地山二十九所同日俱大發水，潰出，劉向以為近水沴土也。天戒若曰，勿盛齊楚之君，今失制度，將為亂。後十六年，帝庶兄齊悼惠王之孫文王則薨，無子，帝分齊地，立悼惠王庶子六人皆為王。〔一〕賈誼、晁錯諫，以為違古制，恐為亂。至景帝三年，齊楚七國起兵百餘萬，漢皆破之。春秋四國同日災，〔二〕漢七國同日眾山潰，咸被其害，不畏天威之明效也。","sentenceOrder":130},
  {"id":"s_work_han_thu_36_131","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「謂齊孝王將閭、濟北王志、菑川王賢、膠東王雄渠、膠西王卬、濟南王辟光。」","sentenceOrder":131},
  {"id":"s_work_han_thu_36_132","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「宋、衛、陳、鄭。」","sentenceOrder":132},
  {"id":"s_work_han_thu_36_133","chapterId":"ch_work_han_thu_36","textTraditional":"成帝河平三年二月丙戌，犍為柏江山崩，捐江山崩，皆廱江水，〔一〕江水逆流壞城，殺十三人，地震積二十一日，百二十四動。元延三年正月丙寅，蜀郡岷山崩，廱江，江水逆流，三日乃通。劉向以為周時岐山崩，三川竭，而幽王亡。岐山者，周所興也。漢家本起於蜀漢，今所起之地山崩川竭，星孛又及攝提、大角，從參至辰，〔二〕殆必亡矣。其後三世亡嗣，王莽篡位。","sentenceOrder":133},
  {"id":"s_work_han_thu_36_134","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「廱讀曰壅。次下亦同。」","sentenceOrder":134},
  {"id":"s_work_han_thu_36_135","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　如淳曰：「孛星尾長及攝提、大角，始發於參至辰也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_36_136","chapterId":"ch_work_han_thu_36","textTraditional":"傳曰：「皇之不極，是謂不建，厥咎眊，〔一〕厥罰恆陰，厥極弱。時則有射妖，時則有龍蛇之孽，時則有馬禍，時則有下人伐上之痾，時則有日月亂行，星辰逆行。」","sentenceOrder":136},
  {"id":"s_work_han_thu_36_137","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　服虔曰：「眊音老耄。」","sentenceOrder":137},
  {"id":"s_work_han_thu_36_138","chapterId":"ch_work_han_thu_36","textTraditional":"「皇之不極，是謂不建」，皇，君也。極，中；建，立也。人君貌言視聽思心五事皆失，不得其中，則不能立萬事，失在眊悖，故其咎眊也。〔一〕王者自下承天理物。雲起於山，而彌於天；〔二〕天氣亂，故其罰常陰也。一曰，上失中，則下彊盛而蔽君明也。易曰「亢龍有悔，貴而亡位，高而亡民，賢人在下位而亡輔」，〔三〕如此，則君有南面之尊，而亡一人之助，故其極弱也。盛陽動進輕疾〔四〕。禮，春而大射，以順陽氣。〔五〕上微弱則下奮動，故有射妖。易曰「雲從龍」，〔六〕又曰「龍蛇之蟄，以存身也」。〔七〕陰氣動，故有龍蛇之孽。於易，乾為君為馬，馬任用而彊力，君氣毀，故有馬禍。一曰，馬多死及為怪，亦是也。君亂且弱，人之所叛，天之所去，不有明王之誅，則有篡弒之禍，故有下人伐上之痾。凡君道傷者病天氣，不言五行沴天，而曰「日月亂行，星辰逆行」者，為若下不敢沴天，猶春秋曰「王師敗績于貿戎」，不言敗之者，以自敗為文，尊尊之意也。劉歆皇極傳曰有下體生上之痾。說以為下人伐上，天誅已成，不得復為痾云。皇極之常陰，劉向以為春秋亡其應。一曰，久陰不雨是也。劉歆以為自屬常陰。","sentenceOrder":138},
  {"id":"s_work_han_thu_36_139","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「眊，不明也。悖，惑也，音布內反。」","sentenceOrder":139},
  {"id":"s_work_han_thu_36_140","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「彌，滿也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_36_141","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「乾上九文言也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_36_142","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　服虔曰：「陽行輕且疾也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_36_143","chapterId":"ch_work_han_thu_36","textTraditional":"〔五〕　韋昭曰：「將祭，與群臣射，謂之大射。」","sentenceOrder":143},
  {"id":"s_work_han_thu_36_144","chapterId":"ch_work_han_thu_36","textTraditional":"〔六〕　師古曰：「乾九五文言。」","sentenceOrder":144},
  {"id":"s_work_han_thu_36_145","chapterId":"ch_work_han_thu_36","textTraditional":"〔七〕　師古曰：「下繫辭也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_36_146","chapterId":"ch_work_han_thu_36","textTraditional":"昭帝元平元年四月崩，亡嗣，立昌邑王賀。賀即位，天陰，晝夜不見日月。賀欲出，光祿大夫夏侯勝當車諫曰：「天久陰而不雨，臣下有謀上者，陛下欲何之？」賀怒，縛勝以屬吏，〔一〕吏白大將軍霍光。光時與車騎將軍張安世謀欲廢賀。光讓安世，以為泄語，安世實不泄，召問勝。勝上洪範五行傳曰：「『皇之不極，厥罰常陰，時則有下人伐上。』不敢察察言，〔二〕故云臣下有謀。」光、安世讀之，大驚，以此益重經術士。後數日卒共廢賀，此常陰之明效也。京房易傳曰：「有蜺、蒙、霧。霧，上下合也。蒙如塵雲。蜺，日旁氣也。其占曰：后妃有專，蜺再重，赤而專，至衝旱。〔三〕妻不壹順，黑蜺四背，又白蜺雙出日中。妻以貴高夫，茲謂擅陽，蜺四方，日光不陽，解而溫。〔四〕內取茲謂禽，〔五〕蜺如禽，在日旁。以尊降妃，茲謂薄嗣，蜺直而塞，六辰乃除，夜星見而赤。〔六〕女不變始，茲謂乘夫，〔七〕蜺白在日側，黑蜺果之。氣正直。〔八〕妻不順正，茲謂擅陽，蜺中窺貫而外專。夫妻不嚴茲謂媟，〔九〕蜺與日會。婦人擅國茲謂頃，〔一０〕蜺白貫日中，赤蜺四背。〔一一〕適不答茲謂不次，〔一二〕蜺直在左，蜺交在右。取於不專，茲謂危嗣，蜺抱日兩未及。君淫外茲謂亡，蜺氣左日交於外。取不達茲謂不知，蜺白奪明而大溫，溫而雨。〔一三〕尊卑不別茲謂媟，蜺三出三已，三辰除，〔一四〕除則日出且雨。臣私祿及親，茲謂罔辟，〔一五〕厥異蒙，其蒙先大溫，已蒙起，日不見。行善不請於上，茲謂作福，蒙一日五起五解。辟不下謀，臣辟異道，茲謂不見，上蒙下霧，風三變而俱解。立嗣子疑，茲謂動欲，蒙赤，日不明。德不序茲謂不聰，蒙，日不明，溫而民病。德不試，空言祿，〔一六〕茲謂主窳臣夭，〔一七〕蒙起而白。君樂逸人茲謂放，蒙，日青，黑雲夾日，左右前後行過日。公不任職，茲謂怙祿，蒙三日，又大風五日，蒙不解。利邪以食，茲謂閉上，蒙大起，白雲如山行蔽日。公懼不言道，茲謂閉下，蒙大起，日不見，若雨不雨，至十二日解，而有大雲蔽日。祿生於下，茲謂誣君，蒙微而小雨，已乃大雨。下相攘善，茲謂盜明，蒙黃濁。下陳功，求於上，茲謂不知，蒙，微而赤，風鳴條，解復蒙。下專刑茲謂分威，蒙而日不得明，大臣厭小臣茲謂蔽，蒙微，日不明，若解不解，大風發，赤雲起而蔽日。眾不惡惡茲謂閉，蒙，尊卦用事，〔一八〕三日而起，日不見。漏言亡喜，茲謂下厝用，〔一九〕蒙微，日無光，有雨雲，雨不降。廢忠惑佞茲謂亡，蒙，天先清而暴，蒙微而日不明。有逸民茲謂不明，蒙濁，奪日光。公不任職，茲謂不絀，蒙白，三辰止，則日青，青而寒，寒必雨。忠臣進善君不試，茲謂遏，〔二０〕蒙，先小雨，雨已蒙起，微而日不明。惑眾在位，茲謂覆國，蒙微而日不明，一溫一寒，風揚塵。知佞厚之茲謂庳，蒙甚而溫。君臣故弼茲謂悖，〔二一〕厥災風雨霧，風拔木，亂五穀，已而大霧。庶正蔽惡，茲謂生孽災，厥異霧。」此皆陰雲之類云。","sentenceOrder":146},
  {"id":"s_work_han_thu_36_147","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「屬，委也，音之欲反。」","sentenceOrder":147},
  {"id":"s_work_han_thu_36_148","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　臣瓚曰：「不敢察察明言之。」","sentenceOrder":148},
  {"id":"s_work_han_thu_36_149","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　孟康曰：「專，員也。若五月再重，赤而員，至十一月旱也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_36_150","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　服虔曰：「蒙氣解而溫。」","sentenceOrder":150},
  {"id":"s_work_han_thu_36_151","chapterId":"ch_work_han_thu_36","textTraditional":"〔五〕　服虔曰：「人君內淫於骨肉也。」臣瓚曰：「人君取於國中也。」師古曰：「取，如禮記『聚麀』之聚。瓚說非。」","sentenceOrder":151},
  {"id":"s_work_han_thu_36_152","chapterId":"ch_work_han_thu_36","textTraditional":"〔六〕　韋昭曰：「六辰，謂從卯至申。」","sentenceOrder":152},
  {"id":"s_work_han_thu_36_153","chapterId":"ch_work_han_thu_36","textTraditional":"〔七〕　孟康曰：「始貴高於夫，終行此不變也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_36_154","chapterId":"ch_work_han_thu_36","textTraditional":"〔八〕　師古曰：「果謂干之也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_36_155","chapterId":"ch_work_han_thu_36","textTraditional":"〔九〕　韋昭曰：「媟言媟慢也。」師古曰：「音先列反。」","sentenceOrder":155},
  {"id":"s_work_han_thu_36_156","chapterId":"ch_work_han_thu_36","textTraditional":"〔一０〕師古曰：「頃讀曰傾。」","sentenceOrder":156},
  {"id":"s_work_han_thu_36_157","chapterId":"ch_work_han_thu_36","textTraditional":"〔一一〕服虔曰：「蜺背日。」","sentenceOrder":157},
  {"id":"s_work_han_thu_36_158","chapterId":"ch_work_han_thu_36","textTraditional":"〔一二〕服虔曰：「言適妻不見答也。」臣瓚曰：「夫不接妻謂不答。」師古曰：「適讀曰嫡。答，報也。言妻有承順之心，不見報答也。一曰，答，對也，言不以恩意接對之。」","sentenceOrder":158},
  {"id":"s_work_han_thu_36_159","chapterId":"ch_work_han_thu_36","textTraditional":"〔一三〕師古曰：「取讀曰聚。」","sentenceOrder":159},
  {"id":"s_work_han_thu_36_160","chapterId":"ch_work_han_thu_36","textTraditional":"〔一四〕韋昭曰：「若從寅至辰也。蜺旦見西，晏則雨。」","sentenceOrder":160},
  {"id":"s_work_han_thu_36_161","chapterId":"ch_work_han_thu_36","textTraditional":"〔一五〕韋昭曰：「辟，君也。」師古曰：「辟音壁。其下並同。」","sentenceOrder":161},
  {"id":"s_work_han_thu_36_162","chapterId":"ch_work_han_thu_36","textTraditional":"〔一六〕師古曰：「試，用也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_36_163","chapterId":"ch_work_han_thu_36","textTraditional":"〔一七〕孟康曰：「謂君惰窳，用人不以次第，為夭也。」師古曰：「窳音庾。」","sentenceOrder":163},
  {"id":"s_work_han_thu_36_164","chapterId":"ch_work_han_thu_36","textTraditional":"〔一八〕孟康曰：「尊卦，乾坤也。」臣瓚曰：「京房謂之方伯卦，震、兌、坎、離也。」師古曰：「孟說是。」","sentenceOrder":164},
  {"id":"s_work_han_thu_36_165","chapterId":"ch_work_han_thu_36","textTraditional":"〔一九〕師古曰：「厝音千各反。」","sentenceOrder":165},
  {"id":"s_work_han_thu_36_166","chapterId":"ch_work_han_thu_36","textTraditional":"〔二０〕師古曰：「試，用也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_36_167","chapterId":"ch_work_han_thu_36","textTraditional":"〔二一〕師古曰：「弼猶相戾也。悖，惑也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_36_168","chapterId":"ch_work_han_thu_36","textTraditional":"嚴公十八年「秋，有蜮」。劉向以為蜮生南越。越地多婦人，男女同川，淫女為主，亂氣所生，故聖人名之曰蜮。蜮猶惑也，在水旁，能射人，射人有處，甚者至死。〔一〕南方謂之短弧，〔二〕近射妖，死亡之象也。時嚴將取齊之淫女，故蜮至。天戒若曰，勿取齊女，將生淫惑篡弒之禍。嚴不寤，遂取之。入後淫於二叔，二叔以死，兩子見弒，夫人亦誅。〔三〕劉歆以為蜮，盛暑所生，非自越來也。京房易傳曰：「忠臣進善君不試，厥咎國生蜮。」〔四〕","sentenceOrder":168},
  {"id":"s_work_han_thu_36_169","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「以氣射人也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_36_170","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「即射工也，亦呼水弩。」","sentenceOrder":170},
  {"id":"s_work_han_thu_36_171","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「並解于上。」","sentenceOrder":171},
  {"id":"s_work_han_thu_36_172","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　師古曰：「試，用也。」","sentenceOrder":172},
  {"id":"s_work_han_thu_36_173","chapterId":"ch_work_han_thu_36","textTraditional":"史記魯哀公時，有隼集于陳廷而死，〔一〕楛矢貫之，〔二〕石砮，〔三〕長尺有咫。〔四〕陳閔公使使問仲尼，〔五〕仲尼曰：「隼之來遠矣！昔武王克商，通道百蠻，使各以方物來貢，肅慎貢楛矢，〔六〕石砮長尺有咫。先王分異姓以遠方職，使毋忘服，〔七〕故分陳以肅慎矢。」試求之故府，果得之。〔八〕劉向以為隼近黑祥，貪暴類也；矢貫之，近射妖也；死於廷，國亡表也。象陳眊亂，不服事周，〔九〕而行貪暴，將致遠夷之禍，為所滅也。是時中國齊晉、南夷吳楚為彊，〔一０〕陳交晉不親，附楚不固，數被二國之禍。後楚有白公之亂，〔一一〕陳乘而侵之，〔一二〕卒為楚所滅。〔一三〕","sentenceOrder":173},
  {"id":"s_work_han_thu_36_174","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「隼，鷙鳥，即今之鴩也。說者以為鷂，失之矣。廷，朝廷也。鴩字音胡骨反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_36_175","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　應劭曰：「楛，木名。」師古曰：「音怙，其木堪為箭笴，今豳以北皆用之，土俗呼其木為楛子也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_36_176","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　應劭曰：「砮，鏃也，音奴，又乃互反。」","sentenceOrder":176},
  {"id":"s_work_han_thu_36_177","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　張晏曰：「八寸曰咫。」","sentenceOrder":177},
  {"id":"s_work_han_thu_36_178","chapterId":"ch_work_han_thu_36","textTraditional":"〔五〕　師古曰：「閔公名周，懷公之子。」","sentenceOrder":178},
  {"id":"s_work_han_thu_36_179","chapterId":"ch_work_han_thu_36","textTraditional":"〔六〕　臣瓚曰：「肅慎，東北夷。」","sentenceOrder":179},
  {"id":"s_work_han_thu_36_180","chapterId":"ch_work_han_thu_36","textTraditional":"〔七〕　師古曰：「服，事也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_36_181","chapterId":"ch_work_han_thu_36","textTraditional":"〔八〕　師古曰：「得昔所分之矢於府藏中。」","sentenceOrder":181},
  {"id":"s_work_han_thu_36_182","chapterId":"ch_work_han_thu_36","textTraditional":"〔九〕　師古曰：「眊音莫報反。」","sentenceOrder":182},
  {"id":"s_work_han_thu_36_183","chapterId":"ch_work_han_thu_36","textTraditional":"〔一０〕師古曰：「中國則齊、晉為彊，南夷則吳、楚為彊。」","sentenceOrder":183},
  {"id":"s_work_han_thu_36_184","chapterId":"ch_work_han_thu_36","textTraditional":"〔一一〕師古曰：「白公，楚平王太子建之子勝也。建遇讒，奔鄭而死。勝在吳，子西召之，使處吳境，為白公。吳人伐慎，白公敗之，請以戰備獻，因作亂，子西、子期皆死。事在哀十六年。」","sentenceOrder":184},
  {"id":"s_work_han_thu_36_185","chapterId":"ch_work_han_thu_36","textTraditional":"〔一二〕師古曰：「白公之亂，陳人恃其聚而侵楚。事見哀十七年。」","sentenceOrder":185},
  {"id":"s_work_han_thu_36_186","chapterId":"ch_work_han_thu_36","textTraditional":"〔一三〕師古曰：「陳閔公之二十年，獲麟之歲也。其二十四年，而為楚所滅。」","sentenceOrder":186},
  {"id":"s_work_han_thu_36_187","chapterId":"ch_work_han_thu_36","textTraditional":"史記夏后氏之衰，有二龍止於夏廷，而言「余，褒之二君也」。〔一〕夏帝卜殺之，去之，止之，莫吉；卜請其漦而藏之，乃吉〔二〕。於是布幣策告之。〔三〕龍亡而漦在，乃櫝去之。〔四〕其後夏亡，傳櫝於殷周，三代莫發，至厲王末，發而觀之，漦流于廷，不可除也。厲王使婦人臝而譟之，〔五〕漦化為玄黿，〔六〕入後宮。處妾遇之而孕，〔七〕生子，懼而棄之。宣王立，女童謠曰：「檿弧萁服，實亡周國。」〔八〕後有夫婦鬻是器者，宣王使執而僇之。〔九〕既去，見處妾所棄妖子，聞其夜號，哀而收之，遂亡奔褒。後褒人有罪，入妖子以贖，是為褒姒，幽王見而愛之，生子伯服。王廢申后及太子宜咎，而立褒姒、伯服代之。廢后之父申侯與繒西畎戎共攻殺幽王。〔一０〕詩曰：「赫赫宗周，褒姒滅之。」〔一一〕劉向以為夏后季世，周之幽、厲，皆誖亂逆天，〔一二〕故有龍黿之怪，近龍蛇孽也。漦，血也，一曰沫也。檿弧，桑弓也。萁服，蓋以萁草為箭服，近射妖也。女童謠者，禍將生於女，國以兵寇亡也。〔一三〕","sentenceOrder":187},
  {"id":"s_work_han_thu_36_188","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「褒，古國名。」","sentenceOrder":188},
  {"id":"s_work_han_thu_36_189","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　應劭曰：「漦，沫也。」鄭氏曰：「漦音牛齝之齝。」師古曰：「去謂驅逐也，止謂拘留也。去音丘呂反。漦音丑之反。」","sentenceOrder":189},
  {"id":"s_work_han_thu_36_190","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「奠幣為禮，讀策辭而告之也。說者以為策者糈米，蓋失之矣。」","sentenceOrder":190},
  {"id":"s_work_han_thu_36_191","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　師古曰：「櫝，匱也。去，藏也。櫝音讀。去音丘呂反。」","sentenceOrder":191},
  {"id":"s_work_han_thu_36_192","chapterId":"ch_work_han_thu_36","textTraditional":"〔五〕　應劭曰：「群呼曰譟。」師古曰：「譟音先到反。」","sentenceOrder":192},
  {"id":"s_work_han_thu_36_193","chapterId":"ch_work_han_thu_36","textTraditional":"〔六〕　韋昭曰：「玄，黑；黿，蜤蜴也，似蛇而有足。」師古曰：「黿似鱉而大，非蛇及蜤蜴。」","sentenceOrder":193},
  {"id":"s_work_han_thu_36_194","chapterId":"ch_work_han_thu_36","textTraditional":"〔七〕　師古曰：「處妾，宮中之童女。」","sentenceOrder":194},
  {"id":"s_work_han_thu_36_195","chapterId":"ch_work_han_thu_36","textTraditional":"〔八〕　服虔曰：「檿，檿桑也。」師古曰：「女童謠，閭里之童女為歌謠也。檿，山桑之有點文者也。木弓曰弧。服，盛箭者，即今之步叉也。萁，草，似荻而細，織之為服也。檿音一簟反。萁音基。荻音敵。」","sentenceOrder":195},
  {"id":"s_work_han_thu_36_196","chapterId":"ch_work_han_thu_36","textTraditional":"〔九〕　師古曰：「鬻，賣也，音弋六反。」","sentenceOrder":196},
  {"id":"s_work_han_thu_36_197","chapterId":"ch_work_han_thu_36","textTraditional":"〔一０〕師古曰：「畎戎即犬戎，亦曰昆夷。」","sentenceOrder":197},
  {"id":"s_work_han_thu_36_198","chapterId":"ch_work_han_thu_36","textTraditional":"〔一一〕師古曰：「小雅正月之詩也。赫赫，盛貌也。宗周，鎬京也。滅，滅也，音呼悅反。」","sentenceOrder":198},
  {"id":"s_work_han_thu_36_199","chapterId":"ch_work_han_thu_36","textTraditional":"〔一二〕師古曰：「誖，惑也，音布內反。」","sentenceOrder":199},
  {"id":"s_work_han_thu_36_200","chapterId":"ch_work_han_thu_36","textTraditional":"〔一三〕師古曰：「因婦人以致兵寇也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_36_201","chapterId":"ch_work_han_thu_36","textTraditional":"左氏傳昭公十九年，龍鬥於鄭時門之外洧淵。〔一〕劉向以為近龍孽也。鄭以小國攝乎晉楚之間，〔二〕重以彊吳，〔三〕鄭當其衝，不能修德，將鬥三國，以自危亡。〔四〕是時子產任政，內惠於民，外善辭令，以交三國，鄭卒亡患，能以德消變之效也。京房易傳曰：「眾心不安，厥妖龍鬥。」","sentenceOrder":201},
  {"id":"s_work_han_thu_36_202","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「時門，鄭城門也。洧泉，洧水之泉也。洧水出滎陽密縣東南，至潁川長平入潁也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_36_203","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「攝，收持之。」","sentenceOrder":203},
  {"id":"s_work_han_thu_36_204","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「重音直用反。」","sentenceOrder":204},
  {"id":"s_work_han_thu_36_205","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　師古曰：「言若不修德，則三國伐之，必危亡。」","sentenceOrder":205},
  {"id":"s_work_han_thu_36_206","chapterId":"ch_work_han_thu_36","textTraditional":"惠帝二年正月癸酉旦，有兩龍見於蘭陵廷東里溫陵井中，〔一〕至乙亥夜去。劉向以為龍貴象而困於庶人井中，象諸侯將有幽執之禍。其後呂太后幽殺三趙王，諸呂亦終誅滅。京房易傳曰：「有德遭害，厥妖龍見井中。」又曰：「行刑暴惡，黑龍從井出。」","sentenceOrder":206},
  {"id":"s_work_han_thu_36_207","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「蘭陵縣之廷東里也。溫陵，人姓名也。」","sentenceOrder":207},
  {"id":"s_work_han_thu_36_208","chapterId":"ch_work_han_thu_36","textTraditional":"左氏傳魯嚴公時有內蛇與外蛇鬥鄭南門中，內蛇死。劉向以為近蛇孽也。先是鄭厲公劫相祭仲而逐兄昭公代立。〔一〕後厲公出奔，昭公復入。〔二〕死，弟子儀代立。〔三〕厲公自外劫大夫傅瑕，使僇子儀。〔四〕此外蛇殺內蛇之象也。蛇死六年，而厲公立。嚴公聞之，問申繻曰：「猶有妖乎？」〔五〕對曰：「人之所忌，其氣炎以取之，〔六〕妖由人興也。人亡舋焉，妖不自作。人棄常，故有妖。」〔七〕京房易傳曰：「立嗣子疑，厥妖蛇居國門鬥。」","sentenceOrder":208},
  {"id":"s_work_han_thu_36_209","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「厲公母，宋廱氏之女也。祭仲，祭封人仲足也。桓十一年，宋人執祭仲，曰：『不立突，將死。』仲乃與宋盟而立厲公。昭公奔衛。祭音側介反。」","sentenceOrder":209},
  {"id":"s_work_han_thu_36_210","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「桓十五年，厲公與祭仲之婿廱糾謀殺祭仲，不克，五月，出奔蔡。六月，昭公復歸于鄭。九月，厲公殺檀伯而居櫟也。」","sentenceOrder":210},
  {"id":"s_work_han_thu_36_211","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「桓十七年，高渠彌弒昭公而立其弟子亹。十八年，齊人殺子亹，祭仲乃立亹之弟儀也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_36_212","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　師古曰：「傅瑕，鄭大夫也。莊十四年，厲公自櫟侵鄭，獲傅瑕，與之盟。於是傅瑕殺子儀而納厲公也。」","sentenceOrder":212},
  {"id":"s_work_han_thu_36_213","chapterId":"ch_work_han_thu_36","textTraditional":"〔五〕　師古曰：「申繻，魯大夫也。繻音須。」","sentenceOrder":213},
  {"id":"s_work_han_thu_36_214","chapterId":"ch_work_han_thu_36","textTraditional":"〔六〕　師古曰：「炎音弋贍反。」","sentenceOrder":214},
  {"id":"s_work_han_thu_36_215","chapterId":"ch_work_han_thu_36","textTraditional":"〔七〕　師古曰：「已解於上。」","sentenceOrder":215},
  {"id":"s_work_han_thu_36_216","chapterId":"ch_work_han_thu_36","textTraditional":"左氏傳文公十六年夏，有蛇自泉宮出，〔一〕入于國，如先君之數。劉向以為近蛇孽也。泉宮在囿中，公母姜氏嘗居之，蛇從之出，象宮將不居也。詩曰：「維虺維蛇，女子之祥。」〔二〕又蛇入國，國將有女憂也。如先君之數者，公母將薨象也。秋，公母薨。公惡之，乃毀泉臺。夫妖孽應行而自見，非見而為害也。文不改行循正，共御厥罰，〔三〕而作非禮，以重其過。〔四〕後二年薨，公子遂殺文之二子惡、視，而立宣公。〔五〕文公夫人大歸于齊。〔六〕","sentenceOrder":216},
  {"id":"s_work_han_thu_36_217","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「泉宮，即泉臺。」","sentenceOrder":217},
  {"id":"s_work_han_thu_36_218","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「小雅斯干之詩。」","sentenceOrder":218},
  {"id":"s_work_han_thu_36_219","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「共讀曰恭。御讀曰禦，又讀如本字。」","sentenceOrder":219},
  {"id":"s_work_han_thu_36_220","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　師古曰：「重音直用反。」","sentenceOrder":220},
  {"id":"s_work_han_thu_36_221","chapterId":"ch_work_han_thu_36","textTraditional":"〔五〕　師古曰：「惡即子赤也。視，其母弟。」","sentenceOrder":221},
  {"id":"s_work_han_thu_36_222","chapterId":"ch_work_han_thu_36","textTraditional":"〔六〕　師古曰：「本齊女，故出而歸齊，所謂哀姜者也。」","sentenceOrder":222},
  {"id":"s_work_han_thu_36_223","chapterId":"ch_work_han_thu_36","textTraditional":"武帝太始四年七月，趙有蛇從郭外入，與邑中蛇鬥孝文廟下，邑中蛇死。後二年秋，有衛太子事，事自趙人江充起。","sentenceOrder":223},
  {"id":"s_work_han_thu_36_224","chapterId":"ch_work_han_thu_36","textTraditional":"左氏傳定公十年，宋公子地有白馬駟，〔一〕公嬖向魋欲之〔二〕，公取而朱其尾鬣〔三〕以予之。地怒，使其徒抶魋而奪之。〔四〕魋懼將走，公閉門而泣之，目盡腫。公弟辰謂地曰：「子為君禮，不過出竟，君必止子。」〔五〕地出奔陳，公弗止。辰為之請，不聽。辰曰：「是我迋吾兄也，〔六〕吾以國人出，君誰與處？」遂與其徒出奔陳。明年俱入于蕭以叛，大為宋患，〔七〕近馬禍也。","sentenceOrder":224},
  {"id":"s_work_han_thu_36_225","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「地，宋元公子也。四馬曰駟。」","sentenceOrder":225},
  {"id":"s_work_han_thu_36_226","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「公謂景公，即地之兄也。魋，宋司馬桓魋也。向音式尚反。魋音大回反。」","sentenceOrder":226},
  {"id":"s_work_han_thu_36_227","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「鬣，領上鬣也，音力涉反。」","sentenceOrder":227},
  {"id":"s_work_han_thu_36_228","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　師古曰：「抶，擊也，音丑失反。」","sentenceOrder":228},
  {"id":"s_work_han_thu_36_229","chapterId":"ch_work_han_thu_36","textTraditional":"〔五〕　師古曰：「辰亦元公子也。言若見君怒，懼而出奔，是為臣之禮也。竟讀曰境（也）。」","sentenceOrder":229},
  {"id":"s_work_han_thu_36_230","chapterId":"ch_work_han_thu_36","textTraditional":"〔六〕　應劭曰：「迋音君狂〔反〕。」臣瓚曰：「迋音九放反。」師古曰：「二說皆非也。迋，欺也，音求往反。」","sentenceOrder":230},
  {"id":"s_work_han_thu_36_231","chapterId":"ch_work_han_thu_36","textTraditional":"〔七〕　師古曰：「蕭，宋邑。」","sentenceOrder":231},
  {"id":"s_work_han_thu_36_232","chapterId":"ch_work_han_thu_36","textTraditional":"史記秦孝公二十一年有馬生人，昭王二十年牡馬生子而死。劉向以為皆馬禍也。孝公始用商君攻守之法，東侵諸侯，至於昭王，用兵彌烈。〔一〕其象將以兵革抗極成功，而還自害也。牡馬非生類，妄生而死，猶秦恃力彊得天下，而還自滅之象也。〔一〕曰，諸畜生非其類，子孫必有非其姓者，至於始皇，果呂不韋子。京房易傳曰：「方伯分威，厥妖牡馬生子。亡天子，諸侯相伐，厥妖馬生人。」","sentenceOrder":232},
  {"id":"s_work_han_thu_36_233","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「烈，猛也。」","sentenceOrder":233},
  {"id":"s_work_han_thu_36_234","chapterId":"ch_work_han_thu_36","textTraditional":"文帝十二年，有馬生角於吳，角在耳前，上鄉。〔一〕右角長三寸，左角長二寸，皆大二寸。劉向以為馬不當生角，猶吳不當舉兵鄉上也。是時，吳王濞封有四郡五十餘城，〔二〕內懷驕恣，變見於外，天戒早矣。王不寤，後卒舉兵，誅滅。京房易傳曰：「臣易上，政不順，厥妖馬生角，茲謂賢士不足。」又曰：「天子親伐，馬生角。」","sentenceOrder":234},
  {"id":"s_work_han_thu_36_235","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「鄉讀曰嚮。次下亦同。」","sentenceOrder":235},
  {"id":"s_work_han_thu_36_236","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「高紀云『六年春，以故東陽郡、鄣郡、吳郡五十三縣立劉賈為荊王』。十二年十月詔曰：『吳，古之建國，日者荊王兼有其地，今死無後，朕欲復立吳王。』長沙王臣等請立沛侯為吳王。而荊燕吳傳云：『荊王劉賈為黥布所殺，無後，上患會稽輕悍，無壯王填之，乃立濞為吳王，王三郡五十三城。』是則濞之所封，賈本地也，止有三郡，荊燕吳傳與紀（罔）〔同〕矣。今此云四郡，未詳其說。若以賈本不得會稽，濞加一郡者，則不得言五十三城也。」","sentenceOrder":236},
  {"id":"s_work_han_thu_36_237","chapterId":"ch_work_han_thu_36","textTraditional":"成帝綏和（三）〔二〕年二月，大廄馬生角，在左耳前，圍長各二寸。是時王莽為大司馬，害上之萌自此始矣。〔一〕哀帝建平二年，定襄牡馬生駒，三足，隨群飲食，太守以聞。馬，國之武用，三足，不任用之象也。後侍中董賢年二十二為大司馬，居上公之位，天下不宗。哀帝暴崩，成帝母王太后召弟子新都侯王莽入，收賢印綬，賢恐，自殺，莽因代之，並誅外家丁、傅。又廢哀帝傅皇后，令自殺，發掘帝祖母傅太后、母丁太后陵，更以庶人葬之。辜及至尊，大臣微弱之禍也。","sentenceOrder":237},
  {"id":"s_work_han_thu_36_238","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「萌，若草木之始生也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_36_239","chapterId":"ch_work_han_thu_36","textTraditional":"文公十一年，「敗狄于鹹」。〔一〕穀梁、公羊傳曰，長狄〔二〕兄弟三人，一者之魯，〔三〕一者之齊，〔四〕一者之晉。〔五〕皆殺之，身橫九畝；〔六〕斷其首而載之，眉見於軾。〔七〕何以書？記異也。劉向以為是時周室衰微，三國為大，可責者也。天戒若曰，不行禮義，大為夷狄之行，將至危亡。其後三國皆有篡弒之禍〔八〕，近下人伐上之痾也。劉歆以為人變，屬黃祥。一曰，屬臝蟲之孽。一曰，天地之性人為貴，凡人為變，皆屬皇極下人伐上之痾云。京房易傳曰：「君暴亂，疾有道，厥妖長狄入國。」又曰：「豐其屋，下獨苦。〔九〕長狄生，世主虜。」","sentenceOrder":239},
  {"id":"s_work_han_thu_36_240","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「鹹，魯地也。」","sentenceOrder":240},
  {"id":"s_work_han_thu_36_241","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「防風之後，漆姓也，國號鄋瞞。鄋音所求反。瞞音莫干反。」","sentenceOrder":241},
  {"id":"s_work_han_thu_36_242","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「僑如也。來伐魯，為叔孫得臣所獲。」","sentenceOrder":242},
  {"id":"s_work_han_thu_36_243","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　師古曰：「榮如也。齊襄公二年伐齊，為王子成父所獲。」","sentenceOrder":243},
  {"id":"s_work_han_thu_36_244","chapterId":"ch_work_han_thu_36","textTraditional":"〔五〕　師古曰：「焚如也。宣十五年，晉滅潞國而獲之。」","sentenceOrder":244},
  {"id":"s_work_han_thu_36_245","chapterId":"ch_work_han_thu_36","textTraditional":"〔六〕　師古曰：「畮，古畝字。」","sentenceOrder":245},
  {"id":"s_work_han_thu_36_246","chapterId":"ch_work_han_thu_36","textTraditional":"〔七〕　師古曰：「軾，車前橫木。」","sentenceOrder":246},
  {"id":"s_work_han_thu_36_247","chapterId":"ch_work_han_thu_36","textTraditional":"〔八〕　師古曰：「謂魯文公薨，襄仲弒惡及視而立宣公；齊連稱、管至父弒襄公而立無知；晉欒書、中行偃弒厲公而立悼公。」","sentenceOrder":247},
  {"id":"s_work_han_thu_36_248","chapterId":"ch_work_han_thu_36","textTraditional":"〔九〕　師古曰：「豐其屋，易豐卦上六爻辭也。豐，大也。」","sentenceOrder":248},
  {"id":"s_work_han_thu_36_249","chapterId":"ch_work_han_thu_36","textTraditional":"史記秦始皇帝二十六年，有大人長五丈，足履六尺，皆夷狄服，凡十二人，見于臨洮。〔一〕天戒若曰，勿大為夷狄之行，將受其禍。是歲始皇初并六國，反喜以為瑞，銷天下兵器，作金人十二以象之。遂自賢聖，燔詩書，阬儒士；奢淫暴虐，務欲廣地；南戍五嶺，北築長城以備胡越，〔二〕塹山填谷，西起臨洮，東至遼東，徑數千里。故大人見於臨洮，明禍亂之起。後十四年而秦亡，亡自戍卒陳勝發。","sentenceOrder":249},
  {"id":"s_work_han_thu_36_250","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「隴西之縣也。音吐高反。」","sentenceOrder":250},
  {"id":"s_work_han_thu_36_251","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「五嶺，解在張耳陳餘傳。」","sentenceOrder":251},
  {"id":"s_work_han_thu_36_252","chapterId":"ch_work_han_thu_36","textTraditional":"史記魏襄王十三年，魏有女子化為丈夫。京房易傳曰：「女子化為丈夫，茲謂陰昌，賤人為王；丈夫化為女子，茲謂陰勝，厥咎亡。」一曰，男化為女，宮刑濫也；〔一〕女化為男，婦政行也。","sentenceOrder":252},
  {"id":"s_work_han_thu_36_253","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　如淳曰：「宮刑之行大濫也。」","sentenceOrder":253},
  {"id":"s_work_han_thu_36_254","chapterId":"ch_work_han_thu_36","textTraditional":"哀帝建平中，豫章有男子化為女子，嫁為人婦，生一子。長安陳鳳言此陽變為陰，將亡繼嗣，自相生之象。一曰，嫁為人婦生一子〔者〕，將復一世乃絕。","sentenceOrder":254},
  {"id":"s_work_han_thu_36_255","chapterId":"ch_work_han_thu_36","textTraditional":"哀帝建平四年四月，山陽方與女子田無嗇生子。〔一〕先未生二月，兒啼腹中，及生，不舉，葬之陌上，三日，人過聞啼聲，母掘收養。","sentenceOrder":255},
  {"id":"s_work_han_thu_36_256","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「方與者，山陽之縣也。女子姓田，名無嗇。方與音房豫。」","sentenceOrder":256},
  {"id":"s_work_han_thu_36_257","chapterId":"ch_work_han_thu_36","textTraditional":"平帝元始元年二月，朔方廣牧女子趙春病死，〔一〕斂棺積六日，〔二〕出在棺外，自言見夫死父，曰：「年二十七，不當死。」太守譚以聞。京房易傳曰：「『幹父之蠱，有子，考亡咎』。〔三〕子三年不改父道，思慕不皇，亦重見先人之非，〔四〕不則為私，厥妖人死復生。」一曰，至陰為陽，下人為上。","sentenceOrder":257},
  {"id":"s_work_han_thu_36_258","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「廣牧，朔方之縣也。姓趙，名春。」","sentenceOrder":258},
  {"id":"s_work_han_thu_36_259","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「斂音力贍反。棺音工喚反。」","sentenceOrder":259},
  {"id":"s_work_han_thu_36_260","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　韋昭曰：「蠱事也。子能正父之事，是為有子，故考不為咎累。」師古曰：「易蠱卦初六爻辭也。」","sentenceOrder":260},
  {"id":"s_work_han_thu_36_261","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　師古曰：「言父有不善之事，當速改之，若唯思慕而已，無所變易，是重顯先人之非也。一曰，三年之內，但思慕而已，不暇見父之非，故不改也。重音直用反。」","sentenceOrder":261},
  {"id":"s_work_han_thu_36_262","chapterId":"ch_work_han_thu_36","textTraditional":"六月，長安女子有生兒，兩頭異頸面相鄉，四臂共匈俱前鄉〔一〕，凥上有目長二寸所。京房易傳曰：「『睽孤，見豕負塗』，〔二〕厥妖人生兩頭。下相攘善，妖亦同。人若六畜首目在下，茲謂亡上，正將變更。凡妖之作，以譴失正，各象其類。二首，下不壹也；足多，所任邪也；足少，下不勝任，或不任下也。凡下體生於上，不敬也；上體生於下，媟瀆也；生非其類，淫亂也；人生而大，上速成也；生而能言，好虛也。群妖推此類，不改乃成凶也。」","sentenceOrder":262},
  {"id":"s_work_han_thu_36_263","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":263},
  {"id":"s_work_han_thu_36_264","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「易睽卦上九象辭也。睽孤，乖剌之意也。塗，泥也。睽音苦攜反。」","sentenceOrder":264},
  {"id":"s_work_han_thu_36_265","chapterId":"ch_work_han_thu_36","textTraditional":"景帝二年九月，膠東下密人年七十餘，生角，角有毛。時膠東、膠西、濟南、齊四（主）〔王〕有舉兵反謀，謀由吳王濞起，連楚、趙，凡七國。下密，縣居四齊之中；〔一〕角，兵象，上鄉者也〔二〕；老人，吳王象也；年七十，七國象也。天戒若曰，人不當生角，猶諸侯不當舉兵以鄉京師也；禍從老人生，七國俱敗云。諸侯不寤，明年吳王先起，諸侯從之，七國俱滅。京房易傳曰：「冢宰專政，厥妖人生角。」","sentenceOrder":265},
  {"id":"s_work_han_thu_36_266","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「四齊即上所云膠東、膠西、濟南、齊也。本皆齊地，故謂之四齊。」","sentenceOrder":266},
  {"id":"s_work_han_thu_36_267","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「鄉讀曰嚮。次下亦同。」","sentenceOrder":267},
  {"id":"s_work_han_thu_36_268","chapterId":"ch_work_han_thu_36","textTraditional":"成帝建始三年十月丁未，京師相驚，言大水至。渭水虒上小女陳持弓年九歲，〔一〕走入橫城門，入未央宮尚方掖門，殿門門衛戶者莫見，至句盾禁中而覺得。〔二〕民以水相驚者，陰氣盛也。小女而入宮殿中者，下人將因女寵而居有宮室之象也。名曰持弓，有似周家檿弧之祥。易曰：「弧矢之利，以威天下。」〔三〕是時，帝母王太后弟鳳始為上將，秉國政，天知其後將威天下而入宮室，故象先見也。其後，王氏兄弟父子五侯秉權，至莽卒篡天下，蓋陳氏之後云。京房易傳曰：「妖言動眾，茲謂不信，路將亡人，司馬死。」","sentenceOrder":268},
  {"id":"s_work_han_thu_36_269","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「虒上，地名也。音斯。」","sentenceOrder":269},
  {"id":"s_work_han_thu_36_270","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「句盾，少府之署。覺得，事覺而見執得也。」","sentenceOrder":270},
  {"id":"s_work_han_thu_36_271","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「下繫之辭也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_36_272","chapterId":"ch_work_han_thu_36","textTraditional":"成帝綏和二年八月庚申，鄭通里男子王褒〔一〕衣絳衣小冠，帶劍入北司馬門殿東門，〔二〕上前殿，入非常室中，〔三〕解帷組結佩之，〔四〕招前殿署長業等曰：「天帝令我居此。」業等收縛考問，褒故公車大誰卒，〔五〕病狂易，〔六〕不自知入宮狀，下獄死。是時王莽為大司馬，哀帝即位，莽乞骸骨就第，天知其必不退，故因是而見象也。姓名章服甚明，徑上前殿路寢，入室取組而佩之，稱天帝命，然時人莫察。後莽就國，天下冤之，哀帝徵莽還京師。明年帝崩，莽復為大司馬，因是而篡國。","sentenceOrder":272},
  {"id":"s_work_han_thu_36_273","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　師古曰：「鄭縣之通里。」","sentenceOrder":273},
  {"id":"s_work_han_thu_36_274","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「入北司馬門，又入殿之東門也。」","sentenceOrder":274},
  {"id":"s_work_han_thu_36_275","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　如淳曰：「殿上室名。」","sentenceOrder":275},
  {"id":"s_work_han_thu_36_276","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　師古曰：「組，綬類，所以係帷，又垂以為飾也。佩帶之。」","sentenceOrder":276},
  {"id":"s_work_han_thu_36_277","chapterId":"ch_work_han_thu_36","textTraditional":"〔五〕　應劭曰：「在司馬殿門掌讙呵者也。」服虔曰：「衛士之師也，著樊噲冠。」師古曰：「大誰者，主問非常之人，云姓名是誰也。而應氏乃以讙譁為義，云大讙呵，不當厥理。後之學者輒改此書誰字為讙，違本文矣。大誰本以誰何稱，因用名官，有大誰長。今此卒者，長所領士卒也。」","sentenceOrder":277},
  {"id":"s_work_han_thu_36_278","chapterId":"ch_work_han_thu_36","textTraditional":"〔六〕　師古曰：「謂病狂而變易其常也。」","sentenceOrder":278},
  {"id":"s_work_han_thu_36_279","chapterId":"ch_work_han_thu_36","textTraditional":"哀帝建平四年正月，民驚走，持稿或棷一枚，〔一〕傳相付與，曰行詔籌。道中相過逢多至千數，或被髮徒踐，〔二〕或夜折關，或踰牆入，或乘車騎奔馳，以置驛傳行，經歷郡國二十六，至京師。其夏，京師郡國民聚會里巷仟佰，設（祭）張博具，〔三〕歌舞祠西王母，又傳書曰：「母告百姓，佩此書者不死。不信我言，視門樞下，當有白髮。」〔四〕至秋止。是時帝祖母傅太后驕，與政事，〔五〕故杜鄴對曰：「春秋災異，以指象為言語。籌，所以紀數。民，陰，水類也。水以東流為順走，而西行，反類逆上。象數度放溢，妄以相予，違忤民心之應也。西王母，婦人之稱。博弈，男子之事。於街巷仟伯，明離闑內，〔六〕與疆外。〔七〕臨事盤樂，炕陽之意。白髮，衰年之象，體尊性弱，難理易亂。門，人之所由；樞，其要也。居人之所由，制持其要也。其明甚者。今外家丁、傅並侍帷幄，布於列位，有罪惡者不坐辜罰，亡功能者畢受官爵。皇甫、三桓，詩人所刺，春秋所譏，亡以甚此。〔八〕指象昭昭，以覺聖朝，柰何不應！」後哀帝崩，成帝母王太后臨朝，王莽為大司馬，誅滅丁、傅。一曰丁、傅所亂者小，此異乃王太后、莽之應云。","sentenceOrder":279},
  {"id":"s_work_han_thu_36_280","chapterId":"ch_work_han_thu_36","textTraditional":"〔一〕　如淳曰：「棷，麻幹也。」師古曰：「稿，禾稈也，音工老反。棷音鄒，又音側九反。」","sentenceOrder":280},
  {"id":"s_work_han_thu_36_281","chapterId":"ch_work_han_thu_36","textTraditional":"〔二〕　師古曰：「徒踐，謂（徙）〔徒〕跣也。」","sentenceOrder":281},
  {"id":"s_work_han_thu_36_282","chapterId":"ch_work_han_thu_36","textTraditional":"〔三〕　師古曰：「博戲之具。」","sentenceOrder":282},
  {"id":"s_work_han_thu_36_283","chapterId":"ch_work_han_thu_36","textTraditional":"〔四〕　師古曰：「樞，門扇所由開閉者也，音昌于反。」","sentenceOrder":283},
  {"id":"s_work_han_thu_36_284","chapterId":"ch_work_han_thu_36","textTraditional":"〔五〕　師古曰：「與讀曰豫。」","sentenceOrder":284},
  {"id":"s_work_han_thu_36_285","chapterId":"ch_work_han_thu_36","textTraditional":"〔六〕　師古曰：「闑，門橛也，音魚列反。」","sentenceOrder":285},
  {"id":"s_work_han_thu_36_286","chapterId":"ch_work_han_thu_36","textTraditional":"〔七〕　師古曰：「與讀曰預。」","sentenceOrder":286},
  {"id":"s_work_han_thu_36_287","chapterId":"ch_work_han_thu_36","textTraditional":"〔八〕　師古曰：「皇甫，周卿士之字也。用后嬖寵，而處職位，詩人刺之。事見小雅十月之交篇。」","sentenceOrder":287},
  {"id":"s_work_han_thu_36_288","chapterId":"ch_work_han_thu_36","textTraditional":"校勘記","sentenceOrder":288},
  {"id":"s_work_han_thu_36_289","chapterId":"ch_work_han_thu_36","textTraditional":"一四四三頁　五行　厥風絕經（紀）〔緯〕，　殿、局本都作「緯」。王先謙說，據注文，作「緯」是。","sentenceOrder":289},
  {"id":"s_work_han_thu_36_290","chapterId":"ch_work_han_thu_36","textTraditional":"一四四五頁　二行　正（書）〔晝〕雷，　景祐、殿本都作「晝」。王先謙說作「晝」是。","sentenceOrder":290},
  {"id":"s_work_han_thu_36_291","chapterId":"ch_work_han_thu_36","textTraditional":"一四四五頁一二行　言其始有（成）〔威〕權。　景祐、殿本都作「威」。朱一新說作「威」是。","sentenceOrder":291},
  {"id":"s_work_han_thu_36_292","chapterId":"ch_work_han_thu_36","textTraditional":"一四四六頁　七行　〔邴〕，鄭祀泰之邑也。　王先謙說殿本「鄭」作「邴」是。按景祐、局本都作「鄭」，當於「鄭」上補「邴」字，文義方足。","sentenceOrder":292},
  {"id":"s_work_han_thu_36_293","chapterId":"ch_work_han_thu_36","textTraditional":"一四四六頁　九行　（謂）〔為〕災孽也。　景祐、殿本都作「為」。　朱一新說作「為」是。","sentenceOrder":293},
  {"id":"s_work_han_thu_36_294","chapterId":"ch_work_han_thu_36","textTraditional":"一四四六頁一二行　左公子（涸）〔泄〕，　景祐、殿本都作「泄」，朱一新說作「泄」是。","sentenceOrder":294},
  {"id":"s_work_han_thu_36_295","chapterId":"ch_work_han_thu_36","textTraditional":"一四四七頁　七行　時（成）〔文〕公喪制未除。殿本作「文」，景祐、汲古、局本都誤作「成」。","sentenceOrder":295},
  {"id":"s_work_han_thu_36_296","chapterId":"ch_work_han_thu_36","textTraditional":"一四四八頁　九行　王心弗（（暂缺F609））〔〈式，中“工改今”〉〕，　景祐、殿本作「〈式，中“工改今”〉」。朱一新說作「〈式，中“工改今”〉」是。","sentenceOrder":296},
  {"id":"s_work_han_thu_36_297","chapterId":"ch_work_han_thu_36","textTraditional":"一四五一頁一三行　是歲（二）〔三〕川竭，　景祐、殿本都作「三」。葉德輝說作「三」是。","sentenceOrder":297},
  {"id":"s_work_han_thu_36_298","chapterId":"ch_work_han_thu_36","textTraditional":"一四五五頁　六行　及齊（威）〔桓〕死，　景祐、殿本都作「桓」。","sentenceOrder":298},
  {"id":"s_work_han_thu_36_299","chapterId":"ch_work_han_thu_36","textTraditional":"一四六九頁一０行　竟讀曰境（也）。　殿本無「也」字。","sentenceOrder":299},
  {"id":"s_work_han_thu_36_300","chapterId":"ch_work_han_thu_36","textTraditional":"一四六九頁一一行　迋音君狂〔反〕。　「反」字據景祐本補。","sentenceOrder":300},
  {"id":"s_work_han_thu_36_301","chapterId":"ch_work_han_thu_36","textTraditional":"一四六九頁一五行　〔一〕曰，諸畜生非其類，　景祐、殿本都有「一」字。","sentenceOrder":301},
  {"id":"s_work_han_thu_36_302","chapterId":"ch_work_han_thu_36","textTraditional":"一四七０頁一一行　荊燕吳傳與紀（罔）〔同〕矣。　景祐、殿本都作「同」。朱一新說作「同」是。","sentenceOrder":302},
  {"id":"s_work_han_thu_36_303","chapterId":"ch_work_han_thu_36","textTraditional":"一四七０頁一二行　成帝綏和（三）〔二〕年二月，　景祐、殿本都作「二」。","sentenceOrder":303},
  {"id":"s_work_han_thu_36_304","chapterId":"ch_work_han_thu_36","textTraditional":"一四七三頁　一行　嫁為人婦生一子〔者〕，　景祐、殿本都有「者」字。","sentenceOrder":304},
  {"id":"s_work_han_thu_36_305","chapterId":"ch_work_han_thu_36","textTraditional":"一四七四頁　六行　四（主）〔王〕　景祐、殿本都作「王」。朱一新說作「王」是。","sentenceOrder":305},
  {"id":"s_work_han_thu_36_306","chapterId":"ch_work_han_thu_36","textTraditional":"一四七六頁　九行　設（祭）張博具，　錢大昭說閩本無「祭」字。朱一新說汪本無「祭」字。景祐本亦無。","sentenceOrder":306},
  {"id":"s_work_han_thu_36_307","chapterId":"ch_work_han_thu_36","textTraditional":"一四七七頁　四行　謂（徙）〔徒〕跣也。　景祐、殿本都作「徒」。王先謙說作「徒」是。","sentenceOrder":307},
  {"id":"s_work_han_thu_37_1","chapterId":"ch_work_han_thu_37","textTraditional":"隱公三年「二月己巳，日有食之」。穀梁傳曰，言日不言朔，食晦。公羊傳曰，食二日，董仲舒、劉向以為其後戎執天子之使，〔一〕鄭獲魯隱，〔二〕滅戴，〔三〕衛、魯、宋咸殺君。〔四〕左氏劉歆以為正月二日，燕、越之分野也。凡日所躔而有變，則分野之國失政者受之。〔五〕人君能修政，共御厥罰，則災消而福至；〔六〕不能，則災息而禍生。〔七〕故經書災而不記其故，蓋吉凶亡常，隨行而成禍福也。周衰，天子不班朔，〔八〕魯曆不正，置閏不得其月，月大小不得其度。史記（曰）〔日〕食，或言朔而實非朔，或不言朔而實朔，或脫不書朔與日，皆官失之也。京房易傳曰：「亡師茲謂不御，厥異日食，其食也既，並食不一處。誅眾失理，茲謂生叛，厥食既，光散。縱畔茲謂不明，厥食先大雨三日，雨除而寒，寒即食。專祿不封，茲謂不安，厥食既，先日出而黑，光反外燭。〔九〕君臣不通茲謂亡，厥蝕三既。同姓上侵，茲謂誣君，厥食四方有雲，中央無雲，其日大寒。公欲弱主位，茲謂不知，厥食中白青，四方赤，已食地震。諸侯相侵，茲謂不承，厥食三毀三復。君疾善，下謀上，茲謂亂，厥食既，先雨雹，殺走獸。弒君獲位茲謂逆，厥食既，先風雨折木，日赤。內臣外鄉茲謂背，〔一０〕厥食食且雨，地中鳴。〔一一〕冢宰專政茲謂因，厥食先大風，食時日居雲中，四方亡雲。伯正越職，茲謂分威，〔一二〕厥食日中分。諸侯爭美於上茲謂泰，厥食日傷月，食半，天營而鳴。〔一三〕賦不得茲謂竭，厥食星隨而下。受命之臣專征云試，厥食雖侵光猶明，〔一四〕若文王臣獨誅紂矣〔一五〕。小人順受命者征其君云殺，厥食五色，至大寒隕霜，〔一六〕若紂臣順武王而誅紂矣。〔一七〕諸侯更制茲謂叛，〔一八〕厥食三復三食，食已而風，地動。適讓庶茲謂生欲，〔一九〕厥食日失位，光晻晻，月形見。〔二０〕酒亡節茲謂荒，厥蝕乍青乍黑乍赤，明日大雨，發霧而寒。」凡食二十占，其形二十有四，改之輒除；不改三年，三年不改六年，六年不改九年。推隱三年之食，貫中央，上下竟而黑，臣弒從中成之形也。後衛州吁弒君而立。","sentenceOrder":1},
  {"id":"s_work_han_thu_37_2","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「凡伯，周大夫也。隱七年，天王使凡伯來聘，戎伐凡伯于楚丘以歸。」","sentenceOrder":2},
  {"id":"s_work_han_thu_37_3","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「公羊傳隱六年春鄭人來渝平。渝平，墮（城）〔成〕也。曰『吾成敗矣，吾與鄭人未有成』。狐壤之戰，隱公獲焉。何以不言戰？諱獲也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_37_4","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「十年秋，宋人、蔡人、衛人伐戴，鄭伯伐取之。戴國，今外黃縣東南戴城是也。讀者多誤為載，故隨室置載州焉。」","sentenceOrder":4},
  {"id":"s_work_han_thu_37_5","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「四年，衛州吁殺其君完。十一年，羽父使賊殺公于寪氏。桓二年春，宋督弒其君與夷。」","sentenceOrder":5},
  {"id":"s_work_han_thu_37_6","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「躔，踐也，音纏。」","sentenceOrder":6},
  {"id":"s_work_han_thu_37_7","chapterId":"ch_work_han_thu_37","textTraditional":"〔六〕　師古曰：「共讀曰恭。御讀曰禦，又讀如本字。」","sentenceOrder":7},
  {"id":"s_work_han_thu_37_8","chapterId":"ch_work_han_thu_37","textTraditional":"〔七〕　師古曰：「息謂蕃滋也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_37_9","chapterId":"ch_work_han_thu_37","textTraditional":"〔八〕　師古曰：「班，布也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_37_10","chapterId":"ch_work_han_thu_37","textTraditional":"〔九〕　韋昭曰：「中無光，四邊有明外燭。」","sentenceOrder":10},
  {"id":"s_work_han_thu_37_11","chapterId":"ch_work_han_thu_37","textTraditional":"〔一０〕師古曰：「鄉讀曰嚮。」","sentenceOrder":11},
  {"id":"s_work_han_thu_37_12","chapterId":"ch_work_han_thu_37","textTraditional":"〔一一〕韋昭曰：「地中有聲如鳴耳，或曰如狗子聲。」","sentenceOrder":12},
  {"id":"s_work_han_thu_37_13","chapterId":"ch_work_han_thu_37","textTraditional":"〔一二〕師古曰：「伯讀曰霸。正者，長帥之稱。」","sentenceOrder":13},
  {"id":"s_work_han_thu_37_14","chapterId":"ch_work_han_thu_37","textTraditional":"〔一三〕韋昭曰：「食半，謂食望也。」臣瓚曰：「月食半，謂食月之半也。月食常以望，不為異也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_37_15","chapterId":"ch_work_han_thu_37","textTraditional":"〔一四〕師古曰：「試，用也，自擅意也。一說試與弒同，謂欲弒君。」","sentenceOrder":15},
  {"id":"s_work_han_thu_37_16","chapterId":"ch_work_han_thu_37","textTraditional":"〔一五〕韋昭曰：「是時紂臣尚未欲誅紂，獨文王之臣欲誅之。」","sentenceOrder":16},
  {"id":"s_work_han_thu_37_17","chapterId":"ch_work_han_thu_37","textTraditional":"〔一六〕師古曰：「殺亦讀曰弒。」","sentenceOrder":17},
  {"id":"s_work_han_thu_37_18","chapterId":"ch_work_han_thu_37","textTraditional":"〔一七〕韋昭曰：「紂惡益甚，其臣欲順武王而誅紂。」","sentenceOrder":18},
  {"id":"s_work_han_thu_37_19","chapterId":"ch_work_han_thu_37","textTraditional":"〔一八〕師古曰：「更，改也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_37_20","chapterId":"ch_work_han_thu_37","textTraditional":"〔一九〕師古曰：「適讀曰嫡。」","sentenceOrder":20},
  {"id":"s_work_han_thu_37_21","chapterId":"ch_work_han_thu_37","textTraditional":"〔二０〕師古曰：「晻音烏感反。見音胡電反。」","sentenceOrder":21},
  {"id":"s_work_han_thu_37_22","chapterId":"ch_work_han_thu_37","textTraditional":"桓公三年「七月壬辰朔，日有食之，既」。董仲舒、劉向以為前事已大，後事將至者又大，則既。先是魯、宋弒君，魯又成宋亂，易許田，亡事天子之心；楚僭稱王。後鄭岠王師，射桓王，〔一〕又二君相篡。〔二〕劉歆以為六月，趙與晉分。〔三〕先是，晉曲沃伯再弒晉侯，〔四〕是歲晉大亂，〔五〕滅其宗國。〔六〕京房易傳以為桓三年日食貫中央，上下竟而黃，臣弒而不卒之形也。後楚嚴稱王，兼地千里。〔七〕","sentenceOrder":22},
  {"id":"s_work_han_thu_37_23","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「並已解於上。」","sentenceOrder":23},
  {"id":"s_work_han_thu_37_24","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「謂厲公奔蔡而昭公入，高渠彌殺昭公而立子亹。」","sentenceOrder":24},
  {"id":"s_work_han_thu_37_25","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　晉灼曰：「周之六月，今之四月，始去畢而入參。參，晉分也。畢，趙也。日行去趙遠，入晉分多，故曰與。計二十八宿，分其次，度其月，及所屬，下皆以為例。」","sentenceOrder":25},
  {"id":"s_work_han_thu_37_26","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「曲沃伯，本桓叔成師之封號也，其後遂繼襲焉。魯惠公三十年，大夫潘父殺昭侯而納成師，不克，晉人立孝侯。惠之四十五年，成師之子曲沃莊伯伐翼，殺孝侯也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_37_27","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「桓三年，莊伯之子曲沃武公伐翼，逐翼侯于汾隰，夜獲而殺之。」","sentenceOrder":27},
  {"id":"s_work_han_thu_37_28","chapterId":"ch_work_han_thu_37","textTraditional":"〔六〕　師古曰：「桓八年，曲沃武公滅翼，遂并其國。」","sentenceOrder":28},
  {"id":"s_work_han_thu_37_29","chapterId":"ch_work_han_thu_37","textTraditional":"〔七〕　師古曰：「楚武王荊尸久已見傳，今此言莊始稱王，未詳其說。」","sentenceOrder":29},
  {"id":"s_work_han_thu_37_30","chapterId":"ch_work_han_thu_37","textTraditional":"十七年「十月朔，日有食之」。穀梁傳曰，言朔不言日，食二日也。劉向以為是時衛侯朔有罪出奔齊，〔一〕天子更立衛君。〔二〕朔藉助五國，舉兵伐之而自立，王命遂壞。〔三〕魯夫人淫失於齊，卒殺威公。〔四〕董仲舒以為言朔不言日，惡魯桓且有夫人之禍，將不終日也。劉歆以為楚、鄭分。","sentenceOrder":30},
  {"id":"s_work_han_thu_37_31","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「朔，衛惠公也。桓十六年經書『衛侯朔出奔齊』。公羊傳曰『得罪乎天子』，穀梁傳曰『天子召而不往也』。」","sentenceOrder":31},
  {"id":"s_work_han_thu_37_32","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「謂公子黔牟。」","sentenceOrder":32},
  {"id":"s_work_han_thu_37_33","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「莊五年冬，公會齊人、宋人、陳人、蔡人伐衛。莊六年春，王人子突救衛，夏，衛侯朔入，放公子黔牟于周，是也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_37_34","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「失讀曰佚。」","sentenceOrder":34},
  {"id":"s_work_han_thu_37_35","chapterId":"ch_work_han_thu_37","textTraditional":"嚴公十八年「三月，日有食之」。穀梁傳曰，不言日，不言朔，夜食。〔一〕史推合朔在夜，明旦日食而出，出而解，〔二〕是為夜食。劉向以為夜食者，陰因日明之衰而奪其光，象周天子不明，齊桓將奪其威，專會諸侯而行伯道。〔三〕其後遂九合諸侯，〔四〕天子使世子會之，〔五〕此其效也。公羊傳曰食晦。董仲舒以為宿在東壁，魯象也。後公子慶父、叔牙果通於夫人以劫公。劉歆以為晦魯、衛分。","sentenceOrder":35},
  {"id":"s_work_han_thu_37_36","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　張晏曰：「日夜食，則無景。立六尺木不見其景，以此為候。」","sentenceOrder":36},
  {"id":"s_work_han_thu_37_37","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　孟康曰：「夜食地中，出而止。」","sentenceOrder":37},
  {"id":"s_work_han_thu_37_38","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「伯讀曰霸。」","sentenceOrder":38},
  {"id":"s_work_han_thu_37_39","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「解在郊祀志。」","sentenceOrder":39},
  {"id":"s_work_han_thu_37_40","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「僖五年，齊侯、宋公、陳侯、衛侯、鄭伯、許男、曹伯會王太子于首止是。」","sentenceOrder":40},
  {"id":"s_work_han_thu_37_41","chapterId":"ch_work_han_thu_37","textTraditional":"二十五年「六月辛未朔，日有食之」。董仲舒以為宿在畢，主邊兵夷狄象也。後狄滅邢、衛。〔一〕劉歆以為五月二日魯、趙分。","sentenceOrder":41},
  {"id":"s_work_han_thu_37_42","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「春秋閔元年狄伐邢，二年狄滅衛，其後並為齊所立，而邢遷于夷儀，衛遷于楚丘。」","sentenceOrder":42},
  {"id":"s_work_han_thu_37_43","chapterId":"ch_work_han_thu_37","textTraditional":"二十六年「十二月癸亥朔，日有食之」。董仲舒以為宿在心，心為明堂，文武之道廢，中國不絕若綫之象也。〔一〕劉向以為時戎侵曹，〔二〕魯夫人淫於慶父、叔牙，將以弒君，故比年再蝕以見戒。〔三〕劉歆以為十月二日楚、鄭分。","sentenceOrder":43},
  {"id":"s_work_han_thu_37_44","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「綫，縷也，音先箭反。」","sentenceOrder":44},
  {"id":"s_work_han_thu_37_45","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「事在莊二十四年。」","sentenceOrder":45},
  {"id":"s_work_han_thu_37_46","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「比，頻也。見，顯也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_37_47","chapterId":"ch_work_han_thu_37","textTraditional":"三十年「九月庚午朔，日有食之」。董仲舒、劉向以為後魯二君弒，〔一〕夫人誅，〔二〕兩弟死，〔三〕狄滅邢，〔四〕徐取舒，〔五〕晉殺世子，〔六〕楚滅弦。〔七〕劉歆以為八月秦、周分。","sentenceOrder":47},
  {"id":"s_work_han_thu_37_48","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「謂子般為圉人所殺，閔公為卜齮所殺也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_37_49","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「哀姜為齊人所殺。」","sentenceOrder":49},
  {"id":"s_work_han_thu_37_50","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「謂叔牙及慶父也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_37_51","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「已解於上。」","sentenceOrder":51},
  {"id":"s_work_han_thu_37_52","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「僖三年，徐人取舒。舒，國名也，在廬江舒縣也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_37_53","chapterId":"ch_work_han_thu_37","textTraditional":"〔六〕　師古曰：「僖五年，晉侯殺其太子申生。」","sentenceOrder":53},
  {"id":"s_work_han_thu_37_54","chapterId":"ch_work_han_thu_37","textTraditional":"〔七〕　師古曰：「僖五年，楚人滅弦。弦，國名也，在弋陽。」","sentenceOrder":54},
  {"id":"s_work_han_thu_37_55","chapterId":"ch_work_han_thu_37","textTraditional":"僖公五年「九月戊申朔，日有食之」。董仲舒、劉向以為先是齊桓行伯，江、黃自至，〔一〕南服彊楚。〔二〕其後不內自正，而外執陳大夫，則陳、楚不附，〔三〕鄭伯逃盟，〔四〕諸侯將不從桓政，故天見戒。其後晉滅虢，〔五〕楚（國）〔圍〕許，諸侯伐鄭〔六〕，晉弒二君，〔七〕狄滅溫，〔八〕楚伐黃，〔九〕桓不能救。劉歆以為七月秦、晉分。","sentenceOrder":55},
  {"id":"s_work_han_thu_37_56","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「伯讀曰霸。江、黃，二國名也。僖二年，齊侯、宋公、江人、黃人盟于貫。傳曰『服江、黃也』。江國在汝南安陽縣，黃國在弋陽縣。」","sentenceOrder":56},
  {"id":"s_work_han_thu_37_57","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「僖四年，齊侯以諸侯之師侵蔡，遂伐楚，盟于邵陵。」","sentenceOrder":57},
  {"id":"s_work_han_thu_37_58","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「邵陵盟後，以陳轅濤塗為誤軍而執之，陳不服罪，故伐之。楚自是不復通。」","sentenceOrder":58},
  {"id":"s_work_han_thu_37_59","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「僖五年秋，齊侯與諸侯盟于首止，鄭伯逃歸不盟。」","sentenceOrder":59},
  {"id":"s_work_han_thu_37_60","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「事在僖五年。」","sentenceOrder":60},
  {"id":"s_work_han_thu_37_61","chapterId":"ch_work_han_thu_37","textTraditional":"〔六〕　師古曰：「事並在僖六年。」","sentenceOrder":61},
  {"id":"s_work_han_thu_37_62","chapterId":"ch_work_han_thu_37","textTraditional":"〔七〕　師古曰：「謂里克弒奚齊及卓子。」","sentenceOrder":62},
  {"id":"s_work_han_thu_37_63","chapterId":"ch_work_han_thu_37","textTraditional":"〔八〕　師古曰：「溫，周邑也。僖十年，狄滅之。」","sentenceOrder":63},
  {"id":"s_work_han_thu_37_64","chapterId":"ch_work_han_thu_37","textTraditional":"〔九〕　師古曰：「僖十一年，黃不歸楚貢，故伐之。」","sentenceOrder":64},
  {"id":"s_work_han_thu_37_65","chapterId":"ch_work_han_thu_37","textTraditional":"十二年「三月庚午（朔），日有食之」。董仲舒、劉向以為是時楚滅黃，〔一〕狄侵衛、鄭，〔二〕莒滅杞。〔三〕劉歆以為三月齊、衛分。","sentenceOrder":65},
  {"id":"s_work_han_thu_37_66","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「事在十二年夏。」","sentenceOrder":66},
  {"id":"s_work_han_thu_37_67","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「僖十三年狄侵衛，十四年狄侵鄭。」","sentenceOrder":67},
  {"id":"s_work_han_thu_37_68","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「僖十四年諸侯城緣陵。公羊傳曰：『曷為城？杞滅也。孰滅之？蓋徐、莒也。』」","sentenceOrder":68},
  {"id":"s_work_han_thu_37_69","chapterId":"ch_work_han_thu_37","textTraditional":"十五年「五月，日有食之」。劉向以為象晉文公將行伯道，〔一〕後遂伐衛，執曹伯，敗楚城濮，〔二〕再會諸侯，〔三〕召天王而朝之，〔四〕此其效也。日食者臣之惡也，夜食者掩其罪也，以為上亡明王，桓、文能行伯道，攘夷狄，安中國，〔五〕雖不正猶可，蓋春秋實與而文不與之義也。董仲舒以為後秦獲晉侯，〔六〕齊滅項，〔七〕楚敗徐于婁林。〔八〕劉歆以為二月朔齊、越分。","sentenceOrder":69},
  {"id":"s_work_han_thu_37_70","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「伯讀曰霸。」","sentenceOrder":70},
  {"id":"s_work_han_thu_37_71","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「事並在二十八年。」","sentenceOrder":71},
  {"id":"s_work_han_thu_37_72","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「二十八年五月盟于踐土，冬會于溫。」","sentenceOrder":72},
  {"id":"s_work_han_thu_37_73","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「晉侯不欲就朝王，故召王使來。經書『天王狩于河陽』。」","sentenceOrder":73},
  {"id":"s_work_han_thu_37_74","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「伯讀曰霸。攘，卻也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_37_75","chapterId":"ch_work_han_thu_37","textTraditional":"〔六〕　師古曰：「晉侯，夷吾也。僖十五年十一月，晉侯及秦伯戰于韓，秦獲晉侯以歸也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_37_76","chapterId":"ch_work_han_thu_37","textTraditional":"〔七〕　師古曰：「事在公羊傳僖十七年。項國，今項城縣是也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_37_77","chapterId":"ch_work_han_thu_37","textTraditional":"〔八〕　師古曰：「事在僖十五年冬。婁林，徐地。」","sentenceOrder":77},
  {"id":"s_work_han_thu_37_78","chapterId":"ch_work_han_thu_37","textTraditional":"文公元年「二月癸亥，日有食之」。董仲舒、劉向以為先是大夫始執國政，〔一〕公子遂如京師，〔二〕後楚世子商臣殺父，齊公子商人弒君，皆自立，〔三〕宋子哀出奔，〔四〕晉滅江，〔五〕楚滅六，〔六〕大夫公孫敖、叔彭生並專會盟。〔七〕劉歆以為正月朔燕、越分。","sentenceOrder":78},
  {"id":"s_work_han_thu_37_79","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「謂東門襄仲也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_37_80","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「事在僖三十年，報宰周公之聘。」","sentenceOrder":80},
  {"id":"s_work_han_thu_37_81","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「已解於上。」","sentenceOrder":81},
  {"id":"s_work_han_thu_37_82","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「宋子哀，宋卿高哀也。不義宋公，而來奔魯。事在文十四年。」","sentenceOrder":82},
  {"id":"s_work_han_thu_37_83","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「春秋文四年『楚人滅江』，今此云晉，未詳其說。」","sentenceOrder":83},
  {"id":"s_work_han_thu_37_84","chapterId":"ch_work_han_thu_37","textTraditional":"〔六〕　師古曰：「六，國名也，在廬江六縣。文五年楚人滅之。」","sentenceOrder":84},
  {"id":"s_work_han_thu_37_85","chapterId":"ch_work_han_thu_37","textTraditional":"〔七〕　師古曰：「文七年冬公孫敖如莒蒞盟，十一年叔彭生會郤缺于承匡。公孫敖，孟穆伯；叔彭生，叔仲惠伯也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_37_86","chapterId":"ch_work_han_thu_37","textTraditional":"十五年「六月辛丑朔，日有食之」。董仲舒、劉向以為後宋、齊、莒、晉、鄭八年之間五君殺死，〔一〕（夷）〔楚〕滅舒蓼。劉歆以為四月二日魯、衛分。","sentenceOrder":86},
  {"id":"s_work_han_thu_37_87","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「文十六年宋弒其君杵臼，十八年夏齊人弒其君商人，冬莒弒其君庶其，宣二年晉趙盾弒其君夷皋，四年鄭公子歸生弒其君夷也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_37_88","chapterId":"ch_work_han_thu_37","textTraditional":"宣公八年「七月甲子，日有食之，既」。董仲舒、劉向以為先是楚商臣弒父而立，至于嚴王遂彊。諸夏大國唯有齊、晉，齊、晉新有篡弒之禍，內皆未安，故楚乘弱橫行，八年之間六侵伐而一滅國〔一〕；伐陸渾戎，觀兵周室；〔二〕後又入鄭，鄭伯肉袒謝罪；北敗晉師于邲，流血色水；〔三〕圍宋九月，析骸而炊之。〔四〕劉歆以為十月二日楚、鄭分。","sentenceOrder":88},
  {"id":"s_work_han_thu_37_89","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「六侵伐者，謂宣元年侵陳，三年侵鄭，四年伐鄭，五年伐鄭，六年伐鄭，八年伐陳也。一滅國者，謂八年滅舒蓼也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_37_90","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「宣三年『楚子伐陸渾之戎，遂至于洛，觀兵于周疆』。觀兵者，示威武也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_37_91","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「事並在十二年。邲，鄭地，色水，謂血流入水而變水之色也。邲音蒲必反。」","sentenceOrder":91},
  {"id":"s_work_han_thu_37_92","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「事在十五年。炊，爨也。言無薪樵，示困之甚也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_37_93","chapterId":"ch_work_han_thu_37","textTraditional":"十年「四月丙辰，日有食之」。董仲舒、劉向以為後陳夏徵舒弒其君，〔一〕楚滅蕭，〔二〕晉滅二國，〔三〕王札子殺召伯、毛伯。〔四〕劉歆以為二月魯、衛分。","sentenceOrder":93},
  {"id":"s_work_han_thu_37_94","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「弒靈公也。事在十年。」","sentenceOrder":94},
  {"id":"s_work_han_thu_37_95","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「蕭，宋附庸國也。事在十二年。」","sentenceOrder":95},
  {"id":"s_work_han_thu_37_96","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「謂十五年滅赤狄潞氏，十六年滅赤狄甲氏。」","sentenceOrder":96},
  {"id":"s_work_han_thu_37_97","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「事在十五年。」","sentenceOrder":97},
  {"id":"s_work_han_thu_37_98","chapterId":"ch_work_han_thu_37","textTraditional":"十七年「六月癸卯，日有食之」。董仲舒、劉向以為後邾支解鄫子，〔一〕晉敗王師于貿戎，〔二〕敗齊于鞍。〔三〕劉歆以為三月晦朓魯、衛分。〔四〕","sentenceOrder":98},
  {"id":"s_work_han_thu_37_99","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「十八年，邾人戕鄫子于鄫，支解而節斷之，謂解其四支，斷其骨節。」","sentenceOrder":99},
  {"id":"s_work_han_thu_37_100","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「事在成元年。」","sentenceOrder":100},
  {"id":"s_work_han_thu_37_101","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「事在成二年。」","sentenceOrder":101},
  {"id":"s_work_han_thu_37_102","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　服虔曰：「朓，相覜也。日晦食為朓。」臣瓚曰：「志云晦而月見西方曰朓，以此名之，非日食晦之名也。」師古曰：「朓音佗了反。」","sentenceOrder":102},
  {"id":"s_work_han_thu_37_103","chapterId":"ch_work_han_thu_37","textTraditional":"成公十六年「六月丙寅朔，日有食之」。董仲舒、劉向以為後晉敗楚、鄭于鄢陵，〔一〕執魯侯。〔二〕劉歆以為四月二日魯、衛分。","sentenceOrder":103},
  {"id":"s_work_han_thu_37_104","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「事在十六年。鄢陵，鄭地。」","sentenceOrder":104},
  {"id":"s_work_han_thu_37_105","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「已解於上。」","sentenceOrder":105},
  {"id":"s_work_han_thu_37_106","chapterId":"ch_work_han_thu_37","textTraditional":"十七年「十二月丁巳朔，日有食之」。董仲舒、劉向以為後楚滅舒庸，〔一〕晉弒其君，〔二〕宋魚石因楚奪君邑，〔三〕莒滅鄫，齊滅萊，〔四〕鄭伯弒死。〔五〕劉歆以為九月周、楚分。","sentenceOrder":106},
  {"id":"s_work_han_thu_37_107","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「事在十七年日食之後。舒庸，蓋群舒之一種，楚與國也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_37_108","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「謂厲公也。事在十八年。」","sentenceOrder":108},
  {"id":"s_work_han_thu_37_109","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「魚石，宋大夫也，十五年出奔楚，至十八年楚伐宋，取彭城而納之。」","sentenceOrder":109},
  {"id":"s_work_han_thu_37_110","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「事並在襄六年。鄫、萊皆小國。」","sentenceOrder":110},
  {"id":"s_work_han_thu_37_111","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「鄭僖公也，襄七年會于鄬，其大夫子駟使賊夜殺之，而以虐疾赴。鄬音蒍。」","sentenceOrder":111},
  {"id":"s_work_han_thu_37_112","chapterId":"ch_work_han_thu_37","textTraditional":"襄公十四年「二月乙未朔，日有食之」。董仲舒、劉向以為後衛大夫孫、甯共逐獻公，立孫剽。〔一〕劉歆以為前年十二月二日宋、燕分。","sentenceOrder":112},
  {"id":"s_work_han_thu_37_113","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　孟康曰：「剽音驃。」師古曰：「孫林父、甯殖逐獻公，襄十四年四月出奔齊，而立剽。剽，穆公之孫也。剽又音匹妙反。」","sentenceOrder":113},
  {"id":"s_work_han_thu_37_114","chapterId":"ch_work_han_thu_37","textTraditional":"十五年「八月丁巳〔朔〕，日有食之」。董仲舒、劉向以為先是晉為雞澤之會，諸侯盟，又大夫盟，後為溴梁之會，諸侯在而大夫獨相與盟，〔一〕君若綴斿，不得舉手。〔二〕劉歆以為五月二日魯、趙分。","sentenceOrder":114},
  {"id":"s_work_han_thu_37_115","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「並已解於上。」","sentenceOrder":115},
  {"id":"s_work_han_thu_37_116","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　應劭曰：「斿，旌旗之流，隨風動搖也。」師古曰：「言為下所執，隨人東西也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_37_117","chapterId":"ch_work_han_thu_37","textTraditional":"二十年「十月丙辰朔，日有食之」。董仲舒以為陳慶虎、慶寅蔽君之明，〔一〕邾庶其有叛心，〔二〕後庶其以漆、閭丘來奔，〔三〕陳殺二慶。〔四〕劉歆以為八月秦、周分。","sentenceOrder":117},
  {"id":"s_work_han_thu_37_118","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「二慶，並陳大夫也。襄二十年，陳侯之弟黃出奔楚，將出，呼於國曰：『慶氏無道，求專陳國，暴蔑其君，而去其親，五年不滅，是無天也。』」","sentenceOrder":118},
  {"id":"s_work_han_thu_37_119","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「庶其，邾大夫。」","sentenceOrder":119},
  {"id":"s_work_han_thu_37_120","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「事在二十一年。漆及閭丘，邾之二邑。」","sentenceOrder":120},
  {"id":"s_work_han_thu_37_121","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「二十三年，陳侯如楚，公子黃訴二慶。楚人召之，慶氏以陳叛楚，屈建從陳侯圍陳，遂殺二慶也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_37_122","chapterId":"ch_work_han_thu_37","textTraditional":"二十一年「九月庚戌朔，日有食之」。董仲舒以為晉欒盈將犯君，後入于曲沃。〔一〕劉歆以為七月秦、晉分。","sentenceOrder":122},
  {"id":"s_work_han_thu_37_123","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「已解於上。」","sentenceOrder":123},
  {"id":"s_work_han_thu_37_124","chapterId":"ch_work_han_thu_37","textTraditional":"「十月庚辰朔，日有食之」。董仲舒以為宿在軫、角，楚大國象也。後楚屈氏譖殺公子追舒，〔一〕齊慶封脅君亂國。〔二〕劉歆以為八月秦、周分。","sentenceOrder":124},
  {"id":"s_work_han_thu_37_125","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「公子追舒，楚令尹子南也。二十二年，楚殺之。」","sentenceOrder":125},
  {"id":"s_work_han_thu_37_126","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「慶封，齊大夫也。二十七年，使盧蒲嫳帥甲攻崔氏，殺成及彊，盡俘其家。崔杼縊而死，自是慶封當國，專執政也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_37_127","chapterId":"ch_work_han_thu_37","textTraditional":"二十三年「二月癸酉朔，日有食之」。董仲舒以為後衛侯入陳儀，〔一〕甯喜弒其君剽。〔二〕劉歆以為前年十二月二日宋、燕分。","sentenceOrder":127},
  {"id":"s_work_han_thu_37_128","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「衛侯衎也，前為孫、甯所逐，二十五年入于陳儀。陳儀，衛邑。左傳云夷儀。」","sentenceOrder":128},
  {"id":"s_work_han_thu_37_129","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「二十六年，甯喜殺剽，而衎入于衛。甯喜，殖子也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_37_130","chapterId":"ch_work_han_thu_37","textTraditional":"二十四年「七月甲子朔，日有食之，既」。劉歆以為五月魯、趙分。","sentenceOrder":130},
  {"id":"s_work_han_thu_37_131","chapterId":"ch_work_han_thu_37","textTraditional":"「八月癸巳朔，日有食之」。董仲舒以為比食又既，〔一〕象陽將絕，〔二〕夷狄主上國之象也。後六君弒，〔三〕楚子果從諸侯伐鄭，〔四〕滅舒鳩，〔五〕魯往朝之，〔六〕卒主中國，〔七〕伐吳討慶封。〔八〕劉歆以為六月晉、趙分。","sentenceOrder":131},
  {"id":"s_work_han_thu_37_132","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「比，頻也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_37_133","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　孟康曰：「陽，君也。」","sentenceOrder":133},
  {"id":"s_work_han_thu_37_134","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「謂二十五年齊崔杼殺其君光，二十六年衛甯喜弒其君剽，二十九年閽殺吳子餘祭，三十年蔡太子班弒其君固，三十一年莒人弒其君密州，昭元年楚令尹子圍入問王疾，縊而殺之。」","sentenceOrder":134},
  {"id":"s_work_han_thu_37_135","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「二十四年冬，楚子、蔡侯、陳侯、許男伐鄭。」","sentenceOrder":135},
  {"id":"s_work_han_thu_37_136","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「二十五年，楚屈建帥師滅舒鳩。舒鳩亦群舒一種。」","sentenceOrder":136},
  {"id":"s_work_han_thu_37_137","chapterId":"ch_work_han_thu_37","textTraditional":"〔六〕　師古曰：「二十八年，公如楚。」","sentenceOrder":137},
  {"id":"s_work_han_thu_37_138","chapterId":"ch_work_han_thu_37","textTraditional":"〔七〕　師古曰：「謂楚靈王以昭四年與諸侯會于申。」","sentenceOrder":138},
  {"id":"s_work_han_thu_37_139","chapterId":"ch_work_han_thu_37","textTraditional":"〔八〕　師古曰：「慶封以二十八年為慶舍之難自齊出奔魯，遂奔吳。至申之會，楚靈王伐吳，執慶封而殺之。」","sentenceOrder":139},
  {"id":"s_work_han_thu_37_140","chapterId":"ch_work_han_thu_37","textTraditional":"二十七年「十二月乙亥朔，日有食之」。董仲舒以為禮義將大滅絕之象也。時吳子好勇，使刑人守門；〔一〕蔡侯通於世子之妻〔二〕；莒不早立嗣。〔三〕後閽戕吳子，〔四〕蔡世子般弒其父，莒人亦弒君而庶子爭。〔五〕劉向以為自二十年至此歲，八年間日食七作，禍亂將重起，〔六〕故天仍見戒也。〔七〕後齊崔杼弒君，〔八〕宋殺世子，〔九〕北燕伯出奔，〔一０〕鄭大夫自外入而篡位，〔一一〕指略如董仲舒。劉歆以為九月周、楚分。","sentenceOrder":140},
  {"id":"s_work_han_thu_37_141","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「吳子即餘祭也。刑人，閽者。」","sentenceOrder":141},
  {"id":"s_work_han_thu_37_142","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「即蔡侯固，為太子所殺者也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_37_143","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「即密州也，生去疾及展輿，既立展輿又廢之。」","sentenceOrder":143},
  {"id":"s_work_han_thu_37_144","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「戕，傷也。它國臣來弒君曰戕。音牆。」","sentenceOrder":144},
  {"id":"s_work_han_thu_37_145","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「展輿因國人攻其父而殺之。展輿即位，去疾奔齊。明年去疾入而展輿出奔吳。並非嫡嗣，故云庶子爭。」","sentenceOrder":145},
  {"id":"s_work_han_thu_37_146","chapterId":"ch_work_han_thu_37","textTraditional":"〔六〕　師古曰：「重音直用反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_37_147","chapterId":"ch_work_han_thu_37","textTraditional":"〔七〕　師古曰：「仍，頻也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_37_148","chapterId":"ch_work_han_thu_37","textTraditional":"〔八〕　師古曰：「已解於上。」","sentenceOrder":148},
  {"id":"s_work_han_thu_37_149","chapterId":"ch_work_han_thu_37","textTraditional":"〔九〕　師古曰：「宋平公太子痤也。事在二十六年。」","sentenceOrder":149},
  {"id":"s_work_han_thu_37_150","chapterId":"ch_work_han_thu_37","textTraditional":"〔一０〕孟康曰：「有南燕，故言北燕，南燕姞姓，北燕姬姓也。」師古曰：「昭三年『北燕伯款出奔齊』。」","sentenceOrder":150},
  {"id":"s_work_han_thu_37_151","chapterId":"ch_work_han_thu_37","textTraditional":"〔一一〕師古曰：「謂伯有也。已解於上。」","sentenceOrder":151},
  {"id":"s_work_han_thu_37_152","chapterId":"ch_work_han_thu_37","textTraditional":"昭公七年「四月甲辰朔，日有食之」。董仲舒、劉向以為先是楚靈王弒君而立，會諸侯，〔一〕執徐子，滅賴，〔二〕後陳公子招殺世子，〔三〕楚因而滅之，〔四〕又滅蔡，〔五〕後靈王亦弒死〔六〕。劉歆以為二月魯、衛分。傳曰晉侯問於士文伯曰：「誰將當日食？」〔七〕對曰：「魯、衛惡之，衛大魯小。」公曰：「何故？」對曰：「去衛地，如魯地，於是有災，其衛君乎？魯將上卿。」是歲，八月衛襄公卒，十一月魯季孫宿卒。晉侯謂士文伯曰：「吾所問日食從矣，可常乎？」〔八〕對曰：「不可。六物不同，民心不壹，事序不類，官職不則，同始異終，胡可常也？詩曰：『或宴宴居息，或盡悴事國。』〔九〕其異終也如是。」公曰：「何謂六物？」對曰：「歲、時、日、月、星、辰是謂。」公曰：「何謂辰？」對曰：「日月之會是謂。」公曰：「詩所謂『此日而食，于何不臧』，何也？〔一０〕」對曰：「不善政之謂也。國無政，不用善，則自取適于日月之災。〔一一〕故政不可不慎也，務三而已：一曰擇人，二曰因民，三曰從時。」此推日食之占循變復之要也。易曰：「縣象著明，莫大於日月。」〔一二〕是故聖人重之，載于三經。〔一三〕於易在豐之震曰：「豐其沛，日中見昧，折其右肱，亡咎。」〔一四〕於詩十月之交，則著卿士、司徒，下至趣馬、師氏，咸非其材。〔一五〕同於右肱之所折，協於三務之所擇，明小人乘君子，陰侵陽之原也。","sentenceOrder":152},
  {"id":"s_work_han_thu_37_153","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「已解於上。」","sentenceOrder":153},
  {"id":"s_work_han_thu_37_154","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「申之會，楚人執徐子，遂滅賴。」","sentenceOrder":154},
  {"id":"s_work_han_thu_37_155","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「招，成公子，哀公弟也。昭八年，經書『陳侯之弟招殺陳太子偃師』。偃師即哀公之子也。招音韶。」","sentenceOrder":155},
  {"id":"s_work_han_thu_37_156","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「偃師之死，哀公縊。其九月，楚公子棄疾奉偃師之子孫吳圍陳，遂滅之。」","sentenceOrder":156},
  {"id":"s_work_han_thu_37_157","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「十一年，楚師滅蔡也。執太子有以歸，用之。」","sentenceOrder":157},
  {"id":"s_work_han_thu_37_158","chapterId":"ch_work_han_thu_37","textTraditional":"〔六〕　師古曰：「十三年，楚公子比弒其君虔于乾谿是也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_37_159","chapterId":"ch_work_han_thu_37","textTraditional":"〔七〕　師古曰：「士文伯，晉大夫伯瑕。」","sentenceOrder":159},
  {"id":"s_work_han_thu_37_160","chapterId":"ch_work_han_thu_37","textTraditional":"〔八〕　師古曰：「從，謂如士文伯之言也。可常，謂常可以此占之（下）〔不〕。」","sentenceOrder":160},
  {"id":"s_work_han_thu_37_161","chapterId":"ch_work_han_thu_37","textTraditional":"〔九〕　如淳曰：「顇，古悴字也。」師古曰：「小雅北山之詩也。宴宴，安息之貌也。盡悴，言盡力而悴病也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_37_162","chapterId":"ch_work_han_thu_37","textTraditional":"〔一０〕師古曰：「小雅十月之交之詩也。臧，善也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_37_163","chapterId":"ch_work_han_thu_37","textTraditional":"〔一一〕師古曰：「適讀曰謫。」","sentenceOrder":163},
  {"id":"s_work_han_thu_37_164","chapterId":"ch_work_han_thu_37","textTraditional":"〔一二〕師古曰：「上繫之辭也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_37_165","chapterId":"ch_work_han_thu_37","textTraditional":"〔一三〕師古曰：「謂易、詩、春秋。」","sentenceOrder":165},
  {"id":"s_work_han_thu_37_166","chapterId":"ch_work_han_thu_37","textTraditional":"〔一四〕服虔曰：「日中而昏也。」師古曰：「此豐卦九三爻辭也，言遇此災，則當退去右肱之臣，乃免咎。」","sentenceOrder":166},
  {"id":"s_work_han_thu_37_167","chapterId":"ch_work_han_thu_37","textTraditional":"〔一五〕師古曰：「十月之交詩曰：『皇父卿士，番維司徒。橛維趣馬，楀維師氏，豔妻煽方處。』司徒，地官卿也，掌邦教。趣馬，中士也，掌王馬之政。師氏，中大夫也，掌司朝得失之事。番、橛、楀，皆氏也。美色曰豔。豔妻，褒姒也。豔或作閻，閻亦嬪妾之姓也。煽，熾也。詩人刺王淫於色，故皇父之徒皆用后寵而處職位，不以德選也。趣音千后反。橛音居衛反。楀音居禹反。番音扶元反。」","sentenceOrder":167},
  {"id":"s_work_han_thu_37_168","chapterId":"ch_work_han_thu_37","textTraditional":"十五年「六月丁巳朔，日有食之」。劉歆以為三月魯、衛分。","sentenceOrder":168},
  {"id":"s_work_han_thu_37_169","chapterId":"ch_work_han_thu_37","textTraditional":"十七年「六月甲戌朔，日有食之」。董仲舒以為時宿在畢，晉國象也。晉厲公誅四大夫，失眾心，以弒死。〔一〕後莫敢復責大夫，六卿遂相與比周，專晉國，君還事之。〔二〕日比再食，其事在春秋後，故不載於經。劉歆以為魯、趙分。左氏傳平子曰：〔三〕「唯正月朔，慝未作，日有食之，於是乎天子不舉，伐鼓於社，諸侯用幣於社，伐鼓於朝，禮也。其餘則否。」太史曰：「在此月也，日過分而未至，三辰有災，百官降物，君不舉，避移時，樂奏鼓，祝用幣，史用辭，嗇夫馳，庶人走，此月朔之謂也。當夏四月，是謂孟夏。」說曰：正月謂周六月，夏四月，正陽純乾之月也。慝謂陰爻也，冬至陽爻起初，故曰復。至建巳之月為純乾，亡陰爻，而陰侵陽，為災重，故伐鼓用幣，責陰之禮。降物，素服也。不舉，去樂也。避移時，避正堂，須時移災復也。嗇夫，掌幣吏。庶人，其徒役也。劉歆以為六月二日魯、趙分。","sentenceOrder":169},
  {"id":"s_work_han_thu_37_170","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「四大夫，謂三郤及胥童也。胥童非厲公所誅，以導亂而死，故總書四大夫。厲公竟為欒書、中行偃所殺。」","sentenceOrder":170},
  {"id":"s_work_han_thu_37_171","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「六卿謂范氏、中行氏、智氏、韓、魏、趙也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_37_172","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「季平子。」","sentenceOrder":172},
  {"id":"s_work_han_thu_37_173","chapterId":"ch_work_han_thu_37","textTraditional":"二十一年「七月壬午朔，日有食之」。董仲舒以為周景王老，劉子、單子專權，〔一〕蔡侯朱驕，君臣不說之象也。〔二〕後蔡侯朱果出奔，〔三〕劉子、單子立王猛。劉歆以為五月二日魯、趙分。","sentenceOrder":173},
  {"id":"s_work_han_thu_37_174","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「已解於上。」","sentenceOrder":174},
  {"id":"s_work_han_thu_37_175","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「蔡侯朱，蔡平公之子。說讀曰悅。」","sentenceOrder":175},
  {"id":"s_work_han_thu_37_176","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「昭二十一年出奔楚。」","sentenceOrder":176},
  {"id":"s_work_han_thu_37_177","chapterId":"ch_work_han_thu_37","textTraditional":"二十二年「十二月癸酉朔，日有食之」。董仲舒以為宿在心，天子之象也。後尹氏立王子朝，天王居于狄泉。〔一〕劉歆以為十月楚、鄭分。","sentenceOrder":177},
  {"id":"s_work_han_thu_37_178","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「天王，敬王也，避子朝之難，故居狄泉。」","sentenceOrder":178},
  {"id":"s_work_han_thu_37_179","chapterId":"ch_work_han_thu_37","textTraditional":"二十四年「五月乙未朔，日有食之」。董仲舒以為宿在胃，魯象也。後昭公為季氏所逐。劉向以為自十五年至此歲，十年間天戒七見，人君猶不寤。後楚殺戎蠻子，〔一〕晉滅陸渾戎，〔二〕盜殺衛侯兄，〔三〕蔡、莒之君出奔，〔四〕吳滅巢，〔五〕公子光殺王僚，〔六〕宋三臣以邑叛其君。〔七〕它如仲舒。劉歆以為二日魯、趙分。是月斗建辰。左氏傳梓慎曰：「將大水。」〔八〕昭子曰：「旱也。〔九〕日過分而陽猶不克，克必甚，能無旱乎！〔一０〕陽不克，莫將積聚也。」〔一一〕是歲秋，大雩，旱也。二至二分，日有食之，不為災。日月之行也，春秋分日夜等，故同道；冬夏至長短極，故相過。相過同道而食輕，不為大災，水旱而已。","sentenceOrder":179},
  {"id":"s_work_han_thu_37_180","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「昭十六年楚子誘戎蠻子殺之。戎蠻國在河南新城縣。」","sentenceOrder":180},
  {"id":"s_work_han_thu_37_181","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「十七年晉荀吳帥師滅陸渾之戎。其地今陸渾縣是也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_37_182","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「衛靈公兄也，名縶，二十年為齊豹所殺。以豹不義，故貶稱盜，所謂求名而不得。」","sentenceOrder":182},
  {"id":"s_work_han_thu_37_183","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「蔡君，即朱也。莒君，莒子庚與也，二十三年出奔魯。」","sentenceOrder":183},
  {"id":"s_work_han_thu_37_184","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「二十四年吳滅巢。巢，吳、楚間小國，即居巢城是也。」","sentenceOrder":184},
  {"id":"s_work_han_thu_37_185","chapterId":"ch_work_han_thu_37","textTraditional":"〔六〕　師古曰：「事在二十七年。」","sentenceOrder":185},
  {"id":"s_work_han_thu_37_186","chapterId":"ch_work_han_thu_37","textTraditional":"〔七〕　師古曰：「二十一年，宋華亥、向寧、華定入于宋南里以叛是也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_37_187","chapterId":"ch_work_han_thu_37","textTraditional":"〔八〕　師古曰：「梓慎，魯大夫。」","sentenceOrder":187},
  {"id":"s_work_han_thu_37_188","chapterId":"ch_work_han_thu_37","textTraditional":"〔九〕　師古曰：「叔孫昭子。」","sentenceOrder":188},
  {"id":"s_work_han_thu_37_189","chapterId":"ch_work_han_thu_37","textTraditional":"〔一０〕孟康曰：「謂春分後陰多陽少，為不克。陽勝則盛，故言甚。」","sentenceOrder":189},
  {"id":"s_work_han_thu_37_190","chapterId":"ch_work_han_thu_37","textTraditional":"〔一一〕蘇林曰：「莫，莫爾不勝，為積聚也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_37_191","chapterId":"ch_work_han_thu_37","textTraditional":"三十一年「十二月辛亥朔，日有食之」。董仲舒以為宿在心，天子象也。時京師微弱，後諸侯果相率而城周，〔一〕宋中幾亡尊天子之心，而不衰城。〔二〕劉向以為時吳滅徐，〔三〕而蔡滅沈，〔四〕楚圍蔡，吳敗楚入郢，昭王走出。〔五〕劉歆以為二日宋、燕分。","sentenceOrder":191},
  {"id":"s_work_han_thu_37_192","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「定元年，晉魏舒合諸侯之大夫于狄泉以城周是也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_37_193","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「中幾，宋大夫。衰城，謂以差次受功賦也。衰音初為反。一曰，衰讀曰蓑。蓑城，謂以草覆城也。蓑音先和反。中讀曰仲。」","sentenceOrder":193},
  {"id":"s_work_han_thu_37_194","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「事在昭三十年。」","sentenceOrder":194},
  {"id":"s_work_han_thu_37_195","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「定四年蔡公孫姓帥師滅沈。」","sentenceOrder":195},
  {"id":"s_work_han_thu_37_196","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「事並在定四年。」","sentenceOrder":196},
  {"id":"s_work_han_thu_37_197","chapterId":"ch_work_han_thu_37","textTraditional":"定公五年「三月辛亥朔，日有食之」。董仲舒、劉向以為後鄭滅許，〔一〕魯陽虎作亂，竊寶玉大弓，季桓子退仲尼，宋三臣以邑叛。〔二〕劉歆以為正月二日燕、趙分。","sentenceOrder":197},
  {"id":"s_work_han_thu_37_198","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「六年鄭游速帥師滅許，以許男斯歸。」","sentenceOrder":198},
  {"id":"s_work_han_thu_37_199","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「已解於上。」","sentenceOrder":199},
  {"id":"s_work_han_thu_37_200","chapterId":"ch_work_han_thu_37","textTraditional":"十二年「十一月丙寅朔，日有食之」。董仲舒、劉向以為後晉三大夫以邑叛，薛弒其君，〔一〕楚滅頓、胡，〔二〕越敗吳，〔三〕衛逐世子。〔四〕劉歆以為十二月二日楚、鄭分。","sentenceOrder":200},
  {"id":"s_work_han_thu_37_201","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「十三年，晉趙鞅入于晉陽以叛，荀寅、士吉射入朝歌以叛，薛殺其君比。」","sentenceOrder":201},
  {"id":"s_work_han_thu_37_202","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「十四年，楚公子結帥師滅頓，以頓子牂歸。十五年，楚人滅胡，以胡子豹歸。」","sentenceOrder":202},
  {"id":"s_work_han_thu_37_203","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「十四年五月於越敗吳于檇李是也。檇音醉。」","sentenceOrder":203},
  {"id":"s_work_han_thu_37_204","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「十四年，衛太子蒯瞶出奔宋。」","sentenceOrder":204},
  {"id":"s_work_han_thu_37_205","chapterId":"ch_work_han_thu_37","textTraditional":"十五年「八月庚辰朔，日有食之」。董仲舒以為宿在柳，周室大壞，夷狄主諸夏之象也。明年，中國諸侯果累累從楚而圍蔡，〔一〕蔡恐，遷于州來。〔二〕晉人執戎蠻子歸于楚，〔三〕京師楚也〔四〕。劉向以為盜殺蔡侯，〔五〕齊陳乞弒其君而立陽生，〔六〕孔子終不用。劉歆以為六月晉、趙分。","sentenceOrder":205},
  {"id":"s_work_han_thu_37_206","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「哀元年楚子、陳侯、隨侯、許男圍蔡是也。累讀曰纍。纍，不絕之貌。」","sentenceOrder":206},
  {"id":"s_work_han_thu_37_207","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「哀二年十一月，蔡遷于州來。州來，楚邑，今下蔡縣是。」","sentenceOrder":207},
  {"id":"s_work_han_thu_37_208","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「哀公四年，晉人執戎蠻子赤歸于楚。」","sentenceOrder":208},
  {"id":"s_work_han_thu_37_209","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「言以楚為京師。」","sentenceOrder":209},
  {"id":"s_work_han_thu_37_210","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「哀四年，蔡公孫翩殺蔡侯申。翩非大夫，故賤之而書盜。」","sentenceOrder":210},
  {"id":"s_work_han_thu_37_211","chapterId":"ch_work_han_thu_37","textTraditional":"〔六〕　師古曰：「哀六年齊陳乞弒其君荼。荼即景公之子也。陽生，荼之兄，即悼公也。荼音塗。」","sentenceOrder":211},
  {"id":"s_work_han_thu_37_212","chapterId":"ch_work_han_thu_37","textTraditional":"哀公十四年「五月庚申朔，日有食之」。在獲麟後。劉歆以為三月二日齊、衛分。","sentenceOrder":212},
  {"id":"s_work_han_thu_37_213","chapterId":"ch_work_han_thu_37","textTraditional":"凡春秋十二公，二百四十二年，日食三十六。穀梁以為朔二十六，晦七，夜二，二日一。公羊以為朔二十七，二日七，晦二。左氏以為朔十六，二日十八，晦一，不書日者二。","sentenceOrder":213},
  {"id":"s_work_han_thu_37_214","chapterId":"ch_work_han_thu_37","textTraditional":"高帝三年十月甲戌晦，日有食之，在斗二十度，燕地也。後二年，燕王臧荼反，誅，立盧綰為燕王，後又反，敗。","sentenceOrder":214},
  {"id":"s_work_han_thu_37_215","chapterId":"ch_work_han_thu_37","textTraditional":"十一月癸卯晦，日有食之，在虛三度，齊地也。後二年，齊王韓信徙為楚王，明年廢為列侯，後又反，誅。","sentenceOrder":215},
  {"id":"s_work_han_thu_37_216","chapterId":"ch_work_han_thu_37","textTraditional":"九年六月乙未晦，日有食之，既，在張十三度。","sentenceOrder":216},
  {"id":"s_work_han_thu_37_217","chapterId":"ch_work_han_thu_37","textTraditional":"惠帝七年正月辛丑朔，日有食之，在危十三度。谷永以為歲首正月朔日，是為三朝，尊者惡之。","sentenceOrder":217},
  {"id":"s_work_han_thu_37_218","chapterId":"ch_work_han_thu_37","textTraditional":"五月丁卯，先晦一日，日有食之，幾盡，〔一〕在七星初。劉向以為五月微陰始起而犯至陽，其占重。至其八月，宮車晏駕，有呂氏詐置嗣君之害。京房易傳曰：「凡日食不以晦朔者，名曰薄。人君誅將不以理，或賊臣將暴起，日月雖不同宿，陰氣盛，薄日光也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_37_219","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「幾音鉅依反。後皆類此。」","sentenceOrder":219},
  {"id":"s_work_han_thu_37_220","chapterId":"ch_work_han_thu_37","textTraditional":"高后二年六月丙戌晦，日有食之。","sentenceOrder":220},
  {"id":"s_work_han_thu_37_221","chapterId":"ch_work_han_thu_37","textTraditional":"七年正月己丑晦，日有食之，既，在營室九度，為宮室中。時高后惡之，曰：「此為我也！」明年應。〔一〕","sentenceOrder":221},
  {"id":"s_work_han_thu_37_222","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「謂高后崩也。」","sentenceOrder":222},
  {"id":"s_work_han_thu_37_223","chapterId":"ch_work_han_thu_37","textTraditional":"文帝二年十一月癸卯晦，日有食之，在婺女一度。","sentenceOrder":223},
  {"id":"s_work_han_thu_37_224","chapterId":"ch_work_han_thu_37","textTraditional":"三年十月丁酉晦，日有食之，在斗二十（三）〔二〕度。","sentenceOrder":224},
  {"id":"s_work_han_thu_37_225","chapterId":"ch_work_han_thu_37","textTraditional":"十一月丁卯晦，日有食之，在虛八度。","sentenceOrder":225},
  {"id":"s_work_han_thu_37_226","chapterId":"ch_work_han_thu_37","textTraditional":"後四年四月丙辰晦，日有食之，在東井十三度。","sentenceOrder":226},
  {"id":"s_work_han_thu_37_227","chapterId":"ch_work_han_thu_37","textTraditional":"七年正月辛未朔，日有食之。","sentenceOrder":227},
  {"id":"s_work_han_thu_37_228","chapterId":"ch_work_han_thu_37","textTraditional":"景帝三年二月壬午晦，日有食之，在胃二度。","sentenceOrder":228},
  {"id":"s_work_han_thu_37_229","chapterId":"ch_work_han_thu_37","textTraditional":"七年十一月庚寅晦，日有食之，在虛九度。","sentenceOrder":229},
  {"id":"s_work_han_thu_37_230","chapterId":"ch_work_han_thu_37","textTraditional":"中元年十二月甲寅晦，日有食之。","sentenceOrder":230},
  {"id":"s_work_han_thu_37_231","chapterId":"ch_work_han_thu_37","textTraditional":"中二年九月甲戌晦，日有食之。","sentenceOrder":231},
  {"id":"s_work_han_thu_37_232","chapterId":"ch_work_han_thu_37","textTraditional":"三年九月戊戌晦，日有食之，幾盡，在尾九度。","sentenceOrder":232},
  {"id":"s_work_han_thu_37_233","chapterId":"ch_work_han_thu_37","textTraditional":"六年七月辛亥晦，日有食之，在軫七度。","sentenceOrder":233},
  {"id":"s_work_han_thu_37_234","chapterId":"ch_work_han_thu_37","textTraditional":"後元年七月乙巳，先晦一日，日有食之，在翼十七度。","sentenceOrder":234},
  {"id":"s_work_han_thu_37_235","chapterId":"ch_work_han_thu_37","textTraditional":"武帝建元二年二月丙戌朔，日有食之，在奎十四度。劉向以為奎為卑賤婦人，後有衛皇后自至微興，卒有不終之害。〔一〕","sentenceOrder":235},
  {"id":"s_work_han_thu_37_236","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「皇后自殺，不終其位也。」","sentenceOrder":236},
  {"id":"s_work_han_thu_37_237","chapterId":"ch_work_han_thu_37","textTraditional":"三年九月丙子晦，日有食之，在尾二度。","sentenceOrder":237},
  {"id":"s_work_han_thu_37_238","chapterId":"ch_work_han_thu_37","textTraditional":"五年正月己巳朔，日有食之。","sentenceOrder":238},
  {"id":"s_work_han_thu_37_239","chapterId":"ch_work_han_thu_37","textTraditional":"元光元年二月丙辰晦，日有食之。","sentenceOrder":239},
  {"id":"s_work_han_thu_37_240","chapterId":"ch_work_han_thu_37","textTraditional":"七月癸未，先晦一日，日有食之，在翼八度。劉向以為前年高園便殿災，與春秋御廩災後日食於翼、軫同。其占，內有女變，外為諸侯。其後陳皇后廢，江都、淮南、衡山王謀反，誅。日中時食從東北，過半，晡時復。","sentenceOrder":240},
  {"id":"s_work_han_thu_37_241","chapterId":"ch_work_han_thu_37","textTraditional":"元朔二年二月乙巳晦，日有食之，在胃三度。","sentenceOrder":241},
  {"id":"s_work_han_thu_37_242","chapterId":"ch_work_han_thu_37","textTraditional":"六年十一月癸丑晦，日有食之。","sentenceOrder":242},
  {"id":"s_work_han_thu_37_243","chapterId":"ch_work_han_thu_37","textTraditional":"元狩元年五月乙巳晦，日有食之，在柳六度。京房易傳推以為是時日食從旁右，法曰君失臣。明年丞相公孫弘薨。日食從旁左者，亦君失臣；從上者，臣失君；從下者，君失民。","sentenceOrder":243},
  {"id":"s_work_han_thu_37_244","chapterId":"ch_work_han_thu_37","textTraditional":"元鼎五年四月丁丑晦，日有食之，在東井二十三度。","sentenceOrder":244},
  {"id":"s_work_han_thu_37_245","chapterId":"ch_work_han_thu_37","textTraditional":"元封四年六月己酉朔，日有食之。","sentenceOrder":245},
  {"id":"s_work_han_thu_37_246","chapterId":"ch_work_han_thu_37","textTraditional":"太始元年正月乙巳晦，日有食之。","sentenceOrder":246},
  {"id":"s_work_han_thu_37_247","chapterId":"ch_work_han_thu_37","textTraditional":"四年十月甲寅晦，日有食之，在斗十九度。","sentenceOrder":247},
  {"id":"s_work_han_thu_37_248","chapterId":"ch_work_han_thu_37","textTraditional":"征和四年八月辛酉晦，日有食之，不盡如鉤，在亢二度。晡時食從西北，日下晡時復。","sentenceOrder":248},
  {"id":"s_work_han_thu_37_249","chapterId":"ch_work_han_thu_37","textTraditional":"昭帝始元三年十一月壬辰朔，日有食之，在斗九度，燕地也。後四年，燕剌王謀反，誅。","sentenceOrder":249},
  {"id":"s_work_han_thu_37_250","chapterId":"ch_work_han_thu_37","textTraditional":"元鳳元年七月己亥晦，日有食之，幾盡，在張十二度。劉向以為己亥而既，其占重。〔一〕後六年，宮車晏駕，卒以亡嗣。","sentenceOrder":250},
  {"id":"s_work_han_thu_37_251","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　孟康曰：「己，土；亥，水也。純陰，故食為最重也。日食盡為既。」","sentenceOrder":251},
  {"id":"s_work_han_thu_37_252","chapterId":"ch_work_han_thu_37","textTraditional":"宣帝地節元年十二月癸亥晦，日有食之，在營室十五度。","sentenceOrder":252},
  {"id":"s_work_han_thu_37_253","chapterId":"ch_work_han_thu_37","textTraditional":"五鳳元年十二月乙酉朔，日有食之，在婺女十度。","sentenceOrder":253},
  {"id":"s_work_han_thu_37_254","chapterId":"ch_work_han_thu_37","textTraditional":"四年四月辛丑朔，日有食之，在畢十九度。是為正月朔，慝未作，左氏以為重異。","sentenceOrder":254},
  {"id":"s_work_han_thu_37_255","chapterId":"ch_work_han_thu_37","textTraditional":"元帝永光二年三月壬戌朔，日有食之，在婁八度。","sentenceOrder":255},
  {"id":"s_work_han_thu_37_256","chapterId":"ch_work_han_thu_37","textTraditional":"四年六月戊寅晦，日有食之，在張七度。","sentenceOrder":256},
  {"id":"s_work_han_thu_37_257","chapterId":"ch_work_han_thu_37","textTraditional":"建昭五年六月壬申晦，日有食之，不盡如鉤，因入。","sentenceOrder":257},
  {"id":"s_work_han_thu_37_258","chapterId":"ch_work_han_thu_37","textTraditional":"成帝建始三年十二月戊申朔，日有食之，其夜未央殿中地震。谷永對曰：「日食婺女九度，占在皇后。地震蕭牆之內，咎在貴妾〔一〕。二者俱發，明同事異人，共掩制陽，將害繼嗣也。亶日食，則妾不見；〔二〕亶地震，則后不見。異日而發，則似殊事；亡故動變，則恐不知。是月后妾當有失節之郵，〔三〕故天因此兩見其變。若曰，違失婦道，隔遠眾妾，〔四〕妨絕繼嗣者，此二人也。」杜欽對亦曰：「日以戊申食，時加未。戊未，土也，中宮之部。其夜殿中地震，此必適妾將有爭寵相害而為患者。〔五〕人事失於下，變象見於上。能應之（司）〔以〕德，則咎異消；忽而不戒，則禍敗至。〔六〕應之，非誠不立，非信不行。」","sentenceOrder":258},
  {"id":"s_work_han_thu_37_259","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「蕭牆，謂門屏也。蕭，肅也，人臣至此，加肅敬也。」","sentenceOrder":259},
  {"id":"s_work_han_thu_37_260","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「亶讀曰但。下例並同。」","sentenceOrder":260},
  {"id":"s_work_han_thu_37_261","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「郵與尤同。尤，過也。」","sentenceOrder":261},
  {"id":"s_work_han_thu_37_262","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「遠音于萬反。」","sentenceOrder":262},
  {"id":"s_work_han_thu_37_263","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「適讀曰嫡。」","sentenceOrder":263},
  {"id":"s_work_han_thu_37_264","chapterId":"ch_work_han_thu_37","textTraditional":"〔六〕　師古曰：「忽，怠忘。」","sentenceOrder":264},
  {"id":"s_work_han_thu_37_265","chapterId":"ch_work_han_thu_37","textTraditional":"河平元年四月己亥晦，日有食之，不盡如鉤，在東井六度。劉向對曰：「四月交於五月，月同孝惠，日同孝昭。東井，京師地，且既，其占恐害繼嗣。」日蚤食時，從西南起。","sentenceOrder":265},
  {"id":"s_work_han_thu_37_266","chapterId":"ch_work_han_thu_37","textTraditional":"三年八月乙卯晦，日有食之，在房。","sentenceOrder":266},
  {"id":"s_work_han_thu_37_267","chapterId":"ch_work_han_thu_37","textTraditional":"四年三月癸丑朔，日有食之，在昴。","sentenceOrder":267},
  {"id":"s_work_han_thu_37_268","chapterId":"ch_work_han_thu_37","textTraditional":"陽朔元年二月丁未晦，日有食之，在胃。","sentenceOrder":268},
  {"id":"s_work_han_thu_37_269","chapterId":"ch_work_han_thu_37","textTraditional":"永始元年九月丁巳晦，日有食之。谷永以京房易占對曰：「元年九月日蝕，酒亡節之所致也。獨使京師知之，四國不見者，若曰，湛湎于酒，君臣不別，禍在內也。」〔一〕","sentenceOrder":269},
  {"id":"s_work_han_thu_37_270","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「湛讀曰沈，又讀曰耽也。」","sentenceOrder":270},
  {"id":"s_work_han_thu_37_271","chapterId":"ch_work_han_thu_37","textTraditional":"永始二年二月乙酉晦，日有食之。谷永以京房易占對曰：「今年二月日食，賦斂不得度，民愁怨之所致也。所以使四方皆見，京師陰蔽者，若曰，人君好治宮室，大營墳墓，賦斂茲重，而百姓屈竭〔一〕，禍在外也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_37_272","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「茲，益也。屈，盡也，音其勿反。」","sentenceOrder":272},
  {"id":"s_work_han_thu_37_273","chapterId":"ch_work_han_thu_37","textTraditional":"三年正月己卯晦，日有食之。","sentenceOrder":273},
  {"id":"s_work_han_thu_37_274","chapterId":"ch_work_han_thu_37","textTraditional":"四年七月辛未晦，日有食之。","sentenceOrder":274},
  {"id":"s_work_han_thu_37_275","chapterId":"ch_work_han_thu_37","textTraditional":"元延元年正月己亥朔，日有食之。","sentenceOrder":275},
  {"id":"s_work_han_thu_37_276","chapterId":"ch_work_han_thu_37","textTraditional":"哀帝元壽元年正月辛丑朔，日有食之，不盡如鉤，在營室十度，與惠帝七年同月日。","sentenceOrder":276},
  {"id":"s_work_han_thu_37_277","chapterId":"ch_work_han_thu_37","textTraditional":"二年三月壬辰晦，日有食之。","sentenceOrder":277},
  {"id":"s_work_han_thu_37_278","chapterId":"ch_work_han_thu_37","textTraditional":"平帝元始元年五月丁巳朔，日有食之，在東井。","sentenceOrder":278},
  {"id":"s_work_han_thu_37_279","chapterId":"ch_work_han_thu_37","textTraditional":"二年九月戊申晦，日有食之，既。","sentenceOrder":279},
  {"id":"s_work_han_thu_37_280","chapterId":"ch_work_han_thu_37","textTraditional":"凡漢著紀十二世，二百一十二年，日食五十三，朔十四，晦三十六，先晦一日三。","sentenceOrder":280},
  {"id":"s_work_han_thu_37_281","chapterId":"ch_work_han_thu_37","textTraditional":"成帝建始元年八月戊午，晨漏未盡三刻，有兩月重見。京房易傳曰：「『婦貞厲，月幾望，君子征，凶。』〔一〕言君弱而婦彊，為陰所乘，則月並出。晦而月見西方謂之朓，朔而月見東方謂之仄慝，〔二〕仄慝則侯王其肅，朓則侯王其舒。」劉向以為朓者疾也，君舒緩則臣驕慢，故日行遲而月行疾也。仄慝者不進之意，君肅急則臣恐懼，故日行疾而月行遲，不敢迫近君也。不舒不急，以正失之者，食朔日。劉歆以為舒者侯王展意顓事，臣下促急，故月行疾也。肅者王侯縮朒不任事，〔三〕臣下弛縱，故月行遲也。〔四〕當春秋時，侯王率多縮朒不任事，故食二日仄慝者十八，食晦日朓者一，此其效也。考之漢家，食晦朓者三十六，終亡二日仄慝者，歆說信矣。此皆謂日月亂行者也。","sentenceOrder":281},
  {"id":"s_work_han_thu_37_282","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「小畜上九爻辭也。幾音鉅依反。」","sentenceOrder":282},
  {"id":"s_work_han_thu_37_283","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　孟康曰：「朓者，月行疾在日前，故早見。仄慝者，行遲在日後，當沒而更見。」師古曰：「朓音吐了反。」","sentenceOrder":283},
  {"id":"s_work_han_thu_37_284","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　服虔曰：「朒音忸怩之忸。」鄭氏曰：「不任事之貌也。」師古曰：「朒音女六反。」","sentenceOrder":284},
  {"id":"s_work_han_thu_37_285","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「弛，放也，音式爾反。」","sentenceOrder":285},
  {"id":"s_work_han_thu_37_286","chapterId":"ch_work_han_thu_37","textTraditional":"元帝永光元年四月，日色青白，亡景，〔一〕正中時有景亡光。〔二〕是夏寒，至九月，日乃有光。京房易傳曰：「美不上人，茲謂上弱，厥異日白，七日不溫。順亡所制茲謂弱，〔三〕日白六十日，物亡霜而死。天子親伐，茲謂不知，日白，體動而寒。弱而有任，茲謂不亡，日白不溫，明不動。辟（（暂缺F604））〔諐〕公行，茲謂不伸，〔四〕厥異日黑，大風起，天無雲，日光晻。〔五〕不難上政，茲謂見過，日黑居仄，大如彈丸。」","sentenceOrder":286},
  {"id":"s_work_han_thu_37_287","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　韋昭曰：「日下無景也。無景，謂唯質見耳。」","sentenceOrder":287},
  {"id":"s_work_han_thu_37_288","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　韋昭曰：「無光曜也。」","sentenceOrder":288},
  {"id":"s_work_han_thu_37_289","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　孟康曰：「君順從於臣下，無所能制。」","sentenceOrder":289},
  {"id":"s_work_han_thu_37_290","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　孟康曰：「辟，君也。有過而公行之。」","sentenceOrder":290},
  {"id":"s_work_han_thu_37_291","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「晻與闇同也。」","sentenceOrder":291},
  {"id":"s_work_han_thu_37_292","chapterId":"ch_work_han_thu_37","textTraditional":"成帝河平元年正月壬寅朔，日月俱在營室，時日出赤。二月癸未，日朝赤，且入又赤，夜月赤。甲申，日出赤如血，亡光，漏上四刻半，乃頗有光，燭地赤黃，食後乃復。京房易傳曰：「辟不聞道茲謂亡，厥異日赤。」三月乙未，日出黃，有黑氣大如錢，居日中央。京房易傳曰：「祭天不順茲謂逆，厥異日赤，其中黑。聞善不予，茲謂失知，厥異日黃。」夫大人者，與天地合其德，與日月合其明，故聖王在上，總命群賢，以亮天功，〔一〕則日之光明，五色備具，燭燿亡主；有主則為異，應行而變也。色不虛改，形不虛毀，觀日之五變，足以監矣。故曰「縣象著明，莫大乎日月」，此之謂也。","sentenceOrder":292},
  {"id":"s_work_han_thu_37_293","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「虞書舜典帝曰：『咨，二十有二人，欽哉，惟時亮天功。』謂敕六官、十二牧、四嶽，令各敬其職事，信定其功，順天道也。故志引之。」","sentenceOrder":293},
  {"id":"s_work_han_thu_37_294","chapterId":"ch_work_han_thu_37","textTraditional":"嚴公七年「四月辛卯夜，恆星不見，夜中星隕如雨」。董仲舒、劉向以為常星二十八宿者，人君之象也；眾星，萬民之類也。列宿不見，象諸侯微也；眾星隕墜，民失其所也。夜中者，為中國也。不及地而復，象齊桓起而救存之也。鄉亡桓公，星遂至地，中國其良絕矣。〔一〕劉向以為夜中者，言不得終性命，中道敗也。或曰象其叛也，言當中道叛其上也。天垂象以視下，〔二〕將欲人君防惡遠非，慎卑省微，以自全安也。〔三〕如人君有賢明之材，畏天威命，若高宗謀祖己，〔四〕成王泣金縢，〔五〕改過修正，立信布德，存亡繼絕，修廢舉逸，下學而上達，〔六〕裁什一之稅，復三日之役，〔七〕節用儉服，以惠百姓，則諸侯懷德，士民歸仁，災消而福興矣。遂莫肯改寤，法則古人，而各行其私意，終於君臣乖離，上下交怨。自是之後，齊、宋之君弒，〔八〕譚、遂、邢、衛之國滅，〔九〕宿遷於宋，〔一０〕蔡獲於楚，〔一一〕晉相弒殺，五世乃定，〔一二〕此其效也。左氏傳曰：「恆星不見，夜明也；星隕如雨，與雨偕也。」劉歆以為晝象中國，夜象夷狄。夜明，故常見之星皆不見，象中國微也。「星隕如雨」，如，而也，星隕而且雨，故曰「與雨偕也」，明雨與星隕，兩變相成也。洪範曰：「庶民惟星。」易曰：「雷雨作，解。」〔一三〕是歲歲在玄枵，齊分野也。夜中而星隕，象庶民中離上也。雨以解過施，復從上下，象齊桓行伯，〔一四〕復興周室也。周四月，夏二月也，日在降婁，魯分野也。先是，衛侯朔奔齊，衛公子黔牟立，齊帥諸侯伐之，天子使使救衛。〔一五〕魯公子溺專政，會齊以犯王命，〔一六〕嚴弗能止，卒從而伐衛，逐天王所立。〔一七〕不義至甚，而自以為功。（名）〔民〕去其上，政繇下作，〔一八〕尤著，故星隕於魯，天事常象也。","sentenceOrder":294},
  {"id":"s_work_han_thu_37_295","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「鄉讀曰嚮。中國，中夏之國也。良猶信也。」","sentenceOrder":295},
  {"id":"s_work_han_thu_37_296","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「視讀曰示。」","sentenceOrder":296},
  {"id":"s_work_han_thu_37_297","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「遠，離也。省，視。」","sentenceOrder":297},
  {"id":"s_work_han_thu_37_298","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「謂殷之武丁有雊雉之異，而祖己訓諸王，作高宗肜日高宗之訓。」","sentenceOrder":298},
  {"id":"s_work_han_thu_37_299","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「武王有疾，周公作金縢之書為王請命，王翌日乃瘳。後武王崩，成王即位，管、蔡流言，而周公居東。天大雷電以風，禾盡偃，大木斯拔。王啟金縢，乃得周公代武王之說，王執書以泣，遣使者逆公。王出郊，天乃雨，反風，禾則盡起。」","sentenceOrder":299},
  {"id":"s_work_han_thu_37_300","chapterId":"ch_work_han_thu_37","textTraditional":"〔六〕　師古曰：「下學，謂博謀於群下也。上達，謂通於天道而畏威。」","sentenceOrder":300},
  {"id":"s_work_han_thu_37_301","chapterId":"ch_work_han_thu_37","textTraditional":"〔七〕　師古曰：「古之田租，十稅其一，一歲役兆庶不過三日也。」","sentenceOrder":301},
  {"id":"s_work_han_thu_37_302","chapterId":"ch_work_han_thu_37","textTraditional":"〔八〕　師古曰：「莊八年齊無知弒其君諸兒，十二年宋萬弒其君捷也。」","sentenceOrder":302},
  {"id":"s_work_han_thu_37_303","chapterId":"ch_work_han_thu_37","textTraditional":"〔九〕　師古曰：「十年齊侯滅譚，十三年齊人滅遂，閔二年狄人入衛，僖二十五年衛侯燬滅邢。」","sentenceOrder":303},
  {"id":"s_work_han_thu_37_304","chapterId":"ch_work_han_thu_37","textTraditional":"〔一０〕師古曰：「莊十年宋人遷宿，蓋取其地也。宿國，東平無鹽縣是。」","sentenceOrder":304},
  {"id":"s_work_han_thu_37_305","chapterId":"ch_work_han_thu_37","textTraditional":"〔一一〕師古曰：「莊十年荊敗蔡師于莘，以蔡侯獻舞歸也。」","sentenceOrder":305},
  {"id":"s_work_han_thu_37_306","chapterId":"ch_work_han_thu_37","textTraditional":"〔一二〕師古曰：「謂殺奚齊、卓子及懷公也。自獻公以至文公反國，凡易五君乃定。」","sentenceOrder":306},
  {"id":"s_work_han_thu_37_307","chapterId":"ch_work_han_thu_37","textTraditional":"〔一三〕師古曰：「解卦象辭也。」","sentenceOrder":307},
  {"id":"s_work_han_thu_37_308","chapterId":"ch_work_han_thu_37","textTraditional":"〔一四〕師古曰：「伯讀曰霸。」","sentenceOrder":308},
  {"id":"s_work_han_thu_37_309","chapterId":"ch_work_han_thu_37","textTraditional":"〔一五〕師古曰：「已解於上。」","sentenceOrder":309},
  {"id":"s_work_han_thu_37_310","chapterId":"ch_work_han_thu_37","textTraditional":"〔一六〕師古曰：「溺，魯大夫名也。莊三年，『溺會齊師伐衛』，疾其專命，故貶而去族。天子救衛，而溺伐之，故云犯王命。」","sentenceOrder":310},
  {"id":"s_work_han_thu_37_311","chapterId":"ch_work_han_thu_37","textTraditional":"〔一七〕師古曰：「謂放黔牟也。」","sentenceOrder":311},
  {"id":"s_work_han_thu_37_312","chapterId":"ch_work_han_thu_37","textTraditional":"〔一八〕師古曰：「繇讀與由同。次下亦同。」","sentenceOrder":312},
  {"id":"s_work_han_thu_37_313","chapterId":"ch_work_han_thu_37","textTraditional":"成帝永始二年二月癸未，夜過中，星隕如雨，長一二丈，繹繹未至地滅，〔一〕至雞鳴止。谷永對曰：「日月星辰燭臨下土，其有食隕之異，則遐邇幽隱靡不咸睹。星辰附離于天，猶庶民附離王者也。王者失道，綱紀廢頓，下將叛去，故星叛天而隕，以見其象。春秋記異，星隕最大，自魯嚴以來，至今再見。臣聞三代所以喪亡者，皆繇婦人群小，湛湎於酒。〔二〕書云：『乃用其婦人之言，四方之逋逃多罪，是信是使。』〔三〕詩曰：『赫赫宗周、褒姒滅之。』〔四〕『顛覆厥德，荒沈于酒。』〔五〕及秦所以二世而亡者，養生大奢，奉終大厚。方今國家兼而有之，社稷宗廟之大憂也。」京房易傳曰：「君不任賢，厥妖天雨星。」","sentenceOrder":313},
  {"id":"s_work_han_thu_37_314","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「繹繹，光采貌。」","sentenceOrder":314},
  {"id":"s_work_han_thu_37_315","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「湛讀曰沈，又讀曰耽。其下亦同。」","sentenceOrder":315},
  {"id":"s_work_han_thu_37_316","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「周書泰誓也。言紂惑於妲己，而昵近亡逃罪人，信用之。」","sentenceOrder":316},
  {"id":"s_work_han_thu_37_317","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「小雅正月之詩也。已解於上。滅音許悅反。」","sentenceOrder":317},
  {"id":"s_work_han_thu_37_318","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「大雅抑之詩也。刺王傾敗其德，荒廢政事而耽酒。」","sentenceOrder":318},
  {"id":"s_work_han_thu_37_319","chapterId":"ch_work_han_thu_37","textTraditional":"文公十四年「七月，有星孛入于北斗」。董仲舒以為孛者惡氣之所生也。謂之孛者，言其孛孛有所防蔽，闇亂不明之貌也。北斗，大國象。後齊、宋、魯、莒、晉皆弒君。〔一〕劉向以為君臣亂於朝，政令虧於外，則上濁三光之精，五星贏縮，變色逆行，甚則為孛。北斗，人君象；孛星，亂臣類，篡殺之表也。星傳曰「魁者，貴人之牢」。又曰「孛星見北斗中，大臣諸侯有受誅者」。一曰魁為齊、晉。夫彗星較然在北斗中，天之視人顯矣，〔二〕史之有占明矣，時君終不改寤。是後，宋、魯、莒、晉、鄭、陳六國咸弒其君，〔三〕齊再弒焉。〔四〕中國既亂，夷狄並侵，兵革從橫，楚乘威席勝，深入諸夏，〔五〕六侵伐，〔六〕一滅國，〔七〕觀兵周室。〔八〕晉外滅二國，〔九〕內敗王師，〔一０〕又連三國之兵大敗齊師于鞍，〔一一〕追亡逐北，東臨海水，〔一二〕威陵京師，武折大齊。皆孛星炎之所及，流至二十八年。〔一三〕星傳又曰：「彗星入北斗，有大戰。其流入北斗中，得名人；〔一四〕不入，失名人。」宋華元，賢名大夫，大棘之戰，華元獲於鄭，〔一五〕傳舉其效云。左氏傳曰有星孛北斗，周史服曰：「不出七年，宋、齊、晉之君皆將死亂。」〔一六〕劉歆以為北斗有環域，四星入其中也。斗，天之三辰，綱紀星也。宋、齊、晉，天子方伯，中國綱紀。彗所以除舊布新也。斗七星，故曰不出七年。至十六年，宋人弒昭公；〔一七〕十八年，齊人弒懿公；〔一八〕宣公二年，晉趙穿弒靈公。","sentenceOrder":319},
  {"id":"s_work_han_thu_37_320","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「文十四年齊公子商人弒其君舍，十六年宋人弒其君杵臼，十八年襄仲殺惡及視，莒弒其君庶其，宣二年晉趙穿攻靈公於桃園。」","sentenceOrder":320},
  {"id":"s_work_han_thu_37_321","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「視讀曰示。」","sentenceOrder":321},
  {"id":"s_work_han_thu_37_322","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「宋、魯、莒、晉已解於上。宣四年鄭公子歸生弒其君夷，十年陳夏徵舒弒其君平國。」","sentenceOrder":322},
  {"id":"s_work_han_thu_37_323","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「再弒者，謂（向）〔商〕人殺舍，而閻職等又殺（向）〔商〕人。」","sentenceOrder":323},
  {"id":"s_work_han_thu_37_324","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「謂邲戰之後。」","sentenceOrder":324},
  {"id":"s_work_han_thu_37_325","chapterId":"ch_work_han_thu_37","textTraditional":"〔六〕　師古曰：「謂宣十二年春楚子圍鄭，夏與晉師戰于邲，晉師敗績，十三年楚子伐宋，十四年楚子圍宋，成二年楚師侵衛，遂侵魯師于蜀，成六年楚公子嬰齊帥師伐鄭。」","sentenceOrder":325},
  {"id":"s_work_han_thu_37_326","chapterId":"ch_work_han_thu_37","textTraditional":"〔七〕　師古曰：「謂宣十二年楚子滅蕭。」","sentenceOrder":326},
  {"id":"s_work_han_thu_37_327","chapterId":"ch_work_han_thu_37","textTraditional":"〔八〕　師古曰：「已解於上。」","sentenceOrder":327},
  {"id":"s_work_han_thu_37_328","chapterId":"ch_work_han_thu_37","textTraditional":"〔九〕　師古曰：「謂宣十五年晉滅赤狄潞氏，十六年滅赤狄甲氏也。」","sentenceOrder":328},
  {"id":"s_work_han_thu_37_329","chapterId":"ch_work_han_thu_37","textTraditional":"〔一０〕師古曰：「謂成元年晉敗王師于貿戎是也。」","sentenceOrder":329},
  {"id":"s_work_han_thu_37_330","chapterId":"ch_work_han_thu_37","textTraditional":"〔一一〕師古曰：「謂成二年晉郤克會魯季孫行父、衛孫良夫、曹公子首及齊侯戰于鞍，齊師敗績。鞍，齊地。」","sentenceOrder":330},
  {"id":"s_work_han_thu_37_331","chapterId":"ch_work_han_thu_37","textTraditional":"〔一二〕師古曰：「謂逐之三周華不注，又從之入自丘輿，擊馬陘，東至海濱也。」","sentenceOrder":331},
  {"id":"s_work_han_thu_37_332","chapterId":"ch_work_han_thu_37","textTraditional":"〔一三〕師古曰：「炎音弋贍反。其下並同。」","sentenceOrder":332},
  {"id":"s_work_han_thu_37_333","chapterId":"ch_work_han_thu_37","textTraditional":"〔一四〕孟康曰：「謂得名臣也。」","sentenceOrder":333},
  {"id":"s_work_han_thu_37_334","chapterId":"ch_work_han_thu_37","textTraditional":"〔一五〕師古曰：「宣二年宋華元帥師及鄭公子歸生戰于大棘，宋師敗績，獲華元。大棘，宋地。」","sentenceOrder":334},
  {"id":"s_work_han_thu_37_335","chapterId":"ch_work_han_thu_37","textTraditional":"〔一六〕師古曰：「史服，周內史叔服也。」","sentenceOrder":335},
  {"id":"s_work_han_thu_37_336","chapterId":"ch_work_han_thu_37","textTraditional":"〔一七〕師古曰：「即杵臼。」","sentenceOrder":336},
  {"id":"s_work_han_thu_37_337","chapterId":"ch_work_han_thu_37","textTraditional":"〔一八〕師古曰：「即商人。」","sentenceOrder":337},
  {"id":"s_work_han_thu_37_338","chapterId":"ch_work_han_thu_37","textTraditional":"昭公十七年「冬，有星孛于大辰」。董仲舒以為大辰心也，心（在）〔為〕明堂，天子之象。後王室大亂，三王分爭，此其效也〔一〕。劉向以為星傳曰「心，大星，天王也。其前星，太子；後星，庶子也。尾為君臣乖離。」孛星加心，象天子適庶將分爭也。〔二〕其在諸侯，角、亢、氐，陳、鄭也；房、心，宋也。後五年，周景王崩，王室亂，大夫劉子、單子立王猛，尹氏、召伯、毛伯立子晁。子晁，楚出也。〔三〕時楚彊，宋、衛、陳、鄭皆南附楚。王猛既卒，敬王即位，子晁入王城，天王居狄泉，莫之敢納。五年，楚平王居卒，子晁奔楚，王室乃定。後楚帥六國伐吳，吳敗之于雞父，殺獲其君臣。〔四〕蔡怨楚而滅沈，楚怒，圍蔡。吳人救之，遂為柏舉之戰，敗楚師，屠郢都，妻昭王母，鞭平王墓。〔五〕此皆孛彗流炎所及之效也。左氏傳曰：「有星孛于大辰，西及漢。申繻曰：『彗，所以除舊布新也，〔六〕天事恆象。今除於火，火出必布焉。諸侯其有火災乎？』梓慎曰：『往年吾見，是其徵也。火出而見，今茲火出而章，必火入而伏，其居火也久矣，其與不然乎？火出，於夏為三月，於商為四月，於周為五月。夏數得天，若火作，其四國當之，在宋、衛、陳、鄭乎？宋，大辰之虛；陳，太昊之虛；鄭，祝融之虛：〔七〕皆火房也。星孛及漢；漢，水祥也。衛，顓頊之虛，其星為大水。水，火之牡也。〔八〕其以丙子若壬午作乎？水火所以合也。若火入而伏，必以壬午，不過見之月。』」明年「夏五月，火始昏見，丙子風。梓慎曰：『是謂融風，火之始也。〔九〕七日其火作乎？』〔一０〕戊寅風甚，壬午太甚，〔一一〕宋、衛、陳、鄭皆火。」劉歆以為大辰，房、心、尾也，八月心星在西方，孛從其西過心東及漢也。宋，大辰虛，謂宋先祖掌祀大辰星也。陳，太昊虛，虙羲木德，〔一二〕火所生也。鄭，祝融虛，高辛氏火正也。故皆為火所舍。衛，顓頊虛，星為大水，營室也。天星既然，又四國失政相似，及為王室亂皆同。","sentenceOrder":338},
  {"id":"s_work_han_thu_37_339","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「三王，已解於上。」","sentenceOrder":339},
  {"id":"s_work_han_thu_37_340","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「適讀曰嫡。」","sentenceOrder":340},
  {"id":"s_work_han_thu_37_341","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「姊妹之子曰出。」","sentenceOrder":341},
  {"id":"s_work_han_thu_37_342","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「昭二十三年，楚薳越帥師，及頓、胡、沈、蔡、陳、許之師與吳師戰于雞父，楚師敗績。胡子髡、沈子逞滅，獲陳大夫夏齧。雞父，楚地也。父讀曰甫。」","sentenceOrder":342},
  {"id":"s_work_han_thu_37_343","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「沈，楚之與國。定四年四月，蔡公孫姓帥師滅沈，以沈子嘉歸。秋，楚為沈故圍蔡。冬，吳興師以救之，與楚戰于柏舉，楚師敗績。庚辰，吳入郢，君舍乎君室，大夫舍乎大夫室，妻楚王之母，撻平王之墓也。」","sentenceOrder":343},
  {"id":"s_work_han_thu_37_344","chapterId":"ch_work_han_thu_37","textTraditional":"〔六〕　師古曰：「申繻，魯大夫。」","sentenceOrder":344},
  {"id":"s_work_han_thu_37_345","chapterId":"ch_work_han_thu_37","textTraditional":"〔七〕　師古曰：「虛讀皆曰墟。其下並同。」","sentenceOrder":345},
  {"id":"s_work_han_thu_37_346","chapterId":"ch_work_han_thu_37","textTraditional":"〔八〕　張晏曰：「水以天一，為地二牡。丙與午，南方火也，子及壬，北方水也，又其配合。」","sentenceOrder":346},
  {"id":"s_work_han_thu_37_347","chapterId":"ch_work_han_thu_37","textTraditional":"〔九〕　張晏曰：「融風，立春木風也，火之母也，火所始生也。淮南子曰『東北曰炎風』。高誘以為艮氣所生也。炎風一曰融風。」","sentenceOrder":347},
  {"id":"s_work_han_thu_37_348","chapterId":"ch_work_han_thu_37","textTraditional":"〔一０〕張晏曰：「自丙子至壬午凡七日，既其配合之日，又火以七為紀。」","sentenceOrder":348},
  {"id":"s_work_han_thu_37_349","chapterId":"ch_work_han_thu_37","textTraditional":"〔一一〕師古曰：「太甚者，又更甚也。」","sentenceOrder":349},
  {"id":"s_work_han_thu_37_350","chapterId":"ch_work_han_thu_37","textTraditional":"〔一二〕師古曰：「虙讀與伏同。」","sentenceOrder":350},
  {"id":"s_work_han_thu_37_351","chapterId":"ch_work_han_thu_37","textTraditional":"哀公十三年「冬十一月，有星孛于東方」。董仲舒、劉向以為不言宿名者，不加宿也。〔一〕以辰乘日而出，亂氣蔽君明也。明年，春秋事終。一曰，周之十一月，夏九月，日在氐。出東方者，軫、角、亢也。軫，楚；角、亢，陳、鄭也。或曰角、亢大國象，為齊、晉也。其後楚滅陳，〔二〕田氏篡齊，〔三〕六卿分晉，〔四〕此其效也。劉歆以為孛，東方大辰也，不言大辰，旦而見與日爭光，星入而彗猶見。是歲再失閏，十一月實八月也。日在鶉火，周分野也。十四年冬，「有星孛」，在獲麟後。劉歆以為不言所在，官失之也。","sentenceOrder":351},
  {"id":"s_work_han_thu_37_352","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　孟康曰：「不在二十八宿之中也。」","sentenceOrder":352},
  {"id":"s_work_han_thu_37_353","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「襄十七年楚公孫朝帥師滅陳也。」","sentenceOrder":353},
  {"id":"s_work_han_thu_37_354","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「齊平公十三年，春秋之傳終矣。平公二十五年卒。卒後七十年而康公為田和所滅。」","sentenceOrder":354},
  {"id":"s_work_han_thu_37_355","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「晉出公八年，春秋之傳終矣。出公十七年卒。卒後八十年，至靜公為韓、魏、趙所滅，而三分其地。蓋晉之衰也，六卿擅權，其後范氏、中行氏、智氏滅，而韓、魏、趙兼其土田人眾，故總言六卿分晉也。」","sentenceOrder":355},
  {"id":"s_work_han_thu_37_356","chapterId":"ch_work_han_thu_37","textTraditional":"高帝三年七月，有星孛于大角，旬餘乃入。劉向以為是時項羽為楚王，伯諸侯，〔一〕而漢已定三秦，與羽相距滎陽，天下歸心於漢，楚將滅，故彗除王位也。一曰，項羽阬秦卒，燒宮室，弒義帝，亂王位，故彗加之也。","sentenceOrder":356},
  {"id":"s_work_han_thu_37_357","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「伯讀曰霸。」","sentenceOrder":357},
  {"id":"s_work_han_thu_37_358","chapterId":"ch_work_han_thu_37","textTraditional":"文帝後七年九月，有星孛于西方，其本直尾、箕，末指虛、危，長丈餘，及天漢，十六日不見。劉向以為尾宋地，今楚彭城也。箕為燕，又為吳、越、齊。宿在漢中，負海之國水澤地也。是時景帝新立，信用晁錯，將誅正諸侯王，其象先見。後三年，吳、楚、四齊與趙七國舉兵反，〔一〕皆誅滅云。","sentenceOrder":358},
  {"id":"s_work_han_thu_37_359","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「四齊，膠東、膠西、菑川、濟南也。」","sentenceOrder":359},
  {"id":"s_work_han_thu_37_360","chapterId":"ch_work_han_thu_37","textTraditional":"武帝建元六年六月，有星孛于北方。劉向以為明年淮南王安入朝，與太尉武安侯田蚡有邪謀，而陳皇后驕恣，其後陳后廢，而淮南王反，誅。","sentenceOrder":360},
  {"id":"s_work_han_thu_37_361","chapterId":"ch_work_han_thu_37","textTraditional":"八月，長星出于東方，長終天，三十日去。占曰：「是為蚩尤旗，見則王者征伐四方。」其後兵誅四夷，連數十年。","sentenceOrder":361},
  {"id":"s_work_han_thu_37_362","chapterId":"ch_work_han_thu_37","textTraditional":"元狩四年四月，長星又出西北，是時伐胡尤甚。","sentenceOrder":362},
  {"id":"s_work_han_thu_37_363","chapterId":"ch_work_han_thu_37","textTraditional":"元封元年五月，有星孛于東井，又孛于三台。其後江充作亂，京師紛然。此明東井、三台為秦地效也。","sentenceOrder":363},
  {"id":"s_work_han_thu_37_364","chapterId":"ch_work_han_thu_37","textTraditional":"宣帝地節元年正月，有星孛于西方，去太白二丈所。劉向以為太白為大將，彗孛加之，掃滅象也。明年，大將軍霍光薨，後二年家夷滅。","sentenceOrder":364},
  {"id":"s_work_han_thu_37_365","chapterId":"ch_work_han_thu_37","textTraditional":"成帝建始元年正月，有星孛于營室，青白色，長六七丈，廣尺餘。劉向、谷永以為營室為後宮懷任之象，彗星加之，將有害懷任絕繼嗣者。一曰，後宮將受害也。其後許皇后坐祝詛後宮懷任者廢。趙皇后立妹為昭儀，害兩皇子，上遂無嗣。趙后姊妹卒皆伏辜。","sentenceOrder":365},
  {"id":"s_work_han_thu_37_366","chapterId":"ch_work_han_thu_37","textTraditional":"元延元年七月辛未，有星孛于東井，踐五諸侯，〔一〕出河戍北率行軒轅、太微，後日六度有餘，晨出東方。十三日夕見西方，犯次妃、長秋、斗、填，蜂炎再貫紫宮中。大火當後，達天河，除於妃后之域。南逝度犯大角、攝提，至天市而按節徐行，〔二〕炎入市，中旬而後西去，五十六日與倉龍俱伏。谷永對曰：「上古以來，大亂之極，所希有也。察其馳騁驟步，芒炎或長或短，所歷奸犯，〔三〕內為後宮女妾之害，外為諸夏叛逆之禍。」劉向亦曰：「三代之亡，攝提易方；秦、項之滅，星孛大角。」是歲，趙昭儀害兩皇子。後五年，成帝崩，昭儀自殺。哀帝即位，趙氏皆免官爵，徙遼西。哀帝亡嗣。平帝即位，王莽用事，追廢成帝趙皇后、哀帝傅皇后，皆自殺。外家丁、傅皆免官爵，徙合浦，歸故郡。平帝亡嗣，莽遂篡國。","sentenceOrder":366},
  {"id":"s_work_han_thu_37_367","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　孟康曰：「五諸侯，星名。」","sentenceOrder":367},
  {"id":"s_work_han_thu_37_368","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　服虔曰：「謂行遲。」","sentenceOrder":368},
  {"id":"s_work_han_thu_37_369","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「奸音干。」","sentenceOrder":369},
  {"id":"s_work_han_thu_37_370","chapterId":"ch_work_han_thu_37","textTraditional":"釐公十六年「正月戊申朔，隕石于宋，五，是月六鶂退飛過宋都」。董仲舒、劉向以為象宋襄公欲行伯道將自敗之戒也。〔一〕石陰類，五陽數，自上而隕，此陰而陽行，欲高反下也。石與金同類，色以白為主，近白祥也。鶂水鳥，六陰數，退飛，欲進反退也。其色青，青祥也，屬於貌之不恭。天戒若曰，德薄國小，勿持炕陽，欲長諸侯，與彊大爭，必受其害。襄公不寤，明年齊威死，伐齊喪，〔二〕執滕子，圍曹，〔三〕為盂之會，與楚爭盟，卒為所執。後得反國，〔四〕不悔過自責，復會諸侯伐鄭，與楚戰于泓，軍敗身傷，為諸侯笑。〔五〕左氏傳曰：隕石，星也；鶂退飛，風也。宋襄公以問周內史叔興曰：「是何祥也？吉凶何在？」對曰：「今茲魯多大喪，明年齊有亂，〔六〕君將得諸侯而不終。」退而告人曰：「是陰陽之事，非吉凶之所生也。吉凶繇人，吾不敢逆君故也。」〔七〕是歲，魯公子季友、鄫季姬、公孫茲皆卒。〔八〕明年齊威死，適庶亂。〔九〕宋襄公伐齊行伯，卒為楚所敗。〔一０〕劉歆以為是歲歲在壽星，其衝降婁。〔一一〕降婁，魯分野也，故為魯多大喪。正月，日在星紀，厭在玄枵。玄枵，齊分野也。石，山物；齊，大嶽後。〔一二〕五石象齊威卒而五公子作亂，〔一三〕故為明年齊有亂。庶民惟星，隕於宋，象宋襄將得諸侯之眾，而治五公子之亂。星隕而鶂退飛，故為得諸侯而不終。六鶂象後六年伯業始退，執於盂也。〔一四〕民反德為亂，亂則妖災生，言吉凶繇人，然后陰陽衝厭受其咎。齊、魯之災非君所致，故曰「吾不敢逆君故也」。京房易傳曰：「距諫自彊，茲謂卻行，厥異鶂退飛。適當黜，則鶂退飛。」〔一五〕","sentenceOrder":370},
  {"id":"s_work_han_thu_37_371","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「伯讀曰霸。」","sentenceOrder":371},
  {"id":"s_work_han_thu_37_372","chapterId":"ch_work_han_thu_37","textTraditional":"〔二〕　師古曰：「僖十七年齊桓公卒，十八年宋襄公以諸侯伐齊。」","sentenceOrder":372},
  {"id":"s_work_han_thu_37_373","chapterId":"ch_work_han_thu_37","textTraditional":"〔三〕　師古曰：「十九年三月，宋人執滕子嬰齊，秋，宋人圍曹。」","sentenceOrder":373},
  {"id":"s_work_han_thu_37_374","chapterId":"ch_work_han_thu_37","textTraditional":"〔四〕　師古曰：「二十一年春，為鹿上之盟。秋，會于盂。於是楚執宋公以伐宋，冬，會于薄以釋之。鹿上、盂、薄，皆宋地。」","sentenceOrder":374},
  {"id":"s_work_han_thu_37_375","chapterId":"ch_work_han_thu_37","textTraditional":"〔五〕　師古曰：「二十二年夏，宋公、衛侯、許男、滕子伐鄭。十一月，宋公及楚人戰於泓，宋師敗績，公傷股，門官殲焉。二十三年卒，傷於泓故也。泓，水名也，音於宏反。」","sentenceOrder":375},
  {"id":"s_work_han_thu_37_376","chapterId":"ch_work_han_thu_37","textTraditional":"〔六〕　師古曰：「今茲謂此年。」","sentenceOrder":376},
  {"id":"s_work_han_thu_37_377","chapterId":"ch_work_han_thu_37","textTraditional":"〔七〕　師古曰：「繇讀與由同。」","sentenceOrder":377},
  {"id":"s_work_han_thu_37_378","chapterId":"ch_work_han_thu_37","textTraditional":"〔八〕　師古曰：「僖十六年三月公子季友卒，四月季姬卒，七月公孫茲卒。季姬，魯女適鄫者也。公孫茲，叔孫戴伯也。」","sentenceOrder":378},
  {"id":"s_work_han_thu_37_379","chapterId":"ch_work_han_thu_37","textTraditional":"〔九〕　師古曰：「適讀曰嫡。」","sentenceOrder":379},
  {"id":"s_work_han_thu_37_380","chapterId":"ch_work_han_thu_37","textTraditional":"〔一０〕師古曰：「已解於上，伯讀曰霸。」","sentenceOrder":380},
  {"id":"s_work_han_thu_37_381","chapterId":"ch_work_han_thu_37","textTraditional":"〔一一〕師古曰：「降音胡江反。」","sentenceOrder":381},
  {"id":"s_work_han_thu_37_382","chapterId":"ch_work_han_thu_37","textTraditional":"〔一二〕師古曰：「齊，姜姓也，其先為堯之四嶽，四嶽分掌四方諸侯。」","sentenceOrder":382},
  {"id":"s_work_han_thu_37_383","chapterId":"ch_work_han_thu_37","textTraditional":"〔一三〕師古曰：「五公子，謂無虧也，元也，昭也，潘也，商人也。」","sentenceOrder":383},
  {"id":"s_work_han_thu_37_384","chapterId":"ch_work_han_thu_37","textTraditional":"〔一四〕師古曰：「伯讀曰霸。」","sentenceOrder":384},
  {"id":"s_work_han_thu_37_385","chapterId":"ch_work_han_thu_37","textTraditional":"〔一五〕師古曰：「適讀曰嫡。」","sentenceOrder":385},
  {"id":"s_work_han_thu_37_386","chapterId":"ch_work_han_thu_37","textTraditional":"惠帝三年，隕石綿諸，一。〔一〕","sentenceOrder":386},
  {"id":"s_work_han_thu_37_387","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「綿諸，道也，屬天水郡也。」","sentenceOrder":387},
  {"id":"s_work_han_thu_37_388","chapterId":"ch_work_han_thu_37","textTraditional":"武帝征和四年二月丁酉，隕石雍，二，天晏亡雲，聲聞四百里。〔一〕","sentenceOrder":388},
  {"id":"s_work_han_thu_37_389","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「雍，扶風之縣也。晏，天清也。」","sentenceOrder":389},
  {"id":"s_work_han_thu_37_390","chapterId":"ch_work_han_thu_37","textTraditional":"元帝建昭元年正月戊辰，隕石梁國，六。","sentenceOrder":390},
  {"id":"s_work_han_thu_37_391","chapterId":"ch_work_han_thu_37","textTraditional":"成帝建始四年正月癸卯，隕石槁，四，肥累，一。〔一〕","sentenceOrder":391},
  {"id":"s_work_han_thu_37_392","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　孟康曰：「皆縣名也，故屬真定。」師古曰：「槁音工老反。累音力追反。」","sentenceOrder":392},
  {"id":"s_work_han_thu_37_393","chapterId":"ch_work_han_thu_37","textTraditional":"陽朔三年二月壬戌，隕石白馬，八。〔一〕","sentenceOrder":393},
  {"id":"s_work_han_thu_37_394","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「東郡之縣名。」","sentenceOrder":394},
  {"id":"s_work_han_thu_37_395","chapterId":"ch_work_han_thu_37","textTraditional":"鴻嘉二年五月癸未，隕石杜衍，三。〔一〕","sentenceOrder":395},
  {"id":"s_work_han_thu_37_396","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「南陽之縣名。」","sentenceOrder":396},
  {"id":"s_work_han_thu_37_397","chapterId":"ch_work_han_thu_37","textTraditional":"元延四年三月，隕石都關，二。〔一〕","sentenceOrder":397},
  {"id":"s_work_han_thu_37_398","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「山陽之縣名。」","sentenceOrder":398},
  {"id":"s_work_han_thu_37_399","chapterId":"ch_work_han_thu_37","textTraditional":"哀帝建平元年正月丁未，隕石北地，十。其九月甲辰，隕石虞，二。〔一〕","sentenceOrder":399},
  {"id":"s_work_han_thu_37_400","chapterId":"ch_work_han_thu_37","textTraditional":"〔一〕　師古曰：「梁國之縣名。」","sentenceOrder":400},
  {"id":"s_work_han_thu_37_401","chapterId":"ch_work_han_thu_37","textTraditional":"平帝元始二年六月，隕石鉅鹿，二。","sentenceOrder":401},
  {"id":"s_work_han_thu_37_402","chapterId":"ch_work_han_thu_37","textTraditional":"自惠盡平，隕石凡十一，皆有光燿雷聲，成、哀尤屢。","sentenceOrder":402},
  {"id":"s_work_han_thu_37_403","chapterId":"ch_work_han_thu_37","textTraditional":"校勘記","sentenceOrder":403},
  {"id":"s_work_han_thu_37_404","chapterId":"ch_work_han_thu_37","textTraditional":"一四七九頁　八行　史記（曰）〔日〕食，　殿本作「日」。王先謙說作「日」是。","sentenceOrder":404},
  {"id":"s_work_han_thu_37_405","chapterId":"ch_work_han_thu_37","textTraditional":"一四八０頁一二行　渝平，墮（城）〔成〕也。　景祐、殿、局本都作「成」。朱一新說「成」字是。","sentenceOrder":405},
  {"id":"s_work_han_thu_37_406","chapterId":"ch_work_han_thu_37","textTraditional":"一四八五頁　六行　楚（國）〔圍〕許，　景祐、殿、局本都作「圍」。朱一新說作「圍」是。","sentenceOrder":406},
  {"id":"s_work_han_thu_37_407","chapterId":"ch_work_han_thu_37","textTraditional":"一四八六頁　二行　三月庚午（朔），　王引之說「朔」衍字，檢左氏、公羊、穀梁皆無「朔」字。","sentenceOrder":407},
  {"id":"s_work_han_thu_37_408","chapterId":"ch_work_han_thu_37","textTraditional":"一四八七頁一四行　（夷）〔楚〕滅舒蓼。　景祐、殿本都作「楚」。","sentenceOrder":408},
  {"id":"s_work_han_thu_37_409","chapterId":"ch_work_han_thu_37","textTraditional":"一四九０頁　六行　十五年八月丁巳〔朔〕，　錢大昭說閩本有「朔」字。按景祐本有。","sentenceOrder":409},
  {"id":"s_work_han_thu_37_410","chapterId":"ch_work_han_thu_37","textTraditional":"一四九五頁　一行　謂常可以此占之（下）〔不〕。　景祐、殿本都作「不」。","sentenceOrder":410},
  {"id":"s_work_han_thu_37_411","chapterId":"ch_work_han_thu_37","textTraditional":"一五０一頁　六行　在斗二十（三）〔二〕度。　錢大昭說閩本作「二」。按景祐本作「二」。","sentenceOrder":411},
  {"id":"s_work_han_thu_37_412","chapterId":"ch_work_han_thu_37","textTraditional":"一五０四頁　六行　能應之（司）〔以〕德，　景祐、殿、局本都作「以」。","sentenceOrder":412},
  {"id":"s_work_han_thu_37_413","chapterId":"ch_work_han_thu_37","textTraditional":"一五０七頁　五行　辟（（暂缺F604））〔諐〕公行，　楊樹達說「（暂缺F604）」當作「諐」，諐與愆同。按各本皆誤。","sentenceOrder":413},
  {"id":"s_work_han_thu_37_414","chapterId":"ch_work_han_thu_37","textTraditional":"一五０九頁　八行　（名）〔民〕去其上，　景祐、殿本都作「民」，此誤。","sentenceOrder":414},
  {"id":"s_work_han_thu_37_415","chapterId":"ch_work_han_thu_37","textTraditional":"一五一二頁一四行　（向）〔商〕人　景祐、殿本都作「商」。王先謙說作「商」是。","sentenceOrder":415},
  {"id":"s_work_han_thu_37_416","chapterId":"ch_work_han_thu_37","textTraditional":"一五一三頁一四行　心（在）〔為〕明堂，　景祐、殿本都作「為」。王先謙說作「為」是。","sentenceOrder":416},
  {"id":"s_work_han_thu_38_1","chapterId":"ch_work_han_thu_38","textTraditional":"昔在黃帝，作舟車以濟不通，旁行天下，〔一〕方制萬里，畫野分州，〔二〕得百里之國萬區。是故易稱「先王（以）建萬國，親諸侯」，〔三〕書云「協和萬國」，〔四〕此之謂也。堯遭洪水，褱山襄陵，〔五〕天下分絕，為十二州，〔六〕使禹治之。水土既平，更制九州，列五服，〔七〕任土作貢。〔八〕","sentenceOrder":1},
  {"id":"s_work_han_thu_38_2","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「旁行，謂四出而行之。」","sentenceOrder":2},
  {"id":"s_work_han_thu_38_3","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「方制，制為方域也。畫謂為之界也。野，古野字。畫音獲。」","sentenceOrder":3},
  {"id":"s_work_han_thu_38_4","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「易比卦象辭。」","sentenceOrder":4},
  {"id":"s_work_han_thu_38_5","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「虞書堯典之辭也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_38_6","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「褱字與（古）懷（字）同。懷，包也。襄，駕也。言水大汎溢，包山而駕陵也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_38_7","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「九州之外有并州、幽州、營州，故曰十二。水中可居者曰州。洪水汎大，各就高陸，人之所居，凡十二處。」","sentenceOrder":7},
  {"id":"s_work_han_thu_38_8","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「其數在下也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_38_9","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「任其土地所有，以定貢賦之差也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_38_10","chapterId":"ch_work_han_thu_38","textTraditional":"曰：禹敷土，〔一〕隨山栞木，奠高山大川。〔二〕","sentenceOrder":10},
  {"id":"s_work_han_thu_38_11","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「敷，分也，謂分別治之。自此以下皆是夏書禹貢之文。」","sentenceOrder":11},
  {"id":"s_work_han_thu_38_12","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「栞，古刊字也。奠，定也。言禹隨行山之形狀而刊斫其木，以為表記，決水通道，故高山大川各得安定也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_38_13","chapterId":"ch_work_han_thu_38","textTraditional":"冀州既載，〔一〕壺口治梁及岐。〔二〕既脩太原，至于嶽陽。〔三〕覃懷底績，至于衡章。〔四〕厥土惟白壤。〔五〕厥賦上上錯，〔六〕厥田中中。〔七〕恆、衛既從，大陸既作。〔八〕鳥夷皮服。〔九〕夾右碣石，入于河。〔一０〕","sentenceOrder":13},
  {"id":"s_work_han_thu_38_14","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「兩河間曰冀州。載，始也。冀州，堯所都，故禹治水自冀州始也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_38_15","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「壺口山在河東。梁山在夏陽。岐山在美陽，即今之岐州岐山縣箭括嶺也。禹循山而西，治眾水。」","sentenceOrder":15},
  {"id":"s_work_han_thu_38_16","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「太原即今之晉陽是也。嶽陽在太原西南。」","sentenceOrder":16},
  {"id":"s_work_han_thu_38_17","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「覃懷，近河地名也。底，致也。績，功也。衡章，謂章水橫流而入河也。言禹於覃懷致功以至衡章也。底音之履反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_38_18","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「柔土曰壤。」","sentenceOrder":18},
  {"id":"s_work_han_thu_38_19","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「賦者，發斂土地所生之物以供天子也。上上，第一也。錯，雜也。言賦第一，又雜出諸品也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_38_20","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「言其高下之形摠於九州之中為第五也。一曰，為其肥瘠之等差也。它皆類此。」","sentenceOrder":20},
  {"id":"s_work_han_thu_38_21","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「恆、衛，二水名。恆水出恆山，衛水在靈壽。大陸，澤名，在鉅鹿北。言恆、衛之水各從故道，大陸之澤已可耕作也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_38_22","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「此東北之夷，搏取鳥獸，食其肉而衣其皮也。一說，居在海曲，被服容止皆象鳥也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_38_23","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「碣石，海邊山名也。言禹夾行此山之右而入于河，逆上也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_38_24","chapterId":"ch_work_han_thu_38","textTraditional":"泲、河惟兗州。〔一〕九河既道，〔二〕雷夏既澤，雍、沮會同，〔三〕桑土既蠶，是降丘宅土。〔四〕厥土黑墳，〔五〕屮繇木條。〔六〕厥田中下，〔七〕賦貞，〔八〕作十有三年乃同。〔九〕厥貢漆絲，〔一０〕厥棐織文。〔一一〕浮于泲、漯，通于河。〔一二〕","sentenceOrder":24},
  {"id":"s_work_han_thu_38_25","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「泲本濟水之字，從水〈泲，去氵〉聲。言此州東南據濟水，西北距河。泲音姊。」","sentenceOrder":25},
  {"id":"s_work_han_thu_38_26","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「九河，河水分為九，各從其道。爾雅曰：『徒駭、太史、馬頰、覆釜、胡蘇、簡、絜、鉤般、鬲津，是曰九河。』一說，道讀曰導。導，治也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_38_27","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「雷夏，澤名，在濟陰城陽西北。言此澤還復其故，而雍、沮二水同會其中也。沮音千余反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_38_28","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「降，下也。宅，居也。言此地宜桑，先時人眾避水，皆上丘陵，今水害除，得以蠶織，故皆下丘居平土也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_38_29","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「色黑而墳起也。墳音扶粉反。」","sentenceOrder":29},
  {"id":"s_work_han_thu_38_30","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「屮，古草字也。繇，悅茂也。條，脩暢也。繇音弋昭反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_38_31","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「第六也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_38_32","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「貞，正也。州第九，賦亦正當也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_38_33","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「治水十三年，乃同於它州，言用功多也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_38_34","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「貢，獻也。地宜漆林，又善蠶絲，故以獻也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_38_35","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕師古曰：「棐與篚同。篚，竹器，筐屬也。織文，錦綺之類，盛於筐篚而獻之。」","sentenceOrder":35},
  {"id":"s_work_han_thu_38_36","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕師古曰：「浮，以舟渡也。泲、漯，二水名。漯水出東郡東武陽。因水入水曰通。漯音它合反。」","sentenceOrder":36},
  {"id":"s_work_han_thu_38_37","chapterId":"ch_work_han_thu_38","textTraditional":"海、岱惟青州。〔一〕嵎夷既略，惟、甾其道。〔二〕厥土白墳，海瀕廣潟。〔三〕田上下，賦中上。〔四〕貢鹽、絺，海物惟錯，〔五〕岱畎絲、枲、鈆、松、怪石，〔六〕萊夷作牧，厥棐檿絲〔七〕。浮于汶，達于泲。〔八〕","sentenceOrder":37},
  {"id":"s_work_han_thu_38_38","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「東北據海，西南距岱。岱即太山也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_38_39","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「嵎夷，地名也，即陽谷所在。略，言用功少也。惟、甾，二水名。皆復故道也。惟水出琅邪箕屋山。甾水出泰山萊蕪縣。惟字今作濰，甾字或作淄，古今通用也。一曰，道讀曰導。導，治也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_38_40","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「瀕，水涯也。潟，鹵鹹之地。瀕音頻，又音賓。潟音昔。」","sentenceOrder":40},
  {"id":"s_work_han_thu_38_41","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「田第三，賦第四。」","sentenceOrder":41},
  {"id":"s_work_han_thu_38_42","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「葛之精者曰絺。海中物產既多，故雜獻。」","sentenceOrder":42},
  {"id":"s_work_han_thu_38_43","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「畎，小谷也。枲，麻屬也。鈆，青金也。怪石，石之次玉美好者也。言岱山之谷，出絲、枲、鈆、松、怪石五種，皆獻之。畎音工犬反。」","sentenceOrder":43},
  {"id":"s_work_han_thu_38_44","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「萊山之夷，地宜畜牧。檿，檿桑也。食檿之蠶絲，可以弦琴瑟。檿音烏簟反。」","sentenceOrder":44},
  {"id":"s_work_han_thu_38_45","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「汶水出泰山郡萊蕪縣原山。言渡汶水西達于泲也。汶音問。」","sentenceOrder":45},
  {"id":"s_work_han_thu_38_46","chapterId":"ch_work_han_thu_38","textTraditional":"海、岱及淮惟徐州。〔一〕淮、沂其乂，蒙、羽其藝。〔二〕大野既豬，東原厎平。〔三〕厥土赤埴墳，草木漸包。〔四〕田上中，賦中中。〔五〕貢土五色，〔六〕羽畎夏狄，嶧陽孤桐，〔七〕泗瀕浮磬，〔八〕淮夷蠙珠臮魚，〔九〕厥棐玄纖縞。〔一０〕浮于淮、泗，達于河。〔一一〕","sentenceOrder":46},
  {"id":"s_work_han_thu_38_47","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「東至海，北至岱，南及淮。」","sentenceOrder":47},
  {"id":"s_work_han_thu_38_48","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「淮、沂二水已治，蒙、羽二山皆可種藝也。淮出大復山。沂出泰山。沂音牛依反。」","sentenceOrder":48},
  {"id":"s_work_han_thu_38_49","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「大野即鉅野澤也。豬，停水也。東原，地名。厎，致也。言大野之水既已停蓄也。東原之地致功而平可耕稼也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_38_50","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「埴，黏土也。漸包，言相漸及包裹而生。」","sentenceOrder":50},
  {"id":"s_work_han_thu_38_51","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「田第二，賦第五。」","sentenceOrder":51},
  {"id":"s_work_han_thu_38_52","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「王者取五色土，封以為太社，而此州畢貢之，言備有。」","sentenceOrder":52},
  {"id":"s_work_han_thu_38_53","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「羽畎，羽山之谷也。夏狄，狄雉之羽可為旌旄者也，羽山之谷出焉。嶧陽，嶧山之陽也。山南曰陽。孤桐，特生之桐也，可為琴瑟，嶧山之南生焉。嶧音驛。」","sentenceOrder":53},
  {"id":"s_work_han_thu_38_54","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「泗水之涯浮出好石，可為磬也。泗水出濟陰乘氏縣。」","sentenceOrder":54},
  {"id":"s_work_han_thu_38_55","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「淮夷，淮水上之夷也。蠙珠，珠名。臮，及也。言其地出珠及美魚也。蠙音步千反，字或作玭。」","sentenceOrder":55},
  {"id":"s_work_han_thu_38_56","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「玄，黑也。纖，細繒也。縞，鮮支也，即今所謂素者也。言獻黑細繒及鮮支也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_38_57","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕師古曰：「渡二水而入于河。」","sentenceOrder":57},
  {"id":"s_work_han_thu_38_58","chapterId":"ch_work_han_thu_38","textTraditional":"淮、海惟揚州。〔一〕彭蠡既豬，陽鳥逌居。〔二〕三江既入，震澤厎定。〔三〕篠簜既敷，〔四〕屮夭木喬。〔五〕厥土塗泥〔六〕。田下下，賦下上錯。〔七〕貢金三品，〔八〕瑤、瑻、篠簜，齒、革、羽毛，〔九〕鳥夷卉服，〔一０〕厥棐織貝，〔一一〕厥包橘、柚，錫貢。〔一二〕均江海，通于淮、泗。〔一三〕","sentenceOrder":58},
  {"id":"s_work_han_thu_38_59","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「北據淮，南距海。」","sentenceOrder":59},
  {"id":"s_work_han_thu_38_60","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「彭蠡，澤名，在彭澤縣西北。陽鳥，隨陽之鳥也。言彭蠡之水既已蓄聚，則鴻雁之屬所共居之。蠡音禮。」","sentenceOrder":60},
  {"id":"s_work_han_thu_38_61","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「三江，謂北江、中江、南江也。震澤在吳西，即具區也。厎，致也。言三江既入，則震澤致定。」","sentenceOrder":61},
  {"id":"s_work_han_thu_38_62","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「篠，小竹也。簜，大竹也。敷謂布地而生也。篠音先了反。簜音蕩。」","sentenceOrder":62},
  {"id":"s_work_han_thu_38_63","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「夭，盛貌也。喬，上竦也。夭音於驕反。喬音橋，又音驕。」","sentenceOrder":63},
  {"id":"s_work_han_thu_38_64","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「瀸洳溼也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_38_65","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「田第九，賦第七。又雜出諸品。」","sentenceOrder":65},
  {"id":"s_work_han_thu_38_66","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「金、銀、銅。」","sentenceOrder":66},
  {"id":"s_work_han_thu_38_67","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「瑤、瑻，皆美玉名也。齒，象齒也。革，犀革也。羽旄，謂眾鳥之羽可為旄者也。瑻音昆。」","sentenceOrder":67},
  {"id":"s_work_han_thu_38_68","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「鳥夷，東南之夷善捕鳥者也。卉服，絺葛之屬。」","sentenceOrder":68},
  {"id":"s_work_han_thu_38_69","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕師古曰：「織謂細布也。貝，水蟲也，古以為貨。」","sentenceOrder":69},
  {"id":"s_work_han_thu_38_70","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕師古曰：「柚，似橘而大，其味尤酸。橘、柚皆不耐寒，故包裹而致之也。錫貢者，須錫命而獻之，言不常來也。柚音弋救反。」","sentenceOrder":70},
  {"id":"s_work_han_thu_38_71","chapterId":"ch_work_han_thu_38","textTraditional":"〔一三〕師古曰：「均，平也。通淮、泗而入江海，故云平。」","sentenceOrder":71},
  {"id":"s_work_han_thu_38_72","chapterId":"ch_work_han_thu_38","textTraditional":"荊及衡陽惟荊州。〔一〕江、漢朝宗于海。〔二〕九江孔殷〔三〕，沱、灊既道，雲夢，土作乂。〔四〕厥土塗泥。田下中，賦上下。〔五〕貢羽旄、齒、革，金三品，〔六〕杶、幹、栝、柏，厲、砥、砮、丹，〔七〕惟箘簵、楛，三國厎貢厥名，〔八〕包匭菁茅〔九〕，厥棐玄纁璣組，〔一０〕九江納錫大龜。〔一一〕浮于江、沱、灊、漢，逾于洛，至于南河。〔一二〕","sentenceOrder":72},
  {"id":"s_work_han_thu_38_73","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「北據荊山，南及衡山之陽也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_38_74","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「江、漢二水歸入于海，有似諸侯朝於天子，故曰朝宗。宗，尊也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_38_75","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「孔，甚也。殷，中也。言江水於此州界分為九道，甚得地形之中。」","sentenceOrder":75},
  {"id":"s_work_han_thu_38_76","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「沱、灊，二水名，自江出為沱，自漢出為灊。雲夢，澤名。言二水既從其道，則雲夢之土可為（畋魚）〔畎畝〕之治也。沱音徒何反。灊音潛。一曰，道讀曰導。導，治也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_38_77","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「田第八，賦第三。」","sentenceOrder":77},
  {"id":"s_work_han_thu_38_78","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「自金以上所貢與揚州同。」","sentenceOrder":78},
  {"id":"s_work_han_thu_38_79","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「杶木似樗而實。幹，柘也。栝木柏葉而松身。厲，磨也。砥，其尤細者也。砮，石名，可為矢鏃。丹，赤石也，所謂丹沙者也。杶音丑倫反。栝音古活反。砥音指，又音（祗）〔扺〕。砮音奴。」","sentenceOrder":79},
  {"id":"s_work_han_thu_38_80","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「箘簵，竹名，楛，木名也，皆可為矢。言此州界本有三國致貢斯物，其名稱美也。箘音囷。簵音路。楛音（枯）〔怙〕。」","sentenceOrder":80},
  {"id":"s_work_han_thu_38_81","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「匭，柙也。菁，菜也，可以為葅。茅可以縮酒。苞其茅匭其菁而獻之。匭音軌。菁音精。」","sentenceOrder":81},
  {"id":"s_work_han_thu_38_82","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「玄，黑色。纁，絳也。璣，珠之不圜者。組，綬類也。纁音勳。璣音機，又音祈。」","sentenceOrder":82},
  {"id":"s_work_han_thu_38_83","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕師古曰：「大龜尺有二寸，出於九江。錫命而納，不常獻也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_38_84","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕師古曰：「逾，越也。言渡四水而越洛，乃至南河也。南河在冀州南。」","sentenceOrder":84},
  {"id":"s_work_han_thu_38_85","chapterId":"ch_work_han_thu_38","textTraditional":"荊、河惟豫州。〔一〕伊、雒、瀍、澗既入于河，〔二〕滎、波既豬，〔三〕道荷澤，被盟豬。〔四〕厥土惟壤，下土墳壚。〔五〕田中上，賦錯上中。〔六〕貢漆、枲、絺、紵、棐纖纊，〔七〕錫貢磬錯。〔八〕浮于洛，入于河。〔九〕","sentenceOrder":85},
  {"id":"s_work_han_thu_38_86","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「西南至荊山，北距河水。」","sentenceOrder":86},
  {"id":"s_work_han_thu_38_87","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「伊出陸渾山，雒出冢領山，瀍出穀成山，澗出黽池山，四水皆入河。」","sentenceOrder":87},
  {"id":"s_work_han_thu_38_88","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「滎，沇水泆出所為也，即今滎澤是也。波，亦水名。言其水並已遏聚矣。一說，謂滎水之波。」","sentenceOrder":88},
  {"id":"s_work_han_thu_38_89","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「荷澤在湖陵。盟豬亦澤名，在荷之東北。言治荷澤之水衍溢，則使被及盟豬，不常入也。道讀曰導。荷音歌。被音被馬之被。盟音孟。」","sentenceOrder":89},
  {"id":"s_work_han_thu_38_90","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「高地則壤，下地則墳。壚謂土之剛黑者也，音盧。」","sentenceOrder":90},
  {"id":"s_work_han_thu_38_91","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「田第四，賦第二，雜出第一。」","sentenceOrder":91},
  {"id":"s_work_han_thu_38_92","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「紵，織紵為布及綀也。纖纊，細綿也。紵音佇。纊音曠。」","sentenceOrder":92},
  {"id":"s_work_han_thu_38_93","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「錯，治玉之石。磬錯，言可以治磬也。亦待錫命而貢。」","sentenceOrder":93},
  {"id":"s_work_han_thu_38_94","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「因洛入河也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_38_95","chapterId":"ch_work_han_thu_38","textTraditional":"華陽、黑水惟梁州。〔一〕岷、嶓既藝，沱、灊既道，〔二〕蔡、蒙旅平，和夷厎績。〔三〕厥土青黎。〔四〕田下上，賦下中三錯。〔五〕貢璆、鐵、銀、鏤、砮、磬，〔六〕熊、羆、狐、貍、織皮。〔七〕西頃因桓是來，〔八〕浮于灊，逾于沔，〔九〕入于渭，亂于河。〔一０〕","sentenceOrder":95},
  {"id":"s_work_han_thu_38_96","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「東據華山之南，西距黑水。」","sentenceOrder":96},
  {"id":"s_work_han_thu_38_97","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「岷，岷山也。嶓，嶓冢山也。言水已去，二山之土皆可種藝。沱、灊，二水，治從故道也。岷音旻。嶓音波。道讀曰導。」","sentenceOrder":97},
  {"id":"s_work_han_thu_38_98","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「蔡、蒙，二（水）〔山〕名。旅，陳也。旅平，言已平治而陳祭也。和夷，地名，亦以致功可耕稼也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_38_99","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「色青而細疏。」","sentenceOrder":99},
  {"id":"s_work_han_thu_38_100","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「田第七，賦第八，又雜出第七至第九，凡三品。」","sentenceOrder":100},
  {"id":"s_work_han_thu_38_101","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「璆，美玉也。鏤，剛鐵也。磬，磬石也。璆音虯。」","sentenceOrder":101},
  {"id":"s_work_han_thu_38_102","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「織皮，謂罽也。言貢四獸之皮，又貢（維）〔雜〕罽。」","sentenceOrder":102},
  {"id":"s_work_han_thu_38_103","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「西頃，山名，在臨洮西南。桓，水名也。言治西頃山，因桓水是來，無它道也。頃讀曰傾。」","sentenceOrder":103},
  {"id":"s_work_han_thu_38_104","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「漢上曰沔，音莫踐反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_38_105","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「正絕流曰亂。」","sentenceOrder":105},
  {"id":"s_work_han_thu_38_106","chapterId":"ch_work_han_thu_38","textTraditional":"黑水、西河惟雍州。〔一〕弱水既西，〔二〕涇屬渭汭。〔三〕漆、沮既從，酆水逌同。〔四〕荊、岐既旅，〔五〕終南、惇物，至于鳥鼠。〔六〕原隰厎績，至于豬野。〔七〕三危既宅，三苗丕敘。〔八〕厥土黃壤。田上上，賦中下。〔九〕貢球、琳、琅玕。〔一０〕浮于積石，至于龍門西河，〔一一〕會于渭汭。〔一二〕織皮昆崙、析支、渠叟，西戎即敘。〔一三〕","sentenceOrder":106},
  {"id":"s_work_han_thu_38_107","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「西據黑水，東距西河。西河即龍門之河也，在冀州西，故曰西河。」","sentenceOrder":107},
  {"id":"s_work_han_thu_38_108","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「治使西流至合黎。」","sentenceOrder":108},
  {"id":"s_work_han_thu_38_109","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「屬，逮也。水北曰汭。言治涇水入于渭也。屬音之欲反。汭音芮，又音而悅反。」","sentenceOrder":109},
  {"id":"s_work_han_thu_38_110","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「漆、沮，即馮翊之洛水也。酆水出鄠之南山。言漆、沮既從入渭，酆水亦來同也。逌，古攸字也。攸，所也。沮音七余反。」","sentenceOrder":110},
  {"id":"s_work_han_thu_38_111","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「荊、岐，二山名。荊在岐東。言二山治畢，已旅祭也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_38_112","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「終南、惇物二山皆在武功。鳥鼠山在隴西首陽西南。自終南西出至于鳥鼠也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_38_113","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「高平曰原，下溼曰隰。豬野，地名。言皆致功也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_38_114","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「三危，山名，已可居也。三苗，本有苗氏之族，徙居於此，分而為三，故言三苗。今皆大得其次敘。」","sentenceOrder":114},
  {"id":"s_work_han_thu_38_115","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「田第一，賦第六。」","sentenceOrder":115},
  {"id":"s_work_han_thu_38_116","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「球、琳，皆玉名。琅玕，石似珠者也。球音求，又音虯。琳音林。琅音郎。玕音干。」","sentenceOrder":116},
  {"id":"s_work_han_thu_38_117","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕師古曰：「積石山在金城西南，龍門山在河東之西界，皆河水所經。」","sentenceOrder":117},
  {"id":"s_work_han_thu_38_118","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕師古曰：「逆流曰會。自渭北涯逆流西上。」","sentenceOrder":118},
  {"id":"s_work_han_thu_38_119","chapterId":"ch_work_han_thu_38","textTraditional":"〔一三〕師古曰：「昆崙、析支、渠叟，三國名也。言此諸國皆織皮毛，各得其業。而西方遠戎，並就次敘也。叟讀曰搜。」","sentenceOrder":119},
  {"id":"s_work_han_thu_38_120","chapterId":"ch_work_han_thu_38","textTraditional":"道〈氵幵〉及岐，至于荊山，〔一〕逾于河；〔二〕壺口、雷首，至于大嶽；〔三〕厎柱、析城，至于王屋；〔四〕太行、恆山，至于碣石，入于海。〔五〕西傾、朱圉、鳥鼠，至于太華；〔六〕熊耳、外方、桐柏，至于倍尾。〔七〕道嶓冢，至于荊山；〔八〕內方，至于大別；〔九〕崏山之陽，至于衡山，〔一０〕過九江，至于敷淺原〔一一〕。","sentenceOrder":120},
  {"id":"s_work_han_thu_38_121","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「自此以下，更說所治山水首尾之次也。治山通水，故舉山言之。〈氵幵〉山在〈氵幵〉縣西。道讀曰導。後皆類此。〈氵幵〉音苦堅反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_38_122","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「即梁山龍門。」","sentenceOrder":122},
  {"id":"s_work_han_thu_38_123","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「自壺口、雷首而至大嶽也。雷首在河東蒲阪南。大嶽即所謂嶽陽者。」","sentenceOrder":123},
  {"id":"s_work_han_thu_38_124","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「厎柱在陝縣東北，山在河中，形若柱也。析城山在濩澤西南。王屋山在垣縣東北。」","sentenceOrder":124},
  {"id":"s_work_han_thu_38_125","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「太行山在河內山陽西北。恆山在上曲陽西北。言二山連延，東北接碣石而入于海。行音胡郎反。」","sentenceOrder":125},
  {"id":"s_work_han_thu_38_126","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「朱圉山在漢陽冀縣南。太華即今華陰山。」","sentenceOrder":126},
  {"id":"s_work_han_thu_38_127","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「熊耳在陝東。外方在潁川故縣，即崇高也。桐柏在平氏東南。倍尾在安陸東北。言四山相連也。倍讀曰陪。」","sentenceOrder":127},
  {"id":"s_work_han_thu_38_128","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「嶓冢山在梁州南。此荊山在南郡臨沮東北。嶓音波。」","sentenceOrder":128},
  {"id":"s_work_han_thu_38_129","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「內方在荊州。大別在廬江安豐也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_38_130","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「崏山在蜀郡湔氐西。衡山在長沙湘南之東南。崏山，江所出。衡山，江所經。」","sentenceOrder":130},
  {"id":"s_work_han_thu_38_131","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕師古曰：「敷淺原，一名（博）〔傅〕陽山，在豫章歷陵南。」","sentenceOrder":131},
  {"id":"s_work_han_thu_38_132","chapterId":"ch_work_han_thu_38","textTraditional":"道弱水，至于合藜，餘波入于流沙。〔一〕道黑水，至于三危，入于南海。〔二〕道河積石，至于龍門，〔三〕南至于華陰，東至于厎柱，〔四〕又東至于盟津，〔五〕東過洛汭，至于大伾，〔六〕北過降水，至于大陸，〔七〕又北播為九河，〔八〕同為逆河，入于海。〔九〕嶓冢道漾，東流為漢，〔一０〕又東為滄浪之水，〔一一〕過三澨，至于大別，〔一二〕南入于江，〔一三〕東匯澤為彭蠡〔一四〕，東為北江，入于海。〔一五〕崏山道江，東別為沱，〔一六〕又東至于醴，〔一七〕過九江，至于東陵，〔一八〕東迆北會于匯，〔一九〕東為中江，入于海。〔二０〕道沇水，東流為泲，〔二一〕入于河，軼為滎，〔二二〕東出于陶丘北，〔二三〕又東至于荷〔二四〕，又東北會於汶，〔二五〕又北東入于海。〔二六〕道淮自桐柏，東會于泗、沂，東入于海。道渭自鳥鼠同穴，東會于酆，又東至于涇，又東過漆、沮，入于河。道洛自熊耳，東北會于澗、瀍，又東會于伊，又東北入于河。","sentenceOrder":132},
  {"id":"s_work_han_thu_38_133","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「合藜山在酒泉。流沙在敦煌西。」","sentenceOrder":133},
  {"id":"s_work_han_thu_38_134","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「黑水出張掖雞山，南流至敦煌，過三危山，又南流而入于南海。」","sentenceOrder":134},
  {"id":"s_work_han_thu_38_135","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「積石山在河關西羌中。龍門山在夏陽北。言治河施功，自積石起，鑿山穿地，以通其流，至龍門山也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_38_136","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「自龍門南流以至華陰，又折而東經厎柱。」","sentenceOrder":136},
  {"id":"s_work_han_thu_38_137","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「盟讀曰孟。孟津在洛陽之北，都道所湊，故號孟津。孟，長大也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_38_138","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「洛汭，洛入河處，蓋今所謂洛口也。山再重曰伾。大伾山在成皋。伾音平鄙反。」","sentenceOrder":138},
  {"id":"s_work_han_thu_38_139","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「降水在信都。大陸在鉅鹿。」","sentenceOrder":139},
  {"id":"s_work_han_thu_38_140","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「播，布也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_38_141","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「同，合也。九河又合而為一，名為逆河，言相迎受也。海即渤海是也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_38_142","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「漾水出隴西氐道，東流過武關山南為漢。禹治漾水自嶓冢始也。漾音恙。」","sentenceOrder":142},
  {"id":"s_work_han_thu_38_143","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕師古曰：「出荊山東南流為滄浪之水，即漁父所歌者也。浪音琅。」","sentenceOrder":143},
  {"id":"s_work_han_thu_38_144","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕師古曰：「三澨水在江夏竟陵。澨音筮。」","sentenceOrder":144},
  {"id":"s_work_han_thu_38_145","chapterId":"ch_work_han_thu_38","textTraditional":"〔一三〕師古曰：「觸大別山而南入江也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_38_146","chapterId":"ch_work_han_thu_38","textTraditional":"〔一四〕師古曰：「匯，迴也，又東迴而為彭蠡澤也。匯音胡賄反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_38_147","chapterId":"ch_work_han_thu_38","textTraditional":"〔一五〕師古曰：「自彭蠡江分為三，遂為北江而入海。」","sentenceOrder":147},
  {"id":"s_work_han_thu_38_148","chapterId":"ch_work_han_thu_38","textTraditional":"〔一六〕師古曰：「別而出也，江東南流，沱東行也。沱音徒何反。」","sentenceOrder":148},
  {"id":"s_work_han_thu_38_149","chapterId":"ch_work_han_thu_38","textTraditional":"〔一七〕師古曰：「醴水在荊州。」","sentenceOrder":149},
  {"id":"s_work_han_thu_38_150","chapterId":"ch_work_han_thu_38","textTraditional":"〔一八〕師古曰：「東陵，地名。」","sentenceOrder":150},
  {"id":"s_work_han_thu_38_151","chapterId":"ch_work_han_thu_38","textTraditional":"〔一九〕師古曰：「迆，溢也。東溢分流，都共北會彭蠡也。迆音弋爾反。」","sentenceOrder":151},
  {"id":"s_work_han_thu_38_152","chapterId":"ch_work_han_thu_38","textTraditional":"〔二０〕師古曰：「亦自彭蠡出。」","sentenceOrder":152},
  {"id":"s_work_han_thu_38_153","chapterId":"ch_work_han_thu_38","textTraditional":"〔二一〕師古曰：「泉出王屋山，名為沇，流去乃為泲也。沇音弋臠反。」","sentenceOrder":153},
  {"id":"s_work_han_thu_38_154","chapterId":"ch_work_han_thu_38","textTraditional":"〔二二〕師古曰：「軼與溢同。言濟水入河，並流而南，截河，又並流溢出，乃為滎澤。一曰軼，過也，音逸。」","sentenceOrder":154},
  {"id":"s_work_han_thu_38_155","chapterId":"ch_work_han_thu_38","textTraditional":"〔二三〕師古曰：「陶丘，丘再重也，在濟陰定陶西南。」","sentenceOrder":155},
  {"id":"s_work_han_thu_38_156","chapterId":"ch_work_han_thu_38","textTraditional":"〔二四〕師古曰：「即荷澤。」","sentenceOrder":156},
  {"id":"s_work_han_thu_38_157","chapterId":"ch_work_han_thu_38","textTraditional":"〔二五〕師古曰：「濟與汶合。」","sentenceOrder":157},
  {"id":"s_work_han_thu_38_158","chapterId":"ch_work_han_thu_38","textTraditional":"〔二六〕師古曰：「北折而東也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_38_159","chapterId":"ch_work_han_thu_38","textTraditional":"九州逌同，〔一〕四奧既宅，〔二〕九山刊旅，〔三〕九川滌原，〔四〕九澤既陂，〔五〕四海會同。〔六〕六府孔修，〔七〕庶土交正，厎慎財賦，〔八〕咸則三壤，成賦中國。〔九〕錫土姓：「祗台德先，不距朕行。」〔一０〕","sentenceOrder":159},
  {"id":"s_work_han_thu_38_160","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「各以其所而同法。」","sentenceOrder":160},
  {"id":"s_work_han_thu_38_161","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「奧讀曰墺，謂土之可居者也。宅亦居也。言四方之土已可定居也。墺音於六反。」","sentenceOrder":161},
  {"id":"s_work_han_thu_38_162","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「九州之山皆已刊木通道而旅祭也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_38_163","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「九州泉源皆已清滌無壅塞。」","sentenceOrder":163},
  {"id":"s_work_han_thu_38_164","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「九州陂澤皆已遏障無決溢。」","sentenceOrder":164},
  {"id":"s_work_han_thu_38_165","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「四海之內皆同會京師。」","sentenceOrder":165},
  {"id":"s_work_han_thu_38_166","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「水、火、金、木、土、穀皆甚治。」","sentenceOrder":166},
  {"id":"s_work_han_thu_38_167","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「言眾土各以其所出，交易有無，而不失正，致慎貨財，以供貢賦。」","sentenceOrder":167},
  {"id":"s_work_han_thu_38_168","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「言皆隨其土田上中下三品，而成其賦於中國也。中國，京師也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_38_169","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「台，養也。言封諸侯，賜之土田，因以為姓。所敬養者，惟德為先，故無距我之行也。台音怡。」","sentenceOrder":169},
  {"id":"s_work_han_thu_38_170","chapterId":"ch_work_han_thu_38","textTraditional":"五百里甸服：〔一〕百里賦內總，〔二〕二百里（納）〔內〕銍，〔三〕三百里內戛服，〔四〕四百里粟，五百里米。〔五〕五百里侯服：〔六〕百里采，〔七〕二百里男國，〔八〕三百里諸侯。〔九〕五百里綏服：〔一０〕三百里揆文教，〔一一〕二百里奮武衛〔一二〕。五百里要服：〔一三〕三百里夷，〔一四〕二百里蔡。〔一五〕五百里荒服：〔一六〕三百里蠻，〔一七〕二百里流。〔一八〕東漸于海，西被于流沙，朔、南臮，聲教訖于四海。〔一九〕","sentenceOrder":170},
  {"id":"s_work_han_thu_38_171","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「規方千里，最近王城者為甸服，則四面五百里也。甸之為言田也，主為王者治田。」","sentenceOrder":171},
  {"id":"s_work_han_thu_38_172","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「自此以下，說甸服之內，以差言之也。總，禾稿摠入也。內讀曰納。下皆類此。」","sentenceOrder":172},
  {"id":"s_work_han_thu_38_173","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「銍謂所刈，即禾穗也。銍音窒。」","sentenceOrder":173},
  {"id":"s_work_han_thu_38_174","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「戛，稿也。言服者，謂有役則服之耳。戛音工黠反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_38_175","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「精者納少，麤者納多。」","sentenceOrder":175},
  {"id":"s_work_han_thu_38_176","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「此次甸服之外方五百里也。侯，候也，主斥候而服事也。」","sentenceOrder":176},
  {"id":"s_work_han_thu_38_177","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「又說侯服內之差次也。采，事也，王事則供之，不主一也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_38_178","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「男之言任，任王事者。」","sentenceOrder":178},
  {"id":"s_work_han_thu_38_179","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「三百里同主斥候，故合而言之為一等。」","sentenceOrder":179},
  {"id":"s_work_han_thu_38_180","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「此又次侯服外之五百里也。綏，安也，言其安服王者政教。」","sentenceOrder":180},
  {"id":"s_work_han_thu_38_181","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕師古曰：「揆度王者文教而行之也。三百里皆同。」","sentenceOrder":181},
  {"id":"s_work_han_thu_38_182","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕師古曰：「奮其武力以衛王者。二百里皆同。」","sentenceOrder":182},
  {"id":"s_work_han_thu_38_183","chapterId":"ch_work_han_thu_38","textTraditional":"〔一三〕師古曰：「此又次綏服外之五百里也。要，以文教要來之也。要音一遙反。」","sentenceOrder":183},
  {"id":"s_work_han_thu_38_184","chapterId":"ch_work_han_thu_38","textTraditional":"〔一四〕師古曰：「夷，易也，言行平易之法也。三百里皆同。」","sentenceOrder":184},
  {"id":"s_work_han_thu_38_185","chapterId":"ch_work_han_thu_38","textTraditional":"〔一五〕師古曰：「蔡，法也，遵刑法而已。二百里皆同。」","sentenceOrder":185},
  {"id":"s_work_han_thu_38_186","chapterId":"ch_work_han_thu_38","textTraditional":"〔一六〕師古曰：「又次要服外五百里，此五服之最在外者也。荒，言其荒忽，各因本俗。」","sentenceOrder":186},
  {"id":"s_work_han_thu_38_187","chapterId":"ch_work_han_thu_38","textTraditional":"〔一七〕師古曰：「蠻謂以文德蠻幕而覆之。三百里皆同。」","sentenceOrder":187},
  {"id":"s_work_han_thu_38_188","chapterId":"ch_work_han_thu_38","textTraditional":"〔一八〕師古曰：「任其流移，不考詰也。二百里皆同。」","sentenceOrder":188},
  {"id":"s_work_han_thu_38_189","chapterId":"ch_work_han_thu_38","textTraditional":"〔一九〕師古曰：「漸，入也。被，加也。朔，北方也。訖，盡也。言東入于海，西加流沙，北方南方皆及，聲教盡於四海也。一曰，漸，浸；臮，及也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_38_190","chapterId":"ch_work_han_thu_38","textTraditional":"禹錫玄圭，告厥成功。〔一〕","sentenceOrder":190},
  {"id":"s_work_han_thu_38_191","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「玄，天色也。堯以禹治水功成，故賜玄圭以表之也。自此以上，皆禹貢之文。」","sentenceOrder":191},
  {"id":"s_work_han_thu_38_192","chapterId":"ch_work_han_thu_38","textTraditional":"後受禪於虞，為夏后氏。","sentenceOrder":192},
  {"id":"s_work_han_thu_38_193","chapterId":"ch_work_han_thu_38","textTraditional":"殷因於夏，亡所變改。周既克殷，監於二代而損益之，定官分職，改禹徐、梁二州合之於雍、青，〔一〕分冀州之地以為幽、并。故周官有職方氏，〔二〕掌天下之地，辯九州之國。","sentenceOrder":193},
  {"id":"s_work_han_thu_38_194","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「省徐州以入青州，并梁州以合雍州。」","sentenceOrder":194},
  {"id":"s_work_han_thu_38_195","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「夏官之屬也。職，主也，主四方之土地。」","sentenceOrder":195},
  {"id":"s_work_han_thu_38_196","chapterId":"ch_work_han_thu_38","textTraditional":"東南曰揚州：其山曰會稽，〔一〕藪曰具區，〔二〕川曰三江，寖曰五湖；〔三〕其利金、錫、竹箭；民二男五女；畜宜鳥獸，〔四〕穀宜稻。","sentenceOrder":196},
  {"id":"s_work_han_thu_38_197","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「在山陰縣。」","sentenceOrder":197},
  {"id":"s_work_han_thu_38_198","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「藪，大澤也。具區在吳也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_38_199","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「寖，古浸字也。川，水之通流者也。浸謂引以灌溉者。五湖在吳。」","sentenceOrder":199},
  {"id":"s_work_han_thu_38_200","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「鳥，孔翠之屬。獸，犀象之屬。」","sentenceOrder":200},
  {"id":"s_work_han_thu_38_201","chapterId":"ch_work_han_thu_38","textTraditional":"正南曰荊州：其山曰衡，藪曰雲夢，川曰江、漢，寖曰潁、湛；〔一〕其利丹、銀、齒、革；民一男二女；畜及穀宜，與揚州同。","sentenceOrder":201},
  {"id":"s_work_han_thu_38_202","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「潁水出陽城陽乾山，宜屬豫州。許慎又云『湛水，豫州浸』。並未詳也。湛音直林反，又音直減反。」","sentenceOrder":202},
  {"id":"s_work_han_thu_38_203","chapterId":"ch_work_han_thu_38","textTraditional":"河南曰豫州：其山曰華，〔一〕藪曰圃田，〔二〕川曰滎、雒，{穴浸}曰波、溠；〔三〕其利林、漆、絲枲；民二男三女；畜宜六擾〔四〕，其穀宜五種。〔五〕","sentenceOrder":203},
  {"id":"s_work_han_thu_38_204","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「即華陰之華山也。連延東出，故屬豫州。」","sentenceOrder":204},
  {"id":"s_work_han_thu_38_205","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「在中牟。」","sentenceOrder":205},
  {"id":"s_work_han_thu_38_206","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「滎即沇水所溢者也。波即上禹貢所云滎波者也。溠水在楚，亦不當為豫州浸也。溠音莊亞反。」","sentenceOrder":206},
  {"id":"s_work_han_thu_38_207","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「馬、牛、羊、豕、犬、雞也。謂之擾者，言人所馴養也。擾音人沼反。」","sentenceOrder":207},
  {"id":"s_work_han_thu_38_208","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「黍、稷、菽、麥、稻。」","sentenceOrder":208},
  {"id":"s_work_han_thu_38_209","chapterId":"ch_work_han_thu_38","textTraditional":"正東曰青州：其山曰沂，藪曰孟諸，〔一〕川曰淮、泗，寖曰沂、沭；〔二〕其利蒲、魚；民二男三女；其畜宜雞、狗，穀宜稻、麥。","sentenceOrder":209},
  {"id":"s_work_han_thu_38_210","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「沂山在蓋縣，即沂水所出也。孟諸，即盟豬也。」","sentenceOrder":210},
  {"id":"s_work_han_thu_38_211","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「沭水出東莞，音術。」","sentenceOrder":211},
  {"id":"s_work_han_thu_38_212","chapterId":"ch_work_han_thu_38","textTraditional":"河東曰兗州：其山曰岱，藪曰泰野，〔一〕其川曰河、泲，浸曰盧、濰；〔二〕其利蒲、魚；民二男三女；其畜宜六擾，穀宜四種。〔三〕","sentenceOrder":212},
  {"id":"s_work_han_thu_38_213","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「即大野。」","sentenceOrder":213},
  {"id":"s_work_han_thu_38_214","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「盧水在濟北盧縣。鄭康成讀曰雷，非也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_38_215","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「馬、牛、羊、豕、犬、雞，黍、稷、稻、麥也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_38_216","chapterId":"ch_work_han_thu_38","textTraditional":"正西曰雍州：其山曰嶽，〔一〕藪曰弦蒲，〔二〕川曰涇、汭，〔三〕其浸曰渭、洛；〔四〕其利玉、石；其民三男二女；畜宜牛、馬，穀宜黍、稷。","sentenceOrder":216},
  {"id":"s_work_han_thu_38_217","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「即吳嶽也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_38_218","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「在汧縣。」","sentenceOrder":218},
  {"id":"s_work_han_thu_38_219","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「汭在豳地。詩大雅公劉之篇曰『汭鞠之即』。」","sentenceOrder":219},
  {"id":"s_work_han_thu_38_220","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「洛即漆、沮也，在馮翊。」","sentenceOrder":220},
  {"id":"s_work_han_thu_38_221","chapterId":"ch_work_han_thu_38","textTraditional":"東北曰幽州：其山曰醫無閭，〔一〕藪曰豯養，〔二〕川曰河、泲，浸曰菑、時；〔三〕其利魚、鹽；民一男三女；畜宜四擾，〔四〕穀宜三種。〔五〕","sentenceOrder":221},
  {"id":"s_work_han_thu_38_222","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「在遼東。」","sentenceOrder":222},
  {"id":"s_work_han_thu_38_223","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「在長廣。」","sentenceOrder":223},
  {"id":"s_work_han_thu_38_224","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「菑出萊蕪。時水出般陽。」","sentenceOrder":224},
  {"id":"s_work_han_thu_38_225","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「馬、牛、羊、豕。」","sentenceOrder":225},
  {"id":"s_work_han_thu_38_226","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「黍、稷、稻。」","sentenceOrder":226},
  {"id":"s_work_han_thu_38_227","chapterId":"ch_work_han_thu_38","textTraditional":"河內曰冀州：其山曰霍，〔一〕藪曰揚紆，〔二〕川曰漳，浸曰汾、潞；〔三〕其利松、柏；民五男三女；畜宜牛、羊，穀宜黍、稷。","sentenceOrder":227},
  {"id":"s_work_han_thu_38_228","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「在平陽永安縣東北。」","sentenceOrder":228},
  {"id":"s_work_han_thu_38_229","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「爾雅曰『秦有揚紆』，而此以為冀州，未詳其義及所在。」","sentenceOrder":229},
  {"id":"s_work_han_thu_38_230","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「漳水出上黨長子。汾水出汾陽北山。潞出歸德。」","sentenceOrder":230},
  {"id":"s_work_han_thu_38_231","chapterId":"ch_work_han_thu_38","textTraditional":"正北曰并州：其山曰恆山，藪曰昭餘祁，〔一〕川曰虖池、嘔夷，浸曰淶、易；〔二〕其利布帛；民二男三女；畜宜五擾，〔三〕穀宜五種。","sentenceOrder":231},
  {"id":"s_work_han_thu_38_232","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「在太原鄔縣。鄔音一戶反，又音於庶反。」","sentenceOrder":232},
  {"id":"s_work_han_thu_38_233","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「虖池出鹵城。嘔夷出平舒。淶出廣昌。易出故安。虖音呼。池音徒河反。嘔音於侯反。」","sentenceOrder":233},
  {"id":"s_work_han_thu_38_234","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「馬、牛、羊、犬、豕。」","sentenceOrder":234},
  {"id":"s_work_han_thu_38_235","chapterId":"ch_work_han_thu_38","textTraditional":"而保章氏掌天文，以星土辯九州之地，所封封域皆有分星，以視吉凶。〔一〕","sentenceOrder":235},
  {"id":"s_work_han_thu_38_236","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「保章氏，春官之屬也。保，守也，言守天文之職也。分音扶問反。」","sentenceOrder":236},
  {"id":"s_work_han_thu_38_237","chapterId":"ch_work_han_thu_38","textTraditional":"周爵五等，而土三等：公、侯百里，伯七十里，子、男五十里。不滿為附庸，蓋千八百國。而太昊、黃帝之後，唐、虞侯伯猶存，帝王圖籍相踵而可知。周室既衰，禮樂征伐自諸侯出，轉相吞滅，數百年間，列國秏盡。〔一〕至春秋時，尚有數十國，五伯迭興，總其盟會。〔二〕陵夷至於戰國，天下分而為七，〔三〕合從連衡，經數十年。秦遂并兼四海。以為周制微弱，終為諸侯所喪，故不立尺土之封，分天下為郡縣，盪滅前聖之苗裔，靡有孑遺者矣。","sentenceOrder":237},
  {"id":"s_work_han_thu_38_238","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「秏，滅也，音呼到反。」","sentenceOrder":238},
  {"id":"s_work_han_thu_38_239","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「此五伯謂齊桓、宋襄、晉文、秦穆、楚莊也。迭，互也。伯讀曰霸。迭音徒結反。」","sentenceOrder":239},
  {"id":"s_work_han_thu_38_240","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「謂秦、韓、魏、趙、燕、齊、楚也。」","sentenceOrder":240},
  {"id":"s_work_han_thu_38_241","chapterId":"ch_work_han_thu_38","textTraditional":"漢興，因秦制度，崇恩德，行簡易，以撫海內。至武帝攘卻胡、越，開地斥境，南置交阯，北置朔方之州，〔一〕兼徐、梁、幽、并夏、周之制，改雍曰涼，改梁曰益，凡十三（郡）〔部〕，置刺史。先王之跡既遠，地名又數改易，〔二〕是以采獲舊聞，考跡詩書，推表山川，以綴禹貢、周官、春秋，下及戰國、秦、漢焉。〔三〕","sentenceOrder":241},
  {"id":"s_work_han_thu_38_242","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「胡廣記云，漢既定南越之地，置交阯刺史，別於諸州，令持節治蒼梧，分雍州置朔方刺史。」","sentenceOrder":242},
  {"id":"s_work_han_thu_38_243","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「數音所角反。」","sentenceOrder":243},
  {"id":"s_work_han_thu_38_244","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「中古以來，說地理者多矣，或解釋經典，或撰述方志，競為新異，妄有穿鑿，安處互會，頗失其真。後之學者，因而祖述，曾不考其謬論，莫能尋其根本。今並不錄，蓋無尤焉。」","sentenceOrder":244},
  {"id":"s_work_han_thu_38_245","chapterId":"ch_work_han_thu_38","textTraditional":"京兆尹，故秦內史，高帝元年屬塞國，二年更為渭南郡，九年罷，復為內史。武帝建元六年分為右內史，太初元年更為京兆尹。元始二年戶十九萬五千七百二，口六十八萬二千四百六十八。〔一〕縣十二：長安，高帝五年置。惠帝元年初城，六年成。戶八萬八百，口二十四萬六千二百。王莽曰常安。〔二〕新豐，驪山在南，故驪戎國。秦曰驪邑。高祖七年置。〔三〕船司空，莽曰船利。〔四〕藍田，山出美玉，有虎候山祠，秦孝公置也。華陰，故陰晉，秦惠文王五年更名寧秦，高帝八年更名華陰。太華山在南，有祠，豫州山。集靈宮，武帝起。莽曰華壇也。鄭，周宣王弟鄭桓公邑。有鐵官。〔五〕湖，有周天子祠二所。故曰胡，武帝建元年更名湖。下邽，〔六〕南陵，文帝七年置。沂水出藍田谷，北至霸陵入霸水。霸水亦出藍田谷，北入渭。（師）古曰茲水，秦穆公更名以章霸功，視子孫。〔七〕奉明，宣帝置也。霸陵，故芷陽，文帝更名。莽曰水章也。杜陵。故杜伯國，宣帝更名。有周右將軍杜主祠四所。莽曰饒安也。","sentenceOrder":245},
  {"id":"s_work_han_thu_38_246","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「漢之戶口當元始時最為殷盛，故志舉之以為數也。後皆類此。」","sentenceOrder":246},
  {"id":"s_work_han_thu_38_247","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「王莽篡位，改漢郡縣名，普易之也。下皆類此。」","sentenceOrder":247},
  {"id":"s_work_han_thu_38_248","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　應劭曰：「太上皇思東歸，於是高祖改築城寺街里以象豐，徙豐民以實之，故號新豐。」","sentenceOrder":248},
  {"id":"s_work_han_thu_38_249","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　服虔曰：「縣名。」師古曰：「本主船之官，遂以為縣。」","sentenceOrder":249},
  {"id":"s_work_han_thu_38_250","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「宣王母弟友所封也。其子與平王東遷，更稱新鄭。」臣瓚曰：「周自穆王以下都於西鄭，不得以封桓公也。初桓公為周司徒，王室將亂，故謀於史伯而寄帑與賄於虢、會之間。幽王既敗，二年而滅會，四年而滅虢，居於鄭父之丘，是以為鄭桓公，無封京兆之文也。」師古曰：「春秋外傳云：『幽王既敗，鄭桓公死之，其子武公與平王東遷。』故左氏傳云：『我周之東遷，晉、鄭焉依。』又鄭莊公云『我先君新邑於此』，蓋道新鄭也。穆王以下無都西鄭之事，瓚說非也。會音工外反。」","sentenceOrder":250},
  {"id":"s_work_han_thu_38_251","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　應劭曰：「秦武公伐邽戎，置有上邽，故加下。」師古曰：「邽音圭，取邽戎之人而來為此縣。」","sentenceOrder":251},
  {"id":"s_work_han_thu_38_252","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　〔師古曰〕：「沂音先歷反。視讀曰示。」","sentenceOrder":252},
  {"id":"s_work_han_thu_38_253","chapterId":"ch_work_han_thu_38","textTraditional":"左馮翊，故秦內史，高帝元年屬塞國，二年更名河上郡，九年罷，復為內史。武帝建元六年分為左內史，太初元年更名左馮翊。戶二十三萬五千一百一，口九十一萬七千八百二十二。縣二十四：高陵，左輔都尉治。莽曰千春。櫟陽，秦獻公自雍徙。莽曰師亭。〔一〕翟道，莽曰渙。池陽，惠帝四年置。巀嶭山在北。〔二〕夏陽，故少梁，秦惠文王十一年更名。禹貢梁山在西北，龍門山在北。有鐵官。莽曰冀亭。衙，莽曰達昌。〔三〕粟邑，莽曰粟城。谷口，九嵕山在西。有天齊公、五床山、僊人、五帝祠四所。莽曰谷喙。〔四〕蓮勺，〔五〕鄜，莽曰脩令。〔六〕頻陽，秦厲公置。〔七〕臨晉，故大荔，秦獲之，更名。有河水祠。芮鄉，故芮國。莽曰監晉。〔八〕重泉，莽曰調泉。郃陽，〔九〕祋祤，景帝二年置。〔一０〕武城，莽曰桓城。〔一一〕沈陽，莽曰制昌。褱德，禹貢北條荊山在南，下有彊梁原。洛水東南入渭，雍州浸。莽曰德驩。〔一二〕徵，莽曰氾愛。〔一三〕雲陵，昭帝置也。萬年，高帝置。莽曰異赤。〔一四〕長陵，高帝置。戶五萬五十七，口十七萬九千四百六十九。莽曰長平。陽陵，故弋陽，景帝更名。莽曰渭陽。雲陽。有休屠、金人及徑路神祠三所，越巫（暂缺F603）（暂缺F602）祠三所。〔一五〕","sentenceOrder":253},
  {"id":"s_work_han_thu_38_254","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　如淳曰：「櫟音藥。」","sentenceOrder":254},
  {"id":"s_work_han_thu_38_255","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「在池水之陽。」師古曰：「巀嶭，即今俗所呼嵯峨山是也，音巀齧。音才葛反，又音五葛反。」","sentenceOrder":255},
  {"id":"s_work_han_thu_38_256","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　如淳曰：「衙音牙。」師古曰：「即春秋所云『秦晉戰于彭衙』。」","sentenceOrder":256},
  {"id":"s_work_han_thu_38_257","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「嵕音子公反，又音子孔反。喙音許穢反。」","sentenceOrder":257},
  {"id":"s_work_han_thu_38_258","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　如淳曰：「音輦酌。」","sentenceOrder":258},
  {"id":"s_work_han_thu_38_259","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　孟康曰：「音敷。」","sentenceOrder":259},
  {"id":"s_work_han_thu_38_260","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　應劭曰：「在頻水之陽。」","sentenceOrder":260},
  {"id":"s_work_han_thu_38_261","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　應劭曰：「臨晉水，故曰臨晉。」臣瓚曰：「晉水在河之間，此縣在河之西，不得云臨晉水也。舊說曰，秦築高壘以臨晉國，故曰臨晉也。」師古曰：「瓚說是也。說者或以為魏文侯伐秦始置臨晉，非也。文侯重城之耳，豈始置乎！」","sentenceOrder":261},
  {"id":"s_work_han_thu_38_262","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　應劭曰：「在郃水之陽也。」師古曰：「音合。即大雅大明之詩所謂『在洽之陽』。」","sentenceOrder":262},
  {"id":"s_work_han_thu_38_263","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「祋音丁活反，又音丁外反。祤音詡。」","sentenceOrder":263},
  {"id":"s_work_han_thu_38_264","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕師古曰：「即左氏傳所云『（伐秦）〔秦伐〕晉取武城』者也。」","sentenceOrder":264},
  {"id":"s_work_han_thu_38_265","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕師古曰：「褱亦懷字。」","sentenceOrder":265},
  {"id":"s_work_han_thu_38_266","chapterId":"ch_work_han_thu_38","textTraditional":"〔一三〕師古曰：「徵音懲，即今之澄城縣是也。左傳所云『取北徵』，謂此地耳，而杜元凱未詳其處也。」","sentenceOrder":266},
  {"id":"s_work_han_thu_38_267","chapterId":"ch_work_han_thu_38","textTraditional":"〔一四〕師古曰：「三輔黃圖云太上皇葬櫟陽北原，起萬年陵是也。」","sentenceOrder":267},
  {"id":"s_work_han_thu_38_268","chapterId":"ch_work_han_thu_38","textTraditional":"〔一五〕孟康曰：「（暂缺F603）音辜磔之辜，越人祠也。（暂缺F602）音穰。休音許虯反。屠音除。」","sentenceOrder":268},
  {"id":"s_work_han_thu_38_269","chapterId":"ch_work_han_thu_38","textTraditional":"右扶風，故秦內史，高帝元年屬雍國，二年更為中地郡。九年罷，復為內史。武帝建元六年分為右內史，太初元年更名主爵都尉為右扶風。〔一〕戶二十一萬六千三百七十七，口八十三萬六千七十。縣二十一：渭城，故咸陽，高帝元年更名新城，七年罷，屬長安。武帝元鼎三年更名渭城。有蘭池宮。莽曰京城。槐里，周曰犬丘，懿王都之。秦更名廢丘。高祖三年更名。有黃山宮，孝惠二年起。莽曰槐治。鄠，古國。有扈谷亭。扈，夏啟所伐。酆水出東南，又有潏水，皆北過上林苑入渭。有萯陽宮，秦文王起。〔二〕盩厔，有長楊宮，有射熊館，秦昭王起。靈軹渠，武帝穿也。斄，周后稷所封。〔三〕郁夷，詩「周道郁夷」。有汧水祠。莽曰郁平。〔四〕美陽，禹貢岐山在西北。中水鄉，周大王所邑。有高泉宮，秦宣太后起也。郿，成國渠首受渭，東北至上林入蒙籠渠。右輔都尉治。〔五〕雍，秦惠公都之。有五畤，太昊、黃帝以下祠三百三所。橐泉宮，孝公起。祈年宮，惠公起。棫陽宮，昭王起。有鐵官。〔六〕漆，水在縣西。有鐵官。莽曰漆治。栒邑，有豳鄉，詩豳國，公劉所都。〔七〕隃麋，有黃帝子祠。莽曰扶亭。〔八〕陳倉，有上公、明星、黃帝孫、舜妻（盲）〔育〕冢祠。有羽陽宮，秦武王起也。杜陽，杜水南入渭。〔詩曰「自杜」〕莽曰通杜。〔九〕汧，吳山在西，古文以為汧山。雍州山。北有蒲谷鄉弦中谷，雍州弦蒲藪。汧水出西北，入渭。芮水出西北，東入涇。詩芮（阨）〔〈亻母〉〕，雍州川也。〔一０〕好畤，垝山在東。有梁山宮，秦始皇起。莽曰好邑。〔一一〕虢，有黃帝子、周文武祠。虢宮，秦宣太后起也。安陵，惠帝置。莽曰嘉平。〔一二〕茂陵，武帝置。戶六萬一千八十七，口二十七萬七千二百七十七。莽曰宣城。〔一三〕平陵，昭帝置。莽曰廣利。武功，太壹山，古文以為終南。垂山，古文以為敦物。皆在縣東。斜水出衙領山北，至郿入渭。褒水亦出衙領，至南鄭入沔。有垂山、斜水、（淮）〔褒〕水祠三所。莽曰新光。〔一四〕","sentenceOrder":269},
  {"id":"s_work_han_thu_38_270","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「主爵都尉，本秦之主爵中尉，掌列侯，至太初元年更名右扶風，而治於內史右地。故此志追書建元六年分為右內史，又云更名主爵都尉為右扶風。」","sentenceOrder":270},
  {"id":"s_work_han_thu_38_271","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「潏音決。萯音倍。」","sentenceOrder":271},
  {"id":"s_work_han_thu_38_272","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「讀與邰同，音（（暂缺F600））〔胎〕。」","sentenceOrder":272},
  {"id":"s_work_han_thu_38_273","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「小雅四牡之詩曰『四牡騑騑，周道倭遲』。韓詩作郁夷字，言使臣乘馬行於此道。」","sentenceOrder":273},
  {"id":"s_work_han_thu_38_274","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「郿音媚。」","sentenceOrder":274},
  {"id":"s_work_han_thu_38_275","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　應劭曰：「四面積高曰雍。」師古曰：「棫音域。」","sentenceOrder":275},
  {"id":"s_work_han_thu_38_276","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　應劭曰：「左氏傳曰『畢、原、酆、郇，文之昭也』。郇侯、賈伯伐晉是也。」臣瓚曰：「汲郡古文『晉武公滅荀，以賜大夫原氏黯，是為荀叔』。又云『文公城荀』。然則荀當在晉之境內，不得在扶風界也。今河東有荀城，古荀國。」師古曰：「瓚說是也。此栒讀與荀同，自別邑耳，非伐晉者。」","sentenceOrder":276},
  {"id":"s_work_han_thu_38_277","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「鄃音踰。」","sentenceOrder":277},
  {"id":"s_work_han_thu_38_278","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「大雅綿之詩曰『人之初生，自土、漆、沮』，齊詩作『自杜』，言公劉避狄而來居杜與漆、沮之地。」","sentenceOrder":278},
  {"id":"s_work_han_thu_38_279","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「（阨）〔〈亻母〉〕讀與鞠同。大雅公劉之詩曰『止旅乃密，芮鞠之即』，韓詩作芮（阨）〔〈亻母〉〕。言公劉止其軍旅，欲使安靜，乃就芮（阨）〔〈亻母〉〕之間耳。」","sentenceOrder":279},
  {"id":"s_work_han_thu_38_280","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕師古曰：「垝音丘毀反。」","sentenceOrder":280},
  {"id":"s_work_han_thu_38_281","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕師古曰：「闞駰以為本周之程邑也。」","sentenceOrder":281},
  {"id":"s_work_han_thu_38_282","chapterId":"ch_work_han_thu_38","textTraditional":"〔一三〕師古曰：「黃圖云本槐里之茂鄉。」","sentenceOrder":282},
  {"id":"s_work_han_thu_38_283","chapterId":"ch_work_han_thu_38","textTraditional":"〔一四〕師古曰：「斜音弋奢反。衙音牙。」","sentenceOrder":283},
  {"id":"s_work_han_thu_38_284","chapterId":"ch_work_han_thu_38","textTraditional":"弘農郡，武帝元鼎四年置。莽曰右隊。戶十一萬八千九十一，口四十七萬五千九百五十四。有鐵官，在黽池。縣十一：弘農，故秦函谷關。衙山領下谷，爥水所出，北入河。盧氏，熊耳山在東。伊水出，東北入雒，過郡一，行四百五十里。又有育水，南至順陽入沔。又有洱水，東南至魯陽，亦入沔。皆過郡二，行六百里。莽曰昌富。〔一〕陝，故虢國。有焦城，故焦國。北虢在大陽，東虢在滎陽，西虢在雍州。莽曰黃眉。宜陽，在黽池有鐵官也。黽池，高帝八年復黽池中鄉民。景帝中二年初城，徙萬家為縣。穀水出穀陽谷，東北至穀城入雒。莽曰陝亭。〔二〕丹水，水出上雒冢領山，東至析入鈞。密陽鄉，故商密也。〔三〕新安，禹貢澗水在東，南入雒。商，秦相衛鞅邑也。析，黃水出黃谷，鞠水出析谷，俱東至酈入湍水。莽曰君亭。〔四〕陸渾，春秋遷陸渾戎於此。有關。〔五〕上雒。禹貢雒水出冢領山，東北至鞏入河，過郡二，行千七十里，豫州川。又有甲水，出秦領山，東南至鍚入沔，過郡三，行五百七十里。熊耳獲輿山在東北。〔六〕","sentenceOrder":284},
  {"id":"s_work_han_thu_38_285","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「洱音耳。」","sentenceOrder":285},
  {"id":"s_work_han_thu_38_286","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「黽音莫踐反，又音莫忍反。」","sentenceOrder":286},
  {"id":"s_work_han_thu_38_287","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「鈞亦水名也，音均。」","sentenceOrder":287},
  {"id":"s_work_han_thu_38_288","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「析音先歷反。鞠水即今所謂菊潭也。酈音持益反。湍音專。」","sentenceOrder":288},
  {"id":"s_work_han_thu_38_289","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「渾音胡昆反。」","sentenceOrder":289},
  {"id":"s_work_han_thu_38_290","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「鍚音陽。」","sentenceOrder":290},
  {"id":"s_work_han_thu_38_291","chapterId":"ch_work_han_thu_38","textTraditional":"河東郡，秦置。莽曰兆陽。有根倉、溼倉。戶二十三萬六千八百九十六，口九十六萬二千九百一十二。縣二十四：安邑，巫咸山在南，鹽池在西南。魏絳自魏徙此，至惠王徙大梁。有鐵官、鹽官。莽曰河東。大陽，吳山在西，上有吳城，周武王封太伯後於此，是為虞公，為晉所滅。有天子廟。莽曰勤田。〔一〕猗氏，解，〔二〕蒲反，有堯山、首山祠。雷首山在南。故曰蒲，秦更名。莽曰蒲城。〔三〕河北，詩魏國，晉獻公滅之，以封大夫畢萬，曾孫絳徙安邑也。左邑，莽曰兆亭。汾陰，介山在南。聞喜，故曲沃。晉武公自晉陽徙此。武帝元鼎六年行過，更名。〔四〕濩澤，禹貢析城山在西南。〔五〕端氏，臨汾，垣，禹貢王屋山在東北，沇水所出，東南至武德入河，軼出滎陽北地中，又東至琅槐入海，過郡九，行千八百四十里。〔六〕皮氏，耿鄉，故耿國，晉獻公滅之，以賜大夫趙夙。後十世獻侯徙中牟。有鐵官。莽曰延平。長脩，平陽，韓武子玄孫貞子居此。有鐵官。莽曰香平。〔七〕襄陵，有班氏（香）〔鄉〕亭。莽曰幹昌。〔八〕彘，霍大山在東，冀州山，周厲王所奔。莽曰黃城。〔九〕楊，莽曰有年亭。〔一０〕北屈，禹貢壺口山在東南。莽曰朕北。〔一一〕蒲子，〔一二〕絳，晉武公自曲沃徙此。有鐵官。〔一三〕狐讘，〔一四〕騏。侯國。〔一五〕","sentenceOrder":291},
  {"id":"s_work_han_thu_38_292","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「在大河之陽。」","sentenceOrder":292},
  {"id":"s_work_han_thu_38_293","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「音蟹。」","sentenceOrder":293},
  {"id":"s_work_han_thu_38_294","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　應劭曰：「秦始皇東巡見長阪，故加『反』云。」孟康曰：「本蒲也，晉文公以賂秦，後秦人還蒲，魏人喜曰『蒲反矣』。謂秦名之，非也。」臣瓚曰：「秦世家云『以垣為蒲反』，然則本非蒲也。」師古曰：「應說是。」","sentenceOrder":294},
  {"id":"s_work_han_thu_38_295","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　應劭曰：「今曲沃也。秦改為左邑。武帝於此聞南越破，改曰聞喜。」","sentenceOrder":295},
  {"id":"s_work_han_thu_38_296","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「有濩澤，在西北。」師古曰：「濩音烏虢反。」","sentenceOrder":296},
  {"id":"s_work_han_thu_38_297","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「琅音郎。槐音回。」","sentenceOrder":297},
  {"id":"s_work_han_thu_38_298","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　應劭曰：「堯都也，在平河之陽。」","sentenceOrder":298},
  {"id":"s_work_han_thu_38_299","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　應劭曰：「襄陵在西北。」師古曰：「晉襄公之陵，因以名縣。」","sentenceOrder":299},
  {"id":"s_work_han_thu_38_300","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　應劭曰：「順帝改曰永安。」","sentenceOrder":300},
  {"id":"s_work_han_thu_38_301","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕應劭曰：「楊侯國。」","sentenceOrder":301},
  {"id":"s_work_han_thu_38_302","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕應劭曰：「有南故稱北。」臣瓚曰：「汲郡古文『翟章救鄭，次于南屈』。」師古曰：「屈音居勿反。即晉公子夷吾所居。」","sentenceOrder":302},
  {"id":"s_work_han_thu_38_303","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕應劭曰：「故蒲反舊邑，武帝置。」師古曰：「重耳所居也。應說失之。」","sentenceOrder":303},
  {"id":"s_work_han_thu_38_304","chapterId":"ch_work_han_thu_38","textTraditional":"〔一三〕應劭曰：「絳水出西南。」","sentenceOrder":304},
  {"id":"s_work_han_thu_38_305","chapterId":"ch_work_han_thu_38","textTraditional":"〔一四〕師古曰：「讘音之涉反。」","sentenceOrder":305},
  {"id":"s_work_han_thu_38_306","chapterId":"ch_work_han_thu_38","textTraditional":"〔一五〕師古曰：「音其。」","sentenceOrder":306},
  {"id":"s_work_han_thu_38_307","chapterId":"ch_work_han_thu_38","textTraditional":"太原郡，秦置。有鹽官，在晉陽。屬并州。戶十六萬九千八百六十三，口六十八萬四百八十八。有家馬官。〔一〕縣二十一：晉陽，故詩唐國，周成王滅唐，封弟叔虞。龍山在西北。有鹽官。晉水所出，東入汾。〔二〕葰人，〔三〕界休，莽曰界美。〔四〕榆次，涂水鄉，晉大夫知徐吾邑。梗陽鄉，魏戊邑。莽曰大原亭。〔五〕中都，于離，莽曰于合。茲氏，莽曰茲同。狼孟，莽曰狼調。鄔，九澤在北，是為昭餘祁，并州藪。晉大夫司馬彌牟邑。〔六〕盂，晉大夫孟丙邑。平陶，莽曰多穰。汾陽，北山，汾水所出，西南至汾陰入河，過郡二，行千三百四十里，冀州浸。京陵，莽曰致城。〔七〕陽曲，〔八〕大陵，有鐵官。莽曰大寧。原平，祁，晉大夫賈辛邑。莽曰示。上艾，綿曼水，東至蒲吾，入虖池水。〔九〕慮虒，〔一０〕陽邑，莽曰繁穰。廣武。（河主）〔句注〕、賈屋山在北。都尉治。莽曰信桓。〔一一〕","sentenceOrder":307},
  {"id":"s_work_han_thu_38_308","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　臣瓚曰：「漢有家馬廄，一廄萬匹，時以邊表有事，故分來在此。家馬後改曰挏馬也。」師古曰：「挏音動。」","sentenceOrder":308},
  {"id":"s_work_han_thu_38_309","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　臣瓚曰：「所謂唐，今河東永安是也，去晉四百里。」師古曰：「瓚說是也。」","sentenceOrder":309},
  {"id":"s_work_han_thu_38_310","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　如淳曰：「音璅。」師古曰：「又音山寡反。」","sentenceOrder":310},
  {"id":"s_work_han_thu_38_311","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「休音許虯反。」","sentenceOrder":311},
  {"id":"s_work_han_thu_38_312","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「涂音塗。梗音鯁。」","sentenceOrder":312},
  {"id":"s_work_han_thu_38_313","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「音一戶反，又音於據反。」","sentenceOrder":313},
  {"id":"s_work_han_thu_38_314","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「即九京。」","sentenceOrder":314},
  {"id":"s_work_han_thu_38_315","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　應劭曰：「河千里一曲，當其陽，故曰陽曲也。」師古曰：「隋文帝自以姓楊，故惡陽曲之號，乃改其縣為陽直。今則復舊名焉。」","sentenceOrder":315},
  {"id":"s_work_han_thu_38_316","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「虖音呼。池音徒何反。」","sentenceOrder":316},
  {"id":"s_work_han_thu_38_317","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「音廬夷。」","sentenceOrder":317},
  {"id":"s_work_han_thu_38_318","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕師古曰：「賈屋山，即史記所云『趙襄子北登夏屋』者。」","sentenceOrder":318},
  {"id":"s_work_han_thu_38_319","chapterId":"ch_work_han_thu_38","textTraditional":"上黨郡，秦置，屬并州。有上黨關、壺口關、石研關、天井關。〔一〕戶七萬三千七百九十八，口三十三萬七千七百六十六。縣十四：長子，周史辛甲所封。鹿谷山，濁漳水所出，東至鄴入（青）〔清〕漳。〔二〕屯留，桑欽言「絳水出西南，東入海」。〔三〕余吾，銅鞮，有上虒亭，下虒聚。〔四〕沾，大黽谷，清漳水所出，東北至邑成入大河，過郡五，行千六百八十里，冀州川。〔五〕涅氏，涅水也。〔六〕襄垣，莽曰上黨亭。壺關，有羊腸版。沾水東至朝歌入淇。〔七〕泫氏，楊谷，絕水所出，南至野王入沁。〔八〕高都，莞谷，丹水所出，東南入泫水。有天井關。〔九〕潞，故潞子國。陭氏，〔一０〕陽阿，穀遠。羊頭山世靡谷，沁水所出，東南至滎陽入河，過郡三，行九百七十里。莽曰穀近。〔一一〕","sentenceOrder":319},
  {"id":"s_work_han_thu_38_320","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「研音形。」","sentenceOrder":320},
  {"id":"s_work_han_thu_38_321","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「長讀曰長短之長，今俗為長幼之長，非也。」","sentenceOrder":321},
  {"id":"s_work_han_thu_38_322","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「屯音純。」","sentenceOrder":322},
  {"id":"s_work_han_thu_38_323","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「虒音斯。」","sentenceOrder":323},
  {"id":"s_work_han_thu_38_324","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「沾水出壺關。」師古曰：「沾音他兼反。」","sentenceOrder":324},
  {"id":"s_work_han_thu_38_325","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「涅水出焉，故以名縣也。涅音乃結反。」","sentenceOrder":325},
  {"id":"s_work_han_thu_38_326","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　應劭曰：「黎侯國也，今黎亭是。」","sentenceOrder":326},
  {"id":"s_work_han_thu_38_327","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　應劭曰：「山海經泫水所出者也。」師古曰：「泫音工玄反。」","sentenceOrder":327},
  {"id":"s_work_han_thu_38_328","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「莞音丸。」","sentenceOrder":328},
  {"id":"s_work_han_thu_38_329","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「音於義反。」","sentenceOrder":329},
  {"id":"s_work_han_thu_38_330","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕師古曰：「今沁水至懷州武陟縣界入河。此云至滎陽，疑傳寫錯誤。」","sentenceOrder":330},
  {"id":"s_work_han_thu_38_331","chapterId":"ch_work_han_thu_38","textTraditional":"河內郡，高帝元年為殷國，二年更名。莽曰後隊，屬司隸。戶二十四萬一千二百四十六，口百六萬七千九十七。縣十八：懷，有工官。莽曰河內。汲，武德，〔一〕波，〔二〕山陽，東太行山在西北。〔三〕河陽，莽曰河亭。州，共，故國。北山，淇水所出，東至黎陽入河。〔四〕平皋，〔五〕朝歌，紂所都。周武王弟康叔所封，更名衛。莽曰雅歌。脩武，〔六〕溫，故國，己姓，蘇忿生所封也。野王，太行山在西北。衛元君為秦所奪，自（僕）〔濮〕陽徙此。莽曰平野。〔七〕獲嘉，故汲之新中鄉，武帝行過更名也。軹，〔八〕沁水，〔九〕隆慮，國水東北至信成入張甲河，過郡三，行千八百四十里。有鐵官。〔一０〕蕩陰。蕩水東至內黃澤。西山，羑水所出，亦至內黃入蕩。有羑里城，西伯所拘也。〔一一〕","sentenceOrder":331},
  {"id":"s_work_han_thu_38_332","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　孟康曰：「始皇東巡置，自以武德定天下。」","sentenceOrder":332},
  {"id":"s_work_han_thu_38_333","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　孟康曰：「今有絺城，晉文公所得賜者。」","sentenceOrder":333},
  {"id":"s_work_han_thu_38_334","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「行音胡郎反。」","sentenceOrder":334},
  {"id":"s_work_han_thu_38_335","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　孟康曰：「共伯入為三公者也。」師古曰：「共音恭。」","sentenceOrder":335},
  {"id":"s_work_han_thu_38_336","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「邢侯自襄國徙此。當齊桓公時，衛人伐邢，邢遷于夷儀，其地屬晉，號曰邢丘。以其在河之皋，處勢平夷，故曰平皋。」臣瓚曰：「春秋傳狄人伐邢，邢遷于夷儀，不至此也。今襄國西有夷儀城，去襄國百餘里。邢是丘名，非國也。」師古曰：「應說非也。左氏傳曰『晉侯送女於邢丘』，蓋謂此耳。」","sentenceOrder":336},
  {"id":"s_work_han_thu_38_337","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　應劭曰：「晉始啟南陽，今南陽城是也，秦改曰脩武。」臣瓚曰：「韓非書『秦昭王越趙長平西伐脩武』，時秦未兼天下，脩武之名久矣。」師古曰：「瓚說是也。」","sentenceOrder":337},
  {"id":"s_work_han_thu_38_338","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　孟康曰：「故邘國也，今邘亭是也。」師古曰：「行音胡郎反。」","sentenceOrder":338},
  {"id":"s_work_han_thu_38_339","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　孟康曰：「原鄉，晉文公所圍是也。」師古曰：「音只。」","sentenceOrder":339},
  {"id":"s_work_han_thu_38_340","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「沁音千浸反。」","sentenceOrder":340},
  {"id":"s_work_han_thu_38_341","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕應劭曰：「隆慮山在北，避殤帝名改曰林慮也。」師古曰：「慮音廬。」","sentenceOrder":341},
  {"id":"s_work_han_thu_38_342","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕師古曰：「蕩音湯。羑音羊九反。」","sentenceOrder":342},
  {"id":"s_work_han_thu_38_343","chapterId":"ch_work_han_thu_38","textTraditional":"河南郡，故秦三川郡，高帝更名。雒陽戶五萬二千八百三十九。莽曰保忠信鄉，屬司隸也。戶二十七萬六千四百四十四，口一百七十四萬二百七十九。有鐵官、工官。敖倉在滎陽。縣二十二：雒陽，周公遷殷民，是為成周。春秋昭公（二）〔三〕十（一）〔二〕年，晉合諸侯于狄泉，以其地大成周之城，居敬王。莽曰宜陽。〔一〕滎陽，卞水、馮池皆在西南。有狼湯渠，首受泲，東南至陳入潁，過郡四，行七百八十里。〔二〕偃師，尸鄉，殷湯所都。莽曰師成。〔三〕京，〔四〕平陰，〔五〕中牟，圃田澤在西，豫州藪。有筦叔邑，趙獻侯自耿徙此。〔六〕平，莽曰治平。陽武，有博狼沙。莽曰陽桓。〔七〕河南，故郟鄏地。周武王遷九鼎，周公致太平，營以為都，是為王城，至平王居之。〔八〕緱氏，劉聚，周大夫劉子邑，有延壽城仙人祠。莽曰中亭。〔九〕卷，〔一０〕原武，莽曰原桓。鞏，東周所居。穀成，禹貢瀍水出{兟日}亭北，東南入雒。〔一一〕故市，密，故國。有大騩山，潩水所出，南至臨潁入潁。〔一二〕新成，惠帝四年置。蠻中，故戎蠻子國。開封，逢池在東北，或曰宋之逢澤也。〔一三〕成皋，故虎牢。或曰制。〔一四〕苑陵，莽曰左亭。梁，{單心}狐聚，秦滅西周徙其君於此。陽人聚，秦滅東周徙其君於此。〔一五〕新鄭。詩鄭國，鄭桓公之子武公所國，後為韓所滅，韓自平陽徙都之。〔一六〕","sentenceOrder":343},
  {"id":"s_work_han_thu_38_344","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「魚豢云漢火行忌水，故去『洛』『水』而加『隹』。如魚氏說，則光武以後改為『雒』字也。」","sentenceOrder":344},
  {"id":"s_work_han_thu_38_345","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「故虢國，今虢亭是也。」師古曰：「狼音浪。湯音宕。泲音子禮反，本濟水字。」","sentenceOrder":345},
  {"id":"s_work_han_thu_38_346","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　臣瓚曰：「湯居亳，今濟陰縣是也。今亳有湯冢，己氏有伊尹冢，皆相近也。」師古曰：「瓚說非也。又如皇甫謐所云湯都在穀熟，事並不經。劉向云『湯無葬處』，安得湯冢乎！」","sentenceOrder":346},
  {"id":"s_work_han_thu_38_347","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「即鄭共叔段所居也。」","sentenceOrder":347},
  {"id":"s_work_han_thu_38_348","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「在平城南，故曰平陰。」","sentenceOrder":348},
  {"id":"s_work_han_thu_38_349","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「筦與管同。」","sentenceOrder":349},
  {"id":"s_work_han_thu_38_350","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「狼音浪。」","sentenceOrder":350},
  {"id":"s_work_han_thu_38_351","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「郟音夾。鄏音辱。」","sentenceOrder":351},
  {"id":"s_work_han_thu_38_352","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「緱音工侯反。」","sentenceOrder":352},
  {"id":"s_work_han_thu_38_353","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「音去權反。」","sentenceOrder":353},
  {"id":"s_work_han_thu_38_354","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕師古曰：「即今新安。{兟日}音潛。」","sentenceOrder":354},
  {"id":"s_work_han_thu_38_355","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕應劭曰：「『密人不恭』，密須氏姞姓之國也。」臣瓚曰：「密，姬姓之國也，見世本。密須，今安定陰密是也。」師古曰：「應、瓚二說皆非也。此密即春秋僖六年『圍新密』者也，蓋鄭地。而詩所云『密人』，即左傳所謂『密須之鼓』者也，在安定陰密。騩音隗。潩音翼，又音昌力反。」","sentenceOrder":355},
  {"id":"s_work_han_thu_38_356","chapterId":"ch_work_han_thu_38","textTraditional":"〔一三〕臣瓚曰：「汲郡古文梁惠王發逢忌之藪以賜民，今浚儀有逢陂忌澤是也。」","sentenceOrder":356},
  {"id":"s_work_han_thu_38_357","chapterId":"ch_work_han_thu_38","textTraditional":"〔一四〕師古曰：「穆天子傳云『七萃之士生捕獸，即獻天子，天子畜之東虢，號曰獸牢』。」","sentenceOrder":357},
  {"id":"s_work_han_thu_38_358","chapterId":"ch_work_han_thu_38","textTraditional":"〔一五〕應劭曰：「左傳曰秦取梁。梁，伯翳之後，與秦同祖。」臣瓚曰：「秦取梁，後改曰夏陽，今馮翊夏陽是也。此梁，周之小邑，見於春秋。」師古曰：「瓚說是也。{單心}音乃旦反。」","sentenceOrder":358},
  {"id":"s_work_han_thu_38_359","chapterId":"ch_work_han_thu_38","textTraditional":"〔一六〕應劭曰：「國語曰，鄭桓公為周司徒，王室將亂，寄帑與賄於虢、會之閒。幽王敗，威公死之，其子武公與平王東遷洛邑，遂伐虢、會而并其地，而邑於此。」","sentenceOrder":359},
  {"id":"s_work_han_thu_38_360","chapterId":"ch_work_han_thu_38","textTraditional":"東郡，秦置。莽曰治亭。屬兗州。戶四十萬一千二百九十七，口百六十五萬九千二十八。縣二十二：濮陽，衛成公自楚丘徙此。故帝丘，顓頊虛。莽曰治亭。〔一〕（畔）觀，莽曰觀治。〔二〕聊城，頓丘，莽曰順丘。〔三〕發干，莽曰戢楯。范，莽曰建睦。茬平，莽曰功崇。〔四〕東武陽，禹治漯水，東北至千乘入海，過郡三，行千二十里。莽曰武昌。〔五〕博平，莽曰加睦。黎，莽曰黎治。〔六〕清，莽曰清治。〔七〕東阿，都尉治。〔八〕離狐，莽曰瑞狐。臨邑，有（（暂缺F5FA））〔泲〕廟。莽曰穀城亭。〔九〕利苗，須昌，故須句國，大昊後，風姓。〔一０〕壽良，蚩尤祠在西北（涑）〔泲〕上。有朐城。〔一一〕樂昌，陽平，白馬，南燕，南燕國，姞姓，黃帝後。〔一二〕廩丘。","sentenceOrder":360},
  {"id":"s_work_han_thu_38_361","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「濮水南入鉅野。」師古曰：「虛讀曰墟。」","sentenceOrder":361},
  {"id":"s_work_han_thu_38_362","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「夏有觀扈，世祖更名衛國，以封周後。」師古曰：「觀音工喚反。」","sentenceOrder":362},
  {"id":"s_work_han_thu_38_363","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「以丘名縣也。丘一成為頓丘，謂一（成）〔頓〕而成也。或曰，成，重也，一重之丘也。」","sentenceOrder":363},
  {"id":"s_work_han_thu_38_364","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　應劭曰：「在茬山之平地者也。」師古曰：「音仕疑反。」","sentenceOrder":364},
  {"id":"s_work_han_thu_38_365","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「武水之陽也。」師古曰：「漯音它合反。」","sentenceOrder":365},
  {"id":"s_work_han_thu_38_366","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　孟康曰：「詩黎侯國，今黎陽也。」臣瓚曰：「黎陽在魏郡，非黎縣也。」師古曰：「瓚說是。」","sentenceOrder":366},
  {"id":"s_work_han_thu_38_367","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　應劭曰：「章帝更名樂平。」","sentenceOrder":367},
  {"id":"s_work_han_thu_38_368","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　應劭曰：「衛邑也。有西故稱東。」","sentenceOrder":368},
  {"id":"s_work_han_thu_38_369","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「（（暂缺F5FA））〔泲〕亦濟水字也。其後並同。」","sentenceOrder":369},
  {"id":"s_work_han_thu_38_370","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「句音劬。」","sentenceOrder":370},
  {"id":"s_work_han_thu_38_371","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕應劭曰：「世祖（父叔）〔叔父〕名良，故曰壽張。」","sentenceOrder":371},
  {"id":"s_work_han_thu_38_372","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕師古曰：「姞音其乙反。」","sentenceOrder":372},
  {"id":"s_work_han_thu_38_373","chapterId":"ch_work_han_thu_38","textTraditional":"陳留郡，武帝元狩元年置。屬兗州。戶二十九萬六千二百八十四，口一百五十萬九千五十。縣十七：陳留，魯渠水首受狼湯渠，東至陽夏，入渦渠。〔一〕小黃，成安，寧陵，莽曰康善。〔二〕雍丘，故杞國也，周武王封禹後東樓公。先春秋時徙魯東北，二十一世簡公為楚所滅。酸棗，東昏，莽曰東明。襄邑，有服官。莽曰襄平。〔三〕外黃，都尉治。〔四〕封丘，濮渠水首受（涑）〔泲〕，東北至都關，入羊里水，過郡三，行六百三十里。〔五〕長羅，侯國。莽曰惠澤。尉氏，〔六〕傿，莽曰順通。〔七〕長垣，莽曰長固。〔八〕平丘，濟陽，莽曰濟前。浚儀。故大梁。魏惠王自安邑徙此。睢水首受狼湯水，東至取慮入泗，過郡四，行千三百六十里。〔九〕","sentenceOrder":373},
  {"id":"s_work_han_thu_38_374","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　孟康曰：「留，鄭邑也，後為陳所并，故曰陳留。」臣瓚曰：「宋亦有留，彭城留是也。留屬陳，故稱陳留也。」師古曰：「瓚說是也。渦音戈。」","sentenceOrder":374},
  {"id":"s_work_han_thu_38_375","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　孟康曰：「故葛伯國，今葛鄉是。」","sentenceOrder":375},
  {"id":"s_work_han_thu_38_376","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　應劭曰：「春秋傳曰『師于襄牛』是也。」師古曰：「圈稱云襄邑宋地，本承匡襄陵鄉也。宋襄公所葬，故曰襄陵。秦始皇以承匡卑溼，故徙縣於襄陵，謂之襄邑，縣西三十里有承匡城。然則應說以為襄牛，誤也。」","sentenceOrder":376},
  {"id":"s_work_han_thu_38_377","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　張晏曰：「魏郡有內黃，故加外。」臣瓚曰：「縣有黃溝，故氏之也。」師古曰：「左氏傳云『惠公敗宋師于黃』，杜預以為外黃縣東有黃城，即此地也。」","sentenceOrder":377},
  {"id":"s_work_han_thu_38_378","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　孟康曰：「春秋傳『敗狄于長丘』，今翟溝是。」","sentenceOrder":378},
  {"id":"s_work_han_thu_38_379","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　應劭曰：「古獄官曰尉氏，鄭之別獄也。」臣瓚曰：「鄭大夫尉氏之邑，故遂以為邑。」師古曰：「鄭大夫尉氏亦以掌獄之官故為族耳。應說是也。」","sentenceOrder":379},
  {"id":"s_work_han_thu_38_380","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　應劭曰：「鄭伯克段于鄢是也。」師古曰：「鄢音偃。」","sentenceOrder":380},
  {"id":"s_work_han_thu_38_381","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　孟康曰：「春秋會于匡，今匡城是。」","sentenceOrder":381},
  {"id":"s_work_han_thu_38_382","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　應劭曰：「魏惠王自安邑徙此，號曰梁。」師古曰：「取慮，縣名也，音秋廬。取又音趨。」","sentenceOrder":382},
  {"id":"s_work_han_thu_38_383","chapterId":"ch_work_han_thu_38","textTraditional":"潁川郡，秦置。高帝五年為韓國，六年復故。莽曰左隊。陽翟有工官。屬豫州。〔一〕戶四十三萬二千四百九十一，口二百二十一萬九百七十三。縣二十：陽翟，夏禹國。周末，韓景侯自新鄭徙此。戶四萬一千六百五十，口十萬九千。莽曰潁川。〔二〕昆陽，〔三〕潁陽，〔四〕定陵，有東不羹。莽曰定城。〔五〕長社，〔六〕新汲，〔七〕襄城，有西不羹。莽曰相城。郾，〔八〕郟，〔九〕舞陽，〔一０〕潁陰，崇高，武帝置，以奉太室山，是為中岳。有太室、少室山廟。古文以崇高為外方山也。〔一一〕許，故國，姜姓，四岳後，太叔所封，二十四世為楚所滅。傿陵，戶四萬九千一百一，口二十六萬一千四百一十八。莽曰左亭。〔一二〕臨潁，莽曰監潁。父城，應鄉，故國，周武王弟所封。〔一三〕成安，侯國也。周承休，侯國，元帝置，元始二年更名鄭公。莽曰嘉美。〔一四〕陽城，陽城山，洧水所出，東南至長平入潁，過郡三，行五百里。陽乾山，潁水所出，東至下蔡入淮，過郡三，行千五百里，荊州浸。有鐵官。〔一五〕綸氏。","sentenceOrder":383},
  {"id":"s_work_han_thu_38_384","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　孟康曰：「夏啟有鈞臺之饗，今鈞臺在南。」","sentenceOrder":384},
  {"id":"s_work_han_thu_38_385","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「夏禹都也。」臣瓚曰：「世本禹都陽城，汲郡古文亦云居之，不居陽翟也。」師古曰：「陽翟本禹所受封耳。應、瓚之說皆非。」","sentenceOrder":385},
  {"id":"s_work_han_thu_38_386","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　應劭曰：「昆水出南陽。」","sentenceOrder":386},
  {"id":"s_work_han_thu_38_387","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　應劭曰：「潁水出陽城。」","sentenceOrder":387},
  {"id":"s_work_han_thu_38_388","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「羹音郎。其後亦同。」","sentenceOrder":388},
  {"id":"s_work_han_thu_38_389","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　應劭曰：「宋人圍長葛是也。其社中樹暴長，更名長社。」師古曰：「長讀如本字。」","sentenceOrder":389},
  {"id":"s_work_han_thu_38_390","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「闞駰云本汲鄉也，宣帝神爵三年置。以河內有汲，故加新也。」","sentenceOrder":390},
  {"id":"s_work_han_thu_38_391","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「音一戰反。」","sentenceOrder":391},
  {"id":"s_work_han_thu_38_392","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「音夾。」","sentenceOrder":392},
  {"id":"s_work_han_thu_38_393","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕應劭曰：「舞水出南。」","sentenceOrder":393},
  {"id":"s_work_han_thu_38_394","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕師古曰：「崈，古崇字。」","sentenceOrder":394},
  {"id":"s_work_han_thu_38_395","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕李奇曰：「六國為安陵。」師古曰：「傿音偃。」","sentenceOrder":395},
  {"id":"s_work_han_thu_38_396","chapterId":"ch_work_han_thu_38","textTraditional":"〔一三〕應劭曰：「韓詩外傳周成王與弟戲以桐葉為圭，『吾以此封汝。』周公曰：『天子無戲言。』王應時而封，故曰應侯鄉，是也。」臣瓚曰：「呂氏春秋曰成王以戲授桐葉為圭以封叔虞，非應侯也。汲郡古文殷時已自有國，非成王之所造也。」師古曰：「武王之弟自封應國，非桐圭之事也。應氏之說蓋失之焉。又據左氏傳云『邘、晉、應、韓，武之穆也』，是則應侯武王之子，又與志說不同。」","sentenceOrder":396},
  {"id":"s_work_han_thu_38_397","chapterId":"ch_work_han_thu_38","textTraditional":"〔一四〕〔師古曰〕：「休音許虯反。」","sentenceOrder":397},
  {"id":"s_work_han_thu_38_398","chapterId":"ch_work_han_thu_38","textTraditional":"〔一五〕師古曰：「乾音干。洧音于軌反。」","sentenceOrder":398},
  {"id":"s_work_han_thu_38_399","chapterId":"ch_work_han_thu_38","textTraditional":"汝南郡，高帝置。莽曰汝汾。分為賞都尉。屬豫州。戶四十六萬一千五百八十七，口二百五十九萬六千一百四十八。縣三十七：平輿，〔一〕陽安，〔二〕陽城，侯國。莽曰新安。〈氵隱〉強，〔三〕富波，女陽，〔四〕鮦陽，〔五〕吳房，〔六〕安成，侯國。莽曰至成。南頓，故頓子國，姬姓。〔七〕朗陵，〔八〕細陽，莽曰樂慶。〔九〕宜春，侯國。莽曰宣孱。女陰，故胡國。都尉治。莽曰汝墳。新蔡，蔡平侯自蔡徙此，後二世徙下蔡。莽曰新遷。新息，莽曰新德。〔一０〕灈陽，〔一一〕期思，〔一二〕慎陽，〔一三〕慎，莽曰慎治。召陵，〔一四〕弋陽，侯國。〔一五〕西平，有鐵官。莽曰新亭。〔一六〕上蔡，故蔡國，周武王弟叔度所封。度放，成王封其子胡，十八世徙新蔡。浸，莽曰閏治。〔一七〕西華，莽曰華望。長平，莽曰長正。宜祿，莽曰賞都亭。項，故國。新郪，莽曰新延。〔一八〕歸德，侯國。宣帝置。莽曰歸惠。新陽，莽曰新明。〔一九〕安昌，侯國。莽曰始成。安陽，侯國。莽曰均夏。〔二０〕博陽，侯國。莽曰樂家。成陽，侯國。莽曰新利。定陵。高陵山，汝水出，東南至新蔡入淮，過郡四，行千三百四十里。","sentenceOrder":399},
  {"id":"s_work_han_thu_38_400","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「故沈子國。今沈亭是也。輿音豫。」","sentenceOrder":400},
  {"id":"s_work_han_thu_38_401","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「道國也。今道亭是。」","sentenceOrder":401},
  {"id":"s_work_han_thu_38_402","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　應劭曰：「〈氵隱〉水出潁川陽城。」師古曰：「〈氵隱〉音於謹反，又音殷。」","sentenceOrder":402},
  {"id":"s_work_han_thu_38_403","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　應劭曰：「汝水出弘農，入淮。」師古曰：「女讀曰汝。其下汝陰亦同。」","sentenceOrder":403},
  {"id":"s_work_han_thu_38_404","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「在鮦水之陽也。」孟康曰：「鮦音紂。」","sentenceOrder":404},
  {"id":"s_work_han_thu_38_405","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　孟康曰：「本房子國。楚靈王遷房於楚。吳王闔閭弟夫概奔楚，楚封於此，為堂谿氏。以封吳，故曰吳房，今吳房城堂谿亭是。」","sentenceOrder":405},
  {"id":"s_work_han_thu_38_406","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　應劭曰：「頓迫於陳，其後南徙，故號南頓，故城尚在。」","sentenceOrder":406},
  {"id":"s_work_han_thu_38_407","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　應劭曰：「朗陵山在西南。」","sentenceOrder":407},
  {"id":"s_work_han_thu_38_408","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「居細水之陽，故曰細陽。細水本出新郪。郪音千私反。」","sentenceOrder":408},
  {"id":"s_work_han_thu_38_409","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕孟康曰：「故息國，其後徙東，故加新云。」","sentenceOrder":409},
  {"id":"s_work_han_thu_38_410","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕應劭曰：「灈水出吳房，東入瀙也。」師古曰：「灈音劬。瀙音楚人反，又音楚刃反。」","sentenceOrder":410},
  {"id":"s_work_han_thu_38_411","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕師古曰：「故蔣國。」","sentenceOrder":411},
  {"id":"s_work_han_thu_38_412","chapterId":"ch_work_han_thu_38","textTraditional":"〔一三〕應劭曰：「慎水出東北，入淮。」師古曰：「慎字本作滇，音真，後誤為慎耳。今猶有真丘、真陽縣，字並單作真，知其音不改也。闞駰云永平五年失印更刻，遂誤以『水』為『心』。」","sentenceOrder":412},
  {"id":"s_work_han_thu_38_413","chapterId":"ch_work_han_thu_38","textTraditional":"〔一四〕師古曰：「即桓公伐楚次於召陵者也。召讀曰邵。」","sentenceOrder":413},
  {"id":"s_work_han_thu_38_414","chapterId":"ch_work_han_thu_38","textTraditional":"〔一五〕應劭曰：「弋山在西北。故黃國，今黃城是。」","sentenceOrder":414},
  {"id":"s_work_han_thu_38_415","chapterId":"ch_work_han_thu_38","textTraditional":"〔一六〕應劭曰：「故柏子國也，今柏亭是。」","sentenceOrder":415},
  {"id":"s_work_han_thu_38_416","chapterId":"ch_work_han_thu_38","textTraditional":"〔一七〕應劭曰：「孫叔敖子所邑之浸丘是也。世祖更名固始。」師古曰：「浸音子衽反。」","sentenceOrder":416},
  {"id":"s_work_han_thu_38_417","chapterId":"ch_work_han_thu_38","textTraditional":"〔一八〕應劭曰：「秦伐魏，取郪丘。漢興為新郪。章帝封殷後，更名宋。」臣瓚曰：「光武既封殷後於宋，又封新郪。」師古曰：「封於新郪，號為宋國耳。瓚說非。」","sentenceOrder":417},
  {"id":"s_work_han_thu_38_418","chapterId":"ch_work_han_thu_38","textTraditional":"〔一九〕應劭曰：「在新水之陽。」","sentenceOrder":418},
  {"id":"s_work_han_thu_38_419","chapterId":"ch_work_han_thu_38","textTraditional":"〔二０〕應劭曰：「故江國，今江亭是。」","sentenceOrder":419},
  {"id":"s_work_han_thu_38_420","chapterId":"ch_work_han_thu_38","textTraditional":"南陽郡，秦置。莽曰前隊。屬荊州。戶三十五萬九千（一）〔三〕百一十六，口一百九十四萬二千五十一。縣三十六：宛，故申伯國。有屈申城。縣南有北筮山。戶四萬七千五百四十七。有工官、鐵官。莽曰南陽。犨，〔一〕杜衍，莽曰閏衍。酇，侯國。莽曰南庚。〔二〕育陽，有南筮聚，在東北。〔三〕博山，侯國。哀帝置。故順陽。〔四〕涅陽，莽曰前亭。〔五〕陰，〔六〕堵陽，莽曰陽城。〔七〕雉，衡山，灃水所出，東至〈屋阝〉入汝。〔八〕山都，蔡陽，莽之母功顯君邑。〔九〕新野，筑陽，故穀伯國。莽曰宜禾。〔一０〕棘陽，〔一一〕武當，舞陰，中陰山，瀙水所出，東至蔡入汝。西鄂，〔一二〕穰，莽曰農穰。〔一三〕酈，育水出西北，南入漢。〔一四〕安眾，侯國。故宛西鄉。冠軍，武帝置。故穰盧陽鄉、宛臨駣聚。〔一五〕比陽，〔一六〕平氏，禹貢桐柏大復山在東南，淮水所出，東南至淮（陵）〔浦〕入海，過郡四，行三千二百四十里，青州川。莽曰平善。隨，故國。厲鄉，故厲國也。〔一七〕葉，楚葉公邑。有長城，號曰方城。〔一八〕鄧，故國。都尉治。〔一九〕朝陽，莽曰厲信。〔二０〕魯陽，有魯山。古魯縣，御龍氏所遷。魯山，滍水所出，東北至定陵入汝。又有昆水，東南至定陵入汝。〔二一〕舂陵，侯國。故蔡陽白水鄉。上唐鄉，故唐國。〔二二〕新都，侯國。莽曰新林。湖陽，故廖國也。〔二三〕紅陽，侯國。莽曰紅俞。〔二四〕樂成，侯國。博望，侯國。莽曰宜樂。復陽。侯國。故湖陽樂鄉。〔二五〕","sentenceOrder":420},
  {"id":"s_work_han_thu_38_421","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「音昌牛反。」","sentenceOrder":421},
  {"id":"s_work_han_thu_38_422","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　孟康曰：「音讚。」師古曰：「即蕭何所封。」","sentenceOrder":422},
  {"id":"s_work_han_thu_38_423","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　應劭曰：「育水出弘農盧氏，南入于沔。」","sentenceOrder":423},
  {"id":"s_work_han_thu_38_424","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　應劭曰：「漢明帝改曰順陽，在順水之陽也。」師古曰：「順陽，舊名。應說非。」","sentenceOrder":424},
  {"id":"s_work_han_thu_38_425","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「在涅水之陽。」師古曰：「涅音乃結反。」","sentenceOrder":425},
  {"id":"s_work_han_thu_38_426","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「即春秋左氏傳所云遷陰於下陰者也，與酇相近。今襄州有陰城縣，縣有酇城鄉。」","sentenceOrder":426},
  {"id":"s_work_han_thu_38_427","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　韋昭曰：「堵音者。」","sentenceOrder":427},
  {"id":"s_work_han_thu_38_428","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「舊讀雉音弋爾反。而太康地志云即陳倉人所逐二童子名寶雞者，雄止陳倉為石，雌止此縣，故名雉縣，疑不可據也。〈屋阝〉音屋。」","sentenceOrder":428},
  {"id":"s_work_han_thu_38_429","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　應劭曰：「蔡水所出，東入淮。」","sentenceOrder":429},
  {"id":"s_work_han_thu_38_430","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕應劭曰：「筑水出漢中房陵，東入沔。」師古曰：「春秋云『穀伯綏來朝』是也。今襄州有穀城縣，在筑水之陽。筑音逐。」","sentenceOrder":430},
  {"id":"s_work_han_thu_38_431","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕應劭曰：「在棘水之陽。」","sentenceOrder":431},
  {"id":"s_work_han_thu_38_432","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕應劭曰：「江夏有鄂，故加西云。」","sentenceOrder":432},
  {"id":"s_work_han_thu_38_433","chapterId":"ch_work_han_thu_38","textTraditional":"〔一三〕師古曰：「今鄧州穰縣是也。音人羊反。」","sentenceOrder":433},
  {"id":"s_work_han_thu_38_434","chapterId":"ch_work_han_thu_38","textTraditional":"〔一四〕如淳曰：「酈音蹢躅之蹢。」","sentenceOrder":434},
  {"id":"s_work_han_thu_38_435","chapterId":"ch_work_han_thu_38","textTraditional":"〔一五〕應劭曰：「武帝以封霍去病。去病仍出匈奴，功冠諸軍，故曰冠軍。駣音桃。」","sentenceOrder":435},
  {"id":"s_work_han_thu_38_436","chapterId":"ch_work_han_thu_38","textTraditional":"〔一六〕應劭曰：「比水所出，東入蔡。」","sentenceOrder":436},
  {"id":"s_work_han_thu_38_437","chapterId":"ch_work_han_thu_38","textTraditional":"〔一七〕師古曰：「厲讀曰賴。」","sentenceOrder":437},
  {"id":"s_work_han_thu_38_438","chapterId":"ch_work_han_thu_38","textTraditional":"〔一八〕師古曰：「音式涉反。」","sentenceOrder":438},
  {"id":"s_work_han_thu_38_439","chapterId":"ch_work_han_thu_38","textTraditional":"〔一九〕應劭曰：「鄧侯國。」","sentenceOrder":439},
  {"id":"s_work_han_thu_38_440","chapterId":"ch_work_han_thu_38","textTraditional":"〔二０〕應劭曰：「在朝水之陽。」","sentenceOrder":440},
  {"id":"s_work_han_thu_38_441","chapterId":"ch_work_han_thu_38","textTraditional":"〔二一〕師古曰：「即淮南所云魯陽公與韓戰日反三舍者也。滍音峙，又音雉。」","sentenceOrder":441},
  {"id":"s_work_han_thu_38_442","chapterId":"ch_work_han_thu_38","textTraditional":"〔二二〕師古曰：「漢記云朔五年以零陵泠道之舂陵鄉封長沙王子買為舂陵侯。至戴侯仁，以舂陵地形下溼，上書徙南陽。元帝許之，以蔡陽白水鄉徙仁為舂陵侯。」","sentenceOrder":442},
  {"id":"s_work_han_thu_38_443","chapterId":"ch_work_han_thu_38","textTraditional":"〔二三〕師古曰：「廖音力救反。左氏傳作飂字，其音同耳。」","sentenceOrder":443},
  {"id":"s_work_han_thu_38_444","chapterId":"ch_work_han_thu_38","textTraditional":"〔二四〕師古曰：「俞音踰。」","sentenceOrder":444},
  {"id":"s_work_han_thu_38_445","chapterId":"ch_work_han_thu_38","textTraditional":"〔二五〕應劭曰：「在桐柏下復山之陽。」師古曰：「復音房目反。」","sentenceOrder":445},
  {"id":"s_work_han_thu_38_446","chapterId":"ch_work_han_thu_38","textTraditional":"南郡，秦置，高帝元年更為臨江郡，五年復故。景帝二年復為臨江，中二年復故。莽曰南順。屬荊州。戶十二萬五千五百七十九，口七十一萬八千五百四十。有發弩官。〔一〕縣十八：江陵，故楚郢都，楚文王自丹陽徙此。後九世平王城之。後十世秦拔我郢，徙（東）〔陳〕。莽曰江陸。臨沮，禹貢南條荊山在東北，漳水所出，東至江陵入陽水，陽水入沔，行六百里。〔二〕夷陵，都尉治。莽曰居利。〔三〕華容，雲夢澤在南，荊州藪。夏水首受江，東入沔，行五百里。〔四〕宜城，故鄢，惠帝三年更名。郢，楚別邑，故郢。莽曰郢亭。邔，〔五〕當陽，中盧，〔六〕枝江，故羅國。江沱出西，東入江。〔七〕襄陽，莽曰相陽。〔八〕編，有雲夢官。莽曰南順。〔九〕秭歸，歸鄉，故歸國。〔一０〕夷道，莽曰江南。〔一一〕州陵，莽曰江夏。若，楚昭王畏吳，自郢徙此，後復還郢。〔一二〕巫，夷水東至夷道入江，過郡二，行五百四十里。有鹽官。〔一三〕高成。洈山，洈水所出，東入繇。繇水南至華容入江，過郡二，行五百里。莽曰言程。〔一四〕〔一〕　師古曰：「主教放弩也。」","sentenceOrder":446},
  {"id":"s_work_han_thu_38_447","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「沮水出漢中房陵，東入江。」師古曰：「沮水即左傳所云『江、漢、沮、漳，楚之望也』。音千余反。」","sentenceOrder":447},
  {"id":"s_work_han_thu_38_448","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　應劭曰：「夷山在西北。」","sentenceOrder":448},
  {"id":"s_work_han_thu_38_449","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　應劭曰：「春秋『許遷于容城』是。」","sentenceOrder":449},
  {"id":"s_work_han_thu_38_450","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　孟康曰：「音忌。」師古曰：「音其已反。」","sentenceOrder":450},
  {"id":"s_work_han_thu_38_451","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「在襄陽縣南。今猶有次廬村。以隋室諱忠，故改忠為次。」","sentenceOrder":451},
  {"id":"s_work_han_thu_38_452","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「沱即江別出者也，音徒何反。」","sentenceOrder":452},
  {"id":"s_work_han_thu_38_453","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　應劭曰：「在襄水之陽。」","sentenceOrder":453},
  {"id":"s_work_han_thu_38_454","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　孟康曰：「編音鞭。」","sentenceOrder":454},
  {"id":"s_work_han_thu_38_455","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕孟康曰：「秭音姊。」","sentenceOrder":455},
  {"id":"s_work_han_thu_38_456","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕應劭曰：「夷水出巫，東入江。」","sentenceOrder":456},
  {"id":"s_work_han_thu_38_457","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕師古曰：「春秋傳作鄀，其音同。」","sentenceOrder":457},
  {"id":"s_work_han_thu_38_458","chapterId":"ch_work_han_thu_38","textTraditional":"〔一三〕應劭曰：「巫山在西南。」","sentenceOrder":458},
  {"id":"s_work_han_thu_38_459","chapterId":"ch_work_han_thu_38","textTraditional":"〔一四〕師古曰：「洈音危。繇讀曰由。」","sentenceOrder":459},
  {"id":"s_work_han_thu_38_460","chapterId":"ch_work_han_thu_38","textTraditional":"江夏郡，高帝置。屬荊州。〔一〕戶五萬六千八百四十四，口二十一萬九千二百一十八。縣十四：西陵，有雲夢官。莽曰江陽。竟陵，章山在東北，古文以為內方山。鄖鄉，楚鄖公邑。莽曰守平。〔二〕西陽，襄，莽曰襄非。邾，衡山王吳芮都。〔三〕軑，故弦子國。〔四〕鄂，〔五〕安陸，橫尾山在東北，古文以為陪尾山。沙羨，〔六〕蘄春，〔七〕鄳，〔八〕雲杜，〔九〕下雉，莽曰閏光。〔一０〕鍾武。侯國。莽曰當利。","sentenceOrder":460},
  {"id":"s_work_han_thu_38_461","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「沔水自江別至南郡華容為夏水，過郡入江，故曰江夏。」","sentenceOrder":461},
  {"id":"s_work_han_thu_38_462","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「音云。」","sentenceOrder":462},
  {"id":"s_work_han_thu_38_463","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「音朱，又音誅。」","sentenceOrder":463},
  {"id":"s_work_han_thu_38_464","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　孟康曰：「音汏。」師古曰：「又音徒系反。」","sentenceOrder":464},
  {"id":"s_work_han_thu_38_465","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「音五各反。」","sentenceOrder":465},
  {"id":"s_work_han_thu_38_466","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　晉灼曰：「羨音夷。」","sentenceOrder":466},
  {"id":"s_work_han_thu_38_467","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　晉灼曰：「音祈。」","sentenceOrder":467},
  {"id":"s_work_han_thu_38_468","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　蘇林曰：「音盲。」師古曰：「音萌，又音莫耿反。」","sentenceOrder":468},
  {"id":"s_work_han_thu_38_469","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　應劭曰：「左傳『若敖取于〈云阝〉』，今〈云阝〉亭是也。」師古曰：「〈云阝〉音云。」","sentenceOrder":469},
  {"id":"s_work_han_thu_38_470","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕如淳曰：「音羊氏反。」","sentenceOrder":470},
  {"id":"s_work_han_thu_38_471","chapterId":"ch_work_han_thu_38","textTraditional":"廬江郡，故淮南，文帝十六年別為國。金蘭西北有東陵鄉，淮水出。屬揚州。廬江出陵陽東南，北入江。〔一〕戶十二萬四千三百八十三，口四十五萬七千三百三十三。有樓船官。縣十二：舒，故國。莽曰昆鄉。居巢，〔二〕龍舒，〔三〕臨湖，雩婁，決水北至蓼入淮，又有灌水，亦北至蓼入決，過郡二，行五百一十里。〔四〕襄安，莽曰廬江亭也。樅陽，〔五〕尋陽，禹貢九江在南，皆東合為大江。灊，天柱山在南。有祠。沘山，沘水所出，北至壽春入芍陂。〔六〕睆，有鐵官。〔七〕湖陵邑，北湖在南。松茲。侯國。莽曰誦善。","sentenceOrder":471},
  {"id":"s_work_han_thu_38_472","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「故廬子國。」","sentenceOrder":472},
  {"id":"s_work_han_thu_38_473","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「春秋『楚人圍巢』。巢，國也。」","sentenceOrder":473},
  {"id":"s_work_han_thu_38_474","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　應劭曰：「群舒之邑。」","sentenceOrder":474},
  {"id":"s_work_han_thu_38_475","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「雩音許于反。婁音力于反。」","sentenceOrder":475},
  {"id":"s_work_han_thu_38_476","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「音七容反。」","sentenceOrder":476},
  {"id":"s_work_han_thu_38_477","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　晉灼曰：「音潛。」師古曰：「沘音比，又音布几反。芍音酌，又音鵲。」","sentenceOrder":477},
  {"id":"s_work_han_thu_38_478","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「音胡管反。」","sentenceOrder":478},
  {"id":"s_work_han_thu_38_479","chapterId":"ch_work_han_thu_38","textTraditional":"九江郡，秦置，高帝四年更名為淮南國，武帝元狩元年復故。莽曰延平。屬揚州。〔一〕戶十五萬五十二，口七十八萬五百二十五。有陂官、湖官。縣十五：壽春邑，楚考烈王自陳徙此。浚遒，〔二〕成德，莽曰平阿。橐皋，〔三〕陰陵，莽曰陰陸。歷陽，都尉治。莽曰明義。當塗，侯國。莽曰山聚。〔四〕鍾離，莽曰蠶富。〔五〕合肥，〔六〕東城，莽曰武城。博鄉，侯國。莽曰揚陸。曲陽，侯國。莽曰延平亭。〔七〕建陽，全椒，阜陵。莽曰阜陸。","sentenceOrder":479},
  {"id":"s_work_han_thu_38_480","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「江自廬江尋陽分為九。」","sentenceOrder":480},
  {"id":"s_work_han_thu_38_481","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　晉灼曰：「音酋熟之酋。」師古曰：「浚音峻。遒音才由反。」","sentenceOrder":481},
  {"id":"s_work_han_thu_38_482","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　孟康曰：「音拓姑。」","sentenceOrder":482},
  {"id":"s_work_han_thu_38_483","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　應劭曰：「禹所娶塗山侯國也。有禹虛。」","sentenceOrder":483},
  {"id":"s_work_han_thu_38_484","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「鍾離子國。」","sentenceOrder":484},
  {"id":"s_work_han_thu_38_485","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　應劭曰：「夏水出父城東南，至此與淮合，故曰合肥。」","sentenceOrder":485},
  {"id":"s_work_han_thu_38_486","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　應劭曰：「在淮曲之陽。」","sentenceOrder":486},
  {"id":"s_work_han_thu_38_487","chapterId":"ch_work_han_thu_38","textTraditional":"山陽郡，故梁。景帝中六年別為山陽國。武帝建元五年別為郡。莽曰鉅野。屬兗州。戶十七萬二千八百四十七，口八十萬一千二百八十八。有鐵官。縣二十三：昌邑，武帝天漢四年更山陽為昌邑國。有梁丘鄉。春秋傳曰「宋、齊會于梁丘」。南平陽，莽曰黽平。〔一〕成武，有楚丘亭。齊桓公所城，遷衛文公於此。子成公徙濮陽。莽曰成安。湖陵，禹貢「浮于泗、淮，通于河」，水在南。莽曰湖陸。〔二〕東緍，〔三〕方與，〔四〕橐，莽曰高平。〔五〕鉅野，大野澤在北，兗州藪。單父，都尉治。莽曰利父。〔六〕薄，〔七〕都關，城都，侯國。莽曰城穀。黃，侯國。爰戚，侯國。莽曰戚亭。郜成，侯國。莽曰告成。中鄉，侯國。平樂，侯國。（淮）〔包〕水東北至（泲）〔沛〕入泗。鄭，侯國。瑕丘，〔八〕甾鄉，侯國。〔九〕栗鄉，侯國。莽曰足亭。曲鄉，侯國。西陽。侯國。","sentenceOrder":487},
  {"id":"s_work_han_thu_38_488","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　孟康曰：「邾庶期以漆來奔，又城漆，今漆鄉是。」","sentenceOrder":488},
  {"id":"s_work_han_thu_38_489","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「尚書一名湖。章帝封東平王倉子為湖陵侯，更名湖陵。」","sentenceOrder":489},
  {"id":"s_work_han_thu_38_490","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「春秋僖二十三年『齊侯伐宋圍緡』，即謂此。音旻。」","sentenceOrder":490},
  {"id":"s_work_han_thu_38_491","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　晉灼曰：「音房豫。」","sentenceOrder":491},
  {"id":"s_work_han_thu_38_492","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　臣瓚曰：「音拓。」","sentenceOrder":492},
  {"id":"s_work_han_thu_38_493","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「音善甫。」","sentenceOrder":493},
  {"id":"s_work_han_thu_38_494","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　臣瓚曰：「湯所都。」","sentenceOrder":494},
  {"id":"s_work_han_thu_38_495","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　應劭曰：「瑕丘在西南。」","sentenceOrder":495},
  {"id":"s_work_han_thu_38_496","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「音側其反。」","sentenceOrder":496},
  {"id":"s_work_han_thu_38_497","chapterId":"ch_work_han_thu_38","textTraditional":"濟陰郡，故梁。景帝中六年別為濟陰國。宣帝甘露二年更名定陶。禹貢荷澤在定陶東。屬兗州。〔一〕戶二十九萬二（千）〔十〕五，口百三十八萬六千二百七十八。縣九：定陶，故曹國，周武王弟叔振鐸所封。禹貢陶丘在西南。陶丘亭。冤句，莽改定陶曰濟平，冤句縣曰濟平亭。〔二〕呂都，莽曰祈都。葭密，〔三〕成陽，有堯（家）〔冢〕靈臺。禹貢雷澤在西北。鄄城，莽曰鄄良。〔四〕句陽，〔五〕秺，莽曰萬歲。〔六〕乘氏。泗水東南至睢陵入淮，過郡六，行千一百一十里。〔七〕","sentenceOrder":497},
  {"id":"s_work_han_thu_38_498","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「荷音柯。」","sentenceOrder":498},
  {"id":"s_work_han_thu_38_499","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「句音劬。」","sentenceOrder":499},
  {"id":"s_work_han_thu_38_500","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「葭音家。」","sentenceOrder":500},
  {"id":"s_work_han_thu_38_501","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「鄄音工掾反。」","sentenceOrder":501},
  {"id":"s_work_han_thu_38_502","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「左氏傳『句瀆之丘』也。」師古曰：「音鉤。」","sentenceOrder":502},
  {"id":"s_work_han_thu_38_503","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　孟康曰：「音妒。」","sentenceOrder":503},
  {"id":"s_work_han_thu_38_504","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　應劭曰：「春秋『敗宋師于乘丘』是也。」師古曰：「睢音雖。」","sentenceOrder":504},
  {"id":"s_work_han_thu_38_505","chapterId":"ch_work_han_thu_38","textTraditional":"沛郡，故秦泗水郡。高帝更名。莽曰吾符。屬豫州。戶四十萬九千七十九，口二百三萬四百八十。縣三十七：相，莽曰吾符亭。龍亢，〔一〕竹，莽曰篤亭。〔二〕穀陽，〔三〕蕭，故蕭叔國，宋別封附庸也。向，故國。春秋曰「莒人入向」。姜姓，炎帝後。〔四〕銍，〔五〕廣戚，侯國。莽曰力聚。下蔡，故州來國，為楚所滅，後吳取之，至夫差遷昭侯於此。後四世侯齊竟為楚所滅。豐，莽曰吾豐。鄲，莽曰單城。〔六〕譙，莽曰延成亭。蘄，〈垂，字形见说文〉鄉。高祖破黥布。都尉治。莽曰蘄城。〔七〕〈工虫〉，莽曰貢。〔八〕輒與，莽曰華樂。山桑，公丘，侯國。故滕國，周懿王子錯叔繡所封，三十一世為齊所滅。〔九〕符離，莽曰符合。敬丘，侯國。〔一０〕夏丘，莽曰歸思。洨，侯國。垓下，高祖破項羽。莽曰（有）〔育〕成。〔一一〕沛，有鐵官。芒，莽曰博治。〔一二〕建成，侯國。城父，夏肥水東南至下蔡入淮，過郡二，行六百二十里。莽曰思善。建平，侯國。莽曰田平。酇，莽曰贊治。〔一三〕栗，侯國。莽曰成富。扶陽，侯國。莽曰合治。高，侯國。高柴，侯國。漂陽，〔一四〕平阿，侯國。莽曰平寧。東鄉，臨都，義成，祈鄉。侯國。莽曰會穀。","sentenceOrder":505},
  {"id":"s_work_han_thu_38_506","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　晉灼曰：「亢音岡。」","sentenceOrder":506},
  {"id":"s_work_han_thu_38_507","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　李奇曰：「今竹邑。」","sentenceOrder":507},
  {"id":"s_work_han_thu_38_508","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　應劭曰：「在穀水之陽。」","sentenceOrder":508},
  {"id":"s_work_han_thu_38_509","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「音餉。」","sentenceOrder":509},
  {"id":"s_work_han_thu_38_510","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「銍音竹乙反。」","sentenceOrder":510},
  {"id":"s_work_han_thu_38_511","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　孟康曰：「音多。」","sentenceOrder":511},
  {"id":"s_work_han_thu_38_512","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「〈垂，字形见说文〉音直恚反。」","sentenceOrder":512},
  {"id":"s_work_han_thu_38_513","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「〈工虫〉亦音貢。」","sentenceOrder":513},
  {"id":"s_work_han_thu_38_514","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「左氏傳云『郜、雍、曹、滕，文之昭也』，系本亦云『錯叔繡，文王子』，而此志云懿王子，未詳其義耳。」","sentenceOrder":514},
  {"id":"s_work_han_thu_38_515","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕應劭曰：「春秋『遇於犬丘』，明帝更名（犬）〔大〕丘。」","sentenceOrder":515},
  {"id":"s_work_han_thu_38_516","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕應劭曰：「洨水所出，南入淮。」師古曰：「洨音肴。」","sentenceOrder":516},
  {"id":"s_work_han_thu_38_517","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕應劭曰：「世祖更名臨睢。睢水出焉。」師古曰：「芒音莫郎反。睢音雖。」","sentenceOrder":517},
  {"id":"s_work_han_thu_38_518","chapterId":"ch_work_han_thu_38","textTraditional":"〔一三〕應劭曰：「音嵯。」師古曰：「此縣本為〈虚阝〉，應音是也。中古以來借酇字為之耳，讀皆為〈虚阝〉，而莽呼為贊治，則此縣亦有贊音。」","sentenceOrder":518},
  {"id":"s_work_han_thu_38_519","chapterId":"ch_work_han_thu_38","textTraditional":"〔一四〕如淳曰：「漂音票。」","sentenceOrder":519},
  {"id":"s_work_han_thu_38_520","chapterId":"ch_work_han_thu_38","textTraditional":"魏郡，高帝置。莽曰魏城。屬冀州。戶二十一萬二千八百四十九，口九十萬九千六百五十五。縣十八：鄴，故大河在東北入海。館陶，河水別出為屯氏河，東北至章武入海，過郡四，行千五百里。斥丘，莽曰利丘。〔一〕沙，內黃，清河水出南。〔二〕清淵，〔三〕魏，都尉治。莽曰魏城亭。〔四〕繁陽，〔五〕元城，〔六〕梁期，黎陽，莽曰黎蒸。〔七〕即裴，侯國。莽曰即是。〔八〕武始，漳水東至邯鄲入漳，又有拘澗水，東北至邯鄲入白渠。〔九〕邯會，侯國。〔一０〕陰安，平恩，侯國。莽曰延平。邯溝，侯國。〔一一〕武安。欽口山，白渠水所出，東至列人入漳。又有浸水，東北至東昌入虖池河，過郡五，行六百一里。有鐵官。莽曰桓安。〔一二〕","sentenceOrder":520},
  {"id":"s_work_han_thu_38_521","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「斥丘在西南也。」師古曰：「闞駰云地多斥鹵，故曰斥丘。」","sentenceOrder":521},
  {"id":"s_work_han_thu_38_522","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「春秋『吳子、晉侯會于黃池』。今黃澤在西。陳留有外黃，故加內云。」臣瓚曰：「國語曰『吳子會諸侯于黃池，掘溝於齊、魯之間』。今陳外黃有黃溝是也。史記曰『伐宋取黃池』。然則不得在魏郡明矣。」師古曰：「瓚說是也，應說失之。」","sentenceOrder":522},
  {"id":"s_work_han_thu_38_523","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　應劭曰：「清河在西北。」","sentenceOrder":523},
  {"id":"s_work_han_thu_38_524","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　應劭曰：「魏武侯別都。」","sentenceOrder":524},
  {"id":"s_work_han_thu_38_525","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「在繁水之陽。」張晏曰：「其界為繁淵。」","sentenceOrder":525},
  {"id":"s_work_han_thu_38_526","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　應劭曰：「魏武侯公子元食邑於此，因而遂氏焉。」","sentenceOrder":526},
  {"id":"s_work_han_thu_38_527","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　晉灼曰：「黎山在其南，河水經其東。其山上碑云縣取山之名，取水之陽以為名。」","sentenceOrder":527},
  {"id":"s_work_han_thu_38_528","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　應劭曰：「裴音非。」","sentenceOrder":528},
  {"id":"s_work_han_thu_38_529","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　應劭曰：「拘音矩。」","sentenceOrder":529},
  {"id":"s_work_han_thu_38_530","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕張晏曰：「漳水之別，自城西南與邯山之水會，今城旁猶有溝渠在也。」師古曰：「邯音下安反。」","sentenceOrder":530},
  {"id":"s_work_han_thu_38_531","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕師古曰：「邯水之溝。」","sentenceOrder":531},
  {"id":"s_work_han_thu_38_532","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕師古曰：「浸音子衽反。虖音呼。池音徙何反。其下並同。」","sentenceOrder":532},
  {"id":"s_work_han_thu_38_533","chapterId":"ch_work_han_thu_38","textTraditional":"鉅鹿郡，秦置。屬冀州。戶十五萬五千九百五十一，口八十二萬七千一百七十七。縣二十：鉅鹿，禹貢大陸澤在北。紂所作沙丘臺在東北七十里。〔一〕南〈糸言糸〉，莽曰富平。〔二〕廣阿，象氏，侯國。莽曰寧昌。廮陶，〔三〕宋子，莽曰宜子。楊氏，莽曰功陸。臨平，下曲陽，都尉治。〔四〕貰，〔五〕郻，莽曰秦聚。〔六〕新巿，侯國。莽曰巿樂。堂陽，有鹽官。嘗分為（涇）〔經〕縣。〔七〕安定，侯國。敬武，歷鄉，侯國。莽曰歷聚。樂信，侯國。武陶，侯國。柏鄉，侯國。安鄉。侯國。","sentenceOrder":533},
  {"id":"s_work_han_thu_38_534","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「鹿，林之大者也。」臣瓚曰：「山足曰鹿。」師古曰：「應說是。」","sentenceOrder":534},
  {"id":"s_work_han_thu_38_535","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　孟康曰：「〈糸言糸〉音良全反。」","sentenceOrder":535},
  {"id":"s_work_han_thu_38_536","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「廮音一井反。」","sentenceOrder":536},
  {"id":"s_work_han_thu_38_537","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　應劭曰：「晉荀吳滅鼓，今鼓聚昔陽亭是也。」師古曰：「常山有上曲陽，故此云下。」","sentenceOrder":537},
  {"id":"s_work_han_thu_38_538","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「音式制反。」","sentenceOrder":538},
  {"id":"s_work_han_thu_38_539","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「音苦么反。」","sentenceOrder":539},
  {"id":"s_work_han_thu_38_540","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　應劭曰：「在堂水之陽。」","sentenceOrder":540},
  {"id":"s_work_han_thu_38_541","chapterId":"ch_work_han_thu_38","textTraditional":"常山郡，高帝置。莽曰井關。屬冀州。〔一〕戶十四萬一千七百四十一，口六十七萬七千九百五十六。縣十八：元氏，沮水首受中丘西山窮泉谷，東至堂陽入黃河。莽曰井關亭。〔二〕石邑，井陘山在西，洨水所出，東南至廮陶入泜。〔三〕桑中，侯國。靈壽，中山桓公居此。禹貢衛水出東北，東入虖池。蒲吾，有鐵山。大白渠水首受綿曼水，東南至下曲陽入斯洨。〔四〕上曲陽，恆山北谷在西北。有祠。并州山。禹貢恆水所出，東入滱。莽曰常山亭。〔五〕九門，莽曰久門。井陘，〔六〕房子，贊皇山，（石）濟水所出，東至廮陶入泜。莽曰多子。〔七〕中丘，逢山長谷，（諸）〔渚〕水所出，東至張邑入濁。莽曰直聚。封斯，侯國。關，平棘，〔八〕鄗，世祖即位，更名高邑。莽日禾成亭。〔九〕樂陽，侯國。莽曰暢苗。平臺，侯國。莽曰順臺。都鄉，侯國。有鐵官。莽曰分鄉。南行唐。牛飲山白陸谷，滋水所出，東至新市入虖池。都尉治。莽曰延億。","sentenceOrder":541},
  {"id":"s_work_han_thu_38_542","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　張晏曰：「恆山在西，避文帝諱，故改曰常山。」","sentenceOrder":542},
  {"id":"s_work_han_thu_38_543","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「闞駰云趙公子元之封邑，故曰元氏。」","sentenceOrder":543},
  {"id":"s_work_han_thu_38_544","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「洨音效，又音爻。泜音脂，又音丁計反。其後亦同。」","sentenceOrder":544},
  {"id":"s_work_han_thu_38_545","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　應劭曰：「蒲水出中山蒲陰，東入河。」","sentenceOrder":545},
  {"id":"s_work_han_thu_38_546","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「滱音彄。」","sentenceOrder":546},
  {"id":"s_work_han_thu_38_547","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　應劭曰：「井陘山在南，音刑。」","sentenceOrder":547},
  {"id":"s_work_han_thu_38_548","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「濟音子詣反。」","sentenceOrder":548},
  {"id":"s_work_han_thu_38_549","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　應劭曰：「伐晉取棘蒲也。」師古曰：「功臣表棘蒲侯陳武，平棘侯林摯，是則平棘、棘蒲非一地也。應說失之。」","sentenceOrder":549},
  {"id":"s_work_han_thu_38_550","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「鄗音呼各反。」","sentenceOrder":550},
  {"id":"s_work_han_thu_38_551","chapterId":"ch_work_han_thu_38","textTraditional":"清河郡，高帝置。莽曰平河。屬冀州。戶二十萬一千七百七十四，口八十七萬五千四百二十二。縣十四：清陽，王都。東武城，繹幕，〔一〕靈，河水別出為鳴犢河，東北至蓨入屯氏河。莽曰播。〔二〕厝，莽曰厝治。〔三〕鄃，莽曰善陸。〔四〕貝丘，都尉治。〔五〕信成，張甲河首受屯氏別河，東北至蓨入漳水。{艸心}題，〔六〕東陽，侯國。莽曰胥陵。信鄉，侯國。〔七〕繚，〔八〕棗彊，復陽。莽曰樂歲。〔九〕","sentenceOrder":551},
  {"id":"s_work_han_thu_38_552","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「繹音亦。」師古曰：「本音弋尺反。」","sentenceOrder":552},
  {"id":"s_work_han_thu_38_553","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「蓨音條。其下亦同。」","sentenceOrder":553},
  {"id":"s_work_han_thu_38_554","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　應劭曰：「安帝以孝德皇后葬於厝，改曰甘陵也。」師古曰：「音趨亦反。」","sentenceOrder":554},
  {"id":"s_work_han_thu_38_555","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「音輸。」","sentenceOrder":555},
  {"id":"s_work_han_thu_38_556","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「左氏傳『齊襄公田于貝丘』是。」","sentenceOrder":556},
  {"id":"s_work_han_thu_38_557","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「{艸心}，古莎字。」","sentenceOrder":557},
  {"id":"s_work_han_thu_38_558","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　孟康曰：「順帝更名安平。」","sentenceOrder":558},
  {"id":"s_work_han_thu_38_559","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「音良笑反。」","sentenceOrder":559},
  {"id":"s_work_han_thu_38_560","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　應劭曰：「音腹。」","sentenceOrder":560},
  {"id":"s_work_han_thu_38_561","chapterId":"ch_work_han_thu_38","textTraditional":"涿郡，高帝置。莽曰垣翰。屬幽州。戶十九萬五千六百七，口七十八萬二千七百六十四。有鐵官。縣二十九：涿，桃水（受首）〔首受〕淶水，分東至安次入河。〔一〕迺，莽曰遒屏。〔二〕穀丘，故安，閻鄉，易水所出，東至范陽入濡也，并州浸。水亦至范陽入淶。〔三〕南深澤，范陽，莽曰順陰。〔四〕蠡吾，〔五〕容城，莽曰深澤。易，廣望，侯國。鄚，莽曰言符。〔六〕高陽，莽曰高亭。〔七〕州鄉，侯國。安平，都尉治。莽曰廣望亭。樊輿，侯國。莽曰握符。成，侯國。莽曰宜家。良鄉，侯國。垣水南東至陽鄉入桃。莽曰廣陽。利鄉，侯國。莽曰章符。臨鄉，侯國。益昌，侯國。莽曰有袟。陽鄉，侯國。莽曰章武。西鄉，侯國。莽曰移風。饒陽，〔八〕中水，〔九〕武垣，莽曰垣翰亭。〔一０〕阿陵，莽曰阿陸。阿武，侯國。高郭，侯國。莽曰廣隄。新昌。侯國。","sentenceOrder":561},
  {"id":"s_work_han_thu_38_562","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「涿水出上谷涿鹿縣。」師古曰：「淶音來。」","sentenceOrder":562},
  {"id":"s_work_han_thu_38_563","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「遒古遒字，音字由反。」","sentenceOrder":563},
  {"id":"s_work_han_thu_38_564","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「言易水又至范陽入淶也。濡音乃官反。」","sentenceOrder":564},
  {"id":"s_work_han_thu_38_565","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　應劭曰：「在范水之陽。」","sentenceOrder":565},
  {"id":"s_work_han_thu_38_566","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「蠡音禮。」","sentenceOrder":566},
  {"id":"s_work_han_thu_38_567","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　應劭曰：「音莫。」","sentenceOrder":567},
  {"id":"s_work_han_thu_38_568","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　應劭曰：「在高河之陽。」","sentenceOrder":568},
  {"id":"s_work_han_thu_38_569","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　應劭曰：「在饒河之陽。」","sentenceOrder":569},
  {"id":"s_work_han_thu_38_570","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　應劭曰：「在易、滱二水之間，故曰中水。」","sentenceOrder":570},
  {"id":"s_work_han_thu_38_571","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕應劭曰：「垣水出良鄉，東入桃。」","sentenceOrder":571},
  {"id":"s_work_han_thu_38_572","chapterId":"ch_work_han_thu_38","textTraditional":"勃海郡，高帝置。莽曰迎河。屬幽州。〔一〕戶二十五萬六千三百七十七，口九十萬五千一百一十九。縣二十六：浮陽，莽曰浮城。陽信，東光，有胡蘇亭。阜城，莽曰吾城。千童，〔二〕重合，南皮，莽曰迎河亭。〔三〕定，侯國。章武，有鹽官。莽曰桓章。中邑，莽曰檢陰。高成，都尉治。高樂，莽曰為鄉。參戶，侯國。成平，虖池河，民曰徒駭河。莽曰澤亭。柳，侯國。臨樂，侯國。莽曰樂亭。東平舒，〔四〕重平，安次，脩市，侯國。莽曰居寧。〔五〕文安，景成，侯國。束州，建成，章鄉，〔侯國〕。蒲領。侯國。","sentenceOrder":572},
  {"id":"s_work_han_thu_38_573","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「在勃海之濱，因以為名。」","sentenceOrder":573},
  {"id":"s_work_han_thu_38_574","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「靈帝改曰饒安。」","sentenceOrder":574},
  {"id":"s_work_han_thu_38_575","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「闞駰云章武有北皮亭，故此云南。」","sentenceOrder":575},
  {"id":"s_work_han_thu_38_576","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「代郡有平舒，故此加東。」","sentenceOrder":576},
  {"id":"s_work_han_thu_38_577","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「音條。」","sentenceOrder":577},
  {"id":"s_work_han_thu_38_578","chapterId":"ch_work_han_thu_38","textTraditional":"平原郡，高帝置。莽曰河平。屬青州。戶十五萬四千三百八十七，口六十六萬四千五百四十三。縣十九：平原，有篤馬河，東北入海，五百六十里。鬲，平當以為鬲津。莽曰河平亭。〔一〕高唐，桑欽言漯水所出。〔二〕重丘，平昌，侯國。羽，侯國。莽曰羽貞。般，莽曰分明。〔三〕樂陵，都尉治。莽曰美陽。〔四〕祝阿，莽曰安成。瑗，莽曰東順亭。阿陽，漯陰，莽曰翼成。〔五〕朸，莽曰張鄉。〔六〕富平，侯國。莽曰樂安亭。〔七〕安德，〔八〕合陽，侯國。莽曰宜鄉。樓虛，侯國。龍頟，侯國。莽曰清鄉。〔九〕安。侯國。","sentenceOrder":578},
  {"id":"s_work_han_thu_38_579","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「讀與（耿）〔隔〕同。」","sentenceOrder":579},
  {"id":"s_work_han_thu_38_580","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「漯音它合反。」","sentenceOrder":580},
  {"id":"s_work_han_thu_38_581","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　如淳曰：「般音如面般之般。」韋昭曰：「音逋垣反。」師古曰：「爾雅說九河云『鉤般』，郭璞以為水曲如鉤，流般桓也。然今其土俗用如、韋之音。」","sentenceOrder":581},
  {"id":"s_work_han_thu_38_582","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「樂音來各反。」","sentenceOrder":582},
  {"id":"s_work_han_thu_38_583","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「漯水出東武陽，東北入海。」師古曰：「漯音它合反。」","sentenceOrder":583},
  {"id":"s_work_han_thu_38_584","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　應劭曰：「音力。」","sentenceOrder":584},
  {"id":"s_work_han_thu_38_585","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　應劭曰：「明帝更名厭次。」","sentenceOrder":585},
  {"id":"s_work_han_thu_38_586","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「悳，古德字。」","sentenceOrder":586},
  {"id":"s_work_han_thu_38_587","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「今書本頟字或作額，而崔浩云有龍頟村，作額者非。」","sentenceOrder":587},
  {"id":"s_work_han_thu_38_588","chapterId":"ch_work_han_thu_38","textTraditional":"千乘郡，高帝置。莽曰建信。屬青州。〔一〕戶十一萬六千七百二十七，口四十九萬七百二十。有鐵官、鹽官、均輸官。縣十五：千乘，有鐵官。東鄒，溼沃，莽曰延亭。平安，侯國。莽曰鴻睦。博昌，時水東北至鉅定入馬車瀆，幽州浸。〔二〕蓼城，都尉治。莽曰施武。建信，狄，莽曰利居。〔三〕琅槐，〔四〕樂安，被陽，侯國。〔五〕高昌，繁安，侯國。莽曰瓦亭。高宛，莽曰常鄉。延鄉。","sentenceOrder":588},
  {"id":"s_work_han_thu_38_589","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「和帝更名樂安。」","sentenceOrder":589},
  {"id":"s_work_han_thu_38_590","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「昌水出東萊昌陽。」臣瓚曰：「從東萊至博昌，經歷宿水，不得至也。取其嘉名耳。」師古曰：「瓚說是。」","sentenceOrder":590},
  {"id":"s_work_han_thu_38_591","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　應劭曰：「安帝更名曰臨濟。」","sentenceOrder":591},
  {"id":"s_work_han_thu_38_592","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「槐音回。」","sentenceOrder":592},
  {"id":"s_work_han_thu_38_593","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　如淳曰：「一作疲，音罷軍之罷。」師古曰：「音皮彼反。」","sentenceOrder":593},
  {"id":"s_work_han_thu_38_594","chapterId":"ch_work_han_thu_38","textTraditional":"濟南郡，故齊。文帝十六年別為濟南國。景帝二年為郡。莽曰樂安。屬青州。戶十四萬七百六十一，口六十四萬二千八百八十四。縣十四：東平陵，有工官、鐵官。鄒平，臺，莽曰臺治。梁鄒，土鼓，於陵，都尉治。莽曰於陸。陽丘，般陽，莽曰濟南亭。〔一〕菅，〔二〕朝陽，侯國。莽曰脩治。〔三〕歷城，有鐵官。猇，侯國。莽曰利成。〔四〕著，〔五〕宜成。侯國。","sentenceOrder":594},
  {"id":"s_work_han_thu_38_595","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「在般水之陽。」師古曰：「般音盤。」","sentenceOrder":595},
  {"id":"s_work_han_thu_38_596","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「音姦。」","sentenceOrder":596},
  {"id":"s_work_han_thu_38_597","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　應劭曰：「在朝水之陽。」","sentenceOrder":597},
  {"id":"s_work_han_thu_38_598","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　應劭曰：「音箎。」蘇林曰：「音爻。今東朝陽有猇亭。蔡謨音由，音（鶚）〔鴞〕。」師古曰：「蔡音是，音于虯反。」","sentenceOrder":598},
  {"id":"s_work_han_thu_38_599","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「音竹庶反，又音直庶反。而韋昭誤以為蓍龜之蓍字，乃音紀咨反，失之遠矣。」","sentenceOrder":599},
  {"id":"s_work_han_thu_38_600","chapterId":"ch_work_han_thu_38","textTraditional":"泰山郡，高帝置。屬兗州。戶十七萬二千八十六，口七十二萬六千六百四。有工官。汶水出萊毋，西入濟。〔一〕縣二十四：奉高，有明堂，在西南四里，武帝元封二年造。有工官。博，有泰山廟。岱山在西北，（求山上）〔兗州山〕。茬，〔二〕盧，都尉治。濟北王都也。肥成，〔三〕蛇丘，隧鄉，故隧國。春秋曰「齊人殲于隧」也。〔四〕剛，故闡。莽曰柔。〔五〕柴，蓋，臨樂（于）〔子〕山，洙水所出，西北至蓋入池水。又沂水南至下邳入泗，過郡五，行六百里，青州浸。〔六〕梁父，〔七〕東平陽，南武陽，冠石山，治水所出，南至下邳入泗，過郡二，行九百四十里。莽曰桓宣。〔八〕萊蕪，原山，甾水所出，東至（傳）〔博〕昌入泲，幽（川）〔州〕浸。又禹貢汶水出西南入泲。汶水，桑欽所言。〔九〕鉅平，有亭亭山祠。〔一０〕嬴，有鐵官。〔一一〕牟，故國。〔一二〕蒙陰，禹貢蒙山在西南，有祠。顓臾國在蒙山下。莽曰蒙恩。華，莽曰翼陰。寧陽，侯國。莽曰寧順。乘丘，〔一三〕富陽，桃山，侯國。莽曰裒魯。桃鄉，侯國。莽曰鄣亭。式。","sentenceOrder":600},
  {"id":"s_work_han_thu_38_601","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「汶音問。毋與無同。」","sentenceOrder":601},
  {"id":"s_work_han_thu_38_602","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「茬山在東北。音淄。」師古曰：「又音仕疑反。」","sentenceOrder":602},
  {"id":"s_work_han_thu_38_603","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　應劭曰：「肥子國。」","sentenceOrder":603},
  {"id":"s_work_han_thu_38_604","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「蛇音移。隧音遂。」","sentenceOrder":604},
  {"id":"s_work_han_thu_38_605","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「春秋『秋取酄及闡』，今闡亭是也。」師古曰：「酄音驩。」","sentenceOrder":605},
  {"id":"s_work_han_thu_38_606","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「蓋讀如本字，又音古盍反。洙音殊。」","sentenceOrder":606},
  {"id":"s_work_han_thu_38_607","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「以山名縣也。父音甫。」","sentenceOrder":607},
  {"id":"s_work_han_thu_38_608","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　應劭曰：「武水所出，南入泗。」","sentenceOrder":608},
  {"id":"s_work_han_thu_38_609","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「泲音子禮反。」","sentenceOrder":609},
  {"id":"s_work_han_thu_38_610","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕應劭曰：「左氏傳『陽虎入于酄陽關以叛』。今陽關亭是也。」","sentenceOrder":610},
  {"id":"s_work_han_thu_38_611","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕師古曰：「音盈。」","sentenceOrder":611},
  {"id":"s_work_han_thu_38_612","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕應劭曰：「附庸也。」師古曰：「春秋桓十五年『牟人來朝』，即此也。」","sentenceOrder":612},
  {"id":"s_work_han_thu_38_613","chapterId":"ch_work_han_thu_38","textTraditional":"〔一三〕師古曰：「春秋莊公十五年『公敗宋師于乘丘』，即此是也。」","sentenceOrder":613},
  {"id":"s_work_han_thu_38_614","chapterId":"ch_work_han_thu_38","textTraditional":"齊郡，秦置。莽曰濟南。屬青州。戶十五萬四千八百二十六，口五十五萬四千四百四十四。縣十二：臨淄，師尚父所封。如水西北至梁鄒入泲。有服官、鐵官。莽曰齊陵。〔一〕昌國，德會水西北至西安入如。利，莽曰利治。西安，莽曰東寧。鉅定，馬車瀆水首受鉅定，東北至琅槐入海。廣，為山，濁水所出，東北至廣饒入鉅定。廣饒，昭南，臨朐，有逢山祠。石膏山，洋水所出，東北至廣饒入鉅定。莽曰監朐。〔二〕北鄉，侯國。莽曰禺聚。平廣，侯國。臺鄉。","sentenceOrder":614},
  {"id":"s_work_han_thu_38_615","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「齊獻公自營丘徙此。」臣瓚曰：「臨淄即營丘也。故晏子曰：『始爽鳩氏居之，逢伯陵居之，太公居之。』又曰：『先君太公築營之丘。』今齊之城中有丘，即營丘也。」師古曰：「瓚說是也。築營之丘，言於營丘地築城邑。」","sentenceOrder":615},
  {"id":"s_work_han_thu_38_616","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「臨朐山有伯氏駢邑。」師古曰：「朐音劬。洋音祥。」","sentenceOrder":616},
  {"id":"s_work_han_thu_38_617","chapterId":"ch_work_han_thu_38","textTraditional":"北海郡，景帝中二年置。屬青州。戶十二萬七千，口五十九萬三千一百五十九。縣二十六：營陵，或曰營丘。莽曰北海亭。〔一〕劇魁，侯國。莽曰上符。安丘，莽曰誅郅。〔二〕瓡，侯國。莽曰道德。〔三〕淳于，〔四〕益，莽曰探陽。平壽，〔五〕劇，侯國。都昌，有鹽官。平望，侯國。莽曰所聚。平的，侯國。〔六〕柳泉，侯國。莽曰弘睦。壽光，有鹽官。莽曰翼平亭。〔七〕樂望，侯國。饒，侯國。斟，故國，禹後。桑犢，覆甑山，溉水所出，東北至都昌入海。〔八〕平城，侯國。密鄉，侯國。羊石，侯國。樂都，侯國。莽曰拔壟，一作杕，一作枝也。石鄉，侯國。一作正鄉。上鄉，侯國。新成，侯國。成鄉，侯國。莽曰石樂。膠陽。侯國。","sentenceOrder":617},
  {"id":"s_work_han_thu_38_618","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「師尚父封於營丘，陵亦丘也。」臣瓚曰：「營丘即臨淄也。營陵，春秋謂之緣陵。」師古曰：「臨淄、營陵，皆舊營丘地。」","sentenceOrder":618},
  {"id":"s_work_han_thu_38_619","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　孟康曰：「今渠丘是。」","sentenceOrder":619},
  {"id":"s_work_han_thu_38_620","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「瓡即執字。」","sentenceOrder":620},
  {"id":"s_work_han_thu_38_621","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　應劭曰：「春秋『州公如曹』，左氏傳曰『淳于公如曹』。」臣瓚曰：「州，國名也，淳于公國之所都。」","sentenceOrder":621},
  {"id":"s_work_han_thu_38_622","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「古〈木斗〉尋，禹後，今〈木斗〉城是也。」臣瓚曰：「〈木斗〉尋在河南，不在此也。汲郡古文云『大康居〈木斗〉尋，羿亦居之，桀亦居之』。尚書序云『大康失邦，昆弟五人，須于洛汭』，此即大康所居為近洛也。又吳起對魏武侯曰『昔夏桀之居，左河濟，右太華，伊闕在其南，羊腸在其北』，河南城為值之。又周書度邑篇曰武王問太公曰：『吾將因有夏之居，南望過于三塗，北瞻望于有河。』有夏之居，即河南是也。」師古曰：「應說止云〈木斗〉尋本是禹後耳，何豫夏國之都乎？瓚說非也。〈木斗〉音斟。」","sentenceOrder":622},
  {"id":"s_work_han_thu_38_623","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「的音丁歷反，其字從白。」","sentenceOrder":623},
  {"id":"s_work_han_thu_38_624","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　應劭曰：「古〈木斗〉灌，禹後，今灌亭是。」","sentenceOrder":624},
  {"id":"s_work_han_thu_38_625","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「溉音功代反。」","sentenceOrder":625},
  {"id":"s_work_han_thu_38_626","chapterId":"ch_work_han_thu_38","textTraditional":"東萊郡，高帝置。屬青州。〔一〕戶十萬三千二百九十二，口五十萬二千六百九十三。縣十七：掖，莽曰掖通。腄，有之罘山祠。居上山，聲洋（丹）水所出，東北入海。〔二〕平度，莽曰利盧。黃，有萊山松林萊君祠。莽曰意母。臨朐，有海水祠。莽曰監朐。〔三〕曲成，有參山萬里沙祠。陽丘山，治水所出，南至沂入海。有鹽官。牟平，莽曰望利。東牟，有鐵官、鹽官。莽曰弘德。〈巾弦〉，有百支萊王祠。有鹽官。〔四〕育犁，昌陽，有鹽官。莽曰夙敬亭。不夜，有成山日祠。莽曰夙夜。〔五〕當利，有鹽官。莽曰（來）〔東〕萊亭。盧鄉，陽樂，侯國。莽曰延樂。陽石，莽曰識命。徐鄉。","sentenceOrder":626},
  {"id":"s_work_han_thu_38_627","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「故萊子國也。」","sentenceOrder":627},
  {"id":"s_work_han_thu_38_628","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「腄音直瑞反。洋音祥。」","sentenceOrder":628},
  {"id":"s_work_han_thu_38_629","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「齊郡已有臨朐，而東萊又有此縣，蓋各以所近為名也。斯類非一。」","sentenceOrder":629},
  {"id":"s_work_han_thu_38_630","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「〈巾弦〉音堅。」","sentenceOrder":630},
  {"id":"s_work_han_thu_38_631","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「齊地記云古有日夜出，見於東萊，故萊子立此城，以不夜為名。」","sentenceOrder":631},
  {"id":"s_work_han_thu_38_632","chapterId":"ch_work_han_thu_38","textTraditional":"琅邪郡，秦置。莽曰填夷。屬徐州。〔一〕戶二十二萬八千九百六十，口一百七萬九千一百。有鐵官。縣五十一：東武，莽曰祥善。不其，有太一、僊人祠九所，及明堂，武帝所起。〔二〕海曲，有鹽官。贛榆，〔三〕朱虛，凡山，丹水所出，東北至壽光入海。東泰山，汶水所出，東至安丘入維。有三山、五帝祠。〔四〕諸，莽曰諸并。〔五〕梧成，靈門，有高{石木}山。壺山，浯水所出，東北入淮。〔六〕姑幕，都尉治。或曰薄姑。莽曰季睦。〔七〕虛水，侯國。〔八〕臨原，侯國。莽曰填夷亭。琅邪，越王句踐嘗治此，起館臺。（存）〔有〕四時祠。〔九〕祓，侯國。〔一０〕柜，根艾水東入海。莽曰祓同。〔一一〕缾，侯國。〔一二〕邞，膠水東至平度入海。莽曰純德。〔一三〕雩（段）〔假〕，侯國。〔一四〕黔陬，故介國也。〔一五〕雲，侯國。計斤，莒子始起此，後徙莒。有鹽官。〔一六〕稻，侯國。皋虞，侯國。莽曰盈廬。平昌，長廣，有萊山萊王祠。奚養澤在西，秦地圖曰劇清（地）〔池〕，幽州藪。有鹽官。橫，故山，久台水所出，東南至東武入淮。莽曰令丘。〔一七〕東莞，術水南至下邳入泗，過郡三，行七百一十里，青州浸。〔一八〕魏其，侯國。莽曰青泉。昌，有環山祠。茲鄉，侯國。箕，侯國。禹貢濰水北至（昌）都〔昌〕入海，過郡三，行五百二十里，兗州浸也。椑，夜頭水南至海。莽曰識命。〔一九〕高廣，侯國。高鄉，侯國。柔，侯國。即來，侯國。莽曰盛睦。麗，侯國。武鄉，侯國。莽曰順理。伊鄉，侯國。新山，侯國。高陽，侯國。昆山，侯國。參封，侯國。折泉，侯國。折泉水北至莫入淮。博石，侯國。房山，侯國。慎鄉，侯國。駟望，侯國。莽曰泠鄉。〔二０〕安丘，侯國。莽曰寧鄉。高陵，侯國。莽曰蒲（睦）〔陸〕。臨安，侯國。莽曰誠信。石山。侯國。","sentenceOrder":632},
  {"id":"s_work_han_thu_38_633","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「填音竹人反。」","sentenceOrder":633},
  {"id":"s_work_han_thu_38_634","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　如淳曰：「其音基。」","sentenceOrder":634},
  {"id":"s_work_han_thu_38_635","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「贛音紺。榆音踰。」","sentenceOrder":635},
  {"id":"s_work_han_thu_38_636","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「前言汶水出萊蕪入濟，今此又言出朱虛入維，將桑欽所說有異，或者有二汶水乎？五帝祠在汶水之上。」","sentenceOrder":636},
  {"id":"s_work_han_thu_38_637","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「春秋『城諸（入）〔及〕鄆』者。」","sentenceOrder":637},
  {"id":"s_work_han_thu_38_638","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「{石木}即柘字也。浯音吾。」","sentenceOrder":638},
  {"id":"s_work_han_thu_38_639","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　應劭曰：「左氏傳曰『薄姑氏因之，而後太公因之』。」","sentenceOrder":639},
  {"id":"s_work_han_thu_38_640","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　如淳曰：「虛音墟。」","sentenceOrder":640},
  {"id":"s_work_han_thu_38_641","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「山海經云琅邪臺在琅邪之東。」","sentenceOrder":641},
  {"id":"s_work_han_thu_38_642","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「音廢。」","sentenceOrder":642},
  {"id":"s_work_han_thu_38_643","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕如淳曰：「音巨。」","sentenceOrder":643},
  {"id":"s_work_han_thu_38_644","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕如淳曰：「音瓶。」","sentenceOrder":644},
  {"id":"s_work_han_thu_38_645","chapterId":"ch_work_han_thu_38","textTraditional":"〔一三〕師古曰：「音夫，又音扶。」","sentenceOrder":645},
  {"id":"s_work_han_thu_38_646","chapterId":"ch_work_han_thu_38","textTraditional":"〔一四〕師古曰：「雩音許于反。（段）〔假〕音工下反。」","sentenceOrder":646},
  {"id":"s_work_han_thu_38_647","chapterId":"ch_work_han_thu_38","textTraditional":"〔一五〕師古曰：「陬音子侯反。」","sentenceOrder":647},
  {"id":"s_work_han_thu_38_648","chapterId":"ch_work_han_thu_38","textTraditional":"〔一六〕師古曰：「即春秋左氏傳所謂介根也，語音有輕重。」","sentenceOrder":648},
  {"id":"s_work_han_thu_38_649","chapterId":"ch_work_han_thu_38","textTraditional":"〔一七〕師古曰：「台音怡。」","sentenceOrder":649},
  {"id":"s_work_han_thu_38_650","chapterId":"ch_work_han_thu_38","textTraditional":"〔一八〕孟康曰：「故鄆邑，今鄆亭是也。」師古曰：「莞音官。術水即沭水也，音同。」","sentenceOrder":650},
  {"id":"s_work_han_thu_38_651","chapterId":"ch_work_han_thu_38","textTraditional":"〔一九〕應劭曰：「音裨。」","sentenceOrder":651},
  {"id":"s_work_han_thu_38_652","chapterId":"ch_work_han_thu_38","textTraditional":"〔二０〕師古曰：「泠音零。」","sentenceOrder":652},
  {"id":"s_work_han_thu_38_653","chapterId":"ch_work_han_thu_38","textTraditional":"東海郡，高帝置。莽曰沂平。屬徐州。〔一〕戶三十五萬八千四百一十四，口百五十五萬九千三百五十七。縣三十八：郯，故國，少昊後，盈姓。〔二〕蘭陵，莽曰蘭東。〔三〕襄賁，莽曰章信。〔四〕下邳，（萬）〔葛〕嶧山在西，古文以為嶧陽。有鐵官。莽曰閏儉。〔五〕良成，侯國。莽曰承翰。〔六〕平曲，莽曰平端。戚，〔七〕朐，秦始皇立石海上以為東門闕。有鐵官。開陽，故鄅國。莽曰厭虜。〔八〕費，故魯季氏邑。都尉治。莽曰順從。〔九〕利成，莽曰流泉。海曲，莽曰東海亭。蘭祺，侯國。莽曰溥睦。繒，故國，禹後。莽曰繒治。南成，侯國。山鄉，侯國。建鄉，侯國。即丘，莽曰就信。〔一０〕祝其，禹貢羽山在南，鯀所殛。莽曰猶亭。臨沂，厚丘，莽曰祝其亭。容丘，侯國。祠水東南至下邳入泗。東安，侯國。莽曰業亭。合鄉，莽曰合聚。承，莽曰承治。〔一一〕建陽，侯國。莽曰建力。曲陽，莽曰從羊。〔一二〕司吾，莽曰息吾。〔一三〕于鄉，侯國。平曲，侯國。莽曰端平。都陽，侯國。〔一四〕陰平，侯國。郚鄉，侯國。莽曰徐亭。〔一五〕武陽，侯國。莽曰弘亭。新陽，侯國。莽曰博聚。建陵，侯國。莽曰付亭。昌慮，侯國。莽曰慮聚。〔一六〕都平。侯國。","sentenceOrder":653},
  {"id":"s_work_han_thu_38_654","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「秦郯郡。」","sentenceOrder":654},
  {"id":"s_work_han_thu_38_655","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「音談。」","sentenceOrder":655},
  {"id":"s_work_han_thu_38_656","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　孟康曰：「次室亭魯伯是。」","sentenceOrder":656},
  {"id":"s_work_han_thu_38_657","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　應劭曰：「賁音肥。」","sentenceOrder":657},
  {"id":"s_work_han_thu_38_658","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「邳在薛，其後徙此，故曰下。」臣瓚曰：「有上邳，故曰下邳也。」師古曰：「瓚說是。」","sentenceOrder":658},
  {"id":"s_work_han_thu_38_659","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「左氏傳所謂『晉侯會吳子於良』，即此是。」","sentenceOrder":659},
  {"id":"s_work_han_thu_38_660","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　鄭氏曰：「音憂戚。」","sentenceOrder":660},
  {"id":"s_work_han_thu_38_661","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「鄅音禹。厭音一涉反。」","sentenceOrder":661},
  {"id":"s_work_han_thu_38_662","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「音祕。」","sentenceOrder":662},
  {"id":"s_work_han_thu_38_663","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕孟康曰：「古祝丘。」","sentenceOrder":663},
  {"id":"s_work_han_thu_38_664","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕應劭曰：「音證。」","sentenceOrder":664},
  {"id":"s_work_han_thu_38_665","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕應劭曰：「在淮曲之陽。」","sentenceOrder":665},
  {"id":"s_work_han_thu_38_666","chapterId":"ch_work_han_thu_38","textTraditional":"〔一三〕應劭曰：「左傳吳執鍾吾子。」","sentenceOrder":666},
  {"id":"s_work_han_thu_38_667","chapterId":"ch_work_han_thu_38","textTraditional":"〔一四〕應劭曰：「春秋『齊人遷陽』是。」","sentenceOrder":667},
  {"id":"s_work_han_thu_38_668","chapterId":"ch_work_han_thu_38","textTraditional":"〔一五〕師古曰：「郚音吾，又音魚。」","sentenceOrder":668},
  {"id":"s_work_han_thu_38_669","chapterId":"ch_work_han_thu_38","textTraditional":"〔一六〕師古曰：「慮音廬。」","sentenceOrder":669},
  {"id":"s_work_han_thu_38_670","chapterId":"ch_work_han_thu_38","textTraditional":"臨淮郡，武帝元狩六年置。莽曰淮平。戶二十六萬八千二百八十三，口百二十三萬七千七百六十四。縣二十九：徐，故國，盈姓。至春秋時徐子章禹為楚所滅。莽曰徐調。取慮，〔一〕淮浦，游水北入海。莽曰淮敬。〔二〕盱眙，都尉治。莽曰武匡。〔三〕厹猶，莽曰秉義。〔四〕僮，莽曰成信。射陽，莽曰監淮亭。〔五〕開陽，贅其，〔六〕高山，〔七〕睢陵，莽曰睢陸。〔八〕鹽瀆，有鐵官。淮陰，莽曰嘉信。淮陵，莽曰淮陸。下相，莽曰從德。〔九〕富陵，莽曰〈木{〈目目〉木}〉虜。〔一０〕東陽，播旌，莽曰著信。西平，莽曰永聚。高平，侯國。莽曰成丘。開陵，侯國。莽曰成鄉。昌陽，侯國。廣平，侯國。莽曰平寧。蘭陽，侯國。莽曰建節。襄平，侯國。莽曰相平。海陵，有江海會祠。莽曰亭間。輿，莽曰美德。堂邑，有鐵官。樂陵。侯國。","sentenceOrder":670},
  {"id":"s_work_han_thu_38_671","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「取音趨，又音秋。慮音廬。」","sentenceOrder":671},
  {"id":"s_work_han_thu_38_672","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「淮涯也。」","sentenceOrder":672},
  {"id":"s_work_han_thu_38_673","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　應劭曰：「音吁怡。」","sentenceOrder":673},
  {"id":"s_work_han_thu_38_674","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「厹音仇。」","sentenceOrder":674},
  {"id":"s_work_han_thu_38_675","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「在射水之陽。」","sentenceOrder":675},
  {"id":"s_work_han_thu_38_676","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「贅音之銳反。」","sentenceOrder":676},
  {"id":"s_work_han_thu_38_677","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　應劭曰：「高山在東南。」","sentenceOrder":677},
  {"id":"s_work_han_thu_38_678","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「睢音雖。」","sentenceOrder":678},
  {"id":"s_work_han_thu_38_679","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　應劭曰：「相水出沛國，故加下。」","sentenceOrder":679},
  {"id":"s_work_han_thu_38_680","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕〔師古曰〕：「〈木{〈目目〉木}〉音朔。」","sentenceOrder":680},
  {"id":"s_work_han_thu_38_681","chapterId":"ch_work_han_thu_38","textTraditional":"會稽郡，秦置。高帝六年為荊國，十二年更名吳。景帝四年屬江都。屬揚州。戶二十二萬三千三十八，口百三萬二千六百四。縣二十六：吳，故國，周太伯所邑。具區澤在西，揚州藪，古文以為震澤。南江在南，東入海，揚州川。莽曰泰德。曲阿，故雲陽。莽曰風美。烏傷，莽曰烏孝。毗陵，季札所居。江在北，東入海，揚州川。莽曰毗壇。〔一〕餘暨，蕭山，潘水所出，東入海。莽曰餘衍。〔二〕陽羨，諸暨，莽曰疏虜。無錫，有歷山，春申君歲祠以牛。莽曰有錫。山陰，會稽山在南，上有禹冢、禹井，揚州山。越王句踐本國。有靈文園。〔三〕丹徒，〔四〕餘姚，婁，有南武城，闔閭所起以候越。莽曰婁治。上虞，有仇亭。柯水東入海。莽曰會稽。海鹽，故武原鄉。有鹽官。莽曰展武。剡，莽曰盡忠。〔五〕由拳，柴辟，故就李鄉，吳、越戰地。〔六〕大末，穀水東北至錢唐入江。莽曰末治。〔七〕烏程，有歐陽亭。〔八〕句章，渠水東入海。餘杭，莽曰進睦。〔九〕鄞，有鎮亭，有鮚埼亭。東南有天門水入海。有越天門山。莽曰謹。〔一０〕錢唐，西部都尉治。武林山，武林水所出，東入海，行八百三十里。莽曰泉亭。鄮，莽曰海治。〔一一〕富春，莽曰誅歲。冶，〔一二〕回浦。南部都尉治。","sentenceOrder":681},
  {"id":"s_work_han_thu_38_682","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「舊延陵，漢改之。」","sentenceOrder":682},
  {"id":"s_work_han_thu_38_683","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「吳王闔閭弟夫概之所邑。」師古曰：「應說非也。暨音既。下諸暨亦同。潘音甫元反。」","sentenceOrder":683},
  {"id":"s_work_han_thu_38_684","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「靈文侯，薄太后父。」","sentenceOrder":684},
  {"id":"s_work_han_thu_38_685","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「即春秋云朱方也。」","sentenceOrder":685},
  {"id":"s_work_han_thu_38_686","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「音上冉反。」","sentenceOrder":686},
  {"id":"s_work_han_thu_38_687","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　應劭曰：「古之檇李也。」師古曰：「拳音權。辟讀曰壁。檇音子遂反。」","sentenceOrder":687},
  {"id":"s_work_han_thu_38_688","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　孟康曰：「大音如闥。」","sentenceOrder":688},
  {"id":"s_work_han_thu_38_689","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「歐音烏侯反。」","sentenceOrder":689},
  {"id":"s_work_han_thu_38_690","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　孟康曰：「杭音行伍之行。」","sentenceOrder":690},
  {"id":"s_work_han_thu_38_691","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「鄞音牛斤反。鮚音結，蚌也，長一寸，廣二分，有一小蟹在其腹中。埼，曲岸也，其中多鮚，故以名亭。埼音鉅依反。」","sentenceOrder":691},
  {"id":"s_work_han_thu_38_692","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕孟康曰：「音貿。」","sentenceOrder":692},
  {"id":"s_work_han_thu_38_693","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕師古曰：「本閩越地。」","sentenceOrder":693},
  {"id":"s_work_han_thu_38_694","chapterId":"ch_work_han_thu_38","textTraditional":"丹揚郡，故鄣郡。屬江都。武帝元封二年更名丹揚。屬揚州。戶十萬七千五百四十一，口四十萬五千一百七十一。有銅官。縣十七：宛陵，彭澤聚在西南。清水西北至蕪湖入江。莽曰無宛。於{兟日}，〔一〕江乘，莽曰相武。春穀，秣陵，莽曰宣亭。故鄣，莽曰候望。〔二〕句容，涇，〔三〕丹陽，楚之先熊繹所封，十八世，文王徙郢。石城，分江水首受江，東至餘姚入海，過郡二，行千二百里。胡孰，陵陽，桑欽言淮水出東南，北入大江。蕪湖，中江出西南，東至陽羨入海，揚州川。黝，漸江水出南蠻夷中，東入海。成帝鴻嘉二年為廣德王國。莽曰愬虜。〔四〕溧陽，〔五〕歙，都尉治。〔六〕宣城。","sentenceOrder":694},
  {"id":"s_work_han_thu_38_695","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「朁音潛。」","sentenceOrder":695},
  {"id":"s_work_han_thu_38_696","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「鄣音章。」","sentenceOrder":696},
  {"id":"s_work_han_thu_38_697","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　韋昭曰：「涇水出蕪湖。」","sentenceOrder":697},
  {"id":"s_work_han_thu_38_698","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「黝音伊，字本作黟。其音同。」","sentenceOrder":698},
  {"id":"s_work_han_thu_38_699","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「溧水所出南湖也。」師古曰：「音栗。」","sentenceOrder":699},
  {"id":"s_work_han_thu_38_700","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「音攝。」","sentenceOrder":700},
  {"id":"s_work_han_thu_38_701","chapterId":"ch_work_han_thu_38","textTraditional":"豫章郡，高帝置。莽曰九江。屬揚州。戶六萬七千四百六十二，口三十五萬一千九百六十五。縣十八：南昌，莽曰宜善。廬陵，莽曰桓亭。彭澤，禹貢彭蠡澤在西。鄱陽，武陽鄉右十餘里有黃金采。鄱水西入湖漢。莽曰鄉亭。〔一〕歷陵，傅昜山、傅昜川在南，古文以為傅淺原。莽曰蒲亭。〔二〕餘汗，餘水在北，至鄡陽入湖漢。莽曰治干。〔三〕柴桑，莽曰九江亭。艾，脩水東北至彭澤入湖漢，行六百六十里。莽曰治翰。贛，豫章水出西南，北入大江。〔四〕新淦，都尉治。莽曰偶亭。〔五〕南城，盱水西北至南昌入湖漢。〔六〕建成，蜀水東至南昌入湖漢。莽曰多聚。宜春，南水東至新淦入湖漢。莽曰脩曉。海昏，莽曰宜生。〔七〕雩都，湖漢水東至彭澤入江，行千九百八十里。〔八〕鄡陽，莽曰豫章。南野，彭水東入湖漢。安平，侯國。莽曰安寧。","sentenceOrder":701},
  {"id":"s_work_han_thu_38_702","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　孟康曰：「鄱音婆。」師古曰：「采者，謂采取金之處。」","sentenceOrder":702},
  {"id":"s_work_han_thu_38_703","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「傅讀曰敷。昜，古陽字。」","sentenceOrder":703},
  {"id":"s_work_han_thu_38_704","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　應劭曰：「汗音干。」師古曰：「鄡音口堯反。」","sentenceOrder":704},
  {"id":"s_work_han_thu_38_705","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　如淳曰：「音感。」","sentenceOrder":705},
  {"id":"s_work_han_thu_38_706","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「淦水所出，西入湖漢也。」師古曰：「淦音紺，又音古含反。」","sentenceOrder":706},
  {"id":"s_work_han_thu_38_707","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「盱音香于反。」","sentenceOrder":707},
  {"id":"s_work_han_thu_38_708","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「即昌邑王賀所封。」","sentenceOrder":708},
  {"id":"s_work_han_thu_38_709","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「音于。」","sentenceOrder":709},
  {"id":"s_work_han_thu_38_710","chapterId":"ch_work_han_thu_38","textTraditional":"桂陽郡，高帝置。莽曰南平。屬荊州。戶二萬八千一百一十九，口十五萬六千四百八十八。有金官。縣十一：郴，耒山，耒山所出，西南至湘南入湖。項羽所立義帝都此。莽曰宣風。〔一〕臨武，秦水東南至湞陽入匯，行七百里。莽曰大武。〔二〕便，莽曰便屏。南平，耒陽，（春）〔舂〕山，（春）〔舂〕水所出，北至酃入湖，過郡二，行七百八十里。莽曰南平亭。〔三〕桂陽，匯水南至四會入鬱（林），過郡二，行九百里。〔四〕陽山，侯國。〔五〕曲江，莽曰除虜。含洭，〔六〕湞陽，莽曰基武。〔七〕陰山。侯國。","sentenceOrder":710},
  {"id":"s_work_han_thu_38_711","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「郴音丑林反。耒音郎內反。」","sentenceOrder":711},
  {"id":"s_work_han_thu_38_712","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「湞音丈庚反，又音貞。匯音胡賄反。」","sentenceOrder":712},
  {"id":"s_work_han_thu_38_713","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「在耒水之陽也。酃音靈。」","sentenceOrder":713},
  {"id":"s_work_han_thu_38_714","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　應劭曰：「桂水所出，東北入湘。」","sentenceOrder":714},
  {"id":"s_work_han_thu_38_715","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「今陰山也。」師古曰：「下自有陰山。應說非也。」","sentenceOrder":715},
  {"id":"s_work_han_thu_38_716","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　應劭曰：「洭水所出，東北入沅。」師古曰：「洭音匡。沅音元。」","sentenceOrder":716},
  {"id":"s_work_han_thu_38_717","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　應劭曰：「湞水出南海龍川，西入秦。」","sentenceOrder":717},
  {"id":"s_work_han_thu_38_718","chapterId":"ch_work_han_thu_38","textTraditional":"武陵郡，高帝置。莽曰建平。屬荊州。戶三萬四千一百七十七，口十八萬五千七百五十八。縣十三：索，漸水東入沅。〔一〕孱陵，莽曰孱陸。〔二〕臨沅，莽曰監元。〔三〕沅陵，莽曰沅陸。鐔成，康谷水南入海。玉山，潭水所出，東至阿林入鬱，過郡二，行七百二十里。〔四〕無陽，無水首受故且蘭，南入沅，八百九十里。〔五〕遷陵，莽曰遷陸。辰陽，三山谷，辰水所出，南入沅，七百五十里。莽曰會亭。〔六〕酉陽，〔七〕義陵，鄜梁山，序水所出，西入沅。莽曰建平。〔八〕佷山，〔九〕零陽，〔一０〕充。酉原山，酉水所出，南至沅陸入沅，行千二百里。歷山，澧水所出，東至下雋入沅，過郡二，行一千二百里。〔一一〕","sentenceOrder":718},
  {"id":"s_work_han_thu_38_719","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「順帝更名漢壽。」如淳曰：「音繩索之索。」師古曰：「沅音元。」","sentenceOrder":719},
  {"id":"s_work_han_thu_38_720","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「孱音踐。」師古曰：「音仕連反。」","sentenceOrder":720},
  {"id":"s_work_han_thu_38_721","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　應劭曰：「沅水出牂柯，入于江。」","sentenceOrder":721},
  {"id":"s_work_han_thu_38_722","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　應劭曰：「潭水所出，東入鬱。音淫。」孟康曰：「鐔音潭。」師古曰：「孟音是。」","sentenceOrder":722},
  {"id":"s_work_han_thu_38_723","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「且音子余反。」","sentenceOrder":723},
  {"id":"s_work_han_thu_38_724","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　應劭曰：「辰水所出，東入沅。」","sentenceOrder":724},
  {"id":"s_work_han_thu_38_725","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　應劭曰：「酉水所出，東入湘。」","sentenceOrder":725},
  {"id":"s_work_han_thu_38_726","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「鄜音敷。」","sentenceOrder":726},
  {"id":"s_work_han_thu_38_727","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　孟康曰：「音恆。出藥草恆山。」","sentenceOrder":727},
  {"id":"s_work_han_thu_38_728","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕應劭曰：「零水所出，東南入湘。」","sentenceOrder":728},
  {"id":"s_work_han_thu_38_729","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕師古曰：「澧音禮。雋音辭兗反。」","sentenceOrder":729},
  {"id":"s_work_han_thu_38_730","chapterId":"ch_work_han_thu_38","textTraditional":"零陵郡，武帝元鼎六年置。莽曰九疑。屬荊州。戶二萬一千九十二，口十三萬九千三百七十八。縣十：零陵，陽海山，湘水所出，北至酃入江，過郡二，行二千五百三十里。又有離水，東南至廣信入鬱林，行九百八十里。營道，九疑山在南。莽曰九疑亭。始安，夫夷，營浦，都梁，侯國。路山，資水所出，東北至益陽入沅，過郡二，行千八百里。泠道，莽曰泠陵。〔一〕泉陵，侯國。莽曰溥閏。洮陽，莽曰洮治。〔二〕鍾武。莽曰鍾桓。〔三〕","sentenceOrder":730},
  {"id":"s_work_han_thu_38_731","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「泠水出丹陽宛陵，西北入江。」臣瓚曰：「宛陵在豫章北界，相去三千里，又隔諸水，不得從下逆至泠道而復入江也。」師古曰：「瓚說是。泠音零。」","sentenceOrder":731},
  {"id":"s_work_han_thu_38_732","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　如淳曰：「洮音韜。」","sentenceOrder":732},
  {"id":"s_work_han_thu_38_733","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　應劭曰：「今重安。」","sentenceOrder":733},
  {"id":"s_work_han_thu_38_734","chapterId":"ch_work_han_thu_38","textTraditional":"漢中郡，秦置。莽曰新成。屬益州。戶十萬一千五百七十，口三十萬六百一十四。縣十二：西城，〔一〕旬陽，北山，旬水所出，南入沔。南鄭，旱山，池水所出，東北入漢。褒中，都尉治。漢陽鄉。房陵，淮山，淮水所出，東至中廬入沔。又有筑水，東至筑陽亦入沔。東山，沮水所出，東至郢入江，行七百里。〔二〕安陽，鬵谷水出西南，北入漢。在谷水出北，南入漢。〔三〕成固，沔陽，有鐵官。〔四〕鍚，莽曰鍚治。〔五〕武陵，上庸，長利。有鄖關。〔六〕","sentenceOrder":734},
  {"id":"s_work_han_thu_38_735","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「世本媯虛在西北，舜之居。」","sentenceOrder":735},
  {"id":"s_work_han_thu_38_736","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　師古曰：「筑音逐。」","sentenceOrder":736},
  {"id":"s_work_han_thu_38_737","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「鬵音潛，其字亦或從水。」","sentenceOrder":737},
  {"id":"s_work_han_thu_38_738","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　應劭曰：「沔水出武（昌）〔都〕，東南入江。」如淳曰：「此方人謂漢水為沔水。」師古曰：「漢上曰沔。音莫踐反。」","sentenceOrder":738},
  {"id":"s_work_han_thu_38_739","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「音陽。」師古曰：「即春秋所謂鍚穴。」","sentenceOrder":739},
  {"id":"s_work_han_thu_38_740","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「音云。」","sentenceOrder":740},
  {"id":"s_work_han_thu_38_741","chapterId":"ch_work_han_thu_38","textTraditional":"廣漢郡，高帝置。莽曰就都。屬益州。戶十六萬七千四百九十九，口六十六萬二千二百四十九。有工官。縣十三：梓潼，五婦山，馳水所出，南入涪，行五百五十里。莽曰子同。〔一〕汁方，莽曰美信。〔二〕涪，有孱亭。莽曰統睦。〔三〕雒，章山，雒水所出，南至新都谷入湔。有工官。莽曰吾雒。〔四〕綿竹，紫巖山，綿水所出，東至新都北入雒。都尉治。廣漢，莽曰廣信。葭明，〔五〕郪，〔六〕新都，甸氐道，白水出徼外，東至葭明入漢，過郡一，行九百五十里。莽曰致治。〔七〕白水，〔八〕剛氐道，涪水出徼外，南至墊江入漢，過郡二，行千六十九里。陰平道。北部都尉治。莽曰摧虜。","sentenceOrder":741},
  {"id":"s_work_han_thu_38_742","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「潼水所出，南入墊江。墊音徒浹反。」師古曰：「潼音童。涪音浮。」","sentenceOrder":742},
  {"id":"s_work_han_thu_38_743","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「汁音十。」","sentenceOrder":743},
  {"id":"s_work_han_thu_38_744","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　應劭曰：「涪水出廣漢，南入漢。」","sentenceOrder":744},
  {"id":"s_work_han_thu_38_745","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「湔音子先反。」","sentenceOrder":745},
  {"id":"s_work_han_thu_38_746","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「音家盲。」師古曰：「明音萌。」","sentenceOrder":746},
  {"id":"s_work_han_thu_38_747","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「音妻，又音千私反。」","sentenceOrder":747},
  {"id":"s_work_han_thu_38_748","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　李奇曰：「甸音媵。」師古曰：「音食證反。」","sentenceOrder":748},
  {"id":"s_work_han_thu_38_749","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　應劭曰：「出徼外，北入漢。」","sentenceOrder":749},
  {"id":"s_work_han_thu_38_750","chapterId":"ch_work_han_thu_38","textTraditional":"蜀郡，秦置。有小江入，并行千九百八十里。禹貢桓水出蜀山西南，行羌中，入南海。莽曰導江。屬益州。戶二十六萬八千二百七十九，口百二十四萬五千九百二十九。縣十五：成都，戶七萬六千二百五十六。有工官。郫，禹貢江沱在西，東入大江。〔一〕繁，廣都，莽曰就都亭。臨邛，僕千水東至武陽入江，過郡二，行五百一十里。有鐵官、鹽官。莽曰監邛。〔二〕青衣，禹貢蒙山谿大渡水東南至南安入渽。〔三〕江原，〈壽阝〉水首受江，南至武陽入江。莽曰邛原。〔四〕嚴道，邛來山，邛水所出，東入青衣。有木官。莽曰嚴治。綿虒，玉壘山，湔水所出，東南至江陽入江，過郡三，行千八百九十里。〔五〕旄牛，鮮水出徼外，南入若水。若水亦出徼外，南至大莋入繩，過郡二，行千六百里。〔六〕徙，〔七〕湔氐道，禹貢崏山在西徼外，江水所出，東南至江都入海，過郡七，行二千六百六十里。〔八〕汶江，渽水出徼外，南至南安，東入江，過郡三，行三千四十里。江沱在西南，東入江。〔九〕廣柔，蠶陵。莽曰步昌。","sentenceOrder":750},
  {"id":"s_work_han_thu_38_751","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　師古曰：「郫音疲。沱音徒何反。」","sentenceOrder":751},
  {"id":"s_work_han_thu_38_752","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「邛水出嚴道邛來山，東入青衣。」","sentenceOrder":752},
  {"id":"s_work_han_thu_38_753","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　應劭曰：「順帝更名漢嘉也。」師古曰：「渽音哉。」","sentenceOrder":753},
  {"id":"s_work_han_thu_38_754","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　應劭曰：「〈壽阝〉音壽。」","sentenceOrder":754},
  {"id":"s_work_han_thu_38_755","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「虒音斯。」〔師古曰〕：「湔音子千反。」","sentenceOrder":755},
  {"id":"s_work_han_thu_38_756","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「莋音才各反。」","sentenceOrder":756},
  {"id":"s_work_han_thu_38_757","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「音斯。」","sentenceOrder":757},
  {"id":"s_work_han_thu_38_758","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「音丁奚反。」","sentenceOrder":758},
  {"id":"s_work_han_thu_38_759","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　師古曰：「沱音徒何反。」","sentenceOrder":759},
  {"id":"s_work_han_thu_38_760","chapterId":"ch_work_han_thu_38","textTraditional":"犍為郡，武帝建元六年開。莽曰西順。屬益州。〔一〕戶十萬九千四百一十九，口四十八萬九千四百八十六。縣十二：僰道，莽曰僰治。〔二〕江陽，武陽，有鐵官。莽曰戢成。南安，有鹽官、鐵官。資中，符，溫水南至鄨入黚水，黚水亦南至鄨入江。莽曰符信。〔三〕牛鞞，〔四〕南廣，汾關山，符黑水所出，北至僰道入江。又有大涉水，北至符入江，過郡三，行八百四十里。漢陽，都尉治。山闟谷，漢水所出，東至鄨入延。莽曰新通。〔五〕郁〈馬阝〉，莽曰孱〈馬阝〉。〔六〕朱提，山出銀。〔七〕堂琅。","sentenceOrder":760},
  {"id":"s_work_han_thu_38_761","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「故夜郎國。」","sentenceOrder":761},
  {"id":"s_work_han_thu_38_762","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「故僰侯國也。音蒲北反。」","sentenceOrder":762},
  {"id":"s_work_han_thu_38_763","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「鄨音蔽，又音鱉。黚音紀炎反。」","sentenceOrder":763},
  {"id":"s_work_han_thu_38_764","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　孟康曰：「音髀。」師古曰：「音必爾反。」","sentenceOrder":764},
  {"id":"s_work_han_thu_38_765","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「闟音它盍反。」","sentenceOrder":765},
  {"id":"s_work_han_thu_38_766","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「〈馬阝〉音莫亞反。孱音仕連反。」","sentenceOrder":766},
  {"id":"s_work_han_thu_38_767","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　應劭曰：「朱提山在西南。」蘇林曰：「朱音銖。提音時。北方人名匕曰匙。」","sentenceOrder":767},
  {"id":"s_work_han_thu_38_768","chapterId":"ch_work_han_thu_38","textTraditional":"越嶲郡，武帝元鼎六年開。莽曰集嶲。屬益州。〔一〕戶六萬一千二百八，口四十萬八千四百五。縣十五：邛都，南山出銅。有邛池澤。遂久，繩水出徼外，東至僰道入江，過郡二，行千四百里。靈關道，臺登，孫水南至會無入若，行七百五十里。〔二〕定莋，出鹽。步北澤在南。都尉治。〔三〕會無，東山出碧。莋秦，大莋，姑復，臨池澤在南。〔四〕三絳，蘇示，{尸二}江在西北。〔五〕闌，〔六〕卑水，〔七〕灊街，〔八〕青蛉。臨池灊在北。僕水出徼外，東南至來惟入勞，過郡二，行千八百八十里。（則）〔有〕禺同山，有金馬、碧雞。〔九〕","sentenceOrder":768},
  {"id":"s_work_han_thu_38_769","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「故邛都國也。有嶲水。言越此水以章休盛也。」師古曰：「嶲音先蕊反。」","sentenceOrder":769},
  {"id":"s_work_han_thu_38_770","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「今曰臺高。」","sentenceOrder":770},
  {"id":"s_work_han_thu_38_771","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「莋音才各反。其下並同。本筰都也。」","sentenceOrder":771},
  {"id":"s_work_han_thu_38_772","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「復音扶目反。」","sentenceOrder":772},
  {"id":"s_work_han_thu_38_773","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「示讀曰祗。{尸二}，古夷字。」","sentenceOrder":773},
  {"id":"s_work_han_thu_38_774","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「音蘭。」","sentenceOrder":774},
  {"id":"s_work_han_thu_38_775","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　孟康曰：「音班。」","sentenceOrder":775},
  {"id":"s_work_han_thu_38_776","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「灊音潛，又音才心反。其下亦同。」","sentenceOrder":776},
  {"id":"s_work_han_thu_38_777","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　應劭曰：「青蛉水出西，東入江也。」師古曰：「蛉音零，禺音愚。」","sentenceOrder":777},
  {"id":"s_work_han_thu_38_778","chapterId":"ch_work_han_thu_38","textTraditional":"益州郡，武帝元封二年開。莽曰就新。屬益州。〔一〕戶八萬一千九百四十六，口五十八萬四百六十三。縣二十四：滇池，大澤在西，滇池澤在西北。有黑水祠。雙柏，同勞，銅瀨，談虜山，迷水所出，東至談稿入溫。連然，有鹽官。俞元，池在南，橋水所出，東至毋單入溫，行千九百里。懷山出銅。收靡，南山臘〔谷〕，涂水所出，西北至越嶲入繩，過郡二，行千二十里。〔二〕穀昌，秦臧，牛蘭山，即水所出，南至雙柏入僕，行八百二十里。邪龍，味，〔三〕昆澤，葉榆，葉榆澤在東。貪水首受青蛉，南至邪龍入僕，行五百里。〔四〕律高，西石空山出錫，東南盢町山出銀、鉛。〔五〕不韋，雲南，嶲唐，周水首受徼外。又有類水，西南至不韋，行六百五十里。弄棟，東農山，毋血水出，北至三絳南入繩，行五百一十里。比蘇，〔六〕賁古，北采山出錫，西羊山出銀、鉛，南烏山出錫。〔七〕毋棳，橋水首受橋山，東至中留入潭，過郡四，行三千一百二十里。莽曰有棳。〔八〕勝休，河水東至毋棳入橋。莽曰勝僰。健伶，〔九〕來唯。從〈阝虫〉山出銅。勞水出徼外，東至麋泠入南海，過郡三，行三千五百六十里。〔一０〕","sentenceOrder":778},
  {"id":"s_work_han_thu_38_779","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「故滇王國也。」師古曰：「滇音顛。其下並同。」","sentenceOrder":779},
  {"id":"s_work_han_thu_38_780","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　李奇曰：「靡音麻，即升麻，殺毒藥所出也。」師古曰：「涂音途。」","sentenceOrder":780},
  {"id":"s_work_han_thu_38_781","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　孟康曰：「音昧。」","sentenceOrder":781},
  {"id":"s_work_han_thu_38_782","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　師古曰：「葉音弋涉反。」","sentenceOrder":782},
  {"id":"s_work_han_thu_38_783","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「盢音呼鶪反。町音挺。」","sentenceOrder":783},
  {"id":"s_work_han_thu_38_784","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「比音頻二反。」","sentenceOrder":784},
  {"id":"s_work_han_thu_38_785","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「賁音奔。」","sentenceOrder":785},
  {"id":"s_work_han_thu_38_786","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「毋讀與無同。棳音之悅反，其字從木。」","sentenceOrder":786},
  {"id":"s_work_han_thu_38_787","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　應劭曰：「音鈴。」","sentenceOrder":787},
  {"id":"s_work_han_thu_38_788","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「〈阝虫〉音胡工反。泠音零。」","sentenceOrder":788},
  {"id":"s_work_han_thu_38_789","chapterId":"ch_work_han_thu_38","textTraditional":"牂柯郡，武帝元鼎六年開。莽曰同亭。有柱蒲關。屬益州。〔一〕戶二萬四千二百一十九，口十五萬三千三百六十。縣十七：故且蘭，沅水東南至益陽入江，過郡二，行二千五百三十里。〔二〕鐔封，溫水東至廣鬱入鬱，過郡二，行五百六十里。〔三〕鄨，不狼山，鄨水所出，東入沅，過郡二，行七百三十里。〔四〕漏臥，〔五〕平夷，同並，〔六〕談指，宛溫，〔七〕毋斂，剛水東至潭中入潭。莽曰有斂。〔八〕夜郎，豚水東至廣鬱。都尉治。莽曰同亭。〔九〕毋單，〔一０〕漏江，西隨，麋水西受徼外，東至麋泠入尚龍谿，過郡二，行千一百六里。都夢，壺水東南至麋泠入尚龍谿，過郡二，行千一百六十里。談稿，〔一一〕進桑，南部都尉治。有關。句町。文象水東至增食入鬱。又有盧唯水、來細水、伐水。莽曰從化。〔一二〕","sentenceOrder":789},
  {"id":"s_work_han_thu_38_790","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「臨牂柯江也。」師古曰：「牂柯，係船杙也。華陽國志云，楚頃襄王時，遣莊蹻伐夜郎，軍至且蘭，椓船於岸而步戰。既滅夜郎，以且蘭有椓船牂柯處，乃改其名為牂柯。杙音弋。」","sentenceOrder":790},
  {"id":"s_work_han_thu_38_791","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　應劭曰：「故且蘭侯邑也。且音苴。」師古曰：「音子閭反。」","sentenceOrder":791},
  {"id":"s_work_han_thu_38_792","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「鐔音尋，又音淫。」","sentenceOrder":792},
  {"id":"s_work_han_thu_38_793","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　孟康曰：「鄨音鷩。」師古曰：「音不列反。」","sentenceOrder":793},
  {"id":"s_work_han_thu_38_794","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　應劭曰：「故漏臥侯國。」","sentenceOrder":794},
  {"id":"s_work_han_thu_38_795","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　應劭曰：「故同並侯邑。並音伴。」","sentenceOrder":795},
  {"id":"s_work_han_thu_38_796","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　師古曰：「宛音於元反。」","sentenceOrder":796},
  {"id":"s_work_han_thu_38_797","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「潭音大含反。」","sentenceOrder":797},
  {"id":"s_work_han_thu_38_798","chapterId":"ch_work_han_thu_38","textTraditional":"〔九〕　應劭曰：「故夜郎侯邑。」","sentenceOrder":798},
  {"id":"s_work_han_thu_38_799","chapterId":"ch_work_han_thu_38","textTraditional":"〔一０〕師古曰：「毋讀與無同。單音丹。」","sentenceOrder":799},
  {"id":"s_work_han_thu_38_800","chapterId":"ch_work_han_thu_38","textTraditional":"〔一一〕師古曰：「稿音工老反。」","sentenceOrder":800},
  {"id":"s_work_han_thu_38_801","chapterId":"ch_work_han_thu_38","textTraditional":"〔一二〕應劭曰：「故句町國。」師古曰：「音劬挺。」","sentenceOrder":801},
  {"id":"s_work_han_thu_38_802","chapterId":"ch_work_han_thu_38","textTraditional":"巴郡，秦置。屬益州。〔一〕戶十五萬八千六百四十三，口七十萬八千一百四十八。縣十一：江州，臨江，莽曰監江。枳，〔二〕閬中，彭道將池在南，彭道魚池在西南。〔三〕墊江，〔四〕朐忍，容毋水所出，南〔入江〕。有橘官、鹽官。〔五〕安漢，是魚池在南。莽曰安新。宕渠，符特山在西南。潛水西南入江。不曹水出東北〔徐谷〕，南入灊（徐谷）。〔六〕魚復，江關，都尉治。有橘官。〔七〕充國，涪陵。莽曰巴亭。〔八〕","sentenceOrder":802},
  {"id":"s_work_han_thu_38_803","chapterId":"ch_work_han_thu_38","textTraditional":"〔一〕　應劭曰：「左氏巴子使韓服告楚。」","sentenceOrder":803},
  {"id":"s_work_han_thu_38_804","chapterId":"ch_work_han_thu_38","textTraditional":"〔二〕　如淳曰：「音徙，或音抵。」師古曰：「音之爾反。」","sentenceOrder":804},
  {"id":"s_work_han_thu_38_805","chapterId":"ch_work_han_thu_38","textTraditional":"〔三〕　師古曰：「閬音浪。」","sentenceOrder":805},
  {"id":"s_work_han_thu_38_806","chapterId":"ch_work_han_thu_38","textTraditional":"〔四〕　孟康曰：「音重疊之疊。」","sentenceOrder":806},
  {"id":"s_work_han_thu_38_807","chapterId":"ch_work_han_thu_38","textTraditional":"〔五〕　師古曰：「朐音劬。」","sentenceOrder":807},
  {"id":"s_work_han_thu_38_808","chapterId":"ch_work_han_thu_38","textTraditional":"〔六〕　師古曰：「宕音徒浪反。」","sentenceOrder":808},
  {"id":"s_work_han_thu_38_809","chapterId":"ch_work_han_thu_38","textTraditional":"〔七〕　應劭曰：「復音腹。」","sentenceOrder":809},
  {"id":"s_work_han_thu_38_810","chapterId":"ch_work_han_thu_38","textTraditional":"〔八〕　師古曰：「涪音浮。」","sentenceOrder":810},
  {"id":"s_work_han_thu_38_811","chapterId":"ch_work_han_thu_38","textTraditional":"校勘記","sentenceOrder":811},
  {"id":"s_work_han_thu_38_812","chapterId":"ch_work_han_thu_38","textTraditional":"一五二三頁　四行　先王（以）建萬國，親諸侯。　景祐本無「以」字。","sentenceOrder":812},
  {"id":"s_work_han_thu_38_813","chapterId":"ch_work_han_thu_38","textTraditional":"一五二三頁一一行　褱字與（古）懷（字）同。　景祐本無「古」「字」二字。","sentenceOrder":813},
  {"id":"s_work_han_thu_38_814","chapterId":"ch_work_han_thu_38","textTraditional":"一五二九頁一三行　（畋魚）〔畎畝〕之治也。　景祐、殿本都作「畎畝」。王先謙說作「畎畝」是。","sentenceOrder":814},
  {"id":"s_work_han_thu_38_815","chapterId":"ch_work_han_thu_38","textTraditional":"一五三０頁　二行　砥音指，又音（袛）〔抵〕。　景祐、殿本都作「抵」。王先謙說作「抵」是。","sentenceOrder":815},
  {"id":"s_work_han_thu_38_816","chapterId":"ch_work_han_thu_38","textTraditional":"一五三０頁　三行　楛音（枯）〔怙〕。　景祐、殿本都作「怙」。王先謙說作「怙」是。","sentenceOrder":816},
  {"id":"s_work_han_thu_38_817","chapterId":"ch_work_han_thu_38","textTraditional":"一五三一頁一二行　蔡、蒙，二（水）〔山〕名。　景祐、殿、局本都作「山」。王先謙說作「山」是。","sentenceOrder":817},
  {"id":"s_work_han_thu_38_818","chapterId":"ch_work_han_thu_38","textTraditional":"一五三一頁一六行　又貢（維）〔雜〕罽。　景祐、殿本都作「雜」。王先謙說作「雜」是。","sentenceOrder":818},
  {"id":"s_work_han_thu_38_819","chapterId":"ch_work_han_thu_38","textTraditional":"一五三四頁　六行　敷淺原，一名（博）〔傅〕陽山，　景祐、殿本都作「傅」。王先謙說作「傅」是。","sentenceOrder":819},
  {"id":"s_work_han_thu_38_820","chapterId":"ch_work_han_thu_38","textTraditional":"一五三七頁　六行　二百里（納）〔內〕銍。　景祐、殿本都作「內」。","sentenceOrder":820},
  {"id":"s_work_han_thu_38_821","chapterId":"ch_work_han_thu_38","textTraditional":"一五四三頁　三行　凡十三（郡）〔部〕，　楊樹達說「郡」字誤，當作「部」。按景祐、殿、局本都作「部」。","sentenceOrder":821},
  {"id":"s_work_han_thu_38_822","chapterId":"ch_work_han_thu_38","textTraditional":"一五四四頁　三行　（師）古曰茲水，秦穆公更名以章霸功，視子孫。　錢大昕說「古」下皆班氏本文，「師」字後人妄加，「沂音」上則當有「師古曰」三字。","sentenceOrder":822},
  {"id":"s_work_han_thu_38_823","chapterId":"ch_work_han_thu_38","textTraditional":"一五四六頁　八行　即左氏傳所云（伐秦）〔秦伐〕晉取武城者也。　景祐、殿、局本都作「秦伐」。","sentenceOrder":823},
  {"id":"s_work_han_thu_38_824","chapterId":"ch_work_han_thu_38","textTraditional":"一五四七頁　七行　舜妻（盲）〔育〕冢祠。　梁玉繩說竹書舜三十年葬后育於渭，育乃后名，「盲」必「育」之誤。","sentenceOrder":824},
  {"id":"s_work_han_thu_38_825","chapterId":"ch_work_han_thu_38","textTraditional":"一五四七頁　七行　〔詩曰「自杜」。〕　四字據景祐本補。","sentenceOrder":825},
  {"id":"s_work_han_thu_38_826","chapterId":"ch_work_han_thu_38","textTraditional":"一五四七頁　九行　詩芮（阨）〔〈亻母〉〕，　景祐、殿本都作「〈亻母〉」。　段玉裁說作「〈亻母〉」是。注同。","sentenceOrder":826},
  {"id":"s_work_han_thu_38_827","chapterId":"ch_work_han_thu_38","textTraditional":"一五四七頁一三行　有垂山、斜水、（淮）〔褒〕水祠三所。　汪士鋒、王先謙都說「淮水」當作「褒水」。按與上文合。","sentenceOrder":827},
  {"id":"s_work_han_thu_38_828","chapterId":"ch_work_han_thu_38","textTraditional":"一五四八頁　二行　音（（暂缺F600））〔胎〕。　景祐、殿本都作「胎」。王鳴盛說作「胎」是。","sentenceOrder":828},
  {"id":"s_work_han_thu_38_829","chapterId":"ch_work_han_thu_38","textTraditional":"一五五０頁　九行　有班氏（香）〔鄉〕亭。　景祐、殿本都作「鄉」。朱一新說作「鄉」是。","sentenceOrder":829},
  {"id":"s_work_han_thu_38_830","chapterId":"ch_work_han_thu_38","textTraditional":"一五五二頁　四行　（河主）〔句注〕、賈屋山在北。　王念孫說「河主」當作「句注」。王先謙說王說是。","sentenceOrder":830},
  {"id":"s_work_han_thu_38_831","chapterId":"ch_work_han_thu_38","textTraditional":"一五五三頁　二行　入（青）〔清〕漳。　景祐、殿本都作「清」。王鳴盛說作「清」是。","sentenceOrder":831},
  {"id":"s_work_han_thu_38_832","chapterId":"ch_work_han_thu_38","textTraditional":"一五五四頁　七行　自（僕）〔濮〕陽徙此。　景祐、殿本都作「濮」。王先謙說作「濮」是。","sentenceOrder":832},
  {"id":"s_work_han_thu_38_833","chapterId":"ch_work_han_thu_38","textTraditional":"一五五五頁一０行　春秋昭公（二）〔三〕十（一）〔二〕　王鳴盛說「二十一年」南監本作「二十二年」，當作「三十二年」。","sentenceOrder":833},
  {"id":"s_work_han_thu_38_834","chapterId":"ch_work_han_thu_38","textTraditional":"一五五七頁一一行　（畔）觀，　陳景雲、王先謙都說「畔」字衍。","sentenceOrder":834},
  {"id":"s_work_han_thu_38_835","chapterId":"ch_work_han_thu_38","textTraditional":"一五五七頁一四行　有（（暂缺F5FA））〔泲〕廟。　王先謙說「（暂缺F5FA）」當為「泲」。按景祐、殿、局本都作「泲」。","sentenceOrder":835},
  {"id":"s_work_han_thu_38_836","chapterId":"ch_work_han_thu_38","textTraditional":"一五五八頁　三行　丘一成為頓丘，謂一（成）〔頓〕而成也。　景祐、殿、局本都作「頓」。王鳴盛說作「頓」是。","sentenceOrder":836},
  {"id":"s_work_han_thu_38_837","chapterId":"ch_work_han_thu_38","textTraditional":"一五五八頁一一行　世祖（父叔）〔叔父〕名良，　景祐、殿本都作「叔父」。","sentenceOrder":837},
  {"id":"s_work_han_thu_38_838","chapterId":"ch_work_han_thu_38","textTraditional":"一五五八頁一六行　濮渠水首受（（暂缺F5FA））〔泲〕，　同上。","sentenceOrder":838},
  {"id":"s_work_han_thu_38_839","chapterId":"ch_work_han_thu_38","textTraditional":"一五六一頁一一行　〔師古曰〕：「休音許虯反。」　錢大昭說「休」字上脫「師古曰」三字。","sentenceOrder":839},
  {"id":"s_work_han_thu_38_840","chapterId":"ch_work_han_thu_38","textTraditional":"一五六三頁一四行　戶三十五萬九千（一）〔三〕百一十六，　景祐、殿本都作「三」。","sentenceOrder":840},
  {"id":"s_work_han_thu_38_841","chapterId":"ch_work_han_thu_38","textTraditional":"一五六四頁　五行　東南至淮（陵）〔浦〕入海，　齊召南說「淮陵」當作「淮浦」，各本俱誤。王先謙說齊說是。","sentenceOrder":841},
  {"id":"s_work_han_thu_38_842","chapterId":"ch_work_han_thu_38","textTraditional":"一五六六頁　九行　後十世秦拔我郢，徙（東）〔陳〕。　齊召南說「東」當作「陳」，各本俱誤。","sentenceOrder":842},
  {"id":"s_work_han_thu_38_843","chapterId":"ch_work_han_thu_38","textTraditional":"一五七０頁一二行　（淮）〔包〕水東北至（泲）〔沛〕入泗。　王先謙說「淮」當作「泡」。按景祐、殿本都作「包」。齊召南說「泲」蓋「沛」字之訛，水經泗水注引此文云「泡水東北至沛入泗」是也。","sentenceOrder":843},
  {"id":"s_work_han_thu_38_844","chapterId":"ch_work_han_thu_38","textTraditional":"一五七一頁　八行　戶二十九萬二（千）〔十〕五，　景祐、殿本都作「十」。","sentenceOrder":844},
  {"id":"s_work_han_thu_38_845","chapterId":"ch_work_han_thu_38","textTraditional":"一五七一頁一０行　有堯（家）〔冢〕靈臺。　錢大昭說「家」當作「冢」。按景祐、殿、局本都作「冢」。","sentenceOrder":845},
  {"id":"s_work_han_thu_38_846","chapterId":"ch_work_han_thu_38","textTraditional":"一五七二頁　九行　莽曰（有）〔育〕成。　景祐、殿本都作「育」。王念孫說當為「肴」字之誤。","sentenceOrder":846},
  {"id":"s_work_han_thu_38_847","chapterId":"ch_work_han_thu_38","textTraditional":"一五七三頁　七行　明帝更名（犬）〔大〕丘。　汪士鐸說「犬」當作「大」。按景祐、殿本都作「大」。","sentenceOrder":847},
  {"id":"s_work_han_thu_38_848","chapterId":"ch_work_han_thu_38","textTraditional":"一五七五頁　五行　嘗分為（涇）〔經〕縣。　景祐、殿本都作「經」。","sentenceOrder":848},
  {"id":"s_work_han_thu_38_849","chapterId":"ch_work_han_thu_38","textTraditional":"一五七六頁　四行　（石）濟水所出，　王念孫說「石」字衍。","sentenceOrder":849},
  {"id":"s_work_han_thu_38_850","chapterId":"ch_work_han_thu_38","textTraditional":"一五七六頁　四行　逢山長谷，（諸）〔渚〕水所出，　景祐本作「渚」。","sentenceOrder":850},
  {"id":"s_work_han_thu_38_851","chapterId":"ch_work_han_thu_38","textTraditional":"一五七七頁一五行　桃水（受首）〔首受〕淶水，　景祐、殿本都作「首受」。","sentenceOrder":851},
  {"id":"s_work_han_thu_38_852","chapterId":"ch_work_han_thu_38","textTraditional":"一五七九頁　四行　「侯國」二字據景祐、殿本補。","sentenceOrder":852},
  {"id":"s_work_han_thu_38_853","chapterId":"ch_work_han_thu_38","textTraditional":"一五八０頁　二行　讀與（耿）〔隔〕同。　景祐、殿本都作「隔」。","sentenceOrder":853},
  {"id":"s_work_han_thu_38_854","chapterId":"ch_work_han_thu_38","textTraditional":"一五八一頁一二行　蔡謨音由，音（鶚）〔鴞〕。　景祐、殿本都作「鴞」。","sentenceOrder":854},
  {"id":"s_work_han_thu_38_855","chapterId":"ch_work_han_thu_38","textTraditional":"一五八一頁一六行　（求山上）〔兗州山〕。　錢大昕說「求山上」三字為「兗州山」之訛。","sentenceOrder":855},
  {"id":"s_work_han_thu_38_856","chapterId":"ch_work_han_thu_38","textTraditional":"一五八二頁　一行　臨樂（于）〔子〕山，洙水所出，　景祐、殿本都作「子」。","sentenceOrder":856},
  {"id":"s_work_han_thu_38_857","chapterId":"ch_work_han_thu_38","textTraditional":"一五八二頁　三行　東至（傳）〔博〕昌入泲，幽（川）〔州〕浸。　景祐、殿本作「博」作「州」，此誤。","sentenceOrder":857},
  {"id":"s_work_han_thu_38_858","chapterId":"ch_work_han_thu_38","textTraditional":"一五八五頁　二行　居上山，聲洋（丹）水所出，　王先謙說「丹」是衍文。","sentenceOrder":858},
  {"id":"s_work_han_thu_38_859","chapterId":"ch_work_han_thu_38","textTraditional":"一五八五頁　六行　莽曰（來）〔東〕萊亭。　景祐、殿本都作「東」。王先謙說作「東」是。","sentenceOrder":859},
  {"id":"s_work_han_thu_38_860","chapterId":"ch_work_han_thu_38","textTraditional":"一五八六頁　二行　（存）〔有〕四時祠。　錢大昭說「存」當作「有」。按景祐、殿本都作「有」。","sentenceOrder":860},
  {"id":"s_work_han_thu_38_861","chapterId":"ch_work_han_thu_38","textTraditional":"一五八六頁　三行　雩（段）〔假〕，　王先謙說據顏注「段」當作「假」。按景祐本正作「假」，注同。","sentenceOrder":861},
  {"id":"s_work_han_thu_38_862","chapterId":"ch_work_han_thu_38","textTraditional":"一五八六頁　四行　秦地圖曰劇清（地）〔池〕，　據王先謙補注引于欽齊乘，「地」當作「池」。","sentenceOrder":862},
  {"id":"s_work_han_thu_38_863","chapterId":"ch_work_han_thu_38","textTraditional":"一五八六頁　七行　至（昌）都〔昌〕入海，　殿本作「都昌」。錢大昭說作「都昌」是。","sentenceOrder":863},
  {"id":"s_work_han_thu_38_864","chapterId":"ch_work_han_thu_38","textTraditional":"一五八六頁一一行　莽曰蒲（睦）〔陸〕。　景祐、殿本都作「陸」。周壽昌說作「陸」是。","sentenceOrder":864},
  {"id":"s_work_han_thu_38_865","chapterId":"ch_work_han_thu_38","textTraditional":"一五八七頁　二行　城諸（入）〔及〕鄆者。　景祐、殿本都作「及」。王先謙說作「及」是。","sentenceOrder":865},
  {"id":"s_work_han_thu_38_866","chapterId":"ch_work_han_thu_38","textTraditional":"一五八八頁　三行　（萬）〔葛〕嶧山在西。　景祐、殿本都作「葛」。王先謙說作「葛」是。","sentenceOrder":866},
  {"id":"s_work_han_thu_38_867","chapterId":"ch_work_han_thu_38","textTraditional":"一五九０頁一三行　〔師古曰〕：「〈木{〈目目〉木}〉音朔。」　齊召南說上脫「師古曰」三字，各本俱誤。","sentenceOrder":867},
  {"id":"s_work_han_thu_38_868","chapterId":"ch_work_han_thu_38","textTraditional":"一五九四頁　四行　（春）〔舂〕山，（春）〔舂〕水所出，　景祐、殿本都作「舂」。王先謙說作「舂」是。","sentenceOrder":868},
  {"id":"s_work_han_thu_38_869","chapterId":"ch_work_han_thu_38","textTraditional":"一五九四頁　五行　匯水南至四會入鬱（林），　景祐本無「林」字。王念孫說無「林」字是。","sentenceOrder":869},
  {"id":"s_work_han_thu_38_870","chapterId":"ch_work_han_thu_38","textTraditional":"一五九七頁　二行　沔水出武（昌）〔都〕，　景祐、殿本都作「都」。王鳴盛說作「都」是。","sentenceOrder":870},
  {"id":"s_work_han_thu_38_871","chapterId":"ch_work_han_thu_38","textTraditional":"一五九九頁　一行　「師古曰」三字據景祐、殿本補。","sentenceOrder":871},
  {"id":"s_work_han_thu_38_872","chapterId":"ch_work_han_thu_38","textTraditional":"一六００頁　六行　（則）〔有〕禺同山，　王先謙說「則」當作「有」。","sentenceOrder":872},
  {"id":"s_work_han_thu_38_873","chapterId":"ch_work_han_thu_38","textTraditional":"一六０一頁　四行　南山臘〔谷〕，涂水所出，　王先謙說「臘」下脫「谷」字。按各本都脫。","sentenceOrder":873},
  {"id":"s_work_han_thu_38_874","chapterId":"ch_work_han_thu_38","textTraditional":"一六０三頁一一行　容毋水所出，南〔入江〕。　王先謙說「南」下脫「入江」二字。","sentenceOrder":874},
  {"id":"s_work_han_thu_38_875","chapterId":"ch_work_han_thu_38","textTraditional":"一六０三頁一二行　不曹水出東北〔徐谷〕，南入灊（徐谷）。　王先謙說「徐谷」二字當在「東北」之下。","sentenceOrder":875},
  {"id":"s_work_han_thu_39_1","chapterId":"ch_work_han_thu_39","textTraditional":"武都郡，武帝元鼎六年置。莽曰樂平。〔一〕戶五萬一千三百七十六，口二十三萬五千五百六十。縣九：武都，東漢水受氐道水，一名沔，過江夏，謂之夏水，入江。天池大澤在縣西。莽曰循虜。〔二〕上祿，故道，莽曰善治。河池，泉街水南至沮入漢，行五百二十里。莽曰樂平亭。〔三〕平樂道，沮，沮水出東狼谷，南至沙羨南入江，過郡五，行四千里，荊州川。〔四〕嘉陵道，循成道，下辨道。莽曰楊德。〔五〕","sentenceOrder":1},
  {"id":"s_work_han_thu_39_2","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「故白馬氐羌。」","sentenceOrder":2},
  {"id":"s_work_han_thu_39_3","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「以有天池大澤，故謂之都。」","sentenceOrder":3},
  {"id":"s_work_han_thu_39_4","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「華陽國志云一名仇池，地方百頃。」","sentenceOrder":4},
  {"id":"s_work_han_thu_39_5","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「沮音千余反。羨音夷。」","sentenceOrder":5},
  {"id":"s_work_han_thu_39_6","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「辨音步見反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_39_7","chapterId":"ch_work_han_thu_39","textTraditional":"隴西郡，秦置。莽曰厭戎。〔一〕戶五萬三千九百六十四，口二十三萬六千八百二十四。有鐵官、鹽官。縣十一：狄道，白石山在東。莽曰操虜。〔二〕上邽，〔三〕安故，氐道，禹貢養水所出，至武都為漢。莽曰亭道。〔四〕首陽，禹貢鳥鼠同穴山在西南，渭水所出，東至船司空入河，過郡四，行千八百七十里，雍州浸。予道，莽曰德道。大夏，莽曰順夏。羌道，羌水出塞外，南至陰平入白水，過郡三，行六百里。〔五〕襄武，莽曰相桓。臨洮，洮水出西羌中，北至枹罕東入（西）〔河〕。禹貢西頃山在縣西，南部都尉治也。〔六〕西。禹貢嶓冢山，西漢所出，南入廣漢白水，東南至江州入江，過郡四，行二千七百六十里。莽曰西治。","sentenceOrder":7},
  {"id":"s_work_han_thu_39_8","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「有隴坻，在其西也。」師古曰：「隴坻謂隴阪，即今之隴山也。此郡在隴之西，故曰隴西。坻音丁計反，又音底。」","sentenceOrder":8},
  {"id":"s_work_han_thu_39_9","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「其地有狄種，故云狄道。」","sentenceOrder":9},
  {"id":"s_work_han_thu_39_10","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　應劭曰：「史記故邽戎邑也。」師古曰：「邽音圭。」","sentenceOrder":10},
  {"id":"s_work_han_thu_39_11","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「氐，夷種名也。氐之所居，故曰氐道，氐音丁溪反。養音弋向反，字本作漾，或作瀁。」","sentenceOrder":11},
  {"id":"s_work_han_thu_39_12","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「水經云羌水出羌中參谷。」","sentenceOrder":12},
  {"id":"s_work_han_thu_39_13","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「洮音吐高反。枹讀曰膚。頃讀曰傾。」","sentenceOrder":13},
  {"id":"s_work_han_thu_39_14","chapterId":"ch_work_han_thu_39","textTraditional":"金城郡，昭帝始元六年置。莽曰西海。〔一〕戶三萬八千四百七十，口十四萬九千六百四十八。縣十三：允吾，烏亭逆水出參街谷，東至枝陽入湟。莽曰修遠。〔二〕浩亹，浩亹水出西塞外，東至允吾入湟水。莽曰興武。〔三〕令居，澗水出西北塞外，至縣西南，入鄭伯津。莽曰罕虜。〔四〕枝陽，金城，莽曰金屏。榆中，枹罕，〔五〕白石，離水出西塞外，東至枹罕入河。莽曰順礫。〔六〕河關，積石山在西南羌中。河水行塞外，東北入塞內，至章武入海，過郡十六，行九千四百里。破羌，宣帝神爵二年置。安夷，允街，宣帝神爵二年置。莽曰修遠。〔七〕臨羌。西北至塞外，有西王母石室、僊海、鹽池。北則湟水所出，東至允吾入河。西有須抵池，有弱水、昆侖山祠。莽曰鹽羌。〔八〕","sentenceOrder":14},
  {"id":"s_work_han_thu_39_15","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「初築城得金，故曰金城。」臣瓚曰：「稱金，取其堅固也，故墨子曰『雖金城湯池』。」師古曰：「瓚說是也。一云，以郡在京師之西，故謂金城。金，西方之行。」","sentenceOrder":15},
  {"id":"s_work_han_thu_39_16","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　應劭曰：「允吾音鈆牙。」","sentenceOrder":16},
  {"id":"s_work_han_thu_39_17","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　孟康曰：「浩亹音合門。」師古曰：「浩音誥。浩，水名也。亹者，水流峽山，岸深若門也。詩大雅曰『鳧鷖在亹』，亦其義也。今俗呼此水為閤門河，蓋疾言之，浩為閤耳。湟音皇。」","sentenceOrder":17},
  {"id":"s_work_han_thu_39_18","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　孟康曰：「令音連。」師古曰：「令音零。」","sentenceOrder":18},
  {"id":"s_work_han_thu_39_19","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　應劭曰：「故罕羌侯邑也。枹音鈇。」師古曰：「讀曰膚，本枹鼓字也。其字從木。」","sentenceOrder":19},
  {"id":"s_work_han_thu_39_20","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　應劭曰：「白石山在東。」","sentenceOrder":20},
  {"id":"s_work_han_thu_39_21","chapterId":"ch_work_han_thu_39","textTraditional":"〔七〕　孟康曰：「允音鈆。」","sentenceOrder":21},
  {"id":"s_work_han_thu_39_22","chapterId":"ch_work_han_thu_39","textTraditional":"〔八〕　師古曰：「闞駰云西有（畢）〔卑〕和羌，即獻王莽地為西海郡者也。抵音丁禮反。」","sentenceOrder":22},
  {"id":"s_work_han_thu_39_23","chapterId":"ch_work_han_thu_39","textTraditional":"天水郡，武帝元鼎三年置。莽曰填戎。明帝改曰漢陽。〔一〕戶六萬三百七十，口二十六萬一千三百四十八。縣十六：平襄，莽曰平相。〔二〕街泉，戎邑道，莽曰填戎亭。望垣，莽曰望亭。罕幵，〔三〕綿諸道，阿陽，略陽道，冀，禹貢朱圄山在縣南梧中聚。莽曰冀治。〔四〕勇士，屬國都尉治滿福。莽曰紀德。〔五〕成紀，清水，莽曰識睦。奉捷，隴，〔六〕豲道，騎都尉治密艾亭。〔七〕蘭干。莽曰蘭盾。","sentenceOrder":23},
  {"id":"s_work_han_thu_39_24","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「秦州地記云郡前湖水冬夏無增減，因以名焉。填音竹真反。其後並同。」","sentenceOrder":24},
  {"id":"s_work_han_thu_39_25","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「闞駰云故襄戎邑也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_39_26","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　應劭曰：「音羌肩反。」師古曰：「本破罕幵之羌處其人於此，因以名云。」","sentenceOrder":26},
  {"id":"s_work_han_thu_39_27","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「續漢郡國志云有緹群山、落門聚。圄讀與圉同。」","sentenceOrder":27},
  {"id":"s_work_han_thu_39_28","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「即今土俗呼為健士者也。隨室之初避皇太子諱，因而遂改。」","sentenceOrder":28},
  {"id":"s_work_han_thu_39_29","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「今呼隴城縣者也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_39_30","chapterId":"ch_work_han_thu_39","textTraditional":"〔七〕　應劭曰：「豲，戎邑也，音完。」","sentenceOrder":30},
  {"id":"s_work_han_thu_39_31","chapterId":"ch_work_han_thu_39","textTraditional":"武威郡，故匈奴休屠王地。武帝太初四年開。莽曰張掖。〔一〕戶萬七千五百八十一，口七萬六千四百一十九。縣十：姑臧，南山，谷水所出，北至武威入海，行七百九十里。張掖，武威，休屠澤在東北，古文以為豬野澤。休屠，莽曰晏然。都尉治熊水障。北部都尉治休屠城。揟次，莽曰播德。〔二〕鸞（鳥）〔烏〕，撲，莽曰敷虜。〔三〕媼圍，蒼柗，南山，柗陜水所出，北至揟次入海。莽曰射楚。〔四〕宣威。","sentenceOrder":31},
  {"id":"s_work_han_thu_39_32","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「休音許虯反。屠音直閭反。其後並同。」","sentenceOrder":32},
  {"id":"s_work_han_thu_39_33","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　孟康曰：「揟音子如反。次音咨，諸本作恣。」","sentenceOrder":33},
  {"id":"s_work_han_thu_39_34","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　孟康曰：「音蒲環。」","sentenceOrder":34},
  {"id":"s_work_han_thu_39_35","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「柗，古松字也。陜音下夾反，兩山之間也。松陜，陜名。」","sentenceOrder":35},
  {"id":"s_work_han_thu_39_36","chapterId":"ch_work_han_thu_39","textTraditional":"張掖郡，故匈奴昆邪王地，武帝太初元年開。莽曰設屏。〔一〕戶二萬四千三百五十二，口八萬八千七百三十一。縣十：觻得，千金渠西至樂涫入澤中。羌谷水出羌中，東北至居延入海，過郡二，行二千一百里。莽曰官式。〔二〕昭武，莽曰渠武。刪丹，桑欽以為道弱水自此，西至酒泉合黎。莽曰貫虜。氐池，莽曰否武。屋蘭，莽曰傳武。（曰）〔日〕勒，都尉治澤索谷。莽曰勒治。〔三〕驪靬，莽曰揭虜。〔四〕番和，農都尉治。莽曰羅虜。〔五〕居延，居延澤在東北，古文以為流沙。都尉治。莽曰居成。〔六〕顯美。","sentenceOrder":36},
  {"id":"s_work_han_thu_39_37","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「張國臂掖，故曰張掖也。」師古曰：「昆音胡門反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_39_38","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　應劭曰：「觻得渠西入澤羌谷。」孟康曰：「觻音鹿。」師古曰：「孟音是也。涫音官。其下並同。」","sentenceOrder":38},
  {"id":"s_work_han_thu_39_39","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「澤音鐸。索音先各反。」","sentenceOrder":39},
  {"id":"s_work_han_thu_39_40","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　李奇曰：「音遲虔。」如淳曰：「音弓靬。」師古曰：「驪音力遲反。靬音虔是也。今其土俗人呼驪靬，疾言之曰力虔。揭音其謁反。」","sentenceOrder":40},
  {"id":"s_work_han_thu_39_41","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　如淳曰：「番音盤。」","sentenceOrder":41},
  {"id":"s_work_han_thu_39_42","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「闞駰云武帝使伏波將軍路博德築遮虜障於居延城。」","sentenceOrder":42},
  {"id":"s_work_han_thu_39_43","chapterId":"ch_work_han_thu_39","textTraditional":"酒泉郡，武帝太初元年開。莽曰輔平。〔一〕戶萬八千一百三十七，口七萬六千七百二十六。縣九：祿福，呼蠶水出南羌中，東北至會水入羌谷。莽曰顯德。表是，莽曰載武。樂涫，莽曰樂亭。天〈阝衣〉，〔二〕玉門，莽曰輔平亭。〔三〕會水，北部都尉治偃（前）〔泉〕障。東部都尉治東部障。莽曰蕭武。〔四〕池頭，綏彌，〔五〕乾齊。西部都尉治西部障。莽曰測虜。〔六〕","sentenceOrder":43},
  {"id":"s_work_han_thu_39_44","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「其水若酒，故曰酒泉也。」師古曰：「舊俗傳云城下有金泉，泉味如酒。」","sentenceOrder":44},
  {"id":"s_work_han_thu_39_45","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「音衣。此地有天〈阝衣〉阪，故以名。」","sentenceOrder":45},
  {"id":"s_work_han_thu_39_46","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「闞駰云漢罷玉門關屯，徙其人於此。」","sentenceOrder":46},
  {"id":"s_work_han_thu_39_47","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「闞駰云眾水所會，故曰會水。」","sentenceOrder":47},
  {"id":"s_work_han_thu_39_48","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　如淳曰：「今曰安彌。」","sentenceOrder":48},
  {"id":"s_work_han_thu_39_49","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　孟康曰：「乾音干。」","sentenceOrder":49},
  {"id":"s_work_han_thu_39_50","chapterId":"ch_work_han_thu_39","textTraditional":"敦煌郡，武帝後元年分酒泉置。正西關外有白龍堆沙，有蒲昌海。莽曰敦德。〔一〕戶萬一千二百，口三萬八千三百三十五。縣六：敦煌，中部都尉治步廣候官。杜林以為古瓜州地，生美瓜。莽曰敦德。〔二〕冥安，南籍端水出南羌中，西北入其澤，溉民田。〔三〕效穀，〔四〕淵泉，〔五〕廣至，宜禾都尉治昆侖障。莽曰廣桓。龍勒。有陽關、玉門關，皆都尉治。氐置水出南羌中，東北入澤，溉民田。","sentenceOrder":50},
  {"id":"s_work_han_thu_39_51","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「敦，大也。煌，盛也。敦音屯。」","sentenceOrder":51},
  {"id":"s_work_han_thu_39_52","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「即春秋左氏傳所云『允姓之戎居于瓜州』者也。其地今猶出大瓜，長者狐入瓜中食之，首尾不出。」","sentenceOrder":52},
  {"id":"s_work_han_thu_39_53","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　應劭曰：「冥水出北，入其澤。」","sentenceOrder":53},
  {"id":"s_work_han_thu_39_54","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「本漁澤障也。桑欽說孝武元封六年濟南崔不意為魚澤尉，教力田，以勤效得穀，因立為縣名。」","sentenceOrder":54},
  {"id":"s_work_han_thu_39_55","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「闞駰云地多泉水，故以為名。」","sentenceOrder":55},
  {"id":"s_work_han_thu_39_56","chapterId":"ch_work_han_thu_39","textTraditional":"安定郡，武帝元鼎三年置。戶四萬二千七百二十五，口十四萬三千二百九十四。縣二十一：高平，莽曰鋪睦。復累，〔一〕安俾，〔二〕撫夷，莽曰撫寧。朝那，有端旬祠十五所，胡巫祝。又有湫淵祠。〔三〕涇陽，幵頭山在西，禹貢涇水所出，東南至陽陵入渭，過郡三，行千六十里，雍州川。〔四〕臨涇，莽曰監涇。鹵，灈水出西。〔五〕烏氏，烏水出西，北入河。都盧山在西。莽曰烏亭。〔六〕陰密，詩密人國。有囂安亭。〔七〕安定，參〈糸言糸〉，主騎都尉治。〔八〕三水，屬國都尉治。有鹽官。莽曰廣延亭。陰槃，安武，莽曰安桓。祖厲，莽曰鄉禮。〔九〕爰得，眴卷，河水別出為河溝，東至富平北入河。〔一０〕彭陽，鶉陰，月（支）〔氏〕道。莽曰月順。〔一一〕","sentenceOrder":56},
  {"id":"s_work_han_thu_39_57","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「復音服。累音力追反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_39_58","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　孟康曰：「俾音卑。」","sentenceOrder":58},
  {"id":"s_work_han_thu_39_59","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　應劭曰：「史記故戎那邑也。」師古曰：「湫音子由反。」","sentenceOrder":59},
  {"id":"s_work_han_thu_39_60","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「幵音苦見反，又音牽。此山在今靈州東南，土俗語訛謂之汧屯山。」","sentenceOrder":60},
  {"id":"s_work_han_thu_39_61","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「灈音其于反。」","sentenceOrder":61},
  {"id":"s_work_han_thu_39_62","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「氏音支。」","sentenceOrder":62},
  {"id":"s_work_han_thu_39_63","chapterId":"ch_work_han_thu_39","textTraditional":"〔七〕　師古曰：「即詩大雅所云『密人不恭，敢距大邦』者。」","sentenceOrder":63},
  {"id":"s_work_han_thu_39_64","chapterId":"ch_work_han_thu_39","textTraditional":"〔八〕　師古曰：「〈糸言糸〉音力全反。」","sentenceOrder":64},
  {"id":"s_work_han_thu_39_65","chapterId":"ch_work_han_thu_39","textTraditional":"〔九〕　應劭曰：「祖音（置）〔罝〕。」師古曰：「厲音賴。」","sentenceOrder":65},
  {"id":"s_work_han_thu_39_66","chapterId":"ch_work_han_thu_39","textTraditional":"〔一０〕應劭曰：「眴音旬日之旬。卷音箘簬之箘。」","sentenceOrder":66},
  {"id":"s_work_han_thu_39_67","chapterId":"ch_work_han_thu_39","textTraditional":"〔一一〕應劭曰：「氏音支。」","sentenceOrder":67},
  {"id":"s_work_han_thu_39_68","chapterId":"ch_work_han_thu_39","textTraditional":"北地郡，秦置。莽曰威成。戶六萬四千四百六十一，口二十一萬六百八十八。縣十九：馬領，〔一〕直路，沮水出（東，西）〔西，東〕入洛。靈武，莽曰威成亭。富平，北部都尉治神泉障。渾懷都尉治塞外渾懷障。莽曰特武。〔二〕靈州，惠帝四年置。有河奇苑、號非苑。莽曰令周。〔三〕昫衍，〔四〕方渠，除道，莽曰通道。五街，莽曰吾街。鶉孤，歸德，洛水出北蠻夷中，入河。有堵苑、白馬苑。回獲，略畔道，莽曰延年道。〔五〕泥陽，莽曰泥陰。〔六〕郁郅，泥水出北蠻夷中。有牧師菀官。莽曰功著。〔七〕義渠道，莽曰義溝。弋居，有鹽官。大〈暂缺F5DF〉，〔八〕廉。卑移山在西北。莽曰西河亭。","sentenceOrder":68},
  {"id":"s_work_han_thu_39_69","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「川形似馬領，故以為名。領，頸也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_39_70","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「渾音胡昆反。」","sentenceOrder":70},
  {"id":"s_work_han_thu_39_71","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「苑謂馬牧也。水中可居者曰州。此地在河之州，隨水高下，未嘗淪沒，故號靈州，又曰河奇也。二苑皆在北焉。」","sentenceOrder":71},
  {"id":"s_work_han_thu_39_72","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　應劭曰：「昫音煦。」師古曰：「音香于反。」","sentenceOrder":72},
  {"id":"s_work_han_thu_39_73","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「有略畔山，今在慶州界，其土俗呼曰洛盤，音訛耳。」","sentenceOrder":73},
  {"id":"s_work_han_thu_39_74","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　應劭曰：「泥水出郁郅北蠻中。」","sentenceOrder":74},
  {"id":"s_work_han_thu_39_75","chapterId":"ch_work_han_thu_39","textTraditional":"〔七〕　師古曰：「郁音於六反。郅音之日反。」","sentenceOrder":75},
  {"id":"s_work_han_thu_39_76","chapterId":"ch_work_han_thu_39","textTraditional":"〔八〕　師古曰：「〈暂缺F5DF〉即古要字也，音一遙反。」","sentenceOrder":76},
  {"id":"s_work_han_thu_39_77","chapterId":"ch_work_han_thu_39","textTraditional":"上郡，秦置，高帝元年更為翟國，七月復故。匈歸都尉治塞外匈歸障。屬并州。〔一〕戶十萬三千六百八十三，口六十萬六千六百五十八。縣二十三：膚施，有五龍山、帝、原水、黃帝祠四所。獨樂，有鹽官。陽周，橋山在南，有黃帝冢。莽曰上陵畤。木禾，平都，淺水，莽曰廣信。京室，莽曰積粟。洛都，莽曰卑順。白土，圜水出西，東入河。莽曰黃土。〔二〕襄洛，莽曰上黨亭。原都，漆垣，莽曰漆牆。奢延，莽曰奢節。雕陰，〔三〕推邪，莽曰排邪。〔四〕楨林，莽曰楨幹。〔五〕高望，北部都尉治。莽曰堅甯。雕陰道，龜茲，屬國都尉治。有鹽官。〔六〕定陽，〔七〕高奴，有洧水，可{難灬}。莽曰利平。〔八〕望松，北部都尉治。宜都。莽曰堅寧小邑。","sentenceOrder":77},
  {"id":"s_work_han_thu_39_78","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「匈歸者，言匈奴歸附。」","sentenceOrder":78},
  {"id":"s_work_han_thu_39_79","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「圜音銀，其釋在下。」","sentenceOrder":79},
  {"id":"s_work_han_thu_39_80","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　應劭曰：「雕山在西南。」","sentenceOrder":80},
  {"id":"s_work_han_thu_39_81","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「邪音似嗟反。」","sentenceOrder":81},
  {"id":"s_work_han_thu_39_82","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「楨音貞。」","sentenceOrder":82},
  {"id":"s_work_han_thu_39_83","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　應劭曰：「音丘慈。」師古曰：「龜茲國人來降附者，處之於此，故以名云。」","sentenceOrder":83},
  {"id":"s_work_han_thu_39_84","chapterId":"ch_work_han_thu_39","textTraditional":"〔七〕　應劭曰：「在定水之陽。」","sentenceOrder":84},
  {"id":"s_work_han_thu_39_85","chapterId":"ch_work_han_thu_39","textTraditional":"〔八〕　師古曰：「{難灬}，古然火字。」","sentenceOrder":85},
  {"id":"s_work_han_thu_39_86","chapterId":"ch_work_han_thu_39","textTraditional":"西河郡，武帝元朔四年置。南部都尉治塞外翁龍、埤是。莽曰歸新。屬并州。〔一〕戶十三萬六千三百九十，口六十九萬八千八百三十六。縣三十六：富昌，有鹽官。莽曰富成。騶虞，鵠澤，〔二〕平定，莽曰陰平亭。美稷，屬國都尉治。中陽，樂街，莽曰截虜。徒經，莽曰廉恥。皋狼，大成，莽曰好成。廣田，莽曰廣翰。圜陰，惠帝五年置。莽曰方陰。〔三〕益闌，莽曰香闌。平周，鴻門，有天封苑火井祠，火從地出也。藺，宣武，莽曰討貉。千章，增山，有道西出眩雷塞，北部都尉治。〔四〕圜陽，〔五〕廣衍，武車，莽曰桓車。虎猛，西部都尉治。離石，穀羅，武澤在西北。饒，莽曰饒衍。方利，莽曰廣德。隰成，莽曰慈平亭。臨水，莽曰（堅）〔監〕水。土軍，西都，莽曰五原亭。平陸，陰山，莽曰山寧。觬是，莽曰伏觬。〔六〕博陵，莽曰助桓。鹽官。","sentenceOrder":86},
  {"id":"s_work_han_thu_39_87","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「翁龍、埤是，二障名也。埤音婢。」","sentenceOrder":87},
  {"id":"s_work_han_thu_39_88","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　孟康曰：「鵠音告。」師古曰：「音古督反。」","sentenceOrder":88},
  {"id":"s_work_han_thu_39_89","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「圜字本作圁，縣在圁水之陰，因以為名也。王莽改為方陰，則是當時已誤為圜字。今有銀州、銀水，即是舊名猶存，但字變耳。」","sentenceOrder":89},
  {"id":"s_work_han_thu_39_90","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「眩音州縣之縣。」","sentenceOrder":90},
  {"id":"s_work_han_thu_39_91","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「此縣在圁水之陽。」","sentenceOrder":91},
  {"id":"s_work_han_thu_39_92","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　蘇林曰：「音麑。」師古曰：「觬音倪，其字從角。」","sentenceOrder":92},
  {"id":"s_work_han_thu_39_93","chapterId":"ch_work_han_thu_39","textTraditional":"朔方郡，武帝元朔二年開。西部都尉治窳渾。莽曰溝搜。屬并州。〔一〕戶三萬四千三百三十八，口十三萬六千六百二十八。縣十：三封，武帝元狩三年城。朔方，金連鹽澤、青鹽澤皆在南。莽曰武符。修都，臨河，莽曰監河。呼遒，〔二〕窳渾，有道西北出雞鹿塞。屠申澤在東。莽曰極武。渠搜，中部都尉治。莽曰溝搜。沃野，武帝元狩三年城。有鹽官。莽曰綏武。廣牧，東部都尉治。莽曰鹽官。臨戎。武帝元朔五年城。莽曰推武。","sentenceOrder":93},
  {"id":"s_work_han_thu_39_94","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「窳音庾。渾音魂。」","sentenceOrder":94},
  {"id":"s_work_han_thu_39_95","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「遒音在由反。」","sentenceOrder":95},
  {"id":"s_work_han_thu_39_96","chapterId":"ch_work_han_thu_39","textTraditional":"五原郡，秦九原郡，武帝元朔二年更名。東部都尉治稒陽。莽曰獲降。屬并州。〔一〕戶三萬九千三百二十二，口二十三萬一千三百二十八。縣十六：九原，莽曰成平。固陵，莽曰固調。五原，莽曰填河亭。臨沃，莽曰振武。文國，莽曰繁聚。河陰，蒱澤，屬國都尉治。南興，莽曰南利。武都，莽曰桓都。宜梁，曼柏，莽曰延柏。〔二〕成宜，中部都尉治原高，西部都尉治田辟。有鹽官。莽曰艾虜。〔三〕稒陽，北出石門障得光祿城，又西北得支就城，又西北得頭曼城，又西北得虖河城，又西得宿虜城。莽曰固陰。〔四〕莫〈黑旦〉，〔五〕西安陽，莽曰鄣安。河目。","sentenceOrder":96},
  {"id":"s_work_han_thu_39_97","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「稒音固。」","sentenceOrder":97},
  {"id":"s_work_han_thu_39_98","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「曼音萬。」","sentenceOrder":98},
  {"id":"s_work_han_thu_39_99","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「辟讀曰壁。艾讀曰刈。」","sentenceOrder":99},
  {"id":"s_work_han_thu_39_100","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「曼音莫安反。虖音呼。」","sentenceOrder":100},
  {"id":"s_work_han_thu_39_101","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　如淳曰：「音忉怛。」師古曰：「音丁葛反。」","sentenceOrder":101},
  {"id":"s_work_han_thu_39_102","chapterId":"ch_work_han_thu_39","textTraditional":"雲中郡，秦置。莽曰受降。屬并州。戶三萬八千三百三，口十七萬三千二百七十。縣十一：雲中，莽曰遠服。咸陽，莽曰賁武。陶林，東部都尉治。楨陵，緣胡山在西北。西部都尉治。莽曰楨陸。犢和，沙陵，莽曰希恩。原陽，沙南，北輿，中部都尉治。〔一〕武泉，莽曰順泉。陽壽。莽曰常得。","sentenceOrder":102},
  {"id":"s_work_han_thu_39_103","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「闞駰云廣陵有輿，故此加北。」","sentenceOrder":103},
  {"id":"s_work_han_thu_39_104","chapterId":"ch_work_han_thu_39","textTraditional":"定襄郡，高帝置。莽曰得降。屬并州。戶三萬八千五百五十九，口十六萬三千一百四十四。縣一十二：成樂，桐過，莽曰椅桐。〔一〕都武，莽曰通德。武進，白渠水出塞外，西至沙陵入河。西部都尉治。莽曰伐蠻。襄陰，武皋，荒干水出塞外，西至沙陵入河。中部都尉治。莽曰永武。駱，莽曰遮要。定陶，莽曰迎符。武城，莽曰桓就。武要，東部都尉治。莽曰厭胡。〔二〕定襄，莽曰著武。復陸。莽曰聞武。〔三〕","sentenceOrder":104},
  {"id":"s_work_han_thu_39_105","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「過音工禾反。」","sentenceOrder":105},
  {"id":"s_work_han_thu_39_106","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「厭音一葉反。其下並同。」","sentenceOrder":106},
  {"id":"s_work_han_thu_39_107","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「復音服。」","sentenceOrder":107},
  {"id":"s_work_han_thu_39_108","chapterId":"ch_work_han_thu_39","textTraditional":"鴈門郡，秦置。句注山在陰館。莽曰填狄。屬并州。戶七萬三千一百三十八，口二十九萬三千四百五十四。縣十四：善無，莽曰陰館。沃陽，鹽澤在東北，有長丞。西部都尉治。莽曰敬陽。繁畤，莽曰當要。〔一〕中陵，莽曰遮害。陰館，樓煩鄉。景帝後三年置。累頭山，治水所出，東至泉州入海，過郡六，行千一百里。莽曰富代。〔二〕樓煩，有鹽官。〔三〕武州，莽曰桓州。〈氵{山王}〉陶，〔四〕劇陽，莽曰善陽。崞，莽曰崞張。〔五〕平城，東部都尉治。莽曰平順。埒，莽曰填狄亭。馬邑，莽曰章昭。〔六〕彊陰。諸聞澤在東北。莽曰伏陰。","sentenceOrder":108},
  {"id":"s_work_han_thu_39_109","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「畤音止。」","sentenceOrder":109},
  {"id":"s_work_han_thu_39_110","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「累音力追反。治音弋之反。燕剌王傳作台字。」","sentenceOrder":110},
  {"id":"s_work_han_thu_39_111","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　應劭曰：「故樓煩胡地。」","sentenceOrder":111},
  {"id":"s_work_han_thu_39_112","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　孟康曰：「音汪。」","sentenceOrder":112},
  {"id":"s_work_han_thu_39_113","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　孟康曰：「音郭。」","sentenceOrder":113},
  {"id":"s_work_han_thu_39_114","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「晉太康地記云秦時建此城輒崩不成，有馬周旋馳走反覆，父老異之，因依以築城，遂名為馬邑。」","sentenceOrder":114},
  {"id":"s_work_han_thu_39_115","chapterId":"ch_work_han_thu_39","textTraditional":"代郡，秦置。莽曰厭狄。有五原關、常山關。屬幽州。〔一〕戶五萬六千七百七十一，口二十七萬八千七百五十四。縣十八：桑乾，莽曰安德。〔二〕道人，莽曰道仁。〔三〕當城，〔四〕高柳，西部都尉治。馬城，東部都尉治。班氏，秦地圖書班氏。莽曰班副。延陵，狋氏，莽曰狋聚。〔五〕且如，于延水出塞外，東至寧入沽。中部都尉治。〔六〕平邑，莽曰平胡。陽原，東安陽，莽曰竟安。〔七〕參合，平舒，祈夷水北至桑乾入沽。莽曰平葆。代，莽曰厭狄亭。〔八〕靈丘，滱河東至文安入大河，過郡五，行九百四十里。并州川。〔九〕廣昌，淶水東南至容城入河，過郡三，行五百里，并州浸。莽曰廣屏。〔一０〕鹵城。虖池河東至參（合）〔戶〕入虖池別，過郡九，行千三百四十里，并州川。從河東至文安入海，過郡六，行千三百七十里。莽曰魯盾。〔一一〕","sentenceOrder":115},
  {"id":"s_work_han_thu_39_116","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「故代國。」","sentenceOrder":116},
  {"id":"s_work_han_thu_39_117","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　孟康曰：「乾音干。」","sentenceOrder":117},
  {"id":"s_work_han_thu_39_118","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「本有仙人遊其地，因以為名。」","sentenceOrder":118},
  {"id":"s_work_han_thu_39_119","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「闞駰云當桓都城，故曰當城。」","sentenceOrder":119},
  {"id":"s_work_han_thu_39_120","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　孟康曰：「狋音權。氏音精。」","sentenceOrder":120},
  {"id":"s_work_han_thu_39_121","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「且音子如反。沽音姑，又音故。」","sentenceOrder":121},
  {"id":"s_work_han_thu_39_122","chapterId":"ch_work_han_thu_39","textTraditional":"〔七〕　師古曰：「闞駰云五原有安陽，故此加東也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_39_123","chapterId":"ch_work_han_thu_39","textTraditional":"〔八〕　應劭曰：「故代國。」","sentenceOrder":123},
  {"id":"s_work_han_thu_39_124","chapterId":"ch_work_han_thu_39","textTraditional":"〔九〕　應劭曰：「武靈王葬此，因氏焉。」臣瓚曰：「靈丘之號在趙武靈王之前也。」師古曰：「瓚說是也。滱音寇。又音苦侯反。其下並同。」","sentenceOrder":124},
  {"id":"s_work_han_thu_39_125","chapterId":"ch_work_han_thu_39","textTraditional":"〔一０〕師古曰：「淶音來。」","sentenceOrder":125},
  {"id":"s_work_han_thu_39_126","chapterId":"ch_work_han_thu_39","textTraditional":"〔一一〕師古曰：「虖音呼。池音徒河反。」","sentenceOrder":126},
  {"id":"s_work_han_thu_39_127","chapterId":"ch_work_han_thu_39","textTraditional":"上谷郡，秦置。莽曰朔調。屬幽州。戶三萬六千八，口十一萬七千七百六十二。縣十五：沮陽，莽曰沮陰。〔一〕泉上，莽曰塞泉。潘，莽曰樹武。〔二〕軍都，溫餘水東至路，南入沽。居庸，有關。雊瞀，〔三〕夷輿，莽曰朔調亭。寧，西部都尉治。莽曰博康。昌平，莽曰長昌。廣寧，莽曰廣康。涿鹿，莽曰抪陸。〔四〕且居，（樂陽）〔陽樂〕水出東，（東）〔南〕入（海）〔沽〕。莽曰久居。茹，莽曰穀武。女祈，東部都尉治。莽曰祈。下落。莽曰下忠。","sentenceOrder":127},
  {"id":"s_work_han_thu_39_128","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　孟康曰：「音俎。」","sentenceOrder":128},
  {"id":"s_work_han_thu_39_129","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「音普半反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_39_130","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　孟康曰：「音句無。」師古曰：「雊音工豆反。瞀音莫豆反。」","sentenceOrder":130},
  {"id":"s_work_han_thu_39_131","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　應劭曰：「黃帝與蚩尤戰于涿鹿之野。」","sentenceOrder":131},
  {"id":"s_work_han_thu_39_132","chapterId":"ch_work_han_thu_39","textTraditional":"漁陽郡，秦置。莽曰（北順）〔通路〕。屬幽州。戶六萬八千八百二，口二十六萬四千一百一十六。縣十二：漁陽，沽水出塞外，東南至泉州入海，行七百五十里。有鐵官。莽曰得漁。狐奴，莽曰舉符。路，莽曰通路亭。雍奴，泉州，有鹽官。莽曰泉調。平谷，安樂，厗奚，莽曰敦德。〔一〕獷平，莽曰平獷。〔二〕要陽，都尉治。莽曰要術。〔三〕白檀，洫水出北蠻夷。〔四〕滑鹽。莽曰匡德。〔五〕","sentenceOrder":132},
  {"id":"s_work_han_thu_39_133","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　孟康曰：「厗音題，字或作蹄。」","sentenceOrder":133},
  {"id":"s_work_han_thu_39_134","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　服虔曰：「獷音鞏。」師古曰：「音九永反，又音穬。」","sentenceOrder":134},
  {"id":"s_work_han_thu_39_135","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「音一妙反。」","sentenceOrder":135},
  {"id":"s_work_han_thu_39_136","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「洫音呼鵙反。」","sentenceOrder":136},
  {"id":"s_work_han_thu_39_137","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　應劭曰：「明帝改名鹽。」","sentenceOrder":137},
  {"id":"s_work_han_thu_39_138","chapterId":"ch_work_han_thu_39","textTraditional":"右北平郡，秦置。莽曰北順。屬幽州。戶六萬六千六百八十九，口三十二萬七百八十。縣十六：平剛，無終，故無終子國。浭水西至雍奴入海，過郡二，行六百五十里。〔一〕石成，廷陵，莽曰鋪武。俊靡，灅水南至無終東入庚。莽曰俊麻。〔二〕薋，都尉治。莽曰裒睦。〔三〕徐無，莽曰北順亭。字，榆水出東。土垠，〔四〕白狼，莽曰伏狄。〔五〕夕陽，有鐵官。莽曰夕陰。昌城，莽曰淑武。驪成，大揭石山在縣西南。莽曰揭石。〔六〕廣成，莽曰平虜。聚陽，莽曰篤睦。平明。莽曰平陽。","sentenceOrder":138},
  {"id":"s_work_han_thu_39_139","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「浭音庚。即下所云入庚者同一水也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_39_140","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「灅音力水反，又音郎賄反。」","sentenceOrder":140},
  {"id":"s_work_han_thu_39_141","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「音才私反。」","sentenceOrder":141},
  {"id":"s_work_han_thu_39_142","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「垠音銀。」","sentenceOrder":142},
  {"id":"s_work_han_thu_39_143","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「有白狼山，故以名縣。」","sentenceOrder":143},
  {"id":"s_work_han_thu_39_144","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「揭音桀。」","sentenceOrder":144},
  {"id":"s_work_han_thu_39_145","chapterId":"ch_work_han_thu_39","textTraditional":"遼西郡，秦置。有小水四十八，并行三千四十六里。屬幽州。戶七萬二千六百五十四，口三十五萬二千三百二十五。縣十四：且慮，有高廟。莽曰鉏慮。〔一〕海陽，龍鮮水東入封大水。封大水、綏虛水皆南入海。有鹽官。新安平，夷水東入塞外。柳城，馬首山在西南。參柳水北入海。西部都尉治。令支，有孤竹城。莽曰令氏亭。〔二〕肥如，玄水東入濡水。濡水南入海陽。又有盧水，南入玄。莽曰肥而。〔三〕賓從，莽曰勉武。交黎，渝水首受塞外，南入海。東部都尉治。莽曰禽虜。〔四〕陽樂，狐蘇，唐就水至徒河入海。徒河，莽曰河福。文成，莽曰言虜。臨渝，渝水首受白狼，東入塞外。又有侯水，北入渝。莽曰馮德。〔五〕絫。下官水南入海。又有揭石水、賓水，皆南入官。莽曰選武。〔六〕","sentenceOrder":145},
  {"id":"s_work_han_thu_39_146","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「且音子余反。慮音廬。」","sentenceOrder":146},
  {"id":"s_work_han_thu_39_147","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　應劭曰：「故伯夷國，今有孤竹城。令音鈴。」孟康曰：「支音秪。」師古曰：「令又音郎定反。」","sentenceOrder":147},
  {"id":"s_work_han_thu_39_148","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　應劭曰：「肥子奔燕，燕封於此也。」師古曰：「濡音乃官反。」","sentenceOrder":148},
  {"id":"s_work_han_thu_39_149","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　應劭曰：「今昌黎。」師古曰：「渝音喻。其下並同。」","sentenceOrder":149},
  {"id":"s_work_han_thu_39_150","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「馮讀曰憑　。」","sentenceOrder":150},
  {"id":"s_work_han_thu_39_151","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「絫音力追反。」","sentenceOrder":151},
  {"id":"s_work_han_thu_39_152","chapterId":"ch_work_han_thu_39","textTraditional":"遼東郡，秦置。屬幽州。戶五萬五千九百七十二，口二十七萬二千五百三十九。縣十八：襄平，有牧師官。莽曰昌平。新昌，無慮，西部都尉治。〔一〕望平，大遼水出塞外，南至安市入海，行千二百五十里。莽曰長說。〔二〕房，候城，中部都尉治。遼隊，莽曰順睦。〔三〕遼陽，大梁水西南至遼陽入遼。莽曰遼陰。險瀆，〔四〕居就，室偽山，室偽水所出，北至襄平入梁也。高顯，安市，武次，東部都尉治。莽曰桓次。平郭，有鐵官、鹽官。西安平，莽曰北安平。文，莽曰（受）〔文〕亭。番汗，沛水出塞外，西南入海。〔五〕沓氏。〔六〕","sentenceOrder":152},
  {"id":"s_work_han_thu_39_153","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「慮音閭。」師古曰：「即所謂醫巫閭。」","sentenceOrder":153},
  {"id":"s_work_han_thu_39_154","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「說讀曰（侻）〔悅〕。」","sentenceOrder":154},
  {"id":"s_work_han_thu_39_155","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「隊音遂。」","sentenceOrder":155},
  {"id":"s_work_han_thu_39_156","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　應劭曰：「朝鮮王滿都也。依水險，故曰險瀆。」臣瓚曰：「王險城在樂浪郡浿水之東，此自是險瀆也。」師古曰：「瓚說是也。浿音普大反。」","sentenceOrder":156},
  {"id":"s_work_han_thu_39_157","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　應劭曰：「汗水出塞外，西南入海。番音盤。」師古曰：「沛音普蓋反。汗音寒。」","sentenceOrder":157},
  {"id":"s_work_han_thu_39_158","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　應劭曰：「氏水也。音長答反。」師古曰：「凡言氏者，皆謂因之而立名。」","sentenceOrder":158},
  {"id":"s_work_han_thu_39_159","chapterId":"ch_work_han_thu_39","textTraditional":"玄菟郡，武帝元封四年開。高句驪，莽曰下句驪。屬幽州。〔一〕戶四萬五千六，口二十二萬一千八百四十五。縣三：高句驪，遼山，遼水所出，西南至遼隊入大遼水。又有南蘇水，西北經塞外。〔二〕上殷台，莽曰下殷。〔三〕西蓋馬。馬訾水西北入鹽難水，西南至西安平入海，過郡二，行二千一百里。莽曰玄菟亭。","sentenceOrder":159},
  {"id":"s_work_han_thu_39_160","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「故真番，朝鮮胡國。」","sentenceOrder":160},
  {"id":"s_work_han_thu_39_161","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　應劭曰：「故句驪胡。」","sentenceOrder":161},
  {"id":"s_work_han_thu_39_162","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　如淳曰：「台音鮐。」師古曰：「音胎。」","sentenceOrder":162},
  {"id":"s_work_han_thu_39_163","chapterId":"ch_work_han_thu_39","textTraditional":"樂浪郡，武帝元封三年開。莽曰樂鮮。屬幽州。〔一〕戶六萬二千八百一十二，口四十萬六千七百四十八。有雲鄣。縣二十五：朝鮮，〔二〕〈言冄〉邯，〔三〕浿水，水西至增地入海。莽曰樂鮮亭。〔四〕含資，帶水西至帶方入海。黏蟬，〔五〕遂成，增地，莽曰增土。帶方，駟望，海冥，莽曰海桓。列口，長岑，屯有，昭明，南部都尉治。鏤方，提奚，渾彌，〔六〕吞列，分黎山，列水所出，西至黏蟬入海，行八百二十里。東〈暂缺F5DE〉，〔七〕不而，東（郡）〔部〕都尉治。蠶台，〔八〕華麗，邪頭昧，〔九〕前莫，夫租。","sentenceOrder":163},
  {"id":"s_work_han_thu_39_164","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「故朝鮮國也。」師古曰：「樂音洛。浪音狼。」","sentenceOrder":164},
  {"id":"s_work_han_thu_39_165","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　應劭曰：「武王封箕子於朝鮮。」","sentenceOrder":165},
  {"id":"s_work_han_thu_39_166","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　孟康曰：「〈言冄〉音男。」師古曰：「〈言冄〉音乃甘反。邯音酣。」","sentenceOrder":166},
  {"id":"s_work_han_thu_39_167","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「浿音普大反。」","sentenceOrder":167},
  {"id":"s_work_han_thu_39_168","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　服虔曰：「蟬音提。」","sentenceOrder":168},
  {"id":"s_work_han_thu_39_169","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「渾音下昆反。」","sentenceOrder":169},
  {"id":"s_work_han_thu_39_170","chapterId":"ch_work_han_thu_39","textTraditional":"〔七〕　應劭曰：「音移。」","sentenceOrder":170},
  {"id":"s_work_han_thu_39_171","chapterId":"ch_work_han_thu_39","textTraditional":"〔八〕　師古曰：「台音胎。」","sentenceOrder":171},
  {"id":"s_work_han_thu_39_172","chapterId":"ch_work_han_thu_39","textTraditional":"〔九〕　孟康曰：「昧音妹。」","sentenceOrder":172},
  {"id":"s_work_han_thu_39_173","chapterId":"ch_work_han_thu_39","textTraditional":"南海郡，秦置。秦敗，尉佗王此地。武帝元鼎六年開。屬交州。戶萬九千六百一十三，口九萬四千二百五十三。有圃羞官。縣六：番禺，尉佗都。有鹽官。〔一〕博羅，中宿，有洭浦官。〔二〕龍川，〔三〕四會，揭陽。莽曰南海亭。〔四〕","sentenceOrder":173},
  {"id":"s_work_han_thu_39_174","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　如淳曰：「番音潘。禺音愚。」","sentenceOrder":174},
  {"id":"s_work_han_thu_39_175","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「洭音匡。」","sentenceOrder":175},
  {"id":"s_work_han_thu_39_176","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「裴氏廣州記云本博羅縣之東鄉也，有龍穿地而出，即穴流泉，因以為號。」","sentenceOrder":176},
  {"id":"s_work_han_thu_39_177","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　韋昭曰：「揭音其逝反。」師古曰：「音竭。」","sentenceOrder":177},
  {"id":"s_work_han_thu_39_178","chapterId":"ch_work_han_thu_39","textTraditional":"鬱林郡，故秦桂林郡，屬尉佗。武帝元鼎六年開，更名。有小谿川水七，并行三千一百一十里。莽曰鬱平。屬交州。戶萬二千四百一十五，口七萬一千一百六十二。縣十二：布山，安廣，阿林，廣鬱，鬱水首受夜郎豚水，東至四會入海，過郡四，行四千三十里。中留，〔一〕桂林，潭中，莽曰中潭。〔二〕臨塵，朱涯水入領方。又有斤（員）〔南〕水。又有侵離水，行七百里。莽曰監塵。定周，〔周〕水首受無斂，東入潭，行七百九十里。增食，驩水首受牂柯東界，入朱涯水，行五百七十里。領方。斤（員）〔南〕水入鬱。又有墧水。都尉治。〔三〕雍雞。有關。","sentenceOrder":178},
  {"id":"s_work_han_thu_39_179","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「留音力救反，水名。」","sentenceOrder":179},
  {"id":"s_work_han_thu_39_180","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「潭音大含反。」","sentenceOrder":180},
  {"id":"s_work_han_thu_39_181","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「墧音橋。」","sentenceOrder":181},
  {"id":"s_work_han_thu_39_182","chapterId":"ch_work_han_thu_39","textTraditional":"蒼梧郡，武帝元鼎六年開。莽曰新廣。屬交州。有離水關。戶二萬四千三百七十九，口十四萬六千一百六十。縣十：廣信，莽曰廣信亭。謝沐，有關。高要，有鹽官。封陽，〔一〕臨賀，莽曰大賀。端谿，馮乘，富川，荔蒲，有荔平關。〔二〕猛陵。龍山，合水所出，南至布山入海。莽曰猛陸。","sentenceOrder":182},
  {"id":"s_work_han_thu_39_183","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「在封水之陽。」","sentenceOrder":183},
  {"id":"s_work_han_thu_39_184","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「荔音（肄）〔隸〕。」","sentenceOrder":184},
  {"id":"s_work_han_thu_39_185","chapterId":"ch_work_han_thu_39","textTraditional":"交趾郡，武帝元鼎六年開，屬交州。戶九萬二千四百四十，口七十四萬六千二百三〔十〕七。縣十：羸〈阝婁〉，有羞官。〔一〕安定，苟屚，〔二〕麊泠，都尉治。〔三〕曲昜，〔四〕北帶，稽徐，〔五〕西于，龍編，〔六〕朱〈截，中“隹改鳥”〉。","sentenceOrder":185},
  {"id":"s_work_han_thu_39_186","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　孟康曰：「羸音蓮。〈阝婁〉音受土簍。」師古曰：「〈阝婁〉簍二字並音來口反。」","sentenceOrder":186},
  {"id":"s_work_han_thu_39_187","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「屚與漏同。」","sentenceOrder":187},
  {"id":"s_work_han_thu_39_188","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　應劭曰：「麊音彌。」孟康曰：「音螟蛉。」師古曰：「音麋零。」","sentenceOrder":188},
  {"id":"s_work_han_thu_39_189","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「昜，古陽字。」","sentenceOrder":189},
  {"id":"s_work_han_thu_39_190","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「稽音古奚反。」","sentenceOrder":190},
  {"id":"s_work_han_thu_39_191","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「編音鞭。」","sentenceOrder":191},
  {"id":"s_work_han_thu_39_192","chapterId":"ch_work_han_thu_39","textTraditional":"合浦郡，武帝元鼎六年開。莽曰桓合。屬交州。戶萬五千三百九十八，口七萬八千九百八十。縣五：徐聞，高涼，合浦，有關。莽曰桓亭。臨允，牢水北入高要入鬱，過郡三，行五百三十里。莽曰大允。朱盧。都尉治。","sentenceOrder":192},
  {"id":"s_work_han_thu_39_193","chapterId":"ch_work_han_thu_39","textTraditional":"九真郡，武帝元鼎六年開。有小水五十二，并行八千五百六十里。戶三萬五千七百四十三，口十六萬六千一十三。有界關。縣七：胥浦，莽曰驩成。居風，都龐，〔一〕餘發，咸驩，無切，都尉治。無編。莽曰九真亭。","sentenceOrder":193},
  {"id":"s_work_han_thu_39_194","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「龐音龍。」師古曰：「音聾。」","sentenceOrder":194},
  {"id":"s_work_han_thu_39_195","chapterId":"ch_work_han_thu_39","textTraditional":"日南郡，故秦象郡，武帝元鼎六年開，更名。有小水十六，并行三千一百八十里。屬交州。〔一〕戶萬五千四百六十，口六萬九千四百八十五。縣五：朱吾，比景，〔二〕盧容，西捲，水入海，有竹，可為杖。莽曰日南亭。〔三〕象林。","sentenceOrder":195},
  {"id":"s_work_han_thu_39_196","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「言其在日之南，所謂開北戶以向日者。」","sentenceOrder":196},
  {"id":"s_work_han_thu_39_197","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　如淳曰：「日中於頭上，景在已下，故名之。」","sentenceOrder":197},
  {"id":"s_work_han_thu_39_198","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　孟康曰：「音卷。」師古曰：「音權。」","sentenceOrder":198},
  {"id":"s_work_han_thu_39_199","chapterId":"ch_work_han_thu_39","textTraditional":"趙國，故秦邯鄲郡，高帝四年為趙國，景帝三年復為邯鄲郡，五年復故。莽曰桓亭。屬冀州。戶八萬四千二百二，口三十四萬九千九百五十二。縣四：邯鄲，堵山，牛首水所出，東入白渠。趙敬侯自中牟徙此。〔一〕易陽，〔二〕柏人，莽曰壽仁。〔三〕襄國。故邢國。西山，渠水所出，東北至任入浸。又有蓼水、馮水，皆東至朝平入湡。〔四〕","sentenceOrder":199},
  {"id":"s_work_han_thu_39_200","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　張晏曰：「邯鄲山在東城下。單，盡也。城郭從邑，故加邑云。」師古曰：「邯音寒。」","sentenceOrder":200},
  {"id":"s_work_han_thu_39_201","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　應劭曰：「易水出涿郡故安。」師古曰：「在易水之陽。」","sentenceOrder":201},
  {"id":"s_work_han_thu_39_202","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「本晉邑。」","sentenceOrder":202},
  {"id":"s_work_han_thu_39_203","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「湡音藕，又音牛吼反。」","sentenceOrder":203},
  {"id":"s_work_han_thu_39_204","chapterId":"ch_work_han_thu_39","textTraditional":"廣平國，武帝征和二年置為平干國，宣帝五鳳二年復故。莽曰富昌。屬冀州。戶二萬七千九百八十四，口十九萬八千五百五十八。縣十六：廣平，張，朝平，南和，列葭水東入〈氵虒〉。〔一〕列人，莽曰列治。斥章，〔二〕任，〔三〕曲周，武帝建元四年置。莽曰直周。南曲，曲梁，侯國。莽曰直梁。廣鄉，平利，平鄉，陽臺，侯國。廣年，莽曰富昌。城鄉。","sentenceOrder":204},
  {"id":"s_work_han_thu_39_205","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「葭音家。〈氵虒〉音斯。」","sentenceOrder":205},
  {"id":"s_work_han_thu_39_206","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　應劭曰：「漳水出治北，入河。其國斥鹵，故曰斥章。」","sentenceOrder":206},
  {"id":"s_work_han_thu_39_207","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「本晉邑也。鄭皇頡奔晉，為任大夫。」","sentenceOrder":207},
  {"id":"s_work_han_thu_39_208","chapterId":"ch_work_han_thu_39","textTraditional":"真定國，武帝元鼎四年置。屬冀州。戶三萬七千一百二十六，口十七萬八千六百一十六。縣四：真定，故東垣，高帝十一年更名。莽曰思治。稿城，莽曰稿實。〔一〕肥纍，故肥子國。〔二〕綿曼。斯洨水首受太白渠，東至鄡入河。莽曰綿延。〔三〕","sentenceOrder":208},
  {"id":"s_work_han_thu_39_209","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「稿音工老反。」","sentenceOrder":209},
  {"id":"s_work_han_thu_39_210","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「纍音力追反。」","sentenceOrder":210},
  {"id":"s_work_han_thu_39_211","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「曼音萬。鄡音口堯反。」","sentenceOrder":211},
  {"id":"s_work_han_thu_39_212","chapterId":"ch_work_han_thu_39","textTraditional":"中山國，高帝郡，景帝三年為國。莽曰常山。屬冀州。〔一〕戶十六萬八百七十三，口六十六萬八千八十。縣十四：盧奴，〔二〕北平，徐水東至高陽入博。又有盧水，亦至高陽入河。有鐵官。莽曰善和。北新成，桑欽言易水出西北，東入滱。莽曰朔平。唐，堯山在南。莽曰和親。〔三〕深澤，莽曰翼和，苦陘，莽曰北陘。〔四〕安國，莽曰興睦。曲逆，蒲陽山，蒲水所出，東入濡。又有蘇水，亦東入濡。莽曰順平。〔五〕望都，博水東至高陽入河。莽曰順調。〔六〕新市，〔七〕新處，毋極，陸成，安險。莽曰寧險。〔八〕","sentenceOrder":212},
  {"id":"s_work_han_thu_39_213","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「中山，故國。」","sentenceOrder":213},
  {"id":"s_work_han_thu_39_214","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　應劭曰：「盧水出右北平，東入河。」","sentenceOrder":214},
  {"id":"s_work_han_thu_39_215","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　應劭曰：「故堯國也。唐水在西。」張晏曰：「堯為唐侯，國於此。堯山在唐東北望都界。」孟康曰：「晉荀吳伐鮮虞及中人，今中人亭是。」","sentenceOrder":215},
  {"id":"s_work_han_thu_39_216","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　應劭曰：「章帝更名漢昌。陘音邢。」","sentenceOrder":216},
  {"id":"s_work_han_thu_39_217","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　張晏曰：「濡水於城北曲而西流，故曰曲逆。章帝醜其名，改曰蒲陰，在蒲水之陰。」師古曰：「濡音乃官反。」","sentenceOrder":217},
  {"id":"s_work_han_thu_39_218","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　張晏曰：「堯山在北，堯母慶都山在南，登堯山見都山，故以為名。」","sentenceOrder":218},
  {"id":"s_work_han_thu_39_219","chapterId":"ch_work_han_thu_39","textTraditional":"〔七〕　應劭曰：「鮮虞子國，今鮮虞亭是。」","sentenceOrder":219},
  {"id":"s_work_han_thu_39_220","chapterId":"ch_work_han_thu_39","textTraditional":"〔八〕　應劭曰：「章帝更名安熹。」","sentenceOrder":220},
  {"id":"s_work_han_thu_39_221","chapterId":"ch_work_han_thu_39","textTraditional":"信都國，景帝二年為廣川國，宣帝甘露三年復故。莽曰新博。屬冀州。〔一〕戶六萬五千五百五十六，口三十萬四千三百八十四。縣十七：信都，王都。故章河、故虖池皆在北，東入海。禹貢絳水亦入海。莽曰新博亭。歷，莽曰歷寧。扶柳，〔二〕辟陽，莽曰樂信。〔三〕南宮，莽曰序下。下博，莽曰閏博。〔四〕武邑，莽曰順桓。觀津，莽曰朔定亭。〔五〕高隄，〔六〕廣川，〔七〕樂鄉，侯國。莽曰樂丘。平隄，侯國。桃，莽曰桓分。西梁，侯國。昌成，侯國。東昌，侯國。莽曰田昌。脩。莽曰脩治。〔八〕","sentenceOrder":221},
  {"id":"s_work_han_thu_39_222","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「明帝更名樂安。安帝改曰安平。」","sentenceOrder":222},
  {"id":"s_work_han_thu_39_223","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「闞駰云其地有扶澤，澤中多柳，故曰扶柳。」","sentenceOrder":223},
  {"id":"s_work_han_thu_39_224","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「辟音珪璧。」","sentenceOrder":224},
  {"id":"s_work_han_thu_39_225","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　應劭曰：「博水出中山望都，入河。」","sentenceOrder":225},
  {"id":"s_work_han_thu_39_226","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「觀音工喚反。」","sentenceOrder":226},
  {"id":"s_work_han_thu_39_227","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「隄音丁奚反。」","sentenceOrder":227},
  {"id":"s_work_han_thu_39_228","chapterId":"ch_work_han_thu_39","textTraditional":"〔七〕　師古曰：「闞駰云其縣中有長河為流，故曰廣川也。至隋仁壽元年，初立煬帝為皇太子，以避諱故，改為長河縣，至今為名。」","sentenceOrder":228},
  {"id":"s_work_han_thu_39_229","chapterId":"ch_work_han_thu_39","textTraditional":"〔八〕　師古曰：「脩音條。」","sentenceOrder":229},
  {"id":"s_work_han_thu_39_230","chapterId":"ch_work_han_thu_39","textTraditional":"河間國，故趙，文帝二年別為國。莽曰朔定。〔一〕戶四萬五千四十三，口十八萬七千六百六十二。縣四：樂成，虖池別水首受虖池河，東至東光入虖池河。莽曰陸信。候井，武隧，莽曰桓隧。〔二〕弓高。虖池別河首受虖池河，東至平舒入海。莽曰樂成。","sentenceOrder":230},
  {"id":"s_work_han_thu_39_231","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「在河之間。」","sentenceOrder":231},
  {"id":"s_work_han_thu_39_232","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「隧音遂。」","sentenceOrder":232},
  {"id":"s_work_han_thu_39_233","chapterId":"ch_work_han_thu_39","textTraditional":"廣陽國，高帝燕國，昭帝元鳳元年為廣陽郡，宣帝本始元年更為國。莽曰廣有。戶二萬七百四十，口七萬六百五十八。縣四：薊，故燕國，召公所封。莽曰伐戎。方城，廣陽，陰鄉。莽曰陰順。","sentenceOrder":233},
  {"id":"s_work_han_thu_39_234","chapterId":"ch_work_han_thu_39","textTraditional":"甾川國，故齊，文帝十八年別為國。後并北海。戶五萬二百八十九，口二十二萬七千三十一。縣三：劇，義山，蕤水所出，北至壽光入海。莽曰俞。〔一〕東安平，菟頭山，女水出，東北至臨甾入鉅定。〔二〕樓鄉。","sentenceOrder":234},
  {"id":"s_work_han_thu_39_235","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「故肥國，今肥亭是。」","sentenceOrder":235},
  {"id":"s_work_han_thu_39_236","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　孟康曰：「紀季以酅入于齊，今酅亭是也。」師古曰：「闞駰云博陵有安平，故此加東。酅音攜。」","sentenceOrder":236},
  {"id":"s_work_han_thu_39_237","chapterId":"ch_work_han_thu_39","textTraditional":"廣陽國，高帝燕國，昭帝元鳳元年為廣陽郡，宣帝本始元年更為國。莽曰廣有。戶二萬七百四","sentenceOrder":237},
  {"id":"s_work_han_thu_39_238","chapterId":"ch_work_han_thu_39","textTraditional":"膠東國，故齊，高帝元年別為國，五月復屬齊國，文帝十六年復為國。莽曰郁秩。戶七萬二千二，口三十二萬三千三百三十一。縣八：即墨，有天室山祠。莽曰即善。昌武，下密，有三石山祠。〔一〕壯武，莽曰曉武。郁秩，有鐵官。挺，〔二〕觀陽，〔三〕鄒盧。莽曰始斯。","sentenceOrder":238},
  {"id":"s_work_han_thu_39_239","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「密水出高密。」","sentenceOrder":239},
  {"id":"s_work_han_thu_39_240","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「挺音徒鼎反。」","sentenceOrder":240},
  {"id":"s_work_han_thu_39_241","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　應劭曰：「在觀水之陽。」師古曰：「觀音工喚反。」","sentenceOrder":241},
  {"id":"s_work_han_thu_39_242","chapterId":"ch_work_han_thu_39","textTraditional":"高密國，故齊，文帝十六年別為膠西國，宣帝本始元年更為高密國。戶四萬五百三十一，口十九萬二千五百三十六。縣五：高密，莽曰章牟。昌安，石泉，莽曰養信。夷安，莽曰原亭。〔一〕成鄉。莽曰順成。","sentenceOrder":242},
  {"id":"s_work_han_thu_39_243","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「故萊夷維邑。」","sentenceOrder":243},
  {"id":"s_work_han_thu_39_244","chapterId":"ch_work_han_thu_39","textTraditional":"城陽國，故齊。文帝二年別為國。莽曰莒陵。屬兗州。戶五萬六千六百四十二，口二十萬五千七百八十四。縣四：莒，故國，盈姓，三十世為楚所滅。少昊後。有鐵官。莽曰莒陵。陽都，〔一〕東安，慮。莽曰著善。","sentenceOrder":244},
  {"id":"s_work_han_thu_39_245","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「齊人遷陽，故陽國是。」","sentenceOrder":245},
  {"id":"s_work_han_thu_39_246","chapterId":"ch_work_han_thu_39","textTraditional":"淮陽國，高帝十一年置。莽曰新平。屬兗州。〔一〕戶十三萬五千五百四十四，口九十八萬一千四百二十三。縣九：陳，故國，舜後，胡公所封，為楚所滅。楚頃襄王自郢徙此。莽曰陳陵。苦，莽曰賴陵。〔二〕陽夏，〔三〕寧平，扶溝，渦水首受狼湯渠，東至向入淮，過郡三，行千里。〔四〕固始，〔五〕圉，新平，柘。","sentenceOrder":246},
  {"id":"s_work_han_thu_39_247","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　孟康曰：「孝明帝更名陳國。」","sentenceOrder":247},
  {"id":"s_work_han_thu_39_248","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「晉太康地記云城東有賴鄉祠，老子所生地。」","sentenceOrder":248},
  {"id":"s_work_han_thu_39_249","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　應劭曰：「夏音賈。」","sentenceOrder":249},
  {"id":"s_work_han_thu_39_250","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「狼音浪。湯音徒浪反。渦音戈，又音瓜。」","sentenceOrder":250},
  {"id":"s_work_han_thu_39_251","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「本名寢丘，楚令尹孫叔敖所封地。」","sentenceOrder":251},
  {"id":"s_work_han_thu_39_252","chapterId":"ch_work_han_thu_39","textTraditional":"梁國，故秦碭郡，高帝五年為梁國。莽曰陳定。屬豫州。〔一〕戶三萬八千七百九，口十萬六千七百五十二。縣八：碭，山出文石。莽曰節碭。〔二〕甾，故戴國。莽曰嘉穀。〔三〕杼秋，莽曰予秋。〔四〕蒙，獲水首受甾獲渠，東北至彭城入泗，過郡五，行五百五十里。莽曰蒙恩。已氏，莽曰已善。虞，莽曰陳定亭。下邑，莽曰下洽。睢陽。故宋國，微子所封。禹貢盟諸澤在東北。〔五〕","sentenceOrder":252},
  {"id":"s_work_han_thu_39_253","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「以有碭山，故名碭郡。」","sentenceOrder":253},
  {"id":"s_work_han_thu_39_254","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　應劭曰：「碭山在東。」師古曰：「碭，文石也，其山出焉，故以名縣。碭音唐，又音徒浪反。」","sentenceOrder":254},
  {"id":"s_work_han_thu_39_255","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　應劭曰：「章帝改曰考城。」","sentenceOrder":255},
  {"id":"s_work_han_thu_39_256","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「杼音食汝反。」","sentenceOrder":256},
  {"id":"s_work_han_thu_39_257","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「睢音雖。」","sentenceOrder":257},
  {"id":"s_work_han_thu_39_258","chapterId":"ch_work_han_thu_39","textTraditional":"東平國，故梁國，景帝中六年別為濟東國，武帝元鼎元年為大河郡，宣帝甘露二年為東平國。莽曰有鹽。屬兗州。戶十三萬一千七百五十三，口六十萬七千九百七十六。有鐵官。縣七：無鹽，有郈鄉。莽曰有鹽亭。〔一〕任城，故任國，太昊後，風姓。莽曰延就亭。東平陸，〔二〕富城，莽曰成富。章，亢父，詩亭，故詩國。莽曰順父。〔三〕樊。","sentenceOrder":258},
  {"id":"s_work_han_thu_39_259","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「郈音后。」","sentenceOrder":259},
  {"id":"s_work_han_thu_39_260","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　應劭曰：「古厥國，今有厥亭是。」","sentenceOrder":260},
  {"id":"s_work_han_thu_39_261","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「音抗甫。」","sentenceOrder":261},
  {"id":"s_work_han_thu_39_262","chapterId":"ch_work_han_thu_39","textTraditional":"魯國，故秦薛郡，高后元年為魯國。屬豫州。戶十一萬八千四十五，口六十萬七千三百八十一。縣六：魯，伯禽所封。戶五萬二千。有鐵官。卞，泗水西南至方與入沛，過郡三，行五百里，青州川。〔一〕汶陽，莽曰汶亭。〔二〕蕃，南梁水西至胡陵入沛渠。〔三〕騶，故邾國，曹姓，二十九世為楚所滅。嶧山在北。莽曰騶亭。〔四〕薛。夏車正奚仲所國，後遷于邳，湯相仲虺居之。","sentenceOrder":262},
  {"id":"s_work_han_thu_39_263","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「即春秋僖十七年夫人姜氏會齊侯於卞者也。方與音房豫。」","sentenceOrder":263},
  {"id":"s_work_han_thu_39_264","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　應劭曰：「詩曰『汶水湯湯』。」師古曰：「汶音問。即左傳所云公賜季友汶陽之田者也。」","sentenceOrder":264},
  {"id":"s_work_han_thu_39_265","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　應劭曰：「邾國也，音皮。」師古曰：「白裒云陳蕃之子為魯相，國人為諱，改曰皮。此說非也。郡縣之名，土俗各有別稱，不必皆依本字。」","sentenceOrder":265},
  {"id":"s_work_han_thu_39_266","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　應劭曰：「邾文公卜遷于嶧者也。音驛。」","sentenceOrder":266},
  {"id":"s_work_han_thu_39_267","chapterId":"ch_work_han_thu_39","textTraditional":"楚國，高帝置，宣帝地節元年更為彭城郡，黃龍元年復故。莽曰和樂。屬徐州。戶十一萬四千七百三十八，口四十九萬七千八百四。縣七：彭城，古彭祖國。戶四萬一百九十六。有鐵官。留，梧，莽曰吾治。傅陽，故偪陽國。莽曰輔陽。〔一〕呂，武原，莽曰和樂亭。甾丘。莽曰善丘。","sentenceOrder":267},
  {"id":"s_work_han_thu_39_268","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「偪音福。左氏傳所云偪陽妘姓者也。」","sentenceOrder":268},
  {"id":"s_work_han_thu_39_269","chapterId":"ch_work_han_thu_39","textTraditional":"泗水國，故東海郡，武帝元鼎四年別為泗水國。莽曰水順。戶二萬五千二十五，口十一萬九千一百一十四。縣三：淩，莽曰生夌。〔一〕泗陽，莽曰淮平亭。于。莽曰于屏。","sentenceOrder":269},
  {"id":"s_work_han_thu_39_270","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「淩水所出，（入淮南）〔南入淮〕。」","sentenceOrder":270},
  {"id":"s_work_han_thu_39_271","chapterId":"ch_work_han_thu_39","textTraditional":"廣陵國，高帝六年屬荊州，十一年更屬吳，景帝四年更名江都，武帝元狩三年更名廣陵。莽曰江平。屬徐州。戶三萬六千七百七十三，口十四萬七百二十二。有鐵官。縣四：廣陵，江都易王非、廣陵厲王胥皆都此，并得鄣郡，而不得吳。莽曰安定。江都，有江水祠。渠水首受江，北至射陽入湖。高郵，平安。莽曰杜鄉。","sentenceOrder":271},
  {"id":"s_work_han_thu_39_272","chapterId":"ch_work_han_thu_39","textTraditional":"六安國，故楚，高帝元年別為衡山國，五年屬淮南，文帝十六年復為衡山，武帝元狩二年別為六安國。莽曰安風。戶三萬八千三百四十五，口十七萬八千六百一十六。縣五：六，故國，皋繇後，偃姓，為楚所滅。如谿水首受沘，東北至壽春入芍陂。〔一〕蓼，故國，皋繇後，為楚所滅。安豐，禹貢大別山在西南。莽曰美豐。安風，莽曰安風亭。陽泉。","sentenceOrder":272},
  {"id":"s_work_han_thu_39_273","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「沘音匕，又音鄙。芍音鵲。」","sentenceOrder":273},
  {"id":"s_work_han_thu_39_274","chapterId":"ch_work_han_thu_39","textTraditional":"長沙國，秦郡，高帝五年為國。莽曰填蠻。屬荊州。戶四萬三千四百七十，口二十三萬五千八百二十五。縣十三：臨湘，莽曰撫睦。〔一〕羅，〔二〕連道，益陽，湘山在北。〔三〕下雋，莽曰閏雋。〔四〕（收）〔攸〕，酃，〔五〕承陽，〔六〕湘南，禹貢衡山在東南，荊州山。昭陵，荼陵，泥水西入湘，行七百里。莽曰聲鄉。〔七〕容陵，安成。廬水東至廬陵入湖漢。莽曰思成。","sentenceOrder":274},
  {"id":"s_work_han_thu_39_275","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「湘水出零山。」","sentenceOrder":275},
  {"id":"s_work_han_thu_39_276","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　應劭曰：「楚文王徙羅子自枝江居此。」師古曰：「盛弘之荊州記云縣北帶汨水，水原出豫章艾縣界，西流注湘。〈氵公〉汨西北去縣三十里，名為屈潭，屈原自沉處。」","sentenceOrder":276},
  {"id":"s_work_han_thu_39_277","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　應劭曰：「在益水之陽。」","sentenceOrder":277},
  {"id":"s_work_han_thu_39_278","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「雋音字兗反，又音辭兗反。」","sentenceOrder":278},
  {"id":"s_work_han_thu_39_279","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　孟康曰：「音鈴。」","sentenceOrder":279},
  {"id":"s_work_han_thu_39_280","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　應劭曰：「承水之陽。」師古曰：「承水原出零陵永昌縣界，東流注湘也。承音丞。」","sentenceOrder":280},
  {"id":"s_work_han_thu_39_281","chapterId":"ch_work_han_thu_39","textTraditional":"〔七〕　師古曰：「荼音弋奢反，又音丈加反。」","sentenceOrder":281},
  {"id":"s_work_han_thu_39_282","chapterId":"ch_work_han_thu_39","textTraditional":"本秦京師為內史，〔一〕分天下作三十六郡。漢興，以其郡（大）〔太〕大，稍復開置，又立諸侯王國。武帝開廣三邊。故自高祖增二十六，文、景各六，武帝二十八，昭帝一，訖於孝平，凡郡國一百三，縣邑千三百一十四，道三十二，侯國二百四十一。地東西九千三百二里，南北萬三千三百六十八里。提封田一萬萬四千五百一十三萬六千四百五頃，〔二〕其一萬萬二百五十二萬八千八百八十九頃，邑居道路，山川林澤，群不可墾，其三千二百二十九萬九百四十七頃，可墾不可墾，定墾田八百二十七萬五百三十六頃。民戶千二百二十三萬三千六十二，口五千九百五十九萬四千九百七十八。漢極盛矣。","sentenceOrder":282},
  {"id":"s_work_han_thu_39_283","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「京師，天子所都畿內也。秦并天下，改立郡縣，而京畿所統，特號內史，言其在內，以別於諸郡守也。」","sentenceOrder":283},
  {"id":"s_work_han_thu_39_284","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「提封者，大舉其封疆也。」","sentenceOrder":284},
  {"id":"s_work_han_thu_39_285","chapterId":"ch_work_han_thu_39","textTraditional":"凡民函五常之性，〔一〕而其剛柔緩急，音聲不同，繫水土之風氣，故謂之風；好惡取舍，動靜亡常，〔二〕隨君上之情Q欲Y，故謂之俗。孔子曰：「移風易俗，莫善於樂。」〔三〕言聖王在上，統理人倫，必移其本，而易其末，此混同天下一之虖中和，然後王教成也。漢承百（年）〔王〕之末，國土變改，民人遷徙，成帝時劉向略言其（域）〔地〕分，丞相張禹使屬潁川朱贛條其風俗，猶未宣究，故輯而論之，〔四〕終其本末著於篇。","sentenceOrder":285},
  {"id":"s_work_han_thu_39_286","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「函，苞也，讀與含同。」","sentenceOrder":286},
  {"id":"s_work_han_thu_39_287","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「好音呼到反。惡音一故反。」","sentenceOrder":287},
  {"id":"s_work_han_thu_39_288","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「孝經載孔子之言。」","sentenceOrder":288},
  {"id":"s_work_han_thu_39_289","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「輯與集同。」","sentenceOrder":289},
  {"id":"s_work_han_thu_39_290","chapterId":"ch_work_han_thu_39","textTraditional":"秦地，於天官東井、輿鬼之分野也。其界自弘農故關以西，京兆、扶風、馮翊、北地、上郡、西河、安定、天水、隴西，南有巴、蜀、廣漢、犍為、武都，西有金城、武威、張掖、酒泉、敦煌，又西南有牂柯、越巂、益州，皆宜屬焉。","sentenceOrder":290},
  {"id":"s_work_han_thu_39_291","chapterId":"ch_work_han_thu_39","textTraditional":"秦之先曰柏益，出自帝顓頊，堯時助禹治水，為舜朕虞，養育草木鳥獸，賜姓嬴氏，〔一〕歷夏、殷為諸侯。至周有造父，〔二〕善馭習馬，得華騮、綠耳之乘，〔三〕幸於穆王，封於趙城，故更為趙氏。後有非子，為周孝王養馬汧、渭之間。孝王曰：「昔伯益知禽獸，子孫不絕。」乃封為附庸，邑之於秦，今隴西秦亭秦谷是也。至玄孫，氏為莊公，〔四〕破西戎，有其地。子襄公時，幽王為犬戎所敗，平王東遷雒邑。襄公將兵救周有功，賜受廄、酆之地，列為諸侯。〔五〕後八世，穆公稱伯，以河為竟。〔六〕十餘世，孝公用商君，制轅田，〔七〕開仟伯，〔八〕東雄諸侯。子惠公初稱王，得上郡、西河。孫昭王開巴蜀，滅周，取九鼎。昭王曾孫政并六國，稱皇帝，負力怙威，燔書阬儒，自任私智。至子胡亥，天下畔之。","sentenceOrder":291},
  {"id":"s_work_han_thu_39_292","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「伯益一號伯翳，蓋翳益聲相近故也。」","sentenceOrder":292},
  {"id":"s_work_han_thu_39_293","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「造音（於）〔千〕到反。父讀曰甫。」","sentenceOrder":293},
  {"id":"s_work_han_thu_39_294","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「華騮，言其色如華之赤也。綠耳，耳綠色。」","sentenceOrder":294},
  {"id":"s_work_han_thu_39_295","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「氏與是同，古通用字。」","sentenceOrder":295},
  {"id":"s_work_han_thu_39_296","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「廄亦岐字。」","sentenceOrder":296},
  {"id":"s_work_han_thu_39_297","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「伯讀曰霸。竟讀曰境，言其地界東至於河。」","sentenceOrder":297},
  {"id":"s_work_han_thu_39_298","chapterId":"ch_work_han_thu_39","textTraditional":"〔七〕　張晏曰：「周制三年一易，以同美惡，商鞅始割列田地，開立阡陌，令民各有常制。」孟康曰：「三年爰土易居，古制也，末世侵廢。商鞅相秦，復立爰田，上田不易，中田一易，下田再易，爰自在其田，不復易居也。食貨志曰『自爰其處而已』是也。轅爰同。」","sentenceOrder":298},
  {"id":"s_work_han_thu_39_299","chapterId":"ch_work_han_thu_39","textTraditional":"〔八〕　師古曰：「南北曰仟，東西曰伯，皆謂開田之疆畝也。伯音莫白反。」","sentenceOrder":299},
  {"id":"s_work_han_thu_39_300","chapterId":"ch_work_han_thu_39","textTraditional":"故秦地於禹貢時跨雍、梁二州，詩風兼秦、豳兩國。昔后稷封斄，〔一〕公劉處豳，〔二〕大王徙廄，〔三〕文王作酆，〔四〕武王治鎬，〔五〕其民有先王遺風，好稼穡，務本業，故豳詩言農桑衣食之本甚備。〔六〕有鄠、杜竹林，南山檀柘，號稱陸海，為九州膏腴。〔七〕始皇之初，鄭國穿渠，引涇水溉田，〔八〕沃野千里，〔九〕民以富饒。漢興，立都長安，徙齊諸田，楚昭、屈、景及諸功臣家於長陵。後世世徙吏二千石、高訾富人及豪桀并兼之家於諸陵。〔一０〕蓋亦以彊幹弱支，非獨為奉山園也。〔一一〕是故五方雜厝〔一二〕，風俗不純。其世家則好禮文，富人則商賈為利，豪桀則游俠通姦。瀕南山，〔一三〕近夏陽，〔一四〕多阻險輕薄，易為盜賊，常為天下劇。又郡國輻湊，浮食者多，民去本就末，列侯貴人車服僭上，眾庶放效，羞不相及，〔一五〕嫁娶尤崇侈靡，送死過度。","sentenceOrder":300},
  {"id":"s_work_han_thu_39_301","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「斄讀曰邰，今武功故城是也。」","sentenceOrder":301},
  {"id":"s_work_han_thu_39_302","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「即今豳州栒邑是。」","sentenceOrder":302},
  {"id":"s_work_han_thu_39_303","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「今岐山縣是。」","sentenceOrder":303},
  {"id":"s_work_han_thu_39_304","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「今長安西北界靈臺鄉豐水上是。」","sentenceOrder":304},
  {"id":"s_work_han_thu_39_305","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「今昆明池北鎬陂是。」","sentenceOrder":305},
  {"id":"s_work_han_thu_39_306","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「謂七月之詩。」","sentenceOrder":306},
  {"id":"s_work_han_thu_39_307","chapterId":"ch_work_han_thu_39","textTraditional":"〔七〕　師古曰：「言其地高陸而饒物產，如海之無所不出，故云陸海。腹之下肥曰腴，故取諭云。」","sentenceOrder":307},
  {"id":"s_work_han_thu_39_308","chapterId":"ch_work_han_thu_39","textTraditional":"〔八〕　師古曰：「鄭國，人姓名。事具在溝洫志。」","sentenceOrder":308},
  {"id":"s_work_han_thu_39_309","chapterId":"ch_work_han_thu_39","textTraditional":"〔九〕　師古曰：「沃即溉也，言千里之地皆得溉灌。」","sentenceOrder":309},
  {"id":"s_work_han_thu_39_310","chapterId":"ch_work_han_thu_39","textTraditional":"〔一０〕師古曰：「訾讀與貲同。高訾，言多財也。」","sentenceOrder":310},
  {"id":"s_work_han_thu_39_311","chapterId":"ch_work_han_thu_39","textTraditional":"〔一一〕如淳曰：「黃圖謂陵冢為山。」師古曰：「謂京師為幹，四方為支也。」","sentenceOrder":311},
  {"id":"s_work_han_thu_39_312","chapterId":"ch_work_han_thu_39","textTraditional":"〔一二〕晉灼曰：「厝，古錯（反）〔字〕。」","sentenceOrder":312},
  {"id":"s_work_han_thu_39_313","chapterId":"ch_work_han_thu_39","textTraditional":"〔一三〕師古曰：「瀕猶邊。瀕音頻，又音賓。」","sentenceOrder":313},
  {"id":"s_work_han_thu_39_314","chapterId":"ch_work_han_thu_39","textTraditional":"〔一四〕師古曰：「夏陽即河之西岸也。今在同州韓城縣界。」","sentenceOrder":314},
  {"id":"s_work_han_thu_39_315","chapterId":"ch_work_han_thu_39","textTraditional":"〔一五〕師古曰：「放，依也，音甫往反。」","sentenceOrder":315},
  {"id":"s_work_han_thu_39_316","chapterId":"ch_work_han_thu_39","textTraditional":"天水、隴西，山多林木，民以板為室屋。及安定、北地、上郡、西河，皆迫近戎狄，修習戰備，高上氣力，以射獵為先。故秦詩曰「在其板屋」；〔一〕又曰「王于興師，修我甲兵，與子偕行」。〔二〕及車轔、四臷、小戎之篇，皆言車馬田狩之事。〔三〕漢興，六郡良家子選給羽林、期門，〔四〕以材力為官，名將多出焉。孔子曰：「君子有勇而亡誼則為亂，小人有勇而亡誼則為盜。」〔五〕故此數郡，民俗質木，不恥寇盜。〔六〕","sentenceOrder":316},
  {"id":"s_work_han_thu_39_317","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「小戎之詩也。言襄公出征，則婦人居板屋之中而念其君子。」","sentenceOrder":317},
  {"id":"s_work_han_thu_39_318","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「無衣之詩也。言於王之興師，則修我甲兵，而與子俱征伐也。」","sentenceOrder":318},
  {"id":"s_work_han_thu_39_319","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「車轔、美秦仲大有車馬。其詩曰『有車轔轔，有馬白顛』。四臷，美襄公田狩也。其詩曰『四臷孔阜，六轡在手』，『輶車鸞鑣，載獫猲獢』。小戎，美襄公備兵甲，討西戎。其詩曰『小戎俴收，五楘良輈』，『文茵暢轂，駕我騏馵』，『龍盾之合，鋈以觼軜』。轔音鄰。臷音耋。輶音猶，又音誘。獫音力贍反。獢音許昭反。俴音踐。楘音木。馵音〈氵{山王}〉。鋈音沃。觼音玦。軜音納。」","sentenceOrder":319},
  {"id":"s_work_han_thu_39_320","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　如淳曰：「醫、商賈、百工不得豫也。」師古曰：「六郡謂隴西、天水、安定、北地、上郡，西河。羽林、期門，解在百官公卿表。」","sentenceOrder":320},
  {"id":"s_work_han_thu_39_321","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「論語載孔子對子路之言也。」","sentenceOrder":321},
  {"id":"s_work_han_thu_39_322","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「質木者，無有文飾，如木石然。」","sentenceOrder":322},
  {"id":"s_work_han_thu_39_323","chapterId":"ch_work_han_thu_39","textTraditional":"自武威以西，本匈奴昆邪王、休屠王地，〔一〕武帝時攘之〔二〕，初置四郡，以通西域，鬲絕南羌、匈奴。〔三〕其民或以關東下貧，或以報怨過當，〔四〕或以誖逆亡道，家屬徙焉。〔五〕習俗頗殊，地廣民稀，水屮宜畜牧，〔六〕（古）〔故〕涼州之畜為天下饒。保邊塞，二千石治之，咸以兵馬為務；酒禮之會，上下通焉，吏民相親。是以其俗風雨時節，穀糴常賤，少盜賊，有和氣之應，賢於內郡。此政寬厚，吏不苛刻之所致也。","sentenceOrder":323},
  {"id":"s_work_han_thu_39_324","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「昆音下門反。休音許虯反。屠音除。」","sentenceOrder":324},
  {"id":"s_work_han_thu_39_325","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「攘，卻也，音人羊反。」","sentenceOrder":325},
  {"id":"s_work_han_thu_39_326","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「鬲與隔同。」","sentenceOrder":326},
  {"id":"s_work_han_thu_39_327","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「過其本所殺。」","sentenceOrder":327},
  {"id":"s_work_han_thu_39_328","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「誖，亂也，惑也，音布內反。」","sentenceOrder":328},
  {"id":"s_work_han_thu_39_329","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「屮，古草字。」","sentenceOrder":329},
  {"id":"s_work_han_thu_39_330","chapterId":"ch_work_han_thu_39","textTraditional":"巴、蜀、廣漢本南夷，秦并以為郡，土地肥美，有江水沃野，山林竹木疏食果實之饒。〔一〕南賈滇、僰僮，〔二〕西近邛、莋馬旄牛。〔三〕民食稻魚，亡凶年憂，俗不愁苦，而輕易淫泆，柔弱褊阨。〔四〕景、武間，文翁為蜀守，教民讀書法令，未能篤信道德，反以好文刺譏，貴慕權勢。及司馬相如游宦京師諸侯，以文辭顯於世，鄉黨慕循其跡。後有王褒、嚴遵、揚雄之徒，〔五〕文章冠天下。繇文翁倡其教，相如為之師，〔六〕故孔子曰：「有教亡類。」〔七〕","sentenceOrder":330},
  {"id":"s_work_han_thu_39_331","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「疏菜也。」","sentenceOrder":331},
  {"id":"s_work_han_thu_39_332","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「言滇、僰之地多出僮隸也。滇音顛。僰音蒲北反。」","sentenceOrder":332},
  {"id":"s_work_han_thu_39_333","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「言邛、莋之地出馬及旄牛。莋音材各反。」","sentenceOrder":333},
  {"id":"s_work_han_thu_39_334","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「言其材質不彊，而心忿陿。」","sentenceOrder":334},
  {"id":"s_work_han_thu_39_335","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「遵即嚴君平。」","sentenceOrder":335},
  {"id":"s_work_han_thu_39_336","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「繇讀與由同。倡，始也，音充向反。」","sentenceOrder":336},
  {"id":"s_work_han_thu_39_337","chapterId":"ch_work_han_thu_39","textTraditional":"〔七〕　師古曰：「論語載孔子之言。言人之性術在所教耳，無種類。」","sentenceOrder":337},
  {"id":"s_work_han_thu_39_338","chapterId":"ch_work_han_thu_39","textTraditional":"武都地雜氐、羌，及犍為、牂柯、越巂，皆西南外夷，武帝初開置。民俗略與巴、蜀同，而武都近天水，俗頗似焉。","sentenceOrder":338},
  {"id":"s_work_han_thu_39_339","chapterId":"ch_work_han_thu_39","textTraditional":"故秦地天下三分之一，而人眾不過什三，然量其富居什六。（秦豳）吳札觀樂，為之歌秦，〔一〕曰：「此之謂夏聲。〔二〕夫能夏則大，大之至也，其周舊乎？」","sentenceOrder":339},
  {"id":"s_work_han_thu_39_340","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「札，吳王壽夢子也，來聘魯而請觀周樂。事見左氏傳襄二十九年。」","sentenceOrder":340},
  {"id":"s_work_han_thu_39_341","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「夏，中國。」","sentenceOrder":341},
  {"id":"s_work_han_thu_39_342","chapterId":"ch_work_han_thu_39","textTraditional":"自井十度至柳三度，謂之鶉首之次，秦之分也。","sentenceOrder":342},
  {"id":"s_work_han_thu_39_343","chapterId":"ch_work_han_thu_39","textTraditional":"魏地，觜觿、參之分野也。〔一〕其界自高陵以東，盡河東、河內，南有陳留及汝南之召陵、〈氵隱〉彊、新汲、西華、長平，〔二〕潁川之舞陽、郾、許、傿陵，〔三〕河南之開封、中牟、陽武、酸棗、卷，〔四〕皆魏分也。","sentenceOrder":343},
  {"id":"s_work_han_thu_39_344","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「觿音弋隨反。」","sentenceOrder":344},
  {"id":"s_work_han_thu_39_345","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「召讀曰邵。〈氵隱〉音於靳反，又音殷。」","sentenceOrder":345},
  {"id":"s_work_han_thu_39_346","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「郾音一扇反。傿音偃。」","sentenceOrder":346},
  {"id":"s_work_han_thu_39_347","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「卷音去權反。」","sentenceOrder":347},
  {"id":"s_work_han_thu_39_348","chapterId":"ch_work_han_thu_39","textTraditional":"河內本殷之舊都，周既滅殷，分其畿內為三國，詩風邶、庸、衛國是也。〔一〕鄁，以封紂子武庚；庸，管叔尹之；衛，蔡叔尹之：以監殷民，謂之三監。〔二〕故書序曰「武王崩，三監畔」，〔三〕周公誅之，盡以其地封弟康叔，號曰孟侯，〔四〕以夾輔周室；遷邶、庸之民于雒邑，故邶、庸、衛三國之詩相與同風。邶詩曰「在浚之下」，〔五〕庸曰「在浚之郊」；〔六〕邶又曰「亦流于淇」，〔七〕「河水洋洋」，〔八〕庸曰「送我淇上」，〔九〕「在彼中河」，〔一０〕衛曰「瞻彼淇奧」，〔一一〕「河水洋洋」。〔一二〕故吳公子札聘魯觀周樂，聞邶、庸、衛之歌，曰：「美哉淵乎！吾聞康叔之德如是，是其衛風乎？」至十六世，懿公亡道，為狄所滅。齊桓公帥諸侯伐狄，而更封衛於河南曹、楚丘，是為文公。〔一三〕而河內殷虛，更屬于晉。〔一四〕康叔之風既歇，而紂之化猶存，故俗剛彊，多豪桀侵奪，薄恩禮，好生分。〔一五〕","sentenceOrder":348},
  {"id":"s_work_han_thu_39_349","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「自紂城而北謂之邶，南謂之庸，東謂之衛。邶音步內反，字或作鄁。庸字或作鄘。」","sentenceOrder":349},
  {"id":"s_work_han_thu_39_350","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「武庚即祿父也。尹，主也。管叔、蔡叔皆武王之弟。」","sentenceOrder":350},
  {"id":"s_work_han_thu_39_351","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「周書大誥之序。」","sentenceOrder":351},
  {"id":"s_work_han_thu_39_352","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「康叔亦武王弟也。孟，長也。言為諸侯之長。」","sentenceOrder":352},
  {"id":"s_work_han_thu_39_353","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「凱風之詩也。浚，衛邑也，音峻。」","sentenceOrder":353},
  {"id":"s_work_han_thu_39_354","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「干旄之詩。」","sentenceOrder":354},
  {"id":"s_work_han_thu_39_355","chapterId":"ch_work_han_thu_39","textTraditional":"〔七〕　師古曰：「泉水之詩。」","sentenceOrder":355},
  {"id":"s_work_han_thu_39_356","chapterId":"ch_work_han_thu_39","textTraditional":"〔八〕　師古曰：「今邶詩無此句。」","sentenceOrder":356},
  {"id":"s_work_han_thu_39_357","chapterId":"ch_work_han_thu_39","textTraditional":"〔九〕　師古曰：「桑中之詩。淇上，淇水之上。」","sentenceOrder":357},
  {"id":"s_work_han_thu_39_358","chapterId":"ch_work_han_thu_39","textTraditional":"〔一０〕師古曰：「柏舟之詩也。中河，河中也。」","sentenceOrder":358},
  {"id":"s_work_han_thu_39_359","chapterId":"ch_work_han_thu_39","textTraditional":"〔一一〕師古曰：「淇奧之詩也。奧，水隈也，音於六反。」","sentenceOrder":359},
  {"id":"s_work_han_thu_39_360","chapterId":"ch_work_han_thu_39","textTraditional":"〔一二〕師古曰：「碩人之詩也。洋洋，盛大也，音羊，又音翔。」","sentenceOrder":360},
  {"id":"s_work_han_thu_39_361","chapterId":"ch_work_han_thu_39","textTraditional":"〔一三〕師古曰：「曹及楚丘，二邑名。」","sentenceOrder":361},
  {"id":"s_work_han_thu_39_362","chapterId":"ch_work_han_thu_39","textTraditional":"〔一四〕師古曰：「殷虛，汲郡朝歌縣也。虛讀曰墟。」","sentenceOrder":362},
  {"id":"s_work_han_thu_39_363","chapterId":"ch_work_han_thu_39","textTraditional":"〔一五〕師古曰：「生分，謂父母在而昆弟不同財產。」","sentenceOrder":363},
  {"id":"s_work_han_thu_39_364","chapterId":"ch_work_han_thu_39","textTraditional":"河東土地平易，有鹽鐵之饒，本唐堯所居，詩風唐、魏之國也。周武王子唐叔在母未生，〔一〕武王夢帝謂己〔二〕曰：「余名而子曰虞，將與之唐，屬之參。」〔三〕及生，名之曰虞。至成王滅唐，而封叔虞。唐有晉水，及叔虞子燮為晉侯云，故參為晉星。其民有先王遺教，君子深思，小人儉陋。故唐詩蟋蟀、山樞、葛生之篇曰「今我不樂，日月其邁」；〔四〕「宛其死矣，它人是媮」；〔五〕「百歲之後，歸于其居」。〔六〕皆思奢儉之中，念死生之慮。〔七〕吳札聞唐之歌，曰：「思深哉！其有陶唐氏之遺民乎？」","sentenceOrder":364},
  {"id":"s_work_han_thu_39_365","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「謂懷孕時。」","sentenceOrder":365},
  {"id":"s_work_han_thu_39_366","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「帝，天也。」","sentenceOrder":366},
  {"id":"s_work_han_thu_39_367","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「屬音之欲反。參音所林反。」","sentenceOrder":367},
  {"id":"s_work_han_thu_39_368","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「蟋蟀之詩也。邁，行也。言日月行往，將老而死也。蟋音悉。蟀音率。」","sentenceOrder":368},
  {"id":"s_work_han_thu_39_369","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「山有樞之詩也。媮，樂也。言己儉吝，死亡之後當為它人所樂也。媮音愉，又音偷。樞音甌。」","sentenceOrder":369},
  {"id":"s_work_han_thu_39_370","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「葛生之詩也。居謂墳墓也。言死當歸于墳墓，不能復為樂也。」","sentenceOrder":370},
  {"id":"s_work_han_thu_39_371","chapterId":"ch_work_han_thu_39","textTraditional":"〔七〕　師古曰：「中音竹仲反。」","sentenceOrder":371},
  {"id":"s_work_han_thu_39_372","chapterId":"ch_work_han_thu_39","textTraditional":"魏國，亦姬姓也，在晉之南河曲，故其詩曰「彼汾一曲」；〔一〕「寘諸河之側」。〔二〕自唐叔十六世至獻公，滅魏以封大夫畢萬，〔三〕滅耿以封大夫趙夙，〔四〕及大夫韓武子食采於韓原，〔五〕晉於是始大。至於文公，伯諸侯，尊周室，〔六〕始有河內之土。〔七〕吳札聞魏之歌，曰：「美哉渢渢乎！〔八〕以德輔此，則明主也。」文公後十六世為韓、魏、趙所滅，三家皆自立為諸侯，是為三晉。趙與秦同祖，韓、趙皆姬姓也。自畢萬後十世稱侯，至孫稱王，徙都大梁，故魏一號為梁，七世為秦所滅。","sentenceOrder":372},
  {"id":"s_work_han_thu_39_373","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「汾沮洳之詩。沮音子豫反。洳音人豫反。」","sentenceOrder":373},
  {"id":"s_work_han_thu_39_374","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「伐檀之詩。寘，置也，音之豉反。」","sentenceOrder":374},
  {"id":"s_work_han_thu_39_375","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「畢萬，畢公高之後，魏犨祖父。」","sentenceOrder":375},
  {"id":"s_work_han_thu_39_376","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「趙夙，趙衰之兄。」","sentenceOrder":376},
  {"id":"s_work_han_thu_39_377","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「韓武子，韓厥之曾祖也，本與周同姓，食采於韓，更為韓氏。此說依史記，而與釋春秋傳者不同。」","sentenceOrder":377},
  {"id":"s_work_han_thu_39_378","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「伯讀曰霸。」","sentenceOrder":378},
  {"id":"s_work_han_thu_39_379","chapterId":"ch_work_han_thu_39","textTraditional":"〔七〕　師古曰：「左氏傳所謂『始啟南陽』者。」","sentenceOrder":379},
  {"id":"s_work_han_thu_39_380","chapterId":"ch_work_han_thu_39","textTraditional":"〔八〕　師古曰：「渢渢，浮貌也。言其中庸，可與為善，可與為惡也。渢音馮。」","sentenceOrder":380},
  {"id":"s_work_han_thu_39_381","chapterId":"ch_work_han_thu_39","textTraditional":"周地，柳、七星、張之分野也。今之河南雒陽、穀成、平陰、偃師、鞏、緱氏，是其分也。","sentenceOrder":381},
  {"id":"s_work_han_thu_39_382","chapterId":"ch_work_han_thu_39","textTraditional":"昔周公營雒邑，以為在于土中，諸侯蕃屏四方，〔一〕故立京師。至幽王淫褒姒，以滅宗周，子平王東居雒邑。其後五伯更帥諸侯以尊周室，〔二〕故周於三代最為長久。八百餘年至於赧王，乃為秦所兼。初雒邑與宗周通封畿，〔三〕東西長而南北短，短長相覆為千里。至襄王以河內賜晉文公，又為諸侯所侵，故其分墬小。〔四〕","sentenceOrder":382},
  {"id":"s_work_han_thu_39_383","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「言雒陽四面皆有諸侯為蕃屏。」","sentenceOrder":383},
  {"id":"s_work_han_thu_39_384","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「伯讀曰霸。解在刑法志。更，互也，音工衡反。」","sentenceOrder":384},
  {"id":"s_work_han_thu_39_385","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　韋昭曰：「通在二封之地，共千里也。」師古曰：「宗周，鎬京也，方八百里，八八六十四，為方百里者六十四也。雒邑，成周也，方六百里，六六三十六，為方百里者三十六。（三）〔二〕都得百里者〔百〕，方千里也。故詩云『邦畿千里』。」","sentenceOrder":385},
  {"id":"s_work_han_thu_39_386","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「墬，古地字。」","sentenceOrder":386},
  {"id":"s_work_han_thu_39_387","chapterId":"ch_work_han_thu_39","textTraditional":"周人之失，巧偽趨利，貴財賤義，高富下貧，憙為商賈，不好仕宦。〔一〕","sentenceOrder":387},
  {"id":"s_work_han_thu_39_388","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「憙音許吏反。」","sentenceOrder":388},
  {"id":"s_work_han_thu_39_389","chapterId":"ch_work_han_thu_39","textTraditional":"自柳三度至張十二度，謂之鶉火之次，周之分也。","sentenceOrder":389},
  {"id":"s_work_han_thu_39_390","chapterId":"ch_work_han_thu_39","textTraditional":"韓地，角、亢、氐之分野也。韓分晉得南陽郡及潁川之父城、定陵、襄城、潁陽、潁陰、長社、陽翟、郟，〔一〕東接汝南，西接弘農得新安、宜陽，皆韓分也。及詩風陳、鄭之國，與韓同星分焉。","sentenceOrder":390},
  {"id":"s_work_han_thu_39_391","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「郟音工洽反，即今郟城縣是也。」","sentenceOrder":391},
  {"id":"s_work_han_thu_39_392","chapterId":"ch_work_han_thu_39","textTraditional":"鄭國，今河南之新鄭，本高辛氏火正祝融之虛也。〔一〕及成皋、滎陽，潁川之崇高、陽城，皆鄭分也。本周宣王弟友為周司徒，食采於宗周畿內，是為鄭。〔二〕鄭桓公問於史伯曰：「王室多故，何所可以逃死？」史伯曰：「四方之國，非王母弟甥舅則夷狄，不可入也，其濟、洛、河、潁之間乎！〔三〕子男之國，虢、會為大，〔四〕恃勢與險，崈侈貪冒，〔五〕君若寄帑與賄，周亂而敝，必將背君；〔六〕君以成周之眾，奉辭伐罪，亡不克矣。」公曰：「南方不可乎？」對曰：「夫楚，重黎之後也，黎為高辛氏火正，昭顯天地，以生柔嘉之材。姜、嬴、荊、羋，實與諸姬代相干也。〔七〕姜，伯夷之後也；嬴，伯益之後也。伯夷能禮於神以佐堯，伯益能儀百物以佐舜，〔八〕其後皆不失祠，而未有興者，周衰將起，不可偪也。」桓公從其言，乃東寄帑與賄，虢、會受之。後三年，幽王敗，（威）〔桓〕公死，其子武公與平王東遷，卒定虢、會之地，右雒左（沛）〔泲〕，食溱、洧焉。〔九〕土陿而險，山居谷汲，男女亟聚會，〔一０〕故其俗淫。鄭詩曰：「出其東門，有女如雲。」〔一一〕又曰：「溱與洧方灌灌兮，士與女方秉菅兮。」「恂盱且樂，惟士與女，伊其相謔。」〔一二〕此其風也。吳札聞鄭之歌，曰：「美哉！其細已甚，民弗堪也。是其先亡乎？」〔一三〕自武公後二十三世，為韓所滅。","sentenceOrder":392},
  {"id":"s_work_han_thu_39_393","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「虛讀曰墟。後皆類此。」","sentenceOrder":393},
  {"id":"s_work_han_thu_39_394","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「即今之華陰鄭縣。」","sentenceOrder":394},
  {"id":"s_work_han_thu_39_395","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「濟音子禮反。」","sentenceOrder":395},
  {"id":"s_work_han_thu_39_396","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「會讀曰鄶，字或作檜。檜國在豫州外方之北，滎播之南，溱、洧之間，妘姓之國。」","sentenceOrder":396},
  {"id":"s_work_han_thu_39_397","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「冒，蒙也，蔽於義理。」","sentenceOrder":397},
  {"id":"s_work_han_thu_39_398","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「帑讀與孥同，謂妻子也。」","sentenceOrder":398},
  {"id":"s_work_han_thu_39_399","chapterId":"ch_work_han_thu_39","textTraditional":"〔七〕　師古曰：「代，遞也。干，犯也。」","sentenceOrder":399},
  {"id":"s_work_han_thu_39_400","chapterId":"ch_work_han_thu_39","textTraditional":"〔八〕　師古曰：「儀與宜同。宜，安也。」","sentenceOrder":400},
  {"id":"s_work_han_thu_39_401","chapterId":"ch_work_han_thu_39","textTraditional":"〔九〕　師古曰：「溱、洧，二水也。溱音臻。洧音鮪。」","sentenceOrder":401},
  {"id":"s_work_han_thu_39_402","chapterId":"ch_work_han_thu_39","textTraditional":"〔一０〕師古曰：「亟，屢也，音丘吏反。」","sentenceOrder":402},
  {"id":"s_work_han_thu_39_403","chapterId":"ch_work_han_thu_39","textTraditional":"〔一一〕師古曰：「出其東門之詩。東門，鄭之東門也。如雲，言其眾多而往來不定。」","sentenceOrder":403},
  {"id":"s_work_han_thu_39_404","chapterId":"ch_work_han_thu_39","textTraditional":"〔一二〕師古曰：「溱洧之詩也。灌灌，水流盛也。菅，蘭也。恂，信也。盱，大也。伊，惟也。謔，戲言也。謂仲春之月，二水流盛，而士與女執芳草於其間，以相贈遺，信大樂矣，惟以戲謔也。灌音胡貫反。菅音姦。」","sentenceOrder":404},
  {"id":"s_work_han_thu_39_405","chapterId":"ch_work_han_thu_39","textTraditional":"〔一三〕臣瓚曰：「謂音聲細弱也，此衰弱之徵。」","sentenceOrder":405},
  {"id":"s_work_han_thu_39_406","chapterId":"ch_work_han_thu_39","textTraditional":"陳國，今淮陽之地。陳本太昊之虛，周武王封舜後媯滿於陳，是為胡公，妻以元女大姬。婦人尊貴，好祭祀，用史巫，故其俗巫鬼。陳詩曰：「坎其擊鼓，宛丘之下，亡冬亡夏，值其鷺羽。」〔一〕又曰：「東門之枌，宛丘之栩，子仲之子，婆娑其下。」〔二〕此其風也。吳札聞陳之歌，曰：「國亡主，其能久乎！」〔三〕自胡公後二十三世為楚所滅。陳雖屬楚，於天文自若其故。","sentenceOrder":406},
  {"id":"s_work_han_thu_39_407","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「宛丘之詩也。坎坎，擊鼓聲。四方高，中央下，曰宛丘。值，立也。鷺鳥之羽以為翿，立之而舞，以事神也。無冬無夏，言其恆也。」","sentenceOrder":407},
  {"id":"s_work_han_thu_39_408","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「東門之枌之詩也。東門，陳國之東門也。枌，白榆也。栩，杼也。子仲，陳大夫之氏也。婆娑。舞貌也。亦言於枌栩之下歌舞以娛神也。枌音扶云反。栩音許羽反。杼音神汝反。」","sentenceOrder":408},
  {"id":"s_work_han_thu_39_409","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「言政由婦人，不以君為主也。」","sentenceOrder":409},
  {"id":"s_work_han_thu_39_410","chapterId":"ch_work_han_thu_39","textTraditional":"潁川、南陽，本夏禹之國。夏人上忠，其敝鄙朴。韓自武子後七世稱侯，六世稱王，五世而為秦所滅。秦既滅韓，徙天下不軌之民於南陽，〔一〕故其俗夸奢，上氣力，好商賈漁獵，藏匿難制御也。宛，西通武關，東受江、淮，一都之會也。宣帝時，鄭弘、召信臣為南陽太守，〔二〕治皆見紀。信臣勸民農桑，去末歸本，郡以殷富。潁川，韓都。士有申子、韓非，刻害餘烈，〔三〕高（士）〔仕〕宦，好文法，民以貪遴爭訟生分為失。〔四〕韓延壽為太守，先之以敬讓；黃霸繼之，教化大行，獄或八年亡重罪囚。南陽好商賈，召父富以本業；〔五〕潁川好爭訟分異，黃、韓化以篤厚。「君子之德風也，小人之德草也」，信矣。〔六〕","sentenceOrder":410},
  {"id":"s_work_han_thu_39_411","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「不軌，不循法度者。」","sentenceOrder":411},
  {"id":"s_work_han_thu_39_412","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「召讀曰邵。」","sentenceOrder":412},
  {"id":"s_work_han_thu_39_413","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「申子，申不害也。烈，業也。」","sentenceOrder":413},
  {"id":"s_work_han_thu_39_414","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「遴與吝同。」","sentenceOrder":414},
  {"id":"s_work_han_thu_39_415","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「召父，謂召信臣也。勸其務農以致富。」","sentenceOrder":415},
  {"id":"s_work_han_thu_39_416","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「論語載孔子之言也。曰『君子之德風，小人之德草也，草上之風必偃』。言從教而化。」","sentenceOrder":416},
  {"id":"s_work_han_thu_39_417","chapterId":"ch_work_han_thu_39","textTraditional":"自東井六度至亢六度，謂之壽星之次，鄭之分野，與韓同分。","sentenceOrder":417},
  {"id":"s_work_han_thu_39_418","chapterId":"ch_work_han_thu_39","textTraditional":"趙地，昴、畢之分野。趙分晉，得趙國。北有信都、真定、常山、中山，又得涿郡之高陽、鄚、州鄉；〔一〕東有廣平、鉅鹿、清河、河間，又得渤海郡之東平舒、中邑、文安、束州、成平、章武，河以北也；南至浮水、繁陽、內黃、斥丘；西有太原、定襄、雲中、五原、上黨。上黨，本韓之別郡也，遠韓近趙，後卒降趙，皆趙分也。","sentenceOrder":418},
  {"id":"s_work_han_thu_39_419","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「鄚音莫。」","sentenceOrder":419},
  {"id":"s_work_han_thu_39_420","chapterId":"ch_work_han_thu_39","textTraditional":"自趙夙後九世稱侯，四世敬侯徙都邯鄲，至曾孫武靈王稱王，五世為秦所滅。","sentenceOrder":420},
  {"id":"s_work_han_thu_39_421","chapterId":"ch_work_han_thu_39","textTraditional":"趙、中山地薄人眾，猶有沙丘紂淫亂餘民。〔一〕丈夫相聚游戲，悲歌慷慨，起則椎剽掘冢，〔二〕作姦巧，多弄物，為倡優。女子彈弦跕躧，游媚富貴，遍諸侯之後宮。〔三〕","sentenceOrder":421},
  {"id":"s_work_han_thu_39_422","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　晉灼曰：「言地薄人眾，猶復有沙丘紂淫地餘民，通係之於淫風而言之也，不說沙丘在中山也。」","sentenceOrder":422},
  {"id":"s_work_han_thu_39_423","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「椎殺人而剽劫之也。椎音直追反，其字從木。剽音頻妙反。掘冢，發冢也。」","sentenceOrder":423},
  {"id":"s_work_han_thu_39_424","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　如淳曰：「跕音蹀足之蹀。躧音屣。」臣瓚曰：「躡跟為跕，拄指為躧。」師古曰：「跕音它頰反。躧字與屣同。屣謂小履之無跟者也。跕謂輕躡之也。」","sentenceOrder":424},
  {"id":"s_work_han_thu_39_425","chapterId":"ch_work_han_thu_39","textTraditional":"邯鄲北通燕、涿，南有鄭、衛，漳、河之間一都會也。其土廣俗雜，大率精急，高氣勢，輕為姦。","sentenceOrder":425},
  {"id":"s_work_han_thu_39_426","chapterId":"ch_work_han_thu_39","textTraditional":"太原、上黨又多晉公族子孫，以詐力相傾，矜夸功名，報仇過直，〔一〕嫁取送死奢靡。〔二〕漢興，號為難治，常擇嚴猛之將，或任殺伐為威。父兄被誅，子弟怨憤，至告訐刺史二千石，〔三〕或報殺其親屬。","sentenceOrder":426},
  {"id":"s_work_han_thu_39_427","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「直，亦當也。」","sentenceOrder":427},
  {"id":"s_work_han_thu_39_428","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「取讀曰娶。其下並同。」","sentenceOrder":428},
  {"id":"s_work_han_thu_39_429","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「訐，面相斥罪也，音居列反，又音居謁反。」","sentenceOrder":429},
  {"id":"s_work_han_thu_39_430","chapterId":"ch_work_han_thu_39","textTraditional":"鍾、代、石、北，迫近胡寇，〔一〕民俗懻忮，〔二〕好氣為姦，不事農商，自全晉時，已患其剽悍，〔三〕而武靈王又益厲之。故冀州之部，盜賊常為它州劇。","sentenceOrder":430},
  {"id":"s_work_han_thu_39_431","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　如淳曰：「鍾，所在未聞。石，山險之限，在上曲陽。」","sentenceOrder":431},
  {"id":"s_work_han_thu_39_432","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　臣瓚曰：「懻音冀，今北土名彊直為懻中。」師古曰：「懻，堅也。忮，恨也，音章豉反。」","sentenceOrder":432},
  {"id":"s_work_han_thu_39_433","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「剽，急也，輕也。悍，勇也。剽音頻妙反，又音疋妙反。悍音胡旦反。」","sentenceOrder":433},
  {"id":"s_work_han_thu_39_434","chapterId":"ch_work_han_thu_39","textTraditional":"定襄、雲中、五原，本戎狄地，頗有趙、齊、衛、楚之徙。〔一〕其民鄙朴，少禮文，好射獵。雁門亦同俗，於天文別屬燕。","sentenceOrder":434},
  {"id":"s_work_han_thu_39_435","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「言四國之人被遷徙來居之。」","sentenceOrder":435},
  {"id":"s_work_han_thu_39_436","chapterId":"ch_work_han_thu_39","textTraditional":"燕地，尾、箕分野也。武王定殷，封召公於燕，其後三十六世與六國俱稱王。東有漁陽、右北平、遼西，遼東，西有上谷、代郡、雁門，南得涿郡之易、容城、范陽、北新城、故安、涿縣、良鄉、新昌，及勃海之安次，皆燕分也。樂浪、玄菟，亦宜屬焉。","sentenceOrder":436},
  {"id":"s_work_han_thu_39_437","chapterId":"ch_work_han_thu_39","textTraditional":"燕稱王十世，秦欲滅六國，燕王太子丹遣勇士荊軻西刺秦王，不成而誅，秦遂舉兵滅燕。","sentenceOrder":437},
  {"id":"s_work_han_thu_39_438","chapterId":"ch_work_han_thu_39","textTraditional":"薊，南通齊、趙，勃、碣之間一都會也。〔一〕初太子丹賓養勇士，不愛後宮美女，民化以為俗，至今猶然。賓客相過，以婦侍宿，嫁取之夕，男女無別，反以為榮。後稍頗止，然終未改。其俗愚悍少慮，輕薄無威，亦有所長，敢於急人，〔二〕燕丹遺風也。","sentenceOrder":438},
  {"id":"s_work_han_thu_39_439","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「薊縣，燕之所都也。勃，勃海也。碣，碣石也。」","sentenceOrder":439},
  {"id":"s_work_han_thu_39_440","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　如淳曰：「赴人之急，果於赴難也。」","sentenceOrder":440},
  {"id":"s_work_han_thu_39_441","chapterId":"ch_work_han_thu_39","textTraditional":"上谷至遼東，地廣民希，數被胡寇，俗與趙、代相類，有魚鹽棗栗之饒。北隙烏丸、夫餘，〔一〕東賈真番之利。","sentenceOrder":441},
  {"id":"s_work_han_thu_39_442","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　如淳曰：「有怨隙也。或曰，隙，際也。」師古曰：「訓際是也。烏丸，本東胡也，為冒頓所滅，餘類保烏丸山，因以為號。夫餘在長城之北，去玄菟千里。夫讀曰扶。」","sentenceOrder":442},
  {"id":"s_work_han_thu_39_443","chapterId":"ch_work_han_thu_39","textTraditional":"玄菟、樂浪，武帝時置，皆朝鮮、濊貉、句驪蠻夷。〔一〕殷道衰，箕子去之朝鮮，〔二〕教其民以禮義，田蠶織作。樂浪朝鮮民犯禁八條：〔三〕相殺以當時償殺；相傷以穀償；相盜者男沒入為其家奴，女子為婢，欲自贖者，人五十萬。雖免為民，俗猶羞之，嫁取無所讎，〔四〕是以其民終不相盜，無門戶之閉，婦人貞信不淫辟〔五〕。其田民飲食以籩豆，〔六〕都邑頗放效吏及內郡賈人，往往以杯器食。〔七〕郡初取吏於遼東，吏見民無閉臧，及賈人往者，夜則為盜，俗稍益薄。今於犯禁浸多，至六十餘條。可貴哉，仁賢之化也！然東夷天性柔順，異於三方之外，〔八〕故孔子悼道不行，設浮於海，欲居九夷，有以也夫！〔九〕樂浪海中有倭人，分為百餘國，以歲時來獻見云。〔一０〕","sentenceOrder":443},
  {"id":"s_work_han_thu_39_444","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「濊音穢，字或作薉，其音同。」","sentenceOrder":444},
  {"id":"s_work_han_thu_39_445","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「史記云『武王伐紂，封箕子於朝鮮』，與此不同。」","sentenceOrder":445},
  {"id":"s_work_han_thu_39_446","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「八條不具見。」","sentenceOrder":446},
  {"id":"s_work_han_thu_39_447","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「讎，匹也。一曰，讎讀曰售。」","sentenceOrder":447},
  {"id":"s_work_han_thu_39_448","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「辟讀曰僻。」","sentenceOrder":448},
  {"id":"s_work_han_thu_39_449","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「以竹曰籩，以木曰豆，若今之檠也。檠音其敬反。」","sentenceOrder":449},
  {"id":"s_work_han_thu_39_450","chapterId":"ch_work_han_thu_39","textTraditional":"〔七〕　師古曰：「都邑之人頗用杯器者，效吏及賈人也。放音甫往反。」","sentenceOrder":450},
  {"id":"s_work_han_thu_39_451","chapterId":"ch_work_han_thu_39","textTraditional":"〔八〕　師古曰：「三方，謂南、西、北也。」","sentenceOrder":451},
  {"id":"s_work_han_thu_39_452","chapterId":"ch_work_han_thu_39","textTraditional":"〔九〕　師古曰：「論語稱孔子曰：『道不行，乘桴浮於海，從我者其由也歟！』言欲乘桴筏而適東夷，以其國有仁賢之化，可以行道也。桴音孚。筏音伐。」","sentenceOrder":452},
  {"id":"s_work_han_thu_39_453","chapterId":"ch_work_han_thu_39","textTraditional":"〔一０〕如淳曰：「如墨委面，在帶方東南萬里。」臣瓚曰：「倭是國名，不謂用墨，故謂之委也。」師古曰：「如淳云『如墨委面』，蓋音委字耳，此音非也。倭音一戈反，今猶有倭國。魏略云倭在帶方東南大海中，依山島為國，度海千里，復有國，皆倭種。」","sentenceOrder":453},
  {"id":"s_work_han_thu_39_454","chapterId":"ch_work_han_thu_39","textTraditional":"自危四度至斗六度，謂之析木之次，燕之分也。","sentenceOrder":454},
  {"id":"s_work_han_thu_39_455","chapterId":"ch_work_han_thu_39","textTraditional":"齊地，虛、危之分野也。東有甾川、東萊、琅邪、高密、膠東，南有泰山、城陽，北有千乘，清河以南，勃海之高樂、高城、重合、陽信，西有濟南、平原，皆齊分也。","sentenceOrder":455},
  {"id":"s_work_han_thu_39_456","chapterId":"ch_work_han_thu_39","textTraditional":"少昊之世有爽鳩氏，虞、夏時有季崱，〔一〕湯時有逢公柏陵，殷末有薄姑氏，皆為諸侯，國此地。至周成王時，薄姑氏與四國共作亂，成王滅之，以封師尚父，是為太公。〔二〕詩風齊國是也。臨甾名營丘，故齊詩曰：「子之營兮，遭我虖嶩之間兮。」〔三〕又曰：「俟我於著乎而。」〔四〕此亦其舒緩之體也。吳札聞齊之歌，曰：「泱泱乎，大風也哉！〔五〕其太公乎？國未可量也。」","sentenceOrder":456},
  {"id":"s_work_han_thu_39_457","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「崱音仕力反。」","sentenceOrder":457},
  {"id":"s_work_han_thu_39_458","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「武王封太公於齊，初未得爽鳩之地，成王以益之也。」","sentenceOrder":458},
  {"id":"s_work_han_thu_39_459","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「齊國風營詩之辭也。毛詩作還，齊詩作營。之，往也。嶩，山名也，字或作峱，亦作巙，音皆乃高反。言往適營丘而相逢於嶩山也。」","sentenceOrder":459},
  {"id":"s_work_han_thu_39_460","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「齊國風著詩之辭也。著，地名，即濟南郡著縣也。乎而，語助也。一曰，門屏之間曰著，音直庶反。」","sentenceOrder":460},
  {"id":"s_work_han_thu_39_461","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「泱泱，弘大之意也，音烏郎反。」","sentenceOrder":461},
  {"id":"s_work_han_thu_39_462","chapterId":"ch_work_han_thu_39","textTraditional":"古有分土，亡分民。〔一〕太公以齊地負海舄鹵，少五穀而人民寡，〔二〕乃勸以女工之業，通魚鹽之利，而人物輻湊。後十四世，桓公用管仲，設輕重以富國，〔三〕合諸侯成伯功，〔四〕身在陪臣而取三歸。〔五〕故其俗彌侈，織作冰紈綺繡純麗之物，〔六〕號為冠帶衣履天下。〔七〕","sentenceOrder":462},
  {"id":"s_work_han_thu_39_463","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「有分土者，謂立封疆也。無分民者，謂通往來不常厥居也。」","sentenceOrder":463},
  {"id":"s_work_han_thu_39_464","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「舄鹵，解在食貨志。」","sentenceOrder":464},
  {"id":"s_work_han_thu_39_465","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「解在食貨志。」","sentenceOrder":465},
  {"id":"s_work_han_thu_39_466","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「伯讀曰霸。」","sentenceOrder":466},
  {"id":"s_work_han_thu_39_467","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「三歸，三姓之女。」","sentenceOrder":467},
  {"id":"s_work_han_thu_39_468","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　如淳曰：「紈，白熟也。純，緣也，謂絛組之屬也。麗，好也。」臣瓚曰：「冰紈，紈細密堅如冰者也。純麗，溫純美麗之物也。」師古曰：「如說非也。冰，謂布帛之細，其色鮮絜如冰者也。紈，素也。綺，文繒也，即今之所謂細綾也。純，精好也。麗，華靡也。紈音丸。純音淳。」","sentenceOrder":468},
  {"id":"s_work_han_thu_39_469","chapterId":"ch_work_han_thu_39","textTraditional":"〔七〕　師古曰：「言天下之人冠帶衣履，皆仰齊地。」","sentenceOrder":469},
  {"id":"s_work_han_thu_39_470","chapterId":"ch_work_han_thu_39","textTraditional":"初太公治齊，修道術，尊賢智，賞有功，故至今其土多好經術，矜功名，舒緩闊達而足智。其失夸奢朋黨，言與行繆，虛詐不情〔一〕，急之則離散，緩之則放縱。始桓公兄襄公淫亂，姑姊妹不嫁，於是令國中民家長女不得嫁，名曰「巫兒」，為家主祠，嫁者不利其家，民至今以為俗。痛乎，道民之道，可不慎哉！〔二〕","sentenceOrder":470},
  {"id":"s_work_han_thu_39_471","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「不可得其情。」","sentenceOrder":471},
  {"id":"s_work_han_thu_39_472","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「上道讀曰導。」","sentenceOrder":472},
  {"id":"s_work_han_thu_39_473","chapterId":"ch_work_han_thu_39","textTraditional":"昔太公始封，周公問「何以治齊？」太公曰：「舉賢而上功。」周公曰：「後世必有篡殺之臣。」其後二十九世為彊臣田和所滅，而和自立為齊侯。初，和之先陳公子完有罪來奔齊，〔一〕齊桓公以為大夫，更稱田氏。九世至和而篡齊，至孫威王稱王，五世為秦所滅。","sentenceOrder":473},
  {"id":"s_work_han_thu_39_474","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「公子完，陳厲公之子也。左氏傳魯莊二十二年『陳人殺其太子禦寇，公子完與顓孫奔齊』，蓋禦寇之黨也。」","sentenceOrder":474},
  {"id":"s_work_han_thu_39_475","chapterId":"ch_work_han_thu_39","textTraditional":"臨甾，海、岱之間一都會也，其中具五民云。〔一〕","sentenceOrder":475},
  {"id":"s_work_han_thu_39_476","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　服虔曰：「士、農、商、工、賈也。」如淳曰：「遊子樂其俗，不復歸，故有五方之民也。」師古曰：「如說是。」","sentenceOrder":476},
  {"id":"s_work_han_thu_39_477","chapterId":"ch_work_han_thu_39","textTraditional":"魯地，奎、婁之分野也。東至東海，南有泗水，至淮，得臨淮之下相、睢陵、僮、取慮，皆魯分也。〔一〕","sentenceOrder":477},
  {"id":"s_work_han_thu_39_478","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「睢音雖。取音趣，又音秋。慮音閭。」","sentenceOrder":478},
  {"id":"s_work_han_thu_39_479","chapterId":"ch_work_han_thu_39","textTraditional":"周興，以少昊之虛曲阜封周公子伯禽為魯侯，〔一〕以為周公主。〔二〕其民有聖人之教化，故孔子曰「齊一變至於魯，魯一變至於道」，言近正也。〔三〕瀕洙泗之水，〔四〕其民涉度，幼者扶老而代其任。〔五〕俗既益薄，長老不自安，與幼少相讓，故曰：「魯道衰，洙泗之間齗齗如也。」〔六〕孔子閔王道將廢，乃修六經，以述唐虞三代之道，弟子受業而通者七十有七人。是以其民好學，上禮義，重廉恥。周公始封，太公問「何以治魯？」周公曰：「尊尊而親親。」太公曰：「後世浸弱矣。」〔七〕故魯自文公以後，祿去公室，政在大夫，季氏逐昭公，陵夷微弱，三十四世而為楚所滅。然本大國，故自為分野。","sentenceOrder":479},
  {"id":"s_work_han_thu_39_480","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「少昊，金天氏之（地）〔帝〕。」","sentenceOrder":480},
  {"id":"s_work_han_thu_39_481","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「主周公之祭祀。」","sentenceOrder":481},
  {"id":"s_work_han_thu_39_482","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「魯庶幾至道，齊人不如魯也。」","sentenceOrder":482},
  {"id":"s_work_han_thu_39_483","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「言所居皆邊於一水也。瀕音頻，又音賓。」","sentenceOrder":483},
  {"id":"s_work_han_thu_39_484","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「任，負戴也。」","sentenceOrder":484},
  {"id":"s_work_han_thu_39_485","chapterId":"ch_work_han_thu_39","textTraditional":"〔六〕　師古曰：「齗齗，分辨之意也，音牛斤反。」","sentenceOrder":485},
  {"id":"s_work_han_thu_39_486","chapterId":"ch_work_han_thu_39","textTraditional":"〔七〕　師古曰：「言漸微弱也。」","sentenceOrder":486},
  {"id":"s_work_han_thu_39_487","chapterId":"ch_work_han_thu_39","textTraditional":"今去聖久遠，周公遺化銷微，孔氏庠序衰壞。地陿民眾，頗有桑麻之業，亡林澤之饒。俗儉嗇愛財，趨商賈，好訾毀，多巧偽，〔一〕喪祭之禮文備實寡，然其好學猶愈於它俗。〔二〕","sentenceOrder":487},
  {"id":"s_work_han_thu_39_488","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「以言相毀曰訾。訾音子爾反。」","sentenceOrder":488},
  {"id":"s_work_han_thu_39_489","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「愈，勝也。」","sentenceOrder":489},
  {"id":"s_work_han_thu_39_490","chapterId":"ch_work_han_thu_39","textTraditional":"漢興以來，魯東海多至卿相。東平、須昌、壽良，皆在濟東，屬魯，非宋地也，當考。〔一〕","sentenceOrder":490},
  {"id":"s_work_han_thu_39_491","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「當考者，言當更考覈之，其事未審。」","sentenceOrder":491},
  {"id":"s_work_han_thu_39_492","chapterId":"ch_work_han_thu_39","textTraditional":"宋地，房、心之分野也。今之沛、梁、楚、山陽、濟陰、東平及東郡之須昌、壽張，皆宋分也。","sentenceOrder":492},
  {"id":"s_work_han_thu_39_493","chapterId":"ch_work_han_thu_39","textTraditional":"周封微子於宋，今之睢陽是也，本陶唐氏火正閼伯之虛也。濟陰定陶，詩風曹國也。武王封弟叔振鐸於曹，其後稍大，得山陽、陳留，二十餘世為宋所滅。","sentenceOrder":493},
  {"id":"s_work_han_thu_39_494","chapterId":"ch_work_han_thu_39","textTraditional":"昔堯作游成陽，〔一〕舜漁靁澤，〔二〕湯止于亳，故其民猶有先王遺風，重厚多君子，好稼穡，惡衣食，以致畜藏。〔三〕","sentenceOrder":494},
  {"id":"s_work_han_thu_39_495","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　如淳曰：「作，起也。成陽在定陶，今有堯冢靈臺。」師古曰：「作游者，言為宮室遊止之處也。」","sentenceOrder":495},
  {"id":"s_work_han_thu_39_496","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「漁，捕魚也。靁，古雷字。」","sentenceOrder":496},
  {"id":"s_work_han_thu_39_497","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「畜讀曰蓄。」","sentenceOrder":497},
  {"id":"s_work_han_thu_39_498","chapterId":"ch_work_han_thu_39","textTraditional":"宋自微子二十餘世，至景公滅曹，滅曹後五世亦為齊、楚、魏所滅，參分其地。魏得其梁、陳留，齊得其濟陰、東平，楚得其沛。故今之楚彭城，本宋也，春秋經曰「圍宋彭城」。宋雖滅，本大國，故自為分野。","sentenceOrder":498},
  {"id":"s_work_han_thu_39_499","chapterId":"ch_work_han_thu_39","textTraditional":"沛楚之失，急疾顓己，地薄民貧，〔一〕而山陽好為姦盜。","sentenceOrder":499},
  {"id":"s_work_han_thu_39_500","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「顓與專同。急疾顓己，言性褊狹而自用。」","sentenceOrder":500},
  {"id":"s_work_han_thu_39_501","chapterId":"ch_work_han_thu_39","textTraditional":"衛地，營室、東壁之分野也。今之東郡及魏郡黎陽，河內之野王、朝歌，皆衛分也。","sentenceOrder":501},
  {"id":"s_work_han_thu_39_502","chapterId":"ch_work_han_thu_39","textTraditional":"衛本國既為狄所滅，〔一〕文公徙封楚丘，三十餘年，子成公徙於帝丘。故春秋經曰「衛〈興，中“八改仓”〉于帝丘」，〔二〕今之濮陽是也。本顓頊之虛，故謂之帝丘。夏后之世，昆吾氏居之。成公後十餘世，為韓、魏所侵，盡亡其旁邑，獨有濮陽。後秦滅濮陽，置東郡，徙之於野王。始皇既并天下，猶獨置衛君，二世時乃廢為庶人。凡四十世，九百年，最後絕，故獨為分野。","sentenceOrder":502},
  {"id":"s_work_han_thu_39_503","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「衛懿公為狄人所滅，事在春秋閔公二年。」","sentenceOrder":503},
  {"id":"s_work_han_thu_39_504","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「〈興，中“八改仓”〉，古遷字。」","sentenceOrder":504},
  {"id":"s_work_han_thu_39_505","chapterId":"ch_work_han_thu_39","textTraditional":"衛地有桑間濮上之阻，〔一〕男女亦亟聚會，聲色生焉，〔二〕故俗稱鄭衛之音。周末有子路、夏育，民人慕之，〔三〕故其俗剛武，上氣力。漢興，二千石治者亦以殺戮為威。宣帝時韓延壽為東郡太守，承聖恩，崇禮義，尊諫爭，至今東郡號善為吏，延壽之化也。其失頗奢靡，嫁取送死過度，而野王好氣任俠，有濮上風。","sentenceOrder":505},
  {"id":"s_work_han_thu_39_506","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「阻者，言其隱阨得肆淫僻之情也。」","sentenceOrder":506},
  {"id":"s_work_han_thu_39_507","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「亟，屢也，音丘吏反。」","sentenceOrder":507},
  {"id":"s_work_han_thu_39_508","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「子路，孔子弟子仲由也，性好勇。夏育亦古之壯士。皆衛人。」","sentenceOrder":508},
  {"id":"s_work_han_thu_39_509","chapterId":"ch_work_han_thu_39","textTraditional":"楚地，翼、軫之分野也。今之南郡、江夏、零陵、桂陽、武陵、長沙及漢中、汝南郡，盡楚分也。","sentenceOrder":509},
  {"id":"s_work_han_thu_39_510","chapterId":"ch_work_han_thu_39","textTraditional":"周成王時，封文、武先師鬻熊之曾孫熊繹於荊蠻，為楚子，居丹陽。後十餘世至熊達，是為武王，{穴浸}以彊大。〔一〕後五世至嚴王，總帥諸侯，觀兵周室，并吞江、漢之間，內滅陳、魯之國。後十餘世，頃襄王東徙于陳。","sentenceOrder":510},
  {"id":"s_work_han_thu_39_511","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「{穴浸}，漸也。」","sentenceOrder":511},
  {"id":"s_work_han_thu_39_512","chapterId":"ch_work_han_thu_39","textTraditional":"楚有江漢川澤山林之饒；江南地廣，或火耕水耨。民食魚稻，以漁獵山伐為業，〔一〕果蓏蠃蛤，食物常足。〔二〕故啙窳媮生，而亡積聚，〔三〕飲食還給，不憂凍餓，〔四〕亦亡千金之家。信巫鬼，重淫祀。而漢中淫失枝柱，與巴蜀同俗。〔五〕汝南之別，皆急疾有氣勢。江陵，故郢都，西通巫、巴，東有雲夢之饒，亦一都會也。","sentenceOrder":512},
  {"id":"s_work_han_thu_39_513","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「山伐，謂伐山取竹木。」","sentenceOrder":513},
  {"id":"s_work_han_thu_39_514","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「蠃音來戈反。蛤音閤，似蜯而圜。」","sentenceOrder":514},
  {"id":"s_work_han_thu_39_515","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　應劭曰：「啙，弱也。言風俗朝夕取給媮生而已，無長久之慮也。」如淳曰：「啙或作鮆，音紫。窳音庾。」晉灼曰：「啙，病也。窳，惰也。」師古曰：「諸家之說皆非也。啙，短也。窳，弱也。言短力弱材不能勤作，故朝夕取給而無儲偫也。如音是也。」","sentenceOrder":515},
  {"id":"s_work_han_thu_39_516","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「還，及也，言常相及而給足也。」","sentenceOrder":516},
  {"id":"s_work_han_thu_39_517","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「失讀曰泆。柱音竹甫反。枝柱，言意相節卻，不順從也。」","sentenceOrder":517},
  {"id":"s_work_han_thu_39_518","chapterId":"ch_work_han_thu_39","textTraditional":"吳地，斗分野也。今之會稽、九江、丹陽、豫章、廬江、廣陵、六安、臨淮郡，盡吳分也。","sentenceOrder":518},
  {"id":"s_work_han_thu_39_519","chapterId":"ch_work_han_thu_39","textTraditional":"殷道既衰，周大王亶父興廄梁之地，長子大伯，次曰仲雍，少曰公季。公季有聖子昌，大王欲傳國焉。大伯、仲雍辭行采藥，遂奔荊蠻。公季嗣位，至昌為西伯，受命而王。故孔子美而稱曰：「大伯，可謂至德也已矣！三以天下讓，民無得而稱焉。」謂「虞仲夷逸，隱居放言，身中清，廢中權。」〔一〕大伯初奔荊蠻，荊蠻歸之，號曰句吳。〔二〕大伯卒，仲雍立，至曾孫周章，而武王克殷，因而封之。又封周章弟中於河北，是為北吳，〔三〕後世謂之虞，十二世為晉所滅。後二世而荊蠻之吳子壽夢盛大稱王。其少子則季札，有賢材。兄弟欲傳國，札讓而不受。自（大伯）壽夢稱王六世，闔廬舉伍子胥、孫武為將，戰勝攻取，興伯名於諸侯。〔四〕至子夫差，誅子胥，用宰嚭，〔五〕為粵王句踐所滅。","sentenceOrder":519},
  {"id":"s_work_han_thu_39_520","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「皆論語載孔子之言也。虞仲，即仲雍也。夷逸，言竄於蠻夷而遁逸也。隱居而不言，故其身清潔，所廢中於權道。」","sentenceOrder":520},
  {"id":"s_work_han_thu_39_521","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「句音鉤，夷俗語之發聲也，亦猶越為于越也。」","sentenceOrder":521},
  {"id":"s_work_han_thu_39_522","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「中讀曰仲。」","sentenceOrder":522},
  {"id":"s_work_han_thu_39_523","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「伯讀曰霸。」","sentenceOrder":523},
  {"id":"s_work_han_thu_39_524","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「嚭音披美反。」","sentenceOrder":524},
  {"id":"s_work_han_thu_39_525","chapterId":"ch_work_han_thu_39","textTraditional":"吳、粵之君皆好勇，故其民至今好用劍，輕死易發。","sentenceOrder":525},
  {"id":"s_work_han_thu_39_526","chapterId":"ch_work_han_thu_39","textTraditional":"粵既并吳，後六世為楚所滅。後秦又擊楚，徙壽春，至子為秦所滅。","sentenceOrder":526},
  {"id":"s_work_han_thu_39_527","chapterId":"ch_work_han_thu_39","textTraditional":"壽春、合肥受南北湖皮革、鮑、木之輸，〔一〕亦一都會也。始楚賢臣屈原被讒放流，作離騷諸賦以自傷悼。〔二〕後有宋玉、唐勒之屬慕而述之，皆以顯名。漢興，高祖王兄子濞於吳，招致天下之娛游子弟，枚乘、鄒陽、嚴夫子之徒興於文、景之際。而淮南王安亦都壽春，招賓客著書。而吳有嚴助、朱賈臣，貴顯漢朝，文辭並發，故世傳楚辭。其失巧而少信。初淮南王異國中民家有女者，〔三〕以待游士而妻之，故至今多女而少男。〔四〕本吳粵與楚接比，數相并兼，〔五〕故民俗略同。","sentenceOrder":527},
  {"id":"s_work_han_thu_39_528","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「皮革，犀兕之屬也。鮑，鮑魚也。木，楓柟豫章之屬。」","sentenceOrder":528},
  {"id":"s_work_han_thu_39_529","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「諸賦，謂九歌、天問、九章之屬。」","sentenceOrder":529},
  {"id":"s_work_han_thu_39_530","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　晉灼曰：「有女者見優異。」","sentenceOrder":530},
  {"id":"s_work_han_thu_39_531","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　如淳曰：「得女寵，或去男也。」臣瓚曰：「周官職方云『揚州之民，二男而五女』，此風氣非由淮南王安能使多女也。」師古曰：「二說皆非也。志亦言土地風氣既足女矣，因淮南之化，又更聚焉。」","sentenceOrder":531},
  {"id":"s_work_han_thu_39_532","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「比，近也，音頻寐反。」","sentenceOrder":532},
  {"id":"s_work_han_thu_39_533","chapterId":"ch_work_han_thu_39","textTraditional":"吳東有海鹽章山之銅，三江五湖之利，亦江東之一都會也。豫章出黃金，然菫菫物之所有，取之不足以更費。〔一〕江南卑溼，丈夫多夭。","sentenceOrder":533},
  {"id":"s_work_han_thu_39_534","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　應劭曰：「菫菫，少也。更，（賞）〔償〕也。言金少耳，取不足用，顧費用也。」師古曰：「應說非也。此言所出之金既以少矣，自外諸物蓋亦不多，故總言取之不足償功直也。菫讀曰僅。更音庚。」","sentenceOrder":534},
  {"id":"s_work_han_thu_39_535","chapterId":"ch_work_han_thu_39","textTraditional":"會稽海外有東鯷人，〔一〕分為二十餘國，以歲時來獻見云。","sentenceOrder":535},
  {"id":"s_work_han_thu_39_536","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　孟康曰：「音題。」晉灼曰：「音鞮。」師古曰：「孟音是也。」","sentenceOrder":536},
  {"id":"s_work_han_thu_39_537","chapterId":"ch_work_han_thu_39","textTraditional":"粵地，牽牛、婺女之分野也。今之蒼梧、鬱林、合浦、交阯、九真、南海、日南，皆粵分也。","sentenceOrder":537},
  {"id":"s_work_han_thu_39_538","chapterId":"ch_work_han_thu_39","textTraditional":"其君禹後，帝少康之庶子云，封於會稽，〔一〕文身斷髮，以避蛟龍之害。〔二〕後二十世，至句踐稱王，與吳王闔廬戰，敗之雋李。〔三〕夫差立，句踐乘勝復伐吳，吳大破之，棲會稽，〔四〕臣服請平。後用范蠡、大夫種計，遂伐滅吳，兼并其地。度淮與齊、晉諸侯會，致貢於周。周元王使使賜命為伯，諸侯畢賀。後五世為楚所滅，子孫分散，君服於楚。〔五〕後十世，至閩君搖，佐諸侯平秦。漢興，復立搖為越王。是時，秦南海尉趙佗亦自王，傳國至武帝時，盡滅以為郡云。","sentenceOrder":538},
  {"id":"s_work_han_thu_39_539","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　臣瓚曰：「自交阯至會稽七八千里，百越雜處，各有種姓，不得盡云少康之後也。按世本，越為羋姓，與楚同祖，故國語曰『羋姓夔、越』，然則越非禹後明矣。又羋姓之越，亦句踐之後，不謂南越也。」師古曰：「越之為號，其來尚矣，少康封庶子以主禹祠，君於越地耳。故此志云其君禹後，豈謂百越之人皆禹苗裔？瓚說非也。」","sentenceOrder":539},
  {"id":"s_work_han_thu_39_540","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　應劭曰：「常在水中，故斷其髮，文其身，以象龍子，故不見傷害也。」","sentenceOrder":540},
  {"id":"s_work_han_thu_39_541","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「雋音醉，字本作檇，其旁從木。」","sentenceOrder":541},
  {"id":"s_work_han_thu_39_542","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「會稽，山名。登山而處，以避兵難，言若鳥之棲。」","sentenceOrder":542},
  {"id":"s_work_han_thu_39_543","chapterId":"ch_work_han_thu_39","textTraditional":"〔五〕　師古曰：「事楚為君而服從之。」","sentenceOrder":543},
  {"id":"s_work_han_thu_39_544","chapterId":"ch_work_han_thu_39","textTraditional":"處近海，多犀、象、毒冒、珠璣、銀、銅、果、布之湊，〔一〕中國往商賈者多取富焉。番禺，其一都會也。","sentenceOrder":544},
  {"id":"s_work_han_thu_39_545","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　韋昭曰：「果謂龍眼、離支之屬。布，葛布也。」師古曰：「毒音代。冒音莫內反。璣謂珠之不圜者也，音祈，又音機。布謂諸雜細布皆是也。」","sentenceOrder":545},
  {"id":"s_work_han_thu_39_546","chapterId":"ch_work_han_thu_39","textTraditional":"自合浦徐聞南入海，得大州，東西南北方千里，武帝元封元年略以為儋耳、珠崖郡。民皆服布如單被，穿中央為貫頭。〔一〕男子耕農，種禾稻紵麻，女子桑蠶織績。亡馬與虎，民有五畜，〔二〕山多麈嗷。〔三〕兵則矛、盾、刀，木弓弩，竹矢，或骨為鏃。〔四〕自初為郡縣，吏卒中國人多侵陵之，故率數歲壹反。元帝時，遂罷棄之。","sentenceOrder":546},
  {"id":"s_work_han_thu_39_547","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「著時從頭而貫之。」","sentenceOrder":547},
  {"id":"s_work_han_thu_39_548","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「牛、羊、豕、雞、犬。」","sentenceOrder":548},
  {"id":"s_work_han_thu_39_549","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「麈似鹿而大，嗷似鹿而小。麈音主，嗷音京。」","sentenceOrder":549},
  {"id":"s_work_han_thu_39_550","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「鏃，矢鋒，音子木反。」","sentenceOrder":550},
  {"id":"s_work_han_thu_39_551","chapterId":"ch_work_han_thu_39","textTraditional":"自日南障塞、徐聞、合浦船行可五月，有都元國；又船行可四月，有邑盧沒國；又船行可二十餘日，有諶離國；〔一〕步行可十餘日，有夫甘都盧國。〔二〕自夫甘都盧國船行可二月餘，有黃支國，民俗略與珠厓相類。其州廣大，戶口多，多異物，自武帝以來皆獻見。有譯長，屬黃門，與應募者俱入海巿明珠、璧流離、奇石異物，齎黃金雜繒而往。所至國皆稟食為耦，〔三〕蠻夷賈船，轉送致之。亦利交易，剽殺人。〔四〕又苦逢風波溺死，不者數年來還。大珠至圍二寸以下。平帝元始中，王莽輔政，欲燿威德，厚遺黃支王，令遣使獻生犀牛。自黃支船行可八月，到皮宗；船行可（八）〔二〕月，到日南、象林界云。黃支之南，有已程不國，漢之譯使自此還矣。","sentenceOrder":551},
  {"id":"s_work_han_thu_39_552","chapterId":"ch_work_han_thu_39","textTraditional":"〔一〕　師古曰：「諶音士林反。」","sentenceOrder":552},
  {"id":"s_work_han_thu_39_553","chapterId":"ch_work_han_thu_39","textTraditional":"〔二〕　師古曰：「都盧國人勁捷善緣高，故張衡西京賦云『烏獲扛鼎，都盧尋橦』，又曰『非都盧之輕趫，孰能超而究升』也。夫音扶。」","sentenceOrder":553},
  {"id":"s_work_han_thu_39_554","chapterId":"ch_work_han_thu_39","textTraditional":"〔三〕　師古曰：「稟，給也。耦，嫓也。給其食而侶嫓之，相隨行也。」","sentenceOrder":554},
  {"id":"s_work_han_thu_39_555","chapterId":"ch_work_han_thu_39","textTraditional":"〔四〕　師古曰：「剽，劫也，音頻妙反。」","sentenceOrder":555},
  {"id":"s_work_han_thu_39_556","chapterId":"ch_work_han_thu_39","textTraditional":"校勘記","sentenceOrder":556},
  {"id":"s_work_han_thu_39_557","chapterId":"ch_work_han_thu_39","textTraditional":"一六一０頁　五行　北至抱罕東入（西）〔河〕。　景祐、殿、局本都作「河」。王鳴盛說作「河」是。","sentenceOrder":557},
  {"id":"s_work_han_thu_39_558","chapterId":"ch_work_han_thu_39","textTraditional":"一六一一頁一五行　西有（畢）〔卑〕和羌，　景祐、殿本都作「卑」。王先謙說作「卑」是。","sentenceOrder":558},
  {"id":"s_work_han_thu_39_559","chapterId":"ch_work_han_thu_39","textTraditional":"一六一二頁一五行　鸞（鳥）〔烏〕，　景祐、殿本都作「烏」。段玉裁說作「烏」是。","sentenceOrder":559},
  {"id":"s_work_han_thu_39_560","chapterId":"ch_work_han_thu_39","textTraditional":"一六一三頁　七行　（曰）〔日〕勒，　殿本考證說，按匈奴傳當作「日勒」。","sentenceOrder":560},
  {"id":"s_work_han_thu_39_561","chapterId":"ch_work_han_thu_39","textTraditional":"一六一四頁　三行　治偃（前）〔泉〕障。　景祐本作「泉」，殿本作「水」。","sentenceOrder":561},
  {"id":"s_work_han_thu_39_562","chapterId":"ch_work_han_thu_39","textTraditional":"一六一五頁一一行　月（支）〔氏〕道。　景祐、殿、局本都作「氏」。","sentenceOrder":562},
  {"id":"s_work_han_thu_39_563","chapterId":"ch_work_han_thu_39","textTraditional":"一六一六頁　四行　祖音（置）〔罝〕。　景祐、殿本都作「罝」。","sentenceOrder":563},
  {"id":"s_work_han_thu_39_564","chapterId":"ch_work_han_thu_39","textTraditional":"一六一六頁　八行　沮水出（東，西）〔西，東〕入洛。　王念孫、陳澧、王先謙都說「西」「東」誤倒。","sentenceOrder":564},
  {"id":"s_work_han_thu_39_565","chapterId":"ch_work_han_thu_39","textTraditional":"一六一八頁一一行　莽曰（堅）〔監〕水。　景祐、殿本都作「監」。王先謙說作「監」是。","sentenceOrder":565},
  {"id":"s_work_han_thu_39_566","chapterId":"ch_work_han_thu_39","textTraditional":"一六二二頁　七行　虖池河東至參（合）〔戶〕入虖池別，　齊召南說「參合」當是「參戶」之誤。王念孫說齊說是。","sentenceOrder":566},
  {"id":"s_work_han_thu_39_567","chapterId":"ch_work_han_thu_39","textTraditional":"一六二三頁　八行　（樂陽）〔陽樂〕水出東，（東）〔南〕入（海）〔沽〕。　王念孫說「樂陽」當為「陽樂」，「入海」當為「入沽」。王鳴盛說南監本下「東」作「南」，是。按殿本亦作「南」。","sentenceOrder":567},
  {"id":"s_work_han_thu_39_568","chapterId":"ch_work_han_thu_39","textTraditional":"一六二三頁一四行　莽曰（北順）〔通路〕。　景祐、殿本都作「通路」。王先謙說此涉下右北平而誤。","sentenceOrder":568},
  {"id":"s_work_han_thu_39_569","chapterId":"ch_work_han_thu_39","textTraditional":"一六二六頁　四行　莽曰（受）〔文〕亭。　景祐、殿本都作「文」。王先謙說作「文」是。","sentenceOrder":569},
  {"id":"s_work_han_thu_39_570","chapterId":"ch_work_han_thu_39","textTraditional":"一六二六頁　七行　說讀曰（侻）〔悅〕。　景祐、殿本都作「悅」。","sentenceOrder":570},
  {"id":"s_work_han_thu_39_571","chapterId":"ch_work_han_thu_39","textTraditional":"一六二七頁　九行　東（郡）〔部〕都尉治。　朱一新說汪本「郡」作「部」，是。按景祐、殿本都作「部」。","sentenceOrder":571},
  {"id":"s_work_han_thu_39_572","chapterId":"ch_work_han_thu_39","textTraditional":"一六二八頁一三行　又有斤（員）〔南〕水。　景祐本作「南」，溫水注同。","sentenceOrder":572},
  {"id":"s_work_han_thu_39_573","chapterId":"ch_work_han_thu_39","textTraditional":"一六二八頁一三行　〔周〕水首受無斂，　王先謙說「水」上奪「周」字。","sentenceOrder":573},
  {"id":"s_work_han_thu_39_574","chapterId":"ch_work_han_thu_39","textTraditional":"一六二九頁　九行　三〔十〕七。　「十」字據景祐、殿本補。","sentenceOrder":574},
  {"id":"s_work_han_thu_39_575","chapterId":"ch_work_han_thu_39","textTraditional":"一六三八頁　八行　（入淮南）〔南入淮〕。　王鳴盛說南監本作「南入淮」，是。按景祐、殿本都同南監本。","sentenceOrder":575},
  {"id":"s_work_han_thu_39_576","chapterId":"ch_work_han_thu_39","textTraditional":"一六三九頁　五行　（收）〔攸〕。　景祐、殿本「收」作「攸」。","sentenceOrder":576},
  {"id":"s_work_han_thu_39_577","chapterId":"ch_work_han_thu_39","textTraditional":"一六三九頁一五行　以其郡（大）〔太〕大，　上「大」字殿本作「太」。","sentenceOrder":577},
  {"id":"s_work_han_thu_39_578","chapterId":"ch_work_han_thu_39","textTraditional":"一六四０頁一０行　漢承百（年）〔王〕之末，　朱一新說汪本「年」作「王」，是。按景祐、殿本都作「王」。","sentenceOrder":578},
  {"id":"s_work_han_thu_39_579","chapterId":"ch_work_han_thu_39","textTraditional":"一六四０頁一一行　成帝時劉向略言其（域）〔地〕分，　景祐、殿本都作「地」。","sentenceOrder":579},
  {"id":"s_work_han_thu_39_580","chapterId":"ch_work_han_thu_39","textTraditional":"一六四二頁　一行　造音（於）〔千〕到反。　景祐、殿、局本都作「千」。","sentenceOrder":580},
  {"id":"s_work_han_thu_39_581","chapterId":"ch_work_han_thu_39","textTraditional":"一六四三頁一四行　厝，古錯（反）〔字〕。　景祐、殿本都作「字」。朱一新說作「字」是。","sentenceOrder":581},
  {"id":"s_work_han_thu_39_582","chapterId":"ch_work_han_thu_39","textTraditional":"一六四五頁　二行　（古）〔故〕涼州之畜為天下饒。　景祐、殿本都作「故」。朱一新說作「故」是。","sentenceOrder":582},
  {"id":"s_work_han_thu_39_583","chapterId":"ch_work_han_thu_39","textTraditional":"一六四六頁一０行　（秦豳）吳札觀樂，為之歌秦，　王念孫說「秦豳」二字衍。","sentenceOrder":583},
  {"id":"s_work_han_thu_39_584","chapterId":"ch_work_han_thu_39","textTraditional":"一六五一頁　三行　（三）〔二〕都得百里者〔百〕，方千里也。　朱一新說「三都」當作「二都」，謂宗周及雒邑也。「者」下當有「百」字。按景祐、殿本都作「二都」，「者」下都有「百」字。","sentenceOrder":584},
  {"id":"s_work_han_thu_39_585","chapterId":"ch_work_han_thu_39","textTraditional":"一六五二頁　七行　（威）〔桓〕公死，　景祐、殿本都作「桓」。","sentenceOrder":585},
  {"id":"s_work_han_thu_39_586","chapterId":"ch_work_han_thu_39","textTraditional":"一六五二頁　七行　右雒左（沛）〔泲〕，　朱一新說「沛」當作「泲」。按景祐、殿本都作「泲」。","sentenceOrder":586},
  {"id":"s_work_han_thu_39_587","chapterId":"ch_work_han_thu_39","textTraditional":"一六五四頁　九行　高（士）〔仕〕宦，　景祐、殿本都作「仕」。錢大昭說作「仕」是。","sentenceOrder":587},
  {"id":"s_work_han_thu_39_588","chapterId":"ch_work_han_thu_39","textTraditional":"一六五八頁　八行　有以也夫！（九）　注〔九〕原在「也」字下。劉攽說「夫」字宜屬上句。","sentenceOrder":588},
  {"id":"s_work_han_thu_39_589","chapterId":"ch_work_han_thu_39","textTraditional":"一六六二頁一一行　金天氏之（地）〔帝〕。　景祐、殿本都作「帝」。","sentenceOrder":589},
  {"id":"s_work_han_thu_39_590","chapterId":"ch_work_han_thu_39","textTraditional":"一六六七頁　七行　自（大伯）壽夢稱王六世，　陳奐說「大伯」二字疑衍。","sentenceOrder":590},
  {"id":"s_work_han_thu_39_591","chapterId":"ch_work_han_thu_39","textTraditional":"一六六九頁　一行　更，（賞）〔償〕也。　景祐、殿、局本都作「償」。","sentenceOrder":591},
  {"id":"s_work_han_thu_39_592","chapterId":"ch_work_han_thu_39","textTraditional":"一六七一頁　八行　船行可（八）〔二〕月，　景祐、殿本都作「二」。","sentenceOrder":592},
  {"id":"s_work_han_thu_40_1","chapterId":"ch_work_han_thu_40","textTraditional":"應劭曰：「溝廣四尺，深四尺；洫廣深倍於溝。」師古曰：「洫音許域反。」","sentenceOrder":1},
  {"id":"s_work_han_thu_40_2","chapterId":"ch_work_han_thu_40","textTraditional":"夏書：禹堙洪水十三年，〔一〕過家不入門。陸行載車，水行乘舟，泥行乘毳，〔二〕山行則梮，〔三〕以別九州；〔四〕隨山浚川，〔五〕任土作貢；〔六〕通九道，陂九澤，度九山。〔七〕然河災之羨溢，害中國也尤甚。〔八〕唯是為務，故道河自積石，〔九〕歷龍門，南到華陰，東下底柱，〔一０〕及盟津、雒內，至于大伾〔一一〕。於是禹以為河所從來者高，水湍悍，難以行平地，〔一二〕數為敗，乃釃二渠以引其河，〔一三〕北載之高地，過洚水，至於大陸，播為九河，〔一四〕同為迎河，入于勃海。〔一五〕九川既疏，九澤既陂，諸夏乂安，〔一六〕功施乎三代。","sentenceOrder":2},
  {"id":"s_work_han_thu_40_3","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　如淳曰：「堙，沒也。」師古曰：「堙，塞也。洪水氾溢，疏通而止塞之。堙音因。」","sentenceOrder":3},
  {"id":"s_work_han_thu_40_4","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　孟康曰：「毳形如箕，擿行泥上。」如淳曰：「毳音茅蕝之蕝。謂以板置泥上以通行路也。」師古曰：「孟說是也。毳讀如本字。」","sentenceOrder":4},
  {"id":"s_work_han_thu_40_5","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　如淳曰：「梮謂以鐵如錐頭，長半寸，施之履下，以上山，不蹉跌也。」韋昭曰：「梮，木器，如今輿床，人舉以行也。」師古曰：「如說是也。梮音居足反。」","sentenceOrder":5},
  {"id":"s_work_han_thu_40_6","chapterId":"ch_work_han_thu_40","textTraditional":"〔四〕　師古曰：「分其界。」","sentenceOrder":6},
  {"id":"s_work_han_thu_40_7","chapterId":"ch_work_han_thu_40","textTraditional":"〔五〕　師古曰：「順山之高下而深其流。」","sentenceOrder":7},
  {"id":"s_work_han_thu_40_8","chapterId":"ch_work_han_thu_40","textTraditional":"〔六〕　師古曰：「任其土地所有以定貢賦之差也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_40_9","chapterId":"ch_work_han_thu_40","textTraditional":"〔七〕　師古曰：「言通九州之道，及鄣遏其澤，商度其山也。度音大各反。」","sentenceOrder":9},
  {"id":"s_work_han_thu_40_10","chapterId":"ch_work_han_thu_40","textTraditional":"〔八〕　師古曰：「羨讀與衍同，音弋展反。」","sentenceOrder":10},
  {"id":"s_work_han_thu_40_11","chapterId":"ch_work_han_thu_40","textTraditional":"〔九〕　師古曰：「道，治也，引也。從積石山而治引之令通流也。道讀曰導。」","sentenceOrder":11},
  {"id":"s_work_han_thu_40_12","chapterId":"ch_work_han_thu_40","textTraditional":"〔一０〕師古曰：「厎音之履反。」","sentenceOrder":12},
  {"id":"s_work_han_thu_40_13","chapterId":"ch_work_han_thu_40","textTraditional":"〔一一〕鄭氏曰：「山一成為伾，在修武、武德界。」張晏曰：「成皋縣山是也。臣瓚以為今修武、武德無此山也。成皋縣山又不一成也。今黎陽山臨河，豈是乎？」師古曰：「內讀曰汭。伾音皮彼反。解在地理志。」","sentenceOrder":13},
  {"id":"s_work_han_thu_40_14","chapterId":"ch_work_han_thu_40","textTraditional":"〔一二〕師古曰：「急流曰湍。悍，勇也。湍音它端反。」","sentenceOrder":14},
  {"id":"s_work_han_thu_40_15","chapterId":"ch_work_han_thu_40","textTraditional":"〔一三〕孟康曰：「釃，分也。分其流，泄其怒也。二渠，其一出貝丘西南南折者也，其一則漯川也。河自王莽時遂空，唯用漯耳。」師古曰：「釃音山支反。漯音它合反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_40_16","chapterId":"ch_work_han_thu_40","textTraditional":"〔一四〕師古曰：「播，布也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_40_17","chapterId":"ch_work_han_thu_40","textTraditional":"〔一五〕臣瓚以為「禹貢『夾右碣石入于河』，則河入海乃在碣石也。武帝元光二年，河移徙東郡，更注勃海。禹時不注也。」師古曰：「解在地理志。」","sentenceOrder":17},
  {"id":"s_work_han_thu_40_18","chapterId":"ch_work_han_thu_40","textTraditional":"〔一六〕師古曰：「疏，分流。」","sentenceOrder":18},
  {"id":"s_work_han_thu_40_19","chapterId":"ch_work_han_thu_40","textTraditional":"自是之後，滎陽下引河東南為鴻溝，以通宋、鄭、陳、蔡、曹、衛，與濟、汝、淮、泗會。於楚，西方則通渠漢川、雲夢之際，東方則通溝江淮之間。於吳，則通渠三江、五湖。於齊，則通淄濟之間。於蜀，則蜀守李冰鑿離{山隼}，〔一〕避沫水之害，〔二〕穿二江成都中。此渠皆可行舟，有餘則用溉，〔三〕百姓饗其利。至於它，往往引其水，用溉田，溝渠甚多，然莫足數也。","sentenceOrder":19},
  {"id":"s_work_han_thu_40_20","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　晉灼曰：「{山隼}，古堆字也。{山隼}，岸也。」師古曰：「音丁回反。」","sentenceOrder":20},
  {"id":"s_work_han_thu_40_21","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「沫音本末之末。水出蜀西南徼外，東南入江。」","sentenceOrder":21},
  {"id":"s_work_han_thu_40_22","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　師古曰：「溉，灌也，音工代反。」","sentenceOrder":22},
  {"id":"s_work_han_thu_40_23","chapterId":"ch_work_han_thu_40","textTraditional":"魏文侯時，西門豹為鄴令，有令名。〔一〕至文侯曾孫襄王時，與群臣飲酒，王為群臣祝曰：「今吾臣皆〔如〕西門豹之為人臣也！」史起進曰：「魏氏之行田也以百畝，〔二〕鄴獨二百畝，是田惡也。漳水在其旁，西門豹不知用，是不智也。知而不興，是不仁也。仁智豹未之盡，何足法也！」於是以史起為鄴令，遂引漳水溉鄴，以富魏之河內。民歌之曰：「鄴有賢令兮為史公，決漳水兮灌鄴旁，終古舄鹵兮生稻梁。」〔三〕","sentenceOrder":23},
  {"id":"s_work_han_thu_40_24","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「有善政之稱。」","sentenceOrder":24},
  {"id":"s_work_han_thu_40_25","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「賦田之法，一夫百畝也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_40_26","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　蘇林曰：「終古，猶言久古也。爾雅曰『鹵，鹹苦也』。」師古曰：「舄即斥鹵也。謂鹹鹵之地也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_40_27","chapterId":"ch_work_han_thu_40","textTraditional":"其後韓聞秦之好興事，欲罷之，無令東伐。〔一〕乃使水工鄭國間說秦，〔二〕令鑿涇水，自中山西邸瓠口為渠，〔三〕並北山，東注洛，三百餘里，〔四〕欲以溉田。中作而覺，〔五〕秦欲殺鄭國。鄭國曰：「始臣為間，然渠成亦秦之利也。臣為韓延數歲之命，而為秦建萬世之功。」秦以為然，卒使就渠。渠成而用（溉）注填閼之水，溉舄鹵之地四萬餘頃，收皆畝一鍾。〔六〕於是關中為沃野，無凶年，秦以富彊，卒并諸侯，因名曰鄭國渠。","sentenceOrder":27},
  {"id":"s_work_han_thu_40_28","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　如淳曰：「息秦滅韓之計也。」師古曰：「罷讀曰疲，令其疲勞不能出兵。」","sentenceOrder":28},
  {"id":"s_work_han_thu_40_29","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「間音居莧反。其下亦同。」","sentenceOrder":29},
  {"id":"s_work_han_thu_40_30","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　師古曰：「中讀曰仲，即今九嵕之東仲山也。邸，至也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_40_31","chapterId":"ch_work_han_thu_40","textTraditional":"〔四〕　師古曰：「並音步浪反。洛水，即馮翊漆沮水。」","sentenceOrder":31},
  {"id":"s_work_han_thu_40_32","chapterId":"ch_work_han_thu_40","textTraditional":"〔五〕　師古曰：「中作，謂用功中道，事未竟也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_40_33","chapterId":"ch_work_han_thu_40","textTraditional":"〔六〕　師古曰：「注，引也。閼讀與淤同，音於據反。填閼謂壅泥也。言引淤濁之水灌鹹鹵之田，更令肥美，故一畝之收至六斛四斗。」","sentenceOrder":33},
  {"id":"s_work_han_thu_40_34","chapterId":"ch_work_han_thu_40","textTraditional":"漢興三十有九年，孝文時河決酸棗，東潰金隄，〔一〕於是東郡大興卒塞之。","sentenceOrder":34},
  {"id":"s_work_han_thu_40_35","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「潰，潢決也。金隄，河隄名也，在東郡白馬界。隄音丁奚反。」","sentenceOrder":35},
  {"id":"s_work_han_thu_40_36","chapterId":"ch_work_han_thu_40","textTraditional":"其後三十六歲，孝武元光中，河決於瓠子，東南注鉅野，〔一〕通於淮、泗。上使汲黯、鄭當時興人徒塞之，輒復壞。是時武安侯田蚡為丞相，其奉邑食鄃。鄃居河北，〔二〕河決而南則鄃無水災，邑收入多。蚡言於上曰：「江河之決皆天事，未易以人力彊塞，彊塞之未必（順）〔應〕天。」而望氣用數者亦以為然，是以久不復塞也。","sentenceOrder":36},
  {"id":"s_work_han_thu_40_37","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「鉅野，澤名，舊屬兗州界，即今之鄆州鉅野縣。」","sentenceOrder":37},
  {"id":"s_work_han_thu_40_38","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「奉音扶用反。鄃音輸，清河之縣也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_40_39","chapterId":"ch_work_han_thu_40","textTraditional":"時鄭當時為大司農，言「異時關東漕粟從渭上，〔一〕度六月罷，〔二〕而渭水道九百餘里，時有難處。引渭穿渠起長安，旁南山下，〔三〕至河三百餘里，徑，易遭，〔四〕度可令三月罷；（罷）而渠下民田萬餘頃又可得以溉。此（捐）〔損〕漕省卒，而益肥關中之地，得穀。」上以為然，令齊人水工徐伯表，〔五〕發卒數萬人穿漕渠，三歲而通。以漕，大便利。其後漕稍多，而渠下之民頗得以溉矣。","sentenceOrder":39},
  {"id":"s_work_han_thu_40_40","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「異時，往時也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_40_41","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「計度其功，六月而後可罷也。度音大各反。」","sentenceOrder":41},
  {"id":"s_work_han_thu_40_42","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　師古曰：「旁音步浪反。」","sentenceOrder":42},
  {"id":"s_work_han_thu_40_43","chapterId":"ch_work_han_thu_40","textTraditional":"〔四〕　〔師古曰：「徑，直也。易音弋豉反。」〕","sentenceOrder":43},
  {"id":"s_work_han_thu_40_44","chapterId":"ch_work_han_thu_40","textTraditional":"〔五〕　師古曰：「巡行穿渠之處而表記之，今之豎標是。」","sentenceOrder":44},
  {"id":"s_work_han_thu_40_45","chapterId":"ch_work_han_thu_40","textTraditional":"後河東守番係〔一〕言：「漕從山東西，歲百餘萬石，〔二〕更底柱之艱，〔三〕敗亡甚多而煩費。穿渠引汾溉皮氏、汾陰下，引河溉汾陰、蒲阪下，〔四〕度可得五千頃。故盡河堧棄地，〔五〕民茭牧其中耳，〔六〕今溉田之，〔七〕度可得穀二百萬石以上。穀從渭上，與關中無異，〔八〕而底柱之東可毋復漕。」上以為然，發卒數萬人作渠田。數歲，河移徙，渠不利，田者不能償種。〔九〕久之，河東渠田廢，予越人，令少府以為稍入。〔一０〕","sentenceOrder":45},
  {"id":"s_work_han_thu_40_46","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「姓番名係也。番音普安反。」","sentenceOrder":46},
  {"id":"s_work_han_thu_40_47","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「謂從山東運漕而西入關也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_40_48","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　師古曰：「更，歷也，音庚。」","sentenceOrder":48},
  {"id":"s_work_han_thu_40_49","chapterId":"ch_work_han_thu_40","textTraditional":"〔四〕　師古曰：「引汾水可用溉皮氏及汾陰以下，而引河水可用溉汾陰及蒲阪以下，地形所宜也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_40_50","chapterId":"ch_work_han_thu_40","textTraditional":"〔五〕　師古曰：「謂河岸以下緣河邊地素不耕墾者也。堧音而緣反。」","sentenceOrder":50},
  {"id":"s_work_han_thu_40_51","chapterId":"ch_work_han_thu_40","textTraditional":"〔六〕　師古曰：「茭，乾草也。謂收茭草及牧畜產於其中。茭音交。」","sentenceOrder":51},
  {"id":"s_work_han_thu_40_52","chapterId":"ch_work_han_thu_40","textTraditional":"〔七〕　師古曰：「溉而種之。」","sentenceOrder":52},
  {"id":"s_work_han_thu_40_53","chapterId":"ch_work_han_thu_40","textTraditional":"〔八〕　師古曰：「雖從關外而來，於渭水運上，皆可致之，故曰與關中收穀無異也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_40_54","chapterId":"ch_work_han_thu_40","textTraditional":"〔九〕　師古曰：「言所收之直不足償糧種之費也。種音之勇反。」","sentenceOrder":54},
  {"id":"s_work_han_thu_40_55","chapterId":"ch_work_han_thu_40","textTraditional":"〔一０〕如淳曰：「時越人有徙者，以田與之，其租稅入少府也。」師古曰：「越人習於水田，又新至，未有業，故與之也。稍，漸也。其入未多，故謂之稍也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_40_56","chapterId":"ch_work_han_thu_40","textTraditional":"其後人有上書，欲通褒斜道及漕，〔一〕事下御史大夫張湯。湯問之，言「抵蜀從故道，故道多阪，回遠。〔二〕今穿褒斜道，少阪，近四百里；而褒水通沔，斜水通渭，皆可以行船漕。漕從南陽上沔入褒，褒絕水至斜，間百餘里，以車轉，從斜下渭。如此，漢中穀可致，而山東從沔無限，便於底柱之漕。且褒斜材木竹箭之饒，儗於巴蜀。」〔三〕上以為然。拜湯子卬為漢中守，發數萬人作褒斜道五百餘里。道果便近，而水多湍石，不可漕。","sentenceOrder":56},
  {"id":"s_work_han_thu_40_57","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「褒、斜，二谷名，其谷皆各自有水耳。斜音弋奢反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_40_58","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「抵，至也。故道屬武都，有蠻夷，故曰道，即今鳳州界也。回音胡內反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_40_59","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　師古曰：「儗，比也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_40_60","chapterId":"ch_work_han_thu_40","textTraditional":"其後嚴熊言「臨晉民願穿洛以溉重泉以東萬餘頃故惡地。〔一〕誠即得水，可令畝十石。」於是為發卒萬人穿渠，自徵引洛水至商顏下。〔二〕岸善崩，〔三〕乃鑿井，深者四十餘丈。往往為井，井下相通行水。水隤以絕商顏，〔四〕東至山領十餘里間。井渠之生自此始。穿得龍骨，故名曰龍首渠。作之十餘歲，渠頗通，猶未得其饒。","sentenceOrder":60},
  {"id":"s_work_han_thu_40_61","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「臨晉、重泉皆馮翊之縣也。洛即漆沮水。」","sentenceOrder":61},
  {"id":"s_work_han_thu_40_62","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　應劭曰：「徵在馮翊。商顏，山名也。」師古曰：「徵音懲，即今所謂澄城也。商顏，商山之顏也。謂之顏者，譬人之顏額也，亦猶山（額）〔領〕象人之頸領。」","sentenceOrder":62},
  {"id":"s_work_han_thu_40_63","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　如淳曰：「洛水岸也。」師古曰：「善崩，言憙崩也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_40_64","chapterId":"ch_work_han_thu_40","textTraditional":"〔四〕　師古曰：「下流曰隤。」","sentenceOrder":64},
  {"id":"s_work_han_thu_40_65","chapterId":"ch_work_han_thu_40","textTraditional":"自河決瓠子後二十餘歲，歲因以數不登，而梁楚之地尤甚。上既封禪，巡祭山川，其明年，乾封少雨。〔一〕上乃使汲仁、郭昌發卒數萬人塞瓠子決河。於是上以用事萬里沙，則還自臨決河，湛白馬玉璧，〔二〕令群臣從官自將軍以下皆負薪寘決河。〔三〕是時東郡燒草，以故薪柴少，而下淇園之竹以為揵。〔四〕上既臨河決，悼功之不成，乃作歌曰：","sentenceOrder":65},
  {"id":"s_work_han_thu_40_66","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「乾音干。解在郊祀志。」","sentenceOrder":66},
  {"id":"s_work_han_thu_40_67","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「湛讀曰沈。沈馬及璧以禮水神也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_40_68","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　師古曰：「寘音大千反。」","sentenceOrder":68},
  {"id":"s_work_han_thu_40_69","chapterId":"ch_work_han_thu_40","textTraditional":"〔四〕　晉灼曰：「淇園，衛之苑也。」如淳曰：「樹竹塞水決之口，稍稍布插按樹之，水稍弱，補令密，謂之揵。以草塞其衷，乃以土填之。有石，以石為之。」師古曰：「揵音其偃反。」","sentenceOrder":69},
  {"id":"s_work_han_thu_40_70","chapterId":"ch_work_han_thu_40","textTraditional":"瓠子決兮將奈何？浩浩洋洋，慮殫為河。〔一〕殫為河兮地不得寧，功無已時兮吾山平。〔二〕吾山平兮鉅野溢，〔三〕魚弗鬱兮柏冬日。〔四〕正道弛兮離常流，〔五〕蛟龍騁兮放遠游。歸舊川兮神哉沛，〔六〕不封禪兮安知外！〔七〕皇謂河公兮何不仁，〔八〕泛濫不止兮愁吾人！齧桑浮兮淮、泗滿，〔九〕久不反兮水維緩。〔一０〕","sentenceOrder":70},
  {"id":"s_work_han_thu_40_71","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　如淳曰：「殫，盡也。」師古曰：「浩浩洋洋，皆水盛貌。慮猶恐也。浩音胡老反。洋音羊。」","sentenceOrder":71},
  {"id":"s_work_han_thu_40_72","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　如淳曰：「恐水漸山使平也。」韋昭曰：「鑿山以填河。」師古曰：「韋說是也。已，止也。言用功多不可畢止也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_40_73","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　如淳曰：「瓠子決，灌鉅野澤使溢也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_40_74","chapterId":"ch_work_han_thu_40","textTraditional":"〔四〕　孟康曰：「鉅野滿溢，則眾魚弗鬱而滋長，迫冬日乃止也。」師古曰：「孟說非也。弗鬱，憂不樂也。水長涌溢，濊濁不清，故魚不樂，又迫於冬日，將甚困也。柏讀與迫同。弗音佛。」","sentenceOrder":74},
  {"id":"s_work_han_thu_40_75","chapterId":"ch_work_han_thu_40","textTraditional":"〔五〕　晉灼曰：「言河道皆弛壞。」","sentenceOrder":75},
  {"id":"s_work_han_thu_40_76","chapterId":"ch_work_han_thu_40","textTraditional":"〔六〕　臣瓚曰：「水還舊道，則群害消除，神祐滂沛也。」師古曰：「沛音普大反。」","sentenceOrder":76},
  {"id":"s_work_han_thu_40_77","chapterId":"ch_work_han_thu_40","textTraditional":"〔七〕　師古曰：「言不因巡（將）〔狩〕封禪而出，則不知關外有此水。」","sentenceOrder":77},
  {"id":"s_work_han_thu_40_78","chapterId":"ch_work_han_thu_40","textTraditional":"〔八〕　張晏曰：「皇，武帝也。河公，河伯也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_40_79","chapterId":"ch_work_han_thu_40","textTraditional":"〔九〕　如淳曰：「齧桑，邑名，為水所浮漂。」","sentenceOrder":79},
  {"id":"s_work_han_thu_40_80","chapterId":"ch_work_han_thu_40","textTraditional":"〔一０〕師古曰：「水維，水之綱維也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_40_81","chapterId":"ch_work_han_thu_40","textTraditional":"一曰：","sentenceOrder":81},
  {"id":"s_work_han_thu_40_82","chapterId":"ch_work_han_thu_40","textTraditional":"河湯湯兮激潺湲，〔一〕北渡回兮迅流難。〔二〕搴長茭兮湛美玉，〔三〕河公許兮薪不屬。〔四〕薪不屬兮衛人罪，〔五〕燒蕭條兮噫乎何以御水！〔六〕隤林竹兮揵石菑，〔七〕宣防塞兮萬福來。","sentenceOrder":82},
  {"id":"s_work_han_thu_40_83","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「歌有二章，自『河湯湯』以下更是其一，故云一曰也。湯湯，疾貌也。潺湲，激流也。湯音傷。潺音仕連反。湲音于權反。」","sentenceOrder":83},
  {"id":"s_work_han_thu_40_84","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「迅，疾也，音訊。」","sentenceOrder":84},
  {"id":"s_work_han_thu_40_85","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　如淳曰：「搴，取也。茭，草也，音（茭）〔郊〕。一曰，茭，竿也。取長竿樹之，用著石間以塞決河也。」臣瓚曰：「竹葦絙謂之茭也，所以引置土石也。」師古曰：「瓚說是也。搴，拔也。絙，索也。湛美玉者，以祭河也。茭字宜從竹。搴音騫。茭音交，又音爻。湛讀曰沈。絙音工登反。」","sentenceOrder":85},
  {"id":"s_work_han_thu_40_86","chapterId":"ch_work_han_thu_40","textTraditional":"〔四〕　如淳曰：「旱燒，故薪不足也。」師古曰：「沈玉禮神，但許福祐，但以薪不屬逮，故無功也。屬音之欲反。」","sentenceOrder":86},
  {"id":"s_work_han_thu_40_87","chapterId":"ch_work_han_thu_40","textTraditional":"〔五〕　師古曰：「東郡本衛地，故言此衛（之人）〔人之〕罪也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_40_88","chapterId":"ch_work_han_thu_40","textTraditional":"〔六〕　師古曰：「燒草皆盡，故野蕭條然也。噫乎，歎辭也。噫音於期反。」","sentenceOrder":88},
  {"id":"s_work_han_thu_40_89","chapterId":"ch_work_han_thu_40","textTraditional":"〔七〕　師古曰：「隤林竹者，即上所說『下淇園之竹以為揵』也。石菑者謂臿石立之，然後以土就填塞也。菑亦臿耳，音側其反，義與（剚）〔插〕同。」","sentenceOrder":89},
  {"id":"s_work_han_thu_40_90","chapterId":"ch_work_han_thu_40","textTraditional":"於是卒塞瓠子，築宮其上，名曰宣防。而道河北行二渠，復禹舊跡，〔一〕而梁、楚之地復寧，無水災。","sentenceOrder":90},
  {"id":"s_work_han_thu_40_91","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「道讀曰導。」","sentenceOrder":91},
  {"id":"s_work_han_thu_40_92","chapterId":"ch_work_han_thu_40","textTraditional":"自是之後，用事者爭言水利。朔方、西河、河西、酒泉皆引河及川谷以溉田。而關中靈軹、成國、湋渠〔一〕引諸川，汝南、九江引淮，東海引鉅定，〔二〕泰山下引汶水，〔三〕皆穿渠為溉田，各萬餘頃。它小渠及陂山通道者，不可勝言也。〔四〕","sentenceOrder":92},
  {"id":"s_work_han_thu_40_93","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　如淳曰：「地理志『盩厔有靈軹渠』。成國，渠名，在陳倉。湋音韋，水出韋谷。」","sentenceOrder":93},
  {"id":"s_work_han_thu_40_94","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　臣瓚曰：「鉅定，澤名也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_40_95","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　師古曰：「汶音問。」","sentenceOrder":95},
  {"id":"s_work_han_thu_40_96","chapterId":"ch_work_han_thu_40","textTraditional":"〔四〕　師古曰：「陂山，因山之形也。道，引也。陂音彼義反。道讀曰導。一曰，陂山，遏山之流以為陂也，音彼皮反。」","sentenceOrder":96},
  {"id":"s_work_han_thu_40_97","chapterId":"ch_work_han_thu_40","textTraditional":"自鄭國渠起，至元鼎六年，百三十六歲，而兒寬為左內史，奏請穿鑿六輔渠，〔一〕以益溉鄭國傍高卬之田。〔二〕上曰：「農，天下之本也。泉流灌寖，所以育五穀也。〔三〕左、右內史地，名山川原甚眾，細民未知其利，故為通溝瀆，畜陂澤，〔四〕所以備旱也。今內史稻田租挈重，不與郡同，〔五〕其議減。令吏民勉農，盡地利，平繇行水，勿使失時。」〔六〕","sentenceOrder":97},
  {"id":"s_work_han_thu_40_98","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「在鄭國渠之裏，今尚謂之輔渠，亦曰六渠也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_40_99","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「素不得鄭國之溉灌者也。卬謂上向也，讀曰仰。」","sentenceOrder":99},
  {"id":"s_work_han_thu_40_100","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　師古曰：「寖，古浸字。」","sentenceOrder":100},
  {"id":"s_work_han_thu_40_101","chapterId":"ch_work_han_thu_40","textTraditional":"〔四〕　師古曰：「畜讀曰蓄。」","sentenceOrder":101},
  {"id":"s_work_han_thu_40_102","chapterId":"ch_work_han_thu_40","textTraditional":"〔五〕　師古曰：「租挈，收田租之約令也。郡謂四方諸郡也。挈音苦計反。」","sentenceOrder":102},
  {"id":"s_work_han_thu_40_103","chapterId":"ch_work_han_thu_40","textTraditional":"〔六〕　師古曰：「平繇者，均齊渠堰之力役，謂俱得水利也。繇讀曰徭。」","sentenceOrder":103},
  {"id":"s_work_han_thu_40_104","chapterId":"ch_work_han_thu_40","textTraditional":"後十六歲，太始二年，趙中大夫白公〔一〕復奏穿渠。引涇水，首起谷口，尾入櫟陽，〔二〕注渭中，袤二百里，〔三〕溉田四千五百餘頃，因名曰白渠。民得其饒，歌之曰：「田於何所？池陽、谷口。鄭國在前，白渠起後。〔四〕舉臿為雲，決渠為雨。〔五〕涇水一石，其泥數斗。且溉且糞，長我禾黍。〔六〕衣食京師，億萬之口。」言此兩渠饒也。","sentenceOrder":104},
  {"id":"s_work_han_thu_40_105","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　鄭氏曰：「白，姓。公，爵。時人多相謂為公。」師古曰：「此時無公爵也，蓋相呼尊老之稱耳。」","sentenceOrder":105},
  {"id":"s_work_han_thu_40_106","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「谷口即今雲陽縣治谷是。」","sentenceOrder":106},
  {"id":"s_work_han_thu_40_107","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　師古曰：「袤，長也，音茂。」","sentenceOrder":107},
  {"id":"s_work_han_thu_40_108","chapterId":"ch_work_han_thu_40","textTraditional":"〔四〕　師古曰：「鄭國興於秦時，故云前。」","sentenceOrder":108},
  {"id":"s_work_han_thu_40_109","chapterId":"ch_work_han_thu_40","textTraditional":"〔五〕　師古曰：「臿，鍫也，所以開渠者也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_40_110","chapterId":"ch_work_han_thu_40","textTraditional":"〔六〕　如淳曰：「水渟淤泥，可以當糞。」","sentenceOrder":110},
  {"id":"s_work_han_thu_40_111","chapterId":"ch_work_han_thu_40","textTraditional":"是時方事匈奴，興功利，言便宜者甚眾。齊人延年上書〔一〕言：「河出昆侖，經中國，注勃海，是其地勢西北高而東南下也。可案圖書，觀地形，令水工準高下，開大河上領，〔二〕出之胡中，東注之海。如此，關東長無水災，北邊不憂匈奴，可以省隄防備塞，士卒轉輸，胡寇侵盜，覆軍殺將，暴骨原野之患。天下常備匈奴而不憂百越者，以其水絕壤斷也。此功壹成，萬世大利。」書奏，上壯之，報曰：「延年計議甚深。然河乃大禹之所道也，〔三〕聖人作事，為萬世功，通於神明，恐難改更。」","sentenceOrder":111},
  {"id":"s_work_han_thu_40_112","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「史不得其姓。」","sentenceOrder":112},
  {"id":"s_work_han_thu_40_113","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　晉灼曰：「上領，山頭也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_40_114","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　師古曰：「道讀曰導。」","sentenceOrder":114},
  {"id":"s_work_han_thu_40_115","chapterId":"ch_work_han_thu_40","textTraditional":"自塞宣房後，河復北決於館陶，分為屯氏河，〔一〕東北經魏郡、清河、信都、勃海入海，廣深與大河等，故因其自然，不隄塞也。此開通後，館陶東北四五郡雖時小被水害，而兗州以南六郡無水憂。宣帝地節中，光祿大夫郭昌使行河。北曲三所水流之勢皆邪直貝丘縣。〔二〕恐水盛，隄防不能禁，乃各更穿渠，直東，經東郡界中，不令北曲。渠通利，百姓安之。元帝永光五年，河決清河靈鳴犢口〔三〕，而屯氏河絕。","sentenceOrder":115},
  {"id":"s_work_han_thu_40_116","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「屯音大門反。而隋室分析州縣，誤以為毛氏河，乃置毛州，失之甚矣。」","sentenceOrder":116},
  {"id":"s_work_han_thu_40_117","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「直，當也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_40_118","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　師古曰：「清河之靈縣鳴犢河口也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_40_119","chapterId":"ch_work_han_thu_40","textTraditional":"成帝初，清河都尉馮逡〔一〕奏言：「郡承河下流，與兗州東郡分水為界，城郭所居尤卑下，土壤輕脆易傷。頃所以闊無大害者，以屯氏河通，兩川分流也。〔二〕今屯氏河塞，靈鳴犢口又益不利，獨一川兼受數河之任，雖高增隄防，終不能泄。如有霖雨，旬日不霽，必盈溢。〔三〕靈鳴犢口在清河東界，所在處下，雖令通利，猶不能為魏郡、清河減損水害。禹非不愛民力，以地形有勢，故穿九河，今既滅難明，屯氏河不流行七十餘年，新絕未久，其處易浚。〔四〕又其口所居高，於以分〔流〕殺水力，道里便宜，可復浚以助大河泄暴水，備非常。又地節時郭昌穿直渠，後三歲，河水更從故第二曲間北可六里，復南合。今其曲勢復邪直貝丘，百姓寒心，宜復穿渠東行。不豫修治，北決病四五郡，南決病十餘郡，然後憂之，晚矣。」事下丞相、御史，白博士許商治尚書，善為算，能度功用。〔五〕遣行視，〔六〕以為屯氏河盈溢所為，方用度不足，〔七〕可且勿浚。","sentenceOrder":119},
  {"id":"s_work_han_thu_40_120","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「逡音七旬反。」","sentenceOrder":120},
  {"id":"s_work_han_thu_40_121","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「闊，稀也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_40_122","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　師古曰：「雨止曰霽，音子計反，又音才詣反。」","sentenceOrder":122},
  {"id":"s_work_han_thu_40_123","chapterId":"ch_work_han_thu_40","textTraditional":"〔四〕　師古曰：「浚謂治道之令其深也。浚音峻。」","sentenceOrder":123},
  {"id":"s_work_han_thu_40_124","chapterId":"ch_work_han_thu_40","textTraditional":"〔五〕　師古曰：「白，白於天子也。度音大各反。」","sentenceOrder":124},
  {"id":"s_work_han_thu_40_125","chapterId":"ch_work_han_thu_40","textTraditional":"〔六〕　師古曰：「行音下更反。」","sentenceOrder":125},
  {"id":"s_work_han_thu_40_126","chapterId":"ch_work_han_thu_40","textTraditional":"〔七〕　師古曰：「言國家少財役。」","sentenceOrder":126},
  {"id":"s_work_han_thu_40_127","chapterId":"ch_work_han_thu_40","textTraditional":"後三歲，河果決於館陶及東郡金隄，泛溢兗、豫，入平原、千乘、濟南，凡灌四郡三十二縣，水居地十五萬餘頃，深者三丈，壞敗官亭室廬且四萬所。御史大夫尹忠對方略疏闊，上切責之，忠自殺。遣大司農非調〔一〕調均錢穀河決所灌之郡，〔二〕謁者二人發河南以東漕船五百〈木叟〉，〔三〕徙民避水居丘陵，九萬七千餘口。河隄使者王延世使塞，〔四〕以竹落長四丈，大九圍，盛以小石，兩船夾載而下之。三十六日，河隄成。上曰：「東郡河決，流漂二州，校尉延世隄防三旬立塞。其以五年為河平元年。卒治河者為著外繇六月。〔五〕惟延世長於計策，功費約省，用力日寡，朕甚嘉之。其以延世為光祿大夫，秩中二千石，賜爵關內侯，黃金百斤。」","sentenceOrder":127},
  {"id":"s_work_han_thu_40_128","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「大司農名非調也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_40_129","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「令其調發均平錢穀遭水之郡，使存給也。調音徒釣反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_40_130","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　師古曰：「一船為一〈木叟〉，音先勞反，其字從木。」","sentenceOrder":130},
  {"id":"s_work_han_thu_40_131","chapterId":"ch_work_han_thu_40","textTraditional":"〔四〕　師古曰：「命其為使而塞河也。華陽國志云延世字長叔，犍為資中人也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_40_132","chapterId":"ch_work_han_thu_40","textTraditional":"〔五〕　如淳曰：「律說，戍邊一歲當罷，若有急，當留守六月。今以卒治河之故，復留六月。」孟康曰：「外繇，戍邊也。治水不復戍邊也。」師古曰：「如、孟二說皆非也。以卒治河有勞，雖執役日近，皆得比繇戍六月也。著謂著於簿籍也。著音竹助反。下云『非受平賈，為著外繇』，其義亦同。」","sentenceOrder":132},
  {"id":"s_work_han_thu_40_133","chapterId":"ch_work_han_thu_40","textTraditional":"後二歲，河復決平原，流入濟南、千乘，所壞敗者半建始時，復遣王延世治之。杜欽說大將軍王鳳，以為「前河決，丞相史楊焉言延世受焉術以塞之，蔽不肯見。今獨任延世，延世見前塞之易，恐其慮害不深。又審如焉言，延世之巧，反不如焉。且水勢各異，不博議利害而任一人，如使不及今冬成，來春桃華水盛，必羨溢，有填淤反壤之害。〔一〕如此，數郡種不得下，〔二〕民人流散，盜賊將生，雖重誅延世，無益於事。宜遣焉及將作大匠許商、諫大夫乘馬延年雜作。〔三〕延世與焉必相破壞，深論便宜，以相難極。〔四〕商、延年皆明計算，能商功利，〔五〕足以分別是非，擇其善而從之，必有成功。」鳳如欽言，白遣焉等作治，六月乃成。復賜延世黃金百斤。治河卒非受平賈者，為著外繇六月。〔六〕","sentenceOrder":133},
  {"id":"s_work_han_thu_40_134","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「月令『仲春之月，始雨水，桃始華』。蓋桃方華時，既有雨水，川谷冰泮，眾流猥集，波瀾盛長，故謂之桃華水耳。而韓詩傳云『三月桃華水』。反壤者，水塞不通，故令其土壤反還也。羨音弋繕反。淤音於庶反。」","sentenceOrder":134},
  {"id":"s_work_han_thu_40_135","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「種，五穀之子也，音之勇反。」","sentenceOrder":135},
  {"id":"s_work_han_thu_40_136","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　孟康曰：「乘馬，姓也。」師古曰：「乘音食證反。」","sentenceOrder":136},
  {"id":"s_work_han_thu_40_137","chapterId":"ch_work_han_thu_40","textTraditional":"〔四〕　師古曰：「壞，毀也，音怪。極，窮也，音居力反。」","sentenceOrder":137},
  {"id":"s_work_han_thu_40_138","chapterId":"ch_work_han_thu_40","textTraditional":"〔五〕　師古曰：「商，度也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_40_139","chapterId":"ch_work_han_thu_40","textTraditional":"〔六〕　蘇林曰：「平賈，以錢取人作卒，顧其時庸之平賈也。」如淳曰：「律說，平賈一月，得錢二千。」師古曰：「賈音價。」","sentenceOrder":139},
  {"id":"s_work_han_thu_40_140","chapterId":"ch_work_han_thu_40","textTraditional":"後九歲，鴻嘉四年，楊焉言「從河上下，患底柱隘，可鐫廣之。」〔一〕上從其言，使焉鐫之。鐫之裁沒水中，不能去，而令水益湍怒，為害甚於故。","sentenceOrder":140},
  {"id":"s_work_han_thu_40_141","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「鐫謂琢鑿之也，音子全反。」","sentenceOrder":141},
  {"id":"s_work_han_thu_40_142","chapterId":"ch_work_han_thu_40","textTraditional":"是歲，勃海、清河、信都河水湓溢，灌縣邑三十一，〔一〕敗官亭民舍四萬餘所。河隄都尉許商與丞相史孫禁共行視，圖方略。〔二〕禁以為「今河溢之害數倍於前決平原時。今可決平原金隄間，開通大河，令入故篤馬河。〔三〕至海五百餘里，水道浚利，又乾三郡水地，得美田且二十餘萬頃，足以償所開傷民田廬處，又省吏卒治隄救水，歲三萬人以上。」許商以為「古說九河之名，有徒駭、胡蘇、鬲津，今見在成平、東光、鬲界中。〔四〕自鬲以北至徒駭間，相去二百餘里，今河雖數移徙，不離此域。孫禁所欲開者，在九河南篤馬河，失水之跡，處勢平夷，旱則淤絕，水則為敗，不可許。」公卿皆從商言。先是，谷永以為「河，中國之經瀆，〔五〕聖王興則出圖書，王道廢則竭絕。今潰溢橫流，漂沒陵阜，異之大者也。修政以應之，災變自除。」是時李尋、解光亦言「陰氣盛則水為之長，故一日之間，晝減夜增，江河滿溢，所謂水不潤下，雖常於卑下之地，猶日月變見於朔望，明天道有因而作也。眾庶見王延世蒙重賞，競言便巧，不可用。議者常欲求索九河故跡而穿之，今因其自決，可且勿塞，以觀水勢。河欲居之，當稍自成川，跳出沙土，然後順天心而圖之，必有成功，而用財力寡。」於是遂止不塞。滿昌、師丹等數言百姓可哀，上數遣使者處業振贍之。〔六〕","sentenceOrder":142},
  {"id":"s_work_han_thu_40_143","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「湓，踊也，音普頓反。」","sentenceOrder":143},
  {"id":"s_work_han_thu_40_144","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「圖，謀也。行音下更反。」","sentenceOrder":144},
  {"id":"s_work_han_thu_40_145","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　韋昭曰：「在平原縣。」","sentenceOrder":145},
  {"id":"s_work_han_thu_40_146","chapterId":"ch_work_han_thu_40","textTraditional":"〔四〕　師古曰：「此九河之三也。徒駭在成平，胡蘇在東光，鬲津在鬲。成平、東光屬勃海，鬲屬平原。徒駭者，言禹治此河，用功極眾，故人徒驚駭也。胡蘇，下流急疾之貌也。鬲津，言其陿小，可鬲以為津而度也。鬲與隔同。」","sentenceOrder":146},
  {"id":"s_work_han_thu_40_147","chapterId":"ch_work_han_thu_40","textTraditional":"〔五〕　師古曰：「經，常也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_40_148","chapterId":"ch_work_han_thu_40","textTraditional":"〔六〕　師古曰：「處業，謂安處之使得其居業。」","sentenceOrder":148},
  {"id":"s_work_han_thu_40_149","chapterId":"ch_work_han_thu_40","textTraditional":"哀帝初，平當使領河隄，〔一〕奏言「九河今皆寘滅，按經義治水，有決河深川，〔二〕而無隄防雍塞之文。〔三〕河從魏郡以東，北多溢決，水跡難以分明。四海之眾不可誣，宜博求能浚川疏河者。」下丞相孔光、大司空何武，奏請部刺史、三輔、三河、弘農太守舉吏民能者，莫有應書。待詔賈讓奏言：","sentenceOrder":149},
  {"id":"s_work_han_thu_40_150","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「為使而領其事。」","sentenceOrder":150},
  {"id":"s_work_han_thu_40_151","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「決，分泄也。深，浚治也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_40_152","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　師古曰：「雍讀曰壅。」","sentenceOrder":152},
  {"id":"s_work_han_thu_40_153","chapterId":"ch_work_han_thu_40","textTraditional":"治河有上中下策。古者立國居民，疆理土地，必遺川澤之分，度水勢所不及。〔一〕大川無防，小水得入，陂障卑下，以為汙澤，〔二〕使秋水多，得有所休息，左右游波，寬緩而不迫。夫土之有川，猶人之有口也。治土而防其川，猶止兒啼而塞其口，豈不遽止，然其死可立而待也。〔三〕故曰：「善為川者，決之使道；〔四〕善為民者，宣之使言。」蓋隄防之作，近起戰國，雍防百川，各以自利。〔五〕齊與趙、魏，以河為竟。〔六〕趙、魏瀕山，齊地卑下〔七〕，作隄去河二十五里。河水東抵齊隄，則西泛趙、魏，趙、魏亦為隄去河二十五里。雖非其正，水尚有所游盪。時至而去，則填淤肥美，民耕田之。或久無害，稍築室宅，遂成聚落。大水時至漂沒，則更起隄防以自救，稍去其城郭，排水澤而居之，湛溺自其宜也。〔八〕今隄防陿者去水數百步，遠者數里。近黎陽南故大金隄，從河西西北行，至西山南頭，乃折東，與東山相屬。〔九〕民居金隄東，為廬舍，（住）〔往〕十餘歲更起隄，從東山南頭直南與故大隄會。又內黃界中有澤，方數十里，環之有隄，〔一０〕往十餘歲太守以賦民〔一一〕，民今起廬舍其中，此臣親所見者也。東郡白馬故大隄亦復數重，民皆居其間。從黎陽北盡魏界，故大隄去河遠者數十里，內亦數重，此皆前世所排也。河從河內北至黎陽為石隄，激使東抵東郡平剛；〔一二〕又為石隄，使西北抵黎陽、觀下；〔一三〕又為石隄，使東北抵東郡津北；又為石隄，使西北抵魏郡昭陽；又為石隄，激使東北。百餘里間，河再西三東，迫阨如此，不得安息。","sentenceOrder":153},
  {"id":"s_work_han_thu_40_154","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「遺，留也。度，計也。言川澤水所流聚之處，皆留而置之，不以為居邑而妄墾殖，必計水所不及，然後居而田之也。分音扶問反。度音大各反。」","sentenceOrder":154},
  {"id":"s_work_han_thu_40_155","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「停水曰汙，音一胡反。」","sentenceOrder":155},
  {"id":"s_work_han_thu_40_156","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　師古曰：「遽，速也，音其庶反。」","sentenceOrder":156},
  {"id":"s_work_han_thu_40_157","chapterId":"ch_work_han_thu_40","textTraditional":"〔四〕　師古曰：「道讀曰導。導，通引也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_40_158","chapterId":"ch_work_han_thu_40","textTraditional":"〔五〕　師古曰：「雍讀曰壅。」","sentenceOrder":158},
  {"id":"s_work_han_thu_40_159","chapterId":"ch_work_han_thu_40","textTraditional":"〔六〕　師古曰：「竟讀曰境。」","sentenceOrder":159},
  {"id":"s_work_han_thu_40_160","chapterId":"ch_work_han_thu_40","textTraditional":"〔七〕　師古曰：「瀕山，猶言以山為邊界也。」師古曰：「瀕音頻，又音賓。」","sentenceOrder":160},
  {"id":"s_work_han_thu_40_161","chapterId":"ch_work_han_thu_40","textTraditional":"〔八〕　師古曰：「湛讀曰沈。」","sentenceOrder":161},
  {"id":"s_work_han_thu_40_162","chapterId":"ch_work_han_thu_40","textTraditional":"〔九〕　師古曰：「屬，連及也，音之欲反。」","sentenceOrder":162},
  {"id":"s_work_han_thu_40_163","chapterId":"ch_work_han_thu_40","textTraditional":"〔一０〕師古曰：「環，繞也。」","sentenceOrder":163},
  {"id":"s_work_han_thu_40_164","chapterId":"ch_work_han_thu_40","textTraditional":"〔一一〕師古曰：「以隄中之地給與民。」","sentenceOrder":164},
  {"id":"s_work_han_thu_40_165","chapterId":"ch_work_han_thu_40","textTraditional":"〔一二〕師古曰：「激者，聚石於隄旁衝要之處，所以激去其水也。激音工歷反。」","sentenceOrder":165},
  {"id":"s_work_han_thu_40_166","chapterId":"ch_work_han_thu_40","textTraditional":"〔一三〕師古曰：「觀，縣名也，音工喚反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_40_167","chapterId":"ch_work_han_thu_40","textTraditional":"今行上策，徙冀州之民當水衝者，決黎陽遮害亭，放河使北入海。河西薄大山，東薄金隄，勢不能遠泛濫，期月自定。難者將曰：「若如此，敗壞城郭田廬冢墓以萬數，百姓怨恨。」昔大禹治水，山陵當路者毀之，故鑿龍門，辟伊闕，〔一〕析底柱，破碣石，〔二〕墮斷天地之性。〔三〕此乃人功所造，何足言也！今瀕河十郡治隄歲費且萬萬，及其大決，所殘無數。如出數年治河之費，以業所徙之民，遵古聖之法，定山川之位，使神人各處其所，而不相奸。〔四〕且以大漢方制萬里，豈其與水爭咫尺之地哉？此功一立，河定民安，千載無患，故謂之上策。","sentenceOrder":167},
  {"id":"s_work_han_thu_40_168","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「辟讀曰闢。闢，開也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_40_169","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「析，分也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_40_170","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　師古曰：「墮，毀也，音火規反。」","sentenceOrder":170},
  {"id":"s_work_han_thu_40_171","chapterId":"ch_work_han_thu_40","textTraditional":"〔四〕　師古曰：「奸音干。」","sentenceOrder":171},
  {"id":"s_work_han_thu_40_172","chapterId":"ch_work_han_thu_40","textTraditional":"若乃多穿漕渠於冀州地，使民得以溉田，分殺水怒，雖非聖人法，然亦救敗術也。難者將曰：「河水高於平地，歲增隄防，猶尚決溢，不可以開渠。」臣竊按視遮害亭西十八里，至淇水口，乃有金隄，高一丈。自是東，地稍下，隄稍高，至遮害亭，高四五丈。往六七歲，河水大盛，增丈七尺，壞黎陽南郭門，入至隄下。〔一〕水未踰隄二尺所，從隄上北望，河高出民屋，百姓皆走上山。水留十三日，隄潰（二所），吏民塞之。臣循隄上，行視水勢，〔二〕南七十餘里，至淇口，水適至隄半，計出地上五尺所。今可從淇口以東為石隄，多張水門。初元中，遮害亭下河去隄足數十步，至今四十餘歲，適至隄足。由是言之，其地堅矣。恐議者疑河大川難禁制，滎陽漕渠足以（下）〔卜〕之，〔三〕其水門但用木與土耳，今據堅地作石隄，勢必完安。冀州渠首盡當卬此水門。治渠非穿地也，〔四〕但為東方一隄，北行三百餘里，入漳水中，其西因山足高地，諸渠皆往往股引取之；〔五〕旱則開東方下水門溉冀州，水則開西方高門分河流。通渠有三利，不通有三害。民常罷於救水，半失作業；〔六〕水行地上，湊潤上徹，民則病溼氣，木皆立枯，鹵不生穀；〔七〕決溢有敗，為魚鱉食：此三害也。若有渠溉，則鹽鹵下溼，填淤加肥；〔八〕故種禾麥，更為秔稻，高田五倍，下田十倍；〔九〕轉漕舟船之便：此三利也。今瀕河隄吏卒郡數千人，伐買薪石之費歲數千萬，足以通渠成水門；又民利其溉灌，相率治渠，雖勞不罷。〔一０〕民田適治，河隄亦成，此誠富國安民，興利除害，支數百歲，故謂之中策。","sentenceOrder":172},
  {"id":"s_work_han_thu_40_173","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　如淳曰：「然則隄在郭內也。」臣瓚曰：「謂水從郭南門入，北門出，而至隄也。」師古曰：「瓚說是也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_40_174","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「行音下更反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_40_175","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　如淳曰：「今礫谿口是也。言作水門通水流，不為害也。」師古曰：「礫谿，谿名，即水經所云（涑）〔泲〕水東通礫谿者。」","sentenceOrder":175},
  {"id":"s_work_han_thu_40_176","chapterId":"ch_work_han_thu_40","textTraditional":"〔四〕　師古曰：「卬音牛向反。」","sentenceOrder":176},
  {"id":"s_work_han_thu_40_177","chapterId":"ch_work_han_thu_40","textTraditional":"〔五〕　如淳曰：「股，支別也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_40_178","chapterId":"ch_work_han_thu_40","textTraditional":"〔六〕　師古曰：「此一害也。罷讀曰疲。」","sentenceOrder":178},
  {"id":"s_work_han_thu_40_179","chapterId":"ch_work_han_thu_40","textTraditional":"〔七〕　師古曰：「此二害。」","sentenceOrder":179},
  {"id":"s_work_han_thu_40_180","chapterId":"ch_work_han_thu_40","textTraditional":"〔八〕　師古曰：「此一利。」","sentenceOrder":180},
  {"id":"s_work_han_thu_40_181","chapterId":"ch_work_han_thu_40","textTraditional":"〔九〕　師古曰：「此二利也。秔謂稻之不粘者也，音庚。」","sentenceOrder":181},
  {"id":"s_work_han_thu_40_182","chapterId":"ch_work_han_thu_40","textTraditional":"〔一０〕師古曰：「罷讀曰疲。」","sentenceOrder":182},
  {"id":"s_work_han_thu_40_183","chapterId":"ch_work_han_thu_40","textTraditional":"若乃繕完故隄，增卑倍薄，勞費無已，數逢其害，此最下策也。","sentenceOrder":183},
  {"id":"s_work_han_thu_40_184","chapterId":"ch_work_han_thu_40","textTraditional":"王莽時，徵能治河者以百數，其大略異者，長水校尉平陵關並〔一〕言：「河決率常於平原、東郡左右，其地形下而土疏惡。聞禹治河時，本空此地，以為水猥，盛則放溢，〔二〕少稍自索，〔三〕雖時易處，猶不能離此。上古難識，近察秦漢以來，河決曹、衛之域，其南北不過百八十里者，可空此地，勿以為官亭民室而已。」大司馬史長安張戎〔四〕言：「水性就下，行疾則自刮除成空而稍深。河水重濁，號為一石水而六斗泥。今西方諸郡，以至京師東行，民皆引河、渭山川水溉田。春夏乾燥，少水時也，故使河流遲，貯淤而稍淺；雨多水暴至，則溢決。而國家數隄塞之，稍益高於平地，猶築垣而居水也。可各順從其性，毋復灌溉，則百川流行，水道自利，無溢決之害矣。」御史臨淮韓牧〔五〕以為「可略於禹貢九河處穿之，縱不能為九，但為四五，宜有益。」大司空掾王橫〔六〕言：「河入勃海，勃海地高於韓牧所欲穿處。往者天嘗連雨，東北風，海水溢，西南出，浸數百里，九河之地已為海所漸矣。〔七〕禹之行河水，本隨西山下東北去。〔八〕周譜云定王五年河徙，〔九〕則今所行非禹之所穿也。又秦攻魏，決河灌其都，決處遂大，不可復補。宜卻徙完平處，更開空，〔一０〕使緣西山足乘高地而東北入海，乃無水災。」沛郡桓譚為司空掾，典其議，為甄豐言：「凡此數者，必有一是。宜詳考驗，皆可豫見，計定然後舉事，費不過數億萬，亦可以事諸浮食無產業民。〔一一〕空居與行役，同當衣食；衣食縣官，而為之作，乃兩便，〔一二〕可以上繼禹功，下除民疾。」王莽時，但崇空語，無施行者。","sentenceOrder":184},
  {"id":"s_work_han_thu_40_185","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「桓譚新論云並字子陽，材智通達也。」","sentenceOrder":185},
  {"id":"s_work_han_thu_40_186","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「猥，多也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_40_187","chapterId":"ch_work_han_thu_40","textTraditional":"〔三〕　師古曰：「索，盡也，音先各反。」","sentenceOrder":187},
  {"id":"s_work_han_thu_40_188","chapterId":"ch_work_han_thu_40","textTraditional":"〔四〕　師古曰：「（雜）〔新〕論云字仲功，習溉灌事也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_40_189","chapterId":"ch_work_han_thu_40","textTraditional":"〔五〕　師古曰：「新論云字子台，善水事。」","sentenceOrder":189},
  {"id":"s_work_han_thu_40_190","chapterId":"ch_work_han_thu_40","textTraditional":"〔六〕　師古曰：「橫字平中，琅邪人。見儒林傳。中讀曰仲。」","sentenceOrder":190},
  {"id":"s_work_han_thu_40_191","chapterId":"ch_work_han_thu_40","textTraditional":"〔七〕　師古曰：「漸，浸也，讀如本字，又音子廉反。」","sentenceOrder":191},
  {"id":"s_work_han_thu_40_192","chapterId":"ch_work_han_thu_40","textTraditional":"〔八〕　師古曰：「行謂通流也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_40_193","chapterId":"ch_work_han_thu_40","textTraditional":"〔九〕　如淳曰：「譜音補，世統譜諜也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_40_194","chapterId":"ch_work_han_thu_40","textTraditional":"〔一０〕師古曰：「空猶穿。」","sentenceOrder":194},
  {"id":"s_work_han_thu_40_195","chapterId":"ch_work_han_thu_40","textTraditional":"〔一一〕師古曰：「事謂役使也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_40_196","chapterId":"ch_work_han_thu_40","textTraditional":"〔一二〕師古曰：「言無產業之人，端居無為，及發行力役，俱須衣食耳。今縣官給其衣食，而使修治河水，是為公私兩便也。」","sentenceOrder":196},
  {"id":"s_work_han_thu_40_197","chapterId":"ch_work_han_thu_40","textTraditional":"贊曰：古人有言：「微禹之功，吾其魚乎！」〔一〕中國川原以百數，莫著於四瀆，而河為宗。孔子曰：「多聞而志之，知之次也。」〔二〕國之利害，故備論其事。","sentenceOrder":197},
  {"id":"s_work_han_thu_40_198","chapterId":"ch_work_han_thu_40","textTraditional":"〔一〕　師古曰：「左氏傳載周大夫劉定公之辭也。言無禹治水之功，則天下之人皆為魚鱉耳。」","sentenceOrder":198},
  {"id":"s_work_han_thu_40_199","chapterId":"ch_work_han_thu_40","textTraditional":"〔二〕　師古曰：「論語稱孔子之言曰『多聞擇其善者而從之，多見而志之，知之次也。』志，記也，字亦作識，音式冀反。」","sentenceOrder":199},
  {"id":"s_work_han_thu_40_200","chapterId":"ch_work_han_thu_40","textTraditional":"校勘記","sentenceOrder":200},
  {"id":"s_work_han_thu_40_201","chapterId":"ch_work_han_thu_40","textTraditional":"一六七七頁一一行　令吾臣皆〔如〕西門豹之為人臣也！　景祐、殿、局本都有「如」字。","sentenceOrder":201},
  {"id":"s_work_han_thu_40_202","chapterId":"ch_work_han_thu_40","textTraditional":"一六七八頁　六行　渠成而用（溉）注填閼之水，　王念孫說此「溉」字涉下「溉」字而衍。","sentenceOrder":202},
  {"id":"s_work_han_thu_40_203","chapterId":"ch_work_han_thu_40","textTraditional":"一六七九頁　四行　彊塞之未必（順）〔應〕天。　景祐、汲古、殿、局本都作「應」。","sentenceOrder":203},
  {"id":"s_work_han_thu_40_204","chapterId":"ch_work_han_thu_40","textTraditional":"一六七九頁一０行　（罷）而渠下民田萬餘頃又可得以溉。此（捐）〔損〕漕省卒，　「罷」字史記無，蘇輿疑衍。「捐」字景祐、殿本都作「損」，史記同。","sentenceOrder":204},
  {"id":"s_work_han_thu_40_205","chapterId":"ch_work_han_thu_40","textTraditional":"一六七九頁一六行　注〔四〕十一字據景祐、殿本補。","sentenceOrder":205},
  {"id":"s_work_han_thu_40_206","chapterId":"ch_work_han_thu_40","textTraditional":"一六八一頁一六行　亦猶山（額）〔領〕象人之頸領。　景祐、殿本都作「領」。王先謙說作「領」是。","sentenceOrder":206},
  {"id":"s_work_han_thu_40_207","chapterId":"ch_work_han_thu_40","textTraditional":"一六八三頁　七行　言不因巡（將）〔狩〕封禪而出，　景祐、殿、局本都作「狩」，此誤。","sentenceOrder":207},
  {"id":"s_work_han_thu_40_208","chapterId":"ch_work_han_thu_40","textTraditional":"一六八四頁　一行　茭，草也，音（茭）〔郊〕。　景祐、殿本都作「郊」，此誤。","sentenceOrder":208},
  {"id":"s_work_han_thu_40_209","chapterId":"ch_work_han_thu_40","textTraditional":"一六八四頁　五行　故言此衛（之人）〔人之〕罪也。　景祐、殿本都作「人之」，是。","sentenceOrder":209},
  {"id":"s_work_han_thu_40_210","chapterId":"ch_work_han_thu_40","textTraditional":"一六八四頁　八行　義與（剚）〔插〕同。　景祐本作「插」。","sentenceOrder":210},
  {"id":"s_work_han_thu_40_211","chapterId":"ch_work_han_thu_40","textTraditional":"一六八七頁一三行　於以分〔流〕殺水力，　景祐、殿本都有「流」字。","sentenceOrder":211},
  {"id":"s_work_han_thu_40_212","chapterId":"ch_work_han_thu_40","textTraditional":"一六九二頁一五行　（住）〔往〕十餘歲更起隄，　王念孫說「住」當作「往」。","sentenceOrder":212},
  {"id":"s_work_han_thu_40_213","chapterId":"ch_work_han_thu_40","textTraditional":"一六九五頁　四行　水留十三日，隄潰（二所），　景祐、殿本無「二所」二字。朱一新說二字涉上文而衍。","sentenceOrder":213},
  {"id":"s_work_han_thu_40_214","chapterId":"ch_work_han_thu_40","textTraditional":"一六九五頁　七行　滎陽漕渠足以（下）〔卜〕之，　景祐、汲古、殿、局本都作「卜」。","sentenceOrder":214},
  {"id":"s_work_han_thu_40_215","chapterId":"ch_work_han_thu_40","textTraditional":"一六九六頁　三行　（涑）〔泲〕水東過礫谿者。　殿本「涑」作「泲」。王先謙說作「泲」是。","sentenceOrder":215},
  {"id":"s_work_han_thu_40_216","chapterId":"ch_work_han_thu_40","textTraditional":"一六九八頁　一行　（雜）〔新〕論云　景祐、殿本都作「新」。","sentenceOrder":216},
  {"id":"s_work_han_thu_41_1","chapterId":"ch_work_han_thu_41","textTraditional":"昔仲尼沒而微言絕，〔一〕七十子喪而大義乖。〔二〕故春秋分為五，〔三〕詩分為四，〔四〕易有數家之傳。戰國從衡，真偽分爭，〔五〕諸子之言紛然殽亂。〔六〕至秦患之，乃燔滅文章，以愚黔首。〔七〕漢興，改秦之敗，大收篇籍，廣開獻書之路。迄孝武世，書缺簡脫，禮壞樂崩，〔八〕聖上喟然而稱曰：〔九〕「朕甚閔焉！」於是建藏書之策，〔一０〕置寫書之官，下及諸子傳說，皆充祕府。至成帝時，以書頗散亡，使謁者陳農求遺書於天下。詔光祿大夫劉向校經傳諸子詩賦，步兵校尉任宏校兵書，太史令尹咸校數術，〔一一〕侍醫李柱國校方技。〔一二〕每一書已，〔一三〕向輒條其篇目，撮其指意，錄而奏之。〔一四〕會向卒，哀帝復使向子侍中奉車都尉歆卒父業。〔一五〕歆於是總群書而奏其七略，故有輯略，〔一六〕有六藝略，〔一七〕有諸子略，有詩賦略，有兵書略，有術數略，有方技略。今刪其要，以備篇籍。〔一八〕","sentenceOrder":1},
  {"id":"s_work_han_thu_41_2","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　李奇曰：「隱微不顯之言也。」師古曰：「精微要妙之言耳。」","sentenceOrder":2},
  {"id":"s_work_han_thu_41_3","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「七十子，謂弟子達者七十二人。舉其成數，故言七十。」","sentenceOrder":3},
  {"id":"s_work_han_thu_41_4","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　韋昭曰：「謂左氏、公羊、穀梁、鄒氏、夾氏也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_41_5","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　韋昭曰：「謂毛氏、齊、魯、韓。」","sentenceOrder":5},
  {"id":"s_work_han_thu_41_6","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「從音子容反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_41_7","chapterId":"ch_work_han_thu_41","textTraditional":"〔六〕　師古曰：「殽，雜也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_41_8","chapterId":"ch_work_han_thu_41","textTraditional":"〔七〕　師古曰：「燔，燒也。秦謂人為黔首，言其頭黑也。燔音扶元反。黔音其炎反，又音琴。」","sentenceOrder":8},
  {"id":"s_work_han_thu_41_9","chapterId":"ch_work_han_thu_41","textTraditional":"〔八〕　師古曰：「編絕散落故簡脫。脫音吐活反。」","sentenceOrder":9},
  {"id":"s_work_han_thu_41_10","chapterId":"ch_work_han_thu_41","textTraditional":"〔九〕　師古曰：「喟，歎息之貌也，音丘位反。」","sentenceOrder":10},
  {"id":"s_work_han_thu_41_11","chapterId":"ch_work_han_thu_41","textTraditional":"〔一０〕如淳曰：「劉歆七略曰『外則有太常、太史、博士之藏，內則有延閣、廣內、祕室之府』。」","sentenceOrder":11},
  {"id":"s_work_han_thu_41_12","chapterId":"ch_work_han_thu_41","textTraditional":"〔一一〕師古曰：「占卜之書。」","sentenceOrder":12},
  {"id":"s_work_han_thu_41_13","chapterId":"ch_work_han_thu_41","textTraditional":"〔一二〕師古曰：「醫藥之書。」","sentenceOrder":13},
  {"id":"s_work_han_thu_41_14","chapterId":"ch_work_han_thu_41","textTraditional":"〔一三〕師古曰：「已，畢也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_41_15","chapterId":"ch_work_han_thu_41","textTraditional":"〔一四〕師古曰：「撮，總取也，音千括反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_41_16","chapterId":"ch_work_han_thu_41","textTraditional":"〔一五〕師古曰：「卒，終也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_41_17","chapterId":"ch_work_han_thu_41","textTraditional":"〔一六〕師古曰：「輯與集同，謂諸書之總要。」","sentenceOrder":17},
  {"id":"s_work_han_thu_41_18","chapterId":"ch_work_han_thu_41","textTraditional":"〔一七〕師古曰：「六藝，六經也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_41_19","chapterId":"ch_work_han_thu_41","textTraditional":"〔一八〕師古曰：「刪去浮冗，取其指要也。其每略所條家及篇數，有與總凡不同者，轉（為）〔寫〕脫誤，年代久遠，無以詳知。」","sentenceOrder":19},
  {"id":"s_work_han_thu_41_20","chapterId":"ch_work_han_thu_41","textTraditional":"易經十二篇，施、孟、梁丘三家。〔一〕易傳周氏二篇。字王孫也。服氏二篇。〔二〕楊氏二篇。名何，字叔元，菑川人。蔡公二篇。衛人，事周王孫。韓氏二篇。名嬰。王氏二篇。名同。丁氏八篇。名寬，字子襄，梁人也。古五子十八篇。自甲子至壬子，說易陰陽。淮南道訓二篇。淮南王安聘明易者九人，號九師（法）〔說〕。古雜八十篇，雜災異三十五篇，神輸五篇，圖一。〔三〕孟氏京房十一篇，災異孟氏京房六十六篇，五鹿充宗略說三篇，京氏段嘉十二篇。〔四〕章句施、孟、梁丘氏各二篇。","sentenceOrder":20},
  {"id":"s_work_han_thu_41_21","chapterId":"ch_work_han_thu_41","textTraditional":"凡易十三家，二百九十四篇。","sentenceOrder":21},
  {"id":"s_work_han_thu_41_22","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「上下經及十翼，故十二篇。」","sentenceOrder":22},
  {"id":"s_work_han_thu_41_23","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「劉向別錄云，服氏，齊人，號服光。」","sentenceOrder":23},
  {"id":"s_work_han_thu_41_24","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「劉向別錄云『神輸者，王道失則災害生，得則四海輸之祥瑞』。」","sentenceOrder":24},
  {"id":"s_work_han_thu_41_25","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　蘇林曰：「東海人，為博士。」晉灼曰：「儒林不見。」師古曰：「蘇說是也。喜即京房所從受易者也，見儒林傳及劉向別錄。」","sentenceOrder":25},
  {"id":"s_work_han_thu_41_26","chapterId":"ch_work_han_thu_41","textTraditional":"易曰：「宓戲氏仰觀象於天，俯觀法於地，觀鳥獸之文，與地之宜，近取諸身，遠取諸物，於是始作八卦，以通神明之德，以類萬物之情。」〔一〕至於殷、周之際，紂在上位，逆天暴物，文王以諸侯順命而行道，天人之占可得而效，於是重易六爻，作上下篇。孔氏為之彖、象、繫辭、文言、序卦之屬十篇。故曰易道深矣，人更三聖，〔二〕世歷三古。〔三〕及秦燔書，而易為筮卜之事，傳者不絕。漢興，田（和）〔何〕傳之。訖于宣、元，有施、孟、梁丘、京氏列於學官，而民間有費、高二家之說。〔四〕劉向以中古文易經校施、孟、梁丘經，〔五〕或脫去「無咎」、「悔亡」，唯費氏經與古文同。","sentenceOrder":26},
  {"id":"s_work_han_thu_41_27","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「下繫之辭也。鳥獸之文，謂其跡在地者。宓讀與伏同。」","sentenceOrder":27},
  {"id":"s_work_han_thu_41_28","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　韋昭曰：「伏羲、文王、孔子。」師古曰：「更，經也，音工衡反。」","sentenceOrder":28},
  {"id":"s_work_han_thu_41_29","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　孟康曰：「易繫辭曰『易之興，其於中古乎？』然則伏羲為上古，文王為中古，孔子為下古。」","sentenceOrder":29},
  {"id":"s_work_han_thu_41_30","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「費音扶味反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_41_31","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「中者，天子之書也。言中，以別於外耳。」","sentenceOrder":31},
  {"id":"s_work_han_thu_41_32","chapterId":"ch_work_han_thu_41","textTraditional":"尚書古文經四十六卷。為五十七篇。〔一〕經二十九卷。大、小夏侯二家。歐陽經（二）〔三〕十二卷。〔二〕傳四十一篇。歐陽章句三十一卷。大、小夏侯章句各二十九卷。大、小夏侯解故二十九篇。歐陽說義二篇。劉向五行傳記十一卷。許商五行傳記一篇。周書七十一篇。周史記。〔三〕議奏四十二篇。宣帝時石渠論。〔四〕","sentenceOrder":32},
  {"id":"s_work_han_thu_41_33","chapterId":"ch_work_han_thu_41","textTraditional":"凡書九家，四百一十二篇。入劉向稽疑一篇。〔五〕","sentenceOrder":33},
  {"id":"s_work_han_thu_41_34","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「孔安國書序云『凡五十九篇，為四十六卷。承詔作傳，引序各冠其篇首，定五十八篇。』鄭玄敘贊云『後又亡其一篇』，故五十七。」","sentenceOrder":34},
  {"id":"s_work_han_thu_41_35","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「此二十九卷，伏生傳授者。」","sentenceOrder":35},
  {"id":"s_work_han_thu_41_36","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「劉向云『周時誥誓號令也，蓋孔子所論百篇之餘也。』今之存者四十五篇矣。」","sentenceOrder":36},
  {"id":"s_work_han_thu_41_37","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　韋昭曰：「閣名也，於此論書。」","sentenceOrder":37},
  {"id":"s_work_han_thu_41_38","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「此凡言入者，謂七略之外班氏新入之也。其云出者與此同。」","sentenceOrder":38},
  {"id":"s_work_han_thu_41_39","chapterId":"ch_work_han_thu_41","textTraditional":"易曰：「河出圖，雒出書，聖人則之。」〔一〕故書之所起遠矣，至孔子篹焉，〔二〕上斷於堯，下訖于秦，凡百篇，而為之序，言其作意。秦燔書禁學，濟南伏生獨壁藏之。漢興亡失，求得二十九篇，以教齊魯之間。訖孝宣世，有歐陽、大小夏侯氏，立於學官。古文尚書者，出孔子壁中。〔三〕武帝末，魯共王壞孔子宅，欲以廣其宮，而得古文尚書及禮記、論語、孝經凡數十篇，皆古字也。共王往入其宅，聞鼓琴瑟鍾磬之音，於是懼，乃止不壞。孔安國者，孔子後也，悉得其書，以考二十九篇，得多十六篇。〔四〕安國獻之。遭巫蠱事，未列于學官。劉向以中古文校歐陽、大小夏侯三家經文，酒誥脫簡一，召誥脫簡二。〔五〕率簡二十五字者，脫亦二十五字，簡二十二字者，脫亦二十二字，文字異者七百有餘，脫字數十。書者，古之號令，號令於眾，其言不立具，則聽受施行者弗曉。古文讀應爾雅，故解古今語而可知也。","sentenceOrder":39},
  {"id":"s_work_han_thu_41_40","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「上繫之辭也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_41_41","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　孟康曰：「篹音撰。」","sentenceOrder":41},
  {"id":"s_work_han_thu_41_42","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「家語云孔騰字子襄，畏秦法峻急，藏尚書、孝經、論語於夫子舊堂壁中，而漢記尹敏傳云孔鮒所藏。二說不同，未知孰是。」","sentenceOrder":42},
  {"id":"s_work_han_thu_41_43","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「壁中書多，以考見行世二十九篇之外，更得十六篇。」","sentenceOrder":43},
  {"id":"s_work_han_thu_41_44","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「召讀曰邵。」","sentenceOrder":44},
  {"id":"s_work_han_thu_41_45","chapterId":"ch_work_han_thu_41","textTraditional":"詩經二十八卷，魯、齊、韓三家。〔一〕魯故二十五卷。〔二〕魯說二十八卷。齊后氏故二十卷。齊孫氏故二十七卷。齊后氏傳三十九卷。齊孫氏傳二十八卷。齊雜記十八卷。韓故三十六卷。韓內傳四卷。韓外傳六卷。韓說四十一卷。毛詩二十九卷。毛詩故訓傳三十卷。","sentenceOrder":45},
  {"id":"s_work_han_thu_41_46","chapterId":"ch_work_han_thu_41","textTraditional":"凡詩六家，四百一十六卷。","sentenceOrder":46},
  {"id":"s_work_han_thu_41_47","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　應劭曰：「申公作魯詩，后蒼作齊詩，韓嬰作韓詩。」","sentenceOrder":47},
  {"id":"s_work_han_thu_41_48","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「故者，通其指義也。它皆類此。今流俗毛詩改故訓傳為詁字，失真耳。」","sentenceOrder":48},
  {"id":"s_work_han_thu_41_49","chapterId":"ch_work_han_thu_41","textTraditional":"書曰：「詩言志，（哥）〔歌〕詠言。」〔一〕故哀樂之心感，而（哥）〔歌〕詠之聲發。誦其言謂之詩，詠其聲謂之（哥）〔歌〕。故古有采詩之官，王者所以觀風俗，知得失，自考正也。孔子純取周詩，上采殷，下取魯，凡三百五篇，遭秦而全者，以其諷誦，不獨在竹帛故也。漢興，魯申公為詩訓故，而齊轅固、燕韓生皆為之傳。或取春秋，采雜說，咸非其本義。與不得已，魯最為近之。〔二〕三家皆列於學官。又有毛公之學，自謂子夏所傳，而河間獻王好之，未得立。","sentenceOrder":49},
  {"id":"s_work_han_thu_41_50","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「虞書舜典之辭也。在心為志，發言為詩。詠者，永也。永，長也，（哥）〔歌〕所以長言之。」","sentenceOrder":50},
  {"id":"s_work_han_thu_41_51","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「與不得已者，言皆不得也。三家（者）〔皆〕不得其真，而魯最近之。」","sentenceOrder":51},
  {"id":"s_work_han_thu_41_52","chapterId":"ch_work_han_thu_41","textTraditional":"禮古經五十六卷，經（七十）〔十七〕篇。后氏、戴氏。記百三十一篇。七十子後學者所記也。明堂陰陽三十三篇。古明堂之遺事。王史氏二十一篇。七十子後學者。〔一〕曲臺后倉九篇。〔二〕中庸說二篇。〔三〕明堂陰陽說五篇。周官經六篇。王莽時劉歆置博士。〔四〕周官傳四篇。軍禮司馬法百五十五篇。古封禪群祀二十二篇。封禪議對十九篇。武帝時也。漢封禪群祀三十六篇。議奏三十八篇。石渠。","sentenceOrder":52},
  {"id":"s_work_han_thu_41_53","chapterId":"ch_work_han_thu_41","textTraditional":"凡禮十三家，五百五十五篇。入司馬法一家，百五十五篇。","sentenceOrder":53},
  {"id":"s_work_han_thu_41_54","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「劉向別錄云六國時人也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_41_55","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　如淳曰：「行禮射於曲臺，后倉為記，故名曰曲臺記。漢官曰大射于曲臺。」晉灼曰：「天子射宮也。西京無太學，於此行禮也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_41_56","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「今禮記有中庸一篇，亦非本禮經，蓋此之流。」","sentenceOrder":56},
  {"id":"s_work_han_thu_41_57","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「即今之周官禮也，亡其冬官，以考工記充之。」","sentenceOrder":57},
  {"id":"s_work_han_thu_41_58","chapterId":"ch_work_han_thu_41","textTraditional":"易曰：「有夫婦父子君臣上下，禮義有所錯。」〔一〕而帝王質文世有損益，至周曲為之防，事為之制，〔二〕故曰：「禮經三百，威儀三千。」〔三〕及周之衰，諸侯將踰法度，惡其害己，皆滅去其籍，自孔子時而不具，至秦大壞。漢興，魯高堂生傳士禮十七篇。訖孝宣世，后倉最明。戴德、戴聖、慶普皆其弟子，三家立於學官。禮古經者，出於魯淹中〔四〕及孔氏，（學七十）〔與十七〕篇文相似，多三十九篇。及明堂陰陽、王史氏記所見，多天子諸侯卿大夫之制，雖不能備，猶瘉倉等推士禮而致於天子之說。〔五〕","sentenceOrder":58},
  {"id":"s_work_han_thu_41_59","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「序卦之辭也。錯，置也，音千故反。」","sentenceOrder":59},
  {"id":"s_work_han_thu_41_60","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「委曲防閑，每事為制也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_41_61","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　韋昭曰：「周禮三百六十官也。三百，舉成數也。」臣瓚曰：「禮經三百，謂冠、婚、吉、凶。周禮三百，是官名也。」師古曰：「禮經三百，韋說是也。威儀三千乃謂冠、婚、吉、凶，蓋儀禮是也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_41_62","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　蘇林曰：「里名也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_41_63","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「瘉與愈同。愈，勝也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_41_64","chapterId":"ch_work_han_thu_41","textTraditional":"樂記二十三篇。樂記二十三篇。王禹記二十四篇。雅歌詩四篇。雅琴趙氏七篇。名定，勃海人，宣帝時丞相魏相所奏。雅琴師氏八篇。名中，東海人，傳言師曠後。雅琴龍氏九十九篇。名德，梁人。〔一〕","sentenceOrder":64},
  {"id":"s_work_han_thu_41_65","chapterId":"ch_work_han_thu_41","textTraditional":"凡樂六家，百六十五篇。出淮南劉向等琴頌七篇。","sentenceOrder":65},
  {"id":"s_work_han_thu_41_66","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「劉向別錄云亦魏相所奏也。與趙定俱召見待詔，後拜為侍郎。」","sentenceOrder":66},
  {"id":"s_work_han_thu_41_67","chapterId":"ch_work_han_thu_41","textTraditional":"易曰：「先王作樂崇德，殷薦之上帝，以享祖考。」〔一〕故自黃帝下至三代，樂各有名。孔子曰：「安上治民，莫善於禮；移風易俗，莫善於樂。」〔二〕二者相與並行。周衰俱壞，樂尤微眇，以音律為節，〔三〕又為鄭衛所亂故無遺法。漢興，制氏以雅樂聲律，世在樂官，頗能紀其鏗鏘鼓舞，而不能言其義。〔四〕六國之君，魏文侯最為好古，孝文時得其樂人竇公，〔五〕獻其書，乃周官大宗伯之大司樂章也。武帝時，河間獻王好儒，與毛生等共采周官及諸子言樂事者，以作樂記，獻八佾之舞，與制氏不相遠。其內史丞王定傳之，以授常山王禹。禹，成帝時為謁者，數言其義，〔六〕獻二十四卷記。劉向校書，得樂記二十三篇，與禹不同，其道浸以益微。〔七〕","sentenceOrder":67},
  {"id":"s_work_han_thu_41_68","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「豫卦象辭也。殷，盛也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_41_69","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「孝經載孔子之言。」","sentenceOrder":69},
  {"id":"s_work_han_thu_41_70","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「眇，細也。言其道精微，節在音律，不可具於書。眇亦讀曰妙。」","sentenceOrder":70},
  {"id":"s_work_han_thu_41_71","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「鏗音初衡反。」","sentenceOrder":71},
  {"id":"s_work_han_thu_41_72","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「桓譚新論云竇公年百八十歲，兩目皆盲，文帝奇之，問曰：『何因至此？』對曰：『臣年十三失明，父母哀其不及眾技，教鼓琴，臣導引，無所服餌。』」","sentenceOrder":72},
  {"id":"s_work_han_thu_41_73","chapterId":"ch_work_han_thu_41","textTraditional":"〔六〕　師古曰：「數音所角反。」","sentenceOrder":73},
  {"id":"s_work_han_thu_41_74","chapterId":"ch_work_han_thu_41","textTraditional":"〔七〕　師古曰：「浸，漸也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_41_75","chapterId":"ch_work_han_thu_41","textTraditional":"春秋古經十二篇，經十一卷。公羊、穀梁二家。左氏傳三十卷。左丘明，魯太史。公羊傳十一卷。公羊子，齊人。〔一〕穀梁傳十一卷。穀梁子，魯人。〔二〕鄒氏傳十一卷。夾氏傳十一卷。有錄無書。〔三〕左氏微二篇。〔四〕鐸氏微三篇。楚太傅鐸椒也。張氏微十篇。虞氏微傳二篇。趙相虞卿。公羊外傳五十篇。穀梁外傳二十篇。公羊章句三十八篇。穀梁章句三十三篇。公羊雜記八十三篇。公羊顏氏記十一篇。公羊董仲舒治獄十六篇。議奏三十九篇。石渠論。國語二十一篇。左丘明著。新國語五十四篇。劉向分國語。世本十五篇。古史官記黃帝以來訖春秋時諸侯大夫。戰國策二十三篇。記春秋後。奏事二十篇。秦時大臣奏事，及刻石名山文也。楚漢春秋九篇。陸賈所記。太史公百三十篇。十篇有錄無書。馮商所續太史公七篇。〔五〕太古以來年紀二篇。漢著記百九十卷。〔六〕漢大年紀五篇。","sentenceOrder":75},
  {"id":"s_work_han_thu_41_76","chapterId":"ch_work_han_thu_41","textTraditional":"凡春秋二十三家，九百四十八篇。省太史公四篇。","sentenceOrder":76},
  {"id":"s_work_han_thu_41_77","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「名高。」","sentenceOrder":77},
  {"id":"s_work_han_thu_41_78","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「名喜。」","sentenceOrder":78},
  {"id":"s_work_han_thu_41_79","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「夾音頰。」","sentenceOrder":79},
  {"id":"s_work_han_thu_41_80","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「微謂釋其微指。」","sentenceOrder":80},
  {"id":"s_work_han_thu_41_81","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　韋昭曰：「馮商受詔續太史公十餘篇，在班彪別錄。商字子高。」師古曰：「七略云商陽陵人，治易，事五鹿充宗，後事劉向，能屬文，後與孟柳俱待詔，頗序列傳，未卒，病死。」","sentenceOrder":81},
  {"id":"s_work_han_thu_41_82","chapterId":"ch_work_han_thu_41","textTraditional":"〔六〕　師古曰：「若今之起居注。」","sentenceOrder":82},
  {"id":"s_work_han_thu_41_83","chapterId":"ch_work_han_thu_41","textTraditional":"古之王者世有史官，君舉必書，所以慎言行，昭法式也。左史記言，右史記事，事為春秋，言為尚書，帝王靡不同之。周室既微，載籍殘缺，仲尼思存前聖之業，乃稱曰：「夏禮吾能言之，杞不足徵也；殷禮吾能言之，宋不足徵也。文獻不足故也，足則吾能徵之矣。」〔一〕以魯周公之國，禮文備物，史官有法，故與左丘明觀其史記，據行事，仍人道，〔二〕因興以立功，就敗以成罰，假日月以定曆數，藉朝聘以正禮樂。有所褒諱貶損，不可書見，口授弟子，弟子退而異言。〔三〕丘明恐弟子各安其意，以失其真，故論本事而作傳，明夫子不以空言說經也。春秋所貶損大人當世君臣，有威權勢力，其事實皆形於傳，是以隱其書而不宣，所以免時難也。及末世口說流行，故有公羊、穀梁、鄒、夾之傳。四家之中，公羊、穀梁立於學官，鄒氏無師，夾氏未有書。","sentenceOrder":83},
  {"id":"s_work_han_thu_41_84","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「論語載孔子之言也。徵，成也。獻，賢也。孔子自謂能言夏、殷之禮，而杞、宋之君文章賢材不足以成之，故我不得成此禮也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_41_85","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「仍亦因也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_41_86","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「謂人執所見，各不同也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_41_87","chapterId":"ch_work_han_thu_41","textTraditional":"論語古二十一篇。出孔子壁中，兩子張。〔一〕齊二十二篇。多問王、知道。〔二〕魯二十篇，傳十九篇。〔三〕齊說二十九篇。魯夏侯說二十一篇。魯安昌侯說二十一篇。〔四〕魯王駿說二十篇。〔五〕燕傳說三卷。議奏十八篇。石渠論。孔子家語二十七卷。〔六〕孔子三朝七篇。〔七〕孔子徒人圖法二卷。","sentenceOrder":87},
  {"id":"s_work_han_thu_41_88","chapterId":"ch_work_han_thu_41","textTraditional":"凡論語十二家，二百二十九篇。","sentenceOrder":88},
  {"id":"s_work_han_thu_41_89","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　如淳曰：「分堯曰篇後子張問『何如可以從政』已下為篇，名曰從政。」","sentenceOrder":89},
  {"id":"s_work_han_thu_41_90","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　如淳曰：「問王、知道，皆篇名也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_41_91","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「解釋論語意者。」","sentenceOrder":91},
  {"id":"s_work_han_thu_41_92","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「張禹也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_41_93","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「王吉子。」","sentenceOrder":93},
  {"id":"s_work_han_thu_41_94","chapterId":"ch_work_han_thu_41","textTraditional":"〔六〕　師古曰：「非今所有家語。」","sentenceOrder":94},
  {"id":"s_work_han_thu_41_95","chapterId":"ch_work_han_thu_41","textTraditional":"〔七〕　師古曰：「今大戴禮有其一篇，蓋孔子對〔魯〕哀公語也。三朝見公，故曰三朝。」","sentenceOrder":95},
  {"id":"s_work_han_thu_41_96","chapterId":"ch_work_han_thu_41","textTraditional":"論語者，孔子應答弟子時人及弟子相與言而接聞於夫子之語也。當時弟子各有所記。夫子既卒，門人相與輯而論篹，故謂之論語〔一〕。漢興，有齊、魯之說。傳齊論者，昌邑中尉王吉、少府宋畸〔二〕、御史大夫貢禹、尚書令五鹿充宗、膠東庸生，唯王陽名家。〔三〕傳魯論語者，常山都尉龔奮、長信少府夏侯勝、丞相韋賢、魯扶卿、前將軍蕭望之、安昌侯張禹，皆名家。張氏最後而行於世。","sentenceOrder":96},
  {"id":"s_work_han_thu_41_97","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「輯與集同。篹與撰同。」","sentenceOrder":97},
  {"id":"s_work_han_thu_41_98","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「畸音居宜反。」","sentenceOrder":98},
  {"id":"s_work_han_thu_41_99","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「王吉字子陽，故謂之王陽。」","sentenceOrder":99},
  {"id":"s_work_han_thu_41_100","chapterId":"ch_work_han_thu_41","textTraditional":"孝經古孔氏一篇。二十二章。〔一〕孝經古孔氏一篇。二十二章。〔一〕孝經一篇。十八章。長孫氏、江氏、后氏、翼氏四家。長孫氏說二篇。江氏說一篇。翼氏說一篇。后氏說一篇。雜傳四篇。安昌侯說一篇。五經雜議十八篇。石渠論。爾雅三卷二十篇。〔二〕小爾雅一篇，古今字一卷。弟子職一篇。〔三〕說三篇。","sentenceOrder":100},
  {"id":"s_work_han_thu_41_101","chapterId":"ch_work_han_thu_41","textTraditional":"凡孝經十一家，五十九篇。","sentenceOrder":101},
  {"id":"s_work_han_thu_41_102","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「劉向云古文字也。庶人章分為二也，曾子敢問章為三，又多一章，凡二十二章。」","sentenceOrder":102},
  {"id":"s_work_han_thu_41_103","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　張晏曰：「爾，近也。雅，正也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_41_104","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　應劭曰：「管仲所作，在管子書。」","sentenceOrder":104},
  {"id":"s_work_han_thu_41_105","chapterId":"ch_work_han_thu_41","textTraditional":"孝經者，孔子為曾子陳孝道也。夫孝，天之經，地之義，民之行也。舉大者言，故曰孝經。漢興，長孫氏、博士江翁、少府后倉、諫大夫翼奉、安昌侯張禹傳之，各自名家。經文皆同，唯孔氏壁中古文為異。「父母生之，續莫大焉」，「故親生之膝下」，諸家說不安處，古文字讀皆異。〔一〕","sentenceOrder":105},
  {"id":"s_work_han_thu_41_106","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　臣瓚曰：「孝經云『續莫大焉』，而諸家之說各不安處之也。」師古曰：「桓譚新論云古孝經千八百七十（一）〔二〕字，今異者四百餘字。」","sentenceOrder":106},
  {"id":"s_work_han_thu_41_107","chapterId":"ch_work_han_thu_41","textTraditional":"史籀十五篇。周宣王太史作大篆十五篇，建武時亡六篇矣。〔一〕八體六技。〔二〕蒼頡一篇。上七章，秦丞相李斯作；爰歷六章，車府令趙高作；博學七章，太史令胡母敬作。凡將一篇。司馬相如作。急就一篇。（成）〔元〕帝時黃門令史游作。元尚一篇。成帝時將作大匠李長作。訓纂一篇。揚雄作。別字十三篇。蒼頡傳一篇。揚雄蒼頡訓纂一篇。杜林蒼頡訓纂一篇。杜林蒼頡故一篇。","sentenceOrder":107},
  {"id":"s_work_han_thu_41_108","chapterId":"ch_work_han_thu_41","textTraditional":"凡小學十家，四十五篇。入揚雄、杜林二家二篇。","sentenceOrder":108},
  {"id":"s_work_han_thu_41_109","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「籀音冑。」","sentenceOrder":109},
  {"id":"s_work_han_thu_41_110","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　韋昭曰：「八體，一曰大篆，二曰小篆，三曰刻符，四曰蟲書，五曰摹印，六曰署書，七曰殳書，八曰隸書。」","sentenceOrder":110},
  {"id":"s_work_han_thu_41_111","chapterId":"ch_work_han_thu_41","textTraditional":"易曰：「上古結繩以治，後世聖人易之以書契，百官以治，萬民以察，蓋取諸夬。」〔一〕「夬，揚於王庭」，〔二〕言其宣揚於王者朝廷，其用最大也。古者八歲入小學，故周官保氏掌養國子，教之六書，〔三〕謂象形、象事、象意、象聲、轉注、假借，造字之本也。〔四〕漢興，蕭何草律，〔五〕亦著其法，曰：「太史試學童，能諷書九千字以上，乃得為史。又以六體試之，課最者以為尚書御史史書令史。〔六〕吏民上書，字或不正，輒舉劾。」六體者，古文、奇字、篆書、隸書、繆篆、蟲書，〔七〕皆所以通知古今文字，摹印章，書幡信也。古制，書必同文，不知則闕，問諸故老，至於衰世，是非無正，人用其私。〔八〕故孔子曰：「吾猶及史之闕文也，今亡矣夫！」〔九〕蓋傷其浸不正。〔一０〕史籀篇者，周時史官教學童書也，與孔氏壁中古文異體。蒼頡七章者，秦丞相李斯所作也；爰歷六章者，車府令趙高所作也；博學七章者，太史令胡母敬所作也：文字多取史籀篇，而篆體復頗異，所謂秦篆者也。是時始造隸書矣，起於官獄多事，苟趨省易，〔一一〕施之於徒隸也。漢（書）〔興〕，閭里書師合蒼頡、爰歷、博學三篇，斷六十字以為一章，凡五十五章，并為蒼頡篇。〔一二〕武帝時司馬相如作凡將篇，無復字。〔一三〕元帝時黃門令史游作急就篇，成帝時將作大匠李長作元尚篇，皆蒼頡中正字也。凡將則頗有出矣。至元始中，徵天下通小學者以百數，各令記字於庭中。揚雄取其有用者以作訓纂篇，順續蒼頡，又易蒼頡中重復之字，凡八十九章。臣復續揚雄作十（二）〔三〕章，〔一四〕凡一百二章，無復字，六藝群書所載略備矣。蒼頡多古字，俗師失其讀，宣帝時徵齊人能正讀者，張敞從受之，傳至外孫之子杜林，為作訓故，并列焉。","sentenceOrder":111},
  {"id":"s_work_han_thu_41_112","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「下繫之辭。」","sentenceOrder":112},
  {"id":"s_work_han_thu_41_113","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「夬卦之辭。」","sentenceOrder":113},
  {"id":"s_work_han_thu_41_114","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「保氏，地官之屬也。保，安也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_41_115","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「象形，謂畫成其物，隨體詰屈，日、月是也。象事，即指事也，謂視而可識，察而見意，上、下是也。象意，即會意也，謂比類合誼，以見指撝，武、信是也。象聲，即形聲，謂以事為名，取譬相成，江、河是也。轉注，謂建類一首，同意相受，考、老是也。假借，謂本無其字，依聲託事，令、長是也。文字之義，總歸六書，故曰立字之本也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_41_116","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「草，創造之。」","sentenceOrder":116},
  {"id":"s_work_han_thu_41_117","chapterId":"ch_work_han_thu_41","textTraditional":"〔六〕　韋昭曰：「若今尚書蘭臺令史也。」臣瓚曰：「史書，今之太史書。」","sentenceOrder":117},
  {"id":"s_work_han_thu_41_118","chapterId":"ch_work_han_thu_41","textTraditional":"〔七〕　師古曰：「古文謂孔子壁中書。奇字即古文而異者也。篆書謂小篆，蓋秦始皇使程邈所作也。隸書亦程邈所獻，主於徒隸，從簡易也。繆篆謂其文屈曲纏繞，所以摹印章也。蟲書謂為蟲鳥之形，所以書幡信也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_41_119","chapterId":"ch_work_han_thu_41","textTraditional":"〔八〕　師古曰：「各任私意而為字。」","sentenceOrder":119},
  {"id":"s_work_han_thu_41_120","chapterId":"ch_work_han_thu_41","textTraditional":"〔九〕　師古曰：「論語載孔子之（書）〔言〕，謂文字有疑，則當闕而不說。孔子自言，我初涉學，尚見闕文，今則皆無，任意改（治）〔作〕也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_41_121","chapterId":"ch_work_han_thu_41","textTraditional":"〔一０〕師古曰：「浸，漸也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_41_122","chapterId":"ch_work_han_thu_41","textTraditional":"〔一一〕師古曰：「趨讀曰趣，謂趣向之也。易音弋豉反。」","sentenceOrder":122},
  {"id":"s_work_han_thu_41_123","chapterId":"ch_work_han_thu_41","textTraditional":"〔一二〕師古曰：「并，合也，總合以為蒼頡篇也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_41_124","chapterId":"ch_work_han_thu_41","textTraditional":"〔一三〕師古曰：「復，重也，音扶目反。後皆類此。」","sentenceOrder":124},
  {"id":"s_work_han_thu_41_125","chapterId":"ch_work_han_thu_41","textTraditional":"〔一四〕韋昭曰：「臣，班固自謂也。作十三章，後人不別，疑在蒼頡下篇三十四章中。」","sentenceOrder":125},
  {"id":"s_work_han_thu_41_126","chapterId":"ch_work_han_thu_41","textTraditional":"凡六藝一百三家，三千一百二十三篇。入三家，一百五十九篇；出重十一篇。","sentenceOrder":126},
  {"id":"s_work_han_thu_41_127","chapterId":"ch_work_han_thu_41","textTraditional":"六藝之文：樂以和神，仁之表也；詩以正言，義之用也；禮以明體，明者著見，故無訓也；書以廣聽，知之術也；春秋以斷事，信之符也。五者，蓋五常之道，相須而備，而易為之原。故曰「易不可見，則乾坤或幾乎息矣」，〔一〕言與天地為終始也。至於五學，世有變改，猶五行之更用事焉。〔二〕古之學者耕且養，三年而通一藝，存其大體，玩經文而已，是故用日少而畜德多，〔三〕三十而五經立也。後世經傳既已乖離，博學者又不思多聞闕疑之義，〔四〕而務碎義逃難，便辭巧說，破壞形體；〔五〕說五字之文，至於二三萬言。〔六〕後進彌以馳逐，故幼童而守一藝，白首而後能言；安其所習，毀所不見，〔七〕終以自蔽。此學者之大患也。序六藝為九種。","sentenceOrder":127},
  {"id":"s_work_han_thu_41_128","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　蘇林曰：「不能見易意，則乾坤近於滅息也。」師古曰：「此上繫之辭也。幾，近也，音鉅依反。」","sentenceOrder":128},
  {"id":"s_work_han_thu_41_129","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「更，互也，音工衡反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_41_130","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「畜讀曰蓄。蓄，聚也。易大畜卦象辭曰：『君子以多識前言往行，以畜其德。』」","sentenceOrder":130},
  {"id":"s_work_han_thu_41_131","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「論語稱孔子曰『多聞闕疑，慎言其餘，則寡尤』。言為學之道，務在多聞，疑則闕之，慎於言語，則少過也，故志引之。」","sentenceOrder":131},
  {"id":"s_work_han_thu_41_132","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「苟為僻碎之義，以避它人之攻難者，故為便辭巧說，以析破文字之形體也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_41_133","chapterId":"ch_work_han_thu_41","textTraditional":"〔六〕　師古曰：「言其煩妄也。桓譚新論云秦近君能說堯典，篇目兩字之說至十餘萬言，但說『曰若稽古』三萬言。」","sentenceOrder":133},
  {"id":"s_work_han_thu_41_134","chapterId":"ch_work_han_thu_41","textTraditional":"〔七〕　師古曰：「己所常習則保安之，未嘗所見者則妄毀誹。」","sentenceOrder":134},
  {"id":"s_work_han_thu_41_135","chapterId":"ch_work_han_thu_41","textTraditional":"晏子八篇。名嬰，諡平仲，相齊景公，孔子稱善與人交，有列傳。〔一〕子思二十三篇。名伋，孔子孫，為魯繆公師。曾子十八篇。名參，孔子弟子。漆雕子十三篇。孔子弟子漆雕啟後。宓子十六篇。名不齊，字子賤，孔子弟子。〔二〕景子三篇。說宓子語，似其弟子。世子二十一篇。名碩，陳人也，七十子之弟子。魏文侯六篇。李克七篇。子夏弟子，為魏文侯相。公孫尼子二十八篇。七十子之弟子。孟子十一篇。名軻，鄒人，子思弟子，有列傳。〔三〕孫卿子三十三篇。名況，趙人，為齊稷下祭酒，有列傳。〔四〕羋子十八篇。名嬰，齊人，七十子之後。〔五〕內業十五篇。不知作書者。周史六弢六篇。惠、襄之間，或曰顯王時，或曰孔子問焉。〔六〕周政六篇。周時法度政教。周法九篇。法天地，立百官。河間周制十八篇。似河間獻王所述也。讕言十（一）篇。不知作者，陳人君法度。〔七〕功議四篇。不知作者，論功德事。甯越一篇。中牟人，為周威王師。王孫子一篇。一曰巧心。公孫固一篇。十八章。齊閔王失國，（閒）〔問〕之，固因為陳古今成敗也。李氏春秋二篇。羊子四篇。百章。故秦博士。董子一篇。名無心，難墨子。（侯）〔俟〕子一篇。〔八〕徐子四十二篇。宋外黃人。魯仲連子十四篇。有列傳。平原君七篇。朱建也。虞氏春秋十五篇。虞卿也。高祖傳十三篇。高祖與大臣述古語及詔策也。陸賈二十三篇。劉敬三篇。孝文傳十一篇。文帝所稱及詔策。賈山八篇。太常蓼侯孔臧十篇。父聚，高祖時以功臣封，臧嗣爵。賈誼五十八篇。河間獻王對上下三雍宮三篇。董仲舒百二十三篇。兒寬九篇。公孫弘十篇。終軍八篇。吾丘壽王六篇。虞丘說一篇。難孫卿也。莊助四篇。臣彭四篇。鉤盾冗從李步昌八篇。宣帝時數言事。儒家言十八篇。不知作者。桓寬鹽鐵論六十篇。〔九〕劉向所序六十七篇。新序、說苑、世說、列女傳頌圖也。揚雄所序三十八篇。太玄十九，法言十三，樂四，箴二。","sentenceOrder":135},
  {"id":"s_work_han_thu_41_136","chapterId":"ch_work_han_thu_41","textTraditional":"右儒五十三家，八百三十六篇。入揚雄一家〔三〕十八篇。","sentenceOrder":136},
  {"id":"s_work_han_thu_41_137","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「有列傳者，謂太史公書。」","sentenceOrder":137},
  {"id":"s_work_han_thu_41_138","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「宓讀與伏同。」","sentenceOrder":138},
  {"id":"s_work_han_thu_41_139","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「聖證論云軻字子車，而此志無字，未詳其所得。」","sentenceOrder":139},
  {"id":"s_work_han_thu_41_140","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「本曰荀卿，避宣帝諱，故曰孫。」","sentenceOrder":140},
  {"id":"s_work_han_thu_41_141","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「羋音弭。」","sentenceOrder":141},
  {"id":"s_work_han_thu_41_142","chapterId":"ch_work_han_thu_41","textTraditional":"〔六〕　師古曰：「即今之六韜也，蓋言取天下及軍旅之事。弢字與韜同也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_41_143","chapterId":"ch_work_han_thu_41","textTraditional":"〔七〕　如淳曰：「讕音粲爛。」師古曰：「說者引孔子家語云孔穿所造，非也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_41_144","chapterId":"ch_work_han_thu_41","textTraditional":"〔八〕　李奇曰：「或作侔子。」","sentenceOrder":144},
  {"id":"s_work_han_thu_41_145","chapterId":"ch_work_han_thu_41","textTraditional":"〔九〕　師古曰：「寬字次公，汝南人也。孝昭帝時，丞相御史與諸賢良文學論鹽鐵事，寬撰次之。」","sentenceOrder":145},
  {"id":"s_work_han_thu_41_146","chapterId":"ch_work_han_thu_41","textTraditional":"儒家者流，蓋出於司徒之官，助人君順陰陽明教化者也。游文於六經之中，留意於仁義之際，祖述堯舜，憲章文武，宗師仲尼，以重其言，〔一〕於道最為高。孔子曰：「如有所譽，其有所試。」〔二〕唐虞之隆，殷周之盛，仲尼之業，已試之效者也。然惑者既失精微，而辟者又隨時抑揚，違離道本，〔三〕苟以譁眾取寵。〔四〕後進循之，是以五經乖析，儒學浸衰，此辟儒之患。〔五〕","sentenceOrder":146},
  {"id":"s_work_han_thu_41_147","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「祖，始也。述，修也。憲，法也。章，明也。宗，尊也。言以堯舜為本始而遵修之，以文王、武王為明法，又師尊仲尼之道。」","sentenceOrder":147},
  {"id":"s_work_han_thu_41_148","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「論語載孔子之言也。言於人有所稱譽者，輒試以事，取其實效也。譽音弋於反。」","sentenceOrder":148},
  {"id":"s_work_han_thu_41_149","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「辟讀曰僻。」","sentenceOrder":149},
  {"id":"s_work_han_thu_41_150","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「譁，諠也。寵，尊也。譁音呼華反。」","sentenceOrder":150},
  {"id":"s_work_han_thu_41_151","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「浸，漸也。辟讀曰僻。」","sentenceOrder":151},
  {"id":"s_work_han_thu_41_152","chapterId":"ch_work_han_thu_41","textTraditional":"伊尹五十一篇。湯相。","sentenceOrder":152},
  {"id":"s_work_han_thu_41_153","chapterId":"ch_work_han_thu_41","textTraditional":"太公二百三十七篇。呂望為周師尚父，本有道者。或有近世又以為太公術者所增加也。〔一〕謀八十一篇，言七十一篇，兵八十五篇。","sentenceOrder":153},
  {"id":"s_work_han_thu_41_154","chapterId":"ch_work_han_thu_41","textTraditional":"辛甲二十九篇。紂臣，七十五諫而去，周封之。鬻子二十二篇。名熊，為周師，自文王以下問焉，周封為楚祖。〔二〕筦子八十六篇。名夷吾，相齊桓公，九合諸侯，不以兵車也，有列傳。〔三〕老子鄰氏經傳四篇。姓李，名耳，鄰氏傳其學。老子傅氏經說三十七篇。述老子學。老子徐氏經說六篇。字少季，臨淮人，傳老子。劉向說老子四篇。文子九篇。老子弟子，與孔子並時，而稱周平王問，似依託者也。蜎子十三篇。名淵，楚人，老子弟子。〔四〕關尹子九篇。名喜，為關吏，老子過關，喜去吏而從之。莊子五十二篇。名周，宋人。列子八篇。名圄寇，先莊子，莊子稱之。老成子十八篇。長盧子九篇。〔楚人〕。王狄子一篇。公子牟四篇。魏之公子也，先莊子，莊子稱之。田子二十五篇。名駢，齊人，游稷下，號天口駢。〔五〕老萊子十六篇。楚人，與孔子同時。黔婁子四篇。齊隱士，守道不詘，威王下之。〔六〕宮孫子二篇。〔七〕鶡冠子一篇。楚人，居深山，以鶡為冠。〔八〕周訓十四篇。〔九〕黃帝四經四篇。黃帝銘六篇。黃帝君臣十篇。起六國時，與老子相似也。雜黃帝五十八篇。六國時賢者所作。力牧二十二篇。六國時所作，託之力牧。力牧，黃帝相。孫子十六篇。六國時。捷子二篇。齊人，武帝時說。曹羽二篇。楚人，武帝時說於齊王。郎中嬰齊十二篇。武帝時。〔一０〕臣君子二篇。蜀人。鄭長者一篇。六國時。先韓子，韓子稱之。〔一一〕楚子三篇。道家言二篇。近世，不知作者。","sentenceOrder":154},
  {"id":"s_work_han_thu_41_155","chapterId":"ch_work_han_thu_41","textTraditional":"右道三十七家，九百九十三篇。","sentenceOrder":155},
  {"id":"s_work_han_thu_41_156","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「父讀曰甫也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_41_157","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「鬻音弋六反。」","sentenceOrder":157},
  {"id":"s_work_han_thu_41_158","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「筦讀與管同。」","sentenceOrder":158},
  {"id":"s_work_han_thu_41_159","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「蜎，姓也。音一元反。」","sentenceOrder":159},
  {"id":"s_work_han_thu_41_160","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「駢音步田反。」","sentenceOrder":160},
  {"id":"s_work_han_thu_41_161","chapterId":"ch_work_han_thu_41","textTraditional":"〔六〕　師古曰：「黔音其炎反。下音胡稼反。」","sentenceOrder":161},
  {"id":"s_work_han_thu_41_162","chapterId":"ch_work_han_thu_41","textTraditional":"〔七〕　師古曰：「宮孫，姓也，不知名。」","sentenceOrder":162},
  {"id":"s_work_han_thu_41_163","chapterId":"ch_work_han_thu_41","textTraditional":"〔八〕　師古曰：「以鶡鳥羽為冠。」","sentenceOrder":163},
  {"id":"s_work_han_thu_41_164","chapterId":"ch_work_han_thu_41","textTraditional":"〔九〕　師古曰：「劉向別錄云人間小書，其言俗薄。」","sentenceOrder":164},
  {"id":"s_work_han_thu_41_165","chapterId":"ch_work_han_thu_41","textTraditional":"〔一０〕師古曰：「劉向云故待詔，不知其姓，數從游觀，名能為文。」","sentenceOrder":165},
  {"id":"s_work_han_thu_41_166","chapterId":"ch_work_han_thu_41","textTraditional":"〔一一〕師古曰：「別錄云鄭人，不知姓名。」","sentenceOrder":166},
  {"id":"s_work_han_thu_41_167","chapterId":"ch_work_han_thu_41","textTraditional":"道家者流，蓋出於史官，歷記成敗存亡禍福古今之道，然後知秉要執本，清虛以自守，卑弱以自持，此君人南面之術也。合於堯之克攘，〔一〕易之嗛嗛，一謙而四益，此其所長也。〔二〕及放者為之，則欲絕去禮學，兼棄仁義，〔三〕曰獨任清虛可以為治。","sentenceOrder":167},
  {"id":"s_work_han_thu_41_168","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「虞書堯典稱堯之德曰『允恭克讓』，言其信恭能讓也，故志引之云。攘，古讓字。」","sentenceOrder":168},
  {"id":"s_work_han_thu_41_169","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「四益，謂天道虧盈而益謙，地道變盈而流謙，鬼神害盈而福謙，人道惡盈而好謙也。此謙卦彖辭。嗛字與謙同。」","sentenceOrder":169},
  {"id":"s_work_han_thu_41_170","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「放，蕩也。」","sentenceOrder":170},
  {"id":"s_work_han_thu_41_171","chapterId":"ch_work_han_thu_41","textTraditional":"宋司星子韋三篇。景公之史。公檮生終始十四篇。傳鄒奭始終書。〔一〕公孫發二十二篇。六國時。鄒子四十九篇。名衍，齊人，為燕昭王師，居稷下，號談天衍。鄒子終始五十六篇。〔二〕乘丘子五篇。六國時。杜文公五篇。六國時。〔三〕黃帝泰素二十篇。六國時韓諸公子所作。〔四〕南公三十一篇。六國時。容成子十四篇。張蒼十六篇。丞相北平侯。鄒奭子十二篇。齊人，號曰雕龍奭。〔五〕閭丘子十三篇。名快，魏人，在南公前。馮促十三篇。鄭人。將鉅子五篇。六國時。先南公，南公稱之。五曹官制五篇。漢制，似賈誼所條。周伯十一篇。齊人，六國時。衛侯官十二篇。近世，不知作者。于長天下忠臣九篇。平陰人，近世。〔六〕公孫渾邪十五篇。平曲侯。雜陰陽三十八篇。不知作者。","sentenceOrder":171},
  {"id":"s_work_han_thu_41_172","chapterId":"ch_work_han_thu_41","textTraditional":"右陰陽二十一家，三百六十九篇。","sentenceOrder":172},
  {"id":"s_work_han_thu_41_173","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「檮音疇，其字從木。」","sentenceOrder":173},
  {"id":"s_work_han_thu_41_174","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「亦鄒衍所說。」","sentenceOrder":174},
  {"id":"s_work_han_thu_41_175","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「劉向別錄云韓人也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_41_176","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「劉向別錄云或言韓諸公孫之所作也。言陰陽五行，以為黃帝之道也，故曰泰素。」","sentenceOrder":176},
  {"id":"s_work_han_thu_41_177","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「奭音試亦反。」","sentenceOrder":177},
  {"id":"s_work_han_thu_41_178","chapterId":"ch_work_han_thu_41","textTraditional":"〔六〕　師古曰：「劉向別錄云傳天下忠臣。」","sentenceOrder":178},
  {"id":"s_work_han_thu_41_179","chapterId":"ch_work_han_thu_41","textTraditional":"陰陽家者流，蓋出於羲和之官，敬順昊天，歷象日月星辰，敬授民時，此其所長也。及拘者為之，則牽於禁忌，泥於小數，〔一〕舍人事而任鬼神。〔二〕","sentenceOrder":179},
  {"id":"s_work_han_thu_41_180","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「泥，滯也，音乃計反。」","sentenceOrder":180},
  {"id":"s_work_han_thu_41_181","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「舍，廢也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_41_182","chapterId":"ch_work_han_thu_41","textTraditional":"李子三十二篇。名悝，相魏文侯，富國彊兵。商君二十九篇。名鞅，姬姓，衛後也，相秦孝公，有列傳。申子六篇。名不害，京人，相韓昭侯，終其身諸侯不敢侵韓。〔一〕處子九篇。〔二〕慎子四十二篇。名到，先申韓，申韓稱之。韓子五十五篇。名非，韓諸公子，使秦，李斯害而殺之。游棣子一篇。晁錯三十一篇。〔三〕燕十事十篇。不知作者。法家言二篇。不知作者。","sentenceOrder":182},
  {"id":"s_work_han_thu_41_183","chapterId":"ch_work_han_thu_41","textTraditional":"右法十家，二百一十七篇。","sentenceOrder":183},
  {"id":"s_work_han_thu_41_184","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「京，河南京縣。」","sentenceOrder":184},
  {"id":"s_work_han_thu_41_185","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「史記云趙有處子。」","sentenceOrder":185},
  {"id":"s_work_han_thu_41_186","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「棣音徒計反。」","sentenceOrder":186},
  {"id":"s_work_han_thu_41_187","chapterId":"ch_work_han_thu_41","textTraditional":"法家者流，蓋出於理官，信賞必罰，以輔禮制。易曰「先王以明罰飭法」，〔一〕此其所長也。及刻者為之，則無教化，去仁愛，專任刑法而欲以致治，至於殘害至親，傷恩薄厚。〔二〕","sentenceOrder":187},
  {"id":"s_work_han_thu_41_188","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「噬嗑之象辭也。飭，整也，讀與敕同。」","sentenceOrder":188},
  {"id":"s_work_han_thu_41_189","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「薄厚者，變厚為薄。」","sentenceOrder":189},
  {"id":"s_work_han_thu_41_190","chapterId":"ch_work_han_thu_41","textTraditional":"鄧析二篇。鄭人，與子產並時。〔一〕尹文子一篇。說齊宣王。先公孫龍。〔二〕公孫龍子十四篇。趙人。〔三〕成公生五篇。與黃公等同時。〔四〕惠子一篇。名施，與莊子並時。黃公四篇。名疵，為秦博士，作歌詩，在秦時歌詩中。〔五〕毛公九篇。趙人，與公孫龍等並游平原君趙勝家。〔六〕","sentenceOrder":190},
  {"id":"s_work_han_thu_41_191","chapterId":"ch_work_han_thu_41","textTraditional":"右名七家，三十六篇。","sentenceOrder":191},
  {"id":"s_work_han_thu_41_192","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「列子及孫卿並云子產殺鄧析。據左傳，昭公二十年子產卒，定公九年駟歂殺鄧析而用其竹刑，則非子產所殺也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_41_193","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「劉向云與宋鈃俱游稷下。鈃音形。」","sentenceOrder":193},
  {"id":"s_work_han_thu_41_194","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「即為堅白之辯者。」","sentenceOrder":194},
  {"id":"s_work_han_thu_41_195","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「姓成公。劉向云與李斯子由同時。由為三川守，成公生游談不仕。」","sentenceOrder":195},
  {"id":"s_work_han_thu_41_196","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「疵音才斯反。」","sentenceOrder":196},
  {"id":"s_work_han_thu_41_197","chapterId":"ch_work_han_thu_41","textTraditional":"〔六〕　師古曰：「劉向別錄云論堅白同異，以為可以治天下。此蓋史記所云『藏於博徒』者。」","sentenceOrder":197},
  {"id":"s_work_han_thu_41_198","chapterId":"ch_work_han_thu_41","textTraditional":"名家者流，蓋出於禮官。古者名位不同，禮亦異數。孔子曰：「必也正名乎！名不正則言不順，言不順則事不成。」〔一〕此其所長也。及譥者為之，〔二〕則苟鉤（鈲）〔鋠〕析亂而已。〔三〕","sentenceOrder":198},
  {"id":"s_work_han_thu_41_199","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「論語載孔子之言也。言欲為政，必先正其名。」","sentenceOrder":199},
  {"id":"s_work_han_thu_41_200","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　晉灼曰：「譥，許也。」師古曰：「譥音工釣反。」","sentenceOrder":200},
  {"id":"s_work_han_thu_41_201","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「（鈲）〔鋠〕，破也，音普革反，又音普狄反。」","sentenceOrder":201},
  {"id":"s_work_han_thu_41_202","chapterId":"ch_work_han_thu_41","textTraditional":"尹佚二篇。周臣，在成、康時也。田俅子三篇。先韓子。〔一〕我子一篇。〔二〕隨巢子六篇。墨翟弟子。胡非子三篇。墨翟弟子。墨子七十一篇。名翟，為宋大夫，在孔子後。","sentenceOrder":202},
  {"id":"s_work_han_thu_41_203","chapterId":"ch_work_han_thu_41","textTraditional":"右墨六家，八十六篇。","sentenceOrder":203},
  {"id":"s_work_han_thu_41_204","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　蘇林曰：「俅音仇。」","sentenceOrder":204},
  {"id":"s_work_han_thu_41_205","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「劉向別錄云為墨子之學。」","sentenceOrder":205},
  {"id":"s_work_han_thu_41_206","chapterId":"ch_work_han_thu_41","textTraditional":"墨家者流，蓋出於清廟之守。茅屋采椽，〔一〕是以貴儉；養三老五更，是以兼愛；選士大射，是以上賢；宗祀嚴父，是以右鬼〔二〕；順四時而行，是以非命；〔三〕以孝視天下，是以上同：〔四〕此其所長也。及蔽者為之，見儉之利，因以非禮，推兼愛之意，而不知別親疏。","sentenceOrder":206},
  {"id":"s_work_han_thu_41_207","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「采，柞木也，字作棌，本從木。以茅覆屋，以棌為椽，言其質素也。采音千在反。」","sentenceOrder":207},
  {"id":"s_work_han_thu_41_208","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　如淳曰：「右鬼，謂信鬼神。若杜伯射宣王，是親鬼而右之。」師古曰：「右猶尊尚也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_41_209","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　蘇林曰：「非有命者，言儒者執有命，而反勸人修德積善，政教與行相反，故譏之也。」如淳曰：「言無吉凶之命，但有賢不肖（之）善惡。」","sentenceOrder":209},
  {"id":"s_work_han_thu_41_210","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　如淳曰：「言皆同，可以治也。」師古曰：「墨子有節用、兼愛、上賢、明鬼神、非命、上同等諸篇，故志歷序其本意也。視讀曰示。」","sentenceOrder":210},
  {"id":"s_work_han_thu_41_211","chapterId":"ch_work_han_thu_41","textTraditional":"蘇子三十一篇。名秦，有列傳。張子十篇。名儀，有列傳。龐煖二篇。為燕將。〔一〕闕子一篇。國筮子十七篇。秦零陵令信一篇。難秦相李斯。蒯子五篇。名通。鄒陽七篇。主父偃二十八篇。徐樂一篇。莊安一篇。待詔金馬聊蒼三篇。趙人，武帝時。〔二〕","sentenceOrder":211},
  {"id":"s_work_han_thu_41_212","chapterId":"ch_work_han_thu_41","textTraditional":"右從橫十二家，百七篇。","sentenceOrder":212},
  {"id":"s_work_han_thu_41_213","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「煖音許遠反。」","sentenceOrder":213},
  {"id":"s_work_han_thu_41_214","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「嚴助傳作膠蒼，而此志作聊。志傳不同，未知孰是。」","sentenceOrder":214},
  {"id":"s_work_han_thu_41_215","chapterId":"ch_work_han_thu_41","textTraditional":"從橫家者流，蓋出於行人之官。孔子曰：「誦詩三百，使於四方，不能專對，雖多亦奚以為？」〔一〕又曰：「使乎，使乎！」〔二〕言其當權事制宜，受命而不受辭，此其所長也。及邪人為之，則上詐諼而棄其信。〔三〕","sentenceOrder":215},
  {"id":"s_work_han_thu_41_216","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「論語載孔子之言也。謂人不達於事，誦詩雖多，亦無所用。」","sentenceOrder":216},
  {"id":"s_work_han_thu_41_217","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「亦論語載孔子之言，歎使者之難其人。」","sentenceOrder":217},
  {"id":"s_work_han_thu_41_218","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「諼，詐言也，音許遠反。」","sentenceOrder":218},
  {"id":"s_work_han_thu_41_219","chapterId":"ch_work_han_thu_41","textTraditional":"孔甲盤盂二十六篇。黃帝之史，或曰夏帝孔甲，似皆非。大〈伞，中“十改巾”〉三十七篇。傳言禹所作，其文似後世語。〔一〕五子胥八篇。名員，春秋時為吳將，忠直遇讒死。子晚子三十五篇。齊人，好議兵，與司馬法相似。由余三篇。戎人，秦穆公聘以為大夫。尉繚（子）二十九篇。六國時。〔二〕尸子二十篇。名佼，魯人，秦相商君師之。鞅死，佼逃入蜀。〔三〕呂氏春秋二十六篇。秦相呂不韋輯智略士作。淮南內二十一篇。王安。淮南外三十三篇。〔四〕東方朔二十篇。伯象先生一篇。〔五〕荊軻論五篇。軻為燕刺秦王，不成而死，司馬相如等論之。吳子一篇。公孫尼一篇。博士臣賢對一篇。漢世，難韓子、商君。臣說三篇。武帝時（所）作賦。〔六〕解子簿書三十五篇。推雜書八十七篇。雜家言一篇。王伯，不知作者。〔七〕","sentenceOrder":219},
  {"id":"s_work_han_thu_41_220","chapterId":"ch_work_han_thu_41","textTraditional":"右雜二十家，四百三篇。入兵法。","sentenceOrder":220},
  {"id":"s_work_han_thu_41_221","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「〈伞，中“十改巾”〉，古禹字。」","sentenceOrder":221},
  {"id":"s_work_han_thu_41_222","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「尉，姓；繚，名也。音了，又音聊。劉向別錄云繚為商君學。」","sentenceOrder":222},
  {"id":"s_work_han_thu_41_223","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「佼音絞。」","sentenceOrder":223},
  {"id":"s_work_han_thu_41_224","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「內篇論道，外篇雜說。」","sentenceOrder":224},
  {"id":"s_work_han_thu_41_225","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　應劭曰：「蓋隱者也，故公孫敖難以無益世主之治。」","sentenceOrder":225},
  {"id":"s_work_han_thu_41_226","chapterId":"ch_work_han_thu_41","textTraditional":"〔六〕　師古曰：「說者，其人名，讀曰悅。」","sentenceOrder":226},
  {"id":"s_work_han_thu_41_227","chapterId":"ch_work_han_thu_41","textTraditional":"〔七〕　師古曰：「言伯王之道。伯讀曰霸。」","sentenceOrder":227},
  {"id":"s_work_han_thu_41_228","chapterId":"ch_work_han_thu_41","textTraditional":"雜家者流，蓋出於議官。兼儒、墨，合名、法，知國體之有此，〔一〕見王治之無不貫，〔二〕此其所長也。及盪者為之，則漫羨而無所歸心。〔三〕","sentenceOrder":228},
  {"id":"s_work_han_thu_41_229","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「治國之體，亦當有此雜家之說。」","sentenceOrder":229},
  {"id":"s_work_han_thu_41_230","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「王者之治，於百家之道無不貫綜。」","sentenceOrder":230},
  {"id":"s_work_han_thu_41_231","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「漫，放也。羨音弋戰反。」","sentenceOrder":231},
  {"id":"s_work_han_thu_41_232","chapterId":"ch_work_han_thu_41","textTraditional":"神農二十篇。六國時，諸子疾時（念）〔怠〕於農業，道耕農事，託之神農。〔一〕野老十七篇。六國時，在齊、楚間。〔二〕宰氏十七篇。不知何世。董安國十六篇。漢代內史，不知何帝時。尹都尉十四篇。不知何世。趙氏五篇。不知何世。氾勝之十八篇。成帝時為議郎。〔三〕王氏六篇。不知何世。蔡癸一篇。宣帝時，以言便宜，至弘農太守。〔四〕","sentenceOrder":232},
  {"id":"s_work_han_thu_41_233","chapterId":"ch_work_han_thu_41","textTraditional":"右農九家，百一十四篇。","sentenceOrder":233},
  {"id":"s_work_han_thu_41_234","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「劉向別錄云疑李悝及商君所說。」","sentenceOrder":234},
  {"id":"s_work_han_thu_41_235","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　應劭曰：「年老居田野，相民耕種，故號野老。」","sentenceOrder":235},
  {"id":"s_work_han_thu_41_236","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「劉向別錄云使教田三輔，有好田者師之，徙為御史。氾音凡，又音敷劍反。」","sentenceOrder":236},
  {"id":"s_work_han_thu_41_237","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「劉向別錄云邯鄲人。」","sentenceOrder":237},
  {"id":"s_work_han_thu_41_238","chapterId":"ch_work_han_thu_41","textTraditional":"農家者流，蓋出於農稷之官。播百穀，勸耕桑，以足衣食，故八政一曰食，二曰貨。孔子曰「所重民食」，〔一〕此其所長也。及鄙者為之，以為無所事聖王，〔二〕欲使君臣並耕，誖上下之序。〔三〕","sentenceOrder":238},
  {"id":"s_work_han_thu_41_239","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「論語載孔子稱殷湯伐桀告天辭也。言為君之道，所重者在人之食。」","sentenceOrder":239},
  {"id":"s_work_han_thu_41_240","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「言不須聖（主）〔王〕，天下自治。」","sentenceOrder":240},
  {"id":"s_work_han_thu_41_241","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「誖，亂也，音布內反。」","sentenceOrder":241},
  {"id":"s_work_han_thu_41_242","chapterId":"ch_work_han_thu_41","textTraditional":"伊尹說二十七篇。其語淺薄，似依託也。鬻子說十九篇。後世所加。周考七十六篇。考周事也。青史子五十七篇。古史官記事也。師曠六篇。見春秋，其言淺薄，本與此同，似因託之。務成子十一篇。稱堯問，非古語。宋子十八篇。孫卿道宋子，其言黃老意。天乙三篇。天乙謂湯，其言非殷時，皆依託也。黃帝說四十篇。迂誕依託。封禪方說十八篇。武帝時。待詔臣饒心術二十五篇。武帝時。〔一〕待詔臣安成未央術一篇。〔二〕臣壽周紀七篇。項國圉人，宣帝時。虞初周說九百四十三篇。河南人，武帝時以方士侍郎（隴）〔號〕黃車使者。〔三〕百家百三十九卷。","sentenceOrder":242},
  {"id":"s_work_han_thu_41_243","chapterId":"ch_work_han_thu_41","textTraditional":"右小說十五家，千三百八十篇。","sentenceOrder":243},
  {"id":"s_work_han_thu_41_244","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「劉向別錄云饒齊人也，不知其姓，武帝時待詔，作書名曰心術也。」","sentenceOrder":244},
  {"id":"s_work_han_thu_41_245","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　應劭曰：「道家也，好養生事，為未央之術。」","sentenceOrder":245},
  {"id":"s_work_han_thu_41_246","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　應劭曰：「其說以周書為本。」師古曰：「史記云虞初洛陽人，即張衡西京賦『小說九百，本自虞初』者也。」","sentenceOrder":246},
  {"id":"s_work_han_thu_41_247","chapterId":"ch_work_han_thu_41","textTraditional":"小說家者流，蓋出於稗官。〔一〕街談巷語，道聽塗說者之所造也。孔子曰：「雖小道，必有可觀者焉，致遠恐泥，是以君子弗為也。」〔二〕然亦弗滅也。閭里小知者之所及，亦使綴而不忘。如或一言可采，此亦芻蕘狂夫之議也。","sentenceOrder":247},
  {"id":"s_work_han_thu_41_248","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　如淳曰：「稗音鍛家排。九章『細米為稗』。街談巷說，其細碎之言也。王者欲知閭巷風俗，故立稗官使稱說之。今世亦謂偶語為稗。」師古曰：「稗音稊稗之稗，不與鍛排同也。稗官，小官。漢名臣奏唐林請省置吏，公卿大夫至都官稗官各減什三，是也。」","sentenceOrder":248},
  {"id":"s_work_han_thu_41_249","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「論語載孔子之言。泥，滯也，音乃細反。」","sentenceOrder":249},
  {"id":"s_work_han_thu_41_250","chapterId":"ch_work_han_thu_41","textTraditional":"凡諸子百八十九家，四千三百二十四篇。","sentenceOrder":250},
  {"id":"s_work_han_thu_41_251","chapterId":"ch_work_han_thu_41","textTraditional":"出蹴〈革{匊夂}〉一家，二十五篇。","sentenceOrder":251},
  {"id":"s_work_han_thu_41_252","chapterId":"ch_work_han_thu_41","textTraditional":"諸子十家，其可觀者九家而已。皆起於王道既微，諸侯力政，時君世主，好惡殊方，〔一〕是以九家之（說）〔術〕蠭出並作，〔二〕各引一端，崇其所善，以此馳說，取合諸侯。其言雖殊，辟猶水火，相滅亦相生也。〔三〕仁之與義，敬之與和，相反而皆相成也。易曰：「天下同歸而殊塗，一致而百慮。」〔四〕今異家者各推所長，窮知究慮，以明其指，雖有蔽短，合其要歸，亦六經之支與流裔〔五〕。使其人遭明王聖主，得其所折中，皆股肱之材已。〔六〕仲尼有言：「禮失而求諸野。」〔七〕方今去聖久遠，道術缺廢，無所更索，〔八〕彼九家者，不猶瘉於野乎？〔九〕若能修六藝之術，而觀此九家之言，舍短取長，則可以通萬方之略矣。〔一０〕","sentenceOrder":252},
  {"id":"s_work_han_thu_41_253","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「好音呼到反。惡音一故反。」","sentenceOrder":253},
  {"id":"s_work_han_thu_41_254","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「蠭與鋒同。」","sentenceOrder":254},
  {"id":"s_work_han_thu_41_255","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「辟讀曰譬。」","sentenceOrder":255},
  {"id":"s_work_han_thu_41_256","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「下繫之辭。」","sentenceOrder":256},
  {"id":"s_work_han_thu_41_257","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「裔，衣末也。其於六經，如水之下流，衣之末裔。」","sentenceOrder":257},
  {"id":"s_work_han_thu_41_258","chapterId":"ch_work_han_thu_41","textTraditional":"〔六〕　師古曰：「已，語終辭。」","sentenceOrder":258},
  {"id":"s_work_han_thu_41_259","chapterId":"ch_work_han_thu_41","textTraditional":"〔七〕　師古曰：「言都邑失禮，則於外野求之，亦將有獲。」","sentenceOrder":259},
  {"id":"s_work_han_thu_41_260","chapterId":"ch_work_han_thu_41","textTraditional":"〔八〕　師古曰：「索，求也。」","sentenceOrder":260},
  {"id":"s_work_han_thu_41_261","chapterId":"ch_work_han_thu_41","textTraditional":"〔九〕　師古曰：「瘉與愈同。愈，勝也。」","sentenceOrder":261},
  {"id":"s_work_han_thu_41_262","chapterId":"ch_work_han_thu_41","textTraditional":"〔一０〕師古曰：「舍，廢也。」","sentenceOrder":262},
  {"id":"s_work_han_thu_41_263","chapterId":"ch_work_han_thu_41","textTraditional":"屈原賦二十五篇。楚懷王大夫，有列傳。唐勒賦四篇。楚人。宋玉賦十六篇。楚人，與唐勒並時，在屈原後也。趙幽王賦一篇。莊夫子賦二十四篇。名忌，吳人。賈誼賦七篇。枚乘賦九篇。司馬相如賦二十九篇。淮南王賦八十二篇。淮南王群臣賦四十四篇。太常蓼侯孔臧賦二十篇。陽丘侯劉隁賦十九篇。〔一〕吾丘壽王賦十五篇。蔡甲賦一篇。上所自造賦二篇。〔二〕兒寬賦二篇。光祿大夫張子僑賦三篇。與王褒同時也。陽成侯劉德賦九篇。劉向賦三十三篇。王褒賦十六篇。","sentenceOrder":263},
  {"id":"s_work_han_thu_41_264","chapterId":"ch_work_han_thu_41","textTraditional":"右賦二十家，三百六十一篇。","sentenceOrder":264},
  {"id":"s_work_han_thu_41_265","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「隁音偃。」","sentenceOrder":265},
  {"id":"s_work_han_thu_41_266","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「武帝也。」","sentenceOrder":266},
  {"id":"s_work_han_thu_41_267","chapterId":"ch_work_han_thu_41","textTraditional":"陸賈賦三篇。枚皋賦百二十篇。朱建賦二篇。常侍郎莊怱奇賦十一篇。枚皋同時。〔一〕嚴助賦三十五篇。〔二〕朱買臣賦三篇。宗正劉辟彊賦八篇。司馬遷賦八篇。郎中臣嬰齊賦十篇。臣說賦九篇。〔三〕臣吾賦十八篇。遼東太守蘇季賦一篇。蕭望之賦四篇。河內太守徐明賦三篇。字長君，東海人，元、成世歷五郡太守，有能名。給事黃門侍郎李息賦九篇。淮陽憲王賦二篇。揚雄賦十二篇。待詔馮商賦九篇。博士弟子杜參賦二篇。〔四〕車郎張豐賦三篇。張子僑子。驃騎將軍朱宇賦三篇。〔五〕","sentenceOrder":267},
  {"id":"s_work_han_thu_41_268","chapterId":"ch_work_han_thu_41","textTraditional":"右賦二十一家，二百七十四篇。入揚雄八篇。","sentenceOrder":268},
  {"id":"s_work_han_thu_41_269","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「七略云『怱奇者，或言莊夫子子，或言族家子莊助昆弟也。從行至茂陵，（造作）〔詔造〕賦』。」","sentenceOrder":269},
  {"id":"s_work_han_thu_41_270","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「上言莊怱奇，下言嚴助，史駮文。」","sentenceOrder":270},
  {"id":"s_work_han_thu_41_271","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「說，名，音悅。」","sentenceOrder":271},
  {"id":"s_work_han_thu_41_272","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「劉向別錄云『臣向謹與長社尉杜參校中祕書』。劉歆又云『參，杜陵人，以陽朔元年病死，〔死〕時年二十餘』。」","sentenceOrder":272},
  {"id":"s_work_han_thu_41_273","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「劉向別錄云『驃騎將軍史朱宇』，志以宇在驃騎府，故總言驃騎將軍。」","sentenceOrder":273},
  {"id":"s_work_han_thu_41_274","chapterId":"ch_work_han_thu_41","textTraditional":"孫卿賦十篇。秦時雜賦九篇。李思孝景皇帝頌十五篇。廣川惠王越賦五篇。長沙王群臣賦三篇。魏內史賦二篇。東暆令延年賦七篇。〔一〕衛士令李忠賦二篇。張偃賦二篇。賈充賦四篇。張仁賦六篇。秦充賦二篇。李步昌賦二篇。侍郎謝多賦十篇。平陽公主舍人周長孺賦二篇。雒陽錡華賦九篇。〔二〕眭弘賦一篇。〔三〕別栩陽賦五篇。〔四〕臣昌市賦六篇。臣義賦二篇。黃門書者假史王商賦十三篇。侍中徐博賦四篇。黃門書者王廣呂嘉賦五篇。漢中都尉丞華龍賦二篇。左馮翊史路恭賦八篇。","sentenceOrder":274},
  {"id":"s_work_han_thu_41_275","chapterId":"ch_work_han_thu_41","textTraditional":"右賦二十五家，百三十六篇。","sentenceOrder":275},
  {"id":"s_work_han_thu_41_276","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「東暆，縣名。暆音移。」","sentenceOrder":276},
  {"id":"s_work_han_thu_41_277","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「錡，姓；華，名。錡音魚綺反。」","sentenceOrder":277},
  {"id":"s_work_han_thu_41_278","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「即眭孟也。眭音先隨反。」","sentenceOrder":278},
  {"id":"s_work_han_thu_41_279","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　服虔曰：「栩音詡。」","sentenceOrder":279},
  {"id":"s_work_han_thu_41_280","chapterId":"ch_work_han_thu_41","textTraditional":"客主賦十八篇。雜行出及頌德賦二十四篇。雜四夷及兵賦二十篇。雜中賢失意賦十二篇。雜思慕悲哀死賦十六篇。雜鼓琴劍戲賦十三篇。雜山陵水泡雲氣雨旱賦十六篇。〔一〕雜禽獸六畜昆蟲賦十八篇。雜器械草木賦三十三篇。（文）〔大〕雜賦三十四篇。成相雜辭十一篇。隱書十八篇。〔二〕","sentenceOrder":280},
  {"id":"s_work_han_thu_41_281","chapterId":"ch_work_han_thu_41","textTraditional":"右雜賦十二家，二百三十三篇。","sentenceOrder":281},
  {"id":"s_work_han_thu_41_282","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「泡，水上浮漚也。泡音普交反。漚音一侯反。」","sentenceOrder":282},
  {"id":"s_work_han_thu_41_283","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「劉向別錄云『隱書者，疑其言以相問，對者以慮思之，可以無不諭』。」","sentenceOrder":283},
  {"id":"s_work_han_thu_41_284","chapterId":"ch_work_han_thu_41","textTraditional":"高祖歌詩二篇。泰一雜甘泉壽宮歌詩十四篇。宗廟歌詩五篇。漢興以來兵所誅滅歌詩十四篇。出行巡狩及游歌詩十篇。臨江王及愁思節士歌詩四篇。李夫人及幸貴人歌詩三篇。詔賜中山靖王子噲及孺子妾冰未央材人歌詩四篇。〔一〕吳楚汝南歌詩十五篇。燕代謳雁門雲中隴西歌詩九篇。邯鄲河間歌詩四篇。齊鄭歌詩四篇。淮南歌詩四篇。左馮翊秦歌詩三篇。京兆尹秦歌詩五篇。河東蒲反歌詩一篇。黃門倡車忠等歌詩十五篇。雜各有主名歌詩十篇。雜歌詩九篇。雒陽歌詩四篇。河南周歌詩七篇。河南周歌聲曲折七篇。周謠歌詩七十五篇。周謠歌詩聲曲折七十五篇。諸神歌詩三篇。送迎靈頌歌詩三篇。周歌詩二篇。南郡歌詩五篇。","sentenceOrder":284},
  {"id":"s_work_han_thu_41_285","chapterId":"ch_work_han_thu_41","textTraditional":"右歌詩二十八家，三百一十四篇。","sentenceOrder":285},
  {"id":"s_work_han_thu_41_286","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「孺子，王妾之有品號者也。妾，王之眾妾也。冰，其名。材人，天子內官。」","sentenceOrder":286},
  {"id":"s_work_han_thu_41_287","chapterId":"ch_work_han_thu_41","textTraditional":"凡詩賦百六家，千三百一十八篇。入揚雄八篇。","sentenceOrder":287},
  {"id":"s_work_han_thu_41_288","chapterId":"ch_work_han_thu_41","textTraditional":"傳曰：「不歌而誦謂之賦，登高能賦可以為大夫。」言感物造耑，材知深美，〔一〕可與圖事，故可以為列大夫也。古者諸侯卿大夫交接鄰國，以微言相感，當揖讓之時，必稱詩以諭其志，蓋以別賢不肖而觀盛衰焉。故孔子曰「不學詩，無以言」也。〔二〕春秋之後，周道浸壞，〔三〕聘問歌詠不行於列國，學詩之士逸在布衣，而賢人失志之賦作矣。大儒孫卿及楚臣屈原離讒憂國，皆作賦以風，〔四〕咸有惻隱古詩之義。其後宋玉、唐勒，漢興枚乘、司馬相如，下及揚子雲，競為侈麗閎衍之詞，沒其風諭之義。是以揚子悔之，曰：「詩人之賦麗以則，辭人之賦麗以淫。〔五〕如孔氏之門人用賦也，則賈誼登堂，相如入室矣，如其不用何！」〔六〕自孝武立樂府而采歌謠，於是有代趙之謳，秦楚之風，皆感於哀樂，緣事而發，亦可以觀風俗，知薄厚云。〔序〕詩賦為五種。","sentenceOrder":288},
  {"id":"s_work_han_thu_41_289","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「耑，古端字也。因物動志，則造辭義之端緒。」","sentenceOrder":289},
  {"id":"s_work_han_thu_41_290","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「論語載孔子戒伯魚之辭也。」","sentenceOrder":290},
  {"id":"s_work_han_thu_41_291","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「浸，漸也。」","sentenceOrder":291},
  {"id":"s_work_han_thu_41_292","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「離，遭也。風讀曰諷。次下亦同。」","sentenceOrder":292},
  {"id":"s_work_han_thu_41_293","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「辭人，言後代之為文辭。」","sentenceOrder":293},
  {"id":"s_work_han_thu_41_294","chapterId":"ch_work_han_thu_41","textTraditional":"〔六〕　師古曰：「言孔氏之門既不用賦，不可如何。謂賈誼、相如無所施也。」","sentenceOrder":294},
  {"id":"s_work_han_thu_41_295","chapterId":"ch_work_han_thu_41","textTraditional":"吳孫子兵法八十二篇。圖九卷。〔一〕齊孫子八十九篇。圖四卷。〔二〕公孫鞅二十七篇。吳起四十八篇。有列傳。范蠡二篇。越王句踐臣也。大夫種二篇。與范蠡俱事句踐。（季）〔李〕子十篇。娷一篇。〔三〕兵春秋一篇。龐煖三篇。〔四〕兒良一篇。〔五〕廣武君一篇。李左車。韓信三篇。〔六〕","sentenceOrder":295},
  {"id":"s_work_han_thu_41_296","chapterId":"ch_work_han_thu_41","textTraditional":"右兵權謀十三家，二百五十九篇。","sentenceOrder":296},
  {"id":"s_work_han_thu_41_297","chapterId":"ch_work_han_thu_41","textTraditional":"省伊尹、太公、管子、孫卿子、鶡冠子、蘇子、蒯通、陸賈、淮南王二百五十九種，出司馬法入禮也。","sentenceOrder":297},
  {"id":"s_work_han_thu_41_298","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「孫武也，臣於闔廬。」","sentenceOrder":298},
  {"id":"s_work_han_thu_41_299","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「孫臏。」","sentenceOrder":299},
  {"id":"s_work_han_thu_41_300","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「娷音女瑞反，蓋說兵法者，人名也。」","sentenceOrder":300},
  {"id":"s_work_han_thu_41_301","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「煖音許遠反，又音許元反。」","sentenceOrder":301},
  {"id":"s_work_han_thu_41_302","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「六國時人也。兒音五溪反。」","sentenceOrder":302},
  {"id":"s_work_han_thu_41_303","chapterId":"ch_work_han_thu_41","textTraditional":"〔六〕　師古曰：「淮陰侯。」","sentenceOrder":303},
  {"id":"s_work_han_thu_41_304","chapterId":"ch_work_han_thu_41","textTraditional":"權謀者，以正守國，以奇用兵，先計而後戰，兼形勢，包陰陽，用技巧者也。","sentenceOrder":304},
  {"id":"s_work_han_thu_41_305","chapterId":"ch_work_han_thu_41","textTraditional":"楚兵法七篇。圖四卷。蚩尤二篇。見呂刑。孫軫五篇。圖二卷。繇敘二篇。王孫十六篇。圖五卷。尉繚三十一篇。魏公子二十一篇。圖十卷。名無忌，有列傳。景子十三篇。李良三篇。丁子一篇。項王一篇。名籍。","sentenceOrder":305},
  {"id":"s_work_han_thu_41_306","chapterId":"ch_work_han_thu_41","textTraditional":"右兵形勢十一家，九十二篇。圖十八卷。","sentenceOrder":306},
  {"id":"s_work_han_thu_41_307","chapterId":"ch_work_han_thu_41","textTraditional":"形勢者，雷動風舉，後發而先至，離合背鄉，變化無常，〔一〕以輕疾制敵者也。","sentenceOrder":307},
  {"id":"s_work_han_thu_41_308","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「背音步內反。鄉讀曰嚮。」","sentenceOrder":308},
  {"id":"s_work_han_thu_41_309","chapterId":"ch_work_han_thu_41","textTraditional":"太壹兵法一篇。天一兵法三十五篇。神農兵法一篇。黃帝十六篇。圖三卷。封胡五篇。黃帝臣，依託也。風后十三篇。圖二卷。黃帝臣，依託也。力牧十五篇。黃帝臣，依託也。鵊冶子一篇。圖一卷。〔一〕鬼容區三篇。圖一卷。黃帝臣，依託。〔二〕地典六篇。孟子一篇。東父三十一篇。師曠八篇。晉平公臣。萇弘十五篇。周史。別成子望軍氣六篇。圖三卷。辟兵威勝方七十篇。","sentenceOrder":309},
  {"id":"s_work_han_thu_41_310","chapterId":"ch_work_han_thu_41","textTraditional":"右陰陽十六家，二百四十九篇，圖十卷。","sentenceOrder":310},
  {"id":"s_work_han_thu_41_311","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　晉灼曰：「鵊音夾。」","sentenceOrder":311},
  {"id":"s_work_han_thu_41_312","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰；「即鬼臾區也。」","sentenceOrder":312},
  {"id":"s_work_han_thu_41_313","chapterId":"ch_work_han_thu_41","textTraditional":"陰陽者，順時而發，推刑德，隨斗擊，因五勝，〔一〕假鬼神而為助者也。","sentenceOrder":313},
  {"id":"s_work_han_thu_41_314","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「五勝，五行相勝也。」","sentenceOrder":314},
  {"id":"s_work_han_thu_41_315","chapterId":"ch_work_han_thu_41","textTraditional":"鮑子兵法十篇。圖一卷。五子胥十篇。圖一卷。公勝子五篇。苗子五篇。圖一卷。逢門射法二篇。〔一〕陰通成射法十一篇。李將軍射法三篇。〔二〕魏氏射法六篇。彊弩將軍王圍射法五卷。〔三〕望遠連弩射法具十五篇。護軍射師王賀射書五篇。蒲苴子弋法四篇。〔四〕劍道三十八篇。手搏六篇。雜家兵法五十七篇。蹴〈革{匊夂}〉二十五篇。〔五〕","sentenceOrder":315},
  {"id":"s_work_han_thu_41_316","chapterId":"ch_work_han_thu_41","textTraditional":"右兵技巧十三家，百九十九篇。省墨子重，入蹴〈革{匊夂}〉也。","sentenceOrder":316},
  {"id":"s_work_han_thu_41_317","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「即逢蒙。」","sentenceOrder":317},
  {"id":"s_work_han_thu_41_318","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「李廣。」","sentenceOrder":318},
  {"id":"s_work_han_thu_41_319","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「圍，郁郅人也，見趙充國傳。」","sentenceOrder":319},
  {"id":"s_work_han_thu_41_320","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「苴音子余反。」","sentenceOrder":320},
  {"id":"s_work_han_thu_41_321","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「〈革{匊夂}〉以韋為之，實以物，蹴蹋之以為戲也。蹴〈革{匊夂}〉，陳力之事，故附於兵法焉。蹴音子六反。〈革{匊夂}〉音巨六反。」","sentenceOrder":321},
  {"id":"s_work_han_thu_41_322","chapterId":"ch_work_han_thu_41","textTraditional":"技巧者，習手足，便器械，積機關，以立攻守之勝者也。","sentenceOrder":322},
  {"id":"s_work_han_thu_41_323","chapterId":"ch_work_han_thu_41","textTraditional":"凡兵書五十三家，七百九十篇，圖四十三卷。省十家二百七十一篇重，入蹴〈革{匊夂}〉一家二十五篇，出司馬法百五十五篇入禮也。","sentenceOrder":323},
  {"id":"s_work_han_thu_41_324","chapterId":"ch_work_han_thu_41","textTraditional":"兵家者，蓋出古司馬之職，王官之武備也。洪範八政，八曰師。孔子曰為國者「足食足兵」，〔一〕「以不教民戰，是謂棄之」〔二〕，明兵之重也。易曰「古者弦木為弧，剡木為矢，弧矢之利，以威天下」，〔三〕其用上矣。後世燿金為刃，割革為甲，〔四〕器械甚備。下及湯武受命，以師克亂而濟百姓，動之以仁義，行之以禮讓，司馬法是其遺事也。自春秋至於戰國，出奇設伏，變詐之兵並作。漢興，張良、韓信序次兵法，凡百八十二家，刪取要用，定著三十五家。諸呂用事而盜取之。武帝時，軍政楊僕捃摭遺逸，紀奏兵錄，〔五〕猶未能備。至于孝成，命任宏論次兵書為四種。","sentenceOrder":324},
  {"id":"s_work_han_thu_41_325","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「論語載孔子之言。無兵與食，不可以為國。」","sentenceOrder":325},
  {"id":"s_work_han_thu_41_326","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「亦論語所載孔子之言，非其不素習武備。」","sentenceOrder":326},
  {"id":"s_work_han_thu_41_327","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「下繫之辭也。弧，木弓也。剡謂銳而利之也，音弋冉反。」","sentenceOrder":327},
  {"id":"s_work_han_thu_41_328","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「燿讀與鑠同，謂銷也。」","sentenceOrder":328},
  {"id":"s_work_han_thu_41_329","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰；「捃摭，謂拾取之。捃音九問反。摭音之石反。」","sentenceOrder":329},
  {"id":"s_work_han_thu_41_330","chapterId":"ch_work_han_thu_41","textTraditional":"泰壹雜子星二十八卷。五殘雜變星二十一卷。〔一〕黃帝雜子氣三十三篇。常從日月星氣二十一卷。〔二〕皇公雜子星二十二卷。淮南雜子星十九卷。泰壹雜子雲雨三十四卷。國章觀霓雲雨三十四卷。泰階六符一卷。〔三〕金度玉衡漢五星客流出入八篇。漢五星彗客行事占驗八卷。漢日旁氣行事占驗三卷。漢流星行事占驗八卷。漢日旁氣行占驗十三卷。漢日食月暈雜變行事占驗十三卷。海中星占驗十二卷。海中五星經雜事二十二卷。海中五星順逆二十八卷。海中二十八宿國分二十八卷。海中二十八宿臣分二十八卷。海中日月彗虹雜占十八卷。圖書祕記十七篇。","sentenceOrder":330},
  {"id":"s_work_han_thu_41_331","chapterId":"ch_work_han_thu_41","textTraditional":"右天文二十一家，四百四十五卷。","sentenceOrder":331},
  {"id":"s_work_han_thu_41_332","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「五殘，星名也。見天文志。」","sentenceOrder":332},
  {"id":"s_work_han_thu_41_333","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「常從，人姓名也，老子師之。」","sentenceOrder":333},
  {"id":"s_work_han_thu_41_334","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　李奇曰：「三台謂之泰階，兩兩成體，三台故六。觀色以知吉凶，故曰符。」","sentenceOrder":334},
  {"id":"s_work_han_thu_41_335","chapterId":"ch_work_han_thu_41","textTraditional":"天文者，序二十八宿，步五星日月，以紀吉凶之象，聖王所以參政也。易曰：「觀乎天文，以察時變。」〔一〕然星事〈歹凶〉悍，非湛密者弗能由也。〔二〕夫觀景以譴形，非明王亦不能服聽也。以不能由之臣，諫不能聽之王，此所以兩有患也。","sentenceOrder":335},
  {"id":"s_work_han_thu_41_336","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「賁卦之彖辭也。」","sentenceOrder":336},
  {"id":"s_work_han_thu_41_337","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「〈歹凶〉讀與凶同。湛讀曰沈。由，用也。」","sentenceOrder":337},
  {"id":"s_work_han_thu_41_338","chapterId":"ch_work_han_thu_41","textTraditional":"黃帝五家曆三十三卷。顓頊曆二十一卷。顓頊五星曆十四卷。日月宿曆十三卷。夏殷周魯曆十四卷。天曆大曆十八卷。漢元殷周諜曆十七卷。耿昌月行帛圖二百三十二卷。耿昌月行度二卷。傳周五星行度三十九卷。律曆數法三卷。自古五星宿紀三十卷。太歲謀日晷二十九卷。帝王諸侯世譜二十卷。古來帝王年譜五卷。日晷書三十四卷。許商算術二十六卷。杜忠算術十六卷。","sentenceOrder":338},
  {"id":"s_work_han_thu_41_339","chapterId":"ch_work_han_thu_41","textTraditional":"右曆譜十八家，六百六卷。","sentenceOrder":339},
  {"id":"s_work_han_thu_41_340","chapterId":"ch_work_han_thu_41","textTraditional":"曆譜者，序四時之位，正分至之節，會日月五星之辰，以考寒暑殺生之實。故聖王必正曆數，以定三統服色之制，又以探知五星日月之會。凶阨之患，吉隆之喜，其術皆出焉。此聖人知命之術也，非天下之至材，其孰與焉！〔一〕道之亂也，患出於小人而強欲知天道者，壞大以為小，削遠以為近，是以道術破碎而難知也。","sentenceOrder":340},
  {"id":"s_work_han_thu_41_341","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「與讀曰豫。」","sentenceOrder":341},
  {"id":"s_work_han_thu_41_342","chapterId":"ch_work_han_thu_41","textTraditional":"泰一陰陽二十三卷。黃帝陰陽二十五卷。黃帝諸子論陰陽二十五卷。諸王子論陰陽二十五卷。太元陰陽二十六卷。三典陰陽談論二十七卷。神農大幽五行二十七卷。四時五行經二十六卷。猛子閭昭二十五卷。陰陽五行時令十九卷。堪輿金匱十四卷。〔一〕務成子災異應十四卷。十二典災異應十二卷。鍾律災異二十六卷。鍾律叢辰日苑二十三卷。鍾律消息二十九卷。黃鍾七卷。天一六卷。泰一二十（二）九卷。刑德七卷。風鼓六甲二十四卷。風后孤虛二十卷。六合隨典二十五卷。轉位十二神二十五卷。羨門式法二十卷。羨門式二十卷。文解六甲十八卷。文解二十八宿二十八卷。五音奇胲用兵二十三卷。〔二〕五音奇胲刑德二十一卷。五音定名十五卷。","sentenceOrder":342},
  {"id":"s_work_han_thu_41_343","chapterId":"ch_work_han_thu_41","textTraditional":"右五行三十一家，六百五十二卷。","sentenceOrder":343},
  {"id":"s_work_han_thu_41_344","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「許慎云『堪，天道；輿，地道也』。」","sentenceOrder":344},
  {"id":"s_work_han_thu_41_345","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　如淳曰：「音該。」師古曰：「許慎云『胲，軍中約也』。」","sentenceOrder":345},
  {"id":"s_work_han_thu_41_346","chapterId":"ch_work_han_thu_41","textTraditional":"五行者，五常之形氣也。書云「初一曰五行，次二曰羞用五事」，〔一〕言進用五事以順五行也。貌、言、視、聽、思心失，而五行之序亂，五星之變作，皆出於律曆之數而分為一者也。〔二〕其法亦起五德終始，推其極則無不至。而小數家因此以為吉凶，而行於世，浸以相亂。〔三〕","sentenceOrder":346},
  {"id":"s_work_han_thu_41_347","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「周書洪範之辭也。」","sentenceOrder":347},
  {"id":"s_work_han_thu_41_348","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「說皆在五行志也。」","sentenceOrder":348},
  {"id":"s_work_han_thu_41_349","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「浸，漸也。」","sentenceOrder":349},
  {"id":"s_work_han_thu_41_350","chapterId":"ch_work_han_thu_41","textTraditional":"龜書五十二卷。夏龜二十六卷。南龜書二十八卷。巨龜三十六卷。雜龜十六卷。蓍書二十八卷。周易三十八卷。周易明堂二十六卷。周易隨曲射匿五十卷。大筮衍易二十八卷。大次雜易三十卷。鼠序卜黃二十五卷。於陵欽易吉凶二十三卷。任良易旗七十一卷。易卦八具。","sentenceOrder":350},
  {"id":"s_work_han_thu_41_351","chapterId":"ch_work_han_thu_41","textTraditional":"右蓍龜十五家，四百一卷。","sentenceOrder":351},
  {"id":"s_work_han_thu_41_352","chapterId":"ch_work_han_thu_41","textTraditional":"蓍龜者，聖人之所用也。書曰：「女則有大疑，謀及卜筮。〔一〕」易曰：「定天下之吉凶，成天下之亹亹者，莫善於蓍龜。」「是故君子將有為也，將有行也，問焉而以言，其受命也如嚮，無有遠近幽深，遂知來物。非天下之至精，其孰能與於此！」〔二〕及至衰世，解於齊戒，而婁煩卜筮，〔三〕神明不應。故筮瀆不告，易以為忌；〔四〕龜厭不告，詩以為刺。〔五〕","sentenceOrder":352},
  {"id":"s_work_han_thu_41_353","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「周書洪範之辭也。言所為之事有疑，則以卜筮決之也。龜曰卜，蓍曰筮。」","sentenceOrder":353},
  {"id":"s_work_han_thu_41_354","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「皆上繫之辭也。亹亹，深遠也。言君子所為行，皆以其言問於易。受命如嚮者，謂示以吉凶，其應速疾，如響之隨聲也。遂猶究也。來物謂當來之事也。嚮與響同。與讀曰豫。」","sentenceOrder":354},
  {"id":"s_work_han_thu_41_355","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「解讀曰懈。齊讀曰齋。婁讀曰屢。」","sentenceOrder":355},
  {"id":"s_work_han_thu_41_356","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「易蒙卦之辭曰『初筮告，再三瀆，瀆則不告』，言童蒙之來決疑。初則以實而告，至於再三，為其煩瀆，乃不告也。」","sentenceOrder":356},
  {"id":"s_work_han_thu_41_357","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「小雅小旻之詩曰『我龜既厭，不我告猶』，言卜問煩數，媟嫚於龜，龜靈厭之，不告以道也。」","sentenceOrder":357},
  {"id":"s_work_han_thu_41_358","chapterId":"ch_work_han_thu_41","textTraditional":"黃帝長柳占夢十一卷。甘德長柳占夢二十卷。武禁相衣器十四卷。嚏耳鳴雜占十六卷。〔一〕禎祥變怪二十一卷。人鬼精物六畜變怪二十一卷。變怪誥咎十三卷。執不祥劾鬼物八卷。請官除訞祥十九卷。〔二〕禳祀天文十八卷。〔三〕請禱致福十九卷。請雨止雨二十六卷。泰壹雜子候歲二十二卷。子贛雜子候歲二十六卷。五法積貯寶臧二十三卷。神農教田相土耕種十四卷。昭明子釣種生魚鱉八卷。種樹臧果相蠶十三卷。","sentenceOrder":358},
  {"id":"s_work_han_thu_41_359","chapterId":"ch_work_han_thu_41","textTraditional":"右雜占十八家，三百一十三卷。","sentenceOrder":359},
  {"id":"s_work_han_thu_41_360","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「嚏音丁計反。」","sentenceOrder":360},
  {"id":"s_work_han_thu_41_361","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「訞字與妖同。」","sentenceOrder":361},
  {"id":"s_work_han_thu_41_362","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「禳，除災也，音人羊反。」","sentenceOrder":362},
  {"id":"s_work_han_thu_41_363","chapterId":"ch_work_han_thu_41","textTraditional":"雜占者，紀百事之象，候善惡之徵。〔一〕易曰：「占事知來。」〔二〕眾占非一，而夢為大，故周有其官。〔三〕而詩載熊羆虺蛇眾魚旐旟之夢，著明大人之占，以考吉凶，〔四〕蓋參卜筮。春秋之說訞也，曰：「人之所忌，其氣炎以取之，訞由人興也。人失常則訞興，人無釁焉，訞不自作。」〔五〕故曰：「德勝不祥，義厭不惠。」〔六〕桑穀共生，大戊以興；鴝雉登鼎，武丁為宗。〔七〕然惑者不稽諸躬，而忌訞之見，〔八〕是以詩刺「召彼故老，訊之占夢」，〔九〕傷其舍本而憂末，不能勝凶咎也。","sentenceOrder":363},
  {"id":"s_work_han_thu_41_364","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「徵，證也。」","sentenceOrder":364},
  {"id":"s_work_han_thu_41_365","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「下繫之辭也。言有事而占，則睹方來之驗也。」","sentenceOrder":365},
  {"id":"s_work_han_thu_41_366","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「謂大卜掌三夢之法，又占夢中士二人，皆宗伯之屬官。」","sentenceOrder":366},
  {"id":"s_work_han_thu_41_367","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　師古曰：「小雅斯干之詩曰：『吉夢維何？維熊維羆，男子之祥；維虺維蛇，女子之祥。』無羊之詩曰：『牧人乃夢，眾維魚矣，旐維旟矣。大人占之，眾維魚矣，實維豐年，旐維旟矣，室家溱溱。』言熊羆虺蛇皆為吉祥之夢，而生男女。及見眾魚，則為豐年之應，旐旟則為多盛之象。大人占之，謂以聖人占夢之法占之也。畫龜蛇曰旐，鳥隼曰旟。」","sentenceOrder":367},
  {"id":"s_work_han_thu_41_368","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　師古曰：「申繻之辭也，事見莊公十四年。炎謂火之光始燄燄也。言人之所忌，其氣燄引致於災也。釁，瑕也。失常，謂反五常之德也。炎讀與燄同。」","sentenceOrder":368},
  {"id":"s_work_han_thu_41_369","chapterId":"ch_work_han_thu_41","textTraditional":"〔六〕　師古曰：「厭音伊葉反。惠，順也。」","sentenceOrder":369},
  {"id":"s_work_han_thu_41_370","chapterId":"ch_work_han_thu_41","textTraditional":"〔七〕　師古曰：「說在郊祀、五行志。」","sentenceOrder":370},
  {"id":"s_work_han_thu_41_371","chapterId":"ch_work_han_thu_41","textTraditional":"〔八〕　師古曰：「稽，考也，計也。」","sentenceOrder":371},
  {"id":"s_work_han_thu_41_372","chapterId":"ch_work_han_thu_41","textTraditional":"〔九〕　師古曰：「小雅正月之詩也。故老，元老也。訊，問也。言不能修德以禳災，但問元老以占夢之吉凶。」","sentenceOrder":372},
  {"id":"s_work_han_thu_41_373","chapterId":"ch_work_han_thu_41","textTraditional":"山海經十三篇。國朝七卷。宮宅地形二十卷。相人二十四卷。相寶劍刀二十卷。相六畜三十八卷。","sentenceOrder":373},
  {"id":"s_work_han_thu_41_374","chapterId":"ch_work_han_thu_41","textTraditional":"右形法六家，百二十二卷。","sentenceOrder":374},
  {"id":"s_work_han_thu_41_375","chapterId":"ch_work_han_thu_41","textTraditional":"形法者，大舉九州之勢以立城郭室舍形，人及六畜骨法之度數、器物之形容以求其聲氣貴賤吉凶。猶律有長短，而各徵其聲，非有鬼神，數自然也。然形與氣相首尾，亦有有其形而無其氣，有其氣而無其形，此精微之獨異也。","sentenceOrder":375},
  {"id":"s_work_han_thu_41_376","chapterId":"ch_work_han_thu_41","textTraditional":"凡數術百九十家，二千五百二十八卷。","sentenceOrder":376},
  {"id":"s_work_han_thu_41_377","chapterId":"ch_work_han_thu_41","textTraditional":"數術者，皆明堂羲和史卜之職也。史官之廢久矣，其書既不能具，雖有其書而無其人。易曰：「苟非其人，道不虛行。」〔一〕春秋時魯有梓慎，鄭有裨灶，晉有卜偃，宋有子韋。六國時楚有甘公，魏有石申夫。漢有唐都，庶得麤觕。〔二〕蓋有因而成易，無因而成難，故因舊書以序數術為六種。","sentenceOrder":377},
  {"id":"s_work_han_thu_41_378","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「下繫之辭也。言道由人行。」","sentenceOrder":378},
  {"id":"s_work_han_thu_41_379","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「觕，粗略也，音才戶反。」","sentenceOrder":379},
  {"id":"s_work_han_thu_41_380","chapterId":"ch_work_han_thu_41","textTraditional":"黃帝內經十八卷。外經三十（九）〔七〕卷。扁鵲內經九卷。外經十二卷。白氏內經三十八卷。外經三十六卷。旁篇二十五卷。","sentenceOrder":380},
  {"id":"s_work_han_thu_41_381","chapterId":"ch_work_han_thu_41","textTraditional":"右醫經七家，二百一十六卷。","sentenceOrder":381},
  {"id":"s_work_han_thu_41_382","chapterId":"ch_work_han_thu_41","textTraditional":"醫經者，原人血脈經（絡）〔落〕骨髓陰陽表裏，以起百病之本，死生之分，而用度箴石湯火所施，〔一〕調百藥齊和之所宜。〔二〕至齊之得，猶慈石取鐵，以物相使。拙者失理，以瘉為劇，（以死為生）〔以生為死〕。〔三〕","sentenceOrder":382},
  {"id":"s_work_han_thu_41_383","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「箴，所以刺病也。石謂砭石，即石箴也。古者攻病則有砭，今其術絕矣。箴音之林反。砭音彼廉反。」","sentenceOrder":383},
  {"id":"s_work_han_thu_41_384","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「齊音才詣反，其下並同。和音乎臥反。」","sentenceOrder":384},
  {"id":"s_work_han_thu_41_385","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「瘉讀與愈同。愈，差也。」","sentenceOrder":385},
  {"id":"s_work_han_thu_41_386","chapterId":"ch_work_han_thu_41","textTraditional":"五藏六府痺十二病方三十卷。〔一〕五藏六府疝十六病方四十卷。〔二〕五藏六府癉十二病方四十卷。〔三〕風寒熱十六病方二十六卷。泰始黃帝扁鵲俞拊方二十三卷。〔四〕五藏傷中十一病方三十一卷。客疾五藏狂顛病方十七卷。金創瘲瘛方三十卷。〔五〕婦人嬰兒方十九卷。湯液經法三十二卷。神農黃帝食禁七卷。","sentenceOrder":386},
  {"id":"s_work_han_thu_41_387","chapterId":"ch_work_han_thu_41","textTraditional":"右經方十一家，二百七十四卷。","sentenceOrder":387},
  {"id":"s_work_han_thu_41_388","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「痺，風溼之病，音必二反。」","sentenceOrder":388},
  {"id":"s_work_han_thu_41_389","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「疝，心腹氣病，音山諫反，〔又音刪〕。」","sentenceOrder":389},
  {"id":"s_work_han_thu_41_390","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「癉，黃病，音丁韓反。」","sentenceOrder":390},
  {"id":"s_work_han_thu_41_391","chapterId":"ch_work_han_thu_41","textTraditional":"〔四〕　應劭曰：「黃帝時醫也。」師古曰：「拊音膚。」","sentenceOrder":391},
  {"id":"s_work_han_thu_41_392","chapterId":"ch_work_han_thu_41","textTraditional":"〔五〕　服虔曰：「音〈疒挈〉引之〈疒挈〉。」師古曰：「小兒病也。瘛音充制反。瘲音子用反。」","sentenceOrder":392},
  {"id":"s_work_han_thu_41_393","chapterId":"ch_work_han_thu_41","textTraditional":"經方者，本草石之寒溫，量疾病之淺深，假藥味之滋，因氣感之宜，辯五苦六辛，致水火之齊，以通閉解結，反之於平。及失其宜者，以熱益熱，以寒增寒，精氣內傷，不見於外，是所獨失也。故諺曰：「有病不治，常得中醫。」","sentenceOrder":393},
  {"id":"s_work_han_thu_41_394","chapterId":"ch_work_han_thu_41","textTraditional":"容成陰道二十六卷。務成子陰道三十六卷。堯舜陰道二十三卷。湯盤庚陰道二十卷。天老雜子陰道二十五卷。天一陰道二十四卷。黃帝三王養陽方二十卷。三家內房有子方十七卷。","sentenceOrder":394},
  {"id":"s_work_han_thu_41_395","chapterId":"ch_work_han_thu_41","textTraditional":"右房中八家，百八十六卷。","sentenceOrder":395},
  {"id":"s_work_han_thu_41_396","chapterId":"ch_work_han_thu_41","textTraditional":"房中者，（性情）〔情性〕之極，至道之際，是以聖王制外樂以禁內情，而為之節文。傳曰：「先王之作樂，所以節百事也。」樂而有節，則和平壽考。及迷者弗顧，以生疾而隕性命。","sentenceOrder":396},
  {"id":"s_work_han_thu_41_397","chapterId":"ch_work_han_thu_41","textTraditional":"宓戲雜子道二十篇。上聖雜子道二十六卷。道要雜子十八卷。黃帝雜子步引十二卷。黃帝岐伯按摩十卷。黃帝雜子芝菌十八卷。〔一〕黃帝雜子十九家方二十一卷。泰壹雜子十五家方二十二卷。神農雜子技道二十三卷。泰壹雜子黃冶三十一卷。〔二〕","sentenceOrder":397},
  {"id":"s_work_han_thu_41_398","chapterId":"ch_work_han_thu_41","textTraditional":"右神僊十家，二百五卷。","sentenceOrder":398},
  {"id":"s_work_han_thu_41_399","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「服餌芝菌之法也。菌音求閔反。」","sentenceOrder":399},
  {"id":"s_work_han_thu_41_400","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「黃冶，釋在郊祀志。」","sentenceOrder":400},
  {"id":"s_work_han_thu_41_401","chapterId":"ch_work_han_thu_41","textTraditional":"神僊者，所以保性命之真，而游求於其外者也。聊以盪意平心，同死生之域，〔一〕而無怵惕於胸中。然而或者專以為務，則誕欺怪迂之文彌以益多，〔二〕非聖王之所以教也。孔子曰：「索隱行怪，後世有述焉，吾不為之矣。」〔三〕","sentenceOrder":401},
  {"id":"s_work_han_thu_41_402","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「盪，滌。一曰，盪，放也。」","sentenceOrder":402},
  {"id":"s_work_han_thu_41_403","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「誕，大言也。迂，遠也。」","sentenceOrder":403},
  {"id":"s_work_han_thu_41_404","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「禮記載孔子之言。索隱，求索隱暗之事，而行怪迂之道，妄令後人有所祖述，非我本志。」","sentenceOrder":404},
  {"id":"s_work_han_thu_41_405","chapterId":"ch_work_han_thu_41","textTraditional":"凡方技三十六家，八百六十八卷。","sentenceOrder":405},
  {"id":"s_work_han_thu_41_406","chapterId":"ch_work_han_thu_41","textTraditional":"方技者，皆生生之具，王官之一守也。太古有岐伯、俞拊，中世有扁鵲、秦和，〔一〕蓋論病以及國，原診以知政。〔二〕漢興有倉公。今其技術晻味，〔三〕故論其書，以序方技為四種。","sentenceOrder":406},
  {"id":"s_work_han_thu_41_407","chapterId":"ch_work_han_thu_41","textTraditional":"〔一〕　師古曰：「和，秦醫名也。」","sentenceOrder":407},
  {"id":"s_work_han_thu_41_408","chapterId":"ch_work_han_thu_41","textTraditional":"〔二〕　師古曰：「診，視驗，謂視其脈及色候也。診音軫，又音丈刃反。」","sentenceOrder":408},
  {"id":"s_work_han_thu_41_409","chapterId":"ch_work_han_thu_41","textTraditional":"〔三〕　師古曰：「晻與暗同。」","sentenceOrder":409},
  {"id":"s_work_han_thu_41_410","chapterId":"ch_work_han_thu_41","textTraditional":"大凡書，六略三十八種，五百九十六家，萬三千二百六十九卷。入三家，五十篇，省兵十家。","sentenceOrder":410},
  {"id":"s_work_han_thu_41_411","chapterId":"ch_work_han_thu_41","textTraditional":"校勘記","sentenceOrder":411},
  {"id":"s_work_han_thu_41_412","chapterId":"ch_work_han_thu_41","textTraditional":"一七０二頁一七行　轉（為）〔寫〕脫誤，　景祐、殿本都作「寫」。","sentenceOrder":412},
  {"id":"s_work_han_thu_41_413","chapterId":"ch_work_han_thu_41","textTraditional":"一七０三頁一一行　號九師（法）〔說〕。　景祐、殿本都作「說」。","sentenceOrder":413},
  {"id":"s_work_han_thu_41_414","chapterId":"ch_work_han_thu_41","textTraditional":"一七０四頁一二行　漢興，田（和）〔何〕傳之。　錢大昭說「和」當作「何」。按景祐、殿本都作「何」。","sentenceOrder":414},
  {"id":"s_work_han_thu_41_415","chapterId":"ch_work_han_thu_41","textTraditional":"一七０五頁　五行　歐陽經（二）〔三〕十二卷。　景祐、殿本都作「三」。","sentenceOrder":415},
  {"id":"s_work_han_thu_41_416","chapterId":"ch_work_han_thu_41","textTraditional":"一七０八頁一０行　詩言志，（哥）〔歌〕詠言。　景祐、殿本都作「歌」。下及注並同。","sentenceOrder":416},
  {"id":"s_work_han_thu_41_417","chapterId":"ch_work_han_thu_41","textTraditional":"一七０九頁　一行　三家（者）〔皆〕不得其真，　景祐、殿本都作「皆」。","sentenceOrder":417},
  {"id":"s_work_han_thu_41_418","chapterId":"ch_work_han_thu_41","textTraditional":"一七０九頁　二行　經（七十）〔十七〕篇。　劉敞說此「七十」與後「七十」皆當作「十七」。錢大昭、王先謙都說劉說是。","sentenceOrder":418},
  {"id":"s_work_han_thu_41_419","chapterId":"ch_work_han_thu_41","textTraditional":"一七一０頁一一行　（學七十）〔與十七〕篇文相似，　劉敞說「學七十」當作「與十七」。楊樹達以為劉說確鑿不可易。","sentenceOrder":419},
  {"id":"s_work_han_thu_41_420","chapterId":"ch_work_han_thu_41","textTraditional":"一七一七頁一０行　蓋孔子對〔魯〕哀公語也。　景祐、殿本都有「魯」字。","sentenceOrder":420},
  {"id":"s_work_han_thu_41_421","chapterId":"ch_work_han_thu_41","textTraditional":"一七一九頁一０行　千八百七十（一）〔二〕字，　景祐、殿本都作「二」。","sentenceOrder":421},
  {"id":"s_work_han_thu_41_422","chapterId":"ch_work_han_thu_41","textTraditional":"一七二０頁　二行　（成）〔元〕帝時黃門令史游作。　錢大昭說「成帝」當作「元帝」。　按景祐、殿本都作「元帝」。","sentenceOrder":422},
  {"id":"s_work_han_thu_41_423","chapterId":"ch_work_han_thu_41","textTraditional":"一七二一頁　八行　漢（書）〔興〕，　景祐、殿本都作「興」，此誤。","sentenceOrder":423},
  {"id":"s_work_han_thu_41_424","chapterId":"ch_work_han_thu_41","textTraditional":"一七二一頁一二行　臣復續揚雄作十（二）〔三〕章，　景祐、殿本都作「三」。王先謙說作「三」是。","sentenceOrder":424},
  {"id":"s_work_han_thu_41_425","chapterId":"ch_work_han_thu_41","textTraditional":"一七二二頁一二行　論語載孔子之（書）〔言〕，　景祐、殿本都作「言」。王先謙說作「言」是。","sentenceOrder":425},
  {"id":"s_work_han_thu_41_426","chapterId":"ch_work_han_thu_41","textTraditional":"一七二二頁一三行　任意改（治）〔作〕也。　景祐、殿本都作「作」。王先謙說作「作」是。","sentenceOrder":426},
  {"id":"s_work_han_thu_41_427","chapterId":"ch_work_han_thu_41","textTraditional":"一七二五頁一０行　讕言十（一）篇。　景祐、殿本都作「十篇」。","sentenceOrder":427},
  {"id":"s_work_han_thu_41_428","chapterId":"ch_work_han_thu_41","textTraditional":"一七二五頁一四行　齊閔王失國，（閒）〔問〕之，　景祐、殿、局本都作「問」。王先謙說作「問」是。","sentenceOrder":428},
  {"id":"s_work_han_thu_41_429","chapterId":"ch_work_han_thu_41","textTraditional":"一七二六頁　三行　（侯）〔俟〕子一篇。　景祐、殿本都作「俟」。王先謙說作「俟」是。","sentenceOrder":429},
  {"id":"s_work_han_thu_41_430","chapterId":"ch_work_han_thu_41","textTraditional":"一七二七頁一四行　入揚雄一家〔三〕十八篇。　景祐、殿本都作「三十八」。","sentenceOrder":430},
  {"id":"s_work_han_thu_41_431","chapterId":"ch_work_han_thu_41","textTraditional":"一七三０頁　六行　「楚人」二字據景祐、殿本補。","sentenceOrder":431},
  {"id":"s_work_han_thu_41_432","chapterId":"ch_work_han_thu_41","textTraditional":"一七三七頁一０行　則苟鉤（鈲）〔鋠〕析亂而已。　李慈銘說「鈲」當作「鋠」，注同。","sentenceOrder":432},
  {"id":"s_work_han_thu_41_433","chapterId":"ch_work_han_thu_41","textTraditional":"一七三八頁一五行　但有賢不肖（之）善惡。　景祐、殿本都無「之」字。","sentenceOrder":433},
  {"id":"s_work_han_thu_41_434","chapterId":"ch_work_han_thu_41","textTraditional":"一七四０頁一四行　尉繚（子）二十九篇。　景祐、殿本都無「子」字。","sentenceOrder":434},
  {"id":"s_work_han_thu_41_435","chapterId":"ch_work_han_thu_41","textTraditional":"一七四一頁一一行　武帝時（所）作賦。　景祐、殿本都無「所」字。","sentenceOrder":435},
  {"id":"s_work_han_thu_41_436","chapterId":"ch_work_han_thu_41","textTraditional":"一七四二頁　三行　諸子疾時（念）〔怠〕於農業，　景祐、殿本都作「怠」，此誤。","sentenceOrder":436},
  {"id":"s_work_han_thu_41_437","chapterId":"ch_work_han_thu_41","textTraditional":"一七四四頁　一行　言不須聖（主）〔王〕，　景祐、殿本都作「王」。","sentenceOrder":437},
  {"id":"s_work_han_thu_41_438","chapterId":"ch_work_han_thu_41","textTraditional":"一七四五頁　二行　武帝時以方士侍郎（隴）〔號〕黃車使者。　景祐、殿本都作「號」。","sentenceOrder":438},
  {"id":"s_work_han_thu_42_1","chapterId":"ch_work_han_thu_42","textTraditional":"服虔曰：「傳次其時之先後耳，不以賢智功之大小也。」師古曰：「雖次時之先後，亦以事類相從。如江充、息夫躬與蒯通同傳，賈山與路溫舒同傳，嚴助與賈捐之同傳之類是也。」","sentenceOrder":1},
  {"id":"s_work_han_thu_42_2","chapterId":"ch_work_han_thu_42","textTraditional":"陳勝字涉，陽城人。〔一〕吳廣，字叔，陽夏人也。〔二〕勝少時，嘗與人傭耕。〔三〕輟耕之壟上，〔四〕悵然甚久，曰：「苟富貴，無相忘！」〔五〕傭者笑而應曰：「若為傭耕，何富貴也？」勝太息曰：「嗟乎，燕雀安知鴻鵠之志哉！」〔六〕","sentenceOrder":2},
  {"id":"s_work_han_thu_42_3","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「地理志屬汝南郡。」","sentenceOrder":3},
  {"id":"s_work_han_thu_42_4","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「地理志屬淮陽。夏音工雅反。」","sentenceOrder":4},
  {"id":"s_work_han_thu_42_5","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「與人，與人俱也。傭耕，謂受其雇直而為之耕，言賣功傭也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_42_6","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「輟，止也。之，往也。壟上，謂田中之高處。」","sentenceOrder":6},
  {"id":"s_work_han_thu_42_7","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　師古曰：「但一人富貴，不問彼此，皆不相忘也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_42_8","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　師古曰：「鴻，大鳥也，水居。鵠，黃鵠也，一舉千里。鵠音胡督反。」","sentenceOrder":8},
  {"id":"s_work_han_thu_42_9","chapterId":"ch_work_han_thu_42","textTraditional":"秦二世元年秋七月，發閭左戍漁陽九百人，〔一〕勝、廣皆為屯長。〔二〕行至鄿大澤鄉，會天大雨，道不通，度已失期。失期法斬，〔三〕勝、廣乃謀曰：「今亡亦死，舉大計亦死，等死，死國可乎？」勝曰：「天下苦秦久矣。吾聞二世，少子，不當立，當立者乃公子扶蘇。扶蘇以數諫故不得立，上使外將兵。〔四〕今或聞無罪，二世殺之。百姓多聞其賢，未知其死。〔五〕項燕為楚將，數有功〔六〕，愛士卒，楚人憐之。或以為在。今誠以吾眾為天下倡，宜多應者。」〔七〕廣以為然。乃行卜。卜者知其指意，曰：「足下事皆成，有功。然足下卜之鬼乎！」〔八〕勝、廣喜，念鬼，曰：「此教我先威眾耳。」乃丹書帛曰「陳勝王」，置人所罾魚腹中。〔九〕卒買魚亨食，得書，已怪之矣。〔一０〕又間令廣之次所旁叢祠中，夜構火，狐鳴呼曰：「大楚興，陳勝王。」〔一一〕卒皆夜驚恐。旦日，卒中往往指目勝、廣。〔一二〕","sentenceOrder":9},
  {"id":"s_work_han_thu_42_10","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「閭，里門也。發閭左之人皆遣戍也。解具在食貨志。」","sentenceOrder":10},
  {"id":"s_work_han_thu_42_11","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「人所聚曰屯，為其長帥也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_42_12","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「度謂量計之，音大各反。」","sentenceOrder":12},
  {"id":"s_work_han_thu_42_13","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「數音所角反。下皆類此。」","sentenceOrder":13},
  {"id":"s_work_han_thu_42_14","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　如淳曰：「扶蘇自殺，故人不知其死。或以為不知何坐而死，故天下冤二世殺之。」師古曰：「如、或說皆非也。此言我聞二世已殺扶蘇矣，而百姓皆未知之，故勝、廣舉事詐自稱扶蘇耳。」","sentenceOrder":14},
  {"id":"s_work_han_thu_42_15","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　師古曰：「燕音一千反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_42_16","chapterId":"ch_work_han_thu_42","textTraditional":"〔七〕　師古曰：「倡讀曰唱，謂首號令也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_42_17","chapterId":"ch_work_han_thu_42","textTraditional":"〔八〕　李奇曰：「卜者誡曰，所卜事雖成，當死為鬼。惡指斥言，而勝失其指，反依鬼神起怪也。」蘇林曰：「狐鳴祠中即是也。」如淳曰：「以鬼道威眾乎，或但用人事也。」師古曰：「李、如之說皆非也。卜者云事成有功，然須假託鬼神乃可暴起耳。故勝、廣曉此意，則為魚書狐鳴以威眾耳。」","sentenceOrder":17},
  {"id":"s_work_han_thu_42_18","chapterId":"ch_work_han_thu_42","textTraditional":"〔九〕　師古曰：「罾，魚網也，形如仰繖蓋，四維而舉之，音曾。」","sentenceOrder":18},
  {"id":"s_work_han_thu_42_19","chapterId":"ch_work_han_thu_42","textTraditional":"〔一０〕師古曰：「亨音普庚反。」","sentenceOrder":19},
  {"id":"s_work_han_thu_42_20","chapterId":"ch_work_han_thu_42","textTraditional":"〔一一〕鄭氏曰：「間謂竊令人行也。」張晏曰：「戍人所止處也。叢，鬼所憑也。」師古曰：「張說非也。此言密於廣所次舍處旁側叢祠中為之，非戍人所止處也。叢謂草木岑蔚者也。祠，神祠也。構謂結起也。呼音火故反。」","sentenceOrder":20},
  {"id":"s_work_han_thu_42_21","chapterId":"ch_work_han_thu_42","textTraditional":"〔一二〕師古曰：「指而私目視之。」","sentenceOrder":21},
  {"id":"s_work_han_thu_42_22","chapterId":"ch_work_han_thu_42","textTraditional":"勝、廣素愛人，士卒多為用。將尉醉，〔一〕廣故數言欲亡，忿尉，令辱之，以激怒其眾。尉果笞廣。尉劍挺，廣起奪而殺尉。〔二〕勝佐之，并殺兩尉。召令徒屬曰：「公等遇雨，皆已失期，當斬。藉弟令毋斬，〔三〕而戍死者固什六七。且壯士不死則已，死則舉大名耳。侯王將相，寧有種乎！」〔四〕徒屬皆曰：「敬受令。」乃詐稱公子扶蘇、項燕，從民望也。袒右，稱大楚。〔五〕為壇而盟，祭以尉首。〔六〕勝自立為將軍，廣為都尉。攻大澤鄉，拔之。收兵而攻鄿，蘄下。乃令符離人葛嬰將兵徇蘄以東，〔七〕攻銍、酇、苦、柘、譙，皆下之。〔八〕行收兵，比至陳，〔九〕兵車六七百乘，騎千餘，卒數萬人。攻陳，陳守令皆不在，〔一０〕獨守丞與戰譙門中。〔一一〕不勝，守丞死。乃入據陳。數日，號召三老豪桀會計事。〔一二〕皆曰：「將軍身被堅執銳，〔一三〕伐無道，誅暴秦，復立楚之社稷，功宜為王。」勝乃立為王，號（為）張楚。〔一四〕","sentenceOrder":22},
  {"id":"s_work_han_thu_42_23","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「將尉者，其官本尉耳。時領戍人，故為將尉。」","sentenceOrder":23},
  {"id":"s_work_han_thu_42_24","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「挺，拔也。尉劍自拔出，廣因奪取之。」","sentenceOrder":24},
  {"id":"s_work_han_thu_42_25","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　服虔曰：「藉猶借也。弟，使也。」應劭曰：「藉，吏士名藉也。弟，次也。言今失期當斬，就使藉弟幸得不斬，戍死者固十六七也。」蘇林曰：「藉，假；弟，且也。」晉灼曰：「酈食其傳『弟言之』，外戚傳『弟一見我』，蘇說是也。」師古曰：「服、應說弟義皆非也。晉氏意頗近之，而猶未得。漢書諸言弟者甚眾。弟，但也，語有緩急耳。言但令無斬也。今俗人語稱但者，急言之則音如弟矣。酈食其、外戚傳所云弟者，皆謂但耳，義非且也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_42_26","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「言求之而得，不必胤冑。」","sentenceOrder":26},
  {"id":"s_work_han_thu_42_27","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　師古曰：「袒右者，脫右肩之衣。當時取異於凡眾也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_42_28","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　師古曰：「以所殺尉之首祭神也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_42_29","chapterId":"ch_work_han_thu_42","textTraditional":"〔七〕　李奇曰：「徇，略也。」師古曰：「音似峻反。」","sentenceOrder":29},
  {"id":"s_work_han_thu_42_30","chapterId":"ch_work_han_thu_42","textTraditional":"〔八〕　師古曰：「五縣名也。銍音竹乙反。酇音才多反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_42_31","chapterId":"ch_work_han_thu_42","textTraditional":"〔九〕　師古曰：「比音必寐反。」","sentenceOrder":31},
  {"id":"s_work_han_thu_42_32","chapterId":"ch_work_han_thu_42","textTraditional":"〔一０〕師古曰：「守，郡守也。令，縣令也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_42_33","chapterId":"ch_work_han_thu_42","textTraditional":"〔一一〕晉灼曰：「譙門，義闕。」師古曰：「守丞，謂郡丞之居守者。一曰郡守之丞，故曰守丞。譙門，謂門上為高樓以望者耳。樓一名譙，故謂美麗之樓為麗譙。譙亦呼為巢。所謂巢車者，亦於兵（革）〔車〕之上為樓以望敵也。譙巢聲相近，本一物也。今流俗書本譙下有城字，非也。此自陳耳，非譙之城。譙城前已下矣。」","sentenceOrder":33},
  {"id":"s_work_han_thu_42_34","chapterId":"ch_work_han_thu_42","textTraditional":"〔一二〕師古曰：「號令召呼之。」","sentenceOrder":34},
  {"id":"s_work_han_thu_42_35","chapterId":"ch_work_han_thu_42","textTraditional":"〔一三〕師古曰：「堅，堅甲也。銳，利兵也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_42_36","chapterId":"ch_work_han_thu_42","textTraditional":"〔一四〕劉德曰：「若云張大楚國也。」張晏曰：「先是楚為秦滅，已弛，今立楚，為張也。」師古曰：「張說是也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_42_37","chapterId":"ch_work_han_thu_42","textTraditional":"於是諸郡縣苦秦吏暴，皆殺其長吏，將以應勝。乃以廣為假王，監諸將以西擊滎陽。令陳人武臣、張耳、陳餘徇趙，汝陰人鄧宗徇九江郡。當此時，楚兵數千人為聚者不可勝數。〔一〕","sentenceOrder":37},
  {"id":"s_work_han_thu_42_38","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「聚音材喻反。」","sentenceOrder":38},
  {"id":"s_work_han_thu_42_39","chapterId":"ch_work_han_thu_42","textTraditional":"葛嬰至東城，立襄彊為楚王。〔一〕後聞勝已立，因殺襄彊，還報。至陳，勝殺嬰，令魏人周市北徇魏地。〔二〕廣圍滎陽。李由為三川守守滎陽，廣不能下。勝徵國之豪桀與計，〔三〕以上蔡人房君蔡賜為上柱國。〔四〕","sentenceOrder":39},
  {"id":"s_work_han_thu_42_40","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「東城，縣名，地理志屬九江郡。」","sentenceOrder":40},
  {"id":"s_work_han_thu_42_41","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「即梁地，非河東之魏也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_42_42","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「徵，召也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_42_43","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　鄭氏曰：「房君，官號也。姓蔡名賜。」晉灼曰：「張耳傳言相國房君是也。」師古曰：「房君者，封邑之名，非官號也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_42_44","chapterId":"ch_work_han_thu_42","textTraditional":"周文，陳賢人也，嘗為項燕軍視日，〔一〕事春申君，〔二〕自言習兵。勝與之將軍印，西擊秦。行收兵至關，車千乘，卒十萬，至戲，軍焉。〔三〕秦令少府章邯免驪山徒、人奴產子，〔四〕悉發以擊楚軍，大敗之。周文走出關，止屯曹陽。〔五〕二月餘，章邯追敗之，復走黽池。〔六〕十餘日，章邯擊，大破之。周文自剄，軍遂不戰。","sentenceOrder":44},
  {"id":"s_work_han_thu_42_45","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　文穎曰：「周文即周章也。」服虔曰：「視日旁氣也。」如淳曰：「視日時吉凶舉動之占。」師古曰：「視日，如說是也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_42_46","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　應劭曰：「楚相黃歇。」","sentenceOrder":46},
  {"id":"s_work_han_thu_42_47","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「戲，水名，在新豐東，音許宜反。解具在高紀。」","sentenceOrder":47},
  {"id":"s_work_han_thu_42_48","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　服虔曰：「家人之產奴也。」師古曰：「奴產子，猶今人云家生奴也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_42_49","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　晉灼曰：「亭名也，在弘農東十三里，魏武帝改為好陽。」師古曰：「曹水之陽也。其水出陝縣西南峴頭山而北流入河，今謂之好陽澗，在陝縣西四十五里。」","sentenceOrder":49},
  {"id":"s_work_han_thu_42_50","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　師古曰：「黽音湎。」","sentenceOrder":50},
  {"id":"s_work_han_thu_42_51","chapterId":"ch_work_han_thu_42","textTraditional":"武臣至邯鄲，自立為趙王，陳餘為大將軍，張耳、召騷為左右丞相。〔一〕勝怒，捕繫武臣等家室，欲誅之。柱國曰：「秦未亡而誅趙王將相家屬，此生一秦，〔二〕不如因立之。」勝乃遣使者賀趙，而徙繫武臣等家屬宮中。〔三〕而封張耳子敖為成都君，趣趙兵亟入關。〔四〕趙王將相相與謀曰：「王王趙，非楚意也。楚已誅秦，必加兵於趙。計莫如毋西兵，〔五〕使使北徇燕地以自廣。趙南據大河，北有燕代，楚雖勝秦，不敢制趙，若不勝秦，必重趙。〔六〕趙承秦楚之敝，可以得志於天下。」趙王以為然，因不西兵，而遣故上谷卒史韓廣將兵北徇燕。〔七〕","sentenceOrder":51},
  {"id":"s_work_han_thu_42_52","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「召讀曰邵。」","sentenceOrder":52},
  {"id":"s_work_han_thu_42_53","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「言為讎敵，與秦無異。」","sentenceOrder":53},
  {"id":"s_work_han_thu_42_54","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「徙居宮中，示優禮也。拘而不遣，故謂之繫。」","sentenceOrder":54},
  {"id":"s_work_han_thu_42_55","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「趣讀曰促。亟，急也，音居力反。」","sentenceOrder":55},
  {"id":"s_work_han_thu_42_56","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　師古曰：「勿令兵西出也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_42_57","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　師古曰：「重謂尊重也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_42_58","chapterId":"ch_work_han_thu_42","textTraditional":"〔七〕　張晏曰：「卒史，曹史也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_42_59","chapterId":"ch_work_han_thu_42","textTraditional":"燕地貴人豪桀謂韓廣曰：「楚趙皆已立王。燕雖小，亦萬乘之國也，願將軍立為王。」韓廣曰：「廣母在趙，不可。」燕人曰：「趙方西憂秦，南憂楚，其力不能禁我。且以楚之強，不敢害趙王將相之家，今趙（又）〔獨〕安敢害將軍（之）家乎？」韓廣以為然，乃自立為燕王。居數月，趙奉燕王母家屬歸之。","sentenceOrder":59},
  {"id":"s_work_han_thu_42_60","chapterId":"ch_work_han_thu_42","textTraditional":"是時，諸將徇地者不可勝數。周市北至狄，〔一〕狄人田儋殺狄令，自立為齊王，反擊周市。市軍散，還至魏地，立魏後故甯陵君咎為魏王。〔二〕咎在勝所，不得之魏。魏地已定，欲立周市為王，市不肯。使者五反，〔三〕勝乃立甯陵君為魏王，遣之國。周市為相。","sentenceOrder":60},
  {"id":"s_work_han_thu_42_61","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「縣名也，後漢安帝時改名臨濟。」","sentenceOrder":61},
  {"id":"s_work_han_thu_42_62","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　應劭曰：「魏諸公子，名咎。欲立六國後以樹黨也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_42_63","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「反謂回還也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_42_64","chapterId":"ch_work_han_thu_42","textTraditional":"將軍田臧等相與謀曰：「周章軍已破，〔一〕秦兵且至，我守滎陽城不能下，秦軍至，必大敗。不如少遺兵，足以守滎陽，〔二〕悉精兵迎秦軍。〔三〕今假王驕，不知兵權，不可與計，非誅之，事恐敗。」因相與矯陳王令以誅吳廣，〔四〕獻其首於勝。勝使賜田臧楚令尹印，使為上將。田臧乃使諸將李歸等守滎陽城，自以精兵西迎秦軍於敖倉。與戰，田臧死，軍破。章邯進擊李歸等滎陽下，破之，李歸死。","sentenceOrder":64},
  {"id":"s_work_han_thu_42_65","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　服虔曰：「周章即周文。」","sentenceOrder":65},
  {"id":"s_work_han_thu_42_66","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「遺，留也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_42_67","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「悉，盡也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_42_68","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「矯，詐也。託言受令也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_42_69","chapterId":"ch_work_han_thu_42","textTraditional":"陽城人鄧說將兵居郯，〔一〕章邯別將擊破之，鄧說走陳。銍人五逢將兵居許，章邯擊破之。五逢亦走陳。勝誅鄧說。","sentenceOrder":69},
  {"id":"s_work_han_thu_42_70","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「說讀曰悅。郯，東海縣也，音談。」","sentenceOrder":70},
  {"id":"s_work_han_thu_42_71","chapterId":"ch_work_han_thu_42","textTraditional":"勝初立時，淩人秦嘉、銍人董緤、符離人朱雞石、取慮人鄭布、徐人丁疾等皆特起，〔一〕將兵圍東海守於郯。勝聞，乃使武平君畔為將軍，〔二〕監郯下軍。秦嘉自立為大司馬，惡屬人，〔三〕告軍吏曰：「武平君年少，不知兵事，勿聽。」因矯以王命殺武平君畔。","sentenceOrder":71},
  {"id":"s_work_han_thu_42_72","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　張晏曰：「淩，泗水縣也。銍、符離，沛縣也。取慮、徐，臨淮縣也。」師古曰：「緤音先列反。取音趨，又音秋。慮音廬。」","sentenceOrder":72},
  {"id":"s_work_han_thu_42_73","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　張晏曰：「畔，名也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_42_74","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「不欲統屬於人。」","sentenceOrder":74},
  {"id":"s_work_han_thu_42_75","chapterId":"ch_work_han_thu_42","textTraditional":"章邯已破五逢，擊陳，柱國房君死。章邯又進擊陳西張賀軍。勝出臨戰，軍破，張賀死。","sentenceOrder":75},
  {"id":"s_work_han_thu_42_76","chapterId":"ch_work_han_thu_42","textTraditional":"臘月，〔一〕勝之汝陰，還至下城父，〔二〕其御莊賈殺勝以降秦。葬碭，諡曰隱王。","sentenceOrder":76},
  {"id":"s_work_han_thu_42_77","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　張晏曰：「秦之臘月，夏之九月。」臣瓚曰：「建丑之月也。」師古曰：「史記云胡亥二年十月誅葛嬰，十一月周文死，十二月陳涉死。瓚說是也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_42_78","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「下城父，地名，在城父縣東。父音甫。」","sentenceOrder":78},
  {"id":"s_work_han_thu_42_79","chapterId":"ch_work_han_thu_42","textTraditional":"勝故涓人將軍呂臣為蒼頭軍，〔一〕起新陽，〔二〕攻陳下之，殺莊賈，復以陳為楚。","sentenceOrder":79},
  {"id":"s_work_han_thu_42_80","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　應劭曰：「涓人，如謁者。將軍姓呂名臣也。時軍皆著青巾，故曰蒼頭。」服虔曰：「蒼頭謂士卒青帛巾，若赤眉之號，以相別也。」師古曰：「涓，潔也。涓人，主潔除之人。涓音蠲。」","sentenceOrder":80},
  {"id":"s_work_han_thu_42_81","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「縣名也，屬汝南郡。」","sentenceOrder":81},
  {"id":"s_work_han_thu_42_82","chapterId":"ch_work_han_thu_42","textTraditional":"初，勝令銍人宋留將兵定南陽，入武關。留已徇南陽，聞勝死，南陽復為秦。〔一〕宋留不能入武關，乃東至新蔡，遇秦軍，宋留以軍降秦。秦傳留至咸陽，車裂留以徇。〔二〕","sentenceOrder":82},
  {"id":"s_work_han_thu_42_83","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「為音于偽反。」","sentenceOrder":83},
  {"id":"s_work_han_thu_42_84","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「徇，行示也，以示眾為戒。徇音辭峻反。」","sentenceOrder":84},
  {"id":"s_work_han_thu_42_85","chapterId":"ch_work_han_thu_42","textTraditional":"秦嘉等聞勝軍敗，乃立景駒為楚王，引兵之方與，〔一〕欲擊秦軍濟陰下。使公孫慶使齊王，欲與并力俱進。齊王曰：「陳王戰敗，未知其死生，楚安得不請而立王？」公孫慶曰：「齊不請楚而立王，楚何故請齊而立王？且楚首事，當令於天下。」〔二〕田儋殺公孫慶。","sentenceOrder":85},
  {"id":"s_work_han_thu_42_86","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「之，往也。方與，縣名也。方音房。與音豫。」","sentenceOrder":86},
  {"id":"s_work_han_thu_42_87","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「首事，謂最先（兵起）〔起兵〕。」","sentenceOrder":87},
  {"id":"s_work_han_thu_42_88","chapterId":"ch_work_han_thu_42","textTraditional":"秦左右校復攻陳，下之。呂將軍走，徼兵復聚，〔一〕與番盜英布相遇，〔二〕攻擊秦左右校，破之青波，〔三〕復以陳為楚。會項梁立懷王孫心為楚王。","sentenceOrder":88},
  {"id":"s_work_han_thu_42_89","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　如淳曰：「徼，要也。徼（要）散卒復相聚斂也。」師古曰：「徼音工堯反。」","sentenceOrder":89},
  {"id":"s_work_han_thu_42_90","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「番即番陽縣也。於番為盜，故曰番盜。番音蒲何反。其後番字改作鄱。」","sentenceOrder":90},
  {"id":"s_work_han_thu_42_91","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　文穎曰：「地名也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_42_92","chapterId":"ch_work_han_thu_42","textTraditional":"陳勝王凡六月。初為王，其故人嘗與傭耕者聞之，乃之陳，叩宮門曰：「吾欲見涉。」宮門令欲縛之。自辯數，乃置，〔一〕不肯為通。勝出，遮道而呼涉。〔二〕乃召見，載與歸。入宮，見殿屋帷帳，客曰：「夥，涉之為王沈沈者！」〔三〕楚人謂多為夥，故天下傳之，「夥涉為王」，由陳涉始。客出入愈益發舒，言勝故情。或言「客愚無知，專妄言，輕威。」勝斬之。諸故人皆自引去，由是無親勝者。以朱防為中正，胡武為司過，主司群臣。諸將徇地，至，令之不是者，繫而罪之。以苛察為忠。其所不善者，不下吏，輒自治。〔四〕勝信用之，諸將以故不親附。此其所以敗也。","sentenceOrder":92},
  {"id":"s_work_han_thu_42_93","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「辯數，謂自分別其姓名也，并歷道與涉故舊之事，故舍而不縛也。數音山羽反。」","sentenceOrder":93},
  {"id":"s_work_han_thu_42_94","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「呼謂大喚也，音火故反。」","sentenceOrder":94},
  {"id":"s_work_han_thu_42_95","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　應劭曰：「夥音禍。沈沈，宮室深邃之貌也。沈音長含反。」","sentenceOrder":95},
  {"id":"s_work_han_thu_42_96","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「不以付吏，而防、武自治之。」","sentenceOrder":96},
  {"id":"s_work_han_thu_42_97","chapterId":"ch_work_han_thu_42","textTraditional":"勝雖已死，其所置遣侯王將相竟亡秦。高祖時為勝置守冢于碭，至今血食。王莽敗，乃絕。〔一〕","sentenceOrder":97},
  {"id":"s_work_han_thu_42_98","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「至今血食者，司馬遷作史記本語也。莽敗乃絕者，班固之詞也。於文為衍，蓋失不刪耳。」","sentenceOrder":98},
  {"id":"s_work_han_thu_42_99","chapterId":"ch_work_han_thu_42","textTraditional":"項籍字羽，下相人也。〔一〕初起，年二十四。其季父梁，梁父即楚名將項燕者也。家世楚將，封於項，〔二〕故姓項氏。","sentenceOrder":99},
  {"id":"s_work_han_thu_42_100","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　韋昭曰：「臨淮縣。」","sentenceOrder":100},
  {"id":"s_work_han_thu_42_101","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古：「即今項城縣。」","sentenceOrder":101},
  {"id":"s_work_han_thu_42_102","chapterId":"ch_work_han_thu_42","textTraditional":"籍少時，學書不成，去；學劍又不成，去。梁怒之。籍曰：「書足記姓名而已。劍一人敵，不足學，學萬人敵耳。」於是梁奇其意，乃教以兵法。籍大喜，略知其意，又不肯竟。梁嘗有櫟陽逮，請蘄獄掾曹咎書抵櫟陽獄史司馬欣，以故事皆已。〔一〕梁嘗殺人，與籍避仇吳中。吳中賢士大夫皆出梁下。〔二〕每有大繇役及喪，梁常主辦，陰以兵法部勒賓客子弟，以知其能。秦始皇帝東遊會稽，渡浙江，〔三〕梁與籍觀。籍曰：「彼可取而代也。」梁掩其口，曰：「無妄言，族矣！」〔四〕梁以此奇籍。籍長八尺二寸，力扛鼎，〔五〕才氣過人。吳中（弟子）〔子弟〕皆憚籍。","sentenceOrder":102},
  {"id":"s_work_han_thu_42_103","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　應劭曰：「項梁曾坐事傳繫櫟陽獄，從蘄獄掾曹咎取書與司馬欣。抵，相歸抵也。已，止也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_42_104","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「言皆不及也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_42_105","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　應劭曰：「浙音折。」晉灼曰：「江水至會稽山陰為浙江。」","sentenceOrder":105},
  {"id":"s_work_han_thu_42_106","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「凡言族者，謂族誅之。」","sentenceOrder":106},
  {"id":"s_work_han_thu_42_107","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　師古曰：「扛，舉也，音江。」","sentenceOrder":107},
  {"id":"s_work_han_thu_42_108","chapterId":"ch_work_han_thu_42","textTraditional":"秦二世元年，陳勝起。九月，會稽假守通〔一〕素賢梁，乃召與計事。梁曰：「方今江西皆反秦，此亦天亡秦時也。先發制人，後發制於人。」守歎曰：「聞夫子楚將世家，唯足下耳！」梁曰：「吳有奇士桓楚，亡在澤中，人莫知其處，獨籍知之。」梁乃戒籍持劍居外待。梁復入，與守語曰：「請召籍，使受令召桓楚。」籍入，梁眴籍曰：「可行矣！」〔二〕籍遂拔劍擊斬守。梁持守頭，佩其印綬。門下驚擾，籍所擊殺數十百人。〔三〕府中皆讋伏，莫敢復起。〔四〕梁乃召故人所知豪吏，諭以所為，〔五〕遂舉吳中兵。使人收下縣，〔六〕得精兵八千人，部署豪桀為校尉、候、司馬。〔七〕有一人不得官，自言。梁曰：「某時某喪，使公主某事，不能辦，以故不任公。」眾乃皆服。梁為會稽將，籍為裨將，〔八〕徇下縣。","sentenceOrder":108},
  {"id":"s_work_han_thu_42_109","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　張晏曰：「假守，兼守也。」，晉灼曰：「楚漢春秋云姓殷。」","sentenceOrder":109},
  {"id":"s_work_han_thu_42_110","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「眴，動目也，音舜，動目而使之也。今書本有作眄字者，流俗所改耳。」","sentenceOrder":110},
  {"id":"s_work_han_thu_42_111","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「數十百人者，八九十乃至百也。他皆類此。」","sentenceOrder":111},
  {"id":"s_work_han_thu_42_112","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「讋，失氣也，音章涉反。」","sentenceOrder":112},
  {"id":"s_work_han_thu_42_113","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　師古曰：「諭，曉告之。」","sentenceOrder":113},
  {"id":"s_work_han_thu_42_114","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　師古曰：「四面諸縣也。非郡所都，故謂之下也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_42_115","chapterId":"ch_work_han_thu_42","textTraditional":"〔七〕　師古曰：「分部而署置之。」","sentenceOrder":115},
  {"id":"s_work_han_thu_42_116","chapterId":"ch_work_han_thu_42","textTraditional":"〔八〕　師古曰：「裨，助也，相副助也。裨音頻移反。他皆類此。」","sentenceOrder":116},
  {"id":"s_work_han_thu_42_117","chapterId":"ch_work_han_thu_42","textTraditional":"秦二年，廣陵人召平為陳勝徇廣陵，〔一〕未下。聞陳勝敗走，秦將章邯且至，乃渡江矯陳王令，拜梁為楚上柱國，曰：「江東已定，急引兵西擊秦。」梁乃以八千人渡江而西。聞陳嬰已下東陽，使使欲與連和俱西。陳嬰者，故東陽令史，〔二〕居縣，素信，為長者。〔三〕東陽少年殺其令，相聚數千人，欲立長，無適用，〔四〕乃請陳嬰。嬰謝不能，遂強立之，縣中從之者得二萬人。欲立嬰為王，異軍蒼頭特起。〔五〕嬰母謂嬰曰：「自吾為乃家婦，聞先故未曾貴。〔六〕今暴得大名，不祥。不如有所屬，事成猶得封侯，事敗易以亡，非世所指名也。」嬰乃不敢為王，謂其軍〔吏〕曰：「項氏世世將家，有名於楚，今欲舉大事，將非其人，不可。〔七〕我倚名族，亡秦必矣。」〔八〕其眾從之，乃以其兵屬梁。梁渡淮，英布、蒲將軍亦以其兵屬焉。〔九〕凡六七萬人，軍下邳。","sentenceOrder":117},
  {"id":"s_work_han_thu_42_118","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「召讀曰邵。」","sentenceOrder":118},
  {"id":"s_work_han_thu_42_119","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　蘇林曰：「曹史也。」晉灼曰：「漢儀注令（史）〔吏〕曰令史，丞（史）〔吏〕曰丞史。」師古曰：「晉說是也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_42_120","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「素立恩信，號為長者。」","sentenceOrder":120},
  {"id":"s_work_han_thu_42_121","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「適，主也，音與的同。」","sentenceOrder":121},
  {"id":"s_work_han_thu_42_122","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　應劭曰：「言與眾異也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_42_123","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　師古曰：「乃，汝也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_42_124","chapterId":"ch_work_han_thu_42","textTraditional":"〔七〕　師古曰：「言以不材之人為將，不可求勝也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_42_125","chapterId":"ch_work_han_thu_42","textTraditional":"〔八〕　師古曰：「倚，依也，音於綺反。」","sentenceOrder":125},
  {"id":"s_work_han_thu_42_126","chapterId":"ch_work_han_thu_42","textTraditional":"〔九〕　服虔曰：「英布起於蒲地，因以為號也。」如淳曰：「史記項羽紀言當陽君、蒲將軍皆屬項羽，（自比）〔此自〕更有蒲將軍也。」師古曰：「此二人也，服說失之。若是一人，不當先言姓名，後乃稱將軍也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_42_127","chapterId":"ch_work_han_thu_42","textTraditional":"是時，秦嘉已立景駒為楚王，軍彭城東，欲以距梁。梁謂軍吏曰：「陳王首事，戰不利，未聞所在。今秦嘉背陳王立景駒，大逆亡道。」乃引兵擊秦嘉。〔嘉〕軍敗走，追至胡陵。嘉還戰〔一〕一日，嘉死，軍降。景駒走死梁地。梁已并秦嘉軍，〔軍〕胡陵，將引而西。章邯至栗，〔二〕梁使別將朱雞石、餘樊君與戰。餘樊君死。朱雞石敗，亡走胡陵。梁乃引兵入薛，誅朱雞石。梁前使羽別攻襄城，襄城堅守不下。已拔，皆阬之，〔三〕還報梁。聞陳王定死，召諸別將會薛計事。時沛公亦從沛往。","sentenceOrder":127},
  {"id":"s_work_han_thu_42_128","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「復來戰。」","sentenceOrder":128},
  {"id":"s_work_han_thu_42_129","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「栗，縣名。地理志屬沛郡。」","sentenceOrder":129},
  {"id":"s_work_han_thu_42_130","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「陷之於阬，盡殺之。」","sentenceOrder":130},
  {"id":"s_work_han_thu_42_131","chapterId":"ch_work_han_thu_42","textTraditional":"居鄛人范增〔一〕年七十，素好奇計，往說梁曰：「陳勝敗固當。〔二〕夫秦滅六國，楚最亡罪，自懷王入秦不反，楚人憐之至今，故南公稱曰『楚雖三戶，亡秦必楚』。〔三〕今陳勝首事，不立楚後，其勢不長。今君起江東，楚蠭起之將皆爭附君者，〔四〕以君世世楚將，為能復立楚之後也。」於是梁乃求楚懷王孫心，在民間為人牧羊，立以為楚懷王，從民望也。陳嬰為上柱國，封五縣。與懷王都盱台。〔五〕梁自號武信君，引兵攻亢父。〔六〕","sentenceOrder":131},
  {"id":"s_work_han_thu_42_132","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　晉灼曰：「鄛音鄛絕之鄛。」師古曰：「居鄛，縣名也，地理志屬廬江郡。鄛音巢，字亦作巢。本春秋時巢國。」","sentenceOrder":132},
  {"id":"s_work_han_thu_42_133","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「言其計畫非是，宜應敗也。」","sentenceOrder":133},
  {"id":"s_work_han_thu_42_134","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　服虔曰：「南公，南方之老人也。」蘇林曰：「但令有三戶在，其怨深，足以亡秦。」","sentenceOrder":134},
  {"id":"s_work_han_thu_42_135","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「蠭，古蜂字也。蠭起，如蠭之起，言其眾也。一說蠭與鋒同，言鋒銳而起者。」","sentenceOrder":135},
  {"id":"s_work_han_thu_42_136","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　師古曰：「盱音許于反。台音怡。」","sentenceOrder":136},
  {"id":"s_work_han_thu_42_137","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　師古曰：「亢音抗。父音甫。」","sentenceOrder":137},
  {"id":"s_work_han_thu_42_138","chapterId":"ch_work_han_thu_42","textTraditional":"初，章邯既殺齊王田儋於臨菑，〔一〕田假復自立為齊王。儋弟榮走保東阿，章邯追圍之。梁引兵救東阿，大破秦軍東阿，田榮即引兵歸，逐王假。假亡走楚，相田角亡走趙。角弟閒，故將，居趙不敢歸。田榮立儋子市為齊王。梁已破東阿下軍，遂追秦軍。數使使趣齊兵俱西。〔二〕榮曰：「楚殺田假，趙殺田角、田閒，乃發兵。」梁曰：「田假與國之王，〔三〕窮來歸我，不忍殺。」趙亦不殺角、閒以市於齊。〔四〕齊遂不肯發兵助楚。梁使羽與沛公別攻城陽，屠之。西破秦軍濮陽東，秦兵收入濮陽。沛公、羽攻定陶。定陶未下，去，西略地至雍丘，大破秦軍，斬李由。還攻外黃，外黃未下。","sentenceOrder":138},
  {"id":"s_work_han_thu_42_139","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「高紀及儋傳並言於臨濟，此獨言臨菑，疑此誤也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_42_140","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「趣讀曰促。」","sentenceOrder":140},
  {"id":"s_work_han_thu_42_141","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　張晏曰：「與，黨與也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_42_142","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　張晏曰：「若市買相貿易以利也。」梁救榮難，榮猶不用命。梁念殺假等，榮未必多出兵，不如待以（初）〔禮〕，又可以貿易他利，以除己害，遂背德，可輔假以伐齊，故曰市。市，貿易也。」晉灼曰：「欲令楚殺田假，以為己利，而楚保全不殺，以買其計，故曰市也。」師古曰：「二說皆非也。市者，以角、閒市取齊兵也，直言趙不殺角、閒以求齊兵耳。」","sentenceOrder":142},
  {"id":"s_work_han_thu_42_143","chapterId":"ch_work_han_thu_42","textTraditional":"梁起東阿，比至定陶，再破秦軍，〔一〕羽等又斬李由，益輕秦，有驕色。宋義諫曰：「戰勝而將驕卒惰者敗。今少惰矣，秦兵日益，臣為君畏之。」梁不聽。乃使宋義於齊。道遇齊使者高陵君顯〔二〕，曰：「公將見武信君乎？」曰：「然。」義曰：「臣論武信君軍必敗。公徐行則免，疾行則及禍。」秦果悉起兵益章邯，夜銜枚擊楚，大破之定陶，〔三〕梁死。沛公與羽去外黃，攻陳留，陳留堅守不下。沛公、羽相與謀曰：「今梁軍敗，士卒恐。」乃與呂臣俱引兵而東。呂臣軍彭城東，羽軍彭城西，沛公軍碭。","sentenceOrder":143},
  {"id":"s_work_han_thu_42_144","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「比音必寐反。」","sentenceOrder":144},
  {"id":"s_work_han_thu_42_145","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　張晏曰：「名顯，封於高陵。」晉灼曰：「高陵，瑯邪縣也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_42_146","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「銜枚，解在高紀。」","sentenceOrder":146},
  {"id":"s_work_han_thu_42_147","chapterId":"ch_work_han_thu_42","textTraditional":"章邯已破梁軍，則以為楚地兵不足憂，乃渡河北擊趙，大破之。當此之時，趙歇為王，陳餘為將，張耳為相，走入鉅鹿城。〔一〕秦將王離、涉閒圍鉅鹿，〔二〕章邯軍其南，築甬道而輸之粟。〔三〕陳餘將卒數萬人軍鉅鹿北，所謂河北軍也。","sentenceOrder":147},
  {"id":"s_work_han_thu_42_148","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「趙歇、張耳共入鉅鹿也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_42_149","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　張晏曰：「秦二將也。王離，王翦孫。涉，姓；閒，名也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_42_150","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「章邯為甬道而運粟，以饟王離、涉閒之軍。」","sentenceOrder":150},
  {"id":"s_work_han_thu_42_151","chapterId":"ch_work_han_thu_42","textTraditional":"宋義所遇齊使者高陵君顯見楚懷王曰：「宋義論武信君必敗，數日果敗。軍未戰先見敗徵，〔一〕可謂知兵矣。」王召宋義與計事而說之，〔二〕因以為上將軍；羽為魯公，為次將，范增為末將。諸別將皆屬，號卿子冠軍。〔三〕北救趙，至安陽，留不進。〔四〕秦三年，羽謂宋義曰：「今秦軍圍鉅鹿，疾引兵渡河，楚擊其外，趙應其內，破秦軍必矣。」宋義曰：「不然。夫搏牛之虻不可以破蝨。〔五〕今秦攻趙，戰勝則兵罷，我承其敝；〔六〕不勝，則我引兵鼓行而西，必舉秦矣。〔七〕故不如先鬥秦、趙。夫擊輕銳，我不如公；坐運籌策，公不如我。」因下令軍中曰：「猛如虎，佷如羊，貪如狼，強不可令者，皆斬。」遣其子襄相齊，身送之無鹽，〔八〕飲酒高會。〔九〕天寒大雨，士卒凍飢。羽曰：「將戮力而攻秦，久留不行。今歲飢民貧，卒食半菽，〔一０〕軍無見糧，〔一一〕乃飲酒高會，不引兵渡河因趙食，與并力擊秦，乃曰『承其敝』。夫以秦之強，攻新造之趙，其勢必舉趙。趙舉秦強，何敝之承！且國兵新破，王坐不安席，掃境內而屬將軍，〔一二〕國家安危，在此一舉。今不卹士卒而徇私（宴），非社稷之臣也。」羽晨朝上將軍宋義，即其帳中斬義頭。〔一三〕出令軍中曰：「宋義與齊謀反楚，楚王陰令籍誅之。」諸將讋服，〔一四〕莫敢枝梧。〔一五〕皆曰：「首立楚者，將軍家也。今將軍誅亂。」乃相與共立羽為假上將軍。〔一六〕使人追宋義子，及之齊，殺之。使桓楚報命於王。王因使使立羽為上將軍。","sentenceOrder":151},
  {"id":"s_work_han_thu_42_152","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「徵，證也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_42_153","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":153},
  {"id":"s_work_han_thu_42_154","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「冠軍，言其在諸軍之上。」","sentenceOrder":154},
  {"id":"s_work_han_thu_42_155","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「今相州安陽縣。」","sentenceOrder":155},
  {"id":"s_work_han_thu_42_156","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　張晏曰：「搏音博。」蘇林曰：「虻喻秦，蝨喻章邯等，言小大不同勢，欲滅秦當寬邯等也。」如淳曰：「猶言本欲以大力伐秦，而不可以救趙也。」師古曰：「搏，擊也，言以手擊牛之背，可以殺其上虻，而不能破蝨，喻今將兵方欲滅秦，不可盡力與章邯即戰。或未能禽，徒費力也。如說近也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_42_157","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　師古曰：「罷讀曰疲。」","sentenceOrder":157},
  {"id":"s_work_han_thu_42_158","chapterId":"ch_work_han_thu_42","textTraditional":"〔七〕　師古曰：「鼓行，謂擊鼓而行，無畏懼也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_42_159","chapterId":"ch_work_han_thu_42","textTraditional":"〔八〕　師古曰：「縣名。」","sentenceOrder":159},
  {"id":"s_work_han_thu_42_160","chapterId":"ch_work_han_thu_42","textTraditional":"〔九〕　師古曰：「高會，大會也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_42_161","chapterId":"ch_work_han_thu_42","textTraditional":"〔一０〕孟康曰：「半，五升器名也。」臣瓚曰：「土卒食蔬菜以菽雜半之。」師古曰：「瓚說是也。菽謂豆也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_42_162","chapterId":"ch_work_han_thu_42","textTraditional":"〔一一〕師古曰：「無見在之糧。」","sentenceOrder":162},
  {"id":"s_work_han_thu_42_163","chapterId":"ch_work_han_thu_42","textTraditional":"〔一二〕師古曰：「屬，委也，音之欲反。」","sentenceOrder":163},
  {"id":"s_work_han_thu_42_164","chapterId":"ch_work_han_thu_42","textTraditional":"〔一三〕師古曰：「即，就也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_42_165","chapterId":"ch_work_han_thu_42","textTraditional":"〔一四〕師古曰：「讋，失氣也，音之涉反。」","sentenceOrder":165},
  {"id":"s_work_han_thu_42_166","chapterId":"ch_work_han_thu_42","textTraditional":"〔一五〕如淳曰：「梧音悟。枝梧猶枝扞也。」臣瓚曰：「小柱為枝，邪柱為梧，今屋梧邪柱是也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_42_167","chapterId":"ch_work_han_thu_42","textTraditional":"〔一六〕師古曰：「未得懷王之命，故且為假也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_42_168","chapterId":"ch_work_han_thu_42","textTraditional":"羽已殺卿子冠軍，威震楚國，名聞諸侯。乃遣當陽君、蒲將軍將卒二萬人渡河救鉅鹿。戰少利，陳餘復請兵。羽乃悉引兵渡河。已渡，皆湛舡，〔一〕破釜甑，燒廬舍，持三日糧，視士必死，無還心。〔二〕於是至則圍王離，與秦軍遇，九戰，絕甬道，大破之，殺蘇角，〔三〕虜王離。涉閒不降，自燒殺。當是時，楚兵冠諸侯。〔四〕諸侯軍救鉅鹿者十餘壁，莫敢縱兵。及楚擊秦，諸侯皆從壁上觀。楚戰士無不一當十，呼聲動天地。諸侯軍人人惴恐。〔六〕於是楚已破秦軍，羽見諸侯將，入轅門，〔七〕膝行而前，莫敢仰視。羽繇是始為諸侯上將軍，〔八〕兵皆屬焉。","sentenceOrder":168},
  {"id":"s_work_han_thu_42_169","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「湛讀曰沈，謂沈沒其舡於水中。」","sentenceOrder":169},
  {"id":"s_work_han_thu_42_170","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「視讀曰示。」","sentenceOrder":170},
  {"id":"s_work_han_thu_42_171","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　文穎曰：「秦將。」","sentenceOrder":171},
  {"id":"s_work_han_thu_42_172","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「言最為上也。」","sentenceOrder":172},
  {"id":"s_work_han_thu_42_173","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　師古曰：「呼音火故反。」","sentenceOrder":173},
  {"id":"s_work_han_thu_42_174","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　服虔曰：「惴音章瑞反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_42_175","chapterId":"ch_work_han_thu_42","textTraditional":"〔七〕張晏曰：「軍行以車為陳，轅相向為門，故曰轅門。」　師古曰：「周禮掌舍，王行則『設車宮轅門』也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_42_176","chapterId":"ch_work_han_thu_42","textTraditional":"〔八〕師古曰：「繇讀與由同。」","sentenceOrder":176},
  {"id":"s_work_han_thu_42_177","chapterId":"ch_work_han_thu_42","textTraditional":"章邯軍棘原，〔一〕羽軍漳南，相持未戰。秦軍數卻，〔二〕二世使人讓章邯。〔三〕章邯恐，使長史欣請事。至咸陽，留司馬門三日，〔四〕趙高不見，有不信之心。長史欣恐，還走，不敢出故道。趙高果使人追之，不及。欣至軍，報曰：「事亡可為者。〔五〕相國趙高顓國主斷。〔六〕今戰而勝，高嫉吾功；不勝，不免於死。願將軍熟計之。」陳餘亦遺章邯書曰：「白起為秦將，南并鄢郢，北阬馬服，〔七〕攻城略地，不可勝計，而卒賜死。〔八〕蒙恬為秦將，北逐戎人，開榆中地數（十）〔千〕里，〔九〕竟斬陽周。〔一０〕何者？功多，秦不能封，因以法誅之。今將軍為秦將三歲矣，所亡失已十萬數，而諸侯並起茲益多。彼趙高素諛日久，〔一一〕今事急，亦恐二世誅之，故欲以法誅將軍以塞責，〔一二〕使人更代以脫其禍。〔一三〕將軍居外久，多內隙，有功亦誅，亡功亦誅。且天之亡秦，無愚智皆知之。今將軍內不能直諫，外為亡國將，孤立而欲長存，豈不哀哉！將軍何不還兵與諸侯為從，〔一四〕南面稱孤，孰與身伏斧質，妻子為戮乎？」〔一五〕章邯狐疑，陰使候始成使羽，欲約〔一六〕。約未成，羽使蒲將軍引兵渡三戶，〔一七〕軍漳南，與秦戰，再破之。羽悉引兵擊秦軍汙水上，〔一八〕大破之。","sentenceOrder":177},
  {"id":"s_work_han_thu_42_178","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕晉灼曰：「地名，在鉅鹿南。」","sentenceOrder":178},
  {"id":"s_work_han_thu_42_179","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「卻，退也，音丘略反。」","sentenceOrder":179},
  {"id":"s_work_han_thu_42_180","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「讓謂責也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_42_181","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「凡言司馬門者，宮垣之內兵衛所在，四面皆有司馬。司馬主武事，故總謂宮之外門為司馬門。」","sentenceOrder":181},
  {"id":"s_work_han_thu_42_182","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　師古曰：「言不可復為軍旅之事。」","sentenceOrder":182},
  {"id":"s_work_han_thu_42_183","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　師古曰：「顓與專同也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_42_184","chapterId":"ch_work_han_thu_42","textTraditional":"〔七〕　服虔曰：「馬服，趙括也。父奢為趙將，有功，賜號馬服。馬服猶服馬也，故世稱之。」師古曰：「鄢郢，皆楚邑也。鄢音偃。郢音弋井反。」","sentenceOrder":184},
  {"id":"s_work_han_thu_42_185","chapterId":"ch_work_han_thu_42","textTraditional":"〔八〕　師古曰：「卒，終也。」","sentenceOrder":185},
  {"id":"s_work_han_thu_42_186","chapterId":"ch_work_han_thu_42","textTraditional":"〔九〕　服虔曰：「金城縣治也。」蘇林曰：「在上郡。」師古曰：「即今之榆林，古者上郡界。蘇說是也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_42_187","chapterId":"ch_work_han_thu_42","textTraditional":"〔一０〕孟康曰：「縣名也，屬上郡。」晉灼曰：「恬賜死，死於此縣。」","sentenceOrder":187},
  {"id":"s_work_han_thu_42_188","chapterId":"ch_work_han_thu_42","textTraditional":"〔一一〕師古曰：「諛，諂也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_42_189","chapterId":"ch_work_han_thu_42","textTraditional":"〔一二〕師古曰：「塞，當也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_42_190","chapterId":"ch_work_han_thu_42","textTraditional":"〔一三〕師古曰：「脫，免也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_42_191","chapterId":"ch_work_han_thu_42","textTraditional":"〔一四〕文穎曰：「關東為從，關西為橫。」孟康曰：「南北為從，東西為橫。」師古曰：「言欲如六國時共敵秦。二說皆是也。還兵謂迴兵內嚮以攻秦也。從音子容反。」","sentenceOrder":191},
  {"id":"s_work_han_thu_42_192","chapterId":"ch_work_han_thu_42","textTraditional":"〔一五〕師古曰：「質謂鍖也。古者斬人，加於鍖上而斫之也。鍖音竹林反。」","sentenceOrder":192},
  {"id":"s_work_han_thu_42_193","chapterId":"ch_work_han_thu_42","textTraditional":"〔一六〕鄭氏曰：「候，軍候也。始，姓；成，名也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_42_194","chapterId":"ch_work_han_thu_42","textTraditional":"〔一七〕服虔曰：「漳水津也。」孟康曰：「在鄴西三十里。」","sentenceOrder":194},
  {"id":"s_work_han_thu_42_195","chapterId":"ch_work_han_thu_42","textTraditional":"〔一八〕師古曰：「汙水在鄴西南，音于。」","sentenceOrder":195},
  {"id":"s_work_han_thu_42_196","chapterId":"ch_work_han_thu_42","textTraditional":"邯使使見羽，欲約。羽召軍吏謀曰：「糧少，欲聽其約。」軍吏皆曰：「善。」羽乃與盟洹水南殷虛上。〔一〕已盟，章邯見羽流涕，為言趙高。羽乃立章邯為雍王，置軍中。使長史欣為上將，將秦軍行前。〔二〕","sentenceOrder":196},
  {"id":"s_work_han_thu_42_197","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　應劭曰：「洹水在湯陰界。殷虛，故殷都也。」師古曰：「洹水出林慮縣東北，至于長樂入清水。洹音桓，俗音袁，非也。虛讀曰墟。」","sentenceOrder":197},
  {"id":"s_work_han_thu_42_198","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「行前，謂居前而行。」","sentenceOrder":198},
  {"id":"s_work_han_thu_42_199","chapterId":"ch_work_han_thu_42","textTraditional":"漢元年，羽將諸侯兵三十餘萬，行略地至河南，遂西到新安〔一〕。異時諸侯吏卒徭役屯戍過秦中，〔二〕秦中遇之多亡狀，〔三〕及秦軍降諸侯，諸侯吏卒乘勝奴虜使之，輕（重）折辱秦吏卒。吏卒多竊言〔曰〕：「章將軍〔等〕詐吾屬降諸侯，今能入關破秦，大善；即不能，諸侯虜吾屬而東，秦又盡誅吾父毌妻子。」諸將微聞其計，以告羽。羽乃召英布、蒲將軍計曰：「秦吏卒尚眾，其心不服，至關不聽，事必危，不如擊之，獨與章邯、長史欣、都尉翳入秦。」於是夜擊阬秦軍二十餘萬人。","sentenceOrder":199},
  {"id":"s_work_han_thu_42_200","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「今穀州新安城是。」","sentenceOrder":200},
  {"id":"s_work_han_thu_42_201","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「異時猶言先時也。秦中，關中秦地也。」","sentenceOrder":201},
  {"id":"s_work_han_thu_42_202","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「無善形狀也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_42_203","chapterId":"ch_work_han_thu_42","textTraditional":"至函谷關，有兵守，不得入。聞沛公已屠咸陽，羽大怒，使當陽君擊關。羽遂入，至戲西鴻門，聞沛公欲王關中，獨有秦府庫珍寶。亞父范增亦大怒，勸羽擊沛公。饗士，旦日合戰。羽季父項伯素善張良。良時從沛公，項伯夜以語良。良與俱見沛公，因伯自解於羽〔一〕。明日，沛公從百餘騎至鴻門謝羽，自陳「封秦府庫，還軍霸上以待大王，閉關以備他盜，不敢背德。」羽意既解，范增欲害沛公，賴張良、樊噲得免。語在高紀。","sentenceOrder":203},
  {"id":"s_work_han_thu_42_204","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕師古曰：「自解，猶今言分疏也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_42_205","chapterId":"ch_work_han_thu_42","textTraditional":"後數日，羽乃屠咸陽，殺秦降王子嬰，燒其宮室，火三月不滅；收其寶貨，略婦女而東。秦民失望。〔一〕於是韓生說羽曰：「關中阻山帶河，四塞之地，肥饒，可都以伯。」〔二〕羽見秦宮室皆已燒殘，又懷思東歸，曰：「富貴不歸故鄉，如衣錦夜行。」〔三〕韓生曰：「人謂楚人沐猴而冠，果然。」〔四〕羽聞之，斬韓生。","sentenceOrder":205},
  {"id":"s_work_han_thu_42_206","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「沛公入關，儉節自處，約法三章，反秦之政。而項羽屠殺焚燒，恣其殘酷，故關中之人失所望也。」","sentenceOrder":206},
  {"id":"s_work_han_thu_42_207","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「伯讀曰霸。」","sentenceOrder":207},
  {"id":"s_work_han_thu_42_208","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「言無人見之，不榮顯矣。」","sentenceOrder":208},
  {"id":"s_work_han_thu_42_209","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　張晏曰：「沐猴，獮猴也。」師古曰：「言雖著人衣冠，其心不類人也。果然，果如人之言也。」","sentenceOrder":209},
  {"id":"s_work_han_thu_42_210","chapterId":"ch_work_han_thu_42","textTraditional":"初，懷王與諸將約，先入關者王其地。羽既背約。使人致命於懷王。懷王曰：「如約。」羽乃曰：「懷王者，吾家武信君所立耳，非有功伐，〔一〕何以得顓主約？〔二〕天下初發難，〔三〕假立諸侯後以伐秦。然身被堅執銳首事，暴露於野三年，滅秦定天下者，皆將相諸君與籍力也。懷王亡功，固當分其地王之。」諸將皆曰：「善。」羽乃陽尊懷王為義帝，曰：「古之王者，地方千里，必居上游。」〔四〕徙之長沙，都郴。〔五〕乃分天下以王諸侯。","sentenceOrder":210},
  {"id":"s_work_han_thu_42_211","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　張晏曰：「積功曰伐。」","sentenceOrder":211},
  {"id":"s_work_han_thu_42_212","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「顓與專同。」","sentenceOrder":212},
  {"id":"s_work_han_thu_42_213","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　服虔曰：「兵初起時也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_42_214","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　文穎曰：「居水之上流也。游或作流。」師古曰：「游即流也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_42_215","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　師古曰：「郴音丑林反。」","sentenceOrder":215},
  {"id":"s_work_han_thu_42_216","chapterId":"ch_work_han_thu_42","textTraditional":"羽與范增疑沛公，業已講解，〔一〕又惡背約，恐諸侯叛之，陰謀曰：「巴、蜀道險，秦之遷民皆居之。」乃曰：「巴、蜀亦關中地。」故立沛公為漢王，王巴、蜀、漢中。而參分關中，王秦降將以距塞漢道。乃立章邯為雍王，王咸陽以西。長史司馬欣，故櫟陽獄吏，嘗有德於梁；都尉董翳，本勸章邯降。故立欣為塞王，王咸陽以東至河；立翳為翟王，王上郡。徙魏王豹為西魏王，王河東。瑕丘公申陽者，張耳嬖臣也，〔三〕先下河南，迎楚河上。立陽為河南王。趙將司馬卬定河內，數有功。立卬為殷王，王河內。徙趙王歇王代。趙相張耳素賢，又從入關，立為常山王，王趙地。當陽君英布為楚將，常冠軍。立布為九江王。番君吳芮〔四〕帥百粵佐諸侯從入關。立芮為衡山王。義帝柱國共敖〔五〕將兵擊南郡，功多，因立為臨江王。徙燕王韓廣為遼東王。燕將臧荼〔六〕從楚救趙，因從入關。立荼為燕王。徙齊王田市為膠東王。齊將田都從共救趙，入關。立都為齊王。故秦所滅齊王建孫田安，羽方渡河救趙，安下濟北數城，引兵降羽。立安為濟北王。田榮者，背梁不肯助楚擊秦，以故不得封。陳餘棄將印去，不從入關，然素聞其賢，有功於趙，聞其在南皮，故因環封之三縣。〔七〕番君將梅鋗〔八〕功多，故封十萬戶侯。羽自立為西楚伯王，〔九〕王梁楚地九郡，都彭城。","sentenceOrder":216},
  {"id":"s_work_han_thu_42_217","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　蘇林曰：「講，和也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_42_218","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　孟康曰：「瑕丘縣之老人也，姓申名陽。」","sentenceOrder":218},
  {"id":"s_work_han_thu_42_219","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「嬖謂愛幸也。」","sentenceOrder":219},
  {"id":"s_work_han_thu_42_220","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「番音蒲河反。」","sentenceOrder":220},
  {"id":"s_work_han_thu_42_221","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　師古曰：「共讀曰龔。」","sentenceOrder":221},
  {"id":"s_work_han_thu_42_222","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　師古曰：「荼音塗。」","sentenceOrder":222},
  {"id":"s_work_han_thu_42_223","chapterId":"ch_work_han_thu_42","textTraditional":"〔八〕　孟康曰：「繞南皮三縣以封之。」師古曰：「環音宦。」","sentenceOrder":223},
  {"id":"s_work_han_thu_42_224","chapterId":"ch_work_han_thu_42","textTraditional":"〔八〕師古曰：「鋗音火玄反。」","sentenceOrder":224},
  {"id":"s_work_han_thu_42_225","chapterId":"ch_work_han_thu_42","textTraditional":"〔九〕師古曰：「伯讀曰霸。」","sentenceOrder":225},
  {"id":"s_work_han_thu_42_226","chapterId":"ch_work_han_thu_42","textTraditional":"諸侯各就國。田榮聞羽徙齊王市膠東，而立田都為齊王，大怒，不肯遣市之膠東，因以齊反，迎擊都。都走楚。市畏羽，乃亡之膠東就國。榮怒，追殺之即墨，自立為齊王。予彭越將軍印，今反梁地。越乃擊殺濟北王田安。田榮遂并王三齊之地。時漢王還定三秦。羽聞漢并關中，且東，〔一〕齊、梁畔之，大怒，乃以故吳令鄭昌為韓王以距漢，令蕭公角等擊彭越。越敗蕭公角等。時，張良徇韓，遺項王書曰：「漢王失職，欲得關中，如約即止，不敢東。」〔二〕又以齊、梁反書遺羽，羽以此故無西意，而北擊齊。徵兵九江王布。布稱疾不行，使將將數千人往。二年，羽陰使九江王布殺義帝。陳餘使張同、夏說說齊王榮，〔三〕曰：「項王為天下宰不平，今盡王故王於醜地，〔四〕而王群臣諸將善地，逐其故主趙王，乃北居代，餘以為不可。〔五〕聞大王起兵，且不聽不義，〔六〕願大王資餘兵，〔七〕使擊常山，以復趙王，請以國為扞蔽。」〔八〕齊王許之，因遣兵往。陳餘悉三縣兵，〔九〕與齊併力擊常山，大破之。張耳走歸漢。陳餘迎故趙王歇反之趙。趙王因立餘為代王。羽至城陽，田榮亦將兵會戰。榮不勝，走至平原，平原民殺之。羽遂北燒夷齊城郭室屋，〔一０〕皆阬降卒，係虜老弱婦女。徇齊至北海，所過殘滅。齊人相聚而畔之。於是田榮弟橫收得亡卒數萬人，反城陽。羽因留，連戰未能下。","sentenceOrder":226},
  {"id":"s_work_han_thu_42_227","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「言方欲出關而擊楚也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_42_228","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「如本要約也。」","sentenceOrder":228},
  {"id":"s_work_han_thu_42_229","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「夏說讀曰悅，下說齊王，說音式芮反。」","sentenceOrder":229},
  {"id":"s_work_han_thu_42_230","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「醜，惡也。」","sentenceOrder":230},
  {"id":"s_work_han_thu_42_231","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　師古曰：「於義不當然。」","sentenceOrder":231},
  {"id":"s_work_han_thu_42_232","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　師古曰：「凡不義之事，皆不聽順。」","sentenceOrder":232},
  {"id":"s_work_han_thu_42_233","chapterId":"ch_work_han_thu_42","textTraditional":"〔七〕　師古曰：「資，給也。」","sentenceOrder":233},
  {"id":"s_work_han_thu_42_234","chapterId":"ch_work_han_thu_42","textTraditional":"〔八〕　師古曰：「猶為齊之藩屏。」","sentenceOrder":234},
  {"id":"s_work_han_thu_42_235","chapterId":"ch_work_han_thu_42","textTraditional":"〔九〕　師古曰：「悉，盡也。」","sentenceOrder":235},
  {"id":"s_work_han_thu_42_236","chapterId":"ch_work_han_thu_42","textTraditional":"〔一０〕師古曰：「夷，平也。」","sentenceOrder":236},
  {"id":"s_work_han_thu_42_237","chapterId":"ch_work_han_thu_42","textTraditional":"漢王劫五諸侯兵，〔一〕凡五十六萬人，東伐楚。羽聞之，即令諸將擊齊，而自以精兵三萬人南從魯出胡陵。漢王皆已破彭城，收其貨賂美人，日置酒高會。羽乃從蕭晨擊漢軍而東，至彭城，日中，大破漢軍。〔二〕漢軍皆走，迫之穀、泗水。〔三〕漢軍皆南走山〔四〕，楚又追擊至靈辟東睢水上。〔五〕漢軍卻，為楚所擠，〔六〕多殺。漢卒十餘萬皆入睢水，睢水為不流。〔七〕漢王乃與數十騎遁去。語在高紀。太公、呂后間求漢王，〔八〕反遇楚軍。楚軍與歸，羽常置軍中。","sentenceOrder":237},
  {"id":"s_work_han_thu_42_238","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　服虔曰：「時有十八諸侯，漢得其五。」師古曰：「常山、河南、魏、韓、殷也。解在高紀。十八諸侯，漢時又先已得塞、翟矣。服說非也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_42_239","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　張晏曰：「一日之中。或曰早擊之，至日中大破。」師古曰：「或說是也。」","sentenceOrder":239},
  {"id":"s_work_han_thu_42_240","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　臣瓚曰：「二水皆在沛郡彭城。」","sentenceOrder":240},
  {"id":"s_work_han_thu_42_241","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「走，趣也，音奏。」","sentenceOrder":241},
  {"id":"s_work_han_thu_42_242","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　師古曰：「睢音雖。」","sentenceOrder":242},
  {"id":"s_work_han_thu_42_243","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　臣瓚曰：「擠，排也。」師古曰：「音子詣反，又音子奚反。」","sentenceOrder":243},
  {"id":"s_work_han_thu_42_244","chapterId":"ch_work_han_thu_42","textTraditional":"〔七〕　師古曰：「言殺人多，填於水中。」","sentenceOrder":244},
  {"id":"s_work_han_thu_42_245","chapterId":"ch_work_han_thu_42","textTraditional":"〔八〕　師古曰：「間行而求之。」","sentenceOrder":245},
  {"id":"s_work_han_thu_42_246","chapterId":"ch_work_han_thu_42","textTraditional":"漢王稍收散卒，蕭何亦發關中卒悉詣滎陽，戰京、索間，〔一〕敗楚。楚以故不能過滎陽而西。漢軍滎陽，築甬道，取敖倉食。三年，羽數擊絕漢甬道，漢王食乏，請和，割滎陽以西為漢。羽欲聽之。歷陽侯范增曰：「漢易與耳，今不取，後必悔之。」羽乃急圍滎陽。漢王患之，乃與陳平金四萬斤以間楚君臣。〔二〕語在陳平傳。項羽以故疑范增，稍奪之權。范增怒曰：「天下事大定矣，君王自為之！願賜骸骨歸。」行未至彭城，疽發背死。〔三〕於是漢將紀信詐為漢王出降，以誑楚軍，故漢王得與數十騎從西門出。令周苛、樅公、魏豹守滎陽。〔四〕漢王西入關收兵，還出宛、葉間，〔五〕與九江王黥布行收兵。羽聞之，即引兵南。漢王堅壁不與戰。","sentenceOrder":246},
  {"id":"s_work_han_thu_42_247","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「索音山各反。」","sentenceOrder":247},
  {"id":"s_work_han_thu_42_248","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「間音居莧反。」","sentenceOrder":248},
  {"id":"s_work_han_thu_42_249","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「疽，癰創也，音千餘反。」","sentenceOrder":249},
  {"id":"s_work_han_thu_42_250","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「苛音何。樅音千容反。」","sentenceOrder":250},
  {"id":"s_work_han_thu_42_251","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　師古曰：「葉音式涉反。」","sentenceOrder":251},
  {"id":"s_work_han_thu_42_252","chapterId":"ch_work_han_thu_42","textTraditional":"是時，彭越渡睢，與項聲、薛公戰下邳，殺薛公。羽乃東擊彭越。漢王亦引兵北軍成皋。羽已破走彭越，〔一〕引兵西下滎陽城，亨周苛，殺樅公，虜韓王信，進圍成皋。漢王跳，〔二〕獨與滕公得出。北渡河，至修武，從張耳、韓信。楚遂拔成皋。漢王得韓信軍，留止，使盧綰、劉賈渡白馬津入楚地，佐彭越共擊破楚軍燕郭西，〔三〕燒其積聚，攻下梁地十餘城。羽聞之，謂海春侯大司馬曹咎曰：「謹守成皋。即漢欲挑戰，慎毋與戰，勿令得東而已。我十五日必定梁地，復從將軍。」於是引兵東。","sentenceOrder":252},
  {"id":"s_work_han_thu_42_253","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「擊破之令其走。」","sentenceOrder":253},
  {"id":"s_work_han_thu_42_254","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「輕身而急出也。跳音徒彫反。」","sentenceOrder":254},
  {"id":"s_work_han_thu_42_255","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「燕縣，故南燕國也，屬東郡。」","sentenceOrder":255},
  {"id":"s_work_han_thu_42_256","chapterId":"ch_work_han_thu_42","textTraditional":"四年，羽擊陳留、外黃，外黃不下。數日降，羽悉令男子年十五以上詣城東，欲阬之。外黃令舍人兒年十三，〔一〕往說羽曰：「彭越強劫外黃，〔二〕外黃恐，故且降，待大王。大王至，又皆阬之，百姓豈有所歸心哉！從此以東，梁地十餘城皆恐，莫肯下矣。」羽然其言，乃赦外黃當阬者。而東至睢陽，聞之皆爭下。","sentenceOrder":256},
  {"id":"s_work_han_thu_42_257","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　蘇林曰：「令之舍人兒也。」臣瓚曰：「稱兒者，以其幼弱，故係其父。」","sentenceOrder":257},
  {"id":"s_work_han_thu_42_258","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「強音其兩反。」","sentenceOrder":258},
  {"id":"s_work_han_thu_42_259","chapterId":"ch_work_han_thu_42","textTraditional":"漢果數挑楚軍戰，楚軍不出。使人辱之，五六日，大司馬怒，渡兵氾水。〔一〕卒半渡，漢擊，大破之，盡得楚國金玉貨賂。大司馬咎、長史欣皆自剄氾水上。咎故蘄獄掾，欣故塞王，羽信任之。羽至睢陽，聞咎等破，則引兵還，漢軍方圍鍾離（昧）〔眜〕於滎陽東，〔二〕羽軍至，漢軍畏楚，盡走險阻。〔三〕羽亦軍廣武相守，乃為高俎，置太公其上，〔四〕告漢王曰：「今不急下，吾亨太公。」漢王曰：「吾與若俱北面受命懷王，〔五〕約為兄弟，吾翁即汝翁〔六〕。必欲亨乃翁，幸分我一盃羹。」〔七〕羽怒，欲殺之。項伯曰：「天下事未可知。且為天下者不顧家，雖殺之無益，但益怨耳。」羽從之。乃使人謂漢王曰：「天下匈匈，徒以吾兩人〔八〕願與王挑戰，決雌雄，毋徒罷天下父子為也。」〔九〕漢王笑謝曰：「吾寧鬥智，不能鬥力。」羽令壯士出挑戰。漢有善騎射曰樓煩，〔一０〕楚挑戰，三合，樓煩輒射殺之。羽大怒，自被甲持戟挑戰。樓煩欲射，羽瞋目叱之。〔一一〕樓煩目不能視，手不能發，走還入壁，不敢復出。漢王使間問之，乃羽也。〔一二〕漢王大驚。於是羽與漢王相與臨廣武間而語。漢王數羽十罪。〔一三〕語在高紀。羽怒，伏弩射傷漢王。漢王入成皋。","sentenceOrder":259},
  {"id":"s_work_han_thu_42_260","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「氾音凡。解在高紀。」","sentenceOrder":260},
  {"id":"s_work_han_thu_42_261","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「（昧）〔眜〕音莫葛反。」","sentenceOrder":261},
  {"id":"s_work_han_thu_42_262","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「走音奏。」","sentenceOrder":262},
  {"id":"s_work_han_thu_42_263","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　如淳曰：「高俎，几之上也。」李奇曰：「軍中巢櫓謂之俎。」師古曰：「俎者，所以薦肉。示欲烹之，故置俎上。如說是也。」","sentenceOrder":263},
  {"id":"s_work_han_thu_42_264","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　師古曰：「若，汝也。」","sentenceOrder":264},
  {"id":"s_work_han_thu_42_265","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　師古曰：「翁謂父也。」","sentenceOrder":265},
  {"id":"s_work_han_thu_42_266","chapterId":"ch_work_han_thu_42","textTraditional":"〔七〕　師古曰：「乃亦汝也。古者以杯盛羹，今之側杯有兩耳者是也。」","sentenceOrder":266},
  {"id":"s_work_han_thu_42_267","chapterId":"ch_work_han_thu_42","textTraditional":"〔八〕　師古曰：「匈匈，讙擾之意也。他皆類此。」","sentenceOrder":267},
  {"id":"s_work_han_thu_42_268","chapterId":"ch_work_han_thu_42","textTraditional":"〔九〕　師古曰：「罷讀曰疲。」","sentenceOrder":268},
  {"id":"s_work_han_thu_42_269","chapterId":"ch_work_han_thu_42","textTraditional":"〔一０〕應劭曰：「樓煩，胡人也。」李奇曰：「後為縣，屬雁門。此縣人善騎射，謂士為樓煩。取其稱耳，未必樓煩人也。」師古曰：「李說是也。」","sentenceOrder":269},
  {"id":"s_work_han_thu_42_270","chapterId":"ch_work_han_thu_42","textTraditional":"〔一一〕師古曰：「瞋目，張目也，音充人反。」","sentenceOrder":270},
  {"id":"s_work_han_thu_42_271","chapterId":"ch_work_han_thu_42","textTraditional":"〔一二〕師古曰：「間，微問之也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_42_272","chapterId":"ch_work_han_thu_42","textTraditional":"〔一三〕師古曰：「數，責也，音所具反。」","sentenceOrder":272},
  {"id":"s_work_han_thu_42_273","chapterId":"ch_work_han_thu_42","textTraditional":"時彭越數反梁地，絕楚糧食，又韓信破齊，且欲擊楚。羽使從兄子項它為大將，龍且為裨將，〔一〕救齊。韓信破殺龍且，追至成陽，虜齊王廣。信遂自立為齊王。羽聞之，恐，使武涉往說信。語在信傳。","sentenceOrder":273},
  {"id":"s_work_han_thu_42_274","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「它音徒何反。且音子余反。高紀云項聲，此傳云項它，紀傳不同，未知孰是。」","sentenceOrder":274},
  {"id":"s_work_han_thu_42_275","chapterId":"ch_work_han_thu_42","textTraditional":"時，漢關中兵益出，食多，羽兵食少。漢王使侯公說羽，羽乃與漢王約，中分天下，割鴻溝而西者為漢，東者為楚，歸漢王父母妻子。已約，羽解而東。五年，漢王進兵追羽，至（故）〔固〕陵，復為羽所敗。漢王用張良計，致齊王信、建成侯、彭越兵，乃劉賈入楚地，圍壽春。大司馬周殷叛楚，舉九江兵隨劉賈，迎黥布，與齊梁諸侯皆大會。","sentenceOrder":275},
  {"id":"s_work_han_thu_42_276","chapterId":"ch_work_han_thu_42","textTraditional":"羽壁垓下，軍少食盡。漢帥諸侯兵圍之數重。羽夜聞漢軍四面皆楚歌，乃驚曰：「漢皆已得楚乎？是何楚人多也！」起飲帳中。有美人姓虞氏，常幸從；駿馬名騅，常騎。〔一〕乃悲歌忼慨，自為歌詩曰：「力拔山兮氣蓋世，時不利兮騅不逝。騅不逝兮可柰何！虞兮虞兮柰若何！」〔二〕歌數曲，美人和之。羽泣下數行，左右皆泣，莫能仰視。","sentenceOrder":276},
  {"id":"s_work_han_thu_42_277","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「蒼白雜毛曰騅，蓋以其色名之。」","sentenceOrder":277},
  {"id":"s_work_han_thu_42_278","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「若，汝也。」","sentenceOrder":278},
  {"id":"s_work_han_thu_42_279","chapterId":"ch_work_han_thu_42","textTraditional":"於是羽遂上馬，戲下騎從者八百餘人，〔一〕夜直潰圍南出馳。平明，漢軍乃覺之，令騎將灌嬰以五千騎追羽。羽渡淮，騎能屬者百餘人。〔二〕羽至陰陵，迷失道，〔三〕問一田父，田父紿曰「左」。〔四〕左，乃陷大澤中，以故漢追及之。羽復引而東，至東城，乃有二十八騎。追者數千，羽自度不得脫，〔五〕謂其騎曰：「吾起兵至今八歲矣，身七十餘戰，所當者破，所擊者服，未嘗敗北，遂伯有天下。〔六〕然今卒困於此，〔七〕此天亡我，非戰之罪也。今日固決死，願為諸軍快戰，必三勝，斬將，艾旗，乃後死，〔八〕使諸君知我非用兵罪，天亡我也。」於是引其騎因四隤山〔九〕而為圜陳外嚮。〔一０〕漢騎圍之數重。羽謂其騎曰：「吾為公取彼一將。」令四面騎馳下，期山東為三處。於是羽大呼馳下，〔一一〕漢軍皆披靡。〔一二〕遂殺漢一將。是時，楊喜為郎騎，追羽，羽還叱之，〔一三〕喜人馬俱驚，辟易數里。〔一四〕與其騎會三處。漢軍不知羽所居，分軍為三，復圍之。羽乃馳，復斬漢一都尉，殺數十百人。復聚其騎，亡兩騎。乃謂騎曰：「何如？」騎皆服曰：「如大王言。」","sentenceOrder":279},
  {"id":"s_work_han_thu_42_280","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「戲，大將之旗也，音許宜反，又音許為反。漢書通以戲為旌麾及指麾字。」","sentenceOrder":280},
  {"id":"s_work_han_thu_42_281","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「屬，聯及也，音之欲反。」","sentenceOrder":281},
  {"id":"s_work_han_thu_42_282","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　孟康曰：「縣名，屬九江郡。」","sentenceOrder":282},
  {"id":"s_work_han_thu_42_283","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　文穎曰：「紿，欺也；欺令左也。」","sentenceOrder":283},
  {"id":"s_work_han_thu_42_284","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　師古曰：「脫，免也，音土活反。」","sentenceOrder":284},
  {"id":"s_work_han_thu_42_285","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　師古曰：「伯讀曰霸。」","sentenceOrder":285},
  {"id":"s_work_han_thu_42_286","chapterId":"ch_work_han_thu_42","textTraditional":"〔七〕　師古曰：「卒，終也。」","sentenceOrder":286},
  {"id":"s_work_han_thu_42_287","chapterId":"ch_work_han_thu_42","textTraditional":"〔八〕　師古曰：「艾音刈。」","sentenceOrder":287},
  {"id":"s_work_han_thu_42_288","chapterId":"ch_work_han_thu_42","textTraditional":"〔九〕　孟康曰：「四下隤陁也。」師古曰：「隤音徒回反。」","sentenceOrder":288},
  {"id":"s_work_han_thu_42_289","chapterId":"ch_work_han_thu_42","textTraditional":"〔一０〕師古曰：「圜陳，四周為之也。外嚮，謂兵刃皆在外也。」","sentenceOrder":289},
  {"id":"s_work_han_thu_42_290","chapterId":"ch_work_han_thu_42","textTraditional":"〔一一〕師古曰：「呼，叫也，音火故反。」","sentenceOrder":290},
  {"id":"s_work_han_thu_42_291","chapterId":"ch_work_han_thu_42","textTraditional":"〔一二〕師古曰：「披音普彼反。」","sentenceOrder":291},
  {"id":"s_work_han_thu_42_292","chapterId":"ch_work_han_thu_42","textTraditional":"〔一三〕師古曰：「還謂迴面也。」","sentenceOrder":292},
  {"id":"s_work_han_thu_42_293","chapterId":"ch_work_han_thu_42","textTraditional":"〔一四〕師古曰：「辟易，謂開張而易其本處。辟音頻亦反。」","sentenceOrder":293},
  {"id":"s_work_han_thu_42_294","chapterId":"ch_work_han_thu_42","textTraditional":"於是羽遂引東，欲渡烏江。〔一〕烏江亭長檥船待，〔二〕謂羽曰：「江東雖小，地方千里，眾數十萬，亦足王也。願大王急渡。今獨臣有船，漢軍至，亡以渡。」羽笑曰：「乃天亡我，何渡為！且籍與江東子弟八千人渡而西，今亡一人還，縱江東父兄憐而王我，我何面目見之哉？縱彼不言，籍獨不愧於心乎！」謂亭長曰：「吾知公長者也，吾騎此馬五歲，所當亡敵，嘗一日千里，吾不忍殺，以賜公。」乃令騎皆去馬，步持短兵接戰。羽獨所殺漢軍數百人。羽亦被十餘創。顧見漢騎司馬呂馬童曰：「若非吾故人乎？」〔三〕馬童面之，〔四〕指王翳曰：〔五〕「此項王也。」羽乃曰：「吾聞漢購我頭千金，邑萬戶，〔六〕吾為公得。」〔七〕乃自剄。王翳取其頭，亂相輮蹈〔八〕爭羽相殺者數十人。最後楊喜、呂馬童、郎中呂勝、楊武各得其一體。故分其地以封五人，皆為列侯。","sentenceOrder":294},
  {"id":"s_work_han_thu_42_295","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　臣瓚曰：「在牛渚。」","sentenceOrder":295},
  {"id":"s_work_han_thu_42_296","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　服虔曰：「檥音蟻。」如淳曰：「南方人謂整船向岸曰檥。」","sentenceOrder":296},
  {"id":"s_work_han_thu_42_297","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「若，汝也。」","sentenceOrder":297},
  {"id":"s_work_han_thu_42_298","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　張晏曰：「以故人難親斫之，故背之也。」如淳曰：「面謂不正視也。」師古曰：「如說非也。面謂背之，不面向也。面縛亦謂反偝而縛之。杜元凱以為但見其面，非也。」","sentenceOrder":298},
  {"id":"s_work_han_thu_42_299","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　如淳曰：「指示王翳。」","sentenceOrder":299},
  {"id":"s_work_han_thu_42_300","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　師古曰：「購，以財設賞，音工豆反。」","sentenceOrder":300},
  {"id":"s_work_han_thu_42_301","chapterId":"ch_work_han_thu_42","textTraditional":"〔七〕　鄧展曰：「令公得我為功也。」晉灼曰：「字或作德。」","sentenceOrder":301},
  {"id":"s_work_han_thu_42_302","chapterId":"ch_work_han_thu_42","textTraditional":"〔八〕　師古曰：「輮，踐也，音人九反。」","sentenceOrder":302},
  {"id":"s_work_han_thu_42_303","chapterId":"ch_work_han_thu_42","textTraditional":"漢王乃以魯公號葬羽於穀城。諸項支屬皆不誅。封項伯等四人為列侯，賜姓劉氏。","sentenceOrder":303},
  {"id":"s_work_han_thu_42_304","chapterId":"ch_work_han_thu_42","textTraditional":"贊曰：昔賈生之過秦曰：〔一〕","sentenceOrder":304},
  {"id":"s_work_han_thu_42_305","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　應劭曰：「賈生書有過秦二篇，言秦之過。此第一篇也。司馬遷取以為贊，班固因之。」","sentenceOrder":305},
  {"id":"s_work_han_thu_42_306","chapterId":"ch_work_han_thu_42","textTraditional":"秦孝公據殽函之固，擁雍州之地，〔一〕君臣固守而闚周室，有席卷天下，包舉宇內，囊括四海，并吞八荒之心。〔二〕當是時也，商君佐之，〔三〕內立法度，務耕織，修守戰之備，外連衡而鬥諸侯。於是秦人拱手而取西河之外。〔四〕","sentenceOrder":306},
  {"id":"s_work_han_thu_42_307","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「殽謂殽山，今陝縣東二殽是也。函謂函谷，今桃林縣南洪溜澗是也。」","sentenceOrder":307},
  {"id":"s_work_han_thu_42_308","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　張晏曰：「括，結囊也，言其能包含天下。」師古曰：「八荒，八方荒忽極遠之地也。」","sentenceOrder":308},
  {"id":"s_work_han_thu_42_309","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「衛鞅也，封於商。」","sentenceOrder":309},
  {"id":"s_work_han_thu_42_310","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「言其不費功力也。」","sentenceOrder":310},
  {"id":"s_work_han_thu_42_311","chapterId":"ch_work_han_thu_42","textTraditional":"孝公既沒，惠文、武、昭襄〔一〕蒙故業，因遺策，南取漢中，西舉巴蜀，東割膏腴之地，收要害之郡。諸侯恐懼，會盟而謀弱秦，不愛珍器重寶肥饒之地，以致天下之士。合從締交，〔二〕相與為一。當此之時，齊有孟嘗，〔三〕趙有平原，〔四〕楚有春申〔五〕，魏有信陵。〔六〕此四賢者，皆明智而忠信，寬厚而愛人，尊賢重士，約從離橫，〔七〕兼韓、魏、燕、趙、宋、衛、中山之眾。於是六國之士有甯越、徐尚、蘇秦、杜赫之屬為之謀，齊明、周最、陳軫、召滑、樓緩、翟景、蘇厲、樂毅之徒通其意，〔八〕吳起、孫臏、帶他、兒良、王廖、田忌、廉頗、趙奢之朋制其兵。〔九〕常以十倍之地，百萬之軍，仰關而攻秦。〔一０〕秦人開關延敵，九國之師遁巡而不敢進。〔一一〕秦無亡矢遺鏃之費，而天下已困矣。〔一二〕於是從散約敗，爭割地而賂秦。秦有餘力而制其弊，追亡逐北，伏尸百萬，流血漂鹵，〔一三〕因利乘便，宰割天下，分裂山河；強國請服，弱國入朝。","sentenceOrder":311},
  {"id":"s_work_han_thu_42_312","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「惠文王，孝公之子。武王，惠文王之子。昭襄王，武王之弟。」","sentenceOrder":312},
  {"id":"s_work_han_thu_42_313","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「締，結也。從音子容反。締音大系反。」","sentenceOrder":313},
  {"id":"s_work_han_thu_42_314","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　師古曰：「孟嘗君田文。」","sentenceOrder":314},
  {"id":"s_work_han_thu_42_315","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「平原君趙勝。」","sentenceOrder":315},
  {"id":"s_work_han_thu_42_316","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　師古曰：「春申君黃歇。」","sentenceOrder":316},
  {"id":"s_work_han_thu_42_317","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　師古曰：「公子無忌為信陵君。」","sentenceOrder":317},
  {"id":"s_work_han_thu_42_318","chapterId":"ch_work_han_thu_42","textTraditional":"〔七〕　師古曰：「約誓為從，欲以分離為橫。橫謂秦也。從音子容反。其下亦同。」","sentenceOrder":318},
  {"id":"s_work_han_thu_42_319","chapterId":"ch_work_han_thu_42","textTraditional":"〔八〕　師古曰：「召讀曰邵。」","sentenceOrder":319},
  {"id":"s_work_han_thu_42_320","chapterId":"ch_work_han_thu_42","textTraditional":"〔九〕　師古曰：「臏音頻忍反。他音徒何反。兒音五奚反。廖音聊。」","sentenceOrder":320},
  {"id":"s_work_han_thu_42_321","chapterId":"ch_work_han_thu_42","textTraditional":"〔一０〕師古曰：「秦之地形高，而諸侯之兵欲攻關中者皆仰嚮，故云仰關也。今流俗書本仰字作叩，非也。」","sentenceOrder":321},
  {"id":"s_work_han_thu_42_322","chapterId":"ch_work_han_thu_42","textTraditional":"〔一一〕師古曰：「遁巡，謂疑懼而卻退也。遁音千旬反。流俗書本巡字誤作逃，讀者因之而為遁逃之義。潘岳西征賦云『逃遁以奔竄』，斯亦誤矣。」","sentenceOrder":322},
  {"id":"s_work_han_thu_42_323","chapterId":"ch_work_han_thu_42","textTraditional":"〔一二〕師古曰：「鏃，矢鋒也，音子木反。」","sentenceOrder":323},
  {"id":"s_work_han_thu_42_324","chapterId":"ch_work_han_thu_42","textTraditional":"〔一三〕師古曰：「漂，浮也。鹵，盾也。其血可以浮盾，言殺人多也。漂音匹遙反。」","sentenceOrder":324},
  {"id":"s_work_han_thu_42_325","chapterId":"ch_work_han_thu_42","textTraditional":"施及孝文、莊襄王，〔一〕享國之日淺，國家亡事。","sentenceOrder":325},
  {"id":"s_work_han_thu_42_326","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「施，延也。孝文王，昭襄王之子也。莊襄王，孝文王之子，即始皇父也。施音戈豉反。」","sentenceOrder":326},
  {"id":"s_work_han_thu_42_327","chapterId":"ch_work_han_thu_42","textTraditional":"及至始皇，奮六世之餘烈，〔一〕振長策而馭宇內，〔二〕吞二周而亡諸侯，履至尊而制六合，執敲扑以鞭笞天下，〔三〕威震四海。南取百粵之地，以為桂林、象郡。百粵之君頫首係頸，〔四〕委命下吏。乃使蒙恬北築長城而守藩籬，〔五〕卻匈奴七百餘里〔六〕，胡人不敢南下而牧馬，士不敢彎弓而報怨。於是廢先王之道，焚百家之言，以愚黔首。墮名城，殺豪俊，〔七〕收天下之兵聚之咸陽，銷鋒鍉〔八〕鑄以為金人十二，〔九〕以弱天下之民。然後踐華為城，〔一０〕因河為池，據億丈之城，臨不測之川，以為固。良將勁弩，守要害之處，信臣精卒，陳利兵而誰何。〔一一〕天下已定，始皇之心，自以為關中之固，金城千里，子孫帝王萬世之業也。","sentenceOrder":327},
  {"id":"s_work_han_thu_42_328","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「孝公、惠文王、武王、昭襄王、孝文王、莊襄王，凡六君也。烈，業也。」","sentenceOrder":328},
  {"id":"s_work_han_thu_42_329","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「以乘馬為喻也。策，所以撾馬也。」","sentenceOrder":329},
  {"id":"s_work_han_thu_42_330","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　鄧展曰：「敲，短杖也。扑，捶也。」師古曰：「敲音苦交反。扑音普木反。」","sentenceOrder":330},
  {"id":"s_work_han_thu_42_331","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　鄧展曰：「頫音俯。」師古曰：「古俯字。」","sentenceOrder":331},
  {"id":"s_work_han_thu_42_332","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　師古曰：「言以長城扞蔽胡寇，如人家之有藩籬。」","sentenceOrder":332},
  {"id":"s_work_han_thu_42_333","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　師古曰：「卻音丘略反。」","sentenceOrder":333},
  {"id":"s_work_han_thu_42_334","chapterId":"ch_work_han_thu_42","textTraditional":"〔七〕　師古曰：「墮，毀也，音火規反。」","sentenceOrder":334},
  {"id":"s_work_han_thu_42_335","chapterId":"ch_work_han_thu_42","textTraditional":"〔八〕　如淳曰：「鍉音嫡，箭鏃也。」師古曰：「鋒，戈戟刃也。鍉與鏑同，即箭鏃也。如音是也。」","sentenceOrder":335},
  {"id":"s_work_han_thu_42_336","chapterId":"ch_work_han_thu_42","textTraditional":"〔九〕　師古曰：「所謂公仲者也。三輔黃圖云坐高三丈。其銘曰：『皇帝二十六年，初兼天下，改諸侯為郡縣，一法律，同度量。大人來見臨洮，其長五丈，足跡六尺。』」","sentenceOrder":336},
  {"id":"s_work_han_thu_42_337","chapterId":"ch_work_han_thu_42","textTraditional":"〔一０〕服虔曰：「斷華山為城。」晉灼曰：「踐，登也。」師古曰：「晉說是。」","sentenceOrder":337},
  {"id":"s_work_han_thu_42_338","chapterId":"ch_work_han_thu_42","textTraditional":"〔一一〕師古曰：「問之為誰，又云何人，其義一也。」","sentenceOrder":338},
  {"id":"s_work_han_thu_42_339","chapterId":"ch_work_han_thu_42","textTraditional":"始皇既沒，餘威震于殊俗。然而陳涉，甕牖繩樞之子，〔一〕甿隸之人，〔二〕遷徙之徒也，材能不及中庸，非有仲尼、墨翟之知，〔三〕陶朱、猗頓之富。〔四〕躡足行伍之間，〔五〕而免起阡陌之中，〔六〕帥罷散之卒，將數百之眾，〔七〕轉而攻秦。斬木為兵，揭竿為旗，〔八〕天下雲合嚮應，〔九〕贏糧而景從，〔一０〕山東豪俊遂並起而亡秦族矣。","sentenceOrder":339},
  {"id":"s_work_han_thu_42_340","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　服虔曰：「以繩係戶樞。」孟康曰：「瓦甕為（樞）〔窗〕也。」","sentenceOrder":340},
  {"id":"s_work_han_thu_42_341","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　如淳曰：「甿，古文萌字。甿，民也。」","sentenceOrder":341},
  {"id":"s_work_han_thu_42_342","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　文穎曰：「墨翟，宋人為墨家者也。」","sentenceOrder":342},
  {"id":"s_work_han_thu_42_343","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「越人范蠡逃越，止於陶，自謂陶朱公。猗頓本魯人，大畜牛羊於猗氏之南，貲（撥）〔擬〕王公，馳名天下。」","sentenceOrder":343},
  {"id":"s_work_han_thu_42_344","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　如淳曰：「躡音疊。」師古曰：「躡音女涉反。」","sentenceOrder":344},
  {"id":"s_work_han_thu_42_345","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　如淳曰：「時皆僻屈在阡陌之中也。」師古曰：「免者，言免脫徭役也。免字或作俛，讀與俯同。」","sentenceOrder":345},
  {"id":"s_work_han_thu_42_346","chapterId":"ch_work_han_thu_42","textTraditional":"〔七〕　師古曰：「罷讀曰疲。」","sentenceOrder":346},
  {"id":"s_work_han_thu_42_347","chapterId":"ch_work_han_thu_42","textTraditional":"〔八〕　師古曰：「揭音竭，謂豎之也。今讀之者為負揭之揭，非也。」","sentenceOrder":347},
  {"id":"s_work_han_thu_42_348","chapterId":"ch_work_han_thu_42","textTraditional":"〔九〕　師古曰：「嚮讀曰響，言如響之應聲。」","sentenceOrder":348},
  {"id":"s_work_han_thu_42_349","chapterId":"ch_work_han_thu_42","textTraditional":"〔一０〕師古曰：「贏，擔也。景從，言如影之隨形也。」","sentenceOrder":349},
  {"id":"s_work_han_thu_42_350","chapterId":"ch_work_han_thu_42","textTraditional":"且天下非小弱也；雍州之地，殽函之固，自若也。〔一〕陳涉之位，不齒於齊、楚、燕、趙、韓、魏、宋、衛、中山之君；〔二〕鉏耰棘矜，不敵於鉤戟長鎩；〔三〕適戍之眾，不亢於九國之師；〔四〕深謀遠慮，行軍用兵之道，非及曩時之士也。〔五〕然而成敗異變，功業相反，何也？試使山東之國與陳涉度長絜大，〔六〕比權量力，不可同年而語矣。然秦以區區之地，致萬乘之權，〔七〕招八州而朝同列，〔八〕百有餘年，然后以六合為家，〔九〕殽函為宮。一夫作難而七廟墮，〔一０〕身死人手，為天下笑者，何也？仁誼不施，而攻守之勢異也。","sentenceOrder":350},
  {"id":"s_work_han_thu_42_351","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　師古曰：「自若，猶言如故也。」","sentenceOrder":351},
  {"id":"s_work_han_thu_42_352","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「齒謂齊列如齒。」","sentenceOrder":352},
  {"id":"s_work_han_thu_42_353","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　服虔曰：「耰，鉏柄也；以鉏柄及棘作矛〈矛堇〉也。」晉灼曰：「耰椎，塊椎也。」師古曰：「服說非也。耰，摩田器也。棘，戟也。矜與〈矛堇〉同，〈矛堇〉謂矛鋋之杷也。鉤戟，戟刃鉤曲者也。鎩，鈹也。言往者秦銷兵刃，陳涉起時但用鉏耰及戈戟之〈矛堇〉以相攻戰也。耰音憂。矜音其巾反。鎩音（其）〔山〕列反。」","sentenceOrder":353},
  {"id":"s_work_han_thu_42_354","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「適讀曰謫，謂罪罰而行也。亢，當也，讀與抗同。」","sentenceOrder":354},
  {"id":"s_work_han_thu_42_355","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　師古曰：「曩，昔也，音乃朗反。」","sentenceOrder":355},
  {"id":"s_work_han_thu_42_356","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　師古曰：「絜謂圍束之也。度音徒各反。絜音下結反。」","sentenceOrder":356},
  {"id":"s_work_han_thu_42_357","chapterId":"ch_work_han_thu_42","textTraditional":"〔七〕　師古曰：「區區，小貌也。」","sentenceOrder":357},
  {"id":"s_work_han_thu_42_358","chapterId":"ch_work_han_thu_42","textTraditional":"〔八〕　鄧展曰：「招，舉也。」蘇林曰：「招音翹。」","sentenceOrder":358},
  {"id":"s_work_han_thu_42_359","chapterId":"ch_work_han_thu_42","textTraditional":"〔九〕　師古曰：「后與後同，古通用字也。」","sentenceOrder":359},
  {"id":"s_work_han_thu_42_360","chapterId":"ch_work_han_thu_42","textTraditional":"〔一０〕師古曰：「墮，毀也，音火規反。」","sentenceOrder":360},
  {"id":"s_work_han_thu_42_361","chapterId":"ch_work_han_thu_42","textTraditional":"周生亦有言，〔一〕「舜蓋重童子」，項羽又重童子，〔二〕豈其苗裔邪？何其興之暴也！夫秦失其政，陳涉首難，豪桀蜂起，相與並爭，不可勝數。然羽非有尺寸，乘勢拔起隴畝之中，〔三〕三年，遂將五諸侯兵滅秦，分裂天下而威海內，封立王侯，政繇羽出，〔四〕號為「伯王」，〔五〕位雖不終，近古以來未嘗有也。〔六〕及羽背關懷楚，放逐義帝，〔七〕而怨王侯畔己，難矣。自矜功伐，奮其私智而不師古，始霸王之國，欲以力征經營天下，五年卒亡其國，身死東城，尚不覺寤，不自責過失，乃引「天亡我，非用兵之罪」，豈不謬哉！","sentenceOrder":361},
  {"id":"s_work_han_thu_42_362","chapterId":"ch_work_han_thu_42","textTraditional":"〔一〕　鄭氏曰：「周時賢（大夫）〔人也〕。」師古曰：「史記稱太史公曰『余聞之周生』則知非周時人，蓋姓周耳。」","sentenceOrder":362},
  {"id":"s_work_han_thu_42_363","chapterId":"ch_work_han_thu_42","textTraditional":"〔二〕　師古曰：「童子，目之眸子。」","sentenceOrder":363},
  {"id":"s_work_han_thu_42_364","chapterId":"ch_work_han_thu_42","textTraditional":"〔三〕　晉灼曰：「拔音卒拔之拔。」鄧展曰：「疾起也。」師古曰：「音步末反。」","sentenceOrder":364},
  {"id":"s_work_han_thu_42_365","chapterId":"ch_work_han_thu_42","textTraditional":"〔四〕　師古曰：「繇與由同。」","sentenceOrder":365},
  {"id":"s_work_han_thu_42_366","chapterId":"ch_work_han_thu_42","textTraditional":"〔五〕　師古曰：「伯讀曰霸。」","sentenceOrder":366},
  {"id":"s_work_han_thu_42_367","chapterId":"ch_work_han_thu_42","textTraditional":"〔六〕　師古曰：「近古猶末代。」","sentenceOrder":367},
  {"id":"s_work_han_thu_42_368","chapterId":"ch_work_han_thu_42","textTraditional":"〔七〕　師古曰：「背關，謂背約不王高祖於關中。懷楚，謂思東歸而都彭城。」","sentenceOrder":368},
  {"id":"s_work_han_thu_42_369","chapterId":"ch_work_han_thu_42","textTraditional":"校勘記","sentenceOrder":369},
  {"id":"s_work_han_thu_42_370","chapterId":"ch_work_han_thu_42","textTraditional":"一七八八頁　二行　號（為）張楚。景祐、殿本都無「為」字。","sentenceOrder":370},
  {"id":"s_work_han_thu_42_371","chapterId":"ch_work_han_thu_42","textTraditional":"一七八八頁一七行　亦於兵（革）〔車〕之上為樓以望敵也。　景祐、殿、局本都作「車」。王先謙說作「車」是。","sentenceOrder":371},
  {"id":"s_work_han_thu_42_372","chapterId":"ch_work_han_thu_42","textTraditional":"一七九一頁一二行　今趙（又）〔獨〕安敢害將軍（之）家乎？　景祐、殿本「又」作「獨」，無「之」字。","sentenceOrder":372},
  {"id":"s_work_han_thu_42_373","chapterId":"ch_work_han_thu_42","textTraditional":"一七九四頁　八行　首事，謂最先（兵起）〔起兵〕。　景祐、殿本都作「起兵」。","sentenceOrder":373},
  {"id":"s_work_han_thu_42_374","chapterId":"ch_work_han_thu_42","textTraditional":"一七九四頁一一行　徼（要）散卒復相聚斂也。　景祐、殿本都無「要」字。","sentenceOrder":374},
  {"id":"s_work_han_thu_42_375","chapterId":"ch_work_han_thu_42","textTraditional":"一七九六頁　七行　吳中（弟子）〔子弟〕皆憚籍。　景祐、殿本都作「子弟」。王先謙說此誤倒。","sentenceOrder":375},
  {"id":"s_work_han_thu_42_376","chapterId":"ch_work_han_thu_42","textTraditional":"一七九八頁　四行　謂其軍〔吏〕曰：　景祐、殿本都有「吏」字。王先謙說此脫。","sentenceOrder":376},
  {"id":"s_work_han_thu_42_377","chapterId":"ch_work_han_thu_42","textTraditional":"一七九八頁　八行　漢儀注令（史）〔吏〕曰令史，丞（史）〔吏〕曰丞史。　據史記集解改。","sentenceOrder":377},
  {"id":"s_work_han_thu_42_378","chapterId":"ch_work_han_thu_42","textTraditional":"一七九八頁一五行　（自比）〔此自〕更有蒲將軍也。　景祐、殿本都作「自此」，「比」字誤。王先謙說史記集解引作「此自」，是。","sentenceOrder":378},
  {"id":"s_work_han_thu_42_379","chapterId":"ch_work_han_thu_42","textTraditional":"一七九九頁　二行　乃引兵擊秦嘉，〔嘉〕軍敗走。　王先謙說「軍」上當更有「嘉」字，按史記有，此脫。","sentenceOrder":379},
  {"id":"s_work_han_thu_42_380","chapterId":"ch_work_han_thu_42","textTraditional":"一七九九頁　三行　梁已并秦嘉軍，〔軍〕胡陵，　景祐、殿本都有下「軍」字。王先謙說史記同，此脫。","sentenceOrder":380},
  {"id":"s_work_han_thu_42_381","chapterId":"ch_work_han_thu_42","textTraditional":"一八００頁一六行　不如待以（初）〔禮〕，　景祐、殿本都作「禮」。王先謙說作「禮」是。","sentenceOrder":381},
  {"id":"s_work_han_thu_42_382","chapterId":"ch_work_han_thu_42","textTraditional":"一八０二頁一四行　今不卹士卒而徇私（宴），　景祐、殿本都無「宴」字。","sentenceOrder":382},
  {"id":"s_work_han_thu_42_383","chapterId":"ch_work_han_thu_42","textTraditional":"一八０四頁　九行　羽繇是始為諸侯上將軍，〔八〕　注〔八〕原在「上」字下，劉敞說「上將軍」當連文。","sentenceOrder":383},
  {"id":"s_work_han_thu_42_384","chapterId":"ch_work_han_thu_42","textTraditional":"一八０五頁　八行　開榆中地數（十）〔千〕里，景祐、殿、局本都作「千」，史記同。","sentenceOrder":384},
  {"id":"s_work_han_thu_42_385","chapterId":"ch_work_han_thu_42","textTraditional":"一八０七頁一０行　輕（重）折辱秦吏卒。　吏卒多竊言〔曰〕：「章將軍〔等〕詐吾屬降諸侯，　宋祁說一本無「重」字。王先謙說史記亦無，一本是。景祐、殿本「言」下有「曰」字，「章將軍」下有「等」字，史記同。","sentenceOrder":385},
  {"id":"s_work_han_thu_42_386","chapterId":"ch_work_han_thu_42","textTraditional":"一八一五頁　九行　漢軍方圍鍾離（昧）〔眜〕於滎陽東，　景祐、殿本都作「眜」，注同。王先謙說作「眜」是。","sentenceOrder":386},
  {"id":"s_work_han_thu_42_387","chapterId":"ch_work_han_thu_42","textTraditional":"一八一七頁　八行　漢王進兵追羽，至（故）〔固〕陵，　殿本作「固」。王先謙說作「固」是。","sentenceOrder":387},
  {"id":"s_work_han_thu_42_388","chapterId":"ch_work_han_thu_42","textTraditional":"一八二四頁一一行　瓦甕為（樞）〔窗〕也。　景祐、殿本都作「窗」。王先謙說作「窗」是。","sentenceOrder":388},
  {"id":"s_work_han_thu_42_389","chapterId":"ch_work_han_thu_42","textTraditional":"一八二四頁一四行　貲（撥）〔擬〕王公，　景祐、殿本都作「擬」。王先謙說作「擬」是。","sentenceOrder":389},
  {"id":"s_work_han_thu_42_390","chapterId":"ch_work_han_thu_42","textTraditional":"一八二五頁一六行　鎩音（其）〔山〕列反。　景祐、殿本都作「山」。","sentenceOrder":390},
  {"id":"s_work_han_thu_42_391","chapterId":"ch_work_han_thu_42","textTraditional":"一八二六頁一四行　周時賢（大夫）〔人也〕。　景祐、殿本都作「賢人也」，王先謙說此「大夫」二字有誤。","sentenceOrder":391},
  {"id":"s_work_han_thu_43_1","chapterId":"ch_work_han_thu_43","textTraditional":"張耳，大梁人也，〔一〕少時及魏公子毋忌為客。〔二〕嘗亡命遊外黃，〔三〕外黃富人女甚美，庸奴其夫，〔四〕亡邸父客。〔五〕父客謂曰：「必欲求賢夫，從張耳。」女聽，為請決，嫁之。〔六〕女家厚奉給耳，耳以故致千里客，宦為外黃令。","sentenceOrder":1},
  {"id":"s_work_han_thu_43_2","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　臣瓚曰：「今陳留大梁城也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_43_3","chapterId":"ch_work_han_thu_43","textTraditional":"〔二〕　師古曰：「毋忌，六國時信陵君也。言其尚及見毋忌，為之賓客。」","sentenceOrder":3},
  {"id":"s_work_han_thu_43_4","chapterId":"ch_work_han_thu_43","textTraditional":"〔三〕　師古曰：「命者，名也。凡言亡命，謂脫其名籍而逃亡。」","sentenceOrder":4},
  {"id":"s_work_han_thu_43_5","chapterId":"ch_work_han_thu_43","textTraditional":"〔四〕　師古曰：「言不恃賴其夫，視之若庸奴。」","sentenceOrder":5},
  {"id":"s_work_han_thu_43_6","chapterId":"ch_work_han_thu_43","textTraditional":"〔五〕　如淳曰：「父時故賓客也。」師古曰：「邸，歸也，音丁禮反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_43_7","chapterId":"ch_work_han_thu_43","textTraditional":"〔六〕　師古曰：「請決絕於前夫而嫁於耳。」","sentenceOrder":7},
  {"id":"s_work_han_thu_43_8","chapterId":"ch_work_han_thu_43","textTraditional":"陳餘，亦大梁人，好儒術。遊趙苦陘，〔一〕富人公乘氏以其女妻之。餘年少，父事耳，相與為刎頸交。〔二〕","sentenceOrder":8},
  {"id":"s_work_han_thu_43_9","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　張晏曰：「苦陘，章帝醜其名，改曰漢昌。」師古曰：「陘音刑。」","sentenceOrder":9},
  {"id":"s_work_han_thu_43_10","chapterId":"ch_work_han_thu_43","textTraditional":"〔二〕　師古曰：「刎，斷也。刎頸交者，言托契深重，雖斷頸絕頭，無所顧也。刎音舞粉反。」","sentenceOrder":10},
  {"id":"s_work_han_thu_43_11","chapterId":"ch_work_han_thu_43","textTraditional":"高祖為布衣時，嘗從耳遊。秦滅魏，購求耳千金，餘五百金。兩人變名姓，俱之陳，為里監門。〔一〕吏嘗以過笞餘，餘欲起，耳攝使受笞。〔二〕吏去，耳數之曰：〔三〕「始吾與公言何如？今見小辱而欲死一吏乎？」餘謝罪。","sentenceOrder":11},
  {"id":"s_work_han_thu_43_12","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　師古曰：「監門，卒之賤者，故為卑職以自隱。」","sentenceOrder":12},
  {"id":"s_work_han_thu_43_13","chapterId":"ch_work_han_thu_43","textTraditional":"〔二〕　師古曰：「攝謂引持之。」","sentenceOrder":13},
  {"id":"s_work_han_thu_43_14","chapterId":"ch_work_han_thu_43","textTraditional":"〔三〕　師古曰：「數，責也，音所具反。」","sentenceOrder":14},
  {"id":"s_work_han_thu_43_15","chapterId":"ch_work_han_thu_43","textTraditional":"陳涉起蘄至陳，耳、餘上謁涉。〔一〕涉及左右生平數聞耳、餘賢，見，大喜。","sentenceOrder":15},
  {"id":"s_work_han_thu_43_16","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　師古曰：「上其謁而見也。上謁，若今之通名。」","sentenceOrder":16},
  {"id":"s_work_han_thu_43_17","chapterId":"ch_work_han_thu_43","textTraditional":"陳豪桀說涉曰：「將軍被堅執銳，帥士卒以誅暴秦，復立楚社稷，功德宜為王。」陳涉問兩人，兩人對曰：「將軍瞋目張膽，〔一〕出萬死不顧之計，為天下除殘。今始至陳而王之，視天下私。〔二〕願將軍毋王，急引兵而西，遣人立六國後，自為樹黨。〔三〕如此，野無交兵，誅暴秦，據咸陽以令諸侯，則帝業成矣。今獨王陳，恐天下解（矣）〔也〕。」〔四〕涉不聽，遂立為王。","sentenceOrder":17},
  {"id":"s_work_han_thu_43_18","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　師古曰：「張膽，言勇之甚。」","sentenceOrder":18},
  {"id":"s_work_han_thu_43_19","chapterId":"ch_work_han_thu_43","textTraditional":"〔二〕　師古曰：「視讀曰示。」","sentenceOrder":19},
  {"id":"s_work_han_thu_43_20","chapterId":"ch_work_han_thu_43","textTraditional":"〔三〕　師古曰：「樹，立也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_43_21","chapterId":"ch_work_han_thu_43","textTraditional":"〔四〕　師古曰：「解謂離散其心也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_43_22","chapterId":"ch_work_han_thu_43","textTraditional":"耳、餘復說陳王曰：「大王興梁、楚，務在入關，未及收河北也。臣嘗遊趙，知其豪桀，〔一〕願請奇兵略趙地。」於是陳王許之，以所善陳人武臣為將軍，耳、餘為左右校尉，與卒三千人，從白馬渡河。〔二〕至諸縣，說其豪桀〔三〕曰：「秦為亂政虐刑，殘滅天下，北為長城之役，南有五領之戍，〔四〕外內騷動，百姓罷敝，〔五〕頭會箕斂〔六〕以供軍費，財匱力盡，〔七〕重以苛法，〔八〕使天下父子不相聊。〔九〕今陳王奮臂為天下倡始，莫不嚮應，〔一０〕家自為怒，各報其怨，〔一一〕縣殺其令丞，郡殺其守尉。今以張大楚，王陳，〔一二〕使吳廣、周文將卒百萬西擊秦。於此時而不成封侯之業者，非人豪也。夫因天下之力而攻無道之君，報父兄之怨而成割地之業，此一時也。」豪桀皆然其言。乃行收兵，得數萬人，號武信君。〔一三〕下趙十餘城，餘皆城守莫肯下。乃引兵東北擊范陽。范陽人蒯通說其令徐公降武信君，又說武信君以侯印封范陽令。語在通傳。趙地聞之，不戰下者三十餘城。","sentenceOrder":22},
  {"id":"s_work_han_thu_43_23","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　師古曰：「與相知也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_43_24","chapterId":"ch_work_han_thu_43","textTraditional":"〔二〕　師古曰：「津名，即今滑州白馬縣界也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_43_25","chapterId":"ch_work_han_thu_43","textTraditional":"〔三〕　鄧展曰：「至河北縣說之。」","sentenceOrder":25},
  {"id":"s_work_han_thu_43_26","chapterId":"ch_work_han_thu_43","textTraditional":"〔四〕　服虔曰：「山領有五，因以為名。交趾、合浦界有此領。」師古曰：「服說非也。領者，西自衡山之南，東窮於海，一山之限耳。而別標名，則有五焉。裴氏廣州記云『大庾、始安、臨賀、桂陽、揭陽，是為五領。』鄧德明南康記曰『大庾領一也，桂陽騎田領二也，九真都龐領三也，臨賀萌渚領四也，始安越城領五也。』裴說是也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_43_27","chapterId":"ch_work_han_thu_43","textTraditional":"〔五〕　師古曰：「罷讀曰疲。」","sentenceOrder":27},
  {"id":"s_work_han_thu_43_28","chapterId":"ch_work_han_thu_43","textTraditional":"〔六〕　服虔曰：「吏到其家，人人頭數出穀，以箕斂之。」","sentenceOrder":28},
  {"id":"s_work_han_thu_43_29","chapterId":"ch_work_han_thu_43","textTraditional":"〔七〕　師古曰：「匱，竭也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_43_30","chapterId":"ch_work_han_thu_43","textTraditional":"〔八〕　師古曰：「重音直用反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_43_31","chapterId":"ch_work_han_thu_43","textTraditional":"〔九〕　師古曰：「言無聊賴，以相保養。」","sentenceOrder":31},
  {"id":"s_work_han_thu_43_32","chapterId":"ch_work_han_thu_43","textTraditional":"〔一０〕師古曰：「倡讀曰唱。嚮讀曰響。」","sentenceOrder":32},
  {"id":"s_work_han_thu_43_33","chapterId":"ch_work_han_thu_43","textTraditional":"〔一一〕師古曰：「為音于偽反。」","sentenceOrder":33},
  {"id":"s_work_han_thu_43_34","chapterId":"ch_work_han_thu_43","textTraditional":"〔一二〕師古曰：「言張建大楚之國，而王於陳也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_43_35","chapterId":"ch_work_han_thu_43","textTraditional":"〔一三〕師古曰：「武臣自號也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_43_36","chapterId":"ch_work_han_thu_43","textTraditional":"至邯鄲，耳、餘聞周章軍入關，至戲卻；〔一〕又聞諸將為陳王徇地，多以讒毀得罪誅。怨陳王不以為將軍而以為校尉，乃說武臣曰：「陳王非必立六國後。〔二〕今將軍下趙數十城，獨介居河北〔三〕，不王無以填之。〔四〕且陳王聽讒，還報，恐不得脫於禍。〔五〕願將軍毋失時。」武臣乃聽，遂立為趙王。以餘為大將軍，耳為丞相。","sentenceOrder":36},
  {"id":"s_work_han_thu_43_37","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　蘇林曰：「至戲地而卻兵。」","sentenceOrder":37},
  {"id":"s_work_han_thu_43_38","chapterId":"ch_work_han_thu_43","textTraditional":"〔二〕　師古曰：「非，不也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_43_39","chapterId":"ch_work_han_thu_43","textTraditional":"〔三〕　晉灼曰：「介音戛。」臣瓚曰：「介，特也。」師古曰：「二說並非也。介，隔也，讀如本字。」","sentenceOrder":39},
  {"id":"s_work_han_thu_43_40","chapterId":"ch_work_han_thu_43","textTraditional":"〔四〕　師古曰：「填音竹刃反。」","sentenceOrder":40},
  {"id":"s_work_han_thu_43_41","chapterId":"ch_work_han_thu_43","textTraditional":"〔五〕　師古曰：「脫，免也，音土活反。」","sentenceOrder":41},
  {"id":"s_work_han_thu_43_42","chapterId":"ch_work_han_thu_43","textTraditional":"使人報陳王，陳王大怒，欲盡族武臣等家，而發兵擊趙。相國房君諫曰：「秦未亡，今又誅武臣等家，此生一秦也。不如因而賀之，使急引兵西擊秦。」陳王從其計，徙繫武臣等家宮中，封耳子敖為成都君。使使者賀趙，趣兵西入關。〔一〕耳、餘說武臣曰：「王王趙，非楚意，特以計賀王。〔二〕楚已滅秦，必加兵於趙。願王毋西兵，北徇燕、代，南收河內，以自廣。趙南據大河，北有燕、代，楚雖勝秦，必不敢制趙。」趙王以為然，因不西兵，而使韓廣略燕，李良略常山，張黶略上黨。〔三〕","sentenceOrder":42},
  {"id":"s_work_han_thu_43_43","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　師古曰：「趣讀曰促。」","sentenceOrder":43},
  {"id":"s_work_han_thu_43_44","chapterId":"ch_work_han_thu_43","textTraditional":"〔二〕　師古曰：「言力不能制，且事安撫為權宜之計耳。」","sentenceOrder":44},
  {"id":"s_work_han_thu_43_45","chapterId":"ch_work_han_thu_43","textTraditional":"〔三〕　師古曰：「黶音烏黠反。」","sentenceOrder":45},
  {"id":"s_work_han_thu_43_46","chapterId":"ch_work_han_thu_43","textTraditional":"韓廣至燕，燕人因立廣為燕王。趙王乃與（陳）〔耳〕、餘北略地燕界。趙王間出，為燕軍所得。〔一〕燕囚之，欲與分地。〔二〕使者往，燕輒殺之，以固求地。耳、餘患之。有廝養卒謝其舍曰〔三〕：「吾為二公說燕，與趙王載歸。」〔四〕舍中人皆笑曰：「使者往十輩皆死，若何以能得王？」〔五〕乃走燕壁。〔六〕燕將見之，問曰：「知臣何欲？」燕將曰：「若欲得王耳。」曰：「君知張耳、陳餘何如人也？」燕將曰：「賢人也。」曰：「其志何欲？」燕將曰：「欲得其王耳。」趙卒笑曰；「君未知兩人所欲也。夫武臣、張耳、陳餘，杖馬箠下趙數十城，〔七〕亦各欲南面而王。夫臣之與主，豈可同日道哉！顧其勢初定，〔八〕且以長少先立武臣，以持趙心。今趙地已服，兩人亦欲分趙而王，時未可耳。今君囚趙王，念此兩人名為求王，實欲燕殺之，此兩人分趙而王。夫以一趙尚易燕，〔九〕況以兩賢王左提右挈，而責殺王，滅燕易矣。」〔一０〕燕以為然，乃歸趙王。養卒為御而歸。","sentenceOrder":46},
  {"id":"s_work_han_thu_43_47","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　師古曰：「間出，謂投間隙而微出也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_43_48","chapterId":"ch_work_han_thu_43","textTraditional":"〔二〕　師古曰：「要劫之，令割趙地輸燕以和解也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_43_49","chapterId":"ch_work_han_thu_43","textTraditional":"〔三〕　蘇林曰：「廝，取薪者也。養，養人者也。舍謂所舍宿主人也。」晉灼曰：「以辭相告曰謝。」師古曰：「謝其舍，謂告其舍中人也。故下言舍中人皆笑。今流俗書本於此舍下輒加人字，非也。廝音斯。」","sentenceOrder":49},
  {"id":"s_work_han_thu_43_50","chapterId":"ch_work_han_thu_43","textTraditional":"〔四〕　師古曰；「二公，張耳、陳餘。」","sentenceOrder":50},
  {"id":"s_work_han_thu_43_51","chapterId":"ch_work_han_thu_43","textTraditional":"〔五〕　師古曰：「若，汝也。次下亦同。」","sentenceOrder":51},
  {"id":"s_work_han_thu_43_52","chapterId":"ch_work_han_thu_43","textTraditional":"〔六〕　師古曰：「走，趣也，音奏。」","sentenceOrder":52},
  {"id":"s_work_han_thu_43_53","chapterId":"ch_work_han_thu_43","textTraditional":"〔七〕　張晏曰：「言其不用兵革也。」師古曰：「箠謂馬撾也，音止橤反。」","sentenceOrder":53},
  {"id":"s_work_han_thu_43_54","chapterId":"ch_work_han_thu_43","textTraditional":"〔八〕　師古曰：「顧，思念也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_43_55","chapterId":"ch_work_han_thu_43","textTraditional":"〔九〕　師古曰：「易，輕也，音弋豉反。」","sentenceOrder":55},
  {"id":"s_work_han_thu_43_56","chapterId":"ch_work_han_thu_43","textTraditional":"〔一０〕師古曰：「提挈，言相扶持也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_43_57","chapterId":"ch_work_han_thu_43","textTraditional":"李良已定常山，還報趙王，趙王復使良略太原。至石邑，秦兵塞井陘，未能前。秦將詐稱二世使使遺良書，不封，〔一〕曰：「良嘗事我，得顯幸，誠能反趙為秦，赦良罪，貴良。」良得書，疑不信，之邯鄲益請兵。〔二〕未至，道逢趙王姊，從百餘騎。良望見，以為王，伏謁道旁。王姊醉，不知其將，使騎謝良。良素貴，起，慚其從官。從官有一人曰：「天下叛秦，能者先立。且趙王素出將軍下，今女兒乃不為將軍下車，請追殺之。」良以得秦書，欲反趙，未決，因此怒，遣人追殺王姊，遂襲邯鄲。邯鄲不知，竟殺武臣。趙人多為耳、餘耳目者，故得脫出。收兵得數萬人。客有說耳、餘曰：「兩君羈旅，〔三〕而欲附趙，難可獨立；〔立〕趙後，輔以誼，〔四〕可就功。」〔五〕及求得趙歇，立為趙王，居信都。〔六〕","sentenceOrder":57},
  {"id":"s_work_han_thu_43_58","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　張晏曰：「欲其漏泄君臣相疑也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_43_59","chapterId":"ch_work_han_thu_43","textTraditional":"〔二〕　師古曰：「之，往也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_43_60","chapterId":"ch_work_han_thu_43","textTraditional":"〔三〕　張晏曰：「羈，寄。旅，客也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_43_61","chapterId":"ch_work_han_thu_43","textTraditional":"〔四〕　師古曰：「謂求取六國時趙王後而立之，以名義自輔助也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_43_62","chapterId":"ch_work_han_thu_43","textTraditional":"〔五〕　師古曰：「就，成也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_43_63","chapterId":"ch_work_han_thu_43","textTraditional":"〔六〕　張晏曰：「歇，趙之苗裔也。信都，襄國也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_43_64","chapterId":"ch_work_han_thu_43","textTraditional":"李良進兵擊餘，餘敗良。良走歸章邯。章邯引兵至邯鄲，皆徙其民河內，夷其城郭。〔一〕耳與趙王歇走入鉅鹿城，王離圍之。餘北收常山兵，得數萬人，軍鉅鹿北。章邯軍鉅鹿南棘原，築甬道屬河，〔二〕饟王離。〔三〕王離兵食多，急攻鉅鹿。鉅鹿城中食盡，耳數使人召餘，餘自度兵少，不能敵秦，不敢前。數月，耳大怒，怨餘，使張黶、陳釋往讓餘〔四〕曰：「始吾與公為刎頸交，今王與耳旦暮死，而公擁兵數萬，不肯相救，相不赴奏俱死？〔五〕且什〔有〕一二相全。」〔六〕餘曰：「所以不俱死，欲為趙王、張君報秦。今俱死，如以肉餧虎，何益？」〔七〕張黶、陳釋曰：「事已急，要以俱死立信，安知後慮！」餘曰：「吾顧以無益。」〔八〕乃使五千人令張黶、陳釋先嘗秦軍，〔九〕至皆沒。","sentenceOrder":64},
  {"id":"s_work_han_thu_43_65","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　師古曰：「夷，平也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_43_66","chapterId":"ch_work_han_thu_43","textTraditional":"〔二〕　師古曰：「屬，聯及也，音之欲反。」","sentenceOrder":66},
  {"id":"s_work_han_thu_43_67","chapterId":"ch_work_han_thu_43","textTraditional":"〔三〕　師古曰：「饟，古餉字，謂饋運其軍糧也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_43_68","chapterId":"ch_work_han_thu_43","textTraditional":"〔四〕　師古曰：「讓，責也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_43_69","chapterId":"ch_work_han_thu_43","textTraditional":"〔五〕　師古曰：「胡，何也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_43_70","chapterId":"ch_work_han_thu_43","textTraditional":"〔六〕　師古曰：「十中尚冀得一二勝秦。」","sentenceOrder":70},
  {"id":"s_work_han_thu_43_71","chapterId":"ch_work_han_thu_43","textTraditional":"〔七〕　師古曰：「餧，飤也，音於偽反。」","sentenceOrder":71},
  {"id":"s_work_han_thu_43_72","chapterId":"ch_work_han_thu_43","textTraditional":"〔八〕　師古曰：「顧，思念也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_43_73","chapterId":"ch_work_han_thu_43","textTraditional":"〔九〕　師古曰：「嘗，試也，言若嘗食云。」","sentenceOrder":73},
  {"id":"s_work_han_thu_43_74","chapterId":"ch_work_han_thu_43","textTraditional":"當是時，燕、齊、楚聞趙急，皆來救。張敖亦北收代，得萬餘人來，皆壁餘旁。項羽兵數絕章邯甬道，王離軍乏食。項羽悉引兵渡河，破章邯軍。諸侯軍及敢擊秦軍，遂虜王離。於是趙王歇、張耳得出鉅鹿。與餘相見，責讓餘，問張黶、陳釋所在。餘曰：「黶、釋以必死責臣，臣使將五千人先嘗秦軍，皆沒。」耳不信，以為殺之，數問餘。餘怒曰：「不意君之望臣深也！〔一〕豈以臣重去將哉？」〔二〕乃脫解印綬與耳，耳不敢受。餘起如廁，客有說耳曰：「天予不取，反受其咎。今陳將軍與君印綬，不受，反天不祥。急取之。」耳乃佩其印，收其麾下。餘還，亦望耳不讓，趨出。耳遂收其兵。餘獨與麾下數百人之河上澤中漁獵。由此有隙。","sentenceOrder":74},
  {"id":"s_work_han_thu_43_75","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　師古曰：「望，怨望也。次下亦同。」","sentenceOrder":75},
  {"id":"s_work_han_thu_43_76","chapterId":"ch_work_han_thu_43","textTraditional":"〔二〕　師古曰：「重，難也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_43_77","chapterId":"ch_work_han_thu_43","textTraditional":"趙王歇復居信都。耳從項羽入關。項羽立諸侯，耳雅遊，多為人所稱。〔一〕項羽素亦聞耳賢，乃分趙立耳為常山王，治信都。〔二〕信都更名襄國。","sentenceOrder":77},
  {"id":"s_work_han_thu_43_78","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　師古曰：「雅，故也。言其久故倦遊，交結英傑，是以多為人所稱譽也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_43_79","chapterId":"ch_work_han_thu_43","textTraditional":"〔二〕　師古曰：「治，為治處也，音丈吏反。」","sentenceOrder":79},
  {"id":"s_work_han_thu_43_80","chapterId":"ch_work_han_thu_43","textTraditional":"餘客多說項羽：「陳餘、張耳一體有功於趙。」羽以餘不從入關，聞其在南皮，即以南皮旁三縣封之。而徙趙王歇王代。","sentenceOrder":80},
  {"id":"s_work_han_thu_43_81","chapterId":"ch_work_han_thu_43","textTraditional":"耳之國，餘愈怒曰：「耳與餘功等也，今耳王，餘獨侯。」及齊王田榮叛楚，餘乃使夏說說田榮〔一〕曰：「項羽為天下宰不平，盡王諸將善地，徙故王王惡地，今趙王乃居代！願王假臣兵，請以南皮為扞蔽。」〔二〕田榮欲樹黨，乃遣兵從餘。餘悉三縣兵，〔三〕襲常山王耳。耳敗走，曰：「漢王與我有故，〔四〕而項王彊，立我，我欲之楚。」〔五〕甘公曰：〔六〕「漢王之入關，五星聚東井。東井者，秦分也。〔七〕先至必王。楚雖彊，後必屬漢。」耳走漢。漢亦還定三秦，方圍章邯廢丘。耳謁漢王，漢王厚遇之。〔八〕","sentenceOrder":81},
  {"id":"s_work_han_thu_43_82","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　師古曰：「夏說讀曰悅。說田榮，音式銳反。」","sentenceOrder":82},
  {"id":"s_work_han_thu_43_83","chapterId":"ch_work_han_thu_43","textTraditional":"〔二〕　師古曰：「扞蔽，猶言藩屏也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_43_84","chapterId":"ch_work_han_thu_43","textTraditional":"〔三〕　師古曰：「悉，盡也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_43_85","chapterId":"ch_work_han_thu_43","textTraditional":"〔四〕　張晏曰：「漢王布衣時常從耳遊也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_43_86","chapterId":"ch_work_han_thu_43","textTraditional":"〔五〕　師古曰：「羽既強盛，又為所立，是以狐疑，莫知所往。」","sentenceOrder":86},
  {"id":"s_work_han_thu_43_87","chapterId":"ch_work_han_thu_43","textTraditional":"〔六〕　文穎曰：「善說星者甘氏也。」晉灼曰：「齊人。」","sentenceOrder":87},
  {"id":"s_work_han_thu_43_88","chapterId":"ch_work_han_thu_43","textTraditional":"〔七〕　師古曰：「分音扶問反。」","sentenceOrder":88},
  {"id":"s_work_han_thu_43_89","chapterId":"ch_work_han_thu_43","textTraditional":"〔八〕　師古曰：「高紀云元年五月漢王定雍地，東如咸陽，引兵圍雍王廢丘，而遣諸將略地。八月，塞王欣、翟王翳皆降漢。二年十月，陳餘擊常山王張耳，耳敗走，降漢。而此傳乃言方圍廢丘時耳謁漢王，隔以他事，於後始云漢二年東擊楚，則與帝紀前後參錯不同，疑傳誤也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_43_90","chapterId":"ch_work_han_thu_43","textTraditional":"餘已敗耳，皆收趙地，迎趙王於代，復為趙王。趙王德餘，〔一〕立以為代王。餘為趙王弱，國初定，留傅趙王，而使夏說以相國守代。〔二〕","sentenceOrder":90},
  {"id":"s_work_han_thu_43_91","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　師古曰：「懷其德。」","sentenceOrder":91},
  {"id":"s_work_han_thu_43_92","chapterId":"ch_work_han_thu_43","textTraditional":"〔二〕　師古曰：「為代相國而居守。」","sentenceOrder":92},
  {"id":"s_work_han_thu_43_93","chapterId":"ch_work_han_thu_43","textTraditional":"漢二年，東擊楚，使告趙，欲與俱。餘曰：「漢殺張耳乃從。」於是漢求人類耳者，斬其頭遺餘，餘乃遣兵助漢。漢敗於彭城西，餘亦聞耳詐死，即背漢。漢遣耳與韓信擊破趙井陘，斬餘泜水上，〔一〕追殺趙王歇襄國。","sentenceOrder":93},
  {"id":"s_work_han_thu_43_94","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　蘇林曰：「泜音祗也。」晉灼曰：「問其方人音柢。」師古曰：「蘇、晉二說皆是也。蘇音祗敬之祗，音執夷反，古音如是。晉音根柢之柢，音丁計反，今其土俗呼水則然。」","sentenceOrder":94},
  {"id":"s_work_han_thu_43_95","chapterId":"ch_work_han_thu_43","textTraditional":"四年夏，立耳為趙王。五年秋，耳薨，諡曰景王。子敖嗣立為王，尚高祖長女魯元公主，為王后。","sentenceOrder":95},
  {"id":"s_work_han_thu_43_96","chapterId":"ch_work_han_thu_43","textTraditional":"七年，高祖從平城過趙，趙王旦暮自上食，體甚卑，有子婿禮。高祖箕踞罵詈，甚慢之。〔一〕趙相貫高、趙午年六十餘，故耳客也，怒曰：「吾王孱王也！」〔二〕說敖曰：「天下豪桀並起，能者先立，今王事皇帝甚恭，皇帝遇王無禮，請為王殺之。」敖齧其指出血，〔三〕曰：「君何言之誤！且先王亡國，賴皇帝得復國，〔四〕德流子孫，秋豪皆帝力也。願君無復出口。」貫高等十餘人相謂曰：「吾等非也。吾王長者，不背德。且吾等義不辱，今帝辱我王，故欲殺之，何乃汙王為？〔五〕事成歸王，事敗獨身坐耳。」","sentenceOrder":96},
  {"id":"s_work_han_thu_43_97","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　師古曰：「箕踞者，謂申兩腳其形如箕。」","sentenceOrder":97},
  {"id":"s_work_han_thu_43_98","chapterId":"ch_work_han_thu_43","textTraditional":"〔二〕　孟康曰：「冀州人謂懦弱為孱。」師古曰：「音士連反。」","sentenceOrder":98},
  {"id":"s_work_han_thu_43_99","chapterId":"ch_work_han_thu_43","textTraditional":"〔三〕　師古曰：「自齧其指出血，以表至誠，而為誓約，不背漢也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_43_100","chapterId":"ch_work_han_thu_43","textTraditional":"〔四〕　師古曰：「復音房目反。」","sentenceOrder":100},
  {"id":"s_work_han_thu_43_101","chapterId":"ch_work_han_thu_43","textTraditional":"〔五〕　師古曰：「言何為乃汙染王。」","sentenceOrder":101},
  {"id":"s_work_han_thu_43_102","chapterId":"ch_work_han_thu_43","textTraditional":"八年，上從東垣過。〔一〕貫高等乃壁人柏人，要之置廁。〔二〕上過欲宿，心動，問曰：「縣名為何？」曰：「柏人。」「柏人者，迫於人！」不宿去。","sentenceOrder":102},
  {"id":"s_work_han_thu_43_103","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　師古曰：「擊韓王信餘寇於東垣，還而過趙。」","sentenceOrder":103},
  {"id":"s_work_han_thu_43_104","chapterId":"ch_work_han_thu_43","textTraditional":"〔二〕　文穎曰：「置人廁壁中以伺高祖。」","sentenceOrder":104},
  {"id":"s_work_han_thu_43_105","chapterId":"ch_work_han_thu_43","textTraditional":"九年，貫高怨家知其謀，告之。於是上逮捕趙王諸反者。趙午等十餘人皆爭自剄，貫高獨怒罵曰：「誰令公等為之？今王實無謀，而并捕王；公等死，誰當白王不反者？」〔一〕乃檻車與王詣長安〔二〕。高對獄曰：「獨吾屬為之，王不知也。」吏榜笞數千，〔三〕刺爇，身無完者，〔四〕終不復言。呂后數言張王以魯元故，不宜有此。上怒曰：「使長敖據天下，豈少乃女虖！」〔五〕廷尉以貫高辭聞，上曰：「壯士！誰知者，以私問之。」〔六〕中大夫泄公曰：「臣素知之，〔七〕此固趙國立名義不侵為然諾者也。」〔八〕上使泄公持節問之箯輿前。卬視泄公，〔九〕勞若如平生歡。〔一０〕與語，問張王果有謀不。〔一一〕高曰：「人情豈不各愛其父母妻子哉？今吾三族皆以論死，豈以王易吾親哉！〔一二〕顧為王實不反，〔一三〕獨吾等為之。」具道本根所以，王不知狀。於是泄公具以報上，上乃赦趙王。","sentenceOrder":105},
  {"id":"s_work_han_thu_43_106","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　師古曰：「白，明也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_43_107","chapterId":"ch_work_han_thu_43","textTraditional":"〔二〕　師古曰：「檻車者，車而為檻形，謂以板四周之，無所通見。」","sentenceOrder":107},
  {"id":"s_work_han_thu_43_108","chapterId":"ch_work_han_thu_43","textTraditional":"〔三〕　師古曰；「榜謂捶擊之也，音彭。他皆類此。」","sentenceOrder":108},
  {"id":"s_work_han_thu_43_109","chapterId":"ch_work_han_thu_43","textTraditional":"〔四〕　應劭曰：「以鐵刺之，又燒灼之。」師古曰：「爇音而說反。」","sentenceOrder":109},
  {"id":"s_work_han_thu_43_110","chapterId":"ch_work_han_thu_43","textTraditional":"〔五〕　師古曰：「乃，汝也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_43_111","chapterId":"ch_work_han_thu_43","textTraditional":"〔六〕　張晏曰：「以和悅問之。」臣瓚曰：「字多作私，謂以私情相問也。」師古曰：「瓚說是也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_43_112","chapterId":"ch_work_han_thu_43","textTraditional":"〔七〕　師古曰：「泄音薛。」","sentenceOrder":112},
  {"id":"s_work_han_thu_43_113","chapterId":"ch_work_han_thu_43","textTraditional":"〔八〕　師古曰：「侵猶犯負也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_43_114","chapterId":"ch_work_han_thu_43","textTraditional":"〔九〕　師古曰：「箯輿者，編竹木以為輿形，如今之食輿矣。高時榜笞刺爇委困，故以箯輿處之也。箯音鞭。卬讀曰仰。」","sentenceOrder":114},
  {"id":"s_work_han_thu_43_115","chapterId":"ch_work_han_thu_43","textTraditional":"〔一０〕師古曰：「勞苦，相勞問其勤苦也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_43_116","chapterId":"ch_work_han_thu_43","textTraditional":"〔一一〕師古曰：「果猶決也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_43_117","chapterId":"ch_work_han_thu_43","textTraditional":"〔一二〕師古曰：「易，代也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_43_118","chapterId":"ch_work_han_thu_43","textTraditional":"〔一三〕師古曰：「顧，思念也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_43_119","chapterId":"ch_work_han_thu_43","textTraditional":"上賢高能自立然諾，使泄公赦之，告曰：「張王已出，上多足下，〔一〕故赦足下。」高曰：「所以不死，白張王不反耳。今王已出，吾責塞矣。〔二〕且人臣有篡弒之名，豈有面目復事上哉！」乃仰絕亢而死。〔三〕","sentenceOrder":119},
  {"id":"s_work_han_thu_43_120","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　師古曰：「多猶重也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_43_121","chapterId":"ch_work_han_thu_43","textTraditional":"〔二〕　師古曰：「塞，當也，滿也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_43_122","chapterId":"ch_work_han_thu_43","textTraditional":"〔三〕　蘇林曰：「亢，頸大脈也，俗所謂胡脈也。」師古曰：「亢者，總謂頸耳。爾雅云『亢，鳥嚨』，即喉嚨也，音下郎反，又音工郎反。」","sentenceOrder":122},
  {"id":"s_work_han_thu_43_123","chapterId":"ch_work_han_thu_43","textTraditional":"敖已出，尚魯元公主如故，〔一〕封為宣平侯。於是上賢張王諸客，皆以為諸侯相、郡守。語在田叔傳。及孝惠、高后、文、景時，張王客子孫皆為二千石。","sentenceOrder":123},
  {"id":"s_work_han_thu_43_124","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　師古曰：「尚猶配也。易泰卦九二爻辭曰『得尚于中行』，王弼亦以為配也。諸言尚公主者其義皆然。而說者乃云尚公主，與尚書尚食同意，訓尚為主，言主掌之，失其理矣。公主既尊，又非物類，不得以主掌為辭，貢禹又云『諸侯則國人承公主』，益知主不得言主掌也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_43_125","chapterId":"ch_work_han_thu_43","textTraditional":"初，孝惠時，齊悼惠王獻城陽郡，尊魯元公主為太后。〔一〕高后元年，魯元太后薨。後六年，宣平侯敖復薨。呂太后立敖子偃為魯王，以母為太后故也。〔二〕又憐其年少孤弱，乃封敖前婦子二人：壽為樂昌侯，侈為信都侯。高后崩，大臣誅諸呂，廢魯王及二侯。孝文即位，復封故魯王偃為南宮侯。薨，子生嗣。武帝時，生有罪免，國除。元光中，復封偃孫廣國為睢陵侯。〔三〕薨，子昌嗣。太初中，昌坐不敬免，國除。孝平元始二年，繼絕世，封敖玄孫慶忌為宣平侯，食千戶。","sentenceOrder":125},
  {"id":"s_work_han_thu_43_126","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　師古曰：「為齊太后，以母禮事之。」","sentenceOrder":126},
  {"id":"s_work_han_thu_43_127","chapterId":"ch_work_han_thu_43","textTraditional":"〔二〕　師古曰：「以公主為齊王太后，故立其子為王。」","sentenceOrder":127},
  {"id":"s_work_han_thu_43_128","chapterId":"ch_work_han_thu_43","textTraditional":"〔三〕　師古曰：「睢音雖。」","sentenceOrder":128},
  {"id":"s_work_han_thu_43_129","chapterId":"ch_work_han_thu_43","textTraditional":"贊曰：張耳、陳餘，世所稱賢，其賓客廝役皆天下俊桀，所居國無不取卿相者。然耳、餘始居約時，〔一〕相然信死，豈顧問哉！及據國爭權，卒相滅亡，何鄉者慕用之誠，〔二〕後相背之盭也！〔三〕勢利之交，古人羞之，蓋謂是矣。","sentenceOrder":129},
  {"id":"s_work_han_thu_43_130","chapterId":"ch_work_han_thu_43","textTraditional":"〔一〕　晉灼曰：「始在貧賤儉約之時。」","sentenceOrder":130},
  {"id":"s_work_han_thu_43_131","chapterId":"ch_work_han_thu_43","textTraditional":"〔二〕　師古曰：「鄉讀曰嚮。嚮謂曩昔也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_43_132","chapterId":"ch_work_han_thu_43","textTraditional":"〔三〕　師古曰：「盭，古戾字。戾，違也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_43_133","chapterId":"ch_work_han_thu_43","textTraditional":"校勘記","sentenceOrder":133},
  {"id":"s_work_han_thu_43_134","chapterId":"ch_work_han_thu_43","textTraditional":"一八三０頁一四行　恐天下解（矣）〔也〕。　景祐、殿本都作「也」。","sentenceOrder":134},
  {"id":"s_work_han_thu_43_135","chapterId":"ch_work_han_thu_43","textTraditional":"一八三三頁一四行　趙王乃與（陳）〔耳〕、餘北略地燕界。　景祐、殿本都作「耳」。王先謙說「陳」為「耳」之誤。","sentenceOrder":135},
  {"id":"s_work_han_thu_43_136","chapterId":"ch_work_han_thu_43","textTraditional":"一八三五頁　九行　難可獨立；〔立〕趙後，　景祐、殿本都重「立」字。王先謙說重「立」字是。","sentenceOrder":136},
  {"id":"s_work_han_thu_43_137","chapterId":"ch_work_han_thu_43","textTraditional":"一八三六頁　五行　且什〔有〕一二相全。　景祐、殿本都有「有」字。王先謙說有「有」字是。","sentenceOrder":137},
  {"id":"s_work_han_thu_44_1","chapterId":"ch_work_han_thu_44","textTraditional":"魏豹，故魏諸公子也。〔一〕其兄魏咎，故魏時封為甯陵君，秦滅魏，〔二〕為庶人。陳勝之王也，咎往從之。勝使魏人周市徇魏地，〔三〕魏地已下，欲立周市為魏王。市曰：「天下昏亂，忠臣乃見。〔四〕今天下共畔秦，其誼必立魏王後乃可。」齊、趙使車各五十乘，立市為王。市不受，迎魏咎於陳，五反，〔五〕陳王乃遣立咎為魏王。","sentenceOrder":1},
  {"id":"s_work_han_thu_44_2","chapterId":"ch_work_han_thu_44","textTraditional":"〔一〕　師古曰：「六國時魏也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_44_3","chapterId":"ch_work_han_thu_44","textTraditional":"〔二〕　文穎曰：「魏，大梁也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_44_4","chapterId":"ch_work_han_thu_44","textTraditional":"〔三〕　師古曰：「徇，略也，音辭峻反。」","sentenceOrder":4},
  {"id":"s_work_han_thu_44_5","chapterId":"ch_work_han_thu_44","textTraditional":"〔四〕　師古曰：「言當昏亂之時，忠臣乃得顯其節義也。老子道經曰『國家昏亂有忠臣』。」","sentenceOrder":5},
  {"id":"s_work_han_thu_44_6","chapterId":"ch_work_han_thu_44","textTraditional":"〔五〕　師古曰：「反謂回還也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_44_7","chapterId":"ch_work_han_thu_44","textTraditional":"章邯已破陳王，進兵擊魏王於臨濟。魏王使周市請救齊、楚。齊、楚遣項它、田巴將兵，隨市救魏。〔一〕章邯遂擊破殺周市等軍，圍臨濟。咎為其民約降。〔二〕約降定，咎自殺。〔三〕","sentenceOrder":7},
  {"id":"s_work_han_thu_44_8","chapterId":"ch_work_han_thu_44","textTraditional":"〔一〕　師古曰：「楚遣項它，齊遣田巴。」","sentenceOrder":8},
  {"id":"s_work_han_thu_44_9","chapterId":"ch_work_han_thu_44","textTraditional":"〔二〕　師古曰：「與章邯為誓而約降。」","sentenceOrder":9},
  {"id":"s_work_han_thu_44_10","chapterId":"ch_work_han_thu_44","textTraditional":"〔三〕　師古曰：「但欲全其人，而身自不降。」","sentenceOrder":10},
  {"id":"s_work_han_thu_44_11","chapterId":"ch_work_han_thu_44","textTraditional":"魏豹亡走楚。楚懷王予豹數千人，復徇魏地。項羽己破秦兵，降章邯，豹下魏二十餘城，立為魏王。〔一〕豹引精兵從項羽入關。羽封諸侯，欲有梁地，〔二〕乃徙豹於河東，都平陽，為西魏王。","sentenceOrder":11},
  {"id":"s_work_han_thu_44_12","chapterId":"ch_work_han_thu_44","textTraditional":"〔一〕　師古曰：「項羽立之。」","sentenceOrder":12},
  {"id":"s_work_han_thu_44_13","chapterId":"ch_work_han_thu_44","textTraditional":"〔二〕　師古曰：「羽欲自取梁地。」","sentenceOrder":13},
  {"id":"s_work_han_thu_44_14","chapterId":"ch_work_han_thu_44","textTraditional":"漢王還定三秦，渡臨晉，豹以國屬焉，遂從擊楚於彭城。漢王敗，還至滎陽，豹請視親病，〔一〕至國，則絕河津畔漢。漢王謂酈生曰：「緩頰往說之。」酈生（至）〔往〕，豹謝曰：「人生一世間，如白駒過隙。〔二〕今漢王嫚侮人，罵詈諸侯群臣如奴耳，非有上下禮節，吾不忍復見也。」漢王遣韓信擊豹，遂虜之，傳豹詣滎陽，以其地為河東、太原、上黨郡。漢王令豹守滎陽。楚圍之急，周苛曰：「反國之王，難與共守。」遂殺豹。〔三〕","sentenceOrder":14},
  {"id":"s_work_han_thu_44_15","chapterId":"ch_work_han_thu_44","textTraditional":"〔一〕　師古曰：「親謂母也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_44_16","chapterId":"ch_work_han_thu_44","textTraditional":"〔二〕　師古曰：「言其速疾也。白駒謂日景也。隙，壁際也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_44_17","chapterId":"ch_work_han_thu_44","textTraditional":"〔三〕　師古曰：「反國，言其嘗叛也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_44_18","chapterId":"ch_work_han_thu_44","textTraditional":"田儋，狄人也，〔一〕故齊王田氏之族也。〔二〕儋從弟榮，榮弟橫，皆豪桀，宗彊，能得人。陳涉使周市略地，北至狄，狄城守。儋陽為縛其奴，從少年之廷，欲謁殺奴。〔三〕見狄令，因擊殺令，而召豪吏子弟曰：「諸侯皆反秦自立，齊，古之建國，儋，田氏，當王。」遂自立為齊王，發兵擊周市。市軍還去，儋因率兵東略定齊地。","sentenceOrder":18},
  {"id":"s_work_han_thu_44_19","chapterId":"ch_work_han_thu_44","textTraditional":"〔一〕　師古曰：「狄，縣名也，地理志屬千乘。」","sentenceOrder":19},
  {"id":"s_work_han_thu_44_20","chapterId":"ch_work_han_thu_44","textTraditional":"〔二〕　師古曰：「亦六國時齊也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_44_21","chapterId":"ch_work_han_thu_44","textTraditional":"〔三〕　服虔曰：「古殺奴婢，皆當告官，儋欲殺令，故詐縛奴以謁也。」師古曰：「陽縛其奴，為殺奴之狀。廷，縣廷之中也，音定。今流俗書本為字作偽，非也。陽即偽耳，不當重言之。」","sentenceOrder":21},
  {"id":"s_work_han_thu_44_22","chapterId":"ch_work_han_thu_44","textTraditional":"秦將章邯圍魏王咎於臨濟，急。魏王請救於齊，儋將兵救魏。章邯夜銜枚擊，大破齊、楚軍，殺儋於臨濟下。儋從弟榮收儋餘兵東走東阿。","sentenceOrder":22},
  {"id":"s_work_han_thu_44_23","chapterId":"ch_work_han_thu_44","textTraditional":"齊人聞儋死，乃立故齊王建之弟田假為王，田角為相，田閒為將，以距諸侯。","sentenceOrder":23},
  {"id":"s_work_han_thu_44_24","chapterId":"ch_work_han_thu_44","textTraditional":"榮之走東阿，章邯追圍之。項梁聞榮急，乃引兵擊破章邯東阿下。章邯走而西，項梁因追之。而榮怒齊之立假，乃引兵歸，擊逐假。假亡走楚。相角亡走趙。角弟閒前救趙，因不敢歸。榮乃立儋子市為王，榮相之，橫為將，平齊地。","sentenceOrder":24},
  {"id":"s_work_han_thu_44_25","chapterId":"ch_work_han_thu_44","textTraditional":"項梁既追章邯，章邯兵益盛，項梁使使趣齊兵共擊章邯。〔一〕榮曰：「楚殺田假，趙殺角、閒，乃出兵。」楚懷王曰：「田假與國之王，窮而歸我，殺之不誼。」趙亦不殺田角、田閒以市於齊。齊王曰：「蝮蠚手則斬手，蠚足則斬足。〔二〕何者？為害於身也。田假、田角、田閒於楚、趙，非手足戚，〔三〕何故不殺？且秦復得志於天下，則齮齕首用事者墳墓矣。」〔四〕楚、趙不聽齊，齊亦怒，終不肯出兵。章邯果敗殺項梁，〔五〕破楚兵。楚兵東走，而章邯渡河圍趙於鉅鹿。項羽由此怨榮。","sentenceOrder":25},
  {"id":"s_work_han_thu_44_26","chapterId":"ch_work_han_thu_44","textTraditional":"〔一〕　師古曰：「趣讀曰促。」","sentenceOrder":26},
  {"id":"s_work_han_thu_44_27","chapterId":"ch_work_han_thu_44","textTraditional":"〔二〕　應劭曰：「蝮一名虺。蠚，螫也。螫人手足則割去其肉，不然則死。」師古曰：「爾雅及說文皆以為蝮即虺也，博三寸，首大如擘，而郭璞云各自一種蛇。其蝮蛇，細頸大頭焦尾，色如綬文，文間有毛，似豬鬣，鼻上有針，大者長七八尺，一名反鼻，非虺之類也。以今俗名證之，郭說得矣。虺若土色，所在有之，俗呼土虺。其蝮唯出南方。蝮音芳六反。蠚音火各反。螫音式亦反。虺音許偉反。擘者，人手大指也，音步歷反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_44_28","chapterId":"ch_work_han_thu_44","textTraditional":"〔三〕　文穎曰：「言將亡身，非手足憂也。」臣瓚曰：「田假於楚，非手足之親也。」師古曰：「瓚說是也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_44_29","chapterId":"ch_work_han_thu_44","textTraditional":"〔四〕　如淳曰：「齮，側齧也。齕，鞮也。」師古曰：「首用事，謂起兵而立號者也。齮音螘。齕音紇。鞮音五絞反。」","sentenceOrder":29},
  {"id":"s_work_han_thu_44_30","chapterId":"ch_work_han_thu_44","textTraditional":"〔五〕　師古曰：「擊敗而殺之。」","sentenceOrder":30},
  {"id":"s_work_han_thu_44_31","chapterId":"ch_work_han_thu_44","textTraditional":"羽既存趙，降章邯，西滅秦，立諸侯王，乃徙齊王市更王膠東，治即墨。〔一〕齊將田都從共救趙，因入關，故立都為齊王，治臨菑。故齊王建孫田安，項羽方渡河救趙，安下濟北數城，引兵降項羽，羽立安為濟北王，治博陽。榮以負項梁，不肯助楚攻秦，故不得王。趙將陳餘亦失職，不得王。二人俱怨項羽。","sentenceOrder":31},
  {"id":"s_work_han_thu_44_32","chapterId":"ch_work_han_thu_44","textTraditional":"〔一〕　師古曰：「治謂都之也，音丈吏反。下皆類此。」","sentenceOrder":32},
  {"id":"s_work_han_thu_44_33","chapterId":"ch_work_han_thu_44","textTraditional":"榮使人將兵助陳餘，令反趙地，而榮亦發兵以距擊田都，都亡走楚。榮留齊王市毋之膠東。市左右曰：「項王強暴，王不就國，必危。」市懼，乃亡就國。榮怒，追擊殺市於即墨，還攻殺濟北王安，自立為王，盡并三齊之地。〔一〕","sentenceOrder":33},
  {"id":"s_work_han_thu_44_34","chapterId":"ch_work_han_thu_44","textTraditional":"〔一〕　師古曰：「三齊，齊及濟北、膠東。」","sentenceOrder":34},
  {"id":"s_work_han_thu_44_35","chapterId":"ch_work_han_thu_44","textTraditional":"項王聞之，大怒，乃北伐齊。榮發兵距之城陽。榮兵敗，走平原，平原民殺榮。項羽遂燒夷齊城郭，〔一〕所過盡屠破。齊人相聚畔之。榮弟橫收齊散兵，得數萬人，反擊項羽於城陽。而漢王帥諸侯敗楚，入彭城。項羽聞之，乃釋齊〔二〕而歸擊漢於彭城，因連與漢戰，相距滎陽。以故橫復收齊城邑，立榮子廣為王，而橫相之，政事無巨細皆斷於橫。","sentenceOrder":35},
  {"id":"s_work_han_thu_44_36","chapterId":"ch_work_han_thu_44","textTraditional":"〔一〕　師古曰：「夷，平也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_44_37","chapterId":"ch_work_han_thu_44","textTraditional":"〔二〕　師古曰：「釋，解也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_44_38","chapterId":"ch_work_han_thu_44","textTraditional":"定齊三年，聞漢將韓信引兵且東擊齊，齊使華毋傷、田解〔一〕軍歷下以距漢。〔二〕會漢使酈食其往說王廣及相橫，與連和。橫然之，乃罷歷下守備，縱酒，〔三〕且遣使與漢平。〔四〕韓信乃渡平原，襲破齊歷下軍，因入臨菑。王廣、相橫以酈生為賣己而亨之〔五〕。廣東走高密，橫走博，〔六〕守相田光走城陽，〔七〕將軍田既軍於膠東。楚使龍且救齊，〔八〕齊王與合軍高密。漢將韓信、曹參破殺龍且，虜齊王廣。漢將灌嬰追得守相光，至博。而橫聞王死，自立為王，還擊嬰，嬰敗橫軍於贏下。〔九〕橫亡走梁，歸彭越。越時居梁地，中立，且為漢，且為楚。〔一０〕韓信已殺龍且，因進兵破殺田既於膠東，灌嬰破殺齊將田吸於千乘，〔一一〕遂平齊地。","sentenceOrder":38},
  {"id":"s_work_han_thu_44_39","chapterId":"ch_work_han_thu_44","textTraditional":"〔一〕　師古曰：「二人也。華音戶化反。」","sentenceOrder":39},
  {"id":"s_work_han_thu_44_40","chapterId":"ch_work_han_thu_44","textTraditional":"〔二〕　張晏曰：「濟南歷山之下。」","sentenceOrder":40},
  {"id":"s_work_han_thu_44_41","chapterId":"ch_work_han_thu_44","textTraditional":"〔三〕　師古曰：「縱，放也。放意而飲酒。」","sentenceOrder":41},
  {"id":"s_work_han_thu_44_42","chapterId":"ch_work_han_thu_44","textTraditional":"〔四〕　師古曰：「方欲遣使。」","sentenceOrder":42},
  {"id":"s_work_han_thu_44_43","chapterId":"ch_work_han_thu_44","textTraditional":"〔五〕　師古曰：「謂其與韓信合謀。」","sentenceOrder":43},
  {"id":"s_work_han_thu_44_44","chapterId":"ch_work_han_thu_44","textTraditional":"〔六〕　蘇林曰：「泰山博縣。」","sentenceOrder":44},
  {"id":"s_work_han_thu_44_45","chapterId":"ch_work_han_thu_44","textTraditional":"〔七〕　師古曰：「守相者，言為相而專主居守之事。」","sentenceOrder":45},
  {"id":"s_work_han_thu_44_46","chapterId":"ch_work_han_thu_44","textTraditional":"〔八〕　師古曰：「且音子閭反。」","sentenceOrder":46},
  {"id":"s_work_han_thu_44_47","chapterId":"ch_work_han_thu_44","textTraditional":"〔九〕　晉灼曰：「泰山贏縣也。」師古曰：「音弋成反。」","sentenceOrder":47},
  {"id":"s_work_han_thu_44_48","chapterId":"ch_work_han_thu_44","textTraditional":"〔一０〕師古曰：「言在楚、漢之間，居中自立而兩助之也。中音竹仲反。」","sentenceOrder":48},
  {"id":"s_work_han_thu_44_49","chapterId":"ch_work_han_thu_44","textTraditional":"〔一一〕師古曰：「吸音許及反。」","sentenceOrder":49},
  {"id":"s_work_han_thu_44_50","chapterId":"ch_work_han_thu_44","textTraditional":"漢滅項籍，漢王立為皇帝，彭越為梁王。橫懼誅，而與其徒屬五百餘人入海，居隝中。〔一〕高帝聞之，以橫兄弟本定齊，齊人賢者多附焉，今在海中不收，後恐有亂，乃使使赦橫罪而召之。橫謝曰：「臣亨陛下之使酈食其，今聞其弟商為漢將而賢，臣恐懼，不敢奉詔，請為庶人，守海隝中。」使還報，高帝乃詔衛尉酈商曰：「齊王橫即至，人馬從者敢動搖者致族夷！」〔二〕乃復使使持節具告以詔意，曰：「橫來，大者王，小者乃侯耳；〔三〕不來，且發兵加誅。」橫乃與其客二人乘傳詣雒陽。〔四〕","sentenceOrder":50},
  {"id":"s_work_han_thu_44_51","chapterId":"ch_work_han_thu_44","textTraditional":"〔一〕　韋昭曰：「海中山曰隝。」師古曰：「音丁老反。」","sentenceOrder":51},
  {"id":"s_work_han_thu_44_52","chapterId":"ch_work_han_thu_44","textTraditional":"〔二〕　師古曰：「族夷，言平除其族。」","sentenceOrder":52},
  {"id":"s_work_han_thu_44_53","chapterId":"ch_work_han_thu_44","textTraditional":"〔三〕　師古曰：「大者謂橫身，小者其徒屬。」","sentenceOrder":53},
  {"id":"s_work_han_thu_44_54","chapterId":"ch_work_han_thu_44","textTraditional":"〔四〕　師古曰：「傳音張戀反。」","sentenceOrder":54},
  {"id":"s_work_han_thu_44_55","chapterId":"ch_work_han_thu_44","textTraditional":"至尸鄉廄置，〔一〕橫謝使者曰：「人臣見天子，當洗沐。」止留。謂其客曰：「橫始與漢王俱南面稱孤，〔二〕今漢王為天子，而橫乃為亡虜，北面事之，其媿固已甚矣。又吾亨人之兄，與其弟併肩而事主，〔三〕縱彼畏天子之詔，不敢動搖，我獨不媿於心乎？且陛下所以欲見我，不過欲壹見我面貌耳。陛下在雒陽，今斬吾頭，馳三十里間，形容尚未能敗，猶可知也。」遂自剄，令客奉其頭，從使者馳奏之高帝。高帝曰：「嗟乎，有以！起布衣，兄弟三人更王，〔四〕豈非賢哉！」為之流涕，而拜其二客為都尉，發卒二千，以王者禮葬橫。","sentenceOrder":55},
  {"id":"s_work_han_thu_44_56","chapterId":"ch_work_han_thu_44","textTraditional":"〔一〕　（師古）〔應劭〕曰：「尸鄉在偃師城西。」臣瓚曰：「案廄置謂置馬以傳驛者。」","sentenceOrder":56},
  {"id":"s_work_han_thu_44_57","chapterId":"ch_work_han_thu_44","textTraditional":"〔二〕　師古曰：「王者自稱曰孤，蓋為謙也。老子德經曰貴以賤為本，高以下為基，是以侯王自謂孤寡不穀。」","sentenceOrder":57},
  {"id":"s_work_han_thu_44_58","chapterId":"ch_work_han_thu_44","textTraditional":"〔三〕　師古曰：「併音步鼎反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_44_59","chapterId":"ch_work_han_thu_44","textTraditional":"〔四〕　師古曰：「更音工衡反。」","sentenceOrder":59},
  {"id":"s_work_han_thu_44_60","chapterId":"ch_work_han_thu_44","textTraditional":"既葬，二客穿其冢旁，皆自剄從之。高帝聞而大驚，以橫之客皆賢者，吾聞其餘尚五百人在海中，使使召至，聞橫死，亦皆自殺。於是乃知田橫兄弟能得士也。","sentenceOrder":60},
  {"id":"s_work_han_thu_44_61","chapterId":"ch_work_han_thu_44","textTraditional":"韓王信，故韓襄王孽孫也，〔一〕長八尺五寸。項梁立楚懷王，燕、齊、趙、魏皆已前王，唯韓無有後，故立韓公子橫陽（城君）〔君成〕為韓王，欲以撫定韓地。項梁死定陶，成奔懷王。〔二〕沛公引兵擊陽城，使張良以韓司徒徇韓地，得信，以為韓將，將其兵從入武關。","sentenceOrder":61},
  {"id":"s_work_han_thu_44_62","chapterId":"ch_work_han_thu_44","textTraditional":"〔一〕　張晏曰：「孺子為孽。」師古曰：「孽謂庶耳。張說非也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_44_63","chapterId":"ch_work_han_thu_44","textTraditional":"〔二〕　師古曰：「犇，古奔字。」","sentenceOrder":63},
  {"id":"s_work_han_thu_44_64","chapterId":"ch_work_han_thu_44","textTraditional":"沛公為漢王，信從入漢中，乃說漢王曰：「項王王諸將，王獨居此，遷也。士卒皆山東人，竦而望歸，及其蠭東鄉，可以爭天下。」〔一〕漢王還定三秦，乃許王信，先拜為韓太尉，將兵略韓地。","sentenceOrder":64},
  {"id":"s_work_han_thu_44_65","chapterId":"ch_work_han_thu_44","textTraditional":"〔一〕　鄭氏曰：「及軍中將士氣鋒也。」師古曰：「高紀及韓彭英盧傳皆稱斯說是楚王韓信之辭，而此傳復云韓王信之語，豈史家謬錯乎？將二人所勸大指實同也？竦謂引領舉足也。蠭與鋒同。鄉讀曰嚮。」","sentenceOrder":65},
  {"id":"s_work_han_thu_44_66","chapterId":"ch_work_han_thu_44","textTraditional":"項籍之封諸王皆就國，韓王成以不從無功，不遣之國，更封為穰侯，〔一〕後又殺之。聞漢遣信略韓地，乃令故籍游吳時令鄭昌為韓王〔二〕距漢。漢二年，信略定韓地十餘城。漢王至河南，信急擊韓王昌，昌降漢。乃立信為韓王，常將韓兵從。漢王使信與周苛等守滎陽，楚拔之，信降楚。已得亡歸漢，〔三〕漢復以為韓王，竟從擊破項籍。五年春，與信剖符，王潁川。〔四〕","sentenceOrder":66},
  {"id":"s_work_han_thu_44_67","chapterId":"ch_work_han_thu_44","textTraditional":"〔一〕　文穎曰：「穰，南陽縣也。」臣瓚曰：「穰縣屬江夏。」師古曰：「文說是也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_44_68","chapterId":"ch_work_han_thu_44","textTraditional":"〔二〕　孟康曰：「項籍在吳時，昌為吳縣令。」","sentenceOrder":68},
  {"id":"s_work_han_thu_44_69","chapterId":"ch_work_han_thu_44","textTraditional":"〔三〕　師古曰：「降楚之後復得歸漢。」","sentenceOrder":69},
  {"id":"s_work_han_thu_44_70","chapterId":"ch_work_han_thu_44","textTraditional":"〔四〕　師古曰：「剖，分也。為合符而分之。」","sentenceOrder":70},
  {"id":"s_work_han_thu_44_71","chapterId":"ch_work_han_thu_44","textTraditional":"六年春，上以為信壯武，北近鞏、雒，〔一〕南迫宛、葉，〔二〕東有淮陽，皆天下勁兵處也，乃更以太原郡為韓國，徙信以備胡，都晉陽。信上書曰：「國被邊，〔三〕匈奴數入，晉陽去塞遠，請治馬邑。」上許之。秋，匈奴冒頓大入圍信，信數使使胡求和解。漢發兵救之，疑信數間使，有二心。〔四〕上賜信書責讓之曰：「專死不勇，專生不任，〔五〕寇攻馬邑，君王力不足以堅守乎？安危存亡之地，此二者朕所以責於君王。」〔六〕信得書，恐誅，因與匈奴約共攻漢，以馬邑降胡，擊太原。","sentenceOrder":71},
  {"id":"s_work_han_thu_44_72","chapterId":"ch_work_han_thu_44","textTraditional":"〔一〕　師古曰：「鞏即今鞏縣。」","sentenceOrder":72},
  {"id":"s_work_han_thu_44_73","chapterId":"ch_work_han_thu_44","textTraditional":"〔二〕　師古曰：「南陽之二縣也。宛音於元反。葉音式涉反。」","sentenceOrder":73},
  {"id":"s_work_han_thu_44_74","chapterId":"ch_work_han_thu_44","textTraditional":"〔三〕　李奇曰：「被音被馬之被。」師古曰：「被猶帶也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_44_75","chapterId":"ch_work_han_thu_44","textTraditional":"〔四〕　師古曰：「間，私也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_44_76","chapterId":"ch_work_han_thu_44","textTraditional":"〔五〕　李奇曰：「言為將軍，齎必死之意不得為勇，齎必生之心不任軍事。傳曰『期死非勇也，必生非任也』。」","sentenceOrder":76},
  {"id":"s_work_han_thu_44_77","chapterId":"ch_work_han_thu_44","textTraditional":"〔六〕　師古曰：「言雖處危亡之地，執忠履信，可以安存，責其有二心。」","sentenceOrder":77},
  {"id":"s_work_han_thu_44_78","chapterId":"ch_work_han_thu_44","textTraditional":"七年冬，上自往擊破信軍銅鞮，〔一〕斬其將王喜。信亡走匈奴。（與）其將白土人曼丘臣、王黃〔二〕立趙苗裔趙利為王，〔三〕復收信散兵，而與信及冒頓謀攻漢。匈奴使左右賢王將萬餘騎與王黃等屯廣武以南，至晉陽，〔四〕與漢兵戰，漢兵大破之，追至于離石，復破之。〔五〕匈奴復聚兵樓煩西北。漢令車騎擊匈奴，常敗走，漢乘勝追北。聞冒頓居代谷，上居晉陽，使人視冒頓，還報曰「可擊」。上遂至平城，上白登。〔六〕匈奴騎圍上，上乃使人厚遺閼氏。〔七〕閼氏說冒頓曰：「今得漢地，猶不能居，且兩主不相厄。」居七日，胡騎稍稍引去。天霧，漢使人往來，胡不覺。護軍中尉陳平言上曰：「胡者全兵，〔八〕請令彊弩傅兩矢外鄉，〔九〕徐行出圍。」入平城，漢救兵亦至。胡騎遂解去，漢亦罷兵歸。信為匈奴將兵往來擊邊，令王黃等說誤陳豨。","sentenceOrder":78},
  {"id":"s_work_han_thu_44_79","chapterId":"ch_work_han_thu_44","textTraditional":"〔一〕　師古曰：「上黨之縣也。鞮音丁奚反。」","sentenceOrder":79},
  {"id":"s_work_han_thu_44_80","chapterId":"ch_work_han_thu_44","textTraditional":"〔二〕　張晏曰：「白土，縣名也，屬上郡。」","sentenceOrder":80},
  {"id":"s_work_han_thu_44_81","chapterId":"ch_work_han_thu_44","textTraditional":"〔三〕　師古曰：「六國時趙後。」","sentenceOrder":81},
  {"id":"s_work_han_thu_44_82","chapterId":"ch_work_han_thu_44","textTraditional":"〔四〕　師古曰：「廣武亦太原之縣。」","sentenceOrder":82},
  {"id":"s_work_han_thu_44_83","chapterId":"ch_work_han_thu_44","textTraditional":"〔五〕　師古曰：「離石，西河之縣。」","sentenceOrder":83},
  {"id":"s_work_han_thu_44_84","chapterId":"ch_work_han_thu_44","textTraditional":"〔六〕　服虔曰：「臺名，去平城七里。」如淳曰：「平城旁之高地，若丘陵也。」師古曰：「在平城東山上，去平城十餘里，今其處猶存。服說非也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_44_85","chapterId":"ch_work_han_thu_44","textTraditional":"〔七〕　師古曰：「閼氏，匈奴單于之妻也。閼音於連反。氏音支。」","sentenceOrder":85},
  {"id":"s_work_han_thu_44_86","chapterId":"ch_work_han_thu_44","textTraditional":"〔八〕　李奇曰：「言唯弓矛無雜仗也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_44_87","chapterId":"ch_work_han_thu_44","textTraditional":"〔九〕　師古曰：「傅讀曰附。每一弩而加兩矢外鄉者，以禦敵也。鄉讀曰嚮。」","sentenceOrder":87},
  {"id":"s_work_han_thu_44_88","chapterId":"ch_work_han_thu_44","textTraditional":"十一年春，信復與胡騎入居參合。〔一〕漢使柴將軍擊之，〔二〕遺信書曰：「陛下寬仁，諸侯雖有叛亡，而後歸，輒復故位號，不誅也。〔三〕大王所知。今王以敗亡走胡，非有大罪，急自歸。」信報曰：「陛下擢僕閭巷，南面稱孤，此僕之幸也。滎陽之事，僕不能死，囚於項籍，此一罪也。寇攻馬邑，僕不能堅守，以城降之，此二罪也。今為反寇，將兵與將軍爭一旦之命，此三罪也。夫種、蠡無一罪，身死亡；〔四〕僕有三罪，而欲求活，此伍子胥所以僨於吳世也。〔五〕今僕亡匿山谷間，旦暮乞貣蠻夷，〔六〕僕之思歸，如痿人不忘起，盲者不忘視，〔七〕勢不可耳。」遂戰。柴將軍屠參合，斬信。","sentenceOrder":88},
  {"id":"s_work_han_thu_44_89","chapterId":"ch_work_han_thu_44","textTraditional":"〔一〕　師古曰：「代郡之縣。」","sentenceOrder":89},
  {"id":"s_work_han_thu_44_90","chapterId":"ch_work_han_thu_44","textTraditional":"〔二〕　鄧展曰：「柴奇也。」應劭曰：「柴武也。」晉灼曰：「奇，武之子。」師古曰：「應說是也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_44_91","chapterId":"ch_work_han_thu_44","textTraditional":"〔三〕　師古曰：「復音扶目反。」","sentenceOrder":91},
  {"id":"s_work_han_thu_44_92","chapterId":"ch_work_han_thu_44","textTraditional":"〔四〕　文穎曰：「大夫種、范蠡也。」師古曰：「二人皆越王句踐之臣也。大夫種位為大夫，名種也，有功於越，而句踐逼令自死。范蠡即陶朱公也，浮海而逃之齊，又居陶，自號朱公，竟以壽終。信引之以自喻者，蓋言種不去則見殺，蠡逃亡則獲免。蠡音禮。」","sentenceOrder":92},
  {"id":"s_work_han_thu_44_93","chapterId":"ch_work_han_thu_44","textTraditional":"〔五〕　蘇林曰：「僨音奮。」孟康曰：「僨猶斃也。言子胥得罪於夫差而不知去，所以斃於世也。」師古曰：「僨謂僵仆而倒也，音方問反。」","sentenceOrder":93},
  {"id":"s_work_han_thu_44_94","chapterId":"ch_work_han_thu_44","textTraditional":"〔六〕　師古曰：「貣音吐得反。」","sentenceOrder":94},
  {"id":"s_work_han_thu_44_95","chapterId":"ch_work_han_thu_44","textTraditional":"〔七〕　師古曰：「痿，風痹病也，音人佳反。」","sentenceOrder":95},
  {"id":"s_work_han_thu_44_96","chapterId":"ch_work_han_thu_44","textTraditional":"信之入匈奴，與太子俱，及至頹當城，生子，因名曰頹當。韓太子亦生子嬰。至孝文時，頹當及嬰率其眾降。漢封頹當為弓高侯〔一〕，嬰為襄城侯。〔二〕吳楚反時，弓高侯功冠諸將。傳子至孫，孫無子，國絕。嬰孫以不敬失侯。穨當孽孫嫣，〔三〕貴幸，名顯當世。嫣弟說，〔四〕以校尉擊匈奴，封龍頟侯。〔五〕後坐酎金失侯，復以待詔為橫海將軍，擊破東越，封按道侯。〔六〕太初中，為游擊將軍屯五原外列城，還為光祿勳，掘蠱太子宮，為太子所殺。〔七〕子興嗣，坐巫蠱誅。上曰：「游擊將軍死事，無論坐者。」〔八〕乃復封興弟增為龍頟侯。增少為郎，諸曹侍中光祿大夫，昭帝時至前將軍，與大將軍霍光定策立宣帝，益封千戶。本始二年，五將征匈奴，增將三萬騎出雲中，斬首百餘級，至期而還。神爵元年，代張安世為大司馬車騎將軍，領尚書事。增世貴，幼為忠臣，事三主，重於朝廷。為人寬和自守，以溫顏遜辭承上接下，無所失意，保身固寵，不能有所建明。五鳳二年薨，諡曰安侯。子寶嗣，亡子，國除。成帝時，繼功臣後，封增兄子岑為龍頟侯。薨，子持弓嗣。王莽敗，乃絕。","sentenceOrder":96},
  {"id":"s_work_han_thu_44_97","chapterId":"ch_work_han_thu_44","textTraditional":"〔一〕　晉灼曰：「功臣表屬營陵。」","sentenceOrder":97},
  {"id":"s_work_han_thu_44_98","chapterId":"ch_work_han_thu_44","textTraditional":"〔二〕　晉灼曰：「功臣表屬魏郡。」","sentenceOrder":98},
  {"id":"s_work_han_thu_44_99","chapterId":"ch_work_han_thu_44","textTraditional":"〔三〕　鄭氏曰：「音鄢陵之鄢。」師古曰：「鄭音是也，音偃。」","sentenceOrder":99},
  {"id":"s_work_han_thu_44_100","chapterId":"ch_work_han_thu_44","textTraditional":"〔四〕　師古曰：「說讀曰悅。」","sentenceOrder":100},
  {"id":"s_work_han_thu_44_101","chapterId":"ch_work_han_thu_44","textTraditional":"〔五〕　師古曰：「字或作雒。」","sentenceOrder":101},
  {"id":"s_work_han_thu_44_102","chapterId":"ch_work_han_thu_44","textTraditional":"〔六〕　師古曰：「史記年表并衛青傳載韓說初封龍雒侯，後為按道侯，皆與此傳同。而漢書功臣侯表乃云龍頟侯名譊，按道侯名說，列為二人，與此不同，疑表誤。」","sentenceOrder":102},
  {"id":"s_work_han_thu_44_103","chapterId":"ch_work_han_thu_44","textTraditional":"〔七〕　師古曰：「掘音其勿反。」","sentenceOrder":103},
  {"id":"s_work_han_thu_44_104","chapterId":"ch_work_han_thu_44","textTraditional":"〔八〕　服虔曰：「時無故見殺，而無為之論坐伏辜者也。」臣瓚曰：「按說無故見殺，而子復為巫蠱見誅，皆為怨枉，故上曰毋有應論坐者也。」師古曰：「二說皆非。言韓說以掘蠱為太子所殺，死於國事，忠誠可閔。今興雖以巫蠱見誅，其昆弟宗族應從坐者，可勿論之，所以追寵說也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_44_105","chapterId":"ch_work_han_thu_44","textTraditional":"贊曰：周室既壞，至春秋末，諸侯秏盡，〔一〕而炎黃唐虞之苗裔尚猶頗有存者。〔二〕秦滅六國，而上古遺烈埽地盡矣。〔三〕楚漢之際，豪桀相王，唯魏豹、韓信、田儋兄弟為舊國之後，然皆及身而絕。橫之志節，賓客慕義，猶不能自立，豈非天虖！韓氏自弓高後貴顯，蓋周烈近與！〔四〕","sentenceOrder":105},
  {"id":"s_work_han_thu_44_106","chapterId":"ch_work_han_thu_44","textTraditional":"〔一〕　師古曰：「秏，減也，言漸少而盡也，音呼到反。」","sentenceOrder":106},
  {"id":"s_work_han_thu_44_107","chapterId":"ch_work_han_thu_44","textTraditional":"〔二〕　師古曰：「謂神農、黃帝、堯、舜之後。」","sentenceOrder":107},
  {"id":"s_work_han_thu_44_108","chapterId":"ch_work_han_thu_44","textTraditional":"〔三〕　師古曰：「烈，業也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_44_109","chapterId":"ch_work_han_thu_44","textTraditional":"〔四〕　晉灼曰：「韓先與周同姓，其後苗裔事晉，封於韓原，姓韓氏，韓厥其後也，故曰周烈。」臣瓚曰：「案武王之子，方於三代，世為最近也。」師古曰：「左氏傳云『邘、晉、應、韓，武之穆也』。據如此贊所云，則韓萬先祖，武王之裔。而杜預等以為出自曲沃成師，未詳其說。與讀曰歟。」","sentenceOrder":109},
  {"id":"s_work_han_thu_44_110","chapterId":"ch_work_han_thu_44","textTraditional":"校勘記","sentenceOrder":110},
  {"id":"s_work_han_thu_44_111","chapterId":"ch_work_han_thu_44","textTraditional":"一八四五頁　二行　「王」字據殿本補。王先謙說有「王」字是。","sentenceOrder":111},
  {"id":"s_work_han_thu_44_112","chapterId":"ch_work_han_thu_44","textTraditional":"一八四六頁一一行　酈生（至）〔往〕，豹謝曰：　景祐、殿本都作「往」。","sentenceOrder":112},
  {"id":"s_work_han_thu_44_113","chapterId":"ch_work_han_thu_44","textTraditional":"一八五二頁　三行　（師古）〔應劭〕曰：　景祐、殿本都作「應劭」。王先謙說作「應劭」是。","sentenceOrder":113},
  {"id":"s_work_han_thu_44_114","chapterId":"ch_work_han_thu_44","textTraditional":"一八五二頁一０行　故立韓公子橫陽（城君）〔君成〕為韓王，　景祐、殿本都作「君成」。王先謙說作「君成」是，史記同。","sentenceOrder":114},
  {"id":"s_work_han_thu_44_115","chapterId":"ch_work_han_thu_44","textTraditional":"一八五四頁一０行　（與）其將白土人曼丘臣、　劉攽說「與」字不當有。王先謙亦說「與」字誤衍。","sentenceOrder":115},
  {"id":"s_work_han_thu_45_1","chapterId":"ch_work_han_thu_45","textTraditional":"韓信，淮陰人也。家貧無行，不得推擇為吏，〔一〕又不能治生為商賈，〔二〕常從人寄食。其母死無以葬，乃行營高燥地，令傍可置萬家者。〔三〕信從下鄉南昌亭長食，〔四〕亭長妻苦之，〔五〕乃晨炊蓐食。〔六〕食時信往，不為具食。信亦知其意，自絕去。至城下釣，有一漂母哀之，飯信，〔七〕竟漂數十日。信謂漂母曰：「吾必重報母。」母怒曰：「大丈夫不能自食，吾哀王孫而進食，〔八〕豈望報乎！」淮陰少年又侮信曰：「雖長大，好帶刀劍，怯耳。」眾辱信曰：「能死，刺我；不能，出跨下。」〔九〕於是信孰視，俛出跨下。〔一０〕一巿皆笑信，以為怯。","sentenceOrder":1},
  {"id":"s_work_han_thu_45_2","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　李奇曰：「無善行可推舉選擇也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_45_3","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「行賣曰商。坐販曰賈。」","sentenceOrder":3},
  {"id":"s_work_han_thu_45_4","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「言其有大志也。行音下更反。燥音先老反。」","sentenceOrder":4},
  {"id":"s_work_han_thu_45_5","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　張晏曰：「下鄉，屬淮陰。」","sentenceOrder":5},
  {"id":"s_work_han_thu_45_6","chapterId":"ch_work_han_thu_45","textTraditional":"〔五〕　師古曰：「苦，厭也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_45_7","chapterId":"ch_work_han_thu_45","textTraditional":"〔六〕　張晏曰：「未起而床蓐中食。」","sentenceOrder":7},
  {"id":"s_work_han_thu_45_8","chapterId":"ch_work_han_thu_45","textTraditional":"〔七〕　韋昭曰：「以水擊絮曰漂。」師古曰：「哀憐而飯之。漂音匹妙反。飯音扶晚反。」","sentenceOrder":8},
  {"id":"s_work_han_thu_45_9","chapterId":"ch_work_han_thu_45","textTraditional":"〔八〕　蘇林曰：「王孫，如言公子也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_45_10","chapterId":"ch_work_han_thu_45","textTraditional":"〔九〕　師古曰：「眾辱，於眾中辱之。跨下，兩股之間也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_45_11","chapterId":"ch_work_han_thu_45","textTraditional":"〔一０〕師古曰：「俛亦俯字。」","sentenceOrder":11},
  {"id":"s_work_han_thu_45_12","chapterId":"ch_work_han_thu_45","textTraditional":"及項梁度淮，信乃杖劍從之，〔一〕居戲下，無所知名。〔二〕梁敗，又屬項羽，為郎中。信數以策干項羽，羽弗用。漢王之入蜀，信亡楚歸漢，未得知名，為連敖。〔三〕坐法當斬，其疇十三人皆已斬，〔四〕至信，信乃仰視，適見滕公，〔五〕曰：「上不欲就天（子）〔下〕乎？而斬壯士！」滕公奇其言，壯其貌，釋弗斬。〔六〕與語，大說之，言於漢王。漢王以為治粟都尉，上未奇之也。","sentenceOrder":12},
  {"id":"s_work_han_thu_45_13","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「言直帶一劍，更無餘資。」","sentenceOrder":13},
  {"id":"s_work_han_thu_45_14","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「汎在旌戲之下也。戲讀曰麾，又音許宜反。」","sentenceOrder":14},
  {"id":"s_work_han_thu_45_15","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　李奇曰：「楚官名。」","sentenceOrder":15},
  {"id":"s_work_han_thu_45_16","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　師古曰：「疇，類名。」","sentenceOrder":16},
  {"id":"s_work_han_thu_45_17","chapterId":"ch_work_han_thu_45","textTraditional":"〔五〕　師古曰：「夏侯嬰。」","sentenceOrder":17},
  {"id":"s_work_han_thu_45_18","chapterId":"ch_work_han_thu_45","textTraditional":"〔六〕　師古曰：「釋，放也，置也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_45_19","chapterId":"ch_work_han_thu_45","textTraditional":"數與蕭何語，何奇之。至南鄭，諸將道亡者數十人。信度何等已數言上，〔一〕不我用，即亡。何聞信亡，不及以聞，自追之。人有言上曰：「丞相何亡。」上怒，如失左右手。居一二日，何來謁。上且怒且喜，罵何曰：「若亡，何也？」〔二〕何曰：「臣非敢亡，追亡者耳。」上曰：「所追者誰也？」曰：「韓信。」上復罵曰：「諸將亡者已數十，公無所追；追信，詐也。」何曰：「諸將易得，至如信，國士無雙。〔三〕王必欲長王漢中，無所事信；〔四〕必欲爭天下，非信無可與計事者。顧王策安決。」〔五〕王曰：「吾亦欲東耳，安能鬱鬱久居此乎？」何曰：「王計必東，能用信，信即留；不能用信，信終亡耳。」王曰：「吾為公以為將。」何曰：「雖為將，信不留。」王曰：「以為大將。」何曰：「幸甚。」於是王欲召信拜之。何曰：「王素嫚無禮，〔六〕今拜大將如召小兒，此乃信所以去也。〔王〕必欲拜之，擇日齋戒，設壇場具禮，乃可。」王許之。諸將皆喜，人人各自以為得大將。至拜，乃韓信也，一軍皆驚。","sentenceOrder":19},
  {"id":"s_work_han_thu_45_20","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「度，計量也，音大各反。」","sentenceOrder":20},
  {"id":"s_work_han_thu_45_21","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「若，汝也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_45_22","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「為國家之奇士。」","sentenceOrder":22},
  {"id":"s_work_han_thu_45_23","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　張晏曰：「無事用信。」","sentenceOrder":23},
  {"id":"s_work_han_thu_45_24","chapterId":"ch_work_han_thu_45","textTraditional":"〔五〕　師古曰：「顧，思念也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_45_25","chapterId":"ch_work_han_thu_45","textTraditional":"〔六〕　師古曰：「嫚與慢同。」","sentenceOrder":25},
  {"id":"s_work_han_thu_45_26","chapterId":"ch_work_han_thu_45","textTraditional":"信（以）〔已〕拜，上坐。王曰：「丞相數言將軍，將軍何以教寡人計策？」信謝，因問王曰：「今東鄉爭權天下，豈非項王邪？」〔一〕上曰：「然。」信曰：「大王自料勇悍仁彊孰與項王？」〔二〕漢王默然良久，曰：「弗如也。」信再拜賀曰：「唯〔三〕信亦以為大王弗如也。然臣嘗事項王，請言項王為人也。項王意烏猝嗟，千人皆廢，〔四〕然不能任屬賢將，〔五〕此特匹夫之勇也。〔六〕項王見人恭謹，言語姁姁，〔七〕人有病疾，涕泣分食飲，至使人有功，當封爵，刻印刓，忍不能予，〔八〕此所謂婦人之仁也。項王雖霸天下而臣諸侯，不居關中而都彭城；又背義帝約，而以親愛王，諸侯不平。諸侯之見項王逐義帝江南，亦皆歸逐其主，自王善地。項王所過亡不殘滅，多怨百姓，〔九〕百姓不附，特劫於威，彊服耳。〔一０〕名雖為霸，實失天下心，〔一一〕故曰其彊易弱。〔一二〕今大王誠能反其道，任天下武勇，何不誅！〔一三〕以天下城邑封功臣，何不服！以義兵從思東歸之士，何不散！〔一四〕且三秦王為秦將，〔一五〕將秦子弟數歲，而所殺亡不可勝計，又欺其眾降諸侯。至新安，項王詐阬秦降卒二十餘萬人，唯獨邯、欣、翳脫。〔一六〕秦父兄怨此三人，痛於骨髓。今楚強以威王此三人，秦民莫愛也。大王之入武關，秋豪亡所害，〔一七〕除秦苛法，與民約，法三章耳，秦民亡不欲得大王王秦者。於諸侯之約，大王當王關中，關中民戶知之。〔一八〕王失職之蜀，民亡不恨者。〔一九〕今王舉而東，三秦可傳檄而定也。」〔二０〕於是漢王大喜，自以為得信晚。遂聽信計，部署諸將所擊。〔二一〕","sentenceOrder":26},
  {"id":"s_work_han_thu_45_27","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":27},
  {"id":"s_work_han_thu_45_28","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「料，量也。與，如也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_45_29","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「唯，應辭，音弋癸反。」","sentenceOrder":29},
  {"id":"s_work_han_thu_45_30","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　李奇曰：「猝嗟猶咄嗟也。言羽一咄嗟，千人皆失氣也。」晉灼曰：「意烏，恚怒聲也。猝嗟，形發動也。廢，不收也。」師古曰：「意烏，晉說是也。猝嗟，暴猝嗟歎也。猝音千忽反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_45_31","chapterId":"ch_work_han_thu_45","textTraditional":"〔五〕　師古曰：「屬，委也，音之欲反。」","sentenceOrder":31},
  {"id":"s_work_han_thu_45_32","chapterId":"ch_work_han_thu_45","textTraditional":"〔六〕　師古曰：「特，但也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_45_33","chapterId":"ch_work_han_thu_45","textTraditional":"〔七〕　師古曰：「姁姁，和好貌也，音許于反。」","sentenceOrder":33},
  {"id":"s_work_han_thu_45_34","chapterId":"ch_work_han_thu_45","textTraditional":"〔八〕　蘇林曰：「刓音刓角之刓，刓與摶同。手弄角訛，不忍授也。」師古曰：「刓音五丸反。摶音大官反。又音專。」","sentenceOrder":34},
  {"id":"s_work_han_thu_45_35","chapterId":"ch_work_han_thu_45","textTraditional":"〔九〕　師古曰：「結怨於百姓。」","sentenceOrder":35},
  {"id":"s_work_han_thu_45_36","chapterId":"ch_work_han_thu_45","textTraditional":"〔一０〕師古曰：「彊音其兩反。其下『強以威王』亦同。」","sentenceOrder":36},
  {"id":"s_work_han_thu_45_37","chapterId":"ch_work_han_thu_45","textTraditional":"〔一一〕師古曰：「羽自號西楚霸王，故云名為霸也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_45_38","chapterId":"ch_work_han_thu_45","textTraditional":"〔一二〕師古曰：「易使弱也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_45_39","chapterId":"ch_work_han_thu_45","textTraditional":"〔一三〕師古曰：「言何所不誅也。下皆類此。」","sentenceOrder":39},
  {"id":"s_work_han_thu_45_40","chapterId":"ch_work_han_thu_45","textTraditional":"〔一四〕師古曰：「散謂四散而立功。」","sentenceOrder":40},
  {"id":"s_work_han_thu_45_41","chapterId":"ch_work_han_thu_45","textTraditional":"〔一五〕師古曰：「章邯、司馬欣、董翳。」","sentenceOrder":41},
  {"id":"s_work_han_thu_45_42","chapterId":"ch_work_han_thu_45","textTraditional":"〔一六〕師古曰：「脫，免也，音土活反。」","sentenceOrder":42},
  {"id":"s_work_han_thu_45_43","chapterId":"ch_work_han_thu_45","textTraditional":"〔一七〕師古曰：「秋豪，喻細微之物。」","sentenceOrder":43},
  {"id":"s_work_han_thu_45_44","chapterId":"ch_work_han_thu_45","textTraditional":"〔一八〕師古曰；「言家家皆知。」","sentenceOrder":44},
  {"id":"s_work_han_thu_45_45","chapterId":"ch_work_han_thu_45","textTraditional":"〔一九〕師古曰：「之，往也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_45_46","chapterId":"ch_work_han_thu_45","textTraditional":"〔二０〕師古曰：「檄謂檄書也。傳檄可定，言不足用兵也。檄，解在高紀。」","sentenceOrder":46},
  {"id":"s_work_han_thu_45_47","chapterId":"ch_work_han_thu_45","textTraditional":"〔二一〕師古曰：「部分而署置之。」","sentenceOrder":47},
  {"id":"s_work_han_thu_45_48","chapterId":"ch_work_han_thu_45","textTraditional":"漢王舉兵東出陳倉，定三秦。二年，出關，收魏、河南，韓、殷王皆降。令齊、趙共擊楚彭城，漢兵敗散而還。信復發兵與漢王會滎陽，復擊破楚京、索間，〔一〕以故楚兵不能西。","sentenceOrder":48},
  {"id":"s_work_han_thu_45_49","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「索音山客反。」","sentenceOrder":49},
  {"id":"s_work_han_thu_45_50","chapterId":"ch_work_han_thu_45","textTraditional":"漢之敗卻彭城，〔一〕塞王欣、翟王翳亡漢降楚，齊、趙、魏亦皆反，與楚和。漢王使酈生往說魏王豹，豹不聽，乃以信為左丞相擊魏。信問酈生：「魏得毋用周叔為大將乎？」曰：「栢直也。」信曰：「豎子耳。」遂進兵擊魏。魏盛兵蒲阪，塞臨晉。信乃益為疑兵，〔二〕陳船欲度臨晉，而伏兵從夏陽以木罌缶度軍，襲安邑。〔三〕魏王豹驚，引兵迎信。信遂虜豹，定河東，使人請漢王：「願益兵三萬人，臣請以北舉燕、趙，東擊齊，南絕楚之糧道，西與大王會於滎陽。」漢王與兵三萬人，遣張耳與俱，進擊趙、代。破代，禽夏說閼與。〔四〕信之下魏、代，漢輒使人收其精兵，詣滎陽以距楚。","sentenceOrder":50},
  {"id":"s_work_han_thu_45_51","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「兵敗於彭城而卻退也。卻音丘略反。」","sentenceOrder":51},
  {"id":"s_work_han_thu_45_52","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「多張兵形，令敵人疑也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_45_53","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　服虔曰：「以木柙縳罌缶以度也。」韋昭曰：「以木為器，如罌缶也。」師古曰：「服說是也。罌缶謂瓶之大腹小口者也，音一政反。臨晉在今同州朝邑縣界。夏陽在韓城縣界。」","sentenceOrder":53},
  {"id":"s_work_han_thu_45_54","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　李奇曰：「夏說，代相也。」孟康曰：「閼與是邑名也，在上黨隰縣。」師古曰：「說讀曰悅。閼音一曷反。與音豫。」","sentenceOrder":54},
  {"id":"s_work_han_thu_45_55","chapterId":"ch_work_han_thu_45","textTraditional":"信、耳以兵數萬，欲東下井陘擊趙。趙王、成安君陳餘聞漢且襲之，聚兵井陘口，號稱二十萬。廣武君李左車說成安君曰：「聞漢將韓信涉西河，虜魏王，禽夏說，新喋血閼與。〔一〕今乃輔以張耳，議欲以下趙，〔二〕此乘勝而去國遠鬥，其鋒不可當。臣聞『千里餽糧，士有飢色；〔三〕樵蘇後爨，師不宿飽。』〔四〕今井陘之道，車不得方軌，騎不得成列，〔五〕行數百里，其勢糧食必在後。願足下假臣奇兵三萬人，從間（道）〔路〕絕其輜重；〔六〕足下深溝高壘勿與戰。彼前不得鬥，退不得還，吾奇兵絕其後，野無所掠鹵，不至十日，兩將之頭可致戲下。〔七〕願君留意臣之計，必不為二子所禽矣。」成安君，儒者，常稱義兵不用詐謀奇計，謂曰：「吾聞兵法『什則圍之，倍則戰。』〔八〕今韓信兵號數萬，其實不能，千里襲我，亦以罷矣。〔九〕今如此避弗擊，後有大者，何以距之？諸侯謂吾怯，而輕來伐我。」不聽廣武君策。","sentenceOrder":55},
  {"id":"s_work_han_thu_45_56","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「喋音牒。喋血，解在文紀。」","sentenceOrder":56},
  {"id":"s_work_han_thu_45_57","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「言其立計議如此。」","sentenceOrder":57},
  {"id":"s_work_han_thu_45_58","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「言難繼也。餽字與饋同。」","sentenceOrder":58},
  {"id":"s_work_han_thu_45_59","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　師古曰：「樵，取薪也。蘇，取草也。小雅白華之詩曰『樵彼桑薪』。樵音在消反。」","sentenceOrder":59},
  {"id":"s_work_han_thu_45_60","chapterId":"ch_work_han_thu_45","textTraditional":"〔五〕　師古曰：「方軌，謂併行也。列，行列。」","sentenceOrder":60},
  {"id":"s_work_han_thu_45_61","chapterId":"ch_work_han_thu_45","textTraditional":"〔六〕　師古曰：「間路，微路也。重音直用反。」","sentenceOrder":61},
  {"id":"s_work_han_thu_45_62","chapterId":"ch_work_han_thu_45","textTraditional":"〔七〕　師古曰：「戲讀曰麾，又音許宜反。」","sentenceOrder":62},
  {"id":"s_work_han_thu_45_63","chapterId":"ch_work_han_thu_45","textTraditional":"〔八〕　師古曰：「言多十倍者可以圍城，多一倍者戰則可勝。」","sentenceOrder":63},
  {"id":"s_work_han_thu_45_64","chapterId":"ch_work_han_thu_45","textTraditional":"〔九〕　師古曰：「罷讀曰疲。」","sentenceOrder":64},
  {"id":"s_work_han_thu_45_65","chapterId":"ch_work_han_thu_45","textTraditional":"信使間人窺知其不用，〔一〕還報，則大喜，乃敢引兵遂下。未至井陘口三十里，止舍。〔二〕夜半傳發，選輕騎二千人，〔三〕人持一赤幟，〔四〕從間道萆山而望趙軍，〔五〕戒曰：「趙見我走，必空壁逐我，若疾入，拔趙幟，立漢幟。」〔六〕令其裨將傳餐〔七〕，曰：「今日破趙會食。」諸將皆嘸然，陽應曰：「諾。」〔八〕信謂軍吏曰：「趙已先據便地壁，且彼未見大將旗鼓，未肯擊前行，〔九〕恐吾阻險而還。」乃使萬人先行，出，背水陳。趙兵望見大笑。平旦，信建大將旗鼓，鼓行出井陘口，〔一０〕趙開壁擊之，大戰良久。於是信、張耳棄鼓旗，走水上軍，〔一一〕復疾戰。趙空壁爭漢鼓旗，逐信、耳。信、耳已入水上軍，軍皆殊死戰，不可敗。〔一二〕信所出奇兵二千騎者，候趙空壁逐利，即馳入趙壁，皆拔趙旗幟，立漢赤幟二千。趙軍已不能得信、耳等，欲還歸壁，壁皆漢赤幟，大驚，以漢為皆已破趙王將矣，遂亂，遁走。趙將雖斬之，弗能禁。於是漢兵夾擊，破虜趙軍，斬成安君泜水上，〔一三〕禽趙王歇。","sentenceOrder":65},
  {"id":"s_work_han_thu_45_66","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「間人，微伺之也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_45_67","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「舍，息也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_45_68","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　孟康曰：「傳，令軍中使發也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_45_69","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　師古曰：「幟，旌旗之屬也，音式志反。」","sentenceOrder":69},
  {"id":"s_work_han_thu_45_70","chapterId":"ch_work_han_thu_45","textTraditional":"〔五〕　如淳曰：「萆音蔽，依山自覆蔽也。」師古曰：「蔽隱於山間使敵不見。」","sentenceOrder":70},
  {"id":"s_work_han_thu_45_71","chapterId":"ch_work_han_thu_45","textTraditional":"〔六〕　師古曰：「若，汝也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_45_72","chapterId":"ch_work_han_thu_45","textTraditional":"〔七〕　服虔曰：「立（騎）〔駐〕傳餐食也。」如淳曰：「小飯曰餐，破趙後乃當共飽食也。」師古曰：「餐，古飡字，音千安反。」","sentenceOrder":72},
  {"id":"s_work_han_thu_45_73","chapterId":"ch_work_han_thu_45","textTraditional":"〔八〕　孟康曰：「嘸音撫，不精明也。」劉德曰：「音憮。」師古曰：「劉音是也。音文府反。」","sentenceOrder":73},
  {"id":"s_work_han_thu_45_74","chapterId":"ch_work_han_thu_45","textTraditional":"〔九〕　師古曰：「行音胡郎反。」","sentenceOrder":74},
  {"id":"s_work_han_thu_45_75","chapterId":"ch_work_han_thu_45","textTraditional":"〔一０〕師古曰：「聲鼓而行。」","sentenceOrder":75},
  {"id":"s_work_han_thu_45_76","chapterId":"ch_work_han_thu_45","textTraditional":"〔一一〕師古曰：「走，趣也，音奏。」","sentenceOrder":76},
  {"id":"s_work_han_thu_45_77","chapterId":"ch_work_han_thu_45","textTraditional":"〔一二〕師古曰：「殊，絕也。謂決意必死。」","sentenceOrder":77},
  {"id":"s_work_han_thu_45_78","chapterId":"ch_work_han_thu_45","textTraditional":"〔一三〕師古曰：「泜音祗，又音丁計反。」","sentenceOrder":78},
  {"id":"s_work_han_thu_45_79","chapterId":"ch_work_han_thu_45","textTraditional":"信乃令軍毋斬廣武君，有生得之者，購千金。頃之，有縛而至戲下者，信解其縛，東鄉坐，西鄉對，而師事之。〔一〕","sentenceOrder":79},
  {"id":"s_work_han_thu_45_80","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「鄉皆讀曰嚮。」","sentenceOrder":80},
  {"id":"s_work_han_thu_45_81","chapterId":"ch_work_han_thu_45","textTraditional":"諸校（劾）〔效〕首虜休，皆賀，〔一〕因問信曰：「兵法有『右背山陵，前左水澤』，今者將軍令臣等反背水陳，曰破趙會食，臣等不服。然竟以勝，此何術也？」信曰：「此在兵法，顧諸君弗察耳。〔二〕兵法不曰『陷之死地而後生，投之亡地而後存』乎？且信非得素拊循士大夫，經所謂『敺市人而戰之』也，〔三〕其勢非置死地，人人自為戰；今即予生地，皆走，寧尚得而用之乎！」諸將皆服曰：「非所及也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_45_82","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「諸校，諸部也，猶今言諸營也。（劾）〔效〕，致也。謂各致其所獲。」","sentenceOrder":82},
  {"id":"s_work_han_thu_45_83","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「顧，念也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_45_84","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「經亦謂兵法也。敺與驅同也。忽入市鄽而敺取其人令戰，言非素所練習。」","sentenceOrder":84},
  {"id":"s_work_han_thu_45_85","chapterId":"ch_work_han_thu_45","textTraditional":"於是問廣武君曰：「僕欲北攻燕，東伐齊，何若有功？」〔一〕廣武君辭曰：「臣聞『亡國之大夫不可以圖存，〔二〕敗軍之將不可以語勇。』若臣者，何足以權大事乎！」信曰：「僕聞之，百里奚居虞而虞亡，之秦而秦伯，〔三〕非愚於虞而智於秦也，用與不用，聽與不聽耳。向使成安君聽子計，僕亦禽矣。僕委心歸計，願子勿辭。」廣武君曰：「臣聞『智者千慮，必有一失；愚者千慮，亦有一得。』故曰『狂夫之言，聖人擇焉。』（故）〔顧〕恐臣計未足用，〔四〕願效愚忠。故成安君有百戰百勝之計，一日而失之，軍敗鄗下〔五〕，身死泜水上。今足下虜魏王，禽夏說，不旬朝破趙二十萬眾，誅成安君。名聞海內，威震諸侯，眾庶莫不輟作怠惰，靡衣媮食，傾耳以待（禽）〔命〕者。〔六〕然而眾勞卒罷，〔七〕其實難用也。今足下舉倦敝之兵，頓之燕堅城之下，情見力屈，〔八〕欲戰不拔，曠日持久，糧食單竭。〔九〕若燕不破，齊必距境而以自彊。二國相持，則劉項之權未有所分也。臣愚，竊以為亦過矣。」信曰：「然則何由？」〔一０〕廣武君對曰：「當今之計，不如按甲休兵，百里之內，牛酒日至，以饗士大夫，北首燕路，〔一一〕然後發一乘之使，奉咫尺之書，〔一二〕以使燕，燕必不敢不聽。從燕而東臨齊，雖有智者，亦不知為齊計矣。如是，則天下事可圖也。兵故有先聲而後實者，此之謂也。」信曰：「善。敬奉教。」於是用廣武君策，發使燕，燕從風而靡。乃遣使報漢，因請立張耳王趙以撫其國。漢王許之。","sentenceOrder":85},
  {"id":"s_work_han_thu_45_86","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「何若，猶言何如也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_45_87","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「圖，謀也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_45_88","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「百里奚，本虞臣也。後事於秦，遂為大夫，穆公用其言，以取霸。伯讀曰霸。」","sentenceOrder":88},
  {"id":"s_work_han_thu_45_89","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　師古曰：「顧，念也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_45_90","chapterId":"ch_work_han_thu_45","textTraditional":"〔五〕　李奇曰：「鄗音羹臛之臛，常山縣也。光武即位於此，故改曰高邑。」","sentenceOrder":90},
  {"id":"s_work_han_thu_45_91","chapterId":"ch_work_han_thu_45","textTraditional":"〔六〕　師古曰：「輟，止也。靡，輕麗也。媮與偷字同。偷，苟且也。言為靡麗之衣，苟且而食，恐懼之甚，不為久計也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_45_92","chapterId":"ch_work_han_thu_45","textTraditional":"〔七〕　師古曰：「罷讀曰疲。」","sentenceOrder":92},
  {"id":"s_work_han_thu_45_93","chapterId":"ch_work_han_thu_45","textTraditional":"〔八〕　師古曰：「見，顯露也。屈，盡也。見音胡電反。屈音其勿反。」","sentenceOrder":93},
  {"id":"s_work_han_thu_45_94","chapterId":"ch_work_han_thu_45","textTraditional":"〔九〕　師古曰：「單亦盡。」","sentenceOrder":94},
  {"id":"s_work_han_thu_45_95","chapterId":"ch_work_han_thu_45","textTraditional":"〔一０〕師古曰：「由，從也，言當從何計也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_45_96","chapterId":"ch_work_han_thu_45","textTraditional":"〔一一〕師古曰：「首謂趣向也，音式究反。」","sentenceOrder":96},
  {"id":"s_work_han_thu_45_97","chapterId":"ch_work_han_thu_45","textTraditional":"〔一二〕師古曰：「八寸曰咫。咫尺者，言其簡牘或長咫，或長尺，喻輕率也。今俗言尺書，或言尺牘，蓋其遺語耳。」","sentenceOrder":97},
  {"id":"s_work_han_thu_45_98","chapterId":"ch_work_han_thu_45","textTraditional":"楚數使奇兵度河擊趙，王耳、信往來救趙，因行定趙城邑，發卒佐漢。楚方急圍漢王滎陽，漢王出，南之宛、葉，〔一〕得九江王布，入成皋，楚復急圍之。四年，漢王出成皋，度河，獨與滕公從張耳軍修武。至，宿傳舍。晨自稱漢使，馳入壁。張耳、韓信未起，即其臥，奪其印符，〔二〕麾召諸將易置之。信、耳起，乃知獨漢王來，大驚。漢王奪兩人軍，即令張耳備守趙地，拜信為相國，發趙兵未發者擊齊。〔三〕","sentenceOrder":98},
  {"id":"s_work_han_thu_45_99","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「之，往也。宛、葉，二縣名。宛音於元反。葉音式涉反。」","sentenceOrder":99},
  {"id":"s_work_han_thu_45_100","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「就其臥處。」","sentenceOrder":100},
  {"id":"s_work_han_thu_45_101","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　文穎曰：「謂趙人未嘗見發者。」","sentenceOrder":101},
  {"id":"s_work_han_thu_45_102","chapterId":"ch_work_han_thu_45","textTraditional":"信引兵東，未度平原，聞漢王使酈食其已說下齊。信欲止，蒯通說信令擊齊。語在通傳。信然其計，遂渡河，襲歷下軍，至臨菑。齊王走高密，使使於楚請救。信已定臨菑，東追至高密西。楚使龍且將，號稱二十萬，〔一〕救齊。","sentenceOrder":102},
  {"id":"s_work_han_thu_45_103","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「且音子余反。」","sentenceOrder":103},
  {"id":"s_work_han_thu_45_104","chapterId":"ch_work_han_thu_45","textTraditional":"齊王、龍且并軍與信戰，未合。〔一〕或說龍且曰：「漢兵遠鬥，窮寇〔久〕戰，鋒不可當也。齊、楚自居其地戰，兵易敗散。〔二〕不如深壁，令齊王使其信臣招所亡城，〔三〕城聞王在，楚來救，必反漢。漢二千里客居齊，齊城皆反之，其勢無所得食，可毋戰而降也。」龍且曰：「吾平生知韓信為人，易與耳。寄食於漂母，無資身之策；受辱於跨下，無兼人之勇，不足畏也。且救齊而降之，吾何功？今戰而勝之，齊半可得，〔四〕何為而止！」遂戰，與信夾濰水陳。〔五〕信乃夜令人為萬餘囊，〔盛〕沙以壅水上流，引兵半度，擊龍且。陽不勝，還走。龍且果喜曰：「固知信怯。」遂追度水。信使人決壅囊，水大至。龍且軍太半不得度，即急擊，殺龍且。龍且水東軍散走，齊王廣亡去。信追北至城陽，虜廣。楚卒皆降，遂平齊。","sentenceOrder":104},
  {"id":"s_work_han_thu_45_105","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「欲戰而未交兵也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_45_106","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「近其室家，懷顧望也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_45_107","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「信臣，常所親信之臣。」","sentenceOrder":107},
  {"id":"s_work_han_thu_45_108","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　師古曰：「自謂當得封齊之半地。」","sentenceOrder":108},
  {"id":"s_work_han_thu_45_109","chapterId":"ch_work_han_thu_45","textTraditional":"〔五〕　師古曰：「濰音維。濰水出琅邪北箕縣，東北經臺昌入海，即禹貢所云『濰淄其道』者也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_45_110","chapterId":"ch_work_han_thu_45","textTraditional":"使人言漢王曰：「齊夸詐多變，反覆之國，南邊（荒）〔楚〕，〔一〕不為假王以填之，其勢不定。〔二〕今權輕，不足以安之，臣請自立為假王。」當是時，楚方急圍漢王於滎陽，使者至，發書〔三〕，漢王大怒，罵曰：「吾困於此，旦暮望而來佐我，〔四〕乃欲自立為王！」張良、陳平伏後躡漢王足，因附耳語曰：「漢方不利，寧能禁信之自王乎？不如因立，善遇之，使自為守。不然，變生。」漢王亦寤，因復罵曰：「大丈夫定諸侯，即為真王耳，何以假為！」遣張良立信為齊王，徵其兵使擊楚。","sentenceOrder":110},
  {"id":"s_work_han_thu_45_111","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「邊，近也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_45_112","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「填音竹刃反。」","sentenceOrder":112},
  {"id":"s_work_han_thu_45_113","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　張晏曰：「發信使者所齎書也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_45_114","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　師古曰：「而，汝也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_45_115","chapterId":"ch_work_han_thu_45","textTraditional":"楚以亡龍且，項王恐，使盱台人武涉往說信曰：「足下何不反漢與楚？楚王與足下有舊故。且漢王不可必，〔一〕身居項王掌握中數矣，〔二〕然得脫，背約，復擊項王，其不可親信如此。今足下雖自以為與漢王為金石交，〔三〕然終為漢王所禽矣。足下所以得須臾至今者，以項王在。項王即亡，次取足下。何不與楚連和，三分天下而王齊？今釋此時，自必於漢王以擊楚，且為智者固若此邪！」信謝曰：「臣得事項王數年，官不過郎中，位不過執戟，〔四〕言不聽，畫策不用，故背楚歸漢。漢王授我上將軍印，數萬之眾，解衣衣我，推食食我，〔五〕言聽計用，吾得至於此。夫人深親信我，背之不祥。幸為信謝項王。」武涉已去，蒯通知天下權在於信，深說以三分天下，（之計）〔鼎足而王〕。語在通傳。信不忍背漢，又自以功大，漢王不奪我齊，遂不聽。","sentenceOrder":115},
  {"id":"s_work_han_thu_45_116","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「必謂必信之。」","sentenceOrder":116},
  {"id":"s_work_han_thu_45_117","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「數音山角反。」","sentenceOrder":117},
  {"id":"s_work_han_thu_45_118","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「稱金石者，取其堅固。」","sentenceOrder":118},
  {"id":"s_work_han_thu_45_119","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　張晏曰：「郎中宿衛執戟。」","sentenceOrder":119},
  {"id":"s_work_han_thu_45_120","chapterId":"ch_work_han_thu_45","textTraditional":"〔五〕　師古曰：「下衣音於記反。下食讀曰飤也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_45_121","chapterId":"ch_work_han_thu_45","textTraditional":"漢王之敗固陵，用張良計，徵信將兵會陔下。項羽死，高祖襲奪信軍，徙信為楚王，都下邳。","sentenceOrder":121},
  {"id":"s_work_han_thu_45_122","chapterId":"ch_work_han_thu_45","textTraditional":"信至國，召所從食漂母，賜千金。及下鄉亭長，錢百，〔一〕曰：「公，小人，為德不竟。」〔二〕召辱己少年令出跨下者，以為中尉，告諸將相曰：「此壯士也。方辱我時，寧不能死？死之無名，故忍而就此。」〔三〕","sentenceOrder":122},
  {"id":"s_work_han_thu_45_123","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「以恥辱之。」","sentenceOrder":123},
  {"id":"s_work_han_thu_45_124","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「言晨炊蓐食。」","sentenceOrder":124},
  {"id":"s_work_han_thu_45_125","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「就，成也。成今日之功。」","sentenceOrder":125},
  {"id":"s_work_han_thu_45_126","chapterId":"ch_work_han_thu_45","textTraditional":"項王亡將鍾離眜〔一〕家在伊廬，〔二〕素與信善。項王敗，眜亡歸信。漢怨眜，聞在楚，詔楚捕之。信初之國，行縣邑，陳兵出入。〔三〕有變告信欲反，〔四〕書聞，〔五〕上患之。用陳平謀，偽游於雲夢者，實欲襲信，信弗知。高祖且至楚，信欲發兵，自度無罪；〔六〕欲謁上，恐見禽。人或說信曰：「斬眜謁上，上必喜，亡患。」信見眜計事，眜曰：「漢所以不擊取楚，以眜在。公若欲捕我自媚漢，吾今死，公隨手亡矣。」乃罵信曰：「公非長者！」卒自剄。信持其首謁於陳。高祖令武士縛信，載後車。信曰：「果若人言，『狡兔死，良狗亨。』」〔七〕上曰：「人告公反。」遂械信。至雒陽，赦以為淮陰侯。","sentenceOrder":126},
  {"id":"s_work_han_thu_45_127","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「眜音莫曷反。」","sentenceOrder":127},
  {"id":"s_work_han_thu_45_128","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　劉德曰：「東海朐南有此邑。」韋昭曰：「今中廬縣也。」師古曰：「韋說非也。中廬在襄陽之南。」","sentenceOrder":128},
  {"id":"s_work_han_thu_45_129","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「行音下更反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_45_130","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　師古曰：「凡言變告者，謂告非常之事。」","sentenceOrder":130},
  {"id":"s_work_han_thu_45_131","chapterId":"ch_work_han_thu_45","textTraditional":"〔五〕　師古曰：「聞於天子。」","sentenceOrder":131},
  {"id":"s_work_han_thu_45_132","chapterId":"ch_work_han_thu_45","textTraditional":"〔六〕　師古曰：「度音大各反。」","sentenceOrder":132},
  {"id":"s_work_han_thu_45_133","chapterId":"ch_work_han_thu_45","textTraditional":"〔七〕　張晏曰：「狡猶猾也。」師古曰：「此黃石公三略之言。」","sentenceOrder":133},
  {"id":"s_work_han_thu_45_134","chapterId":"ch_work_han_thu_45","textTraditional":"信知漢王畏惡其能，稱疾不朝從。〔一〕由此日怨望，居常鞅鞅，〔二〕羞與絳、灌等列。嘗過樊將軍噲，噲趨拜送迎，言稱臣，曰：「大王乃肯臨臣。」信出門，笑曰：「生乃與噲等為伍！」〔三〕","sentenceOrder":134},
  {"id":"s_work_han_thu_45_135","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「朝，朝見也。從，從行也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_45_136","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「鞅鞅，志不滿也，音於兩反。」","sentenceOrder":136},
  {"id":"s_work_han_thu_45_137","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「言俱為列侯。」","sentenceOrder":137},
  {"id":"s_work_han_thu_45_138","chapterId":"ch_work_han_thu_45","textTraditional":"上嘗從容與信言諸將〔一〕能各有差。上問曰：「如我，能將幾何？」信曰：「陛下不過能將十萬。」上曰：「如公何如？」曰：「如臣，多多益辦耳。」上笑曰：「多多益辦，何為為我禽？」信曰：「陛下不能將兵，而善將將，此乃信之為陛下禽也。且陛下所謂天授，非人力也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_45_139","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「從音千容反。」","sentenceOrder":139},
  {"id":"s_work_han_thu_45_140","chapterId":"ch_work_han_thu_45","textTraditional":"後陳豨為代相監邊，辭信，信挈其手，〔一〕與步於庭數匝，仰天而嘆曰：「子可與言乎？吾欲與子有言。」豨因曰：「唯將軍命。」信曰：「公之所居，天下精兵處也，而公，陛下之信幸臣也。人言公反，陛下必不信；再至，陛下乃疑；三至，必怒而自將。吾為公從中起，天下可圖也。」陳豨素知其能，信之，曰：「謹奉教！」","sentenceOrder":140},
  {"id":"s_work_han_thu_45_141","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「挈謂執提之。」","sentenceOrder":141},
  {"id":"s_work_han_thu_45_142","chapterId":"ch_work_han_thu_45","textTraditional":"漢十年，豨果反，高帝自將而往，信〔稱〕病不從。陰使人之豨所，而與家臣謀，夜詐赦諸官徒奴，欲發兵襲呂后、太子。部署已定，待豨報。其舍人得罪信，信囚，欲殺之。〔一〕舍人弟上書變告信欲反狀於呂后。呂后欲召，恐其黨不（亂）〔就〕，〔二〕乃與蕭相國謀，詐令人從帝所來，稱豨已死，群臣皆賀。相國紿信曰：「雖病，強入賀。」〔三〕信入，呂后使武士縛信，斬之長樂鍾室。〔四〕信方斬，曰：「吾不用蒯通計，反為女子所詐，豈非天哉！」遂夷信三族。","sentenceOrder":142},
  {"id":"s_work_han_thu_45_143","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　晉灼曰：「楚漢春秋云謝公也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_45_144","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「黨音他朗反。」","sentenceOrder":144},
  {"id":"s_work_han_thu_45_145","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「紿，詐也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_45_146","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　師古曰：「鍾室，謂懸鍾之室。」","sentenceOrder":146},
  {"id":"s_work_han_thu_45_147","chapterId":"ch_work_han_thu_45","textTraditional":"高祖已破豨歸，至，聞信死，且喜且哀之，問曰：「信死亦何言？」呂后道其語。高祖曰：「此齊辯士蒯通也。」召欲亨之。通至自說，釋弗誅。〔一〕語在通傳。","sentenceOrder":147},
  {"id":"s_work_han_thu_45_148","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「自說，謂自解說也。釋，放也，置也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_45_149","chapterId":"ch_work_han_thu_45","textTraditional":"彭越字仲，昌邑人也。常漁鉅野澤中，為盜。〔一〕陳勝起，或謂越曰：「豪桀相立畔秦，仲可效之。」越曰：「兩龍方鬥，且待之。」〔二〕","sentenceOrder":149},
  {"id":"s_work_han_thu_45_150","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「漁，捕魚也。鉅野，即今鄆州鉅野（中）〔縣〕。」","sentenceOrder":150},
  {"id":"s_work_han_thu_45_151","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「兩龍，謂秦與陳勝。」","sentenceOrder":151},
  {"id":"s_work_han_thu_45_152","chapterId":"ch_work_han_thu_45","textTraditional":"居歲餘，澤間少年相聚百餘人，往從越，「請仲為長」，越謝不願也。少年強請，乃許。與期旦日日出時，後會者斬。旦日日出，十餘人後，後者至日中。於是越謝曰：「臣老，諸君強以為長。今期而多後，不可盡誅，誅最後者一人。」令校長斬之。〔一〕皆笑曰：「何至是！請後不敢。」於是越乃引一人斬之，設壇祭，令徒屬。徒屬皆驚，畏越，不敢仰視。乃行略地，收諸侯散卒，得千餘人。","sentenceOrder":152},
  {"id":"s_work_han_thu_45_153","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「一校之長也。校音下教反。」","sentenceOrder":153},
  {"id":"s_work_han_thu_45_154","chapterId":"ch_work_han_thu_45","textTraditional":"沛公之從碭北擊昌邑，越助之。昌邑未下，沛公引兵西。越亦將其眾居鉅野澤中，收魏敗散卒。項籍入關，王諸侯，還歸，越眾萬餘人無所屬。齊王田榮叛項王，漢乃使人賜越將軍印，使下濟陰以擊楚。楚令蕭公角將兵擊越，越大破楚軍。漢二年春，與魏豹及諸侯東擊楚，越將其兵三萬餘人，歸漢外黃。〔一〕漢王曰：「彭將軍收魏地，得十餘城，欲急立魏後。今西魏王豹，魏咎從弟，真魏也。」〔二〕乃拜越為魏相國，擅將兵，略定梁地。〔三〕","sentenceOrder":154},
  {"id":"s_work_han_thu_45_155","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「於外黃來歸漢。」","sentenceOrder":155},
  {"id":"s_work_han_thu_45_156","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　鄭氏曰：「豹，真魏後也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_45_157","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「擅，專也，使專為此事。」","sentenceOrder":157},
  {"id":"s_work_han_thu_45_158","chapterId":"ch_work_han_thu_45","textTraditional":"漢王之敗彭城解而西也，越皆亡其所下城，獨將其兵北居河上。漢三年，越常往來為漢游兵擊楚，絕其糧於梁地。項王與漢王相距滎陽，越攻下睢陽、外黃十七城。項王聞之，乃使曹咎守成皋，自東收越所下城邑，皆復為楚。越將其兵北走穀城。項王南走陽夏，〔一〕越復下昌邑旁二十餘城，得粟十餘萬斛，以給漢食。","sentenceOrder":158},
  {"id":"s_work_han_thu_45_159","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「走並音奏。夏音攻雅反。」","sentenceOrder":159},
  {"id":"s_work_han_thu_45_160","chapterId":"ch_work_han_thu_45","textTraditional":"漢王敗，使使召越并力擊楚，越曰：「魏地初定，尚畏楚，未可去。」漢王追楚，為項籍所敗固陵。乃謂留侯曰：「諸侯兵不從，為之奈何？」留侯曰：「彭越本定梁地，功多，始君王以魏豹故，拜越為相國。今豹死亡後，且越亦欲王，而君王不蚤定。〔一〕今取睢陽以北至穀城，皆許以王彭越。」又言所以許韓信。語在高紀。於是漢王發使使越，如留侯策。使者至，越乃引兵會垓下。項籍死，立越為梁王，都定陶。","sentenceOrder":160},
  {"id":"s_work_han_thu_45_161","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「蚤，古早字。」","sentenceOrder":161},
  {"id":"s_work_han_thu_45_162","chapterId":"ch_work_han_thu_45","textTraditional":"六年，朝陳。九年，十年，皆來朝長安。","sentenceOrder":162},
  {"id":"s_work_han_thu_45_163","chapterId":"ch_work_han_thu_45","textTraditional":"陳豨反代地，高帝自往擊之，至邯鄲，徵兵梁。梁王稱病，使使將兵詣邯鄲。高帝怒，使人讓梁王。〔一〕梁王恐，欲自往謝。其將扈輒曰：「王始不往，見讓而往，往即為禽，不如遂發兵反。」梁王不聽，稱病。梁太僕有罪，亡走漢，告梁王與扈輒謀反。於是上使使掩捕梁王，囚之雒陽。有司治反形已具，〔二〕請論如法。上赦以為庶人，徙蜀青衣。〔三〕西至鄭，〔四〕逢呂后從長安東，欲之雒陽，道見越。越為呂后泣涕，自言亡罪，願處故昌邑。呂后許諾，詔與俱東。至雒陽，呂后言上曰：「彭越壯士也，今徙之蜀，此自遺患，不如遂誅之。妾謹與俱來。」於是呂后令其舍人告越復謀反。廷尉奏請，遂夷越宗族。","sentenceOrder":163},
  {"id":"s_work_han_thu_45_164","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「讓，責也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_45_165","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　張晏曰：「扈輒勸越反，越不聽，而云反形已具，有司非也。」臣瓚曰：「扈輒勸越反，而越不誅輒，是反形已具也。」師古曰：「瓚說是也。」","sentenceOrder":165},
  {"id":"s_work_han_thu_45_166","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　文穎曰：「青衣，縣名。」","sentenceOrder":166},
  {"id":"s_work_han_thu_45_167","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　師古曰：「即今華州鄭縣是也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_45_168","chapterId":"ch_work_han_thu_45","textTraditional":"黥布，六人也，〔一〕姓英氏。少時客相之，當刑而王。及壯，坐法黥，布欣然笑曰：「人相我當刑而王，幾是乎？」〔二〕人有聞者，共戲笑之。布以論輸驪山，〔三〕驪山之徒數十萬人，布皆與其徒長豪桀交通，乃率其曹耦，亡之江中為群盜。〔四〕","sentenceOrder":168},
  {"id":"s_work_han_thu_45_169","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「六，縣名也。解在高紀。」","sentenceOrder":169},
  {"id":"s_work_han_thu_45_170","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　臣瓚曰：「幾，近也。」師古曰：「幾音鉅依反。」","sentenceOrder":170},
  {"id":"s_work_han_thu_45_171","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「有罪論決，而輸作於驪山。」","sentenceOrder":171},
  {"id":"s_work_han_thu_45_172","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　師古曰：「曹，輩也。」","sentenceOrder":172},
  {"id":"s_work_han_thu_45_173","chapterId":"ch_work_han_thu_45","textTraditional":"陳勝之起也，布乃見番君，〔一〕其眾數千人。番君以女妻之。章邯之滅陳勝，破呂臣軍，布引兵北擊秦左右校，破之青波，〔二〕引兵而東。聞項梁定會稽，西度淮，布以兵屬梁。梁西擊景駒、秦嘉等，布常冠軍。〔三〕項梁聞陳涉死，立楚懷王，以布為當陽君。項梁敗死，懷王與布及諸侯將皆聚彭城。當是時，秦急圍趙，趙數使人請救懷王。懷王使宋義為上將〔軍〕，項籍與布皆屬之，北救趙。及籍殺宋義河上，自立為上將軍，使布先涉河，〔四〕擊秦軍，數有利。籍乃悉引兵從之，遂破秦軍，降章邯等。楚兵常勝，功冠諸侯。諸侯兵皆服屬楚者，以布數以少敗眾也。","sentenceOrder":173},
  {"id":"s_work_han_thu_45_174","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「番音蒲何反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_45_175","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「地名也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_45_176","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「言其驍勇為眾軍之最。」","sentenceOrder":176},
  {"id":"s_work_han_thu_45_177","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　師古曰：「涉謂無舟楫而渡也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_45_178","chapterId":"ch_work_han_thu_45","textTraditional":"項籍之引兵西至新安，又使布等夜擊阬章邯秦卒二十餘萬人。至關，不得入，又使布等先從間道破關下軍，〔一〕遂得入。至咸陽，布為前鋒。項王封諸將，立布為九江王，都六。尊懷王為義帝，徙都長沙，乃陰令布擊之。布使將追殺之郴。","sentenceOrder":178},
  {"id":"s_work_han_thu_45_179","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「間道，微道也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_45_180","chapterId":"ch_work_han_thu_45","textTraditional":"齊王田榮叛楚，項王往擊齊，徵兵九江，布稱病不往，遣將將數千人行。漢之敗楚彭城，布又稱病不佐楚。項王由此怨布，數使使者譙讓召布，〔一〕布愈恐，不敢往。項王方北憂齊、趙，西患漢，所與者獨布，又多其材，〔二〕欲親用之，以故未擊。","sentenceOrder":180},
  {"id":"s_work_han_thu_45_181","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「譙讓，責之也。譙音在笑反。」","sentenceOrder":181},
  {"id":"s_work_han_thu_45_182","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「多猶重也。」","sentenceOrder":182},
  {"id":"s_work_han_thu_45_183","chapterId":"ch_work_han_thu_45","textTraditional":"漢王與楚大戰彭城，不利，出梁地，至虞，〔一〕謂左右曰：「如彼等者，無足與計天下事者。」謁者隨何進曰：「不審陛下所謂。」漢王曰：「孰能為我使淮南，〔二〕使之發兵背楚，留項王於齊數月，我之取天下可以萬全。」隨何曰：「臣請使之。」乃與二十人俱使淮南。至，太宰主之，〔三〕三日不得見。隨何因說太宰曰：「王之不見何，必以楚為彊，以漢為弱，此臣之所為使。〔四〕使何得見，言之而是邪，是大王所欲聞也；言之而非邪，使何等二十人伏斧質淮南巿，〔五〕以明背漢而與楚也。」太宰乃言之王，王見之。隨何曰：「漢王使使臣敬進書大王御者，竊怪大王與楚何親也。」淮南王曰：「寡人北鄉而臣事之。」〔六〕隨何曰：「大王與項王俱列為諸侯，北鄉而臣事之，必以楚為彊，可以託國也。項王伐齊，身負版築，〔七〕以為士卒先。大王宜悉淮南之眾，〔八〕身自將，為楚軍前鋒，今乃發四千人以助楚。夫北面而臣事人者，固若是乎？夫漢王戰於彭城，項王未出齊也，大王宜埽淮南之眾，日夜會戰彭城下。〔九〕今撫萬人之眾，無一人渡淮者，陰拱而觀其孰勝。〔一０〕夫託國於人者，固若是乎？大王提空名以鄉楚，〔一一〕而欲厚自託，臣竊為大王不取也。然大王不背楚者，以漢為弱也。夫楚兵雖彊，天下負之以不義之名，〔一二〕以其背明約而殺義帝也。然而楚王特以戰勝自彊。漢王收諸侯，還守成皋、滎陽，下蜀、漢之粟，深溝壁壘，分卒守徼乘塞。楚人還兵，間以梁地，〔一三〕深入敵國八九百里〔一四〕，欲戰則不得，攻城則力不能，老弱轉糧千里之外。楚兵至滎陽、成皋，漢堅守而不動，進則不得攻，退則不能解，故楚兵不足罷也。〔一五〕使楚兵勝漢，則諸侯自危懼而相救。夫楚之彊，適足以致天下之兵耳。故楚不如漢，其勢易見也。今大王不與萬全之漢，而自託於危亡之楚，臣竊為大王或之。臣非以淮南之兵足以亡楚也。夫大王發兵而背楚，項王必留；留數月，漢之取天下可以萬全。臣請與大王杖劍而歸漢王，漢王必裂地而分大王，又況淮南，必大王有也。故漢王敬使使臣進愚計，願大王之留意也。」淮南王曰：「請奉命。」陰許叛楚與漢，未敢泄。","sentenceOrder":183},
  {"id":"s_work_han_thu_45_184","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「即今宋州虞城縣是也。」","sentenceOrder":184},
  {"id":"s_work_han_thu_45_185","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「孰，誰也。」","sentenceOrder":185},
  {"id":"s_work_han_thu_45_186","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　服虔曰：「淮南太宰作內主。」","sentenceOrder":186},
  {"id":"s_work_han_thu_45_187","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　師古曰：「此事正是臣所為來欲言之。」","sentenceOrder":187},
  {"id":"s_work_han_thu_45_188","chapterId":"ch_work_han_thu_45","textTraditional":"〔五〕　師古曰：「質，鍖也。言伏於鍖上而斧斬之。鍖音竹林反。」","sentenceOrder":188},
  {"id":"s_work_han_thu_45_189","chapterId":"ch_work_han_thu_45","textTraditional":"〔六〕　師古曰：「鄉讀曰嚮。次下亦同。」","sentenceOrder":189},
  {"id":"s_work_han_thu_45_190","chapterId":"ch_work_han_thu_45","textTraditional":"〔七〕　李奇曰：「版，牆版也。築，杵也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_45_191","chapterId":"ch_work_han_thu_45","textTraditional":"〔八〕　師古曰：「悉，盡也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_45_192","chapterId":"ch_work_han_thu_45","textTraditional":"〔九〕　師古曰：「埽者，謂盡舉之，如埽地之為。」","sentenceOrder":192},
  {"id":"s_work_han_thu_45_193","chapterId":"ch_work_han_thu_45","textTraditional":"〔一０〕師古曰：「斂手曰拱。孰，誰也。言不動搖，坐觀成敗也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_45_194","chapterId":"ch_work_han_thu_45","textTraditional":"〔一一〕師古曰：「提，舉也。鄉讀曰嚮。」","sentenceOrder":194},
  {"id":"s_work_han_thu_45_195","chapterId":"ch_work_han_thu_45","textTraditional":"〔一二〕師古曰：「負，加也。加於身上，若言被也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_45_196","chapterId":"ch_work_han_thu_45","textTraditional":"〔一三〕服虔曰：「梁在楚、漢之中央。」師古曰：「間音居莧反。」","sentenceOrder":196},
  {"id":"s_work_han_thu_45_197","chapterId":"ch_work_han_thu_45","textTraditional":"〔一四〕張晏曰：「羽從齊還，當經梁地八九百里，乃得羽地也。」","sentenceOrder":197},
  {"id":"s_work_han_thu_45_198","chapterId":"ch_work_han_thu_45","textTraditional":"〔一五〕師古曰：「不足者，言易也。罷讀曰疲。」","sentenceOrder":198},
  {"id":"s_work_han_thu_45_199","chapterId":"ch_work_han_thu_45","textTraditional":"楚使者在，〔一〕方急責布發兵，隨何直入曰：「九江王已歸漢，楚何以得發兵！」布愕然。楚使者起，何因說布曰：「事已搆〔二〕，獨可遂殺楚使，毋使歸，而疾走漢并力。」〔三〕布曰：「如使者教。」因起兵而攻楚。楚使項聲、龍且攻淮南，項王留而攻下邑。〔四〕數月，龍且攻淮南，破布軍。布欲引兵走漢，恐項王擊之，故間行與隨何俱歸漢。","sentenceOrder":199},
  {"id":"s_work_han_thu_45_200","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　文穎曰：「在淮南王所也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_45_201","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「搆，結也。言背楚之事以結成也。」","sentenceOrder":201},
  {"id":"s_work_han_thu_45_202","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「走音奏。次下亦同。」","sentenceOrder":202},
  {"id":"s_work_han_thu_45_203","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　師古曰：「縣名也，在梁地。」","sentenceOrder":203},
  {"id":"s_work_han_thu_45_204","chapterId":"ch_work_han_thu_45","textTraditional":"至，漢王方踞床洗，〔一〕而召布入見。布大怒，悔來，欲自殺。出就舍，張御食飲從官如漢王居，布又大喜過望。〔二〕於是乃使人之九江。楚已使項伯收九江兵，盡殺布妻子。布使者頗得故人幸臣，將眾數千人歸漢。漢益分布兵而與俱北，收兵至成皋。四年秋七月，立布為淮南王，與擊項籍。布使人之九江，得數縣。五年，布與劉賈入九江，誘大司馬周殷，殷反楚。遂舉九江兵與漢擊楚，破垓下。","sentenceOrder":204},
  {"id":"s_work_han_thu_45_205","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「洗，濯足也，音先典反。」","sentenceOrder":205},
  {"id":"s_work_han_thu_45_206","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「高祖以布先久為王，恐其意自尊大，故峻其禮，令布折服。已而美其帷帳，厚其飲食，多其從官，以悅其心，此權道也。張音竹亮反，若今言張設。」","sentenceOrder":206},
  {"id":"s_work_han_thu_45_207","chapterId":"ch_work_han_thu_45","textTraditional":"項籍死，上置酒對眾折隨何曰腐儒，〔一〕「為天下安用腐儒哉！」〔二〕隨何跪曰：「夫陛下引兵攻彭城，楚王未去齊也，陛下發步卒五萬人，騎五千，能以取淮南乎？」曰：「不能。」隨何曰：「陛下使何與二十人使淮南，如陛下之意，是何之功賢於步卒數萬，騎五千也。然陛下謂何腐儒，『為天下安用腐儒』，何也？」上曰：「吾方圖子之功。」〔三〕乃以隨何為護軍中尉。布遂剖符為淮南王，都六，九江、廬江、衡山、豫章郡皆屬焉。","sentenceOrder":207},
  {"id":"s_work_han_thu_45_208","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「腐者，爛敗。言無所堪任。」","sentenceOrder":208},
  {"id":"s_work_han_thu_45_209","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「高祖意欲褒賞隨何，恐群臣不服，故對眾折辱，令其自數功勞也。」","sentenceOrder":209},
  {"id":"s_work_han_thu_45_210","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「圖，謀也。」","sentenceOrder":210},
  {"id":"s_work_han_thu_45_211","chapterId":"ch_work_han_thu_45","textTraditional":"六年，朝陳。七年，朝雒陽。九年，朝長安。","sentenceOrder":211},
  {"id":"s_work_han_thu_45_212","chapterId":"ch_work_han_thu_45","textTraditional":"十一年，高后誅淮陰侯，布因心恐。夏，漢誅梁王彭越，盛其醢以遍賜諸侯。〔一〕至淮南，淮南王方獵，見醢，因大恐，陰令人部聚兵，候伺旁郡警急。〔二〕","sentenceOrder":212},
  {"id":"s_work_han_thu_45_213","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「反者被誅，皆以為醢，即刑法志所云『葅其骨肉』是也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_45_214","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「恐被收捕，即欲發兵反。」","sentenceOrder":214},
  {"id":"s_work_han_thu_45_215","chapterId":"ch_work_han_thu_45","textTraditional":"布有所幸姬病，就醫。醫家與中大夫賁赫對門，〔一〕赫乃厚餽遺，從姬飲醫家。姬侍王，從容語次，譽赫長者也。〔二〕王怒曰：「女安從知之？」〔三〕具道，王疑與亂。赫恐，稱病。王愈怒，欲捕赫。赫上變事，乘傳詣長安。〔四〕布使人追，不及。赫至，上變，言布謀反有端，可先未發誅也。〔五〕上以其書語蕭相國，蕭相國曰：「布不宜有此，〔六〕恐仇怨妄誣之。〔七〕請繫赫，使人微驗淮南王。」〔八〕布見赫以罪亡上變，已疑其言國陰事，漢使又來，頗有所驗，遂族赫家，發兵反。","sentenceOrder":215},
  {"id":"s_work_han_thu_45_216","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「賁音肥。姓賁，名赫。」","sentenceOrder":216},
  {"id":"s_work_han_thu_45_217","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「從音千容反。」","sentenceOrder":217},
  {"id":"s_work_han_thu_45_218","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「安從，何由者也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_45_219","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　師古曰：「傳音張戀反。」","sentenceOrder":219},
  {"id":"s_work_han_thu_45_220","chapterId":"ch_work_han_thu_45","textTraditional":"〔五〕　師古曰：「及其未發兵，先誅伐之。」","sentenceOrder":220},
  {"id":"s_work_han_thu_45_221","chapterId":"ch_work_han_thu_45","textTraditional":"〔六〕　師古曰：「不應有反謀。」","sentenceOrder":221},
  {"id":"s_work_han_thu_45_222","chapterId":"ch_work_han_thu_45","textTraditional":"〔七〕　師古曰：「怨音於元反。」","sentenceOrder":222},
  {"id":"s_work_han_thu_45_223","chapterId":"ch_work_han_thu_45","textTraditional":"〔八〕　師古曰：「微驗，不顯言其事。」","sentenceOrder":223},
  {"id":"s_work_han_thu_45_224","chapterId":"ch_work_han_thu_45","textTraditional":"反書聞，上乃赦赫，以為將軍。召諸侯問：「布反，為之柰何？」皆曰：「發兵阬豎子耳，何能為！」汝陰侯滕公以問其客薛公，薛公曰：「是固當反。」滕公曰：「上裂地而封之，疏爵而貴之，〔一〕南面而立萬乘之主，其反何也？」薛公曰：「前年殺彭越，往年殺韓信，〔二〕三人皆同功一體之人也。自疑禍及身，故反耳。」滕公言之上曰：「臣客故楚令尹薛公，其人有籌策，可問。」上乃見問薛公，對曰：「布反不足怪也。使布出於上計，山東非漢之有也；出於中計，勝負之數未可知也；出於下計，陛下安枕而臥矣。」上曰：「何謂上計？」薛公對曰：「東取吳，西取楚，并齊取魯，傳檄燕、趙，固守其所，山東非漢之有也。」「何謂中計？」「東取吳，西取楚，并韓取魏，據敖倉之粟，塞成皋之險，勝敗之數未可知也。」「何謂下計？」「東取吳，西取下蔡，歸重於越，身歸長沙，〔三〕陛下安枕而臥，漢無事矣。」上曰：「是計將安出？」〔四〕薛公曰：「出下計。」上曰：「胡為廢上計而出下計？」〔五〕薛公曰：「布故驪山之徒也，致萬乘之主，此皆為身，不顧後為百姓萬世慮者也，故出下計。」上曰：「善。」封薛公千戶。遂發兵自將東擊布。","sentenceOrder":224},
  {"id":"s_work_han_thu_45_225","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　張晏曰：「疏，分也。」","sentenceOrder":225},
  {"id":"s_work_han_thu_45_226","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　張晏曰：「往年與前年同耳，文相避也。」","sentenceOrder":226},
  {"id":"s_work_han_thu_45_227","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「重，輜重也，音直用反。」","sentenceOrder":227},
  {"id":"s_work_han_thu_45_228","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　師古曰：「是者，謂布也。」","sentenceOrder":228},
  {"id":"s_work_han_thu_45_229","chapterId":"ch_work_han_thu_45","textTraditional":"〔五〕　師古曰：「胡，何也。」","sentenceOrder":229},
  {"id":"s_work_han_thu_45_230","chapterId":"ch_work_han_thu_45","textTraditional":"布之初反，謂其將曰：「上老矣，厭兵，必不能來。使諸將，諸將獨患淮陰、彭越，今已死，餘不足畏。」故遂反。果如薛公揣之，〔一〕東擊荊，荊王劉賈走死富陵。〔二〕盡劫其兵，度淮擊楚。楚發兵與戰徐、僮間，〔三〕為三軍，欲以相救為奇。〔四〕或說楚將曰：「布善用兵，民素畏之。且兵法，諸侯自戰其地為散地。〔五〕今別為三，彼敗吾一，餘皆走，安能相救！」不聽。布果破其一軍，二軍散走。","sentenceOrder":230},
  {"id":"s_work_han_thu_45_231","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　文穎曰：「揣，度也，音初委反。」","sentenceOrder":231},
  {"id":"s_work_han_thu_45_232","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「縣名，屬臨淮郡。」","sentenceOrder":232},
  {"id":"s_work_han_thu_45_233","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「二縣之間也。」","sentenceOrder":233},
  {"id":"s_work_han_thu_45_234","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　師古曰：「不聚一處，分而為三，欲互相救，出奇兵。」","sentenceOrder":234},
  {"id":"s_work_han_thu_45_235","chapterId":"ch_work_han_thu_45","textTraditional":"〔五〕　師古曰：「謂在其本地戀土懷安，故易逃散。」","sentenceOrder":235},
  {"id":"s_work_han_thu_45_236","chapterId":"ch_work_han_thu_45","textTraditional":"遂西，與上兵遇蘄西，會垂。〔一〕布兵精甚，上乃壁庸城〔二〕，望布軍置陳如項籍軍。上惡之，與布相望見，隃謂布「何苦而反？」〔三〕布曰：「欲為帝耳。」上怒罵之，遂戰，破布軍。布走度淮，數止戰，不利，與百餘人走江南。布舊與番君婚，故長沙哀王使人誘布，〔四〕偽與俱亡，走越，〔五〕布信而隨至番陽。番陽人殺布茲鄉，〔六〕遂滅之。封賁赫為列侯，將率封者六人。","sentenceOrder":236},
  {"id":"s_work_han_thu_45_237","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「會音工外反。垂音丈瑞反，解在高紀。」","sentenceOrder":237},
  {"id":"s_work_han_thu_45_238","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　鄧展曰：「地名也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_45_239","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「隃讀曰遙。」","sentenceOrder":239},
  {"id":"s_work_han_thu_45_240","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　晉灼曰：「芮之孫回也。」師古曰：「據表云惠帝二年哀王回始立，今此是芮之子成王臣耳。傳既不同，晉說亦誤也。」","sentenceOrder":240},
  {"id":"s_work_han_thu_45_241","chapterId":"ch_work_han_thu_45","textTraditional":"〔五〕　師古曰：「偽謂詐為此計。」","sentenceOrder":241},
  {"id":"s_work_han_thu_45_242","chapterId":"ch_work_han_thu_45","textTraditional":"〔六〕　師古曰：「鄡陽縣之鄉也。鄡音口堯反。」","sentenceOrder":242},
  {"id":"s_work_han_thu_45_243","chapterId":"ch_work_han_thu_45","textTraditional":"盧綰，豐人也，與高祖同里。綰親與高祖太上皇相愛，〔一〕及生男，高祖、綰同日生，里中持羊酒賀兩家。及高祖、綰壯，學書，又相愛也。里中嘉兩家親相愛，生子同日，壯又相愛，復賀羊酒。高祖為布衣時，有吏事避宅，綰常隨上下。〔二〕及高祖初起沛，綰以客從，入漢為將軍，常侍中。從東擊項籍，以太尉常從，出入臥內，衣被食飲賞賜，群臣莫敢望。雖蕭、曹等，特以事見禮，至其親幸，莫及綰者。封為長安侯。長安，故咸陽也。","sentenceOrder":243},
  {"id":"s_work_han_thu_45_244","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　晉灼曰：「親，父也。綰之父與高祖父太上皇相愛。」","sentenceOrder":244},
  {"id":"s_work_han_thu_45_245","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「避宅，謂不居其家，潛匿東西。」","sentenceOrder":245},
  {"id":"s_work_han_thu_45_246","chapterId":"ch_work_han_thu_45","textTraditional":"項籍死，使綰別將，與劉賈擊臨江王共尉，〔一〕還，從擊燕王臧荼，皆破平。時諸侯非劉氏而王者七人。上欲王綰，為群臣觖望。〔二〕及虜臧荼，乃下詔，詔諸將相列侯擇群臣有功者以為燕王。群臣知上欲王綰，皆曰：「太尉長安侯盧綰常從平定天下，功最多，可王。」上乃立綰為燕王。諸侯得幸莫如燕王者。綰立六年，以陳豨事見疑而敗。","sentenceOrder":246},
  {"id":"s_work_han_thu_45_247","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　李奇曰：「共敖子也。」師古曰：「共讀曰龔。」","sentenceOrder":247},
  {"id":"s_work_han_thu_45_248","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「觖謂相觖也。望，怨望也。觖音決。」","sentenceOrder":248},
  {"id":"s_work_han_thu_45_249","chapterId":"ch_work_han_thu_45","textTraditional":"豨者，宛句人也，〔一〕不知始所以得從。及韓王信反入匈奴，上至平城還，豨以郎中封為列侯，以趙相國將監趙、代邊，邊兵皆屬焉。豨少時，常稱慕魏公子，〔二〕及將守邊，招致賓客。常告過趙，〔三〕賓客隨之者千餘乘，邯鄲官舍皆滿。豨所以待客，如布衣交，皆出客下。〔四〕趙相周昌乃求入見上，具言豨賓客盛，擅兵於外，恐有變。上令人覆案豨客居代者諸為不法事，多連引豨。豨恐，陰令客通使王黃、曼丘臣所。〔五〕漢十年秋，太上皇崩，上因是召豨。豨稱病，遂與王黃等反，自立為代王，劫略趙、代。上聞，乃赦吏民為豨所詿誤劫略者。上自擊豨，破之。語在高紀。","sentenceOrder":249},
  {"id":"s_work_han_thu_45_250","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「宛句，縣名也，地理志屬濟陰。宛音於元反。句音劬。」","sentenceOrder":250},
  {"id":"s_work_han_thu_45_251","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「謂信陵君無忌。」","sentenceOrder":251},
  {"id":"s_work_han_thu_45_252","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「因休告之假而過趙。」","sentenceOrder":252},
  {"id":"s_work_han_thu_45_253","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　師古曰：「言屈己禮之，不以富貴自尊大。」","sentenceOrder":253},
  {"id":"s_work_han_thu_45_254","chapterId":"ch_work_han_thu_45","textTraditional":"〔五〕　師古曰：「二人皆韓王信將。」","sentenceOrder":254},
  {"id":"s_work_han_thu_45_255","chapterId":"ch_work_han_thu_45","textTraditional":"初，上如邯鄲擊豨，〔一〕燕王綰亦擊其東北。豨使王黃求救匈奴，綰亦使其臣張勝使匈奴，言豨等軍破。勝至胡，故燕王臧荼子衍亡在胡，見勝曰：「公所以重於燕者，以習胡事也。燕所以久存者，以諸侯數反，兵連不決也。今公為燕欲急滅豨等，豨等已盡，次亦至燕，公等亦且為虜矣。公何不令燕且緩豨，而與胡連和？事寬，得長王燕，即有漢急，可以安國。」勝以為然，乃私令匈奴兵擊燕。綰疑勝與胡反，上書請族勝。勝還報，具道所以為者。綰寤，乃詐論他人，以脫勝家屬，使得為匈奴間。〔二〕而陰使范齊之豨所，欲令久連兵毋決。〔三〕","sentenceOrder":255},
  {"id":"s_work_han_thu_45_256","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「如，往也。」","sentenceOrder":256},
  {"id":"s_work_han_thu_45_257","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「間音居莧反。」","sentenceOrder":257},
  {"id":"s_work_han_thu_45_258","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　晉灼曰：「使豨久亡畔。」","sentenceOrder":258},
  {"id":"s_work_han_thu_45_259","chapterId":"ch_work_han_thu_45","textTraditional":"漢既斬豨，其裨將降，言燕王綰使范齊通計謀豨所。上使使召綰，綰稱病。又使辟陽侯審食其、御史大夫趙堯往迎綰，因驗問其左右。綰愈恐，閟匿，〔一〕謂其幸臣曰：「非劉氏而王者，獨我與長沙耳。往年漢族淮陰，誅彭越，皆呂后計。今上病，屬任呂后。〔二〕呂后婦人，專欲以事誅異姓王者及大功臣。」乃稱病不行。其左右皆亡匿。語頗泄，辟陽侯聞之，歸具報，上益怒。又得匈奴降者，言張勝亡在匈奴，為燕使。於是上曰：「綰果反矣！」使樊噲擊綰。綰悉將其宮人家屬，騎數千，居長城下候伺，幸上病瘉，自入謝。〔三〕高祖崩，綰遂將其眾亡入匈奴，匈奴以為東胡盧王。為蠻夷所侵奪，常思復歸。居歲餘，死胡中。","sentenceOrder":259},
  {"id":"s_work_han_thu_45_260","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「閟，閉也，閉其蹤蹟，藏匿其人也。閟音祕。」","sentenceOrder":260},
  {"id":"s_work_han_thu_45_261","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「屬音之欲反。」","sentenceOrder":261},
  {"id":"s_work_han_thu_45_262","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「瘉與愈同。」","sentenceOrder":262},
  {"id":"s_work_han_thu_45_263","chapterId":"ch_work_han_thu_45","textTraditional":"高后時，綰妻與其子亡降，會高后病，不能見，舍燕邸，〔一〕為欲置酒見之。高后竟崩，綰妻亦病死。","sentenceOrder":263},
  {"id":"s_work_han_thu_45_264","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「舍，止也。諸侯王及諸郡朝宿之館，在京師者謂之邸。」","sentenceOrder":264},
  {"id":"s_work_han_thu_45_265","chapterId":"ch_work_han_thu_45","textTraditional":"孝景帝時，綰孫它人以東胡王降，〔一〕封為惡谷侯。傳至曾孫，有罪，國除。","sentenceOrder":265},
  {"id":"s_work_han_thu_45_266","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　如淳曰：「為東胡王而來降也。東胡，烏丸也。」","sentenceOrder":266},
  {"id":"s_work_han_thu_45_267","chapterId":"ch_work_han_thu_45","textTraditional":"吳芮，秦時番陽令也，〔一〕甚得江湖間民心，號曰番君。天下之初叛秦也，黥布歸芮，芮妻之，〔二〕因率越人舉兵以應諸侯。沛公攻南陽，乃遇芮之將梅鋗，〔三〕與偕攻析、酈，〔四〕降之。及項羽相王，〔五〕以芮率百越佐諸侯，從入關，故立芮為衡山王，都邾。〔六〕其將梅鋗功多，封十萬戶，為列侯。項籍死，上以鋗有功，從入武關，故德芮，徙為長沙王，都臨湘，一年薨，諡曰文王，子成王臣嗣。薨，子哀王回嗣。薨，子共王右嗣。〔七〕薨，子靖王差嗣。孝文後七年薨，無子，國除。初，文王芮，高祖賢之，制詔御史：「長沙王忠，其定著令。」〔八〕至孝惠、高后時，封芮庶子二人為列侯，傳國數世絕。","sentenceOrder":267},
  {"id":"s_work_han_thu_45_268","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕　師古曰：「番音蒲何反。」","sentenceOrder":268},
  {"id":"s_work_han_thu_45_269","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕　師古曰：「嫁女與之也。妻音千計反。他皆類此。」","sentenceOrder":269},
  {"id":"s_work_han_thu_45_270","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕　師古曰：「鋗音呼玄反。」","sentenceOrder":270},
  {"id":"s_work_han_thu_45_271","chapterId":"ch_work_han_thu_45","textTraditional":"〔四〕　師古曰：「二縣也，並屬南陽。酈音郎益反。」","sentenceOrder":271},
  {"id":"s_work_han_thu_45_272","chapterId":"ch_work_han_thu_45","textTraditional":"〔五〕　李奇曰：「自相尊王也。」","sentenceOrder":272},
  {"id":"s_work_han_thu_45_273","chapterId":"ch_work_han_thu_45","textTraditional":"〔六〕　師古曰：「邾音朱，又音姝。」","sentenceOrder":273},
  {"id":"s_work_han_thu_45_274","chapterId":"ch_work_han_thu_45","textTraditional":"〔七〕　師古曰：「共讀曰恭。」","sentenceOrder":274},
  {"id":"s_work_han_thu_45_275","chapterId":"ch_work_han_thu_45","textTraditional":"〔八〕　鄧展曰：「漢約非劉氏不王，而芮王，故著令中，使特王也。或曰，以芮至忠，故著令也。」師古曰：「尋後贊文，或說是也。」","sentenceOrder":275},
  {"id":"s_work_han_thu_45_276","chapterId":"ch_work_han_thu_45","textTraditional":"贊曰：昔高祖定天下，功臣異姓而王者八國。張耳、吳芮、彭越、黥布、臧荼、盧綰與兩韓信，皆徼一時之權變，以詐力成功，〔一〕咸得裂土，南面稱孤。見疑強大，懷不自安，事窮勢迫，卒謀叛逆，終於滅亡。張耳以智全，至子亦失國。唯吳芮之起，不失正道，故能傳號五世，以無嗣絕，慶流支庶。有以矣夫，〔二〕著于甲令而稱忠也！〔三〕","sentenceOrder":276},
  {"id":"s_work_han_thu_45_277","chapterId":"ch_work_han_thu_45","textTraditional":"〔一〕師古曰：「徼，要也，音工堯反。」","sentenceOrder":277},
  {"id":"s_work_han_thu_45_278","chapterId":"ch_work_han_thu_45","textTraditional":"〔二〕師古曰：「以其不用詐力也。」","sentenceOrder":278},
  {"id":"s_work_han_thu_45_279","chapterId":"ch_work_han_thu_45","textTraditional":"〔三〕師古曰：「甲者，令篇之次也。」","sentenceOrder":279},
  {"id":"s_work_han_thu_45_280","chapterId":"ch_work_han_thu_45","textTraditional":"校勘記","sentenceOrder":280},
  {"id":"s_work_han_thu_45_281","chapterId":"ch_work_han_thu_45","textTraditional":"一八六二頁　九行　上不欲就天（子）〔下〕乎？景祐、殿、局本都作「下」，史記同。","sentenceOrder":281},
  {"id":"s_work_han_thu_45_282","chapterId":"ch_work_han_thu_45","textTraditional":"一八六三頁　二行　信度何等已數言上，〔一〕不我用，即亡。　注〔一〕原在「言」字下。　楊樹達說「上」字當屬上讀，顏於「言」字下斷句，非是。","sentenceOrder":282},
  {"id":"s_work_han_thu_45_283","chapterId":"ch_work_han_thu_45","textTraditional":"一八六三頁一０行　〔王〕必欲拜之，　景祐、殿本都有「王」字，史記同。","sentenceOrder":283},
  {"id":"s_work_han_thu_45_284","chapterId":"ch_work_han_thu_45","textTraditional":"一八六四頁　二行　信（以）〔已〕拜，上坐。　景祐、殿本都作「已」。","sentenceOrder":284},
  {"id":"s_work_han_thu_45_285","chapterId":"ch_work_han_thu_45","textTraditional":"一八六四頁　四行　唯〔三〕信亦以為大王弗如也。　王念孫說當作一句讀，「唯」讀為「雖」。史記淮陰侯傳作「惟信亦為大王不如也」，則不得斷「惟」字為句而讀為唯諾之唯矣。","sentenceOrder":285},
  {"id":"s_work_han_thu_45_286","chapterId":"ch_work_han_thu_45","textTraditional":"一八六七頁一０行　從間（道）〔路〕絕其輜重。　景祐、殿本都作「路」。王先謙說作「路」是。","sentenceOrder":286},
  {"id":"s_work_han_thu_45_287","chapterId":"ch_work_han_thu_45","textTraditional":"一八六九頁　八行　立（騎）〔駐〕傳餐食也。　景祐、殿本都作「駐」。","sentenceOrder":287},
  {"id":"s_work_han_thu_45_288","chapterId":"ch_work_han_thu_45","textTraditional":"一八七０頁　二行　諸校（劾）〔效〕首虜休，　沈欽韓說「劾」當作「效」。按景祐、殿本都作「效」，注同。","sentenceOrder":288},
  {"id":"s_work_han_thu_45_289","chapterId":"ch_work_han_thu_45","textTraditional":"一八七０頁一四行　（故）〔顧〕恐臣計未足用，　景祐、殿、局本都作「顧」。","sentenceOrder":289},
  {"id":"s_work_han_thu_45_290","chapterId":"ch_work_han_thu_45","textTraditional":"一八七一頁　二行　傾耳以待（禽）〔命〕者。　景祐、汲古、殿、局本都作「命」。","sentenceOrder":290},
  {"id":"s_work_han_thu_45_291","chapterId":"ch_work_han_thu_45","textTraditional":"一八七三頁　二行　漢兵遠鬥，窮寇〔久〕戰，鋒不可當也。　宋祁說一本「戰」字上有「久」字。按景祐本有。","sentenceOrder":291},
  {"id":"s_work_han_thu_45_292","chapterId":"ch_work_han_thu_45","textTraditional":"一八七三頁　七行　〔盛〕沙以壅水上流，　景祐、殿本都有「盛」字。王先謙說有「盛」字是。","sentenceOrder":292},
  {"id":"s_work_han_thu_45_293","chapterId":"ch_work_han_thu_45","textTraditional":"一八七三頁一五行　南邊（荒）〔楚〕，　景祐、殿本都作「楚」，史記同。","sentenceOrder":293},
  {"id":"s_work_han_thu_45_294","chapterId":"ch_work_han_thu_45","textTraditional":"一八七五頁　一行　深說以三分天下，（之計）〔鼎足而王〕。　景祐本無「之計」二字，有「鼎足而王」四字。","sentenceOrder":294},
  {"id":"s_work_han_thu_45_295","chapterId":"ch_work_han_thu_45","textTraditional":"一八七七頁一四行　信〔稱〕病不從。　宋祁說浙本「病」字上有「稱」字。錢大昭說南監本、閩本有「稱」字。按景祐本有。","sentenceOrder":295},
  {"id":"s_work_han_thu_45_296","chapterId":"ch_work_han_thu_45","textTraditional":"一八七八頁　一行　恐其黨不（亂）〔就〕，景祐、殿本都作「就」。王先謙說作「就」是。","sentenceOrder":296},
  {"id":"s_work_han_thu_45_297","chapterId":"ch_work_han_thu_45","textTraditional":"一八七八頁一三行　即今鄆州鉅野（中）〔縣〕　景祐、殿本都作「縣」。王先謙說作「縣」是。","sentenceOrder":297},
  {"id":"s_work_han_thu_45_298","chapterId":"ch_work_han_thu_45","textTraditional":"一八八二頁　三行　懷王使宋義為上將〔軍〕，　景祐本有「軍」字。","sentenceOrder":298},
  {"id":"s_work_han_thu_46_1","chapterId":"ch_work_han_thu_46","textTraditional":"荊王劉賈，高帝從父兄也，〔一〕不知其初起時。漢元年，還定三秦，賈為將軍，定塞地，〔二〕從東擊項籍。","sentenceOrder":1},
  {"id":"s_work_han_thu_46_2","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　師古曰：「父之兄弟之子，為從父兄弟也。言本同祖，從父而別。」","sentenceOrder":2},
  {"id":"s_work_han_thu_46_3","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　師古曰：「司馬欣之國也。塞音先代反。」","sentenceOrder":3},
  {"id":"s_work_han_thu_46_4","chapterId":"ch_work_han_thu_46","textTraditional":"漢王敗成皋，北度河，得張耳、韓信軍，軍脩武，深溝高壘，使賈將二萬人，騎數百，擊楚，度白馬津〔一〕入楚地，燒其積聚〔二〕，以破其業，無以給項王軍食。已而楚兵擊之，賈輒避不肯與戰，而與彭越相保。〔三〕","sentenceOrder":4},
  {"id":"s_work_han_thu_46_5","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　師古曰：「即今滑州白馬縣河津也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_46_6","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　師古曰：「倉廩芻稿之屬。」","sentenceOrder":6},
  {"id":"s_work_han_thu_46_7","chapterId":"ch_work_han_thu_46","textTraditional":"〔三〕　師古曰：「保謂依恃，以自安固。」","sentenceOrder":7},
  {"id":"s_work_han_thu_46_8","chapterId":"ch_work_han_thu_46","textTraditional":"漢王追項籍至固陵，使賈南度淮圍壽春。還至，使人間招楚大司馬周殷。〔一〕周殷反楚，佐賈舉九江，迎英布兵，皆會垓下，誅項籍。漢王因使賈將九江兵，與太尉盧綰西南擊臨江王共尉，〔二〕尉死，以臨江為南郡。","sentenceOrder":8},
  {"id":"s_work_han_thu_46_9","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　師古曰：「間謂私求間隙而招之。」","sentenceOrder":9},
  {"id":"s_work_han_thu_46_10","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　師古曰：「共敖之子也。共讀曰龔。」","sentenceOrder":10},
  {"id":"s_work_han_thu_46_11","chapterId":"ch_work_han_thu_46","textTraditional":"賈既有功，而高祖子弱，昆弟少，又不賢，欲王同姓以填天下，〔一〕乃下詔曰：「將軍劉賈有功，及擇子弟可以為王者。」群臣皆曰：「立劉賈為荊王，王淮東。」立六年而淮南王黥布反，東擊荊。賈與戰，弗勝，走富陵，〔二〕為布軍所殺。","sentenceOrder":11},
  {"id":"s_work_han_thu_46_12","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　師古曰：「填音竹刃反。」","sentenceOrder":12},
  {"id":"s_work_han_thu_46_13","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　師古曰：「縣名，地理志屬臨淮郡。」","sentenceOrder":13},
  {"id":"s_work_han_thu_46_14","chapterId":"ch_work_han_thu_46","textTraditional":"燕王劉澤，高祖從祖昆弟也。〔一〕高祖三年，澤為郎中。十一年，以將軍擊陳豨將王黃，封為營陵侯。","sentenceOrder":14},
  {"id":"s_work_han_thu_46_15","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　師古曰：「言同曾祖，從祖而別也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_46_16","chapterId":"ch_work_han_thu_46","textTraditional":"高后時，齊人田生〔一〕游乏資，以畫奸澤。〔二〕澤大說之，〔三〕用金二百斤為田生壽。〔四〕田生已得金，即歸齊。二歲，澤使人謂田生曰：「弗與矣。」〔五〕田生如長安，不見澤，而假大宅，令其子求事呂后所幸大謁者張卿。〔六〕居數月，田生子請張卿臨，親脩具。〔七〕張卿往，見田生帷帳具置如列侯。張卿驚。酒酣，乃屏人說張卿曰：「臣觀諸侯邸第百餘，皆高帝一切功臣。今呂氏雅故本推轂高帝就天下，〔八〕功至大，又有親戚太后之重。太后春秋長，〔九〕諸呂弱，太后欲立呂產為呂王，王代。（呂）〔太〕后又重發之，〔一０〕恐大臣不聽。今卿最幸，大臣所敬，何不風大臣以聞太后，〔一一〕太后必喜。諸呂以王，萬戶侯亦卿之有。太后心欲之，而卿為內臣，不急發，恐（過）〔禍〕及身矣。」張卿大然之，乃風大臣語太后。太后朝，因問大臣。大臣請立呂產為呂王。太后賜張卿千金，〔一二〕張卿以其半進田生。田生弗受，因說之曰：「呂產王也，諸大臣未大服。今營陵侯澤，諸劉長，為大將軍，獨此尚觖望。〔一三〕今卿言太后，裂十餘縣王之，彼得王喜，於諸呂王益固矣。」張卿入言之。又太后女弟呂須女亦為營陵侯妻，故遂立營陵侯澤為琅邪王。琅邪王與田生之國，急行毋留。〔一四〕出關，太后果使人追之。已出，即還。","sentenceOrder":16},
  {"id":"s_work_han_thu_46_17","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　晉灼曰：「楚漢春秋云字子春。」","sentenceOrder":17},
  {"id":"s_work_han_thu_46_18","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　服虔曰：「以計畫干之。」文穎曰：「以工畫得寵也。」師古曰：「共為計策，欲以求王。服說是也。畫音獲。」","sentenceOrder":18},
  {"id":"s_work_han_thu_46_19","chapterId":"ch_work_han_thu_46","textTraditional":"〔三〕　師古曰：「說讀曰悅。」","sentenceOrder":19},
  {"id":"s_work_han_thu_46_20","chapterId":"ch_work_han_thu_46","textTraditional":"〔四〕　師古曰：「因飲酒獻壽而與之金。」","sentenceOrder":20},
  {"id":"s_work_han_thu_46_21","chapterId":"ch_work_han_thu_46","textTraditional":"〔五〕　孟康曰：「與，黨與也。言不復與我為友也。」文穎曰：「不復與汝相知也。」師古曰：「孟說是。」","sentenceOrder":21},
  {"id":"s_work_han_thu_46_22","chapterId":"ch_work_han_thu_46","textTraditional":"〔六〕　如淳曰：「奄人也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_46_23","chapterId":"ch_work_han_thu_46","textTraditional":"〔七〕　師古曰：「親，父也。具，供具也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_46_24","chapterId":"ch_work_han_thu_46","textTraditional":"〔八〕　如淳曰：「呂公知高祖貴，以女妻之，推轂使為長者也。」師古曰：「謂翼戴崇獎，以成帝業，若車之行，助推其轂，故得引重而致遠也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_46_25","chapterId":"ch_work_han_thu_46","textTraditional":"〔九〕　師古曰：「言年老。」","sentenceOrder":25},
  {"id":"s_work_han_thu_46_26","chapterId":"ch_work_han_thu_46","textTraditional":"〔一０〕鄧展曰：「重，難發其事。」","sentenceOrder":26},
  {"id":"s_work_han_thu_46_27","chapterId":"ch_work_han_thu_46","textTraditional":"〔一一〕師古曰：「風讀曰諷。其下亦同。」","sentenceOrder":27},
  {"id":"s_work_han_thu_46_28","chapterId":"ch_work_han_thu_46","textTraditional":"〔一二〕師古曰：「千斤之金。」","sentenceOrder":28},
  {"id":"s_work_han_thu_46_29","chapterId":"ch_work_han_thu_46","textTraditional":"〔一三〕師古曰：「觖音決。」","sentenceOrder":29},
  {"id":"s_work_han_thu_46_30","chapterId":"ch_work_han_thu_46","textTraditional":"〔一四〕師古曰：「田生勸之。」","sentenceOrder":30},
  {"id":"s_work_han_thu_46_31","chapterId":"ch_work_han_thu_46","textTraditional":"澤王琅邪二年，而太后崩，澤乃曰：「帝少，諸呂用事，諸劉孤弱。」引兵與齊王合謀西，欲誅諸呂。至梁，聞漢灌將軍屯滎陽，澤還兵備西界，遂跳驅至長安。〔一〕代王亦從代至。諸將相與琅邪王共立代王，是為孝文帝。文帝元年，徙澤為燕王，而復以琅邪歸齊。〔二〕","sentenceOrder":31},
  {"id":"s_work_han_thu_46_32","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　師古曰：「齊王傳云使祝午紿琅邪王，琅邪王馳見齊王，齊王因留琅邪王，而使祝午盡發琅邪國而并將其兵。琅邪王既見欺，不得反國，乃說齊王求入關計事，齊王以為然，乃益具車送琅邪王，與此傳不同，疑此傳誤也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_46_33","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　李奇曰：「本齊地，前分以王澤，今復與齊也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_46_34","chapterId":"ch_work_han_thu_46","textTraditional":"澤王燕二年，薨，諡曰敬王。子康王嘉嗣，九年薨。子定國嗣。定國與父康王姬姦，生子男一人。奪弟妻為姬。與子女三人姦。定國有所欲誅殺臣肥如令郢人，郢人等告定國。〔一〕定國使謁者以它法劾捕格殺郢人滅口。至元朔中，郢人昆弟復上書具言定國事。下公卿，皆議曰：「定國禽獸行，亂人倫，逆天道，當誅。」上許之。定國自殺，立四十二年，國除。哀帝時繼絕世，乃封敬王澤玄孫之孫無終公士歸生為營陵侯，〔二〕更始中為兵所殺。〔三〕","sentenceOrder":34},
  {"id":"s_work_han_thu_46_35","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　如淳曰：「定國自欲有所殺餘臣，肥如知，令郢人以告也。」師古曰：「此說非也。肥如，燕之屬縣也。郢人者，縣令之名也。定國別欲誅其臣，又欲誅肥如令郢人，而為郢人等所告也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_46_36","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　師古曰：「無終，其所屬縣也。公士，第一爵。歸生，名也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_46_37","chapterId":"ch_work_han_thu_46","textTraditional":"〔三〕　師古曰：「更始，劉聖公之年號也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_46_38","chapterId":"ch_work_han_thu_46","textTraditional":"吳王濞，高帝兄仲之子也。高帝立仲為代王。匈奴攻代，仲不能堅守，棄國間行，走雒陽，自歸，天子不忍致法，廢為合陽侯。子濞，封為沛侯。黥布反，高祖自將往誅之。濞年二十，以騎將從破布軍。荊王劉賈為布所殺，無後。上患吳會稽輕悍，無壯王填之，〔一〕諸子少，〔二〕乃立濞於沛，為吳王，〔三〕王三郡五十三城。已拜受印，高祖召濞相之，曰：「若狀有反相。」〔四〕獨悔，業已拜，〔五〕因拊其背，〔六〕曰：「漢後五十年東南有亂，豈若邪？然天下同姓一家，慎無反！」濞頓首曰：「不敢。」","sentenceOrder":38},
  {"id":"s_work_han_thu_46_39","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　師古曰：「悍，勇也。填音竹刃反。」","sentenceOrder":39},
  {"id":"s_work_han_thu_46_40","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　師古曰：「少，幼也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_46_41","chapterId":"ch_work_han_thu_46","textTraditional":"〔三〕　師古曰：「行至沛而封拜濞也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_46_42","chapterId":"ch_work_han_thu_46","textTraditional":"〔四〕　師古曰：「若，汝也。此下亦同。」","sentenceOrder":42},
  {"id":"s_work_han_thu_46_43","chapterId":"ch_work_han_thu_46","textTraditional":"〔五〕　師古曰：「獨悔者，心自懷悔，不以語人也。既以封拜為事，臣下皆知之，故不改。」","sentenceOrder":43},
  {"id":"s_work_han_thu_46_44","chapterId":"ch_work_han_thu_46","textTraditional":"〔六〕　師古曰：「拊，摩循之也。一曰拊，輕擊之，音芳羽反。」","sentenceOrder":44},
  {"id":"s_work_han_thu_46_45","chapterId":"ch_work_han_thu_46","textTraditional":"會孝惠、高后時天下初定，郡國諸侯各務自拊循其民。吳有豫章郡銅山，〔一〕即招致天下亡命者盜鑄錢，東煮海水為鹽，以故無賦，國用饒足。〔二〕","sentenceOrder":45},
  {"id":"s_work_han_thu_46_46","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　韋昭曰：「此有豫字，誤也。但當言章郡，今故章也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_46_47","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　如淳曰：「鑄錢煮海，收其利以足國用，故無賦於民也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_46_48","chapterId":"ch_work_han_thu_46","textTraditional":"孝文時，吳太子入見，得侍皇太子飲博。吳太子師傅皆楚人，輕悍，又素驕。博爭道，不恭，皇太子引博局提吳太子，殺之。〔一〕於是遣其喪歸葬吳。吳王慍〔二〕曰：「天下一宗，〔三〕死長安即葬長安，何必來葬！」復遣喪之長安葬。吳王由是怨望，稍失藩臣禮，稱疾不朝。京師知其以子故，驗問實不病，諸吳使來，輒繫責治之。吳王恐，所謀滋甚。〔四〕及後使人為秋請，〔五〕上復責問吳使者。使者曰：「察見淵中魚，不祥。〔六〕今吳王始詐疾，（反）〔及〕覺，見責急，愈益閉，恐上誅之，計乃無聊。唯上與更始。〔七〕」於是天子皆赦吳使者歸之，而賜吳王几杖，老，不朝。吳得釋，其謀亦益解。然其居國以銅鹽故，百姓無賦。卒踐更，輒予平賈〔八〕。歲時存問茂材，賞賜閭里。〔九〕它郡國吏欲來捕亡人者，頌共禁不與。〔一０〕如此者三十餘年，以故能使其眾。","sentenceOrder":48},
  {"id":"s_work_han_thu_46_49","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　師古曰：「提，擲也，音徒計反。」","sentenceOrder":49},
  {"id":"s_work_han_thu_46_50","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　師古曰：「慍，怒也，音於問反。」","sentenceOrder":50},
  {"id":"s_work_han_thu_46_51","chapterId":"ch_work_han_thu_46","textTraditional":"〔三〕　師古曰：「猶言同姓共為一家。」","sentenceOrder":51},
  {"id":"s_work_han_thu_46_52","chapterId":"ch_work_han_thu_46","textTraditional":"〔四〕　師古曰：「滋，益也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_46_53","chapterId":"ch_work_han_thu_46","textTraditional":"〔五〕　孟康曰：「律，春曰朝，秋曰請，如古諸侯朝聘也。」如淳曰：「濞不自行也，使人代己致請禮。」師古曰：「二說皆是也。請音材姓反。」","sentenceOrder":53},
  {"id":"s_work_han_thu_46_54","chapterId":"ch_work_han_thu_46","textTraditional":"〔六〕　服虔曰：「天子察見下之私，則不祥也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_46_55","chapterId":"ch_work_han_thu_46","textTraditional":"〔七〕　師古曰：「言赦其已往之事。」","sentenceOrder":55},
  {"id":"s_work_han_thu_46_56","chapterId":"ch_work_han_thu_46","textTraditional":"〔八〕　服虔曰：「以當為更卒，出錢三百，謂之過更。自行為卒，謂之踐更。吳王欲得民心，為卒者顧其庸，隨時月與平賈也。」晉灼曰：「謂借人自代為卒者，官為出錢，顧其時庸平賈也。」師古曰：「晉說是也。賈讀曰價，謂庸直也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_46_57","chapterId":"ch_work_han_thu_46","textTraditional":"〔九〕　師古曰：「茂，美也。茂材者，有美材之人也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_46_58","chapterId":"ch_work_han_thu_46","textTraditional":"〔一０〕如淳曰：「頌猶公也。」師古曰：「頌讀曰容。」","sentenceOrder":58},
  {"id":"s_work_han_thu_46_59","chapterId":"ch_work_han_thu_46","textTraditional":"朝錯為太子家令，得幸皇太子，數從容言吳過可削。〔一〕數上書說之，文帝寬，不忍罰，以此吳王日益橫。〔二〕及景帝即位，錯為御史大夫，說上曰：「昔高帝初定天下，昆弟少，諸子弱，大封同姓，故孽子悼惠王王齊七十二城，〔三〕庶弟元王王楚四十城，兄子王吳五十餘城。封三庶孽，分天下半。今吳王前有太子之隙，詐稱病不朝，於古法當誅。文帝不忍，因賜几杖，德至厚也。不改過自新，乃益驕恣，公即山鑄錢，煮海為鹽，〔四〕誘天下亡人謀作亂逆。今削之亦反，不削亦反。削之，其反亟，禍小；不削之，其反遲，禍大。」〔五〕三年冬，楚王來朝，錯因言楚王戊往年為薄太后服，私姦服舍，〔六〕請誅之。詔赦，削東海郡。及前二年，趙王有罪，削其常山郡。膠西王卬以賣爵事有姦，削其六縣。","sentenceOrder":59},
  {"id":"s_work_han_thu_46_60","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　師古曰：「從音子容反。」","sentenceOrder":60},
  {"id":"s_work_han_thu_46_61","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　師古曰：「橫音胡孟反。」","sentenceOrder":61},
  {"id":"s_work_han_thu_46_62","chapterId":"ch_work_han_thu_46","textTraditional":"〔三〕　師古曰：「孽亦庶也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_46_63","chapterId":"ch_work_han_thu_46","textTraditional":"〔四〕　師古曰：「公謂顯然為之也。即，就也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_46_64","chapterId":"ch_work_han_thu_46","textTraditional":"〔五〕　師古曰：「亟，急也，音居力反。」","sentenceOrder":64},
  {"id":"s_work_han_thu_46_65","chapterId":"ch_work_han_thu_46","textTraditional":"〔六〕　服虔曰：「服在喪次，而私姦宮中也。」師古曰：「言於服舍為姦，非宮中也。服舍，居喪之次，堊室之屬也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_46_66","chapterId":"ch_work_han_thu_46","textTraditional":"漢廷臣方議削吳，吳王恐削地無已，因欲發謀舉事。念諸侯無足與計者，聞膠西王勇，好兵，諸侯皆畏憚之，於是乃使中大夫應高口說膠西王曰：「吳王不肖，有夙夜之憂，〔一〕不敢自外，使使臣諭其愚心。」王曰：「何以教之？」高曰：「今者主上任用邪臣，聽信讒賊，變更律令，〔二〕侵削諸侯，徵求滋多，誅罰良重，〔三〕日以益甚。語有之曰：『狧穅及米。』〔四〕吳與膠西，知名諸侯也，一時見察，不得安肆矣。〔五〕吳王身有內疾，不能朝請二十餘年，〔六〕常患見疑，無以自白，〔七〕脅肩絫足，猶懼不見釋。〔八〕竊聞大王以爵事有過，所聞諸侯削地，罪不至此，〔九〕此恐不止削地而已。」王曰：「有之，子將柰何？」高曰：「同惡相助，同好相留，同情相求，同欲相趨，同利相死。今吳王自以與大王同憂，願因時循理，棄軀以除患於天下，〔一０〕意亦可乎？」膠西王瞿然駭曰：〔一一〕「寡人何敢如是？主上雖急，固有死耳，安得不事？〔一二〕」高曰：「御史大夫朝錯營或天子，侵奪諸侯，〔一三〕蔽忠塞賢，朝廷疾怨，諸侯皆有背叛之意，人事極矣。彗星出，蝗蟲起，此萬世一時，而愁勞，聖人所以起也。吳王內以朝錯為誅，外從大王後車，方洋天下，〔一四〕所向者降，所指者下，莫敢不服。大王誠幸而許之一言，則吳王率楚王略函谷關，守滎陽敖倉之粟，距漢兵，治次舍，須大王。〔一五〕大王幸而臨之，則天下可并，兩主分割，不亦可乎？」王曰：「善。」歸報吳王，猶恐其不果，乃身自為使者，〔一六〕至膠西面約之。","sentenceOrder":66},
  {"id":"s_work_han_thu_46_67","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　師古曰：「凡言不肖者，謂其鄙陋無所象似也。解在刑法志。」","sentenceOrder":67},
  {"id":"s_work_han_thu_46_68","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　師古曰：「更，改也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_46_69","chapterId":"ch_work_han_thu_46","textTraditional":"〔三〕　師古曰：「滋亦益也。良，實也，信也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_46_70","chapterId":"ch_work_han_thu_46","textTraditional":"〔四〕　師古曰：「狧，古〈舌也〉字。〈舌也〉，用舌食也，蓋以犬為喻也。言初〈舌也〉穅遂至食米也。〈舌也〉音食爾反。」","sentenceOrder":70},
  {"id":"s_work_han_thu_46_71","chapterId":"ch_work_han_thu_46","textTraditional":"〔五〕　師古曰：「肆，縱也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_46_72","chapterId":"ch_work_han_thu_46","textTraditional":"〔六〕　師古曰：「內疾，謂在身中，不顯於外。請音材姓反。」","sentenceOrder":72},
  {"id":"s_work_han_thu_46_73","chapterId":"ch_work_han_thu_46","textTraditional":"〔七〕　師古曰：「白，明也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_46_74","chapterId":"ch_work_han_thu_46","textTraditional":"〔八〕　師古曰：「脅，翕也，謂歛之也。絫，古累字也。累足，重足也。並謂懼耳。釋，解也，放也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_46_75","chapterId":"ch_work_han_thu_46","textTraditional":"〔九〕　師古曰：「言其本罪皆不合削地也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_46_76","chapterId":"ch_work_han_thu_46","textTraditional":"〔一０〕師古曰：「循，順也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_46_77","chapterId":"ch_work_han_thu_46","textTraditional":"〔一一〕師古曰：「瞿然，無守之貌，音居具反。」","sentenceOrder":77},
  {"id":"s_work_han_thu_46_78","chapterId":"ch_work_han_thu_46","textTraditional":"〔一二〕師古曰：「安，焉也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_46_79","chapterId":"ch_work_han_thu_46","textTraditional":"〔一三〕師古曰：「營謂回繞之也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_46_80","chapterId":"ch_work_han_thu_46","textTraditional":"〔一四〕師古曰：「方洋猶翱翔也。方音房，又音旁。洋音羊。」","sentenceOrder":80},
  {"id":"s_work_han_thu_46_81","chapterId":"ch_work_han_thu_46","textTraditional":"〔一五〕師古曰：「次舍，息止之處也。須，待也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_46_82","chapterId":"ch_work_han_thu_46","textTraditional":"〔一六〕師古曰：「潛行而去也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_46_83","chapterId":"ch_work_han_thu_46","textTraditional":"膠西群臣或聞王謀，諫曰：「諸侯地不能為漢十二，〔一〕為叛逆以憂太后，非計也。〔二〕今承一帝，尚云不易，假令事成，兩主分爭，患乃益生。」王不聽，遂發使約齊、菑川、膠東、濟南，皆許諾。","sentenceOrder":83},
  {"id":"s_work_han_thu_46_84","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　師古曰：「不當漢十分之二。」","sentenceOrder":84},
  {"id":"s_work_han_thu_46_85","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　文穎曰：「王之太后也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_46_86","chapterId":"ch_work_han_thu_46","textTraditional":"諸侯既新削罰，震恐，多怨錯。乃削吳會稽、豫章郡書至，則吳王先起兵，誅漢吏二千石以下。膠西、膠東、菑川、濟南、楚、趙亦皆反，發兵西。齊王後悔，背約城守。濟北王城壞未完，其郎中令劫守王，不得發兵。膠西王、膠東王為渠率，〔一〕與菑川、濟南共攻圍臨菑。趙王遂亦陰使匈奴與連兵。","sentenceOrder":86},
  {"id":"s_work_han_thu_46_87","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　師古曰：「渠，大也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_46_88","chapterId":"ch_work_han_thu_46","textTraditional":"七國之發也，吳王悉其士卒，〔一〕下令國中曰：「寡人年六十二，身自將。少子年十四，亦為士卒先。諸年上與寡人同，下與少子等，皆發。」二十餘萬人。南使閩、東越，閩、東越亦發兵從。","sentenceOrder":88},
  {"id":"s_work_han_thu_46_89","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　師古曰：「悉，盡也，盡發使行。」","sentenceOrder":89},
  {"id":"s_work_han_thu_46_90","chapterId":"ch_work_han_thu_46","textTraditional":"孝景前三年正月甲子，初起兵於廣陵。西涉淮，因并楚兵。發使遺諸侯書曰：「吳王劉濞敬問膠西王、膠東王、菑川王、濟南王、趙王、楚王、淮南王、衡山王、廬江王、故長沙王子：〔一〕幸教！以漢有賊臣錯，無功天下，侵奪諸侯之地，使吏劾繫訊治，以侵辱之為故，〔二〕不以諸侯人君禮遇劉氏骨肉，〔三〕絕先帝功臣，進任姦人，誑亂天下，欲危社稷。陛下多病志逸，不能省察。〔四〕欲舉兵誅之，謹聞教。敝國雖狹，地方三千里；〔五〕人民雖少，精兵可具五十萬。寡人素事南越三十餘年，其王諸君皆不辭分其兵以隨寡人，〔六〕又可得三十萬。寡人雖不肖，願以身從諸王。南越直長沙者，因王子定長沙以北，〔七〕西走蜀、漢中。告越、〔八〕楚王、淮南三王，與寡人西面；〔九〕齊諸王與趙王定河間、河內，或入臨晉關，或與寡人會雒陽；〔一０〕燕王、趙王故與胡王有約，燕王北定代、雲中，轉胡眾入蕭關，走長安，〔一一〕匡正天下，以安高廟。願王勉之。楚元王子、淮南三王或不沐洗十餘年，怨入骨髓，〔一二〕欲壹有所出久矣，〔一三〕寡人未得諸王之意，未敢聽。今諸王苟能存亡繼絕，振弱伐暴，以安劉氏，社稷所願也。吳國雖貧，寡人節衣食用，積金錢，脩兵革，聚糧食，夜以繼日，三十餘年矣。凡皆為此，〔一四〕願諸王勉之。能斬捕大將者，賜金五千斤，封萬戶；列將，三千斤，封五千戶；裨將，二千斤，封二千戶；二千石，千斤，封千戶：皆為列侯。其以軍若城邑降者，卒萬人，邑萬戶，如得大將；〔一五〕人戶五千，如得列將；人戶三千，如得裨將；人戶千，如得二千石；其小吏皆以差次受爵金。它封賜皆倍軍法。〔一六〕其有故爵邑者，更益勿因。〔一七〕願諸王明以令士大夫，不敢欺也。寡人金錢在天下者往往而有，非必取於吳，〔一八〕諸王日夜用之不能盡。有當賜者告寡人，寡人且往遺之。敬以聞。」","sentenceOrder":90},
  {"id":"s_work_han_thu_46_91","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　如淳曰：「吳芮後四世無嗣，國除，庶子二人為列侯，不得嗣王，志將不滿，故誘與之反也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_46_92","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　孟康曰：「故，事也。」師古曰：「言專以侵辱諸侯為事業。」","sentenceOrder":92},
  {"id":"s_work_han_thu_46_93","chapterId":"ch_work_han_thu_46","textTraditional":"〔三〕　師古曰：「人君者，言諸王各自君其國。」","sentenceOrder":93},
  {"id":"s_work_han_thu_46_94","chapterId":"ch_work_han_thu_46","textTraditional":"〔四〕　師古曰：「逸，放也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_46_95","chapterId":"ch_work_han_thu_46","textTraditional":"〔五〕　師古曰：「狹音胡夾反。」","sentenceOrder":95},
  {"id":"s_work_han_thu_46_96","chapterId":"ch_work_han_thu_46","textTraditional":"〔六〕　師古曰：「諸君謂其酋豪。」","sentenceOrder":96},
  {"id":"s_work_han_thu_46_97","chapterId":"ch_work_han_thu_46","textTraditional":"〔七〕　如淳曰：「南越直長沙者，因王子定之。」師古曰：「直，當也。言越地之北，當長沙者也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_46_98","chapterId":"ch_work_han_thu_46","textTraditional":"〔八〕　如淳曰：「告東越，使定之也。」師古曰：「此說非也。言王子定長沙已北，而西趣蜀及漢中，平定以訖，使報南越也。走音奏。」","sentenceOrder":98},
  {"id":"s_work_han_thu_46_99","chapterId":"ch_work_han_thu_46","textTraditional":"〔九〕　師古曰：「淮南三王，謂厲王三子為王者，淮南、衡山、濟北也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_46_100","chapterId":"ch_work_han_thu_46","textTraditional":"〔一０〕師古曰：「臨晉關即今之蒲津關。」","sentenceOrder":100},
  {"id":"s_work_han_thu_46_101","chapterId":"ch_work_han_thu_46","textTraditional":"〔一一〕師古曰：「走音奏。」","sentenceOrder":101},
  {"id":"s_work_han_thu_46_102","chapterId":"ch_work_han_thu_46","textTraditional":"〔一二〕師古曰：「言心有所懷，志不在洗沐也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_46_103","chapterId":"ch_work_han_thu_46","textTraditional":"〔一三〕師古曰：「謂發兵。」","sentenceOrder":103},
  {"id":"s_work_han_thu_46_104","chapterId":"ch_work_han_thu_46","textTraditional":"〔一四〕師古曰：「為此謂欲反也。為音于偽反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_46_105","chapterId":"ch_work_han_thu_46","textTraditional":"〔一五〕師古曰：「以卒萬人或邑萬戶來降附者，其封賞則與大將同。下皆類此。」","sentenceOrder":105},
  {"id":"s_work_han_thu_46_106","chapterId":"ch_work_han_thu_46","textTraditional":"〔一六〕服虔曰：「封賜倍漢之常法。」","sentenceOrder":106},
  {"id":"s_work_han_thu_46_107","chapterId":"ch_work_han_thu_46","textTraditional":"〔一七〕師古曰：「於舊爵之外，特更與之。」","sentenceOrder":107},
  {"id":"s_work_han_thu_46_108","chapterId":"ch_work_han_thu_46","textTraditional":"〔一八〕師古曰：「言處處郡國皆有之。」","sentenceOrder":108},
  {"id":"s_work_han_thu_46_109","chapterId":"ch_work_han_thu_46","textTraditional":"七國反書聞，天子乃遣太尉條侯周亞夫將三十六將軍往擊吳楚；遣曲周侯酈寄擊趙，將軍欒布擊齊，大將軍竇嬰屯滎陽監齊趙兵。","sentenceOrder":109},
  {"id":"s_work_han_thu_46_110","chapterId":"ch_work_han_thu_46","textTraditional":"初，吳楚反書聞，兵未發，竇嬰言故吳相爰盎。召入見，上問以吳楚之計，盎對曰：「吳楚相遺書，曰『賊臣朝錯擅適諸侯，削奪之地』，〔一〕以故反，名為西共誅錯，復故地而罷。〔二〕方今計獨斬錯，發使赦七國，復其故地，則兵可毋血刃而俱罷。」〔三〕上從其議，遂斬錯。語具在盎傳。以盎為泰常，奉宗廟，使吳王，〔四〕吳王弟子德侯為宗正，〔五〕輔親戚。使至吳，〔六〕吳楚兵已攻梁壁矣。宗正以親故，先入見，諭吳王拜受詔。吳王聞盎來，亦知其欲說，笑而應曰：「我已為東帝，尚誰拜？」不肯見盎而留軍中，欲劫使將。盎不肯，使人圍守，且殺之。盎得夜亡走梁，〔七〕遂歸報。","sentenceOrder":110},
  {"id":"s_work_han_thu_46_111","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　師古曰：「適讀曰謫。」","sentenceOrder":111},
  {"id":"s_work_han_thu_46_112","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　師古曰：「復音扶目反。次下亦同。」","sentenceOrder":112},
  {"id":"s_work_han_thu_46_113","chapterId":"ch_work_han_thu_46","textTraditional":"〔三〕　師古曰：「血刃，謂殺傷人而刃著血也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_46_114","chapterId":"ch_work_han_thu_46","textTraditional":"〔四〕　師古曰：「奉宗廟之指意也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_46_115","chapterId":"ch_work_han_thu_46","textTraditional":"〔五〕　師古曰：「德哀侯廣之子也，名通。」","sentenceOrder":115},
  {"id":"s_work_han_thu_46_116","chapterId":"ch_work_han_thu_46","textTraditional":"〔六〕　師古曰：「以親戚之意諭說也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_46_117","chapterId":"ch_work_han_thu_46","textTraditional":"〔七〕　服虔曰：「梁王與吳戰，盎得奔梁。」","sentenceOrder":117},
  {"id":"s_work_han_thu_46_118","chapterId":"ch_work_han_thu_46","textTraditional":"條侯將乘六乘傳，會兵滎陽。〔一〕至雒陽，見劇孟，喜曰：「七國反，吾乘傳至此，不自意全。〔二〕又以為諸侯已得劇孟。孟今無動，吾據滎陽，〔三〕滎陽以東無足憂者。」至淮陽，問故父絳侯客鄧都尉曰：「策安出？」客曰：「吳（楚）兵銳甚，難與爭鋒。楚兵輕，不能久。方今為將軍計，莫若引兵東北壁昌邑，以梁委吳，吳必盡銳攻之。將軍深溝高壘，使輕兵絕淮泗口，塞吳饟道。〔四〕使吳、梁相敝而糧食竭，乃以全制其極，破吳必矣。」條侯曰：「善。」從其策，遂堅壁昌邑南，輕兵絕吳饟道。","sentenceOrder":118},
  {"id":"s_work_han_thu_46_119","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　師古曰：「會兵謂集大兵。傳音張戀反。」","sentenceOrder":119},
  {"id":"s_work_han_thu_46_120","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　師古曰：「意不自言得安全至雒陽也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_46_121","chapterId":"ch_work_han_thu_46","textTraditional":"〔三〕　師古曰：「言劇孟既不動搖，吾又得據滎陽也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_46_122","chapterId":"ch_work_han_thu_46","textTraditional":"〔四〕　師古曰：「饟，古餉字。」","sentenceOrder":122},
  {"id":"s_work_han_thu_46_123","chapterId":"ch_work_han_thu_46","textTraditional":"吳王之初發也，吳臣田祿伯為大將軍。田祿伯曰：「兵屯聚而西，無它奇道，難以立功。臣願得五萬人，別循江淮而上，收淮南、長沙，入武關，與大王會，此亦一奇也。」吳王太子諫曰：「王以反為名，此兵難以藉人，〔一〕人亦且反王，柰何？且擅兵而別，多它利害，〔二〕徒自損耳。」吳王即不許田祿伯。","sentenceOrder":123},
  {"id":"s_work_han_thu_46_124","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　師古曰：「藉，假也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_46_125","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　蘇林曰：「祿伯儻將兵降漢，自為己利，於吳為生患害。」師古曰：「蘇說非也。上言『難以藉人，人亦且反王』，是則已疑祿伯矣。下乃云『多它利害』，謂分兵而去，前事不測，或有利害，難可決機耳，非重云畏其降漢者。」","sentenceOrder":125},
  {"id":"s_work_han_thu_46_126","chapterId":"ch_work_han_thu_46","textTraditional":"吳少將桓將軍說王曰：「吳多步兵，步兵利險；漢多車騎，車騎利平地。願大王所過城不下，直去，疾西據雒陽武庫，食敖倉粟，阻山河之險以令諸侯，雖無入關，天下固已定矣。大王徐行，留下城邑，漢軍車騎至，馳入梁楚之郊，事敗矣。」吳王問吳老將，老將曰：「此年少（椎）〔推〕鋒可耳，安知大慮！」於是王不用桓將軍計。","sentenceOrder":126},
  {"id":"s_work_han_thu_46_127","chapterId":"ch_work_han_thu_46","textTraditional":"王專并將其兵，未度淮，諸賓客皆得為將、校尉、行間候、司馬，〔一〕獨周丘不用。周丘者，下邳人，亡命吳，酤酒無行，王薄之，不任。周丘乃上謁，說王曰：「臣以無能，不得待罪行間。臣非敢求有所將也，願請王一漢節，必有以報。」王乃予之。周丘得節，夜馳入下邳。下邳時聞吳反，皆城守。至傳舍，召令入戶，使從者以罪斬令。遂召昆弟所善豪吏告曰：「吳反兵且至，屠下邳不過食頃。今先下，家室必完，能者封侯至矣。」出乃相告，下邳皆下。周丘一夜得三萬人，使人報吳王，遂將其兵北略城邑。比至城陽，兵十餘萬，〔二〕破城陽中尉軍。聞吳王敗走，自度無與共成功，〔三〕即引兵歸下邳。未至，癰發背死。","sentenceOrder":127},
  {"id":"s_work_han_thu_46_128","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　孟康曰：「行伍間候也。」師古曰：「在行伍間，或為候，或為司馬也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_46_129","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　師古曰：「比音必寐反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_46_130","chapterId":"ch_work_han_thu_46","textTraditional":"〔三〕　師古曰：「度音大各反。」","sentenceOrder":130},
  {"id":"s_work_han_thu_46_131","chapterId":"ch_work_han_thu_46","textTraditional":"二月，吳王兵既破，敗走，於是天子制詔將軍：「蓋聞為善者天報以福，為非者天報以殃。高皇帝親垂功德，建立諸侯，幽王、悼惠王絕無後，孝文皇帝哀憐加惠，〔一〕王幽王子遂，悼惠王子卬等，令奉其先王宗廟，為漢藩國，德配天地，明並日月。而吳王濞背德反義，誘受天下亡命罪人，亂天下幣，〔二〕稱疾不朝二十餘年。有司數請濞罪，孝文皇帝寬之，欲其改行為善。今乃與楚王戊、趙王遂、膠西王卬、濟南王辟光、菑川王賢、膠東王雄渠約從謀反，〔三〕為逆無道，起兵以危宗廟，賊殺大臣及漢使者，迫劫萬民，伐殺無罪，燒殘民家，掘其丘壟，甚為虐暴。而卬等又重逆無道，〔四〕燒宗廟，鹵御物，〔五〕朕甚痛之。朕素服避正殿，將軍其勸士大夫擊反虜。擊反虜者，深入多殺為功，斬首捕虜比三百石以上皆殺，無有所置。〔六〕敢有議詔及不如詔者，皆要斬。」","sentenceOrder":131},
  {"id":"s_work_han_thu_46_132","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　師古曰：「憐其國絕，故加恩惠而更封。」","sentenceOrder":132},
  {"id":"s_work_han_thu_46_133","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　如淳曰：「幣，錢也。以私錢殽亂天下錢。」","sentenceOrder":133},
  {"id":"s_work_han_thu_46_134","chapterId":"ch_work_han_thu_46","textTraditional":"〔三〕　師古曰：「從音子容反。」","sentenceOrder":134},
  {"id":"s_work_han_thu_46_135","chapterId":"ch_work_han_thu_46","textTraditional":"〔四〕　師古曰：「重音直用反。」","sentenceOrder":135},
  {"id":"s_work_han_thu_46_136","chapterId":"ch_work_han_thu_46","textTraditional":"〔五〕　如淳曰：「鹵，抄掠也。」師古曰：「御物，供宗廟之服器也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_46_137","chapterId":"ch_work_han_thu_46","textTraditional":"〔六〕　師古曰：「置，放釋也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_46_138","chapterId":"ch_work_han_thu_46","textTraditional":"初，吳王之度淮，與楚王遂西敗棘壁，乘勝而前，銳甚。梁孝王恐，遣將軍擊之，又敗梁兩軍，士卒皆還走。梁數使使條侯求救，條侯不許。又使使愬條侯於上，上使告條侯救梁，又守便宜不行。梁使韓安國及楚死事相弟張羽為將軍，〔一〕乃得頗敗吳兵。吳兵欲西，梁城守，不敢西，即走條侯軍，〔二〕會下邑。欲戰，〔三〕條侯壁，不肯戰。吳糧絕，卒飢，數挑戰，遂夜奔條侯壁，驚東南。條侯使備西北，果從西北。不得入，吳大敗，士卒多飢死叛散。於是吳王乃與其戲下壯士千人夜亡去，〔四〕度淮走丹徒，保東越。東越兵可萬餘人，使人收聚亡卒。漢使人以利啗東越，〔五〕東越即紿吳王〔六〕，吳王出勞軍，使人鏦殺吳王，〔七〕盛其頭，馳傳以聞。〔八〕吳王太子駒亡走閩越。吳王之棄軍亡也，軍遂潰，往往稍降太尉條侯及梁軍。楚王戊軍敗，自殺。","sentenceOrder":138},
  {"id":"s_work_han_thu_46_139","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　李奇曰：「相，即張尚也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_46_140","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　師古曰：「走音奏。」","sentenceOrder":140},
  {"id":"s_work_han_thu_46_141","chapterId":"ch_work_han_thu_46","textTraditional":"〔三〕　師古曰：「下邑，梁之縣。」","sentenceOrder":141},
  {"id":"s_work_han_thu_46_142","chapterId":"ch_work_han_thu_46","textTraditional":"〔四〕　師古曰：「戲讀曰麾，又音許宜反。」","sentenceOrder":142},
  {"id":"s_work_han_thu_46_143","chapterId":"ch_work_han_thu_46","textTraditional":"〔五〕　師古曰：「啗音徒濫反。解在高紀。」","sentenceOrder":143},
  {"id":"s_work_han_thu_46_144","chapterId":"ch_work_han_thu_46","textTraditional":"〔六〕　師古曰：「紿，誑也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_46_145","chapterId":"ch_work_han_thu_46","textTraditional":"〔七〕　孟康曰：「方言戟謂之鏦。」蘇林曰：「鏦音從容之從。」師古曰：「鏦謂以矛戟撞之，音楚江反。」","sentenceOrder":145},
  {"id":"s_work_han_thu_46_146","chapterId":"ch_work_han_thu_46","textTraditional":"〔八〕　師古曰：「傳音張戀反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_46_147","chapterId":"ch_work_han_thu_46","textTraditional":"三王之圍齊臨菑也，三月不能下。漢兵至，膠西、膠東、菑川王各引兵歸國。膠西王徒跣，席稿，飲水，謝太后。王太子德曰：「漢兵還，臣觀之以罷，〔一〕可襲，願收王餘兵擊之，不勝而逃入海，未晚也。」王曰：「吾士卒皆已壞，不可用。」不聽。漢將弓高侯頹當遺王書〔二〕曰：「奉詔誅不義，降者赦，除其罪，復故；不降者滅之。王何處？須以從事。」〔三〕王肉袒叩頭漢軍壁，謁曰：「臣卬奉法不謹，驚駭百姓，乃苦將軍遠道至于窮國，敢請葅醢之罪。」弓高侯執金鼓見之，曰：「王苦軍事，願聞王發兵狀。」王頓首膝行對曰：「今者，朝錯天子用事臣，變更高皇帝法令，侵奪諸侯地。卬等以為不義，恐其敗亂天下，七國發兵，且以誅錯。今聞錯已誅，卬等謹已罷兵歸。」將軍曰：「王苟以錯為不善，何不以聞？及未有詔虎符，擅發兵擊義國。以此觀之，意非徒欲誅錯也。」乃出詔書為王讀之，曰：「王其自圖之。」〔四〕王曰：「如卬等死有餘罪。」遂自殺。太后、太子皆死。膠東、菑川、濟南王皆伏誅。酈將軍攻趙，十月而下之，趙王自殺。濟北王以劫故，不誅。","sentenceOrder":147},
  {"id":"s_work_han_thu_46_148","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　師古曰：「罷讀曰疲。」","sentenceOrder":148},
  {"id":"s_work_han_thu_46_149","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　師古曰：「韓頹當。」","sentenceOrder":149},
  {"id":"s_work_han_thu_46_150","chapterId":"ch_work_han_thu_46","textTraditional":"〔三〕　師古曰：「言王欲以何理自安處，吾待以行事也。處音昌汝反。」","sentenceOrder":150},
  {"id":"s_work_han_thu_46_151","chapterId":"ch_work_han_thu_46","textTraditional":"〔四〕　師古曰：「圖，謀也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_46_152","chapterId":"ch_work_han_thu_46","textTraditional":"初，吳王首反，并將楚兵，連齊、趙。正月起，三月皆破滅。","sentenceOrder":152},
  {"id":"s_work_han_thu_46_153","chapterId":"ch_work_han_thu_46","textTraditional":"贊曰：荊王王也，由漢初定，天下未集，〔一〕故雖疏屬，以策為王，鎮江淮之間。劉澤發於田生，權激呂氏，〔二〕然卒南面稱孤者三世。事發相重，豈不危哉！〔三〕吳王擅山海之利，能薄斂以使其眾，逆亂之萌，自其子興。〔四〕古者諸侯不過百里，山海不以封，蓋防此矣。朝錯為國遠慮，禍反及身。「毋為權首，將受其咎」，豈謂錯哉！〔五〕","sentenceOrder":153},
  {"id":"s_work_han_thu_46_154","chapterId":"ch_work_han_thu_46","textTraditional":"〔一〕　師古曰：「集，和也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_46_155","chapterId":"ch_work_han_thu_46","textTraditional":"〔二〕　晉灼曰：「田生欲王劉澤，先使張卿說封呂產，恐其大臣觖望，澤卒得王，故云以權激呂氏也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_46_156","chapterId":"ch_work_han_thu_46","textTraditional":"〔三〕　晉灼曰：「劉澤以金與田生，以事張卿，言之呂后，而劉澤得王，故曰事發相重也。」師古曰：「重猶累也。言澤得王，本由田生行說，若其事發覺，則相隨入罪，事相累誤。累音力瑞反。」","sentenceOrder":156},
  {"id":"s_work_han_thu_46_157","chapterId":"ch_work_han_thu_46","textTraditional":"〔四〕　師古曰：「萌謂始生也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_46_158","chapterId":"ch_work_han_thu_46","textTraditional":"〔五〕　師古曰：「此逸周書之言，贊引之者，謂錯適當此言耳。」","sentenceOrder":158},
  {"id":"s_work_han_thu_46_159","chapterId":"ch_work_han_thu_46","textTraditional":"校勘記","sentenceOrder":159},
  {"id":"s_work_han_thu_46_160","chapterId":"ch_work_han_thu_46","textTraditional":"一九０一頁　五行（呂）〔太〕后又重發之，　王先謙說「呂后」駁文，當作「太后」。按殿本作「太后」。","sentenceOrder":160},
  {"id":"s_work_han_thu_46_161","chapterId":"ch_work_han_thu_46","textTraditional":"一九０一頁　七行　不急發，恐（過）〔禍〕及身矣。　景祐、殿本都作「禍」。王先謙說作「禍」是，史記同。","sentenceOrder":161},
  {"id":"s_work_han_thu_46_162","chapterId":"ch_work_han_thu_46","textTraditional":"一九０五頁　一行　（反）〔及〕覺，　景祐、殿本都作「及」。王先謙說作「及」是。","sentenceOrder":162},
  {"id":"s_work_han_thu_46_163","chapterId":"ch_work_han_thu_46","textTraditional":"一九一三頁　四行　吳（楚）兵銳甚，　王先慎說「楚」字衍文，史記無「楚」字。","sentenceOrder":163},
  {"id":"s_work_han_thu_46_164","chapterId":"ch_work_han_thu_46","textTraditional":"一九一四頁　六行　此年少（椎）〔推〕鋒可耳，　景祐、殿本都作「推」。王先謙說作「推」是，史記亦作「推」。","sentenceOrder":164},
  {"id":"s_work_han_thu_47_1","chapterId":"ch_work_han_thu_47","textTraditional":"楚元王交字游，高祖同父少弟也。〔一〕好書，多材藝。少時嘗與魯穆生、白生、申公俱受詩於浮丘伯。〔二〕伯者，孫卿門人也。〔三〕及秦焚書，各別去。","sentenceOrder":1},
  {"id":"s_work_han_thu_47_2","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「言同父，知其異母。」","sentenceOrder":2},
  {"id":"s_work_han_thu_47_3","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　服虔曰：「白生，魯國奄里人。浮丘伯，秦時儒生。」","sentenceOrder":3},
  {"id":"s_work_han_thu_47_4","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「孫卿姓荀名況，為楚蘭陵令，漢以避宣帝諱，改之曰孫。」","sentenceOrder":4},
  {"id":"s_work_han_thu_47_5","chapterId":"ch_work_han_thu_47","textTraditional":"高祖兄弟四人，長兄伯，次仲，伯蚤卒。〔一〕高祖既為沛公，景駒自立為楚王。高祖使仲與審食其留侍太上皇，〔二〕交與蕭、曹等俱從高祖見景駒，遇項梁，共立楚懷王。因西攻南陽，入武關，與秦戰於藍田。至霸上，封交為文信君，從入蜀漢，還定三秦，誅項籍。即帝位，交與盧綰常侍上，出入臥內，傳言語諸內事隱謀。而上從父兄劉賈數別將。","sentenceOrder":5},
  {"id":"s_work_han_thu_47_6","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「蚤，古早字也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_47_7","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「食音異。其音基。」","sentenceOrder":7},
  {"id":"s_work_han_thu_47_8","chapterId":"ch_work_han_thu_47","textTraditional":"漢六年，既廢楚王信，分其地為二國，立賈為荊王，交為楚王，王薛郡、東海、彭城三十六縣，先有功也。後封次兄仲為代王，長子肥為齊王。","sentenceOrder":8},
  {"id":"s_work_han_thu_47_9","chapterId":"ch_work_han_thu_47","textTraditional":"初，高祖微時，常避事，時時與賓客過其丘嫂食。〔一〕嫂厭叔與客來，陽為羹盡，轑釜，〔二〕客以故去。已而視釜中有羹，繇是怨嫂。〔三〕及立齊、代王，而伯子獨不得侯。太上皇以為言，高祖曰：「某非敢忘封之也，為其母不長者。」七年十月，封其子信為羹頡侯。〔四〕","sentenceOrder":9},
  {"id":"s_work_han_thu_47_10","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　應劭曰：「丘，姓也。」孟康曰：「西方謂亡女婿為丘婿。丘，空也，兄亡空有嫂也。」張晏曰：「丘，大也，長嫂稱也。」晉灼曰：「禮謂大婦為冢婦。」師古曰：「史記丘字作巨。丘、巨皆大也。張、晉二說，其義得之。」","sentenceOrder":10},
  {"id":"s_work_han_thu_47_11","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　服虔曰：「音勞。轑，轢也。」師古曰：「以勺轢釜，令為聲也。轢音洛，又音歷。」","sentenceOrder":11},
  {"id":"s_work_han_thu_47_12","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「繇與由同。」","sentenceOrder":12},
  {"id":"s_work_han_thu_47_13","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「頡音戛。言其母戛羹釜也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_47_14","chapterId":"ch_work_han_thu_47","textTraditional":"元王既至楚，以穆生、白生、申公為中大夫。高后時，浮丘伯在長安，元王遣子郢客與申公俱卒業。〔一〕文帝時，聞申公為詩最精，以為博士。元王好詩，諸子皆讀詩，申公始為詩傳，號魯詩。〔二〕元王亦次之詩傳，號曰元王詩，〔三〕世或有之。","sentenceOrder":14},
  {"id":"s_work_han_thu_47_15","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「卒，終也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_47_16","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「凡言傳者，謂為之解說，若今詩毛氏傳也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_47_17","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「次謂綴集之。」","sentenceOrder":17},
  {"id":"s_work_han_thu_47_18","chapterId":"ch_work_han_thu_47","textTraditional":"高后時，以元王子郢客為宗正，封上邳侯。元王立二十三年薨，太子辟非先卒，〔一〕文帝乃以宗正上邳侯郢客嗣，是為夷王。申公為博士，失官，隨郢客歸，復以為中大夫。立四年薨，子戊嗣。文帝尊寵元王，子生，爵比皇子。〔二〕景帝即位，以親親封元王寵子五人：子禮為平陸侯，富為休侯，歲為沈猶侯，〔三〕埶為宛朐侯〔四〕，調為棘樂侯。","sentenceOrder":18},
  {"id":"s_work_han_thu_47_19","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「辟非者，猶辟邪辟兵之類也。先卒者，元王未薨之時已卒也。辟音壁。」","sentenceOrder":19},
  {"id":"s_work_han_thu_47_20","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「元王生子，封爵皆與皇子同，所以尊寵元王也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_47_21","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　晉灼曰：「沈音審。王子侯表屬千乘高宛。」","sentenceOrder":21},
  {"id":"s_work_han_thu_47_22","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「埶，古藝字。」","sentenceOrder":22},
  {"id":"s_work_han_thu_47_23","chapterId":"ch_work_han_thu_47","textTraditional":"初，元王敬禮申公等，穆生不耆酒，〔一〕元王每置酒，常為穆生設醴。〔二〕及王戊即位，常設，後忘設焉。穆生退曰：「可以逝矣！醴酒不設，王之意怠，不去，楚人將鉗我於市。」〔三〕稱疾臥。申公、白生強起之曰：「獨不念先王之德與？〔四〕今王一旦失小禮，何足至此！」穆生曰：「易稱『知幾其神乎！〔五〕幾者動之微，吉凶之先見者也。〔六〕君子見幾而作，不俟終日。』先王之所以禮吾三人者，為道之存故也；今而忽之，是忘道也。〔七〕忘道之人，胡可與久處！豈為區區之禮哉？」〔八〕遂謝病去。申公、白生獨留。","sentenceOrder":23},
  {"id":"s_work_han_thu_47_24","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「耆讀曰嗜。」","sentenceOrder":24},
  {"id":"s_work_han_thu_47_25","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「醴，甘酒也。少麴多米，一宿而熟，不齊之。」","sentenceOrder":25},
  {"id":"s_work_han_thu_47_26","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「鉗，以鐵束頸也，音其炎反。」","sentenceOrder":26},
  {"id":"s_work_han_thu_47_27","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「與讀曰歟。」","sentenceOrder":27},
  {"id":"s_work_han_thu_47_28","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「下繫之辭也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_47_29","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「見音胡電反。」","sentenceOrder":29},
  {"id":"s_work_han_thu_47_30","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　師古曰：「忽，怠也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_47_31","chapterId":"ch_work_han_thu_47","textTraditional":"〔八〕　師古曰：「區區，謂小也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_47_32","chapterId":"ch_work_han_thu_47","textTraditional":"王戊稍淫暴，二十年，為薄太后服私姦，削東海、薛郡，乃與吳通謀。二人諫，不聽，胥靡之，〔一〕衣之赭衣，使杵臼雅舂於市。〔二〕休侯使人諫王，王曰：「季父不吾與，我起，先取季父矣。」〔三〕休侯懼，乃與母太夫人奔京師。〔四〕二十一年春，景帝之三年也，削書到，遂應吳王反。其相張尚、太傅趙夷吾諫，不聽。遂殺尚、夷吾，起兵會吳西攻梁，破棘壁，至昌邑南，與漢將周亞夫戰。漢絕吳楚糧道，士饑，吳王走，戊自殺，軍遂降漢。","sentenceOrder":32},
  {"id":"s_work_han_thu_47_33","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　應劭曰：「詩云『若此無罪，淪胥以鋪』。胥靡，刑名也。」晉灼曰：「胥，相也。靡，隨也。古者相隨坐輕刑之名。」師古曰：「聯繫使相隨而服役之，故謂之胥靡，猶今之役囚徒以鎖聯綴耳。晉說近之，而云隨坐輕刑，非也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_47_34","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　晉灼曰：「高肱舉杵，正身而舂之。」師古曰：「為木杵而手舂，即今所謂步臼者耳，非碓臼也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_47_35","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰；「不吾與，言不與我同心。」","sentenceOrder":35},
  {"id":"s_work_han_thu_47_36","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　臣瓚曰：「侯母號太夫人。」","sentenceOrder":36},
  {"id":"s_work_han_thu_47_37","chapterId":"ch_work_han_thu_47","textTraditional":"漢已平吳楚，景帝乃立宗正平陸侯禮為楚王，奉元王後，是為文王。四年薨，子安王道嗣。二十二年薨，子襄王注嗣。十四年薨，子節王純嗣。十六年薨，子延壽嗣。宣帝即位，延壽以為廣陵王胥武帝子，天下有變必得立，陰欲附倚輔助之，〔一〕故為其（後）〔后〕母弟趙何齊取廣陵王女為妻。與何齊謀曰：「我與廣陵王相結，天下不安，發兵助之，使廣陵王立，何齊尚公主，列侯可得也。」因使何齊奉書遺廣陵王曰：「願長耳目，〔二〕毋後人有天下。」〔三〕何齊父長年上書告之。事下有司，考驗辭服，延壽自殺。立三十二年，國除。","sentenceOrder":37},
  {"id":"s_work_han_thu_47_38","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「倚，依也。音於綺反。」","sentenceOrder":38},
  {"id":"s_work_han_thu_47_39","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「言常伺聽，勿失機也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_47_40","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「方爭天下，勿使在人後。」","sentenceOrder":40},
  {"id":"s_work_han_thu_47_41","chapterId":"ch_work_han_thu_47","textTraditional":"初，休侯富既奔京師，而王戊反，富等皆坐免侯，削屬籍。後聞其數諫戊，乃更封為紅侯。太夫人與竇太后有親，懲山東之寇，〔一〕求留京師，詔許之。富子辟彊等四人〔二〕供養，仕於朝。〔三〕太夫人薨，賜塋，〔四〕葬靈戶。〔五〕富傳國至曾孫，無子，絕。","sentenceOrder":41},
  {"id":"s_work_han_thu_47_42","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「懲，創也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_47_43","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「辟音必亦反。彊音居良反。又辟讀曰闢，彊讀曰疆。解在文紀。」","sentenceOrder":43},
  {"id":"s_work_han_thu_47_44","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「四子以在京師供養其祖母，故仕於漢朝也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_47_45","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「塋，冢地，謂為界域。塋音營。」","sentenceOrder":45},
  {"id":"s_work_han_thu_47_46","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「地名也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_47_47","chapterId":"ch_work_han_thu_47","textTraditional":"辟彊字少卿，亦好讀詩，能屬文。〔一〕武帝時，以宗室子隨二千石論議，冠諸宗室。〔二〕清靜少欲，常以書自娛，不肯仕。昭帝即位，或說大將軍霍光曰：「將軍不見諸呂之事乎？處伊尹、周公之位，攝政擅權，而背宗室，不與共職，是以天下不信，卒至於滅亡。今將軍當盛位，帝春秋富，宜納宗室，又多與大臣共事，〔三〕反諸呂道，如是則可以免患。」〔四〕光然之，乃擇宗室可用者。辟彊子德待詔丞相府，〔五〕年三十餘，欲用之。或言父見在，亦先帝之所寵也。遂拜辟彊為光祿大夫，守長樂衛尉，時年已八十矣。徙為宗正，數月卒。","sentenceOrder":47},
  {"id":"s_work_han_thu_47_48","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「屬文，謂會綴文辭也，音之欲反。後皆類此。」","sentenceOrder":48},
  {"id":"s_work_han_thu_47_49","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「論議每出宗室之上也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_47_50","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　服虔曰：「共議事也。」師古曰：「每事皆與參共知之。」","sentenceOrder":50},
  {"id":"s_work_han_thu_47_51","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「言諸呂專權，所以滅亡，今納宗室，是反其道，乃可免患也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_47_52","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「於丞相府聽詔命也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_47_53","chapterId":"ch_work_han_thu_47","textTraditional":"德字路叔（少），修黃老術，有智略。少時數言事，召見甘泉宮，武帝謂之「千里駒」。〔一〕昭帝初，為宗正丞，雜治劉澤詔獄。〔二〕父為宗正，徙大鴻臚丞，遷太中大夫，後復為宗正，雜案上官氏、蓋主事。德常持老子知足之計。〔三〕妻死，大將軍光欲以女妻之，德不敢取，畏盛滿也。蓋長公主孫譚遮德自言，〔四〕德數責以公主起居無狀。〔五〕侍御史以為光望不受女，〔六〕承指劾德誹謗詔獄，〔七〕免為庶人，屏居山田。光聞而恨之，〔八〕復白召德守青州刺史。歲餘，復為宗正，與立宣帝，〔九〕以定策賜爵關內侯。地節中，以親親行謹厚封為陽城侯。子安民為郎中右曹，宗家以德得官宿衛者二十餘人。","sentenceOrder":53},
  {"id":"s_work_han_thu_47_54","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「言若駿馬可致千里也。年齒幼少，故謂之駒。」","sentenceOrder":54},
  {"id":"s_work_han_thu_47_55","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「雜謂以他官共治之也。劉澤，齊孝王之孫，謀反欲殺青州刺史者。」","sentenceOrder":55},
  {"id":"s_work_han_thu_47_56","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「老子德經云『知足不辱』。」","sentenceOrder":56},
  {"id":"s_work_han_thu_47_57","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「公主之孫名譚，自言者，申理公主所坐。」","sentenceOrder":57},
  {"id":"s_work_han_thu_47_58","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「無狀，無善狀也。數音所具反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_47_59","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「望，怨望也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_47_60","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　師古曰：「承指，謂取霍光之意指，德實責數公主，而御史乃以為受譚冤訴，故云誹謗詔獄。」","sentenceOrder":60},
  {"id":"s_work_han_thu_47_61","chapterId":"ch_work_han_thu_47","textTraditional":"〔八〕　師古曰：「以御史不知己意。」","sentenceOrder":61},
  {"id":"s_work_han_thu_47_62","chapterId":"ch_work_han_thu_47","textTraditional":"〔九〕　師古曰：「與讀曰豫。豫其謀議也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_47_63","chapterId":"ch_work_han_thu_47","textTraditional":"德寬厚，好施生，〔一〕每行京兆尹事，多所平反罪人。〔二〕家產過百萬，則以振昆弟〔三〕賓客食飲，〔四〕曰：「富，民之怨也。」立十一年，子向坐鑄偽黃金，當伏法，〔五〕德上書訟罪。會薨，大鴻臚奏德訟子罪，失大臣體，不宜賜諡置嗣。制曰：「賜諡繆侯，〔六〕為置嗣。」傳至孫慶忌，復為宗正太常。薨，子岑嗣，為諸曹中郎將，列校尉，至太常。薨，傳子，至王莽敗，乃絕。","sentenceOrder":63},
  {"id":"s_work_han_thu_47_64","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「言好施恩惠於人，而生全之。」","sentenceOrder":64},
  {"id":"s_work_han_thu_47_65","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　蘇林曰：「反音幡，幡罪人辭使從輕也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_47_66","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「振，舉救之。」","sentenceOrder":66},
  {"id":"s_work_han_thu_47_67","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「既以救貧昆弟，又散供食飲之費。」","sentenceOrder":67},
  {"id":"s_work_han_thu_47_68","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　如淳曰：「律，鑄偽黃金棄市也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_47_69","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「繆，惡諡也，以其妄訟子。」","sentenceOrder":69},
  {"id":"s_work_han_thu_47_70","chapterId":"ch_work_han_thu_47","textTraditional":"向字子政，〔一〕本名更生。年十二，以父德任為輦郎。〔二〕既冠，以行修飭擢為諫大夫。〔三〕是時，宣帝循武帝故事，招選名儒俊材置左右。更生以通達能屬文辭，與王褒、張子僑等並進對〔四〕，獻賦頌凡數十篇。上復興神僊方術之事，而淮南有枕中鴻寶苑秘書。〔五〕書言神僊使鬼物為金之術，及鄒衍重道延命方，世人莫見，而更生父德武帝時治淮南獄得其書。更生幼而讀誦，以為奇，獻之，言黃金可成。上令典尚方鑄作事，〔六〕費甚多，方不驗。上乃下更生吏，吏劾更生鑄偽黃金，繫當死。更生兄陽城侯安民上書，入國戶半，贖更生罪。上亦奇其材，得踰冬減死論。〔七〕會初立穀梁春秋，徵更生受穀梁，講論五經於石渠。〔八〕復拜為郎中給事黃門，遷散騎諫大夫給事中。","sentenceOrder":70},
  {"id":"s_work_han_thu_47_71","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「名向，字子政。義則相配，而近代學者讀向音餉，既無別釋，靡所據憑，當依本字為勝也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_47_72","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　服虔曰：「父保任其子為郎也。輦郎，如今引御輦郎也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_47_73","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「飭，整也，讀與敕同，其字從力。」","sentenceOrder":73},
  {"id":"s_work_han_thu_47_74","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「子僑官至光祿大夫，見藝文志。進對，謂進見而對詔命也。僑字或作蟜，或作喬，皆音鉅驕反。」","sentenceOrder":74},
  {"id":"s_work_han_thu_47_75","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「鴻寶苑祕書，並道術篇名。臧在枕中，言常存錄之不漏泄也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_47_76","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「尚方，主巧作金銀之所。若今之中尚署。」","sentenceOrder":76},
  {"id":"s_work_han_thu_47_77","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　服虔曰：「踰冬，至春行寬大而減死罪。」如淳曰：「獄冬盡當決竟，而得踰冬，復至後冬，故或逢赦，或得減死也。」師古曰：「服說是也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_47_78","chapterId":"ch_work_han_thu_47","textTraditional":"〔八〕　師古曰：「三輔舊事云石渠閣在未央大殿北，以藏祕書。」","sentenceOrder":78},
  {"id":"s_work_han_thu_47_79","chapterId":"ch_work_han_thu_47","textTraditional":"元帝初即位，太傅蕭望之為前將軍，少傅周堪為諸吏光祿大夫，〔一〕皆領尚書事，甚見尊任。更生年少於望之、堪，然二人重之，薦更生宗室忠直，明經有行，擢為散騎宗正給事中，與侍中金敞拾遺於左右。四人同心輔政，患苦外戚許、史在位放縱，而中書宦官弘恭、石顯弄權。望之、堪、更生議，欲白罷退之。未白而語泄，遂為許、史及恭、顯所譖愬，堪、更生下獄，及望之皆免官。語在望之傳。其春地震，夏，客星見昴、卷舌間。〔二〕上感悟，下詔賜望之爵關內侯，奉朝請。秋，徵堪、向，欲以為諫大夫，恭、顯白皆為中郎。冬，地復震。時恭、顯、許、史子弟侍中諸曹，皆側目於望之等，更生懼焉，乃使其外親上變事，〔三〕言：","sentenceOrder":79},
  {"id":"s_work_han_thu_47_80","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「加官也。百官公卿表云諸吏所加或列侯、將軍、卿大夫，得舉不法也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_47_81","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「見於昴與卷舌之間也。卷音俱免反。」","sentenceOrder":81},
  {"id":"s_work_han_thu_47_82","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「非常之事，故謂之變也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_47_83","chapterId":"ch_work_han_thu_47","textTraditional":"竊聞故前將軍蕭望之等，皆忠正無私，欲致大治，忤於貴戚尚書。〔一〕今道路人聞望之等復進，以為且復見毀讒，必曰嘗有過之臣不宜復用，是大不然。〔二〕臣聞春秋地震，為在位執政太盛也，不為三獨夫動，亦已明矣。〔三〕且往者高皇帝時，季布有罪，至於夷滅，後赦以為將軍，高后、孝文之間卒為名臣。〔四〕孝武帝時兒寬有重罪繫，按道侯韓說諫曰：〔五〕「前吾丘壽王死，陛下至今恨之；〔六〕今殺寬，後將復大恨矣！」上感其言，遂貰寬，〔七〕復用之，位至御史大夫，御史大夫未有及寬者也。又董仲舒坐私為災異書，主父偃取奏之，下吏，罪至不道，幸蒙不誅，復為太中大夫，膠西相，以老病免歸。漢有所欲興，常有詔問。〔八〕仲舒為世儒宗，定議有益天下。孝宣皇帝時，夏侯勝坐誹謗繫獄，三年免為庶人。宣帝復用勝，至長信少府，太子太傅，名敢直言，天下美之。若乃群臣，多此比類，難一二記。〔九〕有過之臣，無負國家，有益天下，此四臣者，足以觀矣。","sentenceOrder":83},
  {"id":"s_work_han_thu_47_84","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「忤猶逆也，音五故反。他皆類此。」","sentenceOrder":84},
  {"id":"s_work_han_thu_47_85","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「言不宜用有過之臣者，此議非也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_47_86","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　應劭曰：「謂蕭望之、周堪及向。」師古曰：「獨夫猶言匹夫也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_47_87","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「卒，終也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_47_88","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「說讀曰悅。」","sentenceOrder":88},
  {"id":"s_work_han_thu_47_89","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「恨猶悔也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_47_90","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　師古曰：「貰謂緩恕其罪也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_47_91","chapterId":"ch_work_han_thu_47","textTraditional":"〔八〕　師古曰：「興謂改作（慮）〔憲〕章。」","sentenceOrder":91},
  {"id":"s_work_han_thu_47_92","chapterId":"ch_work_han_thu_47","textTraditional":"〔九〕　師古曰：「比音必寐反。」","sentenceOrder":92},
  {"id":"s_work_han_thu_47_93","chapterId":"ch_work_han_thu_47","textTraditional":"前弘恭奏望之等獄決，三月，地大震。恭移病出，〔一〕後復視事，天陰雨雪。〔二〕由是言之，地動殆為恭等。〔三〕","sentenceOrder":93},
  {"id":"s_work_han_thu_47_94","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「移病者，移書言病也，一曰言以病移出，不居官府。」","sentenceOrder":94},
  {"id":"s_work_han_thu_47_95","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「雨音于具反。」","sentenceOrder":95},
  {"id":"s_work_han_thu_47_96","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「殆，近也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_47_97","chapterId":"ch_work_han_thu_47","textTraditional":"臣愚以為宜退恭、顯以章蔽善之罰，〔一〕進望之等以通賢者之路。如此，太平之門開，災異之原塞矣。","sentenceOrder":97},
  {"id":"s_work_han_thu_47_98","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「章，明也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_47_99","chapterId":"ch_work_han_thu_47","textTraditional":"書奏，恭、顯疑其更生所為，白請考姦詐。辭果服，遂逮更生繫獄，下太傅韋玄成、諫大夫貢禹，與廷尉雜考。劾更生前為九卿，坐與望之、堪謀排車騎將軍高、許、史氏侍中者，毀離親戚，欲退去之，而獨專權。為臣不忠，幸不伏誅，復蒙恩徵用，不悔前過，而教令人言變事，誣罔不道。更生坐免為庶人。而望之亦坐使子上書自冤前事，恭、顯白令詣獄置對。〔一〕望之自殺。天子甚悼恨之，乃擢周堪為光祿勳，堪弟子張猛光祿大夫給事中，大見信任。恭、顯憚之，數譖毀焉。更生見堪、猛在位，幾己得復進，〔二〕懼其傾危，乃上封事諫曰：","sentenceOrder":99},
  {"id":"s_work_han_thu_47_100","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「置對者，立為對辭。」","sentenceOrder":100},
  {"id":"s_work_han_thu_47_101","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「幾讀曰冀。」","sentenceOrder":101},
  {"id":"s_work_han_thu_47_102","chapterId":"ch_work_han_thu_47","textTraditional":"臣前幸得以骨肉備九卿，奉法不謹，乃復蒙恩。竊見災異並起，天地失常，徵表為國。〔一〕欲終不言，念忠臣雖在甽畝，猶不忘君，惓惓之義也。〔二〕況重以骨肉之親，〔三〕又加以舊恩未報乎！欲竭愚誠，又恐越職，然惟二恩未報，〔四〕忠臣之義，一杼愚意，退就農畝，死無所恨。〔五〕","sentenceOrder":102},
  {"id":"s_work_han_thu_47_103","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「徵，證也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_47_104","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「甽者，田中之溝也。田溝之法，耜廣五寸，二耜為耦，一耦之伐，廣尺深尺，謂之甽，六甽而為一畝。甽音工犬反，字或作畎，其音同耳。惓惓、忠謹之意。惓讀與拳同，音其專反。禮記曰『得一善則拳拳服膺，弗失之矣』。」","sentenceOrder":104},
  {"id":"s_work_han_thu_47_105","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「重音直用反。」","sentenceOrder":105},
  {"id":"s_work_han_thu_47_106","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「惟，思也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_47_107","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「杼謂引而泄之也。音食汝反。」","sentenceOrder":107},
  {"id":"s_work_han_thu_47_108","chapterId":"ch_work_han_thu_47","textTraditional":"臣聞舜命九官，〔一〕濟濟相讓，和之至也。眾賢和於朝，則萬物和於野。故簫韶九成，而鳳皇來儀；擊石拊石，百獸率舞〔二〕。四海之內，靡不和寧。及至周文，開基西郊，〔三〕雜遝眾賢，罔不肅和，〔四〕崇推讓之風，以銷分爭之訟。文王既沒，周公思慕，歌詠文王之德，其詩曰：「於穆清廟，肅雍顯相；濟濟多士，秉文之德。」〔五〕當此之時，武王、周公繼政，朝臣和於內，萬國驩於外，故盡得其驩心，以事其先祖。其詩曰：「有來雍雍，至止肅肅，相維辟公，天子穆穆。」〔六〕言四方皆以和來也。諸侯和於下，天應報於上，故周頌曰「降福穰穰」，〔七〕又曰「飴我釐麰」。〔八〕釐麰，麥也，始自天降。此皆以和致和，獲天助也。","sentenceOrder":108},
  {"id":"s_work_han_thu_47_109","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「尚書禹作司空，棄后稷，契司徒，咎繇作士，垂共工，（作）〔益〕朕虞，伯夷秩宗，夔典樂，龍納言，凡九官也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_47_110","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「詔，舜樂名。舉簫管之屬，示其備也。於韶樂九奏則鳳皇見其容儀，擊鍾鳴磬而百獸相率來舞，言感至和也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_47_111","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「言文王始受命作周也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_47_112","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「雜遝，聚積之貌，遝音大合反。」","sentenceOrder":112},
  {"id":"s_work_han_thu_47_113","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「此周頌祀文王清廟之詩也。於，歎辭也。穆，美也。肅，敬也。雍，和也。顯，明也。相，助也。濟濟，盛也。言文王有清淨之化，敬而且和，光明著見，故濟濟之眾士皆執行文王之德也。於讀曰烏。」","sentenceOrder":113},
  {"id":"s_work_han_thu_47_114","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「此周頌禘太祖之雝詩也。相，助也。辟，百辟也。公，諸侯也。言有此賓客以和而來至（也）〔止〕而敬者，乃助王祭之人，百辟與諸侯耳。於是時，天子則穆穆然。禮記曰『天子穆穆，諸侯皇皇』。辟音璧。」","sentenceOrder":114},
  {"id":"s_work_han_thu_47_115","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　師古曰：「此執競之篇祀武王之詩也。穰穰，多也。音人羊反。」","sentenceOrder":115},
  {"id":"s_work_han_thu_47_116","chapterId":"ch_work_han_thu_47","textTraditional":"〔八〕　師古曰：「此思文之篇以后稷配天之詩也。飴，遺也，言天遺此物也。飴讀與貽同也。釐音力之反，又讀與來同。麰音牟。」","sentenceOrder":116},
  {"id":"s_work_han_thu_47_117","chapterId":"ch_work_han_thu_47","textTraditional":"下至幽、厲之際，朝廷不和，轉相非怨，〔一〕詩人疾而憂之曰：「民之無良，相怨一方。」〔二〕眾小在位而從邪議，歙歙相是而背君子，故其詩曰：「歙歙訿訿，亦孔之哀！謀之其臧，則具是違；謀之不臧，則具是依！」〔三〕君子獨處守正，不橈眾枉，〔四〕勉彊以從王事則反見憎毒讒愬，故其詩曰：「密勿從事，不敢告勞，無罪無辜，讒口嗷嗷！」〔五〕當是之時，日月薄蝕而無光，〔六〕其詩曰：「朔日辛卯，日有蝕之，亦孔之醜！」〔七〕又曰：「彼月而微，此日而微，今此下民，亦孔之哀！」〔八〕又曰：「日月鞠凶，不用其行；四國無政，不用其良！」〔九〕天變見於上，地變動於下，水泉沸騰，山谷易處。其詩曰：「百川沸騰，山冢卒崩，高岸為谷，深谷為陵。哀今之人，胡憯莫懲！」〔一０〕霜降失節，不以其時，其詩曰：「正月繁霜，我心憂傷；民之訛言，亦孔之將！」言民以是為非，甚眾大也。〔一一〕此皆不和，賢不肖易位之所致也。〔一二〕","sentenceOrder":117},
  {"id":"s_work_han_thu_47_118","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「厲王、夷王之子。厲王生宣王，宣王生幽王。」","sentenceOrder":118},
  {"id":"s_work_han_thu_47_119","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「此小雅角弓之篇刺幽王之詩也。良，善也。言人各為不善，其意乖離，而相怨也。一方，謂自守一方，所嚮異之。」","sentenceOrder":119},
  {"id":"s_work_han_thu_47_120","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「此小雅小旻篇刺幽王之詩也。言在位卿士。歙歙然患其上，訿訿然不供職，各失臣節，甚可哀痛。而謀之善者，則背違之，不善之謀，依而施用，所以為刺也。歙音翕。訿音紫。」","sentenceOrder":120},
  {"id":"s_work_han_thu_47_121","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「橈，屈也，不為眾曲而自屈也。橈音女教反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_47_122","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「此小雅十月之交篇刺幽王之詩也。密勿猶黽勉從事也。嗷嗷，眾聲也。言己黽勉行事，不敢自陳勞苦，實無罪辜，而被讒譖嗷嗷然也。嗷音敖。」","sentenceOrder":122},
  {"id":"s_work_han_thu_47_123","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「薄，迫也。謂被掩迫也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_47_124","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　師古曰：「自此已下至『百川沸騰』，皆十月之交詩也。孔，甚也。醜，惡也。周之十月，夏之八月，朔日有辛卯，日月交會，而日見蝕，陰侵於陽。辛，金日也。卯，木辰也。以卯侵金，則臣侵君，故甚惡之。」","sentenceOrder":124},
  {"id":"s_work_han_thu_47_125","chapterId":"ch_work_han_thu_47","textTraditional":"〔八〕　師古曰：「微，虧微也。言彼月者，當有虧耳，而今此日，乃復微也。言君臣失道，是為災異，故令人甚哀也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_47_126","chapterId":"ch_work_han_thu_47","textTraditional":"〔九〕　師古曰：「鞠，告也。言日月不用其常行之道以告凶災者，由四方之國無政理，不能用善人也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_47_127","chapterId":"ch_work_han_thu_47","textTraditional":"〔一０〕師古曰：「沸，湧出也。騰，乘也。冢，山頂也。卒，盡也。胡，何也。憯，曾也。懲，乂也。言百川沸涌而相乘陵，山頂隆高而盡崩壞，陵谷易處，尊卑失序，咎異大矣，誠可畏懼。哀哉今人，何為曾莫創乂也！憯音千感反。」","sentenceOrder":127},
  {"id":"s_work_han_thu_47_128","chapterId":"ch_work_han_thu_47","textTraditional":"〔一一〕張晏曰：「正月，夏之四月也，純陽用事，而反多霜，急恆寒（苦）〔若〕之災也。」師古曰：「此小雅正月之篇刺幽王之詩也。四月正陽之月，故謂之正月。繁，多也。訛，偽也。孔，甚也。將，大也。此言王政乖舛，陽月多霜，害於生物，故己心為憂傷，而眾庶之人，共為偽言，以是為非，排斥賢儁，禍甚大也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_47_129","chapterId":"ch_work_han_thu_47","textTraditional":"〔一二〕師古曰：「賢人在下，不肖居上，故云易位。」","sentenceOrder":129},
  {"id":"s_work_han_thu_47_130","chapterId":"ch_work_han_thu_47","textTraditional":"自此之後，天下大亂，篡殺殃禍並作，厲王奔彘，〔一〕幽王見殺。〔二〕至乎平王末年，魯隱之始即位也，〔三〕周大夫祭伯乖離不和，出奔於魯，〔四〕而春秋為諱，不言來奔，傷其禍殃自此始也。是後尹氏世卿而專恣，〔五〕諸侯背畔而不朝，周室卑微。二百四十二年之間，〔六〕日食三十六，〔七〕地震五，〔八〕山陵崩阤二，〔九〕彗星三見，〔一０〕夜常星不見，夜中星隕如雨一〔一一〕，火災十四。〔一二〕長狄入三國，〔一三〕五石隕墜，六鶂退飛，多麋，有蜮、蜚，鴝鵒來巢者，皆一見。〔一四〕晝冥晦。〔一五〕雨木冰。〔一六〕李梅冬實。七月霜降，草木不死。〔一七〕八月殺菽。〔一八〕大雨雹。〔一九〕雨雪雷霆失序相乘。〔二０〕水、旱、饑，蝝、螽、螟螽午並起。〔二一〕當是時，禍亂輒應，弒君三十六，〔二二〕亡國五十二，〔二三〕諸侯奔走，不得保其社稷者，不可勝數也。〔二四〕周室多禍：晉敗其師於貿戎；〔二五〕伐其郊；〔二六〕鄭傷桓王；〔二七〕戎執其使；〔二八〕衛侯朔召不往，齊逆命而助朔；〔二九〕五大夫爭權，三君更立，莫能正理。〔三０〕遂至陵夷不能復興。〔三一〕","sentenceOrder":130},
  {"id":"s_work_han_thu_47_131","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「厲王無道，下不堪命，乃相與畔襲厲王。厲王出奔彘。彘，晉地，今晉州北永安縣是也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_47_132","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「為犬戎所攻，殺幽王于驪山下，虜褒姒，盡取周賂而去。」","sentenceOrder":132},
  {"id":"s_work_han_thu_47_133","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「平王，幽王之子。」","sentenceOrder":133},
  {"id":"s_work_han_thu_47_134","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　張晏曰：「隱元年『祭伯來』，穀梁傳曰『奔也』。」師古曰：「祭音側介反。」","sentenceOrder":134},
  {"id":"s_work_han_thu_47_135","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「春秋公羊經隱公三年『夏四月，尹氏卒。』傳曰『尹氏者何？天子之大夫也。其稱尹氏何？貶也。曷為貶？譏繼卿。繼卿，非禮也。』又詩小雅節南山云『尹氏太師，赫赫師尹，不平謂何！』刺之也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_47_136","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「謂從隱公元年至哀公十四年獲麟也。隱公十一年，桓公十八年，莊公三十二年，閔公（三）〔二〕年，僖公三十三年，文公十八年，宣公十八年，成公十八年，襄公三十一年，昭公三十二年，定公十五年，哀公十四年，凡二百四十二年也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_47_137","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　師古曰：「謂隱三年二月己巳；桓三年七月壬辰朔，十七年十月朔；莊十八年三月，二十五年六月辛未朔，二十六年十二月癸亥朔，三十年九月庚午朔；僖五年九月戊申朔，十二年三月庚午，十五年五月；文元年二月癸亥朔，十五年六月辛丑朔；宣八年七月甲子，十年四月丙辰，十七年六月癸卯；成十六年六月丙寅朔，十七年十二月丁巳朔；襄十四年二月乙未朔，十五年秋八月丁巳，二十年冬十月丙辰朔，二十一年九月庚戌朔，冬十月庚辰朔，二十三年二月癸酉朔，二十四年秋七月甲子朔，八月癸巳朔，二十七年冬十二月乙亥朔；昭七年夏四月甲辰朔，十五年六月丁巳朔，十七年夏六月甲戌朔，二十一年秋七月壬午朔，二十二年十二月癸酉朔，二十四年夏五月乙未朔，三十一年十二月辛亥朔；定五年正月辛亥朔，十二年十一月丙寅朔，十五年八月庚辰朔：凡三十六也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_47_138","chapterId":"ch_work_han_thu_47","textTraditional":"〔八〕　師古曰：「謂文九年九月癸酉，襄十六年五月甲子，昭十九年五月己卯，二十三年八月乙未，哀三年四月甲午，凡五也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_47_139","chapterId":"ch_work_han_thu_47","textTraditional":"〔九〕　師古曰：「謂僖十四年八月辛卯沙鹿崩，成五年夏梁山崩，凡二也。阤，下頹也。音丈爾反。」","sentenceOrder":139},
  {"id":"s_work_han_thu_47_140","chapterId":"ch_work_han_thu_47","textTraditional":"〔一０〕師古曰：「謂文十四年秋七月有星孛入于北斗，昭十七年冬有星孛于大辰，哀十三年冬十一月有星孛于東方。」","sentenceOrder":140},
  {"id":"s_work_han_thu_47_141","chapterId":"ch_work_han_thu_47","textTraditional":"〔一一〕師古曰：「事在莊七年夏四月辛卯。」","sentenceOrder":141},
  {"id":"s_work_han_thu_47_142","chapterId":"ch_work_han_thu_47","textTraditional":"〔一二〕師古曰：「桓十四年秋八月壬申御廩災，莊二十年夏齊大災，僖二十年五月乙巳西宮災，成三年二月甲子新宮災，襄九年春宋火，三十年五月甲午宋災，昭九年夏四月陳火，十八年夏五月壬午宋、衛、陳、鄭災，定二年夏五月壬辰雉門及兩觀災，哀三年五月辛卯桓宮、僖宮災，四年六月辛丑亳社災，凡十四也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_47_143","chapterId":"ch_work_han_thu_47","textTraditional":"〔一三〕師古曰：「謂春秋文十一年經書『冬十月甲午叔孫得臣敗狄于鹹』，公羊傳曰『狄者何？長狄也，兄弟三人，一者之齊，一者之魯，一者之晉。』之齊榮如，之魯喬如，之晉焚如。長狄，鄋瞞之種。鄋音搜，瞞音末安反。」","sentenceOrder":143},
  {"id":"s_work_han_thu_47_144","chapterId":"ch_work_han_thu_47","textTraditional":"〔一四〕師古曰：「謂僖十六年『正月戊申朔，隕石于宋，五。是月，六鶂退飛過宋都。』莊十七年『冬，多麋。』十八年『秋，有蜮。』二十九年『秋，有蜚。』昭二十五年『夏，有鴝鵒來巢。』蜮，短尾狐也。鶂，水鳥也。蜚，負蠜也。鶂音五歷反。蜮音域。蜚音扶味反。鴝音劬。鵒音欲。」","sentenceOrder":144},
  {"id":"s_work_han_thu_47_145","chapterId":"ch_work_han_thu_47","textTraditional":"〔一五〕師古曰：「僖十五年『九月己卯晦，震夷伯之廟。』穀梁傳曰『晦，冥也。』」","sentenceOrder":145},
  {"id":"s_work_han_thu_47_146","chapterId":"ch_work_han_thu_47","textTraditional":"〔一六〕師古曰：「事在成十六年正月。雨木冰者，氣著樹木結為冰也，今俗呼為間樹。雨音于具反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_47_147","chapterId":"ch_work_han_thu_47","textTraditional":"〔一七〕師古曰：「僖三十三年經書『冬隕霜，不煞草。』李梅實，未知在何月也。而此言李梅冬實，又云七月霜降，草木不死，與今春秋不同，未見義所出。」","sentenceOrder":147},
  {"id":"s_work_han_thu_47_148","chapterId":"ch_work_han_thu_47","textTraditional":"〔一八〕師古曰：「謂定公元年『十月，隕霜殺菽。』周之十月，夏之八月。菽謂豆也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_47_149","chapterId":"ch_work_han_thu_47","textTraditional":"〔一九〕師古曰：「事在僖二十九年秋，及昭三年冬，四年正月。雨音于具反。」","sentenceOrder":149},
  {"id":"s_work_han_thu_47_150","chapterId":"ch_work_han_thu_47","textTraditional":"〔二０〕師古曰：「隱九年三月癸酉大雨震電，庚辰大雨雪，莊六年冬十月雨雪，僖十年冬大雨雪，皆是也。靁，古雷字也。霆，雷之急者也，音大丁反。」","sentenceOrder":150},
  {"id":"s_work_han_thu_47_151","chapterId":"ch_work_han_thu_47","textTraditional":"〔二一〕如淳曰：「螽午猶雜沓也。」師古曰：「謂桓元年秋大水，十三年夏大水，莊七年秋大水，十一年秋宋大水，二十四年秋大水，二十五年秋大水，宣十年秋大水，成五年秋大水，襄二十四年秋七月大水；僖二十一年夏大旱，宣七年秋大旱；宣十年冬饑，十五年冬蝝生饑，襄二十四年冬大饑；桓五年秋螽，僖十五年八月螽，文三年秋雨螽於宋，八年冬螽，宣六年八月螽，十三年秋、十五年秋螽，襄七年八月螽，哀十二年十二月螽，十三年九月螽，十二月螽；隱五年九月螟，八年九月螟，莊六年秋螟：皆是也。螽即螟也。螟，蟲之食苗心者也。螽音終，螟音冥。」","sentenceOrder":151},
  {"id":"s_work_han_thu_47_152","chapterId":"ch_work_han_thu_47","textTraditional":"〔二二〕師古曰：「謂隱公四年衛州吁弒其君完；十一年羽父使賊弒公于寪氏；桓二年宋督弒其君與夷；七年曲沃伯誘晉小子侯殺之；十七年鄭高渠彌弒昭公；莊八年齊無知弒其君諸兒；十二年宋萬弒其君捷；十四年傅瑕弒其君鄭子；三十二年共仲使圉人犖賊子般；閔二年共仲使卜齮賊公于武闈；僖十年晉里克弒其君卓；二十四年晉弒懷公于高梁；文元年楚太子商臣弒其君頵；十四年齊公子商人弒其君舍；十六年宋人弒其君杵臼；十八年齊人弒其君商人；魯襄仲殺子惡；莒弒其君庶其；宣二年晉趙盾弒其君夷皋；四年鄭公子歸生弒其君夷；十年陳夏徵舒弒其君平國；成十八年晉弒其君州蒲；襄七年鄭子駟使賊夜弒僖公；二十五年齊崔杼弒其君光；二十六年衛甯喜弒其君剽；二十九年閽弒吳子餘祭；三十年蔡太子般弒其君固；三十一年莒人弒其君密州；昭元年楚公子圍問王疾，縊而弒之；十三年楚公子比弒其君虔于乾谿；十九年許太子止弒其君買；二十七年吳弒其君僚；定十三年薛弒其君比；哀四年盜殺蔡侯申；六年齊陳乞弒其君荼；十年齊人弒悼公：凡三十六。」","sentenceOrder":152},
  {"id":"s_work_han_thu_47_153","chapterId":"ch_work_han_thu_47","textTraditional":"〔二三〕師古曰：「謂桓五年州公如曹；莊四年紀侯大去其國；十年齊師滅譚；十三年齊人滅遂；十四年楚子滅息；十六年楚滅鄧；閔元年晉滅耿，滅霍，滅魏；僖五年楚滅弦，晉滅虢，滅虞；十二年楚人滅黃；十七年楚滅項；十九年秦人取梁；二十五年衛侯燬滅邢；二十六年楚人滅夔；三十三年秦滅滑；文四年楚滅江；五年楚人滅六，滅蓼；十六年楚人、秦人、巴人滅庸；宣八年楚人滅舒蓼，九年取根牟；十二年楚子滅蕭；十五年晉師滅赤狄潞氏；成六年取鄟；十七年楚滅舒（蕭）〔庸〕；襄六年莒人滅鄫，齊侯滅萊；十年諸侯滅偪陽；十三年取邿；二十五年楚滅舒鳩；昭四年楚子滅賴；十三年晉滅肥；十六年楚子取戎蠻氏；十七年晉滅陸渾戎；二十一年晉滅鼓；三十年吳滅徐；定四年蔡滅沈；五年楚滅唐；六年鄭滅許；十四年楚人滅頓；十五年楚子滅胡；哀八年宋公滅曹；又邾滅須句，楚滅權，晉滅焦、楊，楚滅道、房、申：凡五十二。」","sentenceOrder":153},
  {"id":"s_work_han_thu_47_154","chapterId":"ch_work_han_thu_47","textTraditional":"〔二四〕師古曰：「謂桓十五年鄭伯突出奔蔡，襄十四年衛侯出奔齊，昭三年北燕伯款出奔齊，二十三年莒子庚輿來奔之類是也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_47_155","chapterId":"ch_work_han_thu_47","textTraditional":"〔二五〕師古曰：「貿戎，地名也。春秋公羊經成元年秋，王師敗績于貿戎。傳曰『孰敗之？蓋晉敗之』也。貿音莫侯反。」","sentenceOrder":155},
  {"id":"s_work_han_thu_47_156","chapterId":"ch_work_han_thu_47","textTraditional":"〔二六〕師古曰：「郊、周邑也。昭二十三年正月，經書『晉人圍郊』也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_47_157","chapterId":"ch_work_han_thu_47","textTraditional":"〔二七〕應劭曰：「王以諸侯伐鄭，鄭伯禦之，射王中肩。」師古曰：「事在桓五年秋。」","sentenceOrder":157},
  {"id":"s_work_han_thu_47_158","chapterId":"ch_work_han_thu_47","textTraditional":"〔二八〕師古曰：「隱七年冬，經書『天王使凡伯來聘，戎伐凡伯于楚丘以歸』。」","sentenceOrder":158},
  {"id":"s_work_han_thu_47_159","chapterId":"ch_work_han_thu_47","textTraditional":"〔二九〕師古曰：「春秋桓十六年，經書『衛侯朔出奔齊』，穀梁傳曰『天子召而不往也』。」","sentenceOrder":159},
  {"id":"s_work_han_thu_47_160","chapterId":"ch_work_han_thu_47","textTraditional":"〔三０〕應劭曰：「周景王崩，單穆公、劉文公、鞏簡公、甘平公、召莊公，此五大夫相與爭奪，更立王子猛、子朝及敬王，是為三君也。更音工衡反。」","sentenceOrder":160},
  {"id":"s_work_han_thu_47_161","chapterId":"ch_work_han_thu_47","textTraditional":"〔三一〕師古曰：「陵夷謂卑替也。解在成紀及異姓諸侯王表也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_47_162","chapterId":"ch_work_han_thu_47","textTraditional":"由此觀之，和氣致祥，乖氣致異；祥多者其國安，異眾者其國危，天地之常經，古今之通義也。今陛下開三代之業，招文學之士，優游寬容，使得並進。今賢不肖渾殽，〔一〕白黑不分，邪正雜糅，忠讒並進。〔二〕章交公車，人滿北軍。〔三〕朝臣舛午，膠戾乘剌，〔四〕更相讒愬，轉相是非。〔五〕傳授增加，文書紛糾，前後錯繆，毀譽渾亂。〔六〕所以營或耳目，感移心意，不可勝載。〔七〕分曹為黨，往往群朋，〔八〕將同心以陷正臣。正臣進者，治之表也；正臣陷者，亂之機也。乘治亂之機，未知孰任，而災異數見，此臣所以寒心者也。夫乘權藉勢之人，子弟鱗集於朝，〔九〕羽翼陰附者眾，輻湊於前，〔一０〕毀譽將必用，以終乖離之咎。〔一一〕是以日月無光，雪霜夏隕，海水沸出，陵谷易處，列星失行，皆怨氣之所致也。夫遵衰周之軌跡，循詩人之所刺，而欲以成太平，致雅頌，猶卻行而求及前人也。〔一二〕初元以來六年矣，案春秋六年之中，災異未有稠如今者也。〔一三〕夫有春秋之異，無孔子之救，猶不能解紛，〔一四〕況甚於春秋乎？","sentenceOrder":162},
  {"id":"s_work_han_thu_47_163","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「言雜亂也。渾音胡本反，其下亦同。」","sentenceOrder":163},
  {"id":"s_work_han_thu_47_164","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「糅，和也，音汝救反。」","sentenceOrder":164},
  {"id":"s_work_han_thu_47_165","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　如淳曰：「漢儀注中壘校尉主北軍壘門內，尉一人主上書者獄。上章於公車，有不如法者，以付北軍尉，北軍尉以法治之。楊惲上書，遂幽北闕。北闕，公車所在。」","sentenceOrder":165},
  {"id":"s_work_han_thu_47_166","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「言志意不和，各相違背。午音五故反，剌音來曷反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_47_167","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「更音工衡反。」","sentenceOrder":167},
  {"id":"s_work_han_thu_47_168","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「言各任私情，不得其實。」","sentenceOrder":168},
  {"id":"s_work_han_thu_47_169","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　師古曰：「言其誣罔天子也。營謂回繞之。」","sentenceOrder":169},
  {"id":"s_work_han_thu_47_170","chapterId":"ch_work_han_thu_47","textTraditional":"〔八〕　師古曰：「曹，輩也。」","sentenceOrder":170},
  {"id":"s_work_han_thu_47_171","chapterId":"ch_work_han_thu_47","textTraditional":"〔九〕　師古曰：「言其相次如魚鱗。」","sentenceOrder":171},
  {"id":"s_work_han_thu_47_172","chapterId":"ch_work_han_thu_47","textTraditional":"〔一０〕師古曰：「輻湊，言如車輻之歸於轂也。」","sentenceOrder":172},
  {"id":"s_work_han_thu_47_173","chapterId":"ch_work_han_thu_47","textTraditional":"〔一一〕師古曰：「言讒佞之人毀譽得進，則忠賢被斥，日以乖離也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_47_174","chapterId":"ch_work_han_thu_47","textTraditional":"〔一二〕師古曰：「卻音邱略反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_47_175","chapterId":"ch_work_han_thu_47","textTraditional":"〔一三〕師古曰：「稠，多也。音直流反。」","sentenceOrder":175},
  {"id":"s_work_han_thu_47_176","chapterId":"ch_work_han_thu_47","textTraditional":"〔一四〕師古曰：「紛，亂也。」","sentenceOrder":176},
  {"id":"s_work_han_thu_47_177","chapterId":"ch_work_han_thu_47","textTraditional":"原其所以然者，讒邪並進也。讒邪之所以並進者，由上多疑心，既已用賢人而行善政，如或譖之，則賢人退而善政還。〔一〕夫執狐疑之心者，來讒賊之口；持不斷之意者，開群枉之門。〔二〕讒邪進則眾賢退，群枉盛則正士消。故易有否泰。〔三〕小人道長，君子道消，君子道消，則政日亂，故為否。否者，閉而亂也。君子道長，小人道消，小人道消，則政日治，故為泰。泰者，通而治也。詩又云「雨雪麃麃，見晛聿消」，〔四〕與易同義。昔者鯀、共工、驩兜與舜、禹雜處堯朝，〔五〕周公與管、蔡並居周位，當是時，迭進相毀，〔六〕流言相謗，豈可勝道哉！帝堯、成王能賢舜、禹、周公而消共工、管、蔡，故以大治，榮華至今。孔子與季、孟偕仕於魯〔七〕，李斯與叔孫俱宦於秦，〔八〕定公、始皇賢季、孟、李斯而消孔子、叔孫，故以大亂，污辱至今。故治亂榮辱之端，在所信任；信任既賢，在於堅固而不移。詩云「我心匪石，不可轉也」。〔九〕言守善篤也。易曰「渙汗其大號」。〔一０〕言號令如汗，汗出而不反者也。今出善令，未能踰時而反，是反汗也；〔一一〕用賢未能三旬而退，是轉石也。論語曰：「見不善如探湯。」〔一二〕今二府奏佞諂不當在位，歷年而不去。〔一三〕故出令則如反汗，用賢則如轉石，去佞則如拔山，如此望陰陽之調，不亦難乎！","sentenceOrder":177},
  {"id":"s_work_han_thu_47_178","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「還謂收還也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_47_179","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「枉，曲也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_47_180","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「否音皮鄙反。」","sentenceOrder":180},
  {"id":"s_work_han_thu_47_181","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「此小雅角弓篇刺幽王好讒佞之詩也。麃麃，盛也。見，無雲也。晛，日氣也。聿，辭也。言雨雪之盛麃麃然，至於無雲，日氣始出，而雨雪皆消釋矣。喻小人雖多，王若欲興善政，則賢者升用，而小人誅滅矣。麃音彼驕反。晛音乃見反。」。","sentenceOrder":181},
  {"id":"s_work_han_thu_47_182","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「鯀，崇伯之名，即檮杌也。共工，少皡氏之後，即窮奇也。驩兜，帝鴻氏之後，即渾敦也。鯀音工本反。驩音火官反。檮音徒高反。杌音兀。渾音胡本反。敦音徒本反。」","sentenceOrder":182},
  {"id":"s_work_han_thu_47_183","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「迭，互也。音大結反。」","sentenceOrder":183},
  {"id":"s_work_han_thu_47_184","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　師古曰：「季、孟謂季孫、孟孫，皆桓公之後代，執國權而卑公室也。」","sentenceOrder":184},
  {"id":"s_work_han_thu_47_185","chapterId":"ch_work_han_thu_47","textTraditional":"〔八〕　師古曰：「叔孫者，叔孫通也。」","sentenceOrder":185},
  {"id":"s_work_han_thu_47_186","chapterId":"ch_work_han_thu_47","textTraditional":"〔九〕　師古曰：「此邶柏舟之詩也，言石性雖堅，尚可移轉，己志貞確，執德不傾，過於石也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_47_187","chapterId":"ch_work_han_thu_47","textTraditional":"〔一０〕師古曰：「此易渙卦九（四）〔五〕爻辭也。言王者渙然大發號令，如汗之出也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_47_188","chapterId":"ch_work_han_thu_47","textTraditional":"〔一一〕師古曰：「一時，三月也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_47_189","chapterId":"ch_work_han_thu_47","textTraditional":"〔一二〕師古曰：「論語載孔子之言。探湯，言其除難無所避也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_47_190","chapterId":"ch_work_han_thu_47","textTraditional":"〔一三〕如淳曰：「二府，丞相、御史也。」師古曰：「讇，古諂字。」","sentenceOrder":190},
  {"id":"s_work_han_thu_47_191","chapterId":"ch_work_han_thu_47","textTraditional":"是以群小窺見間隙，緣飾文字，巧言醜詆，〔一〕流言飛文，譁於民間。〔二〕故詩云：「憂心悄悄，慍于群小。」〔三〕小人成群，誠足慍也。昔孔子與顏淵、子貢更相稱譽，不為朋黨；〔四〕禹、稷與皋陶傳相汲引，不為比周。〔五〕何則？忠於為國，無邪心也。故賢人在上位，則引其類而聚之於朝，易曰「飛龍在天，大人聚也」；〔六〕在下位，則思與其類俱進，易曰「拔茅茹以其彙，征吉」。〔七〕在上則引其類，在下則推其類，故湯用伊尹，不仁者遠，而眾賢至，類相致也。今佞邪與賢臣並在交戟之內，〔八〕合黨共謀，違善依惡，歙歙訿訿，數設危險之言，欲以傾移主上。如忽然用之，此天地之所以先戒，災異之所以重至者也。〔九〕","sentenceOrder":191},
  {"id":"s_work_han_thu_47_192","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「詆，毀也，辱也。音丁禮反。」","sentenceOrder":192},
  {"id":"s_work_han_thu_47_193","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「譁，讙也。譁音火瓜反。」","sentenceOrder":193},
  {"id":"s_work_han_thu_47_194","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「此邶柏舟言仁而不遇之詩也。悄悄，憂貌。慍，怒也。悄音千小反。」","sentenceOrder":194},
  {"id":"s_work_han_thu_47_195","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「事具見論語。更音工衡反。」","sentenceOrder":195},
  {"id":"s_work_han_thu_47_196","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「事見尚書舜典。比音頻寐反。」","sentenceOrder":196},
  {"id":"s_work_han_thu_47_197","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「此乾卦九五象辭也。言聖王正位，臨馭四方，則賢人君子皆來見也。」","sentenceOrder":197},
  {"id":"s_work_han_thu_47_198","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　鄭氏曰；「彙音謂。彙，類也。茹，牽引也。茅喻君有潔白之德，臣下引其類而仕之。」師古曰：「此泰卦初九爻辭。征，行也。茹音汝據反。」","sentenceOrder":198},
  {"id":"s_work_han_thu_47_199","chapterId":"ch_work_han_thu_47","textTraditional":"〔八〕　師古曰：「交戟，謂宿衛者。」","sentenceOrder":199},
  {"id":"s_work_han_thu_47_200","chapterId":"ch_work_han_thu_47","textTraditional":"〔九〕　師古曰：「重音直用反。」","sentenceOrder":200},
  {"id":"s_work_han_thu_47_201","chapterId":"ch_work_han_thu_47","textTraditional":"自古明聖，未有無誅而治者也，故舜有四放之罰，〔一〕而孔子有兩觀之誅，〔二〕然後聖化可得而行也。今以陛下明知，誠深思天地之心，跡察兩觀之誅，〔三〕覽否泰之卦，觀雨雪之詩，歷周、唐之所進以為法，原秦、魯之所消以為戒，〔四〕考祥應之福，省災異之禍，以揆當世之變，〔五〕放遠佞邪之黨，壞散險詖之聚〔六〕，杜閉群枉之門，廣開眾正之路，〔七〕決斷狐疑，分別猶豫，使是非炳然可知，則百異消滅，而眾祥並至，太平之基，萬世之利也。","sentenceOrder":201},
  {"id":"s_work_han_thu_47_202","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「謂流共工于幽州，放驩兜于崇山，竄三曲于三危，殛鯀于羽山也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_47_203","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　應劭曰：「少正卯姦人之雄，故孔子攝司寇七日，誅之於兩觀之下。」師古曰：「兩觀，謂闕也。」","sentenceOrder":203},
  {"id":"s_work_han_thu_47_204","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「尋其餘跡而察之。」","sentenceOrder":204},
  {"id":"s_work_han_thu_47_205","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「歷謂歷觀之，原謂思其本也。」","sentenceOrder":205},
  {"id":"s_work_han_thu_47_206","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「省，視也。揆，度也。」","sentenceOrder":206},
  {"id":"s_work_han_thu_47_207","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「險言曰詖，音彼義反。」","sentenceOrder":207},
  {"id":"s_work_han_thu_47_208","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　師古曰：「杜，塞也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_47_209","chapterId":"ch_work_han_thu_47","textTraditional":"臣幸得託肺附，〔一〕誠見陰陽不調，不敢不通所聞。竊推春秋災異，以（效）〔救〕今事一二，條其所以，〔二〕不宜宣泄。臣謹重封昧死上。","sentenceOrder":209},
  {"id":"s_work_han_thu_47_210","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「舊解云肺附謂肝肺相附著，猶言心膂也。一說肺謂斫木之肺札也，自言於帝室猶肺札附於大材木也。」","sentenceOrder":210},
  {"id":"s_work_han_thu_47_211","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「以，由也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_47_212","chapterId":"ch_work_han_thu_47","textTraditional":"恭、顯見其書，愈與許、史比而怨更生等。〔一〕堪性公方，自見孤立，遂直道而不曲。是歲夏寒，日青無光，恭、顯及許、史皆言堪、猛用事之咎。上內重堪，又患眾口之寖潤，無所取信。時長安令楊興以材能幸，常稱譽堪。上欲以為助，乃見問興：「朝臣齗齗不可光祿勳，何（也）〔邪〕？」〔二〕興者傾巧士，謂上疑堪，因順指曰：「堪非獨不可於朝廷，自州里亦不可也。臣見眾人聞堪前與劉更生等謀毀骨肉，以為當誅，故臣前言堪不可誅傷，為國養恩也。」上曰：「然此何罪而誅？今宜奈何？」興曰：「臣愚以為可賜爵關內侯，食邑三百戶，勿令典事。明主不失師傅之恩，此最策之得者也。」上於是疑。會城門校尉諸葛豐亦言堪、猛短，上因發怒免豐。語在其傳。又曰：「豐言堪、猛貞信不立，朕閔而不治，又惜其材能未有所效，其左遷堪為河東太守，猛槐里令。」","sentenceOrder":212},
  {"id":"s_work_han_thu_47_213","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「比音頻寐反。」","sentenceOrder":213},
  {"id":"s_work_han_thu_47_214","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「齗齗，忿嫉之意也。齗音牛斤反。」","sentenceOrder":214},
  {"id":"s_work_han_thu_47_215","chapterId":"ch_work_han_thu_47","textTraditional":"顯等專權日甚。後三歲餘，孝宣廟闕災，其晦，日有蝕之。於是上召諸前言日變在堪、猛者責問，皆稽首謝。乃因下詔曰：「河東太守堪，先帝賢之，命而傅朕。資質淑茂，道術通明，〔一〕論議正直，秉心有常，發憤悃愊，〔二〕信有憂國之心。以不能阿尊事貴，孤特寡助，抑厭遂退，〔三〕卒不克明。〔四〕往者眾臣見異，〔五〕不務自修，深惟其故，而反晻昧說天，託咎此人。〔六〕朕不得已，〔七〕出而試之，以彰其材。堪出之後，大變仍臻，眾亦嘿然。堪治未期年，而三老官屬有識之士詠頌其美，使者過郡，靡人不稱。〔八〕此固足以彰先帝之知人，而朕有以自明也。俗人乃造端作基，非議詆欺，〔九〕或引幽隱，非所宜明，意疑以類，欲以陷之，朕亦不取也。朕迫于俗，不得專心，乃者天著大異，朕甚懼焉。今堪年衰歲暮，恐不得自信，〔一０〕排於異人，將安究之哉？〔一一〕其徵堪詣行在所。」拜為光祿大夫，秩中二千石，領尚書事。猛復為太中大夫給事中。顯幹尚書〔事〕，〔一二〕尚書五人，皆其黨也。堪希得見，常因顯白事，事決顯口。會堪疾瘖，不能言而卒。〔一三〕顯誣譖猛，令自殺於公車。更生傷之，乃著疾讒、擿要、救危及世頌，凡八篇，〔一四〕依興古事，悼己及同類也。〔一五〕遂廢十餘年。","sentenceOrder":215},
  {"id":"s_work_han_thu_47_216","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「淑，善也。茂，美也。」","sentenceOrder":216},
  {"id":"s_work_han_thu_47_217","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　張晏曰：「悃，誠也。愊，緻密也。」師古曰：「悃愊，至誠也。悃音口本反。愊音平力反。」","sentenceOrder":217},
  {"id":"s_work_han_thu_47_218","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「厭音一甲反，謂不伸也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_47_219","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「卒，終也。克，能也。」","sentenceOrder":219},
  {"id":"s_work_han_thu_47_220","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「異，災異也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_47_221","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「晻，不明也，讀與暗同，又音烏感反。」","sentenceOrder":221},
  {"id":"s_work_han_thu_47_222","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　師古曰：「已，止也。」","sentenceOrder":222},
  {"id":"s_work_han_thu_47_223","chapterId":"ch_work_han_thu_47","textTraditional":"〔八〕　師古曰：「靡，無也。」","sentenceOrder":223},
  {"id":"s_work_han_thu_47_224","chapterId":"ch_work_han_thu_47","textTraditional":"〔九〕　師古曰：「詆，毀也，音丁禮反。」","sentenceOrder":224},
  {"id":"s_work_han_thu_47_225","chapterId":"ch_work_han_thu_47","textTraditional":"〔一０〕師古曰：「信讀曰伸。」","sentenceOrder":225},
  {"id":"s_work_han_thu_47_226","chapterId":"ch_work_han_thu_47","textTraditional":"〔一一〕師古曰：「究，竟也，明也。」","sentenceOrder":226},
  {"id":"s_work_han_thu_47_227","chapterId":"ch_work_han_thu_47","textTraditional":"〔一二〕師古曰：「幹與管同，言管主其事。」","sentenceOrder":227},
  {"id":"s_work_han_thu_47_228","chapterId":"ch_work_han_thu_47","textTraditional":"〔一三〕師古曰：「瘖音於今反。」","sentenceOrder":228},
  {"id":"s_work_han_thu_47_229","chapterId":"ch_work_han_thu_47","textTraditional":"〔一四〕師古曰：「擿謂指發之也，音吐歷反。」","sentenceOrder":229},
  {"id":"s_work_han_thu_47_230","chapterId":"ch_work_han_thu_47","textTraditional":"〔一五〕師古曰：「興謂比喻也，音許證反。」","sentenceOrder":230},
  {"id":"s_work_han_thu_47_231","chapterId":"ch_work_han_thu_47","textTraditional":"成帝即位，顯等伏辜，更生乃復進用，更名向。向以故九卿召拜為中郎，使領護三輔都水。〔一〕數奏封事，遷光祿大夫。是時帝元舅陽平侯王鳳為大將軍秉政，倚太后，專國權，〔二〕兄弟七人皆封為列侯。時數有大異，向以為外戚貴盛，鳳兄弟用事之咎。而上方精於詩書，觀古文，詔向領校中五經祕書。〔三〕向見尚書洪範，箕子為武王陳五行陰陽休咎之應。〔四〕向乃集合上古以來歷春秋六國至秦漢符瑞災異之記，推跡行事，連傳禍福，著其占驗，比類相從，各有條目，凡十一篇，號曰洪範五行傳論，奏之。天子心知向忠精，故為鳳兄弟起此論也，然終不能奪王氏權。","sentenceOrder":231},
  {"id":"s_work_han_thu_47_232","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　蘇林曰：「三輔多溉灌渠，悉主之，故言都水。」","sentenceOrder":232},
  {"id":"s_work_han_thu_47_233","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「倚音於綺反。」","sentenceOrder":233},
  {"id":"s_work_han_thu_47_234","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「言中者以別於外。」","sentenceOrder":234},
  {"id":"s_work_han_thu_47_235","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「休，美也，音許求反。它皆類此。」","sentenceOrder":235},
  {"id":"s_work_han_thu_47_236","chapterId":"ch_work_han_thu_47","textTraditional":"久之，營起昌陵，數年不成，復還歸延陵，制度泰奢。向上疏諫曰：","sentenceOrder":236},
  {"id":"s_work_han_thu_47_237","chapterId":"ch_work_han_thu_47","textTraditional":"臣聞易曰：「安不忘危，存不忘亡，是以身安而國家可保也。」〔一〕故賢聖之君，博觀終始，窮極事情，而是非分明。王者必通三統，〔二〕明天命所授者博，非獨一姓也。孔子論詩，至於「殷士膚敏，祼將于京」，〔三〕喟然歎曰：〔四〕「大哉天命！善不可不傳于子孫，是以富貴無常；不如是，則王公其何以戒慎，民萌何以勸勉？」〔五〕蓋傷微子之事周，而痛殷之亡也。雖有堯舜之聖，不能化丹朱之子；雖有禹湯之德，不能訓末孫之桀紂。自古及今，未有不亡之國也。昔高皇帝既滅秦，將都雒陽，感寤劉敬之言，自以德不及周，而賢於秦，遂徙都關中，依周之德，因秦之阻。世之長短，以德為效，〔六〕故常戰栗，不敢諱亡。孔子所謂「富貴無常」，蓋謂此也。","sentenceOrder":237},
  {"id":"s_work_han_thu_47_238","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「易下繫之辭。」","sentenceOrder":238},
  {"id":"s_work_han_thu_47_239","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　應劭曰：「二王之後，與己為三統也。」孟康曰：「天地人之始也。」張晏曰：「一曰天統，為周十一月建子為正，天始施之端也。二曰地統，謂殷以十二月建丑為正，地始化之端也。三曰人統，謂夏以十三月建寅為正，人始成之端也。」師古曰：「二家之說皆不備也。言王者象天地人之三統，故存三代也。」","sentenceOrder":239},
  {"id":"s_work_han_thu_47_240","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「此大雅文王之篇。殷士，殷之卿士也。膚，美也。敏，疾也。祼，灌鬯也。將，行也。京，周京也。言殷之臣有美德而敏疾，乃來助祭于周，行祼鬯之事，是天命無常，歸於有德。」","sentenceOrder":240},
  {"id":"s_work_han_thu_47_241","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「喟然，歎息貌，音丘位反。」","sentenceOrder":241},
  {"id":"s_work_han_thu_47_242","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「萌與甿同，無知之貌。」","sentenceOrder":242},
  {"id":"s_work_han_thu_47_243","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「效謂徵驗也。」","sentenceOrder":243},
  {"id":"s_work_han_thu_47_244","chapterId":"ch_work_han_thu_47","textTraditional":"孝文皇帝居霸陵，北臨廁，〔一〕意悽愴悲懷，顧謂群臣曰：「嗟乎！以北山石為槨，用紵絮斮陳漆其間，〔二〕豈可動哉！」張釋之進曰：「使其中有可欲，雖錮南山猶有隙；使其中無可欲，雖無石槨，又何慼焉？」〔三〕夫死者無終極，而國家有廢興，故釋之之言，為無窮計也。孝文寤焉，遂薄葬，不起山墳。","sentenceOrder":244},
  {"id":"s_work_han_thu_47_245","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　服虔曰：「廁，側近水也。」李奇曰：「霸陵山北頭廁近霸水，帝登其上以遠望也。」","sentenceOrder":245},
  {"id":"s_work_han_thu_47_246","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　應劭曰：「斮，斬也。陳，施也。」孟康曰：「斮絮以漆著其間也。」師古曰：「美石出京師北山，今宜州石是也，故云以北山石為槨。紵絮者，可以紵衣之絮也。斮而陳其間，又從而漆之也。紵音張呂反。斮音側略反。」","sentenceOrder":246},
  {"id":"s_work_han_thu_47_247","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「有可欲，謂多臧金玉而厚葬之，人皆欲發取之，是有間隙也。無可欲，謂不寘器（衛）〔備〕而薄葬，人無欲攻掘取之，故無憂慼也。錮謂鑄塞也。云錮南山者，取其深大，假為喻也。錮音固。」","sentenceOrder":247},
  {"id":"s_work_han_thu_47_248","chapterId":"ch_work_han_thu_47","textTraditional":"易曰：「古之葬者，厚衣之以薪，臧之中野，不封不樹〔一〕。後世聖人易之以棺槨。」棺槨之作，自黃帝始。黃帝葬於橋山，〔二〕堯葬濟陰，丘壟皆小，葬具甚微。〔三〕舜葬蒼梧，二妃不從。〔四〕禹葬會稽，不改其列。〔五〕殷湯無葬處。〔六〕文、武、周公葬於畢，〔七〕秦穆公葬於雍橐泉宮祈年館下，樗里子葬於武庫，〔八〕皆無丘隴之處。此聖帝明王賢君智士遠覽獨慮無窮之計也。其賢臣孝子亦承命順意而薄葬之，此誠奉安君父，忠孝之至也。","sentenceOrder":248},
  {"id":"s_work_han_thu_47_249","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「厚衣之以薪，言積薪以覆之也。不封，謂不聚土為墳也。不樹，謂不種樹也。衣音於既反。」","sentenceOrder":249},
  {"id":"s_work_han_thu_47_250","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「在上郡陽周縣。」","sentenceOrder":250},
  {"id":"s_work_han_thu_47_251","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　晉灼曰：「丘壟，冢墳也。」","sentenceOrder":251},
  {"id":"s_work_han_thu_47_252","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「二妃，堯之二女。」","sentenceOrder":252},
  {"id":"s_work_han_thu_47_253","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　鄭氏曰：「不改樹木百物之列也。」如淳曰：「列，隴也。墨子曰『禹葬會稽之山，既葬，收餘壤其上，壟若參耕之畝，則止矣。』」晉灼曰：「列，肆也。淮南子云『舜葬蒼梧，不變其肆』，言不煩於民也。」師古曰：「鄭說是也。淮南所云『不變其肆』，肆者故也，言山川田畝皆如故耳，非別義也。晉氏失之。」","sentenceOrder":253},
  {"id":"s_work_han_thu_47_254","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「謂不見傳記也。」","sentenceOrder":254},
  {"id":"s_work_han_thu_47_255","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　李奇曰：「在岐州之間。」臣瓚曰：「汲郡古文畢西於豐三十里。」師古曰：「二說皆非也。畢陌在長安西北四十里也。」","sentenceOrder":255},
  {"id":"s_work_han_thu_47_256","chapterId":"ch_work_han_thu_47","textTraditional":"〔八〕　文穎曰：「秦惠王異母弟也。」師古曰：「樗里子且死，曰：『葬我必於渭南章臺東，後百年當有天子宮夾我墓。』及漢興，長樂宮在其東，未央宮在其西，武庫正直其上也。」","sentenceOrder":256},
  {"id":"s_work_han_thu_47_257","chapterId":"ch_work_han_thu_47","textTraditional":"夫周公，武王弟也，葬兄甚微。孔子葬母於防，〔一〕稱古墓而不墳，〔二〕曰：「丘，東西南北之人也，不可不識也。」〔三〕為四尺墳，遇雨而崩。弟子修之，以告孔子，孔子流涕曰：「吾聞之，古〔者〕不修墓。」蓋非之也。〔四〕延陵季子適齊而反，其子死，葬於嬴、博之間，〔五〕穿不及泉，斂以時服，封墳掩坎，其高可隱，〔六〕而號曰：〔七〕「骨肉歸復於土，命也，魂氣則無不之也。」夫嬴、博去吳千有餘里，季子不歸葬。孔子往觀曰：「延陵季子於禮合矣。」〔八〕故仲尼孝子，而延陵慈父，舜禹忠臣，周公弟弟，〔九〕其葬君親骨肉，皆微薄矣；非苟為儉，誠便於體也。宋桓司馬為石槨，仲尼曰「不如速朽。」〔一０〕秦相呂不韋集知略之士而造春秋，亦言薄葬之義，皆明於事情者也。","sentenceOrder":257},
  {"id":"s_work_han_thu_47_258","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「防，魯邑名也。音扶方反。」","sentenceOrder":258},
  {"id":"s_work_han_thu_47_259","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「墓謂壙穴也。墳謂積土也。」","sentenceOrder":259},
  {"id":"s_work_han_thu_47_260","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「東西南北，言周遊以行其道，不得專在本邦，故墓須表識，音式志反。」","sentenceOrder":260},
  {"id":"s_work_han_thu_47_261","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「事見禮記。」","sentenceOrder":261},
  {"id":"s_work_han_thu_47_262","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「二邑並在泰山，其子死於其間。」","sentenceOrder":262},
  {"id":"s_work_han_thu_47_263","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　孟康曰：「隱蔽之，才可見而已。」臣瓚曰：「謂人立可隱肘也。」師古曰：「瓚說是也。隱音於靳反。」","sentenceOrder":263},
  {"id":"s_work_han_thu_47_264","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　師古曰：「號謂哭而且言也。」","sentenceOrder":264},
  {"id":"s_work_han_thu_47_265","chapterId":"ch_work_han_thu_47","textTraditional":"〔八〕　師古曰：「事亦見禮記。」","sentenceOrder":265},
  {"id":"s_work_han_thu_47_266","chapterId":"ch_work_han_thu_47","textTraditional":"〔九〕　師古曰：「弟弟者，言弟能順理也。上弟音徒計反。」","sentenceOrder":266},
  {"id":"s_work_han_thu_47_267","chapterId":"ch_work_han_thu_47","textTraditional":"〔一０〕李奇曰：「宋桓魋為石槨，奢泰，故激以此言。」","sentenceOrder":267},
  {"id":"s_work_han_thu_47_268","chapterId":"ch_work_han_thu_47","textTraditional":"逮至吳王闔閭，違禮厚葬，十有餘年，越人發之。及秦惠文、武、昭、嚴襄五王，〔一〕皆大作丘隴，多其瘞臧，〔二〕咸盡發掘暴露，甚足悲也。秦始皇帝葬於驪山之阿，〔三〕下錮三泉，上崇山墳，其高五十餘丈，周回五里有餘；石槨為游館，〔四〕人膏為燈燭，水銀為江海，黃金為鳧雁。珍寶之臧，機械之變，〔五〕棺槨之麗，宮館之盛，不可勝原。〔六〕又多殺宮人，生薶工匠，計以萬數。天下苦其役而反之，驪山之作未成，而周章百萬之師至其下矣〔七〕。項籍燔其宮室營宇，往者咸見發掘。〔八〕其後牧兒亡羊，羊入其鑿，〔九〕牧者持火照求羊，失火燒其臧槨。自古至今，葬未有盛如始皇者也，數年之間，外被項籍之災，內離牧豎之禍，〔一０〕豈不哀哉！","sentenceOrder":268},
  {"id":"s_work_han_thu_47_269","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「嚴襄者，謂莊襄，則始皇父也。」","sentenceOrder":269},
  {"id":"s_work_han_thu_47_270","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「瘞，埋也。音于例反。」","sentenceOrder":270},
  {"id":"s_work_han_thu_47_271","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「阿謂山曲也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_47_272","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　李奇曰：「壙中為遊戲之觀也。」師古曰：「多累石作槨於壙中，以為離宮別館也。」","sentenceOrder":272},
  {"id":"s_work_han_thu_47_273","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　孟康曰：「作機發木人之屬，盡其巧變也。」晉灼曰：「始皇本紀令匠作機弩矢，有所穿近，輒射之。又言工匠為機，咸皆知之，已下，閉羨門，皆殺工匠也。」師古曰：「晉說是也。」","sentenceOrder":273},
  {"id":"s_work_han_thu_47_274","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「言不能盡其本數。」","sentenceOrder":274},
  {"id":"s_work_han_thu_47_275","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　師古曰：「周章，陳勝之將。」","sentenceOrder":275},
  {"id":"s_work_han_thu_47_276","chapterId":"ch_work_han_thu_47","textTraditional":"〔八〕　師古曰：「言至其墓所者發掘之而求財物也。」","sentenceOrder":276},
  {"id":"s_work_han_thu_47_277","chapterId":"ch_work_han_thu_47","textTraditional":"〔九〕　師古曰：「鑿謂所穿冢臧者，音在到反。」","sentenceOrder":277},
  {"id":"s_work_han_thu_47_278","chapterId":"ch_work_han_thu_47","textTraditional":"〔一０〕師古曰：「離，遭也。」","sentenceOrder":278},
  {"id":"s_work_han_thu_47_279","chapterId":"ch_work_han_thu_47","textTraditional":"是故德彌厚者葬彌薄，知愈深者葬愈微。無德寡知，其葬愈厚，丘隴彌高，宮廟甚麗，發掘必速。由是觀之，明暗之效，葬之吉凶，昭然可見矣。周德既衰而奢侈，宣王賢而中興，更為儉宮室，小寢廟。詩人美之，斯干之詩是也，〔一〕上章道宮室之如制，下章言子孫之眾多也。〔二〕及魯嚴公〔三〕刻飾宗廟，多築臺囿，〔四〕後嗣再絕，〔五〕春秋刺焉。周宣如彼而昌，魯、秦如此而絕，是則奢儉之得失也。","sentenceOrder":279},
  {"id":"s_work_han_thu_47_280","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「小雅篇名，美宣王考室。其首章曰『秩秩斯干』。秩秩，流行也。干，澗也。喻宣王之德如澗水源，秩秩流出，無極已也。」","sentenceOrder":280},
  {"id":"s_work_han_thu_47_281","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「宮室如制，謂『殖殖其廷，有覺其楹，君子攸寧』也。子孫眾多，謂『維熊維羆，男子之祥；維虺維蛇，女子之祥』也。」","sentenceOrder":281},
  {"id":"s_work_han_thu_47_282","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「即莊公也。」","sentenceOrder":282},
  {"id":"s_work_han_thu_47_283","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「解在五行志。」","sentenceOrder":283},
  {"id":"s_work_han_thu_47_284","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　孟康曰：「謂子般、閔公皆殺死也。」","sentenceOrder":284},
  {"id":"s_work_han_thu_47_285","chapterId":"ch_work_han_thu_47","textTraditional":"陛下即位，躬親節儉，始營初陵，其制約小，天下莫不稱賢明。及徙昌陵，增埤為高，〔一〕積土為山，發民墳墓，積以萬數，營起邑居，期日迫卒，〔二〕功費大萬百餘。〔三〕死者恨於下，生者愁於上，怨氣感動陰陽，因之以饑饉，物故流離以十萬數，〔四〕臣甚惛焉。〔五〕以死者為有知，發人之墓，其害多矣；若其無知，又安用大？〔六〕謀之賢知則不說，以示眾庶則苦之；〔七〕若苟以說愚夫淫侈之人，又何為哉！陛下慈仁篤美甚厚，聰明疏達蓋世，宜弘漢家之德，崇劉氏之美，光昭五帝、三王，而顧與暴秦亂君競為奢侈，比方丘隴，〔八〕說愚夫之目，隆一時之觀，違賢知之心，亡萬世之安，臣竊為陛下羞之。唯陛下上覽明聖黃帝、堯、舜、禹、湯、文、武、周公、仲尼之制，下觀賢知穆公、延陵、樗里、張釋之之意。孝文皇帝去墳薄葬，以儉安神，可以為則；秦昭、始皇增山厚臧，以侈生害，足以為戒。初陵之橅，宜從公卿大臣之議，〔九〕以息眾庶。","sentenceOrder":285},
  {"id":"s_work_han_thu_47_286","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「埤，下也，音婢。」","sentenceOrder":286},
  {"id":"s_work_han_thu_47_287","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「卒讀曰猝。」","sentenceOrder":287},
  {"id":"s_work_han_thu_47_288","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　應劭曰：「大萬，億也。大，巨也。」","sentenceOrder":288},
  {"id":"s_work_han_thu_47_289","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「物故，謂死也。流離，謂亡其居處也。」","sentenceOrder":289},
  {"id":"s_work_han_thu_47_290","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「惛謂不了，言惑於此事也。惛音昏。一曰，惛，古閔字，憂病也。」","sentenceOrder":290},
  {"id":"s_work_han_thu_47_291","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「安，焉也。」","sentenceOrder":291},
  {"id":"s_work_han_thu_47_292","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　師古曰：「說讀曰悅。其下亦同。」","sentenceOrder":292},
  {"id":"s_work_han_thu_47_293","chapterId":"ch_work_han_thu_47","textTraditional":"〔八〕　師古曰：「顧猶反也。」","sentenceOrder":293},
  {"id":"s_work_han_thu_47_294","chapterId":"ch_work_han_thu_47","textTraditional":"〔九〕　應劭曰：「橅音規摹之摹。」師古曰：「謂規度墓地，應音是也。韋玄成傳及蕭望之傳規橅音（議）〔義〕皆同，其字從木。」","sentenceOrder":294},
  {"id":"s_work_han_thu_47_295","chapterId":"ch_work_han_thu_47","textTraditional":"書奏，上甚感向言，而不能從其計。","sentenceOrder":295},
  {"id":"s_work_han_thu_47_296","chapterId":"ch_work_han_thu_47","textTraditional":"向睹俗彌奢淫，而趙、衛之屬起微賤，踰禮制。〔一〕向以為王教由內及外，自近者始。故採取詩書所載賢妃貞婦，興國顯家可法則，及孽嬖亂亡者，〔二〕序次為列女傳，凡八篇，以戒天子。及采傳記行事，著新序、說苑凡五十篇奏之。數上疏言得失，陳法戒。書數十上，以助觀覽，補遺闕。上雖不能盡用，然內嘉其言，常嗟歎之。","sentenceOrder":296},
  {"id":"s_work_han_thu_47_297","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「趙皇后、昭儀、衛婕妤也。」","sentenceOrder":297},
  {"id":"s_work_han_thu_47_298","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「孽，庶也。嬖，愛也。嬖音必計反。」","sentenceOrder":298},
  {"id":"s_work_han_thu_47_299","chapterId":"ch_work_han_thu_47","textTraditional":"時上無繼嗣，政由王氏出，災異〈浸，右下加“巾”〉甚。〔一〕向雅奇陳湯智謀，與相親友，獨謂湯曰：「災異如此，而外家日（甚）〔盛〕，其漸必危劉氏。吾幸得同姓末屬，絫世蒙漢厚恩，〔二〕身為宗室遺老，歷事三主。上以我先帝舊臣，每進見常加優禮，吾而不言，孰當言者？」〔三〕向遂上封事極諫曰：","sentenceOrder":299},
  {"id":"s_work_han_thu_47_300","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「〈浸，右下加“巾”〉，漸也。」","sentenceOrder":300},
  {"id":"s_work_han_thu_47_301","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「絫，古累字。」","sentenceOrder":301},
  {"id":"s_work_han_thu_47_302","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「孰，誰也。」","sentenceOrder":302},
  {"id":"s_work_han_thu_47_303","chapterId":"ch_work_han_thu_47","textTraditional":"臣聞人君莫不欲安，然而常危，莫不欲存，然而常亡，失御臣之術也。夫大臣操權柄，持國政，〔一〕未有不為害者也。昔晉有六卿，〔二〕齊有田、崔，衛有孫、甯，魯有季、孟，常掌國事，世執朝柄。終後田氏取齊；六卿分晉；崔杼弒其君光；孫林父、甯殖出其君衎，弒其君剽；〔三〕季氏八佾舞於庭，三家者以雍徹，〔四〕並專國政，卒逐昭公。周大夫尹氏筦朝事，〔五〕濁亂王室，子朝、子猛更立，連年乃定。〔六〕故經曰「王室亂」，又曰「尹氏殺王子克」，甚之也。〔七〕春秋舉成敗，錄禍福，如此類甚眾，皆陰盛而陽微，下失臣道之所致也。故書曰：「臣之有作威作福，害于而家，凶于而國。」〔八〕孔子曰「祿去公室，政逮大夫」，危亡之兆〔九〕。秦昭王舅穰侯及涇陽、葉陽君〔一０〕專國擅勢，上假太后之威，三人者權重於昭王，家富於秦國，國甚危殆，賴寤范睢之言，而秦復存。二世委任趙高，專權自恣，壅蔽大臣，終有閻樂望夷之禍〔一一〕，秦遂以亡。近事不遠，即漢所代也。","sentenceOrder":303},
  {"id":"s_work_han_thu_47_304","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「操，執也。音千高反。」","sentenceOrder":304},
  {"id":"s_work_han_thu_47_305","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　應劭曰：「智伯、范、中行、韓、魏、趙也。」","sentenceOrder":305},
  {"id":"s_work_han_thu_47_306","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「衎音口旦反。剽音匹照反。解在五行志。」","sentenceOrder":306},
  {"id":"s_work_han_thu_47_307","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「佾，列也，謂舞者之行列也。八人一佾，八佾六十四人也。雍，樂詩名，徹饌奏之。皆憯王者之禮。」","sentenceOrder":307},
  {"id":"s_work_han_thu_47_308","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「筦與管同。」","sentenceOrder":308},
  {"id":"s_work_han_thu_47_309","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「更音工衡反。解並在五行志。」","sentenceOrder":309},
  {"id":"s_work_han_thu_47_310","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　師古曰：「言其惡大甚也。」","sentenceOrder":310},
  {"id":"s_work_han_thu_47_311","chapterId":"ch_work_han_thu_47","textTraditional":"〔八〕　師古曰：「周書洪範也。而，汝也。言唯君得作威作福，臣下為之，則致凶害也。」","sentenceOrder":311},
  {"id":"s_work_han_thu_47_312","chapterId":"ch_work_han_thu_47","textTraditional":"〔九〕　李奇曰：「卿當為政，而反大夫為政也。」臣瓚曰：「政不由君，下及大夫也。上大夫即卿也。」師古曰：「瓚說是也。論語孔子曰：『祿去公室五君矣，政逮於大夫四君矣，故三桓之子孫微矣。」","sentenceOrder":312},
  {"id":"s_work_han_thu_47_313","chapterId":"ch_work_han_thu_47","textTraditional":"〔一０〕鄭氏曰：「皆昭王母之弟也。」師古曰：「穰侯，魏冉也。涇陽、葉陽，皆其弟也。葉音式涉反。」","sentenceOrder":313},
  {"id":"s_work_han_thu_47_314","chapterId":"ch_work_han_thu_47","textTraditional":"〔一一〕鄭氏曰：「望夷，秦宮名也。」應劭曰：「秦二世齋於望夷之宮，閻樂以兵殺二世也。」師古曰：「博物志云宮在長陵西北，長平觀道東，臨涇水，作之以望北夷。此說非也。胡亥葬於宜春苑，苑不在渭北也。」","sentenceOrder":314},
  {"id":"s_work_han_thu_47_315","chapterId":"ch_work_han_thu_47","textTraditional":"漢興，諸呂無道，擅相尊王。呂產、呂祿席太后之寵，據將相之位，〔一〕兼南北軍之眾，擁梁、趙王之尊，驕盈無厭，欲危劉氏。賴忠正大臣絳侯、朱虛侯等竭誠盡節以誅滅之，然後劉氏復安。今王氏一姓乘朱輪華轂者二十三人，青紫貂蟬充盈幄內，魚鱗左右。〔二〕大將軍秉事用權，五侯驕奢僭盛，並作威福，擊斷自恣，行汙而寄治，身私而託公，〔三〕依東宮之尊，假甥舅之親，以為威重。〔四〕尚書九卿州牧郡守皆出其門，〔五〕筦執樞機，朋黨比周。稱譽者登進，忤恨者誅傷；游談者助之說，執政者為之言。排擯宗室，孤弱公族，其有智能者，尤非毀而不進。遠絕宗室之任，不令得給事朝省，恐其與己分權；數稱燕王、蓋主以疑上心，〔六〕避諱呂、霍而弗肯稱。〔七〕內有管、蔡之萌，外假周公之論，兄弟據重，宗族磐互。〔八〕歷上古至秦漢，外戚僭貴未有如王氏者也。雖周皇甫、秦穰侯、漢武安、呂、霍、上官之屬，皆不及也。〔九〕","sentenceOrder":315},
  {"id":"s_work_han_thu_47_316","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「席猶因也，言若人之坐於席也。」","sentenceOrder":316},
  {"id":"s_work_han_thu_47_317","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「言在帝之左右，相次若魚鱗也。」","sentenceOrder":317},
  {"id":"s_work_han_thu_47_318","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「寄，託也。內為汙私之行，而外託治公之道也。」","sentenceOrder":318},
  {"id":"s_work_han_thu_47_319","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「東宮，太后所居也。」","sentenceOrder":319},
  {"id":"s_work_han_thu_47_320","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「言為其僚吏者皆居顯要之職。」","sentenceOrder":320},
  {"id":"s_work_han_thu_47_321","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「示宗室親近而反逆也。」","sentenceOrder":321},
  {"id":"s_work_han_thu_47_322","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　師古曰：「呂后、霍后二家皆坐僭擅誅滅，故為王氏諱而不言也。」","sentenceOrder":322},
  {"id":"s_work_han_thu_47_323","chapterId":"ch_work_han_thu_47","textTraditional":"〔八〕　師古曰：「磐結而交互也。字或作牙，謂若犬牙相交入之意也。」","sentenceOrder":323},
  {"id":"s_work_han_thu_47_324","chapterId":"ch_work_han_thu_47","textTraditional":"〔九〕　師古曰：「皇甫，周卿士字也，周后寵之，故處於盛位，權黨於朝，詩人刺之。事見小雅十月之交篇。武安侯，田蚡也。」","sentenceOrder":324},
  {"id":"s_work_han_thu_47_325","chapterId":"ch_work_han_thu_47","textTraditional":"物盛必有非常之變先見，為其人微象。孝昭帝時，冠石立於泰山，〔一〕仆柳起於上林。〔二〕而孝宣帝即位，今王氏先祖墳墓在濟南者，其梓柱生枝葉，扶疏上出屋，根垂地中，雖立石起柳，無以過此之明也。事勢不兩大，王氏與劉氏亦且不並立，如下有泰山之安，則上有累卵之危。陛下為人子孫，守持宗廟，而令國祚移於外親，降為皁隸，〔三〕縱不為身，奈宗廟何！婦人內夫家，外父母家，此亦非皇太后之福也。〔四〕孝宣皇帝不與舅平昌、樂昌侯權，所以安全之也。","sentenceOrder":325},
  {"id":"s_work_han_thu_47_326","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　晉灼曰：「漢注冠山石名。」臣瓚曰：「冠山下有石自立，三石為足，一石在上，故曰冠石也。」師古曰：「事具在眭孟傳。」","sentenceOrder":326},
  {"id":"s_work_han_thu_47_327","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「其樹已死，僵仆於地，而更起生，事亦具在眭孟傳。」","sentenceOrder":327},
  {"id":"s_work_han_thu_47_328","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「皁隸，卑賤之人也。春秋左氏傳曰『大夫臣士，士臣皁，皁臣輿，輿臣隸』也。」","sentenceOrder":328},
  {"id":"s_work_han_thu_47_329","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　如淳曰：「內猶親也，而皇太后反外夫家也。」","sentenceOrder":329},
  {"id":"s_work_han_thu_47_330","chapterId":"ch_work_han_thu_47","textTraditional":"夫明者起福於無形，銷患於未然。宜發明詔，吐德音，援近宗室，親而納信，〔一〕黜遠外戚，毋授以政，〔二〕皆罷令就弟，以則效先帝之所行，厚安外戚，全其宗族，誠東宮之意，外家之福也。王氏永存，保其爵祿，劉氏長安，不失社稷，所以褒睦外內之姓，子子孫孫無疆之計也。如不行此策，田氏復見於今，六卿必起於漢，〔三〕為後嗣憂，昭昭甚明，不可不深圖，不可不蚤慮。〔四〕易曰：「君不密，則失臣；臣不密，則失身；幾事不密，則害成。」〔五〕唯陛下深留聖思，審固幾密，覽往事之戒，以折中取信，居萬安之實，用保宗廟，久承皇太后，〔六〕天下幸甚。","sentenceOrder":330},
  {"id":"s_work_han_thu_47_331","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「援，引也，謂升引而附近之也。援音爰。」","sentenceOrder":331},
  {"id":"s_work_han_thu_47_332","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「遠謂疏而離之也。音于萬反。」","sentenceOrder":332},
  {"id":"s_work_han_thu_47_333","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「如，若也。」","sentenceOrder":333},
  {"id":"s_work_han_thu_47_334","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「蚤，古早字。」","sentenceOrder":334},
  {"id":"s_work_han_thu_47_335","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「上繫之辭也。」","sentenceOrder":335},
  {"id":"s_work_han_thu_47_336","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「言社稷不安，則帝身亦不得久事皇太后也。」","sentenceOrder":336},
  {"id":"s_work_han_thu_47_337","chapterId":"ch_work_han_thu_47","textTraditional":"書奏，天子召見向，歎息悲傷其意，謂曰：「君且休矣，吾將思之。」〔一〕以向為中壘校尉。","sentenceOrder":337},
  {"id":"s_work_han_thu_47_338","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「且令出外休息。」","sentenceOrder":338},
  {"id":"s_work_han_thu_47_339","chapterId":"ch_work_han_thu_47","textTraditional":"向為人簡易無威儀，廉靖樂道，不交接世俗，專積思於經術，晝誦書傳，夜觀星宿，或不寐達旦。元延中，星孛東井，蜀郡岷山崩雍江。〔一〕向惡此異，語在五行志。懷不能已，復上奏，其辭曰：","sentenceOrder":339},
  {"id":"s_work_han_thu_47_340","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「雍讀作壅。」","sentenceOrder":340},
  {"id":"s_work_han_thu_47_341","chapterId":"ch_work_han_thu_47","textTraditional":"臣聞帝舜戒伯禹，毋若丹朱敖；〔一〕周公戒成王，毋若殷王紂。〔二〕詩曰「殷監不遠，在夏后之世」，〔三〕亦言湯以桀為戒也。聖帝明王常以敗亂自戒，不諱廢興，故臣敢極陳其愚，唯陛下留神察焉。","sentenceOrder":341},
  {"id":"s_work_han_thu_47_342","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「事見虞書益稷篇。丹朱，堯子也。敖讀曰傲。」","sentenceOrder":342},
  {"id":"s_work_han_thu_47_343","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「事見周書亡逸篇。」","sentenceOrder":343},
  {"id":"s_work_han_thu_47_344","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「大雅蕩之詩。」","sentenceOrder":344},
  {"id":"s_work_han_thu_47_345","chapterId":"ch_work_han_thu_47","textTraditional":"謹案春秋二百四十二年，日蝕三十六，襄公尤數，率三歲五月有奇而壹食。〔一〕漢興訖竟寧，孝景帝尤數，率三歲一月而一食。臣向前數言日當食，今連三年比食。〔二〕自建始以來，二十歲間而八食，率二歲六月而一發，古今罕有。異有小大希稠，占有舒疾緩急，而聖人所以斷疑也。易曰：「觀乎天文，以察時變。」〔三〕昔孔子對魯哀公，並言夏桀、殷紂暴虐天下，故曆失則攝提失方，孟陬無紀，〔四〕此皆易姓之變也。秦始皇之末至二世時，日月薄食，山陵淪亡，辰星出於四孟，〔五〕太白經天而行，〔六〕無雲而雷〔七〕，枉矢夜光，〔八〕熒惑襲月，〔九〕〈薛女〉火燒宮，〔一０〕野禽戲廷，〔一一〕都門內崩，〔一二〕長人見臨洮，石隕于東郡，星孛大角，大角以亡。〔一三〕觀孔子之言，考暴秦之異，天命信可畏也。及項籍之敗，亦孛大角。漢之入秦，五星聚于東井，得天下之象也。孝惠時，有雨血，日食於衝，滅光星見之異。〔一四〕孝昭時，有泰山臥石自立，上林僵柳復起，大星如月西行，眾星隨之，此為特異。孝宣興起之表，天狗夾漢而西，〔一五〕久陰不雨者二十餘日，昌邑不終之異也。皆著於漢紀。觀秦、漢之易世，覽惠、昭之無後，察昌邑之不終，視孝宣之紹起，天之去就，豈不昭昭然哉！高宗、成王亦有雊雉拔木之變，能思其故，故高宗有百年之福，成王有復風之報。〔一六〕神明之應，應若景嚮，〔一七〕世所同聞也。","sentenceOrder":345},
  {"id":"s_work_han_thu_47_346","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「奇謂成數之餘，不滿者也。音居宜反。」","sentenceOrder":346},
  {"id":"s_work_han_thu_47_347","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「比，頻也。」","sentenceOrder":347},
  {"id":"s_work_han_thu_47_348","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「賁彖辭也。」","sentenceOrder":348},
  {"id":"s_work_han_thu_47_349","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　孟康曰：「攝提，星名也。隨斗杓建十二月，曆不正，則失其所建。首時為孟，正月為陬。」師古曰：「陬音子侯反，又音鄒。」","sentenceOrder":349},
  {"id":"s_work_han_thu_47_350","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「四時之孟月也。當見四仲也。」","sentenceOrder":350},
  {"id":"s_work_han_thu_47_351","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　孟康曰：「謂出東入西，出西入東也。太白陰星，出東當伏東，出西當伏西。過午為經天也。」","sentenceOrder":351},
  {"id":"s_work_han_thu_47_352","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　張晏曰：「雷當託雲，猶君之託臣也。二世不恤天下，人有畔心，象獨號令而無臣也。」","sentenceOrder":352},
  {"id":"s_work_han_thu_47_353","chapterId":"ch_work_han_thu_47","textTraditional":"〔八〕　應劭曰：「流星也，其射如矢，蛇行不正，故曰枉矢流，以亂伐亂。」蘇林曰：「有聲為天狗，無聲為枉矢也。」","sentenceOrder":353},
  {"id":"s_work_han_thu_47_354","chapterId":"ch_work_han_thu_47","textTraditional":"〔九〕　應劭曰：「熒惑主內亂，月主刑，故趙高殺二世也。」","sentenceOrder":354},
  {"id":"s_work_han_thu_47_355","chapterId":"ch_work_han_thu_47","textTraditional":"〔一０〕師古曰：「〈薛女〉，災也。」","sentenceOrder":355},
  {"id":"s_work_han_thu_47_356","chapterId":"ch_work_han_thu_47","textTraditional":"〔一一〕張晏曰：「野鳥入處，主人將去。」","sentenceOrder":356},
  {"id":"s_work_han_thu_47_357","chapterId":"ch_work_han_thu_47","textTraditional":"〔一二〕師古曰：「內嚮而壞。」","sentenceOrder":357},
  {"id":"s_work_han_thu_47_358","chapterId":"ch_work_han_thu_47","textTraditional":"〔一三〕應劭曰：「天王坐席也。流星茀大角，大角因伏不見也。」","sentenceOrder":358},
  {"id":"s_work_han_thu_47_359","chapterId":"ch_work_han_thu_47","textTraditional":"〔一四〕孟康曰：「日月行交道之衝也。相薄而既也，京房所謂陰氣盛，薄奪日光者也。」","sentenceOrder":359},
  {"id":"s_work_han_thu_47_360","chapterId":"ch_work_han_thu_47","textTraditional":"〔一五〕李奇曰：「流星也。下墮地為天狗，皆祅星。」","sentenceOrder":360},
  {"id":"s_work_han_thu_47_361","chapterId":"ch_work_han_thu_47","textTraditional":"〔一六〕師古曰：「復，反也。事並見尚書高宗肜日及金滕篇，解在五行志。」","sentenceOrder":361},
  {"id":"s_work_han_thu_47_362","chapterId":"ch_work_han_thu_47","textTraditional":"〔一七〕師古曰：「嚮讀曰響。」","sentenceOrder":362},
  {"id":"s_work_han_thu_47_363","chapterId":"ch_work_han_thu_47","textTraditional":"臣幸得託末屬，誠見陛下有寬明之德，冀銷大異，而興高宗、成王之聲，以崇劉氏，故豤豤數奸死亡之誅。〔一〕今日食尤屢，星孛東井，攝提炎及紫宮，〔二〕有識長老莫不震動，此變之大者也。其事難一二記，故易曰「書不盡言，言不盡意」，〔三〕是以設卦指爻，而復說義。書曰「伻來以圖」，〔四〕天文難以相曉，臣雖圖上，猶須口說，然後可知，願賜清燕之閒，〔五〕指圖陳狀。","sentenceOrder":363},
  {"id":"s_work_han_thu_47_364","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「豤豤，款誠之意也。奸，犯也。豤音懇。奸音干。」","sentenceOrder":364},
  {"id":"s_work_han_thu_47_365","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「炎音弋贍反。」","sentenceOrder":365},
  {"id":"s_work_han_thu_47_366","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「上繫之辭。」","sentenceOrder":366},
  {"id":"s_work_han_thu_47_367","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　孟康曰：「伻，使也。使人以圖來示成王，明（曰）〔口〕說不了，指圖乃了也。」師古曰：「周書洛誥之辭。」","sentenceOrder":367},
  {"id":"s_work_han_thu_47_368","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「閒讀曰閑。」","sentenceOrder":368},
  {"id":"s_work_han_thu_47_369","chapterId":"ch_work_han_thu_47","textTraditional":"上輒入之，〔一〕然終不能用也。向每召見，數言公族者國之枝葉，枝葉落則本根無所庇廕；〔二〕方今同姓疏遠，母黨專政，祿去公室，權在外家，非所以彊漢宗，卑私門，保守社稷，安固後嗣也。","sentenceOrder":369},
  {"id":"s_work_han_thu_47_370","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「謂召入也。」","sentenceOrder":370},
  {"id":"s_work_han_thu_47_371","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「庇音必寐反。廕音於禁反。」","sentenceOrder":371},
  {"id":"s_work_han_thu_47_372","chapterId":"ch_work_han_thu_47","textTraditional":"向自見得信於上，故常顯訟宗室，譏刺王氏及在位大臣，其言多痛切，發於至誠。上數欲用向為九卿，輒不為王氏居位者及丞相御史所持，故終不遷。〔一〕居列大夫官前後三十餘年，年七十二卒。卒後十三歲而王氏代漢。向三子皆好學：長子伋，〔二〕以易教授，官至郡守；中子賜，九卿丞，蚤卒；少子歆，最知名。","sentenceOrder":372},
  {"id":"s_work_han_thu_47_373","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「持謂扶持佐助也。」","sentenceOrder":373},
  {"id":"s_work_han_thu_47_374","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「伋音汲。」","sentenceOrder":374},
  {"id":"s_work_han_thu_47_375","chapterId":"ch_work_han_thu_47","textTraditional":"歆字子駿，少以通詩書能屬文召見成帝，待詔宦者署，為黃門郎。河平中，受詔與父向領校祕書，講六藝傳記，諸子、詩賦、數術、方技，無所不究。向死後，歆復為中壘校尉。","sentenceOrder":375},
  {"id":"s_work_han_thu_47_376","chapterId":"ch_work_han_thu_47","textTraditional":"哀帝初即位，大司馬王莽舉歆宗室有材行，為侍中太中大夫，遷騎都尉、奉車光祿大夫，貴幸。復領五經，卒父前業。歆乃集六藝群書，種別為七略。語在藝文志。","sentenceOrder":376},
  {"id":"s_work_han_thu_47_377","chapterId":"ch_work_han_thu_47","textTraditional":"歆及向始皆治易，宣帝時，詔向受穀梁春秋，十餘年，大明習。及歆校秘書，見古文春秋左氏傳，歆大好之。時丞相史尹咸以能治左氏，與歆共校經傳。歆略從咸及丞相翟方進受，質問大義。〔一〕初左氏傳多古字古言，學者傳訓故而已，〔二〕及歆治左氏，引傳文以解經，轉相發明，由是章句義理備焉。歆亦湛靖有謀，〔三〕父子俱好古，博見彊志，〔四〕過絕於人。歆以為左丘明好惡與聖人同〔五〕，親見夫子，而公羊、穀梁在七十子後，〔六〕傳聞之與親見之，其詳略不同。歆數以難向，向不能非間也，〔七〕然猶自持其穀梁義。及歆親近，欲建立左氏春秋及毛詩、逸禮、古文尚書皆列於學官。哀帝令歆與五經博士講論其義，諸博士或不肯置對，〔八〕歆因移書太常博士，責讓之曰：","sentenceOrder":377},
  {"id":"s_work_han_thu_47_378","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「質，正也。」","sentenceOrder":378},
  {"id":"s_work_han_thu_47_379","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「故謂指趣也。」","sentenceOrder":379},
  {"id":"s_work_han_thu_47_380","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「湛讀曰沈。」","sentenceOrder":380},
  {"id":"s_work_han_thu_47_381","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「志，記也。」","sentenceOrder":381},
  {"id":"s_work_han_thu_47_382","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「論語載孔子曰：『巧言令色足恭，左丘明恥之，丘亦恥之；匿怨而友其人，左丘明恥之，丘亦恥之。』」","sentenceOrder":382},
  {"id":"s_work_han_thu_47_383","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「七十子是孔子弟子也，實七十二人，指其（言成數）〔成數言〕也。」","sentenceOrder":383},
  {"id":"s_work_han_thu_47_384","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　師古曰：「間音居莧反。」","sentenceOrder":384},
  {"id":"s_work_han_thu_47_385","chapterId":"ch_work_han_thu_47","textTraditional":"〔八〕　師古曰：「並不與歆意同，故不肯立其學也。置對，置辭以對也。」","sentenceOrder":385},
  {"id":"s_work_han_thu_47_386","chapterId":"ch_work_han_thu_47","textTraditional":"昔唐虞既衰，而三代迭興，〔一〕聖帝明王，累起相襲，其道甚著。周室既微而禮樂不正，道之難全也如此。是故孔子憂道之不行，歷國應聘。自衛反魯，然後樂正，雅頌乃得其所；修易，序書，制作春秋，以紀帝王之道。及夫子沒而微言絕，七十子終而大義乖。重遭戰國，棄籩豆之禮，理軍旅之陳，〔二〕孔氏之道抑，而孫吳之術興。陵夷至于暴秦，燔經書，殺儒士，設挾書之法，行是古之罪，〔三〕道術由是遂滅。漢興，去聖帝明王遐遠，仲尼之道又絕，法度無所因襲。時獨有一叔孫通略定禮儀，天下唯有易卜，未有它書。至孝惠之世，乃除挾書之律，然公卿大臣絳、灌之屬咸介冑武夫，莫以為意。至孝文皇帝，始使掌故朝錯〔四〕從伏生受尚書。尚書初出于屋壁，朽折散絕，今其書見在，時師傳讀而已。詩始萌牙。〔五〕天下眾書往往頗出，皆諸子傳說，猶廣立於學官，為置博士。在漢朝之儒，唯賈生而已。〔六〕至孝武皇帝，然後鄒、魯、梁、趙頗有詩、禮、春秋先師，〔七〕皆起於建元之間。當此之時，一人不能獨盡其經，或為雅，或為頌，相合而成。泰誓後得，博士集而讀之。故詔書稱曰：「禮壞樂崩，書缺簡脫，朕甚閔焉。」時漢興已七八十年，離於全經，固已遠矣。〔八〕","sentenceOrder":386},
  {"id":"s_work_han_thu_47_387","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「迭，互也。音大結反。」","sentenceOrder":387},
  {"id":"s_work_han_thu_47_388","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「籩豆，禮食之器也。以竹曰籩，以木曰豆。籩音邊。」","sentenceOrder":388},
  {"id":"s_work_han_thu_47_389","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「以古事為是者即罪之。」","sentenceOrder":389},
  {"id":"s_work_han_thu_47_390","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　李奇曰：「掌故，官名也。」","sentenceOrder":390},
  {"id":"s_work_han_thu_47_391","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「言若草木之初生。」","sentenceOrder":391},
  {"id":"s_work_han_thu_47_392","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「謂賈誼。」","sentenceOrder":392},
  {"id":"s_work_han_thu_47_393","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　師古曰：「前學之師也。」","sentenceOrder":393},
  {"id":"s_work_han_thu_47_394","chapterId":"ch_work_han_thu_47","textTraditional":"〔八〕　師古曰：「言廢絕以久，不可得其真也。」","sentenceOrder":394},
  {"id":"s_work_han_thu_47_395","chapterId":"ch_work_han_thu_47","textTraditional":"及魯恭王壞孔子宅，欲以為宮，而得古文於壞壁之中，逸禮有三十九，書十六篇。天漢之後，孔安國獻之，遭巫蠱倉卒之難，未及施行。及春秋左氏丘明所修，皆古文舊書，多者二十餘通，臧於祕府，伏而未發。孝成皇帝閔學殘文缺，稍離其真，乃陳發祕臧，校理舊文，得此三事，以考學官所傳，經或脫簡，傳或間編。〔一〕傳問民間，則有魯國（柏）〔桓〕公、趙國貫公、膠東庸生之遺學與此同，抑而未施。此乃有識者之所惜閔，士君子之所嗟痛也。往者綴學之士不思廢絕之闕，苟因陋就寡，分文析字，煩言碎辭，學者罷老且不能究其一藝。〔二〕信口說而背傳記，是末師而非往古，至於國家將有大事，若立辟雍封禪巡狩之儀，則幽冥而莫知其原。〔三〕猶欲保殘守缺，挾恐見破之私意，而無從善服義之公心，或懷妒嫉，不考情實，雷同相從，隨聲是非，抑此三學，以尚書為備，〔四〕謂左氏為不傳春秋，豈不哀哉！","sentenceOrder":395},
  {"id":"s_work_han_thu_47_396","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「脫簡，遺失之。間編，謂舊編爛絕，就更次之，前後錯亂也。間音古莧反。」","sentenceOrder":396},
  {"id":"s_work_han_thu_47_397","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「罷讀曰疲。究，竟也。」","sentenceOrder":397},
  {"id":"s_work_han_thu_47_398","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「幽冥猶暗昧也。」","sentenceOrder":398},
  {"id":"s_work_han_thu_47_399","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　蘇林曰：「備之而已。」臣瓚曰：「當時學者，謂尚書唯有二十八篇，不知本（存）〔有〕百篇也。」師古曰：「瓚說是也。」","sentenceOrder":399},
  {"id":"s_work_han_thu_47_400","chapterId":"ch_work_han_thu_47","textTraditional":"今聖上德通神明，繼統揚業，亦閔文學錯亂，學士若茲，雖昭其情，猶依違謙讓，〔一〕樂與士君子同之。故下明詔，試左氏可立不，遣近臣奉指銜命，將以輔弱扶微，與二三君子比意同力，冀得廢遺。〔二〕今則不然，深閉固距，而不肯試，猥以不誦絕之，〔三〕欲以杜塞餘道，絕滅微學。夫可與樂成，難與慮始，此乃眾庶之所為耳，非所望士君子也。且此數家之事，皆先帝所親論，今上所考視，其古文舊書，皆有徵驗，外內相應，豈苟而已哉！","sentenceOrder":400},
  {"id":"s_work_han_thu_47_401","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「依違，言不專決也。」","sentenceOrder":401},
  {"id":"s_work_han_thu_47_402","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「比，合也。經藝有廢遺者，冀得興立之也。比音頻寐反。」","sentenceOrder":402},
  {"id":"s_work_han_thu_47_403","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「猥，苟也。苟不誦習之，而欲絕去此學。」","sentenceOrder":403},
  {"id":"s_work_han_thu_47_404","chapterId":"ch_work_han_thu_47","textTraditional":"夫禮失求之於野，古文不猶愈於野乎？〔一〕往者博士書有歐陽，春秋公羊，易則施、孟，然孝宣皇帝猶復廣立穀梁春秋，梁丘易，大小夏侯尚書，義雖相反，猶並置之。何則？與其過而廢之也，寧過而立之。〔二〕傳曰：「文武之道未墜於地，在人；賢者志其大者，不賢者志其小者。」〔三〕今此數家之言所以兼包大小之義，豈可偏絕哉！若必專己守殘，〔四〕黨同門，妒道真，〔五〕違明詔，失聖意，以陷於文吏之議，甚為二三君子不取也。","sentenceOrder":404},
  {"id":"s_work_han_thu_47_405","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「愈，勝也。」","sentenceOrder":405},
  {"id":"s_work_han_thu_47_406","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「過猶誤。」","sentenceOrder":406},
  {"id":"s_work_han_thu_47_407","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「論語孔子弟子子貢之言。志，識也，一曰記。」","sentenceOrder":407},
  {"id":"s_work_han_thu_47_408","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「專執己所偏見，苟守殘缺之文也。」","sentenceOrder":408},
  {"id":"s_work_han_thu_47_409","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「黨同師之學，妒道藝之真也。」","sentenceOrder":409},
  {"id":"s_work_han_thu_47_410","chapterId":"ch_work_han_thu_47","textTraditional":"其言甚切，諸儒皆怨恨。是時名儒光祿大夫龔勝以歆移書上疏深自罪責，願乞骸骨罷。及儒者師丹為大司空，亦大怒，奏歆改亂舊章，非毀先帝所立。上曰：「歆欲廣道術，亦何以為非毀哉？」歆由是忤執政大臣，為眾儒所訕，〔一〕懼誅，求出補吏，為河內太守。以宗室不宜典三河，徙守五原，後復轉在涿郡，歷三郡守。數年，以病免官，起家復為安定屬國都尉。會哀帝崩，王莽持政，莽少與歆俱為黃門郎，重之，白太后。太后留歆為右曹太中大夫，遷中壘校尉，羲和，京兆尹，使治明堂辟雍，封紅休侯。典儒林史卜之官，考定律曆，著三統曆譜。","sentenceOrder":410},
  {"id":"s_work_han_thu_47_411","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「訕，謗也，音所諫反。」","sentenceOrder":411},
  {"id":"s_work_han_thu_47_412","chapterId":"ch_work_han_thu_47","textTraditional":"初，歆以建平元年改名秀，字穎叔云。〔一〕及王莽篡位，歆為國師，後事皆在莽傳。","sentenceOrder":412},
  {"id":"s_work_han_thu_47_413","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　應劭曰：「河圖赤伏符云『劉秀發兵捕不道，四夷雲集龍鬥野，四七之際火為主』，故改名，幾以趣也。」","sentenceOrder":413},
  {"id":"s_work_han_thu_47_414","chapterId":"ch_work_han_thu_47","textTraditional":"贊曰：仲尼稱「材難不其然與！」〔一〕自孔子後，綴文之士眾矣，唯孟軻、孫況，董仲舒、司馬遷、劉向、揚雄。〔二〕此數公者，皆博物洽聞，通達古今，其言有補於世。傳曰「聖人不出，其間必有命世者焉」，豈近是乎？〔三〕劉氏洪範論發明大傳，著天人之應；七略剖判藝文，總百家之緒；三統曆譜考步日月五星之度。有意其推本之也。〔四〕嗚虖！向言山陵之戒，于今察之，〔五〕哀哉！指明梓柱以推廢興，昭矣！〔六〕豈非直諒多聞，古之益友與！〔七〕","sentenceOrder":414},
  {"id":"s_work_han_thu_47_415","chapterId":"ch_work_han_thu_47","textTraditional":"〔一〕　師古曰：「論語載孔子之言也。賢材難得。與讀曰歟。」","sentenceOrder":415},
  {"id":"s_work_han_thu_47_416","chapterId":"ch_work_han_thu_47","textTraditional":"〔二〕　師古曰：「孫況即荀卿也。」","sentenceOrder":416},
  {"id":"s_work_han_thu_47_417","chapterId":"ch_work_han_thu_47","textTraditional":"〔三〕　師古曰：「近音其靳反。」","sentenceOrder":417},
  {"id":"s_work_han_thu_47_418","chapterId":"ch_work_han_thu_47","textTraditional":"〔四〕　師古曰：「言其究極根本，深有意也。」","sentenceOrder":418},
  {"id":"s_work_han_thu_47_419","chapterId":"ch_work_han_thu_47","textTraditional":"〔五〕　師古曰：「虖讀曰呼。」","sentenceOrder":419},
  {"id":"s_work_han_thu_47_420","chapterId":"ch_work_han_thu_47","textTraditional":"〔六〕　師古曰：「昭然明白。」","sentenceOrder":420},
  {"id":"s_work_han_thu_47_421","chapterId":"ch_work_han_thu_47","textTraditional":"〔七〕　師古曰：「諒，信也。論語稱孔子曰『益者三友，友直，友諒，友多聞，益矣。』贊言向直諒多聞，可謂益矣。與讀曰歟。」","sentenceOrder":421},
  {"id":"s_work_han_thu_47_422","chapterId":"ch_work_han_thu_47","textTraditional":"校勘記","sentenceOrder":422},
  {"id":"s_work_han_thu_47_423","chapterId":"ch_work_han_thu_47","textTraditional":"一九二五頁　五行　故為其（後）〔后〕母弟趙何齊取廣陵王女為妻。　宋祁說「後」疑是「后」字。楊樹達說宋。說是","sentenceOrder":423},
  {"id":"s_work_han_thu_47_424","chapterId":"ch_work_han_thu_47","textTraditional":"一九二七頁　一行　德字路叔（少），修黃老術，　景祐、殿本都無「叔」字。王念孫說「叔」字誤為「少」，「少」字與下文「少時」重複，不當有……","sentenceOrder":424},
  {"id":"s_work_han_thu_47_425","chapterId":"ch_work_han_thu_47","textTraditional":"一九三一頁一一行　興謂改作（慮）〔憲〕章。　景祐、殿本都作「憲」。　王先謙說作「憲」是。","sentenceOrder":425},
  {"id":"s_work_han_thu_47_426","chapterId":"ch_work_han_thu_47","textTraditional":"一九三四頁　二行　（作）〔益〕朕虞，　景祐、殿本都作「益」。　王先謙說作「益」是。","sentenceOrder":426},
  {"id":"s_work_han_thu_47_427","chapterId":"ch_work_han_thu_47","textTraditional":"一九三四頁一０行　言有此賓客以和而來至（也）〔止〕而敬者，　殿本作「至止」。王先謙說殿本是。","sentenceOrder":427},
  {"id":"s_work_han_thu_47_428","chapterId":"ch_work_han_thu_47","textTraditional":"一九三六頁　九行　急恆寒（苦）〔若〕之災也。　景祐、殿本都作「若」。　王先謙說作「若」是。","sentenceOrder":428},
  {"id":"s_work_han_thu_47_429","chapterId":"ch_work_han_thu_47","textTraditional":"一九三七頁一四行　閔公（三）〔二〕年，　景祐、殿本都作「二」。王先謙說作「二」是。","sentenceOrder":429},
  {"id":"s_work_han_thu_47_430","chapterId":"ch_work_han_thu_47","textTraditional":"一九四０頁一五行　十七年楚滅舒（蕭）〔庸〕；　景祐、殿本作「庸」。　王先謙說作「庸」是。","sentenceOrder":430},
  {"id":"s_work_han_thu_47_431","chapterId":"ch_work_han_thu_47","textTraditional":"一九四五頁　一行　九（四）〔五〕爻辭也。　景祐、殿本都作「五」，此誤。","sentenceOrder":431},
  {"id":"s_work_han_thu_47_432","chapterId":"ch_work_han_thu_47","textTraditional":"一九四七頁　四行　以（效）〔救〕今事一二，　景祐、殿本都作「救」。","sentenceOrder":432},
  {"id":"s_work_han_thu_47_433","chapterId":"ch_work_han_thu_47","textTraditional":"一九四七頁一０行　朝臣齗齗不可光祿勳，何（也）〔邪〕？　景祐、殿本都作「邪」。","sentenceOrder":433},
  {"id":"s_work_han_thu_47_434","chapterId":"ch_work_han_thu_47","textTraditional":"一九四八頁一三行　顯幹尚書〔事〕，　殿本有「事」字。王先謙說據注文當有。","sentenceOrder":434},
  {"id":"s_work_han_thu_47_435","chapterId":"ch_work_han_thu_47","textTraditional":"一九五二頁　四行　謂不寘器（衛）〔備〕而薄葬，　景祐、殿本都作「備」。","sentenceOrder":435},
  {"id":"s_work_han_thu_47_436","chapterId":"ch_work_han_thu_47","textTraditional":"一九五三頁一０行　古〔者〕不修墓。　景祐、殿本都有「者」字。","sentenceOrder":436},
  {"id":"s_work_han_thu_47_437","chapterId":"ch_work_han_thu_47","textTraditional":"一九五七頁一二行　規橅音（議）〔義〕皆同，　景祐、殿、局本都作「義」，此誤。","sentenceOrder":437},
  {"id":"s_work_han_thu_47_438","chapterId":"ch_work_han_thu_47","textTraditional":"一九五八頁　六行　而外家日（甚）〔盛〕，　景祐、殿本都作「盛」。王先謙說作「盛」是。","sentenceOrder":438},
  {"id":"s_work_han_thu_47_439","chapterId":"ch_work_han_thu_47","textTraditional":"一九六六頁　六行　明（曰）〔口〕說不了，　景祐、殿本都作「口」。王先謙說作「口」是。","sentenceOrder":439},
  {"id":"s_work_han_thu_47_440","chapterId":"ch_work_han_thu_47","textTraditional":"一九六八頁　六行　指其（言成數）〔成數言〕也。　殿本作「成數言」。王先謙說殿本是。","sentenceOrder":440},
  {"id":"s_work_han_thu_47_441","chapterId":"ch_work_han_thu_47","textTraditional":"一九七０頁　二行　則有魯國（柏）〔桓〕公、　王先謙說「柏」當作「桓」。按殿本作「桓」，景祐本亦作「柏」。","sentenceOrder":441},
  {"id":"s_work_han_thu_47_442","chapterId":"ch_work_han_thu_47","textTraditional":"一九七０頁一一行　不知本（存）〔有〕百篇也。　景祐、殿本都作「有」。王先謙說作「有」是。","sentenceOrder":442},
  {"id":"s_work_han_thu_48_1","chapterId":"ch_work_han_thu_48","textTraditional":"季布，楚人也，為任俠有名。〔一〕項籍使將兵，數窘漢王〔二〕。項籍滅，高祖購求布千金，敢有舍匿，罪三族。〔三〕布匿濮陽周氏，周氏曰：「漢求將軍急，跡且至臣家，〔四〕能聽臣，臣敢進計；即否，願先自剄。」布許之。乃髡鉗布，衣褐，〔五〕置廣柳車中，〔六〕并與其家僮數十人，之魯朱家所賣之。〔七〕朱家心知其季布也，買置田舍。乃之雒陽見汝陰侯滕公，〔八〕說曰：「季布何罪？臣各為其主用，職耳。〔九〕項氏臣豈可盡誅邪？今上始得天下，而以私怨求一人，何示不廣也！且以季布之賢，漢求之急如此，此不北走胡，南走越耳。夫忌壯士以資敵國，此伍子胥所以鞭荊平之墓也。〔一０〕君何不從容為上言之？」〔一一〕滕公心知朱家大俠，意布匿其所，乃許諾。侍間，果言如朱家指。〔一二〕上乃赦布。當是時，諸公皆多布能摧剛為柔，〔一三〕朱家亦以此名聞當世。布召見，謝，拜郎中。","sentenceOrder":1},
  {"id":"s_work_han_thu_48_2","chapterId":"ch_work_han_thu_48","textTraditional":"〔一〕　應劭曰：「任謂有堅完可任託以事也。」如淳曰：「相與信為任，同是非為俠。」師古曰：「任謂任使其氣力。俠之言挾也，以權力俠輔人也。任音人禁反。俠音下頰反。」","sentenceOrder":2},
  {"id":"s_work_han_thu_48_3","chapterId":"ch_work_han_thu_48","textTraditional":"〔二〕　如淳曰：「窘，困也。」師古曰：「窘音求閔反。」","sentenceOrder":3},
  {"id":"s_work_han_thu_48_4","chapterId":"ch_work_han_thu_48","textTraditional":"〔三〕　師古曰：「舍，止；匿，隱也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_48_5","chapterId":"ch_work_han_thu_48","textTraditional":"〔四〕　師古曰：「跡謂尋其蹤跡也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_48_6","chapterId":"ch_work_han_thu_48","textTraditional":"〔五〕　師古曰：「衣，著之也。褐，毛布之衣也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_48_7","chapterId":"ch_work_han_thu_48","textTraditional":"〔六〕　服虔曰：「東郡謂廣轍車為廣柳車。」鄭氏曰：「作大柳衣車，若周禮喪車也。」李奇曰：「廣柳，大隆穹也。」晉灼曰：「周禮說『衣翣柳』，柳，聚也，眾飾之所聚也。此為載以喪車，欲人不知也。」師古曰：「晉、鄭二說是也。隆穹，所謂車軬者耳，非此之謂也。軬音扶晚反。」","sentenceOrder":7},
  {"id":"s_work_han_thu_48_8","chapterId":"ch_work_han_thu_48","textTraditional":"〔七〕　師古曰：「朱家，魯人，見游俠傳。」","sentenceOrder":8},
  {"id":"s_work_han_thu_48_9","chapterId":"ch_work_han_thu_48","textTraditional":"〔八〕　師古曰：「夏侯嬰也，本為滕令，遂號為滕公。」","sentenceOrder":9},
  {"id":"s_work_han_thu_48_10","chapterId":"ch_work_han_thu_48","textTraditional":"〔九〕　師古曰：「職，常也。言此乃常道也。一曰職，主掌其事也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_48_11","chapterId":"ch_work_han_thu_48","textTraditional":"〔一０〕師古曰：「子胥，伍員也。荊即楚也。子胥之父伍奢為平王所殺，子胥奔吳，教吳伐楚。平王已卒，其後吳師入郢，子胥掘平王之墓，取屍鞭之三百也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_48_12","chapterId":"ch_work_han_thu_48","textTraditional":"〔一一〕師古曰：「從音千容反。」","sentenceOrder":12},
  {"id":"s_work_han_thu_48_13","chapterId":"ch_work_han_thu_48","textTraditional":"〔一二〕師古曰：「侍，侍於天子。間謂事務之隙。」","sentenceOrder":13},
  {"id":"s_work_han_thu_48_14","chapterId":"ch_work_han_thu_48","textTraditional":"〔一三〕師古曰：「多猶重也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_48_15","chapterId":"ch_work_han_thu_48","textTraditional":"孝惠時，為中郎將。單于嘗為書嫚呂太后，〔一〕太后怒，召諸將議之。上將軍樊噲曰：「臣願得十萬眾，橫行匈奴中。」諸將皆阿呂太后，〔二〕以噲言為然。布曰：「樊噲可斬也。夫以高帝兵三十餘萬，困於平城，噲時亦在其中。今噲奈何以十萬眾橫行匈奴中，面謾！〔三〕且秦以事胡，陳勝等起。今瘡痍未瘳，〔四〕噲又面諛，欲搖動天下。」是時殿上皆恐，太后罷朝，遂不復議擊匈奴事。","sentenceOrder":15},
  {"id":"s_work_han_thu_48_16","chapterId":"ch_work_han_thu_48","textTraditional":"〔一〕　師古曰：「嫚謂辭語褻污也。嫚讀與慢同。」","sentenceOrder":16},
  {"id":"s_work_han_thu_48_17","chapterId":"ch_work_han_thu_48","textTraditional":"〔一〕　師古曰：「阿，曲也，曲從其意。」","sentenceOrder":17},
  {"id":"s_work_han_thu_48_18","chapterId":"ch_work_han_thu_48","textTraditional":"〔三〕　師古曰：「謾，欺誑也，音嫚，又音莫連反。」","sentenceOrder":18},
  {"id":"s_work_han_thu_48_19","chapterId":"ch_work_han_thu_48","textTraditional":"〔四〕　師古曰：「痍，傷也。瘳，差也。痍音夷。瘳音丑留反。」","sentenceOrder":19},
  {"id":"s_work_han_thu_48_20","chapterId":"ch_work_han_thu_48","textTraditional":"布為河東守。孝文時，人有言其賢，召欲以為御史大夫。人又言其勇，使酒難近。〔一〕至，留邸一月，〔二〕見罷。〔三〕布進曰：「臣待罪河東，陛下無故召臣，此人必有以臣欺陛下者。〔四〕今臣至，無所受事，罷去，此人必有毀臣者。夫陛下以一人譽召臣，一人毀去臣，臣恐天下有識者聞之，有以窺陛下。」〔五〕上默然，慚曰：「河東吾股肱郡，故特召君耳。」布之官。","sentenceOrder":20},
  {"id":"s_work_han_thu_48_21","chapterId":"ch_work_han_thu_48","textTraditional":"〔一〕　應劭曰：「使酒，酗酒也。」師古曰：「言因酒霑洽而使氣也。近謂附近天子為大臣也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_48_22","chapterId":"ch_work_han_thu_48","textTraditional":"〔二〕　師古曰：「邸，諸郡朝宿之舍在京師也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_48_23","chapterId":"ch_work_han_thu_48","textTraditional":"〔三〕　師古曰：「既引見而罷，令還郡也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_48_24","chapterId":"ch_work_han_thu_48","textTraditional":"〔四〕　師古曰：「謂妄言其賢，故云欺也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_48_25","chapterId":"ch_work_han_thu_48","textTraditional":"〔五〕　師古曰：「窺見陛下淺深也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_48_26","chapterId":"ch_work_han_thu_48","textTraditional":"辯士曹丘生數招權顧金錢，〔一〕事貴人趙談等，〔二〕與竇長君善。〔三〕布聞，寄書諫長君曰：「吾聞曹丘生非長者，勿與通。」及曹丘生歸，欲得書請布。〔四〕竇長君曰：「季將軍不說足下，〔五〕足下無往。」固請書，遂行。使人先發書，〔六〕布果大怒，待曹丘。曹丘至，則揖布曰：「楚人諺曰『得黃金百，不如得季布諾』，〔七〕足下何以得此聲梁楚之間哉？且僕與足下俱楚人，使僕游揚足下名於天下，顧不美乎？〔八〕何足下距僕之深也！」布乃大說。〔九〕引入，留數月，為上客，厚送之。布名所以益聞者，曹丘揚之也。","sentenceOrder":26},
  {"id":"s_work_han_thu_48_27","chapterId":"ch_work_han_thu_48","textTraditional":"〔一〕　孟康曰：「招，求也。以金錢事權貴，而求得其形勢以自炫耀也。」李奇曰：「持權屬以請人，顧以金錢也。」師古曰：「二家之說皆非也。言招求貴人威權，因以請託，故得他人顧金錢也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_48_28","chapterId":"ch_work_han_thu_48","textTraditional":"〔二〕　李奇曰：「宦者趙談也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_48_29","chapterId":"ch_work_han_thu_48","textTraditional":"〔三〕　服虔曰：「景帝舅。」","sentenceOrder":29},
  {"id":"s_work_han_thu_48_30","chapterId":"ch_work_han_thu_48","textTraditional":"〔四〕　師古曰：「欲得竇長君書與布，為己紹介也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_48_31","chapterId":"ch_work_han_thu_48","textTraditional":"〔五〕　師古曰：「說讀曰悅。」","sentenceOrder":31},
  {"id":"s_work_han_thu_48_32","chapterId":"ch_work_han_thu_48","textTraditional":"〔六〕　師古曰：「使人先致書於布。發，視也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_48_33","chapterId":"ch_work_han_thu_48","textTraditional":"〔七〕　師古曰：「諺，傳也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_48_34","chapterId":"ch_work_han_thu_48","textTraditional":"〔八〕　師古曰：「顧，念也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_48_35","chapterId":"ch_work_han_thu_48","textTraditional":"〔九〕　師古曰：「說讀曰悅。」","sentenceOrder":35},
  {"id":"s_work_han_thu_48_36","chapterId":"ch_work_han_thu_48","textTraditional":"布弟季心氣蓋關中，遇人恭謹，為任俠，方數千里，士爭為死。嘗殺人，亡吳，從爰絲匿，長事爰絲，〔一〕弟畜灌夫、籍福之屬。嘗為中司馬，〔二〕中尉郅都不敢加。少年多時時竊借其名以行〔三〕。當是時，季心以勇，布以諾，聞關中。","sentenceOrder":36},
  {"id":"s_work_han_thu_48_37","chapterId":"ch_work_han_thu_48","textTraditional":"〔一〕　師古曰：「絲，爰盎字。言以兄長之禮事也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_48_38","chapterId":"ch_work_han_thu_48","textTraditional":"〔二〕　如淳曰：「中尉之司馬。」","sentenceOrder":38},
  {"id":"s_work_han_thu_48_39","chapterId":"ch_work_han_thu_48","textTraditional":"〔三〕　師古曰：「詐自稱為心之賓客徒黨也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_48_40","chapterId":"ch_work_han_thu_48","textTraditional":"布母弟丁公，〔一〕為項羽將，逐窘高祖彭城西。短兵接，漢王急，顧謂丁公曰：「兩賢豈相厄哉！」〔二〕丁公引兵而還。及項王滅，丁公謁見高祖，以丁公徇軍中，〔三〕曰：「丁公為項王臣不忠，使項王失天下者也。」遂斬之，曰：「使後為人臣無傚丁公也！」","sentenceOrder":40},
  {"id":"s_work_han_thu_48_41","chapterId":"ch_work_han_thu_48","textTraditional":"〔一〕　晉灼曰：「楚漢春秋云薛人，名固。」師古曰：「此母弟為同母異父之弟。」","sentenceOrder":41},
  {"id":"s_work_han_thu_48_42","chapterId":"ch_work_han_thu_48","textTraditional":"〔二〕　孟康曰：「丁公及彭城賴齮追上，故曰兩賢也。」師古曰：「孟說非也。兩賢，高祖自謂并謂固耳，言吾與固俱是賢，豈相厄困也。故固感此言而止也。雖與賴齮俱追，而高祖獨與固言耳。」","sentenceOrder":42},
  {"id":"s_work_han_thu_48_43","chapterId":"ch_work_han_thu_48","textTraditional":"〔三〕　師古曰：「徇，行示也，音辭俊反。」","sentenceOrder":43},
  {"id":"s_work_han_thu_48_44","chapterId":"ch_work_han_thu_48","textTraditional":"欒布，梁人也。彭越為家人時，嘗與布游，〔一〕窮困，賣庸於齊，為酒家保。〔二〕數歲別去，而布為人所略，賣為奴於燕。為其主家報仇，〔三〕燕將臧荼舉以為都尉。荼為燕王，布為將。及荼反，漢擊燕，虜布。梁王彭越聞之，乃言上，請贖布為梁大夫。使於齊，未反，〔四〕漢召彭越責以謀反，夷三族，梟首雒陽，下詔有收視者輒捕之。布還，奏事彭越頭下，祠而哭之。吏捕以聞。上召布罵曰：「若與彭越反邪？吾禁人勿收，若獨祠而哭之，與反明矣。〔五〕趣亨之。」〔六〕方提趨湯，〔七〕顧曰：「願一言而死。」上曰：「何言？」布曰：「方上之困彭城，敗滎陽、成皋間，項王所以不能遂西，徒以彭王居梁地，〔八〕與漢合從苦楚也。〔九〕當是之時，彭王壹顧，與楚則漢破，與漢則楚破。且垓下之會，微彭王，項氏不亡。〔一０〕天下已定，彭王剖符受封，（亦）欲傳之萬世。今（漢）〔帝〕壹徵兵於梁，彭王病不行，而疑以為反。反形未見，以苛細誅之，臣恐功臣人人自危也。今彭王已死，臣生不如死，請就亨。」上乃釋布，拜為都尉。","sentenceOrder":44},
  {"id":"s_work_han_thu_48_45","chapterId":"ch_work_han_thu_48","textTraditional":"〔一〕　師古曰：「家人，猶言編戶之人也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_48_46","chapterId":"ch_work_han_thu_48","textTraditional":"〔二〕　孟康曰：「酒家作保。保，庸也。可保信，故謂之保。」師古曰：「謂庸作受顧也。為保，謂保可任使。」","sentenceOrder":46},
  {"id":"s_work_han_thu_48_47","chapterId":"ch_work_han_thu_48","textTraditional":"〔三〕　服虔曰：「為買者報仇也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_48_48","chapterId":"ch_work_han_thu_48","textTraditional":"〔四〕　師古曰：「反，還也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_48_49","chapterId":"ch_work_han_thu_48","textTraditional":"〔五〕　師古曰：「若，汝也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_48_50","chapterId":"ch_work_han_thu_48","textTraditional":"〔六〕　師古曰：「趣讀曰促。促，急也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_48_51","chapterId":"ch_work_han_thu_48","textTraditional":"〔七〕　師古曰：「提，舉也，舉而欲投之於湯也。趨讀曰趣，趨，嚮也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_48_52","chapterId":"ch_work_han_thu_48","textTraditional":"〔八〕　師古曰：「徒，但也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_48_53","chapterId":"ch_work_han_thu_48","textTraditional":"〔九〕　師古曰：「從音子容反。」","sentenceOrder":53},
  {"id":"s_work_han_thu_48_54","chapterId":"ch_work_han_thu_48","textTraditional":"〔一０〕師古曰：「微，無也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_48_55","chapterId":"ch_work_han_thu_48","textTraditional":"孝文時，為燕相，至將軍。布稱曰：「窮困不能辱身，非人也；富貴不能快意，非賢也。」於是嘗有德，厚報之；有怨，必以法滅之。吳楚反時，以功封為鄃侯，〔一〕復為燕相。燕齊之間皆為立社，號曰欒公社。","sentenceOrder":55},
  {"id":"s_work_han_thu_48_56","chapterId":"ch_work_han_thu_48","textTraditional":"〔一〕　蘇林曰：「鄃音輸，清河縣也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_48_57","chapterId":"ch_work_han_thu_48","textTraditional":"布薨，子賁嗣侯，〔一〕孝武時坐為太常犧牲不如令，國除。","sentenceOrder":57},
  {"id":"s_work_han_thu_48_58","chapterId":"ch_work_han_thu_48","textTraditional":"〔一〕　師古曰：「賁音奔。」","sentenceOrder":58},
  {"id":"s_work_han_thu_48_59","chapterId":"ch_work_han_thu_48","textTraditional":"田叔，趙陘城人也。〔一〕其先，齊田氏也。叔好劍，學黃老術於樂鉅公。〔二〕為人廉直，喜任俠。〔三〕游諸公，〔四〕趙人舉之趙相趙午，言之趙王張敖，以為郎中。數歲，趙王賢之，未及遷。","sentenceOrder":59},
  {"id":"s_work_han_thu_48_60","chapterId":"ch_work_han_thu_48","textTraditional":"〔一〕　蘇林曰：「陘音刑。」","sentenceOrder":60},
  {"id":"s_work_han_thu_48_61","chapterId":"ch_work_han_thu_48","textTraditional":"〔二〕　師古曰：「姓樂，名鉅也。公者，老人之稱也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_48_62","chapterId":"ch_work_han_thu_48","textTraditional":"〔三〕　師古曰：「喜，好也，音許吏反。」","sentenceOrder":62},
  {"id":"s_work_han_thu_48_63","chapterId":"ch_work_han_thu_48","textTraditional":"〔四〕　師古曰：「諸公，皆長者也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_48_64","chapterId":"ch_work_han_thu_48","textTraditional":"會趙午、貫高等謀弒上，事發覺，漢下詔捕趙王及群臣反者。趙有敢隨王，罪三族。唯田叔、孟舒等十餘人赭衣自髡鉗，隨王至長安。趙王敖事白，得出，〔一〕廢王為宣平侯，乃進言叔等十人。上召見，與語，漢廷臣無能出其右者。〔二〕上說，〔三〕盡拜為郡守、諸侯相。叔為漢中守十餘年。","sentenceOrder":64},
  {"id":"s_work_han_thu_48_65","chapterId":"ch_work_han_thu_48","textTraditional":"〔一〕　師古曰：「白，明也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_48_66","chapterId":"ch_work_han_thu_48","textTraditional":"〔二〕　師古曰：「材不勝。」","sentenceOrder":66},
  {"id":"s_work_han_thu_48_67","chapterId":"ch_work_han_thu_48","textTraditional":"〔三〕　師古曰：「說讀曰悅。」","sentenceOrder":67},
  {"id":"s_work_han_thu_48_68","chapterId":"ch_work_han_thu_48","textTraditional":"孝文帝初立，召叔問曰：「公知天下長者乎？」對曰：「臣何足以知之！」上曰：「公長者，宜知之。」叔頓首曰：「故雲中守孟舒，長者也。」是時孟舒坐虜大入雲中免。上曰：「先帝置孟舒雲中十餘年矣，虜常一入，孟舒不能堅守，無故士卒戰死者數百人。長者固殺人乎？」叔叩頭曰：「夫貫高等謀反，天子下明詔，趙有敢隨張王者罪三族，然孟舒自髡鉗，隨張王，以身死之，豈自知為雲中守哉！漢與楚相距，士卒罷敝，〔一〕而匈奴冒頓新服北夷，來為邊寇，孟舒知士卒罷敝，不忍出言，士爭臨城死敵，如子為父，以故死者數百人，孟舒豈敺之哉！〔二〕是乃孟舒所以為長者。」於是上曰：「賢哉孟舒！」復召以為雲中守。","sentenceOrder":68},
  {"id":"s_work_han_thu_48_69","chapterId":"ch_work_han_thu_48","textTraditional":"〔一〕　師古曰：「罷讀為疲。下亦同。」","sentenceOrder":69},
  {"id":"s_work_han_thu_48_70","chapterId":"ch_work_han_thu_48","textTraditional":"〔二〕　師古曰：「敺與驅同。言不敺之令戰也。敺字從攴。攴音普木反。」","sentenceOrder":70},
  {"id":"s_work_han_thu_48_71","chapterId":"ch_work_han_thu_48","textTraditional":"後數歲，叔坐法失官。梁孝王使人殺漢議臣爰盎，景帝召叔案梁，具得其事。還報，上曰：「梁有之乎？」對曰：「有之。」「事安在？」〔一〕叔曰：「上無以梁事為問也。〔二〕今梁王不伏誅，是廢漢法也；如其伏誅，太后食不甘味，臥不安席，此憂在陛下。」於是上大賢之，以為魯相。","sentenceOrder":71},
  {"id":"s_work_han_thu_48_72","chapterId":"ch_work_han_thu_48","textTraditional":"〔一〕　師古曰：「索其狀也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_48_73","chapterId":"ch_work_han_thu_48","textTraditional":"〔二〕　師古曰：「言不須更論之也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_48_74","chapterId":"ch_work_han_thu_48","textTraditional":"相初至官，民以王取其財物自言者百餘人。叔取其渠率二（千）〔十〕人笞，怒之〔一〕曰：「王非汝主邪？何敢自言主！」魯王聞之，大慚，發中府錢，使相償之。〔二〕相曰：「王自使人償之，不爾，是王為惡而相為善也。」〔三〕","sentenceOrder":74},
  {"id":"s_work_han_thu_48_75","chapterId":"ch_work_han_thu_48","textTraditional":"〔一〕　師古曰：「渠，大也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_48_76","chapterId":"ch_work_han_thu_48","textTraditional":"〔二〕　師古曰：「中府，王之財物藏也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_48_77","chapterId":"ch_work_han_thu_48","textTraditional":"〔三〕　師古曰：「不爾，是則王為惡。」","sentenceOrder":77},
  {"id":"s_work_han_thu_48_78","chapterId":"ch_work_han_thu_48","textTraditional":"魯王好獵，相常從入苑中，王輒休相就館。相常暴坐苑外，〔一〕終不休，曰：「吾王暴露，獨何為舍？」王以故不大出遊。","sentenceOrder":78},
  {"id":"s_work_han_thu_48_79","chapterId":"ch_work_han_thu_48","textTraditional":"〔一〕　師古曰：「於外自暴露而坐。」","sentenceOrder":79},
  {"id":"s_work_han_thu_48_80","chapterId":"ch_work_han_thu_48","textTraditional":"數年以官卒，魯以百金祠，少子仁不受，曰：「義不傷先人名。」","sentenceOrder":80},
  {"id":"s_work_han_thu_48_81","chapterId":"ch_work_han_thu_48","textTraditional":"仁以壯勇為衛將軍舍人，〔一〕數從擊匈奴。衛將軍進言仁為郎中，至二千石、丞相長史，失官。後使刺三河，還，〔二〕奏事稱意，拜為京輔都尉。月餘，遷司直。數歲，戾太子舉兵，仁部閉城門，令太子得亡，坐縱反者族。〔三〕","sentenceOrder":81},
  {"id":"s_work_han_thu_48_82","chapterId":"ch_work_han_thu_48","textTraditional":"〔一〕　張晏曰：「衛青也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_48_83","chapterId":"ch_work_han_thu_48","textTraditional":"〔二〕　如淳曰：「為刺史於三河郡。三河謂河南、河內、河東也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_48_84","chapterId":"ch_work_han_thu_48","textTraditional":"〔三〕　師古曰：「遣仁掌閉城門，乃令太子得出，故云縱反也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_48_85","chapterId":"ch_work_han_thu_48","textTraditional":"贊曰：以項羽之氣，而季布以勇顯名楚，身履軍搴旗者數矣〔一〕，可謂壯士。及至困厄奴僇，苟活而不變，何也？〔二〕彼自負其材，受辱不羞，欲有所用其未足也，故終為漢名將。賢者誠重其死。夫婢妾賤人，感概而自殺，非能勇也，〔三〕其畫無俚之至耳。〔四〕欒布哭彭越，田叔隨張敖，赴死如歸，彼誠知所處，〔五〕雖古烈士，何以加哉！","sentenceOrder":85},
  {"id":"s_work_han_thu_48_86","chapterId":"ch_work_han_thu_48","textTraditional":"〔一〕　鄧展曰：「履軍，戰勝蹈履之。」李奇曰：「搴，拔也。」孟康曰：「搴，斬取也。」師古曰：「謂勝敵拔取旗也。鄧、李二說皆是。搴音騫。今流俗書本改履謂屢，而加典字，云身屢典軍，非也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_48_87","chapterId":"ch_work_han_thu_48","textTraditional":"〔二〕　師古曰：「僇，古戮字也。奴僇，謂髡鉗為奴而賣之也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_48_88","chapterId":"ch_work_han_thu_48","textTraditional":"〔三〕　師古曰：「感概，謂感念局狹為小節。概音工代反。」","sentenceOrder":88},
  {"id":"s_work_han_thu_48_89","chapterId":"ch_work_han_thu_48","textTraditional":"〔四〕　張晏曰：「言其計畫道理無所至，故自殺耳。」蘇林曰：「俚，賴也。言其計畫無所成賴。」晉灼曰：「揚雄方言曰『俚，聊也』，許慎曰『賴也』。此為其計畫無所聊賴，至於自殺耳。」師古曰：「晉說是也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_48_90","chapterId":"ch_work_han_thu_48","textTraditional":"〔五〕　如淳曰：「太史公曰『非死者難，處死者難』也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_48_91","chapterId":"ch_work_han_thu_48","textTraditional":"校勘記","sentenceOrder":91},
  {"id":"s_work_han_thu_48_92","chapterId":"ch_work_han_thu_48","textTraditional":"一九八０頁　九行　彭王剖符受封，（亦）欲傳之萬世。　景祐本無「亦」字。","sentenceOrder":92},
  {"id":"s_work_han_thu_48_93","chapterId":"ch_work_han_thu_48","textTraditional":"一九八０頁　九行　今（漢）〔帝〕壹徵兵於梁，　宋祁說越本「漢」作「帝」。按景祐本作「帝」。","sentenceOrder":93},
  {"id":"s_work_han_thu_48_94","chapterId":"ch_work_han_thu_48","textTraditional":"一九八三頁一二行　叔取其渠率二（千）〔十〕人笞，　景祐、殿、局本都作「十」。王先謙說作「十」是。","sentenceOrder":94},
  {"id":"s_work_han_thu_49_1","chapterId":"ch_work_han_thu_49","textTraditional":"高皇帝八男：呂后生孝惠帝，曹夫人生齊悼惠王肥，薄姬生孝文帝，戚夫人生趙隱王如意，趙姬生淮南厲王長，諸姬生趙幽王友、趙共王恢、燕靈王建。〔一〕淮南厲王長自有傳。","sentenceOrder":1},
  {"id":"s_work_han_thu_49_2","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　鄭氏曰：「諸，姬姓也。」張晏曰：「非一之稱也。」師古曰：「諸姬，總言在姬妾之列者耳。其知姓位者，史各具言之。不知氏族及秩次者，則云諸姬也。而趙幽以下三王非必同母，蓋以皆不知其所生之姬姓，故總言之。文三王傳云『諸姬生代孝王參、梁懷王揖』，景十三王傳云『屬諸姬子于栗姬』，此意皆同。張云非一，近得之矣。春秋左氏傳曰『諸子仲子、戎子』，『諸子鬻姒』，此其例也。豈以諸為姓乎？鄭說非矣。共讀曰恭。其下類此。」","sentenceOrder":2},
  {"id":"s_work_han_thu_49_3","chapterId":"ch_work_han_thu_49","textTraditional":"齊悼惠王肥，其母高祖微時外婦也。〔一〕高祖六年立，食七十餘城。諸民能齊言者皆與齊。〔二〕孝惠二年，入朝。帝與齊王燕飲太后前，置齊王上坐，如家人禮。〔三〕太后怒，乃令人酌兩卮鴆酒置前，〔四〕令齊王為壽。齊王起，帝亦起，欲俱為壽。太后恐，自起反卮。〔五〕齊王怪之，因不敢飲，陽醉去。問知其鴆，乃憂，自以為不得脫長安。〔六〕內史士曰：〔七〕「太后獨有帝與魯元公主，今王有七十餘城，而公主乃食數城。王誠以一郡上太后為公主湯沐邑，太后必喜，王無患矣。」於是齊王獻城陽郡以尊公主為王太后。〔八〕呂太后喜而許之。乃置酒齊邸，樂飲，遣王歸國。後十三年薨，子襄嗣。","sentenceOrder":3},
  {"id":"s_work_han_thu_49_4","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「謂與旁通者。」","sentenceOrder":4},
  {"id":"s_work_han_thu_49_5","chapterId":"ch_work_han_thu_49","textTraditional":"〔二〕　孟康曰：「此時流移，故使齊言者還齊也。」師古曰：「欲其國大，故多封之。」","sentenceOrder":5},
  {"id":"s_work_han_thu_49_6","chapterId":"ch_work_han_thu_49","textTraditional":"〔三〕　師古曰：「以兄弟齒列，不從君臣之禮，故曰家人也。坐音材臥反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_49_7","chapterId":"ch_work_han_thu_49","textTraditional":"〔四〕　應劭曰：「鴆鳥黑身赤目，食蝮（蛟）〔蛇〕野葛，以其羽畫酒中，飲之立死。」","sentenceOrder":7},
  {"id":"s_work_han_thu_49_8","chapterId":"ch_work_han_thu_49","textTraditional":"〔五〕　師古曰：「反音幡。」","sentenceOrder":8},
  {"id":"s_work_han_thu_49_9","chapterId":"ch_work_han_thu_49","textTraditional":"〔六〕　師古曰：「脫，免也。言死於長安，不得更至齊國也。脫音吐活反。」","sentenceOrder":9},
  {"id":"s_work_han_thu_49_10","chapterId":"ch_work_han_thu_49","textTraditional":"〔七〕　師古曰：「內史，王官。士者，其名也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_49_11","chapterId":"ch_work_han_thu_49","textTraditional":"〔八〕　師古曰：「為齊王太后也。言以母禮事之，所以自媚也。解具在惠紀。」","sentenceOrder":11},
  {"id":"s_work_han_thu_49_12","chapterId":"ch_work_han_thu_49","textTraditional":"趙隱王如意，九年立。〔一〕四年，高祖崩，〔二〕呂太后徵王到長安，鴆殺之。無子，絕。","sentenceOrder":12},
  {"id":"s_work_han_thu_49_13","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「高祖之九年也。他皆類此。」","sentenceOrder":13},
  {"id":"s_work_han_thu_49_14","chapterId":"ch_work_han_thu_49","textTraditional":"〔二〕　師古曰：「趙王之四年。」","sentenceOrder":14},
  {"id":"s_work_han_thu_49_15","chapterId":"ch_work_han_thu_49","textTraditional":"趙幽王友，十一年立為淮陽王。趙隱王如意死，孝惠元年，徙友王趙，凡立十四年。友以諸呂女為后，不愛，愛它姬。諸呂女怒去，讒之於太后曰：「王曰『呂氏安得王？〔一〕太后百歲後，吾必擊之。』」太后怒，以故召趙王。趙王至，置邸不見，令衛圍守之，不得食。其群臣或竊饋之，輒捕論之。趙王餓，乃歌曰：「諸呂用事兮，劉氏微；迫脅王侯兮，彊授我妃。我妃既妒兮，誣我以惡；〔二〕讒女亂國兮，上曾不寤。我無忠臣兮，何故棄國？〔三〕自快中野兮，蒼天與直！〔四〕于嗟不可悔兮，寧早自賊！〔五〕為王餓死兮，誰者憐之？呂氏絕理兮，託天報仇！」遂幽死。以民禮葬之長安。","sentenceOrder":15},
  {"id":"s_work_han_thu_49_16","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「安猶焉也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_49_17","chapterId":"ch_work_han_thu_49","textTraditional":"〔二〕　師古曰：「惡音一故反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_49_18","chapterId":"ch_work_han_thu_49","textTraditional":"〔三〕　師古曰：「謂不能明白之也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_49_19","chapterId":"ch_work_han_thu_49","textTraditional":"〔四〕　師古曰：「天色蒼蒼，故曰蒼天。言己之理直，冀天臨監之。」","sentenceOrder":19},
  {"id":"s_work_han_thu_49_20","chapterId":"ch_work_han_thu_49","textTraditional":"〔五〕　師古曰：「賊，害也。悔不早棄趙國而快意自殺於田野之中，今乃被幽餓也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_49_21","chapterId":"ch_work_han_thu_49","textTraditional":"高后崩，孝文即位，立幽王子遂為趙王。二年，有司請立皇子為王。上曰：「趙幽王幽死，朕甚憐之。已立其長子遂為趙王。遂弟辟彊及齊悼惠王子朱虛侯章、東牟侯興居有功，皆可王。」於是取趙之河間立辟彊，是為河間文王。文王立十三年薨，子哀王福嗣。一年薨。無子，國除。","sentenceOrder":21},
  {"id":"s_work_han_thu_49_22","chapterId":"ch_work_han_thu_49","textTraditional":"趙王遂立二十六年，孝景時晁錯以過削趙常山郡，諸侯怨，吳楚反，遂與合謀起兵。其相建德、內史王悍諫，不聽。遂燒殺德、悍，〔一〕發兵住其西界，欲待吳楚俱進，北使匈奴與連和。漢使曲周侯酈寄擊之，趙王城守邯鄲，相距七月。吳楚敗，匈奴聞之，亦不肯入邊。欒布自破齊還，并兵引水灌趙城。城壞，王遂自殺，國除。景帝憐趙相、內史守正死，皆封其子為列侯。","sentenceOrder":22},
  {"id":"s_work_han_thu_49_23","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「上云其相建德、內史王悍，下云燒殺德、悍，是為相姓建名德也。而景武功臣侯表云『遽侯橫父建德，以趙相死事，子侯』，則是不知其姓。表傳不同，疑後人轉寫此傳，誤脫去一建字也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_49_24","chapterId":"ch_work_han_thu_49","textTraditional":"趙共王恢。十一年，梁王彭越誅，立恢為梁王。十六年，趙幽王死，呂后徙恢王趙，恢心不樂。太后以呂產女為趙王后，王后從官皆諸呂也，內擅權，微司趙王，王不得自恣。王有愛姬，王后鴆殺之。王乃為歌詩四章，令樂人歌之。王悲思，六月自殺。太后聞之，以為用婦人故自殺，無思奉宗廟禮，廢其嗣。","sentenceOrder":24},
  {"id":"s_work_han_thu_49_25","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「王之美人生子也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_49_26","chapterId":"ch_work_han_thu_49","textTraditional":"齊悼惠王子，前後凡九人為王：太子襄為齊哀王，次子章為城陽景王，興居為濟北王，將閭為齊王，志為濟北王，辟光為濟南王〔一〕，賢為菑川王，卬為膠西王，雄渠為膠東王。","sentenceOrder":26},
  {"id":"s_work_han_thu_49_27","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「辟音壁，又讀曰闢。」","sentenceOrder":27},
  {"id":"s_work_han_thu_49_28","chapterId":"ch_work_han_thu_49","textTraditional":"齊哀王襄，孝惠六年嗣立。明年，惠帝崩，呂太后稱制。元年，以其兄子鄜侯呂台為呂王，〔一〕割齊之濟南郡為呂王奉邑。〔二〕明年，哀王弟章入宿衛於漢，高后封為朱虛侯，以呂祿女妻之。後四年，封章弟興居為東牟侯，皆宿衛長安。高后七年，割齊琅邪郡，立營陵侯劉澤為琅邪王。是歲，趙王友幽死于邸。三趙王既廢，高后立諸呂為三王，擅權用事。","sentenceOrder":28},
  {"id":"s_work_han_thu_49_29","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「鄜音敷。」","sentenceOrder":29},
  {"id":"s_work_han_thu_49_30","chapterId":"ch_work_han_thu_49","textTraditional":"〔二〕　師古曰：「奉音扶用反。他皆類此。」","sentenceOrder":30},
  {"id":"s_work_han_thu_49_31","chapterId":"ch_work_han_thu_49","textTraditional":"章年二十，有氣力，忿劉氏不得職。嘗入侍燕飲，高后令章為酒吏。章自請曰：「臣，將種也，請得以軍法行酒。」高后曰：「可。」酒酣，章進歌舞，已而曰：「請為太后言耕田。」〔一〕高后兒子畜之，〔二〕笑曰：「顧乃父知田耳，〔三〕若生而為王子，安知田乎？」〔四〕章曰：「臣知之。」太后曰：「試為我言田意。」章曰：「深耕穊種，立苗欲疏；〔五〕非其種者，鉏而去之。」〔六〕太后默然。頃之，諸呂有一人醉，亡酒，〔七〕章追，拔劍斬之，而還報曰：「有亡酒一人，臣謹行軍法斬之。」太后左右大驚。業已許其軍法，亡以罪也。因罷酒。自是後，諸呂憚章，雖大臣皆依朱虛侯。劉氏為彊。〔八〕","sentenceOrder":31},
  {"id":"s_work_han_thu_49_32","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「欲申諷喻也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_49_33","chapterId":"ch_work_han_thu_49","textTraditional":"〔二〕　師古曰：「比之於子也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_49_34","chapterId":"ch_work_han_thu_49","textTraditional":"〔三〕　師古曰：「顧，念也。乃，汝也。汝父，謂高帝也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_49_35","chapterId":"ch_work_han_thu_49","textTraditional":"〔四〕　師古曰：「若亦汝也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_49_36","chapterId":"ch_work_han_thu_49","textTraditional":"〔五〕　師古曰：「穊，稠也。穊種者，言多生子孫也。疏立者，四散置之，令為藩輔也。穊音冀。」","sentenceOrder":36},
  {"id":"s_work_han_thu_49_37","chapterId":"ch_work_han_thu_49","textTraditional":"〔六〕　師古曰：「以斥諸呂也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_49_38","chapterId":"ch_work_han_thu_49","textTraditional":"〔七〕　師古曰：「避酒而逃亡。」","sentenceOrder":38},
  {"id":"s_work_han_thu_49_39","chapterId":"ch_work_han_thu_49","textTraditional":"〔八〕　師古曰：「為音于偽反。」","sentenceOrder":39},
  {"id":"s_work_han_thu_49_40","chapterId":"ch_work_han_thu_49","textTraditional":"其明年，高后崩。趙王呂祿為上將軍，呂王產為相國，皆居長安中，聚兵以威大臣，欲為亂。章以呂祿女為婦，知其謀，乃使人陰出告其兄齊王，欲令發兵西，〔一〕朱虛侯、東牟侯欲從中與大臣為內應，以誅諸呂，因立齊王為帝。","sentenceOrder":40},
  {"id":"s_work_han_thu_49_41","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕師古曰：「西詣京師。」","sentenceOrder":41},
  {"id":"s_work_han_thu_49_42","chapterId":"ch_work_han_thu_49","textTraditional":"齊王聞此計，與其舅駟鈞、郎中令祝午、中尉魏勃陰謀發兵。齊相召平聞之，〔一〕乃發兵入衛王宮。魏勃紿平曰：〔二〕「王欲發兵，非有漢虎符驗也。而相君圍王，固善。勃請為君將兵衛衛王。」〔三〕召平信之，乃使魏勃將。勃既將，以兵圍相府。召平曰：「嗟乎！道家之言『當斷不斷，反受其亂』。」遂自殺。於是齊王以駟鈞為相，魏勃為將軍，祝午為內史，悉發國中兵。使祝午紿琅邪王曰：「呂氏為亂，齊王發兵欲西誅之。齊王自以兒子，年少，不習兵革之事，願舉國委大王。大王自高帝將也，〔四〕習戰事。齊王不敢離兵，〔五〕使臣請大王幸之臨菑見齊王計事，并將齊兵以西平關中之亂。」琅邪王信之，以為然，乃馳見齊王。齊王與魏勃等因留琅邪王，而使祝午盡發琅邪國而并將其兵。","sentenceOrder":42},
  {"id":"s_work_han_thu_49_43","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「召讀曰邵。」","sentenceOrder":43},
  {"id":"s_work_han_thu_49_44","chapterId":"ch_work_han_thu_49","textTraditional":"〔二〕　師古曰：「紿，誑也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_49_45","chapterId":"ch_work_han_thu_49","textTraditional":"〔三〕　師古曰：「謂將兵及衛守之具，以禁衛王，令不得發也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_49_46","chapterId":"ch_work_han_thu_49","textTraditional":"〔四〕　師古曰：「言自高帝之時已為將也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_49_47","chapterId":"ch_work_han_thu_49","textTraditional":"〔五〕　服虔曰：「不敢離其兵而到琅邪。」","sentenceOrder":47},
  {"id":"s_work_han_thu_49_48","chapterId":"ch_work_han_thu_49","textTraditional":"琅邪王劉澤既欺，不得反國，乃說齊王曰：「齊悼惠王，高皇帝長子也，推本言之，大王高皇帝適長孫也，〔一〕當立。今諸大臣狐疑未有所定，而澤於劉氏最為長年，大臣固待澤決計。今大王留臣無為也，不如使我入關計事。」齊王以為然，乃益具車送琅邪王。","sentenceOrder":48},
  {"id":"s_work_han_thu_49_49","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「適讀曰嫡。」","sentenceOrder":49},
  {"id":"s_work_han_thu_49_50","chapterId":"ch_work_han_thu_49","textTraditional":"琅邪王既行，齊遂舉兵西攻呂國之濟南。於是齊王遺諸侯王書曰：「高帝平定天下，王諸子弟。悼惠王薨，惠帝使留侯張良立臣為齊王。惠帝崩，高后用事，春秋高，聽諸呂擅廢帝更立，又殺三趙王，滅梁、趙、燕，以王諸呂，分齊國為四。〔一〕忠臣進諫，上或亂不聽。今高后崩，皇帝春秋富，〔二〕未能治天下，固待大臣諸侯。今諸呂又擅自尊官，聚（官）〔兵〕嚴威，劫列侯忠臣，撟制以令天下，〔三〕宗廟以危。寡人帥兵入誅不當為王者。」","sentenceOrder":50},
  {"id":"s_work_han_thu_49_51","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「本自齊國，更分為濟南、琅邪、城陽，凡為四也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_49_52","chapterId":"ch_work_han_thu_49","textTraditional":"〔二〕　師古曰：「言年幼也。比之於財，方未匱竭，故謂之富。」","sentenceOrder":52},
  {"id":"s_work_han_thu_49_53","chapterId":"ch_work_han_thu_49","textTraditional":"〔三〕　師古曰：「撟，託也。託天子之制詔也。撟音矯。」","sentenceOrder":53},
  {"id":"s_work_han_thu_49_54","chapterId":"ch_work_han_thu_49","textTraditional":"漢聞之，相國呂產等遣大將軍潁陰侯灌嬰將兵擊之。嬰至滎陽，乃謀曰：「諸呂舉兵關中，欲危劉氏而自立，今我破齊還報，是益呂氏資也。」乃留兵屯滎陽，使人諭齊王及諸侯，與連和，〔一〕以待呂氏之變而共誅之。齊王聞之，乃屯兵西界待約。","sentenceOrder":54},
  {"id":"s_work_han_thu_49_55","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「諭謂曉告也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_49_56","chapterId":"ch_work_han_thu_49","textTraditional":"呂祿、呂產欲作亂，朱虛侯章與太尉勃、丞相平等誅之。章首先斬呂產，太尉勃等乃盡誅諸呂。而琅邪王亦從齊至長安。","sentenceOrder":56},
  {"id":"s_work_han_thu_49_57","chapterId":"ch_work_han_thu_49","textTraditional":"大臣議欲立齊王，皆曰：「母家駟鈞惡戾，虎而冠者也。〔一〕訪以呂氏故，幾亂天下，〔二〕今又立齊王，是欲復為呂氏也。代王母家薄氏，君子長者，且代王，高帝子，於今見在，最為長。以子則順，以善人則大臣安。」於是大臣乃謀迎代王，而遣章以誅呂氏事告齊王，令罷兵。","sentenceOrder":57},
  {"id":"s_work_han_thu_49_58","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　張晏曰：「言鈞惡戾，如虎著冠。」","sentenceOrder":58},
  {"id":"s_work_han_thu_49_59","chapterId":"ch_work_han_thu_49","textTraditional":"〔二〕　如淳曰：「訪猶方也。」師古曰：「幾音鉅依反。」","sentenceOrder":59},
  {"id":"s_work_han_thu_49_60","chapterId":"ch_work_han_thu_49","textTraditional":"灌嬰在滎陽，聞魏勃本教齊王反，既誅呂氏，罷齊兵，使使召責問魏勃。勃曰：「失火之家，豈暇先言丈人後救火乎！」〔一〕因退立，股戰而栗。〔二〕恐不能言者，終無他語。灌將軍孰視，笑曰：「人謂魏勃勇，妄庸人耳，何能為乎！」乃罷勃。〔三〕勃父以善鼓琴見秦皇帝。及勃少時，欲求見齊相曹參，家貧無以自通，乃常獨早埽齊相舍人門外。舍人怪之，以為物而司之，得勃。〔四〕勃曰：「願見相君無因，故為子埽，欲以求見。」於是舍人見勃，曹參因以為舍人。壹為參御言事，以為賢，言之悼惠王。王召見，拜為內史。始悼惠王得自置二千石。及悼惠王薨，哀王嗣，勃用事重於相。","sentenceOrder":60},
  {"id":"s_work_han_thu_49_61","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「言以社稷將危，故舉兵以匡之，不暇待有詔命也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_49_62","chapterId":"ch_work_han_thu_49","textTraditional":"〔二〕　師古曰：「股，腳也。戰者，懼之甚也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_49_63","chapterId":"ch_work_han_thu_49","textTraditional":"〔三〕　師古曰：「放令去。」","sentenceOrder":63},
  {"id":"s_work_han_thu_49_64","chapterId":"ch_work_han_thu_49","textTraditional":"〔四〕　師古曰：「物謂鬼神。司者，察視之。」","sentenceOrder":64},
  {"id":"s_work_han_thu_49_65","chapterId":"ch_work_han_thu_49","textTraditional":"齊王既罷兵歸，而代王立，是為孝文帝。","sentenceOrder":65},
  {"id":"s_work_han_thu_49_66","chapterId":"ch_work_han_thu_49","textTraditional":"文帝元年，盡以高后時所割齊之城陽、琅邪、濟南郡復予齊，而徙琅邪王王燕。益封朱虛侯、東牟侯各二千戶，黃金千斤。","sentenceOrder":66},
  {"id":"s_work_han_thu_49_67","chapterId":"ch_work_han_thu_49","textTraditional":"是歲，齊哀王薨，子文王則嗣。十四年薨，無子，國除。","sentenceOrder":67},
  {"id":"s_work_han_thu_49_68","chapterId":"ch_work_han_thu_49","textTraditional":"城陽景王章，孝文二年以朱虛侯與東牟侯興居俱立，二年薨。子共王喜嗣。孝文十二年，徙王淮南，五年，復還王城陽，凡立三十三年薨。子頃王延嗣，二十六年薨。子敬王義嗣，九年薨。子惠王武嗣，十一年薨。子荒王順嗣，四十六年薨。子戴王恢嗣，八年薨。子孝王景嗣，二十四年薨。子哀王雲嗣，一年薨，無子，國絕。成帝復立雲兄俚為城陽王，〔一〕王莽時絕。","sentenceOrder":68},
  {"id":"s_work_han_thu_49_69","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「俚音里。」","sentenceOrder":69},
  {"id":"s_work_han_thu_49_70","chapterId":"ch_work_han_thu_49","textTraditional":"濟北王興居初以東牟侯與大臣共立文帝於代邸，曰：「誅呂氏，臣無功，請與太僕滕公俱入清宮。」〔一〕遂將少帝出，迎皇帝入宮。","sentenceOrder":70},
  {"id":"s_work_han_thu_49_71","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「滕公，夏侯嬰也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_49_72","chapterId":"ch_work_han_thu_49","textTraditional":"始誅諸呂時，朱虛侯章功尤大，大臣許盡以趙地王章，盡以梁地王興居。及文帝立，聞朱虛、東牟之初欲立齊王，故黜其功。〔一〕二年，王諸子，乃割齊二郡以王章、興居。章、興居意自以失職奪功。歲餘，章薨，而匈奴大入邊，漢多發兵，丞相灌嬰將擊之，文帝親幸太原。興居以為天子自擊胡，遂發兵反。上聞之，罷兵歸長安，使棘蒲侯柴將軍〔二〕擊破，虜濟北王。王自殺，國除。","sentenceOrder":72},
  {"id":"s_work_han_thu_49_73","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「不賞之。」","sentenceOrder":73},
  {"id":"s_work_han_thu_49_74","chapterId":"ch_work_han_thu_49","textTraditional":"〔二〕　張晏曰：「柴武。」","sentenceOrder":74},
  {"id":"s_work_han_thu_49_75","chapterId":"ch_work_han_thu_49","textTraditional":"文帝憫濟北王逆亂以自滅，明年，盡封悼惠王諸子罷軍等七人為列侯。〔一〕至十五年，齊文王又薨，無子。時悼惠王後尚有城陽王在，文帝憐悼惠王適嗣之絕，〔二〕於是乃分齊為六國，盡立前所封悼惠王子列侯見在者六人為王。齊孝王將閭以楊虛侯立，濟北王志以安都侯立，菑川王賢以武成侯立，膠東王雄渠以白石侯立，膠西王卬以平昌侯立，濟南王辟光以扐侯立。〔三〕孝文十六年，六王同日俱立。","sentenceOrder":75},
  {"id":"s_work_han_thu_49_76","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「罷音皮彼反，又讀曰疲。」","sentenceOrder":76},
  {"id":"s_work_han_thu_49_77","chapterId":"ch_work_han_thu_49","textTraditional":"〔二〕　師古曰：「適讀曰嫡。」","sentenceOrder":77},
  {"id":"s_work_han_thu_49_78","chapterId":"ch_work_han_thu_49","textTraditional":"〔三〕　服虔曰：「扐音勒。扐，平原縣也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_49_79","chapterId":"ch_work_han_thu_49","textTraditional":"立十一年，孝景三年，吳楚反，膠東、膠西、菑川、濟南王皆發兵應吳楚。欲與齊，〔一〕齊孝王狐疑，城守不聽。三國兵共圍齊，〔二〕齊王使路中大夫告於天子。〔三〕天子復令路中大夫還報，告齊王堅守，漢兵今破吳楚矣。路中大夫至，三國兵圍臨菑數重，無從入。三國將與路中大夫盟曰：「若反言漢已破矣，〔四〕齊趣下三國，不且見屠。」〔五〕路中大夫既許，至城下，望見齊王，曰：「漢已發兵百萬，使太尉亞夫擊破吳楚，方引兵救齊，齊必堅守無下！」三國將誅路中大夫。","sentenceOrder":79},
  {"id":"s_work_han_thu_49_80","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「與之同反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_49_81","chapterId":"ch_work_han_thu_49","textTraditional":"〔二〕　張晏曰：「膠西、菑川、濟南也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_49_82","chapterId":"ch_work_han_thu_49","textTraditional":"〔三〕　張晏曰：「姓路，為中大夫。」","sentenceOrder":82},
  {"id":"s_work_han_thu_49_83","chapterId":"ch_work_han_thu_49","textTraditional":"〔四〕　師古曰：「若，汝也。反謂反易其辭也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_49_84","chapterId":"ch_work_han_thu_49","textTraditional":"〔五〕　師古曰：「趣讀曰促。」","sentenceOrder":84},
  {"id":"s_work_han_thu_49_85","chapterId":"ch_work_han_thu_49","textTraditional":"齊初圍急，陰與三國通謀，約未定，會路中大夫從漢來，其大臣乃復勸王無下三國。會漢將欒布、平陽侯等兵至齊，〔一〕擊破三國兵，解圍。已後聞齊初與三國有謀，將欲移兵伐齊。齊孝王懼，飲藥自殺。而膠東、膠西、濟南、菑川王皆伏誅，國除。獨濟北王在。","sentenceOrder":85},
  {"id":"s_work_han_thu_49_86","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「平陽侯，曹襄。」","sentenceOrder":86},
  {"id":"s_work_han_thu_49_87","chapterId":"ch_work_han_thu_49","textTraditional":"齊孝王之自殺也，景帝聞之，以為齊首善，〔一〕以迫劫有謀，非其罪也，召立孝王太子壽，是為懿王。二十三年薨，子厲王次昌嗣。","sentenceOrder":87},
  {"id":"s_work_han_thu_49_88","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「言其初首無逆亂之心。」","sentenceOrder":88},
  {"id":"s_work_han_thu_49_89","chapterId":"ch_work_han_thu_49","textTraditional":"其母曰紀太后。太后取其弟紀氏女為王后，王不愛。紀太后欲其家重寵，〔一〕令其長女紀翁主入王宮〔二〕正其後宮無令得近王，欲令愛紀氏女。王因與其姊翁主姦。","sentenceOrder":89},
  {"id":"s_work_han_thu_49_90","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「重音直用反。」","sentenceOrder":90},
  {"id":"s_work_han_thu_49_91","chapterId":"ch_work_han_thu_49","textTraditional":"〔二〕　師古曰：「諸王女曰翁主，而紀氏所生，故謂之紀翁主。」","sentenceOrder":91},
  {"id":"s_work_han_thu_49_92","chapterId":"ch_work_han_thu_49","textTraditional":"齊有宦者徐甲，〔一〕入事漢皇太后。〔二〕皇太后有愛女曰脩成君，脩成君非劉氏子，〔三〕太后憐之。脩成君有女娥，太后欲嫁之於諸侯。宦者甲乃請使齊，必令王上書請娥。皇太后大喜，使甲之齊。時主父偃知甲之使齊以取后事，亦因謂甲：「即事成，幸言偃女願得充王後宮。」甲至齊，風以此事。〔四〕紀太后怒曰：「王有后，後宮備具。且甲，齊貧人，及為宦者入事漢，初無補益，乃欲亂吾王家！且主父偃何為者？乃欲以女充後宮！」甲大窮，還報皇太后曰：「王已願尚娥，〔五〕然事有所害，恐如燕王。」燕王者，與其子昆弟姦，坐死。〔六〕故以燕感太后。〔七〕太后曰：「毋復言嫁女齊事。」事寖淫聞於上。〔八〕主父偃由此與齊有隙。","sentenceOrder":92},
  {"id":"s_work_han_thu_49_93","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「宦者，奄人。」","sentenceOrder":93},
  {"id":"s_work_han_thu_49_94","chapterId":"ch_work_han_thu_49","textTraditional":"〔二〕　張晏曰：「皇太后，武帝之母。」","sentenceOrder":94},
  {"id":"s_work_han_thu_49_95","chapterId":"ch_work_han_thu_49","textTraditional":"〔三〕　蘇林曰：「皇太后前嫁金氏所生。」","sentenceOrder":95},
  {"id":"s_work_han_thu_49_96","chapterId":"ch_work_han_thu_49","textTraditional":"〔四〕　師古曰：「風讀曰諷。」","sentenceOrder":96},
  {"id":"s_work_han_thu_49_97","chapterId":"ch_work_han_thu_49","textTraditional":"〔五〕　師古曰：「尚，配也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_49_98","chapterId":"ch_work_han_thu_49","textTraditional":"〔六〕　師古曰：「燕王定國傳云『與其子女三人姦』。子昆弟者，言是其子女又長幼非一，故云子昆弟也。一曰，子昆弟者，定國之姊妹也。言定國姦其子女及其姊妹。」","sentenceOrder":98},
  {"id":"s_work_han_thu_49_99","chapterId":"ch_work_han_thu_49","textTraditional":"〔七〕　師古曰：「言齊王與其姊妹姦，終當坐之致死，不足嫁女與之。」","sentenceOrder":99},
  {"id":"s_work_han_thu_49_100","chapterId":"ch_work_han_thu_49","textTraditional":"〔八〕　師古曰：「寖，古浸字也。浸淫，猶言漸染也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_49_101","chapterId":"ch_work_han_thu_49","textTraditional":"偃方幸用事，因言：「齊臨菑十萬戶，巿租千金，〔一〕人眾殷富，鉅於長安，〔二〕非天子親弟愛子不得王此。今齊王於親屬益疏。」乃從容言呂太后時齊欲反，〔三〕及吳楚時孝王幾為亂。〔四〕今聞齊王與其姊亂。於是武帝拜偃為齊相，且正其事。偃至齊，急治王後宮宦者為王通於姊翁主所者，辭及王。王年少，懼以罪為吏所執誅，乃飲藥自殺。","sentenceOrder":101},
  {"id":"s_work_han_thu_49_102","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「收一巿之租，直千金也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_49_103","chapterId":"ch_work_han_thu_49","textTraditional":"〔二〕　師古曰：「鉅，大也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_49_104","chapterId":"ch_work_han_thu_49","textTraditional":"〔三〕　師古曰：「從音千容反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_49_105","chapterId":"ch_work_han_thu_49","textTraditional":"〔四〕　師古曰：「幾音鉅依反。」","sentenceOrder":105},
  {"id":"s_work_han_thu_49_106","chapterId":"ch_work_han_thu_49","textTraditional":"是時趙王懼主父偃壹出敗齊，恐其漸疏骨肉，乃上書言偃受金及輕重之短，〔一〕天子亦因囚偃。公孫弘曰：「齊王以憂死，無後，非誅偃無以塞天下之望。」〔二〕偃遂坐誅。","sentenceOrder":106},
  {"id":"s_work_han_thu_49_107","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「輕重，謂用心不平。」","sentenceOrder":107},
  {"id":"s_work_han_thu_49_108","chapterId":"ch_work_han_thu_49","textTraditional":"〔二〕　師古曰：「塞，滿也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_49_109","chapterId":"ch_work_han_thu_49","textTraditional":"厲王立五年，國除。","sentenceOrder":109},
  {"id":"s_work_han_thu_49_110","chapterId":"ch_work_han_thu_49","textTraditional":"濟北王志，吳楚反時初亦與通謀，後堅守不發兵，故得不誅，徙王菑川。元朔中，齊國絕。","sentenceOrder":110},
  {"id":"s_work_han_thu_49_111","chapterId":"ch_work_han_thu_49","textTraditional":"悼惠王後唯有二國：城陽、菑川。菑川地比齊，〔一〕武帝為悼惠王冢園在齊，乃割臨菑東圜悼惠王冢園邑盡以予菑川，〔二〕令奉祭祀。","sentenceOrder":111},
  {"id":"s_work_han_thu_49_112","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「比，近也，音頻二反。」","sentenceOrder":112},
  {"id":"s_work_han_thu_49_113","chapterId":"ch_work_han_thu_49","textTraditional":"〔二〕　師古曰：「圜謂周繞之。」","sentenceOrder":113},
  {"id":"s_work_han_thu_49_114","chapterId":"ch_work_han_thu_49","textTraditional":"志立三十五年薨，是為懿王。子靖王建嗣，二十年薨。子頃王遺嗣，三十五年薨。子思王終古嗣。五鳳中，青州刺史奏終古使所愛奴與八子及諸御婢姦，〔一〕終古或參與被席，〔二〕或白晝使（羸）〔臝〕伏，犬馬交接，〔三〕終古親臨觀。產子，輒曰：「亂不可知，使去其子。」〔四〕事下丞相御史，奏終古位諸侯王，以令置八子，秩比六百石，所以廣嗣重祖也。而終古禽獸行，亂君臣夫婦之別，悖逆人倫，〔五〕請逮捕。有詔削四縣。二十八年薨。子考王尚嗣，五年薨。子孝王橫嗣，三十一年薨。子懷王交嗣，六年薨。子永嗣，王莽時絕。","sentenceOrder":114},
  {"id":"s_work_han_thu_49_115","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　如淳曰：「八子，妾號。」","sentenceOrder":115},
  {"id":"s_work_han_thu_49_116","chapterId":"ch_work_han_thu_49","textTraditional":"〔二〕　師古曰：「與讀曰豫。」","sentenceOrder":116},
  {"id":"s_work_han_thu_49_117","chapterId":"ch_work_han_thu_49","textTraditional":"〔三〕　師古曰：「（羸）〔臝〕者，露形體也，音郎果反。」","sentenceOrder":117},
  {"id":"s_work_han_thu_49_118","chapterId":"ch_work_han_thu_49","textTraditional":"〔四〕　師古曰：「去，除也，音丘呂反。」","sentenceOrder":118},
  {"id":"s_work_han_thu_49_119","chapterId":"ch_work_han_thu_49","textTraditional":"〔五〕　師古曰：「悖，乖也，音步內反。」","sentenceOrder":119},
  {"id":"s_work_han_thu_49_120","chapterId":"ch_work_han_thu_49","textTraditional":"贊曰：悼惠之王齊，最為大國。以海內初定，子弟少，激秦孤立亡藩輔，〔一〕故大封同姓，以填天下。〔二〕時諸侯得自除御史大夫群卿以下眾官，如漢朝，漢獨為置丞相。自吳楚誅後，稍奪諸侯權，左官附益阿黨之法設。〔三〕其後諸侯唯得衣食租稅，貧者或乘牛車。","sentenceOrder":120},
  {"id":"s_work_han_thu_49_121","chapterId":"ch_work_han_thu_49","textTraditional":"〔一〕　師古曰：「激，感發也，音工歷反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_49_122","chapterId":"ch_work_han_thu_49","textTraditional":"〔二〕　師古曰：「填音竹刃反。」","sentenceOrder":122},
  {"id":"s_work_han_thu_49_123","chapterId":"ch_work_han_thu_49","textTraditional":"〔三〕　張晏曰：「諸侯有罪，傅相不舉奏，為阿黨。」師古曰：「皆新制律令之條也。左官，解在諸侯王表。附益，言欲增益諸侯王也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_49_124","chapterId":"ch_work_han_thu_49","textTraditional":"校勘記","sentenceOrder":124},
  {"id":"s_work_han_thu_49_125","chapterId":"ch_work_han_thu_49","textTraditional":"一九八八頁　八行　食蝮（蛟）〔蛇〕野葛，　景祐、殿、局本都作「蛇」。　王先謙說作「蛇」是。","sentenceOrder":125},
  {"id":"s_work_han_thu_49_126","chapterId":"ch_work_han_thu_49","textTraditional":"一九八九頁　五行　我無忠臣兮，何故棄國？〔三〕　注〔三〕原在「何故」下。　劉攽說「棄國」當屬上句。","sentenceOrder":126},
  {"id":"s_work_han_thu_49_127","chapterId":"ch_work_han_thu_49","textTraditional":"一九九四頁　七行　聚（官）〔兵〕嚴威，　景祐、殿本都作「兵」，史記同。","sentenceOrder":127},
  {"id":"s_work_han_thu_49_128","chapterId":"ch_work_han_thu_49","textTraditional":"二００一頁一五行　或白晝使（羸）〔臝〕伏，　景祐本作「臝」。王念孫說此古字之僅存者。","sentenceOrder":128},
  {"id":"s_work_han_thu_50_1","chapterId":"ch_work_han_thu_50","textTraditional":"蕭何，沛人也。以文毋害為沛主吏掾。〔一〕高祖為布衣時，數以吏事護高祖。高祖為亭長，常佑之。〔二〕高祖以吏繇咸陽，〔三〕吏皆送奉錢三，何獨以五。〔四〕秦御史監郡者，與從事辨之〔五〕。何乃給泗水卒史事，〔六〕第一。〔七〕秦御史欲入言徵何，何固請，得毋行。〔八〕","sentenceOrder":1},
  {"id":"s_work_han_thu_50_2","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　服虔曰：「為人解通，無嫉害也。」應劭曰：「雖為文吏，而不刻害也。」蘇林曰：「毋害，若言無比也。一曰，害，勝也，無能勝害之者。」晉灼曰：「酷吏傳趙禹為丞相亞夫吏，府中皆稱其廉，然亞夫不任，曰：『極知禹無害，然文深，不可以居大府。』蘇說是也。」師古曰：「害，傷也，無人能傷害之者。蘇、晉兩說皆得其意，服、應非也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_50_3","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　師古曰：「佑，助也。言居家時，為何所護，及為亭長，何又擁助也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_50_4","chapterId":"ch_work_han_thu_50","textTraditional":"〔三〕　師古曰：「繇讀曰傜。傜，役也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_50_5","chapterId":"ch_work_han_thu_50","textTraditional":"〔四〕　師古曰：「出錢以資行，他人皆三百，何獨五百。奉音扶用反。」","sentenceOrder":5},
  {"id":"s_work_han_thu_50_6","chapterId":"ch_work_han_thu_50","textTraditional":"〔五〕　張晏曰：「何與共事備辨，明何素有方略也。」蘇林曰：「辟何與從事也。秦時無刺史，以御史監郡。」師古曰：「二說皆同。」","sentenceOrder":6},
  {"id":"s_work_han_thu_50_7","chapterId":"ch_work_han_thu_50","textTraditional":"〔六〕　師古曰：「泗水郡，沛所屬也。何為郡卒史。」","sentenceOrder":7},
  {"id":"s_work_han_thu_50_8","chapterId":"ch_work_han_thu_50","textTraditional":"〔七〕　師古曰：「課最上。」","sentenceOrder":8},
  {"id":"s_work_han_thu_50_9","chapterId":"ch_work_han_thu_50","textTraditional":"〔八〕　孟康曰：「當還入相秦事，故召何也。」師古曰：「此說非也。御史以何明辨，欲因入奏事之次，言於朝廷，徵何用之。何心不願，以情固請，而御史止，故得不行也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_50_10","chapterId":"ch_work_han_thu_50","textTraditional":"及高祖起為沛公，何嘗為丞督事。〔一〕沛公至咸陽，諸將皆爭走金帛財物之府分之，〔二〕何獨先入收秦丞相御史律令圖書臧之。沛公具知天下阨塞，戶口多少，彊弱處，民所疾苦者，以何得秦圖書也。","sentenceOrder":10},
  {"id":"s_work_han_thu_50_11","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　師古曰：「督謂監視之也。何為沛丞，專督眾事。」","sentenceOrder":11},
  {"id":"s_work_han_thu_50_12","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　師古曰：「走謂趣向之，音奏。」","sentenceOrder":12},
  {"id":"s_work_han_thu_50_13","chapterId":"ch_work_han_thu_50","textTraditional":"初，諸侯相與約，先入關破秦者王其地。沛公既先定秦，項羽後至，欲攻沛公，沛公謝之得解。羽遂屠燒咸陽，與范增謀曰：「巴蜀道險，秦之遷民皆居蜀。」乃曰：「蜀漢亦關中地也。」故立沛公為漢王，而三分關中地，王秦降將以距漢王。漢王怒，欲謀攻項羽。周勃、灌嬰、樊噲皆勸之，何諫之曰：「雖王漢中之惡，不猶愈於死乎？」〔一〕漢王曰：「何為乃死也？」何曰：「今眾弗如，百戰百敗，不死何為？周書曰『天予不取，反受其咎』。〔二〕語曰『天漢』，其稱甚美。〔三〕夫能詘於一人之下，而信於萬乘之上者，湯武是也。〔四〕臣願大王王漢中，養其民以致賢人，收用巴蜀，還定三秦，天下可圖也。」漢王曰：「善。」乃遂就國，以何為丞相。何進韓信，漢王以為大將軍，說漢王令引兵東定三秦。語在信傳。","sentenceOrder":13},
  {"id":"s_work_han_thu_50_14","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　師古曰：「愈，勝也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_50_15","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　師古曰：「周書者，本與尚書同類，蓋孔子所刪百篇之外，劉向所奏有七十一篇。」","sentenceOrder":15},
  {"id":"s_work_han_thu_50_16","chapterId":"ch_work_han_thu_50","textTraditional":"〔三〕　孟康曰：「語，古語也。言地之有漢，若天之有河漢，名號休美。」臣瓚曰：「流俗語云『天漢』，其言常以漢配天，此美名也。」師古曰：「瓚說是也。天漢，河漢也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_50_17","chapterId":"ch_work_han_thu_50","textTraditional":"〔四〕　師古曰：「信讀曰伸，古通用字。」","sentenceOrder":17},
  {"id":"s_work_han_thu_50_18","chapterId":"ch_work_han_thu_50","textTraditional":"何以丞相留收巴蜀，填撫諭告，〔一〕使給軍食。漢二年，漢王與諸侯擊楚，何守關中，侍太子，治櫟陽。為令約束，立宗廟、社稷、宮室、縣邑，輒奏，上可許以從事；〔二〕即不及奏，輒以便宜施行，上來以聞。〔三〕計戶轉漕給軍，漢王數失軍遯去，何常興關中卒，輒補缺。上以此剸屬任何關中事。〔四〕","sentenceOrder":18},
  {"id":"s_work_han_thu_50_19","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　師古曰：「填音竹刃反。」","sentenceOrder":19},
  {"id":"s_work_han_thu_50_20","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　師古曰：「可其所奏，許其所請，依以行事。」","sentenceOrder":20},
  {"id":"s_work_han_thu_50_21","chapterId":"ch_work_han_thu_50","textTraditional":"〔三〕　應劭曰：「上來還，乃以所為聞也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_50_22","chapterId":"ch_work_han_thu_50","textTraditional":"〔四〕　師古曰：「剸讀與專同，又音章阮反。此即言專聲之急上者也，（又）〔今〕俗語猶然。他皆類此。屬音之欲反。」","sentenceOrder":22},
  {"id":"s_work_han_thu_50_23","chapterId":"ch_work_han_thu_50","textTraditional":"漢三年，與項羽相距京、索間，〔一〕上數使使勞苦丞相。〔二〕鮑生謂何曰：〔三〕「今王暴衣露蓋，數勞苦君者，有疑君心。為君計，莫若遣君子孫昆弟能勝兵者悉詣軍所，上益信君。」於是何從其計，漢王大說。〔四〕","sentenceOrder":23},
  {"id":"s_work_han_thu_50_24","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　師古曰：「索音山客反。」","sentenceOrder":24},
  {"id":"s_work_han_thu_50_25","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　師古曰：「勞音來到反。次下亦同。」","sentenceOrder":25},
  {"id":"s_work_han_thu_50_26","chapterId":"ch_work_han_thu_50","textTraditional":"〔三〕　師古曰：「鮑生，當時有識之士，姓鮑而為諸生也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_50_27","chapterId":"ch_work_han_thu_50","textTraditional":"〔四〕　師古曰：「說讀曰悅。」","sentenceOrder":27},
  {"id":"s_work_han_thu_50_28","chapterId":"ch_work_han_thu_50","textTraditional":"漢五年，已殺項羽，即皇帝位，論功行封，群臣爭功，歲餘不決。上以何功最盛，先封為酇侯，〔一〕食邑八千戶。功臣皆曰：「臣等身被堅執兵，多者百餘戰，少者數十合，攻城略地，大小各有差。今蕭何未有汗馬之勞，徒持文墨議論，不戰，顧居臣等上，何也？」〔二〕上曰：「諸君知獵乎？」曰：「知之。」「知獵狗乎？」曰：「知之。」上曰：「夫獵，追殺獸者狗也，而發縱指示獸處者人也。〔三〕今諸君徒能走得獸耳，功狗也；至如蕭何，發縱指示，功人也。且諸君獨以身從我，多者三兩人；蕭何舉宗數十人皆隨我，功不可忘也！」群臣後皆莫敢言。","sentenceOrder":28},
  {"id":"s_work_han_thu_50_29","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　文穎曰：「音贊。」師古曰：「先封何者，謂諸功臣舊未爵者，何最在前封也。酇屬南陽，解在高紀。」","sentenceOrder":29},
  {"id":"s_work_han_thu_50_30","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　師古曰：「顧猶反也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_50_31","chapterId":"ch_work_han_thu_50","textTraditional":"〔三〕　師古曰：「發縱，謂解紲而放之也。指示者，以手指示之，今俗言放狗。縱音子用反，而讀者乃為蹤蹟之蹤，非也。書本皆不為蹤字。自有逐蹤之狗，不待人發也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_50_32","chapterId":"ch_work_han_thu_50","textTraditional":"列侯畢已受封，奏位次，皆曰：「平陽侯曹參身被七十創，攻城略地，功最多，宜第一。」上已橈功臣多封何，〔一〕至位次未有以復難之，然心欲何第一。關內侯鄂（千）秋時為謁者，進曰：「群臣議皆誤。夫曹參雖有野戰略地之功，此特一時之事。夫上與楚相距五歲，失軍亡眾，跳身遯者數矣，〔二〕然蕭何常從關中遣軍補其處。非上所詔令召，而數萬眾會上乏絕者數矣。夫漢與楚相守滎陽數年，軍無見糧，〔三〕蕭何轉漕關中，給食不乏。陛下雖數亡山東，蕭何常全關中待陛下，此萬世功也。今雖無曹參等百數，何缺於漢？〔四〕漢得之不必待以全。柰何欲以一旦之功（而）加萬世之功哉！蕭何當第一，曹參次之。」上曰：「善。」於是乃令何第一，賜帶劍履上殿，入朝不趨。上曰：「吾聞進賢受上賞，蕭何功雖高，待鄂君乃得明。」於是因鄂（千）秋故所食關內侯邑二千戶，封為安平侯。是日，悉封何父母兄弟十餘人，皆食邑。乃益封何二千戶，「以嘗繇咸陽時何送我獨贏錢二也」。〔五〕","sentenceOrder":32},
  {"id":"s_work_han_thu_50_33","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　應劭曰：「橈，屈也。」師古曰：「音女教反。」","sentenceOrder":33},
  {"id":"s_work_han_thu_50_34","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　師古曰：「跳身，謂輕身走出也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_50_35","chapterId":"ch_work_han_thu_50","textTraditional":"〔三〕　師古曰：「無見在之糧。」","sentenceOrder":35},
  {"id":"s_work_han_thu_50_36","chapterId":"ch_work_han_thu_50","textTraditional":"〔四〕　師古曰：「數音所具反。」","sentenceOrder":36},
  {"id":"s_work_han_thu_50_37","chapterId":"ch_work_han_thu_50","textTraditional":"〔五〕　師古曰：「贏，餘也。二謂二百也。眾人送皆三百，何獨五百，故云贏二也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_50_38","chapterId":"ch_work_han_thu_50","textTraditional":"陳豨反，上自將，至邯鄲。而韓信謀反關中。呂后用何計誅信。語在信傳。上已聞誅信，使使拜丞相為相國，益封五千戶，令卒五百人一都尉為相國衛。諸君皆賀，召平獨弔。〔一〕召平者，故秦東陵侯。秦破，為布衣，貧，種瓜長安城東，瓜美，故世謂「東陵瓜」，從召平始也。平謂何曰：「禍自此始矣。上暴露於外，而君守於內，非被矢石之難，而益君封置衛者，以今者淮陰新反於中，有疑君心。夫置衛衛君，非以寵君也。〔二〕願君讓封勿受，悉以家私財佐軍。」何從其計，上說。〔三〕","sentenceOrder":38},
  {"id":"s_work_han_thu_50_39","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　師古曰：「召讀曰邵。」","sentenceOrder":39},
  {"id":"s_work_han_thu_50_40","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　師古曰：「恐其為變，故守衛之。」","sentenceOrder":40},
  {"id":"s_work_han_thu_50_41","chapterId":"ch_work_han_thu_50","textTraditional":"〔三〕　師古曰：「說讀曰悅。」","sentenceOrder":41},
  {"id":"s_work_han_thu_50_42","chapterId":"ch_work_han_thu_50","textTraditional":"其秋，黥布反，上自將擊之，數使使問相國何為。〔一〕曰：「為上在軍，拊循勉百姓，悉所有佐軍，如陳豨時。」〔二〕客又說何曰：「君滅族不久矣。夫君位為相國，功第一，不可復加。然君初入關，本得百姓心，十餘年矣。皆附君，尚復孳孳得民和。〔三〕上所謂數問君，畏君傾動關中。今君胡不多買田地，賤貰貣以自汙？上心必安。」〔四〕於是何從其計，上乃大說。〔五〕","sentenceOrder":42},
  {"id":"s_work_han_thu_50_43","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　師古曰：「問其居守，何所營為。」","sentenceOrder":43},
  {"id":"s_work_han_thu_50_44","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　師古曰：「悉，盡也，盡所有糧食資用出以佐軍也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_50_45","chapterId":"ch_work_han_thu_50","textTraditional":"〔三〕　師古曰：「孳字與孜同。孜孜，言不怠也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_50_46","chapterId":"ch_work_han_thu_50","textTraditional":"〔四〕　師古曰：「貰，賒也。貣音土得反。」","sentenceOrder":46},
  {"id":"s_work_han_thu_50_47","chapterId":"ch_work_han_thu_50","textTraditional":"〔五〕　師古曰：「說讀曰悅。」","sentenceOrder":47},
  {"id":"s_work_han_thu_50_48","chapterId":"ch_work_han_thu_50","textTraditional":"上罷布軍歸，民道遮行，〔一〕上書言相國彊賤買民田宅數千人。上至，何謁。上笑曰：「今相國乃利民！」民所上書皆以與何，曰：「君自謝民。」後何為民請曰：「長安地陿，上林中多空地，棄，願令民得入田，毋收稿為獸食。」〔二〕上大怒曰：「相國多受賈人財物，為請吾苑！」乃下何廷尉，械繫之。數日，王衛尉侍，〔三〕前問曰：「相國胡大罪，陛下繫之暴也？」〔四〕上曰：「吾聞李斯相秦皇帝，有善歸主，有惡自予。今相國多受賈豎金，為請吾苑，以自媚於民。〔五〕故繫治之。」王衛尉曰：「夫職事苟有便於民而請之，真宰相事也。陛下柰何乃疑相國受賈人錢乎！且陛下距楚數歲，陳豨、黥布反時，陛下自將往，當是時相國守關中，關中搖足則關西非陛下有也。相國不以此時為利，乃利賈人之金乎？且秦以不聞其過亡天下，夫李斯之分過，又何足法哉！陛下何疑宰相之淺也！」上不懌。〔六〕是日，使使持節赦出何。何年老，素恭謹，徒跣入謝。上曰：「相國休矣！〔七〕相國為民請吾苑不許，我不過為桀紂主，而相國為賢相。吾故繫相國，欲令百姓聞吾過。」","sentenceOrder":48},
  {"id":"s_work_han_thu_50_49","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　師古曰：「在道上遮天子行。」","sentenceOrder":49},
  {"id":"s_work_han_thu_50_50","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　師古曰：「稿，禾稈也。言恣人田之，不收其稿稅也。稿音工老反。稈音工旱反。」","sentenceOrder":50},
  {"id":"s_work_han_thu_50_51","chapterId":"ch_work_han_thu_50","textTraditional":"〔三〕　如淳曰：「百官公卿表『衛尉王氏』，無名字。」師古曰：「史失之也。侍謂侍天子也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_50_52","chapterId":"ch_work_han_thu_50","textTraditional":"〔四〕　師古曰：「前問，謂進而請也。胡，何也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_50_53","chapterId":"ch_work_han_thu_50","textTraditional":"〔五〕　師古曰：「媚，愛也，求愛於民。」","sentenceOrder":53},
  {"id":"s_work_han_thu_50_54","chapterId":"ch_work_han_thu_50","textTraditional":"〔六〕　師古曰：「懌，悅也。感衛尉之言，故慚悔而不悅也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_50_55","chapterId":"ch_work_han_thu_50","textTraditional":"〔七〕　師古曰：「令出外自休息。」","sentenceOrder":55},
  {"id":"s_work_han_thu_50_56","chapterId":"ch_work_han_thu_50","textTraditional":"高祖崩，何事惠帝。何病，上親自臨視何疾，因問曰：「君即百歲後，誰可代君？」對曰：「知臣莫如主。」帝曰：「曹參何如？」何頓首曰：「帝得之矣。何死不恨矣！」","sentenceOrder":56},
  {"id":"s_work_han_thu_50_57","chapterId":"ch_work_han_thu_50","textTraditional":"何買田宅必居窮辟處，〔一〕為家不治垣屋。〔二〕曰：「令後世賢，師吾儉；不賢，毋為勢家所奪。」","sentenceOrder":57},
  {"id":"s_work_han_thu_50_58","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　師古曰：「辟讀曰僻。僻，隱也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_50_59","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　師古曰：「垣，牆也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_50_60","chapterId":"ch_work_han_thu_50","textTraditional":"孝惠二年，何薨，諡曰文終侯。子祿嗣，薨，無子。高后乃封何夫人同為酇侯，小子延為筑陽侯。〔一〕孝文元年，罷同，更封延為酇侯。薨，子遺嗣。薨，無子。文帝復以遺弟則嗣，有罪免。景帝二年，制詔御史：「故相國蕭何，高皇帝大功臣，所與為天下也。〔二〕今其祀絕，朕甚憐之。其以武陽縣戶二千封何孫嘉為列侯。」嘉，則弟也。薨，子勝嗣，後有罪免。武帝元狩中，復下詔御史：「以酇戶二千四百封何曾孫慶為酇侯，布告天下，令明知朕報蕭相國德也。」慶，則子也。薨，子壽成嗣，坐為太常（儀）〔犧〕牲瘦免。宣帝時，詔丞相御史求問蕭相國後在者，得玄孫建世等十二人，復下詔以酇戶二千封建世為酇侯。傳子至孫獲，坐使奴殺人減死論。成帝時，復封何玄孫之子南〈糸言糸〉長喜為酇侯。〔三〕傳子至曾孫，王莽敗乃絕。","sentenceOrder":60},
  {"id":"s_work_han_thu_50_61","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　師古曰：「酇及筑陽皆南陽縣也。今其地（見）〔並〕屬襄州。筑音逐。」","sentenceOrder":61},
  {"id":"s_work_han_thu_50_62","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　師古曰：「為，治也。亦曰共造其功業。」","sentenceOrder":62},
  {"id":"s_work_han_thu_50_63","chapterId":"ch_work_han_thu_50","textTraditional":"〔三〕　蘇林曰：「〈糸言糸〉音人足攣躃之攣，鉅鹿縣名也。」師古曰：「喜為此縣之長。」","sentenceOrder":63},
  {"id":"s_work_han_thu_50_64","chapterId":"ch_work_han_thu_50","textTraditional":"曹參，沛人也。秦時為獄掾，而蕭何為主吏，居縣為豪吏矣〔一〕。高祖為沛公也，參以中涓從。〔二〕擊胡陵、方與，〔三〕攻秦監公軍，大破之。〔四〕東下薛，擊泗水守軍薛郭西。復攻胡陵，取之。徙守方與。方與反為魏，擊之。豐反為魏，攻之。賜爵七大夫。北擊司馬欣軍碭東，取狐父、祁善置。〔五〕又攻下邑以西，至虞，擊秦將章邯車騎。攻轅戚及亢父，〔六〕先登。遷為五大夫。北救東阿，擊章邯軍，陷陳，追至濮陽。攻定陶，取臨濟。南救雍丘，擊李由軍，破之，殺李由，虜秦候一人。章邯破殺項梁也，沛公與項羽引兵而東。楚懷王以沛公為碭郡長，將碭郡兵。於是乃封參執帛，〔七〕號曰建成君。遷為戚公，屬碭郡。〔八〕","sentenceOrder":64},
  {"id":"s_work_han_thu_50_65","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　師古曰：「言參及蕭何為吏之豪長也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_50_66","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　如淳曰：「中涓，如中謁者也。」師古曰：「涓，絜也，言其在內主知絜清灑埽之事，蓋親近左右也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_50_67","chapterId":"ch_work_han_thu_50","textTraditional":"〔三〕　師古曰：「音房豫。」","sentenceOrder":67},
  {"id":"s_work_han_thu_50_68","chapterId":"ch_work_han_thu_50","textTraditional":"〔四〕　孟康曰：「監，御史監郡者。公，名也。」晉灼曰：「按高紀名平也。秦一郡置守尉監三人。」師古曰：「公者，時人尊稱之耳。晉說是也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_50_69","chapterId":"ch_work_han_thu_50","textTraditional":"〔五〕　文穎曰：「善置，置名也。」晉灼曰：「祁音坻。」師古曰：「狐父、祁，二縣名也。祁音鉅夷反，又音十夷反。父音甫。置若今之驛也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_50_70","chapterId":"ch_work_han_thu_50","textTraditional":"〔六〕　師古曰：「亢父音抗甫。」","sentenceOrder":70},
  {"id":"s_work_han_thu_50_71","chapterId":"ch_work_han_thu_50","textTraditional":"〔七〕　鄭氏曰：「楚爵也。」張晏曰：「孤卿也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_50_72","chapterId":"ch_work_han_thu_50","textTraditional":"〔八〕　師古曰：「為戚縣之令。」","sentenceOrder":72},
  {"id":"s_work_han_thu_50_73","chapterId":"ch_work_han_thu_50","textTraditional":"其後從攻東郡尉軍，破之成武南。擊王離軍成陽南，又攻杠里，大破之。追北，西至開封，擊趙賁軍，破之，〔一〕圍趙賁開封城中。西擊秦將楊熊軍於曲遇，〔二〕破之，虜秦司馬及御史各一人。遷為執珪。〔三〕從西攻陽武，下轘轅、緱氏，絕河津。擊趙賁軍尸北，破之。〔四〕從南攻犨，與南陽守齮戰陽城郭東，〔五〕陷陳，取宛，虜齮，定南陽郡。〔六〕從西攻武關、嶢關，取之。〔七〕前攻秦軍藍田南，又夜擊其北軍，大破之，遂至咸陽，破秦。","sentenceOrder":73},
  {"id":"s_work_han_thu_50_74","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　師古曰：「賁音奔。」","sentenceOrder":74},
  {"id":"s_work_han_thu_50_75","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　師古曰：「曲音丘羽反。遇音顒。」","sentenceOrder":75},
  {"id":"s_work_han_thu_50_76","chapterId":"ch_work_han_thu_50","textTraditional":"〔三〕　張晏曰：「侯伯執珪，以朝位比之。」如淳曰：「呂氏春秋『得五員者位執珪』，古爵名也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_50_77","chapterId":"ch_work_han_thu_50","textTraditional":"〔四〕　孟康曰：「尸鄉之北。」","sentenceOrder":77},
  {"id":"s_work_han_thu_50_78","chapterId":"ch_work_han_thu_50","textTraditional":"〔五〕　應劭曰：「今堵陽。」","sentenceOrder":78},
  {"id":"s_work_han_thu_50_79","chapterId":"ch_work_han_thu_50","textTraditional":"〔六〕　師古曰：「高紀言『南陽守齮降，封為殷侯』，而此傳言虜齮，紀傳不同，疑傳誤。」","sentenceOrder":79},
  {"id":"s_work_han_thu_50_80","chapterId":"ch_work_han_thu_50","textTraditional":"〔七〕　師古曰：「嶢音堯。」","sentenceOrder":80},
  {"id":"s_work_han_thu_50_81","chapterId":"ch_work_han_thu_50","textTraditional":"項羽至，以沛公為漢王。漢王封參為建成侯。從至漢中，遷為將軍。從還定三秦，攻下辨、故道、〔一〕雍、斄。〔二〕擊章平軍於好畤南，破之，圍好畤，取壤鄉。〔三〕擊三秦軍壤東及高櫟，破之。〔四〕復圍章平，平出好畤走。因擊趙賁、內史保軍，破之。東取咸陽，更名曰新城。參將兵守景陵二十三日，〔五〕三秦使章平等攻參，參出擊，大破之。賜食邑於寧秦。〔六〕以將軍引兵圍章邯廢丘；以中尉從漢王出臨晉關。至河內，下脩武，度圍津，〔七〕東擊龍且、項佗定陶，破之。〔八〕東取碭、蕭、彭城。擊項籍軍，漢軍大敗走。參以中尉圍取雍丘。王武反於外黃，程處反於燕，〔九〕往擊，盡破之。柱天侯反於衍氏，進破取衍氏。擊羽嬰於昆陽，追至葉。〔一０〕還攻武彊，〔一一〕因至滎陽。參自漢中為將軍中尉，從擊諸侯，及項王敗，還至滎陽。〔一二〕","sentenceOrder":81},
  {"id":"s_work_han_thu_50_82","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　鄧展曰：「武都二縣也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_50_83","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　蘇林曰：「右扶風二縣也。斄音胎。」","sentenceOrder":83},
  {"id":"s_work_han_thu_50_84","chapterId":"ch_work_han_thu_50","textTraditional":"〔三〕　文穎曰：「壤，地名也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_50_85","chapterId":"ch_work_han_thu_50","textTraditional":"〔四〕　師古曰：「櫟音歷。」","sentenceOrder":85},
  {"id":"s_work_han_thu_50_86","chapterId":"ch_work_han_thu_50","textTraditional":"〔五〕　孟康曰：「縣名也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_50_87","chapterId":"ch_work_han_thu_50","textTraditional":"〔六〕　蘇林曰：「今華陰。」","sentenceOrder":87},
  {"id":"s_work_han_thu_50_88","chapterId":"ch_work_han_thu_50","textTraditional":"〔七〕　師古曰：「在東郡。」","sentenceOrder":88},
  {"id":"s_work_han_thu_50_89","chapterId":"ch_work_han_thu_50","textTraditional":"〔八〕　師古曰：「且音子餘反。佗音徒何反。」","sentenceOrder":89},
  {"id":"s_work_han_thu_50_90","chapterId":"ch_work_han_thu_50","textTraditional":"〔九〕　服虔曰：「皆漢將。」師古曰：「燕，東郡之縣，故南燕國。音一千反。」","sentenceOrder":90},
  {"id":"s_work_han_thu_50_91","chapterId":"ch_work_han_thu_50","textTraditional":"〔一０〕師古曰：「葉，南陽縣也，音式涉反。」","sentenceOrder":91},
  {"id":"s_work_han_thu_50_92","chapterId":"ch_work_han_thu_50","textTraditional":"〔一一〕師古曰：「武彊城在陽武。」","sentenceOrder":92},
  {"id":"s_work_han_thu_50_93","chapterId":"ch_work_han_thu_50","textTraditional":"〔一二〕師古曰：「敗謂戰彭城而敗。」","sentenceOrder":93},
  {"id":"s_work_han_thu_50_94","chapterId":"ch_work_han_thu_50","textTraditional":"漢二年，拜為假左丞相，入屯兵關中。月餘，魏王豹反，以假丞相別與韓信東攻魏將孫速東張，〔一〕大破之。因攻安邑，得魏將王襄。擊魏王於曲陽，追至東垣，生獲魏王豹。取平陽，得豹母妻子，盡定魏地，凡五十二縣。賜食邑平陽。因從韓信擊趙相國夏說軍於鄔東，〔二〕大破之，斬夏說。韓信與故常山王張耳引兵下井陘，擊成安君陳餘，而令參還圍趙別將戚公於鄔城中。戚公出走，追斬之。乃引兵詣漢王在所。韓信已破趙，為相國，東擊齊，參以左丞相屬焉。攻破齊歷下軍，遂取臨淄。還定濟北郡，收著、漯陰、平原、鬲、盧。〔三〕已而從韓信擊龍且軍於上假密，〔四〕大破之，斬龍且，虜亞將周蘭。〔五〕定齊郡，凡得七十縣。得故齊王田廣相田光，其守相許章，及故將軍田既。〔六〕韓信立為齊王，引兵東詣陳，與漢王共破項羽，而參留平齊未服者。","sentenceOrder":94},
  {"id":"s_work_han_thu_50_95","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　蘇林曰：「東張屬河東。」師古曰：「〈辶欶〉，古速字。」","sentenceOrder":95},
  {"id":"s_work_han_thu_50_96","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　蘇林曰：「鄔，太原縣也。」師古曰：「說讀曰悅。鄔音一戶反，又音乙據反。」","sentenceOrder":96},
  {"id":"s_work_han_thu_50_97","chapterId":"ch_work_han_thu_50","textTraditional":"〔三〕　師古曰：「五縣名也。時未有濟北郡，史追書之耳。著音竹庶反，又音直庶反。漯音它合反。鬲與隔同。」","sentenceOrder":97},
  {"id":"s_work_han_thu_50_98","chapterId":"ch_work_han_thu_50","textTraditional":"〔四〕　文穎曰：「或以為高密。」","sentenceOrder":98},
  {"id":"s_work_han_thu_50_99","chapterId":"ch_work_han_thu_50","textTraditional":"〔五〕　師古曰：「亞將，次將也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_50_100","chapterId":"ch_work_han_thu_50","textTraditional":"〔六〕　師古曰：「守相，為相居守者。」","sentenceOrder":100},
  {"id":"s_work_han_thu_50_101","chapterId":"ch_work_han_thu_50","textTraditional":"漢王即皇帝位，韓信徙為楚王。參歸相印焉。高祖以長子肥為齊王，而以參為相國。高祖六年，與諸侯剖符，賜參爵列侯，食邑平陽萬六百三十戶，世世勿絕。","sentenceOrder":101},
  {"id":"s_work_han_thu_50_102","chapterId":"ch_work_han_thu_50","textTraditional":"參以齊相國擊陳豨將張春，破之。黥布反，參從悼惠王將車騎十二萬，與高祖會擊黥布軍，大破之。南至蘄，還定竹邑、相、蕭、留。〔一〕","sentenceOrder":102},
  {"id":"s_work_han_thu_50_103","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　師古曰：「四縣名。」","sentenceOrder":103},
  {"id":"s_work_han_thu_50_104","chapterId":"ch_work_han_thu_50","textTraditional":"參功：凡下二國，縣百二十二；得王二人，相三人，將軍六人，大莫囂、郡守、司馬、候、御史各一人。〔一〕","sentenceOrder":104},
  {"id":"s_work_han_thu_50_105","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　如淳曰：「囂音敖。」張晏曰：「莫敖，楚卿號也。時近六國，故有令尹、莫敖之官。」","sentenceOrder":105},
  {"id":"s_work_han_thu_50_106","chapterId":"ch_work_han_thu_50","textTraditional":"孝惠元年，除諸侯相國法，更以參為齊丞相。參之相齊，齊七十城。天下初定，悼惠王富於春秋，參盡召長老諸先生，問所以安集百姓。而齊故諸儒以百數，〔一〕言人人殊，參未知所定。聞膠西有蓋公，〔二〕善治黃老言，〔三〕使人厚幣請之。既見蓋公，蓋公為言治道貴清靜而民自定，推此類具言之。參於是避正堂，舍蓋公焉〔四〕。其治要用黃老術，故相齊九年，齊國安集，大稱賢相。","sentenceOrder":106},
  {"id":"s_work_han_thu_50_107","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　師古曰：「數音所具反。」","sentenceOrder":107},
  {"id":"s_work_han_thu_50_108","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　師古曰：「蓋音古盍反。」","sentenceOrder":108},
  {"id":"s_work_han_thu_50_109","chapterId":"ch_work_han_thu_50","textTraditional":"〔三〕　張晏曰：「黃帝、老子之書。」","sentenceOrder":109},
  {"id":"s_work_han_thu_50_110","chapterId":"ch_work_han_thu_50","textTraditional":"〔四〕　師古曰：「舍，止也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_50_111","chapterId":"ch_work_han_thu_50","textTraditional":"蕭何薨，參聞之，告舍人趣治行，〔一〕「吾且入相。」居無何，使者果召參。參去，屬其後相〔二〕曰：「以齊獄市為寄，慎勿擾也。」後相曰：「治無大於此者乎？」參曰：「不然。夫獄市者，所以并容也，今君擾之，姦人安所容乎？吾是以先之。」〔三〕","sentenceOrder":111},
  {"id":"s_work_han_thu_50_112","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　師古曰：「舍人猶家人也，一說私屬官主家事者也。趣讀曰促，謂速也。治行，謂脩治行裝也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_50_113","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　師古曰：「屬音之欲反。」","sentenceOrder":113},
  {"id":"s_work_han_thu_50_114","chapterId":"ch_work_han_thu_50","textTraditional":"〔三〕　孟康曰：「夫獄市者，兼受善惡，若窮極姦人，姦人無所容竄，久且為亂。秦人極刑而天下畔，孝武峻法而獄繁，此其效也。」師古曰：「老子云『我無為，民自化；我好靜，民自正。』參欲以道化為本，不欲擾其末也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_50_115","chapterId":"ch_work_han_thu_50","textTraditional":"始參微時，與蕭何善，及為宰相，有隙。〔一〕至何且死，所推賢唯參。參代何為相國，舉事無所變更，壹遵何之約束。〔二〕擇郡國吏長大，〔三〕訥於文辭，謹厚長者，即召除為丞相史。吏言文刻深，欲務聲名，輒斥去之。〔四〕日夜飲酒。卿大夫以下吏及賓客見參不事事，〔五〕來者皆欲有言。至者，參輒飲以醇酒，〔六〕度之欲有言，復飲酒，醉而後去，〔七〕終莫得開說，〔八〕以為常。","sentenceOrder":115},
  {"id":"s_work_han_thu_50_116","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　師古曰：「參自以戰鬥功多，而封賞每在何後，故怨何也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_50_117","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　師古曰：「舉，皆也，言凡事皆無變改。」","sentenceOrder":117},
  {"id":"s_work_han_thu_50_118","chapterId":"ch_work_han_thu_50","textTraditional":"〔三〕　孟康曰：「取年長大者。」","sentenceOrder":118},
  {"id":"s_work_han_thu_50_119","chapterId":"ch_work_han_thu_50","textTraditional":"〔四〕　師古曰：「斥，卻也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_50_120","chapterId":"ch_work_han_thu_50","textTraditional":"〔五〕　如淳曰：「不事丞相之事。」","sentenceOrder":120},
  {"id":"s_work_han_thu_50_121","chapterId":"ch_work_han_thu_50","textTraditional":"〔六〕　師古曰：「醇酒不澆，謂厚酒也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_50_122","chapterId":"ch_work_han_thu_50","textTraditional":"〔七〕　師古曰：「度音大各反。飲音於禁反。」","sentenceOrder":122},
  {"id":"s_work_han_thu_50_123","chapterId":"ch_work_han_thu_50","textTraditional":"〔八〕　如淳曰：「開謂有所啟白。」","sentenceOrder":123},
  {"id":"s_work_han_thu_50_124","chapterId":"ch_work_han_thu_50","textTraditional":"相舍後園近吏舍，吏舍日飲歌呼。〔一〕從吏患之，無如何〔二〕，乃請參遊後園。聞吏醉歌呼，從吏幸相國召按之。乃反取酒張坐飲，〔三〕大歌呼與相和。","sentenceOrder":124},
  {"id":"s_work_han_thu_50_125","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　師古曰：「呼音火故反。其下並同。」","sentenceOrder":125},
  {"id":"s_work_han_thu_50_126","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　師古曰：「從吏，吏之常從相者也。從音材用反。」","sentenceOrder":126},
  {"id":"s_work_han_thu_50_127","chapterId":"ch_work_han_thu_50","textTraditional":"〔三〕　師古曰：「張設坐席而飲也。坐音才臥反。」","sentenceOrder":127},
  {"id":"s_work_han_thu_50_128","chapterId":"ch_work_han_thu_50","textTraditional":"參見人之有細過，掩匿覆蓋之，府中無事。","sentenceOrder":128},
  {"id":"s_work_han_thu_50_129","chapterId":"ch_work_han_thu_50","textTraditional":"參子窋為中大夫。〔一〕惠帝怪相國不治事，以為「豈少朕與？」〔二〕乃謂窋曰：「女歸，試私從容問乃父〔三〕曰：『高帝新棄群臣，帝富於春秋，君為相國，日飲，無所請事，何以憂天下？』然無言吾告女也。」窋既洗沐歸，時間，自從其所諫參。〔四〕參怒而笞之二百，曰：「趣入侍，〔五〕天下事非乃所當言也。」至朝時，帝讓參〔六〕曰：「與窋胡治乎？〔七〕乃者我使諫君也。」〔八〕參免冠謝曰：「陛下自察聖武孰與高皇帝？」上曰：「朕乃安敢望先帝！」參曰：「陛下觀參孰與蕭何賢？」上曰：「君似不及也。」參曰：「陛下言之是也。且高皇帝與蕭何定天下，法令既明具，陛下垂拱，參等守職，遵而勿失，不亦可乎？」惠帝曰：「善。君休矣！」〔九〕","sentenceOrder":129},
  {"id":"s_work_han_thu_50_130","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　師古曰：「窋音張律反。」","sentenceOrder":130},
  {"id":"s_work_han_thu_50_131","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　師古曰：「言豈以我為年少故也。與讀曰歟。」","sentenceOrder":131},
  {"id":"s_work_han_thu_50_132","chapterId":"ch_work_han_thu_50","textTraditional":"〔三〕　師古曰：「乃，汝也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_50_133","chapterId":"ch_work_han_thu_50","textTraditional":"〔四〕　師古曰：「間謂空隙也。自從其所，猶言自出其意也。」","sentenceOrder":133},
  {"id":"s_work_han_thu_50_134","chapterId":"ch_work_han_thu_50","textTraditional":"〔五〕　師古曰：「趣讀曰促。」","sentenceOrder":134},
  {"id":"s_work_han_thu_50_135","chapterId":"ch_work_han_thu_50","textTraditional":"〔六〕　師古曰：「讓，責也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_50_136","chapterId":"ch_work_han_thu_50","textTraditional":"〔七〕　師古曰：「胡，何也。言共窋為何治也。治音丈吏反。」","sentenceOrder":136},
  {"id":"s_work_han_thu_50_137","chapterId":"ch_work_han_thu_50","textTraditional":"〔八〕　師古曰：「乃者猶言曩者。」","sentenceOrder":137},
  {"id":"s_work_han_thu_50_138","chapterId":"ch_work_han_thu_50","textTraditional":"〔九〕　師古曰：「且令出休息。」","sentenceOrder":138},
  {"id":"s_work_han_thu_50_139","chapterId":"ch_work_han_thu_50","textTraditional":"參為相國三年，薨，諡曰懿侯。百姓歌之曰：「蕭何為法，講若畫一；〔一〕曹參代之，守而勿失。載其清靖，民以寧壹。」〔二〕","sentenceOrder":139},
  {"id":"s_work_han_thu_50_140","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　文穎曰：「講或作較。」師古曰：「講，和也。畫一，言整齊也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_50_141","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　師古曰：「載猶乘也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_50_142","chapterId":"ch_work_han_thu_50","textTraditional":"窋嗣侯，高后時至御史大夫。傳國至曾孫襄，武帝時為將軍，擊匈奴，薨。子宗嗣，有罪，完為城旦。至哀帝時，乃封參玄孫之孫本始為平陽侯，二千戶，王莽時薨。子宏嗣，建武中先降河北，封平陽侯。至今八侯。","sentenceOrder":142},
  {"id":"s_work_han_thu_50_143","chapterId":"ch_work_han_thu_50","textTraditional":"贊曰：蕭何、曹參皆起秦刀筆吏，〔一〕當時錄錄未有奇節〔二〕。漢興，依日月之末光，〔三〕何以信謹守管籥，參與韓信俱征伐。〔四〕天下既定，因民之疾秦法，順流與之更始，二人同心，遂安海內。淮陰、黥布等已滅，唯何、參擅功名，位冠群臣，聲施後世，〔五〕為一代之宗臣，〔六〕慶流曲裔，盛矣哉！","sentenceOrder":143},
  {"id":"s_work_han_thu_50_144","chapterId":"ch_work_han_thu_50","textTraditional":"〔一〕　師古曰：「刀所以削書也，古者用簡牒，故吏皆以刀筆自隨也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_50_145","chapterId":"ch_work_han_thu_50","textTraditional":"〔二〕　師古曰：「錄錄猶鹿鹿，言在凡庶之中也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_50_146","chapterId":"ch_work_han_thu_50","textTraditional":"〔三〕　師古曰：「易文言云『聖人作而萬物睹』，又曰『見龍在田，天下文明』。贊言何、參值漢初興，故以日月為喻耳。」","sentenceOrder":146},
  {"id":"s_work_han_thu_50_147","chapterId":"ch_work_han_thu_50","textTraditional":"〔四〕　師古曰：「高祖出征，何每居守，故言守管籥。」","sentenceOrder":147},
  {"id":"s_work_han_thu_50_148","chapterId":"ch_work_han_thu_50","textTraditional":"〔五〕　師古曰：「冠謂居其首。」","sentenceOrder":148},
  {"id":"s_work_han_thu_50_149","chapterId":"ch_work_han_thu_50","textTraditional":"〔六〕　師古曰：「言為後世之所尊仰，故曰宗臣也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_50_150","chapterId":"ch_work_han_thu_50","textTraditional":"校勘記","sentenceOrder":150},
  {"id":"s_work_han_thu_50_151","chapterId":"ch_work_han_thu_50","textTraditional":"二００五頁　五行　何乃給泗水卒史事，〔六〕第一。　注〔六〕原在「卒史」下，明舊讀以「事第一」為句。　齊召南說「事」字當屬上句。","sentenceOrder":151},
  {"id":"s_work_han_thu_50_152","chapterId":"ch_work_han_thu_50","textTraditional":"二００七頁一五行　（又）〔今〕俗語猶然。　殿、局本都作「今」。","sentenceOrder":152},
  {"id":"s_work_han_thu_50_153","chapterId":"ch_work_han_thu_50","textTraditional":"二００九頁　二行　關內侯鄂（千）秋時為謁者，　景祐、殿本都無「千」字，下同。","sentenceOrder":153},
  {"id":"s_work_han_thu_50_154","chapterId":"ch_work_han_thu_50","textTraditional":"二００九頁　七行　柰何欲以一旦之功（而）加萬世之功哉！　景祐、殿本都無「而」字。","sentenceOrder":154},
  {"id":"s_work_han_thu_50_155","chapterId":"ch_work_han_thu_50","textTraditional":"二０一三頁　一行　坐為太常（儀）〔犧〕牲瘦免。　景祐、殿、局本都作「犧」，此誤。","sentenceOrder":155},
  {"id":"s_work_han_thu_50_156","chapterId":"ch_work_han_thu_50","textTraditional":"二０一三頁　五行　今其地（見）〔並〕屬襄州。　景祐、殿本都作「並」。","sentenceOrder":156},
  {"id":"s_work_han_thu_51_1","chapterId":"ch_work_han_thu_51","textTraditional":"張良字子房，其先韓人也。大父開地，〔一〕相韓昭侯、宣惠王、襄哀王。父平，相釐王、〔二〕悼惠王。悼惠王二十三年，平卒。卒二十歲，秦滅韓。良（年）少，未宦事韓。韓破，良家僮三百人，弟死不葬，悉以家財求客刺秦王，為韓報仇，以五世相韓故。〔三〕","sentenceOrder":1},
  {"id":"s_work_han_thu_51_2","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　應劭曰：「大父，祖父；開地，名也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_51_3","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「釐讀曰僖。」","sentenceOrder":3},
  {"id":"s_work_han_thu_51_4","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「從昭侯至悼惠王，凡五君。」","sentenceOrder":4},
  {"id":"s_work_han_thu_51_5","chapterId":"ch_work_han_thu_51","textTraditional":"良嘗學禮淮陽，東見倉海君，〔一〕得力士，為鐵椎重百二十斤。秦皇帝東游，至博狼沙中，〔二〕良與客狙擊秦皇帝，〔三〕誤中副車。〔四〕秦皇帝大怒，大索天下，〔五〕求賊急甚。良乃更名姓，亡匿下邳。〔六〕","sentenceOrder":5},
  {"id":"s_work_han_thu_51_6","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　晉灼曰：「海神也。」如淳曰：「東夷君長也。」師古曰：「二說並非。蓋當時賢者之號也。良既見之，因而求得力士。」","sentenceOrder":6},
  {"id":"s_work_han_thu_51_7","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　服虔曰：「河南陽武南地名也，今有亭。」師古曰：「狼音浪。」","sentenceOrder":7},
  {"id":"s_work_han_thu_51_8","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「狙謂密伺之，音千豫反，字本作覷。」","sentenceOrder":8},
  {"id":"s_work_han_thu_51_9","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「副謂後乘也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_51_10","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「索，搜也。索音山客反。」","sentenceOrder":10},
  {"id":"s_work_han_thu_51_11","chapterId":"ch_work_han_thu_51","textTraditional":"〔六〕　師古曰：「更，改也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_51_12","chapterId":"ch_work_han_thu_51","textTraditional":"良嘗閒從容步游下邳圯上，〔一〕有一老父，衣褐，至良所〔二〕，直墮其履圯下，〔三〕顧謂良曰：「孺子下取履！」〔四〕良愕然，欲歐之。〔五〕為其老，乃彊忍，下取履，因跪進。父以足受之，笑去。良殊大驚。父去里所，復還，〔六〕曰：「孺子可教矣。後五日平明，與我期此。」良因怪（之），跪曰：「諾。」五日平明，良往。父已先在，怒曰：「與老人期，後，何也？去，後五日蚤會。」〔七〕五日，雞鳴往。父又先在，復怒曰：「後，何也？去，後五日復蚤來。」五日，良夜半往。有頃，父亦來，喜曰：「當如是。」出一編書，〔八〕曰：「讀是則為王者師。後十年興。十三年，孺子見我，濟北穀城山下黃石即我已。」〔九〕遂去不見。旦日視其書，乃太公兵法。良因異之，常習〔讀〕誦。","sentenceOrder":12},
  {"id":"s_work_han_thu_51_13","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　服虔曰：「圯音頤，楚人謂橋曰圯。」應劭曰：「汜水之上也。」文穎曰：「沂水上橋也。」師古曰：「下邳之水，非汜水也，又非沂水。服說是矣。」","sentenceOrder":13},
  {"id":"s_work_han_thu_51_14","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「褐制若裘，今道士所服者是。」","sentenceOrder":14},
  {"id":"s_work_han_thu_51_15","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「直猶故也，一曰正也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_51_16","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「孺，幼也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_51_17","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「愕，驚貌也。歐，擊也，音一口反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_51_18","chapterId":"ch_work_han_thu_51","textTraditional":"〔六〕　師古曰：「行一里許而還來。」","sentenceOrder":18},
  {"id":"s_work_han_thu_51_19","chapterId":"ch_work_han_thu_51","textTraditional":"〔七〕　師古曰：「放良令去，戒以後會也。其下亦同。蚤音早。」","sentenceOrder":19},
  {"id":"s_work_han_thu_51_20","chapterId":"ch_work_han_thu_51","textTraditional":"〔八〕　師古曰：「編謂聯次之也。聯簡牘以為書，故云一編。編音鞭。」","sentenceOrder":20},
  {"id":"s_work_han_thu_51_21","chapterId":"ch_work_han_thu_51","textTraditional":"〔九〕　師古曰：「已，語終之辭。」","sentenceOrder":21},
  {"id":"s_work_han_thu_51_22","chapterId":"ch_work_han_thu_51","textTraditional":"居下邳，為任俠。項伯嘗殺人，從良匿。","sentenceOrder":22},
  {"id":"s_work_han_thu_51_23","chapterId":"ch_work_han_thu_51","textTraditional":"後十年，陳涉等起，良亦聚少年百餘人。景駒自立為楚假王，在留。良欲往從之，行道遇沛公。沛公將數千人略地下邳，遂屬焉。沛公拜良為廄將。〔一〕良數以太公兵法說沛公，沛公喜，常用其策。良為它人言，皆不省。〔二〕良曰：「沛公殆天授。」〔三〕故遂從不去。","sentenceOrder":23},
  {"id":"s_work_han_thu_51_24","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　服虔曰：「官名也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_51_25","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「省，視也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_51_26","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「殆，近也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_51_27","chapterId":"ch_work_han_thu_51","textTraditional":"沛公之薛，見項梁，共立楚懷王。良乃說項梁曰：「君已立楚後，韓諸公子橫陽君成賢，可立為王，益樹黨。」〔一〕項梁使良求韓成，立為韓王。以良為韓司徒，與韓王將千餘人西略韓地，得數城，秦輒復取之，往來為游兵潁川。","sentenceOrder":27},
  {"id":"s_work_han_thu_51_28","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「廣立六國之後共攻秦也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_51_29","chapterId":"ch_work_han_thu_51","textTraditional":"沛公之從雒陽南出轘轅，良引兵從沛公，下韓十餘城，擊楊熊軍。沛公乃令韓王成留守陽翟，與良俱南，攻下宛，西入武關。沛公欲以二萬人擊秦嶢關下軍，〔一〕良曰：「秦兵尚彊，未可輕。臣聞其將屠者子，賈豎易動以利。〔二〕願沛公且留壁，使人先行，為五萬人具食，益張旗幟諸山上，為疑兵，〔三〕令酈食其持重寶啗秦將。」〔四〕秦將果欲連和俱西襲咸陽，〔五〕沛公欲聽之。良曰：「此獨其將欲叛，士卒恐不從。不從必危，不如因其解擊之。」〔六〕沛公乃引兵擊秦軍，大破之。逐北至藍田，再戰，秦兵竟敗。遂至咸陽，秦王子嬰降沛公。","sentenceOrder":29},
  {"id":"s_work_han_thu_51_30","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「嶢音堯。」","sentenceOrder":30},
  {"id":"s_work_han_thu_51_31","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「商賈之人志無遠大，譬猶僮豎，故云賈豎。」","sentenceOrder":31},
  {"id":"s_work_han_thu_51_32","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「皆所以表己軍之多，誇示敵人。幟音式志反。」","sentenceOrder":32},
  {"id":"s_work_han_thu_51_33","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「啗音徒濫反，解在高紀。」","sentenceOrder":33},
  {"id":"s_work_han_thu_51_34","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「欲與漢王和而隨漢兵襲咸陽。」","sentenceOrder":34},
  {"id":"s_work_han_thu_51_35","chapterId":"ch_work_han_thu_51","textTraditional":"〔六〕　師古曰：「解讀曰懈。」","sentenceOrder":35},
  {"id":"s_work_han_thu_51_36","chapterId":"ch_work_han_thu_51","textTraditional":"沛公入秦，宮室帷帳狗馬重寶婦女以千數，意欲留居之。樊噲諫，沛公不聽。良曰：「夫秦為無道，故沛公得至此。為天下除殘去賊，宜縞素為資。〔一〕今始入秦，即安其樂，此所謂『助桀為虐』。且『忠言逆耳利於行，毒藥苦口利於病』，願沛公聽樊噲言。」沛公乃還軍霸上。","sentenceOrder":36},
  {"id":"s_work_han_thu_51_37","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　晉灼曰：「資，質也。欲令沛公反秦奢泰，服儉素以為資。」師古曰：「縞，白素也，音工老反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_51_38","chapterId":"ch_work_han_thu_51","textTraditional":"項羽至鴻門，欲擊沛公，項伯夜馳至沛公軍，私見良，欲與俱去。良曰：「臣為韓王送沛公，今（有事）〔事有〕急，亡去不義。」乃具語沛公。沛公大驚，曰：「為之柰何？」良曰：「沛公誠欲背項王邪？」沛公曰：「鯫生說我距關毋內諸侯，〔一〕秦地可王也，故聽之。」良曰：「沛公自度能卻項王乎？」〔二〕沛公默然，曰：「今為柰何？」良因要項伯見沛公。沛公與伯飲，為壽，結婚，令伯具言沛公不敢背項王，所以距關者，備它盜也。項羽後解，語在羽傳。","sentenceOrder":38},
  {"id":"s_work_han_thu_51_39","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　服虔曰：「鯫音七垢反。鯫，小人也。」臣瓚曰：「楚漢春秋鯫姓。」師古曰：「服說是也。音才垢反。」","sentenceOrder":39},
  {"id":"s_work_han_thu_51_40","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「卻音丘略反。」","sentenceOrder":40},
  {"id":"s_work_han_thu_51_41","chapterId":"ch_work_han_thu_51","textTraditional":"漢元年，沛公為漢王，王巴蜀，賜良金百溢，〔一〕珠二斗，良具以獻項伯。漢王亦因令良厚遺項伯，使請漢中地。〔二〕項王許之。漢王之國，良送至褒中，遣良歸韓。良因說漢王燒絕棧道，〔三〕示天下無還心，以固項王意。乃使良還。行，燒絕棧道。〔四〕","sentenceOrder":41},
  {"id":"s_work_han_thu_51_42","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕服虔曰：「二十兩曰溢。」師古曰：「秦以溢名金，若漢之論斤也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_51_43","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　服虔曰：「本不盡與漢中，故請求之。」","sentenceOrder":43},
  {"id":"s_work_han_thu_51_44","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「棧道，閣道也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_51_45","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「還謂歸還韓。且行且燒，所過之處皆燒之也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_51_46","chapterId":"ch_work_han_thu_51","textTraditional":"良歸至韓，聞項羽以良從漢王故，不遣韓王成之國，與俱東，至彭城殺之。時漢王還定三秦，良乃遺項羽書曰：「漢王失職，欲得關中，如約即止，不敢復東。」又以齊反書遺羽，曰：「齊與趙欲并滅楚。」項羽以故北擊齊。","sentenceOrder":46},
  {"id":"s_work_han_thu_51_47","chapterId":"ch_work_han_thu_51","textTraditional":"良乃間行歸漢。漢王以良為成信侯，從東擊楚。至彭城，漢王兵敗而還。至下邑，〔一〕漢王下馬踞鞍而問曰：「吾欲捐關已東等棄之，誰可與共功者？」〔二〕良曰：「九江王布，楚梟將，〔三〕與項王有隙，彭越與齊王田榮反梁地，此兩人可急使。而漢王之將獨韓信可屬大事，當一面。〔四〕即欲捐之，捐之此三人，楚可破也。」漢王乃遣隨何說九江王布，而使人連彭越。〔五〕及魏王豹反，使韓信特將北擊之，〔六〕因舉燕、（伐）〔代〕、齊、趙。然卒破楚者，此三人力也。","sentenceOrder":47},
  {"id":"s_work_han_thu_51_48","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「梁國之縣也，今屬宋州。」","sentenceOrder":48},
  {"id":"s_work_han_thu_51_49","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「捐關以東，謂不自有其地，將以與人，令其立功，共破楚也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_51_50","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「梟謂最勇健也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_51_51","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「屬，委也，音之欲反。」","sentenceOrder":51},
  {"id":"s_work_han_thu_51_52","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「與相連結也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_51_53","chapterId":"ch_work_han_thu_51","textTraditional":"〔六〕　師古曰：「特，獨也。專任之使將也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_51_54","chapterId":"ch_work_han_thu_51","textTraditional":"良多病，未嘗特將兵，常為畫策臣，時時從。","sentenceOrder":54},
  {"id":"s_work_han_thu_51_55","chapterId":"ch_work_han_thu_51","textTraditional":"漢三年，項羽急圍漢王於滎陽，漢王憂恐，與酈食其謀橈楚權。〔一〕酈生曰：「昔湯伐桀，封其後杞；武王誅紂，封其後宋。今秦無道，伐滅六國，無立錐之地。陛下誠復立六國後，此皆爭戴陛下德義，願為臣妾。德義已行，南面稱伯，〔二〕楚必斂衽而朝。」〔三〕漢王曰：「善。趣刻印，先生因行佩之。」〔四〕","sentenceOrder":55},
  {"id":"s_work_han_thu_51_56","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「橈，弱也，音女教反，其字從木。」","sentenceOrder":56},
  {"id":"s_work_han_thu_51_57","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「伯讀曰霸。」","sentenceOrder":57},
  {"id":"s_work_han_thu_51_58","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「衽，衣襟也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_51_59","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「趣讀曰促。佩謂授與六國使帶也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_51_60","chapterId":"ch_work_han_thu_51","textTraditional":"酈生未行，良從外來謁漢王。漢王方食，曰：「客有為我計橈楚權者。」具以酈生計告良曰：「於子房何如？」良曰：「誰為陛下畫此計者？陛下事去矣。」漢王曰：「何哉？」良曰：「臣請借前箸以籌之。〔一〕昔湯武伐桀紂封其後者，度能制其死命也。〔二〕今陛下能制項籍死命乎？其不可一矣。武王入殷，表商容閭，〔三〕式箕子門，〔四〕封比干墓，今陛下能乎？其不可二矣。發鉅橋之粟〔五〕，散鹿臺之財，〔六〕以賜貧窮，今陛下能乎？其不可三矣。殷事以畢，偃革為軒，〔七〕倒載干戈，示不復用，今陛下能乎？其不可四矣。休馬華山之陽，示無所為，今陛下能乎？其不可五矣。息牛桃林之野，〔八〕（示）天下不復輸積，今陛下能乎？其不可六矣。且夫天下游士，（左）〔離〕親戚，棄墳墓，〔九〕去故舊，從陛下者，但日夜望咫尺之地。今乃立六國後，唯無復立者，〔一０〕游士各歸事其主，從親戚，反故舊，陛下誰與取天下乎？其不可七矣。且楚唯毋彊，六國復橈而從之，〔一一〕陛下焉得而臣之？其不可八矣。誠用此謀，陛下事去矣。」漢王輟食吐哺，罵曰：「豎儒，幾敗乃公事！」〔一二〕令趣銷印。〔一三〕","sentenceOrder":60},
  {"id":"s_work_han_thu_51_61","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　張晏曰：「求借所食之箸用指畫也。或曰，前世湯武箸明之事，以籌度今時之不若也。」師古曰：「或說非也。箸音直庶反。」","sentenceOrder":61},
  {"id":"s_work_han_thu_51_62","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「度音大各反。」","sentenceOrder":62},
  {"id":"s_work_han_thu_51_63","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「商容，殷賢人也。里門曰閭。表謂顯異之。」","sentenceOrder":63},
  {"id":"s_work_han_thu_51_64","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「式亦表也。一說，至其門而撫車式，所以敬之。」","sentenceOrder":64},
  {"id":"s_work_han_thu_51_65","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　服虔曰：「鉅橋，倉名也。」師古曰：「許慎云鉅鹿之大橋，有漕粟也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_51_66","chapterId":"ch_work_han_thu_51","textTraditional":"〔六〕　臣瓚曰：「鹿臺，臺名，今在朝歌城中。」師古曰：「劉向云鹿臺大三里，高千尺也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_51_67","chapterId":"ch_work_han_thu_51","textTraditional":"〔七〕　蘇林曰：「革者，兵車革輅。軒者，朱軒也。」如淳曰：「偃武備而治禮樂也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_51_68","chapterId":"ch_work_han_thu_51","textTraditional":"〔八〕　晉灼曰：「在弘農閺鄉南谷中。」師古曰：「山海經云『夸父之山，北有林焉，名曰桃林，廣圍三百里』，即謂此也。其山谷今在閺鄉縣東南，湖城縣西南，去湖城三十五里。」","sentenceOrder":68},
  {"id":"s_work_han_thu_51_69","chapterId":"ch_work_han_thu_51","textTraditional":"〔九〕　師古曰：「（左）〔離〕者，言其乖避而委離之，以從漢也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_51_70","chapterId":"ch_work_han_thu_51","textTraditional":"〔一０〕師古曰：「既立六國後，土地皆盡，無以封功勞之人，故云無復立者。唯，發語之辭。」","sentenceOrder":70},
  {"id":"s_work_han_thu_51_71","chapterId":"ch_work_han_thu_51","textTraditional":"〔一一〕服虔曰：「唯當使楚無彊，彊則六國弱而從之。」晉灼曰：「當今唯楚大，無有彊之者，若復立六國，皆橈而從之，陛下焉得而臣之乎？」師古曰：「服說是也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_51_72","chapterId":"ch_work_han_thu_51","textTraditional":"〔一二〕師古曰：「輟，止也。哺，食在口中者也。幾，近也。哺音捕。幾音鉅依反。」","sentenceOrder":72},
  {"id":"s_work_han_thu_51_73","chapterId":"ch_work_han_thu_51","textTraditional":"〔一三〕師古曰：「趣讀曰促。」","sentenceOrder":73},
  {"id":"s_work_han_thu_51_74","chapterId":"ch_work_han_thu_51","textTraditional":"後韓信破齊欲自立為齊王，漢王怒。良說漢王，漢王使良授齊王信印。語在信傳。","sentenceOrder":74},
  {"id":"s_work_han_thu_51_75","chapterId":"ch_work_han_thu_51","textTraditional":"五年冬，漢王追楚至陽夏南，〔一〕戰不利，壁固陵，諸侯期不至。良說漢王，漢王用其計，諸侯皆至。語在高紀。","sentenceOrder":75},
  {"id":"s_work_han_thu_51_76","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「夏音工雅反。」","sentenceOrder":76},
  {"id":"s_work_han_thu_51_77","chapterId":"ch_work_han_thu_51","textTraditional":"漢六年，封功臣。良未嘗有戰鬥功，高帝曰：「運籌策帷幄中，決勝千里外，子房功也。自擇齊三萬戶。」良曰：「始臣起下邳，與上會留，此天以臣授陛下。陛下用臣計，幸而時中，臣願封留足矣，不敢當三萬戶。」乃封良為留侯，與蕭何等俱封。","sentenceOrder":77},
  {"id":"s_work_han_thu_51_78","chapterId":"ch_work_han_thu_51","textTraditional":"上已封大功臣二十餘人，其餘日夜爭功而不決，未得行封。上居雒陽南宮，從復道望見諸將〔一〕往往數人偶語。上曰：「此何語？」良曰：「陛下不知乎？此謀反耳。」上曰：「天下屬安定，何故而反？」〔二〕良曰：「陛下起布衣，與此屬取天下，今陛下已為天子，而所封皆蕭、曹故人所親愛，而所誅者皆平生仇怨。今軍吏計功，天下不足以遍封，此屬畏陛下不能盡封，又恐見疑過失及誅，故相聚而謀反耳。」上乃憂曰：「為將柰何？」良曰：「上平生所憎，群臣所共知，誰最甚者？」上曰：「雍齒與我有故怨，數窘辱我，〔三〕我欲殺之，為功多，不忍。」良曰：「今急先封雍齒，以示群臣，群臣見雍齒先封，則人人自堅矣。」於是上置酒，封雍齒為什方侯〔四〕，而急趣丞相御史定功行封。〔五〕群臣罷酒，皆喜曰：「雍齒且侯，我屬無患矣。」","sentenceOrder":78},
  {"id":"s_work_han_thu_51_79","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「復讀曰複。」","sentenceOrder":79},
  {"id":"s_work_han_thu_51_80","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「屬，近也，言近始安。屬音之欲反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_51_81","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　服虔曰：「未起之時與我有故怨也。」師古曰：「每以勇力困辱高祖。」","sentenceOrder":81},
  {"id":"s_work_han_thu_51_82","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　蘇林曰：「漢中縣也。」師古曰：地理志屬廣漢，非漢中也。今則屬益州。什音十。」","sentenceOrder":82},
  {"id":"s_work_han_thu_51_83","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「趣音促。」","sentenceOrder":83},
  {"id":"s_work_han_thu_51_84","chapterId":"ch_work_han_thu_51","textTraditional":"劉敬說上都關中，上疑之。左右大臣皆山東人，多勸上都雒陽：「雒陽東有成皋，西有殽黽，〔一〕背河鄉雒，其固亦足恃。」〔二〕良曰：「雒陽雖有此固，其中小，不過數百里，田地薄，四面受敵，此非用武之國。夫關中左殽函，右隴蜀，沃野千里，〔三〕南有巴蜀之饒，北有胡苑之利，〔四〕阻三面而固守，獨以一面東制諸侯。諸侯安定，河、渭漕輓天下，西給京師；〔五〕諸侯有變，順流而下，足以委輸。此所謂金城千里，天府之國。〔六〕劉敬說是也。」於是上即日駕，西都關中。","sentenceOrder":84},
  {"id":"s_work_han_thu_51_85","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「殽，山也。黽，池也，音湎。」","sentenceOrder":85},
  {"id":"s_work_han_thu_51_86","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":86},
  {"id":"s_work_han_thu_51_87","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「沃者，溉灌也。言其土地皆有溉灌之利，故云沃野。」","sentenceOrder":87},
  {"id":"s_work_han_thu_51_88","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「謂安定、北地、上郡之北與胡相接之地，可以畜牧者也。養禽獸謂之苑。」","sentenceOrder":88},
  {"id":"s_work_han_thu_51_89","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「輓，引也。輓音晚。」","sentenceOrder":89},
  {"id":"s_work_han_thu_51_90","chapterId":"ch_work_han_thu_51","textTraditional":"〔六〕　師古曰：「財物所聚謂之府。言關中之地物產饒多，可備贍給，故稱天府也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_51_91","chapterId":"ch_work_han_thu_51","textTraditional":"良從入關，性多疾，即道引不食穀，〔一〕閉門不出歲餘。","sentenceOrder":91},
  {"id":"s_work_han_thu_51_92","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　孟康曰：「服辟穀藥而靜居行氣。道讀曰導。」","sentenceOrder":92},
  {"id":"s_work_han_thu_51_93","chapterId":"ch_work_han_thu_51","textTraditional":"上欲廢太子，立戚夫人子趙王如意。大臣多爭，未能得堅決也。呂后恐，不知所為。或謂呂后曰：「留侯善畫計，上信用之。」呂后乃使建成侯呂澤劫良，曰：「君常為上謀臣，今上日欲易太子，〔一〕君安得高枕而臥？」〔二〕良曰：「始上數在急困之中，幸用臣策；今天下安定，以愛欲易太子，骨肉之間，雖臣等百人何益！」呂澤彊要曰：「為我畫計。」良曰：「此難以口舌爭也。顧上有所不能致者四人。〔三〕四人年老矣，皆以上嫚娒士，〔四〕故逃匿山中，義不為漢臣。然上高此四人。今公誠能毋愛金玉璧帛，令太子為書，卑辭安車，因使辨士固請，宜來。〔五〕來，以為客，時從入朝，令上見之，則一助也。」於是呂后令呂澤使人奉太子書，卑辭厚禮，迎此四人。四人至，客建成侯所。","sentenceOrder":93},
  {"id":"s_work_han_thu_51_94","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「言日日欲易之。」","sentenceOrder":94},
  {"id":"s_work_han_thu_51_95","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「安，焉也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_51_96","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「顧，念也。四人，謂園公、綺里季、夏黃公、甪里先生，所謂商山四皓也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_51_97","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「嫚與慢同。娒，古侮字。」","sentenceOrder":97},
  {"id":"s_work_han_thu_51_98","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「宜應得其來。」","sentenceOrder":98},
  {"id":"s_work_han_thu_51_99","chapterId":"ch_work_han_thu_51","textTraditional":"漢十一年，黥布反，上疾，欲使太子往擊之。四人相謂曰：「凡來者，將以存太子。太子將兵，事危矣。」乃說建成侯曰：「太子將兵，有功即位不益，〔一〕無功則從此受禍。且太子所與俱諸將，皆與上定天下梟將也，今乃使太子將之，此無異使羊將狼，皆不肯為用，其無功必矣。臣聞『母愛者子抱』，今戚夫人日夜侍御，趙王常居前，上〔曰〕『終不使不肖子居愛子上』，明〔其〕代太子位必矣。君何不急請呂后承間為上泣〔二〕言：『黥布，天下猛將，善用兵，今諸將皆陛下故等夷，〔三〕乃令太子將，此屬莫肯為用，且布聞之，鼓行而西耳。〔四〕上雖疾，彊載輜車，臥而護之，〔五〕諸將不敢不盡力。上雖苦，彊為妻子計。』」於是呂澤夜見呂后。呂后承間為上泣而言，如四人意。上曰：「吾惟之，豎子固不足遣，〔六〕乃公自行耳。」〔七〕於是上自將而東，群臣居守，皆送至霸上。良疾，強起至曲郵，〔八〕見上曰：「臣宜從，疾甚。楚人剽疾，願上慎毋與楚爭鋒。」〔九〕因說上令太子為將軍監關中兵。上謂「子房雖疾，彊臥傅太子」。是時叔孫通已為太傅，良行少傅事。","sentenceOrder":99},
  {"id":"s_work_han_thu_51_100","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「太子嗣君，貴已極矣，雖更立功，位無加益矣。」","sentenceOrder":100},
  {"id":"s_work_han_thu_51_101","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「因空隙之時。」","sentenceOrder":101},
  {"id":"s_work_han_thu_51_102","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「夷，平也，言故時皆齊等。」","sentenceOrder":102},
  {"id":"s_work_han_thu_51_103","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「擊鼓而行，言無所畏。」","sentenceOrder":103},
  {"id":"s_work_han_thu_51_104","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「輜車，衣車也。護謂監領諸將。」","sentenceOrder":104},
  {"id":"s_work_han_thu_51_105","chapterId":"ch_work_han_thu_51","textTraditional":"〔六〕　師古曰：「惟，思也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_51_106","chapterId":"ch_work_han_thu_51","textTraditional":"〔七〕　師古曰：「乃公，汝父也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_51_107","chapterId":"ch_work_han_thu_51","textTraditional":"〔八〕　師古曰：「在新豐西，今俗謂之郵頭。」","sentenceOrder":107},
  {"id":"s_work_han_thu_51_108","chapterId":"ch_work_han_thu_51","textTraditional":"〔九〕　師古曰：「剽音匹妙反。」","sentenceOrder":108},
  {"id":"s_work_han_thu_51_109","chapterId":"ch_work_han_thu_51","textTraditional":"漢十二年，上從破布歸，疾益甚，愈欲易太子。良諫不聽，因疾不視事。叔孫太傅稱說引古，以死爭太子。上陽許之，猶欲易之。及宴，置酒，太子侍。四人者從太子，年皆八十有餘，須眉皓白，衣冠甚偉。〔一〕上怪，問曰：「何為者？」四人前對，各言其姓名。上乃驚曰：「吾求公，避逃我，今公何自從吾兒游乎？」四人曰：「陛下輕士善罵，臣等義不辱，故恐而亡匿。今聞太子仁孝，恭敬愛士，天下莫不延頸願為太子死者，故臣等來。」上曰：「煩公幸卒調護太子。」〔二〕","sentenceOrder":109},
  {"id":"s_work_han_thu_51_110","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「所以謂之四皓。」","sentenceOrder":110},
  {"id":"s_work_han_thu_51_111","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「調謂和平之，護謂保安之。」","sentenceOrder":111},
  {"id":"s_work_han_thu_51_112","chapterId":"ch_work_han_thu_51","textTraditional":"四人為壽已畢，趨去。上目送之，〔一〕召戚夫人指視曰：〔二〕「我欲易之，彼四人為之輔，羽翼已成，難動矣。呂氏真乃主矣。」〔三〕戚夫人泣涕，上曰：「為我楚舞，吾為若楚歌。」〔四〕歌曰：「鴻鵠高飛，一舉千里。〔五〕羽翼以就，橫絕四海。〔六〕橫絕四海，又可奈何！雖有矰繳，尚安所施！」〔七〕歌數闋，〔八〕戚夫人歔欷流涕，〔九〕上起去，罷酒。竟不易太子者，良本招此四人之力也。","sentenceOrder":112},
  {"id":"s_work_han_thu_51_113","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「以目瞻之訖其出也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_51_114","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「視讀曰示。」","sentenceOrder":114},
  {"id":"s_work_han_thu_51_115","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「乃，汝也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_51_116","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「若亦汝也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_51_117","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「鵠音胡督反。」","sentenceOrder":117},
  {"id":"s_work_han_thu_51_118","chapterId":"ch_work_han_thu_51","textTraditional":"〔六〕　師古曰：「就，成也。絕謂飛而直度也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_51_119","chapterId":"ch_work_han_thu_51","textTraditional":"〔七〕　師古曰：「繳，弋射也。其矢為矰。矰音增。繳音之若反。」","sentenceOrder":119},
  {"id":"s_work_han_thu_51_120","chapterId":"ch_work_han_thu_51","textTraditional":"〔八〕　師古曰：「闋，盡也。曲終為闋，音口穴反。」","sentenceOrder":120},
  {"id":"s_work_han_thu_51_121","chapterId":"ch_work_han_thu_51","textTraditional":"〔九〕　師古曰：「歔音虛，欷音稀，又音許氣反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_51_122","chapterId":"ch_work_han_thu_51","textTraditional":"良從上擊代，出奇計下馬邑，及立蕭相國，〔一〕所與從容言天下事甚眾，〔二〕非天下所以存亡，故不著。〔三〕良乃稱曰：「家世相韓，及韓滅，不愛萬金之資，為韓報仇彊秦，天下震動。今以三寸舌為帝者師，封萬戶，位列侯，此布衣之極，於良足矣。願棄人間事，欲從赤松子游耳。」〔四〕乃學道，欲輕舉。〔五〕高帝崩，呂后德良，乃彊食之，〔六〕曰：「人生一世〔間〕，如白駒之過隙，〔七〕何自苦如此！」良不得已，彊聽食。後六歲薨。諡曰文成侯。","sentenceOrder":122},
  {"id":"s_work_han_thu_51_123","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　服虔曰：「何時未為相國，良勸高祖立之。」","sentenceOrder":123},
  {"id":"s_work_han_thu_51_124","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「從音千容反。」","sentenceOrder":124},
  {"id":"s_work_han_thu_51_125","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「著謂書之於史。著音竹助反。」","sentenceOrder":125},
  {"id":"s_work_han_thu_51_126","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「赤松子，仙人號也，神農時為雨師，服水玉，教神農能入火自燒。至昆山上，常止西王母石室，隨風雨上下。炎帝少女追之，亦得仙俱去。」","sentenceOrder":126},
  {"id":"s_work_han_thu_51_127","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「道謂仙道。」","sentenceOrder":127},
  {"id":"s_work_han_thu_51_128","chapterId":"ch_work_han_thu_51","textTraditional":"〔六〕　師古曰：「食讀曰飤。」","sentenceOrder":128},
  {"id":"s_work_han_thu_51_129","chapterId":"ch_work_han_thu_51","textTraditional":"〔七〕　師古曰：「解在魏豹傳。」","sentenceOrder":129},
  {"id":"s_work_han_thu_51_130","chapterId":"ch_work_han_thu_51","textTraditional":"良始所見下邳圯上老父與書者，後十三歲從高帝過濟北，果得穀城山下黃石，取而寶祠之。及良死，并葬黃石。每上冢伏臘祠黃石。","sentenceOrder":130},
  {"id":"s_work_han_thu_51_131","chapterId":"ch_work_han_thu_51","textTraditional":"子不疑嗣侯。孝文三年坐不敬，國除。","sentenceOrder":131},
  {"id":"s_work_han_thu_51_132","chapterId":"ch_work_han_thu_51","textTraditional":"陳平，陽武戶牖鄉人也。〔一〕少時家貧，好讀書，治黃帝、老子之術。有田三十畝，與兄伯居。伯常耕田，縱平使游學。平為人長大美色，人或謂平：「貧何食而肥若是？」其嫂疾平之不親家生產，曰：「亦食糠覈耳。〔二〕有叔如此，不如無有！」伯聞之，逐其婦棄之。","sentenceOrder":132},
  {"id":"s_work_han_thu_51_133","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「陽武，縣名，屬陳留。戶牖者，其鄉名。」","sentenceOrder":133},
  {"id":"s_work_han_thu_51_134","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　孟康曰：「覈，麥糠中不破者也。」晉灼曰：「覈音紇。京師人謂麤屑為紇頭。」","sentenceOrder":134},
  {"id":"s_work_han_thu_51_135","chapterId":"ch_work_han_thu_51","textTraditional":"及平長，可取婦，富人莫與者，貧者平亦媿之。久之，戶牖富人張負有女孫，五嫁夫輒死，人莫敢取，平欲得之。邑中有大喪，平家貧侍喪，以先往後罷為助。張負既見之喪所，獨視偉平，〔一〕平亦以故後去。負隨平至其家，家乃負郭窮巷，〔二〕以席為門，然門外多長者車轍。張負歸，謂其子仲曰：「吾欲以女孫予陳平。」仲曰：「平貧不事事，〔三〕一縣中盡笑其所為，獨柰何予之女？」負曰：「固有美如陳平長貧者乎？」卒與女。為平貧，乃假貸幣以聘，〔四〕予酒肉之資以內婦。負戒其孫曰：「毋以貧故，事人不謹。事兄伯如事乃父，事嫂如事乃母。」〔五〕平既取張氏女，資用益饒，游道日廣。","sentenceOrder":135},
  {"id":"s_work_han_thu_51_136","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「視而悅其奇偉。」","sentenceOrder":136},
  {"id":"s_work_han_thu_51_137","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「負謂偝也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_51_138","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「不事產業之事。」","sentenceOrder":138},
  {"id":"s_work_han_thu_51_139","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「貸音土戴反。」","sentenceOrder":139},
  {"id":"s_work_han_thu_51_140","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「乃，汝也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_51_141","chapterId":"ch_work_han_thu_51","textTraditional":"里中社，平為宰，〔一〕分肉甚均。里父老曰：「善，陳孺子之為宰！」平曰：「嗟乎，使平得宰天下，亦如此肉矣！」","sentenceOrder":141},
  {"id":"s_work_han_thu_51_142","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「主切割肉也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_51_143","chapterId":"ch_work_han_thu_51","textTraditional":"陳涉起王，使周市略地，立魏咎為魏王，與秦軍相攻於臨濟。平已前謝兄伯，〔一〕從少年往事魏王咎，為太僕。說魏王，王不聽。人或讒之，平亡去。","sentenceOrder":143},
  {"id":"s_work_han_thu_51_144","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　服虔曰：「謝語其兄伯，往事魏也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_51_145","chapterId":"ch_work_han_thu_51","textTraditional":"項羽略地至河上，平往歸之，從入破秦，賜爵卿。〔一〕項羽之東王彭城也，漢王還定三秦而東。殷王反楚，項羽乃以平為信武君，將魏王客在楚者往擊，殷降而還。項王使項悍拜平為都尉，〔二〕賜金二十溢。居無何，〔三〕漢攻下殷。項王怒，將誅定殷者。平懼誅，乃封其金與印，使使歸項王，而平身間行杖劍亡。度河，船人見其美丈夫，獨行，疑其亡將，要下當有寶器金玉，目之，欲殺平。平心恐，乃解衣臝而佐刺船。〔四〕船人知其無有，乃止。","sentenceOrder":145},
  {"id":"s_work_han_thu_51_146","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　張晏曰：「禮秩如卿，不治事。」","sentenceOrder":146},
  {"id":"s_work_han_thu_51_147","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「悍音下旦反。」","sentenceOrder":147},
  {"id":"s_work_han_thu_51_148","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「無何，猶言無幾時。」","sentenceOrder":148},
  {"id":"s_work_han_thu_51_149","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「自露其形，示無所懷挾。」","sentenceOrder":149},
  {"id":"s_work_han_thu_51_150","chapterId":"ch_work_han_thu_51","textTraditional":"平遂至脩武降漢，因魏無知求見漢王，漢王召入。是時，萬石君石奮為中涓，受平謁。平等十人俱進，賜食。王曰：「罷，就舍矣。」平曰：「臣為事來，所言不可以過今日。」於是漢王與語而說之，〔一〕問曰：「子居楚何官？」平曰：「為都尉。」是日拜平為都尉，使參乘，典護軍。諸將盡讙，〔二〕曰：「大王一日得楚之亡卒，未知高下，而即與共載，使監護長者！」漢王聞之，愈益幸平，遂與東伐項王。至彭城，為楚所敗，引師而還。收散兵至滎陽，以平為亞將，屬韓王信，軍廣武。","sentenceOrder":150},
  {"id":"s_work_han_thu_51_151","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":151},
  {"id":"s_work_han_thu_51_152","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「讙囂而議也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_51_153","chapterId":"ch_work_han_thu_51","textTraditional":"絳、灌等或讒平曰：〔一〕「平雖美丈夫，如冠玉耳，其中未必有也。〔二〕聞平居家時盜其嫂；〔三〕事魏王不容，亡而歸楚；歸楚不中，又亡歸漢。〔四〕今大王尊官之，令護軍。臣聞平使諸將，金多者得善處，金少者得惡處。平，反覆亂臣也，願王察之。」漢王疑之，以讓無知，問曰：「有之乎？」無知曰：「有。」漢王曰：「公言其賢人何也？」對曰：「臣之所言者，能也；陛下所問者，行也。今有尾生、孝已之行，〔五〕而無益於勝敗之數，陛下何暇用之乎？今楚漢相距，臣進奇謀之士，顧其計誠足以利國家耳。〔六〕盜嫂受金又安足疑乎？」漢王召平而問曰：「吾聞先生事魏不遂，事楚而去，〔七〕今又從吾游，信者固多心乎？」平曰：「臣事魏王，魏王不能用臣說，故去事項王。項王不信人，其所任愛，非諸項即妻之昆弟，雖有奇士不能用。臣居楚聞漢王之能用人，故歸大王。臝身來，不受金無以為資。誠臣計畫有可采者，願大王用之；使無可用者，大王所賜金具在，請封輸官，得請骸骨。」漢王乃謝，厚賜，拜以為護軍中尉，盡護諸將。諸將乃不敢復言。","sentenceOrder":153},
  {"id":"s_work_han_thu_51_154","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「舊說云，絳，絳侯周勃也，灌，灌嬰也。而楚漢春秋高祖之臣別有絳灌，疑昧之文，不可據也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_51_155","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　孟康曰：「飾冠以玉，光好外見，中非所有也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_51_156","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「盜猶私也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_51_157","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「中音竹仲反。」","sentenceOrder":157},
  {"id":"s_work_han_thu_51_158","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　如淳曰：「孝已，高宗之子，有孝行。」師古曰：「尾生，古之信士，一說即微生高。」","sentenceOrder":158},
  {"id":"s_work_han_thu_51_159","chapterId":"ch_work_han_thu_51","textTraditional":"〔六〕　師古曰：「顧，念也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_51_160","chapterId":"ch_work_han_thu_51","textTraditional":"〔七〕　師古曰：「遂猶竟（也）。」","sentenceOrder":160},
  {"id":"s_work_han_thu_51_161","chapterId":"ch_work_han_thu_51","textTraditional":"其後，楚急擊，絕漢甬道，圍漢王於滎陽城。漢王患之，請割滎陽以西和。項王弗聽。漢王謂平曰：「天下紛紛，何時定乎？」平曰：「項王為人，恭敬愛人，士之廉節好禮者多歸之。至於行功賞爵邑，重之，〔一〕士亦以此不附。今大王嫚而少禮，士之廉節者不來；然大王能饒人以爵邑，士之頑頓耆利無恥者亦多歸漢。〔二〕誠各去兩短，集兩長，天下指麾即定矣。然大王資侮人，〔三〕不能得廉節之士。顧楚有可亂者，〔四〕彼項王骨鯁之臣亞父、鍾離眛、龍且、周殷之屬，〔五〕不過數人耳。大王能出捐數萬斤金，行反間，間其君臣，以疑其心，〔六〕項王為人意忌信讒，必內相誅。漢因舉兵而攻之，破楚必矣。」漢王以為然，乃出黃金四萬斤予平，恣所為，不問出入。","sentenceOrder":161},
  {"id":"s_work_han_thu_51_162","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「言愛惜之。」","sentenceOrder":162},
  {"id":"s_work_han_thu_51_163","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　如淳曰：「頑頓，謂無廉隅也。」師古曰：「頓讀曰鈍。耆讀曰嗜。」","sentenceOrder":163},
  {"id":"s_work_han_thu_51_164","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「資謂天性也。〈亻母〉，古侮字。」","sentenceOrder":164},
  {"id":"s_work_han_thu_51_165","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「顧，念也。」","sentenceOrder":165},
  {"id":"s_work_han_thu_51_166","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「眛音秣。且音子閭反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_51_167","chapterId":"ch_work_han_thu_51","textTraditional":"〔六〕　師古曰：「間音居莧反。」","sentenceOrder":167},
  {"id":"s_work_han_thu_51_168","chapterId":"ch_work_han_thu_51","textTraditional":"平既多以金縱反間於楚軍，宣言諸將鍾離眛等為項王將，功多矣，然終不得列地而王，欲與漢為一，以滅項氏，分王其地。項王果疑之，使使至漢。漢為太牢之具，舉進，見楚使，〔一〕即陽驚曰：「以為亞父使，乃項王使也！」復持去，以惡草具進楚使。〔二〕使歸，具以報項王，果大疑亞父。亞父欲急擊下滎陽城，項王不信，不肯聽亞父。亞父聞項王疑之，乃大怒曰：「天下事大定矣，君王自為之！願乞骸骨歸！」歸未至彭城，疽發背而死。〔三〕","sentenceOrder":168},
  {"id":"s_work_han_thu_51_169","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「舉鼎俎而來。」","sentenceOrder":169},
  {"id":"s_work_han_thu_51_170","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　服虔曰：「去肴肉，更以惡草之具。」","sentenceOrder":170},
  {"id":"s_work_han_thu_51_171","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「疽，峭瘡也，音千余反。」","sentenceOrder":171},
  {"id":"s_work_han_thu_51_172","chapterId":"ch_work_han_thu_51","textTraditional":"平乃夜出女子二千人滎陽東門，楚因擊之。平乃與漢王從城西門出去。遂入關，收聚兵而復東。","sentenceOrder":172},
  {"id":"s_work_han_thu_51_173","chapterId":"ch_work_han_thu_51","textTraditional":"明年，淮陰侯信破齊，自立為假齊王，使使言之漢王。漢王怒而罵，平躡漢王。〔一〕漢王寤，乃厚遇齊使，使張良往立信為齊王。於是封平以戶牖鄉。用其計策，卒滅楚。","sentenceOrder":173},
  {"id":"s_work_han_thu_51_174","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　孟康曰：「躡謂躡漢王足。」","sentenceOrder":174},
  {"id":"s_work_han_thu_51_175","chapterId":"ch_work_han_thu_51","textTraditional":"漢六年，人有上書告楚王韓信反。高帝問諸將，諸將曰：「亟發兵阬豎子耳。」〔一〕高帝默然。以問平，平固辭謝，曰：「諸將云何？」上具告之。平曰：「人之上書言信反，人有聞知者乎？」曰：「未有。」曰：「信知之乎？」曰：「弗知。」平曰：「陛下兵精孰與楚？」〔二〕上曰：「不能過也。」平曰：「陛下將用兵有能敵韓信者乎？」上曰：「莫及也。」平曰：「今兵不如楚精，將弗及，而舉兵擊之，是趣之戰也，〔三〕竊為陛下危之。」上曰：「為之柰何？」平曰：「古者天子巡狩，會諸侯。南方有雲夢，〔四〕陛下弟出偽游雲夢，〔五〕會諸侯於陳。陳，楚之西界，信聞天子以好出游，其勢必郊迎謁。〔六〕而陛下因禽之，特一力士之事耳。」高帝以為然，乃發使告諸侯會陳，「吾將南游雲夢」。上因隨以行。行至陳，楚王信果郊迎道中。高帝豫具武士，見信，即執縛之。語在信傳。","sentenceOrder":175},
  {"id":"s_work_han_thu_51_176","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「亟，急也，音居力反。」","sentenceOrder":176},
  {"id":"s_work_han_thu_51_177","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「與，如也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_51_178","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「趣讀曰促。」","sentenceOrder":178},
  {"id":"s_work_han_thu_51_179","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「楚澤名。夢音莫風反，又讀如本字。」","sentenceOrder":179},
  {"id":"s_work_han_thu_51_180","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「弟，但也，語聲急也。它皆類此。」","sentenceOrder":180},
  {"id":"s_work_han_thu_51_181","chapterId":"ch_work_han_thu_51","textTraditional":"〔六〕　師古曰：「出〔其〕郊遠迎謁也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_51_182","chapterId":"ch_work_han_thu_51","textTraditional":"遂會諸侯於陳。還至雒陽，與功臣剖符定封，封平為戶牖侯，世世勿絕。平辭曰：「此非臣之功也。」上曰：「吾用先生計謀，戰勝克敵，非功而何？」平曰：「非魏無知臣安得進？」上曰：「若子可謂不背本矣！」〔一〕乃復賞魏無知。","sentenceOrder":182},
  {"id":"s_work_han_thu_51_183","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「若，如也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_51_184","chapterId":"ch_work_han_thu_51","textTraditional":"其明年，平從擊韓王信於代。至平城，為匈奴圍，七日不得食。高帝用平奇計，使單于閼氏解，圍以得開。〔一〕高帝既出，其計祕，世莫得聞。高帝南過曲逆，〔二〕上其城，望室屋甚大，曰：「壯哉縣！吾行天下，獨見雒陽與是耳。」顧問御史：「曲逆戶口幾何？」對曰：「始秦時三萬餘戶，間者兵數起，多亡匿，今見五千餘戶。」於是（召）〔詔〕御史，更封平為曲逆侯，盡食之，除前所食戶牖。","sentenceOrder":184},
  {"id":"s_work_han_thu_51_185","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「閼氏音焉支。」","sentenceOrder":185},
  {"id":"s_work_han_thu_51_186","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　孟康曰：「中山蒲陰縣。」","sentenceOrder":186},
  {"id":"s_work_han_thu_51_187","chapterId":"ch_work_han_thu_51","textTraditional":"平自初從，至天下定後，常以護軍中尉從擊臧荼、陳豨、黥布。凡六出奇計，輒益邑封。奇計或頗祕，世莫得聞也。","sentenceOrder":187},
  {"id":"s_work_han_thu_51_188","chapterId":"ch_work_han_thu_51","textTraditional":"高帝從擊布軍還，病創，徐行至長安。燕王盧綰反，上使樊噲以相國將兵擊之。既行，人有短惡噲者。〔一〕高帝怒曰：「噲見吾病，乃幾我死也！」〔二〕用平計，召絳侯周勃受詔床下，曰：「〔陳〕平乘馳傳載勃代噲將，〔三〕平至軍中即斬噲頭！」二人既受詔，馳傳未至軍，行計曰：「樊噲，帝之故人，功多，〔四〕又呂后女弟呂須夫，有親且貴，帝以忿怒故欲斬之，即恐後悔。寧囚而致上，令上自誅之。」未至軍，為壇，以節召樊噲。噲受詔，即反接，〔五〕載檻車詣長安，而令周勃代將兵定燕。","sentenceOrder":188},
  {"id":"s_work_han_thu_51_189","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「陳其短失過惡於上，謂譖毀之。它皆類此。」","sentenceOrder":189},
  {"id":"s_work_han_thu_51_190","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　孟康曰：「幾幸我死也。幾音冀。」","sentenceOrder":190},
  {"id":"s_work_han_thu_51_191","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「傳音張戀反。」","sentenceOrder":191},
  {"id":"s_work_han_thu_51_192","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「行計，謂於道中且計也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_51_193","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「反縛兩手也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_51_194","chapterId":"ch_work_han_thu_51","textTraditional":"平行聞高帝崩，〔一〕平恐呂后及呂須怒，乃馳傳先去。逢使者詔平與灌嬰屯於滎陽。平受詔，立復馳至宮，哭殊悲，因奏事喪前。呂后哀之，曰：「君出休矣！」平畏讒之就，〔二〕因固請之，得宿衛中。太后乃以為郎中令，日傅教帝。〔三〕是後呂須讒乃不得行。樊噲至，即赦復爵邑。","sentenceOrder":194},
  {"id":"s_work_han_thu_51_195","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「未至京師，於道中聞高帝崩。」","sentenceOrder":195},
  {"id":"s_work_han_thu_51_196","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「就，成也，言畏讒毒己者得（其成）〔成其〕計。」","sentenceOrder":196},
  {"id":"s_work_han_thu_51_197","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　如淳曰：「傅相之。」","sentenceOrder":197},
  {"id":"s_work_han_thu_51_198","chapterId":"ch_work_han_thu_51","textTraditional":"惠帝六年，相國曹參薨，安國侯王陵為右丞相，平為左丞相。","sentenceOrder":198},
  {"id":"s_work_han_thu_51_199","chapterId":"ch_work_han_thu_51","textTraditional":"王陵，沛人也。始為縣豪，高祖微時兄事陵。及高祖起沛，入咸陽，陵亦聚黨數千人，居南陽，不肯從沛公。及漢王之還擊項籍，陵乃以兵屬漢。項羽取陵母置軍中，陵使至，則東鄉坐陵母，欲以招陵。〔一〕陵母既私送使者，泣曰：「願為老妾語陵，善事漢王。漢王長者，毋以老妾故持二心。妾以死送使者。」遂伏劍而死。項王怒，亨陵母。陵卒從漢王定天下。以善雍齒，雍齒，高祖之仇，陵又本無從漢之意，以故後封陵，為安國侯。","sentenceOrder":199},
  {"id":"s_work_han_thu_51_200","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":200},
  {"id":"s_work_han_thu_51_201","chapterId":"ch_work_han_thu_51","textTraditional":"陵為人少文任氣，好直言。為右丞相二歲，惠帝崩。高后欲立諸呂為王，問陵。陵曰：「高皇帝刑白馬而盟曰：『非劉氏而王者，天下共擊之。』今王呂氏，非約也。」太后不說。〔一〕問〔左〕丞相平及絳侯周勃等，皆曰：「高帝定天下，王子弟；今太后稱制，欲王昆弟諸呂，無所不可。」太后喜。罷朝，陵讓平、勃曰：「始與高帝唼血而盟，諸君不在邪？〔二〕今高帝崩，太后女主，欲王呂氏，諸君縱欲阿意背約，何面目見高帝於地下乎！」平曰：「於面折廷爭，臣不如君；〔三〕全社稷，定劉氏後，君亦不如臣。」陵無以應之。於是呂太后欲廢陵，乃陽遷陵為帝太傅，實奪之相權。陵怒，謝病免，杜門竟不朝請，〔四〕十年而薨。","sentenceOrder":201},
  {"id":"s_work_han_thu_51_202","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":202},
  {"id":"s_work_han_thu_51_203","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「唼，小歠也，音所甲反。」","sentenceOrder":203},
  {"id":"s_work_han_thu_51_204","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「廷爭，謂當朝廷而諫爭。」","sentenceOrder":204},
  {"id":"s_work_han_thu_51_205","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「杜，塞也，閉塞其門也。請音才性反。杜字本作〈度夂〉，音同。」","sentenceOrder":205},
  {"id":"s_work_han_thu_51_206","chapterId":"ch_work_han_thu_51","textTraditional":"陵之免，呂太后徙平為右丞相，以辟陽侯審食其為左丞相。〔一〕食其亦沛人也。漢王之敗彭城西，楚取太上皇、呂后為質，食其以舍人侍呂后。其後從破項籍為侯，幸於呂太后。及為相，不治，〔二〕監宮中，如郎中令，公卿百官皆因決事。","sentenceOrder":206},
  {"id":"s_work_han_thu_51_207","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「食其音異基。」","sentenceOrder":207},
  {"id":"s_work_han_thu_51_208","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　鄭氏曰：「不立治處，使止宮中也。」李奇曰：「不治丞相職事也。」師古曰：「李說是也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_51_209","chapterId":"ch_work_han_thu_51","textTraditional":"呂須常以平前為高帝謀執樊噲，數讒平曰：「為丞相不治事，日飲醇酒，戲婦人。」平聞，日益甚。呂太后聞之，私喜。面質呂須於平前，〔一〕曰：「鄙語曰『兒婦人口不可用』，顧君與我何如耳，無畏呂須之譖。」〔二〕","sentenceOrder":209},
  {"id":"s_work_han_thu_51_210","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「質，對也。」","sentenceOrder":210},
  {"id":"s_work_han_thu_51_211","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「顧，念也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_51_212","chapterId":"ch_work_han_thu_51","textTraditional":"呂太后多立諸呂為王，平偽聽之。〔一〕及呂太后崩，平與太尉勃合謀，卒誅諸呂，立文帝，平本謀也。審食其免相，文帝立，舉以為相。〔二〕","sentenceOrder":212},
  {"id":"s_work_han_thu_51_213","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「謂且順從之，不乖牾也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_51_214","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　如淳曰：「舉猶皆也。眾人之議皆以為勃、平功多矣。」師古曰：「言文帝以平、勃俱舊臣，有功，皆欲以為相。」","sentenceOrder":214},
  {"id":"s_work_han_thu_51_215","chapterId":"ch_work_han_thu_51","textTraditional":"太尉勃親以兵誅呂氏，功多；平欲讓勃位，乃謝病。文帝初立，怪平病，問之。平曰：「高帝時，勃功不如臣；及誅諸呂，臣功亦不如勃。願以相讓勃。」於是乃以太尉勃為右丞相，位第一；平徙為左丞相，位第二。賜平金千斤，益封三千戶。","sentenceOrder":215},
  {"id":"s_work_han_thu_51_216","chapterId":"ch_work_han_thu_51","textTraditional":"居頃之，上益明習國家事，朝而問右丞相勃曰：「天下一歲決獄幾何？」〔一〕勃謝不知。問「天下錢穀一歲出入幾何？」勃又謝不知。汗出洽背，〔二〕媿不能對。上亦問左丞相平。平曰：「（各）有主者。」上曰：「主者為誰乎？」平曰：「陛下即問決獄，責廷尉；問錢穀，責治粟內史。」上曰：「苟各有主者，而君所主何事也？」平謝曰：「主臣！〔三〕陛下不知其駑下，使待罪宰相。〔四〕宰相者，上佐天子理陰陽，順四時，下遂萬物之宜，〔五〕外填撫四夷諸侯，內親附百姓，使卿大夫各得任其職也。」上稱善。勃大慚，出而讓平曰：「君獨不素教我乎！」平笑曰：「君居其位，獨不知其任邪？且陛下即問長安盜賊數，又欲彊對邪？」於是絳侯自知其能弗如平遠矣。居頃之，勃謝（病請）免相，而平顓為丞相。〔六〕","sentenceOrder":216},
  {"id":"s_work_han_thu_51_217","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「臨朝問也。幾音居豈反。」","sentenceOrder":217},
  {"id":"s_work_han_thu_51_218","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「洽，霑也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_51_219","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　文穎曰：「惶恐之辭也，猶今言死罪也。」孟康曰：「主臣，主群臣也，若今言人主。」晉灼曰：「主，擊也。臣，服也。言其擊服，惶恐之辭。」師古曰：「文、晉二說是也。」","sentenceOrder":219},
  {"id":"s_work_han_thu_51_220","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「駑，凡馬之稱，非駿者也，故以自喻。駑音奴。」","sentenceOrder":220},
  {"id":"s_work_han_thu_51_221","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「遂，申也。」","sentenceOrder":221},
  {"id":"s_work_han_thu_51_222","chapterId":"ch_work_han_thu_51","textTraditional":"〔六〕　師古曰：「顓與專同。」","sentenceOrder":222},
  {"id":"s_work_han_thu_51_223","chapterId":"ch_work_han_thu_51","textTraditional":"孝文二年，平薨，諡曰獻侯。傳子至曾孫何，坐略人妻棄（主）〔市〕。王陵亦至玄孫，坐酎金國除。辟陽侯食其免後三歲而為淮南王所殺，文帝令其子平嗣侯。淄川王反，辟陽近淄川，平降之，國除。","sentenceOrder":223},
  {"id":"s_work_han_thu_51_224","chapterId":"ch_work_han_thu_51","textTraditional":"始平曰：「我多陰謀，道家之所禁。〔一〕吾世即廢，亦已矣，終不能復起，以吾多陰禍也。」其後曾孫陳掌以衛氏親戚貴，〔二〕願得續封，然終不得也。","sentenceOrder":224},
  {"id":"s_work_han_thu_51_225","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「此平謂陳平。」","sentenceOrder":225},
  {"id":"s_work_han_thu_51_226","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「掌妻，衛子夫之姊。」","sentenceOrder":226},
  {"id":"s_work_han_thu_51_227","chapterId":"ch_work_han_thu_51","textTraditional":"周勃，沛人。其先卷人也，〔一〕徙沛。勃以織薄曲為生，〔二〕常以吹簫給喪事，〔三〕材官引強。〔四〕","sentenceOrder":227},
  {"id":"s_work_han_thu_51_228","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「卷，縣名也，地理志屬河南，音丘權反。其下亦同。」","sentenceOrder":228},
  {"id":"s_work_han_thu_51_229","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　蘇林曰：「薄一名曲。月令曰『具曲植』。」師古曰：「許慎云葦薄為曲也。」","sentenceOrder":229},
  {"id":"s_work_han_thu_51_230","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「吹簫以樂喪賓，若樂人也。」","sentenceOrder":230},
  {"id":"s_work_han_thu_51_231","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　服虔曰：「能引強弓弩官也。」孟康曰：「如今挽強司馬也。」師古曰：「強音其兩反。」","sentenceOrder":231},
  {"id":"s_work_han_thu_51_232","chapterId":"ch_work_han_thu_51","textTraditional":"高祖為沛公初起，勃以中涓從攻胡陵，下方與。〔一〕方與反，與戰，卻敵。攻豐。擊秦軍碭東。還軍留及蕭。復攻碭，破之。下下邑，先登。賜爵五大夫。攻（蘭）〔蒙〕、虞，取之。擊章邯車騎殿。〔二〕略定魏地。攻轅戚、東緍，以往至栗，〔三〕取之。攻齧桑，先登。擊秦軍阿下，破之。追至濮陽，下蘄城。攻都關、定陶，襲取宛朐，得單父令。〔四〕夜襲取臨濟，攻壽張，以前至卷，破李由雍丘下。攻開封，先至城下為多。〔五〕後章邯破項梁，沛公與項羽引兵東如碭。自初起沛還至碭，一歲二月。楚懷王封沛公號武安侯，為碭郡長。沛公拜勃為襄賁令。〔六〕從沛公定魏地，攻東郡尉於成武，破之。攻長社，先登。攻潁陽、緱氏，絕河津。擊趙賁軍尸北。〔七〕南攻南陽守齮，破武關、嶢關。攻秦軍於藍田。至咸陽，滅秦。","sentenceOrder":232},
  {"id":"s_work_han_thu_51_233","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「音房豫。」","sentenceOrder":233},
  {"id":"s_work_han_thu_51_234","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「殿之言填也，謂鎮軍後以扞敵。勃擊破章邯之殿兵也。殿音丁見反。」","sentenceOrder":234},
  {"id":"s_work_han_thu_51_235","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「緍音昏。」","sentenceOrder":235},
  {"id":"s_work_han_thu_51_236","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「音善甫。」","sentenceOrder":236},
  {"id":"s_work_han_thu_51_237","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　文穎曰：「勃士卒至者多也。」如淳曰：「周禮『戰功曰多』。」師古曰：「多謂功多也。」","sentenceOrder":237},
  {"id":"s_work_han_thu_51_238","chapterId":"ch_work_han_thu_51","textTraditional":"〔六〕　師古曰：「賁音肥。」","sentenceOrder":238},
  {"id":"s_work_han_thu_51_239","chapterId":"ch_work_han_thu_51","textTraditional":"〔七〕　師古曰：「賁音奔。尸即尸鄉。」","sentenceOrder":239},
  {"id":"s_work_han_thu_51_240","chapterId":"ch_work_han_thu_51","textTraditional":"項羽至，以沛公為漢王。漢王賜勃爵為威武侯。從入漢中，拜為將軍。還定三秦，賜食邑懷德。攻槐里、好畤，最。〔一〕北擊趙賁、內史保於咸陽，最。北救漆。〔二〕擊章平、姚卬軍。西定汧〔三〕還下郿、頻陽。〔四〕圍章邯廢丘，破之。西擊益已軍，破之〔五〕。攻上邽。〔六〕東守嶢關。擊項籍。攻曲遇，最。〔七〕還守敖倉，追籍。籍已死，因東定楚地泗水、東海郡，凡得二十二縣。還守雒陽、櫟陽，賜與潁陰侯共食鍾離。以將軍從高祖擊燕王臧荼，破之易下。所將卒當馳道為多。〔八〕賜爵列侯，剖符世世不絕。食絳八千二百八十戶。","sentenceOrder":240},
  {"id":"s_work_han_thu_51_241","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　如淳曰：「於將率之中功為最也。」","sentenceOrder":241},
  {"id":"s_work_han_thu_51_242","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「漆，扶風縣。」","sentenceOrder":242},
  {"id":"s_work_han_thu_51_243","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「汧亦扶風縣，音口肩反。」","sentenceOrder":243},
  {"id":"s_work_han_thu_51_244","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「郿即岐州郿縣也。頻陽在櫟陽東北。郿音媚。」","sentenceOrder":244},
  {"id":"s_work_han_thu_51_245","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　如淳曰：「章邯將也。」","sentenceOrder":245},
  {"id":"s_work_han_thu_51_246","chapterId":"ch_work_han_thu_51","textTraditional":"〔六〕　師古曰：「邽音圭。」","sentenceOrder":246},
  {"id":"s_work_han_thu_51_247","chapterId":"ch_work_han_thu_51","textTraditional":"〔七〕　師古曰：「曲音丘禹反。遇音顒。」","sentenceOrder":247},
  {"id":"s_work_han_thu_51_248","chapterId":"ch_work_han_thu_51","textTraditional":"〔八〕　師古曰：「當高祖所行之前。」","sentenceOrder":248},
  {"id":"s_work_han_thu_51_249","chapterId":"ch_work_han_thu_51","textTraditional":"以將軍從高帝擊韓王信於代，降下霍人。以前至武泉，〔一〕擊胡騎，破之武泉北。轉攻韓信軍銅鞮，破之。還，降太原六城。擊韓信胡騎晉陽下，破之，下晉陽。後擊韓信軍於硰石，〔二〕破之，追北八十里。還攻樓煩三城，因擊胡騎平城下，所將卒當馳道為多。勃遷為太尉。","sentenceOrder":249},
  {"id":"s_work_han_thu_51_250","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　孟康曰：「縣屬雲中也。」","sentenceOrder":250},
  {"id":"s_work_han_thu_51_251","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　應劭曰：「硰音沙。」孟康曰：「地名也。」齊恭曰：「硰音赤坐反。」師古曰：「齊音是也。」","sentenceOrder":251},
  {"id":"s_work_han_thu_51_252","chapterId":"ch_work_han_thu_51","textTraditional":"〔擊〕陳豨，屠馬邑。所將卒斬豨將軍乘馬降。〔一〕轉擊韓信、陳豨、趙利軍於樓煩，破之。得豨將宋最、鴈門守圂。〔二〕因轉攻得雲中守遫、丞相箕肄、將軍博。〔三〕定鴈門郡十七縣，雲中郡十二縣。因復擊豨靈丘，破之，斬豨丞相程縱、將軍陳武、都尉高肄。定代郡九縣。","sentenceOrder":252},
  {"id":"s_work_han_thu_51_253","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「姓乘馬，名降也。乘音食孕反。」","sentenceOrder":253},
  {"id":"s_work_han_thu_51_254","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「圂者，鴈門守之名，音下頓反。」","sentenceOrder":254},
  {"id":"s_work_han_thu_51_255","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「遫，古速字也。肄音弋二反。博者，亦豨將之名也。」","sentenceOrder":255},
  {"id":"s_work_han_thu_51_256","chapterId":"ch_work_han_thu_51","textTraditional":"燕王盧綰反，勃以相國代樊噲將，擊下薊，〔一〕得綰大將抵、丞相偃、守陘、〔二〕太尉弱、御史大夫施屠渾都。〔三〕破綰軍上蘭，後擊綰軍沮陽。〔四〕追至長城，定上谷十二縣，右北平十六縣，遼東二十九縣，漁陽二十二縣。最從高帝得相國一人，〔五〕丞相二人，將軍、二千石各三人；別破軍二，下城三，定郡五，縣七十九，得丞相、大將各一人。","sentenceOrder":256},
  {"id":"s_work_han_thu_51_257","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「即幽州薊縣也，音計。」","sentenceOrder":257},
  {"id":"s_work_han_thu_51_258","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　張晏曰：「盧綰郡守，陘其名也。」師古曰：「陘音刑。」","sentenceOrder":258},
  {"id":"s_work_han_thu_51_259","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「姓施屠，名渾都。渾音胡昆反。」","sentenceOrder":259},
  {"id":"s_work_han_thu_51_260","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　服虔曰：「沮音阻。」師古曰：「縣名，屬上谷。」","sentenceOrder":260},
  {"id":"s_work_han_thu_51_261","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「最者，凡也。總言其攻戰克獲之數。」","sentenceOrder":261},
  {"id":"s_work_han_thu_51_262","chapterId":"ch_work_han_thu_51","textTraditional":"勃為人木強敦厚，〔一〕高帝以為可屬大事。〔二〕勃不好文學，每召諸生說士，東鄉坐責之：〔三〕「趣為我語。」〔四〕其椎少文如此。〔五〕","sentenceOrder":262},
  {"id":"s_work_han_thu_51_263","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「木謂質樸。強音其兩反。」","sentenceOrder":263},
  {"id":"s_work_han_thu_51_264","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「屬，委也，音之欲反。」","sentenceOrder":264},
  {"id":"s_work_han_thu_51_265","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　如淳曰：「勃自東鄉，責諸生說士，不以賓主之禮也。」師古曰：「鄉讀曰嚮。」","sentenceOrder":265},
  {"id":"s_work_han_thu_51_266","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　蘇林曰：「音趣舍。」臣瓚曰：「令直言勿稱經書也。」師古曰：「二說皆非也。趣讀曰促。謂令速言也。」","sentenceOrder":266},
  {"id":"s_work_han_thu_51_267","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　服虔曰：「謂訥鈍也。」應劭曰：「今俗名拙語為椎儲。」師古曰：「椎謂樸鈍如椎也。音直推反。」","sentenceOrder":267},
  {"id":"s_work_han_thu_51_268","chapterId":"ch_work_han_thu_51","textTraditional":"勃既定燕而歸，高帝已崩矣，以列侯事惠帝。惠帝六年，置太尉官，以勃為太尉。十年，高后崩。呂祿以趙王為漢上將軍，呂產以呂王為相國，秉權，欲危劉氏。勃與丞相平、朱虛侯章共誅諸呂。語在高后紀。","sentenceOrder":268},
  {"id":"s_work_han_thu_51_269","chapterId":"ch_work_han_thu_51","textTraditional":"於是陰謀（乃）〔以〕為「少帝及濟川、淮陽、恆山王皆非惠帝子，呂太后以計詐名它人子，殺其母，養之後宮，令孝惠子之，立以為後，用彊呂氏。今已滅諸呂，少帝即長用事，吾屬類無矣，〔一〕不如視諸侯賢者立之。」遂迎立代王，是為孝文皇帝。","sentenceOrder":269},
  {"id":"s_work_han_thu_51_270","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「云被誅滅無遺種。」","sentenceOrder":270},
  {"id":"s_work_han_thu_51_271","chapterId":"ch_work_han_thu_51","textTraditional":"東牟侯興居，朱虛侯章弟也，曰：「誅諸呂，臣無功，請得除宮。」乃與太僕汝陰滕公入宮。滕公前謂少帝曰：「足下非劉氏，不當立。」乃顧麾左右執戟，皆仆兵罷。〔一〕有數人不肯去，（官）〔宦〕者令張釋諭告，亦去。〔二〕滕公召乘輿車載少帝出。少帝曰：「欲持我安之乎？」〔三〕滕公曰：「就舍少府。」乃奉天子法駕，迎皇帝代邸，報曰：「宮謹除。」皇帝入未央宮，有謁者十人持戟衛端門，〔四〕曰：「天子在也，足下何為者？」不得入。太尉往喻，乃引兵去，皇帝遂入。是夜，有司分部誅濟川、淮陽、常山王及少帝於邸。","sentenceOrder":271},
  {"id":"s_work_han_thu_51_272","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「仆，頓也，音赴。」","sentenceOrder":272},
  {"id":"s_work_han_thu_51_273","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「荊燕吳傳云張擇，今此作釋，參錯不同，未知孰是也？」","sentenceOrder":273},
  {"id":"s_work_han_thu_51_274","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「言往何所也。」","sentenceOrder":274},
  {"id":"s_work_han_thu_51_275","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「端門，殿之正門。」","sentenceOrder":275},
  {"id":"s_work_han_thu_51_276","chapterId":"ch_work_han_thu_51","textTraditional":"文帝即位，以勃為右丞相，賜金五千斤，邑萬戶。居十餘月，人或說勃曰：「君既誅諸呂，立代王，威震天下，而君受厚賞處尊位以厭之，則禍及身矣。」〔一〕勃懼，亦自危，乃謝請歸相印。上許之。歲餘，陳丞相平卒，上復用勃為（丞）相。十餘月，上曰：「前日吾詔列侯就國，或頗未能行，丞相朕所重，其為朕率列侯之國。」乃免相就國。","sentenceOrder":276},
  {"id":"s_work_han_thu_51_277","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「厭謂當之也。言既有大功，又受厚賞而居尊位，以久當之〔不去〕，即禍及矣。厭音一涉反，又音烏狎反。」","sentenceOrder":277},
  {"id":"s_work_han_thu_51_278","chapterId":"ch_work_han_thu_51","textTraditional":"歲餘，每河東守尉行縣至絳，絳侯勃自畏恐誅，常被甲，令家人持兵以見。其後人有上書告勃欲反，下廷尉，逮捕勃治之。勃恐，不知置辭。〔一〕吏稍侵辱之。勃以千金與獄吏，獄吏乃書牘背示之，〔二〕曰「以公主為證」。公主者，孝文帝女也，勃太子勝之尚之，〔三〕故獄吏教引為證。初，勃之益封，盡以予薄昭。及繫急，薄昭為言薄太后，太后亦以為無反事。文帝朝，太后以冒絮提文帝，〔四〕曰：「絳侯綰皇帝璽，將兵於北軍，〔五〕不以此時反，今居一小縣，顧欲反邪！」〔六〕文帝既見勃獄辭，乃謝曰：「吏方驗而出之。」於是使使持節赦勃，復爵邑。勃既出，曰：「吾嘗將百萬軍，安知獄吏之貴也！」","sentenceOrder":278},
  {"id":"s_work_han_thu_51_279","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「置，立也。辭，對獄之辭。」","sentenceOrder":279},
  {"id":"s_work_han_thu_51_280","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　李奇曰：「吏所執簿也。」師古曰：「牘，木簡，以書辭也，音讀。」","sentenceOrder":280},
  {"id":"s_work_han_thu_51_281","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「尚，配也，解在張耳傳。」","sentenceOrder":281},
  {"id":"s_work_han_thu_51_282","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　應劭曰：「陌頟絮也。」晉灼曰：「巴蜀異志謂頭上巾為冒絮。」師古曰：「冒，覆也，老人所以覆其頭。提，擲也。提音徒計反。」","sentenceOrder":282},
  {"id":"s_work_han_thu_51_283","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　應劭曰：「言勃誅諸呂，廢少帝，手貫國璽時尚不反，況今更有異乎？」師古曰：「綰謂引結其組，音烏版反。」","sentenceOrder":283},
  {"id":"s_work_han_thu_51_284","chapterId":"ch_work_han_thu_51","textTraditional":"〔六〕　師古曰：「顧猶倒也。」","sentenceOrder":284},
  {"id":"s_work_han_thu_51_285","chapterId":"ch_work_han_thu_51","textTraditional":"勃復就國，孝文十一年薨，諡曰武侯。子勝之嗣，尚公主不相中，〔一〕坐殺人，死，國絕。一年，〔文帝乃擇勃子賢者河內太守〕（弟）亞夫復為侯。","sentenceOrder":285},
  {"id":"s_work_han_thu_51_286","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　如淳曰：「猶言不相合當也。」師古曰：「意不相可也。中音竹仲反。」","sentenceOrder":286},
  {"id":"s_work_han_thu_51_287","chapterId":"ch_work_han_thu_51","textTraditional":"亞夫為河內守時，許負相之：〔一〕「君後三歲而侯。侯八歲，為將相，持國秉，〔二〕貴重矣，於人臣無二。後九年而餓死。」亞夫笑曰：「臣之兄以代父侯矣，有如卒，子當代，我何說侯乎？然既已貴如負言，又何說餓死？指視我。」〔三〕負指其口曰：「從理入口，此餓死法也。」〔四〕居三歲，兄絳侯勝之有罪，文帝擇勃子賢者，皆推亞夫，乃封為條侯。〔五〕","sentenceOrder":287},
  {"id":"s_work_han_thu_51_288","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　應劭曰：「許負，河內溫人，老嫗也。」","sentenceOrder":288},
  {"id":"s_work_han_thu_51_289","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「秉音彼命反。」","sentenceOrder":289},
  {"id":"s_work_han_thu_51_290","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「視讀曰示。」","sentenceOrder":290},
  {"id":"s_work_han_thu_51_291","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「從，豎也，音子容反。」","sentenceOrder":291},
  {"id":"s_work_han_thu_51_292","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「縣在勃海。地理志作蓨字，其音同耳。」","sentenceOrder":292},
  {"id":"s_work_han_thu_51_293","chapterId":"ch_work_han_thu_51","textTraditional":"文帝後六年，匈奴大入邊。以宗正劉禮為將軍軍霸上，祝茲侯徐厲為將軍軍棘門，以河內守亞夫為將軍軍細柳，以備胡。上自勞軍，至霸上及棘門軍，直馳入，將以下騎出入送迎。已而之細柳軍，軍士吏被甲，銳兵刃，彀弓弩，持滿。〔一〕天子先驅至，不得入。〔二〕先驅曰：「天子且至！」軍門都尉曰：「軍中聞將軍之令，不聞天子之詔。」有頃，上至，又不得入。於是上使使持節詔將軍曰：「吾欲勞軍。」亞夫乃傳言開壁門。壁門士請車騎曰：「將軍約，軍中不得驅馳。」於是天子乃按轡徐行。至中營，將軍亞夫揖，曰：「介冑之士不拜，請以軍禮見。」〔三〕天子為動，改容式車。〔四〕使人稱謝：〔五〕「皇帝敬勞將軍。」成禮而去。既出軍門，群臣皆驚。文帝曰：「嗟乎，此真將軍矣！鄉者霸上、棘門如兒戲耳，〔六〕其將固可襲而虜也。至於亞夫，可得而犯邪！」稱善者久之。月餘，三軍皆罷。乃拜亞夫為中尉。","sentenceOrder":293},
  {"id":"s_work_han_thu_51_294","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「彀，張也，音遘。」","sentenceOrder":294},
  {"id":"s_work_han_thu_51_295","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「先驅，導駕者也，若今之武候隊矣。」","sentenceOrder":295},
  {"id":"s_work_han_thu_51_296","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　應劭曰：「禮，介者不拜。」","sentenceOrder":296},
  {"id":"s_work_han_thu_51_297","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「古者立乘，凡言式車者，謂俛身撫式，以禮敬人。式，車前橫木也。」","sentenceOrder":297},
  {"id":"s_work_han_thu_51_298","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「謝，告也。」","sentenceOrder":298},
  {"id":"s_work_han_thu_51_299","chapterId":"ch_work_han_thu_51","textTraditional":"〔六〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":299},
  {"id":"s_work_han_thu_51_300","chapterId":"ch_work_han_thu_51","textTraditional":"文帝且崩時，戒太子曰：「即有緩急，周亞夫真可任將兵。」文帝崩，亞夫為車騎將軍。","sentenceOrder":300},
  {"id":"s_work_han_thu_51_301","chapterId":"ch_work_han_thu_51","textTraditional":"孝景帝三年，吳楚反。亞夫以中尉為太尉，東擊吳楚。因自請上曰：「楚兵剽輕，難與爭鋒。〔一〕願以梁委之，絕其食道，乃可制也。」上許之。〔二〕","sentenceOrder":301},
  {"id":"s_work_han_thu_51_302","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「剽音匹妙反。」","sentenceOrder":302},
  {"id":"s_work_han_thu_51_303","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「吳王傳云亞夫至淮陽，問鄧都尉，為畫此計，亞夫乃從之。今此云自請而後行。二傳不同，未知孰是。」","sentenceOrder":303},
  {"id":"s_work_han_thu_51_304","chapterId":"ch_work_han_thu_51","textTraditional":"亞夫既發，至霸上，趙涉遮說亞夫曰：「將軍東誅吳楚，勝則宗廟安，不勝則天下危，能用臣之言乎？」亞夫下車，禮而問之。涉曰：「吳王素富，懷輯死士久矣。〔一〕此知將軍且行，必置間人於殽黽阨陿之間。且兵事上神密，將軍何不從此右去，走藍田，〔二〕出武關，抵雒陽，〔三〕間不過差一二日，〔四〕直入武庫，擊鳴鼓。諸侯聞之，以為將軍從天而下也。」〔五〕太尉如其計。至雒陽，使吏搜殽黽間，果得吳伏兵。乃請涉為護軍。","sentenceOrder":304},
  {"id":"s_work_han_thu_51_305","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「輯與集同。」","sentenceOrder":305},
  {"id":"s_work_han_thu_51_306","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「右謂少西去也。走音奏。」","sentenceOrder":306},
  {"id":"s_work_han_thu_51_307","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「抵，至也。」","sentenceOrder":307},
  {"id":"s_work_han_thu_51_308","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「謂右去行遲止一二日也。」","sentenceOrder":308},
  {"id":"s_work_han_thu_51_309","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「不意其猝至。」","sentenceOrder":309},
  {"id":"s_work_han_thu_51_310","chapterId":"ch_work_han_thu_51","textTraditional":"亞夫至，會兵滎陽。〔一〕吳方攻梁，梁急，請救。亞夫引兵東北走昌邑，〔二〕深壁而守。梁王使使請亞夫，亞夫守便宜，不往。梁上書言景帝，景帝詔使救梁。亞夫不奉詔，堅壁不出，而使輕騎兵弓高侯等絕吳楚兵後食道。吳楚兵乏糧，飢，欲退，數挑戰，終不出。夜，軍中驚，內相攻擊擾亂，至於帳下。亞夫堅臥不起。頃之，復定。吳奔壁東南陬，〔三〕亞夫使備西北。已而其精兵果奔西北，不得入。吳楚既餓，乃引而去。亞夫出精兵追擊，大破吳王濞。吳王濞棄其軍，與壯士數千人亡走，保於江南丹徒。漢兵因乘勝，遂盡虜之，降其縣，購吳王千金。月餘，越人斬吳王頭以告。凡相守攻三月，而吳楚破平。於是諸將乃以太尉計謀為是。由此梁孝王與亞夫有隙。","sentenceOrder":310},
  {"id":"s_work_han_thu_51_311","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「會，集也。」","sentenceOrder":311},
  {"id":"s_work_han_thu_51_312","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「走音奏。」","sentenceOrder":312},
  {"id":"s_work_han_thu_51_313","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　如淳曰：「陬，隅也。」師古曰：「音子侯反，又音鄒。」","sentenceOrder":313},
  {"id":"s_work_han_thu_51_314","chapterId":"ch_work_han_thu_51","textTraditional":"歸，復置太尉官。五歲，遷為丞相，景帝甚重之。上廢栗太子，亞夫固爭之，不（待）〔得〕。上由此疏之。而梁孝王每朝，常與太后言亞夫之短。","sentenceOrder":314},
  {"id":"s_work_han_thu_51_315","chapterId":"ch_work_han_thu_51","textTraditional":"竇太后曰：「皇后兄王信可侯也。」上讓曰：「始南皮及章武先帝不侯，〔一〕及臣即位，乃侯之，信未得封也。」竇太后曰：「人生各以時行耳。〔二〕竇長君在時，竟不得封侯，死後，乃其子彭祖顧得侯。〔三〕吾甚恨之。帝趣侯信也！」〔四〕上曰：「請得與丞相計之。」亞夫曰：「高帝約『非劉氏不得王，非有功不得侯。不如約，天下共擊之』。今信雖皇后兄，無功，侯之，非約也。」上默然而沮。〔五〕","sentenceOrder":315},
  {"id":"s_work_han_thu_51_316","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「南皮竇彭祖，太后弟長君之子。章武，太后母弟廣國。」","sentenceOrder":316},
  {"id":"s_work_han_thu_51_317","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「言富貴當及己身也。」","sentenceOrder":317},
  {"id":"s_work_han_thu_51_318","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「顧，反也。」","sentenceOrder":318},
  {"id":"s_work_han_thu_51_319","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「趣讀曰促。」","sentenceOrder":319},
  {"id":"s_work_han_thu_51_320","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「沮者，止壞之意也，音才與反。」","sentenceOrder":320},
  {"id":"s_work_han_thu_51_321","chapterId":"ch_work_han_thu_51","textTraditional":"其後匈奴王徐盧等五人降漢，〔一〕上欲侯之以勸後。亞夫曰：「彼背其主降陛下，陛下侯之，即何以責人臣不守節者乎？」上曰：「丞相議不可用。」乃悉封徐盧等為列侯。亞夫因謝病免相。","sentenceOrder":321},
  {"id":"s_work_han_thu_51_322","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「功臣表云唯徐盧。」","sentenceOrder":322},
  {"id":"s_work_han_thu_51_323","chapterId":"ch_work_han_thu_51","textTraditional":"頃之，上居禁中，召亞夫賜食。獨置大胾，〔一〕無切肉，又不置箸。亞夫心不平，顧謂尚席取箸。〔二〕上視而笑曰：「此非不足君所乎？」〔三〕亞夫免冠謝上。上曰：「起。」亞夫因趨出。上目送之，曰：「此鞅鞅，非少主臣也！」","sentenceOrder":323},
  {"id":"s_work_han_thu_51_324","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　師古曰：「胾，大臠，音側吏反。」","sentenceOrder":324},
  {"id":"s_work_han_thu_51_325","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　應劭曰：「尚席，主席者也。」","sentenceOrder":325},
  {"id":"s_work_han_thu_51_326","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　孟康曰：「設胾無箸者，此非不足滿於君所乎？嫌恨之也。」如淳曰：「非故不足君之食具，偶失之也。」師古曰：「孟說近之。帝言賜君食而不設箸，此由我意於君有不足乎？」","sentenceOrder":326},
  {"id":"s_work_han_thu_51_327","chapterId":"ch_work_han_thu_51","textTraditional":"居無何，亞夫子為父買工官尚方甲楯五百被可以葬者。〔一〕取庸苦之，不與錢。〔二〕庸知其盜買縣官器，怨而上變告子，事連汙亞夫。書既聞，上下吏。吏簿責亞夫，〔三〕亞夫不對。上罵之曰：「吾不用也。」〔四〕召詣廷尉。廷尉責問曰：「君侯欲反何？」亞夫曰：「臣所買器，乃葬器也，何謂反乎？」吏曰：「君縱不欲反地上，即欲反地下耳。」吏侵之益急。初，吏捕亞夫，亞夫欲自殺，其夫人止之，以故不得死，遂入廷尉，因不食五日，歐血而死。國絕。","sentenceOrder":327},
  {"id":"s_work_han_thu_51_328","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　如淳曰：「工官，官名也。」張晏曰：「被，具也。五百具甲楯也。」師古曰：「被音皮義反。」","sentenceOrder":328},
  {"id":"s_work_han_thu_51_329","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「庸謂賃也。苦謂極苦使也。」","sentenceOrder":329},
  {"id":"s_work_han_thu_51_330","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　如淳曰：「簿音主簿之簿，簿問其辭情。」師古曰：「簿問者，書之於簿，一一問之也。」","sentenceOrder":330},
  {"id":"s_work_han_thu_51_331","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　孟康曰：「言不用汝對，欲殺之也。」如淳曰：「恐獄吏畏其復用事，不敢折辱也。」師古曰：「孟說是也。一云，帝責此吏云不勝其任，吾不用汝，故召亞夫令詣廷尉也。」","sentenceOrder":331},
  {"id":"s_work_han_thu_51_332","chapterId":"ch_work_han_thu_51","textTraditional":"一歲，上乃更封絳侯勃它子堅為平曲侯，續絳侯後。傳子建德，為太子太傅，坐酎金免官。後有罪，國除。","sentenceOrder":332},
  {"id":"s_work_han_thu_51_333","chapterId":"ch_work_han_thu_51","textTraditional":"亞夫果餓死。死後，上乃封王信為蓋侯。至平帝元始二年，繼絕世，復封勃玄孫之子恭為絳侯，千戶。","sentenceOrder":333},
  {"id":"s_work_han_thu_51_334","chapterId":"ch_work_han_thu_51","textTraditional":"贊曰：聞張良之智勇，以為其貌魁梧奇偉，〔一〕反若婦人女子。故孔子稱「以貌取人，失之子羽」。〔二〕學者多疑於鬼神，〔三〕如良受書老父，亦異矣。高祖數離困阨，良常有力，〔四〕豈可謂非天乎！陳平之志，見於社下，傾側擾攘楚、魏之間，卒歸於漢，而為謀臣。及呂后時，事多故矣，〔五〕平竟自免，以智終。王陵廷爭，杜門自絕，亦各其志也。周勃為布衣時，鄙樸庸人，至登輔佐，匡國家難，誅諸呂，立孝文，為漢伊周，〔六〕何其盛也！始呂后問宰相，高祖曰：「陳平智有餘，王陵少戇，可以佐之；〔七〕安劉氏者必勃也。」又問其次，云「過此以後，非乃所及」。〔八〕終皆如言，聖矣夫！","sentenceOrder":334},
  {"id":"s_work_han_thu_51_335","chapterId":"ch_work_han_thu_51","textTraditional":"〔一〕　應劭曰：「魁梧，丘虛壯大之意也。」蘇林曰：「梧音悟。」師古曰：「魁，大貌也。梧者，言其可驚悟，今人讀為吾，非也。」","sentenceOrder":335},
  {"id":"s_work_han_thu_51_336","chapterId":"ch_work_han_thu_51","textTraditional":"〔二〕　師古曰：「子羽，孔子弟子澹臺滅明字，貌惡而行善，故云然也。」","sentenceOrder":336},
  {"id":"s_work_han_thu_51_337","chapterId":"ch_work_han_thu_51","textTraditional":"〔三〕　師古曰：「謂無鬼神之事也。」","sentenceOrder":337},
  {"id":"s_work_han_thu_51_338","chapterId":"ch_work_han_thu_51","textTraditional":"〔四〕　師古曰：「離，遭也。」","sentenceOrder":338},
  {"id":"s_work_han_thu_51_339","chapterId":"ch_work_han_thu_51","textTraditional":"〔五〕　師古曰：「故謂中屯難也。」","sentenceOrder":339},
  {"id":"s_work_han_thu_51_340","chapterId":"ch_work_han_thu_51","textTraditional":"〔六〕　師古曰：「處伊尹、周公之任。」","sentenceOrder":340},
  {"id":"s_work_han_thu_51_341","chapterId":"ch_work_han_thu_51","textTraditional":"〔七〕　師古曰：「戇，愚也，舊音下紺反，今讀音竹巷反。」","sentenceOrder":341},
  {"id":"s_work_han_thu_51_342","chapterId":"ch_work_han_thu_51","textTraditional":"〔八〕　師古曰：「乃，汝也，言汝亦不及見也。」","sentenceOrder":342},
  {"id":"s_work_han_thu_51_343","chapterId":"ch_work_han_thu_51","textTraditional":"校勘記","sentenceOrder":343},
  {"id":"s_work_han_thu_51_344","chapterId":"ch_work_han_thu_51","textTraditional":"二０二三頁　四行　良（年）少，　景祐、殿本都無「年」字。","sentenceOrder":344},
  {"id":"s_work_han_thu_51_345","chapterId":"ch_work_han_thu_51","textTraditional":"二０二四頁　八行　良因怪（之），　景祐、殿本都無「之」字。","sentenceOrder":345},
  {"id":"s_work_han_thu_51_346","chapterId":"ch_work_han_thu_51","textTraditional":"二０二四頁一三行　常習〔讀〕誦。　宋祁說一本「習」下有「讀」字。　按景祐本有。","sentenceOrder":346},
  {"id":"s_work_han_thu_51_347","chapterId":"ch_work_han_thu_51","textTraditional":"二０二七頁　六行　今（有事）〔事有〕急，　景祐、殿本都作「事有」。","sentenceOrder":347},
  {"id":"s_work_han_thu_51_348","chapterId":"ch_work_han_thu_51","textTraditional":"二０二八頁一一行　因舉燕、（伐）〔代〕、齊、趙。　何焯說「伐」當作「代」。　按各本都作「伐」，史記作「代」。","sentenceOrder":348},
  {"id":"s_work_han_thu_51_349","chapterId":"ch_work_han_thu_51","textTraditional":"二０三０頁　三行　（示）天下不復輸積，　景祐、殿本都無「示」字。","sentenceOrder":349},
  {"id":"s_work_han_thu_51_350","chapterId":"ch_work_han_thu_51","textTraditional":"二０三０頁　四行　（左）〔離〕親戚，　景祐、殿本都作「離」，注同。","sentenceOrder":350},
  {"id":"s_work_han_thu_51_351","chapterId":"ch_work_han_thu_51","textTraditional":"二０三四頁一二行　上〔曰〕『終不使不肖子居愛子上』，明〔其〕代太子位必矣。　景祐、殿本都有「曰」字「其」字，史記同。","sentenceOrder":351},
  {"id":"s_work_han_thu_51_352","chapterId":"ch_work_han_thu_51","textTraditional":"二０三七頁　七行　人生一世〔間〕，　景祐、殿本都有「間」字，史記同。","sentenceOrder":352},
  {"id":"s_work_han_thu_51_353","chapterId":"ch_work_han_thu_51","textTraditional":"二０四一頁一六行　遂猶竟（也）。　景祐、殿本都無「也」字。","sentenceOrder":353},
  {"id":"s_work_han_thu_51_354","chapterId":"ch_work_han_thu_51","textTraditional":"二０四四頁一二行　出〔其〕郊遠迎謁也。　景祐、殿本都有「其」字。","sentenceOrder":354},
  {"id":"s_work_han_thu_51_355","chapterId":"ch_work_han_thu_51","textTraditional":"二０四五頁　四行　於是（召）〔詔〕御史，　景祐、殿本都作「詔」。　王先謙說作「詔」是。","sentenceOrder":355},
  {"id":"s_work_han_thu_51_356","chapterId":"ch_work_han_thu_51","textTraditional":"二０四五頁一二行　〔陳〕平乘馳傳　景祐、殿本都有「陳」字。","sentenceOrder":356},
  {"id":"s_work_han_thu_51_357","chapterId":"ch_work_han_thu_51","textTraditional":"二０四六頁一一行　言畏讒毒己者得（其成）〔成其〕計。　王先謙說「其成」字誤倒。","sentenceOrder":357},
  {"id":"s_work_han_thu_51_358","chapterId":"ch_work_han_thu_51","textTraditional":"二０四七頁　七行　問〔左〕丞相平　景祐、殿本都有「左」字。","sentenceOrder":358},
  {"id":"s_work_han_thu_51_359","chapterId":"ch_work_han_thu_51","textTraditional":"二０四九頁　五行　（各）有主者。　宋祁說越本無「各」字。　按景祐本亦無。　王念孫說無「各」字是。","sentenceOrder":359},
  {"id":"s_work_han_thu_51_360","chapterId":"ch_work_han_thu_51","textTraditional":"二０四九頁一０行　勃謝（病請）免相，　宋祁說越本無「病請」二字。　按景祐本亦無。","sentenceOrder":360},
  {"id":"s_work_han_thu_51_361","chapterId":"ch_work_han_thu_51","textTraditional":"二０五０頁　三行　坐略人妻棄（主）〔巿〕。　景祐、汲古、殿、局本都作「巿」，「主」字誤。","sentenceOrder":361},
  {"id":"s_work_han_thu_51_362","chapterId":"ch_work_han_thu_51","textTraditional":"二０五一頁　二行　攻（蘭）〔蒙〕、虞，取之。　齊召南說史記作「攻蒙、虞」，「蘭」當作「蒙」。　王先謙說地無「蘭虞」名，齊說是。","sentenceOrder":362},
  {"id":"s_work_han_thu_51_363","chapterId":"ch_work_han_thu_51","textTraditional":"二０五三頁　五行　〔擊〕陳豨，　景祐、殿本都有「擊」字，史記亦有，此脫。","sentenceOrder":363},
  {"id":"s_work_han_thu_51_364","chapterId":"ch_work_han_thu_51","textTraditional":"二０五四頁一五行　於是陰謀（乃）〔以〕為　景祐、殿本都作「以」。　王先謙說作「以」是。","sentenceOrder":364},
  {"id":"s_work_han_thu_51_365","chapterId":"ch_work_han_thu_51","textTraditional":"二０五五頁　五行　有數人不肯去，（官）〔宦〕者令張釋諭告，亦去。　景祐、殿、局本都作「宦」　王先謙說作「宦」是。","sentenceOrder":365},
  {"id":"s_work_han_thu_51_366","chapterId":"ch_work_han_thu_51","textTraditional":"二０五五頁一五行　上復用勃為（丞）相。　景祐、殿本都無「丞」字。","sentenceOrder":366},
  {"id":"s_work_han_thu_51_367","chapterId":"ch_work_han_thu_51","textTraditional":"二０五六頁　二行　以久當之〔不去〕，即禍及矣。　景祐、殿本都有「不去」二字。　王先謙說此脫。","sentenceOrder":367},
  {"id":"s_work_han_thu_51_368","chapterId":"ch_work_han_thu_51","textTraditional":"二０五七頁　三行　一年，〔文帝乃擇勃子賢者河內太守〕（弟）亞夫復為侯。　錢大昭說閩本無「弟」字，「亞夫」上多十二字。　按景祐本同閩本。二０六０頁一０頁　不（待）〔得〕。　錢大昭說「待」當作「得」。　按景祐、殿本都作「得」。","sentenceOrder":368},
  {"id":"s_work_han_thu_52_1","chapterId":"ch_work_han_thu_52","textTraditional":"樊噲，沛人也，以屠狗為事。〔一〕後與高祖俱隱於芒碭山澤間。","sentenceOrder":1},
  {"id":"s_work_han_thu_52_2","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「時人食狗亦與羊豕同，故噲專屠以賣。」","sentenceOrder":2},
  {"id":"s_work_han_thu_52_3","chapterId":"ch_work_han_thu_52","textTraditional":"陳勝初起，蕭何、曹參使噲求迎高祖，立為沛公。〔一〕噲以舍人從攻胡陵、方與，〔二〕還守豐，擊泗水監豐下，破之。〔三〕復東定沛，破泗水守薛西。〔四〕與司馬{尸二}戰碭東，〔五〕卻敵，斬首十五級，賜爵國大夫。〔六〕常從，沛公擊章邯軍濮陽，攻城先登，斬首二十三級，賜爵列大夫。〔七〕從攻（陽城）〔城陽〕，先登。下戶牖，〔八〕破李由軍，斬首十六級，賜上聞爵。〔九〕後攻圉都尉、東郡守尉於成武，〔一０〕卻敵，斬首十四級，捕虜十六人〔一一〕，賜爵五大夫。從攻秦軍，出亳南。〔一二〕河間守軍於杠里，破之。〔一三〕擊破趙賁軍開封北，〔一四〕以卻敵先登，斬候一人，首六十八級，捕虜二十六人，〔一五〕賜爵卿。從攻破揚熊於曲遇。〔一六〕攻宛陵，先登，斬首八級，捕虜四十四人，賜爵封號賢成君。〔一七〕從攻長社、轘轅，絕河津，東攻秦軍尸鄉，南攻秦軍於犨。破南陽守齮於陽城。東攻宛城，先登。西至酈，〔一八〕以卻敵，斬首十四級，捕虜四十（四）人，賜重封。〔一九〕攻武關，至霸上，斬都尉一人，首十級，捕虜百四十六人，降卒二千九百人。","sentenceOrder":3},
  {"id":"s_work_han_thu_52_4","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「高祖時亡在外，故求而迎之。」","sentenceOrder":4},
  {"id":"s_work_han_thu_52_5","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「皆縣名。方音房。與音豫。」","sentenceOrder":5},
  {"id":"s_work_han_thu_52_6","chapterId":"ch_work_han_thu_52","textTraditional":"〔三〕　師古曰：「泗水，郡名。監謂御史監郡者也，破之於豐縣下。」","sentenceOrder":6},
  {"id":"s_work_han_thu_52_7","chapterId":"ch_work_han_thu_52","textTraditional":"〔四〕　師古曰：「破郡守於薛縣之西。」","sentenceOrder":7},
  {"id":"s_work_han_thu_52_8","chapterId":"ch_work_han_thu_52","textTraditional":"〔五〕　師古曰：「秦將章邯之司馬也。{尸二}讀與夷同。」","sentenceOrder":8},
  {"id":"s_work_han_thu_52_9","chapterId":"ch_work_han_thu_52","textTraditional":"〔六〕　文穎曰：「即官大夫也，爵第六級。」","sentenceOrder":9},
  {"id":"s_work_han_thu_52_10","chapterId":"ch_work_han_thu_52","textTraditional":"〔七〕　文穎曰：「即公大夫也，爵第七級。」","sentenceOrder":10},
  {"id":"s_work_han_thu_52_11","chapterId":"ch_work_han_thu_52","textTraditional":"〔八〕　師古曰：「陽武縣之鄉。」","sentenceOrder":11},
  {"id":"s_work_han_thu_52_12","chapterId":"ch_work_han_thu_52","textTraditional":"〔九〕　張晏曰：「得徑上聞也。」如淳曰：「呂氏春秋曰『魏文侯東勝齊於長城，天子賞文侯以上聞』。」晉灼曰「名通於天子也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_52_13","chapterId":"ch_work_han_thu_52","textTraditional":"〔一０〕師古曰：「圉即陳留圉縣。」","sentenceOrder":13},
  {"id":"s_work_han_thu_52_14","chapterId":"ch_work_han_thu_52","textTraditional":"〔一一〕師古曰：「生獲曰虜。」","sentenceOrder":14},
  {"id":"s_work_han_thu_52_15","chapterId":"ch_work_han_thu_52","textTraditional":"〔一二〕鄭氏曰：「亳，成湯封邑，今河南偃師湯亭是。」","sentenceOrder":15},
  {"id":"s_work_han_thu_52_16","chapterId":"ch_work_han_thu_52","textTraditional":"〔一三〕師古曰：「杠音江。」","sentenceOrder":16},
  {"id":"s_work_han_thu_52_17","chapterId":"ch_work_han_thu_52","textTraditional":"〔一四〕師古曰：「賁音奔。」","sentenceOrder":17},
  {"id":"s_work_han_thu_52_18","chapterId":"ch_work_han_thu_52","textTraditional":"〔一五〕師古曰：「既斬候一人，又更斬它首六十八。」","sentenceOrder":18},
  {"id":"s_work_han_thu_52_19","chapterId":"ch_work_han_thu_52","textTraditional":"〔一六〕師古曰：「曲音丘羽反。遇音顒。」","sentenceOrder":19},
  {"id":"s_work_han_thu_52_20","chapterId":"ch_work_han_thu_52","textTraditional":"〔一七〕張晏曰：「食祿比封君而無邑也。」臣瓚曰：「秦制，列侯乃有封爵。」師古曰：「瓚說非也。楚漢之際，權設寵榮，假其位號，或得邑地，或空受爵，此例多矣。約以秦制，於義不通。」","sentenceOrder":20},
  {"id":"s_work_han_thu_52_21","chapterId":"ch_work_han_thu_52","textTraditional":"〔一八〕師古曰：「南陽之縣也，音直益反。」","sentenceOrder":21},
  {"id":"s_work_han_thu_52_22","chapterId":"ch_work_han_thu_52","textTraditional":"〔一九〕張晏曰：「益祿也。」如淳曰：「正爵名也。」臣瓚曰：「增封也。」師古曰：「諸家之說皆非也。重封者，加二號耳。」","sentenceOrder":22},
  {"id":"s_work_han_thu_52_23","chapterId":"ch_work_han_thu_52","textTraditional":"項羽在戲下，欲攻沛公。沛公從百餘騎因項伯面見項羽，謝無有閉關事。項羽既饗軍土，中酒，〔一〕亞父謀欲殺沛公，令項莊拔劍舞坐中，欲擊沛公，項伯常屏蔽之。時獨沛公與張良得入坐，樊噲居營外，聞事急，乃持盾入。初入營，營衛止噲，〔二〕噲直撞入，立帳下。〔三〕項羽目之，問為誰。張良曰：「沛公參乘樊噲也。」項羽曰：「壯士。」賜之卮酒彘肩。噲既飲酒，拔劍切肉食之。項羽曰：「能復飲乎？」噲曰：「臣死且不辭，豈特卮酒乎！且沛公先入定咸陽，暴師霸上，以待大王。〔四〕大王今日至，聽小人之言，與沛公有隙，臣恐天下解心疑大王也。」項羽默然。沛公如廁，麾噲去。既出，沛公留車騎，〔五〕獨騎馬，噲等四人步從，從山下走歸霸上軍，而使張良謝項羽。羽亦因遂已，〔六〕無誅沛公之心。是日微樊噲奔入營譙讓項羽，沛公幾殆。〔七〕","sentenceOrder":23},
  {"id":"s_work_han_thu_52_24","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　張晏曰：「酒酣也。」師古曰：「飲酒之中也。不醉不醒，故謂之中。中音竹仲反。」","sentenceOrder":24},
  {"id":"s_work_han_thu_52_25","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「營衛，謂營壘之守衛者。」","sentenceOrder":25},
  {"id":"s_work_han_thu_52_26","chapterId":"ch_work_han_thu_52","textTraditional":"〔三〕　師古曰：「謂以盾撞擊人。撞音丈江反。」","sentenceOrder":26},
  {"id":"s_work_han_thu_52_27","chapterId":"ch_work_han_thu_52","textTraditional":"〔四〕　師古曰：「時項羽未為王，故高紀云『以待將軍』。此言大王，史追書耳。」","sentenceOrder":27},
  {"id":"s_work_han_thu_52_28","chapterId":"ch_work_han_thu_52","textTraditional":"〔五〕　師古曰：「沛公所乘之車及從者之騎。」","sentenceOrder":28},
  {"id":"s_work_han_thu_52_29","chapterId":"ch_work_han_thu_52","textTraditional":"〔六〕　師古曰：「已，止也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_52_30","chapterId":"ch_work_han_thu_52","textTraditional":"〔七〕　師古曰：「微，無也。譙，責也。殆，危也。譙音才笑反。幾音鉅依反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_52_31","chapterId":"ch_work_han_thu_52","textTraditional":"後數日，項羽入屠咸陽，立沛公為漢王。漢王賜噲爵為列侯，號臨武侯。遷為郎中，從入漢中。","sentenceOrder":31},
  {"id":"s_work_han_thu_52_32","chapterId":"ch_work_han_thu_52","textTraditional":"還定三秦，別擊西丞白水北，〔一〕（擁）〔雍〕輕車騎雍南，破之。從攻雍、斄城，先登。〔二〕擊章平軍好畤，攻城，先登陷陣，斬縣令丞各一人，首十一級，虜二十人，遷為郎中騎將。從擊秦車騎壤東，〔三〕卻敵，遷為將軍。攻趙賁，下郿、槐里、柳中、咸陽；〔四〕灌廢丘，最。〔五〕至櫟陽，賜食邑杜之樊鄉。〔六〕從攻項籍，屠煮棗，〔七〕擊破王武、程處軍於外黃。攻鄒、魯、瑕丘、薛。項羽敗漢王於彭城，盡復取魯、梁地。噲還至滎陽，益食平陰二千戶，以將軍守廣武一歲。〔八〕項羽引東，從高祖擊項籍，下陽夏，〔九〕虜楚周將軍卒四千人。〔一０〕圍項籍陳，大破之。〔一一〕屠胡陵。","sentenceOrder":32},
  {"id":"s_work_han_thu_52_33","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　服虔曰：「西丞，縣名也。」晉灼曰：「白水，今廣平魏縣也。地理志無西丞，似秦將名也。」師古曰：「二說並非也。西謂隴西郡西縣也。白水，水名，經西縣東南流而過。言擊西縣之丞於白水之北。」","sentenceOrder":33},
  {"id":"s_work_han_thu_52_34","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「斄讀與邰同，縣名，即后稷所封，今武功故城是，音胎。」","sentenceOrder":34},
  {"id":"s_work_han_thu_52_35","chapterId":"ch_work_han_thu_52","textTraditional":"〔三〕　師古曰：「地名也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_52_36","chapterId":"ch_work_han_thu_52","textTraditional":"〔四〕　師古曰：「柳中即細柳地也，在長安西。」","sentenceOrder":36},
  {"id":"s_work_han_thu_52_37","chapterId":"ch_work_han_thu_52","textTraditional":"〔五〕　李奇曰：「以水灌廢丘也。」張晏曰：「最，功第一也。」晉灼曰：「京輔治華陰灌北也。」師古曰：「高紀言『引水灌廢丘』，李說是也。或者云漢王自彭城敗還始灌廢丘，此時未也。此說非矣。彭城還，更灌廢丘，始平定之，無廢丘。此時已當灌矣。」","sentenceOrder":37},
  {"id":"s_work_han_thu_52_38","chapterId":"ch_work_han_thu_52","textTraditional":"〔六〕　師古曰：「杜縣之鄉也，今曰樊川。」","sentenceOrder":38},
  {"id":"s_work_han_thu_52_39","chapterId":"ch_work_han_thu_52","textTraditional":"〔七〕　晉灼曰：「地理志無也。清河有煮棗城，功臣表有煮棗侯。」師古曰：「既云攻項籍，屠煮棗，則其地當在大河之南，非清河之城明矣，但未詳其處耳。」","sentenceOrder":39},
  {"id":"s_work_han_thu_52_40","chapterId":"ch_work_han_thu_52","textTraditional":"〔八〕　師古曰：「即滎陽之廣武。」","sentenceOrder":40},
  {"id":"s_work_han_thu_52_41","chapterId":"ch_work_han_thu_52","textTraditional":"〔九〕　師古曰：「夏音工雅反。」","sentenceOrder":41},
  {"id":"s_work_han_thu_52_42","chapterId":"ch_work_han_thu_52","textTraditional":"〔一０〕師古曰：「周殷。」","sentenceOrder":42},
  {"id":"s_work_han_thu_52_43","chapterId":"ch_work_han_thu_52","textTraditional":"〔一一〕師古曰：「於陳縣圍之。」","sentenceOrder":43},
  {"id":"s_work_han_thu_52_44","chapterId":"ch_work_han_thu_52","textTraditional":"項籍死，漢王即皇帝位，以噲有功，益食邑八百戶。其秋，燕王臧荼反，噲從攻虜荼，定燕地。楚王韓信反，噲從至陳，取信，定楚。更賜爵列侯，與剖符，世世勿絕，食舞陽，號為舞陽侯，除前所食。以將軍從攻反者韓王信於代。自霍人以往至雲中，與絳侯等共定之，益食千五百戶。因擊陳狶與曼丘臣軍，戰襄國，破柏人，先登，降（之）定清河、常山凡二十七縣，殘東垣，〔一〕遷為左丞相。破得綦母（印）〔卬〕、尹潘軍於無終、廣昌。〔二〕破豨別將胡人王黃軍代南，因擊韓信軍參合。軍所將卒斬韓信，擊豨胡騎橫谷，斬將軍趙既，虜代丞相馮梁、守孫奮、大將王黃、將軍（大將）一人、太僕解福等十人。與諸將共定代鄉邑七十三。後燕王盧綰反，噲以相國擊綰，破其丞相抵薊南，〔三〕定燕縣十八，鄉邑五十一。益食千三百戶，定食舞陽五千四百戶。從，斬首百七十六級，虜二百八十七人。別，破軍七，下城五，定郡六，縣五十二，得丞相一人，將軍十三人，二千石以下至三百石十二人。","sentenceOrder":44},
  {"id":"s_work_han_thu_52_45","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　張晏曰：「殘有所毀也。」臣瓚曰：「殘謂多所殺傷也。」師古曰：「瓚說是。」","sentenceOrder":45},
  {"id":"s_work_han_thu_52_46","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「姓綦母，名（印）〔卬〕也。綦音其。」","sentenceOrder":46},
  {"id":"s_work_han_thu_52_47","chapterId":"ch_work_han_thu_52","textTraditional":"〔三〕　師古曰：「抵，至也。一說，抵者，其丞相之名也，音丁禮反。」","sentenceOrder":47},
  {"id":"s_work_han_thu_52_48","chapterId":"ch_work_han_thu_52","textTraditional":"噲以呂后弟呂須為婦，生子伉，〔一〕故其比諸將最親。先黥布反時，高帝嘗病，〔二〕惡見人，臥禁中，詔戶者無得入群臣。群臣絳、灌等莫敢入。十餘日，噲乃排闥直入，〔三〕大臣隨之。上獨枕一宦者臥。噲等見上流涕曰：「始陛下與臣等起豐沛，定天下，何其壯也！今天下已定，又何憊也！〔四〕且陛下病甚，大臣震恐，不見臣等計事，顧獨與一宦者絕乎？〔五〕且陛下獨不見趙高之事乎？」〔六〕高帝笑而起。","sentenceOrder":48},
  {"id":"s_work_han_thu_52_49","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「伉音抗，又音剛。」","sentenceOrder":49},
  {"id":"s_work_han_thu_52_50","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「黥布未反之前。」","sentenceOrder":50},
  {"id":"s_work_han_thu_52_51","chapterId":"ch_work_han_thu_52","textTraditional":"〔三〕　師古曰：「闥，宮中小門也，一曰門屏也，音土曷反。」","sentenceOrder":51},
  {"id":"s_work_han_thu_52_52","chapterId":"ch_work_han_thu_52","textTraditional":"〔四〕　師古曰：「憊，力極也，音蒲拜反。」","sentenceOrder":52},
  {"id":"s_work_han_thu_52_53","chapterId":"ch_work_han_thu_52","textTraditional":"〔五〕　師古曰：「顧猶反也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_52_54","chapterId":"ch_work_han_thu_52","textTraditional":"〔六〕　師古曰：「謂始皇崩，趙高矯為詔命，殺扶蘇而立胡亥。」","sentenceOrder":54},
  {"id":"s_work_han_thu_52_55","chapterId":"ch_work_han_thu_52","textTraditional":"其後盧綰反，高帝使噲以相國擊燕。是時高帝病甚，人有惡噲黨於呂氏，〔一〕即上一日宮車晏駕，則噲欲以兵盡誅戚氏、趙王如意之屬。高帝大怒，乃使陳平載絳侯代將，而即軍中斬噲。〔二〕陳平畏呂后，執噲詣長安。至則高帝已崩，呂后釋噲，〔三〕得復爵邑。","sentenceOrder":55},
  {"id":"s_work_han_thu_52_56","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「惡謂毀譖，言其罪惡也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_52_57","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「即，就也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_52_58","chapterId":"ch_work_han_thu_52","textTraditional":"〔三〕　師古曰：「釋，解也，解免其罪。」","sentenceOrder":58},
  {"id":"s_work_han_thu_52_59","chapterId":"ch_work_han_thu_52","textTraditional":"孝惠六年，噲薨，諡曰武侯，子伉嗣。而伉母呂須亦為臨光侯，（噲）高后時用事顓權，〔一〕大臣盡畏之。高后崩，大臣誅呂須等，因誅伉，舞陽侯中絕數月。孝文帝立，乃復封噲庶子市人為侯，復故邑。薨，諡曰荒侯。子佗廣嗣。六歲，其舍人上書言：「荒侯巿人病不能為人，〔二〕令其夫人與其弟亂而生佗廣，佗廣實非荒侯子。」下吏，免。平帝元始二年，繼絕世，封噲玄孫之子章為舞陽侯，邑千戶。","sentenceOrder":59},
  {"id":"s_work_han_thu_52_60","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「顓與專同。」","sentenceOrder":60},
  {"id":"s_work_han_thu_52_61","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「言無人道也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_52_62","chapterId":"ch_work_han_thu_52","textTraditional":"酈商，高陽人也。〔一〕陳勝起，商聚少年得數千人。沛公略地六月餘，商以所將四千人屬沛公於岐。從攻長社，先登，賜爵封信成君。從攻緱氏，絕河津，破秦軍雒陽東。從下宛、穰，定十七縣。別將攻旬關，〔二〕西定漢中。〔三〕","sentenceOrder":62},
  {"id":"s_work_han_thu_52_63","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「酈音歷。」","sentenceOrder":63},
  {"id":"s_work_han_thu_52_64","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「漢中旬水上之關也，今在洵陽縣。」","sentenceOrder":64},
  {"id":"s_work_han_thu_52_65","chapterId":"ch_work_han_thu_52","textTraditional":"〔三〕　師古曰：「先言攻旬關，定漢中，然後云沛公為漢王，是則沛公從武關、藍田而來，商時別從西道平定漢中。」","sentenceOrder":65},
  {"id":"s_work_han_thu_52_66","chapterId":"ch_work_han_thu_52","textTraditional":"沛公為漢王，賜商爵信成君，以將軍為隴西都尉。別定北地郡，破章邯別將於烏氏、栒邑、泥陽，〔一〕賜食邑武城六千戶。從擊項籍軍，與鍾離眛戰，受梁相國印，〔二〕益食四千戶。從擊項羽二歲，攻胡陵。","sentenceOrder":66},
  {"id":"s_work_han_thu_52_67","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「烏氏，安定縣也。栒邑今在豳州。泥陽，北地縣。氏音支。栒音荀。」","sentenceOrder":67},
  {"id":"s_work_han_thu_52_68","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「漢以梁相國印授之。」","sentenceOrder":68},
  {"id":"s_work_han_thu_52_69","chapterId":"ch_work_han_thu_52","textTraditional":"漢王即帝位，燕王臧荼反，商以將軍從擊荼，戰龍脫，〔一〕先登陷陣，破荼軍易下，〔二〕卻敵，遷為右丞相，賜爵列侯，與剖符，世世勿絕，食邑涿郡五千戶。別定上谷，因攻代，受趙相國印〔三〕。與絳侯等定代郡、鴈門，得代丞相程縱、守相郭同、〔四〕將軍以下至六百石十九人。還，以將軍將太上皇衛一歲。十月，以右丞相擊陳豨，殘東垣。又從擊黥布，攻其前垣，〔五〕陷兩陳，得以破布軍，更封為曲周侯，食邑五千一百戶，除前所食。凡別破軍三，降定郡六，縣七十三，得丞相、守相、大將（軍）各一人，小將（軍）二人，二千石以下至六百石十九人。","sentenceOrder":69},
  {"id":"s_work_han_thu_52_70","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　孟康曰：「地名也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_52_71","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「今易縣。」","sentenceOrder":71},
  {"id":"s_work_han_thu_52_72","chapterId":"ch_work_han_thu_52","textTraditional":"〔三〕　師古曰：「初受梁相國印，今又受趙相國印。」","sentenceOrder":72},
  {"id":"s_work_han_thu_52_73","chapterId":"ch_work_han_thu_52","textTraditional":"〔四〕　師古曰：「守相，謂為相而居守者。」","sentenceOrder":73},
  {"id":"s_work_han_thu_52_74","chapterId":"ch_work_han_thu_52","textTraditional":"〔五〕　李奇曰：「前鋒堅蔽若垣牆也。或曰，軍前以大（軍）〔車〕自障若垣也。」師古曰：「二說皆非也。謂攻其壁壘之前垣。」","sentenceOrder":74},
  {"id":"s_work_han_thu_52_75","chapterId":"ch_work_han_thu_52","textTraditional":"商事孝惠帝、呂后。呂后崩，商疾不治事。〔一〕其子寄，子況，與呂祿善。及高后崩，大臣欲誅諸呂，呂祿為將軍，軍於北軍，太尉勃不得入北軍，於是乃使人劫商，令其子寄紿呂祿。呂祿信之，與出游，而太尉勃乃得入據北軍，遂以誅諸呂。商是歲薨，諡曰景侯。子寄嗣。天下稱酈況賣友。","sentenceOrder":75},
  {"id":"s_work_han_thu_52_76","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　文穎曰：「商有疾病，不能治官事。」","sentenceOrder":76},
  {"id":"s_work_han_thu_52_77","chapterId":"ch_work_han_thu_52","textTraditional":"孝景時，吳、楚、齊、趙反，上以寄為將軍，圍趙城，七月不能下。欒布自平齊來，乃滅趙。孝景中二年，寄欲取平原君（姊）為夫人，〔一〕景帝怒，下寄吏，免。上乃封商它子堅為繆侯，〔二〕奉商後。傳至玄孫終根，武帝時為太常，坐巫蠱誅，國除。元始中，賜高祖時功臣自酈商以下子孫爵（乎）〔皆〕關內侯，食邑凡百餘人。","sentenceOrder":77},
  {"id":"s_work_han_thu_52_78","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　蘇林曰：「景帝王皇后母臧兒也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_52_79","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「繆，所封邑名。」","sentenceOrder":79},
  {"id":"s_work_han_thu_52_80","chapterId":"ch_work_han_thu_52","textTraditional":"夏侯嬰，沛人也。為沛廄司御，每送使客，還過泗上亭，與高祖語，未嘗不移日也。嬰已而試補縣吏，與高祖相愛。高祖戲而傷嬰，人有告高祖。高祖時為亭長，重坐傷人，〔一〕告故不傷嬰，〔二〕嬰證之。移獄覆，嬰坐高祖繫歲餘，掠笞數百，終脫高祖。","sentenceOrder":80},
  {"id":"s_work_han_thu_52_81","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　如淳曰：「為吏傷人，其罪重。」","sentenceOrder":81},
  {"id":"s_work_han_thu_52_82","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　蘇林曰：「自告情故，不傷嬰也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_52_83","chapterId":"ch_work_han_thu_52","textTraditional":"高祖之初與徒屬欲攻沛也，〔一〕嬰時以縣令史為高祖使。上降沛一日，〔二〕高祖為沛公，賜爵七大夫，以嬰為太僕，常奉車〔三〕。從攻胡陵，嬰與蕭何降泗水監平，〔四〕平以胡陵降，賜嬰爵五大夫。從擊秦軍碭東，攻濟陽，下戶牖，破李由軍雍丘，以兵車趣攻戰疾，破之，〔五〕賜爵執帛。從擊章邯軍東阿、濮陽下，以兵車趣攻戰疾，破之，賜爵執圭。從擊趙賁軍開封，楊熊軍曲遇。嬰從捕虜六十八人，降卒八百五十人，得印一匱。〔六〕又擊秦軍雒陽東，以兵車趣攻戰疾，賜爵封，轉為滕令。〔七〕因奉車〔八〕從攻定南陽，戰於藍田、芷陽，〔九〕至霸上。沛公為漢王，賜嬰爵列侯，號昭平侯，復為太僕，從入蜀漢。","sentenceOrder":83},
  {"id":"s_work_han_thu_52_84","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「謂始亡在外，未被樊噲召時。」","sentenceOrder":84},
  {"id":"s_work_han_thu_52_85","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「謂父老開城門迎高祖時也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_52_86","chapterId":"ch_work_han_thu_52","textTraditional":"〔三〕　師古曰：「為沛公御車。」","sentenceOrder":86},
  {"id":"s_work_han_thu_52_87","chapterId":"ch_work_han_thu_52","textTraditional":"〔四〕　張晏曰：「胡陵，平所止縣，何嘗給之，故與降。」","sentenceOrder":87},
  {"id":"s_work_han_thu_52_88","chapterId":"ch_work_han_thu_52","textTraditional":"〔五〕　師古曰：「趣讀曰促，謂急速也。次下亦同。」","sentenceOrder":88},
  {"id":"s_work_han_thu_52_89","chapterId":"ch_work_han_thu_52","textTraditional":"〔六〕　師古曰：「時自相署置官之印。」","sentenceOrder":89},
  {"id":"s_work_han_thu_52_90","chapterId":"ch_work_han_thu_52","textTraditional":"〔七〕　鄧展曰：「今沛郡公丘縣。」","sentenceOrder":90},
  {"id":"s_work_han_thu_52_91","chapterId":"ch_work_han_thu_52","textTraditional":"〔八〕　師古曰：「因此又每奉車從攻戰，以至霸上。」","sentenceOrder":91},
  {"id":"s_work_han_thu_52_92","chapterId":"ch_work_han_thu_52","textTraditional":"〔九〕　師古曰：「芷陽後為霸陵縣。」","sentenceOrder":92},
  {"id":"s_work_han_thu_52_93","chapterId":"ch_work_han_thu_52","textTraditional":"還定三秦，從擊項籍。至彭城，項羽大破漢軍。漢王不利，馳去。見孝惠、魯元，載之。漢王急，馬罷，虜在後，〔一〕常蹳兩兒棄之，〔二〕嬰常收載行，面雍樹馳。〔三〕漢王怒，欲斬嬰者十餘，卒得脫，而致孝惠、魯元於豐。","sentenceOrder":93},
  {"id":"s_work_han_thu_52_94","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「罷讀曰疲。」","sentenceOrder":94},
  {"id":"s_work_han_thu_52_95","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　服虔曰：「蹳音撥。」晉灼曰：「音足跋物之跋。」師古曰：「服音是。」","sentenceOrder":95},
  {"id":"s_work_han_thu_52_96","chapterId":"ch_work_han_thu_52","textTraditional":"〔三〕　服虔曰：「高祖欲斬之，故嬰圍樹走，面向樹也。」應劭曰：「古者立乘，嬰恐小兒墮墜，各置一面擁持之。樹，立也。」蘇林曰：「南方人謂抱小兒為雍樹。面者，以面首向臨之也。」師古曰：「面，偝也。雍，抱持之。言取兩兒，令面背己，而抱持之以馳，故云面雍樹馳。服言圍樹而走，義尤疏越，雍讀曰擁。」","sentenceOrder":96},
  {"id":"s_work_han_thu_52_97","chapterId":"ch_work_han_thu_52","textTraditional":"漢王既至滎陽，收散兵，復振，賜嬰食邑沂陽。〔一〕擊項籍下邑，追至陳，卒定楚。至魯，益食茲氏。〔二〕","sentenceOrder":97},
  {"id":"s_work_han_thu_52_98","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「沂音魚依反。」","sentenceOrder":98},
  {"id":"s_work_han_thu_52_99","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「茲氏，縣名，地理志屬太原。」","sentenceOrder":99},
  {"id":"s_work_han_thu_52_100","chapterId":"ch_work_han_thu_52","textTraditional":"漢王即帝位，燕王臧荼反，嬰從擊荼。明年，從至陳，取楚王信。更食汝陰，剖符，世世勿絕。從擊代，至武泉、雲中，益食千戶。因從擊韓信軍胡騎晉陽旁，大破之。追北至平城，為胡所圍，七日不得通。高帝使使厚遺閼氏，冒頓乃開其圍一角。高帝出欲馳，嬰固徐行，弩皆持滿外鄉，〔一〕卒以得脫。〔二〕益食嬰細陽千戶。〔三〕從擊胡騎句注北，大破之。擊胡騎平城南，三陷陳，功為多，（閼）〔賜〕所奪邑五百戶。〔四〕從擊陳豨、黥布軍，陷陳卻敵，益千戶，定食汝陰六千九百戶，除前所食。","sentenceOrder":100},
  {"id":"s_work_han_thu_52_101","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「故示閑暇，所以固士卒心，而令敵不測也。鄉讀曰嚮。」","sentenceOrder":101},
  {"id":"s_work_han_thu_52_102","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「卒，終也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_52_103","chapterId":"ch_work_han_thu_52","textTraditional":"〔三〕　師古曰：「益其邑使食之。」","sentenceOrder":103},
  {"id":"s_work_han_thu_52_104","chapterId":"ch_work_han_thu_52","textTraditional":"〔四〕　孟康曰：「時有罪過奪邑者，以賜之。」","sentenceOrder":104},
  {"id":"s_work_han_thu_52_105","chapterId":"ch_work_han_thu_52","textTraditional":"嬰自上初起沛，常為太僕從，竟高祖崩。以太僕事惠帝。惠帝及高后德嬰之脫孝惠、魯元於下邑間也，乃賜嬰北第第一，〔一〕曰「近我」，以尊異之。惠帝崩，以太僕事高后。高后崩，代王之來，嬰以太僕與東牟侯入清宮，廢少帝，以天子法駕迎代王代邸，與大臣共立文帝，復為太僕。八歲薨，諡曰文侯。傳至曾孫頗，〔二〕尚平陽公主，坐與父御婢奸，自殺，國除。","sentenceOrder":105},
  {"id":"s_work_han_thu_52_106","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「北第者，近北闕之第，嬰最第一也。故張衡西京賦云『北闕甲第，當道直啟』。」","sentenceOrder":106},
  {"id":"s_work_han_thu_52_107","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「頗音普河反。」","sentenceOrder":107},
  {"id":"s_work_han_thu_52_108","chapterId":"ch_work_han_thu_52","textTraditional":"初嬰為滕令奉車，故號滕公。及曾孫頗尚主，主隨外家姓，號孫公主，故滕公子孫更為孫氏。","sentenceOrder":108},
  {"id":"s_work_han_thu_52_109","chapterId":"ch_work_han_thu_52","textTraditional":"灌嬰，睢陽販繒者也。〔一〕高祖為沛公，略地至雍丘，章邯殺項梁，而沛公還軍於碭，嬰以中涓從，擊破東郡尉於成武及秦軍於杠里，疾鬥，賜爵七大夫。又從攻秦軍亳南、開封、曲遇，戰疾力〔二〕，賜爵執帛，號宣陵君。從攻陽武以西至雒陽，破秦軍尸北。北絕河津，南破南陽守齮陽城東，遂定南陽郡。西入武關，戰於藍田，疾力，至霸上，賜爵執圭，號昌文君。","sentenceOrder":109},
  {"id":"s_work_han_thu_52_110","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「繒者，帛之總名。」","sentenceOrder":110},
  {"id":"s_work_han_thu_52_111","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　孟康曰：「攻戰速疾也。」師古曰：「疾，急速也。力，強力也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_52_112","chapterId":"ch_work_han_thu_52","textTraditional":"沛公為漢王，拜嬰為郎中，從入漢中，十月，拜為中謁者。從還定三秦，下櫟陽，降塞王。還圍章邯廢丘，未拔。從東出臨晉關，擊降殷王，定其地。擊項羽將龍且、魏相項佗軍定陶南，疾戰，破之。賜嬰爵列侯，號昌文侯，食杜平鄉。〔一〕","sentenceOrder":112},
  {"id":"s_work_han_thu_52_113","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「杜縣之平鄉。」","sentenceOrder":113},
  {"id":"s_work_han_thu_52_114","chapterId":"ch_work_han_thu_52","textTraditional":"復以中謁者從降下碭，以北至彭城。項羽擊破漢王，漢王遁而西，嬰從還，軍於雍丘。王武、魏公申徒反，〔一〕從擊破之。攻下外黃，西收軍於滎陽。楚騎來眾，漢王乃擇軍中可為騎將者，皆推故秦騎士重泉人李必、駱甲〔二〕習騎兵，今為校尉，可為騎將。漢王欲拜之，必、甲曰：「臣故秦民，恐軍不信臣，臣願得大王左右善騎者傅之。」〔三〕嬰雖少，然數力戰，乃拜嬰為中大夫，令李必、駱甲為左右校尉，將郎中騎兵擊楚騎於滎陽東，大破之。受詔別擊楚軍後，絕其饟道，〔四〕起陽武至襄邑。擊項羽之將項冠於魯下，破之，所將卒斬右司馬、騎將各一人。〔五〕擊破柘公王武軍燕西，〔六〕所將卒斬樓煩將五人，〔七〕連尹一人。〔八〕擊王武別將桓嬰白馬下，破之，所將卒斬都尉一人。以騎度河南，送漢王到雒陽，從北迎相國韓信軍於邯鄲。還至敖倉，嬰遷為御史大夫。","sentenceOrder":114},
  {"id":"s_work_han_thu_52_115","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　張晏曰：「故秦將，降為公，今反。」","sentenceOrder":115},
  {"id":"s_work_han_thu_52_116","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「重泉，縣名也，地理志屬左馮翊。」","sentenceOrder":116},
  {"id":"s_work_han_thu_52_117","chapterId":"ch_work_han_thu_52","textTraditional":"〔三〕　如淳曰：「傅音附，猶言隨從者。」","sentenceOrder":117},
  {"id":"s_work_han_thu_52_118","chapterId":"ch_work_han_thu_52","textTraditional":"〔四〕　師古曰：「饟，古餉字。」","sentenceOrder":118},
  {"id":"s_work_han_thu_52_119","chapterId":"ch_work_han_thu_52","textTraditional":"〔五〕　張晏曰：「主右方之馬，左亦如之。」晉灼曰：「下所謂左右千人之騎。」","sentenceOrder":119},
  {"id":"s_work_han_thu_52_120","chapterId":"ch_work_han_thu_52","textTraditional":"〔六〕　師古曰：「柘，縣名。公者，柘之令也。王武，其人姓名也。燕亦縣名，古南燕國也。音一千反。」","sentenceOrder":120},
  {"id":"s_work_han_thu_52_121","chapterId":"ch_work_han_thu_52","textTraditional":"〔七〕　李奇曰：「樓煩，縣名，其人善騎射，故名射士為樓煩，取其稱也。」師古曰：「解在項羽傳。」","sentenceOrder":121},
  {"id":"s_work_han_thu_52_122","chapterId":"ch_work_han_thu_52","textTraditional":"〔八〕　蘇林曰：「楚官也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_52_123","chapterId":"ch_work_han_thu_52","textTraditional":"三年，以列侯食邑杜平鄉。受詔將郎中騎兵東屬相國韓信，擊破齊軍於歷下，所將卒虜（單）〔車〕騎將（軍）華毋傷〔一〕及將吏四十六人。降下臨淄，得相田光。追齊相田橫至嬴、博，〔二〕擊破其騎，所將卒斬騎將一人，生得騎將四人。攻下嬴、博，破齊將軍田吸於千乘，斬之。東從韓信攻龍且、留公於假密，〔三〕卒斬龍且，〔四〕生得右司馬、連尹各一人，樓煩將十人，身生得亞將周蘭〔五〕。","sentenceOrder":123},
  {"id":"s_work_han_thu_52_124","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「華音下化反。」","sentenceOrder":124},
  {"id":"s_work_han_thu_52_125","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「二縣名。」","sentenceOrder":125},
  {"id":"s_work_han_thu_52_126","chapterId":"ch_work_han_thu_52","textTraditional":"〔三〕　師古曰：「留，縣名，公，留令也。攻龍且及留令於假密。」","sentenceOrder":126},
  {"id":"s_work_han_thu_52_127","chapterId":"ch_work_han_thu_52","textTraditional":"〔四〕　師古曰：「嬰所將之卒也。其下亦同。」","sentenceOrder":127},
  {"id":"s_work_han_thu_52_128","chapterId":"ch_work_han_thu_52","textTraditional":"〔五〕　師古曰：「亞，次也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_52_129","chapterId":"ch_work_han_thu_52","textTraditional":"齊地已定，韓信自立為齊王，使嬰別將擊楚將公杲於魯北，破之。轉南，破薛郡長，〔一〕身虜騎將（入）〔一人〕。攻（博）〔傅〕陽，前至下相以東南僮、取慮、徐。〔二〕度淮，盡降其城邑，至廣陵。〔三〕項羽使項聲、薛公、郯公復定淮北，嬰度淮擊破項聲、郯公下邳，斬薛公，下下邳、壽春。擊破楚騎平陽，〔四〕遂降彭城。虜柱國項佗，〔五〕降留、薛、沛、酇、蕭、相。〔六〕攻苦、譙，〔七〕復得亞將。與漢王會頤鄉。從擊項籍軍陳下，破之。所將卒斬樓煩將二人，虜將八人。賜益食邑二千五百戶。","sentenceOrder":129},
  {"id":"s_work_han_thu_52_130","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「長，亦如郡守也，時每郡置長。」","sentenceOrder":130},
  {"id":"s_work_han_thu_52_131","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「僮及取慮及徐，三縣名也。取音趨，又音秋，慮音廬。」","sentenceOrder":131},
  {"id":"s_work_han_thu_52_132","chapterId":"ch_work_han_thu_52","textTraditional":"〔三〕　蘇林曰：「別將兵屯廣陵也。」師古曰：「此說非也。謂從下相以東南盡降城邑，乃至廣陵皆平定。」","sentenceOrder":132},
  {"id":"s_work_han_thu_52_133","chapterId":"ch_work_han_thu_52","textTraditional":"〔四〕　師古曰：「此平陽在東郡。」","sentenceOrder":133},
  {"id":"s_work_han_thu_52_134","chapterId":"ch_work_han_thu_52","textTraditional":"〔五〕　師古曰：「佗音徒何反。」","sentenceOrder":134},
  {"id":"s_work_han_thu_52_135","chapterId":"ch_work_han_thu_52","textTraditional":"〔六〕　師古曰：「凡六縣也，酇音才何反。」","sentenceOrder":135},
  {"id":"s_work_han_thu_52_136","chapterId":"ch_work_han_thu_52","textTraditional":"〔七〕　師古曰：「二縣也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_52_137","chapterId":"ch_work_han_thu_52","textTraditional":"項籍敗垓下去也，嬰以御史大夫將車騎別追項籍至東城，破之。所將卒五人共斬項籍，皆賜爵列侯。降左右司馬各一人，卒萬二千人，盡得其軍將吏。下東城、歷陽。度江，破吳郡長吳下，〔一〕得吳守，遂定吳、豫章、會稽郡。還定淮北，凡五十二縣。","sentenceOrder":137},
  {"id":"s_work_han_thu_52_138","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　如淳曰：「雄長之長也。」師古曰：「此說非也。吳郡長，當時為吳郡長，嬰破之於吳下。」","sentenceOrder":138},
  {"id":"s_work_han_thu_52_139","chapterId":"ch_work_han_thu_52","textTraditional":"漢王即帝位，賜益嬰邑三千戶。以車騎將軍從擊燕王荼。明年，從至陳，取楚王信。還，剖符，世世勿絕，食潁陰二千五百戶。","sentenceOrder":139},
  {"id":"s_work_han_thu_52_140","chapterId":"ch_work_han_thu_52","textTraditional":"從擊（漢）〔韓〕王信於代，至馬邑，別降樓煩以北六縣，斬代左將，破胡騎將於武泉北。復從擊信胡騎晉陽下，所將卒斬胡白題將一人。〔一〕又受詔并將燕、趙、齊、梁、楚車騎，擊破胡騎於硰石。〔二〕至平城，為胡所困。","sentenceOrder":140},
  {"id":"s_work_han_thu_52_141","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「胡名也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_52_142","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「硰音千坐反。」","sentenceOrder":142},
  {"id":"s_work_han_thu_52_143","chapterId":"ch_work_han_thu_52","textTraditional":"從擊陳豨，別攻豨丞相侯敞軍曲逆下，破之，卒斬敞及特將五人。〔一〕降曲逆、盧奴、上曲陽、安國、安平。攻下東垣。","sentenceOrder":143},
  {"id":"s_work_han_thu_52_144","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「卒謂所將之卒也。特，獨也，各（特）〔獨〕為將。」","sentenceOrder":144},
  {"id":"s_work_han_thu_52_145","chapterId":"ch_work_han_thu_52","textTraditional":"黥布反，以車騎將軍先出，攻布別將於相，破之，斬亞將樓煩將三人。又進擊破布上柱國及大司馬軍。又進破布別將肥銖。嬰身生得左司馬一人，所將卒斬其小將十人，追北至淮上。益食邑二千五百戶。布已破，高帝歸，定令嬰食潁陰五千戶，除前所食邑。凡從所得二千石二人，別破軍十六，降城四十六，定國一，郡二，縣五十二，得將軍二人，柱國、相各一人，二千石十人。","sentenceOrder":145},
  {"id":"s_work_han_thu_52_146","chapterId":"ch_work_han_thu_52","textTraditional":"嬰自破布歸，高帝崩，以列侯事惠帝及呂后。呂后崩，呂祿等欲為亂。齊哀王聞之，舉兵西，呂祿等以嬰為大將軍往擊之。嬰至滎陽，乃與絳侯等謀，因屯兵滎陽，風齊王以誅呂氏事，〔一〕齊兵止不前。絳侯等既誅諸呂，齊王罷兵歸。嬰自滎陽還，與絳侯、陳平共立文帝。於是益封嬰三千戶，賜金千斤，為太尉。","sentenceOrder":146},
  {"id":"s_work_han_thu_52_147","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「風讀曰諷。」","sentenceOrder":147},
  {"id":"s_work_han_thu_52_148","chapterId":"ch_work_han_thu_52","textTraditional":"三歲，絳侯勃免相，嬰為丞相，罷太尉官。是歲，匈奴大入北地，上令丞相嬰將騎八萬五千擊匈奴。匈奴去，濟北王反，詔罷嬰兵。後歲餘，以丞相薨，諡曰懿侯。傳至孫（疆）〔彊〕，有罪，絕。武帝復封嬰孫賢為臨汝侯，奉嬰後，後有罪，國除。","sentenceOrder":148},
  {"id":"s_work_han_thu_52_149","chapterId":"ch_work_han_thu_52","textTraditional":"傅寬，以魏五大夫騎將從，為舍人，起橫陽。從攻安陽、杠里，趙賁軍於開封，及擊楊熊曲遇、陽武，斬首十二級，賜爵卿。從至霸上。沛公為漢王，賜寬封號共德君。〔一〕從入漢中，為右騎將。定三秦，賜食邑雕陰。〔二〕從擊項籍，待懷，〔三〕賜爵通德侯。從擊項冠、周蘭、龍且，所將卒斬騎將一人敖下，〔四〕益食邑。","sentenceOrder":149},
  {"id":"s_work_han_thu_52_150","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「共讀曰恭。」","sentenceOrder":150},
  {"id":"s_work_han_thu_52_151","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　孟康曰：「縣名，屬上郡。」","sentenceOrder":151},
  {"id":"s_work_han_thu_52_152","chapterId":"ch_work_han_thu_52","textTraditional":"〔三〕　服虔曰：「（侍）〔待〕高帝於懷。懷，縣（召）〔名〕也。」師古曰：「地理志屬河內，即今懷州。」","sentenceOrder":152},
  {"id":"s_work_han_thu_52_153","chapterId":"ch_work_han_thu_52","textTraditional":"〔四〕　師古曰：「敖，地名。敖倉蓋取此名也。左氏傳曰『敖、鄗之間』。」","sentenceOrder":153},
  {"id":"s_work_han_thu_52_154","chapterId":"ch_work_han_thu_52","textTraditional":"屬淮陰，〔一〕擊破齊歷下軍，擊田解。屬相國參，殘博，〔二〕益食邑。因定齊地，剖符世世勿絕，封陽陵侯，二千六百戶，除前所食。為齊右丞相，備齊。〔三〕五歲為齊相國。","sentenceOrder":154},
  {"id":"s_work_han_thu_52_155","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　張晏曰：「韓信也。信時為相國，云淮陰者，終言之也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_52_156","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「參，曹參也。博，太山縣也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_52_157","chapterId":"ch_work_han_thu_52","textTraditional":"〔三〕　張晏曰：「時田橫未降，故設屯備。」","sentenceOrder":157},
  {"id":"s_work_han_thu_52_158","chapterId":"ch_work_han_thu_52","textTraditional":"四月，擊陳豨，屬太尉勃，以相國代丞相噲擊豨。一月，徙為代相國，將屯。〔一〕二歲，為丞相，將屯。孝惠五年薨，諡曰景侯。傳至曾孫偃，謀反，誅，國除。","sentenceOrder":158},
  {"id":"s_work_han_thu_52_159","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　如淳曰：「既為相國，有警則將卒而屯守也。」師古曰：「此說非也。時代國常有屯兵以備邊寇，寬為代相，兼將此屯兵也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_52_160","chapterId":"ch_work_han_thu_52","textTraditional":"靳歙，以中涓從，起宛朐。〔一〕攻濟陽。破李由軍。擊秦軍開封東，斬騎千人將一人，〔二〕首五十七級，捕虜七十三人，賜爵封臨平君。又戰藍田北，斬車司馬二人，〔三〕騎長一人，〔四〕首二十八級，捕虜五十七人。至霸上。沛公為漢王，賜歙爵建武侯，遷騎都尉。","sentenceOrder":160},
  {"id":"s_work_han_thu_52_161","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「歙音翕。宛音於元反。朐音其于反。」","sentenceOrder":161},
  {"id":"s_work_han_thu_52_162","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　如淳曰：「騎將率號為千人。漢儀注邊郡置部都尉、千人、司馬、候也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_52_163","chapterId":"ch_work_han_thu_52","textTraditional":"〔三〕　張晏曰：「主車也。」","sentenceOrder":163},
  {"id":"s_work_han_thu_52_164","chapterId":"ch_work_han_thu_52","textTraditional":"〔四〕　張晏曰：「騎之長。」","sentenceOrder":164},
  {"id":"s_work_han_thu_52_165","chapterId":"ch_work_han_thu_52","textTraditional":"從定三秦。別西擊章平軍於隴西，破之，定隴西六縣，所將卒斬車司馬、候各四人，騎長十二人。從東擊楚，至彭城。漢軍敗還，保雍丘，擊反者王武等。略梁地，別西擊邢說軍菑南，破之，〔一〕身得說都尉二人，司馬、候十二人，降吏卒四千六百八十人。破楚軍滎陽東。食邑四千二百戶。","sentenceOrder":165},
  {"id":"s_work_han_thu_52_166","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「菑，縣名也，後為考城。說讀曰悅。」","sentenceOrder":166},
  {"id":"s_work_han_thu_52_167","chapterId":"ch_work_han_thu_52","textTraditional":"別之河內，擊趙賁軍朝歌，破之，所將卒得騎將二人，車馬二百五十匹。從攻安陽以東，至棘蒲，下十縣。別攻破趙軍，得其將司馬二人，候四人，降吏卒二千四百人。從降下邯鄲。別下平陽，身斬守相，所將卒斬兵守郡一人，〔一〕降鄴。從攻朝歌、邯鄲，又別擊破趙（郡）〔軍〕，降邯鄲郡六縣。還軍敖倉，破項籍軍成皋南，擊絕楚饟道，起滎陽至襄邑。破項冠魯下。略地東至鄫、郯、下邳，南至蘄、竹邑。擊項悍濟陽下。還擊項籍軍陳下，破之。別定江陵，降柱國、大司馬以下八人，身得江陵王，致雒陽，〔二〕因定南郡。從至陳，取楚王信，剖符世世勿絕，定食四千六百戶，為信武侯。","sentenceOrder":167},
  {"id":"s_work_han_thu_52_168","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　李奇曰：「或以為郡守也，字反耳。」晉灼曰：「將兵郡守也。」師古曰：「當言兵郡守一人也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_52_169","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「江陵王謂共敖之子共尉也，得而送致於雒陽。」","sentenceOrder":169},
  {"id":"s_work_han_thu_52_170","chapterId":"ch_work_han_thu_52","textTraditional":"以騎都尉〔從〕擊代，攻韓信平城下，還軍東垣。有功，遷為車騎將軍，并將梁、趙、齊、燕、楚車騎，別擊陳豨丞相敞，破之〔一〕，因降曲逆。從擊黥布有功，益封，定食邑五千三百戶。凡斬首九十級，虜百四十二人，別破軍十四，降城五十九，定郡、國各一，縣二十三，得王、柱國各一人，二千石以下至五〔百〕石三十九人。","sentenceOrder":170},
  {"id":"s_work_han_thu_52_171","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「侯敞。」","sentenceOrder":171},
  {"id":"s_work_han_thu_52_172","chapterId":"ch_work_han_thu_52","textTraditional":"高后五年，薨，諡曰肅侯。子亭嗣，有罪，國除。","sentenceOrder":172},
  {"id":"s_work_han_thu_52_173","chapterId":"ch_work_han_thu_52","textTraditional":"周緤，沛人也。〔一〕以舍人從高祖起沛。至霸上，西入蜀漢，還定三秦，常為參乘，賜食邑池陽。〔二〕從東擊項羽滎陽，絕甬道，從出度平陰，遇韓信軍襄國，戰有利不利，終亡離上心。上以緤為信武侯，〔三〕食邑三千三百戶。","sentenceOrder":173},
  {"id":"s_work_han_thu_52_174","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「緤音息列反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_52_175","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　師古曰：「即馮翊池陽縣。」","sentenceOrder":175},
  {"id":"s_work_han_thu_52_176","chapterId":"ch_work_han_thu_52","textTraditional":"〔三〕　師古曰：「以其忠信，故加此號。」","sentenceOrder":176},
  {"id":"s_work_han_thu_52_177","chapterId":"ch_work_han_thu_52","textTraditional":"上欲自擊陳豨，緤泣曰：「始秦攻破天下，未曾自行，今上常自行，是亡人可使者乎？」上以為「愛我」，賜入殿門不趨。","sentenceOrder":177},
  {"id":"s_work_han_thu_52_178","chapterId":"ch_work_han_thu_52","textTraditional":"十二年，更封緤為〈崩阝〉城侯，〔一〕孝文五年薨，諡曰貞侯。子昌嗣，有罪，國除。景帝復封緤子應為鄲侯，〔二〕薨，諡曰康侯。子仲居嗣，坐為太常有罪，國除。","sentenceOrder":178},
  {"id":"s_work_han_thu_52_179","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　服虔曰：「音菅蒯之蒯。」蘇林曰：「音簿催反。」晉灼曰：「功臣表屬長沙。」師古曰：「此字從崩，從邑，音蒯，非也。呂忱音陪，而楚漢春秋作憑城侯。陪、憑聲相近，此其實也。又音普肯反。」","sentenceOrder":179},
  {"id":"s_work_han_thu_52_180","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　蘇林曰：「音多，屬沛國。」","sentenceOrder":180},
  {"id":"s_work_han_thu_52_181","chapterId":"ch_work_han_thu_52","textTraditional":"贊曰：仲尼稱「犁牛之子騂且角，雖欲勿用，山川其舍諸？〔一〕」言士不繫於世類也。語曰「雖有茲基，不如逢時」，〔二〕信矣！樊噲、夏侯嬰、灌嬰之徒，方其鼓刀僕御販繒之時，〔三〕豈自知附驥之尾，〔四〕（勤）〔勒〕功帝籍，慶流子孫哉？當孝文時，天下以酈寄為賣友。夫賣友者，謂見利而忘義也。若寄父為功臣而又執劫，〔五〕雖摧呂祿，以安社稷，誼存君親，可也。","sentenceOrder":181},
  {"id":"s_work_han_thu_52_182","chapterId":"ch_work_han_thu_52","textTraditional":"〔一〕　師古曰：「論語載孔子為弟子仲弓發此言也。犁，雜色；騂，赤色也。舍，置也。言牛色純而角美，堪為犧牲，雖以其母犁色而不欲用，山川寧肯置之？喻父雖不材，不害子之美。」","sentenceOrder":182},
  {"id":"s_work_han_thu_52_183","chapterId":"ch_work_han_thu_52","textTraditional":"〔二〕　張晏曰：「茲基，鉏也。言雖有田具，值時乃獲。」","sentenceOrder":183},
  {"id":"s_work_han_thu_52_184","chapterId":"ch_work_han_thu_52","textTraditional":"〔三〕　師古曰：「鼓刀謂屠狗。」","sentenceOrder":184},
  {"id":"s_work_han_thu_52_185","chapterId":"ch_work_han_thu_52","textTraditional":"〔四〕　師古曰：「蓋以蚊｛亡虫｝為喻，言託驥之尾，則涉千里。」","sentenceOrder":185},
  {"id":"s_work_han_thu_52_186","chapterId":"ch_work_han_thu_52","textTraditional":"〔五〕　師古曰：「周勃等劫其父而令寄行說。」","sentenceOrder":186},
  {"id":"s_work_han_thu_52_187","chapterId":"ch_work_han_thu_52","textTraditional":"校勘記","sentenceOrder":187},
  {"id":"s_work_han_thu_52_188","chapterId":"ch_work_han_thu_52","textTraditional":"二０六七頁　八行　從攻（陽城）〔城陽〕，　史記作「城陽」，正義說漢書作「陽城」，大錯誤。","sentenceOrder":188},
  {"id":"s_work_han_thu_52_189","chapterId":"ch_work_han_thu_52","textTraditional":"二０六八頁　一行　捕虜四十（四）人，　景祐、殿本都作「四十人」，史記同。","sentenceOrder":189},
  {"id":"s_work_han_thu_52_190","chapterId":"ch_work_han_thu_52","textTraditional":"二０七０頁　九行　（擁）〔雍〕輕車騎雍南，　景祐本作「雍」，史記同。王念孫說作「雍」是。","sentenceOrder":190},
  {"id":"s_work_han_thu_52_191","chapterId":"ch_work_han_thu_52","textTraditional":"二０七二頁　二行　降（之）定清河、常山凡二十七縣，　王先謙說「之」字衍，史記無。","sentenceOrder":191},
  {"id":"s_work_han_thu_52_192","chapterId":"ch_work_han_thu_52","textTraditional":"二０七二頁　三行　破得綦母（印）〔卬〕，　景祐、殿本都作「卬」。王先謙說作「卬」是。注同。","sentenceOrder":192},
  {"id":"s_work_han_thu_52_193","chapterId":"ch_work_han_thu_52","textTraditional":"二０七二頁　五行　將軍（大將）一人、　史記作「將軍太卜」，王先謙疑「大將」即「太卜」之誤。但汲古本史記無「太卜」二字，則此「大將」二字當是衍文。","sentenceOrder":193},
  {"id":"s_work_han_thu_52_194","chapterId":"ch_work_han_thu_52","textTraditional":"二０七三頁一四行　（噲）高后時用事顓權，　景祐、殿本都無「噲」字。　錢大昭說無「噲」字是。","sentenceOrder":194},
  {"id":"s_work_han_thu_52_195","chapterId":"ch_work_han_thu_52","textTraditional":"二０七五頁　七行　得丞相、守相、大將（軍）各一人，小將（軍）二人，　景祐本無二「軍」字。王念孫說景祐本是，史記亦無二「軍」字。","sentenceOrder":195},
  {"id":"s_work_han_thu_52_196","chapterId":"ch_work_han_thu_52","textTraditional":"二０七五頁一二行　軍前以大（軍）〔車〕自障若垣也。　景祐、殿本都作「車」。　王先謙說作「車」是。","sentenceOrder":196},
  {"id":"s_work_han_thu_52_197","chapterId":"ch_work_han_thu_52","textTraditional":"二０七六頁　四行　寄欲取平原君（姊）為夫人　王先謙說各本無「姊」字，是。","sentenceOrder":197},
  {"id":"s_work_han_thu_52_198","chapterId":"ch_work_han_thu_52","textTraditional":"二０七六頁　六行　酈商以下子孫爵（乎）〔皆〕關內侯，　景祐、殿本都作「皆」。王先謙說作「皆」是。","sentenceOrder":198},
  {"id":"s_work_han_thu_52_199","chapterId":"ch_work_han_thu_52","textTraditional":"二０七九頁　一行　（閼）〔賜〕所奪邑五百戶。　景祐、殿本都作「賜」。　王先謙說「閼」字誤。","sentenceOrder":199},
  {"id":"s_work_han_thu_52_200","chapterId":"ch_work_han_thu_52","textTraditional":"二０八一頁一六行　所將卒虜（單）〔車〕騎將（軍）華毋傷　景祐、殿本都作「車」。王先謙說「單」字誤。「華」字上景祐本無「軍」字。","sentenceOrder":200},
  {"id":"s_work_han_thu_52_201","chapterId":"ch_work_han_thu_52","textTraditional":"二０八二頁一０行　身虜騎將（入）〔一人〕。攻（博）〔傅〕陽，　齊召南說「入」字係「一人」兩字傳寫誤併。沈欽韓說「博陽」當作「傅陽」。","sentenceOrder":201},
  {"id":"s_work_han_thu_52_202","chapterId":"ch_work_han_thu_52","textTraditional":"二０八三頁一三行　從擊（漢）〔韓〕王信於代，　景祐、殿、局本都作「韓」，「漢」字誤。","sentenceOrder":202},
  {"id":"s_work_han_thu_52_203","chapterId":"ch_work_han_thu_52","textTraditional":"二０八四頁　五行　各（特）〔獨〕為將。　景祐、殿本都作「獨」。王先謙說作「獨」是。","sentenceOrder":203},
  {"id":"s_work_han_thu_52_204","chapterId":"ch_work_han_thu_52","textTraditional":"二０八五頁　二行　傳至孫（疆）〔彊〕，　景祐、殿本都作「彊」。","sentenceOrder":204},
  {"id":"s_work_han_thu_52_205","chapterId":"ch_work_han_thu_52","textTraditional":"二０八五頁一０行　（侍）〔待〕高帝於懷。懷，縣（召）〔名〕也。　景祐、殿、局本都作「待」作「名」，此誤。","sentenceOrder":205},
  {"id":"s_work_han_thu_52_206","chapterId":"ch_work_han_thu_52","textTraditional":"二０八七頁　七行　又別擊破趙（郡）〔軍〕，　景祐、殿本都作「軍」。　王先謙說作「軍」是。","sentenceOrder":206},
  {"id":"s_work_han_thu_52_207","chapterId":"ch_work_han_thu_52","textTraditional":"二０八七頁一四行　以騎都尉〔從〕擊代，　景祐、殿本都有「從」字。","sentenceOrder":207},
  {"id":"s_work_han_thu_52_208","chapterId":"ch_work_han_thu_52","textTraditional":"二０八八頁　二行　至五〔百〕石三十九人。　景祐、殿本都有「百」字，此脫。","sentenceOrder":208},
  {"id":"s_work_han_thu_52_209","chapterId":"ch_work_han_thu_52","textTraditional":"二０八九頁　六行　（勤）〔勒〕功帝籍，　景祐、殿本都作「勒」。　王先謙說作「勒」是。","sentenceOrder":209},
  {"id":"s_work_han_thu_53_1","chapterId":"ch_work_han_thu_53","textTraditional":"張蒼，陽武人也，好書律曆。秦時為御史，主柱下方書。〔一〕有罪，亡歸。及沛公略地過陽武，蒼以客從攻南陽。蒼當斬，解衣伏質，〔二〕身長大，肥白如瓠，時王陵見而怪其美士，乃言沛公，赦勿斬。遂西入武關，至咸陽。","sentenceOrder":1},
  {"id":"s_work_han_thu_53_2","chapterId":"ch_work_han_thu_53","textTraditional":"〔一〕　如淳曰：「方，板也，謂事在板上者也。秦置柱下史，蒼為御史，主其事。或曰主四方文書也。」師古曰：「下云蒼自秦時為柱下御史，明習天下圖書計籍，則主四方文書是也。柱下，居殿柱之下，若今侍立御史矣。」","sentenceOrder":2},
  {"id":"s_work_han_thu_53_3","chapterId":"ch_work_han_thu_53","textTraditional":"〔二〕　師古曰：「質，鍖也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_53_4","chapterId":"ch_work_han_thu_53","textTraditional":"沛公立為漢王，入漢中，還定三秦。陳餘擊走常山王張耳，耳歸漢，漢以蒼為常山守。從韓信擊趙，蒼得陳餘。趙地已平，漢王以蒼為代相，備邊寇。已而徙為趙相，相趙王耳。耳卒，相其子敖。復徙相代。燕王臧荼反，蒼以代相從攻荼有功，（六年）封為北平侯，食邑千二百戶。","sentenceOrder":4},
  {"id":"s_work_han_thu_53_5","chapterId":"ch_work_han_thu_53","textTraditional":"遷為計相，〔一〕一月，更以列侯為主計四歲。〔二〕是時蕭何為相國，而蒼乃自秦時為柱下御史，明習天下圖書計籍，又善用算律曆，故令蒼以列侯居相府，領主郡國上計者。黥布反，漢立皇子長為淮南王，而蒼相之。十四年，遷為御史大夫。","sentenceOrder":5},
  {"id":"s_work_han_thu_53_6","chapterId":"ch_work_han_thu_53","textTraditional":"〔一〕　文穎曰：「以能計，故號曰計相。」師古曰：「專主計籍，故號計相。」","sentenceOrder":6},
  {"id":"s_work_han_thu_53_7","chapterId":"ch_work_han_thu_53","textTraditional":"〔二〕　張晏曰：「以列侯典校郡國簿書。」如淳曰：「以其所主，因以為官號，與計相同。時所卒立，非久施也。」師古曰：「去計相之名，更號主計。」","sentenceOrder":7},
  {"id":"s_work_han_thu_53_8","chapterId":"ch_work_han_thu_53","textTraditional":"周昌者，沛人也。其從兄苛，〔一〕秦時皆為泗水卒史。及高祖（沛起）〔起沛〕，擊破泗水守監，於是苛、昌（自）〔以〕卒史從沛公，沛公以昌為職志，〔二〕苛為客。〔三〕從入關破秦。沛公立為漢王，以苛為御史大夫，昌為中尉。","sentenceOrder":8},
  {"id":"s_work_han_thu_53_9","chapterId":"ch_work_han_thu_53","textTraditional":"〔一〕　師古曰：「苛音何。」","sentenceOrder":9},
  {"id":"s_work_han_thu_53_10","chapterId":"ch_work_han_thu_53","textTraditional":"〔二〕　應劭曰：「掌主職也。」鄭氏曰：「主旗志也。」師古曰：「志與幟同，音式異反。」","sentenceOrder":10},
  {"id":"s_work_han_thu_53_11","chapterId":"ch_work_han_thu_53","textTraditional":"〔三〕　張晏曰：「為帳下賓客，不掌官也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_53_12","chapterId":"ch_work_han_thu_53","textTraditional":"漢三年，楚圍漢王滎陽急，漢王出去，而使苛守滎陽城。楚破滎陽城，欲令苛將，苛罵曰：「若趣降漢王！不然，今為（慮）〔虜〕矣！」〔一〕項羽怒，亨苛。漢王於是拜昌為御史大夫。常從擊破項籍。六年，與蕭、曹等俱封，為汾陰侯。苛子成以父死事，封為高景侯。","sentenceOrder":12},
  {"id":"s_work_han_thu_53_13","chapterId":"ch_work_han_thu_53","textTraditional":"〔一〕　師古曰：「若，汝也。趣讀曰促。」","sentenceOrder":13},
  {"id":"s_work_han_thu_53_14","chapterId":"ch_work_han_thu_53","textTraditional":"昌為人強力，敢直言，自蕭、曹等皆卑下之。〔一〕昌嘗燕入奏事，〔二〕高帝方擁戚姬，〔三〕昌還走。〔四〕高帝逐得，騎昌項，上問曰：「我何如主也？」昌仰曰：「陛下即桀紂之主也。」於是上笑之，然尤憚昌。及高帝欲廢太子，而立戚姬子如意為太子，大臣固爭莫能得，上以留侯策止。而昌庭爭之強，上問其說，昌為人吃，〔五〕又盛怒，曰：「臣口不能言，然臣（心）〔期期〕知其（其）不可。陛下欲廢太子，臣期期不奉詔。」〔六〕上欣然而笑，即罷。呂后側耳於東箱聽，〔七〕見昌，為跪謝曰：「微君，太子幾廢。」〔八〕","sentenceOrder":14},
  {"id":"s_work_han_thu_53_15","chapterId":"ch_work_han_thu_53","textTraditional":"〔一〕　師古曰：「下音胡駕反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_53_16","chapterId":"ch_work_han_thu_53","textTraditional":"〔二〕　孟康曰：「以上宴時入奏事。」師古曰：「燕謂安閑之居也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_53_17","chapterId":"ch_work_han_thu_53","textTraditional":"〔三〕　師古曰：「擁，抱也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_53_18","chapterId":"ch_work_han_thu_53","textTraditional":"〔四〕　師古曰：「還謂卻退也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_53_19","chapterId":"ch_work_han_thu_53","textTraditional":"〔五〕　師古曰：「吃，言之難也，音訖。」","sentenceOrder":19},
  {"id":"s_work_han_thu_53_20","chapterId":"ch_work_han_thu_53","textTraditional":"〔六〕　師古曰：「以口吃，故每重言期期。」","sentenceOrder":20},
  {"id":"s_work_han_thu_53_21","chapterId":"ch_work_han_thu_53","textTraditional":"〔七〕　師古曰：「正寢之東西室皆曰箱，言似箱篋之形。」","sentenceOrder":21},
  {"id":"s_work_han_thu_53_22","chapterId":"ch_work_han_thu_53","textTraditional":"〔八〕　師古曰：「微，無也。幾音鉅依反。」","sentenceOrder":22},
  {"id":"s_work_han_thu_53_23","chapterId":"ch_work_han_thu_53","textTraditional":"是歲，戚姬子如意為趙王，年十歲，高祖憂萬歲之後不全也。趙堯為符璽御史，趙人方與公〔一〕謂御史大夫周昌曰：「君之史趙堯，年雖少，然奇士，君必異之，是且代君之位。」昌笑曰：「堯年少，刀筆吏耳，何至是乎！」居頃之，堯侍高祖，高祖獨心不樂，悲歌，群臣不知上所以然。堯進請（間）〔問〕曰：「陛下所為不樂，非以趙王年少，而戚夫人與呂后有隙，備萬歲之後而趙王不能自全乎？」高祖曰：「我私憂之，不知所出。」〔二〕堯曰：「陛下獨為趙王置貴彊相，及呂后、太子、群臣素所敬憚者乃可。」高祖曰：「然。吾念之欲如是，而群臣誰可者？」堯曰：「御史大夫昌，其人堅忍伉直，自呂后、太子及大臣皆素嚴憚之。獨昌可。」高祖曰：「善。」於是召昌謂曰：「吾固欲煩公，〔三〕公彊為我相趙。」〔四〕昌泣曰：「臣初起從陛下，陛下獨奈何中道而棄之於諸侯乎？」高祖曰：「吾極知其左遷，〔五〕然吾私憂趙，念非公無可者。公不得已強行！」〔六〕於是徙御史大夫昌為趙相。","sentenceOrder":23},
  {"id":"s_work_han_thu_53_24","chapterId":"ch_work_han_thu_53","textTraditional":"〔一〕　孟康曰：「方與，縣名。公，其號也。」師古曰：「音房豫。」","sentenceOrder":24},
  {"id":"s_work_han_thu_53_25","chapterId":"ch_work_han_thu_53","textTraditional":"〔二〕　師古曰：「不知計所出。」","sentenceOrder":25},
  {"id":"s_work_han_thu_53_26","chapterId":"ch_work_han_thu_53","textTraditional":"〔三〕　師古曰：「固，必也，言必欲勞煩公。」","sentenceOrder":26},
  {"id":"s_work_han_thu_53_27","chapterId":"ch_work_han_thu_53","textTraditional":"〔四〕　師古曰：「彊音其兩反。次下亦同。」","sentenceOrder":27},
  {"id":"s_work_han_thu_53_28","chapterId":"ch_work_han_thu_53","textTraditional":"〔五〕　師古曰：「是時尊右而卑左，故謂貶秩位為左遷。佗皆類此。」","sentenceOrder":28},
  {"id":"s_work_han_thu_53_29","chapterId":"ch_work_han_thu_53","textTraditional":"〔六〕　師古曰：「已，止也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_53_30","chapterId":"ch_work_han_thu_53","textTraditional":"既行久之，高祖持御史大夫印弄之，曰：「誰可以為御史大夫者？」孰視堯曰：「無以易堯。」〔一〕遂拜堯為御史大夫。堯亦前有軍功食邑，及以御史大夫從擊陳豨有功，封為江邑侯。","sentenceOrder":30},
  {"id":"s_work_han_thu_53_31","chapterId":"ch_work_han_thu_53","textTraditional":"〔一〕　師古曰：「言堯可為之，餘人不能勝也。易，代也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_53_32","chapterId":"ch_work_han_thu_53","textTraditional":"高祖崩，太后使使召趙王，其相昌令王稱疾不行。使者三反，昌曰：「高帝屬臣趙王，〔一〕王年少，竊聞太后怨戚夫人，欲召趙王并誅之。臣不敢遣王，王且亦疾，不能奉詔。」太后怒，乃使使召趙相。相至，謁太后，太后罵昌曰：「爾不知我之怨戚氏乎？而不遣趙王！」昌既被徵，高后使使召趙王。王果來，至長安月餘，見鴆殺。昌謝病不朝見，三歲而薨，諡曰悼侯。傳子至孫意，有罪，國除。景帝復封昌孫左車為安陽侯，有罪，國除。","sentenceOrder":32},
  {"id":"s_work_han_thu_53_33","chapterId":"ch_work_han_thu_53","textTraditional":"〔一〕　師古曰：「屬，委也，音之欲反。」","sentenceOrder":33},
  {"id":"s_work_han_thu_53_34","chapterId":"ch_work_han_thu_53","textTraditional":"初，趙堯既代周昌為御史大夫，高祖崩，事惠帝終世。高后元年，怨堯前定趙王如意之畫，〔一〕乃抵堯罪，以廣阿侯任敖為御史大夫。","sentenceOrder":34},
  {"id":"s_work_han_thu_53_35","chapterId":"ch_work_han_thu_53","textTraditional":"〔一〕　師古曰：「畫謂畫策令周昌為相。」","sentenceOrder":35},
  {"id":"s_work_han_thu_53_36","chapterId":"ch_work_han_thu_53","textTraditional":"任敖，沛人也，少為獄吏。高祖嘗避吏，吏繫呂后，遇之不謹。任敖素善高祖，怒，擊傷主呂后吏。及高祖初起，敖以客從為御史，守豐二歲。高祖立為漢王，東擊項羽，敖遷為上黨守。陳豨反，敖堅守，封為廣阿侯，食邑千八百戶。高后時為御史大夫，三歲免。孝文元年薨，諡曰懿侯。傳子至曾孫越人，坐為太常廟酒酸不敬，國除。","sentenceOrder":36},
  {"id":"s_work_han_thu_53_37","chapterId":"ch_work_han_thu_53","textTraditional":"初任敖免，平陽侯曹窋代敖為御史大夫。〔一〕高后崩，與大臣共誅諸呂。後坐事免，以淮南相張蒼為御史大夫。蒼與絳侯等尊立孝文皇帝，四年，代灌嬰為丞相。","sentenceOrder":37},
  {"id":"s_work_han_thu_53_38","chapterId":"ch_work_han_thu_53","textTraditional":"〔一〕　師古曰：「窋音竹律反。」","sentenceOrder":38},
  {"id":"s_work_han_thu_53_39","chapterId":"ch_work_han_thu_53","textTraditional":"漢興二十餘年，天下初定，公卿皆軍吏。蒼為計相時，緒正律曆。〔一〕以高祖十月始至霸上，故因秦時本十月為歲首，不革。〔二〕推五德之運，以為漢當水德之時，上黑如故。吹律調樂，入之音聲，及以比定律令。〔三〕若百工，天下作程品。〔四〕至於為丞相，卒就之。〔五〕故漢家言律曆者本張蒼。蒼（尤）〔凡〕好書，無所不觀，無所不通，而尤邃律曆。〔六〕","sentenceOrder":39},
  {"id":"s_work_han_thu_53_40","chapterId":"ch_work_han_thu_53","textTraditional":"〔一〕　文穎曰：「緒，尋也，謂本其統緒而正之。」","sentenceOrder":40},
  {"id":"s_work_han_thu_53_41","chapterId":"ch_work_han_thu_53","textTraditional":"〔二〕　師古曰：「革，改也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_53_42","chapterId":"ch_work_han_thu_53","textTraditional":"〔三〕　如淳曰：「比音比次之比。謂五音清濁，各有所比，不相錯入，以定十二律之法令於樂官，使長行之。或曰，比謂比方之比，音必履反。」臣瓚曰：「謂以比故取類，以定法律與條令也。」師古曰：「依如氏之說，比音頻二反。」","sentenceOrder":42},
  {"id":"s_work_han_thu_53_43","chapterId":"ch_work_han_thu_53","textTraditional":"〔四〕　如淳曰：「若，順也。百工為器物皆有尺寸斤兩斛斗輕重之宜，使得其法，此之謂順。」晉灼曰：「若，豫及之辭。」師古曰：「言吹律調音以定法令，及百工程品，皆取則也。若，晉說是。」","sentenceOrder":43},
  {"id":"s_work_han_thu_53_44","chapterId":"ch_work_han_thu_53","textTraditional":"〔五〕　師古曰：「卒，終也。就，成也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_53_45","chapterId":"ch_work_han_thu_53","textTraditional":"〔六〕　師古曰：「邃，深也，音先遂反。」","sentenceOrder":45},
  {"id":"s_work_han_thu_53_46","chapterId":"ch_work_han_thu_53","textTraditional":"蒼德安國侯王陵，〔一〕及貴，父事陵。陵死後，蒼為丞相，洗沐，常先朝陵夫人上食，然後敢歸家。","sentenceOrder":46},
  {"id":"s_work_han_thu_53_47","chapterId":"ch_work_han_thu_53","textTraditional":"〔一〕　師古曰：「以救其死刑故也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_53_48","chapterId":"ch_work_han_thu_53","textTraditional":"蒼為丞相十餘年，魯人公孫臣上書，陳終始五德傳，〔一〕言漢土德時，其符黃龍見，當改正朔，易服色。事下蒼，蒼以為非是，罷之。其後黃龍見成紀，於是文帝召公孫臣以為博士，草立土德時曆制度，〔二〕更元年。蒼由此自絀，謝病稱老。蒼任人為中候，〔三〕大為姦利，上以為讓，〔四〕蒼遂病免。孝景五年薨，諡曰文侯。傳子至孫類，有罪，國除。","sentenceOrder":48},
  {"id":"s_work_han_thu_53_49","chapterId":"ch_work_han_thu_53","textTraditional":"〔一〕　師古曰：「傳謂傳次也，音直戀反。」","sentenceOrder":49},
  {"id":"s_work_han_thu_53_50","chapterId":"ch_work_han_thu_53","textTraditional":"〔二〕　張晏曰：「以秦水德，漢土勝之。」晉灼曰：「草，創始也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_53_51","chapterId":"ch_work_han_thu_53","textTraditional":"〔三〕　張晏曰：「所選舉保任也。按中候，官名。」師古曰：「蒼有所保舉，而其人為中候之官。」","sentenceOrder":51},
  {"id":"s_work_han_thu_53_52","chapterId":"ch_work_han_thu_53","textTraditional":"〔四〕　師古曰：「用此事責蒼。」","sentenceOrder":52},
  {"id":"s_work_han_thu_53_53","chapterId":"ch_work_han_thu_53","textTraditional":"初蒼父長不滿五尺，蒼長八尺餘，蒼子復長八尺，及孫類長六尺餘。蒼免相後，口中無齒，食乳，女子為乳母。〔一〕妻妾以百數，嘗孕者不復幸。年百餘歲乃卒。著書十八篇，言陰陽律曆事。","sentenceOrder":53},
  {"id":"s_work_han_thu_53_54","chapterId":"ch_work_han_thu_53","textTraditional":"〔一〕　師古曰：「言每就飲之。」","sentenceOrder":54},
  {"id":"s_work_han_thu_53_55","chapterId":"ch_work_han_thu_53","textTraditional":"申屠嘉，梁人也。以材官蹶張〔一〕從高帝擊項籍，遷為隊率。〔二〕從擊黥布，為都尉。孝惠時，為淮陽守。孝文元年，舉故以二千石從高祖者，悉以為關內侯，食邑二十四人，而嘉食邑五百戶。十六年，遷為御史大夫。張蒼免相，文帝以皇后弟竇廣國賢有行，欲相之，曰：「恐天下以吾私廣國。」久念不可，而高帝時大臣餘見無可者，〔三〕乃以御史大夫嘉為丞相，因故邑封為故安侯。","sentenceOrder":55},
  {"id":"s_work_han_thu_53_56","chapterId":"ch_work_han_thu_53","textTraditional":"〔一〕　如淳曰：「材官之多力，能腳踏彊弩張之，故曰蹶張。律有蹶張士。」師古曰：「今之弩，以手張者曰擘張，以足蹋者曰蹶張。蹶音厥。擘音布麥反。」","sentenceOrder":56},
  {"id":"s_work_han_thu_53_57","chapterId":"ch_work_han_thu_53","textTraditional":"〔二〕　師古曰：「一隊之率也，音所類反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_53_58","chapterId":"ch_work_han_thu_53","textTraditional":"〔三〕　師古曰：「見謂見在之人。」","sentenceOrder":58},
  {"id":"s_work_han_thu_53_59","chapterId":"ch_work_han_thu_53","textTraditional":"嘉為人廉直，門不受私謁。是時太中大夫鄧通方愛幸，賞賜累鉅萬。文帝常燕飲通家，其（見）寵如是。是時嘉入朝，而通居上旁，有怠慢之禮，嘉奏事畢，因言曰：「陛下幸愛群臣則富貴之，至於朝廷之禮，不可以不肅！」〔一〕上曰：「君勿言，吾私之。」〔二〕罷朝坐府中，嘉為檄召通詣丞相府，〔三〕不來，且斬通。通恐，入言上。上曰：「汝弟往，〔四〕吾今使人召若。」〔五〕通至（詣）丞相府，免冠，徒跣，頓首謝嘉。嘉坐自如，〔六〕弗為禮，責曰：「夫朝廷者，高皇帝之朝廷也，通小臣，戲殿上，大不敬，當斬。史今行斬之！」〔七〕通頓首，首盡出血，不解。上度丞相已困通〔八〕，使使持節召通，而謝丞相：「此吾弄臣，君釋之。」鄧通既至，為上泣曰：「丞相幾殺臣。」〔九〕","sentenceOrder":59},
  {"id":"s_work_han_thu_53_60","chapterId":"ch_work_han_thu_53","textTraditional":"〔一〕　師古曰：「肅，敬也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_53_61","chapterId":"ch_work_han_thu_53","textTraditional":"〔二〕　師古曰：「言欲私戒教之。」","sentenceOrder":61},
  {"id":"s_work_han_thu_53_62","chapterId":"ch_work_han_thu_53","textTraditional":"〔三〕　師古曰：「檄，木書也，長二尺。」","sentenceOrder":62},
  {"id":"s_work_han_thu_53_63","chapterId":"ch_work_han_thu_53","textTraditional":"〔四〕　師古曰：「弟，但也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_53_64","chapterId":"ch_work_han_thu_53","textTraditional":"〔五〕　師古曰：「若亦汝也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_53_65","chapterId":"ch_work_han_thu_53","textTraditional":"〔六〕　師古曰：「如其故。」","sentenceOrder":65},
  {"id":"s_work_han_thu_53_66","chapterId":"ch_work_han_thu_53","textTraditional":"〔七〕　如淳曰：「嘉語其史曰：『今便行斬之。』」","sentenceOrder":66},
  {"id":"s_work_han_thu_53_67","chapterId":"ch_work_han_thu_53","textTraditional":"〔八〕　師古曰：「度音徒各反。」","sentenceOrder":67},
  {"id":"s_work_han_thu_53_68","chapterId":"ch_work_han_thu_53","textTraditional":"〔九〕　師古曰：「幾音巨依反。」","sentenceOrder":68},
  {"id":"s_work_han_thu_53_69","chapterId":"ch_work_han_thu_53","textTraditional":"嘉為丞相五歲，文帝崩，孝景即位。二年，晁錯為內史，貴幸用事，諸法令多所請變更，議以適罰侵削諸侯。〔一〕而丞相嘉自絀，〔二〕所言不用，疾錯。錯為內史，門東出，不便，更穿一門，南出。南出者，太上皇廟堧垣也。〔三〕嘉聞錯穿宗廟垣，為奏請誅錯。客有語錯，錯恐，夜入宮上謁，自歸上。〔四〕至朝，嘉請誅內史錯。上曰：「錯所穿非真廟垣，乃外堧垣，故冗官居其中，〔五〕且又我使為之，錯無罪。」罷朝，嘉謂長史曰：「吾悔不先斬錯乃請之，〔六〕為錯所賣。」至舍，因歐血而死。諡曰節侯。傳子至孫臾，有罪，國除。","sentenceOrder":69},
  {"id":"s_work_han_thu_53_70","chapterId":"ch_work_han_thu_53","textTraditional":"〔一〕　師古曰：「適讀曰謫。」","sentenceOrder":70},
  {"id":"s_work_han_thu_53_71","chapterId":"ch_work_han_thu_53","textTraditional":"〔二〕　師古曰：「絀，退也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_53_72","chapterId":"ch_work_han_thu_53","textTraditional":"〔三〕　服虔曰：「宮外垣餘地也。」如淳曰：「堧音畏懦之懦。」師古曰：「堧音如椽反，解在食貨志。」","sentenceOrder":72},
  {"id":"s_work_han_thu_53_73","chapterId":"ch_work_han_thu_53","textTraditional":"〔四〕　師古曰：「歸首於天子。」","sentenceOrder":73},
  {"id":"s_work_han_thu_53_74","chapterId":"ch_work_han_thu_53","textTraditional":"〔五〕　師古曰：「冗謂散輩也，如今之散官，音如勇反。」","sentenceOrder":74},
  {"id":"s_work_han_thu_53_75","chapterId":"ch_work_han_thu_53","textTraditional":"〔六〕　師古曰：「言先斬而後奏。」","sentenceOrder":75},
  {"id":"s_work_han_thu_53_76","chapterId":"ch_work_han_thu_53","textTraditional":"自嘉死後，開封侯陶青、桃侯劉舍及武帝時柏至侯許昌、平棘侯薛澤、武彊侯莊青翟、商陵侯趙周，皆以列侯繼踵，〈足齒〉〈足齒〉廉謹，〔一〕為丞相備員而已，無所能發明功名著於世者。","sentenceOrder":76},
  {"id":"s_work_han_thu_53_77","chapterId":"ch_work_han_thu_53","textTraditional":"〔一〕　師古曰：「〈足齒〉〈足齒〉，持整之貌也。〈足齒〉音初角反。」","sentenceOrder":77},
  {"id":"s_work_han_thu_53_78","chapterId":"ch_work_han_thu_53","textTraditional":"贊曰：張蒼文好律曆，為漢名相，〔一〕而專遵用秦之顓頊曆，何哉？〔二〕周昌，木強人也。〔三〕任敖以舊德用。〔四〕申屠嘉可謂剛毅守節，然無術學，殆與蕭、曹、陳平異矣。〔五〕","sentenceOrder":78},
  {"id":"s_work_han_thu_53_79","chapterId":"ch_work_han_thu_53","textTraditional":"〔一〕　師古曰：「文好律曆，猶言名為好律曆也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_53_80","chapterId":"ch_work_han_thu_53","textTraditional":"〔二〕　張晏曰：「不考經典，專用顓頊曆，何哉？」師古曰：「何哉，何為其然哉？」","sentenceOrder":80},
  {"id":"s_work_han_thu_53_81","chapterId":"ch_work_han_thu_53","textTraditional":"〔三〕　師古曰：「言其強（直）〔質〕如木石然。強音其兩反。」","sentenceOrder":81},
  {"id":"s_work_han_thu_53_82","chapterId":"ch_work_han_thu_53","textTraditional":"〔四〕　張晏曰：「謂傷辱呂后吏。」","sentenceOrder":82},
  {"id":"s_work_han_thu_53_83","chapterId":"ch_work_han_thu_53","textTraditional":"〔五〕　師古曰：「殆，近也，言其識見不如蕭、曹等也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_53_84","chapterId":"ch_work_han_thu_53","textTraditional":"校勘記","sentenceOrder":84},
  {"id":"s_work_han_thu_53_85","chapterId":"ch_work_han_thu_53","textTraditional":"二０九三頁一一行　（六年）封為北平侯，　景祐、殿本都無「六年」二字。","sentenceOrder":85},
  {"id":"s_work_han_thu_53_86","chapterId":"ch_work_han_thu_53","textTraditional":"二０九四頁　七行　及高祖（沛起）〔起沛〕，　景祐、殿本都作「起沛」，此誤倒。","sentenceOrder":86},
  {"id":"s_work_han_thu_53_87","chapterId":"ch_work_han_thu_53","textTraditional":"二０九四頁　八行　於是苛、昌（自）〔以〕卒史從沛公，　宋祁說越本「自」作「以」。按景祐本作「以」。","sentenceOrder":87},
  {"id":"s_work_han_thu_53_88","chapterId":"ch_work_han_thu_53","textTraditional":"二０九五頁　一行　今為（慮）〔虜〕矣！　景祐、殿本都作「虜」。錢大昭說當為「虜」。","sentenceOrder":88},
  {"id":"s_work_han_thu_53_89","chapterId":"ch_work_han_thu_53","textTraditional":"二０九五頁　七行　然臣（心）〔期期〕知其（其）不可。　景祐、殿本都無「心」字及下「其」字，「知」上有「期期」二字。","sentenceOrder":89},
  {"id":"s_work_han_thu_53_90","chapterId":"ch_work_han_thu_53","textTraditional":"二０九六頁　五行　堯進請（間）〔問〕曰：　景祐、殿本都作「問」。王念孫說「請問」義自可通，史記亦作「請問」。","sentenceOrder":90},
  {"id":"s_work_han_thu_53_91","chapterId":"ch_work_han_thu_53","textTraditional":"二０九八頁一一行　蒼（尤）〔凡〕好書，無所不觀，　景祐本作「凡」。王念孫說「凡」當讀為「汎」。","sentenceOrder":91},
  {"id":"s_work_han_thu_53_92","chapterId":"ch_work_han_thu_53","textTraditional":"二一０一頁　一行　其（見）寵如是。　宋祁說越本無「見」字。按景祐本亦無。","sentenceOrder":92},
  {"id":"s_work_han_thu_53_93","chapterId":"ch_work_han_thu_53","textTraditional":"二一０一頁　四行　通至（詣）丞相府，　王先謙說「詣」字誤衍。","sentenceOrder":93},
  {"id":"s_work_han_thu_53_94","chapterId":"ch_work_han_thu_53","textTraditional":"二一０三頁　五行　言其強（直）〔質〕如木石然。　景祐、殿本都作「質」。","sentenceOrder":94},
  {"id":"s_work_han_thu_54_1","chapterId":"ch_work_han_thu_54","textTraditional":"酈食其，陳留高陽人也。〔一〕好讀書，家貧落魄，無衣食業。〔二〕為里監門，然吏縣中賢豪不敢役，〔三〕皆謂之狂生。","sentenceOrder":1},
  {"id":"s_work_han_thu_54_2","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「食音異。其音基。」","sentenceOrder":2},
  {"id":"s_work_han_thu_54_3","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　鄭氏曰：「魄音薄。」應劭曰：「志行衰惡之貌也。」師古曰：「落魄，失業無次也。鄭音是。」","sentenceOrder":3},
  {"id":"s_work_han_thu_54_4","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「吏及賢者豪者皆不敢使役食其。」","sentenceOrder":4},
  {"id":"s_work_han_thu_54_5","chapterId":"ch_work_han_thu_54","textTraditional":"及陳勝、項梁等起，諸將徇地過高陽者數十人，〔一〕食其聞其將皆握齱好荷禮〔二〕自用，不能聽大度之言，食其乃自匿。後聞沛公略地陳留郊，沛公麾下騎士適食其里中子，〔三〕沛公時時問邑中賢豪。騎士歸，食其見，謂曰：「吾聞沛公嫚易人，有大略，此真吾所願從游，莫為我先。〔四〕若見沛公，〔五〕謂曰『臣里中有酈生，年六十餘，長八尺，人皆謂之狂生』，自謂我非狂。」騎士曰：「沛公不喜儒，〔六〕諸客冠儒冠來者，沛公輒解其冠，溺其中。〔七〕與人言，常大罵。未可以儒生說也。」食其曰：「第言之。」〔八〕騎士從容言食其所戒者。〔九〕","sentenceOrder":5},
  {"id":"s_work_han_thu_54_6","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「徇亦略也，音辭峻反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_54_7","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　應劭曰：「握齱，急促之貌。」師古曰：「荷與苛同。苛，細也。齱音初角反。」","sentenceOrder":7},
  {"id":"s_work_han_thu_54_8","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　服虔曰：「食其里中子適會作沛公騎士。」","sentenceOrder":8},
  {"id":"s_work_han_thu_54_9","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　師古曰：「先謂紹介也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_54_10","chapterId":"ch_work_han_thu_54","textTraditional":"〔五〕　師古曰：「若，汝也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_54_11","chapterId":"ch_work_han_thu_54","textTraditional":"〔六〕　師古曰：「喜，好也，音許吏反。」","sentenceOrder":11},
  {"id":"s_work_han_thu_54_12","chapterId":"ch_work_han_thu_54","textTraditional":"〔七〕　師古曰：「溺讀曰尿，音乃釣反。」","sentenceOrder":12},
  {"id":"s_work_han_thu_54_13","chapterId":"ch_work_han_thu_54","textTraditional":"〔八〕　師古曰：「第，但也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_54_14","chapterId":"ch_work_han_thu_54","textTraditional":"〔九〕　師古曰：「從音千容反。」","sentenceOrder":14},
  {"id":"s_work_han_thu_54_15","chapterId":"ch_work_han_thu_54","textTraditional":"沛公至高陽傳舍，〔一〕使人召食其。食其至，入謁，沛公方踞床令兩女子洗，〔二〕而見食其。食其入，即長揖不拜，曰：「足下欲助秦攻諸侯乎？欲率諸侯（攻）〔破〕秦乎？」沛公罵曰：「豎儒！〔三〕夫天下同苦秦久矣，故諸侯相率攻秦，何謂助秦？」食其曰：「必欲聚徒合義兵誅無道秦，不宜踞見長者。」於是沛公輟洗，起衣，〔四〕延食其上坐，謝之。食其因言六國從衡時。〔五〕沛公喜，賜食其食，問曰：「計安出？」食其曰：「足下起瓦合之卒，〔六〕收散亂之兵，不滿萬人，欲以徑入彊秦，此所謂探虎口者也。夫陳留，天下之衝，四通五達之郊也，〔七〕今其城中又多積粟。臣知其令，〔八〕今請使，令下足下。〔九〕即不聽，足下舉兵攻之，臣為內應。」於是遣食其往，沛公引〔兵〕隨之，遂下陳留。號食其為廣野君。","sentenceOrder":15},
  {"id":"s_work_han_thu_54_16","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「傳舍者，人所止息，前人已去，後人復來，轉相傳也。一音張戀反，謂傳置之舍也，其義兩通。它皆類此。」","sentenceOrder":16},
  {"id":"s_work_han_thu_54_17","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「洗足也，音先典反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_54_18","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「言其賤劣如僮豎。」","sentenceOrder":18},
  {"id":"s_work_han_thu_54_19","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　師古曰：「輟，止也。起衣，著衣也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_54_20","chapterId":"ch_work_han_thu_54","textTraditional":"〔五〕　師古曰：「從音子容反。衡，橫也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_54_21","chapterId":"ch_work_han_thu_54","textTraditional":"〔六〕　師古曰：「瓦合，謂如破瓦之相合，雖曰聚合而不齊同。」","sentenceOrder":21},
  {"id":"s_work_han_thu_54_22","chapterId":"ch_work_han_thu_54","textTraditional":"〔七〕　如淳曰：「四面往來通之，并數中央，凡五達也。」臣瓚曰：「四通五達，言無險阻也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_54_23","chapterId":"ch_work_han_thu_54","textTraditional":"〔八〕　師古曰：「素與其縣令相知。」","sentenceOrder":23},
  {"id":"s_work_han_thu_54_24","chapterId":"ch_work_han_thu_54","textTraditional":"〔九〕　師古曰：「下，降也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_54_25","chapterId":"ch_work_han_thu_54","textTraditional":"食其言弟商，使將數千人從沛公西南略地。食其（嘗）〔常〕為說客，馳使諸侯。","sentenceOrder":25},
  {"id":"s_work_han_thu_54_26","chapterId":"ch_work_han_thu_54","textTraditional":"漢三年秋，項羽擊漢，拔滎陽，漢兵遁保鞏。楚人聞韓信破趙，彭越數反梁地，則分兵救之。〔一〕韓信方東擊齊，漢王數困滎陽、成皋，計欲捐成皋以東，屯鞏、雒以距楚。食其因曰：「臣聞之，知天之天者，王事可成；不知天之天者，王事不可成。王者以民為天，而民以食為天。夫敖倉，天下轉輸久矣，臣聞其下乃有臧粟甚多。楚人拔滎陽，不堅守敖倉，乃引而東，令適卒分守成皋，〔二〕此乃天所以資漢。方今楚易取而漢反卻，自奪便，〔三〕臣竊以為過矣。且兩雄不俱立，楚漢久相持不決，百姓騷動，海內搖蕩，農夫釋耒，紅女下機，〔四〕天下之心未有所定也。願足下急復進兵，收取滎陽，據敖庾之粟，〔五〕塞成皋之險，杜太行之道，〔六〕距飛狐之口，〔七〕守白馬之津，以示諸侯形制之勢，〔八〕則天下知所歸矣。方今燕、趙已定，唯齊未下。今田廣據千里之齊，田間將二十萬之眾軍於歷城，諸田宗彊，負海岱，阻河濟，〔九〕南近楚，齊人多變詐，足下雖遣數十萬師，未可以歲月破也。臣請得奉明詔說齊王使為漢而稱東藩。」上曰：「善。」","sentenceOrder":26},
  {"id":"s_work_han_thu_54_27","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「（反）〔救〕趙及梁。」","sentenceOrder":27},
  {"id":"s_work_han_thu_54_28","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「適讀曰謫。謫卒謂卒之有罪謫者，即所謂謫戍。」","sentenceOrder":28},
  {"id":"s_work_han_thu_54_29","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「不圖進取，是為自奪便利也。卻音丘略反。」","sentenceOrder":29},
  {"id":"s_work_han_thu_54_30","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　師古曰：「耒，手耕曲木也，音盧對反。紅讀曰工。」","sentenceOrder":30},
  {"id":"s_work_han_thu_54_31","chapterId":"ch_work_han_thu_54","textTraditional":"〔五〕　師古曰：「敖庾即敖倉。」","sentenceOrder":31},
  {"id":"s_work_han_thu_54_32","chapterId":"ch_work_han_thu_54","textTraditional":"〔六〕　師古曰：「太行，山名，在河內野王之北，上黨之南。行音胡剛反。」","sentenceOrder":32},
  {"id":"s_work_han_thu_54_33","chapterId":"ch_work_han_thu_54","textTraditional":"〔七〕　如淳曰：「上黨壺關也。」臣瓚曰：「飛狐在代郡西南。」師古曰：「瓚說是。壺關無飛狐之名。」","sentenceOrder":33},
  {"id":"s_work_han_thu_54_34","chapterId":"ch_work_han_thu_54","textTraditional":"〔八〕　師古曰：「以地形而制服。」","sentenceOrder":34},
  {"id":"s_work_han_thu_54_35","chapterId":"ch_work_han_thu_54","textTraditional":"〔九〕　師古曰：「負，背也。岱，泰山也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_54_36","chapterId":"ch_work_han_thu_54","textTraditional":"乃從其畫，復守敖倉，而使食其說齊王，曰：「王知天下之所歸乎？」曰：「不知也。」曰：「知天下之所歸，則齊國可得而有也；若不知天下之所歸，即齊國未可保也。」齊王曰：「天下何歸？」食其曰：「天下歸漢。」齊王曰：「先生何以言之？」曰：「漢王與項王戮力西面擊秦，約先入咸陽者王之，項王背約不與，而王之漢中。項王遷殺義帝，漢王起蜀漢之兵擊三秦，出關而責義帝之負處，收天下之兵，立諸侯之後。降城即以侯其將，得賂則以分其士，與天下同其利，豪英賢材皆樂為之用。諸侯之兵四面而至，蜀漢之粟方船而下。〔一〕項王有背約之名，殺義帝之負；於人之功無所記，於人之罪無所忘；〔二〕戰勝而不得其賞，拔城而不得其封；非項氏莫得用事；〔三〕為人刻印，玩而不能授；〔四〕攻城得賂，積財而不能賞。天下畔之，賢材怨之，而莫為之用。故天下之士歸於漢王，可坐而策也。夫漢王發蜀漢，定三秦；涉西河之外，援上黨之兵；〔五〕下井陘，誅成安君；破北魏，〔六〕舉三十二城：此黃帝之兵，非人之力，天之福也。今已據敖庾之粟，塞成皋之險，守白馬之津，杜太行之阨，距飛狐之口，天下後服者先亡矣。王疾下漢王，齊國杜稷可得而保也；不下漢王，危亡可立而待也。」田廣以為然，乃聽食其，罷歷下兵守戰備，與食其日縱酒。〔七〕","sentenceOrder":36},
  {"id":"s_work_han_thu_54_37","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「方，併也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_54_38","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「言項羽吝爵賞而念舊惡。」","sentenceOrder":38},
  {"id":"s_work_han_thu_54_39","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「言唯任同姓之親。」","sentenceOrder":39},
  {"id":"s_work_han_thu_54_40","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　孟康曰：「刻斷無復廉鍔也。」臣瓚曰：「項羽吝於爵賞，玩惜侯印，不能以封人。」師古曰：「韓信傳作刓，此作玩，其義各通。孟說非也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_54_41","chapterId":"ch_work_han_thu_54","textTraditional":"〔五〕　師古曰：「援，引也，音爰。」","sentenceOrder":41},
  {"id":"s_work_han_thu_54_42","chapterId":"ch_work_han_thu_54","textTraditional":"〔六〕　師古曰：「謂魏豹也。梁地既有魏名，故謂此為北。」","sentenceOrder":42},
  {"id":"s_work_han_thu_54_43","chapterId":"ch_work_han_thu_54","textTraditional":"〔七〕　師古曰：「日日縱意而飲酒。」","sentenceOrder":43},
  {"id":"s_work_han_thu_54_44","chapterId":"ch_work_han_thu_54","textTraditional":"韓信聞食其馮軾下齊七十餘城，〔一〕乃夜度兵平原襲齊。齊王田廣聞漢兵至，以為食其賣己，〔二〕乃亨食其，引兵走。","sentenceOrder":44},
  {"id":"s_work_han_thu_54_45","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「馮讀曰憑。憑，據也。軾，車前橫板隆起者也。云憑軾者，言但安坐乘車而游說，不用兵眾。」","sentenceOrder":45},
  {"id":"s_work_han_thu_54_46","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「言其與韓信通謀。」","sentenceOrder":46},
  {"id":"s_work_han_thu_54_47","chapterId":"ch_work_han_thu_54","textTraditional":"漢十二年，曲周侯酈商以丞相將兵擊黥布，有功。高祖舉功臣，思食其。食其子疥〔一〕數將兵，上以其父故，封疥為高梁侯。後更食武陽，卒，子遂嗣。三世，侯平有罪，國除。","sentenceOrder":47},
  {"id":"s_work_han_thu_54_48","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「疥音介。」","sentenceOrder":48},
  {"id":"s_work_han_thu_54_49","chapterId":"ch_work_han_thu_54","textTraditional":"陸賈，楚人也。以客從高祖定天下，名有口辯，〔一〕居左右，常使諸侯。","sentenceOrder":49},
  {"id":"s_work_han_thu_54_50","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「時人皆謂其口辯。」","sentenceOrder":50},
  {"id":"s_work_han_thu_54_51","chapterId":"ch_work_han_thu_54","textTraditional":"時中國初定，尉佗平南越，因王之。〔一〕高祖使賈賜佗印為南越王。賈至，尉佗魋結箕踞見賈。〔二〕賈因說佗曰：「足下中國人，親戚昆弟墳墓在真定。今足下反天性，棄冠帶，〔三〕欲以區區之越與天子（伉）〔抗〕衡為敵國，〔四〕禍且及身矣。夫秦失其正，諸侯豪桀並起，〔五〕唯漢王先入關，據咸陽。項籍背約，自立為西楚霸王，諸侯皆屬，可謂至彊矣。然漢王起巴蜀，鞭笞天下，劫諸侯，遂誅項羽。五年之間，海內平定，此非人力，天之所建也。天子聞君王王南越，而不助天下誅暴逆，將相欲移兵而誅王，天子憐百姓新勞苦，且休之，遣臣授君王印，剖符通使。君王宜郊迎，北面稱臣，〔六〕乃欲以新造未集之越〔七〕屈強於此。〔八〕漢誠聞之，掘燒君王先人（家）〔冢〕墓，夷種宗族，〔九〕使一偏將將十萬眾臨越，即越殺王降漢，如反覆手耳。」〔一０〕","sentenceOrder":51},
  {"id":"s_work_han_thu_54_52","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「佗音徒河反。」","sentenceOrder":52},
  {"id":"s_work_han_thu_54_53","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　服虔曰：「魋音椎，今兵士椎頭髻也。」師古曰：「結讀曰髻。椎髻者。一撮之髻，其形如椎。箕踞，謂伸其兩腳而坐。亦曰箕踞其形似箕。」","sentenceOrder":53},
  {"id":"s_work_han_thu_54_54","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「偝父母之國，無骨肉之恩，是反天性也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_54_55","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　師古曰：「區區，小貌。」","sentenceOrder":55},
  {"id":"s_work_han_thu_54_56","chapterId":"ch_work_han_thu_54","textTraditional":"〔五〕　師古曰：「正亦政也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_54_57","chapterId":"ch_work_han_thu_54","textTraditional":"〔六〕　師古曰：「郊迎，謂出郊而迎。」","sentenceOrder":57},
  {"id":"s_work_han_thu_54_58","chapterId":"ch_work_han_thu_54","textTraditional":"〔七〕　師古曰：「集猶成也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_54_59","chapterId":"ch_work_han_thu_54","textTraditional":"〔八〕　師古曰：「屈音其勿反。屈強，謂不柔服也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_54_60","chapterId":"ch_work_han_thu_54","textTraditional":"〔九〕　師古曰：「夷，平也，謂平除其種族。」","sentenceOrder":60},
  {"id":"s_work_han_thu_54_61","chapterId":"ch_work_han_thu_54","textTraditional":"〔一０〕師古曰：「言其易。」","sentenceOrder":61},
  {"id":"s_work_han_thu_54_62","chapterId":"ch_work_han_thu_54","textTraditional":"於是佗乃蹶然起坐，〔一〕謝賈曰：「居蠻夷中久，殊失禮義。」因問賈曰：「我孰與蕭何、曹參、韓信賢？」〔二〕賈曰：「王似賢也。」復問曰：「我孰與皇帝賢？」賈曰：「皇帝起豐沛，討暴秦，誅彊楚，為天下興利除害，繼五帝三王之業，統天下，理中國。中國之人以億計，地方萬里，居天下之膏腴，人眾車輿，萬物殷富，政由一家，自天地剖判未始有也。〔三〕今王眾不過數萬，皆蠻夷，崎嶇山海間，〔四〕譬如漢一郡，王何乃比於漢！」佗大笑曰：「吾不起中國，故王此。使我居中國，何遽不若漢？」〔五〕乃大說賈〔六〕，留與飲數月。曰：「越中無足與語，至生來，令我日聞所不聞。」〔七〕賜賈橐中裝直千金，〔八〕它送亦千金。〔九〕賈卒拜佗為南越王，令稱臣奉漢約。歸報，高帝大說，〔一０〕拜賈為太中大夫。","sentenceOrder":62},
  {"id":"s_work_han_thu_54_63","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「蹶然，驚起之貌也，音厥。」","sentenceOrder":63},
  {"id":"s_work_han_thu_54_64","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「與，如也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_54_65","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「言自開闢以來未嘗有也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_54_66","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　師古曰：「崎音丘宜反，嶇音區。」","sentenceOrder":66},
  {"id":"s_work_han_thu_54_67","chapterId":"ch_work_han_thu_54","textTraditional":"〔五〕　師古曰：「言有何迫促而不如漢也。遽音其庶反。」","sentenceOrder":67},
  {"id":"s_work_han_thu_54_68","chapterId":"ch_work_han_thu_54","textTraditional":"〔六〕　師古曰：「說讀曰悅，謂愛悅之。」","sentenceOrder":68},
  {"id":"s_work_han_thu_54_69","chapterId":"ch_work_han_thu_54","textTraditional":"〔七〕　師古曰：「言素所不聞者，日聞之。」","sentenceOrder":69},
  {"id":"s_work_han_thu_54_70","chapterId":"ch_work_han_thu_54","textTraditional":"〔八〕　張晏曰：「珠玉之寶也。裝，裹也。」如淳曰：「明月珠之屬也。」師古曰：「有底曰囊，無底曰橐。言其寶物質輕而價重，可入囊橐以齎行，故曰橐中裝也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_54_71","chapterId":"ch_work_han_thu_54","textTraditional":"〔九〕　（師古）〔蘇林〕曰：「非橐中物，故曰它送也。」師古曰：「它猶餘也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_54_72","chapterId":"ch_work_han_thu_54","textTraditional":"〔一０〕師古曰：「說讀曰悅。」","sentenceOrder":72},
  {"id":"s_work_han_thu_54_73","chapterId":"ch_work_han_thu_54","textTraditional":"賈時時前說稱詩書。高帝罵之曰：「乃公居馬上得之，安事詩書！」賈曰：「馬上得之，寧可以馬上治乎？且湯武逆取而以順守之，文武並用，長久之術也。昔者吳王夫差、智伯極武而亡；〔一〕秦任刑法不變，卒滅趙氏。〔二〕鄉使秦以并天下，行仁義，法先聖，陛下安得而有之？」〔三〕高帝不懌，〔四〕有慚色，謂賈曰：「試為我著秦所以失天下，吾所以得之者，〔五〕及古成敗之國。」賈凡著十二篇。每奏一篇，高帝未嘗不稱善，左右呼萬歲，稱其書曰新語。〔六〕","sentenceOrder":73},
  {"id":"s_work_han_thu_54_74","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「夫差，吳王闔閭子也，好用兵，卒為越所滅。智伯，晉卿荀瑤也，貪而好勝，率韓、魏共攻趙襄子，襄子與韓、魏約，反而喪之。夫音扶。差音楚宜反。」","sentenceOrder":74},
  {"id":"s_work_han_thu_54_75","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　鄭氏曰：「秦之先造父封於趙城，其後以為（信）〔姓〕。」張晏曰：「雍襄王為質於趙，還為太子，遂稱趙氏。」師古曰：「據秦本紀，鄭說是。」","sentenceOrder":75},
  {"id":"s_work_han_thu_54_76","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「鄉讀曰嚮。安，焉也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_54_77","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　師古曰：「懌，和樂也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_54_78","chapterId":"ch_work_han_thu_54","textTraditional":"〔五〕　師古曰：「著，明也，謂作書明言（也）〔之〕。」","sentenceOrder":78},
  {"id":"s_work_han_thu_54_79","chapterId":"ch_work_han_thu_54","textTraditional":"〔六〕　師古曰：「其書今見存。」","sentenceOrder":79},
  {"id":"s_work_han_thu_54_80","chapterId":"ch_work_han_thu_54","textTraditional":"孝惠時，呂太后用事，欲王諸呂，畏大臣及有口者。〔一〕賈自度不能爭之，〔二〕乃病免。以好畤田地善，往家焉。〔三〕有五男，乃出所使越橐中裝，賣千金，分其子，子二百金，令為生產。賈常乘安車駟馬，從歌鼓瑟侍者十人，寶劍直百金，謂其子曰：「與女約：過女，女給人馬酒食極（飲）〔欲〕，十日而更。〔四〕所死家，得寶劍車騎侍從者。一歲中以往來過它客，率不過再過，〔五〕數擊鮮，毋久溷女為也。」〔六〕","sentenceOrder":80},
  {"id":"s_work_han_thu_54_81","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「有口謂辯士。」","sentenceOrder":81},
  {"id":"s_work_han_thu_54_82","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「度音徒各反。」","sentenceOrder":82},
  {"id":"s_work_han_thu_54_83","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「好畤即今雍州好畤縣。」","sentenceOrder":83},
  {"id":"s_work_han_thu_54_84","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　師古曰：「又改向一子處。」","sentenceOrder":84},
  {"id":"s_work_han_thu_54_85","chapterId":"ch_work_han_thu_54","textTraditional":"〔五〕　師古曰：「非徒至諸子所，又往來經過它處為賓客，率計一歲之中，每子不過再過至也。上過音工禾反。」","sentenceOrder":85},
  {"id":"s_work_han_thu_54_86","chapterId":"ch_work_han_thu_54","textTraditional":"〔六〕　服虔曰：「溷，辱也。吾常行，數擊新美食，不久辱汝也。」師古曰：「鮮謂新殺之肉也。溷，亂也。言我至之時，汝宜數數擊殺牲牢，與我鮮食，我不久住，亂累汝也。數音所角反。溷音下困反。」","sentenceOrder":86},
  {"id":"s_work_han_thu_54_87","chapterId":"ch_work_han_thu_54","textTraditional":"呂太后時，王諸呂，諸呂擅權，欲劫少主，危劉氏。右丞相陳平患之，力不能爭，恐禍及己。平（嘗）〔常〕燕居深念。〔一〕賈往，不請，直入坐，〔二〕陳平方念，不見賈。〔三〕賈曰：「何念深也？」平曰：「生揣我何念？」〔四〕賈曰：「足下位為上相，食三萬戶侯，可謂極富貴無欲矣。然有憂念，不過患諸呂、少主耳。」陳平曰：「然。為之奈何？」賈曰：「天下安，注意相；天下危，注意將。將相和，則士豫附；〔五〕士豫附，天下雖有變，則權不分。權不分，為社稷計，在兩君掌握耳。臣常欲謂太尉絳侯，〔六〕絳侯與我戲，易吾言。〔七〕君何不交驩太尉，深相結？」為陳平畫呂氏數事。平用其計，乃以五百金為絳侯壽，厚具樂飲太尉，〔八〕太尉亦報如之。兩人深相結，呂氏謀益壞。陳平乃以奴婢百人，車馬五十乘，錢五百萬，遺賈為食飲費。賈以此游漢廷公卿間，〔九〕名聲籍甚。〔一０〕及誅呂氏，立孝文，賈頗有力。","sentenceOrder":87},
  {"id":"s_work_han_thu_54_88","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「念，思也。以國家不安，故靜居獨慮，思其方策。」","sentenceOrder":88},
  {"id":"s_work_han_thu_54_89","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「言不因門人將命，而徑入自坐。」","sentenceOrder":89},
  {"id":"s_work_han_thu_54_90","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「思慮之際，故不覺賈至。」","sentenceOrder":90},
  {"id":"s_work_han_thu_54_91","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　孟康曰：「揣，度也。」韋昭曰：「揣音初委反。」","sentenceOrder":91},
  {"id":"s_work_han_thu_54_92","chapterId":"ch_work_han_thu_54","textTraditional":"〔五〕　師古曰：「豫，素也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_54_93","chapterId":"ch_work_han_thu_54","textTraditional":"〔六〕　師古曰：「謂者，與之言。」","sentenceOrder":93},
  {"id":"s_work_han_thu_54_94","chapterId":"ch_work_han_thu_54","textTraditional":"〔七〕　師古曰：「言絳侯與我相戲狎，輕易其言耳。」","sentenceOrder":94},
  {"id":"s_work_han_thu_54_95","chapterId":"ch_work_han_thu_54","textTraditional":"〔八〕　師古曰：「厚為（其）〔共〕具，而與太尉樂飲。」","sentenceOrder":95},
  {"id":"s_work_han_thu_54_96","chapterId":"ch_work_han_thu_54","textTraditional":"〔九〕　師古曰：「廷謂朝廷。」","sentenceOrder":96},
  {"id":"s_work_han_thu_54_97","chapterId":"ch_work_han_thu_54","textTraditional":"〔一０〕孟康曰：「言狼籍（之）〔甚〕盛。」","sentenceOrder":97},
  {"id":"s_work_han_thu_54_98","chapterId":"ch_work_han_thu_54","textTraditional":"孝文即位，欲使人之南越，丞相平乃言賈為太中大夫，往使尉佗，去黃屋稱制，〔一〕令比諸侯，皆如意指。語在南越傳。陸生竟以壽終。","sentenceOrder":98},
  {"id":"s_work_han_thu_54_99","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「黃屋，謂車上之蓋也。黃屋及稱制，皆天子之儀，故令去之。」","sentenceOrder":99},
  {"id":"s_work_han_thu_54_100","chapterId":"ch_work_han_thu_54","textTraditional":"朱建，楚人也。故嘗為淮南王黥布相，有罪去，後復事布。布欲反時，問建，建諫止之。布不聽，聽梁父侯，遂反。〔一〕漢既誅布，聞建諫之，高祖賜建號平原君，家徙長安。","sentenceOrder":100},
  {"id":"s_work_han_thu_54_101","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　如淳曰：「遂者，布臣也。」臣瓚曰：「布用梁甫侯之計而遂反。」師古曰：「瓚說是也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_54_102","chapterId":"ch_work_han_thu_54","textTraditional":"為人辯有口，刻廉剛直，行不苟合，義不取容。辟陽侯行不正，得幸呂太后，〔一〕欲知建，〔二〕建不肯見。及建母死，貧未有以發喪，方假貣服具。〔三〕陸賈素與建善，乃見辟陽侯，賀曰：「平原君母死。」〔辟陽侯曰：「平原君母死〕，何乃賀我？」陸生曰：「前日君侯欲知平原君，平原君義不知君，以其母故。〔四〕今其母死，君誠厚送喪，則彼為君死矣。」辟陽侯乃奉百金裞，〔五〕列侯貴人以辟陽侯故，往賻凡五百金。〔六〕","sentenceOrder":102},
  {"id":"s_work_han_thu_54_103","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「審食其。」","sentenceOrder":103},
  {"id":"s_work_han_thu_54_104","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「欲與相知。」","sentenceOrder":104},
  {"id":"s_work_han_thu_54_105","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「貣音土得反。」","sentenceOrder":105},
  {"id":"s_work_han_thu_54_106","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　張晏曰：「相知當同恤災危，以母在，故義不知君也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_54_107","chapterId":"ch_work_han_thu_54","textTraditional":"〔五〕　師古曰：「贈終者之衣被曰裞。言以百金為衣被之具。裞音式芮反，其字從衣。」","sentenceOrder":107},
  {"id":"s_work_han_thu_54_108","chapterId":"ch_work_han_thu_54","textTraditional":"〔六〕　師古曰：「布帛曰賻。」","sentenceOrder":108},
  {"id":"s_work_han_thu_54_109","chapterId":"ch_work_han_thu_54","textTraditional":"久之，人或毀辟陽侯，惠帝大怒，下吏，欲誅之。太后慚，不可言。〔一〕大臣多害辟陽侯行，欲遂誅之。辟陽侯困急，使人欲見建。建辭曰：「獄急，不敢見君。」建乃求見孝惠幸臣閎籍孺，〔二〕說曰：「君所以得幸帝，天下莫不聞。〔三〕今辟陽侯幸太后而下吏，〔四〕道路皆言君讒，欲殺之。今日辟陽侯誅，旦日太后含怒，亦誅君。君何不肉袒為辟陽侯言帝？〔五〕帝聽君出辟陽侯，太后大驩。兩主俱幸君，君富貴益倍矣。」於是閎籍孺大恐，從其計，言帝，帝果出辟陽侯。辟陽侯之囚，欲見建，建不見，辟陽侯以為背之，大怒。及其成功出之，大驚。","sentenceOrder":109},
  {"id":"s_work_han_thu_54_110","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「不可自言之。」","sentenceOrder":110},
  {"id":"s_work_han_thu_54_111","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「佞幸傳云高祖時則有籍孺，孝惠有閎孺，斯則二人皆名為孺，而姓各別。今此云閎籍孺，誤剩籍字，後人所妄加耳。」","sentenceOrder":111},
  {"id":"s_work_han_thu_54_112","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「言不以材德進。」","sentenceOrder":112},
  {"id":"s_work_han_thu_54_113","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　師古曰：「下音胡嫁反。它皆類此。」","sentenceOrder":113},
  {"id":"s_work_han_thu_54_114","chapterId":"ch_work_han_thu_54","textTraditional":"〔五〕　師古曰：「肉袒，謂脫其衣袖而見肉。肉袒者，自挫辱之甚，冀見哀憐。」","sentenceOrder":114},
  {"id":"s_work_han_thu_54_115","chapterId":"ch_work_han_thu_54","textTraditional":"呂太后崩，大臣誅諸呂，辟陽侯與諸呂至深，〔一〕卒不誅。計畫所以全者，皆陸生、平原君之力也。","sentenceOrder":115},
  {"id":"s_work_han_thu_54_116","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　如淳曰：「辟陽侯與諸呂相親信，為罪宜誅者至深也。」師古曰：「直言辟陽侯與諸呂相知，情義至深重耳。如說非也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_54_117","chapterId":"ch_work_han_thu_54","textTraditional":"孝文時，淮南厲王殺辟陽侯，以黨諸呂故。孝文聞其客朱建為其策，使吏捕欲治。聞吏至門，建欲自殺。諸子及吏皆曰：「事未可知，何自殺為？」建曰：「我死禍絕，不及乃身矣。」〔一〕遂自剄。文帝聞而惜之，曰：「吾無殺建意也。」乃召其子，拜為中大夫。使匈奴，單于無禮，罵單于，遂死匈奴中。","sentenceOrder":117},
  {"id":"s_work_han_thu_54_118","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「乃，汝也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_54_119","chapterId":"ch_work_han_thu_54","textTraditional":"婁敬，齊人也。漢五年，戍隴西，過雒陽，高帝在焉。敬脫輓輅，〔一〕見齊人虞將軍曰：「臣願見上言便宜。」虞將軍欲與鮮衣，敬曰：「臣衣帛，衣帛見，〔二〕衣褐，衣褐見，〔三〕不敢易衣。」虞將軍入言上，上召見，賜食。","sentenceOrder":119},
  {"id":"s_work_han_thu_54_120","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　蘇林曰：「輅音凍〈冫各〉之〈冫各〉。一木橫遮車前，二人挽之，一人推之。」孟康曰：「輅音胡格反。」師古曰：「二音同聲也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_54_121","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「衣，著也。帛謂繒也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_54_122","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「此褐謂織毛布之衣。」","sentenceOrder":122},
  {"id":"s_work_han_thu_54_123","chapterId":"ch_work_han_thu_54","textTraditional":"已而問敬，敬說曰：「陛下都雒陽，豈欲與周室比隆哉？」上曰：「然。」敬曰：「陛下取天下與周異。周之先自后稷，堯封之邰，〔一〕積德絫善十餘世。〔二〕公劉避桀居豳。大王以狄伐故，去豳，杖馬箠去居岐，〔三〕國人爭歸之。及文王為西伯，斷虞芮訟〔四〕，始受命，呂望、伯夷自海濱來歸之。〔五〕武王伐紂，不期而會孟津上八百諸侯，遂滅殷。成王即位，周公之屬傅相焉，乃營成周都雒，以為此天下中，〔六〕諸侯四方納貢職，道里鈞矣，有德則易以王，無德則易以亡。凡居此者，欲令務以德致人，不欲阻險，令後世驕奢以虐民也。及周之衰，分而為二，〔七〕天下莫朝周，周不能制。非德薄，形勢弱也。今陛下起豐沛，收卒三千人，以之徑往，卷蜀漢，定三秦，與項籍戰滎陽，大戰七十，小戰四十，使天下之民肝腦塗地，父子暴骸中野，不可勝數，哭泣之聲不絕，傷夷者未起，〔八〕而欲比隆成康之時，臣竊以為不侔矣。〔九〕且夫秦地被山帶河，四塞以為固，卒然有急，百萬之眾可具。〔一０〕因秦之故，資甚美膏腴之地，此所謂天府。〔一一〕陛下入關而都之，山東雖亂，秦故地可全而有也。夫與人鬥，不搤其亢，拊其背，未能全勝。〔一二〕今陛下入關而都，按秦之故，此亦搤天下之亢而拊其背也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_54_124","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「邰，邑名也，即今武功故城是其處，音吐材反。」","sentenceOrder":124},
  {"id":"s_work_han_thu_54_125","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「絫，古累字。」","sentenceOrder":125},
  {"id":"s_work_han_thu_54_126","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「箠，馬策也。杖謂柱之也。云杖馬箠者，以示無所攜持也。箠音止繠反。」","sentenceOrder":126},
  {"id":"s_work_han_thu_54_127","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　文穎曰：「二國爭田，見文王之德而自和也。」師古曰：「虞，今虞州是也。芮，今芮城縣是也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_54_128","chapterId":"ch_work_han_thu_54","textTraditional":"〔五〕　師古曰：「濱，涯也，音賓，又音頻。」","sentenceOrder":128},
  {"id":"s_work_han_thu_54_129","chapterId":"ch_work_han_thu_54","textTraditional":"〔六〕　師古曰：「中音竹仲反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_54_130","chapterId":"ch_work_han_thu_54","textTraditional":"〔七〕　師古曰：「謂東周君、西周君。」","sentenceOrder":130},
  {"id":"s_work_han_thu_54_131","chapterId":"ch_work_han_thu_54","textTraditional":"〔八〕　師古曰：「夷，創也，音痍。」","sentenceOrder":131},
  {"id":"s_work_han_thu_54_132","chapterId":"ch_work_han_thu_54","textTraditional":"〔九〕　師古曰：「侔，等也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_54_133","chapterId":"ch_work_han_thu_54","textTraditional":"〔一０〕師古曰：「卒讀曰猝。」","sentenceOrder":133},
  {"id":"s_work_han_thu_54_134","chapterId":"ch_work_han_thu_54","textTraditional":"〔一一〕　師古曰：「府，聚也，萬物所聚。」","sentenceOrder":134},
  {"id":"s_work_han_thu_54_135","chapterId":"ch_work_han_thu_54","textTraditional":"〔一二〕　張晏曰：「亢，喉嚨也。」師古曰：「搤與扼同，謂捉持之也。亢音岡，又音下郎反。」","sentenceOrder":135},
  {"id":"s_work_han_thu_54_136","chapterId":"ch_work_han_thu_54","textTraditional":"高帝問群臣，群臣皆山東人，爭言周王數百年，秦二世則亡，不如都周。上疑未能決。及留侯明言入關便，即日駕西都關中。","sentenceOrder":136},
  {"id":"s_work_han_thu_54_137","chapterId":"ch_work_han_thu_54","textTraditional":"於是上曰：「本言都秦地者婁敬，婁者劉也。」賜姓劉氏，拜為郎中，號曰奉春君。〔一〕","sentenceOrder":137},
  {"id":"s_work_han_thu_54_138","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　張晏曰：「春，歲之始，以其首勸都關中。」","sentenceOrder":138},
  {"id":"s_work_han_thu_54_139","chapterId":"ch_work_han_thu_54","textTraditional":"漢七年，韓王信反，高帝自往擊。至晉陽，聞信與匈欲擊漢，上大怒，使人使匈奴。匈奴匿其壯士肥牛馬，〔一〕徒見其老弱及羸畜。使者十輩來，皆言匈奴易擊。上使劉敬復往使匈奴，還報曰：「兩國相擊，此宜夸矜見所長。〔二〕今臣往，徒見羸胔老弱，〔三〕此必欲見短，伏奇兵以爭利。愚以為匈奴不可擊也。」是時漢兵以踰句注，三十餘萬眾，〔四〕兵已業行。上怒，罵敬曰：「齊虜！以舌得官，乃今妄言沮吾軍。」〔五〕械繫敬廣武。〔六〕遂往，至平城，匈奴果出奇兵圍高帝白登，七日然後得解。高帝至廣武，赦敬，曰：「吾不用公言，以困平城。吾已斬先使十輩言可擊者矣。」乃封敬二千戶，為關內侯，號建信侯。","sentenceOrder":139},
  {"id":"s_work_han_thu_54_140","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「匿，藏也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_54_141","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「見，示也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_54_142","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「胔音漬，謂（見）〔死〕者之肉也。一說胔讀曰瘠。瘠，瘦也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_54_143","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　師古曰：「句注，山名，在雁門。」","sentenceOrder":143},
  {"id":"s_work_han_thu_54_144","chapterId":"ch_work_han_thu_54","textTraditional":"〔五〕　師古曰：「沮謂止壞也，音材汝反。」","sentenceOrder":144},
  {"id":"s_work_han_thu_54_145","chapterId":"ch_work_han_thu_54","textTraditional":"〔六〕　師古曰：「械謂桎梏也。廣武，縣名，屬雁門。」","sentenceOrder":145},
  {"id":"s_work_han_thu_54_146","chapterId":"ch_work_han_thu_54","textTraditional":"高帝罷平城歸，韓王信亡入胡。當是時，冒頓單于兵彊，控弦四十萬騎，〔一〕數苦北邊。上患之，問敬。敬曰：「天下初定，士卒罷於兵革，〔二〕未可以武服也。冒頓殺父代立，妻群母，以力為威，未可以仁義說也。獨可以計久遠子孫為臣耳，然陛下恐不能為。」上曰：「誠可，何為不能！顧為奈何？」〔三〕敬曰：「陛下誠能以適長公主妻單于，〔四〕厚奉遺之，彼知漢女送厚，蠻夷必慕，以為閼氏，生子必為太子，代單于。何者？貪漢重幣。陛下以歲時漢所餘彼所鮮數問遺，〔五〕使辯士風諭以禮節。〔六〕冒頓在，固為子婿；死，外孫為單于。豈曾聞（外）孫敢與大父亢禮哉？可毋戰以漸臣也。若陛下不能遣長公主，而（今）〔令〕宗室及後宮詐稱公主，彼亦知不肯貴近，無益也。」〔七〕高帝曰：「善。」欲遣長公主。呂后泣曰：「妾唯以一太子、一女，〔八〕奈何棄之匈奴！」上竟不能遣長公主，而取家人子為公主，妻單于。〔九〕使敬往結和親約。","sentenceOrder":146},
  {"id":"s_work_han_thu_54_147","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「控，引也，謂皆引弓也，音口弄反。」","sentenceOrder":147},
  {"id":"s_work_han_thu_54_148","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「罷讀曰疲。」","sentenceOrder":148},
  {"id":"s_work_han_thu_54_149","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「顧，思念也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_54_150","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　師古曰：「適讀曰嫡，謂皇后所生。」","sentenceOrder":150},
  {"id":"s_work_han_thu_54_151","chapterId":"ch_work_han_thu_54","textTraditional":"〔五〕　師古曰：「鮮，少也。問遺，謂餉饋之也。鮮音息善反。遺音弋季反。」","sentenceOrder":151},
  {"id":"s_work_han_thu_54_152","chapterId":"ch_work_han_thu_54","textTraditional":"〔六〕　師古曰：「風讀曰諷。」","sentenceOrder":152},
  {"id":"s_work_han_thu_54_153","chapterId":"ch_work_han_thu_54","textTraditional":"〔七〕　師古曰：「近音其靳反。」","sentenceOrder":153},
  {"id":"s_work_han_thu_54_154","chapterId":"ch_work_han_thu_54","textTraditional":"〔八〕　師古曰：「言唯以此自慰。」","sentenceOrder":154},
  {"id":"s_work_han_thu_54_155","chapterId":"ch_work_han_thu_54","textTraditional":"〔九〕　師古曰：「於外庶人之家取女而名之為公主。」","sentenceOrder":155},
  {"id":"s_work_han_thu_54_156","chapterId":"ch_work_han_thu_54","textTraditional":"敬從匈奴來，因言「匈奴河南白羊、樓煩王，〔一〕去長安近者七百里，輕騎一日一夕可以至。〔二〕秦中新破，〔三〕少民，地肥饒，可益實。夫諸侯初起時，非齊諸田，楚昭、屈、景莫與。〔四〕今陛下雖都關中，實少人。北近胡寇，東有六國彊族，一日有變，陛下亦未得安枕而臥也。臣願陛下徙齊諸田，楚昭、屈、景，燕、趙、韓、魏後，及豪傑名家，且實關中。無事，可以備胡；諸侯有變，亦足率以東伐。此彊本弱末之術也。」上曰：「善。」乃使劉敬徙所言關中十餘萬口。〔五〕","sentenceOrder":156},
  {"id":"s_work_han_thu_54_157","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　張晏曰：「白羊，匈奴國名也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_54_158","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「言匈奴欲來為寇者。」","sentenceOrder":158},
  {"id":"s_work_han_thu_54_159","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「秦中謂關中，故秦地也。新破，謂經兵革之後未殷實。」","sentenceOrder":159},
  {"id":"s_work_han_thu_54_160","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　師古曰：「皆二國之王族。」","sentenceOrder":160},
  {"id":"s_work_han_thu_54_161","chapterId":"ch_work_han_thu_54","textTraditional":"〔五〕　師古曰：「今高陵、櫟陽諸田，華陰、好畤諸景，及三輔諸屈、諸懷尚多，皆此時所徙。」","sentenceOrder":161},
  {"id":"s_work_han_thu_54_162","chapterId":"ch_work_han_thu_54","textTraditional":"叔孫通，薛人也。〔一〕秦時以文學徵，待詔博士。〔二〕數歲，陳勝起，二世召博士諸儒生問曰：「楚戍卒攻蘄入陳，於公何如？」博士諸生三十餘人前曰：「人臣無將，將則反，罪死無赦。〔三〕願陛下急發兵擊之。」二世怒，作色。〔四〕通前曰：「諸生言皆非。夫天下為一家，毀郡縣城，鑠其兵，視天下弗復用。〔五〕且明主在上，法令具於下，吏人人奉職，四方輻輳，〔六〕安有反者！此特群盜鼠竊狗盜，〔七〕何足置齒牙間哉？郡守尉（令）〔今〕捕誅，何足憂？」二世喜，盡問諸生，諸生或言反，或言盜。於是二世令御史按諸生言反者下吏，非所宜言。諸生言盜者皆罷之。乃賜通帛二十疋，衣一襲，〔八〕拜為博士。通已出，反舍，〔九〕諸生曰：「生何言之諛也？」通曰：「公不知，我幾不免虎口！」〔一０〕乃亡去之薛，薛已降楚矣。","sentenceOrder":162},
  {"id":"s_work_han_thu_54_163","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　晉灼曰：「楚漢春秋名何。」師古曰：「薛，縣名，屬魯國。」","sentenceOrder":163},
  {"id":"s_work_han_thu_54_164","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「於博士中待詔。」","sentenceOrder":164},
  {"id":"s_work_han_thu_54_165","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　臣瓚曰：「將謂為逆亂也。」師古曰：「將有其意。」","sentenceOrder":165},
  {"id":"s_work_han_thu_54_166","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　師古曰：「不許其言陳勝為反。作色，謂變動其色。」","sentenceOrder":166},
  {"id":"s_work_han_thu_54_167","chapterId":"ch_work_han_thu_54","textTraditional":"〔五〕　師古曰：「鑠，銷也。視讀曰示。」","sentenceOrder":167},
  {"id":"s_work_han_thu_54_168","chapterId":"ch_work_han_thu_54","textTraditional":"〔六〕　師古曰：「輳，聚也，言如車輻之聚於轂也。字或作湊，並音千豆反。」","sentenceOrder":168},
  {"id":"s_work_han_thu_54_169","chapterId":"ch_work_han_thu_54","textTraditional":"〔七〕　師古曰：「如鼠之竊，如狗之盜。」","sentenceOrder":169},
  {"id":"s_work_han_thu_54_170","chapterId":"ch_work_han_thu_54","textTraditional":"〔八〕　師古曰：「一襲，上下皆具也，今人呼為一副也。」","sentenceOrder":170},
  {"id":"s_work_han_thu_54_171","chapterId":"ch_work_han_thu_54","textTraditional":"〔九〕　師古曰：「還其所居也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_54_172","chapterId":"ch_work_han_thu_54","textTraditional":"〔一０〕師古曰：「幾音鉅依反。」","sentenceOrder":172},
  {"id":"s_work_han_thu_54_173","chapterId":"ch_work_han_thu_54","textTraditional":"及項梁之薛，通從之。敗定陶，從懷王。懷王為義帝，徙長沙，通留事項王。漢二年，漢王從五諸侯入彭城，通降漢王。","sentenceOrder":173},
  {"id":"s_work_han_thu_54_174","chapterId":"ch_work_han_thu_54","textTraditional":"通儒服，漢王憎之，乃變其服，服短衣，楚製。〔一〕漢王喜。","sentenceOrder":174},
  {"id":"s_work_han_thu_54_175","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「製謂裁衣之形製。」","sentenceOrder":175},
  {"id":"s_work_han_thu_54_176","chapterId":"ch_work_han_thu_54","textTraditional":"通之降漢，從弟子百餘人，然無所進，剸言諸故群盜壯士進之。〔一〕弟子皆曰：「事先生數年，幸得從降漢，今不進臣等，剸言大猾，何也？」通乃謂曰：「漢王方蒙矢石爭天下，〔三〕諸生寧能鬥乎？故先言斬將搴旗之士。〔四〕諸生且待我，我不忘矣。」漢王拜通為博士，號稷嗣君。〔五〕","sentenceOrder":176},
  {"id":"s_work_han_thu_54_177","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「剸與專同，又音之兗反。此則言專聲之急上者耳。」","sentenceOrder":177},
  {"id":"s_work_han_thu_54_178","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「狡猾之人。」","sentenceOrder":178},
  {"id":"s_work_han_thu_54_179","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「蒙猶被也，冒也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_54_180","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　師古曰：「搴，拔取，音騫。」","sentenceOrder":180},
  {"id":"s_work_han_thu_54_181","chapterId":"ch_work_han_thu_54","textTraditional":"〔五〕　張晏曰：「后稷佐唐，欲令復如之。」","sentenceOrder":181},
  {"id":"s_work_han_thu_54_182","chapterId":"ch_work_han_thu_54","textTraditional":"漢王已并天下，諸侯共尊為皇帝於定陶，通就其儀號。〔一〕高帝悉去秦儀法，為簡易。群臣飲爭功，醉或妄呼，〔二〕拔劍擊柱，上患之。通知上益饜之，說上曰：「夫儒者難與進取，可與守成。臣願徵魯諸生，與臣弟子共起朝儀。」高帝曰：「得無難乎？」通曰：「五帝異樂，三王不同禮。禮者，因時世人情為之節文者也。故夏、殷、周禮所因損益可知者，謂不相復也。〔三〕臣願頗采古禮與秦儀雜就之。」上曰：「可試為之，令易知，度吾所能行為之。」〔四〕","sentenceOrder":182},
  {"id":"s_work_han_thu_54_183","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「就，成也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_54_184","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「呼音火故反。」","sentenceOrder":184},
  {"id":"s_work_han_thu_54_185","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「復，重也，因也，音扶目反。」","sentenceOrder":185},
  {"id":"s_work_han_thu_54_186","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　師古曰：「度音徒各反。」","sentenceOrder":186},
  {"id":"s_work_han_thu_54_187","chapterId":"ch_work_han_thu_54","textTraditional":"於是通使徵魯諸生三十餘人。〔一〕魯有兩生不肯行，曰：「公所事者且十主，皆面諛親貴。今天下初定，死者未葬，傷者未起，又欲起禮樂。禮樂所由起，百年積德而後可興也。〔二〕吾不忍為公所為。公所為不合古，吾不行。公往矣，毋污我！」通笑曰：「若真鄙儒，不知時變。」〔三〕","sentenceOrder":187},
  {"id":"s_work_han_thu_54_188","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「通為使者，而徵諸生。」","sentenceOrder":188},
  {"id":"s_work_han_thu_54_189","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「言（德行）〔行德〕教百年，然後可定禮樂也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_54_190","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「若，汝也。鄙，言不通。」","sentenceOrder":190},
  {"id":"s_work_han_thu_54_191","chapterId":"ch_work_han_thu_54","textTraditional":"遂與所徵三十人西，〔一〕及上左右為學者〔二〕與其弟子百餘人為綿蕞野外。〔三〕習之月餘，通曰：「上可試觀。」上使行禮，曰：「吾能為此。」乃令群臣習肄，〔四〕會十月。","sentenceOrder":191},
  {"id":"s_work_han_thu_54_192","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「西入關。」","sentenceOrder":192},
  {"id":"s_work_han_thu_54_193","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「左右，謂近臣也。為學，謂素有學術。」","sentenceOrder":193},
  {"id":"s_work_han_thu_54_194","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　應劭曰：「立竹及茅索營之，習禮儀其中也。」如淳曰：「謂以茅翦樹地，為纂位尊卑之次也。春秋傳曰『置茅蕝』。」師古曰：「蕞與蕝同，並音子悅反。如說是。」","sentenceOrder":194},
  {"id":"s_work_han_thu_54_195","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　師古曰：「肄亦習也，音弋二反。」","sentenceOrder":195},
  {"id":"s_work_han_thu_54_196","chapterId":"ch_work_han_thu_54","textTraditional":"漢七年，長樂宮成，諸侯群臣朝十月。〔一〕儀：〔二〕先平明，〔三〕謁者治禮，引以次入殿門，廷中陳車騎戍卒衛官，設兵，張旗志。〔四〕傳曰「趨」。〔五〕殿下郎中俠陛，陛數百人。〔六〕功臣列侯諸將軍軍吏以次陳西方，東鄉；文官丞相以下陳東方，西鄉。〔七〕大行設九賓，臚句傳。〔八〕於是皇帝輦出房，百官執戟傳警，〔九〕引諸侯王以下至吏六百石以次奉賀。自諸侯王以下莫不震恐肅敬。至禮畢，盡伏，置法酒。〔一０〕諸侍坐殿上皆伏抑首〔一一〕，以尊卑次起上壽。觴九行，謁者言「罷酒」。御史執法舉不如儀者輒引去。竟朝置酒，無敢讙譁失禮者。於是高帝曰：「吾乃今日知為皇帝之貴也。」拜通為奉常，〔一二〕賜金五百斤。","sentenceOrder":196},
  {"id":"s_work_han_thu_54_197","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「適會七年十月，而長樂宮新成也。漢時尚以十月為正月，故行朝歲之禮，史家追書十月。」","sentenceOrder":197},
  {"id":"s_work_han_thu_54_198","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「欲敘其下儀法，先言儀如此也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_54_199","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「未平明之前。」","sentenceOrder":199},
  {"id":"s_work_han_thu_54_200","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　師古曰：「志與幟同，音式餌反。」","sentenceOrder":200},
  {"id":"s_work_han_thu_54_201","chapterId":"ch_work_han_thu_54","textTraditional":"〔五〕　師古曰：「傳聲教入者皆令趨，謂疾行為敬也。」","sentenceOrder":201},
  {"id":"s_work_han_thu_54_202","chapterId":"ch_work_han_thu_54","textTraditional":"〔六〕　師古曰：「俠與挾同。挾其兩旁，每陛皆數百人也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_54_203","chapterId":"ch_work_han_thu_54","textTraditional":"〔七〕　師古曰：「鄉皆讀曰嚮。」","sentenceOrder":203},
  {"id":"s_work_han_thu_54_204","chapterId":"ch_work_han_thu_54","textTraditional":"〔八〕　蘇林曰：「上傳語告下為臚，下告上為句也。」韋昭曰：「大行掌賓客之禮，今之鴻臚也。九賓則周禮九儀也。謂公、侯、伯、子、男、孤、卿、大夫、士也。」師古曰：「臚音廬。」","sentenceOrder":204},
  {"id":"s_work_han_thu_54_205","chapterId":"ch_work_han_thu_54","textTraditional":"〔九〕　師古曰：「傳聲而唱警。」","sentenceOrder":205},
  {"id":"s_work_han_thu_54_206","chapterId":"ch_work_han_thu_54","textTraditional":"〔一０〕師古曰：「法酒者，猶言禮酌，謂不飲之至醉。」","sentenceOrder":206},
  {"id":"s_work_han_thu_54_207","chapterId":"ch_work_han_thu_54","textTraditional":"〔一一〕師古曰：「抑，屈也。謂依禮法不敢平坐而視。」","sentenceOrder":207},
  {"id":"s_work_han_thu_54_208","chapterId":"ch_work_han_thu_54","textTraditional":"〔一二〕師古曰：「解在百官公卿表。後改為太常也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_54_209","chapterId":"ch_work_han_thu_54","textTraditional":"通因進曰：「諸弟子儒生隨臣久矣，與共為儀，願陛下官之。」高帝悉以為郎。通出，皆以五百金賜諸生。諸生乃喜曰：「叔孫生聖人，知當世務。」","sentenceOrder":209},
  {"id":"s_work_han_thu_54_210","chapterId":"ch_work_han_thu_54","textTraditional":"九年，高帝徙通為太子太傅。十二年，高帝欲以趙王如意易太子，通諫曰：「昔者晉獻公以驪姬故，廢太子，立奚齊，晉國亂者數十年，為天下笑。秦以不早定扶蘇，胡亥詐立，自使滅祀，此陛下所親見。今太子仁孝，天下皆聞之；呂后與陛下（共）〔攻〕苦食啖〔一〕，其可背哉！陛下必欲廢適而立少，〔二〕臣願先伏誅，以頸血汙地。」高帝曰：「公罷矣，吾特戲耳。」〔三〕通曰：「太子天下本，本壹搖天下震動，奈何以天下戲！」高帝曰：「吾聽公。」及上置酒，見留侯所招客從太子入見，上遂無易太子志矣。","sentenceOrder":210},
  {"id":"s_work_han_thu_54_211","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　如淳曰：「食無菜茹為啖。」師古曰：「啖當作淡。淡謂無味之食也。言共攻擊勤苦之事，而食無味之食也。淡音大敢反。」","sentenceOrder":211},
  {"id":"s_work_han_thu_54_212","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「適讀曰嫡。」","sentenceOrder":212},
  {"id":"s_work_han_thu_54_213","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「特，但也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_54_214","chapterId":"ch_work_han_thu_54","textTraditional":"高帝崩，孝惠即位，乃謂通曰：「先帝園陵寢廟，群臣莫習。」徙通為奉常，〔一〕定宗廟儀法。及稍定漢諸儀法，皆通所論著也。惠帝為東朝長樂宮，〔二〕及間往，〔三〕數蹕煩民，〔四〕作復道，方築武庫南，〔五〕通奏事，因請間，〔六〕曰：「陛下何自築復道高帝寢，衣冠月出游高廟？〔七〕子孫奈何乘宗廟道（以）〔上〕行哉！」惠帝懼，曰：「急壞之。」通曰：「人主無過舉。〔八〕今已作，百姓皆知之矣。願陛下為原廟〔九〕渭北，衣冠月出游之，益廣宗廟，大孝之本。」上乃詔有司立原廟。","sentenceOrder":214},
  {"id":"s_work_han_thu_54_215","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「又重為之也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_54_216","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　孟康曰：「朝太后於長樂宮。」","sentenceOrder":216},
  {"id":"s_work_han_thu_54_217","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「非大朝時，中間小謁見。」","sentenceOrder":217},
  {"id":"s_work_han_thu_54_218","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　孟康曰：「妨其往來也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_54_219","chapterId":"ch_work_han_thu_54","textTraditional":"〔五〕　如淳曰：「作復道，方始築武庫南也。」師古曰：「復音方目反。」","sentenceOrder":219},
  {"id":"s_work_han_thu_54_220","chapterId":"ch_work_han_thu_54","textTraditional":"〔六〕　師古曰：「請空隙之時，不欲對眾言之。」","sentenceOrder":220},
  {"id":"s_work_han_thu_54_221","chapterId":"ch_work_han_thu_54","textTraditional":"〔七〕　服虔曰：「持高廟中衣，月旦以游於眾廟，已而復之。」應劭曰：「月旦出高帝衣冠，備法駕，名曰游衣冠。」如淳曰：「高祖之衣冠藏在宮中之寢，三月出游，其道正值今之所作復道下，故言乘宗廟道上行也。」晉灼曰：「黃圖高廟在長安城門街東，寢在桂宮北。服言衣藏於廟中，如言宮中，皆非也。」師古曰：「諸家之說皆未允也。謂從高帝陵寢出衣冠，游於高廟，每月一為之，漢制則然。而後之學者不曉其意，謂以月出之時而夜游衣冠，失之遠也。」","sentenceOrder":221},
  {"id":"s_work_han_thu_54_222","chapterId":"ch_work_han_thu_54","textTraditional":"〔八〕　師古曰：「舉事不當有過失。」","sentenceOrder":222},
  {"id":"s_work_han_thu_54_223","chapterId":"ch_work_han_thu_54","textTraditional":"〔九〕　師古曰：「原，重也。先以有廟，今更立之，故云重也。」","sentenceOrder":223},
  {"id":"s_work_han_thu_54_224","chapterId":"ch_work_han_thu_54","textTraditional":"惠帝常出游離宮，通曰：「古者有春嘗菓，方今櫻桃孰，可獻，〔一〕願陛下出，因取櫻桃獻宗廟。」上許之。諸菓獻由此興。","sentenceOrder":224},
  {"id":"s_work_han_thu_54_225","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「禮記曰『仲春之月，羞以含桃，先薦寢廟』，即此櫻桃也。今所謂朱櫻者是也。櫻音於耕反。」","sentenceOrder":225},
  {"id":"s_work_han_thu_54_226","chapterId":"ch_work_han_thu_54","textTraditional":"贊曰：高祖以征伐定天下，而縉紳之徒騁其知辯，〔一〕並成大業。語曰「廊廟之材非一木之枝，帝王之功非一士之略」，〔二〕信哉！劉敬脫輓輅而建金城之安，叔孫通舍枹鼓而立一王之儀，〔三〕遇其時也。酈生自匿監門，待主然後出，猶不免鼎鑊。〔四〕朱建始名廉直，既距辟陽，不終其節，亦以喪身。陸賈位止大夫，致仕諸呂，〔五〕不受憂責，從容平、勃之間，〔六〕附會將相以彊社稷，身名俱榮，其最優乎！","sentenceOrder":226},
  {"id":"s_work_han_thu_54_227","chapterId":"ch_work_han_thu_54","textTraditional":"〔一〕　師古曰：「縉紳，儒者之服也，解在郊祀志。」","sentenceOrder":227},
  {"id":"s_work_han_thu_54_228","chapterId":"ch_work_han_thu_54","textTraditional":"〔二〕　師古曰：「此語本出慎子。」","sentenceOrder":228},
  {"id":"s_work_han_thu_54_229","chapterId":"ch_work_han_thu_54","textTraditional":"〔三〕　師古曰：「枹者鼓椎，所以擊鼓也。舍枹鼓者，言新罷戰陣之事，別創漢代之禮，故云一王之儀也。枹音桴，其字從木。」","sentenceOrder":229},
  {"id":"s_work_han_thu_54_230","chapterId":"ch_work_han_thu_54","textTraditional":"〔四〕　師古曰：「鼎大而無足曰鑊，音胡郭反。」","sentenceOrder":230},
  {"id":"s_work_han_thu_54_231","chapterId":"ch_work_han_thu_54","textTraditional":"〔五〕　師古曰：「以諸呂僭差，託病歸家。」","sentenceOrder":231},
  {"id":"s_work_han_thu_54_232","chapterId":"ch_work_han_thu_54","textTraditional":"〔六〕　師古曰：「謂和輯陳平、周勃以安漢朝也。從音七容反。」","sentenceOrder":232},
  {"id":"s_work_han_thu_54_233","chapterId":"ch_work_han_thu_54","textTraditional":"校勘記","sentenceOrder":233},
  {"id":"s_work_han_thu_54_234","chapterId":"ch_work_han_thu_54","textTraditional":"二一０六頁一三行　欲率諸侯（攻）〔破〕秦乎？　景祐、殿本都作「破」，史記同。","sentenceOrder":234},
  {"id":"s_work_han_thu_54_235","chapterId":"ch_work_han_thu_54","textTraditional":"二一０七頁　三行　沛公引〔兵〕隨之，　景祐、殿本都有「兵」字。王先謙說此脫。","sentenceOrder":235},
  {"id":"s_work_han_thu_54_236","chapterId":"ch_work_han_thu_54","textTraditional":"二一０七頁一四行　食其（嘗）〔常〕為說客，　王先謙說「嘗」字誤，當依史記作「常」。","sentenceOrder":236},
  {"id":"s_work_han_thu_54_237","chapterId":"ch_work_han_thu_54","textTraditional":"二一０八頁一０行　（反）〔救〕趙及梁。　景祐、殿本都作「救」。王先謙說作「救」是。","sentenceOrder":237},
  {"id":"s_work_han_thu_54_238","chapterId":"ch_work_han_thu_54","textTraditional":"二一一一頁　五行　與天子（伉）〔抗〕衡為敵國，　景祐、殿本都作「抗」。","sentenceOrder":238},
  {"id":"s_work_han_thu_54_239","chapterId":"ch_work_han_thu_54","textTraditional":"二一一一頁一０行　掘燒君王先人（家）〔冢〕墓，　景祐、殿、局本都作「冢」，此誤。","sentenceOrder":239},
  {"id":"s_work_han_thu_54_240","chapterId":"ch_work_han_thu_54","textTraditional":"二一一三頁　九行　（師古）〔蘇林〕曰：　景祐、殿本都作「蘇林」。","sentenceOrder":240},
  {"id":"s_work_han_thu_54_241","chapterId":"ch_work_han_thu_54","textTraditional":"二一一四頁　三行　其後以為（信）〔姓〕。　景祐、殿本都作「姓」，此誤。","sentenceOrder":241},
  {"id":"s_work_han_thu_54_242","chapterId":"ch_work_han_thu_54","textTraditional":"二一一四頁　七行　謂作書明言（也）〔之〕。景祐本「也」作「之」。","sentenceOrder":242},
  {"id":"s_work_han_thu_54_243","chapterId":"ch_work_han_thu_54","textTraditional":"二一一四頁一二行　女給人馬酒食極（飲）〔欲〕，　景祐、殿本都作「欲」。","sentenceOrder":243},
  {"id":"s_work_han_thu_54_244","chapterId":"ch_work_han_thu_54","textTraditional":"二一一五頁　六行　平（嘗）〔常〕燕居深念。　景祐本作「嘗」，殿本作「常」，史記同。王先謙說作「嘗」是。","sentenceOrder":244},
  {"id":"s_work_han_thu_54_245","chapterId":"ch_work_han_thu_54","textTraditional":"二一一六頁　五行　厚為（其）〔共〕具，　景祐、殿本都作「共」。王先謙說作「共」是。","sentenceOrder":245},
  {"id":"s_work_han_thu_54_246","chapterId":"ch_work_han_thu_54","textTraditional":"二一一六頁　七行　言狼籍（之）〔甚〕盛。　景祐、殿本都作「甚」。","sentenceOrder":246},
  {"id":"s_work_han_thu_54_247","chapterId":"ch_work_han_thu_54","textTraditional":"二一一七頁　一行　〔辟陽侯曰：「平原君母死〕，何乃賀我？」　景祐、殿本都有「何」上九字。王先謙說史記同，此奪。","sentenceOrder":247},
  {"id":"s_work_han_thu_54_248","chapterId":"ch_work_han_thu_54","textTraditional":"二一二二頁　一行　胔音漬，謂（見）〔死〕者之肉也。　景祐、殿本都作「死」。王先謙說作「死」是。","sentenceOrder":248},
  {"id":"s_work_han_thu_54_249","chapterId":"ch_work_han_thu_54","textTraditional":"二一二二頁一一行　豈曾聞（外）孫敢與大父亢禮哉？　宋祁說越本無「外」字。按景祐本無。","sentenceOrder":249},
  {"id":"s_work_han_thu_54_250","chapterId":"ch_work_han_thu_54","textTraditional":"二一二二頁一一行　而（今）〔令〕宗室及後宮詐稱公主，　景祐、殿、局本都作「令」，此誤。","sentenceOrder":250},
  {"id":"s_work_han_thu_54_251","chapterId":"ch_work_han_thu_54","textTraditional":"二一二四頁　八行　郡守尉（令）〔今〕捕誅，何足憂？　景祐、殿本都作「今」。王先謙說作「今」是。","sentenceOrder":251},
  {"id":"s_work_han_thu_54_252","chapterId":"ch_work_han_thu_54","textTraditional":"二一二七頁　五行　言（德行）〔行德〕教百年，　景祐、殿本都作「行德」。王先謙說作「行德」是。","sentenceOrder":252},
  {"id":"s_work_han_thu_54_253","chapterId":"ch_work_han_thu_54","textTraditional":"二一二九頁　六行　呂后與陛下（共）〔攻〕苦食啖，　景祐、殿本都作「攻」。王先謙說作「攻」是。","sentenceOrder":253},
  {"id":"s_work_han_thu_54_254","chapterId":"ch_work_han_thu_54","textTraditional":"二一三０頁　二行　子孫奈何乘宗廟道（以）〔上〕行哉！　景祐、殿本都作「上」。王先謙說作「上」是。","sentenceOrder":254},
  {"id":"s_work_han_thu_55_1","chapterId":"ch_work_han_thu_55","textTraditional":"淮南厲王長，高帝少子也，其母故趙王張敖美人。高帝八年，從東垣過趙，趙王獻美人，厲王母也，幸，有身。趙王不敢內宮，〔一〕為築外宮舍之。〔二〕及貫高等謀反事覺，并逮治王，盡捕王母兄弟美人，繫之河內。厲王母亦繫，告吏曰：「日得幸上，有子。〔三〕」吏以聞，上方怒趙，未及理厲王母，厲王母弟趙兼因辟陽侯言呂后，呂后妒，不肯白，辟陽侯不強爭。厲王母已生厲王，恚，。即自殺。吏奉厲王詣上，上悔，〔四〕令呂后母之，而葬其母真定。真定，厲王母家縣也。","sentenceOrder":1},
  {"id":"s_work_han_thu_55_2","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「不敢更內之於宮中。」","sentenceOrder":2},
  {"id":"s_work_han_thu_55_3","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　師古曰：「舍，止也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_55_4","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　師古曰：「日謂往日。」","sentenceOrder":4},
  {"id":"s_work_han_thu_55_5","chapterId":"ch_work_han_thu_55","textTraditional":"〔四〕　師古曰：「（以）〔悔〕不理其母。」","sentenceOrder":5},
  {"id":"s_work_han_thu_55_6","chapterId":"ch_work_han_thu_55","textTraditional":"十一年，淮南王布反，上自將擊滅布，即立子長為淮南王。王早失母，常附呂后，孝惠、呂后時以故得幸無患，然常心怨辟陽侯，不敢發。及孝文初即位，自以為最親，〔一〕驕蹇，數不奉法。〔二〕上寬赦之。三年，入朝，甚橫。〔三〕從上入苑獵，與上同輦，常謂上「大兄」。厲王有材力，力扛鼎，〔四〕乃往請辟陽侯。辟陽侯出見之，即自袖金椎椎之，〔五〕命從者刑之。〔六〕馳詣闕下，肉袒而謝曰：「臣母不當坐趙時事，辟陽侯力能得之呂后，不爭，罪一也。趙王如意子母無罪，呂后殺之，辟陽侯不爭，罪二也。呂后王諸呂，欲以危劉氏，辟陽侯不爭，罪三也。臣謹為天下誅賊，報母之仇，伏闕下請罪。」文帝傷其志，為親故不治，赦之。","sentenceOrder":6},
  {"id":"s_work_han_thu_55_7","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「時高帝子唯二人在。」","sentenceOrder":7},
  {"id":"s_work_han_thu_55_8","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　師古曰：「蹇謂不順也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_55_9","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　師古曰：「橫音胡孟反。」","sentenceOrder":9},
  {"id":"s_work_han_thu_55_10","chapterId":"ch_work_han_thu_55","textTraditional":"〔四〕　師古曰：「扛，舉也，音江。」","sentenceOrder":10},
  {"id":"s_work_han_thu_55_11","chapterId":"ch_work_han_thu_55","textTraditional":"〔五〕　師古曰：「褏，古袖字也。謂以金椎藏置袖中，出而椎之。」","sentenceOrder":11},
  {"id":"s_work_han_thu_55_12","chapterId":"ch_work_han_thu_55","textTraditional":"〔六〕　如淳曰：「刻其形體，備五刑也。」師古曰：「直斷其首，非五刑也。事見史記。」","sentenceOrder":12},
  {"id":"s_work_han_thu_55_13","chapterId":"ch_work_han_thu_55","textTraditional":"當是時，自薄太后及太子諸大臣皆憚厲王。厲王以此歸國益恣，不用漢法，出入警蹕，稱制，自作法令，數上書不遜順。〔一〕文帝重自切責之。〔二〕時帝舅薄昭為將軍，尊重，上令昭予厲王書諫數之，曰：〔三〕","sentenceOrder":13},
  {"id":"s_work_han_thu_55_14","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「數音所角反。」","sentenceOrder":14},
  {"id":"s_work_han_thu_55_15","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　如淳曰：「重，難也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_55_16","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　師古曰：「數音所具反。」","sentenceOrder":16},
  {"id":"s_work_han_thu_55_17","chapterId":"ch_work_han_thu_55","textTraditional":"竊聞大王剛直而勇，慈惠而厚，貞信多斷，是天以聖人之資奉大王也甚盛，不可不察。今大王所行，不稱天資。皇帝初即位，易侯邑在淮南者，〔一〕大王不肯。皇帝卒易之，〔二〕使大王得三縣之實，甚厚。大王以未嘗與皇帝相見，求入朝見，未畢昆弟之歡〔三〕，而殺列侯以自為名。皇帝不使吏與其間，〔四〕赦大王，甚厚。漢法，二千石缺，輒言漢補，大王逐漢所置，而請自置相、二千石。皇帝骫天下正法而許大王，甚厚。〔五〕大王欲屬國為布衣，守冢真定。〔六〕皇帝不許，使大王毋失南面之尊，甚厚。〔七〕大王宜日夜奉法度，修貢職，以稱皇帝之厚德，今乃輕言恣行，以負謗於天下，甚非計也。","sentenceOrder":17},
  {"id":"s_work_han_thu_55_18","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　晉灼曰：「侯邑在淮南者，更易以它郡地封之，不欲使錯在王國。」","sentenceOrder":18},
  {"id":"s_work_han_thu_55_19","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　師古曰：「卒，終也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_55_20","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　師古曰：「畢，盡也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_55_21","chapterId":"ch_work_han_thu_55","textTraditional":"〔四〕　師古曰：「與讀曰豫，謂不令吏干豫治其事。」","sentenceOrder":21},
  {"id":"s_work_han_thu_55_22","chapterId":"ch_work_han_thu_55","textTraditional":"〔五〕　蘇林曰：「不從正法，聽王自置二千石。」師古曰：「骫，古委字。骫謂曲也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_55_23","chapterId":"ch_work_han_thu_55","textTraditional":"〔六〕　師古曰：「屬謂委棄之也，音之欲反。」","sentenceOrder":23},
  {"id":"s_work_han_thu_55_24","chapterId":"ch_work_han_thu_55","textTraditional":"〔七〕　師古曰：「毋失，不失也。南面之尊，謂王位也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_55_25","chapterId":"ch_work_han_thu_55","textTraditional":"夫大王以千里為宅居，以萬民為臣妾，此高皇帝之厚德也。高帝蒙霜露，沬風雨，〔一〕赴矢石，野戰（次）〔攻〕城，身被創痍，〔二〕以為子孫成萬世之業，艱難危苦甚矣。大王不思先帝之艱苦，日夜怵惕，修身正行，養犧牲，豐潔粢盛，奉祭祀，以無忘先帝之功德，而欲屬國為布衣，甚過。且夫貪讓國土之名，輕廢先帝之業，不可以言孝。父為之基，而不能守，不賢。不求守長陵，而求之真定，先母後父，不誼。數逆天子之令，不順。言節行以高兄，無禮。〔三〕幸臣有罪，大者立斷，小者肉刑，不仁。〔四〕貴布衣一劍之任，賤王侯之位，不知。不好學問大道，觸情妄行，不（詳）〔祥〕。〔五〕此八者，危亡之路也，而大王行之。棄南面之位，奮諸、賁之勇，〔六〕常出入危亡之路，臣之所見，高皇帝之神必不廟食於大王之手，明白。","sentenceOrder":25},
  {"id":"s_work_han_thu_55_26","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「沬亦頮字也。蒙，冒也。沬，洗面也，音胡內反，字從午未之未。」","sentenceOrder":26},
  {"id":"s_work_han_thu_55_27","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　師古曰：「痍音夷。」","sentenceOrder":27},
  {"id":"s_work_han_thu_55_28","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　鄭氏曰：「淮南王呼帝為大兄也。」師古曰：「鄭說非也。謂請守母冢，自為名節而表異行，用此矜高於兄耳。」","sentenceOrder":28},
  {"id":"s_work_han_thu_55_29","chapterId":"ch_work_han_thu_55","textTraditional":"〔四〕　師古曰：「斷謂斬也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_55_30","chapterId":"ch_work_han_thu_55","textTraditional":"〔五〕　師古曰：「任情意所欲則行之妄行。行音下更反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_55_31","chapterId":"ch_work_han_thu_55","textTraditional":"〔六〕　應劭曰：「吳專諸，衛孟賁也。」師古曰：「賁音奔。」","sentenceOrder":31},
  {"id":"s_work_han_thu_55_32","chapterId":"ch_work_han_thu_55","textTraditional":"昔者，周公誅管叔，放蔡叔，以安周；齊桓殺其弟，以反國；〔一〕秦始皇殺兩弟，遷其母，以安秦；〔二〕頃王亡代，高帝奪之國，以便事；〔三〕濟北舉兵，皇帝誅之，以安漢。〔四〕故周、齊行之於古，秦、漢用之於今，大王不察古今之所以安國便事，而欲以親戚之意望於太上，不可得也。〔五〕亡之諸侯，游宦事人，及舍匿者，論皆有法。〔六〕其在王所，吏主者坐。〔七〕今諸侯子為吏者，御史主；〔八〕為軍吏者，中尉主；客出入殿門者，衛尉大行主；諸從蠻夷來歸誼及以亡名數自（古）〔占〕者，內史縣令主。相欲委下吏，無與其禍，不可得也。〔九〕王若不改，漢繫大王邸，論相以下，為之奈何？夫墮父大業，退為布衣所哀，〔一０〕幸臣皆伏法而誅，為天下笑，以羞先帝之德，〔一一〕甚為大王不取也。","sentenceOrder":32},
  {"id":"s_work_han_thu_55_33","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　韋昭曰：「子糾兄也，言弟者諱也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_55_34","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　應劭曰：「始皇母與嫪毐私通生二子，事覺誅毐，并殺二弟，遷其母於咸陽宮也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_55_35","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　應劭曰：「頃王，高帝兄仲也。匈奴入代不能守，走歸京師。高帝奪其國，退為郃陽侯，以便國法也。」師古曰：「便音頻面反。」","sentenceOrder":35},
  {"id":"s_work_han_thu_55_36","chapterId":"ch_work_han_thu_55","textTraditional":"〔四〕　應劭曰：「濟北王興居與大臣共誅諸呂，自以功大，怨其賞薄，故反。」","sentenceOrder":36},
  {"id":"s_work_han_thu_55_37","chapterId":"ch_work_han_thu_55","textTraditional":"〔五〕　如淳曰：「太上，天子也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_55_38","chapterId":"ch_work_han_thu_55","textTraditional":"〔六〕　師古曰：「舍匿，謂容止而藏隱也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_55_39","chapterId":"ch_work_han_thu_55","textTraditional":"〔七〕　師古曰：「言各有所主，而坐其罪。」","sentenceOrder":39},
  {"id":"s_work_han_thu_55_40","chapterId":"ch_work_han_thu_55","textTraditional":"〔八〕　如淳曰：「主御史也。自此以下至縣令主皆謂王官屬。」","sentenceOrder":40},
  {"id":"s_work_han_thu_55_41","chapterId":"ch_work_han_thu_55","textTraditional":"〔九〕　師古曰：「言諸侯王之相欲委罪於在下小吏，而身不干豫之，不可得也。與讀曰豫。」","sentenceOrder":41},
  {"id":"s_work_han_thu_55_42","chapterId":"ch_work_han_thu_55","textTraditional":"〔一０〕師古曰：「墮，毀也。布衣，貧賤之人。王既伏法，則貧賤之人反哀憐之。墮音火規反。」","sentenceOrder":42},
  {"id":"s_work_han_thu_55_43","chapterId":"ch_work_han_thu_55","textTraditional":"〔一一〕師古曰：「羞，辱也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_55_44","chapterId":"ch_work_han_thu_55","textTraditional":"宜急改操易行，上書謝罪，曰：「臣不幸早失先帝，少孤，呂氏之世，未嘗忘死。〔一〕陛下即位，臣怙恩德驕盈，行多不軌。〔二〕追念罪過，恐懼，伏地待誅不敢起。」皇帝聞之必喜。大王昆弟歡欣於上，群臣皆得延壽於下；上下得宜，海內常安。願孰計而疾行之。行之有疑，禍如發矢，不可追已。〔三〕","sentenceOrder":44},
  {"id":"s_work_han_thu_55_45","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　服虔曰：「常恐畏死也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_55_46","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　師古曰：「軌，法也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_55_47","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　師古曰：「發矢，喻速也。已，語終辭。」","sentenceOrder":47},
  {"id":"s_work_han_thu_55_48","chapterId":"ch_work_han_thu_55","textTraditional":"王得書不說。〔一〕六年，令男子但等七十人與棘蒲侯柴武太子奇謀，以輦車四十乘反谷口，〔二〕令人使閩越、匈奴。事覺，治之，乃使使召淮南王。","sentenceOrder":48},
  {"id":"s_work_han_thu_55_49","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":49},
  {"id":"s_work_han_thu_55_50","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　孟康曰：「谷口在長安北，故縣也，處多嶮阻。」師古曰：「輦車，人輓行以載兵器也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_55_51","chapterId":"ch_work_han_thu_55","textTraditional":"王至長安，丞相張蒼，典客馮敬行御史大夫事，與宗正、廷尉雜奏：「長廢先帝法，不聽天子詔，居處無度，為黃屋蓋儗天子，〔一〕擅為法令，不用漢法。及所置吏，以其郎中春為丞相，收聚漢諸侯人及有罪亡者，匿與居，為治家室，賜與財物爵祿田宅，爵或至關內侯，奉以二千石所當得。〔二〕大夫但、〔三〕士伍開章等七十人〔四〕與棘蒲侯太子奇謀反，欲以危宗廟社稷，謀使閩越及匈奴發其兵。事覺，長安尉奇等往捕開章，長匿不予，與故中尉蕑忌謀，殺以閉口，〔五〕為棺槨衣衾，葬之肥陵，〔六〕謾吏曰『不知安在』〔七〕。又陽聚土，樹表其上曰『開章死，葬此下』。〔八〕及長身自賊殺無罪者一人；令吏論殺無罪者六人；為亡命棄市詐捕命者以除罪；〔九〕擅罪人，無告劾繫治城旦以上十四人；敗免罪人死罪十八人，城旦舂以下五十八人；賜人爵關內侯以下九十四人。前日長病，陛下心憂之，使使者賜棗脯，長不肯見拜使者。南海民處廬江界中者反，淮南吏卒擊之。陛下遣使者齎帛五十匹，以賜吏卒勞苦者。長不欲受賜，謾曰『無勞苦者』。南海王織上書獻璧帛皇帝，忌擅燔其書，不以聞。〔一０〕吏請召治忌，長不遣，謾曰『忌病』。長所犯不軌，當棄市，臣請論如法。」","sentenceOrder":51},
  {"id":"s_work_han_thu_55_52","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「儗，比也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_55_53","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　如淳曰：「賜亡畔來者，如賜其國二千石也。」臣瓚曰：「奉畔者以二千石之秩祿也。」師古曰：「瓚說是也。奉音扶用反。」","sentenceOrder":53},
  {"id":"s_work_han_thu_55_54","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　張晏曰：「大夫，姓也，上云『男子但』，明其本姓大夫也。」如淳曰：「但，大夫名也。」師古曰：「既曰大夫但，又士伍開章，明其為大夫也。上言男子但等者，總謂反人耳，不妨但為大夫也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_55_55","chapterId":"ch_work_han_thu_55","textTraditional":"〔四〕　如淳曰：「律，有罪失官爵，稱士伍也。開章，名。」","sentenceOrder":55},
  {"id":"s_work_han_thu_55_56","chapterId":"ch_work_han_thu_55","textTraditional":"〔五〕　師古曰：「姓蕑，名忌。蕑音奸，嚴助傳作間字，音同耳。今流俗書本此蕑字或有作簡者，非也，蓋後人所改。既殺開章，所有口語皆無端緒，故云閉口。」","sentenceOrder":56},
  {"id":"s_work_han_thu_55_57","chapterId":"ch_work_han_thu_55","textTraditional":"〔六〕　師古曰：「肥陵，地名，在肥水之上。」","sentenceOrder":57},
  {"id":"s_work_han_thu_55_58","chapterId":"ch_work_han_thu_55","textTraditional":"〔七〕　師古曰：「謾，誑也。實葬肥陵，誑云不知處。謾音慢，又音莫連反。次下亦同。」","sentenceOrder":58},
  {"id":"s_work_han_thu_55_59","chapterId":"ch_work_han_thu_55","textTraditional":"〔八〕　師古曰：「表者，豎木為之，若柱形也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_55_60","chapterId":"ch_work_han_thu_55","textTraditional":"〔九〕　晉灼曰：「亡命者當棄市，而王藏之。詐捕不命者而言命，以脫命者之罪。」師古曰：「為音于偽反。」","sentenceOrder":60},
  {"id":"s_work_han_thu_55_61","chapterId":"ch_work_han_thu_55","textTraditional":"〔一０〕文穎曰：「忌，蕑忌也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_55_62","chapterId":"ch_work_han_thu_55","textTraditional":"制曰：「朕不忍置法於王，其與列侯吏二千石議。」列侯吏二千石臣嬰等四十三人議，皆曰：「宜論如法。」制曰：「其赦長死罪，廢勿王。」有司奏：「請處蜀嚴道邛郵，〔一〕遣其子、子母從居，〔二〕縣為築蓋家室，皆日三食，給薪菜鹽炊食器席蓐。」〔三〕制曰：「食長，給肉日五斤，〔四〕酒二斗。令故美人材人得幸者十人從居。」〔五〕於是盡誅所與謀者。乃遣長，載以輜車，〔六〕令縣次傳。","sentenceOrder":62},
  {"id":"s_work_han_thu_55_63","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　張晏曰：「嚴道，蜀郡縣也。邛，郵置名也。」師古曰：「郵，行書之舍，音尤。」","sentenceOrder":63},
  {"id":"s_work_han_thu_55_64","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　師古曰：「子母者，所生子之姬妾。」","sentenceOrder":64},
  {"id":"s_work_han_thu_55_65","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　師古曰：「炊器，釜鬲之屬。食器，盃碗之屬。」","sentenceOrder":65},
  {"id":"s_work_han_thu_55_66","chapterId":"ch_work_han_thu_55","textTraditional":"〔四〕　師古曰：「食音飤。」","sentenceOrder":66},
  {"id":"s_work_han_thu_55_67","chapterId":"ch_work_han_thu_55","textTraditional":"〔五〕　師古曰：「上言子母，則有子者令從之。今此云美人材人，則無子者亦令從之。」","sentenceOrder":67},
  {"id":"s_work_han_thu_55_68","chapterId":"ch_work_han_thu_55","textTraditional":"〔六〕　師古曰：「輜，衣車也，音甾。」","sentenceOrder":68},
  {"id":"s_work_han_thu_55_69","chapterId":"ch_work_han_thu_55","textTraditional":"爰盎諫曰：「上素驕淮南王，不為置嚴相傅，以故至此。且淮南王為人剛，今暴摧折之，臣恐其逢霧露病死，陛下有殺弟之名，奈何！」上曰：「吾特苦之耳，令復之。」〔一〕淮南王謂侍者曰：「誰謂乃公勇者？吾以驕不聞過，故至此。」乃不食而死。縣傳者不敢發車封。〔二〕至雍，〔三〕雍令發之，以死聞。上悲哭，謂爰盎曰：「吾不從公言，卒亡淮南王。」盎曰：「淮南王不可奈何，願陛下自寬。」上曰：「為之奈何？」曰：「獨斬丞相、御史以謝天下乃可。」上即令丞相、御史逮諸縣傳淮南王不發封餽侍者，〔四〕皆棄市。乃以列侯葬淮南王于雍，置守冢三十家。","sentenceOrder":69},
  {"id":"s_work_han_thu_55_70","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「暫困苦之，令其自悔，即追還也。復音扶目反。」","sentenceOrder":70},
  {"id":"s_work_han_thu_55_71","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　孟康曰：「檻車有封也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_55_72","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　師古曰：「雍，扶風雍縣。」","sentenceOrder":72},
  {"id":"s_work_han_thu_55_73","chapterId":"ch_work_han_thu_55","textTraditional":"〔四〕　師古曰：「逮，追捕之也。餽亦饋字耳。」","sentenceOrder":73},
  {"id":"s_work_han_thu_55_74","chapterId":"ch_work_han_thu_55","textTraditional":"孝文八年，憐淮南王，王有子四人。年皆七八歲，乃封子安為阜陵侯，子勃為安陽侯，子賜為陽周侯，子良為東城侯。","sentenceOrder":74},
  {"id":"s_work_han_thu_55_75","chapterId":"ch_work_han_thu_55","textTraditional":"十二年，民有作歌歌淮南王曰：「一尺布，尚可縫；一斗粟，尚可舂。兄弟二人，不相容！」〔一〕上聞之曰：「昔堯舜放逐骨肉，周公殺管蔡，〔二〕天下稱聖，不以私害公。天下豈以為我貪淮南地邪？」乃徙城陽王王淮南故地，而追尊諡淮南王為厲王，置園如諸侯儀。","sentenceOrder":75},
  {"id":"s_work_han_thu_55_76","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　孟康曰：「尺帛斗粟猶尚不棄，況於兄弟而更相逐乎！」臣瓚曰：「一尺帛可縫而共衣，一斗粟可舂而共食，況以天下之廣，而不相容也。」師古曰：「瓚說是。」","sentenceOrder":76},
  {"id":"s_work_han_thu_55_77","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　師古曰：「鯀及共工皆堯舜之同姓，故云骨肉。」","sentenceOrder":77},
  {"id":"s_work_han_thu_55_78","chapterId":"ch_work_han_thu_55","textTraditional":"十六年，上憐淮南王廢法不軌，自使失國早夭，乃徙淮南王喜復王故城陽，而立厲王三子王淮南故地，三分之：阜陵侯安為淮南王，安陽侯勃為衡山王，陽周侯賜為廬江王。東城侯良前薨，無後。","sentenceOrder":78},
  {"id":"s_work_han_thu_55_79","chapterId":"ch_work_han_thu_55","textTraditional":"孝景三年，吳楚七國反，吳使者至淮南，（淮南）王欲發兵應之。其相曰：「王必欲應吳，臣願為將。」王乃屬之。〔一〕相已將兵，因城守，不聽王而為漢。漢亦使曲城侯將兵救淮南，〔二〕淮南以故得完。吳使者至廬江，廬江王不應，而往來使越；至衡山，衡山王堅守無二心。孝景四年，吳楚已破，衡山王朝，上以為貞信，乃勞苦之〔三〕曰：「南方卑溼。」徙王王於濟北以褒之。及薨，遂賜諡為貞王。廬江王以邊越，數使使相交，〔四〕徙為衡山王，王江北。","sentenceOrder":79},
  {"id":"s_work_han_thu_55_80","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「屬謂以兵委之也。屬音之欲反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_55_81","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　晉灼曰：「功臣表蟲達也。」師古曰：「晉說非。此蟲達之子耳，名（揵）〔捷〕。達已先薨也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_55_82","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　師古曰：「勞音來到反。」","sentenceOrder":82},
  {"id":"s_work_han_thu_55_83","chapterId":"ch_work_han_thu_55","textTraditional":"〔四〕　師古曰：「邊越者，邊界與越相接。」","sentenceOrder":83},
  {"id":"s_work_han_thu_55_84","chapterId":"ch_work_han_thu_55","textTraditional":"淮南王安為人好書，鼓琴，不喜弋獵狗馬馳騁，〔一〕亦欲以行陰德拊循百姓，流名譽。招致賓客方術之士數千人，作為內書二十一篇，外書甚眾，又有中篇八卷，言神仙黃白之術，〔二〕亦二十餘萬言。時武帝方好藝文，以安屬為諸父，〔三〕辯博善為文辭，甚尊重之。每為報書及賜，〔四〕常召司馬相如等視草乃遣。〔五〕初，安入朝，獻所作內篇，新出，上愛祕之。使為離騷傳，〔六〕旦受詔，日食時上。又獻頌德及長安都國頌。每宴見，談說得失及方技賦頌，昏莫然後罷。","sentenceOrder":84},
  {"id":"s_work_han_thu_55_85","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「喜音許吏反。」","sentenceOrder":85},
  {"id":"s_work_han_thu_55_86","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　張晏曰：「黃，黃金；白，白銀也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_55_87","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　師古曰：「安於天子服屬為從父叔父。」","sentenceOrder":87},
  {"id":"s_work_han_thu_55_88","chapterId":"ch_work_han_thu_55","textTraditional":"〔四〕　師古曰：「賜，賜書也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_55_89","chapterId":"ch_work_han_thu_55","textTraditional":"〔五〕　師古曰：「草謂為文之藁草。」","sentenceOrder":89},
  {"id":"s_work_han_thu_55_90","chapterId":"ch_work_han_thu_55","textTraditional":"〔六〕　師古曰：「傳謂解說之，若毛詩傳。」","sentenceOrder":90},
  {"id":"s_work_han_thu_55_91","chapterId":"ch_work_han_thu_55","textTraditional":"安初入朝，雅善太尉武安侯，〔一〕武安侯迎之霸上，與語曰：「方今上無太子，王親高皇帝孫，行仁義，天下莫不聞。宮車一日晏駕，非王尚誰立者！」淮南王大喜，厚遺武安侯寶賂。其群臣賓客，江淮間多輕薄，以厲王遷死感激安。建元六年，彗星見，淮南王心怪之。或說王曰：「先吳軍時，彗星出，長數尺，然尚流血千里。今彗星竟天，天下兵當大起。」王心以為上無太子，天下有變，諸侯並爭，愈益治攻戰具，積金錢賂遺郡國。遊士妄作妖言阿諛王，王喜，多賜予之。","sentenceOrder":91},
  {"id":"s_work_han_thu_55_92","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「田蚡。」","sentenceOrder":92},
  {"id":"s_work_han_thu_55_93","chapterId":"ch_work_han_thu_55","textTraditional":"王有女陵，慧有口。〔一〕王愛陵，多予金錢，為中詗長安〔二〕，約結上左右。元朔二年，上賜淮南王几杖，不朝。后荼愛幸〔三〕，生子遷為太子，取皇太后外孫修成君女為太子妃。〔四〕王謀為反具，畏太子妃知而內泄事，乃與太子謀，令詐不愛，三月不同席。王陽怒太子，閉使與妃同內，終不近妃。妃求去，王乃上書謝歸之。后荼、太子遷及女陵擅國權，奪民田宅，妄致繫人。〔五〕","sentenceOrder":93},
  {"id":"s_work_han_thu_55_94","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「性慧了而口辯。」","sentenceOrder":94},
  {"id":"s_work_han_thu_55_95","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　孟康曰：「詗音偵。西方人以反間為詗。王使其女為偵於中也。」如淳曰：「詗音朽政反。」師古曰：「詗，有所候伺也。如音是矣。偵者，義與詗同，然音則異。音丑政反。」","sentenceOrder":95},
  {"id":"s_work_han_thu_55_96","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　師古曰：「荼者，后名也，音塗。」","sentenceOrder":96},
  {"id":"s_work_han_thu_55_97","chapterId":"ch_work_han_thu_55","textTraditional":"〔四〕　服虔曰：「武帝異姓姊之女也。」應劭曰：「修成君，王太后先適金氏女也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_55_98","chapterId":"ch_work_han_thu_55","textTraditional":"〔五〕　師古曰：「致，至也，牽引而致之。」","sentenceOrder":98},
  {"id":"s_work_han_thu_55_99","chapterId":"ch_work_han_thu_55","textTraditional":"太子學用劍，自以為人莫及，聞郎中雷被巧，〔一〕召與戲。被壹再辭讓，誤中太子。〔二〕太子怒，被恐。此時有欲從軍者輒詣長安，被即願奮擊匈奴。太子數惡被，〔三〕王使郎中令斥免，欲以禁後。〔四〕元朔五年，被遂亡之長安，上書自明。事下廷尉、河南。河南治，〔五〕逮淮南太子。〔六〕王、王后計欲毋遣太子，〔七〕遂發兵。計未定，猶與十餘日。〔八〕會有詔即訊太子，〔九〕淮南相怒壽春丞留太子逮不遣，〔一０〕劾不敬。王請相，相不聽。王使人上書告相，事下廷尉治。從跡連王，〔一一〕王使人候司。〔一二〕漢公卿請逮捕治王，王恐，欲發兵。太子遷謀曰：「漢使即逮王，令人衣衛士衣，持戟居王旁，有非是者，即刺殺之，臣亦使人刺殺淮南中尉，乃舉兵，未晚也。」是時上不許公卿，而遣漢中尉宏即訊驗王。〔一三〕王視漢中尉顏色和，問斥雷被事耳，自度無何，〔一四〕不發。中尉還，以聞。公卿治者曰：「淮南王安雍閼求奮擊匈奴者雷被等，格明詔，〔一五〕當棄市。」詔不許。請廢勿王，上不許。請削五縣，可二縣。使中尉宏赦其罪，罰以削地。中尉入淮南界，宣言赦王。王初聞公卿請誅之，未知得削地，聞漢使來，恐其捕之，乃與太子謀如前計。中尉至，即賀王，王以故不發。其後自傷曰：「吾行仁義見削地，寡人甚恥之。」為反謀益甚。諸使者道長安來，〔一六〕為妄言，言上無男，即喜；言漢廷治，有男，即怒，〔一七〕以為妄言，非也。〔一八〕","sentenceOrder":99},
  {"id":"s_work_han_thu_55_100","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「被音皮義反。巧者，善用劍也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_55_101","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　師古曰：「中音竹仲反。」","sentenceOrder":101},
  {"id":"s_work_han_thu_55_102","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　師古曰：「謂譖毀之於王也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_55_103","chapterId":"ch_work_han_thu_55","textTraditional":"〔四〕　師古曰：「令後人更不敢效之。」","sentenceOrder":103},
  {"id":"s_work_han_thu_55_104","chapterId":"ch_work_han_thu_55","textTraditional":"〔五〕　師古曰：「章下廷尉及河南令，於河南雜治其事。」","sentenceOrder":104},
  {"id":"s_work_han_thu_55_105","chapterId":"ch_work_han_thu_55","textTraditional":"〔六〕　師古曰：「追赴河南也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_55_106","chapterId":"ch_work_han_thu_55","textTraditional":"〔七〕　師古曰：「王與王后共計也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_55_107","chapterId":"ch_work_han_thu_55","textTraditional":"〔八〕　師古曰：「與讀曰豫。」","sentenceOrder":107},
  {"id":"s_work_han_thu_55_108","chapterId":"ch_work_han_thu_55","textTraditional":"〔九〕　師古曰：「即，就也。訊，問也。就淮南問之，不逮詣河南。」","sentenceOrder":108},
  {"id":"s_work_han_thu_55_109","chapterId":"ch_work_han_thu_55","textTraditional":"〔一０〕如淳曰：「丞順王意，不遣太子應逮書。」","sentenceOrder":109},
  {"id":"s_work_han_thu_55_110","chapterId":"ch_work_han_thu_55","textTraditional":"〔一一〕師古曰：「從讀曰蹤。」","sentenceOrder":110},
  {"id":"s_work_han_thu_55_111","chapterId":"ch_work_han_thu_55","textTraditional":"〔一二〕師古曰：「入京師候司其事。」","sentenceOrder":111},
  {"id":"s_work_han_thu_55_112","chapterId":"ch_work_han_thu_55","textTraditional":"〔一三〕師古曰：「即亦就也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_55_113","chapterId":"ch_work_han_thu_55","textTraditional":"〔一四〕師古曰：「自計度更無罪。度音徒各反。」","sentenceOrder":113},
  {"id":"s_work_han_thu_55_114","chapterId":"ch_work_han_thu_55","textTraditional":"〔一五〕師古曰：「雍讀曰壅。格音閣，謂攱閣不行之。」","sentenceOrder":114},
  {"id":"s_work_han_thu_55_115","chapterId":"ch_work_han_thu_55","textTraditional":"〔一六〕師古曰：「道，從也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_55_116","chapterId":"ch_work_han_thu_55","textTraditional":"〔一七〕師古曰：「漢廷治者，朝廷皆治理也。治音丈吏反。」","sentenceOrder":116},
  {"id":"s_work_han_thu_55_117","chapterId":"ch_work_han_thu_55","textTraditional":"〔一八〕師古曰：「云治及有男皆妄言耳，非真實也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_55_118","chapterId":"ch_work_han_thu_55","textTraditional":"日夜與左吳等按輿地圖，〔一〕部署兵所從入。王曰：「上無太子，宮車即晏駕，大臣必徵膠東王，不即常山王，諸侯並爭，吾可以無備乎！且吾高帝孫，親行仁義，陛下遇我厚，吾能忍之；萬世之後，吾寧能北面事豎子乎！」","sentenceOrder":118},
  {"id":"s_work_han_thu_55_119","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　蘇林曰：「輿猶盡載之意。」","sentenceOrder":119},
  {"id":"s_work_han_thu_55_120","chapterId":"ch_work_han_thu_55","textTraditional":"王有孽子不害，最長，〔一〕王不愛，后、太子皆不以為子兄數。〔二〕不害子建，材高有氣，常怨望太子不省其父。〔三〕時諸侯皆得分子弟為侯，〔四〕淮南王有兩子，一子為太子，而建父不得為侯。陰結交，〔五〕欲害太子，以其父代之。太子知之，數捕繫笞建。建具知太子之欲謀殺漢中尉，即使所善壽春嚴正上書天子曰：「毒藥苦口利病，忠言逆耳利行。今淮南王孫建材能高，淮南王后荼、荼子遷常疾害建。建父不害無罪，擅數繫，欲殺之。今建在，可徵問，具知淮南王陰事。」書既聞，上以其事下廷尉、河南治。是歲元朔六年也。故辟陽侯孫審卿善丞相公孫弘，怨淮南厲王殺其大父，陰求淮南事而搆之於弘。弘乃疑淮南有畔逆計，深探其獄。〔六〕河南治建，辭引太子及黨與。","sentenceOrder":120},
  {"id":"s_work_han_thu_55_121","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「孽，庶也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_55_122","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　如淳曰：「后不以為子，太子不以為兄秩數。」","sentenceOrder":122},
  {"id":"s_work_han_thu_55_123","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　服虔曰：「不省錄著兄弟數中也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_55_124","chapterId":"ch_work_han_thu_55","textTraditional":"〔四〕　師古曰：「分國邑以封之。」","sentenceOrder":124},
  {"id":"s_work_han_thu_55_125","chapterId":"ch_work_han_thu_55","textTraditional":"〔五〕　師古曰：「與外人交通為援。」","sentenceOrder":125},
  {"id":"s_work_han_thu_55_126","chapterId":"ch_work_han_thu_55","textTraditional":"〔六〕　張晏曰：「探窮其根原。」","sentenceOrder":126},
  {"id":"s_work_han_thu_55_127","chapterId":"ch_work_han_thu_55","textTraditional":"初，王數以舉兵謀問伍被，被常諫之，以吳楚七國為效。〔一〕王引陳勝、吳廣，被復言形勢不同，必敗亡。及建見治，王恐國陰事泄，欲發，復問被，被為言發兵權變。語在被傳。於是王銳欲發〔二〕，乃令官奴入宮中，作皇帝璽，丞相、御史大夫、將軍、吏中二千石、都官令、丞印，及旁近郡太守、都尉印，漢使節法冠。〔三〕欲如伍被計，使人為得罪而西，〔四〕事大將軍、丞相；一日發兵，即刺大將軍衛青，〔五〕而說丞相弘下之，如發蒙耳。〔六〕欲發國中兵，恐相、二千石不聽，王乃與伍被謀，為失火宮中，相、二千石救火，因殺之。又欲令人衣求盜衣，〔七〕持羽檄從南方來，〔八〕呼言曰「南越兵入」，〔九〕欲因以發兵。乃使人之廬江、會稽為求盜，未決。","sentenceOrder":127},
  {"id":"s_work_han_thu_55_128","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「言反事不成。」","sentenceOrder":128},
  {"id":"s_work_han_thu_55_129","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　師古曰：「王意欲發兵如鋒刃之銳利，故云銳也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_55_130","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　師古曰：「法冠，御史冠也。本楚王冠，秦滅楚，以其君冠賜御史。」","sentenceOrder":130},
  {"id":"s_work_han_thu_55_131","chapterId":"ch_work_han_thu_55","textTraditional":"〔四〕　蘇林曰：「詐作得罪人而西也。」師古曰：「為得罪之狀而去也。西謂如京師也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_55_132","chapterId":"ch_work_han_thu_55","textTraditional":"〔五〕　師古曰：「發兵謂王發兵反。」","sentenceOrder":132},
  {"id":"s_work_han_thu_55_133","chapterId":"ch_work_han_thu_55","textTraditional":"〔六〕　如淳曰：「以物蒙覆其頭，而為發去之，則其人欲之耳。」晉灼曰：「如發去物上之蒙，直取其易也。」師古曰：「晉說是。」","sentenceOrder":133},
  {"id":"s_work_han_thu_55_134","chapterId":"ch_work_han_thu_55","textTraditional":"〔七〕　師古曰：「求盜，卒之掌逐捕賊盜者。」","sentenceOrder":134},
  {"id":"s_work_han_thu_55_135","chapterId":"ch_work_han_thu_55","textTraditional":"〔八〕　師古曰：「羽檄，徵兵之書也，解在高紀。」","sentenceOrder":135},
  {"id":"s_work_han_thu_55_136","chapterId":"ch_work_han_thu_55","textTraditional":"〔九〕　師古曰：「呼音火故反。」","sentenceOrder":136},
  {"id":"s_work_han_thu_55_137","chapterId":"ch_work_han_thu_55","textTraditional":"廷尉以建辭連太子遷聞，上遣廷尉監與淮南中尉逮捕太子。至，淮南王聞，與太子謀召相、二千石，欲殺而發兵。召相，相至；內史以出為解。〔一〕中尉曰：「臣受詔使，不得見王。」王念獨殺相而內史、中尉不來，無益也，即罷相。〔二〕計猶與未決。〔三〕太子念所坐者謀殺漢中尉，所與謀殺者已死，以為口絕，乃謂王曰：「群臣可用者皆前繫，今無足與舉事者。王以非時發，恐無功，臣願會逮。」〔四〕王亦愈欲休，即許太子。太子自刑，不殊。〔五〕伍被自詣吏，具告與淮南王謀反。吏因捕太子、王后，圍王宮，盡捕王賓客在國中者，索得反具以聞。〔六〕上下公卿治，所連引與淮南王謀反列侯、二千石、豪桀數千人，皆以罪輕重受誅。","sentenceOrder":137},
  {"id":"s_work_han_thu_55_138","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「不應召而云已出也。解者，解說也，若今言分疏矣。」","sentenceOrder":138},
  {"id":"s_work_han_thu_55_139","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　師古曰：「遣出去。」","sentenceOrder":139},
  {"id":"s_work_han_thu_55_140","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　師古曰：「與讀曰豫。」","sentenceOrder":140},
  {"id":"s_work_han_thu_55_141","chapterId":"ch_work_han_thu_55","textTraditional":"〔四〕　師古曰：「會謂應逮書而往也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_55_142","chapterId":"ch_work_han_thu_55","textTraditional":"〔五〕　晉灼曰：「不殊，不死也。」師古曰：「殊，絕也，雖自刑殺，而身首不絕也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_55_143","chapterId":"ch_work_han_thu_55","textTraditional":"〔六〕　師古曰：「索，搜也，音山客反。」","sentenceOrder":143},
  {"id":"s_work_han_thu_55_144","chapterId":"ch_work_han_thu_55","textTraditional":"衡山王賜，淮南王弟，當坐收。有司請逮捕衡山王，上曰：「諸侯各以其國為本，不當相坐。與諸侯王列侯議。」趙王彭祖、列侯讓等四十三人皆曰：「淮南王安大逆無道，謀反明白，當伏誅。」膠西王端議曰：「安廢法度，行邪辟，〔一〕有詐偽心，以亂天下，營惑百姓，〔二〕背畔宗廟，妄作妖言。春秋曰『臣毋將，將而誅。』安罪重於將，謀反形已定。臣端所見其書印圖及它逆亡道事驗明白，當伏法。論國吏二百石以上及比者，〔三〕宗室近幸臣不在法中者，不能相教，皆當免，〔四〕削爵為士伍，毋得官為吏。其非吏，它贖死金二斤八兩，〔五〕以章安之罪，〔六〕使天下明知臣子之道，毋敢復有邪僻背畔之意。」丞相弘、廷尉湯等以聞，上使宗正以符節治王。未至，安自刑殺。后、太子諸所與謀皆收夷。國除為九江郡。〔七〕","sentenceOrder":144},
  {"id":"s_work_han_thu_55_145","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「辟讀曰僻。下皆類此。」","sentenceOrder":145},
  {"id":"s_work_han_thu_55_146","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　師古曰：「營謂回繞之。」","sentenceOrder":146},
  {"id":"s_work_han_thu_55_147","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　師古曰：「謂真二百石及秩比二百石以上。」","sentenceOrder":147},
  {"id":"s_work_han_thu_55_148","chapterId":"ch_work_han_thu_55","textTraditional":"〔四〕　師古曰：「若本有重罪，自從其法，縱無反狀者，亦皆免。」","sentenceOrder":148},
  {"id":"s_work_han_thu_55_149","chapterId":"ch_work_han_thu_55","textTraditional":"〔五〕　蘇林曰：「非吏故曰它。」師古曰：「為近幸之人，非吏人者。」","sentenceOrder":149},
  {"id":"s_work_han_thu_55_150","chapterId":"ch_work_han_thu_55","textTraditional":"〔六〕　師古曰：「章，明也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_55_151","chapterId":"ch_work_han_thu_55","textTraditional":"〔七〕　師古曰：「夷謂誅滅之。」","sentenceOrder":151},
  {"id":"s_work_han_thu_55_152","chapterId":"ch_work_han_thu_55","textTraditional":"衡山王賜，后乘舒生子三人，長男爽為太子，次女無采，少男孝。姬徐來生子男女四人，美人厥姬生子二人。淮南、衡山相責望禮節，間不相能。〔一〕衡山王聞淮南王作為畔逆具，亦心結賓客以應之，恐為所并。","sentenceOrder":152},
  {"id":"s_work_han_thu_55_153","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「兄弟相責故有嫌。」","sentenceOrder":153},
  {"id":"s_work_han_thu_55_154","chapterId":"ch_work_han_thu_55","textTraditional":"元光六年入朝，謁者衛慶有方術，欲上書事天子，王怒，故劾慶死罪，強榜服之。〔一〕內史以為非是，卻其獄。〔二〕王使人上書告內史，內史治，言王不直。〔三〕又數侵奪人田，壞人冢以為田。有司請逮治衡山王，上不許，為置吏二百石以上。〔四〕衡山王以此恚，與奚慈、張廣昌謀，求能為兵法候星氣者，日夜縱臾王謀反事。〔五〕","sentenceOrder":154},
  {"id":"s_work_han_thu_55_155","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「榜，擊也。擊笞之，令其自服死罪也。榜音彭。」","sentenceOrder":155},
  {"id":"s_work_han_thu_55_156","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　師古曰：「卻，退也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_55_157","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　師古曰：「內史被治而具言王之意狀。」","sentenceOrder":157},
  {"id":"s_work_han_thu_55_158","chapterId":"ch_work_han_thu_55","textTraditional":"〔四〕　如淳曰：「漢儀注吏四百石已下自除國中。今以王之惡，天子皆為置。」","sentenceOrder":158},
  {"id":"s_work_han_thu_55_159","chapterId":"ch_work_han_thu_55","textTraditional":"〔五〕　如淳曰：「臾讀曰勇。縱臾，猶言勉強也。」師古曰：「縱音子勇反。縱臾謂獎勸也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_55_160","chapterId":"ch_work_han_thu_55","textTraditional":"后乘舒死，立徐來為后，厥姬俱幸。兩人相妒，厥姬乃惡徐來於太子，〔一〕曰「徐來使婢蠱殺太子母。」太子心怨徐來。徐來兄至衡山，太子與飲，以刃刑傷之。后以此怨太子，數惡之於王。女弟無采嫁，棄歸，〔二〕與客姦。太子數以數讓之，〔三〕無采怒，不與太子通。后聞之，即善遇無采及孝。孝少失母，附后，后以計愛之，〔四〕與共毀太子，王以故數繫笞太子。元朔四年中，人有賊傷后假母者，〔五〕王疑太子使人傷之，笞太子。後王病，太子時稱病不侍。孝、無采惡太子：「實不病，自言，有喜色。」王於是大怒，欲廢太子而立弟孝。后知王決廢太子，又欲并廢孝。后有侍者善舞，王幸之，后欲令與孝亂以污之，欲并廢二子而以己子廣代之。太子知之，念后數惡己無已時，〔六〕欲與亂以止其口。后飲太子，太子前為壽，因據后股求與臥。后怒，以告王。王乃召，欲縛笞之。太子知王常欲廢己而立孝，乃謂王曰：「孝與王御者姦，無采與奴姦，王強食，請上書。」即背王去。王使人止之，莫能禁，王乃自追捕太子。太子妄惡言，王械繫宮中。","sentenceOrder":160},
  {"id":"s_work_han_thu_55_161","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「惡謂讒毀之也。下皆類此。」","sentenceOrder":161},
  {"id":"s_work_han_thu_55_162","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　師古曰：「為夫所棄而歸也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_55_163","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　師古曰：「上數音所角反，下數音所具反。」","sentenceOrder":163},
  {"id":"s_work_han_thu_55_164","chapterId":"ch_work_han_thu_55","textTraditional":"〔四〕　師古曰：「非心實慈念，但以事計須撫之。」","sentenceOrder":164},
  {"id":"s_work_han_thu_55_165","chapterId":"ch_work_han_thu_55","textTraditional":"〔五〕　師古曰：「繼母也。一曰父之旁妻。」","sentenceOrder":165},
  {"id":"s_work_han_thu_55_166","chapterId":"ch_work_han_thu_55","textTraditional":"〔六〕　師古曰：「已，止也，數見讒譖無休止。」","sentenceOrder":166},
  {"id":"s_work_han_thu_55_167","chapterId":"ch_work_han_thu_55","textTraditional":"孝日益以親幸。王奇孝材能，乃佩之王印，號曰將軍，（今）〔令〕居外家，多給金錢，招致賓客。賓客來者，微知淮南、衡山有逆計，皆將養勸之。〔一〕王乃使孝客江都人枚赫、陳喜作輣車鍛矢，刻天子璽，將、相、軍吏印。王日夜求壯士如周丘等，〔二〕數稱引吳楚反時計畫約束。衡山王非敢效淮南王求即天子位，畏淮南起并其國，以為淮南已西，發兵定江淮間而有之，望如是。","sentenceOrder":167},
  {"id":"s_work_han_thu_55_168","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「將讀曰獎。」","sentenceOrder":168},
  {"id":"s_work_han_thu_55_169","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　師古曰：「下邳人，吳王反時請得漢節下下邳者。」","sentenceOrder":169},
  {"id":"s_work_han_thu_55_170","chapterId":"ch_work_han_thu_55","textTraditional":"元朔五年秋，當朝，六年，過淮南。淮南王乃昆弟語，〔一〕除前隙，約束反具。〔二〕衡山王即上書謝病，上賜不朝。乃使人上書請廢太子爽，立孝為太子。爽聞，即使所善白嬴之長安上書，言衡山王與子謀逆，言孝作兵車鍛矢，與王御者姦。至長安未及上書，即吏捕嬴，以淮南事繫。〔三〕王聞之，恐其言國陰事，即上書告太子，以為不道。事下沛郡治。元狩元年冬，有司求捕與淮南王謀反者，得陳喜於孝家。吏劾孝首匿喜。〔四〕孝以為陳喜雅數與王計反，〔五〕恐其發之，聞律先自告除其罪，又疑太子使白嬴上書發其事，即先自告所與謀反者枚赫、陳喜等。廷尉治，事驗，請逮捕衡山王治。上曰：「勿捕。」遣中尉安、大行息即問王，〔六〕王具以情實對。吏皆圍王宮守之。中尉、大行還，以聞。公卿請遣宗正、大行與沛郡雜治王。王聞，即自殺。孝先自告反，告除其罪。〔七〕孝坐與王御婢姦，及后徐來坐蠱前后乘舒，及太子爽坐告王父不孝，皆棄市。諸坐與王謀反者皆誅。國除為郡。","sentenceOrder":170},
  {"id":"s_work_han_thu_55_171","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「為相親愛之言。」","sentenceOrder":171},
  {"id":"s_work_han_thu_55_172","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　師古曰：「（芺）〔共〕契約為反具。」","sentenceOrder":172},
  {"id":"s_work_han_thu_55_173","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　師古曰：「漢有司捕繫之。」","sentenceOrder":173},
  {"id":"s_work_han_thu_55_174","chapterId":"ch_work_han_thu_55","textTraditional":"〔四〕　師古曰：「為頭首而藏匿之。」","sentenceOrder":174},
  {"id":"s_work_han_thu_55_175","chapterId":"ch_work_han_thu_55","textTraditional":"〔五〕　師古曰：「數音所角反。」","sentenceOrder":175},
  {"id":"s_work_han_thu_55_176","chapterId":"ch_work_han_thu_55","textTraditional":"〔六〕　師古曰：「就問之。」","sentenceOrder":176},
  {"id":"s_work_han_thu_55_177","chapterId":"ch_work_han_thu_55","textTraditional":"〔七〕　師古曰：「先告有反謀，又告人與己反，而自得除反罪。」","sentenceOrder":177},
  {"id":"s_work_han_thu_55_178","chapterId":"ch_work_han_thu_55","textTraditional":"濟北貞王勃者，景帝四年徙。徙二年，因前王衡山，凡十四年薨。子式王胡嗣，五十四年薨。子寬嗣。十二年，寬坐與父式王后光、姬孝兒姦，誖人倫，〔一〕又祠祭祝詛上，有司請誅。上遣大鴻臚利召王，王以刃自剄死。國除為北安縣，屬泰山郡。","sentenceOrder":178},
  {"id":"s_work_han_thu_55_179","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「誖，亂也，音布內反。」","sentenceOrder":179},
  {"id":"s_work_han_thu_55_180","chapterId":"ch_work_han_thu_55","textTraditional":"贊曰：詩云「戎狄是膺，荊舒是懲」，〔一〕信哉是言也！淮南、衡山親為骨肉，疆土千里，列在諸侯，不務遵蕃臣職，以丞輔天子，而剸懷邪辟之計，〔二〕謀為畔逆，仍父子再亡國，〔三〕各不終其身。此非獨王也，亦其俗薄，臣下漸靡使然。〔四〕夫荊楚剽輕，好作亂，乃自古記之矣。〔五〕","sentenceOrder":180},
  {"id":"s_work_han_thu_55_181","chapterId":"ch_work_han_thu_55","textTraditional":"〔一〕　師古曰：「此魯頌閟宮之章也。膺，當也，懲，艾也。荊，楚也。舒，群舒也。言北有戎狄，南有荊舒，土俗彊獷，好為寇亂，常須以兵膺當而懲艾也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_55_182","chapterId":"ch_work_han_thu_55","textTraditional":"〔二〕　師古曰：「剸與專同，音之兗反。」","sentenceOrder":182},
  {"id":"s_work_han_thu_55_183","chapterId":"ch_work_han_thu_55","textTraditional":"〔三〕　師古曰：「仍，頻也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_55_184","chapterId":"ch_work_han_thu_55","textTraditional":"〔四〕　師古曰：「靡謂相隨從。」","sentenceOrder":184},
  {"id":"s_work_han_thu_55_185","chapterId":"ch_work_han_thu_55","textTraditional":"〔五〕　師古曰：「剽音匹妙反。」","sentenceOrder":185},
  {"id":"s_work_han_thu_55_186","chapterId":"ch_work_han_thu_55","textTraditional":"校勘記","sentenceOrder":186},
  {"id":"s_work_han_thu_55_187","chapterId":"ch_work_han_thu_55","textTraditional":"二一三八頁　五行　野戰（次）〔攻〕城。　錢大昭說「次」當作「攻」。按景祐、殿、局本都作「攻」。","sentenceOrder":187},
  {"id":"s_work_han_thu_55_188","chapterId":"ch_work_han_thu_55","textTraditional":"二一三八頁一０行　觸情妄行，不（詳）〔祥〕。　景祐、殿本都作「祥」。","sentenceOrder":188},
  {"id":"s_work_han_thu_55_189","chapterId":"ch_work_han_thu_55","textTraditional":"二一三九頁　八行　諸從蠻夷來歸誼及以亡名數自（古）〔占〕者，景祐、殿、局本都「占」。此誤。","sentenceOrder":189},
  {"id":"s_work_han_thu_55_190","chapterId":"ch_work_han_thu_55","textTraditional":"二一四四頁一四行　吳使者至淮南，（淮南）王欲發兵應之。　錢大昭說「淮南」二字閩本不重。按景祐、殿本都不重。","sentenceOrder":190},
  {"id":"s_work_han_thu_55_191","chapterId":"ch_work_han_thu_55","textTraditional":"二一四五頁　五行　此蟲達之子耳，名（揵）〔捷〕。　景祐本作「捷」，與功臣表同。","sentenceOrder":191},
  {"id":"s_work_han_thu_55_192","chapterId":"ch_work_han_thu_55","textTraditional":"二一五五頁一０行　號曰將軍，（今）〔令〕居外家，　景祐、殿、局本都作「令」。","sentenceOrder":192},
  {"id":"s_work_han_thu_55_193","chapterId":"ch_work_han_thu_55","textTraditional":"二一五六頁一二行　（芺）〔共〕契約為反具。　景祐、殿、局本都作「共」。王先謙說作「共」是。","sentenceOrder":193},
  {"id":"s_work_han_thu_56_1","chapterId":"ch_work_han_thu_56","textTraditional":"蒯通，范陽人也，〔一〕本與武帝同諱。〔二〕楚漢初起，武臣略定趙地，號武信君。通說范陽令徐公曰：「臣，范陽百姓蒯通也，竊閔公之將死，故弔之。雖然，賀公得通而生也。」徐公再拜曰：「何以弔之？」通曰：「足下為令十餘年矣，殺人之父，孤人之子，斷人之足，黥人之首，甚眾。慈父孝子所以不敢事刃於公之腹者，畏秦法也。〔三〕今天下大亂，秦政不施，〔四〕然則慈父孝子將爭接刃於公之腹，以復其怨而成其（功）名。〔五〕此通之所以弔者也。」曰：「何以賀得子而生也？」曰：「趙武信君不知通不肖，使人候問其死生，通且見武信君而說之，〔六〕曰：『必將戰勝而後略地，攻得而後下城，臣竊以為殆矣。〔七〕用臣之計，毋戰而略地，不攻而下城，傳檄而千里定，可乎？』彼將曰：『何謂也？』〔八〕臣因對曰：『范陽令宜整頓其士卒以守戰者也，怯而畏死，貪而好富貴，故欲以其城先下君。先下君而君不利〔之〕，則邊地之城皆將相告曰「范陽令先降而身死」，必將嬰城固守，〔九〕皆為金城湯池，不可攻也。〔一０〕為君計者，莫若以黃屋朱輪迎范陽令，使馳騖於燕趙之郊，〔二〕則邊城皆將相告曰「范陽令先下而身富貴」，必相率而降，猶如阪上走丸也。〔一二〕此臣所謂傳檄而千里定者也。』」徐公再拜，具車馬遣通。通遂以此說武臣。武臣以車百乘，騎二百，侯印迎徐公。燕趙聞之，降者三十餘城，如通策焉。","sentenceOrder":1},
  {"id":"s_work_han_thu_56_2","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「涿郡之縣也，舊屬燕。通本燕人，後游於齊，故高祖云齊辯士蒯通。」","sentenceOrder":2},
  {"id":"s_work_han_thu_56_3","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「本名為徹，其後史家追書為通。」","sentenceOrder":3},
  {"id":"s_work_han_thu_56_4","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　李奇曰：「東方人以物臿地中為事。」師古曰：「事音側吏反。字本作倳，周官考工記又作菑，音皆同耳。」","sentenceOrder":4},
  {"id":"s_work_han_thu_56_5","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「施，設也，立也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_56_6","chapterId":"ch_work_han_thu_56","textTraditional":"〔五〕　師古曰：「復猶報也，音扶目反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_56_7","chapterId":"ch_work_han_thu_56","textTraditional":"〔六〕　師古曰：「今將欲見之。」","sentenceOrder":7},
  {"id":"s_work_han_thu_56_8","chapterId":"ch_work_han_thu_56","textTraditional":"〔七〕　師古曰：「殆，危也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_56_9","chapterId":"ch_work_han_thu_56","textTraditional":"〔八〕　師古曰：「彼謂武信君也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_56_10","chapterId":"ch_work_han_thu_56","textTraditional":"〔九〕　孟康曰：「嬰，以城自繞。」","sentenceOrder":10},
  {"id":"s_work_han_thu_56_11","chapterId":"ch_work_han_thu_56","textTraditional":"〔一０〕師古曰：「金以喻堅，湯喻沸熱不可近。」","sentenceOrder":11},
  {"id":"s_work_han_thu_56_12","chapterId":"ch_work_han_thu_56","textTraditional":"〔一一〕師古曰：「令眾皆見。」","sentenceOrder":12},
  {"id":"s_work_han_thu_56_13","chapterId":"ch_work_han_thu_56","textTraditional":"〔一二〕師古曰：「言乘勢便易。」","sentenceOrder":13},
  {"id":"s_work_han_thu_56_14","chapterId":"ch_work_han_thu_56","textTraditional":"後漢將韓信虜魏王，破趙、代，降燕，定三國，引兵將東擊齊。未度平原，聞漢王使酈食其說下齊，信欲止。通說信曰：「將軍受詔擊齊，而漢獨發間使下齊，寧有詔止將軍乎？〔一〕何以得無行！且酈生一士，伏軾掉三寸舌，下齊七十餘城，〔二〕將軍將數萬之眾，乃下趙五十餘城。為將數歲，反不如一豎儒之功乎！」於是信然之，從其計，遂度河。齊巳聽酈生，即留之縱酒，罷備漢守禦。信因襲歷下軍，遂至臨菑。齊王以酈生為欺己而亨之，因敗走。信遂定齊地，自立為齊假王。漢方困於滎陽，遣張良即立信為齊王，以安固之。項王亦遣武涉說信，欲與連和。","sentenceOrder":14},
  {"id":"s_work_han_thu_56_15","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「間使，謂使人伺間隙而單行。」","sentenceOrder":15},
  {"id":"s_work_han_thu_56_16","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「掉，搖也，音徒釣反。」","sentenceOrder":16},
  {"id":"s_work_han_thu_56_17","chapterId":"ch_work_han_thu_56","textTraditional":"蒯通知天下權在信，欲說信令背漢，乃先微感信曰：「僕嘗受相人之術，相君之面，不過封侯，又危而不安；相君之背，貴而不可言。」〔一〕信曰：「何謂也？」通因請間，〔二〕曰：「天下初作難也，俊雄豪桀建號壹呼，〔三〕天下之士雲合霧集，魚鱗雜襲，〔四〕飄至風起。〔五〕當此之時，憂在亡秦而已。〔六〕今劉、項分爭，使人肝腦塗地，流離中野，不可勝數。漢王將數十萬眾，距鞏、雒，岨山河，一日數戰，無尺寸之功，折北不救，〔七〕敗滎陽，傷成皋，〔八〕還走宛、葉之間，此所謂智勇俱困者也。楚人起彭城，轉鬥逐北，至滎陽，乘利席勝，威震天下，〔九〕然兵困於京、索之間，〔一０〕迫西山而不能進，三年於此矣。〔一一〕銳氣挫於嶮塞，粮食盡於內藏，百姓罷極，無所歸命。〔一二〕以臣料之，〔一三〕非天下賢聖，其勢固不能息天下之禍。當今之時，兩主縣命足下。足下為漢則漢勝，與楚則楚勝。臣願披心腹，墮肝膽，〔一四〕效愚忠，恐足下不能用也。方今為足下計，莫若兩利而俱存之，參分天下，鼎足而立，其勢莫敢先動。夫以足下之賢聖，有甲兵之眾，據彊齊，從燕、趙，出空虛之地以制其後，因民之欲，西鄉為百姓請命，〔一五〕天下孰敢不聽！足下按齊國之故，有淮泗之地，懷諸侯以德，深拱揖讓，〔一六〕則天下君王相率而朝齊矣。蓋聞『天與弗取，反受其咎；時至弗行，反受其殃。』願足下孰圖之。」","sentenceOrder":17},
  {"id":"s_work_han_thu_56_18","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　張晏曰：「言背者，云背畔則大貴。」","sentenceOrder":18},
  {"id":"s_work_han_thu_56_19","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「不欲顯言，故請間隙而私說。」","sentenceOrder":19},
  {"id":"s_work_han_thu_56_20","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　師古曰：「建號者，自立為侯王。呼音火故反。」","sentenceOrder":20},
  {"id":"s_work_han_thu_56_21","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「雜襲猶雜沓，言相雜而累積。」","sentenceOrder":21},
  {"id":"s_work_han_thu_56_22","chapterId":"ch_work_han_thu_56","textTraditional":"〔五〕　師古曰：「飄讀曰焱，謂疾風，音必遙反。」","sentenceOrder":22},
  {"id":"s_work_han_thu_56_23","chapterId":"ch_work_han_thu_56","textTraditional":"〔六〕　師古曰：「志滅秦，所憂者唯此。」","sentenceOrder":23},
  {"id":"s_work_han_thu_56_24","chapterId":"ch_work_han_thu_56","textTraditional":"〔七〕　師古曰：「折，挫也。北，奔也。不救，謂無援助也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_56_25","chapterId":"ch_work_han_thu_56","textTraditional":"〔八〕　張晏曰：「於成皋戰傷胸也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_56_26","chapterId":"ch_work_han_thu_56","textTraditional":"〔九〕　師古曰：「席，因也，若人之在席上。」","sentenceOrder":26},
  {"id":"s_work_han_thu_56_27","chapterId":"ch_work_han_thu_56","textTraditional":"〔一０〕師古曰：「索音山客反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_56_28","chapterId":"ch_work_han_thu_56","textTraditional":"〔一一〕師古曰：「至今已三年。」","sentenceOrder":28},
  {"id":"s_work_han_thu_56_29","chapterId":"ch_work_han_thu_56","textTraditional":"〔一二〕師古曰：「罷讀曰疲。」","sentenceOrder":29},
  {"id":"s_work_han_thu_56_30","chapterId":"ch_work_han_thu_56","textTraditional":"〔一三〕師古曰：「料，量也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_56_31","chapterId":"ch_work_han_thu_56","textTraditional":"〔一四〕師古曰：「墮，毀也，音火規反。」","sentenceOrder":31},
  {"id":"s_work_han_thu_56_32","chapterId":"ch_work_han_thu_56","textTraditional":"〔一五〕師古曰：「鄉讀曰嚮。齊國在東，故曰西嚮。止楚漢之戰鬥，士卒不死亡，故云請命。」","sentenceOrder":32},
  {"id":"s_work_han_thu_56_33","chapterId":"ch_work_han_thu_56","textTraditional":"〔一六〕師古曰：「深拱猶高拱。」","sentenceOrder":33},
  {"id":"s_work_han_thu_56_34","chapterId":"ch_work_han_thu_56","textTraditional":"信曰：「漢遇我厚，吾豈可見利而背恩乎！」通曰：「始常山王、成安君故相與為刎頸之交，及爭張黶、陳釋之事，〔一〕常山王奉頭鼠竄，以歸漢王。〔二〕借兵東下，戰於鄗北，成安君死於泜水之南，〔三〕頭足異處。此二人相與，天下之至驩也，而卒相滅亡者，何也？患生於多欲而人心難測也。今足下行忠信以交於漢王，必不能固於二君之相與也，而事多大於張黶、陳釋之事者，故臣以為足下必漢王之不危足下，過矣。〔四〕大夫種存亡越，伯句踐，〔五〕立功名而身死。語曰：『野禽殫，走犬亨；〔六〕敵國破，謀臣亡。』故以交友言之，則不過張王與成安君；以忠臣言之，則不過大夫種。此二者，宜足以觀矣。願足下深慮之。且臣聞之，勇略震主者身危，功蓋天下者不賞。足下涉西河，虜魏王，禽夏說，〔七〕下井陘，誅成安君之罪，以令於趙，脅燕定齊，南摧楚人之兵數十萬眾，遂斬龍且，西鄉以報，〔八〕此所謂功無二於天下，略不世出者也。〔九〕今足下挾不賞之功，戴震主之威，歸楚，楚人不信；歸漢，漢人震恐。足下欲持是安歸乎？〔一０〕夫勢在人臣之位，而有高天下之名，切為足下危之。」信曰：「生且休矣，吾將念之。」〔一一〕","sentenceOrder":34},
  {"id":"s_work_han_thu_56_35","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「黶音一點反。」","sentenceOrder":35},
  {"id":"s_work_han_thu_56_36","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「言其迫窘逃亡，如鼠之藏竄。」","sentenceOrder":36},
  {"id":"s_work_han_thu_56_37","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　師古曰：「鄗音呼各反。泜音祗，又音丁計反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_56_38","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「過猶誤也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_56_39","chapterId":"ch_work_han_thu_56","textTraditional":"〔五〕　師古曰：「令句踐致霸功也。伯讀曰霸。」","sentenceOrder":39},
  {"id":"s_work_han_thu_56_40","chapterId":"ch_work_han_thu_56","textTraditional":"〔六〕　師古曰：「殫，盡也，音單。」","sentenceOrder":40},
  {"id":"s_work_han_thu_56_41","chapterId":"ch_work_han_thu_56","textTraditional":"〔七〕　師古曰：「說讀曰悅。」","sentenceOrder":41},
  {"id":"s_work_han_thu_56_42","chapterId":"ch_work_han_thu_56","textTraditional":"〔八〕　師古曰：「且音子餘反。鄉讀曰嚮。」","sentenceOrder":42},
  {"id":"s_work_han_thu_56_43","chapterId":"ch_work_han_thu_56","textTraditional":"〔九〕　師古曰：「言其計略奇異，世所希有。」","sentenceOrder":43},
  {"id":"s_work_han_thu_56_44","chapterId":"ch_work_han_thu_56","textTraditional":"〔一０〕師古曰：「安，焉也。此下亦同。」","sentenceOrder":44},
  {"id":"s_work_han_thu_56_45","chapterId":"ch_work_han_thu_56","textTraditional":"〔一一〕師古曰：「念猶思也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_56_46","chapterId":"ch_work_han_thu_56","textTraditional":"數日，通復說曰：「聽者，事之候也；〔一〕計者，存亡之機也。夫隨廝養之役者，失萬乘之權；守儋石之祿者，闕卿相之位。〔二〕計誠知之，而決弗敢行者，百事之禍也。故猛虎之猶與，不如蜂蠆之致蠚；〔三〕孟賁之狐疑，不如童子之必至。〔四〕此言貴能行之也。夫功者難成而易敗，時者難值而易失。『時乎時，不再來。〔五〕』願足下無疑臣之計。」信猶與不忍背漢，又自以功多，漢不奪我齊，遂謝通。〔六〕通說不聽，惶恐，乃陽狂為巫。","sentenceOrder":46},
  {"id":"s_work_han_thu_56_47","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「謂能聽善謀也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_56_48","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　應劭曰：「齊人名小甖為儋，受二斛。」晉灼曰：「石，斗石也。」師古曰：「儋音都濫反。或曰，儋者，一人之所負擔也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_56_49","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　師古曰：「與讀曰預。蠆，蝎也。蠚，毒也。蠆音丑界反。蠚音呼各反。」","sentenceOrder":49},
  {"id":"s_work_han_thu_56_50","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「孟賁，古之勇力士。賁音奔。」","sentenceOrder":50},
  {"id":"s_work_han_thu_56_51","chapterId":"ch_work_han_thu_56","textTraditional":"〔五〕　師古曰：「此古語，歎時之不可失。」","sentenceOrder":51},
  {"id":"s_work_han_thu_56_52","chapterId":"ch_work_han_thu_56","textTraditional":"〔六〕　師古曰：「告令罷去。」","sentenceOrder":52},
  {"id":"s_work_han_thu_56_53","chapterId":"ch_work_han_thu_56","textTraditional":"天下既定，後信以罪廢為淮陰侯，謀反被誅，臨死歎曰：「悔不用蒯通之言，死於女子之手！」高帝曰：「是齊辯士蒯通。」乃詔齊召蒯通。通至，上欲亨之，曰：「若教韓信反，何也？」〔一〕通曰：「狗各吠非其主。當彼時，臣獨知齊王韓信，　非知陛下也。且秦失其鹿，〔二〕天下共逐之，高材者先得。天下匈匈，爭欲為陛下所為，顧力不能，〔三〕可殫誅邪！」〔四〕上乃赦之。","sentenceOrder":53},
  {"id":"s_work_han_thu_56_54","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「若，汝也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_56_55","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　張晏曰：「以鹿喻帝位。」","sentenceOrder":55},
  {"id":"s_work_han_thu_56_56","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　師古曰：「顧，念也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_56_57","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「殫，盡也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_56_58","chapterId":"ch_work_han_thu_56","textTraditional":"至齊悼惠王時，曹參為相，禮下賢人，請通為客。","sentenceOrder":58},
  {"id":"s_work_han_thu_56_59","chapterId":"ch_work_han_thu_56","textTraditional":"初，齊王田榮怨項羽，謀舉兵畔之，劫齊士，不與者死。〔一〕齊處士東郭先生、梁石君在劫中，強從。及田榮敗，二人醜之，〔二〕相與入深山隱居。客謂通曰：「先生之於曹相國，拾遺舉過，顯賢進能，齊國莫若先生者。先生知梁石君、東郭先生世俗所不及，何不進之於相國乎？」通曰：「諾。臣之里婦，與里之諸母相善也。里婦夜亡肉，姑以為盜，怒而逐之。婦晨去，過所善諸母，語以事而謝之。〔三〕里母曰：『女安行，〔四〕我今令而家追女矣。』〔五〕即束縕請火於亡肉家，〔六〕曰：『昨暮夜，犬得肉，爭鬥相殺，請火治之。』〔七〕亡肉家遽追呼其婦。〔八〕故里母非談說之士也，束縕乞火非還婦之道也，然物有相感，事有適可。臣請乞火於曹相國。」乃見相國曰：「婦人有夫死三日而嫁者，有幽居守寡不出門者，足下即欲求婦，何取？」曰：「取不嫁者。」通曰：「然則求臣亦猶是也，彼東郭先生、梁石君，齊之俊士也，隱居不嫁，未嘗卑節下意以求仕也。願足下使人禮之。」曹相國曰：「敬受命。」皆以為上賓。","sentenceOrder":59},
  {"id":"s_work_han_thu_56_60","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「劫而取之，不從則殺也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_56_61","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「自恥從亂，以為醜惡也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_56_62","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　師古曰：「謝謂告辭也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_56_63","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「安，徐也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_56_64","chapterId":"ch_work_han_thu_56","textTraditional":"〔五〕　師古曰：「而，亦汝。」","sentenceOrder":64},
  {"id":"s_work_han_thu_56_65","chapterId":"ch_work_han_thu_56","textTraditional":"〔六〕　師古曰：「縕，亂麻，音於粉反。」","sentenceOrder":65},
  {"id":"s_work_han_thu_56_66","chapterId":"ch_work_han_thu_56","textTraditional":"〔七〕　師古曰：「治謂燖治死犬。燖音似廉反。」","sentenceOrder":66},
  {"id":"s_work_han_thu_56_67","chapterId":"ch_work_han_thu_56","textTraditional":"〔八〕　師古曰：「遽，速也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_56_68","chapterId":"ch_work_han_thu_56","textTraditional":"通論戰國時說士權變，亦自序其說，凡八十一首，號曰雋永〔一〕。","sentenceOrder":68},
  {"id":"s_work_han_thu_56_69","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「雋音字兗反。雋，肥肉也。永，長也。言其所論甘美，而義深長也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_56_70","chapterId":"ch_work_han_thu_56","textTraditional":"初，通善齊人安其生，安其生嘗干項羽，羽不能用其策。而項羽欲封此兩人，兩人卒不肯受。","sentenceOrder":70},
  {"id":"s_work_han_thu_56_71","chapterId":"ch_work_han_thu_56","textTraditional":"伍被，楚人也。〔一〕或言其先伍子胥後也。被以材能稱，為淮南中郎。是時淮南王安好術學，折節下士，招致英雋以百數，被為冠首。〔二〕","sentenceOrder":71},
  {"id":"s_work_han_thu_56_72","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「被音皮義反。」","sentenceOrder":72},
  {"id":"s_work_han_thu_56_73","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「最居其上也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_56_74","chapterId":"ch_work_han_thu_56","textTraditional":"久之，淮南王陰有邪謀，被數微諫。〔一〕後王坐東宮，召被欲與計事，呼之曰：「將軍上。」被曰：「王安得亡國之言乎？昔子胥諫吳王，吳王不用，乃曰『臣今見麋鹿游姑蘇之臺也。』〔二〕今臣亦將見宮中生荊棘，露霑衣也。」於是王怒，繫被父母，囚之三月。","sentenceOrder":74},
  {"id":"s_work_han_thu_56_75","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「私諫之。」","sentenceOrder":75},
  {"id":"s_work_han_thu_56_76","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　張晏曰：「吳臺名也。」師古曰：「吳地記云因山為名，西南去國三十五里。」","sentenceOrder":76},
  {"id":"s_work_han_thu_56_77","chapterId":"ch_work_han_thu_56","textTraditional":"王復召被曰：「將軍許寡人乎？」（對）〔被〕曰：「不，臣將為大王畫計耳。臣聞聰者聽於無聲，明者見於未形，〔一〕故聖人萬舉而萬全。文王壹動而功顯萬世，列為三王，所謂因天心以動作者也。」王曰：「方今漢庭治乎？亂乎？」被曰：「天下治。」王不說〔二〕曰：「公何以言治也？」被對曰：「被竊觀朝廷，君臣父子夫婦長幼之序皆得其理，上之舉錯遵古之道，〔三〕風俗紀綱未有所缺。重裝富賈周流天下，道無不通，交易之道行。南越賓服，羌、僰貢獻，東甌入朝，〔四〕廣長榆，〔五〕開朔方，匈奴折傷。雖未及古太平時，然猶為治。」王怒，被謝死罪。","sentenceOrder":77},
  {"id":"s_work_han_thu_56_78","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「言智慮通達，事未形兆，皆預見之。」","sentenceOrder":78},
  {"id":"s_work_han_thu_56_79","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":79},
  {"id":"s_work_han_thu_56_80","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　師古曰：「錯音千故反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_56_81","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「僰，西南夷也，音蒲北反。」","sentenceOrder":81},
  {"id":"s_work_han_thu_56_82","chapterId":"ch_work_han_thu_56","textTraditional":"〔五〕　如淳曰：「廣謂斥大之也。長榆，塞名，王恢所謂樹榆以為塞者也。」師古曰：「長榆在朔方，即衛青傳所云榆谿舊塞是也。或謂之榆中。」","sentenceOrder":82},
  {"id":"s_work_han_thu_56_83","chapterId":"ch_work_han_thu_56","textTraditional":"王又曰：「山東即有變，漢必使大將軍將而制山東，公以為大將軍何如人也？」被曰：「臣所善黃義，從大將軍擊匈奴，言大將軍遇士大夫以禮，與士卒有恩，眾皆樂為用。騎上下山如飛，材力絕人如此，數將習兵，未易當也。及謁者曹梁使長安來，言大將軍號令明，當敵勇，常為士卒先；須士卒休，乃舍；穿井得水，乃敢飲；軍罷，士卒已踰河，乃度。皇太后所賜金錢，盡以賞賜。雖古名將不過也。」王曰：「夫蓼太子〔一〕知略不世出，非常人也，以為漢廷公卿列侯皆如沐猴而冠耳。」被曰：「獨先刺大將軍，乃可舉事。」","sentenceOrder":83},
  {"id":"s_work_han_thu_56_84","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　服虔曰：「淮南太子也。」文穎曰：「食采於此，或言外家姓也。」師古曰：「蓼自地名，而王之太子豈以食地為號？文言外家姓，近為得之，亦猶漢之栗太子也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_56_85","chapterId":"ch_work_han_thu_56","textTraditional":"王復問被曰：「公以為吳舉兵非邪？」被曰：「非也。夫吳王賜號為劉氏祭酒，〔一〕受几杖而不朝，王四郡之眾，地方數千里，采山銅以為錢，煮海水以為鹽，伐江陵之木以為船，國富民眾，行珍寶，賂諸侯，與七國合從，舉兵而西，破大梁，敗狐父，〔二〕奔走而還，為越所禽，死於丹徒，〔三〕頭足異處，身滅祀絕，為天下戮。〔四〕夫以吳眾不能成功者，何也？誠逆天違眾而不見時也。」王曰：「男子之所死者，一言耳。〔五〕且吳何知反？漢將一日過成皋者四十餘人。〔六〕今我令緩先要成皋之口，〔七〕周被下潁川兵塞轘轅、伊闕之道，陳定發南陽兵守武關。河南太守獨有雒陽耳，〔八〕何足憂？然此北尚有臨晉關、河東、上黨與河內、趙國界者通谷數行。〔九〕人言『絕成皋之道，天下不通』。據三川之險，招天下之兵，公以為何如？」被曰：「臣見其禍，未見其福也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_56_86","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　應劭曰：「禮，飲酒必祭，示有先也，故稱祭酒，尊之也。」如淳曰：「祭祠時唯尊長者以酒沃酹。」師古曰：「如說是也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_56_87","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「在梁、碭之間也。父音甫。」","sentenceOrder":87},
  {"id":"s_work_han_thu_56_88","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　師古曰：「即今潤州丹徒縣也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_56_89","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「天下之人皆共戮之。一曰天下之大戮也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_56_90","chapterId":"ch_work_han_thu_56","textTraditional":"〔五〕　張晏曰：「不成即死，一言耳。」臣瓚曰：「或有一言，云以死報也。」師古曰：「二說死，並非也。言男子感氣，相許一言，不顧其死。或曰，一言之恨，不顧危亡，以此致死也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_56_91","chapterId":"ch_work_han_thu_56","textTraditional":"〔六〕　師古曰：「言不知塞成皋口，而令漢將得出之，是不知反計也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_56_92","chapterId":"ch_work_han_thu_56","textTraditional":"〔七〕　韋昭曰：「淮南臣名也。」師古曰：「緩者，名也，不言其姓。今流俗書本於緩上妄加樓字，非也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_56_93","chapterId":"ch_work_han_thu_56","textTraditional":"〔八〕　師古曰：「如此計，則漢河南郡唯有雒陽在耳，餘皆不屬。」","sentenceOrder":93},
  {"id":"s_work_han_thu_56_94","chapterId":"ch_work_han_thu_56","textTraditional":"〔九〕　如淳曰：「言此北尚嶮阻，其谿谷可得通行者有數處。」","sentenceOrder":94},
  {"id":"s_work_han_thu_56_95","chapterId":"ch_work_han_thu_56","textTraditional":"後漢逮淮南王孫建，繫治之。王恐陰事泄，謂被曰：「事至，吾欲遂發。天下勞苦有間矣，〔一〕諸侯頗有失行，皆自疑，我舉兵西鄉，必有應者；〔二〕無應，即還略衡山。勢不得不發。」被曰：「略衡山以擊（盧）〔廬〕江，有尋陽之船，守下雉之城，〔三〕結九江之浦，絕豫章之口，強弩臨江而守，以禁南郡之下，東保會稽，南通勁越，屈強江淮間，〔四〕可以延歲月之壽耳，未見其福也。」王曰：「左吳、趙賢、朱驕如皆以為什八九成，〔五〕公獨以為無福，何？」被曰：「大王之群臣近幸素能使眾者，皆前繫詔獄，餘無可用者。」王曰：「陳勝、吳廣無立錐之地，百人之聚，起於大澤，奮臂大呼，天下嚮應，〔六〕西至於戲而兵百二十萬。今吾國雖小，勝兵可得二十萬，公何以言有禍無福？」被曰：「臣不敢避子胥之誅，願大王無為吳王之聽。往者秦為無道，殘賊天下，殺術士，燔詩書，滅聖跡，棄禮義，任刑法，轉海濱之粟，致于西河。〔七〕當是之時，男子疾耕不足於糧餽，〔八〕女子紡績不足於蓋形。遣蒙恬築長城，東西數千里。暴兵露師，常數十萬，死者不可勝數，僵尸滿野，流血千里。於是百姓力屈，〔九〕欲為亂者十室而五。又使徐福入海求仙藥，多齎珍寶，童男女三千人，五種百工而行。〔一０〕徐福得平原大澤，止王不來。於是百姓悲痛愁思，欲為亂者十室而六。又使尉佗踰五嶺，攻百越，〔一一〕尉佗知中國勞極，止王南越。〔一二〕行者不還，往者莫返，於是百姓離心瓦解，欲為亂者十室而七。興萬乘之駕，作阿房之宮，收太半之賦，發閭左之戍。〔一三〕父不寧子，兄不安弟，〔一四〕政苛刑慘，民皆引領而望，傾耳而聽，悲號仰天，叩心怨上，〔一五〕欲為亂者，十室而八。客謂高皇帝曰：『時可矣。』高帝曰：『待之，聖人當起東南。』間不一歲，陳、吳大呼，〔一六〕劉、項並和，天下嚮應，〔一七〕所謂蹈瑕釁，因秦之亡時而動，百姓願之，若枯旱之望雨，故起於行陳之中，以成帝王之功。今大王見高祖得天下之易也，獨不觀近世之吳楚乎！當今陛下臨制天下，壹齊海內，氾愛蒸庶，〔一八〕布德施惠。口雖未言，聲疾雷震；令雖未出，化馳如神。心有所懷，威動千里；下之應上，猶景嚮也。〔一九〕而大將軍材能非直章邯、楊熊也。王以陳勝、吳廣論之，被以為過矣。〔二０〕且大王之兵眾不能什分吳楚之一，天下安寧又萬倍於秦時。願王用臣之計。臣聞箕子過故國而悲，作麥秀之歌〔二一〕，痛紂之不用王子比干之言也。故孟子曰，紂貴為天子，死曾不如匹夫。是紂先自絕久矣，非死之日天去之也。今臣亦竊悲大王棄千乘之君，將賜絕命之書，為群臣先，〔二二〕身死于東宮也。」〔二三〕被因流涕而起。","sentenceOrder":95},
  {"id":"s_work_han_thu_56_96","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　如淳曰：「言天下勞苦，人心有間隙，易動亂。」師古曰：「此說非也。有間，猶言中間已有也。故謂此者乃為間也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_56_97","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":97},
  {"id":"s_work_han_thu_56_98","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　孟康曰：「下雉，江夏縣名。」師古曰：「雉音羊氏反。」","sentenceOrder":98},
  {"id":"s_work_han_thu_56_99","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「屈音具勿反。」","sentenceOrder":99},
  {"id":"s_work_han_thu_56_100","chapterId":"ch_work_han_thu_56","textTraditional":"〔五〕　師古曰：「吳、賢、驕如，王之三臣也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_56_101","chapterId":"ch_work_han_thu_56","textTraditional":"〔六〕　師古曰：「呼音火故反。嚮讀曰響。」","sentenceOrder":101},
  {"id":"s_work_han_thu_56_102","chapterId":"ch_work_han_thu_56","textTraditional":"〔七〕　師古曰：「瀕，涯也。海濱謂緣海涯之地。瀕音頻，又音賓。」","sentenceOrder":102},
  {"id":"s_work_han_thu_56_103","chapterId":"ch_work_han_thu_56","textTraditional":"〔八〕　師古曰：「餽亦饋字也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_56_104","chapterId":"ch_work_han_thu_56","textTraditional":"〔九〕　師古曰：「屈，盡也，音其勿反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_56_105","chapterId":"ch_work_han_thu_56","textTraditional":"〔一０〕師古曰：「五種，五穀之種也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_56_106","chapterId":"ch_work_han_thu_56","textTraditional":"〔一一〕師古曰：「五嶺解在張耳傳。」","sentenceOrder":106},
  {"id":"s_work_han_thu_56_107","chapterId":"ch_work_han_thu_56","textTraditional":"〔一二〕師古曰：「南越傳云南海尉任囂謂趙佗曰『聞陳勝等作亂，豪桀叛秦相立』，即被佗書行南海尉事。囂死後，佗始自為王。今此乃言尉佗先王，陳勝乃反，此蓋伍被一時對辭，不究其實也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_56_108","chapterId":"ch_work_han_thu_56","textTraditional":"〔一三〕師古曰：「閭左解在食貨志。」","sentenceOrder":108},
  {"id":"s_work_han_thu_56_109","chapterId":"ch_work_han_thu_56","textTraditional":"〔一四〕師古曰：「言不能相保。」","sentenceOrder":109},
  {"id":"s_work_han_thu_56_110","chapterId":"ch_work_han_thu_56","textTraditional":"〔一五〕師古曰：「叩，擊也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_56_111","chapterId":"ch_work_han_thu_56","textTraditional":"〔一六〕師古曰：「中間不經一歲也。呼音火故反。」","sentenceOrder":111},
  {"id":"s_work_han_thu_56_112","chapterId":"ch_work_han_thu_56","textTraditional":"〔一七〕師古曰：「和音胡（計）〔臥〕反。嚮讀曰響。」","sentenceOrder":112},
  {"id":"s_work_han_thu_56_113","chapterId":"ch_work_han_thu_56","textTraditional":"〔一八〕師古曰：「氾，普也。蒸亦眾也。氾音敷劍反。」","sentenceOrder":113},
  {"id":"s_work_han_thu_56_114","chapterId":"ch_work_han_thu_56","textTraditional":"〔一九〕師古曰：「言如影之隨形，響之應聲。嚮讀曰響。」","sentenceOrder":114},
  {"id":"s_work_han_thu_56_115","chapterId":"ch_work_han_thu_56","textTraditional":"〔二０〕師古曰：「過，誤也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_56_116","chapterId":"ch_work_han_thu_56","textTraditional":"〔二一〕張晏曰：「箕子將朝周，過殷故都，見麥及禾黍，心悲，乃作歌曰：『麥秀之漸漸兮，黍苗之繩繩兮，彼狡童兮，不與我好兮。』狡童謂紂也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_56_117","chapterId":"ch_work_han_thu_56","textTraditional":"〔二二〕師古曰：「在群臣先死。」","sentenceOrder":117},
  {"id":"s_work_han_thu_56_118","chapterId":"ch_work_han_thu_56","textTraditional":"〔二三〕如淳曰：「王時所居也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_56_119","chapterId":"ch_work_han_thu_56","textTraditional":"後王復召問被：「苟如公言，不可以徼幸邪？」〔一〕被曰：「必不得已，被有愚計。」王曰：「柰何？」被曰：「當今諸侯無異心，百姓無怨氣。朔方之郡土地廣美，民徙者不足以實其地。可為丞相、御史請書，〔二〕徙郡國豪桀及耐罪以上，以赦令除，家產五十萬以上者，皆徙其家屬朔方之郡，〔三〕益發甲卒，急其會日。〔四〕又偽為左右都司空上林中都官詔獄書，〔五〕逮諸侯太子及幸臣〔六〕。如此，則民怨，諸侯懼，即使辯士隨而說之，黨可以徼幸。〔七〕」王曰：「此可也。雖然，吾以不至若此，專發而已。」〔八〕後事發覺，被詣吏自告與淮南王謀反（縱）〔蹤〕跡如此。天子以伍被雅辭多引漢美，欲勿誅。張湯進曰：「被首為王畫反計，罪無赦。」遂誅被。","sentenceOrder":119},
  {"id":"s_work_han_thu_56_120","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「徼，要也。幸，非望之福也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_56_121","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「謂詐為此文書，令徙人也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_56_122","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　師古曰：「以赦令除，謂遇赦免罪者。」","sentenceOrder":122},
  {"id":"s_work_han_thu_56_123","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「促其期日。」","sentenceOrder":123},
  {"id":"s_work_han_thu_56_124","chapterId":"ch_work_han_thu_56","textTraditional":"〔五〕　晉灼曰：「百官表宗正有左右都司空，上林有水司空；皆主囚徒官也。」師古曰：「中都官，京師諸官府。」","sentenceOrder":124},
  {"id":"s_work_han_thu_56_125","chapterId":"ch_work_han_thu_56","textTraditional":"〔六〕　師古曰：「追對獄。」","sentenceOrder":125},
  {"id":"s_work_han_thu_56_126","chapterId":"ch_work_han_thu_56","textTraditional":"〔七〕　師古曰：「黨讀曰儻。」","sentenceOrder":126},
  {"id":"s_work_han_thu_56_127","chapterId":"ch_work_han_thu_56","textTraditional":"〔八〕　師古曰：「言不須為此詐，直自發兵而已。」","sentenceOrder":127},
  {"id":"s_work_han_thu_56_128","chapterId":"ch_work_han_thu_56","textTraditional":"江充字次倩，趙國邯鄲人也。〔一〕充本名齊，有女弟善鼓琴歌舞，嫁之趙太子丹。齊得幸於敬肅王，為上客。","sentenceOrder":128},
  {"id":"s_work_han_thu_56_129","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「倩音千見反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_56_130","chapterId":"ch_work_han_thu_56","textTraditional":"久之，太子疑齊以己陰私告王，與齊忤，〔一〕使吏逐捕齊，不得，收繫其父兄，按驗，皆棄市。齊遂絕跡亡，西入關，更名充。詣闕告太子丹與同產姊及王後宮姦亂，交通郡國豪猾，攻剽為姦，〔二〕吏不能禁。書奏，天子怒，遣使者詔郡發吏卒圍趙王宮，收捕太子丹，移繫魏郡詔獄，與廷尉雜治，法至死。","sentenceOrder":130},
  {"id":"s_work_han_thu_56_131","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「言相乖。」","sentenceOrder":131},
  {"id":"s_work_han_thu_56_132","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「剽，劫也，音頻妙反。」","sentenceOrder":132},
  {"id":"s_work_han_thu_56_133","chapterId":"ch_work_han_thu_56","textTraditional":"趙王彭祖，帝異母兄也，上書訟太子罪，言「充逋逃小臣，苟為姦訛，激怒聖朝，〔一〕欲取必於萬乘以復私怨。〔二〕後雖亨醢，計猶不悔。臣願選從趙國勇敢士，〔三〕從軍擊匈奴，極盡死力，以贖丹罪。」上不許，竟敗趙太子。〔四〕","sentenceOrder":133},
  {"id":"s_work_han_thu_56_134","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「訛，古訛字也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_56_135","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「取必，謂必取勝也。復，報也，音扶目反。」","sentenceOrder":135},
  {"id":"s_work_han_thu_56_136","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　師古曰：「選取勇敢之士（已）〔以〕自隨。」","sentenceOrder":136},
  {"id":"s_work_han_thu_56_137","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　張晏曰：「雖遇赦，終見廢也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_56_138","chapterId":"ch_work_han_thu_56","textTraditional":"初，充召見犬臺宮，〔一〕自請願以所常被服冠見上。〔二〕上許之。充衣紗縠襌衣，〔三〕曲裾後垂交輸，〔四〕冠襌纚步搖冠，飛翮之纓。〔五〕充為人魁岸，容貌甚壯。〔六〕帝望見而異之，謂左右曰：「燕趙固多奇士。」既至前，問以當世政事，上說之。","sentenceOrder":138},
  {"id":"s_work_han_thu_56_139","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　晉灼曰：「黃圖上林有犬臺宮，外有走狗觀也。」師古曰：「今書本犬臺有作太壹字者，誤也。漢無太壹宮也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_56_140","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「被音皮義反。」","sentenceOrder":140},
  {"id":"s_work_han_thu_56_141","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　師古曰：「紗縠，紡絲而織之也。輕者為紗，縐者為縠。襌衣，制若今之朝服中襌也。漢官儀曰武賁中郎將衣紗縠襌衣。襌音單，字從衣。次下亦同。」","sentenceOrder":141},
  {"id":"s_work_han_thu_56_142","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　張晏曰：「曲裾者，如婦人衣也。」如淳曰：「交輸，割正幅，使一頭狹若燕尾，垂之兩旁，見於後，是禮深衣『（績）〔續〕衽鉤邊』。賈逵謂之『衣圭』。」蘇林曰：「交輸，如今新婦袍上挂全幅繒角割，名曰交輸裁也。」師古曰：「如、蘇二說皆是也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_56_143","chapterId":"ch_work_han_thu_56","textTraditional":"〔五〕　服虔曰：「冠襌纚，故行步則搖，以鳥羽作纓也。」蘇林曰：「析翠鳥羽以作蕤也。」臣瓚曰：「飛翮之纓，謂如蟬翼者也。」師古曰：「服說是也。纚，織絲為之，即今方目紗是也。纚音山爾反。搖音（戈）〔弋〕招反。」","sentenceOrder":143},
  {"id":"s_work_han_thu_56_144","chapterId":"ch_work_han_thu_56","textTraditional":"〔六〕　師古曰：「魁，大也。岸者，有廉棱如崖岸之形。」","sentenceOrder":144},
  {"id":"s_work_han_thu_56_145","chapterId":"ch_work_han_thu_56","textTraditional":"充因自請，願使匈奴。詔問其狀，充對曰：「因變制宜，以敵為師，事不可豫圖。」上以充為謁者，使匈奴還，拜為直指繡衣使者，督三輔盜賊，禁察踰侈。貴戚近臣多奢僭，充皆舉劾，奏請沒入車馬，令身待北軍擊匈奴。〔一〕奏可。充即移書光祿勳中黃門，逮名近臣侍中諸當詣北軍者，移劾門衛，禁止無令得出入宮殿。於是貴戚子弟惶恐，皆見上叩頭求哀，願得入錢贖罪。上許之，令各以秩次輸錢北軍，凡數千萬。上以充忠直，奉法不阿，所言中意。〔二〕","sentenceOrder":145},
  {"id":"s_work_han_thu_56_146","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　文穎曰：「令貴戚身待於北軍也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_56_147","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「中，當也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_56_148","chapterId":"ch_work_han_thu_56","textTraditional":"充出，逢館陶長公主行馳道中。〔一〕充呵問之，公主曰：「有太后詔。」充曰：「獨公主得行，車騎皆不得。」〔二〕盡劾沒入官。〔三〕","sentenceOrder":148},
  {"id":"s_work_han_thu_56_149","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「武帝之姑，即陳皇后母也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_56_150","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「從公主之車騎也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_56_151","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　如淳曰：「令乙，騎乘車馬行馳道中，已論者，沒入車馬被具。」","sentenceOrder":151},
  {"id":"s_work_han_thu_56_152","chapterId":"ch_work_han_thu_56","textTraditional":"後充從上甘泉，〔一〕逢太子家使〔二〕乘車馬行馳道中，充以屬吏。〔三〕太子聞之，使人謝充曰：「非愛車馬，誠不欲令上聞之，以教敕亡素者。〔四〕唯江君寬之！」充不聽，遂白奏。上曰：「人臣當如是矣。」大見信用，威震京師。","sentenceOrder":152},
  {"id":"s_work_han_thu_56_153","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「甘泉在北山，故言上也。他皆類此。」","sentenceOrder":153},
  {"id":"s_work_han_thu_56_154","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「太子遣人之甘泉請問者也。使音山吏反。」","sentenceOrder":154},
  {"id":"s_work_han_thu_56_155","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　師古曰：「屬音之欲反。」","sentenceOrder":155},
  {"id":"s_work_han_thu_56_156","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「言素不教敕左右。」","sentenceOrder":156},
  {"id":"s_work_han_thu_56_157","chapterId":"ch_work_han_thu_56","textTraditional":"遷為水衡都尉，宗族知友多得其力者。久之，坐法免。","sentenceOrder":157},
  {"id":"s_work_han_thu_56_158","chapterId":"ch_work_han_thu_56","textTraditional":"會陽陵朱安世告丞相公孫賀子太僕敬聲為巫蠱事，連及陽石、諸邑公主，賀父子皆坐誅。語在賀傳。後上幸甘泉，疾病，充見上年老，恐晏駕後為太子所誅，因是為姦，奏言上疾祟在巫蠱。〔一〕於是上以充為使者治巫蠱。充將胡巫掘地求偶人，〔二〕捕蠱及夜祠，視鬼，染汙令有處，〔三〕輒收捕驗治，燒鐵鉗灼，強服之。〔四〕民轉相誣以巫蠱，吏輒劾以大逆亡道，坐而死者前後數萬人。","sentenceOrder":158},
  {"id":"s_work_han_thu_56_159","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「祟謂禍咎之徵也，音息遂反。故其字從出從示。示者，鬼神所以示人也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_56_160","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　張晏曰：「胡者，言不與華同，故充任使之。」","sentenceOrder":160},
  {"id":"s_work_han_thu_56_161","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　張晏曰：「充捕巫蠱及夜祭祠祝詛者，令胡巫視鬼，詐以酒醊地，令有處也。」師古曰：「捕夜祠及視鬼之人，而充遣巫汙染地上，為祠祭之處，以誣其人也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_56_162","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「以燒鐵或鉗之，或灼之。鉗，鑷也。灼，炙也。鉗音其炎反。」","sentenceOrder":162},
  {"id":"s_work_han_thu_56_163","chapterId":"ch_work_han_thu_56","textTraditional":"是時，上春秋高，疑左右皆為蠱祝詛，有與亡，莫敢訟其冤者。充既知上意，因言宮中有蠱氣，先治後宮希幸夫人，以次及皇后，遂掘蠱於太子宮，得桐木人。〔一〕太子懼，不能自明，收充，自臨斬之。罵曰：「趙虜！亂乃國王父子不足邪！〔二〕乃復亂吾父子也！」太子繇是遂敗。〔三〕語在戾園傳。〔四〕後武帝知充有詐，夷充三族。","sentenceOrder":163},
  {"id":"s_work_han_thu_56_164","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「三輔舊事云充使胡巫作而薶之。」","sentenceOrder":164},
  {"id":"s_work_han_thu_56_165","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「乃，汝也。」","sentenceOrder":165},
  {"id":"s_work_han_thu_56_166","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　師古曰：「繇讀與由同。」","sentenceOrder":166},
  {"id":"s_work_han_thu_56_167","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「即武五子傳也，其中敘戾太子。後加諡，置園邑，故云戾園。」","sentenceOrder":167},
  {"id":"s_work_han_thu_56_168","chapterId":"ch_work_han_thu_56","textTraditional":"息夫躬字子微，河內河陽人也。少為博士弟子，受春秋，通覽記書。〔一〕容貌壯麗，為眾所異。","sentenceOrder":168},
  {"id":"s_work_han_thu_56_169","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「傳記及諸家之書。」","sentenceOrder":169},
  {"id":"s_work_han_thu_56_170","chapterId":"ch_work_han_thu_56","textTraditional":"哀帝初即位，皇后父特進孔鄉侯傅晏與躬同郡，相友善，躬繇是以為援，交游日廣。〔一〕先是，長安孫寵亦以游說顯名，免汝南太守，〔二〕與躬相結，俱上書，召待詔。是時哀帝被疾，始即位，而人有告中山孝王太后祝詛上，太后及弟宜鄉侯馮參皆自殺，其罪不明。是後無鹽危山有石自立，開道。〔三〕躬與寵謀曰：「上亡繼嗣，體久不平，關東諸侯，心爭陰謀。今無鹽有大石自立，聞邪臣託往事，以為大山石立而先帝龍興。〔四〕東平王雲以故與其后日夜祠祭祝詛上，欲求非望。〔五〕而后舅伍宏反因方術以醫技得幸，出入禁門。霍顯之謀將行於杯杓，〔六〕荊軻之變必起於帷幄。事勢若此，告之必成；發國姦，誅主讎，取封侯之計也。」躬、寵乃與中郎右師譚，〔七〕共因中常侍宋弘上變事告焉。上惡之，下有司案驗，東平王雲、雲后謁及伍宏等皆坐誅。〔八〕上擢寵為南陽太守，譚穎川都尉，弘、躬皆光祿大夫左曹給事中。是時侍中董賢愛幸，上欲侯之，遂下詔云：「躬、寵因賢以聞，封賢為高安侯，寵為方陽侯，躬為宜陵侯，食邑各千戶。賜譚爵關內侯，食邑。」丞相王嘉內疑東平獄事，〔九〕爭不欲侯賢等，語在嘉傳。嘉固言董賢泰盛，寵、躬皆傾覆有佞邪材，恐必撓亂國家，〔一０〕不可任用。嘉以此得罪矣。","sentenceOrder":170},
  {"id":"s_work_han_thu_56_171","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「繇讀與由同。」","sentenceOrder":171},
  {"id":"s_work_han_thu_56_172","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「為太守免而歸也。」","sentenceOrder":172},
  {"id":"s_work_han_thu_56_173","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　服虔曰：「山開自成道也。」張晏曰：「從石立之下道徑自通也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_56_174","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「言邪人有此私議。」","sentenceOrder":174},
  {"id":"s_work_han_thu_56_175","chapterId":"ch_work_han_thu_56","textTraditional":"〔五〕　師古曰：「言求帝位也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_56_176","chapterId":"ch_work_han_thu_56","textTraditional":"〔六〕　師古曰：「杓，所以抒挹也，字與勺同，音上灼反。」","sentenceOrder":176},
  {"id":"s_work_han_thu_56_177","chapterId":"ch_work_han_thu_56","textTraditional":"〔七〕　張晏曰：「右師，姓。譚，名也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_56_178","chapterId":"ch_work_han_thu_56","textTraditional":"〔八〕　師古曰：「謁者，后之名也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_56_179","chapterId":"ch_work_han_thu_56","textTraditional":"〔九〕　師古曰：「疑不實也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_56_180","chapterId":"ch_work_han_thu_56","textTraditional":"〔一０〕師古曰：「撓，攪也。撓音呼高反。」","sentenceOrder":180},
  {"id":"s_work_han_thu_56_181","chapterId":"ch_work_han_thu_56","textTraditional":"躬既親近，數進見言事，論議亡所避。眾畏其口，見之仄目〔一〕。躬上疏歷詆公卿大臣，〔二〕曰：「方今丞相王嘉健而蓄縮，不可用。〔三〕御史大夫賈延墮弱不任職。左將軍公孫祿、司隸鮑宣皆外有直項之名，內實騃不曉政事。〔四〕諸曹以下僕速不足數。〔五〕卒有彊弩圍城，長戟指闕，〔六〕陛下誰與備之？如使狂夫嘄謼於東崖，〔七〕匈奴飲馬於渭水，邊竟雷動，四野風起，〔八〕京師雖有武蜂精兵，未有能窺左足而先應者也。〔九〕軍書交馳而輻湊，羽檄重跡而押至，〔一０〕小夫懦臣之徒憒眊不知所為。〔一一〕其有犬馬之決者，仰藥而伏刃，〔一二〕雖加夷滅之誅，何益禍敗之至哉！」","sentenceOrder":181},
  {"id":"s_work_han_thu_56_182","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「仄，古側字也。」","sentenceOrder":182},
  {"id":"s_work_han_thu_56_183","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「詆謂毀訾也，音丁禮反。」","sentenceOrder":183},
  {"id":"s_work_han_thu_56_184","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　師古曰：「蓄縮，謂〈恡，去“忄”〉於事也。」","sentenceOrder":184},
  {"id":"s_work_han_thu_56_185","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「騃，愚也，音五駭反。」","sentenceOrder":185},
  {"id":"s_work_han_thu_56_186","chapterId":"ch_work_han_thu_56","textTraditional":"〔五〕　師古曰：「僕遫，凡短之貌也。僕音步木反。遫，古速字。」","sentenceOrder":186},
  {"id":"s_work_han_thu_56_187","chapterId":"ch_work_han_thu_56","textTraditional":"〔六〕　師古曰：「卒讀曰猝。」","sentenceOrder":187},
  {"id":"s_work_han_thu_56_188","chapterId":"ch_work_han_thu_56","textTraditional":"〔七〕　師古曰：「東崖謂東海之邊也。嘄，古叫字。謼音火故反。」","sentenceOrder":188},
  {"id":"s_work_han_thu_56_189","chapterId":"ch_work_han_thu_56","textTraditional":"〔八〕　師古曰：「竟讀曰境。」","sentenceOrder":189},
  {"id":"s_work_han_thu_56_190","chapterId":"ch_work_han_thu_56","textTraditional":"〔九〕　蘇林曰：「窺音跬。」師古曰：「跬，半步也，言一舉足也，音口婢反。」","sentenceOrder":190},
  {"id":"s_work_han_thu_56_191","chapterId":"ch_work_han_thu_56","textTraditional":"〔一０〕文穎曰：「押音狎習之狎。」師古曰：「押至，言相因而至也。羽檄，檄之插羽者也，解在高紀。」","sentenceOrder":191},
  {"id":"s_work_han_thu_56_192","chapterId":"ch_work_han_thu_56","textTraditional":"〔一一〕師古曰：「憒，心亂也。眊，目闇也。憒音工內反。眊音莫報反。」","sentenceOrder":192},
  {"id":"s_work_han_thu_56_193","chapterId":"ch_work_han_thu_56","textTraditional":"〔一二〕師古曰：「仰藥，仰首而飲藥。」","sentenceOrder":193},
  {"id":"s_work_han_thu_56_194","chapterId":"ch_work_han_thu_56","textTraditional":"躬又言：「秦開鄭國渠以富國彊兵，今為京師，土地肥饒，可度地勢水泉，廣溉灌之利。」〔一〕天子使躬持節領護三輔都水。躬立表，欲穿長安城，引漕注太倉下以省轉輸。議不可成，乃止。","sentenceOrder":194},
  {"id":"s_work_han_thu_56_195","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「度音徒各反。」","sentenceOrder":195},
  {"id":"s_work_han_thu_56_196","chapterId":"ch_work_han_thu_56","textTraditional":"董賢貴幸日盛，丁、傅害其寵，孔鄉侯晏與躬謀，欲求居位輔政。會單于當來朝，遣使言病，願朝明年。躬因是而上奏，以為「單于當以十一月入塞，後以病為解，〔一〕疑有他變。烏孫兩昆彌弱，卑爰疐強盛，〔二〕居彊煌之地，〔三〕擁十萬之眾，東結單于，遣子往侍。如因素彊之威，循烏孫就屠之跡，〔四〕舉兵南伐，并烏孫之勢也。烏孫并，則匈奴盛，而西域危矣。可令降胡詐為卑爰疐使者來上書曰：『所以遣子侍單于者，非親信之也，實畏之耳。唯天子哀，〔五〕告單于歸臣侍子。願助戊己校尉保惡都奴之界。』因下其章諸將軍，令匈奴客聞焉。則是所謂『上兵伐謀，〔六〕其次伐交』者也。」〔七〕","sentenceOrder":196},
  {"id":"s_work_han_thu_56_197","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「自解說云病。」","sentenceOrder":197},
  {"id":"s_work_han_thu_56_198","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　蘇林曰：「疐音欬嚏之嚏。」晉灼曰：「音詩『載疐其尾』之疐。」師古曰：「以字言之，晉音是，音竹二反。而匈奴傳服虔乃音獻捷之捷，既已失之。末俗學者又改疐字為〈广疌〉，以應服氏之音，尤離真矣。」","sentenceOrder":198},
  {"id":"s_work_han_thu_56_199","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　臣瓚曰：「是其國所都地名。」","sentenceOrder":199},
  {"id":"s_work_han_thu_56_200","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　孟康曰：「烏孫先王也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_56_201","chapterId":"ch_work_han_thu_56","textTraditional":"〔五〕　師古曰：「謂閔念之。」","sentenceOrder":201},
  {"id":"s_work_han_thu_56_202","chapterId":"ch_work_han_thu_56","textTraditional":"〔六〕　服虔曰：「謀者，舉兵伐解之也。」師古曰：「此說非也。言知敵有謀者，則以事而應之，沮其所為，不用兵革，所以為貴耳。」","sentenceOrder":202},
  {"id":"s_work_han_thu_56_203","chapterId":"ch_work_han_thu_56","textTraditional":"〔七〕　師古曰：「知敵有外交連結相援者，則間誤之，令其解散也。」","sentenceOrder":203},
  {"id":"s_work_han_thu_56_204","chapterId":"ch_work_han_thu_56","textTraditional":"書奏，上引見躬，召公卿將軍大議。左將軍公孫祿以為「中國常以威信懷伏夷狄，躬欲逆詐造不信之謀，不可許。且匈奴賴先帝之德，保塞稱蕃。今單于以疾病不任奉朝賀，遣使自陳，不失臣子之禮。臣祿自保沒身不見匈奴為邊竟憂也。」〔一〕躬掎祿曰：〔二〕「臣為國家計幾先，謀將然，〔三〕豫圖未形，〔四〕為萬世慮。而左將軍公孫祿欲以其犬馬齒保目所見。臣與祿異議，未可同日語也。」上曰：「善。」乃罷群臣，獨與躬議。","sentenceOrder":204},
  {"id":"s_work_han_thu_56_205","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「竟讀曰境。」","sentenceOrder":205},
  {"id":"s_work_han_thu_56_206","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「掎，從後引之也，謂引躡其言也，音居綺反。」","sentenceOrder":206},
  {"id":"s_work_han_thu_56_207","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　張晏曰：「幾音冀。」師古曰：「先謀將然者，謂彼欲有其事，則為謀策以壞之。」","sentenceOrder":207},
  {"id":"s_work_han_thu_56_208","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「圖，謀也，未有形兆而謀之。」","sentenceOrder":208},
  {"id":"s_work_han_thu_56_209","chapterId":"ch_work_han_thu_56","textTraditional":"因建言：「往年熒惑守心，太白高而芒光，又角星茀於河鼓〔一〕，其法為有兵亂。是後訛言行詔籌，經歷郡國，天下騷動，恐必有非常之變。可遣大將軍行邊兵，敕武備，〔二〕斬一郡守，以立威，震四夷，因以厭應變異。」〔三〕上然之，以問丞相。丞相嘉對曰：「臣聞動民以行不以言，應天以實不以文。下民微細，猶不可詐，況於上天神明而可欺哉！天之見異，所以敕戒人君，〔四〕欲令覺悟反正，推誠行善。民心說而天意得矣。〔五〕辯士見一端，或妄以意傅著星曆，〔六〕虛造匈奴、烏孫、西羌之難，謀動干戈，設為權變，非應天之道也。守相有罪，〔七〕車馳詣闕，交臂就死，恐懼如此，而談說者云，動安之危，〔八〕辯口快耳，〔九〕其實未可從。夫議政者，苦其諂諛傾險辯慧深刻也。〔一０〕諂諛則主德毀，傾險則下怨恨，辯慧則破正道，深刻則傷恩惠。昔秦繆公不從百里奚、蹇叔之言，〔一一〕以敗其師，〔一二〕悔過自責，疾詿誤之臣，思黃髮之言，〔一三〕名垂於後世。唯陛下觀覽古戒，反覆參考，無以先入之語為主。」〔一四〕","sentenceOrder":209},
  {"id":"s_work_han_thu_56_210","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「茀讀與孛同。」","sentenceOrder":210},
  {"id":"s_work_han_thu_56_211","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「敕，整也。行音下更反。」","sentenceOrder":211},
  {"id":"s_work_han_thu_56_212","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　師古曰：「厭音一涉反。」","sentenceOrder":212},
  {"id":"s_work_han_thu_56_213","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「見謂顯示也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_56_214","chapterId":"ch_work_han_thu_56","textTraditional":"〔五〕　師古曰：「說讀曰悅。」","sentenceOrder":214},
  {"id":"s_work_han_thu_56_215","chapterId":"ch_work_han_thu_56","textTraditional":"〔六〕　師古曰：「傅讀曰附。著音治略反。」","sentenceOrder":215},
  {"id":"s_work_han_thu_56_216","chapterId":"ch_work_han_thu_56","textTraditional":"〔七〕　鄧展曰：「郡守、諸侯相。」","sentenceOrder":216},
  {"id":"s_work_han_thu_56_217","chapterId":"ch_work_han_thu_56","textTraditional":"〔八〕　師古曰：「之，往也，言搖動安全之計，往就危殆也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_56_218","chapterId":"ch_work_han_thu_56","textTraditional":"〔九〕　師古曰：「苟快聽者之耳。」","sentenceOrder":218},
  {"id":"s_work_han_thu_56_219","chapterId":"ch_work_han_thu_56","textTraditional":"〔一０〕師古曰：「讇，古諂字。」","sentenceOrder":219},
  {"id":"s_work_han_thu_56_220","chapterId":"ch_work_han_thu_56","textTraditional":"〔一一〕師古曰：「繆讀曰穆。」","sentenceOrder":220},
  {"id":"s_work_han_thu_56_221","chapterId":"ch_work_han_thu_56","textTraditional":"〔一二〕師古曰：「謂敗於殽。」","sentenceOrder":221},
  {"id":"s_work_han_thu_56_222","chapterId":"ch_work_han_thu_56","textTraditional":"〔一三〕師古曰：「語在秦誓。」","sentenceOrder":222},
  {"id":"s_work_han_thu_56_223","chapterId":"ch_work_han_thu_56","textTraditional":"〔一四〕師古曰：「先入，謂躬先為此計入於帝耳。」","sentenceOrder":223},
  {"id":"s_work_han_thu_56_224","chapterId":"ch_work_han_thu_56","textTraditional":"上不聽，遂下詔曰：「間者災變不息，盜賊眾多，兵革之徵，或頗著見。〔一〕未聞將軍惻然深以為意，簡練戎士，繕修干戈。〔二〕器用盬惡，〔三〕孰當督之！〔四〕天下雖安，忘戰必危。將軍與中二千石舉明習兵法有大慮者各一人，將軍二人，詣公車。」〔五〕就拜孔鄉侯傅晏為大司馬衛將軍，陽安侯丁明又為大司馬票騎將軍。","sentenceOrder":224},
  {"id":"s_work_han_thu_56_225","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「謂玄象。」","sentenceOrder":225},
  {"id":"s_work_han_thu_56_226","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「繕，補也。」","sentenceOrder":226},
  {"id":"s_work_han_thu_56_227","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　鄧展曰：「盬，不堅牢也。」師古曰：「音公戶反。」","sentenceOrder":227},
  {"id":"s_work_han_thu_56_228","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「督，視察也。」","sentenceOrder":228},
  {"id":"s_work_han_thu_56_229","chapterId":"ch_work_han_thu_56","textTraditional":"〔五〕　師古曰：「堪為將軍者，凡舉二人。」","sentenceOrder":229},
  {"id":"s_work_han_thu_56_230","chapterId":"ch_work_han_thu_56","textTraditional":"是日，日有食之，董賢因此沮躬、晏之策。後數日，收晏衛將軍印綬，而丞相御史奏躬罪過。上繇是惡躬等，〔一〕下詔曰：「南陽太守方陽侯寵，素亡廉聲，有酷惡之資，毒流百姓。左曹光祿大夫宜陵侯躬，虛造詐諼之策，〔二〕欲以詿誤朝廷。皆交遊貴戚，趨權門，為名。其免躬、寵官，遣就國。」","sentenceOrder":230},
  {"id":"s_work_han_thu_56_231","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「繇讀與由同。」","sentenceOrder":231},
  {"id":"s_work_han_thu_56_232","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「諼，詐辭也，音虛遠反。」","sentenceOrder":232},
  {"id":"s_work_han_thu_56_233","chapterId":"ch_work_han_thu_56","textTraditional":"躬歸國，未有第宅，寄居丘亭。〔一〕姦人以為侯家富，常夜守之。〔二〕躬邑人河內掾賈惠往過躬，教以祝盜方，以桑東南指枝為匕，〔三〕畫北斗七星其上，躬夜自被髮，立中庭，向北斗，〔四〕持匕招指祝盜。〔五〕人有上書言躬懷怨恨，非笑朝廷所進，（侯）〔候〕星宿，視天子吉凶，與巫同祝詛。上遣侍御史、廷尉監逮躬，繫雒陽詔獄。欲掠問，躬仰天大謼，〔六〕因僵仆。吏就問，云咽已絕，〔七〕血從鼻耳出。食頃，死。黨友謀議相連下獄百餘人。〔八〕躬母聖，坐祠灶祝詛上，大逆不道。聖棄市，妻充漢與家屬徙合浦。躬同族親屬素所厚者，皆免廢錮。〔九〕哀帝崩，有司奏：「方陽侯寵及右師譚等，皆造作姦謀，罪及王者骨肉，雖蒙赦令，不宜處爵位，在中土。」皆免寵等，徙合浦郡。","sentenceOrder":233},
  {"id":"s_work_han_thu_56_234","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　張晏曰：「丘亭，野亭名。」師古曰：「此說非也。丘，空也。」","sentenceOrder":234},
  {"id":"s_work_han_thu_56_235","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「謂欲盜之，伺其便。」","sentenceOrder":235},
  {"id":"s_work_han_thu_56_236","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　師古曰：「桑東南出之枝。」","sentenceOrder":236},
  {"id":"s_work_han_thu_56_237","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「被音皮義反。」","sentenceOrder":237},
  {"id":"s_work_han_thu_56_238","chapterId":"ch_work_han_thu_56","textTraditional":"〔五〕　師古曰：「或招或指，所以求福排禍也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_56_239","chapterId":"ch_work_han_thu_56","textTraditional":"〔六〕　師古曰：「謼，古呼字，音火故反。」","sentenceOrder":239},
  {"id":"s_work_han_thu_56_240","chapterId":"ch_work_han_thu_56","textTraditional":"〔七〕　師古曰：「咽，喉嚨，音一千反。」","sentenceOrder":240},
  {"id":"s_work_han_thu_56_241","chapterId":"ch_work_han_thu_56","textTraditional":"〔八〕　師古曰：「親黨及朋友。」","sentenceOrder":241},
  {"id":"s_work_han_thu_56_242","chapterId":"ch_work_han_thu_56","textTraditional":"〔九〕　師古曰：「終身不得仕。」","sentenceOrder":242},
  {"id":"s_work_han_thu_56_243","chapterId":"ch_work_han_thu_56","textTraditional":"初，躬待詔，數危言高論，自恐遭害，著絕命辭曰：「玄雲泱鬱，將安歸兮！〔一〕鷹隼橫厲，鸞俳佪兮！〔二〕矰若浮猋，動則機兮！〔三〕藂棘〈淺，中“氵改扌”〉〈淺，中“氵改扌”〉，曷可棲兮！〔四〕發忠忘身，自繞罔兮！冤頸折翼，庸得往兮！〔五〕涕泣流兮萑蘭，〔六〕心結愲兮傷肝。〔七〕虹蜺曜兮日微，〔八〕孽杳冥兮未開。〔九〕痛入天兮鳴謼，冤際絕兮誰語！〔一０〕仰天光兮自列，招上帝兮我察。〔一一〕秋風為我吟，浮雲為我陰。〔一二〕嗟若是兮欲何留，〔一三〕撫神龍兮〈扌監〉其須。〔一四〕游曠迥兮反亡期，〔一五〕雄失據兮世我思。」〔一六〕後數年乃死，如其文。","sentenceOrder":243},
  {"id":"s_work_han_thu_56_244","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　師古曰：「泱鬱，盛貌。泱音焉朗反。」","sentenceOrder":244},
  {"id":"s_work_han_thu_56_245","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　師古曰：「厲，疾飛也。鸞，神鳥也，赤靈之精，赤色，五采，雞形，鳴中五音。俳佪，謂不得其所也。」","sentenceOrder":245},
  {"id":"s_work_han_thu_56_246","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　師古曰：「矰，弋射矢也。猋，疾風也。言繒弋張設，其疾若風，動則機發。猋音必遙反。」","sentenceOrder":246},
  {"id":"s_work_han_thu_56_247","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「〈淺，中“氵改扌”〉〈淺，中“氵改扌”〉，眾盛貌，音仕巾反。」","sentenceOrder":247},
  {"id":"s_work_han_thu_56_248","chapterId":"ch_work_han_thu_56","textTraditional":"〔五〕　應劭曰：「雖冤頸折翼，庸得不往也。」張晏曰：「陷於讒人之網，何用得去也。」師古曰：「冤，屈也。張說是。」","sentenceOrder":248},
  {"id":"s_work_han_thu_56_249","chapterId":"ch_work_han_thu_56","textTraditional":"〔六〕　張晏曰：「萑蘭，草名也，蔓延於地，有所依憑則起。躬怨哀帝不用己為大臣以（置）〔致〕治也。」臣瓚曰：「萑蘭，泣涕闌干也。」師古曰：「瓚說是。萑音完。」","sentenceOrder":249},
  {"id":"s_work_han_thu_56_250","chapterId":"ch_work_han_thu_56","textTraditional":"〔七〕　師古曰：「結愲，亂也。」孟康曰：「愲音骨。」","sentenceOrder":250},
  {"id":"s_work_han_thu_56_251","chapterId":"ch_work_han_thu_56","textTraditional":"〔八〕　張晏曰：「虹蜺，邪陰之氣，而有照曜，以蔽日月。云讒言流行，忠良浸微也。」","sentenceOrder":251},
  {"id":"s_work_han_thu_56_252","chapterId":"ch_work_han_thu_56","textTraditional":"〔九〕　如淳曰：「虹蜺覆日光明謂之孽。」師古曰：「孽，邪氣也，音牛列反。」","sentenceOrder":252},
  {"id":"s_work_han_thu_56_253","chapterId":"ch_work_han_thu_56","textTraditional":"〔一０〕張晏曰：「躬自以被讒枉而與君絕也。」師古曰：「鳴謼者，以鳥自喻也。誰語，言無所告語也。謼音火故反。語音牛助反。」","sentenceOrder":253},
  {"id":"s_work_han_thu_56_254","chapterId":"ch_work_han_thu_56","textTraditional":"〔一一〕張晏曰：「上帝，天也。招，呼也。」師古曰：「列謂陳列其本心。」","sentenceOrder":254},
  {"id":"s_work_han_thu_56_255","chapterId":"ch_work_han_thu_56","textTraditional":"〔一二〕師古曰：「唫，古吟字。」","sentenceOrder":255},
  {"id":"s_work_han_thu_56_256","chapterId":"ch_work_han_thu_56","textTraditional":"〔一三〕師古曰：「言變故如是，何用久留而生。」","sentenceOrder":256},
  {"id":"s_work_han_thu_56_257","chapterId":"ch_work_han_thu_56","textTraditional":"〔一四〕師古曰：「〈扌監〉與攬同，謂執持之。」","sentenceOrder":257},
  {"id":"s_work_han_thu_56_258","chapterId":"ch_work_han_thu_56","textTraditional":"〔一五〕師古曰：「言一死不可復生。」","sentenceOrder":258},
  {"id":"s_work_han_thu_56_259","chapterId":"ch_work_han_thu_56","textTraditional":"〔一六〕師古曰：「雄謂君上也。據謂尊位也。言上失所據，乃思我耳。」","sentenceOrder":259},
  {"id":"s_work_han_thu_56_260","chapterId":"ch_work_han_thu_56","textTraditional":"贊曰：仲尼「惡利口之覆邦家」，〔一〕蒯通一說而喪三儁〔二〕，其得不亨者，幸也。伍被安於危國，身為謀主，忠不終而詐讎，〔三〕誅夷不亦宜乎！書放四罪，〔四〕詩歌青蠅，〔五〕春秋以來，禍敗多矣。昔子翬謀桓而魯隱危，〔六〕欒書搆郤而晉厲弒。〔七〕豎牛奔仲，叔孫卒；〔八〕郈伯毀季，昭公逐；〔九〕費忌納女，楚建走；〔一０〕宰嚭讒胥，夫差喪；〔一一〕李園進妹，春申斃；〔一二〕上官訴屈，懷王執；〔一三〕趙高敗斯，二世縊；〔一四〕伊戾坎盟，宋痤死；〔一五〕江充造蠱，太子殺；息夫作姦，東平誅：皆自小覆大，繇疏陷親，可不懼哉！可不懼哉！〔一六〕","sentenceOrder":260},
  {"id":"s_work_han_thu_56_261","chapterId":"ch_work_han_thu_56","textTraditional":"〔一〕　應劭曰：「事具論語。」","sentenceOrder":261},
  {"id":"s_work_han_thu_56_262","chapterId":"ch_work_han_thu_56","textTraditional":"〔二〕　應劭曰：「亨酈食其，敗田橫，驕韓信也。」","sentenceOrder":262},
  {"id":"s_work_han_thu_56_263","chapterId":"ch_work_han_thu_56","textTraditional":"〔三〕　李奇曰：「詐為王畫策，而讎見納也。」師古曰：「讎讀曰（集）〔售〕。謂被初忠於漢，而不能終，為王畫詐偽之策，而見納用也。」","sentenceOrder":263},
  {"id":"s_work_han_thu_56_264","chapterId":"ch_work_han_thu_56","textTraditional":"〔四〕　師古曰：「謂流共工，放驩兜，竄三苗，殛鯀也。事見虞書。」","sentenceOrder":264},
  {"id":"s_work_han_thu_56_265","chapterId":"ch_work_han_thu_56","textTraditional":"〔五〕　師古曰：「小雅青蠅之詩也。其首章曰：『營營青蠅，止於樊，愷悌君子，無信讒言。』蓋蠅之為蟲，毀汙白黑，以喻佞人變亂善惡。」","sentenceOrder":265},
  {"id":"s_work_han_thu_56_266","chapterId":"ch_work_han_thu_56","textTraditional":"〔六〕　應劭曰：「公子翬謂隱公曰：『吾將為君殺桓公，以我為太宰。』公曰：『為其少故，今將授之矣。』翬懼，反譖隱公而殺之。」","sentenceOrder":266},
  {"id":"s_work_han_thu_56_267","chapterId":"ch_work_han_thu_56","textTraditional":"〔七〕　應劭曰：「欒書使楚公子茂語厲公曰：『鄢陵之戰，郤至以為必敗，欲奉孫周以代君也。』公信之而滅三郤。欒書因是反，弒厲公。」","sentenceOrder":267},
  {"id":"s_work_han_thu_56_268","chapterId":"ch_work_han_thu_56","textTraditional":"〔八〕　張晏曰：「牛，叔孫穆子之孽子也。仲，正妻子也。牛讒仲，叔孫怒而逐之，奔齊。叔孫病，牛餓殺之。」","sentenceOrder":268},
  {"id":"s_work_han_thu_56_269","chapterId":"ch_work_han_thu_56","textTraditional":"〔九〕　張晏曰：「郈昭伯毀季平子於昭公，昭公伐平子不勝，因出奔齊。」","sentenceOrder":269},
  {"id":"s_work_han_thu_56_270","chapterId":"ch_work_han_thu_56","textTraditional":"〔一０〕應劭曰：「楚平王為太子建娶於秦。無忌曰秦女美甚，勸王自納之，因而構焉，云其怨望，今將畔，令王殺之。」","sentenceOrder":270},
  {"id":"s_work_han_thu_56_271","chapterId":"ch_work_han_thu_56","textTraditional":"〔一一〕應劭曰：「吳將伐齊，子胥諫之。宰嚭曰：『伍員自以先王謀臣，心常鞅鞅，臨事沮大眾，冀國之敗。』夫差大怒，賜之屬鏤之劍。其明年越滅吳。」","sentenceOrder":271},
  {"id":"s_work_han_thu_56_272","chapterId":"ch_work_han_thu_56","textTraditional":"〔一二〕張晏曰：「李園，春申君之舍人也，進其妹於春申君。已有身，使妹謂春申君曰：『楚王無子，百年之後，將立兄弟。君用事日久，多失禮於王之兄弟。兄弟誠立，禍將及身。今妾有子，人莫知。若進妾於王，後若生男，則君之子為王也。』春申君乃言之王，召入之，遂生男，立為太子。後（孝）〔考〕烈王薨，李園害春申君之寵，乃刺殺之。」","sentenceOrder":272},
  {"id":"s_work_han_thu_56_273","chapterId":"ch_work_han_thu_56","textTraditional":"〔一三〕張晏曰：「屈平忠而有謀，為上官子蘭所譖，見放逐。後秦昭誘懷王會於武關，遂執以歸，卒死於秦。」","sentenceOrder":273},
  {"id":"s_work_han_thu_56_274","chapterId":"ch_work_han_thu_56","textTraditional":"〔一四〕張晏曰：「趙高譖殺李斯而代其位，乃使其婿閻樂攻二世於望夷宮，乞為黔首，不聽，乃縊而死。」","sentenceOrder":274},
  {"id":"s_work_han_thu_56_275","chapterId":"ch_work_han_thu_56","textTraditional":"〔一五〕李奇曰：「伊戾為太子傅，無寵，欲敗太子，言與楚客盟謀宋，詐歃血加盟書以證之，公以故殺痤。」師古曰：「痤音在戈反。」","sentenceOrder":275},
  {"id":"s_work_han_thu_56_276","chapterId":"ch_work_han_thu_56","textTraditional":"〔一六〕師古曰：「覆音芳福反。繇與由同。」","sentenceOrder":276},
  {"id":"s_work_han_thu_56_277","chapterId":"ch_work_han_thu_56","textTraditional":"校勘記","sentenceOrder":277},
  {"id":"s_work_han_thu_56_278","chapterId":"ch_work_han_thu_56","textTraditional":"二一五九頁　七行　以復其怨而成其（功）名。　景祐、殿本都無「功」字，史記張耳陳餘傳同。","sentenceOrder":278},
  {"id":"s_work_han_thu_56_279","chapterId":"ch_work_han_thu_56","textTraditional":"二一五九頁一一行　先下君而君不利〔之〕，　景祐本有「之」字。","sentenceOrder":279},
  {"id":"s_work_han_thu_56_280","chapterId":"ch_work_han_thu_56","textTraditional":"二一六八頁　八行　（對）〔被〕曰：　景祐、殿本都作「被」。","sentenceOrder":280},
  {"id":"s_work_han_thu_56_281","chapterId":"ch_work_han_thu_56","textTraditional":"二一七一頁　四行　略衡山以擊（盧）〔廬〕江，　景祐、殿本都作「廬」。王先謙說此誤。","sentenceOrder":281},
  {"id":"s_work_han_thu_56_282","chapterId":"ch_work_han_thu_56","textTraditional":"二一七三頁一五行　和音胡（計）〔臥〕反。　景祐、殿本都作「臥」，此誤。","sentenceOrder":282},
  {"id":"s_work_han_thu_56_283","chapterId":"ch_work_han_thu_56","textTraditional":"二一七四頁一一行　被詣吏自告與淮南王謀反（縱）〔蹤〕跡如此。　景祐、殿本都作「蹤」，此誤。","sentenceOrder":283},
  {"id":"s_work_han_thu_56_284","chapterId":"ch_work_han_thu_56","textTraditional":"二一七六頁　五行　選取勇敢之士（已）〔以〕自隨。　景祐、殿本都作「以」。二一七六頁一四行（績）〔續〕衽鉤邊。　殿本作「續」。王先謙說作「續」是。按景祐本作「績」。","sentenceOrder":284},
  {"id":"s_work_han_thu_56_285","chapterId":"ch_work_han_thu_56","textTraditional":"二一七七頁　二行　搖音（戈）〔弋〕招反。　景祐、殿本都作「弋」，此誤。","sentenceOrder":285},
  {"id":"s_work_han_thu_56_286","chapterId":"ch_work_han_thu_56","textTraditional":"二一八六頁一六行　（侯）〔候〕星宿，　景祐、殿、局本都作「候」，此誤。","sentenceOrder":286},
  {"id":"s_work_han_thu_56_287","chapterId":"ch_work_han_thu_56","textTraditional":"二一八八頁一０行　以（置）〔致〕治也。　殿本作「致」。王先謙說作「致」是。","sentenceOrder":287},
  {"id":"s_work_han_thu_56_288","chapterId":"ch_work_han_thu_56","textTraditional":"二一八九頁一五行　讎讀曰（集）〔售〕。　景祐、殿、局本都作「售」，此誤。","sentenceOrder":288},
  {"id":"s_work_han_thu_56_289","chapterId":"ch_work_han_thu_56","textTraditional":"二一九０頁一六行　後（孝）〔考〕烈王薨，　王先謙說「孝」當作「考」。","sentenceOrder":289},
  {"id":"s_work_han_thu_57_1","chapterId":"ch_work_han_thu_57","textTraditional":"萬石君石奮，其父趙人也。趙亡，徙溫。〔一〕高祖東擊項籍，過河內，時奮年十五，為小吏，侍高祖。高祖與語，愛其恭敬，問曰：「若何有？」〔二〕對曰；「有母，不幸失明。家貧。有姊，能鼓瑟。」高祖曰：「若能從我乎？」曰：「願盡力。」於是高祖召其姊為美人，以奮為中涓，受書謁。〔三〕徙其家長安中戚里，〔四〕以姊為美人故也。","sentenceOrder":1},
  {"id":"s_work_han_thu_57_2","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　師古曰：「溫，河內之縣。」","sentenceOrder":2},
  {"id":"s_work_han_thu_57_3","chapterId":"ch_work_han_thu_57","textTraditional":"〔二〕　師古曰：「若，汝也。有何戚屬？」","sentenceOrder":3},
  {"id":"s_work_han_thu_57_4","chapterId":"ch_work_han_thu_57","textTraditional":"〔三〕　師古曰：「中涓，官名，主居中而涓潔者也。外有書謁，令奮受之也。涓音蠲。」","sentenceOrder":4},
  {"id":"s_work_han_thu_57_5","chapterId":"ch_work_han_thu_57","textTraditional":"〔四〕　師古曰：「於上有姻戚者，則皆居之，故名其里為戚里。」","sentenceOrder":5},
  {"id":"s_work_han_thu_57_6","chapterId":"ch_work_han_thu_57","textTraditional":"奮積功勞，孝文時官至太中大夫。無文學，恭謹，舉無與比〔一〕。東陽侯張相如為太子太傅，免。選可為傅者，皆推奮太子太傅。及孝景即位，以奮為九卿。迫近，憚之，〔二〕徙奮為諸侯相。奮長子建，次甲，次乙，次慶，〔三〕皆以馴行孝謹，〔四〕官至二千石。於是景帝曰：「石君及四子皆二千石，人臣尊寵乃舉集其門。」凡號奮為萬石君。〔五〕","sentenceOrder":6},
  {"id":"s_work_han_thu_57_7","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　張晏曰：「舉朝無比也。」師古曰：「舉，皆也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_57_8","chapterId":"ch_work_han_thu_57","textTraditional":"〔二〕　張晏曰：「以其恭敬履度，故難之。」","sentenceOrder":8},
  {"id":"s_work_han_thu_57_9","chapterId":"ch_work_han_thu_57","textTraditional":"〔三〕　師古曰：「史失其名，故云甲乙耳，非其名。」","sentenceOrder":9},
  {"id":"s_work_han_thu_57_10","chapterId":"ch_work_han_thu_57","textTraditional":"〔四〕　師古曰：「馴，順也，音巡。」","sentenceOrder":10},
  {"id":"s_work_han_thu_57_11","chapterId":"ch_work_han_thu_57","textTraditional":"〔五〕　師古曰：「集，合也。凡，最計也。總合其一門之計，五人為二千石，故號萬石君。」","sentenceOrder":11},
  {"id":"s_work_han_thu_57_12","chapterId":"ch_work_han_thu_57","textTraditional":"孝景季年，萬石君以上大夫祿歸老于家，以歲時為朝臣。〔一〕過宮門闕必下車趨，見路馬必軾焉。〔二〕子孫（謂）〔為〕小吏，來歸謁，萬石君必朝服見之，不名。子孫有過失，不誚讓，側，雖燕必冠，申申如也。〔四〕僮僕訢訢如也，〔五〕唯謹。〔六〕上時賜食於家，必稽首俯伏而食，如在上前。其執喪，哀戚甚。〔七〕子孫遵教，亦如之。萬石君家以孝謹聞乎郡國，雖齊魯諸儒質行，皆自以為不及也。〔八〕","sentenceOrder":12},
  {"id":"s_work_han_thu_57_13","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　師古曰：「豫朝請。」","sentenceOrder":13},
  {"id":"s_work_han_thu_57_14","chapterId":"ch_work_han_thu_57","textTraditional":"〔二〕　師古曰：「路馬，天子路車之馬。軾謂撫軾，蓋為敬也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_57_15","chapterId":"ch_work_han_thu_57","textTraditional":"〔三〕　師古曰：「便坐於便側之處，非正室也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_57_16","chapterId":"ch_work_han_thu_57","textTraditional":"〔四〕　師古曰：「申申，整敕之貌。」","sentenceOrder":16},
  {"id":"s_work_han_thu_57_17","chapterId":"ch_work_han_thu_57","textTraditional":"〔五〕　晉灼曰：「許慎云古欣字也。」師古曰：「晉說非也。此訢讀與誾誾同，謹敬之貌也，音牛巾反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_57_18","chapterId":"ch_work_han_thu_57","textTraditional":"〔六〕　師古曰：「唯以謹敬為先。」","sentenceOrder":18},
  {"id":"s_work_han_thu_57_19","chapterId":"ch_work_han_thu_57","textTraditional":"〔七〕　師古曰：「執喪，猶言持喪服也。禮記曰『執親之喪』。」","sentenceOrder":19},
  {"id":"s_work_han_thu_57_20","chapterId":"ch_work_han_thu_57","textTraditional":"〔八〕　師古曰：「質，重也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_57_21","chapterId":"ch_work_han_thu_57","textTraditional":"建元二年，郎中令王臧以文學獲罪皇太后。〔一〕太后以為儒者文多質少，今萬石君家不言而躬行，乃以長子建為郎中令，少子慶為內史。","sentenceOrder":21},
  {"id":"s_work_han_thu_57_22","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　張晏曰：「竇太后。」","sentenceOrder":22},
  {"id":"s_work_han_thu_57_23","chapterId":"ch_work_han_thu_57","textTraditional":"建老白首，萬石君尚無恙。〔一〕每五日洗沐歸謁親，〔二〕入子舍，〔三〕竊問侍者，取親中帬廁牏，身自澣洒，〔四〕復與侍者，不敢令萬石君知之，以為常。建奏事於上前，即有可言，屏人乃言極切；〔五〕至廷見，如不能言者。〔六〕上以是親而禮之。","sentenceOrder":23},
  {"id":"s_work_han_thu_57_24","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　師古曰：「恙，憂病。」","sentenceOrder":24},
  {"id":"s_work_han_thu_57_25","chapterId":"ch_work_han_thu_57","textTraditional":"〔二〕　文穎曰：「郎官五日一下。」","sentenceOrder":25},
  {"id":"s_work_han_thu_57_26","chapterId":"ch_work_han_thu_57","textTraditional":"〔三〕　師古曰：「入諸子之舍，自其所居也，若今言諸房矣。」","sentenceOrder":26},
  {"id":"s_work_han_thu_57_27","chapterId":"ch_work_han_thu_57","textTraditional":"〔四〕　服虔曰：「親身之衣也。」蘇林曰：「牏音投。賈逵解周官云『牏，行清也』。」孟康曰：「廁，行清；牏，中受糞函者也。東南人謂鑿木空中如曹謂之牏。」晉灼曰：「今世謂反門小袖衫為侯牏。」師古曰：「親謂父也。中帬，若今言中衣也。廁牏者，近身之小衫，若今汗衫也。蘇音晉說是矣。洒音先禮反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_57_28","chapterId":"ch_work_han_thu_57","textTraditional":"〔五〕　師古曰：「有可言，謂有事當奏諫。」","sentenceOrder":28},
  {"id":"s_work_han_thu_57_29","chapterId":"ch_work_han_thu_57","textTraditional":"〔六〕　師古曰：「廷見，謂當朝而見時。」","sentenceOrder":29},
  {"id":"s_work_han_thu_57_30","chapterId":"ch_work_han_thu_57","textTraditional":"萬石君徙居陵里。〔一〕內史慶醉歸，入外門不下車。萬石君聞之，不食。慶恐，肉袒謝請罪，不許。舉宗及兄建肉袒，萬石君讓曰：〔二〕「內史貴人，入閭里，里中長老皆走匿，而內史坐車中自如，固當！」〔三〕乃謝罷慶。〔四〕慶及諸子入里門，趨至家。","sentenceOrder":30},
  {"id":"s_work_han_thu_57_31","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　師古曰：「茂陵邑中之里。」","sentenceOrder":31},
  {"id":"s_work_han_thu_57_32","chapterId":"ch_work_han_thu_57","textTraditional":"〔二〕　師古曰：「讓，責也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_57_33","chapterId":"ch_work_han_thu_57","textTraditional":"〔三〕　師古曰：「此深責之也，言內史貴人，正固當爾。」","sentenceOrder":33},
  {"id":"s_work_han_thu_57_34","chapterId":"ch_work_han_thu_57","textTraditional":"〔四〕　師古曰：「告令去。」","sentenceOrder":34},
  {"id":"s_work_han_thu_57_35","chapterId":"ch_work_han_thu_57","textTraditional":"萬石君元朔五年卒，建哭泣哀思，杖乃能行。歲餘，建亦死。諸子孫咸孝，然建最甚，甚於萬石君。","sentenceOrder":35},
  {"id":"s_work_han_thu_57_36","chapterId":"ch_work_han_thu_57","textTraditional":"建為郎中令，奏事下，〔一〕建讀之，驚恐曰：「書『馬』者與尾而五，〔二〕今乃四，不足一，獲譴死矣！」其為謹慎，雖他皆如是。","sentenceOrder":36},
  {"id":"s_work_han_thu_57_37","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　師古曰：「建有所奏上而被報下也。下音胡亞反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_57_38","chapterId":"ch_work_han_thu_57","textTraditional":"〔二〕　服虔曰：「作馬字下曲者而五，建時上書誤作四。」師古曰：「馬字下曲者為尾，并四點為四足，凡五。」","sentenceOrder":38},
  {"id":"s_work_han_thu_57_39","chapterId":"ch_work_han_thu_57","textTraditional":"慶為太僕，御出，〔一〕上問車中幾馬，慶以策數馬畢，舉手曰：「六馬。」慶於兄弟最為簡易矣，然猶如此。出為齊相，齊國慕其家行，不治而齊國大治，〔二〕為立石相祠。","sentenceOrder":39},
  {"id":"s_work_han_thu_57_40","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　師古曰：「為上御車而出。」","sentenceOrder":40},
  {"id":"s_work_han_thu_57_41","chapterId":"ch_work_han_thu_57","textTraditional":"〔二〕　師古曰：「不治，言無所治罰。」","sentenceOrder":41},
  {"id":"s_work_han_thu_57_42","chapterId":"ch_work_han_thu_57","textTraditional":"元狩元年，上立太子，選群臣可傅者，慶自沛守為太子太傅，七歲遷御史大夫。元鼎五年，丞相趙周坐酎金免，制詔御史：「萬石君先帝尊之，子孫至孝，其以御史大夫慶為丞相，封牧丘侯。」是時漢方南誅兩越，東擊朝鮮，北逐匈奴，西伐大宛，中國多事。天子巡狩海內，修古神祠，封禪，興禮樂。公家用少，桑弘羊等致利，王溫舒之屬峻法，兒寬等推文學，九卿更進用事，〔一〕事不關決於慶，慶醇謹而已。〔二〕在位九歲，無能有所匡言。嘗欲請治上近臣所忠、九卿咸宣，〔三〕不能服，反受其過，贖罪。","sentenceOrder":42},
  {"id":"s_work_han_thu_57_43","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　師古曰：「更，互也，音工衡反。」","sentenceOrder":43},
  {"id":"s_work_han_thu_57_44","chapterId":"ch_work_han_thu_57","textTraditional":"〔二〕　師古曰：「醇，專厚也，音純。」","sentenceOrder":44},
  {"id":"s_work_han_thu_57_45","chapterId":"ch_work_han_thu_57","textTraditional":"〔三〕　服虔曰：「咸音減損之減。」師古曰：「治所忠及咸宣（三）〔二〕人。」","sentenceOrder":45},
  {"id":"s_work_han_thu_57_46","chapterId":"ch_work_han_thu_57","textTraditional":"元封四年，關東流民二百萬口，無名數者四十萬，〔一〕公卿議欲請徙流民於邊以適之。〔二〕上以為慶老謹，不能與其議，〔三〕乃賜丞相告歸，而案御史大夫以下議為請者。慶慚不任職，上書曰：「臣幸得待罪丞相，疲駑無以輔治。城郭倉廩空虛，民多流亡，罪當伏斧質，上不忍致法。願歸丞相侯印，乞骸骨歸，避賢者路。」","sentenceOrder":46},
  {"id":"s_work_han_thu_57_47","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　師古曰：「名數，若今戶籍。」","sentenceOrder":47},
  {"id":"s_work_han_thu_57_48","chapterId":"ch_work_han_thu_57","textTraditional":"〔二〕　師古曰：「適讀曰謫。」","sentenceOrder":48},
  {"id":"s_work_han_thu_57_49","chapterId":"ch_work_han_thu_57","textTraditional":"〔三〕　師古曰：「與讀曰豫。」","sentenceOrder":49},
  {"id":"s_work_han_thu_57_50","chapterId":"ch_work_han_thu_57","textTraditional":"上報曰：「間者，河水滔陸，〔一〕泛濫十餘郡，隄防勤勞，弗能陻塞，〔二〕朕甚憂之。是故巡方州，〔三〕禮嵩嶽，通八神，以合宣房。〔四〕濟淮江，歷山濱海，〔五〕問百年民所疾苦。惟吏多私，徵求無已，〔六〕去者便，居者擾，故為流民法，以禁重賦〔七〕。乃者封泰山，皇天嘉況，神物並見。〔八〕朕方答氣應，未能承意，〔九〕是以切比閭里，知吏姦邪。〔一０〕委任有司，然則官曠民愁，盜賊公行。〔一一〕往年覲明堂，赦殊死，無禁錮，咸自新，與更始。今流民愈多，計文不改，〔一二〕君不繩責長吏，而請以興徙四十萬口，搖蕩百姓，〔一三〕孤兒幼年未滿十歲，無罪而坐率，〔一四〕朕失望焉。今君上書言倉庫城郭不充實，民多貧，盜賊眾，請入粟為庶人。〔一五〕夫懷知民貧而請益賦，〔一六〕動危之而辭位，〔一七〕欲安歸難乎？〔一八〕君其反室！」〔一九〕","sentenceOrder":50},
  {"id":"s_work_han_thu_57_51","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　晉灼曰：「滔，漫也。」師古曰：「高平曰陸。漫音莫干反。」","sentenceOrder":51},
  {"id":"s_work_han_thu_57_52","chapterId":"ch_work_han_thu_57","textTraditional":"〔二〕　師古曰：「陻，填也，音因。」","sentenceOrder":52},
  {"id":"s_work_han_thu_57_53","chapterId":"ch_work_han_thu_57","textTraditional":"〔三〕　張晏曰：「四方之州也。」師古曰：「東方諸州。」","sentenceOrder":53},
  {"id":"s_work_han_thu_57_54","chapterId":"ch_work_han_thu_57","textTraditional":"〔四〕　孟康曰：「八神，郊祀志八神也，於宣房宮合祀之。」師古曰：「此說非也。自言致禮中嶽，通敬八神耳。合宣房者，於宣房塞決河也，事見溝洫志。」","sentenceOrder":54},
  {"id":"s_work_han_thu_57_55","chapterId":"ch_work_han_thu_57","textTraditional":"〔五〕　師古曰：「濱海者，循海涯而行也。濱音賓，又音頻。」","sentenceOrder":55},
  {"id":"s_work_han_thu_57_56","chapterId":"ch_work_han_thu_57","textTraditional":"〔六〕　師古曰：「惟，思也。已，止也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_57_57","chapterId":"ch_work_han_thu_57","textTraditional":"〔七〕　師古曰：「言百姓去其本土者則免於吏徵求，在舊居者則見煩擾，故朝廷特為流人設法，又禁吏之重賦也。一曰，去者，謂吏出使而侵擾居人以自便也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_57_58","chapterId":"ch_work_han_thu_57","textTraditional":"〔八〕　師古曰：「況，賜也。見，顯示也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_57_59","chapterId":"ch_work_han_thu_57","textTraditional":"〔九〕　師古曰：「言自修整，以報瑞應，恐未承順上天之意。」","sentenceOrder":59},
  {"id":"s_work_han_thu_57_60","chapterId":"ch_work_han_thu_57","textTraditional":"〔一０〕師古曰：「比，校考也，音頻寐反。」","sentenceOrder":60},
  {"id":"s_work_han_thu_57_61","chapterId":"ch_work_han_thu_57","textTraditional":"〔一一〕師古曰：「曠，空也。人不舉職，是空其官。」","sentenceOrder":61},
  {"id":"s_work_han_thu_57_62","chapterId":"ch_work_han_thu_57","textTraditional":"〔一二〕蘇林曰：「校戶口文書不改減也。」如淳曰：「郡上計文書，自文飾，不改正也。」師古曰：「如說是。」","sentenceOrder":62},
  {"id":"s_work_han_thu_57_63","chapterId":"ch_work_han_thu_57","textTraditional":"〔一三〕師古曰：「蕩，動也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_57_64","chapterId":"ch_work_han_thu_57","textTraditional":"〔一四〕服虔曰：「率，坐刑法也。」如淳曰：「率，家長也。」師古曰：「幼年無罪，坐為父兄所率而并徙，如說近之。」","sentenceOrder":64},
  {"id":"s_work_han_thu_57_65","chapterId":"ch_work_han_thu_57","textTraditional":"〔一五〕服虔曰：「慶自以居相位不能理，請入粟贖己罪，退為庶人。」","sentenceOrder":65},
  {"id":"s_work_han_thu_57_66","chapterId":"ch_work_han_thu_57","textTraditional":"〔一六〕師古曰：「懹此（志）〔心〕。」","sentenceOrder":66},
  {"id":"s_work_han_thu_57_67","chapterId":"ch_work_han_thu_57","textTraditional":"〔一七〕師古曰：「搖動百姓，使其危急，而自欲去位。」","sentenceOrder":67},
  {"id":"s_work_han_thu_57_68","chapterId":"ch_work_han_thu_57","textTraditional":"〔一八〕師古曰：「以此危難之事，欲歸之於何人。」","sentenceOrder":68},
  {"id":"s_work_han_thu_57_69","chapterId":"ch_work_han_thu_57","textTraditional":"〔一九〕師古曰：「若此自謂理當然者，可還家。」","sentenceOrder":69},
  {"id":"s_work_han_thu_57_70","chapterId":"ch_work_han_thu_57","textTraditional":"慶素質，見詔報反室，自以為得許，欲上印綬。掾史以為見責甚深，而終以反室者，醜惡之辭也。或勸慶宜引決。〔一〕慶甚懼，不知所出，遂復起視事。","sentenceOrder":70},
  {"id":"s_work_han_thu_57_71","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　師古曰：「令自殺。」","sentenceOrder":71},
  {"id":"s_work_han_thu_57_72","chapterId":"ch_work_han_thu_57","textTraditional":"慶為丞相，文深審謹，無他大略。後三歲餘薨，諡曰恬侯。中子德，慶愛之。上以德嗣，後為太常，坐法免，國除。慶方為丞相時，諸子孫為小吏至二千石者十三人。及慶死後，稍以罪去，孝謹衰矣。","sentenceOrder":72},
  {"id":"s_work_han_thu_57_73","chapterId":"ch_work_han_thu_57","textTraditional":"衛綰，代大陵人也，以戲車為郎，事文帝，〔一〕功次遷中郎將，醇謹無它。〔二〕孝景為太子時，召上左右飲，而綰稱病不行〔三〕。文帝且崩時，屬孝景曰：「綰長者，善遇之。」及景帝立，歲餘，不孰何綰，〔四〕綰日以謹力。〔五〕","sentenceOrder":73},
  {"id":"s_work_han_thu_57_74","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　服虔曰：「力士能扶戲車也。」應劭曰：「能左右超乘。」師古曰：「二說皆非也。戲車，若今之弄車之技。」","sentenceOrder":74},
  {"id":"s_work_han_thu_57_75","chapterId":"ch_work_han_thu_57","textTraditional":"〔二〕　師古曰：「無它餘志念也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_57_76","chapterId":"ch_work_han_thu_57","textTraditional":"〔三〕　張晏曰：「恐文帝謂豫有二心事太子。」","sentenceOrder":76},
  {"id":"s_work_han_thu_57_77","chapterId":"ch_work_han_thu_57","textTraditional":"〔四〕　服虔曰：「不問也。」李奇曰：「孰，誰也。何，呵也。」師古曰：「何即問也。不誰何者，猶言不借問耳。」","sentenceOrder":77},
  {"id":"s_work_han_thu_57_78","chapterId":"ch_work_han_thu_57","textTraditional":"〔五〕　師古曰：「自勉力為謹慎，日日益甚。」","sentenceOrder":78},
  {"id":"s_work_han_thu_57_79","chapterId":"ch_work_han_thu_57","textTraditional":"景帝幸上林，詔中郎將參乘，還而問曰：「君知所以得（驂）〔參〕乘乎？」〔一〕綰曰：「臣代戲車士，幸得功次遷，待罪中郎將，不知也。」上問曰：「吾為太子時召君，君不肯來，何也？」〔二〕對曰：「死罪，病。」上賜之劍，綰曰：「先帝賜臣劍凡六，不敢奉詔。」上曰：「劍，人之所施易，獨至今乎？」〔三〕綰曰：「具在。」上使取六劍，劍常盛，未嘗服也。〔四〕","sentenceOrder":79},
  {"id":"s_work_han_thu_57_80","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　師古曰：「言何以得參乘？」","sentenceOrder":80},
  {"id":"s_work_han_thu_57_81","chapterId":"ch_work_han_thu_57","textTraditional":"〔二〕　師古曰：「言以此特識之。」","sentenceOrder":81},
  {"id":"s_work_han_thu_57_82","chapterId":"ch_work_han_thu_57","textTraditional":"〔三〕　如淳曰：「施讀曰移。言劍者人所好，故多數移易貿換之也。」師古曰：「施讀曰貤。貤，延也，音弋豉反。」","sentenceOrder":82},
  {"id":"s_work_han_thu_57_83","chapterId":"ch_work_han_thu_57","textTraditional":"〔四〕　師古曰：「盛謂在削室之中也。盛音成。削音先召反。」","sentenceOrder":83},
  {"id":"s_work_han_thu_57_84","chapterId":"ch_work_han_thu_57","textTraditional":"郎官有譴，常蒙其罪，〔一〕不與它將爭；有功，常讓它將。上以為廉，忠實無它腸，〔二〕乃拜綰為河間王太傅。吳楚反，詔綰為將，將河間兵擊吳楚有功，拜為中尉。三歲，以軍功封綰為建陵侯。","sentenceOrder":84},
  {"id":"s_work_han_thu_57_85","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　師古曰：「蒙謂覆蔽之。」","sentenceOrder":85},
  {"id":"s_work_han_thu_57_86","chapterId":"ch_work_han_thu_57","textTraditional":"〔二〕　師古曰：「心腸之內無他惡。」","sentenceOrder":86},
  {"id":"s_work_han_thu_57_87","chapterId":"ch_work_han_thu_57","textTraditional":"明年，上廢太子，誅栗卿之屬。〔一〕上以綰為長者，不忍，乃賜綰告歸，而使郅都治捕栗氏。既已，上立膠東王為太子，召綰拜為太子太傅，遷為御史大夫。五歲，代桃侯舍為丞相，〔二〕朝奏事如職所奏。〔三〕然自初宦以至相，終無可言。〔四〕上以為敦厚可相少主，尊寵之，賞賜甚多。","sentenceOrder":87},
  {"id":"s_work_han_thu_57_88","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　師古曰：「太子廢為臨江王，故誅其外家親屬。」","sentenceOrder":88},
  {"id":"s_work_han_thu_57_89","chapterId":"ch_work_han_thu_57","textTraditional":"〔二〕　師古曰：「劉舍。」","sentenceOrder":89},
  {"id":"s_work_han_thu_57_90","chapterId":"ch_work_han_thu_57","textTraditional":"〔三〕　師古曰：「言守職分而已。」","sentenceOrder":90},
  {"id":"s_work_han_thu_57_91","chapterId":"ch_work_han_thu_57","textTraditional":"〔四〕　師古曰：「不能有所興建及廢罷。」","sentenceOrder":91},
  {"id":"s_work_han_thu_57_92","chapterId":"ch_work_han_thu_57","textTraditional":"為丞相三歲，景帝崩，武帝立。建元中，丞相以景帝病時諸官囚多坐不辜者，而君不任職，〔一〕免之。後薨，諡曰哀侯。子信嗣，坐酎金，國除。","sentenceOrder":92},
  {"id":"s_work_han_thu_57_93","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　師古曰：「天子不親政，則丞相當理之，而綰不申其冤。」","sentenceOrder":93},
  {"id":"s_work_han_thu_57_94","chapterId":"ch_work_han_thu_57","textTraditional":"直不疑，南陽人也。為郎，事文帝。其同舍有告歸，誤持其同舍郎金去。已而同舍郎覺，亡意不疑，〔一〕不疑謝有之，〔二〕買金償。後告歸者至而歸金，亡金郎大慚，以此稱為長者。稍遷至中大夫。朝，廷見，人或毀不疑〔三〕曰：「不疑狀貌甚美，然特毋柰其善盜嫂何也！」〔四〕不疑聞，曰：「我乃無兄。」然終不自明也。","sentenceOrder":94},
  {"id":"s_work_han_thu_57_95","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　師古曰：「（諡）〔疑〕其盜取。」","sentenceOrder":95},
  {"id":"s_work_han_thu_57_96","chapterId":"ch_work_han_thu_57","textTraditional":"〔二〕　師古曰：「告云實取。」","sentenceOrder":96},
  {"id":"s_work_han_thu_57_97","chapterId":"ch_work_han_thu_57","textTraditional":"〔三〕　師古曰：「當於闕廷大朝見之時，而人毀之。」","sentenceOrder":97},
  {"id":"s_work_han_thu_57_98","chapterId":"ch_work_han_thu_57","textTraditional":"〔四〕　師古曰：「盜謂私之。」","sentenceOrder":98},
  {"id":"s_work_han_thu_57_99","chapterId":"ch_work_han_thu_57","textTraditional":"吳楚反時，不疑以二千石將擊之。景帝後元年，拜為御史大夫。天子修吳楚時功，封不疑為塞侯。〔一〕武帝即位，與丞相綰俱以過免。","sentenceOrder":99},
  {"id":"s_work_han_thu_57_100","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　師古曰：「塞音先代反。」","sentenceOrder":100},
  {"id":"s_work_han_thu_57_101","chapterId":"ch_work_han_thu_57","textTraditional":"不疑學老子言。其所臨，為官如故，唯恐人之知其為吏跡也。不好立名，稱為長者。薨，諡曰信侯。傳子至孫彭祖，坐酎金，國除。","sentenceOrder":101},
  {"id":"s_work_han_thu_57_102","chapterId":"ch_work_han_thu_57","textTraditional":"周仁，其先任城人也。以毉見。〔一〕景帝為太子時，為舍人，積功遷至太中大夫。景帝初立，拜仁為郎中令。","sentenceOrder":102},
  {"id":"s_work_han_thu_57_103","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　師古曰：「見於天子。」","sentenceOrder":103},
  {"id":"s_work_han_thu_57_104","chapterId":"ch_work_han_thu_57","textTraditional":"仁為人陰重不泄。〔一〕常衣弊補衣溺袴，期為不潔清，〔二〕以是得幸，入臥內。於後宮祕戲，仁常在旁，終無所言。〔三〕上時問人，〔四〕仁曰：「上自察之。」然亦無所毀，如此。〔五〕景帝再自幸其家。家徙陽陵。上所賜甚多，然終常讓，不敢受也。諸侯群臣賂遺，終無所受。武帝立，為先帝臣重之。〔六〕仁乃病免，以二千石祿歸老，子孫咸至大官。","sentenceOrder":104},
  {"id":"s_work_han_thu_57_105","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　服虔曰：「質重不泄人之陰謀也。」張晏曰：「陰重不泄，下溼，故溺袴，是以得比宦者，得入後宮也。仁有子孫，先未得此疾時所生也。」師古曰：「張、服二說皆非也。陰，密也。為性密重不泄人言也。霍去病少言不泄，亦其類也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_57_106","chapterId":"ch_work_han_thu_57","textTraditional":"〔二〕　師古曰：「故為不絜清之事而弊敗其衣服也。溺讀曰尿。尿袴者，為小袴。以藉其尿。」","sentenceOrder":106},
  {"id":"s_work_han_thu_57_107","chapterId":"ch_work_han_thu_57","textTraditional":"〔三〕　師古曰：「是不泄也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_57_108","chapterId":"ch_work_han_thu_57","textTraditional":"〔四〕　師古曰：「問以他人之善惡。」","sentenceOrder":108},
  {"id":"s_work_han_thu_57_109","chapterId":"ch_work_han_thu_57","textTraditional":"〔五〕　師古曰：「雖知其惡，不欲言毀之，故云上自察之。」","sentenceOrder":109},
  {"id":"s_work_han_thu_57_110","chapterId":"ch_work_han_thu_57","textTraditional":"〔六〕　師古曰：「重謂敬難之。」","sentenceOrder":110},
  {"id":"s_work_han_thu_57_111","chapterId":"ch_work_han_thu_57","textTraditional":"張敺字叔，〔一〕高祖功臣安丘侯說少子也。〔二〕敺孝文時以治刑名侍太子，〔三〕然其人長者。景帝時尊重，常為九卿。至武帝元朔中，代韓安國為御史大夫。敺為吏，未嘗言按人，剸以誠長者處官。〔四〕官屬以為長者，亦不敢大欺。上具獄事，有可卻，卻之；〔五〕不可者，不得已，為涕泣，面而封之。〔六〕其愛人如此。","sentenceOrder":111},
  {"id":"s_work_han_thu_57_112","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　孟康曰：「敺音驅。」","sentenceOrder":112},
  {"id":"s_work_han_thu_57_113","chapterId":"ch_work_han_thu_57","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":113},
  {"id":"s_work_han_thu_57_114","chapterId":"ch_work_han_thu_57","textTraditional":"〔三〕　師古曰：「劉向別錄云申子學號曰刑名。刑名者，循名以責實，其尊君卑臣，崇上抑下，合於六經。說者云，刑，刑家，名，名家也，即太史公所論六家之（一）〔二〕也。此說非。」","sentenceOrder":114},
  {"id":"s_work_han_thu_57_115","chapterId":"ch_work_han_thu_57","textTraditional":"〔四〕　師古曰：「剸與專同，又音之兗反。」","sentenceOrder":115},
  {"id":"s_work_han_thu_57_116","chapterId":"ch_work_han_thu_57","textTraditional":"〔五〕　師古曰：「退令更平番之。」","sentenceOrder":116},
  {"id":"s_work_han_thu_57_117","chapterId":"ch_work_han_thu_57","textTraditional":"〔六〕　如淳曰：「不正視，若不見者也。」晉灼曰：「面對囚讀而封之，使其聞見，死而無恨也。」師古曰：「二說皆非也。面謂偝之也，言不忍視之，與呂馬童面之同義。」","sentenceOrder":117},
  {"id":"s_work_han_thu_57_118","chapterId":"ch_work_han_thu_57","textTraditional":"老篤，請免，天子亦寵以上大夫祿，歸老于家。家陽陵。子孫咸至大官。","sentenceOrder":118},
  {"id":"s_work_han_thu_57_119","chapterId":"ch_work_han_thu_57","textTraditional":"贊曰：仲尼有言「君子欲訥於言而敏於行」，〔一〕其萬石君、建陵侯、塞侯、張叔之謂與？〔二〕是以其教不肅而成，不嚴而治。至石建之澣衣，周仁為垢汙，君子譏之。","sentenceOrder":119},
  {"id":"s_work_han_thu_57_120","chapterId":"ch_work_han_thu_57","textTraditional":"〔一〕　師古曰：「論語載孔子之言也。訥，遲也。敏，疾也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_57_121","chapterId":"ch_work_han_thu_57","textTraditional":"〔二〕　師古曰：「與讀曰歟。」","sentenceOrder":121},
  {"id":"s_work_han_thu_57_122","chapterId":"ch_work_han_thu_57","textTraditional":"校勘記","sentenceOrder":122},
  {"id":"s_work_han_thu_57_123","chapterId":"ch_work_han_thu_57","textTraditional":"二一九四頁　九行　子孫（謂）〔為〕小吏，　景祐、殿、局本都作「為」。","sentenceOrder":123},
  {"id":"s_work_han_thu_57_124","chapterId":"ch_work_han_thu_57","textTraditional":"二一九七頁一三行　治所忠及咸宣（三）〔二〕人。　景祐、殿本都作「二」，此誤。","sentenceOrder":124},
  {"id":"s_work_han_thu_57_125","chapterId":"ch_work_han_thu_57","textTraditional":"二一九九頁一六行　懷此（志）〔心〕。　景祐、殿本都作「心」。","sentenceOrder":125},
  {"id":"s_work_han_thu_57_126","chapterId":"ch_work_han_thu_57","textTraditional":"二二０一頁　二行　君知所以得（驂）〔參〕乘乎？　殿本作「參」。王先謙說作「參」是。","sentenceOrder":126},
  {"id":"s_work_han_thu_57_127","chapterId":"ch_work_han_thu_57","textTraditional":"二二０二頁一四行　（諡）〔疑〕其盜取。　景祐、殿本都作「疑」，此誤。","sentenceOrder":127},
  {"id":"s_work_han_thu_57_128","chapterId":"ch_work_han_thu_57","textTraditional":"二二０五頁　一行　即太史公所論六家之（一）〔二〕也。　景祐、殿本都作「二」。王先謙說作「二」是。","sentenceOrder":128},
  {"id":"s_work_han_thu_58_1","chapterId":"ch_work_han_thu_58","textTraditional":"孝文皇帝四男：竇皇后生孝景帝、梁孝王武，諸姬生代孝王參、梁懷王揖。〔一〕","sentenceOrder":1},
  {"id":"s_work_han_thu_58_2","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　師古曰：「不得其姓氏，故曰諸姬，言在諸姬之列者也。解在高五王傳。」","sentenceOrder":2},
  {"id":"s_work_han_thu_58_3","chapterId":"ch_work_han_thu_58","textTraditional":"梁孝王武以孝文二年與太原王參、梁王揖同日立。武為代王，四年徙為淮陽王，十二年徙梁，自初王通歷已十一年矣。〔一〕","sentenceOrder":3},
  {"id":"s_work_han_thu_58_4","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　師古曰：「總數其為王之年。」","sentenceOrder":4},
  {"id":"s_work_han_thu_58_5","chapterId":"ch_work_han_thu_58","textTraditional":"孝王十四年，入朝。十七年，十八年，比年入朝，留。〔一〕其明年，乃之國。二十一年，入朝。二十二年，文帝崩。二十四年，入朝。二十五年，復入朝。是時，上未置太子，與孝王宴飲，從容言曰：〔二〕「千秋萬歲後傳於王。」王辭謝。雖知非至言，然心內喜。太后亦然。","sentenceOrder":5},
  {"id":"s_work_han_thu_58_6","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　師古曰：「比，頻也。留謂留在京師。」","sentenceOrder":6},
  {"id":"s_work_han_thu_58_7","chapterId":"ch_work_han_thu_58","textTraditional":"〔二〕　師古曰：「從音千容反。」","sentenceOrder":7},
  {"id":"s_work_han_thu_58_8","chapterId":"ch_work_han_thu_58","textTraditional":"其春，吳、楚、齊、趙七國反，先擊梁棘壁，〔一〕殺數萬人。梁王城守睢陽，〔二〕而使韓安國、張羽等為將軍以距吳、楚。吳、楚以梁為限，不敢過而西，與太尉亞夫等相距三月。吳、楚破，而梁所殺虜略與漢中分。〔三〕","sentenceOrder":8},
  {"id":"s_work_han_thu_58_9","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　文穎曰：「地名。」","sentenceOrder":9},
  {"id":"s_work_han_thu_58_10","chapterId":"ch_work_han_thu_58","textTraditional":"〔二〕　師古曰：「據睢陽城而自守。」","sentenceOrder":10},
  {"id":"s_work_han_thu_58_11","chapterId":"ch_work_han_thu_58","textTraditional":"〔三〕　孟康曰：「梁所虜吳、楚之捷略與漢同。」","sentenceOrder":11},
  {"id":"s_work_han_thu_58_12","chapterId":"ch_work_han_thu_58","textTraditional":"明年，漢立太子。梁最親，有功，又為大國，居天下膏腴地，北界泰山，西至高陽，〔一〕四十餘城，多大縣。孝王，太后少子，愛之，賞賜不可勝道。〔二〕於是孝王築東苑，方三百餘里，廣睢陽城七十里，〔三〕大治宮室，為復道，自宮連屬於平臺三十餘里。〔四〕得賜天子旌旗，從千乘萬騎，出稱警，入言〈走畢〉，〔五〕儗於天子。〔六〕招延四方豪桀，自山東游士莫不至：齊人羊勝、公孫詭、鄒陽之屬。〔七〕公孫詭多奇邪計，初見日，王賜千金，官至中尉，號曰公孫將軍。多作兵弩弓數十萬，而府庫金錢且百鉅萬，〔八〕珠玉寶器多於京師。","sentenceOrder":12},
  {"id":"s_work_han_thu_58_13","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　蘇林曰：「陳留北縣。」","sentenceOrder":13},
  {"id":"s_work_han_thu_58_14","chapterId":"ch_work_han_thu_58","textTraditional":"〔二〕　師古曰：「道謂言。」","sentenceOrder":14},
  {"id":"s_work_han_thu_58_15","chapterId":"ch_work_han_thu_58","textTraditional":"〔三〕　師古曰：「更廣大之也。晉太康地記云城方十三里，梁孝王築之。鼓倡節杵而後下和之者稱睢陽曲，今踵以為故。今之樂家睢陽曲是其遺音。」","sentenceOrder":15},
  {"id":"s_work_han_thu_58_16","chapterId":"ch_work_han_thu_58","textTraditional":"〔四〕　如淳曰：「平臺在大梁東北，離宮所在也。」晉灼曰：「或說在城中東北角。」師古曰：「今其城東二十里所有故臺基，其處寬博，土俗云平臺也。復音方目反。」","sentenceOrder":16},
  {"id":"s_work_han_thu_58_17","chapterId":"ch_work_han_thu_58","textTraditional":"〔五〕　師古曰：「警者，戒肅也。〈走畢〉，止行人也。言出入者，互文耳。出亦有〈走畢〉。漢儀注皇帝輦動，左右侍帷幄者稱警，出殿則傳蹕，止人清道也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_58_18","chapterId":"ch_work_han_thu_58","textTraditional":"〔六〕　師古曰：「儗，比也，音擬。」","sentenceOrder":18},
  {"id":"s_work_han_thu_58_19","chapterId":"ch_work_han_thu_58","textTraditional":"〔七〕　師古曰：「言皆游梁。」","sentenceOrder":19},
  {"id":"s_work_han_thu_58_20","chapterId":"ch_work_han_thu_58","textTraditional":"〔八〕　師古曰：「鉅萬，百萬也。有百萬者，言凡百也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_58_21","chapterId":"ch_work_han_thu_58","textTraditional":"二十九年十月，孝王入朝。景帝使使持乘輿駟，迎梁王於關下。〔一〕既朝，上疏，因留。以太后故，入則侍帝同輦，出則同車遊獵上林中。梁之侍中、郎、謁者著引籍出入天子殿門，〔二〕與漢宦官亡異。","sentenceOrder":21},
  {"id":"s_work_han_thu_58_22","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　鄧展曰：「但持駟馬往也。」臣瓚曰：「稱乘輿駟，則車馬皆往。言四，不駕六馬耳。天子副車駕四馬。」師古曰：「輿即車也。瓚說是。」","sentenceOrder":22},
  {"id":"s_work_han_thu_58_23","chapterId":"ch_work_han_thu_58","textTraditional":"〔二〕　師古曰：「著音竹略反。」","sentenceOrder":23},
  {"id":"s_work_han_thu_58_24","chapterId":"ch_work_han_thu_58","textTraditional":"十一月，上廢栗太子，太后心欲以梁王為嗣。大臣及爰盎等有所關說於帝，太后議格，〔一〕孝王不敢復言太后以嗣事。〔二〕事祕，世莫知，乃辭歸國。","sentenceOrder":24},
  {"id":"s_work_han_thu_58_25","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　服虔曰：「格音格鬥。」張晏曰：「止也。」蘇林曰：「音閣。」師古曰：「蘇音、張說是。」","sentenceOrder":25},
  {"id":"s_work_han_thu_58_26","chapterId":"ch_work_han_thu_58","textTraditional":"〔二〕　師古曰：「不敢更以此事言於太后。」","sentenceOrder":26},
  {"id":"s_work_han_thu_58_27","chapterId":"ch_work_han_thu_58","textTraditional":"其夏，上立膠東王為太子。梁王怨爰盎及議臣，乃與羊勝、公孫詭之屬謀，陰使人刺殺爰盎及他議臣十餘人。賊未得也。於是天子意梁，〔一〕逐賊，果梁使之。遣使冠蓋相望於道，覆案梁事。捕公孫詭、羊勝，皆匿王後宮。使者責二千石急，梁相軒丘豹〔二〕及內史安國〔三〕皆泣諫王，王乃令勝、詭皆自殺，出之。上由此怨望於梁王。〔四〕梁王恐，乃使韓安國因長公主謝罪太后，然後得釋。","sentenceOrder":27},
  {"id":"s_work_han_thu_58_28","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　師古曰：「意，疑也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_58_29","chapterId":"ch_work_han_thu_58","textTraditional":"〔二〕　師古曰：「姓軒丘，名豹。」","sentenceOrder":29},
  {"id":"s_work_han_thu_58_30","chapterId":"ch_work_han_thu_58","textTraditional":"〔三〕　師古曰：「即韓安國。」","sentenceOrder":30},
  {"id":"s_work_han_thu_58_31","chapterId":"ch_work_han_thu_58","textTraditional":"〔四〕　師古曰：「望謂責而怨之。」","sentenceOrder":31},
  {"id":"s_work_han_thu_58_32","chapterId":"ch_work_han_thu_58","textTraditional":"上怒稍解，因上書請朝。既至關，茅蘭說王，〔一〕使乘布車，〔二〕從兩騎入，匿於長公主園。漢使迎王，王已入關，車騎盡居外，外不知王處。太后泣曰：「帝殺吾子！」（弟）〔帝〕憂恐。於是梁王伏斧質，之闕下謝罪。然後太后、帝皆大喜，相與泣，復如故。悉召王從官入關。然帝益疏王，不與同車輦矣。","sentenceOrder":32},
  {"id":"s_work_han_thu_58_33","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　服虔曰：「茅蘭，孝王大夫也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_58_34","chapterId":"ch_work_han_thu_58","textTraditional":"〔二〕　張晏曰：「布車降服，自比喪人也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_58_35","chapterId":"ch_work_han_thu_58","textTraditional":"三十五年冬，復入朝。上疏欲留，上弗許。歸國，意忽忽不樂。北獵梁山，有獻牛，足上出背上，孝王惡之。六月中，病熱，六日薨。〔一〕","sentenceOrder":35},
  {"id":"s_work_han_thu_58_36","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　張晏曰：「足當處下，所以輔身也。今出背上，象孝王背朝而干上也。北者，陰也，又在梁山，明為梁也。牛者，丑之畜，衝在六月。北方數六，故六月六日王薨也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_58_37","chapterId":"ch_work_han_thu_58","textTraditional":"孝王慈孝，每聞太后病，口不能食，常欲留長安侍太后。太后亦愛之。及聞孝王死，竇太后泣極哀，不食，曰：「帝果殺吾子！」帝哀懼，不知所為。與長公主計之，乃分梁為五國，盡立孝王男五人為王，女五人皆令食湯沐邑。奏之太后，太后乃說，為帝壹餐。〔一〕","sentenceOrder":37},
  {"id":"s_work_han_thu_58_38","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　師古曰：「說讀曰悅。餐，古飡字。」","sentenceOrder":38},
  {"id":"s_work_han_thu_58_39","chapterId":"ch_work_han_thu_58","textTraditional":"孝王未死時，財以鉅萬計，不可勝數。及死，藏府餘黃金尚四十餘萬斤，他財物稱是。","sentenceOrder":39},
  {"id":"s_work_han_thu_58_40","chapterId":"ch_work_han_thu_58","textTraditional":"代孝王參初立為太原王。四年，代王武徙為淮陽王，而參徙為代王，並得復太原，都晉陽如故。〔一〕五年一朝，凡三朝。十七年薨，子共王登嗣。〔二〕二十九年薨，子義嗣。元鼎中，漢廣關，以常山為阻，〔三〕徙代王於清河，是為剛王。並前在代凡立四十年薨，子頃王湯嗣。二十四年薨，子年嗣。","sentenceOrder":40},
  {"id":"s_work_han_thu_58_41","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　師古曰：「如文帝在代時。」","sentenceOrder":41},
  {"id":"s_work_han_thu_58_42","chapterId":"ch_work_han_thu_58","textTraditional":"〔二〕　師古曰：「共讀曰恭。」","sentenceOrder":42},
  {"id":"s_work_han_thu_58_43","chapterId":"ch_work_han_thu_58","textTraditional":"〔三〕　師古曰：「依山以為關。」","sentenceOrder":43},
  {"id":"s_work_han_thu_58_44","chapterId":"ch_work_han_thu_58","textTraditional":"地節中，冀州刺史林奏年為太子時與女弟則私通。及年立為王後，則懷年子，其婿使勿舉。〔一〕則曰：「自來殺之。」婿怒曰：「為王生子，自令王家養之。」則送兒頃太后所。〔二〕相聞知，禁止則，令不得入宮。〔三〕年使從季父往來送迎則，〔四〕連年不絕。有司奏年淫亂，年坐廢為庶人，徙房陵，與湯沐邑百戶。立三年，國除。","sentenceOrder":44},
  {"id":"s_work_han_thu_58_45","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕師古曰：「不養也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_58_46","chapterId":"ch_work_han_thu_58","textTraditional":"〔二〕師古曰：「頃王之后，年之太后，故曰頃太后。」","sentenceOrder":46},
  {"id":"s_work_han_thu_58_47","chapterId":"ch_work_han_thu_58","textTraditional":"〔三〕師古曰：「相者，王之相。」","sentenceOrder":47},
  {"id":"s_work_han_thu_58_48","chapterId":"ch_work_han_thu_58","textTraditional":"〔四〕師古曰：「宗室諸從也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_58_49","chapterId":"ch_work_han_thu_58","textTraditional":"元始二年，新都侯王莽興滅繼絕，白太皇太后，立年弟子如意為廣宗王，奉代孝王後。莽篡位，國絕。","sentenceOrder":49},
  {"id":"s_work_han_thu_58_50","chapterId":"ch_work_han_thu_58","textTraditional":"梁懷王揖，文帝少子也。好詩書，帝愛之，異於他子。五年一朝，凡再入朝。因墮馬死，立十年薨。無子，國除。明年，梁孝王武徙王梁。","sentenceOrder":50},
  {"id":"s_work_han_thu_58_51","chapterId":"ch_work_han_thu_58","textTraditional":"梁孝王子五人為王。太子買為梁共王，〔一〕次子明為濟川王，彭離為濟東王，定為山陽王，不識為濟陰王，皆以孝景中六年同日立。","sentenceOrder":51},
  {"id":"s_work_han_thu_58_52","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　師古曰：「共讀曰恭。」","sentenceOrder":52},
  {"id":"s_work_han_thu_58_53","chapterId":"ch_work_han_thu_58","textTraditional":"梁共王買立十年薨，子平王襄嗣。","sentenceOrder":53},
  {"id":"s_work_han_thu_58_54","chapterId":"ch_work_han_thu_58","textTraditional":"濟川王明以垣邑侯立。七年，坐射殺其中尉，有司請誅，武帝弗忍，廢為庶人，徙房陵，國除。","sentenceOrder":54},
  {"id":"s_work_han_thu_58_55","chapterId":"ch_work_han_thu_58","textTraditional":"濟東王彭離立二十九年。彭離驕悍，〔一〕昏莫私與其奴亡命少年數十人行剽，〔二〕殺人取財物以為好。〔三〕所殺發覺者百餘人，國皆知之，莫敢夜行。所殺者子上書告言，有司請誅，武帝弗忍，廢為庶人，徙上庸，國除，為大河郡。","sentenceOrder":55},
  {"id":"s_work_han_thu_58_56","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　師古曰：「悍，勇也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_58_57","chapterId":"ch_work_han_thu_58","textTraditional":"〔二〕　師古曰：「剽，劫也，音頻妙反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_58_58","chapterId":"ch_work_han_thu_58","textTraditional":"〔三〕　如淳曰：「以是為好喜之事也。」師古曰：「好音呼到反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_58_59","chapterId":"ch_work_han_thu_58","textTraditional":"山陽哀王定立九年薨。亡子，國除。","sentenceOrder":59},
  {"id":"s_work_han_thu_58_60","chapterId":"ch_work_han_thu_58","textTraditional":"濟陰哀王不識立一年薨。亡子，國除。","sentenceOrder":60},
  {"id":"s_work_han_thu_58_61","chapterId":"ch_work_han_thu_58","textTraditional":"孝王支子四王，皆絕於身。〔一〕","sentenceOrder":61},
  {"id":"s_work_han_thu_58_62","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　師古曰：「支子，謂非正嫡也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_58_63","chapterId":"ch_work_han_thu_58","textTraditional":"梁平王襄，母曰陳太后。共王母曰李太后。李太后，親平王之大母也。〔一〕而平王之后曰任后，任后甚有寵於襄。","sentenceOrder":63},
  {"id":"s_work_han_thu_58_64","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　師古曰：「大母，祖母也。共王即李太后所生，故云親祖母也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_58_65","chapterId":"ch_work_han_thu_58","textTraditional":"初，孝王有尊，〔一〕直千金，戒後世善寶之，毋得以與人。〔二〕任后聞而欲得之。李太后曰：「先王有命，毋得以尊與人。他物雖百鉅萬，猶自恣。」任后絕欲得之。王襄直使人開府取尊賜任后，又王及母陳太后事李太后多不順。有漢使者來，李太后欲自言，王使謁者中郎胡等遮止，閉門。李太后與爭門，措指，〔三〕太后啼謼，〔四〕不得見漢使者。李太后亦私與食官長及郎尹霸等姦亂，王與任后以此使人風止李太后。〔五〕李太后亦已，〔六〕後病薨。病時，任后未嘗請疾；〔七〕薨，又不侍喪。","sentenceOrder":65},
  {"id":"s_work_han_thu_58_66","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　應劭曰：「詩云『酌彼金』。，畫雲雷之象，以金飾之也。」鄭氏曰：「上蓋刻為山雲雷之象。」師古曰：「鄭說是也。，古雷字。」","sentenceOrder":66},
  {"id":"s_work_han_thu_58_67","chapterId":"ch_work_han_thu_58","textTraditional":"〔二〕　師古曰：「寶謂愛守也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_58_68","chapterId":"ch_work_han_thu_58","textTraditional":"〔三〕　晉灼曰：「許慎云『措，置』。字借以為笮耳。」師古曰：「音壯客反，謂為門扉所笮。」","sentenceOrder":68},
  {"id":"s_work_han_thu_58_69","chapterId":"ch_work_han_thu_58","textTraditional":"〔四〕　師古曰：「謼音火故反。」","sentenceOrder":69},
  {"id":"s_work_han_thu_58_70","chapterId":"ch_work_han_thu_58","textTraditional":"〔五〕　師古曰：「風讀曰諷。止者，止其自言也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_58_71","chapterId":"ch_work_han_thu_58","textTraditional":"〔六〕　師古曰：「已，止也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_58_72","chapterId":"ch_work_han_thu_58","textTraditional":"〔七〕　張晏曰：「請，問也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_58_73","chapterId":"ch_work_han_thu_58","textTraditional":"元朔中，睢陽人犴反，〔一〕人辱其父，而與睢陽太守客俱出同車。犴反殺其仇車上，亡去。睢陽太守怒，以讓梁二千石。二千石以下求反急，執反親戚。反知國陰事，乃上變告梁王與大母爭尊狀。時相以下具知之，欲以傷梁長吏，書聞。天子下吏驗問，有之。公卿治，奏以為不孝，請誅王及太后。〔二〕天子曰：「首惡失道，任后也。朕置相吏不逮，〔三〕無以輔王，故陷不誼，不忍致法。」削梁王五縣，奪王太后湯沐成陽邑，梟任后首于市，中郎胡等皆伏誅。梁餘尚有八城。","sentenceOrder":73},
  {"id":"s_work_han_thu_58_74","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　師古曰：「犴姓，反名也。犴音岸。」","sentenceOrder":74},
  {"id":"s_work_han_thu_58_75","chapterId":"ch_work_han_thu_58","textTraditional":"〔二〕　師古曰：「陳太后。」","sentenceOrder":75},
  {"id":"s_work_han_thu_58_76","chapterId":"ch_work_han_thu_58","textTraditional":"〔三〕　師古曰：「逮，及也，言其材知不及。」","sentenceOrder":76},
  {"id":"s_work_han_thu_58_77","chapterId":"ch_work_han_thu_58","textTraditional":"襄立四十年薨，子頃王無傷嗣。十一年薨，子敬王定國嗣。四十年薨，子夷王遂嗣。六年薨，子荒王嘉嗣。十五年薨，子立嗣。","sentenceOrder":77},
  {"id":"s_work_han_thu_58_78","chapterId":"ch_work_han_thu_58","textTraditional":"鴻嘉中，太傅輔奏：「立一日至十一犯法，臣下愁苦，莫敢親近，不可諫止。願令王，非耕、祠，法駕毋得出宮，盡出馬置外苑，收兵杖藏私府，毋得以金錢財物假賜人。」事下丞相、御史，請許〔一〕。奏可。後數復敺傷郎，〔二〕夜私出宮。傅相連奏，坐削或千戶或五百戶，如是者數焉。","sentenceOrder":78},
  {"id":"s_work_han_thu_58_79","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　師古曰：「許太傅所奏。」","sentenceOrder":79},
  {"id":"s_work_han_thu_58_80","chapterId":"ch_work_han_thu_58","textTraditional":"〔二〕　師古曰：「敺，棰擊，音一口反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_58_81","chapterId":"ch_work_han_thu_58","textTraditional":"荒王女弟園子為立舅任寶妻，寶兄子昭為立后。數過寶飲食，報寶曰：「我好翁主，〔一〕欲得之。」寶曰：「翁主，姑也，法重。」立曰：「何能為！」〔二〕遂與園子姦。","sentenceOrder":81},
  {"id":"s_work_han_thu_58_82","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　師古曰：「諸王女皆稱翁主，言其父自主婚也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_58_83","chapterId":"ch_work_han_thu_58","textTraditional":"〔二〕　師古曰：「言罪不能至重也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_58_84","chapterId":"ch_work_han_thu_58","textTraditional":"積數歲，永始中，相禹奏立對外家怨望，有惡言。有司案驗，因發淫亂事，奏立禽獸行，請誅。太中大夫谷永上疏曰：「臣聞『禮，天子外屏，不欲見外』也。〔一〕是故帝王之意，不窺人閨門之私，聽聞中冓之言。〔二〕春秋為親者諱。詩云『戚戚兄弟，莫遠具爾』。〔三〕今梁王年少，頗有狂病，始以惡言按驗，既亡事實，而發閨門之私，非本章所指。王辭又不服，猥強劾立，傅致難明之事，〔四〕獨以偏辭成罪斷獄，亡益於治道。汙衊宗室，〔五〕以內亂之惡披布宣揚於天下，非所以為公族隱諱，增朝廷之榮華，昭聖德之風化也。臣愚以為王少，而父同產長，年齒不倫；梁國之富，足以厚聘美女，招致妖麗；父同產亦有恥辱之心。〔六〕案事者乃驗問惡言，〔七〕何故猥自發舒？〔八〕以三者揆之，殆非人情，疑有所迫切，過誤失言，文吏躡尋，不得轉移。萌牙之時，加恩勿治，上也。〔九〕既已案驗舉憲，宜及王辭不服，詔廷尉選上德通理之吏，更審考清問，著不然之效，定失誤之法，〔一０〕而反命於下吏，〔一一〕以廣公族附疏之德，為宗室刷汙亂之恥，〔一二〕甚得治親之誼。」天子由是寢而不治。","sentenceOrder":84},
  {"id":"s_work_han_thu_58_85","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　師古曰：「屏謂當門之牆，以屏蔽者也。外屏，於門外為之。」","sentenceOrder":85},
  {"id":"s_work_han_thu_58_86","chapterId":"ch_work_han_thu_58","textTraditional":"〔二〕　應劭曰：「中冓，材構在堂之中也。」晉灼曰：「魯詩以為夜也。」師古曰：「冓謂舍之交積材木也。應說近之。冓音工豆反。」","sentenceOrder":86},
  {"id":"s_work_han_thu_58_87","chapterId":"ch_work_han_thu_58","textTraditional":"〔三〕　師古曰：「小雅行葦之詩也。戚戚，內相親也。爾，近也。言王之族親，情無疏遠，皆昵近也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_58_88","chapterId":"ch_work_han_thu_58","textTraditional":"〔四〕　師古曰：「傅讀曰附。」","sentenceOrder":88},
  {"id":"s_work_han_thu_58_89","chapterId":"ch_work_han_thu_58","textTraditional":"〔五〕　孟康曰：「衊音漫。」師古曰：「衊音秣，謂塗染也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_58_90","chapterId":"ch_work_han_thu_58","textTraditional":"〔六〕　師古曰：「言其姑亦當自恥，必不與姦。」","sentenceOrder":90},
  {"id":"s_work_han_thu_58_91","chapterId":"ch_work_han_thu_58","textTraditional":"〔七〕　師古曰：「本所問者，怨望朝廷之言耳。」","sentenceOrder":91},
  {"id":"s_work_han_thu_58_92","chapterId":"ch_work_han_thu_58","textTraditional":"〔八〕　師古曰：「猥，曲也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_58_93","chapterId":"ch_work_han_thu_58","textTraditional":"〔九〕　如淳曰：「覆蓋之，則計之上。」","sentenceOrder":93},
  {"id":"s_work_han_thu_58_94","chapterId":"ch_work_han_thu_58","textTraditional":"〔一０〕師古曰：「著，明也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_58_95","chapterId":"ch_work_han_thu_58","textTraditional":"〔一一〕師古曰：「使者還反，以清白之狀付有司也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_58_96","chapterId":"ch_work_han_thu_58","textTraditional":"〔一二〕師古曰：「刷謂拭刷除之也，音所劣反。」","sentenceOrder":96},
  {"id":"s_work_han_thu_58_97","chapterId":"ch_work_han_thu_58","textTraditional":"居數歲，元延中，立復以公事怨相掾及睢陽丞，使奴殺之，殺奴以滅口。凡殺三人，傷五人，手敺郎吏二十餘人。上書不拜奏。謀篡死罪囚。〔一〕有司請誅，上不忍，削立五縣。","sentenceOrder":97},
  {"id":"s_work_han_thu_58_98","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　師古曰：「逆取曰篡。」","sentenceOrder":98},
  {"id":"s_work_han_thu_58_99","chapterId":"ch_work_han_thu_58","textTraditional":"哀帝建平中，立復殺人。天子遣廷尉賞、大鴻臚由持節即訊〔一〕。至，移書傅、相、中尉曰：「王背策戒，〔二〕誖暴妄行，〔三〕連犯大辟，毒流吏民。比比蒙恩，不伏重誅，〔四〕不思改過，復賊殺人。幸得蒙恩，丞相長史、大鴻臚丞即問。王陽病抵讕，置辭驕嫚，〔五〕不首主令，與背畔亡異。〔六〕丞相、御史請收王璽綬，送陳留獄。明詔加恩，復遣廷尉、大鴻臚雜問。今王當受詔置辭，恐復不首實對。書曰：『至于再三，有不用，我降爾命。』〔七〕傅、相、中尉皆以輔正為職，『虎兕出於匣，龜玉毀於匱中，是誰之過也？』〔八〕書到，明以誼曉王。敢復懷詐，罪過益深。傅、相以下，不能輔導，有正法。」","sentenceOrder":99},
  {"id":"s_work_han_thu_58_100","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　師古曰：「就問也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_58_101","chapterId":"ch_work_han_thu_58","textTraditional":"〔二〕　師古曰：「初封時，策書有戒敕之言。」","sentenceOrder":101},
  {"id":"s_work_han_thu_58_102","chapterId":"ch_work_han_thu_58","textTraditional":"〔三〕　師古曰：「誖，乖也，音布內反。」","sentenceOrder":102},
  {"id":"s_work_han_thu_58_103","chapterId":"ch_work_han_thu_58","textTraditional":"〔四〕　師古曰：「比猶頻也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_58_104","chapterId":"ch_work_han_thu_58","textTraditional":"〔五〕　師古曰：「抵，距也。讕，誣諱也。抵音丁禮反。讕音來亶反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_58_105","chapterId":"ch_work_han_thu_58","textTraditional":"〔六〕　師古曰：「不首謂不伏其罪也。主令者，於法令之條與背畔無異也。首音失救反。次下亦同。」","sentenceOrder":105},
  {"id":"s_work_han_thu_58_106","chapterId":"ch_work_han_thu_58","textTraditional":"〔七〕　師古曰：「此周書多方篇之辭也。言我教汝，至于再三，汝不能用，則我下罰黜汝命也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_58_107","chapterId":"ch_work_han_thu_58","textTraditional":"〔八〕　師古曰：「此論語孔子責冉有、季路之辭也。言虎兕出於檻，龜玉毀於櫝匱，豈非典守者之過邪？喻輔相人者，當能持危扶顛也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_58_108","chapterId":"ch_work_han_thu_58","textTraditional":"立惶恐，免冠對曰：「立少失父母，孤弱處深宮中，獨與宦者婢妾居，漸漬小國之俗，加以質性下愚，有不可移之姿。〔一〕往者傅相亦不純以仁誼輔翼立，大臣皆尚苛刻，刺求微密。讒臣在其間，左右弄口，積使上下不和，更相眄伺。〔二〕宮殿之裏，毛氂過失，亡不暴陳。當伏重誅，以視海內，〔三〕數蒙聖恩，得見貰赦。〔四〕今立自知賊殺中郎曹將，冬月迫促，貪生畏死，即詐僵仆陽病，〔五〕徼幸得踰於須臾。〔六〕謹以實對，伏須重誅。」〔七〕時冬月盡，其春大赦，不治。","sentenceOrder":108},
  {"id":"s_work_han_thu_58_109","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　師古曰：「言不從化也。論語稱孔子曰『唯上智與下愚不移』。」","sentenceOrder":109},
  {"id":"s_work_han_thu_58_110","chapterId":"ch_work_han_thu_58","textTraditional":"〔二〕　師古曰：「更音工衡反。」","sentenceOrder":110},
  {"id":"s_work_han_thu_58_111","chapterId":"ch_work_han_thu_58","textTraditional":"〔三〕　師古曰：「視讀曰示。」","sentenceOrder":111},
  {"id":"s_work_han_thu_58_112","chapterId":"ch_work_han_thu_58","textTraditional":"〔四〕　師古曰：「貰謂寬其罪。」","sentenceOrder":112},
  {"id":"s_work_han_thu_58_113","chapterId":"ch_work_han_thu_58","textTraditional":"〔五〕　師古曰：「僵仆，倒地也。僵音薑。仆音赴。」","sentenceOrder":113},
  {"id":"s_work_han_thu_58_114","chapterId":"ch_work_han_thu_58","textTraditional":"〔六〕　師古曰：「冀得踰冬月而減罪也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_58_115","chapterId":"ch_work_han_thu_58","textTraditional":"〔七〕　師古曰：「須，待也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_58_116","chapterId":"ch_work_han_thu_58","textTraditional":"元始中，立坐與平帝外家中山衛氏交通，新都侯王莽奏廢立為庶人，徙漢中。立自殺。二十七年，國除。後二歲，莽白太皇太后立孝王玄孫之曾孫沛郡卒史音為梁王，奉孝王後。莽篡，國絕。","sentenceOrder":116},
  {"id":"s_work_han_thu_58_117","chapterId":"ch_work_han_thu_58","textTraditional":"贊曰：梁孝王雖以愛親故王膏腴之地，〔一〕然會漢家隆盛，百姓殷富，故能殖其貨財，廣其宮室車服。然亦僭矣。怙親亡厭，牛禍告罰，卒用憂死，悲夫！","sentenceOrder":117},
  {"id":"s_work_han_thu_58_118","chapterId":"ch_work_han_thu_58","textTraditional":"〔一〕　師古曰：「太后愛子，而帝親弟，故曰愛親。」","sentenceOrder":118},
  {"id":"s_work_han_thu_58_119","chapterId":"ch_work_han_thu_58","textTraditional":"校勘記","sentenceOrder":119},
  {"id":"s_work_han_thu_58_120","chapterId":"ch_work_han_thu_58","textTraditional":"二二一０頁一二行　（弟）〔帝〕憂恐。　景祐、殿、局本都作「帝」。王先謙說作「帝」是。","sentenceOrder":120},
  {"id":"s_work_han_thu_58_121","chapterId":"ch_work_han_thu_58","textTraditional":"二二一八頁　五行　王陽病抵讕，置辭驕嫚，〔五〕　注〔五〕原在「置辭」下。劉攽說「驕嫚」當屬上句。王先謙亦說當讀「置辭驕嫚」為句。","sentenceOrder":121},
  {"id":"s_work_han_thu_59_1","chapterId":"ch_work_han_thu_59","textTraditional":"賈誼，雒陽人也，年十八，以能誦詩書屬文稱於郡中。〔一〕河南守吳公聞其秀材，召置門下，〔二〕甚幸愛。文帝初立，聞河南守吳公治平為天下第一，〔三〕故與李斯同邑，而嘗學事焉，〔四〕徵以為廷尉。廷尉乃言誼年少，頗通諸家之書。文帝召以為博士。","sentenceOrder":1},
  {"id":"s_work_han_thu_59_2","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「屬謂綴輯之也，言其能為文也。屬音之欲反。」","sentenceOrder":2},
  {"id":"s_work_han_thu_59_3","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「秀，美也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_59_4","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「治平，言其政治和平也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_59_5","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「事之而從其學也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_59_6","chapterId":"ch_work_han_thu_59","textTraditional":"是諸，誼年二十餘，最為少。每詔令議下，〔一〕諸老先生未能言，誼盡為之對，人人各如其意所出。諸生於是以為能。文帝說之，〔二〕超遷，歲中至太中大夫。","sentenceOrder":6},
  {"id":"s_work_han_thu_59_7","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「謂有詔令出下及遣議事。」","sentenceOrder":7},
  {"id":"s_work_han_thu_59_8","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":8},
  {"id":"s_work_han_thu_59_9","chapterId":"ch_work_han_thu_59","textTraditional":"誼以為漢興二十餘年，天下和洽，宜當改正朔，易服色制度，定官名，興禮樂。乃草具其儀法，〔一〕色上黃，數用五，為官名悉更，奏之。〔二〕文帝謙讓未皇也。〔三〕然諸法令所更定，及列侯就國，其說皆誼發之。於是天子議以誼任公卿之位。絳、灌、東陽侯、馮敬之屬盡害之，〔四〕乃毀誼曰：「雒陽之人年少初學，專欲擅權，紛亂諸事。」於是天子後亦疏之，不用其議，以誼為長沙王太傅。","sentenceOrder":9},
  {"id":"s_work_han_thu_59_10","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「草謂創造之。」","sentenceOrder":10},
  {"id":"s_work_han_thu_59_11","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「更，改也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_59_12","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「皇，暇也。自以為不當改制。」","sentenceOrder":12},
  {"id":"s_work_han_thu_59_13","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「絳，絳侯周勃也。灌，灌嬰也。東陽侯，張相如也。馮敬，時為御史大夫。」","sentenceOrder":13},
  {"id":"s_work_han_thu_59_14","chapterId":"ch_work_han_thu_59","textTraditional":"誼既以適去，〔一〕意不自得，及度湘水，〔二〕為賦以弔屈原。屈原，楚賢臣也，被讒放逐，作離騷賦，〔三〕其終篇曰：「已矣！國亡人，莫我知也。」遂自投江而死。誼追傷之，因以自諭。〔四〕其辭曰：","sentenceOrder":14},
  {"id":"s_work_han_thu_59_15","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「適讀曰謫。其下亦同。」","sentenceOrder":15},
  {"id":"s_work_han_thu_59_16","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「湘水出零陵陽海山，北流入江也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_59_17","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「離，遭也。憂動曰騷。遭憂而作此辭。」","sentenceOrder":17},
  {"id":"s_work_han_thu_59_18","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「諭，譬也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_59_19","chapterId":"ch_work_han_thu_59","textTraditional":"恭承嘉惠兮，〔一〕俟罪長沙。〔二〕仄聞屈原兮，自湛汨羅。〔三〕造託湘流兮，敬弔先生。〔四〕遭世罔極兮，迺隕厥身。〔五〕烏虖哀哉兮，逢時不祥！〔六〕鸞鳳伏竄兮，鴟鴞翱翔。〔七〕闒茸尊顯兮，讒諛得志；〔八〕賢聖逆曳兮，方正倒植。〔九〕謂隨、夷溷兮，〔一０〕謂跖、蹻廉；〔一一〕莫邪為鈍兮，〔一二〕鈆刀為銛。〔一三〕于嗟默默，生之亡故兮！〔一四〕斡棄周鼎〔一五〕，寶康瓠兮。〔一六〕騰駕罷牛，驂蹇驢兮；〔一七〕驥垂兩耳，服鹽車兮。〔一八〕章父薦屨，漸不可久兮；〔一九〕嗟（若）〔苦〕先生，獨離此咎兮！〔二０〕","sentenceOrder":19},
  {"id":"s_work_han_thu_59_20","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「恭，敬也。嘉惠，謂詔命也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_59_21","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「俟，古俟字。俟，待也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_59_22","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「仄，古側字。汨，水名，在長沙羅縣，故曰汨羅。湛讀曰沉。汨音莫歷反。」","sentenceOrder":22},
  {"id":"s_work_han_thu_59_23","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「造，至也。言至湘水而因託其流也。造音千到反。」","sentenceOrder":23},
  {"id":"s_work_han_thu_59_24","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　張晏曰：「讒言罔極。」師古曰：「罔，無也。極，中也，無中正之道。一曰極，止也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_59_25","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　師古曰：「虖讀曰呼。」","sentenceOrder":25},
  {"id":"s_work_han_thu_59_26","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　師古曰：「鴟，鴟鵂，怪鳥也。鴞，惡聲之鳥也。鴟音尺夷反。鴞音于驕反。鵂音休。」","sentenceOrder":26},
  {"id":"s_work_han_thu_59_27","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　師古曰：「闒茸，下材不肖之人也。闒音吐盍反。茸音人勇反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_59_28","chapterId":"ch_work_han_thu_59","textTraditional":"〔九〕　師古曰：「植，立也，音值。」","sentenceOrder":28},
  {"id":"s_work_han_thu_59_29","chapterId":"ch_work_han_thu_59","textTraditional":"〔一０〕應劭曰：「隨，卞隨，湯時廉士，湯以天下讓而不受。夷，伯夷也，不食周粟，餓于首陽之下。」師古曰：「溷，濁也，音胡困反。」","sentenceOrder":29},
  {"id":"s_work_han_thu_59_30","chapterId":"ch_work_han_thu_59","textTraditional":"〔一一〕李奇曰：「跖，秦大盜也。楚之大盜為莊蹻。」師古曰：「跖音之石反。蹻音居略反。莊周云，盜跖，柳下惠之弟，蓋寓言也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_59_31","chapterId":"ch_work_han_thu_59","textTraditional":"〔一二〕應劭曰：「莫邪，吳大夫也，作寶劍，因以冠名。」","sentenceOrder":31},
  {"id":"s_work_han_thu_59_32","chapterId":"ch_work_han_thu_59","textTraditional":"〔一三〕晉灼曰：「世俗為利為銛徹。」師古曰：「音弋占反。」","sentenceOrder":32},
  {"id":"s_work_han_thu_59_33","chapterId":"ch_work_han_thu_59","textTraditional":"〔一四〕應劭曰：「默默，不得意也。」鄧展曰：「言屈原無故遇此禍也。」師古曰：「生，先生也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_59_34","chapterId":"ch_work_han_thu_59","textTraditional":"〔一五〕師古曰：「斡，轉也，音管。」","sentenceOrder":34},
  {"id":"s_work_han_thu_59_35","chapterId":"ch_work_han_thu_59","textTraditional":"〔一六〕鄭氏曰：「康瓠，瓦盆底也。爾雅曰：『康瓠謂之甈。』」師古曰：「甈音五列反。」","sentenceOrder":35},
  {"id":"s_work_han_thu_59_36","chapterId":"ch_work_han_thu_59","textTraditional":"〔一七〕師古曰：「罷讀曰疲。蹇，跛也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_59_37","chapterId":"ch_work_han_thu_59","textTraditional":"〔一八〕師古曰：「駕鹽車也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_59_38","chapterId":"ch_work_han_thu_59","textTraditional":"〔一九〕師古曰：「章父，殷冠名也。言冠乃居下，屨反在上也。父讀曰甫。」","sentenceOrder":38},
  {"id":"s_work_han_thu_59_39","chapterId":"ch_work_han_thu_59","textTraditional":"〔二０〕應劭曰：「嗟，咨嗟也。勞苦屈原遇此難也。」師古曰：「離，遭也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_59_40","chapterId":"ch_work_han_thu_59","textTraditional":"誶曰：〔一〕已矣！國其莫吾知兮，〔二〕子獨壹鬱其誰語？〔三〕鳳縹縹其高逝兮，夫固自引而遠去。〔四〕襲九淵之神龍兮，〔五〕沕淵潛以自珍；〔六〕偭蟂獺以隱處兮，〔七〕夫豈從蝦與蛭螾？〔八〕所貴聖之神德兮，遠濁世而自臧。使麒麟可係而羈兮，豈云異夫犬羊？般紛紛其離此郵兮，〔九〕亦夫子之故也！〔一０〕歷九州而相其君兮，何必懷此都也？〔一一〕鳳皇翔于千仞兮，覽德煇而下之；〔一二〕見細德之險（微）〔徵〕兮，遙增擊而去之〔一三〕。彼尋常之汙瀆兮，豈容吞舟之魚！〔一四〕橫江湖之鱣鯨兮，固將制於螻螘。〔一五〕","sentenceOrder":40},
  {"id":"s_work_han_thu_59_41","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　李奇曰：「誶，告也。」張晏曰：「誶，離騷下章亂也。」師古曰：「誶音碎。」","sentenceOrder":41},
  {"id":"s_work_han_thu_59_42","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「一國之人不知我也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_59_43","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「壹鬱猶怫鬱也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_59_44","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「縹縹，輕舉貌，音匹遙反。」","sentenceOrder":44},
  {"id":"s_work_han_thu_59_45","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　鄧展曰：「襲，重也。」師古曰：「九淵，九旋之川，言至深也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_59_46","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　鄧展曰：「沕音昧。」張晏曰：「潛，藏也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_59_47","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　服虔曰：「蟂音梟。」應劭曰：「蟂獺，水蟲害魚者也。偭，背也。欲舍蟂獺，從神龍遊也。」師古曰：「偭音面。」","sentenceOrder":47},
  {"id":"s_work_han_thu_59_48","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　服虔曰：「蛭，水蟲。螾，今之螼螾也。」孟康曰：「言龍自絕於蟂獺，況從蝦與蛭螾也。」師古曰：「蝦亦水蟲也，音遐。蛭音質。螾字與蚓同，音引，今合韻，當音弋人反。螼音丘謹反。」","sentenceOrder":48},
  {"id":"s_work_han_thu_59_49","chapterId":"ch_work_han_thu_59","textTraditional":"〔九〕　蘇林曰：「般音槃。」孟康曰：「般音班。般，反也。紛紛，搆讒意也。」師古曰：「般，孟音是也。字從丹青之丹。離，遭也。郵，過也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_59_50","chapterId":"ch_work_han_thu_59","textTraditional":"〔一０〕李奇曰：「亦夫子不如麟鳳之故，離此咎也。」師古曰：「此說非也。賈誼自言今之離郵，亦猶屈原耳。」","sentenceOrder":50},
  {"id":"s_work_han_thu_59_51","chapterId":"ch_work_han_thu_59","textTraditional":"〔一一〕師古曰：「言往長沙為傅，不足哀傷，何用苟懷此之都邑，蓋亦誼自寬廣之言。」","sentenceOrder":51},
  {"id":"s_work_han_thu_59_52","chapterId":"ch_work_han_thu_59","textTraditional":"〔一二〕師古曰：「八尺曰仞。千仞，言其極高。」","sentenceOrder":52},
  {"id":"s_work_han_thu_59_53","chapterId":"ch_work_han_thu_59","textTraditional":"〔一三〕師古曰：「增，重也。言見苛細之人，險阨之證，故重擊其羽而高去。」","sentenceOrder":53},
  {"id":"s_work_han_thu_59_54","chapterId":"ch_work_han_thu_59","textTraditional":"〔一四〕應劭曰：「八尺曰尋，倍尋曰常。」師古曰：「水不泄為汙，音一胡反，又音一故反。」","sentenceOrder":54},
  {"id":"s_work_han_thu_59_55","chapterId":"ch_work_han_thu_59","textTraditional":"〔一五〕如淳曰：「鱣、鯨，皆大魚也。」臣瓚曰：「鱣魚無鱗，口在腹下。鯨魚長者長數里。」晉灼曰：「小水不容大魚，而橫鱣鯨於汙瀆，必為螻螘所制。以況小朝主闇，不容受忠逆之言，亦為讒賊小臣所害。」師古曰：「鱣音竹連反，字或作鱏。鱏亦大魚也，音淫，又音尋。螻音樓，謂螻蛄也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_59_56","chapterId":"ch_work_han_thu_59","textTraditional":"誼為長沙傅三年，有服飛入誼舍，止於坐隅。〔一〕服似鴞〔二〕，不祥鳥也。誼既以適居長沙，長沙卑濕，誼自傷悼，以為壽不得長，乃為賦以自廣。其辭曰：","sentenceOrder":56},
  {"id":"s_work_han_thu_59_57","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「坐音才臥反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_59_58","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　晉灼曰：「異物志曰『有鳥，小雞，體有文色，土俗因形名之曰服，不能遠飛，行不出域』也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_59_59","chapterId":"ch_work_han_thu_59","textTraditional":"單閼之歲，四月孟夏，〔一〕庚子日斜，服集余舍，〔二〕止于坐隅，貌甚閒暇。〔三〕異物來崪，私怪其故，〔四〕發書占之，讖言其度。〔五〕曰「野鳥入室，主人將去。」問于子服：「余去何之？〔六〕吉虖告我，凶言其災。淹速之度，語余其期。」〔七〕","sentenceOrder":59},
  {"id":"s_work_han_thu_59_60","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　應劭曰：「太歲在卯為單閼。」師古曰：「閼音一葛反。」","sentenceOrder":60},
  {"id":"s_work_han_thu_59_61","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　孟康曰：「日斜，日昳時。」","sentenceOrder":61},
  {"id":"s_work_han_thu_59_62","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「閒讀曰閑。」","sentenceOrder":62},
  {"id":"s_work_han_thu_59_63","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　孟康曰：「崪音萃。萃，聚集也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_59_64","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　師古曰：「讖，驗也，有徵驗之書也。讖音初禁反。」","sentenceOrder":64},
  {"id":"s_work_han_thu_59_65","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　師古曰：「子服者，言加其美稱也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_59_66","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　師古曰：「淹，遲也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_59_67","chapterId":"ch_work_han_thu_59","textTraditional":"服乃太息，舉首奮翼，口不能言，請對以意。〔一〕萬物變化，固亡休息。斡流而遷，或推而還。〔二〕形氣轉續，變化而嬗。〔三〕沕穆亡間，胡可勝言！〔四〕禍兮福所倚，福兮禍所伏；〔五〕憂喜聚門，吉凶同域。〔六〕彼吳彊大，夫差以敗；粵棲會稽，句踐伯世。〔七〕斯遊遂成，卒被五刑；〔八〕傅說胥靡，乃相武丁。〔九〕夫禍之與福，何異糾纆！〔一０〕命不可說，孰知其極？〔一一〕水激則旱，矢激則遠。〔一二〕萬物回薄，震蕩相轉。雲烝雨降，糾錯相紛。大鈞播物，坱圠無垠。〔一三〕天不可與慮，道不可與謀。遲速有命，烏識其時？〔一四〕","sentenceOrder":67},
  {"id":"s_work_han_thu_59_68","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「意字合韻，宜音億。」","sentenceOrder":68},
  {"id":"s_work_han_thu_59_69","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「斡音管。斡，轉也。還讀曰旋。」","sentenceOrder":69},
  {"id":"s_work_han_thu_59_70","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　服虔曰：「嬗音如蟬，謂變蛻也。」蘇林曰：「相傳與也。」師古曰：「此即禪代字，合韻故音嬋耳。蘇說是也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_59_71","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「沕穆，深微貌，胡，何也。言其理深微，不可盡言。沕音勿。」","sentenceOrder":71},
  {"id":"s_work_han_thu_59_72","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　師古曰：「此老子德經之言也。倚音於綺反。」","sentenceOrder":72},
  {"id":"s_work_han_thu_59_73","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　師古曰：「言禍福相因，吉凶不定。」","sentenceOrder":73},
  {"id":"s_work_han_thu_59_74","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　師古曰：「會稽，山名也。句踐避吳之難，保於茲山，故曰棲也。句音鉤。伯讀曰霸。」","sentenceOrder":74},
  {"id":"s_work_han_thu_59_75","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　應劭曰：「李斯西遊於秦，身登相位，二世時為趙高所讒，身伏五刑。」","sentenceOrder":75},
  {"id":"s_work_han_thu_59_76","chapterId":"ch_work_han_thu_59","textTraditional":"〔九〕　張晏曰：「胥靡，刑名也。傅說被刑，築於傅巖，武丁以為己相。」師古曰：「胥靡，相隨之刑也，解在楚元王傳。」","sentenceOrder":76},
  {"id":"s_work_han_thu_59_77","chapterId":"ch_work_han_thu_59","textTraditional":"〔一０〕應劭曰：「禍福相為表裏，如糾繩索相附會也。」臣瓚曰：「糾，絞也。纆，索也。」師古曰：「纆音墨。」","sentenceOrder":77},
  {"id":"s_work_han_thu_59_78","chapterId":"ch_work_han_thu_59","textTraditional":"〔一一〕師古曰：「極，止也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_59_79","chapterId":"ch_work_han_thu_59","textTraditional":"〔一二〕師古曰：「言水之激疾，則去盡，不能浸潤。矢之激發，則去遠。」","sentenceOrder":79},
  {"id":"s_work_han_thu_59_80","chapterId":"ch_work_han_thu_59","textTraditional":"〔一三〕如淳曰：「陶者作器於鈞上，此以造化為大鈞也。」應劭曰：「其氣坱圠，非有限齊也。」師古曰：「今造瓦者謂所轉者為鈞，言造化為人，亦猶陶之造瓦耳。坱音烏朗反。圠音於黠反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_59_81","chapterId":"ch_work_han_thu_59","textTraditional":"〔一四〕師古曰：「烏猶何也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_59_82","chapterId":"ch_work_han_thu_59","textTraditional":"且夫天地為鑪，造化為工；陰陽為炭，萬物為銅，〔一〕合散消息，安有常則？千變萬化，未始有極。忽然為人，何足控揣〔二〕；化為異物，又何足患！〔三〕小智自私，賤彼貴我；達人大觀，物亡不可。貪夫徇財，列士徇名；〔四〕夸者死權，品庶每生。〔五〕怵迫之徒，或趨西東；〔六〕大人不曲，意變齊同。愚士繫俗，時若囚拘；〔七〕至人遺物，獨與道俱。眾人惑惑，好惡積意；〔八〕真人恬漠，獨與道息。〔九〕釋智遺形，超然自喪；〔一０〕寥廓忽荒，與道翱翔。〔一一〕乘流則逝，得坎則止；〔一二〕縱軀委命，不私與己。其生兮若浮，其死兮若休。〔一三〕澹虖若深淵之靚，氾虖若不繫之舟。〔一四〕不以生故自保，養空而浮。〔一五〕德人無累，知命不憂。細故蔕芥，何足以疑！〔一六〕","sentenceOrder":82},
  {"id":"s_work_han_thu_59_83","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「以冶鑄為喻。」","sentenceOrder":83},
  {"id":"s_work_han_thu_59_84","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　孟康曰：「控，引也。揣，持也。言人生忽然，何足引持自貴（借）〔惜〕也。」如淳曰：「控，引也。揣音團。控摶，玩弄愛生之意也。」師古曰：「如說是。」","sentenceOrder":84},
  {"id":"s_work_han_thu_59_85","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「患合韻音環。」","sentenceOrder":85},
  {"id":"s_work_han_thu_59_86","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　臣瓚曰：「以身從物曰徇。」","sentenceOrder":86},
  {"id":"s_work_han_thu_59_87","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　臣瓚曰：「謂夸泰也。莊子曰『權勢不（充）〔尤〕，則夸者悲』。」孟康曰：「每，貪也。」師古曰：「品庶猶庶品也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_59_88","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　孟康曰：「怵，為利所誘訹也。迫，迫貧賤，東西趨利也。」師古曰：「誘訹之訹則音戍。或曰，怵，怵惕也，音丑出反，其義兩通。而說者欲改字為鉥，蓋穿鑿耳。」","sentenceOrder":88},
  {"id":"s_work_han_thu_59_89","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　李奇曰：「時音塊。」蘇林曰：「音人肩傴時爾。音欺全反。」師古曰：「蘇音是。」","sentenceOrder":89},
  {"id":"s_work_han_thu_59_90","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　李奇曰：「惑惑，東西也。所好所惡，積之萬億也。」臣瓚曰：「言眾懷好惡，積之心意也。」師古曰：「瓚說是也。意合韻音於力反。」","sentenceOrder":90},
  {"id":"s_work_han_thu_59_91","chapterId":"ch_work_han_thu_59","textTraditional":"〔九〕　師古曰：「恬，安也。漠，靜也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_59_92","chapterId":"ch_work_han_thu_59","textTraditional":"〔一０〕服虔曰：「絕聖棄智，而亡其身也。」師古曰：「喪合韻音先郎反。」","sentenceOrder":92},
  {"id":"s_work_han_thu_59_93","chapterId":"ch_work_han_thu_59","textTraditional":"〔一一〕師古曰：「荒音呼廣反。」","sentenceOrder":93},
  {"id":"s_work_han_thu_59_94","chapterId":"ch_work_han_thu_59","textTraditional":"〔一二〕孟康曰：「易『坎為險』，遇險難而止也。」張晏曰：「謂夷易則仕，險難則隱也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_59_95","chapterId":"ch_work_han_thu_59","textTraditional":"〔一三〕師古曰：「休，息也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_59_96","chapterId":"ch_work_han_thu_59","textTraditional":"〔一四〕師古曰：「澹，安也，音徒濫反。靚與靜同。氾音敷劍反。」","sentenceOrder":96},
  {"id":"s_work_han_thu_59_97","chapterId":"ch_work_han_thu_59","textTraditional":"〔一五〕服虔曰：「道家養空虛，若浮舟也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_59_98","chapterId":"ch_work_han_thu_59","textTraditional":"〔一六〕師古曰：「蔕芥，小鯁也。蔕音丑芥反。」","sentenceOrder":98},
  {"id":"s_work_han_thu_59_99","chapterId":"ch_work_han_thu_59","textTraditional":"後歲餘，文帝思誼，徵之。至，入見，上方受釐，坐宣室。〔一〕上因感鬼神事，而問鬼神之本。誼具道所以然之故。至夜半，文帝前席。〔二〕既罷，曰：「吾久不見賈生，自以為過之，今不及也。」乃拜誼為梁懷王太傅。懷王，上少子，愛，而好書，故令誼傅之，數問以得失。〔三〕","sentenceOrder":99},
  {"id":"s_work_han_thu_59_100","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　蘇林曰：「宣室，未央前正室也。」應劭曰：「釐，祭餘肉也。漢儀注祭天地五畤，皇帝不自行，祠還致福。釐音禧。」師古曰：「禧，福也。借釐字為之耳，言受神之福也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_59_101","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「漸迫近誼，聽說其言也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_59_102","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「漢朝問以國家之事。」","sentenceOrder":102},
  {"id":"s_work_han_thu_59_103","chapterId":"ch_work_han_thu_59","textTraditional":"是時，匈奴彊，侵邊。天下初定，制度疏闊。諸侯王僭儗，地過古制，〔一〕淮南、濟北王皆為逆誅。誼數上疏陳政事，多所欲匡建，〔二〕其大略曰：","sentenceOrder":103},
  {"id":"s_work_han_thu_59_104","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「儗，比也，上比於天子。儗音擬。」","sentenceOrder":104},
  {"id":"s_work_han_thu_59_105","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「匡，正也，正其失也。建，立也，立制節也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_59_106","chapterId":"ch_work_han_thu_59","textTraditional":"臣竊惟事勢，可為痛哭者一，可為流涕者二，可為長太息者六，若其它背理而傷道者，難遍以疏舉。〔一〕進言者皆曰天下已安已治矣，〔二〕臣獨以為未也。曰安且治者，非愚則諛，〔三〕皆非事實知治亂之體者也。夫抱火厝之積薪之下而寢其上，〔四〕火未及燃，因謂之安，方今之勢，何以異此！本末舛逆，首尾衡決，國制搶攘，〔五〕非甚有紀，〔六〕胡可謂治！陛下何不壹令臣得孰數之於前，因陳治安之策，試詳擇焉！","sentenceOrder":106},
  {"id":"s_work_han_thu_59_107","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「言不可盡條記也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_59_108","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「進言者，謂陳說於天子前者也。治音直吏反。此下並同。」","sentenceOrder":108},
  {"id":"s_work_han_thu_59_109","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「實謂治安，則是愚也；知其不爾而假言之，是諂諛也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_59_110","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「厝，置也，音千故反。」","sentenceOrder":110},
  {"id":"s_work_han_thu_59_111","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　蘇林曰：「搶音濟濟蹌蹌，不安貌也。」晉灼曰：「搶音傖。吳人罵楚人曰傖。傖攘，亂貌也。」師古曰：「晉音是。傖音仕庚反。攘音女庚反。」","sentenceOrder":111},
  {"id":"s_work_han_thu_59_112","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　師古曰：「紀，理也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_59_113","chapterId":"ch_work_han_thu_59","textTraditional":"夫射獵之娛，與安危之機孰急？〔一〕使為治，勞智慮，苦身體，乏鍾鼓之樂，勿為可也。樂與今同，而加之諸侯軌道，兵革不動，〔二〕民保首領，匈奴賓服，四荒鄉風，〔三〕百姓素朴，獄訟衰息，大數既得，則天下順治，海內之氣清和咸理，生為明帝，沒為明神，名譽之美，垂於無窮。禮祖有功而宗有德，使顧成之廟稱為太宗，上配太祖，與漢亡極。建久安之勢，成長治之業，以承祖廟，以奉六親，至孝也；〔四〕以幸天下，以育群生，至仁也；立經陳紀，輕重同得，後可以為萬世法程，〔五〕雖有愚幼不肖之嗣，猶得蒙業而安，至明也。以陛下之明達，因使少知治體者得佐下風，致此非難也。〔六〕其具可素陳於前，願幸無忽。〔七〕臣謹稽之天地，〔八〕驗之往古，按之當今之務，日夜念此至孰也，雖使禹舜復生，為陛下計，亡以易此。〔九〕","sentenceOrder":113},
  {"id":"s_work_han_thu_59_114","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「言二事之中，何者為急。」","sentenceOrder":114},
  {"id":"s_work_han_thu_59_115","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「軌道，言遵法制也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_59_116","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":116},
  {"id":"s_work_han_thu_59_117","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　應劭曰：「六親，父母兄弟妻子也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_59_118","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　師古曰：「程，式也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_59_119","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　師古曰：「少知治體者，誼自謂也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_59_120","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　師古曰：「忽，怠忘也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_59_121","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　師古曰：「稽，考也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_59_122","chapterId":"ch_work_han_thu_59","textTraditional":"〔九〕　師古曰：「易，改也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_59_123","chapterId":"ch_work_han_thu_59","textTraditional":"夫樹國固必相疑之勢，〔一〕下數被其殃，上數爽其憂〔二〕，甚非所以安上而全下也。今或親弟謀為東帝，〔三〕親兄之子西鄉而擊，〔四〕今吳又見告矣。〔五〕天子春秋鼎盛，〔六〕行義未過，〔七〕德澤有加焉，猶尚如是，況莫大諸侯，〔八〕權力且十此者虖！〔九〕","sentenceOrder":123},
  {"id":"s_work_han_thu_59_124","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　鄭氏曰：「今建立國泰大，其勢必固相疑也。」臣瓚曰：「樹國於險固，諸侯強大，則必與天子有相疑之勢也。」師古曰：「鄭說是也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_59_125","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　如淳曰：「爽，忒也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_59_126","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　應劭曰：「淮南厲王長。」","sentenceOrder":126},
  {"id":"s_work_han_thu_59_127","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　如淳曰：「謂齊悼惠王子興居而為濟北王反，欲擊取滎陽也。」師古曰：「鄉讀曰嚮。」","sentenceOrder":127},
  {"id":"s_work_han_thu_59_128","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　如淳曰：「時吳王又不循漢法，有告之者。」","sentenceOrder":128},
  {"id":"s_work_han_thu_59_129","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　應劭曰：「鼎，方也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_59_130","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　師古曰：「行音下更反。」","sentenceOrder":130},
  {"id":"s_work_han_thu_59_131","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　師古曰：「莫大，謂無有大於其國者，言最大也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_59_132","chapterId":"ch_work_han_thu_59","textTraditional":"〔九〕　師古曰：「十倍於此。」","sentenceOrder":132},
  {"id":"s_work_han_thu_59_133","chapterId":"ch_work_han_thu_59","textTraditional":"然而天下少安，何也？大國之王幼弱未壯，漢之所置傅相方握其事。數年之後，諸侯之王大抵皆冠，〔一〕血氣方剛，漢之傅相稱病而賜罷，彼自丞尉以上偏置私人，如此，有異淮南、濟北之為邪！此時而欲為治安，雖堯舜不治。","sentenceOrder":133},
  {"id":"s_work_han_thu_59_134","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「大抵，猶言大略也，音丁禮反。其下亦同。」","sentenceOrder":134},
  {"id":"s_work_han_thu_59_135","chapterId":"ch_work_han_thu_59","textTraditional":"黃帝曰：「日中必{蔧火}，操刀必割。」〔一〕今令此道順而全安，甚易，不肯早為，已乃墮骨肉之屬而抗剄之，〔二〕豈有異秦之季世虖！夫以天子之位，乘今之時，因天之助，尚憚以危為安，以亂為治，假設陛下居齊桓之處，將不合諸侯而匡天下乎？臣又以知陛下有所必不能矣。假設天下如曩時，〔三〕淮陰侯尚王楚，黥布王淮南，彭越王梁，韓信王韓，張敖王趙，貫高為相，盧綰王燕，陳豨在代，令此六七公者皆亡恙，〔四〕當是時而陛下即天子位，能自安乎？臣有以知陛下之不能也。天下殽亂，高皇帝與諸公併起，〔五〕非有仄室之勢以豫席之也。〔六〕諸公幸者，乃為中涓，其次廑得舍人，〔七〕材之不逮至遠也。高皇帝以明聖威武即天子位，割膏腴之地以王諸公，多者百餘城，少者乃三四十縣，德至渥也，〔八〕然其後十年之間，反者九起。陛下之與諸公，非親角材而臣之也，〔九〕又非身封王之也，自高皇帝不能以是一歲為安，故臣知陛下之不能也。然尚有可諉者，曰疏，〔一０〕臣請試言其親者。假令悼惠王王齊，元王王楚，中子王趙，幽王王淮陽，共王王梁，〔一一〕靈王王燕，厲王王淮南，六七貴人皆亡恙，當是時陛下即位，能為治虖？臣又知陛下之不能也。若此諸王，雖名為臣，實皆有布衣昆弟之心，〔一二〕慮亡不帝制而天子自為者。〔一三〕擅爵人，赦死罪，〔一四〕甚者或戴黃屋，〔一五〕漢法令非行也。雖行不軌如厲王者，令之不肯聽，召之安可致乎！〔一六〕幸而來至，法安可得加！動一親戚，天下圜視而起，〔一七〕陛下之臣雖有悍如馮敬者，〔一八〕適啟其口，匕首已陷其匈矣。〔一九〕陛下雖賢，誰與領此？〔二０〕故疏者必危，親者必亂，已然之效也。其異姓負彊而動者，漢已幸勝之矣，又不易其所以然。同姓襲是跡而動，〔二一〕既有徵矣，〔二二〕其勢盡又復然。殃禍之變，未知所移，〔二三〕明帝處之尚不能以安，後世將如之何！","sentenceOrder":135},
  {"id":"s_work_han_thu_59_136","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　孟康曰：「{蔧火}音衛。日中盛者，必暴{蔧火}也。」臣瓚曰：「太公曰『日中不{蔧火}，是謂失時；操刀不割，失利之期。』言當及時也。」師古曰：「此語見六韜。{蔧火}謂暴曬之也。曬音所智反，又音所懈反。」","sentenceOrder":136},
  {"id":"s_work_han_thu_59_137","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　應劭曰：「抗其頭而剄之也。」師古曰：「墮，毀也。抗，舉也。剄，割頸也。墮音火規反。剄音工鼎反。」","sentenceOrder":137},
  {"id":"s_work_han_thu_59_138","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「曩，久也。謂昔時。」","sentenceOrder":138},
  {"id":"s_work_han_thu_59_139","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「無恙，言無憂病。」","sentenceOrder":139},
  {"id":"s_work_han_thu_59_140","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　師古曰：「殽，雜也。併音步鼎反。」","sentenceOrder":140},
  {"id":"s_work_han_thu_59_141","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　應劭曰：「禮，卿大夫之支子為側室。席，大也。」臣瓚曰：「席，藉也。言非有側室之勢為之資藉也。」師古曰：「瓚說是也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_59_142","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　師古曰：「廑與僅同。廑，劣也，言纔得舍人。」","sentenceOrder":142},
  {"id":"s_work_han_thu_59_143","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　師古曰：「德，古德字。渥，厚也，音握。」","sentenceOrder":143},
  {"id":"s_work_han_thu_59_144","chapterId":"ch_work_han_thu_59","textTraditional":"〔九〕　師古曰：「角，校也，競也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_59_145","chapterId":"ch_work_han_thu_59","textTraditional":"〔一０〕孟康曰：「諉，累也。以疏為累，言不以國也。」蔡謨曰：「諉者，託也。尚可託言信、越等以疏故反，故其下句曰『臣請試言其親者』。親者亦恃彊為亂，明信等不以疏也。」師古曰：「蔡說是矣。諉音女瑞反。」","sentenceOrder":145},
  {"id":"s_work_han_thu_59_146","chapterId":"ch_work_han_thu_59","textTraditional":"〔一一〕師古曰：「共讀曰恭。」","sentenceOrder":146},
  {"id":"s_work_han_thu_59_147","chapterId":"ch_work_han_thu_59","textTraditional":"〔一二〕師古曰：「自以為於天子為昆弟，而不論君臣之義。」","sentenceOrder":147},
  {"id":"s_work_han_thu_59_148","chapterId":"ch_work_han_thu_59","textTraditional":"〔一三〕師古曰：「慮，大計也，言諸侯皆欲同皇帝之制度，而為天子之事。」","sentenceOrder":148},
  {"id":"s_work_han_thu_59_149","chapterId":"ch_work_han_thu_59","textTraditional":"〔一四〕師古曰：「擅，專也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_59_150","chapterId":"ch_work_han_thu_59","textTraditional":"〔一五〕師古曰：「天子車蓋之制。」","sentenceOrder":150},
  {"id":"s_work_han_thu_59_151","chapterId":"ch_work_han_thu_59","textTraditional":"〔一六〕師古曰：「不軌，謂不修法制也。致，至也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_59_152","chapterId":"ch_work_han_thu_59","textTraditional":"〔一七〕應劭曰：「圜，精正視也。」師古曰：「言驚愕也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_59_153","chapterId":"ch_work_han_thu_59","textTraditional":"〔一八〕如淳曰：「馮無擇子，名忠直，為御史大夫，奏淮南厲王誅之。」師古曰：「悍，勇也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_59_154","chapterId":"ch_work_han_thu_59","textTraditional":"〔一九〕師古曰：「始欲發言節制諸侯王，則為刺客所殺。」","sentenceOrder":154},
  {"id":"s_work_han_thu_59_155","chapterId":"ch_work_han_thu_59","textTraditional":"〔二０〕師古曰：「領，理也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_59_156","chapterId":"ch_work_han_thu_59","textTraditional":"〔二一〕師古曰：「易其所以然，謂改其法制使不然。」","sentenceOrder":156},
  {"id":"s_work_han_thu_59_157","chapterId":"ch_work_han_thu_59","textTraditional":"〔二二〕師古曰：「徵，證驗也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_59_158","chapterId":"ch_work_han_thu_59","textTraditional":"〔二三〕師古曰：「禍，古禍字。」","sentenceOrder":158},
  {"id":"s_work_han_thu_59_159","chapterId":"ch_work_han_thu_59","textTraditional":"屠牛坦一朝解十二牛，〔一〕而芒刃不頓者，〔二〕所排擊剝割，皆眾理解也。〔三〕至於髖髀之所，非斤則斧。〔四〕夫仁義恩厚，人主之芒刃也；權勢法制，人主之斤斧也。今諸侯王皆眾髖髀也，釋斤斧之用，而欲嬰以芒刃，〔五〕臣以為不缺則折。胡不用之淮南、濟北？勢不可也。〔六〕","sentenceOrder":159},
  {"id":"s_work_han_thu_59_160","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　蘇林曰：「孔子時人也。」師古曰：「坦，屠牛者之名也。事見管子。」","sentenceOrder":160},
  {"id":"s_work_han_thu_59_161","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「芒刃，謂刃之利如豪芒也。頓讀曰鈍。」","sentenceOrder":161},
  {"id":"s_work_han_thu_59_162","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「解，支節也，音胡懈反。」","sentenceOrder":162},
  {"id":"s_work_han_thu_59_163","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「髀，股骨也。髖，髀上也。言其骨大，故須斤斧也。髖音寬。髀音陛，又音必爾反。」","sentenceOrder":163},
  {"id":"s_work_han_thu_59_164","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　師古曰：「嬰，繞也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_59_165","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　晉灼曰：「（一）〔二〕國皆反誅。何不施之仁恩？勢不可故也。」","sentenceOrder":165},
  {"id":"s_work_han_thu_59_166","chapterId":"ch_work_han_thu_59","textTraditional":"臣竊跡前事，〔一〕大抵彊者先反。淮陰王楚最彊，則最先反；韓信倚胡，則又反；〔二〕貫高因趙資，則又反；陳豨兵精，則又反；彭越用梁，則又反；〔三〕黥布用淮南，則又反；盧綰最弱，最後反。長沙乃在二萬五千戶耳，功少而最完，勢疏而最忠，非獨性異人也，亦形勢然也。曩令樊、酈、絳、灌據數十城而王，今雖以殘亡可也；〔四〕令信、越之倫列為徹侯而居，雖至今存可也。〔五〕然則天下之大計可知已。〔六〕欲諸王之皆忠附，則莫若令如長沙王；欲臣子之勿菹醢，則莫若令如樊、酈等；欲天下之治安，莫若眾建諸侯而少其力。力少則易使以義，國小則亡邪心。〔七〕令海內之勢如身之使臂，臂之使指，莫不制從，諸侯之君不敢有異心，輻湊並進而歸命天子，雖在細民，且知其安，故天下咸知陛下之明。割地定制，令齊、趙、楚各為若干國，〔八〕使悼惠王、幽王、元王之子孫畢以次各受祖之分地，〔九〕地盡而止，及燕、梁它國皆然。其分地眾而子孫少者，建以為國，空而置之，須其子孫生者，舉使君之。〔一０〕諸侯之地其削頗入漢者，為徙其侯國及封其子孫也，〔一一〕所以數償之：一寸之地，一人之眾，天子亡所利焉，〔一二〕誠以定治而已，故天下咸知陛下之廉。地制壹定，宗室子孫莫慮不王，〔一三〕下無倍畔之心，上無誅伐之志，〔一四〕故天下咸知陛下之仁。法立而不犯，令行而不逆，貫高、利幾之謀不生，柴奇、開章之計不萌，〔一五〕細民鄉善，大臣致順，〔一六〕故天下咸知陛下之義。臥赤子天下之上而安，植遺腹，朝委裘，而天下不亂，〔一七〕當時大治，後世誦聖。〔一八〕壹動而五業附，陛下誰憚而久不為此？〔一九〕","sentenceOrder":166},
  {"id":"s_work_han_thu_59_167","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「尋前事之蹤跡。」","sentenceOrder":167},
  {"id":"s_work_han_thu_59_168","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「倚，依也，音於綺反。」","sentenceOrder":168},
  {"id":"s_work_han_thu_59_169","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　晉灼曰：「用，役用之也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_59_170","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　晉灼曰：「事勢可亡也。」師古曰：「曩亦謂昔時也。」","sentenceOrder":170},
  {"id":"s_work_han_thu_59_171","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　晉灼曰：「事勢可存。」","sentenceOrder":171},
  {"id":"s_work_han_thu_59_172","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　師古曰：「已，語終辭。」","sentenceOrder":172},
  {"id":"s_work_han_thu_59_173","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　師古曰：「使以義，使之遵禮義也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_59_174","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　師古曰：「若干，豫設數也。解在食貨志。」","sentenceOrder":174},
  {"id":"s_work_han_thu_59_175","chapterId":"ch_work_han_thu_59","textTraditional":"〔九〕　師古曰：「分音扶問反，次下亦同。」","sentenceOrder":175},
  {"id":"s_work_han_thu_59_176","chapterId":"ch_work_han_thu_59","textTraditional":"〔一０〕師古曰：「須，待也。」","sentenceOrder":176},
  {"id":"s_work_han_thu_59_177","chapterId":"ch_work_han_thu_59","textTraditional":"〔一一〕師古曰：「徙其侯國，列侯國邑在諸侯王封內而犬牙相入者，則正其疆界，令其隔絕也。封其子孫者，分諸侯王之國邑，各自封其子孫，而受封之人若有罪黜，其地皆入於漢，故云頗入也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_59_178","chapterId":"ch_work_han_thu_59","textTraditional":"〔一二〕師古曰：「償者，謂所正列侯疆界，有侵諸侯王者，則漢償之。」","sentenceOrder":178},
  {"id":"s_work_han_thu_59_179","chapterId":"ch_work_han_thu_59","textTraditional":"〔一三〕師古曰：「慮，計也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_59_180","chapterId":"ch_work_han_thu_59","textTraditional":"〔一四〕師古曰：「倍讀曰偝。」","sentenceOrder":180},
  {"id":"s_work_han_thu_59_181","chapterId":"ch_work_han_thu_59","textTraditional":"〔一五〕應劭曰：「柴奇、開章，皆與淮南王謀反者也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_59_182","chapterId":"ch_work_han_thu_59","textTraditional":"〔一六〕師古曰：「鄉讀曰嚮。」","sentenceOrder":182},
  {"id":"s_work_han_thu_59_183","chapterId":"ch_work_han_thu_59","textTraditional":"〔一七〕服虔曰：「言天下安，雖赤子遺腹在位，猶不危也。」應劭曰：「置遺腹，朝委裘，皆未有所知也。」孟康曰：「委裘，若容衣，天子未坐朝，事先帝裘衣也。」師古曰：「應、孟二說皆是。」","sentenceOrder":183},
  {"id":"s_work_han_thu_59_184","chapterId":"ch_work_han_thu_59","textTraditional":"〔一八〕師古曰：「稱誦其聖明。」","sentenceOrder":184},
  {"id":"s_work_han_thu_59_185","chapterId":"ch_work_han_thu_59","textTraditional":"〔一九〕師古曰：「憚，畏難也，音徒旦反。」","sentenceOrder":185},
  {"id":"s_work_han_thu_59_186","chapterId":"ch_work_han_thu_59","textTraditional":"天下之勢方病大瘇。〔一〕一脛之大幾如要，一指之大幾如股，〔二〕平居不可屈信，〔三〕一二指搐，身慮亡聊。〔四〕失今不治，必為錮疾，〔五〕後雖有扁鵲，不能為已。〔六〕病非徒瘇也，又苦蹠盭。〔七〕元王之子，帝之從弟也；〔八〕今之王者，從弟之子也。惠王，親兄子也；今之王者，兄子之子也。〔九〕親者或亡分地以安天下，〔一０〕疏者或制大權以偪天子，〔一一〕臣故曰非徒病瘇也，又苦蹠盭。可痛哭者，此病是也。","sentenceOrder":186},
  {"id":"s_work_han_thu_59_187","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　如淳曰：「腫足曰瘇。」師古曰：「音上勇反。」","sentenceOrder":187},
  {"id":"s_work_han_thu_59_188","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「幾，並音巨依反。」","sentenceOrder":188},
  {"id":"s_work_han_thu_59_189","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「信讀曰伸。」","sentenceOrder":189},
  {"id":"s_work_han_thu_59_190","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「搐謂動而痛也。聊，賴也。搐音丑六反。」","sentenceOrder":190},
  {"id":"s_work_han_thu_59_191","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　師古曰：「錮疾，堅久之疾。」","sentenceOrder":191},
  {"id":"s_work_han_thu_59_192","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　師古曰：「扁鵲，良醫也。為，治也。已，語終辭。」","sentenceOrder":192},
  {"id":"s_work_han_thu_59_193","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　師古曰：「〈足炙〉，古蹠字也，音之石反。足下曰蹠，今所呼腳掌是也。盭，古戾字，言足蹠反戾，不可行也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_59_194","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　師古曰：「楚元王，高帝之弟，其子於文帝為從弟。」","sentenceOrder":194},
  {"id":"s_work_han_thu_59_195","chapterId":"ch_work_han_thu_59","textTraditional":"〔九〕　師古曰：「惠王，齊悼惠王。」","sentenceOrder":195},
  {"id":"s_work_han_thu_59_196","chapterId":"ch_work_han_thu_59","textTraditional":"〔一０〕師古曰：「廣立蕃屏，則天下安，故曰以安天下。」","sentenceOrder":196},
  {"id":"s_work_han_thu_59_197","chapterId":"ch_work_han_thu_59","textTraditional":"〔一一〕師古曰：「偪，古逼字。」","sentenceOrder":197},
  {"id":"s_work_han_thu_59_198","chapterId":"ch_work_han_thu_59","textTraditional":"天下之勢方倒縣。凡天子者，天下之首，何也？上也。蠻夷者，天下之足，何也？下也。今匈奴嫚娒侵掠，至不敬也，〔一〕為天下患，至亡已也，〔二〕而漢歲致金絮采繒以奉之。夷狄徵令，是主上之操也；〔三〕天子共貢，是臣下之禮也。〔四〕足反居上，首顧居下，〔五〕倒縣如此，莫之能解，猶為國有人乎？〔六〕非亶倒縣而已，〔七〕又類辟，且病痱。〔八〕夫辟者一面病，痱者一方痛。今西邊北邊之郡，雖有長爵不輕得復，〔九〕五尺以上不輕得息，〔一０〕斥候望烽燧不得臥，〔一一〕將吏被介冑而睡，〔一二〕臣故曰一方病矣。醫能治之，而上不使，〔一三〕可為流涕者此也。","sentenceOrder":198},
  {"id":"s_work_han_thu_59_199","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「娒，古侮字。」","sentenceOrder":199},
  {"id":"s_work_han_thu_59_200","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「亡已，言不可止也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_59_201","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「徵，召也。令，號令也。操謂主上之所操持也。操音千高反。」","sentenceOrder":201},
  {"id":"s_work_han_thu_59_202","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「共讀曰恭。」","sentenceOrder":202},
  {"id":"s_work_han_thu_59_203","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　師古曰：「顧亦反也，言如人反顧然。」","sentenceOrder":203},
  {"id":"s_work_han_thu_59_204","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　師古曰：「顛倒如此，而不能解救，豈謂國有明智之人乎？」","sentenceOrder":204},
  {"id":"s_work_han_thu_59_205","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　師古曰：「亶讀曰但。」","sentenceOrder":205},
  {"id":"s_work_han_thu_59_206","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　服虔曰：「病（癖）〔辟〕，不能行也。」師古曰：「辟，足病。痱，風。辟音壁。痱音肥。」","sentenceOrder":206},
  {"id":"s_work_han_thu_59_207","chapterId":"ch_work_han_thu_59","textTraditional":"〔九〕　張晏曰：「長爵，高爵也。雖受高爵之賞，猶將禦寇，不得復除逸豫也。」蘇林曰：「輕，易也。不易得復除，言難也。」師古曰：「復音方目反。」","sentenceOrder":207},
  {"id":"s_work_han_thu_59_208","chapterId":"ch_work_han_thu_59","textTraditional":"〔一０〕如淳曰：「五尺謂小兒也。言無大小皆當自為戰備。」","sentenceOrder":208},
  {"id":"s_work_han_thu_59_209","chapterId":"ch_work_han_thu_59","textTraditional":"〔一一〕文穎曰：「邊方備胡寇，作高土櫓，櫓上作桔皋，桔皋頭兜零，以薪草置其中，常低之，有寇即火然舉之以相告，曰烽。又多積薪，寇至即燃之，以望其煙，曰燧。」張晏曰：「晝舉烽，夜燔燧也。」師古曰：「張說誤也。晝則燔燧，夜則舉烽。」","sentenceOrder":209},
  {"id":"s_work_han_thu_59_210","chapterId":"ch_work_han_thu_59","textTraditional":"〔一二〕師古曰：「被音皮義反。」","sentenceOrder":210},
  {"id":"s_work_han_thu_59_211","chapterId":"ch_work_han_thu_59","textTraditional":"〔一三〕師古曰：「醫者，誼自謂。」","sentenceOrder":211},
  {"id":"s_work_han_thu_59_212","chapterId":"ch_work_han_thu_59","textTraditional":"陛下何忍以帝皇之號為戎人諸侯，勢既卑辱，而禍不息，長此安窮！〔一〕進謀者率以為是，固不可解也，亡具甚矣。〔二〕臣竊料匈奴之眾〔三〕不過漢一大縣，以天下之大困於一縣之眾，甚為執事者羞之。陛下何不試以臣為屬國之官以主匈奴？行臣之計，請必係單于之頸而制其命，伏中行說而笞其背，〔四〕舉匈奴之眾唯上之令。〔五〕今不獵猛敵而獵田彘，不搏反寇而搏畜菟，翫細娛而不圖大患，非所以為安也。德可遠施，威可遠加，而直數百里外威令不信，〔六〕可為流涕者此也。","sentenceOrder":212},
  {"id":"s_work_han_thu_59_213","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「言長養此患，將何所窮極也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_59_214","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「無治安之具。」","sentenceOrder":214},
  {"id":"s_work_han_thu_59_215","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「料，量也，音聊。」","sentenceOrder":215},
  {"id":"s_work_han_thu_59_216","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　鄭氏曰：「說，奄人也，漢使送公主妻匈奴，說不肯行，強之，因以漢事告匈奴也。」師古曰：「中行，姓。說，名也。行音胡剛反。說讀曰悅。中行說事具在匈奴傳。」","sentenceOrder":216},
  {"id":"s_work_han_thu_59_217","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　師古曰：「聽天子之命。」","sentenceOrder":217},
  {"id":"s_work_han_thu_59_218","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　師古曰：「信讀曰伸。」","sentenceOrder":218},
  {"id":"s_work_han_thu_59_219","chapterId":"ch_work_han_thu_59","textTraditional":"今民賣僮者，〔一〕為之繡衣絲履偏諸緣，〔二〕內之閑中，〔三〕是古天子后服，所以廟而不晏者也，〔四〕而庶人得以衣婢妾。白縠之表，薄紈之裏，緁以偏諸，〔五〕美者黼繡，〔六〕是古天子之服，今富人大賈嘉會召客者以被牆。〔七〕古者以奉一帝一后而節適，〔八〕今庶人屋壁得為帝服，倡優下賤得為后飾，然而天下不屈者，殆未有也。〔九〕且帝之身自衣皁綈，〔一０〕而富民牆屋被文繡；天子之后以緣其領，庶人{薛女}妾緣其履：〔一一〕此臣所謂舛也。夫百人作之不能衣一人，〔一二〕欲天下亡寒，胡可得也？一人耕之，十人聚而食之，欲天下亡飢，不可得也。飢寒切於民之肌膚，欲其亡為姦邪，不可得也。國已屈矣，〔一三〕盜賊直須時耳，〔一四〕然而獻計者曰「毋動」，〔一五〕為大耳。〔一六〕夫俗至大不敬也，至亡等也，〔一七〕至冒上也，〔一八〕進計者猶曰「毋為」，可為長太息者此也。","sentenceOrder":219},
  {"id":"s_work_han_thu_59_220","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　如淳曰：「僮謂隸妾也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_59_221","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　服虔曰：「如牙條以作履緣。」師古曰：「偏諸，若今之織成以為要襻及褾領者也。古謂之車馬裠，其上為乘車及騎從之象也。」","sentenceOrder":221},
  {"id":"s_work_han_thu_59_222","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　服虔曰：「閑，賣奴婢闌。」","sentenceOrder":222},
  {"id":"s_work_han_thu_59_223","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「入廟則服之，宴處則不著，蓋貴之也。」","sentenceOrder":223},
  {"id":"s_work_han_thu_59_224","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　晉灼曰：「以偏諸緁著衣也。」師古曰：「緁音妾，謂以偏諸緶著之也。緶音步千反。」","sentenceOrder":224},
  {"id":"s_work_han_thu_59_225","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　師古曰：「黼者，織為斧形。繡者，刺為眾文。」","sentenceOrder":225},
  {"id":"s_work_han_thu_59_226","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　師古曰：「被音皮義反。」","sentenceOrder":226},
  {"id":"s_work_han_thu_59_227","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　師古曰：「得其節而合宜。」","sentenceOrder":227},
  {"id":"s_work_han_thu_59_228","chapterId":"ch_work_han_thu_59","textTraditional":"〔九〕　師古曰：「屈謂財力盡也，音其勿反。」","sentenceOrder":228},
  {"id":"s_work_han_thu_59_229","chapterId":"ch_work_han_thu_59","textTraditional":"〔一０〕師古曰：「綈，厚繒也，音徒奚反。」","sentenceOrder":229},
  {"id":"s_work_han_thu_59_230","chapterId":"ch_work_han_thu_59","textTraditional":"〔一一〕師古曰：「{薛女}，庶賤者。」","sentenceOrder":230},
  {"id":"s_work_han_thu_59_231","chapterId":"ch_work_han_thu_59","textTraditional":"〔一二〕師古曰：「衣音於既反。」","sentenceOrder":231},
  {"id":"s_work_han_thu_59_232","chapterId":"ch_work_han_thu_59","textTraditional":"〔一三〕　師古曰：「屈音其勿反。」","sentenceOrder":232},
  {"id":"s_work_han_thu_59_233","chapterId":"ch_work_han_thu_59","textTraditional":"〔一四〕　師古曰：「言待時而發。」","sentenceOrder":233},
  {"id":"s_work_han_thu_59_234","chapterId":"ch_work_han_thu_59","textTraditional":"〔一五〕　師古曰：「言天下安，不可動搖。」","sentenceOrder":234},
  {"id":"s_work_han_thu_59_235","chapterId":"ch_work_han_thu_59","textTraditional":"〔一六〕　如淳曰：「好為大語者。」","sentenceOrder":235},
  {"id":"s_work_han_thu_59_236","chapterId":"ch_work_han_thu_59","textTraditional":"〔一七〕　師古曰：「無尊卑之差。」","sentenceOrder":236},
  {"id":"s_work_han_thu_59_237","chapterId":"ch_work_han_thu_59","textTraditional":"〔一八〕　師古曰：「冒，犯也。」","sentenceOrder":237},
  {"id":"s_work_han_thu_59_238","chapterId":"ch_work_han_thu_59","textTraditional":"商君遺禮義，棄仁恩，〔一〕并心於進取，行之二歲，秦俗日敗。故秦人家富子壯則出分，家貧子壯則出贅。〔二〕借父耰鉏，慮有德色；〔三〕母取箕箒，立而誶語。〔四〕抱哺其子，與公併倨；〔五〕婦姑不相說，則反脣而相稽。〔六〕其慈子耆利，不同禽獸者亡幾耳。〔七〕然并心而赴時，猶曰蹶六國，兼天下。〔八〕功成求得矣，〔九〕終不知反廉愧之節，仁義之厚。〔一０〕信并兼之法，遂進取之業，〔一一〕天下大敗；眾掩寡，智欺愚，勇威怯，壯陵衰，其亂至矣。是以大賢起之，威震海內，德從天下。〔一二〕曩之為秦者，今轉而為漢矣。然其遺風餘俗，猶尚未改。今世以侈靡相競，而上亡制度，棄禮誼，捐廉恥，日甚，可謂月異而歲不同矣。逐利不耳，慮非顧行也，〔一三〕今其甚者殺父兄矣。盜者剟寢戶之簾，〔一四〕搴兩廟之器，〔一五〕白晝大都之中剽吏而奪之金。〔一六〕矯偽者出幾十萬石粟，〔一七〕賦六百餘萬錢，乘傳而行郡國〔一八〕，此其亡行義之（先）〔尤〕至者也。而大臣特以簿書不報，期會之間，以為大故。〔一九〕至於俗流失，世壞敗，因恬而不知怪，〔二０〕慮不動於耳目，以為是適然耳。〔二一〕夫移風易俗，使天下回心而鄉道，類非俗吏之所能為也。〔二二〕俗吏之所務，在於刀筆筐篋，〔二三〕而不知大（禮）〔體〕。陛下又不自憂，竊為陛下惜之。","sentenceOrder":238},
  {"id":"s_work_han_thu_59_239","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「謂商鞅。」","sentenceOrder":239},
  {"id":"s_work_han_thu_59_240","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　應劭曰：「出作贅婿也。」師古曰：「謂之贅婿者，言其不當出在妻家，亦猶人身體之有肬贅，非應所有也。一說，贅，質也，家貧無有聘財，以身為質也。贅音之銳反。分音扶問反。」","sentenceOrder":240},
  {"id":"s_work_han_thu_59_241","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「耰，摩田器也，言以耰及鉏借與其父，而容色自矜為恩德也。耰音憂。」","sentenceOrder":241},
  {"id":"s_work_han_thu_59_242","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　服虔曰：「誶猶罵也。」張晏曰：「誶，責讓也。」師古曰：「張說是也。誶音碎。」","sentenceOrder":242},
  {"id":"s_work_han_thu_59_243","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　師古曰：「哺，飤也。言婦抱子而哺之，乃與其舅併倨，無禮之甚也。哺音步。併音步鼎反。」","sentenceOrder":243},
  {"id":"s_work_han_thu_59_244","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　應劭曰：「稽，計也，相與計校也。」師古曰：「說音悅。稽音工奚反。」","sentenceOrder":244},
  {"id":"s_work_han_thu_59_245","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　師古曰：「唯有慈愛其子而貪嗜財利，小異於禽獸也。無幾，言不多也。幾音居豈反。」","sentenceOrder":245},
  {"id":"s_work_han_thu_59_246","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　蘇林曰：「蹶音厥。」師古曰：「蹶謂拔而取之。」","sentenceOrder":246},
  {"id":"s_work_han_thu_59_247","chapterId":"ch_work_han_thu_59","textTraditional":"〔九〕　師古曰：「求得，所求者得也。」","sentenceOrder":247},
  {"id":"s_work_han_thu_59_248","chapterId":"ch_work_han_thu_59","textTraditional":"〔一０〕師古曰：「反，還也。」","sentenceOrder":248},
  {"id":"s_work_han_thu_59_249","chapterId":"ch_work_han_thu_59","textTraditional":"〔一二〕師古曰：「信讀曰伸，一曰信任。」","sentenceOrder":249},
  {"id":"s_work_han_thu_59_250","chapterId":"ch_work_han_thu_59","textTraditional":"〔一三〕師古曰：「大賢謂高祖也。德從天下，天下從其德。」","sentenceOrder":250},
  {"id":"s_work_han_thu_59_251","chapterId":"ch_work_han_thu_59","textTraditional":"〔一三〕師古曰：「言其所追赴，唯計利與不耳。念慮之中，非顧行之善惡也。」","sentenceOrder":251},
  {"id":"s_work_han_thu_59_252","chapterId":"ch_work_han_thu_59","textTraditional":"〔一四〕師古曰：「剟謂割取之也。室有東西箱曰廟，無東西箱曰寢，蓋謂陵上之寢。剟音輟。」","sentenceOrder":252},
  {"id":"s_work_han_thu_59_253","chapterId":"ch_work_han_thu_59","textTraditional":"〔一五〕如淳曰：「搴，取也。兩廟，高祖、惠帝廟也。」師古曰：「搴，拔也，音騫，又音蹇。」","sentenceOrder":253},
  {"id":"s_work_han_thu_59_254","chapterId":"ch_work_han_thu_59","textTraditional":"〔一六〕師古曰：「白晝，晝日也。言白者，謂不陰晦也。剽，劫也，音頻妙反。」","sentenceOrder":254},
  {"id":"s_work_han_thu_59_255","chapterId":"ch_work_han_thu_59","textTraditional":"〔一七〕服虔曰：「吏矯偽徵發，盈出十萬石粟。」師古曰：「服說非也。幾，近也。言詐為文書，以出倉粟近十萬石耳。非謂徵發於下也。幾音鉅依反。」","sentenceOrder":255},
  {"id":"s_work_han_thu_59_256","chapterId":"ch_work_han_thu_59","textTraditional":"〔一八〕如淳曰：「此言富者出錢穀，得高爵，或乃為使者，乘傳車循行郡國，以為榮也。」師古曰：「如說亦非也。此又言矯偽之人詐為詔令，妄作賦斂，其數甚多，又詐乘傳而行郡國也。行音下更反。」","sentenceOrder":256},
  {"id":"s_work_han_thu_59_257","chapterId":"ch_work_han_thu_59","textTraditional":"〔一九〕師古曰：「特，徒也。言公卿大臣特以簿書期會為急，不知正風俗、厲行義也。」","sentenceOrder":257},
  {"id":"s_work_han_thu_59_258","chapterId":"ch_work_han_thu_59","textTraditional":"〔二０〕師古曰：「恬，安也，音徒兼反。」","sentenceOrder":258},
  {"id":"s_work_han_thu_59_259","chapterId":"ch_work_han_thu_59","textTraditional":"〔二一〕師古曰：「適，當也，謂事理當然。」","sentenceOrder":259},
  {"id":"s_work_han_thu_59_260","chapterId":"ch_work_han_thu_59","textTraditional":"〔二二〕師古曰：「鄉讀曰嚮。」","sentenceOrder":260},
  {"id":"s_work_han_thu_59_261","chapterId":"ch_work_han_thu_59","textTraditional":"〔二三〕師古曰：「刀所以削書札。筐篋所以盛書。」","sentenceOrder":261},
  {"id":"s_work_han_thu_59_262","chapterId":"ch_work_han_thu_59","textTraditional":"夫立君臣，等上下，使父子有禮，六親有紀，〔一〕此非天之所為，人之所設也。夫人之所設，不為不立，不植則僵，不修則壞。〔二〕筦子曰：〔三〕「禮義廉恥，是謂四維；四維不張，國乃滅亡。」使筦子愚人也則可，筦子而少知治體，則是豈可不為寒心哉！〔四〕秦滅四維而不張，故君臣乖亂，六親殃戮，姦人並起，萬民離叛，凡十三歲，〔而〕社稷為虛。〔五〕今四維猶未備也，故姦人幾幸，而眾心疑惑。〔六〕豈如今定經制，〔七〕令君君臣臣，〔八〕上下有差，父子六親各得其宜，姦人亡所幾幸，而群臣眾信，上不疑惑！〔九〕此業壹定，世世常安，而後有所持循矣。〔一０〕若夫經制不定，是猶度江河亡維楫，〔一一〕中流而遇風波，船必覆矣〔一二〕。可為長太息者此也。","sentenceOrder":262},
  {"id":"s_work_han_thu_59_263","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「紀，（禮）〔理〕也。」","sentenceOrder":263},
  {"id":"s_work_han_thu_59_264","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「植，建也。僵，偃也，音疆。」","sentenceOrder":264},
  {"id":"s_work_han_thu_59_265","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「筦與管同。管子，管仲也。」","sentenceOrder":265},
  {"id":"s_work_han_thu_59_266","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「若以管子為愚人，其言不實，則無禮義廉恥可也。若以管子為微識治體，則當寒心而憂之。」","sentenceOrder":266},
  {"id":"s_work_han_thu_59_267","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　師古曰：「虛讀曰墟，謂丘墟。」","sentenceOrder":267},
  {"id":"s_work_han_thu_59_268","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　師古曰：「幾讀曰冀。次下亦同。」","sentenceOrder":268},
  {"id":"s_work_han_thu_59_269","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　師古曰：「經，常也。」","sentenceOrder":269},
  {"id":"s_work_han_thu_59_270","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　師古曰：「君為君德，臣為臣道。」","sentenceOrder":270},
  {"id":"s_work_han_thu_59_271","chapterId":"ch_work_han_thu_59","textTraditional":"〔九〕　師古曰：「眾信謂共為忠信也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_59_272","chapterId":"ch_work_han_thu_59","textTraditional":"〔一０〕師古曰：「執持而順行之。」","sentenceOrder":272},
  {"id":"s_work_han_thu_59_273","chapterId":"ch_work_han_thu_59","textTraditional":"〔一二〕師古曰：「維所以繫船，楫所以刺船也。詩曰『紼縭維之』。楫音集，又音接。」","sentenceOrder":273},
  {"id":"s_work_han_thu_59_274","chapterId":"ch_work_han_thu_59","textTraditional":"〔一三〕師古曰：「覆音芳目反。」","sentenceOrder":274},
  {"id":"s_work_han_thu_59_275","chapterId":"ch_work_han_thu_59","textTraditional":"夏為天子，十有餘世，而殷受之。殷為天子，二十餘世，而周受之。周為天子，三十餘世，而秦受之。秦為天子，二世而亡。人性不甚相遠也，〔一〕何三代之君有道之長，而秦無道之暴也？其故可知也。古之王者，太子乃生，固舉以禮，〔二〕使士負之，有司齊肅端冕，〔三〕見之南郊，見于天也。〔四〕過闕則下，過廟則趨，孝子之道也。故自為赤子而教固已行矣。〔五〕昔者成王幼在繈抱之中，召公為太保，周公為太傅，太公為太師。保，保其身體；傅，傅之德（意）〔義〕；師，道之教訓：〔六〕此三公之職也。於是為置三少，皆上大夫也，曰少保、少傅、少師，是與太子宴者也。〔七〕故乃孩提有識，三公、三少固明孝仁禮義以道習之，〔八〕逐去邪人，不使見惡行。於是皆選天下之端士〔九〕孝悌博聞有道術者以衛翼之，〔一０〕使與太子居處出入。故太子乃生而見正事，聞正言，行正道，左右前後皆正人也。夫習與正人居之，不能毋正，猶生長於齊不能不齊言也；習與不正人居之，不能毋不正，猶生長於楚之地不能不楚言也。故擇其所耆，必先受業，乃得嘗之；〔一一〕擇其所樂，必先有習，乃得為之。孔子曰：「少成若天性，習貫如自然。」〔一二〕及太子少長，知妃色，〔一三〕則入于學。學者，所學之官也。〔一四〕學禮曰：「帝入東學，上親而貴仁，則親疏有序而恩相及矣；帝入南學，上齒而貴信，則長幼有差而民不誣矣；帝入西學，上賢而貴德，則聖智在位而功不遺矣；帝入北學，上貴而尊爵，則貴賤有等而下不隃矣；〔一五〕帝入太學，承師問道，退習而考於太傅，太傅罰其不則而匡其不及，〔一六〕則德智長而治道得矣。此五學者既成於上，則百姓黎民化輯於下矣。」〔一七〕及太子既冠成人，免於保傅之嚴，則有記過之史，〔一八〕徹膳之宰，〔一九〕進善之旌，〔二０〕誹謗之木，〔二一〕敢諫之鼓。〔二二〕瞽史誦詩，工誦箴諫，〔二三〕大夫進謀，士傳民語。習與智長，故切而不媿；〔二四〕化與心成，故中道若性。三代之禮：春朝朝日，秋暮夕月，所以明有敬也；〔二五〕春秋入學，坐國老，執醬而親餽之，〔二六〕所以明有孝也；行以鸞和，〔二七〕步中采齊，〔二八〕趣中肆夏，〔二九〕所以明有度也；其於禽獸，見其生不食其死，聞其聲不食其肉，故遠庖廚，所以長恩，且明有仁也。〔三０〕","sentenceOrder":275},
  {"id":"s_work_han_thu_59_276","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「遠音于萬反。」","sentenceOrder":276},
  {"id":"s_work_han_thu_59_277","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「乃，始也。」","sentenceOrder":277},
  {"id":"s_work_han_thu_59_278","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「齊讀曰齋。」","sentenceOrder":278},
  {"id":"s_work_han_thu_59_279","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「見音胡電反。」","sentenceOrder":279},
  {"id":"s_work_han_thu_59_280","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　師古曰：「赤子，言其新生未有眉髮，其色赤。」","sentenceOrder":280},
  {"id":"s_work_han_thu_59_281","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　師古曰：「保，安也。傅，輔也。道讀曰導。其下亦同。」","sentenceOrder":281},
  {"id":"s_work_han_thu_59_282","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　師古曰：「宴謂安居。」","sentenceOrder":282},
  {"id":"s_work_han_thu_59_283","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　師古曰：「孩，小兒也。提謂提撕之。」","sentenceOrder":283},
  {"id":"s_work_han_thu_59_284","chapterId":"ch_work_han_thu_59","textTraditional":"〔九〕　師古曰：「端，正也，直也。」","sentenceOrder":284},
  {"id":"s_work_han_thu_59_285","chapterId":"ch_work_han_thu_59","textTraditional":"〔一０〕師古曰：「悌音徒繼反。」","sentenceOrder":285},
  {"id":"s_work_han_thu_59_286","chapterId":"ch_work_han_thu_59","textTraditional":"〔一一〕師古曰：「耆讀曰嗜。」","sentenceOrder":286},
  {"id":"s_work_han_thu_59_287","chapterId":"ch_work_han_thu_59","textTraditional":"〔一二〕師古曰：「貫亦習也，音工宦反。」","sentenceOrder":287},
  {"id":"s_work_han_thu_59_288","chapterId":"ch_work_han_thu_59","textTraditional":"〔一三〕師古曰：「妃色，妃匹之色。」","sentenceOrder":288},
  {"id":"s_work_han_thu_59_289","chapterId":"ch_work_han_thu_59","textTraditional":"〔一四〕師古曰：「官謂官舍。」","sentenceOrder":289},
  {"id":"s_work_han_thu_59_290","chapterId":"ch_work_han_thu_59","textTraditional":"〔一五〕師古曰：「隃與踰同，謂越制。」","sentenceOrder":290},
  {"id":"s_work_han_thu_59_291","chapterId":"ch_work_han_thu_59","textTraditional":"〔一六〕師古曰：「則，法也。匡，正也。」","sentenceOrder":291},
  {"id":"s_work_han_thu_59_292","chapterId":"ch_work_han_thu_59","textTraditional":"〔一七〕師古曰：「輯與集同。輯，和也。」","sentenceOrder":292},
  {"id":"s_work_han_thu_59_293","chapterId":"ch_work_han_thu_59","textTraditional":"〔一八〕師古曰：「有過則記。」","sentenceOrder":293},
  {"id":"s_work_han_thu_59_294","chapterId":"ch_work_han_thu_59","textTraditional":"〔一九〕師古曰：「有闕則諫。」","sentenceOrder":294},
  {"id":"s_work_han_thu_59_295","chapterId":"ch_work_han_thu_59","textTraditional":"〔二０〕師古曰：「進善言者，立於旌下。」","sentenceOrder":295},
  {"id":"s_work_han_thu_59_296","chapterId":"ch_work_han_thu_59","textTraditional":"〔二一〕師古曰：「譏惡事者，書之於木。」","sentenceOrder":296},
  {"id":"s_work_han_thu_59_297","chapterId":"ch_work_han_thu_59","textTraditional":"〔二二〕師古曰：「欲顯諫者則擊鼓。」","sentenceOrder":297},
  {"id":"s_work_han_thu_59_298","chapterId":"ch_work_han_thu_59","textTraditional":"〔二三〕師古曰：「瞽，無目者也。工，習樂者也。」","sentenceOrder":298},
  {"id":"s_work_han_thu_59_299","chapterId":"ch_work_han_thu_59","textTraditional":"〔二四〕師古曰：「每被切磋，故無大過可恥媿之事。」","sentenceOrder":299},
  {"id":"s_work_han_thu_59_300","chapterId":"ch_work_han_thu_59","textTraditional":"〔二五〕師古曰：「朝日以朝，夕月以暮，皆迎其初出也。下朝音直遙反。」","sentenceOrder":300},
  {"id":"s_work_han_thu_59_301","chapterId":"ch_work_han_thu_59","textTraditional":"〔二六〕師古曰：「餽字與饋同。」","sentenceOrder":301},
  {"id":"s_work_han_thu_59_302","chapterId":"ch_work_han_thu_59","textTraditional":"〔二七〕師古曰：「鸞和，車上鈴也，解在禮樂志。」","sentenceOrder":302},
  {"id":"s_work_han_thu_59_303","chapterId":"ch_work_han_thu_59","textTraditional":"〔二八〕師古曰：「樂詩名也。字或作薺，又作茨，並音（律）〔才〕私反。」","sentenceOrder":303},
  {"id":"s_work_han_thu_59_304","chapterId":"ch_work_han_thu_59","textTraditional":"〔二九〕師古曰：「亦樂詩名。趣讀曰趨。趨，疾步也。凡此中者，謂與其節相應也，並音竹仲反。」","sentenceOrder":304},
  {"id":"s_work_han_thu_59_305","chapterId":"ch_work_han_thu_59","textTraditional":"〔三０〕師古曰：「遠音于萬反。長音竹兩反。」","sentenceOrder":305},
  {"id":"s_work_han_thu_59_306","chapterId":"ch_work_han_thu_59","textTraditional":"夫三代之所以長久者，以其輔翼太子有此具也。及秦而不然。其俗固非貴辭讓也，所上者告訐也；〔一〕固非貴禮義也，所上者刑罰也。使趙高傅胡亥而教之獄，所習者非斬劓人，則夷人之三族也。故胡亥今日即位而明日射人，忠諫者謂之誹謗，深計者謂之妖言，其視殺人若艾草菅然。〔二〕豈惟胡亥之性惡哉？彼其所以道之者非其理故也。〔三〕","sentenceOrder":306},
  {"id":"s_work_han_thu_59_307","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「訐謂面相斥罪也，音居謁反。」","sentenceOrder":307},
  {"id":"s_work_han_thu_59_308","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「艾讀曰刈。菅，茅也，音姦。」","sentenceOrder":308},
  {"id":"s_work_han_thu_59_309","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「道讀曰導。」","sentenceOrder":309},
  {"id":"s_work_han_thu_59_310","chapterId":"ch_work_han_thu_59","textTraditional":"鄙諺曰：「不習為吏，視已成事。」又曰：「前車覆，後車誡。」夫三代之所以長久者，其已事可知也；〔一〕然而不能從者，是不法聖智也。〔二〕秦世之所以亟絕者，其轍跡可見也；〔三〕然而不避，是後車又將覆也。夫存亡之變，治亂之機，其要在是矣。天下之命，縣於太子；太子之善，在於早諭教與選左右。〔四〕夫心未濫而先諭教，則化易成也；開於道術智誼之指，則教之力也。若其服習積貫，則左右而已。〔五〕夫胡、粵之人，生而同聲，耆欲不異，〔六〕及其長而成俗，累數譯而不能相通，行者〔有〕雖死而不相為者，〔七〕則教習然也。臣故曰選左右早諭教最急。夫教得而左右正，則太子正矣，太子正而天下定矣。書曰：「一人有慶，兆民賴之。」〔八〕此時務也。","sentenceOrder":310},
  {"id":"s_work_han_thu_59_311","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「已事，已往之事。」","sentenceOrder":311},
  {"id":"s_work_han_thu_59_312","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「法謂則而效之。」","sentenceOrder":312},
  {"id":"s_work_han_thu_59_313","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「亟，急也，音居力反。車跡曰轍。」","sentenceOrder":313},
  {"id":"s_work_han_thu_59_314","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「諭，曉告也。與猶及也。」","sentenceOrder":314},
  {"id":"s_work_han_thu_59_315","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　師古曰：「貫音工宦反。」","sentenceOrder":315},
  {"id":"s_work_han_thu_59_316","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　師古曰：「耆讀曰嗜。」","sentenceOrder":316},
  {"id":"s_work_han_thu_59_317","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　蘇林曰：「言其人之行，不能易事相為處。」","sentenceOrder":317},
  {"id":"s_work_han_thu_59_318","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　師古曰：「周書呂刑之辭也。一人，天子也。言天子有善，則兆庶獲其利。」","sentenceOrder":318},
  {"id":"s_work_han_thu_59_319","chapterId":"ch_work_han_thu_59","textTraditional":"凡人之智，能見已然，不能見將然。〔一〕夫禮者禁於將然之前，而法者禁於已然之後，是故法之所用易見，而禮之所為生難知也。若夫慶賞以勸善，刑罰以懲惡，先王執此之政，堅如金石，行此之令，信如四時，據此之公，無私如天地耳，豈顧不用哉？〔二〕然而曰禮云禮云者，貴絕惡於未萌，而起教於微眇，〔三〕使民日遷善遠罪而不自知也。〔四〕孔子曰：「聽訟，吾猶人也，必也使毋訟乎！」〔五〕為人主計者，莫如先審取舍；〔六〕取舍之極定於內，而安危之萌應於外矣。〔七〕安者非一日而安也，危者非一日而危也，皆以積漸然，不可不察也。人主之所積，在其取舍。以禮義治之者，積禮義；以刑罰治之者，積刑罰。刑罰積而民怨背，禮義積而民和親。故世主欲民之善同，而所以使民善者或異。或道之以德教，或〈區夂〉之以法令。〔八〕道之以德教者，德教洽而民氣樂；〈區夂〉之以法令者，法令極而民風哀。哀樂之感，禍福之應也。秦王之欲尊宗廟而安子孫，與湯武同，然而湯武廣大其德行，六七百歲而弗失，秦王治天下，十餘歲則大敗。此亡它故矣，湯武之定取舍審而秦王之定取舍不審矣。夫天下，大器也。今人之置器，置諸安處則安，置諸危處則危。天下之情與器亡以異，在天子之所置之。湯武置天下於仁義禮樂，而德澤洽，禽獸草木廣裕，〔九〕德被蠻貊四夷，累子孫數十世，此天下所共聞也。秦王置天下於法令刑罰，德澤亡一有，而怨毒盈於世，下憎惡之如仇讎，禍幾及身，子孫誅絕，〔一０〕此天下之所共見也。是非其明效大驗邪！人之言曰：「聽言之道，必以其事觀之，則言者莫敢妄言。」今或言禮誼之不如法令，教化之不如刑罰，人主胡不引殷、周、秦事以觀之也？〔一一〕","sentenceOrder":319},
  {"id":"s_work_han_thu_59_320","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「將然，謂欲有其事。」","sentenceOrder":320},
  {"id":"s_work_han_thu_59_321","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「顧猶反也。」","sentenceOrder":321},
  {"id":"s_work_han_thu_59_322","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「眇，細小也。」","sentenceOrder":322},
  {"id":"s_work_han_thu_59_323","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「見善則遷，畏罪而離。」","sentenceOrder":323},
  {"id":"s_work_han_thu_59_324","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　師古曰：「論語載孔子之言也。言使吾聽訟，與眾人齊等，然能先以德義化之，使其無訟。」","sentenceOrder":324},
  {"id":"s_work_han_thu_59_325","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　師古曰：「取謂所擇用也。舍謂所棄置也。」","sentenceOrder":325},
  {"id":"s_work_han_thu_59_326","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　師古曰：「極，中也。萌，始生也。」","sentenceOrder":326},
  {"id":"s_work_han_thu_59_327","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　師古曰：「道讀曰導。〈區夂〉與驅同。下皆類此。」","sentenceOrder":327},
  {"id":"s_work_han_thu_59_328","chapterId":"ch_work_han_thu_59","textTraditional":"〔九〕　師古曰：「裕，饒也。」","sentenceOrder":328},
  {"id":"s_work_han_thu_59_329","chapterId":"ch_work_han_thu_59","textTraditional":"〔一０〕師古曰：「幾音鉅依反。」","sentenceOrder":329},
  {"id":"s_work_han_thu_59_330","chapterId":"ch_work_han_thu_59","textTraditional":"〔一一〕師古曰：「胡，何也。」","sentenceOrder":330},
  {"id":"s_work_han_thu_59_331","chapterId":"ch_work_han_thu_59","textTraditional":"人主之尊譬如堂，群臣如陛，眾庶如地。故陛九級上，廉遠地，則堂高；〔一〕陛亡級，廉近地，則堂卑。高者難攀，卑者易陵，〔二〕理勢然也。故古者聖王制為等列，內有公卿大夫士，外有公侯伯子男，然後有官師小吏，〔三〕延及庶人，等級分明，而天子加焉，故其尊不可及也。里諺曰：「欲投鼠而忌器。」此善諭也。鼠近於器，尚憚不投，恐傷其器，況於貴臣之近主乎！〔四〕廉恥節禮以治君子，故有賜死而亡戮辱。是以黥劓之罪不及大夫，以其離主上不遠也。禮不敢齒君之路馬，蹴其芻者有罰；〔五〕見君之几杖則起，遭君之乘車則下，入正門則趨；君之寵臣雖或有過，刑戮之罪不加其身者，尊君之故也。此所以為主上豫遠不敬也，〔六〕所以體貌大臣而厲其節也。〔七〕今自王侯三公之貴，皆天子之所改容而禮之也，古天子之所謂伯父、伯舅也，〔八〕而令與眾庶同黥劓髡刖笞傌棄巿之法，〔九〕然則堂不亡陛虖？被戮辱者不泰迫虖？〔一０〕廉恥不行，大臣無乃握重權，大官而有徒隸亡恥之心虖？夫望夷之事，二世見當以重法者，〔一一〕投鼠而不忌器之習也。","sentenceOrder":331},
  {"id":"s_work_han_thu_59_332","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「級，等也。廉，側隅也。」","sentenceOrder":332},
  {"id":"s_work_han_thu_59_333","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「陵，乘也。」","sentenceOrder":333},
  {"id":"s_work_han_thu_59_334","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「官師，一官之長。」","sentenceOrder":334},
  {"id":"s_work_han_thu_59_335","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「近音其靳反。」","sentenceOrder":335},
  {"id":"s_work_han_thu_59_336","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　師古曰：「齒謂審其齒歲也。芻，所食之草也。蹵音千六反。」","sentenceOrder":336},
  {"id":"s_work_han_thu_59_337","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　師古曰：「遠，離也。」","sentenceOrder":337},
  {"id":"s_work_han_thu_59_338","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　師古曰：「體貌，謂加禮容而敬之。」","sentenceOrder":338},
  {"id":"s_work_han_thu_59_339","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　師古曰：「天子呼諸侯長者，同姓則曰伯父，異姓則曰伯舅。伯，長也。」","sentenceOrder":339},
  {"id":"s_work_han_thu_59_340","chapterId":"ch_work_han_thu_59","textTraditional":"〔九〕　蘇林曰：「傌音罵。」","sentenceOrder":340},
  {"id":"s_work_han_thu_59_341","chapterId":"ch_work_han_thu_59","textTraditional":"〔一０〕師古曰：「迫，迫天子也。」","sentenceOrder":341},
  {"id":"s_work_han_thu_59_342","chapterId":"ch_work_han_thu_59","textTraditional":"〔一一〕如淳曰：「決罪曰當。閻樂殺二世於望夷宮，本由秦制無忌上之風也。」","sentenceOrder":342},
  {"id":"s_work_han_thu_59_343","chapterId":"ch_work_han_thu_59","textTraditional":"臣聞之，履雖鮮不加於枕，冠雖敝不以苴履。〔一〕夫嘗已在貴寵之位，天子改容而體貌之矣，吏民嘗俯伏以敬畏之矣，今而有過，帝令廢之可也，退之可也，賜之死可也，滅之可也；若夫束縛之，係緤之，〔二〕輸之司寇，編之徒官，〔三〕司寇小吏詈罵而榜笞之，〔四〕殆非所以令眾庶見也。夫卑賤者習知尊貴者之一旦吾亦乃可以加此也，〔五〕非所以習天下也，非尊尊貴貴之化也。夫天子之所嘗敬，眾庶之所嘗寵，死而死耳，賤人安宜得如此而頓辱之哉！","sentenceOrder":343},
  {"id":"s_work_han_thu_59_344","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「苴者，履中之藉也，音子余反。」","sentenceOrder":344},
  {"id":"s_work_han_thu_59_345","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「緤謂以長繩係之也。緤音先列反。」","sentenceOrder":345},
  {"id":"s_work_han_thu_59_346","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「司寇，主刑罰之官。編，次列也。」","sentenceOrder":346},
  {"id":"s_work_han_thu_59_347","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「榜音彭。」","sentenceOrder":347},
  {"id":"s_work_han_thu_59_348","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　蘇林曰：「知其有一旦之刑。」","sentenceOrder":348},
  {"id":"s_work_han_thu_59_349","chapterId":"ch_work_han_thu_59","textTraditional":"豫讓事中行之君，智伯伐而滅之，〔一〕移事智伯。及趙滅智伯，豫讓面吞炭，〔二〕必報襄子，五起而不中。人問豫子，豫子曰：「中行眾人畜我，我故眾人事之；智伯國士遇我，我故國士報之。」故此一豫讓也，反君事讎，行若狗彘，已而抗節致忠，行出虖列士，人主使然也。故主上遇其大臣如遇犬馬，彼將犬馬自為也；如遇官徒，彼將官徒自為也。頑頓亡恥〔三〕〈余阝〉詬亡節，〔四〕廉恥不立，且不自好，〔五〕苟若而可，〔六〕故見利則逝，見便則奪〔七〕。主上有敗，則因而挻之矣；〔八〕主上有患，則吾苟免而已，立而觀之耳；有便吾身者，則欺賣而利之耳。人主將何便於此？〔九〕群下至眾，而主上至少也，所託財器職業者粹於群下也。〔一０〕俱亡恥，俱苟妄，則主上最病。故古者禮不及庶人，刑不至大夫，所以厲寵臣之節也。古者大臣有坐不廉而廢者，不謂不廉，曰「簠簋不飾」；〔一一〕坐汙穢淫亂男女亡別者，不曰汙穢，曰「帷薄不修」；坐罷軟不勝任者，不謂罷軟，曰「下官不職」。〔一二〕故貴大臣定有其罪矣，猶未斥然正以謼之也，〔一三〕尚遷就而為之諱也。故其在大譴大何之域者，〔一四〕聞譴何則白冠氂纓，〔一五〕盤水加劍，造請室而請罪耳，〔一六〕上不執縛係引而行也。其有中罪者，聞命而自弛，〔一七〕上不使人頸盭而加也。〔一八〕其有大罪者，聞命則北面再拜，跪而自裁，〔一九〕上不使捽抑而刑之也，〔二０〕曰：「子大夫自有過耳！〔二一〕吾遇子有禮矣。」遇之有禮，故群臣自憙；〔二二〕嬰以廉恥，故人矜節行。〔二三〕上設廉恥禮義以遇其臣，而臣不以節行報其上者，則非人類也。故化成俗定，則為人臣者主耳忘身，〔二四〕國耳忘家，公耳忘私，利不苟就，害不苟去，唯義所在。上之化也，故父兄之臣誠死宗廟，法度之臣誠死社稷，輔翼之臣誠死君上，守圄扞敵之臣誠死城郭封疆。故曰聖人有金城者，比物此志也。〔二五〕彼且為我死，故吾得與之俱生；彼且為我亡，故吾得與之俱存；夫將為我危，故吾得與之皆安。〔二六〕顧行而忘利，守節而仗義，故可以託不御之權，可以寄六尺之孤。〔二七〕此厲廉恥行禮誼之所致也，主上何喪焉！〔二八〕此之不為，而顧彼之久行，〔二九〕故曰可為長太息者此也。〔三０〕","sentenceOrder":349},
  {"id":"s_work_han_thu_59_350","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「行音胡剛反。」","sentenceOrder":350},
  {"id":"s_work_han_thu_59_351","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　鄭氏曰：「釁，漆面以易貌。吞炭，以變聲也。」師古曰：「釁，熏也，以毒藥熏之。」","sentenceOrder":351},
  {"id":"s_work_han_thu_59_352","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「頓讀曰鈍。」","sentenceOrder":352},
  {"id":"s_work_han_thu_59_353","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「〈余阝〉詬，謂無志分也。〈余阝〉音胡結反。詬音后。」","sentenceOrder":353},
  {"id":"s_work_han_thu_59_354","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　師古曰：「自好猶言自喜也。好音呼倒反。」","sentenceOrder":354},
  {"id":"s_work_han_thu_59_355","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　師古曰：「若猶然。」","sentenceOrder":355},
  {"id":"s_work_han_thu_59_356","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　師古曰：「逝，往也。」","sentenceOrder":356},
  {"id":"s_work_han_thu_59_357","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　服虔曰：「音挻起。」師古曰：「挻音式延反。」","sentenceOrder":357},
  {"id":"s_work_han_thu_59_358","chapterId":"ch_work_han_thu_59","textTraditional":"〔九〕　師古曰：「此於人主為不便也。便音頻面反。」","sentenceOrder":358},
  {"id":"s_work_han_thu_59_359","chapterId":"ch_work_han_thu_59","textTraditional":"〔一０〕蘇林曰：「粹，純也。言其勢悉在群下。」","sentenceOrder":359},
  {"id":"s_work_han_thu_59_360","chapterId":"ch_work_han_thu_59","textTraditional":"〔一一〕師古曰：「簠簋，所以盛飯也。方曰簠，圓曰簋。簠音甫，又音扶。簋音軌。」","sentenceOrder":360},
  {"id":"s_work_han_thu_59_361","chapterId":"ch_work_han_thu_59","textTraditional":"〔一二〕師古曰：「罷，廢於事也。軟，弱也。罷讀曰疲。軟音人兗反。」","sentenceOrder":361},
  {"id":"s_work_han_thu_59_362","chapterId":"ch_work_han_thu_59","textTraditional":"〔一三〕師古曰：「謼，古呼字。」","sentenceOrder":362},
  {"id":"s_work_han_thu_59_363","chapterId":"ch_work_han_thu_59","textTraditional":"〔一四〕師古曰：「譴，責也。何，問也。域，界局也。」","sentenceOrder":363},
  {"id":"s_work_han_thu_59_364","chapterId":"ch_work_han_thu_59","textTraditional":"〔一五〕鄭氏曰：「以毛作纓。白冠，喪服也。」","sentenceOrder":364},
  {"id":"s_work_han_thu_59_365","chapterId":"ch_work_han_thu_59","textTraditional":"〔一六〕應劭曰：「請室，請罪之室。」蘇林曰：「音絜清。胡公漢官車駕出有請室令在前先驅，此官有別獄也。」如淳曰：「水性平，若己有正罪，君以平法治之也。加劍，當以自刎也。或曰，殺牲者以盤水取頸血，故示若此也。」師古曰：「應、如二說皆是。」","sentenceOrder":365},
  {"id":"s_work_han_thu_59_366","chapterId":"ch_work_han_thu_59","textTraditional":"〔一七〕師古曰：「中罪，非大非小也。弛，廢也，自廢而死。弛音式爾反。」","sentenceOrder":366},
  {"id":"s_work_han_thu_59_367","chapterId":"ch_work_han_thu_59","textTraditional":"〔一八〕蘇林曰：「不戾其頸而親加刀鋸也。」師古曰：「盭，古戾字，音廬結反。」","sentenceOrder":367},
  {"id":"s_work_han_thu_59_368","chapterId":"ch_work_han_thu_59","textTraditional":"〔一九〕師古曰：「裁，謂自刑殺也。」","sentenceOrder":368},
  {"id":"s_work_han_thu_59_369","chapterId":"ch_work_han_thu_59","textTraditional":"〔二０〕師古曰：「捽，持頭髮也。抑謂按之也。捽音才兀反。」","sentenceOrder":369},
  {"id":"s_work_han_thu_59_370","chapterId":"ch_work_han_thu_59","textTraditional":"〔二一〕服虔曰：「子者，男子美號。」","sentenceOrder":370},
  {"id":"s_work_han_thu_59_371","chapterId":"ch_work_han_thu_59","textTraditional":"〔二二〕師古曰：「憙讀曰喜，音許吏反。憙，好也，好為志氣也。」","sentenceOrder":371},
  {"id":"s_work_han_thu_59_372","chapterId":"ch_work_han_thu_59","textTraditional":"〔二三〕師古曰：「嬰，加也。矜，尚也。」","sentenceOrder":372},
  {"id":"s_work_han_thu_59_373","chapterId":"ch_work_han_thu_59","textTraditional":"〔二四〕孟康曰：「唯為主耳，不念其身。」","sentenceOrder":373},
  {"id":"s_work_han_thu_59_374","chapterId":"ch_work_han_thu_59","textTraditional":"〔二五〕李奇曰：「志，記也。凡此上陳廉恥之事，皆古記也。」如淳曰：「比謂比方也。使忠臣以死社稷之志，比於金城也。」師古曰：「二家之說皆非也。此言聖人厲此節行以御群下，則人皆懷德，戮力同心，國家安固不可毀，狀若金城也。尋其下文，義可曉矣。」","sentenceOrder":374},
  {"id":"s_work_han_thu_59_375","chapterId":"ch_work_han_thu_59","textTraditional":"〔二六〕師古曰：「夫，夫人也，亦猶彼人耳。夫音扶。」","sentenceOrder":375},
  {"id":"s_work_han_thu_59_376","chapterId":"ch_work_han_thu_59","textTraditional":"〔二七〕應劭曰：「言念主忘身，憂國忘家，如此，可託權柄，不須復制御也。六尺之孤，未能自立者也。」","sentenceOrder":376},
  {"id":"s_work_han_thu_59_377","chapterId":"ch_work_han_thu_59","textTraditional":"〔二八〕師古曰：「如此則於主上無所失。」","sentenceOrder":377},
  {"id":"s_work_han_thu_59_378","chapterId":"ch_work_han_thu_59","textTraditional":"〔二九〕服虔曰：「彼謂亡國也。」師古曰：「顧，反也。久謂久行之也。言何不為投鼠忌器之法，而反久行無陛級之事。」","sentenceOrder":378},
  {"id":"s_work_han_thu_59_379","chapterId":"ch_work_han_thu_59","textTraditional":"〔三０〕師古曰：「誼上疏言可為長太息者六，今此至三而止，蓋史家直取其要切者耳。故下贊云掇其切於世事者著於傳。」","sentenceOrder":379},
  {"id":"s_work_han_thu_59_380","chapterId":"ch_work_han_thu_59","textTraditional":"是時丞相絳侯周勃免就國，人有告勃謀反，逮繫長安獄治，卒亡事，復爵邑，故賈誼以此譏上。上深納其言，養臣下有節。是後大臣有罪，皆自殺，不受刑。至武帝時，稍復入獄，自甯成始。","sentenceOrder":380},
  {"id":"s_work_han_thu_59_381","chapterId":"ch_work_han_thu_59","textTraditional":"初，文帝以代王入即位，後分代為兩國，立皇子武為代王，參為太原王，小子勝則梁王矣。後又徙代王武為淮陽王，而太原王參為代王，盡得故地。居數年，梁王勝死，亡子。誼復上疏曰：","sentenceOrder":381},
  {"id":"s_work_han_thu_59_382","chapterId":"ch_work_han_thu_59","textTraditional":"陛下即不定制，如今之勢，不過一傳再傳，〔一〕諸侯猶且人恣而不制，豪植而大強，〔二〕漢法不得行矣。陛下所以為蕃扞及皇太子之所恃者，唯淮陽、代二國耳。〔三〕代北邊匈奴，與強敵為鄰。能自完則足矣。而淮陽之比大諸侯，厪如黑子之著面，〔四〕適足以餌大國耳，〔五〕不足以有所禁禦。方今制在陛下，制國而令子適足以為餌，豈可謂工哉！人主之行異布衣。布衣者，飾小行，競小廉，以自託於鄉黨，人主唯天下安社稷固不耳。高皇帝瓜分天下以王功臣，反者如蝟毛而起，〔六〕以為不可，故蔪去不義諸侯而虛其國。〔七〕擇良日，立諸子雒陽上東門之外，〔八〕畢以為王，〔九〕而天下安。故大人者，不牽小行，以成大功。","sentenceOrder":382},
  {"id":"s_work_han_thu_59_383","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　服虔曰：「一二傳世也。」","sentenceOrder":383},
  {"id":"s_work_han_thu_59_384","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「植，立也。」","sentenceOrder":384},
  {"id":"s_work_han_thu_59_385","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「蕃（翰）〔扞〕得宜，則嗣王安固，故云皇太子之所恃也。」","sentenceOrder":385},
  {"id":"s_work_han_thu_59_386","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「黑子，今所謂黶子也。著音直略反。」","sentenceOrder":386},
  {"id":"s_work_han_thu_59_387","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　師古曰：「餌謂為其所吞食。」","sentenceOrder":387},
  {"id":"s_work_han_thu_59_388","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　師古曰：「蝟，蟲名也，其毛為刺，音謂。」","sentenceOrder":388},
  {"id":"s_work_han_thu_59_389","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　如淳曰：「不義諸侯，彭越、黥布等。」師古曰：「蔪讀與芟同，謂芟刈之。」","sentenceOrder":389},
  {"id":"s_work_han_thu_59_390","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　師古曰：「諸侯國皆在關東，故於東門外立之也。東面最北出門曰上東門。」","sentenceOrder":390},
  {"id":"s_work_han_thu_59_391","chapterId":"ch_work_han_thu_59","textTraditional":"〔九〕　師古曰：「畢猶盡。」","sentenceOrder":391},
  {"id":"s_work_han_thu_59_392","chapterId":"ch_work_han_thu_59","textTraditional":"今淮南地遠者或數千里，越兩諸侯，〔一〕而縣屬於漢〔二〕。其吏民繇役往來長安者，自悉而補，中道衣敝，〔三〕錢用諸費稱此，〔四〕其苦屬漢而欲得王至甚，逋逃而歸諸侯者已不少矣。其勢不可久。臣之愚計，願舉淮南地以益淮陽，而為梁王立後，割淮陽北邊二三列城〔五〕與東郡以益梁；不可者，可徙代王而都睢陽。梁起於新郪以北著之河，〔六〕淮陽包陳以南揵之江，〔七〕則大諸侯之有異心者，破膽而不敢謀。梁足以扞齊、趙，淮陽足以禁吳、楚，陛下高枕，終亡山東之憂矣，此二世之利也。〔八〕當今恬然，適遇諸侯之皆少，〔九〕數歲之後，陛下且見之矣。夫秦日夜苦心勞力以除六國之禍，今陛下力制天下，頤指如意，〔一０〕高拱以成六國之禍，難以言智。苟身亡事，畜亂宿禍，孰視而不定，〔一一〕萬年之後，傳之老母弱子，將使不寧，不可謂仁。臣聞聖主言問其臣而不自造事，〔一二〕故使人臣得畢其愚忠。唯陛下財幸！〔一三〕","sentenceOrder":392},
  {"id":"s_work_han_thu_59_393","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「越，過也。兩諸侯，梁及淮陽。」","sentenceOrder":393},
  {"id":"s_work_han_thu_59_394","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「為縣而屬漢。」","sentenceOrder":394},
  {"id":"s_work_han_thu_59_395","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　應劭曰：「自悉其家資財，補縫作衣。」師古曰：「悉，盡也。」","sentenceOrder":395},
  {"id":"s_work_han_thu_59_396","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「稱音尺孕反。」","sentenceOrder":396},
  {"id":"s_work_han_thu_59_397","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　孟康曰：「列城，縣。」","sentenceOrder":397},
  {"id":"s_work_han_thu_59_398","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　師古曰：「新郪，潁川縣也。郪音千移反。著音直略反。」","sentenceOrder":398},
  {"id":"s_work_han_thu_59_399","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　晉灼曰：「包，取也。」如淳曰：「揵謂立封界也。或曰，揵，接也。」師古曰：「揵音鉅偃反。」","sentenceOrder":399},
  {"id":"s_work_han_thu_59_400","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　如淳曰：「從誼言可二世安耳。」師古曰：「言帝身及太子嗣位之時。」","sentenceOrder":400},
  {"id":"s_work_han_thu_59_401","chapterId":"ch_work_han_thu_59","textTraditional":"〔九〕　師古曰：「恬，安也。少謂年少。」","sentenceOrder":401},
  {"id":"s_work_han_thu_59_402","chapterId":"ch_work_han_thu_59","textTraditional":"〔一０〕如淳曰：「但動頤指麾，則所欲皆如意。」","sentenceOrder":402},
  {"id":"s_work_han_thu_59_403","chapterId":"ch_work_han_thu_59","textTraditional":"〔一一〕師古曰：「畜讀曰蓄。」","sentenceOrder":403},
  {"id":"s_work_han_thu_59_404","chapterId":"ch_work_han_thu_59","textTraditional":"〔一二〕師古曰：「欲發言則問其臣。」","sentenceOrder":404},
  {"id":"s_work_han_thu_59_405","chapterId":"ch_work_han_thu_59","textTraditional":"〔一三〕師古曰：「財與裁同。裁擇而幸從其言。」","sentenceOrder":405},
  {"id":"s_work_han_thu_59_406","chapterId":"ch_work_han_thu_59","textTraditional":"文帝於是從誼計，乃徙淮陽王武為梁王，北界泰山，西至高陽，得大縣四十餘城；徙城陽王喜為淮陽王，撫其民。","sentenceOrder":406},
  {"id":"s_work_han_thu_59_407","chapterId":"ch_work_han_thu_59","textTraditional":"時又封淮南厲王四子皆為列侯。誼知上必將復王之也，上疏諫曰：「竊恐陛下接王淮南諸子，〔一〕曾不與如臣者孰計之也。淮南王之悖逆亡道，天下孰不知其罪？〔二〕陛下幸而赦遷之，自疾而死，天下孰以王死之不當？今奉尊罪人之子，適足以負謗於天下耳。〔三〕此人少壯，豈能忘其父哉？〔四〕白公勝所為父報仇者，大父與伯父、叔父也。〔五〕白公為亂，非欲取國代主也，發憤快志，剡手以衝仇人之匈，〔六〕固為俱靡而已。〔七〕淮南雖小，黥布嘗用之矣，漢存特幸耳。〔八〕夫擅仇人足以危漢之資，於策不便。〔九〕雖割而為四，四子一心也。予之眾，積之財，此非有子胥、白公報於廣都之中，即疑有剸諸、荊軻起於兩柱之間，〔一０〕所謂假賊兵為虎翼者也。〔一一〕願陛下少留計！」","sentenceOrder":407},
  {"id":"s_work_han_thu_59_408","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　孟康曰：「接音挾，挾持欲王淮南諸子也。」臣瓚曰：「謂以恩接待而王之。」師古曰：「二說皆非也。謂接今時當即王之，言不久也。接猶續也，猶今人言續復也。」","sentenceOrder":408},
  {"id":"s_work_han_thu_59_409","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「悖，惑也，音布內反。」","sentenceOrder":409},
  {"id":"s_work_han_thu_59_410","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「言若尊王其子，則是厲王無罪，漢枉殺之。」","sentenceOrder":410},
  {"id":"s_work_han_thu_59_411","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「少壯，猶言稍長大。」","sentenceOrder":411},
  {"id":"s_work_han_thu_59_412","chapterId":"ch_work_han_thu_59","textTraditional":"〔五〕　師古曰：「白公，楚平王之孫，太子建之子也。大父即祖，謂平王也。伯父、叔父，平王（之）〔諸〕子也。事見春秋傳。」","sentenceOrder":412},
  {"id":"s_work_han_thu_59_413","chapterId":"ch_work_han_thu_59","textTraditional":"〔六〕　師古曰：「剡，利也，音弋（再）〔冉〕反。」","sentenceOrder":413},
  {"id":"s_work_han_thu_59_414","chapterId":"ch_work_han_thu_59","textTraditional":"〔七〕　師古曰：「言與仇人俱滅斃也。靡，碎也，音武皮反。」","sentenceOrder":414},
  {"id":"s_work_han_thu_59_415","chapterId":"ch_work_han_thu_59","textTraditional":"〔八〕　師古曰：「言漢之勝布得存，此直天幸耳。」","sentenceOrder":415},
  {"id":"s_work_han_thu_59_416","chapterId":"ch_work_han_thu_59","textTraditional":"〔九〕　師古曰：「言假四子以資權，則當危漢。」","sentenceOrder":416},
  {"id":"s_work_han_thu_59_417","chapterId":"ch_work_han_thu_59","textTraditional":"〔一０〕師古曰：「剸諸刺吳王，荊軻刺秦皇。事見春秋傳及燕丹子也。」","sentenceOrder":417},
  {"id":"s_work_han_thu_59_418","chapterId":"ch_work_han_thu_59","textTraditional":"〔一一〕應劭曰：「周書云『無為虎傅翼，將飛入邑，擇人而食之。』」","sentenceOrder":418},
  {"id":"s_work_han_thu_59_419","chapterId":"ch_work_han_thu_59","textTraditional":"梁王勝墜馬死，〔一〕誼自傷為傅無狀，〔二〕常哭泣，後歲餘，亦死。賈生之死，年三十三矣。","sentenceOrder":419},
  {"id":"s_work_han_thu_59_420","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　李奇曰：「文三王傳言揖，此言勝，為有兩名。」","sentenceOrder":420},
  {"id":"s_work_han_thu_59_421","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「無善狀。」","sentenceOrder":421},
  {"id":"s_work_han_thu_59_422","chapterId":"ch_work_han_thu_59","textTraditional":"後四歲，齊文王薨，亡子。文帝思賈生之言，乃分齊為六國，盡立悼惠王子六人為王；又遷淮南王喜於城陽，分淮南為三國，盡立厲王三子以王之。後十年，文帝崩，景帝立，三年而吳、楚、趙與四齊王合從舉兵，西鄉京師，〔二〕梁王扞之，卒破七國。至武帝時，淮南厲王子為王者兩國亦反誅。","sentenceOrder":422},
  {"id":"s_work_han_thu_59_423","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　韋昭曰：「四齊王，膠東、膠西、菑川、濟南也。」師古曰：「從音子容反。」","sentenceOrder":423},
  {"id":"s_work_han_thu_59_424","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":424},
  {"id":"s_work_han_thu_59_425","chapterId":"ch_work_han_thu_59","textTraditional":"孝武初立，舉賈生之孫二人至郡守。賈嘉最好學，世其家。〔一〕","sentenceOrder":425},
  {"id":"s_work_han_thu_59_426","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「言繼其家業。」","sentenceOrder":426},
  {"id":"s_work_han_thu_59_427","chapterId":"ch_work_han_thu_59","textTraditional":"贊曰：劉向稱「賈誼言三代與秦治亂之意，其論甚美，通達國體，雖古之伊、管未能遠過也。〔一〕使時見用，功化必盛。為庸臣所害，甚可悼痛。」追觀孝文玄默躬行以移風俗，〔二〕誼之所陳略施行矣。及欲改定制度，以漢為土德，色上黃，數用五，及欲試屬國，施五餌三表以係單于，〔三〕其術固以疏矣。誼（以夭）〔亦天〕年早終，雖不至公卿，未為不遇也。凡所著述五十八篇，掇其切於世事者著于傳云。〔四〕","sentenceOrder":427},
  {"id":"s_work_han_thu_59_428","chapterId":"ch_work_han_thu_59","textTraditional":"〔一〕　師古曰：「伊，伊尹。管，管仲。」","sentenceOrder":428},
  {"id":"s_work_han_thu_59_429","chapterId":"ch_work_han_thu_59","textTraditional":"〔二〕　師古曰：「躬行，謂身親儉約之行也，自追觀以下，並史家之詞。」","sentenceOrder":429},
  {"id":"s_work_han_thu_59_430","chapterId":"ch_work_han_thu_59","textTraditional":"〔三〕　師古曰：「賈誼書愛人之狀，好人之技，仁道也；信為大操，常義也；愛好有實，已諾可期，十死一生，彼將必至：此三表也。賜之盛服車乘以壞其目；賜之盛食珍味以壞其口；賜之音樂婦人以壞其耳；賜之高堂邃宇府庫奴婢以壞其腹；於來降者，以上召幸之，相娛樂，親酌而手食之，以壞其心：此五餌也。」","sentenceOrder":430},
  {"id":"s_work_han_thu_59_431","chapterId":"ch_work_han_thu_59","textTraditional":"〔四〕　師古曰：「掇，拾也，音丁活反。」","sentenceOrder":431},
  {"id":"s_work_han_thu_59_432","chapterId":"ch_work_han_thu_59","textTraditional":"校勘記","sentenceOrder":432},
  {"id":"s_work_han_thu_59_433","chapterId":"ch_work_han_thu_59","textTraditional":"二二二三頁　六行　嗟（若）〔苦〕先生，　王先謙說史記、文選「若」都作「苦」，據注文亦當作「苦」。","sentenceOrder":433},
  {"id":"s_work_han_thu_59_434","chapterId":"ch_work_han_thu_59","textTraditional":"二二二四頁一七行　見細德之險（微）〔徵〕兮，宋祁說浙本「微」作徵，作「微」者非是。","sentenceOrder":434},
  {"id":"s_work_han_thu_59_435","chapterId":"ch_work_han_thu_59","textTraditional":"二二二八頁一六行　何足引持自貴（借）〔惜〕也。宋祁說姚本「貴借」作「貴惜」。按　景祐本作「貴惜」。","sentenceOrder":435},
  {"id":"s_work_han_thu_59_436","chapterId":"ch_work_han_thu_59","textTraditional":"二二二九頁　四行　權勢不（充）〔尤〕，則夸者悲。　景祐本作「尤」。史記集解引莊子亦作「尤」。","sentenceOrder":436},
  {"id":"s_work_han_thu_59_437","chapterId":"ch_work_han_thu_59","textTraditional":"二二三七頁　一行　（一）〔二〕國皆反誅。　景祐、殿本都作「二」。王先謙說作「二」是。","sentenceOrder":437},
  {"id":"s_work_han_thu_59_438","chapterId":"ch_work_han_thu_59","textTraditional":"二二四一頁　六行　病（癖）〔辟〕，不能行也。王先謙說「癖」為「辟」之誤。","sentenceOrder":438},
  {"id":"s_work_han_thu_59_439","chapterId":"ch_work_han_thu_59","textTraditional":"二二四四頁一六行　此其亡行義之（先）〔尤〕至者也。殿本作「尤」，　景祐亦作「先」。","sentenceOrder":439},
  {"id":"s_work_han_thu_59_440","chapterId":"ch_work_han_thu_59","textTraditional":"二二四五頁　三行　而不知大（禮）〔體〕。　景祐、殿本都作「體」。王先謙說作「體」是。","sentenceOrder":440},
  {"id":"s_work_han_thu_59_441","chapterId":"ch_work_han_thu_59","textTraditional":"二二四六頁一七行　凡十三歲，〔而〕社稷為虛。景祐、殿本都有「而」字。","sentenceOrder":441},
  {"id":"s_work_han_thu_59_442","chapterId":"ch_work_han_thu_59","textTraditional":"二二四七頁　五行　紀，（禮）〔理〕也。　景祐、殿本都作「理」。","sentenceOrder":442},
  {"id":"s_work_han_thu_59_443","chapterId":"ch_work_han_thu_59","textTraditional":"二二四八頁　六行　傅，傅之德（意）〔義〕；　景祐、殿本都作「義」。王先謙說作「義」是。","sentenceOrder":443},
  {"id":"s_work_han_thu_59_444","chapterId":"ch_work_han_thu_59","textTraditional":"二二五一頁　三行　並音（律）〔才〕私反。　景祐本作「才」。","sentenceOrder":444},
  {"id":"s_work_han_thu_59_445","chapterId":"ch_work_han_thu_59","textTraditional":"二二五二頁　二行　行者〔有〕雖死而不相為者，　按景祐本作「行者有」，殿本作「行有」。","sentenceOrder":445},
  {"id":"s_work_han_thu_59_446","chapterId":"ch_work_han_thu_59","textTraditional":"二六一頁　四行　蕃（翰）〔扞〕得宜，則嗣王安固，　王先謙說「翰」當為「扞」之誤。","sentenceOrder":446},
  {"id":"s_work_han_thu_59_447","chapterId":"ch_work_han_thu_59","textTraditional":"二二六四頁　一行　伯父、叔父，平王（之）〔諸〕子也。　景祐、殿本都作「諸」。","sentenceOrder":447},
  {"id":"s_work_han_thu_59_448","chapterId":"ch_work_han_thu_59","textTraditional":"二二六四頁　二行　音弋（再）〔冉〕反。　景祐、殿本都作「冉」，此誤。","sentenceOrder":448},
  {"id":"s_work_han_thu_59_449","chapterId":"ch_work_han_thu_59","textTraditional":"二二六五頁　六行　誼（以夭）〔亦天〕年早終，　景祐、殿本都作「亦天」。","sentenceOrder":449},
  {"id":"s_work_han_thu_60_1","chapterId":"ch_work_han_thu_60","textTraditional":"師古曰：「晁，古朝字，其下作朝，蓋通用耳。」","sentenceOrder":1},
  {"id":"s_work_han_thu_60_2","chapterId":"ch_work_han_thu_60","textTraditional":"爰盎字絲。其父楚人也，〔一〕故為群盜，徙安陵。〔二〕高后時，盎為呂祿舍人。孝文即位，盎兄噲任盎為郎中。〔三〕","sentenceOrder":2},
  {"id":"s_work_han_thu_60_3","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「盎音一浪反。」","sentenceOrder":3},
  {"id":"s_work_han_thu_60_4","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「群盜者，群眾相隨而為盜也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_60_5","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　（師古）〔如淳〕曰：「盎為兄所保任，故得為郎中也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_60_6","chapterId":"ch_work_han_thu_60","textTraditional":"絳侯為丞相，朝罷趨出，意得甚。〔一〕上禮之恭，常目送之。盎進曰：「丞相何如人也？」上曰：「社稷臣。」盎曰：「絳侯所謂功臣，非社稷臣。社稷臣主在與在，主亡與亡。〔二〕方呂后時，諸呂用事，擅相王，劉氏不絕如帶。〔三〕是時絳侯為太尉，本兵柄，〔四〕弗能正。呂后崩，大臣相與共誅諸呂，太尉主兵，適會其成功，所謂功臣，非社稷臣。丞相如有驕主色，陛下謙讓，〔五〕臣主失禮，竊為陛下弗取也。」後朝，上益莊，丞相益畏。〔六〕已而絳侯望盎曰：「吾與汝兄善，今兒乃毀我！」〔七〕盎遂不謝。","sentenceOrder":6},
  {"id":"s_work_han_thu_60_7","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「意甚自得也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_60_8","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　如淳曰：「人主在時，與共治在時之事；人主雖亡，其法度存，當奉行之。高祖誓非劉氏不王，而勃等聽王諸呂，是從生主之欲，不與亡者也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_60_9","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「言微細也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_60_10","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「執兵權之本。」","sentenceOrder":10},
  {"id":"s_work_han_thu_60_11","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　師古曰：「如，似也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_60_12","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　師古曰：「莊，嚴也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_60_13","chapterId":"ch_work_han_thu_60","textTraditional":"〔七〕　師古曰：「望，責怨之也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_60_14","chapterId":"ch_work_han_thu_60","textTraditional":"及絳侯就國，人上書告以為反，徵擊請室，〔一〕諸公莫敢為言，唯盎明絳侯無罪。絳侯得釋，盎頗有力。絳侯乃大與盎結交。","sentenceOrder":14},
  {"id":"s_work_han_thu_60_15","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「請室，獄也，解在賈誼傳。」","sentenceOrder":15},
  {"id":"s_work_han_thu_60_16","chapterId":"ch_work_han_thu_60","textTraditional":"淮南厲王朝，殺辟陽侯，〔一〕居處驕甚。盎諫曰：「諸侯太驕必生患，可適削地。」〔二〕上弗許。淮南王益橫。〔三〕謀反發覺，上徵淮南王，遷之蜀，檻車傳送。盎時為中郎將，諫曰：「陛下素驕之，弗稍禁，以至此，今又暴摧折之。淮南王為人剛，有如遇霜露行道死，陛下竟為以天下大弗能容，有殺弟名，柰何？」上不聽，遂行之。","sentenceOrder":16},
  {"id":"s_work_han_thu_60_17","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「自國入朝而殺之。」","sentenceOrder":17},
  {"id":"s_work_han_thu_60_18","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「適讀曰謫。」","sentenceOrder":18},
  {"id":"s_work_han_thu_60_19","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「橫音胡孟反。」","sentenceOrder":19},
  {"id":"s_work_han_thu_60_20","chapterId":"ch_work_han_thu_60","textTraditional":"淮南王至雍，病死，聞，〔一〕上輟食，哭甚哀。〔二〕盎入，頓首請罪。〔三〕上曰：「以不用公言至此。」盎曰：「上自寬，此往事，豈可悔哉！且陛下有高世行三，此不足以毀名。」上曰：「吾高世三者何事？」盎曰：「陛下居代時，太后嘗病，三年，陛下不交睫解衣，〔四〕湯藥非陛下口所嘗弗進。夫曾參以布衣猶難之，今陛下親以王者修之，過曾參遠矣。諸呂用事，大臣顓制，〔五〕然陛下從代乘六乘傳，馳不測淵，〔六〕雖賁育之勇不及陛下。〔七〕陛下至代邸，西鄉讓天子者三，南鄉讓天子者再。〔八〕夫許由一讓〔九〕，陛下五以天下讓，過許由四矣。且陛下遷淮南王，欲以苦其志，使改過，有司宿衛不謹，故病死。」於是上乃解，盎繇此名重朝廷。〔一０〕","sentenceOrder":20},
  {"id":"s_work_han_thu_60_21","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「雍是扶風雍縣也。聞，聞於天子也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_60_22","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「輟，止也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_60_23","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「自責以不強諫也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_60_24","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「睫，目旁毛也。交睫，謂睡寐也。睫音接。」","sentenceOrder":24},
  {"id":"s_work_han_thu_60_25","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　師古曰：「顓與專同。」","sentenceOrder":25},
  {"id":"s_work_han_thu_60_26","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　鄭氏曰：「大臣亂，乘傳而赴之，故曰不測淵。」","sentenceOrder":26},
  {"id":"s_work_han_thu_60_27","chapterId":"ch_work_han_thu_60","textTraditional":"〔七〕　孟康曰：「孟賁、夏育，皆古勇士也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_60_28","chapterId":"ch_work_han_thu_60","textTraditional":"〔八〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":28},
  {"id":"s_work_han_thu_60_29","chapterId":"ch_work_han_thu_60","textTraditional":"〔九〕　師古曰：「許由，古高士也。堯讓天下於由，由不受也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_60_30","chapterId":"ch_work_han_thu_60","textTraditional":"〔一０〕師古曰：「繇讀與由同。」","sentenceOrder":30},
  {"id":"s_work_han_thu_60_31","chapterId":"ch_work_han_thu_60","textTraditional":"盎常引大體慷慨。宦者趙談以數幸，常害盎，盎患之。盎兄子種為常侍騎，諫盎曰：「君眾辱之，後雖惡君，上不復信。」〔一〕於是上朝東宮，趙談驂乘，盎伏車前曰：「臣聞天子所與共六尺輿者，皆天下豪英。今漢雖乏人，陛下獨柰何與刀鋸之餘共載！」於是上笑，下趙談。談泣下車。","sentenceOrder":31},
  {"id":"s_work_han_thu_60_32","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕師古曰：「惡謂譖毀之，言其過惡。」","sentenceOrder":32},
  {"id":"s_work_han_thu_60_33","chapterId":"ch_work_han_thu_60","textTraditional":"上從霸陵上，欲西馳下峻阪，盎〈扌監〉轡。〔一〕上曰：「將軍怯邪？」盎言曰：「臣聞千金之子不垂堂，〔二〕百金之子不騎衡，〔三〕聖主不乘危，不徼幸。今陛下騁六飛，〔四〕馳不測山，有如馬驚車敗，陛下縱自輕，柰高廟、太后何？」上乃止。","sentenceOrder":33},
  {"id":"s_work_han_thu_60_34","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「〈扌監〉與攬同。」","sentenceOrder":34},
  {"id":"s_work_han_thu_60_35","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「言富人之子則自愛也。垂堂，謂坐堂外邊，恐墜墮也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_60_36","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　如淳曰：「騎，倚也。衡，樓殿邊欄楯也。」師古曰：「騎謂跨之耳，非倚也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_60_37","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　如淳曰：「六馬之疾若飛也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_60_38","chapterId":"ch_work_han_thu_60","textTraditional":"上幸上林，皇后、慎夫人從。其在禁中，常同坐。〔一〕及坐，郎署長布席，盎引卻慎夫人坐。〔二〕慎夫人怒，不肯坐。上亦怒，起。盎因前說曰：「臣聞尊卑有序則上下和，今陛下既以立后，慎夫人乃妾，妾主豈可以同坐哉！且陛下幸之，則厚賜之。陛下所以為慎夫人，適所以禍之也。獨不見『人豕』乎？」〔三〕於是上乃說〔四〕，入語慎夫人。慎夫人賜盎金五十斤。","sentenceOrder":38},
  {"id":"s_work_han_thu_60_39","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「同坐，謂所坐之處高下齊同，無差等也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_60_40","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　蘇林曰：「郎署，上林中直衛之署也。」如淳曰：「盎時為中郎將，天子幸署，豫設供帳待之，故得卻慎夫人坐也。」師古曰：「卻謂退而卑之也。坐音材臥反。」","sentenceOrder":40},
  {"id":"s_work_han_thu_60_41","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　張晏曰：「戚夫人也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_60_42","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「說讀曰悅。」","sentenceOrder":42},
  {"id":"s_work_han_thu_60_43","chapterId":"ch_work_han_thu_60","textTraditional":"然盎亦以數直諫，不得久居中。調為隴西都尉，〔一〕仁愛士卒，士卒皆爭為死。遷齊相，徙為吳相。辭行，種謂盎曰：「吳王驕日久，國多姦，今絲欲刻治，〔三〕彼不上書告君，則利劍刺君矣。南方卑溼，絲能日飲，亡何，說王毋反而已。〔三〕如此幸得脫。」盎用種之計，吳王厚遇盎。","sentenceOrder":43},
  {"id":"s_work_han_thu_60_44","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「調，選也，音徒釣反。」","sentenceOrder":44},
  {"id":"s_work_han_thu_60_45","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　如淳曰：「種稱叔父字曰絲。」","sentenceOrder":45},
  {"id":"s_work_han_thu_60_46","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「無何，言更無餘事。」","sentenceOrder":46},
  {"id":"s_work_han_thu_60_47","chapterId":"ch_work_han_thu_60","textTraditional":"盎告歸，道逢丞相申屠嘉，下車拜謁，丞相從車上謝。盎還，媿其吏，〔一〕乃之丞相舍上謁，〔二〕求見丞相。丞相良久乃見。因跪曰：「願請間。」〔三〕丞相曰：「使君所言公事，之曹與長史掾議之，吾且奏之；則私，吾不受私語。」盎即起說曰：「君為相，自度孰與陳平、絳侯？」〔四〕丞相曰：「不如。」盎曰：「善，君自謂弗如。夫陳平、絳侯輔翼高帝，定天下，為將相，而誅諸呂，存劉氏；君乃為材官蹶張，遷為隊帥，〔五〕積功至淮陽守，非有奇計攻城野戰之功。且陛下從代來，每朝，郎官者上書疏，未嘗不止輦受。其言不可用，置之；言可采，未嘗不稱善。何也？欲以致天下賢英士大夫，日聞所不聞，以益聖。〔六〕而君自閉箝天下之口，〔七〕而日益愚。夫以聖主責愚相，君受禍不久矣。」丞相乃再拜曰：「嘉鄙人，乃不知，將軍幸教。」引與入坐，為上客。","sentenceOrder":47},
  {"id":"s_work_han_thu_60_48","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「慚不見禮也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_60_49","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「上謁，若今通名也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_60_50","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「欲因間隙，私有所白也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_60_51","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「度，計量也。與猶如也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_60_52","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　如淳曰：「隊帥，軍中小官。」師古曰：「帥音所類反。」","sentenceOrder":52},
  {"id":"s_work_han_thu_60_53","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　師古曰：「日日得聞異言也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_60_54","chapterId":"ch_work_han_thu_60","textTraditional":"〔七〕　師古曰：「箝，籋也，音其炎反。」","sentenceOrder":54},
  {"id":"s_work_han_thu_60_55","chapterId":"ch_work_han_thu_60","textTraditional":"盎素不好晁錯，錯所居坐，盎輒避；盎所居坐，錯亦避：兩人未嘗同堂語。及孝景即位，晁錯為御史大夫，使吏案盎受吳王財物，抵罪，詔赦以為庶人。吳楚反聞，〔一〕錯謂丞史曰：〔二〕「爰盎多受吳王金錢，專為蔽匿，言不反。今果反，欲請治盎，宜知其計謀。」丞史曰：「事未發，治之有絕。〔三〕今兵西向，治之何益！且盎不宜有謀。」〔四〕錯猶與未決。〔五〕人有告盎，盎恐，夜見竇嬰，為言吳所以反，願（致）〔至〕前，口對狀。〔六〕嬰入言，上乃召盎。盎入見，竟言吳所以反，獨急斬錯以謝吳，吳可罷。上拜盎為泰常，竇嬰為大將軍。兩人素相善。是時，諸陵長安中賢大夫爭附兩人，車騎者日數百乘。","sentenceOrder":55},
  {"id":"s_work_han_thu_60_56","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「聞，聞於天子。」","sentenceOrder":56},
  {"id":"s_work_han_thu_60_57","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　如淳曰：「百官表御史大夫有兩丞。丞史，丞及史也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_60_58","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　如淳曰：「事未發之時，治之乃有所絕也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_60_59","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　如淳曰：「盎大臣，不宜有姦謀。」","sentenceOrder":59},
  {"id":"s_work_han_thu_60_60","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　師古曰：「與讀曰豫。」","sentenceOrder":60},
  {"id":"s_work_han_thu_60_61","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　師古曰：「至天子之前也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_60_62","chapterId":"ch_work_han_thu_60","textTraditional":"及晁錯已誅，盎以泰常使吳。吳王欲使將，不肯。欲殺之，使一都尉以五百人圍守盎軍中。初，盎為吳相時，從史盜私盎侍兒。〔一〕盎知之，弗泄，遇之如故。人有告從史，「君知女與侍者通」，乃亡去。盎驅自追之，〔二〕遂以侍者賜之，復為從史。及盎使吳見守，從史適在守盎校為司馬，〔三〕乃悉以其裝齎買二石醇醪，〔四〕會天寒，士卒飢渴，飲醉西南陬卒，卒皆臥。〔五〕司馬夜引盎起，曰：「君可以去矣，吳王期旦日斬君。」盎弗信，曰：「何為者？」司馬曰：「臣故為君從史盜侍兒者也。」盎乃驚，謝曰：「公幸有親，〔六〕吾不足絫公。」〔七〕司馬曰：「君弟去，〔八〕臣亦且亡，辟吾親，〔九〕君何患！」乃以刀決帳，道從醉卒直出。〔一０〕司馬與分背。〔一一〕盎解節旄懷之，〔一二〕屐步行七十里，〔一三〕明，見梁騎，馳去，遂歸報。〔一四〕","sentenceOrder":62},
  {"id":"s_work_han_thu_60_63","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　文穎曰：「婢也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_60_64","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「驅馳而追，言疾速。」","sentenceOrder":64},
  {"id":"s_work_han_thu_60_65","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「為校中之司馬，所領士卒，正當守盎。」","sentenceOrder":65},
  {"id":"s_work_han_thu_60_66","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「裝齎，謂所齎衣物自隨者也。醇者不雜，言其醲也。醪，汁滓合之酒也，音牢。」","sentenceOrder":66},
  {"id":"s_work_han_thu_60_67","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　師古曰：「陬，隅也。飲音於禁反。陬音子侯反，又音鄒。」","sentenceOrder":67},
  {"id":"s_work_han_thu_60_68","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　文穎曰：「言汝有親老。」","sentenceOrder":68},
  {"id":"s_work_han_thu_60_69","chapterId":"ch_work_han_thu_60","textTraditional":"〔七〕　師古曰：「絫，古累字也，音力瑞反。」","sentenceOrder":69},
  {"id":"s_work_han_thu_60_70","chapterId":"ch_work_han_thu_60","textTraditional":"〔八〕　師古曰：「弟，但也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_60_71","chapterId":"ch_work_han_thu_60","textTraditional":"〔九〕　如淳曰：「藏匿吾親，不使遇害也。」晉灼曰：「辟音避。」","sentenceOrder":71},
  {"id":"s_work_han_thu_60_72","chapterId":"ch_work_han_thu_60","textTraditional":"〔一０〕師古曰：「於醉卒之處決帳而開，令通道得亡也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_60_73","chapterId":"ch_work_han_thu_60","textTraditional":"〔一一〕師古曰：「一時各去也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_60_74","chapterId":"ch_work_han_thu_60","textTraditional":"〔一二〕如淳曰：「不欲令人見。」","sentenceOrder":74},
  {"id":"s_work_han_thu_60_75","chapterId":"ch_work_han_thu_60","textTraditional":"〔一三〕如淳曰：「著屐步行而逃亡。」","sentenceOrder":75},
  {"id":"s_work_han_thu_60_76","chapterId":"ch_work_han_thu_60","textTraditional":"〔一四〕文穎曰：「梁騎將擊吳楚者也。」師古曰：「遇梁軍之騎，遂因得脫，歸報天子。」","sentenceOrder":76},
  {"id":"s_work_han_thu_60_77","chapterId":"ch_work_han_thu_60","textTraditional":"吳楚已破，上更以元王子平陸侯禮為楚王，以盎為楚相。嘗上書，不用。盎病免家居，與閭里浮湛，相隨行鬥雞走狗。〔一〕雒陽劇孟嘗過盎，盎善待之。安陵富人有謂盎曰：「吾聞劇孟博徒，〔二〕將軍何自通之？」盎曰：「劇孟雖博徒，然母死，客送喪車千餘乘，此亦有過人者。且緩急人所有。〔三〕夫一旦叩門，不以親為解〔四〕，不以在亡為辭，〔五〕天下所望者，獨季心、劇孟。〔六〕今公陽從數騎，〔七〕一旦有緩急，寧足恃乎！」遂罵富人，弗與通。諸公聞之，皆多盎。〔八〕","sentenceOrder":77},
  {"id":"s_work_han_thu_60_78","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「湛讀曰沉。」","sentenceOrder":78},
  {"id":"s_work_han_thu_60_79","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　服虔曰：「博戲之徒也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_60_80","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「凡人在生，不能無緩急之事。」","sentenceOrder":80},
  {"id":"s_work_han_thu_60_81","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　張晏曰：「不語云親不聽也。」臣瓚曰：「凡人之於赴難濟厄，多以有父母為解，而孟兼行之。」師古曰：「瓚說是也。解者，若今言分疏矣。」","sentenceOrder":81},
  {"id":"s_work_han_thu_60_82","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　師古曰：「或實在家，而辭云不在。」","sentenceOrder":82},
  {"id":"s_work_han_thu_60_83","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　文穎曰：「心，季布弟也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_60_84","chapterId":"ch_work_han_thu_60","textTraditional":"〔七〕　鄧展曰：「陽，外也。」晉灼曰：「陽猶常也。」師古曰：「鄧說是也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_60_85","chapterId":"ch_work_han_thu_60","textTraditional":"〔八〕　師古曰：「多猶重。」","sentenceOrder":85},
  {"id":"s_work_han_thu_60_86","chapterId":"ch_work_han_thu_60","textTraditional":"盎雖居家，景帝時時使人問籌策。梁王欲求為嗣，盎進說，其後語塞。〔一〕梁王以此怨盎，使人刺盎。刺者至關中，問盎，稱之皆不容口。〔二〕乃見盎曰：「臣受梁王金刺君，君長者，不忍刺君。然後刺者十餘曹，〔三〕備之！」盎心不樂，家多怪，乃之棓生所問占。〔四〕還，梁刺客後曹果遮刺殺盎安陵郭門外。","sentenceOrder":86},
  {"id":"s_work_han_thu_60_87","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「塞，不行也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_60_88","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「稱美其德，口不能容也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_60_89","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　如淳曰：「曹，輩也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_60_90","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　蘇林曰：「音桮。」文穎曰：「音陪，秦時賢士善術者也。」師古曰：「蘇音文說是。」","sentenceOrder":90},
  {"id":"s_work_han_thu_60_91","chapterId":"ch_work_han_thu_60","textTraditional":"晁錯，潁川人也。〔一〕學申商刑名於軹張恢生所，〔二〕與雒陽宋孟及劉帶同師。以文學為太常掌故。〔三〕","sentenceOrder":91},
  {"id":"s_work_han_thu_60_92","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　晉灼曰：「音厝置之厝。」師古曰：「據申屠嘉傳序云『責通請錯，匪躬之故』，以韻而言，晉音是也。潘岳西征賦乃讀為錯雜之錯，不可依也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_60_93","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「軹縣之儒生姓張名恢，錯從之受申商法也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_60_94","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　應劭曰：「掌故，六百石吏，主故事。」","sentenceOrder":94},
  {"id":"s_work_han_thu_60_95","chapterId":"ch_work_han_thu_60","textTraditional":"錯為人峭直刻深。〔一〕孝文時，天下亡治尚書者，獨聞齊有伏生，故秦博士，治尚書，年九十餘，老不可徵。乃詔太常，使人受之。太常遣錯受尚書伏生所，還，因上書稱說。〔二〕詔以為太子舍人，門大夫，〔三〕遷博士。又上書言：「人主所以尊顯功名揚於萬世之後者，以知術數也。〔四〕故人主知所以臨制臣下而治其眾，則群臣畏服矣；知所以聽言受事，則不欺蔽矣；知所以安利萬民，則海內必從矣；知所以忠孝事上，則臣子之行備矣：此四者，臣竊為皇太子急之。人臣之議或曰皇太子亡以知事為也，〔五〕臣之愚，誠以為不然。竊觀上世之君，不能奉其宗廟而劫殺於其臣者，皆不知術數者也。（皇太子所讀書多矣，而未深知術數者也。）皇太子所讀書多矣，而未深知術數者，不問書說也。〔六〕夫多誦而不知其說，所謂勞苦而不為功。臣竊觀皇太子材智高奇，馭射伎藝過人絕遠，然於術數未有所守者，以陛下為心也。〔七〕竊願陛下幸擇聖人之術可用今世者，以賜皇太子，因時使太子陳明於前。唯陛下裁察。」上善之，於是拜錯為太子家令。〔八〕以其辯得幸太子，太子家號曰「智囊」〔九〕。","sentenceOrder":95},
  {"id":"s_work_han_thu_60_96","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「峭字與峭同。峭謂峻陿也，音千笑反。」","sentenceOrder":96},
  {"id":"s_work_han_thu_60_97","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「稱師法而說其義。」","sentenceOrder":97},
  {"id":"s_work_han_thu_60_98","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「初為舍人，又為門大夫。」","sentenceOrder":98},
  {"id":"s_work_han_thu_60_99","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　張晏曰：「術數，刑名之書也。」臣瓚曰：「術數謂法制，治國之術也。」師古曰：「瓚說是也。公孫弘云『擅生殺之力，通壅塞之途，權輕重之數，論得失之道，使遠近情偽必見於上，謂之術。』此與錯所言同耳。」","sentenceOrder":99},
  {"id":"s_work_han_thu_60_100","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　師古曰：「言何用知事。」","sentenceOrder":100},
  {"id":"s_work_han_thu_60_101","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　師古曰：「說謂所說之義也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_60_102","chapterId":"ch_work_han_thu_60","textTraditional":"〔七〕　張晏曰：「若伯魚須仲尼教，乃讀詩書也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_60_103","chapterId":"ch_work_han_thu_60","textTraditional":"〔八〕　臣瓚曰：「茂陵中書太子家令秩八百石。」","sentenceOrder":103},
  {"id":"s_work_han_thu_60_104","chapterId":"ch_work_han_thu_60","textTraditional":"〔九〕　師古曰：「言其一身所有皆是智算，若囊橐之盛物也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_60_105","chapterId":"ch_work_han_thu_60","textTraditional":"是時匈奴彊，數寇邊，上發兵以禦之。錯上言兵事，曰：","sentenceOrder":105},
  {"id":"s_work_han_thu_60_106","chapterId":"ch_work_han_thu_60","textTraditional":"臣聞漢興以來，胡虜數入邊地，小入則小利，大入則大利；高后時再入隴西，攻城屠邑，敺略畜產；〔一〕其後復入隴西，殺吏卒，大寇盜。竊聞戰勝之威，民氣百倍；〔二〕敗兵之卒，沒世不復。〔三〕自高后以來，隴西三困於匈奴矣，民氣破傷，亡有勝意。今茲隴西之吏，賴社稷之神靈，奉陛下之明詔，和輯士卒，底厲其節，〔四〕起破傷之民以當乘勝之匈奴，用少擊眾，殺一王，敗其眾而（法曰）大有利。非隴西之民有勇怯，乃將吏之制巧拙異也。故兵法曰：「有必勝之將，無必勝之民。」繇此觀之，〔五〕安邊境，立功名，在於良將，不可不擇也。","sentenceOrder":106},
  {"id":"s_work_han_thu_60_107","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「敺與驅同。」","sentenceOrder":107},
  {"id":"s_work_han_thu_60_108","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「益奮厲也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_60_109","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「永挫折也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_60_110","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「輯與集同。底與砥同。」","sentenceOrder":110},
  {"id":"s_work_han_thu_60_111","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　師古曰：「繇讀與由同。」","sentenceOrder":111},
  {"id":"s_work_han_thu_60_112","chapterId":"ch_work_han_thu_60","textTraditional":"臣又聞用兵，臨戰合刃之急者三：〔一〕一曰得地形，二曰卒服習，三曰器用利。兵法曰：丈五之溝，漸車之水，〔二〕山林積石，經川丘阜，〔三〕屮木所在，〔四〕此步兵之地也，車騎二不當一。土山丘陵，曼衍相屬，〔五〕平原廣野，此車騎之地，步兵十不當一。平陵相遠，川谷居間，〔六〕仰高臨下，此弓弩之地也，短兵百不當一。兩陳相近，平地淺（草）〔屮〕，可前可後，此長戟之地也，劍楯三不當一。（雚）〔萑〕葦竹蕭，〔七〕屮木蒙蘢，支葉茂接，〔八〕此矛鋋之地也，〔九〕長戟二不當一。曲道相伏，險阨相薄，此劍楯之地也，弓弩三不當一。士不選練，卒不服習，起居不精，動靜不集，〔一０〕趨利弗及，避難不畢，前擊後解，與金鼓之（音）〔指〕相失，〔一一〕此不習勒卒之過也，百不當十。兵不完利，與空手同；甲不堅密，與袒裼同；〔一二〕弩不可以及遠，與短兵同；射不能中，與亡矢同；中不能入，與亡鏃同：〔一三〕此將不省兵之禍也，〔一四〕五不當一。故兵法曰：器械不利，以其卒予敵也；卒不可用，以其將予敵也；將不知兵，以其主予敵也；君不擇將，以其國予敵也。四者，（國）〔兵〕之至要也。","sentenceOrder":112},
  {"id":"s_work_han_thu_60_113","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「合刃，謂交兵。」","sentenceOrder":113},
  {"id":"s_work_han_thu_60_114","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「漸讀曰瀸，謂浸也，音子廉反。」","sentenceOrder":114},
  {"id":"s_work_han_thu_60_115","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「經川，常流之水也。大陸曰阜。」","sentenceOrder":115},
  {"id":"s_work_han_thu_60_116","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「屮，古草字。」","sentenceOrder":116},
  {"id":"s_work_han_thu_60_117","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　師古曰：「曼衍，猶聯延也。屬，續也。衍音弋戰反。屬音之欲反。」","sentenceOrder":117},
  {"id":"s_work_han_thu_60_118","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　師古曰：「遠，離也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_60_119","chapterId":"ch_work_han_thu_60","textTraditional":"〔七〕　師古曰：「（雚亂）〔萑，薍〕也。葦，葭也。蕭，蒿也。萑音完。」","sentenceOrder":119},
  {"id":"s_work_han_thu_60_120","chapterId":"ch_work_han_thu_60","textTraditional":"〔八〕　師古曰：「蒙蘢，覆蔽之貌也。蘢音來東反。」","sentenceOrder":120},
  {"id":"s_work_han_thu_60_121","chapterId":"ch_work_han_thu_60","textTraditional":"〔九〕　師古曰：「鋋，鐵把短矛也，音上延反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_60_122","chapterId":"ch_work_han_thu_60","textTraditional":"〔一０〕師古曰：「集，齊也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_60_123","chapterId":"ch_work_han_thu_60","textTraditional":"〔一一〕師古曰：「金，金鉦也。鼓所以進眾，金所以止眾也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_60_124","chapterId":"ch_work_han_thu_60","textTraditional":"〔一二〕應劭曰：「袒裼，肉袒也。」師古曰：「裼音錫。」","sentenceOrder":124},
  {"id":"s_work_han_thu_60_125","chapterId":"ch_work_han_thu_60","textTraditional":"〔一三〕師古曰：「鏃，矢鋒也，音子木反。」","sentenceOrder":125},
  {"id":"s_work_han_thu_60_126","chapterId":"ch_work_han_thu_60","textTraditional":"〔一四〕師古曰：「省，視也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_60_127","chapterId":"ch_work_han_thu_60","textTraditional":"臣又聞小大異形，彊弱異勢，險易異備。〔一〕夫卑身以事彊，小國之形也；合小以攻大，敵國之形也；〔二〕以蠻夷攻蠻夷，中國之形也。〔三〕今匈奴地形技藝與中國異。上下山阪，出入溪澗，中國之馬弗與也；〔四〕險道傾仄，且馳且射，〔五〕中國之騎弗與也；風雨罷勞，飢渴不困，〔六〕中國之人弗與也：此匈奴之長技也。若夫平原易地，輕車突騎，〔七〕則匈奴之眾易撓亂也；〔八〕勁弩長戟，射疏及遠，〔九〕則匈奴之弓弗能格也；堅甲利刃，長短相雜，遊弩往來，什伍俱前，〔一０〕則匈奴之兵弗能當也；材官騶發，矢道同的，〔一一〕則匈奴之革笥木薦弗能支也；〔一二〕下馬地鬥，劍戟相接，去就相薄，〔一三〕則匈奴之足弗能給也：〔一四〕此中國之長技也。以此觀之，匈奴之長技三，中國之長技五。陛下又興數十萬之眾，以誅數萬之匈奴，眾寡之計，以一擊十之術也。","sentenceOrder":127},
  {"id":"s_work_han_thu_60_128","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「易，平也，音弋豉反。」","sentenceOrder":128},
  {"id":"s_work_han_thu_60_129","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「彼我力均，不能相勝，則須連結外援共制之也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_60_130","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「不煩華夏之兵，使其同類自相攻擊也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_60_131","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「與猶如。」","sentenceOrder":131},
  {"id":"s_work_han_thu_60_132","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　師古曰：「仄，古側字。」","sentenceOrder":132},
  {"id":"s_work_han_thu_60_133","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　師古曰：「罷讀曰疲。」","sentenceOrder":133},
  {"id":"s_work_han_thu_60_134","chapterId":"ch_work_han_thu_60","textTraditional":"〔七〕　師古曰：「易亦平也。突騎，言其驍銳可用衝突敵人也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_60_135","chapterId":"ch_work_han_thu_60","textTraditional":"〔八〕　師古曰：「撓，攪也，音火高反，其字從手。一曰，橈，曲也，弱也，音女教反，其字從木。」","sentenceOrder":135},
  {"id":"s_work_han_thu_60_136","chapterId":"ch_work_han_thu_60","textTraditional":"〔九〕　師古曰：「疏亦闊遠也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_60_137","chapterId":"ch_work_han_thu_60","textTraditional":"〔一０〕師古曰：「五人為伍，二伍為什。」","sentenceOrder":137},
  {"id":"s_work_han_thu_60_138","chapterId":"ch_work_han_thu_60","textTraditional":"〔一一〕蘇林曰：「騶音馬驟之驟。」如淳曰：「騶，矢也。處平易之地可以矢相射也。」臣瓚曰：「材官，騎射之官也。射者騶發，其用矢者同中一的，言其工妙也。」師古曰：「騶謂矢之善者也。春秋左氏傳作菆字，其音同耳。材官，有材力者。騶發，發騶矢以射也。手工矢善，故中則同的。的謂所射之準臬也。蘇音失之矣。臬音牛列反，即謂橛也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_60_139","chapterId":"ch_work_han_thu_60","textTraditional":"〔一二〕孟康曰：「革笥，以皮作如鎧者被之。木薦，以木板作如楯。一曰，革笥若楯，木薦之以當人心也。」師古曰：「一說非也。笥音息嗣反。」","sentenceOrder":139},
  {"id":"s_work_han_thu_60_140","chapterId":"ch_work_han_thu_60","textTraditional":"〔一三〕師古曰：「薄，迫也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_60_141","chapterId":"ch_work_han_thu_60","textTraditional":"〔一四〕師古曰：「給謂相連及。」","sentenceOrder":141},
  {"id":"s_work_han_thu_60_142","chapterId":"ch_work_han_thu_60","textTraditional":"雖然，兵，凶器；戰，危事也。以大為小，以彊為弱，在俛卬之間耳。〔一〕夫以人之死爭勝，跌而不振，〔二〕則悔之亡及也。帝王之道，出於萬全。今降胡義渠蠻夷之屬來歸誼者，其眾數千，飲食長技與匈奴同，可賜之堅甲絮衣，勁弓利矢，益以邊郡之良騎。令明將能知其習俗和輯其心者，〔三〕以陛下之明約將之。即有險阻，以此當之；平地通道，則以輕車材官制之。兩軍相為表裏，各用其長技，衡加之以眾，〔四〕此萬全之術也。","sentenceOrder":142},
  {"id":"s_work_han_thu_60_143","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「言不知其術，則雖大必小，雖強必弱也。俛亦俯字。卬讀曰仰。」","sentenceOrder":143},
  {"id":"s_work_han_thu_60_144","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　服虔曰：「蹉跌不可復起也。」師古曰：「跌，足失據也。跌音徒結反。」","sentenceOrder":144},
  {"id":"s_work_han_thu_60_145","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「輯與集同也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_60_146","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　張晏曰：「衡音橫。」師古曰：「衡即橫耳，無勞借音。」","sentenceOrder":146},
  {"id":"s_work_han_thu_60_147","chapterId":"ch_work_han_thu_60","textTraditional":"傳曰：「狂夫之言，而明主擇焉。」臣錯愚陋，昧死上狂言，唯陛下財擇。〔一〕","sentenceOrder":147},
  {"id":"s_work_han_thu_60_148","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「財與裁同也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_60_149","chapterId":"ch_work_han_thu_60","textTraditional":"文帝嘉之，乃賜錯璽書寵答焉，曰：「皇帝問太子家令：上書言兵體三章，聞之。〔一〕書言『狂夫之言，而明主擇焉』。今則不然。言者不狂，而擇者不明，國之大患，故在於此。使夫不明擇於不狂，是以萬聽而萬不當也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_60_150","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　李奇曰：「三者，得地形，卒服習，器用利。」","sentenceOrder":150},
  {"id":"s_work_han_thu_60_151","chapterId":"ch_work_han_thu_60","textTraditional":"錯復言守邊備塞，勸農力本，當世急務二事，曰：","sentenceOrder":151},
  {"id":"s_work_han_thu_60_152","chapterId":"ch_work_han_thu_60","textTraditional":"臣聞秦時北攻胡貉，築塞河上，〔一〕南攻楊粵，〔二〕置戍卒焉。其起兵而攻胡、粵者，非以衛邊地而救民死也，貪戾而欲廣大也，故功未立而天下亂。且夫起兵而不知其勢，戰則為人禽，屯則卒積死。夫胡貉之地，積陰之處也，木皮三寸，冰厚六尺，〔三〕食肉而飲酪，其人密理，鳥獸毳毛，〔四〕其性能寒。〔五〕楊粵之地少陰多陽，其人疏理，鳥獸希毛，其性能暑。秦之戍卒不能其水土，戍者死於邊，輸者僨於道。〔六〕秦民見行，如往棄市，因以謫發之，名曰「謫戍」。先發吏有謫及贅婿、賈人，後以嘗有市籍者，又後以大父母、父母嘗有市籍者，後入閭，取其左。〔七〕發之不順，行者深怨，有背畔之心。凡民守戰至死而不降北者，以計為之也。〔八〕故戰勝守固則有拜爵之賞，攻城屠邑則得其財鹵以富家室，故能使其眾蒙矢石，赴湯火，〔九〕視死如生。今秦之發卒也，有萬死之害，而亡銖兩之報，死事之後不得一算之復，〔一０〕天下明知禍烈及己也。〔一一〕陳勝行戍，至於大澤，為天下先倡，〔一二〕天下從之如流水者，秦以威劫而行之之敝也。","sentenceOrder":152},
  {"id":"s_work_han_thu_60_153","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「貉音莫客反。」","sentenceOrder":153},
  {"id":"s_work_han_thu_60_154","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　張晏曰：「楊州之南越也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_60_155","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　文穎曰：「土地寒故也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_60_156","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「密理，謂其肌肉也。毳，細毛也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_60_157","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　師古曰：「能讀曰耐。此下能暑亦同。」","sentenceOrder":157},
  {"id":"s_work_han_thu_60_158","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　服虔曰：「僨，仆也。」如淳曰：「僨音奮。」","sentenceOrder":158},
  {"id":"s_work_han_thu_60_159","chapterId":"ch_work_han_thu_60","textTraditional":"〔七〕　孟康曰：「秦時復除者居閭之左，後發役不供，復役之也。或云直先發取其左也。」師古曰：「閭，里門也。居閭之左者，一切皆發之，非謂復除也。解在食貨志。」","sentenceOrder":159},
  {"id":"s_work_han_thu_60_160","chapterId":"ch_work_han_thu_60","textTraditional":"〔八〕　師古曰：「北謂敗退。」","sentenceOrder":160},
  {"id":"s_work_han_thu_60_161","chapterId":"ch_work_han_thu_60","textTraditional":"〔九〕　師古曰：「蒙，冒犯也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_60_162","chapterId":"ch_work_han_thu_60","textTraditional":"〔一０〕師古曰：「復，復除也，音方目反。」","sentenceOrder":162},
  {"id":"s_work_han_thu_60_163","chapterId":"ch_work_han_thu_60","textTraditional":"〔一一〕師古曰：「猛火曰烈，取以喻耳。」","sentenceOrder":163},
  {"id":"s_work_han_thu_60_164","chapterId":"ch_work_han_thu_60","textTraditional":"〔一二〕師古曰：「倡讀曰唱。」","sentenceOrder":164},
  {"id":"s_work_han_thu_60_165","chapterId":"ch_work_han_thu_60","textTraditional":"胡人衣食之業不著於地，〔一〕其勢易以擾亂邊竟。〔二〕何以明之？胡人食肉飲酪，衣皮毛，非有城郭田宅之歸居，如飛鳥走獸於廣野，〔三〕美草甘水則止，草盡水竭則移。以是觀之，往來轉徙，時至時去，此胡人之生業，而中國之所以離南畝也。〔四〕今使胡人數處轉牧行獵於塞下，或當燕代，或當上郡、北地、隴西，以候備塞之卒，卒少則入。陛下不救，則邊民絕望而有降敵之心；救之，少發則不足，多發，遠縣纔至，則胡又已去。〔五〕聚而不罷，為費甚大；罷之，則胡復入。如此連年，則中國貧苦而民不安矣。","sentenceOrder":165},
  {"id":"s_work_han_thu_60_166","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「著音直略反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_60_167","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「竟讀曰境。」","sentenceOrder":167},
  {"id":"s_work_han_thu_60_168","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「壄，古野字。」","sentenceOrder":168},
  {"id":"s_work_han_thu_60_169","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「畮，古畝字也。南畝，耕種之處也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_60_170","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　李奇曰：「纔音裁。」師古曰：「纔，淺也，猶言僅至也。他皆類此。」","sentenceOrder":170},
  {"id":"s_work_han_thu_60_171","chapterId":"ch_work_han_thu_60","textTraditional":"陛下幸憂邊境，遣將吏發卒以治塞，甚大惠也。然令遠方之卒守塞，一歲而更，〔一〕不知胡人之能，不如選常居者，家室田作，且以備之。以便為之高城深塹，具藺石，布渠答，〔二〕復為一城其內，城間百五十步。要害之處，通川之道，調立城邑，毋下千家，〔三〕為中周虎落。〔四〕先為室屋，具田器，乃募罪人及免徒復作令居之；〔五〕不足，募以丁奴婢贖罪及輸奴婢欲以拜爵者；不足，乃募民之欲往者。皆賜高爵，復其家。〔六〕予冬夏衣，廩食，能自給而止。〔七〕郡縣之民得買其爵，以自增至卿。〔八〕其亡夫若妻者，縣官買予之。人情非有匹敵，不能久安其處。塞下之民，祿利不厚，不可使久居危難之地。胡人入驅而能止其所驅者，以其半予之，〔九〕縣官為贖其民。〔一０〕如是，則邑里相救助，赴胡不避死。非以德上也，〔一一〕欲全親戚而利其財也。此與東方之（戎）〔戍〕卒不習地勢而心畏胡者，功相萬也。〔一二〕以陛下之時，徙民實邊，使遠方無屯戍之事，塞下之民父子相保，亡係虜之患，利施後世，名稱聖明，其與秦之行怨民，相去遠矣。〔一三〕","sentenceOrder":171},
  {"id":"s_work_han_thu_60_172","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「更謂易代也，音庚，又讀如本字。」","sentenceOrder":172},
  {"id":"s_work_han_thu_60_173","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　服虔曰：「藺石，可投人石也。」蘇林曰：「渠答，鐵疾藜也。」如淳曰：「藺石，城上雷石也。墨子曰：『城上二步一渠，立程長三尺，冠長十尺，臂長六尺；二步一答，廣九尺，袤十二尺。』」師古曰：「藺石，如說是也。渠答，蘇說是也。雷音來內反。」","sentenceOrder":173},
  {"id":"s_work_han_thu_60_174","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「調謂算度之也。總計城邑之中令有千家以上也。調音徒釣反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_60_175","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　鄭氏曰：「虎落者，外蕃也，若今時竹虎也。」蘇林曰：「作虎落於塞要下，以沙布其表，旦視其跡，以知匈奴來入，一名天田。」師古曰：「蘇說非也。虎落者，以竹篾相連遮落之也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_60_176","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　張晏曰：「募民有罪自首，除罪定輸作者也，復作如徒也。」臣瓚曰：「募有罪者及罪人遇赦復作竟其日月者，今皆除其罰，令居之也。」師古曰：「瓚說是也。復音扶目反。」","sentenceOrder":176},
  {"id":"s_work_han_thu_60_177","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　師古曰：「復音方目反。」","sentenceOrder":177},
  {"id":"s_work_han_thu_60_178","chapterId":"ch_work_han_thu_60","textTraditional":"〔七〕　師古曰：「初徙之時，縣官且廩給其衣食，於後能自供贍乃止也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_60_179","chapterId":"ch_work_han_thu_60","textTraditional":"〔八〕　孟康曰：「食貨志所謂樂卿者也，朝位從卿而無職也。」師古曰：「孟說非也。樂卿武帝所置耳，錯之上書未得豫言之也。然二十等爵內無有卿名，蓋謂其等級同列卿者也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_60_180","chapterId":"ch_work_han_thu_60","textTraditional":"〔九〕　孟康曰：「謂胡人入為寇，驅收中國，能奪得之者，以半與之。」師古曰：「孟說非也。言胡人入為寇，驅略漢人及畜產，而它人能止得其所驅者，令其本主以半賞之。」","sentenceOrder":180},
  {"id":"s_work_han_thu_60_181","chapterId":"ch_work_han_thu_60","textTraditional":"〔一０〕張晏曰：「得漢人，官為贖也。」師古曰：「此承上句之言，謂官為備價贖之耳。張說非也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_60_182","chapterId":"ch_work_han_thu_60","textTraditional":"〔一一〕師古曰：「言非以此事欲立德義於主上也。」","sentenceOrder":182},
  {"id":"s_work_han_thu_60_183","chapterId":"ch_work_han_thu_60","textTraditional":"〔一二〕如淳曰：「東方諸郡民不習戰鬥當戍邊者也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_60_184","chapterId":"ch_work_han_thu_60","textTraditional":"〔一三〕師古曰：「言發怨恨之人使行戍役也。」","sentenceOrder":184},
  {"id":"s_work_han_thu_60_185","chapterId":"ch_work_han_thu_60","textTraditional":"上從其言，募民徙塞下。錯復言：","sentenceOrder":185},
  {"id":"s_work_han_thu_60_186","chapterId":"ch_work_han_thu_60","textTraditional":"陛下幸募民相徙以實塞下，使屯戍之事益省，輸將之費益寡，〔一〕甚大惠也。下吏誠能稱厚惠，奉明法，〔二〕存卹所徙之老弱，善遇其壯士，和輯其心而勿侵刻，〔三〕使先至者安樂而不思故鄉，則貧民相募而勸往矣。臣聞古之徙遠方以實廣虛也，〔四〕相其陰陽之和，嘗其水泉之味，審其土地之宜，觀其屮木之饒，然後營邑立城，製里割宅，通田作之道，正阡陌之界，先為築室，家有一堂二內，門戶之閉，〔五〕置器物焉，民至有所居，作有所用，此民所以輕去故鄉而勸之新（色）〔邑〕也。〔六〕為置醫巫，以救疾病，以脩祭祀，男女有昏，〔七〕生死相卹，墳墓相從，種樹畜長，〔八〕室屋完安，此所以使民樂其處而有長居之心也。","sentenceOrder":186},
  {"id":"s_work_han_thu_60_187","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　如淳曰：「將，送也。或曰，將，資也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_60_188","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「稱，副也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_60_189","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「輯與集同。」","sentenceOrder":189},
  {"id":"s_work_han_thu_60_190","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「所以充實寬廣空虛之地。」","sentenceOrder":190},
  {"id":"s_work_han_thu_60_191","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　張晏曰：「二內，二房也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_60_192","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　師古曰：「之，往也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_60_193","chapterId":"ch_work_han_thu_60","textTraditional":"〔七〕　師古曰：「昏謂婚姻配合也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_60_194","chapterId":"ch_work_han_thu_60","textTraditional":"〔八〕　張晏曰：「畜長，六畜也。」師古曰：「種樹謂桑果之屬。長音竹兩反。」","sentenceOrder":194},
  {"id":"s_work_han_thu_60_195","chapterId":"ch_work_han_thu_60","textTraditional":"臣又聞古之制邊縣以備敵也，使五家為伍，伍有長；十長一里，里有假士；四里一連，連有假五百；〔一〕十連一邑，邑有假候：皆擇其邑之賢材有護，〔二〕習地形知民心者，居則習民於射法，出則教民於應敵。故卒伍成於內，則軍正定於外。服習以成，勿令遷徙，〔三〕幼則同游，長則共事。夜戰聲相知，則足以相救；晝戰目相見，則足以相識；驩愛之心，足以相死。如此而勸以厚賞，威以重罰，則前死不還踵矣。〔四〕所徙之民非壯有材力，但費衣糧，不可用也；雖有材力，不得良吏，猶亡功也。","sentenceOrder":195},
  {"id":"s_work_han_thu_60_196","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　服虔曰：「假音假借之假。五百，帥名也。」師古曰：「假，大也，音工雅反。」","sentenceOrder":196},
  {"id":"s_work_han_thu_60_197","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「有保護之能者也。今流俗書本護字作讓，妄改之耳。」","sentenceOrder":197},
  {"id":"s_work_han_thu_60_198","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「各守其業也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_60_199","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「還讀曰旋。旋踵，回旋其足也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_60_200","chapterId":"ch_work_han_thu_60","textTraditional":"陛下絕匈奴不與和親，臣竊意其冬來南也，〔一〕壹大治，則終身創矣。〔二〕欲立威者，始於折膠，〔三〕來而不能困，使得氣去，〔四〕後未易服也。愚臣亡識，唯陛下財察。","sentenceOrder":200},
  {"id":"s_work_han_thu_60_201","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「意，疑之也。」","sentenceOrder":201},
  {"id":"s_work_han_thu_60_202","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「創，懲艾也，音初亮反。」","sentenceOrder":202},
  {"id":"s_work_han_thu_60_203","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　蘇林曰：「秋氣至，膠可折，弓弩可用，匈奴常以為候而出（車）〔軍〕。」","sentenceOrder":203},
  {"id":"s_work_han_thu_60_204","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「使之得勝，逞志氣而去。」","sentenceOrder":204},
  {"id":"s_work_han_thu_60_205","chapterId":"ch_work_han_thu_60","textTraditional":"後詔有司舉賢良文學士，錯在選中。上親策詔之，曰：","sentenceOrder":205},
  {"id":"s_work_han_thu_60_206","chapterId":"ch_work_han_thu_60","textTraditional":"惟十有五年九月壬子，皇帝曰：昔者大禹勤求賢士，施及方外，〔一〕四極之內，舟車所至，人跡所及，靡不聞命，以輔其不逮；〔二〕近者獻其明，遠者通厥聰，比善戮力，以翼天子。〔三〕是以大禹能亡失德，夏以長楙。〔四〕高皇帝親除大害，去亂從，〔五〕並建豪英，以為官師，〔六〕為諫爭，輔天子之闕，而翼戴漢宗也。賴天之靈，宗廟之福，方內以安，澤及四夷。今朕獲執天子之正，以承宗廟之祀，朕既不德，又不敏，明弗能燭，而智不能治，此大夫之所著聞也。故詔有司、諸侯王、三公、九卿及主郡吏，〔七〕各帥其志，以選賢良明於國家之大體，通於人事之終始，及能直言極諫者，各有人數，將以匡朕之不逮。二三大夫之行當此三道，〔八〕朕甚嘉之，故登大夫于朝，親諭朕志。〔九〕大夫其上三道之要，及永惟朕之不德，吏之不平，政之不宣，民之不寧，〔一０〕四者之闕，悉陳其志，毋有所隱。上以薦先帝之宗廟，下以興愚民之休利，著之于篇，〔一一〕朕親覽焉，觀大夫所以佐朕，至與不至。書之，周之密之，重之閉之。〔一二〕興自朕躬，〔一三〕大夫其正論，毋枉執事。〔一四〕烏虖，戒之！〔一五〕二三大夫其帥志毋怠！","sentenceOrder":206},
  {"id":"s_work_han_thu_60_207","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「施，延也，音弋豉反。」","sentenceOrder":207},
  {"id":"s_work_han_thu_60_208","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「意所不及者，取其言以自輔也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_60_209","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「比，和也。翼，助也。比音頻寐反。」","sentenceOrder":209},
  {"id":"s_work_han_thu_60_210","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「楙，美也。」","sentenceOrder":210},
  {"id":"s_work_han_thu_60_211","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　師古曰：「從音子容反。亂從，謂禍亂之蹤跡也。一曰，亂謂作亂者，從謂合從者，若六國時為從者也。今書本從下或有順字，或有治字，皆非也，後人妄加之也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_60_212","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　師古曰：「師，長也，各為一官之長也。字或作帥，音所類反。」","sentenceOrder":212},
  {"id":"s_work_han_thu_60_213","chapterId":"ch_work_han_thu_60","textTraditional":"〔七〕　師古曰：「主郡吏，謂郡守也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_60_214","chapterId":"ch_work_han_thu_60","textTraditional":"〔八〕　張晏曰：「三道，國體、人事、直言也。」師古曰：「二三大夫，總謂當時受策者，非止錯一人焉。」","sentenceOrder":214},
  {"id":"s_work_han_thu_60_215","chapterId":"ch_work_han_thu_60","textTraditional":"〔九〕　師古曰：「諭，告也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_60_216","chapterId":"ch_work_han_thu_60","textTraditional":"〔一０〕師古曰：「永猶深也。惟，思也。」","sentenceOrder":216},
  {"id":"s_work_han_thu_60_217","chapterId":"ch_work_han_thu_60","textTraditional":"〔一一〕師古曰：「休，美也。篇謂簡也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_60_218","chapterId":"ch_work_han_thu_60","textTraditional":"〔一二〕師古曰：「重音直龍反。」","sentenceOrder":218},
  {"id":"s_work_han_thu_60_219","chapterId":"ch_work_han_thu_60","textTraditional":"〔一三〕師古曰：「言朕自發視之。」","sentenceOrder":219},
  {"id":"s_work_han_thu_60_220","chapterId":"ch_work_han_thu_60","textTraditional":"〔一四〕張晏曰：「毋為有司枉橈也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_60_221","chapterId":"ch_work_han_thu_60","textTraditional":"〔一五〕師古曰：「虖讀曰呼。」","sentenceOrder":221},
  {"id":"s_work_han_thu_60_222","chapterId":"ch_work_han_thu_60","textTraditional":"錯對曰：","sentenceOrder":222},
  {"id":"s_work_han_thu_60_223","chapterId":"ch_work_han_thu_60","textTraditional":"平陽侯臣窋、〔一〕汝陰侯臣灶、〔二〕潁陰侯臣何、〔三〕廷尉臣宜昌、隴西太守臣昆邪〔四〕所選賢良太子家令臣錯〔五〕昧死再拜言：臣竊聞古之賢主莫不求賢以為輔翼，故黃帝得力牧而為五帝〔先〕，〔六〕大禹得咎繇而為三王祖，齊桓得筦子而為五伯長。〔七〕今陛下講于大禹及高皇帝之建豪英也，〔八〕退託於不明，以求賢良，〔九〕讓之至也。臣竊觀上世之傳，〔一０〕若高皇帝之建功業，陛下之德厚而得賢佐，皆有司之所覽，刻於玉版，藏於金匱，歷之春秋，紀之後世，為帝者祖宗，與天地相終。今臣窋等乃以臣錯充賦，〔一一〕甚不稱明詔求賢之意。臣錯屮茅臣，亡識知，昧死上愚對，曰：","sentenceOrder":223},
  {"id":"s_work_han_thu_60_224","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　孟康曰：「曹窋，參子也。」","sentenceOrder":224},
  {"id":"s_work_han_thu_60_225","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　如淳曰：「夏侯嬰子也。」","sentenceOrder":225},
  {"id":"s_work_han_thu_60_226","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　文穎曰：「灌嬰子。」","sentenceOrder":226},
  {"id":"s_work_han_thu_60_227","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　服虔曰：「公孫昆邪也。」師古曰：「昆讀曰混，音下昆反。」","sentenceOrder":227},
  {"id":"s_work_han_thu_60_228","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　師古曰：「詔列侯九卿及郡守舉賢良，故錯為窋等所舉。」","sentenceOrder":228},
  {"id":"s_work_han_thu_60_229","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　服虔曰：「力牧，黃帝之佐也。」","sentenceOrder":229},
  {"id":"s_work_han_thu_60_230","chapterId":"ch_work_han_thu_60","textTraditional":"〔七〕　師古曰：「筦字與管同。伯讀曰霸。」","sentenceOrder":230},
  {"id":"s_work_han_thu_60_231","chapterId":"ch_work_han_thu_60","textTraditional":"〔八〕　臣瓚曰：「講謂講議也。」","sentenceOrder":231},
  {"id":"s_work_han_thu_60_232","chapterId":"ch_work_han_thu_60","textTraditional":"〔九〕　師古曰：「自託不明，是謙退。」","sentenceOrder":232},
  {"id":"s_work_han_thu_60_233","chapterId":"ch_work_han_thu_60","textTraditional":"〔一０〕師古曰：「謂史傳。」","sentenceOrder":233},
  {"id":"s_work_han_thu_60_234","chapterId":"ch_work_han_thu_60","textTraditional":"〔一一〕〔如淳〕曰：「猶言備數也。」臣瓚曰：「充賦，此錯之謙也，云如賦調也。」","sentenceOrder":234},
  {"id":"s_work_han_thu_60_235","chapterId":"ch_work_han_thu_60","textTraditional":"詔策曰「明於國家大體」，愚臣竊以古之五帝明之。臣聞五帝神聖，其臣莫能及，故自親事，〔一〕處于法宮之中，明堂之上；〔二〕動靜上配天，下順地，中得人。故眾生之類亡不覆也，根著之徒亡不載也；〔三〕燭以光明，亡偏異也；〔四〕德上及飛鳥，下至水蟲草木諸產，皆被其澤。〔五〕然後陰陽調，四時節，日月光，風雨時，膏露降，〔六〕五穀孰，祅孽滅，賊氣息，民不疾疫，河出圖，洛出書，神龍至，鳳鳥翔，德澤滿天下，靈光施四海。此謂配天地，治國大體之功也。","sentenceOrder":235},
  {"id":"s_work_han_thu_60_236","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「親理萬機之務。」","sentenceOrder":236},
  {"id":"s_work_han_thu_60_237","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　如淳曰：「法宮，路寢正殿也。」","sentenceOrder":237},
  {"id":"s_work_han_thu_60_238","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「有根著地者皆載之也。著音直略反。」","sentenceOrder":238},
  {"id":"s_work_han_thu_60_239","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「燭，照也。」","sentenceOrder":239},
  {"id":"s_work_han_thu_60_240","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　師古曰：「被音皮義反。」","sentenceOrder":240},
  {"id":"s_work_han_thu_60_241","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　師古曰：「甘露凝如膏。」","sentenceOrder":241},
  {"id":"s_work_han_thu_60_242","chapterId":"ch_work_han_thu_60","textTraditional":"詔策曰「通於人事終始」，愚臣竊以古之三王明之。臣聞三王臣主俱賢，故合謀相輔，計安天下，莫不本於人情。人情莫不欲壽，三王生而不傷也；人情莫不欲富，三王厚而不困也；人情莫不欲安，三王扶而不危也；人情莫不欲逸，三王節其力而不盡也。其為法令也，合於人情而後行之；其動眾使民也，本於人事然後為之。取人以己，內恕及人。〔一〕情之所惡，不以彊人；情之所欲，不以禁民。是以天下樂其政，歸其德，望之若父母，從之若流水；百姓和親，國家安寧，名位不失，施及後世。〔二〕此明於人情終始之功也。","sentenceOrder":242},
  {"id":"s_work_han_thu_60_243","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「以己之心揆之於人也。」","sentenceOrder":243},
  {"id":"s_work_han_thu_60_244","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「施，延也，音弋豉反。」","sentenceOrder":244},
  {"id":"s_work_han_thu_60_245","chapterId":"ch_work_han_thu_60","textTraditional":"詔策曰「直言極諫」，愚臣竊以五伯之臣明之。〔一〕臣聞五伯不及其臣，故屬之以國，任之以事。〔二〕五伯之佐之為人臣也，察身而不敢誣，〔三〕奉法令不容私，盡心力不敢矜，〔四〕遭患難不避死，見賢不居其上，受祿不過其量，不以亡能居尊顯之位。自行若此，可謂方正之士矣。其立法也，非以苦民傷眾而為之機陷也，〔五〕以之興利除害，尊主安民而救暴亂也。其行賞也，非虛取民財妄予人也，以勸天下之忠孝而明其功也。故功多者賞厚，功少者賞薄。如此，斂民財以顧其功，〔六〕而民不恨者，知與而安己也。其行罰也，非以忿怒妄誅而從暴心也，〔七〕以禁天下不忠不孝而害國者也。故罪大者罰重，罪小者罰輕。如此，民雖伏罪至死而不怨者，知罪罰之至，自取之也。立法若此，可謂平正之吏矣。法之逆者，請而更之，不以傷民；〔八〕主行之暴者，逆而復之，不以傷國。〔九〕救主之失，補主之過，揚主之美，明主之功，使主內亡邪辟之行，外亡騫汙之名。〔一０〕事君若此，可謂直言極諫之士矣。此五伯之所以德匡天下，威正諸侯，功業甚美，名聲章明。舉天下之賢主，五伯與焉，〔一一〕此身不及其臣而使得直言極諫補其不逮之功也。今陛下人民之眾，威武之重，德惠之厚，令行禁止之勢，萬萬於五伯，而賜愚臣策曰「匡朕之不逮」，愚臣何足以識陛下之高明而奉承之！","sentenceOrder":245},
  {"id":"s_work_han_thu_60_246","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「伯讀曰霸。」","sentenceOrder":246},
  {"id":"s_work_han_thu_60_247","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「屬，委也，音之欲反。」","sentenceOrder":247},
  {"id":"s_work_han_thu_60_248","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「各察己之材用，不敢踰越而誣上。」","sentenceOrder":248},
  {"id":"s_work_han_thu_60_249","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「矜謂自伐也。」","sentenceOrder":249},
  {"id":"s_work_han_thu_60_250","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　孟康曰：「機，發也。陷，穽也。」","sentenceOrder":250},
  {"id":"s_work_han_thu_60_251","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　師古曰：「顧，讎也，若今言雇賃也。」","sentenceOrder":251},
  {"id":"s_work_han_thu_60_252","chapterId":"ch_work_han_thu_60","textTraditional":"〔七〕　師古曰：「從讀曰縱。」","sentenceOrder":252},
  {"id":"s_work_han_thu_60_253","chapterId":"ch_work_han_thu_60","textTraditional":"〔八〕　師古曰：「更，改也。」","sentenceOrder":253},
  {"id":"s_work_han_thu_60_254","chapterId":"ch_work_han_thu_60","textTraditional":"〔九〕　師古曰：「謂逆主意而反還之，不令施行，致傷國也。復音扶目反。」","sentenceOrder":254},
  {"id":"s_work_han_thu_60_255","chapterId":"ch_work_han_thu_60","textTraditional":"〔一０〕師古曰：「辟讀曰僻。騫，損也。汙，辱也。」","sentenceOrder":255},
  {"id":"s_work_han_thu_60_256","chapterId":"ch_work_han_thu_60","textTraditional":"〔一一〕　師古曰：「與讀曰豫。」","sentenceOrder":256},
  {"id":"s_work_han_thu_60_257","chapterId":"ch_work_han_thu_60","textTraditional":"詔策曰「吏之不平，政之不宣，民之不寧」，愚臣竊以秦事明之。臣聞秦始并天下之時，其主不及三王，而臣不及其佐，〔一〕然功力不遲者，何也？地形便，山川利，財用足，民利戰。其所與並者六國，六國者，臣主皆不肖，謀不輯，〔二〕民不用，故當此之時，秦最富彊。夫國富彊而鄰國亂者，帝王之資也，故秦能兼六國，立為天子。當此之時，三王之功不能進焉。〔三〕及其末塗之衰也，任不肖而信讒賊；宮室過度，耆慾亡極，〔四〕民力罷盡，賦斂不節；〔五〕矜奮自賢，群臣恐諛，〔六〕驕溢縱恣，不顧患禍；妄賞以隨（善）〔喜〕意，妄誅以快怒心，法令煩憯，〔七〕刑罰暴酷，輕絕人命，身自射殺；天下寒心，莫安其處。姦邪之吏，乘其亂法，以成其威，獄官主斷，生殺自恣。上下瓦解，各自為制。秦始亂之時，吏之所先侵者，貧人賤民也；至其中節，所侵者富人吏家也；及其末塗，所侵者宗室大臣也。是故親疏皆危，外內咸怨，離散逋逃，人有走心。陳勝先倡，天下大潰，〔八〕絕祀亡世，為異姓福。此吏不平，政不宣，民不寧之禍也。今陛下配天象地，覆露萬民，〔九〕絕秦之跡，除其亂法；躬親本事，廢去淫末；除苛解嬈，〔一０〕寬大愛人；肉刑不用，罪人亡帑；〔一一〕非謗不治，鑄錢者除；〔一二〕通關去塞，〔一三〕不孽諸侯；〔一四〕賓禮長老，愛卹少孤；罪人有期，〔一五〕後宮出嫁；尊賜孝悌，農民不租；〔一六〕明詔軍師，愛士大夫；求進方正，廢退姦邪；除去陰刑，〔一七〕害民者誅；憂勞百姓，列侯就都；〔一八〕親耕節用，視民不奢。〔一九〕所為天下興利除害，變法易故，以安海內者，大功數十，皆上世之所難及，陛下行之，道純德厚，元元之民幸矣。","sentenceOrder":257},
  {"id":"s_work_han_thu_60_258","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「臣亦不及三王之佐。」","sentenceOrder":258},
  {"id":"s_work_han_thu_60_259","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「輯與集同。輯，和也。」","sentenceOrder":259},
  {"id":"s_work_han_thu_60_260","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「進，前也，言不在秦之前也。」","sentenceOrder":260},
  {"id":"s_work_han_thu_60_261","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「耆讀曰嗜。」","sentenceOrder":261},
  {"id":"s_work_han_thu_60_262","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　師古曰：「罷讀曰疲。」","sentenceOrder":262},
  {"id":"s_work_han_thu_60_263","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　張晏曰：「恐機發陷禍而為諂諛以求自全也。」師古曰：「此說非也。直為恐懼而為諂諛也。恐音丘勇反。」","sentenceOrder":263},
  {"id":"s_work_han_thu_60_264","chapterId":"ch_work_han_thu_60","textTraditional":"〔七〕　師古曰：「憯，痛也。言痛害於下。憯音千感反。」","sentenceOrder":264},
  {"id":"s_work_han_thu_60_265","chapterId":"ch_work_han_thu_60","textTraditional":"〔八〕　師古曰：「倡讀曰唱。」","sentenceOrder":265},
  {"id":"s_work_han_thu_60_266","chapterId":"ch_work_han_thu_60","textTraditional":"〔九〕　如淳曰：「覆，蔭也。露，膏澤也。」","sentenceOrder":266},
  {"id":"s_work_han_thu_60_267","chapterId":"ch_work_han_thu_60","textTraditional":"〔一０〕文穎曰：「嬈，煩繞也。」師古曰：「音如紹反。」","sentenceOrder":267},
  {"id":"s_work_han_thu_60_268","chapterId":"ch_work_han_thu_60","textTraditional":"〔一一〕師古曰：「謂除收帑相坐律。亡讀曰無。帑讀曰孥。」","sentenceOrder":268},
  {"id":"s_work_han_thu_60_269","chapterId":"ch_work_han_thu_60","textTraditional":"〔一二〕張晏曰：「除鑄錢之律，聽民得自鑄也。」師古曰：「非讀曰誹。」","sentenceOrder":269},
  {"id":"s_work_han_thu_60_270","chapterId":"ch_work_han_thu_60","textTraditional":"〔一三〕張晏曰：「文帝十二年，除關不用傳。」","sentenceOrder":270},
  {"id":"s_work_han_thu_60_271","chapterId":"ch_work_han_thu_60","textTraditional":"〔一四〕應劭曰：「接之以禮，不以庶孽畜之。」如淳曰：「孽，疑也。去關禁，明無疑於諸侯。」師古曰：「應說是。」","sentenceOrder":271},
  {"id":"s_work_han_thu_60_272","chapterId":"ch_work_han_thu_60","textTraditional":"〔一五〕張晏曰：「早決之也。」晉灼曰：「刑法志云『罪人各以輕重不亡逃，有年而免』。滿其年，免為庶人也。」師古曰：「晉說是也。」","sentenceOrder":272},
  {"id":"s_work_han_thu_60_273","chapterId":"ch_work_han_thu_60","textTraditional":"〔一六〕張晏曰：「足用則除租也。」","sentenceOrder":273},
  {"id":"s_work_han_thu_60_274","chapterId":"ch_work_han_thu_60","textTraditional":"〔一七〕張晏曰：「宮刑也。」","sentenceOrder":274},
  {"id":"s_work_han_thu_60_275","chapterId":"ch_work_han_thu_60","textTraditional":"〔一八〕師古曰：「各就其國也。」","sentenceOrder":275},
  {"id":"s_work_han_thu_60_276","chapterId":"ch_work_han_thu_60","textTraditional":"〔一九〕師古曰：「視讀曰示。」","sentenceOrder":276},
  {"id":"s_work_han_thu_60_277","chapterId":"ch_work_han_thu_60","textTraditional":"詔策曰「永惟朕之不德」，愚臣不足以當之。","sentenceOrder":277},
  {"id":"s_work_han_thu_60_278","chapterId":"ch_work_han_thu_60","textTraditional":"詔策曰「悉陳其志，毋有所隱」，愚臣竊以五帝之賢臣明之。臣聞五帝其臣莫能及，則自親之；三王臣主俱賢，則共憂之；五伯不及其臣，則任使之。此所以神明不遺，而聖賢不廢也，〔一〕故各當其世而立功德焉。傳曰「往者不可及，來者猶可待，〔二〕能明其世者謂之天子」，此之謂也。竊聞戰不勝者易其地，民貧窮者變其業。今以陛下神明德厚，資財不下五帝，〔三〕臨制天下，至今十有六年，民不益富，盜賊不衰，邊竟未安，〔四〕其所以然，意者陛下未之躬親，而待群臣也。今執事之臣皆天下之選已，〔五〕然莫能望陛下清光，〔六〕譬之猶五帝之佐也。陛下不自躬親，而待不望清光之臣，臣竊恐神明之遺也。〔七〕日損一日，歲亡一歲，日月益暮，盛德不及究於天下，〔八〕以傳萬世，愚臣不自度量，竊為陛下惜之。昧死上狂惑屮茅之愚，臣言唯陛下財擇。","sentenceOrder":278},
  {"id":"s_work_han_thu_60_279","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「遺，棄也。不棄神明之德，不廢聖賢之名。」","sentenceOrder":279},
  {"id":"s_work_han_thu_60_280","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「言各當其時務立功也。」","sentenceOrder":280},
  {"id":"s_work_han_thu_60_281","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「資，質也，謂天子之財質。」","sentenceOrder":281},
  {"id":"s_work_han_thu_60_282","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「竟讀曰境。」","sentenceOrder":282},
  {"id":"s_work_han_thu_60_283","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　師古曰：「已，語終之辭。」","sentenceOrder":283},
  {"id":"s_work_han_thu_60_284","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　晉灼曰：「今之臣不能望見陛下之光景所及。」","sentenceOrder":284},
  {"id":"s_work_han_thu_60_285","chapterId":"ch_work_han_thu_60","textTraditional":"〔七〕　師古曰：「言天子虛棄神明之德。」","sentenceOrder":285},
  {"id":"s_work_han_thu_60_286","chapterId":"ch_work_han_thu_60","textTraditional":"〔八〕　師古曰：「究，竟也。」","sentenceOrder":286},
  {"id":"s_work_han_thu_60_287","chapterId":"ch_work_han_thu_60","textTraditional":"時賈誼已死，對策者百餘人，唯錯為高第，繇是遷中大夫。〔一〕","sentenceOrder":287},
  {"id":"s_work_han_thu_60_288","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「繇讀與由同。」","sentenceOrder":288},
  {"id":"s_work_han_thu_60_289","chapterId":"ch_work_han_thu_60","textTraditional":"錯又言宜削諸侯事，及法令可更定者，書凡三十篇。孝文雖不盡聽，然奇其材。當是時，太子善錯計策，爰盎諸大功臣多不好錯。","sentenceOrder":289},
  {"id":"s_work_han_thu_60_290","chapterId":"ch_work_han_thu_60","textTraditional":"景帝即位，以錯為內史。錯數請間言事，輒聽，幸傾九卿，法令多所更定。丞相申屠嘉心弗便，力未有以傷。內史府居太上廟堧中，〔一〕門東出，不便，錯乃穿門南出，鑿廟堧垣。丞相大怒，欲因此過為奏請誅錯。錯聞之，即請間為上言之。丞相奏事，因言錯擅鑿廟垣為門，請下廷尉誅。上曰：「此非廟垣，乃堧中垣，不致於法。」丞相謝。〔二〕罷朝，因怒謂長史曰：「吾當先斬以聞，乃先請，固誤。」丞相遂發病死。錯以此愈貴。","sentenceOrder":290},
  {"id":"s_work_han_thu_60_291","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「堧者，內垣之外游地也，音人緣反。」","sentenceOrder":291},
  {"id":"s_work_han_thu_60_292","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「以所奏不當天子意，故謝。」","sentenceOrder":292},
  {"id":"s_work_han_thu_60_293","chapterId":"ch_work_han_thu_60","textTraditional":"遷為御史大夫，請諸侯之罪過，削其支郡。〔一〕奏上，上〔令〕公卿列侯宗室〔雜議〕，莫敢難，獨竇嬰爭之，繇此與錯有隙〔二〕。錯所更令三十章，〔三〕諸侯讙譁。錯父聞之，從潁川來，謂錯曰：「上初即位，公為政用事，〔四〕侵削諸侯，疏人骨肉，口讓多怨，公何為也！」〔五〕錯曰：「固也。〔六〕不如此，天子不尊，宗廟不安。」父曰：「劉氏安矣，而晁氏危，吾去公歸矣！」遂飲藥死，曰：「吾不忍見禍逮身。」","sentenceOrder":293},
  {"id":"s_work_han_thu_60_294","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「支郡，在國之四邊者也。」","sentenceOrder":294},
  {"id":"s_work_han_thu_60_295","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「繇讀與由同。」","sentenceOrder":295},
  {"id":"s_work_han_thu_60_296","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「更，改也。」","sentenceOrder":296},
  {"id":"s_work_han_thu_60_297","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　如淳曰：「錯為御史大夫，位三公也。」","sentenceOrder":297},
  {"id":"s_work_han_thu_60_298","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　師古曰：「讓，責也。」","sentenceOrder":298},
  {"id":"s_work_han_thu_60_299","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　師古曰：「言固當如此。」","sentenceOrder":299},
  {"id":"s_work_han_thu_60_300","chapterId":"ch_work_han_thu_60","textTraditional":"後十餘日，吳楚七國俱反，以誅錯為名。上與錯議出軍事，錯欲令上自將兵，而身居守。會竇嬰言爰盎，詔召入見，上方與錯調兵食。〔一〕上問盎曰：「君嘗為吳相，知吳臣田祿伯為人虖？今吳楚反，於公意何如？」對曰：「不足憂也，今破矣。」上曰：「吳王即山鑄錢，煮海為鹽〔二〕，誘天下豪桀，白頭舉事，此其計不百全，豈發虖？何以言其無能為也？」盎對曰：「吳銅鹽之利則有之，安得豪桀而誘之！誠令吳得豪桀，亦且輔而為誼，不反矣。吳所誘，皆亡賴子弟，亡命鑄錢姦人，故相誘以亂。」錯曰：「盎策之善。」上問曰：「計安出？」盎對曰：「願屏左右。」上屏人，獨錯在。盎曰：「臣所言，人臣不得知。」乃屏錯。錯趨避東箱，甚恨。上卒問盎〔三〕，對曰：「吳楚相遺書，言高皇帝王子弟各有分地，〔四〕今賊臣晁錯擅適諸侯，削奪之地，〔五〕以故反名為西共誅錯，復故地而罷。方今計，獨有斬錯，發使赦吳楚七國，復其故地，則兵可毋血刃而俱罷。」於是上默然，良久曰：「顧誠何如，吾不愛一人謝天下。」〔六〕盎曰：「愚計出此，唯上孰計之。」乃拜盎為太常，密裝治行。","sentenceOrder":300},
  {"id":"s_work_han_thu_60_301","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「調謂計發之也，音徒釣反。」","sentenceOrder":301},
  {"id":"s_work_han_thu_60_302","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「即，就也。」","sentenceOrder":302},
  {"id":"s_work_han_thu_60_303","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「卒，竟也。」","sentenceOrder":303},
  {"id":"s_work_han_thu_60_304","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「分音扶問反。」","sentenceOrder":304},
  {"id":"s_work_han_thu_60_305","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　師古曰：「適讀曰謫。」","sentenceOrder":305},
  {"id":"s_work_han_thu_60_306","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　師古曰：「顧，念也。誠，實也。」","sentenceOrder":306},
  {"id":"s_work_han_thu_60_307","chapterId":"ch_work_han_thu_60","textTraditional":"後十餘日，丞相青翟、中尉嘉、廷尉〈區夂〉〔一〕劾奏錯曰：「吳王反逆亡道，欲危宗廟，天下所當共誅。今御史大夫錯議曰：『兵數百萬，獨屬群臣，不可信，〔二〕陛下不如自出臨兵，使錯居守。徐、僮之旁吳所未下者可以予吳。』〔三〕錯不稱陛下德信，欲疏群臣百姓，又欲以城邑予吳，亡臣子禮，大逆無道。錯當要斬，父母妻子同產無少長皆棄巿。臣請論如法。」制曰：「可。」錯殊不知。乃使中尉召錯，紿載行巿。〔四〕錯衣朝衣斬東巿。〔五〕","sentenceOrder":307},
  {"id":"s_work_han_thu_60_308","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「張〈區夂〉也，音區。」","sentenceOrder":308},
  {"id":"s_work_han_thu_60_309","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「屬，委也，音之欲反。」","sentenceOrder":309},
  {"id":"s_work_han_thu_60_310","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　鄧展曰：「徐、僮，臨淮二縣也。」","sentenceOrder":310},
  {"id":"s_work_han_thu_60_311","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「誑云乘車案行巿中也。行音下更反。」","sentenceOrder":311},
  {"id":"s_work_han_thu_60_312","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　師古曰：「朝衣，朝服也。」","sentenceOrder":312},
  {"id":"s_work_han_thu_60_313","chapterId":"ch_work_han_thu_60","textTraditional":"錯已死，謁者僕射鄧公為校尉，擊吳楚為將。還，上書言軍事，見上。上問曰：「道軍所來，〔一〕聞晁錯死，吳楚罷不？」鄧公曰：「吳為反數十歲矣，發怒削地，以誅錯為名，其意不在錯也。且臣恐天下之士拑口不敢復言矣。」〔二〕上曰：「何哉？」鄧公曰：「夫晁錯患諸侯彊大不可制，故請削之，以尊京師，萬世之利也。計畫始行，卒受大戮，〔三〕內杜忠臣之口，外為諸侯報仇，〔四〕臣竊為陛下不取也。」於景帝喟然長息，曰：「公言善，吾亦恨之。」乃拜鄧公為城陽中尉。","sentenceOrder":313},
  {"id":"s_work_han_thu_60_314","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　如淳曰：「道路從吳軍所來也。」師古曰：「道軍所來，即是從軍所來耳，無煩更說道路也。」","sentenceOrder":314},
  {"id":"s_work_han_thu_60_315","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「拑音其炎反。」","sentenceOrder":315},
  {"id":"s_work_han_thu_60_316","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　師古曰：「卒，竟也。」","sentenceOrder":316},
  {"id":"s_work_han_thu_60_317","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「杜，塞也。」","sentenceOrder":317},
  {"id":"s_work_han_thu_60_318","chapterId":"ch_work_han_thu_60","textTraditional":"鄧公，成固人也，〔一〕多奇計。建元年中，上招賢良，公卿言鄧先。〔二〕鄧先時免，起家為九卿。一年，復謝病免歸。其子章，以修黃老言顯諸公間。","sentenceOrder":318},
  {"id":"s_work_han_thu_60_319","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　師古曰：「漢中之縣。」","sentenceOrder":319},
  {"id":"s_work_han_thu_60_320","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　師古曰：「鄧先，猶云鄧先生也。一曰，先者其名也。」","sentenceOrder":320},
  {"id":"s_work_han_thu_60_321","chapterId":"ch_work_han_thu_60","textTraditional":"贊曰：爰盎雖不好學，亦善傅會，〔一〕仁心為質，引義慷慨。遭孝文初立，資適逢世。〔二〕時已變易，〔三〕及吳壹說，果於用辯，〔四〕身亦不遂。晁錯銳於為國遠慮，而不見身害。其父睹之，經於溝瀆，〔五〕亡益救敗，不如趙母指括，以全其宗。〔六〕悲夫！錯雖不終，世哀其忠。故論其施行之語著于篇。","sentenceOrder":321},
  {"id":"s_work_han_thu_60_322","chapterId":"ch_work_han_thu_60","textTraditional":"〔一〕　張晏曰：「因宜附著合會之。」","sentenceOrder":322},
  {"id":"s_work_han_thu_60_323","chapterId":"ch_work_han_thu_60","textTraditional":"〔二〕　張晏曰：「資，財也，適值其世，得騁其才。」","sentenceOrder":323},
  {"id":"s_work_han_thu_60_324","chapterId":"ch_work_han_thu_60","textTraditional":"〔三〕　張晏曰：「謂景帝。」","sentenceOrder":324},
  {"id":"s_work_han_thu_60_325","chapterId":"ch_work_han_thu_60","textTraditional":"〔四〕　師古曰：「謂殺晁錯也。」","sentenceOrder":325},
  {"id":"s_work_han_thu_60_326","chapterId":"ch_work_han_thu_60","textTraditional":"〔五〕　師古曰：「論語稱孔子曰：『豈若匹夫匹婦之為諒也，自經於溝瀆，人莫之知。』故贊引之云。」","sentenceOrder":326},
  {"id":"s_work_han_thu_60_327","chapterId":"ch_work_han_thu_60","textTraditional":"〔六〕　張晏曰：「趙奢卒，趙使趙括為將，其母言之趙王曰：『願王易括。』王不許。母要王：『〔括〕有罪，願不坐。』王許之。後括果敗於長平，以母前約故，卒得不坐。」","sentenceOrder":327},
  {"id":"s_work_han_thu_60_328","chapterId":"ch_work_han_thu_60","textTraditional":"校勘記","sentenceOrder":328},
  {"id":"s_work_han_thu_60_329","chapterId":"ch_work_han_thu_60","textTraditional":"二二六七頁　八行　（師古）〔如淳〕曰：　景祐、殿本都作「如淳」，史記集解引亦作「如淳」。","sentenceOrder":329},
  {"id":"s_work_han_thu_60_330","chapterId":"ch_work_han_thu_60","textTraditional":"二二七三頁　九行　願（致）〔至〕前，口對狀。　景祐、殿本都作「至」。王先謙說作「至」是。","sentenceOrder":330},
  {"id":"s_work_han_thu_60_331","chapterId":"ch_work_han_thu_60","textTraditional":"二二七七頁一二行　（皇太子所讀書多矣，而未深知術數者也。）　景祐、汲古、殿、局本都無此十六字。","sentenceOrder":331},
  {"id":"s_work_han_thu_60_332","chapterId":"ch_work_han_thu_60","textTraditional":"二二七九頁　一行　敗其眾而（法曰）大有利。　宋祁說當從浙本作「敗其眾而有大利」。　王先謙說通志九十七晁錯傳亦作「敗其眾而有大利」。","sentenceOrder":332},
  {"id":"s_work_han_thu_60_333","chapterId":"ch_work_han_thu_60","textTraditional":"二二七九頁一二行　平地淺（草）〔屮〕，　景祐、殿本都作「屮」。","sentenceOrder":333},
  {"id":"s_work_han_thu_60_334","chapterId":"ch_work_han_thu_60","textTraditional":"二二七九頁一三行　（雚）〔萑〕葦竹蕭，　景祐、殿本都作「雈」，此誤。注同。","sentenceOrder":334},
  {"id":"s_work_han_thu_60_335","chapterId":"ch_work_han_thu_60","textTraditional":"二二八０頁　一行　與金鼓之（音）〔指〕相失，　景祐本作「指」。王念孫說作","sentenceOrder":335},
  {"id":"s_work_han_thu_60_336","chapterId":"ch_work_han_thu_60","textTraditional":"二二八０頁　五行　四者，（國）〔兵〕之至要也。　景祐、殿本都作「兵」。王先謙說作「兵」是。","sentenceOrder":336},
  {"id":"s_work_han_thu_60_337","chapterId":"ch_work_han_thu_60","textTraditional":"二二八０頁一二行（雚亂）〔雈，薍〕也。　景祐、殿本都作「萑薍」，此誤。","sentenceOrder":337},
  {"id":"s_work_han_thu_60_338","chapterId":"ch_work_han_thu_60","textTraditional":"二二八六頁一０行　縣官為贖其民。〔一０〕　注〔一０〕原在「為贖」下。　劉攽說「其民」當連上句。　王先謙說劉說是。","sentenceOrder":338},
  {"id":"s_work_han_thu_60_339","chapterId":"ch_work_han_thu_60","textTraditional":"二二八六頁一一行　此與東方之（戎）〔戍〕卒　景祐、殿本都作「戍」。　王先謙說作「戍」是。","sentenceOrder":339},
  {"id":"s_work_han_thu_60_340","chapterId":"ch_work_han_thu_60","textTraditional":"二二八八頁　六行　此民所以輕去故鄉而勸之新（色）〔邑〕也。　錢大昭說「色」當作「邑」。按景祐、汲古、殿、局本都作「邑」。","sentenceOrder":340},
  {"id":"s_work_han_thu_60_341","chapterId":"ch_work_han_thu_60","textTraditional":"二二八九頁一五行　匈奴常以為候而出（車）〔軍〕。　景祐、殿本都作「軍」。王先謙說作「軍」是。","sentenceOrder":341},
  {"id":"s_work_han_thu_60_342","chapterId":"ch_work_han_thu_60","textTraditional":"二二九二頁　二行　故黃帝得力牧而為五帝〔先〕，　景祐、殿本都有「先」字。王先謙說有「先」字是。","sentenceOrder":342},
  {"id":"s_work_han_thu_60_343","chapterId":"ch_work_han_thu_60","textTraditional":"二二九三頁　一行　〔如淳〕曰：　景祐、殿本都有「如淳」二字，此脫。","sentenceOrder":343},
  {"id":"s_work_han_thu_60_344","chapterId":"ch_work_han_thu_60","textTraditional":"二二九六頁　七行　妄賞以隨（善）〔喜〕意，　景祐、殿本都作「喜」。","sentenceOrder":344},
  {"id":"s_work_han_thu_60_345","chapterId":"ch_work_han_thu_60","textTraditional":"二三００頁　五行　上〔令〕公卿列侯宗室〔雜議〕，　景祐、殿本都有「令」及「雜議」字。","sentenceOrder":345},
  {"id":"s_work_han_thu_60_346","chapterId":"ch_work_han_thu_60","textTraditional":"二三０四頁　四行　〔括〕有罪，願不坐。　景祐、殿本都有「括」字。","sentenceOrder":346},
  {"id":"s_work_han_thu_61_1","chapterId":"ch_work_han_thu_61","textTraditional":"張釋之字季，南陽堵陽人也。〔一〕與兄仲同居，以貲為騎郎，〔二〕事文帝，十年不得調，〔三〕亡所知名。釋之曰：「久宦減仲之產，不遂。」〔四〕欲免歸。中郎將爰盎知其賢，惜其去，乃請徙釋之補謁者。釋之既朝畢，因前言便宜事。文帝曰：「卑之，毋甚高論，〔五〕令今可行也。」於是釋之言秦漢之間事，秦所以失，漢所以興者。文帝稱善，拜釋之為謁者僕射。","sentenceOrder":1},
  {"id":"s_work_han_thu_61_2","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕師古曰：「堵音者。」","sentenceOrder":2},
  {"id":"s_work_han_thu_61_3","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕蘇林曰：「雇錢若出穀也。」如淳曰：「漢注貲五百萬得為常侍郎。」師古曰：「如說是也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_61_4","chapterId":"ch_work_han_thu_61","textTraditional":"〔三〕師古曰：「調，選也，音徒釣反。」","sentenceOrder":4},
  {"id":"s_work_han_thu_61_5","chapterId":"ch_work_han_thu_61","textTraditional":"〔四〕師古曰：「遂猶達。」","sentenceOrder":5},
  {"id":"s_work_han_thu_61_6","chapterId":"ch_work_han_thu_61","textTraditional":"〔五〕師古曰：「令其議論依附時事也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_61_7","chapterId":"ch_work_han_thu_61","textTraditional":"從行，上登虎圈，〔二〕問上林尉禽獸簿，〔二〕十餘問，尉左右視，盡不能對。〔三〕虎圈嗇夫從旁代尉對上所問禽獸簿甚悉〔四〕，欲以觀其能口對嚮應亡窮者。〔五〕文帝曰：「吏不當如此邪？尉亡賴！」〔六〕詔釋之拜嗇夫為上林令。釋之前曰：「陛下以絳侯周勃何如人也？」上曰：「長者。」又復問：「東陽侯張相如何如人也？」上復曰：「長者。」釋之曰：「夫絳侯、東陽侯稱為長者，此兩人言事曾不能出口，豈效此嗇夫喋喋利口捷給哉！〔七〕且秦以任刀筆之吏，爭以亟疾苛察相高，〔八〕其敝徒文具，亡惻隱之實〔九〕。以故不聞其過，陵夷至於二世，天下土崩。〔一０〕今陛下以嗇夫口辯而超遷之，臣恐天下隨風靡，爭口辯，亡其實。且下之化上，疾於景嚮，舉錯不可不察也。」〔一一〕文帝曰：「善。」乃止不拜嗇夫。","sentenceOrder":7},
  {"id":"s_work_han_thu_61_8","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　師古曰：「圈，養獸之所也，音求遠反。」","sentenceOrder":8},
  {"id":"s_work_han_thu_61_9","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　師古曰：「簿謂簿書也，音步戶反。」","sentenceOrder":9},
  {"id":"s_work_han_thu_61_10","chapterId":"ch_work_han_thu_61","textTraditional":"〔三〕　師古曰：「視其屬官，皆不能對也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_61_11","chapterId":"ch_work_han_thu_61","textTraditional":"〔四〕　師古曰：「悉謂詳盡也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_61_12","chapterId":"ch_work_han_thu_61","textTraditional":"〔五〕　師古曰：「觀猶示也。嚮讀曰（嚮）〔響〕。如響應聲，言其疾也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_61_13","chapterId":"ch_work_han_thu_61","textTraditional":"〔六〕　張晏曰：「材無可恃也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_61_14","chapterId":"ch_work_han_thu_61","textTraditional":"〔七〕　晉灼曰：「喋音牒。」","sentenceOrder":14},
  {"id":"s_work_han_thu_61_15","chapterId":"ch_work_han_thu_61","textTraditional":"〔八〕　師古曰：「亟，急也，音居力反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_61_16","chapterId":"ch_work_han_thu_61","textTraditional":"〔九〕　師古曰：「文具，謂具文而已。」","sentenceOrder":16},
  {"id":"s_work_han_thu_61_17","chapterId":"ch_work_han_thu_61","textTraditional":"〔一０〕師古曰：「陵夷，頹替也，解在成紀。」〔一一〕師古曰：「嚮讀曰響。錯音千故反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_61_18","chapterId":"ch_work_han_thu_61","textTraditional":"就車，召釋之驂乘，徐行，行問釋之秦之敝。〔一〕具以質言。〔二〕至宮，上拜釋之為公車令。","sentenceOrder":18},
  {"id":"s_work_han_thu_61_19","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　師古曰：「行問，且行且問也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_61_20","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　如淳曰：「質，誠也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_61_21","chapterId":"ch_work_han_thu_61","textTraditional":"頃之，太子與梁王共車入朝，不下司馬門，〔一〕於是釋之追止太子、梁王毌入殿門。遂劾不下公門不敬，奏之。薄太后聞之，文帝免冠謝曰：「教兒子不謹。」薄太后使使承詔赦太子、梁王，然後得入。文帝繇是奇釋之，〔二〕拜為中大夫。","sentenceOrder":21},
  {"id":"s_work_han_thu_61_22","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕如淳曰：「宮衛令『諸出入殿門公車司馬門者皆下，不如令，罰金四兩』。」","sentenceOrder":22},
  {"id":"s_work_han_thu_61_23","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕師古曰：「繇讀與由同。」","sentenceOrder":23},
  {"id":"s_work_han_thu_61_24","chapterId":"ch_work_han_thu_61","textTraditional":"頃之，至中郎將。從行至霸陵，上居外臨廁。〔一〕時慎夫人從，上指視慎夫人新豐道，曰：「此走邯鄲道也。」〔二〕使慎夫人鼓瑟，上自倚瑟而歌，〔三〕意悽愴悲懷，顧謂群臣曰：「嗟乎！以北山石為槨，用紵絮斮陳漆其間，豈可動哉！」〔四〕左右皆曰：「善。」釋之前曰：「使其中有可欲，雖錮南山猶有隙；使其中亡可欲，雖亡石槨，又何戚焉？」〔五〕文帝稱善。其後，拜釋之為廷尉。","sentenceOrder":24},
  {"id":"s_work_han_thu_61_25","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕師古曰：「廁，岸之邊側也，解在劉向傳。」","sentenceOrder":25},
  {"id":"s_work_han_thu_61_26","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕張晏曰：「慎夫人，邯鄲人也。」如淳曰：「走音奏。奏，趣也。」師古曰：「視讀曰示。」","sentenceOrder":26},
  {"id":"s_work_han_thu_61_27","chapterId":"ch_work_han_thu_61","textTraditional":"〔四〕師古曰：「紵音竹呂反。斮音側略反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_61_28","chapterId":"ch_work_han_thu_61","textTraditional":"〔五〕師古曰：「解並在劉向傳。」","sentenceOrder":28},
  {"id":"s_work_han_thu_61_29","chapterId":"ch_work_han_thu_61","textTraditional":"頃之，上行出中渭橋，〔一〕有一人從橋下走，乘輿馬驚。於是使騎捕之，屬廷尉。〔二〕釋之治問。曰：「縣人來，〔三〕聞蹕，匿橋下。久，以為行過，〔四〕既出，見車騎，即走耳。」釋之奏當：「此人犯蹕，〔五〕當罰金。」上怒曰：「此人親驚吾馬，馬賴和柔，令它馬，固不敗傷我乎？而廷尉乃當之罰金！」釋之曰：「法者天子所與天子公共也。〔六〕今法如是，更重之，是法不信於民也。且方其時，上使使誅之則已。〔七〕今已下廷尉，廷尉，天下之平也，壹傾，天下用法皆為之輕重，民安所錯其手足？〔八〕唯陛下察之。」上良久曰：「廷尉當是也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_61_30","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　張晏曰：「在渭橋中路。」","sentenceOrder":30},
  {"id":"s_work_han_thu_61_31","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　師古曰：「屬，委也，音之欲反。次下亦同。」","sentenceOrder":31},
  {"id":"s_work_han_thu_61_32","chapterId":"ch_work_han_thu_61","textTraditional":"〔三〕　如淳曰：「長安縣人也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_61_33","chapterId":"ch_work_han_thu_61","textTraditional":"〔四〕　師古曰：「言天子已過。」","sentenceOrder":33},
  {"id":"s_work_han_thu_61_34","chapterId":"ch_work_han_thu_61","textTraditional":"〔五〕　如淳曰：「乙令『蹕先至而犯者，罰金四兩』。」師古曰：「當謂處其罪也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_61_35","chapterId":"ch_work_han_thu_61","textTraditional":"〔六〕　師古曰：「公謂不私也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_61_36","chapterId":"ch_work_han_thu_61","textTraditional":"〔七〕　師古曰：「言初執獲此人，天子即令誅之，其事即畢。」","sentenceOrder":36},
  {"id":"s_work_han_thu_61_37","chapterId":"ch_work_han_thu_61","textTraditional":"〔八〕　師古曰：「安，焉也。錯，置也，音千故反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_61_38","chapterId":"ch_work_han_thu_61","textTraditional":"其後人有盜高廟座前玉環，得，〔一〕文帝怒，下廷尉治。案盜宗廟服御物者為奏，當棄市。上大怒曰：「人亡道，乃盜先帝器！吾屬廷尉者，欲致之族，而君以法奏之，〔二〕非吾所以共承宗廟意也。」〔三〕釋之免冠頓首謝曰：「法如是足也。且罪等，〔四〕然以逆順為基。今盜宗廟器而族之，有如萬分一，假令愚民取長陵一抔土，〔五〕陛下且何以加其法虖？」文帝與太后言之，乃許廷尉當。是時，中尉條侯周亞夫與梁相山都侯王恬（咸）〔啟〕見釋之持議平，乃結為親友。張廷尉繇此天下稱之。〔六〕","sentenceOrder":38},
  {"id":"s_work_han_thu_61_39","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　師古曰：「得者，盜環之人為吏所捕得也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_61_40","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　師古曰：「法謂常法。」","sentenceOrder":40},
  {"id":"s_work_han_thu_61_41","chapterId":"ch_work_han_thu_61","textTraditional":"〔三〕　師古曰：「共讀曰恭。」","sentenceOrder":41},
  {"id":"s_work_han_thu_61_42","chapterId":"ch_work_han_thu_61","textTraditional":"〔四〕　如淳曰：「俱死罪也，盜玉環不若盜長陵土之逆。」","sentenceOrder":42},
  {"id":"s_work_han_thu_61_43","chapterId":"ch_work_han_thu_61","textTraditional":"〔五〕　張晏曰：「不欲指言，故以取土喻也。」師古曰：「抔音步侯反，謂手掬之也，其字從手。不忍言毀徹，故止云取土耳。今學者讀抔為（抔）〔杯〕勺之（抔）〔杯〕，非也。（抔）〔杯〕非應盛土之物也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_61_44","chapterId":"ch_work_han_thu_61","textTraditional":"〔六〕　師古曰：「繇讀與由同。」","sentenceOrder":44},
  {"id":"s_work_han_thu_61_45","chapterId":"ch_work_han_thu_61","textTraditional":"文帝崩，景帝立，釋之恐，〔一〕稱疾。欲免去，懼大誅至；欲見，則未知何如。用王生計，卒見謝，景帝不過也。","sentenceOrder":45},
  {"id":"s_work_han_thu_61_46","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　師古曰：「以嘗劾帝不下司馬門。」","sentenceOrder":46},
  {"id":"s_work_han_thu_61_47","chapterId":"ch_work_han_thu_61","textTraditional":"王生者，善為黃老言，處士。嘗召居廷中，公卿盡會立，王生老人，曰「吾韤解」，〔一〕顧謂釋之：「為我結韤！」釋之跪而結之。〔二〕既已，人或讓王生：「獨柰何廷辱張廷尉如此？」王生曰：「吾老且賤，自度終亡益於張廷尉。廷尉方天下名臣，吾故聊使結韤，欲以重之。」諸公聞之，賢王生而重釋之。","sentenceOrder":47},
  {"id":"s_work_han_thu_61_48","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　師古曰：「韤音武伐反。」","sentenceOrder":48},
  {"id":"s_work_han_thu_61_49","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　師古曰：「結讀曰係。」","sentenceOrder":49},
  {"id":"s_work_han_thu_61_50","chapterId":"ch_work_han_thu_61","textTraditional":"釋之事景帝歲餘，為淮南相，猶尚以前過也。年老病卒。其子摯，字長公，官至大夫，免。以不能取容當世，故終身不仕。","sentenceOrder":50},
  {"id":"s_work_han_thu_61_51","chapterId":"ch_work_han_thu_61","textTraditional":"馮唐，祖父趙人也。父徙代。漢興徙安陵。唐以孝著，為郎中署長，〔一〕事文帝。帝輦過，問唐曰：「父老何自為郎？家安在？」〔二〕具以實言。文帝曰：「吾居代時，吾尚食監高祛數為我言趙將李齊之賢，戰於鉅鹿下。吾每飲食，意未嘗不在鉅鹿也。〔三〕父老知之乎？」唐對曰：「齊尚不如廉頗、李牧之為將也。」上曰：「何已？」〔四〕唐曰：「臣大父在趙時，為官帥將，〔五〕善李牧。臣父故為代相，善李齊，知其為人也。」上既聞廉頗、李牧為人，良說，〔六〕乃拊髀曰：〔七〕「嗟乎！吾獨不得廉頗、李牧為將，豈憂匈奴哉！」唐曰：「主臣！〔八〕陛下雖有廉頗、李牧，不能用也。」上怒，起入禁中。良久，召唐讓曰：「公眾辱我，獨亡間處虖？」〔九〕唐謝曰：「鄙人不知忌諱。」","sentenceOrder":51},
  {"id":"s_work_han_thu_61_52","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　鄭氏曰：「以至孝聞也。」師古曰：「以孝得為郎中，而為郎署之長也。著音竹助反。」","sentenceOrder":52},
  {"id":"s_work_han_thu_61_53","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　師古曰：「言年已老矣，何乃自為郎也？崔浩以為自，從也。從何為郎？此說非也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_61_54","chapterId":"ch_work_han_thu_61","textTraditional":"〔三〕　張晏曰：「每食念監所說李齊在鉅鹿時也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_61_55","chapterId":"ch_work_han_thu_61","textTraditional":"〔四〕　師古曰：「已猶耳。」","sentenceOrder":55},
  {"id":"s_work_han_thu_61_56","chapterId":"ch_work_han_thu_61","textTraditional":"〔五〕　師古曰：「大父，祖父也。帥音所類反。將音子亮反。」","sentenceOrder":56},
  {"id":"s_work_han_thu_61_57","chapterId":"ch_work_han_thu_61","textTraditional":"〔六〕　如淳曰：「良，善也。」師古曰：「說讀曰悅。聞頗、牧之善，帝意大悅。」","sentenceOrder":57},
  {"id":"s_work_han_thu_61_58","chapterId":"ch_work_han_thu_61","textTraditional":"〔七〕　師古曰：「髀音陛。」","sentenceOrder":58},
  {"id":"s_work_han_thu_61_59","chapterId":"ch_work_han_thu_61","textTraditional":"〔八〕　師古曰：「恐懼之言。解在陳平傳。」","sentenceOrder":59},
  {"id":"s_work_han_thu_61_60","chapterId":"ch_work_han_thu_61","textTraditional":"〔九〕　師古曰：「何不間隙之處而言。」","sentenceOrder":60},
  {"id":"s_work_han_thu_61_61","chapterId":"ch_work_han_thu_61","textTraditional":"當是時，匈奴新大入朝那，殺北地都尉卬。上以胡寇為意，乃卒復問唐曰：「公何以言吾不能用頗、牧也？」唐對曰：「臣聞上古王者遣將也，跪而推轂，曰：『闑以內寡人制之，闑以外將軍制之〔一〕；軍功爵賞，皆決於外，歸而奏之。』此非空言也。臣大父言李牧之為趙將居邊，軍市之租皆自用饗士，賞賜決於外，不從中覆也〔二〕。委任而責成功，故李牧乃得盡其知能，選車千三百乘，彀騎萬三千匹，〔三〕百金之士十萬，〔四〕是以北逐單于，破東胡，滅澹林，〔五〕西抑彊秦，南支韓、魏。當是時，趙幾伯。〔六〕後會趙王遷立，〔七〕其母倡也，〔八〕用郭開讒，而誅李牧，令顏聚代之。是以為秦所滅。今臣竊聞魏尚為雲中守，軍市租盡以給士卒，出私養錢，五日壹殺牛，〔九〕以饗賓客軍吏舍人，是以匈奴遠避，不近雲中之塞。虜嘗一入，尚帥車騎擊之，所殺甚眾。夫士卒盡家人子，起田中從軍，安知尺籍伍符？〔一０〕終日力戰，斬首捕虜，上功莫府，一言不相應，文吏以法繩之。其賞不行，吏奉法必用。愚以為陛下法太明，賞太輕，罰太重。且雲中守尚坐上功首虜差六級，陛下下之吏，削其爵，罰作之。繇此言之，〔一一〕陛下雖得李牧，不能用也。臣誠愚，觸忌諱，死罪！」文帝說。〔一二〕是日，令唐持節赦魏尚，復以為雲中守，而拜唐為車騎都尉，主中尉及郡國車士。〔一三〕","sentenceOrder":61},
  {"id":"s_work_han_thu_61_62","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　韋昭曰：「門中橛為闑。」師古曰：「音牛列反。」","sentenceOrder":62},
  {"id":"s_work_han_thu_61_63","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　師古曰：「覆謂覆白之也，音芳目反。」","sentenceOrder":63},
  {"id":"s_work_han_thu_61_64","chapterId":"ch_work_han_thu_61","textTraditional":"〔三〕　師古曰：「彀，張弩也，音遘。」","sentenceOrder":64},
  {"id":"s_work_han_thu_61_65","chapterId":"ch_work_han_thu_61","textTraditional":"〔四〕　服虔曰：「良士直百金也。」如淳曰：「黃金一斤直萬。言富家子弟可任使也。」師古曰：「百金喻其貴重耳。服說是也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_61_66","chapterId":"ch_work_han_thu_61","textTraditional":"〔五〕　鄭氏曰：「澹音擔石之擔。」如淳曰：「胡也。匈奴傳曰『晉北有澹林之胡，樓煩之戎也』。」師古曰：「澹音都甘反，又音談。」","sentenceOrder":66},
  {"id":"s_work_han_thu_61_67","chapterId":"ch_work_han_thu_61","textTraditional":"〔六〕　師古曰：「幾致於霸也。幾音鉅依反。伯讀曰霸。」","sentenceOrder":67},
  {"id":"s_work_han_thu_61_68","chapterId":"ch_work_han_thu_61","textTraditional":"〔七〕　蘇林曰：「趙幽王。」","sentenceOrder":68},
  {"id":"s_work_han_thu_61_69","chapterId":"ch_work_han_thu_61","textTraditional":"〔八〕　師古曰：「倡，樂家之女。」","sentenceOrder":69},
  {"id":"s_work_han_thu_61_70","chapterId":"ch_work_han_thu_61","textTraditional":"〔九〕　服虔曰：「私假錢也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_61_71","chapterId":"ch_work_han_thu_61","textTraditional":"〔一０〕李奇曰：「尺籍所以書軍令。伍符，軍士五五相保之符信也。」如淳曰：「漢軍法曰吏卒斬首，以尺籍書下縣移郡，令人故行，不行奪勞二歲。伍符亦什伍之符，要節度也。」師古曰：「家人子，謂庶人之家子也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_61_72","chapterId":"ch_work_han_thu_61","textTraditional":"〔一一〕師古曰：「繇讀與由同。」","sentenceOrder":72},
  {"id":"s_work_han_thu_61_73","chapterId":"ch_work_han_thu_61","textTraditional":"〔一二〕師古曰：「說讀曰悅。」","sentenceOrder":73},
  {"id":"s_work_han_thu_61_74","chapterId":"ch_work_han_thu_61","textTraditional":"〔一三〕服虔曰：「車戰之士也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_61_75","chapterId":"ch_work_han_thu_61","textTraditional":"十年，景帝立，以唐為楚相。武帝即位，求賢良，舉唐。唐時年九十餘，不能為官，乃以子遂為郎。遂字王孫，亦奇士。魏尚，槐里人也。","sentenceOrder":75},
  {"id":"s_work_han_thu_61_76","chapterId":"ch_work_han_thu_61","textTraditional":"汲黯字長孺，濮陽人也。其先有寵於古之衛君也。〔一〕至黯十世，世為卿大夫。以父任，孝景時為太子洗馬，〔二〕以嚴見憚。","sentenceOrder":76},
  {"id":"s_work_han_thu_61_77","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　文穎曰：「六國時衛弱，但稱君也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_61_78","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　孟康曰：「大臣任舉其子弟為官。」","sentenceOrder":78},
  {"id":"s_work_han_thu_61_79","chapterId":"ch_work_han_thu_61","textTraditional":"武帝即位，黯為謁者。東粵相攻，上使黯往視之。至吳而還，報曰：「粵人相攻，固其俗，不足以辱天子使者。」河內失火，燒千餘家，上使黯往視之。還報曰：「家人失火，屋比延燒，〔一〕不足憂。臣過河內，河內貧人傷水旱萬餘家，或父子相食，臣謹以便宜，持節發河內倉粟以振貧民。請歸節，伏矯制罪。」〔二〕上賢而釋之，遷為滎陽令。黯恥為令，稱疾歸田里。上聞，乃召為中大夫。以數切諫，不得久留內，遷為東海太守。","sentenceOrder":79},
  {"id":"s_work_han_thu_61_80","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　師古曰：「比，近也。言屋相近，故連延而燒也。比音頻寐反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_61_81","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　師古曰：「矯，託也，託奉制詔而行之。」","sentenceOrder":81},
  {"id":"s_work_han_thu_61_82","chapterId":"ch_work_han_thu_61","textTraditional":"黯學黃老言，治官民，好清靜，擇丞史任之，〔一〕責大指而已，不細苛。黯多病，臥閤內不出。歲餘，東海大治，稱之。上聞，召為主爵都尉，列於九卿。治務在無為而已，引大體，不拘文法。","sentenceOrder":82},
  {"id":"s_work_han_thu_61_83","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　如淳曰：「擇郡丞及史任之也。鄭當時為大司農，官屬丞史，亦是也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_61_84","chapterId":"ch_work_han_thu_61","textTraditional":"為人性倨，少禮，〔一〕面折，不能容人之過。合己者善待之，不合者弗能忍見，士亦以此不附焉。然好游俠，任氣節，行修潔。其諫，犯主之顏色。常慕傅伯、爰盎之為人。〔二〕善灌夫、鄭當時及宗正劉棄疾。亦以數直諫，不得久居位。","sentenceOrder":84},
  {"id":"s_work_han_thu_61_85","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　師古曰：「倨，簡傲也，音居庶反。」","sentenceOrder":85},
  {"id":"s_work_han_thu_61_86","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　應劭曰：「傅伯，梁人，為孝王將，素抗直也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_61_87","chapterId":"ch_work_han_thu_61","textTraditional":"是時，太后弟武安侯田蚡為丞相，中二千石拜謁，蚡弗為禮。黯見蚡，未嘗拜，揖之。上方招文學儒者，上曰吾欲云云，〔一〕黯對曰：「陛下內多欲而外施仁義，柰何欲效唐虞之治乎！」上怒，變色而罷朝。公卿皆為黯懼。上退，謂人曰：「甚矣，汲黯之戇也！」群臣或數黯，〔二〕黯曰：「天子置公卿輔弼之臣，寧令從諛承意，陷主於不誼虖？且已在其位，縱愛身，柰辱朝廷何！」","sentenceOrder":87},
  {"id":"s_work_han_thu_61_88","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　張晏曰：「所言欲施仁義也。」師古曰：「云云，猶言如此如此也。史略其辭耳。」","sentenceOrder":88},
  {"id":"s_work_han_thu_61_89","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　師古曰：「數，責之，音所具反。」","sentenceOrder":89},
  {"id":"s_work_han_thu_61_90","chapterId":"ch_work_han_thu_61","textTraditional":"黯多病，病且滿三月，上常賜告者數，終不瘉。〔一〕最後，嚴助為請告。上曰：「汲黯何如人也？」曰：「使黯任職居官，亡以瘉人，〔二〕然至其輔少主守成，雖自謂賁育弗能奪也。」〔三〕上曰：「然。古有社稷之臣，至如汲黯，近之矣。」","sentenceOrder":90},
  {"id":"s_work_han_thu_61_91","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　如淳曰：「杜欽所謂病滿賜告詔恩也。數者，非一也。」師古曰：「數音所角反。瘉與愈同。」","sentenceOrder":91},
  {"id":"s_work_han_thu_61_92","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　師古曰：「瘉，勝也，讀與愈同。」","sentenceOrder":92},
  {"id":"s_work_han_thu_61_93","chapterId":"ch_work_han_thu_61","textTraditional":"〔三〕　師古曰：「孟賁、夏育，皆古之勇士也。賁音奔。」","sentenceOrder":93},
  {"id":"s_work_han_thu_61_94","chapterId":"ch_work_han_thu_61","textTraditional":"大將軍青侍中，上踞廁視之。〔一〕丞相弘宴見，上或時不冠。至如見黯，不冠不見也。上嘗坐武帳，〔二〕黯前奏事，上不冠，望見黯，避帷中，使人可其奏。其見敬禮如此。","sentenceOrder":94},
  {"id":"s_work_han_thu_61_95","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　如淳曰：「廁，溷也。」孟康曰：「廁，床邊側也。」師古曰：「如說是也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_61_96","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　應劭曰：「武帳，織成帳為武士象也。」孟康曰：「今御武帳，置兵闌五兵於帳中也。」師古曰：「孟說是也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_61_97","chapterId":"ch_work_han_thu_61","textTraditional":"張湯以更定律令為廷尉，〔一〕黯質責湯於上前，〔二〕曰：「公為正卿，上不能褒先帝之功業，下不能化天下之邪心，安國富民，使囹圄空虛，何空取高皇帝約束紛更之為？〔三〕而公以此無種矣！」〔四〕黯時與湯論議，湯辯常在文深小苛，黯憤發，罵曰：「天下謂刀筆吏不可（謂）〔為〕公卿，果然。必湯也，令天下重足而立，仄目而視矣！」〔五〕","sentenceOrder":97},
  {"id":"s_work_han_thu_61_98","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　師古曰：「更，改也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_61_99","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　師古曰：「質，對之也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_61_100","chapterId":"ch_work_han_thu_61","textTraditional":"〔三〕　師古曰：「言何為乃紛亂而改更也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_61_101","chapterId":"ch_work_han_thu_61","textTraditional":"〔四〕　師古曰：「言當誅及子孫也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_61_102","chapterId":"ch_work_han_thu_61","textTraditional":"〔五〕　師古曰：「重累其足，言懼甚也。仄，古側字也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_61_103","chapterId":"ch_work_han_thu_61","textTraditional":"是時，漢方征匈奴，招懷四夷，黯務少事，間常言與胡和親，毋起兵。〔一〕上方鄉儒術，〔二〕尊公孫弘，及事益多，吏民巧。上分別文法，湯等數奏決讞以幸。而黯常毀儒，面觸弘等徒懷詐飾智以阿人主取容，而刀筆之吏專深文巧詆，〔三〕陷人於罔，以自為功。上愈益貴弘、湯，弘、湯心疾黯，雖上亦不說也，〔四〕欲誅之以事。〔五〕弘為丞相，乃言上曰：「右內史界部中多貴人宗室，難治，非素重臣弗能任，請徙黯為右內史。」數歲，官事不廢。","sentenceOrder":103},
  {"id":"s_work_han_thu_61_104","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　師古曰：「每因間隙而言也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_61_105","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":105},
  {"id":"s_work_han_thu_61_106","chapterId":"ch_work_han_thu_61","textTraditional":"〔三〕　師古曰：「詆，毀辱也，音丁禮反。」","sentenceOrder":106},
  {"id":"s_work_han_thu_61_107","chapterId":"ch_work_han_thu_61","textTraditional":"〔四〕　師古曰：「說讀曰悅。」","sentenceOrder":107},
  {"id":"s_work_han_thu_61_108","chapterId":"ch_work_han_thu_61","textTraditional":"〔五〕　師古曰：「以事致其罪而誅也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_61_109","chapterId":"ch_work_han_thu_61","textTraditional":"大將軍青既益尊，姊為皇后，然黯與亢禮。或說黯曰：「自天子欲令群臣下大將軍，〔一〕大將軍尊貴，誠重，君不可以不拜。」黯曰：「夫以大將軍有揖客，反不重耶？」〔二〕大將軍聞，愈賢黯，數請問以朝廷所疑，遇黯加於平日。","sentenceOrder":109},
  {"id":"s_work_han_thu_61_110","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　師古曰：「下音胡稼反。」","sentenceOrder":110},
  {"id":"s_work_han_thu_61_111","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　師古曰：「言能降貴以禮士，最為重也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_61_112","chapterId":"ch_work_han_thu_61","textTraditional":"淮南王謀反，憚黯，曰：「黯好直諫，守節死義；至說公孫弘等，如發蒙耳。」〔一〕","sentenceOrder":112},
  {"id":"s_work_han_thu_61_113","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　師古曰：「說音式銳反。」","sentenceOrder":113},
  {"id":"s_work_han_thu_61_114","chapterId":"ch_work_han_thu_61","textTraditional":"上既數征匈奴有功，黯言益不用。","sentenceOrder":114},
  {"id":"s_work_han_thu_61_115","chapterId":"ch_work_han_thu_61","textTraditional":"始黯列九卿矣，而公孫弘、張湯為小吏。及弘、湯稍貴，與黯同位，黯又非毀弘、湯。已而弘至丞相封侯，湯御史大夫，黯時丞史皆與同列，或尊用過之。黯褊心，不能無少望，〔一〕見上，言曰：「陛下用群臣如積薪耳，後來者居上。」黯罷，上曰：「人果不可以無學，觀汲黯之言，日益甚矣。」〔二〕","sentenceOrder":115},
  {"id":"s_work_han_thu_61_116","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　師古曰：「褊，陿也。望，怨也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_61_117","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　師古曰：「言其鄙俚也。或曰，積薪之言出曾子，故云不可無學也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_61_118","chapterId":"ch_work_han_thu_61","textTraditional":"居無何，匈奴渾邪王帥眾來降，〔一〕漢發車二萬乘。縣官亡錢，從民貰馬。〔二〕民或匿馬，馬不具。上怒，欲斬長安令。黯曰：「長安令亡罪，獨斬臣黯，民乃肯出馬。且匈奴畔其主而降漢，徐以縣次傳之，何至令天下騷動，罷中國，甘心夷狄之人乎！」〔三〕上默然。後渾邪王至，賈人與市者，坐當死五百餘人。黯入，請間，見高門，〔四〕曰：「夫匈奴攻當路塞，絕和親，中國舉兵誅之，死傷不可勝計，而費以鉅萬百數。〔五〕臣愚以為陛下得胡人，皆以為奴婢，賜從軍死者家；鹵獲，因與之，以謝天下，塞百姓之心。〔六〕今縱不能，渾邪帥數萬之眾來，虛府庫賞賜，發良民侍養，若奉驕子。愚民安知市買長安中而文吏繩以為闌出財物如邊關乎？〔七〕陛下縱不能得匈奴之贏以謝天下，〔八〕又以微文殺無知者五百餘人，臣竊為陛下弗取也。」上弗許，曰：「吾久不聞汲黯之言，今又復妄發矣。」後數月，黯坐小法，會赦，免官。於是黯隱於田園者數年。","sentenceOrder":118},
  {"id":"s_work_han_thu_61_119","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　師古曰：「渾音胡昆反。」","sentenceOrder":119},
  {"id":"s_work_han_thu_61_120","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　師古曰：「賒買也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_61_121","chapterId":"ch_work_han_thu_61","textTraditional":"〔三〕　師古曰：「罷讀曰疲。」","sentenceOrder":121},
  {"id":"s_work_han_thu_61_122","chapterId":"ch_work_han_thu_61","textTraditional":"〔四〕　晉灼曰：「三輔黃圖未央宮中有高門殿也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_61_123","chapterId":"ch_work_han_thu_61","textTraditional":"〔五〕　師古曰：「即數百鉅萬也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_61_124","chapterId":"ch_work_han_thu_61","textTraditional":"〔六〕　師古曰：「塞，滿也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_61_125","chapterId":"ch_work_han_thu_61","textTraditional":"〔七〕　應劭曰：「闌，妄也。律，胡市，吏民不得持兵器及鐵出關。雖於京師市買，其法一也。」臣瓚曰：「無符傳出入為闌也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_61_126","chapterId":"ch_work_han_thu_61","textTraditional":"〔八〕　師古曰：「贏，餘也，音弋成反。」","sentenceOrder":126},
  {"id":"s_work_han_thu_61_127","chapterId":"ch_work_han_thu_61","textTraditional":"會更立五銖錢，民多盜鑄錢者，楚地尤甚。上以為淮陽，楚地之郊也，〔一〕召黯拜為淮陽太守。黯伏謝不受印綬，詔數強予，然後奉詔。召上殿，黯泣曰：「臣自以為填溝壑，不復見陛下，〔二〕不意陛下復收之。臣常有狗馬之心，〔三〕今病，力〔四〕不能任郡事。臣願為中郎，出入禁闥，補過拾遺，臣之願也。」上曰：「君薄淮陽邪？吾今召君矣。〔五〕顧淮陽吏民不相得，〔六〕吾徒得君重，〔七〕臥而治之。」黯既辭，過大行李息，曰：「黯棄逐居郡，不得與朝廷議矣。〔八〕然御史大夫湯智足以距諫，詐足以飾非，非肯正為天下言，專阿主意。主意所不欲，因而毀之；主意所欲，因而譽之。好興事，舞文法，〔九〕內懷詐以御主心，外挾賊吏以為重。公列九卿不早言之何？〔一０〕公與之俱受其戮矣！」息畏湯，終不敢言。黯居郡如其故治，淮陽政清。後張湯敗，上聞黯與息言，抵息罪。令黯以諸侯相秩居淮陽。〔一一〕居淮陽十歲而卒。","sentenceOrder":127},
  {"id":"s_work_han_thu_61_128","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　師古曰：「郊謂交道衝要之處也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_61_129","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　師古曰：「填音大賢反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_61_130","chapterId":"ch_work_han_thu_61","textTraditional":"〔三〕　師古曰：「思報效。」","sentenceOrder":130},
  {"id":"s_work_han_thu_61_131","chapterId":"ch_work_han_thu_61","textTraditional":"〔四〕　師古曰：「力謂甚也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_61_132","chapterId":"ch_work_han_thu_61","textTraditional":"〔五〕　師古曰：「言後即召也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_61_133","chapterId":"ch_work_han_thu_61","textTraditional":"〔六〕　師古曰：「顧謂思念也。」","sentenceOrder":133},
  {"id":"s_work_han_thu_61_134","chapterId":"ch_work_han_thu_61","textTraditional":"〔七〕　師古曰：「徒，但也。重，威重也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_61_135","chapterId":"ch_work_han_thu_61","textTraditional":"〔八〕　師古曰：「與讀曰豫。」","sentenceOrder":135},
  {"id":"s_work_han_thu_61_136","chapterId":"ch_work_han_thu_61","textTraditional":"〔九〕　如淳曰：「舞猶弄也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_61_137","chapterId":"ch_work_han_thu_61","textTraditional":"〔一０〕師古曰：「言何不早言也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_61_138","chapterId":"ch_work_han_thu_61","textTraditional":"〔一一〕如淳曰：「諸侯王相在郡守上，秩真二千石。律，真二千石月得百五十斛，歲凡得千八百石耳。二千石月得百二十斛，歲凡得一千四百四十石耳。」","sentenceOrder":138},
  {"id":"s_work_han_thu_61_139","chapterId":"ch_work_han_thu_61","textTraditional":"卒後，上以黯故，官其弟仁至九卿，子偃至諸侯相。黯姊子司馬安亦少與黯為太子洗馬。安文深巧善宦，四至九卿，以河南太守卒。昆弟以安故，同時至二千石十人。濮陽段宏始事蓋侯信，〔一〕信任宏，〔二〕官亦再至九卿。然衛人仕者皆嚴憚汲黯，出其下。","sentenceOrder":139},
  {"id":"s_work_han_thu_61_140","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　服虔曰：「景帝王皇后兄也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_61_141","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　蘇林曰：「任，保舉。」","sentenceOrder":141},
  {"id":"s_work_han_thu_61_142","chapterId":"ch_work_han_thu_61","textTraditional":"鄭當時字莊，陳人也。其先鄭君嘗事項籍，籍死而屬漢。高祖令諸故項籍臣名籍，鄭君獨不奉詔。詔盡拜名籍者為大夫，而逐鄭君。鄭君死孝文時。","sentenceOrder":142},
  {"id":"s_work_han_thu_61_143","chapterId":"ch_work_han_thu_61","textTraditional":"當時以任俠自喜，脫張羽於阨，〔一〕聲聞梁楚間。孝景時，為太子舍人。每五日洗沐，常置驛馬長安諸郊，〔二〕請謝賓客，夜以繼日，至明旦，常恐不遍。當時好黃老言，其慕長者，如恐不稱〔三〕。自見年少官薄，然其知友皆大父行，天下有名之士也。〔四〕","sentenceOrder":143},
  {"id":"s_work_han_thu_61_144","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　服虔曰：「梁孝王將，楚相之弟也。」師古曰：「喜音許吏反。脫音佗活反。」","sentenceOrder":144},
  {"id":"s_work_han_thu_61_145","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　如淳曰：「郊，交道四通處也，以請賓客便。」臣瓚曰：「長安四面郊祀之處，閑靜可以請賓客也。」師古曰：「二說皆非也。此謂長安城外四面之郊耳。邑外謂之郊，近郊二十里。」","sentenceOrder":145},
  {"id":"s_work_han_thu_61_146","chapterId":"ch_work_han_thu_61","textTraditional":"〔三〕　師古曰：「恐不稱其意。」","sentenceOrder":146},
  {"id":"s_work_han_thu_61_147","chapterId":"ch_work_han_thu_61","textTraditional":"〔四〕　師古曰：「大父謂祖父。行音胡浪反。」","sentenceOrder":147},
  {"id":"s_work_han_thu_61_148","chapterId":"ch_work_han_thu_61","textTraditional":"武帝即位，當時稍遷為魯中尉，濟南太守，江都相，至九卿為右內史。以武安魏其時議，〔一〕貶秩為詹事，遷為大司農。","sentenceOrder":148},
  {"id":"s_work_han_thu_61_149","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　師古曰：「議田蚡及竇嬰事。」","sentenceOrder":149},
  {"id":"s_work_han_thu_61_150","chapterId":"ch_work_han_thu_61","textTraditional":"當時為大吏，戒門下：「客至，亡貴賤亡留門（下）者。」執賓主之禮，以其貴下人。性廉，又不治產，卬奉賜給諸公。〔一〕然其餽遺人，不過具器食。〔二〕每朝，候上間說，未嘗不言天下長者。〔三〕其推轂士及官屬丞史，誠有味其言也。〔四〕常引以為賢於己。未嘗名吏，與官屬言，若恐傷之。聞人之善言，進之上，唯恐後。山東諸公以此翕然稱鄭莊。","sentenceOrder":150},
  {"id":"s_work_han_thu_61_151","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　師古曰：「卬音牛向反。奉音扶用反。」","sentenceOrder":151},
  {"id":"s_work_han_thu_61_152","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　師古曰：「猶今言一盤食也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_61_153","chapterId":"ch_work_han_thu_61","textTraditional":"〔三〕　師古曰：「候天子間隙之時，其所稱說，皆言長者也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_61_154","chapterId":"ch_work_han_thu_61","textTraditional":"〔四〕　師古曰：「推轂，言薦舉人，如推轂之運轉也。有味者，其言甚美也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_61_155","chapterId":"ch_work_han_thu_61","textTraditional":"使視決河，自請治行五日。〔一〕上曰：「吾聞鄭莊行，千里不齎糧，治行者何也？」然當時在朝，常趨和承意，〔二〕不敢甚斥臧否。漢征匈奴，招四夷，天下費多，財用益屈。〔三〕當時為大司農，任人賓客僦，〔四〕入多逋負。司馬安淮陽太守，發其事，當時以此陷罪，贖為庶人。頃之，守長史。〔五〕遷汝南太守，數歲，以官卒。昆弟以當時故，至二千石者六七人。","sentenceOrder":155},
  {"id":"s_work_han_thu_61_156","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　如淳曰：「治行，謂莊嚴。」","sentenceOrder":156},
  {"id":"s_work_han_thu_61_157","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　師古曰：「趨讀曰趣。趣，向也。和音胡臥反。」","sentenceOrder":157},
  {"id":"s_work_han_thu_61_158","chapterId":"ch_work_han_thu_61","textTraditional":"〔三〕　師古曰：「屈，盡也，音其勿反。」","sentenceOrder":158},
  {"id":"s_work_han_thu_61_159","chapterId":"ch_work_han_thu_61","textTraditional":"〔四〕　晉灼曰：「當時為大司農，而任使其賓客辜較作僦也。」師古曰：「僦謂受顧賃而載運也。言當時保任其賓客於司農載運也。僦音子就反。」","sentenceOrder":159},
  {"id":"s_work_han_thu_61_160","chapterId":"ch_work_han_thu_61","textTraditional":"〔五〕　如淳曰：「丞相長史也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_61_161","chapterId":"ch_work_han_thu_61","textTraditional":"當時始與汲黯列為九卿，內行修。兩人中廢，賓客益落。〔一〕當時死，家亡餘財。","sentenceOrder":161},
  {"id":"s_work_han_thu_61_162","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　師古曰：「落，散也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_61_163","chapterId":"ch_work_han_thu_61","textTraditional":"先是下邽翟公為廷尉，〔一〕賓客亦填門，〔二〕及廢，門外可設爵羅。〔三〕後復為廷尉，客欲往，翟公大署其門〔四〕曰：「一死一生，乃知交情；一貧一富，乃知交態；一貴一賤，交情乃見。」〔五〕","sentenceOrder":163},
  {"id":"s_work_han_thu_61_164","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　蘇林曰：「邽音圭，京兆縣名也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_61_165","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　師古曰：「填，滿也，音田。」","sentenceOrder":165},
  {"id":"s_work_han_thu_61_166","chapterId":"ch_work_han_thu_61","textTraditional":"〔三〕　師古曰：「言其寂靜，無人行也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_61_167","chapterId":"ch_work_han_thu_61","textTraditional":"〔四〕　師古曰：「署謂書之。」","sentenceOrder":167},
  {"id":"s_work_han_thu_61_168","chapterId":"ch_work_han_thu_61","textTraditional":"〔五〕　師古曰：「見音胡電反。」","sentenceOrder":168},
  {"id":"s_work_han_thu_61_169","chapterId":"ch_work_han_thu_61","textTraditional":"贊曰：張釋之之守法，馮唐之論將，汲黯之正直，鄭當時之推士，不如是，亦何以成名哉！揚子以為孝文親詘帝尊以信亞夫之軍〔一〕，曷為不能用頗、牧？彼將有激云爾。〔二〕","sentenceOrder":169},
  {"id":"s_work_han_thu_61_170","chapterId":"ch_work_han_thu_61","textTraditional":"〔一〕　師古曰：「揚子，謂揚雄也。信讀曰伸。」","sentenceOrder":170},
  {"id":"s_work_han_thu_61_171","chapterId":"ch_work_han_thu_61","textTraditional":"〔二〕　師古曰：「謂馮唐欲理魏尚，故以此言激文帝也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_61_172","chapterId":"ch_work_han_thu_61","textTraditional":"校勘記","sentenceOrder":172},
  {"id":"s_work_han_thu_61_173","chapterId":"ch_work_han_thu_61","textTraditional":"二三０八頁一二行　嚮讀曰（嚮）〔響〕，　景祐、殿本都作「響」，此誤。","sentenceOrder":173},
  {"id":"s_work_han_thu_61_174","chapterId":"ch_work_han_thu_61","textTraditional":"二三一一頁　九行　王恬（咸）〔啟〕　殿本作「啟」。王念孫說「咸」字誤。","sentenceOrder":174},
  {"id":"s_work_han_thu_61_175","chapterId":"ch_work_han_thu_61","textTraditional":"二三一一頁一六行　今學者讀抔為（抔）〔杯〕勺之（抔）〔杯〕，非也。（抔）〔杯〕非應盛土之物也。　殿本作「杯」，景祐本作「桮」。則是「桮」之誤。","sentenceOrder":175},
  {"id":"s_work_han_thu_61_176","chapterId":"ch_work_han_thu_61","textTraditional":"二三一八頁一０行　天下謂刀筆吏不可（謂）〔為〕公卿，果然。　景祐、殿本都作「為」。","sentenceOrder":176},
  {"id":"s_work_han_thu_61_177","chapterId":"ch_work_han_thu_61","textTraditional":"二三二一頁一五行　今病，力〔四〕不能任郡事。　注〔四〕在「力」字下，明顏讀「今病力」為句。周壽昌說「力」字屬下句讀似較順。王先謙說周說是。","sentenceOrder":177},
  {"id":"s_work_han_thu_61_178","chapterId":"ch_work_han_thu_61","textTraditional":"二三二四頁　七行　亡貴賤亡留門（下）者。　宋祁說邵本無「下」字。按景祐本無「下」字，史記同。","sentenceOrder":178},
  {"id":"s_work_han_thu_62_1","chapterId":"ch_work_han_thu_62","textTraditional":"賈山，潁川人也。祖父（祛）〔袪〕，故魏王時博士弟子也〔一〕。山受學（祛）〔袪〕，所言涉獵書記，不能為醇儒。〔二〕嘗給事潁陰侯為騎。〔三〕","sentenceOrder":1},
  {"id":"s_work_han_thu_62_2","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「六國時魏也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_62_3","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「涉若涉水，獵若獵獸，言歷覽之不專精也。醇者，不雜也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_62_4","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「為騎者，常騎馬而從也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_62_5","chapterId":"ch_work_han_thu_62","textTraditional":"孝文時，言治亂之道，借秦為諭，名曰至言。其辭曰：","sentenceOrder":5},
  {"id":"s_work_han_thu_62_6","chapterId":"ch_work_han_thu_62","textTraditional":"臣聞為人臣者，盡忠竭愚，以直諫主，不避死亡之誅者，臣山是也。臣不敢以久遠諭，願借秦以為諭，唯陛下少加意焉。","sentenceOrder":6},
  {"id":"s_work_han_thu_62_7","chapterId":"ch_work_han_thu_62","textTraditional":"夫布衣韋帶之士，〔一〕修身於內，成名於外，而使後世不絕息。至秦則不然。貴為天子，富有天下，賦斂重數，百姓任罷〔二〕，赭衣半道，群盜滿山，〔三〕使天下之人戴目而視，傾耳而聽。〔四〕一夫大謼，天下嚮應者，陳勝是也。〔五〕秦非徒如此也，起咸陽而西至雍，離宮三百，〔六〕鍾鼓帷帳，不移而具。又為阿房之殿，殿高數十仞，〔七〕東西五里，南北千步，從車羅騎，四馬騖馳，旌旗不橈。〔八〕為宮室之麗至於此，使其後世曾不得聚廬而託處焉。為馳道於天下，東窮燕齊，南極吳楚，江湖之上，瀕海之觀畢至。〔九〕道廣五十步，三丈而樹，厚築其外，隱以金椎，〔一０〕樹以青松。為馳道之麗至於此，使其後世曾不得邪徑而託足焉。死葬乎驪山，吏徒數十萬人，〔一一〕曠日十年。〔一二〕下徹三泉〔一三〕合采金石，冶銅錮其內，桼塗其外，〔一四〕被以珠玉，飾以翡翠，〔一五〕中成觀游，上成山林。為葬薶之侈至於此，使其後世曾不得蓬顆蔽冢而託葬焉。〔一六〕秦以熊羆之力，虎狼之心，蠶食諸侯，并吞海內，而不篤禮義，〔一七〕故天殃已加矣。臣昧死以聞，願陛下少留意而詳擇其中。〔一八〕","sentenceOrder":7},
  {"id":"s_work_han_thu_62_8","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「言貧賤之人也。韋帶，以單韋為帶，無飾也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_62_9","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「數，屢也。任謂役事也。罷讀曰疲，言疲於役使也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_62_10","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「犯罪者則衣赭衣，行道之人半著赭衣，言被罪者眾也。盜賊皆依山為阻，故云滿山也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_62_11","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「戴目者，言常遠視，有異志也。傾耳而聽，言樂禍亂也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_62_12","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　師古曰：「謼字與呼同。謼，叫也，音火故反。嚮讀曰響。」","sentenceOrder":12},
  {"id":"s_work_han_thu_62_13","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　師古曰：「（此）〔凡〕言離宮者，皆謂於別處置之，非常所居也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_62_14","chapterId":"ch_work_han_thu_62","textTraditional":"〔七〕　師古曰：「阿房者，言殿之四阿皆為房也。一說大陵曰阿，言其殿高若於阿上為房也。房字或作旁，說云始皇作此殿，未有名，以其去咸陽近，且號阿旁。阿，近也。八尺曰仞。」","sentenceOrder":14},
  {"id":"s_work_han_thu_62_15","chapterId":"ch_work_han_thu_62","textTraditional":"〔八〕　師古曰：「橈，屈也。言庭之廣大，殿之高敞，眾騎馳騖無所迫觸，建立旌旗不屈橈。橈音女孝反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_62_16","chapterId":"ch_work_han_thu_62","textTraditional":"〔九〕　師古曰：「瀕，水涯也。瀕海，謂緣海之邊也。畢，盡也。瀕音頻，又音賓，字或作濱，音義同。」","sentenceOrder":16},
  {"id":"s_work_han_thu_62_17","chapterId":"ch_work_han_thu_62","textTraditional":"〔一０〕服虔曰：「作壁如甬道。隱築也，以鐵椎築之。」師古曰：「築令堅實而使隆高耳，不為甬壁也。隱音於靳反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_62_18","chapterId":"ch_work_han_thu_62","textTraditional":"〔一一〕師古曰：「吏以督領，徒以役作也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_62_19","chapterId":"ch_work_han_thu_62","textTraditional":"〔一二〕師古曰：「曠，空也，廢也。言為重役，空廢時日，積年歲也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_62_20","chapterId":"ch_work_han_thu_62","textTraditional":"〔一三〕師古曰：「三重之泉，言其深也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_62_21","chapterId":"ch_work_han_thu_62","textTraditional":"〔一四〕師古曰：「錮謂鑄而合之也，音固。」","sentenceOrder":21},
  {"id":"s_work_han_thu_62_22","chapterId":"ch_work_han_thu_62","textTraditional":"〔一五〕應劭曰：「雄曰翡，雌曰翠。」臣瓚曰：「異物志云翡色赤而大於翠。」師古曰：「鳥各別類，非雄雌異名也。被音皮義反。」","sentenceOrder":22},
  {"id":"s_work_han_thu_62_23","chapterId":"ch_work_han_thu_62","textTraditional":"〔一六〕服虔曰：「謂塊墣作冢，喻小也。」臣瓚曰：「蓬顆，猶裸顆小冢也。」晉灼曰：「東北人名土塊為蓬顆。」師古曰：「諸家之說皆非。顆謂土塊。蓬顆，言塊上生蓬者耳。舉此以對冢上山林，故言蓬顆蔽冢也。顆音口果反。」","sentenceOrder":23},
  {"id":"s_work_han_thu_62_24","chapterId":"ch_work_han_thu_62","textTraditional":"〔一七〕師古曰：「篤，厚也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_62_25","chapterId":"ch_work_han_thu_62","textTraditional":"〔一八〕師古曰：「中音竹仲反。」","sentenceOrder":25},
  {"id":"s_work_han_thu_62_26","chapterId":"ch_work_han_thu_62","textTraditional":"臣聞忠臣之事君也，言切直則不用而身危，不切直則不可以明道，故切直之言，明主所欲急聞，忠臣之所以蒙死而竭知也。〔一〕地之磽者，雖有善種，不能生焉；〔二〕江皋河瀕，雖有惡種，無不猥大。〔三〕昔者夏商之季世，雖關龍逢、箕子、比干之賢，身死亡而道不用。〔四〕文王之時，豪俊之士皆得竭其智，芻蕘採薪之人皆得盡其力，〔五〕此周之所以興也。故地之美者善養禾，君之仁者善養士。雷霆之所擊，無不摧折者；〔六〕萬鈞之所壓，無不糜滅者。今人主之威，非特雷霆也；〔七〕勢重，非特萬鈞也。開道而求諫，和顏色而受之，用其言而顯其身，士猶恐懼而不敢自盡，又乃況於縱欲恣行暴虐，惡聞其過乎！震之以威，壓之以重，〔八〕則雖有堯舜之智，孟賁之勇，豈有不摧折者哉？〔九〕如此，則人主不得聞其過失矣；弗聞，則社稷危矣。古者聖王之制，史在前書過失，工誦箴諫，〔一０〕瞽誦詩諫，〔一一〕公卿比諫，〔一二〕士傳言諫（過），庶人謗於道，商旅議於市，〔一三〕然後君得聞其過失也。聞其過失而改之，見義而從之，所以永有天下也。天子之尊，四海之內，其義莫不為臣。然而養三老於大學，親執醬而餽，執爵而酳，〔一四〕祝〈〈食訇〉，中“言改吉”〉在前，祝鯁在後，〔一五〕公卿奉杖，大夫進履，舉賢以自輔弼，求修正之士使直諫。〔一六〕故以天子之尊，尊養三老，視孝也；〔一七〕立輔弼之臣者，恐驕也；置直諫之士者，恐不得聞其過也；學問至於芻蕘者，求善無饜也；商人庶人誹謗己而改之，從善無不聽也。","sentenceOrder":26},
  {"id":"s_work_han_thu_62_27","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「蒙，冒犯也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_62_28","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「磽，埆，瘠薄也。磽音口交反。」","sentenceOrder":28},
  {"id":"s_work_han_thu_62_29","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　李奇曰：「皋，水邊淤地也。」師古曰：「猥，盛也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_62_30","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　服虔曰：「關龍逢，桀之忠臣也。」師古曰：「比干諫紂而紂殺之。論語曰『微子去之，箕子為之奴，比干諫而死。』」","sentenceOrder":30},
  {"id":"s_work_han_thu_62_31","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　師古曰：「芻，刈草也。蕘，草薪也。言執賤役者也。大雅板之詩曰『詢于芻蕘』。」","sentenceOrder":31},
  {"id":"s_work_han_thu_62_32","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　師古曰：「霆，疾雷也，音廷。」","sentenceOrder":32},
  {"id":"s_work_han_thu_62_33","chapterId":"ch_work_han_thu_62","textTraditional":"〔七〕　師古曰：「特，獨也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_62_34","chapterId":"ch_work_han_thu_62","textTraditional":"〔八〕　師古曰：「震，動也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_62_35","chapterId":"ch_work_han_thu_62","textTraditional":"〔九〕　師古曰：「孟賁，古之勇士。賁音奔。」","sentenceOrder":35},
  {"id":"s_work_han_thu_62_36","chapterId":"ch_work_han_thu_62","textTraditional":"〔一０〕李奇曰：「古有誦詩之工，記過之史，常在君側也。」師古曰：「箴，戒也，音之林反。」","sentenceOrder":36},
  {"id":"s_work_han_thu_62_37","chapterId":"ch_work_han_thu_62","textTraditional":"〔一一〕師古曰：「瞽，無目之人。」","sentenceOrder":37},
  {"id":"s_work_han_thu_62_38","chapterId":"ch_work_han_thu_62","textTraditional":"〔一二〕李奇曰：「相親比而諫也，或曰比方事類以諫也。」師古曰：「比方是也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_62_39","chapterId":"ch_work_han_thu_62","textTraditional":"〔一三〕師古曰：「旅，眾也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_62_40","chapterId":"ch_work_han_thu_62","textTraditional":"〔一四〕師古曰：「餽字與饋同。進食曰餽。酳者，少少飲酒，謂食已而蕩口也，音胤。」","sentenceOrder":40},
  {"id":"s_work_han_thu_62_41","chapterId":"ch_work_han_thu_62","textTraditional":"〔一五〕師古曰：「〈〈食訇〉，中“言改吉”〉，古饐字，謂食不下也。以老人好饐鯁，故為備祝以祝之。」","sentenceOrder":41},
  {"id":"s_work_han_thu_62_42","chapterId":"ch_work_han_thu_62","textTraditional":"〔一六〕師古曰：「修正，謂修身正行者。」","sentenceOrder":42},
  {"id":"s_work_han_thu_62_43","chapterId":"ch_work_han_thu_62","textTraditional":"〔一七〕師古曰：「視讀曰示。」","sentenceOrder":43},
  {"id":"s_work_han_thu_62_44","chapterId":"ch_work_han_thu_62","textTraditional":"昔者，秦政力并萬國，富有天下，破六國以為郡縣，築長城以為關塞。秦地之固，大小之勢，輕重之權，其與一家之富，一夫之彊，胡可勝計也！〔一〕然而兵破於陳涉，地奪於劉氏者，何也？秦王貪狼暴虐，殘賊天下，窮困萬民，以適其欲也。〔二〕昔者，周蓋千八百國，以九州之民養千八百國之君，用民之力不過歲三日，什一而籍，〔三〕君有餘財，民有餘力，而頌聲作。〔四〕秦皇帝以千八百國之民自養，力罷不能勝其役，財盡不能勝其求。〔五〕一君之身耳，所以自養者馳騁弋獵之娛，天下弗能供也。〔六〕勞罷者不得休息，飢寒者不得衣食，亡罪而死刑者無所告訴，人與之為怨，家與之為讎，〔七〕故天下壞也。秦皇帝身在之時，天下已壞矣，而弗自知也。秦皇帝東巡狩，至會稽、琅邪，刻石著其功，自以為過堯舜統；〔八〕縣石鑄鍾虡，〔九〕篩土築阿房之宮，〔一０〕自以為萬世有天下也。古者聖王作諡，三四十世耳，雖堯舜禹湯文武絫世廣德〔一一〕以為子孫基業，無過二三十世者也。〔一二〕秦皇帝曰死而以諡法，是父子名號有時相襲也，以一至萬，則世世不相復也，〔一三〕故死而號曰始皇帝，其次曰二世皇帝者，欲以一至萬也。秦皇帝計其功德，度其後嗣，世世無窮，〔一四〕然身死纔數月耳，〔一五〕天下四面而攻之，宗廟滅絕矣。","sentenceOrder":44},
  {"id":"s_work_han_thu_62_45","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「胡，何也。勝，盡也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_62_46","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「適，快也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_62_47","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「什一，謂十分之中公取一也。籍，借也，謂借人力也。一曰為簿籍而稅之。」","sentenceOrder":47},
  {"id":"s_work_han_thu_62_48","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「頌者，六詩之一，美盛德之形容，蓋帝王之嘉致。」","sentenceOrder":48},
  {"id":"s_work_han_thu_62_49","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　師古曰：「勝，堪也。罷讀曰疲。次下亦同。」","sentenceOrder":49},
  {"id":"s_work_han_thu_62_50","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　師古曰：「弋，繳射也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_62_51","chapterId":"ch_work_han_thu_62","textTraditional":"〔七〕　師古曰：「言人人為怨，家家為讎。」","sentenceOrder":51},
  {"id":"s_work_han_thu_62_52","chapterId":"ch_work_han_thu_62","textTraditional":"〔八〕　如淳曰：「統，繼也。堯舜子不才，不能長世，而秦自以過堯舜，可至萬世也。」師古曰：「此說非也。統，治也。言自美功德，治理天下過於堯舜也。其下乃言一至萬之事。」","sentenceOrder":52},
  {"id":"s_work_han_thu_62_53","chapterId":"ch_work_han_thu_62","textTraditional":"〔九〕　服虔曰：「縣石以為磬也。」蘇林曰：「秦欲平天下法，使輕重如石之在稱也。」師古曰：「二說皆非也。縣，稱也。石，百二十斤。稱銅鐵之斤石以鑄鍾虡，言其奢泰也。虡，猛獸之名，謂鍾鼓之柎飾為此獸。虡音鉅。」","sentenceOrder":53},
  {"id":"s_work_han_thu_62_54","chapterId":"ch_work_han_thu_62","textTraditional":"〔一０〕師古曰：「篩以竹簁為之。篩音師。簁音山爾反。」","sentenceOrder":54},
  {"id":"s_work_han_thu_62_55","chapterId":"ch_work_han_thu_62","textTraditional":"〔一一〕師古曰：「絫，古累字。」","sentenceOrder":55},
  {"id":"s_work_han_thu_62_56","chapterId":"ch_work_han_thu_62","textTraditional":"〔一二〕張晏曰：「夏十七世，殷三十一世，周三十六世。」","sentenceOrder":56},
  {"id":"s_work_han_thu_62_57","chapterId":"ch_work_han_thu_62","textTraditional":"〔一三〕師古曰：「復，重也，音扶目反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_62_58","chapterId":"ch_work_han_thu_62","textTraditional":"〔一四〕師古曰：「度音大各反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_62_59","chapterId":"ch_work_han_thu_62","textTraditional":"〔一五〕師古曰：「纔音財，暫也，淺也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_62_60","chapterId":"ch_work_han_thu_62","textTraditional":"秦皇帝居滅絕之中而不自知者何也？天下莫敢告也。其所以莫敢告者何也？亡養老之義，亡輔弼之臣，亡進諫之士，縱恣行誅，退誹謗之人，殺直諫之士，是以道諛媮合苟容，〔一〕比其德則賢於堯舜，課其功則賢於湯武，天下已潰而莫之告也。〔二〕詩曰：「匪言不能，胡此畏忌，聽言則對，譖言則退。」此之謂也。〔三〕又曰：「濟濟多士，文王以寧。」〔四〕天下未嘗亡士也，然而文王獨言以寧者何也？文王好仁則仁興，得士而敬之則士用，用之有禮義。","sentenceOrder":60},
  {"id":"s_work_han_thu_62_61","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「道讀曰導，導引主意於邪也。媮與偷同。」","sentenceOrder":61},
  {"id":"s_work_han_thu_62_62","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「水旁決曰潰，言天下之（壤）〔壞〕如水潰。」","sentenceOrder":62},
  {"id":"s_work_han_thu_62_63","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「此大雅桑柔之篇也。言賢者見事之是非，非不能分別言之，而不言者何也？此但畏忌犯顏得罪罰也。又言，言而見聽，則悉意答對；不見信受，則屏退也。今詩本云『聽言則對，誦言如醉』。說者又別為義，與此不同。」","sentenceOrder":63},
  {"id":"s_work_han_thu_62_64","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「此大雅文王之篇也。濟濟，多威儀也。此言文王以多士之故，能安天下也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_62_65","chapterId":"ch_work_han_thu_62","textTraditional":"故不致其愛敬，則不能盡其心；不能盡其心，則不能盡其力；不能盡其力，則不能成其功。故古之賢君於其臣也，尊其爵祿而親之；疾則臨視之亡數，〔一〕死則往弔哭之，臨其小斂大斂，已棺塗而後為之服錫衰麻絰，〔二〕而三臨其喪；未斂不飲酒食肉，未葬不舉樂，當宗廟之祭而死，為之廢樂。故古之君人者於其臣也，可謂盡禮矣；服法服，端容貌，正顏色，然後見之。故臣下莫敢不竭力盡死以報其上，功德立於後世，而令聞不忘也。〔三〕","sentenceOrder":65},
  {"id":"s_work_han_thu_62_66","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「言心實憂念之，不為禮飾也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_62_67","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「已棺，謂已大斂也。塗謂塗殯也。錫衰，十五升布，無事其縷者也。棺音工喚反。」","sentenceOrder":67},
  {"id":"s_work_han_thu_62_68","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「令，善也。聞謂聲之聞也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_62_69","chapterId":"ch_work_han_thu_62","textTraditional":"今陛下念思祖考，術追厥功，〔一〕圖所以昭光洪業休德，〔二〕使天下舉賢良方正之士，天下皆訢訢焉，〔三〕曰將興堯舜之道，三王之功矣。天下之士莫不精白以承休德。〔四〕今方正之士皆在朝廷矣，又選其賢者使為常侍諸吏，與之馳敺射獵，〔五〕一日再三出。臣恐朝廷之解弛，〔六〕百官之墮於事也，諸侯聞之，又必怠於政矣。","sentenceOrder":69},
  {"id":"s_work_han_thu_62_70","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「術亦作述。」","sentenceOrder":70},
  {"id":"s_work_han_thu_62_71","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「圖，謀也。休，美也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_62_72","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「訢讀與欣同。」","sentenceOrder":72},
  {"id":"s_work_han_thu_62_73","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「厲精而為潔白也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_62_74","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　師古曰：「敺與驅同。」","sentenceOrder":74},
  {"id":"s_work_han_thu_62_75","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　師古曰：「解讀曰懈。弛，放也，音式爾反。」","sentenceOrder":75},
  {"id":"s_work_han_thu_62_76","chapterId":"ch_work_han_thu_62","textTraditional":"陛下即位，親自勉以厚天下，損食膳，不聽樂，減外徭衛卒，止歲貢；省廄馬以賦縣傳，〔一〕去諸苑以賦農夫，出帛十萬餘匹以振貧民；禮高年，九十者一子不事，八十者二算不事；〔二〕賜天下男子爵，大臣皆至公卿；發御府金賜大臣宗族，亡不被澤者；赦罪人，憐其亡髮，賜之巾，憐其衣赭書其背，父子兄弟相見也〔三〕而賜之衣。平獄緩刑，天下莫不說喜。〔四〕是以元年膏雨降，五穀登，此天之所以相陛下也。〔五〕刑輕於它時而犯法者寡，衣食多於前年而盜賊少，此天下之所以順陛下也。〔六〕臣聞山東吏布詔令，民雖老羸〈隆，中“阝改疒”〉疾，扶杖而往聽之，願少須臾毋死，思見德化之成也。今功業方就，名聞方昭，四方鄉風，〔七〕今從豪俊之臣，方正之士，直與之日日獵射，擊兔伐狐，以傷大業，絕天下之望，臣竊悼之。詩曰：「靡不有初，鮮克有終。」〔八〕臣不勝大願，願少衰射獵，以夏歲二月，〔九〕定明堂，造太學，修先王之道。風行俗成，萬世之基定，然後唯陛下所幸耳。〔一０〕古者大臣不媟，〔一一〕故君子不常見其齊嚴之色，肅敬之容。〔一二〕大臣不得與宴游，〔一三〕方正修潔之士不得從射獵，使皆務其方以高其節，〔一四〕則群臣莫敢不正身修行，盡心以稱大禮。〔一五〕如此，則陛下之道尊敬，功業施於四海，垂於萬世子孫矣。誠不如此，則行日壞而榮日滅矣。夫士修之於家，而壞之於天子之廷，臣竊愍之。陛下與眾臣宴游，與大臣方正朝廷論議。夫游不失樂，朝不失禮，議不失計，軌事之大者也。〔一六〕","sentenceOrder":76},
  {"id":"s_work_han_thu_62_77","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「賦，給與也。傳音張戀反。」","sentenceOrder":77},
  {"id":"s_work_han_thu_62_78","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「一子不事，蠲其賦役。二算不事，免二口之算賦也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_62_79","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「衣音於既反。」","sentenceOrder":79},
  {"id":"s_work_han_thu_62_80","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「說讀曰悅。」","sentenceOrder":80},
  {"id":"s_work_han_thu_62_81","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　師古曰：「相，助也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_62_82","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　師古曰：「天下之人也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_62_83","chapterId":"ch_work_han_thu_62","textTraditional":"〔七〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":83},
  {"id":"s_work_han_thu_62_84","chapterId":"ch_work_han_thu_62","textTraditional":"〔八〕　師古曰：「此大雅蕩之詩也。言人初始皆庶幾於善道，而少有能終之者。」","sentenceOrder":84},
  {"id":"s_work_han_thu_62_85","chapterId":"ch_work_han_thu_62","textTraditional":"〔九〕　師古曰：「時以十月為歲首，則（為）〔謂〕夏正之二月為五月。今欲定制度，循於古法，故特云用夏歲二月也。夏音胡雅反。」","sentenceOrder":85},
  {"id":"s_work_han_thu_62_86","chapterId":"ch_work_han_thu_62","textTraditional":"〔一０〕師古曰：「言乃可恣意也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_62_87","chapterId":"ch_work_han_thu_62","textTraditional":"〔一一〕師古曰：「媟，狎也，音息列反。」","sentenceOrder":87},
  {"id":"s_work_han_thu_62_88","chapterId":"ch_work_han_thu_62","textTraditional":"〔一二〕師古曰：「見，顯示也，音胡電反。」","sentenceOrder":88},
  {"id":"s_work_han_thu_62_89","chapterId":"ch_work_han_thu_62","textTraditional":"〔一三〕師古曰：「安息曰宴。與讀曰豫。」","sentenceOrder":89},
  {"id":"s_work_han_thu_62_90","chapterId":"ch_work_han_thu_62","textTraditional":"〔一四〕師古曰：「方，道也。一曰方謂廉隅也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_62_91","chapterId":"ch_work_han_thu_62","textTraditional":"〔一五〕師古曰：「稱，副也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_62_92","chapterId":"ch_work_han_thu_62","textTraditional":"〔一六〕師古曰：「軌謂法度也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_62_93","chapterId":"ch_work_han_thu_62","textTraditional":"其後文帝除鑄錢令，山復上書諫，以為變先帝法，非是。又訟淮南王無大罪，宜急令反國。又言柴唐子為不善，足以戒。〔一〕章下詰責，〔二〕對以為「錢者，亡用器也，而可以易富貴。富貴者，人主之操柄也，〔三〕令民為之，是與人主共操柄，不可長也。」〔四〕其言多激切，善指事意，然終不加罰，所以廣諫爭之路也。其後復禁鑄錢云。","sentenceOrder":93},
  {"id":"s_work_han_thu_62_94","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　鄧展曰：「淮南傳棘蒲侯柴武太子柴奇與士伍開章謀反。」","sentenceOrder":94},
  {"id":"s_work_han_thu_62_95","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「以其所上之章，令有司詰問。」","sentenceOrder":95},
  {"id":"s_work_han_thu_62_96","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「操，持也，音千高反。」","sentenceOrder":96},
  {"id":"s_work_han_thu_62_97","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「長謂畜養也。言此事宜速禁絕，不可畜養。」","sentenceOrder":97},
  {"id":"s_work_han_thu_62_98","chapterId":"ch_work_han_thu_62","textTraditional":"鄒陽，齊人也。漢興，諸侯王皆自治民聘賢。吳王濞招致四方游士，陽與吳嚴忌、枚乘等俱仕吳，皆以文辯著名。久之，吳王以太子事怨望，稱疾不朝，陰有邪謀，陽奏書諫。為其事尚隱，惡指斥言，故先引秦為諭，因道胡、越、齊、趙、淮南之難，然後乃致其意。其辭曰：","sentenceOrder":98},
  {"id":"s_work_han_thu_62_99","chapterId":"ch_work_han_thu_62","textTraditional":"臣聞秦倚曲臺之宮，〔一〕懸衡天下，〔二〕畫地而不犯，兵加胡越；〔三〕至其晚節末路，張耳、陳勝連從兵之據，〔四〕以叩函谷，咸陽遂危。〔五〕何則？列郡不相親，萬室不相救也。今胡數涉北河之外，上覆飛鳥，下不見伏菟，〔六〕鬥城不休，救兵不止，死者相隨，輦車相屬，〔七〕轉粟流輸，千里不絕。何則？彊趙責於河間，〔八〕六齊望於惠后，〔九〕城陽顧於盧博，〔一０〕三淮南之心思墳墓。〔一一〕大王不憂，臣恐救兵之不專，〔一二〕胡馬遂進窺於邯鄲，越水長沙，還舟青陽。〔一三〕雖使梁并淮陽之兵，下淮東，越廣陵，以遏越人之糧，漢亦折西河而下，北守漳水，以輔大國，胡亦益進，越亦益深。此臣之所為大王患也。〔一四〕","sentenceOrder":99},
  {"id":"s_work_han_thu_62_100","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　應劭曰：「始皇帝所治處也，若漢家未央宮。」師古曰：「倚，恃也，音於綺反。」","sentenceOrder":100},
  {"id":"s_work_han_thu_62_101","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　服虔曰：「關西為衡。」應劭曰：「衡，平也。」如淳曰：「衡猶稱之（權）〔衡〕也，言其懸法度於其上也。」師古曰：「此說秦自以為威力彊固，非論平法也。下又言陳勝連從兵之據，則是說從橫之事耳。服釋是也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_62_102","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「畫地不犯者，法制之行也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_62_103","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「從音子容反。」","sentenceOrder":103},
  {"id":"s_work_han_thu_62_104","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　師古曰：「叩，擊也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_62_105","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　蘇林曰：「言胡來人馬之盛，揚塵上覆飛鳥，下不見伏菟也。一曰，覆，盡也。言上射飛鳥，下盡伏菟也。」師古曰：「覆，盡，是也，音芳目反。」","sentenceOrder":105},
  {"id":"s_work_han_thu_62_106","chapterId":"ch_work_han_thu_62","textTraditional":"〔七〕　師古曰：「屬，連也，音之欲反。」","sentenceOrder":106},
  {"id":"s_work_han_thu_62_107","chapterId":"ch_work_han_thu_62","textTraditional":"〔八〕　應劭曰：「趙幽王為呂后所幽死，文帝立其長子遂為趙王，取趙之河間立遂弟辟彊為河間王，至子哀王無嗣，國除，遂欲復還得河間。」","sentenceOrder":107},
  {"id":"s_work_han_thu_62_108","chapterId":"ch_work_han_thu_62","textTraditional":"〔九〕　孟康曰：「高后割齊濟南郡為呂（王）台奉邑，又割琅邪郡封營陵侯劉澤為琅邪王。文帝乃立悼惠王六子為王。言六齊不保今日之恩，而追怨惠帝與呂后也。一說惠帝二年悼惠王入朝，呂后欲鴆殺之，獻城陽郡，尊魯元公主，得免，六子以此怨之。」","sentenceOrder":108},
  {"id":"s_work_han_thu_62_109","chapterId":"ch_work_han_thu_62","textTraditional":"〔一０〕孟康曰：「城陽王喜也。喜父章與弟興居討諸呂有功，本當盡以趙地王章，梁地王興居。文帝聞其欲立齊王，更以二郡王之。章失職，歲餘薨。興居誅死。盧博，濟北王治處，喜顧念而怨也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_62_110","chapterId":"ch_work_han_thu_62","textTraditional":"〔一一〕張晏曰：「淮南厲王三子為三王，念其父見遷殺，思墓，欲報怨也。」師古曰：「三子為王，謂淮南、衡山、濟北也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_62_111","chapterId":"ch_work_han_thu_62","textTraditional":"〔一二〕孟康曰：「不專救漢也。」如淳曰：「皆自私怨宿忿，不能為吳也。若吳舉兵反，天子來討，謂四國但有意，不敢相救也。」師古曰：「二說皆非也。言諸國各有私怨，欲申其志，不肯專為吳，非不敢相救也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_62_112","chapterId":"ch_work_han_thu_62","textTraditional":"〔一三〕張晏曰：「青陽，地名。還舟，聚舟船也。言胡為趙難，越為吳難，不可恃也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_62_113","chapterId":"ch_work_han_thu_62","textTraditional":"〔一四〕應劭曰：「時趙王遂北連匈奴，吳王濞素事三越，故鄒陽微言胡越亦自受敵，救兵之不專也。胡馬故曰進，越水故曰深。」蘇林曰：「折，截也。陽知吳王陰連結齊、趙、淮南、胡、越，欲諫不敢指斥言，故陳胡、越之難，齊、趙之怨，微言梁并淮陽絕越人之糧，漢折西河以輔大國，以破難其計。欲隱其辭，故謬言胡益進，越益深，為大王患之，以錯亂其語，若吳為憂助漢者也。自此以下，乃致其意焉。」師古曰：「蘇說是。」","sentenceOrder":113},
  {"id":"s_work_han_thu_62_114","chapterId":"ch_work_han_thu_62","textTraditional":"臣聞交龍襄首奮翼，則浮雲出流，霧雨咸集。〔一〕聖王底節修德，則游談之士歸義思名。〔二〕今臣盡智畢議，易精極慮〔三〕，則無國不可奸；〔四〕飾固陋之心，則何王之門不可曳長裾乎？然臣所以歷數王之朝，背淮千里而自致者，非惡臣國而樂吳民也，竊高下風之行，尤說大王之義。〔五〕故願大王之無忽，察聽其志。","sentenceOrder":114},
  {"id":"s_work_han_thu_62_115","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「襄，舉也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_62_116","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「底，厲也，音指。」","sentenceOrder":116},
  {"id":"s_work_han_thu_62_117","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　如淳曰：「改易精思以極盡謀慮也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_62_118","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「奸音干。」","sentenceOrder":118},
  {"id":"s_work_han_thu_62_119","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　師古曰：「言在下風側聽，高尚美悅大王之行義也。說讀曰悅。」","sentenceOrder":119},
  {"id":"s_work_han_thu_62_120","chapterId":"ch_work_han_thu_62","textTraditional":"臣聞鷙鳥絫百，不如一鶚。〔一〕夫全趙之時，〔二〕武力鼎士袨服叢臺之下者一旦成市，〔三〕而不能止幽王之湛患。〔四〕淮南連山東之俠，死士盈朝，不能還厲王之西也。〔五〕然而計議不得，雖諸、賁不能安其位，亦明矣。〔六〕故願大王審畫而已。〔七〕","sentenceOrder":120},
  {"id":"s_work_han_thu_62_121","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　孟康曰：「鶚，大鵰也。」如淳曰：「鷙鳥比諸侯，鶚比天子。」師古曰：「鷙擊之鳥，鷹鸇之屬也。鶚自大鳥而鷙者耳，非鵰也。絫，古累字。鶚音愕。」","sentenceOrder":121},
  {"id":"s_work_han_thu_62_122","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　服虔曰：「全趙，趙未分之時。」","sentenceOrder":122},
  {"id":"s_work_han_thu_62_123","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「袨服，盛服也。鼎士，舉鼎之士也。叢臺，趙王之臺也，在邯鄲。袨音州縣之縣。」","sentenceOrder":123},
  {"id":"s_work_han_thu_62_124","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「幽王謂趙幽王友也。湛讀曰沈。沈患，言幽王為呂后所幽死。」","sentenceOrder":124},
  {"id":"s_work_han_thu_62_125","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　師古曰：「厲王，淮南厲王長也。西謂廢遷嚴道而死於雍也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_62_126","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　師古曰：「諸謂專諸，賁謂孟賁，皆古勇士也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_62_127","chapterId":"ch_work_han_thu_62","textTraditional":"〔七〕　師古曰：「畫，計也，音獲。」","sentenceOrder":127},
  {"id":"s_work_han_thu_62_128","chapterId":"ch_work_han_thu_62","textTraditional":"始孝文皇帝據關入立，寒心銷志，不明求衣。〔一〕自立天子之後，使東牟朱虛東褒義父之後，〔二〕深割嬰兒王之。〔三〕壤子王梁、代，〔四〕益以淮陽。卒仆濟北，囚弟於雍者，豈非象新垣平等哉！〔五〕今天子新據先帝之遺業，左規山東，右制關中，變權易勢，大臣難知。大王弗察，臣恐周鼎復起於漢，新垣過計於朝〔六〕，則我吳遺嗣，不可期於世矣。〔七〕高皇帝燒棧道，水章邯〔八〕，兵不留行，〔九〕收弊民之倦，東馳函谷，西楚大破。〔一０〕水攻則章邯以亡其城，陸擊則荊王以失其地，〔一一〕此皆國家之不幾者也。〔一二〕願大王孰察之。","sentenceOrder":128},
  {"id":"s_work_han_thu_62_129","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　張晏曰：「據函谷關立為天子，諸國聞文帝入關為之寒心散志也。求衣，夜索衣著，不及待明，意不安也。」臣瓚曰：「文帝入關而立，以天下多難，故乃寒心戰慄，未明而起。」師古曰：「瓚說是。」","sentenceOrder":129},
  {"id":"s_work_han_thu_62_130","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　應劭曰：「天下已定，文帝遣朱虛侯章東喻齊王，嘉其首舉兵，欲誅諸呂，猶春秋褒邾儀父也。」師古曰：「立天子，謂立為天子也。義讀曰儀。父讀曰甫。」","sentenceOrder":130},
  {"id":"s_work_han_thu_62_131","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　應劭曰：「封齊王六子為王，其中有小小嬰兒者，文帝於骨肉厚也。或曰，皇子武為代王，參為太原王，揖為梁王。」師古曰：「或說是也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_62_132","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　如淳曰：「文帝之二子。」晉灼曰：「揚雄方言『梁益之間，所愛謂其肥盛曰壤』。或曰，言深割嬰兒王之壤。壤，土也。壤字當上屬也。」師古曰：「或說非也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_62_133","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　應劭曰：「仆，僵仆也。濟北王興居反，見誅。囚弟於雍者，淮南王長有罪，見徙，死於雍。所以然者，坐二國有姦臣如新垣平等，勸王共反。」師古曰：「仆音赴。」","sentenceOrder":133},
  {"id":"s_work_han_thu_62_134","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　如淳曰：「新垣平詐言『鼎在泗水中，臣望東北汾陰有金寶氣，鼎其在乎？弗迎，則不至。』為吳計者，猶新垣平之言，周鼎終不可得也。」服虔曰：「過，誤也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_62_135","chapterId":"ch_work_han_thu_62","textTraditional":"〔七〕　師古曰：「言吳當絕滅無遺嗣也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_62_136","chapterId":"ch_work_han_thu_62","textTraditional":"〔八〕　應劭曰：「章邯為雍王，高祖以水灌其城，破之也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_62_137","chapterId":"ch_work_han_thu_62","textTraditional":"〔九〕　師古曰：「言無所稽留，不廢於行。」","sentenceOrder":137},
  {"id":"s_work_han_thu_62_138","chapterId":"ch_work_han_thu_62","textTraditional":"〔一０〕張晏曰：「項羽自號西楚霸王。」","sentenceOrder":138},
  {"id":"s_work_han_thu_62_139","chapterId":"ch_work_han_thu_62","textTraditional":"〔一一〕　如淳曰：「荊亦楚也，謂項羽敗走。」","sentenceOrder":139},
  {"id":"s_work_han_thu_62_140","chapterId":"ch_work_han_thu_62","textTraditional":"〔一二〕　應劭曰：「言不可庶幾也。」李奇曰：「不但幾微，乃著見也。或曰幾，危也。此數事於國家皆無危險之慮也。」師古曰：「言漢朝之安，諸侯不當妄起邪意。應說是也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_62_141","chapterId":"ch_work_han_thu_62","textTraditional":"吳王不內其言。","sentenceOrder":141},
  {"id":"s_work_han_thu_62_142","chapterId":"ch_work_han_thu_62","textTraditional":"是時，景帝少弟梁孝王貴盛，亦待士。於是鄒陽、枚乘、嚴忌知吳不可說，皆去之梁，從孝王游。","sentenceOrder":142},
  {"id":"s_work_han_thu_62_143","chapterId":"ch_work_han_thu_62","textTraditional":"陽為人有智略，忼慨不苟合，〔一〕介於羊勝、公孫詭之間〔二〕。勝等疾陽，惡之孝王。〔三〕孝王怒，下陽吏，將殺之。陽客游以讒見禽，恐死而負絫，〔四〕乃從獄中上書曰：","sentenceOrder":143},
  {"id":"s_work_han_thu_62_144","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「忼音口朗反。」","sentenceOrder":144},
  {"id":"s_work_han_thu_62_145","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「介謂間廁也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_62_146","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「惡謂讒毀也。其下亦同。」","sentenceOrder":146},
  {"id":"s_work_han_thu_62_147","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「絫音力瑞反。」","sentenceOrder":147},
  {"id":"s_work_han_thu_62_148","chapterId":"ch_work_han_thu_62","textTraditional":"臣聞忠無不報，信不見疑，臣常以為然，徒虛語耳。昔荊軻慕燕丹之義，白虹貫日，太子畏之；〔一〕衛先生為秦畫長平之事，太白食昴，昭王疑之。〔二〕夫精（誠）變天地而信不諭兩主，豈不哀哉！今臣盡忠竭誠，畢議願知，〔三〕左右不明，卒從吏訊，為世所疑。〔四〕是使荊軻、衛先生復起，而燕、秦不寤也。願大王孰察之。","sentenceOrder":148},
  {"id":"s_work_han_thu_62_149","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　應劭曰：「燕太子丹質於秦，始皇遇之無禮，丹亡去，厚養荊軻，令西刺秦王。其精誠感天，白虹為之貫日也。」如淳曰：「白虹，兵象，日為君，為燕丹表可克之兆。」師古曰：「精誠若斯，太子尚畏而不信也。太白食昴，義亦如之。」","sentenceOrder":149},
  {"id":"s_work_han_thu_62_150","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　蘇林曰：「白起為秦伐趙，破長平軍，欲遂滅趙，遣衛先生說昭王益兵糧，為應侯所害，事用不成。精誠上達於天，故太白為之食昴。昴，趙分也，將有兵，故太白食昴。食，干歷之也。」如淳曰：「太白，天之將軍。」","sentenceOrder":150},
  {"id":"s_work_han_thu_62_151","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　張晏曰：「盡其計議，願王知之。」","sentenceOrder":151},
  {"id":"s_work_han_thu_62_152","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「言左右不明者，不欲斥王也。訊謂鞫問也，音信。」","sentenceOrder":152},
  {"id":"s_work_han_thu_62_153","chapterId":"ch_work_han_thu_62","textTraditional":"昔玉人獻寶，楚王誅之；〔一〕李斯謁忠，胡亥極刑。〔二〕是以箕子陽狂，接輿避世，〔三〕恐遭此患也。願大王察玉人、李斯之意，而後楚王、胡亥之聽，〔四〕毋使臣為箕子、接輿所笑。臣聞比干剖心，子胥鴟夷，〔五〕臣始不信，乃今知之。願大王孰察，少加憐焉！","sentenceOrder":153},
  {"id":"s_work_han_thu_62_154","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　應劭曰：「卞和得玉璞，獻之武王，王示玉人，曰石也，刖其右足。武王歿，復獻文王，玉人復曰石也，刖其左足。至成王時，抱其璞哭於郊，乃使玉人攻之，果得寶玉也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_62_155","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　張晏曰：「李斯諫二世以正，而二世殺之，具五刑。」","sentenceOrder":155},
  {"id":"s_work_han_thu_62_156","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　張晏曰：「接輿，楚賢人，陽狂避世。」師古曰：「輿音弋於反。」","sentenceOrder":156},
  {"id":"s_work_han_thu_62_157","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「以謬聽為後。後猶下也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_62_158","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　應劭曰：「吳王取馬革為鴟夷，受子胥，沈之江。鴟夷，榼形。」師古曰：「鴟夷，即今之盛酒鴟夷幐。」","sentenceOrder":158},
  {"id":"s_work_han_thu_62_159","chapterId":"ch_work_han_thu_62","textTraditional":"語曰「有白頭如新，〔一〕傾蓋如故」。〔二〕何則？知與不知也。故樊於期逃秦之燕，藉荊軻首以奉丹事；〔三〕王奢去齊之魏，臨城自剄以卻齊而存魏。〔四〕夫王奢、樊於期非新於齊、秦而故於燕、魏也，所以去二國死兩君者，行合於志，慕義無窮也。是以蘇秦不信於天下，為燕尾生；〔五〕白圭戰亡六城，為魏取中山〔六〕。何則？誠有以相知也。蘇秦相燕，人惡之燕王，燕王按劍而怒，食以駃騠；〔七〕白圭顯於中山，〔八〕人惡之於魏文侯，文侯賜以夜光之璧。何則？兩主二臣，剖心析肝相信，〔九〕豈移於浮辭哉！〔一０〕","sentenceOrder":159},
  {"id":"s_work_han_thu_62_160","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　孟康曰：「初相識至白頭不相知。」","sentenceOrder":160},
  {"id":"s_work_han_thu_62_161","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　文穎曰：「傾蓋，猶交蓋駐車也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_62_162","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　張晏曰：「於期為秦將，被讒走之燕。始皇滅其家，又重購之。燕遣荊軻欲刺秦王，於期自刎首，令軻齎往。」師古曰：「之，往也。藉，假也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_62_163","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　孟康曰：「王奢，齊臣也，亡至魏。其後齊伐魏，奢登城謂齊將曰：『今君之來，不過以奢故也，義不苟生，以為魏累。』遂自剄也。」","sentenceOrder":163},
  {"id":"s_work_han_thu_62_164","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　服虔曰：「蘇秦於秦不出其信，於燕則出尾生之信也。」晉灼曰：「說齊宣王使還燕十城，又令閔王厚葬以弊齊，終死為燕也。」師古曰：「尾生，古之信士，守志亡軀，故以為喻。」","sentenceOrder":164},
  {"id":"s_work_han_thu_62_165","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　張晏曰：「白圭為中山將，亡六城，君欲殺之，亡入魏，魏文侯厚遇之，還拔中山。」","sentenceOrder":165},
  {"id":"s_work_han_thu_62_166","chapterId":"ch_work_han_thu_62","textTraditional":"〔七〕　孟康曰：「駃騠，駿馬也，生七日而超其母。敬重蘇秦，雖有讒謗，而更食以珍奇之味。」師古曰：「食讀曰飤。駃音決。騠音題。」","sentenceOrder":166},
  {"id":"s_work_han_thu_62_167","chapterId":"ch_work_han_thu_62","textTraditional":"〔八〕　師古曰：「以拔中山之功而尊顯也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_62_168","chapterId":"ch_work_han_thu_62","textTraditional":"〔九〕　師古曰：「析，分也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_62_169","chapterId":"ch_work_han_thu_62","textTraditional":"〔一０〕師古曰：「不以浮說而移心。」","sentenceOrder":169},
  {"id":"s_work_han_thu_62_170","chapterId":"ch_work_han_thu_62","textTraditional":"故女無美惡，入宮見妒；士無賢不肖，入朝見嫉。昔司馬喜臏腳於宋，卒相中山；〔一〕范睢拉脅折齒於魏，卒為應侯。〔二〕此二人者，皆信必然之畫，捐朋黨之私，挾孤獨之交，故不能自免於嫉妒之人也。〔三〕是以申徒狄蹈雍之河，〔四〕徐衍負石入海〔五〕。不容於世，義不苟取比周於朝以移主上之心。〔六〕故百里奚乞食於道路，繆公委之以政；〔七〕甯戚飯牛車下，桓公任之以國〔八〕。此二人者，豈素宦於朝，借譽於左右，然後二主用之哉？感於心，合於行，堅如膠桼，昆弟不能離，豈惑於眾口哉？故偏聽生姦，獨任成亂。昔魯聽季孫之說逐孔子，〔九〕宋任子冉之計囚墨翟。〔一０〕夫以孔、墨之辯，不能自免於讒諛，而二國以危。何則？眾口鑠金，積毀銷骨也。〔一一〕秦用戎人由余而伯中國，〔一二〕齊用越人子臧而彊威、宣。〔一三〕此二國豈係於俗，牽於世，繫奇偏之浮辭哉？公聽並觀，垂明當世。〔一四〕故意合則胡越為兄弟，由余、子臧是矣；不合則骨肉為讎敵，朱、象、管、蔡是矣。〔一五〕今人主誠能用齊、秦之明，後宋、魯之聽，則五伯不足侔，而三王易為也。〔一六〕","sentenceOrder":170},
  {"id":"s_work_han_thu_62_171","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　蘇林曰：「六國時人，被此刑也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_62_172","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　應劭曰：「魏人也。魏相魏齊疑其以國陰事告齊，乃掠笞數百，拉脅折齒。」師古曰：「後入秦為相，封為應侯。拉，摧也，音盧合反。」","sentenceOrder":172},
  {"id":"s_work_han_thu_62_173","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「言直道而行，不求朋黨之助，謂忠信必可恃也。畫，計也，音獲。」","sentenceOrder":173},
  {"id":"s_work_han_thu_62_174","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　服虔曰：「殷之末世（人）〔介士〕也。雍之河，雍州之河也。」師古曰：「雍者，河水溢出為小流也。言狄初因蹈雍，遂入大河也。爾雅曰『水自河出為雍』，又曰『江有沲，河有雍』。雍音於龍反。服虔曰雍州之河，非也。」","sentenceOrder":174},
  {"id":"s_work_han_thu_62_175","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　服虔曰：「周之末世人也。」師古曰：「負石者，欲速沈也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_62_176","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　師古曰：「比音頻寐反。」","sentenceOrder":176},
  {"id":"s_work_han_thu_62_177","chapterId":"ch_work_han_thu_62","textTraditional":"〔七〕　應劭曰：「虞人也，聞秦繆公賢，欲往干之，乏資，乞食以自致也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_62_178","chapterId":"ch_work_han_thu_62","textTraditional":"〔八〕　應劭曰：「齊桓公夜出迎客，甯戚疾擊其牛角，高歌曰：『南山矸，自石爛，生不逢堯與舜禪。短布單衣適至骭，從昏飯牛薄夜半，長夜曼曼何時旦！』桓公召與語，說之，以為大夫。」師古曰：「矸字與岸同。骭，脛也。薄，止也。骭音下諫反。曼音莫幹反。」","sentenceOrder":178},
  {"id":"s_work_han_thu_62_179","chapterId":"ch_work_han_thu_62","textTraditional":"〔九〕　師古曰：「季孫，魯大夫季桓子也，名斯。論語云『齊人歸女樂，季桓子受之，三日不朝，孔子行。』蓋桓子故使定公受齊之女樂，欲令去孔子也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_62_180","chapterId":"ch_work_han_thu_62","textTraditional":"〔一０〕文穎曰：「子冉，子罕也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_62_181","chapterId":"ch_work_han_thu_62","textTraditional":"〔一一〕師古曰：「美金見毀，眾共疑之，數被燒鍊，以至銷鑠。讒佞之人，肆其詐巧，離散骨肉，而不覺知。」","sentenceOrder":181},
  {"id":"s_work_han_thu_62_182","chapterId":"ch_work_han_thu_62","textTraditional":"〔一二〕師古曰：「伯讀曰霸。」","sentenceOrder":182},
  {"id":"s_work_han_thu_62_183","chapterId":"ch_work_han_thu_62","textTraditional":"〔一三〕師古曰：「齊之二王諡也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_62_184","chapterId":"ch_work_han_thu_62","textTraditional":"〔一四〕師古曰：「公聽，言不私也。並觀，所見齊同也。」","sentenceOrder":184},
  {"id":"s_work_han_thu_62_185","chapterId":"ch_work_han_thu_62","textTraditional":"〔一五〕師古曰：「朱，丹朱，堯子。象，舜弟。管、蔡，周之二叔也。」","sentenceOrder":185},
  {"id":"s_work_han_thu_62_186","chapterId":"ch_work_han_thu_62","textTraditional":"〔一六〕師古曰：「侔，等也。伯讀曰霸。」","sentenceOrder":186},
  {"id":"s_work_han_thu_62_187","chapterId":"ch_work_han_thu_62","textTraditional":"是以聖王覺寤，（損）〔捐〕子之之心，而不說田常之賢，〔一〕封比干之後，修孕婦之墓，〔二〕故功業覆於天下。〔三〕何則？欲善亡厭也。夫晉文親其讎，彊伯諸侯；齊桓用其仇，而一匡天下。〔四〕何則？慈仁殷勤，誠加於心，不可以虛辭借也。","sentenceOrder":187},
  {"id":"s_work_han_thu_62_188","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　應劭曰：「燕王噲賢其相子之，欲禪以燕國，國乃大亂。田常，陳恆也。齊簡公悅之，而殺簡公。今使人君去此心，則國家安全也。」師古曰：「說讀曰悅。」","sentenceOrder":188},
  {"id":"s_work_han_thu_62_189","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　應劭曰：「紂刳妊者，觀其胎產。」師古曰：「武王克商，反其故政，乃封修之。」","sentenceOrder":189},
  {"id":"s_work_han_thu_62_190","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「覆猶被也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_62_191","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　張晏曰：「寺人勃鞮為晉獻公逐文公，斬其袪。及文公即位，用其言以免呂郄之難。管仲射中桓公帶鉤，而用為相。」師古曰：「伯讀為霸。下皆類此。」","sentenceOrder":191},
  {"id":"s_work_han_thu_62_192","chapterId":"ch_work_han_thu_62","textTraditional":"至夫秦用商鞅之法，東弱韓、魏，立彊天下，卒車裂之〔一〕。越用大夫種之謀，禽勁吳而伯中國，遂誅其身。是以孫叔敖三去相而不悔，〔二〕於陵子仲辭三公為人灌園。〔三〕今人主誠能去驕傲之心，懷可報之意，披心腹，見情素，〔四〕墮肝膽，施德厚〔五〕，終與之窮達，無愛於士，〔六〕則桀之犬可使吠堯，跖之客可使刺由，〔七〕何況因萬乘之權，假聖王之資乎！然則〔荊〕軻湛七族，要離燔妻子，豈足為大王道哉！〔八〕","sentenceOrder":192},
  {"id":"s_work_han_thu_62_193","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「卒，終也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_62_194","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「叔敖三為楚相，而三去之。繒丘之封人謂之曰：『吾聞處官久者士妒之，祿厚者眾怨之，位尊者君恨之。今相國有此三者，而不得罪於楚之士眾，（仕）〔何〕也？』叔敖曰：『吾三相楚而（不）〔身〕愈卑，每益祿而施愈博，位滋尊而禮愈恭，是以不得罪於楚人也。』」","sentenceOrder":194},
  {"id":"s_work_han_thu_62_195","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「於陵，地名也。子仲，陳仲子也。其先與齊同族，兄載為齊相，仲子以為不義，乃將妻子適楚，居于於陵，自謂於陵子仲。楚王聞其賢，使使者持金百鎰聘之，欲以為相。仲子不許，遂夫妻相與逃，而為人灌園，終身不屈其節。」","sentenceOrder":195},
  {"id":"s_work_han_thu_62_196","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「見，顯示之也。素謂心所向也。」","sentenceOrder":196},
  {"id":"s_work_han_thu_62_197","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　師古曰：「墮，毀也，音火規反。」","sentenceOrder":197},
  {"id":"s_work_han_thu_62_198","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　師古曰：「無所吝惜也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_62_199","chapterId":"ch_work_han_thu_62","textTraditional":"〔七〕　應劭曰：「盜跖之客為其人使刺由。由，許由也。」師古曰：「此言被之以恩，則用命也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_62_200","chapterId":"ch_work_han_thu_62","textTraditional":"〔八〕　應劭曰：「荊軻為燕刺秦始皇，不成而死，其族坐之。湛，沒也。吳王闔閭欲殺王子慶忌，要離詐以罪亡，令吳王燔其妻子。要離走見慶忌，以劍刺之。」張晏曰：「七族，上至曾祖，下至曾孫。」師古曰：「此說云湛七族，無荊字也。尋諸史籍，荊軻無湛族之事，不知陽所云者定何人也。湛讀曰沈。」","sentenceOrder":200},
  {"id":"s_work_han_thu_62_201","chapterId":"ch_work_han_thu_62","textTraditional":"臣聞明月之珠，夜光之璧，以闇投人於道，眾莫不按劍相眄者。何則？無因而至前也。蟠木根柢，輪囷離奇，〔一〕而為萬乘器者，以左右先為之容也。〔二〕故無因而至前，雖出隨珠和璧，祗怨結而不見德；〔三〕有人先游，則枯木朽株，樹功而不忘。〔四〕今夫天下布衣窮居之士，身在貧羸，〔五〕雖蒙堯、舜之術，挾伊、管之辯，〔六〕懷龍逢、比干之意，而素無根柢之容，雖竭精神，欲開忠於當世之君，〔七〕則人主必襲按劍相眄之跡矣。〔八〕是使布衣之士不得為枯木（巧）〔朽〕株之資也。","sentenceOrder":201},
  {"id":"s_work_han_thu_62_202","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　蘇林曰：「柢音蔕。」張晏曰：「柢，根下本也。輪囷離奇，委曲盤戾也。」師古曰：「蟠木，屈曲之木也。囷音去輪反。離音力爾反。奇音於綺反。一曰離奇各讀如本字。」","sentenceOrder":202},
  {"id":"s_work_han_thu_62_203","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「萬乘器，天子車輿之屬也。容謂彫刻加飾。」","sentenceOrder":203},
  {"id":"s_work_han_thu_62_204","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「隨國之侯見大蛇傷者，療而愈之，蛇銜明珠以報其德，故稱隨珠。和氏之璧，即卞和所獻之玉耳。祗，適也，音支。」","sentenceOrder":204},
  {"id":"s_work_han_thu_62_205","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「先游，謂進納之也。樹，立也。」","sentenceOrder":205},
  {"id":"s_work_han_thu_62_206","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　師古曰：「衣食不充，故羸瘦也。一曰羸謂無威力。」","sentenceOrder":206},
  {"id":"s_work_han_thu_62_207","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　師古曰：「伊，伊尹。管，管仲。」","sentenceOrder":207},
  {"id":"s_work_han_thu_62_208","chapterId":"ch_work_han_thu_62","textTraditional":"〔七〕　師古曰：「開謂陳說也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_62_209","chapterId":"ch_work_han_thu_62","textTraditional":"〔八〕　師古曰：「襲，重也。言躡其故跡也。」","sentenceOrder":209},
  {"id":"s_work_han_thu_62_210","chapterId":"ch_work_han_thu_62","textTraditional":"是以聖王制世御俗，獨化於陶鈞之上，〔一〕而不牽乎卑辭之語，不奪乎眾多之口。〔二〕故秦皇帝任中庶子蒙〔嘉〕之言〔三〕，以信荊軻，而匕首竊發；〔四〕周文王獵涇渭，載呂尚歸，以王天下。〔五〕秦信左右而亡，周用烏集而王。〔六〕何則？以其能越攣拘之語，馳域外之議，〔七〕獨觀乎昭曠之道也。〔八〕","sentenceOrder":210},
  {"id":"s_work_han_thu_62_211","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　張晏曰：「陶家名模下圓轉者為鈞，以其制器為大小，比之於天也。」師古曰：「此說非也。陶家名轉者為鈞，蓋取周回調鈞耳。言聖王制馭天下，亦猶陶人轉鈞，非陶家轉象天也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_62_212","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「奪者，言欲行善道而為佞人奪其計也。」","sentenceOrder":212},
  {"id":"s_work_han_thu_62_213","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「蒙者，庶子名也。今流俗書本蒙下輒加恬字，非也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_62_214","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「匕首，短劍也。其首類匕，便於用也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_62_215","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　應劭曰：「西伯出遇呂尚於渭之陽，與語大悅，因載歸。」","sentenceOrder":215},
  {"id":"s_work_han_thu_62_216","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　師古曰：「言文王之得太公，非因舊故，若烏鳥之暴集。」","sentenceOrder":216},
  {"id":"s_work_han_thu_62_217","chapterId":"ch_work_han_thu_62","textTraditional":"〔七〕　師古曰：「攣音力全反。」","sentenceOrder":217},
  {"id":"s_work_han_thu_62_218","chapterId":"ch_work_han_thu_62","textTraditional":"〔八〕　師古曰：「昭，明也。曠，廣也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_62_219","chapterId":"ch_work_han_thu_62","textTraditional":"今人主沈諂諛之辭，牽帷廧之制，〔一〕使不羈之士與牛驥同皁，〔二〕此鮑焦所以憤於世也。〔三〕","sentenceOrder":219},
  {"id":"s_work_han_thu_62_220","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　孟康曰：「言為左右便僻侍帷廧臣妾所見牽制矣。」","sentenceOrder":220},
  {"id":"s_work_han_thu_62_221","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「不羈，言才識高遠不可羈係也。皁，歷也。揚雄方言云『梁、宋、齊、楚、燕之間謂歷曰皁』。皁音在早反。」","sentenceOrder":221},
  {"id":"s_work_han_thu_62_222","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　孟康曰：「周之介士也。」師古曰：「鮑焦怨時之不用己，采蔬於道。子貢難曰：『非其時而採其蔬，此焦之有哉？』棄其蔬，乃立枯於洛水之上。蔬謂菜也。」","sentenceOrder":222},
  {"id":"s_work_han_thu_62_223","chapterId":"ch_work_han_thu_62","textTraditional":"臣聞盛飾入朝者不以私汙義，底厲名號者不以利傷行。〔一〕故里名勝母，曾子不入；〔二〕邑號朝歌，墨子回車。〔三〕今欲使天下寥廓之士籠於威重之權，脅於位勢之貴，〔四〕回面汙行，以事諂諛之人，〔五〕而求親近於左右，則士有伏死堀穴巖藪之中耳，〔六〕安有盡忠信而趨闕下者哉！","sentenceOrder":223},
  {"id":"s_work_han_thu_62_224","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「底厲，言其自修廉隅，若磨厲於石也。」","sentenceOrder":224},
  {"id":"s_work_han_thu_62_225","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「曾子至孝，以勝母之名不順，故不入也。」","sentenceOrder":225},
  {"id":"s_work_han_thu_62_226","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　晉灼曰：「紂作朝歌之音。朝歌者，不時也。」師古曰：「朝歌，殷之邑名也。淮南子云『墨子非樂，不入朝歌』。」","sentenceOrder":226},
  {"id":"s_work_han_thu_62_227","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「寥廓，遠大之度也。脅，迫也。寥音聊。」","sentenceOrder":227},
  {"id":"s_work_han_thu_62_228","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　師古曰：「回，邪也。汙，不潔也，音一故反。或曰汙，曲也，音一胡反。」","sentenceOrder":228},
  {"id":"s_work_han_thu_62_229","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　師古曰：「堀與窟同。澤無水曰藪。」","sentenceOrder":229},
  {"id":"s_work_han_thu_62_230","chapterId":"ch_work_han_thu_62","textTraditional":"書奏孝王，孝王立出之，卒為上客。","sentenceOrder":230},
  {"id":"s_work_han_thu_62_231","chapterId":"ch_work_han_thu_62","textTraditional":"初，勝、詭欲使王求為漢嗣，王又嘗上書，願賜容車之地徑至長樂宮，自使梁國士眾築作甬道朝太后。爰盎等皆建以為不可。〔一〕天子不許。梁王怒，令人刺殺盎。上疑梁殺之，使者冠蓋相望責梁王。梁王始與勝、詭有謀，陽爭以為不可，故見讒。枚先生、嚴夫子皆不敢諫。〔二〕","sentenceOrder":231},
  {"id":"s_work_han_thu_62_232","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「建謂立議。」","sentenceOrder":232},
  {"id":"s_work_han_thu_62_233","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「先生，枚乘。夫子，嚴忌。」","sentenceOrder":233},
  {"id":"s_work_han_thu_62_234","chapterId":"ch_work_han_thu_62","textTraditional":"及梁事敗，勝、詭死，孝王恐誅，乃思陽言，深辭謝之，齎以千金，令求方略解罪於上者。陽素知齊人王先生，〔一〕年八十餘，多奇計，即往見，語以其事。王先生曰：「難哉！人主有私怨深怒，欲施必行之誅，誠難解也。以太后之尊，骨肉之親，猶不能止，況臣下乎？昔秦始皇有伏怒於太后，群臣諫而死者以十數。得茅焦為廓大義，〔二〕始皇非能說其言也，乃自強從之耳。〔三〕茅焦亦廑脫死如毛〈氂，中“未改牙”〉耳，〔四〕故事所以難者也。今子欲安之乎？」〔五〕陽曰：「鄒魯守經學，齊楚多辯知，韓魏時有奇節，吾將歷問之。」王先生曰：「子行矣。還，過我而西。」","sentenceOrder":234},
  {"id":"s_work_han_thu_62_235","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「素與相知也。」","sentenceOrder":235},
  {"id":"s_work_han_thu_62_236","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　鄭氏曰：「齊人也。」應劭曰：「茅焦諫云：『陛下車裂假父，有嫉妒之心；囊撲兩弟，有不慈之名；遷母咸陽，有不孝之行。臣竊為陛下危之。臣所言畢。』乃解衣趨鑊。始皇下殿，左手接之曰：『先生起矣！』即迎太后，遂為母子如初。」","sentenceOrder":236},
  {"id":"s_work_han_thu_62_237","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「說讀曰悅。」","sentenceOrder":237},
  {"id":"s_work_han_thu_62_238","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「廑，少也。言纔免於死也。廑音巨刃反。」","sentenceOrder":238},
  {"id":"s_work_han_thu_62_239","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　師古曰：「安，焉也。之，往也。」","sentenceOrder":239},
  {"id":"s_work_han_thu_62_240","chapterId":"ch_work_han_thu_62","textTraditional":"鄒陽行月餘，莫能為謀，還過王先生，曰：「臣將西矣，為如何？」王先生曰：「吾先日欲獻愚計，以為眾不可蓋，〔一〕竊自薄陋不敢道也。若子行，必往見王長君，士無過此者矣。」鄒陽發寤於心，曰：「敬諾。」辭去，不過梁，徑至長安，因客見王長君。長君者，王美人兄也，後封為蓋侯。鄒陽留數日，乘間而請曰：〔二〕「臣非為長君無使令於前，故來侍也；〔三〕愚戇竊不自料，願有謁也。」〔四〕長君跪曰：「幸甚。」陽曰：「竊聞長君弟得幸後宮，天下無有，〔五〕而長君行跡多不循道理者。今爰盎事即窮竟，梁王恐誅。如此，則太后怫鬱泣血，無所發怒，〔六〕切齒側目於貴臣矣。臣恐長君危於絫卵，〔七〕竊為足下憂之。」長君懼然曰：「將為之柰何？」〔八〕陽曰：「長君誠能精為上言之，得毋竟梁事，長君必固自結於太后。太后厚德長君，入於骨髓，而長君之弟幸於兩宮，〔九〕金城之固也。〔一０〕又有存亡繼絕之功，德布天下，名施無窮，願長君深自計之。昔者，舜之弟象日以殺舜為事，〔一一〕及舜立為天子，封之於有卑。〔一二〕夫仁人之於兄弟，無臧怒，無宿怨，厚親愛而已，是以後世稱之。魯公子慶父使僕人殺子般，〔一三〕獄有所歸，〔一四〕季友不探其情而誅焉；〔一五〕慶父親殺閔公，季子緩追免賊，〔一六〕春秋以為親親之道也。〔一七〕魯哀姜薨於夷，孔子曰『齊桓公法而不譎』，以為過也。〔一八〕以是說天子，徼幸梁事不奏。」長君曰：「諾。」乘間入而言之。及韓安國亦見長公主，事果得不治。","sentenceOrder":240},
  {"id":"s_work_han_thu_62_241","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「蓋，覆蔽也。」","sentenceOrder":241},
  {"id":"s_work_han_thu_62_242","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「間謂空隙無事之時。」","sentenceOrder":242},
  {"id":"s_work_han_thu_62_243","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「使令，謂役使之人也。令音力成反。」","sentenceOrder":243},
  {"id":"s_work_han_thu_62_244","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「料，量也。謁，告也。」","sentenceOrder":244},
  {"id":"s_work_han_thu_62_245","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　師古曰：「言獨一耳，無所比類也。」","sentenceOrder":245},
  {"id":"s_work_han_thu_62_246","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　師古曰：「怫鬱，蘊積也。怫音佛。」","sentenceOrder":246},
  {"id":"s_work_han_thu_62_247","chapterId":"ch_work_han_thu_62","textTraditional":"〔七〕　師古曰：「絫卵者，言其將隤而破碎也。」","sentenceOrder":247},
  {"id":"s_work_han_thu_62_248","chapterId":"ch_work_han_thu_62","textTraditional":"〔八〕　師古曰：「懼讀曰瞿，音居具反。瞿然，無守之貌。」","sentenceOrder":248},
  {"id":"s_work_han_thu_62_249","chapterId":"ch_work_han_thu_62","textTraditional":"〔九〕　如淳曰：「太后宮及帝宮也。」","sentenceOrder":249},
  {"id":"s_work_han_thu_62_250","chapterId":"ch_work_han_thu_62","textTraditional":"〔一０〕師古曰：「言其榮寵無極不可壞，故取喻於金城也。」","sentenceOrder":250},
  {"id":"s_work_han_thu_62_251","chapterId":"ch_work_han_thu_62","textTraditional":"〔一一〕師古曰：「言日日欲殺也。」","sentenceOrder":251},
  {"id":"s_work_han_thu_62_252","chapterId":"ch_work_han_thu_62","textTraditional":"〔一二〕服虔曰：「音畀予之畀也。」師古曰：「地名也，音鼻，今鼻亭是也，在零陵。」","sentenceOrder":252},
  {"id":"s_work_han_thu_62_253","chapterId":"ch_work_han_thu_62","textTraditional":"〔一三〕師古曰：「慶父，莊公弟也。子般，莊公太子也。僕人，即鄧扈樂也。父讀曰甫。般字與班同。」","sentenceOrder":253},
  {"id":"s_work_han_thu_62_254","chapterId":"ch_work_han_thu_62","textTraditional":"〔一四〕師古曰：「歸罪於鄧扈樂也。」","sentenceOrder":254},
  {"id":"s_work_han_thu_62_255","chapterId":"ch_work_han_thu_62","textTraditional":"〔一五〕師古曰：「季友，慶父之弟，不探慶父本情而誅扈樂。」","sentenceOrder":255},
  {"id":"s_work_han_thu_62_256","chapterId":"ch_work_han_thu_62","textTraditional":"〔一六〕師古曰：「慶父出奔，季友縱而不追，免其賊亂之罪。」","sentenceOrder":256},
  {"id":"s_work_han_thu_62_257","chapterId":"ch_work_han_thu_62","textTraditional":"〔一七〕師古曰：「公羊之說也，言季友親其兄也。」","sentenceOrder":257},
  {"id":"s_work_han_thu_62_258","chapterId":"ch_work_han_thu_62","textTraditional":"〔一八〕師古曰：「哀姜，莊公夫人也，淫於二叔，而豫殺閔公，齊人殺之於夷。夷，齊地也。法而不譎者，言守法而行，不能用權以免其親也。」","sentenceOrder":258},
  {"id":"s_work_han_thu_62_259","chapterId":"ch_work_han_thu_62","textTraditional":"初，吳王濞與七國謀反，及發，齊、濟北兩國城守不行。漢既破吳，齊王自殺，不得立嗣。濟北王亦欲自殺，幸全其妻子。齊人公孫玃謂濟北王曰：〔一〕「臣請試為大王明說梁王，通意天子，說而不用，死未晚也。」公孫玃遂見梁王，曰：「夫濟北之地，東接彊齊，南牽吳越，北脅燕趙，此四分五裂之國，〔二〕權不足以自守，勁不足以扞寇，〔三〕又非有奇怪云以待難也，〔四〕雖墜言於吳，非其正計也。〔五〕昔者鄭祭仲許宋人立公子突以活其君，非義也，春秋記之，為其以生易死，以存易亡也。〔六〕鄉使濟北見情實，示不從之端，〔七〕則吳必先歷齊畢濟北，〔八〕招燕、趙而總之。如此，則山東之從結而無隙矣。〔九〕今吳楚之王練諸侯之兵，敺白徒之眾，〔一０〕西與天子爭衡，濟北獨底節堅守不下。使吳失與而無助，跬步獨進，〔一一〕瓦解土崩，破敗而不救者，未必非濟北之力也。夫以區區之濟北而與諸侯爭彊，〔一二〕是以羔犢之弱而扞虎狼之敵也。守職不橈，可謂誠一矣。〔一三〕功義如此，尚見疑於上，脅肩低首，絫足撫衿，〔一四〕使有自悔不前之心，〔一五〕非社稷之利也。臣恐藩臣守職者疑之。臣竊料之，〔一六〕能歷西山，徑長樂，抵未央，攘袂而正議者，獨大王耳。〔一七〕上有全亡之功，下有安百姓之名，德淪於骨髓，〔一八〕恩加於無窮，願大王留意詳惟之。」〔一九〕孝王大說，〔二０〕使人馳以聞。濟北王得不坐，徙封於淄川。","sentenceOrder":259},
  {"id":"s_work_han_thu_62_260","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「玃音俱略反。」","sentenceOrder":260},
  {"id":"s_work_han_thu_62_261","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　張晏曰：「四方受敵，濟北居中央為五。」晉灼曰：「四分，即交五而裂，如田字也。」","sentenceOrder":261},
  {"id":"s_work_han_thu_62_262","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「扞，禦也，音胡旦反。」","sentenceOrder":262},
  {"id":"s_work_han_thu_62_263","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　如淳曰：「非有奇材異計欲以為亂逆也，但假權許吳以避其禍耳。」晉灼曰：「非有以怪異之心而城守，須待變難而應吳也。」師古曰：「二說皆非也。此言權謀勁力既不能扞守，又無奇怪神靈可以禦難，恐不自全，故墜言於吳也。」","sentenceOrder":263},
  {"id":"s_work_han_thu_62_264","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　蘇林曰：「墜猶失也。」","sentenceOrder":264},
  {"id":"s_work_han_thu_62_265","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　師古曰：「祭仲，鄭大夫祭足也，事鄭莊公，為公娶鄧曼，生昭公，故祭仲立之。而宋大夫雍氏以女妻莊公而生突。昭公既立，宋人誘祭仲而執之，曰：『不立突，將死。』祭仲與宋人盟，以厲公歸而立之。昭公奔衛，言足脅於大國，苟順其心，欲以全昭公也。祭音側界反。」","sentenceOrder":265},
  {"id":"s_work_han_thu_62_266","chapterId":"ch_work_han_thu_62","textTraditional":"〔七〕　師古曰：「鄉讀曰嚮。見謂顯也。」","sentenceOrder":266},
  {"id":"s_work_han_thu_62_267","chapterId":"ch_work_han_thu_62","textTraditional":"〔八〕　張晏曰：「歷，過。畢，盡收濟北之地。」","sentenceOrder":267},
  {"id":"s_work_han_thu_62_268","chapterId":"ch_work_han_thu_62","textTraditional":"〔九〕　師古曰：「從音子容反。」","sentenceOrder":268},
  {"id":"s_work_han_thu_62_269","chapterId":"ch_work_han_thu_62","textTraditional":"〔一０〕師古曰：「練，選也。敺與驅同。白徒，言素非軍旅之人，若今言白丁矣。」","sentenceOrder":269},
  {"id":"s_work_han_thu_62_270","chapterId":"ch_work_han_thu_62","textTraditional":"〔一一〕師古曰：「半步曰跬，音空絫反。」","sentenceOrder":270},
  {"id":"s_work_han_thu_62_271","chapterId":"ch_work_han_thu_62","textTraditional":"〔一二〕師古曰：「區區，小貌也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_62_272","chapterId":"ch_work_han_thu_62","textTraditional":"〔一三〕師古曰：「橈，曲也，音女教反。」","sentenceOrder":272},
  {"id":"s_work_han_thu_62_273","chapterId":"ch_work_han_thu_62","textTraditional":"〔一四〕師古曰：「脅，翕也，謂斂也。」","sentenceOrder":273},
  {"id":"s_work_han_thu_62_274","chapterId":"ch_work_han_thu_62","textTraditional":"〔一五〕張晏曰：「悔不與吳西也。」","sentenceOrder":274},
  {"id":"s_work_han_thu_62_275","chapterId":"ch_work_han_thu_62","textTraditional":"〔一六〕師古曰：「料，量也。」","sentenceOrder":275},
  {"id":"s_work_han_thu_62_276","chapterId":"ch_work_han_thu_62","textTraditional":"〔一七〕師古曰：「西山，謂崤及華山也。抵，至也。攘，卻也。袂，衣袖也。攘袂，猶今人云掉臂耳。」","sentenceOrder":276},
  {"id":"s_work_han_thu_62_277","chapterId":"ch_work_han_thu_62","textTraditional":"〔一八〕師古曰：「淪，入也。」","sentenceOrder":277},
  {"id":"s_work_han_thu_62_278","chapterId":"ch_work_han_thu_62","textTraditional":"〔一九〕師古曰：「惟，思也。」","sentenceOrder":278},
  {"id":"s_work_han_thu_62_279","chapterId":"ch_work_han_thu_62","textTraditional":"〔二０〕師古曰：「說讀曰悅。」","sentenceOrder":279},
  {"id":"s_work_han_thu_62_280","chapterId":"ch_work_han_thu_62","textTraditional":"枚乘字叔，淮陰人也，為吳王濞郎中。吳王之初怨望謀為逆也，乘奏書諫曰：","sentenceOrder":280},
  {"id":"s_work_han_thu_62_281","chapterId":"ch_work_han_thu_62","textTraditional":"臣聞得全者全昌，失全者全亡。舜無立錐之地，以有天下；禹無十戶之聚，以王諸侯。〔一〕湯、武之土不過百里，上不絕三光之明，下不傷百姓之心者，有王術也。〔二〕故父子之道，天性也；忠臣不避重誅以直諫，〔三〕則事無遺策，功流萬世。臣乘願披腹心而效愚忠，唯大王少加意念惻怛之心於臣乘言。","sentenceOrder":281},
  {"id":"s_work_han_thu_62_282","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「聚，聚邑也，音才喻反。」","sentenceOrder":282},
  {"id":"s_work_han_thu_62_283","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「德政和平，上感天象，則日月星辰無有錯謬，故言不絕三光之明也。」","sentenceOrder":283},
  {"id":"s_work_han_thu_62_284","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「言父子君臣，其義一也。」","sentenceOrder":284},
  {"id":"s_work_han_thu_62_285","chapterId":"ch_work_han_thu_62","textTraditional":"夫以一縷之任係千鈞之重，上縣無極之高，下垂不測之淵，雖甚愚之人猶知哀其將絕也。馬方駭鼓而驚之，〔一〕係方絕又重鎮之；係絕於天不可復結，隊入深淵難以復出。其出不出，間不容髮。〔二〕能聽忠臣之言，百舉必脫。〔三〕必若所欲為，危於絫卵，難於上天；變所欲為，易於反掌，安於太山。今欲極天命之壽，敝無窮之樂，究萬乘之勢，〔四〕不出反掌之易，以居泰山之安，而欲乘絫卵之危，走上天之難，〔五〕此愚臣之所以為大王惑也。","sentenceOrder":285},
  {"id":"s_work_han_thu_62_286","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「駭亦驚也。鼓，擊鼓也。」","sentenceOrder":286},
  {"id":"s_work_han_thu_62_287","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　蘇林曰：「改計取福正在今日，言其激切甚急也。」","sentenceOrder":287},
  {"id":"s_work_han_thu_62_288","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「脫者，免於禍也，音土活反。」","sentenceOrder":288},
  {"id":"s_work_han_thu_62_289","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「敝，盡也。究，竟也。」","sentenceOrder":289},
  {"id":"s_work_han_thu_62_290","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　師古曰：「走，趨向之也，音奏。」","sentenceOrder":290},
  {"id":"s_work_han_thu_62_291","chapterId":"ch_work_han_thu_62","textTraditional":"人性有畏其景而惡其跡者，卻背而走，跡愈多，景愈疾〔一〕，不知就陰而止，景滅跡絕。欲人勿聞，莫若勿言；欲人勿知，莫若勿為。欲湯之凔，〔二〕一人炊之，百人揚之，無益也，〔三〕不如絕薪止火而已。不絕之於彼，而救之於此，譬猶抱薪而救火也。養由基，楚之善射者也，去楊葉百步，百發百中。楊葉之大，加百中焉，可謂善射矣。然其所止，乃百步之內耳，比於臣乘，未知操弓持矢也。〔四〕","sentenceOrder":291},
  {"id":"s_work_han_thu_62_292","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「背音步內反。」","sentenceOrder":292},
  {"id":"s_work_han_thu_62_293","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　鄭氏曰：「音悽愴之愴，寒也。」","sentenceOrder":293},
  {"id":"s_work_han_thu_62_294","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「炊謂爨火也。」","sentenceOrder":294},
  {"id":"s_work_han_thu_62_295","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「乘自言所知者遠，非止見百步之中，故謂由基為不曉射也。」","sentenceOrder":295},
  {"id":"s_work_han_thu_62_296","chapterId":"ch_work_han_thu_62","textTraditional":"福生有基，禍生有胎；〔一〕納其基，絕其胎，禍何自來？〔二〕泰山之霤穿石，單極之〈糹亢〉斷幹。〔三〕水非石之鑽，索非木之鋸，漸靡使之然也。〔四〕夫銖銖而稱之，至石必差；寸寸而度之，至丈必過。〔五〕石稱丈量，徑而寡失。〔六〕夫十圍之木，始生如櫱，足可搔而絕，手可擢而拔，〔七〕據其未生，先其未形也。磨礱底厲，不見其損，有時而盡；〔八〕種樹畜養，不見其益，有時而大；積德絫行，不知其善，有時而用；棄義背理，不知其惡，有時而亡。臣願大王孰計而身行之，此百世不易之道也。","sentenceOrder":296},
  {"id":"s_work_han_thu_62_297","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　服虔曰：「基、胎，皆始也。」","sentenceOrder":297},
  {"id":"s_work_han_thu_62_298","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「納猶藏也。何自來，言無所從來也。」","sentenceOrder":298},
  {"id":"s_work_han_thu_62_299","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　孟康曰：「西方人名屋梁謂極。單，一也。一梁，謂井鹿盧也。言鹿盧為綆索久鍥，斷井幹也。」晉灼曰：「〈糹亢〉，古綆字也。單，盡也，盡極之綆斷幹。幹，井上四交之幹。常為汲索所契傷也。」師古曰：「晉說近之。幹者，交木井上以為欄者也。孟云鹿盧，失其義矣。〈糹亢〉、綆皆音鯁。鍥、契皆刻也，音口計反。」","sentenceOrder":299},
  {"id":"s_work_han_thu_62_300","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「靡，盡也。」","sentenceOrder":300},
  {"id":"s_work_han_thu_62_301","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　鄭氏曰：「石，百二十斤。」張晏曰：「乘所轉四萬六千八十銖而至於石，合而稱之必有盈縮也。」師古曰：「言自小小以至於大數，則有輕重不同也。度音徒各反。」","sentenceOrder":301},
  {"id":"s_work_han_thu_62_302","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　師古曰：「徑，直也。」","sentenceOrder":302},
  {"id":"s_work_han_thu_62_303","chapterId":"ch_work_han_thu_62","textTraditional":"〔七〕　師古曰：「如櫱，言若櫱之生牙也。搔謂抓也。搔音索高反。抓音莊交反。」","sentenceOrder":303},
  {"id":"s_work_han_thu_62_304","chapterId":"ch_work_han_thu_62","textTraditional":"〔八〕　師古曰：「礱亦磨也。底，柔石也；厲，皂石也；皆可以磨者。礱音聾。」","sentenceOrder":304},
  {"id":"s_work_han_thu_62_305","chapterId":"ch_work_han_thu_62","textTraditional":"吳王不納。乘等去而之梁，從孝王游。","sentenceOrder":305},
  {"id":"s_work_han_thu_62_306","chapterId":"ch_work_han_thu_62","textTraditional":"景帝即位，御史大夫晁錯為漢定制度，損削諸侯，吳王遂與六國謀反，舉兵西鄉，〔一〕以誅錯為名。漢聞之，斬錯以謝諸侯。枚乘復說吳王曰：","sentenceOrder":306},
  {"id":"s_work_han_thu_62_307","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":307},
  {"id":"s_work_han_thu_62_308","chapterId":"ch_work_han_thu_62","textTraditional":"昔者，秦西舉胡戎之難，北備榆中之關，〔一〕南距羌筰之塞，〔二〕東當六國之從。〔三〕六國乘信陵之籍，〔四〕明蘇秦之約，厲荊軻之威，并力一心以備秦。然秦卒禽六國，滅其社稷，而并天下，是何也？則地利不同，而民輕重不等也。今漢據全秦之地，兼六國之眾，修戎狄之義，〔五〕而南朝羌筰，此其與秦，地相什而民相百，大王之所明知也。〔六〕今夫讒諛之臣為大王計者，不論骨肉之義，民之輕重，國之大小，以為吳禍，〔七〕此臣所以為大王患也。","sentenceOrder":308},
  {"id":"s_work_han_thu_62_309","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「即今所謂榆關也。」","sentenceOrder":309},
  {"id":"s_work_han_thu_62_310","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「筰，西南夷也，音才各反。」","sentenceOrder":310},
  {"id":"s_work_han_thu_62_311","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「從音子容反。」","sentenceOrder":311},
  {"id":"s_work_han_thu_62_312","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　孟康曰：「魏公子无忌號信陵君。无忌嘗總五國卻秦，有地資也。」","sentenceOrder":312},
  {"id":"s_work_han_thu_62_313","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　師古曰：「修恩義以撫戎狄。」","sentenceOrder":313},
  {"id":"s_work_han_thu_62_314","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　師古曰：「地十倍於秦，眾百倍於秦。」","sentenceOrder":314},
  {"id":"s_work_han_thu_62_315","chapterId":"ch_work_han_thu_62","textTraditional":"〔七〕　師古曰：「言勸王之反，則於吳為禍也。」","sentenceOrder":315},
  {"id":"s_work_han_thu_62_316","chapterId":"ch_work_han_thu_62","textTraditional":"夫舉吳兵以訾於漢，〔一〕譬猶蠅蚋之附群牛，腐肉之齒利劍，鋒接必無事矣。〔二〕天子聞吳率失職諸侯，願責先帝之遺約，〔三〕今漢親誅其三公，以謝前過，是大王之威加於天下，而功越於湯武也。夫吳有諸侯之位，而實富於天子；有隱匿之名，而居過於中國。〔四〕夫漢并二十四郡，十七諸侯，方輸錯出，運行數千里不絕於道，其珍怪不如東山之府。〔五〕轉粟西鄉，陸行不絕，水行滿河，不如海陵之倉。〔六〕修治上林，雜以離宮，積聚玩好，圈守禽獸，不如長洲之苑。〔七〕游曲臺，臨上路，不如朝夕之池。〔八〕深壁高壘，副以關城，不如江淮之險。此臣之所（以）為大王樂也〔九〕。","sentenceOrder":316},
  {"id":"s_work_han_thu_62_317","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　李奇曰：「訾，量也。」師古曰：「音子私反。」","sentenceOrder":317},
  {"id":"s_work_han_thu_62_318","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「蚋，蚊屬也。齒謂當之也。蚋音芮，又音人悅反。」","sentenceOrder":318},
  {"id":"s_work_han_thu_62_319","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「失職，謂被削黜，失其常分。」","sentenceOrder":319},
  {"id":"s_work_han_thu_62_320","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「隱匿，謂僻在東南。」","sentenceOrder":320},
  {"id":"s_work_han_thu_62_321","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　張晏曰：「漢時有二十四郡，十七諸侯王也。四方更輸，錯互（更）出攻也。」如淳曰：「東方諸郡以封王侯，不以封者二十四耳。時七國謀反，其餘不反者，十七也。東山，吳王之府藏也。」師古曰：「二說皆非也。言漢此時有二十四郡，十七諸侯，方軌而輸，雜出貢賦，入於天子，猶不如吳之富也。」","sentenceOrder":321},
  {"id":"s_work_han_thu_62_322","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　如淳曰：「言漢京師仰須山東漕運以自給也。」晉灼曰：「海陵，海中山為倉也。」臣瓚曰：「海陵，縣名也。有吳大倉。」師古曰：「瓚說是也。鄉讀曰嚮。」","sentenceOrder":322},
  {"id":"s_work_han_thu_62_323","chapterId":"ch_work_han_thu_62","textTraditional":"〔七〕　服虔曰：「吳苑。」孟康曰：「以江水洲為苑也。」韋昭曰：「長洲在吳東。」","sentenceOrder":323},
  {"id":"s_work_han_thu_62_324","chapterId":"ch_work_han_thu_62","textTraditional":"〔八〕　張晏曰：「曲臺，長安臺，臨道上。」蘇林曰：「吳以海水朝夕為池也。」師古曰：「三輔黃圖未央宮有曲臺殿。」","sentenceOrder":324},
  {"id":"s_work_han_thu_62_325","chapterId":"ch_work_han_thu_62","textTraditional":"〔九〕　師古曰：「言其富饒及游晏之處踰天子也。」","sentenceOrder":325},
  {"id":"s_work_han_thu_62_326","chapterId":"ch_work_han_thu_62","textTraditional":"今大王還兵疾歸，尚得十半。〔一〕不然，漢知吳之有吞天下之心也，赫然加怒，遣羽林黃頭循江而下，〔二〕襲大王之都；魯東海絕吳之饟道；〔三〕梁王飭車騎，習戰射，〔四〕積粟固守，以備滎陽，待吳之飢。大王雖欲反都，亦不得已。〔五〕夫三淮南之計不負其約，〔六〕齊王殺身以滅其跡，〔七〕四國不得出兵其郡〔八〕，趙囚邯鄲，〔九〕此不可掩，亦已明矣。〔一０〕大王已去千里之國，而制於十里之內矣。〔一一〕張、韓將北地，〔一二〕弓高宿左右，〔一三〕兵不得下壁，軍不得大息，臣竊哀之。願大王孰察焉。","sentenceOrder":326},
  {"id":"s_work_han_thu_62_327","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「十分之中可冀五分無患，故云尚得十半。」","sentenceOrder":327},
  {"id":"s_work_han_thu_62_328","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　蘇林曰：「羽林黃頭郎習水戰者也。」張晏曰：「天子舟立黃旄於其端也。」師古曰：「鄧通以櫂船為黃頭郎。蘇說是也。」","sentenceOrder":328},
  {"id":"s_work_han_thu_62_329","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「饟，古餉字。」","sentenceOrder":329},
  {"id":"s_work_han_thu_62_330","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「飭與敕同。飭，整也。」","sentenceOrder":330},
  {"id":"s_work_han_thu_62_331","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　師古曰：「已，語終之辭。」","sentenceOrder":331},
  {"id":"s_work_han_thu_62_332","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　晉灼曰：「吳楚反，皆守約不從也。」","sentenceOrder":332},
  {"id":"s_work_han_thu_62_333","chapterId":"ch_work_han_thu_62","textTraditional":"〔七〕　晉灼曰：「齊孝王將閭也。吳楚反，堅守距三國。後欒布聞齊初與三國有謀，欲伐之，王懼自殺。」師古曰：「齊王傳云吳楚已平，齊王乃自殺，今此枚乘諫書即已稱之。二傳不同，當有誤者。」","sentenceOrder":333},
  {"id":"s_work_han_thu_62_334","chapterId":"ch_work_han_thu_62","textTraditional":"〔八〕　晉灼曰：「膠東、膠西、濟南、淄川王也。發兵應吳楚，皆見誅。」","sentenceOrder":334},
  {"id":"s_work_han_thu_62_335","chapterId":"ch_work_han_thu_62","textTraditional":"〔九〕　應劭曰：「漢將酈寄圍趙王於邯鄲，與囚無異。」","sentenceOrder":335},
  {"id":"s_work_han_thu_62_336","chapterId":"ch_work_han_thu_62","textTraditional":"〔一０〕師古曰：「言事已彰著。」","sentenceOrder":336},
  {"id":"s_work_han_thu_62_337","chapterId":"ch_work_han_thu_62","textTraditional":"〔一一〕師古曰：「梁下屯兵方十里也。」","sentenceOrder":337},
  {"id":"s_work_han_thu_62_338","chapterId":"ch_work_han_thu_62","textTraditional":"〔一二〕如淳曰：「張，張羽；韓，韓安國也。時皆仕梁。北地良家子，善騎射者也。」師古曰：「將北地者，言將兵而處吳軍之北以距吳，非北地良家子也。張羽、韓安國不將漢兵，如說非也。」","sentenceOrder":338},
  {"id":"s_work_han_thu_62_339","chapterId":"ch_work_han_thu_62","textTraditional":"〔一三〕服虔曰：「韓頹當也。」如淳曰：「宿軍左右也。後弓高侯竟將輕騎絕吳糧道。」師古曰：「宿，止也。言弓高所將之兵屯止於吳軍左右也。」","sentenceOrder":339},
  {"id":"s_work_han_thu_62_340","chapterId":"ch_work_han_thu_62","textTraditional":"吳王不用乘策，卒見禽滅。","sentenceOrder":340},
  {"id":"s_work_han_thu_62_341","chapterId":"ch_work_han_thu_62","textTraditional":"漢既平七國，乘由是知名。景帝召拜乘為弘農都尉。乘久為大國上賓，與英俊並游，得其所好，不樂郡吏，以病去官。","sentenceOrder":341},
  {"id":"s_work_han_thu_62_342","chapterId":"ch_work_han_thu_62","textTraditional":"復游梁，梁客皆善屬辭賦，乘尤高。孝王薨，乘歸淮陰。","sentenceOrder":342},
  {"id":"s_work_han_thu_62_343","chapterId":"ch_work_han_thu_62","textTraditional":"武帝自為太子聞乘名，及即位，乘年老，乃以安車蒲輪徵乘〔一〕，道死。〔二〕詔問乘子，無能為文者，後乃得其孽子皋。〔三〕","sentenceOrder":343},
  {"id":"s_work_han_thu_62_344","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「蒲輪，以蒲裹輪。」","sentenceOrder":344},
  {"id":"s_work_han_thu_62_345","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「（道）在道病死也。」","sentenceOrder":345},
  {"id":"s_work_han_thu_62_346","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「孽，庶也。」","sentenceOrder":346},
  {"id":"s_work_han_thu_62_347","chapterId":"ch_work_han_thu_62","textTraditional":"皋字少孺。乘在梁時，取皋母為小妻。乘之東歸也，皋母不肯隨乘，乘怒，分皋數千錢，留與母居。年十七，上書梁共王，〔一〕得召為郎。三年，為王使，與冗從爭，〔二〕見讒惡遇罪，〔三〕家室沒入。皋亡至長安。會赦，上書北闕，自陳枚乘之子。上得之大喜，召入見待詔，皋因賦殿中。詔使賦平樂館，善之。拜為郎，使匈奴。皋不通經術，詼笑類俳倡，〔四〕為賦頌，好嫚戲，〔五〕以故得媟黷貴幸，〔六〕比東方朔、郭舍人等，而不得比嚴助等得尊官。〔七〕","sentenceOrder":347},
  {"id":"s_work_han_thu_62_348","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「恭王名買，孝王之子也。」","sentenceOrder":348},
  {"id":"s_work_han_thu_62_349","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「冗從，散職之從王者也。冗音人勇反。」","sentenceOrder":349},
  {"id":"s_work_han_thu_62_350","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「惡謂冗從言其短惡之事。」","sentenceOrder":350},
  {"id":"s_work_han_thu_62_351","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　李奇曰：「詼，嘲也。」師古曰：「俳，雜戲也。倡，樂人也。詼音恢。俳音排。嘲音竹交反。」","sentenceOrder":351},
  {"id":"s_work_han_thu_62_352","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　師古曰：「嫚，褻汙也，音慢。」","sentenceOrder":352},
  {"id":"s_work_han_thu_62_353","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　師古曰：「媟，狎也。黷，垢濁也，音瀆。」","sentenceOrder":353},
  {"id":"s_work_han_thu_62_354","chapterId":"ch_work_han_thu_62","textTraditional":"〔七〕　師古曰：「尊，高也。」","sentenceOrder":354},
  {"id":"s_work_han_thu_62_355","chapterId":"ch_work_han_thu_62","textTraditional":"武帝春秋二十九乃得皇子，群臣喜，故皋與東方朔作皇太子生賦及立皇子禖祝，〔一〕受詔所為，皆不從故事，重皇子也。","sentenceOrder":355},
  {"id":"s_work_han_thu_62_356","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「禮月令『祀於高禖』。高禖，求子之神也。武帝晚得太子，喜而立此禖祠，而令皋作祭祀之文也。」","sentenceOrder":356},
  {"id":"s_work_han_thu_62_357","chapterId":"ch_work_han_thu_62","textTraditional":"初，衛皇后立，皋奏賦以戒終。〔一〕皋為賦善於朔也。","sentenceOrder":357},
  {"id":"s_work_han_thu_62_358","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「令慎終如始也。」","sentenceOrder":358},
  {"id":"s_work_han_thu_62_359","chapterId":"ch_work_han_thu_62","textTraditional":"從行至甘泉、雍、河東，東巡狩，封泰山，塞決河宣房，游觀三輔離宮館，臨山澤，弋獵射馭狗馬蹴鞠刻鏤，〔一〕上有所感，輒使賦之。為文疾，受詔輒成，故所賦者多。司馬相如善為文而遲，故所作少而善於皋。皋賦辭中自言為賦不如相如，又言為賦乃非。見視如倡，自悔類倡也。故其賦有詆娸東方朔，〔二〕又自詆娸。其文骫骳，曲隨其事，皆得其意，〔三〕頗詼笑，不甚閒靡。凡可讀者百二十篇，其尤嫚戲不可讀者尚數十篇。","sentenceOrder":359},
  {"id":"s_work_han_thu_62_360","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「蹴，足蹴之也。鞠以韋為之，中實以物，蹴蹋為戲樂也。蹴音千六反。鞠音臣六反。」","sentenceOrder":360},
  {"id":"s_work_han_thu_62_361","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　如淳曰：「娸音欺。詆猶刑辟也。」師古曰：「詆，毀也。娸，醜也。詆音丁禮反。」","sentenceOrder":361},
  {"id":"s_work_han_thu_62_362","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「骫，古委字也。骳音被。骫骳，猶言屈曲也。」","sentenceOrder":362},
  {"id":"s_work_han_thu_62_363","chapterId":"ch_work_han_thu_62","textTraditional":"路溫舒字長君，鉅鹿東里人也。父為里監門。使溫舒牧羊，溫舒取澤中蒲，截以為牒，編用寫書。〔一〕稍習善，求為獄小吏，因學律令，轉為獄史，縣中疑事皆問焉。太守行縣，見而異之，署決曹史。又受春秋，通大義。舉孝廉，為山邑丞，〔二〕坐法免，復為郡吏。","sentenceOrder":363},
  {"id":"s_work_han_thu_62_364","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「小簡曰牒，編聯次之。」","sentenceOrder":364},
  {"id":"s_work_han_thu_62_365","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　蘇林曰：「縣名，在常山。」晉灼曰：「地理志常山有石邑，無山邑。」師古曰：「山邑不知其處。今流俗書本云常山石邑丞，後人妄加石字耳。」","sentenceOrder":365},
  {"id":"s_work_han_thu_62_366","chapterId":"ch_work_han_thu_62","textTraditional":"元鳳中，廷尉光以治詔獄，請溫舒署奏曹掾，〔一〕守廷尉史。會昭帝崩，昌邑王賀廢，宣帝初即位，溫舒上書，言宜尚德緩刑。其辭曰：","sentenceOrder":366},
  {"id":"s_work_han_thu_62_367","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　張晏曰：「光，解光。」","sentenceOrder":367},
  {"id":"s_work_han_thu_62_368","chapterId":"ch_work_han_thu_62","textTraditional":"臣聞齊有無知之禍，而桓公以興；晉有驪姬之難，而文公用伯。〔一〕近世趙王不終，諸呂作（難）〔亂〕，而孝文為大宗。繇是觀之，〔二〕禍亂之作，將以開聖人也。故桓文扶微興壞，尊文武之業，澤加百姓，功潤諸侯，雖不及三王，天下歸仁焉。文帝永思至德，以承天心，崇仁義，省刑罰，通關梁，一遠近，敬賢如大賓，愛民如赤子，內恕情之所安，而施之於海內，是以囹圄空虛，天下太平。夫繼變化之後，必有異舊之恩，此賢聖所以昭天命也。往者，昭帝即世而無嗣，大臣憂戚，焦心合謀，皆以昌邑尊親，援而立之。〔三〕然天不授命，淫亂其心，遂以自亡。深察禍變之故，乃皇天之所以開至聖也。故大將軍受命武帝，股肱漢國，〔四〕披肝膽，決大計，黜亡義，立有德，輔天而行，然後宗廟以安，天下咸寧。","sentenceOrder":368},
  {"id":"s_work_han_thu_62_369","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「伯讀曰霸。」","sentenceOrder":369},
  {"id":"s_work_han_thu_62_370","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「繇讀與由同。」","sentenceOrder":370},
  {"id":"s_work_han_thu_62_371","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「援，引也，音爰。」","sentenceOrder":371},
  {"id":"s_work_han_thu_62_372","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「謂霍光。」","sentenceOrder":372},
  {"id":"s_work_han_thu_62_373","chapterId":"ch_work_han_thu_62","textTraditional":"臣聞春秋正即位，大一統而慎始也。陛下初登至尊，與天合符，宜改前世之失，正始受（命）之統，滌煩文，除民疾，存亡繼絕，以應天意。","sentenceOrder":373},
  {"id":"s_work_han_thu_62_374","chapterId":"ch_work_han_thu_62","textTraditional":"臣聞秦有十失，其一尚存，治獄之吏是也。秦之時，羞文學，好武勇，賤仁義之士，貴治獄之吏；正言者謂之誹謗，遏過者謂之妖言。〔一〕故盛服先生不用於世，忠良切言皆鬱於胸，〔二〕譽諛之聲日滿於耳；虛美熏心，實禍蔽塞。〔三〕此乃秦之所以亡天下也。方今天下賴陛下恩厚，亡金革之危，飢寒之患，父子夫妻戮力安家，然太平未洽者，獄亂之也。夫獄者，天下之大命也，死者不可復生，者不可復屬。〔四〕書曰：「與其殺不辜，寧失不經。」〔五〕今治獄吏則不然，上下相敺，以刻為明；〔六〕深者獲公名，平者多後患。故治獄之吏皆欲人死，非憎人也，自安之道在人之死。是以死人之血流離於市，被刑之徒比肩而立，大辟之計歲以萬數，此仁聖之所以傷也。太平之未洽，凡以此也。夫人情安則樂生，痛則思死。棰楚之下，何求而不得？故囚人不勝痛，則飾辭以視之；〔七〕吏治者利其然，則指道以明之；上奏畏卻，則鍛練而周內之。〔八〕蓋奏當之成，〔九〕雖咎繇聽之，猶以為死有餘辜。〔一０〕何則？成練者眾，文致之罪明也。是以獄吏專為深刻，殘賊而亡極，媮為一切〔一一〕，不顧國患，此世之大賊也。故俗語曰：「畫地為獄，議不入；刻木為吏，期不對。」〔一二〕此皆疾吏之風，悲痛之辭也。故天下之患，莫深於獄；敗法亂正，離親塞道，莫甚乎治獄之吏。此所謂一尚存者也。","sentenceOrder":374},
  {"id":"s_work_han_thu_62_375","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「遏，止也，音一曷反。」","sentenceOrder":375},
  {"id":"s_work_han_thu_62_376","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「鬱，積也。」","sentenceOrder":376},
  {"id":"s_work_han_thu_62_377","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「熏，氣烝也，音勳。」","sentenceOrder":377},
  {"id":"s_work_han_thu_62_378","chapterId":"ch_work_han_thu_62","textTraditional":"〔四〕　師古曰：「，古絕字。屬，連也，音之欲反。」","sentenceOrder":378},
  {"id":"s_work_han_thu_62_379","chapterId":"ch_work_han_thu_62","textTraditional":"〔五〕　師古曰：「虞書大禹謨載咎繇之言。辜，罪也。經，常也。言人命至重，治獄宜慎，寧失不常之過，不濫無罪之人，所以（常）〔崇〕寬恕也。」","sentenceOrder":379},
  {"id":"s_work_han_thu_62_380","chapterId":"ch_work_han_thu_62","textTraditional":"〔六〕　師古曰：「敺與驅同。」","sentenceOrder":380},
  {"id":"s_work_han_thu_62_381","chapterId":"ch_work_han_thu_62","textTraditional":"〔七〕　師古曰：「視讀曰示。」","sentenceOrder":381},
  {"id":"s_work_han_thu_62_382","chapterId":"ch_work_han_thu_62","textTraditional":"〔八〕　晉灼曰：「精熟周悉，致之法中也。」師古曰：「卻，退也，畏為上所卻退。卻音丘略反。」","sentenceOrder":382},
  {"id":"s_work_han_thu_62_383","chapterId":"ch_work_han_thu_62","textTraditional":"〔九〕　師古曰：「當謂處其罪也。」","sentenceOrder":383},
  {"id":"s_work_han_thu_62_384","chapterId":"ch_work_han_thu_62","textTraditional":"〔一０〕師古曰：「咎繇作士，善聽獄訟，故以為喻也。」","sentenceOrder":384},
  {"id":"s_work_han_thu_62_385","chapterId":"ch_work_han_thu_62","textTraditional":"〔一一〕如淳曰：「媮，苟且也。一切，權時也。」","sentenceOrder":385},
  {"id":"s_work_han_thu_62_386","chapterId":"ch_work_han_thu_62","textTraditional":"〔一二〕師古曰：「畫獄木吏，尚不入對，況真實乎。期猶必也。議必不入對。」","sentenceOrder":386},
  {"id":"s_work_han_thu_62_387","chapterId":"ch_work_han_thu_62","textTraditional":"臣聞烏鳶之卵不毀，而後鳳凰集；〔一〕誹謗之罪不誅，而後良言進。故古人有言：「山藪藏疾，川澤納汙，瑾瑜匿惡，國君含詬。」〔二〕唯陛下除誹謗以招切言，開天下之口，廣箴諫之路，掃亡秦之失，尊文武之德，省法制，寬刑罰，以廢治獄，則太平之風可興於世，永履和樂，與天亡極，天下幸甚。〔三〕","sentenceOrder":387},
  {"id":"s_work_han_thu_62_388","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「鳶，鴟也，音弋全反。」","sentenceOrder":388},
  {"id":"s_work_han_thu_62_389","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「春秋左氏傳載晉大夫伯宗之辭。詬，恥也。言山藪之有草木則毒害者居之，川澤之形廣大則能受於汙濁，人君之善御下，亦當忍恥病也。詬音垢。」","sentenceOrder":389},
  {"id":"s_work_han_thu_62_390","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「與天長久，無窮極也。」","sentenceOrder":390},
  {"id":"s_work_han_thu_62_391","chapterId":"ch_work_han_thu_62","textTraditional":"上善其言，遷廣陽私府長。〔一〕","sentenceOrder":391},
  {"id":"s_work_han_thu_62_392","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「藏錢之府，天子曰少府，諸侯曰私府。長者，其官之長也。」","sentenceOrder":392},
  {"id":"s_work_han_thu_62_393","chapterId":"ch_work_han_thu_62","textTraditional":"內史舉溫舒文學高第，遷右扶風丞。時，詔書令公卿選可使匈奴者，溫舒上書，願給冢養，暴骨方外，〔一〕以盡臣節。事下度遼將軍范明友、太僕杜延年問狀，罷歸故官。〔二〕久之，遷臨淮太守，治有異跡，卒於官。","sentenceOrder":393},
  {"id":"s_work_han_thu_62_394","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「求為卒而隨使至匈奴也。」","sentenceOrder":394},
  {"id":"s_work_han_thu_62_395","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「以其言無可取，故罷而遣歸故官。」","sentenceOrder":395},
  {"id":"s_work_han_thu_62_396","chapterId":"ch_work_han_thu_62","textTraditional":"溫舒從祖父受曆數天文，以為漢厄三七之間，〔一〕上封事以豫戒。成帝時，谷永亦言如此。〔二〕及王莽篡位，欲章代漢之符，著其語焉。溫舒子及孫皆至牧守大官。","sentenceOrder":396},
  {"id":"s_work_han_thu_62_397","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　張晏曰：「三七二百一十歲也。自漢初至哀帝元年二百一年也，至平帝崩二百十一年。」","sentenceOrder":397},
  {"id":"s_work_han_thu_62_398","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　師古曰：「永上書所謂『涉三七之節絕』者也。」","sentenceOrder":398},
  {"id":"s_work_han_thu_62_399","chapterId":"ch_work_han_thu_62","textTraditional":"贊曰：春秋魯臧孫達以禮諫君，君子以為有後。〔一〕賈山自下劘上，〔二〕鄒陽、枚乘游於危國，然卒免刑戮者，以其言正也。路溫舒辭順而意篤，遂為世家，宜哉！〔三〕","sentenceOrder":399},
  {"id":"s_work_han_thu_62_400","chapterId":"ch_work_han_thu_62","textTraditional":"〔一〕　師古曰：「臧孫達，魯大夫臧哀伯也。桓公取郜大鼎於宋，哀伯諫之。周內史聞之，曰：『臧孫達其有後於魯乎！君違，不忘諫之以德。』」","sentenceOrder":400},
  {"id":"s_work_han_thu_62_401","chapterId":"ch_work_han_thu_62","textTraditional":"〔二〕　孟康曰：「劘謂剴切之也。」蘇林曰：「劘音摩，厲也。」師古曰：「剴音工來反。」","sentenceOrder":401},
  {"id":"s_work_han_thu_62_402","chapterId":"ch_work_han_thu_62","textTraditional":"〔三〕　師古曰：「謂子孫為大官不絕。」","sentenceOrder":402},
  {"id":"s_work_han_thu_62_403","chapterId":"ch_work_han_thu_62","textTraditional":"校勘記","sentenceOrder":403},
  {"id":"s_work_han_thu_62_404","chapterId":"ch_work_han_thu_62","textTraditional":"二三二七頁　三行　祖父（祛）〔袪〕，　景祐、殿、局本都作「袪」。下同。","sentenceOrder":404},
  {"id":"s_work_han_thu_62_405","chapterId":"ch_work_han_thu_62","textTraditional":"二三二八頁一五行　（此）〔凡〕言離宮者，皆謂於別處置之，　景祐、殿本都作「凡」。王先謙說作「凡」是。","sentenceOrder":405},
  {"id":"s_work_han_thu_62_406","chapterId":"ch_work_han_thu_62","textTraditional":"二三三０頁　八行　士傳言諫（過），　王先謙說，此句不得獨有「過」字，蓋涉下文而衍。漢紀無「過」字。","sentenceOrder":406},
  {"id":"s_work_han_thu_62_407","chapterId":"ch_work_han_thu_62","textTraditional":"二三三四頁　五行　言天下之（壤）〔壞〕如水潰。　景祐、殿本都作「壞」，此誤。","sentenceOrder":407},
  {"id":"s_work_han_thu_62_408","chapterId":"ch_work_han_thu_62","textTraditional":"二三三七頁　三行　則（為）〔謂〕夏正之二月為五月。　景祐、殿本都作「謂」。","sentenceOrder":408},
  {"id":"s_work_han_thu_62_409","chapterId":"ch_work_han_thu_62","textTraditional":"二三三九頁　一行　衡猶稱之（權）〔衡〕也，　景祐、殿本都作「衡」。王先謙說作「衡」是。","sentenceOrder":409},
  {"id":"s_work_han_thu_62_410","chapterId":"ch_work_han_thu_62","textTraditional":"二三三九頁一一行　高后割齊濟南郡為呂（王）台奉邑，　景祐本無「王」字。","sentenceOrder":410},
  {"id":"s_work_han_thu_62_411","chapterId":"ch_work_han_thu_62","textTraditional":"二三四三頁一三行　夫精（誠）變天地而信不諭兩主，　景祐、汲古、殿、局本都無「誠」字。","sentenceOrder":411},
  {"id":"s_work_han_thu_62_412","chapterId":"ch_work_han_thu_62","textTraditional":"二三四七頁　四行　殷之末世（人）〔介士〕也。　景祐、殿本都作「介士」。","sentenceOrder":412},
  {"id":"s_work_han_thu_62_413","chapterId":"ch_work_han_thu_62","textTraditional":"二三四八頁　四行　（損）〔捐〕子之之心，　景祐、殿本都作「捐」。王先謙說作「捐」是。","sentenceOrder":413},
  {"id":"s_work_han_thu_62_414","chapterId":"ch_work_han_thu_62","textTraditional":"二三四九頁　一行　然則〔荊〕軻湛七族，　景祐本有「荊」字。王念孫、王先謙都說當有。","sentenceOrder":414},
  {"id":"s_work_han_thu_62_415","chapterId":"ch_work_han_thu_62","textTraditional":"二三四九頁　四行　「今相國有此三者，而不得罪於楚之士眾，（仕）〔何〕也？」叔敖曰：「吾三相楚而（不）〔身〕愈卑」，　景祐、殿、局本「仕」都作「何」。景祐、殿本「不」作「身」，局本作「心」。","sentenceOrder":415},
  {"id":"s_work_han_thu_62_416","chapterId":"ch_work_han_thu_62","textTraditional":"二三五０頁　五行　是使布衣之士不得為枯木（巧）〔朽〕株之資也。　景祐、殿、局本都作「朽」。","sentenceOrder":416},
  {"id":"s_work_han_thu_62_417","chapterId":"ch_work_han_thu_62","textTraditional":"二三五一頁　一行　故秦皇帝任中庶子蒙〔嘉〕之言，　顧炎武說傳文脫「嘉」字。","sentenceOrder":417},
  {"id":"s_work_han_thu_62_418","chapterId":"ch_work_han_thu_62","textTraditional":"二三六三頁　二行　此臣之所（以）為大王樂也。　景祐本無「以」字。　王念孫說景祐本是。","sentenceOrder":418},
  {"id":"s_work_han_thu_62_419","chapterId":"ch_work_han_thu_62","textTraditional":"二三六三頁　七行　四方更輸，錯互（更）出攻也。　王先謙說，據文選注引，明下「更」字衍。","sentenceOrder":419},
  {"id":"s_work_han_thu_62_420","chapterId":"ch_work_han_thu_62","textTraditional":"二三六五頁一三行　（道）在道病死也。　景祐、殿本都無上「道」字。","sentenceOrder":420},
  {"id":"s_work_han_thu_62_421","chapterId":"ch_work_han_thu_62","textTraditional":"二三六八頁　五行　諸呂作（難）〔亂〕，　景祐、殿本都作「亂」。","sentenceOrder":421},
  {"id":"s_work_han_thu_62_422","chapterId":"ch_work_han_thu_62","textTraditional":"二三六九頁　二行　正始受（命）之統，　王念孫說「命」字涉上文而衍，漢紀及說苑貴德篇皆無「命」字。","sentenceOrder":422},
  {"id":"s_work_han_thu_62_423","chapterId":"ch_work_han_thu_62","textTraditional":"二三七０頁　七行　所以（常）〔崇〕寬恕也。　景祐、殿本都作「崇」。","sentenceOrder":423},
  {"id":"s_work_han_thu_63_1","chapterId":"ch_work_han_thu_63","textTraditional":"竇嬰字王孫，孝文皇后從兄子也。父世觀津人也。〔一〕喜賓客。〔二〕孝文時為吳相，病免。孝景即位，為詹事。","sentenceOrder":1},
  {"id":"s_work_han_thu_63_2","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「縣名也，地理志屬信都。觀音工喚反。」","sentenceOrder":2},
  {"id":"s_work_han_thu_63_3","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「喜，好也，音許吏反。」","sentenceOrder":3},
  {"id":"s_work_han_thu_63_4","chapterId":"ch_work_han_thu_63","textTraditional":"帝弟梁孝王，母竇太后愛之。孝王朝，因燕昆弟飲。〔一〕是時上未立太子，酒酣，上從容曰：「千秋萬歲後傳王。」〔二〕太后驩。嬰引卮酒進上曰：「天下者，高祖天下，父子相傳，漢之約也，上何以得傳梁王！」太后由此憎嬰。嬰亦薄其官，〔三〕因病免。太后除嬰門籍，不得朝請。〔四〕","sentenceOrder":4},
  {"id":"s_work_han_thu_63_5","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「序家人昆弟之親，不為君臣禮也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_63_6","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「從音千庸反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_63_7","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「自嫌其官，輕薄之也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_63_8","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　師古曰：「請音才性反。其下亦同。」","sentenceOrder":8},
  {"id":"s_work_han_thu_63_9","chapterId":"ch_work_han_thu_63","textTraditional":"孝景三年，吳楚反，上察宗室諸竇無如嬰賢，〔一〕召入見，固讓謝，稱病不足任。太后亦慚。於是上曰：「天下方有急，王孫寧可以讓邪？」乃拜嬰為大將軍，賜金千斤。嬰言爰盎、欒布諸名將賢士在家者進之。所賜金，陳廊廡下，〔二〕軍吏過，輒令財取為用〔三〕，金無入家者。嬰守滎陽，監齊趙兵。七國破，封為魏其侯。游士賓客爭歸之。每朝議大事，條侯、魏其，列侯莫敢與亢禮。〔四〕","sentenceOrder":9},
  {"id":"s_work_han_thu_63_10","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「宗室，帝之同姓親也。諸竇，總謂帝外家也。以吳楚之難，故欲用內外之親為將也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_63_11","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「廊，堂下周屋也。廡，門屋也，音侮。」","sentenceOrder":11},
  {"id":"s_work_han_thu_63_12","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「財與裁同，謂裁量而用之也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_63_13","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　師古曰：「言特敬此二人也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_63_14","chapterId":"ch_work_han_thu_63","textTraditional":"四年，立栗太子，〔一〕以嬰為傅。七年，栗太子廢，嬰爭弗能得，謝病，屏居藍田南山下〔二〕數月，諸竇賓客辯士說，莫能來。梁人高遂乃說嬰曰：「能富貴將軍者，上也；能親將軍者，太后也。今將軍傅太子，太子廢，爭不能拔，又不能死，自引謝病，擁趙女屏閒處而不朝，〔三〕袛加懟自明，揚主之過。〔四〕有如兩宮奭將軍，〔五〕則妻子無類矣。」〔六〕嬰然之，乃起，朝請如故。","sentenceOrder":14},
  {"id":"s_work_han_thu_63_15","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「栗姬之子，（敬）〔故〕曰栗太子。」","sentenceOrder":15},
  {"id":"s_work_han_thu_63_16","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「屏，隱也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_63_17","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「擁，抱也。閒處，猶言私處也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_63_18","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　師古曰：「衹，適也。懟，怨怒也。衹音支，其字從衣。懟音直類反。」","sentenceOrder":18},
  {"id":"s_work_han_thu_63_19","chapterId":"ch_work_han_thu_63","textTraditional":"〔五〕　師古曰：「兩宮，太后及帝也。奭，怒貌也，音赫。」","sentenceOrder":19},
  {"id":"s_work_han_thu_63_20","chapterId":"ch_work_han_thu_63","textTraditional":"〔六〕　師古曰：「言被誅戮無遺類也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_63_21","chapterId":"ch_work_han_thu_63","textTraditional":"桃侯免相，〔一〕竇太后數言魏其。景帝曰：「太后豈以臣有愛相魏其者？〔二〕魏其沾沾自喜耳，多易，〔三〕難以為相持重。」遂不用，用建陵侯衛綰為丞相。","sentenceOrder":21},
  {"id":"s_work_han_thu_63_22","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　服虔曰：「劉舍也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_63_23","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「愛猶惜也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_63_24","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　張晏曰：「沾沾，言自整頓也。多易，多輕薄之行也。或曰，沾音瞻。」師古曰：「沾沾，輕薄也，或音他兼反，今俗言薄沾沾。喜音許吏反。易音弋豉反。」","sentenceOrder":24},
  {"id":"s_work_han_thu_63_25","chapterId":"ch_work_han_thu_63","textTraditional":"田蚡，孝景王皇后同母弟也，生長陵。竇嬰已為大將軍，方盛，蚡為諸曹郎，未貴，往來侍酒嬰所，跪起如子姓。〔一〕及孝景晚節，蚡益貴幸，〔二〕為中大夫。辯有口，學盤盂諸書，〔三〕王皇后賢之。","sentenceOrder":25},
  {"id":"s_work_han_thu_63_26","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「姓，生也，言同子禮，若己所生。」","sentenceOrder":26},
  {"id":"s_work_han_thu_63_27","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「晚節，猶言末時也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_63_28","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　應劭曰：「黃帝史孔甲所作也，凡二十九篇，書盤盂中，所以為法戒也。諸書，諸子之書也。」孟康曰：「孔甲盤盂二十六篇，雜家書，兼儒墨名法者也。」晉灼曰：「案藝文志，孟說是也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_63_29","chapterId":"ch_work_han_thu_63","textTraditional":"孝景崩，武帝初即位，蚡以舅封為武安侯，弟勝為周陽侯。","sentenceOrder":29},
  {"id":"s_work_han_thu_63_30","chapterId":"ch_work_han_thu_63","textTraditional":"蚡新用事，卑下賓客，〔一〕進名士家居者貴之，〔二〕欲以傾諸將相。〔三〕上所填撫，多蚡賓客計策。〔四〕會丞相綰病免，上議置丞相、太尉。藉福說蚡曰：「魏其侯貴久矣，素天下士歸之。今將軍初興，未如，即上以將軍為相，必讓魏其。魏其為相，將軍必為太尉。太尉、相尊等耳，〔五〕有讓賢名。」蚡乃微言太后風上〔六〕，於是乃以嬰為丞相，蚡為太尉。藉福賀嬰，因弔曰：「君侯資性喜善疾惡，〔七〕方今善人譽君侯，故至丞相；然惡人眾，亦且毀君侯。君侯能兼容，則幸久；〔八〕不能，今以毀去矣。」嬰不聽。","sentenceOrder":30},
  {"id":"s_work_han_thu_63_31","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「下音胡稼反。」","sentenceOrder":31},
  {"id":"s_work_han_thu_63_32","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　晉灼曰：「滯在里巷未仕者。」","sentenceOrder":32},
  {"id":"s_work_han_thu_63_33","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「傾謂踰越而勝之也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_63_34","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　如淳曰：「多薦名士，名士得進為帝畫計策也。」師古曰：「填音竹刃反。」","sentenceOrder":34},
  {"id":"s_work_han_thu_63_35","chapterId":"ch_work_han_thu_63","textTraditional":"〔五〕　師古曰：「言其尊貴同一等也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_63_36","chapterId":"ch_work_han_thu_63","textTraditional":"〔六〕　師古曰：「風讀曰諷。」","sentenceOrder":36},
  {"id":"s_work_han_thu_63_37","chapterId":"ch_work_han_thu_63","textTraditional":"〔七〕　師古曰：「喜，好也，音許吏反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_63_38","chapterId":"ch_work_han_thu_63","textTraditional":"〔八〕　師古曰：「兼容，謂不嫉惡人令其怨也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_63_39","chapterId":"ch_work_han_thu_63","textTraditional":"嬰、蚡俱好儒術，推轂趙綰為御史大夫，王臧為郎中令。〔一〕迎魯申公，欲設明堂，令列侯就國，除關，〔二〕以禮為服制，〔三〕以興太平。舉謫諸竇宗室無行者，除其屬藉。諸外家為列侯，列侯多尚公主，皆不欲就國，以故毀日至竇太后。太后好黃老言，而嬰、蚡、趙綰等務隆推儒術，貶道家言，是以竇太后滋不說。〔四〕二年，御史大夫趙綰請毋奏事東宮。竇太后大怒，曰：「此欲復為新垣平邪！」乃罷逐趙綰、王臧，而免丞相嬰、太尉蚡，以柏至侯許昌為丞相，武彊侯莊青翟為御史大夫。嬰、蚡以侯家居。","sentenceOrder":39},
  {"id":"s_work_han_thu_63_40","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「推轂，謂升薦之，若轉車轂之為也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_63_41","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　服虔曰：「除關禁也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_63_42","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「謂喪服之制也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_63_43","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　師古曰：「滋，益也。說讀曰悅。」","sentenceOrder":43},
  {"id":"s_work_han_thu_63_44","chapterId":"ch_work_han_thu_63","textTraditional":"蚡雖不任職，以王太后故親幸，數言事，多效，〔一〕士吏趨勢利者皆去嬰而歸蚡。蚡日益橫。〔二〕六年，竇太后崩，丞相昌、御史大夫青翟坐喪事不辦，免。上以蚡為丞相，大司農韓安國為御史大夫。天下士郡諸侯愈益附蚡。〔三〕","sentenceOrder":44},
  {"id":"s_work_han_thu_63_45","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「效謂見聽用。」","sentenceOrder":45},
  {"id":"s_work_han_thu_63_46","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「橫，恣也，音胡孟反。」","sentenceOrder":46},
  {"id":"s_work_han_thu_63_47","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「郡及諸侯也，猶言郡國耳。」","sentenceOrder":47},
  {"id":"s_work_han_thu_63_48","chapterId":"ch_work_han_thu_63","textTraditional":"蚡為人貌侵，生貴甚。〔一〕又以為諸侯王多長，〔二〕上初即位，富於春秋，〔三〕蚡以肺附為相，〔四〕非痛折節以禮屈之，天下不肅。〔五〕當是時，丞相入奏事，語移日，所言皆聽。薦人或起家至二千石，權移主上。上乃曰：「君除吏盡未？吾亦欲除吏。〔六〕」嘗請考工地益宅，上怒曰：「遂取武庫！」是後乃退。〔七〕召客飲，坐其兄蓋侯北鄉，自坐東鄉，〔八〕以為漢相尊，不可以兄故私橈。〔九〕由此滋驕，〔一０〕治宅甲諸第，〔一一〕田園極膏腴，〔一二〕市買郡縣器物相屬於道。〔一三〕前堂羅鐘鼓，立曲旃；〔一四〕後房婦女以百數。諸奏珍物狗馬玩好，不可勝數。〔一五〕","sentenceOrder":48},
  {"id":"s_work_han_thu_63_49","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　服虔曰：「侵，短小也。」師古曰：「生貴，謂自尊高示貴寵也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_63_50","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　張晏曰：「多長年。」","sentenceOrder":50},
  {"id":"s_work_han_thu_63_51","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「謂年幼也。齒歷方久，故云富於春秋也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_63_52","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　師古曰：「舊解云肺附，如肝肺之相附著也。一說，肺，斫木札也，喻其輕薄附著大材也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_63_53","chapterId":"ch_work_han_thu_63","textTraditional":"〔五〕　師古曰：「痛猶甚也。言以尊貴臨之，皆令其屈節而下己也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_63_54","chapterId":"ch_work_han_thu_63","textTraditional":"〔六〕　師古曰：「凡言除者，除去故官就新官。」","sentenceOrder":54},
  {"id":"s_work_han_thu_63_55","chapterId":"ch_work_han_thu_63","textTraditional":"〔七〕　師古曰：「考工，少府之屬官也，主作器械。上責其此請，故謂之曰：『何不遂取武庫！』蚡乃退也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_63_56","chapterId":"ch_work_han_thu_63","textTraditional":"〔八〕　師古曰：「自處尊位也。鄉讀皆曰嚮。」","sentenceOrder":56},
  {"id":"s_work_han_thu_63_57","chapterId":"ch_work_han_thu_63","textTraditional":"〔九〕　師古曰：「橈，曲也，音女教反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_63_58","chapterId":"ch_work_han_thu_63","textTraditional":"〔一０〕師古曰：「滋，益也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_63_59","chapterId":"ch_work_han_thu_63","textTraditional":"〔一一〕師古曰：「言為諸第之（長）〔最〕也。以甲乙之次，言甲則為上矣。」","sentenceOrder":59},
  {"id":"s_work_han_thu_63_60","chapterId":"ch_work_han_thu_63","textTraditional":"〔一二〕師古曰：「膏腴，謂肥厚之處。」","sentenceOrder":60},
  {"id":"s_work_han_thu_63_61","chapterId":"ch_work_han_thu_63","textTraditional":"〔一三〕師古曰：「屬，逮及也，音之欲反。」","sentenceOrder":61},
  {"id":"s_work_han_thu_63_62","chapterId":"ch_work_han_thu_63","textTraditional":"〔一四〕如淳曰：「旃，旗之名也，通帛曰旃。曲旃，僭也。」蘇林曰：「禮，大夫建旃。曲，柄上曲也。」師古曰：「蘇說是也。許慎云『旃，旗曲柄也，所以旃表士眾』也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_63_63","chapterId":"ch_work_han_thu_63","textTraditional":"〔一五〕師古曰：「奏，進也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_63_64","chapterId":"ch_work_han_thu_63","textTraditional":"而嬰失竇太后，益疏不用，無勢，諸公稍自引而怠（〈忄臺〉）〔驁〕，〔一〕唯灌夫獨否。故嬰墨墨不得意，而厚遇夫也。","sentenceOrder":64},
  {"id":"s_work_han_thu_63_65","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「（〈忄臺〉）〔驁〕與傲同。」","sentenceOrder":65},
  {"id":"s_work_han_thu_63_66","chapterId":"ch_work_han_thu_63","textTraditional":"灌夫字仲孺，潁陰人也。父張孟，（常）〔嘗〕為潁陰侯灌嬰舍人，得幸，因進之，〔一〕至二千石，故蒙灌氏姓為灌孟。〔二〕吳楚反時，潁陰侯灌嬰為將軍，屬太尉，〔三〕請孟為校尉。夫以千人與父俱。〔四〕孟年老，潁陰侯彊請之，鬱鬱不得意，故戰常陷堅，遂死吳軍中。漢法，父子俱，有死事，得與喪歸。夫不肯隨喪歸，奮曰：「願取吳王若將軍頭以報父仇。」〔五〕於是夫被甲持戟，募軍中壯士所善願從數十人。〔六〕及出壁門，莫敢前。獨兩人及從奴十餘騎馳入吳軍，至戲下，〔七〕所殺傷數十人。不得前，復還走漢壁，〔八〕亡其奴，獨與一騎歸。夫身中大創十餘，適有萬金良藥，故得無死。〔九〕創少瘳，〔一０〕又復請將軍曰：「吾益知吳壁曲折，請復往。」〔一一〕將軍壯而義之，恐亡夫，乃言太尉，太尉召固止之。吳軍（敗）〔破〕，夫以此名聞天下。","sentenceOrder":66},
  {"id":"s_work_han_thu_63_67","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「進，薦也。嬰薦孟也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_63_68","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「蒙，冒也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_63_69","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「時潁陰侯是灌嬰之子，名何，轉寫誤為嬰耳。」","sentenceOrder":69},
  {"id":"s_work_han_thu_63_70","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　孟康曰：「官主千人，如候司馬也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_63_71","chapterId":"ch_work_han_thu_63","textTraditional":"〔五〕　張晏曰：「自奮厲也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_63_72","chapterId":"ch_work_han_thu_63","textTraditional":"〔六〕　師古曰：「所善，素與己善者。」","sentenceOrder":72},
  {"id":"s_work_han_thu_63_73","chapterId":"ch_work_han_thu_63","textTraditional":"〔七〕　師古曰：「戲，大將之旗也，讀與麾同，又音許宜反。」","sentenceOrder":73},
  {"id":"s_work_han_thu_63_74","chapterId":"ch_work_han_thu_63","textTraditional":"〔八〕　師古曰：「走，趣嚮也，音奏。」","sentenceOrder":74},
  {"id":"s_work_han_thu_63_75","chapterId":"ch_work_han_thu_63","textTraditional":"〔九〕　師古曰：「萬金者，言其價貴也。金字或作全，言得之者必生全也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_63_76","chapterId":"ch_work_han_thu_63","textTraditional":"〔一０〕師古曰：「瘳，差也，音丑流反。」","sentenceOrder":76},
  {"id":"s_work_han_thu_63_77","chapterId":"ch_work_han_thu_63","textTraditional":"〔一一〕師古曰：「曲折，猶言委曲也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_63_78","chapterId":"ch_work_han_thu_63","textTraditional":"潁陰侯言夫，夫為郎中將。數歲，坐法去。家居長安中，諸公莫不稱，由是復為代相。","sentenceOrder":78},
  {"id":"s_work_han_thu_63_79","chapterId":"ch_work_han_thu_63","textTraditional":"武帝即位，以為淮陽天下郊，勁兵處，〔一〕故徙夫為淮陽太守。入為太僕。二年，夫與長樂衛尉竇甫飲，輕重不得，〔二〕夫醉，搏甫。〔三〕甫，竇太后昆弟。上恐太后誅夫，徙夫為燕相。數歲，坐法免，家居長安。","sentenceOrder":79},
  {"id":"s_work_han_thu_63_80","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「郊謂四交輻湊，而兵又勁彊。」","sentenceOrder":80},
  {"id":"s_work_han_thu_63_81","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　晉灼曰：「飲酒輕重不得其平也。」師古曰：「禮數之輕重也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_63_82","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「搏，以手擊之。」","sentenceOrder":82},
  {"id":"s_work_han_thu_63_83","chapterId":"ch_work_han_thu_63","textTraditional":"夫為人剛直，使酒，〔一〕不好面諛。貴戚諸勢在己之右，欲必陵之；士在己左，愈貧賤，尤益禮敬，與鈞。〔二〕稠人廣眾，薦寵下輩。〔三〕士亦以此多之。〔四〕","sentenceOrder":83},
  {"id":"s_work_han_thu_63_84","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「使酒，因酒而使氣也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_63_85","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「右，尊也。左，卑也。鈞，等也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_63_86","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「稠，多也。下輩，下等之人也。每於人眾之中故寵薦也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_63_87","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　師古曰：「多猶重之。」","sentenceOrder":87},
  {"id":"s_work_han_thu_63_88","chapterId":"ch_work_han_thu_63","textTraditional":"夫不好文學，喜任俠，已然諾。〔一〕諸所與交通，無非豪桀大猾。家累數千萬，食客日數十百人。〔二〕波池田園，宗族賓客為權利，〔三〕橫潁川。〔四〕潁川兒歌之曰：「潁水清，灌氏寧；潁水濁，灌氏族。」〔五〕","sentenceOrder":88},
  {"id":"s_work_han_thu_63_89","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「已，必也。謂一言許人，必信之也。喜音許吏反。」","sentenceOrder":89},
  {"id":"s_work_han_thu_63_90","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「或八九十，或百人也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_63_91","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「波讀曰陂。」","sentenceOrder":91},
  {"id":"s_work_han_thu_63_92","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　師古曰：「橫音胡孟反。其下亦同。」","sentenceOrder":92},
  {"id":"s_work_han_thu_63_93","chapterId":"ch_work_han_thu_63","textTraditional":"〔五〕　師古曰：「深怨嫉之，故為此言也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_63_94","chapterId":"ch_work_han_thu_63","textTraditional":"夫家居，卿相侍中賓客益衰。〔一〕及竇嬰失勢，亦欲倚夫引繩排根生平慕之後棄者。〔二〕夫亦得嬰通列侯宗室為名高。兩人相為引重，〔三〕其游如父子然，相得驩甚，無厭，恨相知之晚。","sentenceOrder":94},
  {"id":"s_work_han_thu_63_95","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「以夫居家，而卿相侍中素為夫之賓客者，漸以衰退不復往也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_63_96","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　蘇林曰：「二人相倚，引繩直排根賓客去之者，不與交通也。」孟康曰：「根者，根格，引繩以彈排擯根格之也。」師古曰：「孟說近也。根音下恩反。格音下各反。言嬰與夫共相提挈，有人生平慕嬰、夫，後見其失職而頗慢弛，如此者，共排退之，不復與交。譬如相對挽繩而根格之也。今吳楚俗猶謂牽引前卻為根格也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_63_97","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　張晏曰：「相薦達為聲勢也。」師古曰：「相牽引而致於尊重也。為音于偽反。」","sentenceOrder":97},
  {"id":"s_work_han_thu_63_98","chapterId":"ch_work_han_thu_63","textTraditional":"夫嘗有服，〔一〕過丞相蚡。蚡從容曰：〔二〕「吾欲與仲孺過魏其侯，會仲孺有服。」夫曰：「將軍乃肯幸臨況魏其侯，〔三〕夫安敢以服為解！〔四〕請語魏其具，〔五〕將軍旦日蚤臨。」〔六〕蚡許諾。夫以語嬰。嬰與夫人益巿牛酒，〔七〕夜洒埽張具至旦〔八〕。平明，令門下候司。至日中，蚡不來。嬰謂夫曰：「丞相豈忘之哉？」夫不懌，〔九〕曰：「夫以服請，不宜。」〔一０〕乃駕，自往迎蚡。蚡特前戲許夫，〔一一〕殊無意往。夫至門，蚡尚臥也。於是夫見，曰：「將軍昨日幸許過魏其，魏其夫妻治具，至今未敢嘗食。」蚡悟，謝曰：「吾醉，忘與仲孺言。」乃駕往。往又徐行，夫愈益怒。及飲酒酣，夫起舞屬蚡，〔一二〕蚡不起。夫徙坐，語侵之。〔一三〕嬰乃扶夫去，謝蚡。蚡卒飲至夜，極驩而去。","sentenceOrder":98},
  {"id":"s_work_han_thu_63_99","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「謂喪服也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_63_100","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「從音千容反。」","sentenceOrder":100},
  {"id":"s_work_han_thu_63_101","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「況，賜也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_63_102","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　師古曰：「解謂辭之也，若今言分疏矣。」","sentenceOrder":102},
  {"id":"s_work_han_thu_63_103","chapterId":"ch_work_han_thu_63","textTraditional":"〔五〕　師古曰：「具，辦具酒食。」","sentenceOrder":103},
  {"id":"s_work_han_thu_63_104","chapterId":"ch_work_han_thu_63","textTraditional":"〔六〕　師古曰：「旦日，明旦也。蚤，古早字。」","sentenceOrder":104},
  {"id":"s_work_han_thu_63_105","chapterId":"ch_work_han_thu_63","textTraditional":"〔七〕　師古曰：「益，多也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_63_106","chapterId":"ch_work_han_thu_63","textTraditional":"〔八〕　師古曰：「洒音灑，又音所寄反。」","sentenceOrder":106},
  {"id":"s_work_han_thu_63_107","chapterId":"ch_work_han_thu_63","textTraditional":"〔九〕　師古曰：「懌，悅也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_63_108","chapterId":"ch_work_han_thu_63","textTraditional":"〔一０〕師古曰：「不當忘也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_63_109","chapterId":"ch_work_han_thu_63","textTraditional":"〔一一〕師古曰：「特，但也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_63_110","chapterId":"ch_work_han_thu_63","textTraditional":"〔一二〕師古曰：「屬，付也，猶今之舞訖相勸也。屬音之欲反。」","sentenceOrder":110},
  {"id":"s_work_han_thu_63_111","chapterId":"ch_work_han_thu_63","textTraditional":"〔一三〕師古曰：「徙坐，謂移就其坐也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_63_112","chapterId":"ch_work_han_thu_63","textTraditional":"後蚡使藉福請嬰城南田，嬰大望曰：〔一〕「老僕雖棄，將軍雖貴，寧可以勢相奪乎！」不許。夫聞，怒罵福。福惡兩人有隙，乃謾好謝蚡〔二〕曰：「魏其老且死，易忍，且待之。」已而蚡聞嬰、夫實怒不予，亦怒曰：「魏其子嘗殺人，蚡活之。蚡事魏其無所不可，愛數頃田？且灌夫何與也？〔三〕吾不敢復求田。」由此大怒。","sentenceOrder":112},
  {"id":"s_work_han_thu_63_113","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「望，怨也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_63_114","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「謾猶詭也，詐為好言也。謾讀與慢同，又音莫連反。」","sentenceOrder":114},
  {"id":"s_work_han_thu_63_115","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「與讀曰預。預，干也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_63_116","chapterId":"ch_work_han_thu_63","textTraditional":"元光四年春，蚡言灌夫家在潁川，橫甚，民苦之。請案之。上曰：「此丞相事，何請？」夫亦持蚡陰事，為姦利，受淮南王金與語言。賓客居間，遂已，俱解。〔一〕","sentenceOrder":116},
  {"id":"s_work_han_thu_63_117","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「兩家賓客處於中間和解之。」","sentenceOrder":117},
  {"id":"s_work_han_thu_63_118","chapterId":"ch_work_han_thu_63","textTraditional":"夏，蚡取燕王女為夫人，〔一〕太后詔召列侯宗室皆往賀。嬰過夫，欲與俱。夫謝曰：「夫數以酒失過丞相，〔二〕丞相今者又與夫有隙。」嬰曰：「事已解。」彊與俱。酒酣，蚡起為壽，坐皆避席伏。已嬰為壽，獨故人避席，餘半膝席。〔三〕夫行酒，至蚡，蚡膝席曰：「不能滿觴。」夫怒，因嘻笑曰：「將軍貴人也，畢之！」〔四〕時蚡不肯。〔五〕行酒次至臨汝侯灌賢，賢方與程不識耳語，〔六〕又不避席。夫無所發怒，乃罵賢曰：「平生毀程不識不直一錢，今日長者為壽，乃效女曹兒呫囁耳語！」〔七〕蚡謂夫曰：「程、李俱東西宮衛尉，〔八〕今眾辱程將軍，仲孺獨不為李將軍地乎？」〔九〕夫曰：「今日斬頭穴匈，何知程、李！」〔一０〕坐乃起更衣〔一一〕，稍稍去。嬰去，戲夫。〔一二〕夫出，蚡遂怒曰：「此吾驕灌夫罪也。」乃令騎留夫，〔一三〕夫不得出。藉福起為謝，案夫項令謝。〔一四〕夫愈怒，不肯順。蚡乃戲騎縛夫〔一五〕置傳舍，〔一六〕召長史曰：「今日召宗室，有詔。」〔一七〕劾灌夫罵坐不敬，〔一八〕繫居室。〔一九〕遂其前事，〔二０〕遣吏分曹逐捕諸灌氏支屬，皆得棄巿罪。嬰愧，為資使賓客請，莫能解。〔二一〕蚡吏皆為耳目，諸灌氏皆亡匿，夫繫，遂不得告言蚡陰事。","sentenceOrder":118},
  {"id":"s_work_han_thu_63_119","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「燕王澤之子康王嘉女。」","sentenceOrder":119},
  {"id":"s_work_han_thu_63_120","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「言因酒有失，得罪過於丞相。」","sentenceOrder":120},
  {"id":"s_work_han_thu_63_121","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　蘇林曰：「下席而膝半在席上也。」如淳曰：「以膝跪席上也。」師古曰：「如說是也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_63_122","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　張晏曰：「行酒過之為已畢。」如淳曰：「言雖貴，且當盡酒，以其勢劫之也。」師古曰：「如說近之。言將軍雖貴人也，請盡此觴。嘻，強笑也，音許其反。」","sentenceOrder":122},
  {"id":"s_work_han_thu_63_123","chapterId":"ch_work_han_thu_63","textTraditional":"〔五〕　師古曰：「不為盡也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_63_124","chapterId":"ch_work_han_thu_63","textTraditional":"〔六〕　師古曰：「附耳小語也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_63_125","chapterId":"ch_work_han_thu_63","textTraditional":"〔七〕　師古曰：「女曹兒猶言兒女輩也。呫音昌涉反。囁音人涉反。」","sentenceOrder":125},
  {"id":"s_work_han_thu_63_126","chapterId":"ch_work_han_thu_63","textTraditional":"〔八〕　孟康曰：「李廣為東宮，程不識為西宮。」","sentenceOrder":126},
  {"id":"s_work_han_thu_63_127","chapterId":"ch_work_han_thu_63","textTraditional":"〔九〕　蘇林曰：「不為李將軍除道地邪？」如淳曰：「二人同號比尊，今辱一人，不當為毀廣邪？」師古曰：「如說近之。言既毀程，令廣何地自安處。」","sentenceOrder":127},
  {"id":"s_work_han_thu_63_128","chapterId":"ch_work_han_thu_63","textTraditional":"〔一０〕晉灼曰：「斬頭見刺，猶不止也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_63_129","chapterId":"ch_work_han_thu_63","textTraditional":"〔一一〕師古曰：「坐謂坐上之人也。更，改也。凡久坐者，皆起更衣，以其寒暖或變也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_63_130","chapterId":"ch_work_han_thu_63","textTraditional":"〔一二〕晉灼曰：「戲，古麾字也。」師古曰：「招麾之令出也。漢書多以戲為麾字。」","sentenceOrder":130},
  {"id":"s_work_han_thu_63_131","chapterId":"ch_work_han_thu_63","textTraditional":"〔一三〕師古曰：「騎謂常從之騎也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_63_132","chapterId":"ch_work_han_thu_63","textTraditional":"〔一四〕師古曰：「使其拜也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_63_133","chapterId":"ch_work_han_thu_63","textTraditional":"〔一五〕師古曰：「戲讀亦曰麾。謂指麾命之而令收縛夫也。」","sentenceOrder":133},
  {"id":"s_work_han_thu_63_134","chapterId":"ch_work_han_thu_63","textTraditional":"〔一六〕師古曰：「傳舍，解在酈食其傳。」","sentenceOrder":134},
  {"id":"s_work_han_thu_63_135","chapterId":"ch_work_han_thu_63","textTraditional":"〔一七〕師古曰：「長史，丞相長史也。召宗室，謂請召之為客也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_63_136","chapterId":"ch_work_han_thu_63","textTraditional":"〔一八〕師古曰：「於大坐中罵詈，（不為）〔為不〕敬。」","sentenceOrder":136},
  {"id":"s_work_han_thu_63_137","chapterId":"ch_work_han_thu_63","textTraditional":"〔一九〕師古曰：「居室，署名也，屬少府。其後改名曰保宮。」","sentenceOrder":137},
  {"id":"s_work_han_thu_63_138","chapterId":"ch_work_han_thu_63","textTraditional":"〔二０〕師古曰：「遂，竟也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_63_139","chapterId":"ch_work_han_thu_63","textTraditional":"〔二一〕如淳曰：「為出資費，使人為夫請罪也。」師古曰：「如說非也。為資，為其資地耳，非財物也。為讀如本字。」","sentenceOrder":139},
  {"id":"s_work_han_thu_63_140","chapterId":"ch_work_han_thu_63","textTraditional":"嬰銳為救夫，嬰夫人諫曰：「灌將軍得罪丞相，與太后家迕〔一〕，寧可救邪？」嬰曰：「侯自我得之，自我捐之，無所恨。〔二〕且終不令灌仲孺獨死，嬰獨生。」乃匿其家，竊出上書。〔三〕立召入，具告言灌夫醉飽事，不足誅。上然之，賜嬰食，曰：「東朝廷辯之。」〔四〕","sentenceOrder":140},
  {"id":"s_work_han_thu_63_141","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「相逆迕也。迕音悟。」","sentenceOrder":141},
  {"id":"s_work_han_thu_63_142","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「言不過失爵耳。」","sentenceOrder":142},
  {"id":"s_work_han_thu_63_143","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「匿，避也。不令家人知之，恐其又止諫也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_63_144","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　如淳曰：「東朝，太后朝也。」張晏曰：「會公卿大夫東朝，共理而分別也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_63_145","chapterId":"ch_work_han_thu_63","textTraditional":"嬰東朝，盛推夫善，言其醉飽得過，乃丞相以它事誣罪之。蚡盛毀夫所為橫恣，罪逆不道。嬰度無可奈何，〔一〕因言蚡短。蚡曰：「天下幸而安樂無事，蚡得為（胏）〔肺〕附，所好音樂狗馬田宅，所愛倡優巧匠之屬，〔二〕不如魏其、灌夫日夜招聚天下豪桀壯士與論議，腹誹而心謗，卬視天，俛畫地，〔三〕辟睨兩宮間，〔四〕幸天下有變，而欲有大功。〔五〕臣乃不如魏其等所為。」上問朝臣：「兩人孰是？」御史大夫韓安國曰：「魏其言灌夫父死事，身荷戟馳不測之吳軍，〔六〕身被數十創，名冠三軍，此天下壯士，非有大惡，爭柸酒，不足引它過以誅也。魏其言是。丞相亦言灌夫通姦猾，侵細民，家累巨萬，橫恣潁川，輘轢宗室，侵犯骨肉，〔七〕此所謂『支大於幹，脛大於股，不折必披』。〔八〕丞相言亦是。唯明主裁之。」主爵都尉汲黯是魏其。內史鄭當時是魏其，後不堅。餘皆莫敢對。上怒內史曰：「公平生數言魏其、武安長短，今日廷論，局趣效轅下駒，〔九〕吾并斬若屬矣！」〔一０〕即罷起入，上食太后。太后亦已使人候司，具以語太后。太后怒，不食，曰：「我在也，而人皆藉吾弟，〔一一〕令我百歲後，皆魚肉之乎！〔一二〕且帝寧能為石人邪！〔一三〕此特帝在，即錄錄，〔一四〕設百歲後，是屬寧有可信者乎？」〔一五〕上謝曰：「俱外家，故廷辨之。〔一六〕不然，此一獄吏所決耳。」是時郎中令石建為上分別言兩人。","sentenceOrder":145},
  {"id":"s_work_han_thu_63_146","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「度音徒各反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_63_147","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「倡，樂人也。優，諧戲者也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_63_148","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　張晏曰：「視天，占三光也。畫地，知分野所在也。念欲作反事也。」師古曰：「卬讀曰仰。」","sentenceOrder":148},
  {"id":"s_work_han_thu_63_149","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　張晏曰：「占太后與帝吉凶之期也。」師古曰：「辟睨，傍視也。辟音普計反，字本作〈目辟〉。睨音吾計反。」","sentenceOrder":149},
  {"id":"s_work_han_thu_63_150","chapterId":"ch_work_han_thu_63","textTraditional":"〔五〕　張晏曰：「幸有反者，當為將立大功也。」臣瓚曰：「天下有變，謂因國家變難之際得立大功也。」師古曰：「瓚說是。」","sentenceOrder":150},
  {"id":"s_work_han_thu_63_151","chapterId":"ch_work_han_thu_63","textTraditional":"〔六〕　師古曰：「荷，負也。不測，言其彊盛也。荷音何。」","sentenceOrder":151},
  {"id":"s_work_han_thu_63_152","chapterId":"ch_work_han_thu_63","textTraditional":"〔七〕　師古曰：「輘轢，謂蹈踐之也。輘音淩，轢音郎擊反。」","sentenceOrder":152},
  {"id":"s_work_han_thu_63_153","chapterId":"ch_work_han_thu_63","textTraditional":"〔八〕　師古曰：「披音丕靡反。」","sentenceOrder":153},
  {"id":"s_work_han_thu_63_154","chapterId":"ch_work_han_thu_63","textTraditional":"〔九〕　應劭曰：「駒者，駕著轅下。局趣，〈足戚〉小之貌也。」張晏曰：「俛頭於車轅下，隨母而已。」師古曰：「張說非也。駕車不以牝馬。小雅皇皇者華之詩曰『我馬維駒』，非隨母也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_63_155","chapterId":"ch_work_han_thu_63","textTraditional":"〔一０〕師古曰：「若，汝也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_63_156","chapterId":"ch_work_han_thu_63","textTraditional":"〔一一〕晉灼曰：「藉，蹈也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_63_157","chapterId":"ch_work_han_thu_63","textTraditional":"〔一二〕師古曰：「以比魚肉而食噉也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_63_158","chapterId":"ch_work_han_thu_63","textTraditional":"〔一三〕師古曰：「言徒有人形耳，不知好惡也。一曰，石人者，謂常存不死也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_63_159","chapterId":"ch_work_han_thu_63","textTraditional":"〔一四〕師古曰：「錄錄，言循眾也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_63_160","chapterId":"ch_work_han_thu_63","textTraditional":"〔一五〕師古曰：「設猶脫也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_63_161","chapterId":"ch_work_han_thu_63","textTraditional":"〔一六〕師古曰：「嬰，景帝從舅子。蚡，太后同母弟。故言俱外家。」","sentenceOrder":161},
  {"id":"s_work_han_thu_63_162","chapterId":"ch_work_han_thu_63","textTraditional":"蚡已罷朝，出止車門，召御史大夫安國載，〔一〕怒曰：「與長孺共一禿翁，何為首鼠兩端？」〔二〕安國良久謂蚡曰：「君何不自喜！〔三〕夫魏其毀君，君當免冠解印綬歸，〔四〕曰『臣以（胏）〔肺〕附幸得待罪，固非其任，魏其言皆是。』如此，上必多君有讓，〔五〕不廢君。魏其必媿，杜門齰舌自殺。〔六〕今人毀君，君亦毀之，譬如賈豎女子爭言，何其無大體也！」蚡謝曰：「爭時急，不知出此。」","sentenceOrder":162},
  {"id":"s_work_han_thu_63_163","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「韓安國也。載謂共乘車。」","sentenceOrder":163},
  {"id":"s_work_han_thu_63_164","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　服虔曰：「禿翁，言嬰無官位版授也。首鼠，一前一卻也。」張晏曰：「嬰年老，又嗜酒，頭禿，言當共治一禿翁也。」師古曰：「服說是也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_63_165","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「何不自謙遜為可喜之事也。喜音許吏反。」","sentenceOrder":165},
  {"id":"s_work_han_thu_63_166","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　師古曰：「歸印綬於天子也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_63_167","chapterId":"ch_work_han_thu_63","textTraditional":"〔五〕　師古曰：「多猶重也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_63_168","chapterId":"ch_work_han_thu_63","textTraditional":"〔六〕　師古曰：「杜，塞也。齰，齧也，音仕客反。」","sentenceOrder":168},
  {"id":"s_work_han_thu_63_169","chapterId":"ch_work_han_thu_63","textTraditional":"於是上使御史簿責嬰〔一〕所言灌夫頗不讎，〔二〕劾繫都司空。〔三〕孝景時，嬰嘗受遺詔，曰「事有不便，以便宜論上。」〔四〕及繫，灌夫罪至族，事日急，諸公莫敢復明言於上。嬰乃使昆弟子上書言之，幸得召見。〔五〕書奏，案尚書，大行無遺詔。〔六〕詔書獨臧嬰家，嬰家丞封。〔七〕乃劾嬰矯先帝詔害，罪當棄市。〔八〕五年十月，悉論灌夫支屬。嬰良久乃聞有劾，即陽病痱，不食欲死。〔九〕或聞上無意殺嬰，復食，治病，議定不死矣。乃有飛語為惡言聞上，〔一０〕故以十二月晦論棄市渭城。〔一一〕","sentenceOrder":169},
  {"id":"s_work_han_thu_63_170","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「簿責，以文簿一一責之也。簿音步戶反。」","sentenceOrder":170},
  {"id":"s_work_han_thu_63_171","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　晉灼曰：「讎，當也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_63_172","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「都司空，宗正屬官也，見百官公卿表。」","sentenceOrder":172},
  {"id":"s_work_han_thu_63_173","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　師古曰：「論說其事而上於天子。」","sentenceOrder":173},
  {"id":"s_work_han_thu_63_174","chapterId":"ch_work_han_thu_63","textTraditional":"〔五〕　師古曰：「幸，冀也。」","sentenceOrder":174},
  {"id":"s_work_han_thu_63_175","chapterId":"ch_work_han_thu_63","textTraditional":"〔六〕　如淳曰：「大行，主諸侯官也。」師古曰：「此說非也。大行，景帝大行也。尚書之中無此大行遺詔也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_63_176","chapterId":"ch_work_han_thu_63","textTraditional":"〔七〕　孟康曰：「以家丞印封遺詔也。」","sentenceOrder":176},
  {"id":"s_work_han_thu_63_177","chapterId":"ch_work_han_thu_63","textTraditional":"〔八〕　鄭氏曰：「矯詔有害不害也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_63_178","chapterId":"ch_work_han_thu_63","textTraditional":"〔九〕　師古曰：「痱，風疾也，音肥。」","sentenceOrder":178},
  {"id":"s_work_han_thu_63_179","chapterId":"ch_work_han_thu_63","textTraditional":"〔一０〕張晏曰：「蚡為作飛揚誹謗之語也。」臣瓚曰：「無根而至也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_63_180","chapterId":"ch_work_han_thu_63","textTraditional":"〔一一〕張晏曰：「著日月者，見春垂至，恐遇赦贖之。」","sentenceOrder":180},
  {"id":"s_work_han_thu_63_181","chapterId":"ch_work_han_thu_63","textTraditional":"春，蚡疾，一身盡痛，若有擊者，謼服謝罪。〔一〕上使視鬼者瞻之，曰：「魏其侯與灌夫共守，笞欲殺之。」竟死。子恬嗣，元朔中有罪免。","sentenceOrder":181},
  {"id":"s_work_han_thu_63_182","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　晉灼曰：「服音瓝。關西俗謂得杖呼及小兒啼呼為呼瓝。或言蚡號呼謝服罪也。」師古曰：「兩說皆通。謼，古呼字也。若謂啼為謼服，則謼音火交反，服音平卓反。」","sentenceOrder":182},
  {"id":"s_work_han_thu_63_183","chapterId":"ch_work_han_thu_63","textTraditional":"後淮南王安謀反，覺。始安入朝時，蚡為太尉，迎安霸上，謂安曰：「上未有太子，大王最賢，高祖孫，即（公）〔宮〕車晏駕，非大王立，尚誰立哉？」〔一〕淮南王大喜，厚遺金錢財物。上自嬰、夫事時不直蚡，特為太后故。及聞淮南事，上曰：「使武安侯在者，族矣。」〔二〕","sentenceOrder":183},
  {"id":"s_work_han_thu_63_184","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「言大王尚不得立，當誰立也？」","sentenceOrder":184},
  {"id":"s_work_han_thu_63_185","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「言其賴自死。」","sentenceOrder":185},
  {"id":"s_work_han_thu_63_186","chapterId":"ch_work_han_thu_63","textTraditional":"韓安國字長孺，梁成安人也，後徙睢陽。嘗受韓子、雜說鄒田生所。〔一〕事梁孝王，為中大夫。吳楚反時，孝王使安國及張羽為將，扞吳兵於東界。張羽力戰，安國持重，以故吳不能過梁。吳楚破，安國、張羽名由此顯梁。","sentenceOrder":186},
  {"id":"s_work_han_thu_63_187","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「田生，鄒縣人。」","sentenceOrder":187},
  {"id":"s_work_han_thu_63_188","chapterId":"ch_work_han_thu_63","textTraditional":"梁王以至親故，得自置相、二千石，出入游戲，僭於天子。〔一〕天子聞之，心不善。太后知帝弗善，乃怒梁使者，弗見，案責王所為。安國為梁使，見大長公主而泣〔二〕曰：「何梁王為人子之孝，為人臣之忠，而太后曾不省也？〔三〕夫前日吳、楚、齊、趙七國反，自關以東皆合從而西嚮，〔四〕唯梁最親，為限難。梁王念太后、帝在中，〔五〕而諸侯擾亂，壹言泣數行而下，跪送臣等六人將兵擊卻吳楚，吳楚以故兵不敢西，而卒破亡，梁之力也。今太后以小苛禮責望梁王。〔六〕梁王父兄皆帝王，而所見者大，故出稱〈走畢〉，入言警，〔七〕車旗皆帝所賜，即以嫮鄙小縣，〔八〕驅馳國中，欲夸諸侯，令天下知太后、帝愛之也。今梁使來，輒案責之，梁王恐，日夜涕泣思慕，不知所為。何梁王之忠孝而太后不卹也？」長公主具以告太后，太后喜曰：「為帝言之。」言之，帝心乃解，而免冠謝太后曰：「兄弟不能相教，乃為太后遺憂。」悉見梁使，厚賜之。其後，梁王益親驩。太后、長公主更賜安國直千餘金。〔九〕由此顯，結於漢。","sentenceOrder":188},
  {"id":"s_work_han_thu_63_189","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「僭，擬也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_63_190","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　如淳曰：「大長公主，景帝姊也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_63_191","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「省，視也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_63_192","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　師古曰：「從音子容反。」","sentenceOrder":192},
  {"id":"s_work_han_thu_63_193","chapterId":"ch_work_han_thu_63","textTraditional":"〔五〕　師古曰：「中，關中也。一說謂京師為中，猶言中國也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_63_194","chapterId":"ch_work_han_thu_63","textTraditional":"〔六〕　師古曰：「苛，細也。」","sentenceOrder":194},
  {"id":"s_work_han_thu_63_195","chapterId":"ch_work_han_thu_63","textTraditional":"〔七〕　師古曰：「〈走畢〉，止行人也。警，令戒肅也。天子出入皆備此儀。而今云出稱警入言〈走畢〉者，互舉之耳。」","sentenceOrder":195},
  {"id":"s_work_han_thu_63_196","chapterId":"ch_work_han_thu_63","textTraditional":"〔八〕　服虔曰：「嫮，夸奼也。」晉灼曰：「嫮音坼嫮之嫮。」鄧展曰：「嫮，好也。自以車服之好曜邊鄙之邑也。」師古曰：「服說、晉音是也。鄙，小縣，言在外鄙之小縣也。」","sentenceOrder":196},
  {"id":"s_work_han_thu_63_197","chapterId":"ch_work_han_thu_63","textTraditional":"〔九〕　師古曰：「更音工衡反。」","sentenceOrder":197},
  {"id":"s_work_han_thu_63_198","chapterId":"ch_work_han_thu_63","textTraditional":"其後，安國坐法抵罪，蒙〔一〕獄吏田甲辱安國。安國曰：「死灰獨不復然乎？」甲曰：「然即溺之。」〔二〕居無幾，梁內史缺，〔三〕漢使使者拜安國為梁內史，起（徙）〔徒〕中為二千石。田甲亡。安國曰：「甲不就官，我滅而宗。」（四）甲肉袒謝，安國笑曰：「公等足與治乎？」〔五〕卒善遇之。","sentenceOrder":198},
  {"id":"s_work_han_thu_63_199","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「蒙，梁國之縣也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_63_200","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「溺讀曰尿。」","sentenceOrder":200},
  {"id":"s_work_han_thu_63_201","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「無幾，未多時也。幾音居豈反。」","sentenceOrder":201},
  {"id":"s_work_han_thu_63_202","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　師古曰：「而，汝也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_63_203","chapterId":"ch_work_han_thu_63","textTraditional":"〔五〕　師古曰：「治謂當敵也，今人猶云對治。治音丈吏反。一曰，不足繩治也。治讀如本字。」","sentenceOrder":203},
  {"id":"s_work_han_thu_63_204","chapterId":"ch_work_han_thu_63","textTraditional":"內史之缺也，王新得齊人公孫詭，說之，〔一〕欲請為內史。竇太后（所）〔聞〕，乃詔王以安國為內史。","sentenceOrder":204},
  {"id":"s_work_han_thu_63_205","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":205},
  {"id":"s_work_han_thu_63_206","chapterId":"ch_work_han_thu_63","textTraditional":"公孫詭、羊勝說王求為帝太子及益地事，恐漢大臣不聽，乃陰使人刺漢用事謀臣。及殺故吳相爰盎，景帝遂聞詭、勝等計畫，乃遣使捕詭、勝，必得。〔一〕漢使十輩至梁，相以下舉國大索，〔二〕月餘弗得。安國聞詭、勝匿王所，乃入見王而泣曰：「主辱者臣死。大王無良臣，故紛紛至此。今勝、詭不得，請辭賜死。」王曰：「何至此？」安國泣數行下，曰：「大王自度於皇帝，孰與太上皇之與高帝及皇帝與臨江王親？」〔三〕王曰：「弗如也。」安國曰：「夫太上皇、臨江親父子間，然高帝曰『提三尺取天下者朕也』，〔四〕故太上終不得制事，居于櫟陽。臨江，適長太子，〔五〕以一言過，廢王臨江；〔六〕用宮垣事，卒自殺中尉府。〔七〕何則？治天下終不用私亂公。語曰：『雖有親父，安知不為虎？雖有親兄，安知不為狼？』〔八〕今大王列在諸侯，訹邪臣浮說，〔九〕犯上禁，橈明法〔一０〕。天子以太后故，不忍致法於大王。太后日夜涕泣，幸大王自改，大王終不覺寤。有如太后宮車即晏駕，大王尚誰攀乎？」語未卒，王泣數行而下，謝安國曰：「吾今出之。」即日詭、勝自殺。漢使還報，梁事皆得釋，〔一一〕安國力也。景帝、太后益重安國。","sentenceOrder":206},
  {"id":"s_work_han_thu_63_207","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「必令得之。」","sentenceOrder":207},
  {"id":"s_work_han_thu_63_208","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「索，搜也，音山客反。」","sentenceOrder":208},
  {"id":"s_work_han_thu_63_209","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「孰與，猶言何如也。」","sentenceOrder":209},
  {"id":"s_work_han_thu_63_210","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　師古曰：「三尺，謂劍也。」","sentenceOrder":210},
  {"id":"s_work_han_thu_63_211","chapterId":"ch_work_han_thu_63","textTraditional":"〔五〕　師古曰：「適讀曰嫡。」","sentenceOrder":211},
  {"id":"s_work_han_thu_63_212","chapterId":"ch_work_han_thu_63","textTraditional":"〔六〕　師古曰：「景帝嘗屬諸姬子，太子母栗姬言不遜，由是廢太子，栗姬憂死也。」","sentenceOrder":212},
  {"id":"s_work_han_thu_63_213","chapterId":"ch_work_han_thu_63","textTraditional":"〔七〕　張晏曰：「以侵堧垣徵，自殺也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_63_214","chapterId":"ch_work_han_thu_63","textTraditional":"〔八〕　師古曰：「言其恩愛不可必保也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_63_215","chapterId":"ch_work_han_thu_63","textTraditional":"〔九〕　師古曰：「訹，誘也，音戍。」","sentenceOrder":215},
  {"id":"s_work_han_thu_63_216","chapterId":"ch_work_han_thu_63","textTraditional":"〔一０〕師古曰：「橈，曲也，音女教反。」","sentenceOrder":216},
  {"id":"s_work_han_thu_63_217","chapterId":"ch_work_han_thu_63","textTraditional":"〔一一〕師古曰：「釋，解也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_63_218","chapterId":"ch_work_han_thu_63","textTraditional":"孝王薨，共王即位，〔一〕安國坐法失官，家居。武帝即位，武安侯田蚡為太尉，親貴用事。安國以五百金遺蚡，蚡言安國太后，上素聞安國賢，即召以為北地都尉，遷為太司農。閩、東越相攻，遣安國、大行王恢將兵。未至越，越殺其王降，漢兵亦罷。其年，田蚡為丞相，安國為御史大夫。","sentenceOrder":218},
  {"id":"s_work_han_thu_63_219","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「共讀曰恭。」","sentenceOrder":219},
  {"id":"s_work_han_thu_63_220","chapterId":"ch_work_han_thu_63","textTraditional":"匈奴來請和親，上下其議。〔一〕大行王恢，燕人，數為邊吏，習胡事，議曰：「漢與匈奴和親，率不過數歲即背約。不如勿許，舉兵擊之。」安國曰：「千里而戰，即兵不獲利。今匈奴負戎馬足，懷鳥獸心，〔二〕遷徙鳥集，難得而制。得其地不足為廣，有其眾不足為彊，自上古弗屬。〔三〕漢數千里爭利，則人馬罷，〔四〕虜以全制其敝，勢必危殆。臣故以為不如和親。」群臣議多附安國，於是上許和親。","sentenceOrder":220},
  {"id":"s_work_han_thu_63_221","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「下音胡亞反。」","sentenceOrder":221},
  {"id":"s_work_han_thu_63_222","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「負，恃也。」","sentenceOrder":222},
  {"id":"s_work_han_thu_63_223","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「不內屬於中國。」","sentenceOrder":223},
  {"id":"s_work_han_thu_63_224","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　師古曰：「罷讀曰疲。」","sentenceOrder":224},
  {"id":"s_work_han_thu_63_225","chapterId":"ch_work_han_thu_63","textTraditional":"明年，雁門馬邑豪聶壹〔一〕因大行王恢言：「匈奴初和親，親信邊，可誘以利致之，伏兵襲擊，必破之道也。」上乃召問公卿曰：「朕飾子女以配單于，幣帛文錦，賂之甚厚。單于待命加嫚，侵盜無已，邊竟數驚，朕甚閔之。〔二〕今欲舉兵攻之，何如？」","sentenceOrder":225},
  {"id":"s_work_han_thu_63_226","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　張晏曰：「豪猶帥也。」","sentenceOrder":226},
  {"id":"s_work_han_thu_63_227","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「竟讀曰境。其下亦同。」","sentenceOrder":227},
  {"id":"s_work_han_thu_63_228","chapterId":"ch_work_han_thu_63","textTraditional":"大行恢對曰：「陛下雖未言，臣固願效之。〔一〕臣聞全代之時，〔二〕北有彊胡之敵，內連中國之兵，然尚得養老長幼，種樹以時，倉廩常實，〔三〕匈奴不輕侵也。今以陛下之威，海內為一，天下同任，〔四〕又遣子弟乘邊守塞，〔五〕轉粟輓輸，以為之備，〔六〕然匈奴侵盜不已者，無它，以不恐之故耳。〔七〕臣竊以為擊之便。」","sentenceOrder":228},
  {"id":"s_work_han_thu_63_229","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「效，致也，致其計。」","sentenceOrder":229},
  {"id":"s_work_han_thu_63_230","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　服虔曰：「代未分之時也。」李奇曰：「六國之時全代為一國，尚能以擊匈奴，況今加以漢之大乎！」","sentenceOrder":230},
  {"id":"s_work_han_thu_63_231","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「樹，殖也。」","sentenceOrder":231},
  {"id":"s_work_han_thu_63_232","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　如淳曰：「任，事也。」","sentenceOrder":232},
  {"id":"s_work_han_thu_63_233","chapterId":"ch_work_han_thu_63","textTraditional":"〔五〕　師古曰：「乘，登也。登其城而備守也。」","sentenceOrder":233},
  {"id":"s_work_han_thu_63_234","chapterId":"ch_work_han_thu_63","textTraditional":"〔六〕　師古曰：「輓，引車也，音晚。」","sentenceOrder":234},
  {"id":"s_work_han_thu_63_235","chapterId":"ch_work_han_thu_63","textTraditional":"〔七〕　師古曰：「不示威令恐懼也。」","sentenceOrder":235},
  {"id":"s_work_han_thu_63_236","chapterId":"ch_work_han_thu_63","textTraditional":"御史大夫安國曰：「不然。臣聞高皇帝嘗圍於平城，匈奴至者投鞍高如城者數所。〔一〕平城之飢，七日不食，天下歌之，及解圍反位，而無忿怒之心。夫聖人以天下為度者也，〔二〕不以己私怒傷天下之功，故乃遣劉敬奉金千斤，以結和親，至今為五世利。孝文皇帝又嘗壹擁天下之精兵聚之廣武常谿，〔三〕然終無尺寸之功，而天下黔首無不憂者。孝文寤於兵之不可宿，〔四〕故復合和親之約。此二聖之跡，足以為效矣。臣竊以為勿擊便。」","sentenceOrder":236},
  {"id":"s_work_han_thu_63_237","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「解脫其馬，示閑暇也。投積其鞍，若營壘也。」","sentenceOrder":237},
  {"id":"s_work_han_thu_63_238","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「言當隨天下人心而寬大其度量也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_63_239","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　張晏曰：「廣武，雁門縣。常谿，谿名。」","sentenceOrder":239},
  {"id":"s_work_han_thu_63_240","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　師古曰：「宿，久留也。」","sentenceOrder":240},
  {"id":"s_work_han_thu_63_241","chapterId":"ch_work_han_thu_63","textTraditional":"恢曰：「不然。臣聞五帝不相襲禮，三王不相復樂，〔一〕非故相反也，各因世宜也。且高帝身被堅執銳，蒙霧露，沐霜雪，行幾十年，〔二〕所以不報平城之怨者，非力不能，所以休天下之心也。今邊竟數驚，士卒傷死，中國槥車相望，〔三〕此仁人之所隱也。〔四〕臣故曰擊之便。」","sentenceOrder":241},
  {"id":"s_work_han_thu_63_242","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「襲，因也。復，重也。復音扶目反。」","sentenceOrder":242},
  {"id":"s_work_han_thu_63_243","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「幾，近也，音鉅依反。」","sentenceOrder":243},
  {"id":"s_work_han_thu_63_244","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「槥，小棺也。從軍死者以槥送致其喪，載槥之車相望於道，言其多也。槥音衛。」","sentenceOrder":244},
  {"id":"s_work_han_thu_63_245","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　張晏曰：「隱，痛也。」","sentenceOrder":245},
  {"id":"s_work_han_thu_63_246","chapterId":"ch_work_han_thu_63","textTraditional":"安國曰：「不然。臣聞利不十者不易業，功不百者不變常，是以古之人君謀事必就祖，發政占古語，重作事也。〔一〕且自三代之盛，夷狄不與正朔服色，〔二〕非威不能制，彊弗能服也，以為遠方絕地不牧之民，不足煩中國也。〔三〕且匈奴，輕疾悍亟之兵也，〔四〕至如猋風，去如收電，〔五〕畜牧為業，弧弓射獵，〔六〕逐獸隨草，居處無常，難得而制。今使邊郡久廢耕織，以支胡之常事，其勢不相權也。〔七〕臣故曰勿擊便。」","sentenceOrder":246},
  {"id":"s_work_han_thu_63_247","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「祖，祖廟也。占，問也。重猶難之也。」","sentenceOrder":247},
  {"id":"s_work_han_thu_63_248","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「與讀曰豫。」","sentenceOrder":248},
  {"id":"s_work_han_thu_63_249","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「不牧，謂不可牧養也。」","sentenceOrder":249},
  {"id":"s_work_han_thu_63_250","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　師古曰：「悍，勇也。亟，急也，音居力反。」","sentenceOrder":250},
  {"id":"s_work_han_thu_63_251","chapterId":"ch_work_han_thu_63","textTraditional":"〔五〕　師古曰：「猋，疾風也，音必遙反。」","sentenceOrder":251},
  {"id":"s_work_han_thu_63_252","chapterId":"ch_work_han_thu_63","textTraditional":"〔六〕　師古曰：「以木曰弧，以角曰弓。」","sentenceOrder":252},
  {"id":"s_work_han_thu_63_253","chapterId":"ch_work_han_thu_63","textTraditional":"〔七〕　師古曰：「輕重不等也。」","sentenceOrder":253},
  {"id":"s_work_han_thu_63_254","chapterId":"ch_work_han_thu_63","textTraditional":"恢曰：「不然。臣聞鳳鳥乘於風，聖人因於時。昔秦繆公都雍，〔一〕地方三百里，知時宜之變，攻取西戎，辟地千里，并國十四，〔二〕隴西、北地是也。及後蒙恬為秦侵胡，辟數千里，以河為竟，〔三〕累石為城，樹榆為塞，〔四〕匈奴不敢飲馬於河，置｛逢火｝{隊火}然後敢牧馬。〔五〕夫匈奴獨可以威服，不可以仁畜也。今以中國之盛，萬倍之資，遣百分之一以攻匈奴，譬猶以彊弩射且潰之癰也，必不留行矣。〔六〕若是，則北發月氏可得而臣也。〔七〕臣故曰擊之便。」","sentenceOrder":254},
  {"id":"s_work_han_thu_63_255","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「繆讀與穆同。」","sentenceOrder":255},
  {"id":"s_work_han_thu_63_256","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「辟讀曰闢。次下亦同。」","sentenceOrder":256},
  {"id":"s_work_han_thu_63_257","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「竟讀曰境。」","sentenceOrder":257},
  {"id":"s_work_han_thu_63_258","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　如淳曰：「塞上種榆也。」","sentenceOrder":258},
  {"id":"s_work_han_thu_63_259","chapterId":"ch_work_han_thu_63","textTraditional":"〔五〕　師古曰：「{隊火}，古燧字。」","sentenceOrder":259},
  {"id":"s_work_han_thu_63_260","chapterId":"ch_work_han_thu_63","textTraditional":"〔六〕　師古曰：「留，止也。言無所礙也。」","sentenceOrder":260},
  {"id":"s_work_han_thu_63_261","chapterId":"ch_work_han_thu_63","textTraditional":"〔七〕　師古曰：「發猶徵召也。言威聲之盛，北自月支以來皆可徵召而為臣也。氏讀曰支。」","sentenceOrder":261},
  {"id":"s_work_han_thu_63_262","chapterId":"ch_work_han_thu_63","textTraditional":"安國曰：「不然。臣聞用兵者以飽待饑，正治以待其亂，定舍以待其勞。〔一〕故接兵覆眾，伐國墮城，〔二〕常坐而役敵國，此聖人之兵也。且臣聞之，衝風之衰，不能起毛羽；〔三〕彊弩之末，力不能入魯縞。〔四〕夫盛之有衰，猶朝之必莫也。今將卷甲輕舉，深入長敺，難以為功；〔五〕從行則迫脅，衡行則中絕，〔六〕疾則糧乏，徐則後利，〔七〕不至千里，人馬乏食。兵法曰：『遺人獲也。』〔八〕意者有它繆巧可以禽之，則臣不知也；不然，則未見深入之利也。臣故曰勿擊便。」","sentenceOrder":262},
  {"id":"s_work_han_thu_63_263","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「舍，止息也。」","sentenceOrder":263},
  {"id":"s_work_han_thu_63_264","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「覆，敗也。墮，毀也。言兵與敵接則敗其眾，所伐之國則毀其城也。覆音芳目反。墮音火規反。」","sentenceOrder":264},
  {"id":"s_work_han_thu_63_265","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「衝風，疾風之衝突者也。」","sentenceOrder":265},
  {"id":"s_work_han_thu_63_266","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　師古曰：「縞，素也，曲阜之地，俗善作之，尤為輕細，故以取喻也。」","sentenceOrder":266},
  {"id":"s_work_han_thu_63_267","chapterId":"ch_work_han_thu_63","textTraditional":"〔五〕　師古曰：「敺與驅同。」","sentenceOrder":267},
  {"id":"s_work_han_thu_63_268","chapterId":"ch_work_han_thu_63","textTraditional":"〔六〕　師古曰：「從音子容反。衡猶橫也。」","sentenceOrder":268},
  {"id":"s_work_han_thu_63_269","chapterId":"ch_work_han_thu_63","textTraditional":"〔七〕　師古曰：「後利，謂不及於利。」","sentenceOrder":269},
  {"id":"s_work_han_thu_63_270","chapterId":"ch_work_han_thu_63","textTraditional":"〔八〕　師古曰：「言以軍遺敵人，令其虜獲也。遺音弋季反。」","sentenceOrder":270},
  {"id":"s_work_han_thu_63_271","chapterId":"ch_work_han_thu_63","textTraditional":"恢曰：「不然。夫草木遭霜者不可以風過，〔一〕清水明鏡不可以形逃，〔二〕通方之士，不可以文亂。〔三〕今臣言擊之者，固非發而深入也，將順因單于之欲，誘而致之邊，吾選梟騎或絕其後，單于可禽，百全必取。」","sentenceOrder":271},
  {"id":"s_work_han_thu_63_272","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「言易零落。」","sentenceOrder":272},
  {"id":"s_work_han_thu_63_273","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「言美惡皆見。」","sentenceOrder":273},
  {"id":"s_work_han_thu_63_274","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「方，道也。」","sentenceOrder":274},
  {"id":"s_work_han_thu_63_275","chapterId":"ch_work_han_thu_63","textTraditional":"上曰：「善。」乃從恢議。陰使聶壹為間，〔一〕亡入匈奴，謂單于曰：「吾能斬馬邑令丞，以城降，財物可盡得。」單于愛信，以為然而許之。聶壹乃詐斬死罪囚，縣其頭馬邑城下，視單于使者為信，〔二〕曰：「馬邑長吏已死，可急來。」於是單于穿塞，將十萬騎入武州塞。〔三〕","sentenceOrder":275},
  {"id":"s_work_han_thu_63_276","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「間音居莧反。」","sentenceOrder":276},
  {"id":"s_work_han_thu_63_277","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「視讀曰示。」","sentenceOrder":277},
  {"id":"s_work_han_thu_63_278","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「在雁門。」","sentenceOrder":278},
  {"id":"s_work_han_thu_63_279","chapterId":"ch_work_han_thu_63","textTraditional":"當是時，漢伏兵車騎材官三十餘萬，匿馬邑旁谷中。衛尉李廣為驍騎將軍，太僕公孫賀為輕車將軍，大行王恢為將屯將軍，太中大夫李息為材官將軍。御史大夫安國為護軍將軍，諸將皆屬。約單于入馬邑縱兵。王恢、李息別從代主擊輜重。〔一〕於是單于入塞，未至馬邑百餘里，覺之，還去。語在匈奴傳。塞下傳言單于已去，漢兵追至塞，度弗及，〔二〕王恢等皆罷兵。","sentenceOrder":279},
  {"id":"s_work_han_thu_63_280","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「輜，衣車也。重謂載重物車也。故行者之資，總曰輜重。重音直用反。」","sentenceOrder":280},
  {"id":"s_work_han_thu_63_281","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「度，音徒各反。」","sentenceOrder":281},
  {"id":"s_work_han_thu_63_282","chapterId":"ch_work_han_thu_63","textTraditional":"上怒恢不出擊單于輜重也，恢曰：「始約為入馬邑城，兵與單于接，而臣擊其輜重，可得利。今單于不至而還，臣以三萬人眾不敵，祗取辱。〔一〕固知還而斬，然完陛下士三萬人。」於是下恢廷尉，廷尉當恢逗橈，當斬。〔二〕恢行千金丞相蚡。蚡不敢言上，而言於太后曰：「王恢首為馬邑事，今不成而誅恢，是為匈奴報仇也。」上朝太后，太后以蚡言告上。上曰：「首為馬邑事者恢，故發天下兵數十萬，從其言，為此。且縱單于不可得，恢所部擊，猶頗可得，以尉士大夫心。〔三〕今不誅恢，無以謝天下。」於是恢聞，乃自殺。","sentenceOrder":282},
  {"id":"s_work_han_thu_63_283","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「祗，適也，音支。」","sentenceOrder":283},
  {"id":"s_work_han_thu_63_284","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　服虔曰：「逗音企。」應劭曰：「逗，曲行避敵也，橈，顧望也，軍法語也。」蘇林曰：「逗音豆。」如淳曰：「軍法，行而逗留畏懦者要斬。」師古曰：「服、應二說皆非也。逗謂留止也。橈，屈弱也。逗又音住。」","sentenceOrder":284},
  {"id":"s_work_han_thu_63_285","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「或當得其輜重人眾也。（故）〔古〕尉安之字正如此，其後流俗乃加心耳。」","sentenceOrder":285},
  {"id":"s_work_han_thu_63_286","chapterId":"ch_work_han_thu_63","textTraditional":"安國為人多大略，知足以當世取舍，〔一〕而出於忠厚。貪耆財利，〔二〕然所推舉皆廉士賢於己者。於梁舉壺遂、臧固，至它，皆天下名士，〔三〕士亦以此稱慕之，唯天子以為國器。〔四〕安國為御史大夫五年，丞相蚡薨。安國行丞相事，引墮車，蹇。〔五〕上欲用安國為丞相，使使視，蹇甚，乃更以平棘侯薛澤為丞相。安國病免，〔六〕數月，瘉，復為中尉。","sentenceOrder":286},
  {"id":"s_work_han_thu_63_287","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「舍，止也。取舍，言可取則取，可止則止。」","sentenceOrder":287},
  {"id":"s_work_han_thu_63_288","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「耆讀曰嗜。」","sentenceOrder":288},
  {"id":"s_work_han_thu_63_289","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「於梁舉二人，至於他餘所舉，亦皆名士也。」","sentenceOrder":289},
  {"id":"s_work_han_thu_63_290","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　師古曰：「言臣下皆敬重之，天子一人亦以為國器。國器者，言其器用重大，可施於國政也。」","sentenceOrder":290},
  {"id":"s_work_han_thu_63_291","chapterId":"ch_work_han_thu_63","textTraditional":"〔五〕　如淳曰：「為天子（尊）〔導〕引，而墮車跛蹇也。」","sentenceOrder":291},
  {"id":"s_work_han_thu_63_292","chapterId":"ch_work_han_thu_63","textTraditional":"〔六〕　師古曰：「以足疾。」","sentenceOrder":292},
  {"id":"s_work_han_thu_63_293","chapterId":"ch_work_han_thu_63","textTraditional":"歲餘，徙為衛尉。而將軍衛青等擊匈奴，破龍城。明年，匈奴大入邊。語在青傳。安國為材官將軍，屯漁陽，捕生口虜，言匈奴遠去。即上言方佃作時，〔一〕請且罷屯。罷屯月餘，匈奴大入上谷、漁陽。安國壁乃有七百餘人，出與戰，安國傷，入壁。匈奴虜略千餘人及畜產去。上怒，使使責讓安國。徙益東，屯右北平。是時虜言當入東方。","sentenceOrder":293},
  {"id":"s_work_han_thu_63_294","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「安國上奏也。佃，治田也，音與田同。」","sentenceOrder":294},
  {"id":"s_work_han_thu_63_295","chapterId":"ch_work_han_thu_63","textTraditional":"安國始為御史大夫及護軍，後稍下遷。新壯將軍衛青等有功，益貴。安國既斥疏，將屯又失亡多，甚自媿。幸得罷歸，〔一〕乃益東徙，意忽忽不樂，數月，病歐血死。","sentenceOrder":295},
  {"id":"s_work_han_thu_63_296","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰；「冀得罷歸，以徼幸也。他皆類此。」","sentenceOrder":296},
  {"id":"s_work_han_thu_63_297","chapterId":"ch_work_han_thu_63","textTraditional":"壺遂與太史遷等定漢律曆，官至詹事，其人深中篤行君子。上方倚欲以為相，會其病卒。〔一〕","sentenceOrder":297},
  {"id":"s_work_han_thu_63_298","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「倚謂仗任之也，音於綺反。」","sentenceOrder":298},
  {"id":"s_work_han_thu_63_299","chapterId":"ch_work_han_thu_63","textTraditional":"贊曰：竇嬰、田蚡皆以外戚重，灌夫用一時決策，〔一〕而各名顯，並位卿相，大業定矣。然嬰不知時變，夫亡術而不遜，〔二〕蚡負貴而驕溢。〔三〕凶德參會，待時而發，〔四〕藉福區區其間，惡能救斯敗哉！〔五〕以韓安國之見器，臨其摯而顛墜，〔六〕陵夷以憂死，〔七〕遇合有命，悲夫！若王恢為兵首而受其咎，豈命也虖？〔八〕","sentenceOrder":299},
  {"id":"s_work_han_thu_63_300","chapterId":"ch_work_han_thu_63","textTraditional":"〔一〕　師古曰：「謂馳入吳軍，欲報父讎也。」","sentenceOrder":300},
  {"id":"s_work_han_thu_63_301","chapterId":"ch_work_han_thu_63","textTraditional":"〔二〕　師古曰：「遜，順也。」","sentenceOrder":301},
  {"id":"s_work_han_thu_63_302","chapterId":"ch_work_han_thu_63","textTraditional":"〔三〕　師古曰：「負，恃也。」","sentenceOrder":302},
  {"id":"s_work_han_thu_63_303","chapterId":"ch_work_han_thu_63","textTraditional":"〔四〕　師古曰：「三人相遇，故曰參會。」","sentenceOrder":303},
  {"id":"s_work_han_thu_63_304","chapterId":"ch_work_han_thu_63","textTraditional":"〔五〕　師古曰：「惡音烏，謂於何也。」","sentenceOrder":304},
  {"id":"s_work_han_thu_63_305","chapterId":"ch_work_han_thu_63","textTraditional":"〔六〕　李奇曰：「摯，極也。」","sentenceOrder":305},
  {"id":"s_work_han_thu_63_306","chapterId":"ch_work_han_thu_63","textTraditional":"〔七〕　師古曰：「陵夷，即陵遲也，言漸卑替也。」","sentenceOrder":306},
  {"id":"s_work_han_thu_63_307","chapterId":"ch_work_han_thu_63","textTraditional":"〔八〕　師古曰：「言自己為之，非由命也。」","sentenceOrder":307},
  {"id":"s_work_han_thu_63_308","chapterId":"ch_work_han_thu_63","textTraditional":"校勘記","sentenceOrder":308},
  {"id":"s_work_han_thu_63_309","chapterId":"ch_work_han_thu_63","textTraditional":"二三七七頁　二行　（敬）〔故〕曰栗太子。　景祐、殿本都作「故」，此誤。","sentenceOrder":309},
  {"id":"s_work_han_thu_63_310","chapterId":"ch_work_han_thu_63","textTraditional":"二三八一頁　七行　言為諸第之（長）〔最〕也。　景祐、殿本都作「最」。","sentenceOrder":310},
  {"id":"s_work_han_thu_63_311","chapterId":"ch_work_han_thu_63","textTraditional":"二三八一頁一三行　諸公稍自引而怠（〈忄臺〉）〔驁〕，　景祐、殿本都作「驁」，注同。王先謙說作「驁」是。","sentenceOrder":311},
  {"id":"s_work_han_thu_63_312","chapterId":"ch_work_han_thu_63","textTraditional":"二三八二頁　一行　（常）〔嘗〕為潁陰侯灌嬰舍人，　宋祁說南本、浙本「常」並作「嘗」。王先謙說南、浙本是。","sentenceOrder":312},
  {"id":"s_work_han_thu_63_313","chapterId":"ch_work_han_thu_63","textTraditional":"二三八二頁　八行　吳軍（敗）〔破〕，　景祐、殿本都作「破」。","sentenceOrder":313},
  {"id":"s_work_han_thu_63_314","chapterId":"ch_work_han_thu_63","textTraditional":"二三八五頁　四行　夜洒埽張具至旦。〔八〕　注〔八〕原在「張具」下。王先謙說，「至旦」二字連上為文，言嬰洒埽張具，自夜達旦。","sentenceOrder":314},
  {"id":"s_work_han_thu_63_315","chapterId":"ch_work_han_thu_63","textTraditional":"二三八七頁一０行　「今日召宗室，有詔」，〔一七〕　注〔一七〕原在「宗室」下，景祐、汲古、局本同。今從殿本，以「有詔」連上，蚡與長史語止此。","sentenceOrder":315},
  {"id":"s_work_han_thu_63_316","chapterId":"ch_work_han_thu_63","textTraditional":"二三八八頁一七行　於大坐中罵詈（不為）〔為不〕敬。　景祐、殿本都作「為不」。","sentenceOrder":316},
  {"id":"s_work_han_thu_63_317","chapterId":"ch_work_han_thu_63","textTraditional":"二三八九頁一二行　蚡得為（胏）〔肺〕附，　殿本「胏」作「肺」，與上蚡傳同。而此及景祐本都作「胏」，與蚡傳異。「肺」「胏」蓋一字之異體。","sentenceOrder":317},
  {"id":"s_work_han_thu_63_318","chapterId":"ch_work_han_thu_63","textTraditional":"二三九三頁一四行　即（公）〔宮〕車晏駕，　景祐、殿本都作「宮」，史記同。王先謙說作「宮」是。","sentenceOrder":318},
  {"id":"s_work_han_thu_63_319","chapterId":"ch_work_han_thu_63","textTraditional":"二三九五頁一四行　起（徙）〔徒〕中為二千石。景祐、殿本都作「徒」，史記同，此誤。","sentenceOrder":319},
  {"id":"s_work_han_thu_63_320","chapterId":"ch_work_han_thu_63","textTraditional":"二三九六頁　六行　竇太后（所）〔聞〕，乃詔王以安國為內史。　楊樹達說「所」是誤字，當從史記作「聞」。","sentenceOrder":320},
  {"id":"s_work_han_thu_63_321","chapterId":"ch_work_han_thu_63","textTraditional":"二四０五頁　七行　（故）〔古〕尉安之字正如此，　景祐、殿本都作「古」。王先謙說作「古」是。","sentenceOrder":321},
  {"id":"s_work_han_thu_63_322","chapterId":"ch_work_han_thu_63","textTraditional":"二四０五頁一六行　為天子（尊）〔導〕引，　景祐、殿本都作「導」，此誤。","sentenceOrder":322},
  {"id":"s_work_han_thu_64_1","chapterId":"ch_work_han_thu_64","textTraditional":"孝景皇帝十四男。王皇后生孝武皇帝。栗姬生臨江閔王榮、河間獻王德、臨江哀王閼。〔一〕程姬生魯共王餘、〔二〕江都易王非、〔三〕膠西于王端。〔四〕賈夫人生趙敬肅王彭祖、中山靖王勝。唐姬生長沙定王發。王夫人生廣川惠王越、膠東康王寄、清河哀王乘、常山憲王舜。〔五〕","sentenceOrder":1},
  {"id":"s_work_han_thu_64_2","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「閼音烏葛反。」","sentenceOrder":2},
  {"id":"s_work_han_thu_64_3","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「共讀曰恭。下皆類此。」","sentenceOrder":3},
  {"id":"s_work_han_thu_64_4","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「易音改易之易。諡法云『好更故舊曰易』。」","sentenceOrder":4},
  {"id":"s_work_han_thu_64_5","chapterId":"ch_work_han_thu_64","textTraditional":"〔四〕　師古曰：「于，遠也，言其所行不善，遠乖道德，故以為諡。」","sentenceOrder":5},
  {"id":"s_work_han_thu_64_6","chapterId":"ch_work_han_thu_64","textTraditional":"〔五〕　師古曰：「王夫人，即王皇后之妹也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_64_7","chapterId":"ch_work_han_thu_64","textTraditional":"河間獻王德以孝景前二年立，修學好古，實事求是。〔一〕從民得善書，必為好寫與之，留其真，〔二〕加金帛賜以招之。繇是四方道術之人不遠千里，〔三〕或有先祖舊書，多奉以奏獻王者，〔四〕故得書多，與漢朝等。是時，淮南王安亦好書，所招致率多浮辯〔五〕。獻王所得書皆古文先秦舊書，〔六〕周官、尚書、禮、禮記〔七〕、孟子、老子之屬，皆經傳說記，七十子之徒所論。〔八〕其學舉六藝，〔九〕立毛氏詩、左氏春秋博士。修禮樂，被服儒術，造次必於儒者。〔一０〕山東諸儒（者）〔多〕從而游。","sentenceOrder":7},
  {"id":"s_work_han_thu_64_8","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「務得事實，每求真是也。今流俗書本云求長長老，以是從人得善書，蓋妄加之耳。」","sentenceOrder":8},
  {"id":"s_work_han_thu_64_9","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「真，正也。留其正本。」","sentenceOrder":9},
  {"id":"s_work_han_thu_64_10","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「不以千里為遠，而自致也。繇與由同。」","sentenceOrder":10},
  {"id":"s_work_han_thu_64_11","chapterId":"ch_work_han_thu_64","textTraditional":"〔四〕　師古曰：「奏，進也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_64_12","chapterId":"ch_work_han_thu_64","textTraditional":"〔五〕　師古曰：「言無實用耳。」","sentenceOrder":12},
  {"id":"s_work_han_thu_64_13","chapterId":"ch_work_han_thu_64","textTraditional":"〔六〕　師古曰：「先秦，猶言秦先，謂未焚書之前。」","sentenceOrder":13},
  {"id":"s_work_han_thu_64_14","chapterId":"ch_work_han_thu_64","textTraditional":"〔七〕　師古曰：「禮者，禮經也。禮記者，諸儒記禮之說也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_64_15","chapterId":"ch_work_han_thu_64","textTraditional":"〔八〕　師古曰：「七十子，孔子弟子也，解具在藝文志。」","sentenceOrder":15},
  {"id":"s_work_han_thu_64_16","chapterId":"ch_work_han_thu_64","textTraditional":"〔九〕　師古曰：「此六藝謂六經。」","sentenceOrder":16},
  {"id":"s_work_han_thu_64_17","chapterId":"ch_work_han_thu_64","textTraditional":"〔一０〕師古曰：「被服，言常居處其中也。造次，謂所嚮（必）〔所〕行也。被音皮義反。造音千到反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_64_18","chapterId":"ch_work_han_thu_64","textTraditional":"武帝時，獻王來朝，獻雅樂，對三雍宮〔一〕及詔策所問三十餘事。其對推道術而言，得事之中，〔二〕文約指明。〔三〕","sentenceOrder":18},
  {"id":"s_work_han_thu_64_19","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　應劭曰：「辟雍、明堂、靈臺也。雍，和也，言天地君臣人民皆和也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_64_20","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「中音竹仲反。」","sentenceOrder":20},
  {"id":"s_work_han_thu_64_21","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「約，少也。指謂義之所趨，若人以手指物也。他皆類此。」","sentenceOrder":21},
  {"id":"s_work_han_thu_64_22","chapterId":"ch_work_han_thu_64","textTraditional":"立二十六年薨。中尉常麗以聞，曰：「王身端行治，〔一〕溫仁恭儉，篤敬愛下，明知深察，惠于鰥寡。」大行令奏：「諡法曰『聰明睿知曰獻』，〔二〕宜諡曰獻王。」子共王不害嗣，四年薨。子剛王堪嗣，十二年薨。子頃王授嗣，〔三〕十七年薨。子孝王慶嗣，四十三年薨。子元嗣。","sentenceOrder":22},
  {"id":"s_work_han_thu_64_23","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「端，直；治，理也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_64_24","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「睿，深也，通也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_64_25","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「頃音傾。諸為諡者，皆類此也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_64_26","chapterId":"ch_work_han_thu_64","textTraditional":"元取故廣陵厲王、厲王太子及中山懷王故姬廉等以為姬。甘露中，冀州刺史敞奏元，事下廷尉，逮召廉等。元迫脅凡七人，令自殺。有司奏請誅元，有詔削二縣，萬一千戶。後元怒少史留貴，留貴踰垣出，欲告元，元使人殺留貴母。有司奏元殘賊不改，不可君國子民。廢勿王，處漢中房陵。〔一〕居數年，坐與妻若共乘朱輪車，怒若，又笞擊，令自髡。漢中太守請治（元），病死。立十七年，國除。","sentenceOrder":26},
  {"id":"s_work_han_thu_64_27","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「房陵，漢中縣。」","sentenceOrder":27},
  {"id":"s_work_han_thu_64_28","chapterId":"ch_work_han_thu_64","textTraditional":"絕五歲，成帝建始元年，復立元弟上郡庫令良，〔一〕是為河間惠王。良修獻王之行，母太后薨，服喪如禮。哀帝下詔褒揚曰：「河間王良，喪太后三年，為宗室儀表，其益封萬戶。」二十七年薨。子尚嗣，王莽時絕。","sentenceOrder":28},
  {"id":"s_work_han_thu_64_29","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　如淳曰：「漢官北邊郡庫，官兵之所藏，故置令。」","sentenceOrder":29},
  {"id":"s_work_han_thu_64_30","chapterId":"ch_work_han_thu_64","textTraditional":"臨江哀王閼以孝景前二年立，三年薨。無子，國除為郡。","sentenceOrder":30},
  {"id":"s_work_han_thu_64_31","chapterId":"ch_work_han_thu_64","textTraditional":"臨江閔王榮以孝景前四年為皇太子，四歲廢為臨江王。三歲，坐侵廟壖地為宮，〔一〕上徵榮。榮行，祖於江陵北門，〔二〕既上車，軸折車廢。〔三〕江陵父老流涕竊言曰：「吾王不反矣！」榮至，詣中尉府對簿。中尉郅都簿責訊王，〔四〕王恐，自殺。葬藍田，燕數萬銜土置冢上。百姓憐之。","sentenceOrder":31},
  {"id":"s_work_han_thu_64_32","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「壖音人緣反。解在食貨志及晁錯傳。」","sentenceOrder":32},
  {"id":"s_work_han_thu_64_33","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「祖者，送行之祭，因饗飲也。昔黃帝之子纍祖好遠游而死於道，故後人以為行神也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_64_34","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「廢，壞也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_64_35","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「簿皆音薄戶反。訊，問也，音信。」","sentenceOrder":35},
  {"id":"s_work_han_thu_64_36","chapterId":"ch_work_han_thu_64","textTraditional":"榮最長，亡子，國除。〔一〕地入于漢，為南郡。","sentenceOrder":36},
  {"id":"s_work_han_thu_64_37","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「榮實最長，而傳居二王之後者，以其從太子被廢，後乃立為王也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_64_38","chapterId":"ch_work_han_thu_64","textTraditional":"魯恭王餘以孝景前二年立為淮陽王。吳楚反破後，以孝景前三年徙王魯。好治宮室苑囿狗馬，季年好音，〔一〕不喜辭。〔二〕為人口吃難言。〔三〕","sentenceOrder":38},
  {"id":"s_work_han_thu_64_39","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「季年，末年也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_64_40","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「喜音許吏反。」","sentenceOrder":40},
  {"id":"s_work_han_thu_64_41","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「吃音訖。」","sentenceOrder":41},
  {"id":"s_work_han_thu_64_42","chapterId":"ch_work_han_thu_64","textTraditional":"二十八年薨。子安王光嗣，初好音樂輿馬，晚節遴，〔一〕唯恐不足於財。四十年薨。子孝王慶忌嗣，三十七年薨。子頃王勁嗣，二十八年薨。子文王睃嗣，十八年薨，亡子，國除。哀帝建平三年，復立頃王子睃弟郚鄉侯閔為王。〔二〕王莽時絕。","sentenceOrder":42},
  {"id":"s_work_han_thu_64_43","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「晚節猶言末時也。遴與〈恡，去“忄”〉同，猶言貪嗇也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_64_44","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　蘇林曰：「郚音魚，縣名也，屬東海郡。」師古曰：「又音吾。」","sentenceOrder":44},
  {"id":"s_work_han_thu_64_45","chapterId":"ch_work_han_thu_64","textTraditional":"恭王初好治宮室，壞孔子舊宅以廣其宮，聞鐘磬琴瑟之聲，遂不敢復壞，於其壁中得古文經傳。","sentenceOrder":45},
  {"id":"s_work_han_thu_64_46","chapterId":"ch_work_han_thu_64","textTraditional":"江都易王非以孝景前二年立為汝南王。吳楚反時，非年十五，有材氣，上書自請擊吳。景帝賜非將軍印，擊吳。吳已破，徙王江都，治故吳國，〔一〕以軍功賜天子旗。元光中，匈奴大入漢邊，非上書願擊匈奴，上不許。非好氣力，治宮館，招四方豪桀，驕奢甚。二十七年薨，子建嗣。","sentenceOrder":46},
  {"id":"s_work_han_thu_64_47","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「治謂都之。劉濞所居也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_64_48","chapterId":"ch_work_han_thu_64","textTraditional":"建為太子時，邯鄲人梁蚡持女欲獻之易王，建聞其美，私呼之，因留不出。蚡宣言曰：「子乃與其公爭妻！」建使人殺蚡。蚡家上書，下廷尉考，會赦，不治。易王薨未葬，建居服舍，〔一〕召易王所愛美人淖姬等凡十人與姦。〔二〕建女弟徵臣為蓋侯子婦，〔三〕以易王喪來歸，建復與姦。建異母弟定國為淮陽侯，易王最小子也，其母幸立之，〔四〕具知建事，行錢使男子荼恬上書〔五〕告建淫亂，不當為後。事下廷尉，廷尉治恬受人錢財為上書，論棄市。建罪不治。後數使使至長安迎徵臣，魯恭王太后聞之，〔六〕遺徵臣書曰：「國中口語籍籍，慎無復至江都。」〔七〕後建使謁者吉請問共太后，〔八〕太后泣謂吉：「歸以吾言謂而王，〔九〕王前事漫漫，今當自謹，獨不聞燕齊事乎？〔一０〕言吾為而王泣也。」吉歸，致共太后語，建大怒，擊吉，斥之。〔一一〕","sentenceOrder":48},
  {"id":"s_work_han_thu_64_49","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「倚廬堊室之次也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_64_50","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　鄭氏曰：「淖音卓王孫之卓。」蘇林曰：「淖音泥淖。」師古曰：「蘇說是，音女教反。」","sentenceOrder":50},
  {"id":"s_work_han_thu_64_51","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「女弟，即妹也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_64_52","chapterId":"ch_work_han_thu_64","textTraditional":"〔四〕　師古曰：「冀得立其子為易王嗣。」","sentenceOrder":52},
  {"id":"s_work_han_thu_64_53","chapterId":"ch_work_han_thu_64","textTraditional":"〔五〕　蘇林曰：「荼音食邪反。」","sentenceOrder":53},
  {"id":"s_work_han_thu_64_54","chapterId":"ch_work_han_thu_64","textTraditional":"〔六〕　師古曰：「易王即魯恭王同母之弟，徵臣則太后之孫也，故與書戒之。」","sentenceOrder":54},
  {"id":"s_work_han_thu_64_55","chapterId":"ch_work_han_thu_64","textTraditional":"〔七〕　師古曰：「籍籍，諠聒之意。」","sentenceOrder":55},
  {"id":"s_work_han_thu_64_56","chapterId":"ch_work_han_thu_64","textTraditional":"〔八〕　師古曰：「謂請問起居也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_64_57","chapterId":"ch_work_han_thu_64","textTraditional":"〔九〕　師古曰：「謂，告也。而，汝也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_64_58","chapterId":"ch_work_han_thu_64","textTraditional":"〔一０〕張晏曰：「燕王定國、齊王次昌皆與子昆弟姦，發覺自殺也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_64_59","chapterId":"ch_work_han_thu_64","textTraditional":"〔一一〕師古曰：「斥謂退棄之。」","sentenceOrder":59},
  {"id":"s_work_han_thu_64_60","chapterId":"ch_work_han_thu_64","textTraditional":"建游章臺宮，令四女子乘小船，建以足蹈覆其船，〔一〕四人皆溺，二人死。後游雷波，〔二〕天大風，建使郎二人乘小船入波中。船覆，兩郎溺，攀船，乍見乍沒。建臨觀大笑，令皆死。〔三〕","sentenceOrder":60},
  {"id":"s_work_han_thu_64_61","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「覆音芳目反。其下亦同。」","sentenceOrder":61},
  {"id":"s_work_han_thu_64_62","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「波讀為陂。雷陂，陂名。其下云入波中亦同。」","sentenceOrder":62},
  {"id":"s_work_han_thu_64_63","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「不救止之，並死陂中也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_64_64","chapterId":"ch_work_han_thu_64","textTraditional":"宮人姬八子有過者，輒令臝立擊鼓，〔一〕或置樹上，久者三十日乃得衣；或髡鉗以鈆杵舂，〔二〕不中程，輒掠；〔三〕或縱狼令齧殺之，〔四〕建觀而大笑；或閉不食，令餓死。凡殺不辜三十五人。建欲令人與禽獸交而生子，彊令宮人臝而四據，與羝羊及狗交〔五〕。","sentenceOrder":64},
  {"id":"s_work_han_thu_64_65","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「八子，姬妾官名也。臝者，露其形也，音來果反。」","sentenceOrder":65},
  {"id":"s_work_han_thu_64_66","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「鈆者，錫之類也，立弋全反。」","sentenceOrder":66},
  {"id":"s_work_han_thu_64_67","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「程者，作之課也。掠，笞擊也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_64_68","chapterId":"ch_work_han_thu_64","textTraditional":"〔四〕　師古曰：「縱，放也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_64_69","chapterId":"ch_work_han_thu_64","textTraditional":"〔五〕　師古曰：「羝羊，牡羊，音丁奚反。」","sentenceOrder":69},
  {"id":"s_work_han_thu_64_70","chapterId":"ch_work_han_thu_64","textTraditional":"專為淫虐，自知罪多，國中多欲告言者，建恐誅，心內不安，與其后成光共使越婢下神，祝詛上。與郎中令等語怨望：「漢廷使者即復來覆我，我決不獨死！」〔一〕","sentenceOrder":70},
  {"id":"s_work_han_thu_64_71","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「覆，治也。不獨死，言欲反也。覆音芳目反。」","sentenceOrder":71},
  {"id":"s_work_han_thu_64_72","chapterId":"ch_work_han_thu_64","textTraditional":"建亦頗聞淮南、衡山陰謀，恐一日發，為所并，遂作兵器。號王后父胡應為將軍。中大夫疾有材力，善騎射，〔一〕號曰靈武君。作治黃屋蓋；刻皇帝璽，鑄將軍、都尉金銀印；作漢使節二十，綬千餘；具置軍官品員，及拜爵封侯之賞；具天下之輿地及軍陳圖。遣人通越繇王閩侯，遺以錦帛奇珍，繇王閩侯亦遺建荃、葛、〔二〕珠璣、〔三〕犀甲、翠羽、蝯熊奇獸，數通使往來，約有急相助。〔四〕及淮南事發，治黨與，頗連及建，建使人多推金錢絕其獄。〔五〕","sentenceOrder":72},
  {"id":"s_work_han_thu_64_73","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「疾者，中大夫之名。」","sentenceOrder":73},
  {"id":"s_work_han_thu_64_74","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　蘇林曰：「荃音詮，細布屬也。」服虔曰：「音蓀，細葛也。」臣瓚曰：「荃，香草也。」師古曰：「服、瓚二說皆非也。許慎云『荃，細布也』。字本作絟，音千全反，又音千劣反，蓋今南方筩布之屬皆為荃也。葛即今之葛布也。以荃及葛遺建也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_64_75","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「璣謂珠之不圜者也，音機，又音畿。」","sentenceOrder":75},
  {"id":"s_work_han_thu_64_76","chapterId":"ch_work_han_thu_64","textTraditional":"〔四〕　師古曰：「約謂言契也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_64_77","chapterId":"ch_work_han_thu_64","textTraditional":"〔五〕　師古曰：「行賄賂以滅其蹤緒也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_64_78","chapterId":"ch_work_han_thu_64","textTraditional":"後復謂近臣曰：「我為王，詔獄歲至，生又無驩怡日，壯士不坐死，欲為人所不能為耳。」〔一〕建時佩其父所賜將軍印，載天子旗出。積數歲，事發覺，漢遣丞相長史與江都相雜案，索得兵器璽綬節反具，〔二〕有司請捕誅建。制曰：「與列侯吏二千石博士議。」議皆曰：「建失臣子道，積久，輒蒙不忍，遂謀反逆。所行無道，雖桀紂惡不至於此。天誅所不赦，當以謀反法誅。」有詔宗正、廷尉即問建。〔三〕建自殺，后成光等皆棄市。六年國除，地入于漢，為廣陵郡。","sentenceOrder":78},
  {"id":"s_work_han_thu_64_79","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「亦言欲反也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_64_80","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「索，搜也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_64_81","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「即，就也，就其國問之。」","sentenceOrder":81},
  {"id":"s_work_han_thu_64_82","chapterId":"ch_work_han_thu_64","textTraditional":"絕百二十一年，平帝時新都侯王莽秉政，興滅繼絕，立建弟盱眙侯子宮為廣陵王，〔一〕奉易王後。莽篡，國絕。","sentenceOrder":82},
  {"id":"s_work_han_thu_64_83","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「盱音許于反。眙音怡。」","sentenceOrder":83},
  {"id":"s_work_han_thu_64_84","chapterId":"ch_work_han_thu_64","textTraditional":"膠西于王端，孝景前三年立。為人賊盭，又陰痿，〔一〕一近婦人，病數月。有所愛幸少年，以為郎。郎與後宮亂，端禽滅之，及殺其子母。數犯法，〔二〕漢公卿數請誅端，天子弗忍，而端所為滋甚。〔三〕有司比再請，削其國，去太半。〔四〕端心慍，遂為無訾省。〔五〕府庫壞漏，盡腐財物，以鉅萬計，終不得收徙。〔六〕令吏毋得收租賦。端皆去衛，封其宮門，從一門出入。數變名姓，為布衣，之它國。〔七〕","sentenceOrder":84},
  {"id":"s_work_han_thu_64_85","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「盭，古戾字也，言其性賊害而佷戾也。痿音萎。」","sentenceOrder":85},
  {"id":"s_work_han_thu_64_86","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「數音所角反。次下亦同。」","sentenceOrder":86},
  {"id":"s_work_han_thu_64_87","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「滋，益也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_64_88","chapterId":"ch_work_han_thu_64","textTraditional":"〔四〕　張晏曰：「三分之二為太半，一為少半。」師古曰：「比，頻也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_64_89","chapterId":"ch_work_han_thu_64","textTraditional":"〔五〕　蘇林曰：「為無所省錄也。」師古曰：「訾，訾財也。省，視也。言不視訾財也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_64_90","chapterId":"ch_work_han_thu_64","textTraditional":"〔六〕　師古曰：「不收又不徙置他處。」","sentenceOrder":90},
  {"id":"s_work_han_thu_64_91","chapterId":"ch_work_han_thu_64","textTraditional":"〔七〕　師古曰：「之，往也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_64_92","chapterId":"ch_work_han_thu_64","textTraditional":"相二千石至者，奉漢法以治，端輒求其罪告之，亡罪者詐藥殺之。所以設詐究變，〔一〕彊足以距諫，知足以飾非。相二千石從王治，則漢繩以法。故膠西小國，而所殺傷二千石甚眾。","sentenceOrder":92},
  {"id":"s_work_han_thu_64_93","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「究，極也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_64_94","chapterId":"ch_work_han_thu_64","textTraditional":"立四十七年薨，無子，國除。地入于漢，為膠西郡。","sentenceOrder":94},
  {"id":"s_work_han_thu_64_95","chapterId":"ch_work_han_thu_64","textTraditional":"趙敬肅王彭祖以孝景前二年立為廣川王。趙王遂反破後，徙王趙。彭祖為人巧佞，卑諂足共，〔一〕而心刻深，好法律，持詭辯以中人。〔二〕多內寵姬及子孫。相二千石欲奉漢法以治，則害於王家。是以每相二千石至，彭祖衣帛布單衣，〔三〕自行迎除舍，〔四〕多設疑事以詐動之，得二千石失言，中忌諱，輒書之。二千石欲治者，則以此迫劫；不聽，乃上書告之，及汙以姦利事。彭祖立六十餘年，相二千石無能滿二歲，輒以罪去，大者死，小者刑。以故二千石莫敢治，而趙王擅權。使使即縣為賈人榷會，〔五〕入多於國租稅。以是趙王家多金錢，然所賜姬諸子，亦盡之矣。","sentenceOrder":95},
  {"id":"s_work_han_thu_64_96","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「共讀曰恭。足恭，謂便辟也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_64_97","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「詭辯，違道之辯也。中，傷也，音竹仲反。」","sentenceOrder":97},
  {"id":"s_work_han_thu_64_98","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「或帛或布以為單衣。」","sentenceOrder":98},
  {"id":"s_work_han_thu_64_99","chapterId":"ch_work_han_thu_64","textTraditional":"〔四〕　師古曰：「至除舍迎之也。除舍，謂初所至之舍。」","sentenceOrder":99},
  {"id":"s_work_han_thu_64_100","chapterId":"ch_work_han_thu_64","textTraditional":"〔五〕　韋昭曰：「平會兩家買賣之賈者。榷者，禁他家，獨王家得為之也。」師古曰：「即，就也。就諸縣而專榷賈人之會，若今和市矣。榷音角。會音工外反。」","sentenceOrder":100},
  {"id":"s_work_han_thu_64_101","chapterId":"ch_work_han_thu_64","textTraditional":"彭祖不好治宮室禨祥，〔一〕好為吏。上書願督國中盜賊。〔二〕常夜從走卒行徼邯鄲中。〔三〕諸使過客，以彭祖險陂，莫敢留邯鄲。〔四〕","sentenceOrder":101},
  {"id":"s_work_han_thu_64_102","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　服虔曰：「求福也。」師古曰：「禨，鬼俗也，字或作｛幾鬼｝。淮南子曰『荊人鬼，越人｛幾鬼｝』。禨祥，總謂鬼神之事也。服說失之。禨音居衣反。」","sentenceOrder":102},
  {"id":"s_work_han_thu_64_103","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「督，視察也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_64_104","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「徼謂巡察也，音工釣反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_64_105","chapterId":"ch_work_han_thu_64","textTraditional":"〔四〕　師古曰：「使謂京師使人也。過客，行客從趙過者也。陂謂傾側也，音彼義反。」","sentenceOrder":105},
  {"id":"s_work_han_thu_64_106","chapterId":"ch_work_han_thu_64","textTraditional":"久之，太子丹與其女弟及同產姊姦。江充告丹淫亂，又使人椎埋攻剽，為姦甚眾。〔一〕武帝遣使者發吏卒捕丹，下魏郡詔獄，治罪至死。彭祖上書冤訟丹，願從國中勇敢擊匈奴，〔二〕贖丹罪，上不許。久之，竟赦出。後彭祖入朝，因帝姊平陽隆慮公主，〔三〕求復立丹為太子，上不許。","sentenceOrder":106},
  {"id":"s_work_han_thu_64_107","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「椎殺人而埋之，故曰椎埋。剽，劫也。椎音直佳反，其字從木。剽音頻妙反，其字從刀。」","sentenceOrder":107},
  {"id":"s_work_han_thu_64_108","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「以勇敢自隨。」","sentenceOrder":108},
  {"id":"s_work_han_thu_64_109","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「慮音廬。」","sentenceOrder":109},
  {"id":"s_work_han_thu_64_110","chapterId":"ch_work_han_thu_64","textTraditional":"彭祖取江都易王寵姬，王建所姦淖姬者，甚愛之，生一男，號淖子。彭祖以征和元年薨，諡敬肅王。彭祖薨時，淖姬兄為漢宦者，上召問：「淖子何如？」對曰：「為人多欲。」上曰：「多欲不宜君國子民。」問武始侯昌，曰：「無咎無譽。」上曰：「如是可矣。」遣使者立昌，是為頃王，十九年薨。子懷王尊嗣，五年薨。無子，絕二歲。宣帝立尊弟高，是為哀王，數月薨。子共王充嗣，五十六年薨。子隱嗣，王莽時絕。","sentenceOrder":110},
  {"id":"s_work_han_thu_64_111","chapterId":"ch_work_han_thu_64","textTraditional":"初，武帝復以親親故，立敬肅王小子偃為平干王，〔一〕是為頃王，十一年薨。子繆王元嗣，二十五年薨。大鴻臚禹奏：「元前以刃賊殺奴婢，子男殺謁者，為刺史所舉奏，罪名明白。病先令，令能為樂奴婢從死，〔二〕迫脅自殺者凡十六人，暴虐不道。故春秋之義，誅君之子不宜立。元雖未伏誅，不宜立嗣。」奏可，國除。","sentenceOrder":111},
  {"id":"s_work_han_thu_64_112","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　孟康曰：「今廣平。」","sentenceOrder":112},
  {"id":"s_work_han_thu_64_113","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「先令者，預為遺令也。能為樂，作樂之人也。從死，以殉葬也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_64_114","chapterId":"ch_work_han_thu_64","textTraditional":"中山靖王勝以孝景前三年立。武帝初即位，大臣懲吳楚七國行事，議者（勿）〔多〕冤晁錯之策，〔一〕皆以諸侯連城數十，泰強，欲稍侵削，數奏暴其過惡。〔二〕諸侯王自以骨肉至親，先帝所以廣封連城，犬牙相錯者，為盤石宗也。〔三〕今或無罪，為臣下所侵辱，有司吹毛求疵，〔四〕笞服其臣，使證其君，多自以侵冤。","sentenceOrder":114},
  {"id":"s_work_han_thu_64_115","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「言錯策為是，枉見殺也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_64_116","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「暴謂披布之。」","sentenceOrder":116},
  {"id":"s_work_han_thu_64_117","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「錯，雜也，言其地相交雜。」","sentenceOrder":117},
  {"id":"s_work_han_thu_64_118","chapterId":"ch_work_han_thu_64","textTraditional":"〔四〕　師古曰：「疵，病也，音才斯反。」","sentenceOrder":118},
  {"id":"s_work_han_thu_64_119","chapterId":"ch_work_han_thu_64","textTraditional":"建元三年，代王登、長沙王發、中山王勝、濟川王明來朝，天子置酒，勝聞樂聲而泣。問其故，勝對曰：","sentenceOrder":119},
  {"id":"s_work_han_thu_64_120","chapterId":"ch_work_han_thu_64","textTraditional":"臣聞悲者不可為絫欷，〔一〕思者不可為歎息。〔二〕故高漸離擊筑易水之上，荊軻為之低而不食；〔三〕雍門子壹微吟，孟嘗君為之於邑。〔四〕今臣心結日久，每聞幼眇之聲，不知涕泣之橫集也。〔五〕","sentenceOrder":120},
  {"id":"s_work_han_thu_64_121","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「絫，古累字。累，重也。欷，歔欷也，音許既反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_64_122","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「言聞欷歎之聲，則悲思益甚。」","sentenceOrder":122},
  {"id":"s_work_han_thu_64_123","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　應劭曰：「燕太子丹遣荊軻刺秦王，賓客祖於易水之上，漸離擊筑，士皆垂泣，荊卿不能復食也。」師古曰：「低謂俛首。」","sentenceOrder":123},
  {"id":"s_work_han_thu_64_124","chapterId":"ch_work_han_thu_64","textTraditional":"〔四〕　張晏曰：「齊之賢者，居雍門，因以為號。」蘇林曰：「六國時人，名周，善鼓琴，母死無以葬，見孟嘗君而微吟也。」如淳曰：「雍門子以善鼓琴見孟嘗君，先說萬歲之後，高臺既已顛，曲池又已平，墳墓生荊棘，牧豎游其上，孟嘗君亦如是乎？孟嘗君喟然歎息也。」師古曰：「如說是也，蘇失之矣。於邑，短氣貌。於音烏。邑音一合反，或讀如本字。」","sentenceOrder":124},
  {"id":"s_work_han_thu_64_125","chapterId":"ch_work_han_thu_64","textTraditional":"〔五〕　師古曰：「幼音一笑反。眇音妙。幼妙，精微也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_64_126","chapterId":"ch_work_han_thu_64","textTraditional":"夫眾喣漂山，〔一〕聚蚊成雷，〔二〕朋黨執虎，十夫橈椎。〔三〕是以文王拘於牖里，孔子阨於陳、蔡。此乃烝庶之成風，增積之生害也。〔四〕臣身遠與寡，莫為之先，〔五〕眾口鑠金，積毀銷骨，〔六〕叢輕折軸，羽翮飛肉，〔七〕紛驚逢羅，潸然出涕〔八〕。","sentenceOrder":126},
  {"id":"s_work_han_thu_64_127","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　應劭曰：「喣，吹喣也。」師古曰：「漂，動也。喣音許句反，又音許于反。漂音匹遙反。」","sentenceOrder":127},
  {"id":"s_work_han_thu_64_128","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「{民〈虫虫〉}，古蚊字。靁，古雷字。言眾蚊飛聲有若雷也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_64_129","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「橈，曲也，音女教反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_64_130","chapterId":"ch_work_han_thu_64","textTraditional":"〔四〕　師古曰：「烝庶，謂眾人也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_64_131","chapterId":"ch_work_han_thu_64","textTraditional":"〔五〕　師古曰：「身遠者，去帝京遠。與寡者，少黨與也。先謂素為延譽也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_64_132","chapterId":"ch_work_han_thu_64","textTraditional":"〔六〕　師古曰：「解在鄒陽傳。」","sentenceOrder":132},
  {"id":"s_work_han_thu_64_133","chapterId":"ch_work_han_thu_64","textTraditional":"〔七〕　師古曰：「言積載輕物，物多至令車軸毀折。而鳥之所以能飛翔者，以羽翮扇揚之故也。」","sentenceOrder":133},
  {"id":"s_work_han_thu_64_134","chapterId":"ch_work_han_thu_64","textTraditional":"〔八〕　晉灼曰：「言皆驚亂遇法罔，可為出涕者也。」師古曰：「潸，垂涕貌，音所姦反。」","sentenceOrder":134},
  {"id":"s_work_han_thu_64_135","chapterId":"ch_work_han_thu_64","textTraditional":"臣聞白日曬光，幽隱皆照；〔一〕明月曜夜，蚊虻宵見〔二〕。然雲蒸列布，杳冥晝昏；塵埃抪覆，昧不〔見〕泰山。〔三〕何則？物有蔽之也。今臣雍閼不得聞，〔四〕讒言之徒{夆〈虫虫〉}生〔五〕道遼路遠，曾莫為臣聞，臣竊自悲也。","sentenceOrder":135},
  {"id":"s_work_han_thu_64_136","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「曬，暴也，舒也，音山豉反，又音力支反。」","sentenceOrder":136},
  {"id":"s_work_han_thu_64_137","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「宵亦夜也。蝱音盲。」","sentenceOrder":137},
  {"id":"s_work_han_thu_64_138","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「抪亦布散也。昧，暗也。抪音鋪。」","sentenceOrder":138},
  {"id":"s_work_han_thu_64_139","chapterId":"ch_work_han_thu_64","textTraditional":"〔四〕　師古曰：「雍讀曰壅。雍，塞也。閼猶止也，音烏曷反。」","sentenceOrder":139},
  {"id":"s_work_han_thu_64_140","chapterId":"ch_work_han_thu_64","textTraditional":"〔五〕　師古曰：「{夆〈虫虫〉}生，言眾多也。一曰{夆〈虫虫〉}與鋒同。」","sentenceOrder":140},
  {"id":"s_work_han_thu_64_141","chapterId":"ch_work_han_thu_64","textTraditional":"臣聞社鼷不灌，屋鼠不熏。〔一〕何則？所託者然也。臣雖薄也，得蒙肺附；位雖卑也，得為東藩，屬又稱兄。〔二〕今群臣非有葭莩之親，鴻毛之重，〔三〕群居黨議，朋友相為，使夫宗室擯卻，骨肉冰釋。〔四〕斯伯奇所以流離，比干所以橫分也。〔五〕詩云「我心憂傷，惄焉如擣；假寐永歎，唯憂用老；心之憂矣，疢如疾首」，〔六〕臣之謂也。","sentenceOrder":141},
  {"id":"s_work_han_thu_64_142","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「鼷，小鼠，音奚。」","sentenceOrder":142},
  {"id":"s_work_han_thu_64_143","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「言於戚屬為帝兄。」","sentenceOrder":143},
  {"id":"s_work_han_thu_64_144","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　張晏曰：「葭，蘆〔葉〕也。莩，葉裏白皮也。」晉灼曰：「莩，葭裏之白皮也，皆取喻於輕薄也。」師古曰：「葭，蘆也。莩者，其筩中白皮至薄者也。葭莩喻（著）〔薄〕，鴻毛喻輕薄甚也。莩音孚。張言葉裏白皮非也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_64_145","chapterId":"ch_work_han_thu_64","textTraditional":"〔四〕　師古曰：「擯卻，謂斥退也。冰釋，言銷散也。擯音必刃反。卻音丘略反。」","sentenceOrder":145},
  {"id":"s_work_han_thu_64_146","chapterId":"ch_work_han_thu_64","textTraditional":"〔五〕　師古曰：「伯奇，周尹吉甫之子也，事後母至孝，而後母譖之於吉甫。吉甫欲殺之，伯奇乃亡走山林。比干諫紂，紂怒，殺而剖其心，故云橫分也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_64_147","chapterId":"ch_work_han_thu_64","textTraditional":"〔六〕　師古曰：「小雅小弁之詩也。惄，思也。擣，築也。不脫衣冠而寐曰假寐。永，長也。疢，病也。言我心中憂思，如被擣築，假寐長歎，以憂致老，至於苦病，如遇首疾也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_64_148","chapterId":"ch_work_han_thu_64","textTraditional":"具以吏所侵聞。於是上乃厚諸侯之禮，省有司所奏諸侯事，〔一〕加親親之恩焉。其後更用主父偃謀，令諸侯以私恩自裂地分其子弟，而漢為定制封號，輒別屬漢郡。漢有厚恩，而諸侯地稍自分析弱小云。","sentenceOrder":148},
  {"id":"s_work_han_thu_64_149","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「省，減也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_64_150","chapterId":"ch_work_han_thu_64","textTraditional":"勝為人樂酒好內，〔一〕有子百二十餘人。常與趙王彭祖相非曰：「兄為王，專代吏治事。王者當日聽音樂，御聲色。」趙王亦曰：「中山王但奢淫，不佐天子拊循百姓，何以稱為藩臣！」","sentenceOrder":150},
  {"id":"s_work_han_thu_64_151","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「好內，耽於妻妾也。樂音五教反。」","sentenceOrder":151},
  {"id":"s_work_han_thu_64_152","chapterId":"ch_work_han_thu_64","textTraditional":"四十三年薨。子哀王昌嗣，一年薨。子康王昆侈嗣，二十一年薨。子頃王輔嗣，四年薨。子憲王福嗣，十七年薨。子懷王循嗣，十五年薨，無子，絕四十五歲。成帝鴻嘉二年復立憲王弟孫利鄉侯子雲客，是為廣德夷王。三年薨，無子，絕十四歲。哀帝復立雲客弟廣漢為廣平王。薨，無後。平帝元始二年復立廣川惠王曾孫倫為廣德王，奉靖王後。王莽時絕。","sentenceOrder":152},
  {"id":"s_work_han_thu_64_153","chapterId":"ch_work_han_thu_64","textTraditional":"長沙定王發，母唐姬，故程姬侍者。景帝召程姬，程姬有所避，不願進，〔一〕而飾侍者唐兒使夜進。上醉，不知，以為程姬而幸之，遂有身。已乃覺非程姬也。及生子，因名曰發。〔二〕以孝景前二年立。以其母微無寵，故王卑溼貧國。〔三〕","sentenceOrder":153},
  {"id":"s_work_han_thu_64_154","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「謂月事。」","sentenceOrder":154},
  {"id":"s_work_han_thu_64_155","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　張晏曰：「長沙王生，乃發寤己之繆幸唐姬。」","sentenceOrder":155},
  {"id":"s_work_han_thu_64_156","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　應劭曰：「景帝後二年諸王來朝，有詔更前稱壽歌舞。定王但張袖小舉手，左右笑其拙。上怪問之，對曰：『臣國小地狹，不足回旋。』帝乃以武陵、零陵、桂陽益焉。」","sentenceOrder":156},
  {"id":"s_work_han_thu_64_157","chapterId":"ch_work_han_thu_64","textTraditional":"二十八年薨。子戴王庸嗣，二十七年薨。子頃王鮒鮈嗣，〔一〕十七年薨。子剌王建德嗣，〔二〕宣帝時坐獵縱火燔民九十六家〔三〕，殺二人，又以縣官事怨內史，教人誣告以棄市罪，削八縣，罷中尉官。〔四〕三十四年薨。子煬王旦嗣，〔五〕二年薨。無子，絕歲餘。元帝初元三年復立旦弟宗，是為孝王，五年薨。子魯人嗣，王莽時絕。","sentenceOrder":157},
  {"id":"s_work_han_thu_64_158","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　服虔曰：「鮈音拘。」師古曰：「鮒音附。鮈音劬。字或作胕朐，其音同耳。」","sentenceOrder":158},
  {"id":"s_work_han_thu_64_159","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「剌音來曷反。」","sentenceOrder":159},
  {"id":"s_work_han_thu_64_160","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「縱，放也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_64_161","chapterId":"ch_work_han_thu_64","textTraditional":"〔四〕　師古曰：「減其官屬，所以貶抑之。」","sentenceOrder":161},
  {"id":"s_work_han_thu_64_162","chapterId":"ch_work_han_thu_64","textTraditional":"〔五〕　師古曰：「煬音弋向反。」","sentenceOrder":162},
  {"id":"s_work_han_thu_64_163","chapterId":"ch_work_han_thu_64","textTraditional":"廣川惠王越以孝景中二年立，十三年薨。子繆王齊嗣，〔一〕四十四年薨。初齊有幸臣乘距，已而有罪，欲誅距。距亡，齊因禽其宗族。距怨王，乃上書告齊與同產姦。〔二〕是後，齊數告言漢公卿及幸臣所忠等，〔三〕又告中尉蔡彭祖捕子明，〔四〕罵曰：「吾盡汝種矣！」〔五〕有司案驗，不如王言，劾齊誣罔，大不敬，請繫治。齊恐，上書願與廣川勇士奮擊匈奴，上許之。未發，病薨。有司請除國，奏可。","sentenceOrder":163},
  {"id":"s_work_han_thu_64_164","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「諡法曰『蔽仁傷善曰繆』。」","sentenceOrder":164},
  {"id":"s_work_han_thu_64_165","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「謂其姊妺也。」","sentenceOrder":165},
  {"id":"s_work_han_thu_64_166","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「所姓，忠名。解具在食貨志。」","sentenceOrder":166},
  {"id":"s_work_han_thu_64_167","chapterId":"ch_work_han_thu_64","textTraditional":"〔四〕　孟康曰：「彭祖子名明也。」師古曰：「孟說非也。明，廣川王子也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_64_168","chapterId":"ch_work_han_thu_64","textTraditional":"〔五〕　師古曰：「王誣彭祖罵明云然。」","sentenceOrder":168},
  {"id":"s_work_han_thu_64_169","chapterId":"ch_work_han_thu_64","textTraditional":"後數月，下詔曰：「廣川惠王於朕為兄，朕不忍絕其宗廟，其以惠王孫去為廣川王。」去即繆王齊太子也，師受易、論語、孝經皆通，好文辭方技博弈倡優。其殿門有成慶畫，短衣大絝長劍，〔一〕去好之，作七尺五寸劍，被服皆效焉。有幸姬王昭平、王地餘，許以為后。去嘗疾，姬陽成昭信侍視甚謹，〔二〕更愛之。去與地餘戲，得袖中刀，〔三〕笞問狀，服欲與昭平共殺昭信。笞問昭平，不服，以鐵鍼鍼之，〔四〕彊服。乃會諸姬，去以劍自擊地餘，令昭信擊昭平，皆死。昭信曰：「兩姬婢且泄口。」復絞殺從婢三人。後昭信病，夢見昭平等以狀告去。去曰：「虜乃復見畏我！〔五〕獨可燔燒耳。」掘出尸，皆燒為灰。","sentenceOrder":169},
  {"id":"s_work_han_thu_64_170","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　晉灼曰：「成慶，荊軻也，衛人謂之慶卿，燕人謂之荊卿。」師古曰：「成慶，古之勇士也，事見淮南子，非荊卿也。」","sentenceOrder":170},
  {"id":"s_work_han_thu_64_171","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「陽成姓也，昭信名也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_64_172","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「褏，古衣袖字。」","sentenceOrder":172},
  {"id":"s_work_han_thu_64_173","chapterId":"ch_work_han_thu_64","textTraditional":"〔四〕　師古曰：「以鍼刺也。鍼音之林反。」","sentenceOrder":173},
  {"id":"s_work_han_thu_64_174","chapterId":"ch_work_han_thu_64","textTraditional":"〔五〕　師古曰：「言其見形令我畏忌也。見音胡電反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_64_175","chapterId":"ch_work_han_thu_64","textTraditional":"後去立昭信為后；幸姬陶望卿為脩靡夫人，主繒帛；崔脩成為明貞夫人，主永巷。昭信復譖望卿曰：「與我無禮，衣服常鮮於我〔一〕，盡取善繒匄諸宮人。」〔二〕去曰：「若數惡望卿，不能減我愛；〔三〕設聞其淫，我亨之矣。」後昭信謂去曰：「前畫工畫望卿舍，望卿袒裼傅粉其傍。〔四〕又數出入南戶窺郎吏，疑有姦。」去曰：「善司之。」以故益不愛望卿。後與昭信等飲，諸姬皆侍，去為望卿作歌曰：「背尊章，嫖以忽，〔五〕謀屈奇，起自絕。〔六〕行周流，自生患，諒非望，今誰怨！」〔七〕使美人相和歌之。去曰：「是中當有自知者。」昭信知去已怒，即誣言望卿歷指郎吏臥處，具知其主名，又言郎中令錦被，疑有姦。去即與昭信從諸姬至望卿所，臝其身，更擊之。〔八〕令諸姬各持燒鐵共灼望卿。望卿走，自投井死。昭信出之，椓杙其陰中，〔九〕割其鼻脣，斷其舌。謂去曰：「前殺昭平，反來畏我，〔一０〕今欲靡爛望卿，使不能神。」〔一一〕與去共支解，置大鑊中，取桃灰毒藥并煮之，召諸姬皆臨觀，連日夜靡盡。復共殺其女弟都。","sentenceOrder":175},
  {"id":"s_work_han_thu_64_176","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「鮮謂新華也。」","sentenceOrder":176},
  {"id":"s_work_han_thu_64_177","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「匄，乞遺之也，音工艾反。」","sentenceOrder":177},
  {"id":"s_work_han_thu_64_178","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「若，汝也。惡謂讒毀也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_64_179","chapterId":"ch_work_han_thu_64","textTraditional":"〔四〕　師古曰：「袒裼，脫衣露其肩背也。袒音但。裼音錫。」","sentenceOrder":179},
  {"id":"s_work_han_thu_64_180","chapterId":"ch_work_han_thu_64","textTraditional":"〔五〕　孟康曰：「嫖音匹昭反。」師古曰：「尊章猶言舅姑也。今關中俗婦呼舅（姑）為鍾。鍾者章聲之轉也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_64_181","chapterId":"ch_work_han_thu_64","textTraditional":"〔六〕　師古曰：「屈奇，奇異也。屈音其勿反。」","sentenceOrder":181},
  {"id":"s_work_han_thu_64_182","chapterId":"ch_work_han_thu_64","textTraditional":"〔七〕　師古曰：「諒，信也。言昔被愛寵，信非所望，今見罪責，無所怨也。」","sentenceOrder":182},
  {"id":"s_work_han_thu_64_183","chapterId":"ch_work_han_thu_64","textTraditional":"〔八〕　師古曰：「更音工衡反。」","sentenceOrder":183},
  {"id":"s_work_han_thu_64_184","chapterId":"ch_work_han_thu_64","textTraditional":"〔九〕　師古曰：「杙，橜也。椓音竹角反。杙音弋。」","sentenceOrder":184},
  {"id":"s_work_han_thu_64_185","chapterId":"ch_work_han_thu_64","textTraditional":"〔一０〕師古曰：「令我恐畏也。」","sentenceOrder":185},
  {"id":"s_work_han_thu_64_186","chapterId":"ch_work_han_thu_64","textTraditional":"〔一一〕師古曰：「靡，碎也，音縻，其下亦同。」","sentenceOrder":186},
  {"id":"s_work_han_thu_64_187","chapterId":"ch_work_han_thu_64","textTraditional":"後去數召姬榮愛與飲，昭信復譖之，曰：「榮姬視瞻，意態不善，疑有私。」時愛為去刺方領繡，〔一〕去取燒之。愛恐，自投井。出之未死，笞問愛，自誣與醫姦。去縛繫柱，燒刀灼潰兩目，〔二〕生割兩股，銷鈆灌其口中。愛死，支解以棘埋之。諸幸於去者，昭信輒譖殺之，凡十四人，皆埋太后所居長壽宮中。宮人畏之，莫敢復迕。〔三〕","sentenceOrder":187},
  {"id":"s_work_han_thu_64_188","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　服虔曰：「如今小兒卻襲衣也。頸下施衿，領正方直。」晉灼曰：「今之婦人直領也。繡為方領，上刺作黼黻文。王莽傳曰『有人著赤繢方領』。方領，上服也。」師古曰：「晉說是也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_64_189","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「潰，決也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_64_190","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「迕，逆也，不敢逆昭信意。」","sentenceOrder":190},
  {"id":"s_work_han_thu_64_191","chapterId":"ch_work_han_thu_64","textTraditional":"昭信欲擅愛，曰：「王使明貞夫人主諸姬，淫亂難禁。請閉諸姬舍門，無令出敖。」〔一〕使其大婢為僕射，〔二〕主永巷，盡封閉諸舍，上籥於后，非大置酒召，不得見。去憐之，為作歌曰：「愁莫愁，居無聊。〔三〕心重結，意不舒。內茀鬱，憂哀積。〔四〕上不見天，生何益！日崔隤，時不再。〔五〕願棄軀，死無悔。」令昭信聲鼓為節，以教諸姬歌之，歌罷輒歸永巷，封門。獨昭信兄子初為乘華夫人，得朝夕見。昭信與去從十餘奴博飲游敖。","sentenceOrder":191},
  {"id":"s_work_han_thu_64_192","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「敖謂游戲也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_64_193","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「大婢，婢之長年也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_64_194","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「聊，賴也。」","sentenceOrder":194},
  {"id":"s_work_han_thu_64_195","chapterId":"ch_work_han_thu_64","textTraditional":"〔四〕　師古曰：「茀音拂。」","sentenceOrder":195},
  {"id":"s_work_han_thu_64_196","chapterId":"ch_work_han_thu_64","textTraditional":"〔五〕　師古曰：「崔隤猶言蹉跎也。崔音千回反。隤音頹。」","sentenceOrder":196},
  {"id":"s_work_han_thu_64_197","chapterId":"ch_work_han_thu_64","textTraditional":"初去年十四五，事師受易，師數諫正去，〔一〕去益大，逐之。〔二〕內史請以為掾，師數令內史禁切王家。去使奴殺師父子，不發覺。後去數置酒，令倡俳臝戲坐中〔三〕以為樂。相彊劾繫倡，闌入殿門，〔四〕奏狀。事下考案，倡辭，本為王教脩靡夫人望卿弟都歌舞。使者召望卿、都，去對皆淫亂自殺。會赦不治。望卿前亨煮，即取他死人與都死并付其母。〔五〕母曰：「都是，望卿非也。」數號哭求死，昭信令奴殺之。奴得，辭服。〔六〕本始三年，相內史奏狀，具言赦前所犯。天子遣大鴻臚、丞相長史、御史丞、廷尉正雜治鉅鹿詔獄，奏請逮捕去及后昭信。制曰：「王后昭信、諸姬奴婢證者皆下獄。」辭服。有司復請誅王。制曰：「與列侯、中二千石、二千石、博士議。」議者皆以為去悖虐，聽后昭信讒言，燔燒亨煮，生割剝人，距師之諫，殺其父子。凡殺無辜十六人，至一家母子三人，逆節絕理。其十五人在赦前，大惡仍重，〔七〕當伏顯戮以示眾。制曰：「朕不忍致王於法，議其罰。」有司請廢勿王，與妻子徙上庸。奏可。與湯沐邑百戶。去道自殺，昭信棄市。","sentenceOrder":197},
  {"id":"s_work_han_thu_64_198","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「數音所角反。其下亦同。」","sentenceOrder":198},
  {"id":"s_work_han_thu_64_199","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「益大，謂年漸長大也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_64_200","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「倡，樂人也。俳，雜戲者也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_64_201","chapterId":"ch_work_han_thu_64","textTraditional":"〔四〕　如淳曰：「彊，相名也。」","sentenceOrder":201},
  {"id":"s_work_han_thu_64_202","chapterId":"ch_work_han_thu_64","textTraditional":"〔五〕　師古曰：「死者，尸也。次下求其死亦同。」","sentenceOrder":202},
  {"id":"s_work_han_thu_64_203","chapterId":"ch_work_han_thu_64","textTraditional":"〔六〕　師古曰：「得者，為吏所捕得。」","sentenceOrder":203},
  {"id":"s_work_han_thu_64_204","chapterId":"ch_work_han_thu_64","textTraditional":"〔七〕　師古曰：「仍，頻也。重音直用反。」","sentenceOrder":204},
  {"id":"s_work_han_thu_64_205","chapterId":"ch_work_han_thu_64","textTraditional":"立二十二年，國除。後四歲，宣帝地節四年，復立去兄文，是為戴王。文素正直，數諫王去，故上立焉，二年薨。子海陽嗣，十五年，坐畫屋為男女臝交接，置酒請諸父姊妺飲，令仰視畫；又海陽女弟為人妻，而使與幸臣姦；又與從弟調等謀殺一家三人，已殺。甘露四年坐廢，徙房陵，國除。後十五年，平帝元始二年，復立戴王弟襄隄侯子瘉為廣德王，〔一〕奉惠王後，二年薨。子赤嗣，王莽時絕。","sentenceOrder":205},
  {"id":"s_work_han_thu_64_206","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「隄音丁奚反。瘉音愈。」","sentenceOrder":206},
  {"id":"s_work_han_thu_64_207","chapterId":"ch_work_han_thu_64","textTraditional":"膠東康王寄以孝景中二年立，二十八年薨。淮南王謀反時，寄微聞其事，私作兵車鏃矢，〔一〕戰守備，備淮南之起。及吏治淮南事，辭出之。〔二〕寄於上最親，〔三〕意自傷，發病而死，不敢置後。於是上聞寄有長子賢，母無寵，少子慶，母愛幸，寄常欲立之，為非次，因有過，遂無所言。上憐之，立賢為膠東王，奉康王祀，而封慶為六安王，王故衡山地。膠東王賢立十五年薨，諡為哀王。子戴王通平嗣，二十四年薨。子頃王音嗣，五十四年薨。子共王授嗣，十四年薨。子殷嗣，王莽時絕。","sentenceOrder":207},
  {"id":"s_work_han_thu_64_208","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　應劭曰：「樓車也，所以看敵國營壘之虛實也。」師古曰：「兵車止謂戰車耳。鏃矢，大鏃之矢，今所謂兵箭者也。鏃音子木反。」","sentenceOrder":208},
  {"id":"s_work_han_thu_64_209","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「辭語所連，出其事。」","sentenceOrder":209},
  {"id":"s_work_han_thu_64_210","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「寄母王夫人即王皇后之妺，於上為從母，故寄於諸兄弟之中又更親也。此下有常山王云『天子為最親』，其義亦同。」","sentenceOrder":210},
  {"id":"s_work_han_thu_64_211","chapterId":"ch_work_han_thu_64","textTraditional":"六安共王慶立三十八年薨。子夷王祿嗣，十年薨。子繆王定嗣，二十二年薨。子頃王光嗣，二十七年薨。子育嗣，王莽時絕。","sentenceOrder":211},
  {"id":"s_work_han_thu_64_212","chapterId":"ch_work_han_thu_64","textTraditional":"清河哀王乘以孝景中三年立，十二年薨。無子，國除。","sentenceOrder":212},
  {"id":"s_work_han_thu_64_213","chapterId":"ch_work_han_thu_64","textTraditional":"常山憲王舜以孝景中五年立。舜，帝少子，驕淫，數犯禁，上常寬之。三十三年薨，子勃嗣為王。","sentenceOrder":213},
  {"id":"s_work_han_thu_64_214","chapterId":"ch_work_han_thu_64","textTraditional":"初，憲王有不愛姬生長男梲，〔一〕梲以母無寵故，亦不得幸於王。王后脩生太子勃。王內多，所幸姬生子平、子商，王后稀得幸。及憲王疾甚，諸幸姬侍病，王后以妒媢不常在，〔二〕輒歸舍。醫進藥，太子勃不自嘗藥，又不宿留侍疾。及王薨，王后、太子乃至。憲王雅不以梲為子數，〔三〕不分與財物。郎或說太子、王后，令分梲財，皆不聽。太子代立，又不收恤梲。梲怨王后及太子。漢使者視憲王喪，梲自言憲王病時，王后、太子不侍，及薨，六日出舍，〔四〕太子勃私姦、飲酒、博戲、擊筑，與女子載馳，環城過市，〔五〕入獄視囚。天子遣大行騫驗問，〔六〕逮諸證者，〔七〕王又匿之。吏求捕，勃使人致擊笞掠，擅出漢所疑囚。有司請誅勃及憲王后脩。上曰：「脩素無行，使梲陷之罪。勃無良師傅，不忍致誅。」有司請廢勿王，徙王勃以家屬處房陵，上許之。","sentenceOrder":214},
  {"id":"s_work_han_thu_64_215","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　蘇林曰：「音奪。」師古曰：「音他活反，其字從木。」","sentenceOrder":215},
  {"id":"s_work_han_thu_64_216","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「媢亦妒也。媢音冒。」","sentenceOrder":216},
  {"id":"s_work_han_thu_64_217","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「雅，素也。數音所具反。」","sentenceOrder":217},
  {"id":"s_work_han_thu_64_218","chapterId":"ch_work_han_thu_64","textTraditional":"〔四〕　如淳曰：「出服舍也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_64_219","chapterId":"ch_work_han_thu_64","textTraditional":"〔五〕　師古曰：「環，繞也，音宦。」","sentenceOrder":219},
  {"id":"s_work_han_thu_64_220","chapterId":"ch_work_han_thu_64","textTraditional":"〔六〕　師古曰：「張騫也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_64_221","chapterId":"ch_work_han_thu_64","textTraditional":"〔七〕　師古曰：「逮捕之。」","sentenceOrder":221},
  {"id":"s_work_han_thu_64_222","chapterId":"ch_work_han_thu_64","textTraditional":"勃王數月，廢，國除。月餘，天子為最親，詔有司曰：「常山憲王早夭，后妾不和，適孽誣爭，〔一〕陷于不誼以滅國，朕甚閔焉。其封憲王子平三萬戶，為真定王；子商三萬戶，為泗水王。」頃王平立二十五年薨。〔二〕子烈王偃嗣，十八年薨。子孝王由嗣，二十二年薨。子安王雍嗣，二十六年薨。子共王普嗣，十五年薨。子陽嗣，王莽時絕。","sentenceOrder":222},
  {"id":"s_work_han_thu_64_223","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「適音嫡。孽，庶也。」","sentenceOrder":223},
  {"id":"s_work_han_thu_64_224","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「真定頃王也。」","sentenceOrder":224},
  {"id":"s_work_han_thu_64_225","chapterId":"ch_work_han_thu_64","textTraditional":"泗水思王商立十〔二〕年薨。子哀王安世嗣，一年薨，無子。於是武帝憐泗水王絕，復立安世弟賀，是為戴王。立二十二年薨，有遺腹子煖，〔一〕相內史不以聞。太后上書，昭帝閔之，抵相內史罪，立煖，是為勤王。〔二〕立三十九年薨。子戾王駿嗣，三十一年薨。子靖嗣，王莽時絕。","sentenceOrder":225},
  {"id":"s_work_han_thu_64_226","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「煖音許遠反。」","sentenceOrder":226},
  {"id":"s_work_han_thu_64_227","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「勤，諡也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_64_228","chapterId":"ch_work_han_thu_64","textTraditional":"贊曰：昔魯哀公有言：「寡人生於深宮之中，長於婦人之手，未嘗知憂，未嘗知懼。」〔一〕信哉斯言也！雖欲不危亡，不可得已。〔二〕是故古人以宴安為鴆毒，〔三〕亡德而富貴，謂之不幸。漢興，至于孝平，諸侯王以百數，率多驕淫失道。何則？沈溺放恣之中，居勢使然也。自凡人猶繫于習俗，而況哀公之倫乎！夫唯大雅，卓爾不群，河間獻王近之矣。","sentenceOrder":228},
  {"id":"s_work_han_thu_64_229","chapterId":"ch_work_han_thu_64","textTraditional":"〔一〕　師古曰：「哀公與孔子言也。事見孫卿子。」","sentenceOrder":229},
  {"id":"s_work_han_thu_64_230","chapterId":"ch_work_han_thu_64","textTraditional":"〔二〕　師古曰：「已，語終辭。」","sentenceOrder":230},
  {"id":"s_work_han_thu_64_231","chapterId":"ch_work_han_thu_64","textTraditional":"〔三〕　師古曰：「左氏傳管敬仲云『宴安鴆毒，不可懷也』。」","sentenceOrder":231},
  {"id":"s_work_han_thu_64_232","chapterId":"ch_work_han_thu_64","textTraditional":"校勘記","sentenceOrder":232},
  {"id":"s_work_han_thu_64_233","chapterId":"ch_work_han_thu_64","textTraditional":"二四一０頁　六行　山東諸儒（者）〔多〕從而遊。　錢大昕說閩本「者」作「多」。按景祐、殿本都作「多」。","sentenceOrder":233},
  {"id":"s_work_han_thu_64_234","chapterId":"ch_work_han_thu_64","textTraditional":"二四一０頁一六行　造次，謂所嚮（必）〔所〕行也。　史記索隱「必」作「所」。王先謙說此誤。","sentenceOrder":234},
  {"id":"s_work_han_thu_64_235","chapterId":"ch_work_han_thu_64","textTraditional":"二四一二頁　二行　漢中太守請治（元），病死。　景祐、殿本都無「元」字。","sentenceOrder":235},
  {"id":"s_work_han_thu_64_236","chapterId":"ch_work_han_thu_64","textTraditional":"二四二二頁　四行　議者（勿）〔多〕冤晁錯之策，　景祐、殿本都作「多」。王先謙說作「多」是。","sentenceOrder":236},
  {"id":"s_work_han_thu_64_237","chapterId":"ch_work_han_thu_64","textTraditional":"二四二四頁　八行　昧不〔見〕泰山。　錢大昭說，「泰山」上脫「見」字。按景祐、殿本都有「見」字。","sentenceOrder":237},
  {"id":"s_work_han_thu_64_238","chapterId":"ch_work_han_thu_64","textTraditional":"二四二五頁　五行　葭，蘆〔葉〕也。　景祐、殿本都有「葉」字。","sentenceOrder":238},
  {"id":"s_work_han_thu_64_239","chapterId":"ch_work_han_thu_64","textTraditional":"二四二五頁　六行　葭莩喻（著）〔薄〕，　景祐本作「薄」。","sentenceOrder":239},
  {"id":"s_work_han_thu_64_240","chapterId":"ch_work_han_thu_64","textTraditional":"二四三０頁　三行　今關中俗婦呼舅（姑）為鍾。　景祐、殿本都無「姑」字。","sentenceOrder":240},
  {"id":"s_work_han_thu_64_241","chapterId":"ch_work_han_thu_64","textTraditional":"二四三六頁　一行　泗水思王商立十〔二〕年薨。　景祐、殿本都有「二」字。史記作「十一年」。","sentenceOrder":241},
  {"id":"s_work_han_thu_65_1","chapterId":"ch_work_han_thu_65","textTraditional":"李廣，隴西成紀人也。其先曰李信，秦時為將，逐得燕太子丹者也。廣世世受射。〔一〕孝文十四年，匈奴大入蕭關，〔二〕而廣以良家子從軍擊胡，用善射，殺首虜多，為郎，騎常侍。〔三〕數從射獵，格殺猛獸，文帝曰：「惜廣不逢時，令當高祖世，萬戶侯豈足道哉！」","sentenceOrder":1},
  {"id":"s_work_han_thu_65_2","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「受射法。」","sentenceOrder":2},
  {"id":"s_work_han_thu_65_3","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「在上郡北。」","sentenceOrder":3},
  {"id":"s_work_han_thu_65_4","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「官為郎，常騎以侍天子，故曰騎常侍。」","sentenceOrder":4},
  {"id":"s_work_han_thu_65_5","chapterId":"ch_work_han_thu_65","textTraditional":"景帝即位，為騎郎將。〔一〕吳楚反時，為驍騎都尉，從太尉亞夫戰昌邑下，顯名。以梁王授廣將軍印，故還，賞不行。〔二〕為上谷太守，數與匈奴戰。典屬國公孫昆邪為上泣曰：〔三〕「李廣材氣，天下亡雙，自負其能，數與虜确，恐亡之。」〔四〕上乃徙廣為上郡太守。","sentenceOrder":5},
  {"id":"s_work_han_thu_65_6","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「為騎郎之將，主騎郎。」","sentenceOrder":6},
  {"id":"s_work_han_thu_65_7","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　文穎曰：「廣為漢將，私受梁印，故不得賞也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_65_8","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　服虔曰：「昆邪，中國人也。」師古曰：「對上而泣也。昆音下溫反。」","sentenceOrder":8},
  {"id":"s_work_han_thu_65_9","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　師古曰：「負，恃也。确謂競勝敗也。确音角。」","sentenceOrder":9},
  {"id":"s_work_han_thu_65_10","chapterId":"ch_work_han_thu_65","textTraditional":"匈奴（入）〔侵〕上郡，上使中貴人從廣〔一〕勒習兵擊匈奴。中貴人者將數十騎從，〔二〕見匈奴三人，與戰。射傷中貴人，殺其騎且盡。中貴人走廣，〔三〕廣曰：「是必射鵰者也。」〔四〕廣乃從百騎往馳三人。〔五〕三人亡馬步行，行數十里。廣令其騎張左右翼，〔六〕而廣身自射彼三人者，殺其二人，生得一人，果匈奴射鵰者也。已縛之上山，望匈奴數千騎，見廣，以為誘騎，驚，上山陳。〔七〕廣之百騎皆大恐，欲馳還走。廣曰：「我去大軍數十里，今如此走，匈奴追射，我立盡。今我留，匈奴必以我為大軍之誘，不我擊。」〔八〕廣令曰：「前！」未到匈奴陳二里所，止，令曰：「皆下馬解鞍！」騎曰：「虜多如是，解鞍，即急，柰何？」廣曰：「彼虜以我為走，今解鞍以示不去，用堅其意。」〔九〕有白馬將出護兵。〔一０〕廣上馬，與十餘騎奔射殺白馬將，而復還至其百騎中，解鞍，縱馬臥。〔一一〕時會暮，胡兵終怪之，弗敢擊。夜半，胡兵以為漢有伏軍於傍欲夜取之，即引去。平旦，廣乃歸其大軍。後徙為隴西、北地、雁門、雲中太守。","sentenceOrder":10},
  {"id":"s_work_han_thu_65_11","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　服虔曰：「內臣之貴幸者。」","sentenceOrder":11},
  {"id":"s_work_han_thu_65_12","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　張晏曰：「放（從）〔縱〕遊獵也。」師古曰：「張讀作縱，此說非也。直言將數十騎自隨，在大軍前行而忽遇敵也。從音才用反。」","sentenceOrder":12},
  {"id":"s_work_han_thu_65_13","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「走，趣也，音奏。」","sentenceOrder":13},
  {"id":"s_work_han_thu_65_14","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　文穎曰：「鵰，鳥也，故使善射者射之。」師古曰：「鵰，大鷙鳥也，一名鷲，黑色，翮可以為箭羽，音彫。」","sentenceOrder":14},
  {"id":"s_work_han_thu_65_15","chapterId":"ch_work_han_thu_65","textTraditional":"〔五〕　師古曰：「疾馳而逐之。」","sentenceOrder":15},
  {"id":"s_work_han_thu_65_16","chapterId":"ch_work_han_thu_65","textTraditional":"〔六〕　師古曰：「旁引其騎，若鳥翼之為。」","sentenceOrder":16},
  {"id":"s_work_han_thu_65_17","chapterId":"ch_work_han_thu_65","textTraditional":"〔七〕　師古曰：「為陳以待廣也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_65_18","chapterId":"ch_work_han_thu_65","textTraditional":"〔八〕　師古曰：「不我擊，不敢擊我也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_65_19","chapterId":"ch_work_han_thu_65","textTraditional":"〔九〕　師古曰：「示以堅牢，令敵意知之。」","sentenceOrder":19},
  {"id":"s_work_han_thu_65_20","chapterId":"ch_work_han_thu_65","textTraditional":"〔一０〕師古曰：「將之乘白馬者也。護謂監視之。」","sentenceOrder":20},
  {"id":"s_work_han_thu_65_21","chapterId":"ch_work_han_thu_65","textTraditional":"〔一一〕師古曰：「縱，放也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_65_22","chapterId":"ch_work_han_thu_65","textTraditional":"武帝即位，左右言廣名將也，由是入為未央衛尉，而程不識時亦為長樂衛尉。程不識故與廣俱以邊太守將屯。及出擊胡，而廣行無部曲行陳，〔一〕就善水草頓舍，人人自便，〔二〕不擊（刀）〔刁〕斗自衛，〔三〕莫府省文書，〔四〕然亦遠斥候，未嘗遇害。程不識正部曲行伍營陳，擊（刀）〔刁〕斗，吏治軍簿〔五〕至明，軍不得自便。不識曰：「李將軍極簡易，然虜卒犯之，無以禁；〔六〕而其士亦佚樂，〔七〕為之死。我軍雖煩擾，虜亦不得犯我。」是時漢邊郡李廣、程不識為名將，然匈奴畏廣，士卒多樂從，而苦程不識〔八〕。不識孝景時以數直諫為太中大夫，為人廉，謹於文法。","sentenceOrder":22},
  {"id":"s_work_han_thu_65_23","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「續漢書百官志云『將軍領軍，皆有部曲。大將軍營五部，部校尉一人。部下有曲，曲有軍候一人。』今廣尚於簡易，故行道之中而不立部曲也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_65_24","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「頓，止也。舍，息也。便，安利也，音頻面反。其下亦同。」","sentenceOrder":24},
  {"id":"s_work_han_thu_65_25","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　孟康曰：「（刀）〔刁〕斗，以銅作鐎，受一斗。晝炊飯食，夜擊持行夜，名曰（刀）〔刁〕斗。今在滎陽庫中也。」蘇林曰：「形如鋗，無緣。」師古曰：「鐎音譙郡之譙，溫器也。鋗音火玄反。鋗即銚也。今俗或呼銅銚，音姚。」","sentenceOrder":25},
  {"id":"s_work_han_thu_65_26","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　晉灼曰：「將軍職在征行，無常處，所在為治，故言莫府也。莫，大也。或曰，衛青征匈奴，絕大莫，大克獲，帝就拜大將軍於幕中府，故曰莫府。莫府之名始於此也。」師古曰：「二說皆非也。莫府者，以軍幕為義，古字通單用耳。軍旅無常居止，故以帳幕言之。廉頗、李牧市租皆入幕府，此則非因衛青始有其號。又莫訓大，於義乖矣。省，少也，音所領反。」","sentenceOrder":26},
  {"id":"s_work_han_thu_65_27","chapterId":"ch_work_han_thu_65","textTraditional":"〔五〕　師古曰：「簿，文簿，音步戶反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_65_28","chapterId":"ch_work_han_thu_65","textTraditional":"〔六〕　師古曰：「卒讀曰猝。」","sentenceOrder":28},
  {"id":"s_work_han_thu_65_29","chapterId":"ch_work_han_thu_65","textTraditional":"〔七〕　師古曰：「佚與逸同。逸樂，謂閑豫也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_65_30","chapterId":"ch_work_han_thu_65","textTraditional":"〔八〕　師古曰：「苦謂厭苦之也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_65_31","chapterId":"ch_work_han_thu_65","textTraditional":"後漢誘單于以馬邑城，使大軍伏馬邑傍，而廣為驍騎將軍，屬護軍將軍。〔一〕單于覺之，去，漢軍皆無功。後四歲，廣以衛尉為將軍，出雁門擊匈奴。匈奴兵多，破廣軍，生得廣。單于素聞廣賢，令曰：「得李廣必生致之。」胡騎得廣，廣時傷，置兩馬間，絡而盛（之）臥。行十餘里，廣陽死，睨其傍有一兒騎善馬，〔二〕暫騰而上胡兒馬，〔三〕因抱兒鞭馬南馳數十里，得其餘軍。匈奴騎數百追之，廣行取兒弓射殺追騎，〔四〕以故得脫。於是至漢，漢下廣吏。吏當廣亡失多，為虜所生得，〔五〕當斬，贖為庶人。","sentenceOrder":31},
  {"id":"s_work_han_thu_65_32","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「韓安國。」","sentenceOrder":32},
  {"id":"s_work_han_thu_65_33","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「睨，邪視也，音五係反。」","sentenceOrder":33},
  {"id":"s_work_han_thu_65_34","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「騰，跳躍也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_65_35","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　師古曰：「且行且射也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_65_36","chapterId":"ch_work_han_thu_65","textTraditional":"〔五〕　師古曰：「當謂處其罪也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_65_37","chapterId":"ch_work_han_thu_65","textTraditional":"數歲，與故潁陰侯屏居藍田南山中射獵。〔一〕嘗夜從一騎出，從人田間飲。還至亭，霸陵尉醉，呵止廣，廣騎曰：「故李將軍。」尉曰：「今將軍尚不得夜行，何故也！」宿廣亭下。居無何，匈奴入遼西，殺太守，敗韓將軍。〔二〕韓將軍後徙居右北平，死。於是上乃召拜廣為右北平太守。廣請霸陵尉與俱，〔三〕至軍而斬之，上書自陳謝罪。上報曰：「將軍者，國之爪牙也。司馬法曰：『登車不式，遭喪不服，〔四〕振旅撫師，以征不服；率三軍之心，同戰士之力，故怒形則千里竦，威振則萬物伏；〔五〕是以名聲暴於夷貉，威稜憺乎鄰國。』〔六〕夫報忿除害，捐殘去殺，朕之所圖於將軍也；若乃免冠徒跣，稽顙請罪，豈朕之指哉！〔七〕將軍其率師東轅，彌節白檀，〔八〕以臨右北平盛秋。」〔九〕廣在郡，匈奴號曰「漢飛將軍」，避之，數歲不入界。","sentenceOrder":37},
  {"id":"s_work_han_thu_65_38","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「潁陰侯，灌嬰之孫，名彊。」","sentenceOrder":38},
  {"id":"s_work_han_thu_65_39","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　蘇林曰：「韓安國。」","sentenceOrder":39},
  {"id":"s_work_han_thu_65_40","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「奏謂天子而將行。」","sentenceOrder":40},
  {"id":"s_work_han_thu_65_41","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　服虔曰：「式，撫車之式以禮敬人也。式者，車前橫木也，字或作軾。」","sentenceOrder":41},
  {"id":"s_work_han_thu_65_42","chapterId":"ch_work_han_thu_65","textTraditional":"〔五〕　師古曰：「竦，驚也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_65_43","chapterId":"ch_work_han_thu_65","textTraditional":"〔六〕　李奇曰：「神靈之威曰稜。憺猶動也。」蘇林曰：「陳留人語恐言憺之。」師古曰：「稜音來登反。憺音徒濫反。」","sentenceOrder":43},
  {"id":"s_work_han_thu_65_44","chapterId":"ch_work_han_thu_65","textTraditional":"〔七〕　師古曰：「指，意也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_65_45","chapterId":"ch_work_han_thu_65","textTraditional":"〔八〕　孟康曰：「白檀，縣名也，屬右北平。」李奇曰：「彌節，少安之貌。」師古曰：「彌音亡俾反。」","sentenceOrder":45},
  {"id":"s_work_han_thu_65_46","chapterId":"ch_work_han_thu_65","textTraditional":"〔九〕　師古曰：「盛秋馬肥，恐虜為寇，故令折衝禦難也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_65_47","chapterId":"ch_work_han_thu_65","textTraditional":"廣出獵，見草中石，以為虎而射之，中石沒矢，視之，石也。他日射之，終不能入矣。廣所居郡聞有虎，常自射之。及居右北平射虎，虎騰傷廣，廣亦射殺之。","sentenceOrder":47},
  {"id":"s_work_han_thu_65_48","chapterId":"ch_work_han_thu_65","textTraditional":"石建卒，上召廣代為郎中令。元朔六年，廣復為將軍，從大將軍出定襄。諸將多中首虜率為侯者，〔一〕而廣軍無功。後三歲，廣以郎中令將四千騎出右北平，博望侯張騫將萬騎與廣俱，異道。行數百里，匈奴左賢王將四萬騎圍廣，廣軍士皆恐，廣乃使其子敢往馳之。敢從數十騎直貫胡騎，出其左右而還，報廣曰：「胡虜易與耳。」軍士乃安。為圜陳外鄉，〔二〕胡急擊，矢下如雨。漢兵死者過半，漢矢且盡。廣乃令持滿毋發，〔三〕而廣身自以大黃射其裨將，〔四〕殺數人，胡虜益解。會暮，吏士無人色，〔五〕而廣意氣自如，〔六〕益治軍。〔七〕軍中服其勇也。明日，復力戰，而博望侯軍亦至，匈奴乃解去。漢軍罷，弗能追。〔八〕是時廣軍幾沒，〔九〕罷歸。漢法，博望侯後期，當死，贖為庶人。廣軍自當，亡賞。〔一０〕","sentenceOrder":48},
  {"id":"s_work_han_thu_65_49","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　如淳曰：「中猶充也，充本法得首若干封侯也。」師古曰：「率謂軍功封賞之科著在法令者也。中音竹仲反。其下率亦同。」","sentenceOrder":49},
  {"id":"s_work_han_thu_65_50","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":50},
  {"id":"s_work_han_thu_65_51","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「注矢於弓弩而引滿之，不發矢也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_65_52","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　服虔曰：「黃肩弩也。」孟康曰：「太公陷堅卻敵，以大黃參連弩也。」晉灼曰：「黃肩即黃間也，大黃其大者也。」師古曰：「服、晉二說是也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_65_53","chapterId":"ch_work_han_thu_65","textTraditional":"〔五〕　師古曰：「言懼甚。」","sentenceOrder":53},
  {"id":"s_work_han_thu_65_54","chapterId":"ch_work_han_thu_65","textTraditional":"〔六〕　師古曰：「自如，猶云如舊。」","sentenceOrder":54},
  {"id":"s_work_han_thu_65_55","chapterId":"ch_work_han_thu_65","textTraditional":"〔七〕　師古曰：「巡部曲，整行陳也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_65_56","chapterId":"ch_work_han_thu_65","textTraditional":"〔八〕　師古曰：「罷讀曰疲。」","sentenceOrder":56},
  {"id":"s_work_han_thu_65_57","chapterId":"ch_work_han_thu_65","textTraditional":"〔九〕　師古曰：「幾音鉅衣反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_65_58","chapterId":"ch_work_han_thu_65","textTraditional":"〔一０〕師古曰：「自當，謂為虜所勝，又能勝虜，功過相當也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_65_59","chapterId":"ch_work_han_thu_65","textTraditional":"初，廣與從弟李蔡俱為郎，事文帝。景帝時，蔡積功至二千石。武帝元朔中，為輕車將軍，從大將軍擊右賢王，有功中率，封為樂安侯。〔一〕元狩二年，代公孫弘為丞相。蔡為人在下中，〔二〕名聲出廣下遠甚，然廣不得爵邑，官不過九卿。廣之軍吏及士卒或取封侯。廣與望氣王朔語云：「自漢擊匈奴，廣未嘗不在其中，而諸妄校尉已下，〔三〕材能不及中，〔四〕以軍功取侯者數十人。廣不為後人，然終無尺寸功以得封邑者，何也？豈吾相不當侯邪？」朔曰：「將軍自念，豈嘗有恨者乎？」〔五〕廣曰：「吾為隴西守，羌嘗反，吾誘降者八百餘人，詐而同日殺之，至今恨獨此耳。」朔曰：「禍莫大於殺已降，此乃將軍所以不得侯者也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_65_60","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「此傳及百官表為樂安侯，而功臣表作安樂侯，是功臣表誤也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_65_61","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「在下輩之中。」","sentenceOrder":61},
  {"id":"s_work_han_thu_65_62","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　張晏曰：「妄猶凡也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_65_63","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　師古曰：「中謂中庸之人也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_65_64","chapterId":"ch_work_han_thu_65","textTraditional":"〔五〕　師古曰：「恨，悔也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_65_65","chapterId":"ch_work_han_thu_65","textTraditional":"廣歷七郡太守，前後四十餘年，得賞賜，輒分其戲下，〔一〕飲食與士卒共之。家無餘財，終不言生產事。為人長，爰臂，〔二〕其善射亦天性，雖子孫他人學者莫能及。廣吶口少言，〔三〕與人居，則畫地為軍陳，射闊狹以飲。專以射為戲。〔四〕將兵乏絕處見水，士卒不盡飲，不近水，不盡餐，不嘗食。寬緩不苛，〔五〕士以此愛樂為用。其射，見敵，非在數十步之內，度不中不發，〔六〕發即應弦而倒。用此，其將數困辱，及射猛獸，亦數為所傷云。","sentenceOrder":65},
  {"id":"s_work_han_thu_65_66","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「戲讀曰麾，又音許宜反。」","sentenceOrder":66},
  {"id":"s_work_han_thu_65_67","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　如淳曰：「臂如猿臂通肩也。或曰，似當為緩臂也。」師古曰：「王國風菟爰之詩云『有菟爰爰』，爰爰，緩意也，其義兩通。」","sentenceOrder":67},
  {"id":"s_work_han_thu_65_68","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「吶亦訥字。」","sentenceOrder":68},
  {"id":"s_work_han_thu_65_69","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　如淳曰：「為戲求疏密，持酒以飲不勝者也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_65_70","chapterId":"ch_work_han_thu_65","textTraditional":"〔五〕　師古曰：「苛，細也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_65_71","chapterId":"ch_work_han_thu_65","textTraditional":"〔六〕　師古曰：「度音待各反。中音竹仲反。」","sentenceOrder":71},
  {"id":"s_work_han_thu_65_72","chapterId":"ch_work_han_thu_65","textTraditional":"元狩四年，大將軍票騎將軍大擊匈奴，廣數自請行。上以為老，不許；良久乃許之，以為前將軍。","sentenceOrder":72},
  {"id":"s_work_han_thu_65_73","chapterId":"ch_work_han_thu_65","textTraditional":"大將軍青出塞，捕虜知單于所居，乃自以精兵走之，〔一〕而令廣并於右將軍軍，出東道。〔二〕東道少回遠，〔三〕大軍行，水草少，甚勢不屯行。〔四〕廣辭曰：「臣部為前將軍，今大將軍乃徙臣出東道，且臣結髮而與匈奴戰，〔五〕乃今一得當單于，臣願居前，先死單于。」〔六〕大將軍陰受上指，以為李廣數奇，〔七〕毋令當單于，恐不得所欲。〔八〕是時公孫敖新失侯，為中將軍，大將軍亦欲使敖與俱當單于，故徙廣。廣知之，固辭。大將軍弗聽，令長史封書與廣之莫府，〔九〕曰：「急詣部，如書。」廣不謝大將軍而起行，意象慍怒〔一０〕而就部，引兵與右將軍食其合軍出東道。〔一一〕惑失道，後大將軍。〔一二〕大將軍與單于接戰，單于遁走，弗能得而還。南絕幕，乃遇兩將軍。〔一三〕廣已見大將軍，還入軍。大將軍使長史持糒醪遺廣，〔一四〕因問廣、食其失道狀，曰：「青欲上書報天子失軍曲折。」〔一五〕廣未對。大將軍長史急責廣之莫府上簿。〔一六〕廣曰：「諸校尉亡罪，乃我自失道。吾今自上簿。」","sentenceOrder":73},
  {"id":"s_work_han_thu_65_74","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「走，趣也，音奏。」","sentenceOrder":74},
  {"id":"s_work_han_thu_65_75","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「并，合也，合軍而同道。」","sentenceOrder":75},
  {"id":"s_work_han_thu_65_76","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「回，遶也，曲也，音胡悔反。」","sentenceOrder":76},
  {"id":"s_work_han_thu_65_77","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　張晏曰：「以水草少，不可群輩也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_65_78","chapterId":"ch_work_han_thu_65","textTraditional":"〔五〕　師古曰：「言始勝冠即在戰陳。」","sentenceOrder":78},
  {"id":"s_work_han_thu_65_79","chapterId":"ch_work_han_thu_65","textTraditional":"〔六〕　師古曰：「致死而取單于。」","sentenceOrder":79},
  {"id":"s_work_han_thu_65_80","chapterId":"ch_work_han_thu_65","textTraditional":"〔七〕　孟康曰：「奇，隻不耦也。」如淳曰：「數為匈奴所敗，為奇不耦。」師古曰：「言廣命隻不耦合也。孟說是矣。數音所角反。奇音居宜反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_65_81","chapterId":"ch_work_han_thu_65","textTraditional":"〔八〕　師古曰：「謂不勝敵也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_65_82","chapterId":"ch_work_han_thu_65","textTraditional":"〔九〕　師古曰：「之，往也。莫府，衛青行軍府。」","sentenceOrder":82},
  {"id":"s_work_han_thu_65_83","chapterId":"ch_work_han_thu_65","textTraditional":"〔一０〕師古曰：「言慍怒之色形於外也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_65_84","chapterId":"ch_work_han_thu_65","textTraditional":"〔一一〕師古曰：「趙食其也。食音異。其音基。」","sentenceOrder":84},
  {"id":"s_work_han_thu_65_85","chapterId":"ch_work_han_thu_65","textTraditional":"〔一二〕師古曰：「惑，迷也。在後不及期也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_65_86","chapterId":"ch_work_han_thu_65","textTraditional":"〔一三〕師古曰：「絕，渡也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_65_87","chapterId":"ch_work_han_thu_65","textTraditional":"〔一四〕師古曰：「糒，乾飯也。醪，汁滓酒也。糒音備。醪音牢。」","sentenceOrder":87},
  {"id":"s_work_han_thu_65_88","chapterId":"ch_work_han_thu_65","textTraditional":"〔一五〕師古曰：「曲折猶言委曲也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_65_89","chapterId":"ch_work_han_thu_65","textTraditional":"〔一六〕師古曰：「之，往也。簿謂文狀也，音步戶反。」","sentenceOrder":89},
  {"id":"s_work_han_thu_65_90","chapterId":"ch_work_han_thu_65","textTraditional":"至莫府，謂其麾下曰：「廣結髮與匈奴大小七十餘戰，今幸從大將軍出接單于兵，而大將軍徙廣部行回遠，又迷失道，豈非天哉！且廣年六十餘，終不能復對刀筆之吏矣！」遂引刀自剄。百姓聞之，知與不知，老壯皆為垂泣。〔一〕而右將軍獨下吏，當死，贖為庶人。","sentenceOrder":90},
  {"id":"s_work_han_thu_65_91","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「知謂素相識知也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_65_92","chapterId":"ch_work_han_thu_65","textTraditional":"廣三子，曰當戶、椒、敢，皆為郎。上與韓嫣戲，嫣少不遜〔一〕，當戶擊嫣，嫣走，於是上以為能。當戶蚤死，〔二〕乃拜椒為代郡太守，皆先廣死。廣死軍中時，敢從票騎將軍。廣死明年，李蔡以丞相坐詔賜冢地陽陵當得二十畝，蔡盜取三頃，頗賣得四十餘萬，又盜取神道外壖地一畝葬其中，〔三〕當下獄，自殺。敢以校尉從票騎將軍擊胡左賢王，力戰，奪左賢王旗鼓，斬首多，賜爵關內侯，食邑二百戶，代廣為郎中令。頃之，怨大將軍青之恨其父，〔四〕乃擊傷大將軍，大將軍匿諱之。居無何，敢從上雍，至甘泉宮獵，〔五〕票騎將軍去病怨敢傷青，射殺敢。去病時方貴幸，上為諱，云鹿觸殺之。居歲餘，去病死。","sentenceOrder":92},
  {"id":"s_work_han_thu_65_93","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「嫣音偃。」","sentenceOrder":93},
  {"id":"s_work_han_thu_65_94","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「蚤，古早字。」","sentenceOrder":94},
  {"id":"s_work_han_thu_65_95","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「壖音人椽反。」","sentenceOrder":95},
  {"id":"s_work_han_thu_65_96","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　師古曰：「令其父恨而死也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_65_97","chapterId":"ch_work_han_thu_65","textTraditional":"〔五〕　師古曰：「無何，謂未多時也。雍之所在，地形積高，故云上也。上音時掌反。他皆類此。」","sentenceOrder":97},
  {"id":"s_work_han_thu_65_98","chapterId":"ch_work_han_thu_65","textTraditional":"敢有女為太子中人，愛幸。敢男禹有寵於太子，然好利，亦有勇。嘗與侍中貴人飲，侵陵之，莫敢應。〔一〕後愬之上，上召禹，使刺虎，縣下圈中，未至地，有詔引出之。禹從落中以劍斫絕纍，欲刺虎。〔二〕上壯之，遂救止焉。而當戶有遺腹子陵，將兵擊胡，兵敗，降匈奴。後人告禹謀欲亡從陵，下吏死。","sentenceOrder":98},
  {"id":"s_work_han_thu_65_99","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「言畏其勇氣。」","sentenceOrder":99},
  {"id":"s_work_han_thu_65_100","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「落與絡同，謂當時繈絡之而下也。纍，索也，音力追反。」","sentenceOrder":100},
  {"id":"s_work_han_thu_65_101","chapterId":"ch_work_han_thu_65","textTraditional":"陵字少卿，少為侍中建章監。善騎射，愛人，謙讓下士，〔一〕甚得名譽。武帝以為有廣之風，使將八百騎，深入匈奴二千餘里，過居延視地形，不見虜，還。拜為騎都尉，將勇敢五千人，教射酒泉、張掖以備胡。數年，漢遣貳師將軍伐大宛，使陵將五校兵隨後。行至塞，會貳師還。上賜陵書，陵留吏士，與輕騎五百出敦煌，至鹽水，迎貳師還，復留屯張掖。","sentenceOrder":101},
  {"id":"s_work_han_thu_65_102","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「下音胡亞反。」","sentenceOrder":102},
  {"id":"s_work_han_thu_65_103","chapterId":"ch_work_han_thu_65","textTraditional":"天漢二年，貳師將三萬騎出酒泉，擊右賢王於天山。召陵，欲使為貳師將輜重。〔一〕陵召見武臺，〔二〕叩頭自請曰：「臣所將屯邊者，皆荊楚勇士奇材劍客也，力扼虎，射命中，〔三〕願得自當一隊，〔四〕到蘭干山南以分單于兵，毋令專鄉貳師軍。」〔五〕上曰：「將惡相屬邪！吾發軍多，毋騎予女。」陵對：「對所事騎，〔六〕臣願以少擊眾，步兵五千人涉單于庭。」上壯而許之，因詔彊弩都尉路博德將兵半道迎陵軍。博德故伏波將軍，亦羞為陵後距，奏言：「方秋匈奴馬肥，未可與戰，臣願留陵至春，俱將酒泉、張掖騎各五千人並擊東西浚稽，可必禽也。」〔七〕書奏，上怒，疑陵悔不欲出而教博德上書，乃詔博德：「吾欲予李陵騎，云『欲以少擊眾』。今虜入西河，其引兵走西河，遮鉤營之道。」〔八〕詔陵：「以九月發，出遮虜鄣，〔九〕至東浚稽山南龍勒水上，徘徊觀虜，即亡所見，從浞野侯趙破奴故道抵受降城休士，〔一０〕因騎置以聞。〔一一〕所與博德言者云何？〔一二〕具以書對。」陵於是將其步卒五千人出居延，北行三十日，至浚稽山止營，舉圖所過山川地形，使麾下騎陳步樂還以聞。步樂召見，道陵將率得士死力，上甚說，〔一三〕拜步樂為郎。","sentenceOrder":103},
  {"id":"s_work_han_thu_65_104","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「重音直用反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_65_105","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「未央宮有武臺殿。」","sentenceOrder":105},
  {"id":"s_work_han_thu_65_106","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「扼謂捉持之也。命中者，所指名處即中之也。扼音厄。」","sentenceOrder":106},
  {"id":"s_work_han_thu_65_107","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　師古曰：「隊，部也，音徒內反。」","sentenceOrder":107},
  {"id":"s_work_han_thu_65_108","chapterId":"ch_work_han_thu_65","textTraditional":"〔五〕　師古曰：「鄉讀曰同。」","sentenceOrder":108},
  {"id":"s_work_han_thu_65_109","chapterId":"ch_work_han_thu_65","textTraditional":"〔六〕　師古曰：「猶言不事須騎也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_65_110","chapterId":"ch_work_han_thu_65","textTraditional":"〔七〕　師古曰：「浚稽，山名。時虜分居此兩山也。浚音峻。稽音雞。」","sentenceOrder":110},
  {"id":"s_work_han_thu_65_111","chapterId":"ch_work_han_thu_65","textTraditional":"〔八〕　張晏曰：「胡來要害道，令博德遮之。」師古曰：「走音奏。」","sentenceOrder":111},
  {"id":"s_work_han_thu_65_112","chapterId":"ch_work_han_thu_65","textTraditional":"〔九〕　師古曰：「鄣者，塞上險要之處，往往修築，別置候望之人，所以自鄣蔽而伺敵也。遮虜，鄣名也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_65_113","chapterId":"ch_work_han_thu_65","textTraditional":"〔一０〕師古曰：「抵，歸也。受降城本公孫敖所築。休，息也。浞音仕角反。」","sentenceOrder":113},
  {"id":"s_work_han_thu_65_114","chapterId":"ch_work_han_thu_65","textTraditional":"〔一一〕師古曰：「騎置，謂驛騎也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_65_115","chapterId":"ch_work_han_thu_65","textTraditional":"〔一二〕張晏曰：「天子疑陵教博德上書求至春乃俱西也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_65_116","chapterId":"ch_work_han_thu_65","textTraditional":"〔一三〕師古曰：「說讀曰悅。」","sentenceOrder":116},
  {"id":"s_work_han_thu_65_117","chapterId":"ch_work_han_thu_65","textTraditional":"陵至浚稽山，與單于相直，騎可三萬圍陵軍。軍居兩山間，以大車為營。陵引士出營外為陳，前行持戟盾，後行持弓弩，〔一〕令曰：「聞鼓聲而縱，聞金聲而止。」〔二〕虜見漢軍少，直前就營。陵搏戰攻之，〔三〕千弩俱發，應弦而倒。虜還走上山，漢軍追擊，殺數千人。單于大驚，召左右地兵八萬餘騎攻陵。陵且戰且引，南行數日，抵山谷中。〔四〕連戰，士卒中矢傷，三創者載輦，兩創者將車，一創者持兵戰。陵曰：「吾士氣少衰而鼓不起者，何也？〔五〕軍中豈有女子乎？」始軍出時，關東群盜妻子徙邊者隨軍為卒妻婦，大匿車中。陵搜得，皆劍斬之。明日復戰，斬首三千餘級。引兵東南，循故龍城道行，四五日，抵大澤葭葦中，〔六〕虜從上風縱火，陵亦令軍中縱火以自救。〔七〕南行至山下，單于在南山上，使其子將騎擊陵。陵軍步鬥樹木間，復殺數千人，因發連弩射單于，〔八〕單于下走。是日捕得虜，言「單于曰：『此漢精兵，擊之不能下，日夜引吾南近塞，得毋有伏兵乎？』諸當戶君長皆言〔九〕『單于自將數萬騎擊漢數千人不能滅，後無以復使邊臣，令漢益輕匈奴。復力戰山谷間，尚四五十里得平地，不能破，乃還。』」","sentenceOrder":117},
  {"id":"s_work_han_thu_65_118","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「行並音胡剛反。」","sentenceOrder":118},
  {"id":"s_work_han_thu_65_119","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「金謂鉦也，一名鐲，鐲音濁。」","sentenceOrder":119},
  {"id":"s_work_han_thu_65_120","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　如淳曰：「手對戰也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_65_121","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　師古曰：「抵，當也，至也。其下亦同。，」","sentenceOrder":121},
  {"id":"s_work_han_thu_65_122","chapterId":"ch_work_han_thu_65","textTraditional":"〔五〕　師古曰：「擊鼓進士而士氣不起也。一曰，士卒以有妻婦，故聞鼓音而不時起也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_65_123","chapterId":"ch_work_han_thu_65","textTraditional":"〔六〕　師古曰：「葭即蘆也，音家。」","sentenceOrder":123},
  {"id":"s_work_han_thu_65_124","chapterId":"ch_work_han_thu_65","textTraditional":"〔七〕　師古曰：「預自燒其旁草木，令虜火不得延及也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_65_125","chapterId":"ch_work_han_thu_65","textTraditional":"〔八〕　服虔曰：「三十弩共一弦也。」張晏曰：「三十絭共一臂也。」師古曰：「張說是也。絭音去權反，又音眷。」","sentenceOrder":125},
  {"id":"s_work_han_thu_65_126","chapterId":"ch_work_han_thu_65","textTraditional":"〔九〕　師古曰：「當戶，匈奴官名也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_65_127","chapterId":"ch_work_han_thu_65","textTraditional":"是時陵軍益急，匈奴騎多，戰一日數十合，復傷殺虜二千餘人。虜不利，欲去，會陵軍候管敢為校尉所辱，亡降匈奴，具言「陵軍無後救，射矢且盡，獨將軍麾下及成安侯校各八百人為前行，以黃與白為幟，〔一〕當使精騎射之即破矣。」成安侯者，穎川人，父韓千秋，故濟南相，奮擊南越戰死，武帝封子延年為侯，以校尉隨陵。單于得敢大喜，使騎並攻漢軍，疾呼曰：「李陵、韓延年趣降！」〔二〕遂遮道急攻陵。陵居谷中，虜在山上，四面射，矢如雨下。漢軍南行，未至鞮汗山，〔三〕一日五十萬矢皆盡，即棄車去。士尚三千餘人，徒斬車輻而持之，〔四〕軍吏持尺刀，抵山入陿谷。單于遮其後，乘隅下壘石，〔五〕士卒多死，不得行。昏後，陵便衣獨步出營〔六〕，止左右：「毋隨我，丈夫一取單于耳！」〔七〕良久，陵還，大息曰：「兵敗，死矣！」軍吏或曰：「將軍威震匈奴，天命不遂，後求道徑還歸，如浞野侯為虜所得，後亡還，天子客遇之，況於將軍乎！」陵曰：「公止！吾不死，非壯士也。」於是盡斬旌旗，及珍寶埋地中，陵歎曰：「復得數十矢，足以脫矣。今無兵復戰，〔八〕天明坐受縛矣！各鳥獸散，猶有得脫歸報天子者。」〔九〕令軍士人持二升糒，一半冰，〔一０〕期至遮虜鄣者相待。夜半時，擊鼓起士，鼓不鳴。陵與韓延年俱上馬，壯士從者十餘人。虜騎數千追之，韓延年戰死。陵曰：「無面目報陛下！」遂降。軍人分散，脫至塞者四百餘人。","sentenceOrder":127},
  {"id":"s_work_han_thu_65_128","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「幟，旗也，音式志反。」","sentenceOrder":128},
  {"id":"s_work_han_thu_65_129","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「且攻且呼也。呼音火故反。趣讀曰促。」","sentenceOrder":129},
  {"id":"s_work_han_thu_65_130","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「鞮音丁奚反。」","sentenceOrder":130},
  {"id":"s_work_han_thu_65_131","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　師古曰：「徒，但也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_65_132","chapterId":"ch_work_han_thu_65","textTraditional":"〔五〕　服虔曰：「山名也。」師古曰：「此說非也。言放石以投人，因山隅曲而下也。壘音盧對反。」","sentenceOrder":132},
  {"id":"s_work_han_thu_65_133","chapterId":"ch_work_han_thu_65","textTraditional":"〔六〕　蘇林曰：「搴衣卷褏而行也。」師古曰：「此說非也。便衣，謂著短衣小褏也。」","sentenceOrder":133},
  {"id":"s_work_han_thu_65_134","chapterId":"ch_work_han_thu_65","textTraditional":"〔七〕　師古曰：「言一身獨取也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_65_135","chapterId":"ch_work_han_thu_65","textTraditional":"〔八〕　師古曰：「兵即謂矢及矛戟之屬也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_65_136","chapterId":"ch_work_han_thu_65","textTraditional":"〔九〕　師古曰：「脫，免也，音吐活反。次下亦同。」","sentenceOrder":136},
  {"id":"s_work_han_thu_65_137","chapterId":"ch_work_han_thu_65","textTraditional":"〔一０〕如淳曰：「半讀曰片，或曰五升曰半。」師古曰：「半讀曰判。判，大片也。時冬寒有冰，持之以備渴也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_65_138","chapterId":"ch_work_han_thu_65","textTraditional":"陵敗處去塞百餘里，邊塞以聞。上欲陵死戰，召陵母及婦，使相者視之，無死喪色。後聞陵降，上怒甚，責問陳步樂，步樂自殺。群臣皆罪陵，上以問太史令司馬遷，遷盛言：「陵事親孝，與士信，常奮不顧身以殉國家之急。〔一〕其素所畜積也，〔二〕有國士之風。今舉事一不幸，全軀保妻子之臣隨而媒糱其短，〔三〕誠可痛也！且陵提步卒不滿五千，深輮戎馬之地，〔四〕抑數萬之師，虜救死扶傷不暇，悉舉引弓之民共攻圍之。轉鬥千里，矢盡道窮，士張空拳〔五〕，冒白刃，北首爭死敵，〔六〕得人之死力，雖古名將不過也。身雖陷敗，然其所摧敗亦足暴於天下。〔七〕彼之不死，宜欲得當以報漢也。」〔八〕初，上遣貳師大軍出，財令陵為助兵，〔九〕及陵與單于相值，而貳師功少。上以遷誣罔，欲沮貳師，為陵游說，〔一０〕下遷腐刑。","sentenceOrder":138},
  {"id":"s_work_han_thu_65_139","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「殉，營也，一曰從也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_65_140","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「畜讀曰蓄。」","sentenceOrder":140},
  {"id":"s_work_han_thu_65_141","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　服虔曰：「媒音欺，謂詆欺也。」孟康曰：「媒，酒教；糵，麴也。謂釀成其罪也。」師古曰：「孟說是也。齊人名麴餅曰媒。」","sentenceOrder":141},
  {"id":"s_work_han_thu_65_142","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　師古曰：「輮，踐也，音人九反。」","sentenceOrder":142},
  {"id":"s_work_han_thu_65_143","chapterId":"ch_work_han_thu_65","textTraditional":"〔五〕　文穎曰：「拳，弓弩拳也。」師古曰：「拳字與絭同，音去權反，又音眷。」","sentenceOrder":143},
  {"id":"s_work_han_thu_65_144","chapterId":"ch_work_han_thu_65","textTraditional":"〔六〕　師古曰：「冒，犯也。北首，北嚮也。冒音莫北反。首音式救反。」","sentenceOrder":144},
  {"id":"s_work_han_thu_65_145","chapterId":"ch_work_han_thu_65","textTraditional":"〔七〕　師古曰：「所摧敗，敗匈奴之兵也。暴猶章也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_65_146","chapterId":"ch_work_han_thu_65","textTraditional":"〔八〕　師古曰：「言欲立功以當其罪也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_65_147","chapterId":"ch_work_han_thu_65","textTraditional":"〔九〕　師古曰：「財與纔同，謂淺也，僅也。史傳通用字。他皆類此。」","sentenceOrder":147},
  {"id":"s_work_han_thu_65_148","chapterId":"ch_work_han_thu_65","textTraditional":"〔一０〕師古曰：「沮謂毀壞之，音才呂反。」","sentenceOrder":148},
  {"id":"s_work_han_thu_65_149","chapterId":"ch_work_han_thu_65","textTraditional":"久之，上悔陵無救，曰：「陵當發出塞，乃詔彊弩都尉令迎軍。坐預詔之，得令老將生姦詐。」〔一〕乃遣使勞賜陵餘軍得脫者。","sentenceOrder":149},
  {"id":"s_work_han_thu_65_150","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　孟康曰：「坐預詔彊弩都尉路博德迎陵，博德老將，出塞不至，令陵見沒也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_65_151","chapterId":"ch_work_han_thu_65","textTraditional":"陵在匈奴歲餘，上遣因杅將軍公孫敖〔一〕將兵深入匈奴迎陵。敖軍無功還，曰：「捕得生口，李陵教單于為兵以備漢軍，故臣無所得。」上聞，於是族陵家，母弟妻子皆伏誅。隴西士大夫以李氏為愧。〔二〕其後，漢遣使使匈奴，陵謂使者曰：「吾為漢將步卒五千人橫行匈奴，以亡救而敗，何負於漢而誅吾家？」使者曰：「漢聞李少卿教匈奴為兵。」陵曰：「乃李緒，非我也。」李緒本漢塞外都尉，居奚侯城，匈奴攻之，緒降，而單于客遇緒，常坐陵上。陵痛其家以李緒而誅，使人刺殺緒。大閼氏欲殺陵，〔三〕單于匿之北方，大閼氏死乃還。","sentenceOrder":151},
  {"id":"s_work_han_thu_65_152","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　孟康曰：「因杅，胡地名也。」師古曰：「杅音于。」","sentenceOrder":152},
  {"id":"s_work_han_thu_65_153","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「恥其不能死節，累及家室。」","sentenceOrder":153},
  {"id":"s_work_han_thu_65_154","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「大閼氏，單于之母。」","sentenceOrder":154},
  {"id":"s_work_han_thu_65_155","chapterId":"ch_work_han_thu_65","textTraditional":"單于壯陵，以女妻之，立為右校王，衛律為丁靈王，〔一〕皆貴用事。衛律者，父本長水胡人。律生長漢，善協律都尉李延年，延年薦言律使匈奴。使還，會延年家收，律懼并誅，亡還降匈奴。匈奴愛之，常在單于左右。陵居外，有大事，乃入議。","sentenceOrder":155},
  {"id":"s_work_han_thu_65_156","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「丁靈，胡之別種也。立為王而主其人也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_65_157","chapterId":"ch_work_han_thu_65","textTraditional":"昭帝立，大將軍霍光、左將軍上官桀輔政，素與陵善，遣陵故人隴西任立政等三人〔一〕俱至匈奴招陵。立政等至，單于置酒賜漢使者，李陵、衛律皆侍坐。立政等見陵，未得私語，即目視陵，〔二〕而數數自循其刀環，〔三〕握其足，陰諭之，言可還歸漢也。後陵、律持牛酒勞漢使，博飲，〔四〕兩人皆胡服椎結。〔五〕立政大言曰：「漢已大赦，中國安樂，主上富於春秋，〔六〕霍子孟、上官少叔用事。」〔七〕以此言微動之。陵墨不應，孰視而自循其髮，答曰：「吾已胡服矣！」有頃，律起更衣，立政曰：「咄，少卿良苦！〔八〕霍子孟、上官少叔謝女。」〔九〕陵曰：「霍與上官無恙乎？〔一０〕」立政曰：「請少卿來歸故鄉，毋憂富貴。」陵字立政曰：「少公，〔一一〕歸易耳，恐再辱，柰何！」語未卒，衛律還，頗聞餘語，曰：「李少卿賢者，不獨居一國。范蠡遍遊天下，由余去戎入秦，今何語之親也！」因罷去。立政隨謂陵曰：「亦有意乎？」〔一二〕陵曰：「丈夫不能再辱。」","sentenceOrder":157},
  {"id":"s_work_han_thu_65_158","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「故人，謂舊與相知者。」","sentenceOrder":158},
  {"id":"s_work_han_thu_65_159","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「以目相視而感動之，今俗所謂眼語者也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_65_160","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「循謂摩順也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_65_161","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　蘇林曰：「博且飲也。」師古曰：「勞音來到反。」","sentenceOrder":161},
  {"id":"s_work_han_thu_65_162","chapterId":"ch_work_han_thu_65","textTraditional":"〔五〕　師古曰：「結讀曰髻，一撮之髻，其形如椎。」","sentenceOrder":162},
  {"id":"s_work_han_thu_65_163","chapterId":"ch_work_han_thu_65","textTraditional":"〔六〕　師古曰：「言天子年少。」","sentenceOrder":163},
  {"id":"s_work_han_thu_65_164","chapterId":"ch_work_han_thu_65","textTraditional":"〔七〕　師古曰：「子孟，光之字；少叔，桀之字也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_65_165","chapterId":"ch_work_han_thu_65","textTraditional":"〔八〕　師古曰：「言甚勞苦。」","sentenceOrder":165},
  {"id":"s_work_han_thu_65_166","chapterId":"ch_work_han_thu_65","textTraditional":"〔九〕　師古曰：「謝，以辭相問也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_65_167","chapterId":"ch_work_han_thu_65","textTraditional":"〔一０〕師古曰：「恙，憂病也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_65_168","chapterId":"ch_work_han_thu_65","textTraditional":"〔一一〕師古曰：「呼其字。」","sentenceOrder":168},
  {"id":"s_work_han_thu_65_169","chapterId":"ch_work_han_thu_65","textTraditional":"〔一二〕師古曰：「隨其後而語之。」","sentenceOrder":169},
  {"id":"s_work_han_thu_65_170","chapterId":"ch_work_han_thu_65","textTraditional":"陵在匈奴二十餘年，元平元年病死。","sentenceOrder":170},
  {"id":"s_work_han_thu_65_171","chapterId":"ch_work_han_thu_65","textTraditional":"蘇建，杜陵人也。以校尉從大將軍青擊匈奴，封平陵侯。以將軍築朔方。後以衛尉為遊擊將軍，從大將軍出朔方。後一歲，以右將軍再從大將軍出定襄，亡翕侯，〔一〕失軍當斬，贖為庶人。其後為代郡太守，卒官。有三子：嘉為奉車都尉，賢為騎都尉，中子武最知名。","sentenceOrder":171},
  {"id":"s_work_han_thu_65_172","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　服虔曰：「趙信也。」","sentenceOrder":172},
  {"id":"s_work_han_thu_65_173","chapterId":"ch_work_han_thu_65","textTraditional":"武字子卿，少以父任，兄弟並為郎，稍遷至栘中廄監。〔一〕時漢連伐胡，數通使相窺觀，匈奴留漢使郭吉、路充國等，前後十餘輩。匈奴使來，漢亦留之以相當。天漢元年，且鞮侯單于初立，〔二〕恐漢襲之，乃曰：「漢天子我丈人行也。」〔三〕盡歸漢使路充國等。武帝嘉其義，乃遣武以中郎將使持節送匈奴使留在漢者，因厚（輅）〔賂〕單于，答其善意。武與副中郎將張勝及假吏常惠等〔四〕募士斥候百餘人俱。〔五〕既至匈奴，置幣遺單于。單于益驕，非漢所望也。","sentenceOrder":173},
  {"id":"s_work_han_thu_65_174","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「栘中，廄名，為之監也。栘音移。」","sentenceOrder":174},
  {"id":"s_work_han_thu_65_175","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「且音子閭反。鞮音丁奚反。」","sentenceOrder":175},
  {"id":"s_work_han_thu_65_176","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「丈人，尊老之稱。行音胡浪反。」","sentenceOrder":176},
  {"id":"s_work_han_thu_65_177","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　師古曰：「假吏猶言兼吏也。時權為使之吏，若今之差人充使典矣。」","sentenceOrder":177},
  {"id":"s_work_han_thu_65_178","chapterId":"ch_work_han_thu_65","textTraditional":"〔五〕　師古曰：「募人以充士卒，及在道為斥候者。」","sentenceOrder":178},
  {"id":"s_work_han_thu_65_179","chapterId":"ch_work_han_thu_65","textTraditional":"方欲發使送武等，會緱王與長水虞常等謀反匈奴中。〔一〕緱王者，昆邪王姊子也，〔二〕與昆邪王俱降漢，後隨浞野侯沒胡中〔三〕。及衛律所將降者，陰相與謀劫單于母閼氏歸漢。會武等至匈奴，虞常在漢時素與副張勝相知，私候勝曰：「聞漢天子甚怨衛律，常能為漢伏弩射殺之。吾母與弟在漢，幸蒙其賞賜。」張勝許之，以貨物與常。後月餘，單于出獵，獨閼氏子弟在。虞常等七十餘人欲發，其一人夜亡，告之。單于子弟發兵與戰。緱王等皆死，虞常生得。〔四〕","sentenceOrder":179},
  {"id":"s_work_han_thu_65_180","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「緱音工候反。」","sentenceOrder":180},
  {"id":"s_work_han_thu_65_181","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「昆音胡門反。」","sentenceOrder":181},
  {"id":"s_work_han_thu_65_182","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「從趙破奴擊匈奴，兵敗而降。」","sentenceOrder":182},
  {"id":"s_work_han_thu_65_183","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　師古曰：「被執獲也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_65_184","chapterId":"ch_work_han_thu_65","textTraditional":"單于使衛律治其事。張勝聞之，恐前語發，以狀語武。武曰：「事如此，此必及我。見犯乃死，重負國。」欲自殺，〔一〕勝、惠共止之。虞常果引張勝。單于怒，召諸貴人議，欲殺漢使者。左伊秩訾曰：〔二〕「即謀單于，何以復加？〔三〕宜皆降之。」單于使衛律召武受辭，〔四〕武謂惠等：「屈節辱命，雖生，何面目以歸漢！」引佩刀自刺。衛律驚，自抱持武，馳召毉。鑿地為坎，置熅火，〔五〕覆武其上，〔六〕蹈其背以出血。武氣絕，半日復息。〔七〕惠等哭，輿歸營。單于壯其節，朝夕遣人候問武，而收繫張勝。","sentenceOrder":184},
  {"id":"s_work_han_thu_65_185","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「言被匈奴侵犯，然後乃死，是為更負漢國，故欲先自殺也。重音直用反。」","sentenceOrder":185},
  {"id":"s_work_han_thu_65_186","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　臣瓚曰：「胡官之號也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_65_187","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「言謀〔殺〕衛律而殺之，其罰太重也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_65_188","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　師古曰：「致單于之命，而取其對也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_65_189","chapterId":"ch_work_han_thu_65","textTraditional":"〔五〕　師古曰：「熅謂聚火無焱者也，音於云反。焱音弋贍反。」","sentenceOrder":189},
  {"id":"s_work_han_thu_65_190","chapterId":"ch_work_han_thu_65","textTraditional":"〔六〕　師古曰：「覆身於坎上也。覆音芳目反。」","sentenceOrder":190},
  {"id":"s_work_han_thu_65_191","chapterId":"ch_work_han_thu_65","textTraditional":"〔七〕　師古曰：「息謂出氣也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_65_192","chapterId":"ch_work_han_thu_65","textTraditional":"武益愈，單于使使曉武。〔一〕會論虞常，欲因此時降武。劍斬虞常已，律曰：「漢使張勝謀殺單于近臣，〔二〕當死，單于募降者赦罪。」舉劍欲擊之，勝請降。律謂武曰：「副有罪，當相坐。」武曰：「本無謀，又非親屬，何謂相坐？」復舉劍擬之，武不動。律曰：「蘇君，律前負漢歸匈奴，幸蒙大恩，賜號稱王，擁眾數萬，馬畜彌山，富貴如此。〔三〕蘇君今日降，明日復然。空以身膏草野，誰復知之！」武不應。律曰：「君因我降，與君為兄弟，今不聽吾計，後雖欲復見我，尚可得乎？」武罵律曰：「女為人臣子，不顧恩義，畔主背親，為降虜於蠻夷，何以女為見？〔四〕且單于信女，使決人死生，不平心持正，反欲鬥兩主，觀禍敗。南越殺漢使者，屠為九郡；宛王殺漢使者，頭縣北闕；朝鮮殺漢使者，即時誅滅。獨匈奴未耳。若知我不降明，〔五〕欲令兩國相攻，匈奴之禍從我始矣。」","sentenceOrder":192},
  {"id":"s_work_han_thu_65_193","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「諭說令降也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_65_194","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「衛律自謂也。」","sentenceOrder":194},
  {"id":"s_work_han_thu_65_195","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「彌，滿也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_65_196","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　師古曰：「言何用見女為也。」","sentenceOrder":196},
  {"id":"s_work_han_thu_65_197","chapterId":"ch_work_han_thu_65","textTraditional":"〔五〕　師古曰：「若，汝也。言汝知我不肯降明矣。」","sentenceOrder":197},
  {"id":"s_work_han_thu_65_198","chapterId":"ch_work_han_thu_65","textTraditional":"律知武終不可脅，白單于。單于愈益欲降之，乃幽武置大窖中，〔一〕絕不飲食。〔二〕天雨雪，武臥齧雪與旃毛并咽之，〔三〕數日不死，匈奴以為神，乃徙武北海上無人處，使牧羝，羝乳乃得歸。〔四〕別其官屬常惠等，各置他所。","sentenceOrder":198},
  {"id":"s_work_han_thu_65_199","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「舊米粟之窖而空者也，音工孝反。」","sentenceOrder":199},
  {"id":"s_work_han_thu_65_200","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「飲音於禁反。食讀曰飤。」","sentenceOrder":200},
  {"id":"s_work_han_thu_65_201","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「咽，吞也，音宴。」","sentenceOrder":201},
  {"id":"s_work_han_thu_65_202","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　師古曰：「羝，牡羊也。羝不當產乳，故設此言，示絕其事。若燕太子丹烏白頭、馬生角之比也。羝音丁奚反。乳音人喻反。」","sentenceOrder":202},
  {"id":"s_work_han_thu_65_203","chapterId":"ch_work_han_thu_65","textTraditional":"武既至海上，廩食不至，〔一〕掘野鼠去屮實而食之。〔二〕杖漢節牧羊，臥起操持，節旄盡落。積五六年，單于弟於靬王弋射海上。〔三〕武能網紡繳，檠弓弩，〔四〕於靬王愛之，給其衣食。三歲餘，王病，賜武馬畜服匿穹廬。〔五〕王死後，人眾徙去。其冬，丁令盜武牛羊，〔六〕武復窮厄。","sentenceOrder":203},
  {"id":"s_work_han_thu_65_204","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「無人給飤之。」","sentenceOrder":204},
  {"id":"s_work_han_thu_65_205","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　蘇林曰：「取鼠所去草實而食之。」張晏曰：「取鼠及草實并而食之。」師古曰：「蘇說是也。屮，古草字。去謂藏之也，音丘呂反。」","sentenceOrder":205},
  {"id":"s_work_han_thu_65_206","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「靬音居言反。」","sentenceOrder":206},
  {"id":"s_work_han_thu_65_207","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　師古曰：「繳，生絲縷也，可以弋射。檠謂輔正弓弩也。繳音斫。檠音警，又音巨京反。」","sentenceOrder":207},
  {"id":"s_work_han_thu_65_208","chapterId":"ch_work_han_thu_65","textTraditional":"〔五〕　劉德曰：「服匿如小旃帳。」孟康曰：「服匿如甖，小口大腹方底，用受酒酪。穹廬，旃帳也。」晉灼曰：「河東北界人呼小石甖受二斗所曰服匿。」師古曰：「孟、晉二說是也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_65_209","chapterId":"ch_work_han_thu_65","textTraditional":"〔六〕　師古曰：「令音零。丁令，即上所謂丁靈耳。」","sentenceOrder":209},
  {"id":"s_work_han_thu_65_210","chapterId":"ch_work_han_thu_65","textTraditional":"初，武與李陵俱為侍中，武使匈奴明年，陵降，不敢求武。久之，單于使陵至海上，為武置酒設樂，因謂武曰：「單于聞陵與子卿素厚，故使陵來說足下，虛心欲相待。終不得歸漢，空自苦亡人之地，信義安所見乎？前長君為奉車，〔一〕從至雍棫陽宮，扶輦下除〔二〕，觸柱折轅，劾大不敬，伏劍自刎，〔三〕賜錢二百萬以葬。孺卿從祠河東后土，〔四〕宦騎與黃門駙馬爭船，〔五〕推墮駙馬河中溺死，宦騎亡，詔使孺卿逐捕不得，惶恐飲藥而死。來時，大夫人已不幸，〔六〕陵送葬至陽陵。子卿婦年少，聞已更嫁矣。獨有女弟二人，兩女一男，今復十餘年，存亡不可知。人生如朝露，〔七〕何久自苦如此！陵始降時，忽忽如狂，自痛負漢，加以老母繫保宮，〔八〕子卿不欲降，何以過陵？且陛下春秋高，法令亡常，大臣亡罪夷滅者數十家，安危不可知，子卿尚復誰為乎？願聽陵計，勿復有云。」武曰：「武父子亡功德，皆為陛下所成就，位列將，爵通侯，兄弟親近，常願肝腦塗地。今得殺身自效，雖蒙斧鉞湯鑊，誠甘樂之。臣事君，猶子事父也，子為父死亡所恨。願勿復再言。」陵與武飲數日，復曰：「子卿壹聽陵言。」武曰：「自分已死久矣！〔九〕王必欲降武，請畢今日之驩，效死於前！」〔一０〕陵見其至誠，喟然歎曰：「嗟乎，義士！陵與衛律之罪上通於天。」因泣下霑衿，與武決去〔一一〕。","sentenceOrder":210},
  {"id":"s_work_han_thu_65_211","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　服虔曰：「武兄嘉。」","sentenceOrder":211},
  {"id":"s_work_han_thu_65_212","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　張晏曰：「主扶輦下除道也。」師古曰：「除謂門屏之間。」","sentenceOrder":212},
  {"id":"s_work_han_thu_65_213","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「刎，斷也，斷其頸也，音武粉反。」","sentenceOrder":213},
  {"id":"s_work_han_thu_65_214","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　張晏曰：「武弟賢。」","sentenceOrder":214},
  {"id":"s_work_han_thu_65_215","chapterId":"ch_work_han_thu_65","textTraditional":"〔五〕　師古曰：「宦騎，宦者而為騎也。黃門駙馬，天子駙馬之在黃門者。駙，副也。金日磾傳曰『養馬於黃門』也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_65_216","chapterId":"ch_work_han_thu_65","textTraditional":"〔六〕　師古曰：「不幸亦謂死。」","sentenceOrder":216},
  {"id":"s_work_han_thu_65_217","chapterId":"ch_work_han_thu_65","textTraditional":"〔七〕　師古曰：「朝露見日則晞，人命短促亦如之。」","sentenceOrder":217},
  {"id":"s_work_han_thu_65_218","chapterId":"ch_work_han_thu_65","textTraditional":"〔八〕　師古曰：「百官公卿表云少府屬官有居室，武帝太初元年更名保宮。」","sentenceOrder":218},
  {"id":"s_work_han_thu_65_219","chapterId":"ch_work_han_thu_65","textTraditional":"〔九〕　師古曰：「分音扶問反。」","sentenceOrder":219},
  {"id":"s_work_han_thu_65_220","chapterId":"ch_work_han_thu_65","textTraditional":"〔一０〕師古曰：「效，致也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_65_221","chapterId":"ch_work_han_thu_65","textTraditional":"〔一一〕師古曰：「決，別也。」","sentenceOrder":221},
  {"id":"s_work_han_thu_65_222","chapterId":"ch_work_han_thu_65","textTraditional":"陵惡自賜武，〔一〕使其妻賜武牛羊數十頭。後陵復至北海上，語武：「區脫捕得雲中生口，〔二〕言太守以下吏民皆白服，曰上崩。」武聞之，南鄉號哭，歐血，旦夕臨。〔三〕","sentenceOrder":222},
  {"id":"s_work_han_thu_65_223","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「謂若示己於匈奴中富饒以夸武。」","sentenceOrder":223},
  {"id":"s_work_han_thu_65_224","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　服虔曰：「區脫，土室，胡兒所作以候漢者也。」李奇曰：「匈奴邊境羅落守衛官也。」晉灼曰：「匈奴傳東胡與匈奴間有棄地千餘里，各居其邊為區脫。又云漢得區脫王，發人民屯區脫以備漢，此為因邊境以為官。李說是也。」師古曰：「匈奴邊境為候望之室，服說是也。本非官號，區脫王者，以其所部居區脫之處，因呼之耳。李、晉二說皆失之。區讀（曰）〔與〕甌同，音一侯反。脫音土活反。」","sentenceOrder":224},
  {"id":"s_work_han_thu_65_225","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「鄉讀曰嚮。臨，哭也，音力禁反。」","sentenceOrder":225},
  {"id":"s_work_han_thu_65_226","chapterId":"ch_work_han_thu_65","textTraditional":"數月，昭帝即位。數年，匈奴與漢和親。漢求武等，匈奴詭言武死。後漢使復至匈奴，常惠請其守者與俱，得夜見漢使，具自陳道。教使者謂單于，言天子射上林中，得雁，足有係帛書，言武等在某澤中。使者大喜，如惠語以讓單于。〔一〕單于視左右而驚，謝漢使曰：「武等實在。」於是李陵置酒賀武曰：「今足下還歸，揚名於匈奴，功顯於漢室，雖古竹帛所載，丹青所畫，何以過子卿！陵雖駑怯，令漢且貰陵罪，〔二〕全其老母，使得奮大辱之積志，庶幾乎曹柯之盟，〔三〕此陵宿昔之所不忘也。收族陵家，為世大戮，陵尚復何顧乎？已矣！令子卿知吾心耳。異域之人，壹別長絕！」陵起舞，歌曰：「徑萬里兮度沙幕，為君將兮奮匈奴。路窮絕兮矢刃摧，士眾滅兮名已隤。老母已死，雖欲報恩將安歸！」〔四〕陵泣下數行，因與武決。單于召會武官屬，〔五〕前以降及物故，凡隨武還者九人。〔六〕","sentenceOrder":226},
  {"id":"s_work_han_thu_65_227","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「讓，責也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_65_228","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「貰，寬也。」","sentenceOrder":228},
  {"id":"s_work_han_thu_65_229","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　李奇曰：「欲劫單于，如曹劌劫齊桓公柯盟之時。」","sentenceOrder":229},
  {"id":"s_work_han_thu_65_230","chapterId":"ch_work_han_thu_65","textTraditional":"〔四〕　師古曰：「隤，墜也，音大回反。」","sentenceOrder":230},
  {"id":"s_work_han_thu_65_231","chapterId":"ch_work_han_thu_65","textTraditional":"〔五〕　師古曰：「會謂集聚也。」","sentenceOrder":231},
  {"id":"s_work_han_thu_65_232","chapterId":"ch_work_han_thu_65","textTraditional":"〔六〕　師古曰：「物故謂死也，言其同於鬼物而故也。一說，不欲斥言，但云其所服用之物皆已故耳。而說者妄欲改物為勿，非也。」","sentenceOrder":232},
  {"id":"s_work_han_thu_65_233","chapterId":"ch_work_han_thu_65","textTraditional":"武以（元始）〔始元〕六年春至京師。詔武奉一太牢謁武帝園廟，拜為典屬國，秩中二千石，賜錢二百萬，公田二頃，宅一區。常惠、徐聖、趙終根皆拜為中郎，賜帛各二百匹。其餘六人老歸家，賜錢人十萬，復終身。〔一〕常惠後至右將軍，封列侯，自有傳。武留匈奴凡十九歲，始以彊壯出，及還，須髮盡白。","sentenceOrder":233},
  {"id":"s_work_han_thu_65_234","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「復音芳目反。」","sentenceOrder":234},
  {"id":"s_work_han_thu_65_235","chapterId":"ch_work_han_thu_65","textTraditional":"武來歸明年，上官桀子安與桑弘羊及燕王、蓋王謀反。武子男元與安有謀，坐死。","sentenceOrder":235},
  {"id":"s_work_han_thu_65_236","chapterId":"ch_work_han_thu_65","textTraditional":"初桀、安與大將軍霍光爭權，數疏光過失予燕王，〔一〕令上書告之。又言蘇武使匈奴二十年不降，還乃為典屬國，〔二〕大將軍長史無功勞，為搜粟都尉，光顓權自恣。〔三〕及燕王等反誅，窮治黨與，武素與桀、弘羊有舊，數為燕王所訟，子又在謀中，廷尉奏請逮捕武。霍光寢其奏，免武官。","sentenceOrder":236},
  {"id":"s_work_han_thu_65_237","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「疏謂條錄之。」","sentenceOrder":237},
  {"id":"s_work_han_thu_65_238","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「實十九年，而言二十者，欲久其事以見冤屈，故多言也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_65_239","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「顓與專同。」","sentenceOrder":239},
  {"id":"s_work_han_thu_65_240","chapterId":"ch_work_han_thu_65","textTraditional":"數年，昭帝崩，武以故二千石與計謀立宣帝，〔一〕賜爵關內侯，食邑三百戶。久之，衛將軍張安世薦武明習故事，奉使不辱命，先帝以為遺言。宣帝即時召武待詔宦者署，〔二〕數進見，復為右曹典屬國。以武著節老臣，令朝朔望，號稱祭酒，〔三〕甚優寵之。","sentenceOrder":240},
  {"id":"s_work_han_thu_65_241","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「與讀曰預。」","sentenceOrder":241},
  {"id":"s_work_han_thu_65_242","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「百官公卿表少府屬官有宦者令丞。以其署親近，故令於此待詔也。」","sentenceOrder":242},
  {"id":"s_work_han_thu_65_243","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「加祭酒之號，所以示優尊也。祭酒，已解在伍被傳。」","sentenceOrder":243},
  {"id":"s_work_han_thu_65_244","chapterId":"ch_work_han_thu_65","textTraditional":"武所得賞賜，盡以施予昆弟故人，家不餘財。皇后父平恩侯、帝舅平昌侯、樂昌侯、〔一〕車騎將軍韓增、丞相魏相、御史大夫丙吉皆敬重武。武年老，子前坐事死，上閔之，問左右：「武在匈奴久，豈有子乎？」武因平恩侯自白：「前發匈奴時，胡婦適產一子通國，有聲問來，願因使者致金帛贖之。」上許焉。後通國隨使者至，上以為郎。又以武弟子為右曹。武年八十餘，神爵二年病卒。","sentenceOrder":244},
  {"id":"s_work_han_thu_65_245","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「平恩侯許伯、平昌侯王無故、樂昌侯王武也。」","sentenceOrder":245},
  {"id":"s_work_han_thu_65_246","chapterId":"ch_work_han_thu_65","textTraditional":"甘露三年，單于始入朝。上思股肱之美，乃圖畫其人於麒麟閣，〔一〕法其形貌，署其官爵姓名。〔二〕唯霍光不名，曰大司馬大將軍博陸侯姓霍氏，次曰衛將軍富平侯張安世，次曰車騎將軍龍頟侯韓增，次曰後將軍營平侯趙充國，次曰丞相高平侯魏相，次曰丞相博陽侯丙吉，次曰御史大夫建平侯杜延年，次曰宗正陽城侯劉德，次曰少府梁丘賀，次曰太子太傅蕭望之，次曰典屬國蘇武。皆有功德，知名當世，是以表而揚之，明著中興輔佐，列於方叔、召虎、仲山甫焉。〔三〕凡十一人，皆有傳。自丞相黃霸、廷尉于定國、大司農朱邑、京兆尹張敞、右扶風尹翁歸及儒者夏侯勝等，皆以善終，著名宣帝之世，然不得列於名臣之圖，以此知其選矣。","sentenceOrder":246},
  {"id":"s_work_han_thu_65_247","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　張晏曰：「武帝獲麒麟時作此閣，圖畫其象於閣，遂以為名。」師古曰：「漢宮閣疏名云蕭何造。」","sentenceOrder":247},
  {"id":"s_work_han_thu_65_248","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「署，表也，題也。」","sentenceOrder":248},
  {"id":"s_work_han_thu_65_249","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「三人皆周宣王之臣，有文武之功，佐宣王中興者也。言宣帝亦重興漢室，而霍光等並為名臣，皆比於方叔之屬。召讀曰邵。」","sentenceOrder":249},
  {"id":"s_work_han_thu_65_250","chapterId":"ch_work_han_thu_65","textTraditional":"贊曰：李將軍恂恂如鄙人，口不能出辭，〔一〕及死之日，天下知與不知皆為流涕，彼其中心誠信於士大夫也。諺曰：「桃李不言，下自成蹊。」〔二〕此言雖小，可以喻大。然三代之將，道家所忌，自廣至陵，遂亡其宗，哀哉！孔子稱「志士仁人，有殺身以成仁，無求生以害仁」，「使於四方，不辱君命」，〔三〕蘇武有之矣。","sentenceOrder":250},
  {"id":"s_work_han_thu_65_251","chapterId":"ch_work_han_thu_65","textTraditional":"〔一〕　師古曰：「恂恂，誠謹貌也，音荀。」","sentenceOrder":251},
  {"id":"s_work_han_thu_65_252","chapterId":"ch_work_han_thu_65","textTraditional":"〔二〕　師古曰：「蹊謂徑道也。言桃李以其華實之故，非有所召呼，而人爭歸趣，來往不絕，其下自然成徑，以喻人懷誠信之心，故能潛有所感也。蹊音奚。」","sentenceOrder":252},
  {"id":"s_work_han_thu_65_253","chapterId":"ch_work_han_thu_65","textTraditional":"〔三〕　師古曰：「皆論語載孔子之言。」","sentenceOrder":253},
  {"id":"s_work_han_thu_65_254","chapterId":"ch_work_han_thu_65","textTraditional":"校勘記","sentenceOrder":254},
  {"id":"s_work_han_thu_65_255","chapterId":"ch_work_han_thu_65","textTraditional":"二四四０頁　四行　匈奴（入）〔侵〕上郡，景祐、殿本都作「侵」。","sentenceOrder":255},
  {"id":"s_work_han_thu_65_256","chapterId":"ch_work_han_thu_65","textTraditional":"二四四一頁　一行　放（從）〔縱〕遊獵也。殿本作「縱」。王先謙說作「縱」是。","sentenceOrder":256},
  {"id":"s_work_han_thu_65_257","chapterId":"ch_work_han_thu_65","textTraditional":"二四四一頁一四行　不擊（刀）〔刁〕斗自衛，景祐、殿本都作「刁」，注同。王先謙說作「刁」是。","sentenceOrder":257},
  {"id":"s_work_han_thu_65_258","chapterId":"ch_work_han_thu_65","textTraditional":"二四四三頁　二行　絡而盛（之）臥，宋祁說越本無「之」字。按景祐本亦無「之」字。","sentenceOrder":258},
  {"id":"s_work_han_thu_65_259","chapterId":"ch_work_han_thu_65","textTraditional":"二四四五頁　六行　是時廣軍幾沒，〔九〕罷歸。注〔九〕原在「罷」字下。王先謙說此師古誤讀，「罷」字連「歸」為文。","sentenceOrder":259},
  {"id":"s_work_han_thu_65_260","chapterId":"ch_work_han_thu_65","textTraditional":"二四六０頁　一行　因厚（輅）〔賂〕單于，景祐、殿、局本都作「賂」。王先謙說「輅」訛字。","sentenceOrder":260},
  {"id":"s_work_han_thu_65_261","chapterId":"ch_work_han_thu_65","textTraditional":"二四六一頁一二行　言謀〔殺〕衛律而殺之，景祐本有「殺」字。","sentenceOrder":261},
  {"id":"s_work_han_thu_65_262","chapterId":"ch_work_han_thu_65","textTraditional":"二四六六頁　二行　區讀（日）〔與〕甌同，景祐、殿本都作「與」。王先謙說作「與」是。","sentenceOrder":262},
  {"id":"s_work_han_thu_65_263","chapterId":"ch_work_han_thu_65","textTraditional":"二四六七頁　四行　武以（元始）〔始元〕六年春至京師。景祐、殿本都作「始元」，此誤倒。","sentenceOrder":263},
  {"id":"s_work_han_thu_66_1","chapterId":"ch_work_han_thu_66","textTraditional":"衛青字仲卿。其父鄭季，河東平陽人也，以縣吏給事侯家。平陽侯曹壽尚武帝姊陽信長公主。〔一〕季與主家僮衛媼通，〔二〕生青。青有同母兄衛長及姊子夫，子夫自平陽公主家得幸武帝，故青冒姓為衛氏。〔三〕衛媼長女君孺，次女少兒，次女則子夫。子夫男弟步廣，皆冒衛氏。〔四〕","sentenceOrder":1},
  {"id":"s_work_han_thu_66_2","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「壽姓曹，為平陽侯，當是曹參之後，然參傳及功臣侯表並無之，未詳其意也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_66_3","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　師古曰：「僮者，婢女之總稱也。媼者，後年老之號，非當時所呼也。衛者，舉其夫家姓也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_66_4","chapterId":"ch_work_han_thu_66","textTraditional":"〔三〕　師古曰：「冒謂假稱，若人首之有覆冒也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_66_5","chapterId":"ch_work_han_thu_66","textTraditional":"〔四〕　師古曰：「言步廣及青二人皆不姓衛，而冒稱。」","sentenceOrder":5},
  {"id":"s_work_han_thu_66_6","chapterId":"ch_work_han_thu_66","textTraditional":"青為侯家人，少時歸其父，父使牧羊。民母之子皆奴畜之，不以為兄弟數。〔一〕青嘗從人至甘泉居室，〔二〕有一鉗徒相青曰：「貴人也，官至封侯。」青笑曰：「人奴之生，得無笞罵即足矣，安得封侯事乎！」","sentenceOrder":6},
  {"id":"s_work_han_thu_66_7","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　服虔曰：「民母，嫡母也。」師古曰：「言鄭季正妻本在編戶之間，以別於公主家也。今流俗書本云『牧羊人間，先母之子不以為兄弟數』，妄增也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_66_8","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　張晏曰：「居室，甘泉中徒所居也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_66_9","chapterId":"ch_work_han_thu_66","textTraditional":"青壯，為侯家騎，從平陽主。建元二年春，青姊子夫得入宮幸上。皇后，大長公主女也，〔一〕無子，妒。大長公主聞衛子夫幸，有身，妒之，乃使人捕青。青時給事建章，〔二〕未知名。大長公主執囚青，欲殺之。其友騎郎公孫敖與壯士往篡之，〔三〕故得不死。上聞，乃召青為建章監，侍中。及母昆弟貴，賞賜數日間累千金。君孺為太僕公孫賀妻。少兒故與陳掌通，〔四〕上召貴掌。公孫敖由此益顯。子夫為夫人。青為太中大夫。","sentenceOrder":9},
  {"id":"s_work_han_thu_66_10","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　文穎曰：「陳皇后，武帝姑女也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_66_11","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　師古曰：「建章宮中。」","sentenceOrder":11},
  {"id":"s_work_han_thu_66_12","chapterId":"ch_work_han_thu_66","textTraditional":"〔三〕　師古曰：「逆取曰篡。」","sentenceOrder":12},
  {"id":"s_work_han_thu_66_13","chapterId":"ch_work_han_thu_66","textTraditional":"〔四〕　師古曰：「掌即陳平曾孫也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_66_14","chapterId":"ch_work_han_thu_66","textTraditional":"元光六年，拜為車騎將軍，擊匈奴，出上谷；公孫賀為輕車將軍，出雲中；太中大夫公孫敖為騎將軍，出代郡；衛尉李廣為驍騎將軍，出雁門：軍各萬騎。青至籠城，〔一〕斬首虜數百。騎將軍敖亡七千騎，衛尉廣為虜所得，得脫歸，皆當斬，贖為庶人。賀亦無功。唯青賜爵關內侯。是後匈奴仍侵犯邊。〔二〕語在匈奴傳。","sentenceOrder":14},
  {"id":"s_work_han_thu_66_15","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「籠讀與龍同。」","sentenceOrder":15},
  {"id":"s_work_han_thu_66_16","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　師古曰：「仍，頻也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_66_17","chapterId":"ch_work_han_thu_66","textTraditional":"元朔元年春，衛夫人有男，立為皇后。其秋，青復將三萬騎出雁門，李息出代郡。青斬首虜數千。明年，青復出雲中，西至高闕〔一〕，遂至於隴西，捕首虜數千，畜百餘萬，走白羊、樓煩王。遂取河南地為朔方郡。〔二〕以三千八百戶封青為長平侯。青校尉蘇建為平陵侯，張次公為岸頭侯。〔三〕使建築朔方城。〔四〕上曰：「匈奴逆天理，亂人倫，暴長虐老，〔五〕以盜竊為務，行詐諸蠻夷，造謀籍兵，數為邊害。〔六〕故興師遣將，以征厥罪。詩不云乎？『薄伐獫允，至于太原』；〔七〕『出車彭彭，城彼朔方』。〔八〕今車騎將軍青度西河至高闕，獲首二千三百級，車輜畜產畢收為鹵，已封為列侯，遂西定河南地，案榆谿舊塞，〔九〕絕梓領，梁北河，討蒲泥，破符離，〔一０〕斬輕銳之卒，捕伏聽者〔一一〕三千一十七級。〔一二〕執訊獲醜，〔一三〕敺馬牛羊百有餘萬，全甲兵而還，益封青三千八百戶。」其後匈奴比歲入代郡、雁門、定襄、上郡、朔方，〔一四〕所殺略甚眾。語在匈奴傳。","sentenceOrder":17},
  {"id":"s_work_han_thu_66_18","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「高闕，山名也，一曰塞名也，在朔方之北。」","sentenceOrder":18},
  {"id":"s_work_han_thu_66_19","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　師古曰：「當北地郡之北，黃河之南也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_66_20","chapterId":"ch_work_han_thu_66","textTraditional":"〔三〕　晉灼曰：「河東皮氏亭也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_66_21","chapterId":"ch_work_han_thu_66","textTraditional":"〔四〕　師古曰：「蘇建築之也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_66_22","chapterId":"ch_work_han_thu_66","textTraditional":"〔五〕　師古曰：「謂其俗貴少壯而賤長老也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_66_23","chapterId":"ch_work_han_thu_66","textTraditional":"〔六〕　張晏曰：「從蠻夷借兵鈔邊。」","sentenceOrder":23},
  {"id":"s_work_han_thu_66_24","chapterId":"ch_work_han_thu_66","textTraditional":"〔七〕　師古曰：「小雅六月之詩，美宣王北（代）〔伐〕也。薄伐者，言逐出之也。獫允，北狄名，即匈奴也。獫音險。」","sentenceOrder":24},
  {"id":"s_work_han_thu_66_25","chapterId":"ch_work_han_thu_66","textTraditional":"〔八〕　師古曰：「小雅出車之詩也。彭彭，眾車聲也。朔方，北方也。此詩人美出車而征，因築城以攘獫允也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_66_26","chapterId":"ch_work_han_thu_66","textTraditional":"〔九〕　如淳曰：「案，尋也。榆谿，舊塞名也。」師古曰：「上郡之北有諸次山，諸次水出焉，東經榆林塞為榆谿。言軍尋此塞而行也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_66_27","chapterId":"ch_work_han_thu_66","textTraditional":"〔一０〕如淳曰：「絕，度也。為北河作橋梁也。」晉灼曰：「蒲泥、符離，二王號也。」師古曰：「符離，塞名也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_66_28","chapterId":"ch_work_han_thu_66","textTraditional":"〔一一〕張晏曰：「伏於隱處，聽軍虛實。」","sentenceOrder":28},
  {"id":"s_work_han_thu_66_29","chapterId":"ch_work_han_thu_66","textTraditional":"〔一二〕師古曰：「本以斬敵一首拜爵一級，故謂一首為一級，因復名生獲一人為一級也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_66_30","chapterId":"ch_work_han_thu_66","textTraditional":"〔一三〕師古曰：「執訊者，謂生執其人而訊問之也。獲醜者，得其眾也。一曰醜，惡也。訊音信。」","sentenceOrder":30},
  {"id":"s_work_han_thu_66_31","chapterId":"ch_work_han_thu_66","textTraditional":"〔一四〕師古曰：「比，頻也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_66_32","chapterId":"ch_work_han_thu_66","textTraditional":"元朔五年春，令青將三萬騎出高闕，衛尉蘇建為遊擊將軍，左內史李沮為彊弩將軍，〔一〕太僕公孫賀為騎將軍，代相李蔡為輕車將軍，皆領屬車騎將軍，俱出朔方。大行李息、岸頭侯張次公為將軍，俱出右北平。匈奴右賢王當青等兵，以為漢兵不能至此，飲醉，漢兵夜至，圍右賢王。右賢王驚，夜逃，獨與其愛妾一人騎數百馳，潰圍北去。漢輕騎校尉郭成等追數百里，弗得，得右賢裨王十餘人，〔二〕眾男女萬五千餘人，畜數十百萬，〔三〕於是引兵而還。至塞，天子使使者持大將軍印，即軍中拜青為大將軍，〔四〕諸將皆以兵屬，立號而歸。上曰：「大將軍青躬率戎士，師大捷，獲匈奴王十有餘人，益封青八千七百戶。」而封青子伉為宜春侯，〔五〕子不疑為陰安侯，子登為發干侯。青固謝曰：〔六〕「臣幸得待罪行間，賴陛下神靈，軍大捷，皆諸校力戰之功也。陛下幸已益封臣青，臣青子在繈褓中，未有勤勞，上幸裂地封為三侯，非臣待罪行間所以勸士力戰之意也。伉等三人何敢受封！」上曰：「我非忘諸校功也，今固且圖之。」乃詔御史曰：「護軍都尉公孫敖三從大將軍擊匈奴，常護軍傅校獲王，〔七〕封敖為合騎侯。〔八〕都尉韓說從大軍出窴渾，〔九〕至匈奴右賢王庭，為戲下〔一０〕搏戰獲王，〔一一〕封說為龍頟侯。〔一二〕騎將軍賀從大將軍獲王，封賀為南窌侯。〔一三〕輕車將軍李蔡再從大將軍獲王，封蔡為樂安侯。校尉李朔、趙不虞、公孫戎奴各三從大將軍獲王，封朔為陟軹侯，不虞為隨成侯，戎奴為從平侯。將軍李沮、李息及校尉豆如意、中郎將綰皆有功，賜爵關內侯。沮、息、如意食邑各三百戶。」其秋，匈奴入代，殺都尉。","sentenceOrder":32},
  {"id":"s_work_han_thu_66_33","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　文穎曰：「沮音俎。」","sentenceOrder":33},
  {"id":"s_work_han_thu_66_34","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　師古曰：「裨王，小王也，若言裨將也。裨音頻移反。」","sentenceOrder":34},
  {"id":"s_work_han_thu_66_35","chapterId":"ch_work_han_thu_66","textTraditional":"〔三〕　師古曰：「數十萬以至百萬。」","sentenceOrder":35},
  {"id":"s_work_han_thu_66_36","chapterId":"ch_work_han_thu_66","textTraditional":"〔四〕　師古曰：「即，就也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_66_37","chapterId":"ch_work_han_thu_66","textTraditional":"〔五〕　師古曰：「伉音抗，又音工郎反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_66_38","chapterId":"ch_work_han_thu_66","textTraditional":"〔六〕　師古曰：「固謂再三也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_66_39","chapterId":"ch_work_han_thu_66","textTraditional":"〔七〕　師古曰：「傅讀曰附。言敖總護諸軍，每附部校，以致克捷而獲王也。校者，營壘之稱，故謂軍之一部為一校。或曰幡旗之名，非也。每軍一校，則別為幡耳，不名校也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_66_40","chapterId":"ch_work_han_thu_66","textTraditional":"〔八〕　晉灼曰：「猶冠軍從票之名也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_66_41","chapterId":"ch_work_han_thu_66","textTraditional":"〔九〕　服虔曰：「塞名也。」師古曰：「說讀曰悅。窴音田。渾音魂。」","sentenceOrder":41},
  {"id":"s_work_han_thu_66_42","chapterId":"ch_work_han_thu_66","textTraditional":"〔一０〕師古曰：「戲讀曰麾，又音許宜反。言在大將軍麾旗之下，不別統眾也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_66_43","chapterId":"ch_work_han_thu_66","textTraditional":"〔一一〕師古曰：「搏戰，擊戰。」","sentenceOrder":43},
  {"id":"s_work_han_thu_66_44","chapterId":"ch_work_han_thu_66","textTraditional":"〔一二〕師古曰：「頟字或作額。」","sentenceOrder":44},
  {"id":"s_work_han_thu_66_45","chapterId":"ch_work_han_thu_66","textTraditional":"〔一三〕臣瓚曰：「茂陵中書云南奅侯，此本字也。」師古曰：「窌音普教反。奅亦同字。」","sentenceOrder":45},
  {"id":"s_work_han_thu_66_46","chapterId":"ch_work_han_thu_66","textTraditional":"明年春，大將軍青出定襄，合騎侯敖為中將軍，太僕賀為左將軍，翕侯趙信為前將軍，衛尉蘇建為右將軍，郎中令李廣為後將軍，左內史李沮為彊弩將軍，咸屬大將軍，斬首數千級而還。月餘，悉復出定襄，斬首虜萬餘人。蘇建、趙信并軍三千餘騎，獨逢單于兵，與戰一日餘，漢兵且盡。信故胡人，降為翕侯，見急，匈奴誘之，遂將其餘騎可八百奔降單于。〔一〕蘇建盡亡其軍，獨以身得亡去，自歸青。青問其罪正閎、長史安、議郎周霸等：〔二〕「建當云何？」〔三〕霸曰：「自大將軍出，未嘗斬裨將，今建棄軍，可斬，以明將軍之威。」閎、安曰：「不然。兵法『小敵之堅，大敵之禽也。』〔四〕今建以數千當單于數萬，力戰一日餘，士皆不敢有二心。自歸而斬之，是示後無反意也。不當斬。」青曰：「青幸得以胏附待罪行間〔五〕，不患無威，而霸說我以明威，甚失臣意。且使臣職雖當斬將，以臣之尊寵而不敢自擅專誅於境外，其歸天子，天子自裁之，於以風為人臣不敢專權，不亦可乎？」〔六〕軍吏皆曰「善」。遂囚建行在所。","sentenceOrder":46},
  {"id":"s_work_han_thu_66_47","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「犇，古奔字也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_66_48","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　張晏曰：「正，軍正也。閎，名也。」如淳曰：「律，都軍官長史一人。」","sentenceOrder":48},
  {"id":"s_work_han_thu_66_49","chapterId":"ch_work_han_thu_66","textTraditional":"〔三〕　師古曰：「謂處斷其罪法何至也？」","sentenceOrder":49},
  {"id":"s_work_han_thu_66_50","chapterId":"ch_work_han_thu_66","textTraditional":"〔四〕　師古曰：「言眾寡不敵，以其堅戰無有退心，故士卒喪盡也。一說，若建恥敗而不自歸，則亦被匈奴禽之而去。」","sentenceOrder":50},
  {"id":"s_work_han_thu_66_51","chapterId":"ch_work_han_thu_66","textTraditional":"〔五〕　師古曰：「胏附，謂親戚也。解在田蚡傳也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_66_52","chapterId":"ch_work_han_thu_66","textTraditional":"〔六〕　師古曰：「風讀曰諷。」","sentenceOrder":52},
  {"id":"s_work_han_thu_66_53","chapterId":"ch_work_han_thu_66","textTraditional":"是歲也，霍去病始侯。","sentenceOrder":53},
  {"id":"s_work_han_thu_66_54","chapterId":"ch_work_han_thu_66","textTraditional":"霍去病，大將軍青姊少兒子也。其父霍仲孺先與少兒通，生去病。及衛皇后尊，少兒更為詹事陳掌妻。去病以皇后姊子，年十八為侍中。善騎射，再從大將軍。大將軍受詔，予壯士，為票姚校尉，〔一〕與輕勇騎八百直棄大（將）軍數百里赴利，斬捕首虜過當。〔二〕於是上曰：「票姚校尉去病斬首捕虜二千二十八級，得相國、當戶，斬單于大父行藉若侯產，〔三〕捕季父羅姑比，再冠軍，〔四〕以二千五百戶封去病為冠軍侯。上谷太守郝賢四從大將軍，捕首虜千三百級，封賢為終利侯。騎士孟已有功，賜爵關內侯，邑二百戶。」","sentenceOrder":54},
  {"id":"s_work_han_thu_66_55","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　服虔曰：「音飄搖。」師古曰：「票音頻妙反。姚音羊召反。票姚，勁疾之貌也。荀悅漢紀作票鷂字。去病後為票騎將軍，尚取票姚之字耳。今讀者音飄遙，則不當其義也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_66_56","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　師古曰：「言計其所將人數，則捕首虜為多，過於所當也。一曰漢軍失亡者少，而殺獲匈奴數多，故曰過當也。其下並同。」","sentenceOrder":56},
  {"id":"s_work_han_thu_66_57","chapterId":"ch_work_han_thu_66","textTraditional":"〔三〕　張晏曰：「藉若，胡侯也。產，名也。」師古曰：「此人單于祖父之行也。行音胡浪反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_66_58","chapterId":"ch_work_han_thu_66","textTraditional":"〔四〕　師古曰：「亦單于之季父也，羅姑，其名也。比，頻也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_66_59","chapterId":"ch_work_han_thu_66","textTraditional":"是歲失兩將軍，亡翕侯，功不多，故青不益封。蘇建至，上弗誅，贖為庶人。青賜千金。是時王夫人方幸於上，甯乘說青曰：〔一〕「將軍所以功未甚多，身食萬戶，三子皆為侯者，以皇后故也。今王夫人幸而宗族未富貴，願將軍奉所賜千金為王夫人親壽。」〔二〕青以五百金為王夫人親壽。上聞，問青，青以實對。上乃拜甯乘為東海都尉。","sentenceOrder":59},
  {"id":"s_work_han_thu_66_60","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「史記云甯乘齊人。」","sentenceOrder":60},
  {"id":"s_work_han_thu_66_61","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　師古曰：「親，母也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_66_62","chapterId":"ch_work_han_thu_66","textTraditional":"校尉張騫從大將軍，以嘗使大夏，留匈奴中久，道軍，知善水草處，〔一〕軍得以無飢渴，因前使絕國功，封騫為博望侯。","sentenceOrder":62},
  {"id":"s_work_han_thu_66_63","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「道讀曰導。」","sentenceOrder":63},
  {"id":"s_work_han_thu_66_64","chapterId":"ch_work_han_thu_66","textTraditional":"去病侯三歲，元狩（三）〔二〕年春為票騎將軍，將萬騎出隴西，有功。上曰：「票騎將軍率戎士隃烏盭，〔一〕討遫濮，〔二〕涉狐奴，〔三〕歷五王國，輜重人眾攝讋者弗取，〔四〕幾獲單于子。〔五〕轉戰六日，過焉支山千有餘里，合短兵，鏖皋蘭下，〔六〕殺折蘭王，斬盧侯王，〔七〕銳悍者誅，全甲獲醜，執渾邪王子〔八〕及相國、都尉，捷首虜八千九百六十級，收休屠祭天金人，〔九〕師率減什七，〔一０〕益封去病二千二百戶。」","sentenceOrder":64},
  {"id":"s_work_han_thu_66_65","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「隃與踰同。盭，古戾字也。烏盭，山名也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_66_66","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　師古曰：「遫，古速字也。遫濮，匈奴部落名也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_66_67","chapterId":"ch_work_han_thu_66","textTraditional":"〔三〕　晉灼曰：「水名也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_66_68","chapterId":"ch_work_han_thu_66","textTraditional":"〔四〕　師古曰：「攝讋，謂振動失志氣。言距戰者誅，服者則赦也。讋音之涉反。」","sentenceOrder":68},
  {"id":"s_work_han_thu_66_69","chapterId":"ch_work_han_thu_66","textTraditional":"〔五〕　師古曰：「幾音距衣反。」","sentenceOrder":69},
  {"id":"s_work_han_thu_66_70","chapterId":"ch_work_han_thu_66","textTraditional":"〔六〕　應劭曰：「隴西白石縣塞外河名也。」蘇林曰：「匈奴中山關名也。」李奇曰：「鏖音麃，津名也。」晉灼曰：「世俗謂盡死殺人為鏖糟。」文穎曰：「鏖音意曹反。」師古曰：「鏖字本從金麀聲，轉寫訛耳。鏖謂苦擊而多殺也。皋蘭，山名也。言苦戰於皋蘭山下而多殺虜也。晉說文音皆得之。今俗猶謂打擊之甚者曰鏖。麀，牡鹿也，音於求反。」","sentenceOrder":70},
  {"id":"s_work_han_thu_66_71","chapterId":"ch_work_han_thu_66","textTraditional":"〔七〕　張晏曰：「折蘭、盧侯，胡國名也。殺者，殺之而已。斬者，獲其首也。」師古曰：「折蘭，匈奴中姓也。今鮮卑有是蘭姓者，即其種也。折音上列反。」","sentenceOrder":71},
  {"id":"s_work_han_thu_66_72","chapterId":"ch_work_han_thu_66","textTraditional":"〔八〕　師古曰：「全甲，謂軍中之甲不喪失也。渾音下昆反。」","sentenceOrder":72},
  {"id":"s_work_han_thu_66_73","chapterId":"ch_work_han_thu_66","textTraditional":"〔九〕　如淳曰：「祭天以金人為主也。」張晏曰：「佛徒祠金人也。」師古曰：「今之佛像是也。休音許虯反。屠音儲。」","sentenceOrder":73},
  {"id":"s_work_han_thu_66_74","chapterId":"ch_work_han_thu_66","textTraditional":"〔一０〕師古曰：「言其破敵，故匈奴之師十減其七也。一曰，漢兵失亡之數。下皆類此也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_66_75","chapterId":"ch_work_han_thu_66","textTraditional":"其夏，去病與合騎侯敖俱出北地，異道。博望侯張騫、郎中令李廣俱出右北平，異道。廣將四千騎先至，騫將萬騎後。匈奴左賢王將數萬騎圍廣，廣與戰二日，死者過半，所殺亦過當。騫至，匈奴引兵去。騫坐行留，當斬，贖為庶人。〔一〕而去病出北地，遂深入，合騎侯失道，不相得。去病至祁連山，〔二〕捕首虜甚多。上曰：「票騎將軍涉鈞耆，濟居延，〔三〕遂臻小月氏，〔四〕攻祁連山，揚武乎鱳得，〔五〕得單于單桓、酋涂王，〔六〕及相國、都尉以眾降下者二千五百人，可謂能舍服知成而止矣。〔七〕捷首虜三萬二百，獲五王，王母、單于閼氏、王子五十九人，相國、將軍、當戶、都尉六十三人，師大率減什三，益封去病五千四百戶。賜校尉從至小月氏者爵左庶長。〔八〕鷹擊司馬破奴〔九〕再從票騎將軍斬遫濮王，捕稽且王，〔一０〕右千騎將〔得〕王、王母各一人，王子以下四十一人，捕虜三千三百三十人，前行捕虜千四百人，〔一一〕封破奴為從票侯。〔一二〕校尉高不識從票騎將軍捕呼于耆王王子以下十一人，捕虜千七百六十八人，封不識為宜冠侯。校尉僕多有功，封為煇渠侯。」〔一三〕合騎侯敖坐留不與票騎將軍會，當斬，贖為庶人。諸宿將所將士馬兵亦不如去病，〔一四〕去病所將常選，〔一五〕然亦敢深入，常與壯騎先其大軍，軍亦有天幸，未嘗困絕也。然而諸宿將常留落不耦。〔一六〕由此去病日以親貴，比大將軍。","sentenceOrder":75},
  {"id":"s_work_han_thu_66_76","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「軍行而輒稽留，故坐法。」","sentenceOrder":76},
  {"id":"s_work_han_thu_66_77","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　師古曰：「祁連山即天山也，匈奴呼天為祁連。祁音上夷反。」","sentenceOrder":77},
  {"id":"s_work_han_thu_66_78","chapterId":"ch_work_han_thu_66","textTraditional":"〔三〕　張晏曰：「鈞耆、居延，皆水名也。淺曰涉。深曰濟。」師古曰：「涉謂人馬涉度也。濟謂以舟船。」","sentenceOrder":78},
  {"id":"s_work_han_thu_66_79","chapterId":"ch_work_han_thu_66","textTraditional":"〔四〕　師古曰：「臻，至也。氏音支。」","sentenceOrder":79},
  {"id":"s_work_han_thu_66_80","chapterId":"ch_work_han_thu_66","textTraditional":"〔五〕　鄭氏曰：「鱳音鹿，張掖縣也。」師古曰：「鄭說非也。此鱳得，匈奴中地名，而張掖縣轉取其名耳。」","sentenceOrder":80},
  {"id":"s_work_han_thu_66_81","chapterId":"ch_work_han_thu_66","textTraditional":"〔六〕　張晏曰：「單桓、酋涂，皆胡王也。」師古曰：「酋音才由反。涂音塗。」","sentenceOrder":81},
  {"id":"s_work_han_thu_66_82","chapterId":"ch_work_han_thu_66","textTraditional":"〔七〕　師古曰：「服而舍之，功成則止也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_66_83","chapterId":"ch_work_han_thu_66","textTraditional":"〔八〕　師古曰：「第十爵。」","sentenceOrder":83},
  {"id":"s_work_han_thu_66_84","chapterId":"ch_work_han_thu_66","textTraditional":"〔九〕　師古曰：「趙破奴。」","sentenceOrder":84},
  {"id":"s_work_han_thu_66_85","chapterId":"ch_work_han_thu_66","textTraditional":"〔一０〕師古曰：「且音子閭反。」","sentenceOrder":85},
  {"id":"s_work_han_thu_66_86","chapterId":"ch_work_han_thu_66","textTraditional":"〔一一〕師古曰：「前行，謂在軍之前而行。」","sentenceOrder":86},
  {"id":"s_work_han_thu_66_87","chapterId":"ch_work_han_thu_66","textTraditional":"〔一二〕張晏曰：「從票騎將軍有功，因以為號。」","sentenceOrder":87},
  {"id":"s_work_han_thu_66_88","chapterId":"ch_work_han_thu_66","textTraditional":"〔一三〕師古曰：「功臣侯表作僕朋，今此作多，轉寫者誤也。煇音暉也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_66_89","chapterId":"ch_work_han_thu_66","textTraditional":"〔一四〕師古曰：「宿，舊也。兵，兵器也」","sentenceOrder":89},
  {"id":"s_work_han_thu_66_90","chapterId":"ch_work_han_thu_66","textTraditional":"〔一五〕師古曰：「選取驍銳。」","sentenceOrder":90},
  {"id":"s_work_han_thu_66_91","chapterId":"ch_work_han_thu_66","textTraditional":"〔一六〕師古曰：「留謂遲留，落謂墜落，故不諧耦而無功也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_66_92","chapterId":"ch_work_han_thu_66","textTraditional":"其後，單于怒渾邪王居西方數為漢所破，亡數萬人，以票騎之兵也，欲召誅渾邪王。渾邪王與休屠王等謀欲降漢，使人先要道邊〔一〕。是時大行李息將城河上，得渾邪王使，即馳傳以聞。〔二〕上恐其以詐降而襲邊，乃令去病將兵往迎之。去病既度河，與渾邪眾相望。渾邪裨王將見漢軍而多欲不降者，〔二〕頗遁去。去病乃馳入，得與渾邪王相見，斬其欲亡者八千人，遂獨遣渾邪王乘傳先詣行在所，盡將其眾度河，降者數萬人，號稱十萬。既至長安，天子所以賞賜數十鉅萬。封渾邪王萬戶，為漯陰侯。〔四〕封其裨王呼毒尼為下摩侯，〔五〕雁疪為煇渠侯，〔六〕禽黎為河綦侯，〔七〕大當戶調雖為常樂侯。〔八〕於是上嘉去病之功，曰：「票騎將軍去病率師征匈奴，西域王渾邪王及厥眾萌咸奔於率，〔九〕以軍糧接食，并將控弦萬有餘人，〔一０〕誅獟悍，〔一一〕捷首虜八千餘級，降異國之王三十二。戰士不離傷，〔一二〕十萬之眾畢懷集服。仍興之勞，爰及河塞，庶幾亡患。〔一三〕以千七百戶益封票騎將軍。減隴西、北地、上郡戍卒之半，以寬天下繇役。」乃分處降者於邊五郡故塞外，而皆在河南，因其故俗為屬國。〔一四〕其明年，匈奴入右北平、定襄，殺略漢千餘人。","sentenceOrder":92},
  {"id":"s_work_han_thu_66_93","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「道猶言也。先為要約來言之於邊界。」","sentenceOrder":93},
  {"id":"s_work_han_thu_66_94","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　師古曰：「傳音張戀反。次下亦同。」","sentenceOrder":94},
  {"id":"s_work_han_thu_66_95","chapterId":"ch_work_han_thu_66","textTraditional":"〔三〕　師古曰：「恐被掩覆也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_66_96","chapterId":"ch_work_han_thu_66","textTraditional":"〔四〕　如淳曰：「漯陰，平原縣也。」師古曰：「漯音吐合反。」","sentenceOrder":96},
  {"id":"s_work_han_thu_66_97","chapterId":"ch_work_han_thu_66","textTraditional":"〔五〕　文穎曰：「呼毒尼，胡王名也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_66_98","chapterId":"ch_work_han_thu_66","textTraditional":"〔六〕　文穎曰：「雁音鷹。疪音庇蔭之庇。」師古曰：「疪音匹履反，其字從疒，非庇蔭之庇。疒音女革反。」","sentenceOrder":98},
  {"id":"s_work_han_thu_66_99","chapterId":"ch_work_han_thu_66","textTraditional":"〔七〕　師古曰：「功臣侯表作烏黎，今此作禽黎，轉寫誤耳。」","sentenceOrder":99},
  {"id":"s_work_han_thu_66_100","chapterId":"ch_work_han_thu_66","textTraditional":"〔八〕　師古曰：「功臣侯表作稠睢，今此傳作調雖，表傳不同，當有誤者。」","sentenceOrder":100},
  {"id":"s_work_han_thu_66_101","chapterId":"ch_work_han_thu_66","textTraditional":"〔九〕　師古曰：「萌字與甿同。犇，古奔字也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_66_102","chapterId":"ch_work_han_thu_66","textTraditional":"〔一０〕師古曰：「言能引弓皆堪戰陣。」","sentenceOrder":102},
  {"id":"s_work_han_thu_66_103","chapterId":"ch_work_han_thu_66","textTraditional":"〔一一〕師古曰：「獟，健行輕貌也，字或作趬。捍，勇也。獟音丘昭反，又音丘召反。」","sentenceOrder":103},
  {"id":"s_work_han_thu_66_104","chapterId":"ch_work_han_thu_66","textTraditional":"〔一二〕師古曰：「離，遭也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_66_105","chapterId":"ch_work_han_thu_66","textTraditional":"〔一三〕師古曰：「重興軍旅之勞，及北河沙塞之表，可得寧息無憂患也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_66_106","chapterId":"ch_work_han_thu_66","textTraditional":"〔一四〕師古曰：「不改其本國之俗而屬於漢，故號屬國。」","sentenceOrder":106},
  {"id":"s_work_han_thu_66_107","chapterId":"ch_work_han_thu_66","textTraditional":"其明年，上與諸將議曰：「翕侯趙信為單于畫計，常以為漢兵不能度幕輕留，〔一〕今大發卒，其勢必得所欲。」是歲元狩四年也。春，上令大將軍青、票騎將軍去病各五萬騎，步兵轉者踵軍數十萬，〔二〕而敢力戰深入之士皆屬去病。去病始為出定襄，當單于。捕虜，虜言單于東，乃更令去病出代郡，令青出定襄。郎中令李廣為前將軍，太僕公孫賀為左將軍，主爵趙食其為右將軍，〔三〕平陽侯襄為後將軍，〔四〕皆屬大將軍。趙信為單于謀曰：「漢兵即度幕，人馬罷，〔五〕匈奴可坐收虜耳。」〔六〕乃悉遠北其輜重，〔七〕皆以精兵待幕北。而適直青軍出塞千餘里，〔八〕見單于兵陳而待，〔九〕於是青令武剛車自環為營，〔一０〕而縱五千騎往當匈奴，匈奴亦（從）〔縱〕萬騎。會日且入，〔一一〕而大風起，沙礫擊面，〔一二〕兩軍不相見，漢益縱左右翼繞單于。〔一三〕單于視漢兵多，而士馬尚彊，戰而匈奴不利，薄莫，單于遂乘六臝，壯騎可數百，直冒漢圍西北馳去。〔一四〕昏，漢匈奴相紛挐，〔一五〕殺傷大當〔一六〕。漢軍左校捕虜，言單于未昏而去，漢軍因發輕騎夜追之，青因隨其後。匈奴兵亦散走。會明，行二百餘里，不得單于，頗捕斬首虜萬餘級，遂至窴顏山趙信城，〔一七〕得匈奴積粟食軍。〔一八〕軍留一日而還，悉燒其城餘粟以歸。","sentenceOrder":107},
  {"id":"s_work_han_thu_66_108","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「言輕易漢軍，故留而不去也。一曰，謂漢兵不能輕入而久留也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_66_109","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　師古曰：「轉者謂運輜重也。踵，接也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_66_110","chapterId":"ch_work_han_thu_66","textTraditional":"〔三〕　師古曰：「食音異。其音基。」","sentenceOrder":110},
  {"id":"s_work_han_thu_66_111","chapterId":"ch_work_han_thu_66","textTraditional":"〔四〕　師古曰：「曹襄。」","sentenceOrder":111},
  {"id":"s_work_han_thu_66_112","chapterId":"ch_work_han_thu_66","textTraditional":"〔五〕　師古曰：「罷讀曰疲。」","sentenceOrder":112},
  {"id":"s_work_han_thu_66_113","chapterId":"ch_work_han_thu_66","textTraditional":"〔六〕　師古曰：「言收虜取漢軍人馬，可不費力，故言坐。」","sentenceOrder":113},
  {"id":"s_work_han_thu_66_114","chapterId":"ch_work_han_thu_66","textTraditional":"〔七〕　師古曰：「送輜重遠去，令處北也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_66_115","chapterId":"ch_work_han_thu_66","textTraditional":"〔八〕　師古曰：「直讀曰值。」","sentenceOrder":115},
  {"id":"s_work_han_thu_66_116","chapterId":"ch_work_han_thu_66","textTraditional":"〔九〕　師古曰：「為行陳而待。」","sentenceOrder":116},
  {"id":"s_work_han_thu_66_117","chapterId":"ch_work_han_thu_66","textTraditional":"〔一０〕張晏曰：「兵車也。」師古曰：「環，繞也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_66_118","chapterId":"ch_work_han_thu_66","textTraditional":"〔一一〕師古曰：「言日欲沒也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_66_119","chapterId":"ch_work_han_thu_66","textTraditional":"〔一二〕師古曰：「礫，小石也，音歷。」","sentenceOrder":119},
  {"id":"s_work_han_thu_66_120","chapterId":"ch_work_han_thu_66","textTraditional":"〔一三〕師古曰：「翼謂左右舒引其兵，如鳥之翅翼。」","sentenceOrder":120},
  {"id":"s_work_han_thu_66_121","chapterId":"ch_work_han_thu_66","textTraditional":"〔一四〕師古曰：「臝者，驢種馬子，堅忍。單于自乘善走臝，而壯騎隨之也。冒，犯也。臝音來戈反。冒音莫克反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_66_122","chapterId":"ch_work_han_thu_66","textTraditional":"〔一五〕師古曰：「紛挐，亂相持搏也。挐音女居反。」","sentenceOrder":122},
  {"id":"s_work_han_thu_66_123","chapterId":"ch_work_han_thu_66","textTraditional":"〔一六〕師古曰：「各大相殺傷。」","sentenceOrder":123},
  {"id":"s_work_han_thu_66_124","chapterId":"ch_work_han_thu_66","textTraditional":"〔一七〕如淳曰：「趙信前降匈奴，匈奴築城居之。」","sentenceOrder":124},
  {"id":"s_work_han_thu_66_125","chapterId":"ch_work_han_thu_66","textTraditional":"〔一八〕師古曰：「食讀曰飤。」","sentenceOrder":125},
  {"id":"s_work_han_thu_66_126","chapterId":"ch_work_han_thu_66","textTraditional":"青之與單于會也，而前將軍廣、右將軍食其軍別從東道，或失道。〔一〕大將軍引還，過幕南，乃相逢。青欲使使歸報，令長史簿責廣，〔二〕廣自殺。食其贖為庶人。青軍入塞，凡斬首虜萬九千級。","sentenceOrder":126},
  {"id":"s_work_han_thu_66_127","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「或，迷也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_66_128","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　師古曰：「簿音步戶反。」","sentenceOrder":128},
  {"id":"s_work_han_thu_66_129","chapterId":"ch_work_han_thu_66","textTraditional":"是時匈奴眾失單于十餘日，右谷蠡王自立為單于。〔一〕單于後得其眾，右王乃去單于之號。〔二〕","sentenceOrder":129},
  {"id":"s_work_han_thu_66_130","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「谷音鹿。蠡音盧奚反。」","sentenceOrder":130},
  {"id":"s_work_han_thu_66_131","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　師古曰：「去，除也，音丘呂反。」","sentenceOrder":131},
  {"id":"s_work_han_thu_66_132","chapterId":"ch_work_han_thu_66","textTraditional":"去病騎兵車重與大將軍軍等，〔一〕而亡裨將。悉以李敢等為大校，當裨將，出代、右北平二千餘里，直左方兵，〔二〕所斬捕功已多於青。","sentenceOrder":132},
  {"id":"s_work_han_thu_66_133","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「重音直用反。」","sentenceOrder":133},
  {"id":"s_work_han_thu_66_134","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　師古曰：「直，當也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_66_135","chapterId":"ch_work_han_thu_66","textTraditional":"既皆還，上曰：「票騎將軍去病率師躬將所獲葷允之士，〔一〕約輕齎，絕大幕，〔二〕涉獲單于章渠，〔三〕以誅北車耆，〔四〕轉擊左大將雙，獲旗鼓，歷度難侯，〔五〕濟弓盧，〔六〕獲屯頭王、韓王等三人，〔七〕將軍、相國、當戶、都尉八十三人，封狼居胥山，禪於姑衍，登臨翰海，〔八〕執訊獲醜七萬有四百四十三級，師率減什二，取食於敵，卓行殊遠而糧不絕。〔九〕以五千八百戶益封票騎將軍。右北平太守路博德屬票騎將軍，會興城，不失期，從至檮余山，〔一０〕斬首捕虜二千八百級，封博德為邳離侯。北地都尉衛山從票騎將軍獲王，封山為義陽侯。故歸義侯因淳王復陸支、〔一一〕樓剸王伊即靬〔一二〕皆從票騎將軍有功，封復陸支為杜侯，伊即靬為眾利侯。從票侯破奴、昌武侯安稽從票騎有功，益封各三百戶。漁陽太守解、校尉敢皆獲鼓旗，賜爵關內侯，解食邑三百戶，敢二百戶。校尉自為爵左庶長。」軍吏卒為官，賞賜甚多。而青不得益封，吏卒無封者。唯西河太守常惠、雲中太守遂成受賞，遂成秩諸侯相，賜食邑二百戶，黃金百斤，惠爵關內侯。","sentenceOrder":135},
  {"id":"s_work_han_thu_66_136","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　服虔曰：「葷音熏。葷允，熏鬻也。堯時曰熏鬻，周曰獫允，秦曰匈奴。」師古曰：「葷字與薰同。鬻音弋六反。」","sentenceOrder":136},
  {"id":"s_work_han_thu_66_137","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　師古曰：「輕齎者，不以輜重自隨，而所齎糧食少也。一曰齎字與資同，謂資裝也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_66_138","chapterId":"ch_work_han_thu_66","textTraditional":"〔三〕　師古曰：「涉謂涉水也。章渠，單于之近臣也，涉水而破獲之。」","sentenceOrder":138},
  {"id":"s_work_han_thu_66_139","chapterId":"ch_work_han_thu_66","textTraditional":"〔四〕　晉灼曰：「王號也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_66_140","chapterId":"ch_work_han_thu_66","textTraditional":"〔五〕　師古曰：「山名也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_66_141","chapterId":"ch_work_han_thu_66","textTraditional":"〔六〕　晉灼曰：「水名也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_66_142","chapterId":"ch_work_han_thu_66","textTraditional":"〔七〕　李奇曰：「皆匈奴王號。」","sentenceOrder":142},
  {"id":"s_work_han_thu_66_143","chapterId":"ch_work_han_thu_66","textTraditional":"〔八〕　張晏曰：「登海邊山以望海也。有大功，故增山而廣地也。」如淳曰：「翰海，北海名也。」師古曰：「積土增山曰封，為墠祭地曰禪也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_66_144","chapterId":"ch_work_han_thu_66","textTraditional":"〔九〕　師古曰：「卓亦遠意。」","sentenceOrder":144},
  {"id":"s_work_han_thu_66_145","chapterId":"ch_work_han_thu_66","textTraditional":"〔一０〕師古曰：「檮音籌，其字從木。」","sentenceOrder":145},
  {"id":"s_work_han_thu_66_146","chapterId":"ch_work_han_thu_66","textTraditional":"〔一一〕師古曰：「復音芳福反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_66_147","chapterId":"ch_work_han_thu_66","textTraditional":"〔一二〕師古曰：「剸音之兗反。靬音居言反。」","sentenceOrder":147},
  {"id":"s_work_han_thu_66_148","chapterId":"ch_work_han_thu_66","textTraditional":"兩軍之出塞，塞閱官及私馬凡十四萬匹，而後入塞者不滿三萬匹。乃置大司馬位，大將軍、票騎將軍皆為大司馬。〔一〕定令，令票騎將軍秩祿與大將軍等。自是後，青日衰而去病日益貴。青故人門下多去事去病，輒得官爵，唯獨任安不肯去。〔二〕","sentenceOrder":148},
  {"id":"s_work_han_thu_66_149","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　晉灼曰：「悉加大司馬者，欲令票騎將軍去病與大將軍青等耳。」","sentenceOrder":149},
  {"id":"s_work_han_thu_66_150","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　師古曰：「安，滎陽人，後為益州刺史，即遺司馬遷書者。」","sentenceOrder":150},
  {"id":"s_work_han_thu_66_151","chapterId":"ch_work_han_thu_66","textTraditional":"去病為人少言不泄，有氣敢往。上嘗欲教之吳孫兵法，〔一〕對曰：「顧方略何如耳，不至學古兵法。」〔二〕上為治第，令視之，對曰：「匈奴不滅，無以家為也。」由此上益重愛之。然少而侍中，貴不省士。〔三〕其從軍，上為遣太官齎數十乘，〔四〕既還，重車餘棄粱肉，〔五〕而士有飢者。其在塞外，卒乏糧，或不能自振〔六〕，而去病尚穿域躢鞠也。〔七〕事多此類。青仁，喜士退讓，〔八〕以和柔自媚於上，然於天下未有稱也。","sentenceOrder":151},
  {"id":"s_work_han_thu_66_152","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「吳，吳起也。孫，孫武也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_66_153","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　師古曰：「顧，念也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_66_154","chapterId":"ch_work_han_thu_66","textTraditional":"〔三〕　師古曰：「省，視也。不恤視也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_66_155","chapterId":"ch_work_han_thu_66","textTraditional":"〔四〕　師古曰：「齎與資同。解已在前也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_66_156","chapterId":"ch_work_han_thu_66","textTraditional":"〔五〕　師古曰：「粱，粟類也，米之善者。重音直用反。」","sentenceOrder":156},
  {"id":"s_work_han_thu_66_157","chapterId":"ch_work_han_thu_66","textTraditional":"〔六〕　師古曰：「振，舉也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_66_158","chapterId":"ch_work_han_thu_66","textTraditional":"〔七〕　服虔曰：「穿地作鞠室也。」師古曰：「鞠，以皮為之，實以毛，蹴躢而戲也。躢音徒臘反。鞠音鉅六反。」","sentenceOrder":158},
  {"id":"s_work_han_thu_66_159","chapterId":"ch_work_han_thu_66","textTraditional":"〔八〕　師古曰：「喜音許吏反。」","sentenceOrder":159},
  {"id":"s_work_han_thu_66_160","chapterId":"ch_work_han_thu_66","textTraditional":"去病自四年軍後三歲，元狩六年薨。上悼之，發屬國玄甲，軍陳自長安至茂陵，〔一〕為冢象祁連山。〔二〕諡之并武與廣地曰景桓侯。〔三〕子嬗嗣。〔四〕嬗字子侯，上愛之，幸其壯而將之。為奉車都尉，從封泰山而薨。無子，國除。","sentenceOrder":160},
  {"id":"s_work_han_thu_66_161","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「送其葬，所以寵衛之也。屬國，即上所云分處降者於邊五郡者也。玄甲，謂甲之黑色也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_66_162","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　師古曰：「在茂陵旁，冢上有（堅）〔豎〕石，冢前有石人馬者是也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_66_163","chapterId":"ch_work_han_thu_66","textTraditional":"〔三〕　蘇林曰：「景，武諡也。桓，廣地諡也。義見諡法。」張晏曰：「諡法『布義行剛曰景，辟土服遠曰桓』也。」","sentenceOrder":163},
  {"id":"s_work_han_thu_66_164","chapterId":"ch_work_han_thu_66","textTraditional":"〔四〕　師古曰：「嬗音上戰反。」","sentenceOrder":164},
  {"id":"s_work_han_thu_66_165","chapterId":"ch_work_han_thu_66","textTraditional":"自去病死後，青長子宜春侯伉坐法失侯。後五歲，伉弟二人，陰安侯不疑、發干侯登，皆坐酎（伉）〔金〕失侯。後二歲，冠軍侯國絕。後四年，元封五年，青薨，諡曰烈侯。子伉嗣，六年坐法免。","sentenceOrder":165},
  {"id":"s_work_han_thu_66_166","chapterId":"ch_work_han_thu_66","textTraditional":"自青圍單于後十四歲而卒，竟不復擊匈奴者，以漢馬少，又方南誅兩越，東伐朝鮮，擊羌、西南夷，以故久不伐胡。","sentenceOrder":166},
  {"id":"s_work_han_thu_66_167","chapterId":"ch_work_han_thu_66","textTraditional":"初，青既尊貴，而平陽侯曹壽有惡疾就國，長公主問：「列侯誰賢者？」左右皆言大將軍。主笑曰：「此出吾家，常騎從我，柰何？」左右曰：「於今尊貴無比。」於是長公主風白皇后，〔一〕皇后言之，上乃詔青尚平陽主，〔二〕與主合葬，起冢象廬山云。〔三〕","sentenceOrder":167},
  {"id":"s_work_han_thu_66_168","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「風讀曰諷。」","sentenceOrder":168},
  {"id":"s_work_han_thu_66_169","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　如淳曰：「本陽信長公主也，為平陽侯所尚，故稱平陽主。」","sentenceOrder":169},
  {"id":"s_work_han_thu_66_170","chapterId":"ch_work_han_thu_66","textTraditional":"〔三〕　師古曰：「在茂陵東，次去病冢之西，相併者是也。」","sentenceOrder":170},
  {"id":"s_work_han_thu_66_171","chapterId":"ch_work_han_thu_66","textTraditional":"最〔一〕大將軍青凡七出擊匈奴，斬捕首虜五萬餘級。一與單于戰，收河南地，置朔方郡。再益封，凡萬六千三百戶；封三子為侯，侯千三百戶，并之二萬二百戶。其裨將及校尉侯者九人，為特將者十五人，〔二〕李廣、張騫、公孫賀、李蔡、曹襄、韓說、蘇建皆自有傳。〔三〕","sentenceOrder":171},
  {"id":"s_work_han_thu_66_172","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「最亦凡也。」","sentenceOrder":172},
  {"id":"s_work_han_thu_66_173","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　師古曰：「特將，謂獨別為將而出征也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_66_174","chapterId":"ch_work_han_thu_66","textTraditional":"〔三〕　師古曰：「七人自有傳，八人今列於此下，凡十五人也。說讀曰悅。」","sentenceOrder":174},
  {"id":"s_work_han_thu_66_175","chapterId":"ch_work_han_thu_66","textTraditional":"李息，郁郅人也，〔一〕事景帝。至武帝立八歲，為材官將軍，軍馬邑；後六歲，為將軍，出代；後三歲，為將軍，從大將軍出朔方：皆無功。凡三為將軍，其後常為大行。","sentenceOrder":175},
  {"id":"s_work_han_thu_66_176","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「北地之縣也。郅音之日反。」","sentenceOrder":176},
  {"id":"s_work_han_thu_66_177","chapterId":"ch_work_han_thu_66","textTraditional":"公孫敖，義渠人，以郎事景帝。至武帝立十二歲，為騎將軍，出代，亡卒七千人，當斬，贖為庶人。後五歲，以校尉從大將軍，封合騎侯。後一歲，以中將軍從大將軍再出定襄，無功。後二歲，以將軍出北地，後票騎，失期當斬，贖為庶人。後二歲，以校尉從大將軍，無功。後十四歲，以因（杆）〔杅〕將軍築受降城。七歲，復以因杅將軍再出擊匈奴，至余吾，〔一〕亡士多，下吏，當斬，詐死，亡居民間五六歲。後覺，復繫。坐妻為巫蠱，族。凡四為將軍。","sentenceOrder":177},
  {"id":"s_work_han_thu_66_178","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「水名也，在朔方北。」","sentenceOrder":178},
  {"id":"s_work_han_thu_66_179","chapterId":"ch_work_han_thu_66","textTraditional":"李沮，雲中人，〔一〕事景帝。武帝立十七歲，以左內史為彊弩將軍。後一歲，復為彊弩將軍。","sentenceOrder":179},
  {"id":"s_work_han_thu_66_180","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　〔師古曰〕：「沮音俎。」","sentenceOrder":180},
  {"id":"s_work_han_thu_66_181","chapterId":"ch_work_han_thu_66","textTraditional":"張次公，河東人，以校尉從大將軍，封岸頭侯。其後太后崩，為將軍，軍北軍。後一歲，復從大將軍。凡再為將軍，後坐法失侯。","sentenceOrder":181},
  {"id":"s_work_han_thu_66_182","chapterId":"ch_work_han_thu_66","textTraditional":"趙信，以匈奴相國降，為侯。武帝立十八年，為前將軍，與匈奴戰，敗，降匈奴。","sentenceOrder":182},
  {"id":"s_work_han_thu_66_183","chapterId":"ch_work_han_thu_66","textTraditional":"趙食其，祋祤人。〔一〕武帝立十八年，以主爵都尉從大將軍，斬首六百六十級。元狩三年，賜爵關內侯，黃金百斤。明年，為右將軍，從大將軍出定襄，迷失道，當斬，贖為庶人。","sentenceOrder":183},
  {"id":"s_work_han_thu_66_184","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「馮翊之縣也。祋音丁活反，又音丁外反。祤音許羽反。」","sentenceOrder":184},
  {"id":"s_work_han_thu_66_185","chapterId":"ch_work_han_thu_66","textTraditional":"郭昌，雲中人，以校尉從大將軍。元封四年，以太中大夫為拔胡將軍，屯朔方。還擊昆明，無功，奪印。","sentenceOrder":185},
  {"id":"s_work_han_thu_66_186","chapterId":"ch_work_han_thu_66","textTraditional":"荀彘，太原廣武人，以御見，侍中，〔一〕用校尉數從大將軍。元封三年，為左將軍擊朝鮮，無功，坐捕樓船將軍誅。","sentenceOrder":186},
  {"id":"s_work_han_thu_66_187","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「以善御得見，因為侍中也。御謂御車也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_66_188","chapterId":"ch_work_han_thu_66","textTraditional":"最票騎將軍去病凡六出擊匈奴，其四出以將軍，〔一〕斬首虜十一萬餘級。渾邪王以眾降數萬，開河西酒泉之地，西方益少胡寇。四益封，凡萬七千七百戶。其校尉吏有功侯者六人，為將軍者二人。","sentenceOrder":188},
  {"id":"s_work_han_thu_66_189","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「再出為票姚校尉也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_66_190","chapterId":"ch_work_han_thu_66","textTraditional":"路博德，西河平州人，以右北平太守從票騎將軍，封邳離侯。票騎死後，博德以衛尉為伏波將軍，伐破南越，益封。其後坐法失侯。為彊弩都尉，屯居延，卒。","sentenceOrder":190},
  {"id":"s_work_han_thu_66_191","chapterId":"ch_work_han_thu_66","textTraditional":"趙破奴，太原人。嘗亡入匈奴，已而歸漢，為票騎將軍司馬。出北地，封從票侯，坐酎金失侯。後一歲，為匈河將軍，攻胡至匈河水，無功。後一歲，擊虜樓蘭王，後為浞野侯。後六歲，以浚稽將軍將二萬騎擊匈奴左王。左王與戰，兵八萬騎圍破奴，破奴為虜所得，遂沒其軍。居匈奴中十歲，復與其太子安國亡入漢。後坐巫蠱，族。","sentenceOrder":191},
  {"id":"s_work_han_thu_66_192","chapterId":"ch_work_han_thu_66","textTraditional":"自衛氏興，大將軍青首封，其後支屬五人為侯。凡二十四歲而五侯皆奪國。征和中，戾太子敗，衛氏遂滅。而霍去病弟光貴盛，自有傳。","sentenceOrder":192},
  {"id":"s_work_han_thu_66_193","chapterId":"ch_work_han_thu_66","textTraditional":"贊曰：蘇建嘗說責「大將軍至尊重，而天下之賢士大夫無稱焉，〔一〕願將軍觀古名將所招選者，勉之哉！」〔二〕青謝曰：「自魏其、武安之厚賓客，天子常切齒，彼親待士大夫，招賢黜不肖者，人主之柄也。人臣奉法遵職而已，何與招士！」〔三〕票騎亦方此意，為將如此。〔四〕","sentenceOrder":193},
  {"id":"s_work_han_thu_66_194","chapterId":"ch_work_han_thu_66","textTraditional":"〔一〕　師古曰：「言不為賢士大夫所稱譽。」","sentenceOrder":194},
  {"id":"s_work_han_thu_66_195","chapterId":"ch_work_han_thu_66","textTraditional":"〔二〕　師古曰：「勸令招賢薦士也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_66_196","chapterId":"ch_work_han_thu_66","textTraditional":"〔三〕　師古曰：「與讀曰豫。」","sentenceOrder":196},
  {"id":"s_work_han_thu_66_197","chapterId":"ch_work_han_thu_66","textTraditional":"〔四〕　師古曰：「方，比類也。」","sentenceOrder":197},
  {"id":"s_work_han_thu_66_198","chapterId":"ch_work_han_thu_66","textTraditional":"校勘記","sentenceOrder":198},
  {"id":"s_work_han_thu_66_199","chapterId":"ch_work_han_thu_66","textTraditional":"二四七四頁　五行　美宣王北（代）〔伐〕也。　景祐、殿、局本都作「伐」，此誤。","sentenceOrder":199},
  {"id":"s_work_han_thu_66_200","chapterId":"ch_work_han_thu_66","textTraditional":"二四七八頁　三行　與輕勇騎八百直棄大（將）軍數百里赴利，　劉敞說「大將軍」衍「將」字。","sentenceOrder":200},
  {"id":"s_work_han_thu_66_201","chapterId":"ch_work_han_thu_66","textTraditional":"二四七八頁　五行　捕季父羅姑比，再冠軍，　史記索隱顏氏云「羅姑比，單于季父名也」。小顏云「比，頻也」。案下文既云「再冠軍」，無容更言頻也。王先謙說索隱說是。","sentenceOrder":201},
  {"id":"s_work_han_thu_66_202","chapterId":"ch_work_han_thu_66","textTraditional":"二四七九頁　七行　元狩（三）〔二〕年春　宋祁說，「三」越本作「二」。王念孫說越本是，景祐本及史記並作「元狩二年」。","sentenceOrder":202},
  {"id":"s_work_han_thu_66_203","chapterId":"ch_work_han_thu_66","textTraditional":"二四八一頁　二行　右千騎將〔得〕王、王母各一人，　史記有「得」字，索隱說此千騎將是漢之將。王先謙說，此文自是右千騎將得王、王母各一人，本書脫「得」字。","sentenceOrder":203},
  {"id":"s_work_han_thu_66_204","chapterId":"ch_work_han_thu_66","textTraditional":"二四八四頁　八行　匈奴亦（從）〔縱〕萬騎。　王先謙說「從」當作「縱」，史記作「匈奴亦縱可萬騎」。","sentenceOrder":204},
  {"id":"s_work_han_thu_66_205","chapterId":"ch_work_han_thu_66","textTraditional":"二四八九頁一二行　冢上有（堅）〔豎〕石，　景祐、殿本都作「豎」，此誤。","sentenceOrder":205},
  {"id":"s_work_han_thu_66_206","chapterId":"ch_work_han_thu_66","textTraditional":"二四八九頁一六行　皆坐酎（伉）〔金〕失侯。　王先謙說「伉」字誤。按景祐、殿、局本都作「金」。","sentenceOrder":206},
  {"id":"s_work_han_thu_66_207","chapterId":"ch_work_han_thu_66","textTraditional":"二四九一頁　九行　以因（杆）〔杅〕將軍築受降城。　景祐、殿、局本都作「杅」。　王先謙說作「杅」是。","sentenceOrder":207},
  {"id":"s_work_han_thu_66_208","chapterId":"ch_work_han_thu_66","textTraditional":"二四九一頁一四行　〔師古曰〕：「沮音俎。」　王先謙說，脫「師古曰」三字。按各本都脫。","sentenceOrder":208},
  {"id":"s_work_han_thu_67_1","chapterId":"ch_work_han_thu_67","textTraditional":"董仲舒，廣川人也。少治春秋，孝景時為博士。下帷講誦，弟子傳以久次相授業，或莫見其面。〔一〕蓋三年不窺園，其精如此〔二〕。進退容止，非禮不行，學士皆師尊之。","sentenceOrder":1},
  {"id":"s_work_han_thu_67_2","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「言新學者但就其舊弟子受業，不必親見仲舒。」","sentenceOrder":2},
  {"id":"s_work_han_thu_67_3","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「雖有園圃，不窺視之，言專學也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_67_4","chapterId":"ch_work_han_thu_67","textTraditional":"武帝即位，舉賢良文學之士前後百數，〔一〕而仲舒以賢良對策焉。","sentenceOrder":4},
  {"id":"s_work_han_thu_67_5","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「數音所具反。」","sentenceOrder":5},
  {"id":"s_work_han_thu_67_6","chapterId":"ch_work_han_thu_67","textTraditional":"制曰：朕獲承至尊休德，〔一〕傳之亡窮，而施之罔極〔二〕，任大而守重，是以夙夜不皇康寧，〔三〕永惟萬事之統，猶懼有闕。〔四〕故廣延四方之豪俊，郡國諸侯公選賢良修絜博習之士〔五〕，欲聞大道之要，至論之極。〔六〕今子大夫褎然為舉首，〔七〕朕甚嘉之。子大夫其精心致思，朕垂聽而問焉。","sentenceOrder":6},
  {"id":"s_work_han_thu_67_7","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「休，美也。言承先帝極尊之位至美之德也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_67_8","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「罔亦無也。極，盡也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_67_9","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「皇，暇也。康，樂也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_67_10","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「永，深也。惟，思也。統，緒也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_67_11","chapterId":"ch_work_han_thu_67","textTraditional":"〔五〕　師古曰：「郡，郡守也。國，王國也。諸侯，列侯也。郡國及諸侯，總謂四方在外者。公選，謂以公正之道選士，無偏私也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_67_12","chapterId":"ch_work_han_thu_67","textTraditional":"〔六〕　師古曰：「極，中也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_67_13","chapterId":"ch_work_han_thu_67","textTraditional":"〔七〕　服虔曰：「子，男子之美號也。」張晏曰：「褎，進也，為舉賢良之首也。」師古曰：「褎然，盛服貌也。詩邶風旄丘之篇曰『褎如充耳』。褎音弋授反。」","sentenceOrder":13},
  {"id":"s_work_han_thu_67_14","chapterId":"ch_work_han_thu_67","textTraditional":"蓋聞五帝三王之道，改制作樂而天下洽和，百王同之。當虞氏之樂莫盛於韶，〔一〕於周莫盛於勺。〔二〕聖王已沒，鐘鼓筦絃之聲未衰，〔三〕而大道微缺，陵夷至虖桀紂之行，〔四〕王道大壞矣。夫五百年之間，守文之君，當塗之士，欲則先王之法以戴翼其世者甚眾，〔五〕然猶不能反，日以仆滅，〔六〕至後王而後止，豈其所持操或誖繆而失其統與？〔七〕固天降命不可復反，必推之於大衰而後息與？〔八〕烏虖！〔九〕凡所為屑屑，夙興夜寐，務法上古者，又將無補與？〔一０〕三代受命，其符安在？災異之變，何緣而起？性命之情，或夭或壽，或仁或鄙，〔一一〕習聞其號，未燭厥理。〔一二〕伊欲風流而令行，刑輕而姦改，〔一三〕百姓和樂，政事宣昭，何脩何飭而膏露降，百穀登，〔一四〕德潤四海，澤臻屮木〔一五〕，三光全，寒暑平，受天之祜，〔一六〕享鬼神之靈，〔一七〕德澤洋溢，施虖方外，延及群生？〔一八〕","sentenceOrder":14},
  {"id":"s_work_han_thu_67_15","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「韶，舜樂。」","sentenceOrder":15},
  {"id":"s_work_han_thu_67_16","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　張晏曰：「勺，周頌篇也，言能成先祖之功以養天下也。」師古曰：「勺讀與酌同。」","sentenceOrder":16},
  {"id":"s_work_han_thu_67_17","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「筦與管字同。」","sentenceOrder":17},
  {"id":"s_work_han_thu_67_18","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「陵夷，言漸穨替也。解在成紀。」","sentenceOrder":18},
  {"id":"s_work_han_thu_67_19","chapterId":"ch_work_han_thu_67","textTraditional":"〔五〕　師古曰：「翼，助也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_67_20","chapterId":"ch_work_han_thu_67","textTraditional":"〔六〕　師古曰：「反，還也。還於正道也。仆，斃也，音赴。」","sentenceOrder":20},
  {"id":"s_work_han_thu_67_21","chapterId":"ch_work_han_thu_67","textTraditional":"〔七〕　師古曰：「操，執也。誖，乖也。統，緒也。操音千高反。與讀曰歟。後皆類此。」","sentenceOrder":21},
  {"id":"s_work_han_thu_67_22","chapterId":"ch_work_han_thu_67","textTraditional":"〔八〕　師古曰：「息，止也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_67_23","chapterId":"ch_work_han_thu_67","textTraditional":"〔九〕　師古曰：「虖讀曰呼。嗚呼，歎辭也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_67_24","chapterId":"ch_work_han_thu_67","textTraditional":"〔一０〕師古曰：「屑屑，動作之貌。補，益也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_67_25","chapterId":"ch_work_han_thu_67","textTraditional":"〔一一〕師古曰：「夭壽，命也。仁鄙，性也。鄙謂不通也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_67_26","chapterId":"ch_work_han_thu_67","textTraditional":"〔一二〕師古曰：「燭，照也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_67_27","chapterId":"ch_work_han_thu_67","textTraditional":"〔一三〕師古曰：「伊，惟也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_67_28","chapterId":"ch_work_han_thu_67","textTraditional":"〔一四〕師古曰：「登，成也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_67_29","chapterId":"ch_work_han_thu_67","textTraditional":"〔一五〕師古曰：「臻，至也。屮，古草字也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_67_30","chapterId":"ch_work_han_thu_67","textTraditional":"〔一六〕師古曰：「祜，福也，音怙。」","sentenceOrder":30},
  {"id":"s_work_han_thu_67_31","chapterId":"ch_work_han_thu_67","textTraditional":"〔一七〕師古曰：「為鬼神所歆饗。」","sentenceOrder":31},
  {"id":"s_work_han_thu_67_32","chapterId":"ch_work_han_thu_67","textTraditional":"〔一八〕師古曰：「施亦延也。洋音羊。施音弋豉反。」","sentenceOrder":32},
  {"id":"s_work_han_thu_67_33","chapterId":"ch_work_han_thu_67","textTraditional":"子大夫明先聖之業，習俗化之變，終始之序，講聞高誼之日久矣，其明以諭朕。〔一〕科別其條，勿猥勿并，〔二〕取之於術，慎其所出。乃其不正不直，不忠不極，枉于執事，書之不泄，興于朕躬，毋悼後害。〔三〕子大夫其盡心，靡有所隱，朕將親覽焉。","sentenceOrder":33},
  {"id":"s_work_han_thu_67_34","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「諭謂曉告也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_67_35","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「猥，積也。并，合也。欲其一二疏理而言之。」","sentenceOrder":35},
  {"id":"s_work_han_thu_67_36","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「極，中也。公卿執事有不忠直而阿枉者，皆令言之。朕自發書，不有漏泄，勿懼有後害而不言也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_67_37","chapterId":"ch_work_han_thu_67","textTraditional":"仲舒對曰：","sentenceOrder":37},
  {"id":"s_work_han_thu_67_38","chapterId":"ch_work_han_thu_67","textTraditional":"陛下發德音，下明詔，求天命與情性，皆非愚臣之所能及也。臣謹案春秋之中，視前世已行之事，以觀天人相與之際，甚可畏也。國家將有失道之敗，而天乃先出災害以譴告之，〔一〕不知自省，又出怪異以警懼之，〔二〕尚不知變，而傷敗乃至。以此見天心之仁愛人君而欲止其亂也。自非大亡道之世者，天盡欲扶持而全安之，事在彊勉而已矣。〔三〕彊勉學問，則聞見博而知益明；彊勉行道，則德日起而大有功：此皆可使還至而（立）有效者也。〔四〕詩曰「夙夜匪解」，〔五〕書云「茂哉茂哉！」〔六〕皆彊勉之謂也。","sentenceOrder":38},
  {"id":"s_work_han_thu_67_39","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「譴，責也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_67_40","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「省，視也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_67_41","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「彊音其兩反。此下並同。」","sentenceOrder":41},
  {"id":"s_work_han_thu_67_42","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「還讀曰旋。旋，速也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_67_43","chapterId":"ch_work_han_thu_67","textTraditional":"〔五〕　師古曰：「大雅烝人之詩也。夙，早也。解讀曰懈。懈，怠也。其下亦同。」","sentenceOrder":43},
  {"id":"s_work_han_thu_67_44","chapterId":"ch_work_han_thu_67","textTraditional":"〔六〕　師古曰：「虞書咎繇謨之辭也。茂，勉也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_67_45","chapterId":"ch_work_han_thu_67","textTraditional":"道者，所繇適於治之路也，〔一〕仁義禮樂皆其具也。故聖王已沒，而子孫長久安寧數百歲，此皆禮樂教化之功也。王者未作樂之時，乃用先王之樂宜於世者，而以深入教化於民。教化之情不得，雅頌之樂不成，故王者功成作樂，樂其德也。樂者，所以變民風，化民俗也；其變民也易，其化人也著。〔二〕故聲發於和而本於情，接於肌膚，臧於骨髓。故王道雖微缺，而筦絃之聲未衰也。夫虞氏之不為政久矣，然而樂頌遺風猶有存者，是以孔子在齊而聞韶也。夫人君莫不欲安存而惡危亡，然而政亂國危者甚眾，所任者非其人，而所繇者非其道，〔三〕是以政日以仆滅也。夫周道衰於幽厲，非道亡也，幽厲不繇也。至於宣王，思昔先王之德，興滯補弊，明文武之功業，周道粲然復興，詩人美之而作，上天祐之，為生賢佐，後世稱誦，至今不絕。此夙夜不解行善之所致也。孔子曰「人能弘道，非道弘人」也。〔四〕故治亂廢興在於己，非天降命不可得反，其所操持誖謬失其統也。","sentenceOrder":45},
  {"id":"s_work_han_thu_67_46","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「繇讀與由同。由，從也。適，往也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_67_47","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「著，明也。易音弋豉反。著音竹筯反。」","sentenceOrder":47},
  {"id":"s_work_han_thu_67_48","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「繇讀與由同。下亦類此。」","sentenceOrder":48},
  {"id":"s_work_han_thu_67_49","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「論語載孔子之言也。言明智之人則能行道。內無其質，非道所化。」","sentenceOrder":49},
  {"id":"s_work_han_thu_67_50","chapterId":"ch_work_han_thu_67","textTraditional":"臣聞天之所大奉使之王者，必有非人力所能致而自至者，此受命之符也。天下之人同心歸之，若歸父母，故天瑞應誠而至。書曰「白魚入于王舟，有火復于王屋，流為烏」，〔一〕此蓋受命之符也。周公曰「復哉復哉」，〔二〕孔子曰「德不孤，必有鄰」，〔三〕皆積善絫德之效也。〔四〕及至後世，淫佚衰微，〔五〕不能統理群生，諸侯背畔，殘賊良民以爭壤土，廢德教而任刑罰。刑罰不中，則生邪氣；〔六〕邪氣積於下，怨惡畜於上。〔七〕上下不和，則陰陽繆盭而妖孽生矣。〔八〕此災異所緣而起也。","sentenceOrder":50},
  {"id":"s_work_han_thu_67_51","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「今文尚書泰誓之辭也。謂伐紂之時有此瑞也。復，歸也，音扶目反。」","sentenceOrder":51},
  {"id":"s_work_han_thu_67_52","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「周公視火烏之瑞，乃曰：『復哉復哉！』復，報也，言周有盛德，故天報以此瑞也。亦見今文泰誓也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_67_53","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「論語載孔子之言也。鄰，近也。言修德者不獨空為之而已，必有近助也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_67_54","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「絫，古累字。」","sentenceOrder":54},
  {"id":"s_work_han_thu_67_55","chapterId":"ch_work_han_thu_67","textTraditional":"〔五〕　師古曰：「佚與逸同。」","sentenceOrder":55},
  {"id":"s_work_han_thu_67_56","chapterId":"ch_work_han_thu_67","textTraditional":"〔六〕　師古曰：「中音竹仲反。」","sentenceOrder":56},
  {"id":"s_work_han_thu_67_57","chapterId":"ch_work_han_thu_67","textTraditional":"〔七〕　師古曰：「畜讀曰蓄。蓄，聚也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_67_58","chapterId":"ch_work_han_thu_67","textTraditional":"〔八〕　師古曰：「盭，古戾字。孽，災也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_67_59","chapterId":"ch_work_han_thu_67","textTraditional":"臣聞命者天之令也，性者生之質也，情者人之欲也。或夭或壽，或仁或鄙，陶冶而成之，不能粹美，〔一〕有治亂之所生，故不齊也。孔子曰：「君子之德風（也），小人之德草（也），屮上之風必偃。」〔二〕故堯舜行德則民仁壽，桀紂行暴則民鄙夭。夫上之化下，下之從上，猶泥之在鈞，唯甄者之所為；〔三〕猶金之在鎔，唯冶者之所鑄。〔四〕「綏之斯來，動之斯和」，此之謂也。〔五〕","sentenceOrder":59},
  {"id":"s_work_han_thu_67_60","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「陶以喻造瓦，冶以喻鑄金也。言天之生人有似於此也。粹，純也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_67_61","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「論語載孔子之言也。言人之從化，若草遇風則偃仆也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_67_62","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「甄，作瓦之人也。鈞，造瓦之法其中旋轉者。甄音吉延反。」","sentenceOrder":62},
  {"id":"s_work_han_thu_67_63","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「鎔謂鑄器之模範也。鎔音容。」","sentenceOrder":63},
  {"id":"s_work_han_thu_67_64","chapterId":"ch_work_han_thu_67","textTraditional":"〔五〕　師古曰：「論語載子貢對陳子禽之言也。綏，安也。言治國家者，安之則競來，動之則和悅耳。」","sentenceOrder":64},
  {"id":"s_work_han_thu_67_65","chapterId":"ch_work_han_thu_67","textTraditional":"臣謹案春秋之文，求王道之端，得之於正。〔一〕正次王，王次春。〔二〕春者，天之所為也；正者，王之所為也。其意曰，上承天之所為，而下以正其所為，正王道之端云爾。然則王者欲有所為，宜求其端於天。天道之大者在陰陽。陽為德，陰為刑；刑主殺而德主生。是故陽常居大夏，而以生育養長為事；陰常居大冬，而積於空虛不用之處。以此見天之任德不任刑也。天使陽出布施於上而主歲功，使陰入伏於下而時出佐陽；陽不得陰之助，亦不能獨成歲。終陽以成歲為名，〔三〕此天意也。王者承天意以從事，故任德教而不任刑。刑者不可任以治世，猶陰之不可任以成歲也。為政而任刑，不順於天，故先王莫之肯為也。今廢先王德教之官，而獨任執法之吏治民，毋乃任刑之意與！〔四〕孔子曰：「不教而誅謂之虐。」〔五〕虐政用於下，而欲德教之被四海，故難成也。","sentenceOrder":65},
  {"id":"s_work_han_thu_67_66","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「謂正月也，音之成反。」","sentenceOrder":66},
  {"id":"s_work_han_thu_67_67","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「解春秋書『春王正月』之一句也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_67_68","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　蘇林曰：「卒以陽名歲，尚德不尚刑也。」師古曰：「謂年首稱春也。即上文所云『王次春』者是也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_67_69","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「與讀曰歟。」","sentenceOrder":69},
  {"id":"s_work_han_thu_67_70","chapterId":"ch_work_han_thu_67","textTraditional":"〔五〕　師古曰：「論語載孔子之言。」","sentenceOrder":70},
  {"id":"s_work_han_thu_67_71","chapterId":"ch_work_han_thu_67","textTraditional":"臣謹案春秋謂一元之意，〔一〕一者萬物之所從始也，元者辭之所謂大也。〔二〕謂一為元者，視大始而欲正本也。〔三〕春秋深探其本，而反自貴者始。故為人君者，正心以正朝廷，正朝廷以正百官，正百官以正萬民，正萬民以正四方。四方正，遠近莫敢不壹於正，而亡有邪氣奸其間者。〔四〕是以陰陽調而風雨時，群生和而萬民殖，五穀孰而草木茂，天地之間被潤澤而大豐美，四海之內聞盛德而皆徠臣，諸福之物，可致之祥，莫不畢至，而王道終矣。","sentenceOrder":71},
  {"id":"s_work_han_thu_67_72","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「釋公始即位何不稱一年而言元年也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_67_73","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「易稱『元者善之長也』，故曰辭之所謂大也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_67_74","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「視讀曰示。」","sentenceOrder":74},
  {"id":"s_work_han_thu_67_75","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「奸，犯也，音干。」","sentenceOrder":75},
  {"id":"s_work_han_thu_67_76","chapterId":"ch_work_han_thu_67","textTraditional":"孔子曰：「鳳鳥不至，河不出圖，吾已矣夫！」〔一〕自悲可致此物，而身卑賤不得致也。〔二〕今陛下貴為天子，富有四海，居得致之位，操可致之勢，〔三〕又有能致之資，〔四〕行高而恩厚，知明而意美，愛民而好士，可謂誼主矣。然而天地未應而美祥莫至者，何也？凡以教化不立而萬民不正也。夫萬民之從利也，如水之走下，〔五〕不以教化隄防之，不能止也。是故教化立而姦邪皆止者，其隄防完也；教化廢而姦邪並出，刑罰不能勝者，其隄防壞也。古之王者明於此，是故南面而治天下，莫不以教化為大務。立大學以教於國，設庠序以化於邑，〔六〕漸民以仁，摩民以誼，〔七〕節民以禮，故其刑罰甚輕而禁不犯者，教化行而習俗美也。","sentenceOrder":76},
  {"id":"s_work_han_thu_67_77","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「論語載孔子之言。」","sentenceOrder":77},
  {"id":"s_work_han_thu_67_78","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「鳳鳥河圖，皆王者之瑞。仲尼自歎有德無位，故不至也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_67_79","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「操，執持也，音千高反。」","sentenceOrder":79},
  {"id":"s_work_han_thu_67_80","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「資，材質也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_67_81","chapterId":"ch_work_han_thu_67","textTraditional":"〔五〕　師古曰：「走音奏。」","sentenceOrder":81},
  {"id":"s_work_han_thu_67_82","chapterId":"ch_work_han_thu_67","textTraditional":"〔六〕　師古曰：「庠序，教學之處也，所以養老而行禮焉。禮學記曰『古之教者，家有塾，黨有庠，術有序，國有學』也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_67_83","chapterId":"ch_work_han_thu_67","textTraditional":"〔七〕　師古曰：「漸謂浸潤之，摩謂砥礪之也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_67_84","chapterId":"ch_work_han_thu_67","textTraditional":"聖王之繼亂世也，埽除其跡而悉去之，〔一〕復修教化而崇起之。教化已明，習俗已成，子孫循之，〔二〕行五六百歲尚未敗也。至周之末世，大為亡道，以失天下。秦繼其後，獨不能改，又益甚之，重禁文學，不得挾書，棄捐禮誼而惡聞之，其心欲盡滅先王之道，而顓為自恣苟簡之治，〔三〕故立為天子十四歲而國破亡矣。自古以來，未嘗有以亂濟亂，大敗天下之民如秦者也。〔四〕其遺毒餘烈，至今未滅，使習俗薄惡，人民嚚頑，抵冒殊扞，〔五〕孰爛如此之甚者也。孔子曰：「腐朽之木不可彫也，糞土之牆不可圬也。」〔六〕今漢繼秦之後，如朽木糞牆矣，雖欲善治之，亡可柰何。法出而姦生，令下而詐起，〔七〕如以湯止沸，抱薪救火，愈甚亡益也。竊譬之琴瑟不調，甚者必解而更張之，乃可鼓也；為政而不行，甚者必變而更化之，乃可理也。當更張而不更張，雖有良工不能善調也；當更化而不更化，雖有大賢不能善治也。故漢得天下以來，常欲善治而至今不可善治者，失之於當更化而不更化也。古人有言曰：「臨淵羨魚，不如（蛛）〔退〕而結網。」〔八〕今臨政而願治七十餘歲矣，不如退而更化；更化則可善治，善治則災害日去，福祿日來。詩云：「宜民宜人，受祿于天。」〔九〕為政而宜於民者，固當受祿于天。夫仁誼禮知信五常之道，王者所當脩飭也；五者脩飭，故受天之祐，而享鬼神之靈，德施于方外，延及群生也。","sentenceOrder":84},
  {"id":"s_work_han_thu_67_85","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「去亦除也，音丘呂反。」","sentenceOrder":85},
  {"id":"s_work_han_thu_67_86","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「循，順也，順而行之。」","sentenceOrder":86},
  {"id":"s_work_han_thu_67_87","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　蘇林曰：「苟為簡易之治也。」師古曰：「此說非也。苟謂苟於權利也，簡謂簡於仁義也。簡易乾坤之德，豈秦所行乎？顓與專同。」","sentenceOrder":87},
  {"id":"s_work_han_thu_67_88","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「濟，益也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_67_89","chapterId":"ch_work_han_thu_67","textTraditional":"〔五〕　文穎曰：「扞，突也。」師古曰：「口不道忠信之言為嚚。心不則德義之經為頑。抵，觸也。冒，犯也。殊，絕也。扞，距也。冒讀如字，又音莫克反。」","sentenceOrder":89},
  {"id":"s_work_han_thu_67_90","chapterId":"ch_work_han_thu_67","textTraditional":"〔六〕　師古曰：「論語載孔子之言也。圬，鏝也，所以泥飾牆也。言內質敗壞不（能）〔可〕修治也。圬音一胡反。鏝音莫干反。」","sentenceOrder":90},
  {"id":"s_work_han_thu_67_91","chapterId":"ch_work_han_thu_67","textTraditional":"〔七〕　師古曰：「下音胡亞反。」","sentenceOrder":91},
  {"id":"s_work_han_thu_67_92","chapterId":"ch_work_han_thu_67","textTraditional":"〔八〕　師古曰：「言當自求之。」","sentenceOrder":92},
  {"id":"s_work_han_thu_67_93","chapterId":"ch_work_han_thu_67","textTraditional":"〔九〕　師古曰：「大雅假樂之詩也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_67_94","chapterId":"ch_work_han_thu_67","textTraditional":"天子覽其對而異焉，乃復冊之曰：","sentenceOrder":94},
  {"id":"s_work_han_thu_67_95","chapterId":"ch_work_han_thu_67","textTraditional":"制曰：蓋聞虞舜之時，游於巖郎之上，〔一〕垂拱無為，而天下太平。周文王至於日昃不暇食，〔二〕而宇內亦治。夫帝王之道，豈不同條共貫與？〔三〕何逸勞之殊也？","sentenceOrder":95},
  {"id":"s_work_han_thu_67_96","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　文穎曰：「巖郎，殿下小屋也。」晉灼曰：「堂邊廡巖郎，謂嚴峻之郎也。」師古曰：「晉說是也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_67_97","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「昃亦（昊）〔〈吳，中“口改日”〉〕字。」","sentenceOrder":97},
  {"id":"s_work_han_thu_67_98","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「與讀曰歟。」","sentenceOrder":98},
  {"id":"s_work_han_thu_67_99","chapterId":"ch_work_han_thu_67","textTraditional":"蓋儉者不造玄黃旌旗之飾。及至周室，設兩觀，乘大路，朱干玉戚，八佾陳於庭，〔一〕而頌聲興。夫帝王之道豈異指哉？〔二〕或曰良玉不瑑，〔三〕又曰非文無以輔德，二端異焉。","sentenceOrder":99},
  {"id":"s_work_han_thu_67_100","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「兩觀，謂闕也。大路，玉路之車也。干，盾也。戚，鉞也。朱丹其盾，玉為戚杷也。佾，列也，舞者之行列也。一列八人，天子八列，六十四人也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_67_101","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「言意趣不同。」","sentenceOrder":101},
  {"id":"s_work_han_thu_67_102","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「瑑謂彫刻為文也，音篆。下皆類此。」","sentenceOrder":102},
  {"id":"s_work_han_thu_67_103","chapterId":"ch_work_han_thu_67","textTraditional":"殷人執五刑以督姦，傷肌膚以懲惡。〔一〕成康不式，四十餘年〔二〕天下不犯，囹圄空虛。秦國用之，死者甚眾，刑者相望，秏矣哀哉！〔三〕","sentenceOrder":103},
  {"id":"s_work_han_thu_67_104","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「督，視責也。懲，止也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_67_105","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「式，用也。成康之時刑措不用。」","sentenceOrder":105},
  {"id":"s_work_han_thu_67_106","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「秏，虛也。言用刑酷烈，誅殺甚眾，天下空虛也。秏音呼到反。或曰秏，不明也，言刑罰闇亂，音莫報反。」","sentenceOrder":106},
  {"id":"s_work_han_thu_67_107","chapterId":"ch_work_han_thu_67","textTraditional":"烏虖！〔一〕朕夙寤晨興，〔二〕惟前帝王之憲，〔三〕永思所以奉至尊，章洪業，〔四〕皆在力本任賢。〔五〕今朕親耕藉田以為農先，勸孝弟，崇有德，使者冠蓋相望，問勤勞，恤孤獨，盡思極神，功烈休德未始云獲也。今陰陽錯繆，氛氣充塞，〔六〕群生寡遂，黎民未濟，〔七〕廉恥貿亂，賢不肖渾（淆）〔殽〕，〔八〕未得其真，故詳延特起之士，（意）庶幾乎！〔九〕今子大夫待詔百有餘人，或道世務而未濟，稽諸上古之不同，考之于今而難行，毋乃牽於文繫而不得騁（歟）〔與〕？〔一０〕將所繇異術，所聞殊方與？〔一一〕各悉對，著于篇，〔一二〕毋諱有司。〔一三〕明其指略，切磋究之，以稱朕意。〔一四〕","sentenceOrder":107},
  {"id":"s_work_han_thu_67_108","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「虖讀曰呼。」","sentenceOrder":108},
  {"id":"s_work_han_thu_67_109","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「夙，早也。寤，寐之覺也。興，起也。覺音工孝反。」","sentenceOrder":109},
  {"id":"s_work_han_thu_67_110","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「憲，法也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_67_111","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「永，深也。章，明也。洪，大也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_67_112","chapterId":"ch_work_han_thu_67","textTraditional":"〔五〕　師古曰：「力本，謂勤力行於本業也。本謂農也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_67_113","chapterId":"ch_work_han_thu_67","textTraditional":"〔六〕　師古曰：「氛，惡氣也。充，滿也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_67_114","chapterId":"ch_work_han_thu_67","textTraditional":"〔七〕　師古曰：「遂，成也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_67_115","chapterId":"ch_work_han_thu_67","textTraditional":"〔八〕　師古曰：「貿，易也。渾殽，雜也。貿音武又反。渾音胡本反。」","sentenceOrder":115},
  {"id":"s_work_han_thu_67_116","chapterId":"ch_work_han_thu_67","textTraditional":"〔九〕　師古曰：「詳，盡也，一曰審也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_67_117","chapterId":"ch_work_han_thu_67","textTraditional":"〔一０〕師古曰：「牽於文繫，謂懼於文吏之法。與讀曰歟。其下類此。」","sentenceOrder":117},
  {"id":"s_work_han_thu_67_118","chapterId":"ch_work_han_thu_67","textTraditional":"〔一一〕師古曰：「繇讀與由同。方謂道也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_67_119","chapterId":"ch_work_han_thu_67","textTraditional":"〔一二〕師古曰：「悉謂盡意而對也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_67_120","chapterId":"ch_work_han_thu_67","textTraditional":"〔一三〕師古曰：「言不當忌畏有司而不極言。」","sentenceOrder":120},
  {"id":"s_work_han_thu_67_121","chapterId":"ch_work_han_thu_67","textTraditional":"〔一四〕師古曰：「究，極也。磋音千何反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_67_122","chapterId":"ch_work_han_thu_67","textTraditional":"仲舒對曰：","sentenceOrder":122},
  {"id":"s_work_han_thu_67_123","chapterId":"ch_work_han_thu_67","textTraditional":"臣聞堯受命，以天下為憂，而未以位為樂也，故誅逐亂臣，務求賢聖，是以得舜、禹、稷、卨、咎繇。眾聖輔德，賢能佐職，教化大行，天下和洽，萬民皆安仁樂誼，各得其宜，動作應禮，從容中道。〔一〕故孔子曰「如有王者，必世而後仁」，此之謂也。〔二〕堯在位七十載，乃遜于位以禪虞舜。堯崩，天下不歸堯子丹朱而歸舜。舜知不可辟，〔三〕乃即天子之位，以禹為相，因堯之輔佐，繼其統業，是以垂拱無為而天下治。孔子曰「韶盡美矣，又盡善（也）〔矣〕」，〔四〕此之謂也。至於殷紂，逆天暴物，殺戮賢知，殘賊百姓。伯夷、太公皆當世賢者，隱處而不為臣。守職之人皆奔走逃亡，入于河海。〔五〕天下秏亂，萬民不安，〔六〕故天下去殷而從周。文王順天理物，師用賢聖，是以閎夭、大顛、散宜生等亦聚於朝廷。〔七〕受施兆民，天下歸之，故太公起海濱而即三公也。〔八〕當此之時，紂尚在上，尊卑昏亂，百姓散亡，故文王悼痛而欲安之，是以日昃而不暇食也。孔子作春秋，先正王而繫萬事，見素王之文焉〔九〕。繇此觀之，〔一０〕帝王之條貫同，然而勞逸異者，所遇之時異也。孔子曰「武盡美矣，未盡善也」，〔一一〕此之謂也。","sentenceOrder":123},
  {"id":"s_work_han_thu_67_124","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「從音千容反。中音竹仲反。」","sentenceOrder":124},
  {"id":"s_work_han_thu_67_125","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「論語載孔子之言也。言如有受命王者，必三十年，仁政乃成。」","sentenceOrder":125},
  {"id":"s_work_han_thu_67_126","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「辟讀曰避。」","sentenceOrder":126},
  {"id":"s_work_han_thu_67_127","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「論語載孔子之言。韶，舜樂也。孔子嘉舜之德，故聽其樂，而云盡善盡美矣。」","sentenceOrder":127},
  {"id":"s_work_han_thu_67_128","chapterId":"ch_work_han_thu_67","textTraditional":"〔五〕　師古曰：「謂若鼓方叔、播鼗武、少師陽之屬也。事在禮樂志。」","sentenceOrder":128},
  {"id":"s_work_han_thu_67_129","chapterId":"ch_work_han_thu_67","textTraditional":"〔六〕　師古曰：「秏，不明也，音莫報反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_67_130","chapterId":"ch_work_han_thu_67","textTraditional":"〔七〕　臣瓚曰：「皆文王賢臣。」","sentenceOrder":130},
  {"id":"s_work_han_thu_67_131","chapterId":"ch_work_han_thu_67","textTraditional":"〔八〕　師古曰：「濱，涯也。即，就也。濱音賓，又音頻。」","sentenceOrder":131},
  {"id":"s_work_han_thu_67_132","chapterId":"ch_work_han_thu_67","textTraditional":"〔九〕　師古曰：「見，顯示也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_67_133","chapterId":"ch_work_han_thu_67","textTraditional":"〔一０〕師古曰：「繇讀與由同。」","sentenceOrder":133},
  {"id":"s_work_han_thu_67_134","chapterId":"ch_work_han_thu_67","textTraditional":"〔一一〕師古曰：「亦論語載孔子之言也。武，周武王樂也。以其用兵伐紂，故有慚德，未盡善也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_67_135","chapterId":"ch_work_han_thu_67","textTraditional":"臣聞制度文采玄黃之飾，所以明尊卑，異貴賤，而勸有德也。故春秋受命所先制者，改正朔，易服色，所以應天也。然則宮室旌旗之制，有法而然者也。故孔子曰：「奢則不遜，儉則固。」〔一〕儉非聖人之中制也。臣聞良玉不瑑，資質潤美，不待刻瑑，此亡異於達巷黨人不學而自知也。〔二〕然則常玉不瑑，不成文章；君子不學，不成其德。","sentenceOrder":135},
  {"id":"s_work_han_thu_67_136","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「論語載孔子之言。遜，順也。固，陋也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_67_137","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　孟康曰：「人，項橐也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_67_138","chapterId":"ch_work_han_thu_67","textTraditional":"臣聞聖王之治天下也，少則習之學，長則材諸位，〔一〕爵祿以養其德，刑罰以威其惡，故民曉於禮誼而恥犯其上。武王行大誼，平殘賊，周公作禮樂以文之，至於成康之隆，囹圄空虛四十餘年，此亦教化之漸而仁誼之流，非獨傷肌膚之效也。至秦則不然。師申商之法，行韓非之說，〔二〕憎帝王之道，以貪狼為俗，〔三〕非有文德以教訓於（天）下也。誅名而不察實，〔四〕為善者不必免，而犯惡者未必刑也。是以百官皆飾（空言）虛辭而不顧實，外有事君之禮，內有背上之心，造偽飾詐，趣利無恥；又好用憯酷之吏，〔五〕賦斂亡度，竭民財力，百姓散亡，不得從耕織之業，群盜並起。是以刑者甚眾，死者相望，而姦不息，俗化使然也。故孔子曰「導之以政，齊之以刑，民免而無恥」，〔六〕此之謂也。","sentenceOrder":138},
  {"id":"s_work_han_thu_67_139","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　服虔曰：「在位當知材知日有益於政也。」應劭曰：「隨其材之優劣而授之位也。」師古曰：「應說近之。謂授之位以試其材也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_67_140","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「申，申不害也。商，商鞅也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_67_141","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「狼性皆貪，故謂貪為貪狼也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_67_142","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「誅，責也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_67_143","chapterId":"ch_work_han_thu_67","textTraditional":"〔五〕　師古曰：「憯，痛也，音千感反。」","sentenceOrder":143},
  {"id":"s_work_han_thu_67_144","chapterId":"ch_work_han_thu_67","textTraditional":"〔六〕　師古曰：「論語載孔子之言也。言以政法教導之，以刑戮整齊之，則人苟免而已，無恥愧也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_67_145","chapterId":"ch_work_han_thu_67","textTraditional":"今陛下并有天下，海內莫不率服，廣覽兼聽，極群下之知，盡天下之美，至德昭然，施於方外。夜郎、康居，殊方萬里，說德歸誼，〔一〕此太平之致也。然而功不加於百姓者，殆王心未加焉。曾子曰：「尊其所聞，則高明矣；行其所知，則光大矣。高明光大，不在於它，在乎加之意而已。」〔二〕願陛下因用所聞，設誠於內而致行之，則三王何異哉！","sentenceOrder":145},
  {"id":"s_work_han_thu_67_146","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「夜郎，西南夷也。康居，西域國也。說讀曰悅。」","sentenceOrder":146},
  {"id":"s_work_han_thu_67_147","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「曾子之書也。曾子，曾參。」","sentenceOrder":147},
  {"id":"s_work_han_thu_67_148","chapterId":"ch_work_han_thu_67","textTraditional":"陛下親耕藉田以為農先，夙寤晨興，憂勞萬民，思惟往古，而務以求賢，此亦堯舜之用心也，然而未云獲者，士素不厲也。〔一〕夫不素養士而欲求賢，譬猶不（瑑）〔琢〕玉而求文采也。故養士之大者，莫大（虐）〔虖〕太學；太學者，賢士之所關也，〔二〕教化之本原也。今以一郡一國之眾，對亡應書者，〔三〕是王道往往而絕也。臣願陛下興太學，置明師，以養天下之士，數考問以盡其材，則英俊宜可得矣。今之郡守、縣令，民之師帥，所使承流而宣化也；故師帥不賢，則主德不宣，恩澤不流。今吏既亡教訓於下，或不承用主上之法，暴虐百姓，與姦為市，〔四〕貧窮孤弱，冤苦失職，甚不稱陛下之意。是以陰陽錯繆，氛氣充塞，群生寡遂，黎民未濟，皆長吏不明，使至於此也。","sentenceOrder":148},
  {"id":"s_work_han_thu_67_149","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「厲謂勸勉之也。一曰砥礪其行也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_67_150","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「關，由也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_67_151","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「書謂舉賢良文學之詔書也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_67_152","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「言小吏有為姦欺者，守令不舉，乃反與之交易求利也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_67_153","chapterId":"ch_work_han_thu_67","textTraditional":"夫長吏多出於郎中、中郎，吏二千石子弟選郎吏，又以富訾，未必賢也。〔一〕且古所謂功者，以任官稱職為差，〔二〕非（所）謂積日絫久也。故小材雖絫日，不離於小官；賢材雖未久，不害為輔佐。〔三〕是以有司竭力盡知，務治其業而以赴功。今則不然。（累）〔絫〕日以取貴，積久以致官，是以廉恥貿亂，賢不肖渾殽，未得其真。臣愚以為使諸列侯、郡守、二千石各擇其吏民之賢者，歲貢各二人以給宿衛，且以觀大臣之能；所貢賢者有賞，所貢不肖者有罰。夫如是，諸侯、吏二千石皆盡心於求賢，天下之士可得而官使也。〔四〕遍得天下之賢人，則三王之盛易為，而堯舜之名可及也。毋以日月為功，實試賢能為上，量材而授官，錄德而定位，〔五〕則廉恥殊路，賢不肖異處矣。陛下加惠，寬臣之罪，令勿牽制於文，使得切磋究之，臣敢不盡愚！","sentenceOrder":153},
  {"id":"s_work_han_thu_67_154","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「訾與資同。」","sentenceOrder":154},
  {"id":"s_work_han_thu_67_155","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「差，次也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_67_156","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「害猶妨也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_67_157","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「授之以官，以使其材也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_67_158","chapterId":"ch_work_han_thu_67","textTraditional":"〔五〕　師古曰：「錄謂存視也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_67_159","chapterId":"ch_work_han_thu_67","textTraditional":"於是天子復冊之。","sentenceOrder":159},
  {"id":"s_work_han_thu_67_160","chapterId":"ch_work_han_thu_67","textTraditional":"制曰：蓋聞「善言天者必有徵於人，〔一〕善言古者必有驗於今」。故朕垂問乎天人之應，上嘉唐虞，下悼桀紂，寖微寖滅寖明寖昌之道，〔二〕虛心以改。今子大夫明於陰陽所以造化，習於先聖之道業，然而文采未極，豈惑虖當世之務哉？條貫靡竟，統紀未終，意朕之不明與？聽若眩與？〔三〕夫三王之教所祖不同，而皆有失，〔四〕或謂久而不易者道也，意豈異哉？今子大夫既已著大道之極，陳治亂之端矣，其悉之究之，孰之復之。〔五〕詩不云虖？「嗟爾君子，毋常安息，神之聽之，介爾景福。」〔六〕朕將親覽焉，子大夫其茂明之。〔七〕","sentenceOrder":160},
  {"id":"s_work_han_thu_67_161","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「徵，證也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_67_162","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「寖，古浸字。寖，漸也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_67_163","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「眩，惑也，音郡縣之縣。與讀皆曰歟。」","sentenceOrder":163},
  {"id":"s_work_han_thu_67_164","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「祖，始也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_67_165","chapterId":"ch_work_han_thu_67","textTraditional":"〔五〕　師古曰：「悉，盡也。究，竟也。復，反復重言之也。復音扶目反。」","sentenceOrder":165},
  {"id":"s_work_han_thu_67_166","chapterId":"ch_work_han_thu_67","textTraditional":"〔六〕　師古曰：「小雅小明之詩也。安息，安處也。介，助也。景，大也。言人君不當苟自安處而已，若能靖恭其位，直道而行，則神聽而知之，助以大福也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_67_167","chapterId":"ch_work_han_thu_67","textTraditional":"〔七〕　師古曰：「茂，勉也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_67_168","chapterId":"ch_work_han_thu_67","textTraditional":"仲舒復對曰：","sentenceOrder":168},
  {"id":"s_work_han_thu_67_169","chapterId":"ch_work_han_thu_67","textTraditional":"臣聞論語曰：「有始有卒者，其唯聖人虖！」〔一〕今陛下幸加惠，留聽於承學之臣，〔二〕復下明冊，以切其意，而究盡聖德，非愚臣之所能具也。前所上對，條貫靡竟，統紀不終，辭不別白，指不分明，此臣淺陋之罪也。","sentenceOrder":169},
  {"id":"s_work_han_thu_67_170","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「論語載孔子之言。卒，終也，言終始如一者，唯聖人能之。」","sentenceOrder":170},
  {"id":"s_work_han_thu_67_171","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「言轉承師說而學之，蓋謙辭也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_67_172","chapterId":"ch_work_han_thu_67","textTraditional":"冊曰：「善言天者必有徵於人，善言古者必有驗於今。」臣聞天者群物之祖也，故遍覆包函而無所殊，〔一〕建日月風雨以和之，經陰陽寒暑以成之。故聖人法天而立道，亦溥愛而亡私，〔二〕布德施仁以厚之，設誼立禮以導之。春者天之所以生也，仁者君之所以愛也；夏者天之所以長也，德者君之所以養也；霜者天之所以殺也，刑者君之所以罰也。繇此言之，〔三〕天人之徵，古今之道也。孔子作春秋，上揆之天道，下質諸人情，參之於古，考之於今。故春秋之所譏，災害之所加也；春秋之所惡，怪異之所施也。書邦家之過，兼災異之變，以此見人之所為，其美惡之極，乃與天地流通而往來相應，此亦言天之一端也。古者修教訓之官，務以德善化民，民已大化之後，天下常亡一人之獄矣。今世廢而不脩，亡以化民，民以故棄行誼而死財利，是以犯法而罪多，一歲之獄以萬千數。以此見古之不可不用也，〔四〕故春秋變古則譏之。天令之謂命，命非聖人不行；質樸之謂性，性非教化不成；人欲之謂情，情非度制不節。是故王者上謹於承天意，以順命也；下務明教化民，以成性也；正法度之宜，別上下之序，以防欲也：脩此三者，而大本舉矣。人受命於天，固超然異於群生，入有父子兄弟之親，出有君臣上下之誼，會聚相遇，則有耆老長幼之施；〔五〕粲然有文以相接，〔六〕驩然有恩以相愛，此人之所以貴也。生五穀以食之，桑麻以衣之，〔七〕六畜以養之，服牛乘馬，圈豹檻虎，是其得天之靈，貴於物也。故孔子曰：「天地之性人為貴。」〔八〕明於天性，知自貴於物；知自貴於物，然後知仁誼；知仁誼，然後重禮節；重禮節，然後安處善；〔九〕安處善，然後樂循理；〔一０〕樂循理，然後謂之君子。故孔子曰「不知命，亡以為君子」，〔一一〕此之謂也。","sentenceOrder":172},
  {"id":"s_work_han_thu_67_173","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「函與含同。殊，異也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_67_174","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「溥，遍也，音普。」","sentenceOrder":174},
  {"id":"s_work_han_thu_67_175","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「繇讀與由同。下皆類此。」","sentenceOrder":175},
  {"id":"s_work_han_thu_67_176","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「古謂古法也。」","sentenceOrder":176},
  {"id":"s_work_han_thu_67_177","chapterId":"ch_work_han_thu_67","textTraditional":"〔五〕　師古曰：「施，設也，陳設其序。」","sentenceOrder":177},
  {"id":"s_work_han_thu_67_178","chapterId":"ch_work_han_thu_67","textTraditional":"〔六〕　師古曰：「粲，明貌。」","sentenceOrder":178},
  {"id":"s_work_han_thu_67_179","chapterId":"ch_work_han_thu_67","textTraditional":"〔七〕　師古曰：「食讀曰飤。衣音於既反。」","sentenceOrder":179},
  {"id":"s_work_han_thu_67_180","chapterId":"ch_work_han_thu_67","textTraditional":"〔八〕　師古曰：「孝經載孔子之言也。性，生也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_67_181","chapterId":"ch_work_han_thu_67","textTraditional":"〔九〕　師古曰：「處於善道以為安。」","sentenceOrder":181},
  {"id":"s_work_han_thu_67_182","chapterId":"ch_work_han_thu_67","textTraditional":"〔一０〕師古曰：「循，順也。」","sentenceOrder":182},
  {"id":"s_work_han_thu_67_183","chapterId":"ch_work_han_thu_67","textTraditional":"〔一一〕師古曰：「論語載孔子之言也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_67_184","chapterId":"ch_work_han_thu_67","textTraditional":"冊曰：「上嘉唐虞，下悼桀紂，寖微寖滅寖明寖昌之道，虛心以改。」臣聞眾少成多，積小致鉅，〔一〕故聖人莫不以晻致明，以微致顯。〔二〕是以堯發於諸侯，〔三〕舜興虖深山，〔四〕非一日而顯也，蓋有漸以致之矣。言出於己，不可塞也；行發於身，不可掩也。言行，治之大者，君子之所以動天地也。故盡小者大，慎微者著。〔五〕詩云：「惟此文王，小心翼翼。」〔六〕故堯兢兢日行其道，而舜業業日致其孝，〔七〕善積而名顯，德章而身尊，此其寖明寖昌之道也。積善在身，猶長日加益，而人不知也；〔八〕積惡在身，猶火之銷膏，而人不見也。非明虖情性察虖流俗者，孰能知之？此唐虞之所以得令名，而桀紂之可為悼懼者也。夫善惡之相從，如景鄉之應形聲也。〔九〕故桀紂暴謾，〔一０〕讒賊並進，賢知隱伏，惡日顯，國日亂，晏然自以如日在天，〔一一〕終陵夷而大壞。夫暴逆不仁者，非一日而亡也，亦以漸至，故桀、紂雖亡道，然猶享國十餘年，此其寖微寖滅之道也。","sentenceOrder":184},
  {"id":"s_work_han_thu_67_185","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「鉅，大也。」","sentenceOrder":185},
  {"id":"s_work_han_thu_67_186","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「晻與暗同。」","sentenceOrder":186},
  {"id":"s_work_han_thu_67_187","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「謂從唐侯升天子之位。」","sentenceOrder":187},
  {"id":"s_work_han_thu_67_188","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　孟康曰：「舜耕於歷山。」","sentenceOrder":188},
  {"id":"s_work_han_thu_67_189","chapterId":"ch_work_han_thu_67","textTraditional":"〔五〕　師古曰：「能盡眾小，則致高大；能慎至微，則著明也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_67_190","chapterId":"ch_work_han_thu_67","textTraditional":"〔六〕　師古曰：「大雅大明之詩也。翼翼，恭肅貌。」","sentenceOrder":190},
  {"id":"s_work_han_thu_67_191","chapterId":"ch_work_han_thu_67","textTraditional":"〔七〕　師古曰：「兢兢，戒慎也。業業，危懼也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_67_192","chapterId":"ch_work_han_thu_67","textTraditional":"〔八〕　師古曰：「長言身形之脩短，自幼及壯也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_67_193","chapterId":"ch_work_han_thu_67","textTraditional":"〔九〕　師古曰：「鄉讀曰響。」","sentenceOrder":193},
  {"id":"s_work_han_thu_67_194","chapterId":"ch_work_han_thu_67","textTraditional":"〔一０〕師古曰：「謾與慢同。」","sentenceOrder":194},
  {"id":"s_work_han_thu_67_195","chapterId":"ch_work_han_thu_67","textTraditional":"〔一一〕師古曰：「晏然，自安意也。如日在天，言終不墜亡也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_67_196","chapterId":"ch_work_han_thu_67","textTraditional":"冊曰：「三王之教所祖不同，而皆有失，或謂久而不易者道也，意豈異哉？」臣聞夫樂而不亂復而不厭者謂之道；〔一〕道者萬世亡弊，弊者道之失也。〔二〕先王之道必有偏而不起之處，故政有眊而不行，〔三〕舉其偏者以補其弊而已矣。三王之道所祖不同，非其相反，將以捄溢扶衰，所遭之變然也。〔四〕故孔子曰：「亡為而治者，其舜虖！」〔五〕改正朔，易服色，以順天命而已；其餘盡循堯道，何更為哉！故王者有改制之名，亡變道之實。然夏上忠，殷上敬，周上文者，所繼之捄，當用此也。〔六〕孔子曰：「殷因於夏禮，所損益可知也；周因於殷禮，所損益可知也；其或繼周者，雖百世可知也。」〔七〕此言百王之用，以此三者矣。夏因於虞，而獨不言所損益者，其道如一而所上同也。道之大原出於天，天不變，道亦不變，是以禹繼舜，舜繼堯，三聖相受而守一道，亡救弊之政也，〔八〕故不言其所損益也。繇是觀之，繼治世者其道同，繼亂世者其道變。今漢繼大亂之後，若宜少損周之文致，〔九〕用夏之忠者。","sentenceOrder":196},
  {"id":"s_work_han_thu_67_197","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「復謂反復行之也，音扶目反。」","sentenceOrder":197},
  {"id":"s_work_han_thu_67_198","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「言有弊非道，由失道故有弊。」","sentenceOrder":198},
  {"id":"s_work_han_thu_67_199","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「眊，不明也，音莫報反。」","sentenceOrder":199},
  {"id":"s_work_han_thu_67_200","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「捄，古救字。」","sentenceOrder":200},
  {"id":"s_work_han_thu_67_201","chapterId":"ch_work_han_thu_67","textTraditional":"〔五〕　師古曰：「論語載孔子之言。」","sentenceOrder":201},
  {"id":"s_work_han_thu_67_202","chapterId":"ch_work_han_thu_67","textTraditional":"〔六〕　師古曰：「繼謂所受先代之次也。救謂救其弊也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_67_203","chapterId":"ch_work_han_thu_67","textTraditional":"〔七〕　師古曰：「論語載孔子之言。謂忠敬與文因循為教，立政垂則，不遠此也。」","sentenceOrder":203},
  {"id":"s_work_han_thu_67_204","chapterId":"ch_work_han_thu_67","textTraditional":"〔八〕　師古曰：「言政和平，不須救弊也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_67_205","chapterId":"ch_work_han_thu_67","textTraditional":"〔九〕　師古曰：「致，至極也。」","sentenceOrder":205},
  {"id":"s_work_han_thu_67_206","chapterId":"ch_work_han_thu_67","textTraditional":"陛下有明德嘉道，愍世俗之靡薄，悼王道之不昭，〔一〕故舉賢良方正之士，論（誼）〔議〕考問，將欲興仁誼之休德，明帝王之法制，〔二〕建太平之道也。臣愚不肖，述所聞，誦所學，道師之言，厪能勿失耳。〔三〕若乃論政事之得失，察天下之息秏，〔四〕此大臣輔佐之職，三公九卿之任，非臣仲舒所能及也。然而臣竊有怪者。夫古之天下亦今之天下，今之天下亦古之天下，共是天下，古（亦）〔以〕大治，上下和睦，習俗美盛，不令而行，不禁而止，吏亡姦邪，民亡盜賊，囹圄空虛，德潤草木，澤被四海，鳳皇來集，麒麟來游，以古準今，壹何不相逮之遠也！安所繆盭而陵夷若是？〔五〕意者有所失於古之道與？有所詭於天之理與？〔六〕試跡之〔於〕古，返之於天，黨可得見乎。〔七〕","sentenceOrder":206},
  {"id":"s_work_han_thu_67_207","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「靡，散也。薄，輕也。昭，明也。」","sentenceOrder":207},
  {"id":"s_work_han_thu_67_208","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「休，美也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_67_209","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「厪與僅同。僅，少也。」","sentenceOrder":209},
  {"id":"s_work_han_thu_67_210","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「息，生也。秏，虛也。秏音呼到反。」","sentenceOrder":210},
  {"id":"s_work_han_thu_67_211","chapterId":"ch_work_han_thu_67","textTraditional":"〔五〕　師古曰：「安，焉也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_67_212","chapterId":"ch_work_han_thu_67","textTraditional":"〔六〕　師古曰：「與讀皆曰歟。詭，違也。」","sentenceOrder":212},
  {"id":"s_work_han_thu_67_213","chapterId":"ch_work_han_thu_67","textTraditional":"〔七〕　師古曰：「（反）〔返〕謂還歸之也。黨音他朗反。」","sentenceOrder":213},
  {"id":"s_work_han_thu_67_214","chapterId":"ch_work_han_thu_67","textTraditional":"夫天亦有所分予，予之齒者去其角，〔一〕傅其翼者兩其足，〔二〕是所受大者不得取小也。古之所予祿者，不食於力，不動於末，〔三〕是亦受大者不得取小，與天同意者也。夫已受大，又取小，天不能足，而況人乎！此民之所以囂囂苦不足也。〔四〕身寵而載高位，家溫而食厚祿，〔五〕因乘富貴之資力，以與民爭利於下，民安能如之哉！是故眾其奴婢，多其牛羊，廣其田宅，博其產業，畜其積委，〔六〕務此而亡已，以迫蹴民，〔七〕民日削月朘，〔八〕寖以大窮。富者奢侈羨溢，貧者窮急愁苦；〔九〕窮急愁苦而上不救，則民不樂生；民不樂生，尚不避死，安能避罪！此刑罰之所以蕃而姦邪不可勝者也。〔一０〕故受祿之家，食祿而已，不與民爭業，然後利可均布，而民可家足。此上天之理，而亦太古之道，天子之所宜法以為制，大夫之所當循以為行也。故公儀子相魯，〔一一〕之其家見織帛，怒而出其妻，食於舍而茹葵，慍而拔其葵，〔一二〕曰：「吾已食祿，又奪園夫紅女利虖！」〔一三〕古之賢人君子在列位者皆如是，是故下高其行而從其教，民化其廉而不貪鄙。及至周室之衰，其卿大夫緩於誼而急於利，亡推讓之風而有爭田之訟。故詩人疾而刺之，曰：「節彼南山，惟石巖巖，赫赫師尹，民具爾瞻。」〔一四〕爾好誼，則民鄉仁而俗善；〔一五〕爾好利，則民好邪而俗敗。由是觀之，天子大夫者，下民之所視效，遠方之所四面而內望也。近者視而放之，遠者望而效之，〔一六〕豈可以居賢人之位而為庶人行哉！夫皇皇求財利常恐乏匱者，庶人之意也；〔一七〕皇皇求仁義常恐不能化民者，大夫之意也。易曰：「負且乘，致寇至。」〔一八〕乘車者君子之位也，負擔者小人之事也，此言居君子之位而為庶人之行者，其患禍必至也。若居君子之位，當君子之行，則舍公儀休之相魯，亡可為者矣。〔一九〕","sentenceOrder":214},
  {"id":"s_work_han_thu_67_215","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「謂牛無上齒則有角，其餘無角者則有上齒。」","sentenceOrder":215},
  {"id":"s_work_han_thu_67_216","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「傅讀曰附。附，箸也。言鳥不四足。」","sentenceOrder":216},
  {"id":"s_work_han_thu_67_217","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「末謂工商之業也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_67_218","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「囂讀與嗷同，音敖。嗷嗷，眾怨愁聲也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_67_219","chapterId":"ch_work_han_thu_67","textTraditional":"〔五〕　師古曰：「載亦乘也。」","sentenceOrder":219},
  {"id":"s_work_han_thu_67_220","chapterId":"ch_work_han_thu_67","textTraditional":"〔六〕　師古曰：「畜讀曰蓄。」","sentenceOrder":220},
  {"id":"s_work_han_thu_67_221","chapterId":"ch_work_han_thu_67","textTraditional":"〔七〕　師古曰：「蹴音子育反。」","sentenceOrder":221},
  {"id":"s_work_han_thu_67_222","chapterId":"ch_work_han_thu_67","textTraditional":"〔八〕　孟康曰：「朘音揎，謂轉褰踧也。」蘇林曰：「朘音鐫石。俗語謂縮肭為朘縮。」師古曰：「孟說是也。揎音宣。踧音子六反。」","sentenceOrder":222},
  {"id":"s_work_han_thu_67_223","chapterId":"ch_work_han_thu_67","textTraditional":"〔九〕　師古曰：「羨，饒也，讀與衍同，音弋戰反。」","sentenceOrder":223},
  {"id":"s_work_han_thu_67_224","chapterId":"ch_work_han_thu_67","textTraditional":"〔一０〕師古曰：「蕃，多也，音扶元反。」","sentenceOrder":224},
  {"id":"s_work_han_thu_67_225","chapterId":"ch_work_han_thu_67","textTraditional":"〔一一〕師古曰：「公儀休。」","sentenceOrder":225},
  {"id":"s_work_han_thu_67_226","chapterId":"ch_work_han_thu_67","textTraditional":"〔一二〕師古曰：「食菜曰茹，音（洳）〔汝〕。」","sentenceOrder":226},
  {"id":"s_work_han_thu_67_227","chapterId":"ch_work_han_thu_67","textTraditional":"〔一三〕師古曰：「紅讀曰工。」","sentenceOrder":227},
  {"id":"s_work_han_thu_67_228","chapterId":"ch_work_han_thu_67","textTraditional":"〔一四〕師古曰：「小雅節南山之詩也。節，高峻貌，巖巖，積石貌。赫赫，顯盛也。師尹，周太師尹氏也。言三公之位，人所瞻仰，若山之高也。節音才結反。」","sentenceOrder":228},
  {"id":"s_work_han_thu_67_229","chapterId":"ch_work_han_thu_67","textTraditional":"〔一五〕師古曰：「爾，汝也。鄉讀曰嚮。」","sentenceOrder":229},
  {"id":"s_work_han_thu_67_230","chapterId":"ch_work_han_thu_67","textTraditional":"〔一六〕師古曰：「放，依也，音甫往反。」","sentenceOrder":230},
  {"id":"s_work_han_thu_67_231","chapterId":"ch_work_han_thu_67","textTraditional":"〔一七〕師古曰：「皇皇，急速之貌也。」","sentenceOrder":231},
  {"id":"s_work_han_thu_67_232","chapterId":"ch_work_han_thu_67","textTraditional":"〔一八〕師古曰：「此易解卦六（二）〔三〕爻辭也。」","sentenceOrder":232},
  {"id":"s_work_han_thu_67_233","chapterId":"ch_work_han_thu_67","textTraditional":"〔一九〕師古曰：「舍，廢也。言為君子之行者，當如公儀休。若廢其所行，則無可為也。」","sentenceOrder":233},
  {"id":"s_work_han_thu_67_234","chapterId":"ch_work_han_thu_67","textTraditional":"春秋大一統者，天地之常經，古今之通誼也。〔一〕今師異道，人異論，百家殊方，指意不同，是以上亡以持一統；法制數變，下不知所守。臣愚以為諸不在六藝之科孔子之術者，皆絕其道，勿使並進。邪辟之說滅息，〔二〕然後統紀可一而法度可明，民知所從矣。","sentenceOrder":234},
  {"id":"s_work_han_thu_67_235","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「一統者，萬物之統皆歸於一也。春秋公羊傳：『隱公元年，春王正月。何言乎王正月？大一統也。』此言諸侯皆繫統天子，不得自專也。」","sentenceOrder":235},
  {"id":"s_work_han_thu_67_236","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「辟讀曰僻。」","sentenceOrder":236},
  {"id":"s_work_han_thu_67_237","chapterId":"ch_work_han_thu_67","textTraditional":"對既畢，天子以仲舒為江都相，事易王。易王，帝兄，素驕，好勇。仲舒以禮誼匡正，王敬重焉。久之，王問仲舒曰：「粵王句踐與大夫泄庸、種、蠡謀伐吳，〔一〕遂滅之。孔子稱殷有三仁，寡人亦以為粵有三仁。〔二〕桓公決疑於管仲，寡人決疑於君。」仲舒對曰：「臣愚不足以奉大對。〔三〕聞昔者魯君問柳下惠：〔四〕『吾欲伐齊，何如？』柳下惠曰：『不可。』歸而有憂色，曰：『吾聞伐國不問仁人，此言何為至於我哉！』徒見問耳，且猶羞之，〔五〕況設詐以伐吳虖？繇此言之，粵本無一仁。夫仁人者，正其誼不謀其利，明其道不計其功，是以仲尼之門，五尺之童羞稱五伯，〔六〕為其先詐力而後仁誼也。苟為詐而已，故不足稱於大君子之門也。〔七〕五伯比於他諸侯為賢，其比三王，猶武夫之與美玉也。」〔八〕王曰：「善。」","sentenceOrder":237},
  {"id":"s_work_han_thu_67_238","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「種，大夫種也。蠡，范蠡也。種音之勇反。蠡音禮。」","sentenceOrder":238},
  {"id":"s_work_han_thu_67_239","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「泄庸一也，大夫種二也，范蠡三也。」","sentenceOrder":239},
  {"id":"s_work_han_thu_67_240","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「大對，謂對大問也。」","sentenceOrder":240},
  {"id":"s_work_han_thu_67_241","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「魯大夫展禽也。柳下，所食（菜）〔采〕邑之名。惠，諡也。」","sentenceOrder":241},
  {"id":"s_work_han_thu_67_242","chapterId":"ch_work_han_thu_67","textTraditional":"〔五〕　師古曰：「徒，但也。」","sentenceOrder":242},
  {"id":"s_work_han_thu_67_243","chapterId":"ch_work_han_thu_67","textTraditional":"〔六〕　師古曰：「伯讀曰霸。次下亦同。」","sentenceOrder":243},
  {"id":"s_work_han_thu_67_244","chapterId":"ch_work_han_thu_67","textTraditional":"〔七〕　張晏曰：「仲尼之門，故稱大也。」","sentenceOrder":244},
  {"id":"s_work_han_thu_67_245","chapterId":"ch_work_han_thu_67","textTraditional":"〔八〕　應劭曰：「武夫，石而似玉者也。」","sentenceOrder":245},
  {"id":"s_work_han_thu_67_246","chapterId":"ch_work_han_thu_67","textTraditional":"仲舒治國，以春秋災異之變推陰陽所以錯行，故求雨，閉諸陽，縱諸陰，其止雨反是；〔一〕行之一國，未嘗不得所欲。中廢為中大夫。先是遼東高廟、長陵高園殿災，仲舒居家推說其意，草稿未上，〔二〕主父偃候仲舒，私見，嫉之，竊其書而奏焉。上召視諸儒〔三〕，仲舒弟子呂步舒不知其師書，以為大愚。於是下仲舒吏，當死，詔赦之。仲舒遂不敢復言災異。","sentenceOrder":246},
  {"id":"s_work_han_thu_67_247","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「謂若閉南門，禁舉火，及開北門，水灑人之類是也。」","sentenceOrder":247},
  {"id":"s_work_han_thu_67_248","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「所作起草為稿也。」","sentenceOrder":248},
  {"id":"s_work_han_thu_67_249","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「視讀曰示。」","sentenceOrder":249},
  {"id":"s_work_han_thu_67_250","chapterId":"ch_work_han_thu_67","textTraditional":"仲舒為人廉直。是時方外攘四夷，〔一〕公孫弘治春秋不如仲舒，而弘希世用事，〔二〕位至公卿。仲舒以弘為從諛，弘嫉之。膠西王亦上兄也，尤縱恣，數害吏二千石。弘乃言於上曰：「獨董仲舒可使相膠西王。」膠西王聞仲舒〔三〕大儒，善待之，仲舒恐久獲罪，病免。凡相兩國，輒事驕王，正身以率下，數上疏諫爭，教令國中，所居而治。及去位歸居，終不問家產業，以修學著書為事。","sentenceOrder":250},
  {"id":"s_work_han_thu_67_251","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「攘，卻也。」","sentenceOrder":251},
  {"id":"s_work_han_thu_67_252","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「希，觀相也。」","sentenceOrder":252},
  {"id":"s_work_han_thu_67_253","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「素聞其賢也。」","sentenceOrder":253},
  {"id":"s_work_han_thu_67_254","chapterId":"ch_work_han_thu_67","textTraditional":"仲舒在家，朝廷如有大議，使使者及廷尉張湯就其家而問之，其對皆有明法。自武帝初立，魏其、武安侯為相而隆儒矣。及仲舒對冊，推明孔氏，抑黜百家。立學校之官，〔一〕州郡舉茂材孝廉，皆自仲舒發之。年老，以壽終於家。家徙茂陵，子及孫皆以學至大官。","sentenceOrder":254},
  {"id":"s_work_han_thu_67_255","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「校音下教反。」","sentenceOrder":255},
  {"id":"s_work_han_thu_67_256","chapterId":"ch_work_han_thu_67","textTraditional":"仲舒所著，皆明經術之意，及上疏條教，凡百二十三篇。而說春秋事得失，聞舉、玉杯、蕃露、清明、竹林之屬，〔一〕復數十篇，十餘萬言，皆傳於後世。掇其切當世施朝廷者著于篇。〔二〕","sentenceOrder":256},
  {"id":"s_work_han_thu_67_257","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「皆其所著書名也。杯音布回反。蕃音扶元反。」","sentenceOrder":257},
  {"id":"s_work_han_thu_67_258","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「掇，采拾也，音丁活反。」","sentenceOrder":258},
  {"id":"s_work_han_thu_67_259","chapterId":"ch_work_han_thu_67","textTraditional":"贊曰：劉向稱「董仲舒有王佐之材，雖伊呂亡以加，〔一〕筦晏之屬，伯者之佐，殆不及也。」〔二〕至向子歆以為「伊呂乃聖人之耦，〔三〕王者不得則不興。故顏淵死，孔子曰『噫！天喪余。〔四〕』唯此一人為能當之，自宰我、子贛、子游、子夏不與焉。〔五〕仲舒遭漢承秦滅學之後，六經離析，下帷發憤，潛心大業，令後學者有所統壹，為群儒首，然考其師友淵源所漸，猶未及乎游夏，〔六〕而曰筦晏弗及，伊呂不加，過矣。」至向曾孫龔，篤論君子也，以歆之言為然。","sentenceOrder":259},
  {"id":"s_work_han_thu_67_260","chapterId":"ch_work_han_thu_67","textTraditional":"〔一〕　師古曰：「伊，伊尹。呂，呂望也。」","sentenceOrder":260},
  {"id":"s_work_han_thu_67_261","chapterId":"ch_work_han_thu_67","textTraditional":"〔二〕　師古曰：「筦，筦仲也。晏，晏嬰也。伯者，齊桓、晉文之屬也。伯讀曰霸。」","sentenceOrder":261},
  {"id":"s_work_han_thu_67_262","chapterId":"ch_work_han_thu_67","textTraditional":"〔三〕　師古曰：「耦，對也。」","sentenceOrder":262},
  {"id":"s_work_han_thu_67_263","chapterId":"ch_work_han_thu_67","textTraditional":"〔四〕　師古曰：「事見論語。噫，歎聲也。言失其輔佐也。噫音於其反。」","sentenceOrder":263},
  {"id":"s_work_han_thu_67_264","chapterId":"ch_work_han_thu_67","textTraditional":"〔五〕　師古曰：「與讀曰豫。」","sentenceOrder":264},
  {"id":"s_work_han_thu_67_265","chapterId":"ch_work_han_thu_67","textTraditional":"〔六〕　師古曰：「漸，浸潤也。游，子游。夏，子夏也。」","sentenceOrder":265},
  {"id":"s_work_han_thu_67_266","chapterId":"ch_work_han_thu_67","textTraditional":"校勘記","sentenceOrder":266},
  {"id":"s_work_han_thu_67_267","chapterId":"ch_work_han_thu_67","textTraditional":"二四九八頁一五行　此皆可使還至而（立）有效者也。　宋祁說越本無「立」字。按景祐本亦無。","sentenceOrder":267},
  {"id":"s_work_han_thu_67_268","chapterId":"ch_work_han_thu_67","textTraditional":"二五０一頁　七行　君子之德風（也），小人之德屮（也），　宋祁說越本無兩「也」字。按景祐本亦無。","sentenceOrder":268},
  {"id":"s_work_han_thu_67_269","chapterId":"ch_work_han_thu_67","textTraditional":"二五０五頁　三行　不如（蛛）〔退〕而結網。　景祐、殿本都作「退」。","sentenceOrder":269},
  {"id":"s_work_han_thu_67_270","chapterId":"ch_work_han_thu_67","textTraditional":"二五０五頁一五行　言內質敗壞不（能）〔可〕修治也。　景祐、殿本都作「可」。王先謙說，依正文則作「可」是。","sentenceOrder":270},
  {"id":"s_work_han_thu_67_271","chapterId":"ch_work_han_thu_67","textTraditional":"二五０六頁　八行　昃亦（昊）〔〈吳，中“口改日”〉〕字。　景祐、殿、局本都作「〈吳，中“口改日”〉」，此誤。","sentenceOrder":271},
  {"id":"s_work_han_thu_67_272","chapterId":"ch_work_han_thu_67","textTraditional":"二五０七頁一０行　賢不肖渾（淆）〔殽〕，　景祐、殿、局本都作「殽」。王先謙說「淆」字後人妄改。","sentenceOrder":272},
  {"id":"s_work_han_thu_67_273","chapterId":"ch_work_han_thu_67","textTraditional":"二五０七頁一０行　故詳延特起之士，（意）庶幾乎！　宋祁說，古浙本有「意」字，他本無。按景祐本無。","sentenceOrder":273},
  {"id":"s_work_han_thu_67_274","chapterId":"ch_work_han_thu_67","textTraditional":"二五０七頁一二行　毋乃牽於文繫而不得騁（歟）〔與〕？　殿本作「與」。據注作「與」是。景祐本亦誤。","sentenceOrder":274},
  {"id":"s_work_han_thu_67_275","chapterId":"ch_work_han_thu_67","textTraditional":"二五０九頁　二行　韶盡美矣，又盡善（也）〔矣〕，　景祐本作「矣」。王念孫說，據顏注，則正文本是「矣」字。","sentenceOrder":275},
  {"id":"s_work_han_thu_67_276","chapterId":"ch_work_han_thu_67","textTraditional":"二五一０頁一三行　非有文德以教訓於（天）下也。　宋祁說景德本無「天」字。按景祐本亦無。","sentenceOrder":276},
  {"id":"s_work_han_thu_67_277","chapterId":"ch_work_han_thu_67","textTraditional":"二五一０頁一四行　是以百官皆飾（空言）虛辭而不顧實，　景祐本無「空言」二字。","sentenceOrder":277},
  {"id":"s_work_han_thu_67_278","chapterId":"ch_work_han_thu_67","textTraditional":"二五一二頁　三行　譬猶不（瑑）〔琢〕玉而求文采也。　景祐本作「琢」。宋祁說當從此本。按通鑑亦作「琢」。","sentenceOrder":278},
  {"id":"s_work_han_thu_67_279","chapterId":"ch_work_han_thu_67","textTraditional":"二五一二頁　四行　故養士之大者，莫大（虐）〔虖〕太學；　景祐、汲古、殿、局本都作「虖」，此誤。","sentenceOrder":279},
  {"id":"s_work_han_thu_67_280","chapterId":"ch_work_han_thu_67","textTraditional":"二五一二頁一五行　且古所謂功者，以任官稱職為差，非（所）謂積日絫久也。　景祐本無下「所」字。王念孫說下「所」字涉上「所」字而衍。","sentenceOrder":280},
  {"id":"s_work_han_thu_67_281","chapterId":"ch_work_han_thu_67","textTraditional":"二五一三頁　二行　（累）〔絫〕日以取貴，　景祐本亦作「累」。殿本作「絫」，則與上文一致。","sentenceOrder":281},
  {"id":"s_work_han_thu_67_282","chapterId":"ch_work_han_thu_67","textTraditional":"二五一九頁一三行　論（誼）〔議〕考問，　王先謙說此「誼」字不可通，蓋涉下「誼」字而誤。治要引作「論議考問」，當從之。","sentenceOrder":282},
  {"id":"s_work_han_thu_67_283","chapterId":"ch_work_han_thu_67","textTraditional":"二五二０頁　一行　共是天下，古（亦）〔以〕大治，　錢大昭說「亦」閩本作「以」。王先謙說閩本是，治要正作「古以大治」。","sentenceOrder":283},
  {"id":"s_work_han_thu_67_284","chapterId":"ch_work_han_thu_67","textTraditional":"二五二０頁　四行　試跡之〔於〕古，　宋祁說姚本「古」上有「於」字。","sentenceOrder":284},
  {"id":"s_work_han_thu_67_285","chapterId":"ch_work_han_thu_67","textTraditional":"二五二０頁一一行　（反）〔返〕謂還歸之也。　殿本作「返」。王先謙說作「返」是。","sentenceOrder":285},
  {"id":"s_work_han_thu_67_286","chapterId":"ch_work_han_thu_67","textTraditional":"二五二二頁一二行　食菜曰茹，音（洳）〔汝〕。　景祐、殿本都作「汝」。","sentenceOrder":286},
  {"id":"s_work_han_thu_67_287","chapterId":"ch_work_han_thu_67","textTraditional":"二五二三頁　二行　此易解卦六（二）〔三〕爻辭也。　景祐、殿本都作「三」，此誤。","sentenceOrder":287},
  {"id":"s_work_han_thu_67_288","chapterId":"ch_work_han_thu_67","textTraditional":"二五二四頁　七行　柳下，所食（菜）〔采〕邑之名。　殿本作「采」，此誤，景祐本亦誤。","sentenceOrder":288},
  {"id":"s_work_han_thu_67_289","chapterId":"ch_work_han_thu_67","textTraditional":"二五二五頁　六行　膠西王聞仲舒〔三〕大儒，善待之。　景祐、殿本都無「儒」字。宋祁說古本「大」字下有「儒」字，但不當於「仲舒」下作注，蓋顏注時已失之矣。","sentenceOrder":289},
  {"id":"s_work_han_thu_68_1","chapterId":"ch_work_han_thu_68","textTraditional":"師古曰：「近代之讀相如賦者多矣，皆改易文字，競為音說，致失本真，徐廣、鄒誕生、諸詮之、陳武之屬是也。今依班書舊文為正，於彼數家，並無取焉。自喻巴蜀之後分為下卷。」","sentenceOrder":1},
  {"id":"s_work_han_thu_68_2","chapterId":"ch_work_han_thu_68","textTraditional":"司馬相如字長卿，蜀郡成都人也。少時好讀書，學擊劍，〔一〕名犬子。〔二〕相如既學，慕藺相如之為人也，更名相如。〔三〕以訾為郎，事孝景帝，為武騎常侍，非其好也。〔四〕會景帝不好辭賦，是時梁孝王來朝，從游說之士齊人鄒陽、淮陰枚乘、吳嚴忌夫子之徒，〔五〕相如見而說之，〔六〕因病免，客游梁，得與諸侯游士居，數歲，乃著子虛之賦。","sentenceOrder":2},
  {"id":"s_work_han_thu_68_3","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　師古曰：「擊劍者，以劍遙擊而中之，非斬刺也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_68_4","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　師古曰：「父母愛之，不欲稱斥，故為此名也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_68_5","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　師古曰：「藺相如，六國時趙人也，義而有勇，故追慕之。」","sentenceOrder":5},
  {"id":"s_work_han_thu_68_6","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　師古曰：「訾讀與貲同。貲，財也。以家財多得拜為郎也。武騎常侍秩六百石。」","sentenceOrder":6},
  {"id":"s_work_han_thu_68_7","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　師古曰：「嚴忌本姓莊，當時尊尚，號曰夫子。史家避漢明帝諱，故遂為嚴耳。」","sentenceOrder":7},
  {"id":"s_work_han_thu_68_8","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　師古曰：「說讀曰悅。」","sentenceOrder":8},
  {"id":"s_work_han_thu_68_9","chapterId":"ch_work_han_thu_68","textTraditional":"會梁孝王薨，相如歸，而家貧無以自業。素與臨邛令王吉相善，吉曰：「長卿久宦游，不遂而困，〔一〕來過我。」於是相如往舍都亭。〔二〕臨邛令繆為恭敬，〔三〕日往朝相如。相如初尚見之，後稱病，使從者謝吉，吉愈益謹肅。","sentenceOrder":9},
  {"id":"s_work_han_thu_68_10","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　師古曰：「遂，達也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_68_11","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　師古曰：「臨邛所治都之亭。」","sentenceOrder":11},
  {"id":"s_work_han_thu_68_12","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　師古曰：「繆，詐也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_68_13","chapterId":"ch_work_han_thu_68","textTraditional":"臨邛多富人，卓王孫僮客八百人，〔一〕程鄭亦數百人，〔二〕乃相謂曰：「令有貴客，為具召之。〔三〕并召令。」令既至，卓氏客以百數，至日中請司馬長卿，長卿謝病不能臨。臨邛令不敢嘗食，身自迎相如，相如為不得已而強往，〔四〕一坐盡傾。〔五〕酒酣，臨邛令前奏琴曰：「竊聞長卿好之，願以自娛。」〔六〕相如辭謝，為鼓一再行。〔七〕是時，卓王孫有女文君新寡，好音，故相如繆與令相重而以琴心挑之。〔八〕相如時從車騎，雍容閒雅，〔九〕甚都。〔一０〕及飲卓氏弄琴，文君竊從戶窺，心說而好之，〔一一〕恐不得當也。〔一二〕既罷，相如乃令侍人重賜文君侍者通殷勤。文君夜亡奔相如，相如與馳歸成都。家徒四壁立。〔一三〕卓王孫大怒曰：「女不材，我不忍殺，一錢不分也！」人或謂王孫，王孫終不聽。文君久之不樂，謂長卿曰：「弟俱如臨邛，〔一四〕從昆弟假貣，猶足以為生，〔一五〕何至自苦如此！」相如與俱之臨邛，盡賣車騎，買酒舍，乃令文君當盧。〔一六〕相如身自著犢鼻褌，〔一七〕與庸保雜作，〔一八〕滌器於市中。〔一九〕卓王孫恥之，為杜門不出。〔二０〕昆弟諸公更謂王孫曰：〔二一〕「有一男兩女，所不足者非財也。〔二二〕今文君既失身於司馬長卿，長卿故倦游，〔二三〕雖貧，其人材足依也。且又令客，奈何相辱如此！」〔二四〕卓王孫不得已，〔二五〕分與文君僮百人，錢百萬，及其嫁時衣被財物。文君乃與相如歸成都，買田宅，為富人。","sentenceOrder":13},
  {"id":"s_work_han_thu_68_14","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　師古曰：「僮謂奴。」","sentenceOrder":14},
  {"id":"s_work_han_thu_68_15","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　師古曰：「程鄭，亦人姓名。言其家富亞王孫也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_68_16","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　師古曰：「具謂酒食之具。召，請也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_68_17","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　師古曰：「示眾人以此意也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_68_18","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　師古曰：「皆傾慕其風采也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_68_19","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　師古曰：「奏，進也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_68_20","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　師古曰：「行謂曲引也。古樂府長歌行短歌行，此其義也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_68_21","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　師古曰：「寄心於琴聲以挑動之也。挑音徒了反。」","sentenceOrder":21},
  {"id":"s_work_han_thu_68_22","chapterId":"ch_work_han_thu_68","textTraditional":"〔九〕　師古曰：「閒讀曰閑。」","sentenceOrder":22},
  {"id":"s_work_han_thu_68_23","chapterId":"ch_work_han_thu_68","textTraditional":"〔一０〕張揖曰：「甚得都士之節也。」韋昭曰：「都邑之容也。」師古曰：「都，閒美之稱也。張說近之。詩鄭風有女同車之篇曰『洵美且都』，山有扶蘇之篇又云『不見子都』，則知都者，美也。韋言都邑，失之遠矣。」","sentenceOrder":23},
  {"id":"s_work_han_thu_68_24","chapterId":"ch_work_han_thu_68","textTraditional":"〔一一〕師古曰：「說讀曰悅。悅其人而好其音也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_68_25","chapterId":"ch_work_han_thu_68","textTraditional":"〔一二〕師古曰：「當謂對偶之。」","sentenceOrder":25},
  {"id":"s_work_han_thu_68_26","chapterId":"ch_work_han_thu_68","textTraditional":"〔一三〕師古曰：「徒，空也。但有四壁，更無資產。」","sentenceOrder":26},
  {"id":"s_work_han_thu_68_27","chapterId":"ch_work_han_thu_68","textTraditional":"〔一四〕文穎曰：「弟，且也。」張揖曰：「如，往也。」師古曰：「弟，但也，發聲之急耳。酈食其曰『弟言之』，此類甚多，義非且也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_68_28","chapterId":"ch_work_han_thu_68","textTraditional":"〔一五〕師古曰：「貣音吐得反。」","sentenceOrder":28},
  {"id":"s_work_han_thu_68_29","chapterId":"ch_work_han_thu_68","textTraditional":"〔一六〕郭璞曰：「盧，酒盧。」師古曰：「賣酒之處累土為盧以居酒瓮，四邊隆起，其一面高，形如鍛盧，故名盧耳。而俗之學者，皆謂當盧為對溫酒火盧，失其義矣。」","sentenceOrder":29},
  {"id":"s_work_han_thu_68_30","chapterId":"ch_work_han_thu_68","textTraditional":"〔一七〕師古曰：「即今之衳也，形似犢鼻，故以名云。衳音之容反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_68_31","chapterId":"ch_work_han_thu_68","textTraditional":"〔一八〕師古曰：「庸即謂賃作者。保謂庸之可信任者也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_68_32","chapterId":"ch_work_han_thu_68","textTraditional":"〔一九〕師古曰：「滌，洒也。器，食器也。食已則洒之，賤人之役也。酒音先禮反。」","sentenceOrder":32},
  {"id":"s_work_han_thu_68_33","chapterId":"ch_work_han_thu_68","textTraditional":"〔二０〕師古曰：「杜，塞也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_68_34","chapterId":"ch_work_han_thu_68","textTraditional":"〔二一〕師古曰：「更，互也，音工衡反。」","sentenceOrder":34},
  {"id":"s_work_han_thu_68_35","chapterId":"ch_work_han_thu_68","textTraditional":"〔二二〕師古曰：「言不患少財也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_68_36","chapterId":"ch_work_han_thu_68","textTraditional":"〔二三〕文穎曰：「倦，疲也。言疲厭游學，博物多能也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_68_37","chapterId":"ch_work_han_thu_68","textTraditional":"〔二四〕師古曰：「言縣令之客，不可以辱也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_68_38","chapterId":"ch_work_han_thu_68","textTraditional":"〔二五〕師古曰：「已，止也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_68_39","chapterId":"ch_work_han_thu_68","textTraditional":"居久之，蜀人楊得意為狗監，〔一〕侍上。上讀子虛賦而善之，曰：「朕獨不得與此人同時哉！」得意曰：「臣邑人司馬相如自言為此賦。」上驚，乃召問相如。相如曰：「有是。然此乃詩侯之事，未足觀，請為天子游獵之賦。」上令尚書給筆札，〔二〕相如以「子虛」，虛言也，為楚稱；〔三〕「烏有先生」者，烏有此事也，〔四〕為齊難；〔五〕「亡是公」者，亡是人也，〔六〕欲明天子之義。故虛藉此三人為辭，〔七〕以推天子諸侯之苑囿。其卒章歸之於節儉，〔八〕因以風諫。〔九〕奏之天子，天子大說。〔一０〕其辭曰：","sentenceOrder":39},
  {"id":"s_work_han_thu_68_40","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　師古曰：「主天子田獵犬也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_68_41","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　師古曰：「札，木簡之薄小者也。時未多用紙，故給札以書。札音壯黠反。」","sentenceOrder":41},
  {"id":"s_work_han_thu_68_42","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　師古曰：「稱說楚之美也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_68_43","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　師古曰：「烏，於何也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_68_44","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　師古曰：「難詰楚事也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_68_45","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　師古曰：「亡讀曰無。下皆類此。」","sentenceOrder":45},
  {"id":"s_work_han_thu_68_46","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　師古曰：「藉，假也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_68_47","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　師古曰：「卒，終也。謂終篇之言，若隤牆填塹之比者。」","sentenceOrder":47},
  {"id":"s_work_han_thu_68_48","chapterId":"ch_work_han_thu_68","textTraditional":"〔九〕　師古曰：「風讀曰諷。」","sentenceOrder":48},
  {"id":"s_work_han_thu_68_49","chapterId":"ch_work_han_thu_68","textTraditional":"〔一０〕師古曰：「說讀曰悅。」","sentenceOrder":49},
  {"id":"s_work_han_thu_68_50","chapterId":"ch_work_han_thu_68","textTraditional":"楚使子虛使於齊，齊王悉發車騎與使者出田。〔一〕田罷，子虛過姹烏有先生，〔二〕亡是公存焉。坐定，烏有先生問曰：「今日田樂乎？」子虛曰：「樂。」「獲多乎？」曰：「少。」「然則何樂？」對曰：「僕樂王之欲夸僕以車騎之眾，而僕對以雲夢之事也。」〔三〕曰：「可得聞乎？」","sentenceOrder":50},
  {"id":"s_work_han_thu_68_51","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　師古曰：「田，獵也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_68_52","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　師古曰：「姹，誇誑之也，音丑亞反，字本作詫也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_68_53","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　張揖曰：「楚藪也。在南郡華容縣。」師古曰：「夢讀如本字，又音莫風反，字或作瞢，其音同耳。」","sentenceOrder":53},
  {"id":"s_work_han_thu_68_54","chapterId":"ch_work_han_thu_68","textTraditional":"子虛曰：「可。王駕車千乘，選徒萬騎，田於海濱，〔一〕列卒滿澤，罘罔彌山。〔二〕掩菟轔鹿，射麋格麟，〔三〕騖於鹽浦，割鮮染輪。〔四〕射中獲多，矜而自功，〔五〕顧謂僕曰：『楚亦有平原廣澤遊獵之地饒樂若此者乎？楚王之獵孰與寡人？』〔六〕僕下車對曰：『臣，楚國之鄙人也，幸得宿衛十有餘年，時從出遊，遊於後園，覽於有無，然猶未能遍睹也。又烏足以言其外澤乎？』齊王曰：『雖然，略以子之所聞見言之。』","sentenceOrder":54},
  {"id":"s_work_han_thu_68_55","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　師古曰：「濱，涯也，音賓，又音頻。」","sentenceOrder":55},
  {"id":"s_work_han_thu_68_56","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　師古曰：「罘，覆車也，即今幡車罔也。王國兔爰之詩曰『雉罹于罦』，罦亦罘字耳。彌，竟也。罘音浮。」","sentenceOrder":56},
  {"id":"s_work_han_thu_68_57","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　師古曰：「轔謂車踐轢之也，音〈恡，去“忄”〉。格字或作腳，言持引其腳也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_68_58","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　張揖曰：「海水之涯多出鹽也。」李奇曰：「鮮，生也。染，擩也。切生肉，擩車輪，鹽而食之也。」師古曰：「騖謂亂馳也。擩，搵也。騖音務。擩音如閱反。搵音一頓反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_68_59","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　師古曰：「自矜其能以為功也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_68_60","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　師古曰：「與猶如也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_68_61","chapterId":"ch_work_han_thu_68","textTraditional":"「僕對曰：『唯唯。〔一〕臣聞楚有七澤，嘗見其一，未睹其餘也。臣之所見，蓋特其小小者耳，名曰雲夢。雲夢者，方九百里，其中有山焉。其山則盤紆岪鬱，隆崇律崒；〔二〕岑崟參差，日月蔽虧；〔三〕交錯糾紛，上干青雲；〔四〕罷池陂陁，下屬江河〔五〕。其土則丹青赭堊，雌黃白坿，錫碧金銀，〔六〕眾色炫燿，照爛龍鱗。〔七〕其石則赤玉玫瑰，琳珉昆吾，〔八〕瑊玏玄厲，〔九〕礝石武夫。〔一０〕其東則有蕙圃，衡蘭芷若，〔一一〕穹窮昌蒲，江離蘪蕪，〔一二〕諸柘巴且。〔一三〕其南則有平原廣澤，登降阤靡，〔一四〕案衍壇曼，〔一五〕緣以大江，限以巫山。〔一六〕其高燥則生葴析苞荔，〔一七〕薜莎青薠。〔一八〕其埤溼則生藏莨蒹葭，〔一九〕東蘠彫胡，〔二０〕蓮藕觚盧，〔二一〕奄閭軒于〔二二〕。眾物居之，不可勝圖。〔二三〕其西則有涌泉清池，激水推移，〔二四〕外發夫容陵華，內隱鉅石白沙。〔二五〕其中則有神龜蛟鼉，毒冒鱉黿。〔二六〕其北則有陰林巨樹，楩柟豫章，〔二七〕桂椒木蘭，檗離朱楊，〔二八〕樝梨梬栗，橘柚芬芳。〔二九〕其上則有宛雛孔鸞，騰遠射干。〔三０〕其下則有白虎玄豹，蟃蜒貙豻〔三一〕。","sentenceOrder":61},
  {"id":"s_work_han_thu_68_62","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　師古曰：「唯唯，恭應之辭也，音弋癸反。」","sentenceOrder":62},
  {"id":"s_work_han_thu_68_63","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　郭璞曰：「詰屈竦起也。岪音佛。」","sentenceOrder":63},
  {"id":"s_work_han_thu_68_64","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　張揖曰：「高山壅蔽，日月虧缺半見。」師古曰：「岑音仕林反。崟音吟。」","sentenceOrder":64},
  {"id":"s_work_han_thu_68_65","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　郭璞曰：「言相摎結而峻絕。」","sentenceOrder":65},
  {"id":"s_work_han_thu_68_66","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　郭璞曰：「言旁穨也。屬，連也。罷音疲。陂音婆。陁音駝。」文穎曰：「南方無河也。冀州凡水大小皆謂之河，詩賦通方言耳。」晉灼曰：「文意假借協陁之韻也。」師古曰：「文、晉之說皆非也。下屬江河者，總言山之廣大，所連者遠耳，於文無妨。陂音普河反。屬音之欲反。」","sentenceOrder":66},
  {"id":"s_work_han_thu_68_67","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　張揖曰：「丹，丹沙也。青，青雘也。赭，赤赭也。堊，白堊也。」蘇林曰：「白坿，白石英也。」師古曰：「丹沙，今之朱沙也。青雘，今之空青也。赭，今之赤土也。堊，今之白土也。錫，青金也。碧謂玉之青白色者也。堊音惡。坿音附。雘音一郭反。」","sentenceOrder":67},
  {"id":"s_work_han_thu_68_68","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　師古曰：「言采色相耀，若龍鱗之間雜也。炫音州縣之縣。」","sentenceOrder":68},
  {"id":"s_work_han_thu_68_69","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　張揖曰：「琳，玉也。珉，石之次玉者也。昆吾，山名也，出善金。尸子曰『昆吾之金』。」晉灼曰：「玫瑰，火齊珠也。」師古曰：「火齊珠，今南方之出火珠也。玫音枚。瑰音回，又音瓌。琳音林。珉音旻。」","sentenceOrder":69},
  {"id":"s_work_han_thu_68_70","chapterId":"ch_work_han_thu_68","textTraditional":"〔九〕　張揖曰：「瑊玏，石之次玉者。玄厲，黑石可用磨也。」如淳曰：「瑊音緘。玏音勒。」","sentenceOrder":70},
  {"id":"s_work_han_thu_68_71","chapterId":"ch_work_han_thu_68","textTraditional":"〔一０〕張揖曰：「皆石之次玉者。礝石，白者如冰，半有赤色。武夫，赤地白采，蔥蘢白黑不分。」郭璞曰：「礝音而兗反。」","sentenceOrder":71},
  {"id":"s_work_han_thu_68_72","chapterId":"ch_work_han_thu_68","textTraditional":"〔一一〕張揖曰：「蕙圃，蕙草之圃也。衡，杜衡也，其狀若葵，其臭如蘪蕪。芷，白芷。若，杜若也。」師古曰：「蘭即今澤蘭也。今流俗書本『芷若』下有『射干』字，妄增之也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_68_73","chapterId":"ch_work_han_thu_68","textTraditional":"〔一二〕張揖曰：「江離，香草也。蘪蕪蘄芷也，似蛇床而香。」師古曰：「蘪蕪即穹窮苗也。」郭璞曰：「江離似水薺，而藥對曰蘪蕪一名江離。張勃又云江離出臨海縣海水中，正青，似亂髮。郭義恭云江離赤葉。諸說不同，未知孰是。今無識之者，然非蘪蕪也，藥對誤耳。」","sentenceOrder":73},
  {"id":"s_work_han_thu_68_74","chapterId":"ch_work_han_thu_68","textTraditional":"〔一三〕張揖曰：「諸柘，甘柘也。蒪苴，蘘荷也。」文穎曰：「巴且草一名巴蕉。」師古曰：「文說巴且是也。且音子余反。蒪音普各反。蒪苴自蘘荷耳，非巴且也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_68_75","chapterId":"ch_work_han_thu_68","textTraditional":"〔一四〕師古曰：「登，上也。降，下也。阤靡，旁袤也。阤音弋爾反。」","sentenceOrder":75},
  {"id":"s_work_han_thu_68_76","chapterId":"ch_work_han_thu_68","textTraditional":"〔一五〕師古曰：「寬廣之貌也。衍音弋戰反。壇音徒但反。曼音莫幹反。」","sentenceOrder":76},
  {"id":"s_work_han_thu_68_77","chapterId":"ch_work_han_thu_68","textTraditional":"〔一六〕張揖曰：「巫山在南郡巫縣也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_68_78","chapterId":"ch_work_han_thu_68","textTraditional":"〔一七〕張揖曰：「葴，馬藍也。析似燕麥。苞，藨也。荔，馬荔。」蘇林曰：「析音斯。」師古曰：「藨即今所用作席者也。馬荔，今之馬藺也。葴音之林反。苞音包。荔音隸。藨音皮表反。」","sentenceOrder":78},
  {"id":"s_work_han_thu_68_79","chapterId":"ch_work_han_thu_68","textTraditional":"〔一八〕張揖曰：「薜，賴蒿也。莎，鎬侯也。青薠似莎而大，生江湖，雁所食。」師古曰：「莎即今青莎草。薠音煩。」","sentenceOrder":79},
  {"id":"s_work_han_thu_68_80","chapterId":"ch_work_han_thu_68","textTraditional":"〔一九〕郭璞曰：「藏茛草中牛馬芻。蒹，荻也，似雚而細小。葭，蘆也。」師古曰：「埤音婢，謂下地也。茛音郎。蒹葭音兼豭。荻音敵。」","sentenceOrder":80},
  {"id":"s_work_han_thu_68_81","chapterId":"ch_work_han_thu_68","textTraditional":"〔二０〕張揖曰：「東蘠，實可食。彫胡，菰米也。」師古曰：「東蘠似蓬，其實如葵子也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_68_82","chapterId":"ch_work_han_thu_68","textTraditional":"〔二一〕張揖曰：「蓮，荷之實也，其根藕。」張晏曰：「觚盧，扈魯也。」郭璞曰：「眾，蔣也。蘆，葦也。」師古曰：「書不為眾蘆字，郭說非也，但不知觚蘆於今是何草耳。」","sentenceOrder":82},
  {"id":"s_work_han_thu_68_83","chapterId":"ch_work_han_thu_68","textTraditional":"〔二二〕張揖曰：「奄閭，蒿也，子可治疾。軒于，蕕草也，生水中，揚州有之。」師古曰：「奄音淹。蕕音猶。」","sentenceOrder":83},
  {"id":"s_work_han_thu_68_84","chapterId":"ch_work_han_thu_68","textTraditional":"〔二三〕師古曰：「勝，舉也。不可盡舉而圖寫之，言其多也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_68_85","chapterId":"ch_work_han_thu_68","textTraditional":"〔二四〕郭璞曰：「波抑揚也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_68_86","chapterId":"ch_work_han_thu_68","textTraditional":"〔二五〕應劭曰：「夫容，蓮華也。陵，芰也。」師古曰：「鉅，大也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_68_87","chapterId":"ch_work_han_thu_68","textTraditional":"〔二六〕張揖曰：「蛟狀魚身而蛇尾，皮有珠。鼉似蜥蜴而大，身有甲，皮可作鼓。毒冒似觜蠵，甲有文。黿似鱉而大。」師古曰：「張說蛟者，乃是鮫魚，非蛟龍之蛟也。蛟解在武紀。鼉音徒何反。又音大河反。毒音代。冒音妹。他皆倣此。」","sentenceOrder":87},
  {"id":"s_work_han_thu_68_88","chapterId":"ch_work_han_thu_68","textTraditional":"〔二七〕服虔曰：「陰林，山北之林也。豫章，大木也，生七年乃可知。」師古曰：「陰林，言其樹木眾而且大，常多陰也。楩音便，又音步田反，即今黃楩木也。柟音南，今所謂楠木。」","sentenceOrder":88},
  {"id":"s_work_han_thu_68_89","chapterId":"ch_work_han_thu_68","textTraditional":"〔二八〕師古曰：「桂即藥之所用其皮者也。椒即所食椒樹也。木蘭皮似椒而香，可作面膏藥。檗，黃檗也。離，山梨也。朱楊，赤莖柳也，生水邊。」","sentenceOrder":89},
  {"id":"s_work_han_thu_68_90","chapterId":"ch_work_han_thu_68","textTraditional":"〔二九〕張揖曰：「樝似梨而甘。梬，梬棗也。」師古曰：「樝即今所謂樝子也。梬棗即今之〈暂缺F4E4〉棗也。柚即橙也，似橘而大，味酢皮厚。樝音側加反。梬音弋整反。柚音弋救反。橙音丈莖反。芬芳，言橘柚之氣也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_68_91","chapterId":"ch_work_han_thu_68","textTraditional":"〔三０〕張揖曰：「宛雛似鳳。孔，孔雀；鸞，鸞鳥也。射干似狐，能緣木。」服虔曰：「騰遠，獸名也。」師古曰：「鸞鳥形如翟而五采文，見山海經。宛音於元反。射音弋舍反。」","sentenceOrder":91},
  {"id":"s_work_han_thu_68_92","chapterId":"ch_work_han_thu_68","textTraditional":"〔三一〕郭璞曰：「蟃蜒，大獸似狸，長百尋。貙似狸而大。豻，胡地野犬也，似狐而小。蟃音萬。蜒音延。豻音岸。」師古曰：「蜒又音弋戰反。貙音丑于反。豻合韻音五安反。」","sentenceOrder":92},
  {"id":"s_work_han_thu_68_93","chapterId":"ch_work_han_thu_68","textTraditional":"「『於是乎乃使剸諸之倫，手格此獸。〔一〕楚王乃駕馴駮之駟，〔二〕乘彫玉之輿，〔三〕靡魚須之橈旃，〔四〕曳明月之珠旗，〔五〕建干將之雄戟，〔六〕左烏號之彫弓，〔七〕右夏服之勁箭；〔八〕陽子驂乘，孅阿為御；〔九〕案節未舒，即陵狡獸，〔一０〕蹴蛩蛩，轔距虛，〔一一〕軼野馬，〈車惠〉騊駼；〔一二〕乘遺風，射遊騏，〔一三〕儵胂倩浰，〔一四〕雷動焱至，〔一五〕星流電擊，弓不虛發，中必決眥，〔一六〕洞胸達掖，絕乎心繫，〔一七〕獲若雨獸，揜屮蔽地。〔一八〕於是楚王乃弭節徘徊，翱翔容與，〔一九〕覽乎陰林，觀壯士之暴怒，與猛獸之恐懼，徼〈郄，中“阝改几”〉受詘，〔二０〕殫睹眾物之變態。〔二一〕","sentenceOrder":93},
  {"id":"s_work_han_thu_68_94","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　師古曰：「剸諸，吳人，刺吳王僚者也。方言勇士，故舉以為類。剸與專同。」","sentenceOrder":94},
  {"id":"s_work_han_thu_68_95","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　張揖曰：「馴，擾也。駮如馬，白身黑尾，一角鋸牙，食虎豹，擾而駕之，以當駟馬也。」師古曰：「馴音旬。」","sentenceOrder":95},
  {"id":"s_work_han_thu_68_96","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　師古曰：「以玉飾輿而彫鏤之。」","sentenceOrder":96},
  {"id":"s_work_han_thu_68_97","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　張揖曰：「以魚須為旃柄，驅馳逐獸，正橈靡也。」郭璞曰：「通帛為旃。」師古曰：「大魚之須出東海，見尚書大傳。橈旃即曲旃也。橈音女教反。」","sentenceOrder":97},
  {"id":"s_work_han_thu_68_98","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　張揖曰：「以明月珠綴飾旗也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_68_99","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　張揖曰：「干將，韓王劍師也。雄戟，胡中有〈角巨〉者，干將所造。」","sentenceOrder":99},
  {"id":"s_work_han_thu_68_100","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　應劭曰：「楚有柘桑，烏棲其上，支下著地，不得飛，欲墮號呼，故曰烏號。」張揖曰：「黃帝乘龍上天，小臣不得上，挽持龍〈冉頁〉，〈冉頁〉拔，墮黃帝弓，臣下抱弓而號，故名弓烏號。」郭璞曰：「雕，畫也。」師古曰：「烏號，應、張二說皆有據也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_68_101","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　伏儼曰：「服，盛箭器也。夏后氏之良弓名煩弱，其矢亦良，即煩弱箭服也，故曰夏服。」師古曰：「箭服，即今之步叉也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_68_102","chapterId":"ch_work_han_thu_68","textTraditional":"〔九〕　張揖曰：「陽子，伯樂也，秦繆公臣，姓孫，名陽。」郭璞曰：「孅阿，古之善御者。孅音纖。」","sentenceOrder":102},
  {"id":"s_work_han_thu_68_103","chapterId":"ch_work_han_thu_68","textTraditional":"〔一０〕師古曰：「案節猶弭節也。未舒，言未盡意驅馳，已淩狡獸，狡捷之獸也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_68_104","chapterId":"ch_work_han_thu_68","textTraditional":"〔一一〕張揖曰：「蛩蛩，青獸，狀如馬。距虛似驘而小。」郭璞曰：「距虛即蛩蛩，變文互言耳。」師古曰：「據爾雅文，郭說是也。蹴音子六反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_68_105","chapterId":"ch_work_han_thu_68","textTraditional":"〔一二〕張揖曰：「軼，過也。野馬似馬而小。北海內有獸，狀如馬，名騊駼。」郭璞曰：「〈車惠〉，車軸頭也。」師古曰：「〈車惠〉謂軸頭衝而殺之也。軼音逸。〈車惠〉音衛。騊音逃。駼音塗。」","sentenceOrder":105},
  {"id":"s_work_han_thu_68_106","chapterId":"ch_work_han_thu_68","textTraditional":"〔一三〕張揖曰：「遺風，千里馬也。爾雅曰巂如馬一角，不角者曰騏。」師古曰：「巂音攜。騏音其。」","sentenceOrder":106},
  {"id":"s_work_han_thu_68_107","chapterId":"ch_work_han_thu_68","textTraditional":"〔一四〕張揖曰：「皆疾貌也。」師古曰：「儵音式六反。胂音式刃反。倩音千見反。浰音練。」","sentenceOrder":107},
  {"id":"s_work_han_thu_68_108","chapterId":"ch_work_han_thu_68","textTraditional":"〔一五〕師古曰：「焱，疾風也。若雷之動，如焱之至，言其威且疾也。焱音必遙反。」","sentenceOrder":108},
  {"id":"s_work_han_thu_68_109","chapterId":"ch_work_han_thu_68","textTraditional":"〔一六〕師古曰：「〔決〕眥即決獸之目眥，言射審也。眥即眥字。」","sentenceOrder":109},
  {"id":"s_work_han_thu_68_110","chapterId":"ch_work_han_thu_68","textTraditional":"〔一七〕張揖曰：「自左射之，貫胸通右髃，中心絕系也。」師古曰：「髃謂肩前骨也，音五口反。繫讀曰系也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_68_111","chapterId":"ch_work_han_thu_68","textTraditional":"〔一八〕師古曰：「言獲殺之多，如天雨獸也。雨音于具反。屮，古草字也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_68_112","chapterId":"ch_work_han_thu_68","textTraditional":"〔一九〕郭璞曰：「弭猶低也。節，所杖信節也。翱翔容與，言自得也。」師古曰：「弭節者，示安徐也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_68_113","chapterId":"ch_work_han_thu_68","textTraditional":"〔二０〕蘇林曰：「〈郄，中“阝改几”〉音倦〈郄，中“阝改几”〉之〈郄，中“阝改几”〉。詘音〈暂缺F4E3〉強之〈暂缺F4E3〉。」郭璞曰：「詘，詘折也。〈郄，中“阝改几”〉，疲極。詘音屈。」師古曰：「蘇音是也。〈郄，中“阝改几”〉音與劇同。詘音其勿反。徼，工堯反。徼，要也。詘，盡也。言獸有倦極者要而取之，力盡者受而有之。」","sentenceOrder":113},
  {"id":"s_work_han_thu_68_114","chapterId":"ch_work_han_thu_68","textTraditional":"〔二一〕郭璞曰：「殫，盡也。變態，姿則也。」師古曰：「殫音單。」","sentenceOrder":114},
  {"id":"s_work_han_thu_68_115","chapterId":"ch_work_han_thu_68","textTraditional":"「『於是鄭女曼姬，〔一〕被阿錫，揄紵縞，〔二〕雜纖羅，垂霧縠，〔三〕襞積褰縐，鬱橈谿谷；〔四〕衯衯裶裶，揚衪戌削，〔五〕蜚襳垂髾；〔六〕扶輿猗靡，〔七〕翕呷萃蔡，〔八〕下摩蘭蕙，上拂羽蓋；〔九〕錯翡翠之葳蕤，〔一０〕繆繞玉綏；〔一一〕眇眇忽忽，若神之髣彿。〔一二〕","sentenceOrder":115},
  {"id":"s_work_han_thu_68_116","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　文穎曰：「鄭國出好女。曼者，言其色理曼澤也。」如淳曰：「鄭女，夏姬也。曼姬，楚武王夫人鄧曼也。」師古曰：「文說是也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_68_117","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　張揖曰：「阿，細繒也。錫，細布也。揄，引也。」師古曰：「紵，纖紵也。縞，鮮支也，今之所謂素者也。揄音踰，又音投也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_68_118","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　張揖曰：「縠縐如霧，垂以為裳也。」師古曰：「纖，細也。霧縠者，言其輕靡如霧，非謂縐文。」","sentenceOrder":118},
  {"id":"s_work_han_thu_68_119","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　張揖曰：「襞積猶簡齰也。褰，縮也。縐，裁也。其縐中文理茀鬱，有似於谿谷也。」師古曰：「張說非也。襞積即今之帬〈衤聶〉，古所謂皮弁素積者，即謂此積也。言襞積文理，隨身所著，或褰縐委屈如豁谷也。襞音壁。縐音側救反。」","sentenceOrder":119},
  {"id":"s_work_han_thu_68_120","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　張揖曰：「衯音芬。祂，衣袖也。戌，鮮也。削，衣刻除貌也。」師古曰：「揚，舉也。祂，曳也。或舉或曳，則戌削然見其降殺之美也。裶音霏。衪音弋示反。戌讀如本字。」","sentenceOrder":120},
  {"id":"s_work_han_thu_68_121","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　張揖曰：「襳，離褂也。髾，髻後垂也。」師古曰：「張說非也。襳，褂衣之長帶也。髾謂燕尾之屬。皆衣上假飾，非髻垂也。蜚，古飛字也。襳音纖。髾音所交反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_68_122","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　張揖曰：「扶持楚王車輿相隨也。」師古曰：「張說非也。此自言鄭女曼姬為侍從者所扶輿而猗靡耳，非謂扶持楚王車輿也。猗音於綺反。今人猶呼相撫掩容養為猗靡。」","sentenceOrder":122},
  {"id":"s_work_han_thu_68_123","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　張揖曰：「翕呷，衣張起也。萃蔡，衣聲也。」師古曰：「呷音火甲反。萃音翠，又音千賄反。」","sentenceOrder":123},
  {"id":"s_work_han_thu_68_124","chapterId":"ch_work_han_thu_68","textTraditional":"〔九〕　師古曰：「下摩蘭蕙，謂垂髾也。上拂羽蓋，謂飛襳也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_68_125","chapterId":"ch_work_han_thu_68","textTraditional":"〔一０〕師古曰：「錯，雜也。葳蕤，羽飾貌。」","sentenceOrder":125},
  {"id":"s_work_han_thu_68_126","chapterId":"ch_work_han_thu_68","textTraditional":"〔一一〕張揖曰：「楚王車之綏以玉飾之也。」郭璞曰：「綏，登車所執也。」師古曰：「二說皆非也。以玉飾綏，亦謂鄭女曼姬之容服也。綏即今之所謂采〈糹畏〉垂鑷者也。繆繞，相纏結也。繆音蓼。〈糹畏〉音隈。」","sentenceOrder":126},
  {"id":"s_work_han_thu_68_127","chapterId":"ch_work_han_thu_68","textTraditional":"〔一二〕郭璞曰：「言其容飾奇豔，非世所見。戰國策曰：『鄭之美女粉白黛黑而立於衢，不知者謂之神也。』」","sentenceOrder":127},
  {"id":"s_work_han_thu_68_128","chapterId":"ch_work_han_thu_68","textTraditional":"「『於是乃群相與獠於蕙圃，〔一〕媻姍勃窣，上金隄〔二〕，揜翡翠，射鵔鸃，〔三〕微矰出，孅繳施，〔四〕弋白鵠，連鴐鵝，〔五〕雙鶬下，玄鶴加。〔六〕怠而後游於清池，〔七〕浮文鷁，〔八〕揚旌枻，〔九〕張翠帷，建羽蓋。〔一０〕罔毒冒，釣紫貝，〔一一〕摐金鼓，〔一二〕吹鳴籟，〔一三〕榜人歌，〔一四〕聲流喝，〔一五〕水蟲駭，波鴻沸，〔一六〕涌泉起，奔揚會，〔一七〕礧石相擊，琅琅磕磕，〔一八〕若雷霆之聲，聞乎數百里外。","sentenceOrder":128},
  {"id":"s_work_han_thu_68_129","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　文穎曰：「宵獵為獠。」師古曰：「獠音力笑反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_68_130","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　師古曰：「媻姍勃窣，謂行於叢薄之間也。金隄，言水之隄塘堅如金也。媻音盤。姍音先安反。窣音先忽反。隄音丁兮反。」","sentenceOrder":130},
  {"id":"s_work_han_thu_68_131","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　師古曰：「鳥赤羽者曰翡，青羽者曰翠。鵔鸃，鷩鳥也，似山雞而小冠，背毛黃，腹下赤，項綠色，其尾毛紅赤，光采鮮明，今俗呼為山雞，其實非也。鵔音峻。鸃音儀。」","sentenceOrder":131},
  {"id":"s_work_han_thu_68_132","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　師古曰：「矰，短矢也。繳，生絲縷也。以繳係矰仰射高鳥，謂之弋射。矰音增。繳音灼。」","sentenceOrder":132},
  {"id":"s_work_han_thu_68_133","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　師古曰：「鵠，水鳥也，其鳴聲鵠鵠云。鴐鵝，野鵝也。連謂重累獲之也。鵠音胡沃反。鴐音加。」","sentenceOrder":133},
  {"id":"s_work_han_thu_68_134","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　師古曰：「鶬鴰也。今關西呼為鴰鹿，山東通謂之鶬，鄙俗名為錯落。錯者，亦言鶬聲之急耳。又謂鴰捋。捋音來奪反。鴰鹿、鴰捋，皆象其鳴聲也。玄鶴，黑鶴也。相鶴經云鶴壽滿二百六十歲則色純黑。言弋射之妙，既中白鵠而連鴐鵝，又下雙鶬而加玄鶴也。鶬音倉。」","sentenceOrder":134},
  {"id":"s_work_han_thu_68_135","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　郭璞曰：「怠，倦也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_68_136","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　張揖曰：「鷁，水鳥也，畫其象於船首。淮南子曰『龍舟鷁首，天子之乘也』。」師古曰：「鷁音五歷反。」","sentenceOrder":136},
  {"id":"s_work_han_thu_68_137","chapterId":"ch_work_han_thu_68","textTraditional":"〔九〕　張揖曰：「揚，舉也。析羽為旌，建於船上。枻，柂也。」師古曰：「枻音曳。柂音大可反。」","sentenceOrder":137},
  {"id":"s_work_han_thu_68_138","chapterId":"ch_work_han_thu_68","textTraditional":"〔一０〕郭璞曰：「施之船上也。」師古曰：「翠帷，帷翠色也。羽蓋，以雜羽飾蓋。」","sentenceOrder":138},
  {"id":"s_work_han_thu_68_139","chapterId":"ch_work_han_thu_68","textTraditional":"〔一一〕郭璞曰：「紫貝，紫質黑文也。」師古曰：「貝，水中介蟲，古以為貨也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_68_140","chapterId":"ch_work_han_thu_68","textTraditional":"〔一二〕師古曰：「摐，撞也。金鼓謂鉦也。摐音窻。」","sentenceOrder":140},
  {"id":"s_work_han_thu_68_141","chapterId":"ch_work_han_thu_68","textTraditional":"〔一三〕張揖曰：「籟，簫也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_68_142","chapterId":"ch_work_han_thu_68","textTraditional":"〔一四〕張揖曰：「榜，船也。月令云『命榜人』，榜人，船長也，主倡聲而歌者也。」師古曰：「榜音謗，又方孟反。」","sentenceOrder":142},
  {"id":"s_work_han_thu_68_143","chapterId":"ch_work_han_thu_68","textTraditional":"〔一五〕郭璞曰：「言悲嘶也。」師古曰：「喝音一介反。嘶音蘇奚反。」","sentenceOrder":143},
  {"id":"s_work_han_thu_68_144","chapterId":"ch_work_han_thu_68","textTraditional":"〔一六〕郭璞曰：「魚鱉躍，濤浪作也。」師古曰：「沸音普蓋反。」","sentenceOrder":144},
  {"id":"s_work_han_thu_68_145","chapterId":"ch_work_han_thu_68","textTraditional":"〔一七〕郭璞曰：「暴湓激相鼓薄也。」師古曰：「湓音普頓反。」","sentenceOrder":145},
  {"id":"s_work_han_thu_68_146","chapterId":"ch_work_han_thu_68","textTraditional":"〔一八〕師古曰：「礧石，轉石也。礧音盧對反。磕音口蓋反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_68_147","chapterId":"ch_work_han_thu_68","textTraditional":"「『將息獠者，擊靈鼓，起烽燧，〔一〕車案行，騎就隊，〔二〕纚乎淫淫，般乎裔裔。〔三〕於是楚王乃登陽雲之臺，〔四〕泊乎無為，澹乎自持，〔五〕勺藥之和具而後御之。〔六〕不若大王終日馳騁，曾不下輿，脟割輪焠，自以為娛。〔七〕臣竊觀之，齊殆不如。』〔八〕於是王無以應僕也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_68_148","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　師古曰：「靈鼓，六面擊之，所以警眾也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_68_149","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　師古曰：「案，依也。行，列也。隊，部也。行音胡郎反。隊音大內反。」","sentenceOrder":149},
  {"id":"s_work_han_thu_68_150","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　郭璞曰：「皆群行貌。」師古曰：「纚音屣。般音盤。」","sentenceOrder":150},
  {"id":"s_work_han_thu_68_151","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　孟康曰：「雲夢中高唐之臺，宋玉所賦者，言其高出雲之陽也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_68_152","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　師古曰：「泊、澹，皆安靜意也。泊音步各反。澹音徒濫反。」","sentenceOrder":152},
  {"id":"s_work_han_thu_68_153","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　伏儼曰：「勺藥以蘭桂調食。」文穎曰：「五味之和也。」晉灼曰：「南都賦曰『歸雁鳴鵽，香稻鮮魚，以為勺藥，酸甜滋味，百種千名。』文說是也。」師古曰：「諸家之說皆未當也。勺藥，藥草名，其根主和五藏，又辟毒氣，故合之於蘭桂五味以助諸食，因呼五味之和為勺藥耳。讀賦之士不得其意，妄為音訓，以誤後學。今人食馬肝馬腸者，猶合勺藥而煮之，豈非古之遺法乎？鵽音竹滑反。」","sentenceOrder":153},
  {"id":"s_work_han_thu_68_154","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　師古曰：「脟字與臠同。焠音千內反。焠亦搵染之義耳。言臠割其肉，搵車輪鹽而食之。此蓋以譏上割鮮染輪之言也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_68_155","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　師古曰：「殆，近也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_68_156","chapterId":"ch_work_han_thu_68","textTraditional":"烏有先生曰：「是何言之過也！足下不遠千里，來況齊國，〔一〕王悉境內之士，備車騎之眾，〔二〕與使者出田，乃欲戮力致獲，以娛左右也，〔三〕何名為夸哉！問楚地之有無者，願聞大國之風烈，先生之餘論也。〔四〕今足下不稱楚王之德厚，而盛推雲夢以為驕，奢言淫樂而顯侈靡，竊為足下不取也。必若所言，固非楚國之美也。有而言之，是章君之惡也；無而言之，是害足下之信也。章君惡，傷私義，〔五〕二者無一可，而先生行之，必且輕於齊而累於楚矣。〔六〕且齊東陼鉅海，南有琅邪，〔七〕觀乎成山，〔八〕射乎之罘，〔九〕浮勃澥，〔一０〕游孟諸，〔一一〕邪與肅慎為鄰〔一二〕，右以湯谷為界。〔一三〕秋田乎青丘，〔一四〕仿偟乎海外，〔一五〕吞若雲夢者八九，其於匈中曾不蔕芥。〔一六〕若乃俶儻瑰瑋，異方殊類，〔一七〕珍怪鳥獸，萬端鱗崒，〔一八〕充仞其中者，不可勝記，禹不能名，卨不能計。〔一九〕然在諸侯之位，不敢言游戲之樂，苑囿之大；先生又見客，〔二０〕是以王辭不復，〔二一〕何為無以應哉！」","sentenceOrder":156},
  {"id":"s_work_han_thu_68_157","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　師古曰：「言有惠賜而來也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_68_158","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　師古曰：「悉，盡也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_68_159","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　師古曰：「謙不斥言使者，故指云其左右也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_68_160","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　張晏曰：「願聞先賢之遺談美論也。」師古曰：「此說非也。先生即謂子虛耳。下又言先生行之，豈先賢也？」","sentenceOrder":160},
  {"id":"s_work_han_thu_68_161","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　師古曰：「非楚國之美，是章君惡；害足下之信，是傷私義也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_68_162","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　師古曰：「言楚使者失辭，自為累重，而於齊無所負檐，故云輕也。累音力瑞反。」","sentenceOrder":162},
  {"id":"s_work_han_thu_68_163","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　蘇林曰：「小州曰陼。」張揖曰：「琅邪，臺名也，在勃海間。」師古曰：「東陼鉅海，東有大海之陼。字與渚同也。」","sentenceOrder":163},
  {"id":"s_work_han_thu_68_164","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　張揖曰：「觀，闕也。成山在東萊不夜縣，於其上築宮闕。」師古曰：「觀音工喚反。」","sentenceOrder":164},
  {"id":"s_work_han_thu_68_165","chapterId":"ch_work_han_thu_68","textTraditional":"〔九〕　晉灼曰：「之罘山在東萊腄縣，射獵其上也。」師古曰：「腄音直瑞反，又音誰。」","sentenceOrder":165},
  {"id":"s_work_han_thu_68_166","chapterId":"ch_work_han_thu_68","textTraditional":"〔一０〕師古曰：「勃澥，海別枝也。澥音蟹。」","sentenceOrder":166},
  {"id":"s_work_han_thu_68_167","chapterId":"ch_work_han_thu_68","textTraditional":"〔一一〕文穎曰：「宋之大澤也，故屬齊。」","sentenceOrder":167},
  {"id":"s_work_han_thu_68_168","chapterId":"ch_work_han_thu_68","textTraditional":"〔一二〕郭璞曰：「肅慎，國名，在海外也。」師古曰：「邪讀為左，謂東北接也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_68_169","chapterId":"ch_work_han_thu_68","textTraditional":"〔一三〕師古曰：「湯谷，日所出也。許慎云熱如湯也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_68_170","chapterId":"ch_work_han_thu_68","textTraditional":"〔一四〕服虔曰：「青丘國在海東三百里。」","sentenceOrder":170},
  {"id":"s_work_han_thu_68_171","chapterId":"ch_work_han_thu_68","textTraditional":"〔一五〕師古曰：「仿音旁。」","sentenceOrder":171},
  {"id":"s_work_han_thu_68_172","chapterId":"ch_work_han_thu_68","textTraditional":"〔一六〕張揖曰：「蔕芥，刺鯁也。」師古曰：「蔕音丑介反。」","sentenceOrder":172},
  {"id":"s_work_han_thu_68_173","chapterId":"ch_work_han_thu_68","textTraditional":"〔一七〕師古曰：「俶儻猶非常也。俶音吐歷反。」","sentenceOrder":173},
  {"id":"s_work_han_thu_68_174","chapterId":"ch_work_han_thu_68","textTraditional":"〔一八〕師古曰：「崒與萃同。萃，集也。如鱗之集，言其多也。」","sentenceOrder":174},
  {"id":"s_work_han_thu_68_175","chapterId":"ch_work_han_thu_68","textTraditional":"〔一九〕張揖曰：「禹為堯司空，辨九州名山，別草木。卨為堯司徒，敷五教，率萬事。」師古曰：「言其所有眾多，雖禹、卨之賢聖，不能名而數之也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_68_176","chapterId":"ch_work_han_thu_68","textTraditional":"〔二０〕師古曰：「見猶至也。言至此國為客也。若今人自稱云見顧見至耳。」","sentenceOrder":176},
  {"id":"s_work_han_thu_68_177","chapterId":"ch_work_han_thu_68","textTraditional":"〔二一〕師古曰：「復，反也，謂不反報也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_68_178","chapterId":"ch_work_han_thu_68","textTraditional":"亡是公听然而笑曰：〔一〕「楚則失矣，而齊亦未為得也。夫使諸侯納貢者，非為財幣，所以述職也；〔二〕封彊畫界者，非為守禦，所以禁淫也。〔三〕今齊列為東蕃，而外私肅慎，〔四〕捐國隃限，越海而田，〔五〕其於義固未可也。且二君之論，不務明君臣之義，正諸侯之禮，徒事爭於游戲之樂，苑囿之大，欲以奢侈相勝，荒淫相越，此不可以揚名發譽，而適足以貶君自損也。〔六〕","sentenceOrder":178},
  {"id":"s_work_han_thu_68_179","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　師古曰：「听，笑貌也。音齗，又音牛隱反。」","sentenceOrder":179},
  {"id":"s_work_han_thu_68_180","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　郭璞曰：「諸侯朝於天子曰述職。」師古曰：「述，循也，謂順行也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_68_181","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　郭璞曰：「天下有道，守在四夷。立境界者，欲以禁絕淫放耳。」師古曰：「彊讀曰疆。」","sentenceOrder":181},
  {"id":"s_work_han_thu_68_182","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　郭璞曰：「私與通也。」","sentenceOrder":182},
  {"id":"s_work_han_thu_68_183","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　師古曰：「捐，棄也，謂田於青丘也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_68_184","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　師古曰：「{臼寸}，古貶字。」","sentenceOrder":184},
  {"id":"s_work_han_thu_68_185","chapterId":"ch_work_han_thu_68","textTraditional":"「且夫齊楚之事又烏足道乎！〔一〕君未睹夫巨麗也，〔二〕獨不聞天子之上林乎？左蒼梧，右西極，〔三〕丹水更其南，〔四〕紫淵徑其北。〔五〕終始霸產，出入涇渭，〔六〕酆鎬潦潏，紆餘委蛇，經營其內。〔七〕蕩蕩乎八川分流，相背異態，〔八〕東西南北，馳騖往來，〔九〕出乎椒丘之闕，〔一０〕行乎州淤之浦，〔一一〕徑乎桂林之中，〔一二〕過乎泱莽之野，〔一三〕汨乎混流，順阿而下，〔一四〕赴隘陿之口，〔一五〕觸穹石，激堆埼，〔一六〕沸乎暴怒，〔一七〕洶涌彭湃，〔一八〕滭弗宓汨，〔一九〕偪側泌瀄，〔二０〕潢流逆折，轉騰潎洌，〔二一〕滂濞沆溉，〔二二〕穹隆雲橈，〔二三〕宛潬膠盭，〔二四〕踰波趨浥，蒞蒞下瀨，〔二五〕批巖衝擁，奔揚滯沛，〔二六〕臨坻注壑，瀺灂霣隊，〔二七〕沈沈隱隱，砰磅訇磕，〔二八〕潏潏淈淈，湁潗鼎沸，〔二九〕馳波跳沫，汨〈氵急〉漂疾，〔三０〕悠遠長懷，寂漻無聲，〔三一〕肆乎永歸。然後灝溔潢漾，〔三二〕安翔徐佪，〔三三〕翯乎滈滈，〔三四〕東注大湖，〔三五〕衍溢陂池。〔三六〕於是蛟龍赤螭，〔三七〕〈魚恒〉〈魚瞢〉漸離，〔三八〕鰅鰫鰬魠，〔三九〕禺禺魼鰨，〔四０〕揵鰭掉尾，振鱗奮翼，〔四一〕潛處乎深巖。〔四二〕魚鱉讙聲，萬物眾夥〔四三〕。明月珠子，的皪江靡，〔四四〕蜀石黃碝，水玉磊砢，〔四五〕磷磷爛爛，采色澔汗，〔四六〕叢積乎其中。〈工鳥〉鷫鵠鴇，鴐鵝屬玉，〔四七〕交精旋目，〔四八〕煩鶩庸渠，〔四九〕箴疵鵁盧，〔五０〕群浮乎其上。汎淫氾濫，隨風澹淡，〔五一〕與波搖蕩，奄薄水陼，〔五二〕唼喋菁藻，咀嚼菱藕。〔五三〕","sentenceOrder":185},
  {"id":"s_work_han_thu_68_186","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　師古曰：「烏，於何也。道，言也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_68_187","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　師古曰：「巨，大也。麗，美也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_68_188","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　文穎曰：「蒼梧郡屬交州，在長安東南，故言左。爾雅曰西至于豳國為西極，在長安西，故言右也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_68_189","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　應劭曰：「丹水出上洛冢領山，東南至析縣入鈞水。」師古曰：「更，歷也，音工衡反。」","sentenceOrder":189},
  {"id":"s_work_han_thu_68_190","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　文穎曰：「西河（有）穀羅縣有紫澤，在縣西北，於長安為在北也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_68_191","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　師古曰：「霸水出藍田谷，西北而入渭。產水亦出藍田谷，北至霸陵入霸。二水終始盡於苑中，不復出也。涇水出安定涇陽开頭山，東至陽陵入渭。渭水出隴西首陽縣鳥鼠同穴山，東北至華陰入河。從苑外來，又出苑去也。开音牽，又音口見反。」","sentenceOrder":191},
  {"id":"s_work_han_thu_68_192","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　應劭曰：「潦，流也。潏，涌出聲也。」張揖曰：「豐水出鄠南山（灃）〔豐〕谷，北入渭。鎬在昆明池北。潦，行潦也。又有潏水，出南山。」晉灼曰：「下言八川，計從丹水以下至潏，除潦為行潦，凡九川。從霸產以下，為數凡七川。潏音決。潏，水涌出聲也。除潦潏下為水，餘適八，下言經營其內，於數則計其外者矣。」師古曰：「應、晉二說皆非也。張言潦為行潦，又失之。潦音牢，亦水名也，出鄠縣西南山潦谷，而北流入於渭。上言左蒼梧，右西極，丹水更其南，紫泉徑其北。皆謂苑外耳。丹水、紫泉非八川數也。霸、產、涇、渭、豐、鎬、潦、潏，是為八川。言經營其內，信則然矣。潏，晉音是也。地里志鄠縣有潏水，北過上林苑入渭，而今之鄠縣則無此水。許慎云『潏水在京兆杜陵』，此即今所謂沈水，從皇子陂西北流經昆明池入渭者也。蓋為字或作水旁穴，與沈字相似，俗人因名沈水乎？將鄠縣潏水今則改名，人不識也？但八川之義，實在於斯耳。」","sentenceOrder":192},
  {"id":"s_work_han_thu_68_193","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　郭璞曰：「變態不同也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_68_194","chapterId":"ch_work_han_thu_68","textTraditional":"〔九〕　郭璞曰：「言更相錯涉也。」師古曰：「來音盧代反。」","sentenceOrder":194},
  {"id":"s_work_han_thu_68_195","chapterId":"ch_work_han_thu_68","textTraditional":"〔一０〕服虔曰：「丘名也，兩山俱起，象雙闕者。」","sentenceOrder":195},
  {"id":"s_work_han_thu_68_196","chapterId":"ch_work_han_thu_68","textTraditional":"〔一一〕師古曰：「水中可居者曰州。淤，漫也。浦，水涯也。淤音於庶反。」","sentenceOrder":196},
  {"id":"s_work_han_thu_68_197","chapterId":"ch_work_han_thu_68","textTraditional":"〔一二〕如淳曰：「桂樹之林也。」","sentenceOrder":197},
  {"id":"s_work_han_thu_68_198","chapterId":"ch_work_han_thu_68","textTraditional":"〔一三〕張揖曰：「山海經所謂『大荒之野』也。」師古曰：「凡言此者，著水流之長遠也。泱音烏朗反。」","sentenceOrder":198},
  {"id":"s_work_han_thu_68_199","chapterId":"ch_work_han_thu_68","textTraditional":"〔一四〕師古曰：「汨，疾貌也。混流，豐流也。曲陵曰阿。汨音于筆反。混音下本反。」","sentenceOrder":199},
  {"id":"s_work_han_thu_68_200","chapterId":"ch_work_han_thu_68","textTraditional":"〔一五〕師古曰：「兩岸間相迫近者也。隘音於懈反。陿音狹。」","sentenceOrder":200},
  {"id":"s_work_han_thu_68_201","chapterId":"ch_work_han_thu_68","textTraditional":"〔一六〕張揖曰：「穹石，大石也。埼，曲岸頭也。」師古曰：「堆，高阜也，音丁回反。埼音巨依反。」","sentenceOrder":201},
  {"id":"s_work_han_thu_68_202","chapterId":"ch_work_han_thu_68","textTraditional":"〔一七〕郭璞曰：「沸，水聲也，音拂。」","sentenceOrder":202},
  {"id":"s_work_han_thu_68_203","chapterId":"ch_work_han_thu_68","textTraditional":"〔一八〕師古曰：「洶涌，跳起也。彭湃，相戾也。洶音許勇反。湃音普拜反。」","sentenceOrder":203},
  {"id":"s_work_han_thu_68_204","chapterId":"ch_work_han_thu_68","textTraditional":"〔一九〕蘇林曰：「滭音畢。宓音密。」師古曰：「滭弗，盛貌也。宓汨，去疾也。汨音于筆反。」","sentenceOrder":204},
  {"id":"s_work_han_thu_68_205","chapterId":"ch_work_han_thu_68","textTraditional":"〔二０〕郭璞曰：「泌瀄音筆櫛。」師古曰：「偪側，相逼也。泌瀄相楔也。偪字與逼同。楔音先結反。」","sentenceOrder":205},
  {"id":"s_work_han_thu_68_206","chapterId":"ch_work_han_thu_68","textTraditional":"〔二一〕孟康曰：「轉騰，相過也。潎洌，相撇也。」師古曰：「潎音匹列反。洌音列。撇又音普結反。」","sentenceOrder":206},
  {"id":"s_work_han_thu_68_207","chapterId":"ch_work_han_thu_68","textTraditional":"〔二二〕郭璞曰：「滂音旁。濞音匹祕反。溉音胡慨反。皆水流聲貌。」師古曰：「沆音胡朗反。」","sentenceOrder":207},
  {"id":"s_work_han_thu_68_208","chapterId":"ch_work_han_thu_68","textTraditional":"〔二三〕師古曰：「橈，曲也。言水急旋回，如雲之屈曲也。橈音女教反。」","sentenceOrder":208},
  {"id":"s_work_han_thu_68_209","chapterId":"ch_work_han_thu_68","textTraditional":"〔二四〕郭璞曰：「憤薄相樛也。」師古曰：「宛音婉。潬音善。盭，古戾字。」","sentenceOrder":209},
  {"id":"s_work_han_thu_68_210","chapterId":"ch_work_han_thu_68","textTraditional":"〔二五〕郭璞曰：「踰，躍也。浥，窊陷也。蒞蒞，聲也。」師古曰：「浥音於俠反。蒞音利。瀨，疾流也。」","sentenceOrder":210},
  {"id":"s_work_han_thu_68_211","chapterId":"ch_work_han_thu_68","textTraditional":"〔二六〕師古曰：「批，反擊也。擁，曲隈也。言水觸批巖崖而衝隈曲，則奔揚而滯沛然也。批音步結反。滯音丑制反。沛音普蓋反。」","sentenceOrder":211},
  {"id":"s_work_han_thu_68_212","chapterId":"ch_work_han_thu_68","textTraditional":"〔二七〕師古曰：「坻謂水中隆高處也。秦風終南之詩曰『宛在水中坻』。坻音遲，瀺音士咸反。灂音才弱反，又音仕角反。霣即隕字。隊音直類反。」","sentenceOrder":212},
  {"id":"s_work_han_thu_68_213","chapterId":"ch_work_han_thu_68","textTraditional":"〔二八〕師古曰：「砰音普冰反。磅音普萌反。訇音呼宏反。磕音口蓋反。皆水流鼓怒之聲也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_68_214","chapterId":"ch_work_han_thu_68","textTraditional":"〔二九〕郭璞曰：「皆水微轉細涌貌也。淈音骨。湁音敕立反。」師古曰：「潏音決。潗音子入反。言水之流如爨鼎沸也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_68_215","chapterId":"ch_work_han_thu_68","textTraditional":"〔三０〕晉灼曰：「〈氵急〉音華給反。」郭璞曰：「〈氵急〉音許立反。」師古曰：「言水波急馳而白沫跳起，（淚）〔汨〕〈氵急〉然也。汨音于筆反。〈氵急〉，晉、郭二音皆通。漂音匹姚反。」","sentenceOrder":215},
  {"id":"s_work_han_thu_68_216","chapterId":"ch_work_han_thu_68","textTraditional":"〔三一〕郭璞曰：「懷亦歸，變文耳。漻音聊。」師古曰：「言長流安靜。」","sentenceOrder":216},
  {"id":"s_work_han_thu_68_217","chapterId":"ch_work_han_thu_68","textTraditional":"〔三二〕郭璞曰：「皆水無涯際貌。」師古曰：「灝音浩。溔音弋少反。潢音胡廣反。漾音弋丈反。肆，放也。言水放流而長歸也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_68_218","chapterId":"ch_work_han_thu_68","textTraditional":"〔三三〕郭璞曰：「言運轉也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_68_219","chapterId":"ch_work_han_thu_68","textTraditional":"〔三四〕郭璞曰：「水白光貌也。」師古曰：「翯音胡角反。滈音鎬。」","sentenceOrder":219},
  {"id":"s_work_han_thu_68_220","chapterId":"ch_work_han_thu_68","textTraditional":"〔三五〕郭璞曰：「大湖在吳縣，尚書所謂震澤也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_68_221","chapterId":"ch_work_han_thu_68","textTraditional":"〔三六〕郭璞曰：「言湓溢而出也。陂池，江旁小水。」","sentenceOrder":221},
  {"id":"s_work_han_thu_68_222","chapterId":"ch_work_han_thu_68","textTraditional":"〔三七〕文穎曰：「龍子為螭。」張揖曰：「赤螭，雌龍也。」如淳曰：「螭，山神也，獸形。」師古曰：「許慎云『离，山神也』，字則單作，螭形若龍，字乃從虫。此作螭，別是一物，既非山神，又非雌龍、龍子，三家之說皆失之。虫音許尾反。」","sentenceOrder":222},
  {"id":"s_work_han_thu_68_223","chapterId":"ch_work_han_thu_68","textTraditional":"〔三八〕李奇曰：「周洛曰鮪，蜀曰〈魚恒〉〈魚瞢〉，出鞏山穴中，三月遡河上，能度龍門之限，則得為龍矣。漸離，未聞。」師古曰：「〈魚恒〉音工鄧反。〈魚瞢〉音莫鄧反。」","sentenceOrder":223},
  {"id":"s_work_han_thu_68_224","chapterId":"ch_work_han_thu_68","textTraditional":"〔三九〕如淳曰：「鰅音顒。鰬音乾。魠音託。」郭璞曰：「鰫音常容反。鰅魚有文采。鰫似鰱而黑。鰬似鱓。魠，鰔也，一名黃頰。」師古曰：「鰅，如音是也。鰫、鰬、魠，郭說是也。鱓音善。鰔音感也。」","sentenceOrder":224},
  {"id":"s_work_han_thu_68_225","chapterId":"ch_work_han_thu_68","textTraditional":"〔四０〕如淳曰：「魼音去魚反。」晉灼曰：「鰨音奴搨反。」郭璞曰：「禺禺魚皮有毛，黃地黑文。魼，比目魚也，狀似牛脾，細鱗紫色，兩相合乃得行。鰨，鯢魚也，似鮎，有四足，聲如嬰兒。」師古曰：「禺音隅，又音顒。鯢音五奚反。鮎音乃兼反。」","sentenceOrder":225},
  {"id":"s_work_han_thu_68_226","chapterId":"ch_work_han_thu_68","textTraditional":"〔四一〕師古曰：「揵，舉也。鰭，魚背上鬣也。掉，搖也。揵音鉅言反。掉音徒釣反。」","sentenceOrder":226},
  {"id":"s_work_han_thu_68_227","chapterId":"ch_work_han_thu_68","textTraditional":"〔四二〕郭璞曰：「隱岸底也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_68_228","chapterId":"ch_work_han_thu_68","textTraditional":"〔四三〕師古曰：「讙，譁也。夥，多也。讙音許元反。夥音下果反。」","sentenceOrder":228},
  {"id":"s_work_han_thu_68_229","chapterId":"ch_work_han_thu_68","textTraditional":"〔四四〕應劭曰：「明月珠子生於江中，其光耀乃照於江邊也。」師古曰：「皪音歷。的皪，光貌也。江靡，江邊靡迆之處也。迆音弋爾反。」","sentenceOrder":229},
  {"id":"s_work_han_thu_68_230","chapterId":"ch_work_han_thu_68","textTraditional":"〔四五〕張揖曰：「蜀石，石次玉者也。」郭璞曰：「碝石黃色。水玉，水精也。」師古曰：「碝音如兗反。磊音洛賄反。砢音洛可反，又音可。」","sentenceOrder":230},
  {"id":"s_work_han_thu_68_231","chapterId":"ch_work_han_thu_68","textTraditional":"〔四六〕郭璞曰：「皆玉石符采映曜也。」師古曰：「磷音〈恡，去“忄”〉。澔音浩。」","sentenceOrder":231},
  {"id":"s_work_han_thu_68_232","chapterId":"ch_work_han_thu_68","textTraditional":"〔四七〕張揖曰：「〈工鳥〉，大鳥也。」郭璞曰：「鷫，鷫鷞也。鴇似雁而無後指。屬玉似鴨而大，長頸赤目，紫紺色。鷫音肅。鴇音保。」師古曰：「〈工鳥〉，古鴻字。鴇即今俗呼為獨豹者也。豹者，鴇聲之訛耳。鴐音加。屬音之欲反。鷞音霜。」","sentenceOrder":232},
  {"id":"s_work_han_thu_68_233","chapterId":"ch_work_han_thu_68","textTraditional":"〔四八〕郭璞曰：「交精似鳧而腳高，有毛冠，辟火災。旋目，未聞也。」師古曰：「今荊郢間有水鳥，大於鷺而短尾，其色紅白。深目，目旁毛皆長而旋，此其旋目乎？」","sentenceOrder":233},
  {"id":"s_work_han_thu_68_234","chapterId":"ch_work_han_thu_68","textTraditional":"〔四九〕郭璞曰：「煩鶩，鴨屬也。庸渠似鳧，灰色而雞腳，一名章渠。鶩音木。」師古曰：「庸渠，即今之水雞也。」","sentenceOrder":234},
  {"id":"s_work_han_thu_68_235","chapterId":"ch_work_han_thu_68","textTraditional":"〔五０〕張揖曰：「箴疪似魚虎而蒼黑色。鵁，〈暂缺F52A〉頭鳥也。盧，白雉也。」郭璞曰：「盧，盧鷀也。箴音針。」師古曰：「盧，郭說是也。白雉不浮水上。疪音貲。鵁音火交反。〈暂缺F52A〉音鳥了反。鷀音慈也。」","sentenceOrder":235},
  {"id":"s_work_han_thu_68_236","chapterId":"ch_work_han_thu_68","textTraditional":"〔五一〕郭璞曰：「皆鳥任風波自縱漂貌。」師古曰：「汎音馮。氾音敷劍反。澹音大覽反。淡音琰。」","sentenceOrder":236},
  {"id":"s_work_han_thu_68_237","chapterId":"ch_work_han_thu_68","textTraditional":"〔五二〕張揖曰：「奄，覆也。草叢生曰薄。」郭璞曰：「薄猶集也。」師古曰：「薄，郭說是也。言奄集陼上而遊戲。」","sentenceOrder":237},
  {"id":"s_work_han_thu_68_238","chapterId":"ch_work_han_thu_68","textTraditional":"〔五三〕張揖曰：「菱，芰也。」郭璞曰：「菁，水草。藻，聚藻也。」師古曰：「唼喋，銜食也。唼音所甲反。喋音丈甲反。咀音才汝反。嚼音才削反。」","sentenceOrder":238},
  {"id":"s_work_han_thu_68_239","chapterId":"ch_work_han_thu_68","textTraditional":"「於是乎崇山矗矗，巃嵷崔巍，〔一〕深林巨木，嶄巖參差。〔二〕九嵕巀嶭，南山峨峨，〔三〕巖阤甗錡，{山椎}崣崛崎，〔四〕振溪通谷，蹇產溝瀆，〔五〕〈谷今〉呀豁閜，阜陵別隝，〔六〕崴磈嵔廆，丘虛堀礨，〔七〕隱轔鬱〈山壘〉，登降施靡，〔八〕陂池貏豸。〔九〕允溶淫鬻，〔一０〕散渙夷陸，〔一一〕亭皋千里，靡不被築。〔一二〕揜以綠蕙，〔一三〕被以江離，糅以蘼蕪，雜以留夷。〔一四〕布結縷，〔一五〕攢戾莎，〔一六〕揭車衡蘭，〔一七〕稿本射干，〔一八〕茈薑蘘荷，〔一九〕葴持若蓀，〔二０〕鮮支黃礫，〔二一〕蔣芧青薠，〔二二〕布濩閎澤，延曼太原，〔二三〕離靡廣衍〔二四〕，應風披靡，吐芳揚烈，〔二五〕郁郁菲菲，眾香發越，〔二六〕肸蠁布寫，晻薆咇茀。〔二七〕","sentenceOrder":239},
  {"id":"s_work_han_thu_68_240","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　郭璞曰：「皆高峻貌也。巃音籠。嵷音才總反。崔音摧。魏音五回反。」師古曰：「嵷音總。」","sentenceOrder":240},
  {"id":"s_work_han_thu_68_241","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　師古曰：「嶄巖，尖銳貌。參差，不齊也。嶄音士銜反。參音楚林反。差音楚宜反。」","sentenceOrder":241},
  {"id":"s_work_han_thu_68_242","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　師古曰：「九嵕山今在醴泉縣界。巀嶭山即今所謂嵯峨山也，在三原縣西也。南山，終南山也。峨峨，高貌。嵕音子公反，又音總。巀音〈雀戈〉。嶭音齧。巀嶭又音在割、五割反。峨音娥。」","sentenceOrder":242},
  {"id":"s_work_han_thu_68_243","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　張揖曰：「{山椎}崣，高貌。崛崎，斗絕也。」蘇林曰：「{山椎}音赬水反。崣音卒鄙反。」郭璞曰：「阤，岸際也，音豸。甗錡，隆屈窊折貌。甗音魚晚反。錡音嶬。崛音掘。崎音倚。{山椎}音作罪反。崣字作委。」師古曰：「蘇、郭兩說並通。郭音作罪反，又音將水反。」","sentenceOrder":243},
  {"id":"s_work_han_thu_68_244","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　張揖曰：「振，拔也。水注川曰溪，注溪曰谷。蹇產，屈折也。」郭璞曰：「自溪及瀆，皆水相通注也。」","sentenceOrder":244},
  {"id":"s_work_han_thu_68_245","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　郭璞曰：「〈谷今〉呀豁閜，澗谷之形容也。隝，水中山也。〈谷今〉音呼含反。呀音呼加反。閜音呼下反。隝音擣。」師古曰：「大阜曰陵，言阜陵居在水中，各別為隝也。豁音呼活反。」","sentenceOrder":245},
  {"id":"s_work_han_thu_68_246","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　郭璞曰：「皆其形勢也。崴音於鬼反。磈音魚鬼反。嵔音惡罪反。廆音瘣。虛音墟。堀音窟。礨音磊。」師古曰：「磈又音於虺反。廆音胡賄反。」","sentenceOrder":246},
  {"id":"s_work_han_thu_68_247","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　郭璞曰：「隱轔鬱壘，堆壟不平貌。轔音洛盡反。」師古曰：「壘音律。施音弋爾反。施靡，猶連延也。」","sentenceOrder":247},
  {"id":"s_work_han_thu_68_248","chapterId":"ch_work_han_thu_68","textTraditional":"〔九〕　郭璞曰：「陂池，旁穨貌也。陂音皮。貏音衣被之被。」師古曰：「陂又音彼奇反。貏又音彼。」","sentenceOrder":248},
  {"id":"s_work_han_thu_68_249","chapterId":"ch_work_han_thu_68","textTraditional":"〔一０〕張揖曰：「水流溪谷之間也。」師古曰：「溶音容。鬻音育。」","sentenceOrder":249},
  {"id":"s_work_han_thu_68_250","chapterId":"ch_work_han_thu_68","textTraditional":"〔一一〕師古曰：「散渙，分散而渙然也。易曰『風行水上，渙』。夷，平也。廣平曰陸。」","sentenceOrder":250},
  {"id":"s_work_han_thu_68_251","chapterId":"ch_work_han_thu_68","textTraditional":"〔一二〕師古曰：「為亭候於皋隰之中，千里相接，皆築令平也。被音皮義反。」","sentenceOrder":251},
  {"id":"s_work_han_thu_68_252","chapterId":"ch_work_han_thu_68","textTraditional":"〔一三〕張揖曰：「掩，覆也。綠，王芻也。蕙，薰草也。」師古曰：「綠蕙，言蕙草色綠耳，非王芻也。」","sentenceOrder":252},
  {"id":"s_work_han_thu_68_253","chapterId":"ch_work_han_thu_68","textTraditional":"〔一四〕張揖曰：「留夷，新夷也。」師古曰：「留夷，香草也，非新夷。新夷乃樹耳。」","sentenceOrder":253},
  {"id":"s_work_han_thu_68_254","chapterId":"ch_work_han_thu_68","textTraditional":"〔一五〕師古曰：「結縷蔓生，著地之處皆生細根，如線相結，故名結縷，今俗呼鼓箏草。兩幼童對銜之，手鼓中央，則聲如箏也，因以名云。」","sentenceOrder":254},
  {"id":"s_work_han_thu_68_255","chapterId":"ch_work_han_thu_68","textTraditional":"〔一六〕師古曰：「攢，聚也。戾莎，言莎草相交戾也。攢音材官反。」","sentenceOrder":255},
  {"id":"s_work_han_thu_68_256","chapterId":"ch_work_han_thu_68","textTraditional":"〔一七〕應劭曰：「揭車一名{艹乞}輿，香草也。」師古曰：「揭音巨列反。{艹乞}音乞。」","sentenceOrder":256},
  {"id":"s_work_han_thu_68_257","chapterId":"ch_work_han_thu_68","textTraditional":"〔一八〕師古曰：「稿本，草類白芷，根似芎藭。射干，即烏扇耳。射音弋舍反。」","sentenceOrder":257},
  {"id":"s_work_han_thu_68_258","chapterId":"ch_work_han_thu_68","textTraditional":"〔一九〕如淳曰：「茈薑，薑上齊也。」師古曰：「薑之息生者，連其株本，則紫色也。蘘荷，蒪苴也，根旁生筍，可以為葅，又治蠱毒。茈音紫。蘘音人羊反。」","sentenceOrder":258},
  {"id":"s_work_han_thu_68_259","chapterId":"ch_work_han_thu_68","textTraditional":"〔二０〕如淳曰：「葴音鍼。」張揖曰：「葴持闕。若，杜若也。蓀，香草也。」師古曰：「葴，寒漿也。持當為符，字之誤耳。符，鬼目也。杜若苗頗類薑，而為棕葉之狀。今流俗書本持字或作橙，非也。後人妄改耳。其下乃言黃甘橙榛，此無橙也。葴音之林反。蓀音孫。」","sentenceOrder":259},
  {"id":"s_work_han_thu_68_260","chapterId":"ch_work_han_thu_68","textTraditional":"〔二一〕師古曰：「鮮支，即今支子樹也。黃礫，今用染者黃屑之木也。二者雖非草類，既云延曼太原，或者賦雜言之耳。」","sentenceOrder":260},
  {"id":"s_work_han_thu_68_261","chapterId":"ch_work_han_thu_68","textTraditional":"〔二二〕張揖曰：「蔣，菰也。芧，三稜也。」郭璞曰：「芧音杼。」師古曰：「蔣音將。芧音丈與反。」","sentenceOrder":261},
  {"id":"s_work_han_thu_68_262","chapterId":"ch_work_han_thu_68","textTraditional":"〔二三〕郭璞曰：「布濩猶布露也。」師古曰：「閎亦大也。濩音護。延音弋戰反。」","sentenceOrder":262},
  {"id":"s_work_han_thu_68_263","chapterId":"ch_work_han_thu_68","textTraditional":"〔二四〕師古曰：「離靡，謂相連不絕也。衍，布也。離音力爾反。」","sentenceOrder":263},
  {"id":"s_work_han_thu_68_264","chapterId":"ch_work_han_thu_68","textTraditional":"〔二五〕師古曰：「烈，酷烈之氣也。披音丕蟻反。」","sentenceOrder":264},
  {"id":"s_work_han_thu_68_265","chapterId":"ch_work_han_thu_68","textTraditional":"〔二六〕郭璞曰：「香氣射散也。菲音妃。」","sentenceOrder":265},
  {"id":"s_work_han_thu_68_266","chapterId":"ch_work_han_thu_68","textTraditional":"〔二七〕師古曰：「肸蠁，盛作也。寫，吐也。晻薆咇茀，皆芳香意也。肸音許乙反。蠁音響。晻音奄，又音烏感反。薆音愛。咇音步必反。茀音勃。薆字或作隱也。」","sentenceOrder":266},
  {"id":"s_work_han_thu_68_267","chapterId":"ch_work_han_thu_68","textTraditional":"「於是乎周覽氾觀，〔一〕縝紛軋芴，〔二〕芒芒怳忽〔三〕，視之無端，察之無涯。〔四〕日出東沼，入虖西陂。〔五〕其南則隆冬生長，涌水躍波；〔六〕其獸則庸旄貘犛，沈牛麈麋，〔七〕赤首圜題，窮奇象犀。〔八〕其北則盛夏含凍裂地，涉冰揭河；〔九〕其獸則麒麟角端，騊駼橐駝，〔一０〕蛩蛩驒騱，駃騠驢〈馬羸〉。〔一一〕","sentenceOrder":267},
  {"id":"s_work_han_thu_68_268","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　師古曰：「氾，普也，音敷劍反。」","sentenceOrder":268},
  {"id":"s_work_han_thu_68_269","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　孟康曰：「縝紛，眾盛也。軋芴，緻密也。」師古曰：「縝音丑人反。軋音於黠反。芴音勿。」","sentenceOrder":269},
  {"id":"s_work_han_thu_68_270","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　郭璞曰：「言眼亂也。」師古曰：「芒音莫郎反。」","sentenceOrder":270},
  {"id":"s_work_han_thu_68_271","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　師古曰：「涯，畔也，音儀。」","sentenceOrder":271},
  {"id":"s_work_han_thu_68_272","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　張揖曰：「朝出苑之東池，莫入於苑西陂中也。」","sentenceOrder":272},
  {"id":"s_work_han_thu_68_273","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　師古曰：「言其土地氣溫，經冬草木不死，水不凍。」","sentenceOrder":273},
  {"id":"s_work_han_thu_68_274","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　張揖曰：「旄，旄牛，其狀如牛而四節毛。犛牛黑色，出西南徼外。沈牛，水牛也，能沈沒水中。麈似鹿而大。」郭璞曰：「庸牛，領有肉堆。貘似熊，庳腳銳{髟者}，骨無髓，食銅鐵。貘音貊，犛音貍。」師古曰：「庸牛即今之犎牛也。旄牛即今所謂偏牛者也。犛牛即今之貓牛者也。犛字又音茅。麈音主。」","sentenceOrder":274},
  {"id":"s_work_han_thu_68_275","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　張揖曰：「題，額也。窮奇狀如牛而蝟毛，其音如嗥狗，食人。」師古曰：「象，大獸也，長鼻，牙長一丈。犀頭似豬，一角在鼻，一角在額前。」","sentenceOrder":275},
  {"id":"s_work_han_thu_68_276","chapterId":"ch_work_han_thu_68","textTraditional":"〔九〕　師古曰：「言其土地氣寒，當暑凝凍，地為之裂，故涉冰而渡河也。揭，搴衣也。詩邶風匏有苦葉之篇曰『深則厲，淺則揭』，揭音丘例反。」","sentenceOrder":276},
  {"id":"s_work_han_thu_68_277","chapterId":"ch_work_han_thu_68","textTraditional":"〔一０〕張揖曰：「雄曰麒，雌曰麟，其狀麋身牛尾，狼題一角，角端似牛，其角可以為弓。」郭璞曰：「麒似麟而無角，角端似豬，角在鼻上，中作弓。」師古曰：「麒麟角端，郭說是也。橐駝者，言其可負橐囊而駝物，故以名云。」","sentenceOrder":277},
  {"id":"s_work_han_thu_68_278","chapterId":"ch_work_han_thu_68","textTraditional":"〔一一〕郭璞曰：「驒騱，駏驉類也。駃騠生三日而超其母。驒音顛。騱音奚。駃音決。騠音提。」","sentenceOrder":278},
  {"id":"s_work_han_thu_68_279","chapterId":"ch_work_han_thu_68","textTraditional":"「於是乎離宮別館，彌山跨谷，〔一〕高廊四注，重坐曲閣，〔二〕華榱璧璫，輦道纚屬，〔三〕步櫩周流，長途中宿。〔四〕夷嵕築堂，絫臺增成，〔五〕巖突洞房。〔六〕頫杳眇而無見，仰攀橑而捫天，〔七〕奔星更於閨闥，宛虹拖於楯軒。〔八〕青龍蚴蟉於東箱，象輿婉僤於西清，〔九〕靈圉燕於閒館，〔一０〕偓佺之倫暴於南榮，〔一一〕醴泉涌於清室，通川過於中庭。〔一二〕磐石裖崖，〔一三〕嶔巖倚傾，〔一四〕嵯峨〈山集〉嶪，刻削崢嶸，〔一五〕玫瑰碧琳，珊瑚叢生，〔一六〕珉玉旁唐，玢豳文磷，〔一七〕赤瑕駁犖，雜臿其間，〔一八〕晁采琬琰，和氏出焉。〔一九〕","sentenceOrder":279},
  {"id":"s_work_han_thu_68_280","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　師古曰：「彌，滿也。跨猶騎也。」","sentenceOrder":280},
  {"id":"s_work_han_thu_68_281","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　師古曰：「廊，堂下四周屋也。重坐，謂增室也。曲閣，閣之屈曲相連者也。」","sentenceOrder":281},
  {"id":"s_work_han_thu_68_282","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　師古曰：「榱，椽也。華謂彫畫之也。璧璫，以玉為椽頭，當即所謂璇題玉題者也。一曰以玉飾瓦之當也。輦道，謂閣道可以乘輦而行者也。纚屬，纚迤相連屬也。纚音力爾反。屬音之欲反。」","sentenceOrder":282},
  {"id":"s_work_han_thu_68_283","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　師古曰：「步櫩，言其下可行步，即今之步廊也。謂其途長遠，雖經日行之，尚不能達，故中道而宿也。」","sentenceOrder":283},
  {"id":"s_work_han_thu_68_284","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　師古曰：「夷，平也。山之高聚者曰嵕。絫，古累字。言平山而築堂於其上為累臺也。增，重也，一重為一成也。嵕音子公反。」","sentenceOrder":284},
  {"id":"s_work_han_thu_68_285","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　師古曰：「於巖穴底為室，若灶突然，潛通臺上。」","sentenceOrder":285},
  {"id":"s_work_han_thu_68_286","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　師古曰：「頫，古俯字也。杳眇，視遠貌。乑，古攀字也。橑，椽也。捫，摸也。言臺榭之高，有升上之者，俯視則不見地，仰攀其椽可以摸天也。橑音老。捫音門。」","sentenceOrder":286},
  {"id":"s_work_han_thu_68_287","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　師古曰：「奔星，流星也。更，歷也。閨闥，宮中小門也。宛虹，曲屈之虹也。拖謂申加於上也。楯軒，軒之蘭板也。並言室宇之高，故星虹得經加之也。更音工衡反。虹音紅。拖音吐賀反，又（言）〔音〕徒可反。」","sentenceOrder":287},
  {"id":"s_work_han_thu_68_288","chapterId":"ch_work_han_thu_68","textTraditional":"〔九〕　師古曰：「象輿，瑞應車也。西清者，西箱清靜之處也。蚴蟉、婉僤，皆行動之貌。蚴音一糾反。蟉音力糾反。僤音善。」","sentenceOrder":288},
  {"id":"s_work_han_thu_68_289","chapterId":"ch_work_han_thu_68","textTraditional":"〔一０〕張揖曰：「靈圉，眾仙號也。」師古曰：「閒讀曰閑。」","sentenceOrder":289},
  {"id":"s_work_han_thu_68_290","chapterId":"ch_work_han_thu_68","textTraditional":"〔一一〕郭璞曰：「偓佺，仙人也，食松子而眼方。暴謂偃臥日中也。榮，屋南檐也。偓音握。佺音銓。」","sentenceOrder":290},
  {"id":"s_work_han_thu_68_291","chapterId":"ch_work_han_thu_68","textTraditional":"〔一二〕師古曰：「醴泉，瑞水，味甘如醴，言於室中涌出，而通流為川，從中庭而過也。」","sentenceOrder":291},
  {"id":"s_work_han_thu_68_292","chapterId":"ch_work_han_thu_68","textTraditional":"〔一三〕孟康曰：「裖，〈石尔〉致也。崖，廉也。以石致川之廉也。」師古曰：「裖〈石尔〉並音之忍反。致音直二反。謂重密而累積。」","sentenceOrder":292},
  {"id":"s_work_han_thu_68_293","chapterId":"ch_work_han_thu_68","textTraditional":"〔一四〕郭璞曰：「嶔巖，欹貌。」師古曰：「嶔音口銜反。倚音於綺反。」","sentenceOrder":293},
  {"id":"s_work_han_thu_68_294","chapterId":"ch_work_han_thu_68","textTraditional":"〔一五〕蘇林曰：「削音峭峻之峭。崢音儕爭反。嶸音戶抨反。」郭璞曰：「言自然若彫刻也。〈山集〉音昨盍反。嶪音五盍反。」師古曰：「直言刻削耳，非云峭峻。郭說是也。〈山集〉音捷。嶪音業。」","sentenceOrder":294},
  {"id":"s_work_han_thu_68_295","chapterId":"ch_work_han_thu_68","textTraditional":"〔一六〕郭璞曰：「珊瑚生水底石邊，大者（可）〔樹〕高三尺餘，枝格交錯，無有葉。」","sentenceOrder":295},
  {"id":"s_work_han_thu_68_296","chapterId":"ch_work_han_thu_68","textTraditional":"〔一七〕蘇林曰：「玢音分。」郭璞曰：「旁唐言盤礡。玢豳，文理貌。」師古曰：「旁唐，文石也。唐字本作碭，言珉玉及石並玢豳也。玢音彼旻反。豳又音彼閑反。」","sentenceOrder":296},
  {"id":"s_work_han_thu_68_297","chapterId":"ch_work_han_thu_68","textTraditional":"〔一八〕張揖曰：「赤瑕，赤玉也。」郭璞曰：「言雜廁崖石中。駁犖，采點也。犖音洛角反。」","sentenceOrder":297},
  {"id":"s_work_han_thu_68_298","chapterId":"ch_work_han_thu_68","textTraditional":"〔一九〕晉灼曰：「晁采闕。」師古曰：「晁，古朝字也。朝采者，美玉每旦有白虹之氣，光采上出，故名朝采，猶言夜光之璧矣。琬琰，美玉名。和氏之璧，卞和所得，亦美玉也。言今皆出於上林。」","sentenceOrder":298},
  {"id":"s_work_han_thu_68_299","chapterId":"ch_work_han_thu_68","textTraditional":"「於是乎盧橘夏孰，〔一〕黃甘橙楱，〔二〕枇杷橪柿，亭柰厚朴，〔三〕梬棗楊梅，〔四〕櫻桃蒲陶，〔五〕隱夫薁棣，〔六〕荅遝離支，〔七〕羅乎後宮，列乎北園，貤丘陵，下平原，〔八〕揚翠葉，扤紫莖，〔九〕發紅華，垂朱榮，煌煌扈扈，照曜鉅野〔一０〕。沙棠櫟櫧，〔一一〕華楓枰櫨，〔一二〕留落胥邪，仁頻并閭，〔一三〕欃檀木蘭，〔一四〕豫章女貞，〔一五〕長千仞，大連抱，〔一六〕夸條直暢，實葉葰楙，〔一七〕攢立叢倚，連卷欐佹〔一八〕，崔錯癹骫，〔一九〕坑衡閜砢，〔二０〕垂條扶疏，落英幡纚，〔二一〕紛溶萷蔘，猗柅從風，〔二二〕藰蒞芔歙，〔二三〕蓋象金石之聲，管籥之音。〔二四〕柴池茈虒，旋還乎後宮，〔二五〕雜襲絫輯，〔二六〕被山緣谷，循阪下隰，〔二七〕視之無端，究之亡窮。","sentenceOrder":299},
  {"id":"s_work_han_thu_68_300","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　應劭曰：「伊尹書曰『箕山之東，青馬之所，有盧橘夏孰』。」晉灼曰：「此雖賦上林，博引異方珍奇，不係於一也。」師古曰：「盧，黑色也。」","sentenceOrder":300},
  {"id":"s_work_han_thu_68_301","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　郭璞曰：「黃甘，橘屬而味精。楱亦橘之類也，音湊。」張揖曰：「楱，小橘也，出武陵。」師古曰：「橙即柚也，音丈耕反。」","sentenceOrder":301},
  {"id":"s_work_han_thu_68_302","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　張揖曰：「枇杷似斛樹，長葉，子若杏。橪，橪支，香草也。亭，山梨也。厚朴，藥名也。」郭璞曰：「橪支木也。」師古曰：「此二句總論樹木，不得雜以香草也。橪，郭說得之。朴，木皮也。此藥以皮為用，而皮厚，故呼厚朴云。橪音煙。朴音匹角反。」","sentenceOrder":302},
  {"id":"s_work_han_thu_68_303","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　張揖曰：「楊梅，其實似穀子而有核，其味酢，出江南也。」","sentenceOrder":303},
  {"id":"s_work_han_thu_68_304","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　師古曰：「櫻桃，即今之朱櫻也。禮記謂含桃，爾雅謂之荊桃。櫻音於耕反。」","sentenceOrder":304},
  {"id":"s_work_han_thu_68_305","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　師古曰：「隱夫未詳。薁即今之郁李也。棣，今之山櫻桃。薁音於六反。棣音（徙）〔徒〕計反。」","sentenceOrder":305},
  {"id":"s_work_han_thu_68_306","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　張揖曰：「荅遝似李，出蜀。」晉灼曰：「離支大如雞子，皮麤，剝去皮，肌如雞子中黃，味甘多酢少。」師古曰：「遝音沓。離音力智反。」","sentenceOrder":306},
  {"id":"s_work_han_thu_68_307","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　師古曰：「貤猶延也，一曰次第而重也。貤音弋豉反。」","sentenceOrder":307},
  {"id":"s_work_han_thu_68_308","chapterId":"ch_work_han_thu_68","textTraditional":"〔九〕　師古曰：「扤，搖也，音兀。」","sentenceOrder":308},
  {"id":"s_work_han_thu_68_309","chapterId":"ch_work_han_thu_68","textTraditional":"〔一０〕師古曰：「言其光采之盛也。鉅野，大野。煌音皇。」","sentenceOrder":309},
  {"id":"s_work_han_thu_68_310","chapterId":"ch_work_han_thu_68","textTraditional":"〔一一〕張揖曰：「沙棠，狀如棠，黃華赤實，其味似李，無核。呂氏春秋曰『果之美者，沙棠之實』。櫟，果名也。櫧似柃，葉冬不落。」應劭曰：「櫟，采木也。」郭璞曰：「櫧似采柔。」師古曰：「櫟非果名，又非采木之櫟，蓋木蓼也，葉辛，初生可食。櫟音歷。櫧音諸。柃音零。采音菜。柔音食諸反。」","sentenceOrder":310},
  {"id":"s_work_han_thu_68_311","chapterId":"ch_work_han_thu_68","textTraditional":"〔一二〕師古曰：「華即今之皮貼弓者也。楓樹脂可為香，今之楓膠香也。爾雅云一名欇欇。枰即平仲木也。櫨，今黃櫨木也。華音胡化反。楓音風。枰音平。櫨音盧。」","sentenceOrder":311},
  {"id":"s_work_han_thu_68_312","chapterId":"ch_work_han_thu_68","textTraditional":"〔一三〕張揖曰：「并閭，椶也。」郭璞曰：「落，檴也，中作器素。胥邪似并閭，皮可作索。」師古曰：「仁頻即賓桹也。頻字或作賓。胥音先余反。邪音弋奢反。檴音鑊。」","sentenceOrder":312},
  {"id":"s_work_han_thu_68_313","chapterId":"ch_work_han_thu_68","textTraditional":"〔一四〕孟康曰：「欃檀，檀別名。」郭璞曰：「欃音讒。」","sentenceOrder":313},
  {"id":"s_work_han_thu_68_314","chapterId":"ch_work_han_thu_68","textTraditional":"〔一五〕師古曰：「女貞樹冬夏常青，未嘗凋落，若有節操，故以名焉。」","sentenceOrder":314},
  {"id":"s_work_han_thu_68_315","chapterId":"ch_work_han_thu_68","textTraditional":"〔一六〕師古曰：「八尺曰仞。連抱者，言非一人所抱。」","sentenceOrder":315},
  {"id":"s_work_han_thu_68_316","chapterId":"ch_work_han_thu_68","textTraditional":"〔一七〕郭璞曰：「夸，張布也。」張揖曰：「葰，甬也。」師古曰：「暢，通也，通謂上下相稱也。葰音峻。楙，古茂字也。甬音踊。」","sentenceOrder":316},
  {"id":"s_work_han_thu_68_317","chapterId":"ch_work_han_thu_68","textTraditional":"〔一八〕師古曰：「攢立，聚立也。叢倚，相倚也。連卷，屈曲也。欐佹，支柱也。倚音於綺反。卷音丘專反，又音巨專反。欐音力爾反。佹音詭。」","sentenceOrder":317},
  {"id":"s_work_han_thu_68_318","chapterId":"ch_work_han_thu_68","textTraditional":"〔一九〕師古曰：「崔錯，交雜也。癹委，蟠戾也。崔音千賄反。癹音步葛反。骫，古委字。」","sentenceOrder":318},
  {"id":"s_work_han_thu_68_319","chapterId":"ch_work_han_thu_68","textTraditional":"〔二０〕師古曰：「坑衡，徑直貌也。閜砢，相扶持也。坑音口庚反。閜音烏可反。砢音來可反。坑字或作抗，言樹之支幹相抗爭衡也。其義兩通。」","sentenceOrder":319},
  {"id":"s_work_han_thu_68_320","chapterId":"ch_work_han_thu_68","textTraditional":"〔二一〕師古曰：「扶疏，四布也。英謂華也。幡纚，飛揚貌也。纚音山爾反。」","sentenceOrder":320},
  {"id":"s_work_han_thu_68_321","chapterId":"ch_work_han_thu_68","textTraditional":"〔二二〕郭璞曰：「紛溶萷蔘，支竦擢也。猗柅猶阿〈冉阝〉也。萷音蕭。蔘音森。猗音於氏反。柅音諾氏反。」師古曰：「溶音容。萷亦音山交反。」","sentenceOrder":321},
  {"id":"s_work_han_thu_68_322","chapterId":"ch_work_han_thu_68","textTraditional":"〔二三〕師古曰：「林木鼓動之聲也。藰音劉。蒞音利。芔，古卉字也，音諱。歙音翕。」","sentenceOrder":322},
  {"id":"s_work_han_thu_68_323","chapterId":"ch_work_han_thu_68","textTraditional":"〔二四〕師古曰：「金石，謂鐘磬也。管長一尺，圍一寸，六孔無底，籥三孔，並以竹為之。」","sentenceOrder":323},
  {"id":"s_work_han_thu_68_324","chapterId":"ch_work_han_thu_68","textTraditional":"〔二五〕如淳曰：「茈音此。虒音豸。」張揖曰：「柴池，參差也。茈虒，不齊也。」郭璞曰：「柴音差。還，還繞也，音宦。」","sentenceOrder":324},
  {"id":"s_work_han_thu_68_325","chapterId":"ch_work_han_thu_68","textTraditional":"〔二六〕師古曰：「雜襲，相因也。絫輯，重積也。絫，古累字。輯與集同。」","sentenceOrder":325},
  {"id":"s_work_han_thu_68_326","chapterId":"ch_work_han_thu_68","textTraditional":"〔二七〕師古曰：「循，順也。下溼曰隰。」","sentenceOrder":326},
  {"id":"s_work_han_thu_68_327","chapterId":"ch_work_han_thu_68","textTraditional":"「於是乎玄猿素雌，蜼玃飛蠝，〔一〕蛭蜩玃蝚，〔二〕獑胡豰蛫，〔三〕棲息乎其間。長嘯哀鳴，翩幡互經，〔四〕夭蟜枝格，偃蹇杪顛，〔五〕隃絕梁，騰殊榛，〔六〕捷垂條，掉希間，〔七〕牢落陸離，爛漫遠遷。〔八〕","sentenceOrder":327},
  {"id":"s_work_han_thu_68_328","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　張揖曰：「蜼如母猴，卬鼻而長尾。玃似彌猴而大。飛蠝，飛鼠也，其狀如兔而鼠首，以其〈冉頁〉飛。」郭璞曰：「蠝，鼯鼠也，毛紫赤色，飛且生，一名飛生。蜼音贈遺之遺。蠝音誄。」師古曰：「玄猿素雌，言猿之雄者玄黑而雌者白素也。爾雅曰『玃父善顧』也。玃音钁。鼯音吾。」","sentenceOrder":328},
  {"id":"s_work_han_thu_68_329","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　如淳曰：「蛭音質。」張揖曰：「蛭，蟣也。蜩，蟬也。玃蝚，彌猴也。」師古曰：「方言獸屬，而引蛭蟣水蟲，又及蜩蟬，乖於事類，如說非也，但未詳是何獸耳。蝚音乃高反，又音柔，即今所謂戎皮為鞍褥者也。戎音柔，聲之轉耳，非彌猴也。」","sentenceOrder":329},
  {"id":"s_work_han_thu_68_330","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　張揖曰：「獑胡似彌猴，頭上有髦，要以後黑。豰，白狐子也。」郭璞曰：「豰似鼬而大，要以後黃，一名黃要，食彌猴。蛫未聞也。獑音讒。豰音呼穀反。蛫音詭。」師古曰：「豰，郭說是也。」","sentenceOrder":330},
  {"id":"s_work_han_thu_68_331","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　郭璞曰：「互經，互相經過也。」","sentenceOrder":331},
  {"id":"s_work_han_thu_68_332","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　郭璞曰：「皆猿猴在樹共戲姿態也。夭蟜，頻申也。」師古曰：「杪顛，枝上端也。蟜音矯。杪音眇。」","sentenceOrder":332},
  {"id":"s_work_han_thu_68_333","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　師古曰：「絕梁，謂正絕水無橋梁也。殊榛，特立株枿也。言超度無梁之水，而跳上株枿之上也。隃字與踰同。榛音仕人反。枿音五曷反。」","sentenceOrder":333},
  {"id":"s_work_han_thu_68_334","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　張揖曰：「捷持縣垂之條，掉往著稀疏無支之間也。」師古曰：「掉音徒釣反。」","sentenceOrder":334},
  {"id":"s_work_han_thu_68_335","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　師古曰：「言其聚散不恆，雜亂移徙也。」","sentenceOrder":335},
  {"id":"s_work_han_thu_68_336","chapterId":"ch_work_han_thu_68","textTraditional":"「若此者數百千處，娛游往來，宮宿館舍，〔一〕庖廚不徙，後宮不移，百官備具。〔二〕","sentenceOrder":336},
  {"id":"s_work_han_thu_68_337","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　師古曰：「娛，戲也。戲音許其反。」","sentenceOrder":337},
  {"id":"s_work_han_thu_68_338","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　師古曰：「言所在之處供具皆足也。」","sentenceOrder":338},
  {"id":"s_work_han_thu_68_339","chapterId":"ch_work_han_thu_68","textTraditional":"「於是乎背秋涉冬，天子校獵。〔一〕乘鏤象，六玉虯〔二〕，拖蜺旌，〔三〕靡雲旗，〔四〕前皮軒，後道游；〔五〕孫叔奉轡，衛公參乘，〔六〕扈從橫行，出乎四校之中。〔七〕鼓嚴簿，縱獵者，〔八〕江河為阹，泰山為櫓，〔九〕車騎雷起，殷天動地〔一０〕，先後陸離，離散別追，〔一一〕淫淫裔裔，緣陵流澤，雲布雨施。〔一二〕生貔豹，搏豺狼，〔一三〕手熊羆，足野羊。〔一四〕蒙鶡蘇，〔一五〕絝白虎，〔一六〕被斑文，〔一七〕跨野馬，〔一八〕陵三嵕之危，〔一九〕下磧歷之坻，〔二０〕徑峻赴險，越壑厲水。〔二一〕推蜚廉，弄解廌，〔二二〕格蝦蛤，鋋猛氏，〔二三〕羂要褭，射封豕。〔二四〕箭不苟害，解脰陷腦；弓不虛發，應聲而倒。〔二五〕","sentenceOrder":339},
  {"id":"s_work_han_thu_68_340","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　李奇曰：「以五校兵出獵也。」師古曰：「李說非也。校獵者，以木相貫穿，總為闌校，遮止禽獸而獵取之。說者或以為周官校人掌田獵之馬，因云校獵，亦失其義。養馬稱校人者，謂以為闌校以養馬耳，故呼為閑也。事具周禮，非以獵馬故稱校人。」","sentenceOrder":340},
  {"id":"s_work_han_thu_68_341","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　張揖曰：「鏤象，象路也，以象牙疏鏤其車輅。六玉虯，謂駕六馬，以玉飾其鑣勒，有似玉虯。龍子有角曰虯。」","sentenceOrder":341},
  {"id":"s_work_han_thu_68_342","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　張揖曰：「析羽毛，染以五采，綴以縷為旌，有似虹蜺之氣也。」師古曰：「拖音土賀反，又音徒可反。」","sentenceOrder":342},
  {"id":"s_work_han_thu_68_343","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　張揖曰：「畫熊虎於旒為旗，似雲氣。」","sentenceOrder":343},
  {"id":"s_work_han_thu_68_344","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　文穎曰：「皮軒，以虎皮飾車。天子出，道車五乘，游車九乘，在乘輿車前，賦頌為偶辭耳。」師古曰：「文說非也。言皮軒最居前，而道游次皮軒之後耳，非謂在乘輿之後也。皮軒之上以赤皮為重蓋，今此制尚存，又非猛獸之皮用飾車也。道讀曰導。」","sentenceOrder":344},
  {"id":"s_work_han_thu_68_345","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　鄭氏曰：「孫叔者，太僕公孫賀也，字子叔。衛公者，大將軍衛青也。大駕，太僕御，大將軍參乘。」師古曰：「參乘，在車之右也。解具在文紀也。」","sentenceOrder":345},
  {"id":"s_work_han_thu_68_346","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　文穎曰：「凡五校，今言四者，一校中隨天子乘輿也。」師古曰：「此說又非也。四校者，闌校之四面也。言其跋扈縱恣而行，出於校之四外也。」","sentenceOrder":346},
  {"id":"s_work_han_thu_68_347","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　孟康曰：「鼓嚴，嚴鼓也。簿，鹵簿也。」師古曰：「縱，放也。簿音步戶反。」","sentenceOrder":347},
  {"id":"s_work_han_thu_68_348","chapterId":"ch_work_han_thu_68","textTraditional":"〔九〕　蘇林曰：「阹，獵者圜陳遮禽獸也。」張揖曰：「櫓，大盾，以為翳也。」郭璞曰：「櫓，望樓也。因山谷遮禽獸為阹。」師古曰：「因江河以遮禽，登泰山而望獲，言田獵之廣遠耳。郭說是也。阹音（怯）〔袪〕。」","sentenceOrder":348},
  {"id":"s_work_han_thu_68_349","chapterId":"ch_work_han_thu_68","textTraditional":"〔一０〕郭璞曰：「殷猶震也。」師古曰：「靁，古雷字也。殷音隱。」","sentenceOrder":349},
  {"id":"s_work_han_thu_68_350","chapterId":"ch_work_han_thu_68","textTraditional":"〔一一〕師古曰：「陸離，分散也。言各有所追逐也。追合韻音竹遂反。」","sentenceOrder":350},
  {"id":"s_work_han_thu_68_351","chapterId":"ch_work_han_thu_68","textTraditional":"〔一二〕郭璞曰：「言遍山野也。」","sentenceOrder":351},
  {"id":"s_work_han_thu_68_352","chapterId":"ch_work_han_thu_68","textTraditional":"〔一三〕郭璞曰：「貔，執夷，虎屬也，音毗。」師古曰：「貔豹二物，皆猛獸也。生謂生取之也。搏，擊也。」","sentenceOrder":352},
  {"id":"s_work_han_thu_68_353","chapterId":"ch_work_han_thu_68","textTraditional":"〔一四〕張揖曰：「熊，犬身人足，黑色。羆如熊，黃白色。野羊，麢羊也，似羊而青。」師古曰：「野羊，今之所謂山羊也，非麢羊矣。手，言手擊殺之。足謂蹴蹈而獲之。」","sentenceOrder":353},
  {"id":"s_work_han_thu_68_354","chapterId":"ch_work_han_thu_68","textTraditional":"〔一五〕孟康曰：「鶡，鶡尾也。蘇，析羽也。」張揖曰：「鶡似雉，鬥死不卻。」郭璞曰：「蒙其尾為帽也。鶡音曷。」","sentenceOrder":354},
  {"id":"s_work_han_thu_68_355","chapterId":"ch_work_han_thu_68","textTraditional":"〔一六〕張揖曰：「著白虎文絝也。」師古曰：「絝，古袴字。」","sentenceOrder":355},
  {"id":"s_work_han_thu_68_356","chapterId":"ch_work_han_thu_68","textTraditional":"〔一七〕師古曰：「被謂衣著之也。斑文，亦貙豹之皮也。被音皮義反。」","sentenceOrder":356},
  {"id":"s_work_han_thu_68_357","chapterId":"ch_work_han_thu_68","textTraditional":"〔一八〕師古曰：「騎之也。」","sentenceOrder":357},
  {"id":"s_work_han_thu_68_358","chapterId":"ch_work_han_thu_68","textTraditional":"〔一九〕師古曰：「陵，上也。三嵕，三聚之山也。」","sentenceOrder":358},
  {"id":"s_work_han_thu_68_359","chapterId":"ch_work_han_thu_68","textTraditional":"〔二０〕師古曰：「磧歷，沙石之貌也。坻，水中高處也。磧音千狄反。坻音遲。」","sentenceOrder":359},
  {"id":"s_work_han_thu_68_360","chapterId":"ch_work_han_thu_68","textTraditional":"〔二一〕師古曰：「厲，以衣度也。」","sentenceOrder":360},
  {"id":"s_work_han_thu_68_361","chapterId":"ch_work_han_thu_68","textTraditional":"〔二二〕郭璞曰：「飛廉，龍雀也，鳥身鹿頭。」張揖曰：「解廌似鹿而一角，人君刑罰得中則生於朝廷，主觸不直者，可得而弄也。」師古曰：「推亦謂弄之也，其字從手。今流俗讀作椎擊之椎，失其義矣。解音蟹。廌音丈介反。」","sentenceOrder":361},
  {"id":"s_work_han_thu_68_362","chapterId":"ch_work_han_thu_68","textTraditional":"〔二三〕孟康曰：「蝦蛤、猛氏，皆獸名也。」郭璞曰：「今蜀中有獸，狀似熊而小，毛淺有光澤，名猛氏。」師古曰：「鋋，鐵把短矛也。蝦音遐。蛤音閤。鋋音蟬。」","sentenceOrder":362},
  {"id":"s_work_han_thu_68_363","chapterId":"ch_work_han_thu_68","textTraditional":"〔二四〕張揖曰：「要褭，馬金（啄）〔喙〕赤色，一日行萬里者。」郭璞曰：「封豕，大豬也。要褭音窈嫋。」師古曰：「罥謂羅繫之也，音工犬反。」","sentenceOrder":363},
  {"id":"s_work_han_thu_68_364","chapterId":"ch_work_han_thu_68","textTraditional":"〔二五〕張揖曰：「脰，項也。」師古曰：「言射必命中，非詭遇也。脰音豆。」","sentenceOrder":364},
  {"id":"s_work_han_thu_68_365","chapterId":"ch_work_han_thu_68","textTraditional":"「於是乘輿弭節徘徊，翱翔往來，〔一〕睨部曲之進退，覽將帥之變態。〔二〕然後侵淫促節，〔三〕儵敻遠去，〔四〕流離輕禽，蹴履狡獸，〔五〕〈車惠〉白鹿，捷狡菟。〔六〕軼赤電，遺光耀〔七〕，追怪物，出宇宙，〔八〕彎蕃弱，滿白羽，〔九〕射游梟，櫟蜚遽。〔一０〕擇肉而后發，先中而命處，〔一一〕弦矢分，蓺殪仆。〔一二〕","sentenceOrder":365},
  {"id":"s_work_han_thu_68_366","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　郭璞曰：「言周旋也。」","sentenceOrder":366},
  {"id":"s_work_han_thu_68_367","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　師古曰：「睨，邪視也。部曲，解在李廣傳。睨音五計反。」","sentenceOrder":367},
  {"id":"s_work_han_thu_68_368","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　郭璞曰：「言短驅也。」","sentenceOrder":368},
  {"id":"s_work_han_thu_68_369","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　師古曰：「儵然敻然，疾遠貌。」","sentenceOrder":369},
  {"id":"s_work_han_thu_68_370","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　師古曰：「流離，困苦之也。」","sentenceOrder":370},
  {"id":"s_work_han_thu_68_371","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　郭璞曰：「狡菟健跳，故捷取之也。」","sentenceOrder":371},
  {"id":"s_work_han_thu_68_372","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　張揖曰：「軼，過也。」郭璞曰：「皆妖氣為變怪者，遊光之屬。」","sentenceOrder":372},
  {"id":"s_work_han_thu_68_373","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　張揖曰：「怪物，奇禽也。天地四方曰宇，古往今來曰宙。」師古曰：「張說宙，非也。許氏說文解字云『宙，舟輿所極覆也』。」","sentenceOrder":373},
  {"id":"s_work_han_thu_68_374","chapterId":"ch_work_han_thu_68","textTraditional":"〔九〕　文穎曰：「彎，牽也。蕃弱，夏后氏之良（工）〔弓〕名。引弓盡箭鏑為滿。以白羽羽箭，故言白羽也。」師古曰：「彎音烏還反。蕃音扶元反。」","sentenceOrder":374},
  {"id":"s_work_han_thu_68_375","chapterId":"ch_work_han_thu_68","textTraditional":"〔一０〕張揖曰：「梟，惡鳥，故射之也。櫟，梢也。飛遽，天上神獸也，鹿頭而龍身。」郭璞曰：「梟，梟羊也，似人長脣，被髮食人。」師古曰：「梟，郭說近是矣，非謂惡鳥之梟也。櫟音洛。遽音鉅。」","sentenceOrder":375},
  {"id":"s_work_han_thu_68_376","chapterId":"ch_work_han_thu_68","textTraditional":"〔一一〕郭璞曰：「言必如所志者也。」","sentenceOrder":376},
  {"id":"s_work_han_thu_68_377","chapterId":"ch_work_han_thu_68","textTraditional":"〔一二〕文穎曰：「所射準的為蓺，一發（矢）〔死〕為殪。」郭璞曰：「仆，斃也。殪音翳。仆音赴。」師古曰：「言弦矢適分，則殪死而赴，如射蓺也。蓺謂射的，即今之垛上橜也。蓺讀與藝同，字亦作臬，音魚列反。」","sentenceOrder":377},
  {"id":"s_work_han_thu_68_378","chapterId":"ch_work_han_thu_68","textTraditional":"「然後揚節而上浮，〔一〕陵驚風，歷駭猋，〔二〕乘虛亡，與神俱，〔三〕藺玄鶴，亂昆雞，〔四〕遒孔鸞，促鵔鸃，〔五〕拂翳鳥，〔六〕捎鳳凰，〔七〕捷鵷鶵，揜焦明。〔八〕","sentenceOrder":378},
  {"id":"s_work_han_thu_68_379","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　郭璞曰：「言騰遊也。」","sentenceOrder":379},
  {"id":"s_work_han_thu_68_380","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　師古曰：「猋謂疾風從下而上也，音必遙反。」","sentenceOrder":380},
  {"id":"s_work_han_thu_68_381","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　張揖曰：「虛無廖廓，與元通靈，言其所乘氣之高，故能出飛鳥之上而與神俱也。」","sentenceOrder":381},
  {"id":"s_work_han_thu_68_382","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　張揖曰：「昆雞似鶴，黃白色。」郭璞曰：「亂者，言亂其行伍也。」","sentenceOrder":382},
  {"id":"s_work_han_thu_68_383","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　郭璞曰：「遒、促，皆迫捕之也。」師古曰：「遒音材由反。」","sentenceOrder":383},
  {"id":"s_work_han_thu_68_384","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　張揖曰：「山海經曰九疑之山有五采之鳥，名曰翳鳥也。」","sentenceOrder":384},
  {"id":"s_work_han_thu_68_385","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　師古曰：「捎音山交反。」","sentenceOrder":385},
  {"id":"s_work_han_thu_68_386","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　張揖曰：「焦明似鳳，西方之鳥也。」","sentenceOrder":386},
  {"id":"s_work_han_thu_68_387","chapterId":"ch_work_han_thu_68","textTraditional":"「道盡塗殫，迴車而還。消〈〈扌炙〉，中“火改言”〉乎襄羊，降集乎北紘，〔一〕率乎直指，〔二〕揜乎反鄉，〔三〕蹶石關，歷封巒，過〈支隹〉鵲，望露寒，〔四〕下堂梨，息宜春，〔五〕西馳宣曲，〔六〕濯鷁牛首〔七〕，登龍臺，〔八〕掩細柳，〔九〕觀士大夫之勤略，〔一０〕鈞獵者之所得獲。〔一一〕徒車之所閵轢，〔一二〕騎之所蹂若，人之所蹈藉，〔一三〕與其窮極倦〈郄，中“阝改几”〉，驚憚讋伏，〔一四〕不被創刃而死者，它它藉藉，〔一五〕填阬滿谷，掩平彌澤。〔一六〕","sentenceOrder":387},
  {"id":"s_work_han_thu_68_388","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　張揖曰：「淮南子云九州之外曰八澤，八澤之外乃有八紘，北方之紘曰委羽。」郭璞曰：「襄羊猶彷徉也。」師古曰：「紘音宏。」","sentenceOrder":388},
  {"id":"s_work_han_thu_68_389","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　師古曰：「率然直去意。」","sentenceOrder":389},
  {"id":"s_work_han_thu_68_390","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　師古曰：「揜然疾歸貌。」","sentenceOrder":390},
  {"id":"s_work_han_thu_68_391","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　張揖曰：「此四觀武帝建元中作，在雲陽甘泉宮外。」師古曰：「蹶，蹋；歷，經也。蹶音鉅月反。巒音鸞。〈支隹〉音支。」","sentenceOrder":391},
  {"id":"s_work_han_thu_68_392","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　張揖曰：「堂梨，宮名，在雲陽東南三十里。」師古曰：「宜春，宮名，在杜縣東，即今曲江池是其處也。」","sentenceOrder":392},
  {"id":"s_work_han_thu_68_393","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　張揖曰：「宣曲，宮名也，在昆明池西。」","sentenceOrder":393},
  {"id":"s_work_han_thu_68_394","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　張揖曰：「牛首，池名也，在上林苑西頭。」師古曰：「濯者，所以刺船也。鷁即鷁首之舟也。濯音直孝反。」","sentenceOrder":394},
  {"id":"s_work_han_thu_68_395","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　張揖曰：「觀名也，在豐水西北，近渭。」","sentenceOrder":395},
  {"id":"s_work_han_thu_68_396","chapterId":"ch_work_han_thu_68","textTraditional":"〔九〕　郭璞曰：「觀名也，在昆明池南也。」","sentenceOrder":396},
  {"id":"s_work_han_thu_68_397","chapterId":"ch_work_han_thu_68","textTraditional":"〔一０〕師古曰：「略，智略也。觀士之勤，大夫之略也。」","sentenceOrder":397},
  {"id":"s_work_han_thu_68_398","chapterId":"ch_work_han_thu_68","textTraditional":"〔一一〕郭璞曰：「平其多少也。」","sentenceOrder":398},
  {"id":"s_work_han_thu_68_399","chapterId":"ch_work_han_thu_68","textTraditional":"〔一二〕郭璞曰：「徒，步也。閵，踐也。轢，輾也，音來各反。」師古曰：「輾音女展反。」","sentenceOrder":399},
  {"id":"s_work_han_thu_68_400","chapterId":"ch_work_han_thu_68","textTraditional":"〔一三〕師古曰：「蹂若，謂踐蹋也。蹂音人九反。」","sentenceOrder":400},
  {"id":"s_work_han_thu_68_401","chapterId":"ch_work_han_thu_68","textTraditional":"〔一四〕郭璞曰：「窮極倦〈郄，中“阝改几”〉，疲憊也。驚憚讋伏，讋怖不動貌。」師古曰：「〈郄，中“阝改几”〉音劇。憚音丁曷反。讋音之涉反。」","sentenceOrder":401},
  {"id":"s_work_han_thu_68_402","chapterId":"ch_work_han_thu_68","textTraditional":"〔一五〕郭璞曰：「言交橫也。」師古曰：「它音徒何反。」","sentenceOrder":402},
  {"id":"s_work_han_thu_68_403","chapterId":"ch_work_han_thu_68","textTraditional":"〔一六〕師古曰：「平，平原也。彌亦滿也。」","sentenceOrder":403},
  {"id":"s_work_han_thu_68_404","chapterId":"ch_work_han_thu_68","textTraditional":"「於是乎游戲懈怠，置酒乎顥天之臺，〔一〕張樂乎膠葛之宇，〔二〕撞千石之鐘，〔三〕立萬石之虡，〔四〕建翠華之旗，樹靈鼉之鼓，〔五〕奏陶唐氏之舞，〔六〕聽葛天氏之歌，〔七〕千人倡，萬人和〔八〕山陵為之震動，川谷為之蕩波。〔九〕巴俞宋蔡，淮南干遮，〔一０〕文成顛歌，〔一一〕族居遞奏，金鼓迭起，〔一二〕鏗鎗闛鞈，洞心駭耳。〔一三〕荊吳鄭衛之聲，〔一四〕韶濩武象之樂，〔一五〕陰淫案衍之音，〔一六〕鄢郢繽紛，激楚結風〔一七〕，俳優侏儒，狄鞮之倡，〔一八〕所以娛耳目樂心意者，麗靡爛漫於前，〔一九〕靡曼美色於後。〔二０〕","sentenceOrder":404},
  {"id":"s_work_han_thu_68_405","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　張揖曰：「臺高上干皓天也。」師古曰：「顥音胡考反。」","sentenceOrder":405},
  {"id":"s_work_han_thu_68_406","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　郭璞曰：「言曠遠深貌也。」","sentenceOrder":406},
  {"id":"s_work_han_thu_68_407","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　張揖曰：「千石，十二萬斤也。」","sentenceOrder":407},
  {"id":"s_work_han_thu_68_408","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　師古曰：「虡，獸名也。立一百二十萬斤之虡以縣鐘也。」","sentenceOrder":408},
  {"id":"s_work_han_thu_68_409","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　師古曰：「翠華之旗，以翠羽為旗上葆也。靈鼉之鼓，以鼉皮為鼓。鼉音徒河反，又音徒丹反。」","sentenceOrder":409},
  {"id":"s_work_han_thu_68_410","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　郭璞曰：「陶唐，堯有天下號也。」如淳曰：「舞咸池。」師古曰：「二家之說皆非也。陶唐當為陰康，傳寫字誤耳。古今人表有葛天氏，陰康氏、呂氏春秋曰：『昔陰康氏之始，陰多滯伏湛積，陽道壅塞，不行其序，民氣鬱閼，筋骨縮栗不達，故作為舞以宣導之。』高誘亦誤解云『陶唐，堯有天下之號也』。案呂氏說陰康之後，方一一歷言黃帝、顓頊、帝嚳，乃及堯、舜作樂之本，皆有次第，豈再陳堯而錯亂其序乎？蓋誘不視古今人表，妄改易呂氏本文。」","sentenceOrder":410},
  {"id":"s_work_han_thu_68_411","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　張揖曰：「葛天氏，三皇時君號也。其樂三人持牛尾投足以歌八曲：一曰戴民，二曰玄鳥，三曰育草木，四曰奮五穀，五曰敬天常，六曰徹帝功，七曰依地德，八曰總禽獸之極。」師古曰：「張說八曲是也。其事亦見呂氏春秋。張云三皇時君，失之矣。」","sentenceOrder":411},
  {"id":"s_work_han_thu_68_412","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　師古曰：「倡讀曰唱。」","sentenceOrder":412},
  {"id":"s_work_han_thu_68_413","chapterId":"ch_work_han_thu_68","textTraditional":"〔九〕　郭璞曰：「波浪起也。」","sentenceOrder":413},
  {"id":"s_work_han_thu_68_414","chapterId":"ch_work_han_thu_68","textTraditional":"〔一０〕師古曰：「巴俞之人剛勇好舞，初高祖用之，克平三秦，美其功力，後使樂府習之，因名巴俞舞也。宋蔡，二國名。淮南，地名，干遮，曲名也。」","sentenceOrder":414},
  {"id":"s_work_han_thu_68_415","chapterId":"ch_work_han_thu_68","textTraditional":"〔一一〕文穎曰：「文成，遼西縣名也。其縣人善歌。顛，益州顛縣，其民能作西南夷歌也。」師古曰：「顛即滇字也，其音則同耳。」","sentenceOrder":415},
  {"id":"s_work_han_thu_68_416","chapterId":"ch_work_han_thu_68","textTraditional":"〔一二〕師古曰：「族，聚也。聚居而遞奏也。金，鐘也。鐘之與鼓，亦互起也。迭音徒結反。」","sentenceOrder":416},
  {"id":"s_work_han_thu_68_417","chapterId":"ch_work_han_thu_68","textTraditional":"〔一三〕師古曰：「鏗鎗，金聲也。闛鞈，鼓音也。洞，徹也。駭，驚也。鏗音口耕反。鎗音切衡反。闛音託郎反。鞈音榻。」","sentenceOrder":417},
  {"id":"s_work_han_thu_68_418","chapterId":"ch_work_han_thu_68","textTraditional":"〔一四〕郭璞曰：「皆淫哇之聲。」","sentenceOrder":418},
  {"id":"s_work_han_thu_68_419","chapterId":"ch_work_han_thu_68","textTraditional":"〔一五〕文穎曰：「韶，舜樂也。濩，湯樂也。武，武王樂也。」張揖曰：「象，周公樂也。南人服象，為虐於夷，成王命周公以兵追之，至於海南，乃為三象樂也。」","sentenceOrder":419},
  {"id":"s_work_han_thu_68_420","chapterId":"ch_work_han_thu_68","textTraditional":"〔一六〕郭璞曰：「流湎曲也。」師古曰：「衍音弋戰反。」","sentenceOrder":420},
  {"id":"s_work_han_thu_68_421","chapterId":"ch_work_han_thu_68","textTraditional":"〔一七〕李奇曰：「鄢，今宜城縣也。郢，楚都也。繽紛，舞貌也。」郭璞曰：「激楚，歌曲也。」師古曰：「結風，亦曲名也。繽音匹人反。」","sentenceOrder":421},
  {"id":"s_work_han_thu_68_422","chapterId":"ch_work_han_thu_68","textTraditional":"〔一八〕張揖曰：「狄鞮，西方譯名。」郭璞曰：「西戎樂名也。」師古曰：「俳優侏儒，倡樂可狎玩者也。狄鞮，郭說是也。鞮音丁奚反。」","sentenceOrder":422},
  {"id":"s_work_han_thu_68_423","chapterId":"ch_work_han_thu_68","textTraditional":"〔一九〕郭璞曰：「言恣所觀也。」","sentenceOrder":423},
  {"id":"s_work_han_thu_68_424","chapterId":"ch_work_han_thu_68","textTraditional":"〔二０〕張揖曰：「靡，細也。曼，澤也。」","sentenceOrder":424},
  {"id":"s_work_han_thu_68_425","chapterId":"ch_work_han_thu_68","textTraditional":"「若夫青琴虙妃之徒，〔一〕絕殊離俗，〔二〕妖冶閑都，靚莊刻飾，便嬛繛約，〔三〕柔橈嬽嬽，嫵媚孅弱，〔四〕曳獨繭之褕〈礻世〉，眇閻易以恤削，〔五〕便姍嫳屑，與世殊服，〔六〕芬芳漚鬱，酷烈淑郁，〔七〕皓齒粲爛，宜笑的皪，〔八〕長眉連娟，微睇綿藐，〔九〕色授魂予，心愉於側。〔一０〕","sentenceOrder":425},
  {"id":"s_work_han_thu_68_426","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　伏儼曰：「青琴，古神女也。」文穎曰：「虙妃，洛水之神女也。」師古曰：「虙讀與伏字同，字本作虙也。」","sentenceOrder":426},
  {"id":"s_work_han_thu_68_427","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　郭璞曰：「世無雙也。」","sentenceOrder":427},
  {"id":"s_work_han_thu_68_428","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　郭璞曰：「靚莊，粉白黛黑也。刻，刻畫鬋鬢也。便嬛，輕麗也。繛約，婉約也。嬛音翾。靚音淨。」師古曰：「妖冶，美好也。閑都，雅麗也。繛音綽。」","sentenceOrder":428},
  {"id":"s_work_han_thu_68_429","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　師古曰：「橈，動曲也。嬽嬽，柔屈貌也。纖，細也。細弱總謂骨體也。橈音女教反。嬽音於圓反。嫵音武。孅即纖字耳。」","sentenceOrder":429},
  {"id":"s_work_han_thu_68_430","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　張揖曰：「褕，襜褕也。〈礻世〉，袖也。」郭璞曰：「獨繭，一繭絲也。閻易，衣長貌也。恤削，言如刻畫作之也。」師古曰：「褕音踰。〈礻世〉音曳。易，弋示反。」","sentenceOrder":430},
  {"id":"s_work_han_thu_68_431","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　師古曰：「言其行步安詳，容服絕異也。便音步千反。姍音先。嫳音步結反。」","sentenceOrder":431},
  {"id":"s_work_han_thu_68_432","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　郭璞曰：「香氣盛也。」師古曰：「漚音一候反。」","sentenceOrder":432},
  {"id":"s_work_han_thu_68_433","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　郭璞曰：「鮮明貌也。」師古曰：「皪音礫。」","sentenceOrder":433},
  {"id":"s_work_han_thu_68_434","chapterId":"ch_work_han_thu_68","textTraditional":"〔九〕　郭璞曰：「連娟言曲細。綿藐，視遠貌。藐音邈。」師古曰：「微睇，小視也。娟音一全反。睇音大計反。」","sentenceOrder":434},
  {"id":"s_work_han_thu_68_435","chapterId":"ch_work_han_thu_68","textTraditional":"〔一０〕張揖曰：「彼色來授，魂往與接也。」師古曰：「愉，樂也，音踰。」","sentenceOrder":435},
  {"id":"s_work_han_thu_68_436","chapterId":"ch_work_han_thu_68","textTraditional":"「於是酒中樂酣，〔一〕天子芒然而思，〔二〕似若有亡，〔三〕曰：『嗟乎，此大奢侈！朕以覽聽餘閒，無事棄日，〔四〕順天道以殺伐，〔五〕時休息（以）於此，〔六〕恐後世靡麗，遂往而不返，非所以為繼嗣創業垂統也。』〔七〕於是乎乃解酒罷獵，而命有司曰：『地可墾辟，悉為農郊，以贍氓隸，〔八〕隤牆填塹，〔九〕使山澤之民得至焉。〔一０〕實陂池而勿禁，虛宮館而勿仞。〔一一〕發倉廩以救貧窮，補不足，恤鰥寡，存孤獨。出德號，省刑罰，〔一二〕改制度，易服色，革正朔，與天下為始。』","sentenceOrder":436},
  {"id":"s_work_han_thu_68_437","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　師古曰：「酒中，飲酒中半也。樂酣，奏樂洽也。中音竹仲反。」","sentenceOrder":437},
  {"id":"s_work_han_thu_68_438","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　師古曰：「芒然猶罔然也。芒音莫郎反。」","sentenceOrder":438},
  {"id":"s_work_han_thu_68_439","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　師古曰：「如有失也。」","sentenceOrder":439},
  {"id":"s_work_han_thu_68_440","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　師古曰：「言聽政餘暇，不能棄日也。閒讀曰閑。」","sentenceOrder":440},
  {"id":"s_work_han_thu_68_441","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　郭璞曰：「因秋氣也。」","sentenceOrder":441},
  {"id":"s_work_han_thu_68_442","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　郭璞曰：「謂苑囿中也。」","sentenceOrder":442},
  {"id":"s_work_han_thu_68_443","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　郭璞曰：「言不可以示將來也。」師古曰：「為音于偽反。」","sentenceOrder":443},
  {"id":"s_work_han_thu_68_444","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　師古曰：「辟讀曰闢。闢，開也。邑外謂之郊，郊野之田故曰農郊也。衛風碩人之詩曰『稅于農郊』也。」","sentenceOrder":444},
  {"id":"s_work_han_thu_68_445","chapterId":"ch_work_han_thu_68","textTraditional":"〔九〕　師古曰：「隤，墜也，音徒回反。」","sentenceOrder":445},
  {"id":"s_work_han_thu_68_446","chapterId":"ch_work_han_thu_68","textTraditional":"〔一０〕師古曰：「恣其芻牧樵采者也。」","sentenceOrder":446},
  {"id":"s_work_han_thu_68_447","chapterId":"ch_work_han_thu_68","textTraditional":"〔一一〕師古曰：「實謂人滿其中，其恣其有所取也。仞亦滿也。勿仞，言（發）〔廢〕罷之也。」","sentenceOrder":447},
  {"id":"s_work_han_thu_68_448","chapterId":"ch_work_han_thu_68","textTraditional":"〔一二〕師古曰：「德號，德音之號令也。易夬卦曰『孚號有厲』是也。」","sentenceOrder":448},
  {"id":"s_work_han_thu_68_449","chapterId":"ch_work_han_thu_68","textTraditional":"「於是歷吉日以齋戒，〔一〕襲朝服，乘法駕，建華旗，鳴玉鸞，〔二〕游于六藝之囿，馳騖乎仁義之塗，〔三〕覽觀春秋之林，〔四〕射貍首，兼騶虞，〔五〕弋玄鶴，舞干戚，〔六〕戴雲罕，揜群雅，〔七〕悲伐檀，〔八〕樂樂胥，〔九〕修容乎禮園，翱翔乎書圃，〔一０〕述易道，〔一一〕放怪獸，〔一二〕登明堂，坐清廟，恣群臣，奏得失，四海之內，靡不受獲。〔一三〕於斯之時，天下大說，鄉風而聽，隨流而化，〔一四〕芔然興道而遷義，〔一五〕刑錯而不用，德隆於三皇，功羡於五帝。〔一六〕若此，故獵乃可喜也。","sentenceOrder":449},
  {"id":"s_work_han_thu_68_450","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　張揖曰：「歷猶算也。」","sentenceOrder":450},
  {"id":"s_work_han_thu_68_451","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　郭璞曰：「鸞，鈴也，在軌曰鸞，在軾曰和。」","sentenceOrder":451},
  {"id":"s_work_han_thu_68_452","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　郭璞曰：「六藝，禮、樂、射、御、書、數也。塗，道也。」師古曰：「郭說非也。此六藝謂六經者也。」","sentenceOrder":452},
  {"id":"s_work_han_thu_68_453","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　如淳曰：「春秋義理繁茂，故比之於林藪也。」","sentenceOrder":453},
  {"id":"s_work_han_thu_68_454","chapterId":"ch_work_han_thu_68","textTraditional":"〔五〕　郭璞曰：「貍首，逸詩篇名，諸侯以為射節。騶虞，召南之卒章，天子以為射節也。」","sentenceOrder":454},
  {"id":"s_work_han_thu_68_455","chapterId":"ch_work_han_thu_68","textTraditional":"〔六〕　郭璞曰：「干，盾；戚，斧也。」","sentenceOrder":455},
  {"id":"s_work_han_thu_68_456","chapterId":"ch_work_han_thu_68","textTraditional":"〔七〕　張揖曰：「罕，畢也，前有九流雲罕之車。詩小雅之材七十四人，大雅之材三十一人，故曰群雅也。」","sentenceOrder":456},
  {"id":"s_work_han_thu_68_457","chapterId":"ch_work_han_thu_68","textTraditional":"〔八〕　師古曰：「伐檀，魏國之詩，刺在位貪鄙也。」","sentenceOrder":457},
  {"id":"s_work_han_thu_68_458","chapterId":"ch_work_han_thu_68","textTraditional":"〔九〕　鄭氏曰：「詩云『于胥樂兮』。」師古曰：「此說非也。謂取小雅桑扈之篇云『君子樂胥，萬邦之屏』耳。胥，有材知之人也。王者樂得有材知之人使在位也。胥音先呂反。」","sentenceOrder":458},
  {"id":"s_work_han_thu_68_459","chapterId":"ch_work_han_thu_68","textTraditional":"〔一０〕師古曰：「此以上皆取經典之嘉辭，以代游獵之娛樂。」","sentenceOrder":459},
  {"id":"s_work_han_thu_68_460","chapterId":"ch_work_han_thu_68","textTraditional":"〔一一〕郭璞曰：「修絜靜精微之術。」","sentenceOrder":460},
  {"id":"s_work_han_thu_68_461","chapterId":"ch_work_han_thu_68","textTraditional":"〔一二〕張揖曰：「苑中奇怪之獸，不復獵也。」","sentenceOrder":461},
  {"id":"s_work_han_thu_68_462","chapterId":"ch_work_han_thu_68","textTraditional":"〔一三〕師古曰：「言天下之人，皆受恩惠，豈直如田獵得獸而已。」","sentenceOrder":462},
  {"id":"s_work_han_thu_68_463","chapterId":"ch_work_han_thu_68","textTraditional":"〔一四〕師古曰：「說讀曰悅。鄉讀曰嚮。」","sentenceOrder":463},
  {"id":"s_work_han_thu_68_464","chapterId":"ch_work_han_thu_68","textTraditional":"〔一五〕師古曰：「芔然猶欻然也。遷，徙也，徙就於義也。芔音許貴反。」","sentenceOrder":464},
  {"id":"s_work_han_thu_68_465","chapterId":"ch_work_han_thu_68","textTraditional":"〔一六〕師古曰：「錯，置也。羡，饒也。五帝謂黃帝、顓頊、帝嚳、堯、舜也，一曰少昊、顓頊、高辛、堯、舜也。錯音千故反。羡音弋戰反。」","sentenceOrder":465},
  {"id":"s_work_han_thu_68_466","chapterId":"ch_work_han_thu_68","textTraditional":"「若夫終日馳騁，勞神苦形，罷車馬之用，抏士卒之精〔一〕，費府庫之財，而無德厚之恩，務在獨樂，不顧眾庶，忘國家之政，貪雉菟之獲，則仁者不繇也。〔二〕從此觀之，齊楚之事，豈不哀哉！地方不過千里，而囿居九百，是草木不得墾辟，而民無所食也。〔三〕夫以諸侯之細，而樂萬乘之所侈，僕恐百姓被其尤也。」〔四〕","sentenceOrder":466},
  {"id":"s_work_han_thu_68_467","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　師古曰：「罷讀曰疲。抏，挫也，音五官反。」","sentenceOrder":467},
  {"id":"s_work_han_thu_68_468","chapterId":"ch_work_han_thu_68","textTraditional":"〔二〕　師古曰：「繇讀與由同。由，用也。」","sentenceOrder":468},
  {"id":"s_work_han_thu_68_469","chapterId":"ch_work_han_thu_68","textTraditional":"〔三〕　師古曰：「辟讀曰闢。」","sentenceOrder":469},
  {"id":"s_work_han_thu_68_470","chapterId":"ch_work_han_thu_68","textTraditional":"〔四〕　師古曰：「尤，過也；被音皮義反。」","sentenceOrder":470},
  {"id":"s_work_han_thu_68_471","chapterId":"ch_work_han_thu_68","textTraditional":"於是二子愀然改容，超若自失，〔一〕逡巡避席，曰：「鄙人固陋，不知忌諱，乃今日見教，謹受命矣。」","sentenceOrder":471},
  {"id":"s_work_han_thu_68_472","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　師古曰：「愀，變色貌，音材小反，又音秋誘反。」","sentenceOrder":472},
  {"id":"s_work_han_thu_68_473","chapterId":"ch_work_han_thu_68","textTraditional":"賦奏，天子以為郎。亡是公言上林廣大，山谷水泉萬物，及子虛言雲夢所有甚眾，侈靡多過其實，且非義理所止，故刪取其要，歸正道而論之。〔一〕","sentenceOrder":473},
  {"id":"s_work_han_thu_68_474","chapterId":"ch_work_han_thu_68","textTraditional":"〔一〕　師古曰：「言不尚其侈靡之論，但取終篇歸於正道耳，非謂削除其辭也，而說者便謂此賦已經史家刊剟，失其意矣。」","sentenceOrder":474},
  {"id":"s_work_han_thu_68_475","chapterId":"ch_work_han_thu_68","textTraditional":"校勘記","sentenceOrder":475},
  {"id":"s_work_han_thu_68_476","chapterId":"ch_work_han_thu_68","textTraditional":"二五四０頁一二行　〔決〕眥即決獸之目眥，　王先謙說，「曰」下當有「決」字。","sentenceOrder":476},
  {"id":"s_work_han_thu_68_477","chapterId":"ch_work_han_thu_68","textTraditional":"二五四九頁　二行　西河（有）穀羅縣有紫澤。　景祐、殿本都無上「有」字。","sentenceOrder":477},
  {"id":"s_work_han_thu_68_478","chapterId":"ch_work_han_thu_68","textTraditional":"二五四九頁　六行　豐水出鄠南山（澧）〔豐〕谷，　景祐本作「豐」。","sentenceOrder":478},
  {"id":"s_work_han_thu_68_479","chapterId":"ch_work_han_thu_68","textTraditional":"二五五一頁　五行　（淚）〔汨〕〈氵急〉然也。　景祐、殿、局都本作「汨」，此誤。","sentenceOrder":479},
  {"id":"s_work_han_thu_68_480","chapterId":"ch_work_han_thu_68","textTraditional":"二五五八頁　七行　又（言）〔音〕徒可反。　殿、局本都作「音」，此誤。　景祐本無「音」字。","sentenceOrder":480},
  {"id":"s_work_han_thu_68_481","chapterId":"ch_work_han_thu_68","textTraditional":"二五五八頁一七行　大者（可）〔樹〕高三尺餘，　景祐、殿本都作「樹」。","sentenceOrder":481},
  {"id":"s_work_han_thu_68_482","chapterId":"ch_work_han_thu_68","textTraditional":"二五六０頁　七行　棣音（徙）〔徒〕計反。　景祐、殿本都作「徒」，此誤。","sentenceOrder":482},
  {"id":"s_work_han_thu_68_483","chapterId":"ch_work_han_thu_68","textTraditional":"二五六四頁一四行　阹音（怯）〔袪〕。　景祐、殿本都作「袪」。　王先謙說作「袪」是。","sentenceOrder":483},
  {"id":"s_work_han_thu_68_484","chapterId":"ch_work_han_thu_68","textTraditional":"二五六五頁一五行　馬金（啄）〔喙〕赤色，　殿、局本都作「喙」。　王先謙說作「喙」是。","sentenceOrder":484},
  {"id":"s_work_han_thu_68_485","chapterId":"ch_work_han_thu_68","textTraditional":"二五六六頁一四行　蕃弱，夏后氏之良（工）〔弓〕名。　景祐、殿、局本都作「弓」，此誤。","sentenceOrder":485},
  {"id":"s_work_han_thu_68_486","chapterId":"ch_work_han_thu_68","textTraditional":"二五六七頁　三行　一發（矢）〔死〕為殪。　景祐、殿、局本都作「死」，此誤。","sentenceOrder":486},
  {"id":"s_work_han_thu_68_487","chapterId":"ch_work_han_thu_68","textTraditional":"二五七二頁一二行　時休息（以）於此。　王先謙說史記、文選並無「以」字，則無「以」字者是。","sentenceOrder":487},
  {"id":"s_work_han_thu_68_488","chapterId":"ch_work_han_thu_68","textTraditional":"二五七三頁一一行　言（發）〔廢〕罷之也。　景祐、殿本都作「廢」。王先謙說作「廢」是。","sentenceOrder":488},
  {"id":"s_work_han_thu_69_1","chapterId":"ch_work_han_thu_69","textTraditional":"相如為郎數歲，會唐蒙使略通夜郎、僰中，〔一〕發巴蜀吏卒千人，郡又多為發轉漕萬餘人，用軍興法誅其渠率。〔二〕巴蜀民大驚恐。上聞之，乃遣相如責唐蒙等，因諭告巴蜀民以非上意。檄曰：","sentenceOrder":1},
  {"id":"s_work_han_thu_69_2","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「行取曰略。夜郎、僰中，皆西南夷也。僰音蒲北反。」","sentenceOrder":2},
  {"id":"s_work_han_thu_69_3","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「渠，大也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_69_4","chapterId":"ch_work_han_thu_69","textTraditional":"告巴蜀太守：蠻夷自擅，不討之日久矣，時侵犯邊境，勞士大夫。陛下即位，存撫天下，集安中國，然後興師出兵，北征匈奴，單于怖駭，交臂受事，屈膝請和。康居西域，重譯納貢，稽首來享。〔一〕移師東指，閩越相誅；右弔番禺，太子入朝。〔二〕南夷之君，西僰之長，常效貢職，不敢惰怠，延頸舉踵，喁喁然，〔三〕皆鄉風慕義，欲為臣妾，〔四〕道里遼遠，山川阻深，不能自致。〔五〕夫不順者已誅，而為善者未賞，故遣中郎將往賓之，發巴蜀之士各五百人以奉幣，衛使者不然，〔六〕靡有兵革之事，戰鬥之患。今聞其乃發軍興制，〔七〕驚懼子弟，憂患長老，郡又擅為轉粟運輸，皆非陛下之意也。當行者或亡逃自賊殺，〔八〕亦非人臣之節也。","sentenceOrder":4},
  {"id":"s_work_han_thu_69_5","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「來入朝覲，豫享祀也。一曰享，獻也，獻其國珍也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_69_6","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　文穎曰：「弔，至也。番禺，南海郡治也。東伐越，後至番禺，故言右也。」師古曰：「南越為東越所伐，漢發兵救之，南越蒙天子德惠，故遣太子入朝，所以云弔耳，非訓至也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_69_7","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　師古曰：「喁喁，眾口向上也，音魚龍反。」","sentenceOrder":7},
  {"id":"s_work_han_thu_69_8","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":8},
  {"id":"s_work_han_thu_69_9","chapterId":"ch_work_han_thu_69","textTraditional":"〔五〕　師古曰：「致，至也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_69_10","chapterId":"ch_work_han_thu_69","textTraditional":"〔六〕　張揖曰：「不然之變也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_69_11","chapterId":"ch_work_han_thu_69","textTraditional":"〔七〕　師古曰：「以發軍之法為興眾之制也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_69_12","chapterId":"ch_work_han_thu_69","textTraditional":"〔八〕　師古曰：「賊猶害也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_69_13","chapterId":"ch_work_han_thu_69","textTraditional":"夫邊郡之士，聞烽舉燧燔，〔一〕皆攝弓而馳，荷兵而走，〔二〕流汗相屬，惟恐居後，〔三〕觸白刃，冒流矢，〔四〕議不反顧，計不旋踵，人懷怒心，如報私讎。彼豈樂死惡生，非編列之民，而與巴蜀異主哉？〔五〕計深慮遠，急國家之難，而樂盡人臣之道也。故有剖符之封，析圭而爵，位為通侯，〔六〕居列東第。〔七〕終則遺顯號於後世，傳土地於子孫，事行甚忠敬，居位甚安佚，〔八〕名聲施於無窮，功（業）〔烈〕著而不滅。是以賢人君子。肝腦塗中原，膏液潤埜屮而不辭也。〔九〕今奉幣使至南夷，即自賊殺，或亡逃抵誅，〔一０〕身死無名，〔一一〕諡為至愚，〔一二〕恥及父母，為天下笑。人之度量相越，豈不遠哉！然此非獨行者之罪也，父兄之教不先，子弟之率不謹，〔一三〕寡廉鮮恥，而俗不長厚也。〔一四〕其被刑戮，不亦宜乎！","sentenceOrder":13},
  {"id":"s_work_han_thu_69_14","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　孟康曰：「｛竹奧｝如覆米｛竹奧｝，縣著契皋頭，有寇則舉之。燧，積薪，有寇則燔然之也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_69_15","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「攝謂張弓注矢而持之也。攝音女涉反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_69_16","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　師古曰：「屬，逮也，音之欲反。」","sentenceOrder":16},
  {"id":"s_work_han_thu_69_17","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　師古曰：「冒，犯也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_69_18","chapterId":"ch_work_han_thu_69","textTraditional":"〔五〕　師古曰：「編列，謂編戶也。編音布先反。」","sentenceOrder":18},
  {"id":"s_work_han_thu_69_19","chapterId":"ch_work_han_thu_69","textTraditional":"〔六〕　如淳曰：「析，中分也。白藏天子，青在諸侯也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_69_20","chapterId":"ch_work_han_thu_69","textTraditional":"〔七〕　師古曰：「東第，甲宅也。居帝城之東，故曰東第也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_69_21","chapterId":"ch_work_han_thu_69","textTraditional":"〔八〕　師古曰：「佚，樂也，讀與逸同。」","sentenceOrder":21},
  {"id":"s_work_han_thu_69_22","chapterId":"ch_work_han_thu_69","textTraditional":"〔九〕　師古曰：「埜與野同，古野字也。屮，古草字。」","sentenceOrder":22},
  {"id":"s_work_han_thu_69_23","chapterId":"ch_work_han_thu_69","textTraditional":"〔一０〕師古曰：「抵，至也，亡逃而至於誅也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_69_24","chapterId":"ch_work_han_thu_69","textTraditional":"〔一一〕師古曰：「無善名也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_69_25","chapterId":"ch_work_han_thu_69","textTraditional":"〔一二〕師古曰：「諡者，行之跡也。終以愚死，後葉傳稱，故謂之諡。」","sentenceOrder":25},
  {"id":"s_work_han_thu_69_26","chapterId":"ch_work_han_thu_69","textTraditional":"〔一三〕師古曰：「不先者，謂往日不素教之也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_69_27","chapterId":"ch_work_han_thu_69","textTraditional":"〔一四〕師古曰：「寡、鮮，皆少也。鮮音息淺反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_69_28","chapterId":"ch_work_han_thu_69","textTraditional":"陛下患使者有司之若彼，悼不肖愚民之如此，故遣信使〔一〕，曉諭百姓以發卒之事，〔二〕因數之以不忠死亡之罪，〔三〕讓三老孝弟以不教誨之過。〔四〕方今田時，重煩百姓，〔五〕已親見近縣，〔六〕恐遠所谿谷山澤之民不遍聞，檄到，亟下縣道，〔七〕咸喻陛下意，毋忽！〔八〕","sentenceOrder":28},
  {"id":"s_work_han_thu_69_29","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「誠信之人以為使也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_69_30","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「諭，告也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_69_31","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　師古曰：「數，責也，音所具反。」","sentenceOrder":31},
  {"id":"s_work_han_thu_69_32","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　師古曰：「讓，責也，責其教誨不備也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_69_33","chapterId":"ch_work_han_thu_69","textTraditional":"〔五〕　師古曰：「重，難也，不欲召聚之也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_69_34","chapterId":"ch_work_han_thu_69","textTraditional":"〔六〕　師古曰：「近縣之人，使者以自見而口諭之矣，故為檄文馳以示遠所也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_69_35","chapterId":"ch_work_han_thu_69","textTraditional":"〔七〕　師古曰：「亟，急也。縣有蠻夷曰道。」","sentenceOrder":35},
  {"id":"s_work_han_thu_69_36","chapterId":"ch_work_han_thu_69","textTraditional":"〔八〕　師古曰：「忽，怠忽也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_69_37","chapterId":"ch_work_han_thu_69","textTraditional":"相如還報。〔一〕唐蒙已略通夜郎，因通西南夷道，發巴蜀廣漢卒，作者數萬人。治道二歲，道不成，士卒多物故，〔二〕費以億萬計。蜀民及漢用事者多言其不便。是時邛、莋之君長〔三〕聞南夷與漢通，得賞賜多，多欲願為內臣妾，請吏，比南夷。上問相如，相如曰：「邛、莋、冉、駹者近蜀，道易通，〔四〕異時嘗通為郡縣矣，〔五〕至漢興而罷。今誠復通，為置縣，愈於南夷。」〔六〕上以為然，乃拜相如為中郎將，建節往使。副使者王然于、壺充國、呂越人，馳四乘之傳，〔七〕因巴蜀吏幣物以賂西南夷。至蜀，太守以下郊迎，〔八〕縣令負弩矢先驅，〔九〕蜀人以為寵。於是卓王孫、臨邛諸公皆因門下獻牛酒以交驩。卓王孫喟然而歎，自以得使女尚司馬長卿晚，〔一０〕乃厚分與其女財，與男等。相如使略定西南夷，邛、莋、冉、駹、斯榆之君皆請為臣妾，除邊關，〔邊關〕益斥，〔一一〕西至沬、若水，〔一二〕南至牂牁為徼，〔一三〕通靈山道，橋孫水，〔一四〕以通邛、莋。還報，天子大說。〔一五〕","sentenceOrder":37},
  {"id":"s_work_han_thu_69_38","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「使訖還報天子也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_69_39","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「物故，死也。解在蘇武傳。」","sentenceOrder":39},
  {"id":"s_work_han_thu_69_40","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　文穎曰：「邛者，今為邛都縣。莋者，今為定莋縣。」師古曰：「莋，才各反。」","sentenceOrder":40},
  {"id":"s_work_han_thu_69_41","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　師古曰：「今夔州、開州等首領姓冉者，皆舊冉種也。駹音尨。」","sentenceOrder":41},
  {"id":"s_work_han_thu_69_42","chapterId":"ch_work_han_thu_69","textTraditional":"〔五〕　師古曰：「異時猶言往時也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_69_43","chapterId":"ch_work_han_thu_69","textTraditional":"〔六〕　晉灼曰：「南夷謂犍為、牂牁也。西夷謂越巂、益州也。」師古曰：「愈，勝也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_69_44","chapterId":"ch_work_han_thu_69","textTraditional":"〔七〕　師古曰：「傳音張戀反。」","sentenceOrder":44},
  {"id":"s_work_han_thu_69_45","chapterId":"ch_work_han_thu_69","textTraditional":"〔八〕　師古曰：「迎於郊界之上也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_69_46","chapterId":"ch_work_han_thu_69","textTraditional":"〔九〕　師古曰：「導路也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_69_47","chapterId":"ch_work_han_thu_69","textTraditional":"〔一０〕師古曰：「尚猶配也，義與尚公主同。今流俗書本此尚字作當，蓋後人見前云文君恐不得當，故改此文以就之耳。」","sentenceOrder":47},
  {"id":"s_work_han_thu_69_48","chapterId":"ch_work_han_thu_69","textTraditional":"〔一一〕師古曰：「斥，開廣也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_69_49","chapterId":"ch_work_han_thu_69","textTraditional":"〔一二〕張揖曰：「沬水出蜀廣平徼外。若水出旄牛徼外。」師古曰：「沬音妹。」","sentenceOrder":49},
  {"id":"s_work_han_thu_69_50","chapterId":"ch_work_han_thu_69","textTraditional":"〔一三〕張揖曰：「徼謂以木石水為界者也。」如淳曰：「斯榆之君等自求去邊關，欲與牂牁作徼塞也。」師古曰：「徼音工釣反。」","sentenceOrder":50},
  {"id":"s_work_han_thu_69_51","chapterId":"ch_work_han_thu_69","textTraditional":"〔一四〕張揖曰：「鑿開靈山道，置靈道縣。孫水出臺登縣，南至會無入若水。」師古曰：「於孫水上作橋也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_69_52","chapterId":"ch_work_han_thu_69","textTraditional":"〔一五〕師古曰：「說讀曰悅。」","sentenceOrder":52},
  {"id":"s_work_han_thu_69_53","chapterId":"ch_work_han_thu_69","textTraditional":"相如使時，蜀長老多言通西南夷之不為用，大臣亦以為然。相如欲諫，業已建之，不敢，〔一〕乃著書，藉蜀父老為辭，而己詰難之，以風天子，〔二〕且因宣其使（詣）〔指〕，令百姓皆知天子意。其辭曰：","sentenceOrder":53},
  {"id":"s_work_han_thu_69_54","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「本由相如立此事，故不敢更諫也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_69_55","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「藉，假也。風讀曰諷。」","sentenceOrder":55},
  {"id":"s_work_han_thu_69_56","chapterId":"ch_work_han_thu_69","textTraditional":"漢興七十有八載，德茂存乎六世，威武紛云，湛恩汪濊〔一〕，群生霑濡，洋溢乎方外。〔二〕於是乃命使西征，隨流而攘〔三〕，風之所被，罔不披靡。〔四〕因朝冉從駹，定莋存邛，略斯榆，舉苞蒲，結軌還轅，東鄉將報，〔五〕至于蜀都。","sentenceOrder":56},
  {"id":"s_work_han_thu_69_57","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「紛云，盛貌。汪濊，深廣也。湛讀曰沈。汪音烏皇反。濊音於喙反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_69_58","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「洋音羊。」","sentenceOrder":58},
  {"id":"s_work_han_thu_69_59","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　師古曰：「攘，卻退也，音人羊反。」","sentenceOrder":59},
  {"id":"s_work_han_thu_69_60","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　師古曰：「被音丕靡反。」","sentenceOrder":60},
  {"id":"s_work_han_thu_69_61","chapterId":"ch_work_han_thu_69","textTraditional":"〔五〕　師古曰：「結，屈也。軌，車跡也。鄉讀曰嚮。報，報天子也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_69_62","chapterId":"ch_work_han_thu_69","textTraditional":"耆老大夫搢紳先生之徒二十有七人，儼然造焉。〔一〕辭畢，進曰：〔二〕「蓋聞天子之於夷狄也，其義羈縻勿絕而已。〔三〕今罷三郡之士，通夜郎之塗，〔四〕三年於茲，而功不竟，士卒勞倦，萬民不贍；今又接之以西夷，百姓力屈，恐不能卒業，〔五〕此亦使者之累也，〔六〕竊為左右患之。且夫邛、莋、西僰之與中國並也，歷年茲多，不可記已。〔七〕仁者不以德來，強者不以力并，意者殆不可乎！〔八〕今割齊民以附夷狄，弊所恃以事無用，〔九〕鄙人固陋，不識所謂。」","sentenceOrder":62},
  {"id":"s_work_han_thu_69_63","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「造，至也，音千到反。」","sentenceOrder":63},
  {"id":"s_work_han_thu_69_64","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「辭謂初謁見之辭。」","sentenceOrder":64},
  {"id":"s_work_han_thu_69_65","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　師古曰：「羈，馬絡頭也。縻，牛紖也。言牽制之，故取諭也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_69_66","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　師古曰：「罷讀曰疲。」","sentenceOrder":66},
  {"id":"s_work_han_thu_69_67","chapterId":"ch_work_han_thu_69","textTraditional":"〔五〕　師古曰：「屈，盡也。卒，終也。業，事也。屈音其勿反。」","sentenceOrder":67},
  {"id":"s_work_han_thu_69_68","chapterId":"ch_work_han_thu_69","textTraditional":"〔六〕　師古曰：「累音力瑞反。」","sentenceOrder":68},
  {"id":"s_work_han_thu_69_69","chapterId":"ch_work_han_thu_69","textTraditional":"〔七〕　師古曰：「已，（詔）〔語〕終之辭也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_69_70","chapterId":"ch_work_han_thu_69","textTraditional":"〔八〕　師古曰：「言古往帝王雖有仁德，不能招來之，雖有強力，不能并吞之，以其險遠，理不可也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_69_71","chapterId":"ch_work_han_thu_69","textTraditional":"〔九〕　師古曰：「所恃即中國之人也，無用謂西南夷也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_69_72","chapterId":"ch_work_han_thu_69","textTraditional":"使者曰：「烏謂此乎？〔一〕必若所云，則是蜀不變服而巴不化俗也，僕尚惡聞若說。〔二〕然斯事體大，固非觀者之所覯也。〔三〕余之行急，其詳不可得聞已。〔四〕請為大夫粗陳其略：〔五〕","sentenceOrder":72},
  {"id":"s_work_han_thu_69_73","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「烏，於何也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_69_74","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「尚，猶也。若，如也。言僕猶惡聞如此之說，況乎遠識之人也。惡音一故反。」","sentenceOrder":74},
  {"id":"s_work_han_thu_69_75","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　師古曰：「覯，見也，音搆。」","sentenceOrder":75},
  {"id":"s_work_han_thu_69_76","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　師古曰：「言行程急速，不暇為汝詳言之。」","sentenceOrder":76},
  {"id":"s_work_han_thu_69_77","chapterId":"ch_work_han_thu_69","textTraditional":"〔五〕　師古曰：「粗猶麄也，音千戶反。」","sentenceOrder":77},
  {"id":"s_work_han_thu_69_78","chapterId":"ch_work_han_thu_69","textTraditional":"「蓋世必有非常之人，然後有非常之事；有非常之事，然後有非常之功。非常者，固常人之所異也。〔一〕故曰非常之元，黎民懼焉；〔二〕及臻厥成，天下晏如也。〔三〕","sentenceOrder":78},
  {"id":"s_work_han_thu_69_79","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「常人見之以為異也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_69_80","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「元，始也。非常之事，其始難知，眾人懼之。」","sentenceOrder":80},
  {"id":"s_work_han_thu_69_81","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　師古曰：「臻，至也。晏，安也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_69_82","chapterId":"ch_work_han_thu_69","textTraditional":"「昔者，洪水沸出，氾濫衍溢，民人升降移徙，崎嶇而不安。夏后氏戚之，乃堙洪原，〔一〕決江疏河，灑沈澹災，東歸之於海，〔二〕而天下永寧。當斯之勤，豈惟民哉？心煩於慮，而身親其勞，躬傶骿胝無胈，膚不生毛，〔三〕故休烈顯乎無窮，聲稱浹乎于茲。〔四〕","sentenceOrder":82},
  {"id":"s_work_han_thu_69_83","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「堙，塞也。水本曰原。堙音因。」","sentenceOrder":83},
  {"id":"s_work_han_thu_69_84","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「疏，通也。灑，分也。沈，深也。澹，安也。言分散其深水，以安定其災也。灑音所宜反。澹音徒濫反。」","sentenceOrder":84},
  {"id":"s_work_han_thu_69_85","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　張揖曰：「躬，體也。戚，湊理也。」孟康曰：「胈，毳；膚，皮也。言禹勤，骿胝無有毳毛也。」師古曰：「（胈音步曷反）骿音步千反。胝音竹尸反。〔胈音步曷反〕。」","sentenceOrder":85},
  {"id":"s_work_han_thu_69_86","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　師古曰：「休，美也。烈，業也。浹，徹也。于茲猶言今茲也。浹音子牒反。」","sentenceOrder":86},
  {"id":"s_work_han_thu_69_87","chapterId":"ch_work_han_thu_69","textTraditional":"「且夫賢君之踐位也，豈特委瑣握〈足齒〉，拘文牽俗，〔一〕循誦習傳，當世取說云爾哉！〔二〕必將崇論谹議，〔三〕創業垂統，為萬世規。故馳騖乎兼容并包，而勤思乎參天貳地。〔四〕且詩不云乎？『普天之下，莫非王土；率土之濱，莫非王臣。』〔五〕是以六合之內，八方之外，〔六〕浸淫衍溢，〔七〕懷生之物有不浸潤於澤者，賢君恥之。今封疆之內，冠帶之倫，〔八〕咸獲嘉祉，靡有闕遺矣。而夷狄殊俗之國，遼絕異黨之域，舟車不通，人跡罕至，政教未加，流風猶微，內之則犯義侵禮於邊境，外之則邪行橫作，放殺其上，〔九〕君臣易位，尊卑失序，父兄不辜，幼孤為奴虜，係絫號泣。〔一０〕內鄉而怨，〔一一〕曰：『蓋聞中國有至仁焉，德洋恩普，物靡不得其所，〔一二〕今獨曷為遺己！』〔一三〕舉踵思慕，若枯旱之望雨，盭夫為之垂涕，〔一四〕況乎上聖，又烏能已？〔一五〕故北出師以討強胡，南馳使以誚勁越。〔一六〕四面風德，〔一七〕二方之君鱗集仰流，〔一八〕願得受號者以億計。〔一九〕故乃關沬、若，〔二０〕徼牂牁，鏤靈山，梁孫原，〔二一〕創道德之塗，垂仁義之統，將博恩廣施，遠撫長駕，〔二二〕使疏逖不閉，〔二三〕曶爽闇昧得燿乎光明，〔二四〕以偃甲兵於此，而息討伐於彼。遐邇一體，中外禔福，不亦康乎？〔二五〕夫拯民於沈溺，〔二六〕奉至尊之休德，〔二七〕反衰世之陵夷，繼周氏之絕業，〔二八〕天子之急務也。百姓雖勞，又惡可以已哉？〔二九〕","sentenceOrder":87},
  {"id":"s_work_han_thu_69_88","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「握〈足齒〉，局陿也。不拘微細之文，不牽流俗之議也。〈足齒〉音初角反。」","sentenceOrder":88},
  {"id":"s_work_han_thu_69_89","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「說讀曰悅。言非直因循自誦，習所傳聞，取美悅於當時而已。」","sentenceOrder":89},
  {"id":"s_work_han_thu_69_90","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　師古曰：「谹，深也，音宏。」","sentenceOrder":90},
  {"id":"s_work_han_thu_69_91","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　師古曰：「比德於地，是貳地也。地與己并天為三，是參天也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_69_92","chapterId":"ch_work_han_thu_69","textTraditional":"〔五〕　師古曰：「小雅北山之詩也。普，大也。濱，涯也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_69_93","chapterId":"ch_work_han_thu_69","textTraditional":"〔六〕　師古曰：「天地四方謂之六合，四方四維謂之八方也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_69_94","chapterId":"ch_work_han_thu_69","textTraditional":"〔七〕　師古曰：「浸淫猶漸漬也。衍溢言有餘也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_69_95","chapterId":"ch_work_han_thu_69","textTraditional":"〔八〕　師古曰：「倫，類也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_69_96","chapterId":"ch_work_han_thu_69","textTraditional":"〔九〕　師古曰：「內之，謂通其朝獻也。外之，謂棄而絕之也。橫音胡孟反。殺讀曰（試）〔弒〕。」","sentenceOrder":96},
  {"id":"s_work_han_thu_69_97","chapterId":"ch_work_han_thu_69","textTraditional":"〔一０〕師古曰：「為人所獲而絫係之，故號泣也。絫，（音）力追（切）〔反〕。」","sentenceOrder":97},
  {"id":"s_work_han_thu_69_98","chapterId":"ch_work_han_thu_69","textTraditional":"〔一一〕師古曰：「鄉讀曰嚮。嚮中國而怨慕也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_69_99","chapterId":"ch_work_han_thu_69","textTraditional":"〔一二〕師古曰：「洋，多也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_69_100","chapterId":"ch_work_han_thu_69","textTraditional":"〔一三〕師古曰：「曷，何也。己，謂怨者之身也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_69_101","chapterId":"ch_work_han_thu_69","textTraditional":"〔一四〕張揖曰：「很戾之夫也。」師古曰：「盭，古戾字。」","sentenceOrder":101},
  {"id":"s_work_han_thu_69_102","chapterId":"ch_work_han_thu_69","textTraditional":"〔一五〕師古曰：「烏猶焉也。已，止也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_69_103","chapterId":"ch_work_han_thu_69","textTraditional":"〔一六〕師古曰：「誚，責也，音材笑反。」","sentenceOrder":103},
  {"id":"s_work_han_thu_69_104","chapterId":"ch_work_han_thu_69","textTraditional":"〔一七〕師古曰：「風，化也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_69_105","chapterId":"ch_work_han_thu_69","textTraditional":"〔一八〕師古曰：「二方謂西夷及南夷也。若魚鱗之相次而仰向承流也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_69_106","chapterId":"ch_work_han_thu_69","textTraditional":"〔一九〕師古曰：「號謂爵號也，一曰受天子之號令也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_69_107","chapterId":"ch_work_han_thu_69","textTraditional":"〔二０〕張揖曰：「以沬、若水為關也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_69_108","chapterId":"ch_work_han_thu_69","textTraditional":"〔二一〕師古曰：「鏤謂疏通之以開道也。梁，橋也。孫原，孫水之原也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_69_109","chapterId":"ch_work_han_thu_69","textTraditional":"〔二二〕張揖曰：「駕，行也，使恩遠安長行之也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_69_110","chapterId":"ch_work_han_thu_69","textTraditional":"〔二三〕師古曰：「逖，遠也，言疏遠者不被閉絕也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_69_111","chapterId":"ch_work_han_thu_69","textTraditional":"〔二四〕師古曰：「曶爽，未明也。曶音忽。」","sentenceOrder":111},
  {"id":"s_work_han_thu_69_112","chapterId":"ch_work_han_thu_69","textTraditional":"〔二五〕師古曰：「禔，安也。康，樂也。禔音土支反。」","sentenceOrder":112},
  {"id":"s_work_han_thu_69_113","chapterId":"ch_work_han_thu_69","textTraditional":"〔二六〕師古曰：「（沈）〔拯〕，升也，言人在沈溺之中，升而舉之也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_69_114","chapterId":"ch_work_han_thu_69","textTraditional":"〔二七〕師古曰：「休，美也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_69_115","chapterId":"ch_work_han_thu_69","textTraditional":"〔二八〕師古曰：「陵夷謂弛替也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_69_116","chapterId":"ch_work_han_thu_69","textTraditional":"〔二九〕師古曰：「惡讀與烏同。已，止也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_69_117","chapterId":"ch_work_han_thu_69","textTraditional":"「且夫王者固未有不始於憂勤，而終於佚樂者也。〔一〕然則受命之符合在於此。〔二〕方將增太山之封，加梁父之事，鳴和鸞，揚樂頌，上咸五，下登三。〔三〕觀者未睹指，聽者未聞音，猶焦朋已翔乎寥廓，〔四〕而羅者猶視乎藪澤，〔五〕悲夫！」","sentenceOrder":117},
  {"id":"s_work_han_thu_69_118","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「言始能憂勤則終獲逸樂也。佚字與逸同。」","sentenceOrder":118},
  {"id":"s_work_han_thu_69_119","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　張揖曰：「合在於憂勤逸樂之中也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_69_120","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　李奇曰：「五帝之德比漢為減，三王之德漢出其上。」師古曰：「此說非也。咸，皆也，言漢德與五帝皆盛，而登於三王之上也。相如不當言漢減於五帝也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_69_121","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　師古曰：「寥廓，天上寬廣之處。寥音聊。」","sentenceOrder":121},
  {"id":"s_work_han_thu_69_122","chapterId":"ch_work_han_thu_69","textTraditional":"〔五〕　師古曰：「澤無水曰藪。」","sentenceOrder":122},
  {"id":"s_work_han_thu_69_123","chapterId":"ch_work_han_thu_69","textTraditional":"於是諸大夫茫然〔一〕喪其所懷來，失厥所以進，〔二〕喟然並稱曰：「允哉漢德，〔三〕此鄙人之所願聞也。百姓雖勞，請以身先之。」敞罔靡徙，遷延而辭避。〔四〕","sentenceOrder":123},
  {"id":"s_work_han_thu_69_124","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「茫音莫郎反。」","sentenceOrder":124},
  {"id":"s_work_han_thu_69_125","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「初有所懷而來，欲進而陳之，今並喪失其來意也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_69_126","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　師古曰：「允，信也。小雅車攻之詩曰『允矣君子』。」","sentenceOrder":126},
  {"id":"s_work_han_thu_69_127","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　師古曰：「敞罔，失志貌。靡徙，自抑退也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_69_128","chapterId":"ch_work_han_thu_69","textTraditional":"其後人有上書言相如使時受金，失官。居歲餘，復召為郎。","sentenceOrder":128},
  {"id":"s_work_han_thu_69_129","chapterId":"ch_work_han_thu_69","textTraditional":"相如口吃而善著書。常有消渴病。與卓氏婚，饒於財。故其（事）〔仕〕宦，未嘗肯與公卿國家之事，〔一〕常稱疾閒居，不慕官爵。〔二〕嘗從上至長楊獵。〔三〕是時天子方好自擊熊豕，馳逐野獸，相如因上疏諫。其辭曰：","sentenceOrder":129},
  {"id":"s_work_han_thu_69_130","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「與讀曰豫。」","sentenceOrder":130},
  {"id":"s_work_han_thu_69_131","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「閒讀曰閑也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_69_132","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　師古曰：「長楊宮也，在{執皿}厔。」","sentenceOrder":132},
  {"id":"s_work_han_thu_69_133","chapterId":"ch_work_han_thu_69","textTraditional":"臣聞物有同類而殊能者，故力稱烏獲，捷言慶忌，〔一〕勇期賁育。〔二〕臣之愚，竊以為人誠有之，獸亦宜然。今陛下好陵阻險，射猛獸，卒然遇逸材之獸，駭不存之地，〔三〕犯屬車之清塵，〔四〕輿不及還轅，人不暇施巧，雖有烏獲、逢蒙之技不能用，〔五〕枯木朽株盡為難矣。是胡越起於轂下，而羌夷接軫也，豈不殆哉！〔六〕雖萬全而無患，然本非天子之所宜近也。","sentenceOrder":133},
  {"id":"s_work_han_thu_69_134","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「烏獲，秦武王力士也。慶忌，吳王僚子也，射能捷矢也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_69_135","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「孟賁，古之勇士也，水行不避蛟龍，陸行不避豺狼，發怒吐氣，聲響動天。夏育，亦猛士也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_69_136","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　師古曰：「卒讀曰猝，音千忽反，謂暴疾也。不存，不可得安存也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_69_137","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　應劭曰：「古者諸侯貳車九乘，秦滅九國，兼其車服，漢依秦制，故大駕屬車八十一乘。」師古曰：「屬者，言相連續不絕也。塵謂行而起塵也。言清者，尊貴之意也。而說者乃以為清道灑塵謂之清塵，非也。屬音之欲反。」","sentenceOrder":137},
  {"id":"s_work_han_thu_69_138","chapterId":"ch_work_han_thu_69","textTraditional":"〔五〕　師古曰：「逢蒙，古之善射者也。孟子曰『逢蒙學射於羿也』。」","sentenceOrder":138},
  {"id":"s_work_han_thu_69_139","chapterId":"ch_work_han_thu_69","textTraditional":"〔六〕　師古曰：「軫，車後橫木。殆，危也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_69_140","chapterId":"ch_work_han_thu_69","textTraditional":"且夫清道而後行，中路而馳，猶時有銜橜之變。〔一〕況乎涉豐草，騁丘虛，〔二〕前有利獸之樂，而內無存變之意，其為害也不〔亦〕難矣！夫輕萬乘之重不以為安，樂出萬有一危之塗以為娛，臣竊為陛下不取。","sentenceOrder":140},
  {"id":"s_work_han_thu_69_141","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　張揖曰：「銜，馬勒銜也。橛，騑馬口長銜也。」師古曰：「橛謂車之鉤心也。銜橛之變，言馬銜或斷，鉤心或出，則致傾敗以傷人也。橛音鉅月反。」","sentenceOrder":141},
  {"id":"s_work_han_thu_69_142","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「豐草，茂草也。虛讀曰墟。」","sentenceOrder":142},
  {"id":"s_work_han_thu_69_143","chapterId":"ch_work_han_thu_69","textTraditional":"蓋明者遠見於未萌，而知者避危於無形，〔一〕禍固多藏於隱微而發於人之所忽者也。故鄙諺曰：「家絫千金，坐不垂堂。〔二〕」此言雖小，可以諭大。臣願陛下留意幸察。","sentenceOrder":143},
  {"id":"s_work_han_thu_69_144","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「萌謂事始，若草木初生者也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_69_145","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　張揖曰：「畏櫩瓦墮中人也。」師古曰：「垂堂者，近堂邊外，自恐墜墮耳，非畏櫚瓦也。言富人之子則自愛深也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_69_146","chapterId":"ch_work_han_thu_69","textTraditional":"上善之。還過宜春宮，相如奏賦以哀二世行失。〔一〕其辭曰：","sentenceOrder":146},
  {"id":"s_work_han_thu_69_147","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「宜春本秦之離宮，胡亥於此為閻樂所殺，故感其處而哀之。」","sentenceOrder":147},
  {"id":"s_work_han_thu_69_148","chapterId":"ch_work_han_thu_69","textTraditional":"登陂陁之長阪兮，坌入會宮之嵯峨。〔一〕臨曲江之隑州兮，望南山之參差。〔二〕巖巖深山之谾谾兮，通谷〈谷害〉乎〈谷今〉谺。〔三〕汨淢靸以永逝兮，注平皋之廣衍。〔四〕觀眾樹之蓊薆兮，覽竹林之榛榛。〔五〕東馳土山兮，北揭石瀨。〔六〕弭節容與兮，歷弔二世。持身不謹兮，亡國失勢；信讒不寤兮，宗廟滅絕。〔七〕烏乎！操行之不得，〔八〕墓蕪穢而不修兮，魂亡歸而不食。","sentenceOrder":148},
  {"id":"s_work_han_thu_69_149","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　蘇林曰：「坌音馬坌叱之坌。」張揖曰：「坌，並也。」師古曰：「曾，重也。嵯峨，高貌也。陂音普何反。陁音徒何反。坌音普頓反，又音步頓反。」","sentenceOrder":149},
  {"id":"s_work_han_thu_69_150","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　張揖曰：「隑，長也。苑中有曲江之象，中有長洲也。」師古曰：「曲岸頭曰隑。隑即碕字耳。言臨曲岸之洲，今猶謂其處曰曲江。隑音鉅依反。」","sentenceOrder":150},
  {"id":"s_work_han_thu_69_151","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　晉灼曰：「谾音籠，古豅字也。」師古曰：「谾谾，深通貌。〈谷害〉音呼活反。〈谷今〉，大開貌。〈谷今〉音呼含反。谺音呼加反。」","sentenceOrder":151},
  {"id":"s_work_han_thu_69_152","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　師古曰：「汨淢，疾貌也。靸然，輕舉意也。皋，水邊地也。汨音于筆反。淢音域。靸音先合反。」","sentenceOrder":152},
  {"id":"s_work_han_thu_69_153","chapterId":"ch_work_han_thu_69","textTraditional":"〔五〕　師古曰：「蓊薆，蔭蔽貌。榛榛，盛貌。蓊音烏孔反。薆音愛。榛音側巾反。」","sentenceOrder":153},
  {"id":"s_work_han_thu_69_154","chapterId":"ch_work_han_thu_69","textTraditional":"〔六〕　師古曰：「揭，褰衣而渡也。石而淺水曰瀨，音賴。揭音丘例反。」","sentenceOrder":154},
  {"id":"s_work_han_thu_69_155","chapterId":"ch_work_han_thu_69","textTraditional":"〔七〕　師古曰：「信讒，謂殺李斯也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_69_156","chapterId":"ch_work_han_thu_69","textTraditional":"〔八〕　師古曰：「操音千到反。」","sentenceOrder":156},
  {"id":"s_work_han_thu_69_157","chapterId":"ch_work_han_thu_69","textTraditional":"相如拜為孝文園令。上既美子虛之事，相如見上好僊，因曰：「上林之事未足美也，尚有靡者。〔一〕臣嘗為大人賦，未就，〔二〕請具而奏之。」相如以為列僊之儒居山澤間，〔三〕形容甚臞，〔四〕此非帝王之僊意也，乃遂奏大人賦。其辭曰：","sentenceOrder":157},
  {"id":"s_work_han_thu_69_158","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「靡，麗也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_69_159","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「就，成也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_69_160","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　師古曰：「儒，柔也，術士之稱也，凡有道術皆為儒。今流俗書本作傳字，非也，後人所改耳。」","sentenceOrder":160},
  {"id":"s_work_han_thu_69_161","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　師古曰：「臞，瘠也，音鉅句反，又音衢。」","sentenceOrder":161},
  {"id":"s_work_han_thu_69_162","chapterId":"ch_work_han_thu_69","textTraditional":"世有大人兮，在乎中州。〔一〕宅彌萬里兮，曾不足以少留。〔二〕悲世俗之迫隘兮，朅輕舉而遠游。〔三〕乘絳幡之素蜺兮，載雲氣而上浮。〔四〕建格澤之修竿兮，〔五〕總光燿之采旄。〔六〕垂旬始以為幓兮，〔七〕曳彗星而為髾。〔八〕掉指橋以偃寋兮，〔九〕又猗抳以招搖。〔一０〕〈扌監〉攙搶以為旌兮，靡屈虹而為綢〔一一〕。紅杳眇以玄湣兮，猋風涌而雲浮。〔一二〕駕應龍象輿之蠖略委麗兮，驂赤螭青虯之蚴蟉宛蜒。〔一三〕低卬夭蟜裾以驕驁兮，詘折隆窮躩以連卷。〔一四〕沛艾赳螑仡以佁儗兮，〔一五〕放散畔岸驤以孱顏。〔一六〕跮踱輵螛容以骫麗兮，〔一七〕蜩蟉偃寋怵以梁倚。〔一八〕糾蓼叫奡踏以朡路兮，〔一九〕薎蒙踊躍騰而狂趭。〔二０〕蒞颯芔歙焱至電過兮，煥然霧除，霍然雲消。〔二一〕","sentenceOrder":162},
  {"id":"s_work_han_thu_69_163","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「大人，以諭天子也。中州，中國也。」","sentenceOrder":163},
  {"id":"s_work_han_thu_69_164","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「彌，滿也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_69_165","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　師古曰：「朅，去意也，音丘例反。」","sentenceOrder":165},
  {"id":"s_work_han_thu_69_166","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　張揖曰：「乘，用也。赤氣為幡，綴以白氣也。」師古曰：「上音時掌反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_69_167","chapterId":"ch_work_han_thu_69","textTraditional":"〔五〕　張揖曰：「格澤之氣如炎火狀，黃白色，起地上至天，下大上銳。修，長也。建此氣為長竿也。」師古曰：「格音胡各反。澤音大各反。」","sentenceOrder":167},
  {"id":"s_work_han_thu_69_168","chapterId":"ch_work_han_thu_69","textTraditional":"〔六〕　張揖曰：「旄，葆也。總，係也。係光耀之氣於長竿以為葆也。」師古曰：「總音摠。葆即今所謂纛頭也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_69_169","chapterId":"ch_work_han_thu_69","textTraditional":"〔七〕　李奇曰：「旬始，氣如雄雞，見北斗旁。」張揖曰：「幓，旒也。縣旬始於葆下，以為十二旒也。」師古曰：「幓音所銜反。」","sentenceOrder":169},
  {"id":"s_work_han_thu_69_170","chapterId":"ch_work_han_thu_69","textTraditional":"〔八〕　張揖曰：「髾，燕尾也。枻彗星綴者旒以為燕尾也。」","sentenceOrder":170},
  {"id":"s_work_han_thu_69_171","chapterId":"ch_work_han_thu_69","textTraditional":"〔九〕　張揖曰：「指橋，隨風指靡也。偃寋，委曲貌。」師古曰：「掉音徒釣反。寋音居偃反。」","sentenceOrder":171},
  {"id":"s_work_han_thu_69_172","chapterId":"ch_work_han_thu_69","textTraditional":"〔一０〕晉灼曰：「猗音依倚反。抳音年纚反。」張揖曰：「猗抳，下垂貌。招搖，跳踃也。」師古曰：「招音韶。踃音蕭。」","sentenceOrder":172},
  {"id":"s_work_han_thu_69_173","chapterId":"ch_work_han_thu_69","textTraditional":"〔一一〕　張揖曰：「彗星為攙搶。注髦首曰旌，今以彗星代之也。靡，順也。綢，韜也。以斷虹為旌杠之韜也。」師古曰：「韜謂（裏）〔裹〕冒旌旗之竿也。攙音初咸反。搶音初衡反。屈音其勿反。綢音直流反。」","sentenceOrder":173},
  {"id":"s_work_han_thu_69_174","chapterId":"ch_work_han_thu_69","textTraditional":"〔一二〕　蘇林曰：「玄音炫。湣音麵。」晉灼曰：「紅，赤色貌。杳眇，深遠也。玄湣，混合也。言自絳幡以下，眾氣色盛，光采相燿，幽藹炫亂也。」師古曰：「如猋風之涌，如雲之浮，言輕舉也。猋音必遙反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_69_175","chapterId":"ch_work_han_thu_69","textTraditional":"〔一三〕　文穎曰：「有翼曰應龍，最其神妙者也。」師古曰：「蠖略委麗、蚴蟉宛蜒，皆其行步進止之貌也。蠖音於縛反，麗音力爾反。蚴音一糾反。蟉音力糾反。宛音於元反。蜒音延。」","sentenceOrder":175},
  {"id":"s_work_han_thu_69_176","chapterId":"ch_work_han_thu_69","textTraditional":"〔一四〕　張揖曰：「裾，直項也。驕驁，縱恣也。詘折，曲委也。隆窮，舉{髟者}也。躩，跳也。連卷，句蹄也。」師古曰：「裾音倨。驕音居召反。驁音五到反。躩音鉅縛反。卷音鉅圓反。」","sentenceOrder":176},
  {"id":"s_work_han_thu_69_177","chapterId":"ch_work_han_thu_69","textTraditional":"〔一五〕　張揖曰：「沛艾，駊騀也。赳螑，申頸低卬也。仡，舉頭也。佁儗，不前也。」師古曰：「沛音普蓋反。赳音古幼反。螑音火幼反。仡音魚乞反。佁音丑吏反。儗音魚吏反。佁儗又音態礙。」","sentenceOrder":177},
  {"id":"s_work_han_thu_69_178","chapterId":"ch_work_han_thu_69","textTraditional":"〔一六〕　師古曰：「畔岸，自縱之貌也。驤，舉也。孱顏，不齊也。孱音士顏反。」","sentenceOrder":178},
  {"id":"s_work_han_thu_69_179","chapterId":"ch_work_han_thu_69","textTraditional":"〔一七〕　張揖曰：「跮踱，互前卻也。輵螛，搖目吐舌也。容，龍體貌也。骫麗，左右相隨也。」師古：「跮音丑日反。踱音丑略反。輵音遏。螛音曷。骫，古委字也。麗音力爾反。」","sentenceOrder":179},
  {"id":"s_work_han_thu_69_180","chapterId":"ch_work_han_thu_69","textTraditional":"〔一八〕　張揖曰：「蜩蟉，掉頭也。怵，奔走也。梁倚，相著也。」師古曰：「蜩音徒釣反。蟉音盧釣反。怵音黜。音丑若反。倚音於綺反。」","sentenceOrder":180},
  {"id":"s_work_han_thu_69_181","chapterId":"ch_work_han_thu_69","textTraditional":"〔一九〕　張揖曰：「糾蓼，相引也。叫奡，相呼也。踏，下也。朡，著也。皆下著道也。」師古曰：「叫奡，高舉之貌。蓼音力糾反。奡音五到反。踏音沓。朡音屆。」","sentenceOrder":181},
  {"id":"s_work_han_thu_69_182","chapterId":"ch_work_han_thu_69","textTraditional":"〔二０〕張揖曰：「薎蒙，飛揚也。踊躍，跳也。騰，馳也。趭，奔走也。」師古曰：「蒙音莫孔反。趭音醮。」","sentenceOrder":182},
  {"id":"s_work_han_thu_69_183","chapterId":"ch_work_han_thu_69","textTraditional":"〔二一〕張揖曰：「蒞颯，飛相及也。芔歙，走相追也。」師古曰：「蒞音利。颯音立。芔音諱。歙音翕。」","sentenceOrder":183},
  {"id":"s_work_han_thu_69_184","chapterId":"ch_work_han_thu_69","textTraditional":"邪絕少陽而登太陰兮，與真人乎相求。〔一〕互折窈窕以右轉兮，橫厲飛泉以正東。〔二〕悉徵靈圉而選之兮，部署眾神於搖光。〔三〕使五帝先導兮，反大壹而從陵陽。〔四〕左玄冥而右黔雷兮，〔五〕前長離而後矞皇。〔六〕廝征伯僑而役羨門兮，詔岐伯使尚方。〔七〕祝融警而蹕御兮，清氣氛而后行。〔八〕屯余車而萬乘兮，綷雲蓋而樹華旗。〔九〕使句芒其將行兮，吾欲往乎南娭。〔一０〕","sentenceOrder":184},
  {"id":"s_work_han_thu_69_185","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　張揖曰：「少陽，東極。太陰，北極。邪度東極而升北極也。真人，謂若士也，游於太陰之中。」師古曰：「真人，至真之人也，非指謂若士也。」","sentenceOrder":185},
  {"id":"s_work_han_thu_69_186","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　張揖曰：「飛泉，飛谷也，在崑崙山西南。」師古曰：「厲，渡也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_69_187","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　張揖曰：「搖光，北斗杓頭第一星。」","sentenceOrder":187},
  {"id":"s_work_han_thu_69_188","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　應劭曰：「五帝，五畤，太皞之屬也。」如淳曰：「天極，大星，一明者，太一常居也。」張揖曰：「陵陽，仙人陵陽子明也。」師古曰：「令太一反其所居，而使陵陽侍從於己。」","sentenceOrder":188},
  {"id":"s_work_han_thu_69_189","chapterId":"ch_work_han_thu_69","textTraditional":"〔五〕　張揖曰：「玄冥，北方黑帝佐也。黔雷，黔嬴也，天上造化神名也。楚辭曰『召黔嬴而見之』。或曰水神也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_69_190","chapterId":"ch_work_han_thu_69","textTraditional":"〔六〕　服虔曰：「皆神名也。」師古曰：「長離，靈鳥也，解在禮樂志。矞音以出反。」","sentenceOrder":190},
  {"id":"s_work_han_thu_69_191","chapterId":"ch_work_han_thu_69","textTraditional":"〔七〕　應劭曰：「廝，役也。」張揖曰：「伯僑，仙人王子僑也。羨門，碣石山上仙人羨門高也。尚，主也。岐伯者，黃帝太醫，屬使主方藥也。」師古曰：「征伯僑者，仙人，姓征，名伯僑，非王子僑也。郊祀志征字作正，其音同耳。或說云征謂役使之，非也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_69_192","chapterId":"ch_work_han_thu_69","textTraditional":"〔八〕　張揖曰：「祝融，南方炎帝之佐也，獸身人面，乘兩龍。」師古曰：「蹕，止行人也。御，禦也。氛，惡氣也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_69_193","chapterId":"ch_work_han_thu_69","textTraditional":"〔九〕　師古曰：「綷，合也，合五采雲以為蓋也。綷音子內反。」","sentenceOrder":193},
  {"id":"s_work_han_thu_69_194","chapterId":"ch_work_han_thu_69","textTraditional":"〔一０〕張揖曰：「句芒，東方青帝之佐也，鳥身人面，乘兩龍。」師古曰：「將行，將領從行也。娭音許其反。」","sentenceOrder":194},
  {"id":"s_work_han_thu_69_195","chapterId":"ch_work_han_thu_69","textTraditional":"歷唐堯於崇山兮，過虞舜於九疑。〔一〕紛湛湛其差錯兮，雜遝膠輵以方馳。〔二〕騷擾衝蓯其（相）紛挐兮，滂濞泱軋麗以林離。〔三〕攢羅列聚叢以蘢茸兮，衍曼流爛痑以陸離。〔四〕徑入雷室之砰磷鬱律兮，洞出鬼谷之堀礨崴魁。〔五〕遍覽八紘而觀四海兮，朅度九江越五河。〔六〕經營炎火而浮弱水兮，杭絕浮渚涉流沙。〔七〕奄息蔥極氾濫水娭兮，〔八〕使靈媧鼓琴而舞馮夷。〔九〕時若曖曖將混濁兮，召屏翳誅風伯，刑雨師。〔一０〕西望崑崙之軋沕荒忽兮，〔一一〕直徑馳乎三危。〔一二〕排閶闔而入帝宮兮，載玉女而與之歸。〔一三〕登閬風而遙集兮，亢鳥騰而壹止。〔一四〕低徊陰山翔以紆曲兮，吾乃今日睹西王母。暠然白首戴勝而穴處兮，亦幸有三足烏為之使。〔一五〕必長生若此而不死兮，雖濟萬世不足以喜。〔一六〕","sentenceOrder":195},
  {"id":"s_work_han_thu_69_196","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　張揖曰：「崇山，狄山也。海外經曰狄山，帝堯葬於其陽。九疑山在零陵營道縣，舜所葬也。」師古曰：「疑，似也。山有九峰，其形相似，故曰九疑。」","sentenceOrder":196},
  {"id":"s_work_han_thu_69_197","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「湛湛，積厚之貌。差錯，交互也。雜遝，重絫也。膠輵猶交加也。湛音徒感反。遝音大合反。輵音葛。」","sentenceOrder":197},
  {"id":"s_work_han_thu_69_198","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　張揖曰：「衝蓯，相入貌。滂濞，眾盛貌。泱軋，不前也。麗，靡也。林離，槮欐也。」師古曰：「衝音尺勇反。蓯音相勇反。挐音女居反。滂音普郎反。濞音普備反。泱音烏朗反。軋音於黠反。槮音所林反。欐音所宜反。」","sentenceOrder":198},
  {"id":"s_work_han_thu_69_199","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　張揖曰：「痑，眾貌，一曰罷極也。陸離，參差也。」師古曰：「蘢茸，聚貌。流爛，布散也。痑，自放縱也。蘢音來孔反。茸音而孔反。衍音弋扇反。痑音式爾反，張云罷極，義則非矣。」","sentenceOrder":199},
  {"id":"s_work_han_thu_69_200","chapterId":"ch_work_han_thu_69","textTraditional":"〔五〕　張揖曰：「雷室，雷淵也。洞，通也。鬼谷在崑崙北直北辰下，眾鬼之所聚也。堀礨崴魁，不平也。」師古曰：「砰磷鬱律，深峻貌。砰音普萌反。磷音力耕反。堀音口骨反。礨音洛賄反。崴音一迴反。」","sentenceOrder":200},
  {"id":"s_work_han_thu_69_201","chapterId":"ch_work_han_thu_69","textTraditional":"〔六〕　張揖曰：「九江在廬江尋陽縣南，皆東合為大江者。」服虔曰：「河有九，今越其五也。」晉灼曰：「五河，五湖，取河之聲合其音耳。」師古曰：「服、晉說五河皆非也。五河，五色之河也。仙經說有紫碧絳青黃之河，非謂九河之內，亦非五（河）〔湖〕也。」","sentenceOrder":201},
  {"id":"s_work_han_thu_69_202","chapterId":"ch_work_han_thu_69","textTraditional":"〔七〕　應劭曰：「楚辭曰『越炎火之萬里』。弱水出張掖刪丹，西至酒泉合黎餘波入于流沙。」張揖曰：「杭，船也。絕，度也。浮渚，流沙中渚也。流沙，沙與水流行也。」師古曰：「弱水謂西域絕遠之水，乘毛車以度者耳，非張掖弱水也。又流沙但有沙流，本無水也。言絕度浮渚，乃涉流沙也。杭音下郎反。」","sentenceOrder":202},
  {"id":"s_work_han_thu_69_203","chapterId":"ch_work_han_thu_69","textTraditional":"〔八〕　張揖曰：「奄然休息也。蔥極，蔥領山也，在西域中。」","sentenceOrder":203},
  {"id":"s_work_han_thu_69_204","chapterId":"ch_work_han_thu_69","textTraditional":"〔九〕　服虔曰：「靈媧，女媧也。伏犧作琴，使女媧鼓之。馮夷，河伯字也，淮南子曰『馮夷得道以潛大川』。」師古曰：「媧音瓜，又工蛙反。」","sentenceOrder":204},
  {"id":"s_work_han_thu_69_205","chapterId":"ch_work_han_thu_69","textTraditional":"〔一０〕應劭曰：「屏翳，天神使也。」張揖曰：「風伯字飛廉。」師古曰：「屏音步丁反。」","sentenceOrder":205},
  {"id":"s_work_han_thu_69_206","chapterId":"ch_work_han_thu_69","textTraditional":"〔一一〕張揖曰：「崑崙去中國五萬里，天帝之下都也。其山廣袤百里，高八萬仞，增城九重，面有九井，以玉為檻，旁有五門，開明獸守之。軋沕荒忽，不分明之貌。」師古曰：「沕音勿。荒音呼廣反。」","sentenceOrder":206},
  {"id":"s_work_han_thu_69_207","chapterId":"ch_work_han_thu_69","textTraditional":"〔一二〕張揖曰：「三危山在鳥鼠山之西，與瑉山相近，黑水出其南陂，書曰『導黑水至于三危』也。」","sentenceOrder":207},
  {"id":"s_work_han_thu_69_208","chapterId":"ch_work_han_thu_69","textTraditional":"〔一三〕張揖曰：「玉女，青要、乘弋等也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_69_209","chapterId":"ch_work_han_thu_69","textTraditional":"〔一四〕張揖曰：「閬風山在崑崙閶闔之中。遙，遠也。」應劭曰：「亢然高飛，如鳥之騰也。」師古曰：「閬音浪。亢音抗。」","sentenceOrder":209},
  {"id":"s_work_han_thu_69_210","chapterId":"ch_work_han_thu_69","textTraditional":"〔一五〕張揖曰：「陰山在崑崙西二千七百里。西王母其狀如人，豹尾虎首，蓬髮暠然白首，石城金室，穴居其中。三足鳥，三足青鳥也，主為西王母取食，在崑崙墟之北。」如淳曰：「山海經曰『西王母梯几而戴勝』。」師古曰：「低徊猶徘徊也。勝，婦人首飾也，漢代謂之（革）〔華〕勝。暠音工老反，字或作翯，音學。」","sentenceOrder":210},
  {"id":"s_work_han_thu_69_211","chapterId":"ch_work_han_thu_69","textTraditional":"〔一六〕師古曰：「昔之談者咸以西王母為仙靈之最，故相如言大人之仙，娛遊之盛，顧視王母，鄙而陿之，不足羨慕也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_69_212","chapterId":"ch_work_han_thu_69","textTraditional":"回車朅來兮，絕道不周，〔一〕會食幽都。呼吸沆瀣兮餐朝霞，〔二〕咀噍芝英兮嘰瓊華。〔三〕僸祲尋而高縱兮，紛鴻溶而上厲。〔四〕貫列缺之倒景兮，〔五〕涉豐隆之滂濞。〔六〕騁游道而脩降兮，騖遺霧而遠逝。〔七〕迫區中之隘陝兮，舒節出乎北垠〔八〕。遺屯騎於玄闕兮，〔九〕軼先驅於寒門。〔一０〕下崢嶸而無地兮，〔一一〕上嵺廓而無天。〔一二〕視眩泯而亡見兮，聽敞怳而亡聞。〔一三〕乘虛亡而上遐兮，超無友而獨存。〔一四〕","sentenceOrder":212},
  {"id":"s_work_han_thu_69_213","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　張揖曰：「不周山在崑崙東南二千三百里也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_69_214","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　張揖曰：「幽都在北方。」如淳曰：「淮南云八極西北曰幽都之門。」應劭曰：「列仙傳陵陽子言春（朗）〔食〕朝霞，朝霞者，日始欲出赤黃氣也。夏食沆瀣，沆瀣，北方夜半氣也。并天地玄黃之氣為六氣。」師古曰：「沆音胡朗反。瀣音韰。」","sentenceOrder":214},
  {"id":"s_work_han_thu_69_215","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　張揖曰：「芝，草蒻也。榮而不實謂之英。嘰，食也。瓊樹生崑崙西流沙濱，大三百圍，高萬仞。華，橤也，食之長生。」師古曰：「芝英，芝菌之英也。咀音才汝反。噍音才笑反，又音才弱反。嘰音機，又音祈。」","sentenceOrder":215},
  {"id":"s_work_han_thu_69_216","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　張揖曰：「僸，卬也。鴻溶，竦踊也。」師古曰：「僸音角甚反。祲音子禁反。鴻音胡孔反。溶音弋孔反。」","sentenceOrder":216},
  {"id":"s_work_han_thu_69_217","chapterId":"ch_work_han_thu_69","textTraditional":"〔五〕　服虔曰：「列缺，天閃也。人在天上，下向視日月，故景倒在下也。」張揖曰：「貫，穿也。陵陽子明經曰列缺氣去地二千四百里，倒景氣去地四千里，其景皆倒在下也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_69_218","chapterId":"ch_work_han_thu_69","textTraditional":"〔六〕　應劭曰：「豐隆，雲師也。楚辭曰『吾令豐隆乘雲兮』。淮南子曰『季春三月，豐隆乃出以將雨』。」師古曰：「豐隆將雨，故言涉也。滂濞，雨水多也。滂音普郎反。濞音匹備反。」","sentenceOrder":218},
  {"id":"s_work_han_thu_69_219","chapterId":"ch_work_han_thu_69","textTraditional":"〔七〕　張揖曰：「馳疾而遺霧在後也。」師古曰：「游，游車也。道，道車也。脩，長也。降，下也。言周覽天上，然後騁車也，循長路而下馳，棄遺霧而遠逝也。道讀曰導。」","sentenceOrder":219},
  {"id":"s_work_han_thu_69_220","chapterId":"ch_work_han_thu_69","textTraditional":"〔八〕　師古曰：「舒，緩也。垠，崖也，音銀。」","sentenceOrder":220},
  {"id":"s_work_han_thu_69_221","chapterId":"ch_work_han_thu_69","textTraditional":"〔九〕　張揖曰：「玄闕，北極之山也。」","sentenceOrder":221},
  {"id":"s_work_han_thu_69_222","chapterId":"ch_work_han_thu_69","textTraditional":"〔一０〕應劭曰：「寒門，北極之門也。」師古曰：「軼，過也，音逸。」","sentenceOrder":222},
  {"id":"s_work_han_thu_69_223","chapterId":"ch_work_han_thu_69","textTraditional":"〔一一〕師古曰：「崢嶸，深遠貌。崢音仕耕反。嶸音宏。」","sentenceOrder":223},
  {"id":"s_work_han_thu_69_224","chapterId":"ch_work_han_thu_69","textTraditional":"〔一二〕師古曰：「嵺廓，廣遠也。嵺音遼。」","sentenceOrder":224},
  {"id":"s_work_han_thu_69_225","chapterId":"ch_work_han_thu_69","textTraditional":"〔一三〕師古曰：「眩泯，目不安也。敞怳，耳不諦也。眩音州縣之縣。泯音眄。」","sentenceOrder":225},
  {"id":"s_work_han_thu_69_226","chapterId":"ch_work_han_thu_69","textTraditional":"〔一四〕師古曰：「上音時掌反。」","sentenceOrder":226},
  {"id":"s_work_han_thu_69_227","chapterId":"ch_work_han_thu_69","textTraditional":"相如既奏大人賦，天子大說，〔一〕飄飄有陵雲氣游天地之閒意。","sentenceOrder":227},
  {"id":"s_work_han_thu_69_228","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":228},
  {"id":"s_work_han_thu_69_229","chapterId":"ch_work_han_thu_69","textTraditional":"相如既病免，家居茂陵。天子曰：「司馬相如病甚，可往從悉取其書，若後之矣。」〔一〕使所忠往，〔二〕而相如已死，家無遺書。問其妻，對曰：「長卿未嘗有書也。時時著書，人又取去。長卿未死時，為一卷書，曰有使來求書，奏之。」其遺札書言封禪事，〔三〕所忠奏焉，天子異之。其辭曰：","sentenceOrder":229},
  {"id":"s_work_han_thu_69_230","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「若，汝也。言汝今去已在他人後也。」","sentenceOrder":230},
  {"id":"s_work_han_thu_69_231","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「使者姓名也，解在食貨志。」","sentenceOrder":231},
  {"id":"s_work_han_thu_69_232","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　師古曰：「書於札而留之，故云遺札。」","sentenceOrder":232},
  {"id":"s_work_han_thu_69_233","chapterId":"ch_work_han_thu_69","textTraditional":"伊上古之初肇，自顥穹生民。〔一〕歷選列辟，以迄乎秦。〔二〕率邇者踵武，聽逖者風聲。〔三〕紛輪威蕤，堙滅而不稱者，不可勝數也。〔四〕繼昭夏，崇號諡，略可道者七十有二君。〔五〕罔若淑而不昌，疇逆失而能存？〔六〕","sentenceOrder":233},
  {"id":"s_work_han_thu_69_234","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「肇，始也。顥、穹，皆謂天也。顥言氣顥汗也，穹言形穹隆也。謂自初始有天地以來也。顥音胡老反。」","sentenceOrder":234},
  {"id":"s_work_han_thu_69_235","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「選，數也。辟，君也。迄，至也。辟音璧。」","sentenceOrder":235},
  {"id":"s_work_han_thu_69_236","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　文穎曰：「率，循也。邇，近也。踵，蹈也。武，跡也。逖，遠也。言循履近者之遺跡，聽遠者之風聲。風謂著於雅頌者也。」師古曰：「風聲，總謂遺風嘉聲耳，無繫於雅頌也。」","sentenceOrder":236},
  {"id":"s_work_han_thu_69_237","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　張揖曰：「紛輪威蕤，亂貌。」","sentenceOrder":237},
  {"id":"s_work_han_thu_69_238","chapterId":"ch_work_han_thu_69","textTraditional":"〔五〕　文穎曰：「昭，明也。夏，大也。德明大，相繼封禪於泰山者，七十有二人也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_69_239","chapterId":"ch_work_han_thu_69","textTraditional":"〔六〕　應劭曰：「罔，無也。若，順也。淑，善也。疇，誰也。」師古曰：「言行順善者無不昌大，為逆失者誰能久存也。」","sentenceOrder":239},
  {"id":"s_work_han_thu_69_240","chapterId":"ch_work_han_thu_69","textTraditional":"軒轅之前，遐哉邈乎，其詳不可得聞已。〔一〕五三六經載籍之傳，維見可觀也。〔二〕書曰：「元首明哉！股肱良哉！」〔三〕因斯以談，君莫盛於堯，臣莫賢於后稷。后稷創業於唐，公劉發跡於西戎，文王改制，爰周郅隆，大行越成，〔四〕而后陵夷衰微，千載亡聲，豈不善始善終哉！〔五〕然無異端，慎所由於前，謹遺教於後耳。〔六〕故軌跡夷易，易遵也；〔七〕湛恩厖洪，易豐也；〔八〕憲度著明，易則也；垂統理順，易繼也。〔九〕是以業隆於繈保而崇冠乎二后。〔一０〕揆厥所元，終都攸卒，〔一一〕未有殊尤絕跡可考於今者也。〔一二〕然猶躡梁甫，登大山，建顯號，施尊名。大漢之德，逢涌原泉，沕潏曼羨，〔一三〕旁魄四塞，雲布霧散，〔一四〕上暢九垓，下泝八埏。〔一五〕懷生之類，沾濡浸潤，協氣橫流，武節焱逝，〔一六〕爾陿游原，迥闊泳末，〔一七〕首惡鬱沒，闇昧昭晰，〔一八〕昆蟲闓懌，回首面內。〔一九〕然后囿騶虞之珍群，徼麋鹿之怪獸，〔二０〕導一莖六穗於庖，〔二一〕犧雙觡共抵之獸，〔二二〕獲周餘放龜于岐，〔二三〕招翠黃乘龍於沼。〔二四〕鬼神接靈圉，賓於閒館。〔二五〕奇物譎詭，俶儻窮變。〔二六〕欽哉，符瑞臻茲，猶以為薄，不敢道封禪。蓋周躍魚隕杭，休之以燎。〔二七〕微夫斯之為符也，以登介丘，不亦恧乎！〔二八〕進攘之道，何其爽與？〔二九〕","sentenceOrder":240},
  {"id":"s_work_han_thu_69_241","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「遐、邈，皆遠也。已，語終之辭。」","sentenceOrder":241},
  {"id":"s_work_han_thu_69_242","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「五，五帝也。三，三（皇）〔王〕也。」","sentenceOrder":242},
  {"id":"s_work_han_thu_69_243","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　師古曰：「此虞書益稷之辭也。元首，君也。股肱，大臣也。」","sentenceOrder":243},
  {"id":"s_work_han_thu_69_244","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　文穎曰：「郅，至也。行，道也。文王始開王業，改正朔服色，太平之道於是成也。」應劭曰：「大行，道德大行也。」師古曰：「郅音質。」","sentenceOrder":244},
  {"id":"s_work_han_thu_69_245","chapterId":"ch_work_han_thu_69","textTraditional":"〔五〕　鄭氏曰：「無聲，無有惡聲也。」師古曰：「雖後嗣衰微，政教頹替，猶經千載而無惡聲。」","sentenceOrder":245},
  {"id":"s_work_han_thu_69_246","chapterId":"ch_work_han_thu_69","textTraditional":"〔六〕　師古曰：「言既創業定制，又垂裕後昆也。」","sentenceOrder":246},
  {"id":"s_work_han_thu_69_247","chapterId":"ch_work_han_thu_69","textTraditional":"〔七〕　師古曰：「夷、易，皆平也。易音弋豉反。」","sentenceOrder":247},
  {"id":"s_work_han_thu_69_248","chapterId":"ch_work_han_thu_69","textTraditional":"〔八〕　師古曰：「湛讀曰沈。沈，深也。厖、洪，皆大也。厖音尨。」","sentenceOrder":248},
  {"id":"s_work_han_thu_69_249","chapterId":"ch_work_han_thu_69","textTraditional":"〔九〕　張揖曰：「垂，縣也。統，緒也。理，道也。文王重易六爻，窮理盡性，縣於後世，其道和順，易續而明，孔子得錯其象而彖其辭也。」師古曰：「統業直言所垂之業，其理至順，故令後嗣易繼之耳，非謂演易也。」","sentenceOrder":249},
  {"id":"s_work_han_thu_69_250","chapterId":"ch_work_han_thu_69","textTraditional":"〔一０〕孟康曰：「繈保謂成王也。二后謂文武也。周公負成王以致太平，功德冠於文武者，遵成法易故也。」","sentenceOrder":250},
  {"id":"s_work_han_thu_69_251","chapterId":"ch_work_han_thu_69","textTraditional":"〔一一〕師古曰：「元，始也。都，於也。攸，所也。卒亦終也。言度其所始，究其所終也。」","sentenceOrder":251},
  {"id":"s_work_han_thu_69_252","chapterId":"ch_work_han_thu_69","textTraditional":"〔一二〕師古曰：「尤，異也。考，校也。言不得與漢校其德也。」","sentenceOrder":252},
  {"id":"s_work_han_thu_69_253","chapterId":"ch_work_han_thu_69","textTraditional":"〔一三〕師古曰：「逢讀曰烽。言如烽火之升，原泉之流也。沕潏曼羨，盛大之意也。沕音勿。潏音聿。羨音（戈）〔弋〕扇反。」","sentenceOrder":253},
  {"id":"s_work_han_thu_69_254","chapterId":"ch_work_han_thu_69","textTraditional":"〔一四〕師古曰：「旁魄，廣被也。魄音步各反。」","sentenceOrder":254},
  {"id":"s_work_han_thu_69_255","chapterId":"ch_work_han_thu_69","textTraditional":"〔一五〕服虔曰：「暢，達也。垓，重也。天有九重。」如淳曰：「淮南云若士謂盧敖：『吾與汗漫期乎九垓之上。』」孟康曰：「泝，流也。埏，地之八際也。言德上達於九重之天，下流於地之八際。」師古曰：「埏，本音延，合韻音弋戰反。淮南子作八夤也。」","sentenceOrder":255},
  {"id":"s_work_han_thu_69_256","chapterId":"ch_work_han_thu_69","textTraditional":"〔一六〕師古曰：「言和氣橫被四表，威武如焱之盛。」","sentenceOrder":256},
  {"id":"s_work_han_thu_69_257","chapterId":"ch_work_han_thu_69","textTraditional":"〔一七〕孟康曰：「爾，近也。原，本也。迥，遠也。闊，廣也。泳，浮也。恩德比之於水，近者游其原，遠者浮其末也。」","sentenceOrder":257},
  {"id":"s_work_han_thu_69_258","chapterId":"ch_work_han_thu_69","textTraditional":"〔一八〕師古曰：「始為惡者皆即湮滅，素暗昧者皆得光明也。晰音之舌反。」","sentenceOrder":258},
  {"id":"s_work_han_thu_69_259","chapterId":"ch_work_han_thu_69","textTraditional":"〔一九〕文穎曰：「闓、懌，皆樂也。」師古曰：「闓讀曰凱。言四方幽遐，皆懷和樂，回首革面，而內嚮也。」","sentenceOrder":259},
  {"id":"s_work_han_thu_69_260","chapterId":"ch_work_han_thu_69","textTraditional":"〔二０〕師古曰：「言騶虞自擾而充苑囿，怪獸自來若入徼塞。言符瑞之盛也。徼音工釣反。」","sentenceOrder":260},
  {"id":"s_work_han_thu_69_261","chapterId":"ch_work_han_thu_69","textTraditional":"〔二一〕鄭氏曰：「導，擇也。一莖六穗，謂嘉禾之米，於庖廚以供祭祀也。」","sentenceOrder":261},
  {"id":"s_work_han_thu_69_262","chapterId":"ch_work_han_thu_69","textTraditional":"〔二二〕服虔曰：「犧，牲也。觡，角也。抵，本也。武帝獲白麟，兩角共一本，因以為牲也。」","sentenceOrder":262},
  {"id":"s_work_han_thu_69_263","chapterId":"ch_work_han_thu_69","textTraditional":"〔二三〕文穎曰：「周放畜餘龜於池沼之中，至漢得之於岐山之旁。龜能吐故納新，千歲不死也。」","sentenceOrder":263},
  {"id":"s_work_han_thu_69_264","chapterId":"ch_work_han_thu_69","textTraditional":"〔二四〕張揖曰：「乘龍，四龍也。」孟康曰：「翠黃，乘黃也，龍翼馬身，黃帝乘之而仙。言見乘黃而招呼之。禮樂志曰『訾黃其何不來下』。余吾渥（津）〔洼〕水中出神馬，故曰乘龍於沼也。」師古曰：「此說非也。言招致翠黃及乘龍於池沼耳。乘音食證反。春秋傳曰『帝賜之乘龍』。」","sentenceOrder":264},
  {"id":"s_work_han_thu_69_265","chapterId":"ch_work_han_thu_69","textTraditional":"〔二五〕文穎曰：「是時上求神仙之人，得上郡之巫長陵女子，能與鬼神交接，治病輒愈，置於上林苑中，號曰神君。有似於古之靈圉，禮待之於閒館舍中也。」師古曰：「閒讀曰閑。」","sentenceOrder":265},
  {"id":"s_work_han_thu_69_266","chapterId":"ch_work_han_thu_69","textTraditional":"〔二六〕師古曰：「俶音吐歷反。」","sentenceOrder":266},
  {"id":"s_work_han_thu_69_267","chapterId":"ch_work_han_thu_69","textTraditional":"〔二七〕應劭曰：「杭，舟也。休，美也。」師古曰：「燎，祭天也。謂武王伐紂，白魚入于王舟，俯取以燎。」","sentenceOrder":267},
  {"id":"s_work_han_thu_69_268","chapterId":"ch_work_han_thu_69","textTraditional":"〔二八〕服虔曰：「介，大也。丘，山也。言周以白魚為瑞，登太山封禪，不亦慚乎？」","sentenceOrder":268},
  {"id":"s_work_han_thu_69_269","chapterId":"ch_work_han_thu_69","textTraditional":"〔二九〕張揖曰：「進，周也。攘，漢也。爽，差也。言周未可封禪而封，為進；漢可封禪而不為，為攘也。」師古曰：「攘，古讓字也。」","sentenceOrder":269},
  {"id":"s_work_han_thu_69_270","chapterId":"ch_work_han_thu_69","textTraditional":"於是大司馬進曰：〔一〕「陛下仁育群生，義征不譓，〔二〕諸夏樂貢，百蠻執贄，〔三〕德牟往初，功無與二，〔四〕休烈液洽，符瑞眾變，期應紹至，不特創見。〔五〕意者太山、梁父設壇場望幸，蓋號以況榮，〔六〕上帝垂恩儲祉，將以慶成，〔七〕陛下嗛讓而弗發也。〔八〕挈三神之歡，缺王道之儀，〔九〕群臣恧焉〔一０〕。或謂且天為質闇，示珍符固不可辭；〔一一〕若然辭之，是泰山靡記而梁父罔幾也。〔一二〕亦各並時而榮，咸濟厥世而屈，說者尚何稱於後，而云七十二君哉？〔一三〕夫修德以錫符，奉符以行事，不為進越也。〔一四〕故聖王弗替，而修禮（以）〔地〕祇，謁款天神，〔一五〕勒功中岳，以章至尊，〔一六〕舒盛德，發號榮，受厚福，以浸黎民。皇皇哉斯事，天下之壯觀，王者之卒業，不可貶也。〔一七〕願陛下全之。〔一八〕而后因雜縉紳先生之略術，使獲曜日月之末光絕炎，以展采錯事。〔一九〕猶兼正列其義，祓飾厥文，作春秋一藝。〔二０〕將襲舊六為七，攄之無窮，〔二一〕俾萬世得激清流，揚微波，蜚英聲，騰茂實。〔二二〕前聖之所以永保鴻名而常為稱首者用此。〔二三〕宜命掌故悉奏其儀而覽焉。」〔二四〕","sentenceOrder":270},
  {"id":"s_work_han_thu_69_271","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　文穎曰：「大司馬，上公，故先進議也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_69_272","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　文穎曰：「譓，順也。」","sentenceOrder":272},
  {"id":"s_work_han_thu_69_273","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　師古曰：「夏，大也。諸夏謂中國之人，比蠻夷為大也。」","sentenceOrder":273},
  {"id":"s_work_han_thu_69_274","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　師古曰：「牟，等也。」","sentenceOrder":274},
  {"id":"s_work_han_thu_69_275","chapterId":"ch_work_han_thu_69","textTraditional":"〔五〕　師古曰：「言符瑞眾多，應期相續而至，不獨初創而見也。」","sentenceOrder":275},
  {"id":"s_work_han_thu_69_276","chapterId":"ch_work_han_thu_69","textTraditional":"〔六〕　孟康曰：「意者，言太山、梁父設壇場，望聖帝往封禪記號以表榮名也。」師古曰：「幸，臨幸也。蓋，發語辭也。」","sentenceOrder":276},
  {"id":"s_work_han_thu_69_277","chapterId":"ch_work_han_thu_69","textTraditional":"〔七〕　師古曰：「上帝，天也。言垂恩於下，豫積祉福，用慶告成之禮。」","sentenceOrder":277},
  {"id":"s_work_han_thu_69_278","chapterId":"ch_work_han_thu_69","textTraditional":"〔八〕　張揖曰：「不肯發意往也。」師古曰：「嗛，古謙字。」","sentenceOrder":278},
  {"id":"s_work_han_thu_69_279","chapterId":"ch_work_han_thu_69","textTraditional":"〔九〕　應劭曰：「挈，絕也。缺，闕也。」如淳曰：「三神，地祇、天神、山岳也。」師古曰：「挈音口計反。」","sentenceOrder":279},
  {"id":"s_work_han_thu_69_280","chapterId":"ch_work_han_thu_69","textTraditional":"〔一０〕師古曰：「恧，愧也，音女六反。」","sentenceOrder":280},
  {"id":"s_work_han_thu_69_281","chapterId":"ch_work_han_thu_69","textTraditional":"〔一一〕師古曰：「言天道質昧，以符瑞見意，不可辭讓也。」","sentenceOrder":281},
  {"id":"s_work_han_thu_69_282","chapterId":"ch_work_han_thu_69","textTraditional":"〔一二〕張揖曰：「泰山之上無所表記，梁父壇場無所庶幾也。」","sentenceOrder":282},
  {"id":"s_work_han_thu_69_283","chapterId":"ch_work_han_thu_69","textTraditional":"〔一三〕應劭曰：「屈，絕也。言古帝王若但各一時之榮，畢世而絕者，則說者無從顯稱於後也。」師古曰：「屈音其勿反。」","sentenceOrder":283},
  {"id":"s_work_han_thu_69_284","chapterId":"ch_work_han_thu_69","textTraditional":"〔一四〕文穎曰：「越，踰也。不為苟進踰禮也。」","sentenceOrder":284},
  {"id":"s_work_han_thu_69_285","chapterId":"ch_work_han_thu_69","textTraditional":"〔一五〕文穎曰：「謁，告也。款，誠也。」師古曰：「替，廢也。不廢封禪之事也。」","sentenceOrder":285},
  {"id":"s_work_han_thu_69_286","chapterId":"ch_work_han_thu_69","textTraditional":"〔一六〕張揖曰：「蓋先禮中岳而幸太山也。」師古曰：「章，明也。」","sentenceOrder":286},
  {"id":"s_work_han_thu_69_287","chapterId":"ch_work_han_thu_69","textTraditional":"〔一七〕師古曰：「皇皇，盛貌也。卒，終也，字或作本，或作丕，丕，大也。」","sentenceOrder":287},
  {"id":"s_work_han_thu_69_288","chapterId":"ch_work_han_thu_69","textTraditional":"〔一八〕張揖曰：「願以封禪全其終也。」","sentenceOrder":288},
  {"id":"s_work_han_thu_69_289","chapterId":"ch_work_han_thu_69","textTraditional":"〔一九〕文穎曰：「采，官也。使諸儒記功著業，得觀日月末光殊絕之明，以展其官職，設錯其事業也。」李奇曰：「炎音火之光炎。」師古曰：「炎音弋贍反。錯音千故反。」","sentenceOrder":289},
  {"id":"s_work_han_thu_69_290","chapterId":"ch_work_han_thu_69","textTraditional":"〔二０〕孟康曰：「猶作春秋者，正天時，列人事也。言諸儒既得展事業，因兼正天時，列人事，敘述大義為一經也。」師曰：「祓，除也。祓飾者，言除去舊事，更飾新文也。祓音敷勿反。」","sentenceOrder":290},
  {"id":"s_work_han_thu_69_291","chapterId":"ch_work_han_thu_69","textTraditional":"〔二一〕文穎曰：「六經加一為七也。」師古曰：「攄，布也，音丑居反。」","sentenceOrder":291},
  {"id":"s_work_han_thu_69_292","chapterId":"ch_work_han_thu_69","textTraditional":"〔二二〕師古曰：「蜚，古飛字。」","sentenceOrder":292},
  {"id":"s_work_han_thu_69_293","chapterId":"ch_work_han_thu_69","textTraditional":"〔二三〕師古曰：「稱音尺孕反。」","sentenceOrder":293},
  {"id":"s_work_han_thu_69_294","chapterId":"ch_work_han_thu_69","textTraditional":"〔二四〕師古曰：「掌故，太常官屬，主故事者。」","sentenceOrder":294},
  {"id":"s_work_han_thu_69_295","chapterId":"ch_work_han_thu_69","textTraditional":"於是天子沛然改容，曰：「俞乎，朕其試哉！」〔一〕乃遷思回慮，總公卿之議，詢封禪之事，詩大澤之博，廣符瑞之富。〔二〕遂作頌曰：","sentenceOrder":295},
  {"id":"s_work_han_thu_69_296","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「沛然，感動之意也。俞者，然也，然其所請也。沛音普大反。俞音踰。」","sentenceOrder":296},
  {"id":"s_work_han_thu_69_297","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　孟康曰：「詩所以詠功德，謂下四章之頌也。大澤之博，謂『自我天覆，雲之油油』也。廣符瑞之富，謂『斑斑之獸』以下三章，言符應廣大富饒也。」","sentenceOrder":297},
  {"id":"s_work_han_thu_69_298","chapterId":"ch_work_han_thu_69","textTraditional":"自我天覆，雲之油油。〔一〕甘露時雨，厥壤可游〔二〕。滋液滲漉，何生不育！〔三〕嘉穀六穗，我穡曷蓄？〔四〕","sentenceOrder":298},
  {"id":"s_work_han_thu_69_299","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　蘇林曰：「油音油麻之油。」李奇曰：「油油，雲行貌。孟子曰『油然作雲，沛然下雨』。」","sentenceOrder":299},
  {"id":"s_work_han_thu_69_300","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「言雨霧滂沛，其澤可以游泳也。」","sentenceOrder":300},
  {"id":"s_work_han_thu_69_301","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　師古曰：「滲漉，謂潤澤下究，故無生而不育也。滲音山禁反。漉音鹿。」","sentenceOrder":301},
  {"id":"s_work_han_thu_69_302","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　李奇曰：「我之稼穡，何等不蓄積？」","sentenceOrder":302},
  {"id":"s_work_han_thu_69_303","chapterId":"ch_work_han_thu_69","textTraditional":"匪唯雨之，又潤澤之；匪唯偏我，氾布護之；〔一〕萬物熙熙，懷而慕之。名山顯位，望君之來。君兮君兮，侯不邁哉〔二〕！","sentenceOrder":303},
  {"id":"s_work_han_thu_69_304","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「氾，普也。布護，言遍布也。氾音敷劍反。」","sentenceOrder":304},
  {"id":"s_work_han_thu_69_305","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「侯，何也。邁，行也。言君何不行封禪。」","sentenceOrder":305},
  {"id":"s_work_han_thu_69_306","chapterId":"ch_work_han_thu_69","textTraditional":"般般之獸，樂我君圃；白質黑章，其儀可喜；〔一〕旼旼穆穆，君子之態。〔二〕蓋聞其聲，今視其來。〔三〕厥塗靡從，天瑞之徵。〔四〕茲爾於舜，虞氏以興。〔五〕","sentenceOrder":306},
  {"id":"s_work_han_thu_69_307","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「謂騶虞也。般字與斑同耳，從丹青之丹。喜音許記反。」","sentenceOrder":307},
  {"id":"s_work_han_thu_69_308","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　孟康曰：「旼旼，和也。穆穆，敬也。言容態和且敬，有似君子也。」張揖曰：「旼音旻。」","sentenceOrder":308},
  {"id":"s_work_han_thu_69_309","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　師古曰：「言往昔但聞其聲，今親見其來也。來合韻音郎代反。」","sentenceOrder":309},
  {"id":"s_work_han_thu_69_310","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　文穎曰：「其來之道何從乎？此乃天瑞之應也。」","sentenceOrder":310},
  {"id":"s_work_han_thu_69_311","chapterId":"ch_work_han_thu_69","textTraditional":"〔五〕　文穎曰：「百獸舞，則騶虞在其中也。」","sentenceOrder":311},
  {"id":"s_work_han_thu_69_312","chapterId":"ch_work_han_thu_69","textTraditional":"濯濯之麟，游彼靈畤。孟冬十月，君徂郊祀。〔一〕馳我君輿，帝用享祉。〔二〕三代之前，蓋未嘗有。","sentenceOrder":312},
  {"id":"s_work_han_thu_69_313","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　文穎曰：「濯濯，肥也。武帝冬幸雍，祠五畤，獲白麟也。」師古曰：「濯音直角反。大雅靈臺之詩云『麀鹿濯濯』。」","sentenceOrder":313},
  {"id":"s_work_han_thu_69_314","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　文穎曰：「馳我君車之前也。」師古曰：「帝，天帝也。以此祭天，天既享之，答以祉福也。」","sentenceOrder":314},
  {"id":"s_work_han_thu_69_315","chapterId":"ch_work_han_thu_69","textTraditional":"宛宛黃龍，興德而升；〔一〕采色玄耀，炳炳煇煌〔二〕。正陽顯見，覺寤黎烝。〔三〕於傳載之，云受命所乘。〔四〕","sentenceOrder":315},
  {"id":"s_work_han_thu_69_316","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　文穎曰：「起至德而見也。」","sentenceOrder":316},
  {"id":"s_work_han_thu_69_317","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「玄讀曰炫。煇煌，光貌。煇音下本反。」","sentenceOrder":317},
  {"id":"s_work_han_thu_69_318","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　文穎曰：「陽，明也。」師古曰：「黎烝，眾庶也。」","sentenceOrder":318},
  {"id":"s_work_han_thu_69_319","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　師古曰：「謂易云『時乘六龍以御天也』。」","sentenceOrder":319},
  {"id":"s_work_han_thu_69_320","chapterId":"ch_work_han_thu_69","textTraditional":"厥之有章，不必諄諄。〔一〕依類託寓，諭以封巒〔二〕。","sentenceOrder":320},
  {"id":"s_work_han_thu_69_321","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　文穎曰：「天之所命，表以符瑞，章明其德，不必諄諄然有語言也。」師古曰：「諄諄，告喻之熟也，音之純反。」","sentenceOrder":321},
  {"id":"s_work_han_thu_69_322","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　文穎曰：「寓，寄也。巒，山也。言依事類託寄，以喻封禪。」","sentenceOrder":322},
  {"id":"s_work_han_thu_69_323","chapterId":"ch_work_han_thu_69","textTraditional":"披藝觀之，天人之際已交，上下相發允答。聖王之事，兢兢翼翼。〔一〕故曰於興必慮衰，安必思危。是以湯武至尊嚴，不失肅祗，〔二〕舜在假典，顧省厥遺：〔三〕此之謂也。","sentenceOrder":323},
  {"id":"s_work_han_thu_69_324","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　師古曰：「兢兢，戒也。翼翼，敬也。」","sentenceOrder":324},
  {"id":"s_work_han_thu_69_325","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　師古曰：「言居天子之位，猶不忘恭敬也。」","sentenceOrder":325},
  {"id":"s_work_han_thu_69_326","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　師古曰：「在，察也。假，（天）〔大〕也。典，則也。言舜察琁璣玉衡，恐己政化有所遺失，不合天心。今漢亦當順天意而封禪也。」","sentenceOrder":326},
  {"id":"s_work_han_thu_69_327","chapterId":"ch_work_han_thu_69","textTraditional":"相如既卒五歲，上始祭后土。八年而遂禮中岳，封于太山，至梁甫，禪肅然。","sentenceOrder":327},
  {"id":"s_work_han_thu_69_328","chapterId":"ch_work_han_thu_69","textTraditional":"相如它所著，苦遺平陵侯書、與五公子相難、屮木書篇，不采，采其尤著公卿者云。","sentenceOrder":328},
  {"id":"s_work_han_thu_69_329","chapterId":"ch_work_han_thu_69","textTraditional":"贊曰：司馬遷稱「春秋推見至隱，〔一〕易本隱以之顯，〔二〕大雅言王公大人，而德逮黎庶，〔三〕小雅譏小己之得失，其流及上。〔四〕所言雖殊，其合德一也。相如雖多虛辭濫說，然要其歸引之於節儉，此亦詩之風諫何異？」〔五〕揚雄以為靡麗之賦，勸百而風一，〔六〕猶騁鄭衛之聲，曲終而奏雅，不已戲乎！〔七〕","sentenceOrder":329},
  {"id":"s_work_han_thu_69_330","chapterId":"ch_work_han_thu_69","textTraditional":"〔一〕　李奇曰：「隱猶微也。言其義顯而文隱，若隱公見弒死，而經不書，隱諱之也。」","sentenceOrder":330},
  {"id":"s_work_han_thu_69_331","chapterId":"ch_work_han_thu_69","textTraditional":"〔二〕　張揖曰：「作八卦以通神明之德，是本隱也。有天道焉，有地道焉，有人道焉，以類萬物之情，是之顯也。」師古曰：「之，往也。」","sentenceOrder":331},
  {"id":"s_work_han_thu_69_332","chapterId":"ch_work_han_thu_69","textTraditional":"〔三〕　張揖曰：「謂文王、公劉在位，大人之德下及眾民者也。」","sentenceOrder":332},
  {"id":"s_work_han_thu_69_333","chapterId":"ch_work_han_thu_69","textTraditional":"〔四〕　張揖曰：「己，詩人自謂也。己小有得失，不得其所，作詩流言，以諷其上也。」師古曰：「小己者，謂卑少之人，以對上言大人耳。」","sentenceOrder":333},
  {"id":"s_work_han_thu_69_334","chapterId":"ch_work_han_thu_69","textTraditional":"〔五〕　師古曰：「風讀曰諷，次下亦同。」","sentenceOrder":334},
  {"id":"s_work_han_thu_69_335","chapterId":"ch_work_han_thu_69","textTraditional":"〔六〕　師古曰：「奢靡之辭多，而節儉之言少也。」","sentenceOrder":335},
  {"id":"s_work_han_thu_69_336","chapterId":"ch_work_han_thu_69","textTraditional":"〔七〕　張揖曰：「不亦輕戲乎哉！」","sentenceOrder":336},
  {"id":"s_work_han_thu_69_337","chapterId":"ch_work_han_thu_69","textTraditional":"校勘記","sentenceOrder":337},
  {"id":"s_work_han_thu_69_338","chapterId":"ch_work_han_thu_69","textTraditional":"二五七九頁　一行　功（業）〔烈〕著而不滅。　景祐、殿本都作「烈」。","sentenceOrder":338},
  {"id":"s_work_han_thu_69_339","chapterId":"ch_work_han_thu_69","textTraditional":"二五八一頁　八行　除邊關。〔邊關〕益斥，　景祐、殿本都重「邊關」字。","sentenceOrder":339},
  {"id":"s_work_han_thu_69_340","chapterId":"ch_work_han_thu_69","textTraditional":"二五八二頁一二行　且因宣其使（詣）〔指〕，　錢大昭說「詣」當作「指」。按景祐、殿本都作「指」。","sentenceOrder":340},
  {"id":"s_work_han_thu_69_341","chapterId":"ch_work_han_thu_69","textTraditional":"二五八四頁　四行　已，（詔）〔語〕終之辭也。　景祐、殿、局本都作「語」，此誤。","sentenceOrder":341},
  {"id":"s_work_han_thu_69_342","chapterId":"ch_work_han_thu_69","textTraditional":"二五八五頁一０行　（胈音步曷反）　殿本此五字在注末。　王先謙說在注末是，此誤。按景祐本亦誤。","sentenceOrder":342},
  {"id":"s_work_han_thu_69_343","chapterId":"ch_work_han_thu_69","textTraditional":"二五八七頁　三行　殺讀曰（試）〔弒〕。　殿本作「弒」。　王先謙說作「弒」是。按景祐本亦誤。","sentenceOrder":343},
  {"id":"s_work_han_thu_69_344","chapterId":"ch_work_han_thu_69","textTraditional":"二五八七頁　四行　絫，（音）力追（切）〔反〕。　景祐、殿本無「音」字，「切」作「反」。","sentenceOrder":344},
  {"id":"s_work_han_thu_69_345","chapterId":"ch_work_han_thu_69","textTraditional":"二五八八頁　三行　（沈）〔拯〕，升也。　景祐、殿、局本都作「拯」，此誤。","sentenceOrder":345},
  {"id":"s_work_han_thu_69_346","chapterId":"ch_work_han_thu_69","textTraditional":"二五八九頁　七行　故其（事）〔仕〕宦，未嘗肯與公卿國家之事。　劉奉世說「事」當作「仕」。王先謙說，「仕」「事」音近，又涉下「事」字而訛。　史記作「其進仕宦」。","sentenceOrder":346},
  {"id":"s_work_han_thu_69_347","chapterId":"ch_work_han_thu_69","textTraditional":"二五九０頁一一行　其為害也不〔亦〕難矣！　景祐本有「亦」字。　王先謙說史記、文選並有「亦」字。","sentenceOrder":347},
  {"id":"s_work_han_thu_69_348","chapterId":"ch_work_han_thu_69","textTraditional":"二五九四頁　二行　韜謂（裏）〔裹〕冒旌旗之竿也。　景祐、殿本都作「裹」。　王先謙說作「裹」是。","sentenceOrder":348},
  {"id":"s_work_han_thu_69_349","chapterId":"ch_work_han_thu_69","textTraditional":"二五九六頁　七行　騷擾衝蓯其（相）紛挐兮，　景祐、殿本都無「相」字。","sentenceOrder":349},
  {"id":"s_work_han_thu_69_350","chapterId":"ch_work_han_thu_69","textTraditional":"二五九七頁一一行　亦非五（河）〔湖〕也。　景祐、殿、局本都作「湖」。王先謙說作「湖」是。","sentenceOrder":350},
  {"id":"s_work_han_thu_69_351","chapterId":"ch_work_han_thu_69","textTraditional":"二五九八頁　九行　漢代謂之（革）〔華〕勝。　景祐、殿本都作「華」。王先謙說作「華」是。","sentenceOrder":351},
  {"id":"s_work_han_thu_69_352","chapterId":"ch_work_han_thu_69","textTraditional":"二五九九頁　一行　春（朗）〔食〕朝霞，　景祐、殿、局本都作「食」，此誤。","sentenceOrder":352},
  {"id":"s_work_han_thu_69_353","chapterId":"ch_work_han_thu_69","textTraditional":"二六０二頁　六行　三，三（皇）〔王〕也。　王先謙說「皇」當作「王」。　按史記索隱作「王」。","sentenceOrder":353},
  {"id":"s_work_han_thu_69_354","chapterId":"ch_work_han_thu_69","textTraditional":"二六０三頁　三行　羨音（戈）〔弋〕扇反。　景祐、殿本都作「弋」，此誤。","sentenceOrder":354},
  {"id":"s_work_han_thu_69_355","chapterId":"ch_work_han_thu_69","textTraditional":"二六０四頁　一行　余吾渥（津）〔洼〕水中出神馬，　景祐、殿本都作「洼」，此誤。","sentenceOrder":355},
  {"id":"s_work_han_thu_69_356","chapterId":"ch_work_han_thu_69","textTraditional":"二六０四頁一六行　而修禮（以）〔地〕祇，　景祐、殿本都作「地」。　史記、文選同，此誤。","sentenceOrder":356},
  {"id":"s_work_han_thu_69_357","chapterId":"ch_work_han_thu_69","textTraditional":"二六０九頁　七行　假，（天）〔大〕也。　景祐、殿本都作「大」，此誤。","sentenceOrder":357},
  {"id":"s_work_han_thu_70_1","chapterId":"ch_work_han_thu_70","textTraditional":"公孫弘，菑川薛人也。少時為獄吏，有罪，免。家貧，牧豕海上。年四十餘，乃學春秋雜說。","sentenceOrder":1},
  {"id":"s_work_han_thu_70_2","chapterId":"ch_work_han_thu_70","textTraditional":"武帝初即位，招賢良文學士，是時弘年六十，以賢良徵為博士。使匈奴，還報，不合意，〔一〕上怒，以為不能，弘乃移病免歸〔二〕。","sentenceOrder":2},
  {"id":"s_work_han_thu_70_3","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「奏事不合天子之意。」","sentenceOrder":3},
  {"id":"s_work_han_thu_70_4","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「移病，謂移書言病也。一曰，以病移居。」","sentenceOrder":4},
  {"id":"s_work_han_thu_70_5","chapterId":"ch_work_han_thu_70","textTraditional":"元光五年，復徵賢良文學，菑川國復推上弘。弘謝曰：「前已嘗西，用不能罷，願更選。」國人固推弘，弘至太常。上策詔諸儒：","sentenceOrder":5},
  {"id":"s_work_han_thu_70_6","chapterId":"ch_work_han_thu_70","textTraditional":"制曰：蓋聞上古至治，畫衣冠，異章服，而民不犯；陰陽和，五穀登，六畜蕃，〔一〕甘露降，風雨時，嘉禾興，朱屮生，〔二〕山不童，澤不涸；〔三〕麟鳳在郊藪，龜龍游於沼，〔四〕河洛出圖書；父不喪子，兄不哭弟；北發渠搜，南撫交阯，〔五〕舟車所至，人跡所及，跂行喙息，咸得其宜。〔六〕朕甚嘉之，今何道而臻乎此？〔七〕子大夫修先聖之術，明君臣之義，講論洽聞，有聲乎當世，〔敢〕問子大夫：天人之道，何所本始？吉凶之效，安所期焉〔八〕？禹湯水旱，厥咎何由？仁義禮知四者之宜，當安設施？屬統垂業，物鬼變化，〔九〕天命之符，廢興何如？天文地理人事之紀，子大夫習焉。其悉意正議，詳具其對，著之于篇，〔一０〕朕將親覽焉，靡有所隱。","sentenceOrder":6},
  {"id":"s_work_han_thu_70_7","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「登，成也。蕃，多也，音扶元反。」〔二〕　師古曰：「屮，古草字。」〔三〕　師古曰：「童，無草木也。涸，水竭也，音胡各反。」〔四〕　師古曰：「邑外謂之郊。澤無水曰藪。沼，池也。」〔五〕　師古曰：「言威德之盛，北則徵發于渠搜，南則綏撫於交阯也。渠搜，遠夷之國也。」〔六〕　師古曰：「跂行，有足而行者也。喙息，謂有口能息者也。跂音岐。喙音許穢反。」〔七〕　師古曰：「臻，至也。」〔八〕　師古曰：「安，焉也。」〔九〕　師古曰：「屬，繫也，音之欲反。其下亦同。」〔一０〕師古曰：「悉，盡也。篇，簡也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_70_8","chapterId":"ch_work_han_thu_70","textTraditional":"弘對曰：","sentenceOrder":8},
  {"id":"s_work_han_thu_70_9","chapterId":"ch_work_han_thu_70","textTraditional":"臣聞上古堯舜之時，不貴爵賞而民勸善，不重刑罰而民不犯，躬率以正而遇民信也；〔一〕末世貴爵厚賞而民不勸，深刑重罰而姦不止，其上不正，遇民不信也。夫厚（當）〔賞〕重刑未足以勸善而禁非，必信而已矣。是故因能任官，則分職治；〔二〕去無用之言，則事情得；不作無用之器，即賦斂省；不奪民時，不妨民力，則百姓富；有德者進，無德者退，則朝廷尊；有功者上，無功者下，則群臣逡；〔三〕罰當罪，則姦邪止；賞當賢，則臣下勸：凡此八者，治〔民〕之本也。故民者，業之即不爭，理得則不怨；有禮則不暴，愛之則親上，〔四〕此有天下之急者也。故法不遠義，則民服而不離；和不遠禮，則民親而不暴。〔五〕故法之所罰，義之所去也；〔六〕和之所賞，禮之所取也。禮義者，民之所服也，而賞罰順之，則民不犯禁矣。故畫衣冠，異章服，而民不犯者，此道素行也。","sentenceOrder":9},
  {"id":"s_work_han_thu_70_10","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「躬謂身親行之，遇謂處待之而已。」","sentenceOrder":10},
  {"id":"s_work_han_thu_70_11","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「分音扶問反。」","sentenceOrder":11},
  {"id":"s_work_han_thu_70_12","chapterId":"ch_work_han_thu_70","textTraditional":"〔三〕（師古）〔李奇〕曰：「言有次第也。」師古曰：「逡音七旬反，其字從辵。」","sentenceOrder":12},
  {"id":"s_work_han_thu_70_13","chapterId":"ch_work_han_thu_70","textTraditional":"〔四〕　師古曰：「各得其業則無爭心，各申其理則無所怨，使之由理則無暴慢，子而愛之則知親上也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_70_14","chapterId":"ch_work_han_thu_70","textTraditional":"〔五〕　師古曰：「遠，違也，音于萬反。」","sentenceOrder":14},
  {"id":"s_work_han_thu_70_15","chapterId":"ch_work_han_thu_70","textTraditional":"〔六〕　師古曰：「去，除也，音丘呂反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_70_16","chapterId":"ch_work_han_thu_70","textTraditional":"臣聞之，氣同則從，聲比則應。〔一〕今人主和德於上，百姓和合於下，〔二〕故心和則氣和，氣和則形和，形和則聲和，聲和則天地之和應矣。故陰陽和，風雨時，甘露降，五穀登，六畜蕃，嘉禾興，朱草生，山不童，澤不涸，此和之至也。故形和則無疾，無疾則不夭，故父不喪子，兄不哭弟。德配天地，明並日月，則麟鳳至，龜龍在郊，河出圖，洛出書，遠方之君莫不說義，〔三〕奉幣而來朝，此和之極也。","sentenceOrder":16},
  {"id":"s_work_han_thu_70_17","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「比亦和也，音頻寐反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_70_18","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「合謂與上合德也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_70_19","chapterId":"ch_work_han_thu_70","textTraditional":"〔三〕　師古曰：「說讀曰悅。」","sentenceOrder":19},
  {"id":"s_work_han_thu_70_20","chapterId":"ch_work_han_thu_70","textTraditional":"臣聞之，仁者愛也，義者宜也，禮者所履也，〔一〕智者術之原也。致利除害，兼愛無私，謂之仁；〔二〕明是非，立可否，謂之義；進退有度，尊卑有分，謂之禮；〔三〕擅殺生之柄，通〔壅〕塞之塗，〔四〕權輕重之數，論得失之道，使遠近情偽必見於上，謂之術：〔五〕凡此四者，治之本，道之用也，皆當設施，不可廢也。得其要，則天下安樂，法設而不用；〔六〕不得其術，則主蔽於上，官亂於下。此事之情，屬統垂業之本也。","sentenceOrder":20},
  {"id":"s_work_han_thu_70_21","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「履而行之。」","sentenceOrder":21},
  {"id":"s_work_han_thu_70_22","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「致謂引而至也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_70_23","chapterId":"ch_work_han_thu_70","textTraditional":"〔三〕　師古曰：「分音扶問反。」","sentenceOrder":23},
  {"id":"s_work_han_thu_70_24","chapterId":"ch_work_han_thu_70","textTraditional":"〔四〕　師古曰：「擅，專也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_70_25","chapterId":"ch_work_han_thu_70","textTraditional":"〔五〕　師古曰：「見，顯也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_70_26","chapterId":"ch_work_han_thu_70","textTraditional":"〔六〕　師古曰：「下不犯法，無所加刑也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_70_27","chapterId":"ch_work_han_thu_70","textTraditional":"臣聞堯遭鴻水，使禹治之，未聞禹之有水也。若湯之旱，則桀之餘烈也。桀紂行惡，受天之罰；禹湯積德，以王天下。因此觀之，天德無私親，順之和起，逆之害生。此天文地理人事之紀。臣弘愚戇，不足以奉大對。〔一〕","sentenceOrder":27},
  {"id":"s_work_han_thu_70_28","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「大對，大問之對也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_70_29","chapterId":"ch_work_han_thu_70","textTraditional":"時對者百餘人，太常奏弘第居下。策奏，天子擢弘對為第一。召入見，容貌甚麗，拜為博士，待詔金馬門。〔一〕","sentenceOrder":29},
  {"id":"s_work_han_thu_70_30","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　如淳曰：「武帝時，相馬者東門京作銅馬法獻之，立馬於魯（斑）〔班〕門外，更名魯（斑）〔班〕門為金馬門。」","sentenceOrder":30},
  {"id":"s_work_han_thu_70_31","chapterId":"ch_work_han_thu_70","textTraditional":"弘復上疏曰：「陛下有先聖之位而無先聖之名，有先聖之名而無先聖之吏，是以勢同而治異。先世之吏正，故其民篤；〔一〕今世之吏邪，故其民薄。政弊而不行，令倦而不聽。夫使邪吏行弊政，用倦令治薄民，民不可得而化，此治之所以異也。臣聞周公旦治天下，期年而變，三年而化，五年而定。唯陛下之所志。」〔二〕書奏，天子以冊書答曰：「問：弘稱周公之治，弘之材能自視孰與周公賢？〔三〕」弘對曰：「愚臣淺薄，安敢比材於周公！雖然，愚心曉然見治道之可以然也。夫虎豹馬牛，禽獸之不可制者也，及其教馴服習之〔四〕，至可牽持駕服，唯人之從。〔五〕臣聞揉曲木者不累日，〔六〕銷金石者不累月，夫人之於利害好惡，豈比禽獸木石之類哉？〔七〕期年而變，臣弘尚竊遲之。」上異其言。","sentenceOrder":31},
  {"id":"s_work_han_thu_70_32","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「篤，厚也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_70_33","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「言志所在也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_70_34","chapterId":"ch_work_han_thu_70","textTraditional":"〔三〕　師古曰：「與猶如也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_70_35","chapterId":"ch_work_han_thu_70","textTraditional":"〔四〕　師古曰：「馴，順也，音巡。」","sentenceOrder":35},
  {"id":"s_work_han_thu_70_36","chapterId":"ch_work_han_thu_70","textTraditional":"〔五〕　師古曰：「從人意。」","sentenceOrder":36},
  {"id":"s_work_han_thu_70_37","chapterId":"ch_work_han_thu_70","textTraditional":"〔六〕　師古曰：「揉謂矯而正之也。異，積也。揉音人九反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_70_38","chapterId":"ch_work_han_thu_70","textTraditional":"〔七〕　師古曰：「好音呼到反。惡音一故反。」","sentenceOrder":38},
  {"id":"s_work_han_thu_70_39","chapterId":"ch_work_han_thu_70","textTraditional":"時方通西南夷，巴蜀苦之，詔使弘視焉。還奏事，盛毀西南夷無所用，上不聽。每朝會議，開陳其端，使人主自擇，不肯面折庭爭。於是上察其行慎厚，辯論有餘，習文法吏事，緣飾以儒術，〔一〕上說之，〔二〕一歲中至左內史。","sentenceOrder":39},
  {"id":"s_work_han_thu_70_40","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「緣飾者，譬之於衣，加純緣者。」","sentenceOrder":40},
  {"id":"s_work_han_thu_70_41","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":41},
  {"id":"s_work_han_thu_70_42","chapterId":"ch_work_han_thu_70","textTraditional":"弘奏事，有所不可，不肯庭辯。〔一〕常與主爵都尉汲黯請間，〔二〕黯先發之，弘推其後，上常說，〔三〕所言皆聽，以此日益親貴。嘗與公卿約議，〔四〕至上前，皆背其約以順上指。汲黯庭詰弘曰：「齊人多詐而無情，始為與臣等建此議，今皆背之，不忠。」上問弘，弘謝曰：「夫知臣者以臣為忠，不知臣者以臣為不忠。」上然弘言。左右幸臣每毀弘，上益厚遇之。","sentenceOrder":42},
  {"id":"s_work_han_thu_70_43","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「不於朝廷顯辯論之。」","sentenceOrder":43},
  {"id":"s_work_han_thu_70_44","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「求空隙之暇。」","sentenceOrder":44},
  {"id":"s_work_han_thu_70_45","chapterId":"ch_work_han_thu_70","textTraditional":"〔三〕　師古曰：「說讀曰悅。」","sentenceOrder":45},
  {"id":"s_work_han_thu_70_46","chapterId":"ch_work_han_thu_70","textTraditional":"〔四〕　師古曰：「約，要也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_70_47","chapterId":"ch_work_han_thu_70","textTraditional":"弘為人談笑多聞，〔一〕常稱以為人主病不廣大，人臣病不儉節。養後母孝謹，後母卒，服喪三年。","sentenceOrder":47},
  {"id":"s_work_han_thu_70_48","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「善於談笑而又多聞也。談字或作詼，音恢，謂啁也，善啁謔也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_70_49","chapterId":"ch_work_han_thu_70","textTraditional":"為內史數年，遷御史大夫。時又東置蒼海，北築朔方之郡。弘數諫，以為罷弊中國以奉無用之地，〔一〕願罷之。於是上乃使朱買臣等難弘置朔方之便。發十策，弘不得一。〔二〕弘乃謝曰：「山東鄙人，不知其便若是，願罷西南夷、蒼海，專奉朔方。」上乃許之。","sentenceOrder":49},
  {"id":"s_work_han_thu_70_50","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「罷讀曰疲。」","sentenceOrder":50},
  {"id":"s_work_han_thu_70_51","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「言其利害十條，弘無以應之。」","sentenceOrder":51},
  {"id":"s_work_han_thu_70_52","chapterId":"ch_work_han_thu_70","textTraditional":"汲黯曰：「弘位在三公，奉祿甚多，〔一〕然為布被，此詐也。」上問弘，弘謝曰：「有之。夫九卿與臣善者無過黯，然今日庭詰弘，誠中弘之病。夫以三公為布被，誠飾詐欲以釣名。〔二〕且臣聞管仲相齊，有三歸，〔三〕侈擬於君，〔四〕桓公以霸，亦上僭於君。晏嬰相景公，食不重肉，妾不衣絲，齊國亦治，亦下比於民。〔五〕今臣弘位為御史大夫，為布被，自九卿以下至於小吏無差，誠如黯言。且無黯，陛下安聞此言？」上以為有讓，愈益賢之。","sentenceOrder":52},
  {"id":"s_work_han_thu_70_53","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「奉音扶用反。其下亦同。」","sentenceOrder":53},
  {"id":"s_work_han_thu_70_54","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「釣，取也。言若釣魚之謂也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_70_55","chapterId":"ch_work_han_thu_70","textTraditional":"〔三〕　師古曰：「三歸，取三姓女也。婦人謂嫁曰歸。」","sentenceOrder":55},
  {"id":"s_work_han_thu_70_56","chapterId":"ch_work_han_thu_70","textTraditional":"〔四〕　師古曰：「擬，疑也，言相似也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_70_57","chapterId":"ch_work_han_thu_70","textTraditional":"〔五〕　師古曰：「比，方也。一曰，比，近也，音頻寐反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_70_58","chapterId":"ch_work_han_thu_70","textTraditional":"元朔中，代薛澤為丞相。先是，漢常以列侯為丞相，唯弘無爵，上於是下詔曰：「朕嘉先聖之道，開廣門路，宣招四方之士，蓋古者任賢而序位，量能以授官，勞大者厥祿厚，德盛者獲爵尊，故武功以顯重，而文德以行褒。其以高成之平津鄉戶六百五十封丞相弘為平津侯。」其後以為故事，至丞相封，自弘始也。","sentenceOrder":58},
  {"id":"s_work_han_thu_70_59","chapterId":"ch_work_han_thu_70","textTraditional":"時上方興功業，婁舉賢良。〔一〕弘自見為舉首，起徒步，數年至宰相封侯，於是起客館，開東閣以延賢人，〔二〕與參謀議。弘身食一肉，脫粟飯，〔三〕故人賓客仰衣食，〔四〕奉祿皆以給之，家無所餘。然其性意忌，外寬內深。〔五〕諸常與弘有隙，無近遠，雖陽與善，後竟報其過。殺主父偃，徙董仲舒膠西，皆弘力也。","sentenceOrder":59},
  {"id":"s_work_han_thu_70_60","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「婁，古屢字。」","sentenceOrder":60},
  {"id":"s_work_han_thu_70_61","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「閤者，小門也，東向開之，避當庭門而引賓客，以別於掾史官屬也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_70_62","chapterId":"ch_work_han_thu_70","textTraditional":"〔三〕　師古曰：「才脫粟而已，不精（鑿）〔〈暂缺EFDD〉〕也。脫音他活反。」","sentenceOrder":62},
  {"id":"s_work_han_thu_70_63","chapterId":"ch_work_han_thu_70","textTraditional":"〔四〕　師古曰：「故人，平生故交也。仰音牛向反。」","sentenceOrder":63},
  {"id":"s_work_han_thu_70_64","chapterId":"ch_work_han_thu_70","textTraditional":"〔五〕　師古曰：「意忌，多所忌害也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_70_65","chapterId":"ch_work_han_thu_70","textTraditional":"後淮南、衡山謀反，治黨與方急，弘病甚，自以為無功而封侯，居宰相位，宜佐明主填撫國家，〔一〕使人由臣子之道。〔二〕今諸侯有畔逆之計，此大臣奉職不稱也。〔三〕恐病死無以塞責，〔四〕乃上書曰：「臣聞天下通道五，所以行之者三。君臣、父子、夫婦、長幼、朋友之交，五者天下之通道也；仁、知、勇三者，所以行之也。故曰『好問近乎知，〔五〕力行近乎仁，〔六〕知恥近乎勇：〔七〕知此三者，知所以自治；知所以自治，然後知所以治人。』〔八〕未有不能自治而能治人者也。陛下躬孝弟，監三王，建周道，兼文武，招來四方之士，任賢序位，量能授官，將以厲百姓勸賢材也。今臣愚駑，無汗馬之勞，〔九〕陛下（下）過意擢臣弘卒伍之中，〔一０〕封為列侯，致位三公。臣弘行能不足以稱，〔一一〕加有負薪之疾，恐先狗馬填溝壑，終無以報德塞責。願歸侯，乞骸骨，避賢者路。」上報曰：「古者賞有功，褒有德，守成〔上〕文，遭遇右武，〔一二〕未有易此者也。〔一三〕朕夙夜庶幾，獲承至尊，懼不能寧，惟所與共為治者，君宜知之。〔一四〕蓋君子善善及後世，若茲行，常在朕躬。〔一五〕君不幸罹霜露之疾，何恙不已，〔一六〕乃上書歸侯，乞骸骨，是章朕之不德也。〔一七〕今事少閒，〔一八〕君其存精神，止念慮，輔助醫藥以自持。」因賜告牛酒雜帛。居數月，有瘳，視事。","sentenceOrder":65},
  {"id":"s_work_han_thu_70_66","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「填音竹刃反。」","sentenceOrder":66},
  {"id":"s_work_han_thu_70_67","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「由，從也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_70_68","chapterId":"ch_work_han_thu_70","textTraditional":"〔三〕　師古曰：「稱，副也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_70_69","chapterId":"ch_work_han_thu_70","textTraditional":"〔四〕　師古曰：「塞，當也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_70_70","chapterId":"ch_work_han_thu_70","textTraditional":"〔五〕　師古曰：「疑則問之，故成其智。」","sentenceOrder":70},
  {"id":"s_work_han_thu_70_71","chapterId":"ch_work_han_thu_70","textTraditional":"〔六〕　師古曰：「屈己濟物，故為仁也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_70_72","chapterId":"ch_work_han_thu_70","textTraditional":"〔七〕　師古曰：「不求苟得，故為勇也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_70_73","chapterId":"ch_work_han_thu_70","textTraditional":"〔八〕　師古曰：「自『好問近乎知』以下，皆禮記中庸之辭。」","sentenceOrder":73},
  {"id":"s_work_han_thu_70_74","chapterId":"ch_work_han_thu_70","textTraditional":"〔九〕　師古曰：「言未嘗從軍旅。」","sentenceOrder":74},
  {"id":"s_work_han_thu_70_75","chapterId":"ch_work_han_thu_70","textTraditional":"〔一０〕師古曰：「過猶誤也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_70_76","chapterId":"ch_work_han_thu_70","textTraditional":"〔一一〕師古曰：「不副其任也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_70_77","chapterId":"ch_work_han_thu_70","textTraditional":"〔一二〕師古曰：「右亦上也，禍亂時則上武耳。」","sentenceOrder":77},
  {"id":"s_work_han_thu_70_78","chapterId":"ch_work_han_thu_70","textTraditional":"〔一三〕師古曰：「易，改也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_70_79","chapterId":"ch_work_han_thu_70","textTraditional":"〔一四〕師古曰：「惟，思也。知謂知治道也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_70_80","chapterId":"ch_work_han_thu_70","textTraditional":"〔一五〕師古曰：「朕常思此，不息於心也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_70_81","chapterId":"ch_work_han_thu_70","textTraditional":"〔一六〕師古曰：「罹，遭也。恙，憂也。已，止也。言何憂於疾不止也。禮記曰『疾止復初』也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_70_82","chapterId":"ch_work_han_thu_70","textTraditional":"〔一七〕師古曰：「章，明也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_70_83","chapterId":"ch_work_han_thu_70","textTraditional":"〔一八〕師古曰：「閒言有空隙也。閒讀曰閑。」","sentenceOrder":83},
  {"id":"s_work_han_thu_70_84","chapterId":"ch_work_han_thu_70","textTraditional":"凡為丞相御史六歲，年八十，終丞相位。其後李蔡、嚴青翟、趙周、石慶、公孫賀、劉屈〈氂，中“未改牙”〉繼踵為丞相。〔一〕自蔡至慶，丞相府客館丘虛而已，〔二〕至賀、屈〈氂，中“未改牙”〉時壞以為馬廄車庫奴婢室矣，唯慶以惇謹，復終相位，〔三〕其餘盡伏誅云。","sentenceOrder":84},
  {"id":"s_work_han_thu_70_85","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「繼踵，言相躡也。屈音丘勿反，又鉅勿反。〈氂，中“未改牙”〉音力之反。」","sentenceOrder":85},
  {"id":"s_work_han_thu_70_86","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「言不能進賢，故不繕修其室屋也。虛讀曰墟。」","sentenceOrder":86},
  {"id":"s_work_han_thu_70_87","chapterId":"ch_work_han_thu_70","textTraditional":"〔三〕　師古曰：「惇，厚也，音敦。」","sentenceOrder":87},
  {"id":"s_work_han_thu_70_88","chapterId":"ch_work_han_thu_70","textTraditional":"弘子度嗣侯，為山陽太守十餘歲，詔徵鉅野令史成詣公車，度留不遣，坐論為城旦。","sentenceOrder":88},
  {"id":"s_work_han_thu_70_89","chapterId":"ch_work_han_thu_70","textTraditional":"元始中，修功臣後，下詔曰：「漢興以來，股肱在位，身行儉約，輕財重義，未有若公孫弘者也。位在宰相封侯，而為布被脫粟之飯，奉祿以給故人賓客，無有所餘，可謂減於制度，〔一〕而率下篤俗者也，〔二〕與內富厚而外為詭服以釣虛譽者殊科。〔三〕夫表德章義，所以率世厲俗，聖王之制也。其賜弘後子孫之次見為適者，〔四〕爵關內侯，食邑三百戶。」","sentenceOrder":89},
  {"id":"s_work_han_thu_70_90","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　應劭曰：「禮，貴有常尊，衣服有品。」","sentenceOrder":90},
  {"id":"s_work_han_thu_70_91","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「篤，厚也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_70_92","chapterId":"ch_work_han_thu_70","textTraditional":"〔三〕　師古曰：「詭，違也。詭服，謂與心志相違也。一曰，違眾之服也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_70_93","chapterId":"ch_work_han_thu_70","textTraditional":"〔四〕　師古曰：「見音胡電反。適讀曰嫡。」","sentenceOrder":93},
  {"id":"s_work_han_thu_70_94","chapterId":"ch_work_han_thu_70","textTraditional":"卜式，河南人也。以田畜為事。有少弟，弟壯，式脫身出，〔一〕獨取畜羊百餘，田宅財物盡與弟。式入山牧，十餘年，羊致千餘頭，買田宅。而弟盡破其產，式輒復分與弟者數矣。〔二〕","sentenceOrder":94},
  {"id":"s_work_han_thu_70_95","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「脫身謂引身出也。脫音他活反。」","sentenceOrder":95},
  {"id":"s_work_han_thu_70_96","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「數音所角反。」","sentenceOrder":96},
  {"id":"s_work_han_thu_70_97","chapterId":"ch_work_han_thu_70","textTraditional":"時漢方事匈奴，式上書，願輸家財半助邊。上使使問式：「欲為官乎？」式曰：「自（少）〔小〕牧羊，不習仕宦，不願也。」使者曰：「家豈有冤，欲言事乎？」式曰：「臣生與人亡所爭，邑人貧者貸之，〔一〕不善者教之，所居，人皆從式，式何故見冤！」使者曰：「苟，子何欲？」〔二〕式曰：「天子誅匈奴，愚以為賢者宜死節，有財者宜輸之，如此而匈奴可滅也。」使者以聞。上以語丞相弘。弘曰：「此非人情。不軌之臣〔三〕不可以為化而亂法，願陛下勿許。」上不報，數歲乃罷式。式歸，復田牧。","sentenceOrder":97},
  {"id":"s_work_han_thu_70_98","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「貸音土戴反。」","sentenceOrder":98},
  {"id":"s_work_han_thu_70_99","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「言子苟如此輸財，必有所欲。」","sentenceOrder":99},
  {"id":"s_work_han_thu_70_100","chapterId":"ch_work_han_thu_70","textTraditional":"〔三〕　師古曰：「軌亦法也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_70_101","chapterId":"ch_work_han_thu_70","textTraditional":"歲餘，會渾邪等降，縣官費眾，倉府空，〔一〕貧民大徙，皆卬給縣官，〔二〕無以盡贍。式復持錢二十萬與河南太守，以給徙民。河南上富人助貧民者，上識式姓名，曰：「是固前欲輸其家半財助邊。」乃賜式外繇四百人，〔三〕式又盡復與官。是時富豪皆爭匿財，〔四〕唯式尤欲助費。上於是以式終長者，乃召拜式為中郎，賜爵左庶長，〔五〕田十頃，布告天下，尊顯以風百姓。〔六〕","sentenceOrder":101},
  {"id":"s_work_han_thu_70_102","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「倉，粟所積也。府，錢所聚也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_70_103","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「卬音牛向反。」","sentenceOrder":103},
  {"id":"s_work_han_thu_70_104","chapterId":"ch_work_han_thu_70","textTraditional":"〔三〕　蘇林曰：「外繇謂戍邊也。一人出三百錢，謂之過更。式歲得十二萬錢也。一說，在繇役之外得復除四百人也。」師古曰：「一說是。」","sentenceOrder":104},
  {"id":"s_work_han_thu_70_105","chapterId":"ch_work_han_thu_70","textTraditional":"〔四〕　師古曰：「匿，藏也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_70_106","chapterId":"ch_work_han_thu_70","textTraditional":"〔五〕　師古曰：「第十爵。」","sentenceOrder":106},
  {"id":"s_work_han_thu_70_107","chapterId":"ch_work_han_thu_70","textTraditional":"〔六〕　師古曰：「風讀曰諷。」","sentenceOrder":107},
  {"id":"s_work_han_thu_70_108","chapterId":"ch_work_han_thu_70","textTraditional":"初式不願為郎，上曰：「吾有羊在上林中，欲令子牧之。」式既為郎，布衣屮蹻而牧羊。〔一〕歲餘，羊肥息。〔二〕上過其羊所，善之。式曰：「非獨羊也，治民亦猶是矣。以時起居，惡者輒去〔三〕，毋令敗群。」上奇其言，欲試使治民。拜式緱氏令，緱氏便之；遷成皋令，將漕最。〔四〕上以式朴忠，〔五〕拜為齊王太傅，轉為相。","sentenceOrder":108},
  {"id":"s_work_han_thu_70_109","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「蹻，即今之鞋也，南方謂之蹻。字本作屩，並音居略反。」","sentenceOrder":109},
  {"id":"s_work_han_thu_70_110","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「息，生也。言羊既肥而又生多也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_70_111","chapterId":"ch_work_han_thu_70","textTraditional":"〔三〕　師古曰：「去，除也，音丘巨反。」","sentenceOrder":111},
  {"id":"s_work_han_thu_70_112","chapterId":"ch_work_han_thu_70","textTraditional":"〔四〕　師古曰：「為縣令而又使（令）領漕，其課最上。」","sentenceOrder":112},
  {"id":"s_work_han_thu_70_113","chapterId":"ch_work_han_thu_70","textTraditional":"〔五〕　師古曰：「朴，質也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_70_114","chapterId":"ch_work_han_thu_70","textTraditional":"會呂嘉反，式上書曰：「臣聞主媿臣死。群臣宜盡死節，其駑下者宜出財以佐軍，如是則強國不犯之道也。〔一〕臣願與子男〔二〕及臨菑習弩博昌習船者請行死之，以盡臣節。」〔三〕上賢之，下詔曰：「朕聞報德以德，報怨以直。〔四〕今天下不幸有事，郡縣諸侯未有奮繇直道者也。〔五〕齊相雅行躬耕，〔六〕隨牧蓄番，輒分昆弟，更造，〔七〕不為利惑。〔八〕日者北邊有興，〔九〕上書助官。往年西河歲惡，率齊人入粟。〔一０〕今又首奮，〔一一〕雖未戰，可謂義形於內矣。〔一二〕其賜式爵關內侯，黃金四（百）〔十〕斤，田十頃，布告天下，使明知之。」","sentenceOrder":114},
  {"id":"s_work_han_thu_70_115","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「國家威強而不見侵犯。」","sentenceOrder":115},
  {"id":"s_work_han_thu_70_116","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「子男，自謂其子也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_70_117","chapterId":"ch_work_han_thu_70","textTraditional":"〔三〕　師古曰：「從軍而致死。」","sentenceOrder":117},
  {"id":"s_work_han_thu_70_118","chapterId":"ch_work_han_thu_70","textTraditional":"〔四〕　師古曰：「論語稱孔子〔曰〕『以直報怨，以德報德』，故詔引之。」","sentenceOrder":118},
  {"id":"s_work_han_thu_70_119","chapterId":"ch_work_han_thu_70","textTraditional":"〔五〕　孟康曰：「未有奮迅樂出身勞於徭役者也。」臣瓚曰：「言未有奮厲於正直之道也。」師古曰：「二說皆非也。奮，憤激也。繇讀與由同。由，從也。直道，謂報怨以直，征南越也。言無欲奮厲而從於報怨之道也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_70_120","chapterId":"ch_work_han_thu_70","textTraditional":"〔六〕　臣瓚曰：「雅，素也。言卜式躬耕於野，不要名利。」晉灼曰：「雅，正也。」師古曰：「晉說是也。言其行雅正，又躬耕也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_70_121","chapterId":"ch_work_han_thu_70","textTraditional":"〔七〕　師古曰：「言其蓄牧滋多，則與昆弟，而更自營為也。番音扶元反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_70_122","chapterId":"ch_work_han_thu_70","textTraditional":"〔八〕　師古曰：「言不惑於利。」","sentenceOrder":122},
  {"id":"s_work_han_thu_70_123","chapterId":"ch_work_han_thu_70","textTraditional":"〔九〕　師古曰：「日者，往日也。興謂發軍。」","sentenceOrder":123},
  {"id":"s_work_han_thu_70_124","chapterId":"ch_work_han_thu_70","textTraditional":"〔一０〕師古曰：「歲惡，猶凶歲也。禮記曰『歲凶，年穀不登』。」","sentenceOrder":124},
  {"id":"s_work_han_thu_70_125","chapterId":"ch_work_han_thu_70","textTraditional":"〔一一〕師古曰：「為首而奮厲，願從軍也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_70_126","chapterId":"ch_work_han_thu_70","textTraditional":"〔一二〕師古曰：「形，見也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_70_127","chapterId":"ch_work_han_thu_70","textTraditional":"元鼎中，徵式代石慶為御史大夫。式既在位，言郡國不便鹽鐵而船有算，可罷。上由是不說式。〔一〕明年當封禪，式又不習文章，貶秩為太子太傅，以兒寬代之。式以壽終。","sentenceOrder":127},
  {"id":"s_work_han_thu_70_128","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":128},
  {"id":"s_work_han_thu_70_129","chapterId":"ch_work_han_thu_70","textTraditional":"兒寬，千乘人也。〔一〕治尚書，事歐陽生。以郡國選詣博士，受業孔安國。貧無資用，嘗為弟子都養。〔二〕時行賃作，帶經而鉏，休息輒讀誦，其精如此。以射策為掌故，功次，補廷尉文學卒史。〔三〕","sentenceOrder":129},
  {"id":"s_work_han_thu_70_130","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「千乘郡千乘縣也。兒音五奚反。」","sentenceOrder":130},
  {"id":"s_work_han_thu_70_131","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「都，凡眾也。養，主給烹炊者也。貧無資用，故供諸弟子烹炊也。養音弋向反。」","sentenceOrder":131},
  {"id":"s_work_han_thu_70_132","chapterId":"ch_work_han_thu_70","textTraditional":"〔三〕　蘇林曰：「秩六百石，舊郡亦有也。」臣瓚曰：「漢注卒史秩百石。」師古曰：「瓚說是也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_70_133","chapterId":"ch_work_han_thu_70","textTraditional":"寬為人溫良，有廉知自將，〔一〕善屬文，〔二〕然懦於武〔三〕，口弗能發明也。時張湯為廷尉，廷尉府盡用文史法律之吏，〔四〕而寬以儒生在其間，見謂不習事，不署曹，〔五〕除為從史，〔六〕之北地視畜數年。〔七〕還至府，上畜簿，〔八〕會廷尉時有疑奏，已再見卻矣，〔九〕掾史莫知所為。寬為言其意，掾史因使寬為奏。奏成，讀之皆服，以白廷尉湯。湯大驚，召寬與語，乃奇其材，以為掾。上寬所作奏，即時得可。異日，湯見上。問曰：「前奏非俗吏所及，誰為之者？湯言兒寬。上曰：「吾固聞之久矣。」湯由是鄉學，〔一０〕以寬為奏讞掾，以古法義決疑獄，甚重之。及湯為御史大夫，以寬為掾，舉侍御史。見上，語經學。上說之，〔一一〕從問尚書一篇。擢為中大夫，遷左內史。","sentenceOrder":133},
  {"id":"s_work_han_thu_70_134","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「將，衛也，以智自衛護也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_70_135","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「屬，綴也，音之欲反。」","sentenceOrder":135},
  {"id":"s_work_han_thu_70_136","chapterId":"ch_work_han_thu_70","textTraditional":"〔三〕　師古曰：「懦，柔也，音乃喚反，又音儒。」","sentenceOrder":136},
  {"id":"s_work_han_thu_70_137","chapterId":"ch_work_han_thu_70","textTraditional":"〔四〕　師古曰：「史謂善史書者。」","sentenceOrder":137},
  {"id":"s_work_han_thu_70_138","chapterId":"ch_work_han_thu_70","textTraditional":"〔五〕　張晏曰：「不署為列曹也。」師古曰：「署，表也，置也。凡言署官，表其秩位，置立為之也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_70_139","chapterId":"ch_work_han_thu_70","textTraditional":"〔六〕　師古曰：「從史者，但只隨官僚，不主文書。」","sentenceOrder":139},
  {"id":"s_work_han_thu_70_140","chapterId":"ch_work_han_thu_70","textTraditional":"〔七〕　師古曰：「之，往也。畜謂廷尉之畜在北地者，若今諸司公廨牛羊。」","sentenceOrder":140},
  {"id":"s_work_han_thu_70_141","chapterId":"ch_work_han_thu_70","textTraditional":"〔八〕　師古曰：「簿謂文計也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_70_142","chapterId":"ch_work_han_thu_70","textTraditional":"〔九〕　師古曰：「卻，退也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_70_143","chapterId":"ch_work_han_thu_70","textTraditional":"〔一０〕師古曰：「鄉讀曰嚮。」","sentenceOrder":143},
  {"id":"s_work_han_thu_70_144","chapterId":"ch_work_han_thu_70","textTraditional":"〔一一〕師古曰：「說讀曰悅。」","sentenceOrder":144},
  {"id":"s_work_han_thu_70_145","chapterId":"ch_work_han_thu_70","textTraditional":"寬既治民，勸農業，緩刑罰，理獄訟，卑體下士，務在於得人心；〔一〕擇用仁厚士，推情與下，不求名聲，吏民大信愛之。寬表奏開六輔渠，〔二〕定水令以廣溉田。〔三〕收租稅，時裁闊狹，與民相假貸，〔四〕以故租多不入。後有軍發，左內史以負租課殿，當免。民聞當免，皆恐失之，大家牛車，小家擔負，輸租繈屬不絕，〔五〕課更以最。上由此愈奇寬。","sentenceOrder":145},
  {"id":"s_work_han_thu_70_146","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「下音胡稼反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_70_147","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　韋昭曰：「六輔謂京兆、馮翊、扶風、河東、河南、河內也。」劉德曰：「於六輔界中為渠也。」師古曰：「二說皆非也。溝洫志云『兒寬為左內史，奏請穿六輔渠以益溉鄭國旁高卬之田』，此則於鄭國渠上流南岸更開六道小渠以輔助溉灌耳。今雍州雲陽、三原兩縣界此渠尚存，鄉人名曰六渠，亦號輔渠。故河渠書云『關內則輔渠、靈軹』是也，焉說三河之地哉！」","sentenceOrder":147},
  {"id":"s_work_han_thu_70_148","chapterId":"ch_work_han_thu_70","textTraditional":"〔三〕　師古曰：「為用水之次具立法，令皆得其所也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_70_149","chapterId":"ch_work_han_thu_70","textTraditional":"〔四〕　師古曰：「謂有貧弱及農要之時不即徵收也。貸音土代反。」","sentenceOrder":149},
  {"id":"s_work_han_thu_70_150","chapterId":"ch_work_han_thu_70","textTraditional":"〔五〕　師古曰：「繈，索也，言輸者接連，不絕於道，若繩索之相屬也，猶今言續索矣。屬音之欲反。」","sentenceOrder":150},
  {"id":"s_work_han_thu_70_151","chapterId":"ch_work_han_thu_70","textTraditional":"及議欲放古巡狩封禪之事，〔一〕諸儒對者五十餘人，未能有所定。先是，司馬相如病死，有遺書，頌功德，言符瑞，足以封泰山。上奇其書，以問寬，寬對曰：「陛下躬發聖德，統楫群元，〔二〕宗祀天地，薦禮百神，精神所鄉，徵兆必報，〔三〕天地並應，符瑞昭明。其封泰山，禪梁父，昭姓考瑞，帝王之盛節也。然享薦之義，不著于經，〔四〕以為封禪告成，合祛於天地神祇，〔五〕祗戒精專以接神明。總百官之職，各稱事宜而為之節文。〔六〕唯聖主所由，制定其當，〔七〕非群臣之所能列。今將舉大事，優游數年，〔八〕使群臣得人自盡，終莫能成。〔九〕唯天子建中和之極，兼總條貫〔一０〕，金聲而玉振之，〔一一〕以順成天慶，垂萬世之基。」上然之，乃自制儀，采儒術以文焉。","sentenceOrder":151},
  {"id":"s_work_han_thu_70_152","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「放，依也，音甫往反。」","sentenceOrder":152},
  {"id":"s_work_han_thu_70_153","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　張晏曰：「統，察；楫，聚也。」如淳曰：「曆數之元也。」臣瓚曰：「統猶總覽也。楫當作輯。」師古曰：「輯、楫與集，三字並同。虞書曰『楫五瑞』是也，其字從木。瓚曰當為輯，不通。」","sentenceOrder":153},
  {"id":"s_work_han_thu_70_154","chapterId":"ch_work_han_thu_70","textTraditional":"〔三〕　師古曰：「鄉讀曰嚮。徵，證也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_70_155","chapterId":"ch_work_han_thu_70","textTraditional":"〔四〕　師古曰：「封禪之享薦也，以非常禮，故經無其文。著音竹箸反。」","sentenceOrder":155},
  {"id":"s_work_han_thu_70_156","chapterId":"ch_work_han_thu_70","textTraditional":"〔五〕　李奇曰：「祛，開散；合，閉也。開閉於天地也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_70_157","chapterId":"ch_work_han_thu_70","textTraditional":"〔六〕　師古曰：「稱，副也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_70_158","chapterId":"ch_work_han_thu_70","textTraditional":"〔七〕　師古曰：「當猶中也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_70_159","chapterId":"ch_work_han_thu_70","textTraditional":"〔八〕　師古曰：「言不決也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_70_160","chapterId":"ch_work_han_thu_70","textTraditional":"〔九〕　師古曰：「所言不同，各有執見也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_70_161","chapterId":"ch_work_han_thu_70","textTraditional":"〔一０〕師古曰：「極，正也。周禮曰『以為人極』也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_70_162","chapterId":"ch_work_han_thu_70","textTraditional":"〔一一〕師古曰：「言振揚德音，如金玉之聲也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_70_163","chapterId":"ch_work_han_thu_70","textTraditional":"既成，將用事，拜寬為御史大夫，從東封泰山，還登明堂。寬上壽曰：「臣聞三代改制，屬象相因。〔一〕間者聖統廢絕，〔二〕陛下發憤，合指天地，祖立明堂辟雍，〔三〕宗祀泰一，〔四〕六律五聲，〔五〕幽贊聖意，〔六〕神樂四合，各有方象，〔七〕以丞嘉祀，為萬世則，〔八〕天下幸甚。將建大元本瑞，登告岱宗，發祉闓門，以候景至。癸亥宗祀，日宣重光；上元甲子，肅邕永享。〔九〕光輝充塞，天文粲然，〔一０〕（充）〔見〕象日昭，報降符應。〔一一〕臣寬奉觴再拜，上千萬歲壽。」制曰：「敬舉君之觴。」","sentenceOrder":163},
  {"id":"s_work_han_thu_70_164","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　李奇曰：「政教之法象相因屬也。」師古曰：「屬，連也，音之欲反。」","sentenceOrder":164},
  {"id":"s_work_han_thu_70_165","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「聖統，聖人之遺業，謂禮文也。」","sentenceOrder":165},
  {"id":"s_work_han_thu_70_166","chapterId":"ch_work_han_thu_70","textTraditional":"〔三〕　師古曰：「祖，始也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_70_167","chapterId":"ch_work_han_thu_70","textTraditional":"〔四〕　師古曰：「宗，尊也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_70_168","chapterId":"ch_work_han_thu_70","textTraditional":"〔五〕　師古曰：「六律，謂黃鍾、太蔟、姑洗、蕤賓、夷則、無射也。五聲，宮、商、角、徵、羽也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_70_169","chapterId":"ch_work_han_thu_70","textTraditional":"〔六〕　師古曰：「幽，深也。贊，明也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_70_170","chapterId":"ch_work_han_thu_70","textTraditional":"〔七〕　如淳曰：「四方色及五神祭祀聲樂各有等。」","sentenceOrder":170},
  {"id":"s_work_han_thu_70_171","chapterId":"ch_work_han_thu_70","textTraditional":"〔八〕　師古曰：「則，法也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_70_172","chapterId":"ch_work_han_thu_70","textTraditional":"〔九〕　李奇曰：「太平之世，日抱重光，謂日有重日也。」蘇林曰：「將，甫始之辭也。太元，太初曆也。本瑞，謂白麟、寶鼎之屬也。以候景至，冬至之景也。上元甲子，太初元年甲子朔旦冬至也。」師古曰：「宗，尊也。肅，敬也。雍，和也。既敬且和，則長為天所亨也。闓讀與開同。」","sentenceOrder":172},
  {"id":"s_work_han_thu_70_173","chapterId":"ch_work_han_thu_70","textTraditional":"〔一０〕師古曰：「塞，滿也。粲然，明貌。」","sentenceOrder":173},
  {"id":"s_work_han_thu_70_174","chapterId":"ch_work_han_thu_70","textTraditional":"〔一一〕師古曰：「言（大）〔天〕顯示景象，日日昭明也。降下符應，以報德化。」","sentenceOrder":174},
  {"id":"s_work_han_thu_70_175","chapterId":"ch_work_han_thu_70","textTraditional":"後太史令司馬遷等言：「曆紀壞廢，漢興未改正朔，宜可正。」上乃詔寬與遷等共定漢太初曆。語在律曆志。","sentenceOrder":175},
  {"id":"s_work_han_thu_70_176","chapterId":"ch_work_han_thu_70","textTraditional":"初梁相褚大通五經，為博士，時寬為弟子。及御史大夫缺，徵褚大，大自以為得御史大夫。至洛陽，聞兒寬為之，褚大笑。及至，與寬議封禪於上前，大不能及，退而服曰：「上誠知人。」寬為御史大夫，以稱意任職，故久無有所匡諫於上，官屬易之。〔一〕居位九歲，以官卒。","sentenceOrder":176},
  {"id":"s_work_han_thu_70_177","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　師古曰：「易，輕也，音弋（鼓）〔豉〕反。」","sentenceOrder":177},
  {"id":"s_work_han_thu_70_178","chapterId":"ch_work_han_thu_70","textTraditional":"贊曰：公孫弘、卜式、兒寬皆以鴻漸之翼困於燕爵，〔一〕遠跡羊豕之間，〔二〕非遇其時，焉能致此位乎？〔三〕是時，漢興六十餘載，海內艾安，〔四〕府庫充實，而四夷未賓，制度多闕。上方欲用文武，求之如弗及，〔五〕始以蒲輪迎枚生，見主父而歎息。〔六〕群士慕嚮，異人並出。卜式拔於芻牧，弘羊擢於賈豎，衛青奮於奴僕，日磾出於降虜，斯亦曩時版築飯牛之（明）〔朋〕已。〔七〕漢之得人，於茲為盛，儒雅則公孫弘、董仲舒、兒寬，篤行則石建、石慶，質直則汲黯、卜式，推賢則韓安國、鄭當時，定令則趙禹、張湯，文章則司馬遷、相如，滑稽則東方朔、枚皋，〔八〕應對則嚴助、朱買臣，曆數則唐都、洛下閎，協律則李延年，運籌則桑弘羊，奉使則張騫、蘇武，將率則衛青、霍去病，受遺則霍光、金日磾，其餘不可勝紀。〔九〕是以興造功業，制度遺文，後世莫及。孝宣承統，纂修洪業，亦講論六藝，招選茂異，而蕭望之、梁丘賀、夏侯勝、韋玄成、嚴彭祖、尹更始以儒術進，劉向、王褒以文章顯，將相則張安世、趙充國、魏相、丙吉、于定國、杜延年，治民則黃霸、王成、龔遂、鄭弘、召信臣、〔一０〕韓延壽、尹翁歸、趙廣漢、嚴延年、張敞之屬，皆有功跡見述於世。參其名臣，亦其次也。〔一一〕","sentenceOrder":178},
  {"id":"s_work_han_thu_70_179","chapterId":"ch_work_han_thu_70","textTraditional":"〔一〕　李奇曰：「漸，進也。鴻一舉而進千里者，羽翼之材也。弘等皆以大材初為俗所薄，若燕爵不知鴻志也。」師古曰：「易漸卦上九爻辭曰：『鴻漸于陸，其羽可以為儀。』鴻，大鳥。漸，進也。高平曰陸。言鴻進於陸，以其羽翼為威儀也。喻弘等皆有鴻之羽儀，未進之時，燕爵所輕也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_70_180","chapterId":"ch_work_han_thu_70","textTraditional":"〔二〕　師古曰：「遠竄其跡也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_70_181","chapterId":"ch_work_han_thu_70","textTraditional":"〔三〕　師古曰：「焉，於（曰）〔何〕也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_70_182","chapterId":"ch_work_han_thu_70","textTraditional":"〔四〕　師古曰：「艾讀曰乂。」","sentenceOrder":182},
  {"id":"s_work_han_thu_70_183","chapterId":"ch_work_han_thu_70","textTraditional":"〔五〕　師古曰：「恐失之。」","sentenceOrder":183},
  {"id":"s_work_han_thu_70_184","chapterId":"ch_work_han_thu_70","textTraditional":"〔六〕　師古曰：「謂言『公皆安在？何相見之晚！』」","sentenceOrder":184},
  {"id":"s_work_han_thu_70_185","chapterId":"ch_work_han_thu_70","textTraditional":"〔七〕　師古曰：「版築，傅說也。飯牛，甯戚也。已，語終辭也。飯音扶晚反。」","sentenceOrder":185},
  {"id":"s_work_han_thu_70_186","chapterId":"ch_work_han_thu_70","textTraditional":"〔八〕　師古曰：「滑稽，轉利之稱也。滑，亂也。稽，礙也。言其變亂無留礙也。一說，稽，考也。言可滑亂不可考校也。滑音骨。稽音工奚反。」","sentenceOrder":186},
  {"id":"s_work_han_thu_70_187","chapterId":"ch_work_han_thu_70","textTraditional":"〔九〕　師古曰：「紀，記也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_70_188","chapterId":"ch_work_han_thu_70","textTraditional":"〔一０〕師古曰：「召讀曰邵。」","sentenceOrder":188},
  {"id":"s_work_han_thu_70_189","chapterId":"ch_work_han_thu_70","textTraditional":"〔一一〕師古曰：「次於武帝時。」","sentenceOrder":189},
  {"id":"s_work_han_thu_70_190","chapterId":"ch_work_han_thu_70","textTraditional":"校勘記","sentenceOrder":190},
  {"id":"s_work_han_thu_70_191","chapterId":"ch_work_han_thu_70","textTraditional":"二六一四頁　三行　〔敢〕問子大夫：　景祐、殿本都有「敢」字。王先謙說有「敢」字是。","sentenceOrder":191},
  {"id":"s_work_han_thu_70_192","chapterId":"ch_work_han_thu_70","textTraditional":"二六一五頁　四行　夫厚（當）〔賞〕重刑未足以勸善而禁非，　景祐、汲古、殿、局本都作「賞」，此誤。","sentenceOrder":192},
  {"id":"s_work_han_thu_70_193","chapterId":"ch_work_han_thu_70","textTraditional":"二六一五頁　七行　凡此八者，治〔民〕之本也。　景祐、殿本都有「民」字。","sentenceOrder":193},
  {"id":"s_work_han_thu_70_194","chapterId":"ch_work_han_thu_70","textTraditional":"二六一五頁一四行　（師古）〔李奇〕曰：　景祐、殿本都作「李奇」，此誤。","sentenceOrder":194},
  {"id":"s_work_han_thu_70_195","chapterId":"ch_work_han_thu_70","textTraditional":"二六一六頁一三行　通〔壅〕塞之塗，　錢大昭說「通」下脫「壅」字。按景祐、殿本都有「壅」字。","sentenceOrder":195},
  {"id":"s_work_han_thu_70_196","chapterId":"ch_work_han_thu_70","textTraditional":"二六一七頁一三行　魯（斑）〔班〕門　殿本作「班」。王先謙說作「班」是。","sentenceOrder":196},
  {"id":"s_work_han_thu_70_197","chapterId":"ch_work_han_thu_70","textTraditional":"二六二一頁　八行　不精（鑿）〔〈暂缺EFDD〉〕也。　李楨說「鑿」當作「〈暂缺EFDD〉」。按景祐、殿本都作「〈暂缺EFDD〉」。","sentenceOrder":197},
  {"id":"s_work_han_thu_70_198","chapterId":"ch_work_han_thu_70","textTraditional":"二六二二頁　二行　陛下（下）過意擢臣弘卒伍之中，　景祐、殿本都不重「下」字。","sentenceOrder":198},
  {"id":"s_work_han_thu_70_199","chapterId":"ch_work_han_thu_70","textTraditional":"二六二二頁　四行　守成〔上〕文，　景祐、殿本都有「上」字。王先謙說據下顏注當有。","sentenceOrder":199},
  {"id":"s_work_han_thu_70_200","chapterId":"ch_work_han_thu_70","textTraditional":"二六二五頁　一行　自（少）〔小〕牧羊，　景祐、殿本都作「小」。","sentenceOrder":200},
  {"id":"s_work_han_thu_70_201","chapterId":"ch_work_han_thu_70","textTraditional":"二六二六頁一四行　為縣令而又使（令）領漕，　景祐、殿本都無下「令」字。","sentenceOrder":201},
  {"id":"s_work_han_thu_70_202","chapterId":"ch_work_han_thu_70","textTraditional":"二六二七頁　五行　黃金四（百）〔十〕斤，　景祐、殿本都作「十」。王先謙說，以理度之，「十」字是。","sentenceOrder":202},
  {"id":"s_work_han_thu_70_203","chapterId":"ch_work_han_thu_70","textTraditional":"二六二七頁　九行　論語稱孔子〔曰〕　景祐、殿本都有「曰」字，此脫。","sentenceOrder":203},
  {"id":"s_work_han_thu_70_204","chapterId":"ch_work_han_thu_70","textTraditional":"二六三二頁　五行　（充）〔見〕象日昭，　景祐、殿本都作「見」。","sentenceOrder":204},
  {"id":"s_work_han_thu_70_205","chapterId":"ch_work_han_thu_70","textTraditional":"二六三三頁　三行　言（大）〔天〕顯示景象，　殿本作「天」。王先謙說作「天」是。","sentenceOrder":205},
  {"id":"s_work_han_thu_70_206","chapterId":"ch_work_han_thu_70","textTraditional":"二六三三頁　九行　音弋（鼓）〔豉〕反。　景祐、殿本都作「豉」，此誤。","sentenceOrder":206},
  {"id":"s_work_han_thu_70_207","chapterId":"ch_work_han_thu_70","textTraditional":"二六三三頁一四行　斯亦曩時版築飯牛之（明）〔朋〕已。　殿本作「朋」。王先謙說殿本是。","sentenceOrder":207},
  {"id":"s_work_han_thu_70_208","chapterId":"ch_work_han_thu_70","textTraditional":"二六三四頁一三行　焉，於（曰）〔何〕也。　景祐、殿本都作「何」，此誤。","sentenceOrder":208},
  {"id":"s_work_han_thu_71_1","chapterId":"ch_work_han_thu_71","textTraditional":"張湯，杜陵人也。父為長安丞，出，湯為兒守舍。〔一〕還，鼠盜肉，父怒，笞湯。湯掘熏得鼠及餘肉，劾鼠掠治，傳爰書，訊鞫論報，〔二〕并取鼠與肉，具獄磔堂下。〔三〕父見之，視文辭如老獄吏，大驚，遂使書獄。〔四〕","sentenceOrder":1},
  {"id":"s_work_han_thu_71_2","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「稱為兒者，言其尚幼小也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_71_3","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「傳謂傳逮，若今之追逮赴對也。爰，換也，以文書代換其口辭也。訊，考問也。鞫，窮也，謂窮覈之也。論報，謂上論之而獲報也。訊音信。」","sentenceOrder":3},
  {"id":"s_work_han_thu_71_4","chapterId":"ch_work_han_thu_71","textTraditional":"〔三〕　師古曰：「具為治獄之文，處正其罪而磔鼠也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_71_5","chapterId":"ch_work_han_thu_71","textTraditional":"〔四〕　如淳曰：「決獄之書，謂律令也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_71_6","chapterId":"ch_work_han_thu_71","textTraditional":"父死後，湯為長安吏。周陽侯為諸卿時，〔一〕嘗繫長安，湯傾身事之。及出為侯，大與湯交，遍見貴人。湯給事內史，為甯成掾，以湯為無害，言大府，〔二〕調茂陵尉，〔三〕治方中。〔四〕","sentenceOrder":6},
  {"id":"s_work_han_thu_71_7","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「姓趙。」","sentenceOrder":7},
  {"id":"s_work_han_thu_71_8","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「大府，丞相府也。無害，言其最勝也，解在蕭何傳。」","sentenceOrder":8},
  {"id":"s_work_han_thu_71_9","chapterId":"ch_work_han_thu_71","textTraditional":"〔三〕　師古曰：「調，選也，選以為此官也。調音徒釣反。」","sentenceOrder":9},
  {"id":"s_work_han_thu_71_10","chapterId":"ch_work_han_thu_71","textTraditional":"〔四〕　孟康曰：「方中，陵上土作方也，湯主治之。」蘇林曰：「天子即位，豫作陵，諱之，故言方中，或言斥土。」如淳曰：「漢注陵方中用地一頃，深十二丈。」師古曰：「蘇說非也。古謂掘地為阬曰方，今荊楚俗土功築作算程課者，猶以方計之，非謂避諱也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_71_11","chapterId":"ch_work_han_thu_71","textTraditional":"武安侯為丞相，〔一〕徵湯為史，薦補侍御史。治陳皇后巫蠱獄，深竟黨與，上以為能，遷太中大夫。與趙禹共定諸律令，務在深文，拘守職之吏。〔二〕已而禹至少府，湯為廷尉，兩人交驩，兄事禹。〔三〕禹志在奉公孤立，而湯舞知以御人。〔四〕始為小吏，乾沒，與長安富賈田甲、魚翁叔之屬交私。〔五〕及列九卿，收接天下名士大夫，己心內雖不合，然陽浮道與之。〔六〕","sentenceOrder":11},
  {"id":"s_work_han_thu_71_12","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「田蚡。」","sentenceOrder":12},
  {"id":"s_work_han_thu_71_13","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　蘇林曰：「拘刻於守職之吏。」","sentenceOrder":13},
  {"id":"s_work_han_thu_71_14","chapterId":"ch_work_han_thu_71","textTraditional":"〔三〕　師古曰：「事之如兄。」","sentenceOrder":14},
  {"id":"s_work_han_thu_71_15","chapterId":"ch_work_han_thu_71","textTraditional":"〔四〕　師古曰：「舞弄其智，制御它人也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_71_16","chapterId":"ch_work_han_thu_71","textTraditional":"〔五〕　服虔曰：「乾沒，射成敗也。」如淳曰：「豫居物以待之，得利為乾，失利為沒。」師古曰：「乾音干。」","sentenceOrder":16},
  {"id":"s_work_han_thu_71_17","chapterId":"ch_work_han_thu_71","textTraditional":"〔六〕　師古曰：「陽以道義為交，非其中心，故云浮也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_71_18","chapterId":"ch_work_han_thu_71","textTraditional":"是時，上方鄉文學，〔一〕湯決大獄，欲傅古義，〔二〕乃請博士弟子治尚書、春秋，補廷尉史，平亭疑法。奏讞疑，〔三〕必奏先為上分別其原，上所是，受而著讞法廷尉挈令，〔四〕揚主之明〔五〕。奏事即譴，湯摧謝，〔六〕鄉上意所便，〔七〕必引正監掾史賢者，曰：「固為臣議，如（此）上責臣，〔八〕臣弗用，愚抵此。」〔九〕罪常釋。〔一０〕間即奏事，上善之，曰：「臣非知為此奏，乃監、掾、史某所為。」〔一一〕其欲薦吏，揚人之善解人之過如此。所治即上意所欲罪，予監吏深刻者；即上意所欲釋，予監吏輕平者。所治即豪，必舞文巧詆；〔一二〕即下戶羸弱，時口言「雖文致法，上裁察。」於是往往釋湯所言。〔一三〕湯至於大吏，內行修，交通賓客飲食，於故人子弟為吏及貧昆弟，調護之尤厚。〔一四〕其造請諸公，不避寒暑。〔一五〕是以湯雖文深意忌不專平，然得此聲譽。而深刻吏多為爪牙用者，依於文學之士。丞相弘數稱其美。","sentenceOrder":18},
  {"id":"s_work_han_thu_71_19","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":19},
  {"id":"s_work_han_thu_71_20","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「傅讀曰附。」","sentenceOrder":20},
  {"id":"s_work_han_thu_71_21","chapterId":"ch_work_han_thu_71","textTraditional":"〔三〕　李奇曰：「亭亦平也。」師古曰：「亭，均也，調也。言平均疑法及為讞疑奏之。」","sentenceOrder":21},
  {"id":"s_work_han_thu_71_22","chapterId":"ch_work_han_thu_71","textTraditional":"〔四〕　韋昭曰：「在板挈也。」師古曰：「著謂明書之也。挈，獄訟之要也。書於讞法挈令以為後式也。挈音口計反。」","sentenceOrder":22},
  {"id":"s_work_han_thu_71_23","chapterId":"ch_work_han_thu_71","textTraditional":"〔五〕　師古曰：「言此自天子之意，非由臣下有司。」","sentenceOrder":23},
  {"id":"s_work_han_thu_71_24","chapterId":"ch_work_han_thu_71","textTraditional":"〔六〕　蘇林曰：「深自挫按也。」師古曰：「若上有責，即摧折而謝也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_71_25","chapterId":"ch_work_han_thu_71","textTraditional":"〔七〕　師古曰：「謂如天子責湯之指而言其端也。鄉讀曰嚮。」","sentenceOrder":25},
  {"id":"s_work_han_thu_71_26","chapterId":"ch_work_han_thu_71","textTraditional":"〔八〕　師古曰：「如上之意。」","sentenceOrder":26},
  {"id":"s_work_han_thu_71_27","chapterId":"ch_work_han_thu_71","textTraditional":"〔九〕　蘇林曰：「坐不用諸掾語，故至於此。」","sentenceOrder":27},
  {"id":"s_work_han_thu_71_28","chapterId":"ch_work_han_thu_71","textTraditional":"〔一０〕臣瓚曰：「謂常見原也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_71_29","chapterId":"ch_work_han_thu_71","textTraditional":"〔一一〕師古曰：「間謂非當朝奏者。」","sentenceOrder":29},
  {"id":"s_work_han_thu_71_30","chapterId":"ch_work_han_thu_71","textTraditional":"〔一二〕師古曰：「詆，誣也，音丁禮反。其下並同。」","sentenceOrder":30},
  {"id":"s_work_han_thu_71_31","chapterId":"ch_work_han_thu_71","textTraditional":"〔一三〕李奇曰：「先見上口言之，欲與輕平，故皆見原釋也。」如淳曰：「雖文書按察致下戶之罪，湯以先口解之矣。上以湯言，輒裁察之，輕其罪也。」師古曰：「李、如二說皆非也。此言下戶羸弱，湯欲佐助，雖具文奏之，而又口奏，言雖律令之文合致此罪，聽上裁察，蓋為此人希恩宥也。於是上得湯言，往往釋其人罪，非未奏之前口豫言也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_71_32","chapterId":"ch_work_han_thu_71","textTraditional":"〔一四〕師古曰：「調，和適之。令得其所也。護謂保佑也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_71_33","chapterId":"ch_work_han_thu_71","textTraditional":"〔一五〕師古曰：「造，至詣也。請，謁問也。造音七到反。」","sentenceOrder":33},
  {"id":"s_work_han_thu_71_34","chapterId":"ch_work_han_thu_71","textTraditional":"及治淮南、衡山、江都反獄，皆窮根本。嚴助、伍被，上欲釋之，湯爭曰：「伍被本造反謀，而助親幸出入禁闥腹心之臣，乃交私諸侯，如此弗誅，後不可治。」上可論之。〔一〕其治獄所巧排大臣自以為功，多此類。繇是益尊任，〔二〕遷御史大夫。","sentenceOrder":34},
  {"id":"s_work_han_thu_71_35","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「可湯所奏而論決之。」","sentenceOrder":35},
  {"id":"s_work_han_thu_71_36","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「繇讀與由同。」","sentenceOrder":36},
  {"id":"s_work_han_thu_71_37","chapterId":"ch_work_han_thu_71","textTraditional":"會渾邪等降漢，大興兵伐匈奴，山東水旱，貧民流徙，皆卬給縣官，〔一〕縣官空虛。湯承上指，請造白金及五銖錢，籠天下鹽鐵，〔二〕排富商大賈，出告緡令，鉏豪彊并兼之家，舞文巧詆以輔法。〔三〕湯每朝奏事，語國家用，日旰，〔四〕天子忘食。丞相取充位，〔五〕天下事皆決湯。百姓不安其生，騷動，縣官所興未獲其利，姦吏並侵漁，〔六〕於是痛繩以罪。自公卿以下至於庶人咸指湯。湯嘗病，上自至舍視，其隆貴如此。","sentenceOrder":37},
  {"id":"s_work_han_thu_71_38","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「卬音牛向反。」","sentenceOrder":38},
  {"id":"s_work_han_thu_71_39","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「籠羅其事，皆令利入官。」","sentenceOrder":39},
  {"id":"s_work_han_thu_71_40","chapterId":"ch_work_han_thu_71","textTraditional":"〔三〕　師古曰：「輔，助也。以巧詆助法，言不公平也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_71_41","chapterId":"ch_work_han_thu_71","textTraditional":"〔四〕　師古曰：「旰，晚也。論事既多，至於日晚。旰音幹。」","sentenceOrder":41},
  {"id":"s_work_han_thu_71_42","chapterId":"ch_work_han_thu_71","textTraditional":"〔五〕　師古曰：「但充其位而已，無所造設也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_71_43","chapterId":"ch_work_han_thu_71","textTraditional":"〔六〕　師古曰：「並，且也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_71_44","chapterId":"ch_work_han_thu_71","textTraditional":"匈奴求和親，群臣議前，〔一〕博士狄山曰：「和親便。」上問其便，山曰：「兵，凶器，未易數動。〔二〕高帝欲伐匈奴，大困平城，乃遂結和親。孝惠、高后時，天下安樂，及文帝欲事匈奴，北邊蕭然苦兵。〔三〕孝景時，吳楚七國反，景帝往來東宮間，〔四〕天下寒心數月。〔五〕吳楚已破，竟景帝不言兵，〔六〕天下富實。今自陛下興兵擊匈奴，中國以空虛，邊大困貧。由是觀之，不如和親。」上問湯，湯曰：「此愚儒無知。」狄山曰：「臣固愚忠，若御史大夫湯，乃詐忠。湯之治淮南、江都，以深文痛詆諸侯，別疏骨肉，使藩臣不自安，臣固知湯之（為）詐忠。」於是上作色曰：「吾使生居一郡，能無使虜入盜乎？」〔七〕山曰：「不能。」曰：「居一縣？」曰：「不能。」復曰：「居一鄣間？」〔八〕山自度辯窮且下吏，〔九〕曰：「能。」乃遣山乘鄣。〔一０〕至月餘，匈奴斬山頭而去。是後群臣震讋。〔一一〕","sentenceOrder":44},
  {"id":"s_work_han_thu_71_45","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「於上前議事。」","sentenceOrder":45},
  {"id":"s_work_han_thu_71_46","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「言難可屢動。」","sentenceOrder":46},
  {"id":"s_work_han_thu_71_47","chapterId":"ch_work_han_thu_71","textTraditional":"〔三〕　師古曰：「蕭然猶騷然，擾動之貌也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_71_48","chapterId":"ch_work_han_thu_71","textTraditional":"〔四〕　師古曰：「謂諮謀於太后也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_71_49","chapterId":"ch_work_han_thu_71","textTraditional":"〔五〕　師古曰：「懼於兵難也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_71_50","chapterId":"ch_work_han_thu_71","textTraditional":"〔六〕　師古曰：「訖景帝之身更不議征伐之事。」","sentenceOrder":50},
  {"id":"s_work_han_thu_71_51","chapterId":"ch_work_han_thu_71","textTraditional":"〔七〕　師古曰：「博士之官，故呼為生也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_71_52","chapterId":"ch_work_han_thu_71","textTraditional":"〔八〕　師古曰：「鄣謂塞上要險之處，別築為城，因置吏士而為鄣蔽以扞寇也。鄣音之向反。」","sentenceOrder":52},
  {"id":"s_work_han_thu_71_53","chapterId":"ch_work_han_thu_71","textTraditional":"〔九〕　師古曰：「度，計也。見詰自辯而辭窮，當下吏也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_71_54","chapterId":"ch_work_han_thu_71","textTraditional":"〔一０〕師古曰：「乘，登也，登而守之。」","sentenceOrder":54},
  {"id":"s_work_han_thu_71_55","chapterId":"ch_work_han_thu_71","textTraditional":"〔一一〕師古曰：「震，動也。讋，失（失）氣也。讋音之涉反。」","sentenceOrder":55},
  {"id":"s_work_han_thu_71_56","chapterId":"ch_work_han_thu_71","textTraditional":"湯客田甲雖賈人，有賢操，〔一〕始湯為小吏，與錢通，〔二〕及為大吏，而甲所以責湯行義，有烈士之風。","sentenceOrder":56},
  {"id":"s_work_han_thu_71_57","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「操謂所執持之志行也。音千到反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_71_58","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「為小吏之時與田甲為錢財之交。」","sentenceOrder":58},
  {"id":"s_work_han_thu_71_59","chapterId":"ch_work_han_thu_71","textTraditional":"湯為御史大夫七歲，敗。","sentenceOrder":59},
  {"id":"s_work_han_thu_71_60","chapterId":"ch_work_han_thu_71","textTraditional":"河東人李文，故嘗與湯有隙，已而為御史中丞，薦數從中文事有可以傷湯者，不能為地。〔一〕湯有所愛史魯謁居，知湯弗平，使人上飛變告文姦事。〔二〕事下湯，湯治論殺文，而湯心知謁居為之。上問：「變事從跡安起？」〔三〕湯陽驚曰：「此殆文故人怨之。」〔四〕謁居病臥閭里主人，湯自往視病，為謁居摩足。趙國以冶鑄為業，王數訟鐵官事，湯常排趙王。趙王求湯陰事。謁居嘗案趙王，趙王怨之，并上書告：「湯大臣也，史謁居有病，湯至為摩足，疑與為大姦。」事下廷尉。謁居病死，事連其弟，弟繫導官。〔五〕湯亦治它囚導官，見謁居弟，欲陰為之，而陽不省。〔六〕謁居弟不知而怨湯，使人上書，告湯與謁居謀，（兵）〔共〕變李文。事下減宣。宣嘗與湯有隙，及得此事，窮竟其事，未奏也。會人有盜發孝文園瘞錢，〔七〕丞相青翟朝，與湯約俱謝，〔八〕至前，〔九〕湯念獨丞相以四時行園，當謝，湯無與也，不謝。〔一０〕丞相謝，上使御史案其事。湯欲致其文丞相見知，〔一一〕丞相患之。三長史皆害湯，欲陷之。〔一二〕","sentenceOrder":60},
  {"id":"s_work_han_thu_71_61","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　服虔曰：「薦，藉也。文與湯故有隙，已而為御史中丞，藉己在內臺，中文書有可用傷湯者因會致之，不能為湯作道地。」蘇林曰：「薦，仍也。」師古曰：「薦、數義同，蘇說是也。數數在中，其有文書事可用傷湯者，不為作道地也。薦音在見反。數音所角反。大雅雲漢之詩曰『饑饉薦臻』，字亦如此。」","sentenceOrder":61},
  {"id":"s_work_han_thu_71_62","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「飛變猶言急變也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_71_63","chapterId":"ch_work_han_thu_71","textTraditional":"〔三〕　師古曰：「從讀曰蹤。」","sentenceOrder":63},
  {"id":"s_work_han_thu_71_64","chapterId":"ch_work_han_thu_71","textTraditional":"〔四〕　師古曰：「殆，近也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_71_65","chapterId":"ch_work_han_thu_71","textTraditional":"〔五〕　蘇林曰：「漢儀注獄二十六所，導官無獄也。」師古曰：「蘇說非也。導，擇也。以主擇米，故曰導官。事見百官表。時或以諸獄皆滿，故權寄在此署繫之，非本獄所也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_71_66","chapterId":"ch_work_han_thu_71","textTraditional":"〔六〕　師古曰：「省，視也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_71_67","chapterId":"ch_work_han_thu_71","textTraditional":"〔七〕　如淳曰：「瘞，埋也，埋錢於園陵以送死也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_71_68","chapterId":"ch_work_han_thu_71","textTraditional":"〔八〕　師古曰：「將入朝之時為此要約。」","sentenceOrder":68},
  {"id":"s_work_han_thu_71_69","chapterId":"ch_work_han_thu_71","textTraditional":"〔九〕　師古曰：「至天子之前。」","sentenceOrder":69},
  {"id":"s_work_han_thu_71_70","chapterId":"ch_work_han_thu_71","textTraditional":"〔一０〕師古曰：「行音下更反。與讀曰豫。無豫謂不干其事也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_71_71","chapterId":"ch_work_han_thu_71","textTraditional":"〔一一〕張晏曰：「見知故縱，以其罪罪之也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_71_72","chapterId":"ch_work_han_thu_71","textTraditional":"〔一二〕師古曰：「百官表丞相有兩長史，今此云三者，蓋以守者，非正員也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_71_73","chapterId":"ch_work_han_thu_71","textTraditional":"始，長史朱買臣素怨湯，語在其傳。王朝，齊人，以術至右內史。邊通學短長，〔一〕剛暴人也，官至濟南相。故皆居湯右，〔二〕已而失官，守長史，詘體於湯。〔三〕湯數行丞相事，知此三長史素貴，常陵折之，故三長史合謀曰：「始湯約與君謝，已而賣君；今欲劾君以宗廟事，此欲代君耳。吾知湯陰事。」使吏捕案湯左田信等，〔四〕曰湯且欲為請奏，信輒先知之，居物致富，與湯分之。〔五〕及它姦事。事辭頗聞。〔六〕上問湯曰：「吾所為，賈人輒知，益居其物，〔七〕是類有以吾謀告之者。」〔八〕湯不謝，又陽驚曰：「固宜有。」減宣亦奏謁居事。上以湯懷詐面欺，〔九〕使使八輩簿責湯。〔一０〕湯具自道無此，不服。於是上使趙禹責湯。禹至，讓湯曰：〔一一〕「君何不知分也！〔一二〕君所治，夷滅者幾何人矣！〔一三〕今人言君皆有狀，天子重致君獄，〔一四〕欲令君自為計，〔一五〕何多以對為？」〔一六〕湯乃為書謝曰：「湯無尺寸之功，起刀筆吏，陛下幸致位三公，無以塞責。〔一七〕然謀陷湯者，三長史也。」遂自殺。","sentenceOrder":73},
  {"id":"s_work_han_thu_71_74","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　（師古）〔應劭〕曰：「短長術興於六國時，長短其語，隱謬用相激怒也。」張晏曰：「蘇秦、張儀之謀，趣彼為短，歸此為長，戰國策名長短術也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_71_75","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「言舊在湯上。」","sentenceOrder":75},
  {"id":"s_work_han_thu_71_76","chapterId":"ch_work_han_thu_71","textTraditional":"〔三〕　師古曰：「謂拜伏也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_71_77","chapterId":"ch_work_han_thu_71","textTraditional":"〔四〕　李奇曰：「左，證左也。」師古曰：「謂之左者，言除罪人正身之外，又取其左右者考問也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_71_78","chapterId":"ch_work_han_thu_71","textTraditional":"〔五〕　服虔曰：「居謂儲也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_71_79","chapterId":"ch_work_han_thu_71","textTraditional":"〔六〕　師古曰：「聞於天子也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_71_80","chapterId":"ch_work_han_thu_71","textTraditional":"〔七〕　師古曰：「益，多也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_71_81","chapterId":"ch_work_han_thu_71","textTraditional":"〔八〕　師古曰：「類，似也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_71_82","chapterId":"ch_work_han_thu_71","textTraditional":"〔九〕　師古曰：「對面欺誣也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_71_83","chapterId":"ch_work_han_thu_71","textTraditional":"〔一０〕蘇林曰：「簿音主簿之簿。簿，悉責也。」師古曰：「以文簿次第一一責之。」","sentenceOrder":83},
  {"id":"s_work_han_thu_71_84","chapterId":"ch_work_han_thu_71","textTraditional":"〔一一〕師古曰：「讓亦責也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_71_85","chapterId":"ch_work_han_thu_71","textTraditional":"〔一二〕師古曰：「分音扶問反。」","sentenceOrder":85},
  {"id":"s_work_han_thu_71_86","chapterId":"ch_work_han_thu_71","textTraditional":"〔一三〕師古曰：「幾音居起反。」","sentenceOrder":86},
  {"id":"s_work_han_thu_71_87","chapterId":"ch_work_han_thu_71","textTraditional":"〔一四〕師古曰：「重猶難也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_71_88","chapterId":"ch_work_han_thu_71","textTraditional":"〔一五〕師古曰：「言引決也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_71_89","chapterId":"ch_work_han_thu_71","textTraditional":"〔一六〕師古曰：「言何用多對。」","sentenceOrder":89},
  {"id":"s_work_han_thu_71_90","chapterId":"ch_work_han_thu_71","textTraditional":"〔一七〕師古曰：「塞，當也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_71_91","chapterId":"ch_work_han_thu_71","textTraditional":"湯死，家產直不過五百金，皆所得奉賜，〔一〕無它贏。〔二〕昆弟諸子欲厚葬湯，湯母曰：「湯為天子大臣，被惡言而死，〔三〕何厚葬為！」載以牛車，有棺而無槨。上聞之，曰：「非此母不生此子。」乃盡按誅三長史。丞相青翟自殺。出田信。上惜湯，復稍進其子安世。","sentenceOrder":91},
  {"id":"s_work_han_thu_71_92","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕師古曰：「奉音扶用反。」","sentenceOrder":92},
  {"id":"s_work_han_thu_71_93","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「贏，餘也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_71_94","chapterId":"ch_work_han_thu_71","textTraditional":"〔三〕　師古曰：「被，加也，音皮義反。」","sentenceOrder":94},
  {"id":"s_work_han_thu_71_95","chapterId":"ch_work_han_thu_71","textTraditional":"安世字子孺，少以父任為郎。用善書給事尚書，〔一〕精力於職，休沐未嘗出。上行幸河東，嘗亡書三篋，詔問莫能知，唯安世識之，〔二〕具作其事。後購求得書，以相校無所遺失。上奇其材，擢為尚書令，遷光祿大夫。","sentenceOrder":95},
  {"id":"s_work_han_thu_71_96","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「於尚書中給事也。給，供也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_71_97","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「識，記也，音式志反。」","sentenceOrder":97},
  {"id":"s_work_han_thu_71_98","chapterId":"ch_work_han_thu_71","textTraditional":"昭帝即位，大將軍霍光秉政，以安世篤行，〔一〕光親重之。會左將軍上官桀父子及御史大夫桑弘羊皆與燕王、蓋主謀反誅，光以朝無舊臣，白用安世為右將軍光祿勳，以自副焉。久之，天子下詔曰：「右將軍光祿勳安世輔政宿衛，肅敬不怠，十有三年，咸以康寧。夫親親任賢，唐虞之道也，其封安世為富平侯。」","sentenceOrder":98},
  {"id":"s_work_han_thu_71_99","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「篤，厚也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_71_100","chapterId":"ch_work_han_thu_71","textTraditional":"明年，昭帝崩，未葬，大將軍光白太后，徙安世為車騎將軍，與共徵立昌邑王。王行淫亂，光復與安世謀廢王，尊立宣帝。帝初即位，褒賞大臣，〔下〕詔曰：「夫褒有德，賞有功，古今之通義也。車騎將軍光祿勳富平侯安世，宿衛忠正，宣德明恩，勤勞國家，守職秉義，以安宗廟，其益封萬六百戶，功次大將軍光。」安世子千秋、延壽、彭祖，皆中郎將侍中。","sentenceOrder":100},
  {"id":"s_work_han_thu_71_101","chapterId":"ch_work_han_thu_71","textTraditional":"大將軍光薨後數月，御史大夫魏相上封事曰：「聖王褒有德以懷萬方，〔一〕顯有功以勸百寮，是以朝廷尊榮，天下鄉風。〔二〕國家承祖宗之業，制諸侯之重，新失大將軍，宜宣章盛德以示天下，顯明功臣以填藩國。〔三〕毋空大位，以塞爭權，〔四〕所以安社稷絕未萌也。〔五〕車騎將軍安世事孝武皇帝三十餘年，忠信謹厚，勤勞政事，夙夜不怠，與大將軍定策，天下受其福，國家重臣也，宜尊其位，以為大將軍，毋令領光祿勳事，使專精神，憂念天下，思惟得失。安世子延壽重厚，可以為光祿勳，領宿衛臣。」上亦欲用之。安世聞指，懼不敢當，請間求見，免冠頓首曰：「老臣耳妄聞，言之為先事，不言情不達，〔六〕誠自量不足以居大位，繼大將軍後。唯天子財哀，以全老臣之命。」〔七〕上笑曰：「君言泰謙。君而不可，尚誰可者！」〔八〕安世深辭弗能得。後數日，竟拜為大司馬車騎將軍，領尚書事。數月，罷車騎將軍屯兵，更為衛將軍，兩宮衛尉，城門、北軍兵屬焉。","sentenceOrder":101},
  {"id":"s_work_han_thu_71_102","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「懷，來也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_71_103","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":103},
  {"id":"s_work_han_thu_71_104","chapterId":"ch_work_han_thu_71","textTraditional":"〔三〕　師古曰：「填音竹刃反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_71_105","chapterId":"ch_work_han_thu_71","textTraditional":"〔四〕　師古曰：「大臣位空，則起爭奪之權也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_71_106","chapterId":"ch_work_han_thu_71","textTraditional":"〔五〕　師古曰：「未萌，謂變故未生者也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_71_107","chapterId":"ch_work_han_thu_71","textTraditional":"〔六〕　師古曰：「事未施行而遽言之，故曰先事也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_71_108","chapterId":"ch_work_han_thu_71","textTraditional":"〔七〕　師古曰：「財與裁同。」","sentenceOrder":108},
  {"id":"s_work_han_thu_71_109","chapterId":"ch_work_han_thu_71","textTraditional":"〔八〕　師古曰：「言君尚不可，誰更可也！」","sentenceOrder":109},
  {"id":"s_work_han_thu_71_110","chapterId":"ch_work_han_thu_71","textTraditional":"時霍光子禹為右將軍，上亦以禹為大司馬，罷其右將軍屯兵，以虛尊加之，而實奪其眾。後歲餘，禹謀反，夷宗族，安世素小心畏忌，已內憂矣。〔一〕其女孫敬為霍氏外屬婦，〔二〕當相坐，安世瘦懼，形於顏色。〔三〕上怪而憐之，以問左右，乃赦敬，以慰其意。安世浸恐。〔四〕職典樞機，以謹慎周密自著，外內無間。〔五〕每定大政，已決，輒移病出，〔六〕聞有詔令，乃驚，使吏之丞相府問焉。自朝廷大臣莫知其與議也。〔七〕","sentenceOrder":110},
  {"id":"s_work_han_thu_71_111","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「忌者，戒盈滿之禍。」","sentenceOrder":111},
  {"id":"s_work_han_thu_71_112","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「女孫，即今所謂孫女也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_71_113","chapterId":"ch_work_han_thu_71","textTraditional":"〔三〕　師古曰：「形，見也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_71_114","chapterId":"ch_work_han_thu_71","textTraditional":"〔四〕　師古曰：「浸，益也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_71_115","chapterId":"ch_work_han_thu_71","textTraditional":"〔五〕　師古曰：「著，明也。間，隙也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_71_116","chapterId":"ch_work_han_thu_71","textTraditional":"〔六〕　師古曰：「移病，謂移書言病也。一曰以病而移居。」","sentenceOrder":116},
  {"id":"s_work_han_thu_71_117","chapterId":"ch_work_han_thu_71","textTraditional":"〔七〕　師古曰：「與讀曰豫。」","sentenceOrder":117},
  {"id":"s_work_han_thu_71_118","chapterId":"ch_work_han_thu_71","textTraditional":"嘗有所薦，其人來謝，安世大恨，以為舉賢達能，豈有私謝邪？絕勿復為通。〔一〕有郎功高不調，〔二〕自言，安世應曰：「君之功高，明主所知。人臣執事，何長短而自言乎！」絕不許。已而郎果遷。〔三〕莫府長史遷，辭去之官，安世問以過失。〔四〕長史曰：「將軍為明主股肱，而士無所進，論者以為譏。」安世曰：「明主在上，賢不肖較然，〔五〕臣下自修而已，何知士而薦之？」其欲匿名跡遠權勢如此。〔六〕","sentenceOrder":118},
  {"id":"s_work_han_thu_71_119","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「有欲謝者，皆不通也。一曰告此人而絕之，更不與相見也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_71_120","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「調，選也，音徒釣反。」","sentenceOrder":120},
  {"id":"s_work_han_thu_71_121","chapterId":"ch_work_han_thu_71","textTraditional":"〔三〕　師古曰：「安世外陽距之，而實令其遷。」","sentenceOrder":121},
  {"id":"s_work_han_thu_71_122","chapterId":"ch_work_han_thu_71","textTraditional":"〔四〕　師古曰：「問己有何失。」","sentenceOrder":122},
  {"id":"s_work_han_thu_71_123","chapterId":"ch_work_han_thu_71","textTraditional":"〔五〕　師古曰：「較，明貌。」","sentenceOrder":123},
  {"id":"s_work_han_thu_71_124","chapterId":"ch_work_han_thu_71","textTraditional":"〔六〕　師古曰：「遠，離也，音于萬反。」","sentenceOrder":124},
  {"id":"s_work_han_thu_71_125","chapterId":"ch_work_han_thu_71","textTraditional":"為光祿勳，郎有醉小便殿上，主事白行法，安世曰：「何以知其不反水漿邪？〔一〕如何以小過成罪！」郎淫官婢，婢兄自言，安世曰：「奴以恚怒，誣汙衣冠。」（自）〔告〕署適奴。〔二〕其隱人過失，皆此類也。","sentenceOrder":125},
  {"id":"s_work_han_thu_71_126","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「反讀曰翻。」","sentenceOrder":126},
  {"id":"s_work_han_thu_71_127","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「適讀曰謫。」","sentenceOrder":127},
  {"id":"s_work_han_thu_71_128","chapterId":"ch_work_han_thu_71","textTraditional":"安世自見父子尊顯，懷不自安，為子延壽求出補吏，上以為北地太守。歲餘，上閔安世年老，復徵延壽為左曹太僕。","sentenceOrder":128},
  {"id":"s_work_han_thu_71_129","chapterId":"ch_work_han_thu_71","textTraditional":"初，安世兄賀幸於衛太子，太子敗，賓客皆誅，安世為賀上書，得下蠶室。〔一〕後為掖庭令，而宣帝以皇曾孫收養掖庭。賀內傷太子無辜，而曾孫孤幼，所以視養拊循，恩甚密焉。及曾孫壯大，賀教書，令受詩，為取許妃，以家財聘之。曾孫數有徵怪，〔二〕語在宣紀。賀聞知，為安世道之，稱其材美。安世輒絕止，以為少主在上，不宜稱述曾孫。及宣帝即位，而賀已死。上謂安世曰：「掖（廷）〔庭〕令平生稱我，將軍止之，是也。」上追思賀恩，欲封其冢為恩德侯，置守冢二百家。〔三〕賀有一子蚤死，〔四〕無子，子安世小男彭祖。〔五〕彭祖又小與上同席研書，指欲封之，先賜爵關內侯。故安世深辭賀封，又求損守冢戶數，稍減至三十戶。上曰：「吾自為掖（廷）〔庭〕令，非為將軍也。」安世乃止，不敢復言。遂下詔曰：「其為故掖（廷）〔庭〕令張賀置守冢三十家。」上自處置其里〔六〕，居冢西鬥雞翁舍南，上少時所嘗游處也。明年，復下詔曰：「朕微眇時，故掖（廷）〔庭〕令張賀輔道朕躬，〔七〕修文學經術，恩惠卓異，厥功茂焉。詩云：『無言不讎，無德不報。』〔八〕其封賀弟子侍中關內侯彭祖為陽都侯，賜賀諡曰陽都哀侯。」時賀有孤孫霸，年七歲，拜為散騎中郎將，賜爵關內侯，食邑三百戶。安世以父子封侯，在位大盛，乃辭祿。詔都內別臧張氏無名錢以百萬數。〔九〕","sentenceOrder":129},
  {"id":"s_work_han_thu_71_130","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「謂腐刑也。凡養蠶者，欲其溫而早成，故為密室蓄火以置之。而新腐刑亦有中風之患，須入密室乃得以全，因呼為蠶室耳。」","sentenceOrder":130},
  {"id":"s_work_han_thu_71_131","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「徵，證也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_71_132","chapterId":"ch_work_han_thu_71","textTraditional":"〔三〕　師古曰：「身死追封，故云封冢也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_71_133","chapterId":"ch_work_han_thu_71","textTraditional":"〔四〕　師古曰：「蚤，古早字。」","sentenceOrder":133},
  {"id":"s_work_han_thu_71_134","chapterId":"ch_work_han_thu_71","textTraditional":"〔五〕　師古曰：「言養以為子。」","sentenceOrder":134},
  {"id":"s_work_han_thu_71_135","chapterId":"ch_work_han_thu_71","textTraditional":"〔六〕　師古曰：「處，安也，音昌汝反。」","sentenceOrder":135},
  {"id":"s_work_han_thu_71_136","chapterId":"ch_work_han_thu_71","textTraditional":"〔七〕　師古曰：「道讀曰導。」","sentenceOrder":136},
  {"id":"s_work_han_thu_71_137","chapterId":"ch_work_han_thu_71","textTraditional":"〔八〕　師古曰：「大雅抑之詩。」","sentenceOrder":137},
  {"id":"s_work_han_thu_71_138","chapterId":"ch_work_han_thu_71","textTraditional":"〔九〕　文穎曰：「都內，主臧官也。」張晏曰：「安世以還官，官不簿也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_71_139","chapterId":"ch_work_han_thu_71","textTraditional":"安世尊為公侯，食邑萬戶，然身衣弋綈，〔一〕夫人自紡績，家童七百人，皆有手技作事，內治產業，累積纖微，是以能殖其貨〔二〕，富於大將軍光。天子甚尊憚大將軍，然內親安世，心密於光焉。","sentenceOrder":139},
  {"id":"s_work_han_thu_71_140","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「弋，黑色也。綈，厚繒也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_71_141","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「殖，生也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_71_142","chapterId":"ch_work_han_thu_71","textTraditional":"元康四年春，安世病，上疏歸侯，乞骸骨。天子報曰：「將軍年老被病，朕甚閔之。雖不能視事，折衝萬里，君先帝大臣，明於治亂，朕所不及，得數問焉，〔一〕何感而上書歸衛將軍富平侯印？〔二〕薄朕忘故，〔三〕非所望也！願將軍強餐食，近醫藥，專精神，以輔天年。」安世復強起視事，至秋薨。天子贈印綬，送以輕車介士，〔四〕諡曰敬侯。賜塋杜東，〔五〕將作穿復土，起冢祠堂。子延壽嗣。","sentenceOrder":142},
  {"id":"s_work_han_thu_71_143","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「言意所不及者，即以問君也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_71_144","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「感，恨也，音胡闇反。」","sentenceOrder":144},
  {"id":"s_work_han_thu_71_145","chapterId":"ch_work_han_thu_71","textTraditional":"〔三〕　蘇林曰：「本望君重於此也。」師古曰：「蘇說非也。薄猶嫌也，君意嫌朕遺忘故舊，而求去也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_71_146","chapterId":"ch_work_han_thu_71","textTraditional":"〔四〕　師古曰：「輕車，古之戰車。續漢書曰『彫朱輪輿，不巾不蓋，菑矛戟幢（也）麾，〈斑，中“文改車”〉弩。』介士謂甲士也。菑，插也。〈斑，中“文改車”〉，皮篋盛弩也。菑音側事反。〈斑，中“文改車”〉音服。」","sentenceOrder":146},
  {"id":"s_work_han_thu_71_147","chapterId":"ch_work_han_thu_71","textTraditional":"〔五〕　師古曰：「塋，冢地也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_71_148","chapterId":"ch_work_han_thu_71","textTraditional":"延壽已歷位九卿，既嗣侯，國在陳留，別邑在魏郡，租入歲千餘萬。延壽自以身無功德，何以能久堪先人大國，數上書讓減戶邑，又因弟陽都侯彭祖口陳至誠。天子以為有讓，乃徙封平原，并一國，戶口如故，而租稅減半。薨，諡曰愛侯。子勃嗣，為散騎諫大夫。","sentenceOrder":148},
  {"id":"s_work_han_thu_71_149","chapterId":"ch_work_han_thu_71","textTraditional":"元帝初即位，詔列侯舉茂材，勃舉太官獻丞陳湯。〔一〕湯有罪，勃坐削戶二百，會薨，故賜諡曰繆侯。〔二〕後湯立功西域，世以勃為知人。子臨嗣。","sentenceOrder":149},
  {"id":"s_work_han_thu_71_150","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　蘇林曰：「獻丞，主貢獻物也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_71_151","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「以其所舉不得人，故加惡諡。（謬）〔繆〕者，妄也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_71_152","chapterId":"ch_work_han_thu_71","textTraditional":"臨亦謙儉，每登閣殿，常歎曰：「桑、霍為我戒，豈不厚哉！」〔一〕且死，分施宗族故舊，〔二〕薄葬不起墳。臨尚敬武公主〔三〕。薨，子放嗣。","sentenceOrder":152},
  {"id":"s_work_han_thu_71_153","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「桑，桑弘羊也。霍，霍禹也。言以驕奢致禍也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_71_154","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「言將死之時，多以財分施也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_71_155","chapterId":"ch_work_han_thu_71","textTraditional":"〔三〕　文穎曰：「成帝姊也。」（陳）〔臣〕瓚曰：「敬武公主是元帝姊也。」師古曰：「二說皆非也。薛宣傳云主怒曰：『嫂何以取妺殺之？』既謂元后為嫂，是則元帝妺也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_71_156","chapterId":"ch_work_han_thu_71","textTraditional":"鴻嘉中，上欲遵武帝故事，與近臣游宴，放以公主子開敏得幸。放取皇后弟平恩侯許嘉女，上為放供張，〔一〕賜甲第，充以乘輿服飾，號為天子取婦，皇后嫁女。大官私官並供（具）〔其〕第，〔二〕兩宮使者冠蓋不絕，賞賜以千萬數。放為侍中中郎將，監平樂屯兵，置莫府，儀比將軍。與上臥起，寵愛殊絕，常從為微行出游，北至甘泉，南至長楊、五莋，〔三〕鬥雞走馬長安中，積數年。","sentenceOrder":156},
  {"id":"s_work_han_thu_71_157","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「供音居用反。張音竹亮反。」","sentenceOrder":157},
  {"id":"s_work_han_thu_71_158","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　服虔曰：「私官，皇后之官也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_71_159","chapterId":"ch_work_han_thu_71","textTraditional":"〔三〕　師古曰：「莋與柞同。」","sentenceOrder":159},
  {"id":"s_work_han_thu_71_160","chapterId":"ch_work_han_thu_71","textTraditional":"是時上諸舅皆害其寵，白太后。太后以上春秋富，動作不節，甚以過放。〔一〕時數有災異，議者歸咎放等。於是丞相宣、御史大夫方進〔二〕奏：「放驕蹇縱恣，奢淫不制。前侍御史修等四人奉使至放家逐名捕賊，〔三〕時放見在，奴從者閉門設兵弩射吏，距使者不肯內。知男子李游君欲獻女，使樂府音監景武強求不得，〔四〕使奴康等之其家，賊傷三人。又以縣官事怨樂府游徼莽，〔五〕而使大奴駿等四十餘人群黨盛兵弩，白晝入樂府攻射官寺，縛束長吏子弟，斫破器物，宮中皆奔走伏匿。〔六〕莽自髡鉗，衣赭衣，及守令史調等皆徒跣叩頭謝放，放乃止。奴從者支屬並乘權勢為暴虐，至求吏妻不得，殺其夫，或恚一人，妄殺其親屬，輒亡入放（弟）〔第〕，不得，幸得勿治。放行輕薄，連犯大惡，有感動陰陽之咎，為臣不忠首，〔七〕罪名雖顯，前蒙恩。驕逸悖理，〔八〕與背畔無異，臣子之惡，莫大於是，不宜宿衛在位。臣請免放歸國，以銷眾邪之萌，厭海內之心。」〔九〕","sentenceOrder":160},
  {"id":"s_work_han_thu_71_161","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「以放為罪過。」","sentenceOrder":161},
  {"id":"s_work_han_thu_71_162","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「薛宣、翟方進。」","sentenceOrder":162},
  {"id":"s_work_han_thu_71_163","chapterId":"ch_work_han_thu_71","textTraditional":"〔三〕　劉德曰：「謂詔捕罪人有名者也。」","sentenceOrder":163},
  {"id":"s_work_han_thu_71_164","chapterId":"ch_work_han_thu_71","textTraditional":"〔四〕　孟康曰：「音監，監主樂人也。姓景名武。」","sentenceOrder":164},
  {"id":"s_work_han_thu_71_165","chapterId":"ch_work_han_thu_71","textTraditional":"〔五〕　師古曰：「樂府之游徼名莽。」","sentenceOrder":165},
  {"id":"s_work_han_thu_71_166","chapterId":"ch_work_han_thu_71","textTraditional":"〔六〕　師古曰：「犇，古奔字。」","sentenceOrder":166},
  {"id":"s_work_han_thu_71_167","chapterId":"ch_work_han_thu_71","textTraditional":"〔七〕　師古曰：「不忠之罪放為首。」","sentenceOrder":167},
  {"id":"s_work_han_thu_71_168","chapterId":"ch_work_han_thu_71","textTraditional":"〔八〕　師古曰：「悖，乖也，音布內反。」","sentenceOrder":168},
  {"id":"s_work_han_thu_71_169","chapterId":"ch_work_han_thu_71","textTraditional":"〔九〕　師古曰：「萌，始生者也。厭，滿也，音一豔反。」","sentenceOrder":169},
  {"id":"s_work_han_thu_71_170","chapterId":"ch_work_han_thu_71","textTraditional":"上不得已，〔一〕左遷放為北地都尉。數月，復徵入侍中。太后以放為言，出放為天水屬國都尉。永始、元延間，比年日蝕，〔二〕故久不還放，璽書勞問不絕。居歲餘，徵放歸第視母公主疾。數月，主有瘳，出放為河東都尉。上雖愛放，然上迫太后，下用大臣，故常涕泣而遣之。後復徵放為侍中光祿大夫，秩中二千石。歲餘，丞相方進復奏放，上不得已，免放，賜錢五百萬，遣就國。數月，成帝崩，放思慕哭泣而死。","sentenceOrder":170},
  {"id":"s_work_han_thu_71_171","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　師古曰：「已，止也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_71_172","chapterId":"ch_work_han_thu_71","textTraditional":"〔二〕　師古曰：「比，頻也。」","sentenceOrder":172},
  {"id":"s_work_han_thu_71_173","chapterId":"ch_work_han_thu_71","textTraditional":"初，安世長子千秋與霍光子禹俱為中郎將，將兵隨度遼將軍范明友擊烏桓。還，謁大將軍光，問千秋戰鬥方略，山川形勢，千秋口對兵事，畫地成圖，無所忘失。光復問禹，禹不能記，曰：「皆有文書。」光由是賢千秋，以禹為不材，歎曰：「霍氏世衰，張氏興矣！」及禹誅滅，而安世子孫相繼，自宣、元以來為侍中、中常侍、諸曹散騎、列校尉者凡十餘人。功臣之世，唯有金氏、張氏，親近寵貴，比於外戚。","sentenceOrder":173},
  {"id":"s_work_han_thu_71_174","chapterId":"ch_work_han_thu_71","textTraditional":"放子純嗣侯，恭儉自修，明習漢家制度故事，有敬侯遺風。王莽時不失爵，建武中歷位至大司空，更封富平之別鄉為武始侯。","sentenceOrder":174},
  {"id":"s_work_han_thu_71_175","chapterId":"ch_work_han_thu_71","textTraditional":"張湯本居杜陵，安世武、昭、宣世輒隨陵，〔一〕凡三徙，復還杜陵。","sentenceOrder":175},
  {"id":"s_work_han_thu_71_176","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　服虔曰：「隨所事帝，徙處其陵也。」","sentenceOrder":176},
  {"id":"s_work_han_thu_71_177","chapterId":"ch_work_han_thu_71","textTraditional":"贊曰：馮商稱張湯之先與留侯同祖，而司馬遷不言，故闕焉〔一〕。漢興以來，侯者百數，保國持寵，未有若富平者也。湯雖酷烈，及身蒙咎，其推賢揚善，固宜有後。安世履道，滿而不溢。賀之陰德，亦有助云。","sentenceOrder":177},
  {"id":"s_work_han_thu_71_178","chapterId":"ch_work_han_thu_71","textTraditional":"〔一〕　如淳曰：「班固目錄馮商，長安人，成帝時以能屬書待詔金馬門，受詔續太史公書十餘篇。」師古曰：「劉歆七略云商陽陵人，治易，事五鹿充宗，能屬文，博通強記，與孟柳俱待詔，頗序列傳，未卒，會病死。」","sentenceOrder":178},
  {"id":"s_work_han_thu_71_179","chapterId":"ch_work_han_thu_71","textTraditional":"校勘記","sentenceOrder":179},
  {"id":"s_work_han_thu_71_180","chapterId":"ch_work_han_thu_71","textTraditional":"二六三九頁　五行　固為臣議，如（此）上責臣，〔八〕　注〔八〕原在「此」字下。王先謙說「此」是衍文。按史記無「此」字。顏注正解「如上責臣」，當在「臣」字下。","sentenceOrder":180},
  {"id":"s_work_han_thu_71_181","chapterId":"ch_work_han_thu_71","textTraditional":"二六四二頁　三行　臣固知湯之（為）詐忠。　景祐、殿本都無「為」字。","sentenceOrder":181},
  {"id":"s_work_han_thu_71_182","chapterId":"ch_work_han_thu_71","textTraditional":"二六四三頁　一行　失（失）氣也。　王先謙說「失」字誤衍。按殿本無。","sentenceOrder":182},
  {"id":"s_work_han_thu_71_183","chapterId":"ch_work_han_thu_71","textTraditional":"二六四三頁一三行　告湯與謁居謀，（兵）〔共〕變李文。　景祐、殿本都作「共」，此誤。","sentenceOrder":183},
  {"id":"s_work_han_thu_71_184","chapterId":"ch_work_han_thu_71","textTraditional":"二六四五頁一一行　（師古）〔應劭〕曰：　景祐、殿本都作「應劭」。王先謙說作「應劭」是。","sentenceOrder":184},
  {"id":"s_work_han_thu_71_185","chapterId":"ch_work_han_thu_71","textTraditional":"二六四七頁一四行　帝初即位，褒賞大臣，〔下〕詔曰：　景祐、殿本都有「下」字。","sentenceOrder":185},
  {"id":"s_work_han_thu_71_186","chapterId":"ch_work_han_thu_71","textTraditional":"二六五０頁一四行　（自）〔告〕署適奴。　景祐、殿本都作「告」。郭嵩燾說作「告」是。","sentenceOrder":186},
  {"id":"s_work_han_thu_71_187","chapterId":"ch_work_han_thu_71","textTraditional":"二六五一頁　九行　掖（廷）〔庭〕令平生稱我，　殿本作「庭」，下同。王先謙說「廷」字誤。按景祐本亦誤。","sentenceOrder":187},
  {"id":"s_work_han_thu_71_188","chapterId":"ch_work_han_thu_71","textTraditional":"二六五三頁一０行　菑矛戟幢（也）麾，〈斑，中“文改車”〉弩。　宋祁說別本、浙本無「也」字。王先謙說無「也」字是。","sentenceOrder":188},
  {"id":"s_work_han_thu_71_189","chapterId":"ch_work_han_thu_71","textTraditional":"二六五四頁　五行　（謬）〔繆〕者，妄也。　景祐、殿本都作「繆」。","sentenceOrder":189},
  {"id":"s_work_han_thu_71_190","chapterId":"ch_work_han_thu_71","textTraditional":"二六五四頁一０行　（陳）〔臣〕瓚曰：　景祐、殿、局本都作「臣」，此誤。","sentenceOrder":190},
  {"id":"s_work_han_thu_71_191","chapterId":"ch_work_han_thu_71","textTraditional":"二六五四頁一三行　大官私官並供（具）〔其〕第，　景祐、殿、局本都作「其」，此誤。","sentenceOrder":191},
  {"id":"s_work_han_thu_71_192","chapterId":"ch_work_han_thu_71","textTraditional":"二六五五頁一二行　輒亡入放（弟）〔第〕，　王先謙說殿本作「第」是。","sentenceOrder":192},
  {"id":"s_work_han_thu_72_1","chapterId":"ch_work_han_thu_72","textTraditional":"杜周，南陽杜衍人也。義縱為南陽太守，以周為爪牙，薦之張湯，為廷尉史。使案邊失亡，〔一〕所論殺甚多。奏事中意，任用〔二〕，與減宣更為中丞者十餘歲。〔三〕","sentenceOrder":1},
  {"id":"s_work_han_thu_72_2","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　文穎曰：「邊卒多亡也。或曰，郡縣主守有所亡失也。」師古曰：「此說皆非也。謂因虜入為寇，而失人畜甲兵倉廩者也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_72_3","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　師古曰：「以奏事當天子之意旨，故被任用也。中音竹仲反。」","sentenceOrder":3},
  {"id":"s_work_han_thu_72_4","chapterId":"ch_work_han_thu_72","textTraditional":"〔三〕　師古曰：「更，互也，音工衡反。」","sentenceOrder":4},
  {"id":"s_work_han_thu_72_5","chapterId":"ch_work_han_thu_72","textTraditional":"周少言重遲，〔一〕而內深次骨。〔二〕宣為左內史，周為廷尉，其治大抵放張湯，〔三〕而善候司。〔四〕上所欲擠者，因而陷之；〔五〕上所欲釋，久繫待問而微見其冤狀。〔六〕客有謂周曰：「君為天下決平，不循三尺法，〔七〕專以人主意指為獄，獄者固如是乎？」〔八〕周曰：「三尺安出哉？〔九〕前主所是著為律，後主所是疏為令；〔一０〕當時為是，何古之法乎！」〔一一〕","sentenceOrder":5},
  {"id":"s_work_han_thu_72_6","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「遲謂性非敏速也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_72_7","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　李奇曰：「其用法深刻至骨。」","sentenceOrder":7},
  {"id":"s_work_han_thu_72_8","chapterId":"ch_work_han_thu_72","textTraditional":"〔三〕　師古曰：「大抵，大歸也。放，依也，音甫往反。」","sentenceOrder":8},
  {"id":"s_work_han_thu_72_9","chapterId":"ch_work_han_thu_72","textTraditional":"〔四〕　師古曰：「觀望天子意。」","sentenceOrder":9},
  {"id":"s_work_han_thu_72_10","chapterId":"ch_work_han_thu_72","textTraditional":"〔五〕　孟康曰：「擠音躋。」師古曰：「擠，墜也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_72_11","chapterId":"ch_work_han_thu_72","textTraditional":"〔六〕　師古曰：「見，顯也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_72_12","chapterId":"ch_work_han_thu_72","textTraditional":"〔七〕　孟康曰：「以三尺竹簡書法律也。」師古曰：「循，因也，順也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_72_13","chapterId":"ch_work_han_thu_72","textTraditional":"〔八〕　師古曰：「言不當然也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_72_14","chapterId":"ch_work_han_thu_72","textTraditional":"〔九〕　師古曰：「安猶焉也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_72_15","chapterId":"ch_work_han_thu_72","textTraditional":"〔一０〕師古曰：「著謂明表也。疏謂分條也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_72_16","chapterId":"ch_work_han_thu_72","textTraditional":"〔一一〕師古曰：「各當其時而為是也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_72_17","chapterId":"ch_work_han_thu_72","textTraditional":"至周為廷尉，詔獄亦益多矣。二千石繫者新故相因，不減百餘人。郡吏大府舉之廷尉，〔一〕一歲至千餘章。章大者連逮證案數百，小者數十人；遠者數千里，近者數百里。會獄，〔二〕吏因責如章告劾，〔三〕不服，以掠笞定之。〔四〕於是聞有逮證，皆亡匿。獄久者至更數赦十餘歲而相告言，〔五〕大氐盡詆以不道，〔六〕以上廷尉及中都官，詔獄逮至六七萬人，〔七〕吏所增加十有餘萬。〔八〕","sentenceOrder":17},
  {"id":"s_work_han_thu_72_18","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　如淳曰：「郡吏，太守也。」文穎曰：「大府，公府也。」孟康曰：「舉之廷尉，以章劾付廷尉治之也。」師古曰：「孟說非也。舉，皆也。言郡吏大府獄事皆歸廷尉也。大府，丞相、御史之府也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_72_19","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　師古曰：「往赴對也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_72_20","chapterId":"ch_work_han_thu_72","textTraditional":"〔三〕　師古曰：「皆令服罪如所告劾之本章。」","sentenceOrder":20},
  {"id":"s_work_han_thu_72_21","chapterId":"ch_work_han_thu_72","textTraditional":"〔四〕　師古曰：「定其辭，令服也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_72_22","chapterId":"ch_work_han_thu_72","textTraditional":"〔五〕　師古曰：「更，歷也。其罪或非赦例，故不得除，而久逃亡不出至於十餘歲，猶相告言，由周用法深刻故也。更音工衡反。」","sentenceOrder":22},
  {"id":"s_work_han_thu_72_23","chapterId":"ch_work_han_thu_72","textTraditional":"〔六〕　師古曰：「氐讀與抵同。抵，歸也。詆，誣也。並音丁禮反。」","sentenceOrder":23},
  {"id":"s_work_han_thu_72_24","chapterId":"ch_work_han_thu_72","textTraditional":"〔七〕　師古曰：「中都官，凡京師諸官府也。獄辭所及，追考問者六七萬人也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_72_25","chapterId":"ch_work_han_thu_72","textTraditional":"〔八〕　師古曰：「吏又於此外以文致之，更增加也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_72_26","chapterId":"ch_work_han_thu_72","textTraditional":"周中廢，後為執金吾，逐捕桑弘羊、衛皇后昆弟子刻深，上以為盡力無私，遷為御史大夫。","sentenceOrder":26},
  {"id":"s_work_han_thu_72_27","chapterId":"ch_work_han_thu_72","textTraditional":"始周為廷史，有一馬，〔一〕及久任事，列三公，而兩子夾河為郡守，家訾累巨萬矣。〔二〕治皆酷暴，唯少子延年行寬厚云。","sentenceOrder":27},
  {"id":"s_work_han_thu_72_28","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「廷史，即廷尉史也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_72_29","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　師古曰：「訾與貲同。」","sentenceOrder":29},
  {"id":"s_work_han_thu_72_30","chapterId":"ch_work_han_thu_72","textTraditional":"延年字幼公，亦明法律。昭帝初立，大將軍霍光秉政，以延年三公子，吏材有餘，補軍司空。〔一〕始元四年，益州蠻夷反，延年以校尉將南陽士擊益州，還，為諫大夫。左將軍上官桀父子與蓋主、燕王謀為逆亂，假稻田使者燕倉知其謀，以告大司農楊敞。敞惶懼，移病，〔二〕以語延年。延年以聞，桀等伏辜。延年封為建平侯。","sentenceOrder":30},
  {"id":"s_work_han_thu_72_31","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　蘇林曰：「主獄官也。」如淳曰：「律，營軍司空、軍中司空各二人。」","sentenceOrder":31},
  {"id":"s_work_han_thu_72_32","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　師古曰：「移病，謂移書言病也。一曰，以病而移居。」","sentenceOrder":32},
  {"id":"s_work_han_thu_72_33","chapterId":"ch_work_han_thu_72","textTraditional":"延年本大將軍霍光吏，首發大姦，〔一〕有忠節，由是擢為太僕右曹給事中。光持刑罰嚴，延年輔之以寬。治燕王獄時，御史大夫桑弘羊子遷亡，過父故吏侯史吳。〔二〕後遷捕得，伏法。會赦，侯史吳自出繫獄，廷尉王平與少府徐仁雜治反事，〔三〕皆以為桑遷坐父謀反而侯史吳臧之，非匿反者，乃匿為隨者也。〔四〕即以赦令除吳罪。後侍御史治實，〔五〕以桑遷通經術，知父謀反而不諫爭，與反者身無異；侯史吳故三百石吏，首匿遷，〔六〕不與庶人匿隨從者等，吳不得赦。奏請覆治，劾廷尉、少府縱反者。〔七〕少府徐仁即丞相車千秋女婿也，故千秋數為侯史吳言。恐光不聽，千秋即召中二千石、博士會公車門，議問吳法。〔八〕議者知大將軍指，皆執吳為不道。明日，千秋封上眾議，光於是以千秋擅召中二千石以下，外內異言，〔九〕遂下廷尉平、少府仁獄。朝廷皆恐丞相坐之。延年乃奏記光爭，以為「吏縱罪人，有常法，今更詆吳為不道，恐於法深。〔一０〕又丞相素無所守持，而為好言於下，盡其素行也。〔一一〕至擅召中二千石，甚無狀。〔一二〕延年愚，以為丞相久故，及先帝用事，〔一三〕非有大故，不可棄也。間者民頗言獄深，吏為峻詆，〔一四〕今丞相所議，又獄事也，如是以及丞相，恐不合眾心。群下讙譁，庶人私議，流言四布，延年竊重將軍失此名於天下也！」〔一五〕光以廷尉、少府弄法輕重，皆論棄市，而不以及丞相，終與相竟〔一六〕。延年論議持平，合和朝廷，皆此類也。","sentenceOrder":33},
  {"id":"s_work_han_thu_72_34","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「首謂初首先發之。」","sentenceOrder":34},
  {"id":"s_work_han_thu_72_35","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　師古曰：「姓侯史，名吳。」","sentenceOrder":35},
  {"id":"s_work_han_thu_72_36","chapterId":"ch_work_han_thu_72","textTraditional":"〔三〕　師古曰：「交雜同共治之也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_72_37","chapterId":"ch_work_han_thu_72","textTraditional":"〔四〕　孟康曰：「言桑遷但隨坐耳，非自反也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_72_38","chapterId":"ch_work_han_thu_72","textTraditional":"〔五〕　師古曰：「重覈其事也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_72_39","chapterId":"ch_work_han_thu_72","textTraditional":"〔六〕　師古曰：「首匿者，言身為謀首而藏匿人也。他皆類此。」","sentenceOrder":39},
  {"id":"s_work_han_thu_72_40","chapterId":"ch_work_han_thu_72","textTraditional":"〔七〕　師古曰：「縱，放也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_72_41","chapterId":"ch_work_han_thu_72","textTraditional":"〔八〕　師古曰：「（言）〔于〕法律之中吳當得何罪。」","sentenceOrder":41},
  {"id":"s_work_han_thu_72_42","chapterId":"ch_work_han_thu_72","textTraditional":"〔九〕　張晏曰：「外則去疾欲盡，內則為其婿也。」師古曰：「此說非也。外內，謂外朝及內朝也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_72_43","chapterId":"ch_work_han_thu_72","textTraditional":"〔一０〕師古曰：「詆，誣也。次下亦同。」","sentenceOrder":43},
  {"id":"s_work_han_thu_72_44","chapterId":"ch_work_han_thu_72","textTraditional":"〔一一〕師古曰：「言非故有所執持，但其素行好與在下人言議耳。」","sentenceOrder":44},
  {"id":"s_work_han_thu_72_45","chapterId":"ch_work_han_thu_72","textTraditional":"〔一二〕師古曰：「無善狀。」","sentenceOrder":45},
  {"id":"s_work_han_thu_72_46","chapterId":"ch_work_han_thu_72","textTraditional":"〔一三〕師古曰：「言在位已久，是為故舊，又嘗及仕先帝而任事也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_72_47","chapterId":"ch_work_han_thu_72","textTraditional":"〔一四〕師古曰：「峻謂峭刻也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_72_48","chapterId":"ch_work_han_thu_72","textTraditional":"〔一五〕師古曰：「重猶難也。以此為重事也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_72_49","chapterId":"ch_work_han_thu_72","textTraditional":"〔一六〕師古曰：「謂終丞相之身無貶黜也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_72_50","chapterId":"ch_work_han_thu_72","textTraditional":"見國家承武帝奢侈師旅之後，數為大將軍光言：「年歲比不登，流民未盡還，〔一〕宜修孝文時政，示以儉約寬和，順天心，說民意，年歲宜應。」〔二〕光納其言，舉賢良，議罷酒榷鹽鐵，皆自延年發之。吏民上書言便宜，有異，輒下延年平處復奏。〔三〕言可官試者，至為縣令，或丞相、御史除用，滿歲以狀聞，或抵其罪法，〔四〕常與兩府及廷尉分章。〔五〕","sentenceOrder":50},
  {"id":"s_work_han_thu_72_51","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「比，頻也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_72_52","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　師古曰：「言儉約寬和，則豐年當應也。說讀曰悅。」","sentenceOrder":52},
  {"id":"s_work_han_thu_72_53","chapterId":"ch_work_han_thu_72","textTraditional":"〔三〕　師古曰：「先平處其可否，然後奏言。處音昌汝反。」","sentenceOrder":53},
  {"id":"s_work_han_thu_72_54","chapterId":"ch_work_han_thu_72","textTraditional":"〔四〕　師古曰：「抵，至也。言事之人有姦妄者，則（特）致之於罪法。」","sentenceOrder":54},
  {"id":"s_work_han_thu_72_55","chapterId":"ch_work_han_thu_72","textTraditional":"〔五〕　如淳曰：「兩府，丞相、御史府也。諸章有所疑，使延年決之。」師古曰：「此說非也。上書言事者，其章或下丞相御史，或付延年，故云分章耳，非令決疑也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_72_56","chapterId":"ch_work_han_thu_72","textTraditional":"昭帝末，寢疾，徵天下名醫，延年典領方藥。帝崩，昌邑王即位，廢，大將軍光、車騎將軍張安世與大臣議所立。時宣帝養於掖廷，號皇曾孫，與延年中子佗相愛善，延年知曾孫德美，勸光、安世立焉。宣帝即位，褒賞大臣，延年以定策安宗廟，益戶二千三百，與始封所食邑凡四千三百戶。詔有司論定策功，大司馬大將軍光功德過太尉絳侯周勃，車騎將軍安世、丞相楊敞功比丞相陳平，前將軍韓增、御史大夫蔡誼功比潁陰侯灌嬰，太僕杜延年功比朱虛侯劉章，後將軍趙充國、大司農田延年、少府史樂成功比典客劉揭，〔一〕皆封侯益土。","sentenceOrder":56},
  {"id":"s_work_han_thu_72_57","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「據如此傳，樂成姓史，而霍光傳云使樂成小家子，則又似姓使，功臣侯表乃云便樂成，三者不同。尋史、使一也，故當姓史，或作使字，而表遂誤為便耳。」","sentenceOrder":57},
  {"id":"s_work_han_thu_72_58","chapterId":"ch_work_han_thu_72","textTraditional":"延年為人安和，備於諸事，〔一〕久典朝政，上任信之，出即奉駕，人給事中，居九卿位十餘年，賞賜賂遺，訾數千萬。","sentenceOrder":58},
  {"id":"s_work_han_thu_72_59","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「言皆明習也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_72_60","chapterId":"ch_work_han_thu_72","textTraditional":"霍光薨後，子禹與宗族謀反，誅。上以延年霍氏舊人，欲退之，而丞相魏相奏延年素貴用事，官職多姦。遣吏考案，但得苑馬多死，官奴婢乏衣食，〔一〕延年坐免官，削戶二千。後數月，復召拜為北地太守。延年以故九卿外為邊吏，治郡不進，〔二〕上以璽書讓延年。〔三〕延年乃選用良吏，捕（繫）〔擊〕豪強，郡中清靜。居歲餘，上使謁者賜延年璽書，黃金二十斤，徙為西河太守，治甚有名。五鳳中，徵入為御史大夫。延年居父官府，不敢當舊位，坐臥皆易其處。是時四夷和，海內平，延年視事三歲，以老病乞骸骨，天子優之，使光祿大夫持節賜延年黃金百斤、（牛）酒，加致醫藥。延年遂稱（疾）〔病〕篤。賜安車駟馬，罷就第。〔四〕後數月薨，諡曰敬侯，子緩嗣。","sentenceOrder":60},
  {"id":"s_work_han_thu_72_61","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「傳言延年身不犯法，但丞相致之於罪耳。」","sentenceOrder":61},
  {"id":"s_work_han_thu_72_62","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　師古曰：「比於諸郡，不為最也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_72_63","chapterId":"ch_work_han_thu_72","textTraditional":"〔三〕　師古曰：「讓，責也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_72_64","chapterId":"ch_work_han_thu_72","textTraditional":"〔四〕　師古曰：「安車，坐乘之車也。後漢輿服志云『公列侯安車，朱斑輪，倚鹿較，伏熊軾，皁蓋』。倚鹿較者，畫立鹿於車之前兩藩外也。伏熊軾者，車前橫軾為伏熊之形也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_72_65","chapterId":"ch_work_han_thu_72","textTraditional":"緩少為郎，本始中以校尉從蒲類將軍擊匈奴，〔一〕還為諫大夫，遷上谷都尉，雁門太守。父延年薨，徵視喪事，拜為太常，治諸陵縣，每冬月封具獄日，常去酒省食，〔二〕官屬稱其有恩。元帝初即位，穀貴民流，永光中西羌反，緩輒上書入錢穀以助用，前後數百萬。","sentenceOrder":65},
  {"id":"s_work_han_thu_72_66","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　文穎曰：「趙充國也。」臣瓚曰：「征蒲類海，故以為名。」","sentenceOrder":66},
  {"id":"s_work_han_thu_72_67","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　師古曰：「獄案已具，當論決之，故封上。」","sentenceOrder":67},
  {"id":"s_work_han_thu_72_68","chapterId":"ch_work_han_thu_72","textTraditional":"緩六弟，五人至大官，少弟熊歷五郡二千石，三州牧刺史，有能名，唯中弟欽官不至而最知名。","sentenceOrder":68},
  {"id":"s_work_han_thu_72_69","chapterId":"ch_work_han_thu_72","textTraditional":"欽字子夏，少好經書，家富而目偏盲，〔一〕故不好為吏。茂陵杜鄴與欽同姓字，〔二〕俱以材能稱京師，故衣冠謂欽為「盲杜子夏」以相別。〔三〕欽惡以疾見詆，〔四〕乃為小冠，高廣財二寸〔五〕，由是京師更謂欽為「小冠杜子夏」，而鄴為「大冠杜子夏」云。","sentenceOrder":69},
  {"id":"s_work_han_thu_72_70","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「盲，目無見也。偏盲者，患一目也。今俗乃以兩目無見者始為盲，語移轉也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_72_71","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　師古曰：「並字子夏。」","sentenceOrder":71},
  {"id":"s_work_han_thu_72_72","chapterId":"ch_work_han_thu_72","textTraditional":"〔三〕　師古曰：「衣冠謂士大夫也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_72_73","chapterId":"ch_work_han_thu_72","textTraditional":"〔四〕　師古曰：「詆，毀也，音丁禮反。」","sentenceOrder":73},
  {"id":"s_work_han_thu_72_74","chapterId":"ch_work_han_thu_72","textTraditional":"〔五〕　師古曰：「財與纔同，古通用字。」","sentenceOrder":74},
  {"id":"s_work_han_thu_72_75","chapterId":"ch_work_han_thu_72","textTraditional":"時帝舅大將軍王鳳以外戚輔政，求賢知自助。鳳父頃侯禁與欽兄緩相善，故鳳深知欽能，奏請欽為大將軍軍武庫令。職閒無事，欽所好也。〔一〕","sentenceOrder":75},
  {"id":"s_work_han_thu_72_76","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「閒讀曰閑。」","sentenceOrder":76},
  {"id":"s_work_han_thu_72_77","chapterId":"ch_work_han_thu_72","textTraditional":"欽為人深博有謀。自上為太子時，以好色聞，及即位，皇太后詔采良家女。欽因是說大將軍鳳曰：「禮壹娶九女，所以極陽數，廣嗣重祖也；〔一〕必鄉舉求窈窕，不問華色，〔二〕所以助德理內也；娣姪雖缺不復補，所以養壽塞爭也。〔三〕故后妃有貞淑之行，則胤嗣有賢聖之君；制度有威儀之節，則人君有壽考之福。廢而不由，則女德不厭；〔四〕女德不厭，則壽命不究於高年。〔五〕書云『或四三年』，〔六〕言失欲之生害也。〔七〕男子五十，好色未衰；婦人四十，容貌改前。以改前之容侍於未衰之年，而不以禮為制，則其原不可救而後徠異態；後徠異態，則正后自疑而支庶有間適之心。〔八〕是以晉獻被納讒之謗，申生蒙無罪之辜。〔九〕今聖主富於春秋，未有適嗣，方鄉術入學，〔一０〕未親后妃之議。將軍輔政，宜因始初之隆，建九女之制，詳擇有行義之家，求淑女之質，毋必有（聲色）〔色聲〕音技能，為萬世大法。〔一一〕夫少，戒之在色，〔一二〕小卞之作，可為寒心。〔一三〕唯將軍常以為憂。」","sentenceOrder":77},
  {"id":"s_work_han_thu_72_78","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　張晏曰：「陽數一三五七九，九，數之極也。」臣瓚曰：「天子一娶九女，夏殷之制也，欽故舉前代之約以刺今之奢也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_72_79","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　師古曰：「鄉舉者，博問鄉里而舉之也。窈窕，幽閑也。窈音一了反。窕音徒了反。」","sentenceOrder":79},
  {"id":"s_work_han_thu_72_80","chapterId":"ch_work_han_thu_72","textTraditional":"〔三〕　師古曰：「媵女之內，兄弟之女則謂之姪，己之女弟則謂之娣。塞，絕也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_72_81","chapterId":"ch_work_han_thu_72","textTraditional":"〔四〕　師古曰：「由，用也，從也。女德不厭，言好色之甚也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_72_82","chapterId":"ch_work_han_thu_72","textTraditional":"〔五〕　師古曰：「究，竟也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_72_83","chapterId":"ch_work_han_thu_72","textTraditional":"〔六〕　師古曰：「周書亡逸篇曰『惟湛樂之從，罔或克壽，或十年，或七八年，或五六年，或四三年』，謂逸欲過度則損壽也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_72_84","chapterId":"ch_work_han_thu_72","textTraditional":"〔七〕　師古曰：「失讀曰佚。佚與逸同。」","sentenceOrder":84},
  {"id":"s_work_han_thu_72_85","chapterId":"ch_work_han_thu_72","textTraditional":"〔八〕　師古曰：「間，代也，音居莧反。適讀曰嫡。次下亦同。」","sentenceOrder":85},
  {"id":"s_work_han_thu_72_86","chapterId":"ch_work_han_thu_72","textTraditional":"〔九〕　師古曰：「蒙亦被也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_72_87","chapterId":"ch_work_han_thu_72","textTraditional":"〔一０〕師古曰：「鄉讀曰嚮。」","sentenceOrder":87},
  {"id":"s_work_han_thu_72_88","chapterId":"ch_work_han_thu_72","textTraditional":"〔一一〕師古曰：「惟求淑質，無論美色及音聲技能，如此，則可為萬代法也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_72_89","chapterId":"ch_work_han_thu_72","textTraditional":"〔一二〕師古曰：「論語孔子曰：『君子有三戒，少之時血氣未定，戒之在色。』言好色無節則致損敗，故戒之也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_72_90","chapterId":"ch_work_han_thu_72","textTraditional":"〔一三〕張晏曰：「刺幽王廢申后而立褒姒，黜太子宜咎而立伯服也。」臣瓚曰：「小卞之詩，太子之傅作也，哀太子之放逐，愍周室之大壞也。」師古曰：「詩小雅也。二說皆是。卞音盤。」","sentenceOrder":90},
  {"id":"s_work_han_thu_72_91","chapterId":"ch_work_han_thu_72","textTraditional":"鳳白之太后，太后以為故事無有。欽復重言：〔一〕「詩云『殷監不遠，在夏后氏之世』。〔二〕刺戒者至迫近，而省聽者常怠忽，〔三〕可不慎哉！前言九女，略陳其禍福，甚可悼懼，竊恐將軍不深留意。后妃之制，夭壽治亂存亡之端也。跡三代之季世，覽宗、宣之饗國，察近屬之符驗，〔四〕禍敗曷常不由女德？是以佩玉晏鳴，關雎歎之，〔五〕知好色之伐性短年，離制度之生無厭，天下將蒙化，陵夷而成俗也。〔六〕故詠淑女，幾以配上，〔七〕忠孝之篤，仁厚之作也。〔八〕夫君親壽尊，國家治安，誠臣子之至願，所當勉之也。易曰：『正其本，萬物理。』〔九〕凡事論有疑未可立行者，求之往古則典刑無，考之來今則吉凶同，卒搖易之則民心惑，〔一０〕若是者誠難施也。今九女之制，合於往古，無害於今，不逆於民心，至易行也，行之至有福也，將軍輔政而不蚤定，〔一一〕非天下之所望也。唯將軍信臣子之願，念關雎之思，〔一二〕逮委政之隆，及始初清明，〔一三〕為漢家建無窮之基，誠難以忽，不可以遴。」〔一四〕鳳不能自立法度，循故事而已。會皇太后女弟司馬君力〔一五〕與欽兄子私通，事上聞，欽慚懼，乞骸骨去。","sentenceOrder":91},
  {"id":"s_work_han_thu_72_92","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「重音直用反。」","sentenceOrder":92},
  {"id":"s_work_han_thu_72_93","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　師古曰：「大雅蕩之詩也。言殷之所監見，其事不遠，近在夏后氏之時。」","sentenceOrder":93},
  {"id":"s_work_han_thu_72_94","chapterId":"ch_work_han_thu_72","textTraditional":"〔三〕　師古曰：「忽，忘也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_72_95","chapterId":"ch_work_han_thu_72","textTraditional":"〔四〕　韋昭曰：「宗，殷高宗也。宣，周宣王也。皆饗國長久。」師古曰：「宗、宣之義，韋說是也。近屬者，謂漢家之事耳。屬猶言甫爾也，音之欲反。」","sentenceOrder":95},
  {"id":"s_work_han_thu_72_96","chapterId":"ch_work_han_thu_72","textTraditional":"〔五〕　李奇曰：「后夫人雞鳴佩玉去君所，周康王后不然，故詩人歎而傷之。」臣瓚曰：「此魯詩也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_72_97","chapterId":"ch_work_han_thu_72","textTraditional":"〔六〕　師古曰：「蒙，被也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_72_98","chapterId":"ch_work_han_thu_72","textTraditional":"〔七〕　師古曰：「關雎之詩云『窈窕淑女，君子好仇』，故云然也。淑，善也。幾讀曰冀。」","sentenceOrder":98},
  {"id":"s_work_han_thu_72_99","chapterId":"ch_work_han_thu_72","textTraditional":"〔八〕　師古曰：「作謂作詩也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_72_100","chapterId":"ch_work_han_thu_72","textTraditional":"〔九〕　師古曰：「今易無此文。」","sentenceOrder":100},
  {"id":"s_work_han_thu_72_101","chapterId":"ch_work_han_thu_72","textTraditional":"〔一０〕鄭（玄）〔氏〕曰：「卒，急也。」師古曰：「卒音（于）〔千〕忽反。」","sentenceOrder":101},
  {"id":"s_work_han_thu_72_102","chapterId":"ch_work_han_thu_72","textTraditional":"〔一一〕師古曰：「蚤，古早字。」","sentenceOrder":102},
  {"id":"s_work_han_thu_72_103","chapterId":"ch_work_han_thu_72","textTraditional":"〔一二〕師古曰：「信讀曰申。」","sentenceOrder":103},
  {"id":"s_work_han_thu_72_104","chapterId":"ch_work_han_thu_72","textTraditional":"〔一三〕師古曰：「委政之隆，言天子委鳳政事，權寵隆盛也。始初清明，天子新即位，宜立法制。」","sentenceOrder":104},
  {"id":"s_work_han_thu_72_105","chapterId":"ch_work_han_thu_72","textTraditional":"〔一四〕李奇曰：「遴，難也。」師古曰：「遴與〈恡，去“忄”〉同。」","sentenceOrder":105},
  {"id":"s_work_han_thu_72_106","chapterId":"ch_work_han_thu_72","textTraditional":"〔一五〕蘇林曰：「字君力，為司馬氏婦。」","sentenceOrder":106},
  {"id":"s_work_han_thu_72_107","chapterId":"ch_work_han_thu_72","textTraditional":"後有日蝕地震之變，詔舉賢良方正能直言士，合陽侯梁放舉欽。欽上對曰：「陛下畏天命，悼變異，延見公卿，舉直言之士，將以求天心，跡得失也。〔一〕臣欽愚戇，經術淺薄，不足以奉大對。〔二〕臣聞日蝕地震，陽微陰盛也。臣者，君之陰也；子者，父之陰也；妻者，夫之陰也；夷狄者，中國之陰也。春秋日蝕三十六，地震五，〔三〕或夷狄侵中國，或政權在臣下，或婦乘夫，〔四〕或臣子背君父，事雖不同，其類一也。臣竊觀人事以考變異，則本朝大臣無不自安之人，外戚親屬無乖剌之心，〔五〕關東諸侯無強大之國，三垂蠻夷無逆理之節；〔六〕殆為後宮。〔七〕何以言之？日以戊申蝕，時加未。戊（夫）〔未〕，土也。土者，中宮之部也。其夜地震未央宮殿中，此必適妾將有爭寵相害而為患者，〔八〕唯陛下深戒之。變感以類相應，人事失於下，變象見於上。能應之以德，則異咎消亡；不能應之以善，則禍敗至。高宗遭雊雉之戒，飭己正事，享百年之壽，殷道復興，〔九〕要在所以應之。應之非誠不立，非信不行。宋景公小國之諸侯耳，有不忍移禍之誠，出人君之言三，熒惑為之退舍〔一０〕。以陛下聖明，內推至誠，深思天變，何應而不感？何搖而不動？孔子曰：『仁遠乎哉！』〔一一〕唯陛下正后妾，抑女寵，防奢泰，去佚游，躬節儉，親萬事，數御安車，由輦道，〔一二〕親二宮之饔膳，〔一三〕致晨昏之定省。如此，即堯舜不足與比隆，咎異何足消滅！如不留聽於庶事，不論材而授位，殫天下之財以奉淫侈，匱萬姓之力以從耳目，〔一四〕近諂諛之人而遠公方，〔一五〕信讒賊之臣以誅忠良，賢俊失在巖穴，大臣怨於不以，〔一六〕雖無變異，社稷之憂也。天下至大，萬事至眾，祖業至重，誠不可以佚豫為，不可以奢泰持也。〔一七〕唯陛下忍無益之欲，以全眾庶之命。臣欽愚戇，言不足采。」","sentenceOrder":107},
  {"id":"s_work_han_thu_72_108","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「觀得失之蹤跡也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_72_109","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　師古曰：「大對謂對大問也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_72_110","chapterId":"ch_work_han_thu_72","textTraditional":"〔三〕　師古曰：「解在劉向傳。」","sentenceOrder":110},
  {"id":"s_work_han_thu_72_111","chapterId":"ch_work_han_thu_72","textTraditional":"〔四〕　師古曰：「乘，陵也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_72_112","chapterId":"ch_work_han_thu_72","textTraditional":"〔五〕　師古曰：「剌，戾也，音來曷反。」","sentenceOrder":112},
  {"id":"s_work_han_thu_72_113","chapterId":"ch_work_han_thu_72","textTraditional":"〔六〕　師古曰：「三垂謂東南西也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_72_114","chapterId":"ch_work_han_thu_72","textTraditional":"〔七〕　師古曰：「殆，近也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_72_115","chapterId":"ch_work_han_thu_72","textTraditional":"〔八〕　師古曰：「適讀曰嫡。嫡謂正后也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_72_116","chapterId":"ch_work_han_thu_72","textTraditional":"〔九〕　師古曰：「解在五行志。」","sentenceOrder":116},
  {"id":"s_work_han_thu_72_117","chapterId":"ch_work_han_thu_72","textTraditional":"〔一０〕張晏曰：「宋景公熒惑守心，太史子韋請移之於大臣及國人與歲，公皆不聽。天感其誠，熒惑為之退舍，景公享延期之祚也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_72_118","chapterId":"ch_work_han_thu_72","textTraditional":"〔一一〕師古曰：「論語載孔子之言也。言仁道不遠，求之而至也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_72_119","chapterId":"ch_work_han_thu_72","textTraditional":"〔一二〕師古曰：「由，從也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_72_120","chapterId":"ch_work_han_thu_72","textTraditional":"〔一三〕韋昭曰：「二宮即成太后與成帝母也。」師古曰：「熟食曰饔，具食曰膳。膳之言善也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_72_121","chapterId":"ch_work_han_thu_72","textTraditional":"〔一四〕師古曰：「殫、匱皆盡也。從讀曰縱。」","sentenceOrder":121},
  {"id":"s_work_han_thu_72_122","chapterId":"ch_work_han_thu_72","textTraditional":"〔一五〕師古曰：「方，正也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_72_123","chapterId":"ch_work_han_thu_72","textTraditional":"〔一六〕師古曰：「失在巖穴，謂隱處巖穴，朝廷失之也。論語稱周公謂魯公『不使大臣怨乎不以』。以，用也。不見用而怨也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_72_124","chapterId":"ch_work_han_thu_72","textTraditional":"〔一七〕師古曰：「為，治也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_72_125","chapterId":"ch_work_han_thu_72","textTraditional":"其夏，上盡召直言之士詣白虎殿對策，〔一〕策曰：「天地之道何貴？王者之法何如？六經之義何上？人之行何先？取人之術何以？〔二〕當世之治何務？各以經對。」〔三〕","sentenceOrder":125},
  {"id":"s_work_han_thu_72_126","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「此殿在未央宮也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_72_127","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　師古曰：「以，用也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_72_128","chapterId":"ch_work_han_thu_72","textTraditional":"〔三〕　師古曰：「據經義以對。」","sentenceOrder":128},
  {"id":"s_work_han_thu_72_129","chapterId":"ch_work_han_thu_72","textTraditional":"欽對曰：「臣聞天道貴信，地道貴貞；〔一〕不信不貞，萬物不生。生，天地之所貴也。王者承天地之所生，理而成之，昆蟲草木靡不得其所。王者法天地，非仁無以廣施，非義無以正身；克己就義，恕以及人，〔二〕六經之所上也。不孝，則事君不忠，蒞官不敬〔三〕，戰陳無勇，朋友不信。孔子曰：『孝無終始，而患不及者，未之有也。』〔四〕孝，人行之所先也。觀本行於鄉黨，考功能於官職，達觀其所舉，富觀其所予，窮觀其所不為，乏觀其所不取，近觀其所為〔主〕，遠觀其所主。〔五〕孔子曰：『視其所以，觀其所由，察其所安，人焉廋哉？』〔六〕取人之術也。殷因於夏尚質，周因於殷尚文，今漢家承周秦之敝，宜抑文尚質，廢奢長儉，表實去偽。〔七〕孔子曰『惡紫之奪朱』，〔八〕當世治之所務也。臣竊有所憂，言之則拂心逆指，〔九〕不言則漸日長，為禍不細，然小臣不敢廢道而求從，違忠而耦意。〔一０〕臣聞玩色無厭，必生好憎之心；好憎之心生，則愛寵偏於一人；愛寵偏於一人，則繼嗣之路不廣，而嫉妒之心興矣。如此，則匹婦之說，不可勝也。〔一一〕唯陛下純德普施，無欲是從，〔一二〕此則眾庶咸說，〔一三〕繼嗣日廣，而海內長安。萬事之是非何足備言！」〔一四〕","sentenceOrder":129},
  {"id":"s_work_han_thu_72_130","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「貞，正也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_72_131","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　師古曰：「恕，仁也。言以仁愛為心，內省己志施之於人也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_72_132","chapterId":"ch_work_han_thu_72","textTraditional":"〔三〕　師古曰：「蒞，臨也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_72_133","chapterId":"ch_work_han_thu_72","textTraditional":"〔四〕　師古曰：「孝經載孔子之言也。言人能終始行孝，而患不及於道者，未之有也。一說行孝終始不備，而患禍不及者，無此事也。」","sentenceOrder":133},
  {"id":"s_work_han_thu_72_134","chapterId":"ch_work_han_thu_72","textTraditional":"〔五〕　師古曰：「所為主，謂託人以為援而自進也。其所主，為人之援而進也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_72_135","chapterId":"ch_work_han_thu_72","textTraditional":"〔六〕　師古曰：「論語載孔子之言也。廋，匿也。此言視人之所用，觀人之所從，察人之所樂，則可知其善惡，無所匿其情也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_72_136","chapterId":"ch_work_han_thu_72","textTraditional":"〔七〕　師古曰：「長謂崇貴之也。表，明也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_72_137","chapterId":"ch_work_han_thu_72","textTraditional":"〔八〕　師古曰：「論語載孔子之言也。朱，正色也。紫，間色之好者也。惡其邪好而奪正色，以喻利口之人，多言少實，傾惑者也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_72_138","chapterId":"ch_work_han_thu_72","textTraditional":"〔九〕　師古曰：「拂謂違戾也，音佛。」","sentenceOrder":138},
  {"id":"s_work_han_thu_72_139","chapterId":"ch_work_han_thu_72","textTraditional":"〔一０〕師古曰：「從，順也。耦，合也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_72_140","chapterId":"ch_work_han_thu_72","textTraditional":"〔一一〕師古曰：「匹婦，一婦人也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_72_141","chapterId":"ch_work_han_thu_72","textTraditional":"〔一二〕師古曰：「從讀曰縱。不縱心於所欲也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_72_142","chapterId":"ch_work_han_thu_72","textTraditional":"〔一三〕師古曰：「說讀曰悅。」","sentenceOrder":142},
  {"id":"s_work_han_thu_72_143","chapterId":"ch_work_han_thu_72","textTraditional":"〔一四〕師古曰：「如此，則細故萬端不足憂也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_72_144","chapterId":"ch_work_han_thu_72","textTraditional":"欽以前事病，賜帛罷，後為議郎，復以病免。","sentenceOrder":144},
  {"id":"s_work_han_thu_72_145","chapterId":"ch_work_han_thu_72","textTraditional":"徵詣大將軍莫府，國家政謀，鳳常與欽慮之。〔一〕數稱達名士王駿、韋安世、王延世等，〔二〕救解馮野王、王尊、胡常之罪過，及繼功臣絕世，填撫四夷，〔三〕當世善政，多出於欽者。見鳳專政泰重，戒之曰：「昔周公身有至聖之德，屬有叔父之親，而成王有獨見之明，無信讒之聽，然管蔡流言而周公懼。穰侯，昭王之舅也〔四〕，權重於秦，威震鄰敵，有旦莫偃伏之愛，〔五〕心不介然有間，然范雎起徒步，由異國，無雅信，〔六〕開一朝之說，而穰侯就封。〔七〕及近者武安侯之見退，〔八〕三事之跡，相去各數百歲，若合符節，甚不可不察。願將軍由周公之謙懼，〔九〕損穰侯之威，放武安之欲，毋使范雎之徒得間其說。」〔一０〕","sentenceOrder":145},
  {"id":"s_work_han_thu_72_146","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「慮，計也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_72_147","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　師古曰：「王駿，王陽子也。韋安世，韋賢之孫，方山之子也。王延世即成帝時塞河隄者也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_72_148","chapterId":"ch_work_han_thu_72","textTraditional":"〔三〕　師古曰：「填音竹刃反。」","sentenceOrder":148},
  {"id":"s_work_han_thu_72_149","chapterId":"ch_work_han_thu_72","textTraditional":"〔四〕　文穎曰：「穰侯，魏冉也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_72_150","chapterId":"ch_work_han_thu_72","textTraditional":"〔五〕　師古曰：「言昭王幼少，旦夕偃伏戲弄於舅之旁側也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_72_151","chapterId":"ch_work_han_thu_72","textTraditional":"〔六〕　師古曰：「雅信，謂素相任信。」","sentenceOrder":151},
  {"id":"s_work_han_thu_72_152","chapterId":"ch_work_han_thu_72","textTraditional":"〔七〕　（師古）〔文穎〕曰：「范雎為丞相，穰侯就國。」","sentenceOrder":152},
  {"id":"s_work_han_thu_72_153","chapterId":"ch_work_han_thu_72","textTraditional":"〔八〕　師古曰：「武安侯謂田蚡也。退謂請考工地益宅，上怒乃退之也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_72_154","chapterId":"ch_work_han_thu_72","textTraditional":"〔九〕　師古曰：「由，從也，用也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_72_155","chapterId":"ch_work_han_thu_72","textTraditional":"〔一０〕師古曰：「間音居莧反。」","sentenceOrder":155},
  {"id":"s_work_han_thu_72_156","chapterId":"ch_work_han_thu_72","textTraditional":"頃之，復日蝕，京兆尹王章上封事求見，果言鳳專權蔽主之過，宜廢勿用，以應天變。於是天子感悟，召見章，與議，欲退鳳。鳳甚憂懼，欽令鳳上疏謝罪，乞骸骨，文指甚哀。太后涕泣為不食。上少而親倚鳳，亦不忍廢，〔一〕復起鳳就位。鳳心慚，稱病篤，欲遂退。欽復說之曰：「將軍深悼輔政十年，變異不已，故乞骸骨，歸咎於身，刻己自責，至誠動眾，愚知莫不感傷。雖然，是無屬之臣，執進退之分，絜其去就之節者耳，〔二〕非主上所以待將軍，非將軍所以報主上也。昔周公雖老，猶在京師，明不離成周，示不忘王室也。仲山父異姓之臣，無親於宣，就封於齊，〔三〕猶歎息永懷，宿夜徘徊，不忍遠去，況將軍之於主上，主上之與將軍哉！夫欲天下治安變異之意，莫有將軍，〔四〕主上照然知之，故攀援不遣，〔五〕書稱『公毋困我！』〔六〕唯將軍不為四國流言自疑於成王，以固至忠。」鳳復起視事。上令尚書劾奏京兆尹章，章死詔獄。語在元后傳。","sentenceOrder":156},
  {"id":"s_work_han_thu_72_157","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「倚音於綺反。」","sentenceOrder":157},
  {"id":"s_work_han_thu_72_158","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　師古曰：「無屬，無親屬於上也。分音扶問反，字或作介。介，隔也，其義兩通。」","sentenceOrder":158},
  {"id":"s_work_han_thu_72_159","chapterId":"ch_work_han_thu_72","textTraditional":"〔三〕　鄧展曰：「詩言仲山甫徂齊者，言銜命往治齊城郭也，而韓詩以為封於齊，此誤耳。」晉灼曰：「韓詩誤而欽引之，阿附權貴求容媚也。」師古曰：「韓詩既有明文，而欽引以為喻，則是其義非繆，而與今說詩者不同。鄧、晉諸人雖曰涉學，未得專非杜氏，追咎韓詩也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_72_160","chapterId":"ch_work_han_thu_72","textTraditional":"〔四〕　師古曰：「言眾人之意皆不如也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_72_161","chapterId":"ch_work_han_thu_72","textTraditional":"〔五〕　師古曰：「援，引也，音爰。」","sentenceOrder":161},
  {"id":"s_work_han_thu_72_162","chapterId":"ch_work_han_thu_72","textTraditional":"〔六〕　師古曰：「此周書洛誥成王告周公詞也。言公必須留此，毋得遂去，而令我困。蓋成帝與鳳詔書引此言之。」","sentenceOrder":162},
  {"id":"s_work_han_thu_72_163","chapterId":"ch_work_han_thu_72","textTraditional":"章既死，眾庶冤之，以譏朝廷。欽欲救其過，復說鳳曰：「京兆尹章所坐事密，吏民見章素好言事，以為不坐官職，疑其以日蝕見對有所言也。假令章內有所犯，雖陷正法，事不暴揚，自京師不曉，況於遠方。恐天下不知章實有罪，而以為坐言事也。如是，塞爭引之原，損寬明之德。〔一〕欽愚以為宜因章事舉直言極諫，並見郎從官展盡其意，加於往前，以明示四方，使天下咸知主上聖明，不以言罪下也。若此，則流言消釋，疑惑著明。」鳳白行其策。欽之補過將美，皆此類也。〔二〕","sentenceOrder":163},
  {"id":"s_work_han_thu_72_164","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「爭引謂引事類以諫爭也。一曰，下有諫爭之言，上引而納之也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_72_165","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　師古曰：「將，助也。」","sentenceOrder":165},
  {"id":"s_work_han_thu_72_166","chapterId":"ch_work_han_thu_72","textTraditional":"優游不仕，以壽終。欽子及昆弟支屬至二千石者且十人。欽兄緩前免太常，以列侯奉朝請，成帝時乃薨，子業嗣。","sentenceOrder":166},
  {"id":"s_work_han_thu_72_167","chapterId":"ch_work_han_thu_72","textTraditional":"業有材能，以列侯選，復為太常。數言得失，不事權貴，與丞相翟方進、衛尉定陵侯淳于長不平。後業坐法免官，復為函谷關都尉。會定陵侯長有罪，當就國，長舅紅陽侯立與業書曰：「誠哀老姊垂白，隨無狀子出關，〔一〕願勿復用前事相侵。」定陵侯既出關，伏罪復發，〔二〕下雒陽獄。丞相史搜得紅陽侯書，奏業聽請，不敬〔三〕，坐免就國。","sentenceOrder":167},
  {"id":"s_work_han_thu_72_168","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「垂白者，言白髮下垂也。無狀猶言不肖。」","sentenceOrder":168},
  {"id":"s_work_han_thu_72_169","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　蘇林曰：「長與許后書也。語在外戚傳。」","sentenceOrder":169},
  {"id":"s_work_han_thu_72_170","chapterId":"ch_work_han_thu_72","textTraditional":"〔三〕　服虔曰：「受立屬請為不敬。」","sentenceOrder":170},
  {"id":"s_work_han_thu_72_171","chapterId":"ch_work_han_thu_72","textTraditional":"其春，丞相方進薨，業上書言：「方進本與長深結厚，更相稱薦，〔一〕長陷大惡，獨得不坐，苟欲障塞前過，不為陛下廣持平例，〔二〕又無恐懼之心，反因時信其邪辟，〔三〕報睚眥怨。〔四〕故事，大逆朋友坐免官，無歸故郡者，今（在）〔坐〕長者歸故郡，已深一等；紅陽侯立坐子受長貨賂故就國耳，非大逆也，而方進復奏立黨友後將軍朱博、鉅鹿太守孫宏、故少府陳咸，皆免官，歸咸故郡。刑罰無平，在方進之筆端，眾庶莫不疑惑，皆言孫宏不與紅陽侯相愛。宏前為中丞時，方進為御史大夫，舉掾隆可侍御史，〔五〕宏奏隆前奉使欺謾，〔六〕不宜執法近侍，方進以此怨宏。又方進為京兆尹時，陳咸為少府，在九卿高弟，陛下所自知也。方進素與司直師丹相善，臨御史大夫缺，使丹奏咸為姦利，請案驗，卒不能有所得，而方進果自得御史大夫。為丞相，即時詆欺，奏免咸，〔七〕復因紅陽侯事歸咸故郡。眾人皆言國家假方進權太甚。案師丹行能無異，及光祿勳許商被病殘人，〔八〕皆但以附從方進，嘗獲尊官。丹前親（屬）〔薦〕邑子丞相史能使巫下神，為國求福，幾獲大利。〔九〕幸賴陛下至明，遣使者毛莫如先考驗，卒得其姦，皆坐死。假令丹知而白之，此誣罔罪也；不知而白之，是背經術惑左道也：〔一０〕二者皆在大辟，重於朱博、孫宏、陳咸所坐。方進終不舉白，專作威福，阿黨所厚，排擠英俊，〔一一〕託公報私，橫厲無所畏忌，〔一二〕欲以熏轑天下。〔一三〕天下莫不望風而靡，〔一四〕自尚書近臣皆結舌杜口，〔一五〕骨肉親屬莫不股栗。〔一六〕威權泰盛而不忠信，非所以安國家也。今聞方進卒病死，〔一七〕不以尉示天下，反復賞賜厚葬，唯陛下深思往事，以戒來今。」","sentenceOrder":171},
  {"id":"s_work_han_thu_72_172","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「更音工衡反。」","sentenceOrder":172},
  {"id":"s_work_han_thu_72_173","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　師古曰：「俱與長厚善，而方進獨不坐，是不平也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_72_174","chapterId":"ch_work_han_thu_72","textTraditional":"〔三〕　師古曰：「信讀曰伸。辟讀曰僻。」","sentenceOrder":174},
  {"id":"s_work_han_thu_72_175","chapterId":"ch_work_han_thu_72","textTraditional":"〔四〕　師古曰：「睚音厓。睚，舉眼也。眥即眥字，謂目匡也。言舉目相忤者，即報之也。一說睚音五懈反。眥音仕懈反。睚眥，瞋目貌也。兩義並通。他皆類此。」","sentenceOrder":175},
  {"id":"s_work_han_thu_72_176","chapterId":"ch_work_han_thu_72","textTraditional":"〔五〕　師古曰：「御史大夫之掾也，名隆。」","sentenceOrder":176},
  {"id":"s_work_han_thu_72_177","chapterId":"ch_work_han_thu_72","textTraditional":"〔六〕　師古曰：「謾，誑也，音慢，又音莫連反。」","sentenceOrder":177},
  {"id":"s_work_han_thu_72_178","chapterId":"ch_work_han_thu_72","textTraditional":"〔七〕　師古曰：「詆，誣也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_72_179","chapterId":"ch_work_han_thu_72","textTraditional":"〔八〕　服虔曰：「殘，癃也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_72_180","chapterId":"ch_work_han_thu_72","textTraditional":"〔九〕　師古曰：「幾讀曰冀。」","sentenceOrder":180},
  {"id":"s_work_han_thu_72_181","chapterId":"ch_work_han_thu_72","textTraditional":"〔一０〕師古曰：「左道，不正之道也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_72_182","chapterId":"ch_work_han_thu_72","textTraditional":"〔一一〕師古曰：「擠，墜也，音子詣反。」","sentenceOrder":182},
  {"id":"s_work_han_thu_72_183","chapterId":"ch_work_han_thu_72","textTraditional":"〔一二〕師古曰：「縱橫陵厲也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_72_184","chapterId":"ch_work_han_thu_72","textTraditional":"〔一三〕師古曰：「熏言熏灼之。轑讀曰燎。假借用字。」","sentenceOrder":184},
  {"id":"s_work_han_thu_72_185","chapterId":"ch_work_han_thu_72","textTraditional":"〔一四〕師古曰：「靡猶弭。」","sentenceOrder":185},
  {"id":"s_work_han_thu_72_186","chapterId":"ch_work_han_thu_72","textTraditional":"〔一五〕師古曰：「杜，塞也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_72_187","chapterId":"ch_work_han_thu_72","textTraditional":"〔一六〕師古曰：「言懼之甚，故股戰慄也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_72_188","chapterId":"ch_work_han_thu_72","textTraditional":"〔一七〕師古曰：「卒讀曰猝。」","sentenceOrder":188},
  {"id":"s_work_han_thu_72_189","chapterId":"ch_work_han_thu_72","textTraditional":"會成帝崩，哀帝即位，業復上書言：「王氏世權日久，朝無骨骾之臣，〔一〕宗室諸侯微弱，與繫囚無異，自佐史以上至於大吏皆權臣之黨。曲陽侯根前為三公輔政，知趙昭儀殺皇子，不輒白奏，反與趙氏比周，恣意妄行，〔二〕譖愬故許后，被加以非罪，〔三〕誅破諸許族，敗元帝外家。內嫉妒同產兄姊紅陽侯立及淳于氏，〔四〕皆老被放棄。新喋血京師，威權可畏。高陽侯薛宣有不養母之名，安昌侯張禹姦人之雄，惑亂朝廷，使先帝負謗於海內，尤不可不慎。陛下初即位，謙讓未皇，〔五〕孤獨特立，莫可據杖，權臣易世，意若探湯。〔六〕宜蚤以義割恩，安百姓心。竊見朱博忠信勇猛，材略不世出，〔七〕誠國家雄俊之寶臣也，宜徵博置左右，以填天下。〔八〕此人在朝，則陛下可高枕而臥矣。昔諸呂欲危劉氏，賴有高祖遺臣周勃、陳平尚存，不者，幾為姦臣笑。」〔九〕","sentenceOrder":189},
  {"id":"s_work_han_thu_72_190","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「骾亦鯁字。」","sentenceOrder":190},
  {"id":"s_work_han_thu_72_191","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　師古曰：「比音頻寐反。」","sentenceOrder":191},
  {"id":"s_work_han_thu_72_192","chapterId":"ch_work_han_thu_72","textTraditional":"〔三〕　師古曰：「被音皮義反。」","sentenceOrder":192},
  {"id":"s_work_han_thu_72_193","chapterId":"ch_work_han_thu_72","textTraditional":"〔四〕　師古曰：「兄，紅陽侯立也。姊，淳于長母也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_72_194","chapterId":"ch_work_han_thu_72","textTraditional":"〔五〕　師古曰：「皇，暇也。」","sentenceOrder":194},
  {"id":"s_work_han_thu_72_195","chapterId":"ch_work_han_thu_72","textTraditional":"〔六〕　師古曰：「言重難之，若以手探熱湯也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_72_196","chapterId":"ch_work_han_thu_72","textTraditional":"〔七〕　師古曰：「言其希有也。」","sentenceOrder":196},
  {"id":"s_work_han_thu_72_197","chapterId":"ch_work_han_thu_72","textTraditional":"〔八〕　師古曰：「填音竹刃反。」","sentenceOrder":197},
  {"id":"s_work_han_thu_72_198","chapterId":"ch_work_han_thu_72","textTraditional":"〔九〕　師古曰：「幾音鉅依反。」","sentenceOrder":198},
  {"id":"s_work_han_thu_72_199","chapterId":"ch_work_han_thu_72","textTraditional":"業又言宜為恭王立廟京師，以章孝道。時高昌侯董宏亦言宜尊帝母定陶王丁后為帝太后。大司空師丹等劾宏誤朝不道，坐免為庶人，業復上書訟宏。前後所言皆合指施行，朱博果見拔用。業由是徵，復為太常。歲餘，左遷上黨都尉。會司隸奏業為太常選舉不實，業坐免官，復就國。","sentenceOrder":199},
  {"id":"s_work_han_thu_72_200","chapterId":"ch_work_han_thu_72","textTraditional":"哀帝崩，王莽秉政，諸前議立廟尊號者皆免，徙合浦。業以前罷黜，故見闊略，〔一〕憂恐，發病死。業成帝初尚帝妹潁邑公主，主無子，薨，業家上書求還京師與主合葬，不許，而賜諡曰荒侯，傳子至孫絕。初，杜周武帝時徙茂陵，至延年徙杜陵云。","sentenceOrder":200},
  {"id":"s_work_han_thu_72_201","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「闊略，謂寬縱不問也。」","sentenceOrder":201},
  {"id":"s_work_han_thu_72_202","chapterId":"ch_work_han_thu_72","textTraditional":"贊曰：張湯、杜周並起文墨小吏，致位三公，列於酷吏。而俱有良子，德器自過，〔一〕爵位尊顯，繼世立朝，相與提衡，〔二〕至於建武，杜氏爵乃獨絕。〔三〕跡其福祚，元功儒林之後莫能及也。〔四〕自謂唐杜苗裔，豈其然乎？〔五〕及欽浮沈當世，好謀而成，以建始之初深陳女戒，終如其言，庶幾乎關雎之見微，〔六〕非夫浮華博習之徒所能規也。業因勢而抵陒，〔七〕稱朱博，毀師丹，愛憎之議可不畏哉！","sentenceOrder":202},
  {"id":"s_work_han_thu_72_203","chapterId":"ch_work_han_thu_72","textTraditional":"〔一〕　師古曰：「言其子德器各過二人之身。」","sentenceOrder":203},
  {"id":"s_work_han_thu_72_204","chapterId":"ch_work_han_thu_72","textTraditional":"〔二〕　如淳曰：「提衡猶言相提攜也。」臣瓚曰：「衡，平也，言二人齊也。」師古曰：「瓚說是也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_72_205","chapterId":"ch_work_han_thu_72","textTraditional":"〔三〕　師古曰：「建武之後，張氏尚有張純為侯，故言杜氏獨絕也。」","sentenceOrder":205},
  {"id":"s_work_han_thu_72_206","chapterId":"ch_work_han_thu_72","textTraditional":"〔四〕　師古曰：「元功，蕭、曹、張、陳之屬也。儒林，貢、薛、韋、匡之輩。」","sentenceOrder":206},
  {"id":"s_work_han_thu_72_207","chapterId":"ch_work_han_thu_72","textTraditional":"〔五〕　師古曰：「謂在周為唐杜氏也。」","sentenceOrder":207},
  {"id":"s_work_han_thu_72_208","chapterId":"ch_work_han_thu_72","textTraditional":"〔六〕　師古曰：「關雎，國風之始，言夫婦之際政化所由，故云見微。微謂微妙也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_72_209","chapterId":"ch_work_han_thu_72","textTraditional":"〔七〕　服虔曰：「抵音紙。陒音羲。謂罪敗而復抨彈之，蘇秦書有此法。」師古曰：「抵，擊也。陒，毀也。言因事形勢而擊毀之也。陒音詭。一說陒讀與戲同，音許宜反。戲亦險也，言擊其危險之處，鬼谷有抵戲篇也。」","sentenceOrder":209},
  {"id":"s_work_han_thu_72_210","chapterId":"ch_work_han_thu_72","textTraditional":"校勘記","sentenceOrder":210},
  {"id":"s_work_han_thu_72_211","chapterId":"ch_work_han_thu_72","textTraditional":"二六六０頁一五行　大氐盡詆以不道，〔六〕以上　注〔六〕原在「以上」下。王先謙說索隱「以上」屬下讀，似當從之。","sentenceOrder":211},
  {"id":"s_work_han_thu_72_212","chapterId":"ch_work_han_thu_72","textTraditional":"二六六三頁一五行　（言）〔于〕法律之中，吳當得何罪。　景祐、殿本都作〔于〕。","sentenceOrder":212},
  {"id":"s_work_han_thu_72_213","chapterId":"ch_work_han_thu_72","textTraditional":"二六六四頁一０行　輒下延年平處復奏。〔三〕言可官試者，至為縣令，　注〔三〕原在「言」字下。王先謙說「言」字當下屬。","sentenceOrder":213},
  {"id":"s_work_han_thu_72_214","chapterId":"ch_work_han_thu_72","textTraditional":"二六六四頁一五行　言事之人有姦妄者，則（特）致之於罪法。　殿本「特」作「持」。景祐本無「特」字。","sentenceOrder":214},
  {"id":"s_work_han_thu_72_215","chapterId":"ch_work_han_thu_72","textTraditional":"二六六六頁　一行　延年乃選用良吏，捕（繫）〔擊〕豪強。　劉奉世說「繫」當作「擊」，字之誤也。按景祐本作「擊」。","sentenceOrder":215},
  {"id":"s_work_han_thu_72_216","chapterId":"ch_work_han_thu_72","textTraditional":"二六六六頁　四行　賜延年黃金百斤，（牛）酒，加致醫藥。延年遂稱（疾）〔病〕篤。　宋祁說浙本「酒」字上有「牛」字。按景祐、殿本都無「牛」字。錢大昭說「疾」南監本、閩本作「病」。按景祐、殿本都作「病」。","sentenceOrder":216},
  {"id":"s_work_han_thu_72_217","chapterId":"ch_work_han_thu_72","textTraditional":"二六六八頁　八行　毋必有（聲色）〔色聲〕音技能，　王先謙說，據顏注，明後人傳寫誤倒「色聲」作「聲色」。","sentenceOrder":217},
  {"id":"s_work_han_thu_72_218","chapterId":"ch_work_han_thu_72","textTraditional":"二六七０頁一六行　鄭（玄）〔氏〕曰：　景祐、殿本都作「鄭氏」，「玄」字誤。","sentenceOrder":218},
  {"id":"s_work_han_thu_72_219","chapterId":"ch_work_han_thu_72","textTraditional":"二六七０頁一六行　卒音（于）〔千〕忽反。　景祐、殿本都作「千」，此誤。","sentenceOrder":219},
  {"id":"s_work_han_thu_72_220","chapterId":"ch_work_han_thu_72","textTraditional":"二六七一頁一二行　戊（夫）〔未〕，土也。　錢大昭說「夫」當作「未」。按景祐、殿、局本都作「未」。","sentenceOrder":220},
  {"id":"s_work_han_thu_72_221","chapterId":"ch_work_han_thu_72","textTraditional":"二六七四頁　五行　近觀其所為〔主〕，　宋祁說「為」字下南本、浙本並有「主」字。王先謙、楊樹達都說當有。","sentenceOrder":221},
  {"id":"s_work_han_thu_72_222","chapterId":"ch_work_han_thu_72","textTraditional":"二六七六頁一二行　（師古）〔文穎〕曰：　景祐、殿本都作「文穎」。","sentenceOrder":222},
  {"id":"s_work_han_thu_72_223","chapterId":"ch_work_han_thu_72","textTraditional":"二六七九頁　八行　今（在）〔坐〕長者歸故郡，　錢大昭說「在」當作「坐」。按景祐、殿、局本都作「坐」。","sentenceOrder":223},
  {"id":"s_work_han_thu_72_224","chapterId":"ch_work_han_thu_72","textTraditional":"二六八０頁　一行　丹前親（屬）〔薦〕邑子丞相史能使巫下神，　景祐、殿本都作「薦」。王先謙說作「薦」是。","sentenceOrder":224},
  {"id":"s_work_han_thu_73_1","chapterId":"ch_work_han_thu_73","textTraditional":"張騫，漢中人也，〔一〕建元中為郎。時匈奴降者言匈奴破月氏王，〔一〕以其頭為飲器，〔三〕月氏遁而怨匈奴，無與共擊之〔四〕。漢方欲事滅胡，聞此言，欲通使，道必更匈奴中，〔五〕乃募能使者。騫以郎應募，使月氏，與堂邑氏奴甘父〔六〕俱出隴西。徑匈奴，〔七〕匈奴得之，傳詣單于。單于曰：「月氏在吾北，漢何以得往使？吾欲使越，漢肯聽我乎？」留騫十餘歲，予妻，有子，然騫持漢節不失。","sentenceOrder":1},
  {"id":"s_work_han_thu_73_2","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　師古曰：「陳壽益部耆舊傳云騫漢中成固人也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_73_3","chapterId":"ch_work_han_thu_73","textTraditional":"〔二〕　師古曰：「月氏，西域胡國也。氏音支。」","sentenceOrder":3},
  {"id":"s_work_han_thu_73_4","chapterId":"ch_work_han_thu_73","textTraditional":"〔三〕　韋昭曰：「飲器，椑榼也。」晉灼曰：「飲器，虎子屬也，或曰飲酒之器也。」師古曰：「匈奴傳云『以所破月氏王頭共飲血盟』，然則飲酒之器是也。韋云椑榼，晉云獸子，皆非也。椑榼，即今之偏榼，所以盛酒耳，非用飲者也。獸子褻器，所以溲便者也。椑音鼙。」","sentenceOrder":4},
  {"id":"s_work_han_thu_73_5","chapterId":"ch_work_han_thu_73","textTraditional":"〔四〕　師古曰：「無人援助也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_73_6","chapterId":"ch_work_han_thu_73","textTraditional":"〔五〕　師古曰：「更，過也，音工衡反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_73_7","chapterId":"ch_work_han_thu_73","textTraditional":"〔六〕　服虔曰：「堂邑，姓也，漢人，其奴名甘父。」師古曰：「堂邑氏之奴，本胡人，名甘父。下云堂邑父者，蓋取主之姓以為氏，而單稱其名曰父。」","sentenceOrder":7},
  {"id":"s_work_han_thu_73_8","chapterId":"ch_work_han_thu_73","textTraditional":"〔七〕　師古曰：「道由匈奴過。」","sentenceOrder":8},
  {"id":"s_work_han_thu_73_9","chapterId":"ch_work_han_thu_73","textTraditional":"居匈奴西，騫因與其屬亡鄉月氏，〔一〕西走數十日〔二〕至大宛。大宛聞漢之饒財，欲通不得，見騫，喜，問欲何之。騫曰：「為漢使月氏而為匈奴所閉道，今亡，唯王使人道送我。〔三〕誠得至，反漢，漢之賂遺王財物不可勝言。」大宛以為然，遣騫，為發譯道，抵康居。〔四〕康居傳致大月氏。大月氏王已為胡所殺，立其夫人為王。既臣大夏而君之，〔五〕地肥饒，少寇，志安樂，又自以遠遠漢，殊無報胡之心。〔六〕騫從月氏至大夏，竟不能得月氏要領。〔七〕","sentenceOrder":9},
  {"id":"s_work_han_thu_73_10","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　師古曰：「屬謂同使之官屬。鄉讀曰嚮。」","sentenceOrder":10},
  {"id":"s_work_han_thu_73_11","chapterId":"ch_work_han_thu_73","textTraditional":"〔二〕　師古曰：「走，趨也。不指知其道里多少，故以日數言之。走音奏。一曰走謂奔走也，讀如本字。」","sentenceOrder":11},
  {"id":"s_work_han_thu_73_12","chapterId":"ch_work_han_thu_73","textTraditional":"〔三〕　師古曰：「道讀曰導。」","sentenceOrder":12},
  {"id":"s_work_han_thu_73_13","chapterId":"ch_work_han_thu_73","textTraditional":"〔四〕　師古曰：「抵，至也。道讀曰導。」","sentenceOrder":13},
  {"id":"s_work_han_thu_73_14","chapterId":"ch_work_han_thu_73","textTraditional":"〔五〕　師古曰：「以大夏為臣，為之作君也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_73_15","chapterId":"ch_work_han_thu_73","textTraditional":"〔六〕　師古曰：「下遠音（千）〔于〕萬反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_73_16","chapterId":"ch_work_han_thu_73","textTraditional":"〔七〕　李奇曰；「要領，要契也。」師古曰：「李說非也。要，衣要也。領，衣領也。凡持衣者則執要與領。言騫不能得月氏意趣，無以持歸於漢，故以要領為喻。要音一遙反。」","sentenceOrder":16},
  {"id":"s_work_han_thu_73_17","chapterId":"ch_work_han_thu_73","textTraditional":"留歲餘，還，並南山，欲從羌中歸，〔一〕復為匈奴所得。留歲餘，單于死，國內亂，騫與胡妻及堂邑父俱亡歸漢。拜騫太中大夫，堂邑父為奉使君。","sentenceOrder":17},
  {"id":"s_work_han_thu_73_18","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　師古曰：「並音步浪反。」","sentenceOrder":18},
  {"id":"s_work_han_thu_73_19","chapterId":"ch_work_han_thu_73","textTraditional":"騫為人彊力，寬大信人，〔一〕蠻夷愛之。堂邑父胡人，善射，窮急射禽獸給食。〔二〕初，騫行時百餘人，去十三歲，唯二人得還。","sentenceOrder":19},
  {"id":"s_work_han_thu_73_20","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　師古曰：「彊力，言堅忍於事。」","sentenceOrder":20},
  {"id":"s_work_han_thu_73_21","chapterId":"ch_work_han_thu_73","textTraditional":"〔二〕　師古曰：「給，供也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_73_22","chapterId":"ch_work_han_thu_73","textTraditional":"騫身所至者，大宛、大月氏、大夏、康居，而傳聞其旁大國五六，具為天子言其地形，所有〔一〕語皆在西域傳。","sentenceOrder":22},
  {"id":"s_work_han_thu_73_23","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　師古曰：「土地之形及所生之物也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_73_24","chapterId":"ch_work_han_thu_73","textTraditional":"騫曰：「臣在大夏時，見邛竹杖、蜀布，〔一〕問安得此，大夏國人曰：『吾賈人往市之身毒國。〔二〕身毒國在大夏東南可數千里。其俗土著，〔三〕與大夏同，同卑溼暑熱。其民乘象以戰。〔四〕其國臨大水焉。』以騫度之，〔五〕大夏去漢萬二千里，居西南。今身毒又居大夏東南數千里，有蜀物，此其去蜀不遠矣。今使大夏，從羌中，險，羌人惡之；少北，則為匈奴所得；從蜀，宜徑，又無寇。」〔六〕天子既聞大宛及大夏、安息之屬皆大國，多奇物，土著，頗與中國同俗，而兵弱，貴漢財物；其北則大月氏、康居之屬，兵彊，可以賂遺設利朝也。〔七〕誠得而以義屬之，〔八〕則廣地萬里，重九譯，致殊俗，威德遍於四海。天子欣欣以騫言為然。乃令因蜀犍為發間使，四道並出：〔九〕出駹，出莋，出徙、邛，出僰，〔一０〕皆各行一二千里。其北方閉氐、莋，〔一一〕南方閉巂、昆明。〔一二〕昆明之屬無君長，善寇盜，輒殺略漢使，終莫得通。然聞其西可千餘里，有乘象國，名滇越，〔一三〕而蜀賈間出物者或至焉，〔一四〕於是漢以求大夏道始通滇國。初，漢欲通西南夷，費多，罷之。及騫言可以通大夏，乃復事西南夷。〔一五〕","sentenceOrder":24},
  {"id":"s_work_han_thu_73_25","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　臣瓚曰：「邛，山名。生此竹，高節，可作杖。」服虔曰：「布，細布也。」師古曰：「邛竹杖，人皆識之，無假多釋。而蘇林乃言節間合而體離，誤後學矣。」","sentenceOrder":25},
  {"id":"s_work_han_thu_73_26","chapterId":"ch_work_han_thu_73","textTraditional":"〔二〕　鄧展曰：「毒音篤。」李奇曰：「一名天篤，則浮屠胡是也。」師古曰：「即敬佛道者。」","sentenceOrder":26},
  {"id":"s_work_han_thu_73_27","chapterId":"ch_work_han_thu_73","textTraditional":"〔三〕　師古曰：「土著者，謂有城郭常居，不隨畜牧移徙也。著音直略反。其下亦同。」","sentenceOrder":27},
  {"id":"s_work_han_thu_73_28","chapterId":"ch_work_han_thu_73","textTraditional":"〔四〕　師古曰：「象，大獸，垂鼻長牙。」","sentenceOrder":28},
  {"id":"s_work_han_thu_73_29","chapterId":"ch_work_han_thu_73","textTraditional":"〔五〕　師古曰：「度，計也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_73_30","chapterId":"ch_work_han_thu_73","textTraditional":"〔六〕　師古曰：「徑，直也。宜猶當也。從蜀向大夏，其道當直。」","sentenceOrder":30},
  {"id":"s_work_han_thu_73_31","chapterId":"ch_work_han_thu_73","textTraditional":"〔七〕　師古曰：「設，施也。施之以利，誘令入朝。」","sentenceOrder":31},
  {"id":"s_work_han_thu_73_32","chapterId":"ch_work_han_thu_73","textTraditional":"〔八〕　師古曰：「謂不以兵革。」","sentenceOrder":32},
  {"id":"s_work_han_thu_73_33","chapterId":"ch_work_han_thu_73","textTraditional":"〔九〕　師古曰：「間使者，求間隙而行。」","sentenceOrder":33},
  {"id":"s_work_han_thu_73_34","chapterId":"ch_work_han_thu_73","textTraditional":"〔一０〕師古曰：「皆夷種名。駹音尨。莋音材各反。徙音斯。僰音蒲（此）〔北〕反。」","sentenceOrder":34},
  {"id":"s_work_han_thu_73_35","chapterId":"ch_work_han_thu_73","textTraditional":"〔一一〕服虔曰：「漢使見閉於夷也。」師古曰：「氐與莋二種也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_73_36","chapterId":"ch_work_han_thu_73","textTraditional":"〔一二〕師古曰：「巂、昆明，亦皆夷種名也。巂音先橤反。」","sentenceOrder":36},
  {"id":"s_work_han_thu_73_37","chapterId":"ch_work_han_thu_73","textTraditional":"〔一三〕服虔曰：「滇音顛。滇（烏）〔馬〕出其國。」","sentenceOrder":37},
  {"id":"s_work_han_thu_73_38","chapterId":"ch_work_han_thu_73","textTraditional":"〔一四〕師古曰：「間出物，謂私往市者。」","sentenceOrder":38},
  {"id":"s_work_han_thu_73_39","chapterId":"ch_work_han_thu_73","textTraditional":"〔一五〕師古曰：「事謂經略通之，專以為事也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_73_40","chapterId":"ch_work_han_thu_73","textTraditional":"騫以校尉從大將軍擊匈奴，知水草處，軍得以不乏，乃封騫為博望侯。〔一〕是歲元朔六年也。後二年，騫為衛尉，與李廣俱出右北平擊匈奴。匈奴圍李將軍，軍失亡多，而騫後期當斬，贖為庶人。是歲驃騎將軍破匈奴西邊，殺數萬人，至祁連山。其秋，渾邪王率眾降漢，而金城、河西（西）並南山至鹽澤，空無匈奴。〔二〕匈奴時有候者到，而希矣。後二年，漢擊走單于於幕北。","sentenceOrder":40},
  {"id":"s_work_han_thu_73_41","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　師古曰：「取其能廣博瞻望。」","sentenceOrder":41},
  {"id":"s_work_han_thu_73_42","chapterId":"ch_work_han_thu_73","textTraditional":"〔二〕　師古曰：「並音步浪反。」","sentenceOrder":42},
  {"id":"s_work_han_thu_73_43","chapterId":"ch_work_han_thu_73","textTraditional":"天子數問騫大夏之屬。騫既失侯，因曰：「臣居匈奴中，聞烏孫王號昆莫。昆莫父難兜靡本與大月氏俱在祁連、焞煌間，小國也〔一〕。大月氏攻殺難兜靡，奪其地，人民亡走匈奴。子昆莫新生，傅父布就翎侯抱亡置草中，〔二〕為求食，還，見狼乳之，〔三〕又烏銜肉翔其旁，以為神，遂持歸匈奴，單于愛養之。及壯，以其父民眾與昆莫，使將兵，數有功。時，月氏已為匈奴所破，西擊塞王。〔四〕塞王南走遠徙，月氏居其地。昆莫既健，自請單于報父怨，遂西攻破大月氏。大月氏復西走，徙大夏地。昆莫略其眾，因留居，兵稍彊，會單于死，不肯復朝事匈奴。匈奴遣兵擊之，不勝，益以為神而遠之。〔五〕今單于新困於漢，而昆莫地空。蠻夷戀故地，又貪漢物，誠以此時厚賂烏孫，招以東居故地，漢遣公主為夫人，結昆弟，其勢宜聽，〔六〕則是斷匈奴右臂也。既連烏孫，自其西大夏之屬皆可招來而為外臣。」天子以為然，拜騫為中郎將，將三百人，馬各二匹，牛羊以萬數，齎金幣帛直數千鉅萬，多持節副使，〔七〕道可便遣之旁國。騫既至烏孫，致賜諭指，〔八〕未能得其決。語在西域傳。騫即分遣副使使大宛、康居、月氏、大夏。烏孫發譯道送騫，〔九〕與烏孫使數十人，馬數十匹，報謝，〔一０〕因令窺漢，知其廣大。","sentenceOrder":43},
  {"id":"s_work_han_thu_73_44","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　師古曰：「祁連山以東，焞煌以西。」","sentenceOrder":44},
  {"id":"s_work_han_thu_73_45","chapterId":"ch_work_han_thu_73","textTraditional":"〔二〕　服虔曰：「傅父，如傅母也。」李奇曰：「布就，字也。翎侯，烏孫官名也。為昆莫作傅父也。」師古曰：「翎侯，烏孫大臣官號，其數非一，亦猶漢之將軍耳。而布就者，又翎侯之中別號，猶右將軍、左將軍耳，非其人之字。翎與翕同。」","sentenceOrder":45},
  {"id":"s_work_han_thu_73_46","chapterId":"ch_work_han_thu_73","textTraditional":"〔三〕　師古曰：「以乳飲之。」","sentenceOrder":46},
  {"id":"s_work_han_thu_73_47","chapterId":"ch_work_han_thu_73","textTraditional":"〔四〕　師古曰：「塞音先得反，西域國名，即佛經所謂釋種者。塞、釋聲相近，本一姓耳。」","sentenceOrder":47},
  {"id":"s_work_han_thu_73_48","chapterId":"ch_work_han_thu_73","textTraditional":"〔五〕　師古曰：「遠，離也，音于萬反。」","sentenceOrder":48},
  {"id":"s_work_han_thu_73_49","chapterId":"ch_work_han_thu_73","textTraditional":"〔六〕　師古曰：「言事事聽從於漢。」","sentenceOrder":49},
  {"id":"s_work_han_thu_73_50","chapterId":"ch_work_han_thu_73","textTraditional":"〔七〕　師古曰：「為騫之副，而各令持節。」","sentenceOrder":50},
  {"id":"s_work_han_thu_73_51","chapterId":"ch_work_han_thu_73","textTraditional":"〔八〕　師古曰：「以天子意指曉告之。」","sentenceOrder":51},
  {"id":"s_work_han_thu_73_52","chapterId":"ch_work_han_thu_73","textTraditional":"〔九〕　師古曰：「道讀曰導。」","sentenceOrder":52},
  {"id":"s_work_han_thu_73_53","chapterId":"ch_work_han_thu_73","textTraditional":"〔一０〕師古曰：「與騫相隨而來，報謝天子。」","sentenceOrder":53},
  {"id":"s_work_han_thu_73_54","chapterId":"ch_work_han_thu_73","textTraditional":"騫還，拜為大行。歲餘，騫卒。後歲餘，其所遣副使通大夏之屬者皆頗與其人俱來，〔一〕於是西北國始通於漢矣。然騫鑿空，〔二〕諸後使往者皆稱博望侯，以為質於外國，〔三〕外國由是信之。其後，烏孫竟與漢結婚。","sentenceOrder":54},
  {"id":"s_work_han_thu_73_55","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　晉灼曰：「其國人。」","sentenceOrder":55},
  {"id":"s_work_han_thu_73_56","chapterId":"ch_work_han_thu_73","textTraditional":"〔二〕　蘇林曰：「鑿，開也。空，通也。騫始開通西域道也。」師古曰：「空，孔也。猶言始鑿其孔穴也。故此下言『當空道』，而西域傳謂『孔道』也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_73_57","chapterId":"ch_work_han_thu_73","textTraditional":"〔三〕　李奇曰：「質，信也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_73_58","chapterId":"ch_work_han_thu_73","textTraditional":"初，天子發書易，〔一〕曰「神馬當從西北來」。得烏孫馬好，名曰「天馬」。及得宛汗血馬，益壯，更名烏孫馬曰「西極馬」，宛馬曰「天馬」云。而漢始築令居以西，〔二〕初置酒泉郡，以通西北國。因益發使抵安息、奄蔡、犛靬、條支、身毒國。〔三〕而天子好宛馬，使者相望於道，一輩大者數百，少者百餘人，所齎操，大放博望侯時。〔四〕其後益習而衰少焉。〔五〕漢率一歲中使者多者十餘，少者五六輩，遠者八九歲，近者數歲而反。〔六〕","sentenceOrder":58},
  {"id":"s_work_han_thu_73_59","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　鄧展曰：「發易書以卜。」","sentenceOrder":59},
  {"id":"s_work_han_thu_73_60","chapterId":"ch_work_han_thu_73","textTraditional":"〔二〕　臣瓚曰：「令居，縣名也，屬金城。築塞西至酒泉也。」師古曰：「令音零。」","sentenceOrder":60},
  {"id":"s_work_han_thu_73_61","chapterId":"ch_work_han_thu_73","textTraditional":"〔三〕　李奇曰：「靬音軒。」服虔曰：「犛靬，張掖縣名也。」師古曰：「抵，至也。自安息以下五國皆西域胡也。犛靬即大秦國也。張掖驪靬縣蓋取此國為名耳。驪犛聲相近。靬讀與軒同。李奇音是也，服說非也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_73_62","chapterId":"ch_work_han_thu_73","textTraditional":"〔四〕　師古曰：「操，持也。所齎持，謂節及幣也。放，依也，音甫往反。」","sentenceOrder":62},
  {"id":"s_work_han_thu_73_63","chapterId":"ch_work_han_thu_73","textTraditional":"〔五〕　師古曰：「以其串習，故不多發人。」","sentenceOrder":63},
  {"id":"s_work_han_thu_73_64","chapterId":"ch_work_han_thu_73","textTraditional":"〔六〕　師古曰：「道遠則還遲，近則來疾。」","sentenceOrder":64},
  {"id":"s_work_han_thu_73_65","chapterId":"ch_work_han_thu_73","textTraditional":"是時，漢既滅越，蜀所通西南夷皆震，請吏。置牂柯、越巂、益州、沈黎、文山郡，欲地接以前通大夏。〔一〕乃遣使歲十餘輩，出此初郡，〔二〕皆復閉昆明，〔三〕為所殺，奪幣物。於是漢發兵擊昆明，斬首數萬。後復遣使，竟不得通。語在西南夷傳。","sentenceOrder":65},
  {"id":"s_work_han_thu_73_66","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　李奇曰：「欲地界相接至大夏也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_73_67","chapterId":"ch_work_han_thu_73","textTraditional":"〔二〕　師古曰：「文山以上初置者。」","sentenceOrder":67},
  {"id":"s_work_han_thu_73_68","chapterId":"ch_work_han_thu_73","textTraditional":"〔三〕　如淳曰：「為昆明所閉。」","sentenceOrder":68},
  {"id":"s_work_han_thu_73_69","chapterId":"ch_work_han_thu_73","textTraditional":"自騫開外國道以尊貴，其吏士爭上書言外國奇怪利害，求使。天子為其絕遠，非人所樂，聽其言，〔一〕予節，募吏民無問所從來，〔二〕為具備人眾遣之，以廣其道。來還不能無侵盜幣物，及使失指，〔三〕天子為其習之，輒覆按致重罪，〔四〕以激怒令贖，〔五〕復求使。使端無窮，而輕犯法。其吏卒亦輒復盛推外國所有，言大者予節，言小者為副，故妄言無行之徒皆爭相效。其使皆私縣官齎物，〔六〕欲賤市以私其利。〔七〕外國亦厭漢使人人有言輕重，〔八〕度漢兵遠，不能至，〔九〕而禁其食物，以苦漢使。〔一０〕漢使乏絕，責怨，至相攻擊。樓蘭、姑師小國，當空道，〔一一〕攻劫漢使王恢等尤甚。而匈奴奇兵又時時遮擊之。使者爭言外國利害，〔一二〕皆有城邑，兵弱易擊。於是天子遣從票侯破奴〔一三〕將屬國騎及郡兵數萬以擊胡，胡皆去。明年，擊破姑師，虜樓蘭王。酒泉列亭鄣至玉門矣。〔一四〕","sentenceOrder":69},
  {"id":"s_work_han_thu_73_70","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　師古曰：「凡人皆不樂去，故有自請為使者，即聽而遣之。」","sentenceOrder":70},
  {"id":"s_work_han_thu_73_71","chapterId":"ch_work_han_thu_73","textTraditional":"〔二〕　師古曰：「不為限禁遠近，雖家人私隸並許應募。」","sentenceOrder":71},
  {"id":"s_work_han_thu_73_72","chapterId":"ch_work_han_thu_73","textTraditional":"〔三〕　師古曰：「乖天子指意。」","sentenceOrder":72},
  {"id":"s_work_han_thu_73_73","chapterId":"ch_work_han_thu_73","textTraditional":"〔四〕　師古曰：「言其串習，不以為難，必當更求充使也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_73_74","chapterId":"ch_work_han_thu_73","textTraditional":"〔五〕　師古曰：「令立功以贖罪。」","sentenceOrder":74},
  {"id":"s_work_han_thu_73_75","chapterId":"ch_work_han_thu_73","textTraditional":"〔六〕　師古曰：「言所齎官物，竊自用之，同於私有。」","sentenceOrder":75},
  {"id":"s_work_han_thu_73_76","chapterId":"ch_work_han_thu_73","textTraditional":"〔七〕　師古曰：「所市之物，得利多者，不盡入官也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_73_77","chapterId":"ch_work_han_thu_73","textTraditional":"〔八〕　服虔曰：「漢使言於外國，人人輕重不實。」","sentenceOrder":77},
  {"id":"s_work_han_thu_73_78","chapterId":"ch_work_han_thu_73","textTraditional":"〔九〕　師古曰：「度，計也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_73_79","chapterId":"ch_work_han_thu_73","textTraditional":"〔一０〕師古曰：「令其困苦也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_73_80","chapterId":"ch_work_han_thu_73","textTraditional":"〔一一〕師古曰：「空即孔也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_73_81","chapterId":"ch_work_han_thu_73","textTraditional":"〔一二〕師古曰：「言服之則利，不討則為害。」","sentenceOrder":81},
  {"id":"s_work_han_thu_73_82","chapterId":"ch_work_han_thu_73","textTraditional":"〔一三〕師古曰：「趙破奴。」","sentenceOrder":82},
  {"id":"s_work_han_thu_73_83","chapterId":"ch_work_han_thu_73","textTraditional":"〔一四〕韋昭曰：「玉門關在龍勒界。」","sentenceOrder":83},
  {"id":"s_work_han_thu_73_84","chapterId":"ch_work_han_thu_73","textTraditional":"而大宛諸國發使隨漢使來，觀漢廣大，以大鳥卵及犛靬眩人獻於漢，〔一〕天子大說。〔二〕而漢使窮河源，其山多玉石，采來〔三〕，天子案古圖書，名河所出山曰昆侖云。","sentenceOrder":84},
  {"id":"s_work_han_thu_73_85","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　應劭曰：「卵大如一二石｛雝缶｝也。眩，相詐惑也。鄧太后時，西夷檀國來朝賀，詔令為之。而諫大夫陳禪以為夷狄偽道不可施行。後數日，尚書陳忠案漢舊書，乃知世宗時犛靬獻見幻人，天子大悅，與俱巡狩，乃知古有此事。」師古曰：「鳥卵如汲水之｛雝缶｝耳，無一二石也。應說失之。眩讀與幻同。即今吞刀吐火，植瓜種樹，屠人截馬之術皆是也。本從西域來。｛雝缶｝音瓮。」","sentenceOrder":85},
  {"id":"s_work_han_thu_73_86","chapterId":"ch_work_han_thu_73","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":86},
  {"id":"s_work_han_thu_73_87","chapterId":"ch_work_han_thu_73","textTraditional":"〔三〕　臣瓚曰：「漢使采取持來至漢。」","sentenceOrder":87},
  {"id":"s_work_han_thu_73_88","chapterId":"ch_work_han_thu_73","textTraditional":"是時，上方數巡狩海上，乃悉從外國客，大都多人則過之，散財帛賞賜，厚具饒給之，以覽視漢富厚焉。〔一〕大角氐，〔二〕出奇戲諸怪物，多聚觀者，〔三〕行賞賜，酒池肉林，令外國客遍觀各倉庫府臧之積，欲以見漢廣大，傾駭之。〔四〕及加其眩者之工，而角氐奇戲歲增變，其益興，自此始。而外國使更來更去。〔五〕大宛以西皆自恃遠，尚驕恣，未可詘以禮羈縻而使也。","sentenceOrder":88},
  {"id":"s_work_han_thu_73_89","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　師古曰：「視讀曰示。言示之令其觀覽。」","sentenceOrder":89},
  {"id":"s_work_han_thu_73_90","chapterId":"ch_work_han_thu_73","textTraditional":"〔二〕　師古曰：「氐音丁禮反。解在武紀。」","sentenceOrder":90},
  {"id":"s_work_han_thu_73_91","chapterId":"ch_work_han_thu_73","textTraditional":"〔三〕　師古曰：「聚都邑人，令觀看，以誇示之。觀音工喚反。」","sentenceOrder":91},
  {"id":"s_work_han_thu_73_92","chapterId":"ch_work_han_thu_73","textTraditional":"〔四〕　師古曰：「見，顯示。」","sentenceOrder":92},
  {"id":"s_work_han_thu_73_93","chapterId":"ch_work_han_thu_73","textTraditional":"〔五〕　師古曰：「遞互來去，前後不絕。更音工衡反。」","sentenceOrder":93},
  {"id":"s_work_han_thu_73_94","chapterId":"ch_work_han_thu_73","textTraditional":"漢使往既多，其少從率進孰於天子，〔一〕言大宛有善馬在貳師城，匿不肯示漢使。天子既好宛馬，聞之甘心，〔二〕使壯士車令等持千金及金馬以請宛王貳師城善馬。宛國饒漢物，〔三〕相與謀曰：「漢去我遠，而鹽水中數有敗，〔四〕出其北有胡寇，出其南乏水草，又且往往而絕邑，〔五〕乏食者多。漢使數百人為輩來，常乏食，死者過半，是安能致大軍乎？且貳師馬，宛寶馬也。」遂不肯予漢使。漢使怒，妄言，椎金馬而去。〔六〕宛中貴人怒曰：〔七〕「漢使至輕我！」遣漢使去，令其東邊郁成王遮攻，殺漢使，取其財物。天子大怒。諸嘗使宛姚定漢等言：「宛兵弱，誠以漢兵不過三千人，強弩射之，即破宛矣。」天子以嘗使浞野侯攻樓蘭，以七百騎先至，虜其王，以定漢等言為然，而欲侯寵姬李氏，〔八〕乃以李廣利為將軍，伐宛。","sentenceOrder":94},
  {"id":"s_work_han_thu_73_95","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　孟康曰：「少從，不如計也。或曰，少者，少年從行之微者也。進孰，美語如成孰也。」晉灼曰：「多進虛美之言必成之計於天子，而率不果也。」師古曰：「漢時謂隨使而出外國者為少從，總言其少年而從使也。從音材用反。事見班固與弟仲升書。進孰者，但空進成孰之言。」","sentenceOrder":95},
  {"id":"s_work_han_thu_73_96","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　師古曰：「志懷美悅，專事求之。」","sentenceOrder":96},
  {"id":"s_work_han_thu_73_97","chapterId":"ch_work_han_thu_73","textTraditional":"〔三〕　師古曰：「素有漢地財物，故不貪金馬之幣。」","sentenceOrder":97},
  {"id":"s_work_han_thu_73_98","chapterId":"ch_work_han_thu_73","textTraditional":"〔四〕　服虔曰：「水名，道從水中行。」師古曰：「沙磧之中不生草木，水又鹹苦，即今敦煌西北惡磧者也。數有敗，言每自死亡也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_73_99","chapterId":"ch_work_han_thu_73","textTraditional":"〔五〕　師古曰：「言近道之處無城郭之居也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_73_100","chapterId":"ch_work_han_thu_73","textTraditional":"〔六〕　如淳曰：「罵詈也。」師古曰：「椎破金馬也。椎音直追反，其字從木。」","sentenceOrder":100},
  {"id":"s_work_han_thu_73_101","chapterId":"ch_work_han_thu_73","textTraditional":"〔七〕　師古曰：「中貴人，中臣之貴者。」","sentenceOrder":101},
  {"id":"s_work_han_thu_73_102","chapterId":"ch_work_han_thu_73","textTraditional":"〔八〕　師古曰：「欲封其兄弟。」","sentenceOrder":102},
  {"id":"s_work_han_thu_73_103","chapterId":"ch_work_han_thu_73","textTraditional":"騫孫猛，字子游，有俊才，元帝時為光祿大夫，使匈奴，給事中，為石顯所譖，自殺。","sentenceOrder":103},
  {"id":"s_work_han_thu_73_104","chapterId":"ch_work_han_thu_73","textTraditional":"李廣利，女弟李夫人有寵於上，產昌邑哀王。太初元年，以廣利為貳師將軍，發屬國六千騎及郡國惡少年數萬人以往，〔一〕期至貳師城取善馬，故號「貳師將軍」。故浩侯王恢使道軍。既西過鹽水，當道小國各堅城守，不肯給食，攻之不能下。下者得食，不下者數日則去。比至郁成，士財有數千，〔二〕皆飢罷〔三〕攻郁成城，郁成距之，所殺傷甚眾。貳師將軍與左右計：「至郁成尚不能舉，況至其王都乎？」引而還。往來二歲，至敦煌，士不過什一二。〔四〕使使上書言：「道遠，多乏食，且士卒不患戰而患飢。人少，不足以拔宛。願且罷兵，益發而復往。」〔五〕天子聞之，大怒，使使遮玉門關，曰：「軍有敢入，斬之。」貳師恐，因留屯敦煌。","sentenceOrder":104},
  {"id":"s_work_han_thu_73_105","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　師古曰：「惡少年謂無行義者。」","sentenceOrder":105},
  {"id":"s_work_han_thu_73_106","chapterId":"ch_work_han_thu_73","textTraditional":"〔二〕　師古曰：「比音必寐反。財與才同。」","sentenceOrder":106},
  {"id":"s_work_han_thu_73_107","chapterId":"ch_work_han_thu_73","textTraditional":"〔三〕　師古曰：「罷讀曰疲。」","sentenceOrder":107},
  {"id":"s_work_han_thu_73_108","chapterId":"ch_work_han_thu_73","textTraditional":"〔四〕　師古曰：「十人之中，一二人得還。」","sentenceOrder":108},
  {"id":"s_work_han_thu_73_109","chapterId":"ch_work_han_thu_73","textTraditional":"〔五〕　師古曰：「益，多也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_73_110","chapterId":"ch_work_han_thu_73","textTraditional":"其夏，漢亡浞野之兵二萬餘於匈奴，〔一〕公卿議者皆願罷宛軍，專力攻胡。天子業出兵誅宛，宛小國而不能下，則大夏之屬漸輕漢，而宛善馬絕不來，烏孫、輪臺易苦漢使，〔二〕為外國笑。乃案言伐宛尤不便者鄧光等。〔三〕赦囚徒扞寇盜，〔四〕發惡少年及邊騎，歲餘而出敦煌六萬人，〔五〕負私從者不與。〔六〕牛十萬，馬三萬匹，驢橐駝以萬數齎糧，兵弩甚設。〔七〕天下騷動，轉相奉伐宛，五十餘校尉。宛城中無井，汲城外流水，於是遣水工徙其城下水空以穴其城。〔八〕益發戍甲卒十八萬酒泉、張掖北，置居延、休屠以衛酒泉。〔九〕而發天下七科適，〔一０〕及載糒給貳師，〔一一〕轉車人徒相連屬至敦煌。〔一二〕而拜習馬者二人為執驅馬校尉〔一三〕，備破宛擇取其善馬云。","sentenceOrder":110},
  {"id":"s_work_han_thu_73_111","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　師古曰：「趙破奴後封浞野侯。浞音士角反。」","sentenceOrder":111},
  {"id":"s_work_han_thu_73_112","chapterId":"ch_work_han_thu_73","textTraditional":"〔二〕　晉灼曰：「易，輕也。」師古曰：「輪臺亦國名。」","sentenceOrder":112},
  {"id":"s_work_han_thu_73_113","chapterId":"ch_work_han_thu_73","textTraditional":"〔三〕　師古曰：「案其罪而行罰。」","sentenceOrder":113},
  {"id":"s_work_han_thu_73_114","chapterId":"ch_work_han_thu_73","textTraditional":"〔四〕　如淳曰：「放囚（徙）〔徒〕使其扞御寇盜。」師古曰：「使從軍為斥侯。」","sentenceOrder":114},
  {"id":"s_work_han_thu_73_115","chapterId":"ch_work_han_thu_73","textTraditional":"〔五〕　師古曰：「興發部署，歲餘乃得行。」","sentenceOrder":115},
  {"id":"s_work_han_thu_73_116","chapterId":"ch_work_han_thu_73","textTraditional":"〔六〕　師古曰：「負私糧食及私從者，不在六萬人數中也。與讀曰豫。」","sentenceOrder":116},
  {"id":"s_work_han_thu_73_117","chapterId":"ch_work_han_thu_73","textTraditional":"〔七〕　師古曰：「施張甚具也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_73_118","chapterId":"ch_work_han_thu_73","textTraditional":"〔八〕　師古曰：「空，孔也。徙其城下水者，令從他道流，不迫其城也。空以穴其城者，圍而攻之，令作孔使穿穴也。下云『決其水原移之』，又云『圍其城攻之』，皆再敘其事也。一曰，既徙其水，不令於城下流，而因其舊引水入城之孔，攻而穴之。」","sentenceOrder":118},
  {"id":"s_work_han_thu_73_119","chapterId":"ch_work_han_thu_73","textTraditional":"〔九〕　如淳曰：「立二縣以衛邊也。或曰置二部都尉。」","sentenceOrder":119},
  {"id":"s_work_han_thu_73_120","chapterId":"ch_work_han_thu_73","textTraditional":"〔一０〕師古曰：「適讀曰謫。七科，解在武紀。」","sentenceOrder":120},
  {"id":"s_work_han_thu_73_121","chapterId":"ch_work_han_thu_73","textTraditional":"〔一一〕師古曰：「糒，乾飯，音備。」","sentenceOrder":121},
  {"id":"s_work_han_thu_73_122","chapterId":"ch_work_han_thu_73","textTraditional":"〔一二〕師古曰：「屬音之欲反。」","sentenceOrder":122},
  {"id":"s_work_han_thu_73_123","chapterId":"ch_work_han_thu_73","textTraditional":"〔一三〕師古曰：「習猶便也。一人為執馬校尉，一人為驅馬校尉。」","sentenceOrder":123},
  {"id":"s_work_han_thu_73_124","chapterId":"ch_work_han_thu_73","textTraditional":"於是貳師後復行，兵多，所至小國莫不迎，出食給軍。至輪臺，輪臺不下，攻數日，屠之。自此而西，平行至宛城，〔一〕兵到者三萬。宛兵迎擊漢兵，漢兵射敗之，宛兵走入保其城。貳師欲攻郁成城，恐留行而令宛益生詐，〔二〕乃先至宛，決其水原，移之，則宛固已憂困。圍其城，攻之四十餘日。宛貴人謀曰：「王毋寡匿善馬，殺漢使。〔三〕今殺王而出善馬，漢兵宜解；即不，乃力戰而死，未晚也。」宛貴人皆以為然，共殺王。其外城壞，虜宛貴人勇將煎靡〔四〕。宛大怨，走入中城，相與謀曰：「漢所為攻宛，以王毋寡。」持其頭，遣人使貳師，約曰：「漢無攻我，我盡出善馬，恣所取，而給漢軍食。即不聽我，我盡殺善馬，康居之救又且至。至，我居內，康居居外，與漢軍戰。孰計之，何從？」〔五〕是時，康居候視漢兵尚盛，不敢進。貳師聞宛城中新得漢人知穿井，而其內食尚多。計以為來誅首惡者毋寡，毋寡頭已至，如此不許，則堅守，而康居候漢兵罷來救宛，破漢軍必矣。〔六〕軍吏皆以為然，許宛之約。宛乃出其馬，令漢自擇之，而多出食食漢軍。〔七〕漢軍取其善馬數十匹，中馬以下牝牡三千餘匹，而立宛貴人之故時遇漢善者名昧蔡為宛王，〔八〕與盟而罷兵。終不得入中城，罷而引歸。","sentenceOrder":124},
  {"id":"s_work_han_thu_73_125","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　師古曰：「平行，言無寇難。」","sentenceOrder":125},
  {"id":"s_work_han_thu_73_126","chapterId":"ch_work_han_thu_73","textTraditional":"〔二〕　師古曰：「留行謂留止軍廢其行。」","sentenceOrder":126},
  {"id":"s_work_han_thu_73_127","chapterId":"ch_work_han_thu_73","textTraditional":"〔三〕　師古曰：「毋寡，宛王名。」","sentenceOrder":127},
  {"id":"s_work_han_thu_73_128","chapterId":"ch_work_han_thu_73","textTraditional":"〔四〕　師古曰：「宛之貴人為將而勇者名煎靡也。煎音子延反。」","sentenceOrder":128},
  {"id":"s_work_han_thu_73_129","chapterId":"ch_work_han_thu_73","textTraditional":"〔五〕　師古曰：「令貳師孰計之，而欲攻戰乎？欲不攻而取馬乎？」","sentenceOrder":129},
  {"id":"s_work_han_thu_73_130","chapterId":"ch_work_han_thu_73","textTraditional":"〔六〕　師古曰：「罷讀曰疲。」","sentenceOrder":130},
  {"id":"s_work_han_thu_73_131","chapterId":"ch_work_han_thu_73","textTraditional":"〔七〕　師古曰：「下食讀曰飤。」","sentenceOrder":131},
  {"id":"s_work_han_thu_73_132","chapterId":"ch_work_han_thu_73","textTraditional":"〔八〕　服虔曰：「蔡音楚言蔡。」師古曰：「昧音本末之末。蔡音千曷反。」","sentenceOrder":132},
  {"id":"s_work_han_thu_73_133","chapterId":"ch_work_han_thu_73","textTraditional":"初，貳師起敦煌西，為人多，道上國不能食，〔一〕分為數軍，從南北道。校尉王申生、故鴻臚壺充國等千餘人別至郁成，城守不肯給食。申生去大軍二百里，負而輕之，〔二〕攻郁成急。郁成窺知申生軍少，晨用三千人攻殺申生等，數人脫亡，走貳師。〔三〕貳師令搜粟都尉上官桀往攻破郁成，郁成降。其王亡走康居，桀追至康居。康居聞漢已破宛，出郁成王與桀。桀令四騎士縛守詣大將軍。〔四〕四人相謂：「郁成，漢所毒，〔五〕今生將，卒失大事。」〔六〕欲殺，莫適先擊。〔七〕上邽騎士趙弟拔劍擊斬郁成王。桀等遂追及大將軍。","sentenceOrder":133},
  {"id":"s_work_han_thu_73_134","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　師古曰：「起，發也。道上國，近道諸國也。食讀曰飤。」","sentenceOrder":134},
  {"id":"s_work_han_thu_73_135","chapterId":"ch_work_han_thu_73","textTraditional":"〔二〕　師古曰：「負，恃也，恃大軍之威而輕敵人。」","sentenceOrder":135},
  {"id":"s_work_han_thu_73_136","chapterId":"ch_work_han_thu_73","textTraditional":"〔三〕　師古曰：「走音奏。」","sentenceOrder":136},
  {"id":"s_work_han_thu_73_137","chapterId":"ch_work_han_thu_73","textTraditional":"〔四〕　如淳曰：「時多別將，故謂貳師為大將軍。」","sentenceOrder":137},
  {"id":"s_work_han_thu_73_138","chapterId":"ch_work_han_thu_73","textTraditional":"〔五〕　師古曰：「言毒恨。」","sentenceOrder":138},
  {"id":"s_work_han_thu_73_139","chapterId":"ch_work_han_thu_73","textTraditional":"〔六〕　師古曰：「卒讀曰猝。」","sentenceOrder":139},
  {"id":"s_work_han_thu_73_140","chapterId":"ch_work_han_thu_73","textTraditional":"〔七〕　師古曰：「適，主也。無有主意先擊者也。音丁歷反。」","sentenceOrder":140},
  {"id":"s_work_han_thu_73_141","chapterId":"ch_work_han_thu_73","textTraditional":"初，貳師後行，天子使使告烏孫大發兵擊宛。烏孫發二千騎往，持兩端，不肯前。貳師將軍之東，〔一〕諸所過小國聞宛破，皆使其子弟從入貢獻，見天子，因為質焉。軍還，入玉門者萬餘人，馬千餘匹。後行，非乏食，戰死不甚多，而將吏貪，不愛卒，侵牟之，以此物故者眾。〔二〕天子為萬里而伐，不錄其過，乃下詔曰：「匈奴為害久矣，今雖徙幕北，與帝國謀共要絕大月氏使，遮殺中郎將江、故雁門守攘。危須以西及大宛皆合約殺期門車令、〔三〕中郎將朝及身毒國使，隔東西道。貳師將軍廣利征討厥罪，伐勝大宛。賴天之靈，從泝河山，涉流沙，通西海，山雪不積，〔四〕士大夫徑度，〔五〕獲王首虜，珍怪之物畢陳於闕。其封廣利為海西侯，食邑八千戶。」又封斬郁成王者趙弟為新畤侯；軍正趙始成功最多，為光祿大夫；上官桀敢深入，為少府；李哆有計謀，為上黨太守。〔六〕軍官吏為九卿者三人，諸侯相、郡守、二千石百餘人，千石以下千餘人。奮行者官過其望，〔七〕以適過行者皆黜其勞。〔八〕士卒賜直四萬錢〔九〕。伐宛再反，〔一０〕凡四歲而得罷焉。","sentenceOrder":141},
  {"id":"s_work_han_thu_73_142","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　師古曰：「東，旋軍東出。」","sentenceOrder":142},
  {"id":"s_work_han_thu_73_143","chapterId":"ch_work_han_thu_73","textTraditional":"〔二〕　師古曰：「侵牟，言如牟賊之食苗也。物故，謂死也。解具在景紀及蘇武傳。」","sentenceOrder":143},
  {"id":"s_work_han_thu_73_144","chapterId":"ch_work_han_thu_73","textTraditional":"〔三〕　服虔曰：「危須，國名也。」文穎曰：「漢使期門郎也，車令，姓名也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_73_145","chapterId":"ch_work_han_thu_73","textTraditional":"〔四〕　張晏曰：「是歲雪少，故得往還，喜得天人之應也。」師古曰：「從，由也。泝，逆流而上也。言路由山險，又泝河也。泝音素。」","sentenceOrder":145},
  {"id":"s_work_han_thu_73_146","chapterId":"ch_work_han_thu_73","textTraditional":"〔五〕　師古曰：「言無屯難也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_73_147","chapterId":"ch_work_han_thu_73","textTraditional":"〔六〕　師古曰：「哆音昌野反。」","sentenceOrder":147},
  {"id":"s_work_han_thu_73_148","chapterId":"ch_work_han_thu_73","textTraditional":"〔七〕　孟康曰：「奮，迅也。自樂而行者。」","sentenceOrder":148},
  {"id":"s_work_han_thu_73_149","chapterId":"ch_work_han_thu_73","textTraditional":"〔八〕　師古曰：「適讀曰謫。言以罪謫而行者，免其所犯，不敘功勞。」","sentenceOrder":149},
  {"id":"s_work_han_thu_73_150","chapterId":"ch_work_han_thu_73","textTraditional":"〔九〕　師古曰：「或以他財物充之，故云直。」","sentenceOrder":150},
  {"id":"s_work_han_thu_73_151","chapterId":"ch_work_han_thu_73","textTraditional":"〔一０〕師古曰：「再反猶今言兩迴。」","sentenceOrder":151},
  {"id":"s_work_han_thu_73_152","chapterId":"ch_work_han_thu_73","textTraditional":"後十一歲，征和三年，貳師復將七萬騎出五原，擊匈奴，度郅居水。〔一〕兵敗，降匈奴，為單于所殺。語在匈奴傳。","sentenceOrder":152},
  {"id":"s_work_han_thu_73_153","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　師古曰：「郅音質。」","sentenceOrder":153},
  {"id":"s_work_han_thu_73_154","chapterId":"ch_work_han_thu_73","textTraditional":"贊曰：「禹本紀言河出昆侖，昆侖高二千五百里餘，日月所相避隱為光明也。自張騫使大夏之後，窮河原，惡睹所謂昆侖者乎？〔一〕故言九州山川，尚書近之矣。至禹本紀、山經所有，放哉！〔二〕","sentenceOrder":154},
  {"id":"s_work_han_thu_73_155","chapterId":"ch_work_han_thu_73","textTraditional":"〔一〕　鄧展曰：「漢以窮河原，於何見昆侖乎？尚書曰『道河積石』，是謂河原出於積石。積石在金城河關，不言出昆侖也。」師古曰：「惡音烏。」","sentenceOrder":155},
  {"id":"s_work_han_thu_73_156","chapterId":"ch_work_han_thu_73","textTraditional":"〔二〕　如淳曰：「放蕩迂闊，不可信也。」師古曰：「如說是也。荀悅誤以放為效字，因解為不效，蓋失之矣。」","sentenceOrder":156},
  {"id":"s_work_han_thu_73_157","chapterId":"ch_work_han_thu_73","textTraditional":"校勘記","sentenceOrder":157},
  {"id":"s_work_han_thu_73_158","chapterId":"ch_work_han_thu_73","textTraditional":"二六八八頁一六行　下遠音（千）〔于〕萬反。　景祐、殿、局本都作「于」，此誤。","sentenceOrder":158},
  {"id":"s_work_han_thu_73_159","chapterId":"ch_work_han_thu_73","textTraditional":"二六九一頁　三行　僰音蒲（此）〔北〕反。　景祐、殿、局本都作「北」，此誤。","sentenceOrder":159},
  {"id":"s_work_han_thu_73_160","chapterId":"ch_work_han_thu_73","textTraditional":"二六九一頁　六行　滇（烏）〔馬〕出其國。　景祐、殿本都作「馬」。王先謙說作「馬」是。","sentenceOrder":160},
  {"id":"s_work_han_thu_73_161","chapterId":"ch_work_han_thu_73","textTraditional":"二六九一頁一二行　而金城、河西（西）並南山至鹽澤，　景祐、殿本都無下「西」字，史記大宛傳有。","sentenceOrder":161},
  {"id":"s_work_han_thu_73_162","chapterId":"ch_work_han_thu_73","textTraditional":"二七００頁一０行　放囚（徙）〔徒〕使其扞御寇盜。　景祐、殿本都作「徒」，此誤。","sentenceOrder":162},
  {"id":"s_work_han_thu_74_1","chapterId":"ch_work_han_thu_74","textTraditional":"昔在顓頊，命南正重司天，火正黎司地。〔一〕唐虞之際，紹重黎之後，使復典之，至于夏商，故重黎氏世序天地。其在周，程伯休甫其後也。〔二〕當宣王時，官失其守而為司馬氏。〔三〕司馬氏世典周史。惠襄之間，司馬氏適晉。〔四〕晉中軍隨會奔魏，〔五〕而司馬氏入少梁。〔六〕","sentenceOrder":1},
  {"id":"s_work_han_thu_74_2","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　張晏曰：「南方，陽也。火，水配也。水為陰，故命南正重主天，火正黎兼地職也。」臣瓚曰：「重、黎，司天地之官也。唐虞謂之羲和，則司地者宜曰北正。古文作北正。」師古曰：「瓚說非也。據班氏幽通賦云『黎淳燿於高辛』，則此為火正是也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_74_3","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　應劭曰：「封為程國伯。休甫，字也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_74_4","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　師古曰：「失其〔所〕守之職也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_74_5","chapterId":"ch_work_han_thu_74","textTraditional":"〔四〕　張晏曰：「周惠王、襄王有子頹、叔帶之難，故司馬氏奔晉也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_74_6","chapterId":"ch_work_han_thu_74","textTraditional":"〔五〕　如淳曰：「左氏傳晉偽使魏壽餘誘士會於秦譟而還時也。」師古曰：「犇，古奔字也。據春秋，隨會奔秦，其後自秦入魏而還晉。今此言隨會奔魏，司馬氏因入少梁，則似謂自晉出奔魏耳。但魏國在獻公時已滅為邑，封畢萬矣。既非別國，不得言奔。未詳遷之所說。」","sentenceOrder":6},
  {"id":"s_work_han_thu_74_7","chapterId":"ch_work_han_thu_74","textTraditional":"〔六〕　師古曰：「少梁，本梁國也，為秦所滅，號為少梁。」","sentenceOrder":7},
  {"id":"s_work_han_thu_74_8","chapterId":"ch_work_han_thu_74","textTraditional":"自司馬氏去周適晉，分散，或在衛，或在趙，或在秦。其在衛者，相中山。〔一〕在趙者，以傳劍論顯，〔二〕蒯聵其後也。〔三〕在秦者錯，與張儀爭論，〔四〕於是惠王使錯將兵伐蜀，遂拔，因而守之。〔五〕錯孫蘄，〔六〕事武安君白起。而少梁更名夏陽。蘄與武安君阬趙長平軍，〔七〕還而與之俱賜死杜郵，〔八〕葬於華池。〔九〕蘄孫昌，為秦王鐵官。當始皇之時，蒯聵玄孫卬為武信君將而徇朝歌。〔一０〕諸侯之相王，王卬於殷。〔一一〕漢之伐楚，卬歸漢，以其地為河內郡。昌生毋懌，〔一二〕毋懌為漢市長。毋懌生喜，喜為五大夫，卒，皆葬高門。〔一三〕喜生談，談為太史公。〔一四〕","sentenceOrder":8},
  {"id":"s_work_han_thu_74_9","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　張宴曰：「司馬喜為中山相。」","sentenceOrder":9},
  {"id":"s_work_han_thu_74_10","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　服虔曰：「世善劍也。」師古曰：「劍論，劍術之論也。論，來頓反。」","sentenceOrder":10},
  {"id":"s_work_han_thu_74_11","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　如淳曰：「刺客傳之蒯聵也。」師古曰：「蒯，苦怪反。聵，五怪反。」","sentenceOrder":11},
  {"id":"s_work_han_thu_74_12","chapterId":"ch_work_han_thu_74","textTraditional":"〔四〕　應劭曰：「秦惠王欲伐蜀，張儀曰不如伐韓，司馬錯以當先伐蜀。惠王從之，起兵伐蜀取之。」師古曰：「錯音千（古）〔各〕反。」","sentenceOrder":12},
  {"id":"s_work_han_thu_74_13","chapterId":"ch_work_han_thu_74","textTraditional":"〔五〕　蘇林曰：「為郡守。」","sentenceOrder":13},
  {"id":"s_work_han_thu_74_14","chapterId":"ch_work_han_thu_74","textTraditional":"〔六〕　師古曰：「音祈。」","sentenceOrder":14},
  {"id":"s_work_han_thu_74_15","chapterId":"ch_work_han_thu_74","textTraditional":"〔七〕　文穎曰：「趙孝成王時，趙括為將。」","sentenceOrder":15},
  {"id":"s_work_han_thu_74_16","chapterId":"ch_work_han_thu_74","textTraditional":"〔八〕　李奇曰：「地名，在咸陽西十里。」師古曰：「郵音尤。」","sentenceOrder":16},
  {"id":"s_work_han_thu_74_17","chapterId":"ch_work_han_thu_74","textTraditional":"〔九〕　晉灼曰：「池名也，在鄠縣。」師古曰：「晉說非也。華池在左馮翊界，近夏陽，非鄠縣。」","sentenceOrder":17},
  {"id":"s_work_han_thu_74_18","chapterId":"ch_work_han_thu_74","textTraditional":"〔一０〕師古曰：「武信君即武臣也，未為趙王之前號武信君。項籍傳曰『趙將司馬卬』，是知為武臣之將也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_74_19","chapterId":"ch_work_han_thu_74","textTraditional":"〔一一〕師古曰：「項羽封卬為殷王。」","sentenceOrder":19},
  {"id":"s_work_han_thu_74_20","chapterId":"ch_work_han_thu_74","textTraditional":"〔一二〕師古曰：「懌，弋赤反。」","sentenceOrder":20},
  {"id":"s_work_han_thu_74_21","chapterId":"ch_work_han_thu_74","textTraditional":"〔一三〕蘇林曰：「長安北門也。」師古曰：「蘇說非也。高門，地名，在夏陽西北，而東去華池三里。」","sentenceOrder":21},
  {"id":"s_work_han_thu_74_22","chapterId":"ch_work_han_thu_74","textTraditional":"〔一四〕如淳曰：「漢儀注太史公，武帝置，位在丞相上。天下計書先上太史公，副上丞相，序事如古春秋。遷死後，宣帝以其官為令，行太史公文書而已。」晉灼曰：「百官表無太史公在丞相上。又衛宏所說多不實，未可以為正。」師古曰：「談為太史令耳，遷尊其父，故謂之為公。如說非也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_74_23","chapterId":"ch_work_han_thu_74","textTraditional":"太史公學天官於唐都，〔一〕受易於楊何，〔二〕習道論於黃子。〔三〕太史公仕於建元、元封之間，愍學者不達其意而師誖，〔四〕乃論六家之要指曰：","sentenceOrder":23},
  {"id":"s_work_han_thu_74_24","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　師古曰：「即律曆志所云方士唐都者。」","sentenceOrder":24},
  {"id":"s_work_han_thu_74_25","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　師古曰：「何字叔元，菑川人，見儒林傳。」","sentenceOrder":25},
  {"id":"s_work_han_thu_74_26","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　師古曰：「景帝時人也，儒林傳謂之黃生，與轅固爭論於上前，謂湯武非受命，乃殺也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_74_27","chapterId":"ch_work_han_thu_74","textTraditional":"〔四〕　師古曰：「誖，惑也。各習師法，惑於所見。誖音布內反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_74_28","chapterId":"ch_work_han_thu_74","textTraditional":"易大傳曰：「天下一致而百慮，同歸而殊塗。」〔一〕夫陰陽、儒、墨、名、法、道德，此務為治者也，直所從言之異路，有省不省耳。〔二〕嘗竊觀陰陽之術，大詳而眾忌諱，使人拘而多畏〔三〕，然其序四時之大順，不可失也。儒者博而寡要，勞而少功，是以其事難盡從，然其敘君臣父子之禮，列夫婦長幼之別，不可易也〔四〕。墨者儉而難遵，是以其事不可遍循，〔五〕然其彊本節用，不可廢也。法家嚴而少恩，然其正君臣上下之分，不可改也。名家使人儉而善失真，〔六〕然其正名實，不可不察也。道家使人精神專一，動合無形，澹足萬物，〔七〕其為術也，因陰陽之大順，采儒墨之善，撮名法之要，〔八〕與時遷徙，應物變化，立俗施事，無所不宜，指約而易操，事少而功多。〔九〕儒者則不然，以為人主天下之儀表也，君唱臣和，主先臣隨。如此，則主勞而臣佚。〔一０〕至於大道之要，去健羨，〔一一〕黜聰明，〔一二〕釋此而任術。夫神大用則竭，形大勞則敝；神形蚤衰，〔一三〕欲與天地長久，非所聞也。","sentenceOrder":28},
  {"id":"s_work_han_thu_74_29","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　張晏曰：「大傳謂易繫辭。」","sentenceOrder":29},
  {"id":"s_work_han_thu_74_30","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　師古曰：「言發跡雖殊，同歸於治，但學者不能省察，昧其端緒耳。直猶但也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_74_31","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　李奇曰：「陰陽之術，月令星官，是其枝葉也。」師古曰：「拘，曲礙也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_74_32","chapterId":"ch_work_han_thu_74","textTraditional":"〔四〕　師古曰：「易，變也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_74_33","chapterId":"ch_work_han_thu_74","textTraditional":"〔五〕　師古曰：「言難盡用。」","sentenceOrder":33},
  {"id":"s_work_han_thu_74_34","chapterId":"ch_work_han_thu_74","textTraditional":"〔六〕　師古曰：「劉向別錄云名家者流出於禮官。古者名位不同，禮亦異數。孔子曰『必也正名乎』。」","sentenceOrder":34},
  {"id":"s_work_han_thu_74_35","chapterId":"ch_work_han_thu_74","textTraditional":"〔七〕　師古曰：「澹，古贍字。」","sentenceOrder":35},
  {"id":"s_work_han_thu_74_36","chapterId":"ch_work_han_thu_74","textTraditional":"〔八〕　師古曰：「撮，總取也，音千活反。」","sentenceOrder":36},
  {"id":"s_work_han_thu_74_37","chapterId":"ch_work_han_thu_74","textTraditional":"〔九〕　師古曰：「操，執持也，音千高反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_74_38","chapterId":"ch_work_han_thu_74","textTraditional":"〔一０〕師古曰：「佚，樂也，字與逸同。」","sentenceOrder":38},
  {"id":"s_work_han_thu_74_39","chapterId":"ch_work_han_thu_74","textTraditional":"〔一一〕服虔曰：「門戶健壯也。」如淳曰：「知雄守雌，是去健也。不見可欲，使心不亂，是去羨也。」晉灼曰：「老子曰『善閉者無關楗』。嚴君平曰『拆關破楗，使姦者自止』。服說是也。」師古曰：「二義並通。楗，其偃反，然今書本字皆作健字也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_74_40","chapterId":"ch_work_han_thu_74","textTraditional":"〔一二〕如淳曰：「不尚賢，絕聖棄知也。」晉灼曰：「嚴君平曰『黜聰棄明，倚依太素，反本歸真，則理得而海內鈞也。』」師古曰：「黜，廢也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_74_41","chapterId":"ch_work_han_thu_74","textTraditional":"〔一三〕師古曰：「蚤，古早字。」","sentenceOrder":41},
  {"id":"s_work_han_thu_74_42","chapterId":"ch_work_han_thu_74","textTraditional":"夫陰陽，四時、八位、十二度、二十四節各有教令，〔一〕曰順之者昌，逆之者亡，未必然也，故曰「使人拘而多畏」。夫春生夏長，秋收冬臧，此天道之大經也，〔二〕弗順則無以為天下紀綱，故曰「四時之大順，不可失也」。","sentenceOrder":42},
  {"id":"s_work_han_thu_74_43","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　張晏曰：「八位，八卦位也。十二度，十二次也。二十四節，就中氣也。各有禁，謂月令也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_74_44","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　師古曰：「經，常法。」","sentenceOrder":44},
  {"id":"s_work_han_thu_74_45","chapterId":"ch_work_han_thu_74","textTraditional":"夫儒者，以六藝為法，六藝經傳以千萬數，累世不能通其學，當年不能究其禮，〔一〕故曰「博而寡要，勞而少功」。若夫列君臣父子之禮，序夫婦長幼之別，雖百家弗能易也。","sentenceOrder":45},
  {"id":"s_work_han_thu_74_46","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　師古曰：「究，盡也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_74_47","chapterId":"ch_work_han_thu_74","textTraditional":"墨者亦上堯舜，言其德行曰：「堂高三尺，土階三等，茅茨不翦，棌椽不斲；〔一〕飯土簋，歠土刑，〔二〕糲粱之食，〔三〕藜藿之羹；〔四〕夏日葛衣，冬日鹿裘。」其送死，桐棺三寸，舉音不盡其哀。教喪禮，必以此為萬民率。故天下共若此，則尊卑無別也。夫世異時移，事業不必同，故曰「儉而難遵」也。要曰彊本節用，則人給家足之道也。〔五〕此墨子之所長，雖百家不能廢也。","sentenceOrder":47},
  {"id":"s_work_han_thu_74_48","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　師古曰：「屋蓋曰茨。茅茨，以茅覆屋也。棌，柞木也。茨音疾茲反。棌音采，又音菜。」","sentenceOrder":48},
  {"id":"s_work_han_thu_74_49","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　師古曰：「簋所以盛飯也，刑以盛羹也。土謂燒土為之，即瓦器也。飯，扶晚反。簋音軌。歠，尺悅反。」","sentenceOrder":49},
  {"id":"s_work_han_thu_74_50","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　服虔曰：「糲，粗米也。」張晏曰：「一斛粟七斗米為糲，音賴。」師古曰：「食，飯也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_74_51","chapterId":"ch_work_han_thu_74","textTraditional":"〔四〕　師古曰：「藜，草似蓬也。藿，豆葉也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_74_52","chapterId":"ch_work_han_thu_74","textTraditional":"〔五〕　師古曰：「給亦足也。人人家家皆得足也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_74_53","chapterId":"ch_work_han_thu_74","textTraditional":"法家不別親疏，不殊貴賤，壹斷於法，則親親尊尊之恩絕矣，可以行一時之計，而不可長用也，故曰「嚴而少恩」。若尊主卑臣，明分職不得相踰越，雖百家不能改也。〔一〕","sentenceOrder":53},
  {"id":"s_work_han_thu_74_54","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　師古曰：「分，扶問反。」","sentenceOrder":54},
  {"id":"s_work_han_thu_74_55","chapterId":"ch_work_han_thu_74","textTraditional":"名家苛察繳繞，〔一〕使人不得反其意，剸決於名，時失人情，〔二〕故曰「使人儉而善失真」。若夫控名責實，參伍不失〔三〕，此不可不察也。","sentenceOrder":55},
  {"id":"s_work_han_thu_74_56","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　如淳曰：「繳繞猶纏繞也。」師古曰：「繳，公鳥反。」","sentenceOrder":56},
  {"id":"s_work_han_thu_74_57","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　師古曰：「剸讀與專同，又音章免反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_74_58","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　晉灼曰：「引名責實，參錯交互，明知事情也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_74_59","chapterId":"ch_work_han_thu_74","textTraditional":"道家無為，又曰無不為，〔一〕其實易行，其辭難知。〔二〕其術以虛無為本，以因循為用。〔三〕無成勢，無常形，故能究萬物之情。不為物先後，故能為萬物主。有法無法，因時為業；有度無度，因物興舍。〔四〕故曰「聖人不巧，時變是守」。〔五〕虛者道之常也，因者君之綱也。〔六〕群臣並至，使各自明也。其實中其聲者謂之端，實不中其聲者謂之款。〔七〕款言不聽，姦乃不生，賢不肖自分，白黑乃形。〔八〕在所欲用耳，何事不成！乃合大道，混混冥冥。〔九〕光燿天下，復反無名。〔一０〕凡人所生者神也，所託者形也。神大用則竭，形大勞則敝，形神離則死。死者不可復生，離者不可復合，故聖人重之。由此觀之，神者生之本，形者生之具。不先定其神形，而曰「我有以治天下」，何由哉？〔一一〕","sentenceOrder":59},
  {"id":"s_work_han_thu_74_60","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　師古曰：「無為者，守靜一也。無不為者，功利大也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_74_61","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　師古曰：「言指趣幽遠。」","sentenceOrder":61},
  {"id":"s_work_han_thu_74_62","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　師古曰：「任自然也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_74_63","chapterId":"ch_work_han_thu_74","textTraditional":"〔四〕　師古曰：「興，起也。舍，廢也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_74_64","chapterId":"ch_work_han_thu_74","textTraditional":"〔五〕　師古曰：「無機巧之心，但順時也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_74_65","chapterId":"ch_work_han_thu_74","textTraditional":"〔六〕　師古曰：「言因百姓之心以為教，但執其綱而已。」","sentenceOrder":65},
  {"id":"s_work_han_thu_74_66","chapterId":"ch_work_han_thu_74","textTraditional":"〔七〕　服虔曰：「款，空也。」李奇曰：「聲則名也。」師古曰：「中，當也，充也，音竹仲反。」","sentenceOrder":66},
  {"id":"s_work_han_thu_74_67","chapterId":"ch_work_han_thu_74","textTraditional":"〔八〕　師古曰：「形，見也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_74_68","chapterId":"ch_work_han_thu_74","textTraditional":"〔九〕　師古曰：「元氣之貌也。混音胡本反。」","sentenceOrder":68},
  {"id":"s_work_han_thu_74_69","chapterId":"ch_work_han_thu_74","textTraditional":"〔一０〕師古曰：「反，還也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_74_70","chapterId":"ch_work_han_thu_74","textTraditional":"〔一一〕師古曰：「凡此皆言道家之教為長也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_74_71","chapterId":"ch_work_han_thu_74","textTraditional":"太史公既掌天官，不治民。有子曰遷。","sentenceOrder":71},
  {"id":"s_work_han_thu_74_72","chapterId":"ch_work_han_thu_74","textTraditional":"遷生龍門，〔一〕耕牧河山之陽。〔二〕年十歲則誦古文。二十而南游江淮，上會稽，探禹穴，窺九疑，〔三〕浮沅湘。〔四〕北涉汶泗，〔五〕講業齊魯之都，觀夫子遺風，鄉射鄒嶧；〔六〕阨困蕃、薛、彭城，〔七〕過梁楚以歸。於是遷仕為郎中，奉使西征巴蜀以南，略邛、筰、昆明，〔八〕還報命。","sentenceOrder":72},
  {"id":"s_work_han_thu_74_73","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　蘇林曰：「禹所鑿龍門也。」師古曰：「龍門山，其東則在今秦州龍門縣北，其西則在今同州韓城縣北，而河從其中下流。」","sentenceOrder":73},
  {"id":"s_work_han_thu_74_74","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　師古曰：「河之北，山之南也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_74_75","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　張晏曰：「禹巡狩至會稽而崩，因葬焉。上有孔穴，民間云禹入此穴。九疑，舜墓在焉。」師古曰：「會稽，山名，本茅山也，禹於此會諸侯之計，因名曰會稽。九疑山有九峰，解在司馬相如傳。」","sentenceOrder":75},
  {"id":"s_work_han_thu_74_76","chapterId":"ch_work_han_thu_74","textTraditional":"〔四〕　師古曰：「沅水出牂柯，湘水出零陵，二水皆入江。」","sentenceOrder":76},
  {"id":"s_work_han_thu_74_77","chapterId":"ch_work_han_thu_74","textTraditional":"〔五〕　師古曰：「汶、泗兩水名在地理志。汶音問。」","sentenceOrder":77},
  {"id":"s_work_han_thu_74_78","chapterId":"ch_work_han_thu_74","textTraditional":"〔六〕　師古曰：「鄒，縣名也。嶧，山名也，近曲阜地也。於此行鄉射之禮，嶧音懌。」","sentenceOrder":78},
  {"id":"s_work_han_thu_74_79","chapterId":"ch_work_han_thu_74","textTraditional":"〔七〕　師古曰：「蕃，縣名也，音皮。」","sentenceOrder":79},
  {"id":"s_work_han_thu_74_80","chapterId":"ch_work_han_thu_74","textTraditional":"〔八〕　師古曰：「筰，才各反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_74_81","chapterId":"ch_work_han_thu_74","textTraditional":"是歲，天子始建漢家之封，而太史公留滯周南，〔一〕不得與從事，〔二〕發憤且卒。而子遷適反，見父於河雒之間。太史公執遷手而泣曰：「予先，周室之太史也。自上世嘗顯功名虞夏，典天官事。後世中衰，絕於予乎？汝復為太史，則續吾祖矣。今天子接千歲之統，封泰山，而予不得從行，是命也夫！命也夫！予死，爾必為太史；為太史，毋忘吾所欲論著矣。且夫孝，始於事親，中於事君，終於立身；揚名於後世，以顯父母，此孝之大也。〔三〕夫天下稱周公，言其能論歌文武之德，宣周召之風，〔四〕達大王王季思慮，爰及公劉，以尊后稷也。〔五〕幽厲之後，王道缺，禮樂衰，孔子脩舊起廢，論詩書，作春秋，則學者至今則之。自獲麟以來四百有餘歲，而諸侯相兼，史記放絕。今漢興，海內壹統，明主賢君，忠臣義士，予為太史而不論載，廢天下之文，予甚懼焉，爾其念哉！」遷俯首流涕曰：「小子不敏，請悉論先人所次舊聞，不敢闕。」卒三歲，而遷為太史令，紬史記石室金鐀之書。〔六〕五年而當太初元年，〔七〕十一月甲子朔旦冬至，天曆始改，建於明堂，諸神受記。〔八〕","sentenceOrder":81},
  {"id":"s_work_han_thu_74_82","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　如淳曰：「周南，洛陽也。」張晏曰：「洛陽而謂周南者，自陝以東皆周南之地也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_74_83","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　師古曰：「與讀曰豫。」","sentenceOrder":83},
  {"id":"s_work_han_thu_74_84","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　師古曰：「此孔子說孝經之辭也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_74_85","chapterId":"ch_work_han_thu_74","textTraditional":"〔四〕　師古曰：「召讀曰邵。」","sentenceOrder":85},
  {"id":"s_work_han_thu_74_86","chapterId":"ch_work_han_thu_74","textTraditional":"〔五〕　師古曰：「爰，曰也，發語辭也。一曰，爰，於也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_74_87","chapterId":"ch_work_han_thu_74","textTraditional":"〔六〕　如淳曰：「紬徹舊書故事而次述之。」師古曰：「此說非也。紬謂綴集之，音冑。鐀與匱同。」","sentenceOrder":87},
  {"id":"s_work_han_thu_74_88","chapterId":"ch_work_han_thu_74","textTraditional":"〔七〕　李奇曰：「遷為太史後五年適當武帝太初元年，時述史記也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_74_89","chapterId":"ch_work_han_thu_74","textTraditional":"〔八〕　張晏曰：「以元新改，立明堂，朝諸侯及郡守受正朔，各有山川之祀，故曰諸神受記。」孟康曰：「明堂班十二月之政，曆紀四時，故改建於明堂。諸神受記，若勾芒祝融之屬皆受瑞記。遷因此而作。」師古曰：「張說是矣。」","sentenceOrder":89},
  {"id":"s_work_han_thu_74_90","chapterId":"ch_work_han_thu_74","textTraditional":"太史公曰：「先人有言：『自周公卒五百歲而有孔子，孔子至於今五百歲，有能紹而明之，正易傳，繼春秋，本詩書禮樂之際。』意在斯乎！意在斯乎！小子何敢攘焉！」〔一〕","sentenceOrder":90},
  {"id":"s_work_han_thu_74_91","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　師古曰：「攘，古讓字。言當述成先人之業，何敢自謙，當五百歲而讓之也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_74_92","chapterId":"ch_work_han_thu_74","textTraditional":"上大夫壺遂曰：「昔孔子為何作春秋哉？」太史公曰：「余聞之董生：〔一〕『周道廢，孔子為魯司寇，諸侯害之，大夫壅之。孔子知時之不用，道之不行也，是非二百四十二年之中，〔二〕以為天下儀表，貶諸侯，討大夫，以達王事而已矣。』〔三〕子曰：『我欲載之空言，不如見之於行事之深切著明也。』春秋上明三王之道，下辨人事之經紀，別嫌疑，明是非，定猶與，〔四〕善善惡惡，賢賢賤不肖，存亡國，繼絕世，補弊起廢，王道之大者也。易著天地陰陽四時五行，故長於變；〔五〕禮綱紀人倫，故長於行；書記先王之事，故長於政；詩記山川谿谷禽獸草木牝牡雌雄，故長於風；樂樂所以立，故長於和；春秋辯是非，故長於治人。是故禮以節人，樂以發和，書以道事，詩以達意，易以道化，春秋以道義。〔六〕撥亂世反之正，莫近於春秋。春秋文成數萬，其指數千。〔七〕萬物之散聚皆在春秋。春秋之中，弒君三十六，亡國五十二，諸侯奔走不得保社稷者不可勝數。〔八〕察其所以，皆失其本已。〔九〕故易曰『差以豪氂，謬以千里』。〔一０〕故『臣弒君，子弒父，非一朝一夕之故，其漸久矣』。〔一一〕有國者不可以不知春秋，前有讒而不見，後有賊而不知。為人臣者不可以不知春秋，守經事而不知其宜，遭變事而不知其權。〔一二〕為人君父者而不通於春秋之義者，必蒙首惡之名。〔一三〕為人臣子不通於春秋之義者，必陷篡弒誅死之罪。其實皆以善為之，而不知其義，〔一四〕被之空言不敢辭。〔一五〕夫不通禮義之指，至於君不君，臣不臣，父不父，子不子。夫君不君則犯，〔一六〕臣不臣則誅，父不父則無道，子不子則不孝。此四行者，天下之大過也。以天下大過予之，受而不敢辭。故春秋者，禮義之大宗也。夫禮禁未然之前，法施已然之後；法之所為用者易見，而禮之所為禁者難知。」","sentenceOrder":92},
  {"id":"s_work_han_thu_74_93","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　服虔曰：「仲舒也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_74_94","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　師古曰：「是非謂本其得失。」","sentenceOrder":94},
  {"id":"s_work_han_thu_74_95","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　師古曰：「時諸侯僭侈，大夫擅權，故貶討之也。貶，退也。討，治也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_74_96","chapterId":"ch_work_han_thu_74","textTraditional":"〔四〕　師古曰：「與讀曰豫。」","sentenceOrder":96},
  {"id":"s_work_han_thu_74_97","chapterId":"ch_work_han_thu_74","textTraditional":"〔五〕　師古曰：「以變化之道為長也。長讀如本字。一曰長謂崇長之也，音竹兩反。下皆類此。」","sentenceOrder":97},
  {"id":"s_work_han_thu_74_98","chapterId":"ch_work_han_thu_74","textTraditional":"〔六〕　師古曰：「道，言也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_74_99","chapterId":"ch_work_han_thu_74","textTraditional":"〔七〕　張晏曰：「春秋萬八千字，當言減，而云成，字誤也。」師古曰：「張說非也。一萬之外即以萬言之，故云數萬，何乃忽言減乎？學者又為曲解，云公羊經傳凡四萬四千餘字，尤疏謬矣。史遷豈謂公羊之傳為春秋乎？」","sentenceOrder":99},
  {"id":"s_work_han_thu_74_100","chapterId":"ch_work_han_thu_74","textTraditional":"〔八〕　師古曰：「解並在劉向傳。」","sentenceOrder":100},
  {"id":"s_work_han_thu_74_101","chapterId":"ch_work_han_thu_74","textTraditional":"〔九〕　師古曰：「已，語終之辭。」","sentenceOrder":101},
  {"id":"s_work_han_thu_74_102","chapterId":"ch_work_han_thu_74","textTraditional":"〔一０〕師古曰：「今之易經及彖象繫辭，並無此語。所稱易緯者，則有之焉。斯蓋易家之別說者也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_74_103","chapterId":"ch_work_han_thu_74","textTraditional":"〔一一〕師古曰：「易坤卦文言之辭。」","sentenceOrder":103},
  {"id":"s_work_han_thu_74_104","chapterId":"ch_work_han_thu_74","textTraditional":"〔一二〕師古曰：「經，常也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_74_105","chapterId":"ch_work_han_thu_74","textTraditional":"〔一三〕師古曰：「蒙猶被也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_74_106","chapterId":"ch_work_han_thu_74","textTraditional":"〔一四〕師古曰：「其心雖善，以不知義理之故，則陷於惡也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_74_107","chapterId":"ch_work_han_thu_74","textTraditional":"〔一五〕蘇林曰：「趙盾不知討賊，而不敢辭弒君之罪。」","sentenceOrder":107},
  {"id":"s_work_han_thu_74_108","chapterId":"ch_work_han_thu_74","textTraditional":"〔一六〕師古曰：「為臣下所干犯也。〔一〕曰違犯禮義也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_74_109","chapterId":"ch_work_han_thu_74","textTraditional":"壺遂曰：「孔子之時，上無明君，下不得任用，故作春秋，垂空文以斷禮義，〔一〕當一王之法。今夫子上遇明天子，下得守職，萬事既具，咸各序其宜，夫子所論，欲以何明？」太史公曰：「唯唯，否否，〔二〕不然。余聞之先人曰：『虙戲至純厚，作易八卦。〔三〕堯舜之盛，尚書載之，禮樂作焉。湯武之隆，詩人歌之。春秋采善貶惡，推三代之德，褒周室，非獨刺譏而已也。』漢興已來，至明天子，獲符瑞，封禪，改正朔，易服色，受命於穆清，〔四〕澤流罔極，〔五〕海外殊俗重譯款塞，〔六〕請來獻見者，不可勝道。〔七〕臣下百官力誦聖德，猶不能宣盡其意。〔八〕且士賢能矣，而不用，有國者恥也；主上明聖，德不布聞，有司之過也。且余掌其官，廢明聖盛德不載，滅功臣賢大夫之業不述，墮先人所言，〔九〕罪莫大焉。余所謂述故事，整齊其世傳，非所謂作也，而君比之春秋，謬矣。」","sentenceOrder":109},
  {"id":"s_work_han_thu_74_110","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　師古曰：「斷，決也，決之於禮義也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_74_111","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　晉灼曰：「唯唯，謙應也。否否，不通也。」師古曰：「唯，弋癸反。」","sentenceOrder":111},
  {"id":"s_work_han_thu_74_112","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　師古曰：「虙讀與伏同。」","sentenceOrder":112},
  {"id":"s_work_han_thu_74_113","chapterId":"ch_work_han_thu_74","textTraditional":"〔四〕　師古曰：「於，歎辭也。穆，美也。言天子有美德而政化清也。於讀曰烏。」","sentenceOrder":113},
  {"id":"s_work_han_thu_74_114","chapterId":"ch_work_han_thu_74","textTraditional":"〔五〕　師古曰：「罔，無也。極，止也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_74_115","chapterId":"ch_work_han_thu_74","textTraditional":"〔六〕　師古曰：「款，叩也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_74_116","chapterId":"ch_work_han_thu_74","textTraditional":"〔七〕　師古曰：「道，言也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_74_117","chapterId":"ch_work_han_thu_74","textTraditional":"〔八〕　師古曰：「力，勤也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_74_118","chapterId":"ch_work_han_thu_74","textTraditional":"〔九〕　師古曰：「墮，毀也，謂不修之也。音火規反。」","sentenceOrder":118},
  {"id":"s_work_han_thu_74_119","chapterId":"ch_work_han_thu_74","textTraditional":"於是論次其文。十年而遭李陵之禍，幽於纍紲。〔一〕乃喟然而歎曰：「是余之罪夫！〔二〕身虧不用矣。」退而深惟曰〔三〕：「夫詩書隱約者，欲遂其志之思也。」〔四〕卒述陶唐以來，至於麟止，〔五〕自黃帝始。〔六〕五帝本紀第一，夏本紀第二，殷本紀第三，周本紀第四，秦本紀第五，始皇本紀第六，項羽本紀第七，高祖本紀第八，呂后本紀第九，孝文本紀第十，孝景本紀第十一，今上本紀第十二。三代世表第一，十二諸侯年表第二，六國年表第三，秦楚之際月表第四，漢諸侯年表第五，高祖功臣年表第六，惠景間功臣年表第七，建元以來侯者年表第八，王子侯者年表第九，漢興以來將相名臣年表第十。禮書第一，樂書第二，律書第三，曆書第四，天官書第五，封禪書第六，河渠書第七，平準書第八。吳太伯世家第一，齊太公世家第二，魯周公世家第三，燕召公世家第四，〔七〕管蔡世家第五，陳杞世家第六，衛康叔世家第七，宋微子世家第八，晉世家第九，楚世家第十，越世家第十一，鄭世家第十二，趙世家第十三，魏世家第十四，韓世家第十五，田完世家第十六，孔子世家第十七，陳涉世家第十八，外戚世家第十九，楚元王世家第二十，荊燕王世家第二十一，齊悼惠王世家第二十二，蕭相國世家第二十三，曹相國世家第二十四，留侯世家第二十五，陳丞相世家第二十六，絳侯世家第二十七，梁孝王世家第二十八，五宗世家第二十九，〔八〕三王世家第三十。伯夷列傳第一，管晏列傳第二，老子韓非列傳第三，司馬穰苴列傳第四，〔九〕孫子吳起列傳第五，伍子胥列傳第六，仲尼弟子列傳第七，商君列傳第八，蘇秦列傳第九，張儀列傳第十，樗里甘茂列傳第十一，穰侯列傳第十二，白起王翦列傳第十三，孟子荀卿列傳第十四，平原虞卿列傳第十五，孟嘗君列傳第十六，魏公子列傳第十七，春申君列傳第十八，范睢蔡澤列傳第十九，樂毅列傳第二十，廉頗藺相如列傳第二十一，田單列傳第二十二，魯仲連列傳第二十三，屈原賈生列傳第二十四，呂不韋列傳第二十五，刺客列傳第二十六，李斯列傳第二十七，蒙恬列傳第二十八，張耳陳餘列傳第二十九，魏豹彭越列傳第三十，黥布列傳第三十一，淮陰侯韓信列傳第三十二，韓王信盧綰列傳第三十三，田儋列傳第三十四，樊酈滕灌列傳第三十五，張丞相倉列傳第三十六，酈生陸賈列傳第三十七，傅靳〈崩阝〉成侯列傳第三十八，〔一０〕劉敬叔孫通列傳第三十九，季布欒布列傳第四十，爰盎朝錯列傳第四十一，張釋之馮唐列傳第四十二，萬石張叔列傳第四十三，田叔列傳第四十四，扁鵲倉公列傳第四十五，吳王濞列傳第四十六，魏其武安列傳第四十七，韓長孺列傳第四十八，李將軍列傳第四十九，衛將軍驃騎列傳第五十，平津主父列傳第五十一，匈奴列傳第五十二，南越列傳第五十三，閩越列傳第五十四，朝鮮列傳第五十五，西南夷列傳第五十六，司馬相如列傳第五十七，淮南衡山列傳第五十八，循吏列傳第五十九，汲鄭列傳第六十，儒林列傳第六十一，酷吏列傳第六十二，大宛列傳第六十三，游俠列傳第六十四，佞幸列傳第六十五，滑稽列傳第六十六，日者列傳第六十七，龜策列傳第六十八，貨殖列傳第六十九。","sentenceOrder":119},
  {"id":"s_work_han_thu_74_120","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　師古曰：「纍，係也。紲，長繩也。纍音力追反。紲音先列反。」","sentenceOrder":120},
  {"id":"s_work_han_thu_74_121","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　師古曰：「喟然，歎息貌也。音邱位反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_74_122","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　師古曰：「惟，思也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_74_123","chapterId":"ch_work_han_thu_74","textTraditional":"〔四〕　師古曰：「隱，憂也。約，屈也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_74_124","chapterId":"ch_work_han_thu_74","textTraditional":"〔五〕　服虔曰：「武帝得白麟，而鑄金作麟足形。作史記止於此也。」張晏曰：「武帝獲麟，遷以為述事之端，上記黃帝，下至麟止，猶春秋止於獲麟也。」師古曰：「遷序事盡太初，故言至麟而止。張說是也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_74_125","chapterId":"ch_work_han_thu_74","textTraditional":"〔六〕　師古曰：「遷之書序眾篇各別有辭，班氏以其文多，故略而不載，但取最後一首，故此單目盡於六十九。至『惟漢繼五帝末流』之後，乃言第七十。讀者不詳其意，或於目中加云『敘傳第七十』，此大妄矣。」","sentenceOrder":125},
  {"id":"s_work_han_thu_74_126","chapterId":"ch_work_han_thu_74","textTraditional":"〔七〕　師古曰：「召讀曰邵。」","sentenceOrder":126},
  {"id":"s_work_han_thu_74_127","chapterId":"ch_work_han_thu_74","textTraditional":"〔八〕　師古曰：「景帝子凡十三人為王，而母五人所生，遷謂同母者為一宗，故云五宗也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_74_128","chapterId":"ch_work_han_thu_74","textTraditional":"〔九〕　師古曰：「苴音子閭反。」","sentenceOrder":128},
  {"id":"s_work_han_thu_74_129","chapterId":"ch_work_han_thu_74","textTraditional":"〔一０〕師古曰：「〈崩阝〉成侯，周緤也。〈崩阝〉音普肯反，又音陪。」","sentenceOrder":129},
  {"id":"s_work_han_thu_74_130","chapterId":"ch_work_han_thu_74","textTraditional":"惟漢繼五帝末流，接三代絕業。周道既廢，秦撥去古文，焚滅詩書，故明堂石室金鐀玉版圖籍散亂。〔一〕漢興，蕭何次律令，韓信申軍法，張蒼為章程，叔孫通定禮儀，則文學彬彬稍進，詩書往往間出。〔二〕自曹參薦蓋公言黃老，而賈誼、朝錯明申韓，公孫弘以儒顯，百年之間，天下遺文古事靡不畢集。太史公仍父子相繼篹其職，〔三〕曰：「於戲！〔四〕余維先人嘗掌斯事，顯於唐虞。至於周，復典之。故司馬氏世主天官，至於余乎，欽念哉！」〔五〕罔羅天下放失舊聞，王跡所興，原始察終，見盛觀衰，論考之行事，略三代，錄秦漢，上記軒轅，下至於茲，著十二本紀，既科條之矣。並時異世，年差不明，作十表。〔六〕禮樂損益，律曆改易，兵權山川鬼神，天人之際，承敝通變，作八書。二十八宿環北辰，三十輻共一轂，運行無窮，〔七〕輔弼股肱之臣配焉，忠信行道以奉主上，作三十世家。扶義俶儻，不令己失時，〔八〕立功名於天下，作七十列傳。凡百三十篇，五十二萬六千五百字，為太史公書。序略，以拾遺補蓺，成一家言，〔九〕協六經異傳，齊百家雜語，臧之名山，副在京師〔一０〕，以俟後聖君子。第七十，〔一一〕遷之自敘云爾。〔一二〕而十篇缺，有錄無書。〔一三〕","sentenceOrder":130},
  {"id":"s_work_han_thu_74_131","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　如淳曰：「玉版，刻玉版畫為文字也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_74_132","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　師古曰：「彬彬，文章貌。彬音邠。間音居莧反。」","sentenceOrder":132},
  {"id":"s_work_han_thu_74_133","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　師古曰：「篹讀與撰同。」","sentenceOrder":133},
  {"id":"s_work_han_thu_74_134","chapterId":"ch_work_han_thu_74","textTraditional":"〔四〕　師古曰：「於戲，歎聲也。於讀曰烏，戲讀曰呼。古字或作烏虖，今字或作烏呼，音義皆同耳。而俗之讀者，隨字而別，又曲為解釋云有吉凶美惡之殊，是不通其大指也。義例具在詩及尚書，不可一二遍舉之。」","sentenceOrder":134},
  {"id":"s_work_han_thu_74_135","chapterId":"ch_work_han_thu_74","textTraditional":"〔五〕　師古曰：「欽，敬也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_74_136","chapterId":"ch_work_han_thu_74","textTraditional":"〔六〕　師古曰：「並時則年曆差殊，異代則難以明辨，故作表也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_74_137","chapterId":"ch_work_han_thu_74","textTraditional":"〔七〕　孟康曰：「象黃帝以下三十家也。老子言車三十輻運行無窮，以象王者如此也。」師古曰：「此說非也。言眾星共繞北辰，諸輻咸歸車轂，若文武之臣尊輔天子也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_74_138","chapterId":"ch_work_han_thu_74","textTraditional":"〔八〕　師古曰：「俶儻，大節也。俶，吐歷反。」","sentenceOrder":138},
  {"id":"s_work_han_thu_74_139","chapterId":"ch_work_han_thu_74","textTraditional":"〔九〕　孟康曰：「蓺音褋。謂裳下壞褋。」李奇曰：「蓺，六蓺也。」師古曰：「李說是也。蓺，古藝字。」","sentenceOrder":139},
  {"id":"s_work_han_thu_74_140","chapterId":"ch_work_han_thu_74","textTraditional":"〔一０〕師古曰：「臧於山者。備亡失也。其副貳本乃留京師也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_74_141","chapterId":"ch_work_han_thu_74","textTraditional":"〔一一〕師古曰：「俟，古俟字。」","sentenceOrder":141},
  {"id":"s_work_han_thu_74_142","chapterId":"ch_work_han_thu_74","textTraditional":"〔一二〕師古曰：「自此以前，皆其自敘之辭也。自此以後，乃班氏作傳語耳。」","sentenceOrder":142},
  {"id":"s_work_han_thu_74_143","chapterId":"ch_work_han_thu_74","textTraditional":"〔一三〕張晏曰：「遷沒之後，亡景紀、武紀、禮書、樂書、兵書、漢興以來將相年表、日者列傳、三王世家、龜策列傳、傅靳列傳。元成之間褚先生補缺，作武帝紀，三王世家，龜策、日者傳，言辭鄙陋，非遷本意也。」師古曰：「序目本無兵書，張云亡失，此說非也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_74_144","chapterId":"ch_work_han_thu_74","textTraditional":"遷既被刑之後，為中書令，尊寵任職。故人益州刺史任安〔一〕予遷書，責以古賢臣之義。遷報之曰：","sentenceOrder":144},
  {"id":"s_work_han_thu_74_145","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　師古曰：「故人者，言其舊交也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_74_146","chapterId":"ch_work_han_thu_74","textTraditional":"少卿足下：〔一〕曩者辱賜書，教以慎於接物，推賢進士為務，意氣勤勤懇懇，〔二〕若望僕不相師用，〔三〕而流俗人之言。〔四〕僕非敢如是也。雖罷駑，亦嘗側聞長者遺風矣。〔五〕顧自以為身殘處穢，動而見尤，〔六〕欲益反損，是以抑鬱而無誰語。〔七〕諺曰：「誰為為之？孰令聽之？」〔八〕蓋鍾子期死，伯牙終身不復鼓琴。〔九〕何則？士為知己用，女為說己容。〔一０〕若僕大質已虧缺，雖材懷隨和，行若由夷，〔一一〕終不可以為榮，適足以發笑而自點耳。〔一二〕","sentenceOrder":146},
  {"id":"s_work_han_thu_74_147","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　如淳曰：「少卿，任安字。」","sentenceOrder":147},
  {"id":"s_work_han_thu_74_148","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　師古曰：「懇懇，至誠也。音墾。」","sentenceOrder":148},
  {"id":"s_work_han_thu_74_149","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　師古曰：「望，怨也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_74_150","chapterId":"ch_work_han_thu_74","textTraditional":"〔四〕　師古曰：「謂隨俗人之言，而流移其志。」","sentenceOrder":150},
  {"id":"s_work_han_thu_74_151","chapterId":"ch_work_han_thu_74","textTraditional":"〔五〕　師古曰：「罷讀曰疲。」","sentenceOrder":151},
  {"id":"s_work_han_thu_74_152","chapterId":"ch_work_han_thu_74","textTraditional":"〔六〕　師古曰：「顧，思念也。尤，過也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_74_153","chapterId":"ch_work_han_thu_74","textTraditional":"〔七〕　師古曰：「無誰語者，言無相知心之人，誰可告語？」","sentenceOrder":153},
  {"id":"s_work_han_thu_74_154","chapterId":"ch_work_han_thu_74","textTraditional":"〔八〕　師古曰：「言無知己者，設欲修名節，立言行，誰可為作之，又令誰聽之？上為音于偽反。」","sentenceOrder":154},
  {"id":"s_work_han_thu_74_155","chapterId":"ch_work_han_thu_74","textTraditional":"〔九〕　師古曰：「伯牙、鍾子期皆楚人也。伯牙鼓琴，子期聽之。方鼓琴而志在泰山，子期曰：『巍巍乎若泰山。』既而志在流水，子期又曰：『湯湯乎若流水。』及子期死，伯牙破琴絕弦，終身不復鼓琴，以時人無足復為鼓琴耳。」","sentenceOrder":155},
  {"id":"s_work_han_thu_74_156","chapterId":"ch_work_han_thu_74","textTraditional":"〔一０〕師古曰：「說讀曰悅。」","sentenceOrder":156},
  {"id":"s_work_han_thu_74_157","chapterId":"ch_work_han_thu_74","textTraditional":"〔一一〕應劭曰：「由、夷，許由、伯夷也。」師古曰：「隨，隨侯珠也。和，和氏璧。」","sentenceOrder":157},
  {"id":"s_work_han_thu_74_158","chapterId":"ch_work_han_thu_74","textTraditional":"〔一二〕師古曰：「點，汙也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_74_159","chapterId":"ch_work_han_thu_74","textTraditional":"書辭宜答，〔一〕會東從上來，〔二〕又迫賤事，〔三〕相見日淺，卒卒無須臾之間得竭指意。〔四〕今少卿抱不測之罪，〔五〕涉旬月，迫季冬，僕又薄從上上雍，〔六〕恐卒然不可諱。〔七〕是僕終已不得舒憤懣以曉左右，〔八〕則長逝者魂魄私恨無窮。〔九〕請略陳固陋。闕然不報，幸勿過。〔一０〕","sentenceOrder":159},
  {"id":"s_work_han_thu_74_160","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　師古曰：「宜早答。」","sentenceOrder":160},
  {"id":"s_work_han_thu_74_161","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　服虔曰：「從武帝還也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_74_162","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　孟康曰：「卑賤之事，苦煩務也。」晉灼曰：「賤事，家之私事賤小者也。」師古曰：「謂所供職事也。孟說是也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_74_163","chapterId":"ch_work_han_thu_74","textTraditional":"〔四〕　文穎曰：「卒言倉卒。」師古曰：「卒卒，促遽之意也。間，隙也。卒音千忽反。」","sentenceOrder":163},
  {"id":"s_work_han_thu_74_164","chapterId":"ch_work_han_thu_74","textTraditional":"〔五〕　如淳曰：「平居時，遷不肯報其書。今有罪在獄，故報往日書，欲使其恕以度己也。」師古曰：「不測謂深也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_74_165","chapterId":"ch_work_han_thu_74","textTraditional":"〔六〕　李奇曰：「薄，迫也。迫當從行也。」如淳曰：「遷時從上在鹵簿中也。」師古曰：「李說是也。」","sentenceOrder":165},
  {"id":"s_work_han_thu_74_166","chapterId":"ch_work_han_thu_74","textTraditional":"〔七〕　師古曰：「卒讀曰猝。不可諱謂安死也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_74_167","chapterId":"ch_work_han_thu_74","textTraditional":"〔八〕　師古曰：「懣，煩悶也。曉，告喻也。懣音滿。」","sentenceOrder":167},
  {"id":"s_work_han_thu_74_168","chapterId":"ch_work_han_thu_74","textTraditional":"〔九〕　師古曰：「謂任安恨不見報。」","sentenceOrder":168},
  {"id":"s_work_han_thu_74_169","chapterId":"ch_work_han_thu_74","textTraditional":"〔一０〕師古曰：「謂中間久不報也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_74_170","chapterId":"ch_work_han_thu_74","textTraditional":"僕聞之，修身者智之府也，〔一〕愛施者仁之端也，取予者義之符也，〔二〕恥辱者勇之決也，立名者行之極也。士有此五者，然後可以託於世，列於君子之林矣。故禍莫憯於欲利，〔三〕悲莫痛於傷心，行莫醜於辱先，而詬莫大於宮刑。〔四〕刑餘之人，無所比數，非一世也，所從來遠矣。昔衛靈公與雍渠載，孔子適陳；〔五〕商鞅因景監見，趙良寒心；〔六〕同子參乘，爰絲變色：〔七〕自古而恥之。夫中材之人，事關於宦豎，莫不傷氣。況忼慨之士乎！〔八〕如今朝雖乏人，柰何令刀鋸之餘薦天下豪雋哉！僕賴先人緒業，得待罪輦轂下，二十餘年矣。〔九〕所以自惟：〔一０〕上之，不能納忠效信，〔一一〕有奇策材力之譽，自結明主；次之，又不能拾遺補闕，招賢進能，顯巖穴之士；外之，不能備行伍，攻城（戰野）〔野戰〕，有斬將搴旗之功；〔一二〕下之，不能累日積勞，取尊官厚祿，以為宗族交遊光寵。四者無一遂，苟合取容，無所短長之效，可見於此矣。鄉者，僕亦嘗廁下大夫之列，〔一三〕陪外廷末議。不以此時引維綱，盡思慮，今已虧形為埽除之隸，在闒茸之中，〔一四〕乃欲卬首信眉，論列是非，〔一五〕不亦輕朝廷，羞當世之士邪！〔一六〕嗟乎！嗟乎！如僕，尚何言哉！尚何言哉！","sentenceOrder":170},
  {"id":"s_work_han_thu_74_171","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　師古曰：「府者，所聚之處也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_74_172","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　師古曰：「符，信也。」","sentenceOrder":172},
  {"id":"s_work_han_thu_74_173","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　師古曰：「憯亦痛也。音千敢反。」","sentenceOrder":173},
  {"id":"s_work_han_thu_74_174","chapterId":"ch_work_han_thu_74","textTraditional":"〔四〕　師古曰：「詬，恥也，音垢。」","sentenceOrder":174},
  {"id":"s_work_han_thu_74_175","chapterId":"ch_work_han_thu_74","textTraditional":"〔五〕　應劭曰：「雍渠，奄人也，靈公近之。」","sentenceOrder":175},
  {"id":"s_work_han_thu_74_176","chapterId":"ch_work_han_thu_74","textTraditional":"〔六〕　應劭曰：「景監，秦嬖人也。」服虔曰：「趙良，賢者。」","sentenceOrder":176},
  {"id":"s_work_han_thu_74_177","chapterId":"ch_work_han_thu_74","textTraditional":"〔七〕　蘇林曰：「趙談也。與遷父同諱，故曰同子。」","sentenceOrder":177},
  {"id":"s_work_han_thu_74_178","chapterId":"ch_work_han_thu_74","textTraditional":"〔八〕　師古曰：「忼音口朗反。」","sentenceOrder":178},
  {"id":"s_work_han_thu_74_179","chapterId":"ch_work_han_thu_74","textTraditional":"〔九〕　師古曰：「言侍從天子之車輿。」","sentenceOrder":179},
  {"id":"s_work_han_thu_74_180","chapterId":"ch_work_han_thu_74","textTraditional":"〔一０〕師古曰：「惟，思也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_74_181","chapterId":"ch_work_han_thu_74","textTraditional":"〔一一〕師古曰：「效，致也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_74_182","chapterId":"ch_work_han_thu_74","textTraditional":"〔一二〕師古曰：「搴，拔也，拔取敵人之旗也。搴音蹇。」","sentenceOrder":182},
  {"id":"s_work_han_thu_74_183","chapterId":"ch_work_han_thu_74","textTraditional":"〔一三〕韋昭曰：「周官太史位下大夫也。」臣瓚曰：「漢太史令千石，故比下大夫。」師古曰：「鄉讀曰嚮。嚮，曩昔時也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_74_184","chapterId":"ch_work_han_thu_74","textTraditional":"〔一四〕師古曰：「闒茸，猥賤也。闒，下也。茸，細毛也。言非豪桀也。闒，吐合反。茸，人勇反。」","sentenceOrder":184},
  {"id":"s_work_han_thu_74_185","chapterId":"ch_work_han_thu_74","textTraditional":"〔一五〕師古曰：「卬讀曰仰。信讀曰伸。列，陳也。」","sentenceOrder":185},
  {"id":"s_work_han_thu_74_186","chapterId":"ch_work_han_thu_74","textTraditional":"〔一六〕師古曰：「羞，辱也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_74_187","chapterId":"ch_work_han_thu_74","textTraditional":"且事本末未易明也。僕少負不羈之才，長無鄉曲之譽，〔一〕主上幸以先人之故，使得奉薄技，出入周衛之中。〔二〕僕以為戴盆何以望天，〔三〕故絕賓客之知，忘室家之業，日夜思竭其不肖之材力，務壹心營職，以求親媚於主上。而事乃有大謬不然者。夫僕與李陵俱居門下，素非相善也，趣舍異路，〔四〕未嘗銜盃酒接殷勤之歡。然僕觀其為人自奇士，事親孝，與士信，臨財廉，取予義，分別有讓，恭儉下人，〔五〕常思奮不顧身以徇國家之急。〔六〕其素所畜積也，〔七〕僕以為有國士之風。夫人臣出萬死不顧一生之計，赴公家之難，斯已奇矣。今舉事壹不當，而全軀保妻子之臣隨而媒孽其短，〔八〕僕誠私心痛之。且李陵提步卒不滿五千，深踐戎馬之地，足歷王庭，垂餌虎口，橫挑彊胡，〔九〕卬億萬之師，〔一０〕與單于連戰十餘日，所殺過當。〔一一〕虜救死扶傷不給，〔一二〕旃裘之君長咸震怖，乃悉徵左右賢王，舉引弓之民，〔一三〕一國共攻而圍之。轉鬥千里，矢盡道窮，救兵不至，士卒死傷如積。然李陵一呼勞軍，〔一四〕士無不起，躬流涕，沬血飲泣，張空弮，冒白刃，北首爭死敵。〔一五〕陵未沒時，使有來報，漢公卿王侯奉觴上壽。後數日，陵敗書聞，主上為之食不甘味，聽朝不怡。大臣憂懼，不知所出。僕竊不自料其卑賤，〔一六〕見主上慘悽怛悼，誠欲效其款款之愚。以為李陵素與士大夫絕甘分少，〔一七〕能得人之死力，雖古名將不過也。身雖陷敗，彼觀其意，且欲得其當而報漢。〔一八〕事已無可柰何，其所摧敗，功亦足以暴於天下。〔一九〕僕懷欲陳之，而未有路。適會召問，即以此指推言陵功，〔二０〕欲以廣主上之意，塞睚眥之辭。未能盡明，〔二一〕明主不深曉，以為僕沮貳師，而為李陵游說，〔二二〕遂下於理。拳拳之忠，終不能自列，〔二三〕因為誣上，卒從吏議。〔二四〕家貧，財賂不足以自贖，交遊莫救，左右親近不為壹言。身非木石，獨與法吏為伍，深幽囹圄之中，誰可告愬者！此正少卿所親見，僕行事豈不然邪？李陵既生降，隤其家聲，〔二五〕而僕又茸以蠶室，〔二六〕重為天下觀笑。〔二七〕悲夫！悲夫！","sentenceOrder":187},
  {"id":"s_work_han_thu_74_188","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　師古曰：「不羈，言其材質高遠，不可羈繫也。負者，亦言無此事也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_74_189","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　服虔曰：「薄技，薄材也。」師古曰：「周衛，言宿衛周密也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_74_190","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　如淳曰：「頭戴盆則不得望天、望天則不得戴盆，事不可兼施。言己方有所造，不暇修人事也。」師古曰：「言營職務耳，未論造書也。如說失之。」","sentenceOrder":190},
  {"id":"s_work_han_thu_74_191","chapterId":"ch_work_han_thu_74","textTraditional":"〔四〕　師古曰：「趣，所嚮也。舍，所廢也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_74_192","chapterId":"ch_work_han_thu_74","textTraditional":"〔五〕　師古曰：「下音胡亞反。」","sentenceOrder":192},
  {"id":"s_work_han_thu_74_193","chapterId":"ch_work_han_thu_74","textTraditional":"〔六〕　師古曰：「徇，從也，營也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_74_194","chapterId":"ch_work_han_thu_74","textTraditional":"〔七〕　師古曰：「畜讀曰蓄。」","sentenceOrder":194},
  {"id":"s_work_han_thu_74_195","chapterId":"ch_work_han_thu_74","textTraditional":"〔八〕　臣瓚曰：「媒謂遘合會之，孽謂為生其罪舋也。」師古曰：「媒如媒娉之媒，孽如麴孽之孽。一曰齊人謂麴餅為媒也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_74_196","chapterId":"ch_work_han_thu_74","textTraditional":"〔九〕　李奇曰：「挑音（銚）〔誂〕。」師古曰：「音徒了反。」","sentenceOrder":196},
  {"id":"s_work_han_thu_74_197","chapterId":"ch_work_han_thu_74","textTraditional":"〔一０〕師古曰：「卬讀曰仰。漢軍北向，匈奴南下，北方地高，故云然。」","sentenceOrder":197},
  {"id":"s_work_han_thu_74_198","chapterId":"ch_work_han_thu_74","textTraditional":"〔一一〕師古曰：「率計戰士，殺敵數多，故云過當也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_74_199","chapterId":"ch_work_han_thu_74","textTraditional":"〔一二〕師古曰：「給猶供也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_74_200","chapterId":"ch_work_han_thu_74","textTraditional":"〔一三〕師古曰：「能引弓者皆發之。」","sentenceOrder":200},
  {"id":"s_work_han_thu_74_201","chapterId":"ch_work_han_thu_74","textTraditional":"〔一四〕師古曰：「呼音火故反。」","sentenceOrder":201},
  {"id":"s_work_han_thu_74_202","chapterId":"ch_work_han_thu_74","textTraditional":"〔一五〕孟康曰：「沬音頮。」李奇曰：「弮，弩弓也。」師古曰：「沬，古頮字。頮，洒面也。言流血在面如盥頮。冒，犯也。首，嚮也。沬音呼內反，字從午未之未。弮音丘權反。又音眷。冒音莫克反。首音式救反。讀者乃以拳掔之拳，大謬矣。拳則屈指，不當言張。陵時矢盡，故張弩之空弓，非是手拳也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_74_203","chapterId":"ch_work_han_thu_74","textTraditional":"〔一六〕師古曰：「料，量也，音聊。」","sentenceOrder":203},
  {"id":"s_work_han_thu_74_204","chapterId":"ch_work_han_thu_74","textTraditional":"〔一七〕師古曰：「自絕旨甘，而與眾人分之，共同其少多也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_74_205","chapterId":"ch_work_han_thu_74","textTraditional":"〔一八〕師古曰：「欲於匈奴立功而歸，以（其當）〔當其〕破敗之罪。」","sentenceOrder":205},
  {"id":"s_work_han_thu_74_206","chapterId":"ch_work_han_thu_74","textTraditional":"〔一九〕師古曰：「謂摧破匈奴之兵也。」","sentenceOrder":206},
  {"id":"s_work_han_thu_74_207","chapterId":"ch_work_han_thu_74","textTraditional":"〔二０〕師古曰：「指，意也。」","sentenceOrder":207},
  {"id":"s_work_han_thu_74_208","chapterId":"ch_work_han_thu_74","textTraditional":"〔二一〕師古曰：「睚眥，舉目眥也，猶言顧瞻之頃也。睚音厓。眥音才賜反。」","sentenceOrder":208},
  {"id":"s_work_han_thu_74_209","chapterId":"ch_work_han_thu_74","textTraditional":"〔二二〕師古曰：「沮，毀壞也。音才汝反。」","sentenceOrder":209},
  {"id":"s_work_han_thu_74_210","chapterId":"ch_work_han_thu_74","textTraditional":"〔二三〕師古曰：「拳拳，忠謹之貌。劉向傳作惓惓字，音義同耳。列，陳也。」","sentenceOrder":210},
  {"id":"s_work_han_thu_74_211","chapterId":"ch_work_han_thu_74","textTraditional":"〔二四〕師古曰：「卒，終也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_74_212","chapterId":"ch_work_han_thu_74","textTraditional":"〔二五〕孟康曰：「家世為將有名聲，陵降而隤之也。」師古曰：「隤，墜也，音頹。」","sentenceOrder":212},
  {"id":"s_work_han_thu_74_213","chapterId":"ch_work_han_thu_74","textTraditional":"〔二六〕蘇林曰：「茸，次也，若人相俾次。」師古曰：「此說非也。茸音人勇反，推也。蠶室，初腐刑所居溫密之室也。謂推致蠶室之中也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_74_214","chapterId":"ch_work_han_thu_74","textTraditional":"〔二七〕師古曰：「觀視之而笑也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_74_215","chapterId":"ch_work_han_thu_74","textTraditional":"事未易一二為俗人言也。僕之先人非有剖符丹書之功，文史星曆近乎卜祝之間，固主上所戲弄，倡優畜之，流俗之所輕也。假令僕伏法受誅，若九牛亡一毛，與螻螘何異？〔一〕而世又不與能死節者比，〔二〕特以為智窮罪極，不能自免，卒就死耳。何也？素所自樹立使然。人固有一死，死有重於泰山，或輕於鴻毛，用之所趨異也。〔三〕太上不辱先，其次不辱身，其次不辱理色，其次不辱辭令，其次詘體受辱，其次易服受辱，其次關木索被箠楚受辱，〔四〕其次鬄毛髮嬰金鐵受辱，〔五〕其次毀肌膚斷支體受辱，最下腐刑，極矣。〔六〕傳曰「刑不上大夫」，此言士節不可不厲也。猛虎處深山，百獸震恐，及其在阱檻之中，搖尾而求食，〔七〕積威約之漸也。故士有畫地為牢勢不入，削木為吏議不對，定計於鮮也。〔八〕今交手足，受木索，暴肌膚，受榜箠，〔九〕幽於圜牆之中，〔一０〕當此之時，見獄吏則頭槍地，〔一一〕視徒隸則心惕息。〔一二〕何者？積威約之勢也。及已至此，言不辱者，所謂彊顏耳，曷足貴乎！〔一三〕且西伯，伯也，拘牖里；李斯，相也，具五刑；〔一四〕淮陰，王也，受械於陳；〔一五〕彭越、張敖南鄉稱孤，繫獄具罪；〔一六〕絳侯誅諸呂，權傾五伯，囚於請室；〔一七〕魏其，大將也，衣赭關三木；〔一八〕季布為朱家鉗奴；灌夫受辱居室。此人皆身至王侯將相，聲聞鄰國，及罪至罔加，不能引決自財。〔一九〕在塵埃之中，古今一體，安在其不辱也！由此言之，勇怯，勢也；彊弱，形也。審矣，曷足怪乎！且人不能蚤自財繩墨之外，已稍陵夷至於鞭箠之間，乃欲引節，斯不亦遠乎！古人所以重施刑於大夫者，殆為此也〔二０〕。夫人情莫不貪生惡死，念親戚，顧妻子，至激於義理者不然，〔二一〕乃有不得已也。今僕不幸，蚤失二親，無兄弟之親，獨身孤立，少卿視僕於妻子何如哉？且勇者不必死節，怯夫慕義，何處不勉焉！〔二二〕僕雖怯耎欲苟活，〔二三〕亦頗識去就之分矣，何至自湛溺累紲之辱哉！〔二四〕且夫臧獲婢妾猶能引決，〔二五〕況若僕之不得已乎！所以隱忍苟活，函糞土之中而不辭者，恨私心有所不盡，鄙沒世而文采不表於後也。","sentenceOrder":215},
  {"id":"s_work_han_thu_74_216","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　師古曰：「螻，螻蛄也。螘，蚍蜉也。皆蟲之微小者。螻音樓。」","sentenceOrder":216},
  {"id":"s_work_han_thu_74_217","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　師古曰：「與，許也。不許其能死節。」","sentenceOrder":217},
  {"id":"s_work_han_thu_74_218","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　師古曰：「趨讀曰趣。趣，嚮也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_74_219","chapterId":"ch_work_han_thu_74","textTraditional":"〔四〕　師古曰：「箠，杖也，音止橤反。」","sentenceOrder":219},
  {"id":"s_work_han_thu_74_220","chapterId":"ch_work_han_thu_74","textTraditional":"〔五〕　師古曰：「嬰，繞也。鬄音吐計反。」","sentenceOrder":220},
  {"id":"s_work_han_thu_74_221","chapterId":"ch_work_han_thu_74","textTraditional":"〔六〕　師古曰：「腐刑，解在景紀。」","sentenceOrder":221},
  {"id":"s_work_han_thu_74_222","chapterId":"ch_work_han_thu_74","textTraditional":"〔七〕　師古曰：「穽，掘地以陷獸也，音才性反。」","sentenceOrder":222},
  {"id":"s_work_han_thu_74_223","chapterId":"ch_work_han_thu_74","textTraditional":"〔八〕　文穎曰：「未遇刑自殺，為鮮明也。」","sentenceOrder":223},
  {"id":"s_work_han_thu_74_224","chapterId":"ch_work_han_thu_74","textTraditional":"〔九〕　師古曰：「榜音彭。」","sentenceOrder":224},
  {"id":"s_work_han_thu_74_225","chapterId":"ch_work_han_thu_74","textTraditional":"〔一０〕師古曰：「圜牆，獄也，周禮謂之圜土。」","sentenceOrder":225},
  {"id":"s_work_han_thu_74_226","chapterId":"ch_work_han_thu_74","textTraditional":"〔一一〕師古曰：「槍，千羊反。」","sentenceOrder":226},
  {"id":"s_work_han_thu_74_227","chapterId":"ch_work_han_thu_74","textTraditional":"〔一二〕師古曰：「惕，懼也。息，喘息也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_74_228","chapterId":"ch_work_han_thu_74","textTraditional":"〔一三〕師古曰：「強音其兩反。」","sentenceOrder":228},
  {"id":"s_work_han_thu_74_229","chapterId":"ch_work_han_thu_74","textTraditional":"〔一四〕師古曰：「說在刑法志。」","sentenceOrder":229},
  {"id":"s_work_han_thu_74_230","chapterId":"ch_work_han_thu_74","textTraditional":"〔一五〕師古曰：「高祖偽遊雲夢，而信至陳上謁，（助）〔即〕見囚執。械謂桎梏之。」","sentenceOrder":230},
  {"id":"s_work_han_thu_74_231","chapterId":"ch_work_han_thu_74","textTraditional":"〔一六〕師古曰：「或繫於獄，或至大罪也。鄉讀曰嚮。」","sentenceOrder":231},
  {"id":"s_work_han_thu_74_232","chapterId":"ch_work_han_thu_74","textTraditional":"〔一七〕師古曰：「伯讀曰霸。」","sentenceOrder":232},
  {"id":"s_work_han_thu_74_233","chapterId":"ch_work_han_thu_74","textTraditional":"〔一八〕師古曰：「三木，在頸及手足。」","sentenceOrder":233},
  {"id":"s_work_han_thu_74_234","chapterId":"ch_work_han_thu_74","textTraditional":"〔一九〕師古曰：「財與裁同，古通用字。」","sentenceOrder":234},
  {"id":"s_work_han_thu_74_235","chapterId":"ch_work_han_thu_74","textTraditional":"〔二０〕師古曰：「重，難也。」","sentenceOrder":235},
  {"id":"s_work_han_thu_74_236","chapterId":"ch_work_han_thu_74","textTraditional":"〔二一〕師古曰：「言激於義理者，則不顧念親戚妻子。」","sentenceOrder":236},
  {"id":"s_work_han_thu_74_237","chapterId":"ch_work_han_thu_74","textTraditional":"〔二二〕師古曰：「勇敢之人闇於分理，未必能死名節。怯懦之夫心知慕義，則處處皆能勉勵也。」","sentenceOrder":237},
  {"id":"s_work_han_thu_74_238","chapterId":"ch_work_han_thu_74","textTraditional":"〔二三〕師古曰：「耎，柔弱也，音人阮反。」","sentenceOrder":238},
  {"id":"s_work_han_thu_74_239","chapterId":"ch_work_han_thu_74","textTraditional":"〔二四〕師古曰：「湛讀曰沈。累音力追反。」","sentenceOrder":239},
  {"id":"s_work_han_thu_74_240","chapterId":"ch_work_han_thu_74","textTraditional":"〔二五〕應劭曰：「揚雄方言云：『海岱之間，罵奴曰臧，罵婢曰獲。燕之北郊，民而{〈工几〉耳}婢謂之臧，女而婦奴謂之獲。』晉灼曰：「臧獲，敗敵所被虜獲為奴隸者。」師古曰：「應說是也。」","sentenceOrder":240},
  {"id":"s_work_han_thu_74_241","chapterId":"ch_work_han_thu_74","textTraditional":"古者富貴而名摩滅，不可勝記，唯俶儻非常之人稱焉。蓋西伯拘而演周易；仲尼厄而作春秋；屈原放逐，乃賦離騷；左丘失明，厥有國語；孫子髕腳，兵法修列；〔一〕不韋遷蜀，世傳呂覽；〔二〕韓非囚秦，說難、孤憤。〔三〕詩三百篇，大氐賢聖發憤之所為作也。〔四〕此人皆意有所鬱結，不得通其道，故述往事，思來者〔五〕。及如左丘明無目，孫子斷足，終不可用，退論書策以舒其憤，思垂空文以自見。〔六〕僕竊不遜，近自託於無能之辭，網羅天下放失舊聞，考之行事，稽其成敗〔七〕興壞之理，凡百三十篇，亦欲以究天人之際，通古今之變，成一家之言。草創未就，適會此禍，惜其不成，是以就極刑而無慍色。僕誠已著此書，藏之名山，傳之其人通邑大都，〔八〕則僕償前辱之責，雖萬被戮，豈有悔哉！然此可為智者道，難為俗人言也。","sentenceOrder":241},
  {"id":"s_work_han_thu_74_242","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　文穎曰：「孫子與龐涓學，而為龐涓所斷足。」師古曰：「髕音頻忍反。」","sentenceOrder":242},
  {"id":"s_work_han_thu_74_243","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　蘇林曰：「呂氏春秋篇名八覽、六論。」","sentenceOrder":243},
  {"id":"s_work_han_thu_74_244","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　師古曰：「說難、孤憤，韓子之篇名。」","sentenceOrder":244},
  {"id":"s_work_han_thu_74_245","chapterId":"ch_work_han_thu_74","textTraditional":"〔四〕　師古曰：「氐，歸也，音丁禮反。」","sentenceOrder":245},
  {"id":"s_work_han_thu_74_246","chapterId":"ch_work_han_thu_74","textTraditional":"〔五〕　師古曰：「令將來之人，見己志也。」","sentenceOrder":246},
  {"id":"s_work_han_thu_74_247","chapterId":"ch_work_han_thu_74","textTraditional":"〔六〕　師古曰：「見，胡電反。」","sentenceOrder":247},
  {"id":"s_work_han_thu_74_248","chapterId":"ch_work_han_thu_74","textTraditional":"〔七〕　師古曰：「稽，計也。」","sentenceOrder":248},
  {"id":"s_work_han_thu_74_249","chapterId":"ch_work_han_thu_74","textTraditional":"〔八〕　師古曰：「其人謂能行其書者。」","sentenceOrder":249},
  {"id":"s_work_han_thu_74_250","chapterId":"ch_work_han_thu_74","textTraditional":"且負下未易居，下流多謗議。僕以口語遇遭此禍，重為鄉黨戮笑，汙辱先人，亦何面目復上父母之丘墓乎？雖累百世，垢彌甚耳！是以腸一日而九回，居則忽忽若有所亡，出則不知所如往。〔一〕每念斯恥，汗未嘗不發背霑衣也。身直為閨閤之臣，寧得自引深臧於巖穴邪！故且從俗浮湛，與時俯仰，〔二〕以通其狂惑。今少卿乃教以推賢進士，無乃與僕之私指謬乎。〔三〕今雖欲自彫瑑，〔四〕曼辭以自解，〔五〕無益，於俗不信，祗取辱耳。〔六〕要之死日，然後是非乃定。書不能盡意，故略陳固陋。","sentenceOrder":250},
  {"id":"s_work_han_thu_74_251","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　師古曰：「如亦往也。」","sentenceOrder":251},
  {"id":"s_work_han_thu_74_252","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　師古曰：「湛讀曰沉。」","sentenceOrder":252},
  {"id":"s_work_han_thu_74_253","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　師古曰：「指，意也。」","sentenceOrder":253},
  {"id":"s_work_han_thu_74_254","chapterId":"ch_work_han_thu_74","textTraditional":"〔四〕　師古曰：「瑑，刻也，音篆。」","sentenceOrder":254},
  {"id":"s_work_han_thu_74_255","chapterId":"ch_work_han_thu_74","textTraditional":"〔五〕　如淳曰：「曼，美也。」師古曰：「曼音萬。」","sentenceOrder":255},
  {"id":"s_work_han_thu_74_256","chapterId":"ch_work_han_thu_74","textTraditional":"〔六〕　師古曰：「祇，適也。」","sentenceOrder":256},
  {"id":"s_work_han_thu_74_257","chapterId":"ch_work_han_thu_74","textTraditional":"遷既死後，其書稍出。宣帝時，遷外孫平通侯楊惲祖述其書，遂宣布焉。至王莽時，求封遷後，為史通子。〔一〕","sentenceOrder":257},
  {"id":"s_work_han_thu_74_258","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　應劭曰：「以遷世為史（宜）〔官〕，通於古今也。」李奇曰：「史通國子爵也。」","sentenceOrder":258},
  {"id":"s_work_han_thu_74_259","chapterId":"ch_work_han_thu_74","textTraditional":"贊曰：自古書契之作而有史官，其載籍博矣。至孔氏篹之，〔一〕上（繼）〔斷〕唐堯，下訖秦繆。唐虞以前雖有遺文，其語不經，〔二〕故言黃帝、顓頊之事未可明也。及孔子因魯史記而作春秋，而左丘明論輯其本事以為之傳，〔三〕又篹異同為國語。又有世本，錄黃帝以來至春秋時帝王公侯卿大夫祖世所出。春秋之後，七國並爭，〔四〕秦兼諸侯，有戰國策。漢興伐秦定天下，有楚漢春秋。故司馬遷據左氏、國語，采世本、戰國策，述楚漢春秋，接其後事，訖于（大）〔天〕漢。其言秦漢，詳矣。至於采經摭傳，〔五〕分散數家之事，甚多疏略，或有抵梧。〔六〕亦其涉獵者廣博，貫穿經傳，馳騁古今，上下數千載間，斯以勤矣。又其是非頗繆於聖人，〔七〕論大道則先黃老而後六經，序遊俠則退處士而進姦雄，述貨殖則崇勢利而羞賤貧，此其所蔽也。然自劉向、揚雄博極群書，皆稱遷有良史之材，服其善序事理，辨而不華，質而不俚，〔八〕其文直，其事核〔九〕，不虛美，不隱惡，故謂之實錄。〔一０〕烏呼！以遷之博物洽聞，而不能以知自全，既陷極刑，幽而發憤，書亦信矣。〔一一〕跡其所以自傷悼，小雅巷伯之倫。〔一二〕夫唯大雅「既明且哲，能保其身」，難矣哉！〔一三〕","sentenceOrder":259},
  {"id":"s_work_han_thu_74_260","chapterId":"ch_work_han_thu_74","textTraditional":"〔一〕　師古曰：「篹與撰同。」","sentenceOrder":260},
  {"id":"s_work_han_thu_74_261","chapterId":"ch_work_han_thu_74","textTraditional":"〔二〕　師古曰：「非經典所說。」","sentenceOrder":261},
  {"id":"s_work_han_thu_74_262","chapterId":"ch_work_han_thu_74","textTraditional":"〔三〕　師古曰：「輯與集同。」","sentenceOrder":262},
  {"id":"s_work_han_thu_74_263","chapterId":"ch_work_han_thu_74","textTraditional":"〔四〕　服虔曰：「關東六國，與秦七國。」","sentenceOrder":263},
  {"id":"s_work_han_thu_74_264","chapterId":"ch_work_han_thu_74","textTraditional":"〔五〕　師古曰：「摭，拾也，音之亦反。」","sentenceOrder":264},
  {"id":"s_work_han_thu_74_265","chapterId":"ch_work_han_thu_74","textTraditional":"〔六〕　如淳曰：「梧讀曰迕，相觸迕也。」師古曰：「抵，觸也。梧，相支柱不安也。梧音悟。」","sentenceOrder":265},
  {"id":"s_work_han_thu_74_266","chapterId":"ch_work_han_thu_74","textTraditional":"〔七〕　師古曰：「頗，普我反。」","sentenceOrder":266},
  {"id":"s_work_han_thu_74_267","chapterId":"ch_work_han_thu_74","textTraditional":"〔八〕　劉德曰：「俚，鄙也。」如淳曰：「言雖質，猶不如閭里之鄙言也。」師古曰：「劉說是也。俚音里。」","sentenceOrder":267},
  {"id":"s_work_han_thu_74_268","chapterId":"ch_work_han_thu_74","textTraditional":"〔九〕　師古曰：「核，堅實也。」","sentenceOrder":268},
  {"id":"s_work_han_thu_74_269","chapterId":"ch_work_han_thu_74","textTraditional":"〔一０〕應劭曰：「言其錄事實。」","sentenceOrder":269},
  {"id":"s_work_han_thu_74_270","chapterId":"ch_work_han_thu_74","textTraditional":"〔一一〕師古曰：「言其報任安書，自陳己志，信不謬。」","sentenceOrder":270},
  {"id":"s_work_han_thu_74_271","chapterId":"ch_work_han_thu_74","textTraditional":"〔一二〕師古曰：「巷伯，奄官也，遇讒而作詩，列在小雅。其詩曰『萋兮菲兮，成是貝錦』是也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_74_272","chapterId":"ch_work_han_thu_74","textTraditional":"〔一三〕師古曰：「尹吉甫作烝民之詩，美宣王而論仲山甫之德，曰『既明且哲，以保其身』。其詩列於大雅，故贊云然。」","sentenceOrder":272},
  {"id":"s_work_han_thu_74_273","chapterId":"ch_work_han_thu_74","textTraditional":"校勘記","sentenceOrder":273},
  {"id":"s_work_han_thu_74_274","chapterId":"ch_work_han_thu_74","textTraditional":"二七０七頁一一行　失其〔所〕守之職也。　景祐、殿本都有「所」字。","sentenceOrder":274},
  {"id":"s_work_han_thu_74_275","chapterId":"ch_work_han_thu_74","textTraditional":"二七０八頁一六行　錯音千（古）〔各〕反。　景祐、殿本都作「各」。王先謙說作「各」是。","sentenceOrder":275},
  {"id":"s_work_han_thu_74_276","chapterId":"ch_work_han_thu_74","textTraditional":"二七一九頁　七行　〔一〕曰違犯禮義也。　景祐、殿本都有「一」字。王先謙說此奪。","sentenceOrder":276},
  {"id":"s_work_han_thu_74_277","chapterId":"ch_work_han_thu_74","textTraditional":"二七二０頁一０行　是余之罪夫！〔一一〕身虧不用矣。　注〔二〕原在「罪」字下，王先謙說殿本在「夫」字下，是。","sentenceOrder":277},
  {"id":"s_work_han_thu_74_278","chapterId":"ch_work_han_thu_74","textTraditional":"二七二七頁一五行　攻城（戰野）〔野戰〕，　景祐、殿本都作「野戰」。","sentenceOrder":278},
  {"id":"s_work_han_thu_74_279","chapterId":"ch_work_han_thu_74","textTraditional":"二七三一頁　三行　挑音（銚）〔誂〕。　景祐、殿本都作「誂」。","sentenceOrder":279},
  {"id":"s_work_han_thu_74_280","chapterId":"ch_work_han_thu_74","textTraditional":"二七三一頁一四行　以（其當）〔當其〕破敗之罪。　殿本作「當其」。王先謙說殿本是。","sentenceOrder":280},
  {"id":"s_work_han_thu_74_281","chapterId":"ch_work_han_thu_74","textTraditional":"二七三四頁一三行　（助）〔即〕見囚執。　景祐、殿本都作「即」。王先謙說作「即」是。","sentenceOrder":281},
  {"id":"s_work_han_thu_74_282","chapterId":"ch_work_han_thu_74","textTraditional":"二七三七頁　七行　以遷世為史（宜）〔官〕，　景祐、殿本都作「官」，此誤。","sentenceOrder":282},
  {"id":"s_work_han_thu_74_283","chapterId":"ch_work_han_thu_74","textTraditional":"二七三七頁　八行　上（繼）〔斷〕唐堯，下訖秦繆。　吳承仕說，「繼」字無義，字當為「斷」。藝文志「斷自堯典」，儒林傳「上斷唐虞」，並其證。按藝文志作「上斷于堯」。","sentenceOrder":283},
  {"id":"s_work_han_thu_74_284","chapterId":"ch_work_han_thu_74","textTraditional":"二七三七頁一二行　接其後事，訖于（大）〔天〕漢。　楊樹達說，「大漢」無義，當作「天漢」。天漢，武帝年號。","sentenceOrder":284},
  {"id":"s_work_han_thu_75_1","chapterId":"ch_work_han_thu_75","textTraditional":"師古曰：「諸帝子傳皆言王，而此獨云子者，以戾太子在其中也。」","sentenceOrder":1},
  {"id":"s_work_han_thu_75_2","chapterId":"ch_work_han_thu_75","textTraditional":"孝武皇帝六男。衛皇后生戾太子，趙婕妤生孝昭帝，王夫人生齊懷王閎，〔一〕李姬生燕剌王旦、廣陵厲王胥，〔二〕李夫人生昌邑哀王髆。〔三〕","sentenceOrder":2},
  {"id":"s_work_han_thu_75_3","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「閎音宏。」","sentenceOrder":3},
  {"id":"s_work_han_thu_75_4","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「不知官秩，故云李姬。諡法『暴戾無親曰剌』。剌音來葛反。」","sentenceOrder":4},
  {"id":"s_work_han_thu_75_5","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「髆音博。」","sentenceOrder":5},
  {"id":"s_work_han_thu_75_6","chapterId":"ch_work_han_thu_75","textTraditional":"戾太子據，元狩元年立為皇太子，年七歲矣。初，上年二十九乃得太子，甚喜，為立禖，〔一〕使東方朔、枚皋作禖祝。〔二〕少壯，詔受公羊春秋，〔三〕又從瑕丘江公受穀梁。及冠就宮，上為立博望苑，〔四〕使通賓客，從其所好，故多以異端進者。元鼎四年，納史良娣，〔五〕產子男進，號曰史皇孫。〔六〕","sentenceOrder":6},
  {"id":"s_work_han_thu_75_7","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「禖，求子之神也，解在枚皋傳。」","sentenceOrder":7},
  {"id":"s_work_han_thu_75_8","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「祝，禖之祝辭。」","sentenceOrder":8},
  {"id":"s_work_han_thu_75_9","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「少壯者，言漸長大也。少讀如本字。」","sentenceOrder":9},
  {"id":"s_work_han_thu_75_10","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　師古曰：「取其廣博觀望也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_75_11","chapterId":"ch_work_han_thu_75","textTraditional":"〔五〕　韋昭曰：「良娣，太子之內官也。太子有妃，有良娣，有孺子，凡三等。」師古曰：「娣音弟。」","sentenceOrder":11},
  {"id":"s_work_han_thu_75_12","chapterId":"ch_work_han_thu_75","textTraditional":"〔六〕　張晏曰：「皆以舅氏姓為氏，以相別也。」師古曰：「進者，皇孫名。」","sentenceOrder":12},
  {"id":"s_work_han_thu_75_13","chapterId":"ch_work_han_thu_75","textTraditional":"武帝末，衛后寵衰，江充用事。充與太子及衛氏有隙，〔一〕恐上晏駕後為太子所誅，會巫蠱事起，充因此為姦。是時，上春秋高，意多所惡，以為左右皆為蠱道祝詛，窮治其事。丞相公孫賀父子，陽石、諸邑公主，〔二〕及皇后弟子長平侯衛伉皆坐誅。〔三〕語在公孫賀、江充傳。","sentenceOrder":13},
  {"id":"s_work_han_thu_75_14","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「充為直指使者，劾太子家車行馳道上，沒入車馬，太子求充，充不聽也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_75_15","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「兩公主。」","sentenceOrder":15},
  {"id":"s_work_han_thu_75_16","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「伉音抗，又音剛。」","sentenceOrder":16},
  {"id":"s_work_han_thu_75_17","chapterId":"ch_work_han_thu_75","textTraditional":"充典治巫蠱，既知上意，白言宮中有蠱氣，入宮至省中，壞御座掘地。上使按道侯韓說、御史章贛、黃門蘇文等助充。〔一〕充遂至太子宮掘蠱，得桐木人。時上疾，辟暑甘泉宮，〔二〕獨皇后、太子在。〔三〕太子召問少傅石德，〔四〕德懼為師傅并誅，因謂太子曰：「前丞相父子、兩公主及衛氏皆坐此，今巫與使者掘地得徵驗，不知巫置之邪，將實有也，無以自明，可矯以節收捕充等繫獄，〔五〕窮治其姦詐。且上疾在甘泉，皇后及家吏請問皆不報，〔六〕上存亡未可知，而姦臣如此，太子將不念秦扶蘇事耶？」〔七〕太子急，然德言。","sentenceOrder":17},
  {"id":"s_work_han_thu_75_18","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「說讀曰悅。贛音貢。」","sentenceOrder":18},
  {"id":"s_work_han_thu_75_19","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「辟讀曰避。」","sentenceOrder":19},
  {"id":"s_work_han_thu_75_20","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「在京師。」","sentenceOrder":20},
  {"id":"s_work_han_thu_75_21","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　師古曰：「石慶子。」","sentenceOrder":21},
  {"id":"s_work_han_thu_75_22","chapterId":"ch_work_han_thu_75","textTraditional":"〔五〕　師古曰：「矯，託也，託詔命也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_75_23","chapterId":"ch_work_han_thu_75","textTraditional":"〔六〕　蘇林曰：「家吏，皇后吏也。」臣瓚曰：「太子稱家，家吏是太子吏也。」師古曰：「既言皇后及家吏，此為皇后吏及太子吏耳。瓚說是也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_75_24","chapterId":"ch_work_han_thu_75","textTraditional":"〔七〕　韋昭曰：「始皇死，趙高詐殺扶蘇而立胡亥也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_75_25","chapterId":"ch_work_han_thu_75","textTraditional":"征和二年七月壬午，乃使客為使者收捕充等。按道侯說疑使者有（詔）〔詐〕，不肯受詔，客格殺說。御史章贛被創突亡，自歸甘泉。太子使舍人無且〔一〕持節夜入未央宮殿長秋門，因長御倚華〔二〕具白皇后，發中廄車載射士，〔三〕出武庫兵，發長樂宮衛，告令百官曰江充反。乃斬充以徇，炙胡巫上林中。〔四〕遂部賓客為將率，與丞相劉屈氂等戰。長安中擾亂，言太子反，以故眾不肯附。太子兵敗，亡，不得。〔五〕","sentenceOrder":25},
  {"id":"s_work_han_thu_75_26","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「且音子閭反。」","sentenceOrder":26},
  {"id":"s_work_han_thu_75_27","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　鄭氏曰：「長音長者。」如淳曰：「漢儀注女長御比侍中，皇后見娙娥以下，長御稱謝。倚華，字也。」師古曰：「倚音於綺反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_75_28","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「中廄，皇后車馬所在也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_75_29","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　服虔曰：「作巫蠱之胡人也。炙，燒也。」師古曰：「胡巫受充意指，妄作蠱狀，太子特忿，且欲得其情實，故以火炙之，令毒痛耳。」","sentenceOrder":29},
  {"id":"s_work_han_thu_75_30","chapterId":"ch_work_han_thu_75","textTraditional":"〔五〕　師古曰：「太子出亡，而吏追捕不得也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_75_31","chapterId":"ch_work_han_thu_75","textTraditional":"上怒甚，群下憂懼，不知所出。〔一〕壺關三老茂上書曰：〔二〕「臣聞父者猶天，母者猶地，子猶萬物也。故天平地安，陰陽和調，物乃茂成；父慈母愛室家之中，子乃孝順。陰陽不和則萬物夭傷，父子不和則室家（散）〔喪〕亡。故父不父則子不子，君不君則臣不臣，雖有粟，吾豈得而食諸！〔三〕昔者虞舜，孝之至也，而不中於瞽叟；〔四〕孝己被謗，伯奇放流，〔五〕骨肉至親，父子相疑。何者？積毀之所生也。由是觀之，子無不孝，而父有不察。（令）〔今〕皇太子為漢適嗣，〔六〕承萬世之業，體祖宗之重，親則皇帝之宗子也。江充，布衣之人，閭閻之隸臣耳，〔七〕陛下顯而用之，銜至尊之命以迫蹴皇太子，〔八〕造飾姦詐，群邪錯謬，是以親戚之路鬲塞而不通。〔九〕太子進則不得上見，退則困於亂臣，獨冤結而亡告，不忍忿忿之心，起而殺充，恐懼逋逃，〔一０〕子盜父兵以救難自免耳，臣竊以為無邪心。詩云：『營營青蠅，止于藩；愷悌君子，無信讒言；讒言罔極，交亂四國。』〔一一〕往者江充讒殺趙太子，天下莫不聞，其罪固宜。〔一二〕陛下不省察，深過太子，〔一三〕發盛怒，舉大兵而求之，三公自將，智者不敢言，辯士不敢說，臣竊痛之。臣聞子胥盡忠而忘其號，〔一四〕比干盡仁而遺其身，〔一五〕忠臣竭誠不顧鈇鉞之誅〔一六〕以陳其愚，志在匡君安社稷也。〔一七〕詩云：『取彼譖人，投畀豺虎。』〔一八〕唯陛下寬心慰意，少察所親，〔一九〕毋患太子之非，亟罷甲兵，無令太子久亡。〔二０〕臣不勝惓惓，〔二一〕出一旦之命，待罪建章闕下。」書奏，天子感寤。","sentenceOrder":31},
  {"id":"s_work_han_thu_75_32","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「計無所出。」","sentenceOrder":32},
  {"id":"s_work_han_thu_75_33","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「壺關，上黨之縣也。荀悅漢紀云令狐茂，班史不載其姓，不知於何得也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_75_34","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「論語云齊景公問政於孔子，孔子對曰：『君君，臣臣，父父，子子。』公曰：『善哉！信如君不君，臣不臣，父不父，子不子，雖有粟，吾豈得而食諸！』言父子君臣之道不立，則國必危亡，倉廩雖多，吾不得食也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_75_35","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　師古曰：「中，當也。瞽叟，舜父也。言不當其意也。中音竹仲反。」","sentenceOrder":35},
  {"id":"s_work_han_thu_75_36","chapterId":"ch_work_han_thu_75","textTraditional":"〔五〕　師古曰：「孝己、伯奇並已解於上。」","sentenceOrder":36},
  {"id":"s_work_han_thu_75_37","chapterId":"ch_work_han_thu_75","textTraditional":"〔六〕　師古曰：「適讀曰嫡。」","sentenceOrder":37},
  {"id":"s_work_han_thu_75_38","chapterId":"ch_work_han_thu_75","textTraditional":"〔七〕　師古曰：「隸，賤也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_75_39","chapterId":"ch_work_han_thu_75","textTraditional":"〔八〕　師古曰：「蹴音千六反。」","sentenceOrder":39},
  {"id":"s_work_han_thu_75_40","chapterId":"ch_work_han_thu_75","textTraditional":"〔九〕　師古曰：「鬲與隔同。」","sentenceOrder":40},
  {"id":"s_work_han_thu_75_41","chapterId":"ch_work_han_thu_75","textTraditional":"〔一０〕師古曰：「逋，亡也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_75_42","chapterId":"ch_work_han_thu_75","textTraditional":"〔一一〕師古曰：「小雅青蠅之詩也。營營，往來之貌也。藩，籬也。愷，樂；悌，易也。言青蠅來往，止於藩籬，變白作黑，讒人搆毀，間親令疏，樂易之君子不當信用。若讒言無極，則四國亦以交亂，宜深察也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_75_43","chapterId":"ch_work_han_thu_75","textTraditional":"〔一二〕師古曰：「充宜得罪也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_75_44","chapterId":"ch_work_han_thu_75","textTraditional":"〔一三〕師古曰：「以太子為罪過而深責之。」","sentenceOrder":44},
  {"id":"s_work_han_thu_75_45","chapterId":"ch_work_han_thu_75","textTraditional":"〔一四〕師古曰：「忘，亡也。吳王殺之，被以惡名，失其善稱號。」","sentenceOrder":45},
  {"id":"s_work_han_thu_75_46","chapterId":"ch_work_han_thu_75","textTraditional":"〔一五〕師古曰：「比干，殷之賢臣，以道諫紂，紂怒殺之，而剖其心也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_75_47","chapterId":"ch_work_han_thu_75","textTraditional":"〔一六〕師古曰：「鈇，所以斫人，如今莝刃也，音膚。」","sentenceOrder":47},
  {"id":"s_work_han_thu_75_48","chapterId":"ch_work_han_thu_75","textTraditional":"〔一七〕師古曰：「匡，正也。正其失也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_75_49","chapterId":"ch_work_han_thu_75","textTraditional":"〔一八〕師古曰：「小雅巷伯之詩。言譖讒之人，誠可疾惡，願投與猛獸食之。畀音必寐反。」","sentenceOrder":49},
  {"id":"s_work_han_thu_75_50","chapterId":"ch_work_han_thu_75","textTraditional":"〔一九〕師古曰：「父子之道，天性之親也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_75_51","chapterId":"ch_work_han_thu_75","textTraditional":"〔二０〕師古曰：「亟，急也，音居力反。」","sentenceOrder":51},
  {"id":"s_work_han_thu_75_52","chapterId":"ch_work_han_thu_75","textTraditional":"〔二一〕師古曰：「惓讀曰拳，解在劉向傳。」","sentenceOrder":52},
  {"id":"s_work_han_thu_75_53","chapterId":"ch_work_han_thu_75","textTraditional":"太子之亡也，東至湖，〔一〕臧匿泉鳩里。〔二〕主人家貧，常賣屨以給太子。太子有故人在湖，聞其富贍，使人呼之〔三〕而發覺。吏圍捕太子，太子自度不得脫，〔四〕即入室距戶自經。山陽男子張富昌為卒，足蹋開戶，新安令史李壽趨抱解太子，主人公遂格鬥死，皇孫二人皆并遇害。上既傷太子，乃下詔曰：「蓋行疑賞，所以申信也。其封李壽為邘侯，〔五〕張富昌為題侯。」〔六〕","sentenceOrder":53},
  {"id":"s_work_han_thu_75_54","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「湖，縣名，今虢州闅鄉、湖城二縣皆其地也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_75_55","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「泉鳩水今在闅鄉縣東南十五里，見有戾太子冢，冢在澗東也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_75_56","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「贍，足也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_75_57","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　師古曰：「度音大各反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_75_58","chapterId":"ch_work_han_thu_75","textTraditional":"〔五〕　韋昭曰：「邘在河內。」師古曰：「為其解救太子也。邘音于。」","sentenceOrder":58},
  {"id":"s_work_han_thu_75_59","chapterId":"ch_work_han_thu_75","textTraditional":"〔六〕　孟康曰：「縣名也。」晉灼曰：「地理志無也。功臣表食邑鉅鹿。」師古曰：「晉說是也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_75_60","chapterId":"ch_work_han_thu_75","textTraditional":"久之，巫蠱事多不信。上知太子惶恐無他意，而車千秋復訟太子冤，上遂擢千秋為丞相，而族滅江充家，焚蘇文於橫橋上，〔一〕及泉鳩里加兵刃於太子者，初為北地太守，後族。上憐太子無辜，乃作思子宮，為歸來望思之臺於湖。〔二〕天下聞而悲之。","sentenceOrder":60},
  {"id":"s_work_han_thu_75_61","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　（師古）〔孟康〕曰：「橫音光。」師古曰：「即橫門渭橋也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_75_62","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「言己望而思之，庶太子之魂來歸也。其臺在今湖城縣之西，閿鄉之東，基趾猶存。」","sentenceOrder":62},
  {"id":"s_work_han_thu_75_63","chapterId":"ch_work_han_thu_75","textTraditional":"初，太子有三男一女，女者平輿侯嗣子尚焉。及太子敗，皆同時遇害。衛（侯）〔后〕、史良娣葬長安城南。史皇孫、皇孫妃王夫人及皇女孫葬廣明。〔一〕皇孫二人隨太子者，與太子并葬湖。〔二〕","sentenceOrder":63},
  {"id":"s_work_han_thu_75_64","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　蘇林曰：「苑名也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_75_65","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「今太子冢北有二冢相次，則二皇孫也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_75_66","chapterId":"ch_work_han_thu_75","textTraditional":"太子有遺孫一人，史皇孫子，王夫人男，年十八即尊位，是為孝宣帝。帝初即位，（帝）〔下〕詔曰：「故皇太子在湖，未有號諡，歲時祠，其議諡，置園邑。」有司奏請：「禮『為人後者，為之子也』，故降其父母不得祭，〔一〕尊祖之義也。陛下為孝昭帝後，承祖宗之祀，制禮不踰閑。〔二〕謹行視孝昭帝所為故皇太子起位在湖，〔三〕史良娣冢在博望苑北，親史皇孫位在廣明郭北。〔四〕諡法曰『諡者，行之跡也』，愚以為親諡宜曰悼（皇），母曰悼后，比諸侯王園，置奉邑三百家。故皇太子諡曰戾，置奉邑二百家。史良娣曰戾夫人，置守冢三十家。園置長丞，周衛奉守如法。」以湖閿鄉邪里聚為戾園，〔五〕長安白亭東為戾后園，廣明成鄉為悼園。皆改葬焉。","sentenceOrder":66},
  {"id":"s_work_han_thu_75_67","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「謂本生之父母也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_75_68","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「閑猶限也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_75_69","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　文穎曰：「位，冢位也。」師古曰：「行音下更反。」","sentenceOrder":69},
  {"id":"s_work_han_thu_75_70","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　如淳曰：「親謂父也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_75_71","chapterId":"ch_work_han_thu_75","textTraditional":"〔五〕　（師古）〔孟康〕曰：「閿，古闅字，從門中{目攴}。建安中正作（聞）〔閿〕。」師古曰：「{目攴}，舉目使人也。{目攴}音許密反。閿字本從{目攴}，其後轉訛誤，遂作門中受耳。而郭璞乃音汝授反，蓋失理遠耳。」","sentenceOrder":71},
  {"id":"s_work_han_thu_75_72","chapterId":"ch_work_han_thu_75","textTraditional":"後八歲，有司復言：「禮『父為士，子為天子，祭以天子』。悼園宜稱尊號曰皇考，立廟：因園為寢，以時薦享焉。益奉園民滿千六百家，以為奉明縣。尊戾夫人曰戾后，置園奉邑，及益戾園各滿三百家。」","sentenceOrder":72},
  {"id":"s_work_han_thu_75_73","chapterId":"ch_work_han_thu_75","textTraditional":"齊懷王閎與燕王旦、廣陵王胥同日立，皆賜策，各以國土風俗申戒焉，曰：「惟元狩六年四月乙巳，皇帝使御史大夫湯〔一〕廟立子閎為齊王，〔二〕曰：烏呼！小子閎，受茲青社。〔三〕朕承天序，惟稽古，建爾國家，〔四〕封于東土，世為漢藩輔。烏呼！念哉，共朕之詔。〔五〕惟命不于常，〔六〕人之好德，克明顯光；義之不圖，俾君子怠。〔七〕悉爾心，允執其中，天祿永終；〔八〕厥有愆不臧，乃凶于乃國，而害于爾躬。〔九〕嗚呼！保國乂民，可不敬與！王其戒之！」〔一０〕閎母王夫人有寵，閎尤愛幸，立八年，薨，無子，國除。","sentenceOrder":73},
  {"id":"s_work_han_thu_75_74","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「張湯。」","sentenceOrder":74},
  {"id":"s_work_han_thu_75_75","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「於廟授策也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_75_76","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　張晏曰：「王者以五色土為太社，封四方諸侯，各以其方色土與之，苴以白茅，歸以立社。」","sentenceOrder":76},
  {"id":"s_work_han_thu_75_77","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　師古曰：「言考於古道而立子為王。」","sentenceOrder":77},
  {"id":"s_work_han_thu_75_78","chapterId":"ch_work_han_thu_75","textTraditional":"〔五〕　師古曰：「共讀曰恭。言敬聽我詔。」","sentenceOrder":78},
  {"id":"s_work_han_thu_75_79","chapterId":"ch_work_han_thu_75","textTraditional":"〔六〕　師古曰：「言皇天無親，惟德是輔，善則得之，惡則失之。」","sentenceOrder":79},
  {"id":"s_work_han_thu_75_80","chapterId":"ch_work_han_thu_75","textTraditional":"〔七〕　師古曰：「言人若好德，則能明顯有光輝；若不圖於義，則君子懈怠，無歸附之者。圖，謀也。俾，使也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_75_81","chapterId":"ch_work_han_thu_75","textTraditional":"〔八〕　師古曰：「能盡爾心，信執中和之（得）〔德〕，則能終天祿者也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_75_82","chapterId":"ch_work_han_thu_75","textTraditional":"〔九〕　師古曰：「臧，善也。乃，汝也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_75_83","chapterId":"ch_work_han_thu_75","textTraditional":"〔一０〕師古曰：「保，安也。乂，治也。與讀曰歟。」","sentenceOrder":83},
  {"id":"s_work_han_thu_75_84","chapterId":"ch_work_han_thu_75","textTraditional":"燕剌王旦賜策曰：「嗚呼！小子旦，受茲玄社，建爾國家，封于北土，世為漢藩輔。嗚呼！薰鬻氏虐老獸心，以姦巧邊甿。〔一〕朕命將率，徂征厥罪。〔二〕萬夫長，千夫長，三十有二帥，〔三〕降旗奔師。〔四〕薰鬻徙域，〔五〕北州以妥。〔六〕悉爾心，毋作怨，毋作棐德，〔七〕毋乃廢備。〔八〕非教士不得從徵。〔九〕王其戒之！」","sentenceOrder":84},
  {"id":"s_work_han_thu_75_85","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　服虔曰：「薰鬻，堯時匈奴號也。」孟康曰：「甿音萌。」師古曰：「虐老，謂貴少壯而食甘肥，賤耆老而與粗惡也。獸心，言貪暴而無仁義也。甿，庶人。薰音勳。鬻音育。」","sentenceOrder":85},
  {"id":"s_work_han_thu_75_86","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「徂，往也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_75_87","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　張晏曰：「時所獲三十二帥也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_75_88","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　如淳曰：「昆邪王偃其旗鼓而來降也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_75_89","chapterId":"ch_work_han_thu_75","textTraditional":"〔五〕　張晏曰：「匈奴徙東。」","sentenceOrder":89},
  {"id":"s_work_han_thu_75_90","chapterId":"ch_work_han_thu_75","textTraditional":"〔六〕　孟康曰：「古綏字也。」臣瓚曰：「妥，安也。」師古曰：「瓚說是也。妥音他果反。」","sentenceOrder":90},
  {"id":"s_work_han_thu_75_91","chapterId":"ch_work_han_thu_75","textTraditional":"〔七〕　服虔曰：「棐，薄也。」師古曰：「棐，古匪字也。匪，非也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_75_92","chapterId":"ch_work_han_thu_75","textTraditional":"〔八〕　師古曰：「禦邊之備不可廢。」","sentenceOrder":92},
  {"id":"s_work_han_thu_75_93","chapterId":"ch_work_han_thu_75","textTraditional":"〔九〕　張晏曰：「士不素習不得應召。」","sentenceOrder":93},
  {"id":"s_work_han_thu_75_94","chapterId":"ch_work_han_thu_75","textTraditional":"旦壯大就國，為人辯略，博學經書雜說，好星曆數術倡優射獵之事，招致游士。及衛太子敗，齊懷王又薨，旦自以次第當立，上書求入宿衛。上怒，下其使獄。後坐臧匿亡命，削良鄉、安次、文安三縣。武帝由是惡旦，後遂立少子為太子。","sentenceOrder":94},
  {"id":"s_work_han_thu_75_95","chapterId":"ch_work_han_thu_75","textTraditional":"帝崩，太子立，是為孝昭帝，賜諸侯王璽書。旦得書，不肯哭，曰：「璽書封小。〔一〕京師疑有變。」遣幸臣壽西長、孫縱之、王孺等之長安，〔二〕以問禮儀為名。王孺見執金吾廣（義）〔意〕，〔三〕問帝崩所病，〔四〕立者誰子，年幾歲。廣意言待詔五莋宮，〔五〕宮中讙言帝崩，諸將軍共立太子為帝，年八九歲，葬時不出臨。〔六〕歸以報王。王曰：「上棄群臣，無語言，蓋主又不得見，甚可怪也。」復遣中大夫至京師上書言：「竊見孝武皇帝躬聖道，孝宗廟，慈愛骨肉，和集兆民，德配天地，明並日月，威武洋溢，〔七〕遠方執寶而朝，增郡數十，斥地且倍，〔八〕封泰山，禪梁父，巡狩天下，遠方珍物陳于太廟，德甚休盛，〔九〕請立廟郡國。」奏報聞。時大將霍光秉政，褒賜燕王錢三千萬，益封萬三千戶。旦怒曰：「我當為帝，何賜也！」遂與宗室中山哀王子劉長、齊孝王孫劉澤等結謀，詐言以武帝時受詔，得職吏事，修武備，備非常。〔一０〕","sentenceOrder":95},
  {"id":"s_work_han_thu_75_96","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　張晏曰：「文少則封小。」","sentenceOrder":96},
  {"id":"s_work_han_thu_75_97","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「之，往也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_75_98","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「郭廣（義）〔意〕。」","sentenceOrder":98},
  {"id":"s_work_han_thu_75_99","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　師古曰：「因何病而崩。」","sentenceOrder":99},
  {"id":"s_work_han_thu_75_100","chapterId":"ch_work_han_thu_75","textTraditional":"〔五〕　師古曰：「苲讀與柞同。」","sentenceOrder":100},
  {"id":"s_work_han_thu_75_101","chapterId":"ch_work_han_thu_75","textTraditional":"〔六〕　師古曰：「臨音力禁反。」","sentenceOrder":101},
  {"id":"s_work_han_thu_75_102","chapterId":"ch_work_han_thu_75","textTraditional":"〔七〕　師古曰：「洋溢，言盛多也。洋音羊。」","sentenceOrder":102},
  {"id":"s_work_han_thu_75_103","chapterId":"ch_work_han_thu_75","textTraditional":"〔八〕　師古曰：「斥，開也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_75_104","chapterId":"ch_work_han_thu_75","textTraditional":"〔九〕　師古曰：「休，美也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_75_105","chapterId":"ch_work_han_thu_75","textTraditional":"〔一０〕如淳曰：「諸侯不得治民與職事，是以為詐言受詔，得知職事，發兵為備也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_75_106","chapterId":"ch_work_han_thu_75","textTraditional":"長於是為旦命令群臣曰：「寡人賴先帝休德，〔一〕獲奉北藩，親受明詔，職吏事，領庫兵，飭武備，〔二〕任重職大，夙夜兢兢，子大夫將何以規佐寡人？且燕國雖小，成周之建國也，〔三〕上自召公，下及昭、襄，〔四〕于今千載，豈可謂無賢哉？寡人束帶聽朝三十餘年，曾無聞焉。其者寡人之不及與？〔五〕意亦子大夫之思有所不至乎？其咎安在？方今寡人欲撟邪防非，章聞揚和，〔六〕撫慰百姓，移風易俗，厥路何由？子大夫其各悉心以對，寡人將察焉。」","sentenceOrder":106},
  {"id":"s_work_han_thu_75_107","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「休，美也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_75_108","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「飭讀與敕同。飭，整也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_75_109","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「自周以來即為燕國，言以久遠。」","sentenceOrder":109},
  {"id":"s_work_han_thu_75_110","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　師古曰：「召公，謂召公奭也。昭、襄，六國時燕之二王也。召讀曰邵。」","sentenceOrder":110},
  {"id":"s_work_han_thu_75_111","chapterId":"ch_work_han_thu_75","textTraditional":"〔五〕　師古曰：「與讀曰歟。」","sentenceOrder":111},
  {"id":"s_work_han_thu_75_112","chapterId":"ch_work_han_thu_75","textTraditional":"〔六〕　師古曰：「撟，正也。章，表也。撟與矯同，其字從手也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_75_113","chapterId":"ch_work_han_thu_75","textTraditional":"群臣皆免冠謝。郎中成軫謂旦曰：「大王失職，獨可起而索，不可坐而得也。〔一〕大王壹起，國中雖女子皆奮臂隨大王。」旦曰：「前高后時，偽立子弘為皇帝，諸侯交手事之八年。〔二〕呂太后崩，大臣誅諸呂，迎立文帝，天下乃知非孝惠子也。我親武帝長子，反不得立，上書請立廟，又不聽。立者疑非劉氏。」","sentenceOrder":113},
  {"id":"s_work_han_thu_75_114","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「失職，謂當為漢嗣而不被用也。索，求也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_75_115","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「交手，謂拱手也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_75_116","chapterId":"ch_work_han_thu_75","textTraditional":"即與劉澤謀為姦書，言少帝非武帝子，大臣所共立，天下宜共伐之。使人傳行郡國，以搖動百姓。澤謀歸發兵臨淄，與燕王俱起。旦遂招來郡國姦人，賦斂銅鐵作甲兵，數閱其車騎材官卒，建旌旗鼓車，旄頭先敺，〔一〕郎中侍從者著貂羽，黃金附蟬，〔二〕皆號侍中。旦從相、中尉以下，勒車騎，發民會圍，大獵文安縣，以講士馬，須期日。〔三〕郎中韓義等數諫旦，旦殺義等凡十五人。會缾侯劉成知澤等謀，〔四〕告之青州刺史雋不疑，不疑收捕澤以聞。天子遣大鴻臚丞治，連引燕王。有詔弗治，而劉澤等皆伏誅。益封缾侯。","sentenceOrder":116},
  {"id":"s_work_han_thu_75_117","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「敺與驅同。」","sentenceOrder":117},
  {"id":"s_work_han_thu_75_118","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　晉灼曰：「以翠羽飾冠也。」師古曰：「貂羽，以貂尾為冠之羽也。附蟬，（謂）〔為〕金蟬以附冠前也。凡此旄頭先驅，皆天子之制。而貂羽附蟬，又天子侍中之飾，王僭為之。」","sentenceOrder":118},
  {"id":"s_work_han_thu_75_119","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「講，習也。須，待也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_75_120","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　師古曰：「缾侯，菑川靖王子也。缾音步丁反。」","sentenceOrder":120},
  {"id":"s_work_han_thu_75_121","chapterId":"ch_work_han_thu_75","textTraditional":"久之，旦姊鄂邑蓋長公主、〔一〕左將軍上官桀父子與霍光爭權有隙，皆知旦怨光，即私與燕交通。旦遣孫縱之等前後十餘輩，多齎金寶走馬，〔二〕賂遺蓋主。上官桀及御史大夫桑弘羊等皆與交通，數記疏光過失與旦，令上書告之。桀欲從中下其章。〔三〕旦聞之，喜，上疏曰：「昔秦據南面之位，制一世之命，威服四夷，輕弱骨肉，顯重異族，廢道任刑，無恩宗室。其後尉佗入南夷，陳涉呼楚澤，〔四〕近狎作亂，內外俱發，〔五〕趙氏無炊火焉。〔六〕高皇帝覽蹤跡，觀得失，見秦建本非是，故改其路，規土連城，布王子孫〔七〕，是以支葉扶疏，異姓不得間也。〔八〕今陛下承明繼成，〔九〕委任公卿，群臣連與成朋，非毀宗室，〔一０〕膚受之愬，日騁於廷，惡吏廢法立威，主恩不及下究。〔一一〕臣聞武帝使中郎將蘇武使匈奴，見留二十年不降，還亶為典屬國。〔一二〕今大將軍長史敞無勞，為搜粟都尉。〔一三〕又將軍都郎羽林，〔一四〕道上移蹕〔一五〕，太官先置。〔一六〕臣旦願歸符璽，入宿衛，察姦臣之變。」","sentenceOrder":121},
  {"id":"s_work_han_thu_75_122","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　張晏曰：「食邑鄂，蓋侯王信妻也。」師古曰：「為蓋侯妻是也，非王信。信者，武帝之舅耳，不取鄂邑主為妻，當是信子頃侯充耳。」","sentenceOrder":122},
  {"id":"s_work_han_thu_75_123","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「走馬，馬之善走者。」","sentenceOrder":123},
  {"id":"s_work_han_thu_75_124","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「下音胡稼反。」","sentenceOrder":124},
  {"id":"s_work_han_thu_75_125","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　師古曰：「呼音火故反。」","sentenceOrder":125},
  {"id":"s_work_han_thu_75_126","chapterId":"ch_work_han_thu_75","textTraditional":"〔五〕　師古曰：「狎，習也。近習之人，謂趙高也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_75_127","chapterId":"ch_work_han_thu_75","textTraditional":"〔六〕　韋昭曰：「趙，秦之別氏。」師古曰：「無炊火，無絕祀也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_75_128","chapterId":"ch_work_han_thu_75","textTraditional":"〔七〕　師古曰：「規，畫也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_75_129","chapterId":"ch_work_han_thu_75","textTraditional":"〔八〕　師古曰：「間音工莧反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_75_130","chapterId":"ch_work_han_thu_75","textTraditional":"〔九〕　師古曰：「承聖明之後，繼已成之業。」","sentenceOrder":130},
  {"id":"s_work_han_thu_75_131","chapterId":"ch_work_han_thu_75","textTraditional":"〔一０〕師古曰：「與謂黨與也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_75_132","chapterId":"ch_work_han_thu_75","textTraditional":"〔一一〕師古曰：「究，竟也。言不終竟於下。」","sentenceOrder":132},
  {"id":"s_work_han_thu_75_133","chapterId":"ch_work_han_thu_75","textTraditional":"〔一二〕師古曰：「亶音但。」","sentenceOrder":133},
  {"id":"s_work_han_thu_75_134","chapterId":"ch_work_han_thu_75","textTraditional":"〔一三〕師古曰：「楊敞也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_75_135","chapterId":"ch_work_han_thu_75","textTraditional":"〔一四〕張晏曰：「都試郎、羽林也。」師古曰：「都，大也，謂大會試之。漢光祿挈令『諸當試者，不會都所，免之』。」","sentenceOrder":135},
  {"id":"s_work_han_thu_75_136","chapterId":"ch_work_han_thu_75","textTraditional":"〔一五〕如淳曰：「移猶傳也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_75_137","chapterId":"ch_work_han_thu_75","textTraditional":"〔一六〕師古曰：「昭紀云『詐令人為燕王旦上書』，又云上曰『朕知此書詐也。將軍都郎屬耳，燕王何以得知之？』而此傳乃云旦自上疏，此下又云帝覺有詐，遂親信光，參錯不同，疑此傳為誤。」","sentenceOrder":137},
  {"id":"s_work_han_thu_75_138","chapterId":"ch_work_han_thu_75","textTraditional":"是時昭帝年十四，覺其有詐，遂親信霍光，而疏上官桀等。桀等因謀共殺光，廢帝，迎立燕王為天子。旦置驛書，往來相報，許立桀為王，外連郡國豪桀以千數。旦以語相平，平曰：「大王前與劉澤結謀，事未成而發覺者，以劉澤素夸，好侵陵也。平聞左將軍素輕易，車騎將軍少而驕，臣恐其如劉澤時不能成，又恐既成，反大王也。」旦曰：「前日一男子詣闕，自謂故太子，長安中民趣鄉之，〔一〕正讙不可止，〔二〕大將軍恐，出兵陳之，以自備耳。我帝長子，天下所信，何憂見反？」後謂群臣：「蓋主報言，獨患大將軍與右將軍王莽。〔三〕今右將軍物故，〔四〕丞相病，幸事必成，徵不久。」令群臣皆裝。","sentenceOrder":138},
  {"id":"s_work_han_thu_75_139","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":139},
  {"id":"s_work_han_thu_75_140","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「人眾既多，故讙譁也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_75_141","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　張晏曰：「天水人也，字稚叔。」","sentenceOrder":141},
  {"id":"s_work_han_thu_75_142","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　師古曰：「謂死也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_75_143","chapterId":"ch_work_han_thu_75","textTraditional":"是時天雨，虹下屬宮中〔一〕飲井水，（水泉）〔井水〕竭。廁中豕群出，壞大官灶。〔二〕烏鵲鬥死。鼠舞殿端門中。〔三〕殿上戶自閉，不可開。天火燒城門。大風壞宮城樓，折拔樹木。流星下墯。后姬以下皆恐。王驚病，使人祠葭水、台水。〔四〕王客呂廣等知星，為王言「當有兵圍城，期在九月十月，漢當有大臣戮死者。」語具在五行志。","sentenceOrder":143},
  {"id":"s_work_han_thu_75_144","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「屬猶注也，音之欲反。」","sentenceOrder":144},
  {"id":"s_work_han_thu_75_145","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「廁，養豕圂也。圂音胡困反。」","sentenceOrder":145},
  {"id":"s_work_han_thu_75_146","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「端門，正門也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_75_147","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　晉灼曰：「地理志葭水在廣平南和，台水在雁門。」師古曰：「葭音家。台音怡。」","sentenceOrder":147},
  {"id":"s_work_han_thu_75_148","chapterId":"ch_work_han_thu_75","textTraditional":"王愈憂恐，謂廣等曰：「謀事不成，妖祥數見，兵氣且至，柰何？」會蓋主舍人父燕倉知其謀，告之，由是發覺。丞相賜璽書，部中二千石逐捕孫縱之及左將軍桀等，皆伏誅。旦聞之，召相平曰：「事敗，遂發兵乎？」平曰：「左將軍已死，百姓皆知之，不可發也。」王憂懣，〔一〕置酒萬載宮，會賓客群臣妃妾坐飲。王自歌曰：「歸空城兮，狗不吠，雞不鳴，橫術何廣廣兮，固知國中之無人！」〔二〕華容夫人起舞曰：「髮紛紛兮寘渠，〔三〕骨籍籍兮亡居。〔四〕母求死子兮，妻求死夫。裴回兩渠間兮，君子獨安居！」〔五〕坐者皆泣。","sentenceOrder":148},
  {"id":"s_work_han_thu_75_149","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「懣音滿，又音悶，解在司馬遷傳。」","sentenceOrder":149},
  {"id":"s_work_han_thu_75_150","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　蘇林曰：「廣音曠。」臣瓚曰：「術，道路也。」師古曰：「廣讀如本字。此歌意，言身死之後，國當空也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_75_151","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　孟康曰：「寘音羃。髮歷羃挂岸也。」臣瓚曰：「寘塞溝渠。」師古曰：「瓚說是也。寘音徒（一）〔千〕反。」","sentenceOrder":151},
  {"id":"s_work_han_thu_75_152","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　師古曰：「籍籍，從橫貌也。居，處也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_75_153","chapterId":"ch_work_han_thu_75","textTraditional":"〔五〕　師古曰：「置酒之宮，池沼所在，其間有渠，故即其所見以為歌辭也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_75_154","chapterId":"ch_work_han_thu_75","textTraditional":"有赦令到，王讀之，曰：「嗟乎！獨赦吏民，不赦我。」因迎后姬諸夫人之明光殿，王曰：「老虜曹為事當族！」〔一〕欲自殺。左右曰：「黨得削國，〔二〕幸不死。」后（妃）〔姬〕夫人共啼泣止王。會天子使使者賜燕王璽書曰：「昔高皇帝王天下，建立子弟以藩屏社稷。先日諸呂陰謀大逆，劉氏不絕若髮，賴絳侯等誅討賊亂，尊立孝文，以安宗廟，非以中外有人，表裏相應故邪？樊、酈、曹、灌，攜劍推鋒，〔三〕從高〔皇〕帝墾菑除害，耘鉏海內，〔四〕〔當此之時，頭如蓬葆〕，〔五〕勤苦至矣，然其賞不過（諸）〔封〕侯。今宗室子孫曾無暴衣露冠之勞，裂地而王之，分財而賜之，父死子繼，兄終弟及。今王骨肉至親，敵吾一體，〔六〕乃與他姓異族謀害社稷，親其所疏，疏其所親，有逆悖之心，無忠愛之義。如使古人有知，當何面目復（舉）〔奉〕齊酎見高祖之廟乎！」〔七〕","sentenceOrder":154},
  {"id":"s_work_han_thu_75_155","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「曹，輩也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_75_156","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「黨音他朗反。」","sentenceOrder":156},
  {"id":"s_work_han_thu_75_157","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「樊噲、酈商、曹參、灌嬰等。」","sentenceOrder":157},
  {"id":"s_work_han_thu_75_158","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　師古曰：「菑，古災字。」","sentenceOrder":158},
  {"id":"s_work_han_thu_75_159","chapterId":"ch_work_han_thu_75","textTraditional":"〔五〕　〔服虔曰〕：〔「頭久不理，如蓬草羽葆也。」師古曰：「草叢生曰葆，音保。」〕","sentenceOrder":159},
  {"id":"s_work_han_thu_75_160","chapterId":"ch_work_han_thu_75","textTraditional":"〔六〕　師古曰：「言若四肢之一也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_75_161","chapterId":"ch_work_han_thu_75","textTraditional":"〔七〕　師古曰：「古人謂先人。」","sentenceOrder":161},
  {"id":"s_work_han_thu_75_162","chapterId":"ch_work_han_thu_75","textTraditional":"旦得書，以符璽屬醫工長，〔一〕謝相二千石：「奉事不謹，死矣。」即以綬自絞。后夫人隨旦自殺者二十餘人。天子加恩，赦王太子建為庶人，賜旦諡曰剌王。旦立三十八年而誅，國除。","sentenceOrder":162},
  {"id":"s_work_han_thu_75_163","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「屬，委也。醫工長，王官之〔主〕醫者也。屬音之欲反。」","sentenceOrder":163},
  {"id":"s_work_han_thu_75_164","chapterId":"ch_work_han_thu_75","textTraditional":"後六年，宣帝即位，封旦兩子，慶為新昌侯，賢為（定安）〔安定〕侯，又立故太子建，是為廣陽頃王，二十九年薨。子穆王舜嗣，二十一年薨。子思王璜嗣，二十年薨。子嘉嗣。王莽時，皆廢漢藩王為家人，嘉獨以獻符命封扶美侯，賜姓王氏。","sentenceOrder":164},
  {"id":"s_work_han_thu_75_165","chapterId":"ch_work_han_thu_75","textTraditional":"廣陵厲王胥賜策曰：「嗚呼！小子胥，受茲赤社，建爾國家，封于南土，世世為漢藩輔。古人有言曰：『大江之南，五湖之間，其人輕心。揚州保彊，〔一〕三代要服，不及以正。』〔二〕嗚呼！悉爾心，祗祗兢兢，乃惠乃順，〔三〕毋桐好逸，毋邇宵人，〔四〕惟法惟則！〔五〕書云『臣不作福，不作威』，〔六〕靡有後羞。王其戒之！」〔七〕","sentenceOrder":165},
  {"id":"s_work_han_thu_75_166","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　李奇曰：「保，恃也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_75_167","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「要服，次荒服之內者也。正，政也。要音一遙反。」","sentenceOrder":167},
  {"id":"s_work_han_thu_75_168","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「祗祗，敬也。兢兢，慎也。言當慈惠于下，忠順于上也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_75_169","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　應劭曰：「無好逸游之事，邇近小人也。」張晏曰：「桐音同。」師古曰：「桐音通。桐，輕脫之貌也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_75_170","chapterId":"ch_work_han_thu_75","textTraditional":"〔五〕　師古曰：「言當依法則。」","sentenceOrder":170},
  {"id":"s_work_han_thu_75_171","chapterId":"ch_work_han_thu_75","textTraditional":"〔六〕　師古曰：「周書洪範云『臣無有作威作福也』。」","sentenceOrder":171},
  {"id":"s_work_han_thu_75_172","chapterId":"ch_work_han_thu_75","textTraditional":"〔七〕　師古曰：「言宜戒慎，勿令後有羞辱之事也。」","sentenceOrder":172},
  {"id":"s_work_han_thu_75_173","chapterId":"ch_work_han_thu_75","textTraditional":"胥壯大，好倡樂逸游，力扛鼎，〔一〕空手搏熊彘猛獸。動作無法度，故終不得為漢嗣。","sentenceOrder":173},
  {"id":"s_work_han_thu_75_174","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「扛，舉也，音江。」","sentenceOrder":174},
  {"id":"s_work_han_thu_75_175","chapterId":"ch_work_han_thu_75","textTraditional":"昭帝初立，益封胥萬三千戶，元鳳中入朝，復益萬戶，賜錢二千萬，黃金二千斤，安車駟馬寶劍。及宣帝即位，封胥四子聖、曾、寶、昌皆為列侯，又立胥小子弘為高密王。所以褒賞甚厚。","sentenceOrder":175},
  {"id":"s_work_han_thu_75_176","chapterId":"ch_work_han_thu_75","textTraditional":"始，昭帝時，胥見上年少無子，有覬欲心。〔一〕而楚地巫鬼，〔二〕胥迎女巫李女須，使下神祝詛。〔三〕女須泣曰：「孝武帝下我。」左右皆（服）〔伏〕。〔四〕言「吾必令胥為天子。」胥多賜女須錢，使禱巫山。〔五〕會昭帝崩，胥曰：「女須良巫也！」殺牛塞禱。〔六〕及昌邑王徵，復使巫祝詛之。後王廢，胥寖信女須等，〔七〕數賜予錢物。宣帝即位，胥曰：「太子孫何以反得立？」復令女須祝詛如前。又胥女為楚王延壽后弟婦，數相餽遺，通私書。〔八〕後延壽坐謀反誅，辭連及胥。有詔勿治，賜胥黃金前後五千斤，它器物甚眾。胥又聞漢立太子，謂姬南等曰：「我終不得立矣。」乃止不詛。後胥子南利侯寶坐殺人奪爵，還歸廣陵，與胥姬左修姦。事發覺，繫獄，棄巿。相勝之奏奪王射陂草田以賦貧民，〔九〕奏可。胥復使巫祝詛如前。","sentenceOrder":176},
  {"id":"s_work_han_thu_75_177","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「覬音冀。」","sentenceOrder":177},
  {"id":"s_work_han_thu_75_178","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「言其土俗尊尚巫鬼之事。」","sentenceOrder":178},
  {"id":"s_work_han_thu_75_179","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「女須者，巫之名也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_75_180","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　師古曰：「見女須云武帝神下，故伏而聽之。」","sentenceOrder":180},
  {"id":"s_work_han_thu_75_181","chapterId":"ch_work_han_thu_75","textTraditional":"〔五〕　師古曰：「即楚地之巫山也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_75_182","chapterId":"ch_work_han_thu_75","textTraditional":"〔六〕　師古曰：「以為因禱祝詛而崩也。塞音先代反。」","sentenceOrder":182},
  {"id":"s_work_han_thu_75_183","chapterId":"ch_work_han_thu_75","textTraditional":"〔七〕　師古曰：「寖，古浸字也。寖，漸也，益也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_75_184","chapterId":"ch_work_han_thu_75","textTraditional":"〔八〕　師古曰：「餽亦饋字。」","sentenceOrder":184},
  {"id":"s_work_han_thu_75_185","chapterId":"ch_work_han_thu_75","textTraditional":"〔九〕　張晏曰：「射水之陂，在射陽縣。」","sentenceOrder":185},
  {"id":"s_work_han_thu_75_186","chapterId":"ch_work_han_thu_75","textTraditional":"胥宮園中棗樹生十餘莖，莖正赤，葉白如素。池水變赤，魚死。有鼠晝立舞王后廷中。胥謂姬南等曰：「棗水魚鼠之怪甚可惡也。」居數月，祝詛事發覺，有司按驗，胥惶恐，藥殺巫及宮人二十餘人以絕口。公卿請誅胥，天子遣廷尉、大鴻臚即訊。〔一〕胥謝曰：「罪死有餘，誠皆有之。〔二〕事久遠，請歸思念具對。」胥既見使者還，置酒顯陽殿，召太子霸及子女董訾、胡生等夜飲，〔三〕使所幸八子郭昭君、家人子趙左君等鼓瑟歌舞。〔四〕王自歌曰：「欲久生兮無終，長不樂兮安窮！〔五〕奉天期兮不得須臾，〔六〕千里馬兮駐待路。〔七〕黃泉下兮幽深，人生要死，何為苦心！〔八〕何用為樂心所喜，出入無悰為樂亟。〔九〕蒿里召兮郭門閱，〔一０〕死不得取代庸，身自逝。」〔一一〕左右悉更涕泣奏酒，〔一二〕至雞鳴時罷。胥謂太子霸曰：「上遇我厚，今負之甚。我死，骸骨當暴。幸而得葬，薄之，無厚也。」即以綬自絞死。及八子郭昭君等二人皆自殺。天子加恩，赦王諸子皆為庶人，賜諡曰厲王。立六十四年而誅，國除。","sentenceOrder":186},
  {"id":"s_work_han_thu_75_187","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「就問也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_75_188","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「誠，實也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_75_189","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「董訾、胡生，皆女名。」","sentenceOrder":189},
  {"id":"s_work_han_thu_75_190","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　師古曰：「八子，姬妾之秩號也。家人子，無官秩者也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_75_191","chapterId":"ch_work_han_thu_75","textTraditional":"〔五〕　師古曰：「人所以欲久生者，貴其安豫無有終極，而我在生，長不歡樂，焉用窮盡年壽也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_75_192","chapterId":"ch_work_han_thu_75","textTraditional":"〔六〕　張晏曰：「奉天子期，當死，不得復延年。」","sentenceOrder":192},
  {"id":"s_work_han_thu_75_193","chapterId":"ch_work_han_thu_75","textTraditional":"〔七〕　張晏曰：「二卿亭驛待以答詔命。」","sentenceOrder":193},
  {"id":"s_work_han_thu_75_194","chapterId":"ch_work_han_thu_75","textTraditional":"〔八〕　師古曰：「言人生必當有死，無假勞心懷悲戚。」","sentenceOrder":194},
  {"id":"s_work_han_thu_75_195","chapterId":"ch_work_han_thu_75","textTraditional":"〔九〕　韋昭曰：「悰亦樂也，音裁宗反。亟，數，亦疾也，謂不久也。言人生以何為樂，但以心志所喜好耳。今我出入皆無歡怡，不得久長也。喜音許吏反。亟音邱吏反。」","sentenceOrder":195},
  {"id":"s_work_han_thu_75_196","chapterId":"ch_work_han_thu_75","textTraditional":"〔一０〕師古曰：「蒿里，死人里。」","sentenceOrder":196},
  {"id":"s_work_han_thu_75_197","chapterId":"ch_work_han_thu_75","textTraditional":"〔一一〕師古曰：「言死當自去，不如他傜役得顧庸自代也。逝，合韻音上列反。」","sentenceOrder":197},
  {"id":"s_work_han_thu_75_198","chapterId":"ch_work_han_thu_75","textTraditional":"〔一二〕師古曰：「更，互也。奏，進也。更音工衡反。」","sentenceOrder":198},
  {"id":"s_work_han_thu_75_199","chapterId":"ch_work_han_thu_75","textTraditional":"後七年，元帝復立胥太子霸，是為孝王，十三年薨。子共王意嗣，〔一〕三年薨。子哀王護嗣，十六年薨，無子，絕。後六年，成帝復立孝王子守，是為靖王，立二十年薨。子宏嗣，王莽時絕。","sentenceOrder":199},
  {"id":"s_work_han_thu_75_200","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「共讀曰恭。」","sentenceOrder":200},
  {"id":"s_work_han_thu_75_201","chapterId":"ch_work_han_thu_75","textTraditional":"初，高密哀王弘本始元年以廣陵王胥少子立，九年薨。子頃王章嗣，三十三年薨。子懷王寬嗣，十一年薨。子慎嗣，王莽時絕。","sentenceOrder":201},
  {"id":"s_work_han_thu_75_202","chapterId":"ch_work_han_thu_75","textTraditional":"昌邑哀王髆天漢四年立，十一年薨，子賀嗣。立十三年，昭帝崩，無嗣，大將軍霍光徵王賀典喪。〔一〕璽書曰：「制詔昌邑王〔二〕：使行大鴻臚事少府樂成、〔三〕宗正德、光祿大夫吉、〔四〕中郎將利漢〔五〕徵王，乘七乘傳詣長安邸。」夜漏未盡一刻，以火發書。其日中，賀發，晡時至定陶，行百三十五里，侍從者馬死相望於道。郎中令龔遂諫王，令還郎謁者五十餘人。賀到濟陽，求長鳴雞，〔六〕道買積竹杖。〔七〕過弘農，使大奴善以衣車載女子。〔八〕至湖，〔九〕使者以讓相安樂。〔一０〕安樂告遂，遂入問賀，賀曰：「無有。」遂曰：「即無有，何愛一善以毀行義！請收屬吏，〔一一〕以湔洒大王。」〔一二〕即捽善，屬衛士長行法。〔一三〕","sentenceOrder":202},
  {"id":"s_work_han_thu_75_203","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「（今）〔令〕為喪主。」","sentenceOrder":203},
  {"id":"s_work_han_thu_75_204","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「太后璽書。」","sentenceOrder":204},
  {"id":"s_work_han_thu_75_205","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「史樂成。」","sentenceOrder":205},
  {"id":"s_work_han_thu_75_206","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　師古曰：「丙吉也。」","sentenceOrder":206},
  {"id":"s_work_han_thu_75_207","chapterId":"ch_work_han_thu_75","textTraditional":"〔五〕　師古曰：「不知姓。」","sentenceOrder":207},
  {"id":"s_work_han_thu_75_208","chapterId":"ch_work_han_thu_75","textTraditional":"〔六〕　師古曰：「鳴聲長者也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_75_209","chapterId":"ch_work_han_thu_75","textTraditional":"〔七〕　文穎曰：「合竹作杖也。」","sentenceOrder":209},
  {"id":"s_work_han_thu_75_210","chapterId":"ch_work_han_thu_75","textTraditional":"〔八〕　師古曰：「凡言大奴者，謂奴之尤長大者也。」","sentenceOrder":210},
  {"id":"s_work_han_thu_75_211","chapterId":"ch_work_han_thu_75","textTraditional":"〔九〕　師古曰：「即湖縣。」","sentenceOrder":211},
  {"id":"s_work_han_thu_75_212","chapterId":"ch_work_han_thu_75","textTraditional":"〔一０〕張晏曰：「使者，長安使人也。」師古曰：「讓，責也。」","sentenceOrder":212},
  {"id":"s_work_han_thu_75_213","chapterId":"ch_work_han_thu_75","textTraditional":"〔一一〕師古曰：「以善付吏也。屬音之欲反。其下亦同。」","sentenceOrder":213},
  {"id":"s_work_han_thu_75_214","chapterId":"ch_work_han_thu_75","textTraditional":"〔一二〕師古曰：「湔，澣也。洒，濯也。湔音子顛反。洒音先禮反。」","sentenceOrder":214},
  {"id":"s_work_han_thu_75_215","chapterId":"ch_work_han_thu_75","textTraditional":"〔一三〕師古曰：「捽，持頭也。衛士長，主衛之官。捽音材兀反。」","sentenceOrder":215},
  {"id":"s_work_han_thu_75_216","chapterId":"ch_work_han_thu_75","textTraditional":"賀到霸上，大鴻臚郊迎，騶奉乘輿車。王使僕壽成御，郎中令遂參乘。旦至廣明東都門，遂曰：「禮，奔喪望見國都哭。此長安東郭門也。」賀曰：「我嗌痛，不能哭。」〔一〕至城門，遂復言，賀曰：「城門與郭門等耳。」且至未央宮東闕，遂曰：「昌邑帳在是闕外馳道北，〔二〕未至帳所，有南北行道，馬足未至數步，大王宜下車，鄉闕西面伏，哭盡哀止。」〔三〕王曰：「諾。」到，哭如儀。","sentenceOrder":216},
  {"id":"s_work_han_thu_75_217","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「嗌，喉咽也，音益。」","sentenceOrder":217},
  {"id":"s_work_han_thu_75_218","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　文穎曰：「弔哭帳也。」師古曰：「是謂此。」","sentenceOrder":218},
  {"id":"s_work_han_thu_75_219","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":219},
  {"id":"s_work_han_thu_75_220","chapterId":"ch_work_han_thu_75","textTraditional":"王受皇帝璽綬，襲尊號。即位二十七日，行淫亂。大將軍光與群臣議，白孝昭皇后，廢賀歸故國，賜湯沐邑二千戶，故王家財物皆與賀。及哀王女四人各賜湯沐邑千戶。語在霍光傳。國除，為山陽郡。","sentenceOrder":220},
  {"id":"s_work_han_thu_75_221","chapterId":"ch_work_han_thu_75","textTraditional":"初賀在國時，數有怪。嘗見白犬，高三尺，無頭，其頸以下似人，而冠方山冠。後見熊，左右皆莫見。又大鳥飛集宮中。王知，惡之，輒以問郎中令遂。遂為言其故，語在五行志。王卬天歎曰：「不祥何為數來！」〔一〕遂叩頭曰：「臣不敢隱忠，數言危亡之戒，大王不說。〔二〕夫國之存亡，豈在臣言哉？願王內自揆度。〔三〕大王誦詩三百五篇，人事浹，王道備，〔四〕王之所行中詩一篇何等也？〔五〕大王位為諸侯王，行汙於庶人，〔六〕以存難，以亡易，宜深察之。」後又血汙王坐席，王問遂，遂叫然號曰：「宮空不久，祅祥數至。血者，陰憂象也。宜畏慎自省。」賀終不改節。居無何，徵。既即位，後王夢青蠅之矢積西階東，可五六石，以屋版瓦覆，〔七〕發視之，青蠅矢也。以問遂，遂曰：「陛下之詩不云乎？〔八〕『營營青蠅，至于藩；愷悌君子，毋信讒言。』〔九〕陛下左側讒人眾多，如是青蠅惡矣。〔一０〕宜進先帝大臣子孫親近以為左右。如不忍昌邑故人，〔一一〕信用讒諛，必有凶咎。願詭禍為福，皆放逐之。〔一二〕臣當先逐矣。」賀不用其言，卒至於廢。","sentenceOrder":221},
  {"id":"s_work_han_thu_75_222","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰；「卬讀曰仰。」","sentenceOrder":222},
  {"id":"s_work_han_thu_75_223","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":223},
  {"id":"s_work_han_thu_75_224","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「度音徒各反。」","sentenceOrder":224},
  {"id":"s_work_han_thu_75_225","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　師古曰：「浹，徹也，音子牒反。」","sentenceOrder":225},
  {"id":"s_work_han_thu_75_226","chapterId":"ch_work_han_thu_75","textTraditional":"〔五〕　師古曰：「言王所行，皆不合法度。王自謂當於何詩之文也。中音竹仲反。」","sentenceOrder":226},
  {"id":"s_work_han_thu_75_227","chapterId":"ch_work_han_thu_75","textTraditional":"〔六〕　師古曰：「汙，濁穢。」","sentenceOrder":227},
  {"id":"s_work_han_thu_75_228","chapterId":"ch_work_han_thu_75","textTraditional":"〔七〕　師古曰：「版瓦，大瓦也。」","sentenceOrder":228},
  {"id":"s_work_han_thu_75_229","chapterId":"ch_work_han_thu_75","textTraditional":"〔八〕　蘇林曰：「猶言陛下所讀之詩也。」","sentenceOrder":229},
  {"id":"s_work_han_thu_75_230","chapterId":"ch_work_han_thu_75","textTraditional":"〔九〕　師古曰：「已解於上。」","sentenceOrder":230},
  {"id":"s_work_han_thu_75_231","chapterId":"ch_work_han_thu_75","textTraditional":"〔一０〕師古曰：「惡即矢也。越王句踐為吳王嘗惡，亦其義也。」","sentenceOrder":231},
  {"id":"s_work_han_thu_75_232","chapterId":"ch_work_han_thu_75","textTraditional":"〔一一〕師古曰：「如，若也。不忍謂不能疏遠也。」","sentenceOrder":232},
  {"id":"s_work_han_thu_75_233","chapterId":"ch_work_han_thu_75","textTraditional":"〔一二〕師古曰：「詭猶反。」","sentenceOrder":233},
  {"id":"s_work_han_thu_75_234","chapterId":"ch_work_han_thu_75","textTraditional":"大將軍光更尊立武帝曾孫，是為孝宣帝。即位，心內忌賀，元康二年遣使者賜山陽太守張敞璽書曰：「制詔山陽太守：其謹備盜賊，察往來過客。毋下所賜書！」〔一〕敞於是條奏賀居處，著其廢亡之效，〔二〕曰：「臣敞地節三年五月視事，故昌邑王居故宮，奴婢在中者百八十三人，閉大門，開小門，廉吏一人為領錢物市買，朝內食物，〔三〕它不得出入。〔四〕督盜一人別主徼循，察往來者，以王家錢取卒，迾宮清中備盜賊。〔五〕臣敞數遣丞吏行察。〔六〕四年九月中，臣敞入視居處狀，故王年二十六七，為人青黑色，小目，鼻末銳卑，少須眉，身體長大，疾痿，行步不便。〔七〕衣短衣大絝，冠惠文冠，〔八〕佩玉環，簪筆持牘趨謁。〔九〕臣敞與坐語中庭，閱妻子奴婢。臣敞欲動觀其意，即以惡鳥感之，曰：『昌邑多梟。』故王應曰：『然前賀西至長安，殊無梟。復來，東至濟陽，乃復聞梟聲。』臣敞閱至子女持轡，〔一０〕故王跪曰：『持轡母，嚴長孫女也。』臣敞故知執金吾嚴延年字長孫，女羅紨，〔一一〕前為故王妻。察故王衣服言語跪起，清狂不惠。〔一二〕妻十六人，子二十二人，其十一人男，十一人女。昧死奏名籍及奴婢財物簿。臣敞前書言：『昌邑哀王歌舞者張修等十人，無子，又非姬，但良人，無官名，王薨當罷歸。太傅豹等擅留，以為哀王園中人，所不當得為，〔一三〕請罷歸。』故王聞之曰：『中人守園，疾者當勿治，相殺傷者當勿法，欲令亟死，太守柰何而欲罷之？』〔一四〕其天資喜由亂亡，終不見仁義，如此。〔一五〕後丞相御史以臣敞書聞，奏可。皆以遣。」上由此知賀不足忌。","sentenceOrder":234},
  {"id":"s_work_han_thu_75_235","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「密令警察，不欲宣露也。」","sentenceOrder":235},
  {"id":"s_work_han_thu_75_236","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「著，明也。」","sentenceOrder":236},
  {"id":"s_work_han_thu_75_237","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「每旦一內之。」","sentenceOrder":237},
  {"id":"s_work_han_thu_75_238","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　師古曰：「食物之外皆不得妄有出入。」","sentenceOrder":238},
  {"id":"s_work_han_thu_75_239","chapterId":"ch_work_han_thu_75","textTraditional":"〔五〕　李奇曰：「迾，遮也。」鄧展曰：「令其宮中清靖，不得妄有異人也。」師古曰：「以王家錢顧人為卒也。」","sentenceOrder":239},
  {"id":"s_work_han_thu_75_240","chapterId":"ch_work_han_thu_75","textTraditional":"〔六〕　師古曰：「行音下更反。」","sentenceOrder":240},
  {"id":"s_work_han_thu_75_241","chapterId":"ch_work_han_thu_75","textTraditional":"〔七〕　師古曰：「痿，風痺疾也，音人佳反。」","sentenceOrder":241},
  {"id":"s_work_han_thu_75_242","chapterId":"ch_work_han_thu_75","textTraditional":"〔八〕　蘇林曰：「治獄法冠也。」孟康曰：「今侍中所著也。」服虔曰：「武冠也，或曰趙惠文王所服，故曰惠文。」晉灼曰：「柱後惠文，法冠也。但言惠文，侍中冠。孟說是也。」","sentenceOrder":242},
  {"id":"s_work_han_thu_75_243","chapterId":"ch_work_han_thu_75","textTraditional":"〔九〕　師古曰：「簪筆，插筆於首也。牘，木簡也。」","sentenceOrder":243},
  {"id":"s_work_han_thu_75_244","chapterId":"ch_work_han_thu_75","textTraditional":"〔一０〕師古曰：「賀之子女名持轡。」","sentenceOrder":244},
  {"id":"s_work_han_thu_75_245","chapterId":"ch_work_han_thu_75","textTraditional":"〔一一〕師古曰：「羅紨，其名也。紨音敷。」","sentenceOrder":245},
  {"id":"s_work_han_thu_75_246","chapterId":"ch_work_han_thu_75","textTraditional":"〔一二〕蘇林曰：「凡狂者，陰陽脈盡濁。今此人不狂似狂者，故言清狂也。或曰，色理清徐而心不慧曰清狂。清狂，如今白癡也。」","sentenceOrder":246},
  {"id":"s_work_han_thu_75_247","chapterId":"ch_work_han_thu_75","textTraditional":"〔一三〕師古曰：「於法不當然。」","sentenceOrder":247},
  {"id":"s_work_han_thu_75_248","chapterId":"ch_work_han_thu_75","textTraditional":"〔一四〕師古曰：「亟，急也，音居力反。」","sentenceOrder":248},
  {"id":"s_work_han_thu_75_249","chapterId":"ch_work_han_thu_75","textTraditional":"〔一五〕師古曰：「喜，好也。由，從也。喜音許吏反。」","sentenceOrder":249},
  {"id":"s_work_han_thu_75_250","chapterId":"ch_work_han_thu_75","textTraditional":"其明年春，乃下詔曰：「蓋聞象有罪，舜封之，骨肉之親，析而不殊。〔一〕其封故昌邑王賀為海昏侯，食邑四千戶。」〔二〕侍中衛尉金安上上書言：「賀天之所棄，陛下至仁，復封為列侯。賀嚚頑放廢之人，不宜得奉宗廟朝聘之禮。」奏可。賀就國豫章。","sentenceOrder":250},
  {"id":"s_work_han_thu_75_251","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「析，分也。殊，絕也。」","sentenceOrder":251},
  {"id":"s_work_han_thu_75_252","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「海昏，豫章之縣。」","sentenceOrder":252},
  {"id":"s_work_han_thu_75_253","chapterId":"ch_work_han_thu_75","textTraditional":"數年，揚州刺史柯奏賀〔一〕與故太守卒史孫萬世交通，萬世問賀：「前見廢時，何不堅守毋出宮，斬大將軍，而聽人奪璽綬乎？」賀曰：「然。失之。」萬世又以賀且王豫章，不久為列侯。賀曰：「且然，〔二〕非所宜言。」有司案驗，請逮捕。制曰：「削戶三千。」後薨。","sentenceOrder":253},
  {"id":"s_work_han_thu_75_254","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「柯者，刺史之名也。」","sentenceOrder":254},
  {"id":"s_work_han_thu_75_255","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「謂亦將如此。」","sentenceOrder":255},
  {"id":"s_work_han_thu_75_256","chapterId":"ch_work_han_thu_75","textTraditional":"豫章太守廖奏言：「舜封象於有鼻，〔一〕死不為置後，以為暴亂之人不宜為太祖。〔二〕海昏侯賀死，上當為後者子充國；〔三〕充國死，復上弟奉親；奉親復死，是天絕之也。陛下聖仁，於賀甚厚，雖舜於象無以加也。宜以禮絕賀，以奉天意。願下有司議。」議皆以為不宜為立嗣，國除。","sentenceOrder":256},
  {"id":"s_work_han_thu_75_257","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰；「廖，太守名也。有鼻在零陵，今鼻亭是也。廖音聊。」","sentenceOrder":257},
  {"id":"s_work_han_thu_75_258","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「謂一國之始祖。」","sentenceOrder":258},
  {"id":"s_work_han_thu_75_259","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「上謂由上其名於有司。」","sentenceOrder":259},
  {"id":"s_work_han_thu_75_260","chapterId":"ch_work_han_thu_75","textTraditional":"元帝即位，復封賀子代宗為海昏侯，傳子至孫，今見為〔侯〕。","sentenceOrder":260},
  {"id":"s_work_han_thu_75_261","chapterId":"ch_work_han_thu_75","textTraditional":"贊曰：巫蠱之禍，豈不哀哉！此不唯一江充之辜，亦有天時，非人力所致焉。建元六年，蚩尤之旗見，其長竟天。後遂命將出征，略取河南，建置朔方。其春，戾太子生。自是之後，師行三十年，兵所誅屠夷滅死者不可勝數。及巫蠱事起，京師流血，僵尸數萬，〔一〕太子子父皆敗。故太子生長於兵，與之終始，何獨一嬖臣哉！秦始皇即位三十九年，內平六國，外攘四夷，死人如亂麻，暴骨長城之下，頭盧相屬於道，〔二〕不一日而無兵。由是山東之難興，四方潰而逆秦。秦將吏外畔，賊臣內發，亂作蕭牆，禍成二世。〔三〕故曰「兵猶火也，弗戢必自焚」，〔四〕信矣。是以倉頡作書，「止」「戈」為「武」。〔五〕聖人以武禁暴整亂，止息干戈，非以為殘而興縱之也。易曰：「天之所助者順也，人之所助者信也；君子履信思順，自天祐之，吉無不利也。」〔六〕故車千秋指明蠱情，章太子之冤。千秋材知未必能過人也，以其銷惡運，遏亂原，〔七〕因衰激極，道迎善氣，〔八〕傳得天人之祐助云。〔九〕","sentenceOrder":261},
  {"id":"s_work_han_thu_75_262","chapterId":"ch_work_han_thu_75","textTraditional":"〔一〕　師古曰：「僵，偃也，音居羊反。」","sentenceOrder":262},
  {"id":"s_work_han_thu_75_263","chapterId":"ch_work_han_thu_75","textTraditional":"〔二〕　師古曰：「盧，頟骨也。屬，連也，音之欲反。」","sentenceOrder":263},
  {"id":"s_work_han_thu_75_264","chapterId":"ch_work_han_thu_75","textTraditional":"〔三〕　師古曰：「蕭牆謂屏牆也，解在五行志。」","sentenceOrder":264},
  {"id":"s_work_han_thu_75_265","chapterId":"ch_work_han_thu_75","textTraditional":"〔四〕　師古曰：「左傳隱四年衛有州吁之亂，公問於眾仲曰：『州吁其成乎？』對曰：『兵猶火也，不戢將自焚也。』言兵不可妄動，久而不戢，則自焚燒。戢，斂也。」","sentenceOrder":265},
  {"id":"s_work_han_thu_75_266","chapterId":"ch_work_han_thu_75","textTraditional":"〔五〕　師古曰：「武字從止，從戈，所謂會意。」","sentenceOrder":266},
  {"id":"s_work_han_thu_75_267","chapterId":"ch_work_han_thu_75","textTraditional":"〔六〕　師古曰：「易上繫辭也。」","sentenceOrder":267},
  {"id":"s_work_han_thu_75_268","chapterId":"ch_work_han_thu_75","textTraditional":"〔七〕　師古曰：「遏，止也，音一曷反。」","sentenceOrder":268},
  {"id":"s_work_han_thu_75_269","chapterId":"ch_work_han_thu_75","textTraditional":"〔八〕　師古曰：「激去至極之災，引致福善之氣也。道讀曰導。」","sentenceOrder":269},
  {"id":"s_work_han_thu_75_270","chapterId":"ch_work_han_thu_75","textTraditional":"〔九〕　師古曰：「傳，引也。」","sentenceOrder":270},
  {"id":"s_work_han_thu_75_271","chapterId":"ch_work_han_thu_75","textTraditional":"校勘記","sentenceOrder":271},
  {"id":"s_work_han_thu_75_272","chapterId":"ch_work_han_thu_75","textTraditional":"二七四三頁一三行　按道侯說疑使者有（詔）〔詐〕，不肯受詔，　錢大昭說「詔」當作「詐」。按景祐、殿本都作「詐」。","sentenceOrder":272},
  {"id":"s_work_han_thu_75_273","chapterId":"ch_work_han_thu_75","textTraditional":"二七四四頁一一行　父子不和則室家（散）〔喪〕亡，　景祐、殿本都作「喪」。","sentenceOrder":273},
  {"id":"s_work_han_thu_75_274","chapterId":"ch_work_han_thu_75","textTraditional":"二七四四頁一三行　（令）〔今〕皇太子為漢適嗣，　錢大昭說「令」當作「今」。按景祐、殿、局本都作「今」。","sentenceOrder":274},
  {"id":"s_work_han_thu_75_275","chapterId":"ch_work_han_thu_75","textTraditional":"二七四七頁一二行　（師古）〔孟康〕曰：　景祐、殿本都作「孟康」，此誤。","sentenceOrder":275},
  {"id":"s_work_han_thu_75_276","chapterId":"ch_work_han_thu_75","textTraditional":"二七四七頁一四行　衛（侯）〔后〕、史良娣葬長安城南。　錢大昭說「侯」當作「后」。按景祐、殿、局本都作「后」。","sentenceOrder":276},
  {"id":"s_work_han_thu_75_277","chapterId":"ch_work_han_thu_75","textTraditional":"二七四八頁　三行　帝初即位，（帝）〔下〕詔曰：　景祐、殿本都「下」。王先謙說「下」是。","sentenceOrder":277},
  {"id":"s_work_han_thu_75_278","chapterId":"ch_work_han_thu_75","textTraditional":"二七四八頁　七行　愚以為親諡宜曰悼（皇），母曰悼后。　王念孫說景祐本無「皇」字是。","sentenceOrder":278},
  {"id":"s_work_han_thu_75_279","chapterId":"ch_work_han_thu_75","textTraditional":"二七四八頁一五行　（師古）〔孟康〕曰「閿，古闅字，從門中{目攴}。建安中正作（聞）閿」。　景祐、殿本「師古」作「孟康」，「聞」作「閿」，此誤。","sentenceOrder":279},
  {"id":"s_work_han_thu_75_280","chapterId":"ch_work_han_thu_75","textTraditional":"二七五０頁　三行　信執中和之（得）〔德〕，　景祐、殿本都作「德」，此誤。","sentenceOrder":280},
  {"id":"s_work_han_thu_75_281","chapterId":"ch_work_han_thu_75","textTraditional":"二七五一頁　九行　王孺見執金吾廣（義）意，　景祐、殿本都作「廣意」，注同。按下文作「廣意」。","sentenceOrder":281},
  {"id":"s_work_han_thu_75_282","chapterId":"ch_work_han_thu_75","textTraditional":"二七五四頁　六行　（謂）〔為〕金蟬以附冠前也。　景祐、殿本都作「為」。","sentenceOrder":282},
  {"id":"s_work_han_thu_75_283","chapterId":"ch_work_han_thu_75","textTraditional":"二七五七頁　二行　飲井水，（水泉）〔井水〕竭。　景祐本作「井水」。王念孫說景祐本是。","sentenceOrder":283},
  {"id":"s_work_han_thu_75_284","chapterId":"ch_work_han_thu_75","textTraditional":"二七五八頁　三行　寘音徒（一）〔千〕反。　景祐、殿本都作「千」。王先謙說作「千」是。","sentenceOrder":284},
  {"id":"s_work_han_thu_75_285","chapterId":"ch_work_han_thu_75","textTraditional":"二七五八頁　七行　后（妃）〔姬〕夫人共啼泣止王。　景祐、汲古、殿、局本都作「姬」，此誤。","sentenceOrder":285},
  {"id":"s_work_han_thu_75_286","chapterId":"ch_work_han_thu_75","textTraditional":"二七五八頁一０行　從高〔皇〕帝墾菑除害，　景祐、殿本都有「皇」字。","sentenceOrder":286},
  {"id":"s_work_han_thu_75_287","chapterId":"ch_work_han_thu_75","textTraditional":"二七五八頁一０行　〔當此之時，頭如蓬葆〕，　景祐、殿本有此八字，此脫。","sentenceOrder":287},
  {"id":"s_work_han_thu_75_288","chapterId":"ch_work_han_thu_75","textTraditional":"二七五八頁一一行　然其賞不過（諸）〔封〕侯。　景祐、殿本都作「封」。王先謙說作「封」是。","sentenceOrder":288},
  {"id":"s_work_han_thu_75_289","chapterId":"ch_work_han_thu_75","textTraditional":"二七五八頁一三行　當何面目復（舉）〔奉〕齊酎見高祖之廟乎！　景祐、殿本都作「奉」。王先謙說作「奉」是。","sentenceOrder":289},
  {"id":"s_work_han_thu_75_290","chapterId":"ch_work_han_thu_75","textTraditional":"二七五九頁　三行　〔服虔曰〕：　宋祈說，浙本注文「頭」字上有此三字。又此注二十字，景祐、殿本有，此脫。","sentenceOrder":290},
  {"id":"s_work_han_thu_75_291","chapterId":"ch_work_han_thu_75","textTraditional":"二七五九頁　九行　王官之〔主〕醫者也。　景祐、殿本都有「主」字。王先謙說有「主」字是。","sentenceOrder":291},
  {"id":"s_work_han_thu_75_292","chapterId":"ch_work_han_thu_75","textTraditional":"二七五九頁一０行　賢為（定安）〔安定〕侯，　景祐、殿本都作「安定」。王先謙說作「安定」是。","sentenceOrder":292},
  {"id":"s_work_han_thu_75_293","chapterId":"ch_work_han_thu_75","textTraditional":"二七六一頁　一行　左右皆（服）〔伏〕。　景祐、殿本都作「伏」。","sentenceOrder":293},
  {"id":"s_work_han_thu_75_294","chapterId":"ch_work_han_thu_75","textTraditional":"二七六四頁　八行　（今）〔令〕為喪主。　景祐、殿本都作「令」，此誤。","sentenceOrder":294},
  {"id":"s_work_han_thu_75_295","chapterId":"ch_work_han_thu_75","textTraditional":"二七七０頁一一行　今見為〔侯〕。　景祐、殿本都有「侯」字。","sentenceOrder":295},
  {"id":"s_work_han_thu_76_1","chapterId":"ch_work_han_thu_76","textTraditional":"師古曰：「分嚴安以後為下卷。」","sentenceOrder":1},
  {"id":"s_work_han_thu_76_2","chapterId":"ch_work_han_thu_76","textTraditional":"嚴助，會稽吳人，嚴夫子子也，〔一〕或言族家子也。〔二〕郡舉賢良，對策百餘人，武帝善助對，繇是獨擢助為中大夫。後得朱買臣、吾丘壽王、司馬相如、主父偃、徐樂、嚴安、東方朔、枚皋、膠倉、終軍、嚴蔥奇等，並在左右。是時征伐四夷，開置邊郡，軍旅數發，內改制度，朝廷多事，婁舉賢良文學之士。〔三〕公孫弘起徒步，數年至丞相，開東閣，延賢人與謀議，朝覲奏事，因言國家便宜。上令助等與大臣辯論，中外相應以義理之文，〔四〕大臣數詘。〔五〕其尤親幸者，東方朔、枚皋、嚴助、吾丘壽王、司馬相如。相如常稱疾避事。朔、皋不根持論，上頗俳優畜之。〔六〕唯助與壽王見任用，而助最先進。","sentenceOrder":2},
  {"id":"s_work_han_thu_76_3","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　張晏曰：「夫子，嚴忌也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_76_4","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「亦云夫子之族子也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_76_5","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「婁，古屢字。」","sentenceOrder":5},
  {"id":"s_work_han_thu_76_6","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「中謂天子之賓客，若嚴助之輩也。外謂公卿大夫也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_76_7","chapterId":"ch_work_han_thu_76","textTraditional":"〔五〕　師古曰：「謂計議不如助等，每詘服也，音丘勿反。」","sentenceOrder":7},
  {"id":"s_work_han_thu_76_8","chapterId":"ch_work_han_thu_76","textTraditional":"〔六〕　師古曰：「論議委隨，不能持正，如樹木之無根柢也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_76_9","chapterId":"ch_work_han_thu_76","textTraditional":"建元三年，閩越舉兵圍東甌，東甌告急於漢。時武帝年未二十，以問太尉田蚡。蚡以為越人相攻擊，其常事，又數反覆，不足煩中國往救也，自秦時棄不屬。〔一〕於是助詰蚡曰：「特患力不能救，德不能覆，誠能，何故棄之？且秦舉咸陽而棄之，何但越也！〔二〕今小國以窮困來告急，天子不振，尚安所愬，〔三〕又何以子萬國乎？」〔四〕上曰：「太尉不足與計。吾新即位，不欲出虎符發兵郡國。」乃遣助以節發兵會稽。會稽守欲距法，不為發。〔五〕助乃斬一司馬，諭意指，〔六〕遂發兵浮海救東甌。未至，閩越引兵罷。","sentenceOrder":9},
  {"id":"s_work_han_thu_76_10","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「言不臣屬於中華。」","sentenceOrder":10},
  {"id":"s_work_han_thu_76_11","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「舉，總也。言總天下乃至京師皆棄也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_76_12","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「振，舉也，起也。安，焉也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_76_13","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「子謂畜為臣子也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_76_14","chapterId":"ch_work_han_thu_76","textTraditional":"〔五〕　師古曰：「以法距之，為無符驗也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_76_15","chapterId":"ch_work_han_thu_76","textTraditional":"〔六〕　師古曰：「以天子意指曉告之。」","sentenceOrder":15},
  {"id":"s_work_han_thu_76_16","chapterId":"ch_work_han_thu_76","textTraditional":"後三歲，閩越復興兵擊南越。南越守天子約，不敢擅發兵，而上書以聞。上多其義，〔一〕大為發興，遣兩將軍將兵誅閩越。淮南王安上書諫曰：","sentenceOrder":16},
  {"id":"s_work_han_thu_76_17","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「多猶重也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_76_18","chapterId":"ch_work_han_thu_76","textTraditional":"陛下臨天下，布德施惠，緩刑罰，薄賦斂，哀鰥寡，恤孤獨，養耆老，振匱乏，盛德上隆，和澤下洽，近者親附，遠者懷德，天下攝然，〔一〕人安其生，自以〔沒〕身不見兵革。今聞有司舉兵將以誅越，臣安竊為陛下重之。〔二〕越，方外之地，劗髮文身之民也。〔三〕不可以冠帶之國法度理也。自三代之盛，胡越不與受正朔，〔四〕非彊弗能服，威弗能制也，以為不居之地，不牧之民，不足以煩中國也。〔五〕故古者封內甸服，〔六〕封外侯服，〔七〕侯衛賓服，〔八〕蠻夷要服，〔九〕戎狄荒服，〔一０〕遠近勢異也。自漢初定已來七十二年，吳越人相攻擊者不可勝數，然天子未嘗舉兵而入其地也。","sentenceOrder":18},
  {"id":"s_work_han_thu_76_19","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　孟康曰：「攝，安也。音奴協反。」","sentenceOrder":19},
  {"id":"s_work_han_thu_76_20","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「重，難也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_76_21","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　晉灼曰：「淮南云『越人劗髮』，張揖以為古翦字也。」師古曰：「劗與翦同，（晉）〔張〕說是也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_76_22","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「與讀曰豫。」","sentenceOrder":22},
  {"id":"s_work_han_thu_76_23","chapterId":"ch_work_han_thu_76","textTraditional":"〔五〕　師古曰：「地不可居，而民不可牧養也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_76_24","chapterId":"ch_work_han_thu_76","textTraditional":"〔六〕　師古曰：「封內謂封圻千里之內也。甸服，主治王田以供祭祀也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_76_25","chapterId":"ch_work_han_thu_76","textTraditional":"〔七〕　師古曰：「封外，千里之外也。侯，候也，為王者斥候。」","sentenceOrder":25},
  {"id":"s_work_han_thu_76_26","chapterId":"ch_work_han_thu_76","textTraditional":"〔八〕　服虔曰：「侯服之外，又有衛服。賓，賓見於王也。侯衛二服同為賓也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_76_27","chapterId":"ch_work_han_thu_76","textTraditional":"〔九〕　師古曰：「又在侯衛之外而居九州之（地）〔內〕也。要，言以文德要來之耳，音一遙反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_76_28","chapterId":"ch_work_han_thu_76","textTraditional":"〔一０〕師古曰：「此在九州之外者也。荒，言其荒忽絕遠，來去無常也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_76_29","chapterId":"ch_work_han_thu_76","textTraditional":"臣聞越非有城郭邑里也，處谿谷之間，篁竹之中，〔一〕習於水鬥，便於用舟，地深昧而多水險，〔二〕中國之人不知其勢阻而入其地，雖百不當其一。得其地，不可郡縣也；攻之，不可暴取也。以地圖察其山川要塞，相去不過寸數，而間獨數百千里，〔三〕阻險林叢弗能盡著。〔四〕視之若易，行之甚難。天下賴宗廟之靈，方內大寧，戴白之老不見兵革，〔五〕民得夫婦相守，父子相保，陛下之德也。越人名為藩臣，貢酎之奉，不輸大內，〔六〕一卒之用不給上事。〔七〕自相攻擊而陛下發兵救之，是反以中國而勞蠻夷也。〔八〕且越人愚戇輕薄，負約反覆，其不（可）用天子之法度，非一日之積也。〔九〕壹不奉詔，舉兵誅之，臣恐後兵革無時得息也。","sentenceOrder":29},
  {"id":"s_work_han_thu_76_30","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　服虔曰：「竹叢也。音皇。」師古曰：「竹田曰篁。」","sentenceOrder":30},
  {"id":"s_work_han_thu_76_31","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「昧，暗也。言多草木。」","sentenceOrder":31},
  {"id":"s_work_han_thu_76_32","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「間，中間也。或八九百里，或千里也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_76_33","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「不可盡載於圖也。著音竹助反。」","sentenceOrder":33},
  {"id":"s_work_han_thu_76_34","chapterId":"ch_work_han_thu_76","textTraditional":"〔五〕　師古曰：「戴白，言白髮在首。」","sentenceOrder":34},
  {"id":"s_work_han_thu_76_35","chapterId":"ch_work_han_thu_76","textTraditional":"〔六〕　應劭曰：「越國僻遠，珍奇之貢，宗廟之祭皆不與也。大內，都內也，國家寶藏也。」師古曰：「百官公卿表云治粟屬官有都內令丞也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_76_36","chapterId":"ch_work_han_thu_76","textTraditional":"〔七〕　師古曰：「給，供也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_76_37","chapterId":"ch_work_han_thu_76","textTraditional":"〔八〕　師古曰：「疲勞中國之人於蠻夷之地。」","sentenceOrder":37},
  {"id":"s_work_han_thu_76_38","chapterId":"ch_work_han_thu_76","textTraditional":"〔九〕　師古曰：「積，久也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_76_39","chapterId":"ch_work_han_thu_76","textTraditional":"間者，數年歲比不登，民待賣爵贅子以接衣食，〔一〕賴陛下德澤振救之，得毋轉死溝壑。四年不登，五年復蝗，民生未復〔二〕。今發兵行數千里，資衣糧，入越地，〔三〕輿轎而隃領，〔四〕拕舟而入水，〔五〕行數百千里，夾以深林叢竹，水道上下擊石〔六〕，林中多蝮蛇猛獸，〔七〕夏月暑時，歐泄霍亂之病相隨屬也〔八〕，曾未施兵接刃，死傷者必眾矣。前時南海王反，陛下先臣使將軍間忌將兵擊之，〔九〕以其軍降，處之上淦。〔一０〕後復反，會天暑多雨，樓船卒水居擊櫂，〔一一〕未戰而疾死者過半。親老涕泣，孤子謕號，〔一二〕破家散業，迎尸千里之外，裹骸骨而歸。悲哀之氣數年不息，長老至今以為記。曾未入其地而禍已至此矣。","sentenceOrder":39},
  {"id":"s_work_han_thu_76_40","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　如淳曰：「淮南俗賣子與人作奴婢，名為贅子，三年不能贖，遂為奴婢。」師古曰：「贅，質也。一說，云贅子者，謂令子出就婦家為贅婿耳。贅婿解在賈誼傳。」","sentenceOrder":40},
  {"id":"s_work_han_thu_76_41","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「生謂生業。復音（拱）〔扶〕目反。」","sentenceOrder":41},
  {"id":"s_work_han_thu_76_42","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「資猶齎。」","sentenceOrder":42},
  {"id":"s_work_han_thu_76_43","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　服虔曰：「轎音橋梁，謂隘道輿車也。」臣瓚曰：「今竹輿車也，江表作竹輿以行是也。」項昭曰：「陵絕水曰轎，音旗廟反。領，山領也。不通船車，運轉皆擔輿也。」師古曰：「服音、瓚說是也。項氏謬矣。此直言以轎過領耳，何云陵絕水乎！又旗廟之音無所依據。隃與踰同。」","sentenceOrder":43},
  {"id":"s_work_han_thu_76_44","chapterId":"ch_work_han_thu_76","textTraditional":"〔五〕　師古曰：「拕，曳也，音它。」","sentenceOrder":44},
  {"id":"s_work_han_thu_76_45","chapterId":"ch_work_han_thu_76","textTraditional":"〔六〕　師古曰：「謂船觸石，難以行也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_76_46","chapterId":"ch_work_han_thu_76","textTraditional":"〔七〕　師古曰：「蝮，惡蛇也，音敷福反，解在田儋傳。」","sentenceOrder":46},
  {"id":"s_work_han_thu_76_47","chapterId":"ch_work_han_thu_76","textTraditional":"〔八〕　師古曰：「泄，吐也，音弋制反。屬音之欲反。」","sentenceOrder":47},
  {"id":"s_work_han_thu_76_48","chapterId":"ch_work_han_thu_76","textTraditional":"〔九〕　文穎曰：「先臣，淮南厲王長也。間忌，人姓名。」師古曰：「淮南王傳作簡忌，此本作間，轉寫字誤省耳。」","sentenceOrder":48},
  {"id":"s_work_han_thu_76_49","chapterId":"ch_work_han_thu_76","textTraditional":"〔一０〕蘇林曰：「淦音耿弇之弇。」師古曰：「音工含反。」","sentenceOrder":49},
  {"id":"s_work_han_thu_76_50","chapterId":"ch_work_han_thu_76","textTraditional":"〔一一〕師古曰：「言常居舟中水上，而又有擊櫂行舟之役，故多死也。櫂音直孝反。」","sentenceOrder":50},
  {"id":"s_work_han_thu_76_51","chapterId":"ch_work_han_thu_76","textTraditional":"〔一二〕師古曰：「謕，古啼字。」","sentenceOrder":51},
  {"id":"s_work_han_thu_76_52","chapterId":"ch_work_han_thu_76","textTraditional":"臣聞軍旅之後必有凶年，言民之各以其愁苦之氣薄陰陽之和，感天地之精，〔一〕而災氣為之生也。陛下德配天地，明象日月，恩至禽獸，澤及草木，一人有飢寒不終其天年而死者，為之悽愴於心。今方內無狗吠之警，〔二〕而使陛下甲卒死亡，暴露中原，霑漬山谷，邊境之民為之早閉晏開，〔三〕晁不及夕，〔四〕臣安竊為陛下重之。〔五〕","sentenceOrder":52},
  {"id":"s_work_han_thu_76_53","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「薄，迫也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_76_54","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「方內，中國四方之內也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_76_55","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「晏，晚也。言有兵難，故邊城早閉而晚開也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_76_56","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「晁，古朝字也。言憂危亡不自保也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_76_57","chapterId":"ch_work_han_thu_76","textTraditional":"〔五〕　師古曰：「重，難也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_76_58","chapterId":"ch_work_han_thu_76","textTraditional":"不習南方地形者，多以越為人眾兵彊，能難邊城。〔一〕淮南全國之時，多為邊吏，〔二〕臣竊聞之，與中國異。〔三〕限以高山，人跡所絕，車道不通，天地所以隔外內也。其入中國必下領水，領水之山峭峻，漂石破舟，〔四〕不可以大船載食糧下也。越人欲為變，必先田餘干界中，〔五〕積食糧，乃入伐材治船。邊城守候誠謹，越人有入伐材者，輒收捕，焚其積聚，雖百越，奈邊城何！且越人綿力薄材，〔六〕不能陸戰，又無車騎弓弩之用，然而不可入者，以保地險，而中國之人不能其水土也。〔七〕臣聞越甲卒不下數十萬，所以入之，五倍乃足，〔八〕輓車奉饟者，不在其中。〔九〕南方暑溼，近夏癉熱，〔一０〕暴露水居，蝮蛇蠚生，〔一一〕疾癘多作，兵未血刃而病死者什二三，雖舉越國而虜之，不足以償所亡。〔一二〕","sentenceOrder":58},
  {"id":"s_work_han_thu_76_59","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　服虔曰：「為邊城作難也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_76_60","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「全國謂未分為三之時也。淮南人於邊為吏，與越接境，故知其地形也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_76_61","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「言其風土不同。」","sentenceOrder":61},
  {"id":"s_work_han_thu_76_62","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「言水流湍急，石為之漂轉，觸破舟船也。漂音匹遙反。」","sentenceOrder":62},
  {"id":"s_work_han_thu_76_63","chapterId":"ch_work_han_thu_76","textTraditional":"〔五〕　韋昭曰：「越邑，今鄱陽縣也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_76_64","chapterId":"ch_work_han_thu_76","textTraditional":"〔六〕　孟康曰：「綿音滅，薄力也。」師古曰：「綿，弱也，言其柔弱如綿，讀如本字。孟說非也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_76_65","chapterId":"ch_work_han_thu_76","textTraditional":"〔七〕　師古曰：「能，堪也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_76_66","chapterId":"ch_work_han_thu_76","textTraditional":"〔八〕　師古曰：「不下，言不減也。漢軍多之五倍，然後可入其地也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_76_67","chapterId":"ch_work_han_thu_76","textTraditional":"〔九〕　師古曰：「輓，引也，音晚。饟亦餉字。」","sentenceOrder":67},
  {"id":"s_work_han_thu_76_68","chapterId":"ch_work_han_thu_76","textTraditional":"〔一０〕師古曰：「癉，黃病，音丁幹反。」","sentenceOrder":68},
  {"id":"s_work_han_thu_76_69","chapterId":"ch_work_han_thu_76","textTraditional":"〔一一〕師古曰：「蠚，毒也，音壑。」","sentenceOrder":69},
  {"id":"s_work_han_thu_76_70","chapterId":"ch_work_han_thu_76","textTraditional":"〔一二〕師古曰：「舉謂總取也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_76_71","chapterId":"ch_work_han_thu_76","textTraditional":"臣聞道路言，閩越王弟甲弒而殺之，〔一〕甲以誅死，其民未有所屬。陛下若欲來內，處之中國，使重臣臨存，〔二〕施德垂賞以招致之，此必攜幼扶老以歸聖德。若陛下無所用之，則繼其絕世，存其亡國，建其王侯，以為畜越，〔三〕此必委質為藩臣，世共貢職。〔四〕陛下以方寸之印，丈二之組，填撫方外，〔五〕不勞一卒，不頓一戟，〔六〕而威德並行。今以兵入其地，此必震恐，以有司為欲屠滅之也，必雉兔逃入山林險阻。〔七〕背而去之，則復相群聚；留而守之，歷歲經年，則士卒罷倦，食糧乏絕，〔八〕男子不得耕稼（種樹）〔樹種〕，婦人不得紡績織紝，〔九〕丁壯從軍，老弱轉餉，〔一０〕居者無食，行者無糧。民苦兵事，亡逃者必眾，隨而誅之，不可勝盡，盜賊必起。","sentenceOrder":71},
  {"id":"s_work_han_thu_76_72","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「甲者，閩王弟之名。」","sentenceOrder":72},
  {"id":"s_work_han_thu_76_73","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「存謂省問之。」","sentenceOrder":73},
  {"id":"s_work_han_thu_76_74","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　李奇曰：「如人畜養六畜也。」師古曰：「直謂畜養之耳，非六畜也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_76_75","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「共讀曰供。」","sentenceOrder":75},
  {"id":"s_work_han_thu_76_76","chapterId":"ch_work_han_thu_76","textTraditional":"〔五〕　師古曰：「組者，印之綬。」","sentenceOrder":76},
  {"id":"s_work_han_thu_76_77","chapterId":"ch_work_han_thu_76","textTraditional":"〔六〕　師古曰：「頓，壞也。一曰頓讀曰鈍。」","sentenceOrder":77},
  {"id":"s_work_han_thu_76_78","chapterId":"ch_work_han_thu_76","textTraditional":"〔七〕　師古曰：「如雉兔之逃竄而入山林險阻之中。」","sentenceOrder":78},
  {"id":"s_work_han_thu_76_79","chapterId":"ch_work_han_thu_76","textTraditional":"〔八〕　師古曰：「罷讀曰疲。勌亦倦字。」","sentenceOrder":79},
  {"id":"s_work_han_thu_76_80","chapterId":"ch_work_han_thu_76","textTraditional":"〔九〕　師古曰：「樹，植也。機縷曰紝。紝音人禁反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_76_81","chapterId":"ch_work_han_thu_76","textTraditional":"〔一０〕師古曰：「餉亦饟字。」","sentenceOrder":81},
  {"id":"s_work_han_thu_76_82","chapterId":"ch_work_han_thu_76","textTraditional":"臣聞長老言，秦之時嘗使尉屠睢擊越，〔一〕又使監祿鑿渠通道。〔二〕越人逃入深山林叢，不可得攻。留軍屯守空地，曠日（持）〔引〕久，士卒勞倦，越（乃）出擊之。秦兵大破，乃發適戍以備之。〔三〕當此之時，外內騷動，百姓靡敝，〔四〕行者不還，往者（果）〔莫〕反，皆不聊生，亡逃相從，群為盜賊，於是山東之難始興。此老子所謂「師之所處，荊棘生之」者也。〔五〕兵者凶事，一方有急，四面皆從。臣恐變故之生，姦邪之作，由此始也。周易曰：「高宗伐鬼方，三年而克之。」〔六〕鬼方，小蠻夷；高宗，殷之盛天子也。以盛天子伐小蠻夷，三年而後克，言用兵之不可不重也。","sentenceOrder":82},
  {"id":"s_work_han_thu_76_83","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　張晏曰：「郡都尉，姓屠名睢也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_76_84","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　張晏曰：「監郡御史也，名祿。」","sentenceOrder":84},
  {"id":"s_work_han_thu_76_85","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「適讀曰謫。」","sentenceOrder":85},
  {"id":"s_work_han_thu_76_86","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「靡，散也，音縻。」","sentenceOrder":86},
  {"id":"s_work_han_thu_76_87","chapterId":"ch_work_han_thu_76","textTraditional":"〔五〕　師古曰：「老子道經之言也。師旅行，必殺傷士眾，侵暴田畝，故致荒殘而生荊棘也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_76_88","chapterId":"ch_work_han_thu_76","textTraditional":"〔六〕　師古曰：「既濟九三爻辭。」","sentenceOrder":88},
  {"id":"s_work_han_thu_76_89","chapterId":"ch_work_han_thu_76","textTraditional":"臣聞天子之兵有征而無戰，言莫敢（挍）〔校〕也。〔一〕如使越人蒙（死）徼幸以逆執事之顏行，〔二〕廝輿之卒有一不備而歸者，〔三〕雖得越王之首，臣猶竊為大漢羞之。陛下以四海為境，九州為家，八（蔬）〔藪〕為囿，江（海）〔漢〕為池，〔四〕生民之屬皆為臣妾。人徒之眾足以奉千官之共，〔五〕租稅之收足以給乘輿之御。玩心神明，秉執聖道，負黼依，〔六〕馮玉几，〔七〕南面而聽斷，號令天下，四海之內莫不嚮應。〔八〕陛下垂德惠以覆露之，〔九〕使元元之民安生樂業，則澤被萬世，傳之子孫，施之無窮。天下之安猶泰山而四維之也，〔一０〕夷狄之地何足以為一日之閒，〔一一〕而煩汗馬之勞乎！詩云「王猶允塞，徐方既來」，〔一二〕言王道甚大，而遠方懷之也。臣聞之，農夫勞而君子養焉，〔一三〕愚者言而智者擇焉。臣安幸得為陛下守藩，以身為鄣蔽，人臣之任也。邊境有警，愛身之死而不畢其愚，非忠臣也。〔一四〕臣安竊恐將吏之以十萬之師為一使之任也！〔一五〕","sentenceOrder":89},
  {"id":"s_work_han_thu_76_90","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「（挍）〔校〕，計也。不敢與計彊弱曲直。」","sentenceOrder":90},
  {"id":"s_work_han_thu_76_91","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　文穎曰：「顏行猶雁行，在前行，故曰顏也。」師古曰：「蒙，犯也。行音胡郎反。」","sentenceOrder":91},
  {"id":"s_work_han_thu_76_92","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　張晏曰：「廝，微；輿，眾也。」師古曰：「廝，析薪者。輿，主駕車者。此皆言賤役之人。」","sentenceOrder":92},
  {"id":"s_work_han_thu_76_93","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「八藪，謂魯有大野，晉有大陸，秦有楊汙，宋有孟諸，楚有雲夢，吳越之間有具區，齊有海隅，鄭有圃田。」","sentenceOrder":93},
  {"id":"s_work_han_thu_76_94","chapterId":"ch_work_han_thu_76","textTraditional":"〔五〕　師古曰：「千官猶百官也，多言之耳。共讀曰供。」","sentenceOrder":94},
  {"id":"s_work_han_thu_76_95","chapterId":"ch_work_han_thu_76","textTraditional":"〔六〕　師古曰：「負，背也。白與黑畫為斧文，謂之黼也。依讀曰扆。扆形如屏風而曲之，畫以黼文，張於戶牖之間。」","sentenceOrder":95},
  {"id":"s_work_han_thu_76_96","chapterId":"ch_work_han_thu_76","textTraditional":"〔七〕　師古曰：「馮讀曰凭。」","sentenceOrder":96},
  {"id":"s_work_han_thu_76_97","chapterId":"ch_work_han_thu_76","textTraditional":"〔八〕　師古曰：「嚮讀曰響。」","sentenceOrder":97},
  {"id":"s_work_han_thu_76_98","chapterId":"ch_work_han_thu_76","textTraditional":"〔九〕　師古曰：「露謂使之沾潤澤也。或露或覆，言養育也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_76_99","chapterId":"ch_work_han_thu_76","textTraditional":"〔一０〕師古曰：「維謂聯繫之。」","sentenceOrder":99},
  {"id":"s_work_han_thu_76_100","chapterId":"ch_work_han_thu_76","textTraditional":"〔一一〕如淳曰：「得其地物，不足為一日閒暇之虞也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_76_101","chapterId":"ch_work_han_thu_76","textTraditional":"〔一二〕師古曰：「大雅常武之詩。猶，道也。允，信也。塞，滿也。既，盡也。言王道信充滿於天下，則徐方淮夷盡來服也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_76_102","chapterId":"ch_work_han_thu_76","textTraditional":"〔一三〕師古曰：「言農夫勤力於耕稼，所得五穀以養君子也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_76_103","chapterId":"ch_work_han_thu_76","textTraditional":"〔一四〕師古曰：「畢，盡也，盡言其意也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_76_104","chapterId":"ch_work_han_thu_76","textTraditional":"〔一五〕師古曰：「言漢發一使鎮撫之，則越人賓服，不煩兵往。」","sentenceOrder":104},
  {"id":"s_work_han_thu_76_105","chapterId":"ch_work_han_thu_76","textTraditional":"是時，漢兵遂出，〔未〕踰領，適會閩越王弟餘善殺王以降。漢兵罷。上嘉淮南之意，美將卒之功，乃令嚴助諭意風指於南越。〔一〕南越王頓首曰：「天子乃幸興兵誅閩越，死無以報！」即遣太子隨助入侍。","sentenceOrder":105},
  {"id":"s_work_han_thu_76_106","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「風讀曰諷，以天子之意指諷告也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_76_107","chapterId":"ch_work_han_thu_76","textTraditional":"助還，又諭淮南曰：「皇帝問淮南王：使中大夫玉上書言事，聞之。朕奉先帝之休德，夙興夜（昧）〔寐〕，明不能燭，〔一〕重以不德，〔二〕是以比年凶菑害眾。〔三〕夫以眇眇之身，託于王侯之上，內有飢寒之民，南夷相攘，〔四〕使邊騷然不安，朕甚懼焉。今王深惟重慮，〔五〕明太平以弼朕失，稱三代至盛，際天接地，人跡所及，咸盡賓服，藐然甚慚。〔六〕嘉王之意，靡有所終，〔七〕使中大夫助諭朕意，告王越事。」","sentenceOrder":107},
  {"id":"s_work_han_thu_76_108","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「燭，照也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_76_109","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「重音直用反。」","sentenceOrder":109},
  {"id":"s_work_han_thu_76_110","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「菑，古災字。」","sentenceOrder":110},
  {"id":"s_work_han_thu_76_111","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「攘謂相侵奪也，音人羊反。」","sentenceOrder":111},
  {"id":"s_work_han_thu_76_112","chapterId":"ch_work_han_thu_76","textTraditional":"〔五〕　師古曰：「惟，思也。慮，計也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_76_113","chapterId":"ch_work_han_thu_76","textTraditional":"〔六〕　如淳曰：「王之所言藐然，聞之甚慚也。」師古曰：「藐，遠也。言不可及也。藐音武卓反。」","sentenceOrder":113},
  {"id":"s_work_han_thu_76_114","chapterId":"ch_work_han_thu_76","textTraditional":"〔七〕　師古曰：「靡，無也。終，極也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_76_115","chapterId":"ch_work_han_thu_76","textTraditional":"助諭意曰：「今者大王以發屯臨越事上書，陛下故遣臣助告王其事。王居遠，事薄遽，不與王同其計。〔一〕朝有闕政，遺王之憂，〔二〕陛下甚恨之。夫兵固凶器，明主之所重出也，〔三〕然自五帝三王禁暴止亂，非兵，未之聞也。漢為天下宗，操殺生之柄，〔四〕以制海內之命，危者望安，亂者卬治。〔五〕今閩越王狼戾不仁〔六〕，殺其骨肉，離其親戚，所為甚多不義，又數舉兵侵陵百越，并兼鄰國，以為暴彊，陰計奇策，入燔尋陽樓船，〔七〕欲招會稽之地，以踐句踐之跡。〔八〕今者，邊又言閩王率兩國擊南越。陛下為萬民安危久遠之計，使人諭告之曰：『天下安寧，各繼世撫民，禁毋敢相并。』有司疑其以虎狼之心，貪據百越之利，或於逆順，不奉明詔，則會稽、豫章必有長患。且天子誅而不伐，焉有勞百姓苦士卒乎〔九〕？故遣兩將屯於境上，震威武，揚聲鄉。〔一０〕屯曾未會，〔一一〕天誘其衷，閩王隕命，輒遣使者罷屯，毋後農時。〔一二〕南越王甚嘉被惠澤，蒙休德，願革心易行，身從使者入謝。〔一三〕有狗馬之病，不能勝服，〔一四〕故遣太子嬰齊入侍；病有瘳，願伏北闕，望大廷，以報盛德。閩王以八月舉兵於冶南，〔一五〕士卒罷倦，〔一六〕三王之眾相與攻之，因其弱弟餘善以成其（謀）〔誅〕。至今國空虛，遣使者上符節，請所立，不敢自立，以待天子之明詔。此一舉，不挫一兵之鋒，不用一卒之死，而閩王伏辜，南越被澤，威震暴王，義存危國，此則陛下深計遠慮之所出也。事效見前，〔一七〕故使臣助來諭王意。」","sentenceOrder":115},
  {"id":"s_work_han_thu_76_116","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　如淳曰：「薄，迫也。言事迫，不暇得先與王共議之。或曰薄，語助也。」師古曰：「薄，迫，是也。遽，速也，音其据反。」","sentenceOrder":116},
  {"id":"s_work_han_thu_76_117","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「言朝政有闕，乃使王有憂也。遺猶與也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_76_118","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「重，難也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_76_119","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「操，執持也，音千高反。」","sentenceOrder":119},
  {"id":"s_work_han_thu_76_120","chapterId":"ch_work_han_thu_76","textTraditional":"〔五〕　師古曰：「卬讀曰仰，謂仰而望之。」","sentenceOrder":120},
  {"id":"s_work_han_thu_76_121","chapterId":"ch_work_han_thu_76","textTraditional":"〔六〕　師古曰：「狼性貪戾，凡言狼戾者，謂貪而戾。」","sentenceOrder":121},
  {"id":"s_work_han_thu_76_122","chapterId":"ch_work_han_thu_76","textTraditional":"〔七〕　師古曰：「漢有樓船貯在尋陽也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_76_123","chapterId":"ch_work_han_thu_76","textTraditional":"〔八〕　師古曰：「先是越王句踐稱霸中國，今越王欲慕之。句音工侯反。」","sentenceOrder":123},
  {"id":"s_work_han_thu_76_124","chapterId":"ch_work_han_thu_76","textTraditional":"〔九〕　師古曰：「王者之兵，但行誅耳，無有戰鬥，故云不伐也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_76_125","chapterId":"ch_work_han_thu_76","textTraditional":"〔一０〕師古曰：「鄉讀曰響。」","sentenceOrder":125},
  {"id":"s_work_han_thu_76_126","chapterId":"ch_work_han_thu_76","textTraditional":"〔一一〕師古曰：「言兵未盡集。」","sentenceOrder":126},
  {"id":"s_work_han_thu_76_127","chapterId":"ch_work_han_thu_76","textTraditional":"〔一二〕師古曰：「令及農時，不待後也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_76_128","chapterId":"ch_work_han_thu_76","textTraditional":"〔一三〕師古曰：「革，改也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_76_129","chapterId":"ch_work_han_thu_76","textTraditional":"〔一四〕師古曰：「服謂朝服也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_76_130","chapterId":"ch_work_han_thu_76","textTraditional":"〔一五〕蘇林曰：「山名也，今名東冶，屬會稽。」","sentenceOrder":130},
  {"id":"s_work_han_thu_76_131","chapterId":"ch_work_han_thu_76","textTraditional":"〔一六〕師古曰：「罷讀曰疲。」","sentenceOrder":131},
  {"id":"s_work_han_thu_76_132","chapterId":"ch_work_han_thu_76","textTraditional":"〔一七〕師古曰：「見，顯也。前謂目前。」","sentenceOrder":132},
  {"id":"s_work_han_thu_76_133","chapterId":"ch_work_han_thu_76","textTraditional":"於是王謝曰：「雖湯伐桀，文王伐崇，誠不過此。臣安妄以愚意狂言，陛下不忍加誅，使使者臨詔臣安以所不聞，〔一〕臣不勝厚幸！」助由是與淮南王相結而還。上大說。〔二〕","sentenceOrder":133},
  {"id":"s_work_han_thu_76_134","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「先未聞者今得聞也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_76_135","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":135},
  {"id":"s_work_han_thu_76_136","chapterId":"ch_work_han_thu_76","textTraditional":"助侍燕從容，〔一〕上問助居鄉里時，助對曰：「家貧，為友婿富人所辱。」〔二〕上問所欲，對願為會稽太守。於是拜為會稽太守。數年，不聞問。〔三〕賜書曰：「制詔會稽太守：君厭承明之廬，〔四〕勞侍從之事，懷故土，〔五〕出為郡吏。會稽東接於海，南近諸越，〔六〕北枕大江。〔七〕間者，闊焉久不聞問，具以春秋對，毋以蘇秦從橫。」〔八〕助恐，上書謝稱：「春秋天王出居于鄭，不能事母，故絕之。〔九〕臣事君，猶子事父母也，臣助當伏誅。陛下不忍加誅，願奉三年計最。」〔一０〕詔許，因留侍中。有奇異，輒使為文，〔一一〕及作賦頌數十篇。","sentenceOrder":136},
  {"id":"s_work_han_thu_76_137","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「從容，閒語也。從音千容反。」","sentenceOrder":137},
  {"id":"s_work_han_thu_76_138","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「友婿，同門之婿。」","sentenceOrder":138},
  {"id":"s_work_han_thu_76_139","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「無善聲。」","sentenceOrder":139},
  {"id":"s_work_han_thu_76_140","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　張晏曰：「承明廬在石渠閣外。直宿所止曰廬。」","sentenceOrder":140},
  {"id":"s_work_han_thu_76_141","chapterId":"ch_work_han_thu_76","textTraditional":"〔五〕　師古曰：「懷，思也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_76_142","chapterId":"ch_work_han_thu_76","textTraditional":"〔六〕　師古曰：「越種非一，故言諸。」","sentenceOrder":142},
  {"id":"s_work_han_thu_76_143","chapterId":"ch_work_han_thu_76","textTraditional":"〔七〕　師古曰：「枕，臨也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_76_144","chapterId":"ch_work_han_thu_76","textTraditional":"〔八〕　師古曰：「從音子容反。」","sentenceOrder":144},
  {"id":"s_work_han_thu_76_145","chapterId":"ch_work_han_thu_76","textTraditional":"〔九〕　師古曰：「周惠王之子襄王也。弟叔帶有寵於惠后，欲立之，故襄王避難而出奔也。僖二十四年經書：『天王出居於鄭。』公羊傳曰：『王者無外，此其言出何？不能乎母也。』」","sentenceOrder":145},
  {"id":"s_work_han_thu_76_146","chapterId":"ch_work_han_thu_76","textTraditional":"〔一０〕如淳曰：「舊法，當使丞奉歲計，（令）〔今〕躬自欲入奉也。」晉灼曰：「最，凡要也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_76_147","chapterId":"ch_work_han_thu_76","textTraditional":"〔一一〕師古曰：「謂非常之文。」","sentenceOrder":147},
  {"id":"s_work_han_thu_76_148","chapterId":"ch_work_han_thu_76","textTraditional":"後淮南王來朝，厚賂遺助，交私論議。及淮南王反，事與助相連，上薄其罪，欲勿誅。〔一〕廷尉張湯爭，以為助出入禁門，腹心之臣，而外與諸侯交私如此，不誅，後不可治。助竟棄市。","sentenceOrder":148},
  {"id":"s_work_han_thu_76_149","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「以其過為輕小。」","sentenceOrder":149},
  {"id":"s_work_han_thu_76_150","chapterId":"ch_work_han_thu_76","textTraditional":"朱買臣字翁子，吳人也。家貧，好讀書，不治產業，常艾薪樵，賣以給食，〔一〕擔束薪，行且誦書。其妻亦負戴相隨，數止買臣毋歌嘔道中。〔二〕買臣愈益疾歌，妻羞之，求去。買臣笑曰：「我年五十當富貴，今已四十餘矣。女苦日久，待我富貴報女功。」〔三〕妻恚怒曰：「如公等，終餓死溝中耳，何能富貴？」買臣不能留，即聽去。其後，買臣獨行歌道中，負薪墓間。故妻與夫家俱上冢，見買臣饑寒，呼飯飲之。〔四〕","sentenceOrder":150},
  {"id":"s_work_han_thu_76_151","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「艾讀曰刈。給，供也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_76_152","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「嘔讀曰謳，音一侯反。」","sentenceOrder":152},
  {"id":"s_work_han_thu_76_153","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「女皆讀曰汝。」","sentenceOrder":153},
  {"id":"s_work_han_thu_76_154","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「飯謂飤之，音扶晚反。飲音於禁反。」","sentenceOrder":154},
  {"id":"s_work_han_thu_76_155","chapterId":"ch_work_han_thu_76","textTraditional":"後數歲，買臣隨上計吏為卒，將重車至長安，〔一〕詣闕上書，書久不報。待詔公車，糧用乏，上計吏卒更乞匄之。〔二〕會邑子嚴助貴幸，薦買臣。召見，說春秋，言楚詞，帝甚說之，〔三〕拜買臣為中大夫，與嚴助俱侍中。是時方築朔方，公孫弘諫，以為罷敝中國。〔四〕上使買臣難詘弘，語在弘傳。後買臣坐事免，久之，召待詔。","sentenceOrder":155},
  {"id":"s_work_han_thu_76_156","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「買臣身自充卒，而與計吏將重車也。載衣食具曰重車。重音直用反。」","sentenceOrder":156},
  {"id":"s_work_han_thu_76_157","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「更音工衡反。乞音氣。匄音工大反。」","sentenceOrder":157},
  {"id":"s_work_han_thu_76_158","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「說讀曰悅。」","sentenceOrder":158},
  {"id":"s_work_han_thu_76_159","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「罷讀曰疲。」","sentenceOrder":159},
  {"id":"s_work_han_thu_76_160","chapterId":"ch_work_han_thu_76","textTraditional":"是時，東越數反覆，買臣因言：「故東越王居保泉山，〔一〕一人守險，千人不得上。今聞東越王更徙處南行，去泉山五百里，居大澤中。今發兵浮海，直指泉山，陳舟列兵，席卷南行，可破滅也。」上拜買臣會稽太守。上謂買臣曰：「富貴不歸故鄉，如衣繡夜行，今子何如？」買臣頓首辭謝。詔買臣到郡，治樓船，備糧食、水戰具，須詔書到，軍與俱進。〔二〕","sentenceOrder":160},
  {"id":"s_work_han_thu_76_161","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「泉山即今泉州之山也，臨海，去海十餘里。保者，保守之以自固也。說者乃云保是地名，失之矣。」","sentenceOrder":161},
  {"id":"s_work_han_thu_76_162","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「須，待也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_76_163","chapterId":"ch_work_han_thu_76","textTraditional":"初，買臣免，待詔，常從會稽守邸者寄居飯食。〔一〕拜為太守，買臣衣故衣，懷其印綬，步歸郡邸。直上計時，會稽吏方相與群飲，〔二〕不視買臣。買臣入室中，守邸與共食，食且飽，少見其綬。〔三〕守邸怪之，前引其綬，視其印，會稽太守章也。守邸驚，出語上計掾吏。皆醉，大呼曰：「妄誕耳！」〔四〕守邸曰：「試來視之。」其故人素輕買臣者入〔內〕視之，還走，疾呼曰：「實然！」坐中驚駭，白守丞，〔五〕相推排陳列中庭拜謁。買臣徐出戶。有頃，長安廄吏乘駟馬車來迎，〔六〕買臣遂乘傳去。〔七〕會稽聞太守且至，發民除道，縣吏並送迎，車百餘乘。入吳界，見其故妻、妻夫治道。買臣駐車，呼令後車載其夫妻，到太守舍，置園中，給食之〔八〕。居一月，妻自經死，買臣乞其夫錢，令葬。〔九〕悉召見故人與飲食諸嘗有恩者，皆報復焉。〔一０〕","sentenceOrder":163},
  {"id":"s_work_han_thu_76_164","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「飯音扶晚反。」","sentenceOrder":164},
  {"id":"s_work_han_thu_76_165","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「直讀曰值。」","sentenceOrder":165},
  {"id":"s_work_han_thu_76_166","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「見，顯示也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_76_167","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「誕，大言也。呼音火故反。次下亦同。」","sentenceOrder":167},
  {"id":"s_work_han_thu_76_168","chapterId":"ch_work_han_thu_76","textTraditional":"〔五〕　服虔曰：「守邸丞也。」張晏曰：「漢舊郡國丞長吏與計吏俱送計也。」師古曰：「張說是也。謂之守丞者，繫太守而言也。守音式授反。」","sentenceOrder":168},
  {"id":"s_work_han_thu_76_169","chapterId":"ch_work_han_thu_76","textTraditional":"〔六〕　張晏曰：「故事，大夫乘官車駕駟，如今州牧刺史矣。」","sentenceOrder":169},
  {"id":"s_work_han_thu_76_170","chapterId":"ch_work_han_thu_76","textTraditional":"〔七〕　師古曰：「傳音張戀反。」","sentenceOrder":170},
  {"id":"s_work_han_thu_76_171","chapterId":"ch_work_han_thu_76","textTraditional":"〔八〕　師古曰：「食讀曰飤。」","sentenceOrder":171},
  {"id":"s_work_han_thu_76_172","chapterId":"ch_work_han_thu_76","textTraditional":"〔九〕　師古曰：「乞音氣。」","sentenceOrder":172},
  {"id":"s_work_han_thu_76_173","chapterId":"ch_work_han_thu_76","textTraditional":"〔一０〕師古曰：「復音扶目反。」","sentenceOrder":173},
  {"id":"s_work_han_thu_76_174","chapterId":"ch_work_han_thu_76","textTraditional":"居歲餘，買臣受詔將兵，與橫海將軍韓說等俱擊破東越，〔一〕有功。徵入為主爵都尉，列於九卿。","sentenceOrder":174},
  {"id":"s_work_han_thu_76_175","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":175},
  {"id":"s_work_han_thu_76_176","chapterId":"ch_work_han_thu_76","textTraditional":"數年，坐法免官，復為丞相長史。張湯為御史大夫。始買臣與嚴助俱侍中，貴用事，湯尚為小吏，趨走買臣等前。後湯以廷尉治淮南獄，排陷嚴助，買臣怨湯。及買臣為長史，湯數行丞相事，知買臣素貴，故陵折之。買臣見湯，坐床上弗為禮。〔一〕買臣深怨，常欲死之。〔二〕後遂告湯陰事，湯自殺，上亦誅買臣。買臣子山拊〔三〕官至郡守，右扶風。","sentenceOrder":176},
  {"id":"s_work_han_thu_76_177","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「言不動容以禮之也。為音于偽反。」","sentenceOrder":177},
  {"id":"s_work_han_thu_76_178","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「致死以害之。」","sentenceOrder":178},
  {"id":"s_work_han_thu_76_179","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　如淳曰：「拊音夫。」","sentenceOrder":179},
  {"id":"s_work_han_thu_76_180","chapterId":"ch_work_han_thu_76","textTraditional":"吾丘壽王字子贛，趙人也。年少，以善格五召待詔。〔一〕詔使從中大夫董仲舒受春秋，高材通明。遷侍中中郎，坐法免。上書謝罪，願養馬黃門，上不許。〔二〕後願守塞扞寇難，復不許。久之，上疏願擊匈奴，詔問狀，壽王對良善，復召為郎。","sentenceOrder":180},
  {"id":"s_work_han_thu_76_181","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　蘇林曰：「博之類，不用箭，但行梟散。」孟康曰：「格音各。行伍相各，故言各。」劉德曰：「格五，棋行。簺法曰簺白乘五，至五格不得行，故云格五。」師古曰：「即今戲之簺也。音先代反。」","sentenceOrder":181},
  {"id":"s_work_han_thu_76_182","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「請於黃門供養馬之事。」","sentenceOrder":182},
  {"id":"s_work_han_thu_76_183","chapterId":"ch_work_han_thu_76","textTraditional":"稍遷，會東郡盜賊起，拜為東郡都尉。上以壽王為都尉，不復置太守。是時，軍旅數發，年歲不熟，多盜賊。詔賜壽王璽書曰：「子在朕前之時，知略輻湊，〔一〕以為天下少雙，海內寡二。及至連十餘城之守，任四千石之重，〔二〕職事並廢，盜賊從橫，〔三〕甚不稱在前時，何也？」壽王謝罪，因言其狀。","sentenceOrder":183},
  {"id":"s_work_han_thu_76_184","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「言其無方而至，若車輪之歸於轂。」","sentenceOrder":184},
  {"id":"s_work_han_thu_76_185","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「郡守、都尉皆二千石，以壽王為都尉，不置太守，兼總二任，故云四千石也。」","sentenceOrder":185},
  {"id":"s_work_han_thu_76_186","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「從音子庸反。」","sentenceOrder":186},
  {"id":"s_work_han_thu_76_187","chapterId":"ch_work_han_thu_76","textTraditional":"後徵入為光祿大夫侍中。丞相公孫弘奏言「民不得挾弓弩。十賊彍弩，百吏不敢前，〔一〕盜賊不輒伏辜，免脫者眾，害寡而利多，此盜賊所以蕃也。〔二〕禁民不得挾弓弩，則盜賊執短兵，短兵接則眾者勝。以眾吏捕寡賊，其勢必得。盜賊有害無利，則莫犯法，刑錯之道也。臣愚以為禁民毋得挾弓弩便。」上下其議。壽王對曰：","sentenceOrder":187},
  {"id":"s_work_han_thu_76_188","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　張晏曰：「彍音郭。」師古曰：「引滿曰彍。」","sentenceOrder":188},
  {"id":"s_work_han_thu_76_189","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「蕃亦多也，音扶元反。」","sentenceOrder":189},
  {"id":"s_work_han_thu_76_190","chapterId":"ch_work_han_thu_76","textTraditional":"臣聞古者作五兵，非以相害，以禁暴討邪也。〔一〕安居則以制猛獸而備非常，有事則以設守衛而施行陣。及至周室衰微，上無明王，諸侯力政，彊侵弱，眾暴寡，海內抏敝，〔二〕（是以）巧詐並生。〔是以〕知者陷愚，勇者威怯，苟以得勝為務，不顧義理。故機變械飾，所以相賊害之具不可勝數。於是秦兼天下，廢王道，立私議，滅詩書而首法令，〔三〕去仁恩而任刑戮，〔四〕墮名城，殺豪桀，〔五〕銷甲兵，折鋒刃。其後，民以耰鉏箠梃相撻擊，〔六〕犯法滋眾，盜賊不勝，〔七〕至於赭衣塞路，群盜滿山，卒以亂亡。故聖王務教化而省禁防，知其不足恃也。","sentenceOrder":190},
  {"id":"s_work_han_thu_76_191","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「五兵謂矛、戟、弓、劍、戈。」","sentenceOrder":191},
  {"id":"s_work_han_thu_76_192","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「抏，訛盡也，音五官反。」","sentenceOrder":192},
  {"id":"s_work_han_thu_76_193","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「以法令為首。」","sentenceOrder":193},
  {"id":"s_work_han_thu_76_194","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「去，除也。」","sentenceOrder":194},
  {"id":"s_work_han_thu_76_195","chapterId":"ch_work_han_thu_76","textTraditional":"〔五〕　師古曰：「墮，毀也，音火規反。」","sentenceOrder":195},
  {"id":"s_work_han_thu_76_196","chapterId":"ch_work_han_thu_76","textTraditional":"〔六〕　師古曰：「耰，摩田之器也。箠，馬檛也。梃，大杖也。耰音憂。箠音之累反。梃音大鼎反。」","sentenceOrder":196},
  {"id":"s_work_han_thu_76_197","chapterId":"ch_work_han_thu_76","textTraditional":"〔七〕　師古曰：「滋，益也。不勝，言不可勝也。」","sentenceOrder":197},
  {"id":"s_work_han_thu_76_198","chapterId":"ch_work_han_thu_76","textTraditional":"今陛下昭明德，建太平，舉俊材，興學官，三公有司或由窮巷，起白屋，裂地而封，〔一〕宇內日化，方外鄉風，〔二〕然而盜賊猶有者，郡國二千石之罪，非挾弓弩之過也。禮曰男子生，桑弧蓬矢以舉之，明示有事也。〔三〕孔子曰：「吾何執？執射乎？」〔四〕大射之禮，自天子降及庶人，三代之道也。詩云「大侯既抗，弓矢斯張，射夫既同，獻爾發功」，〔五〕言貴中也。〔六〕愚聞聖王合射以明教矣，未聞弓矢之為禁也。且所為禁者，為盜賊之以攻奪也。攻奪之罪死，然而不止者，大姦之於重誅固不避也。臣恐邪人挾之而吏不能止，良民以自備而抵法禁，〔七〕是擅賊威而奪民救也。〔八〕竊以為無益於禁姦，而廢先王之典，使學者不得習行其禮，大不便。","sentenceOrder":198},
  {"id":"s_work_han_thu_76_199","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「白屋，以白茅覆屋也。壽王言此者，並以譏公孫弘。」","sentenceOrder":199},
  {"id":"s_work_han_thu_76_200","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":200},
  {"id":"s_work_han_thu_76_201","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「有四方扞禦之事。」","sentenceOrder":201},
  {"id":"s_work_han_thu_76_202","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「論語載孔子之言。」","sentenceOrder":202},
  {"id":"s_work_han_thu_76_203","chapterId":"ch_work_han_thu_76","textTraditional":"〔五〕　師古曰：「小雅賓之初筵之詩也。侯，所以居的，以皮為之。天子射豹侯，諸侯射熊侯，卿大夫射麋侯，士射鹿豕侯。抗，舉也。射夫，眾射者也。同，同耦也。言既舉大侯，又張弓矢，分耦而射，則獻其發矢中的之功也。」","sentenceOrder":203},
  {"id":"s_work_han_thu_76_204","chapterId":"ch_work_han_thu_76","textTraditional":"〔六〕　師古曰：「中音竹仲反。」","sentenceOrder":204},
  {"id":"s_work_han_thu_76_205","chapterId":"ch_work_han_thu_76","textTraditional":"〔七〕　師古曰：「抵，觸也。」","sentenceOrder":205},
  {"id":"s_work_han_thu_76_206","chapterId":"ch_work_han_thu_76","textTraditional":"〔八〕　師古曰：「擅，專也。」","sentenceOrder":206},
  {"id":"s_work_han_thu_76_207","chapterId":"ch_work_han_thu_76","textTraditional":"書奏，上以難丞相弘。弘詘服焉。","sentenceOrder":207},
  {"id":"s_work_han_thu_76_208","chapterId":"ch_work_han_thu_76","textTraditional":"及汾陰得寶鼎，武帝嘉之，薦見宗廟，臧於甘泉宮。群臣皆上壽賀曰：「陛下得周鼎。」壽王獨曰非周鼎。上聞之，召而問之，曰：「今朕得周鼎，群臣皆以為然，壽王獨以為非，何也？有說則可，無說則死。」壽王對曰：「臣安敢無說！臣聞周德始乎后稷，長於公劉，大於大王，〔一〕成於文武，顯於周公。德澤上昭，天下漏泉〔二〕，無所不通。上天報應，鼎為周出，故名曰周鼎。今漢自高祖繼周，亦昭德顯行，布恩施惠，六合和同。至於陛下，恢廓祖業，功德愈盛，天瑞並至，珍祥畢見。昔秦始皇親出鼎於彭城而不能得，天祚有德而寶鼎自出，此天之所以與漢，乃漢寶，非周寶〔也〕。」上曰：「善。」群臣皆稱萬歲。是日，賜壽王黃金十斤。後坐事誅。","sentenceOrder":208},
  {"id":"s_work_han_thu_76_209","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「公劉，后稷曾孫也。大王，文王之祖，則古公亶父也。」","sentenceOrder":209},
  {"id":"s_work_han_thu_76_210","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「昭，明也。漏，言潤澤下霑如屋之漏。」","sentenceOrder":210},
  {"id":"s_work_han_thu_76_211","chapterId":"ch_work_han_thu_76","textTraditional":"主父偃，齊國臨菑人也。學長短從橫術，〔一〕晚乃學易、春秋、百家之言。游齊諸子間，〔二〕諸儒生相與排儐，不（客）〔容〕於齊。家貧，假貣無所得，〔三〕北游燕、趙、中山，皆莫能厚，客甚困。以諸侯莫足游者，元光元年，乃西入關見衛將軍。〔四〕衛將軍數言上，上不省。資用乏，留久，諸侯賓客多厭之，乃上書闕下。朝奏，暮召入見。所言九事，其八事為律令，一事諫伐匈奴，曰：","sentenceOrder":211},
  {"id":"s_work_han_thu_76_212","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　服虔曰：「蘇秦法百家書說也。」師古曰：「長短解在張湯傳。從橫說在藝文志。」","sentenceOrder":212},
  {"id":"s_work_han_thu_76_213","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「諸子，諸侯王子。」","sentenceOrder":213},
  {"id":"s_work_han_thu_76_214","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「貣音土得反。」","sentenceOrder":214},
  {"id":"s_work_han_thu_76_215","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「衛青。」","sentenceOrder":215},
  {"id":"s_work_han_thu_76_216","chapterId":"ch_work_han_thu_76","textTraditional":"臣聞明主不惡切諫以博觀，忠臣不避重誅以直諫，是故事無遺策而功流萬世。今臣不敢隱忠避死，以效愚計，願陛下幸赦而少察之。","sentenceOrder":216},
  {"id":"s_work_han_thu_76_217","chapterId":"ch_work_han_thu_76","textTraditional":"司馬法曰：「國雖大，好戰必亡；天下雖平，忘戰必危。」〔一〕天下既平，天子大愷，〔二〕春蒐秋獮，諸侯春振旅，秋治兵，所以不忘戰也。〔三〕且怒者逆德也，兵者凶器也，爭者末節也。古之人君一怒必伏尸流血，故聖王重行之。〔四〕夫務戰勝，窮武事，未有不悔者也。","sentenceOrder":217},
  {"id":"s_work_han_thu_76_218","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「司馬穰苴善用兵，著書言兵法，謂之司馬法。一說司馬，古主兵之官，有軍陳用兵之法。」","sentenceOrder":218},
  {"id":"s_work_han_thu_76_219","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　應劭曰：「大愷，周禮還師振旅之樂也。」","sentenceOrder":219},
  {"id":"s_work_han_thu_76_220","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「春為陽中，其行木也；秋為陰中，其行金也。金、木，兵器所資，故於此時蒐獮治兵也。蒐，蒐索也，取不孕者。獮，應殺氣也。振，整；旅，眾也。獮音先淺反。」","sentenceOrder":220},
  {"id":"s_work_han_thu_76_221","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「重，難也。」","sentenceOrder":221},
  {"id":"s_work_han_thu_76_222","chapterId":"ch_work_han_thu_76","textTraditional":"昔秦皇帝任戰勝之威，蠶食天下，并吞戰國，海內為一，功齊三代。務勝不休，欲攻匈奴，李斯諫曰：「不可。夫匈奴無城郭之居，委積之守，遷徙鳥舉，難得而制。輕兵深入，糧食必絕；運糧以行，重不及事。得其地，不足以為利；得其民，不可調而守也。〔一〕勝必棄之，非民父母。靡敝中國，甘心匈奴，〔二〕非完計也。」秦皇帝不聽，遂使蒙恬將兵而攻胡，卻地千里，以河為境。地固澤鹵，不生五穀，〔三〕然後發天下丁男以守北河。暴兵露師十有餘年，死者不可勝數，終不能踰河而北。是豈人眾之不足，兵革之不備哉？其勢不可也。又使天下飛芻輓粟，〔四〕起於黃、腄、琅邪負海之郡，轉輸北河，〔五〕率三十鍾而致一石。〔六〕男子疾耕不足於糧餉，〔七〕女子紡績不足於帷幕。百姓靡敝，孤寡老弱不能相養，道死者相望，〔八〕蓋天下始叛也。","sentenceOrder":222},
  {"id":"s_work_han_thu_76_223","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　李奇曰：「不可和調也。」","sentenceOrder":223},
  {"id":"s_work_han_thu_76_224","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「靡，散也，音縻。其下類此。」","sentenceOrder":224},
  {"id":"s_work_han_thu_76_225","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「地多沮澤而鹹鹵。」","sentenceOrder":225},
  {"id":"s_work_han_thu_76_226","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「運載芻槁，令其疾至，故曰飛芻也。輓謂引車船也，音晚。」","sentenceOrder":226},
  {"id":"s_work_han_thu_76_227","chapterId":"ch_work_han_thu_76","textTraditional":"〔五〕　師古曰：「黃、腄，二縣名也，並在東萊。言自東萊及琅邪緣海諸郡，皆令轉輸至北河也。腄音直瑞反，又音誰。」","sentenceOrder":227},
  {"id":"s_work_han_thu_76_228","chapterId":"ch_work_han_thu_76","textTraditional":"〔六〕　師古曰：「六斛四斗為鍾。計其道路所費，凡用百九十二斛，乃得一石至。」","sentenceOrder":228},
  {"id":"s_work_han_thu_76_229","chapterId":"ch_work_han_thu_76","textTraditional":"〔七〕　師古曰：「餉亦饟字。」","sentenceOrder":229},
  {"id":"s_work_han_thu_76_230","chapterId":"ch_work_han_thu_76","textTraditional":"〔八〕　師古曰：「道死謂死於路也。」","sentenceOrder":230},
  {"id":"s_work_han_thu_76_231","chapterId":"ch_work_han_thu_76","textTraditional":"及至高皇帝定天下，略地於邊，聞匈奴聚代谷之外而欲擊之。御史成諫曰：「不可。夫匈奴，獸聚而鳥散，從之如搏景，〔一〕今以陛下盛德攻匈奴，臣竊危之。」高帝不聽，遂至代谷，果有平城之圍。高帝悔之，乃使劉敬往結和親，然後天下亡干戈之事。","sentenceOrder":231},
  {"id":"s_work_han_thu_76_232","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「搏，擊也。搏人之陰景，言不可得也。」","sentenceOrder":232},
  {"id":"s_work_han_thu_76_233","chapterId":"ch_work_han_thu_76","textTraditional":"故兵法曰：「興師十萬，日費千金。」秦常積眾數十萬人，雖有覆軍殺將，係虜單于，〔一〕適足以結怨深讎，不足以償天下之費。夫匈奴行盜侵敺，所以為業，天性固然。〔二〕上自虞夏殷周，固不程督，〔三〕禽獸畜之，不比為人。夫不上觀虞夏殷周之統，而下循近世之失，此臣之所以大恐，百姓所疾苦也。且夫兵久則變生，事苦則慮易。〔四〕使邊境之民靡敝愁苦，將吏相疑而外市，〔五〕故尉佗、章邯得成其私，〔六〕而秦政不行，權分二子，此得失之效也。故周書曰：「安危在出令，存亡在所用。」〔七〕願陛下孰計之而加察焉。","sentenceOrder":233},
  {"id":"s_work_han_thu_76_234","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「覆音芳目反。」","sentenceOrder":234},
  {"id":"s_work_han_thu_76_235","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「來侵邊境而〈區夂〉略人畜也。〈區夂〉與驅同，其字從夂，音普木反。」","sentenceOrder":235},
  {"id":"s_work_han_thu_76_236","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「程，課也。督，視責也。」","sentenceOrder":236},
  {"id":"s_work_han_thu_76_237","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「言思慮變易，失其常也。」","sentenceOrder":237},
  {"id":"s_work_han_thu_76_238","chapterId":"ch_work_han_thu_76","textTraditional":"〔五〕　張晏曰：「與外國交市己利，若章邯之比也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_76_239","chapterId":"ch_work_han_thu_76","textTraditional":"〔六〕　師古曰：「佗音徒何反。」","sentenceOrder":239},
  {"id":"s_work_han_thu_76_240","chapterId":"ch_work_han_thu_76","textTraditional":"〔七〕　師古曰：「此周書者，本尚書之餘。」","sentenceOrder":240},
  {"id":"s_work_han_thu_76_241","chapterId":"ch_work_han_thu_76","textTraditional":"是時，徐樂、嚴安亦俱上書言世務。書奏，上召見三人，謂曰：「公皆安在？何相見之晚也！」〔一〕乃拜偃、樂、安皆為郎中。偃數上疏言事，遷謁者，中郎，中大夫。歲中四遷。","sentenceOrder":241},
  {"id":"s_work_han_thu_76_242","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「言皆者，各在何處。」","sentenceOrder":242},
  {"id":"s_work_han_thu_76_243","chapterId":"ch_work_han_thu_76","textTraditional":"偃說上曰：「古者諸侯地不過百里，彊弱之形易制。今諸侯或連城數十，地方千里，緩則驕奢易為淫亂，急則阻其彊而合從〔一〕以逆京師。今以法割削，則逆節萌起，〔一〕前日朝錯是也。今諸侯子弟或十數，而適嗣代立，〔三〕餘雖骨肉，無尺地之封，則仁孝之道不宣。願陛下令諸侯得推恩分子弟，以地侯之。彼人人喜得所願，上以德施，實分其國，必稍自銷弱矣。」於是上從其計。又說上曰：「茂陵初立，天下豪桀兼并之家，亂眾民，皆可徙茂陵，內實京師，外銷姦猾，此所謂不誅而害除。」上又從之。","sentenceOrder":243},
  {"id":"s_work_han_thu_76_244","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「從音子容反。」","sentenceOrder":244},
  {"id":"s_work_han_thu_76_245","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「萌謂事之始生，如草木之萌芽也。」","sentenceOrder":245},
  {"id":"s_work_han_thu_76_246","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「適讀曰嫡。」","sentenceOrder":246},
  {"id":"s_work_han_thu_76_247","chapterId":"ch_work_han_thu_76","textTraditional":"尊立衛皇后及發燕王定國陰事，偃有功焉。大臣皆畏其口，賂遺累千金。或說偃曰：「大橫！」〔一〕偃曰：「臣結髮游學四十餘年，身不得遂，〔二〕親不以為子，昆弟不收，賓客棄我，我阨日久矣。丈夫生不五鼎食，死則五鼎亨耳！〔三〕吾日暮，故倒行逆施之。」〔四〕","sentenceOrder":247},
  {"id":"s_work_han_thu_76_248","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「橫音胡孟反。」","sentenceOrder":248},
  {"id":"s_work_han_thu_76_249","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「遂猶達也。」","sentenceOrder":249},
  {"id":"s_work_han_thu_76_250","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　張晏曰：「五鼎食，牛、羊、豕、魚，麋也。諸侯五，卿大夫三。」師古曰：「五鼎亨之，謂被鑊亨之誅。」","sentenceOrder":250},
  {"id":"s_work_han_thu_76_251","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「暮言年齒老也。倒行逆施，謂不遵常理。此語本出五子胥，偃述而稱之。」","sentenceOrder":251},
  {"id":"s_work_han_thu_76_252","chapterId":"ch_work_han_thu_76","textTraditional":"偃盛言朔方地肥饒，外阻河，蒙恬築城以逐匈奴，內省轉輸戍漕，廣中國，滅胡之本也。上覽其說，下公卿議，皆言不便。公孫弘曰：「秦時嘗發三十萬眾築北河，終不可就，〔一〕已而棄之。」朱買臣難詘弘，遂置朔方，本偃計也。","sentenceOrder":252},
  {"id":"s_work_han_thu_76_253","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「就，成也。」","sentenceOrder":253},
  {"id":"s_work_han_thu_76_254","chapterId":"ch_work_han_thu_76","textTraditional":"元朔中，偃言齊王內有淫失之行，〔一〕上拜偃為齊相。至齊，遍召昆弟賓客，散五百金予之，數曰：〔二〕「始吾貧時，昆弟不我衣食，賓客不我內門，〔三〕今吾相齊，諸君迎我或千里。吾與諸君絕矣，毋復入偃之門！」乃使人以王與姊姦事動王。王以為終不得脫，恐效燕王論死，乃自殺。","sentenceOrder":254},
  {"id":"s_work_han_thu_76_255","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「失讀曰佚，音尹一反。」","sentenceOrder":255},
  {"id":"s_work_han_thu_76_256","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「數，責也。數音所具反。」","sentenceOrder":256},
  {"id":"s_work_han_thu_76_257","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「衣音於既反。食讀曰飤。內門，謂內之於門中也。」","sentenceOrder":257},
  {"id":"s_work_han_thu_76_258","chapterId":"ch_work_han_thu_76","textTraditional":"偃始為布衣時，嘗游燕、趙，及其貴，發燕事。趙王恐其為國患，欲上書言其陰事，為居中，不敢發。及其為齊相，出關，即使人上書，告偃受諸侯金，以故諸侯子多以得封者。及齊王以自殺聞，上大怒，以為偃劫其王令自殺，乃徵下吏治。偃服受諸侯之金，實不劫齊王令自殺。上欲勿誅，公孫弘爭曰：「齊王自殺無後，國除為郡，入漢，偃本首惡，非誅偃無以謝天下。」乃遂族偃。","sentenceOrder":258},
  {"id":"s_work_han_thu_76_259","chapterId":"ch_work_han_thu_76","textTraditional":"偃方貴幸時，客以千數，及族死，無一人視，獨孔車收葬焉。上聞之，以車為長者。","sentenceOrder":259},
  {"id":"s_work_han_thu_76_260","chapterId":"ch_work_han_thu_76","textTraditional":"徐樂，燕（郡）無終人也。上書曰：","sentenceOrder":260},
  {"id":"s_work_han_thu_76_261","chapterId":"ch_work_han_thu_76","textTraditional":"臣聞天下之患，在於土崩，不在瓦解，古今一也。","sentenceOrder":261},
  {"id":"s_work_han_thu_76_262","chapterId":"ch_work_han_thu_76","textTraditional":"何謂土崩？秦之末世是也。陳涉無千乘之尊，尺土之地，身非王公大人名族之後，〔無〕鄉曲之譽，非有孔、曾、墨子之賢，陶朱、猗頓之富也。然起窮巷，奮棘矜，〔一〕偏袒大呼，天下從風，〔二〕此其故何也？由民困而主不恤，下怨而上不知，俗已亂而政不修，此三者陳涉之所以為資也。此之謂土崩。故曰天下之患在乎土崩。","sentenceOrder":262},
  {"id":"s_work_han_thu_76_263","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「棘，戟也。矜者，戟之把也。時秦銷兵器，故但有戟之把耳。矜音巨巾反。此下亦同。」","sentenceOrder":263},
  {"id":"s_work_han_thu_76_264","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「呼音火故反。」","sentenceOrder":264},
  {"id":"s_work_han_thu_76_265","chapterId":"ch_work_han_thu_76","textTraditional":"何謂瓦解？吳、楚、齊、趙之兵是也。七國謀為大逆，號皆稱萬乘之君，帶甲數十萬，威足以嚴其境內，財足以勸其士民，然不能西攘尺寸之地，〔一〕而身為禽於中原者，此其故何也？非權輕於匹夫而兵弱於陳涉也，當是之時先帝之德未衰，而安土樂俗之民眾，故諸侯無竟外之助。〔二〕此之謂瓦解。故曰天下之患不在瓦解。","sentenceOrder":265},
  {"id":"s_work_han_thu_76_266","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「攘謂侵取漢地。」","sentenceOrder":266},
  {"id":"s_work_han_thu_76_267","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「竟讀曰境。其下同。」","sentenceOrder":267},
  {"id":"s_work_han_thu_76_268","chapterId":"ch_work_han_thu_76","textTraditional":"由此觀之，天下誠有土崩之勢，雖布衣窮處之士或首難而危海內，〔一〕陳涉是也，況三晉之君或存乎？〔二〕天下雖未治也，誠能無土崩之勢，雖有彊國勁兵，不得還踵而身為禽，〔三〕吳楚是也，況群臣百姓，能為亂乎？此二體者，安危之明要，賢主之所留意而深察也。","sentenceOrder":268},
  {"id":"s_work_han_thu_76_269","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「首難謂首唱而作難也。」","sentenceOrder":269},
  {"id":"s_work_han_thu_76_270","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「韓、趙、魏三國本共分晉，故稱三晉。」","sentenceOrder":270},
  {"id":"s_work_han_thu_76_271","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「還讀曰旋。」","sentenceOrder":271},
  {"id":"s_work_han_thu_76_272","chapterId":"ch_work_han_thu_76","textTraditional":"間者，關東五穀數不登，年歲未復，〔一〕民多窮困，重之以邊境之事，〔二〕推數循理而觀之，民宜有不安其處者矣。不安故易動，易動者，土崩之勢也。故賢主獨觀萬化之原，明於安危之機，修之廟堂之上，而銷未形之患也。其要，期使天下無土崩之勢而已矣。故雖有彊國勁兵，陛下逐走獸，射飛鳥，弘游燕之囿，淫從恣之觀，極馳騁之樂，自若。〔三〕金石絲竹之聲不絕於耳，帷幄之私俳優朱儒之笑不乏於前，而天下無宿憂。〔四〕名何必夏、子，俗何必成、康！〔五〕雖然，臣竊以為陛下天然之質，寬仁之資，而誠以天下為務，則禹、湯之名不難侔，而成、康之俗未必不復興也。〔六〕此二體者立，然後處尊安之實，揚廣譽於當世，親天下而服四夷，餘恩遺德為數世隆，南面背依攝袂而揖王公，〔七〕此陛下之所服也〔八〕。臣聞圖王不成，其敝足以安。〔九〕安則陛下何求而不得，何威而不成，奚征而不服哉？〔一０〕","sentenceOrder":272},
  {"id":"s_work_han_thu_76_273","chapterId":"ch_work_han_thu_76","textTraditional":"〔一〕　師古曰：「復音扶目反。」","sentenceOrder":273},
  {"id":"s_work_han_thu_76_274","chapterId":"ch_work_han_thu_76","textTraditional":"〔二〕　師古曰：「重音直用反。」","sentenceOrder":274},
  {"id":"s_work_han_thu_76_275","chapterId":"ch_work_han_thu_76","textTraditional":"〔三〕　師古曰：「自若者，言如其常，無所廢損也。從讀曰縱。」","sentenceOrder":275},
  {"id":"s_work_han_thu_76_276","chapterId":"ch_work_han_thu_76","textTraditional":"〔四〕　師古曰：「宿，久也。」","sentenceOrder":276},
  {"id":"s_work_han_thu_76_277","chapterId":"ch_work_han_thu_76","textTraditional":"〔五〕　服虔曰：「夏，禹也。子，湯也。湯，子姓。」","sentenceOrder":277},
  {"id":"s_work_han_thu_76_278","chapterId":"ch_work_han_thu_76","textTraditional":"〔六〕　師古曰：「侔，等也。」","sentenceOrder":278},
  {"id":"s_work_han_thu_76_279","chapterId":"ch_work_han_thu_76","textTraditional":"〔七〕　師古曰：「依讀曰扆。已解於上。」","sentenceOrder":279},
  {"id":"s_work_han_thu_76_280","chapterId":"ch_work_han_thu_76","textTraditional":"〔八〕　師古曰：「服，事也。」","sentenceOrder":280},
  {"id":"s_work_han_thu_76_281","chapterId":"ch_work_han_thu_76","textTraditional":"〔九〕　師古曰：「言其敝末之法，猶足自安也。」","sentenceOrder":281},
  {"id":"s_work_han_thu_76_282","chapterId":"ch_work_han_thu_76","textTraditional":"〔一０〕〔師古曰：「奚，何也。」〕","sentenceOrder":282},
  {"id":"s_work_han_thu_76_283","chapterId":"ch_work_han_thu_76","textTraditional":"校勘記","sentenceOrder":283},
  {"id":"s_work_han_thu_76_284","chapterId":"ch_work_han_thu_76","textTraditional":"二七七七頁　五行　自以〔沒〕身不見兵革。　錢大昭說，「自以」下脫「沒」字。按景祐、殿本都有「沒」字。","sentenceOrder":284},
  {"id":"s_work_han_thu_76_285","chapterId":"ch_work_han_thu_76","textTraditional":"二七七七頁一三行　（晉）〔張〕說是也。　景祐、殿本都作「張」。王先謙說作「張」是。","sentenceOrder":285},
  {"id":"s_work_han_thu_76_286","chapterId":"ch_work_han_thu_76","textTraditional":"二七七八頁　四行　而居九州之（地）〔內〕也。　景祐、殿本都作「內」。王先謙說作「內」是。","sentenceOrder":286},
  {"id":"s_work_han_thu_76_287","chapterId":"ch_work_han_thu_76","textTraditional":"二七七八頁一二行　其不（可）用天子之法度，　景祐、殿本都無「可」字。","sentenceOrder":287},
  {"id":"s_work_han_thu_76_288","chapterId":"ch_work_han_thu_76","textTraditional":"二七八０頁　二行　復音（拱）〔扶〕目反。　景祐、殿本都作「扶」，此誤。","sentenceOrder":288},
  {"id":"s_work_han_thu_76_289","chapterId":"ch_work_han_thu_76","textTraditional":"二七八三頁　二行　男子不得耕稼（種樹）〔樹種〕，　景祐、殿本都作「樹種」。","sentenceOrder":289},
  {"id":"s_work_han_thu_76_290","chapterId":"ch_work_han_thu_76","textTraditional":"二七八三頁一六行　曠日（持）〔引〕久，士卒勞倦，越（乃）出擊之。　景祐本「持」作「引」，「越」下無「乃」字。","sentenceOrder":290},
  {"id":"s_work_han_thu_76_291","chapterId":"ch_work_han_thu_76","textTraditional":"二七八四頁　一行　行者不還，往者（果）〔莫〕反，　景祐、汲古、殿、局本都作「莫」，此誤。","sentenceOrder":291},
  {"id":"s_work_han_thu_76_292","chapterId":"ch_work_han_thu_76","textTraditional":"二七八四頁一二行　言莫敢（挍）〔校〕也。　景祐、汲古、殿、局本都作「校」，注同。","sentenceOrder":292},
  {"id":"s_work_han_thu_76_293","chapterId":"ch_work_han_thu_76","textTraditional":"二七八四頁一二行　如使越人蒙（死）徼幸以逆執事之顏行，　景祐本無「死」字。","sentenceOrder":293},
  {"id":"s_work_han_thu_76_294","chapterId":"ch_work_han_thu_76","textTraditional":"二七八四頁一四行　八（蔬）〔藪〕為囿，江（海）〔漢〕為池，　景祐、殿本「蔬」都作「藪」，「海」都作「漢」。","sentenceOrder":294},
  {"id":"s_work_han_thu_76_295","chapterId":"ch_work_han_thu_76","textTraditional":"二七八六頁　七行　〔未〕踰領，　宋祁說，一本「踰」上有「未」字。王念孫說一本是。","sentenceOrder":295},
  {"id":"s_work_han_thu_76_296","chapterId":"ch_work_han_thu_76","textTraditional":"二七八六頁一二行　夙興夜（昧）〔寐〕，　景祐、殿本都作「寐」。王先謙說作「寐」是。","sentenceOrder":296},
  {"id":"s_work_han_thu_76_297","chapterId":"ch_work_han_thu_76","textTraditional":"二七八八頁　三行　因其弱弟餘善以成其（謀）〔誅〕。　殿本作「誅」。王先謙說殿本是。","sentenceOrder":297},
  {"id":"s_work_han_thu_76_298","chapterId":"ch_work_han_thu_76","textTraditional":"二七九０頁一三行　（令）〔今〕躬自欲入奉也。　景祐本作「今」。殿本「躬」作「助」。","sentenceOrder":298},
  {"id":"s_work_han_thu_76_299","chapterId":"ch_work_han_thu_76","textTraditional":"二七九二頁一五行　其故人素輕買臣者入〔內〕視之，　王念孫說景祐本有「內」字是。","sentenceOrder":299},
  {"id":"s_work_han_thu_76_300","chapterId":"ch_work_han_thu_76","textTraditional":"二七九六頁　二行　（是以）巧詐並生，〔是以〕知者陷愚，　景祐、殿本「是以」二字都在「巧詐並生」下。","sentenceOrder":300},
  {"id":"s_work_han_thu_76_301","chapterId":"ch_work_han_thu_76","textTraditional":"二七九八頁　六行　乃漢寶，非周寶〔也〕。　景祐、殿本都有「也」字。","sentenceOrder":301},
  {"id":"s_work_han_thu_76_302","chapterId":"ch_work_han_thu_76","textTraditional":"二七九八頁一一行　不（客）〔容〕於齊。　錢大昭說「客」疑當作「容」。按景祐、殿本都作「容」，史記同。","sentenceOrder":302},
  {"id":"s_work_han_thu_76_303","chapterId":"ch_work_han_thu_76","textTraditional":"二八０四頁一０行　徐樂，燕（郡）無終人也。　景祐本無「郡」字。王念孫、王先謙都說燕是國名，「郡」字不當有。","sentenceOrder":303},
  {"id":"s_work_han_thu_76_304","chapterId":"ch_work_han_thu_76","textTraditional":"二八０四頁一三行　〔無〕鄉曲之譽，　王念孫說史記有「無」字，此脫，則文義不明。","sentenceOrder":304},
  {"id":"s_work_han_thu_76_305","chapterId":"ch_work_han_thu_76","textTraditional":"二八０七頁　六行　〔師古曰：「奚，何也。」〕　景祐、殿本都有此注。","sentenceOrder":305},
  {"id":"s_work_han_thu_77_1","chapterId":"ch_work_han_thu_77","textTraditional":"師古曰：「此卷首尚載嚴、朱、吾丘、主父、徐者，存其本書題目，以示不變易也。」","sentenceOrder":1},
  {"id":"s_work_han_thu_77_2","chapterId":"ch_work_han_thu_77","textTraditional":"嚴安者，臨菑人也。以故丞相史上書，曰：","sentenceOrder":2},
  {"id":"s_work_han_thu_77_3","chapterId":"ch_work_han_thu_77","textTraditional":"臣聞鄒（衍）〔子〕曰：〔一〕「政教文質者，所以云救也，〔二〕當時則用，過則舍之，〔三〕有易則易（也）〔之〕，〔四〕故守一而不變者，未睹治之至也。」今天下人民用財侈靡，車馬衣裘宮室皆競修飾，調五聲使有節族，〔五〕雜五色使有文章，重五味方丈於前，以觀欲天下。〔六〕彼民之情，見美則願之，是教民以侈也。侈而無節，則不可贍，〔七〕民離本而徼末矣。〔八〕末不可徒得，〔九〕故搢紳者不憚為詐，帶劍者夸殺人以矯奪，〔一０〕而世不知媿，故姦軌浸長。〔一一〕夫佳麗珍怪固順於耳目，故養失而泰，樂失而淫，禮失而采，〔一二〕教失而偽。偽、采、淫、泰，非所以範民之道也。〔一三〕是以天下人民逐利無已，犯法者眾。臣願為民制度以防其淫，使貧富不相燿以和其心。心既和平，其性恬安。恬安不營，則盜賊銷；盜賊銷，則刑罰少；刑罰少，則陰陽和，四時正，風雨時，草木暢茂，五穀蕃孰，六畜遂字，〔一四〕民不夭厲，和之至也。〔一五〕","sentenceOrder":3},
  {"id":"s_work_han_thu_77_4","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「鄒衍之書也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_77_5","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「以救敝。」","sentenceOrder":5},
  {"id":"s_work_han_thu_77_6","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「非其時則廢置也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_77_7","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「可變易者則易也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_77_8","chapterId":"ch_work_han_thu_77","textTraditional":"〔五〕　蘇林曰：「族音奏。」師古曰：「節，止也。奏，進也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_77_9","chapterId":"ch_work_han_thu_77","textTraditional":"〔六〕　孟康曰：「觀猶顯也。」師古曰：「顯示之，使其慕欲也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_77_10","chapterId":"ch_work_han_thu_77","textTraditional":"〔七〕　師古曰：「贍，足也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_77_11","chapterId":"ch_work_han_thu_77","textTraditional":"〔八〕　師古曰：「徼，要求也，音工堯反。」","sentenceOrder":11},
  {"id":"s_work_han_thu_77_12","chapterId":"ch_work_han_thu_77","textTraditional":"〔九〕　師古曰：「徒，空也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_77_13","chapterId":"ch_work_han_thu_77","textTraditional":"〔一０〕師古曰：「夸，大也，競也。矯，偽也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_77_14","chapterId":"ch_work_han_thu_77","textTraditional":"〔一一〕師古曰：「浸，漸也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_77_15","chapterId":"ch_work_han_thu_77","textTraditional":"〔一二〕如淳曰：「采，飾也。」師古曰：「采者，文過其實也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_77_16","chapterId":"ch_work_han_thu_77","textTraditional":"〔一三〕師古曰：「範謂為之立法也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_77_17","chapterId":"ch_work_han_thu_77","textTraditional":"〔一四〕師古曰：「蕃，多也。遂，成也。字，生也。蕃音扶元反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_77_18","chapterId":"ch_work_han_thu_77","textTraditional":"〔一五〕師古曰：「厲，病也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_77_19","chapterId":"ch_work_han_thu_77","textTraditional":"臣聞周有天下，其治三百餘歲，成康其隆也，刑錯四十餘年而不用。及其衰，亦三百餘年，故五伯更起。〔一〕伯者，常佐天子興利除害，誅暴禁邪，匡正海內，以尊天子。五伯既沒，賢聖莫續，天子孤弱，號令不行。諸侯恣行，彊陵弱，眾暴寡。田常篡齊，六卿分晉，並為戰國，此民之始苦也。於是彊國務攻，弱國修守，合從連衡，馳車轂擊，〔二〕介冑生蟣蝨，民無所告愬。","sentenceOrder":19},
  {"id":"s_work_han_thu_77_20","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「伯讀曰霸。（晉）〔更〕音工衡反。以下並同。」","sentenceOrder":20},
  {"id":"s_work_han_thu_77_21","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「車轂相擊，言其眾多也。從音子容反。」","sentenceOrder":21},
  {"id":"s_work_han_thu_77_22","chapterId":"ch_work_han_thu_77","textTraditional":"及至秦王，蠶食天下，并吞戰國，稱號皇帝，一海內之政，壞諸侯之城。銷其兵，鑄以為鍾虡，〔一〕示不復用。元元黎民得免於戰國，逢明天子，人人自以為更生。〔二〕鄉使秦緩刑罰，薄賦斂，〔三〕省繇役，貴仁義，賤權利，上篤厚，下佞巧，變風易俗，化於海內，則世世必安矣。秦不行是風，循其故俗，為知巧權利者進，篤厚忠正者退，法嚴令苛，諂諛者眾，〔四〕（曰）〔日〕聞其美，（章）〔意〕廣心逸。欲威海外，使蒙恬將兵以北攻彊胡，辟地進境，〔五〕戍於北河，飛芻輓粟以隨其後。又使尉屠睢將樓船之士攻越，使監祿鑿渠運糧，深入越地，越人遁逃。曠日持久，糧食乏絕，越人擊之，秦兵大敗。秦乃使尉佗將卒以戍越。當是時，秦禍北構於胡，南挂於越，〔六〕宿兵於無用之地，〔七〕進而不得退。行十餘年，丁男被甲，丁女轉輸，苦不聊生，自經於道樹，死者相望。及秦皇帝崩，天下大畔。陳勝、吳廣舉陳，〔八〕武臣、張耳舉趙，項梁舉吳，田儋舉齊，景駒舉郢，周市舉魏，韓廣舉燕，窮山通谷，豪士並起，不可勝載也。然本皆非公侯之後，非長官之吏，〔九〕無尺寸之勢，起閭巷，杖棘矜，應時而動，不謀而俱起，不約而同會，壤長地進，至乎伯王，〔一０〕時教使然也。秦貴為天子，富有天下，滅世絕祀，窮兵之禍也。故周失之弱，秦失之彊，不變之患也。","sentenceOrder":22},
  {"id":"s_work_han_thu_77_23","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「虡，懸鍾者也。解在賈山、司馬相如傳。」","sentenceOrder":23},
  {"id":"s_work_han_thu_77_24","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「言天下既免戰國之苦，若逢明聖之主則可以更生，而秦皇反為虐政以殘害也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_77_25","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":25},
  {"id":"s_work_han_thu_77_26","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「讇，古諂字。」","sentenceOrder":26},
  {"id":"s_work_han_thu_77_27","chapterId":"ch_work_han_thu_77","textTraditional":"〔五〕　師古曰：「辟讀曰闢。」","sentenceOrder":27},
  {"id":"s_work_han_thu_77_28","chapterId":"ch_work_han_thu_77","textTraditional":"〔六〕　師古曰：「挂，懸也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_77_29","chapterId":"ch_work_han_thu_77","textTraditional":"〔七〕　師古曰：「宿，留也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_77_30","chapterId":"ch_work_han_thu_77","textTraditional":"〔八〕　師古曰：「舉謂起兵也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_77_31","chapterId":"ch_work_han_thu_77","textTraditional":"〔九〕　師古曰：「長官謂一官之長也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_77_32","chapterId":"ch_work_han_thu_77","textTraditional":"〔一０〕張晏曰：「長，進益也。」師古曰：「言其稍稍攻伐，進益土境，以至彊大也。長音竹兩反。伯讀曰霸。」","sentenceOrder":32},
  {"id":"s_work_han_thu_77_33","chapterId":"ch_work_han_thu_77","textTraditional":"今徇南夷，朝夜郎，降羌僰，略薉州，建城邑，〔一〕深入匈奴，燔其龍城，〔二〕議者美之。此人臣之利，非天下之長策也。今中國無狗吠之警，而外累於遠方之備，靡敝國家，〔三〕非所以子民也。〔四〕行無窮之欲，甘心快意，結怨於匈奴，非所以安邊也。禍挐而不解，兵休而復起，〔五〕近者愁苦，遠者驚駭，非所以持久也。今天下鍛甲摩劍，矯箭控弦，〔六〕轉輸軍糧，未見休時，此天下所共憂也。夫兵久而變起，事煩而慮生。今外郡之地或幾千里〔七〕，列城數十，形束壤制，〔八〕帶脅諸侯，〔九〕非宗室之利也。上觀齊晉所以亡，公室卑削，六卿大盛也；下覽秦之所以滅，刑嚴文刻，欲大無窮也。今郡守之權非特六卿之重也，地幾千里非特閭巷之資也，甲兵器械非特棘矜之用也，以逢萬世之變，則不可勝諱也〔一０〕。","sentenceOrder":33},
  {"id":"s_work_han_thu_77_34","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　張晏曰：「薉，貉也。」師古曰：「薉與穢同。」","sentenceOrder":34},
  {"id":"s_work_han_thu_77_35","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「燔，燒也。龍城，匈奴祭天處。燔音扶元反。」","sentenceOrder":35},
  {"id":"s_work_han_thu_77_36","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「累音力瑞反。」","sentenceOrder":36},
  {"id":"s_work_han_thu_77_37","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「子謂養之如子也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_77_38","chapterId":"ch_work_han_thu_77","textTraditional":"〔五〕　師古曰：「挐，相連引也，音女居反。」","sentenceOrder":38},
  {"id":"s_work_han_thu_77_39","chapterId":"ch_work_han_thu_77","textTraditional":"〔六〕　師古曰：「矯，正曲使直也。控，引也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_77_40","chapterId":"ch_work_han_thu_77","textTraditional":"〔七〕　師古曰：「幾音鉅依反。次下亦同。」","sentenceOrder":40},
  {"id":"s_work_han_thu_77_41","chapterId":"ch_work_han_thu_77","textTraditional":"〔八〕　孟康曰：「言其土地形勢，足以束制其民。」","sentenceOrder":41},
  {"id":"s_work_han_thu_77_42","chapterId":"ch_work_han_thu_77","textTraditional":"〔九〕　師古曰：「帶者，言諸侯之於郡守，譬若佩帶，謂輕小也。脅謂其威力足以脅之也。一曰帶在脅旁，附著之義也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_77_43","chapterId":"ch_work_han_thu_77","textTraditional":"〔一０〕師古曰：「言不可盡諱者，言必滅亡也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_77_44","chapterId":"ch_work_han_thu_77","textTraditional":"後以安為騎馬令。〔一〕","sentenceOrder":44},
  {"id":"s_work_han_thu_77_45","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「主天子之騎馬也。騎音其寄反。」","sentenceOrder":45},
  {"id":"s_work_han_thu_77_46","chapterId":"ch_work_han_thu_77","textTraditional":"終軍字子雲，濟南人也。少好學，以辯博能屬文聞於郡中。〔一〕年十八，選為博士弟子。至府受遣，〔二〕太守聞其有異材，召見軍，甚奇之，與交結。軍揖太守而去，至長安上書言事。武帝異其文，拜軍為謁者給事中。","sentenceOrder":46},
  {"id":"s_work_han_thu_77_47","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「屬音之欲反。」","sentenceOrder":47},
  {"id":"s_work_han_thu_77_48","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「博士弟子屬太常。受遣者，由郡遣詣京師。」","sentenceOrder":48},
  {"id":"s_work_han_thu_77_49","chapterId":"ch_work_han_thu_77","textTraditional":"從上幸雍祠五畤，獲白麟，一角而五蹄。〔一〕時又得奇木，其枝旁出，輒復合於木上。上異此二物，博謀群臣。〔二〕軍上對曰：","sentenceOrder":49},
  {"id":"s_work_han_thu_77_50","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「每一足有五蹄也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_77_51","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「訪其徵應也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_77_52","chapterId":"ch_work_han_thu_77","textTraditional":"臣聞詩頌君德，樂舞后功，異經而同指，明盛德之所隆也。南越竄屏葭葦，與鳥魚群，〔一〕正朔不及其俗。有司臨境，而東甌內附，閩王伏辜，南越賴救。北胡隨畜薦居，〔二〕禽獸行，虎狼心，上古未能攝。大將軍秉鉞，單于奔幕；〔三〕票騎抗旌，昆邪右衽。〔四〕是澤南洽而威北暢也。〔五〕若罰不阿近，舉不遺遠，設官俟賢，縣賞待功，〔六〕能者進以保祿，罷者退而勞力，〔七〕刑於宇內矣。〔八〕履眾美而不足，懷聖明而不專，〔九〕建三宮之文質，章厥職之所宜，〔一０〕封禪之君無聞焉。〔一一〕","sentenceOrder":52},
  {"id":"s_work_han_thu_77_53","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「葭，蘆也，成長則曰葦。葭音加。」","sentenceOrder":53},
  {"id":"s_work_han_thu_77_54","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　蘇林曰：「薦，草也。」師古曰：「蘇說非也。薦讀曰荐。荐，屢也。言隨畜牧屢易故居，不安住也。左傳『戎狄荐居』者也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_77_55","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「犇，古奔字。」","sentenceOrder":55},
  {"id":"s_work_han_thu_77_56","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「抗，舉也。右衽，從中國化也。昆音下門反。」","sentenceOrder":56},
  {"id":"s_work_han_thu_77_57","chapterId":"ch_work_han_thu_77","textTraditional":"〔五〕　師古曰：「洽，溥也。暢，達也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_77_58","chapterId":"ch_work_han_thu_77","textTraditional":"〔六〕　師古曰：「俟，古俟字。次下亦同。」","sentenceOrder":58},
  {"id":"s_work_han_thu_77_59","chapterId":"ch_work_han_thu_77","textTraditional":"〔七〕　師古曰：「罷讀曰疲，謂不堪職任者也。勞力，歸農畝也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_77_60","chapterId":"ch_work_han_thu_77","textTraditional":"〔八〕　師古曰：「刑，法也，言成法於宇內也。一曰，刑，見也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_77_61","chapterId":"ch_work_han_thu_77","textTraditional":"〔九〕　師古曰：「言自謙也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_77_62","chapterId":"ch_work_han_thu_77","textTraditional":"〔一０〕服虔曰：「三宮，明堂、辟雍、靈臺也。」鄭氏曰：「於三宮班政教，有文質者也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_77_63","chapterId":"ch_work_han_thu_77","textTraditional":"〔一一〕張晏曰：「前世封禪之君不聞若斯之美也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_77_64","chapterId":"ch_work_han_thu_77","textTraditional":"夫（人）〔天〕命初定，萬事草創，〔一〕及臻六合同風，九州共貫，必待明聖潤色，祖業傳於無窮。〔二〕故周至成王，然後制定，而休徵之應見。〔三〕陛下盛日月之光，垂聖思於勒成，專神明之敬，奉燔瘞於郊宮，〔四〕獻享之精交神，積和之氣塞明，〔五〕而異獸來獲，宜矣。昔武王中流未濟，白魚入於王舟，俯取以燎，群公咸曰「休哉！」〔六〕今郊祀未見於神祇，而獲獸以饋，〔七〕此天之所以示饗，而上通之符合也。宜因昭時令日，改定告元，〔八〕苴（以）白茅於江淮，發嘉號于營丘，以應緝熙，〔九〕使著事者有紀焉。〔一０〕","sentenceOrder":64},
  {"id":"s_work_han_thu_77_65","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「謂始受命之君也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_77_66","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「潤色謂光飾之。」","sentenceOrder":66},
  {"id":"s_work_han_thu_77_67","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「休，美也。徵，證也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_77_68","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「燔，祭天也。瘞，祭地也。祭天則燒之，祭地則薶之。郊宮，謂泰畤及后土也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_77_69","chapterId":"ch_work_han_thu_77","textTraditional":"〔五〕　師古曰：「塞，荅也。明者，明靈，亦謂神也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_77_70","chapterId":"ch_work_han_thu_77","textTraditional":"〔六〕　師古曰：「謂伐紂時。解在董仲舒傳。」","sentenceOrder":70},
  {"id":"s_work_han_thu_77_71","chapterId":"ch_work_han_thu_77","textTraditional":"〔七〕　師古曰：「以饋謂充祭俎也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_77_72","chapterId":"ch_work_han_thu_77","textTraditional":"〔八〕　張晏曰：「改元年以告神祇也。」師古曰：「昭，明也。令，善也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_77_73","chapterId":"ch_work_han_thu_77","textTraditional":"〔九〕　服虔曰：「苴，作席也。」張晏曰：「江淮職貢三脊茅為藉也。」孟康曰：「嘉號，封禪也。泰山在齊分野，故曰營丘也。或曰登封泰山以明姓號也。」師古曰：「苴音祖，又音子豫反。非苞苴之苴也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_77_74","chapterId":"ch_work_han_thu_77","textTraditional":"〔一０〕師古曰：「謂史官也。紀，記也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_77_75","chapterId":"ch_work_han_thu_77","textTraditional":"蓋六鶂退飛，逆也；〔一〕白魚登舟，順也。〔二〕夫明闇之徵，上亂飛鳥，下動淵魚，〔三〕各以類推。今野獸并角，明同本也；〔四〕眾支內附，示無外也。若此之應，殆將有解編髮，削左衽，襲冠帶，要衣裳，而蒙化者焉。〔五〕斯拱而俟之耳！〔六〕","sentenceOrder":75},
  {"id":"s_work_han_thu_77_76","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　張晏曰：「六鶂退飛，象諸侯畔逆，宋襄公伯道退也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_77_77","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　張晏曰：「周，木德也。舟，木也。殷，水德。魚，水物。魚躍登舟，象諸侯順周，以紂畀武王也。」臣瓚曰：「時論者未以周為木殷為水也。謂武王伐殷而魚入王舟，象征而必獲，故曰順也。」師古曰：「瓚說是也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_77_78","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「亂，變也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_77_79","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「并，合也。獸皆兩角，今此獨一，故云并也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_77_80","chapterId":"ch_work_han_thu_77","textTraditional":"〔五〕　師古曰：「要衣裳謂著中國之衣裳也。編讀曰辮。要音一遙反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_77_81","chapterId":"ch_work_han_thu_77","textTraditional":"〔六〕　師古曰：「拱手而待之，言其即至。」","sentenceOrder":81},
  {"id":"s_work_han_thu_77_82","chapterId":"ch_work_han_thu_77","textTraditional":"對奏，上甚異之，由是改元為元狩。後數月，越地及匈奴名王有率眾來降者，時皆以軍言為中。〔一〕","sentenceOrder":82},
  {"id":"s_work_han_thu_77_83","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「中音竹仲反。」","sentenceOrder":83},
  {"id":"s_work_han_thu_77_84","chapterId":"ch_work_han_thu_77","textTraditional":"元鼎中，博士徐偃使行風俗。〔一〕偃矯制，〔二〕使膠東、魯國鼓鑄鹽鐵。〔三〕還，奏事，徙為太常丞。御史大夫張湯劾偃矯制大害，法至死。偃以為春秋之義，大夫出疆，有可以安社稷，存萬民，顓之可也。〔四〕湯以致其法，不能詘其義。有詔下軍問狀，軍詰偃曰：「古者諸侯國異俗分，百里不通，時有聘會之事，安危之勢，呼吸成變，故有不受辭造命顓己之宜；今天下為一，萬里同風，故春秋『王者無外』。偃巡封域之中，稱以出疆何也？且鹽鐵，郡有餘臧，〔五〕正二國廢，國家不足以為利害，而以安社稷存萬民為辭，何也？」又詰偃：「膠東南近琅邪，北接北海，魯國西枕泰山，東有東海，受其鹽鐵。偃度四郡口數田地，〔六〕率其用器食鹽，不足以并給二郡邪？將勢宜有餘，而吏不能也？何以言之？偃矯制而鼓鑄者，欲及春耕種贍民器也。〔七〕今魯國之鼓，當先具其備，〔八〕至秋乃能舉火。此言與實反者非？〔九〕偃已前三奏，無詔，〔一０〕不惟所為不許，〔一一〕而直矯作威福，以從民望，干名采譽，〔一二〕此明聖所必加誅也。『枉尺直尋』，孟子稱其不可；〔一三〕今所犯罪重，所就者小，〔一四〕偃自予必死而為之邪？〔一五〕將幸誅不加，欲以采名也？」〔一六〕偃窮詘，服罪當死。軍奏「偃矯制顓行，非奉使體，請下御史徵偃即罪。」〔一七〕奏可。上善其詰，有詔示御史大夫。","sentenceOrder":84},
  {"id":"s_work_han_thu_77_85","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「行音下更反。」","sentenceOrder":85},
  {"id":"s_work_han_thu_77_86","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「矯，託也。託言受詔也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_77_87","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　如淳曰：「鑄銅鐵，扇熾火，謂之鼓。」","sentenceOrder":87},
  {"id":"s_work_han_thu_77_88","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「顓與專同。下亦類此。」","sentenceOrder":88},
  {"id":"s_work_han_thu_77_89","chapterId":"ch_work_han_thu_77","textTraditional":"〔五〕　師古曰：「先有畜積。」","sentenceOrder":89},
  {"id":"s_work_han_thu_77_90","chapterId":"ch_work_han_thu_77","textTraditional":"〔六〕　師古曰：「度，計也，音大各反。」","sentenceOrder":90},
  {"id":"s_work_han_thu_77_91","chapterId":"ch_work_han_thu_77","textTraditional":"〔七〕　師古曰：「贍，足也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_77_92","chapterId":"ch_work_han_thu_77","textTraditional":"〔八〕　師古曰：「備者猶今言調度。」","sentenceOrder":92},
  {"id":"s_work_han_thu_77_93","chapterId":"ch_work_han_thu_77","textTraditional":"〔九〕　師古曰：「重問之。」","sentenceOrder":93},
  {"id":"s_work_han_thu_77_94","chapterId":"ch_work_han_thu_77","textTraditional":"〔一０〕師古曰：「不報聽也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_77_95","chapterId":"ch_work_han_thu_77","textTraditional":"〔一一〕師古曰：「惟，思也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_77_96","chapterId":"ch_work_han_thu_77","textTraditional":"〔一二〕師古曰：「干，求也。采，取也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_77_97","chapterId":"ch_work_han_thu_77","textTraditional":"〔一三〕師古曰：「孟子，孟軻也。八尺曰尋。孟子之書曰陳代問於孟子曰：『枉尺直尋，若可為也。』孟子曰：『子過矣。枉己者未有能直人者也。』尋長而尺短。故陳代言所直者多，而所曲者少，則可為之。孟子以為苟有小曲，則害於大直，故不可也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_77_98","chapterId":"ch_work_han_thu_77","textTraditional":"〔一四〕師古曰：「就，成也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_77_99","chapterId":"ch_work_han_thu_77","textTraditional":"〔一五〕師古曰：「予，許也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_77_100","chapterId":"ch_work_han_thu_77","textTraditional":"〔一六〕師古曰：「幸，冀也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_77_101","chapterId":"ch_work_han_thu_77","textTraditional":"〔一七〕師古曰：「徵，召也。即，就也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_77_102","chapterId":"ch_work_han_thu_77","textTraditional":"初，軍從濟南當詣博士，步入關，關吏予軍繻。〔一〕軍問：「以此何為？」吏曰；「為復傳，〔二〕還當以合符。」軍曰：「大丈夫西游，終不復傳還。」棄繻而去。軍為謁者，使行郡國，〔三〕建節東出關，關吏識之，曰：「此使者乃前棄繻生也。」軍行郡國，所見便宜以聞。還奏事，上甚說。〔四〕","sentenceOrder":102},
  {"id":"s_work_han_thu_77_103","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　張晏曰：「繻音須。繻，符也。書帛裂而分之，若券契矣。」蘇林曰：「繻，帛邊也。舊關出入皆以傳。傳（須）〔煩〕，因裂繻頭合以為符信也。」師古曰：「蘇說是也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_77_104","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「復，返也。謂返出關更以為傳。復音扶福反。傳音張戀反。次下亦同。」","sentenceOrder":104},
  {"id":"s_work_han_thu_77_105","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「行音下更反。其後亦同。」","sentenceOrder":105},
  {"id":"s_work_han_thu_77_106","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「說讀曰悅。」","sentenceOrder":106},
  {"id":"s_work_han_thu_77_107","chapterId":"ch_work_han_thu_77","textTraditional":"當發使（使）匈奴，〔一〕軍自請曰：「軍無橫草之功，〔二〕得列宿衛，食祿五年。邊境時有風塵之警，臣宜被堅執銳，當矢石，啟前行。〔三〕駑下不習金革之事，今聞將遣匈奴使者，臣願盡精厲氣，奉佐明使，畫吉凶於單于之前。臣年少材下，孤於外官，〔四〕不足以亢一方之任，〔五〕竊不勝憤懣。」詔問畫吉凶之狀，上奇軍對，擢為諫大夫。","sentenceOrder":107},
  {"id":"s_work_han_thu_77_108","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「漢朝欲遣人為使於匈奴也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_77_109","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「言行草中，使草偃臥，故云橫草也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_77_110","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「行音下郎反。」","sentenceOrder":110},
  {"id":"s_work_han_thu_77_111","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「孤，遠也。外官謂非侍衛之臣也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_77_112","chapterId":"ch_work_han_thu_77","textTraditional":"〔五〕　師古曰：「亢，當也，音抗。」","sentenceOrder":112},
  {"id":"s_work_han_thu_77_113","chapterId":"ch_work_han_thu_77","textTraditional":"南越與漢和親，乃遣軍使南越，說其王，欲令入朝，比內諸侯。軍自請：「願受長纓，必羈南越王而致之闕下。」〔一〕軍遂往說越王，越王聽許，請舉國內屬。天子大說，〔二〕賜南越大臣印綬，壹用漢法，以新改其俗，令使者留填撫之。〔三〕越相呂嘉不欲內屬，發兵攻殺其王，及漢使者皆死。語在南越傳。軍死時年二十餘，故世謂之「終童」。","sentenceOrder":113},
  {"id":"s_work_han_thu_77_114","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「言如馬羈也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_77_115","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":115},
  {"id":"s_work_han_thu_77_116","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「填音竹刃反。」","sentenceOrder":116},
  {"id":"s_work_han_thu_77_117","chapterId":"ch_work_han_thu_77","textTraditional":"王褒字子淵，蜀人也。宣帝時修武帝故事，講論六藝群書，博盡奇異之好，徵能為楚辭九江被公，〔一〕召見誦讀，益召高材劉向、張子僑、華龍、柳褒等待詔金馬門。〔二〕神爵、五鳳之間，天下殷（當）〔富〕，數有嘉應。上頗作歌詩，欲興協律之事，丞相魏相奏言知音善鼓雅琴者渤海趙定、梁國龔德，皆召見待詔。於是益州刺史王襄欲宣風化於眾庶，聞王褒有俊材，請與相見，使褒作中和、樂職、宣布詩，〔三〕選好事者令依鹿鳴之聲習而歌之。時氾鄉侯何武為僮子，選在歌中。〔四〕久之，武等學長安，歌太學下，轉而上聞。宣帝召見武等觀之，皆賜帛，謂曰：「此盛德之事，吾何足以當之！」","sentenceOrder":117},
  {"id":"s_work_han_thu_77_118","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「被，姓也，音皮義反。」","sentenceOrder":118},
  {"id":"s_work_han_thu_77_119","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「華音戶化反。」","sentenceOrder":119},
  {"id":"s_work_han_thu_77_120","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「中和者，言政治和平也。樂職者，言百官各得其職也。宣布者，風化普洽，無所不被。」","sentenceOrder":120},
  {"id":"s_work_han_thu_77_121","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「氾音凡。」","sentenceOrder":121},
  {"id":"s_work_han_thu_77_122","chapterId":"ch_work_han_thu_77","textTraditional":"褒既為刺史作頌，〔一〕又作其傳，〔二〕益州刺史因奏褒有軼材。〔三〕上乃徵褒。既至，詔褎為聖主得賢臣頌其意。褒對曰：","sentenceOrder":122},
  {"id":"s_work_han_thu_77_123","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「即上中和、樂職、宣布詩也。以美盛德，故謂之頌也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_77_124","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「解釋頌歌之義及作者之意。」","sentenceOrder":124},
  {"id":"s_work_han_thu_77_125","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「軼與逸同。」","sentenceOrder":125},
  {"id":"s_work_han_thu_77_126","chapterId":"ch_work_han_thu_77","textTraditional":"夫荷旃被毳者，難與道純綿之麗密；〔一〕羹（黎）〔藜〕唅糗者，不足與論太牢之滋味。〔二〕今臣辟在西蜀，〔三〕生於窮巷之中，長於蓬茨之下，〔四〕無有游觀廣覽之知，顧有至愚極陋之累，〔五〕不足以塞厚望，應明指。〔六〕雖然，敢不略陳愚而抒情素！〔七〕","sentenceOrder":126},
  {"id":"s_work_han_thu_77_127","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「純，絲也。」謂織為繒帛之麗，絲纊之密也。一說，純綿，不雜綿也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_77_128","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　服虔曰：「唅音含。」師古曰：「糗即今之熬米麥所為者，音丘九反，又音昌少反。」","sentenceOrder":128},
  {"id":"s_work_han_thu_77_129","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「辟讀曰僻。」","sentenceOrder":129},
  {"id":"s_work_han_thu_77_130","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「蓬茨，以蓬蓋屋也。茨音才私反。」","sentenceOrder":130},
  {"id":"s_work_han_thu_77_131","chapterId":"ch_work_han_thu_77","textTraditional":"〔五〕　師古曰：「顧猶反也。累音力瑞反。」","sentenceOrder":131},
  {"id":"s_work_han_thu_77_132","chapterId":"ch_work_han_thu_77","textTraditional":"〔六〕　師古曰：「塞，當也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_77_133","chapterId":"ch_work_han_thu_77","textTraditional":"〔七〕　師古曰：「抒猶泄也，音食汝反。」","sentenceOrder":133},
  {"id":"s_work_han_thu_77_134","chapterId":"ch_work_han_thu_77","textTraditional":"記曰：共惟春秋五始之要，〔一〕在乎審己正統而已。夫賢者，國家之器用也。所任賢，則趨舍省而功施普；〔二〕器用利，則用力少而就效眾。故工人之用鈍器也，勞筋苦骨，終日矻矻。〔三〕及至巧冶鑄干將之樸，清水焠其鋒，〔四〕越砥斂其咢，〔五〕水斷蛟龍，陸剸犀革，〔六〕忽若彗氾畫塗。〔七〕如此，則使離婁督繩，公輸削墨，〔八〕雖崇臺五增，延袤百丈，而不溷者，工用相得也。〔九〕庸人之御駑馬，亦傷吻敝策而不進於行，〔一０〕匈喘膚汗，人極馬倦。及至駕齧膝，驂乘旦，〔一一〕王良執靶，〔一二〕韓哀附輿，〔一三〕縱馳騁騖，忽如景靡，〔一四〕過都越國，蹶如歷塊；〔一五〕追奔電，逐遺風，〔一六〕周流八極，萬里壹息。何其遼哉？人馬相得也。〔一七〕故服絺綌之涼者，不苦盛暑之鬱燠〔一八〕；襲貂狐之煗者，不憂至寒之悽愴。〔一九〕何則？有其具者易其備。賢人君子，亦聖（主）〔王〕之所以易海內也。是以嘔喻受之，〔二０〕開寬裕之路，以延天下英俊也。〔二一〕夫竭知附賢者，必建仁策；索人求士者，必樹伯跡。〔二二〕昔周公躬吐捉之勞，故有圉空之隆；〔二三〕齊桓設庭燎之禮，故有匡合之功。〔二四〕由此觀之，君人者勤於求賢而逸於得人。〔二五〕","sentenceOrder":134},
  {"id":"s_work_han_thu_77_135","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　服虔曰：「共，敬也。」張晏曰：「要，春秋稱『元年春王正月』，此五始也。」師古曰：「元者氣之始，春者四時之始，王者受命之始，正月者政教之始，公即位者一國之始，是為五始。共讀曰恭。」","sentenceOrder":135},
  {"id":"s_work_han_thu_77_136","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「趨讀曰趣。普，博也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_77_137","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　應劭曰：「矻矻，勞極貌。」如淳曰：「健作貌也。」師古曰：「如說是也。矻音口骨反。」","sentenceOrder":137},
  {"id":"s_work_han_thu_77_138","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「焠謂（堯）〔燒〕而內水中以堅之也。鋒，刃芒端也。焠音千內反。」","sentenceOrder":138},
  {"id":"s_work_han_thu_77_139","chapterId":"ch_work_han_thu_77","textTraditional":"〔五〕　晉灼曰：「砥（百）〔石〕出南昌，故曰越也。」師古曰：「咢，刃旁也，音五各反。」","sentenceOrder":139},
  {"id":"s_work_han_thu_77_140","chapterId":"ch_work_han_thu_77","textTraditional":"〔六〕　師古曰：「剸，截也，音之兗反，又音徒官反。」","sentenceOrder":140},
  {"id":"s_work_han_thu_77_141","chapterId":"ch_work_han_thu_77","textTraditional":"〔七〕　師古曰：「彗，帚也。氾，氾灑地也。塗，泥也。如以帚埽氾灑之地，以刀畫泥中，言其易。」","sentenceOrder":141},
  {"id":"s_work_han_thu_77_142","chapterId":"ch_work_han_thu_77","textTraditional":"〔八〕　張晏曰：「離婁，黃帝時明目者也。」應劭曰：「公輸，魯般，性巧者也。」師古曰：「督，察視也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_77_143","chapterId":"ch_work_han_thu_77","textTraditional":"〔九〕　師古曰：「溷，亂也，音胡頓反。」","sentenceOrder":143},
  {"id":"s_work_han_thu_77_144","chapterId":"ch_work_han_thu_77","textTraditional":"〔一０〕師古曰：「吻，口角也。策，所以擊馬也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_77_145","chapterId":"ch_work_han_thu_77","textTraditional":"〔一一〕孟康曰：「良馬低頭，口至膝，故曰齧膝。」張晏曰：「駕則旦至，故曰乘旦。」師古曰：「乘音食證反。」","sentenceOrder":145},
  {"id":"s_work_han_thu_77_146","chapterId":"ch_work_han_thu_77","textTraditional":"〔一二〕張晏曰：「王良，郵無恤，字伯樂。」晉灼曰：「靶音霸，謂轡也。」師古曰：「參驗左氏傳及國語、孟子，郵無恤、郵良、劉無止、王良，總一人也。楚辭云『驥躊躇於敝輦，遇孫陽而得代』。王逸云孫陽，伯樂姓名也。列子云伯樂，秦穆公時人。考其年代不相當，張說云良字伯樂，斯失之矣。」","sentenceOrder":146},
  {"id":"s_work_han_thu_77_147","chapterId":"ch_work_han_thu_77","textTraditional":"〔一三〕應劭曰：「世本『韓哀作御』。」師古曰：「宋衷云韓哀，韓文侯也。時已有御，此復言作者，加其精巧也。然則善御者耳，非始作也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_77_148","chapterId":"ch_work_han_thu_77","textTraditional":"〔一四〕師古曰：「亂馳曰騖。景靡者，如光景之徙靡也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_77_149","chapterId":"ch_work_han_thu_77","textTraditional":"〔一五〕師古曰：「如經歷一塊，言其（起）〔速〕疾之甚。塊音口內反。」","sentenceOrder":149},
  {"id":"s_work_han_thu_77_150","chapterId":"ch_work_han_thu_77","textTraditional":"〔一六〕師古曰：「呂氏春秋云『遺風之乘』，言馬行尤疾，每在風前，故遺風於後。今此言逐遺風，則是風之遺逸在後者，馬能逐及也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_77_151","chapterId":"ch_work_han_thu_77","textTraditional":"〔一七〕師古曰：「遼謂所行遠。」","sentenceOrder":151},
  {"id":"s_work_han_thu_77_152","chapterId":"ch_work_han_thu_77","textTraditional":"〔一八〕師古曰：「鬱，熱氣也。燠，溫也，音於六反。」","sentenceOrder":152},
  {"id":"s_work_han_thu_77_153","chapterId":"ch_work_han_thu_77","textTraditional":"〔一九〕師古曰：「悽愴，寒冷也。煗音乃短反。」","sentenceOrder":153},
  {"id":"s_work_han_thu_77_154","chapterId":"ch_work_han_thu_77","textTraditional":"〔二０〕應劭曰：「嘔喻，和悅貌。」師古曰：「嘔音於付反。」","sentenceOrder":154},
  {"id":"s_work_han_thu_77_155","chapterId":"ch_work_han_thu_77","textTraditional":"〔二一〕師古曰：「裕，饒也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_77_156","chapterId":"ch_work_han_thu_77","textTraditional":"〔二二〕師古曰：「伯讀曰霸。」","sentenceOrder":156},
  {"id":"s_work_han_thu_77_157","chapterId":"ch_work_han_thu_77","textTraditional":"〔二三〕師古曰：「一飯三吐飡，一沐三捉髮，以賓賢士，故能成太平之化，刑措不用，囹圄空虛也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_77_158","chapterId":"ch_work_han_thu_77","textTraditional":"〔二四〕應劭曰：「有以九九求見桓公，桓公不納。其人曰：『九九小術，而君不納之，況大於九九者乎！』於是桓公設庭燎之禮而見之。居無幾，隰朋自遠而至，齊桓（逐）〔遂〕以霸。」師古曰：「九九，計數之書，若今算經也。匡謂一匡天下也。合謂九合諸侯。」","sentenceOrder":158},
  {"id":"s_work_han_thu_77_159","chapterId":"ch_work_han_thu_77","textTraditional":"〔二五〕師古曰：「逸，閒也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_77_160","chapterId":"ch_work_han_thu_77","textTraditional":"人臣亦然。昔賢者之未遭遇也，圖事揆策則君不用其謀，陳見悃誠則上不然其信，〔一〕進仕不得施效，斥逐又非其愆。是故伊尹勤於鼎俎，太公困於鼓刀，〔二〕百里自鬻，甯子飯牛，〔三〕離此患也。〔四〕及其遇明君遭聖主也，運籌合上意，諫諍即見聽，進退得關其忠，任職得行其術，去卑辱奧渫而升本朝，〔五〕離疏釋蹻而享膏粱，〔六〕剖符錫壤而光祖考，傳之子孫，以資說士。〔七〕故世必有聖知之君，而後有賢明之臣。故虎嘯而（冽風）〔風冽〕，〔八〕龍興而致雲，蟋蟀俟秋吟，蜉蝤出以陰。〔九〕易曰：「飛龍在天，利見大人。」〔一０〕詩曰：「思皇多士，生此王國。」〔一一〕故世平主聖，俊艾將自至，〔一二〕若堯、舜、禹、湯、文、武之君，獲稷、契、皋陶、伊尹、呂望，〔一三〕明明在朝，穆穆列布，〔一四〕聚精會神，相得益章。〔一五〕雖伯牙操遞鍾，〔一六〕逢門子彎烏號，〔一七〕猶未足以喻其意也。","sentenceOrder":160},
  {"id":"s_work_han_thu_77_161","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「悃，至也，音口本反。」","sentenceOrder":161},
  {"id":"s_work_han_thu_77_162","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「勤於鼎俎，謂負鼎俎以干湯也。鼓刀，謂屠牛於朝歌也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_77_163","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「鬻，賣也。呂氏春秋云百里奚之未遇時也，虞亡而虜縳，鬻以五羊之皮。公孫枝得而悅之，獻諸穆公。飯牛，解在鄒陽傳。鬻音弋六反。」","sentenceOrder":163},
  {"id":"s_work_han_thu_77_164","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「離，遭也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_77_165","chapterId":"ch_work_han_thu_77","textTraditional":"〔五〕　張晏曰：「奧，幽也。渫，狎也，汙也。言敝奧渫汙，不章顯也。」師古曰：「渫音先列反。」","sentenceOrder":165},
  {"id":"s_work_han_thu_77_166","chapterId":"ch_work_han_thu_77","textTraditional":"〔六〕　應劭曰：「離此疏食，釋此木蹻也。」臣瓚曰：「以繩為蹻也。」師古曰：「蹻（自）〔即〕今之鞋耳。瓚說是也。蹻音居略反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_77_167","chapterId":"ch_work_han_thu_77","textTraditional":"〔七〕　師古曰：「談說（也）〔之〕士傳以為資也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_77_168","chapterId":"ch_work_han_thu_77","textTraditional":"〔八〕　師古曰：「冽冽，風貌也，音列。」","sentenceOrder":168},
  {"id":"s_work_han_thu_77_169","chapterId":"ch_work_han_thu_77","textTraditional":"〔九〕　孟康曰：「蜉蝤，渠略也。」師古曰：「蟋蟀，今之促織也。蜉蝤，甲（患）〔蟲〕也，好叢聚而生也，朝生而夕死。蝤音由，字亦作蝣，其音同也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_77_170","chapterId":"ch_work_han_thu_77","textTraditional":"〔一０〕師古曰：「乾卦九五爻辭也。言王者居正陽之位，賢才見之，則利用也。」","sentenceOrder":170},
  {"id":"s_work_han_thu_77_171","chapterId":"ch_work_han_thu_77","textTraditional":"〔一一〕師古曰：「大雅文王之詩也。思，語辭也。皇，美也。言美哉，此眾多賢士，生此周王之國也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_77_172","chapterId":"ch_work_han_thu_77","textTraditional":"〔一二〕師古曰：「艾讀曰乂。」","sentenceOrder":172},
  {"id":"s_work_han_thu_77_173","chapterId":"ch_work_han_thu_77","textTraditional":"〔一三〕師古曰：「契讀與卨同，字本作偰，後從省耳。」","sentenceOrder":173},
  {"id":"s_work_han_thu_77_174","chapterId":"ch_work_han_thu_77","textTraditional":"〔一四〕師古曰：「明明，察也。穆穆，美也。」","sentenceOrder":174},
  {"id":"s_work_han_thu_77_175","chapterId":"ch_work_han_thu_77","textTraditional":"〔一五〕師古曰：「章，明也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_77_176","chapterId":"ch_work_han_thu_77","textTraditional":"〔一六〕晉灼曰：「遞音遞迭之遞。二十四鍾各有節奏，擊之不常，故曰遞。」臣瓚曰：「楚辭云『奏伯牙之號鍾』。號鍾，琴名也。馬融笛賦曰『號鍾高調』。伯牙以善鼓琴，不聞說能擊鍾也。」師古曰：「琴名是也，字既作遞，則與楚辭不同，不得即讀為號，當依晉音耳。」","sentenceOrder":176},
  {"id":"s_work_han_thu_77_177","chapterId":"ch_work_han_thu_77","textTraditional":"〔一七〕師古曰：「逢門，善射者，即逢蒙也。烏號，弓名也。並解在前也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_77_178","chapterId":"ch_work_han_thu_77","textTraditional":"故聖主必待賢臣而弘功業，俊士亦俟明主以顯其德。上下俱欲，驩然交欣，千載壹合，論說無疑，翼乎如鴻毛過順風，沛乎如巨魚縱大壑。〔一〕其得意若此，則胡禁不止，曷令不行？〔二〕化溢四表，橫被無窮，遐夷貢獻，萬祥畢溱。〔三〕是以聖王不遍窺望而視已明，不單頃耳而聽已聰；〔四〕恩從祥風翱，德與和氣游，〔五〕太平之責塞，優游之望得；〔六〕遵遊自然之勢，恬淡無為之場，休徵自至，壽考無疆，雍容垂拱，永永萬年，何必偃卬詘信若彭祖，呴噓呼吸如僑、松，〔七〕眇然絕俗離世哉！〔八〕詩云「濟濟多士，文王以寧」，〔九〕蓋信乎其以寧也！","sentenceOrder":178},
  {"id":"s_work_han_thu_77_179","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「巨亦大也。沛音普大反。」","sentenceOrder":179},
  {"id":"s_work_han_thu_77_180","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「胡、曷皆何也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_77_181","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「溱字與臻同。」","sentenceOrder":181},
  {"id":"s_work_han_thu_77_182","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「單，盡極也。頃讀曰傾。」","sentenceOrder":182},
  {"id":"s_work_han_thu_77_183","chapterId":"ch_work_han_thu_77","textTraditional":"〔五〕　師古曰：「翱，翔也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_77_184","chapterId":"ch_work_han_thu_77","textTraditional":"〔六〕　師古曰：「塞，滿也。」","sentenceOrder":184},
  {"id":"s_work_han_thu_77_185","chapterId":"ch_work_han_thu_77","textTraditional":"〔七〕　如淳曰：「五帝紀彭祖，堯舜時人。列仙傳彭祖，殷大夫也，歷夏至商末，壽年七百。」師古曰：「信讀曰伸。呴噓，皆開口出氣也。僑，王僑，松，赤松子，皆仙人也。呴音許于反。噓音虛。」","sentenceOrder":185},
  {"id":"s_work_han_thu_77_186","chapterId":"ch_work_han_thu_77","textTraditional":"〔八〕　師古曰：「眇然，高遠之意也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_77_187","chapterId":"ch_work_han_thu_77","textTraditional":"〔九〕　師古曰：「亦文王之詩也。濟濟，盛貌也。言文王能多用賢人，故邦國得以安寧也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_77_188","chapterId":"ch_work_han_thu_77","textTraditional":"是時，上頗好神僊，故褒對及之。","sentenceOrder":188},
  {"id":"s_work_han_thu_77_189","chapterId":"ch_work_han_thu_77","textTraditional":"上令褒與張子僑等並待詔，數從褒等放獵，〔一〕所幸宮館，輒為歌頌，第其高下，以差賜帛。議者多以為淫靡不急，上曰：「『不有博弈者乎，為之猶賢乎已！』〔二〕辭賦大者與古詩同義，小者辯麗可喜。〔三〕辟如女工有綺縠，音樂有鄭衛，〔四〕今世俗猶皆以此虞說耳目，〔五〕辭賦比之，尚有仁義風諭，〔六〕鳥獸草木多聞之觀，賢於倡優博弈遠矣。」頃之，擢褒為諫大夫。","sentenceOrder":189},
  {"id":"s_work_han_thu_77_190","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「放，士眾大獵也，一曰游放及田獵。」","sentenceOrder":190},
  {"id":"s_work_han_thu_77_191","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「此論語載孔子之辭也。言博弈雖非道藝，無事為之，猶賢也。弈，今之圍（其）〔棋〕也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_77_192","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「喜，好也，音許吏反。」","sentenceOrder":192},
  {"id":"s_work_han_thu_77_193","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「辟讀曰譬。」","sentenceOrder":193},
  {"id":"s_work_han_thu_77_194","chapterId":"ch_work_han_thu_77","textTraditional":"〔五〕　師古曰：「虞與娛同。說讀曰悅。」","sentenceOrder":194},
  {"id":"s_work_han_thu_77_195","chapterId":"ch_work_han_thu_77","textTraditional":"〔六〕　師古曰：「風讀曰諷。」","sentenceOrder":195},
  {"id":"s_work_han_thu_77_196","chapterId":"ch_work_han_thu_77","textTraditional":"其後太子體不安，苦忽忽善忘，不樂。詔使褒等皆之太子宮虞侍太子，〔一〕朝夕誦讀奇文及所自造作。疾平復，乃歸。〔二〕太子喜褒所為甘泉及洞簫頌，〔三〕令後宮貴人左右皆誦讀之。","sentenceOrder":196},
  {"id":"s_work_han_thu_77_197","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「之，往也。」","sentenceOrder":197},
  {"id":"s_work_han_thu_77_198","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「復音扶目反。」","sentenceOrder":198},
  {"id":"s_work_han_thu_77_199","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「喜音許吏反。」","sentenceOrder":199},
  {"id":"s_work_han_thu_77_200","chapterId":"ch_work_han_thu_77","textTraditional":"後方士言益州有金馬碧雞之寶，可祭祀致也，宣帝使褒往祀焉。褒於道病死，上閔惜之。","sentenceOrder":200},
  {"id":"s_work_han_thu_77_201","chapterId":"ch_work_han_thu_77","textTraditional":"賈捐之字君房，賈誼之曾孫也。元帝初即位，上疏言得失，召待詔金馬門。","sentenceOrder":201},
  {"id":"s_work_han_thu_77_202","chapterId":"ch_work_han_thu_77","textTraditional":"初，武帝征南越，元封元年立儋耳、珠崖郡，皆在南方海中洲居，〔一〕廣袤可千里，〔二〕合十六縣，戶二萬三千餘。其民暴惡，自以阻絕，數犯吏禁，吏亦酷之，率數年壹反，殺吏，漢輒發兵擊定之。自初為郡至昭帝始元元年，二十餘年間，凡六反叛。至其五年，罷儋耳郡并屬珠崖。至宣帝神爵三年，珠崖三縣復反。反後七年，甘露元年，九縣反，輒發兵擊定之。元帝初元元年，珠崖又反，發兵擊之。諸縣更叛，連年不定。〔三〕上與有司議大發軍，捐之建議，以為不當擊。上使侍中駙馬都尉樂昌侯王商詰問捐之曰：「珠崖內屬為郡久矣，今背畔逆節，而云不當擊，長蠻夷之亂，虧先帝功德，經義何以處之？」〔四〕捐之對曰：","sentenceOrder":202},
  {"id":"s_work_han_thu_77_203","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「居海中之洲也。水中可居者曰洲。」","sentenceOrder":203},
  {"id":"s_work_han_thu_77_204","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「袤，長也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_77_205","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「更音工衡反。」","sentenceOrder":205},
  {"id":"s_work_han_thu_77_206","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「於六經之內，當何者之科條也。」","sentenceOrder":206},
  {"id":"s_work_han_thu_77_207","chapterId":"ch_work_han_thu_77","textTraditional":"臣幸得遭明盛之朝，蒙危言之策，無忌諱之患，〔一〕敢昧死竭卷卷。〔二〕","sentenceOrder":207},
  {"id":"s_work_han_thu_77_208","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「危言，直言也。言出而身危，故云危言。論語稱孔子曰：『邦有道，危言（行危）〔危行〕』。」","sentenceOrder":208},
  {"id":"s_work_han_thu_77_209","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「卷讀與拳同。」","sentenceOrder":209},
  {"id":"s_work_han_thu_77_210","chapterId":"ch_work_han_thu_77","textTraditional":"臣聞堯舜，聖之盛也，禹入聖域而不優，〔一〕故孔子稱堯曰「大哉」，韶曰「盡善」，禹曰「無間」。〔二〕以三聖之德，地方不過數千里，〔西〕被流沙，東漸于海，朔南暨聲教，迄于四海，〔三〕欲與聲教則治之，不欲與者不彊治也。〔四〕故君臣歌德〔五〕，含氣之物各（德）〔得〕其宜。武丁、成王，殷、周之大仁也，〔六〕然地東不過江、黃，西不過氐、羌，南不過蠻荊，北不過朔方。是以頌聲並作，視聽之類咸樂其生，越裳氏重九譯而獻，〔七〕此非兵革之所能致。及其衰也，南征不還，〔八〕齊桓捄其難，〔九〕孔子定其文。〔一０〕以至乎秦，興兵遠攻，貪外虛內，務欲廣地，不慮其害。然地南不過閩越，北不過太原，而天下潰畔，禍卒在於二世之末，〔一一〕長城之歌至今未絕。","sentenceOrder":210},
  {"id":"s_work_han_thu_77_211","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　臣瓚曰：「禹之功德，裁入聖人區域，但不能優泰耳。」","sentenceOrder":211},
  {"id":"s_work_han_thu_77_212","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「論語稱孔子曰『大哉，堯之為君也』，又曰『韶，盡美矣，又盡善也』，又曰『禹吾無間然矣』。韶，舜樂名。間音工莧反。」","sentenceOrder":212},
  {"id":"s_work_han_thu_77_213","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「此引禹貢之辭。漸，入也，一曰浸也。朔，北方也。暨，及也。迄，至也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_77_214","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「與讀曰豫。」","sentenceOrder":214},
  {"id":"s_work_han_thu_77_215","chapterId":"ch_work_han_thu_77","textTraditional":"〔五〕　師古曰：「言皆有德可歌頌。」","sentenceOrder":215},
  {"id":"s_work_han_thu_77_216","chapterId":"ch_work_han_thu_77","textTraditional":"〔六〕　師古曰：「武丁，殷之高宗。」","sentenceOrder":216},
  {"id":"s_work_han_thu_77_217","chapterId":"ch_work_han_thu_77","textTraditional":"〔七〕　晉灼曰：「遠國使來，因九譯言語乃通也。」張晏曰：「越不著衣裳，慕中國化，遣譯來著衣裳也，故曰越裳也。」師古曰：「張說非也。越裳自是國名，非以襲衣裳始為稱號。王充論衡作越嘗，此則不作衣裳之字明矣。」","sentenceOrder":217},
  {"id":"s_work_han_thu_77_218","chapterId":"ch_work_han_thu_77","textTraditional":"〔八〕　師古曰：「謂昭王也。（謂）〔為〕楚所溺也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_77_219","chapterId":"ch_work_han_thu_77","textTraditional":"〔九〕　師古曰：「謂襄王也。初為太子，而惠王欲立王子帶，齊桓公為首止之盟，以定太子之位。事在左傳僖五年。」","sentenceOrder":219},
  {"id":"s_work_han_thu_77_220","chapterId":"ch_work_han_thu_77","textTraditional":"〔一０〕張晏曰：「孔子作春秋，夷狄之國雖大，自稱王者皆貶為子。」","sentenceOrder":220},
  {"id":"s_work_han_thu_77_221","chapterId":"ch_work_han_thu_77","textTraditional":"〔一一〕師古曰：「卒，終也。」","sentenceOrder":221},
  {"id":"s_work_han_thu_77_222","chapterId":"ch_work_han_thu_77","textTraditional":"賴聖漢初興，為百姓請命，平定天下。至孝文皇帝，閔中國未安，偃武行文，則斷獄數百，民賦四十，丁男三年而一事。〔一〕時有獻千里馬者，詔曰：「鸞旗在前，屬車在後，〔二〕吉行日五十里，師行（二）〔三〕十里，朕乘千里之馬，獨先安之？」〔三〕於是還馬，與道里費，而下詔曰：「朕不受獻也，其令四方毋求來獻。」當此之時，逸游之樂絕，奇麗之賂塞，鄭衛之倡微矣。夫後（官）〔宮〕盛色則賢者隱處，佞人用事則諍臣杜口，而文帝不行，故諡為孝文，廟稱太宗。至孝武皇帝元狩六年，太倉之粟紅腐而不可食〔四〕，都內之錢貫朽而不可（挍）〔校〕〔五〕。乃探平城之事，〔六〕錄冒頓以來數為邊害，籍兵厲馬，因富民以攘服之。〔七〕西連諸國至于安息，東過碣石以玄菟、樂浪為郡，〔八〕（比）〔北〕卻匈奴萬里，更起營塞，制南海以為八郡，則天下斷獄萬數，民賦數百，造鹽鐵酒榷之利以佐用度，猶不能足。當此之時，寇賊並起，軍旅數發，父戰死於前，子鬥傷於後，女子乘亭鄣，孤兒號於道，老母寡婦飲泣巷哭，〔九〕遙設虛祭，想魂乎萬里之外。淮南王盜寫虎符，陰聘名士，關東公孫勇等詐為使者，是皆廓地泰大，征伐不休之故也。","sentenceOrder":222},
  {"id":"s_work_han_thu_77_223","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　如淳曰：「常賦歲百二十，歲一事。時天下民多，故出賦四十，三歲而一事。」","sentenceOrder":223},
  {"id":"s_work_han_thu_77_224","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「鸞旗，編以羽毛，列繫橦旁，載於車上，大駕出，則陳於道而先行。屬車，相連屬而陳於後也。屬音之欲反。」","sentenceOrder":224},
  {"id":"s_work_han_thu_77_225","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「安之，言何所適往。」","sentenceOrder":225},
  {"id":"s_work_han_thu_77_226","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「粟久腐壞，則色紅赤也。」","sentenceOrder":226},
  {"id":"s_work_han_thu_77_227","chapterId":"ch_work_han_thu_77","textTraditional":"〔五〕　師古曰：「（挍）〔校〕謂數計也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_77_228","chapterId":"ch_work_han_thu_77","textTraditional":"〔六〕　師古曰：「追計其事，故言探。」","sentenceOrder":228},
  {"id":"s_work_han_thu_77_229","chapterId":"ch_work_han_thu_77","textTraditional":"〔七〕　師古曰：「攘，卻也。」","sentenceOrder":229},
  {"id":"s_work_han_thu_77_230","chapterId":"ch_work_han_thu_77","textTraditional":"〔八〕　師古曰：「樂音洛。浪音郎。」","sentenceOrder":230},
  {"id":"s_work_han_thu_77_231","chapterId":"ch_work_han_thu_77","textTraditional":"〔九〕　師古曰：「淚流被面以入於口，故言飲泣也。」","sentenceOrder":231},
  {"id":"s_work_han_thu_77_232","chapterId":"ch_work_han_thu_77","textTraditional":"今天下獨有關東，關東大者獨有齊楚，民眾久困，連年流離，離其城郭，相枕席於道路。〔一〕人情莫親父母，莫樂夫婦，至嫁妻賣子，法不能禁，義不能止，此社稷之憂也。今陛下不忍悁悁之忿，欲驅士眾擠之大海之中，〔二〕快心幽冥之地，非所以救助飢饉，保全元元也。詩云「蠢爾蠻荊，大邦為讎」，〔三〕言聖人起則後服，中國衰則先畔，動為國家難，自古而患之久矣，何況乃復其南方萬里之蠻乎！駱越之人父子同川而浴，相習以鼻飲，與禽獸無異，本不足郡縣置也。顓顓獨居一海之中，〔四〕霧露氣溼，多毒草蟲蛇水土之害，人未見虜，戰士自死。又非獨珠崖有珠犀玳瑁也，〔五〕棄之不足惜，不擊不損威。其民譬猶魚鱉，何足貪也！","sentenceOrder":232},
  {"id":"s_work_han_thu_77_233","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　如淳曰：「席音藉。」師古曰：「席即藉也，不勞借音。」","sentenceOrder":233},
  {"id":"s_work_han_thu_77_234","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「擠，墜也，音子詣反，又子奚反。」","sentenceOrder":234},
  {"id":"s_work_han_thu_77_235","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「詩小雅、采虯之詩也。蠢，動貌也。蠻荊，荊州之蠻也。言敢與大國為讎敵也。」","sentenceOrder":235},
  {"id":"s_work_han_thu_77_236","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「顓與專同。專專猶區區也，一曰圜貌也。」","sentenceOrder":236},
  {"id":"s_work_han_thu_77_237","chapterId":"ch_work_han_thu_77","textTraditional":"〔五〕　師古曰：「玳瑁，文甲也。玳音代。瑁音妺。」","sentenceOrder":237},
  {"id":"s_work_han_thu_77_238","chapterId":"ch_work_han_thu_77","textTraditional":"臣竊以往者羌軍言之，暴師曾未一年，兵出不踰千里，費四十餘萬萬，大司農錢盡，乃以少府禁錢續之。〔一〕夫一隅為不善，費尚如此，況於勞師遠攻，亡士毋功乎！求之往古則不合，施之當今又不便。臣愚以為非冠帶之國，禹貢所及，春秋所治，皆可且無以為。〔二〕願遂棄珠崖，專用恤關東為憂。","sentenceOrder":238},
  {"id":"s_work_han_thu_77_239","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「少府錢主供天子，故曰禁錢。」","sentenceOrder":239},
  {"id":"s_work_han_thu_77_240","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「為猶用也。」","sentenceOrder":240},
  {"id":"s_work_han_thu_77_241","chapterId":"ch_work_han_thu_77","textTraditional":"對奏，上以問丞相御史。御史大夫陳萬年以為當擊；丞相于定國以為「前日興兵擊之連年，護軍都尉、校尉及丞凡十一人，還者二人，卒士及轉輸死者萬人以上，費用三萬萬餘，尚未能盡降。今關東困乏，民難搖動，捐之議是。」上乃從之。遂下詔曰：「珠崖虜殺吏民，背畔為逆，今廷議者或言可擊，或言可守，或欲棄之，其指各殊。朕日夜惟思議者之言，羞威不行，則欲誅之；狐疑辟難，則守屯田；〔一〕通于時變，則憂萬民。夫萬民之饑餓，與遠蠻之不討，危孰大焉？且宗廟之祭，凶年不備，況乎辟不嫌之辱哉！今關東大困，倉庫空虛，無以相贍，又以動兵，非特勞民，凶年隨之。其罷珠崖郡。民有慕義欲內屬，便處之；〔二〕不欲，勿彊。」珠崖由是罷。","sentenceOrder":241},
  {"id":"s_work_han_thu_77_242","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「辟讀曰避。次下亦同。」","sentenceOrder":242},
  {"id":"s_work_han_thu_77_243","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「欲有來入內郡者，所至之處，即安置之。」","sentenceOrder":243},
  {"id":"s_work_han_thu_77_244","chapterId":"ch_work_han_thu_77","textTraditional":"捐之數召見，言多納用。時中書令石顯用事，捐之數短顯，〔一〕以故不得官，後稀復見。而長安令楊興新以材能得幸，與捐之相善。捐之欲得召見，謂興曰：「京兆尹缺，使我得見，言君蘭，〔二〕京兆尹可立得。」興曰：「縣官嘗言興瘉薛大夫，〔三〕我易助也。君房下筆，言語妙天下，〔四〕使君房為尚書令，勝五鹿充宗遠甚。」捐之曰：「令我得代充宗，君蘭為京兆，京兆郡國首，尚書百官本，天下真大治，士則不隔矣。捐之前言平恩侯可為將軍，〔五〕期思侯並可為諸曹，〔六〕皆如言；又薦謁者滿宣，立為冀州刺史；言中謁者不宜受事，宦者不宜入宗廟，立止。相薦之信，不當如是乎！」〔七〕興曰：「我復見，言君房也。」捐之復短石顯。興曰：「顯鼎貴，〔八〕上信用之。今欲進，弟從我計，〔九〕且與合意，即得入矣。」","sentenceOrder":244},
  {"id":"s_work_han_thu_77_245","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「談說其長短。」","sentenceOrder":245},
  {"id":"s_work_han_thu_77_246","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　張晏曰：「楊興字。」","sentenceOrder":246},
  {"id":"s_work_han_thu_77_247","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　張晏曰：「瘉，〔勝〕也。薛廣德為御史大夫。」師古曰：「瘉與愈同。」","sentenceOrder":247},
  {"id":"s_work_han_thu_77_248","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「於天下最為精妙耳。」","sentenceOrder":248},
  {"id":"s_work_han_thu_77_249","chapterId":"ch_work_han_thu_77","textTraditional":"〔五〕　張晏曰：「許嘉也。」","sentenceOrder":249},
  {"id":"s_work_han_thu_77_250","chapterId":"ch_work_han_thu_77","textTraditional":"〔六〕　師古曰：「期思侯，當是賁赫之後嗣也，而表不載。」","sentenceOrder":250},
  {"id":"s_work_han_thu_77_251","chapterId":"ch_work_han_thu_77","textTraditional":"〔七〕　師古曰：「冀相薦之效，當如前所言諸事見納用。」","sentenceOrder":251},
  {"id":"s_work_han_thu_77_252","chapterId":"ch_work_han_thu_77","textTraditional":"〔八〕　如淳曰：「鼎音釘，言方且欲貴矣。」師古曰：「方且，是也。讀如（今）〔本〕字。」","sentenceOrder":252},
  {"id":"s_work_han_thu_77_253","chapterId":"ch_work_han_thu_77","textTraditional":"〔九〕　師古曰：「弟，但也。」","sentenceOrder":253},
  {"id":"s_work_han_thu_77_254","chapterId":"ch_work_han_thu_77","textTraditional":"捐之即與興共為薦顯奏，曰：「竊見石顯本山東名族，有禮義之家也。持正六年，未嘗有過，明習於事，敏而疾見，出公門，入私門。〔一〕宜賜爵關內侯，引其兄弟以為諸曹。」又共為薦興奏，曰：「竊見長安令興，幸得以知名數召見。興事父母有曾氏之孝，〔二〕事師有顏閔之材，〔三〕榮名聞於四方。明詔舉茂材，列侯以為首。為長安令，吏民敬鄉，〔四〕道路皆稱能。觀其下筆屬文，則董仲舒；進談動辭，則東方生；置之爭臣，則汲直；〔五〕用之介冑，則冠軍侯；施之治民，則趙廣漢；抱公絕私，則尹翁歸。興兼此六人而有之，守道堅固，執義不回，〔六〕臨大節而不可奪，國之良臣也，可試守京兆尹。」","sentenceOrder":254},
  {"id":"s_work_han_thu_77_255","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「言自公庭出，即歸其家，不妄交游。」","sentenceOrder":255},
  {"id":"s_work_han_thu_77_256","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「曾參也。」","sentenceOrder":256},
  {"id":"s_work_han_thu_77_257","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「顏回，閔子騫。」","sentenceOrder":257},
  {"id":"s_work_han_thu_77_258","chapterId":"ch_work_han_thu_77","textTraditional":"〔四〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":258},
  {"id":"s_work_han_thu_77_259","chapterId":"ch_work_han_thu_77","textTraditional":"〔五〕　張晏曰：「汲黯方直，故世謂之汲直。」","sentenceOrder":259},
  {"id":"s_work_han_thu_77_260","chapterId":"ch_work_han_thu_77","textTraditional":"〔六〕　師古曰：「回，邪也。」","sentenceOrder":260},
  {"id":"s_work_han_thu_77_261","chapterId":"ch_work_han_thu_77","textTraditional":"石顯聞知，白之上。乃下興、捐之獄，令皇后父陽平侯禁與顯共雜治，奏「興、捐之懷詐偽，以上語相風，更相薦譽，〔一〕欲得大位，漏泄省中語，（岡）〔罔〕上不道。書曰：『讒說殄行，震驚朕師。』〔二〕王制：『順非而澤，不聽而誅。』〔三〕請論如法。」","sentenceOrder":261},
  {"id":"s_work_han_thu_77_262","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「風讀曰諷。更音工衡反。」","sentenceOrder":262},
  {"id":"s_work_han_thu_77_263","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「虞書舜典之辭也。言讒巧之說，殄絕君子之行，震驚我眾。」","sentenceOrder":263},
  {"id":"s_work_han_thu_77_264","chapterId":"ch_work_han_thu_77","textTraditional":"〔三〕　師古曰：「禮記王制云：『行偽而堅，言偽而辯，學非而博，順非而澤，以疑眾，殺。』謂人有堅為辯言，不以誠質，學於非道，雖博無用，飾非文過，辭語順澤，不聽教命，有如此者，皆誅殺也。」","sentenceOrder":264},
  {"id":"s_work_han_thu_77_265","chapterId":"ch_work_han_thu_77","textTraditional":"捐之竟坐棄市。興減死罪一等，髡鉗為城旦。成帝時，至部刺史。","sentenceOrder":265},
  {"id":"s_work_han_thu_77_266","chapterId":"ch_work_han_thu_77","textTraditional":"贊曰：詩稱「戎狄是膺，荊舒是懲」，〔一〕久矣其為諸夏患也。漢興，征伐胡越，於是為盛。究觀淮南、捐之、主父、嚴安之義，深切著明，〔二〕故備論其語。世稱公孫弘排主父，張湯陷嚴助，石顯譖捐之，察其行跡，主父求欲鼎亨而得族，嚴、賈出入禁門招權利，死皆其所也，亦何排陷之恨哉！","sentenceOrder":266},
  {"id":"s_work_han_thu_77_267","chapterId":"ch_work_han_thu_77","textTraditional":"〔一〕　師古曰：「魯頌閟宮之詩也。膺，當也。懲，創刈也。言魯僖公與齊桓舉義兵，北當戎狄，南創荊蠻與群舒以靖難。」","sentenceOrder":267},
  {"id":"s_work_han_thu_77_268","chapterId":"ch_work_han_thu_77","textTraditional":"〔二〕　師古曰：「究，極也。」","sentenceOrder":268},
  {"id":"s_work_han_thu_77_269","chapterId":"ch_work_han_thu_77","textTraditional":"校勘記","sentenceOrder":269},
  {"id":"s_work_han_thu_77_270","chapterId":"ch_work_han_thu_77","textTraditional":"二八０九頁　五行　臣聞鄒（衍）〔子〕曰：　景祐、殿、局本都作「子」。","sentenceOrder":270},
  {"id":"s_work_han_thu_77_271","chapterId":"ch_work_han_thu_77","textTraditional":"二八０九頁　六行　有易則易（也）〔之〕。　景祐、殿本都作「之」。","sentenceOrder":271},
  {"id":"s_work_han_thu_77_272","chapterId":"ch_work_han_thu_77","textTraditional":"二八一一頁　六行　（晉）〔更〕音工衡反。　景祐、殿、局本都作「更」，此誤。","sentenceOrder":272},
  {"id":"s_work_han_thu_77_273","chapterId":"ch_work_han_thu_77","textTraditional":"二八一一頁一二行　（曰）〔日〕聞其美，（章）〔意〕廣心逸。　景祐、殿、局本都作「日」作「意」，此誤。","sentenceOrder":273},
  {"id":"s_work_han_thu_77_274","chapterId":"ch_work_han_thu_77","textTraditional":"二八一六頁　二行　夫（人）〔天〕命初定，萬事草創，　景祐、殿、局本字都作「天」。王先謙說作「天」是。","sentenceOrder":274},
  {"id":"s_work_han_thu_77_275","chapterId":"ch_work_han_thu_77","textTraditional":"二八一六頁　七行　苴（以）白茅於江淮，　王先謙說「以」字衍。按殿本無「以」字。","sentenceOrder":275},
  {"id":"s_work_han_thu_77_276","chapterId":"ch_work_han_thu_77","textTraditional":"二八二０頁　四行　傳（須）〔煩〕，因裂繻頭合以為符信也。　景祐、殿本都作「煩」。王先謙說作「煩」是。","sentenceOrder":276},
  {"id":"s_work_han_thu_77_277","chapterId":"ch_work_han_thu_77","textTraditional":"二八二０頁　九行　當發使（使）匈奴，　景祐本不重「使」字。　王念孫說，按注文則正文似祗有一「使」字。","sentenceOrder":277},
  {"id":"s_work_han_thu_77_278","chapterId":"ch_work_han_thu_77","textTraditional":"二八二一頁一一行　天下殷（當）〔富〕，　景祐、殿、局本都作「富」，此誤。","sentenceOrder":278},
  {"id":"s_work_han_thu_77_279","chapterId":"ch_work_han_thu_77","textTraditional":"二八二二頁一一行　羹（黎）〔藜〕唅糗者，　景祐、殿本都作「藜」。楊樹達說作「藜」是。","sentenceOrder":279},
  {"id":"s_work_han_thu_77_280","chapterId":"ch_work_han_thu_77","textTraditional":"二八二三頁一三行　亦聖（主）〔王〕之所以易海內也。　景祐、殿本都作「王」，文選同。","sentenceOrder":280},
  {"id":"s_work_han_thu_77_281","chapterId":"ch_work_han_thu_77","textTraditional":"二八二四頁　六行　焠謂（堯）〔燒〕而內水中以堅之也。　景祐、殿、局本都作「燒」，此誤。","sentenceOrder":281},
  {"id":"s_work_han_thu_77_282","chapterId":"ch_work_han_thu_77","textTraditional":"二八二四頁　七行　砥（百）〔石〕出南昌，　景祐、殿本都作「石」，此誤。","sentenceOrder":282},
  {"id":"s_work_han_thu_77_283","chapterId":"ch_work_han_thu_77","textTraditional":"二八二五頁　三行　言其（起）〔速〕疾之甚。　景祐、殿本都作「速」。","sentenceOrder":283},
  {"id":"s_work_han_thu_77_284","chapterId":"ch_work_han_thu_77","textTraditional":"二八二五頁一四行　齊桓（逐）〔遂〕以霸。　景祐、殿、局本都作「遂」，此誤。","sentenceOrder":284},
  {"id":"s_work_han_thu_77_285","chapterId":"ch_work_han_thu_77","textTraditional":"二八二六頁　四行　故虎嘯而（冽風）〔風冽〕，　景祐、殿本都作「風冽」，通鑑同。","sentenceOrder":285},
  {"id":"s_work_han_thu_77_286","chapterId":"ch_work_han_thu_77","textTraditional":"二八二六頁一五行　蹻（自）〔即〕今之鞋耳。　景祐、殿本都作「即」。","sentenceOrder":286},
  {"id":"s_work_han_thu_77_287","chapterId":"ch_work_han_thu_77","textTraditional":"二八二七頁　一行　談說（也）〔之〕士傳以為資也。　景祐、汲古、殿、局本都作「之」，此誤。","sentenceOrder":287},
  {"id":"s_work_han_thu_77_288","chapterId":"ch_work_han_thu_77","textTraditional":"二八二七頁　三行　蜉蝤，甲（患）〔蟲〕也，　景祐、殿、局本都作「蟲」，此誤。","sentenceOrder":288},
  {"id":"s_work_han_thu_77_289","chapterId":"ch_work_han_thu_77","textTraditional":"二八二九頁　六行　奕，今之圍（其）〔棋〕也。　景祐、局本作「都」，殿本作「碁」。此誤，汲古本又誤作「甚」。","sentenceOrder":289},
  {"id":"s_work_han_thu_77_290","chapterId":"ch_work_han_thu_77","textTraditional":"二八三一頁　一行　邦有道，危言（行危）〔危行〕。　景祐、殿、局本都作「危行」，此誤倒。","sentenceOrder":290},
  {"id":"s_work_han_thu_77_291","chapterId":"ch_work_han_thu_77","textTraditional":"二八三一頁　四行　〔西〕被流沙，　景祐、殿本都有「西」字，此脫。","sentenceOrder":291},
  {"id":"s_work_han_thu_77_292","chapterId":"ch_work_han_thu_77","textTraditional":"二八三一頁　五行　含氣之物各（德）〔得〕其宜。　景祐、殿、局本都作「得」。","sentenceOrder":292},
  {"id":"s_work_han_thu_77_293","chapterId":"ch_work_han_thu_77","textTraditional":"二八三二頁　四行　（謂）〔為〕楚所溺也。　景祐、殿、局本都作「為」。","sentenceOrder":293},
  {"id":"s_work_han_thu_77_294","chapterId":"ch_work_han_thu_77","textTraditional":"二八三二頁一０行　師行（二）〔三〕十里，　景祐、殿本都作「三」，此誤。","sentenceOrder":294},
  {"id":"s_work_han_thu_77_295","chapterId":"ch_work_han_thu_77","textTraditional":"二八三二頁一二行　夫後（官）〔宮〕盛色　景祐、殿本都作「宮」，此誤。","sentenceOrder":295},
  {"id":"s_work_han_thu_77_296","chapterId":"ch_work_han_thu_77","textTraditional":"二八三二頁一四行　貫朽而不可（挍）〔校〕。　景祐、殿本都作「校」，注同。","sentenceOrder":296},
  {"id":"s_work_han_thu_77_297","chapterId":"ch_work_han_thu_77","textTraditional":"二八三二頁一五行　（比）〔北〕卻匈奴萬里更起營塞，　景祐、殿、局本都作「北」，此誤。","sentenceOrder":297},
  {"id":"s_work_han_thu_77_298","chapterId":"ch_work_han_thu_77","textTraditional":"二八三六頁　六行　瘉，〔勝〕也。　景祐、殿本都有「勝」字，此脫。","sentenceOrder":298},
  {"id":"s_work_han_thu_77_299","chapterId":"ch_work_han_thu_77","textTraditional":"二八三六頁一一行　讀如（今）〔本〕字。　殿、局本作「本」。王先謙說作「本」是。","sentenceOrder":299},
  {"id":"s_work_han_thu_77_300","chapterId":"ch_work_han_thu_77","textTraditional":"二八三七頁一一行　（岡）〔罔〕上不道。　景祐、殿、局本都作「罔」，此誤。","sentenceOrder":300},
  {"id":"s_work_han_thu_78_1","chapterId":"ch_work_han_thu_78","textTraditional":"東方朔字曼倩，〔一〕平原厭次人也。〔二〕武帝初即位，徵天下舉方正賢良文學材力之士，待以不次之位，〔三〕四方士多上書言得失，自衒鬻者以千數，〔四〕其不足采者輒報聞罷。〔五〕朔初來，上書曰：「臣朔少失父母，長養兄嫂。年十三學書，三冬文史足用。〔六〕十五學擊劍。十六學詩書，〔七〕誦二十二萬言。十九學孫吳兵法，戰陣之具，鉦鼓之教，〔八〕亦誦二十二萬言。凡臣朔固已誦四十四萬言。又常服子路之言。〔九〕臣朔年二十二，長九尺三寸，目若懸珠，齒若編貝，〔一０〕勇若孟賁，〔一一〕捷若慶忌〔一二〕，廉若鮑叔，〔一三〕信若尾生。〔一四〕若此，可以為天子大臣矣。臣朔昧死再拜以聞。」","sentenceOrder":1},
  {"id":"s_work_han_thu_78_2","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「倩音千見反。」","sentenceOrder":2},
  {"id":"s_work_han_thu_78_3","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「高祖功臣表有厭次侯爰類，是則厭次之名也其來久矣，而說者乃云後漢始為縣，於此致疑，斯未通也。厭音一涉反，又音一琰反。」","sentenceOrder":3},
  {"id":"s_work_han_thu_78_4","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「不拘常次，言超擢也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_78_5","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　師古曰：「衒，行賣也。鬻亦賣也。衒音州縣之縣，又音工縣反。」","sentenceOrder":5},
  {"id":"s_work_han_thu_78_6","chapterId":"ch_work_han_thu_78","textTraditional":"〔五〕　師古曰：「報云天子已聞其所上之書，而罷之令歸。」","sentenceOrder":6},
  {"id":"s_work_han_thu_78_7","chapterId":"ch_work_han_thu_78","textTraditional":"〔六〕　如淳曰：「貧子冬日乃得學書，言文史之事足可用也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_78_8","chapterId":"ch_work_han_thu_78","textTraditional":"〔七〕　師古曰：「學劍，遙擊而中之，非斬刺也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_78_9","chapterId":"ch_work_han_thu_78","textTraditional":"〔八〕　師古曰：「鉦鼓，所以為進退士眾之節也。鉦音正。」","sentenceOrder":9},
  {"id":"s_work_han_thu_78_10","chapterId":"ch_work_han_thu_78","textTraditional":"〔九〕　服虔曰：「無宿諾。」","sentenceOrder":10},
  {"id":"s_work_han_thu_78_11","chapterId":"ch_work_han_thu_78","textTraditional":"〔一０〕師古曰：「編，列次也，音鞭。」","sentenceOrder":11},
  {"id":"s_work_han_thu_78_12","chapterId":"ch_work_han_thu_78","textTraditional":"〔一一〕師古曰：「孟賁，衛人，古之勇士也。尸子說云：『人謂孟賁生乎？曰勇。貴乎？曰勇。富乎？曰勇。三者人之所難，而皆不足以易勇，故能懾三軍，服猛獸也。』」","sentenceOrder":12},
  {"id":"s_work_han_thu_78_13","chapterId":"ch_work_han_thu_78","textTraditional":"〔一二〕師古曰：「王子慶忌也。射之，矢滿把不能中；駟馬追之不能及也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_78_14","chapterId":"ch_work_han_thu_78","textTraditional":"〔一三〕師古曰：「齊大夫也，與管仲分財，自取其少。而說者乃妄解云鮑焦，非也。焦自介士耳。」","sentenceOrder":14},
  {"id":"s_work_han_thu_78_15","chapterId":"ch_work_han_thu_78","textTraditional":"〔一四〕師古曰：「尾生，古之信士，與女子期於梁下，待之不至，遇水而死。一曰即微生高也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_78_16","chapterId":"ch_work_han_thu_78","textTraditional":"朔文辭不遜，高自稱譽，上偉之，〔一〕令待詔公車，〔二〕奉祿薄，未得省見。〔三〕","sentenceOrder":16},
  {"id":"s_work_han_thu_78_17","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「以為大奇也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_78_18","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「公車令屬衛尉，上書者所詣也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_78_19","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「不被省納，不得見於天子也。奉音扶用反。其下並同。」","sentenceOrder":19},
  {"id":"s_work_han_thu_78_20","chapterId":"ch_work_han_thu_78","textTraditional":"久之，朔紿騶朱儒，〔一〕曰：「上以若曹無益於縣官，〔二〕耕田力作固不及人，臨眾處官不能治民，從軍擊虜不任兵事，無益於國用，徒索衣食，〔三〕今欲盡殺若曹。」朱儒大恐，啼泣。朔教曰：「上即過，叩頭請罪。」居有頃，聞上過，朱儒皆號泣頓首。上問：「何為？」對曰：「東方朔言上欲盡誅臣等。」上知朔多端，召問朔：「何恐朱儒為？」對曰：「臣朔生亦言，死亦言。朱儒長三尺餘，奉一囊粟，錢二百四十。臣朔長九尺餘，亦奉一囊粟，錢二百四十。朱儒飽欲死，臣朔飢欲死。臣言可用，幸異其禮；不可用，罷之，無令但索長安米。」上大笑，因使待詔金馬門，稍得親近。","sentenceOrder":20},
  {"id":"s_work_han_thu_78_21","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　文穎曰：「朱儒之為騶者也。」師古曰：「朱儒，短人也。騶本廄之御騶也，後人以為騎，謂之騶騎。」","sentenceOrder":21},
  {"id":"s_work_han_thu_78_22","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「若，女也。曹，輩也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_78_23","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　如淳曰：「索，盡也。」師古曰：「音先各反。下云索長安米亦同也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_78_24","chapterId":"ch_work_han_thu_78","textTraditional":"上嘗使諸數家射覆，〔一〕置守宮盂下，射之，皆不能中。〔二〕朔自贊曰：「臣嘗受易，請射之。」〔三〕乃別蓍布卦而對曰〔四〕：「臣以為龍又無角，謂之為蛇又有足，跂跂脈脈善緣壁，是非守宮即蜥蜴。」〔五〕上曰：「善。」賜帛十匹。復使射他物，連中，輒賜帛。〔六〕","sentenceOrder":24},
  {"id":"s_work_han_thu_78_25","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「數家，術數之家也。於覆器之下而置諸物，令闇射之，故云射覆。數音所具反。覆音芳目反。」","sentenceOrder":25},
  {"id":"s_work_han_thu_78_26","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「守宮，蟲名也。術家云以器養之，食以丹砂，滿七斤，擣治萬杵，以點女人體，終身不滅，若有房室之事，則滅矣。言可以防閑淫逸，故謂之守宮也。今俗呼為辟宮，辟亦禦扞之義耳。盂，食器也，若盋而大，今之所謂盋盂也。盋音撥。」","sentenceOrder":26},
  {"id":"s_work_han_thu_78_27","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「贊，進也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_78_28","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　師古曰：「別，分也，音彼列反。」","sentenceOrder":28},
  {"id":"s_work_han_thu_78_29","chapterId":"ch_work_han_thu_78","textTraditional":"〔五〕　師古曰：「跂跂，行貌也。脈脈，視貌也。爾雅云『蠑螈，蜥蜴；蜥蜴，蝘蜓，守宮』。是則一類耳。揚雄方言云其在澤中者謂之蜥蜴。故朔曰是非守宮則蜥蜴也。蜥音先歷反。蜴音余赤反。蠑音榮。螈音原。蝘音烏典反。蜓音殄。」","sentenceOrder":29},
  {"id":"s_work_han_thu_78_30","chapterId":"ch_work_han_thu_78","textTraditional":"〔六〕　師古曰：「中音竹仲反。其下並同。」","sentenceOrder":30},
  {"id":"s_work_han_thu_78_31","chapterId":"ch_work_han_thu_78","textTraditional":"時有幸倡郭舍人，滑稽不窮，〔一〕常侍左右，曰：「朔狂，幸中耳，非至數也。〔二〕臣願令朔復射，朔中之，臣榜百，不能中，臣賜帛。」〔三〕乃覆樹上寄生，令朔射之。朔曰：「是寠藪也。」〔四〕舍人曰：「果知朔不能中也。」朔曰：「生肉為膾，乾肉為脯；著樹為寄生，盆下為寠數。」上令倡監榜舍人，舍人不勝痛，呼謈。〔五〕朔笑之曰：「咄！口無毛，聲謷謷，（凥）〔尻〕益高。」〔六〕舍人恚曰：「朔擅詆欺天子從官，當棄巿。」〔七〕上問朔：「何故詆之？」對曰：「臣非敢詆之，乃與為隱耳。」〔八〕上曰：「隱云何？」朔曰：「夫口無毛者，狗竇也；聲謷謷者，鳥哺鷇也；〔九〕尻益高者，鶴俛啄也。」〔一０〕舍人不服，因曰：「臣願復問朔隱語，不知，亦當榜。」即妄為諧語曰：〔一一〕「令壺齟，老柏塗，伊優亞，狋吽牙。何謂也？」〔一二〕朔曰：「令者，命也。壺者，所以盛也。〔一三〕齟者，齒不正也。老者，人所敬也。柏者，鬼之廷也。〔一四〕塗者，漸洳徑也。〔一五〕伊優亞者，辭未定也。狋吽牙者，兩犬爭也。」舍人所問，朔應聲輒對，變詐鋒出，莫能窮者，左右大驚。上以朔為常侍郎，遂得愛幸。","sentenceOrder":31},
  {"id":"s_work_han_thu_78_32","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「幸倡，倡優之見幸遇者也。滑音骨。滑稽，解在公孫弘傳。」","sentenceOrder":32},
  {"id":"s_work_han_thu_78_33","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「至，實也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_78_34","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「榜，擊也，音步行反。」","sentenceOrder":34},
  {"id":"s_work_han_thu_78_35","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　蘇林曰：「寠音貧寠之寠，藪音數錢之數。寠數，鉤灌，四股鉤也。」師古曰：「寠數，戴器也，以盆盛物戴於頭者，則以寠數薦之，今賣白團餅人所用者是也。寄生者，芝菌之類，淋潦之日，著樹而生，形有周圜象寠數者，今關中俗亦呼為寄生。非為蔦之寄生寓木宛童有（林）〔枝〕葉者也。故朔云『著樹為寄生，盆下為寠數』。明其常在盆下。今讀書者不曉其意，謂射覆之物覆在盆下，輒改前『覆守宮盂下』為盆字，失之遠矣。楊惲傳云『鼠不容穴，銜寠數也。』盆下之物有飲食氣，故鼠銜之，四股鐵鉤，非所銜也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_78_36","chapterId":"ch_work_han_thu_78","textTraditional":"〔五〕　服虔曰：「謈音暴。」鄧展曰：「呼音髐箭之髐。謈音瓜瓝之瓝。」師古曰：「鄧音是也。謂痛切而叫呼也，與田蚡傳『呼服』音義皆同。一曰，鄧音近之。謈，自冤痛之聲也。舍人榜痛，乃呼云謈。今人痛甚，則稱阿謈，音步高反。是故朔逐韻而嘲之云『口無毛，聲謷謷』也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_78_37","chapterId":"ch_work_han_thu_78","textTraditional":"〔六〕　鄧展曰：「咄音豽裘之豽也。」師古曰：「咄，叱咄之聲也，音丁骨反。鄧說非也。謷音敖。」","sentenceOrder":37},
  {"id":"s_work_han_thu_78_38","chapterId":"ch_work_han_thu_78","textTraditional":"〔七〕　師古曰：「詆，毀辱也，音丁禮反。」","sentenceOrder":38},
  {"id":"s_work_han_thu_78_39","chapterId":"ch_work_han_thu_78","textTraditional":"〔八〕　師古曰：「隱謂隱語也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_78_40","chapterId":"ch_work_han_thu_78","textTraditional":"〔九〕　項昭曰：「凡鳥哺子而活者為鷇，生而自啄曰雛。」師古曰：「（雛）〔鷇〕音口豆反。」","sentenceOrder":40},
  {"id":"s_work_han_thu_78_41","chapterId":"ch_work_han_thu_78","textTraditional":"〔一０〕師古曰：「俛即俯字也。俯，低也。啄，鳥觜也。俛又音免。啄音竹救反。」","sentenceOrder":41},
  {"id":"s_work_han_thu_78_42","chapterId":"ch_work_han_thu_78","textTraditional":"〔一一〕師古曰：「諧者，和韻之言也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_78_43","chapterId":"ch_work_han_thu_78","textTraditional":"〔一二〕張晏曰：「齟音樝梨之樝。」應劭曰：「狋音銀。」師古曰：「齟音側加反，又，壯加反。塗音丈加反。優音一侯反。亞音烏加反。狋音五伊反。吽音五侯反。」","sentenceOrder":43},
  {"id":"s_work_han_thu_78_44","chapterId":"ch_work_han_thu_78","textTraditional":"〔一三〕師古曰：「盛，受物也，音時政反。」","sentenceOrder":44},
  {"id":"s_work_han_thu_78_45","chapterId":"ch_work_han_thu_78","textTraditional":"〔一四〕師古曰：「言鬼神尚幽闇，故以松柏之樹為廷府。」","sentenceOrder":45},
  {"id":"s_work_han_thu_78_46","chapterId":"ch_work_han_thu_78","textTraditional":"〔一五〕師古曰：「漸洳，浸溼也。漸音子廉反。洳音人庶反。」","sentenceOrder":46},
  {"id":"s_work_han_thu_78_47","chapterId":"ch_work_han_thu_78","textTraditional":"久之，伏日，〔一〕詔賜從官肉。大官丞日晏不來，〔二〕朔獨拔劍割肉，謂其同官曰：「伏日當蚤歸，〔三〕請受賜。」即懷肉去。大官奏之。朔入，上曰：「昨賜肉，不待詔，以劍割肉而去之，何也？」朔免冠謝。上曰：「先生起自責也。」朔再拜曰：「朔來！朔來！受賜不待詔，何無禮也！拔劍割肉，壹何壯也！割之不多，又何廉也！歸遺細君，又何仁也！」〔四〕上笑曰：「使先生自責，乃反自譽！」復賜酒一石，肉百斤，歸遺細君。","sentenceOrder":47},
  {"id":"s_work_han_thu_78_48","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「三伏之日也，解在郊祀志。」","sentenceOrder":48},
  {"id":"s_work_han_thu_78_49","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「晏，晚也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_78_50","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「蚤古早字。」","sentenceOrder":50},
  {"id":"s_work_han_thu_78_51","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　師古曰：「細君，朔妻之名。一說，細，小也，朔自比於諸侯，謂其妻曰小君。」","sentenceOrder":51},
  {"id":"s_work_han_thu_78_52","chapterId":"ch_work_han_thu_78","textTraditional":"初，建元三年，微行始出，北至池陽，西至黃山，〔一〕南獵長楊，東游宜春。〔二〕微行常用飲酎已。〔三〕八九月中，與侍中常侍武騎及待詔隴西北地良家子能騎射者期諸殿門，故有「期門」之號自此始。微行以夜漏下十刻乃出，常稱平陽侯。〔四〕旦明，入山下馳射鹿豕狐兔，手格熊羆，馳騖禾稼稻秔之地。〔五〕民皆號呼罵詈，〔六〕相聚會，自言鄠杜令。令往，欲謁平陽侯，諸騎欲擊鞭之。令大怒，使吏呵止，獵者數騎見留，乃示以乘輿物，久之乃得去。時夜出夕還，後齎五日糧，會朝長信宮，〔七〕上大驩樂之。是後，南山下乃知微行數出也，然尚迫於太后，未敢遠出。丞相御史知指〔八〕，乃使右輔都尉徼循長楊以東，〔九〕右內史發小民共待會所〔一０〕。後乃私置更衣，〔一一〕從宣曲以南十二所，中休更衣，〔一二〕投宿諸宮，〔一三〕長楊、五柞、倍陽、宣曲尤幸。〔一四〕於是上以為道遠勞苦，又為百姓所患，乃使太中大夫吾丘壽王與待詔能用算者二人，舉籍阿城以南，〔一五〕盩厔以東，宜春以西，提封頃畝，及其賈直，〔一六〕欲除以為上林苑，屬之南山。〔一七〕又詔中尉、左右內史表屬縣草田，欲以償鄠杜之民。〔一八〕吾丘壽王奏事，上大說稱善。〔一九〕時朔在傍，進諫曰：","sentenceOrder":52},
  {"id":"s_work_han_thu_78_53","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　晉灼曰：「宮名，在槐里。」","sentenceOrder":53},
  {"id":"s_work_han_thu_78_54","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「宜春宮也，在長安城東南。說者乃以為在鄠，非也。在鄠者，自是宜春觀耳，在長安城西，豈得言東游也？」","sentenceOrder":54},
  {"id":"s_work_han_thu_78_55","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「酎，酒新孰以祭宗廟也。酎音紂。解在景紀。」","sentenceOrder":55},
  {"id":"s_work_han_thu_78_56","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　如淳曰：「平陽侯曹壽尚帝姊，時見尊寵，故稱之。」","sentenceOrder":56},
  {"id":"s_work_han_thu_78_57","chapterId":"ch_work_han_thu_78","textTraditional":"〔五〕　師古曰：「稻，有芒之穀總稱也。秔，其不黏者也，音庚。」","sentenceOrder":57},
  {"id":"s_work_han_thu_78_58","chapterId":"ch_work_han_thu_78","textTraditional":"〔六〕　師古曰：「呼音火故反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_78_59","chapterId":"ch_work_han_thu_78","textTraditional":"〔七〕　師古曰：「五日一朝長信宮，故齎五日糧也。長信，太后之宮也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_78_60","chapterId":"ch_work_han_thu_78","textTraditional":"〔八〕　師古曰：「指謂天子之意也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_78_61","chapterId":"ch_work_han_thu_78","textTraditional":"〔九〕　師古曰：「徼，遮繞也。循，行視也。戒備非常也。徼音工釣反。」","sentenceOrder":61},
  {"id":"s_work_han_thu_78_62","chapterId":"ch_work_han_thu_78","textTraditional":"〔一０〕師古曰：「共讀曰供。」","sentenceOrder":62},
  {"id":"s_work_han_thu_78_63","chapterId":"ch_work_han_thu_78","textTraditional":"〔一一〕師古曰：「為休息易衣之處，亦置宮人。」","sentenceOrder":63},
  {"id":"s_work_han_thu_78_64","chapterId":"ch_work_han_thu_78","textTraditional":"〔一二〕師古曰：「宣曲，宮名，在昆明池西。」","sentenceOrder":64},
  {"id":"s_work_han_thu_78_65","chapterId":"ch_work_han_thu_78","textTraditional":"〔一三〕師古曰：「晝休更衣，夜則別宿於諸宮。」","sentenceOrder":65},
  {"id":"s_work_han_thu_78_66","chapterId":"ch_work_han_thu_78","textTraditional":"〔一四〕師古曰：「倍陽、即萯陽也，其音同耳，宮名，在鄠縣也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_78_67","chapterId":"ch_work_han_thu_78","textTraditional":"〔一五〕師古曰：「舉計其數而為簿籍也。阿城，本秦阿房宮也，以其牆壁崇廣，故俗呼為阿城。」","sentenceOrder":67},
  {"id":"s_work_han_thu_78_68","chapterId":"ch_work_han_thu_78","textTraditional":"〔一六〕師古曰：「提封，亦謂提舉四封之內，總計其數也。賈讀曰價。」","sentenceOrder":68},
  {"id":"s_work_han_thu_78_69","chapterId":"ch_work_han_thu_78","textTraditional":"〔一七〕師古曰：「屬，連也，音之欲反。」","sentenceOrder":69},
  {"id":"s_work_han_thu_78_70","chapterId":"ch_work_han_thu_78","textTraditional":"〔一八〕師古曰：「時未為京兆、馮翊、扶風，故云中尉及左右內史也。草田謂荒田未耕墾也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_78_71","chapterId":"ch_work_han_thu_78","textTraditional":"〔一九〕師古曰：「說讀曰悅。」","sentenceOrder":71},
  {"id":"s_work_han_thu_78_72","chapterId":"ch_work_han_thu_78","textTraditional":"臣聞謙遜靜愨，天表之應，應之以福；〔一〕驕溢靡麗，天表之應，應之以異。今陛下累郎臺，恐其不高也；〔二〕弋獵之處，恐其不廣也。如天不為變，則三輔之地盡可以為苑，何必盩厔、鄠、杜乎！〔三〕奢侈越制，天為之變，上林雖小，臣尚以為大也。","sentenceOrder":72},
  {"id":"s_work_han_thu_78_73","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「愨，謹也，音口角反。」","sentenceOrder":73},
  {"id":"s_work_han_thu_78_74","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「郎，堂下周屋。」","sentenceOrder":74},
  {"id":"s_work_han_thu_78_75","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「中尉及左右內史則為三輔矣，非必謂京兆、馮翊、扶風也。學者疑此言為後人所增，斯未達也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_78_76","chapterId":"ch_work_han_thu_78","textTraditional":"夫南山，天下之阻也，南有江淮，北有河渭，其地從汧隴以東，商雒以西，〔一〕厥壤肥饒。漢興，去三河之地，止霸產以西，都涇渭之南，此所謂天下陸海之地，〔二〕秦之所以虜西戎兼山東者也。其山出玉石，金、銀、銅、鐵，豫章、檀、柘，異類之物，不可勝原，〔三〕此百工所取給，萬民所卬足也。〔四〕又有秔稻梨栗桑麻竹箭之饒，土宜薑芋，水多〈圭黽〉魚，〔五〕貧者得以人給家足，無飢寒之憂。故酆鎬之間號為土膏，其賈畝一金。〔六〕今規以為苑，絕陂池水澤之利，而取民膏腴之地，上乏國家之用，下奪農桑之業，棄成功，就敗事，損耗五穀，〔七〕是其不可一也。且盛荊棘之林，而長養麋鹿，廣狐兔之苑，大虎狼之虛，〔八〕又壞人冢墓，發人室廬，令幼弱懷土而思，耆老泣涕而悲，是其不可二也。斥而營之，垣而囿之，〔九〕騎馳東西，車騖南北，〔一０〕又有深溝大渠，夫一日之樂不足以危無隄之輿，〔一一〕是其不可三也。故務苑囿之大，不恤農時，非所以彊國富人也。","sentenceOrder":76},
  {"id":"s_work_han_thu_78_77","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　服虔曰：「商與上雒二縣也。」師古曰：「汧，汧水也。隴，隴坻也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_78_78","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「高平曰陸，關中地高故稱耳。海者，萬物所出，言關中山川物產饒富，是以謂之陸海也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_78_79","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「原，本也。言說不能盡其根本。」","sentenceOrder":79},
  {"id":"s_work_han_thu_78_80","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　師古曰：「卬音牛向反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_78_81","chapterId":"ch_work_han_thu_78","textTraditional":"〔五〕　師古曰：「芋，草名，其葉似藕荷而長，不圓，其根正白可食，〈圭黽〉即蛙字也，似蝦蟆而小，長腳，蓋人亦取食之。」","sentenceOrder":81},
  {"id":"s_work_han_thu_78_82","chapterId":"ch_work_han_thu_78","textTraditional":"〔六〕　師古曰：「賈讀曰價。」","sentenceOrder":82},
  {"id":"s_work_han_thu_78_83","chapterId":"ch_work_han_thu_78","textTraditional":"〔七〕　師古曰：「耗，減也，音呼到反。」","sentenceOrder":83},
  {"id":"s_work_han_thu_78_84","chapterId":"ch_work_han_thu_78","textTraditional":"〔八〕　師古曰：「虛讀曰墟。」","sentenceOrder":84},
  {"id":"s_work_han_thu_78_85","chapterId":"ch_work_han_thu_78","textTraditional":"〔九〕　師古曰：「斥，卻也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_78_86","chapterId":"ch_work_han_thu_78","textTraditional":"〔一０〕師古曰：「亂馳曰騖。」","sentenceOrder":86},
  {"id":"s_work_han_thu_78_87","chapterId":"ch_work_han_thu_78","textTraditional":"〔一一〕蘇林曰：「隄，限也。輿，乘輿也。無限，若言不訾也。不敢斥天子，故言輿也。」張晏曰：「一日之樂，謂田獵也。無隄之輿，謂天子富貴無隄限也。」師古曰：「張說是也。〔隄〕音丁奚反。」","sentenceOrder":87},
  {"id":"s_work_han_thu_78_88","chapterId":"ch_work_han_thu_78","textTraditional":"夫殷作九巿之宮而諸侯畔，〔一〕靈王起章華之臺而楚民散，〔二〕秦興阿房之殿而天下亂。糞土愚臣，忘生觸死，〔三〕逆盛意，犯隆指，罪當萬死，不勝大願，願陳泰階六符，〔四〕以觀天變，不可不省。","sentenceOrder":88},
  {"id":"s_work_han_thu_78_89","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　應劭曰：「紂於宮中設九巿。」","sentenceOrder":89},
  {"id":"s_work_han_thu_78_90","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「楚靈王作章華之臺納亡人以實之，卒有乾谿之禍也。章華臺在華容城也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_78_91","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「勿忘其生而觸死罪也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_78_92","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　孟康曰：「泰階，三台也。每台二星，凡六星。符，六星之符驗也。」應劭曰：「黃帝泰階六符經曰：『泰階者，天之三階也。上階為天子，中階為諸侯公卿大夫，下階為士庶人。上階上星為男主，下星為女主。中階上星為諸侯三公，下星為卿大夫。下階上星為元士，下星為庶人。三階平則陰陽和，風雨時，社稷神祇咸獲其宜，天下大安，是為太平。三階不平，則五神乏祀，日有食之，水潤不浸，稼穡不成，冬雷夏霜，百姓不寧，故治道傾。天子行暴令，好興甲兵，修宮榭，廣苑囿，則上階為之奄奄疏闊也。』以孝武皆有此事，故朔為陳之。」","sentenceOrder":92},
  {"id":"s_work_han_thu_78_93","chapterId":"ch_work_han_thu_78","textTraditional":"是日因奏泰階之事，上乃拜朔為太中大夫給事中，賜黃金百斤。然遂起上林苑，如壽王所奏云。","sentenceOrder":93},
  {"id":"s_work_han_thu_78_94","chapterId":"ch_work_han_thu_78","textTraditional":"久之，隆慮公主子昭平君〔一〕尚帝女夷安公主，隆慮主病困，以金千斤錢千萬為昭平君豫贖死罪，上許之。隆慮主卒，昭平君日驕，醉殺主傅，獄繫內官。〔二〕以公主子，廷尉上請請論。〔三〕左右人人為言：「前又入贖，陛下許之。」上曰：「吾弟老有是一子，死以屬我。」〔四〕於是為之垂涕歎息，良久曰：「法令者，先帝所造也，用弟故而誣先帝之法，吾何面目入高廟乎！又下負萬民。」乃可其奏，哀不能自止，左右盡悲。朔前上壽，曰：「臣聞聖王為政，賞不避仇讎，誅不擇骨肉。書曰：『不偏不黨，王道蕩蕩。』〔五〕此二者，五帝所重，三王所難也。陛下行之，是以四海之內元元之民各得其所，天下幸甚！臣朔奉觴，昧死再拜上萬歲壽。」上乃起，入省中，夕時召讓朔，〔六〕曰：「傳曰『時然後言，人不厭其言』。〔七〕今先生上壽，時乎？」〔八〕朔免冠頓首曰：「臣聞樂太甚則陽溢，哀太甚則陰損，陰陽變則心氣動，心氣動則精神散，精神散而邪氣及。銷憂者莫若酒，臣朔所以上壽者，明陛下正而不阿，因以止哀也。愚不知忌諱，當死。」先是，朔嘗醉入殿中，小遺殿上，〔九〕劾不敬。有詔免為庶人，待詔宦者署，因此（時）〔對〕復為中郎，賜帛百匹。","sentenceOrder":94},
  {"id":"s_work_han_thu_78_95","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「慮音廬。」","sentenceOrder":95},
  {"id":"s_work_han_thu_78_96","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　服虔曰：「主傅，主之官也。」如淳曰：「禮有傅姆。說者又曰傅者老大夫也，漢使中行說傅翁主也。」師古曰：「傅姆是也。服說失之。內官，署名，解在律曆志。」","sentenceOrder":96},
  {"id":"s_work_han_thu_78_97","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「論決其罪也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_78_98","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　師古曰：「老乃有子，言其晚孕育也。屬音之欲反。」","sentenceOrder":98},
  {"id":"s_work_han_thu_78_99","chapterId":"ch_work_han_thu_78","textTraditional":"〔五〕　師古曰：「周書洪範之辭也。蕩蕩，平坦之貌。」","sentenceOrder":99},
  {"id":"s_work_han_thu_78_100","chapterId":"ch_work_han_thu_78","textTraditional":"〔六〕　師古曰：「讓，責也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_78_101","chapterId":"ch_work_han_thu_78","textTraditional":"〔七〕　師古曰：「論語稱孔子問公叔文子於公明賈曰：『信乎夫子不言不笑不取乎？』對曰：『夫子時然後言，人不厭其言；樂然後笑，人不厭其笑。義然後取，人不厭其取。』」","sentenceOrder":101},
  {"id":"s_work_han_thu_78_102","chapterId":"ch_work_han_thu_78","textTraditional":"〔八〕　師古曰：「言所上壽豈謂時乎？」","sentenceOrder":102},
  {"id":"s_work_han_thu_78_103","chapterId":"ch_work_han_thu_78","textTraditional":"〔九〕　師古曰：「小遺者，小便也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_78_104","chapterId":"ch_work_han_thu_78","textTraditional":"初，帝姑館陶公主號竇太主，〔一〕堂邑侯陳午尚之。午死，主寡居，年五十餘矣，近幸董偃。始偃與母以賣珠為事，偃年十三，隨母出入主家。左右言其姣好，〔二〕主召見，曰：「吾為母養之。」因留第中，教書計相馬御射，〔三〕頗讀傳記。至年十八而冠，出則執轡，入則侍內。為人溫柔愛人，以主故，諸公接之，名稱城中，號曰董君。主因推令散財交士，令中府曰：〔四〕「董君所發，一日金滿百斤，錢滿百萬，帛滿千匹，乃白之。」〔五〕安陵爰叔者，爰盎兄子也，與偃善，謂偃曰：「足下私侍漢主，挾不測之罪，將欲安處乎？」〔六〕偃懼曰：「憂之久矣，不知所以。」〔七〕爰叔曰：「顧城廟遠無宿宮，又有萩竹籍田，〔八〕足下何不白主獻長門園〔九〕？此上所欲也。如是，上知計出於足下也，則安枕而臥，長無慘怛之憂。久之不然，上且請之，於足下何如？」偃頓首曰：「敬奉教。」入言之主，主立奏書獻之。上大說，〔一０〕更名竇太主園為長門宮。主大喜，使偃以黃金百斤為爰叔壽。","sentenceOrder":104},
  {"id":"s_work_han_thu_78_105","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　如淳曰：「竇太后之女也，故曰竇太主也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_78_106","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「姣，美麗也，音狡。」","sentenceOrder":106},
  {"id":"s_work_han_thu_78_107","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「計謂用算也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_78_108","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　師古曰：「中府，掌金帛之臧者也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_78_109","chapterId":"ch_work_han_thu_78","textTraditional":"〔五〕　師古曰：「言不滿此數者，皆恣與之。」","sentenceOrder":109},
  {"id":"s_work_han_thu_78_110","chapterId":"ch_work_han_thu_78","textTraditional":"〔六〕　師古曰：「不測者，言其深也。安處，何以自安處也。一曰，身挾大罪，乃欲自安而居處者乎？」","sentenceOrder":110},
  {"id":"s_work_han_thu_78_111","chapterId":"ch_work_han_thu_78","textTraditional":"〔七〕　師古曰：「以，用也。不知用何計也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_78_112","chapterId":"ch_work_han_thu_78","textTraditional":"〔八〕　如淳曰：「其間雖有地，皆有萩竹籍田，無可作宿觀也。」師古曰：「如說非也。萩即楸字也。言有楸樹及竹林可遊玩，而籍田所在，上又須躬親行事，當有宿宮，故宜獻此園。」","sentenceOrder":112},
  {"id":"s_work_han_thu_78_113","chapterId":"ch_work_han_thu_78","textTraditional":"〔九〕　如淳曰：「竇太主園在長門。長門在長安城東南。園可以為宿館處所，故獻之。」","sentenceOrder":113},
  {"id":"s_work_han_thu_78_114","chapterId":"ch_work_han_thu_78","textTraditional":"〔一０〕師古曰：「說讀曰悅。」","sentenceOrder":114},
  {"id":"s_work_han_thu_78_115","chapterId":"ch_work_han_thu_78","textTraditional":"叔因是為董君畫求見上之策，令主稱疾不朝。上往臨疾，問所欲，主辭謝曰：「妾幸蒙陛下厚恩，先帝遺德，奉朝請之禮，備臣妾之儀，〔一〕列為公主，賞賜邑入，〔二〕隆天重地，死無以塞責〔三〕。一日卒有不勝洒掃之職，〔四〕先狗馬填溝壑，竊有所恨，不勝大願，願陛下時忘萬事，養精游神，從中掖庭回輿，枉路臨妾山林，〔五〕得獻觴上壽，娛樂左右。如是而死，何恨之有！」上曰：「主何憂？幸得愈。恐群臣從官多，大為主費。」上還。有頃，主疾愈，起謁，上以錢千萬從主飲。後數日，上臨山林，主自執宰敝膝，〔六〕道入登階就坐。坐未定，上曰：「願謁主人翁。」主乃下殿，去簪珥，〔七〕徒跣頓首謝曰：「妾無狀，〔八〕負陛下，身當伏誅。陛下不致之法，頓首死罪。」有詔謝。主簪履起，之東箱自引董君〔九〕。董君綠幘傅韝，〔一０〕隨主前，伏殿下。主乃贊：「〔一一〕館陶公主胞人臣偃昧死再拜謁。」〔一二〕因叩頭謝，上為之起。有詔賜衣冠上。〔一三〕偃起，走就衣冠。主自奉食進觴。當是時，董君見尊不名，稱為「主人翁」，飲大驩樂。主乃請賜將軍列侯從官金錢雜繒各有數。於是董君貴寵，天下莫不聞。郡國狗馬蹴鞠劍客輻湊〔一四〕董氏。常從游戲北宮，馳逐平樂，觀雞鞠之會，角狗馬之足，〔一五〕上大歡樂之。於是上為竇太主置酒宣室，使謁者引內董君。","sentenceOrder":115},
  {"id":"s_work_han_thu_78_116","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「請音才姓反。」","sentenceOrder":116},
  {"id":"s_work_han_thu_78_117","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「既別得賞賜，又所食之邑入其租賦也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_78_118","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「塞，補也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_78_119","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　師古曰：「卒讀曰猝。洒音信，又音山豉反。」","sentenceOrder":119},
  {"id":"s_work_han_thu_78_120","chapterId":"ch_work_han_thu_78","textTraditional":"〔五〕　應劭曰：「公主園中有山，謙不敢稱第，故託山林也。」服虔曰：「主所豫作廟陵，故曰山林。」師古曰：「山林，應說是也。不當請帝臨其冢墓也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_78_121","chapterId":"ch_work_han_thu_78","textTraditional":"〔六〕　師古曰：「為賤者之服。」","sentenceOrder":121},
  {"id":"s_work_han_thu_78_122","chapterId":"ch_work_han_thu_78","textTraditional":"〔七〕　師古曰：「珥，珠玉飾耳者也，音餌。」","sentenceOrder":122},
  {"id":"s_work_han_thu_78_123","chapterId":"ch_work_han_thu_78","textTraditional":"〔八〕　師古曰：「狀，形貌也。無狀，猶言無顏面以見人也。一曰，自言所行醜惡無善狀。」","sentenceOrder":123},
  {"id":"s_work_han_thu_78_124","chapterId":"ch_work_han_thu_78","textTraditional":"〔九〕　師古曰：「之，往也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_78_125","chapterId":"ch_work_han_thu_78","textTraditional":"〔一０〕應劭曰：「宰人服也。」韋昭曰：「韝形如射韝，以縛左右手，於事便也。」師古曰：「綠幘，賤人之服也。傅，著也。韝即今之臂韝也。傅讀曰附。韝音工侯反。」","sentenceOrder":125},
  {"id":"s_work_han_thu_78_126","chapterId":"ch_work_han_thu_78","textTraditional":"〔一一〕師古曰：「贊，進也。進傳謁辭。」","sentenceOrder":126},
  {"id":"s_work_han_thu_78_127","chapterId":"ch_work_han_thu_78","textTraditional":"〔一二〕師古曰：「胞與庖同。」","sentenceOrder":127},
  {"id":"s_work_han_thu_78_128","chapterId":"ch_work_han_thu_78","textTraditional":"〔一三〕師古曰：「上，上坐。」","sentenceOrder":128},
  {"id":"s_work_han_thu_78_129","chapterId":"ch_work_han_thu_78","textTraditional":"〔一四〕師古曰：「蹴音千六反。鞠音鉅六反。解在藝文志。」","sentenceOrder":129},
  {"id":"s_work_han_thu_78_130","chapterId":"ch_work_han_thu_78","textTraditional":"〔一五〕師古曰：「角猶校也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_78_131","chapterId":"ch_work_han_thu_78","textTraditional":"是時，朔陛戟殿下，〔一〕辟戟而前曰：〔二〕「董偃有斬罪三，安得入乎？」上曰：「何謂也？」朔曰：「偃以人臣私侍公主，其罪一也。敗男女之化，而亂婚姻之禮，傷王制，其罪二也。陛下富於春秋，方積思於六經，留神於王事，馳騖於唐虞，折節於三代，偃不遵經勸學，反以靡麗為右，奢侈為務，〔三〕盡狗馬之樂，極耳目之欲，行邪枉之道，徑淫辟之路，〔四〕是乃國家之大賊，人主之大蜮。〔五〕偃為淫首，其罪三也。昔伯姬燔而諸侯憚，〔六〕奈何乎陛下？」上默然不應，良久曰：「吾業以設飲，後而自改。」朔曰：「不可。夫宣室者，先帝之正處也，非法度之政不得入焉。故淫亂之漸，其變為篡，是以豎貂為淫而易牙作患，〔七〕慶父死而魯國全〔八〕，管蔡誅而周室安。」上曰：「善。」有詔止，更置酒北宮，引董君從東司馬門。東司馬門更名東交門。〔九〕賜朔黃金三十斤。董君之寵由是日衰，至年三十而終。後數歲，竇太主卒，與董君會葬於霸陵。是後，公主貴人多踰禮制，自董偃始。","sentenceOrder":131},
  {"id":"s_work_han_thu_78_132","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「持戟列陛側。」","sentenceOrder":132},
  {"id":"s_work_han_thu_78_133","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「辟音頻亦反。」","sentenceOrder":133},
  {"id":"s_work_han_thu_78_134","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「右，尊也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_78_135","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　師古曰：「徑，由也。辟讀曰僻。」","sentenceOrder":135},
  {"id":"s_work_han_thu_78_136","chapterId":"ch_work_han_thu_78","textTraditional":"〔五〕　師古曰：「蜮，魅也，音或。說者以為短狐，非也。短狐，射工耳，於此不當其義。今俗猶（河）〔云〕魅蜮也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_78_137","chapterId":"ch_work_han_thu_78","textTraditional":"〔六〕　應劭曰：「憚，敬也。敬其節直也。」師古曰：「伯姬，宋恭姬也。遇火災，待姆不出而死也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_78_138","chapterId":"ch_work_han_thu_78","textTraditional":"〔七〕　師古曰：「豎貂、易牙皆齊桓公臣也。管仲有病，桓公往問之曰：『將何以教寡人？』管仲曰：『願君之遠易牙、豎貂。』公曰：『易牙亨其子以快寡人，尚可疑邪？』對曰：『人之情非不愛其子，其子之忍，又將何有於君？』公曰：『豎貂自宮以近寡人，猶可疑邪？』對曰：『人之情非不愛其身也，其身之忍，又將何有於君？』公曰：『諾。』管仲死，盡逐之，而公食不甘，宮不治。居三年，公曰：『仲父不亦過乎？』於是皆復召，即反之。明年，公有病，易牙、豎貂相與作亂，塞宮門，築高牆，不通人。有一婦人踰垣入，至公所。公曰：『我欲食。』婦人曰：『吾無所得。』又曰：『我欲飲。』婦人曰：『吾無所得。』公曰：『何故？』對曰：『易牙、豎貂相與作亂，塞宮門，築高牆，不通人，故無所得。』公慨然歎涕出，曰：『嗟乎！聖人所見豈不遠哉？若死者有知，我將何面目見仲父乎！』蒙衣袂而絕乎壽宮，蟲流出於戶，蓋以楊門之扉，三月不葬。」","sentenceOrder":138},
  {"id":"s_work_han_thu_78_139","chapterId":"ch_work_han_thu_78","textTraditional":"〔八〕　師古曰：「慶父，魯桓公子，莊公弟也。莊公薨，慶父殺莊公之子閔公而欲作亂，不克，奔莒。其後僖公立，以賂求之於莒，莒人歸之，及密乃縊而死。僖公乃定其位。」","sentenceOrder":139},
  {"id":"s_work_han_thu_78_140","chapterId":"ch_work_han_thu_78","textTraditional":"〔九〕　蘇林曰：「以偃從此門入，交會於內，故以名焉。」","sentenceOrder":140},
  {"id":"s_work_han_thu_78_141","chapterId":"ch_work_han_thu_78","textTraditional":"時天下侈靡趨末，〔一〕百姓多離農畝。上從容問朔：「吾欲化民，豈有道乎？」〔二〕朔對曰：「堯舜禹湯文武成康上古之事，經歷數千載，尚難言也，臣不敢陳。願近述孝文皇帝之時，當世耆老皆聞見之。貴為天（下）〔子〕，富有四海，身衣弋綈，〔三〕足履革舄，〔四〕以韋帶劍，〔五〕莞蒲為席，〔六〕兵木無刃，〔七〕衣縕無文，〔八〕集上書囊以為殿帷；〔九〕以道德為麗，以仁義為準。〔一０〕於是天下望風成俗，昭然化之。今陛下以城中為小，圖起建章，左鳳闕，右神明，〔一一〕號稱千門萬戶；木土衣綺繡，狗馬被繢罽；〔一二〕宮人簪玳瑁，垂珠璣；〔一三〕設戲車，教馳逐，飾文采，藂珍怪；〔一四〕撞萬石之鐘，擊雷霆之鼓，〔一五〕作俳優，舞鄭女。上為淫侈如此，而欲使民獨不奢侈失農，事之難者也。〔一六〕陛下誠能用臣朔之計，推甲乙之帳燔之於四通之衢，〔一七〕卻走馬示不復用，〔一八〕則堯舜之隆宜可與比治矣。易曰：『正其本，萬事理；失之豪氂，差以千里。』〔一九〕願陛下留意察之。」","sentenceOrder":141},
  {"id":"s_work_han_thu_78_142","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「趨讀曰趣。末謂工商之業。」","sentenceOrder":142},
  {"id":"s_work_han_thu_78_143","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「從音千容反。」’","sentenceOrder":143},
  {"id":"s_work_han_thu_78_144","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「弋，黑色也。綈，厚繒，音徒奚反。」","sentenceOrder":144},
  {"id":"s_work_han_thu_78_145","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　師古曰：「革，生皮也。不用柔韋，言儉率也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_78_146","chapterId":"ch_work_han_thu_78","textTraditional":"〔五〕　師古曰：「但空用韋，不加飾。」","sentenceOrder":146},
  {"id":"s_work_han_thu_78_147","chapterId":"ch_work_han_thu_78","textTraditional":"〔六〕　師古曰：「莞，夫離也，今謂之蔥蒲。以莞及蒲為席，亦尚質也。莞音完，又音官。」","sentenceOrder":147},
  {"id":"s_work_han_thu_78_148","chapterId":"ch_work_han_thu_78","textTraditional":"〔七〕　服虔曰：「兵器如木而無刃，言不大治兵器也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_78_149","chapterId":"ch_work_han_thu_78","textTraditional":"〔八〕　師古曰：「縕，亂絮也。言內有亂絮，上無文綵也。縕音於粉反。」","sentenceOrder":149},
  {"id":"s_work_han_thu_78_150","chapterId":"ch_work_han_thu_78","textTraditional":"〔九〕　師古曰：「集謂合聚也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_78_151","chapterId":"ch_work_han_thu_78","textTraditional":"〔一０〕師古曰：「麗，美也。準，平法也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_78_152","chapterId":"ch_work_han_thu_78","textTraditional":"〔一一〕如淳曰：「闕名也。」師古曰：「鳳闕，闕名。神明，臺名也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_78_153","chapterId":"ch_work_han_thu_78","textTraditional":"〔一二〕師古曰：「繢，五綵也。罽，織毛也，即氍毹之屬。」","sentenceOrder":153},
  {"id":"s_work_han_thu_78_154","chapterId":"ch_work_han_thu_78","textTraditional":"〔一三〕師古曰：「玳瑁，文甲也。璣，珠之不圜者。玳音代。瑁音昧。璣音居依反，又音鉅依反。」","sentenceOrder":154},
  {"id":"s_work_han_thu_78_155","chapterId":"ch_work_han_thu_78","textTraditional":"〔一四〕師古曰：「樷，古藂字。」","sentenceOrder":155},
  {"id":"s_work_han_thu_78_156","chapterId":"ch_work_han_thu_78","textTraditional":"〔一五〕師古曰：「言其聲震大也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_78_157","chapterId":"ch_work_han_thu_78","textTraditional":"〔一六〕師古曰：「失農謂失農業也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_78_158","chapterId":"ch_work_han_thu_78","textTraditional":"〔一七〕應劭曰：「帳多故以甲乙第之耳。」孟康曰：「西域傳贊云『興造甲乙之帳，絡以隨珠和璧，天子襲翠被，憑玉几，而處其中』也。」師古曰：「謂推而去之。燔，焚燒也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_78_159","chapterId":"ch_work_han_thu_78","textTraditional":"〔一八〕師古曰：「卻，退也。走馬，善走之馬也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_78_160","chapterId":"ch_work_han_thu_78","textTraditional":"〔一九〕師古曰：「今易無此文，已解於上也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_78_161","chapterId":"ch_work_han_thu_78","textTraditional":"朔雖詼笑，〔一〕然時觀察顏色，直言切諫，上常用之。自公卿在位，朔皆敖弄，無所為屈。〔二〕","sentenceOrder":161},
  {"id":"s_work_han_thu_78_162","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「詼，謿戲也。詼笑，謂謿謔，發言可笑也。詼音恢。其下詼啁、詼諧並同。」","sentenceOrder":162},
  {"id":"s_work_han_thu_78_163","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「敖讀曰傲。為音于偽反。」","sentenceOrder":163},
  {"id":"s_work_han_thu_78_164","chapterId":"ch_work_han_thu_78","textTraditional":"上以朔口諧辭給，〔一〕好作問之。〔二〕嘗問朔曰：「先生視朕何如主也？」朔對曰：「自唐虞之隆，成康之際，未足以諭當世。臣伏觀陛下功德，陳五帝之上，在三王之右。〔三〕非若此而已，誠得天下賢士，公卿在位咸得其人矣。譬若以周邵為丞相，〔四〕孔丘為御史大夫，〔五〕太公為將軍，〔六〕畢公高拾遺於後，〔七〕弁嚴子為衛尉，〔八〕皋陶為大理，〔九〕后稷為司農，〔一０〕伊尹為少府，〔一一〕子贛使外國，〔一二〕顏閔為博士，〔一三〕子夏為太常，〔一四〕益為右扶風，〔一五〕季路為執金吾，〔一六〕契為鴻臚，〔一七〕龍逢為宗正，〔一八〕伯夷為京兆，〔一九〕管仲為馮翊，〔二０〕魯般為將作，〔二一〕仲山甫為光祿，〔二二〕申伯為太僕，〔二三〕延陵季子為水衡，〔二四〕百里奚為典屬國〔二五〕，柳下惠為大長秋，〔二六〕史魚為司直，〔二七〕蘧伯玉為太傅，〔二八〕孔父為詹事，〔二九〕孫叔敖為諸侯相，子產為郡守，〔三０〕王慶忌為期門，〔三一〕夏育為鼎官，〔三二〕羿為旄頭，〔三三〕宋萬為式道候。」〔三四〕上乃大笑。","sentenceOrder":164},
  {"id":"s_work_han_thu_78_165","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「給，捷也。」","sentenceOrder":165},
  {"id":"s_work_han_thu_78_166","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「故動作之而問以言辭也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_78_167","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「右亦高上也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_78_168","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　師古曰：「周公旦、邵公奭二人也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_78_169","chapterId":"ch_work_han_thu_78","textTraditional":"〔五〕　應劭曰：「御史大夫職典制度文章。」","sentenceOrder":169},
  {"id":"s_work_han_thu_78_170","chapterId":"ch_work_han_thu_78","textTraditional":"〔六〕　師古曰：「太公，呂望也。知戰陳征伐之事，故云為將軍。」","sentenceOrder":170},
  {"id":"s_work_han_thu_78_171","chapterId":"ch_work_han_thu_78","textTraditional":"〔七〕　師古曰：「畢公高，文王之子也，為周太師，故云拾遺也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_78_172","chapterId":"ch_work_han_thu_78","textTraditional":"〔八〕　師古曰：「以其有勇。」","sentenceOrder":172},
  {"id":"s_work_han_thu_78_173","chapterId":"ch_work_han_thu_78","textTraditional":"〔九〕　師古曰：「以其作士，士亦理官。」","sentenceOrder":173},
  {"id":"s_work_han_thu_78_174","chapterId":"ch_work_han_thu_78","textTraditional":"〔一０〕師古曰：「主播種。」","sentenceOrder":174},
  {"id":"s_work_han_thu_78_175","chapterId":"ch_work_han_thu_78","textTraditional":"〔一一〕應劭曰：「伊尹善亨割，大官屬少府，故令作之也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_78_176","chapterId":"ch_work_han_thu_78","textTraditional":"〔一二〕師古曰：「以其有辯說。」","sentenceOrder":176},
  {"id":"s_work_han_thu_78_177","chapterId":"ch_work_han_thu_78","textTraditional":"〔一三〕師古曰：「顏回、閔子騫為皆有德行也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_78_178","chapterId":"ch_work_han_thu_78","textTraditional":"〔一四〕師古曰：「以有文學故為太常也。而應劭（曰）以子夏兩字總合為夔，解云夔知樂，故可以為太常，此說非也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_78_179","chapterId":"ch_work_han_thu_78","textTraditional":"〔一五〕應劭曰：「益作舜虞，掌山澤之官也。諸苑多在右扶風，故令作之。」","sentenceOrder":179},
  {"id":"s_work_han_thu_78_180","chapterId":"ch_work_han_thu_78","textTraditional":"〔一六〕師古曰：「亦以有勇力。」","sentenceOrder":180},
  {"id":"s_work_han_thu_78_181","chapterId":"ch_work_han_thu_78","textTraditional":"〔一七〕應劭曰：「卨作司徒，敬敷五教。是時諸侯王治民，鴻臚主諸侯王也。」師古曰：「契讀與卨同，字本作偰，蓋後從省耳。」","sentenceOrder":181},
  {"id":"s_work_han_thu_78_182","chapterId":"ch_work_han_thu_78","textTraditional":"〔一八〕師古曰：「關龍逢，桀之臣也，忠諫而死也。以其直，無所阿私。」","sentenceOrder":182},
  {"id":"s_work_han_thu_78_183","chapterId":"ch_work_han_thu_78","textTraditional":"〔一九〕應劭曰：「帝曰『伯夷，汝作秩宗。』秩宗，主郊廟。京兆與太常同典齋祀，故令為之。」","sentenceOrder":183},
  {"id":"s_work_han_thu_78_184","chapterId":"ch_work_han_thu_78","textTraditional":"〔二０〕應劭曰：「管仲定民之居，寄軍令於內政，終令匡霸，故令為馮翊也。」","sentenceOrder":184},
  {"id":"s_work_han_thu_78_185","chapterId":"ch_work_han_thu_78","textTraditional":"〔二一〕師古曰：「以其巧也。般與班同。」","sentenceOrder":185},
  {"id":"s_work_han_thu_78_186","chapterId":"ch_work_han_thu_78","textTraditional":"〔二二〕晉灼曰：「光祿，主三大夫諫正之官，取其柔亦不茹，剛亦不吐。」","sentenceOrder":186},
  {"id":"s_work_han_thu_78_187","chapterId":"ch_work_han_thu_78","textTraditional":"〔二三〕應劭曰：「申伯，周宣王之舅也。太僕主大駕親御，職又密近，故用親親也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_78_188","chapterId":"ch_work_han_thu_78","textTraditional":"〔二四〕應劭曰：「水衡主池苑。季子，吳人，故使為之。」師古曰：「季子即吳公子札。」","sentenceOrder":188},
  {"id":"s_work_han_thu_78_189","chapterId":"ch_work_han_thu_78","textTraditional":"〔二五〕應劭曰：「奚，秦人。秦近西戎，曉其風俗，故令為之。」","sentenceOrder":189},
  {"id":"s_work_han_thu_78_190","chapterId":"ch_work_han_thu_78","textTraditional":"〔二六〕師古曰：「惠，魯大夫展禽也。食采柳下，諡曰惠。以其貞絜，故為大長秋。」","sentenceOrder":190},
  {"id":"s_work_han_thu_78_191","chapterId":"ch_work_han_thu_78","textTraditional":"〔二七〕師古曰：「史魚，衛大夫史鰌也。論語稱孔子曰『直哉史魚，邦有道如矢，邦無道如矢』。」","sentenceOrder":191},
  {"id":"s_work_han_thu_78_192","chapterId":"ch_work_han_thu_78","textTraditional":"〔二八〕如淳曰：「太傅傅人主使無過。伯玉欲寡其過，故令為之。」師古曰：「蘧伯玉，衛大夫也，名瑗。蘧音渠。」","sentenceOrder":192},
  {"id":"s_work_han_thu_78_193","chapterId":"ch_work_han_thu_78","textTraditional":"〔二九〕應劭曰：「孔父正色而立於朝，則莫敢過而致難乎其君，故為詹事。」師古曰：「孔父，宋大夫也。父讀曰甫。」","sentenceOrder":193},
  {"id":"s_work_han_thu_78_194","chapterId":"ch_work_han_thu_78","textTraditional":"〔三０〕師古曰：「善治邦邑也。」","sentenceOrder":194},
  {"id":"s_work_han_thu_78_195","chapterId":"ch_work_han_thu_78","textTraditional":"〔三一〕應劭曰：「以其勁捷，可為期門郎也。」師古曰：「王慶忌即王子慶忌也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_78_196","chapterId":"ch_work_han_thu_78","textTraditional":"〔三二〕（或）師古曰：「夏育，衛人，力舉千鈞。鼎官，今殿前舉鼎者也。」","sentenceOrder":196},
  {"id":"s_work_han_thu_78_197","chapterId":"ch_work_han_thu_78","textTraditional":"〔三三〕應劭曰：「羿善射，故令為旄頭。今以羽林為之，髮正上向而長衣繡衣，在乘輿車前。」師古曰：「羿音詣。」","sentenceOrder":197},
  {"id":"s_work_han_thu_78_198","chapterId":"ch_work_han_thu_78","textTraditional":"〔三四〕師古曰：「萬，宋閔公臣，亦有勇力也。式，表也。表道之候，若今之武候引駕。」","sentenceOrder":198},
  {"id":"s_work_han_thu_78_199","chapterId":"ch_work_han_thu_78","textTraditional":"是時朝廷多賢材，上復問朔：「方今公孫丞相、兒大夫、〔一〕董仲舒、夏侯始昌、司馬相如、吾丘壽王、主父偃、朱買臣、嚴助、汲黯、膠倉、終軍、嚴安、徐樂、司馬遷之倫，皆辯知閎達，溢于文辭，〔二〕先生自視，何與比哉？」〔三〕朔對曰：「臣觀其臿齒牙，樹頰胲，〔四〕吐脣吻，擢項頤，〔五〕結股腳，連脽尻，〔六〕遺蛇其跡，行步偊旅，〔七〕臣朔雖不肖，尚兼此數子者。」朔之進對澹辭，皆此類也。〔八〕","sentenceOrder":199},
  {"id":"s_work_han_thu_78_200","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「公孫弘及兒寬也。兒音五奚反。」","sentenceOrder":200},
  {"id":"s_work_han_thu_78_201","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「溢者，言其有餘也。」","sentenceOrder":201},
  {"id":"s_work_han_thu_78_202","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「何與猶言何如也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_78_203","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　師古曰：「頰肉曰胲，音改。」","sentenceOrder":203},
  {"id":"s_work_han_thu_78_204","chapterId":"ch_work_han_thu_78","textTraditional":"〔五〕　師古曰：「頤，頷下也，音怡。」","sentenceOrder":204},
  {"id":"s_work_han_thu_78_205","chapterId":"ch_work_han_thu_78","textTraditional":"〔六〕　師古曰：「脽，臂也，音誰。」","sentenceOrder":205},
  {"id":"s_work_han_thu_78_206","chapterId":"ch_work_han_thu_78","textTraditional":"〔七〕　師古曰：「遺蛇猶逶迱也。偊旅，曲躬貌也。蛇音移。偊音禹。」","sentenceOrder":206},
  {"id":"s_work_han_thu_78_207","chapterId":"ch_work_han_thu_78","textTraditional":"〔八〕　師古曰：「澹，古贍字也。贍，給也。」","sentenceOrder":207},
  {"id":"s_work_han_thu_78_208","chapterId":"ch_work_han_thu_78","textTraditional":"武帝既招英俊，程其器能，用之如不及。〔一〕時方外事胡越，內興制度，國家多事，自公孫弘以下至司馬遷皆奉使方外，或為郡國守相至公卿，而朔嘗至太中大夫，後常為郎，與枚皋、郭舍人俱在左右，詼啁而已。〔二〕久之，朔上書陳農戰彊國之計，因自訟獨不得大官，欲求試用。其言專商鞅、韓非之語也，指意放蕩，頗復詼諧，辭數萬言，終不見用。朔因著論，設客難己，用位卑以自慰諭。其辭曰：","sentenceOrder":208},
  {"id":"s_work_han_thu_78_209","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「程謂量計之也。如不及者，恐失之也。」","sentenceOrder":209},
  {"id":"s_work_han_thu_78_210","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「啁與謿同，音竹交反。」","sentenceOrder":210},
  {"id":"s_work_han_thu_78_211","chapterId":"ch_work_han_thu_78","textTraditional":"客難東方朔曰：「蘇秦、張儀一當萬乘之主，而都卿相之位，〔一〕澤及後世。今子大夫修先王之術，慕聖人之義，諷誦詩書百家之言，不可勝數，著於竹帛，脣腐齒落，服膺而不釋，〔二〕好學樂道之效，明白甚矣；自以智能海內無雙，則可謂博聞辯智矣。然悉力盡忠以事聖帝，曠日持久，官不過侍郎，位不過執戟，意者尚有遺行邪？〔三〕同胞之徒無所容居，其故何也？」〔四〕","sentenceOrder":211},
  {"id":"s_work_han_thu_78_212","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　如淳曰：「都，居也。」","sentenceOrder":212},
  {"id":"s_work_han_thu_78_213","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「服膺，俯服其胸臆也。釋，廢置也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_78_214","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「可遺之行，言不盡（言）〔善〕也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_78_215","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　蘇林曰：「胞音胞胎之胞也，言親兄弟。」","sentenceOrder":215},
  {"id":"s_work_han_thu_78_216","chapterId":"ch_work_han_thu_78","textTraditional":"東方先生喟然長息，仰而應之曰：「是固非子之所能備也。彼一時也，此一時也，豈可同哉？夫蘇秦、張儀之時，周室大壞，諸侯不朝，力政爭權，相禽以兵，并為十二國，未有雌雄，〔一〕得士者彊，失士者亡，故談說行焉。身處尊位，珍寶充內，外有廩倉，澤及後世，子孫長享。今則不然。聖帝流德，天下震懾，諸侯賓服〔二〕，連四海之外以為帶，〔三〕安於覆盂，〔四〕動猶運之掌，〔五〕賢不肖何以異哉？遵天之道，順地之理，物無不得其所；故綏之則安，動之則苦；尊之則為將，卑之則為虜；抗之則在青雲之上，抑之則在深泉之下；用之則為虎，不用則為鼠；雖欲盡節效情，安知前後？夫天地之大，士民之眾，竭精談說，並進輻湊者不可勝數，悉力募之，困於衣食，或失門戶。〔六〕使蘇秦、張儀與僕並生於今之世，曾不得掌故，安敢望常侍郎乎！故曰時異事異。","sentenceOrder":216},
  {"id":"s_work_han_thu_78_217","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「十二國，謂魯、衛、齊、楚、宋、鄭、魏、燕、趙、中山、秦、韓也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_78_218","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「懾，恐也，音之涉反。」","sentenceOrder":218},
  {"id":"s_work_han_thu_78_219","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「言如帶之相連也。」","sentenceOrder":219},
  {"id":"s_work_han_thu_78_220","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　師古曰：「言不可傾搖。」","sentenceOrder":220},
  {"id":"s_work_han_thu_78_221","chapterId":"ch_work_han_thu_78","textTraditional":"〔五〕　師古曰：「言至易。」","sentenceOrder":221},
  {"id":"s_work_han_thu_78_222","chapterId":"ch_work_han_thu_78","textTraditional":"〔六〕　師古曰：「言不得所由入也。一曰，謂被誅戮，喪其家室也。」","sentenceOrder":222},
  {"id":"s_work_han_thu_78_223","chapterId":"ch_work_han_thu_78","textTraditional":"「雖然，安可以不務修身乎哉！詩云：『鼓鐘于宮，聲聞于外。』〔一〕『鶴鳴于九皋，聲聞于天。』〔二〕苟能修身，何患不榮！太公體行仁義，七十有二（延）〔乃〕設用於文武，得信厥說，〔三〕封於齊，七百歲而不絕。此士所以日夜孳孳，敏行而不敢怠也。〔四〕辟若鶺鴒，飛且鳴矣。〔五〕傳曰：『天不為人之惡寒而輟其冬，〔六〕地不為人之惡險而輟其廣，君子不為小人之匈匈而易其行。』〔七〕『天有常度，地有常形，君子有常行；君子道其常，小人計其功。』〔八〕詩云：『禮義之不愆，何恤人之言？』〔九〕故曰：『水至清則無魚，人至察則無徒，〔一０〕冕而前旒，所以蔽明；黈纊充耳，所以塞聰。』〔一一〕明有所不見，聰有所不聞，舉大德，赦小過，無求備於一人之義也。〔一二〕枉而直之，使自得之；優而柔之，使自求之；揆而度之，使自索之。〔一三〕蓋聖人教化如此，欲自得之；自得之，則敏且廣矣。〔一四〕","sentenceOrder":223},
  {"id":"s_work_han_thu_78_224","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「小雅白華之詩也。言苟有於中，必形於外也。」","sentenceOrder":224},
  {"id":"s_work_han_thu_78_225","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「小雅鶴鳴之詩也。言處卑而聲徹其高遠。」","sentenceOrder":225},
  {"id":"s_work_han_thu_78_226","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「設，施也。信讀曰伸。」","sentenceOrder":226},
  {"id":"s_work_han_thu_78_227","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　師古曰：「孳與孜同。敏，勉也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_78_228","chapterId":"ch_work_han_thu_78","textTraditional":"〔五〕　師古曰：「鶺鴒，雍渠，小青雀也，飛則鳴，行則搖，言其勤苦也。辟讀曰譬。鶺音脊。鴒音零。」","sentenceOrder":228},
  {"id":"s_work_han_thu_78_229","chapterId":"ch_work_han_thu_78","textTraditional":"〔六〕　師古曰：「輟，止也。」","sentenceOrder":229},
  {"id":"s_work_han_thu_78_230","chapterId":"ch_work_han_thu_78","textTraditional":"〔七〕　師古曰：「匈匈，讙議之聲。」","sentenceOrder":230},
  {"id":"s_work_han_thu_78_231","chapterId":"ch_work_han_thu_78","textTraditional":"〔八〕　師古曰：「道，由也。」","sentenceOrder":231},
  {"id":"s_work_han_thu_78_232","chapterId":"ch_work_han_thu_78","textTraditional":"〔九〕　師古曰：「逸詩也。愆，過也。恤，憂也。」","sentenceOrder":232},
  {"id":"s_work_han_thu_78_233","chapterId":"ch_work_han_thu_78","textTraditional":"〔一０〕師古曰：「徒，眾也。」","sentenceOrder":233},
  {"id":"s_work_han_thu_78_234","chapterId":"ch_work_han_thu_78","textTraditional":"〔一一〕如淳曰：「黈音工苟反。謂以玉為瑱，用黈纊縣之也。」師古曰：「如說非也。黈，黃色也。纊，綿也。以黃綿為丸，用組懸之於冕，垂兩耳旁，示不外聽，非玉瑱之縣也。」","sentenceOrder":234},
  {"id":"s_work_han_thu_78_235","chapterId":"ch_work_han_thu_78","textTraditional":"〔一二〕師古曰：「論語仲弓問政於孔子，孔子曰：『赦小過，舉賢才。』周公謂魯公曰：『故舊無大故，則不棄也，毋求備於一人。』故朔引此言也。士有百行，功過相除，不可求備也。」","sentenceOrder":235},
  {"id":"s_work_han_thu_78_236","chapterId":"ch_work_han_thu_78","textTraditional":"〔一三〕師古曰：「枉，曲也。索亦求也。度音徒各反。」","sentenceOrder":236},
  {"id":"s_work_han_thu_78_237","chapterId":"ch_work_han_thu_78","textTraditional":"〔一四〕師古曰：「敏，疾也。」","sentenceOrder":237},
  {"id":"s_work_han_thu_78_238","chapterId":"ch_work_han_thu_78","textTraditional":"「今世之處士，魁然無徒，廓然獨居，〔一〕上觀許由，下察接輿，計同范蠡，忠合子胥，〔二〕天下和平，與義相扶，寡耦少徒，固其宜也，〔三〕子何疑於我哉？若夫燕之用樂毅，秦之任李斯，酈食其之下齊，說行如流，曲從如環，所欲必得，功若丘山，海內定，國家安，是遇其時也，子又何怪之邪！語曰『以筦闚天，以蠡測海，〔四〕以莛撞鐘』，〔五〕豈能通其條貫，考其文理，發其音聲哉！〔六〕繇是觀之，譬猶鼱鼩之襲狗，〔七〕孤豚之咋虎，〔八〕至則靡耳，何功之有？〔九〕今以下愚而非處士，雖欲勿困，固不得已，此適足以明其不知權變而終或於大道也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_78_239","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「魁讀曰塊。」","sentenceOrder":239},
  {"id":"s_work_han_thu_78_240","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「許由，堯讓以天下而恥聞之。楚狂接輿陽狂匿跡。范蠡佐句踐，功成而退。子胥忠諫，至死不易。」","sentenceOrder":240},
  {"id":"s_work_han_thu_78_241","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「耦，合也。徒，眾也。」","sentenceOrder":241},
  {"id":"s_work_han_thu_78_242","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　服虔曰：「筦音管。」張晏曰：「蠡，瓠瓢也。」師古曰：「筦，古管字。蠡音來奚反。瓢音平搖反。」","sentenceOrder":242},
  {"id":"s_work_han_thu_78_243","chapterId":"ch_work_han_thu_78","textTraditional":"〔五〕　文穎曰：「謂槁莛也。」師古曰：「音唐丁反。」","sentenceOrder":243},
  {"id":"s_work_han_thu_78_244","chapterId":"ch_work_han_thu_78","textTraditional":"〔六〕　師古曰：「考，究也。」","sentenceOrder":244},
  {"id":"s_work_han_thu_78_245","chapterId":"ch_work_han_thu_78","textTraditional":"〔七〕　服虔曰：「音縱劬。」如淳曰：「鼱鼩，小鼠也，音精劬。」","sentenceOrder":245},
  {"id":"s_work_han_thu_78_246","chapterId":"ch_work_han_thu_78","textTraditional":"〔八〕　師古曰：「孤豚，孤特之豚也。咋，嚙也，音仕客反。」","sentenceOrder":246},
  {"id":"s_work_han_thu_78_247","chapterId":"ch_work_han_thu_78","textTraditional":"〔九〕　師古曰：「靡，碎滅也。耳，語辭。」","sentenceOrder":247},
  {"id":"s_work_han_thu_78_248","chapterId":"ch_work_han_thu_78","textTraditional":"又設非有先生之論，其辭曰：","sentenceOrder":248},
  {"id":"s_work_han_thu_78_249","chapterId":"ch_work_han_thu_78","textTraditional":"非有先生仕於吳，進不稱往古以厲主意，退不能揚君美以顯其功，默（默）〔然〕無言者三年矣。吳王怪而問之，曰：「寡人獲先人之功，寄於眾賢之上，夙興夜寐，未嘗敢怠也。今先生率然高舉，遠集吳地，〔一〕將以輔治寡人，誠竊嘉之，體不安席，食不甘味，目不視靡曼之色，耳不聽鐘鼓之音，虛心定志欲聞流議者三年于茲矣。〔二〕今先生進無以輔治，退不揚主譽，竊不為先生取之也。蓋懷能而不見，是不忠也；見而不行，主不明也。〔三〕意者寡人殆不明乎？」非有先生伏而唯唯。〔四〕吳王曰：「可以談矣，寡人將竦意而覽焉。」〔五〕先生曰：「於戲！〔六〕可乎哉？可乎哉？〔七〕談何容易！〔八〕夫談有悖於目拂於耳謬於心而便於身者，〔九〕或有說於目順於耳快於心而毀於行者，〔一０〕非有明王聖主，孰能聽之？」吳王曰：「何為其然也？『中人已上可以語上也。』〔一一〕先生試言，寡人將聽焉。」","sentenceOrder":249},
  {"id":"s_work_han_thu_78_250","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「率然猶颯然。」","sentenceOrder":250},
  {"id":"s_work_han_thu_78_251","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「流，末流也，猶言餘論也。」","sentenceOrder":251},
  {"id":"s_work_han_thu_78_252","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「見，顯也。」","sentenceOrder":252},
  {"id":"s_work_han_thu_78_253","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　師古曰：「唯唯，恭應也，音弋癸反。」","sentenceOrder":253},
  {"id":"s_work_han_thu_78_254","chapterId":"ch_work_han_thu_78","textTraditional":"〔五〕　師古曰：「竦，企待也。」","sentenceOrder":254},
  {"id":"s_work_han_thu_78_255","chapterId":"ch_work_han_thu_78","textTraditional":"〔六〕　師古曰：「於讀曰烏。戲讀曰呼。」","sentenceOrder":255},
  {"id":"s_work_han_thu_78_256","chapterId":"ch_work_han_thu_78","textTraditional":"〔七〕　師古曰：「言不可。」","sentenceOrder":256},
  {"id":"s_work_han_thu_78_257","chapterId":"ch_work_han_thu_78","textTraditional":"〔八〕　師古曰：「不見寬容，則事不易，故曰何容易也。易，弋豉反。」","sentenceOrder":257},
  {"id":"s_work_han_thu_78_258","chapterId":"ch_work_han_thu_78","textTraditional":"〔九〕　師古曰：「悖，逆也。拂，違戾也。悖音布內反。拂音佛。」","sentenceOrder":258},
  {"id":"s_work_han_thu_78_259","chapterId":"ch_work_han_thu_78","textTraditional":"〔一０〕師古曰：「說讀曰悅。」","sentenceOrder":259},
  {"id":"s_work_han_thu_78_260","chapterId":"ch_work_han_thu_78","textTraditional":"〔一一〕師古曰：「引論語載孔子之言。中品之人則可以與言上道也。」","sentenceOrder":260},
  {"id":"s_work_han_thu_78_261","chapterId":"ch_work_han_thu_78","textTraditional":"先生對曰：「昔者關龍逢深諫於桀，而王子比干直言於紂，此二臣者，皆極慮盡忠，閔王澤不下流，而萬民騷動，〔一〕故直言其失，切諫其邪者，將以為君之榮，除主之禍也。今則不然，反以為誹謗君之行，無人臣之禮，〔二〕果紛然傷於身，蒙不辜之名，〔三〕戮及先人，為天下笑，故曰談何容易！是以輔弼之臣瓦解，而邪諂之人並進，〔遂〕及蜚廉、惡來（輩）〔革〕等。〔四〕二人皆詐偽，巧言利口以進其身，陰奉琱瑑刻鏤之好以納其心。〔五〕務快耳目之欲，以苟容為度。遂往不戒，身沒被戮，宗廟崩阤，國家為虛〔六〕，放戮聖賢，親近讒夫。詩不云乎？『讒人罔極，交亂四國』〔七〕，此之謂也。故卑身賤體，說色微辭，〔八〕愉愉咰咰，終無益於主上之治，〔九〕則志士仁人不忍為也。將儼然作矜嚴之色，深言直諫，上以拂主之邪，下以損百姓之害，〔一０〕則忤於邪主之心，歷於衰世之法。〔一一〕故養壽命之士莫肯進也，遂居（家）〔深〕山之間，積土為室，編蓬為戶，彈琴其中，以詠先王之風，亦可以樂而忘死矣。是以伯夷叔齊避周，餓于首陽之下，後世稱其仁。如是，邪主之行固足畏也，故曰談何容易！」","sentenceOrder":261},
  {"id":"s_work_han_thu_78_262","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「閔，病也。」","sentenceOrder":262},
  {"id":"s_work_han_thu_78_263","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「不省其忠而被以此罪也。」","sentenceOrder":263},
  {"id":"s_work_han_thu_78_264","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「蒙，被也。」","sentenceOrder":264},
  {"id":"s_work_han_thu_78_265","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　蘇林曰：「二人皆紂時邪佞人也。」孟康曰：「蜚廉善走。」師古曰：「蜚，古飛字。」","sentenceOrder":265},
  {"id":"s_work_han_thu_78_266","chapterId":"ch_work_han_thu_78","textTraditional":"〔五〕　師古曰：「琱與彫同，畫也。瑑謂刻為文也，音篆。」","sentenceOrder":266},
  {"id":"s_work_han_thu_78_267","chapterId":"ch_work_han_thu_78","textTraditional":"〔六〕　師古曰：「阤，穨也。音直氏反。虛讀曰墟。」","sentenceOrder":267},
  {"id":"s_work_han_thu_78_268","chapterId":"ch_work_han_thu_78","textTraditional":"〔七〕　師古曰：「小雅青蠅之詩也。解在戾太子傳。」","sentenceOrder":268},
  {"id":"s_work_han_thu_78_269","chapterId":"ch_work_han_thu_78","textTraditional":"〔八〕　師古曰：「說讀曰悅。」","sentenceOrder":269},
  {"id":"s_work_han_thu_78_270","chapterId":"ch_work_han_thu_78","textTraditional":"〔九〕　師古曰：「愉愉，顏色和也。呴呴，言語順也。呴音許于反。」","sentenceOrder":270},
  {"id":"s_work_han_thu_78_271","chapterId":"ch_work_han_thu_78","textTraditional":"〔一０〕師古曰：「拂與弼同。損，減也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_78_272","chapterId":"ch_work_han_thu_78","textTraditional":"〔一一〕師古曰：「忤，逆也。歷猶經也，離也。」","sentenceOrder":272},
  {"id":"s_work_han_thu_78_273","chapterId":"ch_work_han_thu_78","textTraditional":"於是吳王懼然易容，〔一〕捐薦去几，危坐而聽。〔二〕先生曰：「接輿避世，箕子被髮陽狂，〔三〕此二人者，皆避濁世以全其身者也。使遇明王聖主，得清燕之閒，寬和之色，〔四〕發憤畢誠，〔五〕圖畫安危，揆度得失，〔六〕上以安主體，下以便萬民，則五帝三王之道可幾而見也。〔七〕故伊尹蒙恥辱負鼎俎和五味以干湯，〔八〕太公釣於渭之陽以見文王。心合意同，謀無不成，計無不從，誠得其君也。深念遠慮，引義以正其身，推恩以廣其下，本仁祖義，〔九〕褒有德，祿賢能，誅惡亂，總遠方，一統類，美風俗，此帝王所由昌也。上不變天性，下不奪人倫，則天地和洽，遠方懷之，故號聖王。臣子之職既加矣，於是裂地定封，爵為公侯，傳國子孫，名顯後世，民到于今稱之，以遇湯與文王也。太公、伊尹以如此，龍逢、比干獨如彼，豈不哀哉！故曰談何容易！」","sentenceOrder":273},
  {"id":"s_work_han_thu_78_274","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「懼然，失守之貌也。懼音居具反。」","sentenceOrder":274},
  {"id":"s_work_han_thu_78_275","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「捐薦席而去，馮几自貶損也。」","sentenceOrder":275},
  {"id":"s_work_han_thu_78_276","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「解並在鄒陽傳。」","sentenceOrder":276},
  {"id":"s_work_han_thu_78_277","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　師古曰：「閒讀曰閑。閑，暇也。」","sentenceOrder":277},
  {"id":"s_work_han_thu_78_278","chapterId":"ch_work_han_thu_78","textTraditional":"〔五〕　師古曰：「畢，盡也。」","sentenceOrder":278},
  {"id":"s_work_han_thu_78_279","chapterId":"ch_work_han_thu_78","textTraditional":"〔六〕　師古曰：「圖，謀；畫，計也。」","sentenceOrder":279},
  {"id":"s_work_han_thu_78_280","chapterId":"ch_work_han_thu_78","textTraditional":"〔七〕　師古曰：「幾，庶幾。」","sentenceOrder":280},
  {"id":"s_work_han_thu_78_281","chapterId":"ch_work_han_thu_78","textTraditional":"〔八〕　師古曰：「蒙，冒也，犯也。」","sentenceOrder":281},
  {"id":"s_work_han_thu_78_282","chapterId":"ch_work_han_thu_78","textTraditional":"〔九〕　師古曰：「以仁為本，以義為始。」","sentenceOrder":282},
  {"id":"s_work_han_thu_78_283","chapterId":"ch_work_han_thu_78","textTraditional":"於是吳王穆然，〔一〕俛而深惟，仰而泣下交頤，曰：「嗟乎！余國之不亡也，綿綿連連，殆哉，世〔之〕不絕也！」〔二〕於是正明堂之朝，齊君〔臣〕之位，舉賢材，布德惠，施仁義，賞有功；躬節儉，減後宮之費，損車馬之用；放鄭聲，遠佞人，〔三〕省庖廚，去侈靡；卑宮館，壞苑囿，填池塹，以予貧民無產業者；開內藏，振貧窮，存耆老，卹孤獨；薄賦斂，省刑辟。行此三年，海內晏然，天下大洽，陰陽和調，萬物咸得其宜；國無災害之變，民無飢寒之色，家給人足，畜積有餘，囹圄空虛；〔四〕鳳凰來集，麒麟在郊，甘露既降，朱草萌牙；遠方異俗之人鄉風慕義，〔五〕各奉其職而來朝賀。故治亂之道，存亡之端，若此易見，而君人者莫肯為也，臣愚竊以為過。故詩云：「王國克生，惟周之楨，濟濟多士，文王以寧。」〔六〕此之謂也。","sentenceOrder":283},
  {"id":"s_work_han_thu_78_284","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　張晏曰：「穆音默。」師古曰：「穆然，靜思貌。」","sentenceOrder":284},
  {"id":"s_work_han_thu_78_285","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「殆，危也。」","sentenceOrder":285},
  {"id":"s_work_han_thu_78_286","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「遠，離也，音于萬反。」","sentenceOrder":286},
  {"id":"s_work_han_thu_78_287","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　師古曰：「畜讀曰蓄。」","sentenceOrder":287},
  {"id":"s_work_han_thu_78_288","chapterId":"ch_work_han_thu_78","textTraditional":"〔五〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":288},
  {"id":"s_work_han_thu_78_289","chapterId":"ch_work_han_thu_78","textTraditional":"〔六〕　師古曰：「大雅文王之詩也。言文王之國生此多士為周室楨幹之臣，所以安寧也。」","sentenceOrder":289},
  {"id":"s_work_han_thu_78_290","chapterId":"ch_work_han_thu_78","textTraditional":"朔之文辭，此二篇最善。其餘有封泰山，責和氏璧及皇太子生禖，屏風，殿上柏柱，平樂觀賦獵，八言、七言上下，〔一〕從公孫弘借車，凡〔劉〕向所錄朔書具是矣。〔二〕世所傳他事皆非也。〔三〕","sentenceOrder":290},
  {"id":"s_work_han_thu_78_291","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　晉灼曰：「八言、七言詩，各有上下篇。」","sentenceOrder":291},
  {"id":"s_work_han_thu_78_292","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰：「劉向別錄所載。」","sentenceOrder":292},
  {"id":"s_work_han_thu_78_293","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「謂如東方朔別傳及俗用五行時日之書，皆非實事也。」","sentenceOrder":293},
  {"id":"s_work_han_thu_78_294","chapterId":"ch_work_han_thu_78","textTraditional":"贊曰：劉向言少時數問長老賢人通於事及朔時者，〔一〕皆曰朔口諧倡辯，不能持論，喜為庸人誦說，〔二〕故令後世多傳聞者。而楊雄亦以為朔言不純師，行不純德，其流風遺書蔑如也。〔三〕然朔名過實者，以其詼達多端，不名一行，應諧似優，不窮似智，正諫似直，穢德似隱。非夷齊而是柳下惠，戒其子以上容：〔四〕「首陽為拙，〔五〕柱下為工；〔六〕飽食安步，以仕易農；依隱玩世，詭時不逢」。〔七〕其滑稽之雄乎！〔八〕朔之詼諧，逢占射覆，〔九〕其事浮淺，行於眾庶，童兒牧豎莫不眩燿。而後世好事者因取奇言怪語附著之朔，故詳錄焉。〔一０〕","sentenceOrder":294},
  {"id":"s_work_han_thu_78_295","chapterId":"ch_work_han_thu_78","textTraditional":"〔一〕　師古曰：「與朔同時也。」","sentenceOrder":295},
  {"id":"s_work_han_thu_78_296","chapterId":"ch_work_han_thu_78","textTraditional":"〔二〕　師古曰；「喜音許吏反。為音于偽反。」","sentenceOrder":296},
  {"id":"s_work_han_thu_78_297","chapterId":"ch_work_han_thu_78","textTraditional":"〔三〕　師古曰：「言辭義淺薄，不足稱也。」","sentenceOrder":297},
  {"id":"s_work_han_thu_78_298","chapterId":"ch_work_han_thu_78","textTraditional":"〔四〕　師古曰：「容身避害也。」","sentenceOrder":298},
  {"id":"s_work_han_thu_78_299","chapterId":"ch_work_han_thu_78","textTraditional":"〔五〕　應劭曰：「伯夷、叔齊不食周粟，餓死首陽山，為拙。」","sentenceOrder":299},
  {"id":"s_work_han_thu_78_300","chapterId":"ch_work_han_thu_78","textTraditional":"〔六〕　應劭曰：「老子為周柱下史，朝隱，故終身無患，是為工也。」","sentenceOrder":300},
  {"id":"s_work_han_thu_78_301","chapterId":"ch_work_han_thu_78","textTraditional":"〔七〕　如淳曰：「依違朝隱，樂玩其身於一世也。反時直言正諫，則與富貴不相逢矣。」臣瓚曰：「行與時詭而不逢禍害也。」師古曰：「瓚說是也。詭，違也。」","sentenceOrder":301},
  {"id":"s_work_han_thu_78_302","chapterId":"ch_work_han_thu_78","textTraditional":"〔八〕　師古曰：「雄謂為之長帥也。」","sentenceOrder":302},
  {"id":"s_work_han_thu_78_303","chapterId":"ch_work_han_thu_78","textTraditional":"〔九〕　如淳曰：「逢占，逢人所問而占之也。」師古曰：「此說非也。逢占，逆占事，猶云逆刺也。」","sentenceOrder":303},
  {"id":"s_work_han_thu_78_304","chapterId":"ch_work_han_thu_78","textTraditional":"〔一０〕師古曰：「言此傳所以詳錄朔之辭語者，為俗人多以奇異妄附於朔故耳。欲明傳所不記，皆非其實也。而今之為漢書學者，猶更取他書雜說，假合東方朔之事以博異聞，良可歎矣。他皆類此。著音直略反。」","sentenceOrder":304},
  {"id":"s_work_han_thu_78_305","chapterId":"ch_work_han_thu_78","textTraditional":"校勘記","sentenceOrder":305},
  {"id":"s_work_han_thu_78_306","chapterId":"ch_work_han_thu_78","textTraditional":"二八四四頁一二行　（凥）〔尻〕蓋高。　王先慎說「凥」當作「尻」，從「九」。按各本皆誤。","sentenceOrder":306},
  {"id":"s_work_han_thu_78_307","chapterId":"ch_work_han_thu_78","textTraditional":"二八四五頁　九行　非為蔦之寄生寓木宛童有（林）〔枝〕葉者也。　景祐、殿、局本都作「枝」，此誤。","sentenceOrder":307},
  {"id":"s_work_han_thu_78_308","chapterId":"ch_work_han_thu_78","textTraditional":"二八四六頁　二行　（雛）〔鷇〕音口豆反。　景祐、殿、局本都作「鷇」，此誤。","sentenceOrder":308},
  {"id":"s_work_han_thu_78_309","chapterId":"ch_work_han_thu_78","textTraditional":"二八五０頁一六行　〔隄〕音丁奚反。　殿本有「隄」字。","sentenceOrder":309},
  {"id":"s_work_han_thu_78_310","chapterId":"ch_work_han_thu_78","textTraditional":"二八五二頁　九行　因此（時）〔對〕復為中郎，　殿、局本都作「對」。王先謙說作「對」是。","sentenceOrder":310},
  {"id":"s_work_han_thu_78_311","chapterId":"ch_work_han_thu_78","textTraditional":"二八五七頁　七行　今俗猶（河）〔云〕魅蜮也。　景祐、殿本都作「云」，局本作「呵」。","sentenceOrder":311},
  {"id":"s_work_han_thu_78_312","chapterId":"ch_work_han_thu_78","textTraditional":"二八五八頁　五行　貴為天（下）〔子〕，　景祐、殿、局本都作「子」，此誤。","sentenceOrder":312},
  {"id":"s_work_han_thu_78_313","chapterId":"ch_work_han_thu_78","textTraditional":"二八六一頁一三行　而應劭（曰）以子夏兩字總合為夔，　景祐、殿本無「曰」字。","sentenceOrder":313},
  {"id":"s_work_han_thu_78_314","chapterId":"ch_work_han_thu_78","textTraditional":"二八六二頁一五行　（或）〔師古〕曰：　王先謙說「或」字誤，當作「師古」。按各本皆誤。","sentenceOrder":314},
  {"id":"s_work_han_thu_78_315","chapterId":"ch_work_han_thu_78","textTraditional":"二八六四頁一二行　言不盡（言）〔善〕也。　景祐、殿本都作「善」。王先謙說作「善」是。","sentenceOrder":315},
  {"id":"s_work_han_thu_78_316","chapterId":"ch_work_han_thu_78","textTraditional":"二八六五頁一五行　七十有二（延）〔乃〕設用於文武，　景祐、殿、局本都作「乃」，此誤。","sentenceOrder":316},
  {"id":"s_work_han_thu_78_317","chapterId":"ch_work_han_thu_78","textTraditional":"二八六八頁　九行　默（默）〔然〕無言者三年矣。　景祐、殿本都作「然」。","sentenceOrder":317},
  {"id":"s_work_han_thu_78_318","chapterId":"ch_work_han_thu_78","textTraditional":"二八七０頁　一行　〔遂〕及蜚廉、惡來（輩）〔革〕等。　景祐、殿本都有「遂」字，「輩」作「革」。","sentenceOrder":318},
  {"id":"s_work_han_thu_79_1","chapterId":"ch_work_han_thu_79","textTraditional":"公孫賀字子叔，北地義渠人也。賀祖父昆邪，〔一〕景帝時為隴西守，以將軍擊吳楚有功，封平曲侯，著書十餘篇。〔二〕","sentenceOrder":1},
  {"id":"s_work_han_thu_79_2","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「昆音戶門反。」","sentenceOrder":2},
  {"id":"s_work_han_thu_79_3","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「藝文志陰陽家有公孫渾邪十五篇是也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_79_4","chapterId":"ch_work_han_thu_79","textTraditional":"賀少為騎士，從軍數有功。自武帝為太子時，賀為舍人，及武帝即位，遷至太僕。賀夫人君孺，衛皇后姊也，賀由是有寵。元光中為輕車將軍，軍馬邑。後四歲，出雲中。後五歲，以車騎將軍從大將軍青出，有功，封南窌侯。〔一〕後再以左將軍出定襄，無功，坐酎金，失侯。復以浮沮將軍出五原二千餘里，無功。〔二〕後八歲，遂代石慶為丞相，封葛繹侯。時朝廷多事，督責大臣。〔三〕自公孫弘後，丞相李蔡、嚴青翟、趙周三人比坐事死。〔四〕石慶雖以謹得終，然數被譴。初賀引拜為丞相，不受印綬，頓首涕泣，曰：「臣本邊鄙，以鞍馬騎射為官，材誠不任宰相。」上與左右見賀悲哀，感動下泣，曰：「扶起丞相。」賀不肯起，上乃起去，賀不得已拜。出，左右問其故，賀曰：「主上賢明，臣不足以稱，恐負重責，從是殆矣。」〔五〕","sentenceOrder":4},
  {"id":"s_work_han_thu_79_5","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　臣瓚曰：「茂陵中書云封南奅侯，表亦作奅。」師古曰：「窌、奅二字同耳，音普教反。」","sentenceOrder":5},
  {"id":"s_work_han_thu_79_6","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「沮音子閭反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_79_7","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「督謂察視也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_79_8","chapterId":"ch_work_han_thu_79","textTraditional":"〔四〕　師古曰：「比，頻也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_79_9","chapterId":"ch_work_han_thu_79","textTraditional":"〔五〕　師古曰：「殆，危也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_79_10","chapterId":"ch_work_han_thu_79","textTraditional":"賀子敬聲，代賀為太僕，父子並居公卿位。敬聲以皇后姊子，驕奢不奉法，征和中擅用北軍錢千九百萬，發覺，下獄。是時詔捕陽陵朱安世不能得，上求之急，賀自請逐捕安世以贖敬聲罪。上許之。後果得安世。安世者，京師大俠也，聞賀欲以贖子，笑曰：「丞相禍及宗矣。南山之竹不足受我辭，斜谷之木不足為我械。」〔一〕安世遂從獄中上書，告敬聲與陽石公主私通，〔二〕及使人巫祭祠詛上，且上甘泉當馳道埋偶人，〔三〕祝詛有惡言。下有司案驗賀，窮治所犯，遂父子死獄中，家族。","sentenceOrder":10},
  {"id":"s_work_han_thu_79_11","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「斜，谷名也，其中多木。械謂桎梏也。言我方欲告丞相事，獄辭且多，械繫方久，故云然也。斜音弋奢反。」","sentenceOrder":11},
  {"id":"s_work_han_thu_79_12","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「武帝女。」","sentenceOrder":12},
  {"id":"s_work_han_thu_79_13","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「甘泉宮在北山，故欲往皆言上也。刻木為人，象人之形，謂之偶人。偶，並也，對也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_79_14","chapterId":"ch_work_han_thu_79","textTraditional":"巫蠱之禍起自朱安世，成於江充，遂及公主、皇后、太子，皆敗。語在江充、戾園傳。〔一〕","sentenceOrder":14},
  {"id":"s_work_han_thu_79_15","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「武五子傳敘戾太子諡戾，而置園邑，故云戾園也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_79_16","chapterId":"ch_work_han_thu_79","textTraditional":"劉屈氂，武帝庶兄中山靖王子也，〔一〕不知其始所以進。","sentenceOrder":16},
  {"id":"s_work_han_thu_79_17","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「屈音丘勿反，又音其勿反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_79_18","chapterId":"ch_work_han_thu_79","textTraditional":"征和二年春，制詔御史：「故丞相賀倚舊故乘高勢而為邪，〔一〕興美田以利子弟賓客，不顧元元，無益邊穀，〔二〕貨賂上流〔三〕，朕忍之久矣。終不自革，〔四〕乃以邊為援，〔五〕使內郡自省作車，〔六〕又令耕者自轉，〔七〕以困農煩擾畜者，重馬傷秏，武備衰減；〔八〕下吏妄賦，百姓流亡；又詐為詔書，以姦傳朱安世。〔九〕獄已正於理。其以涿郡太守屈氂為左丞相，分丞相長史為兩府，以待天下遠方之選。〔一０〕夫親親任賢，周唐之道也。以澎戶二千二百封左丞相為澎侯。」〔一一〕","sentenceOrder":18},
  {"id":"s_work_han_thu_79_19","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「帝為太子，賀已為舍人，故云舊故。」","sentenceOrder":19},
  {"id":"s_work_han_thu_79_20","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　如淳曰：「戍邊卒糧乏，不能為方計以益之也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_79_21","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「丞相貪冒，受賂于下，故使眾庶貨賄上流執事者也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_79_22","chapterId":"ch_work_han_thu_79","textTraditional":"〔四〕　師古曰：「革，改也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_79_23","chapterId":"ch_work_han_thu_79","textTraditional":"〔五〕　如淳曰：「使內郡自作車，耕者自轉，所以饒邊，饒邊所以行恩施，為己名援也。或曰以胡為援也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_79_24","chapterId":"ch_work_han_thu_79","textTraditional":"〔六〕　服虔曰：「詐令內郡自省作車轉輸也。邊屯無事之時，宜自治作車，以給軍用。」師古曰：「令郡自省減諸餘功用而作車也。省音所領反。」","sentenceOrder":24},
  {"id":"s_work_han_thu_79_25","chapterId":"ch_work_han_thu_79","textTraditional":"〔七〕　文穎曰：「自輸穀於邊。」","sentenceOrder":25},
  {"id":"s_work_han_thu_79_26","chapterId":"ch_work_han_thu_79","textTraditional":"〔八〕　師古曰：「重謂懷孕者也。言轉運之勞，畜產疲困，故（反）使懷孕者為之傷秏，以減武備也。秏音呼到反。」","sentenceOrder":26},
  {"id":"s_work_han_thu_79_27","chapterId":"ch_work_han_thu_79","textTraditional":"〔九〕　師古曰：「傳，逮捕也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_79_28","chapterId":"ch_work_han_thu_79","textTraditional":"〔一０〕師古曰：「待得賢人當拜為右丞相。」","sentenceOrder":28},
  {"id":"s_work_han_thu_79_29","chapterId":"ch_work_han_thu_79","textTraditional":"〔一一〕服虔曰：「澎音彭。」晉灼曰：「東海縣。」","sentenceOrder":29},
  {"id":"s_work_han_thu_79_30","chapterId":"ch_work_han_thu_79","textTraditional":"其秋，戾太子為江充所譖，殺充，發兵入丞相府，屈氂挺身逃，亡其印綬。〔一〕是時上避暑在甘泉宮，丞相長史乘疾置以聞。〔二〕上問「丞相何為？」對曰：「丞相祕之，未敢發兵。」上怒曰：「事籍籍如此，何謂祕也？〔三〕丞相無周公之風矣。周公不誅管蔡乎？」乃賜丞相璽書曰：「捕斬反省，自有賞罰。以牛車為櫓，〔四〕毋接短兵，多殺傷士眾。〔五〕堅閉城門，毋令反者得出。」","sentenceOrder":30},
  {"id":"s_work_han_thu_79_31","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「挺，引也。獨引身而逃難，故失印綬也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_79_32","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「置謂所置驛也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_79_33","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「籍籍猶紛紛也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_79_34","chapterId":"ch_work_han_thu_79","textTraditional":"〔四〕　師古曰：「櫓，楯也。遠與敵戰，故以車為櫓，用自蔽也。一說櫓，望敵之樓也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_79_35","chapterId":"ch_work_han_thu_79","textTraditional":"〔五〕　師古曰：「用短兵則士眾多死傷。」","sentenceOrder":35},
  {"id":"s_work_han_thu_79_36","chapterId":"ch_work_han_thu_79","textTraditional":"太子既誅充發兵，宣言帝在甘泉病困，疑有變，姦臣欲作亂。上於是從甘泉來，幸城西建章宮，詔發三輔近縣兵，部中二千石以下，丞相兼將。太子亦遣使者撟制〔一〕赦長安中都官囚徒，〔二〕發武庫兵，命少傅石德及賓客張光等分將，使長安囚如侯持節發長水及宣曲胡騎，〔三〕皆以裝會。侍郎莽通使長安，因追捕如侯，告胡人曰：「節有詐，勿聽也。」遂斬如侯，引騎入長安，又發輯濯士，以予大鴻臚商丘成。〔四〕初，漢節純赤，以太子持赤節，故更為黃旄加上以相別。太子召監北軍使者任安發北軍兵，安受節已閉軍門，不肯應太子。太子引兵去，〈區夂〉四市人〔五〕凡數萬眾，至長樂西闕下，逢丞相軍，合戰五日，死者數萬人，血流入溝中。〔六〕丞相附兵浸多，〔七〕太子軍敗，南奔覆盎城門，得出。〔八〕會夜司直田仁部閉城門，坐令太子得出，丞相欲斬仁。御史大夫暴勝之謂丞相曰：「司直，吏二千石，當先請，柰何擅斬之。」丞相釋仁。〔九〕上聞而大怒，下吏責問御史大夫曰：「司直縱反者，丞相斬之，法也，大夫何以擅止之？」勝之皇恐，自殺。及北軍使者任安，坐受太子節，懷二心，司直田仁縱太子，皆要斬。上曰：「侍郎莽通獲反將如侯，長安男子景建從通獲少傅石德，可謂元功矣。大鴻臚商丘成力戰獲反將張光。其封通為重合侯，建為德侯，成為秺侯。」〔一０〕諸太子賓客，嘗出入宮門，皆坐誅。其隨太子發兵，以反法族。吏士劫略者，皆徙敦煌郡。〔一一〕以太子在外，始置屯兵長安諸城門。後二十餘日，太子得於湖。語在太子傳。〔一二〕","sentenceOrder":36},
  {"id":"s_work_han_thu_79_37","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「撟與矯同，其字從手。矯制，託稱詔命也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_79_38","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「京師諸官府。」","sentenceOrder":38},
  {"id":"s_work_han_thu_79_39","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「長水，校名，宣曲，宮也，並胡騎所屯。今鄠縣東長水鄉即舊營校之地。」","sentenceOrder":39},
  {"id":"s_work_han_thu_79_40","chapterId":"ch_work_han_thu_79","textTraditional":"〔四〕　師古曰：「輯濯士，主用輯及濯行船者也。短曰輯，長曰濯。輯音集，字本從木，其音同耳。濯字本亦作櫂，並音直孝反。」","sentenceOrder":40},
  {"id":"s_work_han_thu_79_41","chapterId":"ch_work_han_thu_79","textTraditional":"〔五〕　師古曰：「〈區夂〉與驅同。」","sentenceOrder":41},
  {"id":"s_work_han_thu_79_42","chapterId":"ch_work_han_thu_79","textTraditional":"〔六〕　師古曰：「溝，街衢之旁通水者也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_79_43","chapterId":"ch_work_han_thu_79","textTraditional":"〔七〕　師古曰：「浸，漸也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_79_44","chapterId":"ch_work_han_thu_79","textTraditional":"〔八〕　師古曰：「長安城南出東頭第一門曰覆盎城門，一號杜門。」","sentenceOrder":44},
  {"id":"s_work_han_thu_79_45","chapterId":"ch_work_han_thu_79","textTraditional":"〔九〕　師古曰：「釋，放也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_79_46","chapterId":"ch_work_han_thu_79","textTraditional":"〔一０〕孟康曰：「秺音妒，在濟陰成武，今有亭。」","sentenceOrder":46},
  {"id":"s_work_han_thu_79_47","chapterId":"ch_work_han_thu_79","textTraditional":"〔一一〕師古曰：「非其本心，然被太子劫略，故徙之也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_79_48","chapterId":"ch_work_han_thu_79","textTraditional":"〔一二〕師古曰：「湖，縣名。」","sentenceOrder":48},
  {"id":"s_work_han_thu_79_49","chapterId":"ch_work_han_thu_79","textTraditional":"其明年，貳師將軍李廣利將兵出擊匈奴，丞相為祖道，送至渭橋，〔一〕與廣利辭決。廣利曰：「願君侯早請昌邑王為太子。〔二〕如立為帝，君侯長何憂乎？」〔三〕屈氂許諾。昌邑王者，貳師將軍女弟李夫人子也。貳師女為屈氂子妻，故共欲立焉。是時治巫蠱獄急，內者令郭穰告丞相夫人以丞相數有譴，使巫祠社，祝詛主上，有惡言，及與貳師共禱祠，欲令昌邑王為帝。有司奏請案驗，罪至大逆不道。有詔載屈氂廚車以徇，〔四〕要斬東市，妻子梟首華陽街。貳師將軍妻子亦收。貳師聞之，降匈奴，宗族遂滅。","sentenceOrder":49},
  {"id":"s_work_han_thu_79_50","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「祖者，送行之祭，因設宴飲焉。」","sentenceOrder":50},
  {"id":"s_work_han_thu_79_51","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　如淳曰：「漢儀注列侯為丞相，稱君侯。」師古曰：「楊惲傳丘常謂惲為君侯，是則通呼列侯之尊稱耳，非必在於丞相也。如氏之說，不為通矣。」","sentenceOrder":51},
  {"id":"s_work_han_thu_79_52","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「如，若也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_79_53","chapterId":"ch_work_han_thu_79","textTraditional":"〔四〕　師古曰：「廚車，載食之車也。徇，行示也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_79_54","chapterId":"ch_work_han_thu_79","textTraditional":"車千秋，本姓田氏，其先齊諸田徙長陵。〔一〕千秋為高寑郎。〔二〕會衛太子為江充所譖敗，久之，千秋上急變訟太子冤，〔三〕曰：「子弄父兵，罪當笞；天子之子過誤殺人，當何罪哉！臣嘗夢見一白頭翁教臣言。」是時，上頗知太子惶恐無他意，乃大感寤，召見千秋。至前，千秋長八尺餘，體貌甚麗，武帝見而說之，〔四〕謂曰：「父子之間，人所難言也，公獨明其不然。此高廟神靈使公教我，公當遂為吾輔佐。」立拜千秋為大鴻臚。〔五〕數月，遂代劉屈氂為丞相，封富民侯。千秋無他材能術學，又無伐閱功勞，〔六〕特以一言寤意，旬月取宰相封侯，世未嘗有也。後漢使者至匈奴，單于問曰：「聞漢新拜丞相，何用得之？」〔七〕使者曰：「以上書言事故。」單于曰：「苟如是，漢置丞相，非用賢也，妄一男子上書即得之矣。」使者還，道單于語。武帝以為辱命，欲下之吏。良久，乃貰之。〔八〕","sentenceOrder":54},
  {"id":"s_work_han_thu_79_55","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「劉敬所言徙關東大族者。」","sentenceOrder":55},
  {"id":"s_work_han_thu_79_56","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「高廟衛寑之郎。」","sentenceOrder":56},
  {"id":"s_work_han_thu_79_57","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「所告非常，故云急變也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_79_58","chapterId":"ch_work_han_thu_79","textTraditional":"〔四〕　師古曰：「說讀曰悅。」","sentenceOrder":58},
  {"id":"s_work_han_thu_79_59","chapterId":"ch_work_han_thu_79","textTraditional":"〔五〕　師古曰：「當其立見而即拜之，言不移時也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_79_60","chapterId":"ch_work_han_thu_79","textTraditional":"〔六〕　師古曰：「伐，積功也。閱，經歷也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_79_61","chapterId":"ch_work_han_thu_79","textTraditional":"〔七〕　師古曰：「言此人何以得為相也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_79_62","chapterId":"ch_work_han_thu_79","textTraditional":"〔八〕　師古曰：「貰，寬縱也，謂釋放之也。其下亦同。」","sentenceOrder":62},
  {"id":"s_work_han_thu_79_63","chapterId":"ch_work_han_thu_79","textTraditional":"然千秋為人敦厚有智，居位自稱，踰於前後數公。〔一〕初，千秋始視事，見上連年治太子獄，誅罰尤多，群下恐懼，思欲寬廣上意，尉安眾庶。〔二〕乃與御史、中二千石共上壽頌德美。勸上施恩惠，緩刑罰，玩聽音樂，養志和神，為天下自虞樂。〔三〕上報曰：「朕之不德，自左丞相與貳師陰謀逆亂，巫蠱之禍流及士大夫。〔四〕朕日一食者累月，乃何樂之聽？痛士大夫常在心，既事不咎。〔五〕雖然，巫蠱始發，詔丞相、御史督二千石求捕，〔六〕廷尉治，未聞九卿廷尉有所鞫也。〔七〕曩者，江充先治甘泉宮人，轉至未央椒房，〔八〕以及敬聲之疇、李禹之屬謀入匈奴，有司無所發，今丞相親掘蘭臺蠱驗，所明知也。至今餘巫頗脫不止，〔九〕陰賊侵身，遠近為蠱，朕媿之甚，何壽之有？敬不舉君之觴！謹謝丞相、二千石各就館。〔一０〕書曰：『毋偏毋黨，王道蕩蕩。』〔一一〕毋有復言。」〔一二〕","sentenceOrder":63},
  {"id":"s_work_han_thu_79_64","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「言稱其職也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_79_65","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「尉安之字，本無心也，是以漢書往往存古體字焉。」","sentenceOrder":65},
  {"id":"s_work_han_thu_79_66","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「虞與娛同。」","sentenceOrder":66},
  {"id":"s_work_han_thu_79_67","chapterId":"ch_work_han_thu_79","textTraditional":"〔四〕　師古曰：「謂與太子戰死者也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_79_68","chapterId":"ch_work_han_thu_79","textTraditional":"〔五〕　師古曰：「言既往之事，不可追咎。」","sentenceOrder":68},
  {"id":"s_work_han_thu_79_69","chapterId":"ch_work_han_thu_79","textTraditional":"〔六〕　師古曰：「督，察視也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_79_70","chapterId":"ch_work_han_thu_79","textTraditional":"〔七〕　師古曰：「鞫，問也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_79_71","chapterId":"ch_work_han_thu_79","textTraditional":"〔八〕　師古曰：「椒房，殿名，皇后所居也。以椒和泥塗壁，取其溫而芳也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_79_72","chapterId":"ch_work_han_thu_79","textTraditional":"〔九〕　師古曰：「言往往尚為蠱也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_79_73","chapterId":"ch_work_han_thu_79","textTraditional":"〔一０〕師古曰：「謝，告也。館，（宮）〔官〕舍也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_79_74","chapterId":"ch_work_han_thu_79","textTraditional":"〔一一〕師古曰：「周書洪範之辭也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_79_75","chapterId":"ch_work_han_thu_79","textTraditional":"〔一二〕師古曰：「不許其更請。」","sentenceOrder":75},
  {"id":"s_work_han_thu_79_76","chapterId":"ch_work_han_thu_79","textTraditional":"後歲餘，武帝疾，立皇子鉤弋夫人男為太子，〔一〕拜大將軍霍光、車騎將軍金日磾、御史大夫桑弘羊及丞相千秋，並受遺詔，輔道少主。〔二〕武帝崩，昭帝初即位，未任聽政，〔三〕政事壹決大將軍光。千秋居丞相位，謹厚有重德。每公卿朝會，光謂千秋曰：「始與君侯俱受先帝遺詔，今光治內，君侯治外，宜有以教督，使光毋負天下。」〔四〕千秋曰：「唯將軍留意，即天下幸甚。」終不肯有所言。光以此重之。每有吉祥嘉應，數褒賞丞相。訖昭帝世，國家少事，百姓稍益充實。始元六年，詔郡國舉賢良文學士，問以民所疾苦，於是鹽鐵之議起焉。〔五〕","sentenceOrder":76},
  {"id":"s_work_han_thu_79_77","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「鉤弋，宮名也，昭帝母趙婕妤居之，故號鉤弋夫人也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_79_78","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「道讀曰導。」","sentenceOrder":78},
  {"id":"s_work_han_thu_79_79","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「年幼，故未堪聽政。」","sentenceOrder":79},
  {"id":"s_work_han_thu_79_80","chapterId":"ch_work_han_thu_79","textTraditional":"〔四〕　師古曰：「督，視也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_79_81","chapterId":"ch_work_han_thu_79","textTraditional":"〔五〕　師古曰：「議罷鹽鐵之官，令百姓皆得煮鹽鑄鐵，因總論政治得失也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_79_82","chapterId":"ch_work_han_thu_79","textTraditional":"千秋為相十二年，薨，諡曰定侯。初，千秋年老，上優之，朝見，得乘小車入宮殿中，故因號曰「車丞相」。子順嗣侯，官至雲中太守，宣帝時以虎牙將軍擊匈奴，坐盜增鹵獲自殺，國除。","sentenceOrder":82},
  {"id":"s_work_han_thu_79_83","chapterId":"ch_work_han_thu_79","textTraditional":"桑弘羊為御史大夫八年，自以為國家興榷筦之利，〔一〕伐其功，〔二〕欲為子弟得官，怨望霍光，與上官桀等謀反，遂誅滅。","sentenceOrder":83},
  {"id":"s_work_han_thu_79_84","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「榷謂專其利使入官也。筦即管字也，義與幹同，皆謂主也。榷解在昭紀。」","sentenceOrder":84},
  {"id":"s_work_han_thu_79_85","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「自矜其功也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_79_86","chapterId":"ch_work_han_thu_79","textTraditional":"王訢，濟南人也。〔一〕以郡縣吏積功，稍遷為被陽令。〔二〕武帝末，軍旅數發，郡國盜賊群起，繡衣御史暴勝之使持斧逐捕盜賊，以軍興從事，誅二千石以下。勝之過被陽，欲斬訢，訢已解衣伏質，〔三〕仰言曰：「使君顓殺生之柄，威震郡國，〔四〕今復斬一訢，不足以增威，不如時有所寬，以明恩貸，〔五〕令盡死力。」勝之壯其言，貰不誅，因與訢相結厚。","sentenceOrder":86},
  {"id":"s_work_han_thu_79_87","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「訢字與欣同。」","sentenceOrder":87},
  {"id":"s_work_han_thu_79_88","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　孟康曰：「故千乘縣也。被音罷。」師古曰：「音皮彼反。」","sentenceOrder":88},
  {"id":"s_work_han_thu_79_89","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「質，鍖也，欲斬人皆伏於鍖上也。鍖音竹林反。」","sentenceOrder":89},
  {"id":"s_work_han_thu_79_90","chapterId":"ch_work_han_thu_79","textTraditional":"〔四〕　師古曰：「為使者，故謂之使君。使音所吏反。顓與專同。」","sentenceOrder":90},
  {"id":"s_work_han_thu_79_91","chapterId":"ch_work_han_thu_79","textTraditional":"〔五〕　師古曰：「貸猶假也，言饒假之。貸音土戴反。」","sentenceOrder":91},
  {"id":"s_work_han_thu_79_92","chapterId":"ch_work_han_thu_79","textTraditional":"勝之使還，薦訢，徵為右輔都尉，守右扶風。上數出幸安定、北地，過扶風，宮館馳道脩治，供張辦。〔一〕武帝嘉之，駐車，拜訢為真，視事十餘年。昭帝時為御史大夫，代車千秋為丞相，封宜春侯。明年薨，諡曰敬侯。","sentenceOrder":92},
  {"id":"s_work_han_thu_79_93","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「供音居用反。張音竹亮反。」","sentenceOrder":93},
  {"id":"s_work_han_thu_79_94","chapterId":"ch_work_han_thu_79","textTraditional":"子譚嗣，以列侯與謀廢昌邑王立宣帝，〔一〕益封三百戶。薨，子咸嗣。王莽妻即咸女，莽篡位，宜春氏以外戚寵。〔二〕自訢傳國至玄孫，莽敗，乃絕。","sentenceOrder":94},
  {"id":"s_work_han_thu_79_95","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「與讀曰豫。」","sentenceOrder":95},
  {"id":"s_work_han_thu_79_96","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　張晏曰：「莽諱取同姓，故氏侯邑也。」師古曰：「此說非也。若云王氏則與莽族相涉，故以侯號稱之耳。莽本以與譚得姓不同，祖系各別，故為婚娶，既非私竊，不須避諱，諱亦不可掩也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_79_97","chapterId":"ch_work_han_thu_79","textTraditional":"楊敞，華陰人也。給事大將軍莫府，為軍司馬，霍光愛厚之，稍遷至大司農。元鳳中，稻田使者燕蒼知上官桀等反謀，以告敞。敞素謹畏事，不敢言，乃移病臥。〔一〕以告諫大夫杜延年，延年以聞。蒼、延年皆封，敞以九卿不輒言，故不得侯。〔二〕後遷御史大夫，代王訢為丞相，封安平侯。","sentenceOrder":97},
  {"id":"s_work_han_thu_79_98","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「移病，（請以）〔謂移〕書言病。一曰以病而移居也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_79_99","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「聞之不即告言也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_79_100","chapterId":"ch_work_han_thu_79","textTraditional":"明年，昭帝崩。昌邑王徵即位，淫亂，大將軍光與車騎將軍張安世謀欲廢王更立。議既定，使大司農田延年報敞。敞驚懼，不知所言，汗出洽背，徒唯唯而已。〔一〕延年起至更衣，〔二〕敞夫人遽從東箱〔三〕謂敞曰：「此國大事，今大將軍議已定，使九卿來報君侯。君侯不疾應，與大將軍同心，猶與無決，〔四〕先事誅矣。」延年從更衣還，敞、夫人與延年參語許諾，〔五〕請奉大將軍教令，遂共廢昌邑王，立宣帝。宣帝即位月餘，敞薨，諡曰敬侯。子忠嗣，以敞居位定策安宗廟，益封三千五百戶。","sentenceOrder":100},
  {"id":"s_work_han_thu_79_101","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「唯唯，恭應之辭也，音弋癸反。」","sentenceOrder":101},
  {"id":"s_work_han_thu_79_102","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「古者延賓必有更衣之處也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_79_103","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「遽，速也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_79_104","chapterId":"ch_work_han_thu_79","textTraditional":"〔四〕　師古曰：「與讀曰豫。」","sentenceOrder":104},
  {"id":"s_work_han_thu_79_105","chapterId":"ch_work_han_thu_79","textTraditional":"〔五〕　師古曰：「三人共言，故云參語。」","sentenceOrder":105},
  {"id":"s_work_han_thu_79_106","chapterId":"ch_work_han_thu_79","textTraditional":"忠弟惲，字子幼，〔一〕以忠任為郎，補常侍騎。〔二〕惲母，司馬遷女也。惲始讀外祖太史公記，頗為春秋。以材能稱。好交英俊諸儒，名顯朝廷，擢為左曹。霍氏謀反，惲先聞知，因侍中金安上以聞，召見言狀。霍氏伏誅，惲等五人皆封，惲為平通侯，遷中郎將。","sentenceOrder":106},
  {"id":"s_work_han_thu_79_107","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「惲音於粉反。」","sentenceOrder":107},
  {"id":"s_work_han_thu_79_108","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「為騎郎而常侍，故謂之常侍騎也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_79_109","chapterId":"ch_work_han_thu_79","textTraditional":"郎官故事，令郎出錢市財用，給文書，乃得出，名曰「山郎」。〔一〕移病盡一日，輒償一沐，〔二〕或至歲餘不得沐。其豪富郎，日出游戲，或行錢得善部。〔三〕貨賂流行，傳相放效。〔四〕惲為中郎將，罷山郎，移長度大司農，以給財用。〔五〕其疾病休謁洗沐，皆以法令從事。郎、謁者有罪過，輒奏免，薦舉其高弟有行能者，至郡守九卿。郎官化之，莫不自厲，絕請謁貨賂之端，令行禁止，宮殿之內翕然同聲。由是擢為諸吏光祿勳，親近用事。","sentenceOrder":109},
  {"id":"s_work_han_thu_79_110","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　張晏曰：「山，財用之所出，故取名焉。」","sentenceOrder":110},
  {"id":"s_work_han_thu_79_111","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　晉灼曰：「五日一洗沐也。」師古曰：「言出財用者，雖非休沐，常得在外也。貧者實病，皆以沐假償之也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_79_112","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「郎官之職，各有主部，故行錢財而擇其善，以招權也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_79_113","chapterId":"ch_work_han_thu_79","textTraditional":"〔四〕　師古曰：「放音斧往反。」","sentenceOrder":113},
  {"id":"s_work_han_thu_79_114","chapterId":"ch_work_han_thu_79","textTraditional":"〔五〕　應劭曰：「長，久也。一歲之調度也。」蘇林曰：「簿書給縑之長也。」師古曰：「應說是也。言總計一歲所須財用，及文書之調度，而移大司農，以官錢供給之，更不取於郎也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_79_115","chapterId":"ch_work_han_thu_79","textTraditional":"初，惲受父財五百萬，及身封侯，皆以分宗族。後母無子，財亦數百萬，死皆予惲，惲盡復分後母昆弟。再受訾千餘萬，皆以分施。其輕財好義如此。","sentenceOrder":115},
  {"id":"s_work_han_thu_79_116","chapterId":"ch_work_han_thu_79","textTraditional":"惲居殿中，廉絜無私，郎官稱公平。然惲伐其行治，〔一〕又性刻害，好發人陰伏，同位有忤己者，必欲害之，以其能高人。由是多怨於朝廷，與太僕戴長樂相失，卒以是敗。〔二〕","sentenceOrder":116},
  {"id":"s_work_han_thu_79_117","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「自矜其節行及政治之能也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_79_118","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「卒，終也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_79_119","chapterId":"ch_work_han_thu_79","textTraditional":"長樂者，宣帝在民間時與相知，及即位，拔擢親近。長樂嘗使行事（隸）〔肄〕宗廟，〔一〕還謂掾史曰：「我親面見受詔，副帝（隸）〔肄〕，秺侯御。」〔二〕人有上書告長樂非所宜言，事下廷尉。長樂疑惲教人告之，亦上書告惲罪：「高昌侯車奔入北掖門，〔三〕惲語富平侯張延壽曰：『聞前曾有奔車抵殿門，〔四〕門關折，馬死，而昭帝崩。今復如此，天時，非人力也。』左馮翊韓延壽有罪下獄，惲上書訟延壽。郎中丘常謂惲曰：『聞君侯訟韓馮翊，當得活乎？』惲曰：『事何容易！脛脛者未必全也。〔五〕我不能自保，〔六〕真人所謂鼠不容穴銜窶數者也。』〔七〕又中書謁者令宣持單于使者語，視諸將軍、中朝二千石。〔八〕惲曰：『冒頓單于得漢美食好物，謂之殠惡，單于不來明甚。』〔九〕惲上觀西閣上畫人，指桀紂畫謂樂昌侯王武曰：『天子過此，一二問其過，可以得師矣。』〔一０〕畫人有堯舜禹湯，不稱而舉桀紂。惲聞匈奴降者道單于見殺，惲曰：『得不肖君，大臣為畫善計不用，自令身無處所。〔一一〕若秦時但任小臣，誅殺忠良，竟以滅亡；令親任大臣，即至今耳。〔一二〕古與今如一丘之貉。』〔一三〕惲妄引亡國以誹謗當世，無人臣禮。又語長樂曰：『正月以來，天陰不雨，此春秋所記，夏侯君所言。〔一四〕行必不至河東矣。』〔一五〕以主上為戲語，尤悖逆絕理。","sentenceOrder":119},
  {"id":"s_work_han_thu_79_120","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　服虔曰：「兼行天子事，先（隸）〔肄〕習威儀也。」師古曰：「肄音弋二反。」","sentenceOrder":120},
  {"id":"s_work_han_thu_79_121","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「我副帝（隸）〔肄〕而秺侯乃為御耳。御謂御車也。秺音丁故反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_79_122","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「犇，古奔字也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_79_123","chapterId":"ch_work_han_thu_79","textTraditional":"〔四〕　師古曰：「抵，觸也，音丁禮反。」","sentenceOrder":123},
  {"id":"s_work_han_thu_79_124","chapterId":"ch_work_han_thu_79","textTraditional":"〔五〕　師古曰：「脛脛，直貌也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_79_125","chapterId":"ch_work_han_thu_79","textTraditional":"〔六〕　師古曰：「言我尚不能自保，訟人何以得活。」","sentenceOrder":125},
  {"id":"s_work_han_thu_79_126","chapterId":"ch_work_han_thu_79","textTraditional":"〔七〕　李奇曰：「真人，正人也。」如淳曰：「所以不容穴，坐銜窶數自妨，故不得入穴。」師古曰：「窶數，戴器也。窶音其羽反。數音山羽反。解在東方朔傳。惲自云今之訟人，亦於己有妨。」","sentenceOrder":126},
  {"id":"s_work_han_thu_79_127","chapterId":"ch_work_han_thu_79","textTraditional":"〔八〕　師古曰：「謂譯者所錄也。視讀曰示。」","sentenceOrder":127},
  {"id":"s_work_han_thu_79_128","chapterId":"ch_work_han_thu_79","textTraditional":"〔九〕　師古曰：「時使者云單于欲來朝，故惲云不來。」","sentenceOrder":128},
  {"id":"s_work_han_thu_79_129","chapterId":"ch_work_han_thu_79","textTraditional":"〔一０〕師古曰：「過此謂經過此也。問其過，謂桀紂之過惡。」","sentenceOrder":129},
  {"id":"s_work_han_thu_79_130","chapterId":"ch_work_han_thu_79","textTraditional":"〔一一〕師古曰：「無處所謂死滅也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_79_131","chapterId":"ch_work_han_thu_79","textTraditional":"〔一二〕師古曰：「言國祚長遠，可以至今猶不亡也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_79_132","chapterId":"ch_work_han_thu_79","textTraditional":"〔一三〕師古曰：「言其同類也。貉，獸名，似狐而善睡，音胡各反。」","sentenceOrder":132},
  {"id":"s_work_han_thu_79_133","chapterId":"ch_work_han_thu_79","textTraditional":"〔一四〕張晏曰：「夏侯勝諫昌邑王曰：『天久陰不雨，臣下必有謀上者。』春秋無久陰不雨之異也。漢史記勝所言，故曰『春秋所記』，謂說春秋災異者耳。」師古曰：「春秋有不雨事，說者因論久陰，附著之也。張謂漢史為春秋，失之矣。」","sentenceOrder":133},
  {"id":"s_work_han_thu_79_134","chapterId":"ch_work_han_thu_79","textTraditional":"〔一五〕張晏曰：「后土祠在河東，天子歲祠之。」","sentenceOrder":134},
  {"id":"s_work_han_thu_79_135","chapterId":"ch_work_han_thu_79","textTraditional":"「事下廷尉。廷尉定國考問，左驗明白，〔一〕奏惲不服罪，而召戶將尊，〔二〕欲令戒飭富平侯延壽，〔三〕曰『太僕定有死罪數事，朝暮人也。〔四〕惲幸與富平侯婚姻，今獨三人坐語，侯言「時不聞惲語」，自與太僕相觸也』。〔五〕尊曰：『不可』。惲怒，持大刀，曰：『蒙富平侯力，得族罪！〔六〕毋泄惲語，令太僕聞之亂餘事。』〔七〕惲幸得列九卿諸吏，宿衛近臣，上所信任，與聞政事，〔八〕不竭忠愛，盡臣子義，而妄怨望，稱引為訞惡言，〔九〕大逆不道，請逮捕治。」上不忍加誅，有詔皆免惲、長樂為庶人。","sentenceOrder":135},
  {"id":"s_work_han_thu_79_136","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「定國，于定國也。左，證左也，言當時在其左右見此事者也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_79_137","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　蘇林曰：「直主門戶者也。」師古曰：「戶將，官名，主戶衛，屬光祿也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_79_138","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「飭與敕同。富平侯張延壽也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_79_139","chapterId":"ch_work_han_thu_79","textTraditional":"〔四〕　師古曰：「言不久活也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_79_140","chapterId":"ch_work_han_thu_79","textTraditional":"〔五〕　師古曰：「令延壽證云惲無此語，長樂誣之也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_79_141","chapterId":"ch_work_han_thu_79","textTraditional":"〔六〕　師古曰：「惲言富平侯依太僕言而證之，則我得罪至於族滅，深怨之辭也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_79_142","chapterId":"ch_work_han_thu_79","textTraditional":"〔七〕　文穎曰：「勿使太僕聞惲此語。」師古曰：「亂餘事者，恐長樂心忿，更加增其餘罪狀也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_79_143","chapterId":"ch_work_han_thu_79","textTraditional":"〔八〕　師古曰：「與讀曰豫。」","sentenceOrder":143},
  {"id":"s_work_han_thu_79_144","chapterId":"ch_work_han_thu_79","textTraditional":"〔九〕　師古曰：「訞與妖同。」","sentenceOrder":144},
  {"id":"s_work_han_thu_79_145","chapterId":"ch_work_han_thu_79","textTraditional":"惲既失爵位，家居治產業，起室宅，以財自娛。歲餘，其友人安定太守西河孫會宗，知略士也，與惲書諫戒之，為言大臣廢退，當闔門惶懼，為可憐之意，〔一〕不當治產業，通賓客，有稱（舉）〔譽〕。惲宰相子，少顯朝廷，一朝〔以〕晻昧語言見廢，〔二〕內懷不服，報會宗書曰：","sentenceOrder":145},
  {"id":"s_work_han_thu_79_146","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「闔，閉也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_79_147","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「晻與暗同。」","sentenceOrder":147},
  {"id":"s_work_han_thu_79_148","chapterId":"ch_work_han_thu_79","textTraditional":"惲材朽行穢，文質無所底，〔一〕幸賴先人餘業得備宿衛，遭遇時變以獲爵位，終非其任，卒與禍會。〔二〕足下哀其愚，蒙賜書，教督以所不及，〔三〕殷勤甚厚。然竊恨足下不深惟其終始〔四〕，而猥隨俗之毀譽也。〔五〕言鄙陋之愚心，若逆指而文過，〔六〕默而息乎，恐違孔氏「各言爾志」之義，〔七〕故敢略陳其愚，唯君子察焉！","sentenceOrder":148},
  {"id":"s_work_han_thu_79_149","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「底，致也，音之履反。」","sentenceOrder":149},
  {"id":"s_work_han_thu_79_150","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「卒亦終也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_79_151","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「蒙，蔽；督，視〔也〕。」","sentenceOrder":151},
  {"id":"s_work_han_thu_79_152","chapterId":"ch_work_han_thu_79","textTraditional":"〔四〕　師古曰：「惟，思也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_79_153","chapterId":"ch_work_han_thu_79","textTraditional":"〔五〕　師古曰：「猥，曲也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_79_154","chapterId":"ch_work_han_thu_79","textTraditional":"〔六〕　師古曰：「逆足下之意指，而自文飾其過。」","sentenceOrder":154},
  {"id":"s_work_han_thu_79_155","chapterId":"ch_work_han_thu_79","textTraditional":"〔七〕　師古曰：「論語云顏回季路侍，子曰『盍各言爾志』，故惲引之。」","sentenceOrder":155},
  {"id":"s_work_han_thu_79_156","chapterId":"ch_work_han_thu_79","textTraditional":"惲家方隆盛時，乘朱輪者十人，位在列卿，爵為通侯，總領從官，與聞政事，〔一〕曾不能以此時有所建明，以宣德化，又不能與群僚同心并力，陪輔朝廷之遺忘，已負竊位素餐之責久矣。〔二〕懷祿貪勢，不能自退，遭遇變故，橫被口語，〔三〕身幽北闕，妻子滿獄。當此之時，自以夷滅不足以塞責，〔四〕豈意得全首領，復奉先人之丘墓乎？伏惟聖主之恩，不可勝量。君子游道，樂以忘憂；小人全軀，說以忘罪。〔五〕竊自思念，過已大矣，行已虧矣，長為農夫以沒世矣。是故身率妻子，戮力耕桑，灌園治產，以給公上，〔六〕不意當復用此為譏議也。","sentenceOrder":156},
  {"id":"s_work_han_thu_79_157","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「與讀曰豫。」","sentenceOrder":157},
  {"id":"s_work_han_thu_79_158","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「素，空也。不稱其職，空食祿也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_79_159","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「橫音胡孟反。」","sentenceOrder":159},
  {"id":"s_work_han_thu_79_160","chapterId":"ch_work_han_thu_79","textTraditional":"〔四〕　師古曰：「塞，補也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_79_161","chapterId":"ch_work_han_thu_79","textTraditional":"〔五〕　師古曰：「說讀曰悅。」","sentenceOrder":161},
  {"id":"s_work_han_thu_79_162","chapterId":"ch_work_han_thu_79","textTraditional":"〔六〕　師古曰：「充縣官之賦斂也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_79_163","chapterId":"ch_work_han_thu_79","textTraditional":"夫人情所不能止者，聖人弗禁，故君父至尊親，〔一〕送其終也，有時而既。〔二〕臣之得罪，已三年矣。田家作苦，歲時伏臘，亨羊炰羔，斗酒自勞。〔三〕家本秦也，能為秦聲。婦，趙女也，雅善鼓瑟。奴婢歌者數人，酒後耳熱，仰天拊缶〔四〕而呼烏烏〔五〕。其詩曰：「田彼南山，蕪穢不治，種一頃豆，落而為萁。人生行樂耳，須富貴何時！」〔六〕是日也，拂衣而喜，奮褎低卬，〔七〕頓足起舞，誠淫荒無度，不知其不可也。〔八〕惲幸有餘祿，方糴賤販貴，逐什一之利，此賈豎之事，汙辱之處，惲親行之。下流之人，眾毀所歸，不寒而栗。〔九〕雖雅知惲者，猶隨風而靡，〔一０〕尚何稱譽之有！董生不云乎？「明明求仁義，常恐不能化民者，卿大夫意也；明明求財利，常恐困乏者，庶人之事也。」〔一一〕故「道不同，不相為謀。」〔一二〕今子尚安得以卿大夫之制而責僕哉！","sentenceOrder":163},
  {"id":"s_work_han_thu_79_164","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「父至親，君至尊。」","sentenceOrder":164},
  {"id":"s_work_han_thu_79_165","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　張晏曰：「喪不過三年，臣見放逐，降居三月，復初。」師古曰：「既，已也。」","sentenceOrder":165},
  {"id":"s_work_han_thu_79_166","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「炰，毛炙肉也，即今所謂爊也。炰音步交反。爊音一高反。勞音來到反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_79_167","chapterId":"ch_work_han_thu_79","textTraditional":"〔四〕　應劭曰：「缶，瓦器也，秦人擊之以節歌。」師古曰：「缶即今之盆類也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_79_168","chapterId":"ch_work_han_thu_79","textTraditional":"〔五〕　師古曰：「李斯上書云：『擊甕叩缶，彈箏搏髀，而呼烏烏快耳者，真秦聲也。』是關中舊有此曲也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_79_169","chapterId":"ch_work_han_thu_79","textTraditional":"〔六〕　張晏曰：「山高而在陽，人君之象也。蕪穢不治，言朝廷之荒亂也。一頃百畝，以喻百官也。言豆者，貞實之物，當在囷倉，零落在野，喻己見放棄也。萁曲而不直，言朝臣皆諂諛也。」師古曰：「萁，豆莖也，音基。須，待也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_79_170","chapterId":"ch_work_han_thu_79","textTraditional":"〔七〕　師古曰：「褎，古衣袖字。」","sentenceOrder":170},
  {"id":"s_work_han_thu_79_171","chapterId":"ch_work_han_thu_79","textTraditional":"〔八〕　師古曰：「自謂為可也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_79_172","chapterId":"ch_work_han_thu_79","textTraditional":"〔九〕　師古曰：「栗，竦縮也。」","sentenceOrder":172},
  {"id":"s_work_han_thu_79_173","chapterId":"ch_work_han_thu_79","textTraditional":"〔一０〕師古曰：「言逐眾議，皆相毀也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_79_174","chapterId":"ch_work_han_thu_79","textTraditional":"〔一一〕師古曰：「引董仲舒之辭也。仲舒傳作皇皇也。」","sentenceOrder":174},
  {"id":"s_work_han_thu_79_175","chapterId":"ch_work_han_thu_79","textTraditional":"〔一二〕師古曰：「論語載孔子之辭，惲又引之。為音于偽反。」","sentenceOrder":175},
  {"id":"s_work_han_thu_79_176","chapterId":"ch_work_han_thu_79","textTraditional":"夫西河魏土，文侯所興，有段干木、田子方之遺風，〔一〕漂然皆有節概，知去就之分。〔二〕頃者，足下離舊土，臨安定，安定山谷之間，昆戎舊壤，〔三〕子弟貪鄙，豈習俗之移人哉？於今乃睹子之志矣。〔四〕方當盛漢之隆，願勉旃，毋多談。〔五〕","sentenceOrder":176},
  {"id":"s_work_han_thu_79_177","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　應劭曰：「段干木、田子方，魏賢人也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_79_178","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「漂然，高遠意，概，度量也。漂音匹遙反。槩音工代反。分音扶問反。」","sentenceOrder":178},
  {"id":"s_work_han_thu_79_179","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　文穎曰：「昆夷之地也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_79_180","chapterId":"ch_work_han_thu_79","textTraditional":"〔四〕　師古曰：「言豈隨安定貪鄙之俗而易其操乎？平生謂子為達道，今乃見子之志與我不同〔者〕也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_79_181","chapterId":"ch_work_han_thu_79","textTraditional":"〔五〕　師古曰：「旃，之也。言子當自勉勵以立功名，不須多與我言也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_79_182","chapterId":"ch_work_han_thu_79","textTraditional":"又惲兄子安平侯譚為典屬國，謂惲曰：「西河太守建平杜侯〔一〕前以罪過出，今徵為御史大夫。侯罪薄，又有功，且復用。」惲曰：「有功何益？縣官不足為盡力。」惲素與蓋寬饒、韓延壽善，譚即曰：「縣官實然，蓋司隸、韓馮翊皆盡力吏也，俱坐事誅。」會有日食變，騶馬猥佐成上書告惲〔二〕「驕奢不悔過，日食之咎，此人所致。」章下廷尉案驗，得所予會宗書，宣帝見而惡之。廷尉當惲大逆無道，〔三〕要斬。妻子徙酒泉郡。譚坐不諫正惲，與相應，有怨望語，免為庶人。召拜成為郎，諸在位與惲厚善者，未央衛尉韋玄成、京兆尹張敞及孫會宗等，皆免官。","sentenceOrder":182},
  {"id":"s_work_han_thu_79_183","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「杜延年。」","sentenceOrder":183},
  {"id":"s_work_han_thu_79_184","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　如淳曰：「騶馬，以給騶使乘之。佐，主猥馬吏也。有吏有佐名成者。」","sentenceOrder":184},
  {"id":"s_work_han_thu_79_185","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「當謂處斷其罪。」","sentenceOrder":185},
  {"id":"s_work_han_thu_79_186","chapterId":"ch_work_han_thu_79","textTraditional":"蔡義，河內溫人也。以明經給事大將軍莫府。家貧，常步行，資禮不逮眾門下，好事者相合〔一〕為義買犢車，令乘之。數歲，遷補覆盎城門候。〔二〕","sentenceOrder":186},
  {"id":"s_work_han_thu_79_187","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「言眾斂錢物。」","sentenceOrder":187},
  {"id":"s_work_han_thu_79_188","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「門候，主候時而開閉也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_79_189","chapterId":"ch_work_han_thu_79","textTraditional":"久之，詔求能為韓詩者，徵義待詔，久不進見。義上疏曰：「臣山東草萊之人，行能亡所比，容貌不及眾，然而不棄人倫者，竊以聞道於先師，自託於經術也。願賜清閒之燕，〔一〕得盡精思於前。」上召見義，說詩，甚說之，〔二〕擢為光祿大夫給事中，進授昭帝。數歲，拜為少府，遷御史大夫，代楊敞為丞相，封陽平侯。又以定策安宗廟益封，加賜黃金二百斤。","sentenceOrder":189},
  {"id":"s_work_han_thu_79_190","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「燕，安息也。閒讀曰閑。」","sentenceOrder":190},
  {"id":"s_work_han_thu_79_191","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「下說讀曰悅。」","sentenceOrder":191},
  {"id":"s_work_han_thu_79_192","chapterId":"ch_work_han_thu_79","textTraditional":"義為丞相時年八十餘，短小無須眉，貌似老嫗，行步俛僂，〔一〕常兩吏扶夾乃能行。時大將軍光秉政，議者或言光置宰相不選賢，苟用可顓制者。〔二〕光聞之，謂侍中左右及官屬曰：「以為人主師當為宰相，何謂云云？〔三〕此語不可使天下聞也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_79_193","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「俛即俯字也。僂，曲背也。僂音力主反。」","sentenceOrder":193},
  {"id":"s_work_han_thu_79_194","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「顓與專同。其後類此。」","sentenceOrder":194},
  {"id":"s_work_han_thu_79_195","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「云云，眾語，謂有不選賢之言也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_79_196","chapterId":"ch_work_han_thu_79","textTraditional":"義為相四歲，薨，諡曰節侯。無子，國除。","sentenceOrder":196},
  {"id":"s_work_han_thu_79_197","chapterId":"ch_work_han_thu_79","textTraditional":"陳萬年字幼公，沛郡相人也。為郡吏，察舉，至縣令，遷廣陵太守，〔一〕以高弟入為右扶風，遷太僕。","sentenceOrder":197},
  {"id":"s_work_han_thu_79_198","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「屢被察廉及舉薦，故得遷之也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_79_199","chapterId":"ch_work_han_thu_79","textTraditional":"萬年廉平，內行修，然善事人，賂遺外戚許、史，傾家自盡，尤事樂陵侯史高。丞相丙吉病，中二千石上謁問疾。〔一〕遣家丞出謝，謝已皆去，萬年獨留，昏夜乃歸。及吉病甚，上自臨，問以大臣行能。吉薦于定國、杜延年及萬年。萬年竟代定國為御史大夫，八歲病卒。","sentenceOrder":199},
  {"id":"s_work_han_thu_79_200","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「上謁，若今通名也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_79_201","chapterId":"ch_work_han_thu_79","textTraditional":"子咸字子康，年十八，以萬年任為郎。有異材，抗直，數言事，刺譏近臣，書數十上，遷為左曹。萬年嘗病，召咸教戒於床下，語至夜半，咸睡，頭觸屏風。萬年大怒，欲杖之，曰：「乃公教戒汝，汝反睡，不聽吾言，何也？」咸叩頭謝曰：「具曉所言，大要教咸諂也。」〔一〕萬年乃不復言。","sentenceOrder":201},
  {"id":"s_work_han_thu_79_202","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「大要，大歸也。讇，古諂字也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_79_203","chapterId":"ch_work_han_thu_79","textTraditional":"萬年死後，元帝擢咸為御史中丞，總領州郡奏事，課第諸刺史，內執法殿中，公卿以下皆敬憚之。是時中書令石顯用事顓權，咸頗言顯短，顯等恨之。時槐里令朱雲殘酷殺不辜，有司舉奏，未下。〔一〕咸素善雲，雲從刺候，教令上書自訟。〔二〕於是石顯微伺知之，白奏咸漏泄省中語，下獄掠治，〔三〕減死，髡為城旦，因廢。","sentenceOrder":203},
  {"id":"s_work_han_thu_79_204","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「天子未下其章也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_79_205","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　晉灼曰：「雲從咸刺探伺候事之輕重，咸因教令上書。」","sentenceOrder":205},
  {"id":"s_work_han_thu_79_206","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「掠，笞擊也，音力向反。」","sentenceOrder":206},
  {"id":"s_work_han_thu_79_207","chapterId":"ch_work_han_thu_79","textTraditional":"成帝初即位，大將軍王鳳以咸前指言石顯，有忠直節，奏請咸補長史。遷冀州刺史，奉使稱意，徵為諫大夫。復出為楚內史，北海、東郡太守。坐為京兆尹王章所薦，章誅，咸免官。起家復為南陽太守。所居以殺伐立威，豪猾吏及大姓犯法，輒論輸府，〔一〕以律程作司空，〔二〕為地臼木杵，舂不中程，或私解脫鉗釱，衣服不如法，〔三〕輒加罪笞。督作劇，不勝痛，〔四〕自絞死，歲數百千人，久者蟲出腐爛，家不得收。其治放嚴延年，其廉不如。所居調發屬縣所出食物以自奉養，〔五〕奢侈玉食。〔六〕然操持掾史，〔七〕郡中長吏皆令閉門自斂，不得踰法。公移敕書曰：〔八〕「即各欲求索自快，是一郡百太守也，何得然哉！」下吏畏之，豪彊執服，〔九〕令行禁止，然亦以此見廢。咸，三公子，少顯名於朝廷，而薛宣、朱博、翟方進、孔光等仕宦絕在咸後，皆以廉儉先至公卿，而咸滯於郡守。","sentenceOrder":207},
  {"id":"s_work_han_thu_79_208","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「府謂郡之府。」","sentenceOrder":208},
  {"id":"s_work_han_thu_79_209","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「司空，主行役之官。」","sentenceOrder":209},
  {"id":"s_work_han_thu_79_210","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「鉗在頸，釱在足，皆以鐵為之。鉗音其炎反。釱音弟。」","sentenceOrder":210},
  {"id":"s_work_han_thu_79_211","chapterId":"ch_work_han_thu_79","textTraditional":"〔四〕　師古曰：「作程劇苦，又被督察，笞罰既多，故不勝痛也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_79_212","chapterId":"ch_work_han_thu_79","textTraditional":"〔五〕　師古曰：「調，徒釣反。」","sentenceOrder":212},
  {"id":"s_work_han_thu_79_213","chapterId":"ch_work_han_thu_79","textTraditional":"〔六〕　師古曰：「玉食，美食如玉也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_79_214","chapterId":"ch_work_han_thu_79","textTraditional":"〔七〕　師古曰：「操，執也，音（于向）〔千高〕反。」","sentenceOrder":214},
  {"id":"s_work_han_thu_79_215","chapterId":"ch_work_han_thu_79","textTraditional":"〔八〕　師古曰：「公然移書以約敕也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_79_216","chapterId":"ch_work_han_thu_79","textTraditional":"〔九〕　師古曰：「執讀曰慹，音之涉反。」","sentenceOrder":216},
  {"id":"s_work_han_thu_79_217","chapterId":"ch_work_han_thu_79","textTraditional":"時車騎將軍王音輔政，信用陳湯。咸數賂遺湯，予書曰：「即蒙子公力，得入帝城，死不恨。」〔一〕後竟徵入為少府。少府多寶物，屬官咸皆鉤校，發其姦臧，〔二〕沒入辜榷財物。〔三〕官屬及諸中宮黃門、鉤盾、掖庭官吏，舉奏按論，畏咸，皆失氣。為少府三歲，與翟方進有隙。方進為丞相，奏「咸前為郡守，所在殘酷，毒螫加於吏民。主守盜，受所監。〔四〕而官媚邪臣陳湯以求薦舉。苟得無恥，不宜處位。」咸坐免。頃之，紅陽侯立舉咸方正，為光祿大夫給事中，方進復奏免之。後數年，立有罪就國，方進奏歸咸故郡，以憂死。","sentenceOrder":217},
  {"id":"s_work_han_thu_79_218","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「子公，湯之字。」","sentenceOrder":218},
  {"id":"s_work_han_thu_79_219","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「鉤音工侯反。」","sentenceOrder":219},
  {"id":"s_work_han_thu_79_220","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「辜，〔罪也〕。榷，專固也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_79_221","chapterId":"ch_work_han_thu_79","textTraditional":"〔四〕　如淳曰：「律，主守而盜直十金，棄市。」師古曰：「受所監法，解在景紀。」","sentenceOrder":221},
  {"id":"s_work_han_thu_79_222","chapterId":"ch_work_han_thu_79","textTraditional":"鄭弘字稚卿，泰山剛人也。〔一〕兄昌字次卿，亦好學，皆明經，通法律政事。次卿為太原、涿郡太守，弘為南陽太守，皆著治跡，條教法度，為後所述。次卿用刑罰深，不如弘平。遷淮陽相，以高弟入為右扶風，京師稱之。代韋玄成為御史大夫。六歲，坐與京房論議免，語在房傳。","sentenceOrder":222},
  {"id":"s_work_han_thu_79_223","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「穉，古稚字。」","sentenceOrder":223},
  {"id":"s_work_han_thu_79_224","chapterId":"ch_work_han_thu_79","textTraditional":"贊曰：所謂鹽鐵議者，起始元中，徵文學賢良問以治亂，皆對願罷郡國鹽鐵酒榷均輸，〔一〕務本抑末，毋與天下爭利，然後〔教〕化可興。御史大夫弘羊以為此乃所以安邊竟，制四夷，〔二〕國家大業，不可廢也。當時相詰難，頗有其議文。至宣帝時，汝南（相）〔桓〕寬次公〔三〕治公羊春秋，舉為郎，至廬江太守丞，博通善屬文，推衍鹽鐵之議，增廣條目，極其論難，著數萬言，〔四〕亦欲以究治亂，成一家之法焉。其辭曰：〔五〕「觀公卿賢良文學之議，『異乎吾所聞』。〔六〕聞汝南朱生言，當此之時，英俊並進，賢良茂陵唐生、文學魯國萬生之徒六十有餘人咸聚闕庭，舒六藝之風，陳治平之原，知者贊其慮，仁者明其施，勇者見其斷，〔七〕辯者騁其辭，齗齗焉，行行焉，〔八〕雖未詳備，斯可略觀矣。中山劉子推言王道，撟當世，反諸正，〔九〕彬彬然弘博君子也。〔一０〕九江祝生奮史魚之節，發憤懣，譏公卿，〔一一〕介然直而不撓，〔一二〕可謂不畏彊圉矣。桑大夫據當世，合時變，上權利之略，雖非正法，鉅儒宿學不能自解，〔一三〕博物通達之士也。然攝公卿之柄，不師古始，放於末利，〔一四〕處非其位，行非其道，果隕其性，以及厥宗。〔一五〕車丞相履伊呂之列，當軸處中，括囊不言，容身而去，〔一六〕彼哉！彼哉！〔一七〕若夫丞相、御史兩府之士，不能正議以輔宰相，成同類，長同行，阿意苟合，以說其上，〔一八〕『斗筲之徒，何足選也！』」〔一九〕","sentenceOrder":224},
  {"id":"s_work_han_thu_79_225","chapterId":"ch_work_han_thu_79","textTraditional":"〔一〕　師古曰：「酒榷均輸解在武紀及食貨志。」","sentenceOrder":225},
  {"id":"s_work_han_thu_79_226","chapterId":"ch_work_han_thu_79","textTraditional":"〔二〕　師古曰：「竟讀曰境。」","sentenceOrder":226},
  {"id":"s_work_han_thu_79_227","chapterId":"ch_work_han_thu_79","textTraditional":"〔三〕　師古曰：「次公者，寬之字。」","sentenceOrder":227},
  {"id":"s_work_han_thu_79_228","chapterId":"ch_work_han_thu_79","textTraditional":"〔四〕　師古曰：「即今之所行鹽鐵論十卷是也。」","sentenceOrder":228},
  {"id":"s_work_han_thu_79_229","chapterId":"ch_work_han_thu_79","textTraditional":"〔五〕　師古曰：「謂（相）〔桓〕寬總評議其善惡。」","sentenceOrder":229},
  {"id":"s_work_han_thu_79_230","chapterId":"ch_work_han_thu_79","textTraditional":"〔六〕　師古曰：「論語載子張之言，言不與己志同也，故寬引〔之〕。」","sentenceOrder":230},
  {"id":"s_work_han_thu_79_231","chapterId":"ch_work_han_thu_79","textTraditional":"〔七〕　師古曰：「斷音丁喚反。」","sentenceOrder":231},
  {"id":"s_work_han_thu_79_232","chapterId":"ch_work_han_thu_79","textTraditional":"〔八〕　師古曰：「齗齗，辯爭之貌；行行，剛彊之貌也。齗音牛斤反。行音胡浪反。」","sentenceOrder":232},
  {"id":"s_work_han_thu_79_233","chapterId":"ch_work_han_thu_79","textTraditional":"〔九〕　師古曰：「正曲曰撟。諸，之也。撟讀（曰）〔與〕矯同，其字從手。」","sentenceOrder":233},
  {"id":"s_work_han_thu_79_234","chapterId":"ch_work_han_thu_79","textTraditional":"〔一０〕師古曰：「彬彬，文章貌也，音彼旻反。」","sentenceOrder":234},
  {"id":"s_work_han_thu_79_235","chapterId":"ch_work_han_thu_79","textTraditional":"〔一一〕師古曰：「懣音滿，又莫本反。」","sentenceOrder":235},
  {"id":"s_work_han_thu_79_236","chapterId":"ch_work_han_thu_79","textTraditional":"〔一二〕師古曰：「撓，曲也，音女教反。」","sentenceOrder":236},
  {"id":"s_work_han_thu_79_237","chapterId":"ch_work_han_thu_79","textTraditional":"〔一三〕師古曰：「解，釋也，言理不出於弘羊也。」","sentenceOrder":237},
  {"id":"s_work_han_thu_79_238","chapterId":"ch_work_han_thu_79","textTraditional":"〔一四〕師古曰：「放，縱也，謂縱心於利也。一說放，依也，音方往反。論語稱孔子曰『放於利而行，多怨』也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_79_239","chapterId":"ch_work_han_thu_79","textTraditional":"〔一五〕師古曰：「性，生也，謂與上官桀謀反誅也。」","sentenceOrder":239},
  {"id":"s_work_han_thu_79_240","chapterId":"ch_work_han_thu_79","textTraditional":"〔一六〕師古曰：「括，結也。易坤卦六四爻辭曰『括囊，無咎無譽』，言自閉慎如囊之括結也。」","sentenceOrder":240},
  {"id":"s_work_han_thu_79_241","chapterId":"ch_work_han_thu_79","textTraditional":"〔一七〕師古曰：「論語云或問子西，孔子曰：『彼哉！彼哉！』言彼人者，無足稱也。」","sentenceOrder":241},
  {"id":"s_work_han_thu_79_242","chapterId":"ch_work_han_thu_79","textTraditional":"〔一八〕師古曰：「說讀曰悅。」","sentenceOrder":242},
  {"id":"s_work_han_thu_79_243","chapterId":"ch_work_han_thu_79","textTraditional":"〔一九〕師古曰：「筲，竹器也，容一斗。選，數也。論語云子貢問曰：『今之從政者何如？』孔子曰：『噫，斗筲之人，何足選也！』言其材器小劣，不足數也。筲音所交反。選音先阮反。噫，歎聲也。噫音於其反。」","sentenceOrder":243},
  {"id":"s_work_han_thu_79_244","chapterId":"ch_work_han_thu_79","textTraditional":"校勘記","sentenceOrder":244},
  {"id":"s_work_han_thu_79_245","chapterId":"ch_work_han_thu_79","textTraditional":"二八八０頁　六行　故（反）使懷孕者為之傷耗，　殿本無「反」字。","sentenceOrder":245},
  {"id":"s_work_han_thu_79_246","chapterId":"ch_work_han_thu_79","textTraditional":"二八八六頁　一行　館，（宮）〔官〕舍也。　景祐、汲古、殿、局本都作「官」，此誤。","sentenceOrder":246},
  {"id":"s_work_han_thu_79_247","chapterId":"ch_work_han_thu_79","textTraditional":"二八八八頁一四行　（請以）〔謂移〕書言病。　景祐、殿本都作「謂移」。","sentenceOrder":247},
  {"id":"s_work_han_thu_79_248","chapterId":"ch_work_han_thu_79","textTraditional":"二八九一頁　四行　長樂嘗使行事（隸）〔肄〕宗廟，　景祐、殿、局本都作「肄」。注及下文同。","sentenceOrder":248},
  {"id":"s_work_han_thu_79_249","chapterId":"ch_work_han_thu_79","textTraditional":"二八九四頁　三行　不當治產業，通賓客，有稱（舉）〔譽〕。　景祐、殿本都作「譽」。　楊樹達說作「譽」是。","sentenceOrder":249},
  {"id":"s_work_han_thu_79_250","chapterId":"ch_work_han_thu_79","textTraditional":"二八九四頁　四行　一朝〔以〕晻昧語言見廢，　殿本有「以」字。王先謙說有「以」字是。","sentenceOrder":250},
  {"id":"s_work_han_thu_79_251","chapterId":"ch_work_han_thu_79","textTraditional":"二八九四頁一四行　蒙，蔽；督，視〔也〕。　景祐、殿、局本都有「也」字。","sentenceOrder":251},
  {"id":"s_work_han_thu_79_252","chapterId":"ch_work_han_thu_79","textTraditional":"二八九七頁一二行　今乃見子之志與我不同〔者〕也。　景祐、殿本都有「者」字。","sentenceOrder":252},
  {"id":"s_work_han_thu_79_253","chapterId":"ch_work_han_thu_79","textTraditional":"二九０一頁一六行　音（于向）〔千高〕反。　景祐、殿本都作「千高」，此誤。","sentenceOrder":253},
  {"id":"s_work_han_thu_79_254","chapterId":"ch_work_han_thu_79","textTraditional":"二九０二頁一一行　辜，〔罪也〕。　景祐、殿本都有「罪也」二字。","sentenceOrder":254},
  {"id":"s_work_han_thu_79_255","chapterId":"ch_work_han_thu_79","textTraditional":"二九０三頁　五行　然後〔教〕化可興，　錢大昭說南監本、閩本都有「教」字。按殿本有，景祐本無。","sentenceOrder":255},
  {"id":"s_work_han_thu_79_256","chapterId":"ch_work_han_thu_79","textTraditional":"二九０三頁　六行　汝南（相）〔桓〕寬次公治公羊春秋，　景祐、殿、局本都作「桓」。","sentenceOrder":256},
  {"id":"s_work_han_thu_79_257","chapterId":"ch_work_han_thu_79","textTraditional":"二九０四頁　九行　故寬引〔之〕。　景祐本有「之」字，他本都脫。","sentenceOrder":257},
  {"id":"s_work_han_thu_79_258","chapterId":"ch_work_han_thu_79","textTraditional":"二九０四頁一二行　撟讀（曰）〔與〕矯同，　景祐、殿、局本都作「與」。","sentenceOrder":258},
  {"id":"s_work_han_thu_80_1","chapterId":"ch_work_han_thu_80","textTraditional":"楊王孫者，孝武時人也。學黃老之術，家業千金，厚自奉養生，亡所不致。〔一〕及病且終，先令其子，〔二〕曰：「吾欲臝葬，以反吾真，〔三〕必亡易吾意。〔四〕死則為布囊盛尸，入地七尺，既下，從足引脫其囊，以身親土。」其子欲默而不從，重廢父命，〔五〕欲從（其）〔之〕，心又不忍，乃往見王孫友人祁侯。〔六〕","sentenceOrder":1},
  {"id":"s_work_han_thu_80_2","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「致，至也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_80_3","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　師古曰：「先令，為遺令。」","sentenceOrder":3},
  {"id":"s_work_han_thu_80_4","chapterId":"ch_work_han_thu_80","textTraditional":"〔三〕　師古曰：「臝者，不為衣衾棺槨者也。反，歸也。真者，自然之道也。臝音郎果反。」","sentenceOrder":4},
  {"id":"s_work_han_thu_80_5","chapterId":"ch_work_han_thu_80","textTraditional":"〔四〕　師古曰：「易，改也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_80_6","chapterId":"ch_work_han_thu_80","textTraditional":"〔五〕　師古曰：「重，難也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_80_7","chapterId":"ch_work_han_thu_80","textTraditional":"〔六〕　師古曰：「祁侯繒賀之孫承嗣者，名它。」","sentenceOrder":7},
  {"id":"s_work_han_thu_80_8","chapterId":"ch_work_han_thu_80","textTraditional":"祁侯與王孫書曰：「王孫苦疾，僕迫從上祠雍，未得詣前。〔一〕願存精神，省思慮，進醫藥，厚自持。竊（閒）〔聞〕王孫先令臝葬，令死者亡知則已，若其有知，是戮尸地下，將臝見先人，竊為王孫不取也。且孝經曰『為之棺槨衣衾』，是亦聖人之遺制，何必區區獨守所聞？〔二〕願王孫察焉。」","sentenceOrder":8},
  {"id":"s_work_han_thu_80_9","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「詣，至也。至前，言（求）〔來〕見也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_80_10","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　師古曰：「區區，小意也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_80_11","chapterId":"ch_work_han_thu_80","textTraditional":"王孫報曰：「蓋聞古之聖王，緣人情不忍其親，故為制禮，今則越之，〔一〕吾是以臝葬，將以矯世也。〔二〕夫厚葬誠亡益於死者，而俗人競以相高，靡財單幣，腐之地下。〔三〕或乃今日入而明日發，〔四〕此真與暴骸於中野何異！且夫死者，終生之化，而物之歸者也。歸者得至，化者得變，是物各反其真也。反真冥冥，亡形亡聲，乃合道情。夫飾外以華眾，厚葬以鬲真，〔五〕使歸者不得至，化者不得變，是使物各失其所也。且吾聞之，精神者天之有也，形骸者地之有也。〔六〕精神離形，各歸其真，故謂之鬼，鬼之為言歸也。其尸塊然獨處，豈有知哉？〔七〕裹以幣帛，鬲以棺槨，支體絡束，口含玉石，欲化不得，鬱為枯腊，千載之後，棺槨朽腐，乃得歸土，就其真宅。繇是言之，焉用久客！〔八〕昔帝堯之葬也，窾木為櫝，葛藟為緘，〔九〕其穿下不亂泉，上不泄殠。〔一０〕故聖王生易尚，死易葬也。〔一一〕不加功於亡用，不損財於亡謂。〔一二〕今費財厚葬，留歸鬲至，死者不知，生者不得，是謂重惑。於戲！吾不為也。」〔一三〕","sentenceOrder":11},
  {"id":"s_work_han_thu_80_12","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「言踰禮而厚葬也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_80_13","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　師古曰：「正曲曰矯。」","sentenceOrder":13},
  {"id":"s_work_han_thu_80_14","chapterId":"ch_work_han_thu_80","textTraditional":"〔三〕　師古曰：「靡，散也。單，盡也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_80_15","chapterId":"ch_work_han_thu_80","textTraditional":"〔四〕　師古曰：「言見發掘也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_80_16","chapterId":"ch_work_han_thu_80","textTraditional":"〔五〕　師古曰：「鬲與隔同。其後並類此。」","sentenceOrder":16},
  {"id":"s_work_han_thu_80_17","chapterId":"ch_work_han_thu_80","textTraditional":"〔六〕　師古曰：「文子稱天氣為魂。延陵季子云『骨肉下歸於土』，是以云然。」","sentenceOrder":17},
  {"id":"s_work_han_thu_80_18","chapterId":"ch_work_han_thu_80","textTraditional":"〔七〕　師古曰：「塊音口對反。」","sentenceOrder":18},
  {"id":"s_work_han_thu_80_19","chapterId":"ch_work_han_thu_80","textTraditional":"〔八〕　師古曰：「言不用久為客也。繇讀與由同。」","sentenceOrder":19},
  {"id":"s_work_han_thu_80_20","chapterId":"ch_work_han_thu_80","textTraditional":"〔九〕　服虔曰：「窾音款。款，空也，空木為匵。」師古曰：「匵即櫝字也。櫝，小棺也。藟，葛蔓也。一曰，藟亦草名，葛之類也。緘，束也。藟音力水反。緘音工咸反。」","sentenceOrder":20},
  {"id":"s_work_han_thu_80_21","chapterId":"ch_work_han_thu_80","textTraditional":"〔一０〕師古曰：「亂，絕也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_80_22","chapterId":"ch_work_han_thu_80","textTraditional":"〔一一〕師古曰：「尚，崇也。言生死皆儉約也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_80_23","chapterId":"ch_work_han_thu_80","textTraditional":"〔一二〕師古曰：「謂者，名稱也，亦指趣也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_80_24","chapterId":"ch_work_han_thu_80","textTraditional":"〔一三〕師古曰：「於讀曰烏。戲讀曰呼。」","sentenceOrder":24},
  {"id":"s_work_han_thu_80_25","chapterId":"ch_work_han_thu_80","textTraditional":"祁侯曰：「善。」遂臝葬。","sentenceOrder":25},
  {"id":"s_work_han_thu_80_26","chapterId":"ch_work_han_thu_80","textTraditional":"胡建字子孟，河東人也。孝武天漢中，守軍正丞，〔一〕貧亡車馬，常步與走卒起居，所以尉薦走卒，甚得其心。〔二〕時監軍御史為姦，穿北軍壘垣以為賈區，〔三〕建欲誅之，乃約其走卒〔四〕曰：「我欲與公有所誅，吾言取之則取，斬之則斬。」於是當選士馬日，監御史與護軍諸校列坐堂皇上，〔五〕建從走卒趨至堂皇下拜謁，因上堂〔皇〕，走卒皆上，建指監御史曰：「取彼。」走卒前曳下堂皇。建曰：「斬之。」遂斬御史。護軍諸校皆愕驚，不知所以。建亦已有成奏在其懷中，遂上奏曰：「臣聞軍法，立武以威眾，誅惡以禁邪。今監御史公穿軍垣以求賈利，〔六〕私買賣以與士巿，不立剛毅之心，勇猛之節，亡以帥先士大夫，尤失理不公。用文吏議，不至重法。黃帝李法曰：〔七〕『壁壘已定，穿窬不繇路，是謂姦人，姦人者殺。』〔八〕臣謹按軍法曰：『正亡屬將軍，將軍有罪以聞，〔九〕二千石以下行法焉。』〔一０〕丞於用法疑，〔一一〕執事不諉上，〔一二〕臣謹以斬，昧死以聞。」制曰：「司馬法曰『國容不入軍，軍容不入國』，何文吏也？〔一三〕三王或誓於軍中，欲民先成其慮也；或誓於軍門之外，欲民先意以待事也；〔一四〕或將交刃而誓，致民志也。』〔一五〕建又何疑焉？」建繇是顯名。","sentenceOrder":26},
  {"id":"s_work_han_thu_80_27","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「南北軍各有正，正又置丞，而建未得真官，兼守之。」","sentenceOrder":27},
  {"id":"s_work_han_thu_80_28","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　師古曰：「尉者，自上安之也。薦者，舉籍也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_80_29","chapterId":"ch_work_han_thu_80","textTraditional":"〔三〕　師古曰：「坐賣曰賈，為賣物之區也。區者，小室之名，若今小庵屋之類耳。故衛士之屋謂之區廬，宿衛（官）〔宮〕外士稱為區士也。賈音古。其下亦同。」","sentenceOrder":29},
  {"id":"s_work_han_thu_80_30","chapterId":"ch_work_han_thu_80","textTraditional":"〔四〕　師古曰：「約，束也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_80_31","chapterId":"ch_work_han_thu_80","textTraditional":"〔五〕　師古曰：「校者，軍之諸部校也。室無四壁曰皇。」","sentenceOrder":31},
  {"id":"s_work_han_thu_80_32","chapterId":"ch_work_han_thu_80","textTraditional":"〔六〕　師古曰：「公謂顯然為之。」","sentenceOrder":32},
  {"id":"s_work_han_thu_80_33","chapterId":"ch_work_han_thu_80","textTraditional":"〔七〕　蘇林曰：「獄官名也。天文志『左角李，右角將』。」孟康曰：「兵書之法也。」師古曰：「李者，法官之號也，總主征伐刑戮之事也，故稱其書曰李法。蘇說近之。」","sentenceOrder":33},
  {"id":"s_work_han_thu_80_34","chapterId":"ch_work_han_thu_80","textTraditional":"〔八〕　師古曰：「窬，小竇也，音踰。繇讀與由同。下皆類此。」","sentenceOrder":34},
  {"id":"s_work_han_thu_80_35","chapterId":"ch_work_han_thu_80","textTraditional":"〔九〕　師古曰：「言軍正不屬將軍。將軍有罪過，得表奏之。」","sentenceOrder":35},
  {"id":"s_work_han_thu_80_36","chapterId":"ch_work_han_thu_80","textTraditional":"〔一０〕孟康曰：「二千石謂軍中校尉、都尉之屬。」","sentenceOrder":36},
  {"id":"s_work_han_thu_80_37","chapterId":"ch_work_han_thu_80","textTraditional":"〔一一〕孟康曰：「丞屬軍正，斬御史於法有疑。」","sentenceOrder":37},
  {"id":"s_work_han_thu_80_38","chapterId":"ch_work_han_thu_80","textTraditional":"〔一二〕師古曰：「諉，累也。言執事者，當見法即行，不可以事累於上也。諉音女瑞反。累音力瑞反。」","sentenceOrder":38},
  {"id":"s_work_han_thu_80_39","chapterId":"ch_work_han_thu_80","textTraditional":"〔一三〕師古曰：「司馬法亦兵書之名也，解在主父偃傳。詔言在於軍中，何用文吏議也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_80_40","chapterId":"ch_work_han_thu_80","textTraditional":"〔一四〕師古曰：「慮謂計念也。先意謂先為之意也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_80_41","chapterId":"ch_work_han_thu_80","textTraditional":"〔一五〕師古曰：「欲致民勇志，使不奔北。」","sentenceOrder":41},
  {"id":"s_work_han_thu_80_42","chapterId":"ch_work_han_thu_80","textTraditional":"後為渭城令，治甚有聲。值昭帝幼，皇后父上官將軍安與帝姊蓋主私夫丁外人相善。外人（矯）〔驕〕恣，怨故京兆尹樊福，使客射殺之。客臧公主廬，吏不敢捕。渭城令建將吏卒圍捕。蓋主聞之，與外人、上官將軍多從奴客往，奔射追吏，〔一〕吏散走。主使僕射劾渭城令游徼傷主家奴。建報亡它坐。〔二〕蓋主怒，使人上書告建侵辱長公主，射甲舍門。〔三〕知吏賊傷奴，辟報故不窮審。〔四〕大將軍霍光寢其奏。後光病，上官氏代聽事，下吏捕建，建自殺。吏民稱冤，至今渭城立其祠。","sentenceOrder":42},
  {"id":"s_work_han_thu_80_43","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「犇，古奔字也。奔走赴之而射也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_80_44","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　服虔曰：「言游徼奉公，無它坐也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_80_45","chapterId":"ch_work_han_thu_80","textTraditional":"〔三〕　師古曰：「甲舍即甲第，公主之宅。」","sentenceOrder":45},
  {"id":"s_work_han_thu_80_46","chapterId":"ch_work_han_thu_80","textTraditional":"〔四〕　蘇林曰：「辟，迴也。報，論也。斷獄（也）為報。故言有故也。不窮審，〔不〕窮盡其事也。」師古曰：「蘇說非也。言為游徼避罪而妄報文書，故不窮治也。辟讀曰避。」","sentenceOrder":46},
  {"id":"s_work_han_thu_80_47","chapterId":"ch_work_han_thu_80","textTraditional":"朱雲字游，魯人也，徙平陵。少時通輕俠，借客報仇。〔一〕長八尺餘，容貌甚壯，以勇力聞。年四十，乃變節從博士白子友受易，又事前將軍蕭望之受論語，皆能傳其業。好倜儻大節，〔二〕當世以是高之。","sentenceOrder":47},
  {"id":"s_work_han_thu_80_48","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「借，助也，音子夜反。」","sentenceOrder":48},
  {"id":"s_work_han_thu_80_49","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　師古曰：「倜音吐歷反。」","sentenceOrder":49},
  {"id":"s_work_han_thu_80_50","chapterId":"ch_work_han_thu_80","textTraditional":"元帝時，琅邪貢禹為御史大夫，而華陰守丞嘉上封事，〔一〕言『治道在於得賢，御史之官，宰相之副，九卿之右，〔二〕不可不選。平陵朱雲，兼資文武，忠正有智略，可使以六百石秩試守御史大夫，以盡其能。」上乃下其事問公卿。太子少傅匡衡對，以為「大臣者，國家之股肱，萬姓所瞻仰，明王所慎擇也。傳曰下輕其上爵，賤人圖柄臣，則國家搖動而民不靜矣。〔三〕今嘉從守丞而圖大臣之位，欲以匹夫徒（走）〔步〕之人而超九卿之右，非所以重國家而尊社稷也。自堯之用舜，文王於太公，猶試然後爵之，又況朱雲者乎？雲素好勇，數犯法亡命，受易頗有師道，其行義未有以異。今御史大夫禹絜白廉正，經術通明，有伯夷、史魚之風，海內莫不聞知，而嘉（〈暂缺F51A〉）〔猥〕稱雲，〔四〕欲令為御史大夫，妄相稱舉，疑有姦心，漸不可長，宜下有司案驗以明好惡。」嘉竟坐之。","sentenceOrder":50},
  {"id":"s_work_han_thu_80_51","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「守華陰縣丞者，其人名嘉。」","sentenceOrder":51},
  {"id":"s_work_han_thu_80_52","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　師古曰：「右言在上也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_80_53","chapterId":"ch_work_han_thu_80","textTraditional":"〔三〕　師古曰：「上爵，大官也。圖，謀也。柄臣，執權之（官）〔臣〕。」","sentenceOrder":53},
  {"id":"s_work_han_thu_80_54","chapterId":"ch_work_han_thu_80","textTraditional":"〔四〕　師古曰：「（〈暂缺F51A〉）〔猥〕，曲也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_80_55","chapterId":"ch_work_han_thu_80","textTraditional":"是時，少府五鹿充宗貴幸，為梁丘易。自宣帝時善梁丘氏說，元帝好之，欲考其異同，令充宗與諸易家論。充宗乘貴辯口，〔一〕諸儒莫能與抗，皆稱疾不敢會。有薦雲者，召入，攝{齊衣}登堂，〔二〕抗首而請，〔三〕音動左右。既論難，連拄五鹿君，〔四〕故諸儒為之語曰：「五鹿嶽嶽，朱雲折其角。」〔五〕繇是為博士。","sentenceOrder":55},
  {"id":"s_work_han_thu_80_56","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「乘，因也。言因藉尊貴之權也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_80_57","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　師古曰：「{齊衣}，衣下之裳音子私反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_80_58","chapterId":"ch_work_han_thu_80","textTraditional":"〔三〕　師古曰：「抗，舉也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_80_59","chapterId":"ch_work_han_thu_80","textTraditional":"〔四〕　師古曰：「拄，刺也，距也，音竹庾反。」","sentenceOrder":59},
  {"id":"s_work_han_thu_80_60","chapterId":"ch_work_han_thu_80","textTraditional":"〔五〕　師古曰：「嶽嶽，長角之貌。」","sentenceOrder":60},
  {"id":"s_work_han_thu_80_61","chapterId":"ch_work_han_thu_80","textTraditional":"遷杜陵令，坐故縱亡命，會赦，舉方正，為槐里令。時中書令石顯用事，與充宗為黨，百僚畏之。唯御史中丞陳咸年少抗節，不附顯等，而與雲相結。雲數上疏，言丞相韋玄成容身保位，亡能往來〔一〕，而咸數毀石顯。久之，有司考雲，疑風吏殺人。〔二〕群臣朝見，上問丞相以雲治行。丞相玄成言雲暴虐亡狀。〔三〕時陳咸在前，聞之，以語雲。雲上書自訟，咸為定奏草，求下御史中丞。事下丞相，丞相部吏考立其殺人罪。〔四〕雲亡入長安，復與咸計議。丞相具發其事，奏「咸宿衛執法之臣，幸得進見，漏泄所聞，以私語雲，為定奏草，欲令自下治，〔五〕後知雲亡命罪人，而與交通，雲以故不得。」〔六〕上於是下咸、雲獄，減死為城旦。咸、雲遂廢錮，終元帝世。","sentenceOrder":61},
  {"id":"s_work_han_thu_80_62","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　李奇曰：「不能有所前卻也。」師古曰：「周書君奭之篇稱周公曰：『惟文王尚克修和有夏，有若虢叔、閎夭、散宜生、泰顛、南宮括。』又曰『亡能往來』。故雲引此以為言也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_80_63","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　師古曰：「風讀曰諷。」","sentenceOrder":63},
  {"id":"s_work_han_thu_80_64","chapterId":"ch_work_han_thu_80","textTraditional":"〔三〕　師古曰：「無善狀也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_80_65","chapterId":"ch_work_han_thu_80","textTraditional":"〔四〕　師古曰：「立，成也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_80_66","chapterId":"ch_work_han_thu_80","textTraditional":"〔五〕　師古曰：「咸為御史中丞，而奏請下中丞，故云自下治。」","sentenceOrder":66},
  {"id":"s_work_han_thu_80_67","chapterId":"ch_work_han_thu_80","textTraditional":"〔六〕　師古曰：「吏捕之不得。」","sentenceOrder":67},
  {"id":"s_work_han_thu_80_68","chapterId":"ch_work_han_thu_80","textTraditional":"至成帝時，丞相故安昌侯張禹以帝師位特進，甚尊重。雲上書求見，公卿在前。雲曰：「今朝廷大臣上不能匡主，下亡以益民，皆尸位素餐，〔一〕孔子所謂『鄙夫不可與事君』，『苟患失之，亡所不至』者也。〔二〕臣願賜尚方斬馬劍，斷佞臣一人以厲其餘。」〔三〕上問：「誰也？」對曰「安昌侯張禹。」上大怒，曰：「小臣居下訕上，廷辱師傅，〔四〕罪死不赦。」御史將雲下，雲攀殿檻，檻折。〔五〕雲呼曰：〔六〕「臣得下從龍逄、比干遊於地下，足矣〔七〕！未知聖朝何如耳？」〔八〕御史遂將雲去。於是左將軍辛慶忌免冠解印綬，叩頭殿下曰：「此臣素著狂直於世。〔九〕使其言是，不可誅；其言非，固當容之。臣敢以死爭。」慶忌叩頭流血。上意解，然後得已。及後當治檻，上曰：「勿易！因而輯之，以旌直臣。〔一０〕」","sentenceOrder":68},
  {"id":"s_work_han_thu_80_69","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「尸，主也。素，空也。尸位者，不舉其事，但主其位而已。素餐者，德不稱官，空當食祿。」","sentenceOrder":69},
  {"id":"s_work_han_thu_80_70","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　師古曰：「皆論語所載孔子之言也。苟患失其寵祿，則言行僻邪，無所不至也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_80_71","chapterId":"ch_work_han_thu_80","textTraditional":"〔三〕　師古曰：「尚方，少府之屬官也，作供御器物，故有斬馬劍，劍利可以斬馬也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_80_72","chapterId":"ch_work_han_thu_80","textTraditional":"〔四〕　師古曰：「訕，謗也，音所諫反，又音刪。」","sentenceOrder":72},
  {"id":"s_work_han_thu_80_73","chapterId":"ch_work_han_thu_80","textTraditional":"〔五〕　師古曰：「檻，軒前欄也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_80_74","chapterId":"ch_work_han_thu_80","textTraditional":"〔六〕　師古曰：「呼，叫也，音火故反。」","sentenceOrder":74},
  {"id":"s_work_han_thu_80_75","chapterId":"ch_work_han_thu_80","textTraditional":"〔七〕　師古曰：「關龍逄，桀臣，王子比干，紂之諸父，皆以諫而死，故云然。」","sentenceOrder":75},
  {"id":"s_work_han_thu_80_76","chapterId":"ch_work_han_thu_80","textTraditional":"〔八〕　師古曰：「言殺直臣其聲惡。」","sentenceOrder":76},
  {"id":"s_work_han_thu_80_77","chapterId":"ch_work_han_thu_80","textTraditional":"〔九〕　師古曰：「著，表也。言此名久彰表。」","sentenceOrder":77},
  {"id":"s_work_han_thu_80_78","chapterId":"ch_work_han_thu_80","textTraditional":"〔一０〕師古曰：「輯與集同，謂補合之也。旌，表也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_80_79","chapterId":"ch_work_han_thu_80","textTraditional":"雲自是之後不復仕，常居鄠田，時出乘牛車從諸生，所過皆敬事焉。薛宣為丞相，雲往見之。宣備賓主禮，因留雲宿，從容謂雲曰：〔一〕「在田野亡事，且留我東閤，可以觀四方奇士。」雲曰：「小生乃欲相吏邪？」〔二〕宣不敢復言。","sentenceOrder":79},
  {"id":"s_work_han_thu_80_80","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「從音七庸反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_80_81","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　師古曰：「小生謂其新學後進。言欲以我為吏乎？」","sentenceOrder":81},
  {"id":"s_work_han_thu_80_82","chapterId":"ch_work_han_thu_80","textTraditional":"其教授，擇諸生，然後為弟子。九江嚴望及望兄子元，字仲，能傳雲學，皆為博士。望至泰山太守。","sentenceOrder":82},
  {"id":"s_work_han_thu_80_83","chapterId":"ch_work_han_thu_80","textTraditional":"雲年七十餘，終於家。病不呼醫飲藥。遺言以身服斂，棺周於身，土周於槨，〔一〕為丈五墳，葬平陵東郭外。","sentenceOrder":83},
  {"id":"s_work_han_thu_80_84","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「棺周於身，小棺裁容身也。土周於槨，冢壙裁容槨也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_80_85","chapterId":"ch_work_han_thu_80","textTraditional":"梅福字子真，九江壽春人也。少學長安，明尚書、穀梁春秋，為郡文學，補南昌尉。〔一〕後去官歸壽春，數因縣道上言變事，〔二〕求假軺傳，〔三〕詣行在所條對急政，〔四〕輒報罷。","sentenceOrder":85},
  {"id":"s_work_han_thu_80_86","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「豫章之縣。」","sentenceOrder":86},
  {"id":"s_work_han_thu_80_87","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　師古曰：「附縣道之使而封奏也。變謂非常之事。」","sentenceOrder":87},
  {"id":"s_work_han_thu_80_88","chapterId":"ch_work_han_thu_80","textTraditional":"〔三〕　師古曰：「小車之傳也。軺音遙。傳音張戀反。」","sentenceOrder":88},
  {"id":"s_work_han_thu_80_89","chapterId":"ch_work_han_thu_80","textTraditional":"〔四〕　師古曰：「條對者，一一條錄而對之。」","sentenceOrder":89},
  {"id":"s_work_han_thu_80_90","chapterId":"ch_work_han_thu_80","textTraditional":"是時成帝委任大將軍王鳳，鳳專勢擅朝，而京兆尹王章素忠直，譏刺鳳，為鳳所誅。王氏浸盛，〔一〕災異數見，群下莫敢正言。福復上書曰：","sentenceOrder":90},
  {"id":"s_work_han_thu_80_91","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「浸，漸也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_80_92","chapterId":"ch_work_han_thu_80","textTraditional":"臣聞箕子佯狂於殷，而為周陳洪範；叔孫通遁秦歸漢，制作儀品。〔一〕夫叔孫先非不忠也，〔二〕箕子非疏其家而畔親也〔三〕，不可為言也。昔高祖納善若不及，從諫若轉圜，〔四〕聽言不求其能，舉功不考其素。〔五〕陳平起於亡命而為謀主，韓信拔於行陳而建上將。〔六〕故天下之士雲合歸漢，〔七〕爭進奇異，知者竭其策，愚者盡其慮，勇士極其節，怯夫勉其死。合天下之知，并天下之威，是以舉秦如鴻毛，取楚若拾遺，〔八〕此高祖所以亡敵於天下也。〔九〕孝文皇帝起於代谷，〔一０〕非有周召之師，伊呂之佐也，〔一一〕循高祖之法，加以恭儉。當此之時，天下幾平。〔一二〕繇是言之，循高祖之法則治，不循則亂。何者？秦為亡道，削仲尼之跡，滅周公之軌，〔一三〕壞井田，除五等，禮廢樂崩，王道不通，故欲行王道者莫能致其功也。孝（文）〔武〕皇帝好忠諫，說至言〔一四〕，出爵不待廉茂，慶賜不須顯功，〔一五〕是以天下布衣各厲志竭精以赴闕廷自衒鬻者不可勝數。漢家得賢，於此為盛。使孝武皇帝聽用其計，升平可致。〔一六〕於是積尸暴骨，快心胡越，故淮南（安王）〔王安〕緣間而起。所以計慮不成而謀議泄者，以眾賢聚於本朝，〔一七〕故其大臣勢陵不敢和從也。〔一八〕方今布衣乃窺國家之隙，見間而起者，蜀郡是也。〔一九〕及山陽亡徒蘇令之群，蹈藉名都大郡，求黨與，索隨和，〔二０〕而亡逃匿之意。此皆輕量大臣，亡所畏忌，國家之權輕，故匹夫欲與上爭衡也。","sentenceOrder":92},
  {"id":"s_work_han_thu_80_93","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「遁，逃也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_80_94","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　師古曰：「先猶言先生也。一曰，先謂在秦時。」","sentenceOrder":94},
  {"id":"s_work_han_thu_80_95","chapterId":"ch_work_han_thu_80","textTraditional":"〔三〕　師古曰：「箕子，紂之諸父，故言疏家畔親也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_80_96","chapterId":"ch_work_han_thu_80","textTraditional":"〔四〕　師古曰：「不及，恐失之也。轉圜，言其順也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_80_97","chapterId":"ch_work_han_thu_80","textTraditional":"〔五〕　師古曰：「直取其功，不論其舊行及所從來也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_80_98","chapterId":"ch_work_han_thu_80","textTraditional":"〔六〕　師古曰：「立以為大將軍。」","sentenceOrder":98},
  {"id":"s_work_han_thu_80_99","chapterId":"ch_work_han_thu_80","textTraditional":"〔七〕　師古曰：「言四面而至。」","sentenceOrder":99},
  {"id":"s_work_han_thu_80_100","chapterId":"ch_work_han_thu_80","textTraditional":"〔八〕　師古曰：「鴻毛喻輕。拾遺，言其易也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_80_101","chapterId":"ch_work_han_thu_80","textTraditional":"〔九〕　師古曰：「亡讀曰無。」","sentenceOrder":101},
  {"id":"s_work_han_thu_80_102","chapterId":"ch_work_han_thu_80","textTraditional":"〔一０〕師古曰：「從代而來即帝位。」","sentenceOrder":102},
  {"id":"s_work_han_thu_80_103","chapterId":"ch_work_han_thu_80","textTraditional":"〔一一〕師古曰：「召讀曰邵。」","sentenceOrder":103},
  {"id":"s_work_han_thu_80_104","chapterId":"ch_work_han_thu_80","textTraditional":"〔一二〕師古曰：「幾音距依反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_80_105","chapterId":"ch_work_han_thu_80","textTraditional":"〔一三〕師古曰：「軌，法也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_80_106","chapterId":"ch_work_han_thu_80","textTraditional":"〔一四〕師古曰：「說讀曰悅。」","sentenceOrder":106},
  {"id":"s_work_han_thu_80_107","chapterId":"ch_work_han_thu_80","textTraditional":"〔一五〕師古曰：「謂諫爭合意即得官爵，不由薦舉及軍功也。廉，廉吏也。茂，茂材也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_80_108","chapterId":"ch_work_han_thu_80","textTraditional":"〔一六〕張晏曰：「民有三年之儲曰升平。」","sentenceOrder":108},
  {"id":"s_work_han_thu_80_109","chapterId":"ch_work_han_thu_80","textTraditional":"〔一七〕師古曰：「本朝，漢朝也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_80_110","chapterId":"ch_work_han_thu_80","textTraditional":"〔一八〕服虔曰：「臣勢陵君也。」師古曰：「謂淮南大臣相內史之屬也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_80_111","chapterId":"ch_work_han_thu_80","textTraditional":"〔一九〕孟康曰：「成帝鴻嘉中廣漢男子鄭躬等反是也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_80_112","chapterId":"ch_work_han_thu_80","textTraditional":"〔二０〕李奇曰：「求索與己和及隨己者。」","sentenceOrder":112},
  {"id":"s_work_han_thu_80_113","chapterId":"ch_work_han_thu_80","textTraditional":"士者，國之重器；得士則重，失士則輕。詩云：「濟濟多士，文王以寧。」〔一〕廟堂之議，非草茅所當言也。臣誠恐身塗野草，尸并卒伍，故數上書求見，輒報罷。臣聞齊桓之時有以九九見者，桓公不逆，欲以致大也。〔二〕今臣所言非特九九也，陛下距臣者三矣，此天下士所以不至也。昔秦武王好力，任鄙叩關自鬻；〔三〕繆公行伯，繇余歸德。〔四〕今欲致天下之士，民有上書求見者，輒使詣尚書問其所言，言可采取者，秩以升斗之祿，賜以一束之帛。若此，則天下之士發憤懣，吐忠言，〔五〕嘉謀日聞於上，天下條貫，國家表裏，爛然可睹矣。〔六〕夫以四海之廣，士民之數，能言之類至眾多也。然其俊桀指世陳政，言成文章，質之先聖而不繆，施之當世合時務，〔七〕若此者，亦亡幾人。〔八〕故爵祿束帛者，天下之厎石，高祖所以厲世摩鈍也。〔九〕孔子曰：「工欲善其事，必先利其器。」〔一０〕至秦則不然，張誹謗之罔，以為漢驅除，倒持泰阿，授楚其柄。〔一一〕故誠能勿失其柄，天下雖有不順，莫敢觸其鋒，此孝武皇帝所以辟地建功為漢世宗也。〔一二〕今不循伯者之道〔一三〕，乃欲以三代選舉之法取當時之士，猶察伯樂之圖，求騏驥於市，而不可得，亦已明矣。故高祖棄陳平之過而獲其謀，〔一四〕晉文召天王，齊桓用其讎，〔一五〕（亡）〔有〕益於時，不顧逆順，此所謂伯道者也。一色成體謂之醇，白黑雜合謂之駮。欲以承平之法治暴秦之緒，〔一六〕猶以鄉飲酒之禮理軍市也。","sentenceOrder":113},
  {"id":"s_work_han_thu_80_114","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「大雅文王之詩也。已解於上。」","sentenceOrder":114},
  {"id":"s_work_han_thu_80_115","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　師古曰：「九九，算術，若今九章、五曹之輩。」","sentenceOrder":115},
  {"id":"s_work_han_thu_80_116","chapterId":"ch_work_han_thu_80","textTraditional":"〔三〕　師古曰：「秦武王即孝公之孫，惠文王之子也。任鄙，力士也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_80_117","chapterId":"ch_work_han_thu_80","textTraditional":"〔四〕　師古曰：「即秦穆公。伯讀曰霸。繇讀曰由。」","sentenceOrder":117},
  {"id":"s_work_han_thu_80_118","chapterId":"ch_work_han_thu_80","textTraditional":"〔五〕　師古曰：「懣音滿。」","sentenceOrder":118},
  {"id":"s_work_han_thu_80_119","chapterId":"ch_work_han_thu_80","textTraditional":"〔六〕　師古曰：「爛然，分明之貌也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_80_120","chapterId":"ch_work_han_thu_80","textTraditional":"〔七〕　師古曰：「質，正也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_80_121","chapterId":"ch_work_han_thu_80","textTraditional":"〔八〕　師古曰：「無幾，言不多也。幾音居豈反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_80_122","chapterId":"ch_work_han_thu_80","textTraditional":"〔九〕　師古曰：「厎，細石也，音之履反，又音秖。」","sentenceOrder":122},
  {"id":"s_work_han_thu_80_123","chapterId":"ch_work_han_thu_80","textTraditional":"〔一０〕師古曰：「論語載孔子之言也。工以喻國政，利器喻賢材。」","sentenceOrder":123},
  {"id":"s_work_han_thu_80_124","chapterId":"ch_work_han_thu_80","textTraditional":"〔一一〕師古曰：「泰阿，劍名，歐冶所鑄也。言秦無道，令陳涉、項羽乘間而發，譬倒持劍而以把授與人也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_80_125","chapterId":"ch_work_han_thu_80","textTraditional":"〔一二〕師古曰：「辟讀曰闢。」","sentenceOrder":125},
  {"id":"s_work_han_thu_80_126","chapterId":"ch_work_han_thu_80","textTraditional":"〔一三〕師古曰：「伯讀曰霸。次下亦同。」","sentenceOrder":126},
  {"id":"s_work_han_thu_80_127","chapterId":"ch_work_han_thu_80","textTraditional":"〔一四〕師古曰：「盜嫂受金之事。」","sentenceOrder":127},
  {"id":"s_work_han_thu_80_128","chapterId":"ch_work_han_thu_80","textTraditional":"〔一五〕師古曰：「召天王，謂狩于河陽也。用其讎，謂以管仲為相。並解於上。」","sentenceOrder":128},
  {"id":"s_work_han_thu_80_129","chapterId":"ch_work_han_thu_80","textTraditional":"〔一六〕師古曰：「緒謂餘業也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_80_130","chapterId":"ch_work_han_thu_80","textTraditional":"今陛下既不納天下之言，又加戮焉。夫〈截，中“隹改鳥”〉鵲遭害，則仁鳥增逝；〔一〕愚者蒙戮，則知士深退。〔二〕間者愚民上疏，多觸不急之法，或下廷尉，而死者眾。〔三〕自陽朔以來，天下以言為諱，朝廷尤甚，〔四〕群臣皆承順上指，莫有執正。何以明其然也？取民所上書，陛下之所善，試下之廷尉，廷尉必曰「非所宜言，大不敬。」以此卜之，一矣。故京兆尹王章資質忠直，敢面引廷爭，孝元皇帝擢之，以厲具臣而矯曲朝。〔五〕及至陛下，戮及妻子。且惡惡止其身，王章非有反畔之辜，而殃及家。折直士之節，結諫臣之舌，群臣皆知其非，然不敢爭，天下以言為戒，最國家之大患也。願陛下循高祖之軌，杜亡秦之路，〔六〕數御十月之歌，〔七〕留意亡逸之戒〔八〕，除不急之法，下亡諱之詔，博覽兼聽，謀及疏賤，令深者不隱，遠者不塞，所謂「辟四門，明四目」也。〔九〕且不急之法，誹謗之微者也。「往者不可及，來者猶可追。」方今君命犯而主威奪，〔一０〕外戚之權日以益隆，陛下不見其形，願察其景。建始以來，日食地震，以率言之，三倍春秋，水災亡與比數。〔一一〕陰盛陽微，金鐵為飛，此何景也！〔一二〕漢興以來，社稷三危。呂、霍、上官皆母后之家也，親親之道，全之為右，〔一三〕當與之賢師良傅，教以忠孝之道。今乃尊寵其位，授以魁柄，〔一四〕使之驕逆，至於夷滅，〔一五〕此失親親之大者也。自霍光之賢，不能為子孫慮，故權臣易世則危。書曰：「毋若火，始庸庸。」〔一六〕勢陵於君，權隆於主，然後防之，亦亡及已。〔一七〕","sentenceOrder":130},
  {"id":"s_work_han_thu_80_131","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「〈截，中“隹改鳥”〉，鴟也。仁鳥，鸞鳳也。〈截，中“隹改鳥”〉音緣。」","sentenceOrder":131},
  {"id":"s_work_han_thu_80_132","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　師古曰：「蒙，被也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_80_133","chapterId":"ch_work_han_thu_80","textTraditional":"〔三〕　師古曰：「以其所言為不急而罪之也。」","sentenceOrder":133},
  {"id":"s_work_han_thu_80_134","chapterId":"ch_work_han_thu_80","textTraditional":"〔四〕　師古曰：「防人之口，法禁嚴切。」","sentenceOrder":134},
  {"id":"s_work_han_thu_80_135","chapterId":"ch_work_han_thu_80","textTraditional":"〔五〕　師古曰：「具臣，具位之臣無益者也。矯，正也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_80_136","chapterId":"ch_work_han_thu_80","textTraditional":"〔六〕　師古曰：「杜，塞也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_80_137","chapterId":"ch_work_han_thu_80","textTraditional":"〔七〕　孟康曰：「福譏切王氏。十月之詩，刺后族太盛也。」師古曰：「詩小雅十月之交篇也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_80_138","chapterId":"ch_work_han_thu_80","textTraditional":"〔八〕　師古曰：「周書篇名也，周公作之以戒成王。」","sentenceOrder":138},
  {"id":"s_work_han_thu_80_139","chapterId":"ch_work_han_thu_80","textTraditional":"〔九〕　師古曰：「虞書舜典曰『闢四門，明四目』，言開四門以致眾賢，則明視於四方也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_80_140","chapterId":"ch_work_han_thu_80","textTraditional":"〔一０〕師古曰：「君命犯者，謂大臣犯君之命。」","sentenceOrder":140},
  {"id":"s_work_han_thu_80_141","chapterId":"ch_work_han_thu_80","textTraditional":"〔一一〕師古曰：「言其極多，不可比較而數也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_80_142","chapterId":"ch_work_han_thu_80","textTraditional":"〔一二〕張晏曰：「河平二年，沛郡鐵官鑄鐵如星飛上去，權臣用事之異也。」蘇林曰：「『言之不從，是謂不艾，則金不從革。』景，象也。何象，言將危亡也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_80_143","chapterId":"ch_work_han_thu_80","textTraditional":"〔一三〕師古曰：「務全安之，此為上。」","sentenceOrder":143},
  {"id":"s_work_han_thu_80_144","chapterId":"ch_work_han_thu_80","textTraditional":"〔一四〕師古曰：「以斗為喻也，斗身為魁。」","sentenceOrder":144},
  {"id":"s_work_han_thu_80_145","chapterId":"ch_work_han_thu_80","textTraditional":"〔一五〕師古曰：「夷，平也，謂平除之。」","sentenceOrder":145},
  {"id":"s_work_han_thu_80_146","chapterId":"ch_work_han_thu_80","textTraditional":"〔一六〕師古曰：「周書洛誥之辭也。庸庸，微小貌也。言火始微小，不早撲滅則至熾盛。大臣貴擅，亦當早圖黜其權也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_80_147","chapterId":"ch_work_han_thu_80","textTraditional":"〔一七〕師古曰：「已，語終辭。」","sentenceOrder":147},
  {"id":"s_work_han_thu_80_148","chapterId":"ch_work_han_thu_80","textTraditional":"上遂不納。","sentenceOrder":148},
  {"id":"s_work_han_thu_80_149","chapterId":"ch_work_han_thu_80","textTraditional":"成帝久亡繼嗣，福以為宜建三統，封孔子之世以為殷後，復上書曰：","sentenceOrder":149},
  {"id":"s_work_han_thu_80_150","chapterId":"ch_work_han_thu_80","textTraditional":"臣聞「不在其位，不謀其政」。政者職也，位卑而言高者罪也。越職觸罪，危言世患，雖伏質橫分，臣之願也。〔一〕守職不言，沒齒身全，死之日，尸未腐而名滅，雖有景公之位，伏歷千駟，臣不貪也。〔二〕故願壹登文石之陛，涉赤墀之塗，〔三〕當戶牖之法坐，〔四〕盡平生之愚慮。亡益於時，有遺於世，〔五〕此臣寢所以不安，食所以忘味也。願陛下深省臣言。〔六〕","sentenceOrder":150},
  {"id":"s_work_han_thu_80_151","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「伏質，斬刑也。橫分，謂身首分離也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_80_152","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　師古曰：「景公，齊景公也。論語云：『齊景公有馬千駟，死之日，民無得而稱焉。』故引之也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_80_153","chapterId":"ch_work_han_thu_80","textTraditional":"〔三〕　應劭曰：「以丹淹泥塗殿上也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_80_154","chapterId":"ch_work_han_thu_80","textTraditional":"〔四〕　師古曰：「戶牖之間謂之扆，言負扆也。法坐，正坐也，聽朝之處，猶言法官、法駕也。坐音才臥反。」","sentenceOrder":154},
  {"id":"s_work_han_thu_80_155","chapterId":"ch_work_han_thu_80","textTraditional":"〔五〕　師古曰：「遺，留也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_80_156","chapterId":"ch_work_han_thu_80","textTraditional":"〔六〕　師古曰：「省，察也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_80_157","chapterId":"ch_work_han_thu_80","textTraditional":"臣聞存人所以自立也，壅人所以自塞也。善惡之報，各如其事。昔者秦滅二周，夷六國，〔一〕隱士不顯，佚民不舉，〔二〕絕三統，滅天道，是以身危子殺，厥孫不嗣，〔三〕所謂壅人以自塞者也。故武王克殷，未下車，存五帝之後，封殷於宋，紹夏於杞，〔四〕明著三統，示不獨有也。是以姬姓半天下，遷廟之主，流出於戶，〔五〕所謂存人以自立者也。今成湯不祀，殷人亡後。陛下繼嗣久微，殆為此也。春秋經曰：「宋殺其大夫。」穀梁傳曰：「其不稱名姓，以其在祖位，尊之也。」〔六〕此言孔子故殷後也，雖不正統，封其子孫以為殷後，禮亦宜之。何者？諸侯奪宗，聖庶奪適。〔七〕傳曰「賢者子孫宜有土」，而況聖人，又殷之後哉！昔成王以諸侯禮葬周公，而皇天動威，雷風著災。〔八〕今仲尼之廟不出闕里，〔九〕孔氏子孫不免編戶，〔一０〕以聖人而歆匹夫之祀，非皇天之意也。今陛下誠能據仲尼之素功，以封其子孫，〔一一〕則國家必獲其福，又陛下之名與天亡極。何者？追聖人素功，封其子孫，未有法也，後聖必以為則。不滅之名，可不勉哉！","sentenceOrder":157},
  {"id":"s_work_han_thu_80_158","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「二周，東周、西周君也。六國，齊、楚、韓、魏、趙、燕。」","sentenceOrder":158},
  {"id":"s_work_han_thu_80_159","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　師古曰：「佚與逸同。」","sentenceOrder":159},
  {"id":"s_work_han_thu_80_160","chapterId":"ch_work_han_thu_80","textTraditional":"〔三〕　張晏曰：「身為燕丹、張良所謀，子二世見殺。孫謂子嬰。」","sentenceOrder":160},
  {"id":"s_work_han_thu_80_161","chapterId":"ch_work_han_thu_80","textTraditional":"〔四〕　師古曰：「謂封黃帝之後於薊，帝堯之後於祝，帝舜之後於陳，并杞、宋，是為五帝。」","sentenceOrder":161},
  {"id":"s_work_han_thu_80_162","chapterId":"ch_work_han_thu_80","textTraditional":"〔五〕　李奇曰：「言其多。」","sentenceOrder":162},
  {"id":"s_work_han_thu_80_163","chapterId":"ch_work_han_thu_80","textTraditional":"〔六〕　師古曰：「事在僖二十五年。穀梁所云『在祖位』者，謂孔子本宋孔父之後，防叔奔魯，遂為魯人。今宋所殺者亦孔父之後留在宋者，於孔子為（祀）〔祖〕列，故尊而不名也。」","sentenceOrder":163},
  {"id":"s_work_han_thu_80_164","chapterId":"ch_work_han_thu_80","textTraditional":"〔七〕　如淳曰：「奪宗，始封之君尊為諸侯，則奪其舊為宗子之事也。奪適，文王舍伯邑考而立武王是也。孔子雖庶，可為殷後。」師古曰：「適讀曰嫡。」","sentenceOrder":164},
  {"id":"s_work_han_thu_80_165","chapterId":"ch_work_han_thu_80","textTraditional":"〔八〕　師古曰：「尚書大傳云：『周公疾，曰：「吾死必葬於成周，示天下臣於成王也。」周公死，天乃雷雨以風，禾盡偃，大木斯拔。國恐，王與大夫開金縢之書，執書以泣曰：「周公勤勞王家，予幼人弗及知。」乃不葬於成周而葬之於畢，示天〔下〕不敢臣。』」","sentenceOrder":165},
  {"id":"s_work_han_thu_80_166","chapterId":"ch_work_han_thu_80","textTraditional":"〔九〕　師古曰：「闕里，孔子舊里也。言除此之外，更無祭祀孔子者也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_80_167","chapterId":"ch_work_han_thu_80","textTraditional":"〔一０〕師古曰：「列為庶人也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_80_168","chapterId":"ch_work_han_thu_80","textTraditional":"〔一一〕師古曰：「素功，素王之功也。穀梁傳曰『孔子素王』。」","sentenceOrder":168},
  {"id":"s_work_han_thu_80_169","chapterId":"ch_work_han_thu_80","textTraditional":"福孤遠，又譏切王氏，故終不見納。","sentenceOrder":169},
  {"id":"s_work_han_thu_80_170","chapterId":"ch_work_han_thu_80","textTraditional":"〔初〕，武帝時，始封周後姬嘉為周子南君，至元帝時，尊周子南君為周承休侯，位次諸侯王。使諸大夫博士求殷後，分散為十餘姓，郡國往往得其大家，推求子孫，絕不能紀。〔一〕時匡衡議，以為「王者存二王後，所以尊其先王而通三統也。其犯誅絕之罪者絕，而更封他親為始封君，上承其王者之始祖。春秋之義，諸侯不能守其社稷者絕。今宋國已不守其統而失國矣，則宜更立殷後為始封君，而上承湯統，非當繼宋之絕侯也，宜明得殷後而已。今之故宋，推求其嫡，久遠不可得；雖得其嫡，嫡之先已絕，不當得立。禮記孔子曰：『丘，殷人也。』先師所共傳，宜以孔子世為湯後。」上以其語不經，〔二〕遂見寢。至成帝時，梅福復言宜封孔子後以奉湯祀。綏和元年，立二王後，推跡古文，以左氏、穀梁、世本、禮記相明，遂下詔封孔子世為殷紹嘉公。語在成紀。是時，福居家，常以讀書養性為事。","sentenceOrder":170},
  {"id":"s_work_han_thu_80_171","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「不自知其昭穆之數也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_80_172","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　師古曰：「不合於經也。」","sentenceOrder":172},
  {"id":"s_work_han_thu_80_173","chapterId":"ch_work_han_thu_80","textTraditional":"至元始中，王莽顓政，〔一〕福一朝棄妻子，去九江，至今傳以為仙。其後，人有見福於會稽者，變名姓，為吳市門卒云。〔二〕","sentenceOrder":173},
  {"id":"s_work_han_thu_80_174","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「顓讀與專同。」","sentenceOrder":174},
  {"id":"s_work_han_thu_80_175","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　師古曰：「其後謂棄妻子去之後。」","sentenceOrder":175},
  {"id":"s_work_han_thu_80_176","chapterId":"ch_work_han_thu_80","textTraditional":"云敞字幼（儒）〔孺〕，平陵人也。師事同縣吳章，章治尚書經為博士。平帝以中山王即帝位，年幼，莽秉政，自號安漢公。以平帝為成帝後，不得顧私親，帝母及外家衛氏皆留中山，不得至京師。莽長子宇，非莽鬲絕衛氏，〔一〕恐帝長大後見怨。宇與吳章謀，夜以血塗莽門，若鬼神之戒，冀以懼莽。章欲因對其咎。事發覺，莽殺宇，誅滅衛氏，謀所聯及，死者百餘人。章坐要斬，磔尸東市門。初，章為當世名儒，教授尤盛，弟子千餘人，莽以為惡人黨，皆當禁（固）〔錮〕，不得仕宦。門人盡更名他師。〔二〕敞時為大司徒掾，自劾吳章第子，收抱章尸歸，棺斂葬之，〔三〕京師稱焉。車騎將軍王舜高其志節，比之欒布，表奏以為掾，薦為中郎諫大夫。莽篡位，王舜為太師。復薦敞可輔職。〔四〕以病免。唐林言敞可典郡，擢為魯郡大尹。更始時，安車徵敞為御史大夫，復病免去，卒于家。","sentenceOrder":176},
  {"id":"s_work_han_thu_80_177","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「鬲讀與隔同。」","sentenceOrder":177},
  {"id":"s_work_han_thu_80_178","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　師古曰：「更以他人為師，諱不言是章弟子。」","sentenceOrder":178},
  {"id":"s_work_han_thu_80_179","chapterId":"ch_work_han_thu_80","textTraditional":"〔三〕　師古曰：「棺音工喚反。斂音力贍反。」","sentenceOrder":179},
  {"id":"s_work_han_thu_80_180","chapterId":"ch_work_han_thu_80","textTraditional":"〔四〕　師古曰：「為輔弼之任。」","sentenceOrder":180},
  {"id":"s_work_han_thu_80_181","chapterId":"ch_work_han_thu_80","textTraditional":"贊曰：昔仲尼稱不得中行，則思狂狷。〔一〕觀楊王孫之志，賢於秦始皇遠矣。世稱朱雲多過其實，〔故曰〕「蓋有不知而作之者，我亡是也。」〔二〕胡建臨敵敢斷，武昭於外。〔三〕斬伐姦隙，軍旅不隊。梅福之辭，合於大雅雖無老成，尚有典刑；殷監不遠，夏后所聞。〔四〕遂從所好，全性市門。云敞之義，著於吳章，為仁由己，再入大府，〔五〕清則濯纓，何遠之有？〔六〕","sentenceOrder":181},
  {"id":"s_work_han_thu_80_182","chapterId":"ch_work_han_thu_80","textTraditional":"〔一〕　師古曰：「論語載孔子曰：『不得中行而與之，必也狂狷乎！狂者進取，狷者有所不為。』中行，中庸也。狷，介也。言不必得中庸之人與之論道，則思狂狷，猶愈於頑嚚無識者也。狷音子掾反。」","sentenceOrder":182},
  {"id":"s_work_han_thu_80_183","chapterId":"ch_work_han_thu_80","textTraditional":"〔二〕　師古曰：「論語稱孔子之言也。疾時人妄有述作，非有實也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_80_184","chapterId":"ch_work_han_thu_80","textTraditional":"〔三〕　師古曰：「昭，明也。」","sentenceOrder":184},
  {"id":"s_work_han_thu_80_185","chapterId":"ch_work_han_thu_80","textTraditional":"〔四〕　師古曰：「大雅蕩之詩曰『雖無老成人，尚有典刑』，言今雖無其人，尚有故法可案用也。又曰『殷監不遠，在夏后之時』，言殷視夏桀之亡，可為戒也。贊引此者，謂梅福請封孔子後，是案武王克商之法而行之。又視秦滅二周，夷六國，不為立後，自取喪亡，可為戒也。」","sentenceOrder":185},
  {"id":"s_work_han_thu_80_186","chapterId":"ch_work_han_thu_80","textTraditional":"〔五〕　師古曰：「論語稱孔子曰：『為仁由己，而由人乎哉！』此贊引之。再入大府，謂初為大司徒掾，後為車騎將軍掾也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_80_187","chapterId":"ch_work_han_thu_80","textTraditional":"〔六〕　師古曰：「楚辭漁父之歌曰：『滄浪之水清，可以濯我纓；滄浪之水濁，可以濯我足。』遇治則仕，遇亂則隱，云敞謝病去職，近於此義也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_80_188","chapterId":"ch_work_han_thu_80","textTraditional":"校勘記","sentenceOrder":188},
  {"id":"s_work_han_thu_80_189","chapterId":"ch_work_han_thu_80","textTraditional":"二九０七頁　五行　欲從（其）〔之〕，心又不忍。　錢大昭說閩本「其」作「之」。按景祐、殿本都作「之」。","sentenceOrder":189},
  {"id":"s_work_han_thu_80_190","chapterId":"ch_work_han_thu_80","textTraditional":"二九０八頁　二行　竊（閒）〔聞〕王孫先令臝葬，　景祐、汲古、殿、局本都作「聞」，此誤。","sentenceOrder":190},
  {"id":"s_work_han_thu_80_191","chapterId":"ch_work_han_thu_80","textTraditional":"二九０八頁　五行　言（求）〔來〕見也。　景祐、殿本都作「來」。王先謙說作「來」是。","sentenceOrder":191},
  {"id":"s_work_han_thu_80_192","chapterId":"ch_work_han_thu_80","textTraditional":"二九一０頁　四行　因上堂〔皇〕，　錢大昭說「堂」下脫「皇」字。按殿本有。","sentenceOrder":192},
  {"id":"s_work_han_thu_80_193","chapterId":"ch_work_han_thu_80","textTraditional":"二九一一頁　一行　宿衛（官）〔宮〕外士稱為區士也。　景祐、殿本都作「宮」。王先謙說作「宮」是。","sentenceOrder":193},
  {"id":"s_work_han_thu_80_194","chapterId":"ch_work_han_thu_80","textTraditional":"二九一一頁一七行　外人（矯）〔驕〕恣，　景祐、殿本都作「驕」。","sentenceOrder":194},
  {"id":"s_work_han_thu_80_195","chapterId":"ch_work_han_thu_80","textTraditional":"二九一二頁　八行　報，論也。斷獄（也）為報。故言有故也。不窮審，〔不〕窮盡其事也。　景祐、殿、局本都無「也」字。殿、局本都有「不」字。王先謙說無「也」字有「不」字是。","sentenceOrder":195},
  {"id":"s_work_han_thu_80_196","chapterId":"ch_work_han_thu_80","textTraditional":"二九一三頁　四行　欲以匹夫徒（走）〔步〕之人而超九卿之右，　景祐、殿本都作「步」。","sentenceOrder":196},
  {"id":"s_work_han_thu_80_197","chapterId":"ch_work_han_thu_80","textTraditional":"二九一三頁　七行　而嘉（〈暂缺F51A〉）〔猥〕稱雲，　景祐、殿、局本都作「猥」。注同。","sentenceOrder":197},
  {"id":"s_work_han_thu_80_198","chapterId":"ch_work_han_thu_80","textTraditional":"二九一三頁一一行　柄臣，執權之（官）〔臣〕。　景祐、殿本都作「臣」。","sentenceOrder":198},
  {"id":"s_work_han_thu_80_199","chapterId":"ch_work_han_thu_80","textTraditional":"二九一八頁　五行　孝（文）〔武〕皇帝好忠諫，　景祐、殿、局本都作「武」。王先謙說作「武」是。","sentenceOrder":199},
  {"id":"s_work_han_thu_80_200","chapterId":"ch_work_han_thu_80","textTraditional":"二九一八頁　七行　故淮南（安王）〔王安〕緣間而起，　景祐、殿、局本都作「王安」。","sentenceOrder":200},
  {"id":"s_work_han_thu_80_201","chapterId":"ch_work_han_thu_80","textTraditional":"二九二０頁一二行　（亡）〔有〕益於時，不顧逆順，此所謂伯道者也。　王念孫說，「亡」當為「有」，蓋涉後文「亡益於時，有遺於世」而誤。","sentenceOrder":201},
  {"id":"s_work_han_thu_80_202","chapterId":"ch_work_han_thu_80","textTraditional":"二九二五頁一六行　於孔子為（祀）〔祖〕列，　景祐、殿本都作「祖」。王先謙說作「祖」是。","sentenceOrder":202},
  {"id":"s_work_han_thu_80_203","chapterId":"ch_work_han_thu_80","textTraditional":"二九二六頁　五行　示天〔下〕不敢臣。　景祐、殿本都有「下」字。王先謙說有「下」字是。","sentenceOrder":203},
  {"id":"s_work_han_thu_80_204","chapterId":"ch_work_han_thu_80","textTraditional":"二九二六頁一０行　〔初〕，武帝時，　錢大昭說，「武帝」上閩本有「初」字。按殿本有，景祐本無。","sentenceOrder":204},
  {"id":"s_work_han_thu_80_205","chapterId":"ch_work_han_thu_80","textTraditional":"二九二七頁　九行　云敞字幼（儒）〔孺〕，　景祐、殿本都作「孺」。王先謙說作「孺」是。","sentenceOrder":205},
  {"id":"s_work_han_thu_80_206","chapterId":"ch_work_han_thu_80","textTraditional":"二九二七頁一四行　皆當禁（固）〔錮〕，　景祐、殿本都作「錮」。","sentenceOrder":206},
  {"id":"s_work_han_thu_80_207","chapterId":"ch_work_han_thu_80","textTraditional":"二九二八頁　九行　〔故曰〕　二字據景祐、殿本補。","sentenceOrder":207},
  {"id":"s_work_han_thu_81_1","chapterId":"ch_work_han_thu_81","textTraditional":"霍光字子孟，票騎將軍去病弟也。　父中孺，河東平陽人也〔一〕，以縣吏給事平陽侯家，〔二〕與侍者衛少兒私通而生去病。中孺吏畢歸家，娶婦生光，因絕不相聞。久之，少兒女弟子夫得幸於武帝，立為皇后，去病以皇后姊子貴幸。既壯大，乃自知父為霍中孺，未及求問。會為票騎將軍擊匈奴，道出河東，何東太守郊迎，負弩矢先驅，〔三〕至平陽傳舍，遣吏迎霍中孺。中孺趨入拜謁，將軍迎拜，因跪曰：「去病不早自知為大人遺體也。」中孺扶服叩頭，〔四〕曰：「老臣得託命將軍，此天力也。」去病大為中孺買田宅奴婢而去。還，復過焉，乃將光西至長安，時年十餘歲，任光為郎，稍遷諸曹侍中。去病死後，光為奉（常）〔車〕都尉光祿大夫，出則奉車，入侍左右，出入禁闥二十餘年，〔五〕小心謹慎，未嘗有過，甚見親信。","sentenceOrder":1},
  {"id":"s_work_han_thu_81_2","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「中讀曰仲。」","sentenceOrder":2},
  {"id":"s_work_han_thu_81_3","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「縣遣吏於侯家供事也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_81_4","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「郊迎，迎於郊界之上也。先驅者，導其路也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_81_5","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「服音蒲北反。」","sentenceOrder":5},
  {"id":"s_work_han_thu_81_6","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　師古曰：「宮中小門謂之闥。」","sentenceOrder":6},
  {"id":"s_work_han_thu_81_7","chapterId":"ch_work_han_thu_81","textTraditional":"征和二年，衛太子為江充所敗，而燕王旦、廣陵王胥皆多過失。是時上年老，寵姬鉤弋趙婕妤有男，〔一〕上心欲以為嗣，命大臣輔之。察群臣唯光任大重，可屬社稷。〔二〕上乃使黃門畫者畫周公負成王朝諸侯以賜光。〔三〕後元二年春，上游五柞宮，病篤，光涕泣問曰：「如有不諱，誰當嗣者？」〔四〕上曰：「君未諭前畫意邪？〔五〕立少子，君行周公之事。」光頓首讓曰：「臣不如金日磾。」日磾亦曰：「臣外國人，不如光。」上以光為大司馬大將軍，日磾為車騎將軍，及太僕上官桀為左將軍，搜粟都尉桑弘羊為御史大夫，皆拜臥內床下，〔六〕受遺詔輔少主。明日，武帝崩，太子襲尊號，是為孝昭皇帝。帝年八歲，政事壹決於光。","sentenceOrder":7},
  {"id":"s_work_han_thu_81_8","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「婕妤居鉤弋宮，故稱之。」","sentenceOrder":8},
  {"id":"s_work_han_thu_81_9","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「任，堪也。屬，委也。任音壬。屬音之欲反。」","sentenceOrder":9},
  {"id":"s_work_han_thu_81_10","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「黃門之署，職任親近，以供天子，百物在焉，故亦有畫工。」","sentenceOrder":10},
  {"id":"s_work_han_thu_81_11","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「不諱，言不可諱也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_81_12","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　師古曰：「諭，曉也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_81_13","chapterId":"ch_work_han_thu_81","textTraditional":"〔六〕　師古曰：「於天子所臥床前拜職。」","sentenceOrder":13},
  {"id":"s_work_han_thu_81_14","chapterId":"ch_work_han_thu_81","textTraditional":"先是，後元年，侍中僕射莽何羅與弟重合侯通謀為逆，〔一〕時光與金日磾、上官桀等共誅之，功未錄。武帝病，封璽書曰：「帝崩發書以從事。」遺詔封金日磾為秺侯，上官桀為安陽侯，光為博陸侯，〔二〕皆以前捕反者功封。時衛尉王莽子男忽侍中，〔三〕揚語曰：〔四〕「帝（病）〔崩〕，忽常在左右，安得遺詔封三子事！〔五〕群兒自相貴耳。」光聞之，切讓王莽，〔六〕莽酖殺忽。","sentenceOrder":14},
  {"id":"s_work_han_thu_81_15","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「莽音莫戶反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_81_16","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　文穎曰：「博，大。陸，平。取其嘉名，無此縣也，食邑北海、河〔間〕、東（城）〔郡〕。」師古曰：「蓋亦取鄉聚之名以為國號，非必縣也，公孫弘平津鄉則是矣。」","sentenceOrder":16},
  {"id":"s_work_han_thu_81_17","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「即右將軍王莽也。其子名忽。」","sentenceOrder":17},
  {"id":"s_work_han_thu_81_18","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「揚謂宣唱之。」","sentenceOrder":18},
  {"id":"s_work_han_thu_81_19","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　師古曰：「安猶焉。」","sentenceOrder":19},
  {"id":"s_work_han_thu_81_20","chapterId":"ch_work_han_thu_81","textTraditional":"〔六〕　師古曰：「切，深也。讓，責也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_81_21","chapterId":"ch_work_han_thu_81","textTraditional":"光為人沈靜詳審，長財七尺三寸，〔一〕白皙，疏眉目，美須敘。〔二〕每出入下殿門，止進有常處，郎僕射竊識視之，不失尺寸，〔三〕其資性端正如此。初輔幼主，政自己出，〔四〕天下想聞其風采。〔五〕殿中嘗有怪，一夜群臣相驚，光召尚符璽郎，〔六〕郎不肯授光。光欲奪之，郎按劍曰：「臣頭可得，璽不可得也！」光甚誼之。明日，詔增此郎秩二等。眾庶莫不多光。〔七〕","sentenceOrder":21},
  {"id":"s_work_han_thu_81_22","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「財與纔同。」","sentenceOrder":22},
  {"id":"s_work_han_thu_81_23","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「皙，潔白也。敘，頰毛也。皙音先歷反。敘音人占反。」","sentenceOrder":23},
  {"id":"s_work_han_thu_81_24","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「識，記也，音式志反。」","sentenceOrder":24},
  {"id":"s_work_han_thu_81_25","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「自，從也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_81_26","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　師古曰：「采，文采。」","sentenceOrder":26},
  {"id":"s_work_han_thu_81_27","chapterId":"ch_work_han_thu_81","textTraditional":"〔六〕　師古曰：「恐有變難，故欲收（其）〔取〕璽。」","sentenceOrder":27},
  {"id":"s_work_han_thu_81_28","chapterId":"ch_work_han_thu_81","textTraditional":"〔七〕　師古曰：「多猶重也。以此事為多足重也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_81_29","chapterId":"ch_work_han_thu_81","textTraditional":"光與左將軍桀結婚相親，光長女為桀子安妻。有女年與帝相配，〔一〕桀因帝姊鄂邑蓋主內安女後宮為婕妤，〔二〕數月立為皇后。父安為票騎將軍，封桑樂侯。光時休沐出，桀輒入代光決事。桀父子既尊盛，而德長公主。〔三〕公主內行不修，近幸河間丁外人。桀、安欲為外人求封，幸依國家故事以列侯尚公主者，光不許。又為外人求光祿大夫，欲令得召見，又不許。長主大以是怨光。而桀、安數為外人求官爵弗能得，亦慚。自先帝時，桀已為九卿，位在光右。〔四〕及父子並為將軍，有椒房中宮之重，〔五〕皇后親安女，光乃其外祖，而顧專制朝事，〔六〕繇是與光爭權。〔七〕","sentenceOrder":29},
  {"id":"s_work_han_thu_81_30","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　晉灼曰：「漢語光嫡妻東閭氏生安夫人，昭后之母也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_81_31","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「鄂邑，所食邑，為蓋侯所尚，故云蓋主也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_81_32","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「懷其恩德也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_81_33","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「右，上也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_81_34","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　師古曰：「椒房殿，皇后所居。」","sentenceOrder":34},
  {"id":"s_work_han_thu_81_35","chapterId":"ch_work_han_thu_81","textTraditional":"〔六〕　師古曰：「顧猶反也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_81_36","chapterId":"ch_work_han_thu_81","textTraditional":"〔七〕　師古曰：「繇讀與由同。」","sentenceOrder":36},
  {"id":"s_work_han_thu_81_37","chapterId":"ch_work_han_thu_81","textTraditional":"燕王旦自以昭帝兄，常懷怨望。及御史大夫桑弘羊建造酒榷鹽鐵，為國興利，伐其功，〔一〕欲為子弟得官，亦怨恨光。於是蓋主、上官桀、安及弘羊皆與燕王旦通謀，詐令人為燕王上書，言「光出都肄郎羽林，道上稱〈走畢〉，〔二〕太官先置。〔三〕又引蘇武前使匈奴，拘留二十年不降，還乃為典屬國，而大將軍長史敞亡功為搜粟都尉。〔四〕又擅調益莫府校尉。〔五〕光專權自恣，疑有非常。臣旦願歸符璽，入宿衛，察姦臣變。」候司光出沐日奏之。桀欲從中下其事，〔六〕桑弘羊當與諸大臣共執退光。書奏，帝不肯下。","sentenceOrder":37},
  {"id":"s_work_han_thu_81_38","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「伐，矜也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_81_39","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　孟康曰：「都，試也。肄，習也。」師古曰：「謂總閱試習武備也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_81_40","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「供飲食之具。」","sentenceOrder":40},
  {"id":"s_work_han_thu_81_41","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「楊敞也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_81_42","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　師古曰：「調，選也。莫府，大將軍府也。調音徒釣反。」","sentenceOrder":42},
  {"id":"s_work_han_thu_81_43","chapterId":"ch_work_han_thu_81","textTraditional":"〔六〕　師古曰：「下謂下有司也，音胡稼反。」","sentenceOrder":43},
  {"id":"s_work_han_thu_81_44","chapterId":"ch_work_han_thu_81","textTraditional":"明旦，光聞之，止畫室中不入。〔一〕上問「大將軍安在？」左將軍桀對曰：「以燕王告其罪，故不敢入。」有詔召大將軍。光入，免冠頓首謝，上曰：「將軍冠。〔二〕朕知是書詐也，將軍亡罪。」光曰：「陛下何以知之？」上曰：「將軍之廣明，都郎屬耳。〔三〕調校尉以來未能十日，燕王何以得知之？且將軍為非，不須校尉。」〔四〕是時帝年十四，尚書左右皆驚，而上書者果亡，捕之甚急。桀等懼，白上小事不足遂，〔五〕上不聽。","sentenceOrder":44},
  {"id":"s_work_han_thu_81_45","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　如淳曰：「近臣所止計畫之室也，或曰彫畫之室。」師古曰：「彫畫是也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_81_46","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「令復著冠也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_81_47","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「之，往也。廣明，亭名也。屬耳，近耳也。屬音之欲反。」","sentenceOrder":47},
  {"id":"s_work_han_thu_81_48","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　文穎曰：「帝云將軍欲反，不由一校尉。」","sentenceOrder":48},
  {"id":"s_work_han_thu_81_49","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　師古曰：「遂猶竟也。不須窮竟也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_81_50","chapterId":"ch_work_han_thu_81","textTraditional":"後桀黨與有譖光者，上輒怒曰：「大將軍忠臣，先帝所屬以輔朕身，〔一〕敢有毀者坐之。」自是桀等不敢復言，乃謀令長公主置酒請光，伏兵格殺之，因廢帝，迎立燕王為天子。事發覺，光盡誅桀、安、弘羊、外人宗族。燕王、蓋主皆自殺。光威震海內。昭帝既冠，遂委任光，訖十三年，百姓充實，四夷賓服。","sentenceOrder":50},
  {"id":"s_work_han_thu_81_51","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「屬，委也，音之欲反。其下亦同。」","sentenceOrder":51},
  {"id":"s_work_han_thu_81_52","chapterId":"ch_work_han_thu_81","textTraditional":"元平元年，昭帝崩，亡嗣。武帝六男獨有廣陵王胥在，群臣議所立，咸持廣陵王。王本以行失道，先帝所不用。光內不自安。郎有上書言「周太王廢太伯立王季，文王舍伯邑考立武王，唯在所宜，〔一〕雖廢長立少可也。廣陵王不可以承宗廟。」言合光意。光以其書視丞相敞等，〔二〕擢郎為九江太守，即日承皇太后詔，遣行大鴻臚事少府樂成、宗正德、光祿大夫吉、中郎將利漢迎昌邑王賀。","sentenceOrder":52},
  {"id":"s_work_han_thu_81_53","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「太伯者，王季之兄。伯邑考，文王長子也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_81_54","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「視讀曰示。敞即楊敞也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_81_55","chapterId":"ch_work_han_thu_81","textTraditional":"賀者，武帝孫，昌邑哀王子也。既至，即位，行淫亂。光憂懣，〔一〕獨以問所親故吏大司農田延年。延年曰：「將軍為國柱石〔二〕，審此人不可，何不建白太后，〔三〕更選賢而立之？」光曰：「今欲如是，於古嘗有此否？」〔四〕延年曰：「伊尹相殷，廢太甲以安宗廟，後世稱其忠。〔五〕將軍若能行此，亦漢之伊尹也。」光乃引延年給事中，陰與車騎將軍張安世圖計，〔六〕遂召丞相、御史、將軍、列侯、中二千石、大夫、博士會議未央宮。光曰：「昌邑王行昏亂，恐危社稷，如何？」群臣皆驚鄂失色，〔七〕莫敢發言，但唯唯而已。田延年前，離席按劍，曰：「先帝屬將軍以幼孤，寄將軍以天下，以將軍忠賢能安劉氏也。今群下鼎沸，社稷將傾，且漢之傳諡常為孝者，以長有天下，令宗廟血食也。如令漢家絕祀，〔八〕將軍雖死，何面目見先帝於地下乎？今日之議，不得旋踵。〔九〕群臣後應者，臣請劍斬之。」光謝曰：「九卿責光是也。天下匈匈不安，光當受難。」〔一０〕於是議者皆叩頭，曰：「萬姓之命在於將軍，唯大將軍令。」〔一一〕","sentenceOrder":55},
  {"id":"s_work_han_thu_81_56","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「懣音滿，又音悶。」","sentenceOrder":56},
  {"id":"s_work_han_thu_81_57","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「柱者，梁下之柱；石者，承柱之礎也。言大臣負國重任，如屋之柱及其石也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_81_58","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「立議而白之。」","sentenceOrder":58},
  {"id":"s_work_han_thu_81_59","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「光不涉學，故有此問也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_81_60","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　師古曰：「商書太甲篇曰『太甲既立，弗明，伊尹放諸桐』是也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_81_61","chapterId":"ch_work_han_thu_81","textTraditional":"〔六〕　師古曰：「圖，謀也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_81_62","chapterId":"ch_work_han_thu_81","textTraditional":"〔七〕　師古曰：「凡言鄂者，皆謂阻礙不依順也，後字作愕，其義亦同。」","sentenceOrder":62},
  {"id":"s_work_han_thu_81_63","chapterId":"ch_work_han_thu_81","textTraditional":"〔八〕　師古曰：「如，若也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_81_64","chapterId":"ch_work_han_thu_81","textTraditional":"〔九〕　師古曰：「宜速決。」","sentenceOrder":64},
  {"id":"s_work_han_thu_81_65","chapterId":"ch_work_han_thu_81","textTraditional":"〔一０〕師古曰：「受其憂責也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_81_66","chapterId":"ch_work_han_thu_81","textTraditional":"〔一一〕師古曰：「言一聽之也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_81_67","chapterId":"ch_work_han_thu_81","textTraditional":"光即與群臣俱見白太后，具陳昌邑王不可以承宗廟狀。皇太后乃車駕幸未央承明殿，詔諸禁門毋內昌邑群臣。王入朝太后還，乘輦欲歸溫室，中黃門宦者各持門扇，王入，門閉，昌邑群臣不得入。王曰：「何為？」大將軍跪曰：「有皇太后詔，毋內昌邑群臣。」王曰：「徐之，何乃驚人如是！」光使盡驅出昌邑群臣，置金馬門外。車騎將軍安世將羽林騎收縛二百餘人，皆送廷尉詔獄。令故昭帝侍中中臣侍守王。光敕左右：「謹宿衛，卒有物故自裁，令我負天下，有殺主名。」〔一〕王尚未自知當廢，謂左右：「我故群臣從官安得罪，而大將軍盡繫之乎。」〔二〕頃之，有太后詔召王。王聞召，意恐，乃曰：「我安得罪而召我哉！」太后被珠襦，〔三〕盛服坐武帳中，侍御數百人皆持兵，期門武士陛戟，陳列殿下。〔四〕群臣以次上殿，召昌邑王伏前聽詔。光與群臣連名奏王，尚書令讀奏曰：","sentenceOrder":67},
  {"id":"s_work_han_thu_81_68","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「卒讀曰猝。物故，死也。自裁，自殺也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_81_69","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「安，焉也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_81_70","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　如淳曰：「以珠飾襦也。」晉灼曰：「貫珠以為襦，形若今革襦矣。」師古曰：「晉說是也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_81_71","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「陛戟謂執戟以衛陛下也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_81_72","chapterId":"ch_work_han_thu_81","textTraditional":"丞相臣敞、〔一〕大司馬大將軍臣光、車騎將軍臣安世〔二〕、度遼將軍臣明友、〔三〕前將軍臣增、〔四〕後將軍臣充國〔五〕、御史大夫臣誼、〔六〕宜春侯臣譚、〔七〕當塗侯臣聖、〔八〕隨桃侯臣昌樂、〔九〕杜侯臣屠耆堂、〔一０〕太僕臣延年、〔一一〕太常臣昌、〔一二〕大司農臣延年、〔一三〕宗正臣德、〔一四〕少府臣樂成、〔一五〕廷尉臣光、〔一六〕執金吾臣延壽、〔一七〕大鴻臚臣賢、〔一八〕左馮翊臣廣明、〔一九〕右扶風臣德、〔二０〕長信少府臣嘉、〔二一〕典屬國臣武、〔二二〕京輔都尉臣廣漢、〔二三〕司隸校尉臣辟兵、〔二四〕諸吏文學光祿大夫臣遷、〔二五〕臣畸、〔二六〕臣吉、〔二七〕臣賜、臣管、臣勝、臣梁、臣長幸、〔二八〕臣夏侯勝、〔二九〕太中大夫臣德、〔三０〕臣卬〔三一〕昧死言皇太后陛下：臣敞等頓首死罪。（大）〔天〕子所以永保宗廟總壹海內者，以慈孝禮誼賞罰為本。孝昭皇帝早棄天下，亡嗣，臣敞等議，禮曰「為人後者為之子也」，昌邑王宜嗣後，遣宗正、大鴻臚、光祿大夫奉節使徵昌邑王典喪。服斬縗，〔三二〕亡悲哀之心，廢禮誼，居道上不素食，〔三三〕使從官略女子載衣車，內所居傳舍。始至謁見，立為皇太子，常私買雞豚以食。受皇帝信璽、行璽大行前，〔三四〕就次發璽不封。〔三五〕從官更持節，〔三六〕引內昌邑從官騶宰官奴二百餘人，常與居禁闥內敖戲。自之符璽取節十六，〔三七〕朝暮臨，〔三八〕令從官更持節從。〔三九〕為書曰「皇帝問侍中君卿：〔四０〕使中御府令高昌奉黃金千斤，賜君卿取十妻。」大行在前殿，發樂府樂器，引內昌邑樂人，擊鼓歌吹作俳倡。〔四一〕會下還，上前殿，〔四二〕擊鐘磬，召內泰壹宗廟樂人輦道牟首，〔四三〕鼓吹歌舞，悉奏眾樂。發長安廚三太牢具祠閣室中，〔四四〕祀已，與從官飲啗。〔四五〕駕法駕，皮軒鸞旗，驅馳北宮、桂宮，弄彘鬥虎。〔四六〕召皇太后御小馬車，〔四七〕使官奴騎乘，遊戲掖庭中。與孝昭皇帝宮人蒙等淫亂，詔掖庭令敢泄言要斬。","sentenceOrder":72},
  {"id":"s_work_han_thu_81_73","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「楊敞也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_81_74","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「張子孺。」","sentenceOrder":74},
  {"id":"s_work_han_thu_81_75","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「范明友。」","sentenceOrder":75},
  {"id":"s_work_han_thu_81_76","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「韓增。」","sentenceOrder":76},
  {"id":"s_work_han_thu_81_77","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　師古曰：「趙充國。」","sentenceOrder":77},
  {"id":"s_work_han_thu_81_78","chapterId":"ch_work_han_thu_81","textTraditional":"〔六〕　師古曰：「蔡誼。」","sentenceOrder":78},
  {"id":"s_work_han_thu_81_79","chapterId":"ch_work_han_thu_81","textTraditional":"〔七〕　師古曰：「王訢子。」","sentenceOrder":79},
  {"id":"s_work_han_thu_81_80","chapterId":"ch_work_han_thu_81","textTraditional":"〔八〕　師古曰：「姓魏也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_81_81","chapterId":"ch_work_han_thu_81","textTraditional":"〔九〕　師古曰：「姓趙，故蒼梧王趙光子。」","sentenceOrder":81},
  {"id":"s_work_han_thu_81_82","chapterId":"ch_work_han_thu_81","textTraditional":"〔一０〕師古曰：「故胡人。」","sentenceOrder":82},
  {"id":"s_work_han_thu_81_83","chapterId":"ch_work_han_thu_81","textTraditional":"〔一一〕師古曰：「杜延年。」","sentenceOrder":83},
  {"id":"s_work_han_thu_81_84","chapterId":"ch_work_han_thu_81","textTraditional":"〔一二〕師古曰：「蒲侯蘇昌。」","sentenceOrder":84},
  {"id":"s_work_han_thu_81_85","chapterId":"ch_work_han_thu_81","textTraditional":"〔一三〕師古曰：「田延年。」","sentenceOrder":85},
  {"id":"s_work_han_thu_81_86","chapterId":"ch_work_han_thu_81","textTraditional":"〔一四〕師古曰：「劉向父。」","sentenceOrder":86},
  {"id":"s_work_han_thu_81_87","chapterId":"ch_work_han_thu_81","textTraditional":"〔一五〕師古曰：「姓史也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_81_88","chapterId":"ch_work_han_thu_81","textTraditional":"〔一六〕師古曰：「李光。」","sentenceOrder":88},
  {"id":"s_work_han_thu_81_89","chapterId":"ch_work_han_thu_81","textTraditional":"〔一七〕師古曰：「李延壽。」","sentenceOrder":89},
  {"id":"s_work_han_thu_81_90","chapterId":"ch_work_han_thu_81","textTraditional":"〔一八〕師古曰：「韋賢。」","sentenceOrder":90},
  {"id":"s_work_han_thu_81_91","chapterId":"ch_work_han_thu_81","textTraditional":"〔一九〕師古曰：「田廣明。」","sentenceOrder":91},
  {"id":"s_work_han_thu_81_92","chapterId":"ch_work_han_thu_81","textTraditional":"〔二０〕師古曰：「周德。」","sentenceOrder":92},
  {"id":"s_work_han_thu_81_93","chapterId":"ch_work_han_thu_81","textTraditional":"〔二一〕師古曰：「不知姓。」","sentenceOrder":93},
  {"id":"s_work_han_thu_81_94","chapterId":"ch_work_han_thu_81","textTraditional":"〔二二〕師古曰：「蘇武。」","sentenceOrder":94},
  {"id":"s_work_han_thu_81_95","chapterId":"ch_work_han_thu_81","textTraditional":"〔二三〕師古曰：「趙廣漢。」","sentenceOrder":95},
  {"id":"s_work_han_thu_81_96","chapterId":"ch_work_han_thu_81","textTraditional":"〔二四〕師古曰：「不知姓。」","sentenceOrder":96},
  {"id":"s_work_han_thu_81_97","chapterId":"ch_work_han_thu_81","textTraditional":"〔二五〕師古曰：「王遷。」","sentenceOrder":97},
  {"id":"s_work_han_thu_81_98","chapterId":"ch_work_han_thu_81","textTraditional":"〔二六〕師古曰：「宋畸。」","sentenceOrder":98},
  {"id":"s_work_han_thu_81_99","chapterId":"ch_work_han_thu_81","textTraditional":"〔二七〕師古曰：「景吉。」","sentenceOrder":99},
  {"id":"s_work_han_thu_81_100","chapterId":"ch_work_han_thu_81","textTraditional":"〔二八〕師古曰：「並不知姓也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_81_101","chapterId":"ch_work_han_thu_81","textTraditional":"〔二九〕李奇曰：「同官同名，故以姓別也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_81_102","chapterId":"ch_work_han_thu_81","textTraditional":"〔三０〕師古曰：「不知姓。」","sentenceOrder":102},
  {"id":"s_work_han_thu_81_103","chapterId":"ch_work_han_thu_81","textTraditional":"〔三一〕師古曰：「趙充國子也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_81_104","chapterId":"ch_work_han_thu_81","textTraditional":"〔三二〕師古曰：「典喪服，言為喪主也。斬縗，謂縗裳下不緶，直斬（斬）割之而已。緶音步千反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_81_105","chapterId":"ch_work_han_thu_81","textTraditional":"〔三三〕師古曰：「素食，菜食無肉也。言王在道常肉食，非居喪之制也。而鄭康成解喪服素食云『平常之食』，失之遠矣。素食，義亦見王莽傳。」","sentenceOrder":105},
  {"id":"s_work_han_thu_81_106","chapterId":"ch_work_han_thu_81","textTraditional":"〔三四〕孟康曰：「漢初有三璽，天子之璽自佩，行璽、信璽在符節臺。大行前，昭帝柩前也。」韋昭曰：「大行，不反之辭也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_81_107","chapterId":"ch_work_han_thu_81","textTraditional":"〔三五〕師古曰：「璽既國器，常當緘封，而王於大行前受之，退還所次，遂爾發漏，更不封之，得令凡人皆見，言不重慎也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_81_108","chapterId":"ch_work_han_thu_81","textTraditional":"〔三六〕師古曰：「更音工衡反。次下亦同。」","sentenceOrder":108},
  {"id":"s_work_han_thu_81_109","chapterId":"ch_work_han_thu_81","textTraditional":"〔三七〕師古曰：「之，往也。自往至署取節也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_81_110","chapterId":"ch_work_han_thu_81","textTraditional":"〔三八〕師古曰：「臨，哭臨也，音力禁反。」","sentenceOrder":110},
  {"id":"s_work_han_thu_81_111","chapterId":"ch_work_han_thu_81","textTraditional":"〔三九〕師古曰：「更互執節，從至哭臨之所。」","sentenceOrder":111},
  {"id":"s_work_han_thu_81_112","chapterId":"ch_work_han_thu_81","textTraditional":"〔四０〕師古曰：「昌邑之侍中名君卿也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_81_113","chapterId":"ch_work_han_thu_81","textTraditional":"〔四一〕師古曰：「俳優，諧戲也。倡，樂人也。俳音排。」","sentenceOrder":113},
  {"id":"s_work_han_thu_81_114","chapterId":"ch_work_han_thu_81","textTraditional":"〔四二〕如淳曰：「下謂柩之入冢。葬還不居喪位，便處前殿也。」師古曰：「下音胡稼反。」","sentenceOrder":114},
  {"id":"s_work_han_thu_81_115","chapterId":"ch_work_han_thu_81","textTraditional":"〔四三〕鄭氏曰：「祭泰壹神樂人也。」孟康曰：「牟首，地名也，上有觀。」如淳曰：「輦道，閣道也。牟首，屏面也。以屏面自隔，無哀戚也。」臣瓚曰：「牟首，池名也，在上林苑中。方在衰絰而輦游於池，言無哀戚也。」師古曰：「召泰壹樂人，內之於輦道牟首而鼓吹歌舞也。牟首，瓚說是也。屏面之說，失之遠矣。又左思吳都賦云『長塗牟首』，劉逵以為牟首閣道有室屋也，此說更無所出。或者思及逵據此『輦道牟首』便誤用之乎？」","sentenceOrder":115},
  {"id":"s_work_han_thu_81_116","chapterId":"ch_work_han_thu_81","textTraditional":"〔四四〕如淳曰：「黃圖北出中門有長安廚，故謂之廚城門。閣室，閣道之有室者。不知禱何淫祀也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_81_117","chapterId":"ch_work_han_thu_81","textTraditional":"〔四五〕師古曰：「啗，食也，音徒敢反。」","sentenceOrder":117},
  {"id":"s_work_han_thu_81_118","chapterId":"ch_work_han_thu_81","textTraditional":"〔四六〕師古曰：「皮軒鸞旗皆法駕所陳也。北宮、桂宮並在未央宮北。」","sentenceOrder":118},
  {"id":"s_work_han_thu_81_119","chapterId":"ch_work_han_thu_81","textTraditional":"〔四七〕張晏曰：「皇太后所駕遊宮中輦車也。漢廄有果下馬，高三尺，以駕輦。」師古曰：「小馬可於果樹下乘之，故號果下馬。」","sentenceOrder":119},
  {"id":"s_work_han_thu_81_120","chapterId":"ch_work_han_thu_81","textTraditional":"太后曰：「止！〔一〕為人臣子當悖亂如是邪！」〔二〕王離席伏。尚書令復讀曰：","sentenceOrder":120},
  {"id":"s_work_han_thu_81_121","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「令且止讀奏。」","sentenceOrder":121},
  {"id":"s_work_han_thu_81_122","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「責王也。悖，乖也，音布內反。」","sentenceOrder":122},
  {"id":"s_work_han_thu_81_123","chapterId":"ch_work_han_thu_81","textTraditional":"取諸侯王列侯二千石綬及墨綬黃綬以并佩昌邑郎官者免奴。〔一〕變易節上黃旄以赤。〔二〕發御府金錢刀劍玉器采繒，賞賜所與遊戲者。與從官官奴夜飲，湛沔於酒。〔三〕詔太官上乘輿食如故。食監奏未釋服未可御故食，〔四〕復詔太官趣具，無關食監。〔五〕太官不敢具，即使從官出買雞豚，詔殿門內，以為常。〔六〕獨夜設九賓溫室，〔七〕延見姊夫昌邑關內侯。祖宗廟祠未舉，為璽書使使者持節，以三太牢祠昌邑哀王園廟，稱嗣子皇帝。〔八〕受璽以來二十七日，使者旁午，〔九〕持節詔諸官署徵發，凡千一百二十七事。文學光祿大夫夏侯勝等及侍中傅嘉數進諫以過失，使人簿責勝〔一０〕，縛嘉繫獄。荒淫迷惑，失帝王禮誼，亂漢制度。臣敞等數進諫，不變更，〔一一〕日以益甚，恐危社稷，天下不安。","sentenceOrder":123},
  {"id":"s_work_han_thu_81_124","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「免奴謂免放為良人者。」","sentenceOrder":124},
  {"id":"s_work_han_thu_81_125","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「以劉屈氂與戾太子戰，加節上黃旄，遂以為常。賀今輒改之。」","sentenceOrder":125},
  {"id":"s_work_han_thu_81_126","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「湛讀曰沈，又讀曰耽。沈沔，荒迷也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_81_127","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「釋謂解脫也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_81_128","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　師古曰：「趣讀曰促。關，由也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_81_129","chapterId":"ch_work_han_thu_81","textTraditional":"〔六〕　師古曰：「內，入也。令每日常入雞豚也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_81_130","chapterId":"ch_work_han_thu_81","textTraditional":"〔七〕　師古曰：「於溫室中設九賓之禮也。九賓，解在叔孫通傳。」","sentenceOrder":130},
  {"id":"s_work_han_thu_81_131","chapterId":"ch_work_han_thu_81","textTraditional":"〔八〕　師古曰：「時在喪服，故未祠宗廟而私祭昌邑哀王也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_81_132","chapterId":"ch_work_han_thu_81","textTraditional":"〔九〕　如淳曰：「旁午，分布也。」師古曰：「一從一橫為旁午，猶言交橫也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_81_133","chapterId":"ch_work_han_thu_81","textTraditional":"〔一０〕師古曰：「簿音步戶反。簿責，以文簿具責之。」","sentenceOrder":133},
  {"id":"s_work_han_thu_81_134","chapterId":"ch_work_han_thu_81","textTraditional":"〔一一〕師古曰：「更，改也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_81_135","chapterId":"ch_work_han_thu_81","textTraditional":"臣敞等謹與博士臣霸、臣雋舍、〔一〕臣德、臣虞舍、臣射、臣倉議，皆曰：「高皇帝建功業為漢太祖，孝文皇帝慈仁節儉為太宗，今陛下嗣孝昭皇帝後，行淫辟不軌。〔二〕詩云：『籍曰未知，亦既抱子。』〔三〕五辟之屬，莫大不孝。〔四〕周襄王不能事母，春秋曰『天王出居于鄭』，繇不孝出之，絕之於天下也。〔五〕宗廟重於君，陛下未見命高廟，不可以承天序，奉祖宗廟，子萬姓，當廢。」臣請有司御史大夫臣誼、宗正臣德、太常臣昌與太祝以一太牢具，告祠高廟。臣敞等昧死以聞。","sentenceOrder":135},
  {"id":"s_work_han_thu_81_136","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　晉灼曰：「雋姓，舍名也。下有臣虞舍，故以姓別之。」師古曰：「雋音辭阮反，又音字阮反。」","sentenceOrder":136},
  {"id":"s_work_han_thu_81_137","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「軌，法也。辟讀曰僻。」","sentenceOrder":137},
  {"id":"s_work_han_thu_81_138","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「大雅抑之詩。衛武公刺厲王也。籍，假也。此言假令人云王尚幼少，未有所知，亦已長大而抱子矣，實不幼少也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_81_139","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「五辟即五刑也。辟音頻亦反。」","sentenceOrder":139},
  {"id":"s_work_han_thu_81_140","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　師古曰：「襄王，惠王子也。僖二十四年經書『天王出居于鄭』。公羊傳曰：『王者無外，此其言出何？不能乎母也。』繇讀與由同。」","sentenceOrder":140},
  {"id":"s_work_han_thu_81_141","chapterId":"ch_work_han_thu_81","textTraditional":"皇太后詔曰：「可。」光令王起拜受詔，王曰：「聞天子有爭臣七人，雖無道不失天下。」〔一〕光曰：「皇太后詔廢，安得天子！」乃即持其手，〔二〕解脫其璽組，奉上太后，扶王下殿，出金馬門，群臣隨送。王西面拜，曰：「愚戇不任漢事。」起就乘輿副車。大將軍光送至昌邑邸，光謝曰：「王行自絕於天，臣等駑怯，不能殺身報德。臣寧負王，不敢負社稷。願王自愛，臣長不復見左右。」〔三〕光涕泣而去。群臣奏言：「古者廢放之人屏於遠方，不及以政〔四〕，請徙王賀漢中房陵縣。」太后詔歸賀昌邑，賜湯沐邑二千戶。昌邑群臣坐亡輔導之誼，陷王於惡，光悉誅殺二百餘人。出死，號呼巿中〔五〕曰：「當斷不斷，反受其亂。」〔六〕","sentenceOrder":141},
  {"id":"s_work_han_thu_81_142","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「引孝經之言。」","sentenceOrder":142},
  {"id":"s_work_han_thu_81_143","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「即，就也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_81_144","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「言不復得侍見於左右。」","sentenceOrder":144},
  {"id":"s_work_han_thu_81_145","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「言不豫政令。」","sentenceOrder":145},
  {"id":"s_work_han_thu_81_146","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　師古曰：「呼音火故反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_81_147","chapterId":"ch_work_han_thu_81","textTraditional":"〔六〕　師古曰：「悔不早殺光等也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_81_148","chapterId":"ch_work_han_thu_81","textTraditional":"光坐庭中，會丞相以下議定所立。廣陵王已前不用，及燕剌王反誅，其子不在議中。近親唯有衛太子孫號皇曾孫在民間，咸稱述焉。光遂復與丞相敞等上奏曰：「禮曰『人道親親故尊祖，尊祖故敬宗。』（太）〔大〕宗亡嗣，擇支子孫賢者為嗣。孝武皇帝曾孫病已，武帝時有詔掖庭養視，至今年十八，師受詩、論語、孝經，躬行節儉，慈仁愛人，可以嗣孝昭皇帝後，奉承祖宗廟，子萬姓。臣昧死以聞。」皇太后詔曰：「可。」光遣宗正劉德至曾孫家尚冠里，洗沐賜御衣，太僕以軨獵車迎曾孫就齋宗正府，入未央宮見皇太后，封為陽武侯。〔一〕已而光奉上皇帝璽綬，謁于高廟，是為孝宣皇帝。明年，下詔曰：「夫褒有德，賞元功，古今通誼也。大司馬大將軍光宿衛忠正，宣德明恩，守節秉誼，以安宗廟。其以河北、東武陽益封光萬七千戶。」與故所食凡二萬戶。賞賜前後黃金七千斤，錢六千萬，雜繒三萬疋，奴婢百七十人，馬二千疋，甲第一區。","sentenceOrder":148},
  {"id":"s_work_han_thu_81_149","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「解並在宣紀。軨音零。」","sentenceOrder":149},
  {"id":"s_work_han_thu_81_150","chapterId":"ch_work_han_thu_81","textTraditional":"自昭帝時，光子禹及兄孫雲皆中郎將，雲弟山奉車都尉侍中，領胡越兵。光兩女婿為東西宮衛尉，昆弟諸婿外孫皆奉朝請，為諸曹大夫，騎都尉，給事中。黨親連體，根據於朝廷。光自後元秉持萬機，及上即位，乃歸政。上謙讓不受，諸事皆先關白光，然後奏御天子。光每朝見，上虛己斂容，禮下之已甚。〔一〕","sentenceOrder":150},
  {"id":"s_work_han_thu_81_151","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「下音胡稼反。」","sentenceOrder":151},
  {"id":"s_work_han_thu_81_152","chapterId":"ch_work_han_thu_81","textTraditional":"光秉政前後二十年，地節二年春病篤，車駕自臨問光病，上為之涕泣。光上書謝恩曰：「願分國邑三千戶，以封兄孫奉車都尉山為列侯，奉兄票騎將軍去病祀。」事下丞相御史，即日拜光子禹為右將軍。","sentenceOrder":152},
  {"id":"s_work_han_thu_81_153","chapterId":"ch_work_han_thu_81","textTraditional":"光薨，上及皇太后親臨光喪。太中大夫任宣與侍御史五人持節護喪事。中二千石治莫府冢上。〔一〕賜金錢、繒絮，繡被百領。衣五十篋，璧珠璣玉衣，〔二〕梓宮、〔三〕便房、黃腸題湊各一具〔四〕，樅木外臧槨十五具。〔五〕東園溫明，〔六〕皆如乘輿制度。載光尸柩以轀輬車，〔七〕黃屋左纛，〔八〕發材官輕車北軍五校士軍陳至茂陵，以送其葬。諡曰宣成侯。發三河卒穿復土，起冢祠堂，置園邑三百家，長丞奉守如舊法。","sentenceOrder":153},
  {"id":"s_work_han_thu_81_154","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　如淳曰：「典為冢者。」","sentenceOrder":154},
  {"id":"s_work_han_thu_81_155","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「漢儀注以玉為襦，如鎧狀連綴之，以黃金為縷，要已下玉為札，長尺，廣二寸半為甲，下至足，亦綴以黃金鏤。」","sentenceOrder":155},
  {"id":"s_work_han_thu_81_156","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　服虔曰：「棺也。」師古曰：「以梓木為之，親身之棺也。為天子制，故亦稱梓宮。」","sentenceOrder":156},
  {"id":"s_work_han_thu_81_157","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　服虔曰：「便房，藏中便坐也。」蘇林曰：「以柏木黃心致累棺外，故曰黃腸。木頭皆內向，故曰題湊。」如淳曰：「漢儀注天子陵中明中高丈二尺四寸，周二丈，內梓宮，次楩槨，柏黃腸題湊。」師古曰：「便房，小曲室也。如氏以為楩木名，非也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_81_158","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　服虔曰：「在正臧外，婢妾臧也。或曰廚廄之屬也。」蘇林曰：「樅木，柏葉松身。」師古曰：「爾雅及毛詩傳並云樅木松葉柏身，檜木乃柏葉松身耳。蘇說非也。樅音七庸反。檜音工闊反，字亦作栝。」","sentenceOrder":158},
  {"id":"s_work_han_thu_81_159","chapterId":"ch_work_han_thu_81","textTraditional":"〔六〕　服虔曰：「東園處此器，形如方漆桶，開一面，漆畫之，以鏡置其中，以懸屍上，大斂并蓋之。」師古曰：「東園，署名也，屬少府。其署主作此器也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_81_160","chapterId":"ch_work_han_thu_81","textTraditional":"〔七〕　文穎曰：「轀輬車，如今喪轜車也。」孟康曰：「如衣車有窗牖，閉之則溫，開之則涼，故名之轀輬車也。」臣瓚曰：「秦始皇道崩，祕其事，載以轀輬車，百官奏事如故，此不得是轜車類也。案杜延年奏，載霍光柩以輬車，駕大廄白虎駟，以轀車駕大廄白鹿駟為倅。」師古曰：「轀輬本安車也，可以臥息。後因載喪，飾以柳翣，故遂為喪車耳。轀者密閉，輬者旁開窗牖，各別一乘，隨事為名。後人既專以載喪，又去其一，總為藩飾，而合二名呼之耳。倅，副也，音千內反。」","sentenceOrder":160},
  {"id":"s_work_han_thu_81_161","chapterId":"ch_work_han_thu_81","textTraditional":"〔八〕　師古曰：「解在高紀也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_81_162","chapterId":"ch_work_han_thu_81","textTraditional":"既葬，封山為樂平侯，以奉車都尉領尚書事。天子思光功德，下詔曰：「故大司馬大將軍博陸侯宿衛孝武皇帝三十有餘年，輔孝昭皇帝十有餘年，遭大難，躬秉誼，率三公九卿大夫定萬世冊以安社稷，天下蒸庶咸以康寧。功德茂盛，朕甚嘉之。復其後世，疇其爵邑〔一〕，世世無有所與，功如蕭相國。」〔二〕明年夏，封太子外祖父許廣漢為平恩侯。復下詔曰：「宣成侯光宿衛忠正，勤勞國家。善善及後世，〔三〕其封光兄孫中郎將雲為冠陽侯。」","sentenceOrder":162},
  {"id":"s_work_han_thu_81_163","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　應劭曰：「疇，等也。」師古曰：「復音方目反。」","sentenceOrder":163},
  {"id":"s_work_han_thu_81_164","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「與讀曰豫。」","sentenceOrder":164},
  {"id":"s_work_han_thu_81_165","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「善善者，謂褒寵善人也。」","sentenceOrder":165},
  {"id":"s_work_han_thu_81_166","chapterId":"ch_work_han_thu_81","textTraditional":"禹既嗣為博陸侯，太夫人顯改光時所自造塋制而侈大之。〔一〕起三山闕，築神道，北臨昭靈，南出承恩，〔二〕盛飾祠室，輦閣通屬永巷，而幽良人婢妾守之。〔三〕廣治第室，作乘輿輦，加畫繡絪馮，黃金塗，〔四〕韋絮薦輪，〔五〕侍婢以五采絲輓顯，游戲第中。〔六〕初，光愛幸監奴馮子都，常與計事，及顯寡居，與子都亂。〔七〕而禹、山亦並繕治第宅，走馬馳逐平樂館。雲當朝請，數稱病私出，〔八〕多從賓客，張圍獵黃山苑中，使蒼頭奴上朝謁，〔九〕莫敢譴者。而顯及諸女，晝夜出入長信宮殿中，亡期度。〔一０〕","sentenceOrder":166},
  {"id":"s_work_han_thu_81_167","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「塋，墓域也，音營。」","sentenceOrder":167},
  {"id":"s_work_han_thu_81_168","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　服虔曰：「昭靈、承恩，皆館名也。」李奇曰：「昭靈，高祖母冢園也。」文穎曰：「承恩，宣平侯冢園也。」師古曰：「服說是也，文、李並失之。」","sentenceOrder":168},
  {"id":"s_work_han_thu_81_169","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　晉灼曰：「閣道乃通屬至永巷中也。」師古曰：「此亦其冢上作輦閣之道及永巷也，非謂掖庭之永巷也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_81_170","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　如淳曰：「絪亦茵。馮（所謂）〔謂所〕馮者也，以黃金塗飾之。」師古曰：「茵，蓐也，以繡為茵馮而黃金塗輿輦也。」","sentenceOrder":170},
  {"id":"s_work_han_thu_81_171","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　晉灼曰：「御輦以韋緣輪，著之以絮。」師古曰：「取其行安，不搖動也。著音張呂反。」","sentenceOrder":171},
  {"id":"s_work_han_thu_81_172","chapterId":"ch_work_han_thu_81","textTraditional":"〔六〕　師古曰：「輓謂牽引車輦也，音晚。」","sentenceOrder":172},
  {"id":"s_work_han_thu_81_173","chapterId":"ch_work_han_thu_81","textTraditional":"〔七〕　晉灼曰：「漢語東閭氏亡，顯以婢代立，素與馮殷姦也。」師古曰：「監奴，謂奴之監知家務者也，殷者，子都之名。」","sentenceOrder":173},
  {"id":"s_work_han_thu_81_174","chapterId":"ch_work_han_thu_81","textTraditional":"〔八〕　師古曰：「請音才姓反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_81_175","chapterId":"ch_work_han_thu_81","textTraditional":"〔九〕　文穎曰：「朝當用謁，不自行而令奴上謁者也。」師古曰：「上謁，若今參見尊貴而通名也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_81_176","chapterId":"ch_work_han_thu_81","textTraditional":"〔一０〕師古曰：「長信宮，上官太后所居。」","sentenceOrder":176},
  {"id":"s_work_han_thu_81_177","chapterId":"ch_work_han_thu_81","textTraditional":"宣帝自在民間聞知霍氏尊盛日久，內不能善。光薨，上始躬親朝政，御史大夫魏相給事中。顯謂禹、雲、山：「女曹不務奉大將軍餘業，〔一〕今大夫給事中，他人壹間，女能復自救邪？」〔二〕後兩家奴爭道，〔三〕霍氏奴入御史府，欲躢大夫門，御史為叩頭謝，乃去。人以謂霍氏，〔四〕顯等始知憂。會魏大夫為丞相，數燕見言事。平恩侯與侍中金安上等徑出入省中。時霍山自若領尚書，〔五〕上令吏民得奏封事，不關尚書，群臣進見獨往來，〔六〕於是霍氏甚惡之。","sentenceOrder":177},
  {"id":"s_work_han_thu_81_178","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「女音汝。曹，輩也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_81_179","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「間音居莧反。」","sentenceOrder":179},
  {"id":"s_work_han_thu_81_180","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「謂霍氏及御史家。」","sentenceOrder":180},
  {"id":"s_work_han_thu_81_181","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「告語也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_81_182","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　師古曰：「自若猶言如故也。」","sentenceOrder":182},
  {"id":"s_work_han_thu_81_183","chapterId":"ch_work_han_thu_81","textTraditional":"〔六〕　師古曰：「謂各各得盡言於上也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_81_184","chapterId":"ch_work_han_thu_81","textTraditional":"宣帝始立，立微時許妃為皇后。顯愛小女成君，欲貴之，私使乳醫淳于衍行毒藥殺許后，〔一〕因勸光內成君，代立為后。語在外戚傳。始許后暴崩，吏捕諸醫，劾衍侍疾亡狀不道，下獄。吏簿問急，〔二〕顯恐事敗，即具以實語光。光大驚，欲自發舉，不忍，猶與。〔三〕會奏上，因署衍勿論。〔四〕光薨後，語稍泄。於是上始聞之而未察，〔五〕乃徙光女婿度遼將軍未央衛尉平陵侯范明友為光祿勳，次婿諸吏中郎將羽林監任勝出為安定太守。數月，復出光姊婿給事中光祿大夫張朔為蜀郡太守，群孫婿中郎將王漢為武威太守。頃之，復徙光長女婿長樂衛尉鄧廣漢為少府。更以禹為大司馬，冠小冠，亡印綬，罷其右將軍屯兵官屬，特使禹官名與光俱大司馬者。〔六〕又收范明友度遼將軍印綬，但為光祿勳。及光中女婿趙平為散騎騎都尉光祿大夫將屯兵，又收平騎都尉印綬。諸領胡越騎、羽林及兩宮衛將屯兵，悉易以所親信許、史子弟代之。","sentenceOrder":184},
  {"id":"s_work_han_thu_81_185","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「乳醫，視產乳之疾者。乳音而樹反。」","sentenceOrder":185},
  {"id":"s_work_han_thu_81_186","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「簿音步戶反。」","sentenceOrder":186},
  {"id":"s_work_han_thu_81_187","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「猶與，不決也。與讀曰豫。」","sentenceOrder":187},
  {"id":"s_work_han_thu_81_188","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「署者，題其奏後也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_81_189","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　師古曰：「未知其虛實。」","sentenceOrder":189},
  {"id":"s_work_han_thu_81_190","chapterId":"ch_work_han_thu_81","textTraditional":"〔六〕　蘇林曰：「特，但也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_81_191","chapterId":"ch_work_han_thu_81","textTraditional":"禹為大司馬，稱病。禹故長史任宣候問，禹曰：「我何病？縣官非我家將軍不得至是，〔一〕今將軍墳墓未乾，盡外我家，〔二〕反任許、史，奪我印綬，令人不省死。」〔三〕宣見禹恨望深，〔四〕乃謂曰：「大將軍時何可復行！〔五〕持國權柄，殺生在手中。廷尉李种、王平、〔六〕左馮翊賈勝胡及車丞相女婿少府徐仁皆坐逆將軍（竟）〔意〕下獄死。使樂成小家子得幸將軍，至九卿封侯。〔七〕百官以下但事馮子都、王子方等，〔八〕視丞相亡如也。〔九〕各自有時，今許、史自天子骨肉，貴正宜耳。大司馬欲用是怨恨，愚以為不可。」禹默然。數日，起視事。","sentenceOrder":191},
  {"id":"s_work_han_thu_81_192","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　如淳曰：「縣官謂天子。」","sentenceOrder":192},
  {"id":"s_work_han_thu_81_193","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「外謂疏斥之。」","sentenceOrder":193},
  {"id":"s_work_han_thu_81_194","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「不自省有過也。」","sentenceOrder":194},
  {"id":"s_work_han_thu_81_195","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「望，怨也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_81_196","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　師古曰：「言今何得復如此也。」","sentenceOrder":196},
  {"id":"s_work_han_thu_81_197","chapterId":"ch_work_han_thu_81","textTraditional":"〔六〕　師古曰：「种音沖。」","sentenceOrder":197},
  {"id":"s_work_han_thu_81_198","chapterId":"ch_work_han_thu_81","textTraditional":"〔七〕　師古曰：「即上所云少府樂成者也。使者，其姓也，字或作史。」","sentenceOrder":198},
  {"id":"s_work_han_thu_81_199","chapterId":"ch_work_han_thu_81","textTraditional":"〔八〕　服虔曰：「皆光奴。」","sentenceOrder":199},
  {"id":"s_work_han_thu_81_200","chapterId":"ch_work_han_thu_81","textTraditional":"〔九〕　師古曰：「亡如猶言無所象似也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_81_201","chapterId":"ch_work_han_thu_81","textTraditional":"顯及禹、山、雲自見日侵削，數相對啼泣，自怨。山曰：「今丞相用事，縣官信之，盡變易大將軍時法令，以公田賦與貧民，發揚大將軍過失。又諸儒生多窶人子，〔一〕遠客飢寒，喜妄說狂言，〔二〕不避忌諱，大將軍常讎之，〔三〕今陛下好與諸儒生語，人人自使書對事，多言我家者。嘗有上書言大將軍時主弱臣強，專制擅權，今其子孫用事，昆弟益驕恣，恐危宗廟，災異數見，盡為是也。其言絕痛，山屏不奏其書。後上書者益黠，盡奏封事，輒（使）〔下〕中書令出取之，不關尚書，益不信人。」顯曰：「丞相數言我家，獨無罪乎？」山曰：「丞相廉正，安得罪？我家昆弟諸婿多不謹。又聞民間讙言霍氏毒殺許皇后，〔四〕寧有是邪？」顯恐急，即具以實告山、雲、禹。山、雲、禹驚曰：「如是，何不早告禹等！縣官離散斥逐諸婿，用是故也。此大事，誅罰不小，柰何？」於是始有邪謀矣。","sentenceOrder":201},
  {"id":"s_work_han_thu_81_202","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「窶，貧而無禮，音其羽反。」","sentenceOrder":202},
  {"id":"s_work_han_thu_81_203","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「喜音許吏反。」","sentenceOrder":203},
  {"id":"s_work_han_thu_81_204","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「言嫉之如仇讎也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_81_205","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「讙，眾聲也，音（計）〔許〕爰反。」","sentenceOrder":205},
  {"id":"s_work_han_thu_81_206","chapterId":"ch_work_han_thu_81","textTraditional":"初，趙平客石夏善為天官，〔一〕語平曰：「熒惑守御星，御星，太僕奉車都尉也，不黜則死。」平內憂山等。雲舅李竟所善張赦見雲家卒卒，〔二〕謂竟曰：「今丞相與平恩侯用事，可令太夫人言太后，先誅此兩人。移徙陛下，在太后耳。」長安男子張章告之，事下廷尉。執金吾捕張赦、石夏等，後有詔止勿捕。山等愈恐，相謂曰：「此縣官重太后，故不竟也。〔三〕然惡端已見，又有弒許后事，陛下雖寬仁，恐左右不聽，久之猶發，發即族矣，不如先也。」〔四〕遂令諸女各歸報其夫，皆曰：「安所相避？」〔五〕","sentenceOrder":206},
  {"id":"s_work_han_thu_81_207","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「曉星文者。」","sentenceOrder":207},
  {"id":"s_work_han_thu_81_208","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「卒讀曰猝，怱遽之貌也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_81_209","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「重，難也。竟，窮竟其事也。」","sentenceOrder":209},
  {"id":"s_work_han_thu_81_210","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「言先反。」","sentenceOrder":210},
  {"id":"s_work_han_thu_81_211","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　師古曰：「言無處相避，當受禍也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_81_212","chapterId":"ch_work_han_thu_81","textTraditional":"會李竟坐與諸侯王交通，辭語及霍氏，有詔雲、山不宜宿衛，免就第。光諸女遇太后無禮，〔一〕馮子都數犯法，上并以為讓，〔二〕山、禹等甚恐。顯夢第中井水溢流庭下，灶居樹上，又夢大將軍謂顯曰：「知捕兒不？〔三〕亟下捕之。」〔四〕第中鼠暴多，與人相觸，以尾畫地。鴞數鳴殿前樹上。〔五〕第門自壞。雲尚冠里宅中門亦壞。巷端人共見有人居雲屋上，徹瓦投地，就視，亡有，大怪之。禹夢車騎聲正讙來捕禹，舉家憂愁。山曰：「丞相擅減宗廟羔、菟、鼃，〔六〕可以此罪也。」謀令太后為博平君置酒，〔七〕召丞相、平恩侯以下，使范明友、鄧廣漢承太后制引斬之，因廢天子而立禹。約定未發，雲拜為玄菟太守，太中大夫任宣為代郡太守。山又坐寫祕書，顯為上書獻城西第，入馬千匹，以贖山罪。書報聞。〔八〕會事發覺，雲、山、明友自殺，顯、禹、廣漢等捕得。禹要斬，顯及諸女昆弟皆棄市。唯獨霍后廢處昭臺宮。與霍氏相連坐誅滅者數千家。","sentenceOrder":212},
  {"id":"s_work_han_thu_81_213","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　服虔曰：「光諸女自以（為）〔於〕上官太后為姨母，遇之無禮。」","sentenceOrder":213},
  {"id":"s_work_han_thu_81_214","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「總以此事責之也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_81_215","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「知兒見捕否？」","sentenceOrder":215},
  {"id":"s_work_han_thu_81_216","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　蘇林曰：「且疾下捕之。」師古曰：「亟音居力反。」","sentenceOrder":216},
  {"id":"s_work_han_thu_81_217","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　師古曰：「鴞，惡聲之鳥也。古者室屋高大，則通呼為殿耳，非止天子宮中。其語亦見黃霸傳。鴞音羽驕反。」","sentenceOrder":217},
  {"id":"s_work_han_thu_81_218","chapterId":"ch_work_han_thu_81","textTraditional":"〔六〕　如淳曰：「高后時定令，敢有擅議宗廟者，棄市。」師古曰：「羔、菟、鼃所以供祭也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_81_219","chapterId":"ch_work_han_thu_81","textTraditional":"〔七〕　文穎曰：「宣帝外祖母也。」","sentenceOrder":219},
  {"id":"s_work_han_thu_81_220","chapterId":"ch_work_han_thu_81","textTraditional":"〔八〕　師古曰：「不許之。」","sentenceOrder":220},
  {"id":"s_work_han_thu_81_221","chapterId":"ch_work_han_thu_81","textTraditional":"上乃下詔曰：「乃者東織室令史張赦使魏郡豪李竟報冠陽侯雲謀為大逆，〔一〕朕以大將軍故，抑而不揚，冀其自新。今大司馬博陸侯禹與母宣成侯夫人顯及從昆弟子冠陽侯雲、樂平侯山諸姊妺婿謀為大逆，欲詿誤百姓。賴（祖宗）〔宗廟〕神靈，先發得，咸伏其辜，〔二〕朕甚悼之。諸為霍氏所詿誤，事在丙申前，未發覺在吏者，皆赦除之。男子張章先發覺，以語期門董忠，忠告左曹楊惲，惲告侍中金安上。惲召見對狀，後章上書以聞。侍中史高與金安上建發其事，〔三〕言無入霍氏禁闥，卒不得遂其謀，〔四〕皆讎有功。〔五〕封章為博成侯，忠高昌侯，惲平通侯，安上都成侯，高樂陵侯。」","sentenceOrder":221},
  {"id":"s_work_han_thu_81_222","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「解在宣紀也。」","sentenceOrder":222},
  {"id":"s_work_han_thu_81_223","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「事發而捕得。」","sentenceOrder":223},
  {"id":"s_work_han_thu_81_224","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「言共立意發之也。」","sentenceOrder":224},
  {"id":"s_work_han_thu_81_225","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「遂，成也。」","sentenceOrder":225},
  {"id":"s_work_han_thu_81_226","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　晉灼曰：「讎，等也。」師古曰：「言其功相等類也。」","sentenceOrder":226},
  {"id":"s_work_han_thu_81_227","chapterId":"ch_work_han_thu_81","textTraditional":"初，霍氏奢侈，茂陵徐生曰：「霍氏必亡。夫奢則不遜，不遜必侮上。侮上者，逆道也。在人之右，眾必害之。〔一〕霍氏秉權日久，害之者多矣。天下害之，而又行以逆道，不亡何待！」乃上疏言「霍氏泰盛，陛下即愛厚之，宜以時抑制，無使至亡。」書三上，輒報聞。其後霍氏誅滅，而告霍氏者皆封。人為徐生上書曰：「臣聞客有過主人者，見其灶直突，傍有積薪，客謂主人，更為曲突，遠徙其薪，不者且有火患。主人嘿然不應。俄而家果失火，鄰里共救之，幸而得息。於是殺牛置酒，謝其鄰人，灼爛者在於上行，〔二〕餘各以功次坐，而不錄言曲突者。人謂主人曰：『鄉使聽客之言，不費牛酒，終亡火患。〔三〕今論功而請賓，曲突徙薪亡恩澤，燋頭爛額為上客耶？』主人乃寤而請之。今茂陵徐福數上書言霍氏且有變，宜防絕之。鄉使福說得行，則國亡裂土出爵之費，臣亡逆亂誅滅之敗。往事既已，而福獨不蒙其功，唯陛下察之，貴徙薪曲突之策，使居焦髮灼爛之右。」〔四〕上乃賜福帛十疋，後以為郎。","sentenceOrder":227},
  {"id":"s_work_han_thu_81_228","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「右，上也。」","sentenceOrder":228},
  {"id":"s_work_han_thu_81_229","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「灼謂被燒炙者也。行音胡（浪）〔郎〕反。」","sentenceOrder":229},
  {"id":"s_work_han_thu_81_230","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「鄉讀曰嚮。次下亦同也。」","sentenceOrder":230},
  {"id":"s_work_han_thu_81_231","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「右，上也。」","sentenceOrder":231},
  {"id":"s_work_han_thu_81_232","chapterId":"ch_work_han_thu_81","textTraditional":"宣帝始立，謁見高廟，大將軍光從驂乘，上內嚴憚之，若有芒剌在背。後車騎將軍張安世代光驂乘，天子從容肆體，甚安近焉。〔一〕及光身死而宗族竟誅，故俗傳之曰：「威震主者不畜，霍氏之禍萌於驂乘。」〔二〕","sentenceOrder":232},
  {"id":"s_work_han_thu_81_233","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「肆，放也，展也。近音鉅靳反。」","sentenceOrder":233},
  {"id":"s_work_han_thu_81_234","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「萌謂始生也。」","sentenceOrder":234},
  {"id":"s_work_han_thu_81_235","chapterId":"ch_work_han_thu_81","textTraditional":"至成帝時，為光置守冢百家，吏卒奉祠焉。元始二年，封光從父昆弟曾孫陽為博陸侯，千戶。","sentenceOrder":235},
  {"id":"s_work_han_thu_81_236","chapterId":"ch_work_han_thu_81","textTraditional":"金日磾字翁叔，〔一〕本匈奴休屠王太子也。〔二〕武帝元狩中，票騎將軍霍去病將兵擊匈奴右地，多斬首，虜獲休屠王祭天金人。其夏，票騎復西過居延，攻祁連山，大克獲。於是單于怨昆邪、休屠居西方多為漢所破，〔三〕召其王欲誅之。昆邪、休屠恐，謀降漢。休屠王後悔，昆邪王殺之，并將其眾降漢。封昆邪王為列侯。日磾以父不降見殺，與母閼氏、弟倫俱沒入官，輸黃門養馬，時年十四矣。","sentenceOrder":236},
  {"id":"s_work_han_thu_81_237","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「磾音丁奚反。」","sentenceOrder":237},
  {"id":"s_work_han_thu_81_238","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「休音許蚪反。屠音儲。」","sentenceOrder":238},
  {"id":"s_work_han_thu_81_239","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「昆音下門反。」","sentenceOrder":239},
  {"id":"s_work_han_thu_81_240","chapterId":"ch_work_han_thu_81","textTraditional":"久之，武帝游宴見馬，〔一〕後宮滿側。日磾等數十人牽馬過殿下，莫不竊視，〔二〕至日磾獨不敢。日磾長八尺二寸，容貌甚嚴，馬又肥好，上異而問之，具以本狀對。上奇焉，即日賜湯沐衣冠，拜為馬監，遷侍中駙馬都尉光祿大夫。日磾既親近，未嘗有過失，上甚信愛之，賞賜累千金，出則驂乘，入侍左右。貴戚多竊怨，曰：「陛下妄得一胡兒，反貴重之！」上聞，愈厚焉。","sentenceOrder":240},
  {"id":"s_work_han_thu_81_241","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「方於宴游之時，而召閱諸馬。」","sentenceOrder":241},
  {"id":"s_work_han_thu_81_242","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「視宮人。」","sentenceOrder":242},
  {"id":"s_work_han_thu_81_243","chapterId":"ch_work_han_thu_81","textTraditional":"日磾母教誨兩子，甚有法度，上聞而嘉之。病死，詔圖畫於甘泉宮，署曰「休屠王閼氏。」〔一〕日磾每見畫常拜，鄉之涕泣，然後乃去。〔二〕日磾子二人皆愛，為帝弄兒，常在旁側。弄兒或自後擁上項，〔三〕日磾在前，見而目之。〔四〕弄兒走且啼曰：「翁怒。」上謂日磾「何怒吾兒為？」其後弄兒壯大，不謹，自殿下與宮人戲，日磾適見之，惡其淫亂，遂殺弄兒。弄兒即日磾長子也。上聞之大怒，日磾頓首謝，具言所以殺弄兒狀。上甚哀，為之泣，已而心敬日磾。","sentenceOrder":243},
  {"id":"s_work_han_thu_81_244","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「題其畫。」","sentenceOrder":244},
  {"id":"s_work_han_thu_81_245","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":245},
  {"id":"s_work_han_thu_81_246","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「擁，抱也。」","sentenceOrder":246},
  {"id":"s_work_han_thu_81_247","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「目，視怒也。」","sentenceOrder":247},
  {"id":"s_work_han_thu_81_248","chapterId":"ch_work_han_thu_81","textTraditional":"初，莽何羅與江充相善，及充敗衛太子，何羅弟通用誅太子時力戰得封。後上知太子冤，乃夷滅充宗族黨與。何羅兄弟懼及，〔一〕遂謀為逆。日磾視其志意有非常，心疑之，陰獨察其動靜，與俱上下。〔二〕何羅亦覺日磾意，以故久不得發。是時上行幸林光宮，〔三〕日磾小疾臥廬。〔四〕何羅與通及小弟安成矯制夜出，共殺使者，發兵。明旦，上未起，何羅亡何從外入。〔五〕日磾奏廁心動，〔六〕立入坐內戶下。須臾，何羅袖白刃從東箱上，〔七〕見日磾，色變，走趨臥內欲入，〔八〕行觸寶瑟，僵。日磾得抱何羅，因傳曰：「莽何羅反！」〔九〕上驚起，左右拔刃欲格之，上恐并中日磾，〔一０〕止勿格。日磾捽胡投何羅殿下，〔一一〕得禽縛之，窮治皆伏辜。繇是著忠孝節。〔一二〕","sentenceOrder":248},
  {"id":"s_work_han_thu_81_249","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「及謂及於禍也。」","sentenceOrder":249},
  {"id":"s_work_han_thu_81_250","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「上下於殿也。」","sentenceOrder":250},
  {"id":"s_work_han_thu_81_251","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　服虔曰：「甘泉一名林光。」師古曰：「秦之林光宮，胡亥所造，漢又於其旁起甘泉宮。」","sentenceOrder":251},
  {"id":"s_work_han_thu_81_252","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「殿中所止曰廬。」","sentenceOrder":252},
  {"id":"s_work_han_thu_81_253","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　師古曰：「無何猶言無故也。」","sentenceOrder":253},
  {"id":"s_work_han_thu_81_254","chapterId":"ch_work_han_thu_81","textTraditional":"〔六〕　師古曰：「奏，向也。日磾方向廁而心動。」","sentenceOrder":254},
  {"id":"s_work_han_thu_81_255","chapterId":"ch_work_han_thu_81","textTraditional":"〔七〕　師古曰：「置刃於衣袖中也。褏，古袖字。」","sentenceOrder":255},
  {"id":"s_work_han_thu_81_256","chapterId":"ch_work_han_thu_81","textTraditional":"〔八〕　師古曰：「趨讀曰趣，嚮也。臥內，天子臥處。」","sentenceOrder":256},
  {"id":"s_work_han_thu_81_257","chapterId":"ch_work_han_thu_81","textTraditional":"〔九〕　師古曰：「傳謂傳聲而唱之。」","sentenceOrder":257},
  {"id":"s_work_han_thu_81_258","chapterId":"ch_work_han_thu_81","textTraditional":"〔一０〕師古曰：「中音竹仲反。」","sentenceOrder":258},
  {"id":"s_work_han_thu_81_259","chapterId":"ch_work_han_thu_81","textTraditional":"〔一一〕孟康曰：「胡音互。捽胡，若今相僻臥輪之類也。」晉灼曰：「胡，頸也，捽其頸而投殿下也。」師古曰：「晉說是也。捽音才乞反。」","sentenceOrder":259},
  {"id":"s_work_han_thu_81_260","chapterId":"ch_work_han_thu_81","textTraditional":"〔一二〕師古曰：「繇讀與由同。」","sentenceOrder":260},
  {"id":"s_work_han_thu_81_261","chapterId":"ch_work_han_thu_81","textTraditional":"日磾自在左右，目不忤視者數十年。〔一〕賜出宮女，不敢近。上欲內其女後宮，不肯。其篤慎如此，上尤奇異之。〔二〕及上病，屬霍光以輔少主，〔三〕光讓日磾。日磾曰：「臣外國人，且使匈奴輕漢。」於是遂為光副。光以女妻日磾嗣子賞。初，武帝遺詔以討莽何羅功封日磾為秺侯，〔四〕日磾以帝少不受封。輔政歲餘，病困，大將軍光白封日磾，臥授印綬。一日，薨，賜葬具冢地，送以輕車介士，軍陳至茂陵，諡曰敬侯。","sentenceOrder":261},
  {"id":"s_work_han_thu_81_262","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「忤，逆也。」","sentenceOrder":262},
  {"id":"s_work_han_thu_81_263","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「篤，厚也。」","sentenceOrder":263},
  {"id":"s_work_han_thu_81_264","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「屬音之欲反。」","sentenceOrder":264},
  {"id":"s_work_han_thu_81_265","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　師古曰：「秺音丁故反。」","sentenceOrder":265},
  {"id":"s_work_han_thu_81_266","chapterId":"ch_work_han_thu_81","textTraditional":"日磾兩子，賞、建，俱侍中，與昭帝略同年，共臥起。賞為奉車、建駙馬都尉。及賞嗣侯，佩兩綬，上謂霍將軍曰：「金氏兄弟兩人不可使俱兩綬邪？」霍光對曰：「賞自嗣父為侯耳。」上笑曰：「侯不在我與將軍乎？」光曰：「先帝之約，有功乃得封侯。」時年俱八九歲。宣帝即位，賞為太僕，霍氏有事萌牙，上書去妻。〔一〕上亦自哀之，獨得不坐。元帝時為光祿勳，薨，亡子，國除。元始中繼絕世，封建孫當為秺侯，奉日磾後。","sentenceOrder":266},
  {"id":"s_work_han_thu_81_267","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「萌牙者，言始有端緒，若草之始生。」","sentenceOrder":267},
  {"id":"s_work_han_thu_81_268","chapterId":"ch_work_han_thu_81","textTraditional":"初，日磾所將俱降弟倫，字少卿，為黃門郎，早卒。日磾兩子貴，及孫則衰矣，而倫後嗣遂盛，子安上始貴顯封侯。","sentenceOrder":268},
  {"id":"s_work_han_thu_81_269","chapterId":"ch_work_han_thu_81","textTraditional":"安上字子侯，少為侍中，惇篤有智，宣帝愛之。頗與發舉楚王延壽反謀，〔一〕賜爵關內侯，食邑三百戶。後霍氏反，安上傳禁門闥，無內霍氏親屬，〔二〕封為都成侯，至建章衛尉。薨，賜冢塋杜陵，諡曰敬侯。四子，常、敞、岑、（哭）〔明〕。","sentenceOrder":269},
  {"id":"s_work_han_thu_81_270","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「與讀曰豫。」","sentenceOrder":270},
  {"id":"s_work_han_thu_81_271","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「禁，止也。門闥，宮中大小之門也。傳聲而止諸門闥也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_81_272","chapterId":"ch_work_han_thu_81","textTraditional":"（今）〔岑〕、明皆為諸曹中郎將，常光祿大夫。元帝為太子時，敞為中庶子，幸有寵，帝即位，為騎都尉光祿大夫，中郎將侍中。元帝崩，故事，近臣皆隨陵為園郎，敞以世名忠孝，太后詔留侍成帝，為奉車水衡都尉，至衛尉。敞為人正直，敢犯顏色，左右憚之，唯上亦難焉。〔一〕病甚，上使使者問所欲，以弟岑為託。上召岑，拜為（郎）使主客。〔二〕敞子涉本為左曹，上拜涉為侍中，使待幸綠車載送衛尉舍。〔三〕須臾卒。敞三子，涉、參、饒。","sentenceOrder":272},
  {"id":"s_work_han_thu_81_273","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「臣下皆敬憚，唯有天子一人，亦難之。」","sentenceOrder":273},
  {"id":"s_work_han_thu_81_274","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　服虔曰：「官名，屬鴻臚，主胡客也。」","sentenceOrder":274},
  {"id":"s_work_han_thu_81_275","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　李奇曰：「輦綠車，常設以待幸也。臨敞病〔困〕，拜子為侍中，以此車送，欲敞見其榮寵也。」如淳曰：「幸綠車常置左右以待召載皇孫，今遣涉歸，以皇孫車載之，寵之也。」晉灼曰：「漢注綠車名皇孫車，太子有子乘以從。」師古曰：「如、晉二說是也。」","sentenceOrder":275},
  {"id":"s_work_han_thu_81_276","chapterId":"ch_work_han_thu_81","textTraditional":"涉明經儉節，諸儒稱之。成帝時為侍中騎都尉，領三輔胡越騎。〔一〕哀帝即位，為奉車都尉，至長信少府。而參使匈奴，匈奴中郎將，〔二〕越騎校尉，關〔內〕都尉，安定、東海太守。饒為越騎校尉。","sentenceOrder":276},
  {"id":"s_work_han_thu_81_277","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「胡越騎之在三輔者，若長水、長楊、宣曲之屬是也。」","sentenceOrder":277},
  {"id":"s_work_han_thu_81_278","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「以其出使匈奴，故拜為匈奴中郎將也。」","sentenceOrder":278},
  {"id":"s_work_han_thu_81_279","chapterId":"ch_work_han_thu_81","textTraditional":"涉兩子，湯、融，皆侍中諸曹將大夫。〔一〕而涉之從父弟欽舉明經，為太子門大夫，哀帝即位，為太中大夫給事中，欽從父弟遷為尚書令，兄弟用事。帝祖母傅太后崩，欽使護作，〔二〕職辦，擢為泰山、弘農太守，著威名。平帝即位，徵為大司馬司直、京兆尹。帝年幼，選置師友，大司徒孔光以明經高行為孔氏師，京兆尹金欽以家世忠孝為金氏友。徙光祿大夫侍中，秩中二千石，封都成侯。","sentenceOrder":279},
  {"id":"s_work_han_thu_81_280","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「將亦謂中郎將也。」","sentenceOrder":280},
  {"id":"s_work_han_thu_81_281","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「監主葬送之事也。」","sentenceOrder":281},
  {"id":"s_work_han_thu_81_282","chapterId":"ch_work_han_thu_81","textTraditional":"時王莽新誅平帝外家衛氏，召明禮少府宗伯鳳〔一〕入說為人後之誼，白令公卿、將軍、侍中、朝臣並聽，〔二〕欲以內厲平帝而外塞百姓之議。〔三〕欽與族昆弟秺侯當俱封。初，當曾祖父日磾傳子節侯賞，而欽祖父安上傳子夷侯常，皆亡子，國絕，故莽封欽、當奉其後。當母南即莽母功顯君同產弟也。當上南大行為太夫人。〔四〕欽因緣謂當：「詔書陳日磾功，亡有賞語。當名為以孫繼祖也，自當為父、祖父立廟。〔五〕賞故國君，使大夫主其祭。」〔六〕時甄邯在旁，庭叱欽，〔七〕因劾奏曰：「欽幸得以通經術，超擢侍帷幄，重蒙厚恩，封襲爵號，〔八〕知聖朝以世有為人後之誼。前遭故定陶太后背本逆天，孝哀不獲厥福，乃者呂寬、衛寶復造姦謀，至於反逆，咸伏厥辜。太皇太后懲艾悼懼，〔九〕逆天之咎，非聖誣法，大亂之殃，誠欲奉承天心，遵明聖制，專壹為後之誼，以安天下之命，數臨正殿，延見群臣，講習禮經。孫繼祖者，謂亡正統持重者也。賞見嗣日磾，後成為君，持大宗重，則禮所謂『尊祖故敬宗』，大宗不可以絕者也。欽自知與當俱拜同誼，即數揚言殿省中，教當云云。〔一０〕當即如其言，則欽亦欲為父明立廟而不入夷侯常廟矣。進退異言，頗惑眾心，亂國大綱，開禍亂原，誣祖不孝，罪莫大焉。尤非大臣所宜，大不敬。秺侯當上母南為太夫人，失禮不敬。」莽白太后，下四輔、公卿、大夫、博士、議郎，皆曰：「欽宜以時即罪。」〔一一〕謁者召欽詣詔獄，欽自殺。邯以綱紀國體，亡所阿私，忠孝尤著，益封千戶。更封長信少府涉子右曹湯為都成侯。湯受封日，不敢還歸家，以明為人後之誼。益封之後，莽復用欽弟遵，封侯，歷九卿位。","sentenceOrder":282},
  {"id":"s_work_han_thu_81_283","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　如淳曰：「宗伯，姓。」","sentenceOrder":283},
  {"id":"s_work_han_thu_81_284","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「白令皆聽之。」","sentenceOrder":284},
  {"id":"s_work_han_thu_81_285","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰；「塞，止也。」","sentenceOrder":285},
  {"id":"s_work_han_thu_81_286","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　文穎曰：「南，名也。大行，官名也。當上名狀於大行也。」鄧展曰：「當上南為太夫人，恃莽姨母故耳。為父立廟，非也。」","sentenceOrder":286},
  {"id":"s_work_han_thu_81_287","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　晉灼曰：「當是賞弟建之孫，此言自當為其父及祖父建立廟也。」","sentenceOrder":287},
  {"id":"s_work_han_thu_81_288","chapterId":"ch_work_han_thu_81","textTraditional":"〔六〕　如淳曰；「以賞故國君，使大夫掌其祭事。」臣瓚曰：「當是支庶上繼大宗，不得顧其外親也。而欽見當母南為太夫人，遂尊其（祖父）〔父祖〕以續日磾，不復為後賞，而令大夫主賞祭事。」師古曰：「瓚說是也。」","sentenceOrder":288},
  {"id":"s_work_han_thu_81_289","chapterId":"ch_work_han_thu_81","textTraditional":"〔七〕　師古曰：「於朝庭中叱之也。」","sentenceOrder":289},
  {"id":"s_work_han_thu_81_290","chapterId":"ch_work_han_thu_81","textTraditional":"〔八〕　師古曰：「重音直用反。」","sentenceOrder":290},
  {"id":"s_work_han_thu_81_291","chapterId":"ch_work_han_thu_81","textTraditional":"〔九〕　師古曰：「艾讀曰乂。乂，創也。」","sentenceOrder":291},
  {"id":"s_work_han_thu_81_292","chapterId":"ch_work_han_thu_81","textTraditional":"〔一０〕師古曰：「云云者，多言也。謂上所陳以孫繼祖也。」","sentenceOrder":292},
  {"id":"s_work_han_thu_81_293","chapterId":"ch_work_han_thu_81","textTraditional":"〔一一〕師古曰：「即，就也。」","sentenceOrder":293},
  {"id":"s_work_han_thu_81_294","chapterId":"ch_work_han_thu_81","textTraditional":"贊曰：霍光以結髮內侍，起於階闥之間，確然秉志，誼形於主。〔一〕受襁褓之託，任漢室之寄，當廟堂，擁幼君，摧燕王，仆上官，〔二〕因權制敵，以成其忠。處廢置之際，臨大節而不可奪，遂匡國家，安社稷。擁昭立宣，光為師保，雖周公、阿衡，何以加此〔三〕！然光不學亡術，闇於大理，陰妻邪謀，〔四〕立女為后，湛溺盈溢之欲，以增顛覆之禍，〔五〕死財三年，宗族誅夷，〔六〕哀哉！昔霍叔封於晉，〔七〕晉即河東，光豈其苗裔乎？金日磾夷狄亡國，羈虜漢庭，而以篤敬寤主，忠信自著，勒功上將，傳國後嗣，世名忠孝，七世內侍，何其盛也！本以休屠作金人為祭天主，故因賜姓金氏云。","sentenceOrder":294},
  {"id":"s_work_han_thu_81_295","chapterId":"ch_work_han_thu_81","textTraditional":"〔一〕　師古曰：「形，見也。」","sentenceOrder":295},
  {"id":"s_work_han_thu_81_296","chapterId":"ch_work_han_thu_81","textTraditional":"〔二〕　師古曰：「仆，頓也，音赴。」","sentenceOrder":296},
  {"id":"s_work_han_thu_81_297","chapterId":"ch_work_han_thu_81","textTraditional":"〔三〕　師古曰：「阿衡，伊尹官號也。阿，倚也。衡，平也。言天子所倚，群下取平也。」","sentenceOrder":297},
  {"id":"s_work_han_thu_81_298","chapterId":"ch_work_han_thu_81","textTraditional":"〔四〕　晉灼曰：「不揚其過也。」","sentenceOrder":298},
  {"id":"s_work_han_thu_81_299","chapterId":"ch_work_han_thu_81","textTraditional":"〔五〕　師古曰：「湛讀曰沈。」","sentenceOrder":299},
  {"id":"s_work_han_thu_81_300","chapterId":"ch_work_han_thu_81","textTraditional":"〔六〕　師古曰：「財與纔同。」","sentenceOrder":300},
  {"id":"s_work_han_thu_81_301","chapterId":"ch_work_han_thu_81","textTraditional":"〔七〕　師古曰：「霍叔，文王之子，武王之弟也。」","sentenceOrder":301},
  {"id":"s_work_han_thu_81_302","chapterId":"ch_work_han_thu_81","textTraditional":"校勘記","sentenceOrder":302},
  {"id":"s_work_han_thu_81_303","chapterId":"ch_work_han_thu_81","textTraditional":"二九三一頁　九行　光為奉（常）〔車〕都尉、　景祐、殿、局本都作「車」。","sentenceOrder":303},
  {"id":"s_work_han_thu_81_304","chapterId":"ch_work_han_thu_81","textTraditional":"二九三三頁　四行　帝（病）〔崩〕，　景祐、殿本都作「崩」。","sentenceOrder":304},
  {"id":"s_work_han_thu_81_305","chapterId":"ch_work_han_thu_81","textTraditional":"二九三三頁　七行　食邑北海、河〔間〕、東（城）〔郡〕。　齊召南說「河」下脫「間」字，「城」則「郡」之訛，見恩澤侯表。","sentenceOrder":305},
  {"id":"s_work_han_thu_81_306","chapterId":"ch_work_han_thu_81","textTraditional":"二九三四頁　七行　故欲收（其）〔取〕璽。　景祐、殿本都作「取」。","sentenceOrder":306},
  {"id":"s_work_han_thu_81_307","chapterId":"ch_work_han_thu_81","textTraditional":"二九四０頁　五行　（大）〔天〕子所以永保宗廟總壹海內者，　錢大昭說「大」當作「天」。按景祐、殿、局本都作「天」。","sentenceOrder":307},
  {"id":"s_work_han_thu_81_308","chapterId":"ch_work_han_thu_81","textTraditional":"二九四０頁　七行　遣宗正、大鴻臚、光祿大夫奉節使徵昌邑王典喪。服斬縗，〔三二〕亡悲哀之心。　錢大昭說，典喪，為喪主也，顏以「典喪服」為句，失其指矣。楊樹達說錢說是，昌邑王傳云「霍光徵王賀典喪」，其明證也。","sentenceOrder":308},
  {"id":"s_work_han_thu_81_309","chapterId":"ch_work_han_thu_81","textTraditional":"二九四二頁一六行　直斬（斬）割之而已。　景祐、殿本都不重「斬」字。","sentenceOrder":309},
  {"id":"s_work_han_thu_81_310","chapterId":"ch_work_han_thu_81","textTraditional":"二九四七頁　九行　（太）〔大〕宗亡嗣，擇支子孫賢者為嗣。　王念孫說「太宗」當為「大宗」，各本皆誤。","sentenceOrder":310},
  {"id":"s_work_han_thu_81_311","chapterId":"ch_work_han_thu_81","textTraditional":"二九五一頁　四行　馮（所謂）〔謂所〕馮者也，　景祐、殿、局本都作「謂所」，此誤倒。","sentenceOrder":311},
  {"id":"s_work_han_thu_81_312","chapterId":"ch_work_han_thu_81","textTraditional":"二九五三頁一一行　皆坐逆將軍（竟）〔意〕下獄死。　朱一新說「竟」當為「意」。按景祐、殿、局本都作「意」。","sentenceOrder":312},
  {"id":"s_work_han_thu_81_313","chapterId":"ch_work_han_thu_81","textTraditional":"二九五四頁一一行　輒（使）〔下〕中書令出取之。　景祐、殿本都作「下」。","sentenceOrder":313},
  {"id":"s_work_han_thu_81_314","chapterId":"ch_work_han_thu_81","textTraditional":"二九五五頁　三行　讙，眾聲也，音（計）〔許〕爰反。　景祐、殿、局本都作「許」，此誤。","sentenceOrder":314},
  {"id":"s_work_han_thu_81_315","chapterId":"ch_work_han_thu_81","textTraditional":"二九五六頁　九行　光諸女自以（為）〔於〕上官太后為姨母，　景祐、殿、局本都作「於」，此誤。","sentenceOrder":315},
  {"id":"s_work_han_thu_81_316","chapterId":"ch_work_han_thu_81","textTraditional":"二九五七頁　三行　賴（祖宗）〔宗廟〕神靈，　景祐、殿本都作「宗廟」。","sentenceOrder":316},
  {"id":"s_work_han_thu_81_317","chapterId":"ch_work_han_thu_81","textTraditional":"二九五八頁一０行　行音胡（浪）〔郎〕反。　景祐、殿本都作「郎」。","sentenceOrder":317},
  {"id":"s_work_han_thu_81_318","chapterId":"ch_work_han_thu_81","textTraditional":"二九六三頁　八行　四子，常、敞、岑、（哭）〔明〕。　景祐、殿、局本都作「明」，此誤。二九六三頁一一行（今）〔岑〕、明皆為諸曹中郎將，　景祐、殿、局本都作「岑」，此誤。","sentenceOrder":318},
  {"id":"s_work_han_thu_81_319","chapterId":"ch_work_han_thu_81","textTraditional":"二九六三頁一四行　上召岑，拜為（郎）使主客。　景祐、殿本都無「郎」字。","sentenceOrder":319},
  {"id":"s_work_han_thu_81_320","chapterId":"ch_work_han_thu_81","textTraditional":"二九六四頁　三行　臨敞病〔困〕，拜子為侍中，　景祐、殿本都有「困」字。王先謙說有「困」字是。","sentenceOrder":320},
  {"id":"s_work_han_thu_81_321","chapterId":"ch_work_han_thu_81","textTraditional":"二九六四頁　七行　關〔內〕都尉，　景祐、殿本都有「內」字。宋祁說當刪。","sentenceOrder":321},
  {"id":"s_work_han_thu_81_322","chapterId":"ch_work_han_thu_81","textTraditional":"二九六六頁一０行　遂尊其（祖父）〔父祖〕以續日磾，　景祐、殿本都作「父祖」。","sentenceOrder":322},
  {"id":"s_work_han_thu_82_1","chapterId":"ch_work_han_thu_82","textTraditional":"趙充國字翁孫，隴西上邽人也，〔一〕後徙金城令居。〔二〕始為騎士，以六郡良家子〔三〕善騎射補羽林。為人沈勇有大略，少好將帥之節，而學兵法，通知四夷事。〔四〕","sentenceOrder":1},
  {"id":"s_work_han_thu_82_2","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「邽音圭。」","sentenceOrder":2},
  {"id":"s_work_han_thu_82_3","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「令音零。」","sentenceOrder":3},
  {"id":"s_work_han_thu_82_4","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　服虔曰：「金城、隴西、天水、安定、北地、上郡是也。」師古曰：「隴西、天水、安定、北地、上郡、西河是也。昭帝分隴西、天水置金城。充國武帝時已為假司馬，則初以六郡良家子者非金城也。此名數正與地理志同也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_82_5","chapterId":"ch_work_han_thu_82","textTraditional":"〔四〕　師古曰：「通知者，謂明曉也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_82_6","chapterId":"ch_work_han_thu_82","textTraditional":"武帝時，以假司馬從貳師將軍擊匈奴，大為虜所圍。漢軍乏食數日，死傷者多，充國乃與壯士百餘人潰圍陷陳，貳師引兵隨之，遂得解。身被二十餘創，貳師奏狀，詔徵充國詣行在所。武帝親見視其創，嗟歎之，拜為中郎，遷車騎將軍長史。","sentenceOrder":6},
  {"id":"s_work_han_thu_82_7","chapterId":"ch_work_han_thu_82","textTraditional":"昭帝時，武都氐人反，〔一〕充國以大將軍護軍都尉將兵擊定之，遷中郎將，將屯上谷，〔二〕還為水衡都尉。擊匈奴，獲西祁王，〔三〕擢為後將軍，兼水衡如故。","sentenceOrder":7},
  {"id":"s_work_han_thu_82_8","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「氐音丁奚反。」","sentenceOrder":8},
  {"id":"s_work_han_thu_82_9","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「領兵屯於上谷也。將音子亮反。」","sentenceOrder":9},
  {"id":"s_work_han_thu_82_10","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　文穎曰：「匈奴王也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_82_11","chapterId":"ch_work_han_thu_82","textTraditional":"與大將軍霍光定冊尊立宣帝，封營平侯。本始中，為蒲類將軍征匈奴，斬虜數百級，還為後將軍、少府。匈奴大發十餘萬騎，南旁塞，至符奚廬山，〔一〕欲入為寇。亡者題除渠堂降漢言之，遣充國將四萬騎屯緣邊九郡。〔二〕單于聞之，引去。","sentenceOrder":11},
  {"id":"s_work_han_thu_82_12","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「旁，依也，音步浪反。」","sentenceOrder":12},
  {"id":"s_work_han_thu_82_13","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　文穎曰：「五原、朔方之屬也。」師古曰：「九郡者，五原、朔方、雲中、代郡、雁門、定襄、北平、上谷、漁陽也。四萬騎分屯之，而充國總統領之。」","sentenceOrder":13},
  {"id":"s_work_han_thu_82_14","chapterId":"ch_work_han_thu_82","textTraditional":"是時，光祿大夫義渠安國使行諸羌，〔一〕先零豪言願時渡湟水北，〔二〕逐民所不田處畜牧。安國以聞。充國劾安國奉使不敬。是後，羌人旁緣前言，抵冒渡湟水，〔三〕郡縣不能禁。元康三年，先零遂與諸羌種豪二百餘人解仇交質盟詛。〔四〕上聞之，以問充國，對曰：「羌人所以易制者，以其種自有豪，數相攻擊，勢不壹也。往三十餘歲，西羌反時，亦先解仇合約攻令居，〔五〕與漢相距，五六年乃定。至征和五年，先零豪封煎等通使匈奴，〔六〕匈奴使人至小月氏，〔七〕傳告諸羌曰：『漢貳師將軍眾十餘萬人降匈奴。羌人為漢事苦。〔八〕張掖、酒泉本我地，地肥美，可共擊居之。』以此觀匈奴欲與羌合，非一世也。間者匈奴困於西方，聞烏桓來保塞，恐兵復從東方起，數使使尉黎、危須諸國，設以子女貂裘，欲沮解之〔九〕。其計不合。疑匈奴更遣使至羌中，道從沙陰地，出鹽澤，過長阬，入窮水塞，南抵屬國，與先零相直。〔一０〕臣恐羌變未止此，且復結聯他種，宜及未然為之備。」〔一一〕後月餘，羌侯狼何果遣使至匈奴藉兵，〔一二〕欲擊鄯善、敦煌以絕漢道。〔一三〕充國以為「狼何，小月氏種，在陽關西南，勢不能獨造此計，疑匈奴使已至羌中，先零、罕、开乃解仇作約。〔一四〕到秋馬肥，變必起矣。宜遣使者行邊兵豫為備，敕視諸羌，毋令解仇，〔一五〕以發覺其謀。」於是兩府復白遣義渠安國行視諸羌，分別善惡。安國至，召先零諸豪三十餘人，以尤桀黠，皆斬之。〔一六〕縱兵擊其種人，斬首千餘級。於是諸降羌及歸義羌侯楊玉等恐怒，亡所信鄉，〔一七〕遂劫略小種，背畔犯塞，攻城邑，殺長吏。安國以騎都尉將騎三千屯備羌，至浩亹，〔一八〕為虜所擊，失亡車重兵器甚眾。〔一九〕安國引還，至令居，以聞。是歲，神爵元年春也。","sentenceOrder":14},
  {"id":"s_work_han_thu_82_15","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「行音下更反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_82_16","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　鄭氏曰：「零音憐。」孟康曰：「豪，帥長也。」師古曰：「湟水出金城臨羌寨外，東入河。湟水之北是漢地。湟音皇。」","sentenceOrder":16},
  {"id":"s_work_han_thu_82_17","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　師古曰：「旁，依也。抵冒，犯突而前。旁音步浪反。冒音莫北反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_82_18","chapterId":"ch_work_han_thu_82","textTraditional":"〔四〕　師古曰：「羌人無大君長，而諸種豪遞相殺伐，故每有仇讎，往來相報。今解仇交質者。自相親結，欲入漢為寇也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_82_19","chapterId":"ch_work_han_thu_82","textTraditional":"〔五〕　師古曰：「合約，共為要契也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_82_20","chapterId":"ch_work_han_thu_82","textTraditional":"〔六〕　師古曰：「煎讀曰翦。」","sentenceOrder":20},
  {"id":"s_work_han_thu_82_21","chapterId":"ch_work_han_thu_82","textTraditional":"〔七〕　師古曰：「氏音支。」","sentenceOrder":21},
  {"id":"s_work_han_thu_82_22","chapterId":"ch_work_han_thu_82","textTraditional":"〔八〕　師古曰：「事，使役。」","sentenceOrder":22},
  {"id":"s_work_han_thu_82_23","chapterId":"ch_work_han_thu_82","textTraditional":"〔九〕　師古曰：「設謂（聞）〔開〕許之也。沮，壞也。欲壞其計，令解散之。沮音才汝反。」","sentenceOrder":23},
  {"id":"s_work_han_thu_82_24","chapterId":"ch_work_han_thu_82","textTraditional":"〔一０〕師古曰：「直，當也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_82_25","chapterId":"ch_work_han_thu_82","textTraditional":"〔一一〕師古曰：「未然者，其計未成。」","sentenceOrder":25},
  {"id":"s_work_han_thu_82_26","chapterId":"ch_work_han_thu_82","textTraditional":"〔一二〕師古曰：「藉，借也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_82_27","chapterId":"ch_work_han_thu_82","textTraditional":"〔一三〕師古曰：「鄯音善。」","sentenceOrder":27},
  {"id":"s_work_han_thu_82_28","chapterId":"ch_work_han_thu_82","textTraditional":"〔一四〕蘇林曰：「罕、开在金城南。」師古曰：「罕、开，羌之別種也。此下言『遣开豪雕庫宣天子至德，罕、开之屬皆聞知明詔』，其下又云『河南大开、小开』，則罕羌、开羌姓族殊矣。开音口堅反。而地理志天水有罕开縣，蓋以此二種羌來降，處之此地，因以名縣也。而今之羌姓有罕开者，總是罕开之類，合而言之，因為姓耳。變开為井，字之訛也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_82_29","chapterId":"ch_work_han_thu_82","textTraditional":"〔一五〕師古曰：「行音下更反。視讀曰示。示，語之也。其下並同。」","sentenceOrder":29},
  {"id":"s_work_han_thu_82_30","chapterId":"ch_work_han_thu_82","textTraditional":"〔一六〕師古曰：「桀，堅也，言不順從也。黠，惡也，為惡堅也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_82_31","chapterId":"ch_work_han_thu_82","textTraditional":"〔一七〕師古曰：「恐中國汎怒，不信其心，而納嚮之。鄉讀曰嚮。」","sentenceOrder":31},
  {"id":"s_work_han_thu_82_32","chapterId":"ch_work_han_thu_82","textTraditional":"〔一八〕師古曰：「浩音誥。亹音門。水名也，解在地理志。」","sentenceOrder":32},
  {"id":"s_work_han_thu_82_33","chapterId":"ch_work_han_thu_82","textTraditional":"〔一九〕師古曰：「重音直用反。」","sentenceOrder":33},
  {"id":"s_work_han_thu_82_34","chapterId":"ch_work_han_thu_82","textTraditional":"時充國年七十餘，上老之，使御史大夫丙吉問誰可將者，充國對曰：「亡踰於老臣者矣。」上遣問焉，曰：「將軍度羌虜何如，當用幾人？」〔一〕充國曰：「百聞不如一見。兵難隃度，〔二〕臣願馳至金城，圖上方略。〔三〕然羌戎小夷，逆天背畔，滅亡不久，願陛下以屬老臣，勿以為憂。」〔四〕上笑曰：「諾。」","sentenceOrder":34},
  {"id":"s_work_han_thu_82_35","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「度，計也，音大各反。其下亦同。」","sentenceOrder":35},
  {"id":"s_work_han_thu_82_36","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　鄭氏曰：「隃，遙也，三輔言也。」師古曰：「隃讀曰遙。」","sentenceOrder":36},
  {"id":"s_work_han_thu_82_37","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　師古曰：「圖其地形，并為攻討方略，俱奏上也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_82_38","chapterId":"ch_work_han_thu_82","textTraditional":"〔四〕　師古曰：「屬，委也，音之欲反。」","sentenceOrder":38},
  {"id":"s_work_han_thu_82_39","chapterId":"ch_work_han_thu_82","textTraditional":"充國至金城，須兵滿萬騎，〔一〕欲渡河，恐為虜所遮，即夜遣三校銜枚先渡，〔二〕渡輒營陳，會明，畢，遂以次盡渡。虜數十百騎來，出入軍傍。充國曰：「吾士馬新倦，不可馳逐。此皆驍騎難制，又恐其為誘兵也。擊虜以殄滅為期，小利不足貪。」令軍勿擊。遣騎候四望陿中，亡虜。〔三〕夜引兵上至落都，〔四〕召諸校司馬，謂曰：「吾知羌虜不能為兵矣。使虜發數千人守杜四望陿中，兵豈得入哉！」〔五〕充國常以遠斥候為務，行必為戰備，止必堅營壁，尤能持重，愛士卒，先計而後戰。遂西至西部都尉府，〔六〕日饗軍士，〔七〕士皆欲為用。虜數挑戰，充國堅守。捕得生口，言羌豪相數責曰：「語汝亡反，今天子遣趙將軍來，年八九十矣，善為兵。今請欲一鬥而死，可得邪！」","sentenceOrder":39},
  {"id":"s_work_han_thu_82_40","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「須，待也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_82_41","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「銜枚者，欲其無聲，使虜不覺。」","sentenceOrder":41},
  {"id":"s_work_han_thu_82_42","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　文穎曰：「金城有三陿，在南六百里。」師古曰：「山峭而夾水曰陿。四望者，陿名也。陿音狹。」","sentenceOrder":42},
  {"id":"s_work_han_thu_82_43","chapterId":"ch_work_han_thu_82","textTraditional":"〔四〕　服虔曰：「山名也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_82_44","chapterId":"ch_work_han_thu_82","textTraditional":"〔五〕　師古曰：「杜，塞也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_82_45","chapterId":"ch_work_han_thu_82","textTraditional":"〔六〕　孟康曰：「在金城。」","sentenceOrder":45},
  {"id":"s_work_han_thu_82_46","chapterId":"ch_work_han_thu_82","textTraditional":"〔七〕　師古曰：「日饗飤也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_82_47","chapterId":"ch_work_han_thu_82","textTraditional":"充國子右曹中郎將卬，將期門佽飛、羽林孤兒、胡越騎為支兵，至令居。虜並出絕轉道，〔一〕卬以聞。有詔將八校尉與驍騎都尉、金城太守合疏捕山間虜，〔二〕通轉道津渡。","sentenceOrder":47},
  {"id":"s_work_han_thu_82_48","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「並猶俱也。轉道，運糧之道也。並讀如字，又音步朗反。」","sentenceOrder":48},
  {"id":"s_work_han_thu_82_49","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　蘇林曰：「疏，搜索也。」師古曰：「疏字本作跡，言尋跡而捕之也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_82_50","chapterId":"ch_work_han_thu_82","textTraditional":"初，罕、开豪靡當兒使弟雕庫來告都尉曰先零欲反，後數日果反。雕庫種人頗在先零中，都尉即留雕庫為質。充國以為亡罪，乃遣歸告種豪：「大兵誅有罪者，明白自別，毋取并滅。〔一〕天子告諸羌人，犯法者能相捕斬，除罪。斬大豪有罪者一人，賜錢四十萬，中豪十五萬，下豪二萬，大男三千，女子及老小千錢，又以其所捕妻子財物盡與之。」充國計欲以威信招降罕开及劫略者，解散虜謀，徼極乃擊之。〔二〕","sentenceOrder":50},
  {"id":"s_work_han_thu_82_51","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「言勿相和同，自取滅亡。」","sentenceOrder":51},
  {"id":"s_work_han_thu_82_52","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「徼，要也，要其倦極者也。徼音工堯反。」","sentenceOrder":52},
  {"id":"s_work_han_thu_82_53","chapterId":"ch_work_han_thu_82","textTraditional":"時上已發三輔、太常徒弛刑，〔一〕三河、潁川、沛郡、淮陽、汝南材官，金城、隴西、天水、安定、北地、上郡騎士、羌騎，與武威、張掖、酒泉太守各屯其郡者，合六萬人矣。酒泉太守辛武賢奏言：「郡兵皆屯備南山，北邊空虛，勢不可久。或曰至秋冬乃進兵，此虜在竟外之冊。〔二〕今虜朝夕為寇，土地寒苦，漢馬不能冬，〔三〕屯兵在武威、張掖、酒泉萬騎以上，皆多羸瘦。可益馬食，以七月上旬齎三十日糧，分兵並出張掖、酒泉合擊罕、开在鮮水上者。虜以畜產為命，今皆離散，兵即分出，雖不能盡誅，亶奪其畜產，虜其妻子，〔四〕復引兵還，冬復擊之，大兵仍出，虜必震壞。」〔五〕","sentenceOrder":53},
  {"id":"s_work_han_thu_82_54","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「弛刑謂不加鉗釱者也。弛之言解也，音式爾反。」","sentenceOrder":54},
  {"id":"s_work_han_thu_82_55","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「竟讀曰境。」","sentenceOrder":55},
  {"id":"s_work_han_thu_82_56","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　師古曰：「能讀曰耐。」","sentenceOrder":56},
  {"id":"s_work_han_thu_82_57","chapterId":"ch_work_han_thu_82","textTraditional":"〔四〕　師古曰：「亶讀曰但。」","sentenceOrder":57},
  {"id":"s_work_han_thu_82_58","chapterId":"ch_work_han_thu_82","textTraditional":"〔五〕　師古曰：「仍，頻也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_82_59","chapterId":"ch_work_han_thu_82","textTraditional":"天子下其書充國，令與校尉以下吏士知羌事者博議。充國及長史董通年以為「武賢欲輕引萬騎，分為兩道出張掖，回遠千里。〔一〕以一馬自佗負三十日食，〔二〕為米二斛四斗，麥八斛，又有衣裝兵器，難以追逐。勤勞而至，虜必商軍進退，稍引去，〔三〕逐水屮，入山林。〔四〕隨而深入，虜即據前險，守後阨，以絕糧道，必有傷危之憂，為夷狄笑，千載不可復。〔五〕而武賢以為可奪其畜產，虜其妻子，此殆空言，非至計也。〔六〕又武威縣、張掖日勒皆當北塞，有通谷水草。〔七〕臣恐匈奴與羌有謀，且欲大入，幸能要杜張掖、酒泉以絕西域，〔八〕其郡兵尤不可發。先零首為畔逆，它種劫略。〔九〕故臣愚冊，欲捐罕、开闇昧之過，隱而勿章，先行先零之誅以震動之，宜悔過反善，因赦其罪，選擇良吏知其俗者撫循和輯〔一０〕，此全師保勝安邊之冊。」天子下其書。公卿議者咸以為先零兵盛，而負罕、开之助，〔一一〕不先破罕、开，則先零未可圖也。","sentenceOrder":59},
  {"id":"s_work_han_thu_82_60","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「回謂路紆曲也，音胡悔反。」","sentenceOrder":60},
  {"id":"s_work_han_thu_82_61","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「佗音徒何反。凡以畜產載負物者皆為佗。」","sentenceOrder":61},
  {"id":"s_work_han_thu_82_62","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　師古曰：「商，計度也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_82_63","chapterId":"ch_work_han_thu_82","textTraditional":"〔四〕　師古曰：「屮，古草字。」","sentenceOrder":63},
  {"id":"s_work_han_thu_82_64","chapterId":"ch_work_han_thu_82","textTraditional":"〔五〕　師古曰：「復音扶目反。」","sentenceOrder":64},
  {"id":"s_work_han_thu_82_65","chapterId":"ch_work_han_thu_82","textTraditional":"〔六〕　師古曰：「殆，僅也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_82_66","chapterId":"ch_work_han_thu_82","textTraditional":"〔七〕　師古曰：「日勒，張掖之縣。」","sentenceOrder":66},
  {"id":"s_work_han_thu_82_67","chapterId":"ch_work_han_thu_82","textTraditional":"〔八〕　師古曰：「要，遮也。杜，塞也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_82_68","chapterId":"ch_work_han_thu_82","textTraditional":"〔九〕　師古曰：「言被劫略而反叛，非其本心。」","sentenceOrder":68},
  {"id":"s_work_han_thu_82_69","chapterId":"ch_work_han_thu_82","textTraditional":"〔一０〕師古曰：「拊，古撫字。輯與集同。」","sentenceOrder":69},
  {"id":"s_work_han_thu_82_70","chapterId":"ch_work_han_thu_82","textTraditional":"〔一一〕師古曰：「負，恃也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_82_71","chapterId":"ch_work_han_thu_82","textTraditional":"上乃拜侍中樂成侯許延壽為強弩將軍，即拜酒泉太守武賢為破羌將軍，〔一〕賜璽書嘉納其冊。以書敕讓充國曰：〔二〕","sentenceOrder":71},
  {"id":"s_work_han_thu_82_72","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「即，就也，就其郡而拜之。」","sentenceOrder":72},
  {"id":"s_work_han_thu_82_73","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「讓，責也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_82_74","chapterId":"ch_work_han_thu_82","textTraditional":"皇帝問後將軍，甚苦暴露。將軍計欲至正月乃擊罕羌，羌人當獲麥，已遠其妻子，〔一〕精兵萬人欲為酒泉、敦煌寇。邊兵少，民守保不得田作。今張掖以東粟石百餘，芻槁束數十。〔二〕轉輸並起，百姓煩擾。將軍將萬餘之眾，不早及秋共水草之利爭其畜食〔三〕，欲至冬，虜皆當畜食，〔四〕多藏匿山中依險阻，將軍士寒，手足皸瘃，〔五〕寧有利哉？將軍不念中國之費，欲以歲數而勝微〔六〕，將軍誰不樂此者！〔七〕","sentenceOrder":74},
  {"id":"s_work_han_thu_82_75","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「徙其妻子令遠居而身來為寇也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_82_76","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「皆謂直錢之數，言其貴。」","sentenceOrder":76},
  {"id":"s_work_han_thu_82_77","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　師古曰：「此畜謂畜產牛羊之屬也。食謂穀麥之屬也。一曰畜食，畜之所食，即謂草也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_82_78","chapterId":"ch_work_han_thu_82","textTraditional":"〔四〕　師古曰：「此畜讀曰蓄。蓄，聚積也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_82_79","chapterId":"ch_work_han_thu_82","textTraditional":"〔五〕　文穎曰：「皸，坼裂也。瘃，寒創也。」師古曰：「皸音軍。瘃音竹足反。」","sentenceOrder":79},
  {"id":"s_work_han_thu_82_80","chapterId":"ch_work_han_thu_82","textTraditional":"〔六〕　師古曰：「久歷年歲，乃勝小敵也。數音所具反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_82_81","chapterId":"ch_work_han_thu_82","textTraditional":"〔七〕　師古曰：「言凡為將軍者，皆樂此。」","sentenceOrder":81},
  {"id":"s_work_han_thu_82_82","chapterId":"ch_work_han_thu_82","textTraditional":"今詔破羌將軍武賢將兵六千一百人，敦煌太守快將二千人，長水校尉富昌、酒泉（侯）〔候〕奉世將婼、月氏兵四千人，〔一〕亡慮萬二千人。〔二〕齎三十日食，以七月二十二日擊罕羌，入鮮水北句廉上，〔三〕去酒泉八百里，去將軍可千二百里。將軍其引兵便道西並進，雖不相及，使虜聞東方北方兵並來，分散其心意，離其黨與，雖不能殄滅，當有瓦解者。已詔中郎將卬將胡越佽飛射士步兵二校，益將軍兵。","sentenceOrder":82},
  {"id":"s_work_han_thu_82_83","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　服虔曰：「婼音兒，羌名也。」蘇林曰：「婼音兒遮反。」師古曰：「蘇音是也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_82_84","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「亡慮，大計也，解在食貨志。」","sentenceOrder":84},
  {"id":"s_work_han_thu_82_85","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　服虔曰：「句音鉤。」師古曰：「句廉，謂水岸曲而有廉稜也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_82_86","chapterId":"ch_work_han_thu_82","textTraditional":"今五星出東方，中國大利，蠻夷大敗。〔一〕太白出高，用兵深入敢戰者吉，弗敢戰者凶。將軍急裝，因天時，誅不義，萬下必全，勿復有疑。","sentenceOrder":86},
  {"id":"s_work_han_thu_82_87","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　張晏曰：「五星所聚，其下勝。羌人在西，星在東，則為漢。」","sentenceOrder":87},
  {"id":"s_work_han_thu_82_88","chapterId":"ch_work_han_thu_82","textTraditional":"充國既得讓，以為將任兵在外，便宜有守，以安國家。〔一〕乃上書謝罪，因陳兵利害，曰：","sentenceOrder":88},
  {"id":"s_work_han_thu_82_89","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「言為將之道，受任行兵於外，雖受詔命，若有便宜，則當（國）〔固〕守以取安利也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_82_90","chapterId":"ch_work_han_thu_82","textTraditional":"臣竊見騎都尉安國前幸賜書，擇羌人可使使{罒干}，諭告以大軍當至，漢不誅罕，以解其謀。恩澤甚厚，非臣下所能及。臣獨私美陛下盛德至計亡已，故遣开豪雕庫宣天子至德，罕、开之屬皆聞知明詔。今先零羌楊玉（此羌之首帥名王）將騎四千及煎鞏騎五千，阻石山木，候便為寇，〔一〕罕羌未有所犯。今置先零，先擊罕，釋有罪，誅亡辜，〔二〕起壹難，就兩害，誠非陛下本計也。","sentenceOrder":90},
  {"id":"s_work_han_thu_82_91","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「謂依阻山之木石以自保固。」","sentenceOrder":91},
  {"id":"s_work_han_thu_82_92","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「釋，置也，放也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_82_93","chapterId":"ch_work_han_thu_82","textTraditional":"臣聞兵法「攻不足者守有餘」，又曰「善戰者致人，不致於人」。〔一〕今罕羌欲為敦煌、酒泉寇，飭兵馬，練戰士，以須其至，〔二〕坐得致敵之術，以逸擊勞，取勝之道也。今恐二郡兵少不足以守，而發之行攻，釋致虜之術而從為虜所致之道，〔三〕臣愚以為不便。先零羌虜欲為背畔，故與罕、开解仇結約，然其私心不能亡恐漢兵至而罕、开背之也。臣愚以為其計常欲先赴罕、开之急，以堅其約，先擊罕羌，先零必助之。今虜馬肥，糧食方饒，擊之恐不能傷害，適使先零得施德於罕羌，堅其約，合其黨。〔四〕虜交堅黨合，精兵二萬餘人，迫脅諸小種，附著者稍眾，莫須之屬不輕得離也。〔五〕如是，虜兵寖多，〔六〕誅之用力數倍，臣恐國家憂累繇十年數，不二三歲而已。〔七〕","sentenceOrder":93},
  {"id":"s_work_han_thu_82_94","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「皆兵法之辭也。致人，引致而取之也。致於人，為人所引也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_82_95","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「飭，整也。須，待也。飭與敕同也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_82_96","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　師古曰：「釋，廢也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_82_97","chapterId":"ch_work_han_thu_82","textTraditional":"〔四〕　師古曰：「施德，自樹恩德也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_82_98","chapterId":"ch_work_han_thu_82","textTraditional":"〔五〕　服虔曰：「莫須，小種羌名也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_82_99","chapterId":"ch_work_han_thu_82","textTraditional":"〔六〕　師古曰：「寖，漸也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_82_100","chapterId":"ch_work_han_thu_82","textTraditional":"〔七〕　師古曰：「累音力瑞反。繇與由同。」","sentenceOrder":100},
  {"id":"s_work_han_thu_82_101","chapterId":"ch_work_han_thu_82","textTraditional":"臣得蒙天子厚恩，父子俱為顯列。臣位至上卿，爵為列侯，犬馬之齒七十六，為明詔填溝壑，死骨不朽，亡所顧念。獨思惟兵利害至孰悉也，於臣之計，先誅先零已，則罕、开之屬不煩兵而服矣。先零已誅而罕、开不服，涉正月擊之，得計之理，又其時也。","sentenceOrder":101},
  {"id":"s_work_han_thu_82_102","chapterId":"ch_work_han_thu_82","textTraditional":"以今進兵，誠不見其利，唯陛下裁察。","sentenceOrder":102},
  {"id":"s_work_han_thu_82_103","chapterId":"ch_work_han_thu_82","textTraditional":"六月戊申奏，七月甲寅璽書報從充國計焉。","sentenceOrder":103},
  {"id":"s_work_han_thu_82_104","chapterId":"ch_work_han_thu_82","textTraditional":"充國引兵至先零在所。虜久屯聚，解弛，〔一〕望見大軍，棄車重，欲渡湟水，〔二〕道阨狹，充國徐行驅之。或曰逐利行遲，〔三〕充國曰：「此窮寇不可迫也。緩之則走不顧，急之則還致死。〔四〕」諸校皆曰：「善。」虜赴水溺死者數百，降及斬首五百餘人，鹵馬牛羊十萬餘頭，車四千餘兩。兵至罕地，令軍毋燔聚落芻牧田中。〔五〕罕羌聞之，喜曰：「漢果不擊我矣！」豪靡忘使人來言：「願得還復故地。」〔六〕充國以聞，未報。靡忘來自歸，充國賜飲食，遣還諭種人。護軍以下皆爭之，曰：「此反虜，不可擅遣。」充國曰：「諸君但欲便文自營，〔七〕非為公家忠計也。」〔八〕語未卒，璽書報，令靡忘以贖論。後罕竟不煩兵而下。","sentenceOrder":104},
  {"id":"s_work_han_thu_82_105","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「解讀曰懈。弛，放也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_82_106","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「重音直用反。」","sentenceOrder":106},
  {"id":"s_work_han_thu_82_107","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　師古曰：「逐利宜疾，今行太遲。」","sentenceOrder":107},
  {"id":"s_work_han_thu_82_108","chapterId":"ch_work_han_thu_82","textTraditional":"〔四〕　師古曰：「謂更迴還盡力而死戰。」","sentenceOrder":108},
  {"id":"s_work_han_thu_82_109","chapterId":"ch_work_han_thu_82","textTraditional":"〔五〕　師古曰：「不得燔燒人居及於田畝之中刈芻放牧也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_82_110","chapterId":"ch_work_han_thu_82","textTraditional":"〔六〕　服虔曰：「靡忘，羌帥名也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_82_111","chapterId":"ch_work_han_thu_82","textTraditional":"〔七〕　師古曰：「苟取文墨之便而自營衛。便音頻面反。」","sentenceOrder":111},
  {"id":"s_work_han_thu_82_112","chapterId":"ch_work_han_thu_82","textTraditional":"〔八〕　師古曰：「為音于偽反。」","sentenceOrder":112},
  {"id":"s_work_han_thu_82_113","chapterId":"ch_work_han_thu_82","textTraditional":"其秋，充國病，上賜書曰：「制詔後將軍：聞苦腳脛、寒泄〔一〕，將軍年老加疾，一朝之變不可諱，〔二〕朕甚憂之。今詔破羌將軍詣屯所，為將軍副，急因天時大利，吏士銳氣，以十二月擊先零羌。即疾劇，留屯毋行，獨遣破羌、彊弩將軍。」時羌降者萬餘人矣。充國度其必壞，欲罷騎兵屯田，以待其敝。作奏未上，會得進兵璽書，中郎將卬懼，使客諫充國曰：「誠令兵出，破軍殺將以傾國家，將軍守之可也。即利與病，又何足爭？一旦不合上意，遣繡衣來責將軍，將軍之身不能自保，〔三〕何國家之安？」充國歎曰：「是何言之不忠也！本用吾言，羌虜得至是邪？〔四〕往者舉可先行羌者，吾舉辛武賢，〔五〕丞相御史復白遣義渠安國，竟沮敗羌。〔六〕金城、湟中穀斛八錢，吾謂耿中丞，〔七〕糴二百萬斛穀，羌人不敢動矣。〔八〕耿中丞請糴百萬斛，乃得四十萬斛耳。義渠再使，且費其半。失此二冊，羌人故敢為逆。失之毫釐，差（之）〔以〕千里，是既然矣。今兵久不決，四夷卒有動搖，相因而起，〔九〕雖有知者不能善其後，羌獨足憂邪！〔一０〕吾固以死守之，明主可為忠言。」遂上屯田奏曰：","sentenceOrder":113},
  {"id":"s_work_han_thu_82_114","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「脛，膝以下骨也。寒泄，下利也。言其患足脛又苦下利。脛音下定反。泄音息列反。」","sentenceOrder":114},
  {"id":"s_work_han_thu_82_115","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「恐其死。」","sentenceOrder":115},
  {"id":"s_work_han_thu_82_116","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　師古曰：「繡衣謂御史。」","sentenceOrder":116},
  {"id":"s_work_han_thu_82_117","chapterId":"ch_work_han_thu_82","textTraditional":"〔四〕　師古曰：「言豫防之，可無今日之寇也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_82_118","chapterId":"ch_work_han_thu_82","textTraditional":"〔五〕　師古曰：「行音下更反。」","sentenceOrder":118},
  {"id":"s_work_han_thu_82_119","chapterId":"ch_work_han_thu_82","textTraditional":"〔六〕　師古曰：「沮，壞也，音才汝反。」","sentenceOrder":119},
  {"id":"s_work_han_thu_82_120","chapterId":"ch_work_han_thu_82","textTraditional":"〔七〕　服虔曰：「耿壽昌也，為司農中丞。」","sentenceOrder":120},
  {"id":"s_work_han_thu_82_121","chapterId":"ch_work_han_thu_82","textTraditional":"〔八〕　師古曰：「言豫儲糧食，可以制敵。」","sentenceOrder":121},
  {"id":"s_work_han_thu_82_122","chapterId":"ch_work_han_thu_82","textTraditional":"〔九〕　師古曰：「卒讀曰猝。」","sentenceOrder":122},
  {"id":"s_work_han_thu_82_123","chapterId":"ch_work_han_thu_82","textTraditional":"〔一０〕師古曰：「言儻如此，則所憂不獨在羌。」","sentenceOrder":123},
  {"id":"s_work_han_thu_82_124","chapterId":"ch_work_han_thu_82","textTraditional":"臣聞兵者，所以明德除害也，故舉得於外，則福生於內，不可不慎。臣所將吏士馬牛食，月用糧穀十九萬九千六百三十斛，鹽千六百九十三斛，茭藁二十五萬二百八十六石。〔一〕難久不解，繇役不息。又恐它夷卒有不虞之變，〔二〕相因並起，為明主憂，誠非素定廟勝之冊。〔三〕且羌虜易以計破，難用兵碎也，故臣愚以為擊之不便。","sentenceOrder":124},
  {"id":"s_work_han_thu_82_125","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「茭，乾芻也。槁，禾稈也。石，百二十斤。稈音工旱反。」","sentenceOrder":125},
  {"id":"s_work_han_thu_82_126","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「卒讀曰猝。」","sentenceOrder":126},
  {"id":"s_work_han_thu_82_127","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　師古曰：「廟勝，謂謀於廟堂而勝敵也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_82_128","chapterId":"ch_work_han_thu_82","textTraditional":"計度臨羌東至浩亹，〔一〕羌虜故田及公田，民所未墾，可二千頃以上，其間郵亭多壞敗者。臣前部士入山，伐材木大小六萬餘枚，皆在水次。願罷騎兵，留弛刑應募，及淮陽、汝南步兵與吏士私從者，合凡萬二百八十一人，用穀月二萬七千三百六十三斛，鹽三百八斛，分屯要害處。冰解漕下，繕鄉亭，浚溝渠，〔二〕治湟陿以西道橋七十所，令可至鮮水左右。田事出，賦人二十畝。〔三〕至四月草生，發郡騎及屬國胡騎伉健各千，倅馬什二，就草，〔四〕為田者遊兵。以充入金城郡，益積畜，省大費。〔五〕今大司農所轉穀至者，足支萬人一歲食。謹上田處及器用簿，〔六〕唯陛下裁許。","sentenceOrder":128},
  {"id":"s_work_han_thu_82_129","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「度音大各反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_82_130","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「漕下，以水運木而下也。繕，補也。浚，深治也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_82_131","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　師古曰：「田事出，謂至春人出營田也。賦謂班與之也。畮，古畝字。」","sentenceOrder":131},
  {"id":"s_work_han_thu_82_132","chapterId":"ch_work_han_thu_82","textTraditional":"〔四〕　師古曰：「倅，副也。什二者，千騎則與副馬二百匹也。伉音口浪反。」","sentenceOrder":132},
  {"id":"s_work_han_thu_82_133","chapterId":"ch_work_han_thu_82","textTraditional":"〔五〕　師古曰：「畜讀曰蓄。」","sentenceOrder":133},
  {"id":"s_work_han_thu_82_134","chapterId":"ch_work_han_thu_82","textTraditional":"〔六〕　師古曰：「簿音步戶反。」","sentenceOrder":134},
  {"id":"s_work_han_thu_82_135","chapterId":"ch_work_han_thu_82","textTraditional":"上報曰：「皇帝問後將軍，言欲罷騎兵萬人留田，即如將軍之計，虜當何時伏誅，兵當何時得決？孰計其便，復奏。」充國上狀曰：","sentenceOrder":135},
  {"id":"s_work_han_thu_82_136","chapterId":"ch_work_han_thu_82","textTraditional":"臣聞帝王之兵，以全取勝，是以貴謀而賤戰。戰而百勝，非善之善者也，故先為不可勝以待敵之可勝。〔一〕蠻夷習俗雖殊於禮義之國，然其欲避害就利，愛親戚，畏死亡，一也。今虜亡其美地薦草，〔二〕愁於寄託遠遯，骨肉離心，人有畔志，而明主般師罷兵，〔三〕萬人留田，順天時，因地利，以待可勝之虜，雖未即伏辜，兵決可期月而望。羌虜瓦解，前後降者萬七百餘人，及受言去者凡七十輩，〔四〕此坐支解羌虜之具也。","sentenceOrder":136},
  {"id":"s_work_han_thu_82_137","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「此兵法之辭也。言先自完堅，令敵不能勝我，乃可以勝敵也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_82_138","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「薦，稠草。」","sentenceOrder":138},
  {"id":"s_work_han_thu_82_139","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　鄧展曰：「般音班。班，還也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_82_140","chapterId":"ch_work_han_thu_82","textTraditional":"〔四〕　如淳曰：「羌胡言欲降，受其言遣去者。」師古曰：「如說非也。謂羌受充國之言，歸相告喻者也。羌虜即羌賊耳，無豫於胡也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_82_141","chapterId":"ch_work_han_thu_82","textTraditional":"臣謹條不出兵留田便宜十二事。步兵九校，〔一〕吏士萬人，留屯以為武備，因田致穀，威德並行，一也。又因排折羌虜，令不得歸肥饒之墬，〔二〕貧破其眾，以成羌虜相畔之漸，二也。居民得並田作，不失農業，三也。〔三〕軍馬一月之食，度支田士一歲〔四〕，罷騎兵以省大費，四也。至春省甲士卒，循河湟漕穀至臨羌，以眎羌虜，〔五〕揚威武，傳世折衝之具，五也。以閒暇時下所伐材，〔六〕繕治郵亭，充入金城，六也。兵出，乘危徼幸，〔七〕不出，令反畔之虜竄於風寒之地，離霜露疾疫瘃墯之患，〔八〕坐得必勝之道，七也。亡經阻遠追死傷之害，八也。內不損威武之重，外不令虜得乘間之勢，九也。〔九〕又亡驚動河南大开、小开〔一０〕使生它變之憂，十也。治湟陿中道橋，令可至鮮水，以制西域，信威千里，〔一一〕從枕席上過師，十一也。〔一二〕大費既省，繇役豫息，以戒不虞，十二也。留屯田得十二便，出兵失十二利。臣充國材下，犬馬齒衰，不識長冊，唯明詔博詳公卿議臣採擇。","sentenceOrder":141},
  {"id":"s_work_han_thu_82_142","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「一部為一校也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_82_143","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「墬，古地字。」","sentenceOrder":143},
  {"id":"s_work_han_thu_82_144","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　師古曰：「並，且也，讀如本字，又音步浪反。」","sentenceOrder":144},
  {"id":"s_work_han_thu_82_145","chapterId":"ch_work_han_thu_82","textTraditional":"〔四〕　師古曰：「度音大各反。」","sentenceOrder":145},
  {"id":"s_work_han_thu_82_146","chapterId":"ch_work_han_thu_82","textTraditional":"〔五〕　師古曰：「眎亦示字。」","sentenceOrder":146},
  {"id":"s_work_han_thu_82_147","chapterId":"ch_work_han_thu_82","textTraditional":"〔六〕　師古曰：「閒讀曰閑。」","sentenceOrder":147},
  {"id":"s_work_han_thu_82_148","chapterId":"ch_work_han_thu_82","textTraditional":"〔七〕　師古曰：「言不可必勝。」","sentenceOrder":148},
  {"id":"s_work_han_thu_82_149","chapterId":"ch_work_han_thu_82","textTraditional":"〔八〕　師古曰：「離，遭也。墯謂因寒瘃而墯指者也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_82_150","chapterId":"ch_work_han_thu_82","textTraditional":"〔九〕　師古曰：「間謂軍之間隙者也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_82_151","chapterId":"ch_work_han_thu_82","textTraditional":"〔一０〕服虔曰：「皆羌種，在河西之河南也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_82_152","chapterId":"ch_work_han_thu_82","textTraditional":"〔一一〕師古曰：「信讀曰申。」","sentenceOrder":152},
  {"id":"s_work_han_thu_82_153","chapterId":"ch_work_han_thu_82","textTraditional":"〔一二〕鄭氏曰：「橋成軍行安易，若於枕席上過也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_82_154","chapterId":"ch_work_han_thu_82","textTraditional":"上復賜報曰：「皇帝問後將軍，言十二便，聞之。虜雖未伏誅，兵決可期月而望，期月而望者，謂今冬邪，謂何時也？將軍獨不計虜聞兵頗罷，且丁壯相聚，攻擾田者及道上屯兵，復殺略人民，將何以止之？又大开、小开前言曰：『我告漢軍先零所在，兵不往擊，久留，得亡效五年時不分別人而并擊我？』〔一〕其意常恐。今兵不出，得亡變生，與先零為一？將軍孰計復奏。」充國奏曰：","sentenceOrder":154},
  {"id":"s_work_han_thu_82_155","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　如淳曰：「此語謂本始五年伐先零，不分別大小开本意，是以大小开有此言也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_82_156","chapterId":"ch_work_han_thu_82","textTraditional":"臣聞兵以計為本，故多算勝少算。先零羌精兵今餘不過七八千人，失地遠客，分散飢凍。罕、开、莫須又頗暴略其羸弱畜產，畔還者不絕，皆聞天子明令相捕斬之賞。臣愚以為虜破壞可日月冀，遠在來春，故曰兵決可期月而望。竊見北邊自敦煌至遼東萬一千五百餘里，乘塞列隧有吏卒數千人，虜數大眾攻之而不能害。今留步士萬人屯田，地勢平易，多高山遠望之便，部曲相保，為塹壘木樵，〔一〕校聯不絕，〔二〕便兵弩，飭鬥具。〔三〕烽火幸通，勢及并力，以逸待勞，兵之利者也。臣愚以為屯田內有亡費之利，外有守禦之備。騎兵雖罷，虜見萬人留田為必禽之具，其土崩歸德，宜不久矣。從今盡三月，虜馬羸瘦，必不敢捐其妻子於他種中，遠涉河山而來為寇。又見屯田之士精兵萬人，終不敢復將其累重還歸故地。〔四〕是臣之愚計，所以度虜且必瓦解其處，〔五〕不戰而自破之冊也。至於虜小寇盜，時殺人民，其原未可卒禁。〔六〕臣聞戰不必勝，不苟接刃；攻不必取，不苟勞眾。誠令兵出，雖不能滅先零，亶能令虜絕不為小寇，則出兵可也。〔七〕即今同是〔八〕而釋坐勝之道，從乘危之勢，往終不見利，空內自罷敝，〔九〕貶重而自損，非所以視蠻夷也。〔一０〕又大兵一出，還不可復留，湟中亦未可空，如是，繇役復發也。且匈奴不可不備，烏桓不可不憂。今久轉運煩費，傾我不虞之用以澹一隅，〔一一〕臣愚以為不便。校尉臨眾幸得承威德，奉厚幣，拊循眾羌，諭以明詔，宜皆鄉風。〔一二〕雖其前辭嘗曰「得亡效五年」，宜亡它心，不足以故出兵。臣竊自惟念，奉詔出塞，引軍遠擊，窮天子之精兵，散車甲於山野，雖亡尺寸之功，媮得避慊之便〔一三〕，而亡後咎餘責，此人臣不忠之利，非明主社稷之福也。臣幸得奮精兵，討不義，久留天誅，〔一四〕罪當萬死。陛下寬仁，未忍加誅，（今）〔令〕臣數得孰計。〔一五〕愚臣伏計孰甚，不敢避斧鉞之誅，昧死陳愚，唯陛下省察。","sentenceOrder":156},
  {"id":"s_work_han_thu_82_157","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「樵與譙同，謂為高樓以望敵也，音才消反。」","sentenceOrder":157},
  {"id":"s_work_han_thu_82_158","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　如淳曰：「播校相連也。」師古曰：「此校謂用木自相貫穿以為固者，亦猶周易『荷校滅耳』也。周禮『校人掌王馬之政』，『六廄成校』，蓋用關械闌養馬也。說文解字云『校，木囚也』，亦謂以木相貫，遮闌禽獸也。今云校聯不絕，言營壘相次。」","sentenceOrder":158},
  {"id":"s_work_han_thu_82_159","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　師古曰：「便，利也。飭，整也，其字從力。」","sentenceOrder":159},
  {"id":"s_work_han_thu_82_160","chapterId":"ch_work_han_thu_82","textTraditional":"〔四〕　師古曰：「累重謂妻子也。累音力瑞反。重音直用反。」","sentenceOrder":160},
  {"id":"s_work_han_thu_82_161","chapterId":"ch_work_han_thu_82","textTraditional":"〔五〕　師古曰：「各於其處自瓦解。」","sentenceOrder":161},
  {"id":"s_work_han_thu_82_162","chapterId":"ch_work_han_thu_82","textTraditional":"〔六〕　師古曰：「卒讀曰猝。」","sentenceOrder":162},
  {"id":"s_work_han_thu_82_163","chapterId":"ch_work_han_thu_82","textTraditional":"〔七〕　師古曰：「亶讀曰但。」","sentenceOrder":163},
  {"id":"s_work_han_thu_82_164","chapterId":"ch_work_han_thu_82","textTraditional":"〔八〕　師古曰：「俱不能止小寇盜。」","sentenceOrder":164},
  {"id":"s_work_han_thu_82_165","chapterId":"ch_work_han_thu_82","textTraditional":"〔九〕　師古曰：「罷讀曰疲。」","sentenceOrder":165},
  {"id":"s_work_han_thu_82_166","chapterId":"ch_work_han_thu_82","textTraditional":"〔一０〕師古曰：「視讀曰示。」","sentenceOrder":166},
  {"id":"s_work_han_thu_82_167","chapterId":"ch_work_han_thu_82","textTraditional":"〔一一〕師古曰：「澹，古贍字。贍，給也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_82_168","chapterId":"ch_work_han_thu_82","textTraditional":"〔一二〕師古曰：「諭，曉告之。鄉讀曰嚮。」","sentenceOrder":168},
  {"id":"s_work_han_thu_82_169","chapterId":"ch_work_han_thu_82","textTraditional":"〔一三〕師古曰：「媮，苟且也。慊亦嫌字。」","sentenceOrder":169},
  {"id":"s_work_han_thu_82_170","chapterId":"ch_work_han_thu_82","textTraditional":"〔一四〕師古曰：「言不早殄滅賊也。」","sentenceOrder":170},
  {"id":"s_work_han_thu_82_171","chapterId":"ch_work_han_thu_82","textTraditional":"〔一五〕師古曰：「數音所角反。其下亦同。」","sentenceOrder":171},
  {"id":"s_work_han_thu_82_172","chapterId":"ch_work_han_thu_82","textTraditional":"充國奏每上，輒下公卿議臣。初是充國計者什三，中什五，最後什八。有詔詰前言不便者，皆頓首服。丞相魏相曰：「臣愚不習兵事利害，後將軍數畫軍冊，其言常是，臣任其計可必用也。」〔一〕上於是報充國曰：「皇帝問後將軍，上書言羌虜可勝之道，今聽將軍，將軍計善。其上留屯田及當罷者人馬數。將軍強食，慎兵事，自愛！」上以破羌、強弩將軍數言當擊，又用充國屯田處離散，恐虜犯之，於是兩從其計，詔兩將軍與中郎將卬出擊。強弩出，降四千餘人，破羌斬首二千級，中郎將卬斬首降者亦二千餘級，而充國所降復得五千餘人。詔罷兵，獨充國留屯田。","sentenceOrder":172},
  {"id":"s_work_han_thu_82_173","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「任，保也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_82_174","chapterId":"ch_work_han_thu_82","textTraditional":"明年五月，充國奏言：「羌本可五萬人軍，凡斬首七千六百級，降者三萬一千二百人，溺河湟飢餓死者五六千人，定計遺脫與煎鞏、黃羝俱亡者不過四千人。羌靡忘等自詭必得，〔一〕請罷屯兵。」奏可，充國振旅而還。","sentenceOrder":174},
  {"id":"s_work_han_thu_82_175","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「詭，責也。自以為憂，責言必能得之。」","sentenceOrder":175},
  {"id":"s_work_han_thu_82_176","chapterId":"ch_work_han_thu_82","textTraditional":"所善浩星賜迎說充國，〔一〕曰：「眾人皆以破羌、強弩出擊，多斬首獲降，虜以破壞。然有識者以為虜勢窮困，兵雖不出，必自服矣。將軍即見，宜歸功於二將軍出擊，非愚臣所及。如此，將軍計未失也。」充國曰：「吾年老矣，爵位已極，豈嫌伐一時事以欺明主哉！兵勢，國之大事，當為後法。老臣不以餘命壹為陛下明言兵之利害，卒死，誰當復言之者？」〔二〕卒以其意對。〔三〕上然其計，罷遣辛武賢歸酒泉太守官，充國復為後將軍衛尉。","sentenceOrder":176},
  {"id":"s_work_han_thu_82_177","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　鄧展曰：「浩星，姓；賜，名也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_82_178","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「卒讀曰猝。」","sentenceOrder":178},
  {"id":"s_work_han_thu_82_179","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　師古曰：「卒，終也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_82_180","chapterId":"ch_work_han_thu_82","textTraditional":"其秋，羌若零、離留、且種、兒庫〔一〕共斬先零大豪猶非、楊玉首，〔二〕及諸豪弟澤、陽雕、良兒、靡忘皆帥煎鞏、黃羝之屬四千餘人降漢。封若零、弟澤二人為帥眾王，離留、且種二人為侯，兒庫為君，陽雕為言兵侯，良兒為君，靡忘為獻牛君。初置金城屬國以處降羌。","sentenceOrder":180},
  {"id":"s_work_han_thu_82_181","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「且，子閭反。」","sentenceOrder":181},
  {"id":"s_work_han_thu_82_182","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　文穎曰：「猶非，人名也。」師古曰：「猶非及楊玉，二人也。宣紀作酋非，而此傳作猶字，疑紀誤。」","sentenceOrder":182},
  {"id":"s_work_han_thu_82_183","chapterId":"ch_work_han_thu_82","textTraditional":"詔舉可護羌校尉者，時充國病，四府舉辛武賢小弟湯。充國遽起奏：「湯使酒，不可典蠻夷。〔一〕不如湯兄臨眾。」時湯已拜受節，有詔更用臨眾。後臨眾病免，五府復舉湯，湯數醉〈酉句〉羌人，〔二〕羌人反畔，卒如充國之言。","sentenceOrder":183},
  {"id":"s_work_han_thu_82_184","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「使酒，因酒以使氣，若今言惡酒者。」","sentenceOrder":184},
  {"id":"s_work_han_thu_82_185","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「〈酉句〉音況務反。」師古曰：「即酗字也。醉怒曰〈酉句〉。」","sentenceOrder":185},
  {"id":"s_work_han_thu_82_186","chapterId":"ch_work_han_thu_82","textTraditional":"初，破羌將軍武賢在軍中時與中郎將卬宴語，〔一〕卬道：「車騎將軍張安世始嘗不快上，〔二〕上欲誅之，卬家將軍以為安世本持橐簪筆〔三〕事孝武帝數十年，見謂忠謹，宜全度之。〔四〕安世用是得免。」及充國還言兵事，武賢罷歸故官，深恨，上書告卬泄省中語。卬坐禁止而入至充國莫府司馬中亂屯兵〔五〕下吏，自殺。","sentenceOrder":186},
  {"id":"s_work_han_thu_82_187","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「閑宴時共語也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_82_188","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　如淳曰：「所為行不可上意。」","sentenceOrder":188},
  {"id":"s_work_han_thu_82_189","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　張晏曰：「橐，契囊也。近臣負橐簪筆，從備顧問，或有所紀也。」師古曰：「橐，所以盛書也。有底曰囊，無底曰橐。簪筆者，插筆於首。橐音丁各反，又音託。」","sentenceOrder":189},
  {"id":"s_work_han_thu_82_190","chapterId":"ch_work_han_thu_82","textTraditional":"〔四〕　師古曰：「全安而免度之，不令喪敗也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_82_191","chapterId":"ch_work_han_thu_82","textTraditional":"〔五〕　如淳曰：「方見禁止而入至充國莫府司馬中。司馬中，律所謂營軍司馬中也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_82_192","chapterId":"ch_work_han_thu_82","textTraditional":"充國乞骸骨，賜安車駟馬、黃金六十斤，罷就第。朝庭每有四夷大議，常與參兵謀，問籌策焉。〔一〕年八十六，甘露二年薨，諡曰壯侯。傳子至孫欽，欽尚敬武公主。主亡子，主教欽良人習詐有身，名它人子。欽薨，子岑嗣侯，習為太夫人。岑父母求錢財亡已，忿恨相告。岑坐非子免，國除。元始中，修功臣後，復封充國曾孫伋為營平侯。〔二〕","sentenceOrder":192},
  {"id":"s_work_han_thu_82_193","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「與讀曰豫。」","sentenceOrder":193},
  {"id":"s_work_han_thu_82_194","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「伋音汲。」","sentenceOrder":194},
  {"id":"s_work_han_thu_82_195","chapterId":"ch_work_han_thu_82","textTraditional":"初，充國以功德與霍光等列，畫未央宮。成帝時，西羌嘗有警，上思將帥之臣，追美充國，乃召黃門郎楊雄即充國圖畫而頌之，〔一〕曰：","sentenceOrder":195},
  {"id":"s_work_han_thu_82_196","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「即，就也。於畫側而書頌。」","sentenceOrder":196},
  {"id":"s_work_han_thu_82_197","chapterId":"ch_work_han_thu_82","textTraditional":"明靈惟宣，戎有先零。先零昌狂，侵漢西疆。漢命虎臣，惟後將軍，整我六師，是討是震。〔一〕既臨其域，諭以威德，有守矜功，謂之弗克。請奮其旅，于罕之羌，天子命我，從之鮮陽。〔二〕營平守節，婁奏封章，〔三〕料敵制勝，威謀靡亢。〔四〕遂克西戎，還師於京，鬼方賓服，罔有不庭。〔五〕昔周之宣，有方有虎〔六〕，詩人歌功，乃列于雅。〔七〕在漢中興，充國作武，赳赳桓桓，亦紹厥後。〔八〕","sentenceOrder":197},
  {"id":"s_work_han_thu_82_198","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「震合韻音真。」","sentenceOrder":198},
  {"id":"s_work_han_thu_82_199","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　應劭曰：「酒泉太守辛武賢自將萬騎出張掖擊羌。宣帝使充國共武賢討罕、开於鮮水之陽也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_82_200","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　師古曰：「婁，古屢字。」","sentenceOrder":200},
  {"id":"s_work_han_thu_82_201","chapterId":"ch_work_han_thu_82","textTraditional":"〔四〕　師古曰：「料，量也。亢，當也。合韻音康。」","sentenceOrder":201},
  {"id":"s_work_han_thu_82_202","chapterId":"ch_work_han_thu_82","textTraditional":"〔五〕　師古曰：「鬼方，言其幽昧也。庭，來帝庭也。一說庭，直也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_82_203","chapterId":"ch_work_han_thu_82","textTraditional":"〔六〕　張晏曰：「方叔、邵虎也。」","sentenceOrder":203},
  {"id":"s_work_han_thu_82_204","chapterId":"ch_work_han_thu_82","textTraditional":"〔七〕　師古曰：「大雅、小雅之詩也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_82_205","chapterId":"ch_work_han_thu_82","textTraditional":"〔八〕　師古曰：「赳赳，勁也。桓桓，威也。紹厥後謂繼周之方、邵也。」","sentenceOrder":205},
  {"id":"s_work_han_thu_82_206","chapterId":"ch_work_han_thu_82","textTraditional":"充國為後將軍，徙杜陵。辛武賢自羌軍還後七年，復為破羌將軍，征烏孫至敦煌，後不出，徵未到，病卒。子慶忌至大官。","sentenceOrder":206},
  {"id":"s_work_han_thu_82_207","chapterId":"ch_work_han_thu_82","textTraditional":"辛慶忌字子真，少以父任為右校丞，隨長羅侯常惠屯田烏孫赤谷城，與歙侯戰，〔一〕陷陳卻敵。惠奏其功，拜為侍郎，遷校尉，將吏士屯焉耆國。還為謁者，尚未知名。元帝初，補金城長史，舉茂材，遷郎中車騎將（軍），朝庭多重之者。轉為校尉，遷張掖太守，徙酒泉，所在著名。","sentenceOrder":207},
  {"id":"s_work_han_thu_82_208","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「歙即翕字也。歙侯，烏孫官名。」","sentenceOrder":208},
  {"id":"s_work_han_thu_82_209","chapterId":"ch_work_han_thu_82","textTraditional":"成帝初，徵為光祿大夫，遷左曹中郎將，至執金吾。始武賢與趙充國有隙，後充國家殺辛氏，至慶忌為執金吾，坐子殺趙氏，左遷酒泉太守。歲餘，大將軍王鳳薦慶忌「前在兩郡著功跡，徵入，歷位朝廷，莫不信鄉。〔一〕質行正直，仁勇得眾心，通於兵事，明略威重，任國柱石。〔二〕父破羌將軍武賢顯名前世，有威西夷。臣鳳不宜久處慶忌之右。」〔三〕乃復徵為光祿大夫、執金吾。數年，坐小法左遷雲中太守，復徵為光祿勳。","sentenceOrder":209},
  {"id":"s_work_han_thu_82_210","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":210},
  {"id":"s_work_han_thu_82_211","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「任，堪也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_82_212","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　師古曰：「右，上也。」","sentenceOrder":212},
  {"id":"s_work_han_thu_82_213","chapterId":"ch_work_han_thu_82","textTraditional":"時數有災異，丞相司直何武上封事曰：「虞有宮之奇，晉獻不寐；〔一〕衛青在位，淮南寢謀。故賢人立朝，折衝厭難，勝於亡形。〔二〕司馬法曰：『天下雖安，忘戰必危。』夫將不豫設，則亡以應卒；〔三〕士不素厲，則難使死敵。是以先帝建列將之官，近戚主內，異姓距外，故姦軌不得萌動而破滅，〔四〕誠萬世之長冊也。光祿勳慶忌行義修正，柔毅敦厚，〔五〕謀慮深遠。前在邊郡，數破敵獲虜，外夷莫不聞。乃者大異並見，未有其應。加以兵革久寢。春秋大災未至而豫禦之，〔六〕慶忌宜在爪牙官以備不虞。」〔七〕其後拜為右將軍諸吏散騎給事中，歲餘徙為左將軍。","sentenceOrder":213},
  {"id":"s_work_han_thu_82_214","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　應劭曰：「晉獻公欲伐虞，以宮之奇在，寢不寐。」","sentenceOrder":214},
  {"id":"s_work_han_thu_82_215","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「厭，抑也。未有禍難之形，豫勝之也。厭音一葉反。」","sentenceOrder":215},
  {"id":"s_work_han_thu_82_216","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　師古曰：「卒讀曰猝，謂暴也。」","sentenceOrder":216},
  {"id":"s_work_han_thu_82_217","chapterId":"ch_work_han_thu_82","textTraditional":"〔四〕　師古曰：「始生曰萌。」","sentenceOrder":217},
  {"id":"s_work_han_thu_82_218","chapterId":"ch_work_han_thu_82","textTraditional":"〔五〕　師古曰：「和柔而能沈毅也。尚書咎繇謨曰『擾而毅』。擾亦柔也。今流俗書本柔字作果者，妄改之。」","sentenceOrder":218},
  {"id":"s_work_han_thu_82_219","chapterId":"ch_work_han_thu_82","textTraditional":"〔六〕　師古曰：「莊十八年『公追戎於濟西』。公羊傳曰：『此未有伐中國者，言追何？大其未至而豫禦也。』」","sentenceOrder":219},
  {"id":"s_work_han_thu_82_220","chapterId":"ch_work_han_thu_82","textTraditional":"〔七〕　師古曰；「虞，度也。言有寇難非意所度也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_82_221","chapterId":"ch_work_han_thu_82","textTraditional":"慶忌居處恭儉，食飲被服尤節約，然性好輿馬，號為鮮明，唯是為奢。為國虎臣，遭世承平，匈奴、西域親附，敬其威信。年老卒官。長子通為護羌校尉，中子遵函谷關都尉，少子茂水衡都尉出為郡守，皆有將帥之風。宗族支屬至二千石者十餘人。","sentenceOrder":221},
  {"id":"s_work_han_thu_82_222","chapterId":"ch_work_han_thu_82","textTraditional":"元始中，安漢公王莽秉政，見慶忌本大將軍鳳所成，三子皆能，欲親厚之。是時莽方立威柄，用甄豐、甄邯以自助，豐、邯新貴，威震朝廷。水衡都尉茂自見名臣子孫，兄弟並列，不甚詘事兩甄。時平帝幼，外家衛氏不得在京師，而護羌校尉通長子次兄素與帝從舅衛子伯相善，〔一〕兩人俱游俠，賓客甚盛。及呂寬事起，莽誅衛氏。兩甄搆言諸辛陰與衛子伯為心腹，有背恩不說安漢公之謀。〔二〕於是司直陳崇舉奏其宗親隴西辛興等侵陵百姓，威行州郡。莽遂按通父子、遵茂兄弟及南郡太守辛伯等，皆誅殺之。辛氏繇是廢。〔三〕慶忌本狄道人，為將軍，徙昌陵。昌陵罷，留長安。","sentenceOrder":222},
  {"id":"s_work_han_thu_82_223","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「次兄，其字也。兄讀如本字，亦讀曰況。」","sentenceOrder":223},
  {"id":"s_work_han_thu_82_224","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":224},
  {"id":"s_work_han_thu_82_225","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　師古曰：「繇讀與由同。」","sentenceOrder":225},
  {"id":"s_work_han_thu_82_226","chapterId":"ch_work_han_thu_82","textTraditional":"贊曰：秦漢已來，山東出相，山西出將。秦將軍白起，郿人〔一〕；王翦，頻陽人。漢興，郁郅王圍、甘延壽，〔二〕義渠公孫賀、傅介子，成紀李廣、李蔡，杜陵蘇建、蘇武，上邽上官桀、趙充國，襄武廉褒，狄道辛武賢、慶忌，皆以勇武顯聞。蘇、辛父子著節，此其可稱列者也，其餘不可勝數。何則？山西天水、隴西、安定、北地處勢迫近羌胡，民俗修習戰備，高上勇力鞍馬騎射。故秦詩曰：「王于興師，修我甲兵，與子皆行。」〔三〕其風聲氣俗自古而然，今之歌謠慷慨，風流猶存耳。","sentenceOrder":226},
  {"id":"s_work_han_thu_82_227","chapterId":"ch_work_han_thu_82","textTraditional":"〔一〕　師古曰：「郿，扶風之縣也，音媚。」","sentenceOrder":227},
  {"id":"s_work_han_thu_82_228","chapterId":"ch_work_han_thu_82","textTraditional":"〔二〕　師古曰：「圍為強弩將軍，見藝文志。郁音於六反。郅音質。」","sentenceOrder":228},
  {"id":"s_work_han_thu_82_229","chapterId":"ch_work_han_thu_82","textTraditional":"〔三〕　師古曰：「小戎之詩也，解在地理志。」","sentenceOrder":229},
  {"id":"s_work_han_thu_82_230","chapterId":"ch_work_han_thu_82","textTraditional":"校勘記","sentenceOrder":230},
  {"id":"s_work_han_thu_82_231","chapterId":"ch_work_han_thu_82","textTraditional":"二九七四頁　九行　設謂（聞）〔開〕許之也。　景祐、殿本都作「開」。王先謙說作「開」是。","sentenceOrder":231},
  {"id":"s_work_han_thu_82_232","chapterId":"ch_work_han_thu_82","textTraditional":"二九八０頁一一行　長水校尉富昌、酒泉（侯）〔候〕奉世將婼、月氏兵四千人，　沈欽韓說，「侯」當為「候」，奉世即馮奉世。","sentenceOrder":232},
  {"id":"s_work_han_thu_82_233","chapterId":"ch_work_han_thu_82","textTraditional":"二九八一頁　七行　若有便宜，則當（國）〔固〕守以取安利也。　王先謙說，「國」當為「固」。按景祐、殿、局本都作「固」。","sentenceOrder":233},
  {"id":"s_work_han_thu_82_234","chapterId":"ch_work_han_thu_82","textTraditional":"二九八一頁一０行　（此羌之首帥名王）　錢大昭說，閩本無「此羌」句。按景祐本無此句。","sentenceOrder":234},
  {"id":"s_work_han_thu_82_235","chapterId":"ch_work_han_thu_82","textTraditional":"二九八四頁一二行　失之毫釐，差（之）〔以〕千里，　景祐、殿本都作「以」。","sentenceOrder":235},
  {"id":"s_work_han_thu_82_236","chapterId":"ch_work_han_thu_82","textTraditional":"二九九０頁一二行　（今）〔令〕臣數得孰計。　景祐、殿本都作「令」。王先謙說作「令」是。","sentenceOrder":236},
  {"id":"s_work_han_thu_82_237","chapterId":"ch_work_han_thu_82","textTraditional":"二九九三頁一三行　師古曰：　王先謙說前「師古」誤。按各本皆誤。","sentenceOrder":237},
  {"id":"s_work_han_thu_82_238","chapterId":"ch_work_han_thu_82","textTraditional":"二九九六頁　三行　遷郎中車騎將（軍），　劉敞、齊召南、沈欽韓都說「軍」字衍。","sentenceOrder":238},
  {"id":"s_work_han_thu_83_1","chapterId":"ch_work_han_thu_83","textTraditional":"傅介子，北地人也，〔一〕以從軍為官。先是龜茲、樓蘭皆嘗殺漢使者，〔二〕語在西域傳。至元鳳中，介子以駿馬監求使大宛，因詔令責樓蘭、龜茲國。","sentenceOrder":1},
  {"id":"s_work_han_thu_83_2","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「趙充國傳贊云『義渠公孫賀、傅介子』，然則介子北地義渠人也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_83_3","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　服虔曰：「龜茲音丘慈。」","sentenceOrder":3},
  {"id":"s_work_han_thu_83_4","chapterId":"ch_work_han_thu_83","textTraditional":"介子至樓蘭，責其王教匈奴遮殺漢使：「大兵方至，王苟不教匈奴，匈奴使過至諸國，何為不言？」王謝服，言「匈奴使屬過，〔一〕當至烏孫，道過龜茲。」介子至龜茲，復責其王，王亦服罪。介子從大宛還到龜茲，龜茲言「匈奴使從烏孫還，在此。」介子因率其吏士共誅斬匈奴使者。還奏事，詔拜介子為中郎，遷平樂監。","sentenceOrder":4},
  {"id":"s_work_han_thu_83_5","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「屬，近也。近始過去。屬音之欲反。」","sentenceOrder":5},
  {"id":"s_work_han_thu_83_6","chapterId":"ch_work_han_thu_83","textTraditional":"介子謂大將軍霍光曰：「樓蘭、龜茲數反覆而不誅，無所懲艾。〔一〕介子過龜茲時，其王近就人，易得也，〔二〕願往刺之，以威示諸國。」大將軍曰：「龜茲道遠，且驗之於樓蘭。」於是白遣之。","sentenceOrder":6},
  {"id":"s_work_han_thu_83_7","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「艾讀曰乂。」","sentenceOrder":7},
  {"id":"s_work_han_thu_83_8","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「附近而親就，言不相猜阻也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_83_9","chapterId":"ch_work_han_thu_83","textTraditional":"介子與士卒俱齎金幣，揚言以賜外國為名。至樓蘭，樓蘭王意不親介子，介子陽引去，至其西界，使譯謂曰：「漢使者持黃金錦繡行賜諸國，〔一〕王不來受，我去之西國矣。」即出金幣以示譯。譯還報王，王貪漢物，來見使者。介子與坐飲，陳物示之。飲酒皆醉，介子謂王曰：「天子使我私報王。」〔二〕王起隨介子入帳中，屏語，〔三〕壯士二人從後刺之，刃交胸，立死。其貴人左右皆散走。介子告諭以「王負漢罪，天子遣我來誅王，當更立前太子質在漢者。漢兵方至，毋敢動，動，滅國矣！」遂持王首還詣闕，公卿將軍議者咸嘉其功。上乃下詔曰：「樓蘭王安歸嘗為匈奴間，候遮漢使者，〔四〕發兵殺略衛司馬安樂、光祿大夫忠、期門郎遂成等三輩，及安息、大宛使，盜取節印獻物，〔五〕甚逆天理。平樂監傅介子持節使誅斬樓蘭王安歸首，縣之北闕，以直報怨，〔六〕不煩師眾。其封介子為義陽侯，食邑七百戶。士刺王者皆補侍郎。」","sentenceOrder":9},
  {"id":"s_work_han_thu_83_10","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「遍往賜之。」","sentenceOrder":10},
  {"id":"s_work_han_thu_83_11","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「謂密有所論。」","sentenceOrder":11},
  {"id":"s_work_han_thu_83_12","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　師古曰：「屏人而獨共語也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_83_13","chapterId":"ch_work_han_thu_83","textTraditional":"〔四〕　師古曰：「（間）〔言〕為匈奴之間（為）〔而〕候伺。」","sentenceOrder":13},
  {"id":"s_work_han_thu_83_14","chapterId":"ch_work_han_thu_83","textTraditional":"〔五〕　晉灼曰：「此安息、大宛遠遣使獻漢，而樓蘭王使人盜取所獻之物也。」師古曰：「節及印，漢使者所賫也。獻物，大宛等使所獻也。樓蘭既殺漢使，又殺諸國使者。」","sentenceOrder":14},
  {"id":"s_work_han_thu_83_15","chapterId":"ch_work_han_thu_83","textTraditional":"〔六〕　師古曰：「論語載孔子言曰『以直報怨，以德報德』，言怨於我者則直道而報之。故詔引之也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_83_16","chapterId":"ch_work_han_thu_83","textTraditional":"介子薨，子敞有罪不得嗣，國除。元始中，繼功臣世，復封介子曾孫長為義陽侯，王莽敗，乃絕。","sentenceOrder":16},
  {"id":"s_work_han_thu_83_17","chapterId":"ch_work_han_thu_83","textTraditional":"常惠，太原人也。少時家貧，自奮應募，隨栘中監蘇武使匈奴，〔一〕并見拘留十餘年，昭帝時乃還。漢嘉其勤勞，拜為光祿大夫。","sentenceOrder":17},
  {"id":"s_work_han_thu_83_18","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「栘中，廄名也，音移。解在昭紀。」","sentenceOrder":18},
  {"id":"s_work_han_thu_83_19","chapterId":"ch_work_han_thu_83","textTraditional":"是時，烏孫公主上書言「匈奴發騎田車師，〔一〕車師與匈奴為一，共侵烏孫，唯天子救之！」漢養士馬，議欲擊匈奴。會昭帝崩，宣帝初即位，本始二年，遣惠使烏孫。公主及昆彌皆遣使，因惠言「匈奴連發大兵擊烏孫，取車延、惡師地，收其人民去，使使脅求公主，〔二〕欲隔絕漢。昆彌願發國半精兵，自給人馬五萬騎，盡力擊匈奴。唯天子出兵以救公主、昆彌！」於是漢大發十五萬騎，五將軍分道出，〔三〕語在匈奴傳。","sentenceOrder":19},
  {"id":"s_work_han_thu_83_20","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「車師，西域國名也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_83_21","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「脅謂以威迫之也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_83_22","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　師古曰：「祁連將軍田廣明、蒲類將軍趙充國、武牙將軍田順、度遼將軍范明友、前將軍韓增。」","sentenceOrder":22},
  {"id":"s_work_han_thu_83_23","chapterId":"ch_work_han_thu_83","textTraditional":"以惠為校尉，持節護烏孫兵。昆彌自將翕侯以下五萬餘騎〔一〕從西方入至右谷蠡庭，〔二〕獲單于父行及嫂居次，〔三〕名王騎將以下三萬九千人，得馬牛驢驘橐佗五萬餘匹，羊六十餘萬頭，烏孫皆自取鹵獲。惠從吏卒十餘人隨昆彌還，未至烏孫，烏孫人盜惠印綬節。惠還，自以當誅。〔四〕時漢五將皆無功，天子以惠奉使克獲，遂封惠為長羅侯。復遣惠持金幣還賜烏孫貴人有功者，惠因奏請龜茲國嘗殺校尉賴丹，未伏誅，請便道擊之，宣帝不許。大將軍霍光風惠以便宜從事。〔五〕惠與吏士五百人俱至烏孫，還過，發西國兵二萬人，令副使發龜茲東國二萬人，烏孫兵七千人，從三面攻龜茲，兵未合，先遣人責其王以前殺漢使狀。王謝曰：「乃我先王時為貴人姑翼所誤耳，我無罪。」惠曰：「即如此，縛姑翼來，吾置王。」〔六〕王執姑翼詣惠，惠斬之而還。","sentenceOrder":23},
  {"id":"s_work_han_thu_83_24","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「歙即翕字也。翕侯，烏孫官號也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_83_25","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「谷音鹿。蠡音黎。」","sentenceOrder":25},
  {"id":"s_work_han_thu_83_26","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　晉灼曰：「匈奴女號，若言公主也。」師古曰：「行音胡浪反。」","sentenceOrder":26},
  {"id":"s_work_han_thu_83_27","chapterId":"ch_work_han_thu_83","textTraditional":"〔四〕　師古曰：「謂失印綬及節為辱命。」","sentenceOrder":27},
  {"id":"s_work_han_thu_83_28","chapterId":"ch_work_han_thu_83","textTraditional":"〔五〕　師古曰：「言至前所專命而行也。風讀曰諷。」","sentenceOrder":28},
  {"id":"s_work_han_thu_83_29","chapterId":"ch_work_han_thu_83","textTraditional":"〔六〕　師古曰：「置猶放。」","sentenceOrder":29},
  {"id":"s_work_han_thu_83_30","chapterId":"ch_work_han_thu_83","textTraditional":"後代蘇武為典屬國，明習外國事，勤勞數有功。甘露中，後將軍趙充國薨，天子遂以惠為右將軍，典屬國如故。宣帝崩，惠事元帝，三歲薨，諡曰壯武侯。傳國至曾孫，建武中乃絕。","sentenceOrder":30},
  {"id":"s_work_han_thu_83_31","chapterId":"ch_work_han_thu_83","textTraditional":"鄭吉，會稽人也，以卒伍從軍，數出西域，由是為郎。吉為人彊執，習外國事。〔一〕自張騫通西域，李廣利征伐之後，初置校尉，屯田渠黎。至宣帝時，吉以侍郎田渠黎，積穀，因發諸國兵攻破車師，遷衛司馬，使護鄯善以西南道。〔二〕","sentenceOrder":31},
  {"id":"s_work_han_thu_83_32","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「彊力而有執志者。」","sentenceOrder":32},
  {"id":"s_work_han_thu_83_33","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「鄯音善。」","sentenceOrder":33},
  {"id":"s_work_han_thu_83_34","chapterId":"ch_work_han_thu_83","textTraditional":"神爵中，匈奴乖亂，日逐王先賢撣欲降漢，〔一〕使人與吉相聞。吉發渠黎、龜茲諸國五萬人迎日逐王，口萬二千人、小王將十二人隨吉至河曲，頗有亡者，吉追斬之，遂將詣京師。漢封日逐王為歸德侯。","sentenceOrder":34},
  {"id":"s_work_han_thu_83_35","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「撣音纏。」","sentenceOrder":35},
  {"id":"s_work_han_thu_83_36","chapterId":"ch_work_han_thu_83","textTraditional":"吉既破車師，降日逐，威震西域，遂并護車師以西北道，故號都護。〔一〕都護之置自吉始焉。","sentenceOrder":36},
  {"id":"s_work_han_thu_83_37","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「並護南北二道，故謂之都。都猶大也，總也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_83_38","chapterId":"ch_work_han_thu_83","textTraditional":"上嘉其功效，乃下詔曰：「都護西域騎都尉鄭吉，拊循外蠻，宣明威信，〔一〕迎匈奴單于從兄日逐王眾，擊破車師兜訾城，〔二〕功效茂著。其封吉為安遠侯，食邑千戶。」吉於是中西域而立莫府，〔三〕治烏壘城，鎮撫諸國，誅伐懷集之。漢之號令班西域矣，〔四〕始自張騫而成於鄭吉。語在西域傳。","sentenceOrder":38},
  {"id":"s_work_han_thu_83_39","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「禮云東夷、北狄、西戎、南蠻，然夷蠻戎狄亦四方之總稱耳，故史傳又云百蠻也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_83_40","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「訾音子移反。」","sentenceOrder":40},
  {"id":"s_work_han_thu_83_41","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　師古曰：「中西域者，言最處諸國之中，近遠均也。中音竹仲反。」","sentenceOrder":41},
  {"id":"s_work_han_thu_83_42","chapterId":"ch_work_han_thu_83","textTraditional":"〔四〕　師古曰：「班，布也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_83_43","chapterId":"ch_work_han_thu_83","textTraditional":"吉薨，諡曰繆侯。子光嗣，薨，無子，國除。元始中，錄功臣不以罪絕者，封吉曾孫永為安遠侯。","sentenceOrder":43},
  {"id":"s_work_han_thu_83_44","chapterId":"ch_work_han_thu_83","textTraditional":"甘延壽字君況，北地郁郅人也。少以良家子善騎射為羽林，投石拔距絕於等倫，〔一〕嘗超踰羽林亭樓，由是遷為郎。試弁，為期門，〔二〕以材力愛幸。稍遷至遼東太守，免官。車騎將軍許嘉薦延壽為郎中諫大夫，使西域都護騎都尉，與副校尉陳湯共誅斬郅支單于，封義成侯。薨，諡曰壯侯。傳國至曾孫，王莽敗，乃絕。","sentenceOrder":44},
  {"id":"s_work_han_thu_83_45","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　應劭曰：「投石，以石投人也。拔距，即下超踰羽林亭樓是也。」張晏曰：「范蠡兵法飛石重十二斤，為機發，行二百步。延壽有力，能以手投之。拔距，超距也。」師古曰：「投石，應（劭）〔說〕是也。拔距者，有人連坐相把據地，距以為堅而能拔取之，皆言其有手掣之力。超踰亭樓，又言其趫捷耳，非拔距也。今人猶（言）〔有〕拔爪之戲，蓋拔距之遺法。」","sentenceOrder":45},
  {"id":"s_work_han_thu_83_46","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　孟康曰：「弁，手搏。」","sentenceOrder":46},
  {"id":"s_work_han_thu_83_47","chapterId":"ch_work_han_thu_83","textTraditional":"陳湯字子公，山陽瑕丘人也。少好書，博達善屬文。〔一〕家貧匄貣無節，不為州里所稱。〔二〕西至長安求官，得太官獻食丞。數歲，富平侯張勃與湯交，高其能。初元二年，元帝詔列侯舉茂材，勃舉湯。湯待遷，父死不奔喪，〔三〕司隸奏湯無循行，勃選舉故不以實，坐削（二百戶）〔戶二百〕，會薨，因賜諡曰繆侯。〔四〕湯下獄論。後復以薦為郎，數求使外國。久之，遷西域副校尉，與甘延壽俱出。","sentenceOrder":47},
  {"id":"s_work_han_thu_83_48","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「屬音之欲反。」","sentenceOrder":48},
  {"id":"s_work_han_thu_83_49","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「匄，乞也。貣音吐得反。」","sentenceOrder":49},
  {"id":"s_work_han_thu_83_50","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　師古曰：「犇，古奔字。」","sentenceOrder":50},
  {"id":"s_work_han_thu_83_51","chapterId":"ch_work_han_thu_83","textTraditional":"〔四〕　師古曰：「以其繆舉人也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_83_52","chapterId":"ch_work_han_thu_83","textTraditional":"先是，宣帝時匈奴乖亂，五單于爭立，呼韓邪單于與郅支單于俱遣子入侍，漢兩受之。後呼韓邪單于身入稱臣朝見，郅支以為呼韓邪破弱降漢，不能自還，即西收右地。會漢發兵送呼韓邪單于，郅支由是遂西破呼偈、堅昆、丁令，〔一〕兼三國而都之。怨漢擁護呼韓邪而不助己，困辱漢使者江乃始等。初元四年，遣使奉獻，因求侍子，願為內附。漢議遣衛司馬谷吉送之。御史大夫貢禹、博士匡衡以為春秋之義「許夷狄者不壹而足」，〔二〕今郅支單于鄉化未（淳）〔醇〕，〔三〕所在絕遠，宜令使者送其子至塞而還。吉上書言：「中國與夷狄有羈（靡）〔縻〕不絕之義，今既養全其子十年，德澤甚厚，空絕而不送，近從塞還，示（捐棄）〔棄捐〕不畜，〔四〕使無鄉從之心。〔五〕棄前恩，立後怨，不便。議者見前江乃始無應敵之數，知勇俱困，以致恥辱，即豫為臣憂。臣幸得建彊漢之節，承明聖之詔，宣諭厚恩，不宜敢桀。〔六〕若懷禽獸，加無道於臣，則單于長嬰大罪，〔七〕必遁逃遠舍，不敢近邊。〔八〕沒一使以安百姓，國之計，臣之願也。願送至庭。」〔九〕上以示朝者，禹復爭，以為吉往必為國取悔生事，不可許。右將軍馮奉世以為可遣，上許焉。既至，郅支單于怒，竟殺吉等。自知負漢，又聞呼韓邪益彊，遂西奔康居。康居王以女妻郅支，郅支亦以女予康居王。康居甚尊敬郅支，欲倚其威以脅諸國。〔一０〕郅支數借兵擊烏孫，深入至赤谷城，殺略民人，（歐）〔驅〕畜產，〔一一〕烏孫不敢追，西邊空虛，不居者且千里。郅支單于自以大國，威名尊重，又乘勝驕，不為康居王禮，怒殺康居王女及貴人、人民數百，或支解投都賴水中。〔一二〕發民作城，日作五百人，二歲乃已。又遣使責闔蘇、大宛諸國歲遺，〔一三〕不敢不予。漢遣使三輩至康居求谷吉等死，〔一四〕郅支困辱使者，不肯奉詔，而因都護上書言：「居困厄，願歸計彊漢，遣子入侍。」〔一五〕其驕嫚如此。","sentenceOrder":52},
  {"id":"s_work_han_thu_83_53","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　服虔曰：「呼偈，小國名，在匈奴北。」師古曰：「偈音起厲反。令與零同。」","sentenceOrder":53},
  {"id":"s_work_han_thu_83_54","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「言（制節）〔節制〕之，不皆稱其所求也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_83_55","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　師古曰：「鄉讀曰嚮。不雜曰醇。醇，一也，厚也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_83_56","chapterId":"ch_work_han_thu_83","textTraditional":"〔四〕　師古曰：「畜謂愛養也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_83_57","chapterId":"ch_work_han_thu_83","textTraditional":"〔五〕　師古曰：「鄉讀曰嚮。嚮從謂向化而從命也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_83_58","chapterId":"ch_work_han_thu_83","textTraditional":"〔六〕　師古曰：「言郅支畏威，當不敢桀黠也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_83_59","chapterId":"ch_work_han_thu_83","textTraditional":"〔七〕　師古曰：「嬰猶帶也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_83_60","chapterId":"ch_work_han_thu_83","textTraditional":"〔八〕　師古曰：「舍，止也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_83_61","chapterId":"ch_work_han_thu_83","textTraditional":"〔九〕　師古曰：「單于庭。」","sentenceOrder":61},
  {"id":"s_work_han_thu_83_62","chapterId":"ch_work_han_thu_83","textTraditional":"〔一０〕師古曰：「倚音於綺反。」","sentenceOrder":62},
  {"id":"s_work_han_thu_83_63","chapterId":"ch_work_han_thu_83","textTraditional":"〔一一〕師古曰：「（歐）〔〈區夂〉〕與驅同。下皆類此。」","sentenceOrder":63},
  {"id":"s_work_han_thu_83_64","chapterId":"ch_work_han_thu_83","textTraditional":"〔一二〕師古曰：「支解謂〔解〕截其四支也。都賴，郅支水名。」","sentenceOrder":64},
  {"id":"s_work_han_thu_83_65","chapterId":"ch_work_han_thu_83","textTraditional":"〔一三〕師古曰：「胡廣云康居北可一千里有國名奄蔡，一名闔蘇。然則闔蘇即奄蔡也。歲遺者，年常所獻遺之物。遺音弋季反。」","sentenceOrder":65},
  {"id":"s_work_han_thu_83_66","chapterId":"ch_work_han_thu_83","textTraditional":"〔一四〕師古曰：「死，尸也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_83_67","chapterId":"ch_work_han_thu_83","textTraditional":"〔一五〕師古曰：「故為此言以調戲也。歸計謂歸附而受計策也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_83_68","chapterId":"ch_work_han_thu_83","textTraditional":"建昭三年，湯與延壽出西域。湯為人沈勇有大慮，多策謀，喜奇功，〔一〕每過城邑山川，常登望。既領外國，與延壽謀曰：「夷狄畏服大種，其天性也。西域本屬匈奴，今郅支單于威名遠聞，侵陵烏孫、大宛，常為康居畫計，欲降服之。如得此二國，北擊伊列，西取安息，南排月氏、山離烏弋，數年之間，城郭諸國危矣。〔二〕且其人剽悍，〔三〕好戰伐，數取勝，久畜之，必為西域患。郅支單于雖所在絕遠，蠻夷無金城強弩之守，如發屯田吏士，驅從烏孫眾兵〔四〕，直指其城下，彼亡則無所之，守則不足自保，〔五〕千載之功可一朝而成也。」延壽亦以為然，欲奏請之，湯曰：「國家與公卿議，大策非凡所見，事必不從。」〔六〕延壽猶與不聽。〔七〕會其久病，湯獨矯制發城郭諸國兵、車師戊己校尉屯田吏士。延壽聞之，驚起，欲止焉。湯怒，按劍叱延壽曰：「大眾已集會，豎子欲沮眾邪？」〔八〕延壽遂從之，部勒行陳，益置揚威、白虎、合騎之校，〔九〕漢兵胡兵合四萬餘人，延壽、湯上疏自劾奏矯制，陳言兵狀。","sentenceOrder":68},
  {"id":"s_work_han_thu_83_69","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「喜音許吏反。」","sentenceOrder":69},
  {"id":"s_work_han_thu_83_70","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　服虔曰：「山離烏弋不在（二）〔三〕十六國中，去中國二萬里。」師古曰：「謂西城國為城郭者，言不隨畜牧遷徙，以別於匈奴也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_83_71","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　師古曰：「剽，輕也。悍，勇也。剽音頻妙反，又音匹妙反。悍音胡幹反。」","sentenceOrder":71},
  {"id":"s_work_han_thu_83_72","chapterId":"ch_work_han_thu_83","textTraditional":"〔四〕　師古曰：「驅，帥之令隨從也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_83_73","chapterId":"ch_work_han_thu_83","textTraditional":"〔五〕　師古曰：「之，往也。保，安也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_83_74","chapterId":"ch_work_han_thu_83","textTraditional":"〔六〕　師古曰：「言凡庸之人，不能遠見，故壞其事也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_83_75","chapterId":"ch_work_han_thu_83","textTraditional":"〔七〕　師古曰：「與讀曰豫。」","sentenceOrder":75},
  {"id":"s_work_han_thu_83_76","chapterId":"ch_work_han_thu_83","textTraditional":"〔八〕　師古曰：「沮，止也，壞也，音才汝反。」","sentenceOrder":76},
  {"id":"s_work_han_thu_83_77","chapterId":"ch_work_han_thu_83","textTraditional":"〔九〕　張晏曰：「西域陳法之名也。」師古曰：「張說非也。一校則別為一部軍，故稱校耳。湯特新置此等諸校名，以為威聲也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_83_78","chapterId":"ch_work_han_thu_83","textTraditional":"即日引軍分行，別為六校，其三校從南道踰蔥領徑大宛，其三校都護自將，發溫宿國，從北道入赤谷，過烏孫，涉康居界，至闐池西。而康居副王抱闐將數千騎，寇赤谷城東，〔一〕殺略大昆彌千餘人，驅畜產甚多。從後與漢軍相及，頗寇盜後重。〔二〕湯縱胡兵擊之，殺四百六十人，得其所略民四百七十人，還付大昆彌，其馬牛羊以給軍食。又捕得抱闐貴人伊奴毒。","sentenceOrder":78},
  {"id":"s_work_han_thu_83_79","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　文穎曰：「闐音填。」","sentenceOrder":79},
  {"id":"s_work_han_thu_83_80","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「重謂輜重也，音直用反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_83_81","chapterId":"ch_work_han_thu_83","textTraditional":"入康居東界，令軍不得為寇。〔一〕間呼其貴人屠墨見之，〔二〕諭以威信，與飲盟遣去。徑引行，未至單于城可六十里，止營。復捕得康居貴人貝色子男開牟以為導。貝色子即屠墨母之弟，〔三〕皆怨單于，由是具知郅支情。","sentenceOrder":81},
  {"id":"s_work_han_thu_83_82","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「勿抄掠。」","sentenceOrder":82},
  {"id":"s_work_han_thu_83_83","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「間謂密呼也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_83_84","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　師古曰：「母之弟即謂舅也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_83_85","chapterId":"ch_work_han_thu_83","textTraditional":"明日引行，未至城三十里，止營。單于遣使問：「漢兵何以來？」應曰：「單于上書言居困阨，願歸計彊漢，身入朝見。天子哀閔單于棄大國，屈意康居，故使都護將軍來迎單于妻子，恐左右驚動，故未敢至城下。」使數往來相答報。延壽、湯因讓之：〔一〕「我為單于遠來，而至今無名王大人見將軍受事者，〔二〕何單于忽大計，失客主之禮也！〔三〕兵來道遠，人畜罷極，食度且盡，〔四〕恐無以自還，願單于與大臣審計策。」","sentenceOrder":85},
  {"id":"s_work_han_thu_83_86","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「讓，責也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_83_87","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「名王，諸王之貴者。受事，受教命而供事也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_83_88","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　師古曰：「忽，忘也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_83_89","chapterId":"ch_work_han_thu_83","textTraditional":"〔四〕　師古曰：「罷讀曰疲。度音大各反。」","sentenceOrder":89},
  {"id":"s_work_han_thu_83_90","chapterId":"ch_work_han_thu_83","textTraditional":"明日，前至郅支城都賴水上，離城三里，止營傅陳。〔一〕望見單于城上立五采幡織，〔二〕數百人披甲乘城，〔三〕又出百餘騎往來馳城下，步兵百餘人夾門魚鱗陳，〔四〕講習用兵。城上人更招漢軍曰「鬥來！」〔五〕百餘騎馳赴營，營皆張弩持滿指之，騎引卻。頗遣吏士射城門騎步兵，騎步兵皆入。延壽、湯令軍聞鼓音皆薄城下，〔六〕四面圍城，各有所守，穿塹，塞門戶，鹵楯為前，戟弩為後，卬射城中樓上人，〔七〕樓上人下走。土城外有重木城，從木城中射，頗殺傷外人。外人發薪燒木城。夜，數百騎欲出外，迎射殺之。","sentenceOrder":90},
  {"id":"s_work_han_thu_83_91","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「傅讀曰敷。敷，布也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_83_92","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「織讀曰幟，音式志反。」","sentenceOrder":92},
  {"id":"s_work_han_thu_83_93","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　師古曰：「乘謂登之備守也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_83_94","chapterId":"ch_work_han_thu_83","textTraditional":"〔四〕　師古曰：「言其相接次，形若魚鱗。」","sentenceOrder":94},
  {"id":"s_work_han_thu_83_95","chapterId":"ch_work_han_thu_83","textTraditional":"〔五〕　師古曰：「更，互也，音工行反。」","sentenceOrder":95},
  {"id":"s_work_han_thu_83_96","chapterId":"ch_work_han_thu_83","textTraditional":"〔六〕　師古曰：「薄，迫也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_83_97","chapterId":"ch_work_han_thu_83","textTraditional":"〔七〕　師古曰：「卬讀曰仰。」","sentenceOrder":97},
  {"id":"s_work_han_thu_83_98","chapterId":"ch_work_han_thu_83","textTraditional":"初，單于聞漢兵至，欲去，疑康居怨己，為漢內應，又聞烏孫諸國兵皆發，自以無所之。〔一〕郅支已出，復還，曰：「不如堅守。漢兵遠來，不能久攻。」單于乃被甲在樓上，諸閼氏夫人數十皆以弓射外人。外人射中單于鼻，諸夫人頗死。單于下騎，傳戰大內。〔二〕夜過半，木城穿，中人卻入土城，乘城呼。〔三〕時康居兵萬餘騎分為十餘處，四面環城，亦與相應和。〔四〕夜，數奔營，不利，輒卻。〔五〕平明，四面火起，吏士喜，大呼乘之，〔六〕鉦鼓聲動地。康居兵引卻。漢兵四面推鹵楯，並入土城中。單于男女百餘人走入大內。漢兵縱火，吏士爭入，單于被創死。軍候假丞杜勳斬單于首，得漢使節二及谷吉等所齎帛書。諸鹵獲以畀得者。〔七〕凡斬閼氏、太子、名王以下千五百一十八級，生虜百四十五人，降虜千餘人，賦予城郭諸國所發十五王。〔八〕","sentenceOrder":98},
  {"id":"s_work_han_thu_83_99","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「之，往也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_83_100","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「下騎謂下樓而騎馬也。傳戰，轉戰也。大內，單于之內室也。言且戰且行而入內室。」","sentenceOrder":100},
  {"id":"s_work_han_thu_83_101","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　師古曰：「乘，登也。呼音火故反。次下亦同。」","sentenceOrder":101},
  {"id":"s_work_han_thu_83_102","chapterId":"ch_work_han_thu_83","textTraditional":"〔四〕　師古曰：「環，繞也，音患。和音胡臥反。」","sentenceOrder":102},
  {"id":"s_work_han_thu_83_103","chapterId":"ch_work_han_thu_83","textTraditional":"〔五〕　師古曰：「犇，古奔字也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_83_104","chapterId":"ch_work_han_thu_83","textTraditional":"〔六〕　師古曰：「乘，逐也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_83_105","chapterId":"ch_work_han_thu_83","textTraditional":"〔七〕　師古曰：「畀，予也。各以與所得人。畀音必寐反。」","sentenceOrder":105},
  {"id":"s_work_han_thu_83_106","chapterId":"ch_work_han_thu_83","textTraditional":"〔八〕　師古曰：「賦謂班與之也。所發十五王，謂所發諸國之兵，共圍郅支王者也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_83_107","chapterId":"ch_work_han_thu_83","textTraditional":"於是延壽、湯上疏曰：「臣聞天下之大義，當混為一，〔一〕昔有唐虞，今有彊漢。匈奴呼韓邪單于已稱北藩，唯郅支單于叛逆，未伏其辜，大夏之西，以為彊漢不能臣也。〔二〕郅支單于慘毒行於民，大惡通于天。臣延壽、臣湯將義兵，行天誅，賴陛下神靈，陰陽並應，天氣精明，陷陳克敵，斬郅支首及名王以下。宜縣頭槁街蠻夷邸間，〔三〕以示萬里，明犯彊漢者，雖遠必誅。」事下有司。丞相匡衡、御史大夫繁延壽〔四〕以為「郅支及名王首更歷諸國，蠻夷莫不聞知。〔五〕月令春『掩骼埋胔』之時，〔六〕宜勿縣。」車騎將軍許嘉、右將軍王商以為「春秋夾谷之會，優施笑君，孔子誅之，〔七〕方盛夏，首足異門而出。宜縣十日乃埋之。」有詔將軍議是。","sentenceOrder":107},
  {"id":"s_work_han_thu_83_108","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「混，同也，音胡本反。」","sentenceOrder":108},
  {"id":"s_work_han_thu_83_109","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「謂漢為不能使郅支臣服也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_83_110","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　晉灼曰：「黃圖在長安城門內。」師古曰：「槁街，街名，蠻夷邸在此街也。邸，若今鴻臚客館也。崔浩以為槁當為橐，橐街即銅駝街也。此說失之。銅駝街在雒陽，西京無也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_83_111","chapterId":"ch_work_han_thu_83","textTraditional":"〔四〕　師古曰：「繁音蒲何反。」","sentenceOrder":111},
  {"id":"s_work_han_thu_83_112","chapterId":"ch_work_han_thu_83","textTraditional":"〔五〕　師古曰：「更音工衡反。」","sentenceOrder":112},
  {"id":"s_work_han_thu_83_113","chapterId":"ch_work_han_thu_83","textTraditional":"〔六〕　應劭曰：「禽獸之骨曰骼。骼，大也。鳥鼠之骨曰胔。胔，可惡也。」臣瓚曰：「枯骨曰骼，有肉曰胔。」師古曰：「瓚說是也。骼音工客反。胔音才賜反。」","sentenceOrder":113},
  {"id":"s_work_han_thu_83_114","chapterId":"ch_work_han_thu_83","textTraditional":"〔七〕　師古曰：「夾谷，地名，即祝其也。定十年『公會齊侯於夾谷，孔子攝相事，齊侯奏宮中之樂，俳優侏儒戲於前，孔子歷階而上曰：「匹夫侮諸侯者，罪應誅。」於是斬侏儒，首足異處，齊侯懼，有慚色。』施者，優人之名。夾音頰。」","sentenceOrder":114},
  {"id":"s_work_han_thu_83_115","chapterId":"ch_work_han_thu_83","textTraditional":"初，中書令石顯嘗欲以姊妻延壽，延壽不取。及丞相、御史亦惡其矯制，皆不與湯。〔一〕湯素貪，所鹵獲財物入塞多不法。〔二〕司隸校尉移書道上，繫吏士按驗之。湯上疏言：「臣與吏士共誅郅支單于，幸得禽滅，萬里振旅，〔三〕宜有使者迎勞道路。〔四〕今司隸反逆收繫按驗，是為郅支報讎也！」上立出吏士，令縣道具酒食以過軍。既至，論功，石顯、匡衡以為「延壽、湯擅興師矯制，幸得不誅，如復加爵土，則後奉使者爭欲乘危徼幸，生事於蠻夷，〔五〕為國招難，漸不可開。」元帝內嘉延壽、湯功，而重違衡、顯之議〔六〕，議久不決。","sentenceOrder":115},
  {"id":"s_work_han_thu_83_116","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「與猶許。」","sentenceOrder":116},
  {"id":"s_work_han_thu_83_117","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「不法者，私自取之，不依軍法。」","sentenceOrder":117},
  {"id":"s_work_han_thu_83_118","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　師古曰：「師入曰振旅。振，整也。旅，眾也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_83_119","chapterId":"ch_work_han_thu_83","textTraditional":"〔四〕　師古曰：「勞音力到反。」","sentenceOrder":119},
  {"id":"s_work_han_thu_83_120","chapterId":"ch_work_han_thu_83","textTraditional":"〔五〕　師古曰：「（若如）〔如，若〕也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_83_121","chapterId":"ch_work_han_thu_83","textTraditional":"〔六〕　師古曰：「重，難也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_83_122","chapterId":"ch_work_han_thu_83","textTraditional":"故宗正劉向上疏曰：「郅支單于囚殺使者吏士以百數，事暴揚外國，傷威毀重，群臣皆閔焉。〔一〕陛下赫然欲誅之，意未嘗有忘。西域都護延壽、副校尉湯承聖指，倚神靈，總百蠻之君，〈扌監〉城郭之兵，〔二〕出百死，入絕域，遂蹈康居，屠五重城，搴歙侯之旗，〔三〕斬郅支之首，縣旌萬里之外，揚威昆山之西，掃谷吉之恥，立昭明之功，萬夷慴伏，莫不懼震。〔四〕呼韓邪單于見郅支已誅，且喜且懼，鄉風馳義，稽首來賓，〔五〕願守北藩，累世稱臣。立千載之功，建萬世之安，群臣之勳莫大焉。昔周大夫方叔、吉甫為宣王誅獫狁而百蠻從，其詩曰：『嘽嘽焞焞，如霆如雷，顯允方叔，征伐獫狁，蠻荊來威。』〔六〕易曰：『有嘉折首，獲（非）〔匪〕其醜。〔七〕』言美誅首惡之人，而諸不順者皆來從也。今延壽、湯所誅震，雖易之折首、詩之雷霆不能及也。論大功者不錄小過，舉大美者不疵細瑕。司馬法曰『軍賞不踰月』，欲民速得為善之利也。蓋急武功，重用人也。吉甫之歸，周厚賜之，其詩曰：『吉甫燕喜，既多受祉，來歸自鎬，我行永久。』〔八〕千里之鎬猶以為遠，況萬里之外，其勤至矣！延壽、湯既未獲受祉之報，反屈捐命之功，久挫於刀筆之前，〔九〕非所以勸有功厲戎士也。昔齊桓公前有尊周之功，〔一０〕後有滅項之罪，〔一一〕君子以功覆過而為之諱行事。〔一二〕貳師將軍李廣利捐五萬之師，靡億萬之費，經四年之勞，〔一三〕而厪獲駿馬三十匹，〔一四〕雖斬宛王毌鼓之首，〔一五〕猶不足以復費〔一六〕，其私罪惡甚多。孝武以為萬里征伐，不錄其過，遂封拜兩侯、三卿、二千石百有餘人。今康居國彊於大宛，郅支之號重於宛王，殺使者罪甚於留馬，而延壽、湯不煩漢士，不費斗糧，比於貳師，功德百之。〔一七〕且常惠隨欲擊之烏孫，鄭吉迎自來之日逐，猶皆裂土受爵。故言威武勤勞則大於方叔、吉甫，列功覆過則優於齊桓、貳師，近事之功則高於安遠、長羅，〔一八〕而大功未著，小惡數布，臣竊痛之！宜以時解縣通籍，〔一九〕除過勿治，尊寵爵位，以勸有功。」","sentenceOrder":122},
  {"id":"s_work_han_thu_83_123","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「閔，病也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_83_124","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「〈扌監〉，總持之也。其字從手。」","sentenceOrder":124},
  {"id":"s_work_han_thu_83_125","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　師古曰：「搴，拔也，音騫。」","sentenceOrder":125},
  {"id":"s_work_han_thu_83_126","chapterId":"ch_work_han_thu_83","textTraditional":"〔四〕　師古曰：「慴，恐也，音之涉反。」","sentenceOrder":126},
  {"id":"s_work_han_thu_83_127","chapterId":"ch_work_han_thu_83","textTraditional":"〔五〕　師古曰：「馳義，慕義驅馳而來也。鄉讀曰嚮。」","sentenceOrder":127},
  {"id":"s_work_han_thu_83_128","chapterId":"ch_work_han_thu_83","textTraditional":"〔六〕　師古曰：「小雅采虯之詩也。嘽嘽，眾也。焞焞，盛也。言車徒既眾且盛，有如雷霆，故能克定獫狁而令荊土之蠻亦畏威而來也。嘽音他丹反。焞音他回反。」","sentenceOrder":128},
  {"id":"s_work_han_thu_83_129","chapterId":"ch_work_han_thu_83","textTraditional":"〔七〕　師古曰：「離上九爻辭也。嘉，善也。醜，類也。言王者出征，克勝斬首，多獲非類，故以為善。」","sentenceOrder":129},
  {"id":"s_work_han_thu_83_130","chapterId":"ch_work_han_thu_83","textTraditional":"〔八〕　師古曰：「小雅六月之詩也。鎬，地名，非豐鎬之鎬。此鎬及方皆在周之北。時獫狁侵鎬及方，至於涇陽。吉甫薄伐，自鎬而還。王以燕禮樂之，多受福賜，以其行役有功，日月長久故也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_83_131","chapterId":"ch_work_han_thu_83","textTraditional":"〔九〕　師古曰：「捐棄其軀命，言無所顧也。挫，屈折也。刀筆謂吏也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_83_132","chapterId":"ch_work_han_thu_83","textTraditional":"〔一０〕師古曰：「謂伐楚責苞茅，及會王太子于首止。」","sentenceOrder":132},
  {"id":"s_work_han_thu_83_133","chapterId":"ch_work_han_thu_83","textTraditional":"〔一一〕師古曰：「項，國名也。春秋僖十七年夏，滅項。公羊傳曰：『齊滅之也。不言齊，為桓公諱也。桓常有繼絕存亡之功，故君子為之諱。』」","sentenceOrder":133},
  {"id":"s_work_han_thu_83_134","chapterId":"ch_work_han_thu_83","textTraditional":"〔一二〕師古曰：「行事謂滅項之事也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_83_135","chapterId":"ch_work_han_thu_83","textTraditional":"〔一三〕師古曰：「靡，散也，音縻。」","sentenceOrder":135},
  {"id":"s_work_han_thu_83_136","chapterId":"ch_work_han_thu_83","textTraditional":"〔一四〕師古曰：「廑與僅同。僅，少也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_83_137","chapterId":"ch_work_han_thu_83","textTraditional":"〔一五〕師古曰：「西域傳作毌寡，而此云毌鼓，鼓寡聲相近，蓋戎狄之言不甚諦也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_83_138","chapterId":"ch_work_han_thu_83","textTraditional":"〔一六〕師古曰：「復，償也，音扶目反。」","sentenceOrder":138},
  {"id":"s_work_han_thu_83_139","chapterId":"ch_work_han_thu_83","textTraditional":"〔一七〕師古曰：「百倍勝之。」","sentenceOrder":139},
  {"id":"s_work_han_thu_83_140","chapterId":"ch_work_han_thu_83","textTraditional":"〔一八〕師古曰：「安遠侯鄭吉，長羅侯常惠也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_83_141","chapterId":"ch_work_han_thu_83","textTraditional":"〔一九〕孟康曰：「縣，罪未竟也，如言縣罰也。通籍，不禁止，令得出入也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_83_142","chapterId":"ch_work_han_thu_83","textTraditional":"於是天子下詔曰：「匈奴郅支單于背畔禮義，留殺漢使者、吏士，甚逆道理，朕豈忘之哉！所以優游而不征者，重動師眾，勞將帥，〔一〕故隱忍而未有云也。今延壽、湯睹便宜，乘時利，結城郭諸國，擅興師矯制而征之，賴天地宗廟之靈，誅討郅支單于，斬獲其首，及閼氏貴人名王以下千數。雖踰義干法，〔二〕內不煩一夫之役，不開府庫之臧，因敵之糧以贍軍用，立功萬里之外，威震百蠻，名顯四海。為國除殘，兵革之原息，邊竟得以安。〔三〕然猶不免死亡之患，罪當在於奉憲，朕甚閔之！其赦延壽、湯罪，勿治。」詔公卿議封焉。議者皆以為宜如軍法捕斬單于令。匡衡、石顯以為「郅支本亡逃失國，竊號絕域，非真單于。」元帝取安遠侯鄭吉故事，封千戶，衡、顯復爭。乃封延壽為義成侯，賜湯爵關內侯，食邑各三百戶，加賜黃金百斤。告上帝、宗廟，大赦天下。拜延壽為長水校尉，湯為射聲校尉。","sentenceOrder":142},
  {"id":"s_work_han_thu_83_143","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「重，難也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_83_144","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「干，犯也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_83_145","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　師古曰：「竟讀曰境。」","sentenceOrder":145},
  {"id":"s_work_han_thu_83_146","chapterId":"ch_work_han_thu_83","textTraditional":"延壽遷城門校尉，護軍都尉，薨於官。成帝初即位，丞相衡復奏「湯以吏二千石奉使，顓命蠻夷中，〔一〕不正身以先下，而盜所收康居財物，戒官屬曰絕域事不覆校。雖在赦前，不宜處位。」湯坐免。","sentenceOrder":146},
  {"id":"s_work_han_thu_83_147","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「顓與專同。」","sentenceOrder":147},
  {"id":"s_work_han_thu_83_148","chapterId":"ch_work_han_thu_83","textTraditional":"後湯上書言康居王侍子非王子也。　按驗，實王子也。湯下獄當死。太中大夫谷永上疏訟湯曰：「臣聞楚有子玉得臣，文公為之仄席而坐；〔一〕趙有廉頗、馬服，彊秦不敢窺兵井陘；〔二〕近漢有郅都、魏尚，匈奴不敢南鄉沙幕。〔三〕由是言之，戰克之將，國之爪牙，不可不重也。蓋『君子聞鼓鼙之聲，則思將率之臣』。〔四〕竊見關內侯陳湯，前使副西域都護，忿郅支之無道，閔王誅之不加〔五〕，策慮愊億，義勇奮發，〔六〕卒興師奔逝，橫厲烏孫，踰集都賴，〔七〕屠三重城，斬郅支首，報十年之逋誅，雪邊吏之宿恥，〔八〕威震百蠻，武暢西海，漢元以來，征伐方外之將，未嘗有也。今湯坐言事非是，幽囚久繫，歷時不決，執憲之吏欲致之大辟。昔白起為秦將，南拔郢都，北阬趙括，以纖介之過，賜死杜郵，〔九〕秦民憐之，莫不隕涕。今湯親秉鉞，席卷喋血萬里之外，〔一０〕薦功（宗）〔祖〕廟，告類上帝，〔一一〕介冑之士靡不慕義。以言事為罪，無赫赫之惡。周書曰：『記人之功，忘人之過，宜為君者也。』〔一二〕夫犬馬有勞於人，尚加帷蓋之報，〔一三〕況國之功臣者哉！竊恐陛下忽於鼓鼙之聲，不察周書之意，而忘帷蓋之施，庸臣遇湯，卒從吏議，〔一四〕使百姓介然有秦民之恨，〔一五〕非所以厲死難之臣也。」書奏，天子出湯，奪爵為士伍。","sentenceOrder":148},
  {"id":"s_work_han_thu_83_149","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「子玉，楚大夫也，得臣其名也。春秋僖二十八年，子玉帥師與晉文公戰于城濮，楚師敗績。晉師三日館穀，而文公猶有憂色，曰：『得臣猶在，憂未歇也。』及楚殺子玉，公喜而後可知也。禮記曰『有憂者仄席而坐』，蓋自貶之。仄，古側字也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_83_150","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「廉頗，趙將也。馬服君趙屠亦趙將也。井陘之口，趙之西界山險道也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_83_151","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":151},
  {"id":"s_work_han_thu_83_152","chapterId":"ch_work_han_thu_83","textTraditional":"〔四〕　師古曰：「禮之樂記曰『鼓鼙之聲讙，讙以立動，動以進眾。君子聽鼓鼙之聲，則思將率之臣』也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_83_153","chapterId":"ch_work_han_thu_83","textTraditional":"〔五〕　師古曰：「閔，憂也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_83_154","chapterId":"ch_work_han_thu_83","textTraditional":"〔六〕　師古曰：「愊億，憤怒之貌也。愊音皮逼反。」","sentenceOrder":154},
  {"id":"s_work_han_thu_83_155","chapterId":"ch_work_han_thu_83","textTraditional":"〔七〕　如淳曰：「踰，遠也。遠集郅支都賴水上也。」師古曰：「卒讀曰猝。厲，度也。踰讀曰遙。」","sentenceOrder":155},
  {"id":"s_work_han_thu_83_156","chapterId":"ch_work_han_thu_83","textTraditional":"〔八〕　師古曰：「逋，亡也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_83_157","chapterId":"ch_work_han_thu_83","textTraditional":"〔九〕　師古曰：「地名也，在咸陽西也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_83_158","chapterId":"ch_work_han_thu_83","textTraditional":"〔一０〕師古曰：「如席之卷。言其疾也。喋血，解在文紀。」","sentenceOrder":158},
  {"id":"s_work_han_thu_83_159","chapterId":"ch_work_han_thu_83","textTraditional":"〔一一〕張晏曰：「謂以所征之國事類告天也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_83_160","chapterId":"ch_work_han_thu_83","textTraditional":"〔一二〕師古曰：「尚書之外逸書也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_83_161","chapterId":"ch_work_han_thu_83","textTraditional":"〔一三〕師古曰：「禮記稱孔子云：『敝帷弗棄，為薶馬也；敝蓋弗棄，為薶狗也。』」","sentenceOrder":161},
  {"id":"s_work_han_thu_83_162","chapterId":"ch_work_han_thu_83","textTraditional":"〔一四〕師古曰：「以庸臣之禮待遇之也。卒，終也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_83_163","chapterId":"ch_work_han_thu_83","textTraditional":"〔一五〕師古曰：「介然猶耿耿。」","sentenceOrder":163},
  {"id":"s_work_han_thu_83_164","chapterId":"ch_work_han_thu_83","textTraditional":"後數歲，西域都護段會宗為烏孫兵所圍，驛騎上書，願發城郭敦煌兵以自救。〔一〕丞相王商、大將軍王鳳及百僚議數日不決。鳳言「湯多籌策，習外國事，可問。」上召湯見宣室。湯擊郅支時中寒病，兩臂不詘申。湯入見，有詔毋拜，示以會宗奏。湯辭謝，曰：「將相九卿皆賢材通明，小臣罷癃，不足以策大事。」〔二〕上曰：「國家有急，君其毋讓。」對曰：「臣以為此必無可憂也。」上曰：「何以言之？」湯曰：「夫胡兵五而當漢兵一，何者？兵刃朴鈍，弓弩不利。今聞頗得漢巧，然猶三而當一。又兵法曰『客倍而主人半然後敵』，今圍會宗者人眾不足以勝會宗，唯陛下勿憂！且兵輕行五十里，重行三十里，今會宗欲發城郭敦煌，歷時乃至，所謂報讎之兵，非救急之用也。」上曰：「柰何？其解可必乎？度何時解？」〔三〕湯知烏孫瓦合，不能久攻，〔四〕故事不過數日，〔五〕因對曰：「已解矣！」詘指計其日，曰：「不出五日，當有吉語聞。」〔六〕居四日，軍書到，言已解。大將軍鳳奏以為從事中郎，莫府事壹決於湯。湯明法令，善因事為勢，納說多從。常受人金錢作章奏，卒以此敗。","sentenceOrder":164},
  {"id":"s_work_han_thu_83_165","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「西域城郭諸國及敦煌兵也。」","sentenceOrder":165},
  {"id":"s_work_han_thu_83_166","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「罷讀曰疲。」","sentenceOrder":166},
  {"id":"s_work_han_thu_83_167","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　師古曰：「度音徒各反。」","sentenceOrder":167},
  {"id":"s_work_han_thu_83_168","chapterId":"ch_work_han_thu_83","textTraditional":"〔四〕　師古曰：「瓦合謂碎瓦之雜居不齊同。」","sentenceOrder":168},
  {"id":"s_work_han_thu_83_169","chapterId":"ch_work_han_thu_83","textTraditional":"〔五〕　師古曰：「故事謂以舊事測之。」","sentenceOrder":169},
  {"id":"s_work_han_thu_83_170","chapterId":"ch_work_han_thu_83","textTraditional":"〔六〕　師古曰：「吉，善也。善謂兵解之事。」","sentenceOrder":170},
  {"id":"s_work_han_thu_83_171","chapterId":"ch_work_han_thu_83","textTraditional":"初，湯與將作大匠解萬年相善。自元帝時，渭陵不復徙民起邑。成帝起初陵，數年後，樂霸陵曲亭南，更營之。萬年與湯議，以為「武帝時工楊光以所作數可意〔一〕自致將作大匠，及大司農中丞耿壽昌造杜陵賜爵關內侯，將作大匠乘馬延年以勞苦秩中二千石；〔二〕今作初陵而營起邑居，成大功，萬年亦當蒙重賞。子公妻家在長安，兒子生長長安，不樂東方，宜求徙，可得賜田宅，俱善。」湯心利之，即上封事言：「初陵，京師之地，最為肥美，可立一縣。天下民不徙諸陵三十餘歲矣，關東富人益眾，多規良田，役使貧民，〔三〕可徙初陵，以彊京師，衰弱諸侯，又使中家以下得均貧富。湯願與妻子家屬徙初陵，為天下先。」於是天子從其計，果起昌陵邑，後徙內郡國民。萬年自詭三年可成，〔四〕後卒不就，〔五〕群臣多言其不便者。下有司議，皆曰：「昌陵因卑為高，積土為山，度便房猶在平地上，〔六〕客土之中不保幽冥之靈，淺外不固，卒徒工庸以鉅萬數，至然脂火夜作，〔七〕取土東山，且與穀同賈。〔八〕作治數年，天下遍被其勞，國家罷敝，府臧空虛，〔九〕下至眾庶，熬熬苦之〔一０〕。故陵因天性，據真土，處勢高敞，旁近祖考，前又已有十年功緒，〔一一〕宜還復故陵，勿徙民。」上乃下詔罷昌陵，語在成紀。丞相御史請廢昌陵邑中室，〔一二〕奏未下，人以問湯：「第宅不（得徹）〔徹，得〕毋復發徙？」〔一三〕湯曰：「縣官且順聽群臣言，猶且復發徙之也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_83_172","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「可天子之意。」","sentenceOrder":172},
  {"id":"s_work_han_thu_83_173","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「姓乘馬，名延年。乘音食孕反。」","sentenceOrder":173},
  {"id":"s_work_han_thu_83_174","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　師古曰：「規，畫也，自占為疆界也。」","sentenceOrder":174},
  {"id":"s_work_han_thu_83_175","chapterId":"ch_work_han_thu_83","textTraditional":"〔四〕　師古曰：「詭，責也，自以為憂責也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_83_176","chapterId":"ch_work_han_thu_83","textTraditional":"〔五〕　師古曰：「卒，終也。就亦成也。」","sentenceOrder":176},
  {"id":"s_work_han_thu_83_177","chapterId":"ch_work_han_thu_83","textTraditional":"〔六〕　師古曰：「度音徒各反。」","sentenceOrder":177},
  {"id":"s_work_han_thu_83_178","chapterId":"ch_work_han_thu_83","textTraditional":"〔七〕　師古曰：「{難灬}，古然字也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_83_179","chapterId":"ch_work_han_thu_83","textTraditional":"〔八〕　師古曰：「賈讀曰價。」","sentenceOrder":179},
  {"id":"s_work_han_thu_83_180","chapterId":"ch_work_han_thu_83","textTraditional":"〔九〕　師古曰：「罷讀曰疲。」","sentenceOrder":180},
  {"id":"s_work_han_thu_83_181","chapterId":"ch_work_han_thu_83","textTraditional":"〔一０〕師古曰：「熬熬，眾愁聲。」","sentenceOrder":181},
  {"id":"s_work_han_thu_83_182","chapterId":"ch_work_han_thu_83","textTraditional":"〔一一〕師古曰：「緒謂端次也。」","sentenceOrder":182},
  {"id":"s_work_han_thu_83_183","chapterId":"ch_work_han_thu_83","textTraditional":"〔一二〕師古曰：「徙人新所起室居。」","sentenceOrder":183},
  {"id":"s_work_han_thu_83_184","chapterId":"ch_work_han_thu_83","textTraditional":"〔一三〕師古曰：「問其不被發徹，更移徙邪？」","sentenceOrder":184},
  {"id":"s_work_han_thu_83_185","chapterId":"ch_work_han_thu_83","textTraditional":"時成都侯商新為大司馬衛將軍輔政，素不善湯。商聞此語，白湯惑眾，下獄治，按驗諸所犯。湯前為騎都尉王莽上書言：「父早死，（犯）〔獨〕不封，母明君共養皇太后，尤勞苦，〔一〕宜封竟為新都侯。」後皇太后同母弟苟參為水衡都尉，死，子伋為侍中，〔二〕參妻欲為伋求封，湯受其金五十斤，許為求比上奏。〔三〕弘農太守張匡坐臧百萬以上，狡猾不道，有詔即訊，〔四〕恐下獄，使人報湯。湯為訟罪，得踰冬月，許謝錢二百萬，皆此類也。事在赦前。後東萊郡黑龍冬出，人以問湯，湯曰：「是所謂玄門開。微行數出，出入不時，故龍以非時出也。」又言當復發徙，傳相語者十餘人。丞相御史奏「湯惑眾不道，妄稱詐歸異於上，非所宜言，大不敬。」廷尉增壽議，以為「不道無正法，〔五〕以所犯劇易為罪，〔六〕臣下（丞）〔承〕用失其中，故移獄廷尉，〔七〕無比者先以聞，〔八〕所以正刑罰，重人命也。明主哀憫百姓，下制書罷昌陵勿徙吏民，已申布。湯妄以意相謂且復發徙，雖頗驚動，所流行者少，百姓不為變，不可謂惑眾。湯稱詐，虛設不然之事，非所宜言，大不敬也。」制曰：「廷尉增壽當是。〔九〕湯前有討郅支單于功，其免湯為庶人，徙邊。」又曰：「故將作大匠萬年佞邪不忠，妄為巧詐，多賦斂，煩繇役，興卒暴之作，〔一０〕卒徒蒙辜，死者連屬，〔一一〕毒流眾庶，海內怨望。雖蒙赦令，不宜居京師。」於是湯與萬年俱徙敦煌。","sentenceOrder":185},
  {"id":"s_work_han_thu_83_186","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「莽傳言莽母渠，今此云明君。則明君者字也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_83_187","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「伋音汲。」","sentenceOrder":187},
  {"id":"s_work_han_thu_83_188","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　師古曰：「比，例也，音必寐反。」","sentenceOrder":188},
  {"id":"s_work_han_thu_83_189","chapterId":"ch_work_han_thu_83","textTraditional":"〔四〕　師古曰：「就其所居考問之。」","sentenceOrder":189},
  {"id":"s_work_han_thu_83_190","chapterId":"ch_work_han_thu_83","textTraditional":"〔五〕　晉灼曰：「增壽，姓趙也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_83_191","chapterId":"ch_work_han_thu_83","textTraditional":"〔六〕　師古曰：「易音弋豉反。」","sentenceOrder":191},
  {"id":"s_work_han_thu_83_192","chapterId":"ch_work_han_thu_83","textTraditional":"〔七〕　如淳曰：「如今讞罪輕重。」","sentenceOrder":192},
  {"id":"s_work_han_thu_83_193","chapterId":"ch_work_han_thu_83","textTraditional":"〔八〕　師古曰：「比謂相比附也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_83_194","chapterId":"ch_work_han_thu_83","textTraditional":"〔九〕　師古曰：「當謂處正其罪也。」","sentenceOrder":194},
  {"id":"s_work_han_thu_83_195","chapterId":"ch_work_han_thu_83","textTraditional":"〔一０〕師古曰：「卒讀曰猝。」","sentenceOrder":195},
  {"id":"s_work_han_thu_83_196","chapterId":"ch_work_han_thu_83","textTraditional":"〔一一〕師古曰：「蒙，被也，屬音之欲反。」","sentenceOrder":196},
  {"id":"s_work_han_thu_83_197","chapterId":"ch_work_han_thu_83","textTraditional":"久之，敦煌太守奏「湯前親誅郅支單于，威行外國，不宜近邊塞。」詔徙安定。","sentenceOrder":197},
  {"id":"s_work_han_thu_83_198","chapterId":"ch_work_han_thu_83","textTraditional":"議郎耿育上書言便宜，因冤訟湯曰：「延壽、湯為聖漢揚鉤深致遠之威，雪國家累年之恥，討絕域不羈之君，係萬里難制之虜，豈有比哉！先帝嘉之，仍下明詔，宣著其功，〔一〕改年垂曆，傳之無窮。〔二〕應是，南郡獻白虎，邊陲無警備。會先帝寢疾，然猶垂意不忘，數使尚書責問丞相，趣立其功。〔三〕獨丞相匡衡排而不予，封延壽、湯數百戶，此功臣戰士所以失望也。孝成皇帝承建業之基，乘征伐之威，兵革不動，國家無事，而大臣傾邪，讒佞在朝，曾不深惟本末之難，以防未然之戒，欲專主威，排妒有功，使湯塊然〔四〕被冤拘囚，不能自明，卒以無罪，老棄敦煌，正當西域通道，令威名折衝之臣旋踵及身，復為郅支遺虜所笑，誠可悲也！至今奉使外蠻者，未嘗不陳郅支之誅以揚漢國之盛。夫援人之功以懼敵，棄人之身以快讒，〔五〕豈不痛哉！且安不忘危，盛必慮衰，今國家素無文帝累年節儉富饒之畜，〔六〕又無武帝薦延〔七〕梟俊禽敵之臣，獨有一陳湯耳！〔八〕假使異世不及陛下，尚望國家追錄其功，封表其墓，以勸後進也。湯幸得身當聖世，功曾未久，反聽邪臣鞭逐斥遠，使亡逃分竄，死無處所。〔九〕遠覽之士，莫不計度，〔一０〕以為湯功累世不可及，而湯過人情所有，〔一一〕湯尚如此，雖復破絕筋骨，暴露形骸，猶復制於脣舌，為嫉妒之臣所係虜耳。此臣所以為國家尤戚戚也。」書奏，天子還湯，卒於長安。","sentenceOrder":198},
  {"id":"s_work_han_thu_83_199","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「仍，頻也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_83_200","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「謂改年為竟寧也。不以此事，蓋當其年，上書者附著耳。」","sentenceOrder":200},
  {"id":"s_work_han_thu_83_201","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　師古曰：「趣讀曰促。」","sentenceOrder":201},
  {"id":"s_work_han_thu_83_202","chapterId":"ch_work_han_thu_83","textTraditional":"〔四〕　師古曰：「塊然，獨處之意，如土塊也。音口內反。」","sentenceOrder":202},
  {"id":"s_work_han_thu_83_203","chapterId":"ch_work_han_thu_83","textTraditional":"〔五〕　師古曰：「援，引也，音爰。」","sentenceOrder":203},
  {"id":"s_work_han_thu_83_204","chapterId":"ch_work_han_thu_83","textTraditional":"〔六〕　師古曰：「畜讀曰蓄，謂府庫也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_83_205","chapterId":"ch_work_han_thu_83","textTraditional":"〔七〕　如淳曰：「薦延，使群臣薦士而延納之。」","sentenceOrder":205},
  {"id":"s_work_han_thu_83_206","chapterId":"ch_work_han_thu_83","textTraditional":"〔八〕　師古曰：「梟謂斬其首而縣之也。俊謂敵之魁率，郅支是也。春秋左氏傳曰『得俊曰克』。」","sentenceOrder":206},
  {"id":"s_work_han_thu_83_207","chapterId":"ch_work_han_thu_83","textTraditional":"〔九〕　師古曰：「分謂散離也。虞書舜典曰『分北三苗』。」","sentenceOrder":207},
  {"id":"s_work_han_thu_83_208","chapterId":"ch_work_han_thu_83","textTraditional":"〔一０〕師古曰：「度音大各反。」","sentenceOrder":208},
  {"id":"s_work_han_thu_83_209","chapterId":"ch_work_han_thu_83","textTraditional":"〔一一〕師古曰：「言湯所犯之罪過，人情共有此事耳，非特詭異深可誅責也。」","sentenceOrder":209},
  {"id":"s_work_han_thu_83_210","chapterId":"ch_work_han_thu_83","textTraditional":"死後數年，王莽為安漢公秉政，既內德湯舊恩，又欲諂皇太后，以討郅支功尊元帝廟稱高宗。以湯、延壽前功大賞薄，及候丞杜勳不賞，乃益封延壽孫遷千六百戶，追諡湯曰破胡壯侯，封湯子馮為破胡侯，勳為討狄侯。","sentenceOrder":210},
  {"id":"s_work_han_thu_83_211","chapterId":"ch_work_han_thu_83","textTraditional":"段會宗字子松，天水上邽人也。竟寧中，以杜陵令五府舉為西域都護、騎都尉光祿大夫，西域敬其威信。三歲，更盡還，〔一〕拜為沛郡太守。以單于當朝，徙為雁門太守。數年，坐法免。西域諸國上書願得會宗，陽朔中復為都護。","sentenceOrder":211},
  {"id":"s_work_han_thu_83_212","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　如淳曰：「邊吏三歲一更，下言終更皆是也。」師古曰：「更，工衡反。其下並同。」","sentenceOrder":212},
  {"id":"s_work_han_thu_83_213","chapterId":"ch_work_han_thu_83","textTraditional":"會宗為人好大節，矜功名，與谷永相友善。谷永閔其老復遠出，予書戒曰：「足下以柔遠之令德，復典都護之重職，〔一〕甚休甚休！〔二〕若子之材，可優遊都城而取卿相，何必勒功昆山之仄，總領百蠻，懷柔殊俗？子之所長，愚無以喻。〔三〕雖然，朋友以言贈行，敢不略意。〔四〕方今漢德隆盛，遠人賓服，傅、鄭、甘、陳之功沒齒不可復見，願吾子因循舊貫，毋求奇功，〔五〕終更亟還，亦足以復雁門之踦。〔六〕萬里之外以身為本。願詳思愚言。」","sentenceOrder":213},
  {"id":"s_work_han_thu_83_214","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「柔，安也。柔遠，言能安遠人。虞書舜典曰『柔遠能邇』。」","sentenceOrder":214},
  {"id":"s_work_han_thu_83_215","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「休，美也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_83_216","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　師古曰：「言子思慮深長，當不待己曉告也。」","sentenceOrder":216},
  {"id":"s_work_han_thu_83_217","chapterId":"ch_work_han_thu_83","textTraditional":"〔四〕　師古曰：「贈行謂將別相贈也。略意，略陳本意也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_83_218","chapterId":"ch_work_han_thu_83","textTraditional":"〔五〕　師古曰：「貫，事也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_83_219","chapterId":"ch_work_han_thu_83","textTraditional":"〔六〕　應劭曰：「踦，隻也。會宗從沛郡下為雁門，又坐法免，為踦隻不偶也。」師古曰：「亟，急也。復猶補也。亟音居力反。踦音居宜反。」","sentenceOrder":219},
  {"id":"s_work_han_thu_83_220","chapterId":"ch_work_han_thu_83","textTraditional":"會宗既出。諸國遣子弟郊迎。小昆彌安日前為會宗所立，德之，〔一〕欲往謁，諸翕侯止不聽，遂至龜茲謁。城郭甚親附。〔二〕康居太子保蘇匿率眾萬餘人欲降，會宗奏狀，漢遣衛司馬逢迎。〔三〕會宗發戊己校尉兵隨司馬受降。司馬畏其眾，欲令降者皆自縛，保蘇匿怨望，舉眾亡去。會宗更盡還，以擅發戊己校尉之兵乏興，有詔贖論。拜為金城太守，以病免。","sentenceOrder":220},
  {"id":"s_work_han_thu_83_221","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「懷會宗之恩德也。」","sentenceOrder":221},
  {"id":"s_work_han_thu_83_222","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　師古曰：「謂城郭諸國。」","sentenceOrder":222},
  {"id":"s_work_han_thu_83_223","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　師古曰：「迎之於道，隨所到而逢之，故曰逢迎也。」","sentenceOrder":223},
  {"id":"s_work_han_thu_83_224","chapterId":"ch_work_han_thu_83","textTraditional":"歲餘，小昆彌為國民所殺，諸翕侯大亂。徵會宗為左曹中郎將光祿大夫，使安輯烏孫，〔一〕立小昆彌兄末振將，〔二〕定其國而還。","sentenceOrder":224},
  {"id":"s_work_han_thu_83_225","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「輯與集同。」","sentenceOrder":225},
  {"id":"s_work_han_thu_83_226","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　服虔曰：「人姓名也。」師古曰：「其名也。昆彌之兄不可別舉姓也。」","sentenceOrder":226},
  {"id":"s_work_han_thu_83_227","chapterId":"ch_work_han_thu_83","textTraditional":"明年，末振將殺大昆彌，會病死，漢恨誅不加。元延中，復遣會宗發戊己校尉諸國兵，即誅末振將太子番丘。〔一〕會宗恐大兵入烏孫，驚番丘，亡逃不可得，即留所發兵墊婁地，〔二〕選精兵三十弩，〔三〕徑至昆彌所在，召番丘，責以「末振將骨肉相殺，殺漢公主子孫，未伏誅而死，使者受詔誅番丘。」即手劍擊殺番丘。官屬以下驚恐，馳歸。小昆彌烏犁靡者，末振將兄子也，勒兵數千騎圍會宗，會宗為言來誅之意：「今圍守殺我，如取漢牛一毛耳。宛王郅支頭縣槁街，烏孫所知也。」昆彌以下服，曰：「末振將負漢，誅其子可也，獨不可告我，令飲食之邪？」〔四〕會宗曰：「豫告昆彌，逃匿之，為大罪。即飲食以付我，傷骨肉恩，故不先告。」昆彌以下號泣罷去。會宗還奏事，公卿議會宗權得便宜，以輕兵深入烏孫，即誅番丘，〔五〕宣明國威，宜加重賞。天子賜會宗爵關內侯，黃金百斤。","sentenceOrder":227},
  {"id":"s_work_han_thu_83_228","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「番音步安反。」","sentenceOrder":228},
  {"id":"s_work_han_thu_83_229","chapterId":"ch_work_han_thu_83","textTraditional":"〔二〕　服虔曰：「墊音墊阨之墊。」鄭氏曰：「婁音羸。」師古曰：「墊音丁念反。婁音樓。」","sentenceOrder":229},
  {"id":"s_work_han_thu_83_230","chapterId":"ch_work_han_thu_83","textTraditional":"〔三〕　李奇曰：「三十人，人持一弩。」","sentenceOrder":230},
  {"id":"s_work_han_thu_83_231","chapterId":"ch_work_han_thu_83","textTraditional":"〔四〕　師古曰：「飲音於禁反。食讀曰飤。次下亦同。」","sentenceOrder":231},
  {"id":"s_work_han_thu_83_232","chapterId":"ch_work_han_thu_83","textTraditional":"〔五〕　師古曰：「即，就也。」","sentenceOrder":232},
  {"id":"s_work_han_thu_83_233","chapterId":"ch_work_han_thu_83","textTraditional":"是時，小昆彌季父卑爰疐〔一〕擁眾欲害昆彌，漢復遣會宗使安輯，與都護孫建并力。明年，會宗病死烏孫中，年七十五矣，城郭諸國為發喪立祠焉。","sentenceOrder":233},
  {"id":"s_work_han_thu_83_234","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「疐音竹二反。」","sentenceOrder":234},
  {"id":"s_work_han_thu_83_235","chapterId":"ch_work_han_thu_83","textTraditional":"贊曰：自元狩之際，張騫始通西域，至于地節，鄭吉建都護之號，訖王莽世，凡十八人，皆以勇略選，然其有功跡者具此。廉褒以恩信稱，郭舜以廉平著，孫建用威重顯，其餘無稱焉。陳湯儻〈蕩，去氵〉，不自收斂，〔一〕卒用困窮，議者閔之，故備列云。","sentenceOrder":235},
  {"id":"s_work_han_thu_83_236","chapterId":"ch_work_han_thu_83","textTraditional":"〔一〕　師古曰：「儻〈蕩，去氵〉，無行檢也。〈蕩，去氵〉音蕩。」","sentenceOrder":236},
  {"id":"s_work_han_thu_83_237","chapterId":"ch_work_han_thu_83","textTraditional":"校勘記","sentenceOrder":237},
  {"id":"s_work_han_thu_83_238","chapterId":"ch_work_han_thu_83","textTraditional":"三００三頁　三行　（間）〔言〕為匈奴之間（為）〔而〕候伺。　景祐、殿本「間」作「言」，「為」作「而」。","sentenceOrder":238},
  {"id":"s_work_han_thu_83_239","chapterId":"ch_work_han_thu_83","textTraditional":"三００七頁　六行　投石，應（劭）〔說〕是也。　景祐、殿本都作「說」，此誤。","sentenceOrder":239},
  {"id":"s_work_han_thu_83_240","chapterId":"ch_work_han_thu_83","textTraditional":"三００七頁　七行　今人猶（言）〔有〕拔爪之戲，　景祐、殿本都作「有」，此誤。","sentenceOrder":240},
  {"id":"s_work_han_thu_83_241","chapterId":"ch_work_han_thu_83","textTraditional":"三００七頁一二行　坐削（二百戶）〔戶二百〕，　景祐、殿本都作「戶二百」。","sentenceOrder":241},
  {"id":"s_work_han_thu_83_242","chapterId":"ch_work_han_thu_83","textTraditional":"三００八頁一０行　今郅支單于鄉化未（淳）〔醇〕，　景祐、殿本都作「醇」。王先謙說「淳」字誤。","sentenceOrder":242},
  {"id":"s_work_han_thu_83_243","chapterId":"ch_work_han_thu_83","textTraditional":"三００八頁一一行　中國與夷狄有羈（靡）〔縻〕不絕之義，　景祐、殿本都作「縻」。王先謙說作「縻」是。","sentenceOrder":243},
  {"id":"s_work_han_thu_83_244","chapterId":"ch_work_han_thu_83","textTraditional":"三００八頁一二行　示（捐棄）〔棄捐〕不畜，　景祐、殿本都作「棄捐」。","sentenceOrder":244},
  {"id":"s_work_han_thu_83_245","chapterId":"ch_work_han_thu_83","textTraditional":"三００九頁　四行　殺略民人，（歐）〔驅〕畜產，　景祐、殿、局本都作「驅」，注同。","sentenceOrder":245},
  {"id":"s_work_han_thu_83_246","chapterId":"ch_work_han_thu_83","textTraditional":"三００九頁一０行　言（制節）〔節制〕之，　景祐、殿本都作「節制」。","sentenceOrder":246},
  {"id":"s_work_han_thu_83_247","chapterId":"ch_work_han_thu_83","textTraditional":"三０一０頁　四行　支解謂〔解〕截其四支也。　景祐、殿本有「解」字。","sentenceOrder":247},
  {"id":"s_work_han_thu_83_248","chapterId":"ch_work_han_thu_83","textTraditional":"三０一一頁　四行　山離烏弋不在（二）〔三〕十六國中，　景祐、殿、局本都作「三」。","sentenceOrder":248},
  {"id":"s_work_han_thu_83_249","chapterId":"ch_work_han_thu_83","textTraditional":"三０一六頁一六行　（若如）〔如，若〕也。　景祐、殿、局本都作「如若」，此誤倒。","sentenceOrder":249},
  {"id":"s_work_han_thu_83_250","chapterId":"ch_work_han_thu_83","textTraditional":"三０一七頁　八行　獲（非）〔匪〕其醜。　景祐、殿本都作「匪」，通鑑、易今本並同。","sentenceOrder":250},
  {"id":"s_work_han_thu_83_251","chapterId":"ch_work_han_thu_83","textTraditional":"三０二一頁　六行　薦功（宗）〔祖〕廟，　景祐、殿本都作「祖」。","sentenceOrder":251},
  {"id":"s_work_han_thu_83_252","chapterId":"ch_work_han_thu_83","textTraditional":"三０二四頁一一行　第宅不（得徹）〔徹，得〕毋復發徙？　景祐、殿、局本都作「徹得」。王文彬說此誤倒。","sentenceOrder":252},
  {"id":"s_work_han_thu_83_253","chapterId":"ch_work_han_thu_83","textTraditional":"三０二五頁一二行　父早死，（犯）〔獨〕不封，　景祐、殿、局本都作「獨」。","sentenceOrder":253},
  {"id":"s_work_han_thu_83_254","chapterId":"ch_work_han_thu_83","textTraditional":"三０二六頁　二行　臣下（丞）〔承〕用失其中，　景祐、殿、局本都作「承」。","sentenceOrder":254},
  {"id":"s_work_han_thu_84_1","chapterId":"ch_work_han_thu_84","textTraditional":"雋不疑字曼倩，勃海人也。〔一〕治春秋，為郡文學，進退必以禮，名聞州郡。","sentenceOrder":1},
  {"id":"s_work_han_thu_84_2","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「雋音字袞反，又辭袞反。」","sentenceOrder":2},
  {"id":"s_work_han_thu_84_3","chapterId":"ch_work_han_thu_84","textTraditional":"武帝末，郡國盜賊群起，暴勝之為直指使者，衣繡衣，持斧，逐捕盜賊，督課郡國，〔一〕東至海，以軍興誅不從命者，〔二〕威振州郡。勝之素聞不疑賢，至勃海，遣吏請與相見。不疑冠進賢冠，帶櫑具劍，〔三〕佩環玦，〔四〕褒衣博帶，〔五〕盛服至門上謁〔六〕。門下欲使解劍，不疑曰：「劍者君子武備，所以衛身，不可解。請退。」吏白勝之。勝之開閤延請，望見不疑容貌尊嚴，衣冠甚偉，勝之躧履起迎。〔七〕登堂坐定，不疑據地曰：「竊伏海瀕，聞暴公子威名舊矣，〔八〕今乃承顏接辭。凡為吏，太剛則折，太柔則廢，威行施之以恩，然後樹功揚名，永終天祿。」〔九〕勝之知不疑非庸人，〔一０〕敬納其戒，深接以禮意，問當世所施行。門下諸從事皆州郡選吏，〔一一〕側聽不疑，莫不驚駭。至昏夜，罷去。勝之遂表薦不疑，徵詣公車，拜為青州刺史。","sentenceOrder":3},
  {"id":"s_work_han_thu_84_4","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「督謂察視之。」","sentenceOrder":4},
  {"id":"s_work_han_thu_84_5","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「有所追捕及行誅罰，皆依興軍之制。」","sentenceOrder":5},
  {"id":"s_work_han_thu_84_6","chapterId":"ch_work_han_thu_84","textTraditional":"〔三〕　應劭曰：「櫑具，木摽首之劍，櫑落壯大也。」晉灼曰：「古長劍首以玉作井鹿盧形，上刻木作山形，如蓮花初生未敷時。今大劍木首，其狀似此。」師古曰：「晉說是也。櫑音磊。摽音匹遙反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_84_7","chapterId":"ch_work_han_thu_84","textTraditional":"〔四〕　師古曰：「環，玉環也。玦即玉佩之玦也。帶環而又著玉佩也。禮記曰『孔子佩象環』也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_84_8","chapterId":"ch_work_han_thu_84","textTraditional":"〔五〕　師古曰：「褒，大裾也。言著褒大之衣，廣博之帶也。而說者乃以為朝服垂褒之衣，非也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_84_9","chapterId":"ch_work_han_thu_84","textTraditional":"〔六〕　師古曰：「上謁，若今通名也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_84_10","chapterId":"ch_work_han_thu_84","textTraditional":"〔七〕　文穎曰：「躧音纚。」師古曰：「履不著跟曰躧。躧謂納履未正，曳之而行，言其遽也。躧音山爾反。」","sentenceOrder":10},
  {"id":"s_work_han_thu_84_11","chapterId":"ch_work_han_thu_84","textTraditional":"〔八〕　師古曰：「瀕，厓也。公子，勝之字也。舊，久也。瀕音頻，又音賓。」","sentenceOrder":11},
  {"id":"s_work_han_thu_84_12","chapterId":"ch_work_han_thu_84","textTraditional":"〔九〕　師古曰：「樹，立也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_84_13","chapterId":"ch_work_han_thu_84","textTraditional":"〔一０〕師古曰：「庸，常也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_84_14","chapterId":"ch_work_han_thu_84","textTraditional":"〔一一〕師古曰：「選州郡吏之最者乃得為從事。」","sentenceOrder":14},
  {"id":"s_work_han_thu_84_15","chapterId":"ch_work_han_thu_84","textTraditional":"久之，武帝崩，昭帝即位，而齊孝王孫劉澤交結郡國豪傑謀反，欲先殺青州刺史。不疑發覺，收捕，皆伏其辜。擢為京兆尹，賜錢百萬。京師吏民敬其威信。每行縣錄囚徒還，〔一〕其母輒問不疑：「有所平反，活幾何人？」〔二〕即不疑多有所平反，母喜笑，為飲食語言異於他時；或亡所出，母怒，為之不食。故不疑為吏，嚴而不殘。","sentenceOrder":15},
  {"id":"s_work_han_thu_84_16","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「省錄之，知其情狀有冤滯與不也。今云慮囚，本錄聲之去者耳，音力具反。而近俗不曉其意，訛其文遂為思慮之慮，失其源矣。行音下更反。」","sentenceOrder":16},
  {"id":"s_work_han_thu_84_17","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　如淳曰：「反音幡。幡，奏使從輕也。」師古曰：「幾音居起反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_84_18","chapterId":"ch_work_han_thu_84","textTraditional":"始元五年，有一男子乘黃犢車，建黃旐，〔一〕衣黃襜褕，著黃冒，〔二〕詣北闕，自謂衛太子。〔三〕公車以聞，〔四〕詔使公卿將軍中二千石雜識視。〔五〕長安中吏民聚觀者數萬人。右將軍勒兵闕下，以備非常。丞相御史中二千石至者（立）〔並〕莫敢發言。京兆尹不疑後到，叱從吏收縛。或曰：「是非未可知，且安之。」〔六〕不疑曰：「諸君何患於衛太子！昔蒯聵違命出奔，輒距而不納，春秋是之。〔七〕衛太子得罪先帝，亡不即死，今來自詣，此罪人也。」遂送詔獄。","sentenceOrder":18},
  {"id":"s_work_han_thu_84_19","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「旐，旌旗之屬，畫龜蛇曰旐。」","sentenceOrder":19},
  {"id":"s_work_han_thu_84_20","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「襜褕，直裾襌衣。襜音昌瞻反。褕音踰。冒所以覆冒其首，即今之下裙冒也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_84_21","chapterId":"ch_work_han_thu_84","textTraditional":"〔三〕　師古曰：「戾太子。」","sentenceOrder":21},
  {"id":"s_work_han_thu_84_22","chapterId":"ch_work_han_thu_84","textTraditional":"〔四〕　師古曰：「公車，主受章奏者。」","sentenceOrder":22},
  {"id":"s_work_han_thu_84_23","chapterId":"ch_work_han_thu_84","textTraditional":"〔五〕　師古曰：「雜，共也。有素識之者，令視知其是非也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_84_24","chapterId":"ch_work_han_thu_84","textTraditional":"〔六〕　師古曰：「安猶徐也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_84_25","chapterId":"ch_work_han_thu_84","textTraditional":"〔七〕　師古曰：「蒯聵，衛靈公太子。輒，蒯聵子也。蒯聵得罪於靈公而出奔晉。及靈公卒，使輒嗣位，而晉趙鞅納蒯聵於戚，欲求入衛。魯哀公三年春，齊國夏、衛石曼姑帥師圍戚。公羊傳曰：『曼姑受命於靈公而立輒，曼姑之義固可以距蒯聵也。輒之義可以立乎？曰可。柰何不以父命辭王父命也。』」","sentenceOrder":25},
  {"id":"s_work_han_thu_84_26","chapterId":"ch_work_han_thu_84","textTraditional":"天子與大將軍霍光聞而嘉之，曰：「公卿大臣當用經術明於大誼。」繇是名聲重於朝廷，〔一〕在位者皆自以不及也。大將軍光欲以女妻之，不疑固辭，不肯當。久之，以病免，終於家。京師紀之。後趙廣漢為京兆尹，言「我禁姦止邪，行於吏民，至於朝廷事，不及不疑遠甚。」廷尉驗治何人，竟得姦詐。〔二〕本夏陽人，姓成名方遂，居湖，〔三〕以卜筮為事。有故太子舍人嘗從方遂卜，謂曰：「子狀貌甚似衛太子。」方遂心利其言，幾得以富貴，〔四〕即詐自稱詣闕。廷尉逮召鄉里識知者張宗祿等，方遂坐誣罔不道，要斬東巿。一〔云〕姓張名延年。〔五〕","sentenceOrder":26},
  {"id":"s_work_han_thu_84_27","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「繇讀與由同。」","sentenceOrder":27},
  {"id":"s_work_han_thu_84_28","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「凡不知姓名及所從來者，皆曰何人。他皆類此。」","sentenceOrder":28},
  {"id":"s_work_han_thu_84_29","chapterId":"ch_work_han_thu_84","textTraditional":"〔三〕　師古曰：「湖，縣名。」","sentenceOrder":29},
  {"id":"s_work_han_thu_84_30","chapterId":"ch_work_han_thu_84","textTraditional":"〔四〕　師古曰：「幾讀曰冀。」","sentenceOrder":30},
  {"id":"s_work_han_thu_84_31","chapterId":"ch_work_han_thu_84","textTraditional":"〔五〕　師古曰：「故昭紀謂之張延年。」","sentenceOrder":31},
  {"id":"s_work_han_thu_84_32","chapterId":"ch_work_han_thu_84","textTraditional":"疏廣字仲翁，東海蘭陵人也。少好學，明春秋，家居教授，學者自遠方至。徵為博士太中大夫。地節三年，立皇太子，選丙吉為太傅，廣為少傅。數月，吉遷御史大夫，廣徙為太傅，廣兄子受字公子，亦以賢良舉為太子家令。受好禮恭謹，敏而有辭。〔一〕宣帝幸太子宮，受迎謁應對，及置酒宴，奉觴上壽，辭禮閑雅，上甚讙說。〔二〕頃之，拜受為少傅。","sentenceOrder":32},
  {"id":"s_work_han_thu_84_33","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「敏謂所見捷利。」","sentenceOrder":33},
  {"id":"s_work_han_thu_84_34","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":34},
  {"id":"s_work_han_thu_84_35","chapterId":"ch_work_han_thu_84","textTraditional":"太子外祖父特進平恩侯許伯以為太子少，白使其弟中郎將舜監護太子家。上以問廣，廣對曰：「太子國儲副君，師友必於天下英俊，不宜獨親外家許氏。且太子自有太傅少傅，官屬已備，今復使舜護太子家，視陋，非所以廣太子德於天下也。」〔一〕上善其言，以語丞相魏相，相免冠謝曰：「此非臣等所能及。」廣繇是見器重，數受賞賜。〔二〕太子每朝，因進見，太傅在前，少傅在後。父子並為師傅，朝廷以為榮。","sentenceOrder":35},
  {"id":"s_work_han_thu_84_36","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「視讀曰示。言獨親外家，示天下以淺陋。」","sentenceOrder":36},
  {"id":"s_work_han_thu_84_37","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「繇讀與由同。」","sentenceOrder":37},
  {"id":"s_work_han_thu_84_38","chapterId":"ch_work_han_thu_84","textTraditional":"在位五歲，皇太子年十二，通論語、孝經。廣謂受曰：「吾聞『知足不辱，知止不殆』，『功遂身退，天之道』也。〔一〕今仕（宦）〔官〕至二千石，宦成名立，如此不去，懼有後悔，豈如父子相隨出關，歸老故鄉，以壽命終，不亦善乎？」受叩頭曰：「從大人議。」即日父子俱移病。〔二〕滿三月賜告，廣遂稱篤，上疏乞骸骨。上以其年篤老，皆許之，加賜黃金二十斤，皇太子贈以五十斤。公卿大夫故人邑子設祖道，供張東都門外，〔三〕送者車數百兩，辭決而去。及道路觀者皆曰：「賢哉二大夫！」或歎息為之下泣。","sentenceOrder":38},
  {"id":"s_work_han_thu_84_39","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「此皆老子之言，廣引之。殆，危也。遂，成也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_84_40","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「移病即移書言病也。一曰以病而移居。」","sentenceOrder":40},
  {"id":"s_work_han_thu_84_41","chapterId":"ch_work_han_thu_84","textTraditional":"〔三〕　蘇林曰：「長安東郭門也。」師古曰：「祖道，餞行也，解在景十三王及劉屈〈氂，中“未改牙”〉傳。供音居共反。張音竹亮反。」","sentenceOrder":41},
  {"id":"s_work_han_thu_84_42","chapterId":"ch_work_han_thu_84","textTraditional":"廣既歸鄉里，日令家共具設酒食，〔一〕請族人故舊賓客，與相娛樂。數問其家金餘尚有幾所，趣賣以共具。〔二〕居歲餘，廣子孫竊謂其昆弟老人廣所愛信者曰：「子孫幾及君時頗立產業基阯，〔三〕今日飲食（廢）〔費〕且盡。宜從丈人所，勸說君買田宅。」〔四〕老人即以閒暇時為廣言此計，〔五〕廣曰：「吾豈老誖不念子孫哉？〔六〕顧自有舊田廬，〔七〕令子孫勤力其中，足以共衣食，與凡人齊。今復增益之以為贏餘，但教子孫怠墯耳。賢而多財，則損其志；愚而多財，則益其過。且夫富者，眾人之怨也；吾既亡以教化子孫，不欲益其過而生怨。又此金者，聖主所以惠養老臣也，故樂與鄉黨宗族共饗其賜，以盡吾餘日，不亦可乎！」於是族人說服。〔八〕皆以壽終。","sentenceOrder":42},
  {"id":"s_work_han_thu_84_43","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「日日設之也。共讀曰供。其他類此。」","sentenceOrder":43},
  {"id":"s_work_han_thu_84_44","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「幾所猶言幾許也。趣讀曰促。」","sentenceOrder":44},
  {"id":"s_work_han_thu_84_45","chapterId":"ch_work_han_thu_84","textTraditional":"〔三〕　師古曰：「幾讀曰冀。」","sentenceOrder":45},
  {"id":"s_work_han_thu_84_46","chapterId":"ch_work_han_thu_84","textTraditional":"〔四〕　鄧展曰：「宜令意自從丈人所出，無泄吾言也。」師古曰：「丈人，莊嚴之稱也，故親而老者皆稱焉。」","sentenceOrder":46},
  {"id":"s_work_han_thu_84_47","chapterId":"ch_work_han_thu_84","textTraditional":"〔五〕　師古曰：「閒即閑字也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_84_48","chapterId":"ch_work_han_thu_84","textTraditional":"〔六〕　師古曰：「誖，惑也，音布內反。」","sentenceOrder":48},
  {"id":"s_work_han_thu_84_49","chapterId":"ch_work_han_thu_84","textTraditional":"〔七〕　師古曰：「顧，思念也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_84_50","chapterId":"ch_work_han_thu_84","textTraditional":"〔八〕　師古曰：「說讀曰悅。」","sentenceOrder":50},
  {"id":"s_work_han_thu_84_51","chapterId":"ch_work_han_thu_84","textTraditional":"于定國字曼倩，東海郯人也。〔一〕其父于公為縣獄史，郡決曹，決獄平，羅文法者于公所決皆不恨。〔二〕郡中為之生立祠，號曰于公祠。","sentenceOrder":51},
  {"id":"s_work_han_thu_84_52","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「郯音談。」","sentenceOrder":52},
  {"id":"s_work_han_thu_84_53","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「羅，罹也，遭也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_84_54","chapterId":"ch_work_han_thu_84","textTraditional":"東海有孝婦，少寡，亡子，養姑甚謹，姑欲嫁之，終不肯。姑謂鄰人曰：「孝婦事我勤苦，哀其亡子守寡。我老，久絫丁壯，柰何？」〔一〕其後姑自經死，〔二〕姑女告吏：「婦殺我母。」吏捕孝婦，孝婦辭不殺姑。吏驗治，孝婦自誣服。具獄上府，〔三〕于公以為此婦養姑十餘年，以孝聞，必不殺也。太守不聽，于公爭之，弗能得，乃抱其具獄，哭於府上，〔四〕因辭疾去。太守竟論殺孝婦。郡中枯旱三年。後太守至，卜筮其故，于公曰：「孝婦不當死，前太守彊斷之，咎黨在是乎？」〔五〕於是太守殺牛自祭孝婦冢，因表其墓，天立大雨，歲孰。郡中以此大敬重于公。","sentenceOrder":54},
  {"id":"s_work_han_thu_84_55","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「絫，古累字也，音力瑞反。」","sentenceOrder":55},
  {"id":"s_work_han_thu_84_56","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「不欲累婦，故自殺。」","sentenceOrder":56},
  {"id":"s_work_han_thu_84_57","chapterId":"ch_work_han_thu_84","textTraditional":"〔三〕　師古曰：「府，郡之曹府也。上音時掌反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_84_58","chapterId":"ch_work_han_thu_84","textTraditional":"〔四〕　師古曰：「具獄者，獄案已成，其文備具也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_84_59","chapterId":"ch_work_han_thu_84","textTraditional":"〔五〕　師古曰：「黨音他朗反。」","sentenceOrder":59},
  {"id":"s_work_han_thu_84_60","chapterId":"ch_work_han_thu_84","textTraditional":"定國少學法于父，父死，後定國亦為獄史，郡決曹，補廷尉史，以選與御史中丞從事治反者獄，以材高舉侍御史，遷御史中丞。會昭帝崩，昌邑王徵即位，行淫亂，定國上書諫。後王廢，宣帝立，大將軍光領尚書事，條奏群臣諫昌邑王者皆超遷。定國繇是為光祿大夫，〔一〕平尚書事，甚見任用。數年，遷水衡都尉，超為廷尉。","sentenceOrder":60},
  {"id":"s_work_han_thu_84_61","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「繇與由同。」","sentenceOrder":61},
  {"id":"s_work_han_thu_84_62","chapterId":"ch_work_han_thu_84","textTraditional":"定國乃迎師學春秋，身執經，北面備弟子禮。為人謙恭，尤重經術士，雖卑賤徒步往過，定國皆與鈞禮，〔一〕恩敬甚備，學士咸（聲）〔稱〕焉。其決疑平法，務在哀鰥寡，罪疑從輕，加審慎之心。朝廷稱之曰：「張釋之為廷尉，天下無冤民；〔二〕于定國為廷尉，民自以不冤。」〔三〕定國食酒至數石不亂，〔四〕冬月請治讞，飲酒益精明。〔五〕為廷尉十八歲，遷御史大夫。","sentenceOrder":62},
  {"id":"s_work_han_thu_84_63","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「鈞禮猶言亢禮。」","sentenceOrder":63},
  {"id":"s_work_han_thu_84_64","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「言決罪皆當。」","sentenceOrder":64},
  {"id":"s_work_han_thu_84_65","chapterId":"ch_work_han_thu_84","textTraditional":"〔三〕　師古曰：「言知其寬平，皆無冤枉之慮。」","sentenceOrder":65},
  {"id":"s_work_han_thu_84_66","chapterId":"ch_work_han_thu_84","textTraditional":"〔四〕　如淳曰：「食酒猶言喜酒也。」師古曰：「若依如氏之說，食字當音嗜，此說非也。下敘定國子永乃言嗜酒耳。食酒者，謂能多飲，費盡其酒，猶云食言焉。今流俗書本輒改食字作飲字，失其真也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_84_67","chapterId":"ch_work_han_thu_84","textTraditional":"〔五〕　師古曰：「讞，平議也，音魚列反。」","sentenceOrder":67},
  {"id":"s_work_han_thu_84_68","chapterId":"ch_work_han_thu_84","textTraditional":"甘露中，代黃霸為丞相，封西平侯。三年，宣帝崩，元帝立，以定國任職舊臣，敬重之。時陳萬年為御史大夫，與定國並位八年，論議無所拂。〔一〕後貢禹代為御史大夫，數處駮議，〔二〕定國明習政事，率常丞相議可。〔三〕然上始即位，關東連年被災害，民流入關，言事者歸咎於大臣。〔四〕上於是數以朝日引見丞相、御史〔五〕，入受詔，條責以職事，曰：「惡吏負賊，妄意良民，〔六〕至亡辜死。或盜賊發，吏不亟追而反繫亡家，〔七〕後不敢復告，以故寖廣。〔八〕民多冤結，州郡不理，連上書者交於闕廷。二千石選舉不實，是以在位多不任職。〔九〕民田有災害，吏不肯除，收趣其租，以故重困。〔一０〕關東流民飢寒疾疫，已詔吏轉漕，虛食廩開府臧相振救，賜寒者衣，至春猶恐不贍。〔一一〕今丞相、御史將欲何施以塞此咎？〔一二〕悉意條狀，陳朕過失。」〔一三〕定國上書謝罪。","sentenceOrder":68},
  {"id":"s_work_han_thu_84_69","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「言不相違戾也。拂音佛。」","sentenceOrder":69},
  {"id":"s_work_han_thu_84_70","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「言與定國不同。」","sentenceOrder":70},
  {"id":"s_work_han_thu_84_71","chapterId":"ch_work_han_thu_84","textTraditional":"〔三〕　師古曰：「（言事者）〔天子皆〕可定國所言。」","sentenceOrder":71},
  {"id":"s_work_han_thu_84_72","chapterId":"ch_work_han_thu_84","textTraditional":"〔四〕　師古曰：「言事者謂上書陳事也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_84_73","chapterId":"ch_work_han_thu_84","textTraditional":"〔五〕　師古曰：「五日一聽朝，故云朝日也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_84_74","chapterId":"ch_work_han_thu_84","textTraditional":"〔六〕　師古曰：「賊發不得，恐負其殿，故妄疑善人，致其罪也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_84_75","chapterId":"ch_work_han_thu_84","textTraditional":"〔七〕　師古曰：「亟，急也。不急追賊，反禁繫失物之家。」","sentenceOrder":75},
  {"id":"s_work_han_thu_84_76","chapterId":"ch_work_han_thu_84","textTraditional":"〔八〕　師古曰：「寖，漸也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_84_77","chapterId":"ch_work_han_thu_84","textTraditional":"〔九〕　師古曰：「謂令長丞尉。」","sentenceOrder":77},
  {"id":"s_work_han_thu_84_78","chapterId":"ch_work_han_thu_84","textTraditional":"〔一０〕師古曰：「趣讀曰促。重音直用反。」","sentenceOrder":78},
  {"id":"s_work_han_thu_84_79","chapterId":"ch_work_han_thu_84","textTraditional":"〔一一〕師古曰：「贍，足也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_84_80","chapterId":"ch_work_han_thu_84","textTraditional":"〔一二〕師古曰：「塞，補也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_84_81","chapterId":"ch_work_han_thu_84","textTraditional":"〔一三〕師古曰：「悉，盡也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_84_82","chapterId":"ch_work_han_thu_84","textTraditional":"永光元年，春霜夏寒，日青亡光，上復以詔條責曰：「郎有從東方來者，言民父子相棄。〔一〕丞相、御史案事之吏匿不言邪？將從東方來者加增之也？何以錯繆至是？〔二〕欲知其實。方今年歲未可預知也，即有水旱，其憂不細。公卿有可以防其未然，救其已然者不？各以誠對，〔三〕毋有所諱。」定國惶恐，上書自劾，歸侯印，乞骸骨。上報曰：「君相朕躬，不敢怠息，〔四〕萬方之事，大錄于君。〔五〕能毋過者，其唯聖人。方今承周秦之敝，俗化陵夷，〔六〕民寡禮誼，陰陽不調，災咎之發，不為一端而作，自聖人推類以記，不敢專也，況於非聖者乎！〔七〕日夜惟思所以，未能盡明。〔八〕經曰：『萬方有罪，罪在朕躬。』〔九〕君雖任職，何必顓焉？〔一０〕其勉察郡國守相（郡）〔群〕牧，非其人者毋令久賊民。永執綱紀，務悉聰明，強食慎疾。」〔一一〕定國遂稱篤，固辭。上乃賜安車駟馬、黃金六十斤，罷就第。數歲，七十餘薨，諡曰安侯。","sentenceOrder":82},
  {"id":"s_work_han_thu_84_83","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「以遭飢饉不能相養。」","sentenceOrder":83},
  {"id":"s_work_han_thu_84_84","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「錯，互也。繆，違也。謂吏及東方人言不相同也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_84_85","chapterId":"ch_work_han_thu_84","textTraditional":"〔三〕　師古曰：「言能防救已不，宜各以實對。」","sentenceOrder":85},
  {"id":"s_work_han_thu_84_86","chapterId":"ch_work_han_thu_84","textTraditional":"〔四〕　師古曰：「息謂自休息。」","sentenceOrder":86},
  {"id":"s_work_han_thu_84_87","chapterId":"ch_work_han_thu_84","textTraditional":"〔五〕　師古曰：「大錄，總錄也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_84_88","chapterId":"ch_work_han_thu_84","textTraditional":"〔六〕　師古曰：「言頹替也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_84_89","chapterId":"ch_work_han_thu_84","textTraditional":"〔七〕　師古曰：「非聖者謂常人。」","sentenceOrder":89},
  {"id":"s_work_han_thu_84_90","chapterId":"ch_work_han_thu_84","textTraditional":"〔八〕　師古曰：「所以，所由也。言何由致此災。」","sentenceOrder":90},
  {"id":"s_work_han_thu_84_91","chapterId":"ch_work_han_thu_84","textTraditional":"〔九〕　師古曰：「此論語堯曰篇載殷湯伐桀告天之辭。」","sentenceOrder":91},
  {"id":"s_work_han_thu_84_92","chapterId":"ch_work_han_thu_84","textTraditional":"〔一０〕師古曰：「顓與專同。事不專由君也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_84_93","chapterId":"ch_work_han_thu_84","textTraditional":"〔一一〕師古曰：「悉，盡也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_84_94","chapterId":"ch_work_han_thu_84","textTraditional":"子永嗣。少時，耆酒多過失，〔一〕年且三十，乃折節修行，以父任為侍中中郎將、長水校尉。定國死，居喪如禮，孝行聞。由是以列侯為散騎光祿勳，至御史大夫。尚館陶公主施。施者，宣帝長女，成帝姑也，賢有行，永以選尚焉。上方欲相之，會永薨。子恬嗣。恬不肖，薄於行。","sentenceOrder":94},
  {"id":"s_work_han_thu_84_95","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「耆讀曰嗜。」","sentenceOrder":95},
  {"id":"s_work_han_thu_84_96","chapterId":"ch_work_han_thu_84","textTraditional":"始定國父于公，其閭門壞，父老方共治之。〔一〕于公謂曰：「少高大閭門，令容駟馬高蓋車。我治獄多陰德，未嘗有所冤，子孫必有興者。」至定國為丞相，永為御史大夫，封侯傳世云。","sentenceOrder":96},
  {"id":"s_work_han_thu_84_97","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「閭門，里門也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_84_98","chapterId":"ch_work_han_thu_84","textTraditional":"薛廣德字長卿，沛郡相人也。以魯詩教授楚國，龔勝、舍師事焉。蕭望之為御史大夫，除廣德為屬，數與論議，器之，〔一〕薦廣德經行宜充本朝。〔二〕為博士，論石渠，〔三〕遷諫大夫，代貢禹為長信少府、御史大夫。","sentenceOrder":98},
  {"id":"s_work_han_thu_84_99","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「以為大器也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_84_100","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「經明行修，宜於本朝任職也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_84_101","chapterId":"ch_work_han_thu_84","textTraditional":"〔三〕　張晏曰：「石渠，閣名也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_84_102","chapterId":"ch_work_han_thu_84","textTraditional":"廣德為人溫雅有醞藉。〔一〕及為三公，直言諫爭。始拜旬日間，上幸甘泉，郊泰畤，禮畢，因留射獵。廣德上書曰：「竊見關東困極，人民流離。陛下日撞亡秦之鐘，聽鄭衛之樂，〔二〕臣誠悼之。今士卒暴露，從官勞倦，願陛下亟反宮，〔三〕思與百姓同憂樂，天下幸甚。」上即日還。其秋，上酎祭宗廟，出便門，〔四〕欲御樓船，廣德當乘輿車，免冠頓首曰：「宜從橋。」詔曰：「大夫冠。」廣德曰：「陛下不聽臣，臣自刎，以血汙車輪，陛下不得入廟矣！〔五〕」上不說。〔六〕先〈區夂〉光祿大夫張猛進曰：〔七〕「臣聞主聖臣直。乘船危，就橋安，聖主不乘危。御史大夫言可聽。」上曰：「曉人不當如是邪！」〔八〕乃從橋。","sentenceOrder":102},
  {"id":"s_work_han_thu_84_103","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　服虔曰：「寬博有餘也。」師古曰：「醞言如醞釀也。藉，有所薦藉也。醞音於問反。藉，才夜反。」","sentenceOrder":103},
  {"id":"s_work_han_thu_84_104","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「撞音丈江反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_84_105","chapterId":"ch_work_han_thu_84","textTraditional":"〔三〕　師古曰：「亟，急也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_84_106","chapterId":"ch_work_han_thu_84","textTraditional":"〔四〕　師古曰：「長安城南面西頭第一門。」","sentenceOrder":106},
  {"id":"s_work_han_thu_84_107","chapterId":"ch_work_han_thu_84","textTraditional":"〔五〕　師古曰：「言不以理，終不得立廟也。一曰以見死傷，犯於齊絜，不得入廟祠也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_84_108","chapterId":"ch_work_han_thu_84","textTraditional":"〔六〕　師古曰：「說讀曰悅。」","sentenceOrder":108},
  {"id":"s_work_han_thu_84_109","chapterId":"ch_work_han_thu_84","textTraditional":"〔七〕　師古曰：「先〈區夂〉，導乘輿也。〈區夂〉與驅同。猛，張騫之孫。」","sentenceOrder":109},
  {"id":"s_work_han_thu_84_110","chapterId":"ch_work_han_thu_84","textTraditional":"〔八〕　師古曰：「謂諫爭之言，當如猛之詳善也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_84_111","chapterId":"ch_work_han_thu_84","textTraditional":"後月餘，以歲惡民流，〔一〕與丞相定國、大司馬車騎將軍史高俱乞骸骨，皆賜安車駟馬、黃金六十斤，罷。廣德為御史大夫，凡十月免。東歸沛，太守迎之界上。沛以為榮，縣其安車傳子孫。〔二〕","sentenceOrder":111},
  {"id":"s_work_han_thu_84_112","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「歲惡，年穀不熟也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_84_113","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「縣其所賜安車以示榮也。致仕縣車，蓋亦古法。韋孟詩云『縣車之義，以洎小臣』也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_84_114","chapterId":"ch_work_han_thu_84","textTraditional":"平當字子思，祖父以訾百萬，自下邑徙平陵。〔一〕當少為大行治禮丞，功次補大鴻臚文學，察廉為順陽長，栒邑令，〔二〕以明經為博士，公卿薦當論議通明，給事中。每有災異，當輒傅經術，言得失。〔三〕文雅雖不能及蕭望之、匡衡，然指意略同。","sentenceOrder":114},
  {"id":"s_work_han_thu_84_115","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「下邑，梁國之縣也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_84_116","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「栒音詢。」","sentenceOrder":116},
  {"id":"s_work_han_thu_84_117","chapterId":"ch_work_han_thu_84","textTraditional":"〔三〕　師古曰：「傅讀曰附。」","sentenceOrder":117},
  {"id":"s_work_han_thu_84_118","chapterId":"ch_work_han_thu_84","textTraditional":"自元帝時，韋玄成為丞相，奏罷太上皇寢廟園，當上書言：「臣聞孔子曰：『如有王者，必世而後仁。』〔一〕三十年之間，道德和洽，制禮興樂，災害不生，禍亂不作。今聖漢受命而王，繼體承業二百餘年，孜孜不怠，政令清矣。然風俗未和，陰陽未調，災害數見，意者大本有不立與？〔二〕何德化休徵不應之久也！禍福不虛，必有因而至者焉。宜深跡其道而務修其本。〔三〕昔者帝堯南面而治，先『克明俊德，以親九族』，而化及萬國。〔四〕孝經曰：『天地之性人為貴，人之行莫大於孝，孝莫大於嚴父，嚴父莫大於配天，則周公其人也。』〔五〕夫孝子善述人之志，周公既成文武之業而制作禮樂，修嚴父配天之事，知文王不欲以子臨父，故推而序之，上極於后稷而以配天。〔六〕此聖人之德，亡以加於孝也。高皇帝聖德受命，有天下，尊太上皇，猶周文武之追王太王、王季也。此漢之始祖，後嗣所宜尊奉以廣盛德，孝之至也。書云：『正稽古建功立事，可以永年，傳於亡窮。』」〔七〕上納其言，下詔復太上皇寢廟園。","sentenceOrder":118},
  {"id":"s_work_han_thu_84_119","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「論語載孔子之言也。言治天下者，三十年然後仁道成著也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_84_120","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「與讀曰歟。」","sentenceOrder":120},
  {"id":"s_work_han_thu_84_121","chapterId":"ch_work_han_thu_84","textTraditional":"〔三〕　師古曰：「跡謂求其蹤跡也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_84_122","chapterId":"ch_work_han_thu_84","textTraditional":"〔四〕　師古曰：「虞書堯典序堯之德曰：『克明俊德，以親九族。九族既睦，平章百姓。百姓昭明，協和萬邦。』故云然也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_84_123","chapterId":"ch_work_han_thu_84","textTraditional":"〔五〕　師古曰：「言嚴謂尊嚴。」","sentenceOrder":123},
  {"id":"s_work_han_thu_84_124","chapterId":"ch_work_han_thu_84","textTraditional":"〔六〕　師古曰：「言文王始受命，宜為周之始祖。乃追王太王、王季，以及后稷，是不以卑臨尊。」","sentenceOrder":124},
  {"id":"s_work_han_thu_84_125","chapterId":"ch_work_han_thu_84","textTraditional":"〔七〕　師古曰：「今文泰誓之辭。言能正考古道以立功立事，則可長年享國。」","sentenceOrder":125},
  {"id":"s_work_han_thu_84_126","chapterId":"ch_work_han_thu_84","textTraditional":"頃之，使行流民幽州，〔一〕舉奏刺史二千石勞來有意者，〔二〕言勃海鹽池可且勿禁，以救民急。〔三〕所過見稱，奉使者十一人為最，遷丞相司直。坐法，左遷朔方刺史，〔四〕復徵入為太中大夫給事中，絫遷長信少府、大鴻臚、光祿勳。〔五〕","sentenceOrder":126},
  {"id":"s_work_han_thu_84_127","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「行音下更反。」","sentenceOrder":127},
  {"id":"s_work_han_thu_84_128","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「勞來謂勸勉也。勞者，恤其勤勞也。來者，以恩招來也。勞音盧到反。來音盧代反。」","sentenceOrder":128},
  {"id":"s_work_han_thu_84_129","chapterId":"ch_work_han_thu_84","textTraditional":"〔三〕　師古曰：「恣民煮鹽，官不專也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_84_130","chapterId":"ch_work_han_thu_84","textTraditional":"〔四〕　師古曰：「武帝初置朔方郡，別令刺史監之，不在十三州之限。」","sentenceOrder":130},
  {"id":"s_work_han_thu_84_131","chapterId":"ch_work_han_thu_84","textTraditional":"〔五〕　師古曰：「絫，古累字。」","sentenceOrder":131},
  {"id":"s_work_han_thu_84_132","chapterId":"ch_work_han_thu_84","textTraditional":"先是太后姊子衛尉淳于長白言昌陵不可成，下有司議。當以為作治連年，可遂就。〔一〕上既罷昌陵，以長首建忠策，復下公卿議封長。當又以為長雖有善言，不應封爵之科。坐前議不正，左遷鉅鹿太守。〔二〕後上遂封長。當以經明禹貢，使行河，〔三〕為騎都尉，領河隄。","sentenceOrder":132},
  {"id":"s_work_han_thu_84_133","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「就亦成也。」","sentenceOrder":133},
  {"id":"s_work_han_thu_84_134","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「前議謂罷昌陵。」","sentenceOrder":134},
  {"id":"s_work_han_thu_84_135","chapterId":"ch_work_han_thu_84","textTraditional":"〔三〕　師古曰：「尚書禹貢載禹治水次第，山川高下，當明此經，故使行河也。行音下更反。」","sentenceOrder":135},
  {"id":"s_work_han_thu_84_136","chapterId":"ch_work_han_thu_84","textTraditional":"哀帝即位，徵當為光祿大夫諸吏散騎，復為光祿勳，御史大夫，至丞相。以冬月，賜爵關內侯。明年春，上使使者召，欲封當。〔一〕當病篤，不應召。室家或謂當：「不可強起受侯印為子孫邪？」當曰：「吾居大位，已負素餐之責矣，起受侯印，還臥而死，死有餘罪。今不起者，所以為子孫也。」遂上書乞骸骨。上報曰：「朕選於眾，以君為相，視事日寡，輔政未久，陰陽不調，冬無大雪，旱氣為災，朕之不德，何必君罪？君何疑而上書乞骸骨，歸關內侯爵邑？使尚書令譚賜君養牛一，上尊酒十石。〔二〕君其勉致醫藥以自持。」後月餘，卒。子晏以明經歷位大司徒，封防鄉侯。漢興，唯韋、平父子至宰相。〔三〕","sentenceOrder":136},
  {"id":"s_work_han_thu_84_137","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　如淳曰：「漢儀注御史大夫為丞相，更春乃封，故先賜爵關內侯。」李奇曰：「（一）以冬月非封侯時，故且先賜爵關內侯也。」師古曰：「李說是也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_84_138","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　如淳曰：「律，稻米一斗得酒一斗為上尊，稷米一斗得酒一斗為中尊，粟米一斗得酒一斗為下尊。」師古曰：「稷即粟也。中尊者宜為黍米，不當言稷。且作酒自有澆醇之異為上中下耳，非必繫之米。」","sentenceOrder":138},
  {"id":"s_work_han_thu_84_139","chapterId":"ch_work_han_thu_84","textTraditional":"〔三〕　師古曰：「韋謂韋賢也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_84_140","chapterId":"ch_work_han_thu_84","textTraditional":"彭宣字子佩，淮陽陽夏人也。〔一〕治易，事張禹，舉為博士，遷東平太傅。禹以帝師見尊信，薦宣經明有威重，可任政事，繇是入為右扶風，〔二〕遷廷尉，以王國人出為太原太守。〔三〕數年，復入為大司農、光祿勳、右將軍。哀帝即位，徙為左將軍。歲餘，上欲令丁、傅處爪牙官，乃策宣曰：「有司數奏言諸侯國人不得宿衛，將軍不宜典兵馬，處大位。朕唯將軍任漢將之重，而子又前取淮陽王女，婚姻不絕，非國之制。使光祿大夫曼賜將軍黃金五十斤、安車駟馬，其上左將軍印綬，以關內侯歸家。」","sentenceOrder":140},
  {"id":"s_work_han_thu_84_141","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「夏音假。」","sentenceOrder":141},
  {"id":"s_work_han_thu_84_142","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「繇讀與由同。」","sentenceOrder":142},
  {"id":"s_work_han_thu_84_143","chapterId":"ch_work_han_thu_84","textTraditional":"〔三〕　李奇曰：「初，漢制王國人不得在京師。」","sentenceOrder":143},
  {"id":"s_work_han_thu_84_144","chapterId":"ch_work_han_thu_84","textTraditional":"宣罷數歲，諫大夫鮑宣數薦宣。會元壽元年正月朔日蝕，鮑宣復（上言）〔言，上〕乃召宣為光祿大夫，遷御史大夫，轉為大司空，封長平侯。","sentenceOrder":144},
  {"id":"s_work_han_thu_84_145","chapterId":"ch_work_han_thu_84","textTraditional":"會哀帝崩，新都侯王莽為大司馬，秉政專權。宣上書言：「三公鼎足承君，一足不任，則覆亂美實。〔一〕臣資性淺薄，年齒老眊，〔二〕數伏疾病，昏亂遺忘，願上大司空、長平侯印綬，乞骸骨歸鄉里，俟寘溝壑。」〔三〕莽白太后，策宣曰：「惟君視事日寡，功德未效，迫于老眊昏亂，非所以輔國家，綏海內也。使光祿勳豐冊詔君，其上大司空印綬，便就國。」莽恨宣求退，故不賜黃金安車駟馬。宣居國數年，薨，諡曰頃侯。傳子至孫，王莽敗，乃絕。","sentenceOrder":145},
  {"id":"s_work_han_thu_84_146","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「美實謂鼎中之實也。易鼎卦九四爻辭曰：『鼎折足，覆公餗。』餗，食也。故宣引以為言。覆音芳目反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_84_147","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　師古曰：「眊與耄同。」","sentenceOrder":147},
  {"id":"s_work_han_thu_84_148","chapterId":"ch_work_han_thu_84","textTraditional":"〔三〕　師古曰：「竢，古俟字。」","sentenceOrder":148},
  {"id":"s_work_han_thu_84_149","chapterId":"ch_work_han_thu_84","textTraditional":"贊曰：雋不疑學以從政，臨事不惑，遂立名跡，終始可述。疏廣行止足之計，免辱殆之絫，〔一〕亦其次也。于定國父子哀鰥哲獄，為任職臣。〔二〕薛廣德保縣車之榮，平當逡遁有恥，彭宣見險而止，〔三〕異乎「苟患失之」者矣。〔四〕","sentenceOrder":149},
  {"id":"s_work_han_thu_84_150","chapterId":"ch_work_han_thu_84","textTraditional":"〔一〕　師古曰：「絫音力瑞反。」","sentenceOrder":150},
  {"id":"s_work_han_thu_84_151","chapterId":"ch_work_han_thu_84","textTraditional":"〔二〕　應劭曰：「哲，智也。」鄭氏曰：「當言折獄。」師古曰：「哀鰥，哀恤鰥寡也。哲獄，知獄情也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_84_152","chapterId":"ch_work_han_thu_84","textTraditional":"〔三〕　師古曰：「遁讀與巡同。」","sentenceOrder":152},
  {"id":"s_work_han_thu_84_153","chapterId":"ch_work_han_thu_84","textTraditional":"〔四〕　師古曰：「論語稱孔子曰：『鄙夫不可與事君。其未得之，患得之；既得之，患失之。苟患失之，無所不至矣。』謂其患於失位而為傾邪也。贊言當、宣二人立操有異於此矣。」","sentenceOrder":153},
  {"id":"s_work_han_thu_84_154","chapterId":"ch_work_han_thu_84","textTraditional":"校勘記","sentenceOrder":154},
  {"id":"s_work_han_thu_84_155","chapterId":"ch_work_han_thu_84","textTraditional":"三０三七頁　七行　丞相御史中二千石至者（立）〔並〕莫敢發言。　各本都作「立」。王念孫說「立」當為「並」。王先謙說通鑑亦作「並」。","sentenceOrder":155},
  {"id":"s_work_han_thu_84_156","chapterId":"ch_work_han_thu_84","textTraditional":"三０三八頁　九行　一〔云〕姓張名延年。　王念孫說「一」下本有「云」字，漢紀正作「一云姓張名延年」。","sentenceOrder":156},
  {"id":"s_work_han_thu_84_157","chapterId":"ch_work_han_thu_84","textTraditional":"三０三九頁一五行　今仕（宦）〔官〕至二千石，　景祐、殿本都作「官」。","sentenceOrder":157},
  {"id":"s_work_han_thu_84_158","chapterId":"ch_work_han_thu_84","textTraditional":"三０四０頁一０行　今日飲食（廢）〔費〕且盡。　景祐、殿本都作「費」。王先謙說作「費」是。","sentenceOrder":158},
  {"id":"s_work_han_thu_84_159","chapterId":"ch_work_han_thu_84","textTraditional":"三０四三頁　一行　學士咸（聲）〔稱〕焉。　錢大昭說「聲」當作「稱」。按景祐、殿本都作「稱」。","sentenceOrder":159},
  {"id":"s_work_han_thu_84_160","chapterId":"ch_work_han_thu_84","textTraditional":"三０四四頁　五行　（言事者）〔天子皆〕可定國所言。　景祐、殿本都作「天子皆」。王先謙說此涉下「言事者」而誤。","sentenceOrder":160},
  {"id":"s_work_han_thu_84_161","chapterId":"ch_work_han_thu_84","textTraditional":"三０四五頁　七行　其勉察郡國守相（郡）〔群〕牧，　景祐、殿本都作「群」。王先謙說作「群」是。","sentenceOrder":161},
  {"id":"s_work_han_thu_84_162","chapterId":"ch_work_han_thu_84","textTraditional":"三０五一頁　八行　（一）以冬月非封侯時，　景祐、殿、局本無「一」字。","sentenceOrder":162},
  {"id":"s_work_han_thu_84_163","chapterId":"ch_work_han_thu_84","textTraditional":"三０五二頁　八行　鮑宣復（上言）〔言，上〕乃召宣為光祿大夫，　景祐、殿本都作「言上」。王先謙說「上」屬下讀。","sentenceOrder":163},
  {"id":"s_work_han_thu_85_1","chapterId":"ch_work_han_thu_85","textTraditional":"昔武王伐紂，遷九鼎於雒邑，〔一〕伯夷、叔齊薄之，〔二〕餓〔死〕于首陽，不食其祿，〔三〕周猶稱盛德焉。然孔子賢此二人，以為「不降其志，不辱其身」也。〔四〕而孟子亦云：「聞伯夷之風者，貪夫廉，懦夫有立志；」〔五〕「奮乎百世之上，（行乎）百世之下莫不興起，非賢人而能若是乎！」","sentenceOrder":1},
  {"id":"s_work_han_thu_85_2","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「九鼎，即夏禹所鑄者也。遷謂從紂都遷之以來。春秋左氏傳曰：『夏之方有德也，遠方圖物，貢金九牧以鑄鼎象物。桀有昏德，鼎遷于商，載祀六百。商紂暴虐，鼎遷于周。』」","sentenceOrder":2},
  {"id":"s_work_han_thu_85_3","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「夷、齊以武王父死不葬而用干戈為不孝，以臣伐君為不忠。」","sentenceOrder":3},
  {"id":"s_work_han_thu_85_4","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「馬融云首陽山在河東蒲阪華山之北，河曲之中。高誘則云在雒陽東北。阮籍詠懷詩亦以為然。今此二山並有夷齊祠耳。而曹大家注幽通賦云隴西首陽縣是也。今隴西亦有首陽山。許慎又云首陽山在遼西。諸說不同，致有疑惑，而伯夷歌云『登彼西山』，則當隴西者近為是也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_85_5","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「事見論語。」","sentenceOrder":5},
  {"id":"s_work_han_thu_85_6","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「懦，柔弱也，音乃喚反，又音儒。」","sentenceOrder":6},
  {"id":"s_work_han_thu_85_7","chapterId":"ch_work_han_thu_85","textTraditional":"漢興有園公、綺里季、夏黃公、甪里先生，〔一〕此四人者，當秦之世，避而入商雒深山，〔二〕以待天下之定也。自高祖聞而召之，不至。其後呂后用留侯計，使皇太子卑辭束帛致禮，安車迎而致之。四人既至，從太子見，高祖客而敬焉，太子得以為重，遂用自安。語在留侯傳。","sentenceOrder":7},
  {"id":"s_work_han_thu_85_8","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「四皓稱號，本起於此，更無姓名可稱知。此蓋隱居之人，匿跡遠害，不自標顯，祕其氏族，故史傳無得而詳。至於後代皇甫謐、圈稱之徒，及諸地理書說，競為四人施安姓字，自相錯互，語又不經，班氏不載於書。諸家皆臆說，今並棄略，一無取焉。」","sentenceOrder":8},
  {"id":"s_work_han_thu_85_9","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「即今之商州商雒縣山也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_85_10","chapterId":"ch_work_han_thu_85","textTraditional":"其後谷口有鄭子真，蜀有嚴君平，〔一〕皆修身自保，非其服弗服，非其食弗食。成帝時，元舅大將軍王鳳以禮聘子真，子真遂不詘而終。君平卜筮於成都巿，以為「卜筮者賤業，而可以惠眾人。有邪惡非正之問，則依蓍龜為言利害。與人子言依於孝，與人弟言依於順，與人臣言依於忠，各因勢導之以善，從吾言者，已過半矣。」裁日閱數人，〔二〕得百錢足自養，則閉肆下簾而授老子。〔三〕博覽亡不通，依老子、嚴周之指著書十餘萬言。〔四〕楊雄少時從遊學，以而仕京師顯名，數為朝廷在位賢者稱君平德。杜陵李彊素善雄，久之為益州牧，喜謂雄曰：「吾真得嚴君平矣。」雄曰：「君備禮以待之，彼人可見而不可得詘也。」彊心以為不然。及至蜀，致禮與相見，卒不敢言以為從事，乃歎曰：「楊子雲誠知人！」君平年九十餘，遂以其業終，蜀人愛敬，至今稱焉。及雄著書言當世士，稱此二人。其論曰：「或問：君子疾沒世而名不稱，〔五〕盍勢諸？名，卿可幾。曰：君子德名為幾。〔六〕梁、齊、楚、趙之君非不富且貴也，〔七〕惡虖成其名！〔八〕谷口鄭子真不詘其志，耕於巖石之下，名震於京師，豈其卿？豈其卿？楚兩龔之絜，其清矣乎！蜀嚴湛冥，〔九〕不作苟見，不治苟得，〔一０〕久幽而不改其操，雖隨、和何以加諸？〔一一〕舉茲以旃，不亦寶乎！」〔一二〕","sentenceOrder":10},
  {"id":"s_work_han_thu_85_11","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「地理志謂君平為嚴遵。三輔決錄云子真名樸，君平名尊，則君平、子真皆其字也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_85_12","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「裁與才同。閱，歷也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_85_13","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「肆者，巿也，列所坐之處也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_85_14","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「嚴周即莊周。」","sentenceOrder":14},
  {"id":"s_work_han_thu_85_15","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「以身沒而無名為病。」","sentenceOrder":15},
  {"id":"s_work_han_thu_85_16","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　孟康曰：「盍，何不也，言何不因名卿之勢以求名。」韋昭曰：「言有勢之名卿，庶幾可不朽。楊子以為不然，唯有德者可以有名。」師古曰：「或人以事有權力之卿，用自表顯，則其名可庶幾而立。楊雄以為自蓄其德，則有名也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_85_17","chapterId":"ch_work_han_thu_85","textTraditional":"〔七〕　師古曰：「謂當時諸侯王也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_85_18","chapterId":"ch_work_han_thu_85","textTraditional":"〔八〕　師古曰：「惡，於何也。惡音烏。」","sentenceOrder":18},
  {"id":"s_work_han_thu_85_19","chapterId":"ch_work_han_thu_85","textTraditional":"〔九〕　孟康曰：「蜀郡嚴君平湛深玄默無欲也。」師古曰：「湛讀曰沈。」","sentenceOrder":19},
  {"id":"s_work_han_thu_85_20","chapterId":"ch_work_han_thu_85","textTraditional":"〔一０〕師古曰：「不為苟顯之行，不事苟得之業。」","sentenceOrder":20},
  {"id":"s_work_han_thu_85_21","chapterId":"ch_work_han_thu_85","textTraditional":"〔一一〕師古曰：「隨，隨侯珠也。和，和氏璧也。諸，之也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_85_22","chapterId":"ch_work_han_thu_85","textTraditional":"〔一二〕師古曰：「旃亦之也。言舉此人而用之，不亦國之寶乎！自此以上皆楊雄之言也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_85_23","chapterId":"ch_work_han_thu_85","textTraditional":"自園公、綺里季、夏黃公、甪里先生、鄭子真、嚴君平皆未嘗仕，然其風聲足以激貪厲俗，近古之逸民也。若王吉、貢禹、兩龔之屬，皆以禮讓進退云。","sentenceOrder":23},
  {"id":"s_work_han_thu_85_24","chapterId":"ch_work_han_thu_85","textTraditional":"王吉字子陽，琅玡皋虞人也。少（時）〔好〕學明經，以郡吏舉孝廉為郎，補若盧右丞，〔一〕遷雲陽令。舉賢良為昌邑中尉，而王好遊獵，驅馳國中，動作亡節，吉上疏諫，曰：","sentenceOrder":24},
  {"id":"s_work_han_thu_85_25","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「少府之屬官有若盧令丞。漢書儀以為主治庫兵者。」","sentenceOrder":25},
  {"id":"s_work_han_thu_85_26","chapterId":"ch_work_han_thu_85","textTraditional":"臣聞古者師日行三十里，吉行五十里。詩云：「匪風發兮，匪車揭兮，顧瞻周道，中心怛兮。」〔一〕說曰：是非古之風也，發發者；是非古之車也，揭揭者。蓋傷之也。〔二〕今者大王幸方與，〔三〕曾不半日而馳二百里，百姓頗廢耕桑，治道牽馬，臣愚以為民不可數變也。〔四〕昔召公述職，〔五〕當民事時，舍於棠下而聽斷焉。〔六〕是時人皆得其所，後世思其仁恩，至虖不伐甘棠，甘棠之詩是也。〔七〕","sentenceOrder":26},
  {"id":"s_work_han_thu_85_27","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「檜國匪風之篇。發發，飄風貌。揭揭，疾驅貌。{制心}，古怛字，傷也。言見此飄風及疾驅，則顧念哀傷，思周道也。揭音丘列反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_85_28","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「今之發發然者非古有道之風也，今之揭揭然者非古有道之車也，故傷之。」","sentenceOrder":28},
  {"id":"s_work_han_thu_85_29","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「縣名也，音房預。」","sentenceOrder":29},
  {"id":"s_work_han_thu_85_30","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「數音所角反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_85_31","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「召讀曰邵。邵公名奭。自陝以西邵公主之。」","sentenceOrder":31},
  {"id":"s_work_han_thu_85_32","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　師古曰：「舍，止息。」","sentenceOrder":32},
  {"id":"s_work_han_thu_85_33","chapterId":"ch_work_han_thu_85","textTraditional":"〔七〕　師古曰：「邵南之詩也，其詩曰：『蔽芾甘棠，勿翦勿伐，邵伯所茇。』蔽芾，小樹貌也。甘棠，杜也。茇，舍也。蔽音必二反。芾音方未反。茇音步末反。」","sentenceOrder":33},
  {"id":"s_work_han_thu_85_34","chapterId":"ch_work_han_thu_85","textTraditional":"大王不好書術而樂逸游，馮式撙銜，〔一〕馳騁不止，口倦乎叱吒，〔二〕手苦於箠轡，〔三〕身勞乎車輿；朝則冒霧露，晝則被塵埃，〔四〕夏則為大暑之所暴炙，冬則為風寒之所匽薄。〔五〕數以耎脆之玉體犯勤勞之煩毒，〔六〕非所以全壽命之宗也，〔七〕又非所以進仁義之隆也。〔八〕","sentenceOrder":34},
  {"id":"s_work_han_thu_85_35","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　臣瓚曰：「撙，促也。」師古曰：「撙，挫也，音子本反。」","sentenceOrder":35},
  {"id":"s_work_han_thu_85_36","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「咤亦吒字也，音竹駕反。」","sentenceOrder":36},
  {"id":"s_work_han_thu_85_37","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「箠，馬策，音止橤反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_85_38","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「冒，犯也，音莫克反。」","sentenceOrder":38},
  {"id":"s_work_han_thu_85_39","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「匽與偃同，言遇疾風則偃靡也。薄，迫也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_85_40","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　師古曰：「耎，柔也，音而兗反。」","sentenceOrder":40},
  {"id":"s_work_han_thu_85_41","chapterId":"ch_work_han_thu_85","textTraditional":"〔七〕　師古曰：「宗，尊也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_85_42","chapterId":"ch_work_han_thu_85","textTraditional":"〔八〕　師古曰：「隆，高也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_85_43","chapterId":"ch_work_han_thu_85","textTraditional":"夫廣夏之下，細旃之上，〔一〕明師居前，勸誦在後，上論唐虞之際，下及殷周之盛，考仁聖之風，習治國之道，訢訢焉發憤忘食，日新厥德，〔二〕其樂豈徒銜橛之間哉！〔三〕休則俛仰詘信以利形，〔四〕進退步趨以實下，〔五〕吸新吐故以練臧，專意積精以適神，〔六〕於以養生，豈不長哉！大王誠留意如此，則心有堯舜之志，體有喬松之壽，〔七〕美聲廣譽登而上聞，則福祿其轃而社稷安矣。〔八〕","sentenceOrder":43},
  {"id":"s_work_han_thu_85_44","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「廣夏，大屋也。旃與氈同。」","sentenceOrder":44},
  {"id":"s_work_han_thu_85_45","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「訢，古欣字。」","sentenceOrder":45},
  {"id":"s_work_han_thu_85_46","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「銜，馬銜也。橛，車鉤心也。張揖以橛為馬之長銜，非也。橛音其月反。」","sentenceOrder":46},
  {"id":"s_work_han_thu_85_47","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「形，體也。信讀曰伸。」","sentenceOrder":47},
  {"id":"s_work_han_thu_85_48","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　如淳曰：「今人不行，則膝已下虛弱不實。」","sentenceOrder":48},
  {"id":"s_work_han_thu_85_49","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　師古曰：「臧，五臧也。練，練其氣也。適，和也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_85_50","chapterId":"ch_work_han_thu_85","textTraditional":"〔七〕　師古曰：「喬松，仙人伯喬及赤松子也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_85_51","chapterId":"ch_work_han_thu_85","textTraditional":"〔八〕　師古曰：「轃與臻同。臻，至也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_85_52","chapterId":"ch_work_han_thu_85","textTraditional":"皇帝仁聖，至今思慕未怠，〔一〕於宮館囿池弋獵之樂未有所幸，大王宜夙夜念此，以承聖意。諸侯骨肉，莫親大王，大王於屬則子也，於位則臣也，一身而二任之責加焉，恩愛行義孅介有不具者，於以上聞，非饗國之福也。臣吉愚戇，願大王察之。","sentenceOrder":52},
  {"id":"s_work_han_thu_85_53","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「皇帝謂昭帝也。言武帝晏駕未久，故尚思慕。」","sentenceOrder":53},
  {"id":"s_work_han_thu_85_54","chapterId":"ch_work_han_thu_85","textTraditional":"王賀雖不遵道，然猶知敬禮吉，乃下令曰：「寡人造行不能無惰，中（慰）〔尉〕甚忠，數輔吾過。使謁者千秋賜中尉牛肉五百斤，酒五石，脯五束。」其後復放從自若。〔一〕吉輒諫爭，甚得輔弼之義，雖不治民，國中莫不敬重焉。","sentenceOrder":54},
  {"id":"s_work_han_thu_85_55","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「從音子用反。」","sentenceOrder":55},
  {"id":"s_work_han_thu_85_56","chapterId":"ch_work_han_thu_85","textTraditional":"久之，昭帝崩，亡嗣，大將軍霍光秉政，遣大鴻臚宗正迎昌邑王。吉即奏書戒王曰：「臣聞高宗諒闇，三年不言。〔一〕今大王以喪事徵，宜日夜哭泣悲哀而已，慎毋有所發。〔二〕且何獨喪事，凡南面之君何言哉？天不言，四時行焉，百物生焉，〔三〕願大王察之。大將軍仁愛勇智，忠信之德天下莫不聞，事孝武皇帝二十餘年未嘗有過。先帝棄群臣，屬以天下，寄幼孤焉，〔四〕大將軍抱持幼君襁褓之中，布政施教，海內晏然，雖周公、伊尹亡以加也。今帝崩亡嗣，大將軍惟思可以奉宗廟者，攀援而立大王，〔五〕其仁厚豈有量哉！〔六〕臣願大王事之敬之，政事壹聽之，大王垂拱南面而已。願留意，（嘗）〔常〕以為念。」","sentenceOrder":56},
  {"id":"s_work_han_thu_85_57","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「已解於上。」","sentenceOrder":57},
  {"id":"s_work_han_thu_85_58","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「發謂興舉眾事。」","sentenceOrder":58},
  {"id":"s_work_han_thu_85_59","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「論語稱孔子曰『天何言哉？四時行焉，百物生焉。天何言哉？』故吉引之。」","sentenceOrder":59},
  {"id":"s_work_han_thu_85_60","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「屬音之欲反。」","sentenceOrder":60},
  {"id":"s_work_han_thu_85_61","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「援，引也，音爰。」","sentenceOrder":61},
  {"id":"s_work_han_thu_85_62","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　師古曰：「言其深多也。量音力向反。」","sentenceOrder":62},
  {"id":"s_work_han_thu_85_63","chapterId":"ch_work_han_thu_85","textTraditional":"王既到，即位二十餘日以行淫亂廢。昌邑群臣坐在國時不舉奏王罪過，令漢朝不聞知，又不能輔道，陷王大惡，〔一〕皆下獄誅。唯吉與郎中令龔遂以忠直數諫正得減死，髡為城旦。","sentenceOrder":63},
  {"id":"s_work_han_thu_85_64","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「道讀曰導。」","sentenceOrder":64},
  {"id":"s_work_han_thu_85_65","chapterId":"ch_work_han_thu_85","textTraditional":"起家復為益州刺史，病去官，復徵為博士諫大夫。是時宣帝頗修武帝故事，宮室車服盛於昭帝。時外戚許、史、王氏貴寵，而上躬親政事，任用能吏。吉上疏言得失，曰：","sentenceOrder":65},
  {"id":"s_work_han_thu_85_66","chapterId":"ch_work_han_thu_85","textTraditional":"陛下躬聖質，總萬方，帝王圖籍日陳于前，惟思世務，將興太平。詔書每下，民欣然若更生。臣伏而思之，可謂至恩，未可謂本務也。〔一〕","sentenceOrder":66},
  {"id":"s_work_han_thu_85_67","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「言天子如此，雖於百姓為至恩，然未盡政務之本也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_85_68","chapterId":"ch_work_han_thu_85","textTraditional":"欲治之主不世出，〔一〕公卿幸得遭遇其時，言聽諫從，然未有建萬世之長策，舉明主於三代之隆者也。〔二〕其務在於期會簿書，斷獄聽訟而已，此非太平之基也。","sentenceOrder":68},
  {"id":"s_work_han_thu_85_69","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「言有時遇之不常值。」","sentenceOrder":69},
  {"id":"s_work_han_thu_85_70","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「三代，夏、殷、周。」","sentenceOrder":70},
  {"id":"s_work_han_thu_85_71","chapterId":"ch_work_han_thu_85","textTraditional":"臣聞聖王宣德流化，必自近始。朝廷不備，難以言治；左右不正，難以化遠。民者，弱而不可勝，愚而不可欺也。聖主獨行於深宮，得則天下稱誦之，失則天下咸言之。行發於近，必見於遠，故謹選左右，審擇所使；左右所以正身也，所使所以宣德也。詩云：「濟濟多士，文王以寧。」〔一〕此其本也。","sentenceOrder":71},
  {"id":"s_work_han_thu_85_72","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「大雅文王之詩。」","sentenceOrder":72},
  {"id":"s_work_han_thu_85_73","chapterId":"ch_work_han_thu_85","textTraditional":"春秋所以大一統者，六合同風，九州共貫也。〔一〕今俗吏所以牧民者，非有禮義科指可世世通行者也，獨設刑法以守之。其欲治者，不知所繇，〔二〕以意穿鑿，各取一切，權譎自在，故一變之後不可復修也。〔三〕是以百里不同風，千里不同俗，戶異政，人殊服，詐偽萌生，刑罰亡極，〔四〕質樸日銷，恩愛寖薄。〔五〕孔子曰「安上治民，莫善於禮」，〔六〕非空言也。王者未制禮之時，引先王禮宜於今者而用之。臣願陛下承天心，發大業，與公卿大臣延及儒生，述舊禮，明王制，驅一世之民濟之仁壽之域，〔七〕則俗何以不若成康，壽何以不若高宗？〔八〕竊見當世趨務不合於道者，謹條奏，〔九〕唯陛下財擇焉。〔一０〕","sentenceOrder":73},
  {"id":"s_work_han_thu_85_74","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「解在董仲舒傳。」","sentenceOrder":74},
  {"id":"s_work_han_thu_85_75","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「繇與由同。」","sentenceOrder":75},
  {"id":"s_work_han_thu_85_76","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「言其敝深難久行。」","sentenceOrder":76},
  {"id":"s_work_han_thu_85_77","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「萌生，言其爭出，如草木之初生。」","sentenceOrder":77},
  {"id":"s_work_han_thu_85_78","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「寖，漸也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_85_79","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　師古曰：「孝經載孔子之言。」","sentenceOrder":79},
  {"id":"s_work_han_thu_85_80","chapterId":"ch_work_han_thu_85","textTraditional":"〔七〕　師古曰：「以仁撫下，則群生安逸而壽考。」","sentenceOrder":80},
  {"id":"s_work_han_thu_85_81","chapterId":"ch_work_han_thu_85","textTraditional":"〔八〕　師古曰：「高宗，殷王武丁也，享國百年。」","sentenceOrder":81},
  {"id":"s_work_han_thu_85_82","chapterId":"ch_work_han_thu_85","textTraditional":"〔九〕　師古曰：「趨讀曰趣。趣，向也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_85_83","chapterId":"ch_work_han_thu_85","textTraditional":"〔一０〕師古曰：「財與裁同。」","sentenceOrder":83},
  {"id":"s_work_han_thu_85_84","chapterId":"ch_work_han_thu_85","textTraditional":"吉意以為「夫婦，人倫大綱，夭壽之萌也。〔一〕世俗嫁娶太早，未知為人父母之道而有子，是以教化不明而民多夭。聘妻送女亡節，則貧人不及，故不舉子。又漢家列侯尚公主，諸侯則國人承翁主，〔二〕使男事女，夫詘於婦，逆陰陽之位，故多女亂。古者衣服車馬貴賤有章，以褒有德而別尊卑，今上下僭差，人人自制，〔三〕是以貪財（趨）〔誅〕利，不畏死亡。周之所以能致治，刑措而不用者，以其禁邪於冥冥，絕惡於未萌也。」〔四〕又言「舜、湯不用三公九卿之世而舉皋陶、伊尹，〔五〕不仁者遠。〔六〕今使俗吏得任子弟，〔七〕率多驕驁，不通古今，〔八〕至於積功治人，亡益於民，此伐檀所為作也。〔九〕宜明選求賢，除任子之令。外家及故人可厚以財，不宜居位。去角抵，減樂府，省尚方，〔一０〕明視天下以儉。〔一一〕古者工不造琱瑑，商不通侈靡，〔一二〕非工商之獨賢，政教使之然也。民見儉則歸本，本立而末成。」其指如此，上以其言迂闊，不甚寵異也。〔一三〕吉遂謝病歸琅邪。","sentenceOrder":84},
  {"id":"s_work_han_thu_85_85","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「由之而生，故云萌。」","sentenceOrder":85},
  {"id":"s_work_han_thu_85_86","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　晉灼曰：「娶天子女則曰尚公主。國人娶諸侯女曰承翁主。尚承皆卑下之名也。」師古曰：「翁主者，言其父自主婚也。解具在高紀。」","sentenceOrder":86},
  {"id":"s_work_han_thu_85_87","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「言無節度。」","sentenceOrder":87},
  {"id":"s_work_han_thu_85_88","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「冥冥，言未有端緒。」","sentenceOrder":88},
  {"id":"s_work_han_thu_85_89","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　李奇曰：「不繼世而爵也。言皋陶、伊尹非三公九卿之世。」","sentenceOrder":89},
  {"id":"s_work_han_thu_85_90","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　師古曰：「任用賢人，放黜讒佞。」","sentenceOrder":90},
  {"id":"s_work_han_thu_85_91","chapterId":"ch_work_han_thu_85","textTraditional":"〔七〕　張晏曰：「子弟以父兄任為郎。」","sentenceOrder":91},
  {"id":"s_work_han_thu_85_92","chapterId":"ch_work_han_thu_85","textTraditional":"〔八〕　師古曰：「驁與傲同。」","sentenceOrder":92},
  {"id":"s_work_han_thu_85_93","chapterId":"ch_work_han_thu_85","textTraditional":"〔九〕　師古曰：「伐檀，詩篇名，刺不用賢也，在魏國風也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_85_94","chapterId":"ch_work_han_thu_85","textTraditional":"〔一０〕師古曰：「尚方主巧作。」","sentenceOrder":94},
  {"id":"s_work_han_thu_85_95","chapterId":"ch_work_han_thu_85","textTraditional":"〔一一〕師古曰：「視讀曰示。」","sentenceOrder":95},
  {"id":"s_work_han_thu_85_96","chapterId":"ch_work_han_thu_85","textTraditional":"〔一二〕師古曰：「瑑者，刻鏤為文。瑑音篆。」","sentenceOrder":96},
  {"id":"s_work_han_thu_85_97","chapterId":"ch_work_han_thu_85","textTraditional":"〔一三〕師古曰：「迂，遠也，音于。」","sentenceOrder":97},
  {"id":"s_work_han_thu_85_98","chapterId":"ch_work_han_thu_85","textTraditional":"始吉少時學問，居長安。東家有大棗樹垂吉庭中，吉婦取棗以啖吉。〔一〕吉後知之，乃去婦。東家聞而欲伐其樹，鄰里共止之，因固請吉令還婦。里中為之語曰：「東家有樹，王陽婦去；東家棗完，去婦復還。」其厲志如此。","sentenceOrder":98},
  {"id":"s_work_han_thu_85_99","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「啖謂使食之，音徒濫反。啖亦啗字耳。此義與高紀『啗以利』同。」","sentenceOrder":99},
  {"id":"s_work_han_thu_85_100","chapterId":"ch_work_han_thu_85","textTraditional":"吉與貢禹為友，世稱「王陽在位，貢公彈冠」，〔一〕言其取舍同也。〔二〕元帝初即位，遣使者徵貢禹與吉。吉年老，道病卒，上悼之，復遣使者弔祠云。","sentenceOrder":100},
  {"id":"s_work_han_thu_85_101","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「彈冠者，且入仕也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_85_102","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「取，進趣也。舍，止息也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_85_103","chapterId":"ch_work_han_thu_85","textTraditional":"初，吉兼通五經，能為騶氏春秋，以詩、論語教授，好梁丘賀說易，令子駿受焉。駿以孝廉為郎。左曹陳咸薦駿賢父子，經明行修，宜顯以厲俗。光祿勳匡衡亦舉駿有專對材。〔一〕遷諫大夫，使責淮陽憲王。〔二〕遷趙內史。吉坐昌邑王被刑後，戒子孫毋為王國吏，故駿道病，免官歸。起家復為幽州刺史，遷司隸校尉，奏免丞相匡衡，遷少府。八歲，成帝欲大用之，出駿為京兆尹，試以政事。先是京兆有趙廣漢、張敞、王尊、王章，至駿皆有能名，故京師稱曰：「前有趙、張，後有三王。」而薛宣從左馮翊代駿為少府，會御史大夫缺，谷永奏言：「聖王不以名譽加於實效。〔三〕考績用人之法，〔四〕薛宣政事已試。」〔五〕上然其議。宣為少府月餘，遂超御史大夫，至丞相。駿乃代宣為御史大夫，並居位。六歲病卒，翟方進代駿為大夫。數月，薛宣免，遂代為丞相。眾人為駿恨不得封侯。駿為少府時，妻死，因不復娶，或問之，駿曰：「德非曾參，子非華、元〔六〕，亦何敢娶？」","sentenceOrder":103},
  {"id":"s_work_han_thu_85_104","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「專對謂見問即對，無所疑也。論語稱孔子曰：『使於四方，不能專對，雖多亦奚以為？』」","sentenceOrder":104},
  {"id":"s_work_han_thu_85_105","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「以其有口辭。」","sentenceOrder":105},
  {"id":"s_work_han_thu_85_106","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「言不聽虛名。」","sentenceOrder":106},
  {"id":"s_work_han_thu_85_107","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「言用人之法，皆須考以功績。」","sentenceOrder":107},
  {"id":"s_work_han_thu_85_108","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「言有效也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_85_109","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　如淳曰：「華與元，曾參之二子也。韓詩外傳曰曾參喪妻不更娶，人問其故，曾子曰：『以華、元善人也。』一曰曾參之子字華元。」師古曰：「二子是也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_85_110","chapterId":"ch_work_han_thu_85","textTraditional":"駿子崇以父任為郎，歷刺史、郡守，治有能名。建平三年，以河南太守徵入為御史大夫數月。是時成帝舅安成恭侯夫人放寡居，共養長信宮，〔一〕坐祝詛下獄，崇奏封事，為放言。放外家解氏與崇為昏，〔二〕哀帝以崇為不忠誠，策詔崇曰：「朕以君有累世之美，故踰列次。〔三〕在位以來，忠誠匡國未聞所繇，〔四〕反懷詐諼之辭，〔五〕欲以攀救舊姻之家，大逆之辜，舉錯專恣，〔六〕不遵法度，亡以示百僚。」左遷為大司農，後徙衛尉左將軍。平帝即位，王莽秉政，大司空彭宣乞骸骨罷，崇代為大司空，封扶平侯。歲餘，崇復謝病乞骸骨，皆避王莽，莽遣就國。歲餘，為傅婢所毒，薨，國除。〔七〕","sentenceOrder":110},
  {"id":"s_work_han_thu_85_111","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「放者，夫人之名也。共音居用反。養音弋亮反。」","sentenceOrder":111},
  {"id":"s_work_han_thu_85_112","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「婚姻之家。」","sentenceOrder":112},
  {"id":"s_work_han_thu_85_113","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「謂自祖及身皆有名也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_85_114","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「繇與由同。由，從也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_85_115","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「諼，詐言也，音虛袁反。」","sentenceOrder":115},
  {"id":"s_work_han_thu_85_116","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　師古曰：「錯，置也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_85_117","chapterId":"ch_work_han_thu_85","textTraditional":"〔七〕　師古曰：「凡言傅婢者，謂傅相其衣服衽席之事。一說傅曰附，謂近幸也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_85_118","chapterId":"ch_work_han_thu_85","textTraditional":"自吉至崇，世名清廉，然材器名稱稍不能及父，而祿位彌隆。皆好車馬衣服，其自奉養極為鮮明，而亡金銀錦繡之物。及遷徙去處，所載不過囊衣，〔一〕不畜積餘財。〔二〕去位家居，亦布衣疏食。天下服其廉而怪其奢，故俗傳「王陽能作黃金」。〔三〕","sentenceOrder":118},
  {"id":"s_work_han_thu_85_119","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「一囊之衣也。有底曰囊，無底曰橐。」","sentenceOrder":119},
  {"id":"s_work_han_thu_85_120","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「畜讀曰蓄。」","sentenceOrder":120},
  {"id":"s_work_han_thu_85_121","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「以其無所求取，不營產業而車服鮮明，故謂自作黃金以給用。」","sentenceOrder":121},
  {"id":"s_work_han_thu_85_122","chapterId":"ch_work_han_thu_85","textTraditional":"貢禹字少翁，琅邪人也。以明經絜行著聞，徵為博士，涼州刺史，病去官。復舉賢良為河南令。歲餘，以職事為府官所責，〔一〕免冠謝。禹曰：「冠壹免，安復可冠也！」遂去官。","sentenceOrder":122},
  {"id":"s_work_han_thu_85_123","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「太守之府。」","sentenceOrder":123},
  {"id":"s_work_han_thu_85_124","chapterId":"ch_work_han_thu_85","textTraditional":"元帝初即位，徵禹為諫大夫，數虛己問以政事。〔一〕是時年歲不登，郡國多困，禹奏言：","sentenceOrder":124},
  {"id":"s_work_han_thu_85_125","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「虛己謂聽受其言也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_85_126","chapterId":"ch_work_han_thu_85","textTraditional":"古者宮室有制，宮女不過九人，秣馬不過八匹；〔一〕牆塗而不琱，木摩而不刻，〔二〕車輿器物皆不文畫，苑囿不過數十里，與民共之；任賢使能，什一而稅，亡它賦斂繇戍之役，使民歲不過三日，千里之內自給，千里之外各置貢職而已。〔三〕故天下家給人足，頌聲並作。","sentenceOrder":126},
  {"id":"s_work_han_thu_85_127","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「秣，養也，謂以粟米（飯）〔飤〕也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_85_128","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「琱字與彫同。彫，畫也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_85_129","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「言天子以畿內賦斂自供，千里之外令其以時入貢，不欲煩勞也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_85_130","chapterId":"ch_work_han_thu_85","textTraditional":"至高祖、孝文、孝景皇帝，循古節儉，宮女不過十餘，廄馬百餘匹。孝文皇帝衣綈履革，〔一〕器亡琱文金銀之飾。後世爭為奢侈，轉轉益（盛）〔甚〕，臣下亦相放效，〔二〕衣服履絝刀劍亂於主上，〔三〕主上時臨朝入廟，眾人不能別異，甚非其宜。然非自知奢僭也，猶魯昭公曰：「吾何僭矣？」","sentenceOrder":130},
  {"id":"s_work_han_thu_85_131","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「娣，厚繒，音徒奚反。」","sentenceOrder":131},
  {"id":"s_work_han_thu_85_132","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「放音甫往反。其下亦同。」","sentenceOrder":132},
  {"id":"s_work_han_thu_85_133","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「絝，古袴字。」","sentenceOrder":133},
  {"id":"s_work_han_thu_85_134","chapterId":"ch_work_han_thu_85","textTraditional":"今大夫僭諸侯，諸侯僭天子，天子過天道，其日久矣。承衰救亂，矯復古化，在於陛下。〔一〕臣愚以為盡如太古難，宜少放古以自節焉。論語曰：「君子樂節禮樂。」〔二〕方今宮室已定，亡可奈何矣，其餘盡可減損。故時齊三服官輸物不過十笥，〔三〕方今齊三服官作工各數千人，一歲費數鉅萬。蜀廣漢主金銀器，歲各用五百萬。三工官官費五千萬，〔四〕東西織室亦然。廄馬食粟將萬匹。臣禹嘗從之東宮，〔五〕見賜杯案，盡文畫金銀飾，非當所以賜食臣下也。〔六〕東宮之費亦不可勝計。天下之民所為大飢餓死者，是也。今民大飢而死，死又不葬，為犬豬（所）食。〔七〕人至相食，而廄馬食粟，苦其大肥，氣盛怒至，乃日步作之。〔八〕王者受命於天，為民父母，固當若此乎！天不見邪？武帝時，又多取好女至數千人，以填後宮。〔九〕及棄天下，昭帝幼弱，霍光專事，不知禮正，妄多臧金錢財物，鳥獸魚鱉牛馬虎豹生禽，凡百九十物，盡瘞臧之，又皆以後宮女置於園陵，大失禮，逆天心，又未必稱武帝意也。昭帝晏駕，光復行之。至孝宣皇帝時，陛下（烏）〔惡〕有所言，〔一０〕群臣亦隨故事，甚可痛也！故使天下承化，取女皆大過度，〔一一〕諸侯妻妾或至數百人，豪富吏民畜歌者至數十人，是以內多怨女，外多曠夫。〔一二〕及眾庶葬埋，皆虛地上以實地下。其過自上生，〔一三〕皆在大臣循故事之罪也。","sentenceOrder":134},
  {"id":"s_work_han_thu_85_135","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「正曲曰矯。復音方目反。」","sentenceOrder":135},
  {"id":"s_work_han_thu_85_136","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「論語稱孔子曰『益者三樂，樂節禮樂，樂道人之善，樂多賢友』也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_85_137","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「三服官主作天子之服，在齊地。笥，盛衣竹器，音先嗣反。」","sentenceOrder":137},
  {"id":"s_work_han_thu_85_138","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　如淳曰：「地理志河內懷、蜀郡成都、廣漢皆有工官。工官，主作漆器物者也。」師古曰：「如說非也。三工官，謂少府之屬官，考工室也，右工室也，東園匠也。上已言蜀漢主金銀器，是不入三工之數也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_85_139","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「從天子往太后宮。」","sentenceOrder":139},
  {"id":"s_work_han_thu_85_140","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　師古曰：「食讀曰飤。」","sentenceOrder":140},
  {"id":"s_work_han_thu_85_141","chapterId":"ch_work_han_thu_85","textTraditional":"〔七〕　師古曰：「食人之骸骨。」","sentenceOrder":141},
  {"id":"s_work_han_thu_85_142","chapterId":"ch_work_han_thu_85","textTraditional":"〔八〕　師古曰：「日日行步而動作之，以散充溢之氣。」","sentenceOrder":142},
  {"id":"s_work_han_thu_85_143","chapterId":"ch_work_han_thu_85","textTraditional":"〔九〕　師古曰：「此填字讀與寘同。」","sentenceOrder":143},
  {"id":"s_work_han_thu_85_144","chapterId":"ch_work_han_thu_85","textTraditional":"〔一０〕師古曰：「不能自言減省之事。」","sentenceOrder":144},
  {"id":"s_work_han_thu_85_145","chapterId":"ch_work_han_thu_85","textTraditional":"〔一一〕師古曰：「取讀曰娶。」","sentenceOrder":145},
  {"id":"s_work_han_thu_85_146","chapterId":"ch_work_han_thu_85","textTraditional":"〔一二〕師古曰：「曠，空也。室家空也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_85_147","chapterId":"ch_work_han_thu_85","textTraditional":"〔一三〕師古曰：「自，從也。上謂天子也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_85_148","chapterId":"ch_work_han_thu_85","textTraditional":"唯陛下深察古道，從其儉者，大減損乘輿服御器物，三分去二。子產多少有命，審察後宮，擇其賢者留二十人，餘悉歸之。〔一〕及諸陵園女亡子者，宜悉遣。獨杜陵宮人數百，誠可哀憐也。廄馬可亡過數十匹。獨舍長安城南苑地以為田獵之囿，〔二〕自城西南至山西至鄠皆復其田，以與貧民。〔三〕方今天下飢饉，可亡大自損減以救之，稱天意乎？天生聖人，蓋為萬民，非獨使自娛樂而已也。故詩曰：「天難諶斯，不易惟王；」「上帝臨女，毋貳爾心。」〔四〕「當仁不讓」，〔五〕獨可以聖心參諸天地，揆之往古，〔六〕不可與臣下議也。若其阿意順指，隨君上下，〔七〕臣禹不勝拳拳，不敢不盡愚心。〔八〕","sentenceOrder":148},
  {"id":"s_work_han_thu_85_149","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「言人產子多少自有定命，非由廣妾媵也，故請止留二十人。」","sentenceOrder":149},
  {"id":"s_work_han_thu_85_150","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「舍，置也。獨留置之，其餘皆廢去。」","sentenceOrder":150},
  {"id":"s_work_han_thu_85_151","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「復音方目反。」","sentenceOrder":151},
  {"id":"s_work_han_thu_85_152","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「大雅大明之詩也。諶，誠也。上帝亦天也。言承天之意，此誠難也。王者之命不妄改易，天常降監，信可畏也，毋貳爾心，機事易失，勿猶豫也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_85_153","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「論語稱孔子曰『當仁不讓於師』，故引之。」","sentenceOrder":153},
  {"id":"s_work_han_thu_85_154","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　師古曰：「揆，度也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_85_155","chapterId":"ch_work_han_thu_85","textTraditional":"〔七〕　師古曰：「上下猶言高下，謂苟順從也。上音時掌反。」","sentenceOrder":155},
  {"id":"s_work_han_thu_85_156","chapterId":"ch_work_han_thu_85","textTraditional":"〔八〕　師古曰：「拳拳，解在劉向傳。下鮑宣傳。（倦倦）〔惓惓〕音義亦同。」","sentenceOrder":156},
  {"id":"s_work_han_thu_85_157","chapterId":"ch_work_han_thu_85","textTraditional":"天子納善其忠，乃下詔令太僕減食穀馬，水衡減食肉獸，省宜春下苑以與貧民，又罷角抵諸戲及齊三服官。遷禹為光祿大夫。","sentenceOrder":157},
  {"id":"s_work_han_thu_85_158","chapterId":"ch_work_han_thu_85","textTraditional":"頃之，禹上書曰：「臣禹年老貧窮，家訾不滿萬錢，妻子穅豆不贍，裋褐不完。〔一〕有田百三十畝，陛下過意徵臣，〔二〕臣賣田百畝以供車馬。至，拜為諫大夫，秩八百石，奉錢月九千二百。〔三〕廩食太官，〔四〕又蒙賞賜四時雜繒綿絮衣服酒肉諸果物，德厚甚深。疾病侍醫臨治，〔五〕賴陛下神靈，不死而活。又拜為光祿大夫，秩二千石，奉錢月萬二千。祿賜愈多，家日以益富，身日以益尊，誠非屮茅愚臣所當蒙也。〔六〕伏自念終亡以報厚（恩）〔德〕，日夜慚愧而已。臣禹犬馬之齒八十一，血氣衰竭，耳目不聰明，非復能有補益，所謂素餐尸祿洿朝之臣也。〔七〕自痛去家三千里，凡有一子，年十二，非有在家為臣具棺槨者也。誠恐一旦蹎仆氣竭，不復自還，〔八〕洿席薦於宮室，骸骨棄捐，孤魂不歸。不勝私願，願乞骸骨，及身生歸鄉里，〔九〕死亡所恨。」","sentenceOrder":158},
  {"id":"s_work_han_thu_85_159","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「裋者，謂僮豎所著布長襦也。褐，毛布之衣也。裋音豎。」","sentenceOrder":159},
  {"id":"s_work_han_thu_85_160","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「過猶誤也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_85_161","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「奉音扶用反。其下亦同。」","sentenceOrder":161},
  {"id":"s_work_han_thu_85_162","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「謂太官給其食。」","sentenceOrder":162},
  {"id":"s_work_han_thu_85_163","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「侍醫，天子之醫也。」","sentenceOrder":163},
  {"id":"s_work_han_thu_85_164","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　師古曰：「屮，古草字。」","sentenceOrder":164},
  {"id":"s_work_han_thu_85_165","chapterId":"ch_work_han_thu_85","textTraditional":"〔七〕　師古曰：「洿與污同，音一故反。」","sentenceOrder":165},
  {"id":"s_work_han_thu_85_166","chapterId":"ch_work_han_thu_85","textTraditional":"〔八〕　師古曰：「蹎音顛，蹶躓也。仆音赴。仆，頓也。不自還者，遂死也。還讀曰旋。」","sentenceOrder":166},
  {"id":"s_work_han_thu_85_167","chapterId":"ch_work_han_thu_85","textTraditional":"〔九〕　師古曰：「及身生，謂及未死之前。」","sentenceOrder":167},
  {"id":"s_work_han_thu_85_168","chapterId":"ch_work_han_thu_85","textTraditional":"天子報曰：「朕以生有伯夷之廉，史魚之直，〔一〕守經據古，不阿當世，孳孳於民，俗之所寡，〔二〕故親近生，幾參國政。〔三〕今未得久聞生之奇論也，而云欲退，意豈有所恨與？〔四〕將在位者與生殊乎？〔五〕往者嘗令金敞語生，欲及生時祿生之子，既已諭矣，今復云子少。夫以王命辨護生家，雖百子何以加？傳曰亡懷土，〔六〕何必思故鄉！生其強飯慎疾以自輔。」後月餘，以禹為長信少府。會御史大夫陳萬年卒，禹代為御史大夫，列於三公。","sentenceOrder":168},
  {"id":"s_work_han_thu_85_169","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「生謂先生也。史魚，衛大夫史鰌也。論語稱孔子曰『直哉史魚，邦有道如矢，邦無道如矢』，言其壹志。」","sentenceOrder":169},
  {"id":"s_work_han_thu_85_170","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「孳與孜同。孜孜，不怠也。寡，少也，言少有此人。」","sentenceOrder":170},
  {"id":"s_work_han_thu_85_171","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「幾讀曰冀。」","sentenceOrder":171},
  {"id":"s_work_han_thu_85_172","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「與讀曰歟。」","sentenceOrder":172},
  {"id":"s_work_han_thu_85_173","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「言志趣不同。」","sentenceOrder":173},
  {"id":"s_work_han_thu_85_174","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　師古曰：「論語孔子曰：『君子懷德，小人懷土。』」","sentenceOrder":174},
  {"id":"s_work_han_thu_85_175","chapterId":"ch_work_han_thu_85","textTraditional":"自禹在位，數言得失，書數十上。禹以為古民亡賦算口錢，起武帝征伐四夷，重賦於民，民產子三歲則出口錢，故民重困，〔一〕至於生子輒殺，甚可悲痛。宜令兒七歲去齒乃出口錢，年二十乃算。","sentenceOrder":175},
  {"id":"s_work_han_thu_85_176","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「重音直用反。」","sentenceOrder":176},
  {"id":"s_work_han_thu_85_177","chapterId":"ch_work_han_thu_85","textTraditional":"又言古者不以金錢為幣，專意於農，故一夫不耕，必有受其飢者。今漢家鑄錢，及諸鐵官皆置吏卒徒，攻山取銅鐵，一歲功十萬人已上，中農食七人，是七十萬人常受其飢也。鑿地數百丈，銷陰氣之精，地臧空虛，不能含氣出雲，斬伐林木亡有時禁，水旱之災未必不繇此也。〔一〕自五銖錢起已來七十餘年，民坐盜鑄錢被刑者眾，富人積錢滿室，猶亡厭足。民心（搖動）〔動搖〕，商賈求利，東西南北各用智巧，好衣美食，歲有十二之利，〔二〕而不出租稅。農夫父子暴露中野，不避寒暑，捽屮杷土，手足胼胝，〔三〕已奉穀租，又出槁稅，〔四〕鄉部私求，不可勝供。〔五〕故民棄本逐末，耕者不能半。貧民雖賜之田，猶賤賣以賈，〔六〕窮則起為盜賊。何者？末利深而惑於錢也。是以姦邪不可禁，其原皆起於錢也。疾其末者絕其本，宜罷採珠玉金銀鑄錢之官，亡復以為幣。市井勿得販賣，〔七〕除其租銖之律，〔八〕租稅祿賜皆以布帛及穀。使百姓壹歸於農，復古道便。〔九〕","sentenceOrder":177},
  {"id":"s_work_han_thu_85_178","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「繇讀與由同。」","sentenceOrder":178},
  {"id":"s_work_han_thu_85_179","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「若有萬錢為賈，則獲二千之利。」","sentenceOrder":179},
  {"id":"s_work_han_thu_85_180","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「捽，拔取也。屮，古草字也。杷，手掊之也。胼，併也。胝，繭也。捽音才兀反。杷音蒲巴反，其字從木。胼音步千反。胝音竹尸反。掊音蒲交反。」","sentenceOrder":180},
  {"id":"s_work_han_thu_85_181","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「槁，禾稈也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_85_182","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「言鄉部之吏又私有所求，不能供之。」","sentenceOrder":182},
  {"id":"s_work_han_thu_85_183","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　師古曰：「賣田與人而更為商賈之業。」","sentenceOrder":183},
  {"id":"s_work_han_thu_85_184","chapterId":"ch_work_han_thu_85","textTraditional":"〔七〕　師古曰：「賤買貴賣曰販。」","sentenceOrder":184},
  {"id":"s_work_han_thu_85_185","chapterId":"ch_work_han_thu_85","textTraditional":"〔八〕　師古曰：「租稅之法皆依田畝，不得雜計百物之銖兩。」","sentenceOrder":185},
  {"id":"s_work_han_thu_85_186","chapterId":"ch_work_han_thu_85","textTraditional":"〔九〕　師古曰：「追遵古法，於事便也。復音扶目反。」","sentenceOrder":186},
  {"id":"s_work_han_thu_85_187","chapterId":"ch_work_han_thu_85","textTraditional":"又言諸離宮及長樂宮衛可減其太半，以寬繇役。〔一〕又諸官奴婢十萬餘人戲遊亡事，稅良民以給之，歲費五六鉅萬，宜免為庶人，廩食，〔二〕令代關東戍卒，乘北邊亭塞候望。〔三〕","sentenceOrder":187},
  {"id":"s_work_han_thu_85_188","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「繇讀曰傜。」","sentenceOrder":188},
  {"id":"s_work_han_thu_85_189","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「給其食。」","sentenceOrder":189},
  {"id":"s_work_han_thu_85_190","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「乘，登也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_85_191","chapterId":"ch_work_han_thu_85","textTraditional":"又欲令近臣自諸曹侍中以上，家亡得私販賣，與民爭利，犯者輒免官削爵，不得仕宦。禹又言：","sentenceOrder":191},
  {"id":"s_work_han_thu_85_192","chapterId":"ch_work_han_thu_85","textTraditional":"孝文皇帝時，貴廉絜，賤貪汙，賈人贅婿及吏坐贓者皆禁錮不得為吏，賞善罰惡，不阿親戚，罪白者伏其誅，〔一〕疑者以與民，〔二〕亡贖罪之法，故令行禁止，海內大化，天下斷獄四百，與刑錯亡異。武帝始臨天下，尊賢用士，闢地廣境數千里，自見功大威行，遂從耆欲，〔三〕用度不足，乃行壹切之變，使犯法者贖罪，入穀者補吏，是以天下奢侈，官亂民貧，盜賊並起，亡命者眾。郡國恐伏其誅，則擇便巧史書習於計簿能欺上府者，以為右職；〔四〕姦軌不勝，則取勇猛能操切百姓者，以苛暴威服下者，使居大位。〔五〕故亡義而有財者顯於世，欺謾而善書者尊於朝，〔六〕誖逆而勇猛者貴於官。〔七〕故俗皆曰：「何以孝弟為？財多而光榮。何以禮義為？史書而仕宦。何以謹慎為？勇猛而臨官。」故黥劓而髡鉗者猶復攘臂為政於世，行雖犬彘，家富勢足，目指氣使，是為賢耳。〔八〕故謂居官而置富者為雄桀，處姦而得利者為壯士，兄勸其弟，父勉其子，俗之壞敗，乃至於是！察其所以然者，皆以犯法得贖罪，求士不得真賢，相守崇財利，〔九〕誅不行之所致也。","sentenceOrder":192},
  {"id":"s_work_han_thu_85_193","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「白，明也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_85_194","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「罪疑從輕也。」","sentenceOrder":194},
  {"id":"s_work_han_thu_85_195","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「從讀曰縱。耆讀曰嗜。」","sentenceOrder":195},
  {"id":"s_work_han_thu_85_196","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「上府謂所屬之府。右職，高職也。」","sentenceOrder":196},
  {"id":"s_work_han_thu_85_197","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「操，持也。切，刻也。操音千高反。」","sentenceOrder":197},
  {"id":"s_work_han_thu_85_198","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　師古曰：「謾，誑也。謾音慢，又音武連反。」","sentenceOrder":198},
  {"id":"s_work_han_thu_85_199","chapterId":"ch_work_han_thu_85","textTraditional":"〔七〕　師古曰：「誖，亂也。音布內反。」","sentenceOrder":199},
  {"id":"s_work_han_thu_85_200","chapterId":"ch_work_han_thu_85","textTraditional":"〔八〕　師古曰：「動目以指物，出氣以使人。」","sentenceOrder":200},
  {"id":"s_work_han_thu_85_201","chapterId":"ch_work_han_thu_85","textTraditional":"〔九〕　師古曰：「相，諸侯相也。守，郡守也。崇，尚也。」","sentenceOrder":201},
  {"id":"s_work_han_thu_85_202","chapterId":"ch_work_han_thu_85","textTraditional":"今欲興至治，致太平，宜除贖罪之法。相守選舉不以實，及有臧者，輒行其誅，亡但免官，〔一〕則爭盡力為善，貴孝弟，賤賈人，進真賢，舉實廉，而天下治矣。孔子，匹夫之人耳，以樂道正身不解之故，〔二〕四海之內，天下之君，微孔子之言亡所折中。〔三〕況乎以漢地之廣，陛下之德，處南面之尊，秉萬乘之權，因天地之助，其於變世易俗，調和陰陽，陶冶萬物，化正天下，易於決流抑隊。〔四〕自成康以來，幾且千歲，〔五〕欲為治者甚眾，然而太平不復興者，何也？以其舍法度而任私意，奢侈行而仁義廢也。","sentenceOrder":202},
  {"id":"s_work_han_thu_85_203","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「不止免官而已。」","sentenceOrder":203},
  {"id":"s_work_han_thu_85_204","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「解讀曰懈。」","sentenceOrder":204},
  {"id":"s_work_han_thu_85_205","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「微亦無也。折，斷也。非孔子之言則無以為中也，音竹仲反。斷音丁煥反。」","sentenceOrder":205},
  {"id":"s_work_han_thu_85_206","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「決欲流之水，抑將隊之物，言其便易。」","sentenceOrder":206},
  {"id":"s_work_han_thu_85_207","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「幾音鉅依反。」","sentenceOrder":207},
  {"id":"s_work_han_thu_85_208","chapterId":"ch_work_han_thu_85","textTraditional":"陛下誠深念高祖之苦，〔一〕醇法太宗之治，正己以先下，選賢以自輔，開進忠正，致誅姦臣，遠放諂佞，〔二〕放出園陵之女，罷倡樂，絕鄭聲，去甲乙之帳，退偽薄之物，修節儉之化，驅天下之民皆歸於農，如此不解，〔三〕則三王可侔，五帝可及。唯陛下留意省察，天下幸甚。","sentenceOrder":208},
  {"id":"s_work_han_thu_85_209","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「言取天下艱難也。」","sentenceOrder":209},
  {"id":"s_work_han_thu_85_210","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「遠，離也。音于萬反。讇，古諂字。」","sentenceOrder":210},
  {"id":"s_work_han_thu_85_211","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「解讀曰懈。」","sentenceOrder":211},
  {"id":"s_work_han_thu_85_212","chapterId":"ch_work_han_thu_85","textTraditional":"天子下其議，令民產子七歲乃出口錢，自此始。又罷上林宮館希幸御者，及省建章、甘泉宮衛卒，減諸侯王廟衛卒省其半。餘雖未盡從，然嘉其質直之意。禹又奏欲罷郡國廟，定漢宗廟迭毀之禮，皆未施行。〔一〕","sentenceOrder":212},
  {"id":"s_work_han_thu_85_213","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「迭，互也。親盡則毀，故曰迭毀。迭音大結反。」","sentenceOrder":213},
  {"id":"s_work_han_thu_85_214","chapterId":"ch_work_han_thu_85","textTraditional":"為御史大夫數月卒，天子賜錢百萬，以其子為郎，官至東郡都尉。禹卒後，上追思其議，竟下詔罷郡國廟，定迭毀之禮。〔然通儒或非之〕，語在韋玄成傳。","sentenceOrder":214},
  {"id":"s_work_han_thu_85_215","chapterId":"ch_work_han_thu_85","textTraditional":"兩龔皆楚人也，勝字君賓，舍字君倩。〔一〕二人相友，並著名節，故世謂之楚兩龔。少皆好學明經，勝為郡吏，舍不仕。","sentenceOrder":215},
  {"id":"s_work_han_thu_85_216","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「倩音千見反。」","sentenceOrder":216},
  {"id":"s_work_han_thu_85_217","chapterId":"ch_work_han_thu_85","textTraditional":"久之，楚王入朝，聞舍高（明）〔名〕，聘舍為常侍，不得已隨王，歸國固辭，願卒學，復至長安。〔一〕而勝為郡吏，三舉孝廉，以王國人不得宿衛補吏。再為尉，壹為丞，勝輒至官乃去。州舉茂材，為重泉令，〔二〕病去官。大司空何武、執金吾閻崇薦勝，哀帝自為定陶王固已聞其名，徵為諫大夫。引見，勝薦龔舍及亢父甯壽、濟陰侯嘉，〔三〕有詔皆徵。勝曰：「竊見國家徵醫巫，常為駕，徵賢者宜駕。」上曰：「大夫乘私車來邪？」勝曰：「唯唯。」〔四〕有詔為駕。龔舍、侯嘉至，皆為諫大夫。甯壽稱疾不至。","sentenceOrder":217},
  {"id":"s_work_han_thu_85_218","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「卒，終也，終其經業。」","sentenceOrder":218},
  {"id":"s_work_han_thu_85_219","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「重泉，左馮翊縣也。」","sentenceOrder":219},
  {"id":"s_work_han_thu_85_220","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「亢音抗。父音甫。」","sentenceOrder":220},
  {"id":"s_work_han_thu_85_221","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「唯唯，恭應之詞也，音（戈）〔弋〕癸反。」","sentenceOrder":221},
  {"id":"s_work_han_thu_85_222","chapterId":"ch_work_han_thu_85","textTraditional":"勝居諫官，數上書求見，言百姓貧，盜賊多，吏不良，風俗薄，災異數見，不可不憂。制度泰奢，刑罰泰深，賦斂泰重，宜以儉約先下。其言祖述王吉、貢禹之意。為大夫二歲餘，遷丞相司直，徙光祿大夫，守右扶風。數月，上知勝非撥煩吏，乃復還勝光祿大夫〔一〕諸吏給事中。勝言董賢亂制度，繇是逆上指。〔二〕","sentenceOrder":222},
  {"id":"s_work_han_thu_85_223","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「依舊官。」","sentenceOrder":223},
  {"id":"s_work_han_thu_85_224","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「繇讀與由同。」","sentenceOrder":224},
  {"id":"s_work_han_thu_85_225","chapterId":"ch_work_han_thu_85","textTraditional":"後歲餘，丞相王嘉上書薦故廷尉梁相等，尚書劾奏嘉「言事恣意，迷國罔上，不道。」下將軍中朝者議，左將軍公孫祿、司隸鮑宣、光祿大夫孔光等十四人皆以為嘉應迷國不道法。勝獨書議曰：「嘉資性邪僻，所舉多貪殘吏。位列三公，陰陽不和，諸事並廢，咎皆繇嘉，〔一〕迷國不疑，〔二〕今舉相等，過微薄。」日暮議者罷。明旦復會，左將軍祿問勝：「君議亡所據，今奏當上，宜何從？」〔三〕勝曰：「將軍以勝議不可者，通劾之。」〔四〕博士夏侯常見勝應祿不和，起至勝前謂曰：「宜如奏所言。」〔五〕勝以手推常曰：「去！」","sentenceOrder":225},
  {"id":"s_work_han_thu_85_226","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「繇讀與由同。」","sentenceOrder":226},
  {"id":"s_work_han_thu_85_227","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　文穎曰：「信必迷國，不疑也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_85_228","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「今欲奏此事，君定從何議也？」","sentenceOrder":228},
  {"id":"s_work_han_thu_85_229","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「并劾勝。」","sentenceOrder":229},
  {"id":"s_work_han_thu_85_230","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「謂如尚書所劾奏也。」","sentenceOrder":230},
  {"id":"s_work_han_thu_85_231","chapterId":"ch_work_han_thu_85","textTraditional":"後數日，復會議可復孝惠、孝景廟不，議者皆曰宜復。勝曰：「當如禮。」常復謂勝：「禮有變。」勝疾言曰：「去！是時之變。」〔一〕常恚，謂勝曰：「我視君何若，〔二〕君欲小與眾異，外以采名，君乃申徒狄屬耳！」〔三〕","sentenceOrder":231},
  {"id":"s_work_han_thu_85_232","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「疾，急也。言時人意自變耳，禮不變也。」","sentenceOrder":232},
  {"id":"s_work_han_thu_85_233","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「何若，言無所似也。」","sentenceOrder":233},
  {"id":"s_work_han_thu_85_234","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　服虔曰：「殷之末世介士也，自沈於河者。」","sentenceOrder":234},
  {"id":"s_work_han_thu_85_235","chapterId":"ch_work_han_thu_85","textTraditional":"先是常又為勝道高陵有子殺母者。勝白之，尚書問：「誰受？」〔一〕對曰：「受夏侯常。」尚書使勝問常，常連恨勝，〔二〕即應曰：「聞之白衣，戒君勿言也。〔三〕奏事不詳，妄作觸罪。」〔四〕勝窮，亡以對尚書，即自劾奏與常爭言，洿辱朝廷。事下御史中丞，召詰問，劾奏「勝吏二千石，常位大夫，皆幸得給事中，與論議，〔五〕不崇禮義，而居公門下相非恨，疾言辯訟，惰謾亡狀，〔六〕皆不敬。」制曰：「貶秩各一等。」勝謝罪，乞骸骨。上乃復加賞賜，以子博為侍郎，出勝為渤海太守。勝謝病不任之官，積六月免歸。","sentenceOrder":235},
  {"id":"s_work_han_thu_85_236","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「言於誰聞之也。」","sentenceOrder":236},
  {"id":"s_work_han_thu_85_237","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「連恨謂再被（謂）〔譖〕去。」","sentenceOrder":237},
  {"id":"s_work_han_thu_85_238","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　服虔曰：「聞之白衣耳，戒君勿言之，如何便上之邪？」師古曰：「白衣，給官府趨走賤人，若今諸司亭長掌固之屬。」","sentenceOrder":238},
  {"id":"s_work_han_thu_85_239","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「言奏事不審，妄有發作自觸罪。」","sentenceOrder":239},
  {"id":"s_work_han_thu_85_240","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「與讀曰豫。」","sentenceOrder":240},
  {"id":"s_work_han_thu_85_241","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　師古曰：「疾，急也。媠，古惰字。謾讀與慢同。亡狀，無善狀也。」","sentenceOrder":241},
  {"id":"s_work_han_thu_85_242","chapterId":"ch_work_han_thu_85","textTraditional":"上復徵為光祿大夫。勝常稱疾臥。數使子上書乞骸骨，會哀帝崩。","sentenceOrder":242},
  {"id":"s_work_han_thu_85_243","chapterId":"ch_work_han_thu_85","textTraditional":"初，琅邪邴漢亦以清行徵用，至京兆尹，後為太中大夫。王莽秉政，勝與漢俱乞骸骨。自昭帝時，涿郡韓福以德行徵至京師，賜策書束帛遣歸。詔曰：「朕閔勞以官職之事，其務修孝弟以教鄉里。行道舍傳舍，〔一〕縣次具酒肉，食從者及馬。〔二〕長吏以時存問，常以歲八月賜羊一頭，酒二斛。不幸死者，賜複衾一，祠以中牢。」於是王莽依故事，白遣勝、漢。策曰：「惟元始二年六月庚寅，光祿大夫、太中大夫耆艾二人以老病罷。太皇太后使謁者僕射策詔之曰：蓋聞古者有司年至則致仕，所以恭讓而不盡其力也。今大夫年至矣，朕愍以官職之事煩大夫，其上子若孫若同產、同產子一人。〔三〕大夫其修身守道，以終高年。賜帛及行道舍宿，歲時羊酒衣衾，皆如韓福故事。所上子男皆除為郎。」於是勝、漢遂歸老于鄉里。漢兄子曼容亦養志自修，為官不肯過六百石，輒自免去，其名過出於漢。","sentenceOrder":243},
  {"id":"s_work_han_thu_85_244","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「於傳舍止宿，若今官人行得過驛也。」","sentenceOrder":244},
  {"id":"s_work_han_thu_85_245","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「道次給酒肉，並飤其從者及馬也。食讀曰飤。」","sentenceOrder":245},
  {"id":"s_work_han_thu_85_246","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「同產，兄弟也。同產子，即兄弟子也。」","sentenceOrder":246},
  {"id":"s_work_han_thu_85_247","chapterId":"ch_work_han_thu_85","textTraditional":"初，龔舍以龔勝薦，徵為諫大夫，病免。復徵為博士，又病去。頃之，哀帝遣使者即楚拜舍為太山太守。〔一〕舍家居在武原，使者至縣請舍，欲令至廷拜授印綬。〔二〕舍曰：「王者以天下為家，何必縣官？」遂於家受詔，便道之官。既至數月，上書乞骸骨。上徵舍，至京兆東湖界，〔三〕固稱病篤。天子使使者收印綬，拜舍為光祿大夫。數賜告，舍終不肯起，乃遣歸。","sentenceOrder":247},
  {"id":"s_work_han_thu_85_248","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「即猶就也。」","sentenceOrder":248},
  {"id":"s_work_han_thu_85_249","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「廷謂縣之庭內。」","sentenceOrder":249},
  {"id":"s_work_han_thu_85_250","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「湖，縣也，時屬京兆。」","sentenceOrder":250},
  {"id":"s_work_han_thu_85_251","chapterId":"ch_work_han_thu_85","textTraditional":"舍亦通五經，以魯詩教授。舍、勝既歸鄉里，郡二千石長吏初到官皆至其家，如師弟子之禮。舍年六十八，王莽居攝中卒。","sentenceOrder":251},
  {"id":"s_work_han_thu_85_252","chapterId":"ch_work_han_thu_85","textTraditional":"莽既篡國，遣五威將帥行天下風俗，將帥親奉羊酒存問勝。明年，莽遣使者即拜勝為講學祭酒，〔一〕勝稱疾不應徵。後二年，莽復遣使者奉璽書，太子師友祭酒印綬，安車駟馬迎勝，即拜，〔二〕秩上卿，先賜六月祿直以辦裝，使者與郡太守、縣長吏、三老官屬、行義諸生千人以上入勝里致詔。〔三〕使者欲令勝起迎，久立門外。勝稱病篤，為床室中戶西南牖下，〔四〕東首加朝服拕紳。〔五〕使者入戶，西行南面立，致詔付璽書，遷延再拜奉印綬，內安車駟馬，進謂勝曰：「聖朝未嘗忘君，制作未定，待君為政，思聞所欲施行，以安海內。」勝對曰：「素愚，加以年老被病，命在朝夕，隨使君上道，必死道路，〔六〕無益萬分。」使者要說，〔七〕至以印綬就加勝身，勝輒推不受。使者即上言：「方盛夏暑熱，勝病少氣，可須秋涼乃發。」〔八〕有詔許。使者五日壹與太守俱問起居，為勝兩子及門人高暉等言：「朝廷虛心待君以茅土之封，雖疾病，宜動移至傳舍，示有行意，必為子孫遺大業。」暉等白使者語，勝自知不見聽，即謂暉等：「吾受漢家厚恩，亡以報，今年老矣，旦暮入地，誼豈以一身事二姓，下見故主哉？」勝因敕以棺斂喪事：〔九〕「衣周於身，棺周於衣。勿隨俗動吾冢，種柏，作祠堂。」〔一０〕語畢，遂不復開口飲食，積十四日死，死時七十九矣。使者、太守臨斂，賜複衾祭祠如法。門人衰絰治喪者百數。有老父來弔，哭甚哀，既而曰：「嗟虖！薰以香自燒，膏以明自銷。〔一一〕龔生竟夭天年，非吾徒也。」遂趨而出，莫知其誰。勝居彭城廉里，後世刻石表其里門。","sentenceOrder":252},
  {"id":"s_work_han_thu_85_253","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「即，就也。就其家而拜之。」","sentenceOrder":253},
  {"id":"s_work_han_thu_85_254","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「就家迎之，因拜官。」","sentenceOrder":254},
  {"id":"s_work_han_thu_85_255","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「行義謂鄉邑有行義之人也。諸生謂學徒也。行音下更反。」","sentenceOrder":255},
  {"id":"s_work_han_thu_85_256","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「牖，窗也。於戶之西室之南牖下也。」","sentenceOrder":256},
  {"id":"s_work_han_thu_85_257","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「拕，引也。臥著朝衣，故云加引大帶於體也。論語稱孔子『疾，君視之，東首加朝服拕紳』，故放之也。拕音土賀反。」","sentenceOrder":257},
  {"id":"s_work_han_thu_85_258","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　師古曰：「示若尊敬使者，故謂之使君。」","sentenceOrder":258},
  {"id":"s_work_han_thu_85_259","chapterId":"ch_work_han_thu_85","textTraditional":"〔七〕　師古曰：「要音一遙反。說音式銳反。」","sentenceOrder":259},
  {"id":"s_work_han_thu_85_260","chapterId":"ch_work_han_thu_85","textTraditional":"〔八〕　師古曰：「須，待也。」","sentenceOrder":260},
  {"id":"s_work_han_thu_85_261","chapterId":"ch_work_han_thu_85","textTraditional":"〔九〕　師古曰：「棺音工煥反。斂音力贍反。」","sentenceOrder":261},
  {"id":"s_work_han_thu_85_262","chapterId":"ch_work_han_thu_85","textTraditional":"〔一０〕師古曰：「若葬多設器備，則恐被掘，故云動吾冢也。亦不得種柏及作祠堂，皆不隨俗。」","sentenceOrder":262},
  {"id":"s_work_han_thu_85_263","chapterId":"ch_work_han_thu_85","textTraditional":"〔一一〕師古曰：「薰，芳草。」","sentenceOrder":263},
  {"id":"s_work_han_thu_85_264","chapterId":"ch_work_han_thu_85","textTraditional":"鮑宣字子都，渤海高城人也。好學明經，為縣鄉嗇夫，守束州丞。〔一〕後為都尉太守功曹，舉孝廉為郎，病去官，復為州從事。大司馬衛將軍王商辟宣，薦為議郎，後以病去。哀帝初，大司空何武除宣為西曹掾，甚敬重焉，薦宣為諫大夫，遷豫州牧。歲餘，丞相司直郭欽奏「宣舉錯煩苛，代二千石署吏聽訟，所察過詔條。〔二〕行部乘傳去法駕，〔三〕駕一馬，〔四〕舍宿鄉亭，為眾所非。」宣坐免。歸家數月，復徵為諫大夫。","sentenceOrder":264},
  {"id":"s_work_han_thu_85_265","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「束州，渤海之縣也。」","sentenceOrder":265},
  {"id":"s_work_han_thu_85_266","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「出六條之外。」","sentenceOrder":266},
  {"id":"s_work_han_thu_85_267","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「行音下更反。傳音張戀反。」","sentenceOrder":267},
  {"id":"s_work_han_thu_85_268","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「言其單率不依典制也。」","sentenceOrder":268},
  {"id":"s_work_han_thu_85_269","chapterId":"ch_work_han_thu_85","textTraditional":"宣每居位，常上書諫爭，其言少文多實。是時帝祖母傅太后欲與成帝母俱稱尊號，封爵親屬，丞相孔光、大司空師丹、何武、大司馬傅喜始執正議，失傅太后指，皆免官。丁、傅子弟並進，董賢貴幸，宣以諫大夫從其後，上書諫曰：","sentenceOrder":269},
  {"id":"s_work_han_thu_85_270","chapterId":"ch_work_han_thu_85","textTraditional":"竊見孝成皇帝時，外親持權，人人牽引所私以充塞朝廷〔一〕，妨賢人路，濁亂天下，奢泰亡度，窮困百姓，是以日蝕且十，彗星四起。危亡之徵，陛下所親見也，今柰何反覆劇於前乎！朝臣亡有大儒骨鯁，白首耆艾，魁壘之士；〔二〕論議通古今，喟然動眾心，〔三〕憂國如飢渴者，臣未見也。敦外親小童及幸臣董賢等在公門省戶下，〔四〕陛下欲與此共承天地，安海內，甚難。〔五〕今世俗謂不智者為能，謂智者為不能。昔堯放四罪而天下服，〔六〕今除一吏而眾皆惑；古刑人尚服，今賞人反惑。〔七〕請寄為姦，〔八〕群小日進。國家空虛，用度不足。民流亡，去城郭，盜賊並起，吏為殘賊，歲增於前。","sentenceOrder":270},
  {"id":"s_work_han_thu_85_271","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「塞，滿也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_85_272","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　服虔曰：「魁壘，壯貌也。」師古曰：「魁音口賄反。壘音磊。」","sentenceOrder":272},
  {"id":"s_work_han_thu_85_273","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「喟然，歎息貌，音丘位反。」","sentenceOrder":273},
  {"id":"s_work_han_thu_85_274","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「敦謂厚重也。」","sentenceOrder":274},
  {"id":"s_work_han_thu_85_275","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「共讀曰恭。」","sentenceOrder":275},
  {"id":"s_work_han_thu_85_276","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　師古曰：「四罪，流共工于幽州，放驩兜于崇山，竄三苗于三危，殛鯀于羽山也。」","sentenceOrder":276},
  {"id":"s_work_han_thu_85_277","chapterId":"ch_work_han_thu_85","textTraditional":"〔七〕　鄧展曰：「不得其人使之，天下惑也。」","sentenceOrder":277},
  {"id":"s_work_han_thu_85_278","chapterId":"ch_work_han_thu_85","textTraditional":"〔八〕　師古曰：「請寄謂以事私相託也。」","sentenceOrder":278},
  {"id":"s_work_han_thu_85_279","chapterId":"ch_work_han_thu_85","textTraditional":"凡民有七亡：〔一〕陰陽不和，水旱為災，一亡也；縣官重責更賦租稅，二亡也；〔二〕貪吏並公，受取不已，三亡也；〔三〕豪強大姓蠶食亡厭，四亡也；苛吏繇役，失農桑時，五亡也；部落鼓鳴，男女遮迣，六亡也；〔四〕盜賊劫略，取民財物，七亡也。七亡尚可，又有七死：酷吏毆殺，一死也；〔五〕治獄深刻，二死也；冤陷亡辜，三死也；盜賊橫發，四死也；〔六〕怨讎相殘，五死也；歲惡飢餓，六死也；時氣疾疫，七死也。民有七亡而無一得，欲望國安，誠難；民有七死而無一生，欲望刑措，誠難。此非公卿守相貪殘成化之所致邪？〔七〕群臣幸得居尊官，食重祿，豈有肯加惻隱於細民，助陛下流教化者邪？〔八〕志但在營私家，稱賓客，為姦利而已。〔九〕以苟容曲從為賢，以拱默尸祿為智，〔一０〕謂如臣宣等為愚。陛下擢臣巖穴，誠冀有益豪毛，豈徒欲使臣美食大官，重高門之地哉！〔一一〕","sentenceOrder":279},
  {"id":"s_work_han_thu_85_280","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「亡謂失其作業也。」","sentenceOrder":280},
  {"id":"s_work_han_thu_85_281","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「更謂為更卒也，音工行反。」","sentenceOrder":281},
  {"id":"s_work_han_thu_85_282","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「並，依也，音步浪反。」","sentenceOrder":282},
  {"id":"s_work_han_thu_85_283","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　晉灼曰：「迣，古列字也。」師古曰：「言聞桴鼓之聲以為有盜賊，皆當遮列而追捕。」","sentenceOrder":283},
  {"id":"s_work_han_thu_85_284","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「毆，擊也，音一口反。」","sentenceOrder":284},
  {"id":"s_work_han_thu_85_285","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　師古曰：「橫音胡孟反。」","sentenceOrder":285},
  {"id":"s_work_han_thu_85_286","chapterId":"ch_work_han_thu_85","textTraditional":"〔七〕　師古曰：「守，郡守也。相，諸侯相也。」","sentenceOrder":286},
  {"id":"s_work_han_thu_85_287","chapterId":"ch_work_han_thu_85","textTraditional":"〔八〕　師古曰：「惻隱，皆痛也。」","sentenceOrder":287},
  {"id":"s_work_han_thu_85_288","chapterId":"ch_work_han_thu_85","textTraditional":"〔九〕　師古曰：「務稱賓客所求也。稱音尺孕反。」","sentenceOrder":288},
  {"id":"s_work_han_thu_85_289","chapterId":"ch_work_han_thu_85","textTraditional":"〔一０〕師古曰：「尸，主也。不憂其職，但主食祿而已。」","sentenceOrder":289},
  {"id":"s_work_han_thu_85_290","chapterId":"ch_work_han_thu_85","textTraditional":"〔一一〕晉灼曰：「高門，殿名也。」師古曰：「在未央宮中。」","sentenceOrder":290},
  {"id":"s_work_han_thu_85_291","chapterId":"ch_work_han_thu_85","textTraditional":"天下乃皇天之天下也，陛下上為皇天子，下為黎庶父母，為天牧養元元，視之當如一，合尸鳩之詩。〔一〕今貧民菜食不厭，衣又穿空，〔二〕父子夫婦不能相保，誠可為酸鼻。陛下不救，將安所歸命乎？〔三〕奈何獨私養外親與幸臣董賢，多賞賜以大萬數，使奴從賓客漿酒霍肉，〔四〕蒼頭廬兒皆用致富！非天意也。〔五〕及汝昌侯傅商亡功而封。夫官爵非陛下之官爵，乃天下之官爵也。陛下取非其官，官非其人，〔六〕而望天說民服，豈不難哉！〔七〕","sentenceOrder":291},
  {"id":"s_work_han_thu_85_292","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「尸鳩，曹國風之篇也。其詩云：『尸鳩在桑，其子七兮；淑人君子，其儀一兮。』言尸鳩之鳥養其子七，平均如一，善人君子布德施惠，亦當然也。尸鳩，拮掬也。拮音居黠反。」","sentenceOrder":292},
  {"id":"s_work_han_thu_85_293","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「厭，飽足也。空，孔也。」","sentenceOrder":293},
  {"id":"s_work_han_thu_85_294","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「安，焉也。」","sentenceOrder":294},
  {"id":"s_work_han_thu_85_295","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　劉德曰：「視酒如漿，視肉如霍也。」師古曰：「霍，豆葉也。貧人茹之也。」","sentenceOrder":295},
  {"id":"s_work_han_thu_85_296","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　孟康曰：「黎民、黔首，黎、黔皆黑也。下民陰類，故以黑為號。漢名奴為蒼頭，非純黑，以別於良人也。諸給殿中者所居為廬，蒼頭侍從因呼為廬兒。」臣瓚曰：「漢儀注官（如）〔奴〕給書計，從侍中已下為蒼頭青幘。」","sentenceOrder":296},
  {"id":"s_work_han_thu_85_297","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　師古曰：「此官不當加於此人，此人不當受於此官也。」","sentenceOrder":297},
  {"id":"s_work_han_thu_85_298","chapterId":"ch_work_han_thu_85","textTraditional":"〔七〕　師古曰：「說讀曰悅。」","sentenceOrder":298},
  {"id":"s_work_han_thu_85_299","chapterId":"ch_work_han_thu_85","textTraditional":"方陽侯孫寵、宜陵侯息夫躬辯足以移眾，彊可用獨立，姦人之雄，或世尤劇者也，宜以時罷退。及外親幼童未通經術者，皆宜令休就師傅。急徵故大司馬傅喜使領外親。故大司空何武、師丹、故丞相孔光、故左將軍彭宣，經皆更博士，位皆歷三公，〔一〕智謀威信，可與建教化，圖安危。〔二〕龔勝為司直，郡國皆慎選舉，三輔委輸官不敢為姦，〔三〕可大委任也。陛下前以小不忍退武等，海內失望。〔四〕陛下尚能容亡功德者甚眾，曾不能忍武等邪！治天下者當用天下之心為心，不得自專快意而已也。上之皇天見譴，下之黎庶怨恨，次有諫爭之臣，陛下苟欲自薄而厚惡臣，天下猶不聽也。臣雖愚戇，獨不知多受祿賜，美食太官，廣田宅，厚妻子，不與惡人結讎怨以安身邪？誠迫大義，官以諫爭為職，不敢不竭愚。惟陛下少留神明，覽五經之文，原聖人之至意，深思天地之戒。臣宣吶鈍於辭，〔五〕不勝惓惓，盡死節而已。","sentenceOrder":299},
  {"id":"s_work_han_thu_85_300","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「更亦歷也，音工衡反。」","sentenceOrder":300},
  {"id":"s_work_han_thu_85_301","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「建，立也。圖，謀也。」","sentenceOrder":301},
  {"id":"s_work_han_thu_85_302","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「委輸謂輸委積者也。委音迂偽反。輸音式喻反。」","sentenceOrder":302},
  {"id":"s_work_han_thu_85_303","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「小有不快於心，不能忍之也。」","sentenceOrder":303},
  {"id":"s_work_han_thu_85_304","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「吶亦訥字也。」","sentenceOrder":304},
  {"id":"s_work_han_thu_85_305","chapterId":"ch_work_han_thu_85","textTraditional":"上以宣名儒，優容之。","sentenceOrder":305},
  {"id":"s_work_han_thu_85_306","chapterId":"ch_work_han_thu_85","textTraditional":"是時郡國地震，民訛言行籌，明年正月朔日蝕，上乃徵孔光，免孫寵、息夫躬，罷侍中諸曹黃門郎數十人。宣復上書言：","sentenceOrder":306},
  {"id":"s_work_han_thu_85_307","chapterId":"ch_work_han_thu_85","textTraditional":"陛下父事天，母事地，子養黎民，即位已來，父虧明，母震動，子訛言相驚恐。今日蝕於三始，〔一〕誠可畏懼。小民正月朔日尚恐毀敗器物，何況於日虧乎！陛下深內自責，避正殿，舉直言，求過失，罷退外親及旁仄素餐之人，〔二〕徵拜孔光為光祿大夫，發覺孫寵、息夫躬過惡，免官遣就國，眾庶歙然，莫不說喜。〔三〕天人同心，人心說則天意解矣。乃二月丙戌，白虹虷日，連陰不雨，〔四〕此天有憂結未解，民有怨望未塞者也。","sentenceOrder":307},
  {"id":"s_work_han_thu_85_308","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　如淳曰：「正月一日為歲之朝，月之朝，日之朝。始猶朝也。」","sentenceOrder":308},
  {"id":"s_work_han_thu_85_309","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「仄，古側字也。」","sentenceOrder":309},
  {"id":"s_work_han_thu_85_310","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「歙音翕。說音悅。次亦同也。」","sentenceOrder":310},
  {"id":"s_work_han_thu_85_311","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「虷音干。」","sentenceOrder":311},
  {"id":"s_work_han_thu_85_312","chapterId":"ch_work_han_thu_85","textTraditional":"侍中駙馬都尉董賢本無葭莩之親，〔一〕但以令色諛言自進，〔二〕賞賜亡度，竭盡府藏，并合三第尚以為小，復壞暴室。〔三〕賢父子坐使天子使者將作治第，行夜吏卒皆得賞賜。〔四〕上冢有會，輒太官為供。海內貢獻當養一君，今反盡之賢家，豈天意與民意邪！天（下）〔不〕可久負，厚之如此，反所以害之也。誠欲哀賢，宜為謝過天地，解讎海內，免遣就國，收乘輿器物，還之縣官。如此，可以父子終其性命；不者，海內之所讎，未有得久安者也。","sentenceOrder":312},
  {"id":"s_work_han_thu_85_313","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「葭音工遐反。莩音孚。葭莩，喻輕薄而附著也，解在景十三王傳。」","sentenceOrder":313},
  {"id":"s_work_han_thu_85_314","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「令，善也。諛，諂也。」","sentenceOrder":314},
  {"id":"s_work_han_thu_85_315","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「時以三第總為一第賜賢，猶嫌陿小，復取暴室之地以增益之也。」","sentenceOrder":315},
  {"id":"s_work_han_thu_85_316","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「為賢第上持時行夜者。音下更反。」","sentenceOrder":316},
  {"id":"s_work_han_thu_85_317","chapterId":"ch_work_han_thu_85","textTraditional":"孫寵、息夫躬不宜居國，可皆免以視天下。〔一〕復徵何武、師丹、彭宣、傅喜，曠然使民易視，以應天心，〔二〕建立大政，以興太平之端。","sentenceOrder":317},
  {"id":"s_work_han_thu_85_318","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「視讀曰示。」","sentenceOrder":318},
  {"id":"s_work_han_thu_85_319","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「易，改也。」","sentenceOrder":319},
  {"id":"s_work_han_thu_85_320","chapterId":"ch_work_han_thu_85","textTraditional":"高門去省戶數十步，求見出入，二年未省，〔一〕欲使海瀕仄陋自通，遠矣！〔二〕願賜數刻之間，〔三〕極竭毣毣之思，〔四〕退入三泉，死亡所恨。〔五〕","sentenceOrder":320},
  {"id":"s_work_han_thu_85_321","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「不被省視也。」","sentenceOrder":321},
  {"id":"s_work_han_thu_85_322","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「瀕，涯也，音頻，又音賓。」","sentenceOrder":322},
  {"id":"s_work_han_thu_85_323","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「刻，漏刻也。間，空隙。」","sentenceOrder":323},
  {"id":"s_work_han_thu_85_324","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「毣音沐。沐〔沐〕猶蒙蒙也。」如淳曰：「謹愿之貌也。」","sentenceOrder":324},
  {"id":"s_work_han_thu_85_325","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「三重之泉，言其深也。」","sentenceOrder":325},
  {"id":"s_work_han_thu_85_326","chapterId":"ch_work_han_thu_85","textTraditional":"上感大異，納宣言，徵何武、彭宣，旬月皆復為三公。拜宣為司隸。時哀帝改司隸校尉但為司隸，官比司直。","sentenceOrder":326},
  {"id":"s_work_han_thu_85_327","chapterId":"ch_work_han_thu_85","textTraditional":"丞相孔光四時行園陵，〔一〕官屬以令行馳道中，〔二〕宣出逢之，使吏鉤止丞相掾史，〔三〕沒入其車馬，摧辱宰相。事下御史，中丞侍御史至司隸官，欲捕從事，閉門不肯內。〔四〕宣坐距閉使者，亡人臣禮，大不敬，不道，下廷尉獄。博士弟子濟南王咸舉幡太學下，曰：「欲救鮑司隸者會此下。」諸生會者千餘人。朝日，遮丞相孔光自言，〔五〕丞相車不得行，又守闕上書。上遂抵宣罪減死一等，髡鉗。宣既被刑，乃徙之上黨，以為其地宜田牧，又少豪俊，易長雄，〔六〕遂家于長子。〔七〕","sentenceOrder":327},
  {"id":"s_work_han_thu_85_328","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「行音下更反。」","sentenceOrder":328},
  {"id":"s_work_han_thu_85_329","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　如淳曰：「令諸使有制得行馳道中者，行旁道，無得行中央三丈也。」","sentenceOrder":329},
  {"id":"s_work_han_thu_85_330","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「鉤，留也。」","sentenceOrder":330},
  {"id":"s_work_han_thu_85_331","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「御史欲捕從事，而司隸閉門不得入也。」","sentenceOrder":331},
  {"id":"s_work_han_thu_85_332","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「朝日謂早旦欲入朝也。」","sentenceOrder":332},
  {"id":"s_work_han_thu_85_333","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　師古曰：「長，為之長帥也。雄，為之雄豪〔也〕。」","sentenceOrder":333},
  {"id":"s_work_han_thu_85_334","chapterId":"ch_work_han_thu_85","textTraditional":"〔七〕　師古曰：「上黨之縣也。長讀如本字。」","sentenceOrder":334},
  {"id":"s_work_han_thu_85_335","chapterId":"ch_work_han_thu_85","textTraditional":"平帝即位，王莽秉政，陰有篡國之心，乃風州郡以罪法案誅諸豪桀，〔一〕及漢忠直臣不附己者，宣及何武等皆死。時名捕隴西辛興，〔二〕興與宣女婿許紺俱過宣，一飯去，〔三〕宣不知情，坐繫獄，自殺。","sentenceOrder":335},
  {"id":"s_work_han_thu_85_336","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「風讀曰諷。」","sentenceOrder":336},
  {"id":"s_work_han_thu_85_337","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「詔顯其名而捕之。」","sentenceOrder":337},
  {"id":"s_work_han_thu_85_338","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「飯音扶晚反。」","sentenceOrder":338},
  {"id":"s_work_han_thu_85_339","chapterId":"ch_work_han_thu_85","textTraditional":"自成帝至王莽時，清名之士，琅邪又有紀逡王思，齊則薛方子容，太原則郇越臣仲、郇相稚賓，沛郡則唐林子高、唐尊伯高，〔一〕皆以明經飭行顯名於世。〔二〕","sentenceOrder":339},
  {"id":"s_work_han_thu_85_340","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「并列其人本土及姓名字也。後皆類此。逡音千旬反。郇音荀，又音胡頑反。今荀郇二姓並有之，俱稱周武王之後也。」","sentenceOrder":340},
  {"id":"s_work_han_thu_85_341","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「飭，謹也，讀與敕同。」","sentenceOrder":341},
  {"id":"s_work_han_thu_85_342","chapterId":"ch_work_han_thu_85","textTraditional":"紀逡、兩唐皆仕王莽，封侯貴重，歷公卿位。唐林數上疏諫正，有忠直節。唐尊衣敝履空，〔一〕以瓦器飲食，又以歷遺公卿，〔二〕被虛偽名。〔三〕","sentenceOrder":342},
  {"id":"s_work_han_thu_85_343","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　服虔曰：「履猶屨也。」師古曰：「衣音於既反。著敝衣躡空履也。空，穿也。」","sentenceOrder":343},
  {"id":"s_work_han_thu_85_344","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　服虔曰：「以瓦器遺之。」","sentenceOrder":344},
  {"id":"s_work_han_thu_85_345","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「被音皮義反。」","sentenceOrder":345},
  {"id":"s_work_han_thu_85_346","chapterId":"ch_work_han_thu_85","textTraditional":"郇越、相，同族昆弟也，並舉州郡孝廉茂材，數病，去官。越散其先人訾千餘萬，以分施九族州里，志節尤高。相王莽時徵為太子四友，病死，莽太子遣使裞以衣衾，〔一〕其子攀棺不聽，曰：「死父遺言，師友之送勿有所受，今於皇太子得託友官，故不受也。」京師稱之。","sentenceOrder":346},
  {"id":"s_work_han_thu_85_347","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「贈喪衣服曰裞。裞音式芮反，其字從衣。」","sentenceOrder":347},
  {"id":"s_work_han_thu_85_348","chapterId":"ch_work_han_thu_85","textTraditional":"薛方嘗為郡掾祭酒，嘗徵不至，及莽以安車迎方，方因使者辭謝曰：「堯舜在上，下有巢由，今明主方隆唐虞之德，小臣欲守箕山之節也。」〔一〕使者以聞，莽說其言，不強致。〔二〕方居家以經教授，喜屬文，〔三〕著詩賦數十篇。","sentenceOrder":348},
  {"id":"s_work_han_thu_85_349","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　張晏曰：「許由隱於箕山，在陽城，有許由祠。」","sentenceOrder":349},
  {"id":"s_work_han_thu_85_350","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":350},
  {"id":"s_work_han_thu_85_351","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「喜音許吏反。屬音之欲反。」","sentenceOrder":351},
  {"id":"s_work_han_thu_85_352","chapterId":"ch_work_han_thu_85","textTraditional":"始隃麋郭欽，哀帝時為丞相司直，〔一〕奏免豫州牧鮑宣、京兆尹薛修等，又奏董賢，左遷盧奴令，平帝時遷南郡太守。而杜陵蔣詡元卿為兗州刺史，亦以廉直為名。王莽居攝，欽、詡皆以病免官，歸鄉里，臥不出戶，卒於家。","sentenceOrder":352},
  {"id":"s_work_han_thu_85_353","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「隃麋，扶風之縣也。隃音踰。」","sentenceOrder":353},
  {"id":"s_work_han_thu_85_354","chapterId":"ch_work_han_thu_85","textTraditional":"齊栗融客卿、北海禽慶子夏、蘇章游卿、山陽曹竟子期皆儒生，去官不仕於莽。莽死，漢更始徵竟以為丞相，封侯，欲視致賢人，銷寇賊。〔一〕竟不受侯爵。會赤眉入長安，欲降竟，竟手劍格死。","sentenceOrder":354},
  {"id":"s_work_han_thu_85_355","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「視讀曰示。」","sentenceOrder":355},
  {"id":"s_work_han_thu_85_356","chapterId":"ch_work_han_thu_85","textTraditional":"世祖即位，徵薛方，道病卒。兩龔、鮑宣子孫皆見褒表，至大官。","sentenceOrder":356},
  {"id":"s_work_han_thu_85_357","chapterId":"ch_work_han_thu_85","textTraditional":"贊曰：易稱「君子之道，或出或處，或默或語」，〔一〕言其各得道之一節，譬諸草木，區以別矣。〔二〕故曰山林之士往而不能反，朝廷之士入而不能出，二者各有所短。春秋列國卿大夫至漢興將相名臣，懷祿耽寵以失其世者多矣！〔三〕是故清節之士於是為貴。然大率多能自治而不能治人。王、貢之材，優於龔、鮑。守死善道，勝實蹈焉。〔四〕貞而不諒，薛方近之。〔五〕郭欽、蔣詡好遯不汙，絕紀、唐矣！〔六〕","sentenceOrder":357},
  {"id":"s_work_han_thu_85_358","chapterId":"ch_work_han_thu_85","textTraditional":"〔一〕　師古曰：「上繫辭也。謂發跡雖異，同歸於道。」","sentenceOrder":358},
  {"id":"s_work_han_thu_85_359","chapterId":"ch_work_han_thu_85","textTraditional":"〔二〕　師古曰：「言蘭桂異類而各芬馨也。」","sentenceOrder":359},
  {"id":"s_work_han_thu_85_360","chapterId":"ch_work_han_thu_85","textTraditional":"〔三〕　師古曰：「懷，思也，言不能去。」","sentenceOrder":360},
  {"id":"s_work_han_thu_85_361","chapterId":"ch_work_han_thu_85","textTraditional":"〔四〕　師古曰：「論語稱孔子曰：『篤信好學，守死善道，危邦不入，亂邦不居。』今龔勝不受莽官，蹈斯之跡也。」","sentenceOrder":361},
  {"id":"s_work_han_thu_85_362","chapterId":"ch_work_han_thu_85","textTraditional":"〔五〕　師古曰：「論語稱孔子曰『君子貞而不諒』，謂君子之人正其道耳，言不必信也。薛方志避亂朝，詭引巢許為喻，近此義也。」","sentenceOrder":362},
  {"id":"s_work_han_thu_85_363","chapterId":"ch_work_han_thu_85","textTraditional":"〔六〕　師古曰：「欽、詡不仕於莽，遯逃濁亂，不汙其節，殊於紀逡及兩唐。」","sentenceOrder":363},
  {"id":"s_work_han_thu_85_364","chapterId":"ch_work_han_thu_85","textTraditional":"校勘記","sentenceOrder":364},
  {"id":"s_work_han_thu_85_365","chapterId":"ch_work_han_thu_85","textTraditional":"三０五五頁　三行　餓〔死〕于首陽，　殿本有「死」字，無「于」字。　景祐本有「死」字，又有「于」字。","sentenceOrder":365},
  {"id":"s_work_han_thu_85_366","chapterId":"ch_work_han_thu_85","textTraditional":"三０五五頁　五行　奮乎百世之上，（行乎）百世之下莫不興起，　景祐、殿本都無「行乎」二字。","sentenceOrder":366},
  {"id":"s_work_han_thu_85_367","chapterId":"ch_work_han_thu_85","textTraditional":"三０五七頁　四行　或問：君子疾沒世而名不稱，盍勢諸？名，卿可幾。　楊樹達說，近人汪榮寶注法言，以「名」一字為句，「卿可幾」三字為句，是也。諸說以「名卿」連讀，非是。","sentenceOrder":367},
  {"id":"s_work_han_thu_85_368","chapterId":"ch_work_han_thu_85","textTraditional":"三０五八頁　七行　少（時）〔好〕學明經，　景祐、殿本都作「好」。王先謙說作「好」是。","sentenceOrder":368},
  {"id":"s_work_han_thu_85_369","chapterId":"ch_work_han_thu_85","textTraditional":"三０六一頁　六行　中（慰）〔尉〕甚忠，　景祐、殿、局本都作「尉」，此誤。","sentenceOrder":369},
  {"id":"s_work_han_thu_85_370","chapterId":"ch_work_han_thu_85","textTraditional":"三０六二頁　一行　願留意，（嘗）〔常〕以為念。　景祐、殿本都作「常」。　王先謙說作「常」是。","sentenceOrder":370},
  {"id":"s_work_han_thu_85_371","chapterId":"ch_work_han_thu_85","textTraditional":"三０六四頁一六行　是以貪財（趨）〔誅〕利，　景祐、殿本都作「誅」。","sentenceOrder":371},
  {"id":"s_work_han_thu_85_372","chapterId":"ch_work_han_thu_85","textTraditional":"三０六九頁一一行　謂以粟米（飯）〔飤〕也。　景祐、殿本都作「飤」。","sentenceOrder":372},
  {"id":"s_work_han_thu_85_373","chapterId":"ch_work_han_thu_85","textTraditional":"三０七０頁　一行　後世爭為奢侈，轉轉益（盛）〔甚〕，　景祐、殿本都作「甚」，通鑑同。","sentenceOrder":373},
  {"id":"s_work_han_thu_85_374","chapterId":"ch_work_han_thu_85","textTraditional":"三０七０頁一三行　為犬豬（所）食。　宋祁說浙本無「所」字。按景祐本無「所」字。","sentenceOrder":374},
  {"id":"s_work_han_thu_85_375","chapterId":"ch_work_han_thu_85","textTraditional":"三０七一頁　三行　陛下（烏）〔惡〕有所言，　景祐、殿本都作「惡」。楊樹達說作「惡」是。","sentenceOrder":375},
  {"id":"s_work_han_thu_85_376","chapterId":"ch_work_han_thu_85","textTraditional":"三０七三頁　三行　下鮑宣傳（倦倦）〔惓惓〕音義亦同，　景祐、殿本都作「惓惓」。","sentenceOrder":376},
  {"id":"s_work_han_thu_85_377","chapterId":"ch_work_han_thu_85","textTraditional":"三０七三頁一０行　伏自念終亡以報厚（恩）〔德〕，　景祐、殿本都作「德」。","sentenceOrder":377},
  {"id":"s_work_han_thu_85_378","chapterId":"ch_work_han_thu_85","textTraditional":"三０七五頁一二行　民心（搖動）〔動搖〕，　景祐、殿本都作「動搖」。","sentenceOrder":378},
  {"id":"s_work_han_thu_85_379","chapterId":"ch_work_han_thu_85","textTraditional":"三０八０頁　一行　〔然通儒或非云〕，　景祐、殿本都有此六字。","sentenceOrder":379},
  {"id":"s_work_han_thu_85_380","chapterId":"ch_work_han_thu_85","textTraditional":"三０八０頁　五行　聞舍高（明）〔名〕，聘舍為常侍。　景祐、殿本都作「名」。王先謙說作「名」是。","sentenceOrder":380},
  {"id":"s_work_han_thu_85_381","chapterId":"ch_work_han_thu_85","textTraditional":"三０八０頁一四行　音（戈）〔弋〕癸反。　景祐、殿本都作「弋」，此誤。","sentenceOrder":381},
  {"id":"s_work_han_thu_85_382","chapterId":"ch_work_han_thu_85","textTraditional":"三０八二頁一六行　連恨謂再被（謂）〔譖〕去。　殿本作「譖」，此誤。","sentenceOrder":382},
  {"id":"s_work_han_thu_85_383","chapterId":"ch_work_han_thu_85","textTraditional":"三０九０頁　八行　官（如）〔奴〕給書計，　景祐、殿本都作「奴」，此誤。","sentenceOrder":383},
  {"id":"s_work_han_thu_85_384","chapterId":"ch_work_han_thu_85","textTraditional":"三０九二頁一０行　天（下）〔不〕可久負，　王先謙說「下」字誤。按景祐、殿本都作「不」。","sentenceOrder":384},
  {"id":"s_work_han_thu_85_385","chapterId":"ch_work_han_thu_85","textTraditional":"三０九三頁一０行　沐〔沐〕猶蒙蒙也。　殿本重「沐」字。王先謙說重「沐」字是。","sentenceOrder":385},
  {"id":"s_work_han_thu_85_386","chapterId":"ch_work_han_thu_85","textTraditional":"三０九四頁　九行　雄，為之雄豪〔也〕。　景祐、殿本都有「也」字。","sentenceOrder":386},
  {"id":"s_work_han_thu_86_1","chapterId":"ch_work_han_thu_86","textTraditional":"韋賢字長孺，魯國鄒人也。其先韋孟，家本彭城，為楚元王傅，傅子夷王及孫王戊。〔一〕戊荒淫不遵道，孟作詩風諫。後遂去位，徙家於鄒，又作一篇。其諫詩曰：","sentenceOrder":1},
  {"id":"s_work_han_thu_86_2","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「官為楚王傅而歷相三王也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_86_3","chapterId":"ch_work_han_thu_86","textTraditional":"肅肅我祖，國自豕韋，〔一〕黼衣朱紱，四牡龍旂。〔二〕彤弓斯征，撫寧遐荒，〔三〕總齊群邦，以翼大商，〔四〕迭彼大彭，勳績惟光。〔五〕至于有周，歷世會同。〔六〕王赧聽譖，寔絕我邦。〔七〕我邦既絕，厥政斯逸，〔八〕賞罰之行，非繇王室。〔九〕庶尹群后，靡扶靡衛，五服崩離，宗周以隊。〔一０〕我祖斯微，遷于彭城，〔一一〕在予小子，勤誒厥生，〔一二〕阨此嫚秦，耒耜以耕。〔一三〕悠悠嫚秦，上天不寧，乃眷南顧，授漢于京。〔一四〕","sentenceOrder":3},
  {"id":"s_work_han_thu_86_4","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　應劭曰：「在商為豕韋氏也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_86_5","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「黼衣畫為斧形，而白與黑為彩也。朱紱為朱裳畫為亞文也。亞，古弗字也，故因謂之。紱字又作黻，其音同聲。」","sentenceOrder":5},
  {"id":"s_work_han_thu_86_6","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「言受彤弓之賜，於此得專征伐也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_86_7","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「翼，佐助也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_86_8","chapterId":"ch_work_han_thu_86","textTraditional":"〔五〕　應劭曰：「國語曰『大彭、豕韋為商伯』。」師古曰：「迭，互也。自言豕韋氏與大彭互為伯於殷商也。迭音徒結反。」","sentenceOrder":8},
  {"id":"s_work_han_thu_86_9","chapterId":"ch_work_han_thu_86","textTraditional":"〔六〕　師古曰：「繼為諸侯預盟會之事也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_86_10","chapterId":"ch_work_han_thu_86","textTraditional":"〔七〕　應劭曰：「王赧，周末王，聽讒受譖，絕豕韋氏也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_86_11","chapterId":"ch_work_han_thu_86","textTraditional":"〔八〕　應劭曰：「言自絕豕韋氏之後，政教逸漏，不由王者也。」臣瓚曰：「逸，放也。管仲曰『令而不行謂之放』。」師古曰：「瓚說是也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_86_12","chapterId":"ch_work_han_thu_86","textTraditional":"〔九〕　師古曰：「繇與由同也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_86_13","chapterId":"ch_work_han_thu_86","textTraditional":"〔一０〕應劭曰：「五服謂甸服、侯服、綏服、要服、荒服也。」師古曰：「庶尹，眾官之長也。群后，諸侯也。隊，失也，音直類反。」","sentenceOrder":13},
  {"id":"s_work_han_thu_86_14","chapterId":"ch_work_han_thu_86","textTraditional":"〔一一〕師古曰：「言我之先祖於此遂微也。〈遷，去辶〉，古遷字。其下並同。」","sentenceOrder":14},
  {"id":"s_work_han_thu_86_15","chapterId":"ch_work_han_thu_86","textTraditional":"〔一二〕師古曰：「誒，歎聲，音許其反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_86_16","chapterId":"ch_work_han_thu_86","textTraditional":"〔一三〕師古曰：「言遭秦暴嫚，無有列位，躬耕於野。」","sentenceOrder":16},
  {"id":"s_work_han_thu_86_17","chapterId":"ch_work_han_thu_86","textTraditional":"〔一四〕師古曰：「高祖起在豐沛，於秦為南，故曰南顧。言以秦之京邑，授與漢也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_86_18","chapterId":"ch_work_han_thu_86","textTraditional":"於赫有漢，四方是征，〔一〕靡適不懷，萬國逌平。〔二〕乃命厥弟，建侯於楚，俾我小臣，惟傅是輔。兢兢元王，恭儉淨壹，〔三〕惠此黎民，納彼輔弼。饗國漸世，垂烈于後，〔四〕乃及夷王，克奉厥緒。咨命不永，唯王統祀，〔五〕左右陪臣，此惟皇士〔六〕。","sentenceOrder":18},
  {"id":"s_work_han_thu_86_19","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「於讀曰烏。烏，歎辭也。赫，明貌。凡此詩中諸歎辭稱於者，其音皆同。」","sentenceOrder":19},
  {"id":"s_work_han_thu_86_20","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「懷，思也，來也。逌，古攸字。攸，所也。言漢兵所往之處，人皆思附而來，萬國所以平也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_86_21","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「兢兢，謹戒也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_86_22","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「元王立二十七年而薨，垂遺業於後嗣也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_86_23","chapterId":"ch_work_han_thu_86","textTraditional":"〔五〕　師古曰：「咨，嗟也。永，長也。夷王立四年而薨，戊乃嗣位，故言不永也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_86_24","chapterId":"ch_work_han_thu_86","textTraditional":"〔六〕　師古曰：「爾雅云：『皇，正也。』」","sentenceOrder":24},
  {"id":"s_work_han_thu_86_25","chapterId":"ch_work_han_thu_86","textTraditional":"如何我王，不思守保，不惟履冰，以繼祖考！〔一〕邦事是廢，逸游是娛，犬馬繇繇，是放是驅。〔二〕務彼鳥獸，忽此稼苗，烝民以匱，我王以媮。〔三〕所弘非德，所親非俊，唯囿是恢，唯諛是信。〔四〕睮睮諂夫，咢咢黃髮，〔五〕如何我王，曾不是察！既藐下臣，追欲從逸，〔六〕嫚彼顯祖，輕茲削黜。","sentenceOrder":25},
  {"id":"s_work_han_thu_86_26","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「惟亦思也，言不思念敬慎如履薄冰之義，用繼其祖考之業也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_86_27","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「繇與悠同。悠悠，行貌。放，放犬也。驅，驅馬也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_86_28","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「媮與愉同，樂也。言眾人失此稼穡，以致困匱，而王反以為樂也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_86_29","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「恢，大也。諛，諂言也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_86_30","chapterId":"ch_work_han_thu_86","textTraditional":"〔五〕　如淳曰：「睮睮，自媚貌也。」師古曰：「咢咢，直言也。睮音踰。咢音五各反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_86_31","chapterId":"ch_work_han_thu_86","textTraditional":"〔六〕　應劭曰：「藐，遠也。言疏遠忠賢之輔，追情Q欲Y，從逸遊也。」臣瓚曰：「藐，陵藐也。」師古曰：「藐與邈同。應說是也。下臣，孟自謂也。從讀曰縱。」","sentenceOrder":31},
  {"id":"s_work_han_thu_86_32","chapterId":"ch_work_han_thu_86","textTraditional":"嗟嗟我王，漢之睦親，〔一〕曾不夙夜，以休令聞！〔二〕穆穆天子，臨爾下土，明明群司，執憲靡顧。〔三〕正遐繇近，殆其怙茲，〔四〕嗟嗟我王，曷不此思！","sentenceOrder":32},
  {"id":"s_work_han_thu_86_33","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「睦，密也，言服屬近。」","sentenceOrder":33},
  {"id":"s_work_han_thu_86_34","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「休，美也。令，善也。聞，聲名也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_86_35","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「靡，無也。言執天子之法，無所顧望也。顧讀如古，協韻。」","sentenceOrder":35},
  {"id":"s_work_han_thu_86_36","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「言欲正遠人，先從近〔親〕始，而王怙恃與漢戚屬，不自勗慎，以致危殆也。繇讀與由同。」","sentenceOrder":36},
  {"id":"s_work_han_thu_86_37","chapterId":"ch_work_han_thu_86","textTraditional":"非思非鑒，嗣其罔則，〔一〕彌彌其失，岌岌其國。〔二〕致冰匪霜，致隊靡嫚，瞻惟我王，昔靡不練。〔三〕興國救顛，孰違悔過，追思黃髮，秦繆以霸。〔四〕歲月其徂，年其逮耇，〔五〕於昔君子，庶顯于後。〔六〕我王如何，曾不斯覽！〔七〕黃髮不近，胡不時監！〔八〕","sentenceOrder":37},
  {"id":"s_work_han_thu_86_38","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「不思鑒戒之義，是令後嗣無所法則也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_86_39","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　應劭曰：「彌彌猶稍稍也，罪過茲甚也。岌岌，欲毀壞也。」師古曰：「岌岌，危動貌，音五合反。」","sentenceOrder":39},
  {"id":"s_work_han_thu_86_40","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「言堅冰之成起於微霜，隕隊之咎由於怠嫚也。練猶閱歷之，言往昔之事，皆在王心，無所不閱也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_86_41","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「言興復邦國，救止顛隊之道，無如能自悔其過惡。秦穆公伐鄭，為晉所敗而歸，乃作秦誓曰：『雖則員然，尚猶詢茲黃髮，則罔所愆。』謂雖有員然之失，庶幾以道謀於黃髮之賢，則行無所過矣。黃髮，老壽之人也，謂髮落更生黃者也。員與云同。」","sentenceOrder":41},
  {"id":"s_work_han_thu_86_42","chapterId":"ch_work_han_thu_86","textTraditional":"〔五〕　師古曰：「逮，及也。耇者，老人面色如垢也。言歲月驟往，年將及耇，不可殆忽。」","sentenceOrder":42},
  {"id":"s_work_han_thu_86_43","chapterId":"ch_work_han_thu_86","textTraditional":"〔六〕　師古曰：「於，歎辭也。言昔之君子，庶幾善道，所以能光顯於後世也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_86_44","chapterId":"ch_work_han_thu_86","textTraditional":"〔七〕　師古曰：「覽，視也，協韻音濫。」","sentenceOrder":44},
  {"id":"s_work_han_thu_86_45","chapterId":"ch_work_han_thu_86","textTraditional":"〔八〕　師古曰：「黃髮不近者，斥遠耇老之人也。近音其靳反。」","sentenceOrder":45},
  {"id":"s_work_han_thu_86_46","chapterId":"ch_work_han_thu_86","textTraditional":"其在鄒詩曰：","sentenceOrder":46},
  {"id":"s_work_han_thu_86_47","chapterId":"ch_work_han_thu_86","textTraditional":"微微小子，既耇且陋，〔一〕豈不牽位，穢我王朝。〔二〕王朝肅清，唯俊之庭，顧瞻余躬，懼穢此征。〔三〕","sentenceOrder":47},
  {"id":"s_work_han_thu_86_48","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「自言年老，材質鄙陋也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_86_49","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　應劭曰：「言豈不戀此爵位乎？以王朝汙穢不肅清故也。」師古曰：「此說非也。恐己穢王朝，所以去耳，故下又言『懼穢此征』也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_86_50","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　李奇曰：「於此便行也。」師古曰：「此皆孟已去遜辭，不欲顯王之過惡也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_86_51","chapterId":"ch_work_han_thu_86","textTraditional":"我之退征，請于天子，天子我恤，矜我髮齒。赫赫天子，明悊且仁，懸車之義，以洎小臣。〔一〕嗟我小子，豈不懷土？庶我王寤，越遷于魯。〔二〕","sentenceOrder":51},
  {"id":"s_work_han_thu_86_52","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　應劭曰：「古者七十縣車致仕。洎，及也。天子以縣車之義及我也。」師古曰：「洎音鉅異反。」","sentenceOrder":52},
  {"id":"s_work_han_thu_86_53","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　應劭曰：「言豈不懷土乎？庶幾王之寤覺，欲還輔相之，相近居魯也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_86_54","chapterId":"ch_work_han_thu_86","textTraditional":"既去禰祖，惟懷惟顧，〔一〕祁祁我徒，戴負盈路。〔二〕爰戾于鄒，鬋茅作堂，〔三〕我徒我環，築室于牆。〔四〕","sentenceOrder":54},
  {"id":"s_work_han_thu_86_55","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「父廟曰禰。言去其父祖舊居，所以懷顧也。禰音乃禮反。」","sentenceOrder":55},
  {"id":"s_work_han_thu_86_56","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「祁祁，眾貌。一曰祁祁，徐行也。徒謂學徒也。戴負者，謂隨其徙居也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_86_57","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「戾，至也。鬋字與剪同。」","sentenceOrder":57},
  {"id":"s_work_han_thu_86_58","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「環，遶也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_86_59","chapterId":"ch_work_han_thu_86","textTraditional":"我既〈遷，去辶〉逝，心存我舊，夢我瀆上，立于王朝。〔一〕其夢如何？夢爭王室。其爭如何？夢王我弼。〔二〕寤其外邦，歎其喟然，〔三〕念我祖考，泣涕其漣。〔四〕微微老夫，咨既遷絕，〔五〕洋洋仲尼，視我遺烈。〔六〕濟濟鄒魯，禮義唯恭，誦習弦歌，于異他邦。〔七〕我雖鄙耇，心其好而，我徒侃爾，樂亦在而。〔八〕","sentenceOrder":59},
  {"id":"s_work_han_thu_86_60","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　應劭曰：「瀆上，孟所居彭城東里名（曰）〔也〕。猶不忘本也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_86_61","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「弼，戾也。言夢爭王室之事，王違戾我言也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_86_62","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「夢在王朝，及寐之寤，乃在鄒也。寤，覺也。喟音丘位反。覺音工效反。」","sentenceOrder":62},
  {"id":"s_work_han_thu_86_63","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「漣漣，泣下貌，音連。」","sentenceOrder":63},
  {"id":"s_work_han_thu_86_64","chapterId":"ch_work_han_thu_86","textTraditional":"〔五〕　師古曰：「咨，嗟也。絕謂與舊居絕也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_86_65","chapterId":"ch_work_han_thu_86","textTraditional":"〔六〕　師古曰：「洋洋，美盛也。烈，業也。視讀曰示。孔子，鄒人，故言示我遺業也。洋音祥，又音羊。」","sentenceOrder":65},
  {"id":"s_work_han_thu_86_66","chapterId":"ch_work_han_thu_86","textTraditional":"〔七〕　師古曰：「言禮樂之教，不同餘土也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_86_67","chapterId":"ch_work_han_thu_86","textTraditional":"〔八〕　師古曰：「而者，句（端）〔絕〕之辭。侃，和樂貌，音口旦反。」","sentenceOrder":67},
  {"id":"s_work_han_thu_86_68","chapterId":"ch_work_han_thu_86","textTraditional":"孟卒于鄒。或曰其子孫好事，述先人之志而作是詩也。","sentenceOrder":68},
  {"id":"s_work_han_thu_86_69","chapterId":"ch_work_han_thu_86","textTraditional":"自孟至賢五世。賢為人質朴少欲，篤志於學，〔一〕兼通禮、尚書，以詩教授，號稱鄒魯大儒。徵為博士，給事中，進授昭帝詩，稍遷光祿大夫詹事，至大鴻臚。昭帝崩，無嗣，大將軍霍光與公卿共尊立孝宣帝。帝初即位，賢以與謀議，安宗廟，賜爵關內侯，食邑〔二〕。徙為長信少府。〔三〕以先帝師，甚見尊重。本始三年，代蔡義為丞相，封扶陽侯，〔四〕食邑七百戶。時賢七十餘，為相五歲，地節三年以老病乞骸骨，賜黃金百斤，罷歸，加賜弟一區。丞相致仕自賢始。年八十二薨，諡曰節侯。","sentenceOrder":69},
  {"id":"s_work_han_thu_86_70","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「篤，厚也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_86_71","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「與讀曰豫。」","sentenceOrder":71},
  {"id":"s_work_han_thu_86_72","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「長信者，太后宮名，為太后官屬也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_86_73","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　孟康曰：「屬沛郡。」","sentenceOrder":73},
  {"id":"s_work_han_thu_86_74","chapterId":"ch_work_han_thu_86","textTraditional":"賢四子：長子方山為高寢令，早終；次子弘，至東海太守；次子舜，留魯守墳墓；少子玄成，復以明經歷位至丞相。故鄒魯諺曰：「遺子黃金滿籯，不如一經。」〔一〕","sentenceOrder":74},
  {"id":"s_work_han_thu_86_75","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　如淳曰：「籯，竹器，受三四斗。今陳留俗有此器。」蔡謨曰：「滿籯者，言其多耳，非器名也。若論陳留之俗，則我陳人也，不聞有此器。」師古曰：「許慎說文解字云『籯，笭也』，楊雄方言云『陳、楚、宋、魏之間謂筲為籯』，然則筐籠之屬是也。今書本籯字或作盈，又是盈滿之義，蓋兩通也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_86_76","chapterId":"ch_work_han_thu_86","textTraditional":"玄成字少翁，以父任為郎，常侍騎。少好學，修父業，尤謙遜下士。〔一〕出遇知識步行，輒下從者，與載送之，〔二〕以為常。其接人，貧賤者益加敬，繇是名譽日廣。〔三〕以明經擢為諫大夫，遷大河都尉。〔四〕","sentenceOrder":76},
  {"id":"s_work_han_thu_86_77","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「下音胡亞反。」","sentenceOrder":77},
  {"id":"s_work_han_thu_86_78","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「輟從者之車馬也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_86_79","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「繇與由同。」","sentenceOrder":79},
  {"id":"s_work_han_thu_86_80","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　服虔曰：「今東平郡也。本為濟東國，後王國除，為大河郡。」","sentenceOrder":80},
  {"id":"s_work_han_thu_86_81","chapterId":"ch_work_han_thu_86","textTraditional":"初，玄成兄弘為太常丞，職奉宗廟，典諸陵邑，煩劇多罪過。父賢以弘當為嗣，故敕令自免。〔一〕弘懷謙，不去官。〔二〕及賢病篤，弘竟坐宗廟事繫獄，罪未決。室家問賢當為後者，賢恚恨不肯言。於是賢門下生博士義倩等與宗家計議，〔三〕共矯賢令，〔四〕使家丞上書言大行，〔五〕以大河都尉玄成為後。賢薨，玄成在官聞喪，又言當為嗣，玄成深知其非賢雅意，即陽為病狂，臥便利，妄笑語昏亂。〔六〕徵至長安，既葬，當襲爵，以病狂不應召。大鴻臚（奉）〔奏〕狀，章下丞相御史案驗。玄成素有名聲，士大夫多疑其欲讓爵辟兄者。〔七〕案事丞相史乃與玄成書〔八〕曰：「古之辭讓，必有文義可觀，故能垂榮於後。今子獨壞容貌，蒙恥辱，為狂癡，光曜晻而不宣。〔九〕微哉！子之所託名也。〔一０〕僕素愚陋，過為宰相執事，〔一一〕願少聞風聲。不然，恐子傷高而僕為小人也。」玄成友人侍郎章亦上疏言：「聖王貴以禮讓為國，宜優養玄成，勿枉其志，〔一二〕使得自安衡門之下。」〔一三〕而丞相御史遂以玄成實不病，劾奏之。有詔勿劾，引拜。玄成不得已受爵。宣帝高其節，以玄成為河南太守。兄弘太山都尉，遷東海太守。","sentenceOrder":81},
  {"id":"s_work_han_thu_86_82","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「恐其有罪見黜，妨為繼嗣，故令以病去官也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_86_83","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「謂若欲代父為侯，故避嫌不肯也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_86_84","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「博士姓義名倩也。宗家，賢之同族也。倩音千見反。」","sentenceOrder":84},
  {"id":"s_work_han_thu_86_85","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「矯，託也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_86_86","chapterId":"ch_work_han_thu_86","textTraditional":"〔五〕　師古曰：「為文書於大行，以言其事也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_86_87","chapterId":"ch_work_han_thu_86","textTraditional":"〔六〕　師古曰：「便利，大小便。」","sentenceOrder":87},
  {"id":"s_work_han_thu_86_88","chapterId":"ch_work_han_thu_86","textTraditional":"〔七〕　師古曰：「辟讀曰避。」","sentenceOrder":88},
  {"id":"s_work_han_thu_86_89","chapterId":"ch_work_han_thu_86","textTraditional":"〔八〕　師古曰：「即案驗玄成事者。」","sentenceOrder":89},
  {"id":"s_work_han_thu_86_90","chapterId":"ch_work_han_thu_86","textTraditional":"〔九〕　師古曰：「晻讀與暗同。」","sentenceOrder":90},
  {"id":"s_work_han_thu_86_91","chapterId":"ch_work_han_thu_86","textTraditional":"〔一０〕李奇曰：「名，聲名也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_86_92","chapterId":"ch_work_han_thu_86","textTraditional":"〔一一〕師古曰：「過猶謬也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_86_93","chapterId":"ch_work_han_thu_86","textTraditional":"〔一二〕師古曰：「枉，屈也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_86_94","chapterId":"ch_work_han_thu_86","textTraditional":"〔一三〕師古曰：「衡門，謂橫一木於門上，貧者之所居也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_86_95","chapterId":"ch_work_han_thu_86","textTraditional":"數歲，玄成徵為未央衛尉，遷太常。坐與故平通侯楊惲厚善，惲誅，黨友皆免官。後以列侯侍祀孝惠廟，當晨入廟，天雨淖，〔一〕不駕駟馬車而騎至廟下。有司劾奏，等輩數人皆削爵為關內侯。玄成自傷貶黜父爵，歎曰：「吾何面目以奉祭祀！」作詩自劾責，曰：","sentenceOrder":95},
  {"id":"s_work_han_thu_86_96","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「淖，泥也，音女教反。」","sentenceOrder":96},
  {"id":"s_work_han_thu_86_97","chapterId":"ch_work_han_thu_86","textTraditional":"赫矣我祖，侯于豕韋，賜命建伯，有殷以綏。〔一〕厥績既昭，車服有常，朝宗商邑，四牡翔翔。〔二〕德之令顯，慶流于裔，宗周至漢，群后歷世。〔三〕","sentenceOrder":97},
  {"id":"s_work_han_thu_86_98","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「建，立也。立為伯也。綏，安也。以有此伯，故天下安也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_86_99","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「翔翔，安舒貌。」","sentenceOrder":99},
  {"id":"s_work_han_thu_86_100","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　應劭曰：「歷世有爵位。」","sentenceOrder":100},
  {"id":"s_work_han_thu_86_101","chapterId":"ch_work_han_thu_86","textTraditional":"肅肅楚傅，輔翼元、夷，〔一〕厥駟有庸，惟慎惟祗。〔二〕嗣王孔佚，越遷于鄒，〔三〕五世壙僚，至我節侯。〔四〕","sentenceOrder":101},
  {"id":"s_work_han_thu_86_102","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「元王、夷王也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_86_103","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　孟康曰：「駟，駟馬也。尚書『車服以庸』。庸，功也。」師古曰：「庸亦常也，即上車服有常同義也。祗，敬也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_86_104","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「孔，甚也。佚與逸同。」","sentenceOrder":104},
  {"id":"s_work_han_thu_86_105","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　應劭曰：「自孟至賢五世無官。壙，空也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_86_106","chapterId":"ch_work_han_thu_86","textTraditional":"惟我節侯，顯德遐聞，〔一〕左右昭、宣，五品以訓。〔二〕既耇致位，惟懿惟奐，〔三〕厥賜祁祁，百金洎館。〔四〕國彼扶陽，在京之東，惟帝是留，政謀是從。繹繹六轡，是列是理，〔五〕威儀濟濟，朝享天子。天子穆穆，是宗是師，〔六〕四方遐爾，觀國之煇。〔七〕","sentenceOrder":106},
  {"id":"s_work_han_thu_86_107","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「聞，合韻音問。」","sentenceOrder":107},
  {"id":"s_work_han_thu_86_108","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「左右，助也，言為相也。五品，五教也。訓，理也。左讀曰佐，右讀曰佑。」","sentenceOrder":108},
  {"id":"s_work_han_thu_86_109","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「言以年致仕也。懿，美也。奐，盛也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_86_110","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「祁祁，行來貌。洎，及也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_86_111","chapterId":"ch_work_han_thu_86","textTraditional":"〔五〕　師古曰：「繹繹，和調之貌。」","sentenceOrder":111},
  {"id":"s_work_han_thu_86_112","chapterId":"ch_work_han_thu_86","textTraditional":"〔六〕　師古曰：「穆穆，天子之容也。宗，尊也，言天子尊之以為師。」","sentenceOrder":112},
  {"id":"s_work_han_thu_86_113","chapterId":"ch_work_han_thu_86","textTraditional":"〔七〕　師古曰：「煇，光也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_86_114","chapterId":"ch_work_han_thu_86","textTraditional":"茅土之繼，在我俊兄，惟我俊兄，是讓是形。〔一〕於休厥德，於赫有聲，〔二〕致我小子，越留於京。〔三〕惟我小子，不肅會同，〔四〕媠彼車服，黜此附庸。〔五〕","sentenceOrder":114},
  {"id":"s_work_han_thu_86_115","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「形，見也。言其謙讓志節顯見也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_86_116","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「於，皆歎辭也。休，美也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_86_117","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「言致爵位於己身而留在京師，豫朝請。」","sentenceOrder":117},
  {"id":"s_work_han_thu_86_118","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「肅，敬也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_86_119","chapterId":"ch_work_han_thu_86","textTraditional":"〔五〕　師古曰：「媠，古惰字也。削爵為關內侯，故云黜此附庸，言見黜而為附庸也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_86_120","chapterId":"ch_work_han_thu_86","textTraditional":"赫赫顯爵，自我隊之；微微附庸，自我招之。誰能忍媿，寄之我顏；誰將遐征，從之夷蠻。〔一〕於赫三事，匪俊匪作，於蔑小子，終焉其度。〔二〕誰謂華高，企其齊而；誰謂德難，厲其庶而。〔三〕嗟我小子，于貳其尤，〔四〕隊彼令聲，申此擇辭。〔五〕四方群后，我監我視，威儀車服，唯肅是履！〔六〕","sentenceOrder":120},
  {"id":"s_work_han_thu_86_121","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「言己恥辱之甚，無所自措，故曰誰有能忍媿者，以我顏寄之；誰欲遠行去者，當與相從，適於蠻夷，不能見朝廷之士也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_86_122","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「於，歎辭也。三事，三公之位也。度，居也。言三公顯職，以賢俊為之，我雖微蔑，方自勉厲，終當居此也。度音大各反。後並同。」","sentenceOrder":122},
  {"id":"s_work_han_thu_86_123","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「華，華山也。華山雖高，企仰則能齊觀。道德不易，克厲然庶幾可及也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_86_124","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「于，往也。尤，過也。自戒云，今以往勿貳其過。一曰，貳〔謂〕不一也，言心不專一，致此過也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_86_125","chapterId":"ch_work_han_thu_86","textTraditional":"〔五〕　師古曰：「令，善也。擇，可擇之辭。一曰，擇謂創也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_86_126","chapterId":"ch_work_han_thu_86","textTraditional":"〔六〕　師古曰：「戒他人。」","sentenceOrder":126},
  {"id":"s_work_han_thu_86_127","chapterId":"ch_work_han_thu_86","textTraditional":"初，宣帝寵姬張婕妤男淮陽憲王好政事，通法律，上奇其材，有意欲以為嗣，然用太子起於細微，又早失母，故不忍也。久之，上欲感風憲王，輔以禮讓之臣，〔一〕乃召拜玄成為淮陽中尉。是時王未就國，玄成受詔，與太子太傅蕭望之及五經諸儒雜論同異於石渠閣，條奏其對。及元帝即位，以玄成為少府，遷太子太傅，至御史大夫。永光中，代于定國為丞相。貶黜十年之間，遂繼父相位，封侯故國，榮當世焉。玄成復作詩，自著復玷缺之艱難，〔二〕因以戒示子孫，曰：","sentenceOrder":127},
  {"id":"s_work_han_thu_86_128","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「風讀曰諷。」","sentenceOrder":128},
  {"id":"s_work_han_thu_86_129","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「玉缺曰玷。復音房目反。囏，古艱字。玷音丁念反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_86_130","chapterId":"ch_work_han_thu_86","textTraditional":"於肅君子，既令厥德，〔一〕儀服此恭，棣棣其則。〔二〕咨余小子，既德靡逮，〔三〕曾是車服，荒嫚以隊。〔四〕","sentenceOrder":130},
  {"id":"s_work_han_thu_86_131","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「於，歎辭也。肅，敬也。令，善也。言君子之人，皆肅敬以善其德也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_86_132","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　李奇曰：「善威儀也。」師古曰：「詩邶柏舟曰：『威儀逮逮，不可選也。』逮逮，閑習之貌，音徒繼反。」","sentenceOrder":132},
  {"id":"s_work_han_thu_86_133","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「逮，及也，自言德不及也。」","sentenceOrder":133},
  {"id":"s_work_han_thu_86_134","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「曾之言則也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_86_135","chapterId":"ch_work_han_thu_86","textTraditional":"明明天子，俊德烈烈，不遂我遺，恤我九列。〔一〕我既茲恤，惟夙惟夜，〔二〕畏忌是申，供事靡惰。〔三〕天子我監，登我三事，〔四〕顧我傷隊，爵復我舊。","sentenceOrder":135},
  {"id":"s_work_han_thu_86_136","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「恤，安也。九列，卿之位，謂少府。」","sentenceOrder":136},
  {"id":"s_work_han_thu_86_137","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「夙，早也。言早夜常自戒也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_86_138","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「申，言自約束也。憜，古惰字。」","sentenceOrder":138},
  {"id":"s_work_han_thu_86_139","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「監，察也。三事，三公之位，謂丞相也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_86_140","chapterId":"ch_work_han_thu_86","textTraditional":"我既此登，望我舊階，先后茲度，漣漣孔懷。〔一〕司直御事，我熙我盛；〔二〕群公百僚，我嘉我慶。于異卿士，非同我心，三事惟囏，莫我肯矜。〔三〕赫赫三事，力雖此畢，非（吾）〔我〕所度，退其罔日。〔四〕昔我之隊，畏不此居，〔五〕今我度茲，戚戚其懼。〔六〕","sentenceOrder":140},
  {"id":"s_work_han_thu_86_141","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　應劭曰：「我既此登，為丞相也。先后茲度，父所在也。」臣瓚曰：「案古文宅度同。」師古曰：「先后即先君也。以父昔居此位，故泣涕而甚思之也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_86_142","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「司直，丞相司直也。御事，治事之吏也。言司直及治事之人助我興盛而為職務也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_86_143","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「言己居尊位，懼不克勝，而群公百官，皆來相慶，是與我心不同也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_86_144","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「我雖畢力於此，然懼非所居，眨退無日。」","sentenceOrder":144},
  {"id":"s_work_han_thu_86_145","chapterId":"ch_work_han_thu_86","textTraditional":"〔五〕　師古曰：「居，合韻音基庶反。」","sentenceOrder":145},
  {"id":"s_work_han_thu_86_146","chapterId":"ch_work_han_thu_86","textTraditional":"〔六〕　師古曰：「度亦居也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_86_147","chapterId":"ch_work_han_thu_86","textTraditional":"嗟我後人，命其靡常，靖享爾位，瞻仰靡荒。〔一〕慎爾會同，戒爾車服，無惰爾儀，以保爾域。〔二〕爾無我視，不慎不整；我之此復，惟祿之幸。〔三〕於戲後人，惟肅惟栗。〔四〕無忝顯祖，以蕃漢室！","sentenceOrder":147},
  {"id":"s_work_han_thu_86_148","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「靖，謀也。享，當也。言天（會）〔命〕無常，唯善是祐。謀當爾位，無荒怠也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_86_149","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「媠亦古惰字也。域謂封邑也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_86_150","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「言我之得復此爵，乃蒙天之福幸而遇之，爾等不當視效而怠慢也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_86_151","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「於戲讀曰嗚乎。」","sentenceOrder":151},
  {"id":"s_work_han_thu_86_152","chapterId":"ch_work_han_thu_86","textTraditional":"玄成為相七年，守正持重不及父賢，而文采過之。建昭三年薨，諡曰共侯。初，賢以昭帝時徙平陵，玄成別徙杜陵，病且死，因使者自白曰：「不勝父子恩，願乞骸骨，歸葬父墓。」上許焉。","sentenceOrder":152},
  {"id":"s_work_han_thu_86_153","chapterId":"ch_work_han_thu_86","textTraditional":"子頃侯寬嗣。薨，子僖侯育嗣。薨，子節侯沈嗣。自賢傳國至玄孫乃絕。玄成兄高寢令方山子安世歷郡守，大鴻臚，長樂衛尉，朝廷稱有宰相之器，會其病終。而東海太守弘子賞亦明詩。哀帝為定陶王時，賞為太傅。哀帝即位，賞以舊恩為大司馬車騎將軍，列為三公，賜爵關內侯，食邑千戶，亦年八十餘，以壽終。宗族至吏二千石者十餘人。","sentenceOrder":153},
  {"id":"s_work_han_thu_86_154","chapterId":"ch_work_han_thu_86","textTraditional":"初，高祖時，令諸侯王都皆立太上皇廟。至惠帝尊高帝廟為太祖廟，景帝尊孝文廟為太宗廟，行所嘗幸郡國各立太祖、太宗廟。至宣帝本始二年，復尊孝武廟為世宗廟，行所巡狩亦立焉。凡祖宗廟在郡國六十八，合百六十七所。〔一〕而京師自高祖下至宣帝，與太上皇、悼皇考各自居陵旁立廟，〔二〕并為百七十六。又園中各有寢、便殿。〔三〕日祭於寢，月祭於廟，時祭於便殿。寢，日四上食；廟，歲二十五祠；〔四〕便殿，歲四祠。又月一游衣冠。而昭靈后、武哀王、昭哀后、孝文太后、孝昭太后、衛思后、戾太子、戾后各有寢園，與諸帝合，凡三十所。一歲祠，上食二萬四千四百五十五，用衛士四萬五千一百二十九人，祝宰樂人萬二千一百四十七人，養犧牲卒不在數中。","sentenceOrder":154},
  {"id":"s_work_han_thu_86_155","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「六十八者，郡國之數也。百六十七所，宗廟之數也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_86_156","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「悼皇考者，宣帝之父，即史皇孫。」","sentenceOrder":156},
  {"id":"s_work_han_thu_86_157","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　如淳曰：「黃圖高廟有便殿，是中央正殿也。」師古曰：「如說非也。凡言便殿、便室者，皆非正大之處。寢者，陵上正殿，若平生露寢矣。便殿者，寢側之（便）〔別〕殿耳。」","sentenceOrder":157},
  {"id":"s_work_han_thu_86_158","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　如淳曰：「月祭朔望，加臘月二十五。」晉灼曰：「漢儀注宗廟一歲十二祠。五月嘗麥。六月、七月三伏、立秋貙婁，又嘗粢。八月先夕饋飧，皆一太牢，酎祭用九太牢。十月嘗稻，又飲蒸，二太牢。十〔一〕月嘗，十二月臘，二太牢。又每月一太牢，如閏加一祀，與此上十二為二十五祠。」師古曰：「晉說是也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_86_159","chapterId":"ch_work_han_thu_86","textTraditional":"至元帝時，貢禹奏言：「古者天子七廟，今孝惠、孝景廟皆親盡，宜毀。及郡國廟不應古禮，宜正定。」天子是其議，未及施行而禹卒。永光四年，乃下詔先議罷郡國廟，曰：「朕聞明王之御世也，遭時為法，因事制宜。〔一〕往者天下初定，遠方未賓，因嘗所親以立宗廟，〔二〕蓋建威銷萌，一民之至權也。〔三〕今賴天地之靈，宗廟之福，四方同軌，蠻貊貢職，〔四〕久遵而不定，令疏遠卑賤共承尊祀，〔五〕殆非皇天祖宗之意，朕甚懼焉。傳不云乎？『吾不與祭，如不祭。』〔六〕其與將軍、列侯、中二千石、二千石、諸大夫、博士、議郎議。」丞相玄成、御史大夫鄭弘、太子太傅嚴彭祖、少府歐陽地餘、諫大夫尹更始等七十人皆曰：「臣聞祭，非自外至者也，繇中出，生於心也。〔七〕故唯聖人為能饗帝，孝子為能饗親。〔八〕立廟京師之居，躬親承事，四海之內各以其職來助祭，尊親之大義，五帝三王所共，不易之道也。〔九〕詩云：『有來雍雍，至止肅肅，相維辟公，天子穆穆。』〔一０〕春秋之義，父不祭於支庶之宅，君不祭於臣僕之家，王不祭於下土諸侯。臣等愚以為宗廟在郡國，宜無修，臣請勿復修。」奏可。因罷昭靈后、武哀王、昭哀后、衛思后、戾太子、戾后園，皆不奉祠，裁置吏卒守焉。","sentenceOrder":159},
  {"id":"s_work_han_thu_86_160","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「言不必同也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_86_161","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「親謂親臨幸處也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_86_162","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「銷遏逆亂，使不得萌生。」","sentenceOrder":162},
  {"id":"s_work_han_thu_86_163","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「同軌，言車轍皆同，示法制齊也。」","sentenceOrder":163},
  {"id":"s_work_han_thu_86_164","chapterId":"ch_work_han_thu_86","textTraditional":"〔五〕　師古曰：「共讀曰恭。」","sentenceOrder":164},
  {"id":"s_work_han_thu_86_165","chapterId":"ch_work_han_thu_86","textTraditional":"〔六〕　師古曰：「論語載孔子之言。與讀曰預。」","sentenceOrder":165},
  {"id":"s_work_han_thu_86_166","chapterId":"ch_work_han_thu_86","textTraditional":"〔七〕　師古曰：「繇讀與由同。」","sentenceOrder":166},
  {"id":"s_work_han_thu_86_167","chapterId":"ch_work_han_thu_86","textTraditional":"〔八〕　師古曰：「言情禮皆備。」","sentenceOrder":167},
  {"id":"s_work_han_thu_86_168","chapterId":"ch_work_han_thu_86","textTraditional":"〔九〕　師古曰：「易，改也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_86_169","chapterId":"ch_work_han_thu_86","textTraditional":"〔一０〕師古曰：「此周頌雍篇（祖）〔禘〕太祖之詩也。雍雍，和也。肅肅，敬也。相，助也。辟，百辟卿士也。公，諸侯也。有來而和者，至而敬者，助王禘祭，是百辟諸侯也。天子是時則穆穆然承事也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_86_170","chapterId":"ch_work_han_thu_86","textTraditional":"罷郡國廟後月餘，復下詔曰：「蓋聞明王制禮，立親廟四，祖宗之廟，萬世不毀，所以明尊祖敬宗，著親親也。〔一〕朕獲承祖宗之重，惟大禮未備，戰栗恐懼，不敢自顓，〔二〕其與將軍、列侯、中二千石、二千石、諸大夫、博士議。」玄成等四十四人奏議曰：「禮，王者始受命，諸侯始封之君，皆為太祖。以下，五廟而迭毀，〔三〕毀廟之主臧乎太祖，五年而再殷祭，言壹禘壹祫也。〔四〕祫祭者，毀廟與未毀廟之主皆合食於太祖，父為昭，子為穆，孫復為昭，古之正禮也。〔五〕祭義曰：『王者禘其祖自出，〔六〕以其祖配之，而立四廟。』言始受命而王，祭天以其祖配，而不為立廟，親盡也。立親廟四，親親也。親盡而迭毀，親疏之殺，示有終也。〔七〕周之所以七廟者，以后稷始封，文王、武王受命而王，是以三廟不毀，與親廟四而七。非有后稷始封，文、武受命之功者，皆當親盡而毀。成王成二聖之業，〔八〕制禮作樂，功德茂盛，廟猶不世，以行為諡而已。〔九〕禮，廟在大門之內，不敢遠親也。〔一０〕臣愚以為高帝受命定天下，宜為帝者太祖之廟，世世不毀，承後屬盡者宜毀。今宗廟異處，昭穆不序，宜入就太祖廟而序昭穆如禮。太上皇、孝惠、孝文、孝景廟皆親盡宜毀，皇考廟親未盡，如故。」〔一一〕大司馬車騎將軍許嘉等二十九人以為孝文皇帝除誹謗，去肉刑，躬節儉，不受獻，罪人不帑，不私其利，〔一二〕出美人，重絕人類，賓賜長老，收恤孤獨，德厚侔天地，利澤施四海，宜為帝者太宗之廟。廷尉忠以為孝武皇帝改正朔，易服色，攘四夷，宜為世宗之廟。〔一三〕諫大夫尹更始等十八人以為皇考廟上序於昭穆，非正禮，宜毀。","sentenceOrder":170},
  {"id":"s_work_han_thu_86_171","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「著亦明也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_86_172","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「顓與專同。」","sentenceOrder":172},
  {"id":"s_work_han_thu_86_173","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「迭，互也。親盡則毀，故云迭也，音大結反。」","sentenceOrder":173},
  {"id":"s_work_han_thu_86_174","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「殷，大也。禘，諦也。（一）〔壹〕，一祭之也。祫，合也。禘音大系反。祫音洽。」","sentenceOrder":174},
  {"id":"s_work_han_thu_86_175","chapterId":"ch_work_han_thu_86","textTraditional":"〔五〕　師古曰：「昭穆者，父子易其號序也。昭，明也。穆，美也。後以晉室諱昭，故學者改昭為韶。」","sentenceOrder":175},
  {"id":"s_work_han_thu_86_176","chapterId":"ch_work_han_thu_86","textTraditional":"〔六〕　師古曰：「祖所從出者。」","sentenceOrder":176},
  {"id":"s_work_han_thu_86_177","chapterId":"ch_work_han_thu_86","textTraditional":"〔七〕　師古曰：「殺，漸降也，音所例反。」","sentenceOrder":177},
  {"id":"s_work_han_thu_86_178","chapterId":"ch_work_han_thu_86","textTraditional":"〔八〕　師古曰：「二聖，文王、武王也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_86_179","chapterId":"ch_work_han_thu_86","textTraditional":"〔九〕　師古曰：「謂之成王，則是以行表諡也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_86_180","chapterId":"ch_work_han_thu_86","textTraditional":"〔一０〕師古曰：「遠，離也，音于萬反。」","sentenceOrder":180},
  {"id":"s_work_han_thu_86_181","chapterId":"ch_work_han_thu_86","textTraditional":"〔一一〕張晏曰：「悼皇考於元帝祖也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_86_182","chapterId":"ch_work_han_thu_86","textTraditional":"〔一二〕師古曰：「重罪之人不及妻子，是不私其利也。帑讀與孥同。」","sentenceOrder":182},
  {"id":"s_work_han_thu_86_183","chapterId":"ch_work_han_thu_86","textTraditional":"〔一三〕師古曰：「忠，尹忠也。攘，卻也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_86_184","chapterId":"ch_work_han_thu_86","textTraditional":"於是上重其事，〔一〕依違者一年，〔二〕乃下詔曰：「蓋聞王者祖有功而宗有德，尊尊之大義也；存親廟四，親親之至恩也。高皇帝為天下誅暴除亂，受命而帝，功莫大焉。孝文皇帝國為代王，諸呂作亂，海內搖動，然群臣黎庶靡不壹意，北面而歸心，猶謙辭固讓而後即位，削亂秦之跡，興三代之風，是以百姓晏然，咸獲嘉福，德莫盛焉。高皇帝為漢太祖，孝文皇帝為太宗，世世承祀，傳之無窮，朕甚樂之。孝宣皇帝為孝昭皇帝後，於義壹體。〔三〕孝景皇帝廟及皇考廟皆親盡，其正禮儀。」玄成等奏曰：「祖宗之廟世世不毀，繼祖以下，五廟而迭毀。今高皇帝為太祖，孝文皇帝為太宗，孝景皇帝為昭，孝武皇帝為穆，孝昭皇帝與孝宣皇帝俱為昭。皇考廟親未盡。太上、孝惠廟皆親盡，宜毀。太上廟主宜瘞園，孝惠皇帝為穆，主遷於太祖廟，寢園皆無復修。」奏可。","sentenceOrder":184},
  {"id":"s_work_han_thu_86_185","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「重，難也。」","sentenceOrder":185},
  {"id":"s_work_han_thu_86_186","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「依違者，不決也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_86_187","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「一體謂俱為昭也。禮，孫與祖俱為昭。宣帝之於昭帝為從孫，故云於義一體。」","sentenceOrder":187},
  {"id":"s_work_han_thu_86_188","chapterId":"ch_work_han_thu_86","textTraditional":"議者又以為清廟之詩言交神之禮無不清靜，〔一〕今衣冠出游，有車騎之眾，風雨之氣，非所謂清靜也。「祭不欲數。數則瀆，瀆則不敬。」〔二〕宜復古禮，四時祭於廟，諸寢園日月間祀皆可勿復修。〔三〕上亦不改也。明年，玄成復言：「古者制禮，別尊卑貴賤，國君之母非適不得配食，則薦於寢，〔四〕身沒而已。陛下躬至孝，承天心，建祖宗，定迭毀，序昭穆，大禮既定，孝文太后、孝昭太后寢祠園宜如禮勿復修。」奏可。","sentenceOrder":188},
  {"id":"s_work_han_thu_86_189","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「清廟，周頌祀文王之詩。其詩云『於穆清廟，肅雍顯相』，又曰『對越在天，駿奔走在廟』。」","sentenceOrder":189},
  {"id":"s_work_han_thu_86_190","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「此禮記祭法之言。瀆，煩汙也。數音所角反。」","sentenceOrder":190},
  {"id":"s_work_han_thu_86_191","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「間音工莧反。」","sentenceOrder":191},
  {"id":"s_work_han_thu_86_192","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「適讀曰嫡也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_86_193","chapterId":"ch_work_han_thu_86","textTraditional":"後歲餘，玄成薨，匡衡為丞相。上寢疾，夢祖宗譴罷郡國廟，上少弟楚孝王亦夢焉。上詔問衡，議欲復之，衡深言不可。上疾久不平，衡惶恐，禱高祖、孝文、孝武廟曰：「嗣曾孫皇帝恭承洪業，夙夜不敢康寧，思育休烈，以章祖宗之盛功。〔一〕故動作接神，必因古聖之經。往者有司以為前因所幸而立廟，將以繫海內之心，非為尊祖嚴親也。今賴宗廟之靈，六合之內莫不附親，廟宜一居京師，天子親奉，郡國廟可止毋修。皇帝祗肅舊禮，尊重神明，即告于祖宗而不敢失。〔二〕今皇帝有疾不豫，乃夢祖宗見戒以廟，楚王夢亦有其序。〔三〕皇帝悼懼，即詔臣衡復修立。謹案上世帝王承祖禰之大（義）〔禮〕，皆不敢不自親。郡國吏卑賤，不可使獨承。又祭祀之義以民為本，間者歲數不登，百姓困乏，郡國廟無以修立。禮，凶年則歲事不舉，以祖禰之意為不樂，是以不敢復。〔四〕如誠非禮義之中，違祖宗之心，咎盡在臣衡，〔五〕當受其殃，大被其疾，隊在溝瀆之中。皇帝至孝肅慎，宜蒙祐福。唯高皇帝、孝文皇帝、孝武皇帝省察，右饗皇帝之孝，〔六〕開賜皇帝眉壽亡疆，〔七〕令所疾日瘳，平復反常，〔八〕永保宗廟，天下幸甚！」","sentenceOrder":193},
  {"id":"s_work_han_thu_86_194","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「育，養也。休，美也。烈，業也。」","sentenceOrder":194},
  {"id":"s_work_han_thu_86_195","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「不敢失禮。」","sentenceOrder":195},
  {"id":"s_work_han_thu_86_196","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「序，緒也，謂端緒也。」","sentenceOrder":196},
  {"id":"s_work_han_thu_86_197","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「復音房目反。」","sentenceOrder":197},
  {"id":"s_work_han_thu_86_198","chapterId":"ch_work_han_thu_86","textTraditional":"〔五〕　師古曰：「如，若也。中音竹仲反。」","sentenceOrder":198},
  {"id":"s_work_han_thu_86_199","chapterId":"ch_work_han_thu_86","textTraditional":"〔六〕　師古曰：「右讀曰祐。」","sentenceOrder":199},
  {"id":"s_work_han_thu_86_200","chapterId":"ch_work_han_thu_86","textTraditional":"〔七〕　師古曰：「眉壽言壽考而眉秀也。疆，境也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_86_201","chapterId":"ch_work_han_thu_86","textTraditional":"〔八〕　師古曰：「反猶還也。」","sentenceOrder":201},
  {"id":"s_work_han_thu_86_202","chapterId":"ch_work_han_thu_86","textTraditional":"又告謝毀廟曰：「往者大臣以為在昔帝王承祖宗之休典，取象於天地，〔一〕天序五行，人親五屬，〔二〕天子奉天，故率其意而尊其制。是以禘嘗之序，靡有過五。受命之君躬接于天，萬世不墮。繼烈以下，五廟而遷，〔三〕上陳太祖，間歲而祫，〔四〕其道應天，故福祿永終。太上皇非受命而屬盡，義則當遷。又以為孝莫大於嚴父，故父之所尊子不敢不承，父之所異子不敢同。禮，公子不得為母信，為後則於子祭，於孫止，〔五〕尊祖嚴父之義也。寢日四上食，園廟間祠，皆可亡修。〔六〕皇帝思慕悼懼，未敢盡從。惟念高皇帝聖德茂盛，受命溥將，欽若稽古，承順天心，〔七〕子孫本支，陳錫亡疆。〔八〕誠以為遷廟合祭，久長之策，高皇帝之意，乃敢不聽〔九〕？即以令日〔一０〕遷太上、孝惠廟，孝文太后、孝昭太后寢，將以昭祖宗之德，順天人之序，定無窮之業。今皇帝未受茲福，乃有不能共職之疾。〔一一〕皇帝願復修承祀，臣衡等咸以為禮不得。〔一二〕如不合高皇帝、孝惠皇帝、孝文皇帝、孝武皇帝、孝昭皇帝、孝宣皇帝、太上皇、孝文太后、孝昭太后之意，罪盡在臣衡等，當受其咎。今皇帝尚未平，詔中朝臣具復毀廟之文。臣衡中朝臣咸復以為天子之祀義有所斷，禮有所承，違統背制，不可以奉先祖，皇天不祐，鬼神不饗。六藝所載，皆言不當，〔一三〕無所依緣，以作其文。事如失指，罪乃在臣衡，當深受其殃。皇帝宜厚蒙祉福，嘉氣日興，疾病平復，永保宗廟，與天亡極，群生百神，有所歸息。」〔一四〕諸廟皆同文。","sentenceOrder":202},
  {"id":"s_work_han_thu_86_203","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「休，美也。典，法也。」","sentenceOrder":203},
  {"id":"s_work_han_thu_86_204","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「五屬謂同族之五服，斬衰、齊衰、大功、小功、緦麻也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_86_205","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「墮，毀也。烈，業也。繼謂始嗣位者也。墮音火規反。」","sentenceOrder":205},
  {"id":"s_work_han_thu_86_206","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「間歲，隔一歲也。」","sentenceOrder":206},
  {"id":"s_work_han_thu_86_207","chapterId":"ch_work_han_thu_86","textTraditional":"〔五〕　李奇曰：「不得信，尊其父也。公子去其所而為大宗後，尚得私祭其母，為孫則止，不得祭公子母也，明繼祖不（得）〔復〕顧其私祖母也。」師古曰：「信讀曰伸。」","sentenceOrder":207},
  {"id":"s_work_han_thu_86_208","chapterId":"ch_work_han_thu_86","textTraditional":"〔六〕　師古曰：「間音工莧反。」","sentenceOrder":208},
  {"id":"s_work_han_thu_86_209","chapterId":"ch_work_han_thu_86","textTraditional":"〔七〕　師古曰：「溥，廣也。將，大也。欽，敬也。若，善也。稽，考也。商頌烈祖之篇曰『我受命溥將』。虞書堯典曰『欽若昊天』，又曰『若稽古帝堯』，故衡總引之。」","sentenceOrder":209},
  {"id":"s_work_han_thu_86_210","chapterId":"ch_work_han_thu_86","textTraditional":"〔八〕　師古曰：「詩大雅文王之篇曰：『陳錫載周，侯文王孫子。文王孫子，本支百世。』陳，敷也。載，始也。本，本宗也。支，支子也。言子孫承受敷錫初始之福，故得永久無窮竟也。」","sentenceOrder":210},
  {"id":"s_work_han_thu_86_211","chapterId":"ch_work_han_thu_86","textTraditional":"〔九〕　師古曰：「言不敢不從。」","sentenceOrder":211},
  {"id":"s_work_han_thu_86_212","chapterId":"ch_work_han_thu_86","textTraditional":"〔一０〕師古曰：「令，善也。謂吉日也。」","sentenceOrder":212},
  {"id":"s_work_han_thu_86_213","chapterId":"ch_work_han_thu_86","textTraditional":"〔一一〕師古曰：「共讀曰恭。」","sentenceOrder":213},
  {"id":"s_work_han_thu_86_214","chapterId":"ch_work_han_thu_86","textTraditional":"〔一二〕師古曰：「於禮不合也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_86_215","chapterId":"ch_work_han_thu_86","textTraditional":"〔一三〕師古曰：「六藝，（之）〔六〕經也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_86_216","chapterId":"ch_work_han_thu_86","textTraditional":"〔一四〕師古曰：「息，止也。」","sentenceOrder":216},
  {"id":"s_work_han_thu_86_217","chapterId":"ch_work_han_thu_86","textTraditional":"久之，上疾連年，遂盡復諸所罷寢廟園，皆修祀如故。初，上定迭毀禮，獨尊孝文廟為太宗，而孝武廟親未盡，故未毀。上於是乃復申明之，曰：「孝宣皇帝尊孝武廟曰世宗，損益之禮，不敢有與焉。〔一〕他皆如舊制。」唯郡國廟遂廢云。","sentenceOrder":217},
  {"id":"s_work_han_thu_86_218","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「與讀曰預。其下亦同。」","sentenceOrder":218},
  {"id":"s_work_han_thu_86_219","chapterId":"ch_work_han_thu_86","textTraditional":"元帝崩，衡奏言：「前以上體不平，故復諸所罷祠，卒不蒙福。〔一〕案衛思后、戾太子、戾后園，親未盡。〔二〕孝惠、孝景廟親盡，宜毀。及太上皇、孝文、孝昭太后、昭靈后、昭哀后、武哀王祠，請悉罷，勿奉。」奏可。初，高后時患臣下妄非議先帝宗廟寢園官，故定著令，敢有擅議者棄市。至元帝改制，蠲除此令。成帝時以無繼嗣，河平元年復復太上皇寢廟園，世世奉祠。昭靈后、武哀王、昭哀后并食於太上寢廟如故，又復擅議宗廟之命。〔三〕","sentenceOrder":219},
  {"id":"s_work_han_thu_86_220","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「卒，終也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_86_221","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「言不當毀也。」","sentenceOrder":221},
  {"id":"s_work_han_thu_86_222","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「復音方目反。」","sentenceOrder":222},
  {"id":"s_work_han_thu_86_223","chapterId":"ch_work_han_thu_86","textTraditional":"成帝崩，哀帝即位。丞相孔光、大司空何武奏言：「永光五年制書，高皇帝為漢太祖，孝文皇帝為太宗。建昭五年制書，孝武皇帝為世宗。損益之禮，不敢有與。臣愚以為迭毀之次，當以時定，非令所為擅議宗廟之意也。臣請與群臣雜議。」奏可。於是，光祿勳彭宣、詹事滿昌、博士左咸等五十三人皆以為繼祖宗以下，五廟而迭毀，後雖有賢君，猶不得與祖宗並列。子孫雖欲褒大顯揚而立之，鬼神不饗也。孝武皇帝雖有功烈，親盡宜毀。","sentenceOrder":223},
  {"id":"s_work_han_thu_86_224","chapterId":"ch_work_han_thu_86","textTraditional":"太僕王舜、中壘校尉劉歆議曰：「臣聞周室既衰，四夷並侵，獫狁最彊，於今匈奴是也。至宣王而伐之，詩人美而頌之曰『薄伐獫狁，至于太原』，〔一〕又曰『嘽嘽推推，如霆如雷，顯允方叔，征伐獫狁，荊蠻來威』，〔二〕故稱中興。及至幽王，犬戎來伐，殺幽王，取宗器。〔三〕自是之後，南夷與北夷交侵，中國不絕如綫。〔四〕春秋紀齊桓南伐楚，北伐山戎，孔子曰：『微管仲，吾其被髮左衽矣。』〔五〕是故棄桓之過而錄其功，以為伯首。〔六〕及漢興，冒頓始彊，破東胡，禽月氏，〔七〕并其土地，地廣兵彊，為中國害。南越尉佗總百粵，自稱帝。故中國雖平，猶有四夷之患，且無寧歲。一方有急，三面救之，是天下皆動而被其害也。孝文皇帝厚以貨賂，與結和親，猶侵暴無已。甚者，興師十餘萬眾，近屯京師及四邊，歲發屯備虜，其為患久矣，非一世之漸也。諸侯郡守連匈奴及百粵以為逆者非一人也。匈奴所殺郡守都尉，略取人民，不可勝數。孝武皇帝愍中國罷勞無安寧之時，〔八〕乃遣大將軍、驃騎、伏波、樓船之屬，南滅百粵，起七郡；北攘匈奴，降昆邪十萬之眾，〔九〕置五屬國，起朔方，以奪其肥饒之地；東伐朝鮮，起玄菟、樂浪，以斷匈奴之左臂；〔一０〕西伐大宛，並三十六國，結烏孫，起敦煌、酒泉、張掖，以鬲婼羌，裂匈奴之右肩。〔一一〕單于孤特，遠遁于幕北。四垂無事，斥地遠境，起十餘郡。〔一二〕功業既定，乃封丞相為富民侯，以大安天下，富實百姓，其規橅可見。〔一三〕又招集天下賢俊，與協心同謀，興制度，改正朔，易服色，立天地之祠，建封禪，殊官號，存周後，定諸侯之制，永無逆爭之心，至今累世賴之。單于守藩，百蠻服從，萬世之基也，中興之功未有高焉者也。高帝建大業，為太祖；孝文皇帝德至厚也，為文太宗；孝武皇帝功至著也，為武世宗；此孝宣帝所以發德音也。禮記王制及春秋穀梁傳，天子七廟，諸侯五，大夫三，士二。天子七日而殯，七月而葬；諸侯五日而殯，五月而葬；此喪事尊卑之序也，與廟數相應。其文曰：『天子三昭三穆，與太祖之廟而七；諸侯二昭二穆，與太祖之廟而五。』故德厚者流光，德薄者流卑。〔一四〕春秋左氏傳曰：『名位不同，禮亦異數。』自上以下，降殺以兩，禮也。〔一五〕七者，其正法數，可常數者也。宗不在此數中。宗，變也，〔一六〕苟有功德則宗之，不可預為設數。故於殷，太甲為太宗，大戊曰中宗，武丁曰高宗。〔一七〕周公為毋逸之戒，舉殷三宗以勸成王。〔一八〕繇是言之，宗無數也，〔一九〕然則所以勸帝者之功德博矣。以七廟言之，孝武皇帝未宜毀；以所宗言之，則不可謂無功德。禮記祀典曰：『夫聖王之制祀也，功施於民則祀之，以勞定國則祀之，能救大災則祀之。』竊觀孝武皇帝，功德皆兼而有焉。凡在於異姓，猶將特祀之，況于先祖？或說天子五廟無見文，又說中宗、高宗者，宗其道而毀其廟。名與實異，非尊德貴功之意也。詩云：『蔽芾甘棠，勿鬋勿伐，邵伯所茇。』〔二０〕思其人猶愛其樹，況宗其道而毀其廟乎？迭毀之禮自有常法，無殊功異德，固以親疏相推及。至祖宗之序，多少之數，經傳無明文，至尊至重，難以疑文虛說定也。孝宣皇舉公卿之議，用眾儒之謀，既以為世宗之廟，建之萬世，宣布天下。臣愚以為孝武皇帝功烈如彼，孝宣皇帝崇立之如此，不宜毀。」上覽其議而從之。制曰：「太僕舜、中壘校尉歆議可。」","sentenceOrder":224},
  {"id":"s_work_han_thu_86_225","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「小雅六月之詩也。薄伐，言逐出之。」","sentenceOrder":225},
  {"id":"s_work_han_thu_86_226","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「小雅采虯之詩也。嘽嘽，眾也。推推，盛也。顯，明也。允，信也。方叔，周之卿士，命為將率也。言出師眾盛，有如雷霆。方叔又能信明其德，既伐獫狁，懲其侵暴，則南荊之蠻，亦畏威而來服也。嘽嘽音他丹反。推音他回反。」","sentenceOrder":226},
  {"id":"s_work_han_thu_86_227","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「宗器，宗廟之器也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_86_228","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　師古曰：「綫，縷也，音思薦反。」","sentenceOrder":228},
  {"id":"s_work_han_thu_86_229","chapterId":"ch_work_han_thu_86","textTraditional":"〔五〕　師古曰：「論語載孔子之言也。微，無也。被髮左衽，戎狄之服。言無管仲佐齊桓公征討，則中夏皆將為夷狄也。」","sentenceOrder":229},
  {"id":"s_work_han_thu_86_230","chapterId":"ch_work_han_thu_86","textTraditional":"〔六〕　師古曰：「伯讀曰霸。」","sentenceOrder":230},
  {"id":"s_work_han_thu_86_231","chapterId":"ch_work_han_thu_86","textTraditional":"〔七〕　師古曰：「氏讀曰支。」","sentenceOrder":231},
  {"id":"s_work_han_thu_86_232","chapterId":"ch_work_han_thu_86","textTraditional":"〔八〕　師古曰：「罷讀曰疲。」","sentenceOrder":232},
  {"id":"s_work_han_thu_86_233","chapterId":"ch_work_han_thu_86","textTraditional":"〔九〕　師古曰：「昆音下門反。」","sentenceOrder":233},
  {"id":"s_work_han_thu_86_234","chapterId":"ch_work_han_thu_86","textTraditional":"〔一０〕師古曰：「樂音來各反。浪音郎。」","sentenceOrder":234},
  {"id":"s_work_han_thu_86_235","chapterId":"ch_work_han_thu_86","textTraditional":"〔一一〕師古曰：「婼音而遮反。」","sentenceOrder":235},
  {"id":"s_work_han_thu_86_236","chapterId":"ch_work_han_thu_86","textTraditional":"〔一二〕師古曰：「斥，開也。遠，廣也。」","sentenceOrder":236},
  {"id":"s_work_han_thu_86_237","chapterId":"ch_work_han_thu_86","textTraditional":"〔一三〕師古曰：「橅讀曰摹，其字從木。」","sentenceOrder":237},
  {"id":"s_work_han_thu_86_238","chapterId":"ch_work_han_thu_86","textTraditional":"〔一四〕師古曰：「流謂流風餘福。」","sentenceOrder":238},
  {"id":"s_work_han_thu_86_239","chapterId":"ch_work_han_thu_86","textTraditional":"〔一五〕師古曰：「殺音所例反。」","sentenceOrder":239},
  {"id":"s_work_han_thu_86_240","chapterId":"ch_work_han_thu_86","textTraditional":"〔一六〕師古曰：「言非常數，故云變也。」","sentenceOrder":240},
  {"id":"s_work_han_thu_86_241","chapterId":"ch_work_han_thu_86","textTraditional":"〔一七〕師古曰：「太甲，湯之孫，太丁之子也。太戊，太庚之子，雍己之弟也。武丁，小乙之子。」","sentenceOrder":241},
  {"id":"s_work_han_thu_86_242","chapterId":"ch_work_han_thu_86","textTraditional":"〔一八〕師古曰：「毋逸，尚書篇名。戒以無逸豫也。」","sentenceOrder":242},
  {"id":"s_work_han_thu_86_243","chapterId":"ch_work_han_thu_86","textTraditional":"〔一九〕師古曰：「繇與由同也。」","sentenceOrder":243},
  {"id":"s_work_han_thu_86_244","chapterId":"ch_work_han_thu_86","textTraditional":"〔二０〕師古曰：「召南甘棠之詩也。解已在前。鬋字與翦同。茇音步葛反。」","sentenceOrder":244},
  {"id":"s_work_han_thu_86_245","chapterId":"ch_work_han_thu_86","textTraditional":"歆又以為「禮，去事有殺，〔一〕故春秋外傳曰：『日祭，月祀，時享，歲貢，終王。』祖禰則日祭，曾高則月祀，二祧則時享，壇墠則歲貢，〔二〕大禘則終王。〔三〕德盛而游廣，親親之殺也〔四〕；彌遠則彌尊，故禘為重矣。孫居王父之處，正昭穆，則孫常與祖相代，此遷廟之殺也。聖人於其祖，出於情矣，禮無所不順，故無毀廟。〔五〕自貢禹建迭毀之議，惠、景及太上寢園廢而為虛，〔六〕失禮意矣。」","sentenceOrder":245},
  {"id":"s_work_han_thu_86_246","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「去，除也。殺，漸也。去音丘呂反。殺音所例反。其下並同也。」","sentenceOrder":246},
  {"id":"s_work_han_thu_86_247","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　張晏曰：「去祧為壇。墠，掃地而祭也。」師古曰：「祧是遠祖也。築土為壇，除地為墠。祧音他堯反。墠音善。」","sentenceOrder":247},
  {"id":"s_work_han_thu_86_248","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　服虔曰：「蠻夷，終王乃入助祭，各以其珍貢以共大禘之祭也。」師古曰：「每一王終，新王即位，乃來助祭。」","sentenceOrder":248},
  {"id":"s_work_han_thu_86_249","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　如淳曰：「游亦流也。」","sentenceOrder":249},
  {"id":"s_work_han_thu_86_250","chapterId":"ch_work_han_thu_86","textTraditional":"〔五〕　晉灼曰：「以情推子，以子況祖，得人心，禮何所違，故無毀棄不禘之主也。謂下三廟廢而為虛者也。」","sentenceOrder":250},
  {"id":"s_work_han_thu_86_251","chapterId":"ch_work_han_thu_86","textTraditional":"〔六〕　師古曰：「虛讀曰墟。」","sentenceOrder":251},
  {"id":"s_work_han_thu_86_252","chapterId":"ch_work_han_thu_86","textTraditional":"至平帝元始中，大司馬王莽奏：「本始元年丞相義等議，〔一〕諡孝宣皇帝親曰悼園，置邑三百家，至元康元年，丞相相等奏，〔二〕父為士，子為天子，祭以天子，悼園宜稱尊號曰『皇考』，立廟，益故奉園民滿千六百家，以為縣。臣愚以為皇考廟本不當立，累世奉之，非是。又孝文太后南陵、〔三〕孝昭太后雲陵園，雖前以禮不復修，陵名未正。謹與大司徒晏等百四十七人議，皆曰孝宣皇帝以兄孫繼統為孝昭皇帝後，以數，故孝元世以孝景皇帝及皇考廟親未盡，不毀。此兩統貳父，違於禮制。案義奏親諡曰『悼』，裁置奉邑，皆應經義。相奏悼園稱『皇考』，立廟，益民為縣，違離祖統，乖繆本義。父為士，子為天子，祭以天子者，乃謂若虞舜、夏禹、殷湯、周文、漢之高祖受命而王者也，非謂繼祖統為後者也。臣請皇高祖考廟奉明園毀勿修，〔四〕罷南陵、雲陵為縣。」奏可。","sentenceOrder":252},
  {"id":"s_work_han_thu_86_253","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「蔡義也。」","sentenceOrder":253},
  {"id":"s_work_han_thu_86_254","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「魏相也。」","sentenceOrder":254},
  {"id":"s_work_han_thu_86_255","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「在霸陵之南，故曰南陵。」","sentenceOrder":255},
  {"id":"s_work_han_thu_86_256","chapterId":"ch_work_han_thu_86","textTraditional":"〔四〕　張晏曰：「奉明園，悼皇考園也。」","sentenceOrder":256},
  {"id":"s_work_han_thu_86_257","chapterId":"ch_work_han_thu_86","textTraditional":"司徒掾班彪曰：〔一〕漢承亡秦絕學之後，祖宗之制因時施宜。自元、成後學者（番）〔蕃〕滋，〔二〕貢禹毀宗廟，匡衡改郊兆，何武定三公，後皆數復，故紛紛不定。〔三〕何者？禮文缺微，古今異制，各為一家，未易可偏定也。考觀諸儒之議，劉歆博而篤矣。","sentenceOrder":257},
  {"id":"s_work_han_thu_86_258","chapterId":"ch_work_han_thu_86","textTraditional":"〔一〕　師古曰：「漢書諸贊，皆固所為。其有叔皮先論述者，（謂）固亦具顯以示後人，而或者〔謂〕固竊盜父名，觀此可以免矣。」","sentenceOrder":258},
  {"id":"s_work_han_thu_86_259","chapterId":"ch_work_han_thu_86","textTraditional":"〔二〕　師古曰：「蕃音扶元反。」","sentenceOrder":259},
  {"id":"s_work_han_thu_86_260","chapterId":"ch_work_han_thu_86","textTraditional":"〔三〕　師古曰：「數音所角反。復音扶目反。」","sentenceOrder":260},
  {"id":"s_work_han_thu_86_261","chapterId":"ch_work_han_thu_86","textTraditional":"校勘記","sentenceOrder":261},
  {"id":"s_work_han_thu_86_262","chapterId":"ch_work_han_thu_86","textTraditional":"三一０四頁　八行　言欲正遠人，先從近〔親〕始。　景祐、殿本都有「親」字。","sentenceOrder":262},
  {"id":"s_work_han_thu_86_263","chapterId":"ch_work_han_thu_86","textTraditional":"三一０六頁一一行　孟所居彭城東里名（曰）〔也〕。　景祐、殿本都作「也」。王先謙說作「也」是。","sentenceOrder":263},
  {"id":"s_work_han_thu_86_264","chapterId":"ch_work_han_thu_86","textTraditional":"三一０七頁　二行　而者，句（端）〔絕〕之辭。　殿本作「絕」，景祐本作「端」。","sentenceOrder":264},
  {"id":"s_work_han_thu_86_265","chapterId":"ch_work_han_thu_86","textTraditional":"三一０八頁一四行　大鴻臚（奉）〔奏〕狀，　景祐、殿本都作「奏」。王先謙說作「奏」是。","sentenceOrder":265},
  {"id":"s_work_han_thu_86_266","chapterId":"ch_work_han_thu_86","textTraditional":"三一一二頁一三行　貳〔謂〕不一也，　景祐、殿本都有「謂」字。","sentenceOrder":266},
  {"id":"s_work_han_thu_86_267","chapterId":"ch_work_han_thu_86","textTraditional":"三一一四頁　六行　非（吾）〔我〕所度，　景祐、殿本都作「我」。","sentenceOrder":267},
  {"id":"s_work_han_thu_86_268","chapterId":"ch_work_han_thu_86","textTraditional":"三一一五頁　一行　言天（會）〔命〕無常，唯善是祐。　景祐、殿、局本都作「命」，此誤。","sentenceOrder":268},
  {"id":"s_work_han_thu_86_269","chapterId":"ch_work_han_thu_86","textTraditional":"三一一六頁　八行　便殿者，寢側之（便）〔別〕殿耳。　景祐、殿本都作「別」。","sentenceOrder":269},
  {"id":"s_work_han_thu_86_270","chapterId":"ch_work_han_thu_86","textTraditional":"三一一六頁一０行　十〔一〕月嘗，　景祐、殿本都有「一」字。","sentenceOrder":270},
  {"id":"s_work_han_thu_86_271","chapterId":"ch_work_han_thu_86","textTraditional":"三一一八頁　一行　此周頌雍篇（祖）〔禘〕太祖之詩也。　景祐、殿、局本都作「禘」。王先謙說作「禘」是。","sentenceOrder":271},
  {"id":"s_work_han_thu_86_272","chapterId":"ch_work_han_thu_86","textTraditional":"三一一九頁　七行　（一）〔壹〕，一祭之也。　殿本作「壹」。王先謙說殿本是。","sentenceOrder":272},
  {"id":"s_work_han_thu_86_273","chapterId":"ch_work_han_thu_86","textTraditional":"三一二一頁一三行　謹案上世帝王承祖禰之大（義）〔禮〕，　宋祁說越本作「禮」。錢大昭說閩本作「禮」。按景祐本作「禮」。","sentenceOrder":273},
  {"id":"s_work_han_thu_86_274","chapterId":"ch_work_han_thu_86","textTraditional":"三一二三頁一五行　明繼祖不（得）〔復〕顧其私祖母也。　景祐、殿本都作「復」。","sentenceOrder":274},
  {"id":"s_work_han_thu_86_275","chapterId":"ch_work_han_thu_86","textTraditional":"三一二四頁一０行　六藝，（之）〔六〕經也。　景祐本作「之」，殿本作「六」。王先謙說作「六」是。","sentenceOrder":275},
  {"id":"s_work_han_thu_86_276","chapterId":"ch_work_han_thu_86","textTraditional":"三一三０頁一三行　自元、成後學者（番）〔蕃〕滋，景祐、殿本都作「蕃」。王先謙說作「蕃」是。","sentenceOrder":276},
  {"id":"s_work_han_thu_86_277","chapterId":"ch_work_han_thu_86","textTraditional":"三一三一頁　二行　其有叔皮先論述者，（謂）固亦具顯以示後人，而或者〔謂〕固竊盜父名，觀此可以免矣。宋祁說，越本「謂」字在後「或者」下。劉攽說，「謂」字合在「或者」下。按景祐、局本都在「或者」下。","sentenceOrder":277},
  {"id":"s_work_han_thu_87_1","chapterId":"ch_work_han_thu_87","textTraditional":"魏相字弱翁，濟陰定陶人也，〔一〕徙平陵。少學易，為郡卒史，舉賢良，以對策高第，為茂陵令。頃之，御史大夫桑弘羊客詐稱御史止傳，〔二〕丞不以時謁，客怒縛丞。相疑其有姦，收捕，案致其罪，論棄客市，〔三〕茂陵大治。","sentenceOrder":1},
  {"id":"s_work_han_thu_87_2","chapterId":"ch_work_han_thu_87","textTraditional":"〔一〕　師古曰：「說者謂相即魏無知之後，蓋承淺近之書，為妄深矣。」","sentenceOrder":2},
  {"id":"s_work_han_thu_87_3","chapterId":"ch_work_han_thu_87","textTraditional":"〔二〕　師古曰：「傳謂縣之傳舍。」","sentenceOrder":3},
  {"id":"s_work_han_thu_87_4","chapterId":"ch_work_han_thu_87","textTraditional":"〔三〕　師古曰：「殺之於市。」","sentenceOrder":4},
  {"id":"s_work_han_thu_87_5","chapterId":"ch_work_han_thu_87","textTraditional":"後遷河南太守，禁止姦邪，豪彊畏服。會丞相車千秋死，先是千秋子為雒陽武庫令，自見失父，而相治郡嚴，恐久獲罪，乃自免去。相使掾追呼之，遂不肯還。相獨恨曰：「大將軍聞此令去官，必以為我用丞相死不能遇其子。使當世貴人非我，殆矣！」〔一〕武庫令西至長安，大將軍霍光果以責過相曰：「幼主新立，以為函谷京師之固，武庫精兵所聚，故以丞相弟為關都尉，子為武庫令。今河南太守不深惟國家大策，〔二〕苟見丞相不在而斥逐其子，何淺薄也！」後人有告相賊殺不辜，事下有司。河南卒戍中都官者二三千人，〔三〕遮大將軍，自言願復留作一年以贖太守罪。河南老弱萬餘人守關欲入上書，關吏以聞。大將軍用武庫令事，遂下相廷尉獄。〔四〕久繫踰冬，會赦出。復有詔守茂陵令，遷楊州刺史。考案郡國守相，多所貶退。相與丙吉相善，時吉為光祿大夫，與相書曰：「朝廷已深知弱翁（行治）〔治行〕，方且大用矣。願少慎事自重，臧器于身。」〔五〕相心善其言，為霽威嚴。〔六〕居部二歲，徵為諫大夫，復為河南太守。","sentenceOrder":5},
  {"id":"s_work_han_thu_87_6","chapterId":"ch_work_han_thu_87","textTraditional":"〔一〕　師古曰：「殆，危也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_87_7","chapterId":"ch_work_han_thu_87","textTraditional":"〔二〕　師古曰：「惟，思也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_87_8","chapterId":"ch_work_han_thu_87","textTraditional":"〔三〕　師古曰：「來京師諸官府為戍卒，若今衛士上番分守諸司。」","sentenceOrder":8},
  {"id":"s_work_han_thu_87_9","chapterId":"ch_work_han_thu_87","textTraditional":"〔四〕　師古曰：「光心以武庫令事嫌之，而下其賊殺不辜之獄也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_87_10","chapterId":"ch_work_han_thu_87","textTraditional":"〔五〕　師古曰：「易下繫辭云：『君子臧器於身，待時而動。』言不顯見其材能。」","sentenceOrder":10},
  {"id":"s_work_han_thu_87_11","chapterId":"ch_work_han_thu_87","textTraditional":"〔六〕　蘇林曰：「霽音限齊之齊。」臣瓚曰：「此雨霽字也。霽，止也。」師古曰：「二說皆是也。音才詣反，又音子詣反。」","sentenceOrder":11},
  {"id":"s_work_han_thu_87_12","chapterId":"ch_work_han_thu_87","textTraditional":"數年，宣帝即位，徵相入為大司農，遷御史大夫。四歲，大將軍霍光薨，上思其功德，以其子禹為右將軍，兄子樂平侯山復領尚書事。〔一〕相因平恩侯許伯奏封事，言：「春秋譏世卿，惡宋三世為大夫，〔二〕及魯季孫之專權，皆危亂國家。自後元以來，祿去王室，政繇冢宰。〔三〕今光死，子復為大將軍，兄子秉樞機，昆弟諸婿據權勢，在兵官。光夫人顯及諸女皆通籍長信宮，〔四〕或夜詔門出入，驕奢放縱，恐寖不制。〔五〕宜有以損奪其權，破散陰謀，以固萬世之基，全功臣之世。」又故事諸上書者皆為二封，署其一曰副，領尚書者先發副封，所言不善，屏去不奏。相復因許伯白，去副封以防雍蔽。〔六〕宣帝善之，詔相給事中，皆從其議。霍氏殺許后之謀始得上聞。乃罷其三侯，令就第，〔七〕親屬皆出補吏。於是韋賢以老病免，相遂代為丞相，封高平侯，食邑八百戶。及霍氏怨相，又憚之，謀矯太后詔，先召斬丞相，然後廢天子。事發覺，伏誅。宣帝始親萬機，厲精為治，練群臣，核名實，而相總領眾職，甚稱上意。","sentenceOrder":12},
  {"id":"s_work_han_thu_87_13","chapterId":"ch_work_han_thu_87","textTraditional":"〔一〕　師古曰：「山者，去病之孫。今言兄子，此傳誤。」","sentenceOrder":13},
  {"id":"s_work_han_thu_87_14","chapterId":"ch_work_han_thu_87","textTraditional":"〔二〕　師古曰：「解在五行志。」","sentenceOrder":14},
  {"id":"s_work_han_thu_87_15","chapterId":"ch_work_han_thu_87","textTraditional":"〔三〕　師古曰：「繇與由同。」","sentenceOrder":15},
  {"id":"s_work_han_thu_87_16","chapterId":"ch_work_han_thu_87","textTraditional":"〔四〕　師古曰：「通籍謂禁門之中皆有名籍，恣出入也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_87_17","chapterId":"ch_work_han_thu_87","textTraditional":"〔五〕　師古曰：「寖，漸也。不制，不可制御也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_87_18","chapterId":"ch_work_han_thu_87","textTraditional":"〔六〕　師古曰：「雍讀曰壅。」","sentenceOrder":18},
  {"id":"s_work_han_thu_87_19","chapterId":"ch_work_han_thu_87","textTraditional":"〔七〕　師古曰：「禹及雲、山也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_87_20","chapterId":"ch_work_han_thu_87","textTraditional":"元康中，匈奴遣兵擊漢屯田車師者，不能下。上與後將軍趙充國等議，欲因匈奴衰弱，出兵擊其右地，使不敢復擾西域。相上書諫曰：「臣聞之，救亂誅暴，謂之義兵，兵義者王；敵加於己，不得已而起者，謂之應兵，兵應者勝；爭恨小故，不忍憤怒者，謂之忿兵，兵忿者敗；利人土地貨寶者，謂之貪兵，兵貪者破；恃國家之大，矜民人之眾，欲見威於敵者，謂之驕兵，兵驕者滅：此五者，非但人事，乃天道也。間者匈奴嘗有善意，所得漢民輒奉歸之，未有犯於邊境，雖爭屯田車師，不足致意中。今聞諸將軍欲興兵入其地，臣愚不知此兵何名者也。今邊郡困乏，父子共犬羊之裘，食草萊之實，常恐不能自存，難於動兵。〔一〕『軍旅之後，必有凶年』，〔二〕言民以其愁苦之氣，傷陰陽之和也。出兵雖勝，猶有後憂，恐災害之變因此以生。今郡國守相多不實選，〔三〕風俗尤薄，水旱不時。案今年計，子弟殺父兄、妻殺夫者，凡二百二十二人，臣愚以為此非小變也。今左右不憂此，〔四〕乃欲發兵報纖介之忿於遠夷，殆孔子所謂『吾恐季孫之憂不在顓臾而在蕭牆之內』也。〔五〕願陛下與平昌侯、樂昌侯、平恩侯及有識者詳議乃可。」〔六〕上從（其）〔相〕言而止。","sentenceOrder":20},
  {"id":"s_work_han_thu_87_21","chapterId":"ch_work_han_thu_87","textTraditional":"〔一〕　師古曰：「不可以兵事動之。」","sentenceOrder":21},
  {"id":"s_work_han_thu_87_22","chapterId":"ch_work_han_thu_87","textTraditional":"〔二〕　師古曰：「此引老子道經之言。」","sentenceOrder":22},
  {"id":"s_work_han_thu_87_23","chapterId":"ch_work_han_thu_87","textTraditional":"〔三〕　師古曰：「言不得其人。」","sentenceOrder":23},
  {"id":"s_work_han_thu_87_24","chapterId":"ch_work_han_thu_87","textTraditional":"〔四〕　師古曰：「左右謂近臣在天子左右者。」","sentenceOrder":24},
  {"id":"s_work_han_thu_87_25","chapterId":"ch_work_han_thu_87","textTraditional":"〔五〕　師古曰：「論語季氏將伐顓臾，孔子謂冉有、季路曰：『吾恐季孫之憂不在顓臾而在蕭牆之內。』故相引之。顓臾，魯附庸國。蕭牆，屏牆也，解在五行志。」","sentenceOrder":25},
  {"id":"s_work_han_thu_87_26","chapterId":"ch_work_han_thu_87","textTraditional":"〔六〕　師古曰：「平昌侯王無故、樂昌侯王武，並帝之舅。平恩侯許伯，皇太子外祖父也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_87_27","chapterId":"ch_work_han_thu_87","textTraditional":"相明易經，有師法，好觀漢故事及便宜章奏，〔一〕以為古今異制，方今務在奉行故事而已。數條漢興已來國家便宜行事，及賢臣賈誼、晁錯、董仲舒等所言，奏請施行之，曰：「臣聞明主在上，賢輔在下，則君安虞而民和睦。〔二〕臣相幸得備位，不能奉明法，廣教化，理四方，以宣聖德。民多背本趨末，〔三〕或有飢寒之色，為陛下之憂，臣相罪當萬死。臣相知能淺薄，不明國家大體，時用之宜，惟民終始，未得所繇。〔四〕竊伏觀先帝聖德仁恩之厚，勤勞天下，垂意黎庶，憂水旱之災，為民貧窮發倉廩，賑乏餧；〔五〕遣諫大夫博士巡行天下，〔六〕察風俗，舉賢良，平冤獄，冠蓋交道；〔七〕省諸用，寬租賦，弛山澤波池，〔八〕禁秣馬酤酒貯積：〔九〕所以周急繼困，慰安元元，便利百姓之道甚備。臣相不能悉陳，昧死奏故事詔書凡二十三事。臣謹案王法必本於農而務積聚，量入制用以備凶災，〔一０〕亡六年之畜，尚謂之急。〔一一〕元鼎二年，平原、勃海、太山、東郡溥被災害，〔一二〕民餓死於道路。二千石不豫慮其難，使至於此，〔一三〕賴明詔振捄，乃得蒙更生。〔一四〕今歲不登，穀暴騰踴，〔一五〕臨秋收斂猶有乏者，至春恐甚，亡以相恤。西羌未平，師旅在外，兵革相乘，臣竊寒心，宜蚤圖其備。〔一六〕唯陛下留神元元，帥繇先帝盛德以撫海內。」〔一七〕上施行其策。","sentenceOrder":27},
  {"id":"s_work_han_thu_87_28","chapterId":"ch_work_han_thu_87","textTraditional":"〔一〕　師古曰：「既觀國家故事，又觀前人所奏便宜之章也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_87_29","chapterId":"ch_work_han_thu_87","textTraditional":"〔二〕　師古曰：「虞與娛同。」","sentenceOrder":29},
  {"id":"s_work_han_thu_87_30","chapterId":"ch_work_han_thu_87","textTraditional":"〔三〕　師古曰：「本，農業也。末，商賈也。趨讀曰趣。」","sentenceOrder":30},
  {"id":"s_work_han_thu_87_31","chapterId":"ch_work_han_thu_87","textTraditional":"〔四〕　師古曰：「惟，思也。繇讀與由同。由，從也，因也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_87_32","chapterId":"ch_work_han_thu_87","textTraditional":"〔五〕　師古曰：「餧，餓也，音乃賄反。」","sentenceOrder":32},
  {"id":"s_work_han_thu_87_33","chapterId":"ch_work_han_thu_87","textTraditional":"〔六〕　師古曰：「行音下更反。」","sentenceOrder":33},
  {"id":"s_work_han_thu_87_34","chapterId":"ch_work_han_thu_87","textTraditional":"〔七〕　師古曰：「言其往來不絕也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_87_35","chapterId":"ch_work_han_thu_87","textTraditional":"〔八〕　師古曰：「弛，放也，言不禁障之也。波音陂。」","sentenceOrder":35},
  {"id":"s_work_han_thu_87_36","chapterId":"ch_work_han_thu_87","textTraditional":"〔九〕　師古曰：「秣，以粟米飤馬也。酤酒者，糜費深也。貯積者，滯米粟也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_87_37","chapterId":"ch_work_han_thu_87","textTraditional":"〔一０〕師古曰：「謂視年歲之豐儉。」","sentenceOrder":37},
  {"id":"s_work_han_thu_87_38","chapterId":"ch_work_han_thu_87","textTraditional":"〔一一〕師古曰：「畜讀曰蓄。禮記王制云：『國無九年之蓄曰不足，無六年之蓄曰急，無三年之蓄曰國非其國也。』」","sentenceOrder":38},
  {"id":"s_work_han_thu_87_39","chapterId":"ch_work_han_thu_87","textTraditional":"〔一二〕師古曰：「溥與普同。」","sentenceOrder":39},
  {"id":"s_work_han_thu_87_40","chapterId":"ch_work_han_thu_87","textTraditional":"〔一三〕師古曰：「慮，思也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_87_41","chapterId":"ch_work_han_thu_87","textTraditional":"〔一四〕師古曰：「捄，古救字。」","sentenceOrder":41},
  {"id":"s_work_han_thu_87_42","chapterId":"ch_work_han_thu_87","textTraditional":"〔一五〕師古曰：「價忽大貴也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_87_43","chapterId":"ch_work_han_thu_87","textTraditional":"〔一六〕師古曰：「蚤，古早字也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_87_44","chapterId":"ch_work_han_thu_87","textTraditional":"〔一七〕師古曰：「帥，循也。繇與由同。由，從也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_87_45","chapterId":"ch_work_han_thu_87","textTraditional":"又數表采易陰陽及明堂月令奏之，〔一〕曰：「臣相幸得備員，奉職不修，不能宣廣教化。陰陽未和，災害未息，咎在臣等。臣聞易曰：『天地以順動，故日月不過，四時不忒；聖王以順動，故刑罰清而民服。』〔二〕天地變化，必繇陰陽，〔三〕陰陽之分，以日為紀。日冬夏至，則八風之序立，萬物之性成，各有常職，不得相干。東方之神太昊，乘震執規司春；〔四〕南方之神炎帝，乘離執衡司夏；〔五〕西方之神少昊，乘兌執矩司秋；〔六〕北方之神顓頊，乘坎執權司冬；〔七〕中央之神黃帝，乘坤艮執繩司下土。〔八〕茲五帝所司，各有時也。東方之卦不可以治西方，南方之卦不可以治北方。春興兌治則飢，秋興震治則華，冬興離治則泄，〔九〕夏興坎治則雹。明王謹於尊天，慎于養人，故立羲和之官以乘四時，〔一０〕節授民事。〔一一〕君動靜以道，奉順陰陽，則日月光明，風雨時節，寒暑調和。三者得敘，則災害不生，五穀熟，絲麻遂，〔一二〕屮木茂，鳥獸蕃，〔一三〕民不夭疾，衣食有餘。若是，則君尊民說，上下亡怨，〔一四〕政教不違，禮讓可興。夫風雨不時，則傷農桑；農桑傷，則民飢寒；飢寒在身，則亡廉恥，寇賊姦宄所繇生也。〔一五〕臣愚以為陰陽者，王事之本，群生之命，自古賢聖未有不繇者也。天子之義，必純取法天地，而觀於先聖。高皇帝所述書天子所服第八〔一六〕曰：『大謁者臣章受詔長樂宮，曰：「令群臣議天子所服，以安治天下。」相國臣何、御史大夫臣昌〔一七〕謹與將軍臣陵、太子太傅臣通等議：〔一八〕「春夏秋冬天子所服，當法天地之數，中得人和。故自天子王侯有土之君，下及兆民，能法天地，順四時，以治國家，身亡禍殃，年壽永究，〔一九〕是奉宗廟安天下之大禮也。臣請法之。中謁者趙堯舉春，〔二０〕李舜舉夏，兒湯舉秋，貢禹舉冬，〔二一〕四人各職一時。」大謁者襄章奏，制曰：「可。」』孝文皇帝時，以二月施恩惠於天下，賜孝弟力田及罷軍卒，祠死事者，頗非時節。〔二二〕御史大夫朝錯時為太子家令，奏言其狀。臣相伏念陛下恩澤甚厚，然而災氣未息，竊恐詔令有未合當時者也。願陛下選明經通知陰陽者四人，各主一時，時至明言所職，以和陰陽，天下幸甚！」相數陳便宜，上納用焉。","sentenceOrder":45},
  {"id":"s_work_han_thu_87_46","chapterId":"ch_work_han_thu_87","textTraditional":"〔一〕　師古曰：「表為標明之。采，撮取也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_87_47","chapterId":"ch_work_han_thu_87","textTraditional":"〔二〕　師古曰：「豫卦象辭也。忒，差也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_87_48","chapterId":"ch_work_han_thu_87","textTraditional":"〔三〕　師古曰：「繇與由同。」","sentenceOrder":48},
  {"id":"s_work_han_thu_87_49","chapterId":"ch_work_han_thu_87","textTraditional":"〔四〕　張晏曰：「木為仁，仁者生，生者圜，故為規。」","sentenceOrder":49},
  {"id":"s_work_han_thu_87_50","chapterId":"ch_work_han_thu_87","textTraditional":"〔五〕　張晏曰：「火為禮，禮者齊，齊者平，故為衡。」","sentenceOrder":50},
  {"id":"s_work_han_thu_87_51","chapterId":"ch_work_han_thu_87","textTraditional":"〔六〕　張晏曰：「金為義，義者成，成者方，故為矩。」","sentenceOrder":51},
  {"id":"s_work_han_thu_87_52","chapterId":"ch_work_han_thu_87","textTraditional":"〔七〕　張晏曰：「水為智，智者謀，謀者重，故為權。」","sentenceOrder":52},
  {"id":"s_work_han_thu_87_53","chapterId":"ch_work_han_thu_87","textTraditional":"〔八〕　張晏曰：「土為信，信者誠，誠者直，故為繩。」","sentenceOrder":53},
  {"id":"s_work_han_thu_87_54","chapterId":"ch_work_han_thu_87","textTraditional":"〔九〕　師古曰：「天地之氣不閉密也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_87_55","chapterId":"ch_work_han_thu_87","textTraditional":"〔一０〕師古曰：「乘，治也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_87_56","chapterId":"ch_work_han_thu_87","textTraditional":"〔一一〕師古曰：「各依其節而授以事。」","sentenceOrder":56},
  {"id":"s_work_han_thu_87_57","chapterId":"ch_work_han_thu_87","textTraditional":"〔一二〕師古曰：「遂，成也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_87_58","chapterId":"ch_work_han_thu_87","textTraditional":"〔一三〕師古曰：「屮，古草字。蕃，多也，音扶元反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_87_59","chapterId":"ch_work_han_thu_87","textTraditional":"〔一四〕師古曰：「說讀曰悅。」","sentenceOrder":59},
  {"id":"s_work_han_thu_87_60","chapterId":"ch_work_han_thu_87","textTraditional":"〔一五〕師古曰：「亂在外為姦，在內為宄。繇與由同。其下類此。」","sentenceOrder":60},
  {"id":"s_work_han_thu_87_61","chapterId":"ch_work_han_thu_87","textTraditional":"〔一六〕如淳曰：「第八，天子衣服之制也，於施行詔書第八。」","sentenceOrder":61},
  {"id":"s_work_han_thu_87_62","chapterId":"ch_work_han_thu_87","textTraditional":"〔一七〕師古曰：「蕭何、周昌也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_87_63","chapterId":"ch_work_han_thu_87","textTraditional":"〔一八〕師古曰：「陵，王陵。通，叔孫通。」","sentenceOrder":63},
  {"id":"s_work_han_thu_87_64","chapterId":"ch_work_han_thu_87","textTraditional":"〔一九〕師古曰：「究，竟也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_87_65","chapterId":"ch_work_han_thu_87","textTraditional":"〔二０〕應劭曰：「四時各舉所施行政事。」服虔曰：「主一時衣服禮物朝祭百事也。」師古曰：「服說是也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_87_66","chapterId":"ch_work_han_thu_87","textTraditional":"〔二一〕師古曰：「高帝時自有一貢禹也。兒音五奚反。」","sentenceOrder":66},
  {"id":"s_work_han_thu_87_67","chapterId":"ch_work_han_thu_87","textTraditional":"〔二二〕師古曰：「罷軍卒，卒之疲於軍事者也。罷音疲。一曰新從軍而休罷者也，音薄蟹反。」","sentenceOrder":67},
  {"id":"s_work_han_thu_87_68","chapterId":"ch_work_han_thu_87","textTraditional":"相敕掾史案事郡國及休告從家還至府，輒白四方異聞，或有逆賊風雨災變，郡不上，相輒奏言之。時丙吉為御史大夫，同心輔政，上皆重之。相為人嚴毅，不如吉寬。視事九歲，神爵三年薨，諡曰憲侯。子弘嗣，甘露中有罪削爵為關內侯。〔一〕","sentenceOrder":68},
  {"id":"s_work_han_thu_87_69","chapterId":"ch_work_han_thu_87","textTraditional":"〔一〕　師古曰：「弘坐騎至宗廟下，大不敬也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_87_70","chapterId":"ch_work_han_thu_87","textTraditional":"丙吉字少卿，魯國人也。治律令，為魯獄史。積功勞，稍遷至廷尉右監。坐法失官，歸為州從事。武帝末，巫蠱事起，吉以故廷尉監徵，〔一〕詔治巫蠱郡邸獄。時宣帝生數月，以皇曾孫坐衛太子事繫，吉見而憐之。又心知太子無事實，重哀曾孫無辜，〔二〕吉擇謹厚女徒，令保養曾孫，置閒燥處。〔三〕吉治巫蠱事，連歲不決。後元二年，武帝疾，往來長楊、五柞宮，〔四〕望氣者言長安獄中有天子氣，於是上遣使者分條中都官詔獄繫者，〔五〕亡輕重一切皆殺之。內謁者令郭穰夜到郡邸獄，吉閉門拒使者不納，曰：「皇曾孫在。他人亡辜死者猶不可，況親曾孫乎！」相守至天明不得入，穰還以聞，因劾奏吉。武帝亦寤，曰：「天使之也。」因赦天下。郡邸獄繫者獨賴吉得生，恩及四海矣。〔六〕曾孫病，幾不全者數焉，〔七〕吉數敕保養乳母加致醫藥，視遇甚有恩惠，以私財物給其衣食。","sentenceOrder":70},
  {"id":"s_work_han_thu_87_71","chapterId":"ch_work_han_thu_87","textTraditional":"〔一〕　師古曰：「被召詣京師。」","sentenceOrder":71},
  {"id":"s_work_han_thu_87_72","chapterId":"ch_work_han_thu_87","textTraditional":"〔二〕　師古曰：「重音直用反。」","sentenceOrder":72},
  {"id":"s_work_han_thu_87_73","chapterId":"ch_work_han_thu_87","textTraditional":"〔三〕　師古曰：「閒讀曰閑。閑，寬靜之處也。燥，高敞也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_87_74","chapterId":"ch_work_han_thu_87","textTraditional":"〔四〕　師古曰：「長楊、五柞宮並在盩厔，往來二宮之間。」","sentenceOrder":74},
  {"id":"s_work_han_thu_87_75","chapterId":"ch_work_han_thu_87","textTraditional":"〔五〕　師古曰：「條謂疏錄之。」","sentenceOrder":75},
  {"id":"s_work_han_thu_87_76","chapterId":"ch_work_han_thu_87","textTraditional":"〔六〕　師古曰：「吉拒閉使者，天子感寤，乃普赦天下。其郡邸繫獄者，既因吉得生，而赦宥之恩遂及四海也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_87_77","chapterId":"ch_work_han_thu_87","textTraditional":"〔七〕　師古曰：「幾音鉅依反。數音所角反。次下亦同。」","sentenceOrder":77},
  {"id":"s_work_han_thu_87_78","chapterId":"ch_work_han_thu_87","textTraditional":"後吉為車騎將軍軍市令，遷大將軍長史，霍光甚重之，入為光祿大夫給事中。昭帝崩，亡嗣，大將軍光遣吉迎昌邑王賀。賀即位，以行淫亂廢，光與車騎將軍張安世諸大臣議所立，未定。吉奏記光曰：「將軍事孝武皇帝，受襁褓之屬，任天下之寄，〔一〕孝昭皇帝早崩亡嗣，海內憂懼，欲亟聞嗣主，〔二〕發喪之日以大誼立後，〔三〕所立非其人，復以大誼廢之，〔四〕天下莫不服焉。方今社稷宗廟群生之命在將軍之壹舉。竊伏聽於眾庶，察其所言，諸侯宗室在（列位）〔位列〕者，未有所聞於民間也。而遺詔所養武帝曾孫名病已在掖庭外家者，〔五〕吉前使居郡邸時見其幼少，至今十八九矣，通經術，有美材，行安而節和。願將軍詳大議，參以蓍龜，豈宜褒顯，先使入侍，〔六〕令天下昭然知之，然後決定大策，天下幸甚！」光覽其議，〔七〕遂尊立皇曾孫，遣宗正劉德與吉迎曾孫於掖庭。宣帝初即位，賜吉爵關內侯。","sentenceOrder":78},
  {"id":"s_work_han_thu_87_79","chapterId":"ch_work_han_thu_87","textTraditional":"〔一〕　師古曰：「屬音之欲反。」","sentenceOrder":79},
  {"id":"s_work_han_thu_87_80","chapterId":"ch_work_han_thu_87","textTraditional":"〔二〕　師古曰：「亟，急也，音居力反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_87_81","chapterId":"ch_work_han_thu_87","textTraditional":"〔三〕　師古曰：「雖無嫡嗣，旁立支屬，令宗廟有奉，故云大誼。」","sentenceOrder":81},
  {"id":"s_work_han_thu_87_82","chapterId":"ch_work_han_thu_87","textTraditional":"〔四〕　師古曰：「恐危社稷，故廢黜之。」","sentenceOrder":82},
  {"id":"s_work_han_thu_87_83","chapterId":"ch_work_han_thu_87","textTraditional":"〔五〕　蘇林曰：「外家猶言外人民家，不在宮中。」晉灼曰：「出郡邸獄，歸在外家史氏，後入掖庭耳。」師古曰：「晉說是也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_87_84","chapterId":"ch_work_han_thu_87","textTraditional":"〔六〕　師古曰：「侍太后。」","sentenceOrder":84},
  {"id":"s_work_han_thu_87_85","chapterId":"ch_work_han_thu_87","textTraditional":"〔七〕　師古曰：「省納而用之。」","sentenceOrder":85},
  {"id":"s_work_han_thu_87_86","chapterId":"ch_work_han_thu_87","textTraditional":"吉為人深厚，不伐善。自曾孫遭遇，吉絕口不道前恩，〔一〕故朝廷莫能明其功也。地節三年，立皇太子，吉為太子太傅，數月，遷御史大夫。及霍氏誅，上躬親政，省尚書事。是時，掖庭宮婢則令民夫上書，自陳嘗有阿保之功。〔二〕章下掖庭令考問，則辭引使者丙吉知狀。掖庭令將則詣御史府以視吉。〔三〕吉識，謂則曰：「汝嘗坐養皇曾孫不謹督笞，汝安得有功？〔四〕獨渭城胡組、淮陽郭徵卿有恩耳。」分別奏組等共養勞苦狀。〔五〕詔吉求組、徵卿，已死，有子孫，皆受厚賞。詔免則為庶人，賜錢十萬。上親見問，然後知吉有舊恩，而終不言。上大賢之，制詔丞相：「朕微眇時，御史大夫吉與朕有舊恩，厥德茂焉。〔六〕詩不云虖？『亡德不報。』〔七〕其封吉為博陽侯，邑千三百戶。」臨當封，吉疾病，上將使人加紼而封之，及其生存也。〔八〕上憂吉疾不起，太子太傅夏侯勝曰：「此未死也。臣聞有陰德者，必饗其樂以及子孫。今吉未獲報而疾甚，非其死疾也。」後病果瘉。〔九〕吉上書固辭，自陳不宜以空名受賞。上報曰：「朕之封君，非空名也，而君上書歸侯印，是顯朕之不德也。方今天下少事，君其專精神，省思慮，近醫藥，以自持。」後五歲，代魏相為丞相。","sentenceOrder":86},
  {"id":"s_work_han_thu_87_87","chapterId":"ch_work_han_thu_87","textTraditional":"〔一〕　師古曰：「遭遇謂升大位也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_87_88","chapterId":"ch_work_han_thu_87","textTraditional":"〔二〕　師古曰：「謂未為宮婢時，有舊夫見在俗間者。」","sentenceOrder":88},
  {"id":"s_work_han_thu_87_89","chapterId":"ch_work_han_thu_87","textTraditional":"〔三〕　師古曰：「視讀曰示。」","sentenceOrder":89},
  {"id":"s_work_han_thu_87_90","chapterId":"ch_work_han_thu_87","textTraditional":"〔四〕　師古曰：「督謂視察之。」","sentenceOrder":90},
  {"id":"s_work_han_thu_87_91","chapterId":"ch_work_han_thu_87","textTraditional":"〔五〕　師古曰：「共音居用反。養音弋亮反。」","sentenceOrder":91},
  {"id":"s_work_han_thu_87_92","chapterId":"ch_work_han_thu_87","textTraditional":"〔六〕　師古曰：「茂，美也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_87_93","chapterId":"ch_work_han_thu_87","textTraditional":"〔七〕　師古曰：「大雅抑之詩。」","sentenceOrder":93},
  {"id":"s_work_han_thu_87_94","chapterId":"ch_work_han_thu_87","textTraditional":"〔八〕　應劭曰：「吉時病不能起，欲如君視疾，（如）〔加〕朝服拖紳，就封之也。」師古曰：「紼，繫印之組也，音弗也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_87_95","chapterId":"ch_work_han_thu_87","textTraditional":"〔九〕　師古曰：「瘉與愈同。」","sentenceOrder":95},
  {"id":"s_work_han_thu_87_96","chapterId":"ch_work_han_thu_87","textTraditional":"吉本起獄法小吏，後學詩、禮，皆通大義。及居相位，上寬大，好禮讓。掾史有罪臧，不稱職，輒予長休告，〔一〕終無所案驗。客或謂吉曰：「君侯為漢相，姦吏成其私，然無所懲艾。」〔二〕吉曰：「夫以三公之府有案吏之名，吾竊陋焉。」後人代吉，因以為故事，公府不案吏，自吉始。","sentenceOrder":96},
  {"id":"s_work_han_thu_87_97","chapterId":"ch_work_han_thu_87","textTraditional":"〔一〕　師古曰：「長給休假，令其去職也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_87_98","chapterId":"ch_work_han_thu_87","textTraditional":"〔二〕　師古曰：「艾讀曰乂。」","sentenceOrder":98},
  {"id":"s_work_han_thu_87_99","chapterId":"ch_work_han_thu_87","textTraditional":"於官屬掾史，務掩過揚善。吉馭吏耆酒，數逋蕩，〔一〕嘗從吉出，醉歐丞相車上。〔二〕西曹主吏白欲斥之，〔三〕吉曰：「以醉飽之失去士，使此人將復何所容？〔四〕西曹地忍之，〔五〕此不過汙丞相車茵耳。」〔六〕遂不去也。此馭吏邊郡人，習知邊塞發奔命警備事，〔七〕嘗出，適見驛騎持赤白囊，邊郡發奔命書馳來至。馭吏因隨驛騎至公車刺取，〔八〕知虜入雲中、代郡，遽歸府見吉白狀，〔九〕因曰：「恐虜所入邊郡，二千石長吏有老病不任兵馬者，宜可豫視。」吉善其言，召東曹案邊長吏，瑣科條其人。〔一０〕未已，詔召丞相、御史，問以虜所入郡吏，吉具對。御史大夫卒遽不能詳知，〔一一〕以得譴讓。〔一二〕而吉見謂憂邊思職，馭吏力也。吉乃歎曰：「士亡不可容，能各有所長。嚮使丞相不先聞馭吏言，何見勞勉之有？」掾史繇是益賢吉。〔一三〕","sentenceOrder":99},
  {"id":"s_work_han_thu_87_100","chapterId":"ch_work_han_thu_87","textTraditional":"〔一〕　師古曰：「逋，亡也。蕩，放也。謂亡其所供之職而游放也。耆讀曰嗜。」","sentenceOrder":100},
  {"id":"s_work_han_thu_87_101","chapterId":"ch_work_han_thu_87","textTraditional":"〔二〕　師古曰：「歐，吐也，音一口反。」","sentenceOrder":101},
  {"id":"s_work_han_thu_87_102","chapterId":"ch_work_han_thu_87","textTraditional":"〔三〕　師古曰：「斥，棄逐。」","sentenceOrder":102},
  {"id":"s_work_han_thu_87_103","chapterId":"ch_work_han_thu_87","textTraditional":"〔四〕　師古曰：「言無所容身也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_87_104","chapterId":"ch_work_han_thu_87","textTraditional":"〔五〕　李奇曰：「地猶第也。」師古曰：「地亦但也，語聲之急也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_87_105","chapterId":"ch_work_han_thu_87","textTraditional":"〔六〕　師古曰：「茵，蓐也，音因。」","sentenceOrder":105},
  {"id":"s_work_han_thu_87_106","chapterId":"ch_work_han_thu_87","textTraditional":"〔七〕　師古曰：「犇，古奔字也。有命則奔赴之，言應速也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_87_107","chapterId":"ch_work_han_thu_87","textTraditional":"〔八〕　師古曰：「刺謂探候之也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_87_108","chapterId":"ch_work_han_thu_87","textTraditional":"〔九〕　師古曰：「遽，速也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_87_109","chapterId":"ch_work_han_thu_87","textTraditional":"〔一０〕張晏曰：「瑣，錄也。欲科條其人老少及所經歷，知其本以文武進也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_87_110","chapterId":"ch_work_han_thu_87","textTraditional":"〔一一〕師古曰：「卒讀曰猝。」","sentenceOrder":110},
  {"id":"s_work_han_thu_87_111","chapterId":"ch_work_han_thu_87","textTraditional":"〔一二〕師古曰：「讓，責也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_87_112","chapterId":"ch_work_han_thu_87","textTraditional":"〔一三〕師古曰：「繇與由同。」","sentenceOrder":112},
  {"id":"s_work_han_thu_87_113","chapterId":"ch_work_han_thu_87","textTraditional":"吉又嘗出，逢清道群鬥者，死傷橫道，〔一〕吉過之不問，掾史獨怪之。吉前行，逢人逐牛，牛喘吐舌。〔二〕吉止駐，使騎吏問：「逐牛行幾里矣？」掾史獨謂丞相前後失問，或以譏吉，吉曰：「民鬥相殺傷，長安令、京兆尹職所當禁備逐捕，歲竟丞相課其殿最，奏行賞罰而已。宰相不親小事，非所當於道路問也。方春少陽用事，未可大熱，〔三〕恐牛近行用暑故喘，此時氣失節，恐有所傷害也。三公典調和陰陽，職（所）當憂，是以問之。」掾史乃服，以吉知大體。","sentenceOrder":113},
  {"id":"s_work_han_thu_87_114","chapterId":"ch_work_han_thu_87","textTraditional":"〔一〕　李奇曰：「清道時反群鬥也。」師古曰：「清道，謂天子當出，或有齋祠，先令道路清淨。」","sentenceOrder":114},
  {"id":"s_work_han_thu_87_115","chapterId":"ch_work_han_thu_87","textTraditional":"〔二〕　師古曰：「喘，急息，音昌兗反。」","sentenceOrder":115},
  {"id":"s_work_han_thu_87_116","chapterId":"ch_work_han_thu_87","textTraditional":"〔三〕　師古曰：「少音式邵反。」","sentenceOrder":116},
  {"id":"s_work_han_thu_87_117","chapterId":"ch_work_han_thu_87","textTraditional":"五鳳三年春，吉病篤。上自臨問吉，曰：「君即有不諱，誰可以自代者？」〔一〕吉辭謝曰：「群臣行能，明主所知，愚臣無所能識。」上固問，吉頓首曰：「西河太守杜延年明於法度，曉國家故事，前為九卿十餘年，今在郡治有能名。廷尉于定國執憲詳平，天下自以不冤。太僕陳萬年事後母孝，惇厚備於行止。此三人能皆在臣右，唯上察之。」上以吉言皆是而許焉。及吉薨，御史大夫黃霸為丞相，徵西河太守杜延年為御史大夫，會其年老，乞骸骨，病免。以廷尉于定國代為御史大夫。黃霸薨，而定國為丞相，太僕陳萬年代定國為御史大夫，居位皆稱職，上稱吉為知人。","sentenceOrder":117},
  {"id":"s_work_han_thu_87_118","chapterId":"ch_work_han_thu_87","textTraditional":"〔一〕　師古曰：「不諱，言死不可復言也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_87_119","chapterId":"ch_work_han_thu_87","textTraditional":"吉薨，諡曰定侯。子顯嗣，甘露中有罪削爵為關內侯，官至衛尉太僕。始顯少為諸曹，嘗從祠高廟，至夕牲日，乃使出取齋衣。〔一〕丞相吉大怒，謂其夫人曰：「宗廟至重，而顯不敬慎，亡吾爵者必顯也。」夫人為言，然後乃已。〔二〕吉中子禹為水衡都尉。少子高為中壘校尉。","sentenceOrder":119},
  {"id":"s_work_han_thu_87_120","chapterId":"ch_work_han_thu_87","textTraditional":"〔一〕　師古曰：「未祭一日，其夕展視牲具，謂之夕牲。」","sentenceOrder":120},
  {"id":"s_work_han_thu_87_121","chapterId":"ch_work_han_thu_87","textTraditional":"〔二〕　師古曰：「免其罪罰也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_87_122","chapterId":"ch_work_han_thu_87","textTraditional":"元帝時，長安士伍尊上書，〔一〕言「臣少時為郡邸小吏，竊見孝宣皇帝以皇曾孫在郡邸獄。是時治獄使者丙吉見皇曾孫遭離無辜，吉仁心感動，涕泣悽惻，選擇復作胡組養視皇孫，吉常從。臣尊日再侍臥庭上。〔二〕後遭條獄之詔，吉扞拒大難，不避嚴刑峻法。既遭大赦，吉謂守丞誰如，皇孫不當在官，〔三〕使誰如移書京兆尹，遣與胡組俱送京兆尹，不受，復還。及組日滿當去，皇孫思慕，吉以私錢顧組，令留與郭徵卿並養數月，乃遣組去。後少內嗇夫白吉曰：『食皇孫亡詔令。』〔四〕時吉得食米肉，月月以給皇孫。吉即時病，〔五〕輒使臣尊朝夕請問皇孫，視省席蓐燥濕。候伺組、徵卿，不得令晨夜去皇孫敖盪，〔六〕數奏甘毳食物。〔七〕所以擁全神靈，成育聖躬，功德已亡量矣。時豈豫知天下之福，而徼其報哉！〔八〕誠其仁恩內結於心也。雖介之推割肌以存君，不足（比也）〔以比〕。〔九〕孝宣皇帝時，臣上書言狀，幸得下吉，吉謙讓不敢自伐，刪去臣辭，〔一０〕專歸美於組、徵卿。組、徵卿皆以受田宅賜錢，吉封為博陽侯。臣尊不得比組、徵卿。臣年老居貧，死在旦暮，欲終不言，恐使有功不著。吉子顯坐微文奪爵為關內侯，臣愚以為宜復其爵邑，〔一一〕以報先人功德。」先是顯為太僕十餘年，與官屬大為姦利，臧千餘萬，司隸校尉昌案劾，罪至不道，奏請逮捕。上曰：「故丞相吉有舊恩，朕不忍絕。」免顯官，奪邑四百戶。後復以為城門校尉。顯卒，子昌嗣爵關內侯。","sentenceOrder":122},
  {"id":"s_work_han_thu_87_123","chapterId":"ch_work_han_thu_87","textTraditional":"〔一〕　師古曰：「先嘗有爵，經奪免之，而與士卒為伍，故稱士伍。其人名尊。」","sentenceOrder":123},
  {"id":"s_work_han_thu_87_124","chapterId":"ch_work_han_thu_87","textTraditional":"〔二〕　師古曰：「郡邸之庭也。侍謂參省之也。時皇孫孩弱，常在襁褓，故指言臥也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_87_125","chapterId":"ch_work_han_thu_87","textTraditional":"〔三〕　孟康曰：「郡守丞也，來詣京師邸治獄，姓誰名如。言皇孫不當在獄官，宜屬郡縣也。」文穎曰：「不當在郡邸官也。」師古曰：「守丞者，守獄官之丞耳，非郡丞也。誰如者，其人名，不作譙字，言姓，又非也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_87_126","chapterId":"ch_work_han_thu_87","textTraditional":"〔四〕　師古曰：「少內，掖庭主府臧之官也。食讀曰飤。詔令無文，無從得其廩具也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_87_127","chapterId":"ch_work_han_thu_87","textTraditional":"〔五〕　師古曰：「有病時也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_87_128","chapterId":"ch_work_han_thu_87","textTraditional":"〔六〕　師古曰：「去，離也。敖，游戲也。盪，放也。盪讀與蕩同。」","sentenceOrder":128},
  {"id":"s_work_han_thu_87_129","chapterId":"ch_work_han_thu_87","textTraditional":"〔七〕　師古曰：「奏，進也。毳讀與脆同。」","sentenceOrder":129},
  {"id":"s_work_han_thu_87_130","chapterId":"ch_work_han_thu_87","textTraditional":"〔八〕　師古曰：「繳，要也，音工堯反。」","sentenceOrder":130},
  {"id":"s_work_han_thu_87_131","chapterId":"ch_work_han_thu_87","textTraditional":"〔九〕　師古曰：「韓詩外傳云：『晉公子重耳之亡也，過曹，里鳧須以從，因盜其資而逃。重耳無糧，餧不能行，介子推割其股肉以食重耳，然後能行也。』」","sentenceOrder":131},
  {"id":"s_work_han_thu_87_132","chapterId":"ch_work_han_thu_87","textTraditional":"〔一０〕師古曰：「刪，削也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_87_133","chapterId":"ch_work_han_thu_87","textTraditional":"〔一一〕師古曰：「復音防目反。」","sentenceOrder":133},
  {"id":"s_work_han_thu_87_134","chapterId":"ch_work_han_thu_87","textTraditional":"成帝時，修廢功，以吉舊恩尤重，鴻嘉元年制詔丞相御史：「蓋聞褒功德，繼絕統，所以重宗廟，廣賢聖之路也。故博陽侯吉以舊恩有功而封，今其祀絕，朕甚憐之。夫善善及子孫，古今之通誼也，其封吉孫中郎將關內侯昌為博陽侯，奉吉後。」國絕三十二歲復續云。昌傳子至孫，王莽時乃絕。","sentenceOrder":134},
  {"id":"s_work_han_thu_87_135","chapterId":"ch_work_han_thu_87","textTraditional":"贊曰：古之制名，必繇象類，〔一〕遠取諸物，近取諸身。故經謂君為元首，臣為股肱，〔二〕明其一體，相待而成也。是故君臣相配，古今常道，自然之勢也。近觀漢相，高祖開基，蕭、曹為冠〔三〕，孝宣中興，丙、魏有聲。是時黜陟有序，眾職修理，公卿多稱其位，〔四〕海內興於禮讓。覽其行事，豈虛虖哉！〔五〕","sentenceOrder":135},
  {"id":"s_work_han_thu_87_136","chapterId":"ch_work_han_thu_87","textTraditional":"〔一〕　師古曰：「繇與由同。」","sentenceOrder":136},
  {"id":"s_work_han_thu_87_137","chapterId":"ch_work_han_thu_87","textTraditional":"〔二〕　師古曰：「謂虞書益稷云『元首明哉，股肱良哉』也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_87_138","chapterId":"ch_work_han_thu_87","textTraditional":"〔三〕　師古曰：「名位在眾臣之上。」","sentenceOrder":138},
  {"id":"s_work_han_thu_87_139","chapterId":"ch_work_han_thu_87","textTraditional":"〔四〕　師古曰：「稱，副也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_87_140","chapterId":"ch_work_han_thu_87","textTraditional":"〔五〕　師古曰：「言君明臣賢，所以致治，非徒然也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_87_141","chapterId":"ch_work_han_thu_87","textTraditional":"校勘記","sentenceOrder":141},
  {"id":"s_work_han_thu_87_142","chapterId":"ch_work_han_thu_87","textTraditional":"三一三四頁　五行　朝廷已深知弱翁（行治）〔治行〕，　景祐、殿本都作「治行」。王先謙說作「治行」是。","sentenceOrder":142},
  {"id":"s_work_han_thu_87_143","chapterId":"ch_work_han_thu_87","textTraditional":"三一三六頁一二行　上從（其）〔相〕言而止。　景祐、殿本都作「相」。","sentenceOrder":143},
  {"id":"s_work_han_thu_87_144","chapterId":"ch_work_han_thu_87","textTraditional":"三一四三頁一０行　諸侯宗室在（列位）〔位列〕者，　景祐、殿本都作「位列」。","sentenceOrder":144},
  {"id":"s_work_han_thu_87_145","chapterId":"ch_work_han_thu_87","textTraditional":"三一四五頁一０行　（如）〔加〕朝服拖紳，　景祐、殿本都作「加」。","sentenceOrder":145},
  {"id":"s_work_han_thu_87_146","chapterId":"ch_work_han_thu_87","textTraditional":"三一四七頁一一行　三公典調和陰陽，職（所）當憂，　景祐、殿本都無「所」字。","sentenceOrder":146},
  {"id":"s_work_han_thu_87_147","chapterId":"ch_work_han_thu_87","textTraditional":"三一四九頁　七行　雖介之推割肌以存君，不足（比也）〔以比〕。　景祐、殿本都作「以比」。","sentenceOrder":147},
  {"id":"s_work_han_thu_88_1","chapterId":"ch_work_han_thu_88","textTraditional":"眭弘字孟，魯國蕃人也。〔一〕少時好俠，鬥雞走馬，長乃變節，從嬴公受春秋。〔二〕以明經為議郎，至符節令。","sentenceOrder":1},
  {"id":"s_work_han_thu_88_2","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「眭音息隨反。今河朔尚有此姓，音字皆然。而韋昭、應劭並云音桂，非也。今有炅姓，乃音桂耳。漢之（決錄）〔炔欽〕又不作眭字，寧可混糅將為一族？又近代學者旁引炅氏譜以相附著。私譜之文出於閭巷，家自為說，事非經典，苟引先賢，妄相假託，無所取信，寧足據乎？蕃音皮。」","sentenceOrder":2},
  {"id":"s_work_han_thu_88_3","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「嬴，姓也。公，長老之號耳。」","sentenceOrder":3},
  {"id":"s_work_han_thu_88_4","chapterId":"ch_work_han_thu_88","textTraditional":"孝昭元鳳三年正月，泰山萊蕪山南匈匈有數千人聲，民視之，有大石自立，高丈五尺，大四十八圍，入地深八尺，三石為足。石立後有白烏數千下集其旁。是時昌邑有枯社木臥復生，〔一〕又上林苑中大柳樹斷枯臥地，亦自立生，有蟲食樹葉成文字，曰「公孫病已立」，孟推春秋之意，以為「石柳皆陰類，下民之象，（而）泰山者岱宗之嶽，王者易姓告代之處。今大石自立，僵柳復起，〔二〕非人力所為，此當有從匹夫為天子者。枯社木復生，故廢之家公孫氏當復興者也。」孟意亦不知其所在，即說曰：「先師董仲舒有言，雖有繼體守文之君，不害聖人之受命。漢家堯後，有傳國之運。漢帝宜誰差天下，求索賢人，〔三〕襢以帝位，〔四〕而退自封百里，如殷周二王後，以承順天命。」孟使友人內官長賜上此書。〔五〕時，昭帝幼，大將軍霍光秉政，惡之，下其書廷尉。奏賜、孟妄設祅言惑眾，大逆不道，皆伏誅。後五年，孝宣帝興於民間，即位，徵孟子為郎。","sentenceOrder":4},
  {"id":"s_work_han_thu_88_5","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「社木，社主之樹也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_88_6","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「僵，偃也，偃臥於地，音居羊反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_88_7","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「誰，問；差，擇也。問擇天下賢人。」","sentenceOrder":7},
  {"id":"s_work_han_thu_88_8","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　師古曰：「襢，古禪字也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_88_9","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　師古曰：「內官，署名。百官表云：『內官長丞，初屬少府，中屬主爵，後屬宗正。』賜者，其長之名。」","sentenceOrder":9},
  {"id":"s_work_han_thu_88_10","chapterId":"ch_work_han_thu_88","textTraditional":"夏侯始昌，魯人也。通五經，以齊詩、尚書教授。自董仲舒、韓嬰死後，武帝得始昌，甚重之。始昌明於陰陽，先言柏梁臺災日，至期日果災。時昌邑王以少子愛，上為選師，始昌為太傅。年老，以壽終。族子勝亦以儒顯名。","sentenceOrder":10},
  {"id":"s_work_han_thu_88_11","chapterId":"ch_work_han_thu_88","textTraditional":"夏侯勝字長公。初，魯共王分魯西寧鄉〔一〕以封子節侯，別屬大河，大河後更名東平，故勝為東平人。勝少孤，好學，從始昌受尚書及洪範五行傳，說災異。後事蕑卿，〔二〕又從歐陽氏問。為學精孰，所問非一師也。善說禮服。〔三〕徵為博士、光祿大夫。會昭帝崩，昌邑王嗣立，數出。〔四〕勝當乘輿前諫曰：「天久陰而不雨，臣下有謀上者，陛下出欲何之？」〔五〕王怒，謂勝為祅言，縛以屬吏。〔六〕吏白大將軍霍光，光不舉法。是時，光與車騎將軍張安世謀欲廢昌邑王。光讓安世以為泄語，安世實不言。乃召問勝，勝對言：「在洪範傳曰『皇之不極，厥罰常陰，時則下人有伐上者』，惡察察言，〔七〕故云臣下有謀。」光、安世大驚，以此益重經術士。後十餘日，光卒與安世（共）白太后，〔八〕廢昌邑王，尊立宣帝。光以為群臣奏事東宮，太后省政，〔九〕宜知經術，白令勝用尚書授太后。遷長信少府，賜爵關內侯，以與謀廢立，〔一０〕定策安宗廟，益千戶。","sentenceOrder":11},
  {"id":"s_work_han_thu_88_12","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「共讀如恭。恭王名餘，景帝之子也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_88_13","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「姓蕑名卿。蕑音姦。」","sentenceOrder":13},
  {"id":"s_work_han_thu_88_14","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「禮之喪服也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_88_15","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　師古曰：「每出游戲也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_88_16","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　師古曰：「之，往也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_88_17","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　師古曰：「屬，委也。音之欲反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_88_18","chapterId":"ch_work_han_thu_88","textTraditional":"〔七〕　師古曰：「惡謂忌諱也。察（謂）〔為〕計謀不敢明顯言之也。五行志曰『不敢察察言』也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_88_19","chapterId":"ch_work_han_thu_88","textTraditional":"〔八〕　師古曰：「卒，終也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_88_20","chapterId":"ch_work_han_thu_88","textTraditional":"〔九〕　師古曰：「省，視也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_88_21","chapterId":"ch_work_han_thu_88","textTraditional":"〔一０〕師古曰：「與讀曰豫。」","sentenceOrder":21},
  {"id":"s_work_han_thu_88_22","chapterId":"ch_work_han_thu_88","textTraditional":"宣帝初即位，欲褒先帝，詔丞相御史曰：「朕以眇身，蒙遺德，承聖業，奉宗廟，夙夜惟念。〔一〕孝武皇帝躬仁誼，厲威武，北征匈奴，單于遠遁，南平氐羌、昆明、甌駱兩越，〔二〕東定薉、貉、朝鮮，〔三〕廓地斥境，立郡縣，百蠻率服，款塞自至，珍貢陳於宗廟；協音律，造樂歌，薦上帝，封太山，立明堂，改正朔，易服色；明開聖緒，尊賢顯功，興滅繼絕，褒周之後；備天地之禮，廣道術之路。上天報況，〔四〕符瑞並應，寶鼎出，白麟獲，海效鉅魚，〔五〕神人並見，山稱萬歲。功德茂盛，不能盡宣，而廟樂未稱，〔六〕朕甚悼焉。其與列侯、二千石、博士議。」於是群臣大議廷中，皆曰：「宜如詔書。」長信少府勝獨曰：「武帝雖有攘四夷廣土斥境之功，然多殺士眾，竭民財力，奢泰亡度，天下虛耗，〔七〕百姓流離，物故者（過）半。〔八〕蝗蟲大起，赤地數千里，〔九〕或人民相食，畜積至今未復。〔一０〕亡德澤於民，不宜為立廟樂。」公卿共難勝曰：「此詔書也。」勝曰：「詔書不可用也。人臣之誼，宜直言正論，非苟阿意順指。議已出口，雖死不悔。」於是丞相義、御史大夫廣明〔二〕劾奏勝非議詔書，毀先帝，不道，及丞相長史黃霸阿縱勝，不舉劾，俱下獄。有司遂請尊孝武帝廟為世宗廟，奏盛德、文始、五行之舞，天下世世獻納，以明盛德。武帝巡狩所幸郡國凡四十九，皆立廟，如高祖、太宗焉。","sentenceOrder":22},
  {"id":"s_work_han_thu_88_23","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「惟，思也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_88_24","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「甌駱皆越號。」","sentenceOrder":24},
  {"id":"s_work_han_thu_88_25","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　張晏曰：「薉也，貉也，在遼東之東。」師古曰：「薉字與穢字同。貉音莫客反。」","sentenceOrder":25},
  {"id":"s_work_han_thu_88_26","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　師古曰：「況，賜也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_88_27","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　師古曰：「效，致也。鉅，大也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_88_28","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　師古曰：「稱，副也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_88_29","chapterId":"ch_work_han_thu_88","textTraditional":"〔七〕　師古曰：「耗，減也。音呼到反。」","sentenceOrder":29},
  {"id":"s_work_han_thu_88_30","chapterId":"ch_work_han_thu_88","textTraditional":"〔八〕　師古曰：「物故謂死也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_88_31","chapterId":"ch_work_han_thu_88","textTraditional":"〔九〕　師古曰：「言無五穀之苗。」","sentenceOrder":31},
  {"id":"s_work_han_thu_88_32","chapterId":"ch_work_han_thu_88","textTraditional":"〔一０〕師古曰：「畜讀曰蓄。」","sentenceOrder":32},
  {"id":"s_work_han_thu_88_33","chapterId":"ch_work_han_thu_88","textTraditional":"〔一一〕師古曰：「蔡義、田廣明。」","sentenceOrder":33},
  {"id":"s_work_han_thu_88_34","chapterId":"ch_work_han_thu_88","textTraditional":"勝、霸既久繫，霸欲從勝受經，勝辭以罪死。霸曰：「『朝聞道，夕死可矣』。」〔一〕勝賢其言，遂授之。繫再更冬，講論不怠。〔二〕","sentenceOrder":34},
  {"id":"s_work_han_thu_88_35","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「論語稱孔子曰『朝聞道，夕死可矣』，故霸引之。」","sentenceOrder":35},
  {"id":"s_work_han_thu_88_36","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「更，歷也，音工衡反。」","sentenceOrder":36},
  {"id":"s_work_han_thu_88_37","chapterId":"ch_work_han_thu_88","textTraditional":"至四年夏，關東四十九郡同日地動，或山崩，壞城郭室屋，殺六千餘人。上乃素服，避正殿，遣使者弔問吏民，賜死者棺錢。下詔曰：「蓋災異者，天地之戒也。朕承洪業，託士民之上，未能和群生。曩者地震北海、琅邪，壞祖宗廟，朕甚懼焉。其與列侯、中二千石博問術士，有以應變，補朕之闕，毋有所諱。」因大赦，勝出為諫大夫給事中，霸為揚州刺史。","sentenceOrder":37},
  {"id":"s_work_han_thu_88_38","chapterId":"ch_work_han_thu_88","textTraditional":"勝為人質樸守正，簡易亡威儀。見時謂上為君，〔一〕誤相字於前，〔二〕上亦以是親信之。〔三〕嘗見，出道上語，〔四〕上聞而讓勝，〔五〕勝曰：「陛下所言善，臣故揚之。堯言布於天下，至今見誦。臣以為可傳，故傳耳。」朝廷每有大議，上知勝素直，謂曰：「先生通正言，無懲前事。」〔六〕","sentenceOrder":38},
  {"id":"s_work_han_thu_88_39","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「見，見於天子。」","sentenceOrder":39},
  {"id":"s_work_han_thu_88_40","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「前，天子之前也。君前臣名不當相呼字也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_88_41","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「知其質樸也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_88_42","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　師古曰：「入見天子而以其言為外人道之。」","sentenceOrder":42},
  {"id":"s_work_han_thu_88_43","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　師古曰：「讓，責也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_88_44","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　師古曰：「通謂陳道之也。懲，創也。前事謂坐議廟樂事。」","sentenceOrder":44},
  {"id":"s_work_han_thu_88_45","chapterId":"ch_work_han_thu_88","textTraditional":"勝復為長信少府，遷太子太傅。受詔撰尚書、論語說，〔一〕賜黃金百斤。年九十卒官，賜冢塋，葬平陵。太后賜錢二百萬，為勝素服五日，以報師傅之恩，儒者以為榮。","sentenceOrder":45},
  {"id":"s_work_han_thu_88_46","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「解說其意，若今義疏也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_88_47","chapterId":"ch_work_han_thu_88","textTraditional":"始，勝每講授，常謂諸生曰：「士病不明經術；經術苟明，其取青紫如俛拾地芥耳。〔一〕學經不明，不如歸耕。」","sentenceOrder":47},
  {"id":"s_work_han_thu_88_48","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「地芥謂草芥之橫在地上者。俛而拾之，言其易而必得也。青紫，卿大夫之服也。俛即俯字也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_88_49","chapterId":"ch_work_han_thu_88","textTraditional":"勝從父子建字長卿，〔一〕自師事勝及歐陽高，左右采獲，〔二〕又從五經諸儒問與尚書相出入者，牽引以次章句，具文飾說。勝非之曰：「建所謂章句小儒，破碎大道。」建亦非勝為學疏略，難以應敵。建卒自顓門名經，〔三〕為議郎博士，至太子少傅。勝子兼為左曹太中大夫，孫堯至長信少府、司農、鴻臚，曾孫蕃郡守、州牧、長樂少府。勝同產弟子賞為梁內史，梁內史子定國為豫章太守。而建子千秋亦為少府、太子少傅。","sentenceOrder":49},
  {"id":"s_work_han_thu_88_50","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「從父昆弟之子，名建字長卿。」","sentenceOrder":50},
  {"id":"s_work_han_thu_88_51","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「言於勝及高兩處采問疑義而得（之）。」","sentenceOrder":51},
  {"id":"s_work_han_thu_88_52","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「顓與專同。專門者，自別為一家之學。」","sentenceOrder":52},
  {"id":"s_work_han_thu_88_53","chapterId":"ch_work_han_thu_88","textTraditional":"京房字君明，東郡頓丘人也。治易，事梁人焦延壽。延壽字贛。〔一〕贛貧賤，以好學得幸梁王，王共其資用，〔二〕令極意學。既成，為郡史，察舉補小黃令。以候司先知姦邪，盜賊不得發。〔三〕愛養吏民，化行縣中。舉最當遷，〔四〕三老官屬上書願留贛，有詔許增秩留，〔五〕卒於小黃。贛常曰：「得我道以亡身者，必京生也。」其說長於災變，分六十四卦，更直日用事，以風雨寒溫為候〔六〕：各有占驗。房用之尤精。好鍾律，知音聲。初元四年以孝廉為郎。","sentenceOrder":53},
  {"id":"s_work_han_thu_88_54","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「贛音貢。」","sentenceOrder":54},
  {"id":"s_work_han_thu_88_55","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「共讀曰恭。」","sentenceOrder":55},
  {"id":"s_work_han_thu_88_56","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「以其常先知姦邪，故欲為盜賊者，不敢起發。」","sentenceOrder":56},
  {"id":"s_work_han_thu_88_57","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　師古曰：「以課最而被舉，故欲遷為他官也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_88_58","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　師古曰：「依許留而增其秩。」","sentenceOrder":58},
  {"id":"s_work_han_thu_88_59","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　孟康曰：「分卦直日之法，一爻主一日，六十四卦為三百六十日。餘四卦，震、離、兌、坎，為方伯監司之官。所以用震、離、兌、坎者，是二至二分用事之日，又是四時各專王之氣。各卦主時，其占法各以日觀其善惡也。」師古曰：「更音工衡反。」","sentenceOrder":59},
  {"id":"s_work_han_thu_88_60","chapterId":"ch_work_han_thu_88","textTraditional":"永光、建昭間，西羌反，日蝕，又久青亡光，陰霧不精。〔一〕房數上疏，先言其將然，〔二〕近數月，遠一歲，所言屢中，天子說之。〔三〕數召見問，房對曰：「古帝王以功舉賢，則萬化成，瑞應著，〔四〕末世以毀譽取人，故功業廢而致災異。宜令百官各試其功，災異可息。」詔使房作其事，房奏考功課吏法。〔五〕上令公卿朝臣與房會議溫室，〔六〕皆以房言煩碎，令上下相司，不可許。上意鄉之。〔七〕時部刺史奏事京師，上召見諸刺史，令房曉以課事，刺史復以為不可行。唯御史大夫鄭弘、光祿大夫周堪初言不可，後善之。","sentenceOrder":60},
  {"id":"s_work_han_thu_88_61","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「精謂日光清明也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_88_62","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「言且欲有此事。」","sentenceOrder":62},
  {"id":"s_work_han_thu_88_63","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「說讀曰悅。」","sentenceOrder":63},
  {"id":"s_work_han_thu_88_64","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　師古曰：「萬化，萬機之事，施教化者也。一曰萬物之類也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_88_65","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　晉灼曰：「令丞尉治一縣，崇教化亡犯法者輒遷。有盜賊，滿三日不覺者則尉事也。令覺之，自除，二尉負其（二）〔罪〕。率相准如此法。」","sentenceOrder":65},
  {"id":"s_work_han_thu_88_66","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　師古曰：「溫室，殿名也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_88_67","chapterId":"ch_work_han_thu_88","textTraditional":"〔七〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":67},
  {"id":"s_work_han_thu_88_68","chapterId":"ch_work_han_thu_88","textTraditional":"是時中書令石顯顓權，〔一〕顯友人五鹿充宗為尚書令，與房同經，論議相非。二人用事，房嘗宴見，〔二〕問上曰：「幽厲之君何以危？所任者何人也？」上曰：「君不明，而所任者巧佞。」房曰：「知其巧佞而用之邪，將以為賢也？」上曰：「賢之。」房曰：「然則今何以知其不賢也？」上曰：「以其時亂而君危知之。」房曰：「若是，任賢必治，任不肖必亂，必然之道也。幽厲何不覺寤而更求賢，曷為卒任不肖以至於是？」〔三〕上曰：「臨亂之君各賢其臣，令皆覺寤，天下安得危亡之君？」房曰：「齊桓公、秦二世亦嘗聞此君而非笑之，然則任豎刁、趙高，政治日亂，盜賊滿山，何不以幽厲卜之而覺寤乎？」上曰：「唯有道者能以往知來耳。」房因免冠頓首，曰：「春秋紀二百四十二年災異，以視萬世之君。〔四〕今陛下即位已來，日月失明，星辰逆行，山崩泉涌，地震石隕，夏霜冬雷，〔五〕春凋秋榮，隕霜不殺，水旱螟蟲，民人飢疫，盜賊不禁，刑人滿市，春秋所記災異盡備。〔六〕陸下視今為治邪，亂邪？」上曰：「亦極亂耳。尚何道！」房曰：「今所任用者誰與？」〔七〕上曰：「然幸其瘉於彼，又以為不在此人也。」〔八〕房曰：「夫前世之君亦皆然矣。臣恐後之視今，猶今之視前也。」上良久乃曰：「今為亂者誰哉？」房曰：「明主宜自知之。」上曰：「不知也；如知（之），何故用之？」〔九〕房曰：「上最所信任，與圖事帷幄之中進退天下之士者是矣。」〔一０〕房指謂石顯，上亦知之，謂房曰：「已諭。」〔一一〕","sentenceOrder":68},
  {"id":"s_work_han_thu_88_69","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「顓與專同。」","sentenceOrder":69},
  {"id":"s_work_han_thu_88_70","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「以閒宴時而入見天子。」","sentenceOrder":70},
  {"id":"s_work_han_thu_88_71","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「卒，終也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_88_72","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　師古曰：「視讀曰示。」","sentenceOrder":72},
  {"id":"s_work_han_thu_88_73","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　師古曰：「靁，古雷字。」","sentenceOrder":73},
  {"id":"s_work_han_thu_88_74","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　師古曰：「言今皆備有之。」","sentenceOrder":74},
  {"id":"s_work_han_thu_88_75","chapterId":"ch_work_han_thu_88","textTraditional":"〔七〕　師古曰：「與讀曰歟。」","sentenceOrder":75},
  {"id":"s_work_han_thu_88_76","chapterId":"ch_work_han_thu_88","textTraditional":"〔八〕　師古曰：「瘉與愈同，愈猶勝也。言今之災異及政道猶幸勝於往日，又不由所任之人。」","sentenceOrder":76},
  {"id":"s_work_han_thu_88_77","chapterId":"ch_work_han_thu_88","textTraditional":"〔九〕　師古曰：「如，若也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_88_78","chapterId":"ch_work_han_thu_88","textTraditional":"〔一０〕師古曰：「圖，謀也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_88_79","chapterId":"ch_work_han_thu_88","textTraditional":"〔一一〕師古曰：「言已曉此意。」","sentenceOrder":79},
  {"id":"s_work_han_thu_88_80","chapterId":"ch_work_han_thu_88","textTraditional":"房罷出，後上令房上弟子曉知考功課吏事者，欲試用之。房上中郎任良、姚平，「願以為刺史，試考功法，臣得通籍殿中，為奏事，以防雍塞。」〔一〕石顯、五鹿充宗皆疾房，欲遠之，〔二〕建言宜試以房為郡守。〔三〕元帝於是以房為魏郡太守，秩八百石，居得以考功法治郡。房自請，願無屬刺史，得除用它郡人，自第吏千石已下，〔四〕歲竟乘傳奏事。〔五〕天子許焉。","sentenceOrder":80},
  {"id":"s_work_han_thu_88_81","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「雍讀曰壅。」","sentenceOrder":81},
  {"id":"s_work_han_thu_88_82","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「出之，令遠去。」","sentenceOrder":82},
  {"id":"s_work_han_thu_88_83","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「立議云然也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_88_84","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　如淳曰：「令長屬縣，自課第殿最。」","sentenceOrder":84},
  {"id":"s_work_han_thu_88_85","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　師古曰：「傳音張戀反。其下亦同。」","sentenceOrder":85},
  {"id":"s_work_han_thu_88_86","chapterId":"ch_work_han_thu_88","textTraditional":"房自知數以論議為大臣所非，內與石顯、五鹿充宗有隙，不欲遠離左右，及為太守，憂懼。房以建昭二年二月朔拜，上封事曰：「辛酉以來，蒙氣衰去，太陽精明，臣獨欣然，以為陛下有所定也。然少陰倍力而乘消息。〔一〕臣疑陛下雖行此道，猶不得如意，臣竊悼懼。守陽平侯鳳欲見未得，至己卯，臣拜為太守，此言上雖明下猶勝之效也。〔二〕臣出之後，恐必為用事所蔽，身死而功不成，故願歲盡乘傳奏事，蒙哀見許。乃辛巳，蒙氣復乘卦，太陽侵色，〔三〕此上大夫覆陽而上意疑也。〔四〕己卯、庚辰之間，必有欲隔絕臣令不得乘傳奏事者。」","sentenceOrder":86},
  {"id":"s_work_han_thu_88_87","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　孟康曰：「房以消息卦為辟。辟，君也。息卦曰太陰，消卦曰太陽，其餘卦曰少陰少陽，謂臣下也。并力雜卦氣干消息也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_88_88","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「言權臣蔽主之明，故己出為郡守也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_88_89","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　張晏曰：「晉卦、解卦也。太陽侵色，謂大壯。」","sentenceOrder":89},
  {"id":"s_work_han_thu_88_90","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　師古曰：「覆，掩蔽也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_88_91","chapterId":"ch_work_han_thu_88","textTraditional":"房未發，上令陽平侯鳳承制詔房，止無乘傳奏事。房意愈恐，去至新豐，因郵上封事〔一〕曰：「臣〔前〕以六月中言遯卦不效，法曰：『道人始去，寒，涌水為災。』〔二〕至其七月，涌水出。臣弟子姚平謂臣曰：『房可謂知道，未可謂信道也。房言災異，未嘗不中，今涌水已出，道人當逐死，尚復何言？』臣曰：『陛下至仁，於臣尤厚，雖言而死，臣猶言也。』〔三〕平又曰：『房可謂小忠，未可謂大忠也。昔秦時趙高用事，有正先者，非刺高而死，〔四〕高威自此成，故秦之亂，正先趣之。』〔五〕今臣得出守郡，自詭效功〔六〕，恐未效而死。惟陛下毋使臣塞涌水之異，〔七〕當正先之死，為姚平所笑。」","sentenceOrder":91},
  {"id":"s_work_han_thu_88_92","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「郵，行書者也，若今傳送文書矣。郵音尤。」","sentenceOrder":92},
  {"id":"s_work_han_thu_88_93","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「道人，有道術之人也。天氣寒而又有水涌出也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_88_94","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「自云不避死也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_88_95","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　孟康曰：「姓正名先，秦博士也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_88_96","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　師古曰：「趣讀曰促。」","sentenceOrder":96},
  {"id":"s_work_han_thu_88_97","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　師古曰：「詭，責也，〔自以為憂責也〕。」","sentenceOrder":97},
  {"id":"s_work_han_thu_88_98","chapterId":"ch_work_han_thu_88","textTraditional":"〔七〕　師古曰：「塞亦當也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_88_99","chapterId":"ch_work_han_thu_88","textTraditional":"房至陝，復上封事〔一〕曰：「乃丙戌小雨，丁亥蒙氣去，然少陰并力而乘消息，戊子益甚，到五十分，蒙氣復起。〔二〕此陛下欲正消息，雜卦之黨并力而爭，消息之氣不勝。彊弱安危之機不可不察。己丑夜，有還風，盡辛卯，〔三〕太陽復侵色，至癸巳，日月相薄，〔四〕此邪陰同力而太陽為之疑也。臣前白九年不改，必有星亡之異。〔五〕臣願出任良試考功，臣得居內，星亡之異可去。議者知如此於身不利，臣不可蔽，故云使弟子不若試師。臣為刺史又當奏事，故復云為刺史恐太守不與同心，不若以為太守，此其所以隔絕臣也。陛下不違其言而遂聽之，此乃蒙氣所以不解，太陽亡色者也。臣去朝稍遠，太陽侵色益甚，唯陛下毋難還臣而易逆天意。〔六〕邪說雖安于人，天氣必變，故人可欺，天不可欺也。願陛下察焉。」房去月餘，竟徵下獄。","sentenceOrder":99},
  {"id":"s_work_han_thu_88_100","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「陝，弘農之縣也，音式冉反。」","sentenceOrder":100},
  {"id":"s_work_han_thu_88_101","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　孟康曰：「分一日為八十分，分起夜半，是為戊子之日日在已西而蒙也。蒙常以晨夜，今向中而蒙起，是臣黨盛君不勝也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_88_102","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　孟康曰：「諸卦氣以寒溫不效後九十一日為還風。還風，暴風也。風為教令，言正令還也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_88_103","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　孟康曰：「京房傳曰：『雖非日月同宿之時，陰道盛，猶上薄日光如此，但日無光不食也。』」","sentenceOrder":103},
  {"id":"s_work_han_thu_88_104","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　張晏曰：「九，陽數之極也。」孟康曰：「晝食為既，夜食為盡，而星亡為星不見也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_88_105","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　師古曰：「易，輕也。音弋豉反。」","sentenceOrder":105},
  {"id":"s_work_han_thu_88_106","chapterId":"ch_work_han_thu_88","textTraditional":"初，淮陽憲王舅張博從房受學，以女妻房。房與相親，每朝見，輒為博道其語，〔一〕以為上意欲用房議，而群臣惡其害己，故為眾所排。博曰：「淮陽王上親弟，敏達好政，欲為國忠。〔二〕今欲令王上書求入朝，得佐助房。」房曰：「得無不可？」〔三〕博曰：「前楚王朝薦士，何為不可？」房曰：「中書令石顯、尚書令五鹿君相與合同，巧佞之人也，事縣官十餘年；及丞相韋侯，皆久亡補於民，可謂亡功矣。〔四〕此尤不欲行考功者也。淮陽王即朝見，勸上行考功，事善；不然，但言丞相、中書令任事久而不治，可休丞相，以御史大夫鄭弘代之，遷中書令置他官，以鉤盾令徐立代之，如此，房考功事得施行矣。」博具從房記諸所說災異事，（固）〔因〕令房為淮陽王作求朝奏草，皆持柬與淮陽王。石顯微司具知之，以房親近，未敢言。及房出守郡，顯告房與張博通謀，非謗政治，歸惡天子，詿誤諸侯王，語在憲王傳。初，房見道幽厲事，出為御史大夫鄭弘言之。房、博皆棄巿，弘坐免為庶人。房本姓李，推律自定為京氏，死時年四十一。","sentenceOrder":106},
  {"id":"s_work_han_thu_88_107","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「所與天子言，皆具說之。」","sentenceOrder":107},
  {"id":"s_work_han_thu_88_108","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「為音于偽反。」","sentenceOrder":108},
  {"id":"s_work_han_thu_88_109","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「恐不可也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_88_110","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　師古曰：「韋玄成也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_88_111","chapterId":"ch_work_han_thu_88","textTraditional":"翼奉字少君，東海下邳人也。治齊詩，與蕭望之、匡衡同師。三人經術皆明，衡為後進，望之施之政事，而奉惇學不仕，好律曆陰陽之占。元帝初即位，諸儒薦之，徵待詔宦者署，數言事宴見，天子敬焉。","sentenceOrder":111},
  {"id":"s_work_han_thu_88_112","chapterId":"ch_work_han_thu_88","textTraditional":"時，平昌侯王臨以宣（布）〔帝〕外屬侍中，稱詔欲從奉學其術。奉不肯與言，而上封事曰：「臣聞之於師，治道要務，在知下之邪正。人誠鄉正，雖愚為用；〔一〕若乃懷邪，知益為害。知下之術，在於六情十二律而已。北方之情，好也；好行貪狼，申子主之。〔二〕東方之情，怒也；怒行陰賊，亥卯主之。〔三〕貪狼必待陰而後動，陰賊必待貪狼而後用，二陰並行，是以王者忌子卯也。禮經避之，春秋諱焉。〔四〕南方之情，惡也；惡行廉貞，寅午主之。〔五〕西方之情，喜也；喜行寬大，巳酉主之。〔六〕二陽並行，是以王者吉午酉也。詩曰：『吉日庚午。』〔七〕上方之情，樂也；樂行姦邪，辰未主之。〔八〕下方之情，哀也；哀行公正，戌丑主之。（九）辰未屬陰，戌丑屬陽，萬物各以其類應。今陛下明聖虛靜以待物至，萬事雖眾，何聞而不諭，〔一０〕豈況乎執十二律而御六情！於以知下參實，亦甚優矣，萬不失一，自然之道也。乃正月癸未日加申，有暴風從西南來。未主姦邪，申主貪狼，風以大陰下抵建前，是人主左右邪臣之氣也。〔一一〕平昌侯比三來見臣，皆以正辰加邪時。辰為客，時為主人。以律知人情，王者之祕道也，〔一二〕愚臣誠不敢以語邪人。」","sentenceOrder":112},
  {"id":"s_work_han_thu_88_113","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":113},
  {"id":"s_work_han_thu_88_114","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　孟康曰：「北方水，水生於申，盛於子。水性觸地而行，觸物而潤，多所好故；多好則貪而無厭，故為貪狼也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_88_115","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　孟康曰：「東方木，木生於亥，盛於卯。木性受水氣而生，貫地而出，故為怒；以陰氣賊害土，故為陰賊也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_88_116","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　李奇曰：「北方陰也，卯又陰賊，故為二陰，王者忌之，不舉樂。春秋、禮記說皆同。賈氏說：『桀以乙卯亡，紂以甲子喪，惡以為戒。』」張晏曰：「子刑卯，卯刑子，相刑之日，故以為忌。而云夏以乙卯亡，殷以甲子亡，不推湯武以興，此說非也。」師古曰：「儒者以為子卯夏殷亡日，大失之矣。何儒亮以為學者雖駁云，只取夏殷亡日，不論殷周之興，以為大失，不博考其義。且天人之際，其理相符，有德者昌，無德者亡。以桀紂之暴虐，又遇惡日，其理必亡。以湯武之德，固先天而天不違，所謂德能消殃矣，豈殃能消德也！」","sentenceOrder":116},
  {"id":"s_work_han_thu_88_117","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　孟康曰：「南方火，火生於寅，盛於午。火性炎猛，無所（加）〔容〕受，故為惡；其氣精專嚴整，故為廉貞。」","sentenceOrder":117},
  {"id":"s_work_han_thu_88_118","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　孟康曰：「西方金，金生於巳，盛於酉。金之為物，喜以利刃加於萬物，故為喜；利刃所加，無不寬大，故曰寬大也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_88_119","chapterId":"ch_work_han_thu_88","textTraditional":"〔七〕　師古曰：「小雅吉日之詩也。其詩曰『吉日庚午，既差我馬』，言以庚午之吉日簡擇車馬以出田也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_88_120","chapterId":"ch_work_han_thu_88","textTraditional":"〔八〕　孟康曰：「上方謂北與東也。陽氣所萌生，故為上。辰，窮水也。未，窮木也。翼氏風角曰『木落歸本，水流歸末』，故木利在亥，水利在辰，盛衰各得其所，故樂也。水窮則無隙不入，木上出，窮則旁行，故為姦邪。」","sentenceOrder":120},
  {"id":"s_work_han_thu_88_121","chapterId":"ch_work_han_thu_88","textTraditional":"〔九〕　孟康曰：「下方謂南與西也。陰氣所萌生，故為下。戌，窮火也。丑，窮金也。翼氏風角曰『金剛火彊，各歸其鄉』，故火刑於午，金刑於酉。酉午，金火之盛也。盛時而受刑，至窮無所歸，故曰哀也。火性無所私，金性方剛，故曰公正。」","sentenceOrder":121},
  {"id":"s_work_han_thu_88_122","chapterId":"ch_work_han_thu_88","textTraditional":"〔一０〕師古曰：「諭謂曉解之。」","sentenceOrder":122},
  {"id":"s_work_han_thu_88_123","chapterId":"ch_work_han_thu_88","textTraditional":"〔一一〕張晏曰：「初元二年，歲在甲戌，正月二十二日癸未也，太陰在太歲後。」孟康曰：「時太陰在未，月建在寅，風從未下至寅南也。建為主氣，太陰臣氣也，加主氣，是人主左右邪臣驗也。」晉灼曰：「癸未日風，未辰也，時加申。張說是也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_88_124","chapterId":"ch_work_han_thu_88","textTraditional":"〔一二〕張晏曰：「平昌侯欲依上來學，為時邪也。風日加申，申知祕道也。」孟康曰：「謂乙丑之日也。丑為正日，加未而來為邪時。」晉灼曰：「奉以未為邪時，占知平昌侯為邪人，此當言皆以邪辰加邪時，字誤作正耳。下言大邪之見，辰時俱邪是也。翼氏曰『五行動為五音，四時散為十二律』也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_88_125","chapterId":"ch_work_han_thu_88","textTraditional":"上以奉為中郎，召問奉：「來者以善日邪時，孰與邪日善時？」奉對曰：「師法用辰不用日。〔一〕辰為客，時為主人。見於明主，侍者為主人。〔二〕辰正時邪，見者正，侍者邪；辰邪時正，見者邪，侍者正。忠正之見，侍者雖邪，辰時俱正；〔三〕大邪之見，侍者雖正，辰時俱邪。〔四〕即以自知侍者之邪，而時邪辰正，見者反邪；〔五〕即以自知侍者之正，而時正辰邪，見者反正。〔六〕辰為常事，時為一行。〔七〕辰疏而時精，其效同功，必參五觀之，然後可知。故曰：察其所繇，省其進退，〔八〕參之六合五行，則可以見人性，知人情。難用外察，從中甚明，故詩之為學，情性而已。五性不相害，六情更興廢。〔九〕觀性以曆，〔一０〕觀情以律，〔一一〕明主所宜獨用，難與二人共也。故曰：『顯諸仁，臧諸用。』〔一二〕露之則不神，獨行則自然矣，唯奉能用之，學者莫能行。」","sentenceOrder":125},
  {"id":"s_work_han_thu_88_126","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　孟康曰：「假令甲子日，子為辰，甲為日，用子不用甲也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_88_127","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　張晏曰：「禮，君燕見臣，則使臣為主人，故侍者為主人。」","sentenceOrder":127},
  {"id":"s_work_han_thu_88_128","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　孟康曰：「大正厭小邪也。凡辰時屬南與西為正，北與東為邪。」晉灼曰：「以上占推之，南方巳午、西方酉戌、東北寅丑為正，西南申未、北方亥子、東方辰卯為邪。」","sentenceOrder":128},
  {"id":"s_work_han_thu_88_129","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　孟康曰：「大邪厭小正也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_88_130","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　孟康曰：「凡占以見者為本。今自知侍者邪，而時復邪，則邪無所施，故屬見者。」晉灼曰：「上言忠正客見，侍者雖邪，辰時俱正，然則小邪屬主人矣。何以知之，見者以大正來反我小邪故也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_88_131","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　孟康曰：「已自知侍者正，而時復正，則正無所施。辰雖邪，而見者更正也。」晉灼曰：「上言大邪客見，侍者雖正，辰時俱邪，然則小正屬主人矣。以此法占之，即以自知主人之正，而時正辰邪矣。何以知之？見者以大邪來反我小正故也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_88_132","chapterId":"ch_work_han_thu_88","textTraditional":"〔七〕　孟康曰：「假令甲子日，則一日一夜為子。時，十二時也。日加之，行過也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_88_133","chapterId":"ch_work_han_thu_88","textTraditional":"〔八〕　師古曰：「繇與由同。」","sentenceOrder":133},
  {"id":"s_work_han_thu_88_134","chapterId":"ch_work_han_thu_88","textTraditional":"〔九〕　師古曰：「更音工衡反。」","sentenceOrder":134},
  {"id":"s_work_han_thu_88_135","chapterId":"ch_work_han_thu_88","textTraditional":"〔一０〕張晏曰：「性謂五行也。曆謂日也。」晉灼曰：「翼氏五性：肝性靜，靜行仁，甲己主之；心性躁，躁行禮，丙辛主之；脾性力，力行信，戊癸主之；肺性堅，堅行義，乙庚主之；腎性智，智行敬，丁壬主之也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_88_136","chapterId":"ch_work_han_thu_88","textTraditional":"〔一一〕張晏曰：「情謂六情，廉貞、寬大、公正、姦邪、陰賊、貪狼也。律，十二律也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_88_137","chapterId":"ch_work_han_thu_88","textTraditional":"〔一二〕師古曰：「易上繫之辭也。道周萬物，故曰顯諸仁；日用不知，故曰藏諸用也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_88_138","chapterId":"ch_work_han_thu_88","textTraditional":"是歲，關東大水，郡國十一飢，疫尤甚。上乃下詔江海陂湖園池屬少府者以假貧民，勿租稅；損大官膳，減樂府員，省苑（囿）〔馬〕，諸宮館稀御幸者勿繕治；太僕少府減食穀馬，水衡省食肉獸。明年二月戊午，地震。其夏，齊地人相食。七月己酉，地復震。上曰：「蓋聞賢聖在位，陰陽和，風雨時，日月光，星辰靜，黎庶康寧，考終厥命。今朕共承天地，託于公侯之上，明不能燭，德不能綏，災異並臻，連年不息。乃二月戊午，地大震于隴西郡，毀落太上廟殿壁木飾，壞敗〈豸原〉道縣〔一〕城郭官寺及民室屋，厭殺人眾，山崩地裂，水泉涌出。一年地再動，天惟降災，震驚朕躬。治有大虧，咎至於此。夙夜兢兢，不通大變，深懷鬱悼，未知其序。比年不登，元元困乏，不勝飢寒，以陷刑辟，朕甚閔焉。憯怛於心。〔二〕已詔吏虛倉廩，開府臧，振捄貧民。〔三〕群司其茂思天地之戒，〔四〕有可蠲除減省以便萬姓者，各條奏。悉意陳朕過失，靡有所諱。」〔五〕因赦天下，舉直言極諫之士。奉奏封事曰：","sentenceOrder":138},
  {"id":"s_work_han_thu_88_139","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「豲音（完）〔桓〕。」","sentenceOrder":139},
  {"id":"s_work_han_thu_88_140","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「憯音千感反。」","sentenceOrder":140},
  {"id":"s_work_han_thu_88_141","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「捄，古救字。」","sentenceOrder":141},
  {"id":"s_work_han_thu_88_142","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　師古曰：「茂，勉也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_88_143","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　師古曰：「悉，盡也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_88_144","chapterId":"ch_work_han_thu_88","textTraditional":"臣聞之於師曰，天地設位，懸日月，布星辰，分陰陽，定四時，列五行，以視聖人，名之曰道。〔一〕聖人見道，然後知王治之象，故畫州土，建君臣，立律曆，陳成敗，以視賢者，名之曰經。賢者見經，然後知人道之務，則詩、書、易、春秋、禮、樂是也。易有陰陽，詩有五際，〔二〕春秋有災異，皆列終始，推得失，考天心，以言王道之安危。至秦乃不說，傷之以法，〔三〕是以大道不通，至於滅亡。今陛下明聖，深懷要道，燭臨萬方，〔四〕布德流惠，靡有闕遺。罷省不急之用，振救困貧，賦醫藥，賜棺錢，〔五〕恩澤甚厚。又舉直言，求過失，盛德純備，天下幸甚。","sentenceOrder":144},
  {"id":"s_work_han_thu_88_145","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「視讀曰示。下亦類此。」","sentenceOrder":145},
  {"id":"s_work_han_thu_88_146","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　應劭曰：「君臣、父子、兄弟、夫婦、朋友也。」孟康曰：「詩內傳：『五際，卯、酉、午、戌、亥也。陰陽終始際會之歲，於此則有變改之政也。』」","sentenceOrder":146},
  {"id":"s_work_han_thu_88_147","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「說音悅。言不悅詩、書而以文法傷文學之人也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_88_148","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　師古曰：「燭，照也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_88_149","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　師古曰：「賦謂分給之。」","sentenceOrder":149},
  {"id":"s_work_han_thu_88_150","chapterId":"ch_work_han_thu_88","textTraditional":"臣奉竊學齊詩，聞五際之要十月之交篇，〔一〕知日蝕地震之效昭然可明，猶巢居知風，穴處知雨，〔二〕亦不足多，適所習耳。臣聞人氣內逆，則感動天地；天變見於星氣日蝕，地變見於奇物震動。所以然者，陽用其精，陰用其形，猶人之有五臧六體，五臧象天，六體象地。故臧病則氣色發於面，體病則欠申動於貌。今年太陰建於甲戌，律以庚寅初用事，曆以甲午從春。〔三〕曆中甲庚，律得參陽，性中仁義，情得公正貞廉，〔四〕百年之精歲也。正以精歲，本首王位，〔五〕日臨中時接律而地大震，其後連月久陰，雖有大令，猶不能復，〔六〕陰氣盛矣。古者朝廷必有同姓以明親親，必有異姓以明賢賢，此聖王之所以大通天下也。同姓親而易進，異姓疏而難通，故同姓一，異姓五，乃為平均。今左右亡同姓，獨以舅后之家為親，異姓之臣又疏。二后之黨滿朝，非特處位，勢尤奢僭過度，呂、霍、上官足以卜之，甚非愛人之道，又非後嗣之長策也。陰氣之盛，不亦宜乎！","sentenceOrder":150},
  {"id":"s_work_han_thu_88_151","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「小雅篇名也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_88_152","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「巢居，烏鵲之屬也。穴處，狐貍之類也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_88_153","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　孟康曰：「太陰在甲戌，則太歲在子。十一月庚寅日，黃鍾律初起用事也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_88_154","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　張晏曰：「甲庚皆三陽。甲在東方為仁，庚在西方為義。戌為公正，寅午為廉貞。」晉灼曰：「木數三。寅在東方，木位之始，故曰參陽也。」師古曰：「中音竹仲反。」","sentenceOrder":154},
  {"id":"s_work_han_thu_88_155","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　張晏曰：「春也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_88_156","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　師古曰：「大令謂虛倉廩，開府庫之屬也。復，補也，音扶目反。」","sentenceOrder":156},
  {"id":"s_work_han_thu_88_157","chapterId":"ch_work_han_thu_88","textTraditional":"臣又聞未央、建章、甘泉宮才人各以百數，皆不得天性〔一〕。若杜陵園，其已御見者，臣子不敢有言，雖然，太皇太后之事也。及諸侯王園，與其後宮，宜為設員，出其過制者，此損陰氣應天救邪之道也。今異至不應，災將隨之。其法大水，極陰生陽，反為大旱，甚則有火災，春秋宋伯姬是矣。〔二〕唯陛下財察。〔三〕","sentenceOrder":157},
  {"id":"s_work_han_thu_88_158","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「言絕男女之好也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_88_159","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「伯姬，魯成公女，宋恭公之夫人也。幽居守寡，既久而遇火災，極陰生陽也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_88_160","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「財與裁同。」","sentenceOrder":160},
  {"id":"s_work_han_thu_88_161","chapterId":"ch_work_han_thu_88","textTraditional":"明年夏四月乙未，孝武園白鶴館災。奉自以為中，上疏曰：「臣前上五際地震之效，曰極陰生陽，恐有火災。不合明聽，未見省答，臣竊內不自信。今白鶴館以四月乙未，時加於卯，月宿亢災，與前地震同法。臣奉乃深知道之可信也。不勝拳拳，願復賜間，卒其終始。」〔一〕","sentenceOrder":161},
  {"id":"s_work_han_thu_88_162","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「間，空隙也。卒，盡也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_88_163","chapterId":"ch_work_han_thu_88","textTraditional":"上復延問以得失。奉以為祭天地於雲陽汾陰，及諸寢廟不以親疏迭毀，皆煩費，違古制。又宮室苑囿，奢泰難供，以故民困國虛，亡累年之畜。所繇來久，〔一〕不改其本，難以末正，乃上疏曰：","sentenceOrder":163},
  {"id":"s_work_han_thu_88_164","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「畜讀曰蓄。繇與由同。」","sentenceOrder":164},
  {"id":"s_work_han_thu_88_165","chapterId":"ch_work_han_thu_88","textTraditional":"臣聞昔者盤庚改邑以興殷道，聖人美之。〔一〕竊聞漢德隆盛，在於孝文皇帝躬行節儉，外省繇役。其時未有甘泉、建章及上林中諸離宮館也。未央宮又無高門、武臺、麒麟、（凰）〔鳳〕皇、白虎、玉堂、金華之殿，獨有前殿、曲臺、漸臺、宣室、溫室、承明耳。孝文欲作一臺，度用百金，〔二〕重民之財，廢而不為，其積土基，至今猶存，〔三〕又下遺詔，不起山墳。故其時天下大和，百姓洽足，德流後嗣。","sentenceOrder":165},
  {"id":"s_work_han_thu_88_166","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「盤庚，殷王名也。將遷亳，殷眾庶咸怨，作盤庚三篇以告之，遂乃遷都，事見尚書也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_88_167","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「度，計也，音大各反。」","sentenceOrder":167},
  {"id":"s_work_han_thu_88_168","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「今在新豐縣南，驪山頂上也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_88_169","chapterId":"ch_work_han_thu_88","textTraditional":"如令處於當今，因此制度，必不能成功名。天道有常，王道亡常，亡常者所以應有常也。必有非常之主，然後能立非常之功。臣願陛下徙都於成周，左據成皋，（左）〔右〕阻黽池，前鄉崧高，後介大河，〔一〕建滎陽，扶河東，南北千里以為關，而入敖倉；地方百里者八九，足以自娛；東厭諸侯之權，西遠羌胡之難，〔二〕陛下共己亡為，〔三〕按成周之居，兼盤庚之德，萬歲之後，長為高宗。漢家郊兆寢廟祭祀之禮多不應古，臣奉誠難亶居而改作，〔四〕故願陛下遷都正本。眾制皆定，亡復繕治宮館不急之費，歲可餘一年之畜。〔五〕","sentenceOrder":169},
  {"id":"s_work_han_thu_88_170","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「鄉讀曰嚮。介，隔也，礙也。」","sentenceOrder":170},
  {"id":"s_work_han_thu_88_171","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「厭，抑也。音一葉反。遠音于萬反。」","sentenceOrder":171},
  {"id":"s_work_han_thu_88_172","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「共讀曰恭。」","sentenceOrder":172},
  {"id":"s_work_han_thu_88_173","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　如淳曰：「亶居猶虛居也，欲徙都乃可更制度也。」師古曰：「亶讀曰但。但居，謂依舊都也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_88_174","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　師古曰：「畜讀曰蓄。次下亦同。」","sentenceOrder":174},
  {"id":"s_work_han_thu_88_175","chapterId":"ch_work_han_thu_88","textTraditional":"臣聞三代之祖積德以王，然皆不過數百年而絕。周至成王，有上賢之材，因文武之業，以周召為輔，〔一〕有司各敬其事，在位莫非其人。〔二〕天下甫二世耳，〔三〕然周公猶作詩書深戒成王，以恐失天下。書則曰：「王毋若殷王紂。」〔四〕其詩則曰：「殷之未喪師，克配上帝；宜監于殷，駿命不易。」〔五〕今漢初取天下，起於豐沛，以兵征伐，德化未洽，後世奢侈，國家之費當數代之用，非直費財，又乃費士。孝武之世，暴骨四夷，不可勝數。有天下雖未久，至於陛下八世九主矣，〔六〕雖有成王之明，然亡周召之佐〔七〕。今東方連年飢饉，加之以疾疫，百姓菜色，或至相食。〔八〕地比震動，天氣溷濁，日光侵奪。〔九〕繇此言之，〔一０〕執國政者豈可以不懷怵惕而戒萬分之一乎！故臣願陛下因天變而徙都，所謂與天下更始者也。天道終而復始，窮則反本，故能延長而亡窮也。今漢道未終，陛下本而始之，於以永世延祚，不亦優乎！如因丙子之孟夏，順太陰以東行，〔一一〕到後七年之明歲，必有五年之餘蓄，然後大行考室之禮，〔一二〕雖周之隆盛，亡以加此。唯陛下留神，詳察萬世之策。","sentenceOrder":175},
  {"id":"s_work_han_thu_88_176","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「召讀曰邵。」","sentenceOrder":176},
  {"id":"s_work_han_thu_88_177","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「言所任皆得賢材也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_88_178","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「甫，始也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_88_179","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　師古曰：「周書亡逸篇也。其書曰周公曰：『烏虖！毋若殷王紂之迷亂，酗于酒德哉！』是也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_88_180","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　師古曰：「詩大雅文王之詩也。師，眾也。駿，大也。言殷家自帝乙以上，未喪天下之時，皆能配天而行。至紂荒怠，自取敗滅。今宜以殷王賢愚為鏡，知天之大命甚難也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_88_181","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　如淳曰：「呂后為主，不得為世，故八世九主矣。」","sentenceOrder":181},
  {"id":"s_work_han_thu_88_182","chapterId":"ch_work_han_thu_88","textTraditional":"〔七〕　師古曰：「召讀曰邵。」","sentenceOrder":182},
  {"id":"s_work_han_thu_88_183","chapterId":"ch_work_han_thu_88","textTraditional":"〔八〕　師古曰：「人專食菜，故肌膚青黃，為菜色也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_88_184","chapterId":"ch_work_han_thu_88","textTraditional":"〔九〕　師古曰：「比，頻也。溷，汙也，音下頓反。」","sentenceOrder":184},
  {"id":"s_work_han_thu_88_185","chapterId":"ch_work_han_thu_88","textTraditional":"〔一０〕師古曰：「繇與由同。」","sentenceOrder":185},
  {"id":"s_work_han_thu_88_186","chapterId":"ch_work_han_thu_88","textTraditional":"〔一一〕張晏曰：「如因今丙子之四月也。太陰是時在甲戌，當轉在乙亥、丙子，左旋之也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_88_187","chapterId":"ch_work_han_thu_88","textTraditional":"〔一二〕李奇曰：「凡宮新成，殺牲以釁祭，致其五祀之神，謂之考室。」師古曰：「考，成也，成其禮也。詩小雅斯干之詩序曰『斯干，宣王考室也』，故奉引之。」","sentenceOrder":187},
  {"id":"s_work_han_thu_88_188","chapterId":"ch_work_han_thu_88","textTraditional":"書奏，天子異其意，答曰：「問奉：今園廟有七，云東徙，狀何如？」奉對曰：「昔成王徙洛，般庚遷殷，其所避就，皆陛下所明知也。非有聖明，不能一變天下之道。臣奉愚戇狂惑，唯陛下裁赦。」","sentenceOrder":188},
  {"id":"s_work_han_thu_88_189","chapterId":"ch_work_han_thu_88","textTraditional":"其後，貢禹亦言當定迭毀禮，上遂從之。及匡衡為丞相，奏徙南北郊，其議皆自奉發之。","sentenceOrder":189},
  {"id":"s_work_han_thu_88_190","chapterId":"ch_work_han_thu_88","textTraditional":"奉以中郎為博士、諫大夫，年老以壽終。子及孫，皆以學在儒官。","sentenceOrder":190},
  {"id":"s_work_han_thu_88_191","chapterId":"ch_work_han_thu_88","textTraditional":"李尋字子長，平陵人也。治尚書，與張孺、鄭寬中同師。寬中等守師法教授，尋獨好洪範災異，又學天文月令陰陽。事丞相翟方進，方進亦善為星曆，除尋為吏，數為翟侯言事。帝舅曲陽侯王根為大司馬票騎將軍，厚遇尋。是時多災異，根輔政，數虛己問尋。尋見漢家有中衰阨會之象，其意以為且有洪水為災，乃說根曰：","sentenceOrder":191},
  {"id":"s_work_han_thu_88_192","chapterId":"ch_work_han_thu_88","textTraditional":"書云「天聰明，」〔一〕蓋言紫宮極樞，通位帝紀，〔二〕太微四門，廣開大道，〔三〕五經六緯，尊術顯士，〔四〕翼張舒布，燭臨四海，〔五〕少微處士，為比為輔，〔六〕故次帝廷，女宮在後。〔七〕聖人承天，賢賢易色，取法於此。〔八〕天官上相上將，皆顓面正朝，〔九〕憂責甚重，要在得人。得人之效，成敗之機，不可不勉也。昔秦穆公說諓諓之言，任仡仡之勇，身受大辱，社稷幾亡。〔一０〕悔過自責，思惟黃髮，任用百里奚，卒伯西域，德列王道。〔一一〕二者禍福如此，可不慎哉！","sentenceOrder":192},
  {"id":"s_work_han_thu_88_193","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「虞書皋陶謨之辭也。天視聽，人君之行不可不畏慎也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_88_194","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　孟康曰：「紫宮，天之北宮也。極，天之北極星也，樞是其迴轉者也。天文志曰：『天極其一明者，太一常居也。』太一，天皇大帝也，與通極為一體，故曰通位帝紀也。」","sentenceOrder":194},
  {"id":"s_work_han_thu_88_195","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　孟康曰：「太微，天之南宮也。四門，太微之四門也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_88_196","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　孟康曰：「六緯，五經與樂緯也。」張晏曰：「六緯，五經就孝經緯也。」師古曰：「六緯者，五經之緯及樂緯也。孟說是也。」","sentenceOrder":196},
  {"id":"s_work_han_thu_88_197","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　張晏曰：「翼二十八星，十八度。舒布，張廣也。翼翅夾張，故言也。」","sentenceOrder":197},
  {"id":"s_work_han_thu_88_198","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　孟康曰：「少微四星在太微西，主處士儒學之官，為太微輔佐也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_88_199","chapterId":"ch_work_han_thu_88","textTraditional":"〔七〕　孟康曰：「言少微四星在太微次。太微為天帝廷。女宮謂軒轅星也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_88_200","chapterId":"ch_work_han_thu_88","textTraditional":"〔八〕　師古曰：「賢賢，尊上賢人。易色，輕略於色，不貴之也。易音弋二反。」","sentenceOrder":200},
  {"id":"s_work_han_thu_88_201","chapterId":"ch_work_han_thu_88","textTraditional":"〔九〕　孟康曰：「朝太微宮垣也。西垣為上將，東垣為上相，各專一面而正天之朝事也。」","sentenceOrder":201},
  {"id":"s_work_han_thu_88_202","chapterId":"ch_work_han_thu_88","textTraditional":"〔一０〕師古曰：「諓諓，小善也。仡仡，壯健也。謂聽杞子、逢孫、楊孫之言，言鄭可襲，乃使孟明視、西乞術、白乙丙帥師伐鄭，遂為晉襄公所禦而敗於殽，三帥盡獲，匹馬隻輪皆無反者。諓音踐。仡音（目）〔巨〕乙反，又音牛乞反。」","sentenceOrder":202},
  {"id":"s_work_han_thu_88_203","chapterId":"ch_work_han_thu_88","textTraditional":"〔一一〕師古曰：「謂晉歸三帥之後，穆公自悔，作秦誓云：『雖則員然，尚猶詢茲黃髮，則罔所諐。』自言前有云然之過，今庶幾以道謀此黃髮賢老，則行事無所過失矣。百里奚本虞人也，穆公用之，卒成霸業。」","sentenceOrder":203},
  {"id":"s_work_han_thu_88_204","chapterId":"ch_work_han_thu_88","textTraditional":"夫士者，國家之大寶，功名之本也。將軍一門九侯，二十朱輪，漢興以來，臣子貴盛，未嘗至此。夫物盛必衰，自然之理，唯有賢友彊輔，庶幾可以保身命，全子孫，安國家。","sentenceOrder":204},
  {"id":"s_work_han_thu_88_205","chapterId":"ch_work_han_thu_88","textTraditional":"書曰「曆象日月星辰」，〔一〕此言仰視天文，俯察地理，觀日月消息，候星辰行伍，揆山川變動，參人民繇俗，〔二〕以制法度，考禍福。舉錯誖逆，咎敗將至，徵兆為之先見。〔三〕明君恐懼修正，側身博問，轉禍為福；不可救者，即蓄備以待之，故社稷亡憂。","sentenceOrder":205},
  {"id":"s_work_han_thu_88_206","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「虞書堯典之辭也。」","sentenceOrder":206},
  {"id":"s_work_han_thu_88_207","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「繇讀與謠同。繇俗者，謂若童謠及輿人之誦。」","sentenceOrder":207},
  {"id":"s_work_han_thu_88_208","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「誖，乖也，音布內反。」","sentenceOrder":208},
  {"id":"s_work_han_thu_88_209","chapterId":"ch_work_han_thu_88","textTraditional":"竊見往者赤黃四塞，地氣大發，動土竭民，天下擾亂之徵也。彗星爭明，〔一〕庶雄為桀，大寇之引也。〔二〕此二者已頗效矣。城中訛言大水，奔走上城，朝廷驚駭，女孽入宮，〔三〕此獨未效。間者重以水泉涌溢，旁宮闕仍出。〔四〕月、太白入東井，犯積水，缺天淵。〔五〕日數湛於極陽之色。〔六〕羽氣乘宮，〔七〕起風積雲。又錯以山崩地動，河不用其道。〔八〕盛冬雷電，潛龍為孽。〔九〕繼以隕星流彗，維、填上見，〔一０〕日蝕有背鄉。〔一一〕此亦高下易居，洪水之徵也。不憂不改，洪水乃欲盪滌，流彗乃欲埽除；改之，則有年亡期。〔一二〕故屬者頗有變改，小貶邪猾，〔一三〕日月光精，時雨氣應，〔一四〕此皇天右漢亡已也，〔一五〕何況致大改之！","sentenceOrder":209},
  {"id":"s_work_han_thu_88_210","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　張晏曰：「與日月爭明。」","sentenceOrder":210},
  {"id":"s_work_han_thu_88_211","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「將引致大寇也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_88_212","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　應劭曰：「謂小女陳持弓也。」","sentenceOrder":212},
  {"id":"s_work_han_thu_88_213","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　李奇曰：「旁宮闕而出水也。」師古曰：「旁，附也。仍，頻也。重音直用反。旁音薄郎反。」","sentenceOrder":213},
  {"id":"s_work_han_thu_88_214","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　張晏曰：「犯東井，有水災。」孟康曰：「積水一星在北河北。天淵十星在北斗星東南。缺者，拂其角而過之也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_88_215","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　張晏曰：「眾陽之宗，故為極陽也。色宜明耀，而無光也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_88_216","chapterId":"ch_work_han_thu_88","textTraditional":"〔七〕　孟康曰：「天文志曰西方為羽。羽，少陰之位。少陰臣氣，乘於君也。」晉灼曰：「羽，北方水也，水陰為臣。宮，中央土也，土為君。今水乘土，言臣氣勝於君也。」","sentenceOrder":216},
  {"id":"s_work_han_thu_88_217","chapterId":"ch_work_han_thu_88","textTraditional":"〔八〕　師古曰：「錯，雜也。言河徙流不從故道也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_88_218","chapterId":"ch_work_han_thu_88","textTraditional":"〔九〕　孟康曰：「黑龍冬見。」張晏曰：「五行傳曰：『龍見井中，幽囚之象也。』」","sentenceOrder":218},
  {"id":"s_work_han_thu_88_219","chapterId":"ch_work_han_thu_88","textTraditional":"〔一０〕孟康曰：「有地維星，有四填星，皆妖星也。」晉灼曰：「天文志四填星出四隅，去地可四丈，地維藏光亦出四隅，去地可二丈，若月始出，所見下有亂者亡，有德者昌。」","sentenceOrder":219},
  {"id":"s_work_han_thu_88_220","chapterId":"ch_work_han_thu_88","textTraditional":"〔一一〕師古曰：「背音步內反。鄉讀曰嚮。」","sentenceOrder":220},
  {"id":"s_work_han_thu_88_221","chapterId":"ch_work_han_thu_88","textTraditional":"〔一二〕師古曰：「言可延期，得禳災。」","sentenceOrder":221},
  {"id":"s_work_han_thu_88_222","chapterId":"ch_work_han_thu_88","textTraditional":"〔一三〕師古曰：「屬者謂近時也。屬音之欲反。」","sentenceOrder":222},
  {"id":"s_work_han_thu_88_223","chapterId":"ch_work_han_thu_88","textTraditional":"〔一四〕師古曰：「精謂光明也。」","sentenceOrder":223},
  {"id":"s_work_han_thu_88_224","chapterId":"ch_work_han_thu_88","textTraditional":"〔一五〕師古曰：「右讀曰祐。」","sentenceOrder":224},
  {"id":"s_work_han_thu_88_225","chapterId":"ch_work_han_thu_88","textTraditional":"宜急博求幽隱，拔擢天士，任以大職。〔一〕諸闒茸佞諂，抱虛求進，〔二〕及用殘賊酷虐聞者，若此之徒，皆嫉善憎忠，壞天文，敗地理，涌趯邪陰，湛溺太陽，〔三〕為主結怨於民，〔四〕宜以時廢退，不當得居位。誠必行之，凶災銷滅，子孫之福不旋日而至。政治感陰陽，猶鐵炭之低卬，見效可信者也。〔五〕乃諸蓄水連泉，務通利之。修舊隄防，省池澤稅，以助損邪陰之盛。案行事，考變易，訛言之效，未嘗不至。請徵韓放，〔六〕掾周敞、王望可與圖之。","sentenceOrder":225},
  {"id":"s_work_han_thu_88_226","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　李奇曰：「天士，知天道者也。」晉灼曰：「嚴君平言師於天士。天士，應宿台鼎之臣也。」師古曰：「李說是也。」","sentenceOrder":226},
  {"id":"s_work_han_thu_88_227","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「闒音吐臘反。茸音人勇反。讇，古諂字。」","sentenceOrder":227},
  {"id":"s_work_han_thu_88_228","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「趯字與躍同。湛讀曰沈。」","sentenceOrder":228},
  {"id":"s_work_han_thu_88_229","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　師古曰：「為音于偽反。」","sentenceOrder":229},
  {"id":"s_work_han_thu_88_230","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　孟康曰：「天文志云『縣土炭』也，以鐵易土耳。先冬夏至，縣鐵炭於衡，各一端，令適停。冬，陽氣至，炭仰而鐵低。夏，陰氣至，炭低而鐵仰。以此候二至也。」","sentenceOrder":230},
  {"id":"s_work_han_thu_88_231","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　服虔曰：「姓名也，曉水。」","sentenceOrder":231},
  {"id":"s_work_han_thu_88_232","chapterId":"ch_work_han_thu_88","textTraditional":"根於是薦尋。哀帝初即位，召尋待詔黃門，使侍中衛尉傅喜問尋曰：「間者水出地動，日月失度，星辰亂行，災異仍重，〔一〕極言毋有所諱。」尋對曰：","sentenceOrder":232},
  {"id":"s_work_han_thu_88_233","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「重音直用反。」","sentenceOrder":233},
  {"id":"s_work_han_thu_88_234","chapterId":"ch_work_han_thu_88","textTraditional":"陛下聖德，尊天敬地，畏命重民，悼懼變異，不忘疏賤之臣，幸使重臣臨問，愚臣不足以奉明詔。竊見陛下新即位，開大明，除忌諱，博延名士，靡不並進。臣尋位卑術淺，過隨眾賢待詔，〔一〕食太官，衣御府，久汙玉堂之署。〔二〕比得召見，亡以自效。〔三〕復特見延問至誠，自以逢不世出之命，願竭愚心，不敢有所避，庶幾萬分有一可采。唯棄須臾之間，宿留瞽言，〔四〕考之文理，稽之五經，揆之聖意，以參天心。夫變異之來，各應象而至，臣謹條陳所聞。","sentenceOrder":234},
  {"id":"s_work_han_thu_88_235","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「過猶謬也。」","sentenceOrder":235},
  {"id":"s_work_han_thu_88_236","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「玉堂殿在未央宮。」","sentenceOrder":236},
  {"id":"s_work_han_thu_88_237","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「比，頻也。」","sentenceOrder":237},
  {"id":"s_work_han_thu_88_238","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　師古曰：「間謂空隙之時也。宿音先就反。留音力救反。」","sentenceOrder":238},
  {"id":"s_work_han_thu_88_239","chapterId":"ch_work_han_thu_88","textTraditional":"易曰：「縣象著明，莫大乎日月。」〔一〕夫日者，眾陽之長，輝光所燭，萬里同晷，人君之表也。〔二〕故日將旦，清風發，群陰伏，君以臨朝，不牽於色。日初出，炎以陽，君登朝，佞不行，忠直進，不蔽障。日中輝光，君德盛明，大臣奉公。日將入，專以壹，君就房，有常節。君不修道，則日失其度，晻昧亡光。〔三〕各有云為。其於東方作，日初出時，〔四〕陰雲邪氣起者，法為牽於女謁，〔五〕有所畏難；日出後，為近臣亂政；日中，為大臣欺誣；日且入，為妻妾役使所營。〔六〕間者日尤不精，光明侵奪失色，邪氣珥蜺數作。本起於晨，相連至昏，其日出後至日中間差瘉。〔七〕小臣不知內事，竊以日視陛下志操，衰於始初多矣。其咎恐有以守正直言而得罪者，傷嗣害世，不可不慎也。唯陛下執乾剛之德，彊志守度，毋聽女謁邪臣之態。諸保阿乳母甘言悲辭之託，斷而勿聽。勉強大誼，絕小不忍；良有不得已，可賜以財貨，不可私以官位，誠皇天之禁也。日失其光，則星辰放流。〔八〕陽不能制陰，陰桀得作。間者太白正晝經天。宜隆德克躬，以執不軌。","sentenceOrder":239},
  {"id":"s_work_han_thu_88_240","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「上繫之辭也。在天成象，故曰縣象也。」","sentenceOrder":240},
  {"id":"s_work_han_thu_88_241","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「晷，景也。」","sentenceOrder":241},
  {"id":"s_work_han_thu_88_242","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「晻與暗同，又音烏感反。」","sentenceOrder":242},
  {"id":"s_work_han_thu_88_243","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　師古曰：「作，起也。日出之時，人物皆起。」","sentenceOrder":243},
  {"id":"s_work_han_thu_88_244","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　服虔曰：「謁，請也。」","sentenceOrder":244},
  {"id":"s_work_han_thu_88_245","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　師古曰：「營謂繞也。」","sentenceOrder":245},
  {"id":"s_work_han_thu_88_246","chapterId":"ch_work_han_thu_88","textTraditional":"〔七〕　師古曰：「瘉與愈同。」","sentenceOrder":246},
  {"id":"s_work_han_thu_88_247","chapterId":"ch_work_han_thu_88","textTraditional":"〔八〕　張晏曰：「日夜食則失光，晝立六尺木，不見其景也。日陽失光明，陰得施也。」","sentenceOrder":247},
  {"id":"s_work_han_thu_88_248","chapterId":"ch_work_han_thu_88","textTraditional":"臣聞月者，眾陰之長，銷息見伏，百里為品，千里立表，萬里連紀，〔一〕妃后大臣諸侯之象也。朔晦正終始，弦為繩墨，望成君德，春夏南，秋冬北。間者，月數以春夏與日同道，〔二〕過軒轅上后受氣，〔三〕入太微帝廷（楊）〔揚〕光輝，犯上將近臣，列星皆失色，厭厭如滅，〔四〕此為母后與政亂朝，〔五〕陰陽俱傷，兩不相便。外臣不知朝事，竊信天文即如此，近臣已不足杖矣。〔六〕屋大柱小，可為寒心。〔七〕唯陛下親求賢士，無彊所惡，以崇社稷，尊彊本朝。〔八〕","sentenceOrder":248},
  {"id":"s_work_han_thu_88_249","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　孟康曰：「品，同也，言百里內數度同也。千里則當立表度其景，萬里則繼其本所起紀其宿度也。」","sentenceOrder":249},
  {"id":"s_work_han_thu_88_250","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　孟康曰：「房有四星，其間有三道。春夏南行，南頭第一星裏道也。秋冬北行。北頭第一星裏道也。與日同道者，謂中央道也。此三道者，日月五星之所由也。」","sentenceOrder":250},
  {"id":"s_work_han_thu_88_251","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　孟康曰：「軒轅南大星為后。」","sentenceOrder":251},
  {"id":"s_work_han_thu_88_252","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　鄭氏曰：「厭音檿桑之檿。」師古曰：「音烏點反。」","sentenceOrder":252},
  {"id":"s_work_han_thu_88_253","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　師古曰：「與讀曰豫。」","sentenceOrder":253},
  {"id":"s_work_han_thu_88_254","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　師古曰：「杖謂倚任也。」","sentenceOrder":254},
  {"id":"s_work_han_thu_88_255","chapterId":"ch_work_han_thu_88","textTraditional":"〔七〕　師古曰：「言天下事重大，臣之任當得賢能者。」","sentenceOrder":255},
  {"id":"s_work_han_thu_88_256","chapterId":"ch_work_han_thu_88","textTraditional":"〔八〕　師古曰：「邪佞之人誠可賤惡，勿得寵異，令其盛彊也。」","sentenceOrder":256},
  {"id":"s_work_han_thu_88_257","chapterId":"ch_work_han_thu_88","textTraditional":"臣聞五星者，五行之精，五帝司命，應王者號令為之節度。歲星主歲事，為統首，號令所紀，今失度而盛，此君指意欲有所為，未得其節也。又填星不避歲星者，后帝共政，相留於奎、婁，〔一〕當以義斷之。（營）〔熒〕惑往來亡常，周歷兩宮，作態低卬，〔二〕入天門，上明堂，貫尾亂宮。〔三〕太白發越犯庫，〔四〕兵寇之應也。貫黃龍，入帝庭，〔五〕當門而出，隨熒惑入天門，至房而分，欲與熒惑為患，不敢當明堂之精。此陛下神靈，故禍亂不成也。熒惑厥弛，〔六〕佞巧依勢，微言毀譽，進類蔽善。〔七〕太白出端門，〔八〕臣有不臣者。火入室，金上堂，〔九〕不以時解，其憂凶。填、歲相守，又主內亂。宜察蕭牆之內，毋忽親疏之微，〔一０〕誅放佞人，防絕萌牙，以盪滌濁濊，消散積惡，〔一一〕毋使得成禍亂。辰星主正四時，當效於四仲；四時失序，則辰星作異。今出於歲首之孟，天所以譴告陛下也。政急則出蚤，政緩則出晚，政絕不行則伏不見而為彗茀。〔一二〕四孟皆出，為易王命；四季皆出，星家所諱。今幸獨出寅孟之月，蓋皇天所以篤右陛下也，〔一三〕宜深自改。","sentenceOrder":257},
  {"id":"s_work_han_thu_88_258","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　張晏曰：「歲星為帝，填星為女主也。」","sentenceOrder":258},
  {"id":"s_work_han_thu_88_259","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　張晏曰：「兩宮謂紫微、太微。」","sentenceOrder":259},
  {"id":"s_work_han_thu_88_260","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　孟康曰：「角兩星為天門，房為明堂，尾為後宮。」蘇林曰：「常占（常）〔當〕從尾北，而今貫之，尾為後宮之義也。」","sentenceOrder":260},
  {"id":"s_work_han_thu_88_261","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　張晏曰：「發越，疾貌也。庫，天庫也。」孟康曰：「奎為天庫。」","sentenceOrder":261},
  {"id":"s_work_han_thu_88_262","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　張晏曰：「黃龍，軒轅也。」","sentenceOrder":262},
  {"id":"s_work_han_thu_88_263","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　張晏曰：「厥弛，動搖貌。」","sentenceOrder":263},
  {"id":"s_work_han_thu_88_264","chapterId":"ch_work_han_thu_88","textTraditional":"〔七〕　師古曰：「進其黨類而擁蔽善人。」","sentenceOrder":264},
  {"id":"s_work_han_thu_88_265","chapterId":"ch_work_han_thu_88","textTraditional":"〔八〕　孟康曰：「端門，太微正南門。」","sentenceOrder":265},
  {"id":"s_work_han_thu_88_266","chapterId":"ch_work_han_thu_88","textTraditional":"〔九〕　張晏曰：「熒惑入營室也。」孟康曰：「火入室謂熒惑歷兩宮也。金謂太白也。上堂，入房星也。」","sentenceOrder":266},
  {"id":"s_work_han_thu_88_267","chapterId":"ch_work_han_thu_88","textTraditional":"〔一０〕師古曰：「微謂其事微。」","sentenceOrder":267},
  {"id":"s_work_han_thu_88_268","chapterId":"ch_work_han_thu_88","textTraditional":"〔一一〕師古曰：「濊與穢同也。」","sentenceOrder":268},
  {"id":"s_work_han_thu_88_269","chapterId":"ch_work_han_thu_88","textTraditional":"〔一二〕師古曰：「茀與孛同。」","sentenceOrder":269},
  {"id":"s_work_han_thu_88_270","chapterId":"ch_work_han_thu_88","textTraditional":"〔一三〕師古曰：「篤，厚也。右與祐同。祐猶助也。」","sentenceOrder":270},
  {"id":"s_work_han_thu_88_271","chapterId":"ch_work_han_thu_88","textTraditional":"治國故不可以戚戚，欲速則不達。經曰：「三載考績，三考黜陟。」〔一〕加以號令不順四時，既往不咎，來事之師也。間者春三月治大獄，時賊陰立逆，恐歲小收；季夏舉兵法，時寒氣應，恐後有霜雹之災；秋月行封爵，其月土濕奧，〔二〕恐後有雷雹之變。夫以喜怒賞罰，而不顧時禁，雖有堯舜之心，猶不能致和。善言天者，必有效於人。設上農夫而欲冬田，肉袒深耕，汗出種之，然猶不生者，非人心不至，天時不得也。易曰：「時止則止，時行則行，動靜不失其時，其道光明。」〔三〕書曰：「敬授民時。」〔四〕故古之王者，尊天地，重陰陽，敬四時，嚴月令。順之以善政，則和氣可立致，猶枹鼓之相應也。〔五〕今朝廷忽於時月之令，諸侍中尚書近臣宜皆令通知月令之意，設群下請事；若陛下出令有謬於時者，當知爭之，以順時氣。","sentenceOrder":271},
  {"id":"s_work_han_thu_88_272","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「虞書舜典之辭也，言三年一考功績，三考一行黜陟也。」","sentenceOrder":272},
  {"id":"s_work_han_thu_88_273","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　張晏曰：「違於月令也。」師古曰：「奧，溫也，音於六反。」","sentenceOrder":273},
  {"id":"s_work_han_thu_88_274","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「此艮卦象辭也。言動止隨時則有光明也。」","sentenceOrder":274},
  {"id":"s_work_han_thu_88_275","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　師古曰：「虞書堯典之辭也。言授下以四時之命，不可不敬也。」","sentenceOrder":275},
  {"id":"s_work_han_thu_88_276","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　師古曰：「枹，擊鼓之椎也，音孚。其字從木也。」","sentenceOrder":276},
  {"id":"s_work_han_thu_88_277","chapterId":"ch_work_han_thu_88","textTraditional":"臣聞五行以水為本，其星玄武婺女，天地所紀，終始所生。〔一〕水為準平，王道公正修明，則百川理，落脈通；〔二〕偏黨失綱，則踊溢為敗。書云「水曰潤下」，〔三〕陰動而卑，不失其道。天下有道，則河出圖，洛出書，故河、洛決溢，所為最大。今汝、潁畎澮皆川水漂踊，與雨水並為民害，〔四〕此詩所謂「震電，不寧不令，百川沸騰」者也。〔五〕其咎在於皇甫卿士之屬。〔六〕唯陛下留意詩人之言，少抑外親大臣。","sentenceOrder":277},
  {"id":"s_work_han_thu_88_278","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　孟康曰：「婺女，須女也，北方天地之統，陰陽之終始也。」","sentenceOrder":278},
  {"id":"s_work_han_thu_88_279","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「落謂經絡也。」","sentenceOrder":279},
  {"id":"s_work_han_thu_88_280","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「周書洪範之辭也。」","sentenceOrder":280},
  {"id":"s_work_han_thu_88_281","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　師古曰：「畎澮，小流也。許慎說廣尺深尺曰畎，廣二尋深二仞謂之澮。川者，水貫穿而通流也。畎音工犬反。澮音工外反。」","sentenceOrder":281},
  {"id":"s_work_han_thu_88_282","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　師古曰：「詩小雅十月之交之詩也。，光貌。寧，安；令，善也。言陰陽失和，雷電失序，不安不善，故百川又沸騰。」","sentenceOrder":282},
  {"id":"s_work_han_thu_88_283","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　師古曰：「皇甫卿士，周室女寵之族也，解在劉向傳。」","sentenceOrder":283},
  {"id":"s_work_han_thu_88_284","chapterId":"ch_work_han_thu_88","textTraditional":"臣聞地道柔靜，陰之常義也。地有上中下，其上位震，應妃后不順，中位應大臣作亂，下位應庶民離畔。震或於其國，國君之咎也。四方中央連國歷州俱動者，其異最大。間者關東地數震，五星作異，亦未大逆，宜務崇陽抑陰，以救其咎；固志建威，閉絕私路，拔進英雋，退不任職，以彊本朝。夫本彊則精神折衝，本弱則招殃致凶，為邪謀所陵。〔一〕聞往者淮南王作謀之時，其所難者，獨有汲黯，〔以為〕公孫弘等不足言也。弘，漢之名相，於今亡比，而尚見輕，何況亡弘之屬乎？故曰朝廷亡人，則為賊亂所輕，其道自然也。天下未聞陛下奇策固守之臣也。語曰，何以知朝廷之衰？人人自賢，不務於通人，故世陵夷。〔二〕","sentenceOrder":284},
  {"id":"s_work_han_thu_88_285","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「折衝，言有欲衝突為害者，則能折挫之。」","sentenceOrder":285},
  {"id":"s_work_han_thu_88_286","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「通人謂薦達賢材也。陵夷謂頹替也。」","sentenceOrder":286},
  {"id":"s_work_han_thu_88_287","chapterId":"ch_work_han_thu_88","textTraditional":"馬不伏歷，不可以趨道；士不素養，不可以重國。〔一〕詩曰「濟濟多士，文王以寧」，〔二〕孔子曰「十室之邑，必有忠信」，〔三〕非虛言也。陛下秉四海之眾，曾亡柱幹之固守聞於四境，殆開之不廣，取之不明，勸之不篤。傳曰：「土之美者善養禾，君之明者善養士。」中人皆可使為君子。〔四〕詔書進賢良，赦小過，無求備，以博聚英俊。如近世貢禹，以言事忠切蒙尊榮，當此之時，士厲身立名者多。禹死之後，日日以衰。及京兆尹王章坐言事誅滅，智者結舌，〔五〕邪偽並興，外戚顓命，〔六〕君臣隔塞，至絕繼嗣，女宮作亂。〔七〕此行事之敗，誠可畏而悲也。","sentenceOrder":287},
  {"id":"s_work_han_thu_88_288","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「伏歷謂伏槽歷而秣之也。趨讀曰趣。」","sentenceOrder":288},
  {"id":"s_work_han_thu_88_289","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「大雅文王之詩也。已解於上。」","sentenceOrder":289},
  {"id":"s_work_han_thu_88_290","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「論語載孔子之言也。」","sentenceOrder":290},
  {"id":"s_work_han_thu_88_291","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　師古曰：「言在所以勸厲之。」","sentenceOrder":291},
  {"id":"s_work_han_thu_88_292","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　師古曰：「不敢出言也。」","sentenceOrder":292},
  {"id":"s_work_han_thu_88_293","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　師古曰：「顓與專同。」","sentenceOrder":293},
  {"id":"s_work_han_thu_88_294","chapterId":"ch_work_han_thu_88","textTraditional":"〔七〕　師古曰：「謂趙飛燕姊妺也。」","sentenceOrder":294},
  {"id":"s_work_han_thu_88_295","chapterId":"ch_work_han_thu_88","textTraditional":"本在積任母后之家，非一日之漸，往者不可及，來者猶可追也。先帝大聖，深見天意昭然，使陛下奉承天統，欲矯正之也。宜少抑外親，選練左右，舉有德行道術通明之士充備天官，然後可以輔聖德，保帝位，承大宗。下至郎吏從官，行能亡以異，又不通一藝，及博士無文雅者，宜皆使就南畝，〔一〕以視天下，〔二〕明朝廷皆賢材君子，於以重朝尊君，滅凶致安，此其本也。臣自知所言害身，不辟死亡之誅，唯財留神，反覆覆愚臣之言。〔三〕","sentenceOrder":295},
  {"id":"s_work_han_thu_88_296","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「遣歸農業。」","sentenceOrder":296},
  {"id":"s_work_han_thu_88_297","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「視讀曰示。」","sentenceOrder":297},
  {"id":"s_work_han_thu_88_298","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「財與裁同，謂裁量而反思之。」","sentenceOrder":298},
  {"id":"s_work_han_thu_88_299","chapterId":"ch_work_han_thu_88","textTraditional":"是時哀帝初立，成帝外家王氏未甚抑黜，而帝外家丁、傅新貴，祖母傅太后尤驕恣，欲稱尊號。丞相孔光、大司空師丹執政諫爭，久之，上不得已，遂免光、丹而尊傅太后。語在丹傳。上雖不從尋言，然采其語，每有非常，輒問尋。尋對屢中，遷黃門侍郎。以尋言且有水災，故拜尋為騎都尉，使護河隄。","sentenceOrder":299},
  {"id":"s_work_han_thu_88_300","chapterId":"ch_work_han_thu_88","textTraditional":"初，成帝時，齊人甘忠可詐造天官曆、包元太平經十二卷，以言「漢家逢天地之大終，當更受命於天，天帝使真人赤精子，下教我此道。」忠可以教重平夏賀良、容丘丁廣世、〔一〕東郡郭昌等，中壘校尉劉向奏忠可假鬼神罔上惑眾，下獄治服，未斷病死。賀良等坐挾學忠可書以不敬論，後賀良等復私以相教。哀帝初立，司隸校尉解光亦以明經通災異得幸，白賀良等所挾忠可書。事下奉車都尉劉歆，歆以為不合五經，不可施行。而李尋亦好之。光曰：「前歆父向奏忠可下獄，歆安肯通此道？」時郭昌為長安令，勸尋宜助賀良等。尋遂白賀良等皆待詔黃門，數召見，陳說「漢曆中衰，當更受命。成帝不應天命，故絕嗣。今陛下久疾，變異屢數，〔二〕天所以譴告人也。宜急改元易號，乃得延年益壽，皇子生，災異息矣。得道不得行，咎殃且亡，〔三〕不有洪水將出，災火且起，滌盪（人民）〔民人〕。」","sentenceOrder":300},
  {"id":"s_work_han_thu_88_301","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　服虔曰：「重平，勃海縣也。」晉灼曰：「容丘，東海縣也。」","sentenceOrder":301},
  {"id":"s_work_han_thu_88_302","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「數音所角反。」","sentenceOrder":302},
  {"id":"s_work_han_thu_88_303","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「言知道不能行之，必有殃咎，將至滅亡。」","sentenceOrder":303},
  {"id":"s_work_han_thu_88_304","chapterId":"ch_work_han_thu_88","textTraditional":"哀帝久寢疾，幾其有益，〔一〕遂從賀良等議。於是詔制丞相御史：「蓋聞尚書『五曰考終命』，〔二〕言大運壹終，更紀天元人元，考文正理，推曆定紀，數如甲子也。朕以眇身入繼太祖，承皇天，總百僚，子元元，未有應天心之效。即位出入三年，災變數降，日月失度，星辰錯謬，高下貿易，〔三〕大異連仍，盜賊並起。〔四〕朕甚懼焉，戰戰兢兢，唯恐陵夷。〔五〕惟漢興至今二百載，曆紀開元，皇天降非材之右，漢國再獲受命之符，〔六〕朕之不德，曷敢不通夫受天之元命，必與天下自新。其大赦天下，以建平二年為太初（元將）元年，號曰陳聖劉太平皇帝。漏刻以百二十為度。布告天下，使明知之。」後月餘，上疾自若。〔七〕賀良等復欲妄變政事，大臣爭以為不可許。賀良等奏言大臣皆不知天命，宜退丞相御史，以解光、李尋輔政。上以其言亡驗，遂下賀良等吏，而下詔曰：「朕獲保宗廟，為政不德，變異屢仍，恐懼戰栗，未知所繇。〔八〕待詔賀良等建言改元易號，增益漏刻，可以永安國家。朕信道不篤，過聽其言〔九〕，幾為百姓獲福。〔一０〕卒無嘉應，久旱為災。以問賀良等，對當復改制度，皆背經誼，違聖制，不合時宜。夫過而不改，是為過矣。六月甲子詔書，非赦令也，皆蠲除之。〔一一〕賀良等反道惑眾，姦態當窮竟。」皆下獄，光祿勳平當、光祿大夫毛莫如與御史中丞、廷尉雜治，當賀良等執左道，亂朝政，〔一二〕傾覆國家，誣罔主上，不道。賀良等皆伏誅。尋及解光減死一等，徙敦煌郡。","sentenceOrder":304},
  {"id":"s_work_han_thu_88_305","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「幾讀曰冀。」","sentenceOrder":305},
  {"id":"s_work_han_thu_88_306","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「周書洪範五福之數也。言得壽考而終其命也。」","sentenceOrder":306},
  {"id":"s_work_han_thu_88_307","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「言山崩川竭也。」","sentenceOrder":307},
  {"id":"s_work_han_thu_88_308","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　師古曰：「仍，頻也。」","sentenceOrder":308},
  {"id":"s_work_han_thu_88_309","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　師古曰：「慮漸滅亡也。」","sentenceOrder":309},
  {"id":"s_work_han_thu_88_310","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　師古曰：「右讀曰祐。祐，助也。帝自言不材而得天助也。」","sentenceOrder":310},
  {"id":"s_work_han_thu_88_311","chapterId":"ch_work_han_thu_88","textTraditional":"〔七〕　師古曰：「自若言如故也。」","sentenceOrder":311},
  {"id":"s_work_han_thu_88_312","chapterId":"ch_work_han_thu_88","textTraditional":"〔八〕　師古曰：「繇讀與由同。」","sentenceOrder":312},
  {"id":"s_work_han_thu_88_313","chapterId":"ch_work_han_thu_88","textTraditional":"〔九〕　師古曰：「過，誤也。」","sentenceOrder":313},
  {"id":"s_work_han_thu_88_314","chapterId":"ch_work_han_thu_88","textTraditional":"〔一０〕師古曰：「幾讀曰冀。」","sentenceOrder":314},
  {"id":"s_work_han_thu_88_315","chapterId":"ch_work_han_thu_88","textTraditional":"〔一一〕師古曰：「唯赦令不改，餘皆除之。」","sentenceOrder":315},
  {"id":"s_work_han_thu_88_316","chapterId":"ch_work_han_thu_88","textTraditional":"〔一二〕師古曰：「當謂處正其罪名。」","sentenceOrder":316},
  {"id":"s_work_han_thu_88_317","chapterId":"ch_work_han_thu_88","textTraditional":"贊曰：幽贊神明，通合天人之道者，莫著乎易、春秋。〔一〕然子贛猶云「夫子之文章可得而聞，〔二〕夫子之言性與天道不可得而聞」已矣。〔三〕漢興推陰陽言災異者，孝武時有董仲舒、夏侯始昌，昭、宣則眭孟、夏侯勝，元、成則京房、翼奉、劉向、谷永，哀、平則李尋、田終術。此其納說時君著明者也。察其所言，仿佛一端。〔四〕假經設誼，依託象類，或不免乎「億則屢中」。〔五〕仲舒下吏，夏侯囚執，眭孟誅戮，李尋流放，此學者之大戒也。京房區區，不量淺深，危言刺譏，構怨彊臣，罪辜不旋踵，亦不密以失身，悲夫！〔六〕","sentenceOrder":317},
  {"id":"s_work_han_thu_88_318","chapterId":"ch_work_han_thu_88","textTraditional":"〔一〕　師古曰：「幽，深；贊，明也。」","sentenceOrder":318},
  {"id":"s_work_han_thu_88_319","chapterId":"ch_work_han_thu_88","textTraditional":"〔二〕　師古曰：「謂易辭文言及春秋之屬是。」","sentenceOrder":319},
  {"id":"s_work_han_thu_88_320","chapterId":"ch_work_han_thu_88","textTraditional":"〔三〕　師古曰：「性命玄遠，天道幽深，故孔子不言之也。此皆論語述子貢之言也。」","sentenceOrder":320},
  {"id":"s_work_han_thu_88_321","chapterId":"ch_work_han_thu_88","textTraditional":"〔四〕　師古曰：「仿讀曰髣。佛與彿同。」","sentenceOrder":321},
  {"id":"s_work_han_thu_88_322","chapterId":"ch_work_han_thu_88","textTraditional":"〔五〕　師古曰：「論語稱孔子曰『賜不受命，而貨殖焉，億則屢中』，故此贊引之，言仲舒等億度，所言既多，故時有中者耳，非必道術皆通明也。億音於力反。」","sentenceOrder":322},
  {"id":"s_work_han_thu_88_323","chapterId":"ch_work_han_thu_88","textTraditional":"〔六〕　師古曰：「易上繫辭曰『君不密則失臣，臣不密則失身』，故贊引之也。」","sentenceOrder":323},
  {"id":"s_work_han_thu_88_324","chapterId":"ch_work_han_thu_88","textTraditional":"校勘記","sentenceOrder":324},
  {"id":"s_work_han_thu_88_325","chapterId":"ch_work_han_thu_88","textTraditional":"三一五三頁　六行　漢之（決錄）〔炔欽〕又不作眭字，　宋祁說，「決錄」浙本作「炔欽」。葉德輝說，儒林傳許商門人有齊人炔欽，則作「決錄」者誤也。","sentenceOrder":325},
  {"id":"s_work_han_thu_88_326","chapterId":"ch_work_han_thu_88","textTraditional":"三一五三頁一二行　（而）泰山者岱宗之嶽，　景祐、殿本都無「而」字。","sentenceOrder":326},
  {"id":"s_work_han_thu_88_327","chapterId":"ch_work_han_thu_88","textTraditional":"三一五五頁　八行　光卒與安世（共）白太后，　景祐、殿本都無「共」字。","sentenceOrder":327},
  {"id":"s_work_han_thu_88_328","chapterId":"ch_work_han_thu_88","textTraditional":"三一五六頁　二行　察（謂）〔為〕計謀不敢明顯言之也。　景祐、殿本都作「為」。王先謙說「為」「謂」同字。","sentenceOrder":328},
  {"id":"s_work_han_thu_88_329","chapterId":"ch_work_han_thu_88","textTraditional":"三一五六頁一三行　物故者（過）半。　宋祁說，「者」字下疑有「過」字。按景祐本無「過」字，殿本亦無。","sentenceOrder":329},
  {"id":"s_work_han_thu_88_330","chapterId":"ch_work_han_thu_88","textTraditional":"三一五九頁一三行　言於勝及高兩處采問疑義而得（之）。　宋祁說，注末當有「之」字。按景祐本無「之」字，殿本亦無。","sentenceOrder":330},
  {"id":"s_work_han_thu_88_331","chapterId":"ch_work_han_thu_88","textTraditional":"三一六一頁　八行　令覺之，自除，二尉負其（二）〔罪〕。　殿本作「罪」。王先謙說作「罪」是。","sentenceOrder":331},
  {"id":"s_work_han_thu_88_332","chapterId":"ch_work_han_thu_88","textTraditional":"三一六二頁　八行　如知（之），何故用之？　景祐、殿本都無「之」字，通鑑同。","sentenceOrder":332},
  {"id":"s_work_han_thu_88_333","chapterId":"ch_work_han_thu_88","textTraditional":"三一六四頁一三行　臣〔前〕以六月中言遯卦不效，　景祐、殿本都有「前」字。","sentenceOrder":333},
  {"id":"s_work_han_thu_88_334","chapterId":"ch_work_han_thu_88","textTraditional":"三一六五頁　九行　詭，責也，〔自以為憂責也〕。　景祐、殿本都有後六字。","sentenceOrder":334},
  {"id":"s_work_han_thu_88_335","chapterId":"ch_work_han_thu_88","textTraditional":"三一六七頁　二行　（固）〔因〕令房為淮陽王作求朝奏草，　景祐、殿本都作「因」。","sentenceOrder":335},
  {"id":"s_work_han_thu_88_336","chapterId":"ch_work_han_thu_88","textTraditional":"三一六七頁一三行　平昌侯王臨以宣（布）〔帝〕外屬侍中，　景祐、殿、局本都作「帝」，此誤。","sentenceOrder":336},
  {"id":"s_work_han_thu_88_337","chapterId":"ch_work_han_thu_88","textTraditional":"三一六九頁　三行　無所（加）〔容〕受，　景祐、殿本都作「容」。王先謙說作「容」是。","sentenceOrder":337},
  {"id":"s_work_han_thu_88_338","chapterId":"ch_work_han_thu_88","textTraditional":"三一七二頁一二行　省苑（囿）〔馬〕，　景祐本作「馬」。王念孫說景祐本是。","sentenceOrder":338},
  {"id":"s_work_han_thu_88_339","chapterId":"ch_work_han_thu_88","textTraditional":"三一七二頁　五行　〈豸原〉音（完）〔桓〕。　景祐、殿本都作「桓」。","sentenceOrder":339},
  {"id":"s_work_han_thu_88_340","chapterId":"ch_work_han_thu_88","textTraditional":"三一七五頁一二行　（凰）〔鳳〕皇、　景祐、殿本都作「鳳」，此誤。","sentenceOrder":340},
  {"id":"s_work_han_thu_88_341","chapterId":"ch_work_han_thu_88","textTraditional":"三一七六頁　四行　左據成皋，（左）〔右〕阻黽池，　景祐、殿，局本都作「右」。","sentenceOrder":341},
  {"id":"s_work_han_thu_88_342","chapterId":"ch_work_han_thu_88","textTraditional":"三一八０頁　八行　仡，（目）〔巨〕乙反，　景祐、殿、局本都作「巨」，此誤。","sentenceOrder":342},
  {"id":"s_work_han_thu_88_343","chapterId":"ch_work_han_thu_88","textTraditional":"三一八五頁一三行　入太微帝廷（楊）〔揚〕光煇，　景祐、殿本都作「揚」，此誤。","sentenceOrder":343},
  {"id":"s_work_han_thu_88_344","chapterId":"ch_work_han_thu_88","textTraditional":"三一八六頁一二行　（營）〔熒〕惑往來亡常，　劉攽說「營」當作「熒」。按殿本作「熒」。","sentenceOrder":344},
  {"id":"s_work_han_thu_88_345","chapterId":"ch_work_han_thu_88","textTraditional":"三一八七頁　八行　常占（常）〔當〕從尾北，　景祐、殿本都作「當」，王先謙說作「當」是。","sentenceOrder":345},
  {"id":"s_work_han_thu_88_346","chapterId":"ch_work_han_thu_88","textTraditional":"三一九０頁　三行　〔以為〕公孫弘等不足言也。　景祐、殿本都有「以為」二字。","sentenceOrder":346},
  {"id":"s_work_han_thu_88_347","chapterId":"ch_work_han_thu_88","textTraditional":"三一九二頁一二行　滌盪（人民）〔民人〕。　景祐、殿本都作「民人」。","sentenceOrder":347},
  {"id":"s_work_han_thu_88_348","chapterId":"ch_work_han_thu_88","textTraditional":"三一九三頁　六行　以建平二年為太初（元將）元年，　景祐、殿本都無「元將」二字。","sentenceOrder":348},
  {"id":"s_work_han_thu_88_349","chapterId":"ch_work_han_thu_88","textTraditional":"三一九三頁一二行　六月甲子詔書，非赦令也，皆蠲除之。〔一一〕　注〔一一〕原在「也」字下，改從景祐、殿本。","sentenceOrder":349},
  {"id":"s_work_han_thu_89_1","chapterId":"ch_work_han_thu_89","textTraditional":"趙廣漢字子都，涿郡蠡吾人也，〔一〕故屬河間。〔二〕少為郡吏、州從事，以廉絜通敏下士為名。〔三〕舉茂材，平準令。察廉為陽翟令。以治行尤異，遷京輔都尉，守京兆尹。會昭帝崩，而新豐杜建為京兆掾，護作平陵方上。〔四〕建素豪俠，賓客為姦利，廣漢聞之，先風告。建不改，〔五〕於是收案致法。〔六〕中貴人豪長者為請無不至，終無所聽。〔七〕宗族賓客謀欲篡取，〔八〕廣漢盡知其計議主名起居，〔九〕使吏告曰：「若計如此，且并滅家。」令數吏將建棄巿，莫敢近者。京師稱之。","sentenceOrder":1},
  {"id":"s_work_han_thu_89_2","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「蠡音禮。」","sentenceOrder":2},
  {"id":"s_work_han_thu_89_3","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「言蠡吾舊屬河間，後屬涿郡。」","sentenceOrder":3},
  {"id":"s_work_han_thu_89_4","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「敏謂材識捷疾也。下音胡嫁反。」","sentenceOrder":4},
  {"id":"s_work_han_thu_89_5","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　孟康曰：「壙臧上也。」師古曰：「方上〔解〕在張湯傳。」","sentenceOrder":5},
  {"id":"s_work_han_thu_89_6","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　師古曰：「風讀曰諷。」","sentenceOrder":6},
  {"id":"s_work_han_thu_89_7","chapterId":"ch_work_han_thu_89","textTraditional":"〔六〕　師古曰：「致，至也。令至於罪罰之法。」","sentenceOrder":7},
  {"id":"s_work_han_thu_89_8","chapterId":"ch_work_han_thu_89","textTraditional":"〔七〕　師古曰：「中貴人，居中朝而貴者也。豪，豪桀也。長者，有名德之人也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_89_9","chapterId":"ch_work_han_thu_89","textTraditional":"〔八〕　師古曰：「逆取曰篡。」","sentenceOrder":9},
  {"id":"s_work_han_thu_89_10","chapterId":"ch_work_han_thu_89","textTraditional":"〔九〕　師古曰：「起居謂居止之處，及欲發起之狀。」","sentenceOrder":10},
  {"id":"s_work_han_thu_89_11","chapterId":"ch_work_han_thu_89","textTraditional":"是時，昌邑王徵即位，行淫亂，大將軍霍光與群臣共廢王，尊立宣帝。廣漢以與議定策，賜爵關內侯。〔一〕","sentenceOrder":11},
  {"id":"s_work_han_thu_89_12","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「與讀曰豫。」","sentenceOrder":12},
  {"id":"s_work_han_thu_89_13","chapterId":"ch_work_han_thu_89","textTraditional":"遷潁川太守。郡大姓原、褚宗族橫恣，〔一〕賓客犯為盜賊，前二千石莫能禽制。廣漢既至數月，誅原、褚首惡，郡中震栗。","sentenceOrder":13},
  {"id":"s_work_han_thu_89_14","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　李奇曰：「原音元。」師古曰：「原、褚，二姓也。原讀如本字。橫音胡孟反。」","sentenceOrder":14},
  {"id":"s_work_han_thu_89_15","chapterId":"ch_work_han_thu_89","textTraditional":"先是，潁川豪桀大姓相與為婚姻，吏俗朋黨。廣漢患之，厲使其中可用者受記，〔一〕出有案問，既得罪名，行法罰之，廣漢故漏泄其語，令相怨咎。〔二〕又教吏為缿筩，〔三〕及得投書，削其主名，而託以為豪桀大姓子弟所言。其後彊宗大族家家結為仇讎，姦黨散落，風俗大改。吏民相告訐，〔四〕廣漢得以為耳目，盜賊以故不發，發又輒得。壹切治理，威名流聞，〔五〕及匈奴降者言匈奴中皆聞廣漢。","sentenceOrder":15},
  {"id":"s_work_han_thu_89_16","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　服虔曰：「受相訟牋記也。」師古曰：「擇其中可使者，獎厲而使之。」","sentenceOrder":16},
  {"id":"s_work_han_thu_89_17","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「遣知其事由某人發，故結怨咎也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_89_18","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　蘇林曰：「缿音項，如瓶，可受投書。」孟康曰：「筩，竹筩也，如今官受密事筩也。」師古曰：「缿，若今盛錢臧瓶，為小孔，可入而不可出。或缿或（筒）〔筩〕，皆為此制，而用受書，令投於其中也。筩音同。」","sentenceOrder":18},
  {"id":"s_work_han_thu_89_19","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「面相斥曰訐，音居乂反，又音居謁反。」","sentenceOrder":19},
  {"id":"s_work_han_thu_89_20","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　師古曰：「言諸事皆治理也。治音直吏反。一切，解在平紀。」","sentenceOrder":20},
  {"id":"s_work_han_thu_89_21","chapterId":"ch_work_han_thu_89","textTraditional":"本始二年，漢發五將軍擊匈奴，徵廣漢以太守將兵，屬蒲類將軍趙充國。從軍還，復用守京兆尹，滿歲為真。","sentenceOrder":21},
  {"id":"s_work_han_thu_89_22","chapterId":"ch_work_han_thu_89","textTraditional":"廣漢為二千石，以和顏接士，其尉薦待遇吏，殷勤甚備。〔一〕事推功善，歸之於下，曰：「某掾卿所為，非二千石所及。」行之發於至誠。吏見者皆輸寫心腹，無所隱匿，咸願為用，僵仆無所避〔二〕。廣漢聰明，皆知其能之所宜，盡力與否。其或負者，輒先聞知，風諭不改，乃收捕之，〔三〕無所逃，按之罪立具，即時伏辜。","sentenceOrder":22},
  {"id":"s_work_han_thu_89_23","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　如淳曰：「尉亦薦藉也。」師古曰：「尉薦謂安尉而薦達之。」","sentenceOrder":23},
  {"id":"s_work_han_thu_89_24","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「僵，偃也。仆，頓也。僵音薑。仆音赴。」","sentenceOrder":24},
  {"id":"s_work_han_thu_89_25","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「風讀曰諷。」","sentenceOrder":25},
  {"id":"s_work_han_thu_89_26","chapterId":"ch_work_han_thu_89","textTraditional":"廣漢為人彊力，天性精於吏職。見吏民，或夜不寢至旦。尤善為鉤距，以得事情。〔一〕鉤距者，設欲知馬賈，則先問狗，〔二〕已問羊，又問牛，然後及馬，參伍其賈，以類相準，則知馬之貴賤不失實矣。唯廣漢至精能行之，它人效者莫能及也。郡中盜賊，閭里輕俠，其根株窟穴所在，及吏受取請求銖兩之姦，皆知之。長安少年數人會窮里空舍謀共劫人，〔三〕坐語未訖，廣漢使吏捕治具服。富人蘇回為郎，二人劫之。〔四〕有頃，廣漢將吏到家，自立庭下，使長安丞襲奢叩堂戶曉賊，〔五〕曰：「京兆尹趙君謝兩卿，無得殺質，此宿衛臣也。釋質，束手，得善相遇，幸逢赦令，或時解脫。」〔六〕二人驚愕，又素聞廣漢名，即開戶出，下堂叩頭，廣漢跪謝曰：「幸全活郎，甚厚！」送獄，敕吏謹遇，給酒肉。至冬當出死，豫為調棺，給斂葬具，告語之，〔七〕皆曰：「死無所恨！」","sentenceOrder":26},
  {"id":"s_work_han_thu_89_27","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　蘇林曰：「鉤得其情，使不得去也。」晉灼曰：「鉤，致；距，閉也。使對者無疑，若不問而自知，眾莫覺所由以閉，其術為距也。」師古曰：「晉說是也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_89_28","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「賈讀曰價。」","sentenceOrder":28},
  {"id":"s_work_han_thu_89_29","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「窮里，里中之極隱處。」","sentenceOrder":29},
  {"id":"s_work_han_thu_89_30","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「劫取其身為質，令家將財物贖之。」","sentenceOrder":30},
  {"id":"s_work_han_thu_89_31","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　師古曰：「曉謂喻告之。」","sentenceOrder":31},
  {"id":"s_work_han_thu_89_32","chapterId":"ch_work_han_thu_89","textTraditional":"〔六〕　師古曰：「若束手自來，雖合處牢獄，當善處遇之，或逢赦令，則得免脫也。脫音吐活反。」","sentenceOrder":32},
  {"id":"s_work_han_thu_89_33","chapterId":"ch_work_han_thu_89","textTraditional":"〔七〕　師古曰：「調，辦具之也。棺斂，以棺衣斂尸也。調音徒釣反。棺音工喚反。斂音力贍反。」","sentenceOrder":33},
  {"id":"s_work_han_thu_89_34","chapterId":"ch_work_han_thu_89","textTraditional":"廣漢嘗記召湖都亭長，〔一〕湖都亭長西至界上，界上亭長戲曰：「至府，為我多謝問趙君。」〔二〕亭長既至，廣漢與語，問事畢，謂曰：「界上亭長寄聲謝我，〔三〕何以不為致問？」亭長叩頭服實有之。廣漢因曰：「還為吾謝界上亭長，勉思職事，有以自效，京兆不忘卿厚意。」其發姦擿伏如神，皆此類也。〔四〕","sentenceOrder":34},
  {"id":"s_work_han_thu_89_35","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「為書記以召之，若今之下符追呼人也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_89_36","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「多，厚也，言殷勤，若今人言千萬問訊矣。」","sentenceOrder":36},
  {"id":"s_work_han_thu_89_37","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「謝，告也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_89_38","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「擿謂動發之也，音它狄反。」","sentenceOrder":38},
  {"id":"s_work_han_thu_89_39","chapterId":"ch_work_han_thu_89","textTraditional":"廣漢奏請，令長安游徼獄吏秩百石，〔一〕其後百石吏皆差自重，不敢枉法妄繫留人。京兆政清，吏民稱之不容口。長老傳以為自漢興以來治京兆者莫能及。左馮翊、右扶風皆治長安中，〔二〕犯法者從跡喜過京兆界。〔三〕廣漢歎曰：「亂吾治者，常二輔也！誠令廣漢得兼治之，直差易耳。」","sentenceOrder":39},
  {"id":"s_work_han_thu_89_40","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「特增其秩以厲其行。」","sentenceOrder":40},
  {"id":"s_work_han_thu_89_41","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「治音直吏反。」","sentenceOrder":41},
  {"id":"s_work_han_thu_89_42","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「從讀曰縱。喜音許吏反。」","sentenceOrder":42},
  {"id":"s_work_han_thu_89_43","chapterId":"ch_work_han_thu_89","textTraditional":"初，大將軍霍光秉政，廣漢事光。及光薨後，廣漢心知微指〔一〕，發長安吏自將，與俱至光子博陸侯禹第，直突入其門，廋索私屠酤，椎破盧罌，斧斬其門關而去。〔二〕時光女為皇后，聞之，對帝涕泣。帝心善之，以召問廣漢。廣漢由是侵犯貴戚大臣。所居好用世吏子孫新進年少者，〔三〕專厲彊壯鋒氣，〔四〕見事風生，無所回避，〔五〕率多果敢之計，莫為持難。廣漢終以此敗。","sentenceOrder":43},
  {"id":"s_work_han_thu_89_44","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「識天子意也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_89_45","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「廋讀與搜同，謂入室求之也。盧所以居罌，罌所以盛酒也。盧解在食貨志、司馬相如傳。罌音於耕反。」","sentenceOrder":45},
  {"id":"s_work_han_thu_89_46","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「言舊吏家子孫而其人後出求進，又年少也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_89_47","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「蠭與鋒同，言鋒銳之氣。」","sentenceOrder":47},
  {"id":"s_work_han_thu_89_48","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　師古曰：「風生，言其速疾不可當也。回，曲也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_89_49","chapterId":"ch_work_han_thu_89","textTraditional":"初，廣漢客私酤酒長安巿，丞相（史）〔吏〕逐去（客）。客疑男子蘇賢言之，以語廣漢。廣漢使長安丞按賢，〔一〕尉史禹故劾賢為騎士屯霸上，不詣屯所，乏軍興。〔二〕賢父上書訟罪，告廣漢，事下有司覆治。禹坐要斬，請逮捕廣漢。有詔即訊，〔三〕辭服，會赦，貶秩一等。廣漢疑其邑子榮畜教令，〔四〕後以它法論殺畜。人上書言之，事下丞相御史，案驗甚急。廣漢使所親信長安人為丞相府門卒，令微司丞相門內不法事。地節三年七月中，丞相傅婢有過，自絞死。廣漢聞之，疑丞相夫人妒殺之府舍。而丞相奉齋酎入廟祠〔五〕，廣漢得此，使中郎趙奉壽風曉丞相，〔六〕欲以脅之，毋令窮正己事。丞相不聽，按驗愈急。廣漢欲告之，先問太史知星氣者，言今年當有戮死大臣，廣漢即上書告丞相罪。制曰：「下京兆尹治。」廣漢知事迫切，遂自將吏卒突入丞相府，召其夫人跪庭下受辭，〔七〕收奴婢十餘人去，責以殺婢事。丞相魏相上書自陳：「妻實不殺婢。廣漢數犯罪法不伏辜，以詐巧迫脅臣相，幸臣相寬不奏。願下明使者治廣漢所驗臣相家事。」事下廷尉治（罪），實丞相自以過譴笞傅婢，出至外弟乃死，不如廣漢言。司直蕭望之劾奏：「廣漢摧辱大臣，欲以劫持奉公，逆節傷化，不道。」宣帝惡之，下廣漢廷尉獄，又坐賊殺不辜，鞠獄故不以實，擅斥除騎士乏軍興數罪。〔八〕天子可其奏。吏民守闕號泣者數萬人，或言「臣生無益縣官，願代趙京兆死，使得牧養小民。」廣漢竟坐要斬。","sentenceOrder":49},
  {"id":"s_work_han_thu_89_50","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「按，致其罪也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_89_51","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　文穎曰：「尉史，尉部史也。禹，其名。」","sentenceOrder":51},
  {"id":"s_work_han_thu_89_52","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「令就問之，不追入獄也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_89_53","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「蘇賢同邑之子也。令音力成反。」","sentenceOrder":53},
  {"id":"s_work_han_thu_89_54","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　師古曰：「將酎祭宗廟而先絜齋也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_89_55","chapterId":"ch_work_han_thu_89","textTraditional":"〔六〕　師古曰：「風讀曰諷。」","sentenceOrder":55},
  {"id":"s_work_han_thu_89_56","chapterId":"ch_work_han_thu_89","textTraditional":"〔七〕　師古曰：「受其對辭也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_89_57","chapterId":"ch_work_han_thu_89","textTraditional":"〔八〕　師古曰：「斥除，逐遣之。」","sentenceOrder":57},
  {"id":"s_work_han_thu_89_58","chapterId":"ch_work_han_thu_89","textTraditional":"廣漢雖坐法誅，為京兆尹廉明，威制豪彊，小民得職。〔一〕百姓追思，歌之至今。","sentenceOrder":58},
  {"id":"s_work_han_thu_89_59","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「得職，各得其常所也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_89_60","chapterId":"ch_work_han_thu_89","textTraditional":"尹翁歸字子兄，〔一〕河東平陽人也，徙杜陵。翁歸少孤，與季父居。為獄小吏，曉習文法。喜擊劍，人莫能當。〔二〕是時大將軍霍光秉政，諸霍在平陽，奴客持刀兵入巿鬥變，吏不能禁，〔三〕及翁歸為巿吏，莫敢犯者。公廉不受餽，〔四〕百賈畏之。","sentenceOrder":60},
  {"id":"s_work_han_thu_89_61","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「兄讀曰況。」","sentenceOrder":61},
  {"id":"s_work_han_thu_89_62","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「喜音許吏反。」","sentenceOrder":62},
  {"id":"s_work_han_thu_89_63","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「變，亂也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_89_64","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「餽亦饋字也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_89_65","chapterId":"ch_work_han_thu_89","textTraditional":"後去吏居家。會田延年為河東太守，行縣至平陽，悉召故吏五六十人，延年親臨見，令有文者東，有武者西。閱數十人，次到翁歸，獨伏不肯起，對曰：「翁歸文武兼備，唯所施設。」功曹以為此吏倨敖不遜，〔一〕延年曰：「何傷？」遂召上辭問，〔二〕甚奇其對，除補卒史，便從歸府。案事發姦，窮竟事情，延年大重之，自以能不及翁歸，徙署督郵。河東二十八縣，分為兩部，閎孺部汾北，翁歸部汾南。〔三〕所舉應法，得其罪辜，屬縣長吏雖中傷，莫有怨者。舉廉為緱氏尉，歷守郡中，所居治理，〔四〕遷補都內令，舉廉為弘農都尉。","sentenceOrder":65},
  {"id":"s_work_han_thu_89_66","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「敖讀曰傲。」","sentenceOrder":66},
  {"id":"s_work_han_thu_89_67","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「為文辭而問之。」","sentenceOrder":67},
  {"id":"s_work_han_thu_89_68","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「閎，姓也，音宏。」","sentenceOrder":68},
  {"id":"s_work_han_thu_89_69","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「歷於郡中守丞尉之職也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_89_70","chapterId":"ch_work_han_thu_89","textTraditional":"徵拜東海太守，過辭廷尉于定國。定國家在東海，欲屬託邑子兩人，〔一〕令坐後堂待見。定國與翁歸語終日，不敢見其邑子。既去，定國乃謂邑子曰：「此賢將，汝不任事也，又不可干以私。」〔二〕","sentenceOrder":70},
  {"id":"s_work_han_thu_89_71","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「邑子，同邑人之子也。屬音之欲反。」","sentenceOrder":71},
  {"id":"s_work_han_thu_89_72","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「任，堪也。干，求也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_89_73","chapterId":"ch_work_han_thu_89","textTraditional":"翁歸治東海明察，郡中吏民賢不肖，及姦邪罪名盡知之。縣縣各有記籍。自聽其政，〔一〕有急名則少緩之；吏民小解，輒披籍〔二〕。縣縣收取黠吏豪民，案致其罪，高至於死。收取人必於秋冬課吏大會中，及出行縣，〔三〕不以無事時。其有所取也，以一警百，吏民皆服，恐懼改行自新。東海大豪郯許仲孫〔四〕為姦猾，亂吏治，郡中苦之。二千石欲捕者，輒以力勢變詐自解，終莫能制。翁歸至，論棄仲孫巿，一郡怖栗，莫敢犯禁。東海大治。","sentenceOrder":73},
  {"id":"s_work_han_thu_89_74","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「言決斷諸縣姦邪之事，不委令長。」","sentenceOrder":74},
  {"id":"s_work_han_thu_89_75","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　服虔曰：「披有罪者籍也。」師古曰：「解讀曰懈。」","sentenceOrder":75},
  {"id":"s_work_han_thu_89_76","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「於大會之中及行縣時則收取罪人，以警眾也。行音下更反。」","sentenceOrder":76},
  {"id":"s_work_han_thu_89_77","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「郯縣之豪，姓許名仲孫。」","sentenceOrder":77},
  {"id":"s_work_han_thu_89_78","chapterId":"ch_work_han_thu_89","textTraditional":"以高第入守右扶風，滿歲為真。選用廉平疾姦吏以為右職，接待以禮，好惡與同之；其負翁歸，罰亦必行。治如在東海故跡，姦邪罪名亦縣縣有名籍。盜賊發其比伍中，〔一〕翁歸輒召其縣長吏，曉告以姦黠主名，教使用類推跡盜賊所過抵，〔二〕類常如翁歸言，無有遺（託）〔脫〕。〔三〕緩於小弱，急於豪彊。豪彊有論罪，輸掌畜官，〔四〕使斫莝，〔五〕責以員程，不得取代。〔六〕不中程，輒笞督，〔七〕極者至以鈇自剄而死。〔八〕京師畏其威嚴，扶風大治，盜賊課常為三輔最。〔九〕","sentenceOrder":78},
  {"id":"s_work_han_thu_89_79","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「比謂左右相次者也。五家為伍，若今五保也。比音頻寐反。」","sentenceOrder":79},
  {"id":"s_work_han_thu_89_80","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「抵，歸也。所經過及所歸投也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_89_81","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「類猶率也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_89_82","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「論罪，決罪也。扶風畜牧所在，有苑師之屬，故曰掌畜官也。畜音許救反。」","sentenceOrder":82},
  {"id":"s_work_han_thu_89_83","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　師古曰：「莝，斬芻，音千臥反。」","sentenceOrder":83},
  {"id":"s_work_han_thu_89_84","chapterId":"ch_work_han_thu_89","textTraditional":"〔六〕　師古曰：「員，數也。計其人及日數為功程。」","sentenceOrder":84},
  {"id":"s_work_han_thu_89_85","chapterId":"ch_work_han_thu_89","textTraditional":"〔七〕　師古曰：「督，責也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_89_86","chapterId":"ch_work_han_thu_89","textTraditional":"〔八〕　師古曰：「鈇，斫莝刃也，音大夫之夫。使其斫莝，故因以莝刃自剄。而說者或謂為斧，或云劍鈇，皆失之也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_89_87","chapterId":"ch_work_han_thu_89","textTraditional":"〔九〕　師古曰：「言發則獲之，無有遺失，故為最也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_89_88","chapterId":"ch_work_han_thu_89","textTraditional":"翁歸為政雖任刑，其在公卿之間清絜自守，語不及私，然溫良嗛退，不以行能驕人，〔一〕甚得名譽於朝廷。視事數歲，元康四年病卒。家無餘財，天子賢之，制詔御史：「朕夙興夜寐，以求賢為右，〔二〕不異親疏近遠，務在安民而已。扶風翁歸廉平鄉正，〔三〕治民異等，早夭不遂，不得終其功業，朕甚憐之。其賜翁歸子黃金百斤，以奉其祭祠。」","sentenceOrder":88},
  {"id":"s_work_han_thu_89_89","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「嗛，古以為謙字。」","sentenceOrder":89},
  {"id":"s_work_han_thu_89_90","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「右猶上也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_89_91","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":91},
  {"id":"s_work_han_thu_89_92","chapterId":"ch_work_han_thu_89","textTraditional":"翁歸三子皆為郡守。少子岑歷位九卿，至後將軍。而閎孺亦至廣陵相，有治名。由是世稱田延年為知人。","sentenceOrder":92},
  {"id":"s_work_han_thu_89_93","chapterId":"ch_work_han_thu_89","textTraditional":"韓延壽字長公，燕人也，徙杜陵。少為郡文學。父義為燕郎中。剌王之謀逆也，義諫而死，燕人閔之。是時昭帝富於春秋，大將軍霍光持政，徵郡國賢良文學，問以得失。時魏相以文學對策，以為「賞罰所以勸善禁惡，政之本也。日者燕王為無道，〔一〕韓義出身彊諫，為王所殺。義無比干之親而蹈比干之節，〔二〕宜顯賞其子，以示天下，明為人臣之義。」光納其言，因擢延壽為諫大夫，遷淮陽太守。治甚有名，徙潁川。","sentenceOrder":93},
  {"id":"s_work_han_thu_89_94","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「日者猶言往日也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_89_95","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「殷之比干，紂之諸父，諫紂而死，故以為喻也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_89_96","chapterId":"ch_work_han_thu_89","textTraditional":"潁川多豪彊，難治，國家常為選良二千石。先是，趙廣漢為太守，患其俗多朋黨，故構會吏民，令相告訐，〔一〕一切以為聰明，潁川由是以為俗，民多怨讎。延壽欲更改之，教以禮讓，恐百姓不從，乃歷召郡中長老為鄉里所信向者數十人，設酒具食，親與相對，接以禮意，人人問以謠俗，民所疾苦，〔二〕為陳和睦親愛銷除怨咎之路。長老皆以為便，可施行，因與議定嫁娶喪祭儀品，略依古禮，不得過法。延壽於是令文學校官諸生皮弁執俎豆，〔三〕為吏民行喪嫁娶禮。百姓遵用其教，賣偶車馬下里偽物者，棄之巿道。〔四〕數年，徙為東郡太守，黃霸代延壽居潁川，霸因其跡而大治。","sentenceOrder":96},
  {"id":"s_work_han_thu_89_97","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「構，結也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_89_98","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「謠俗謂閭里歌謠，政教善惡也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_89_99","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「校亦學也，音效。」","sentenceOrder":99},
  {"id":"s_work_han_thu_89_100","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　張晏曰：「下里，地下蒿里偽物也。」師古曰：「偶謂木土為之，象真車馬之形也。偶，對也。棄其物於巿之道上也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_89_101","chapterId":"ch_work_han_thu_89","textTraditional":"延壽為吏，上禮義，好古教化，所至必聘其賢士，以禮待用，廣謀議，納諫爭；舉行喪讓財，表孝弟有行；修治學官，〔一〕春秋鄉（社）〔射〕，陳鍾鼓管弦，盛升降揖讓，及都試講武，設斧鉞旌旗，習射御之事。治城郭，收賦租，先明布告其日，以期會為大事，吏民敬畏趨鄉之。〔二〕又置正、五長，〔三〕相率以孝弟，不得舍姦人。〔四〕閭里仟佰有非常，吏輒聞知，姦人莫敢入界。其始若煩，後吏無追捕之苦，民無箠楚之憂，〔五〕皆便安之。接待下吏，恩施甚厚而約誓明。或欺負之者，延壽痛自刻責：「豈其負之，何以至此？」〔六〕吏聞者自傷悔，其縣尉至自刺死。及門下掾自剄，人救不殊，因瘖不能言。〔七〕延壽聞之，對掾史涕泣，遣吏毉治視，〔八〕厚復其家。〔九〕","sentenceOrder":101},
  {"id":"s_work_han_thu_89_102","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「學官謂庠序之舍也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_89_103","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「趨讀曰趣。鄉讀曰嚮。」","sentenceOrder":103},
  {"id":"s_work_han_thu_89_104","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「正若今之鄉正、里正也。五長，同伍之中置一人為長也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_89_105","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「舍，止也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_89_106","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　師古曰：「箠，杖也。楚，荊木也，即今之荊子也。箠音止橤反。」","sentenceOrder":106},
  {"id":"s_work_han_thu_89_107","chapterId":"ch_work_han_thu_89","textTraditional":"〔六〕　師古曰：「言豈我負之邪，其人何以為此事？」","sentenceOrder":107},
  {"id":"s_work_han_thu_89_108","chapterId":"ch_work_han_thu_89","textTraditional":"〔七〕　師古曰：「殊，絕也。以人救之，故身首不相絕也。瘖音於今反。」","sentenceOrder":108},
  {"id":"s_work_han_thu_89_109","chapterId":"ch_work_han_thu_89","textTraditional":"〔八〕　師古曰：「遣醫治之而吏護視之。」","sentenceOrder":109},
  {"id":"s_work_han_thu_89_110","chapterId":"ch_work_han_thu_89","textTraditional":"〔九〕　師古曰：「復音方目反。」","sentenceOrder":110},
  {"id":"s_work_han_thu_89_111","chapterId":"ch_work_han_thu_89","textTraditional":"延壽嘗出，臨上車，騎吏一人後至，敕功曹議罰白。〔一〕還至府門，門卒當車，願有所言。延壽止車問之，卒曰：「孝經曰：『資於事父以事君，而敬同，故母取其愛，而君取其敬，兼之者父也。』〔二〕今旦明府早駕，久駐未出，騎吏父來至府門，不敢入。騎吏聞之，趨走出謁，適會明府登車。以敬父而見罰，得毋虧大化乎？」延壽舉手輿中曰：「微子，太守不自知過。」〔三〕歸舍，召見門卒。卒本諸生，聞延壽賢，無因自達，故代卒，〔四〕延壽遂待用之。其納善聽諫，皆此類也。在東郡三歲，令行禁止，斷獄大減，為天下最。","sentenceOrder":111},
  {"id":"s_work_han_thu_89_112","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「令定其罪名而更白之。」","sentenceOrder":112},
  {"id":"s_work_han_thu_89_113","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「資，取也。取事父之道以事君，其敬則同也。母則極愛，君則極敬，不如父之兼敬愛也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_89_114","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「微，無也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_89_115","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「代人為卒也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_89_116","chapterId":"ch_work_han_thu_89","textTraditional":"入守左馮翊，滿歲稱職為真。歲餘，不肯出行縣。〔一〕丞掾數白：「宜循行郡中，覽觀民俗，考長吏治跡。」延壽曰：「縣皆有賢令長，督郵分明善惡於外，行縣恐無所益，重為煩擾。」〔二〕丞掾皆以為方春月，可壹出勸耕桑。延壽不得已，行縣至高陵，民有昆弟相與訟田自言，延壽大傷之，曰：「幸得備位，為郡表率，不能宣明教化，至令民有骨肉爭訟，既傷風化，重使賢長吏、嗇夫、三老、孝弟受其恥，〔三〕咎在馮翊，當先退。」是日移病不聽事，因入臥傳舍，閉閤思過。一縣莫知所為，令丞、嗇夫、三老亦皆自繫待罪。於是訟者宗族傳相責讓，此兩昆弟深自悔，皆自髡肉袒謝，願以田相移，終死不敢復爭。〔四〕延壽大喜，開閤延見，內酒肉與相對飲食，厲勉以意告鄉部，有以表勸悔過從善之民。〔五〕延壽乃起聽事，勞謝令丞以下，引見尉薦。郡中歙然，莫不傳相敕厲，不敢犯。延壽恩信周遍二十四縣，莫復以辭訟自言者。推其至誠，吏民不忍欺紿〔六〕。","sentenceOrder":116},
  {"id":"s_work_han_thu_89_117","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「行音下更反。其後亦同。」","sentenceOrder":117},
  {"id":"s_work_han_thu_89_118","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「重音直用反。」","sentenceOrder":118},
  {"id":"s_work_han_thu_89_119","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「重音直用反。」","sentenceOrder":119},
  {"id":"s_work_han_thu_89_120","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「移猶傳也。一說兄以讓弟，弟又讓之，故云相移。」","sentenceOrder":120},
  {"id":"s_work_han_thu_89_121","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　師古曰：「以其悔過從善，故令表顯以示勸勵。」","sentenceOrder":121},
  {"id":"s_work_han_thu_89_122","chapterId":"ch_work_han_thu_89","textTraditional":"〔六〕　師古曰：「紿，誑也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_89_123","chapterId":"ch_work_han_thu_89","textTraditional":"延壽代蕭望之為左馮翊，而望之遷御史大夫。侍謁者福為望之道延壽在東郡時放散官錢千餘萬。望之與丞相丙吉議，吉以為更大赦，不須考。〔一〕會御史當問（事）東郡，望之因令并問之。〔二〕延壽聞知，即部吏案校望之在馮翊時廩犧官錢放散百餘萬。廩犧吏掠治急，自引與望之為姦。延壽劾奏，移殿門禁止望之。望之自奏「職在總領天下，聞事不敢不問，而為延壽所拘持。」上由是不直延壽，各令窮竟所考。望之卒無事實，而望之遣御史案東郡，具得其事。延壽在東郡時，試騎士，〔三〕治飾兵車，畫龍虎朱爵。延壽衣黃紈方領，〔四〕駕四馬，傅總，建幢棨，〔五〕植羽葆，〔六〕鼓車歌車。〔七〕功曹引車，皆駕四馬，載棨戟。五騎為伍，分左右部，軍假司馬、千人持幢旁轂。〔八〕歌者先居射室，〔九〕望見延壽車，噭咷楚歌。〔一０〕延壽坐射室，騎吏持戟夾陛列立，騎士從者帶弓鞬羅後。〔一一〕令騎士兵車四面營陳，被甲鞮鞪居馬上，抱弩負籣〔一二〕。又使騎士戲車弄馬盜驂。〔一三〕延壽又取官銅物，候月蝕鑄作刀劍鉤鐔，放效尚方事。〔一四〕及取官錢帛，私假繇使吏。〔一五〕及治飾車甲三百萬以上。","sentenceOrder":123},
  {"id":"s_work_han_thu_89_124","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「更音工衡反。」","sentenceOrder":124},
  {"id":"s_work_han_thu_89_125","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「望之以延壽代己為馮翊，而有能名出己之上，故忌害之，欲陷以罪法。」","sentenceOrder":125},
  {"id":"s_work_han_thu_89_126","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「每歲大試也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_89_127","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　晉灼曰：「以黃色素作直領也。」師古曰：「衣音於既反。」","sentenceOrder":127},
  {"id":"s_work_han_thu_89_128","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　李奇曰：「戟也。」晉灼曰：「傅，著也。總，以緹繒飾鑣鎋也。建，立也。幢，旌幢也。棨，戟也。」師古曰：「幢，麾也。棨，有衣之戟也，其衣以赤黑繒為之。幢音大江反。棨音啟。」","sentenceOrder":128},
  {"id":"s_work_han_thu_89_129","chapterId":"ch_work_han_thu_89","textTraditional":"〔六〕　師古曰：「植亦立也。羽葆，聚翟尾為之，亦今纛之類也。植音常職反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_89_130","chapterId":"ch_work_han_thu_89","textTraditional":"〔七〕　孟康曰：「如今郊駕時車上鼓吹也。」師古曰：「郊駕，郊祀時備法駕也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_89_131","chapterId":"ch_work_han_thu_89","textTraditional":"〔八〕　師古曰：「旁音步浪反。」","sentenceOrder":131},
  {"id":"s_work_han_thu_89_132","chapterId":"ch_work_han_thu_89","textTraditional":"〔九〕　李奇曰：「都試射堂也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_89_133","chapterId":"ch_work_han_thu_89","textTraditional":"〔一０〕服虔曰：「噭音叫呼之叫。咷音滌濯之滌。」師古曰：「咷音它釣反。」","sentenceOrder":133},
  {"id":"s_work_han_thu_89_134","chapterId":"ch_work_han_thu_89","textTraditional":"〔一一〕師古曰：「鞬，弓衣也，音居言反。」","sentenceOrder":134},
  {"id":"s_work_han_thu_89_135","chapterId":"ch_work_han_thu_89","textTraditional":"〔一二〕如淳曰：「籣，盛弩箭箙也。」師古曰：「鞮鞪即兜鍪也。籣，盛弩矢者也，其形如木桶。鞮音丁奚反。鞪音莫侯反。」","sentenceOrder":135},
  {"id":"s_work_han_thu_89_136","chapterId":"ch_work_han_thu_89","textTraditional":"〔一三〕孟康曰：「戲車弄馬之技也。馳盜解驂馬，御者不見也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_89_137","chapterId":"ch_work_han_thu_89","textTraditional":"〔一四〕師古曰：「鉤亦兵器也，似劍而曲，所以鉤殺人也。鐔，劍喉也。又曰譚似劍而小陿。鐔音淫，又音尋。」","sentenceOrder":137},
  {"id":"s_work_han_thu_89_138","chapterId":"ch_work_han_thu_89","textTraditional":"〔一五〕師古曰：「假謂顧賃也。繇讀與徭同。」","sentenceOrder":138},
  {"id":"s_work_han_thu_89_139","chapterId":"ch_work_han_thu_89","textTraditional":"於是望之劾奏延壽上僭不道，又自陳：「前為延壽所奏，今復舉延壽罪，眾庶皆以臣懷不正之心，侵冤延壽。願下丞相、中二千石、博士議其罪。」事下公卿，皆以延壽前既無狀，後復誣愬典法大臣，欲以解罪，狡猾不道。天子惡之，延壽竟坐棄市。吏民數千人送至渭城，老小扶持車轂，爭奏酒炙。〔一〕延壽不忍距逆，人人為飲，計飲酒石餘。使掾史分謝送者：「遠苦吏民，延壽死無所恨。」百姓莫不流涕。","sentenceOrder":139},
  {"id":"s_work_han_thu_89_140","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「奏，進也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_89_141","chapterId":"ch_work_han_thu_89","textTraditional":"延壽三子皆為郎吏。且死，屬其子勿為吏，以己為戒。〔一〕子皆以父言去官不仕。至孫威，乃復為吏至將軍。威亦多恩信，能拊眾，得士死力。威又坐奢僭誅，延壽之風類也。","sentenceOrder":141},
  {"id":"s_work_han_thu_89_142","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「屬音之欲反。」","sentenceOrder":142},
  {"id":"s_work_han_thu_89_143","chapterId":"ch_work_han_thu_89","textTraditional":"張敞字子高，本河東平陽人也。祖父孺為上谷太守，徙茂陵。敞父福事孝武帝，官至光祿大夫。敞後隨宣帝徙杜陵。敞本以鄉有秩補太守卒史，〔一〕察廉為甘泉倉長，稍遷太僕丞，杜延年甚奇之〔二〕。會昌邑王徵即位，動作不由法度，敞上書諫曰：「孝昭皇帝蚤崩無嗣，〔三〕大臣憂懼，選賢聖承宗廟，東迎之日，唯恐屬車之行遲。〔四〕今天子以盛年初即位，天下莫不拭目傾耳，觀化聽風。〔五〕國輔大臣未褒，而昌邑小輦先遷，〔六〕此過之大者也。」後十餘日王賀廢，敞以切諫顯名，擢為豫州刺史。以數上事有忠言，宣帝徵敞為太中大夫，與于定國並平尚書事。以正違忤大將軍霍光，〔七〕而使主兵車出軍省減用度，〔八〕復出為函谷關都尉。宣帝初即位，廢王賀在昌邑，上心憚之，徙敞為山陽太守。","sentenceOrder":143},
  {"id":"s_work_han_thu_89_144","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「鄉有秩者，嗇夫之類也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_89_145","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「延年時為太僕也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_89_146","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「蚤，古早字。」","sentenceOrder":146},
  {"id":"s_work_han_thu_89_147","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「不欲斥乘輿，故但言屬車耳。屬音之欲反。」","sentenceOrder":147},
  {"id":"s_work_han_thu_89_148","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　師古曰：「言改易視聽，欲急聞見善政化也。拭音式。」","sentenceOrder":148},
  {"id":"s_work_han_thu_89_149","chapterId":"ch_work_han_thu_89","textTraditional":"〔六〕　李奇曰：「挽輦小臣也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_89_150","chapterId":"ch_work_han_thu_89","textTraditional":"〔七〕　師古曰：「守正不阿也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_89_151","chapterId":"ch_work_han_thu_89","textTraditional":"〔八〕　師古曰：「令其主節減軍興之用度也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_89_152","chapterId":"ch_work_han_thu_89","textTraditional":"久之，大將軍霍光薨，宣帝始親政事，封光兄孫山、雲皆為列侯，以光子禹為大司馬。頃之，山、雲以過歸第，霍氏諸婿親屬頗出補吏。敞聞之，上封事曰：「臣聞公子季友有功於魯，大夫趙衰有功於晉，〔一〕大夫田完有功於齊，皆疇其（官邑）〔庸〕，延及子孫，終後田氏篡齊，趙氏分晉，季氏顓魯。〔二〕故仲尼作春秋，跡盛衰，〔三〕譏世卿最甚。乃者大將軍決大計，安宗廟，定天下，功亦不細矣。夫周公七年耳，而大將軍二十歲，海內之命，斷於掌握。方其隆時，感動天地，侵迫陰陽，月朓日蝕，晝冥宵光，〔四〕地大震裂，火生地中，天文失度，祅祥變怪，不可勝記，皆陰類盛長，臣下顓制之所生也。朝臣宜有明言，曰陛下褒寵故大將軍以報功德足矣。間者輔臣顓政，貴戚太盛，君臣之分不明，請罷霍氏三侯皆就弟。及衛將軍張安世，宜賜几杖歸休，時存問召見，以列侯為天子師。明詔以恩不聽，群臣以義固爭而後許，天子必以陛下為不忘功德，而朝臣為知禮，霍氏世世無所患苦。今朝廷不聞直聲，〔五〕而令明詔自親其文，非策之得者也。〔六〕今兩侯以出，人情不相遠，以臣心度之，大司馬及其枝屬必有畏懼之心。夫近臣自危，非完計也，臣敞願於廣朝白發其端，直守遠郡，其路無由。〔七〕夫心之精微口不能言也，言之微眇書不能文也，〔八〕故伊尹五就桀，五就湯，〔九〕蕭相國薦淮陰累歲乃得通，況乎千里之外，因書文諭事指哉！唯陛下省察。」上甚善其計，然不徵也。","sentenceOrder":152},
  {"id":"s_work_han_thu_89_153","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「衰音初為反。」","sentenceOrder":153},
  {"id":"s_work_han_thu_89_154","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「顓與專同。下皆類此。」","sentenceOrder":154},
  {"id":"s_work_han_thu_89_155","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「著盛衰之跡。」","sentenceOrder":155},
  {"id":"s_work_han_thu_89_156","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「冥，闇也。宵，夜也。朓音它了反。」","sentenceOrder":156},
  {"id":"s_work_han_thu_89_157","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　師古曰：「言朝臣不進直言，以陳其事。」","sentenceOrder":157},
  {"id":"s_work_han_thu_89_158","chapterId":"ch_work_han_thu_89","textTraditional":"〔六〕　師古曰：「言失計也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_89_159","chapterId":"ch_work_han_thu_89","textTraditional":"〔七〕　師古曰：「直讀曰值。」","sentenceOrder":159},
  {"id":"s_work_han_thu_89_160","chapterId":"ch_work_han_thu_89","textTraditional":"〔八〕　師古曰：「眇，細也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_89_161","chapterId":"ch_work_han_thu_89","textTraditional":"〔九〕　師古曰：「孟子云『五就湯五就桀者，伊尹也』，言伊尹為湯臣，見貢於桀，桀不用而湯復貢之，如此者五也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_89_162","chapterId":"ch_work_han_thu_89","textTraditional":"久之，勃海、膠東盜賊並起，敞上書自請治之，曰：「臣聞忠孝之道，退家則盡心於親，進宦則竭力於君。夫小國中君猶有奮不顧身之臣，況於明天子乎！今陛下遊意於太平，勞精於政事，亹亹不舍晝夜。〔一〕群臣有司宜各竭力致身。山陽郡戶九萬三千，口五十萬以上，訖計盜賊未得者七十七人，〔二〕它課諸事亦略如此。臣敞愚駑，既無以佐思慮，久處閒郡，〔三〕身逸樂而忘國事，非忠孝之節也。伏聞膠東、勃海左右郡歲數不登，〔四〕盜賊並起，至攻官寺，篡囚徒，搜市朝，劫列侯。吏失綱紀，姦軌不禁。臣敞不敢愛身避死，唯明詔之所處，願盡力摧挫其暴虐，存撫其孤弱。事即有業，所至郡條奏其所由廢及所以興之狀。」〔五〕書奏，天子徵敞，拜膠東相，賜黃金三十斤。敞辭之官，自請治劇郡非賞罰無以勸善懲惡，〔六〕吏追捕有功效者，願得壹切比三輔尤異。〔七〕天子許之。","sentenceOrder":162},
  {"id":"s_work_han_thu_89_163","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「亹亹言勉強也。舍，息也。亹音尾。」","sentenceOrder":163},
  {"id":"s_work_han_thu_89_164","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「訖，盡也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_89_165","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「閒讀曰閑。」","sentenceOrder":165},
  {"id":"s_work_han_thu_89_166","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「年穀頻不孰也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_89_167","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　師古曰：「有業，言各得其所。」","sentenceOrder":167},
  {"id":"s_work_han_thu_89_168","chapterId":"ch_work_han_thu_89","textTraditional":"〔六〕　師古曰：「懲，止也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_89_169","chapterId":"ch_work_han_thu_89","textTraditional":"〔七〕　如淳曰：「壹切，權時也。趙廣漢奏請令長安游徼獄史秩百石，又循吏傳左馮翊有二百石卒史，此之謂尤異也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_89_170","chapterId":"ch_work_han_thu_89","textTraditional":"敞到膠東，明設購賞，開群盜令相捕斬除罪。吏追捕有功，上名尚書調補縣令者數十人。〔一〕由是盜賊解散，傳相捕斬。吏民歙然，〔二〕國中遂平。","sentenceOrder":170},
  {"id":"s_work_han_thu_89_171","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「調，選也，音徒釣反。」","sentenceOrder":171},
  {"id":"s_work_han_thu_89_172","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「歙音翕。」","sentenceOrder":172},
  {"id":"s_work_han_thu_89_173","chapterId":"ch_work_han_thu_89","textTraditional":"居頃之，王太后數出游獵，敞奏書諫曰：「臣聞秦王好淫聲，葉陽后為不聽鄭衛之樂；〔一〕楚嚴好田獵，樊姬為（之）不食鳥獸之肉。〔二〕口非惡旨甘，耳非憎絲竹也，所以抑心意，絕耆欲者〔三〕，將以率二君而全宗祀也。禮，君母出門則乘輜軿，下堂則從傅母，〔四〕進退則鳴玉佩，內飾則結綢繆。〔五〕此言尊貴所以自斂制，不從恣之義也。〔六〕今太后資質淑美，慈愛寬仁，諸侯莫不聞，而少以田獵縱欲為名，於以上聞，亦未宜也。〔七〕唯觀覽於往古，全行乎來今，令后姬得有所法則，下臣有所稱誦，臣敞幸甚！」書奏，太后止不復出。","sentenceOrder":173},
  {"id":"s_work_han_thu_89_174","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　孟康曰：「葉陽，秦昭王后也。」師古曰：「葉（陽）〔音〕式涉反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_89_175","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「樊姬，楚莊王姬也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_89_176","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「耆讀曰嗜。」","sentenceOrder":176},
  {"id":"s_work_han_thu_89_177","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「輜軿，衣車也。輜音甾，又音楚疑反。軿音步千反，又音步丁反。」","sentenceOrder":177},
  {"id":"s_work_han_thu_89_178","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　文穎曰：「謂衣衷結束綢繆也。」師古曰：「組紐之屬，所以自結固也。綢音直留反。繆音一虯反。」","sentenceOrder":178},
  {"id":"s_work_han_thu_89_179","chapterId":"ch_work_han_thu_89","textTraditional":"〔六〕　師古曰：「從謂曰縱。」","sentenceOrder":179},
  {"id":"s_work_han_thu_89_180","chapterId":"ch_work_han_thu_89","textTraditional":"〔七〕　師古曰：「上聞，聞於天子也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_89_181","chapterId":"ch_work_han_thu_89","textTraditional":"是時潁川太守黃霸以治行第一入守京兆尹。霸視事數月，不稱，罷歸潁川。於是制詔御史：「其以膠東相敞守京兆尹。」自趙廣漢誅後，比更守尹，〔一〕如霸等數人，皆不稱職。京師寖廢，〔二〕長安市偷盜尤多，百賈苦之。上以問敞，敞以為可禁。敞既視事，求問長安父老，偷盜酋長數人，〔三〕居皆溫厚，出從童騎，閭里以為長者。〔四〕敞皆召見責問，因貰其罪，把其宿負，〔五〕令致諸偷以自贖。〔六〕偷長曰：「今一旦召詣府，恐諸偷驚駭，願一切受署。」〔七〕敞皆以為吏，遣歸休。置酒，小偷悉來賀，且飲醉，偷長以赭汙其衣裾。〔八〕吏坐里閭閱出者，〔九〕汙赭輒收縛之，一日捕得數百人。窮治所犯，或一人百餘發，盡行法罰。由是枹鼓稀鳴，市無偷盜，〔一０〕天子嘉之。","sentenceOrder":181},
  {"id":"s_work_han_thu_89_182","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「比，頻也。更，歷也，音工衡反。」","sentenceOrder":182},
  {"id":"s_work_han_thu_89_183","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「寖，漸也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_89_184","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　應劭曰：「酋長，帥。」師古曰：「酋音才由反。」","sentenceOrder":184},
  {"id":"s_work_han_thu_89_185","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「溫厚，言富足也。童騎，以童奴為騎而自從也。」","sentenceOrder":185},
  {"id":"s_work_han_thu_89_186","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　師古曰：「貰，緩也。把，執持也，音步馬反。」","sentenceOrder":186},
  {"id":"s_work_han_thu_89_187","chapterId":"ch_work_han_thu_89","textTraditional":"〔六〕　師古曰：「致，至也，引至于官府。」","sentenceOrder":187},
  {"id":"s_work_han_thu_89_188","chapterId":"ch_work_han_thu_89","textTraditional":"〔七〕　師古曰：「自言願權補吏職也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_89_189","chapterId":"ch_work_han_thu_89","textTraditional":"〔八〕　師古曰：「赭，赤土也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_89_190","chapterId":"ch_work_han_thu_89","textTraditional":"〔九〕　師古曰：「閭謂里之門也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_89_191","chapterId":"ch_work_han_thu_89","textTraditional":"〔一０〕師古曰：「枹，擊鼓椎也，音桴，其字從木也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_89_192","chapterId":"ch_work_han_thu_89","textTraditional":"敞為人敏疾，賞罰分明，見惡輒取，時時越法縱舍，有足大者。〔一〕其治京兆，略循趙廣漢之跡。方略耳目，發伏禁姦，不如廣漢，然敞本治春秋，以經術自輔，其政頗雜儒雅，往往表賢顯善，不醇用誅罰，以此能自全，竟免於刑戮。","sentenceOrder":192},
  {"id":"s_work_han_thu_89_193","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　如淳曰：「有可貴異而大之者也。」晉灼曰：「越法縱舍，即足大者也。」師古曰：「晉說是也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_89_194","chapterId":"ch_work_han_thu_89","textTraditional":"京兆典京師，長安中浩穰，於三輔尤為劇。〔一〕郡國二千石以高弟入守，及為真，久者不過二三年，近者數月一歲，輒毀傷失名，以罪過罷。唯廣漢及敞為久任職。敞為京兆，朝廷每有大議，引古今，處便宜，公卿皆服，天子數從之。然敞無威儀，時罷朝會，過走馬章臺街，〔二〕使御吏驅，自以便面拊馬。〔三〕又為婦畫眉，長安中傳張京兆眉憮。〔四〕有司以奏敞。上問之，對曰：「臣聞閨房之內，夫婦之私，有過於畫眉者。」上愛其能，弗備責也。然終不得大位。","sentenceOrder":194},
  {"id":"s_work_han_thu_89_195","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「浩，大也。穰，盛也。言人眾之多也。穰音人掌反。」","sentenceOrder":195},
  {"id":"s_work_han_thu_89_196","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　孟康曰：「在長安中。」臣瓚曰：「在章臺下街也。」","sentenceOrder":196},
  {"id":"s_work_han_thu_89_197","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「便面，所以障面，蓋（車）〔扇〕之類也。不欲見人，以此自障面則得其便，故曰便面，亦曰屏面。今之沙門所持竹扇，上袤平而下圜，即古之便面也。音頻面反。」","sentenceOrder":197},
  {"id":"s_work_han_thu_89_198","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　應劭曰：「憮，大也。」孟康曰：「憮音詡。北方人謂媚好為詡畜。」蘇林曰：「憮音嫵。」師古曰：「本以好媚為稱，何說於大乎？蘇音是。」","sentenceOrder":198},
  {"id":"s_work_han_thu_89_199","chapterId":"ch_work_han_thu_89","textTraditional":"敞與蕭望之、于定國相善。始敞與定國俱以諫昌邑王超遷。定國為大夫平尚書事，敞出為刺史，時望之為大行丞。後望之先至御史大夫，定國後至丞相，敞終不過郡守。為京兆九歲，坐與光祿勳楊惲厚善，後惲坐大逆誅，公卿奏惲黨友，不宜處位，等比皆免，〔一〕而敞奏獨寢不下。〔二〕敞使（卒）〔賊〕捕掾絮舜有所案驗。〔三〕舜以敞劾奏當免，不肯為敞竟事，私歸其家。人或諫舜，舜曰：「吾為是公盡力多矣，今五日京兆耳，安能復案事？」敞聞舜語，即部吏收舜繫獄。是時冬月未盡數日，案事吏晝夜驗治舜，竟致其死事。舜當出死，敞使主簿持教告舜曰：「五日京兆竟何如？冬月已盡，延命乎？」〔四〕乃棄舜市。會立春，行冤獄使者出，〔五〕舜家載尸，并編敞教，〔六〕自言使者。使者奏敞賊殺不辜。天子薄其罪，〔七〕欲令敞得自便利，〔八〕即先下敞前坐楊惲不宜處位奏，免為庶人。敞免奏既下，詣闕上印綬，便從闕下亡命。〔九〕","sentenceOrder":199},
  {"id":"s_work_han_thu_89_200","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「比，例也，音必寐反。」","sentenceOrder":200},
  {"id":"s_work_han_thu_89_201","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「天子惜敞，故留所奏事不出。」","sentenceOrder":201},
  {"id":"s_work_han_thu_89_202","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　李奇曰：「絮音挐。」師古曰：「賊捕掾，主捕賊者也。絮，姓也，音女居反，又音人餘反。」","sentenceOrder":202},
  {"id":"s_work_han_thu_89_203","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「言汝不欲望延命乎？」","sentenceOrder":203},
  {"id":"s_work_han_thu_89_204","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　師古曰：「行音下更反。」","sentenceOrder":204},
  {"id":"s_work_han_thu_89_205","chapterId":"ch_work_han_thu_89","textTraditional":"〔六〕　師古曰：「編，聯也，聯之於章前也。」","sentenceOrder":205},
  {"id":"s_work_han_thu_89_206","chapterId":"ch_work_han_thu_89","textTraditional":"〔七〕　師古曰：「以其事為輕小也。」","sentenceOrder":206},
  {"id":"s_work_han_thu_89_207","chapterId":"ch_work_han_thu_89","textTraditional":"〔八〕　師古曰：「從輕法以免也。便音頻面反。」","sentenceOrder":207},
  {"id":"s_work_han_thu_89_208","chapterId":"ch_work_han_thu_89","textTraditional":"〔九〕　師古曰：「不還其本縣邑也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_89_209","chapterId":"ch_work_han_thu_89","textTraditional":"數月，京師吏民解弛，〔一〕枹鼓數起，而冀州部中有大賊。天子思敞功效，使使者即家在所召敞。〔二〕敞身被重劾，〔三〕及使者至，妻子家室皆泣惶懼，而敞獨笑曰：「吾身亡命為民，郡吏當就捕，今使者來，此天子欲用我也。」即裝隨使者詣公（書）〔車〕上（車）〔書〕曰：「臣前幸得備位列卿，待罪京兆，坐殺賊捕掾絮舜。舜本臣敞素所厚吏，數蒙恩貸，〔四〕以臣有章劾當免，受記考事，〔五〕便歸臥家，謂臣『五日京兆』，背恩忘義，傷化薄俗。臣竊以舜無狀，枉法以誅之。臣敞賊殺無辜，鞠獄故不直，雖伏明法，死無所恨。」天子引見敞，拜為冀州刺史。敞起亡命，復奉使典州。既到部，而廣川王國群輩不道，賊連發，不得。敞以耳目發起賊主名區處，〔六〕誅其渠帥。廣川王姬昆弟及王同族宗室劉調等通行為之囊橐，〔七〕吏逐捕窮窘，蹤跡皆入王宮。敞自將郡國吏，車數百兩，〔八〕圍守王宮，搜索調等，果得之殿屋重轑中。〔九〕敞傅吏皆捕格斷頭，〔一０〕縣其頭王宮門外。因劾奏廣川王。天子不忍致法，削其戶。敞居部歲餘，冀州盜賊禁止。守太原太守，滿歲為真，太原郡清。","sentenceOrder":209},
  {"id":"s_work_han_thu_89_210","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「弛，放也，音式爾反。」","sentenceOrder":210},
  {"id":"s_work_han_thu_89_211","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「就其所居處而召之。」","sentenceOrder":211},
  {"id":"s_work_han_thu_89_212","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「謂前有賊殺不辜之事。」","sentenceOrder":212},
  {"id":"s_work_han_thu_89_213","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「貸音土帶反。」","sentenceOrder":213},
  {"id":"s_work_han_thu_89_214","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　師古曰：「記，書也。若今之州縣為符教也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_89_215","chapterId":"ch_work_han_thu_89","textTraditional":"〔六〕　師古曰：「區謂居止之所也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_89_216","chapterId":"ch_work_han_thu_89","textTraditional":"〔七〕　師古曰：「言容止賊盜，若囊橐之盛物也。」","sentenceOrder":216},
  {"id":"s_work_han_thu_89_217","chapterId":"ch_work_han_thu_89","textTraditional":"〔八〕　師古曰：「一乘車為〔一〕兩也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_89_218","chapterId":"ch_work_han_thu_89","textTraditional":"〔九〕　蘇林曰：「轑，椽也。重轑，重棼中。」師古曰：「重棼即今之廊舍也，一邊虛為兩夏者也。轑音老。棼音扶分反。」","sentenceOrder":218},
  {"id":"s_work_han_thu_89_219","chapterId":"ch_work_han_thu_89","textTraditional":"〔一０〕師古曰：「傅讀曰附。言敞自監護吏而捕之。」","sentenceOrder":219},
  {"id":"s_work_han_thu_89_220","chapterId":"ch_work_han_thu_89","textTraditional":"頃之，宣帝崩。元帝初即位，待詔鄭朋薦敞先帝名臣，宜傅輔皇太子。上以問前將軍蕭望之，望之以為敞能吏，任治煩亂，材輕非師傅之器。天子使使者徵敞，欲以為左馮翊。會病卒。敞所誅殺太原吏吏家怨敞，隨至杜陵刺殺敞中子璜。敞三子官皆至都尉。","sentenceOrder":220},
  {"id":"s_work_han_thu_89_221","chapterId":"ch_work_han_thu_89","textTraditional":"初，敞為京兆尹，而敞弟武拜為梁相。是時梁王驕貴，民多豪彊，號為難治。敞問武：「欲何以治梁？」武敬憚兄，謙不肯言。敞使吏送至關，戒吏自問武。武應曰：「馭黠馬者利其銜策，梁國大都，吏民凋敝，且當以柱後惠文彈治之耳。」〔一〕秦時獄法吏冠柱後惠文，武意欲以刑法治梁。吏還道之，敞笑曰：「審如掾言，武必辨治梁矣。」武既到官，其治有跡，亦能吏也。","sentenceOrder":221},
  {"id":"s_work_han_thu_89_222","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　應劭曰：「柱後，以鐵為柱，今法冠是也，一名惠文冠。」晉灼曰：「漢注法冠也，一號柱後惠文，以纚裹鐵柱卷。秦制執法服，今御史服之，謂之解廌，一角。今冠兩角，以解廌為名耳。」師古曰：「晉說是也。纚即今方目紗也。纚音山爾反。卷音去權反。」","sentenceOrder":222},
  {"id":"s_work_han_thu_89_223","chapterId":"ch_work_han_thu_89","textTraditional":"敞孫竦，王莽時至郡守，封侯，博學文雅過於敞，然政事不及也。竦死，敞無後。","sentenceOrder":223},
  {"id":"s_work_han_thu_89_224","chapterId":"ch_work_han_thu_89","textTraditional":"王尊字子贛，〔一〕涿郡高陽人也。少孤，歸諸父，使牧羊澤中。尊竊學問，能史書。年十三，求為獄小吏。數歲，給事太守府，問詔書行事，尊無不對。〔二〕太守奇之，除補書佐，署守屬監獄〔三〕。久之，尊稱病去，事師郡文學官，〔四〕治尚書、論語，略通大義。復召署守屬治獄，為郡決曹史。數歲，以令舉幽州刺史從事〔五〕。而太守察尊廉，補遼西鹽官長。〔六〕數上書言便宜事，事下丞相御史。","sentenceOrder":224},
  {"id":"s_work_han_thu_89_225","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「贛音貢。」","sentenceOrder":225},
  {"id":"s_work_han_thu_89_226","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「以施行詔條問之，皆曉其事。」","sentenceOrder":226},
  {"id":"s_work_han_thu_89_227","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「署為守屬，令監獄主囚也。監音工銜反。」","sentenceOrder":227},
  {"id":"s_work_han_thu_89_228","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「郡有文學官，而尊事之以為師也。」","sentenceOrder":228},
  {"id":"s_work_han_thu_89_229","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　如淳曰：「漢儀注刺史得擇所部二千石卒史與從事。」","sentenceOrder":229},
  {"id":"s_work_han_thu_89_230","chapterId":"ch_work_han_thu_89","textTraditional":"〔六〕　如淳曰：「地理志遼西有鹽官。」","sentenceOrder":230},
  {"id":"s_work_han_thu_89_231","chapterId":"ch_work_han_thu_89","textTraditional":"初元中，舉直言，遷虢令，〔一〕轉守槐里，兼行美陽令事。春正月，美陽女子告假子不孝，曰：「兒常以我為妻，妒笞我。」尊聞之，遣吏收捕驗問，辭服。尊曰：「律無妻母之法，聖人所不忍書，此經所謂造獄者也。」〔二〕尊於是出坐廷上，取不孝子縣磔著樹，使騎吏五人張弓射殺之，吏民驚駭。","sentenceOrder":231},
  {"id":"s_work_han_thu_89_232","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　如淳曰：「本西虢也，屬右扶風。」","sentenceOrder":232},
  {"id":"s_work_han_thu_89_233","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　晉灼曰：「歐陽尚書有此造獄事也。」師古曰：「非常刑名，造殺戮之法。」","sentenceOrder":233},
  {"id":"s_work_han_thu_89_234","chapterId":"ch_work_han_thu_89","textTraditional":"後上行幸雍，過虢，尊供張如法而辦。〔一〕以高弟擢為安定太守。到官，出教告屬縣曰：「令長丞尉奉法守城，為民父母，〔二〕抑彊扶弱，宣恩廣澤，甚勞苦矣。太守以今日至府，願諸君卿勉力正身以率下。故行貪鄙，能變更者與為治。〔三〕明慎所職，毋以身試法。」又出教敕掾功曹「各自底厲，助太守為治。其不中用，趣自避退，毋久妨賢。〔四〕夫羽翮不修，則不可以致千里；闑內不理，無以整外。〔五〕府丞悉署吏行能，分別白之。賢為上，毋以富。賈人百萬，不足與計事。昔孔子治魯，七日誅少正卯，今太守視事已一月矣，五官掾張輔懷虎狼之心，貪汙不軌，〔六〕一郡之錢盡入輔家，然適足以葬矣。今將輔送獄，直符史詣閤下，從太守受其事。〔七〕丞戒之戒之！相隨入獄矣！」〔八〕輔繫獄數日死，盡得其狡猾不道，百萬姦臧。威震郡中，盜賊分散，入傍郡界。豪彊多誅傷伏辜者。坐殘賊免。","sentenceOrder":234},
  {"id":"s_work_han_thu_89_235","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「尊雖行美陽令，而就虢供張也。供音居用反。張音竹亮反。」","sentenceOrder":235},
  {"id":"s_work_han_thu_89_236","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「城謂縣城也。」","sentenceOrder":236},
  {"id":"s_work_han_thu_89_237","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「更，改也。有如此者太守乃共為治者也。」","sentenceOrder":237},
  {"id":"s_work_han_thu_89_238","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「趣讀曰促。」","sentenceOrder":238},
  {"id":"s_work_han_thu_89_239","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　師古曰：「闑，門橛也，音魚烈反。」","sentenceOrder":239},
  {"id":"s_work_han_thu_89_240","chapterId":"ch_work_han_thu_89","textTraditional":"〔六〕　師古曰：「汙，濁也。不軌，不修法制也。」","sentenceOrder":240},
  {"id":"s_work_han_thu_89_241","chapterId":"ch_work_han_thu_89","textTraditional":"〔七〕　師古曰：「直符史，若今之當直佐史也。」","sentenceOrder":241},
  {"id":"s_work_han_thu_89_242","chapterId":"ch_work_han_thu_89","textTraditional":"〔八〕　師古曰：「意丞教戒張輔，令其避罪，故以此言豫敕之。」","sentenceOrder":242},
  {"id":"s_work_han_thu_89_243","chapterId":"ch_work_han_thu_89","textTraditional":"起家，復為護羌將軍轉校尉，〔一〕護送軍糧委輸。而羌人反，絕轉道，〔二〕兵數萬圍尊。尊以千餘騎奔突羌賊。功未列上，〔三〕坐擅離部署，會赦，免歸家。","sentenceOrder":243},
  {"id":"s_work_han_thu_89_244","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「為校尉主轉運事，而屬護羌將軍。」","sentenceOrder":244},
  {"id":"s_work_han_thu_89_245","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「絕轉運之道。」","sentenceOrder":245},
  {"id":"s_work_han_thu_89_246","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「未列上於天子也。」","sentenceOrder":246},
  {"id":"s_work_han_thu_89_247","chapterId":"ch_work_han_thu_89","textTraditional":"涿郡太守徐明薦尊不宜久在閭巷，上以尊為郿令，〔一〕遷益州刺史。先是，琅邪王陽為益州刺史，行部至邛郲九折阪，〔二〕歎曰：「奉先人遺體，柰何數乘此險！」〔三〕後以病去。及尊為刺史，至其阪，問吏曰：「此非王陽所畏道邪？」吏對曰：「是。」尊叱其馭曰：「驅之！〔四〕王陽為孝子，王尊為忠臣。」尊居部二歲，懷來徼外，蠻夷歸附其威信。博士鄭寬中使行風俗，〔五〕舉奏尊治狀，遷為東平相。","sentenceOrder":247},
  {"id":"s_work_han_thu_89_248","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「右扶風之縣，音媚。」","sentenceOrder":248},
  {"id":"s_work_han_thu_89_249","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　應劭曰：「在蜀郡嚴道縣。」臣瓚曰：「郲，山名也。」師古曰：「郲音來。」","sentenceOrder":249},
  {"id":"s_work_han_thu_89_250","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「乘，登也。」","sentenceOrder":250},
  {"id":"s_work_han_thu_89_251","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「驅馬令疾行也。」","sentenceOrder":251},
  {"id":"s_work_han_thu_89_252","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　師古曰：「行音下更反。」","sentenceOrder":252},
  {"id":"s_work_han_thu_89_253","chapterId":"ch_work_han_thu_89","textTraditional":"是時，東平王以至親驕奢不奉法度，傅相連坐。〔一〕及尊視事，奉璽書至庭中，王未及出受詔，尊持璽書歸舍，食已乃還。致詔後，謁見王，太傅在前說相鼠之詩。〔二〕尊曰：「毋持布鼓過雷門！」〔三〕王怒，起入後宮。尊亦直趨出就舍。先是王數私出入，驅馳國中，與后姬家交通。尊到官，召敕廄長：「大王當從官屬，鳴和鸞乃出，自今有令駕小車，叩頭爭之，言相教不得。」後尊朝王，王復延請登堂。尊謂王曰：「尊來為相，人皆弔尊也，以尊不容朝廷，故見使相王耳。天下皆言王勇，顧但負貴，安能勇？〔四〕如尊乃勇耳。」王變色視尊，意欲格殺之，即好謂尊曰：「願觀相君佩刀。〔五〕」尊舉掖，顧謂傍侍郎：「前引佩刀視王，〔六〕王欲誣相拔刀向王邪？」王情得，〔七〕又雅聞尊高名，大為尊屈，酌酒具食，相對極驩。太后徵史奏尊〔八〕「為相倨慢不臣，王血氣未定，不能忍。愚誠恐母子俱死。今妾不得使王復見尊。陛下不留意，妾願先自殺，不忍見王之失義也。」尊竟坐免為庶人。大將軍王鳳奏請尊補軍中司馬，擢為司隸校尉。","sentenceOrder":253},
  {"id":"s_work_han_thu_89_254","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「前任傅相者頻坐以王得罪。」","sentenceOrder":254},
  {"id":"s_work_han_thu_89_255","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「相鼠，鄘風篇名，刺無禮之詩也。其辭曰：『相鼠有皮，人而無儀！人而無儀，不死何為！』相，視也。言視鼠有皮，雖處高顯之地，偷食苟得，不知廉恥，人無禮儀，亦與鼠同，不如速死也。」","sentenceOrder":255},
  {"id":"s_work_han_thu_89_256","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「雷門，會稽城門也，有大鼓。越擊此鼓，聲聞洛陽，故尊引之也。布鼓謂以布為鼓，故無聲。」","sentenceOrder":256},
  {"id":"s_work_han_thu_89_257","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「顧，念也。負，恃也。安，焉也。」","sentenceOrder":257},
  {"id":"s_work_han_thu_89_258","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　師古曰：「陽為好語也。」","sentenceOrder":258},
  {"id":"s_work_han_thu_89_259","chapterId":"ch_work_han_thu_89","textTraditional":"〔六〕　師古曰：「視讀曰示。」","sentenceOrder":259},
  {"id":"s_work_han_thu_89_260","chapterId":"ch_work_han_thu_89","textTraditional":"〔七〕　師古曰：「謂尊所測正得其情也。」","sentenceOrder":260},
  {"id":"s_work_han_thu_89_261","chapterId":"ch_work_han_thu_89","textTraditional":"〔八〕　張晏曰：「太后名也。」韋昭曰：「徵，召也。召東平史，令為奏也。」師古曰：「張說是也。徵史，太后之名，亦猶東平王后之稱謁也。」","sentenceOrder":261},
  {"id":"s_work_han_thu_89_262","chapterId":"ch_work_han_thu_89","textTraditional":"初，中書謁者令石顯貴幸，專權為姦邪。丞相匡衡、御史大夫張譚皆阿附畏事顯，不敢言。久之，元帝崩，成帝初即位，顯徙為中太僕，〔一〕不復典權。衡、譚乃奏顯舊惡，請免顯等。尊於是劾奏：「丞相衡、御史大夫譚位三公，典五常九德，〔二〕以總方略，壹統類，廣教化，美風俗為職。知中書謁者令顯等專權擅勢，大作威福，縱恣不制，無所畏忌，為海內患害，不以時（皆）〔白〕奏行罰，而阿諛曲從，附下罔上，懷邪迷國，無大臣輔政之義，皆不道，在赦令前。赦後，衡、譚舉奏顯，不自陳不忠之罪，而反揚著先帝任用傾覆之徒，妄言百官畏之，甚於主上。卑君尊臣，非所宜稱，失大臣體。又正月行幸曲臺，臨饗罷衛士，〔三〕衡與中二千石大鴻臚賞等會坐殿門下，衡南鄉，賞等西鄉。衡更為賞布東鄉席，〔四〕起立延賞坐，私語如食頃。衡知行臨，〔五〕百官共職，萬眾會聚，〔六〕而設不正之席，使下坐上，相比為小惠於公門之下，〔七〕動不中禮〔八〕，亂朝廷爵秩之位。衡又使官大奴入殿中，問行起居，還言漏上十四刻行臨到，衡安坐，不變色改容。無怵惕肅敬之心，驕慢不謹。皆不敬。」有詔勿治。於是衡慚懼，免冠謝罪，上丞相、侯印綬。天子以新即位，重傷大臣，〔九〕乃下御史丞問狀。劾奏尊「妄詆欺非謗赦前事，〔一０〕猥歷奏大臣，〔一一〕無正法，飾成小過，以塗汙宰相，摧辱公卿，輕薄國家，奉使不敬。」有詔左遷尊為高陵令，數月，以病免。","sentenceOrder":262},
  {"id":"s_work_han_thu_89_263","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「皇后之屬官。」","sentenceOrder":263},
  {"id":"s_work_han_thu_89_264","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「五常，仁、義、禮、智、信也。九德，寬而栗，柔而立，愿而恭，亂而敬，擾而毅，直而溫，簡而廉，剛而塞，強而義也。事見虞書皋陶謨也。」","sentenceOrder":264},
  {"id":"s_work_han_thu_89_265","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　如淳曰：「諸衛士更盡得代去，故天子自臨而饗之。」","sentenceOrder":265},
  {"id":"s_work_han_thu_89_266","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「鄉讀曰嚮也。」","sentenceOrder":266},
  {"id":"s_work_han_thu_89_267","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　如淳曰：「天子當臨饗士時。」","sentenceOrder":267},
  {"id":"s_work_han_thu_89_268","chapterId":"ch_work_han_thu_89","textTraditional":"〔六〕　師古曰：「共讀曰供。」","sentenceOrder":268},
  {"id":"s_work_han_thu_89_269","chapterId":"ch_work_han_thu_89","textTraditional":"〔七〕　師古曰：「比，周也，音頻寐反。」","sentenceOrder":269},
  {"id":"s_work_han_thu_89_270","chapterId":"ch_work_han_thu_89","textTraditional":"〔八〕　師古曰：「中，當也，音竹仲反。」","sentenceOrder":270},
  {"id":"s_work_han_thu_89_271","chapterId":"ch_work_han_thu_89","textTraditional":"〔九〕　師古曰：「重，難也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_89_272","chapterId":"ch_work_han_thu_89","textTraditional":"〔一０〕師古曰：「詆，毀也，音丁禮反。非讀曰誹也。」","sentenceOrder":272},
  {"id":"s_work_han_thu_89_273","chapterId":"ch_work_han_thu_89","textTraditional":"〔一一〕師古曰：「猥，多也，曲也。歷謂所奏非一人。」","sentenceOrder":273},
  {"id":"s_work_han_thu_89_274","chapterId":"ch_work_han_thu_89","textTraditional":"會南山群盜傰宗等數百人〔一〕為吏民害，拜故弘農太守傅剛為校尉，將跡射士千人逐捕，〔二〕歲餘不能禽。或說大將軍鳳：「賊數百人在轂下，〔三〕發軍擊之不能得，難以視四夷。〔四〕獨選賢京兆尹乃可。」於是鳳薦尊，徵為諫大夫，守京輔都尉，行京兆尹事。旬月間盜賊清。遷光祿大夫，守京兆尹，後為真，凡三歲。坐遇使者無禮。司隸遣假佐放奉詔書白尊發吏捕人，〔五〕放謂尊：「詔書所捕宜密。」尊曰：「治所公正，京兆善漏泄人事。」〔六〕放曰：「所捕宜今發吏。」〔七〕尊又曰：「詔書無京兆文，不當發吏。」及長安繫者三月間千人以上。尊出行縣，男子郭賜自言尊：〔八〕「許仲家十餘人共殺賜兄賞，公歸舍。」〔九〕吏不敢捕。尊行縣還，上奏曰：「彊不陵弱，各得其所，寬大之政行，和平之氣通。」御史大夫中奏尊暴虐不改，外為大言，倨嫚姍（嫌）〔上〕，〔一０〕威信日廢，不宜備位九卿。尊坐（先）〔免〕，吏民多稱惜之。","sentenceOrder":274},
  {"id":"s_work_han_thu_89_275","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　蘇林曰：「傰音朋。」晉灼曰：「音倍。」師古曰：「晉音是也。」","sentenceOrder":275},
  {"id":"s_work_han_thu_89_276","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「跡射，言能尋跡而射取之也。射音食亦反。」","sentenceOrder":276},
  {"id":"s_work_han_thu_89_277","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「在天子輦轂之下，明其逼近也。」","sentenceOrder":277},
  {"id":"s_work_han_thu_89_278","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「視讀曰示。」","sentenceOrder":278},
  {"id":"s_work_han_thu_89_279","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　蘇林曰：「胡公漢官假佐，取內郡善史書佐給諸府也。」","sentenceOrder":279},
  {"id":"s_work_han_thu_89_280","chapterId":"ch_work_han_thu_89","textTraditional":"〔六〕　師古曰：「謂司隸官屬為治所者，尊之也，若今謂使人為尚書矣。治音直吏反。」","sentenceOrder":280},
  {"id":"s_work_han_thu_89_281","chapterId":"ch_work_han_thu_89","textTraditional":"〔七〕　師古曰：「當即發也。」","sentenceOrder":281},
  {"id":"s_work_han_thu_89_282","chapterId":"ch_work_han_thu_89","textTraditional":"〔八〕　師古曰：「有冤事自言而與許仲相訟也。」","sentenceOrder":282},
  {"id":"s_work_han_thu_89_283","chapterId":"ch_work_han_thu_89","textTraditional":"〔九〕　師古曰：「公然而歸，無所避畏者。」","sentenceOrder":283},
  {"id":"s_work_han_thu_89_284","chapterId":"ch_work_han_thu_89","textTraditional":"〔一０〕師古曰：「姍，古訕字也。訕，誹也，音所諫反，又音刪。」","sentenceOrder":284},
  {"id":"s_work_han_thu_89_285","chapterId":"ch_work_han_thu_89","textTraditional":"湖三老公乘興等〔一〕上書訟尊治京兆功效日著。「往者南山盜賊阻山橫行，剽劫良民，殺奉法吏，道路不通，城門至以警戒。步兵校尉使逐捕，暴師露眾，曠日煩費，不能禽制。二卿坐黜，〔二〕群盜寖強，吏氣傷沮，〔三〕流聞四方，為國家憂。當此之時，有能捕斬，不愛金爵重賞。關內侯寬中使問所徵故司隸校尉王尊捕群盜方略，拜為諫大夫，守京輔都尉，行京兆尹事。尊盡節勞心，夙夜思職，卑體下士，〔四〕厲奔北之吏，起沮傷之氣，二旬之間，大黨震壞，渠率效首。〔五〕賊亂蠲除，民反農業，拊循貧弱，鉏耘豪彊。長安宿豪大猾東市賈萬、城西萬章、翦張禁、酒趙放、杜陵楊章等皆通邪結黨，挾養姦軌，上干王法，下亂吏治，并兼役使，侵漁小民，為百姓豺狼。更數二千石，二十年莫能禽討，〔七〕尊以正法案誅，皆伏其辜。姦邪銷釋，吏民說服。〔八〕尊撥劇整亂，誅暴禁邪，皆前所稀有，名將所不及。雖拜為真，未有殊絕褒賞加於尊身。今御史大夫奏尊『傷害陰陽，為國家憂，無承用詔書之意，靖言庸違，象龔滔天。』〔九〕原其所以，出御史丞楊輔，故為尊書佐，素行陰賊，惡口不信，〔一０〕好以刀筆陷人於法。輔常醉過尊大奴利家，利家捽搏其頰，〔一一〕兄子閎拔刀欲剄之。輔以故深怨疾毒，欲傷害尊。疑輔內懷怨恨，外依公事，建畫為此議，傅致奏文，〔一二〕浸潤加誣，以復私怨。〔一三〕昔白起為秦將，東破韓、魏，南拔郢都，應侯譖之，賜死杜郵；〔一四〕吳起為魏守西河，而秦、韓不敢犯，讒人間焉，斥逐奔楚。〔一五〕秦聽浸潤以誅良將，魏信讒言以逐賢守，此皆偏聽不聰，失人之患也。臣等竊痛傷尊修身絜己，砥節首公〔一六〕，刺譏不憚將相，誅惡不避豪彊，誅不制之賊，解國家之憂，功（岩）〔著〕職修，威信不廢，誠國家爪牙之吏，折衝之臣，今一旦無辜制於仇人之手，傷於詆欺之文，上不得以功除罪，下不得蒙棘木之聽，〔一七〕獨掩怨讎之偏奏，被共工之大惡，〔一八〕無所陳怨愬罪。尊以京師廢亂，群盜並興，選賢徵用，起家為卿，賊亂既除，豪猾伏辜，即以佞巧廢黜。一尊之身，三期之間，乍賢乍佞，豈不甚哉！〔一九〕孔子曰：『愛之欲其生，惡之欲其死，是惑也。』『浸潤之譖不行焉，可謂明矣。』〔二０〕願下公卿大夫博士議郎，定尊素行。夫人臣而傷害陰陽，死誅之罪也；靖言庸違，放殛之刑也〔二一〕。審如御史章，尊乃當伏觀闕之誅，〔二二〕放於無人之域，不得苟免。〔二三〕及任舉尊者，當獲選舉之辜，不可但已。〔二四〕即不如章，飾文深詆以愬無罪，〔二五〕亦宜有誅，以懲讒賊之口，絕詐欺之（俗）〔路〕。〔二六〕唯明主參詳，使白黑分別。」書奏，天子復以尊為徐州刺史，遷東郡太守。","sentenceOrder":285},
  {"id":"s_work_han_thu_89_286","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「湖，縣名也，今虢州湖城縣取其名。」","sentenceOrder":286},
  {"id":"s_work_han_thu_89_287","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　如淳曰：「三輔皆秩中二千石，號為卿也。即前京兆尹王昌貶為鴈門太守，甄遵河內太守也。」","sentenceOrder":287},
  {"id":"s_work_han_thu_89_288","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「寖，益也。沮，壞也，音才汝反。」","sentenceOrder":288},
  {"id":"s_work_han_thu_89_289","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「下音胡嫁反。」","sentenceOrder":289},
  {"id":"s_work_han_thu_89_290","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　師古曰：「效，致也，斬其首而致之也。」","sentenceOrder":290},
  {"id":"s_work_han_thu_89_291","chapterId":"ch_work_han_thu_89","textTraditional":"〔六〕　蘇林曰：「萬音矩。」晉灼曰：「翦張禁，酒趙放，此二人作翦、作酒之家。」","sentenceOrder":291},
  {"id":"s_work_han_thu_89_292","chapterId":"ch_work_han_thu_89","textTraditional":"〔七〕　師古曰：「更，歷也，音工衡反。」","sentenceOrder":292},
  {"id":"s_work_han_thu_89_293","chapterId":"ch_work_han_thu_89","textTraditional":"〔八〕　師古曰：「釋，解也，音懌。說讀曰悅。」","sentenceOrder":293},
  {"id":"s_work_han_thu_89_294","chapterId":"ch_work_han_thu_89","textTraditional":"〔九〕　師古曰：「引虞書堯典之辭也。靖，治也。庸，用也。違，僻也。滔，漫也。謂其言假託於治，實用違僻，貌象恭敬，過惡漫天也。漫音莫干反。一曰，滔，漫也。」","sentenceOrder":294},
  {"id":"s_work_han_thu_89_295","chapterId":"ch_work_han_thu_89","textTraditional":"〔一０〕師古曰：「謂其口（而惡）〔惡而〕心不信也。」","sentenceOrder":295},
  {"id":"s_work_han_thu_89_296","chapterId":"ch_work_han_thu_89","textTraditional":"〔一一〕師古曰：「捽，持頭也，音才兀反。搏，擊也。」","sentenceOrder":296},
  {"id":"s_work_han_thu_89_297","chapterId":"ch_work_han_thu_89","textTraditional":"〔一二〕師古曰：「建立謀畫此議也。傅讀曰附，謂益其事而引致於罪狀。」","sentenceOrder":297},
  {"id":"s_work_han_thu_89_298","chapterId":"ch_work_han_thu_89","textTraditional":"〔一三〕師古曰：「浸潤猶漸染也。復，報也。」","sentenceOrder":298},
  {"id":"s_work_han_thu_89_299","chapterId":"ch_work_han_thu_89","textTraditional":"〔一四〕師古曰：「應侯，范雎也。杜郵，地名，在咸陽也。」","sentenceOrder":299},
  {"id":"s_work_han_thu_89_300","chapterId":"ch_work_han_thu_89","textTraditional":"〔一五〕師古曰：「間音工莧反。」","sentenceOrder":300},
  {"id":"s_work_han_thu_89_301","chapterId":"ch_work_han_thu_89","textTraditional":"〔一六〕師古曰：「砥，厲也。首，向也。砥音指。首音式救反。」","sentenceOrder":301},
  {"id":"s_work_han_thu_89_302","chapterId":"ch_work_han_thu_89","textTraditional":"〔一七〕張晏曰：「周禮三槐九棘，公卿於下聽訟。」","sentenceOrder":302},
  {"id":"s_work_han_thu_89_303","chapterId":"ch_work_han_thu_89","textTraditional":"〔一八〕臣瓚曰：「共工，官名，堯時諸侯，舜流之於幽州也。」","sentenceOrder":303},
  {"id":"s_work_han_thu_89_304","chapterId":"ch_work_han_thu_89","textTraditional":"〔一九〕師古曰：「期，年也，音基。」","sentenceOrder":304},
  {"id":"s_work_han_thu_89_305","chapterId":"ch_work_han_thu_89","textTraditional":"〔二０〕師古曰：「論語稱孔子之言。」","sentenceOrder":305},
  {"id":"s_work_han_thu_89_306","chapterId":"ch_work_han_thu_89","textTraditional":"〔二一〕師古曰：「殛，誅也，音居力反。」","sentenceOrder":306},
  {"id":"s_work_han_thu_89_307","chapterId":"ch_work_han_thu_89","textTraditional":"〔二二〕張晏曰：「孔子誅少正卯於兩觀之間。」","sentenceOrder":307},
  {"id":"s_work_han_thu_89_308","chapterId":"ch_work_han_thu_89","textTraditional":"〔二三〕師古曰：「非止合免官而已也。」","sentenceOrder":308},
  {"id":"s_work_han_thu_89_309","chapterId":"ch_work_han_thu_89","textTraditional":"〔二四〕師古曰：「但，徒也，空也。已，止也。不可空然而止也。」","sentenceOrder":309},
  {"id":"s_work_han_thu_89_310","chapterId":"ch_work_han_thu_89","textTraditional":"〔二五〕師古曰：「詆，毀也。」","sentenceOrder":310},
  {"id":"s_work_han_thu_89_311","chapterId":"ch_work_han_thu_89","textTraditional":"〔二六〕師古曰：「懲，（愴）〔創〕也。」","sentenceOrder":311},
  {"id":"s_work_han_thu_89_312","chapterId":"ch_work_han_thu_89","textTraditional":"久之，河水盛溢，泛浸瓠子金隄，老弱奔走，恐水大決為害。尊躬率吏民，投沈白馬，〔一〕祀水神河伯。尊親執圭璧，使巫策祝，請以身填金隄，〔二〕因止宿，廬居隄上。吏民數千萬人爭叩頭救止尊，尊終不肯去。及水盛隄壞，吏民皆奔走，唯一主簿泣在尊旁，立不動。而水波稍卻迴還。吏民嘉壯尊之勇節，白馬三老朱英等奏其狀。下有司考，皆如言。於是制詔御史：「東郡河水盛長，毀壞金隄，未決三尺，百姓惶恐奔走。太守身當水衝，履咫尺之難，不避危殆，以安眾心，吏民復還就作，水不為災，朕甚嘉之。秩尊中二千石，加賜黃金二十斤。」","sentenceOrder":312},
  {"id":"s_work_han_thu_89_313","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「以祭水也。」","sentenceOrder":313},
  {"id":"s_work_han_thu_89_314","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「填，塞也，音大賢反。」","sentenceOrder":314},
  {"id":"s_work_han_thu_89_315","chapterId":"ch_work_han_thu_89","textTraditional":"數歲，卒官，吏民紀之。尊子伯亦為京兆尹，坐耎弱不勝任免。","sentenceOrder":315},
  {"id":"s_work_han_thu_89_316","chapterId":"ch_work_han_thu_89","textTraditional":"王章字仲卿，泰山鉅平人也。少以文學為官，稍遷至諫大夫，在朝廷名敢直言。元帝初，擢為左曹中郎將，與御史中丞陳咸相善，共毀中書令石顯，為顯所陷，咸減死髡，章免官。成帝立，徵章為諫大夫，遷司隸校尉，大臣貴戚敬憚之。王尊免後，代者不稱職，章以選為京兆尹。時帝舅大將軍王鳳輔政，章雖為鳳所舉，非鳳專權，不親附鳳。會日有蝕之，章奏封事，召見，言鳳不可任用，宜更選忠賢。上初納受章言，後不忍退鳳。章由是見疑，遂為鳳所陷，罪至大逆。語在元后傳。","sentenceOrder":316},
  {"id":"s_work_han_thu_89_317","chapterId":"ch_work_han_thu_89","textTraditional":"初，章為諸生學長安，獨與妻居。章疾病，無被，臥牛衣中〔一〕，與妻決，涕泣。〔二〕其妻呵怒之曰：「仲卿！京師尊貴在朝廷人誰踰仲卿者？今疾病困厄，不自激卬，〔三〕乃反涕泣，何鄙也！」","sentenceOrder":317},
  {"id":"s_work_han_thu_89_318","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　師古曰：「牛衣，編亂麻為之，即今俗呼為龍具者。」","sentenceOrder":318},
  {"id":"s_work_han_thu_89_319","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「自謂將死，故辭決。」","sentenceOrder":319},
  {"id":"s_work_han_thu_89_320","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　如淳曰：「激厲抗揚之意也。」師古曰：「卬讀曰仰。仰頭為健。」","sentenceOrder":320},
  {"id":"s_work_han_thu_89_321","chapterId":"ch_work_han_thu_89","textTraditional":"後章仕宦歷位，及為京兆，欲上封事，妻又止之曰：「人當知足，獨不念牛衣中涕泣時耶？」章曰：「非女子所知也。」書遂上，果下廷尉獄，妻子皆收繫。章小女年可十二，夜起號哭曰：「平生獄上呼囚，（素）〔數〕常至九，今八而止。〔一〕我君（數）〔素〕剛，先死者必君。」明日問之，章果死。妻子皆徙合浦。","sentenceOrder":321},
  {"id":"s_work_han_thu_89_322","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　張晏曰：「平生，先時也。獄卒夜閱囚時有九人，常呼問九人。今八人便止，知一人死也。」","sentenceOrder":322},
  {"id":"s_work_han_thu_89_323","chapterId":"ch_work_han_thu_89","textTraditional":"大將軍鳳薨後，弟成都侯商復為大將軍輔政，白上還章妻子故郡。其家屬皆完具，采珠致產數百萬，時蕭育為泰山太守，皆令贖還故田宅。","sentenceOrder":323},
  {"id":"s_work_han_thu_89_324","chapterId":"ch_work_han_thu_89","textTraditional":"章為京兆二歲，死不以其罪，眾庶冤紀之，號為三王。王駿自有傳，駿即王陽子也。","sentenceOrder":324},
  {"id":"s_work_han_thu_89_325","chapterId":"ch_work_han_thu_89","textTraditional":"贊曰：自孝武置左馮翊、右扶風、京兆尹，而吏民為之語曰：「前有趙、張，後有三王。」然劉向獨序趙廣漢、尹翁歸、韓延壽，馮商傳王尊，揚雄亦如之。〔一〕廣漢聰明，下不能欺，延壽厲善，所居移風，然皆訐上不信，以失身墮功。〔二〕翁歸抱公絜己，為近世表。張敞衎衎，履忠進言，〔三〕緣飾儒雅，刑罰必行，縱赦有度，條教可觀，然被輕惰之名。〔四〕王尊文武自將，〔五〕所在必發，譎詭不經，好為大言。王章剛直守節，不量輕重，以陷刑戮，妻子流遷，哀哉！","sentenceOrder":325},
  {"id":"s_work_han_thu_89_326","chapterId":"ch_work_han_thu_89","textTraditional":"〔一〕　張晏曰：「劉向作新序，不道王尊。馮商續史記，為作傳。雄作法言，亦論其美也。」","sentenceOrder":326},
  {"id":"s_work_han_thu_89_327","chapterId":"ch_work_han_thu_89","textTraditional":"〔二〕　師古曰：「墮，毀也，音火規反。」","sentenceOrder":327},
  {"id":"s_work_han_thu_89_328","chapterId":"ch_work_han_thu_89","textTraditional":"〔三〕　師古曰：「衎衎，彊敏之貌也，音口翰反。」","sentenceOrder":328},
  {"id":"s_work_han_thu_89_329","chapterId":"ch_work_han_thu_89","textTraditional":"〔四〕　師古曰：「媠，古惰字也。謂走馬拊馬及畫眉。」","sentenceOrder":329},
  {"id":"s_work_han_thu_89_330","chapterId":"ch_work_han_thu_89","textTraditional":"〔五〕　師古曰：「將，助也。」","sentenceOrder":330},
  {"id":"s_work_han_thu_89_331","chapterId":"ch_work_han_thu_89","textTraditional":"校勘記","sentenceOrder":331},
  {"id":"s_work_han_thu_89_332","chapterId":"ch_work_han_thu_89","textTraditional":"三一九九頁一二行　方上〔解〕在張湯傳。　宋祁說「方上」下當有「解」字。按景祐本有「解」字。","sentenceOrder":332},
  {"id":"s_work_han_thu_89_333","chapterId":"ch_work_han_thu_89","textTraditional":"三二０一頁　五行　或缿或（筒）〔筩〕，　景祐、汲古、殿、局本都作「筩」，此誤。","sentenceOrder":333},
  {"id":"s_work_han_thu_89_334","chapterId":"ch_work_han_thu_89","textTraditional":"三二０四頁一三行　丞相（史）〔吏〕逐去（客）。　景祐本「史」作「吏」。景祐、殿本都無「客」字。","sentenceOrder":334},
  {"id":"s_work_han_thu_89_335","chapterId":"ch_work_han_thu_89","textTraditional":"三二０五頁　七行　事下廷尉治（罪），　景祐本無「罪」字。王念孫說「罪」字後人所加。","sentenceOrder":335},
  {"id":"s_work_han_thu_89_336","chapterId":"ch_work_han_thu_89","textTraditional":"三二０八頁一０行　類常如翁歸言，無有遺（託）〔脫〕。　景祐、殿、局本都作「脫」。王先謙說作「脫」是。","sentenceOrder":336},
  {"id":"s_work_han_thu_89_337","chapterId":"ch_work_han_thu_89","textTraditional":"三二一一頁　七行　春秋鄉（社）〔射〕，　景祐、殿本都作「射」。王先謙說作「射」是。","sentenceOrder":337},
  {"id":"s_work_han_thu_89_338","chapterId":"ch_work_han_thu_89","textTraditional":"三二一四頁　三行　會御史當問（事）東郡，　景祐本無「事」字。","sentenceOrder":338},
  {"id":"s_work_han_thu_89_339","chapterId":"ch_work_han_thu_89","textTraditional":"三二一七頁一二行　皆疇其（官邑）〔庸〕，　景祐、殿本都作「庸」。","sentenceOrder":339},
  {"id":"s_work_han_thu_89_340","chapterId":"ch_work_han_thu_89","textTraditional":"三二二０頁　八行　樊姬為（之）不食鳥獸之肉。　景祐本無「之」字。","sentenceOrder":340},
  {"id":"s_work_han_thu_89_341","chapterId":"ch_work_han_thu_89","textTraditional":"三二二０頁一三行　葉（陽）〔音〕式涉反。　景祐、殿本都作「音」。","sentenceOrder":341},
  {"id":"s_work_han_thu_89_342","chapterId":"ch_work_han_thu_89","textTraditional":"三二二三頁　四行　蓋（車）〔扇〕之類也。　景祐、殿本都作「扇」，此誤。","sentenceOrder":342},
  {"id":"s_work_han_thu_89_343","chapterId":"ch_work_han_thu_89","textTraditional":"三二二三頁一一行　（卒）〔賊〕捕掾，　景祐、殿本都作「賊」，此誤。","sentenceOrder":343},
  {"id":"s_work_han_thu_89_344","chapterId":"ch_work_han_thu_89","textTraditional":"三二二四頁一四行　詣公（書）〔車〕上（車）〔書〕　景祐、殿本都作「詣公車上書」，此誤倒。","sentenceOrder":344},
  {"id":"s_work_han_thu_89_345","chapterId":"ch_work_han_thu_89","textTraditional":"三二三九頁　七行　（素）〔數〕常至九，今八而止。我君（數）〔素〕剛，　景祐、殿本上「素」作「數」，下「數」作「素」，此互訛。","sentenceOrder":345},
  {"id":"s_work_han_thu_89_346","chapterId":"ch_work_han_thu_89","textTraditional":"三二二五頁一四行　一乘車為〔一〕兩也。　景祐本有「一」字。","sentenceOrder":346},
  {"id":"s_work_han_thu_89_347","chapterId":"ch_work_han_thu_89","textTraditional":"三二三一頁一一行　不以時（皆）〔白〕奏行罰，　景祐、殿、局本都作「白」，此誤。","sentenceOrder":347},
  {"id":"s_work_han_thu_89_348","chapterId":"ch_work_han_thu_89","textTraditional":"三二三三頁一０行　倨嫚姍（嫌）〔上〕，　景祐、汲古、殿、局本都作「上」，此誤。","sentenceOrder":348},
  {"id":"s_work_han_thu_89_349","chapterId":"ch_work_han_thu_89","textTraditional":"三二三三頁一０行　尊坐（先）〔免〕。　景祐、殿、局本都作「免」，此誤。","sentenceOrder":349},
  {"id":"s_work_han_thu_89_350","chapterId":"ch_work_han_thu_89","textTraditional":"三二三五頁　八行　功（岩）〔著〕職修，　景祐、殿、局本都作「著」，此誤。","sentenceOrder":350},
  {"id":"s_work_han_thu_89_351","chapterId":"ch_work_han_thu_89","textTraditional":"三二三六頁　一行　絕詐欺之（俗）〔路〕。　景祐、殿本都作「路」。王先謙說作「路」是。","sentenceOrder":351},
  {"id":"s_work_han_thu_89_352","chapterId":"ch_work_han_thu_89","textTraditional":"三二三六頁一三行　謂其口（而惡）〔惡而〕心不信也。　景祐、殿本都作「惡而」。王先謙說作「惡而」是。","sentenceOrder":352},
  {"id":"s_work_han_thu_89_353","chapterId":"ch_work_han_thu_89","textTraditional":"三二三七頁一二行　懲，（愴）〔創〕也。　景祐本作「創」，他本都誤。","sentenceOrder":353},
  {"id":"s_work_han_thu_90_1","chapterId":"ch_work_han_thu_90","textTraditional":"蓋寬饒字次公，魏郡人也。〔一〕明經為郡文學，以孝廉為郎。舉方正，對策高第，遷諫大夫，行郎中戶將事。〔二〕劾奏衛將軍張安世子侍中陽都侯彭祖不下殿門，〔三〕并連及安世居位無補。彭祖時實下門，寬饒坐舉奏大臣非是，〔四〕左遷為衛司馬。〔五〕","sentenceOrder":1},
  {"id":"s_work_han_thu_90_2","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「蓋音公盍反。」","sentenceOrder":2},
  {"id":"s_work_han_thu_90_3","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「百官公卿表郎中令屬官有郎中車、戶、騎三將，蓋各以所主為名也。戶將者，主戶衛也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_90_4","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「過殿門不下車也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_90_5","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　師古曰：「不以實也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_90_6","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　蘇林曰：「如今衛士令也。」臣瓚曰：「漢注有衛屯司馬。」","sentenceOrder":6},
  {"id":"s_work_han_thu_90_7","chapterId":"ch_work_han_thu_90","textTraditional":"先是時，衛司馬在部，見衛尉拜謁，常為衛官繇使巿買。〔一〕寬饒視事，案舊令，遂揖官屬以下行衛者。〔二〕衛尉私使寬饒出，寬饒以令詣官府門上謁辭。〔三〕尚書責問衛尉，〔四〕由是衛官不復私使候、司馬。候、司馬不拜，出先置衛，輒上奏辭，〔五〕自此正焉。","sentenceOrder":7},
  {"id":"s_work_han_thu_90_8","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「繇讀與徭同。」","sentenceOrder":8},
  {"id":"s_work_han_thu_90_9","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　蘇林曰：「衛尉官屬也。或曰詔遣使行衛者也。」師古曰：「或說非也。行音下更反。」","sentenceOrder":9},
  {"id":"s_work_han_thu_90_10","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　文穎曰：「私見使而公辭尚書也。」蘇林曰：「以法詣衛尉府門上謁也。」師古曰：「文說是也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_90_11","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　文穎曰：「由寬饒以法令不給使，尚書責衛尉，不復使司馬。」","sentenceOrder":11},
  {"id":"s_work_han_thu_90_12","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　如淳曰：「天子出，為天子先導。先天子發，故上奏辭。」","sentenceOrder":12},
  {"id":"s_work_han_thu_90_13","chapterId":"ch_work_han_thu_90","textTraditional":"寬饒初拜為司馬，未出殿門，斷其襌衣，令短離地，〔一〕冠大冠，帶長劍，躬案行士卒廬室，視其飲食居處，有疾病者身自撫循臨問，加致醫藥，遇之甚有恩。及歲盡交代，上臨饗罷衛卒，〔二〕衛卒數千人皆叩頭自請，願復留共更一年，〔三〕以報寬饒厚德。宣帝嘉之，以寬饒為太中大夫，使行風俗，〔四〕多所稱舉貶黜，奉使稱意。擢為司隸校尉，刺舉無所迴避，小大輒舉，所劾奏眾多，廷尉處其法，半用半不用，〔五〕公卿貴戚及郡國吏繇使至長安，皆恐懼莫敢犯禁，〔六〕京師為清。","sentenceOrder":13},
  {"id":"s_work_han_thu_90_14","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「襌音單，其字從衣。」","sentenceOrder":14},
  {"id":"s_work_han_thu_90_15","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「得代當歸者也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_90_16","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「更猶今言上番也，音工衡反。」","sentenceOrder":16},
  {"id":"s_work_han_thu_90_17","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　師古曰：「行音下更反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_90_18","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　師古曰：「以其峻刻，故有不用者。」","sentenceOrder":18},
  {"id":"s_work_han_thu_90_19","chapterId":"ch_work_han_thu_90","textTraditional":"〔六〕　師古曰：「繇讀與傜同，供傜役及為使而來者。」","sentenceOrder":19},
  {"id":"s_work_han_thu_90_20","chapterId":"ch_work_han_thu_90","textTraditional":"平恩侯許伯入第，〔一〕丞相、御史、將軍、中二千石皆賀，寬饒不行。許伯請之，乃往，從西階上，東鄉特坐。〔二〕許伯自酌曰：「蓋君後至。」寬饒曰：「無多酌我，我乃酒狂。」丞相魏侯笑曰：「次公醒而狂，何必酒也？」坐者皆屬目卑下之。〔三〕酒酣樂作，長信少府檀長卿起舞，為沐猴與狗鬥，〔四〕坐皆大笑。寬饒不說，卬視屋而歎〔五〕曰：「美哉！然富貴無常，忽則易人，此如傳舍，所閱多矣。〔六〕唯謹慎為得久，君侯可不戒哉！」因起趨出，劾奏長信少府以列卿而沐猴舞，失禮不敬。上欲罪少府，許伯為謝，良久，上乃解。","sentenceOrder":20},
  {"id":"s_work_han_thu_90_21","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「許伯，皇太子外祖也。入第者，治第新成，始入居之。」","sentenceOrder":21},
  {"id":"s_work_han_thu_90_22","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「言自尊抗，無所詘也。鄉讀曰嚮。」","sentenceOrder":22},
  {"id":"s_work_han_thu_90_23","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「屬猶注也，音之欲反。下音胡稼反。」","sentenceOrder":23},
  {"id":"s_work_han_thu_90_24","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　師古曰：「沐猴，獼猴。」","sentenceOrder":24},
  {"id":"s_work_han_thu_90_25","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　師古曰：「說讀曰悅。卬讀曰仰。」","sentenceOrder":25},
  {"id":"s_work_han_thu_90_26","chapterId":"ch_work_han_thu_90","textTraditional":"〔六〕　師古曰：「言如客舍行客，輒過之，故多所經歷也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_90_27","chapterId":"ch_work_han_thu_90","textTraditional":"寬饒為人剛直高節，志在奉公。家貧，奉錢月數千，〔一〕半以給吏民為耳目言事者。身為司隸，子常步行自戍北邊，〔二〕公廉如此。然深刻喜陷害人，〔三〕在位及貴戚人與為怨，〔四〕又好言事刺譏，奸犯上意。〔五〕上以其儒者，優容之，然亦不得遷。同列後進或至九卿，寬饒自以行清能高，有益於國，而為凡庸所越，愈失意不快，數上疏諫爭。太子庶子王生高寬饒節，而非其如此，予書曰：「明主知君絜白公正，不畏彊禦，〔六〕故命君以司察之位，擅君以奉使之權，尊官厚祿已施於君矣。君宜夙夜惟思當世之務，奉法宣化，憂勞天下，雖日有益，月有功，猶未足以稱職而報恩也。自古之治，三王之術各有制度。〔七〕今君不務循職而已，乃欲以太古久遠之事匡拂天子，〔八〕數進不用難聽之語以摩切左右，非所以揚令名全壽命者也。方今用事之人皆明習法令，言足以飾君之辭，文足以成君之過，君不惟蘧氏之高蹤，〔九〕而慕子胥之末行，〔一０〕用不訾之軀，臨不測之險，〔一一〕竊為君痛之。夫君子直而不挺，曲而不詘。〔一二〕大雅云：『既明且哲，以保其身。』〔一三〕狂夫之言，聖人擇焉。唯裁省覽。」寬饒不納其言。","sentenceOrder":27},
  {"id":"s_work_han_thu_90_28","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「奉音扶用反。」","sentenceOrder":28},
  {"id":"s_work_han_thu_90_29","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　蘇林曰：「子自行戍，不取代。」","sentenceOrder":29},
  {"id":"s_work_han_thu_90_30","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「喜音許吏反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_90_31","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　師古曰：「人人皆怨之。」","sentenceOrder":31},
  {"id":"s_work_han_thu_90_32","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　師古曰：「奸音干。」","sentenceOrder":32},
  {"id":"s_work_han_thu_90_33","chapterId":"ch_work_han_thu_90","textTraditional":"〔六〕　師古曰：「彊禦，彊梁而禦善者也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_90_34","chapterId":"ch_work_han_thu_90","textTraditional":"〔七〕　師古曰：「三王謂夏、殷、周，文質不同也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_90_35","chapterId":"ch_work_han_thu_90","textTraditional":"〔八〕　師古曰：「匡，正也。拂讀曰弼。」","sentenceOrder":35},
  {"id":"s_work_han_thu_90_36","chapterId":"ch_work_han_thu_90","textTraditional":"〔九〕　師古曰：「蘧伯玉，邦無道，則可卷而懷之。」","sentenceOrder":36},
  {"id":"s_work_han_thu_90_37","chapterId":"ch_work_han_thu_90","textTraditional":"〔一０〕師古曰：「伍子胥知吳王不可諫，而不能止，自取誅滅也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_90_38","chapterId":"ch_work_han_thu_90","textTraditional":"〔一一〕師古曰：「訾與貲同。不貲者，言無貲量可以比之，貴重之極也。不測謂深也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_90_39","chapterId":"ch_work_han_thu_90","textTraditional":"〔一二〕師古曰：「挺然，直貌。言雖執直道，而遭遇時變，與時紆曲，然其本志不屈橈也。挺音吐鼎反。」","sentenceOrder":39},
  {"id":"s_work_han_thu_90_40","chapterId":"ch_work_han_thu_90","textTraditional":"〔一三〕師古曰：「烝民之詩也。言明智者可以自全，不至亡身。」","sentenceOrder":40},
  {"id":"s_work_han_thu_90_41","chapterId":"ch_work_han_thu_90","textTraditional":"是時上方用刑法，信任中尚書宦官，寬饒奏封事曰：「方今聖道浸廢，儒術不行，〔一〕以刑餘為周召，〔二〕以法律為詩書。〔三〕」又引韓氏易傳言：「五帝官天下，三王家天下，家以傳子，官以傳賢，若四時之運，功成者去，不得其人則不居其位。」書奏，上以寬饒怨謗終不改，下其書中二千石。時執金吾議，以為寬饒指意欲求禪，大逆不道。〔四〕諫大夫鄭昌愍傷寬饒忠直憂國，以言事不當意而為文吏所詆挫，〔五〕上書頌寬饒曰：〔六〕「臣聞山有猛獸，藜藿為之不采；國有忠臣，姦邪為之不起。司隸校尉寬饒居不求安，食不求飽，〔七〕進有憂國之心，退有死節之義，上無許、史之屬，下無金、張之託，〔八〕職在司察，直道而行，多仇少與，〔九〕上書陳國事，有司劾以大辟，臣幸得從大夫之後，官以諫為名，不敢不言。」上不聽，遂下寬饒吏。寬饒引佩刀自剄北闕下，眾莫不憐之。","sentenceOrder":41},
  {"id":"s_work_han_thu_90_42","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「浸，漸也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_90_43","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「言使奄人當權軸也。周謂周公旦也，召謂召公奭也。召讀曰邵。」","sentenceOrder":43},
  {"id":"s_work_han_thu_90_44","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「言以（行）〔刑〕法成教化也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_90_45","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　師古曰：「襢，古禪字。言欲使天子傳位於己。」","sentenceOrder":45},
  {"id":"s_work_han_thu_90_46","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　師古曰：「詆，毀也。挫，折也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_90_47","chapterId":"ch_work_han_thu_90","textTraditional":"〔六〕　師古曰：「頌謂稱其美。」","sentenceOrder":47},
  {"id":"s_work_han_thu_90_48","chapterId":"ch_work_han_thu_90","textTraditional":"〔七〕　師古曰：「論語稱孔子曰『君子食無求飽，居無求安』，故引之。」","sentenceOrder":48},
  {"id":"s_work_han_thu_90_49","chapterId":"ch_work_han_thu_90","textTraditional":"〔八〕　應劭曰：「許伯，宣帝皇后父。史高，宣帝外家也。金，金日磾也。張，張安世也。此四家屬無不聽。」師古曰：「此說非也。許氏、史氏有外屬之恩，金氏、張氏自託在於近狎也。屬讀如本字也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_90_50","chapterId":"ch_work_han_thu_90","textTraditional":"〔九〕　師古曰：「仇，怨讎也。與，黨與也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_90_51","chapterId":"ch_work_han_thu_90","textTraditional":"諸葛豐字少季，琅邪人也。以明經為郡文學，名特立剛直。貢禹為御史大夫，除豐為屬，舉侍御史。元帝擢為司隸校尉，刺舉無所避，京師為之語曰：「間何闊，逢諸葛。」〔一〕上嘉其節，加豐秩光祿大夫。","sentenceOrder":51},
  {"id":"s_work_han_thu_90_52","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「言間者何久闊不相見，以逢諸葛故也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_90_53","chapterId":"ch_work_han_thu_90","textTraditional":"時侍中許章以外屬貴幸，奢淫不奉法度，賓客犯事，與章相連。豐案劾章，欲奏其事，適逢許侍中私出，豐駐車舉節詔章曰：「下！」欲收之。章迫窘，馳車去，豐追之。許侍中因得入宮門，自歸上。〔一〕豐亦上奏，於是收豐節。司隸去節自豐始。","sentenceOrder":53},
  {"id":"s_work_han_thu_90_54","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「歸誠乞哀於天子也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_90_55","chapterId":"ch_work_han_thu_90","textTraditional":"豐上書謝曰：「臣豐駑怯，文不足以勸善，武不足以執邪。陛下不量臣能否，拜為司隸校尉，未有以自效，復秩臣為光祿大夫，官尊責重，非臣所當處也。又迫年歲衰暮，常恐卒填溝渠，〔一〕（德）無以報厚〔德〕，使論議士譏臣無補，長獲素餐之名。〔二〕故常願捐一旦之命，不待時而斷姦臣之首，縣於都市，編書其罪，〔三〕使四方明知為惡之罰，然後卻就斧鉞之誅，〔四〕誠臣所甘心也。夫以布衣之士，尚猶有刎頸之交，〔五〕今以四海之大，曾無伏節死誼之臣，率盡苟合取容，阿黨相為，念私門之利，忘國家之政。邪穢濁溷之氣上感于天，〔六〕是以災變數見，百姓困乏。此臣下不忠之效也，臣誠恥之亡已。凡人情莫不欲安存而惡危亡，然忠臣直士不避患害者，誠為君也。今陛下天覆地載，物無不容，〔七〕使尚書令堯賜臣豐書曰：『夫司隸者刺舉不法，善善惡惡，非得顓之也。〔八〕免處中和，順經術意。』恩深德厚，臣豐頓首幸甚。臣竊不勝憤懣，願賜清宴，〔九〕唯陛下裁幸。」上不許。","sentenceOrder":55},
  {"id":"s_work_han_thu_90_56","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「卒讀曰猝。」","sentenceOrder":56},
  {"id":"s_work_han_thu_90_57","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「素，空也。言不舉職務，空食祿奉而已。」","sentenceOrder":57},
  {"id":"s_work_han_thu_90_58","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「編謂聯次簡牘也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_90_59","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　師古曰：「卻，退也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_90_60","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　師古曰：「刎，斷也，音吻。」","sentenceOrder":60},
  {"id":"s_work_han_thu_90_61","chapterId":"ch_work_han_thu_90","textTraditional":"〔六〕　師古曰：「溷亦濁也，音下頓反。」","sentenceOrder":61},
  {"id":"s_work_han_thu_90_62","chapterId":"ch_work_han_thu_90","textTraditional":"〔七〕　師古曰：「如天之覆，如地之載也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_90_63","chapterId":"ch_work_han_thu_90","textTraditional":"〔八〕　師古曰：「善善，褒賞善人也。惡惡，誅罰惡人也。顓與專同。」","sentenceOrder":63},
  {"id":"s_work_han_thu_90_64","chapterId":"ch_work_han_thu_90","textTraditional":"〔九〕　師古曰：「懣音滿。」","sentenceOrder":64},
  {"id":"s_work_han_thu_90_65","chapterId":"ch_work_han_thu_90","textTraditional":"是後所言益不用，豐復上書言：「臣聞伯奇孝而棄於親，子胥忠而誅於君，〔一〕隱公慈而殺於弟，〔二〕叔武弟而殺於兄。〔三〕夫以四子之行，屈平之材，〔四〕然猶不能自顯而被刑戮，豈不足以觀哉！使臣殺身以安國，蒙誅以顯君，〔五〕臣誠願之。獨恐未有云補，而為眾邪所排，令讒夫得遂，正直之路雍塞，〔六〕忠臣沮心，智士杜口，〔七〕此愚臣之所懼也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_90_66","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「並解於上也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_90_67","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「魯隱公欲立弟桓公，為其尚少，己且攝位，而卒為桓公所殺。」","sentenceOrder":67},
  {"id":"s_work_han_thu_90_68","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「叔武，衛成公之弟夷叔也。成公避晉之難，出奔陳，使大夫元咺奉叔武以居守。其後晉人納成公，成公疑叔武而先期入，叔武將沐，聞君至喜，捉髮走出，前驅射而殺之。事在左傳僖二十八年。叔武弟音大計反。」","sentenceOrder":68},
  {"id":"s_work_han_thu_90_69","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　師古曰：「屈平即是屈原也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_90_70","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　師古曰：「蒙，被也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_90_71","chapterId":"ch_work_han_thu_90","textTraditional":"〔六〕　師古曰：「雍讀曰壅。」","sentenceOrder":71},
  {"id":"s_work_han_thu_90_72","chapterId":"ch_work_han_thu_90","textTraditional":"〔七〕　師古曰：「沮，壞；杜，塞也。沮音才汝反。」","sentenceOrder":72},
  {"id":"s_work_han_thu_90_73","chapterId":"ch_work_han_thu_90","textTraditional":"豐以春夏繫治人，在位多言其短。上徙豐為城門校尉，豐上書告光祿勳周堪、光祿大夫張猛。上不直豐，乃制詔御史：「城門校尉豐，前與光祿勳堪、光祿大夫猛在朝之時，數稱言堪、猛之美。豐前為司隸校尉，不順四時，修法度，專作苛暴，以獲虛威，朕不忍下吏，以為城門校尉。不內省諸己，〔一〕而反怨堪、猛，以求報舉，〔二〕告案無證之辭，暴揚難驗之罪，毀譽恣意，不顧前言，〔三〕不信之大者也。朕憐豐之耆老，不忍加刑，其免為庶人。」終於家。","sentenceOrder":73},
  {"id":"s_work_han_thu_90_74","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「省，察也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_90_75","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「舉言其事以報怨。」","sentenceOrder":75},
  {"id":"s_work_han_thu_90_76","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　帥古曰：「前言謂譽堪、猛之美。今乃更言其短，是不顧也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_90_77","chapterId":"ch_work_han_thu_90","textTraditional":"劉輔，河間宗室〔人〕也。舉孝廉，為襄賁令。〔一〕上書言得失，召見，上美其材，擢為諫大夫。會成帝欲立趙婕妤為皇后，先下詔封婕妤父臨為列侯。輔上書言：「臣聞天之所與必先賜以符瑞，天之所違必先降以災變，此神明之徵應，自然之占驗也。昔武王、周公承順天地，以饗魚烏之瑞，〔二〕然猶君臣祗懼，動色相戒，況於季世，不蒙繼嗣之福，屢受威怒之異者虖！雖夙夜自責，改過易行，畏天命，念祖業，妙選有德之世，考卜窈窕之女，〔三〕以承宗廟，順神祇心，塞天下望，〔四〕子孫之祥猶恐晚暮，今乃觸情縱欲，傾於卑賤之女，欲以母天下，不畏于天，不媿于人，惑莫大焉。里語曰：『腐木不可以為柱，卑人不可以為主。』天人之所不予，必有禍而無福，市道皆共知之，〔五〕朝廷莫肯壹言，臣竊傷心。自念得以同姓拔擢，尸祿不忠，污辱諫爭之官，不敢不盡死，唯陛下深察。」書奏，上使侍御史收縛輔，繫掖庭祕獄，〔六〕群臣莫知其故。","sentenceOrder":77},
  {"id":"s_work_han_thu_90_78","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　蘇林曰：「賁音肥，東海縣也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_90_79","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「謂伐紂時有白魚、赤烏之瑞也。事見今文尚書。」","sentenceOrder":79},
  {"id":"s_work_han_thu_90_80","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「窈窕，幽閑也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_90_81","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　師古曰：「塞，滿也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_90_82","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　師古曰：「市道，市中之道也。一曰市人及行於道路者也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_90_83","chapterId":"ch_work_han_thu_90","textTraditional":"〔六〕　師古曰：「漢書舊儀掖庭詔獄令丞宦者為之，主理婦人女官也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_90_84","chapterId":"ch_work_han_thu_90","textTraditional":"於是中朝左將軍辛慶忌、右將軍廉褒、光祿勳師丹、太中大夫谷永〔一〕俱上書曰：「臣聞明王垂寬容之聽，崇諫爭之官，廣開忠直之路，不罪狂狷之言，〔二〕然後百僚在位，竭忠盡謀，不懼後患，朝廷無諂諛之士，元首無失道之諐。〔三〕竊見諫大夫劉輔，前以縣令求見，擢為諫大夫，此其言必有卓詭切至，當聖心者，〔四〕故得拔至於此。旬日之間，收下祕獄，臣等愚，以為輔幸得託公族之親，在諫臣之列，新從下土來，未知朝廷體，獨觸忌諱，不足深過。小罪宜隱忍而已，如有大惡，宜暴治理官，與眾共之。〔五〕昔趙簡子殺其大夫鳴犢，孔子臨河而還。〔六〕今天心未豫，〔七〕災異屢降，水旱迭臻，〔八〕方當隆寬廣問，褒直盡下之時也。而行慘急之誅於諫爭之臣，震驚群下，失忠直心。假令輔不坐直言，所坐不著，〔九〕天下不可戶曉。〔一０〕同姓近臣本以言顯，其於治親養忠之義誠不宜幽囚于掖庭獄。公卿以下見陛下進用輔亟，而折傷之暴，〔一一〕人有懼心，〔一二〕精銳銷耎，〔一三〕莫敢盡節正言，非所以昭有虞之聽，廣德美之風也。〔一四〕臣等竊深傷之，唯陛下留神省察。」","sentenceOrder":84},
  {"id":"s_work_han_thu_90_85","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　孟康曰：「中朝，內朝也。大司馬左右前後將軍、侍中、常侍、散騎、諸吏為中朝。丞相以下至六百石為外朝也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_90_86","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「狷，急也，音絹。」","sentenceOrder":86},
  {"id":"s_work_han_thu_90_87","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「元首謂天子也。讇，古諂字也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_90_88","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　師古曰：「卓，高遠也。詭，異於眾也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_90_89","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　師古曰：「令眾人知其罪狀而罰之。」","sentenceOrder":89},
  {"id":"s_work_han_thu_90_90","chapterId":"ch_work_han_thu_90","textTraditional":"〔六〕　張晏曰：「趙簡子欲分晉國，故先殺鳴犢，又聘孔子。孔子聞其死，至河而還也。」師古曰：「戰國策說二人姓名云『鳴犢、鐸犨，』，而史記及古今人表並以為鳴犢、竇犨，蓋鐸、犢及竇，其聲相近，故有不同耳。今永等指舉殺鳴犢一人，不論竇犨也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_90_91","chapterId":"ch_work_han_thu_90","textTraditional":"〔七〕　張晏曰：「豫，悅豫也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_90_92","chapterId":"ch_work_han_thu_90","textTraditional":"〔八〕　師古曰：「迭，互也。音徒結反。」","sentenceOrder":92},
  {"id":"s_work_han_thu_90_93","chapterId":"ch_work_han_thu_90","textTraditional":"〔九〕　師古曰：「著，明也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_90_94","chapterId":"ch_work_han_thu_90","textTraditional":"〔一０〕師古曰：「言不可家家曉喻之也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_90_95","chapterId":"ch_work_han_thu_90","textTraditional":"〔一一〕師古曰：「亟，急也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_90_96","chapterId":"ch_work_han_thu_90","textTraditional":"〔一二〕師古曰：「人人皆懼也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_90_97","chapterId":"ch_work_han_thu_90","textTraditional":"〔一三〕蘇林曰：「耎，弱也。」師古曰：「音乃喚反。」","sentenceOrder":97},
  {"id":"s_work_han_thu_90_98","chapterId":"ch_work_han_thu_90","textTraditional":"〔一四〕師古曰：「舜有敢諫之鼓，故言有虞之聽也。一曰謂達四聰也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_90_99","chapterId":"ch_work_han_thu_90","textTraditional":"上乃徙繫輔共工獄，〔一〕減死罪一等，論為鬼薪。終於家。","sentenceOrder":99},
  {"id":"s_work_han_thu_90_100","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　蘇林曰：「考工也。」師古曰：「少府之屬官也，亦有詔獄。共讀與龔同。」","sentenceOrder":100},
  {"id":"s_work_han_thu_90_101","chapterId":"ch_work_han_thu_90","textTraditional":"鄭崇字子游，本高密大族，世與王家相嫁娶。〔一〕祖父以訾徙平陵。父賓明法令，為御史，事貢公，〔二〕名公直。崇少為郡文學史，至丞相大車屬。〔三〕弟立與高武侯傅喜同門學，相友善。〔四〕喜為大司馬，薦崇，哀帝擢為尚書僕射。數求見諫爭，上初納用之。每見曳革履，〔五〕上笑曰：「我識鄭尚書履聲。」","sentenceOrder":101},
  {"id":"s_work_han_thu_90_102","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「女嫁王家，男又娶也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_90_103","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「貢禹也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_90_104","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　如淳曰：「丞相大車屬如今公府御屬。」","sentenceOrder":104},
  {"id":"s_work_han_thu_90_105","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　師古曰：「同門謂同師也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_90_106","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　師古曰：「孰曰韋，生曰革。」","sentenceOrder":106},
  {"id":"s_work_han_thu_90_107","chapterId":"ch_work_han_thu_90","textTraditional":"久之，上欲封祖母傅太后從弟商，崇諫曰：「孝成皇帝封親舅五侯，天為赤黃晝昏，日中有黑氣。今祖母從昆弟二人已侯。孔鄉侯，皇后父；高武侯以三公封，尚有因緣。〔一〕今無故欲復封商，壞亂制度，逆天人心，非傅氏之福也。臣聞師曰：『逆陽者厥極弱，逆陰者厥極凶短折，犯人者有亂亡之患，犯神者有疾夭之禍。』故周公著戒曰：『惟王不知艱難，唯耽樂是從，時亦罔有克壽。』〔二〕故衰世之君夭折蚤沒，〔三〕此皆犯陰之害也。臣願以身命當國咎。」崇因持詔書案起。〔四〕傅太后大怒曰：「何有為天子乃反為一臣所顓制邪！」〔五〕上遂下詔曰：「朕幼而孤，皇太太后躬自養育，免于襁褓，教道以禮，至於成人，〔六〕惠澤茂焉。〔七〕『欲報之德，皞天罔極。』〔八〕前追號皇太太后父為崇祖侯，惟念德報未殊，朕甚恧焉。〔九〕侍中光祿大夫商，皇太太后父同產子，小自保大〔一０〕，恩義最親。其封商為汝昌侯，為崇祖侯後，更號崇祖侯為汝昌哀侯。」","sentenceOrder":107},
  {"id":"s_work_han_thu_90_108","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「孔鄉侯，傅晏也。高武侯，傅喜也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_90_109","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「周書亡逸之篇也。言王者不知稼穡之艱難，唯從耽樂，則致夭喪，無能壽考也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_90_110","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「蚤，古（旱）〔早〕字也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_90_111","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　李奇曰：「持當受詔書案起也。」師古曰：「李說非也。案者，即寫詔之文。」","sentenceOrder":111},
  {"id":"s_work_han_thu_90_112","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　師古曰：「顓與專同也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_90_113","chapterId":"ch_work_han_thu_90","textTraditional":"〔六〕　師古曰：「道讀曰導。」","sentenceOrder":113},
  {"id":"s_work_han_thu_90_114","chapterId":"ch_work_han_thu_90","textTraditional":"〔七〕　師古曰：「茂，美也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_90_115","chapterId":"ch_work_han_thu_90","textTraditional":"〔八〕　師古曰：「詩小雅蓼莪之篇曰：『父兮生我，母兮鞠我，欲報之德，昊天罔極。』言欲報父母之恩德，心無已也。呼昊天者，陳己至誠也。皞字與昊同。」","sentenceOrder":115},
  {"id":"s_work_han_thu_90_116","chapterId":"ch_work_han_thu_90","textTraditional":"〔九〕　師古曰：「殊，異也。恧，愧也，音女六反。」","sentenceOrder":116},
  {"id":"s_work_han_thu_90_117","chapterId":"ch_work_han_thu_90","textTraditional":"〔一０〕如淳曰：「太后從小養之，使至大也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_90_118","chapterId":"ch_work_han_thu_90","textTraditional":"崇又以董賢貴寵過度諫，由是重得罪。〔一〕數以職事見責，發疾頸癰，欲乞骸骨，不敢。尚書令趙昌佞諂，素害崇，知其見疏，因奏崇與宗族通，疑有姦，請治。上責崇曰：「君門如巿人，何以欲禁切主上？」〔二〕崇對曰：「臣門如巿，臣心如水。〔三〕願得考覆。」上怒，下崇獄，窮治，死獄中。","sentenceOrder":118},
  {"id":"s_work_han_thu_90_119","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「重音直用反。」","sentenceOrder":119},
  {"id":"s_work_han_thu_90_120","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「言請求者多，交通賓客。」","sentenceOrder":120},
  {"id":"s_work_han_thu_90_121","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「言至清也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_90_122","chapterId":"ch_work_han_thu_90","textTraditional":"孫寶字子嚴，潁川鄢陵人也。〔一〕以明經為郡吏。御史大夫張忠辟寶為屬，欲令授子經，更為除舍，〔二〕設儲偫。〔三〕寶自劾去，忠固還之，〔四〕心內不平。〔五〕後署寶主簿，寶徙入舍，祭灶請比鄰。忠陰察，怪之，使所親問寶：「前大夫為君設除大舍，子自劾去者，欲為高節也。今兩府高士俗不為主簿，子既為之，徙舍甚說，〔六〕何前後不相副也？」寶曰：「高士不為主簿，而大夫君以寶為可，一府莫言非，〔七〕士安得獨自高？前日君男欲學文，而移寶自近。〔八〕禮有來學，義無往教；道不可詘，身詘何傷？且不遭者可無不為，況主簿乎！」〔九〕忠聞之，甚慚，上書薦寶經明質直，宜備近臣。為議郎，遷諫大夫。","sentenceOrder":122},
  {"id":"s_work_han_thu_90_123","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「鄢音偃。」","sentenceOrder":123},
  {"id":"s_work_han_thu_90_124","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「除謂修飾掃除也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_90_125","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「謂豫備器物也。偫音丈紀反。」","sentenceOrder":125},
  {"id":"s_work_han_thu_90_126","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　師古曰：「固者，謂再三留之。」","sentenceOrder":126},
  {"id":"s_work_han_thu_90_127","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　師古曰：「恨其去也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_90_128","chapterId":"ch_work_han_thu_90","textTraditional":"〔六〕　師古曰：「說讀曰悅。」","sentenceOrder":128},
  {"id":"s_work_han_thu_90_129","chapterId":"ch_work_han_thu_90","textTraditional":"〔七〕　師古曰：「言大夫以為寶適可為主簿耳，府中之人又不以為不當也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_90_130","chapterId":"ch_work_han_thu_90","textTraditional":"〔八〕　師古曰：「文謂書也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_90_131","chapterId":"ch_work_han_thu_90","textTraditional":"〔九〕　師古曰：「言士不遭遇知己，則當屈辱，無所不為也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_90_132","chapterId":"ch_work_han_thu_90","textTraditional":"鴻嘉中，廣漢群盜起，選為益州刺史。廣漢太守扈商者，大司馬車騎將軍王音姊子，軟弱不任職。寶到部，親入山谷，諭告群盜，非本造意。渠率皆得悔過自出，〔一〕遣歸田里。自劾矯制，奏商為亂首，〔二〕春秋之義，誅首惡而已。商亦奏寶所縱或有渠率當坐者。〔三〕商徵下獄，寶坐失死罪免。益州吏民多陳寶功效，言為車騎將軍所排。上復拜寶為冀州刺史，遷丞相司直。","sentenceOrder":132},
  {"id":"s_work_han_thu_90_133","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「渠，大也。」","sentenceOrder":133},
  {"id":"s_work_han_thu_90_134","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「擅放群盜歸，故云矯制。（也）〔由〕商不任職，致有賊盜，故云為亂首也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_90_135","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「縱，放也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_90_136","chapterId":"ch_work_han_thu_90","textTraditional":"時帝舅紅陽侯立使客因南郡太守李尚占墾草田數百頃，〔一〕頗有民所假少府陂澤，略皆開發，〔二〕上書願以入縣官。〔三〕有詔郡平田予直，〔四〕錢有貴一萬萬以上。〔五〕寶聞之，遣丞相史按驗，發其姦，劾奏立、尚懷姦罔上，狡猾不道。尚下獄死。立雖不坐，後兄大司馬衛將軍商薨，次當代商，上度立而用其弟曲陽侯根為大司馬票騎將軍。〔六〕","sentenceOrder":136},
  {"id":"s_work_han_thu_90_137","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「隱度而取之也。草田，荒田也。占音之贍反。」","sentenceOrder":137},
  {"id":"s_work_han_thu_90_138","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「舊為陂澤，本屬少府，其後以假百姓，百姓皆已田之，而立總謂為草田，占云新自墾。」","sentenceOrder":138},
  {"id":"s_work_han_thu_90_139","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「立上書云新墾得此田，請以入官也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_90_140","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　師古曰：「受其田而準償價直也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_90_141","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　師古曰：「增於時價。」","sentenceOrder":141},
  {"id":"s_work_han_thu_90_142","chapterId":"ch_work_han_thu_90","textTraditional":"〔六〕　如淳曰：「度，過也。過立而用根。」","sentenceOrder":142},
  {"id":"s_work_han_thu_90_143","chapterId":"ch_work_han_thu_90","textTraditional":"會益州蠻夷犯法，巴蜀頗不安，上以寶著名西州，拜為廣漢太守，秩中二千石，賜黃金三十斤。蠻夷安輯，吏民稱之。〔一〕","sentenceOrder":143},
  {"id":"s_work_han_thu_90_144","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「輯與集同。」","sentenceOrder":144},
  {"id":"s_work_han_thu_90_145","chapterId":"ch_work_han_thu_90","textTraditional":"徵為京兆尹。故吏侯文以剛直不苟合常稱疾不肯仕，寶以恩禮請文，欲為布衣友，日設酒食，妻子相對。文求受署為掾，進見如賓禮。數月，以立秋日署文東部督郵。入見，敕曰：「今日鷹隼始擊，當順天氣取姦惡，以成嚴霜之誅，掾部渠有其人乎？」〔一〕文卬曰：「無其人不敢空受職。」〔二〕寶曰：「誰也？」文曰：「霸陵杜稚季。」寶曰：「其次。」〔三〕文曰：「豺狼橫道，不宜復問狐狸。」〔四〕寶默然。稚季者大俠，與衛尉淳于長、大鴻臚蕭育等皆厚善。寶前失車騎將軍，與紅陽侯有卻，〔五〕自恐見危，時淳于長方貴幸，友寶，寶亦欲附之，始視事而長以稚季託寶，故寶窮，無以復應文。文怪寶氣索，〔六〕知其有故，因曰：「明府素著威名，今不敢取稚季，當且闔閤，勿有所問。〔七〕如此竟歲，吏民未敢誣明府也。〔八〕即度稚季而譴它事，〔九〕眾口讙譁，終身自墮。」〔一０〕寶曰：「受教。」稚季耳目長，聞知之，杜門不通水火，〔一一〕穿舍後牆為小戶，但持鉏自治園，因文所厚自陳如此。〔一二〕文曰：「我與稚季幸同土壤，素無睚眥，〔一三〕顧受將命，分當相直。〔一四〕誠能自改，嚴將不治前事，即不更心，但更門戶，適趣禍耳。」〔一五〕稚季遂不敢犯法，寶亦竟歲無所譴。明年，稚季病死。寶為京兆尹三歲，京師稱之。會淳于長敗，寶與蕭育等皆坐免官。文復去吏，死於家。稚季子杜蒼，字君敖，名出稚季右，在游俠中。","sentenceOrder":145},
  {"id":"s_work_han_thu_90_146","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「渠讀曰詎。詎，豈也。言掾所部內，豈有其人乎？」","sentenceOrder":146},
  {"id":"s_work_han_thu_90_147","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「卬讀曰仰。謂仰頭而對也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_90_148","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「除稚季之外更有誰也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_90_149","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　師古曰：「言不當釋大而取小也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_90_150","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　師古曰：「失車騎將軍，謂失王音意，奏扈商事也。卻與隙同。」","sentenceOrder":150},
  {"id":"s_work_han_thu_90_151","chapterId":"ch_work_han_thu_90","textTraditional":"〔六〕　師古曰：「索，盡也，音先各反。」","sentenceOrder":151},
  {"id":"s_work_han_thu_90_152","chapterId":"ch_work_han_thu_90","textTraditional":"〔七〕　師古曰：「闔，閉也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_90_153","chapterId":"ch_work_han_thu_90","textTraditional":"〔八〕　師古曰：「誣，謗也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_90_154","chapterId":"ch_work_han_thu_90","textTraditional":"〔九〕　李奇曰：「過度不治罪。」","sentenceOrder":154},
  {"id":"s_work_han_thu_90_155","chapterId":"ch_work_han_thu_90","textTraditional":"〔一０〕師古曰：「墮，毀也，音火規反。」","sentenceOrder":155},
  {"id":"s_work_han_thu_90_156","chapterId":"ch_work_han_thu_90","textTraditional":"〔一一〕師古曰：「杜，塞也。不通水火，謂雖鄰伍亦不往來也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_90_157","chapterId":"ch_work_han_thu_90","textTraditional":"〔一二〕師古曰：「具言恐懼改節之狀也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_90_158","chapterId":"ch_work_han_thu_90","textTraditional":"〔一三〕師古曰：「睚音涯。眥音才賜反。睚又音五懈反。眥又音仕懈反。已解於前也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_90_159","chapterId":"ch_work_han_thu_90","textTraditional":"〔一四〕師古曰：「言自顧念受郡將之命，分當相值遇也。分音胡問反。直讀曰值也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_90_160","chapterId":"ch_work_han_thu_90","textTraditional":"〔一五〕師古曰：「更，改也。趣讀曰促。」","sentenceOrder":160},
  {"id":"s_work_han_thu_90_161","chapterId":"ch_work_han_thu_90","textTraditional":"哀帝即位，徵寶為諫大夫，遷司隸。初，傅太后與中山孝王母馮太后俱事元帝，有卻，〔一〕傅太后使有司考馮太后，令自殺，眾庶冤之。寶奏請覆治，傅太后大怒，曰：「帝置司隸，主使察我。馮氏反事明白，故欲擿觖以揚我惡。〔二〕我當坐之。」上乃順指下寶獄。尚書僕射唐林爭之，上以林朋黨比周，〔三〕左遷敦煌魚澤障候。大司馬傅喜、光祿大夫龔勝固爭，上為言太后，出寶復官。","sentenceOrder":161},
  {"id":"s_work_han_thu_90_162","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「以當熊事，慚而嫉之。」","sentenceOrder":162},
  {"id":"s_work_han_thu_90_163","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「擿觖謂挑發之也。擿音它歷反。觖音決。挑音它聊反。」","sentenceOrder":163},
  {"id":"s_work_han_thu_90_164","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「比音頻寐反。」","sentenceOrder":164},
  {"id":"s_work_han_thu_90_165","chapterId":"ch_work_han_thu_90","textTraditional":"頃之，鄭崇下獄，寶上書曰：「臣聞疏不圖親，外不慮內。〔一〕臣幸得銜命奉使，職在刺舉，不敢避貴幸之勢，以塞視聽之明。按尚書令昌奏僕射崇，下獄覆治，榜掠將死，卒無一辭，〔二〕道路稱冤。疑昌與崇內有纖介，〔三〕浸潤相陷，自禁門內樞機近臣，蒙受冤譖，〔四〕虧損國家，為謗不小。臣請治昌，以解眾心。」書奏，天子不說，〔五〕以寶名臣不忍誅，乃制詔丞相大司空：「司隸寶奏故尚書僕射崇冤，請獄治尚書令昌。案崇近臣，罪惡暴著，而寶懷邪，附下罔上，以春月作詆欺，遂其姦心，蓋國之賊也。傳不云乎？『惡利口之覆國家。』〔六〕其免寶為庶人。」","sentenceOrder":165},
  {"id":"s_work_han_thu_90_166","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「圖，謀也。慮，思也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_90_167","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「榜掠，謂笞擊而考問之也。榜音彭。」","sentenceOrder":167},
  {"id":"s_work_han_thu_90_168","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「言有細故宿嫌也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_90_169","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　師古曰：「蒙，被也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_90_170","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　師古曰：「說讀曰悅。」","sentenceOrder":170},
  {"id":"s_work_han_thu_90_171","chapterId":"ch_work_han_thu_90","textTraditional":"〔六〕　師古曰：「論語稱孔子之言。」","sentenceOrder":171},
  {"id":"s_work_han_thu_90_172","chapterId":"ch_work_han_thu_90","textTraditional":"哀帝崩，王莽白王太后徵寶以為光祿大夫，與王舜等俱迎中山王。平帝立，寶為大司農。會越嶲郡上黃龍游江中，太師孔光、大司徒馬宮等咸稱莽功德比周公，宜告祠宗廟。寶曰：「周公上聖，召公大賢。尚猶有不相說，著於經典，兩不相損。〔一〕今風雨未時，百姓不足，每有一事，群臣同聲，〔二〕得無非其美者。」〔三〕時大臣皆失色，侍中奉車都尉甄邯即時承制罷議者。會寶遣吏迎母，母道病，留弟家，獨遣妻子。司直陳崇以奏寶，事下三公即訊。〔四〕寶對曰：「年七十誖眊，恩衰共養，營妻子，如章。」〔五〕寶坐免，終於家。建武中，錄舊德臣，以寶孫伉為諸長。〔六〕","sentenceOrder":172},
  {"id":"s_work_han_thu_90_173","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「周書君奭之序曰『召公為保，周公為師，相成王為左右，召公不說，周公作君奭』是也。兩不相損者，言俱有令名也。召讀曰邵。說讀曰悅。」","sentenceOrder":173},
  {"id":"s_work_han_thu_90_174","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「言雷同阿附，妄說福祥。」","sentenceOrder":174},
  {"id":"s_work_han_thu_90_175","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「言此非朝廷美事也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_90_176","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　師古曰：「就問之也。」","sentenceOrder":176},
  {"id":"s_work_han_thu_90_177","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　師古曰：「誖，惑也。眊與耄同。自言老耄，心志亂惑，供養之恩衰，具如所奏之章也。誖音布內反。共讀曰供，音居用反。」","sentenceOrder":177},
  {"id":"s_work_han_thu_90_178","chapterId":"ch_work_han_thu_90","textTraditional":"〔六〕　師古曰：「伉音抗。諸，琅邪之縣也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_90_179","chapterId":"ch_work_han_thu_90","textTraditional":"毌將隆字君房，東海蘭陵人也。大司馬車騎將軍王音內領尚書，外典兵馬，踵故選置從事中郎〔一〕與參謀議，奏請隆為從事中郎，遷諫大夫。成帝末，隆奏封事言：「古者選諸侯入為公卿，以褒功德，宜徵定陶王使在國邸，以填萬方。」〔二〕其後上竟立定陶王為太子，隆遷冀州牧、潁川太守。哀帝即位，以高第入為京兆尹，遷執金吾。","sentenceOrder":179},
  {"id":"s_work_han_thu_90_180","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「踵猶躡也，言承躡故事也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_90_181","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「填音竹刃反。」","sentenceOrder":181},
  {"id":"s_work_han_thu_90_182","chapterId":"ch_work_han_thu_90","textTraditional":"時侍中董賢方貴，上使中黃門發武庫兵，前後十輩，送董賢及上乳母王阿舍。隆奏言：「武庫兵器，天下公用，國家武備，繕治造作，皆度大司農錢。〔一〕大司農錢自乘輿不以給共養，〔二〕共養勞賜，壹出少府。蓋不以本臧給末用，不以民力共浮費，〔三〕別公私，示正路也。古者諸侯方伯得顓征伐，乃賜斧鉞。〔四〕漢家邊吏，職在距寇，亦賜武庫兵，皆任其事然後蒙之。春秋之誼，家不臧甲，所以抑臣威，損私力也。今賢等便僻弄臣，私恩微妾，而以天下公用給其私門，契國威器共其家備。〔五〕民力分於弄臣，武兵設於微妾，建立非宜，以廣驕僭，非所以示四方也。孔子曰：『奚取於三家之堂！』〔六〕臣請收還武庫。」上不說。〔七〕","sentenceOrder":182},
  {"id":"s_work_han_thu_90_183","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　蘇林曰：「用度皆出大司農。」","sentenceOrder":183},
  {"id":"s_work_han_thu_90_184","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「共音居用反。養音弋向反。」","sentenceOrder":184},
  {"id":"s_work_han_thu_90_185","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「共讀曰供。」","sentenceOrder":185},
  {"id":"s_work_han_thu_90_186","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　師古曰：「顓與專同也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_90_187","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　李奇曰：「契，缺也。」晉灼曰：「契，取也。」師古曰：「李說是也。共讀曰供。」","sentenceOrder":187},
  {"id":"s_work_han_thu_90_188","chapterId":"ch_work_han_thu_90","textTraditional":"〔六〕　師古曰：「三家，謂魯大夫叔孫、仲孫、季孫也。論語云：『三家者，以雍徹。孔子曰：「相維辟公，天子穆穆，奚取於三家之堂！」』言三家以雍徹食，此乃天子之禮耳，何為在三家之堂也！」","sentenceOrder":188},
  {"id":"s_work_han_thu_90_189","chapterId":"ch_work_han_thu_90","textTraditional":"〔七〕　師古曰：「說讀曰悅。」","sentenceOrder":189},
  {"id":"s_work_han_thu_90_190","chapterId":"ch_work_han_thu_90","textTraditional":"頃之，傅太后使謁者買諸官婢，賤取之，復取執金吾官婢八人。隆奏言賈賤，請更平直。〔一〕上於是制詔丞相、御史大夫：「交讓之禮興，則虞芮之訟息。〔二〕隆位九卿，既無以匡朝廷之不逮，而反奏請與永信宮爭貴賤之賈，程奏顯言，〔三〕眾莫不聞。舉錯不由誼理，〔四〕爭求之名自此始，無以示百僚，傷化失俗。」以隆前有安國之言，〔五〕左遷為沛郡都尉，遷南郡太守。","sentenceOrder":190},
  {"id":"s_work_han_thu_90_191","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「賈讀曰價。其下亦同。」","sentenceOrder":191},
  {"id":"s_work_han_thu_90_192","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「虞、芮，二國名。文王為西伯，為斷其訟，二國各慚而止也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_90_193","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　蘇林曰：「露奏也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_90_194","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　師古曰：「錯音千故反。」","sentenceOrder":194},
  {"id":"s_work_han_thu_90_195","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　如淳曰：「徵定陶王使在國邸也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_90_196","chapterId":"ch_work_han_thu_90","textTraditional":"王莽少時，慕與隆交，隆不甚附。哀帝崩，莽秉政，使大司徒孔光奏隆前為冀州牧治中山馮太后獄冤陷無辜，不宜處位在中土。本中謁者令史立、侍御史丁玄自典考之，但與隆連名奏事。史立時為中太僕，丁玄泰山太守，及尚書令趙昌譖鄭崇者為河內太守，皆免官，徙合浦。","sentenceOrder":196},
  {"id":"s_work_han_thu_90_197","chapterId":"ch_work_han_thu_90","textTraditional":"何並字子廉，祖父以吏二千石自平輿徙平陵。〔一〕並為郡吏，至大司空掾，事何武。武高其志節，舉能治劇，為長陵令，道不拾遺。","sentenceOrder":197},
  {"id":"s_work_han_thu_90_198","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「平（陵）〔輿〕，汝南之縣也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_90_199","chapterId":"ch_work_han_thu_90","textTraditional":"初，邛成太后外家王氏貴，〔一〕而侍中王林卿通輕俠，傾京師。後坐法免，賓客愈盛，歸長陵上冢，因留飲連日。並恐其犯法，自造門上謁，〔二〕謂林卿曰：「冢間單外，君宜以時歸。」〔三〕林卿曰：「諾。」先是林卿殺婢婿埋冢舍，〔四〕並具知之，以非己時，又見其新免，故不發舉，欲無令留界中而已，即且遣吏奉謁傳送。林卿素驕，慚於賓客，並度其為變，儲兵馬以待之。〔五〕林卿既去，北度涇橋，令騎奴還至寺門，拔刀剝其建鼓。〔六〕並自從吏兵追林卿。行數十里，林卿迫窘，乃令奴冠其冠被其襜褕自代，乘車從童騎，〔七〕身變服從間徑馳去。會日暮追及，收縛冠奴，奴曰：「我非侍中，奴耳。」並心自知已失林卿，乃曰：「王君困，自稱奴，得脫死邪？」叱吏斷頭持還，縣所剝鼓置都亭下，署曰：「故侍中王林卿坐殺人埋冢舍，使奴剝寺門鼓。」〔八〕吏民驚駭。林卿因亡命，眾庶讙譁，以為實死。〔九〕成帝太后以邛成太后愛林卿故，聞之涕泣，為言哀帝。哀帝問狀而善之，遷並隴西太守。","sentenceOrder":199},
  {"id":"s_work_han_thu_90_200","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　應劭曰：「宣帝王皇后父奉光封邛成侯，成帝母亦姓王，故以父爵別之也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_90_201","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「造，至也，音千到反。」","sentenceOrder":201},
  {"id":"s_work_han_thu_90_202","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「單外，言在郊郭之外而單露。」","sentenceOrder":202},
  {"id":"s_work_han_thu_90_203","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　師古曰：「婢婿，外人與其婢姦者也。冢舍，守冢之舍也。」","sentenceOrder":203},
  {"id":"s_work_han_thu_90_204","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　師古曰：「儲，豫備也。度音徒各反。」","sentenceOrder":204},
  {"id":"s_work_han_thu_90_205","chapterId":"ch_work_han_thu_90","textTraditional":"〔六〕　師古曰：「諸官曹之所通呼為寺。建鼓一名植鼓。建，立也。謂植木而旁懸鼓焉。縣有此鼓者，所以召集號令，為開閉之時。","sentenceOrder":205},
  {"id":"s_work_han_thu_90_206","chapterId":"ch_work_han_thu_90","textTraditional":"〔七〕　師古曰：「襜褕，曲裾襌衣也。童騎，童奴之騎也。」","sentenceOrder":206},
  {"id":"s_work_han_thu_90_207","chapterId":"ch_work_han_thu_90","textTraditional":"〔八〕　師古曰：「署謂書表其事也。」","sentenceOrder":207},
  {"id":"s_work_han_thu_90_208","chapterId":"ch_work_han_thu_90","textTraditional":"〔九〕　師古曰：「讙譁，眾議也。讙音許元反。」","sentenceOrder":208},
  {"id":"s_work_han_thu_90_209","chapterId":"ch_work_han_thu_90","textTraditional":"徙潁川太守，代陵陽嚴詡。詡本以孝行為官，謂掾史為師友，有過輒閉閤自責，終不大言。郡中亂，王莽遣使徵詡，官屬數百人為設祖道，詡據地哭。掾史曰：「明府吉徵，不宜若此。」詡曰：「吾哀潁川士，身豈有憂哉！我以柔弱徵，必選剛猛代。代到，將有僵仆者，故相弔耳。」〔一〕詡至，拜為美俗使者。〔二〕是時潁川鍾元為尚書令，領廷尉，用事有權。弟威為郡掾，臧千金。〔三〕並為太守，（故）〔過〕辭鍾廷尉，廷尉免冠為弟請一等之罪，〔四〕願蚤就髡鉗。並曰：「罪在弟身與君律，不在於太守。」元懼，馳遣人呼弟。陽翟輕俠趙季、李款多畜賓客，以氣力漁食閭里，〔五〕至姦人婦女，持吏長短，從橫郡中，〔六〕聞並且至，皆亡去。並下車求勇猛曉文法吏且十人，使文吏治三人獄，武吏往捕之，各有所部。敕曰：「三人非負太守，乃負王法，不得不治。鍾威所犯多在赦前，驅使入函谷關，勿令汙民間；不入關，乃收之。趙、李桀惡，雖遠去，當得其頭，以謝百姓。」鍾威負其兄，止雒陽，〔七〕吏格殺之。亦得趙、李它郡，持頭還，並皆縣頭及其具獄於市。郡中清靜，表善好士，〔八〕見紀潁川，名次黃霸。性清廉，妻子不至官舍。數年，卒。疾病，召丞掾作先令書，〔九〕曰：「告子恢，吾生素餐日久，死雖當得法賻，勿受。〔一０〕葬為小槨，亶容下棺。」〔一一〕恢如父言。王莽擢恢為關都尉。建武中以並孫為郎。","sentenceOrder":209},
  {"id":"s_work_han_thu_90_210","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「僵，偃也。仆，顛也。僵音薑。仆音赴。」","sentenceOrder":210},
  {"id":"s_work_han_thu_90_211","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　文穎曰：「宣美風化使者。」","sentenceOrder":211},
  {"id":"s_work_han_thu_90_212","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　師古曰：「臧謂致罪之臧也。」","sentenceOrder":212},
  {"id":"s_work_han_thu_90_213","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　如淳曰：「減死罪一等。」","sentenceOrder":213},
  {"id":"s_work_han_thu_90_214","chapterId":"ch_work_han_thu_90","textTraditional":"〔五〕　師古曰：「漁者，謂侵奪取之，若漁獵之為也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_90_215","chapterId":"ch_work_han_thu_90","textTraditional":"〔六〕　師古曰：「從音子用反。橫音胡孟反。」","sentenceOrder":215},
  {"id":"s_work_han_thu_90_216","chapterId":"ch_work_han_thu_90","textTraditional":"〔七〕　師古曰：「負謂恃其權力也。」","sentenceOrder":216},
  {"id":"s_work_han_thu_90_217","chapterId":"ch_work_han_thu_90","textTraditional":"〔八〕　師古曰：「好音呼到反。」","sentenceOrder":217},
  {"id":"s_work_han_thu_90_218","chapterId":"ch_work_han_thu_90","textTraditional":"〔九〕　師古曰：「先為遺令也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_90_219","chapterId":"ch_work_han_thu_90","textTraditional":"〔一０〕如淳曰：「公令，吏死官，得法賻。」師古曰：「贈終者布帛曰賻，音附。」","sentenceOrder":219},
  {"id":"s_work_han_thu_90_220","chapterId":"ch_work_han_thu_90","textTraditional":"〔一一〕張晏曰：「禮三重棺。趙簡子曰：『不設屬辟，下卿之罰也。』或曰但下棺，無餘器物也。」師古曰：「言止作小槨，纔容下棺而已，無令高大也。亶讀曰但。」","sentenceOrder":220},
  {"id":"s_work_han_thu_90_221","chapterId":"ch_work_han_thu_90","textTraditional":"贊曰：蓋寬饒為司臣，正色立於朝，雖詩所謂「國之司直」無以加也。〔一〕若采王生之言以終其身，斯近古之賢臣矣。諸葛、劉、鄭雖云狂瞽，有異志焉。孔子曰：「吾未見剛者。」〔二〕以數子之名跡，然毌將汙於冀州，〔三〕孫寶橈於定陵，〔四〕況俗人乎！何並之節，亞尹翁歸云。","sentenceOrder":221},
  {"id":"s_work_han_thu_90_222","chapterId":"ch_work_han_thu_90","textTraditional":"〔一〕　師古曰：「詩鄭風羔裘之篇曰『彼己之子，邦之司直』，言其德美，可主正直之任也。」","sentenceOrder":222},
  {"id":"s_work_han_thu_90_223","chapterId":"ch_work_han_thu_90","textTraditional":"〔二〕　師古曰：「論語稱孔子之言也。言有剛德者為難也。」","sentenceOrder":223},
  {"id":"s_work_han_thu_90_224","chapterId":"ch_work_han_thu_90","textTraditional":"〔三〕　孟康曰：「汙，下也。」師古曰：「毌將隆為冀州牧，與史立、丁元共奏馮太后事，是為汙曲也。汙音一胡反。」","sentenceOrder":224},
  {"id":"s_work_han_thu_90_225","chapterId":"ch_work_han_thu_90","textTraditional":"〔四〕　師古曰：「橈亦曲也。謂受淳于長託而不治杜稚季也。橈音女教反。」","sentenceOrder":225},
  {"id":"s_work_han_thu_90_226","chapterId":"ch_work_han_thu_90","textTraditional":"校勘記","sentenceOrder":226},
  {"id":"s_work_han_thu_90_227","chapterId":"ch_work_han_thu_90","textTraditional":"三二四八頁　四行　言以（行）〔刑〕法成教化也。　景祐、殿本都作「刑」。王先謙說作「刑」是。","sentenceOrder":227},
  {"id":"s_work_han_thu_90_228","chapterId":"ch_work_han_thu_90","textTraditional":"三二四九頁　六行　常恐卒填溝渠，（德）無以報厚〔德〕，　景祐、殿本都作「無以報厚德」。","sentenceOrder":228},
  {"id":"s_work_han_thu_90_229","chapterId":"ch_work_han_thu_90","textTraditional":"三二五一頁一三行　河間宗室〔人〕也，　景祐、殿本都有「人」字。","sentenceOrder":229},
  {"id":"s_work_han_thu_90_230","chapterId":"ch_work_han_thu_90","textTraditional":"三二五六頁　五行　蚤，古（旱）〔早〕字也。　景祐、殿、局本都作「早」，此誤。","sentenceOrder":230},
  {"id":"s_work_han_thu_90_231","chapterId":"ch_work_han_thu_90","textTraditional":"三二五八頁一三行　（也）〔由〕商不任職，致有賊盜，　景祐、殿本都作「由」。","sentenceOrder":231},
  {"id":"s_work_han_thu_90_232","chapterId":"ch_work_han_thu_90","textTraditional":"三二六六頁　六行　平（陵）輿，汝南之縣也。　周壽昌說「平陵」當作「平輿」。按景祐本正作「平輿」。","sentenceOrder":232},
  {"id":"s_work_han_thu_90_233","chapterId":"ch_work_han_thu_90","textTraditional":"三二六八頁　一行　並為太守，（故）〔過〕辭鍾廷尉，　景祐、殿本都作「過」。王先謙說作「過」是。","sentenceOrder":233},
  {"id":"s_work_han_thu_91_1","chapterId":"ch_work_han_thu_91","textTraditional":"蕭望之字長倩，東海蘭陵人也，〔一〕徙杜陵。家世以田為業，至望之，好學，治齊詩，事同縣后倉且十年。以令詣太常受業，〔二〕復事同學博士白奇，〔三〕又從夏侯勝問論語、禮服。〔四〕京師諸儒稱述焉。","sentenceOrder":1},
  {"id":"s_work_han_thu_91_2","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　師古曰：「近代譜諜妄相託附，乃云望之蕭何之後，追次昭穆，流俗學者共祖述焉。但酇侯漢室宗臣，功高位重，子孫胤緒具詳表、傳。長倩鉅儒達學，名節並隆，博覽古今，能言其祖。市朝未變，年載非遙，長老所傳，耳目相接，若其實承何後，史傳寧得弗詳？漢書既不敘論，後人焉所取信？不然之事，斷可識矣。」","sentenceOrder":2},
  {"id":"s_work_han_thu_91_3","chapterId":"ch_work_han_thu_91","textTraditional":"〔二〕　如淳曰：「令郡國官有好文學敬長肅政教者，二千石奏上，與計偕，詣太常受業如弟子也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_91_4","chapterId":"ch_work_han_thu_91","textTraditional":"〔三〕　師古曰：「常同於后倉受業，而奇後為博士。」","sentenceOrder":4},
  {"id":"s_work_han_thu_91_5","chapterId":"ch_work_han_thu_91","textTraditional":"〔四〕　師古曰：「禮之喪服也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_91_6","chapterId":"ch_work_han_thu_91","textTraditional":"是時大將軍霍光秉政，長史丙吉薦儒生王仲翁與望之等數人，皆召見。先是左將軍上官桀與蓋主謀殺光，光既誅桀等，後出入自備。吏民當見者，露索去刀兵，兩吏挾持。〔一〕望之獨不肯聽，自引出閤曰：「不願見。」吏牽持匈匈。光聞之，告吏勿持。望之既至前，說光曰：「將軍以功德輔幼主，將以流大化，致於洽平，〔二〕是以天下之士延頸企踵，爭願自（劾）〔效〕，以輔高明。今士見者皆先露索挾持，恐非周公相成王躬吐握之禮，致白屋之意。」〔三〕於是光獨不除用望之，而仲翁等皆補大將軍史。三歲間，仲翁至光祿大夫給事中，望之以射策甲科為郎，〔四〕署小苑東門候。〔五〕仲翁出入從倉頭廬兒，〔六〕下車趨門，傳呼甚寵，〔七〕顧謂望之曰：「不肯錄錄，反抱關為。」〔八〕望之曰：「各從其志。」","sentenceOrder":6},
  {"id":"s_work_han_thu_91_7","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　師古曰：「索，搜也，露形體而搜也。索音山客反。」","sentenceOrder":7},
  {"id":"s_work_han_thu_91_8","chapterId":"ch_work_han_thu_91","textTraditional":"〔二〕　師古曰：「令太平之化通洽四方也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_91_9","chapterId":"ch_work_han_thu_91","textTraditional":"〔三〕　師古曰：「周公攝政，一沐三握髮，一飯三吐餔，以接天下之士。白屋，謂白蓋之屋以茅覆之，賤人所居。蓋音合。」","sentenceOrder":9},
  {"id":"s_work_han_thu_91_10","chapterId":"ch_work_han_thu_91","textTraditional":"〔四〕　師古曰：「射策者，謂為難問疑義書之於策，量其大小署為甲乙之科，列而置之，不使彰顯。有欲射者，隨其所取得而釋之，以知優劣。射之，言投射也。對策者，顯問以政事經義，令各對之，而觀其（人）〔文〕辭定高下也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_91_11","chapterId":"ch_work_han_thu_91","textTraditional":"〔五〕　師古曰：「署，補署也。門候，主候時而開閉也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_91_12","chapterId":"ch_work_han_thu_91","textTraditional":"〔六〕　師古曰：「皆官府之給賤役者也，解在貢禹傳。」","sentenceOrder":12},
  {"id":"s_work_han_thu_91_13","chapterId":"ch_work_han_thu_91","textTraditional":"〔七〕　師古曰：「趨讀曰趣。趣，嚮也。下車而嚮門，傳聲而呼侍從者，甚有尊寵也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_91_14","chapterId":"ch_work_han_thu_91","textTraditional":"〔八〕　師古曰：「錄錄謂循常也。言望之不能隨例搜索，以（為）〔違〕啎執政，不得大官而守門也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_91_15","chapterId":"ch_work_han_thu_91","textTraditional":"後數年，坐弟犯法，不得宿衛，免歸為郡吏。及御史大夫魏相除望之為屬，察廉為大行治禮丞。","sentenceOrder":15},
  {"id":"s_work_han_thu_91_16","chapterId":"ch_work_han_thu_91","textTraditional":"時大將軍光薨，子禹復為大司馬，兄子山領尚書，〔一〕親屬皆宿衛內侍。地節三年夏，京師雨雹，望之因是上疏，願賜清閒之宴，口陳災異之意。〔二〕宣帝自在民間聞望之名，曰：「此東海蕭生邪？下少府宋畸問狀，〔三〕無有所諱。」望之對，以為「春秋昭公三年大雨雹，是時季氏專權，卒逐昭公。鄉使魯君察於天變，宜亡此害。〔四〕今陛下以聖德居位，思政求賢，堯舜之用心也。然而善祥未臻，陰陽不和，是大臣任政，一姓擅勢之所致也。附枝大者賊本心，私家盛者公室危。〔五〕唯明主躬萬機，選同姓，舉賢材，以為腹心，與參政謀，令公卿大臣朝見奏事，明陳其職，以考功能。如是，則庶事理，公道立，姦邪塞，私權廢矣。」對奏，天子拜望之為謁者。時上初即位，思進賢良，多上書言便宜，輒下望之問狀，高者請丞相御史，〔六〕次者中二千石試事，滿歲以狀聞，〔七〕下者報聞，或罷歸田里，所白處奏皆可。〔八〕累遷諫大夫，丞相司直，歲中三遷，官至二千石。其後霍氏竟謀反誅，望之寖益任用。〔九〕","sentenceOrder":16},
  {"id":"s_work_han_thu_91_17","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　師古曰：「霍山，去病之孫。今云兄子者，轉寫誤爾。」","sentenceOrder":17},
  {"id":"s_work_han_thu_91_18","chapterId":"ch_work_han_thu_91","textTraditional":"〔二〕　師古曰：「閒讀曰閑。」","sentenceOrder":18},
  {"id":"s_work_han_thu_91_19","chapterId":"ch_work_han_thu_91","textTraditional":"〔三〕　師古曰：「畸音居宜反。」","sentenceOrder":19},
  {"id":"s_work_han_thu_91_20","chapterId":"ch_work_han_thu_91","textTraditional":"〔四〕　師古曰：「鄉讀曰嚮。亡讀曰無。」","sentenceOrder":20},
  {"id":"s_work_han_thu_91_21","chapterId":"ch_work_han_thu_91","textTraditional":"〔五〕　師古曰：「本心，樹之本株也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_91_22","chapterId":"ch_work_han_thu_91","textTraditional":"〔六〕　師古曰：「望之以其人所言之狀請於丞相御史，或以奏聞，即見超擢。」","sentenceOrder":22},
  {"id":"s_work_han_thu_91_23","chapterId":"ch_work_han_thu_91","textTraditional":"〔七〕　師古曰：「試令行其所言之事，或以諸它職事試之。」","sentenceOrder":23},
  {"id":"s_work_han_thu_91_24","chapterId":"ch_work_han_thu_91","textTraditional":"〔八〕　師古曰：「當主上之意也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_91_25","chapterId":"ch_work_han_thu_91","textTraditional":"〔九〕　師古曰：「寖，漸也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_91_26","chapterId":"ch_work_han_thu_91","textTraditional":"是時選博士諫大夫通政事者補郡國守相，以望之為平原太守。望之雅意在本朝，遠為郡守，內不自得，乃上疏曰：「陛下哀愍百姓，恐德化之不究，〔一〕悉出諫官以補郡吏，所謂憂其末而忘其本者也。朝無爭臣則不知過，國無達士則不聞善。〔二〕願陛下選明經術，溫故知新，通於幾微謀慮之士以為內臣，與參政事。諸侯聞之，則知國家納諫憂政，亡有闕遺。若此不怠，成康之道其庶幾乎！〔三〕外郡不治，豈足憂哉？」書聞，徵入守少府。宣帝察望之經明持重，論議有餘，材任宰相，〔四〕欲詳試其政事，復以為左馮翊。望之從少府出為左遷，恐有不合意，即移病。〔五〕上聞之，使侍中成都侯金安上諭意曰：「所用皆更治民以考功。〔六〕君前為平原太守日淺，故復試之於三輔，非有所聞也。」〔七〕望之即視事。","sentenceOrder":26},
  {"id":"s_work_han_thu_91_27","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　師古曰：「究，竟也，謂周遍於天下。」","sentenceOrder":27},
  {"id":"s_work_han_thu_91_28","chapterId":"ch_work_han_thu_91","textTraditional":"〔二〕　師古曰：「達士謂達於政事也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_91_29","chapterId":"ch_work_han_thu_91","textTraditional":"〔三〕　師古曰：「周成康二王致太平也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_91_30","chapterId":"ch_work_han_thu_91","textTraditional":"〔四〕　師古曰：「任，堪也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_91_31","chapterId":"ch_work_han_thu_91","textTraditional":"〔五〕　師古曰：「移病謂移書言病。一曰以病而移居。」","sentenceOrder":31},
  {"id":"s_work_han_thu_91_32","chapterId":"ch_work_han_thu_91","textTraditional":"〔六〕　師古曰：「更猶經歷也，音工衡反。」","sentenceOrder":32},
  {"id":"s_work_han_thu_91_33","chapterId":"ch_work_han_thu_91","textTraditional":"〔七〕　師古曰：「所聞謂聞其短失。」","sentenceOrder":33},
  {"id":"s_work_han_thu_91_34","chapterId":"ch_work_han_thu_91","textTraditional":"是歲西羌反，漢遣後將軍征之。京兆尹張敞上書言：「國兵在外，軍以夏發，隴西以北，安定以西，吏民並給轉輸，田事頗廢，素無餘積，雖羌虜以破，來春民食必乏。窮辟之處，買亡所得，〔一〕縣官穀度不足以振之。〔二〕願令諸有罪，非盜受財殺人及犯法不得赦者，皆得以差入穀此八郡贖罪。〔三〕務益致穀以豫備百姓之急。」事下有司，望之與少府李彊議，以為「民函陰陽之氣，有（仁）〔好〕義欲利之心，〔四〕在教化之所助。堯在上，不能去民欲利之心，而能令其欲利不勝其好義也；雖桀在上，不能去民好義之心，而能令其好義不勝其欲利也。故堯、桀之分，在於義利而已，道民不可不慎也。〔五〕今欲令民量粟以贖罪，如此則富者得生，貧者獨死，是貧富異刑而法不壹也。人情，貧窮，父兄囚執，聞出財得以生活，為人子弟者將不顧死亡之患，敗亂之行，以赴財利，求救親戚。一人得生，十人以喪，如此，伯夷之行壞，公綽之名滅。〔六〕政教壹傾，雖有周召之佐，恐不能復。〔七〕古者臧於民，不足則取，有餘則予。詩曰『爰及矜人，哀此鰥寡』，〔八〕上惠下也。又曰『雨我公田，遂及我私』，〔九〕下急上也。今有西邊之役，民失作業，雖戶賦口斂以贍其困乏，〔一０〕古之通義，百姓莫以為非。以死救生，恐未可也。〔一一〕陛下布德施教，教化既成，堯舜亡以加也。今議開利路以傷既成之化，臣竊痛之。」","sentenceOrder":34},
  {"id":"s_work_han_thu_91_35","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　師古曰：「辟讀曰僻也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_91_36","chapterId":"ch_work_han_thu_91","textTraditional":"〔二〕　師古曰：「度音徒各反。」","sentenceOrder":36},
  {"id":"s_work_han_thu_91_37","chapterId":"ch_work_han_thu_91","textTraditional":"〔三〕　師古曰：「差，次也。八郡，即隴西以北，安定以西。」","sentenceOrder":37},
  {"id":"s_work_han_thu_91_38","chapterId":"ch_work_han_thu_91","textTraditional":"〔四〕　師古曰：「函與含同也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_91_39","chapterId":"ch_work_han_thu_91","textTraditional":"〔五〕　師古曰：「道讀曰導。」","sentenceOrder":39},
  {"id":"s_work_han_thu_91_40","chapterId":"ch_work_han_thu_91","textTraditional":"〔六〕　師古曰：「公綽，魯大夫孟公綽也。論語稱孔子曰：『若臧武仲之智，公綽之不欲，卞莊子之勇，冉求之藝，文之以禮樂，可以為成人矣。』」","sentenceOrder":40},
  {"id":"s_work_han_thu_91_41","chapterId":"ch_work_han_thu_91","textTraditional":"〔七〕　師古曰：「召讀曰邵。復音扶目反。」","sentenceOrder":41},
  {"id":"s_work_han_thu_91_42","chapterId":"ch_work_han_thu_91","textTraditional":"〔八〕　師古曰：「小雅鴻雁之詩也。矜人，可哀矜之人，謂貧弱者也。言王者惠澤下及哀矜之人以至鰥寡。」","sentenceOrder":42},
  {"id":"s_work_han_thu_91_43","chapterId":"ch_work_han_thu_91","textTraditional":"〔九〕　師古曰：「小雅大田之詩也。言眾庶喜於時雨，先潤公田，又及私田，是則其心先公後私。雨音于具反。」","sentenceOrder":43},
  {"id":"s_work_han_thu_91_44","chapterId":"ch_work_han_thu_91","textTraditional":"〔一０〕師古曰：「率戶而賦，計口而斂也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_91_45","chapterId":"ch_work_han_thu_91","textTraditional":"〔一一〕師古曰：「子弟竭死以救父兄，令其生也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_91_46","chapterId":"ch_work_han_thu_91","textTraditional":"於是天子復下其議兩府，丞相、御史以難問張敞。敞曰：「少府左馮翊所言，常人之所守耳。昔先帝征四夷，兵行三十餘年，百姓猶不加賦，而軍用給。今羌虜一隅小夷，跳梁於山谷間，漢但令罪人出財減罪以誅之，其名賢於煩擾良民橫興賦斂也。〔一〕又諸盜及殺人犯不道者，百姓所疾苦也，皆不得贖；首匿、見知縱、所不當得為之屬，議者或頗言其法可蠲除，〔二〕今因此令贖，其便明甚，何化之所亂？甫刑之罰，小過赦，薄罪贖，〔三〕有金選之品，〔四〕所從來久矣，何賊之所生？敞備皁衣二十餘年，〔五〕嘗聞罪人贖矣，未聞盜賊起也。竊憐涼州被寇，方秋饒時，民尚有飢乏，病死於道路，況至來春將大困乎！不早慮所以振救之策，而引常經以難，恐後為重責。常人可與守經，未可與權也。敞幸得備列卿，以輔兩府為職，不敢不盡愚。」","sentenceOrder":46},
  {"id":"s_work_han_thu_91_47","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　師古曰：「橫音胡孟反。」","sentenceOrder":47},
  {"id":"s_work_han_thu_91_48","chapterId":"ch_work_han_thu_91","textTraditional":"〔二〕　師古曰：「以其罪輕而法重，故常欲除此科條。」","sentenceOrder":48},
  {"id":"s_work_han_thu_91_49","chapterId":"ch_work_han_thu_91","textTraditional":"〔三〕　師古曰：「呂侯為周穆王司寇，作贖刑之法，謂之呂刑。後改為甫侯，故又稱甫刑也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_91_50","chapterId":"ch_work_han_thu_91","textTraditional":"〔四〕　應劭曰：「選音刷，金銖兩名也。」師古曰：「音刷是也。字本作鋝，鋝即鍰也，其重十一銖二十五分銖之十三，一曰重六兩。呂刑曰：『墨辟疑赦，其罰百鍰；劓辟疑赦，其罰惟倍；剕辟疑赦，其罰倍差；宮辟疑赦，其罰六百鍰；大辟疑赦，其罰千鍰。』是其品也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_91_51","chapterId":"ch_work_han_thu_91","textTraditional":"〔五〕　如淳曰：「雖有五時服，至朝皆著皁衣。」","sentenceOrder":51},
  {"id":"s_work_han_thu_91_52","chapterId":"ch_work_han_thu_91","textTraditional":"望之、彊復對曰：「先帝聖德，賢良在位，作憲垂法，為無窮之規，永惟邊竟之不贍，〔一〕故金布令甲曰〔二〕『邊郡數被兵，離飢寒，〔三〕夭絕天年，父子相失，令天下共給其費』，〔四〕固為軍旅卒暴之事也。〔五〕聞天漢四年，常使死罪人入五十萬錢減死罪一等，豪彊吏民請奪假貣，〔六〕至為盜賊以贖罪。其後姦邪橫暴，群盜並起，〔七〕至攻城邑，殺郡守，充滿山谷，吏不能禁，明詔遣繡衣使者以興兵擊之，〔八〕誅者過半，然後衰止。愚以為此使死罪贖之敗也，故曰不便。」時丞相魏相、御史大夫丙吉亦以為羌虜且破，轉輸略足相給，遂不施敞議。望之為左馮翊三年，京師稱之，遷大鴻臚。","sentenceOrder":52},
  {"id":"s_work_han_thu_91_53","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　師古曰：「惟，思也。竟讀曰境。其下亦同。」","sentenceOrder":53},
  {"id":"s_work_han_thu_91_54","chapterId":"ch_work_han_thu_91","textTraditional":"〔二〕　師古曰：「金布者，令篇名也。其上有府庫金錢布帛之事，因以名篇。令甲者，其篇甲乙之次。」","sentenceOrder":54},
  {"id":"s_work_han_thu_91_55","chapterId":"ch_work_han_thu_91","textTraditional":"〔三〕　師古曰：「離，遭也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_91_56","chapterId":"ch_work_han_thu_91","textTraditional":"〔四〕　師古曰：「同共給之也。自此以上，令甲之文。」","sentenceOrder":56},
  {"id":"s_work_han_thu_91_57","chapterId":"ch_work_han_thu_91","textTraditional":"〔五〕　師古曰：「卒讀曰猝。言此令文專為軍旅猝暴而施設。」","sentenceOrder":57},
  {"id":"s_work_han_thu_91_58","chapterId":"ch_work_han_thu_91","textTraditional":"〔六〕　師古曰：「貣音土得反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_91_59","chapterId":"ch_work_han_thu_91","textTraditional":"〔七〕　師古曰：「橫音胡孟反。」","sentenceOrder":59},
  {"id":"s_work_han_thu_91_60","chapterId":"ch_work_han_thu_91","textTraditional":"〔八〕　師古曰：「軍興之法也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_91_61","chapterId":"ch_work_han_thu_91","textTraditional":"先是烏孫昆彌翁歸靡因長羅侯常惠上一書，〔一〕願以漢外孫元貴靡為嗣，得復尚少主，〔二〕結婚內附，畔去匈奴。詔下公卿議，望之以為烏孫絕域，信其美言，萬里結婚，非長策也。天子不聽。神爵二年，遣長羅侯惠使送公主配元貴靡。未出塞，翁歸靡死，其兄子狂王背約自立。惠從塞下上書，願留少主敦煌郡。惠至烏孫，責以負約，因立元貴靡，還迎少主。詔下公卿議，望之復以為「不可。烏孫持兩端，亡堅約，其效可見。前少主在烏孫四十餘年，恩愛不親密，邊境未以安，此已事之驗也。今少主以元貴靡不得立而還，信無負於四夷，此中國之大福也。少主不止，繇役將興，其原起此。」天子從其議，徵少主還。後烏孫雖分國兩立，以元貴靡為大昆彌，漢遂不復與結婚。","sentenceOrder":61},
  {"id":"s_work_han_thu_91_62","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　師古曰：「昆彌，烏孫之王號也。翁歸靡，其人名也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_91_63","chapterId":"ch_work_han_thu_91","textTraditional":"〔二〕　蘇林曰：「宗室女也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_91_64","chapterId":"ch_work_han_thu_91","textTraditional":"三年，代丙吉為御史大夫。五鳳中匈奴大亂，議者多曰匈奴為害日久，可因其壞亂舉兵滅之。詔遣中朝大司馬車騎將軍韓增、諸吏富平侯張延壽、光祿勳楊惲、太僕戴長樂問望之計策，望之對曰：「春秋晉士匄帥師侵齊，聞齊侯卒，引師而還，君子大其不伐喪，〔一〕以為恩足以服孝子，誼足以動諸侯。前單于慕化鄉善稱弟，〔二〕遣使請求和親，海內欣然，夷狄莫不聞。未終奉約，不幸為賊臣所殺，今而伐之，是乘亂而幸災也，彼必奔走遠遁。不以義動兵，恐勞而無功。宜遣使者弔問，輔其微弱，救其災患，四夷聞之，咸貴中國之仁義。如遂蒙恩得復其位，必稱臣服從，此德之盛也。」上從其議，後竟遣兵護輔呼韓邪單于定其國。","sentenceOrder":64},
  {"id":"s_work_han_thu_91_65","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　師古曰：「士匄，晉大夫范宣子也。春秋公羊傳襄十九年，齊侯環卒，『晉士匄帥師侵齊，至穀，聞齊侯卒，乃還。還者何？善辭也，大其不伐喪也。』」","sentenceOrder":65},
  {"id":"s_work_han_thu_91_66","chapterId":"ch_work_han_thu_91","textTraditional":"〔二〕　蘇林曰：「弟，順也。」師古曰：「鄉讀曰嚮。弟音悌。」","sentenceOrder":66},
  {"id":"s_work_han_thu_91_67","chapterId":"ch_work_han_thu_91","textTraditional":"是時大司農中丞耿壽昌奏設常平倉，上善之，望之非壽昌。〔一〕丞相丙吉年老，上重焉，望之又奏言：「百姓或乏困，盜賊未止，二千石多材下不任職。三公非其人，則三光為之不明，今首歲日月少光，〔二〕咎在臣等。」上以望之意輕丞相，〔三〕乃下侍中建章衛尉金安上、光祿勳楊惲、御史中丞王忠，并詰問望之。〔四〕望之免冠置對，天子繇是不說。〔五〕","sentenceOrder":67},
  {"id":"s_work_han_thu_91_68","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　師古曰：「此望之不知權道。」","sentenceOrder":68},
  {"id":"s_work_han_thu_91_69","chapterId":"ch_work_han_thu_91","textTraditional":"〔二〕　師古曰：「首歲，歲之初。首謂正月也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_91_70","chapterId":"ch_work_han_thu_91","textTraditional":"〔三〕　師古曰：「言三公非其人，又云咎在臣等，是其意毀丞相。」","sentenceOrder":70},
  {"id":"s_work_han_thu_91_71","chapterId":"ch_work_han_thu_91","textTraditional":"〔四〕　師古曰：「三人同共問之。」","sentenceOrder":71},
  {"id":"s_work_han_thu_91_72","chapterId":"ch_work_han_thu_91","textTraditional":"〔五〕　師古曰：「繇讀與由同。說讀曰悅。」","sentenceOrder":72},
  {"id":"s_work_han_thu_91_73","chapterId":"ch_work_han_thu_91","textTraditional":"後丞相司直緐延壽〔一〕奏：「侍中謁者良使（丞）〔承〕制詔望之，望之再拜已。良與望之言，望之不起，因故下手，〔二〕而謂御史曰『良禮不備』。故事丞相病，明日御史大夫輒問病；朝奏事會庭中，差居丞相後，丞相謝，大夫少進，揖。今丞相數病，望之不問病；會庭中，與丞相鈞禮。〔三〕時議事不合意，望之曰：『侯年寧能父我邪！』〔四〕知御史有令不得擅使，望之多使守史自給車馬，之杜陵護視家事。〔五〕少史冠法冠，為妻先引，〔六〕又使賣買，私所附益凡十萬三千。〔七〕案望之大臣，通經術，居九卿之右〔八〕，本朝所仰，至不奉法自修，踞慢不遜攘，〔九〕受所監臧二百五十以上，〔一０〕請逮捕繫治。」上於是策望之曰：「有司奏君責使者禮，遇丞相亡禮，廉聲不聞，敖慢不遜，〔一一〕亡以扶政，帥先百僚。君不深思，陷于茲穢，朕不忍致君于理，使光祿勳惲策詔，左遷君為太子太傅，授印。其上故印使者，〔一二〕便道之官。君其秉道明孝，正直是與，帥意亡諐，靡有後言。」〔一三〕","sentenceOrder":73},
  {"id":"s_work_han_thu_91_74","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　師古曰：「緐音婆。」","sentenceOrder":74},
  {"id":"s_work_han_thu_91_75","chapterId":"ch_work_han_thu_91","textTraditional":"〔二〕　蘇林曰：「伏地而言也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_91_76","chapterId":"ch_work_han_thu_91","textTraditional":"〔三〕　師古曰：「不為前後之差也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_91_77","chapterId":"ch_work_han_thu_91","textTraditional":"〔四〕　服虔曰：「寧能與吾父同年邪？」","sentenceOrder":77},
  {"id":"s_work_han_thu_91_78","chapterId":"ch_work_han_thu_91","textTraditional":"〔五〕　如淳曰：「漢儀注御史大夫史（旨）〔員〕四十五人，皆六百石，其十五人給事殿中，其餘三十人留守治百事，皆冠法冠。」師古曰：「自給車馬者，令其自乘私車馬也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_91_79","chapterId":"ch_work_han_thu_91","textTraditional":"〔六〕　蘇林曰：「少史，曹史之下者也。」文穎曰：「先引謂導車前。」","sentenceOrder":79},
  {"id":"s_work_han_thu_91_80","chapterId":"ch_work_han_thu_91","textTraditional":"〔七〕　師古曰：「使其史為望之家有所賣買，而史以其私錢增益之，用潤望之也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_91_81","chapterId":"ch_work_han_thu_91","textTraditional":"〔八〕　師古曰：「右，上也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_91_82","chapterId":"ch_work_han_thu_91","textTraditional":"〔九〕　師古曰：「攘，古讓字。」","sentenceOrder":82},
  {"id":"s_work_han_thu_91_83","chapterId":"ch_work_han_thu_91","textTraditional":"〔一０〕師古曰：「二百五十以上者，當時律令坐罪之次，若今律條言一尺以上、一疋以上矣。」","sentenceOrder":83},
  {"id":"s_work_han_thu_91_84","chapterId":"ch_work_han_thu_91","textTraditional":"〔一一〕師古曰：「敖讀曰傲。」","sentenceOrder":84},
  {"id":"s_work_han_thu_91_85","chapterId":"ch_work_han_thu_91","textTraditional":"〔一二〕師古曰：「使者即謂楊惲也。命惲授太傅印，而望之以大夫印上於惲。」","sentenceOrder":85},
  {"id":"s_work_han_thu_91_86","chapterId":"ch_work_han_thu_91","textTraditional":"〔一三〕師古曰：「諐，古愆字。後言謂自申理。」","sentenceOrder":86},
  {"id":"s_work_han_thu_91_87","chapterId":"ch_work_han_thu_91","textTraditional":"望之既左遷，而黃霸代為御史大夫。數月間，丙吉薨，霸為丞相。霸薨，于定國復代焉。望之遂見廢，不得相。為太傅，以論語、禮服授皇太子。","sentenceOrder":87},
  {"id":"s_work_han_thu_91_88","chapterId":"ch_work_han_thu_91","textTraditional":"初，匈奴呼韓邪單于來朝，詔公卿議其儀，丞相霸、御史大夫定國議曰：「聖王之制，施德行禮，先京師而後諸夏，先諸夏而後夷狄。詩云：『率禮不越，遂視既發；相土烈烈，海外有截。』〔一〕陛下聖德充塞天地，〔二〕光被四表，〔三〕匈奴單于鄉風慕化，奉珍朝賀，〔四〕自古未之有也。其禮儀宜如諸侯王，位次在下。」望之以為「單于非正朔所加，故稱敵國，宜待以不臣之禮，位在諸侯王上。外夷稽首稱藩，中國讓而不臣，此則羈縻之誼，謙亨之福也。〔五〕書曰『戎狄荒服』，〔六〕言其來〔服〕，荒忽亡常。如使匈奴後嗣卒有鳥竄鼠伏，闕於朝享，不為畔臣。〔七〕信讓行乎蠻貉，福祚流于亡窮，萬世之長策也。」天子采之，下詔曰：「蓋聞五帝三王教化所不施，不及以政。今匈奴單于稱北藩，朝正朔，朕之不逮，德不能弘覆。其以客禮待之，令單于位在諸侯王上，贊謁稱臣而不名。」","sentenceOrder":88},
  {"id":"s_work_han_thu_91_89","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　師古曰：「商頌長發之詩也。率，循也。遂，遍也。既，盡也。發，行也。相土，契之孫也。烈烈，威也。截，齊也。言殷宗受命為諸侯，能修禮度，無有所踰越也。遍省視之，教令盡行，而相土之威烈烈然盛，四海之外皆整齊。」","sentenceOrder":89},
  {"id":"s_work_han_thu_91_90","chapterId":"ch_work_han_thu_91","textTraditional":"〔二〕　師古曰：「充，實也。塞，滿也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_91_91","chapterId":"ch_work_han_thu_91","textTraditional":"〔三〕　師古曰：「四表，四海之外。」","sentenceOrder":91},
  {"id":"s_work_han_thu_91_92","chapterId":"ch_work_han_thu_91","textTraditional":"〔四〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":92},
  {"id":"s_work_han_thu_91_93","chapterId":"ch_work_han_thu_91","textTraditional":"〔五〕　師古曰：「易謙卦之辭曰『謙，亨，天道下濟而光明，地道卑而上行』，言謙之為德，無所不通也。亨音火庚反。」","sentenceOrder":93},
  {"id":"s_work_han_thu_91_94","chapterId":"ch_work_han_thu_91","textTraditional":"〔六〕　師古曰：「逸書也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_91_95","chapterId":"ch_work_han_thu_91","textTraditional":"〔七〕　師古曰：「卒，終也。本以客禮待之，若後不來，非叛臣。」","sentenceOrder":95},
  {"id":"s_work_han_thu_91_96","chapterId":"ch_work_han_thu_91","textTraditional":"及宣帝寢疾，選大臣可屬者，〔一〕引外屬侍中樂陵侯史高、太子太傅望之、少傅周堪至禁中，拜高為大司馬車騎將軍，望之為前將軍光祿勳，堪為光祿大夫，皆受遺詔輔政，領尚書事。宣帝崩，太子襲尊號，是為孝元帝。望之、堪本以師傅見尊重，上即位，數宴見，言治亂，陳王事。望之選白宗室明經達學散騎諫大夫劉更生給事中，與侍中金敞並拾遺左右。四人同心謀議，勸道上以古制，〔二〕多所欲匡正，上甚鄉納之。〔三〕","sentenceOrder":96},
  {"id":"s_work_han_thu_91_97","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　師古曰：「屬音之欲反。」","sentenceOrder":97},
  {"id":"s_work_han_thu_91_98","chapterId":"ch_work_han_thu_91","textTraditional":"〔二〕　師古曰：「道讀曰導。」","sentenceOrder":98},
  {"id":"s_work_han_thu_91_99","chapterId":"ch_work_han_thu_91","textTraditional":"〔三〕　師古曰：「鄉讀曰嚮，意信嚮之而納用其言。」","sentenceOrder":99},
  {"id":"s_work_han_thu_91_100","chapterId":"ch_work_han_thu_91","textTraditional":"初，宣帝不甚從儒術，任用法律，而中書宦官用事。中書令弘恭、石顯久典樞機，明習文法，亦與車騎將軍高為表裏，論議常獨持故事，不從望之等。恭、顯又時傾仄見詘。〔一〕望之以為中書政本，宜以賢明之選，自武帝游宴後庭，故用宦者，非國舊制，又違古不近刑人之義，〔二〕白欲更置士人，繇是大與高、恭、顯忤。〔三〕上初即位，謙讓重改作，〔四〕議久不定，出劉更生為宗正。","sentenceOrder":100},
  {"id":"s_work_han_thu_91_101","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　文穎曰：「恭、顯心不自安也。」師古曰：「文說非也。言其不能持正，故議論大事見詘於天子也。仄，古側字。」","sentenceOrder":101},
  {"id":"s_work_han_thu_91_102","chapterId":"ch_work_han_thu_91","textTraditional":"〔二〕　師古曰：「禮曰『刑人不在君側』也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_91_103","chapterId":"ch_work_han_thu_91","textTraditional":"〔三〕　師古曰：「繇讀與由同。忤謂相違逆也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_91_104","chapterId":"ch_work_han_thu_91","textTraditional":"〔四〕　師古曰：「重，難也。未欲更置士人於中書也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_91_105","chapterId":"ch_work_han_thu_91","textTraditional":"望之、堪數薦名儒茂材以備諫官。會稽鄭朋陰欲附望之，上疏言車騎將軍高遣客為姦利郡國，及言許、史子弟罪過。章視周堪，〔一〕堪白令朋待詔金馬門。朋奏記望之曰：「將軍體周召之德，秉公綽之質，有卞莊之威。〔二〕至乎耳順之年，〔三〕履折衝之位，號至將軍，誠士之高致也。窟穴黎庶莫不懽喜，咸曰將軍其人也。〔四〕今將軍規橅云若管晏而休，遂行日仄至周召乃留乎？〔五〕若管晏而休，則下走將歸延陵之皋，〔六〕修農圃之疇，〔七〕畜雞種黍，俟見二子，沒齒而已矣。〔八〕如將軍昭然度行，積思塞邪枉之險蹊，宣中庸之常政，〔九〕興周召之遺業，親日仄之兼聽，則下走其庶幾願竭區區，底厲鋒鍔，〔一０〕奉萬分之一。」望之見納朋，接待以意。〔一一〕朋數稱述望之，短車騎將軍。〔一二〕言許、史過失。","sentenceOrder":105},
  {"id":"s_work_han_thu_91_106","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　師古曰：「視讀曰示。以朋所奏之章示堪也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_91_107","chapterId":"ch_work_han_thu_91","textTraditional":"〔二〕　師古曰：「周謂周公旦。召謂召公奭。公綽，孟公綽也，廉正寡欲。卞莊子，魯卞邑大夫，蓋勇士也。召讀曰邵。」","sentenceOrder":107},
  {"id":"s_work_han_thu_91_108","chapterId":"ch_work_han_thu_91","textTraditional":"〔三〕　師古曰：「論語孔子曰『六十而耳順』。」","sentenceOrder":108},
  {"id":"s_work_han_thu_91_109","chapterId":"ch_work_han_thu_91","textTraditional":"〔四〕　師古曰：「國家委任，誠得其人也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_91_110","chapterId":"ch_work_han_thu_91","textTraditional":"〔五〕　師古曰：「問望之立意當趣如管晏而止，為欲恢廓其道，日昃不食，追周召之蹟然後已乎？橅讀曰模。其字從木。」","sentenceOrder":110},
  {"id":"s_work_han_thu_91_111","chapterId":"ch_work_han_thu_91","textTraditional":"〔六〕　應劭曰：「下走，僕也。」張晏曰：「吳公子札食邑延陵，薄吳王之行，棄國而耕於皋澤。朋云望之所為若但如管晏，則不處漢朝，將歸會稽，尋延陵之軌，隱耕皋澤之中也。」師古曰：「下走者，自謙言趨走之役也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_91_112","chapterId":"ch_work_han_thu_91","textTraditional":"〔七〕　師古曰：「美田曰疇。」","sentenceOrder":112},
  {"id":"s_work_han_thu_91_113","chapterId":"ch_work_han_thu_91","textTraditional":"〔八〕　師古曰：「論語云：『子路從而後，遇丈人以杖荷蓧，止子路宿，殺雞為黍而食之，見其二子焉。明日子路行，以告。子曰：「隱者也。」使子路反見之，至則行矣。』朋之所云蓋謂此也。俟，古俟字也。俟，待（世）〔也〕。沒齒，終身也。蓧，草器也，音徒釣反。」","sentenceOrder":113},
  {"id":"s_work_han_thu_91_114","chapterId":"ch_work_han_thu_91","textTraditional":"〔九〕　師古曰：「度行，度越常檢而為高行也。蹊，徑，謂道也，音奚。」","sentenceOrder":114},
  {"id":"s_work_han_thu_91_115","chapterId":"ch_work_han_thu_91","textTraditional":"〔一０〕師古曰：「鋒，刃端也。鍔，刃旁也，音五各反。」","sentenceOrder":115},
  {"id":"s_work_han_thu_91_116","chapterId":"ch_work_han_thu_91","textTraditional":"〔一一〕師古曰：「與之相見，納用其說也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_91_117","chapterId":"ch_work_han_thu_91","textTraditional":"〔一二〕師古曰：「短謂毀其短惡也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_91_118","chapterId":"ch_work_han_thu_91","textTraditional":"後朋行傾邪，望之絕不與通。朋與大司農史李宮俱待詔，堪獨白宮為黃門郎。朋，楚士，怨恨，〔一〕更求入許、史，推所言許、史事曰：「皆周堪、劉更生教我，我關東人，何以知此？」於是侍中許章白見朋。朋出揚言曰：「我見，言前將軍小過五，大罪一。中書令在旁，知我言狀。」望之聞之，以問弘恭、石顯。顯、恭恐望之自訟，下於它吏，即挾朋及待詔華龍。〔二〕龍者，宣帝時與張子蟜等待詔，〔三〕以行汙濊不進，〔四〕欲入堪等，堪等不納，故與朋相結。恭、顯令二人告望之等謀欲罷車騎將軍疏退許、史狀，候望之出休日，令朋、龍上之。事下弘恭問狀，望之對曰：「外戚在位多奢淫，欲以匡正國家，非為邪也。」恭、顯奏「望之、堪、更生朋黨相稱舉，數譖訴大臣，毀離親戚，欲以專擅權勢，為臣不忠，誣上不道，請謁者召致廷尉。」時上初即位，不省「謁者召致廷尉」為下獄也，可其奏。後上召堪、更生，曰繫獄。上大驚曰：「非但廷尉問邪？」以責恭、顯，皆叩頭謝。上曰：「令出視事。」恭、顯因使高言：「上新即位，未以德化聞於天下，而先驗師傅，既下九卿大夫獄，宜因決免。」於是制詔丞相御史：「前將軍望之傅朕八年，亡它罪過，今事久遠，識忘難明。〔五〕其赦望之罪，收前將軍光祿勳印綬，及堪、更生皆免為庶人。」而朋為黃門郎。","sentenceOrder":118},
  {"id":"s_work_han_thu_91_119","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　張晏曰：「朋，會稽人，會稽并屬楚。」蘇林曰：「楚人脃急也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_91_120","chapterId":"ch_work_han_thu_91","textTraditional":"〔二〕　師古曰：「華音胡化反。」","sentenceOrder":120},
  {"id":"s_work_han_thu_91_121","chapterId":"ch_work_han_thu_91","textTraditional":"〔三〕　師古曰：「蟜音巨遙反，字或作僑。」","sentenceOrder":121},
  {"id":"s_work_han_thu_91_122","chapterId":"ch_work_han_thu_91","textTraditional":"〔四〕　師古曰：「濊與穢同。」","sentenceOrder":122},
  {"id":"s_work_han_thu_91_123","chapterId":"ch_work_han_thu_91","textTraditional":"〔五〕　師古曰：「言不能盡記，有遺忘者，故難明。」","sentenceOrder":123},
  {"id":"s_work_han_thu_91_124","chapterId":"ch_work_han_thu_91","textTraditional":"後數月，制詔御史：「國之將興，尊師而重傅。故前將軍望之傅朕八年，道以經術，厥功茂焉。〔一〕其賜望之爵關內侯，食邑六百戶，給事中，朝朔望，坐次將軍。」天子方倚欲以為丞相，〔二〕會望之子散騎中郎伋上書訟望之前事，〔三〕事下有司，復奏「望之前所坐明白，無譖訴者，〔四〕而教子上書，稱引亡辜之詩，失大臣體，不敬，請逮捕。」弘恭、石顯等知望之素高節，不詘辱，建白「望之〔五〕前為將軍輔政，欲排退許、史，專權擅朝。幸得不坐，復賜爵邑，與聞政事，〔六〕不悔過服罪，深懷怨望，教子上書，歸非於上，〔七〕自以託師傅，懷終不坐。〔八〕非頗詘望之於牢獄，塞其怏怏心，則聖朝亡以施恩厚。」〔九〕上曰：「蕭太傅素剛，安肯就吏？」顯等曰：「人命至重，望之所坐，語言薄罪，必亡所憂。」上乃可其奏。","sentenceOrder":124},
  {"id":"s_work_han_thu_91_125","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　師古曰：「道讀曰導。茂，美也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_91_126","chapterId":"ch_work_han_thu_91","textTraditional":"〔二〕　師古曰：「倚音於綺反。」","sentenceOrder":126},
  {"id":"s_work_han_thu_91_127","chapterId":"ch_work_han_thu_91","textTraditional":"〔三〕　師古曰：「伋音級。」","sentenceOrder":127},
  {"id":"s_work_han_thu_91_128","chapterId":"ch_work_han_thu_91","textTraditional":"〔四〕　師古曰：「言望之自有罪，非人讒譖而訴之也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_91_129","chapterId":"ch_work_han_thu_91","textTraditional":"〔五〕　師古曰：「建立此議而白之於天子。」","sentenceOrder":129},
  {"id":"s_work_han_thu_91_130","chapterId":"ch_work_han_thu_91","textTraditional":"〔六〕　師古曰：「與讀曰豫。」","sentenceOrder":130},
  {"id":"s_work_han_thu_91_131","chapterId":"ch_work_han_thu_91","textTraditional":"〔七〕　師古曰：「言歸惡於天子也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_91_132","chapterId":"ch_work_han_thu_91","textTraditional":"〔八〕　師古曰：「言恃舊恩，自謂終無罪，坐懷此心。」","sentenceOrder":132},
  {"id":"s_work_han_thu_91_133","chapterId":"ch_work_han_thu_91","textTraditional":"〔九〕　服虔曰：「非，不也。」","sentenceOrder":133},
  {"id":"s_work_han_thu_91_134","chapterId":"ch_work_han_thu_91","textTraditional":"顯等封以付謁者，敕令召望之手付，因令太常急發執金吾車騎馳圍其第。使者至，召望之。望之欲自殺，其夫人止之，以為非天子意。望之以問門下生朱雲。雲者好節士，勸望之自裁。於是望之卬天歎曰：〔一〕「吾嘗備位將相，年踰六十矣，老入牢獄，苟求生活，不亦鄙乎！」字謂雲曰：「游，〔二〕趣和藥來，無久留我死！」〔三〕竟飲鴆自殺。天子聞之驚，拊手曰：「曩固疑其不就牢獄，果然殺吾賢傅！」是時太官方上晝食，上乃卻食，為之涕泣，哀慟左右〔四〕。於是召顯等責問以議不詳。〔五〕皆免冠謝，良久然後已。","sentenceOrder":134},
  {"id":"s_work_han_thu_91_135","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　師古曰：「卬讀曰仰。」","sentenceOrder":135},
  {"id":"s_work_han_thu_91_136","chapterId":"ch_work_han_thu_91","textTraditional":"〔二〕　師古曰：「朱雲字游，呼其字。」","sentenceOrder":136},
  {"id":"s_work_han_thu_91_137","chapterId":"ch_work_han_thu_91","textTraditional":"〔三〕　師古曰：「趣讀曰促。」","sentenceOrder":137},
  {"id":"s_work_han_thu_91_138","chapterId":"ch_work_han_thu_91","textTraditional":"〔四〕　師古曰：「慟，動也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_91_139","chapterId":"ch_work_han_thu_91","textTraditional":"〔五〕　師古曰：「詳，審也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_91_140","chapterId":"ch_work_han_thu_91","textTraditional":"望之有罪死，有司請絕其爵邑。有詔加恩，長子伋嗣為關內侯。天子追念望之不忘，每歲時遣使者祠祭望之冢，終元帝世。望之八子，至大官者育、咸、由。","sentenceOrder":140},
  {"id":"s_work_han_thu_91_141","chapterId":"ch_work_han_thu_91","textTraditional":"育字次君，少以父任為太子庶子。元帝即位，為郎，病免，後為御史。大將軍王鳳以育名父子，著材能，除為功曹，遷謁者，使匈奴副校尉。〔一〕後為茂陵令，會課，育第六。〔二〕而漆令郭舜殿，見責問，〔三〕育為之請，扶風怒曰：「君課第六，裁自脫，〔四〕何暇欲為左右言？」〔五〕及罷出，傳召茂陵令詣後曹，〔六〕當以職事對。〔七〕育徑出曹，書佐隨牽育，育案佩刀曰：「蕭育杜陵男子，何詣曹也！」〔八〕遂趨出，欲去官。明旦，詔召入，拜為司隸校尉。育過扶風府門，官屬掾史數百人拜謁車下。後坐失大將軍指免官。復為中郎將使匈奴。歷冀州、青州兩郡刺史，長水校尉，泰山太守，入守大鴻臚。以鄠名賊梁子政阻山為害，久不伏辜，〔九〕育為右扶風數月，盡誅子政等。坐與定陵侯淳于長厚善免官。","sentenceOrder":141},
  {"id":"s_work_han_thu_91_142","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　師古曰：「時令校尉為使於匈奴而育為之副使，故授副校尉也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_91_143","chapterId":"ch_work_han_thu_91","textTraditional":"〔二〕　師古曰：「如今之考第高下。」","sentenceOrder":143},
  {"id":"s_work_han_thu_91_144","chapterId":"ch_work_han_thu_91","textTraditional":"〔三〕　師古曰：「殿，後也。言有所負，最居下也。殿音丁見反。」","sentenceOrder":144},
  {"id":"s_work_han_thu_91_145","chapterId":"ch_work_han_thu_91","textTraditional":"〔四〕　師古曰：「脫，免也，音吐活反。」","sentenceOrder":145},
  {"id":"s_work_han_thu_91_146","chapterId":"ch_work_han_thu_91","textTraditional":"〔五〕　師古曰：「左右者，言與同列在其左右，若今言旁人也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_91_147","chapterId":"ch_work_han_thu_91","textTraditional":"〔六〕　如淳曰：「賊曹、決曹皆後曹。」","sentenceOrder":147},
  {"id":"s_work_han_thu_91_148","chapterId":"ch_work_han_thu_91","textTraditional":"〔七〕　師古曰：「忿其為漆令言，故欲以職事責之。」","sentenceOrder":148},
  {"id":"s_work_han_thu_91_149","chapterId":"ch_work_han_thu_91","textTraditional":"〔八〕　師古曰：「自言欲免官而去，但是杜陵一白衣男子耳，何須召我詣曹乎？」","sentenceOrder":149},
  {"id":"s_work_han_thu_91_150","chapterId":"ch_work_han_thu_91","textTraditional":"〔九〕　師古曰：「名賊者，自顯其名，無所避匿言其彊也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_91_151","chapterId":"ch_work_han_thu_91","textTraditional":"哀帝時，南郡江中多盜賊，拜育為南郡太守。上以育耆舊名臣，乃以三公使車載育入殿中受策，〔一〕曰：「南郡盜賊群輩為害，朕甚憂之。以太守威信素著，故委南郡太守，之官，其於為民除害，安元元而已，亡拘於小文。」加賜黃金二十斤。育至南郡，盜賊靜。病去官，起家復為光祿大夫執金吾，以壽終於官。","sentenceOrder":151},
  {"id":"s_work_han_thu_91_152","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　孟康曰：「使車，三公奉使之車，若安車也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_91_153","chapterId":"ch_work_han_thu_91","textTraditional":"育為人嚴猛尚威，居官數免，稀遷。少與陳咸、朱博為友，著聞當世。往者有王陽、貢公，故長安語曰「蕭、朱結綬，王、貢彈冠」，言其相薦達也。始育與陳咸俱以公卿子顯名，咸最先進，年十八為左曹，二十餘御史中丞。時朱博尚為杜陵亭長，為咸、育所攀援，入王氏。〔一〕後遂並歷刺史郡守相，及為九卿，而博先至將軍上卿，歷位多於咸、育，遂至丞相。育與博後有隙，不能終，故世以交為難。","sentenceOrder":153},
  {"id":"s_work_han_thu_91_154","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　師古曰：「援，引也，音爰。」","sentenceOrder":154},
  {"id":"s_work_han_thu_91_155","chapterId":"ch_work_han_thu_91","textTraditional":"咸字仲，為丞相史，舉茂材，好畤令，遷淮陽、泗水內史，張掖、弘農、河東太守。所居有跡，數增秩賜金。後免官，復為越騎校尉、護軍都尉、中郎將，使匈奴，至大司農，終官。","sentenceOrder":155},
  {"id":"s_work_han_thu_91_156","chapterId":"ch_work_han_thu_91","textTraditional":"由字子驕，為丞相西曹衛將軍掾，遷謁者，使匈奴副校尉。後舉賢良，為定陶令，遷太原都尉，安定太守。治郡有聲，多稱薦者。初，哀帝為定陶王時，由為定陶令，失王指，頃之，制書免由為庶人。哀帝崩，為復土校尉、京輔左輔都尉，遷江夏太守。平江賊成重等有功，增秩為陳留太守。元始中，作明堂辟雍，大朝諸侯，徵由為大鴻臚，會病，不及賓贊，〔一〕還歸故官，病免。復為中散大夫，終官。家至吏二千石者六七人。","sentenceOrder":156},
  {"id":"s_work_han_thu_91_157","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　師古曰：「贊導九賓之事。」","sentenceOrder":157},
  {"id":"s_work_han_thu_91_158","chapterId":"ch_work_han_thu_91","textTraditional":"贊曰：蕭望之歷位將相，籍師傅之恩，可謂親昵亡間。〔一〕及至謀泄隙開，讒邪搆之，卒為便嬖宦豎所圖，〔二〕哀哉！〔不然〕，望之堂堂，折而不橈，〔三〕身為儒宗，有輔佐之能，近古社稷臣也。","sentenceOrder":158},
  {"id":"s_work_han_thu_91_159","chapterId":"ch_work_han_thu_91","textTraditional":"〔一〕　師古曰：「間，隙也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_91_160","chapterId":"ch_work_han_thu_91","textTraditional":"〔二〕　師古曰：「圖，謀也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_91_161","chapterId":"ch_work_han_thu_91","textTraditional":"〔三〕　師古曰：「橈，曲也，音女教反。」","sentenceOrder":161},
  {"id":"s_work_han_thu_91_162","chapterId":"ch_work_han_thu_91","textTraditional":"校勘記","sentenceOrder":162},
  {"id":"s_work_han_thu_91_163","chapterId":"ch_work_han_thu_91","textTraditional":"三二七二頁　三行　爭願自（劾）〔效〕，　景祐、殿本都作「效」，此誤。","sentenceOrder":163},
  {"id":"s_work_han_thu_91_164","chapterId":"ch_work_han_thu_91","textTraditional":"三二七二頁一三行　而觀其（人）〔文〕辭定高下也。　景祐、殿本都作「文」，此誤。","sentenceOrder":164},
  {"id":"s_work_han_thu_91_165","chapterId":"ch_work_han_thu_91","textTraditional":"三二七三頁　一行　言望之不能隨例搜索，以（為）〔違〕牾執政，　景祐、殿、局本都作「違」，此誤。","sentenceOrder":165},
  {"id":"s_work_han_thu_91_166","chapterId":"ch_work_han_thu_91","textTraditional":"三二七五頁一一行　民函陰陽之氣，有（仁）〔好〕義欲利之心，　殿本作「好」。王先謙說作「好」是。","sentenceOrder":166},
  {"id":"s_work_han_thu_91_167","chapterId":"ch_work_han_thu_91","textTraditional":"三二八０頁一六行　侍中謁者良使（丞）〔承〕制詔望之，　景祐、殿本都作「承」。","sentenceOrder":167},
  {"id":"s_work_han_thu_91_168","chapterId":"ch_work_han_thu_91","textTraditional":"三二八一頁一三行　（旨）〔員〕四十五人，　景祐、殿本都作「員」，此誤。","sentenceOrder":168},
  {"id":"s_work_han_thu_91_169","chapterId":"ch_work_han_thu_91","textTraditional":"三二八二頁一五行　言其來〔服〕，荒忽亡常。　景祐、殿本都有「服」字。","sentenceOrder":169},
  {"id":"s_work_han_thu_91_170","chapterId":"ch_work_han_thu_91","textTraditional":"三二八五頁一五行　俟，待（世）〔也〕。　景祐、殿、局本都作「也」，此誤。","sentenceOrder":170},
  {"id":"s_work_han_thu_91_171","chapterId":"ch_work_han_thu_91","textTraditional":"三二九二頁　二行　〔不然〕，望之堂堂，　景祐、殿本都有「不然」二字。","sentenceOrder":171},
  {"id":"s_work_han_thu_92_1","chapterId":"ch_work_han_thu_92","textTraditional":"馮奉世字子明，上黨潞人也，〔一〕徙杜陵。其先馮亭，為韓上黨守。奏攻上黨，絕太行道，〔二〕韓不能守，馮亭乃入上黨城守於趙。〔三〕趙封馮亭為華陽君，與趙將括距秦，〔四〕戰死於長平。宗族繇是分散，〔五〕或留潞，或在趙。在趙者為官帥將，〔六〕官帥將子為代相。及秦滅六國，而馮亭之後馮毋擇、馮去疾、馮劫皆為秦將相焉。","sentenceOrder":1},
  {"id":"s_work_han_thu_92_2","chapterId":"ch_work_han_thu_92","textTraditional":"〔一〕　師古曰：「潞音路。」","sentenceOrder":2},
  {"id":"s_work_han_thu_92_3","chapterId":"ch_work_han_thu_92","textTraditional":"〔二〕　師古曰：「太行，山名，險道所經行也。行音胡郎反。」","sentenceOrder":3},
  {"id":"s_work_han_thu_92_4","chapterId":"ch_work_han_thu_92","textTraditional":"〔三〕　師古曰：「據守上黨城而以降趙。」","sentenceOrder":4},
  {"id":"s_work_han_thu_92_5","chapterId":"ch_work_han_thu_92","textTraditional":"〔四〕　師古曰：「括，趙括，趙奢之子也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_92_6","chapterId":"ch_work_han_thu_92","textTraditional":"〔五〕　師古曰：「繇讀與由同。」","sentenceOrder":6},
  {"id":"s_work_han_thu_92_7","chapterId":"ch_work_han_thu_92","textTraditional":"〔六〕　師古曰：「帥音所類反，字或作師，其義兩通。」","sentenceOrder":7},
  {"id":"s_work_han_thu_92_8","chapterId":"ch_work_han_thu_92","textTraditional":"漢興，文帝時馮唐顯名，即代相子也。至武帝末，奉世以良家子選為郎。昭帝時，以功次補武安長。失官，年三十餘矣，乃學春秋涉大義，讀兵法明習，前將軍韓增奏以為軍司空令。本始中，從軍擊匈奴。軍罷，復為郎。","sentenceOrder":8},
  {"id":"s_work_han_thu_92_9","chapterId":"ch_work_han_thu_92","textTraditional":"先是時，漢數出使西域，多辱命不稱，或貪汙，為外國所苦〔一〕。是時烏孫大有擊匈奴之功，而西域諸國新輯，〔二〕漢方善遇，欲以安之，選可使外國者。前將軍增舉奉世以衛候使持節送大宛諸國客。至伊脩城，〔三〕都尉宋將言莎車與旁國共攻殺漢所置莎車王萬年，〔四〕并殺漢使者奚充國。時匈奴又發兵攻車師城，不能下而去。莎車遣使揚言北道諸國已屬匈奴矣，於是攻劫南道，與歃盟畔漢，從鄯善以西皆絕不通。〔五〕都護鄭吉、校尉司馬意皆在北道諸國間。奉世與其副嚴昌計，以為不亟擊之則莎車日彊，〔六〕其勢難制，必危西域。遂以節諭告諸國王，因發其兵，南北道合萬五千人進擊莎車，攻拔其城。莎車王自殺，傳其首詣長安。諸國悉平，威振西域。奉世乃罷兵以聞。宣帝召見韓增，曰：「賀將軍所舉得其人。」奉世遂西至大宛。大宛聞其斬莎車王，敬之異於它使。得其名馬象龍而還。〔七〕上甚說，〔八〕下議封奉世。〔九〕丞相、將軍皆曰：「春秋之義，大夫出疆，有可以安國家，則顓之可也。〔一０〕奉世功效尤著，宜加爵土之賞。」少府蕭望之獨以奉世奉使有指，〔一一〕而擅矯制違命，發諸國兵，雖有功效，不可以為後法。即封奉世，開後奉使者利，以奉世為比，〔一二〕爭逐發兵，要功萬里之外，〔一三〕為國家生事於夷狄。漸不可長，奉世不宜受封。上善望之議，以奉世為光祿大夫、水衡都尉。","sentenceOrder":9},
  {"id":"s_work_han_thu_92_10","chapterId":"ch_work_han_thu_92","textTraditional":"〔一〕　師古曰：「苦謂困辱之。」","sentenceOrder":10},
  {"id":"s_work_han_thu_92_11","chapterId":"ch_work_han_thu_92","textTraditional":"〔二〕　師古曰：「輯與集同。集，和也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_92_12","chapterId":"ch_work_han_thu_92","textTraditional":"〔三〕　師古曰：「伊脩城在鄯善國，漢於其中置屯田吏士也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_92_13","chapterId":"ch_work_han_thu_92","textTraditional":"〔四〕　師古曰：「莎車，國名；萬年，其（名王）〔王名〕也。莎音素和反。」","sentenceOrder":13},
  {"id":"s_work_han_thu_92_14","chapterId":"ch_work_han_thu_92","textTraditional":"〔五〕　師古曰：「鄯音善。」","sentenceOrder":14},
  {"id":"s_work_han_thu_92_15","chapterId":"ch_work_han_thu_92","textTraditional":"〔六〕　師古曰：「亟，急也，音居力反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_92_16","chapterId":"ch_work_han_thu_92","textTraditional":"〔七〕　師古曰：「言馬形似龍者。」","sentenceOrder":16},
  {"id":"s_work_han_thu_92_17","chapterId":"ch_work_han_thu_92","textTraditional":"〔八〕　師古曰：「說讀曰悅。」","sentenceOrder":17},
  {"id":"s_work_han_thu_92_18","chapterId":"ch_work_han_thu_92","textTraditional":"〔九〕　師古曰：「下其事令議之。」","sentenceOrder":18},
  {"id":"s_work_han_thu_92_19","chapterId":"ch_work_han_thu_92","textTraditional":"〔一０〕師古曰：「顓與專同。」","sentenceOrder":19},
  {"id":"s_work_han_thu_92_20","chapterId":"ch_work_han_thu_92","textTraditional":"〔一一〕師古曰：「本為送諸國客。」","sentenceOrder":20},
  {"id":"s_work_han_thu_92_21","chapterId":"ch_work_han_thu_92","textTraditional":"〔一二〕師古曰：「比音必寐反。」","sentenceOrder":21},
  {"id":"s_work_han_thu_92_22","chapterId":"ch_work_han_thu_92","textTraditional":"〔一三〕師古曰：「逐，競也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_92_23","chapterId":"ch_work_han_thu_92","textTraditional":"元帝即位，為執金吾。上郡屬國歸義降胡萬餘人反去。初，昭帝末，西河屬國胡伊酋若王亦將眾數千人畔，〔一〕奉世輒持節將兵追擊。〔二〕右將軍典屬國常惠薨，奉世代為右將軍典屬國，加諸吏之號。數歲，為光祿勳。","sentenceOrder":23},
  {"id":"s_work_han_thu_92_24","chapterId":"ch_work_han_thu_92","textTraditional":"〔一〕　師古曰：「酋音才由反。」","sentenceOrder":24},
  {"id":"s_work_han_thu_92_25","chapterId":"ch_work_han_thu_92","textTraditional":"〔二〕　師古曰：「言西河、上郡羌胡反畔，子明再追擊之。」","sentenceOrder":25},
  {"id":"s_work_han_thu_92_26","chapterId":"ch_work_han_thu_92","textTraditional":"永光二年秋，隴西羌彡姐旁種反，〔一〕詔召丞相韋玄成、御史大夫鄭弘、大司馬車騎將軍王接、左將軍許嘉、右將軍奉世入議。是（歲時）〔時，歲〕比不登，〔二〕京師穀石二百餘，〔三〕邊郡四百，關東五百。四方饑饉，朝廷方以為憂，而遭羌變。玄成等漠然莫有對者。〔四〕奉世曰：「羌虜近在竟內背畔，〔五〕不以時誅，亡以威制遠蠻。臣願帥師討之。」上問用兵之數，對曰：「臣聞善用兵者，役不再興，糧不三載，故師不久暴而天誅亟決。〔六〕往者數不料敵，〔七〕而師至於折傷；再三發軵，〔八〕則曠日煩費，威武虧矣。今反虜無慮三萬人，〔九〕法當倍用六萬人。然羌戎弓矛之兵耳，器不犀利，〔一０〕可用四萬人，一月足以決。」丞相、御史、兩將軍皆以為民方收斂時，未可多發；萬人屯守之，且足。奉世曰：「不可。天下被饑饉，士馬羸秏，〔一一〕守戰之備久廢不簡，〔一二〕夷狄皆有輕邊吏之心，而羌首難。〔一三〕今以萬人分屯數處，虜見兵少，必不畏懼，戰則挫兵病師，守則百姓不救。如此，怯弱之形見，羌人乘利，諸種並和，〔一四〕相扇而起，臣恐中國之役不得止於四萬，非財幣所能解也。故少發師而曠日，〔一五〕與一舉而疾決，利害相萬也。」〔一六〕固爭之，不能得。有詔益二千人。","sentenceOrder":26},
  {"id":"s_work_han_thu_92_27","chapterId":"ch_work_han_thu_92","textTraditional":"〔一〕　師古曰：「彡音所廉反，又音先廉反。姐音紫。今西羌尚有此姓，而彡音先冉反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_92_28","chapterId":"ch_work_han_thu_92","textTraditional":"〔二〕　師古曰：「比，（類）〔頻〕也。登，成也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_92_29","chapterId":"ch_work_han_thu_92","textTraditional":"〔三〕　師古曰：「一石直二百餘錢也。下皆類此。」","sentenceOrder":29},
  {"id":"s_work_han_thu_92_30","chapterId":"ch_work_han_thu_92","textTraditional":"〔四〕　師古曰：「漠，無聲也，音莫。」","sentenceOrder":30},
  {"id":"s_work_han_thu_92_31","chapterId":"ch_work_han_thu_92","textTraditional":"〔五〕　師古曰：「竟讀曰境。」","sentenceOrder":31},
  {"id":"s_work_han_thu_92_32","chapterId":"ch_work_han_thu_92","textTraditional":"〔六〕　師古曰：「暴，露也。亟，急也，音居力反。」","sentenceOrder":32},
  {"id":"s_work_han_thu_92_33","chapterId":"ch_work_han_thu_92","textTraditional":"〔七〕　師古曰：「料，量也，音聊。」","sentenceOrder":33},
  {"id":"s_work_han_thu_92_34","chapterId":"ch_work_han_thu_92","textTraditional":"〔八〕　如淳曰：「軵，推也。淮南子曰『內郡軵車而餉』。音而隴反。」","sentenceOrder":34},
  {"id":"s_work_han_thu_92_35","chapterId":"ch_work_han_thu_92","textTraditional":"〔九〕　師古曰：「無慮，舉凡之言也，無小思慮而大計也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_92_36","chapterId":"ch_work_han_thu_92","textTraditional":"〔一０〕如淳曰：「今俗刀兵利為犀。」晉灼曰：「犀，堅也。」師古曰：「晉說是。」","sentenceOrder":36},
  {"id":"s_work_han_thu_92_37","chapterId":"ch_work_han_thu_92","textTraditional":"〔一一〕師古曰：「秏，減也，音呼到反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_92_38","chapterId":"ch_work_han_thu_92","textTraditional":"〔一二〕師古曰：「簡謂選揀。」","sentenceOrder":38},
  {"id":"s_work_han_thu_92_39","chapterId":"ch_work_han_thu_92","textTraditional":"〔一三〕師古曰：「言創首為寇難也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_92_40","chapterId":"ch_work_han_thu_92","textTraditional":"〔一四〕師古曰：「和，應也，音胡臥反。」","sentenceOrder":40},
  {"id":"s_work_han_thu_92_41","chapterId":"ch_work_han_thu_92","textTraditional":"〔一五〕師古曰：「曠，空也，空費其日而無功也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_92_42","chapterId":"ch_work_han_thu_92","textTraditional":"〔一六〕師古曰：「相比則為萬倍也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_92_43","chapterId":"ch_work_han_thu_92","textTraditional":"於是遣奉世將萬二千人騎，以將屯為名。〔一〕典屬國任立、護軍都尉韓昌為偏裨，到隴西，分屯三處。典屬國為右軍，屯白石；護軍都尉為前軍，屯臨洮；奉世為中軍，屯首陽西極上。〔二〕前軍到降同阪，〔三〕先遣校尉在前與羌爭地利，又別遣校尉救民於廣陽谷。羌虜盛多，皆為所破，殺兩校尉。奉世具上地形部眾多少之計，願益三萬六千人乃足以決事。書奏，天子大為發兵六萬餘人，拜太常弋陽侯任千秋為奮武將軍以助焉。奉世上言：「願得其眾，不須（復）煩大將。」因陳轉輸之費。","sentenceOrder":43},
  {"id":"s_work_han_thu_92_44","chapterId":"ch_work_han_thu_92","textTraditional":"〔一〕　師古曰：「且云領兵屯田，不言討賊。」","sentenceOrder":44},
  {"id":"s_work_han_thu_92_45","chapterId":"ch_work_han_thu_92","textTraditional":"〔二〕　如淳曰：「西極，山名也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_92_46","chapterId":"ch_work_han_thu_92","textTraditional":"〔三〕　師古曰：「陂，平阪也。降同者，阪名也。阪音府板反。降音下江反。陂音普何反。」","sentenceOrder":46},
  {"id":"s_work_han_thu_92_47","chapterId":"ch_work_han_thu_92","textTraditional":"上於是以璽書勞奉世，且讓之，〔一〕曰：「皇帝問將兵右將軍，〔二〕甚苦暴露。羌虜侵邊境，殺吏民，甚逆天道，故遣將軍帥士大夫行天誅。以將軍材質之美，奮精兵，誅不軌，百下百全之道也。今乃有畔敵之名，〔三〕大為中國羞。以昔不閑習之故邪？〔四〕以恩厚未洽，信約不明也？〔五〕朕甚怪之。上書言羌虜依深山，多徑道，不得不多分部遮要害，須得後發營士，足以決事，部署已定，勢不可復置大將，聞之。前為將軍兵少，不足自守，故發近所騎，日夜詣，〔六〕非為擊也。〔七〕今發三輔、河東、弘農越騎、跡射、佽飛、彀者、羽林孤兒及呼速絫、嗕種，〔八〕方急遣。〔九〕且兵，凶器也，必有成敗者，患策不豫定，料敵不審也，故復遣奮武將軍。兵法曰大將軍出必有偏裨，所以揚威武，參計策，將軍又何疑焉？夫愛吏士，得眾心，舉而無悔，禽敵必全，將軍之職也。若乃轉輸之費，則有司存，將軍勿憂。須奮武將軍兵到，合擊羌虜。」〔一０〕","sentenceOrder":47},
  {"id":"s_work_han_thu_92_48","chapterId":"ch_work_han_thu_92","textTraditional":"〔一〕　師古曰：「讓，責也，責其不須大將。」","sentenceOrder":48},
  {"id":"s_work_han_thu_92_49","chapterId":"ch_work_han_thu_92","textTraditional":"〔二〕　師古曰：「官為右將軍而將兵在外，故謂之將兵右將軍也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_92_50","chapterId":"ch_work_han_thu_92","textTraditional":"〔三〕　如淳曰：「不敢當敵攻戰，為畔敵也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_92_51","chapterId":"ch_work_han_thu_92","textTraditional":"〔四〕　師古曰：「言未嘗當羌虜，不測其形便。」","sentenceOrder":51},
  {"id":"s_work_han_thu_92_52","chapterId":"ch_work_han_thu_92","textTraditional":"〔五〕　師古曰：「言將軍恩惠未洽於士卒，又不能明其約誓，使在下信也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_92_53","chapterId":"ch_work_han_thu_92","textTraditional":"〔六〕　師古曰：「近所，隨近之處也。日夜，言兼行不休息也。詣，詣軍所。」","sentenceOrder":53},
  {"id":"s_work_han_thu_92_54","chapterId":"ch_work_han_thu_92","textTraditional":"〔七〕　師古曰：「助其守。」","sentenceOrder":54},
  {"id":"s_work_han_thu_92_55","chapterId":"ch_work_han_thu_92","textTraditional":"〔八〕　劉德曰：「嗕音辱，羌別種也。彀者，謂能張弩者也。彀音工豆反。絫音力追反。嗕音乃彀反。」","sentenceOrder":55},
  {"id":"s_work_han_thu_92_56","chapterId":"ch_work_han_thu_92","textTraditional":"〔九〕　師古曰：「言令速至軍所也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_92_57","chapterId":"ch_work_han_thu_92","textTraditional":"〔一０〕師古曰：「須，待也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_92_58","chapterId":"ch_work_han_thu_92","textTraditional":"十月，兵畢至隴西。十一月，並進。羌虜大破，斬首數千級，餘皆走出塞。兵未決間，漢復發募士萬人，拜定襄太守韓安國為建威將軍。〔一〕未進，聞羌破，還。上曰：「羌虜破散創艾，亡〔逃〕出塞，〔二〕其罷吏士，頗留屯田，備要害處。」","sentenceOrder":58},
  {"id":"s_work_han_thu_92_59","chapterId":"ch_work_han_thu_92","textTraditional":"〔一〕　師古曰：「自別有此安國，非武帝時人也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_92_60","chapterId":"ch_work_han_thu_92","textTraditional":"〔二〕　師古曰：「創艾謂懲懼也。創音初向反。艾讀曰乂。」","sentenceOrder":60},
  {"id":"s_work_han_thu_92_61","chapterId":"ch_work_han_thu_92","textTraditional":"明年二月，奉世還京師，更為左將軍，光祿勳如故。其後錄功拜爵，下詔曰：「羌虜桀黠，賊害吏民，攻隴西府寺，燔燒置亭，〔一〕絕道橋，甚逆天道。左將軍光祿勳奉世前將兵征討，斬捕首虜八千餘級，鹵馬牛羊以萬數。賜奉世爵關內侯，食邑五百戶，黃金六十斤。」裨將、校尉三十餘人，皆拜。","sentenceOrder":61},
  {"id":"s_work_han_thu_92_62","chapterId":"ch_work_han_thu_92","textTraditional":"〔一〕　師古曰：「置謂置驛之所也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_92_63","chapterId":"ch_work_han_thu_92","textTraditional":"後歲餘，奉世病卒。居爪牙官前後十年，為折衝宿將，功名次趙充國。","sentenceOrder":63},
  {"id":"s_work_han_thu_92_64","chapterId":"ch_work_han_thu_92","textTraditional":"奮武將軍任千秋者，其父宮，昭帝時以丞相徵事捕斬反者左將軍上官桀，封侯，宣帝時為太常，薨。千秋嗣後，復為太常。成帝時，樂昌侯王商代奉世為左將軍，而千秋為右將軍，後亦為左將軍。子孫傳國，至王莽乃絕云。","sentenceOrder":64},
  {"id":"s_work_han_thu_92_65","chapterId":"ch_work_han_thu_92","textTraditional":"奉世死後二年，西域都護甘延壽以誅郅支單于封為列侯。時丞相匡衡亦用延壽矯制生事，據蕭望之前議，以為不當封，而議者咸美其功，上從眾而侯之。於是杜欽上疏，追訟奉世前功曰：「前莎車王殺漢使者，約諸國背畔。〔一〕左將軍奉世以衛候便宜發兵誅莎車王，策定城郭，功施邊境。〔二〕議者以奉世奉使有指，春秋之義亡遂事，漢家之法有矯制，〔三〕故不得侯。今匈奴郅支單于殺漢使者，亡保康居，都護延壽發城郭兵屯田吏士四萬餘人以誅斬之，封為列侯。臣愚以為比罪則郅支薄，量敵則莎車眾，用師則奉世寡，計勝則奉世為功於邊境安，慮敗則延壽為禍於國家深。其違命而擅生事同，延壽割地封，而奉世獨不錄。臣聞功同賞異則勞臣疑，罪鈞刑殊則百姓惑；疑生無常，惑生不知所從；亡常則節趨不立，〔四〕不知所從則百姓無所（措）〔錯〕手足〔五〕。奉世圖難忘死，信命殊俗，〔六〕威功白著，為世使表，〔七〕獨抑厭而不揚，〔八〕非聖主所以塞疑厲節之意也。願下有司議。」上以先帝時事，不復錄。","sentenceOrder":65},
  {"id":"s_work_han_thu_92_66","chapterId":"ch_work_han_thu_92","textTraditional":"〔一〕　師古曰：「約謂共為契約。」","sentenceOrder":66},
  {"id":"s_work_han_thu_92_67","chapterId":"ch_work_han_thu_92","textTraditional":"〔二〕　師古曰：「城郭者，謂西域諸國為城郭而居者。」","sentenceOrder":67},
  {"id":"s_work_han_thu_92_68","chapterId":"ch_work_han_thu_92","textTraditional":"〔三〕　師古曰：「無遂事者，謂臨時制宜，前事不可必遂也。漢家之法，擅矯詔命，雖有功勞不加賞也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_92_69","chapterId":"ch_work_han_thu_92","textTraditional":"〔四〕　師古曰：「趨讀曰趣。趣謂意所嚮。」","sentenceOrder":69},
  {"id":"s_work_han_thu_92_70","chapterId":"ch_work_han_thu_92","textTraditional":"〔五〕　師古曰：「錯，置也，音千故反。」","sentenceOrder":70},
  {"id":"s_work_han_thu_92_71","chapterId":"ch_work_han_thu_92","textTraditional":"〔六〕　師古曰：「圖難，謀除國難也。信讀曰伸。」","sentenceOrder":71},
  {"id":"s_work_han_thu_92_72","chapterId":"ch_work_han_thu_92","textTraditional":"〔七〕　師古曰：「白著謂顯明也。表猶首。」","sentenceOrder":72},
  {"id":"s_work_han_thu_92_73","chapterId":"ch_work_han_thu_92","textTraditional":"〔八〕　師古曰：「厭音一涉反。」","sentenceOrder":73},
  {"id":"s_work_han_thu_92_74","chapterId":"ch_work_han_thu_92","textTraditional":"奉世有子男九人，女四人。長女媛以選充後宮，為元帝昭儀，產中山孝王。元帝崩，媛為中山太后，隨王就國。奉世長子譚，太常舉孝廉為郎，功次補天水司馬。〔一〕奉世擊西羌，譚為校尉，隨父從軍有功，未拜病死。譚弟野王、逡、立、參至大官。〔二〕","sentenceOrder":74},
  {"id":"s_work_han_thu_92_75","chapterId":"ch_work_han_thu_92","textTraditional":"〔一〕　如淳曰：「漢注邊郡置都尉及千人、司馬，皆不治民也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_92_76","chapterId":"ch_work_han_thu_92","textTraditional":"〔二〕　師古曰：「逡音千旬反。」","sentenceOrder":76},
  {"id":"s_work_han_thu_92_77","chapterId":"ch_work_han_thu_92","textTraditional":"野王字君卿，受業博士，通詩。少以父任為太子中庶子。年十八，上書願試守長安令。宣帝奇其志，問丞相魏相，相以為不可許。後以功次補當陽長，遷為櫟陽令，徙夏陽令。元帝時，遷隴西太守，以治行高，入為左馮翊。歲餘，而池陽令並素行貪汙，輕野王外戚年少，治行不改。野王部督郵掾祋祤趙都〔一〕案驗，得其主守盜十金罪，收捕。並不首吏，〔二〕都格殺。並家上書陳冤，事下廷尉。都詣吏自殺以明野王，京師稱其威信，遷為大鴻臚。","sentenceOrder":77},
  {"id":"s_work_han_thu_92_78","chapterId":"ch_work_han_thu_92","textTraditional":"〔一〕　師古曰：「都，祋祤人而為掾也。祋音丁活反，又音丁外反。祤音許羽反。」","sentenceOrder":78},
  {"id":"s_work_han_thu_92_79","chapterId":"ch_work_han_thu_92","textTraditional":"〔二〕　師古曰：「不首吏，謂不伏從收捕也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_92_80","chapterId":"ch_work_han_thu_92","textTraditional":"數年，御史大夫李延壽病卒，在位多舉野王。上使尚書選第中二千石，〔一〕而野王行能第一。上曰：「吾用野王為三公，後世必謂我私後宮親屬，以野王為比。」〔二〕乃下詔曰：「剛彊堅固，確然亡欲，大鴻臚野王是也。心辨善辭，可使四方，少府五鹿充宗是也。廉絜節儉，太子少傅張譚是也。其以少傅為御史大夫。」上繇下第而用譚，〔三〕越次避嫌不用野王，以昭儀兄故也。野王乃歎曰：「人皆以女寵貴，我兄弟獨以賤！」野王雖不為三公，甚見器重，有名當世。","sentenceOrder":80},
  {"id":"s_work_han_thu_92_81","chapterId":"ch_work_han_thu_92","textTraditional":"〔一〕　師古曰：「定其高下之差也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_92_82","chapterId":"ch_work_han_thu_92","textTraditional":"〔二〕　師古曰：「比，例也，音必寐反。」","sentenceOrder":82},
  {"id":"s_work_han_thu_92_83","chapterId":"ch_work_han_thu_92","textTraditional":"〔三〕　師古曰：「繇讀與由同。」","sentenceOrder":83},
  {"id":"s_work_han_thu_92_84","chapterId":"ch_work_han_thu_92","textTraditional":"成帝立，有司奏野王王舅，不宜備九卿。以秩出為上郡太守〔一〕，加賜黃金百斤。朔方剌史蕭育奏封事，薦言「野王行能高妙，內足與圖身，外足以慮化。〔二〕竊惜野王懷國之寶，而不得陪朝廷與朝者並。野王前以王舅出，以賢復入，明國家樂進賢也。」上自為太子時聞知野王。會其病免，復以故二千石使行河隄，因拜為琅邪太守。是時，成帝長舅陽平侯王鳳為大司馬大將軍，輔政八九年矣，時數有災異，京兆尹王章譏鳳顓權不可任用，薦野王代鳳。上初納其言，而後誅章，語在元后傳。於是野王懼不自安，遂病，滿三月賜告，與妻子歸杜陵就醫藥。大將軍鳳風御史中丞劾奏野王〔三〕賜告養病而私自便，〔四〕持虎符出界歸家，奉詔不敬。杜欽時在大將軍莫府，欽素高野王父子行能，奏記於鳳，為野王言曰：「竊見令曰，吏二千石告，過長安謁，〔五〕不分別予賜。〔六〕今有司以為予告得歸，賜告不得，是一律兩科，失省刑之意。〔七〕夫三最予告，令也〔八〕；病滿三月賜告，詔恩也。令告則得，詔恩則不得，失輕重之差。又二千石病賜告得歸有故事，不得去郡亡著令。〔九〕傳曰：『賞疑從予，所以廣恩勸功也；〔一０〕罰疑從去，所以慎刑，闕難知也。』〔一一〕今釋令與故事而假不敬之法，〔一二〕甚違闕疑從去之意。即以二千石守千里之地，任兵馬之重，不宜去郡，將以制刑為後法者，則野王之罪，在未制令前也。刑賞大信，不可不慎。」鳳不聽，竟免野王。郡國二千石病賜告不得歸家，自此始。","sentenceOrder":84},
  {"id":"s_work_han_thu_92_85","chapterId":"ch_work_han_thu_92","textTraditional":"〔一〕　如淳曰：「以鴻臚秩為太守。」","sentenceOrder":85},
  {"id":"s_work_han_thu_92_86","chapterId":"ch_work_han_thu_92","textTraditional":"〔二〕　師古曰：「圖，謀；慮，思也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_92_87","chapterId":"ch_work_han_thu_92","textTraditional":"〔三〕　師古曰：「風讀曰諷。」","sentenceOrder":87},
  {"id":"s_work_han_thu_92_88","chapterId":"ch_work_han_thu_92","textTraditional":"〔四〕　師古曰：「便，安也，音頻面反。」","sentenceOrder":88},
  {"id":"s_work_han_thu_92_89","chapterId":"ch_work_han_thu_92","textTraditional":"〔五〕　如淳曰：「謁者，自白得告也。律，吏二千石以上告歸歸寧，道不過行在所者，便道之官無辭。」","sentenceOrder":89},
  {"id":"s_work_han_thu_92_90","chapterId":"ch_work_han_thu_92","textTraditional":"〔六〕　如淳曰：「予，予告也。賜，賜告也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_92_91","chapterId":"ch_work_han_thu_92","textTraditional":"〔七〕　師古曰：「省，減也，音所領反。」","sentenceOrder":91},
  {"id":"s_work_han_thu_92_92","chapterId":"ch_work_han_thu_92","textTraditional":"〔八〕　師古曰：「在官連有三最，則得予告也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_92_93","chapterId":"ch_work_han_thu_92","textTraditional":"〔九〕　如淳曰：「律施行無不得去郡之文也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_92_94","chapterId":"ch_work_han_thu_92","textTraditional":"〔一０〕師古曰：「疑當賞不當賞則與之，疑厚薄則從厚。」","sentenceOrder":94},
  {"id":"s_work_han_thu_92_95","chapterId":"ch_work_han_thu_92","textTraditional":"〔一一〕師古曰：「疑當罰不當罰則赦之，疑輕重則從輕。」","sentenceOrder":95},
  {"id":"s_work_han_thu_92_96","chapterId":"ch_work_han_thu_92","textTraditional":"〔一二〕師古曰：「釋，廢棄也。假謂假託法律而致其罪。」","sentenceOrder":96},
  {"id":"s_work_han_thu_92_97","chapterId":"ch_work_han_thu_92","textTraditional":"初，野王嗣父爵為關內侯，免歸。數年，年老，終于家。子座嗣爵，〔一〕至孫坐中山太后事絕。","sentenceOrder":97},
  {"id":"s_work_han_thu_92_98","chapterId":"ch_work_han_thu_92","textTraditional":"〔一〕　師古曰：「座音才戈反。」","sentenceOrder":98},
  {"id":"s_work_han_thu_92_99","chapterId":"ch_work_han_thu_92","textTraditional":"逡字子產，通易。太常察孝廉為郎，補謁者。建昭中，選為復土校尉。光祿勳于永舉茂材，為美陽令。功次遷長樂屯衛司馬，清河都尉，隴西太守。治行廉平，年四十餘卒。為都尉時，言河隄方略，在溝洫志。","sentenceOrder":99},
  {"id":"s_work_han_thu_92_100","chapterId":"ch_work_han_thu_92","textTraditional":"立字聖卿，通春秋。以父任為郎，稍遷諸曹。竟寧中，以王舅出為五原屬國都尉。數年，遷五原太守，徙西河、上郡。立居職公廉，治行略與野王相似，而多知有恩貸，〔一〕好為條教。吏民嘉美野王、立相代為太守，歌之曰：「大馮君，小馮君，兄弟繼踵相因循，聰明賢知惠吏民，政如魯、衛德化鈞，周公、康叔猶二君。」〔二〕後遷為東海太守，下溼病痺。〔三〕天子聞之，徙立為太原太守。更歷五郡，〔四〕所居有跡。年老卒官。","sentenceOrder":100},
  {"id":"s_work_han_thu_92_101","chapterId":"ch_work_han_thu_92","textTraditional":"〔一〕　師古曰：「貸音吐戴反。」","sentenceOrder":101},
  {"id":"s_work_han_thu_92_102","chapterId":"ch_work_han_thu_92","textTraditional":"〔二〕　師古曰：「論語稱孔子曰『魯衛之政，兄弟也。』言周公、康叔親則兄弟，治國之政又相似。」","sentenceOrder":102},
  {"id":"s_work_han_thu_92_103","chapterId":"ch_work_han_thu_92","textTraditional":"〔三〕　師古曰：「東海土地下溼，故立病痺也。痺音必寐反。」","sentenceOrder":103},
  {"id":"s_work_han_thu_92_104","chapterId":"ch_work_han_thu_92","textTraditional":"〔四〕　師古曰：「更音工衡反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_92_105","chapterId":"ch_work_han_thu_92","textTraditional":"參字叔平，學通尚書。少為黃門郎給事中，宿衛十餘年。參為人矜嚴，好修容儀，進退恂恂，甚可觀也。〔一〕參，昭儀少弟，行又敕備，以嚴見憚，終不得親近侍帷幄。竟寧中，以王舅出補渭陵食官令。〔二〕以數病徙為寢中郎，〔三〕有詔勿事。〔四〕陽朔中，中山王來朝，參擢為上河農都尉。〔五〕病免官，復為渭陵寢中郎。永始中，超遷代郡太守。以邊郡道遠，徙為安定太守。數歲，病免，復為諫大夫，使領護左馮翊都水。綏和中，立定陶王為皇太子，以中山王見廢，〔六〕故封王舅參為宜鄉侯，以慰王意。參之國，上書願至中山見王、太后。行未到而王薨。王病時，上奏願貶參爵以關內侯食邑留長安。上憐之，下詔曰：「中山孝王短命早薨，願以舅宜鄉侯參為關內侯，歸家，朕甚愍之。其還參京師，以列侯奉朝請。」五侯皆敬憚之。〔七〕丞相翟方進亦甚重焉，數謂參：「物禁太甚。〔八〕君侯以王舅見廢，不得在公卿位，今五侯至尊貴也，與之並列，宜少詘節卑體，視有所宗。〔九〕而君侯盛修容貌以威嚴加之，此非所以下五侯而自益者也。」〔一０〕參性好禮儀，終不改其恆操。頃之，哀帝即位，帝祖母傅太后用事，追怨參姊中山太后，陷以祝詛大逆大罪，語在外戚傳。參以同產當相坐，謁者承制召參詣廷尉，參自殺。且死，仰天歎曰：「參父子兄弟皆備大位，身至封侯，今被惡名而死，姊弟不敢自惜，傷無以見先人於地下！」死者十七人，眾莫不憐之。宗族徙歸故郡。","sentenceOrder":105},
  {"id":"s_work_han_thu_92_106","chapterId":"ch_work_han_thu_92","textTraditional":"〔一〕　師古曰：「恂恂，謹信之貌，音荀。」","sentenceOrder":106},
  {"id":"s_work_han_thu_92_107","chapterId":"ch_work_han_thu_92","textTraditional":"〔二〕　如淳曰：「給陵上祭祀之事。」","sentenceOrder":107},
  {"id":"s_work_han_thu_92_108","chapterId":"ch_work_han_thu_92","textTraditional":"〔三〕　師古曰：「亦渭陵之寢郎也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_92_109","chapterId":"ch_work_han_thu_92","textTraditional":"〔四〕　張晏曰：「不與勞役，職事擾之。」師古曰：「雖居其官，不親職也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_92_110","chapterId":"ch_work_han_thu_92","textTraditional":"〔五〕　師古曰：「上河在西河富平，於此為農都尉。」","sentenceOrder":110},
  {"id":"s_work_han_thu_92_111","chapterId":"ch_work_han_thu_92","textTraditional":"〔六〕　師古曰：「見廢，謂不得為漢嗣也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_92_112","chapterId":"ch_work_han_thu_92","textTraditional":"〔七〕　師古曰：「王氏五侯也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_92_113","chapterId":"ch_work_han_thu_92","textTraditional":"〔八〕　師古曰：「言萬物之禁，在於太甚，人道亦當隨時，不宜獨異。」","sentenceOrder":113},
  {"id":"s_work_han_thu_92_114","chapterId":"ch_work_han_thu_92","textTraditional":"〔九〕　師古曰：「視讀曰示。宗，尊也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_92_115","chapterId":"ch_work_han_thu_92","textTraditional":"〔一０〕師古曰：「下音胡亞反。」","sentenceOrder":115},
  {"id":"s_work_han_thu_92_116","chapterId":"ch_work_han_thu_92","textTraditional":"贊曰：詩稱「抑抑威儀，惟德之隅」。〔一〕宜鄉侯參鞠躬履方，擇地而行，〔二〕可謂淑人君子，然卒死於非罪，不能自免，〔三〕哀哉！讒邪交亂，貞良被害，自古而然。故伯奇放流，〔四〕孟子宮刑，〔五〕申生雉經，〔六〕屈原赴湘，〔七〕小弁之詩作，離騷之辭興。〔八〕經曰：「心之憂矣，涕既隕之。」〔九〕馮參姊弟，亦云悲矣！","sentenceOrder":116},
  {"id":"s_work_han_thu_92_117","chapterId":"ch_work_han_thu_92","textTraditional":"〔一〕　師古曰：「大雅抑之詩也。抑抑，密也。隅，廉也。言有密靜之德，審於威儀，則其持心有廉隅。」","sentenceOrder":117},
  {"id":"s_work_han_thu_92_118","chapterId":"ch_work_han_thu_92","textTraditional":"〔二〕　師古曰：「鞠躬，謹敬貌。履方，踐方直之道也。鞠音居六反。」","sentenceOrder":118},
  {"id":"s_work_han_thu_92_119","chapterId":"ch_work_han_thu_92","textTraditional":"〔三〕　師古曰：「卒，終也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_92_120","chapterId":"ch_work_han_thu_92","textTraditional":"〔四〕　師古曰：「說苑云王國子前母子伯奇，後母子伯封，兄弟相重。後母欲令其子立為太子，乃譖伯奇，而王信之，乃放伯奇也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_92_121","chapterId":"ch_work_han_thu_92","textTraditional":"〔五〕　張晏曰：「寺人孟子，賢者，被讒見宮刑，作巷伯之詩也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_92_122","chapterId":"ch_work_han_thu_92","textTraditional":"〔六〕　師古曰：「國語云晉獻公黜太子申生，乃雉經于新城之廟。蓋為俛頸閉氣而死，若雉之為。」","sentenceOrder":122},
  {"id":"s_work_han_thu_92_123","chapterId":"ch_work_han_thu_92","textTraditional":"〔七〕　師古曰：「楚辭漁父之篇云屈原曰『寧赴湘流，葬於江魚腹中』也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_92_124","chapterId":"ch_work_han_thu_92","textTraditional":"〔八〕　師古曰：「小弁，小雅篇名也，太子之傅作焉，刺幽王信讒，黜申后而放太子宜咎也。離騷經，屈原所作也。離，遭也。騷，憂也。遭憂而作辭。弁音盤。」","sentenceOrder":124},
  {"id":"s_work_han_thu_92_125","chapterId":"ch_work_han_thu_92","textTraditional":"〔九〕　師古曰：「即小弁之詩也。隕，墜也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_92_126","chapterId":"ch_work_han_thu_92","textTraditional":"校勘記","sentenceOrder":126},
  {"id":"s_work_han_thu_92_127","chapterId":"ch_work_han_thu_92","textTraditional":"三二九五頁　五行　萬年，其（名王）〔王名〕也。　景祐、殿本都作「王名」。王先謙說作「王名」是。","sentenceOrder":127},
  {"id":"s_work_han_thu_92_128","chapterId":"ch_work_han_thu_92","textTraditional":"三二九六頁　五行　是（歲時）〔時，歲〕比不登，　景祐、殿本都作「時歲」，此誤倒。","sentenceOrder":128},
  {"id":"s_work_han_thu_92_129","chapterId":"ch_work_han_thu_92","textTraditional":"三二九七頁　二行　比，（類）〔頻〕也。　景祐、殿本都作「頻」，此誤。","sentenceOrder":129},
  {"id":"s_work_han_thu_92_130","chapterId":"ch_work_han_thu_92","textTraditional":"三二九八頁　五行　不須（復）煩大將。　景祐、殿本都無「復」字。","sentenceOrder":130},
  {"id":"s_work_han_thu_92_131","chapterId":"ch_work_han_thu_92","textTraditional":"三二九九頁一五行　羌虜破散創艾，亡〔逃〕出塞。　景祐、殿本都有「逃」字。","sentenceOrder":131},
  {"id":"s_work_han_thu_92_132","chapterId":"ch_work_han_thu_92","textTraditional":"三三０一頁　五行　不知所從則百姓無所（措）〔錯〕手足。　殿本作「錯」。王先謙說，據注，正文「措」當作「錯」。","sentenceOrder":132},
  {"id":"s_work_han_thu_93_1","chapterId":"ch_work_han_thu_93","textTraditional":"孝宣皇帝五男。許皇后生孝元帝，張婕妤生淮陽憲王欽，衛婕妤生楚孝王囂，〔一〕公孫婕妤生東平思王宇，戎婕妤生中山哀王竟。","sentenceOrder":1},
  {"id":"s_work_han_thu_93_2","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「囂音敖。」","sentenceOrder":2},
  {"id":"s_work_han_thu_93_3","chapterId":"ch_work_han_thu_93","textTraditional":"淮陽憲王欽，元康三年立，母張婕妤有寵於宣帝。霍皇后廢後，上欲立張婕妤為后。久之，懲艾霍氏欲害皇太子，〔一〕乃更選後宮無子而謹慎者，乃立長陵王婕妤為后，令母養太子。后無寵，希御見，唯張婕妤最幸。而憲王壯大，好經書法律，聰達有材，帝甚愛之。太子寬仁，喜儒術，〔二〕上數嗟歎憲王，曰：「真我子也！」常有意欲立張婕妤與憲王，然用太子起於微細，上少依倚許氏，〔三〕及即位而許后以殺死，太子蚤失母，故弗忍也。〔四〕久之，上以故丞相韋賢子玄成陽狂讓侯兄，經明行高，稱於朝廷，乃召拜玄成為淮陽中尉，欲感諭憲王，輔以推讓之臣，由是太子遂安。宣帝崩，元帝即位，乃遣憲王之國。","sentenceOrder":3},
  {"id":"s_work_han_thu_93_4","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「艾讀曰乂。乂，創也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_93_5","chapterId":"ch_work_han_thu_93","textTraditional":"〔二〕　師古曰：「喜，好也，音許吏反。」","sentenceOrder":5},
  {"id":"s_work_han_thu_93_6","chapterId":"ch_work_han_thu_93","textTraditional":"〔三〕　師古曰：「倚音於起反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_93_7","chapterId":"ch_work_han_thu_93","textTraditional":"〔四〕　師古曰：「蚤，古早字也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_93_8","chapterId":"ch_work_han_thu_93","textTraditional":"時張婕妤已卒，憲王有外祖母，舅張博兄弟三人歲至淮陽見親，〔一〕輒受王賜。後王上書：請徙外家張氏於國，博上書：願留守墳墓，獨不徙。王恨之。後博至淮陽，王賜之少。博言：「負責數百萬，〔二〕願王為償。」王不許。博辭去，令弟光恐（王）云王遇大人益解，〔三〕博欲上書為大人乞骸骨去。王乃遣人持黃金五十斤送博。博喜，還書謝，〔四〕為諂語盛稱譽王，因言：「當今朝廷無賢臣，災變數見，足為寒心。萬姓咸歸望於大王，大王奈何恬然〔五〕不求入朝見，輔助主上乎？」使弟光數說王宜聽博計，令於京師說用事貴人為王求朝。王不納其言。","sentenceOrder":8},
  {"id":"s_work_han_thu_93_9","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「憲王外祖母隨王在淮陽，博等每來謁見其母。」","sentenceOrder":9},
  {"id":"s_work_han_thu_93_10","chapterId":"ch_work_han_thu_93","textTraditional":"〔二〕　師古曰：「責謂假貸人財物未償者也。責音側懈反。」","sentenceOrder":10},
  {"id":"s_work_han_thu_93_11","chapterId":"ch_work_han_thu_93","textTraditional":"〔三〕　師古曰：「恐謂怖動也。大人，博自稱其母也。解讀曰懈。」","sentenceOrder":11},
  {"id":"s_work_han_thu_93_12","chapterId":"ch_work_han_thu_93","textTraditional":"〔四〕　師古曰：「還書，報書。」","sentenceOrder":12},
  {"id":"s_work_han_thu_93_13","chapterId":"ch_work_han_thu_93","textTraditional":"〔五〕　師古曰：「恬然，安靜貌也。恬音大兼反。」","sentenceOrder":13},
  {"id":"s_work_han_thu_93_14","chapterId":"ch_work_han_thu_93","textTraditional":"後光欲至長安，辭王，復言「願盡力與博共為王求朝。王即日至長安，可因平陽侯。」光得王欲求朝語，馳使人語博。博知王意動，復遺王書曰：「博幸得肺腑，〔一〕數進愚策，未見省察。北游燕趙，欲循行郡國求幽隱之士，聞齊有駟先生者，善為司馬兵法，大將之材也，博得謁見，承間進問五帝三王究竟要道，卓爾非世俗之所知。〔二〕今邊境不安，天下騷動，微此人其莫能安也。〔三〕又聞北海之瀕有賢人焉，〔四〕累世不可逮，然難致也。〔五〕得此二人而薦之，功亦不細矣。博願馳西以此赴助漢急，無財幣以通顯之。趙王使謁者持牛酒，黃金三十斤勞博，博不受；〔六〕復使人願尚女，聘金二百斤，博未許。〔七〕會得光書云大王已遣光西，與博并力求朝。博自以棄捐，不意大王還意反義，結以朱顏，〔八〕願殺身報德。朝事何足言！大王誠賜咳唾，使得盡死，湯禹所以成大功也。駟先生蓄積道術，書無不有，〔九〕願知大王所好，請得輒上。」王得書喜說，〔一０〕報博書曰：「子高乃幸左顧存恤，發心惻隱，〔一一〕顯至誠，納以嘉謀，語以至事，〔一二〕雖亦不敏，敢不諭意！〔一三〕今遣有司為子高償責二百萬。」","sentenceOrder":14},
  {"id":"s_work_han_thu_93_15","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「自云於王有親也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_93_16","chapterId":"ch_work_han_thu_93","textTraditional":"〔二〕　師古曰：「卓爾，高遠貌也。自言見駟先生問以要道，知其高遠也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_93_17","chapterId":"ch_work_han_thu_93","textTraditional":"〔三〕　師古曰：「微，無也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_93_18","chapterId":"ch_work_han_thu_93","textTraditional":"〔四〕　師古曰：「瀕，涯也，音頻，又音賓。」","sentenceOrder":18},
  {"id":"s_work_han_thu_93_19","chapterId":"ch_work_han_thu_93","textTraditional":"〔五〕　師古曰：「逮，及也，言其材智不可及也。致，至也。難得召而至也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_93_20","chapterId":"ch_work_han_thu_93","textTraditional":"〔六〕　師古曰：「勞謂問遺之，音來到反。」","sentenceOrder":20},
  {"id":"s_work_han_thu_93_21","chapterId":"ch_work_han_thu_93","textTraditional":"〔七〕　師古曰：「尚女者，王欲取博女以自配也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_93_22","chapterId":"ch_work_han_thu_93","textTraditional":"〔八〕　師古曰：「還猶回也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_93_23","chapterId":"ch_work_han_thu_93","textTraditional":"〔九〕　師古曰：「言凡是書籍皆有之。」","sentenceOrder":23},
  {"id":"s_work_han_thu_93_24","chapterId":"ch_work_han_thu_93","textTraditional":"〔一０〕如淳曰：「上與王也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_93_25","chapterId":"ch_work_han_thu_93","textTraditional":"〔一一〕師古曰：「左顧猶言枉顧也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_93_26","chapterId":"ch_work_han_thu_93","textTraditional":"〔一二〕師古曰：「以至極之事告語我。」","sentenceOrder":26},
  {"id":"s_work_han_thu_93_27","chapterId":"ch_work_han_thu_93","textTraditional":"〔一三〕師古曰：「諭，曉也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_93_28","chapterId":"ch_work_han_thu_93","textTraditional":"是時，博女婿京房以明易陰陽得幸於上，數召見言事。自謂為石顯、五鹿充宗所排，謀不得用，數為博道之。博常欲誑耀淮陽王，即具記房諸所說災異及召見密語，持予淮陽王以為信驗，詐言「已見中書令石君求朝，許以金五百斤。賢聖制事，蓋慮功而不計費。〔一〕昔禹治鴻水，百姓罷勞，〔二〕成功既立，萬世賴之。今聞陛下春秋未滿四十，髮齒墮落，太子幼弱，佞人用事，陰陽不調，百姓疾疫飢饉死者且半，鴻水之害殆不過此。〔三〕大王緒欲救世，〔四〕將比功德，何可以忽？〔五〕博已與大儒知道者為大王為便宜奏，〔六〕陳安危，指災異，大王朝見，先口陳其意而後奏之，上必大說。〔七〕事成功立，大王即有周、邵之名，邪臣散亡，公卿變節，功德亡比，而梁、趙之寵必歸大王，〔八〕外家亦將富貴，何復望大王之金錢？」王喜說，〔九〕報博書曰：「乃者詔下，止諸侯朝者，寡人憯然不知所出。〔一０〕子高素有顏冉之資，臧武之智，〔一一〕子貢之辯，〔一二〕卞莊子之勇，〔一三〕兼此四者，世之所鮮。〔一四〕既開端緒，願卒成之。〔一五〕求朝，義事也，奈何行金錢乎！」博報曰：「已許石君，須以成事。」〔一六〕王以金五百斤予博。","sentenceOrder":28},
  {"id":"s_work_han_thu_93_29","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「志在成功，不惜財費也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_93_30","chapterId":"ch_work_han_thu_93","textTraditional":"〔二〕　師古曰：「罷讀曰疲。」","sentenceOrder":30},
  {"id":"s_work_han_thu_93_31","chapterId":"ch_work_han_thu_93","textTraditional":"〔三〕　師古曰：「謂堯時水災不大於今。」","sentenceOrder":31},
  {"id":"s_work_han_thu_93_32","chapterId":"ch_work_han_thu_93","textTraditional":"〔四〕　師古曰：「緒，業也，一曰始為端緒。」","sentenceOrder":32},
  {"id":"s_work_han_thu_93_33","chapterId":"ch_work_han_thu_93","textTraditional":"〔五〕　師古曰：「言比功德於古帝王也。忽，怠忘也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_93_34","chapterId":"ch_work_han_thu_93","textTraditional":"〔六〕　師古曰：「大儒知道，謂京房也。道，道術也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_93_35","chapterId":"ch_work_han_thu_93","textTraditional":"〔七〕　師古曰：「說讀曰悅。」","sentenceOrder":35},
  {"id":"s_work_han_thu_93_36","chapterId":"ch_work_han_thu_93","textTraditional":"〔八〕　如淳曰：「梁王，景帝弟，欲為嗣。趙王如意幾代惠帝也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_93_37","chapterId":"ch_work_han_thu_93","textTraditional":"〔九〕　師古曰：「說讀曰悅。」","sentenceOrder":37},
  {"id":"s_work_han_thu_93_38","chapterId":"ch_work_han_thu_93","textTraditional":"〔一０〕師古曰：「憯，痛也。不知計策何所出也。憯音才感反。」","sentenceOrder":38},
  {"id":"s_work_han_thu_93_39","chapterId":"ch_work_han_thu_93","textTraditional":"〔一一〕師古曰：「顏，顏回也。冉耕也，字伯牛。皆孔子弟子。論語稱孔子曰：『德行顏淵、閔子騫、冉伯牛、仲弓。』臧武者，魯大夫臧武仲也，名紇。論語稱孔子曰『若臧武仲之智』，故王引之為言也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_93_40","chapterId":"ch_work_han_thu_93","textTraditional":"〔一二〕師古曰：「論語稱孔子云『言語，宰我、子貢』。」","sentenceOrder":40},
  {"id":"s_work_han_thu_93_41","chapterId":"ch_work_han_thu_93","textTraditional":"〔一三〕師古曰：「卞莊子，古之勇士。」","sentenceOrder":41},
  {"id":"s_work_han_thu_93_42","chapterId":"ch_work_han_thu_93","textTraditional":"〔一四〕師古曰：「鮮，少也，音先踐反。」","sentenceOrder":42},
  {"id":"s_work_han_thu_93_43","chapterId":"ch_work_han_thu_93","textTraditional":"〔一五〕師古曰：「卒，終也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_93_44","chapterId":"ch_work_han_thu_93","textTraditional":"〔一六〕師古曰：「須，待也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_93_45","chapterId":"ch_work_han_thu_93","textTraditional":"會房出為郡守，離左右，顯具得此事告之。房漏泄省中語，博兄弟詿誤諸侯王，誹謗政治，狡猾不道，皆下獄。有司奏請逮捕欽，上不忍致法，遣諫大夫王駿賜欽璽書曰：「皇帝問淮陽王。有司奏王，王舅張博數遺王書，非毀政治，謗訕天子，褒舉諸侯，稱引周、湯。以諂惑王，〔一〕所言尤惡，悖逆無道。王不舉奏而多與金錢，報以好言，罪至不赦，朕惻焉不忍聞，〔二〕為王傷之。推原厥本，不祥自博，〔三〕惟王之心，匪同于凶。已詔有司勿治王事，遣諫大夫駿申諭朕意。〔四〕詩不云乎？『靖恭爾位，正直是與。』〔五〕王其勉之！」","sentenceOrder":45},
  {"id":"s_work_han_thu_93_46","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「讇，古諂字也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_93_47","chapterId":"ch_work_han_thu_93","textTraditional":"〔二〕　師古曰：「惻，痛也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_93_48","chapterId":"ch_work_han_thu_93","textTraditional":"〔三〕　師古曰：「祥，善也。自，從也。不善之事，從博起也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_93_49","chapterId":"ch_work_han_thu_93","textTraditional":"〔四〕　師古曰：「申謂約束之。」","sentenceOrder":49},
  {"id":"s_work_han_thu_93_50","chapterId":"ch_work_han_thu_93","textTraditional":"〔五〕　師古曰：「大雅小明之詩也。與，偕也。言人能安靜而恭以守其位，偕於正直，則明神聽之，用錫福善。」","sentenceOrder":50},
  {"id":"s_work_han_thu_93_51","chapterId":"ch_work_han_thu_93","textTraditional":"駿諭指曰：〔一〕「禮為諸侯制相朝聘之義，蓋以考禮壹德，尊事天子也。〔二〕且王不學詩乎？詩云：『俾侯於魯，為周室輔。』〔三〕今王舅博數遺王書，所言悖逆。王幸受詔策，通經術，〔四〕知諸侯名譽不當出竟。〔五〕天子普覆，德布於朝，而恬有博言〔六〕，多予金錢，與相報應，不忠莫大焉。故事，諸侯王獲罪京師，罪惡輕重，縱不伏誅，必蒙遷削貶黜之罪，〔七〕未有但已者也。〔八〕今聖主赦王之罪，又憐王失計忘本，為博所惑，加賜璽書，使諫大夫申諭至意，殷勤之恩，豈有量哉！博等所犯（罪）惡大，群下之所共攻，王法之所不赦也。自今以來，王毋復以博等累心，〔九〕務與眾棄之。春秋之義，大能變改。〔一０〕易曰『藉用白茅，无咎』，〔一一〕言臣子之道，改過自新，絜己以承上，然後免於咎也。王其留意慎戒，惟思所以悔過易行，塞重責，稱厚恩者。〔一二〕如此，則長有富貴，社稷安矣。」","sentenceOrder":51},
  {"id":"s_work_han_thu_93_52","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「璽書之外，天子又有指意，并令駿曉告於王也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_93_53","chapterId":"ch_work_han_thu_93","textTraditional":"〔二〕　師古曰：「考，成也。壹德謂不二其心也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_93_54","chapterId":"ch_work_han_thu_93","textTraditional":"〔三〕　師古曰：「魯頌閟宮之詩也。言立周公子伯禽，使為諸侯於魯國而作周家之藩輔。」","sentenceOrder":54},
  {"id":"s_work_han_thu_93_55","chapterId":"ch_work_han_thu_93","textTraditional":"〔四〕　如淳曰：「詔策，若廣陵王策曰『無邇宵人，毋作匪德』也。經術之義，不得內交。」","sentenceOrder":55},
  {"id":"s_work_han_thu_93_56","chapterId":"ch_work_han_thu_93","textTraditional":"〔五〕　師古曰：「竟讀曰境。」","sentenceOrder":56},
  {"id":"s_work_han_thu_93_57","chapterId":"ch_work_han_thu_93","textTraditional":"〔六〕　師古曰：「恬，安也。聞博邪言，安而受之。」","sentenceOrder":57},
  {"id":"s_work_han_thu_93_58","chapterId":"ch_work_han_thu_93","textTraditional":"〔七〕　師古曰：「故事者，言舊制如此也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_93_59","chapterId":"ch_work_han_thu_93","textTraditional":"〔八〕　師古曰：「但，徒也，空也。已，止也。未有空然而止者也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_93_60","chapterId":"ch_work_han_thu_93","textTraditional":"〔九〕　師古曰：「累音力瑞反。」","sentenceOrder":60},
  {"id":"s_work_han_thu_93_61","chapterId":"ch_work_han_thu_93","textTraditional":"〔一０〕師古曰：「以有過而能變改者為大。」","sentenceOrder":61},
  {"id":"s_work_han_thu_93_62","chapterId":"ch_work_han_thu_93","textTraditional":"〔一一〕師古曰：「此大過初六爻辭也。茅者，絜白之物，取其自然，故用藉致享於神，慎之至也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_93_63","chapterId":"ch_work_han_thu_93","textTraditional":"〔一二〕師古曰：「塞猶補也。稱，副也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_93_64","chapterId":"ch_work_han_thu_93","textTraditional":"於是淮陽王欽免冠稽首謝曰：「奉藩無狀，〔一〕過惡暴列〔二〕，陛下不忍致法，加大恩，遣使者申諭道術守藩之義。伏念博罪惡尤深，當伏重誅。臣欽願悉心自新，奉承詔策。〔三〕頓首死罪。」","sentenceOrder":64},
  {"id":"s_work_han_thu_93_65","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「無善狀。」","sentenceOrder":65},
  {"id":"s_work_han_thu_93_66","chapterId":"ch_work_han_thu_93","textTraditional":"〔二〕　師古曰：「暴謂章顯也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_93_67","chapterId":"ch_work_han_thu_93","textTraditional":"〔三〕　師古曰：「悉，盡也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_93_68","chapterId":"ch_work_han_thu_93","textTraditional":"京房及博兄弟三人皆棄市，妻子徙邊。","sentenceOrder":68},
  {"id":"s_work_han_thu_93_69","chapterId":"ch_work_han_thu_93","textTraditional":"至成帝即位，以淮陽王屬為叔父，敬寵之，異於它國。王上書自陳舅張博時事，頗為石顯等所侵，因為博家屬徙者求還。丞相御史復劾欽：「前與博相遺私書，指意非諸侯王所宜，蒙恩勿治，事在赦前。不悔過而復稱引，自以為直，失藩臣體，不敬。」上加恩，許王還徙者。","sentenceOrder":69},
  {"id":"s_work_han_thu_93_70","chapterId":"ch_work_han_thu_93","textTraditional":"三十六年薨。子文王玄嗣，二十六年薨。子縯嗣，〔一〕王莽時絕。","sentenceOrder":70},
  {"id":"s_work_han_thu_93_71","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　孟康曰：「縯音引。」師古曰：「音弋善反。」","sentenceOrder":71},
  {"id":"s_work_han_thu_93_72","chapterId":"ch_work_han_thu_93","textTraditional":"楚孝王囂，甘露二年立為定陶王，三年徙楚。成帝河平中入朝，時被疾，天子閔之，下詔曰：「蓋聞『天地之性人為貴，人之行莫大於孝』。〔一〕楚王囂素行孝順仁慈，之國以來二十餘年，孅介之過未嘗聞，朕甚嘉之。今乃遭命，離于惡疾，〔二〕夫子所痛，曰：『蔑之，命矣夫，斯人也而有斯疾也！』〔三〕朕甚閔焉。夫行純茂而不顯異，則有國者將何勗哉？〔四〕書不云乎？『用德章厥善。〔五〕』今王朝正月，詔與子男一人俱，〔六〕其以廣戚縣戶四千三百封其子勳為廣戚侯。」明年，囂薨。子懷王文嗣，一年薨，無子，絕。明年，成帝復立文弟平陸侯衍，是為思王。二十一年薨，子紆嗣，王莽時絕。","sentenceOrder":72},
  {"id":"s_work_han_thu_93_73","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「孝經載孔子之言。」","sentenceOrder":73},
  {"id":"s_work_han_thu_93_74","chapterId":"ch_work_han_thu_93","textTraditional":"〔二〕　師古曰：「離亦遭也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_93_75","chapterId":"ch_work_han_thu_93","textTraditional":"〔三〕　師古曰：「夫子，孔子也。論語云伯牛有疾，子問之，自牖執其手，曰：『蔑之，命矣夫，斯人也而有斯疾也！』蔑，無也。言命之所遭，無有善惡。如斯善人而有如此惡疾，深痛之也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_93_76","chapterId":"ch_work_han_thu_93","textTraditional":"〔四〕　師古曰：「純，大也。一曰善也。茂，美也。勗，勉厲也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_93_77","chapterId":"ch_work_han_thu_93","textTraditional":"〔五〕　師古曰：「商書盤庚之辭也。言褒賞有德以明其善行。」","sentenceOrder":77},
  {"id":"s_work_han_thu_93_78","chapterId":"ch_work_han_thu_93","textTraditional":"〔六〕　師古曰：「從王入朝也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_93_79","chapterId":"ch_work_han_thu_93","textTraditional":"初，成帝時又立紆弟景為定陶王。廣戚侯勳薨，諡曰煬侯，子顯嗣。平帝崩，無子，王莽立顯子嬰為孺子，奉平帝後。莽篡位，以嬰為定安公。漢既誅莽，更始時嬰在長安，平陵方望等頗知天文，以為更始必敗，嬰本統當立者也，〔一〕共起兵將嬰至臨涇，立為天子。更始遣丞相李松擊破殺嬰云。","sentenceOrder":79},
  {"id":"s_work_han_thu_93_80","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「言其舊已繼平帝後當正統。」","sentenceOrder":80},
  {"id":"s_work_han_thu_93_81","chapterId":"ch_work_han_thu_93","textTraditional":"東平思王宇，甘露二年立。元帝即位，就國。壯大，通姦犯法，〔一〕上以至親貰弗罪，傅相連坐。〔二〕","sentenceOrder":81},
  {"id":"s_work_han_thu_93_82","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「與姦猾交通，好犯法。」","sentenceOrder":82},
  {"id":"s_work_han_thu_93_83","chapterId":"ch_work_han_thu_93","textTraditional":"〔二〕　師古曰：「頻坐王獲罪。」","sentenceOrder":83},
  {"id":"s_work_han_thu_93_84","chapterId":"ch_work_han_thu_93","textTraditional":"久之，事太后，內不相得，太后上書言之，求守杜陵園。〔一〕上於是遣太中大夫張子蟜〔二〕奉璽書敕諭之，〔三〕曰：「皇帝問東平王。蓋聞親親之恩莫重於孝，尊尊之義莫大於忠，故諸侯在位不驕以致孝道，制節謹度以翼天子，〔四〕然後富貴不離於身，而社稷可保。今聞王自修有闕，本朝不和，〔五〕流言紛紛，謗自內興，朕甚憯焉，為王懼之。〔六〕詩不云乎？『毋念爾祖，述修厥德，永言配命，自求多褔。』〔七〕朕惟王之春秋方剛，〔八〕忽於道德〔九〕，意有所移，忠言未納，〔一０〕故臨遣太中大夫子蟜諭王朕意。〔一一〕孔子曰：「過而不改，是謂過矣。』〔一二〕王其深惟孰思之，無違朕意。」","sentenceOrder":84},
  {"id":"s_work_han_thu_93_85","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　張晏曰：「宣帝陵也。宮人無子，乃守園陵也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_93_86","chapterId":"ch_work_han_thu_93","textTraditional":"〔二〕　師古曰：「蟜字或作僑，並音鉅昭反。」","sentenceOrder":86},
  {"id":"s_work_han_thu_93_87","chapterId":"ch_work_han_thu_93","textTraditional":"〔三〕　師古曰：「約敕而曉告之也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_93_88","chapterId":"ch_work_han_thu_93","textTraditional":"〔四〕　師古曰：「翼，佐也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_93_89","chapterId":"ch_work_han_thu_93","textTraditional":"〔五〕　師古曰：「謂東平國之朝也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_93_90","chapterId":"ch_work_han_thu_93","textTraditional":"〔六〕　師古曰：「憯，痛也，音千感反。」","sentenceOrder":90},
  {"id":"s_work_han_thu_93_91","chapterId":"ch_work_han_thu_93","textTraditional":"〔七〕　師古曰：「大雅文王之詩也。無念，念也。言當念爾先祖之道，修其德，則長配天命，此乃所以自求多褔。」","sentenceOrder":91},
  {"id":"s_work_han_thu_93_92","chapterId":"ch_work_han_thu_93","textTraditional":"〔八〕　師古曰：「言其年少血氣盛。」","sentenceOrder":92},
  {"id":"s_work_han_thu_93_93","chapterId":"ch_work_han_thu_93","textTraditional":"〔九〕　師古曰：「忽，遺忘也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_93_94","chapterId":"ch_work_han_thu_93","textTraditional":"〔一０〕師古曰：「謂漸染其惡人而移其性，未受忠言也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_93_95","chapterId":"ch_work_han_thu_93","textTraditional":"〔一一〕師古曰：「親臨遣之，令以朕意曉告王。」","sentenceOrder":95},
  {"id":"s_work_han_thu_93_96","chapterId":"ch_work_han_thu_93","textTraditional":"〔一二〕師古曰：「論語載孔子之言也。謂人有失行，許以自新。」","sentenceOrder":96},
  {"id":"s_work_han_thu_93_97","chapterId":"ch_work_han_thu_93","textTraditional":"又特以璽書賜王太后，曰：「皇帝使諸吏宦者令承問東平王太后。朕有聞，〔一〕王太后少加意焉。夫褔善之門莫美於和睦，患咎之首莫大於內離。今東平王出繈褓之中而託于南面之位，加以年齒方剛，涉學日寡，驁忽臣下，〔二〕不自它於太后，〔三〕以是之間，能無失禮義者，其唯聖人乎！傳曰：『父為子隱，直在其中矣。』〔四〕王太后明察此意，不可不詳。閨門之內，母子之間，同氣異息，骨肉之恩，豈可忽哉！豈可忽哉！昔周公戒伯禽曰：『故舊無大故，則不可棄也，毋求備於一人。』〔五〕夫以故舊之恩，猶忍小惡，而況此乎！已遣使者諭王，王既悔過服罪，太后寬忍以貰之，〔六〕後宜不敢。〔七〕王太后強餐，止思念，慎疾自愛。」","sentenceOrder":97},
  {"id":"s_work_han_thu_93_98","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「言母子不和也。不欲指斥言之，故云有聞也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_93_99","chapterId":"ch_work_han_thu_93","textTraditional":"〔二〕　師古曰：「驁讀（曰）〔與〕傲同。」","sentenceOrder":99},
  {"id":"s_work_han_thu_93_100","chapterId":"ch_work_han_thu_93","textTraditional":"〔三〕　李奇曰：「不自它者，親之辭也。」師古曰：「言不自同它人。」","sentenceOrder":100},
  {"id":"s_work_han_thu_93_101","chapterId":"ch_work_han_thu_93","textTraditional":"〔四〕　師古曰：「論語云葉公謂孔子曰：『吾黨有直躬者，其父攘羊而子證之。』孔子曰：『吾黨之直者異於是，父為子隱，子為父隱，直在其中矣。』故引之也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_93_102","chapterId":"ch_work_han_thu_93","textTraditional":"〔五〕　師古曰：「事見論語。言人有小惡，當思其善，不可責以備行而即棄之耳。」","sentenceOrder":102},
  {"id":"s_work_han_thu_93_103","chapterId":"ch_work_han_thu_93","textTraditional":"〔六〕　師古曰：「貰猶緩。」","sentenceOrder":103},
  {"id":"s_work_han_thu_93_104","chapterId":"ch_work_han_thu_93","textTraditional":"〔七〕　師古曰：「言王於後當不敢更為非也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_93_105","chapterId":"ch_work_han_thu_93","textTraditional":"宇慚懼，因使者頓首謝死罪，願洒心自改。〔一〕詔書又敕傅相曰：「夫人之性皆有五常，及其少長，耳目牽於耆欲，〔二〕故五常銷而邪心作，情亂其性，利勝其義，〔三〕而不失厥家者，未之有也。今王富於春秋，氣力勇武，獲師傅之教淺，加以少所聞見，自今以來，非五經之正術，敢以游獵非禮道王者，輒以名聞。」〔四〕","sentenceOrder":105},
  {"id":"s_work_han_thu_93_106","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「洒音先弟反。」","sentenceOrder":106},
  {"id":"s_work_han_thu_93_107","chapterId":"ch_work_han_thu_93","textTraditional":"〔二〕　師古曰：「耆讀曰嗜。」","sentenceOrder":107},
  {"id":"s_work_han_thu_93_108","chapterId":"ch_work_han_thu_93","textTraditional":"〔三〕　張晏曰：「性者，所受而生也。情者，見物而動者也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_93_109","chapterId":"ch_work_han_thu_93","textTraditional":"〔四〕　師古曰：「道讀曰導。」","sentenceOrder":109},
  {"id":"s_work_han_thu_93_110","chapterId":"ch_work_han_thu_93","textTraditional":"宇立二十年，元帝崩。宇謂中謁者信等曰：「漢大臣議天子少弱，未能治天下，以為我知文法，建欲使我輔佐天子。〔一〕我見尚書晨夜極苦，使我為之，不能也。今暑熱，縣官年少，〔二〕持服恐無處所，〔三〕我危得之！」〔四〕比至下，宇凡三哭，〔五〕飲酒食肉，妻妾不離側。又姬朐臑故親幸，後疏遠，〔六〕數歎息呼天。宇聞，斥朐臑為家人子，〔七〕掃除永巷，數笞擊之。朐臑私疏宇過失，數令家告之。宇覺知，絞殺朐臑。有（詔）〔司〕奏請逮捕，有詔削樊、亢父二縣。〔八〕後三歲，天子詔有司曰：「蓋聞仁以親親，古之道也。前東平王有闕，〔九〕有司請廢，朕不忍。又請削，朕不敢專。惟王之至親，未嘗忘於心。今聞王改行自新，尊修經術，親近仁人，非法之求，不以奸吏，〔一０〕朕甚嘉焉。傳不云乎？朝過夕改，君子與之。其復前所削縣如故。」〔一一〕","sentenceOrder":110},
  {"id":"s_work_han_thu_93_111","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「建謂立其議。」","sentenceOrder":111},
  {"id":"s_work_han_thu_93_112","chapterId":"ch_work_han_thu_93","textTraditional":"〔二〕　張晏曰：「不敢指斥成帝，謂之縣官也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_93_113","chapterId":"ch_work_han_thu_93","textTraditional":"〔三〕　如淳曰：「言不從道，冀如昌邑王也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_93_114","chapterId":"ch_work_han_thu_93","textTraditional":"〔四〕　孟康曰：「危，殆也。我殆得為天子也。」師古曰：「危者，猶今之言險不得之也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_93_115","chapterId":"ch_work_han_thu_93","textTraditional":"〔五〕　張晏曰：「下，下棺也。」師古曰：「比音必寐反。下音胡稼反。」","sentenceOrder":115},
  {"id":"s_work_han_thu_93_116","chapterId":"ch_work_han_thu_93","textTraditional":"〔六〕　服虔曰：「朐音劬。臑音奴溝反，又音奴皋反。」","sentenceOrder":116},
  {"id":"s_work_han_thu_93_117","chapterId":"ch_work_han_thu_93","textTraditional":"〔七〕　師古曰：「黜其秩位。」","sentenceOrder":117},
  {"id":"s_work_han_thu_93_118","chapterId":"ch_work_han_thu_93","textTraditional":"〔八〕　師古曰：「音抗甫。」","sentenceOrder":118},
  {"id":"s_work_han_thu_93_119","chapterId":"ch_work_han_thu_93","textTraditional":"〔九〕　師古曰：「闕謂過失也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_93_120","chapterId":"ch_work_han_thu_93","textTraditional":"〔一０〕師古曰：「奸音干。」","sentenceOrder":120},
  {"id":"s_work_han_thu_93_121","chapterId":"ch_work_han_thu_93","textTraditional":"〔一一〕師古曰：「復音扶目反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_93_122","chapterId":"ch_work_han_thu_93","textTraditional":"後年來朝，上疏求諸子及太史公書，上以問大將軍王鳳，對曰：「臣聞諸侯朝聘，考文章，正法度，非禮不言。今東平王幸得來朝，不思制節謹度，以防危失，〔一〕而求諸書，非朝聘之義也。諸子書或反經術，非聖人，或明鬼神，信物怪；〔二〕太史公書有戰國從橫權譎之謀，漢興之初謀臣奇策，天官災異，地形阨塞：皆不宜在諸侯王。不可予。不許之辭宜曰：『五經聖人所制，萬事靡不畢載。王審樂道，傅相皆儒者，旦夕講誦，足以正身虞意。〔三〕夫小辯破義，小道不通，致遠恐泥，皆不足以留意。〔四〕諸益於經術者，不愛於王。』」〔五〕對奏，天子如鳳言，遂不與。","sentenceOrder":122},
  {"id":"s_work_han_thu_93_123","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「危失謂失道而傾危也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_93_124","chapterId":"ch_work_han_thu_93","textTraditional":"〔二〕　師古曰：「物亦鬼。」","sentenceOrder":124},
  {"id":"s_work_han_thu_93_125","chapterId":"ch_work_han_thu_93","textTraditional":"〔三〕　師古曰：「虞與娛同也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_93_126","chapterId":"ch_work_han_thu_93","textTraditional":"〔四〕　師古曰：「論語稱孔子曰：『雖小道必有可觀者焉，致遠恐泥，是以君子不為也。』泥謂陷滯不通也，音乃細反。」","sentenceOrder":126},
  {"id":"s_work_han_thu_93_127","chapterId":"ch_work_han_thu_93","textTraditional":"〔五〕　師古曰：「愛，惜也，於王無所惜。」","sentenceOrder":127},
  {"id":"s_work_han_thu_93_128","chapterId":"ch_work_han_thu_93","textTraditional":"立三十三年薨，〔一〕子煬王雲嗣。哀帝時，無鹽危山土自起覆草，如馳道狀，又瓠山石轉立。〔二〕雲及后謁自之石所祭，治石象瓠山〔三〕立石，束倍草，并祠之。〔四〕建平三年，息夫躬、孫寵等共因幸臣董賢告之。是時，哀帝被疾，多所惡，事下有司，逮王、后謁下獄驗治，言使巫傅恭、婢合歡等祠祭詛祝上，〔五〕為雲求為天子。雲又與知災異者高尚等指星宿，言上疾必不愈，雲當得天下。石立，宣帝起之表也。有司請誅王，有詔廢徙房陵。雲自殺，謁棄市。立十七年，國除。","sentenceOrder":128},
  {"id":"s_work_han_thu_93_129","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「皇覽云東平思王冢在無鹽，人傳言王在國思歸京師，後葬，其冢上松柏皆西靡也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_93_130","chapterId":"ch_work_han_thu_93","textTraditional":"〔二〕　晉灼曰：「漢注作報山。山脅石一枚，轉側起立，高九尺六寸，旁行一丈，廣四尺也。」師古曰：「報山，山名也。古作瓠字，為其形似瓠耳。晉說是也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_93_131","chapterId":"ch_work_han_thu_93","textTraditional":"〔三〕　蘇林曰：「於宮中作山象。」","sentenceOrder":131},
  {"id":"s_work_han_thu_93_132","chapterId":"ch_work_han_thu_93","textTraditional":"〔四〕　師古曰：「倍草，黃倍草也，音步賄反。」","sentenceOrder":132},
  {"id":"s_work_han_thu_93_133","chapterId":"ch_work_han_thu_93","textTraditional":"〔五〕　如淳曰：「傅恭，巫姓字。」","sentenceOrder":133},
  {"id":"s_work_han_thu_93_134","chapterId":"ch_work_han_thu_93","textTraditional":"元始元年，王莽欲反哀帝政，〔一〕白太皇太后，立雲太子開明為東平王，又立思王孫成都為中山王。開明立三年，薨，無子。復立開明兄嚴鄉侯信子匡為東平王，奉開明後。王莽居攝，東郡太守翟義與嚴鄉侯信謀舉兵誅莽，立信為天子。兵敗，皆為莽所滅。","sentenceOrder":134},
  {"id":"s_work_han_thu_93_135","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「改其所為也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_93_136","chapterId":"ch_work_han_thu_93","textTraditional":"中山哀王竟，初元二年立為清河王。三年，徙中山，以幼少未之國。建昭四年，薨邸，葬杜陵，無子，絕。太后歸居外家戎氏。","sentenceOrder":136},
  {"id":"s_work_han_thu_93_137","chapterId":"ch_work_han_thu_93","textTraditional":"孝元皇帝三男。王皇后生孝成帝，傅昭儀生定陶共王康，〔一〕馮昭儀生中山孝王興。","sentenceOrder":137},
  {"id":"s_work_han_thu_93_138","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「共讀曰恭。」","sentenceOrder":138},
  {"id":"s_work_han_thu_93_139","chapterId":"ch_work_han_thu_93","textTraditional":"定陶共王康，永光三年立為濟陽王。八年，徙為山陽王。八年，徙定陶。王少而愛，〔一〕長多材藝，習知音聲，上奇器之。母昭儀又幸，幾代皇后太子。〔二〕語在元后及史丹傳。","sentenceOrder":139},
  {"id":"s_work_han_thu_93_140","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「言少小即為帝所愛。」","sentenceOrder":140},
  {"id":"s_work_han_thu_93_141","chapterId":"ch_work_han_thu_93","textTraditional":"〔二〕　師古曰：「幾音鉅衣反。」","sentenceOrder":141},
  {"id":"s_work_han_thu_93_142","chapterId":"ch_work_han_thu_93","textTraditional":"成帝即位，緣先帝意，厚遇異於它王。十九年薨，子欣嗣。十五年，成帝無子，徵入為皇太子。上以太子奉大宗後，不得顧私親，乃立楚思王子景為定陶王，奉共王後。成帝崩，太子即位，是為孝哀帝。即位二年，追尊共王為共皇，置寢廟京師，序昭穆，儀如孝元帝。〔一〕徙定陶王景為信都王云。〔二〕","sentenceOrder":142},
  {"id":"s_work_han_thu_93_143","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　如淳曰：「恭王，元帝子也。為廟京師，列昭穆之次。如元帝，言如天子之儀。」","sentenceOrder":143},
  {"id":"s_work_han_thu_93_144","chapterId":"ch_work_han_thu_93","textTraditional":"〔二〕　如淳曰：「不復為定陶王立後者，哀帝自以己為後故。」","sentenceOrder":144},
  {"id":"s_work_han_thu_93_145","chapterId":"ch_work_han_thu_93","textTraditional":"中山孝王興，建昭二年（王）〔立〕為信都王。十四年，徙中山。成帝之議立太子也，御史大夫孔光以為尚書有殷及王，兄終弟及，〔一〕中山王元帝之子，宜為後。成帝以中山王不材，又兄弟，不得相入廟。外家王氏與趙昭儀皆欲用哀帝為太子，故遂立焉。上乃封孝王舅馮參為宜鄉侯，而益封孝王萬戶，以尉其意。三十年，薨，子衎嗣。〔二〕七年，哀帝崩，無子，徵中山王衎入即位，是為平帝。太皇太后以帝為成帝後，故立東平思王孫桃鄉頃侯子成都為中山王，奉孝王後。王莽時絕。","sentenceOrder":145},
  {"id":"s_work_han_thu_93_146","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「謂兄死以弟代立，非父子相繼，故言及。」","sentenceOrder":146},
  {"id":"s_work_han_thu_93_147","chapterId":"ch_work_han_thu_93","textTraditional":"〔二〕　師古曰：「諸侯王表云『中山孝王薨，綏和二年王箕子嗣』。而〔平紀〕元始二年詔云：『皇帝二名，通於器物，今更名合於古制。』是則嗣位之時名為箕子，未諱衎也。今此傳云子衎嗣，蓋史家追書之也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_93_148","chapterId":"ch_work_han_thu_93","textTraditional":"贊曰：孝元之後，遍有天下，〔一〕然而世絕於孫，豈非天哉！淮陽憲王於時諸侯為聰察矣，張博誘之，幾陷無道。〔二〕詩云「貪人敗類」，〔三〕古今一也。","sentenceOrder":148},
  {"id":"s_work_han_thu_93_149","chapterId":"ch_work_han_thu_93","textTraditional":"〔一〕　師古曰：「孝元之子孫遍得為天子也。遍即古遍字。」","sentenceOrder":149},
  {"id":"s_work_han_thu_93_150","chapterId":"ch_work_han_thu_93","textTraditional":"〔二〕　師古曰：「幾音鉅依反。」","sentenceOrder":150},
  {"id":"s_work_han_thu_93_151","chapterId":"ch_work_han_thu_93","textTraditional":"〔三〕　師古曰：「大雅蕩之詩也。類，善也。言貪惡之人不可習近，則敗善也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_93_152","chapterId":"ch_work_han_thu_93","textTraditional":"校勘記","sentenceOrder":152},
  {"id":"s_work_han_thu_93_153","chapterId":"ch_work_han_thu_93","textTraditional":"三三一二頁　八行　令弟光恐（王）云王遇大人益解，　宋祁說「恐」字下疑有「王」字。按景祐、殿本都無「王」字。","sentenceOrder":153},
  {"id":"s_work_han_thu_93_154","chapterId":"ch_work_han_thu_93","textTraditional":"三三一七頁　八行　博等所犯（罪）惡大，　宋祁說，「犯」字下當有「罪」字。按景祐、殿本都無「罪」字。","sentenceOrder":154},
  {"id":"s_work_han_thu_93_155","chapterId":"ch_work_han_thu_93","textTraditional":"三三二二頁一０行　驁讀（曰）〔與〕傲同。　景祐、殿本都作「與」。","sentenceOrder":155},
  {"id":"s_work_han_thu_93_156","chapterId":"ch_work_han_thu_93","textTraditional":"三三二三頁一三行　有（詔）〔司〕奏請逮捕。　錢大昭說，「詔」當作「司」。按景祐、殿本都作「司」。","sentenceOrder":156},
  {"id":"s_work_han_thu_93_157","chapterId":"ch_work_han_thu_93","textTraditional":"三三二七頁一二行　建昭二年（王）〔立〕為信都王。　劉敞說上「王」字當作「立」字。","sentenceOrder":157},
  {"id":"s_work_han_thu_93_158","chapterId":"ch_work_han_thu_93","textTraditional":"三三二八頁　五行　而〔平紀〕元始二年詔云：　宋祁說浙本有「平紀」二字。按景祐本有「平紀」二字。","sentenceOrder":158},
  {"id":"s_work_han_thu_94_1","chapterId":"ch_work_han_thu_94","textTraditional":"匡衡字稚圭，東海承人也。〔一〕父世農夫，至衡好學，家貧，庸作以供資用，〔二〕尤精力過絕人。諸儒為之語曰：「無說詩，匡鼎來；〔三〕匡說詩，解人頤。」〔四〕","sentenceOrder":1},
  {"id":"s_work_han_thu_94_2","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「承音證。」","sentenceOrder":2},
  {"id":"s_work_han_thu_94_3","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「庸作，言賣功庸為人作役而受顧也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_94_4","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　服虔曰：「鼎猶言當也，若言匡且來也。」應劭曰：「鼎，方也。」張晏曰：「匡衡少時字鼎，長乃易字稚圭。世所傳衡與貢禹書，上言『衡敬報』，下言『匡鼎白』，知是字也。」師古曰：「服、應二說是也。賈誼曰『天子春秋鼎盛』，其義亦同，而張氏之說蓋穿鑿矣。假有其書，乃是後人見此傳云『匡鼎來』，不曉其意，妄作衡書云『鼎白』耳。字以表德，豈人之所自稱乎？今有西京雜記者，其書淺俗，出於里巷，多有妄說，乃云匡衡小名鼎，蓋絕知者之聽。」","sentenceOrder":4},
  {"id":"s_work_han_thu_94_5","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　如淳曰：「使人笑不能止也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_94_6","chapterId":"ch_work_han_thu_94","textTraditional":"衡射策甲科，以不應令除為太常掌故，〔一〕調補平原文學〔二〕。學者多上書薦衡經明，當世少雙，令為文學就官京師；後進皆欲從衡平原，衡不宜在遠方。事下太子太傅蕭望之、少府梁丘賀問，衡對詩諸大義，其對深美。望之奏衡經學精習，說有師道，可觀覽。宣帝不甚用儒，遣衡歸官。而皇太子見衡對，私善之。","sentenceOrder":6},
  {"id":"s_work_han_thu_94_7","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「投射得甲科之策，而所對文指不應令條也。儒林傳說歲課甲科為郎中，乙科為太子舍人，景科補文學掌故。今不應令，是不中甲科之令，所以止為掌故。」","sentenceOrder":7},
  {"id":"s_work_han_thu_94_8","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「調，選也，音徒釣反。」","sentenceOrder":8},
  {"id":"s_work_han_thu_94_9","chapterId":"ch_work_han_thu_94","textTraditional":"會宣帝崩，元帝初即位，樂陵侯史高以外屬為大司馬車騎將軍，領尚書事，前將軍蕭望之為副。望之名儒，有師傅舊恩，天子任之，多所貢薦。高充位而已，〔一〕與望之有隙。長安令楊興說高曰：「將軍以親戚輔政，貴重於天下無二，然眾庶論議令問休譽不專在將軍者何也？〔二〕彼誠有所聞也。〔三〕以將軍之莫府，海內莫不卬望，〔四〕而所舉不過私門賓客，乳母子弟，人情（以）〔忽〕不自知，〔五〕然一夫竊議，語流天下。夫富貴在身而列士不譽，是有狐白之裘而反衣之也。〔六〕古人病其若此，故卑體勞心，以求賢為務。傳曰：以賢難得之故因曰事不待賢，以食難得之故而曰飽不待食，或之甚者也。平原文學匡衡材智有餘，經學絕倫，但以無階朝廷，故隨牒在遠方。〔七〕將軍誠召置莫府，學士歙然歸仁，〔八〕與參事議，觀其所有，貢之朝廷，必為國器，〔九〕以此顯示眾庶，名流於世。」高然其言，辟衡為議曹史，薦衡於上，上以為郎中，遷博士，給事中。","sentenceOrder":9},
  {"id":"s_work_han_thu_94_10","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「言凡事不在也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_94_11","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「令，善；問，名；休，美也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_94_12","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「以其不能進賢也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_94_13","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「卬讀曰仰。」","sentenceOrder":13},
  {"id":"s_work_han_thu_94_14","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　師古曰：「言高輕忽此事，不自知其非。」","sentenceOrder":14},
  {"id":"s_work_han_thu_94_15","chapterId":"ch_work_han_thu_94","textTraditional":"〔六〕　師古曰：「狐白，謂狐掖下之皮，其色純白，集以為裘，輕柔難得，故貴也。反衣之者，以其毛在內也，今人則以背毛為裘而棄其白，蓋取厚而溫也。衣音於既反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_94_16","chapterId":"ch_work_han_thu_94","textTraditional":"〔七〕　師古曰：「階謂升次也。隨牒，謂隨選補之恆牒，不被超擢者。」","sentenceOrder":16},
  {"id":"s_work_han_thu_94_17","chapterId":"ch_work_han_thu_94","textTraditional":"〔八〕　師古曰：「誠謂實行之也。歙音翕。」","sentenceOrder":17},
  {"id":"s_work_han_thu_94_18","chapterId":"ch_work_han_thu_94","textTraditional":"〔九〕　師古曰：「所有，謂材藝所長。」","sentenceOrder":18},
  {"id":"s_work_han_thu_94_19","chapterId":"ch_work_han_thu_94","textTraditional":"是時，有日蝕地震之變，上問以政治得失，衡上疏曰：","sentenceOrder":19},
  {"id":"s_work_han_thu_94_20","chapterId":"ch_work_han_thu_94","textTraditional":"臣聞五帝不同（樂）〔禮〕，三王各異教，民俗殊務，所遇之時異也。陛下躬聖德，開太平之路，閔愚吏民觸法抵禁，〔一〕比年大赦，〔二〕使百姓得改行自新，天下幸甚。臣竊見大赦之後，姦邪不為衰止，今日大赦，明日犯法，相隨入獄，此殆導之未得其務也。蓋保民者，「陳之以德義」，「示之以好惡」，〔三〕觀其失而制其宜，故動之而和，綏之而安。今天下俗貪財賤義，好聲色，上侈靡，廉恥之節薄，淫辟之意縱，〔四〕綱紀失序，疏者踰內，〔五〕親戚之恩薄；婚姻之黨隆，苟合徼幸，以身設利。不改其原，〔六〕雖歲赦之，刑猶難使錯而不用也。〔七〕","sentenceOrder":20},
  {"id":"s_work_han_thu_94_21","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「抵，觸也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_94_22","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「比，頻也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_94_23","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「保，養也。陳，施也。孝經曰『陳之以德義而民莫遺其親』，『示之以好惡而民知禁』，故衡引以為言。」","sentenceOrder":23},
  {"id":"s_work_han_thu_94_24","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「辟讀曰僻。」","sentenceOrder":24},
  {"id":"s_work_han_thu_94_25","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　師古曰：「疏者，妻妾之家。內者，同姓骨肉也。踰謂過越也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_94_26","chapterId":"ch_work_han_thu_94","textTraditional":"〔六〕　師古曰：「設，施也。原，本也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_94_27","chapterId":"ch_work_han_thu_94","textTraditional":"〔七〕　師古曰：「歲赦，謂每歲一赦也。錯，置也，音千故反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_94_28","chapterId":"ch_work_han_thu_94","textTraditional":"臣愚以為宜壹曠然大變其俗。孔子曰：「能以禮讓為國乎，何有？」〔一〕朝廷者，天下之楨幹也。公卿大夫相與循禮恭讓，則民不爭；〔二〕好仁樂施，則下不暴；上義高節，則民興行；寬柔和惠，則眾相愛。四者，明王之所以不嚴而成化也。何者？朝有變色之言，則下有爭鬥之患；上有自專之士，則下有不讓之人；上有克勝之佐，則下有傷害之心；上有好利之臣，則下有盜竊之民：此其本也。〔三〕今俗吏之治，皆不本禮讓，而上克暴，或忮害好陷人於罪〔四〕，貪財而慕勢，故犯法者眾，姦邪不正，雖嚴刑峻法，猶不為變。此非其天性，有由然也。〔五〕","sentenceOrder":28},
  {"id":"s_work_han_thu_94_29","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「論語載孔子之言。謂能以禮讓治國，則其事甚易。」","sentenceOrder":29},
  {"id":"s_work_han_thu_94_30","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「循，順也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_94_31","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「言下之所行，皆取化於上也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_94_32","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「忮，堅也。謂酷害之心堅也。忮音之豉反。」","sentenceOrder":32},
  {"id":"s_work_han_thu_94_33","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　師古曰：「非其天性自惡，由上失於教化耳。」","sentenceOrder":33},
  {"id":"s_work_han_thu_94_34","chapterId":"ch_work_han_thu_94","textTraditional":"臣竊考國風之詩，周南、召南被賢聖之化深，故篤於行而廉於色。〔一〕鄭伯好勇，而國人暴虎；〔二〕秦穆貴信，而士多從死；〔三〕陳夫人好巫，而民淫祀；〔四〕晉侯好儉，而民畜聚；〔五〕太王躬仁，邠國貴恕。〔六〕由此觀之，治天下者審所上而已〔七〕。今之偽薄忮害，不讓極矣。臣聞教化之流，非家至而人說之也。〔八〕賢者在位，能者布職，朝廷崇禮，百僚敬讓。道德之行，由內及外，自近者始，然後民知所法，遷善日進而不自知。是以百姓安，陰陽和，神靈應，而嘉祥見。詩曰：「商邑翼翼，四方之極；壽考且寧，以保我後生。」〔九〕此成湯所以建至治，保子孫，化異俗而懷鬼方也。〔一０〕今長安天子之都，親承聖化，然其習俗無以異於遠方，郡國來者無所法則，或見侈靡而放效之。〔一一〕此教化之原本，風俗之樞機，宜先正者也。","sentenceOrder":34},
  {"id":"s_work_han_thu_94_35","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「篤，厚也。謂樂得淑女以配君子，憂在進賢，不淫其色之類也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_94_36","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「詩鄭風太叔于田之篇曰：『襢裼暴虎，獻于公所。將叔無狃，戒其傷汝。』襢裼，肉袒也。暴虎，空手以搏之也。公，鄭莊公也。將，請也。叔，莊公之弟太叔也。狃，忕也。汝亦太叔也。言以莊公好勇之故，太叔肉袒空手搏虎，取而獻之。國人愛叔，故請之曰勿忕為之，恐傷汝也。襢音袒，裼音錫，字並從衣。將音千羊反。狃音女九反。」","sentenceOrder":36},
  {"id":"s_work_han_thu_94_37","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　應劭曰：「秦穆公與群臣飲酒，酒酣，公曰：『生共此樂，死共此哀。』於是奄息、仲行、鍼虎許諾。及公薨，皆從死。黃鳥詩所為作也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_94_38","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　張晏曰：「胡公夫人，武王之女大姬，無子，好祭鬼神，鼓舞而祀，故其詩云：『坎其擊鼓，宛丘之下，無冬無夏，值其鷺羽。』」","sentenceOrder":38},
  {"id":"s_work_han_thu_94_39","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　師古曰：「唐風山有樞之詩序云：『刺晉昭公也，不能修道以正其國，有財不能用，有鐘鼓不能以自樂。』其詩曰：『子有衣裳，弗曳弗婁。子有車馬，弗馳弗驅。宛其死矣，它人是愉。』故其俗皆吝嗇而積財也。畜讀曰蓄。」","sentenceOrder":39},
  {"id":"s_work_han_thu_94_40","chapterId":"ch_work_han_thu_94","textTraditional":"〔六〕　師古曰：「太王，周文王之祖，即古公亶父也。國於邠，修德行義。戎狄攻之，欲得地，與之。人人皆怒欲戰。古公曰：『以我故戰，殺人父子而居之，予不忍也。』乃與其私屬度漆沮，踰梁山，止於岐下。邠人舉國扶老攜弱，盡復歸古公於岐下。及它旁國聞古公仁，亦多歸之。邠即今豳州，是其地也。言化太王之仁，故其俗皆貴誠恕。」","sentenceOrder":40},
  {"id":"s_work_han_thu_94_41","chapterId":"ch_work_han_thu_94","textTraditional":"〔七〕　師古曰：「上謂崇尚也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_94_42","chapterId":"ch_work_han_thu_94","textTraditional":"〔八〕　師古曰：「言非家家皆到，人人勸說也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_94_43","chapterId":"ch_work_han_thu_94","textTraditional":"〔九〕　師古曰：「商頌殷武之詩也。商邑，京師也。極，中也。言商邑之禮俗翼翼然可則傚，乃四方之中正也。王則壽考且安，以此全守我子孫也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_94_44","chapterId":"ch_work_han_thu_94","textTraditional":"〔一０〕應劭曰：「鬼方，遠方也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_94_45","chapterId":"ch_work_han_thu_94","textTraditional":"〔一一〕師古曰：「放，依也，音甫往反。」","sentenceOrder":45},
  {"id":"s_work_han_thu_94_46","chapterId":"ch_work_han_thu_94","textTraditional":"臣聞天人之際，精祲有以相盪，〔一〕善惡有以相推，事作乎下者象動乎上，陰陽之理各應其感，陰變則靜者動，陽蔽則明者晻，〔二〕水旱之災隨類而至。今關東連年饑饉，百姓乏困，或至相食，此皆生於賦斂多，民所共者大，〔三〕而吏安集之不稱之效也。陛下祗畏天戒，哀閔元元，大自減損，省甘泉、建章宮衛，罷珠崖，偃武行文，將欲度唐虞之隆，絕殷周之衰也。〔四〕諸見罷珠崖詔書者，莫不欣欣，人自以將見太平也。宜遂減宮室之度，省靡麗之飾，考制度，修外內，近忠正，遠巧佞，放鄭衛，進雅頌，舉異材，開直言，任溫良之人，退刻薄之吏，顯絜白之士，昭無欲之路，〔五〕覽六藝之意，察上世之務，明自然之道，博和睦之化，以崇至仁，匡失俗，易民視，〔六〕令海內昭然咸見本朝之所貴，道德弘於京師，淑問揚乎疆外，〔七〕然後大化可成，禮讓可興也。","sentenceOrder":46},
  {"id":"s_work_han_thu_94_47","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　李奇曰：「祲，氣也。言天人精氣相動也。」師古曰：「祲謂陰陽氣相浸漸以成災祥者也，音子鴆反。」","sentenceOrder":47},
  {"id":"s_work_han_thu_94_48","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　鄧展曰：「靜者動，謂地震也。明者晻，謂日蝕也。」師古曰：「晻與暗同。」","sentenceOrder":48},
  {"id":"s_work_han_thu_94_49","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「共讀曰供。」","sentenceOrder":49},
  {"id":"s_work_han_thu_94_50","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「度，過也。絕謂除其惡政也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_94_51","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　師古曰：「昭亦明也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_94_52","chapterId":"ch_work_han_thu_94","textTraditional":"〔六〕　師古曰：「匡，正也。易，變也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_94_53","chapterId":"ch_work_han_thu_94","textTraditional":"〔七〕　師古曰：「淑，善也。問，名也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_94_54","chapterId":"ch_work_han_thu_94","textTraditional":"上說其言，〔一〕遷衡為光祿大夫、太子少傅。","sentenceOrder":54},
  {"id":"s_work_han_thu_94_55","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":55},
  {"id":"s_work_han_thu_94_56","chapterId":"ch_work_han_thu_94","textTraditional":"時，上好儒術文辭，頗改宣帝之政，言事者多進見，人人自以為得上意。又傅昭儀及子定陶王愛幸，寵於皇后、太子。〔一〕衡復上疏曰：","sentenceOrder":56},
  {"id":"s_work_han_thu_94_57","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「寵，踰也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_94_58","chapterId":"ch_work_han_thu_94","textTraditional":"臣聞治亂安危之機，在乎審所用心。蓋受命之王務在創業垂統傳之無窮，繼體之君心存於承宣先王之德而褒大其功。昔者成王之嗣位，思述文武之道以養其心，休烈盛美皆歸之二后而不敢專其名，〔一〕是以上天歆享，鬼神祐焉。其詩曰：「念我皇祖，陟降廷止。」〔二〕言成王常思祖考之業，而鬼神祐助其治也。","sentenceOrder":58},
  {"id":"s_work_han_thu_94_59","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「休亦美也。烈，業也。后，君也。二君，文王、武王也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_94_60","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「周頌閔予小子之詩。言成王常念文王、武王之德，奉而行之，故鬼神上下臨其朝廷。」","sentenceOrder":60},
  {"id":"s_work_han_thu_94_61","chapterId":"ch_work_han_thu_94","textTraditional":"陛下聖德天覆，子愛海內，然陰陽未和，姦邪未禁者，殆論議者未丕揚先帝之盛功，〔一〕爭言制度不可用也，務變更之，〔二〕所更或不可行，而復復之，〔三〕是以群下更相是非，〔四〕吏民無所信。臣竊恨國家釋樂成之業，而虛為此紛紛也。〔五〕願陛上詳覽統業之事，留神於遵制揚功，以定群下之心。大雅曰：「無念爾祖，聿修厥德。」〔六〕孔子著之孝經首章，蓋至德之本也。傳曰：「審好惡，理情性，而王道畢矣。」能盡其性，然後能盡人物之性；能盡人物之性，可以贊天地之化。〔七〕治性之道，必審己之所有餘，而強其所不足。〔八〕蓋聰明疏通者戒於大察，寡聞少見者戒於雍蔽，〔九〕勇猛剛強者戒於大暴，仁愛溫良者戒於無斷，湛靜安舒者戒於後時，〔一０〕廣心浩大者戒於遺忘。必審己之所當戒，而齊之以義，然後中和之化應，而巧偽之徒不敢比周而望進。〔一一〕唯陛下戒所以崇聖德。","sentenceOrder":61},
  {"id":"s_work_han_thu_94_62","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「丕，大也。丕字或作本，言修其本業而顯揚也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_94_63","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「更，改也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_94_64","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「下復音扶目反。」","sentenceOrder":64},
  {"id":"s_work_han_thu_94_65","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「更音工衡反。」","sentenceOrder":65},
  {"id":"s_work_han_thu_94_66","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　師古曰：「釋，廢也。樂成，謂已成之業，人情所樂也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_94_67","chapterId":"ch_work_han_thu_94","textTraditional":"〔六〕　師古曰：「大雅文王之詩也。無念，念也。聿，述也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_94_68","chapterId":"ch_work_han_thu_94","textTraditional":"〔七〕　師古曰：「贊，明也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_94_69","chapterId":"ch_work_han_thu_94","textTraditional":"〔八〕　師古曰：「強，勉也，音其兩反。」","sentenceOrder":69},
  {"id":"s_work_han_thu_94_70","chapterId":"ch_work_han_thu_94","textTraditional":"〔九〕　師古曰：「雍讀曰壅。」","sentenceOrder":70},
  {"id":"s_work_han_thu_94_71","chapterId":"ch_work_han_thu_94","textTraditional":"〔一０〕師古曰：「湛讀曰沈。」","sentenceOrder":71},
  {"id":"s_work_han_thu_94_72","chapterId":"ch_work_han_thu_94","textTraditional":"〔一一〕師古曰：「比音頻寐反。」","sentenceOrder":72},
  {"id":"s_work_han_thu_94_73","chapterId":"ch_work_han_thu_94","textTraditional":"臣又聞室家之道修，則天下之理得，故詩始國風，〔一〕禮本冠婚。〔二〕始乎國風，原情性而明人倫也；本乎冠婚，正基兆而防未然也。福之興莫不本乎室家，（之道）〔道之〕衰莫不始乎梱內。〔三〕故聖王必慎妃后之際，別適長之位。〔四〕禮之於內也，卑不隃尊，新不先故，〔五〕所以統人情而理陰氣也。其尊適而卑庶也，適子冠乎阼，禮之用醴，〔六〕眾子不得與列，所以貴正體而明嫌疑也。非虛加其禮文而已，乃中心與之殊異，故禮探其情而見之外也。聖人動靜游燕，所親物得其序；〔七〕得其序，則海內自修，百姓從化。如當親者疏，當尊者卑，〔八〕則佞巧之姦因時而動，以亂國家。故聖人慎防其端，禁於未然，不以私恩害公義。陛下聖德純備，莫不修正，則天下無為而治。詩云：「于以四方，克定厥家。」〔九〕傳曰：「正家而天下定矣。」〔一０〕","sentenceOrder":73},
  {"id":"s_work_han_thu_94_74","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「關雎美后妃之德，而為國風之首。」","sentenceOrder":74},
  {"id":"s_work_han_thu_94_75","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「禮記冠義曰：『冠者，禮之始也。』婚義曰：『婚者，禮之本也。』」","sentenceOrder":75},
  {"id":"s_work_han_thu_94_76","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「梱與閫同，謂門橛也，音苦本反。」","sentenceOrder":76},
  {"id":"s_work_han_thu_94_77","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「適讀曰嫡。其下並同。」","sentenceOrder":77},
  {"id":"s_work_han_thu_94_78","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　師古曰：「隃與踰同。」","sentenceOrder":78},
  {"id":"s_work_han_thu_94_79","chapterId":"ch_work_han_thu_94","textTraditional":"〔六〕　師古曰：「阼，主階也。醴，甘酒也，貴於眾酒。」","sentenceOrder":79},
  {"id":"s_work_han_thu_94_80","chapterId":"ch_work_han_thu_94","textTraditional":"〔七〕　師古曰：「言凡物大小高卑，皆有次序。」","sentenceOrder":80},
  {"id":"s_work_han_thu_94_81","chapterId":"ch_work_han_thu_94","textTraditional":"〔八〕　師古曰：「如，若也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_94_82","chapterId":"ch_work_han_thu_94","textTraditional":"〔九〕　師古曰：「周頌桓之詩也。言欲治四方者，先當能定其家，從內以及外。」","sentenceOrder":82},
  {"id":"s_work_han_thu_94_83","chapterId":"ch_work_han_thu_94","textTraditional":"〔一０〕師古曰：「易家人卦之（象也）〔彖辭〕。」","sentenceOrder":83},
  {"id":"s_work_han_thu_94_84","chapterId":"ch_work_han_thu_94","textTraditional":"衡為少傅數年，數上疏陳便宜，及朝廷有政議，傅經以對，〔一〕言多法義。上以為任公卿，〔二〕由是為光祿勳、御史大夫。建昭三年，代韋玄成為丞相，封樂安侯，食邑六百戶。","sentenceOrder":84},
  {"id":"s_work_han_thu_94_85","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「傅讀曰附。附，依也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_94_86","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「任，堪也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_94_87","chapterId":"ch_work_han_thu_94","textTraditional":"元帝崩，成帝即位，衡上疏戒妃匹，勸經學威儀之則，曰：","sentenceOrder":87},
  {"id":"s_work_han_thu_94_88","chapterId":"ch_work_han_thu_94","textTraditional":"陛下秉至孝，哀傷思慕不絕於心，未有游虞弋射之宴，〔一〕誠隆於慎終追遠，無窮已也。〔二〕竊願陛下雖聖性得之，猶復加聖心焉。〔三〕詩云「煢煢在疚」，〔四〕言成王喪畢思慕，意氣未能平也，蓋所以就文武之業，崇大化之本也。〔五〕","sentenceOrder":88},
  {"id":"s_work_han_thu_94_89","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「虞與娛同。」","sentenceOrder":89},
  {"id":"s_work_han_thu_94_90","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「慎終，慎孝道之終也。追遠，不忘本也。論語稱孔子：『慎終追遠，則民德歸厚矣。』故衡引之。」","sentenceOrder":90},
  {"id":"s_work_han_thu_94_91","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「言天性已自然矣，又當加意也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_94_92","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「周頌閔予小子之詩。煢煢，憂貌也。疚，病也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_94_93","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　師古曰：「就，成也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_94_94","chapterId":"ch_work_han_thu_94","textTraditional":"臣又聞之師曰：「妃匹之際，生民之始，萬福之原。」婚姻之禮正，然後品物遂而天命全。〔一〕孔子論詩以關雎為始，言太上者民之父母，〔二〕后夫人之行不侔乎天地，則無以奉神靈之統而理萬物之宜。〔三〕故詩曰：「窈窕淑女，君子好仇。」〔四〕言能致其貞淑，不貳其操，情Q欲Y之感無介乎容儀，〔五〕宴私之意不形乎動靜，〔六〕夫然後可以配至尊而為宗廟主。此綱紀之首，王教之端也，自上世已來，三代興廢，未有不由此者也。願陛下詳覽得失盛衰之效以定大基，采有德，戒聲色，近嚴敬，遠技能。〔七〕","sentenceOrder":94},
  {"id":"s_work_han_thu_94_95","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「遂，成也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_94_96","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「太上，居尊上之位也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_94_97","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「侔，等也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_94_98","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「周南關雎之詩也。窈窕，幽閒也。仇，匹也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_94_99","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　服虔曰：「不見色於容儀也。」師古曰：「介，繫也。言不以情Q欲Y繫心，而著於容儀者。」","sentenceOrder":99},
  {"id":"s_work_han_thu_94_100","chapterId":"ch_work_han_thu_94","textTraditional":"〔六〕　師古曰：「形，見也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_94_101","chapterId":"ch_work_han_thu_94","textTraditional":"〔七〕　師古曰：「無德之人，雖有技能則斥遠之。」","sentenceOrder":101},
  {"id":"s_work_han_thu_94_102","chapterId":"ch_work_han_thu_94","textTraditional":"竊見聖德純茂，專精詩書，好樂無厭。〔一〕臣衡材駑，無以輔相善義，宣揚德音。〔二〕臣聞六經者，聖人所以統天地之心，著善惡之歸，明吉凶之分，通人道之正，〔三〕使不悖於其本性者也。〔四〕故審六藝之指，則人天之理可得而和，草木昆蟲可得而育，此永永不易之道也。〔五〕及論語、孝經，聖人言行之要，宜究其意。〔六〕","sentenceOrder":102},
  {"id":"s_work_han_thu_94_103","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「樂音五教反。」","sentenceOrder":103},
  {"id":"s_work_han_thu_94_104","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「相，助也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_94_105","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「分音扶問反。」","sentenceOrder":105},
  {"id":"s_work_han_thu_94_106","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「悖，乖也，音布內反。」","sentenceOrder":106},
  {"id":"s_work_han_thu_94_107","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　師古曰：「易，變也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_94_108","chapterId":"ch_work_han_thu_94","textTraditional":"〔六〕　師古曰：「究，盡也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_94_109","chapterId":"ch_work_han_thu_94","textTraditional":"臣又聞聖王之自為動靜周旋，奉天承親，臨朝享臣，物有節文，以章人倫。〔一〕蓋欽翼祗栗，事天之容也；溫恭敬遜，承親之禮也；正躬嚴恪，臨眾之儀也；〔二〕嘉惠和說，饗下之顏也。〔三〕舉錯動作，物遵其儀，故形為仁義，動為法則。孔子曰：「德義可尊，容止可觀，進退可度，以臨其民，是以其民畏而愛之，則而象之。」〔四〕大雅云：「敬慎威儀，惟民之則。」〔五〕諸侯正月朝覲天子，天子惟道德，昭穆穆以視之，〔六〕又觀以禮樂，饗醴乃歸。〔七〕故萬國莫不獲賜祉福，蒙化而成俗。今正月初幸路寢，臨朝賀，置酒以饗萬方，傳曰「君子慎始」，願陛下留神動靜之節，使群下得望盛德休光，〔八〕以立基楨，天下幸甚！","sentenceOrder":109},
  {"id":"s_work_han_thu_94_110","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「物，事也，事事皆有節文。」","sentenceOrder":110},
  {"id":"s_work_han_thu_94_111","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「嚴讀曰儼。」","sentenceOrder":111},
  {"id":"s_work_han_thu_94_112","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「說讀曰悅。饗，燕饗也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_94_113","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「孝經載孔子之言也。則，法也。象，似也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_94_114","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　師古曰：「抑之詩。」","sentenceOrder":114},
  {"id":"s_work_han_thu_94_115","chapterId":"ch_work_han_thu_94","textTraditional":"〔六〕　師古曰：「昭，明也。穆穆，天子之容也。視讀曰示。」","sentenceOrder":115},
  {"id":"s_work_han_thu_94_116","chapterId":"ch_work_han_thu_94","textTraditional":"〔七〕　師古曰：「觀亦視也。饗醴，以醴酒饗也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_94_117","chapterId":"ch_work_han_thu_94","textTraditional":"〔八〕　師古曰：「休，美也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_94_118","chapterId":"ch_work_han_thu_94","textTraditional":"上敬納其言。頃之，衡復奏正南北郊，罷諸淫祀，語在郊祀志。","sentenceOrder":118},
  {"id":"s_work_han_thu_94_119","chapterId":"ch_work_han_thu_94","textTraditional":"初，元帝時，中書令石顯用事，自前相韋玄成及衡皆畏顯，不敢失其意。至成帝初即位，衡乃與御史大夫甄譚共奏顯，追條其舊惡，并及黨與。於是司隸校尉王尊劾奏：「衡、譚居大臣位，知顯等專權勢，作威福，為海內患害，不以時白奏行罰，而阿諛曲從，附下罔上，無大臣輔政之義。既奏顯等，不自陳不忠之罪，而反揚著先帝任用傾覆之徒，〔一〕罪至不道。」有詔勿劾。衡慚懼，上疏謝罪，因稱病乞骸骨，上丞相樂安侯印綬。上報曰：「君以道德修明，位在三公，先帝委政，遂及朕躬。君遵修法度，勤勞公家，朕嘉與君同心合意，庶幾有成。今司隸校尉尊妄詆欺，加非於君，〔二〕朕甚閔焉。方下有司問狀，〔三〕君何疑而上書歸侯乞骸骨，是章朕之未燭也〔四〕。傳不云乎？『禮義不愆，何恤人之言！』〔五〕君其察焉。專精神，近醫藥，強食自愛。」因賜上尊酒、養牛。〔六〕衡起視事。上以新即位，褒優大臣，然群下多是王尊者。衡嘿嘿不自安，每有水旱，風雨不時，連乞骸骨讓位。上輒以詔書慰撫，不許。","sentenceOrder":119},
  {"id":"s_work_han_thu_94_120","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「著，明也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_94_121","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「詆，毀也，音丁禮反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_94_122","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「問司隸。」","sentenceOrder":122},
  {"id":"s_work_han_thu_94_123","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「燭，照也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_94_124","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　師古曰：「愆，過也。恤，憂也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_94_125","chapterId":"ch_work_han_thu_94","textTraditional":"〔六〕　師古曰：「上尊，解在薛廣德傳。」","sentenceOrder":125},
  {"id":"s_work_han_thu_94_126","chapterId":"ch_work_han_thu_94","textTraditional":"久之，衡子昌為越騎校尉，醉殺人，繫詔獄。越騎官屬與昌弟且謀篡昌。〔一〕事發覺，衡免冠徒跣待罪，天子使謁者詔衡冠履。而有司奏衡專地盜土，衡竟坐免。","sentenceOrder":126},
  {"id":"s_work_han_thu_94_127","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「逆取曰篡。」","sentenceOrder":127},
  {"id":"s_work_han_thu_94_128","chapterId":"ch_work_han_thu_94","textTraditional":"初，衡封僮之樂安鄉，〔一〕鄉本田隄封三千一百頃，〔二〕南以閩佰為界。〔三〕初元元年，郡圖誤以閩佰為平陵佰。積十餘歲，衡封臨淮郡，〔四〕遂封真平陵佰以為界，多四百頃。至建始元年，郡乃定國界，上計簿，更定圖，言丞相府。衡謂所親吏趙殷曰：〔五〕「主簿陸賜故居奏曹，習事曉知國界，署集曹掾。」明年治計時，衡問殷國界事：「曹欲柰何？」殷曰：「賜以為舉計，令郡實之〔六〕。恐郡不肯從實，可令家丞上書。」衡曰：「顧當得不耳，何至上書？」〔七〕亦不告曹使舉也，聽曹為之。後賜與屬明舉計曰：「案故圖，樂安鄉南以平陵佰為界，不（足）〔從〕故而以閩佰為界，解何？」〔八〕郡即復以四百頃付樂安國。衡遣從史之僮，收取所還田租穀千餘石入衡家。司隸校尉駿、少府忠行廷尉事劾奏「衡監臨盜所主守直十金以上。〔九〕春秋之義，諸侯不得專地，所以壹統尊法制也。衡位三公，輔國政，領計簿，知郡實，正國界，計簿已定而背法制，專地盜土以自益，及賜、明阿承衡意，猥舉郡計，亂減縣界〔一０〕，附下罔上，擅以地附益大臣，皆不道。」於是上可其奏，勿治，丞相免為庶人，終於家。","sentenceOrder":128},
  {"id":"s_work_han_thu_94_129","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　文穎曰：「屬臨淮郡。」","sentenceOrder":129},
  {"id":"s_work_han_thu_94_130","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「提封，舉其封界內之總數。」","sentenceOrder":130},
  {"id":"s_work_han_thu_94_131","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「佰者，田之東西界也。閩者，佰之名也。佰音莫客反。」","sentenceOrder":131},
  {"id":"s_work_han_thu_94_132","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　蘇林曰：「平陵佰在閩佰南，誤十餘歲，衡乃始封此鄉。」〔晉灼曰：「舉郡而言耳，自封縣也。〕」","sentenceOrder":132},
  {"id":"s_work_han_thu_94_133","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　師古曰：「所親，素所親任者。」","sentenceOrder":133},
  {"id":"s_work_han_thu_94_134","chapterId":"ch_work_han_thu_94","textTraditional":"〔六〕　師古曰：「舉發上計之簿，令郡（故）〔改〕從平陵佰以為定實。」","sentenceOrder":134},
  {"id":"s_work_han_thu_94_135","chapterId":"ch_work_han_thu_94","textTraditional":"〔七〕　師古曰：「顧，念也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_94_136","chapterId":"ch_work_han_thu_94","textTraditional":"〔八〕　師古曰：「不足故者，不依故圖而滿足也。解何者，以分解此時意，猶今言分疏也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_94_137","chapterId":"ch_work_han_thu_94","textTraditional":"〔九〕　師古曰：「十金以上，當時律定罪之次，若今律條言一尺以上，一匹以上。」","sentenceOrder":137},
  {"id":"s_work_han_thu_94_138","chapterId":"ch_work_han_thu_94","textTraditional":"〔一０〕師古曰：「猥，曲也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_94_139","chapterId":"ch_work_han_thu_94","textTraditional":"子咸亦明經，歷位九卿。家世多為博士者。","sentenceOrder":139},
  {"id":"s_work_han_thu_94_140","chapterId":"ch_work_han_thu_94","textTraditional":"張禹字子文，河內軹人也，至禹父徙家蓮（白）〔勺〕。〔一〕禹為兒，數隨家至市，喜觀於卜相者前。〔二〕久之，頗曉其別蓍布卦意，〔三〕時從旁言。卜者愛之，又奇其面貌，謂禹父：「是兒多知，可令學經。」及禹壯，至長安學，從沛郡施讎受易，琅邪王陽、膠東庸生問論語，既皆明習，有徒眾，舉為郡文學。甘露中，諸儒薦禹，有詔太子太傅蕭望之問。禹對易及論語大義，望之善焉，奏禹經學精習，有師法，可試事。〔四〕奏寑，罷歸故官。〔五〕久之，試為博士。初元中，立皇太子，而博士鄭寬中以尚書授太子，薦言禹善論語。詔令禹授太子論語，由是遷光祿大夫。數歲，出為東平內史。","sentenceOrder":140},
  {"id":"s_work_han_thu_94_141","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「左馮翊縣名也，音輦酌。」","sentenceOrder":141},
  {"id":"s_work_han_thu_94_142","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「至其人之前而觀之。喜音許吏反。」","sentenceOrder":142},
  {"id":"s_work_han_thu_94_143","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「別，分也，音彼列反。」","sentenceOrder":143},
  {"id":"s_work_han_thu_94_144","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「試以職事也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_94_145","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　師古曰：「寑謂不下也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_94_146","chapterId":"ch_work_han_thu_94","textTraditional":"元帝崩，成帝即位，徵禹、寬中，皆以師賜爵關內侯，寬中食邑八百戶，禹六百戶。拜為諸吏光祿大夫，秩中二千石，給事中，領尚書事。是時，帝舅陽平侯王鳳為大將軍輔政專權，而上富於春秋，謙讓，方鄉經學，敬重師傅。〔一〕而禹與鳳並領尚書，內不自安，數病上書乞骸骨，欲退避鳳。上報曰：「朕以幼年執政，萬機懼失其中，君以道德為師，故委國政。君何疑而數乞骸骨，忽忘雅素，欲避流言？〔二〕朕無聞焉。〔三〕君其固心致思，總秉諸事，推以孳孳，無違朕意。」加賜黃金百斤、養牛、上尊酒，太官致餐，侍醫視疾，使者臨問。〔四〕禹惶恐，復起視事，河平四年代王商為丞相，封安昌侯。","sentenceOrder":146},
  {"id":"s_work_han_thu_94_147","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":147},
  {"id":"s_work_han_thu_94_148","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「雅素，故也。謂師傅故舊之恩。」","sentenceOrder":148},
  {"id":"s_work_han_thu_94_149","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「不聞有毀短之言。」","sentenceOrder":149},
  {"id":"s_work_han_thu_94_150","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「侍醫，侍天子之醫。」","sentenceOrder":150},
  {"id":"s_work_han_thu_94_151","chapterId":"ch_work_han_thu_94","textTraditional":"為相六歲，鴻嘉元年以老病乞骸骨，上加優再三，乃聽許。賜安車駟馬，黃金百斤，罷就第，以列侯朝朔望，位特進，見禮如丞相，置從事史五人，益封四百戶。天子數加賞賜，前後數千萬。","sentenceOrder":151},
  {"id":"s_work_han_thu_94_152","chapterId":"ch_work_han_thu_94","textTraditional":"禹為人謹厚，內殖貨財，〔一〕家以田為業。及富貴，多買田至四百頃，皆涇、渭溉灌，極膏腴上賈。〔二〕它財物稱是。禹性習知音聲，內奢淫，身居大第，後堂理絲竹筦弦。〔三〕","sentenceOrder":152},
  {"id":"s_work_han_thu_94_153","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「殖，生也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_94_154","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「賈讀曰價。」","sentenceOrder":154},
  {"id":"s_work_han_thu_94_155","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　如淳曰：「今樂家五日一習樂為理樂。」師古曰：「筦亦管字。」","sentenceOrder":155},
  {"id":"s_work_han_thu_94_156","chapterId":"ch_work_han_thu_94","textTraditional":"禹成就弟子尤著者，淮陽彭宣至大司空，沛郡戴崇至少府九卿。宣為人恭儉有法度，而崇愷弟多智，〔一〕二人異行。禹心親愛崇，敬宣而疏之。崇每候禹，常責師宜置酒設樂與弟子相娛。禹將崇入後堂飲食，婦女相對，優人筦弦鏗鏘極樂，昏夜乃罷。〔二〕而宣之來也，禹見之於便坐，〔三〕講論經義，日晏賜食，不過一肉卮酒相對。〔四〕宣未嘗得至後堂。及兩人皆聞知，各自得也。〔五〕","sentenceOrder":156},
  {"id":"s_work_han_thu_94_157","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「愷，樂也。弟，易也。言性和樂而簡易。」","sentenceOrder":157},
  {"id":"s_work_han_thu_94_158","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「極樂，盡其歡樂之情。」","sentenceOrder":158},
  {"id":"s_work_han_thu_94_159","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「便坐，謂非正寢，在於旁側可以延賓者也。坐音才臥反。」","sentenceOrder":159},
  {"id":"s_work_han_thu_94_160","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「一豆之肉，一卮行酒。」","sentenceOrder":160},
  {"id":"s_work_han_thu_94_161","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　服虔曰：「各自為得宜。」","sentenceOrder":161},
  {"id":"s_work_han_thu_94_162","chapterId":"ch_work_han_thu_94","textTraditional":"禹年老，自治冢塋，起祠室，好平陵肥牛亭部處地，〔一〕又近延陵，奏請求之，上以賜禹，詔令平陵徙亭它所。曲陽侯根聞而爭之：「此地當平陵寢廟衣冠所出游道，禹為師傅，不遵謙讓，至求衣冠所游之道，又徙壞舊亭，重非所宜。〔二〕孔子稱『賜愛其羊，我愛其禮』，〔三〕宜更賜禹它地。」根雖為舅，上敬重之不如禹，根言雖切，猶不見從，卒以肥牛亭地賜禹。根由是害禹寵，數毀惡之〔四〕。天子愈益敬厚禹。禹每病，輒以起居聞，〔五〕車駕自臨問之。上親拜禹床下，禹頓首謝恩，〔因〕歸誠，言「老臣有四男一女，愛女甚於男，遠嫁為張掖太守蕭咸妻，不勝父子私情，思與相近。」上即時徙咸為弘農太守。又禹小子未有官，上臨候禹，禹數視其小子，上即禹床下拜為黃門郎，給事中。","sentenceOrder":162},
  {"id":"s_work_han_thu_94_163","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「肥牛，亭名。欲得置亭處之地為冢塋。」","sentenceOrder":163},
  {"id":"s_work_han_thu_94_164","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「重音直用反。」","sentenceOrder":164},
  {"id":"s_work_han_thu_94_165","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「論語云子貢欲去告朔之餼羊，孔子曰：『賜也，爾愛其羊，我愛其禮。』故引之。」","sentenceOrder":165},
  {"id":"s_work_han_thu_94_166","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「惡謂言其過惡。」","sentenceOrder":166},
  {"id":"s_work_han_thu_94_167","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　師古曰：「謂其食飲寢臥之增損。」","sentenceOrder":167},
  {"id":"s_work_han_thu_94_168","chapterId":"ch_work_han_thu_94","textTraditional":"禹雖家居，以特進為天子師，國家每有大政，必與定議。〔一〕永始、元延之間，日蝕地震尤數，吏民多上書言災異之應，譏切王氏專政所致。上懼變異數見，意頗然之，未有以明見，乃車駕至禹弟，辟左右，〔二〕親問禹以天變，因用吏民所言王氏事示禹。禹自見年老，子孫弱，又與曲陽侯不平，恐為所怨。禹則謂上曰：「春秋二百四十二年間，日蝕三十餘，地震五（十六），或為諸侯相殺，或夷狄侵中國。災變之異深遠難見，故聖人罕言命，不語怪神。〔三〕性與天道，自子贛之屬不得聞，〔四〕何況淺見鄙儒之所言！陛下宜修政事以善應之，與下同其福喜，此經義意也。新學小生，亂道誤人，宜無信用，以經術斷之。」上雅信愛禹，由此不疑王氏。後曲陽侯根及諸王子弟聞知禹言，皆喜說，〔五〕遂親就禹。禹見時有變異，若上體不安，擇日絜齋露蓍，〔六〕正衣冠立筮，得吉卦則獻其占，如有不吉，禹為感動憂色。","sentenceOrder":168},
  {"id":"s_work_han_thu_94_169","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「與讀曰豫。」","sentenceOrder":169},
  {"id":"s_work_han_thu_94_170","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「辟讀曰闢。」","sentenceOrder":170},
  {"id":"s_work_han_thu_94_171","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「罕，稀也。論語云『子罕言利與命與仁』，又曰『子不語怪力亂神』。」","sentenceOrder":171},
  {"id":"s_work_han_thu_94_172","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「論語云『夫子之言性與天道不可得而聞也』，謂孔子未嘗言性命之事及天道。」","sentenceOrder":172},
  {"id":"s_work_han_thu_94_173","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　師古曰：「說讀曰悅。」","sentenceOrder":173},
  {"id":"s_work_han_thu_94_174","chapterId":"ch_work_han_thu_94","textTraditional":"〔六〕　服虔曰：「露（筮）易蓍於星宿下，明日乃用。言得天氣也。」師古曰：「蓍，草名，筮者所用也，音式夷反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_94_175","chapterId":"ch_work_han_thu_94","textTraditional":"成帝崩，禹及事哀帝，建平二年薨，諡曰節侯。禹四子，長子宏嗣侯，官至太常，列於九卿。三弟皆為校尉散騎諸曹。","sentenceOrder":175},
  {"id":"s_work_han_thu_94_176","chapterId":"ch_work_han_thu_94","textTraditional":"初，禹為師，以上難數對己問經，為論語章句獻之。始魯扶卿及夏侯勝、王陽、蕭望之、韋玄成皆說論語，篇第或異。禹先事王陽，後從庸生，采獲所安，最後出而尊貴。諸儒為之語曰：「欲為論，念張文。」由是學者多從張氏，餘家寖微。〔一〕","sentenceOrder":176},
  {"id":"s_work_han_thu_94_177","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「寖，漸也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_94_178","chapterId":"ch_work_han_thu_94","textTraditional":"孔光字子夏，孔子十四世之孫也。孔子生伯魚鯉，〔一〕鯉生子思伋，〔二〕伋生子上帛，帛生子家求，求生子真箕，箕生子高穿。穿生順，順為魏相。順生鮒，鮒為陳涉博士，死陳下。鮒弟子襄為孝惠博士，長沙太傅。襄生忠，忠生武及安國，武生延年。延年生霸，字次儒。霸生光焉。安國、延年皆以治尚書為武帝博士。安國至臨淮太守。霸亦治尚書，事太傅夏侯勝，昭帝末年為博士，宣帝時為太中大夫，以選授皇太子經，遷詹事，高密相。是時，諸侯王相在郡守上。","sentenceOrder":178},
  {"id":"s_work_han_thu_94_179","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「名鯉，字伯魚。先言其字者，孔氏自為譜諜，示尊其先也。下皆類此。」","sentenceOrder":179},
  {"id":"s_work_han_thu_94_180","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「伋音級。」","sentenceOrder":180},
  {"id":"s_work_han_thu_94_181","chapterId":"ch_work_han_thu_94","textTraditional":"元帝即位，徵霸，以師賜爵關內侯，食邑八百戶，號褒成君〔一〕，給事中，加賜黃金二百斤，第一區，徙名數于長安。〔二〕霸為人謙退，不好權勢，常稱爵位泰過，何德以堪之！上欲致霸相位，自御史大夫貢禹卒，及薛廣德免，輒欲拜霸。霸讓位，自陳至三，上深知其至誠，乃弗用。以是敬之，賞賜甚厚。及霸薨，上素服臨弔者再，至賜東園祕器錢帛，策贈以列侯禮，諡曰烈君。","sentenceOrder":181},
  {"id":"s_work_han_thu_94_182","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　如淳曰：「為帝師，教令成就，故曰褒成君。」","sentenceOrder":182},
  {"id":"s_work_han_thu_94_183","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「名數，戶籍也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_94_184","chapterId":"ch_work_han_thu_94","textTraditional":"霸四子，長子福嗣關內侯。次子捷、捷弟喜皆列校尉諸曹。光，最少子也，經學尤明，年未二十，舉為議郎。光祿勳匡衡舉光方正，為諫大夫。坐議有不合，左遷虹長，〔一〕自免歸教授。成帝初即位，舉為博士，數使錄冤獄，行風俗，〔二〕振贍流民，奉使稱旨，由是知名。是時，博士選三科，高（第）為尚書，次為刺史，其不通政事，以久次補諸侯太傅。光以高第為尚書，觀故事品式，數歲明習漢制及法令。上甚信任之，轉為僕射，尚書令。〔三〕有詔光周密謹慎，未嘗有過，加諸吏官，以子男放為侍郎，給事黃門。數年，遷諸吏光祿大夫，秩中二千石，給事中，賜黃金百斤，領尚書事。後為光祿勳，復領尚書，諸吏給事中如故。凡典樞機十餘年，守法度，修故事。上有所問，據經法以心所安而對，不希指苟合；〔四〕如或不從，不敢強諫爭，以是久而安。時有所言，輒削草稿，〔五〕以為章主之過，以奸忠直，人臣大罪也。〔六〕有所薦舉，唯恐其人之聞知。沐日歸休，兄弟妻子燕語，終不及朝省政事。或問光：「溫室省中樹皆何木也？」〔七〕光嘿不應，更答以它語，其不泄如是。光帝師傅子，少以經行自著，進官蚤成。〔八〕不結黨友，養游說，有求於人。既性自守，亦其勢然也。〔九〕徙光祿勳為御史大夫。","sentenceOrder":184},
  {"id":"s_work_han_thu_94_185","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「不合，謂不合天子意也。虹，沛之縣也，音貢。」","sentenceOrder":185},
  {"id":"s_work_han_thu_94_186","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「行音下更反。」","sentenceOrder":186},
  {"id":"s_work_han_thu_94_187","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「先為僕射，後為尚書令。」","sentenceOrder":187},
  {"id":"s_work_han_thu_94_188","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「希指，希望天子之旨意也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_94_189","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　（師古）〔服虔〕曰：「言已繕（事）書，輒削壞其草。」","sentenceOrder":189},
  {"id":"s_work_han_thu_94_190","chapterId":"ch_work_han_thu_94","textTraditional":"〔六〕　師古曰：「奸，求也。奸忠直之名也。奸音干。」","sentenceOrder":190},
  {"id":"s_work_han_thu_94_191","chapterId":"ch_work_han_thu_94","textTraditional":"〔七〕　晉灼曰：「長樂宮中有溫室殿。」","sentenceOrder":191},
  {"id":"s_work_han_thu_94_192","chapterId":"ch_work_han_thu_94","textTraditional":"〔八〕　師古曰：「蚤，古早字。」","sentenceOrder":192},
  {"id":"s_work_han_thu_94_193","chapterId":"ch_work_han_thu_94","textTraditional":"〔九〕　師古曰：「言以名父之子，學宦早成，不須黨援也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_94_194","chapterId":"ch_work_han_thu_94","textTraditional":"綏和中，上即位二十五年，無繼嗣，至親有同產弟中山孝王及同產弟子定陶王在。定陶王好學多材，於帝子行。〔一〕而王祖母傅太后陰為王求漢嗣，私事趙皇后、昭儀及帝舅大司馬驃騎將軍王根，故皆勸上。上於是召丞相翟方進、御史大夫光、右將軍廉褒、後將軍朱博，皆引入禁中，議中山、定陶王誰宜為嗣者。方進、根以為定陶王帝弟之子，禮曰「昆弟之子猶子也」，「為其後者為之子也」，定陶王宜為嗣。褒、博皆如方進、根議。光獨以為禮立嗣以親，中山王先帝之子，帝親弟也，以尚書盤庚殷之及王為比，〔二〕中山王宜為嗣。上以禮兄弟不相入廟，又皇后、昭儀欲立定陶王，故遂立為太子。光以議不中意，左遷廷尉。〔三〕","sentenceOrder":194},
  {"id":"s_work_han_thu_94_195","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「行音胡浪反。」","sentenceOrder":195},
  {"id":"s_work_han_thu_94_196","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「兄終弟及也。比音必寐反。」","sentenceOrder":196},
  {"id":"s_work_han_thu_94_197","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「中，當也。」","sentenceOrder":197},
  {"id":"s_work_han_thu_94_198","chapterId":"ch_work_han_thu_94","textTraditional":"光久典尚書，練法令，號稱詳平。時定陵侯淳于長坐大逆誅，長小妻迺始等六人皆以長事未發覺時棄去，或更嫁。及長事發，丞相方進、大司空武議，〔一〕以為「令，犯法者各以法時律令論之，〔二〕明有所訖也。〔三〕長犯大逆時，迺始等見為長妻，已有當坐之罪，與身犯法無異。後乃棄去，於法無以解。〔四〕請論。」光議以為「大逆無道，父母妻子同產無少長皆棄市，欲懲後犯法者也。〔五〕夫婦之道，有義則合，無義則離。長未自知當坐大逆之法，而棄去迺始等，或更嫁，義已絕，而欲以為長妻論殺之，名不正，不當坐。」有詔光議是。","sentenceOrder":198},
  {"id":"s_work_han_thu_94_199","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「翟方進及何武。」","sentenceOrder":199},
  {"id":"s_work_han_thu_94_200","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「此（其）〔具〕引令條之文也。法時謂始犯法之時也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_94_201","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「訖，止也。」","sentenceOrder":201},
  {"id":"s_work_han_thu_94_202","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「解，免也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_94_203","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　師古曰：「懲，創止也。」","sentenceOrder":203},
  {"id":"s_work_han_thu_94_204","chapterId":"ch_work_han_thu_94","textTraditional":"是歲，右將軍褒、後將軍博坐定陵、紅陽侯〔一〕皆免為庶人。以光為左將軍，居右將軍官職，執金吾王咸為右將軍，居後將軍官職。罷後將軍官。數月，丞相方進薨，召左將軍光，當拜，已刻侯印書贊，〔二〕上暴崩，即其夜於大行前拜受丞相博山侯印綬。","sentenceOrder":204},
  {"id":"s_work_han_thu_94_205","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「廉褒、朱博坐與淳于長、王立交厚也。」","sentenceOrder":205},
  {"id":"s_work_han_thu_94_206","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「贊，進也，延進而拜之。書贊者，書贊辭於策也。」","sentenceOrder":206},
  {"id":"s_work_han_thu_94_207","chapterId":"ch_work_han_thu_94","textTraditional":"哀帝初即位，躬行儉約，省減諸用，政事由己出，朝廷翕然，望至治焉。褒賞大臣，益封光千戶。時成帝母太皇太后自居長樂宮，而帝祖母定陶傅太后在國邸，有詔問丞相、大司空：「定陶共王太后宜當何居？」光素聞傅太后為人剛暴，長於權謀，自帝在襁褓而養長教道至於成人，帝之立又有力。光心恐傅太后與政事，〔一〕不欲令與帝旦夕相近，即議以為定陶太后宜改築宮。大司空何武曰：「可居北宮。」上從武言。北宮有紫房復道通未央宮，〔二〕傅太后果從復道朝夕至帝所，求欲稱尊號，貴寵其親屬，使上不得直道（而）行〔三〕。頃之，太后從弟子傅遷在左右尤傾邪，上免官遣歸故郡。傅太后怒，上不得已復留遷。光與大司空師丹奏言：「詔書『侍中駙馬都尉遷巧佞無義，漏泄不忠，國之賊也，免歸故郡。』復有詔止。天下疑惑，無所取信，虧損聖德，誠不小愆。陛下以變異連見，避正殿，見群臣，思求其故，至今未有所改。〔四〕臣請歸遷故郡，以銷姦黨，應天戒。」卒不得遣，復為侍中。脅於傅太后，皆此類也。","sentenceOrder":207},
  {"id":"s_work_han_thu_94_208","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「與讀曰豫。」","sentenceOrder":208},
  {"id":"s_work_han_thu_94_209","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「復讀曰複。」","sentenceOrder":209},
  {"id":"s_work_han_thu_94_210","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「不得依正直之道。」","sentenceOrder":210},
  {"id":"s_work_han_thu_94_211","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「舊有不善之事，皆未改除。」","sentenceOrder":211},
  {"id":"s_work_han_thu_94_212","chapterId":"ch_work_han_thu_94","textTraditional":"又傅太后欲與成帝母俱稱尊號，群下多順指，言母以子貴，宜立尊號以厚孝道。唯師丹與光持不可。〔一〕上重違大臣正議，〔二〕又內迫傅太后，猗違者連歲。〔三〕丹以罪免，而朱博代為大司空。光自先帝時議繼嗣有持異之隙矣，又重忤傅太后指，〔四〕由是傅氏在位者與朱博為表裏，共毀譖光。後數月遂策免光曰：「丞相者，朕之股肱，所與共承宗廟，統理海內，〔五〕輔朕之不逮以治天下也。朕既不明，災異重仍，〔六〕日月無光，山崩河決，五星失行，是章朕之不德而股肱之不良也。〔七〕君前為御史大夫，輔翼先帝，出入八年，卒無忠言嘉謀，今相朕，出入三年，憂國之風復無聞焉。陰陽錯謬，歲比不登，〔八〕天下空虛，百姓饑饉，父子分散，流離道路，以十萬數。而百官群職曠廢，〔九〕姦軌放縱，盜賊並起，或攻官寺，殺長吏。數以問君，君無怵惕憂懼之意，對毋能為。〔一０〕是以群卿大夫咸惰哉莫以為意，咎由君焉。君秉社稷之重，總百僚之任，上無以匡朕之闕，下不能綏安百姓。書不云乎？『毋曠庶官，天工人其代之。』〔一一〕於虖！〔一二〕君其上丞相博山侯印綬，罷歸。」〔一三〕","sentenceOrder":212},
  {"id":"s_work_han_thu_94_213","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　蘇林曰：「執持不可。」","sentenceOrder":213},
  {"id":"s_work_han_thu_94_214","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「重，難也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_94_215","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　如淳曰：「不決事之言也。」師古曰：「猗違猶依違耳。猗音於奇反。」","sentenceOrder":215},
  {"id":"s_work_han_thu_94_216","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「重音直用反。」","sentenceOrder":216},
  {"id":"s_work_han_thu_94_217","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　師古曰：「共讀曰恭。」","sentenceOrder":217},
  {"id":"s_work_han_thu_94_218","chapterId":"ch_work_han_thu_94","textTraditional":"〔六〕　師古曰：「仍，頻也。重音直用反。」","sentenceOrder":218},
  {"id":"s_work_han_thu_94_219","chapterId":"ch_work_han_thu_94","textTraditional":"〔七〕　師古曰：「章，明也。」","sentenceOrder":219},
  {"id":"s_work_han_thu_94_220","chapterId":"ch_work_han_thu_94","textTraditional":"〔八〕　師古曰：「比，頻也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_94_221","chapterId":"ch_work_han_thu_94","textTraditional":"〔九〕　師古曰：「曠，空也。」","sentenceOrder":221},
  {"id":"s_work_han_thu_94_222","chapterId":"ch_work_han_thu_94","textTraditional":"〔一０〕師古曰：「言盜賊不能為害。」","sentenceOrder":222},
  {"id":"s_work_han_thu_94_223","chapterId":"ch_work_han_thu_94","textTraditional":"〔一一〕師古曰：「虞書咎繇謨之辭也。位非其人，是為空官。言人代天理官，不可以天官私非其材。」","sentenceOrder":223},
  {"id":"s_work_han_thu_94_224","chapterId":"ch_work_han_thu_94","textTraditional":"〔一二〕師古曰：「於讀曰烏。虖讀曰呼。」","sentenceOrder":224},
  {"id":"s_work_han_thu_94_225","chapterId":"ch_work_han_thu_94","textTraditional":"〔一三〕師古曰：「漢舊儀云丞相有它過，使者奉策書，即時步出府，乘棧車歸田里。」","sentenceOrder":225},
  {"id":"s_work_han_thu_94_226","chapterId":"ch_work_han_thu_94","textTraditional":"光退閭里，杜門自守。〔一〕而朱博代為丞相，數月，坐承傅太后指妄奏事自殺。平當代為丞相，數月薨。王嘉復為丞相，數諫爭忤指。旬歲間閱三相，〔二〕議者皆以為不及光。上由是思之。","sentenceOrder":226},
  {"id":"s_work_han_thu_94_227","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「杜，塞也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_94_228","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「閱猶歷也。」","sentenceOrder":228},
  {"id":"s_work_han_thu_94_229","chapterId":"ch_work_han_thu_94","textTraditional":"會元壽元年正月朔日有蝕之，後十餘日傅太后崩。是月徵光詣公車，問日蝕事。光對曰：「臣聞日者，眾陽之宗，人君之表，至尊之象。君德衰微，陰道盛彊，侵蔽陽明，則日蝕應之。書曰『羞用五事』，『建用皇極』。〔一〕如貌、言、視、聽、思失，〔二〕大中之道不立，則咎徵薦臻，六極屢降。皇之不極，是為大中不立，其傳曰『時則有日月亂行』，謂朓、側匿，〔三〕甚則薄蝕是也。又曰『六沴之作』，〔四〕歲之朝曰三朝，〔五〕其應至重。乃正月辛丑朔日有蝕之，變見三朝之會。上天聰明，苟無其事，變不虛生。書曰『惟先假王正厥事』，〔六〕言異變之來，起事有不正也。臣聞師曰，天（右）〔左〕與王者，〔七〕故災異數見，以譴告之，欲其改更。若不畏懼，有以塞除，而輕忽簡誣，則凶罰加焉，其至可必。〔八〕詩曰：『敬之敬之，天惟顯思，命不易哉！』〔九〕又曰：『畏天之威，于時保之。』〔一０〕皆謂不懼者凶，懼之則吉也。陛下聖德聰明，兢兢業業，〔一一〕承順天戒，敬畏變異，勤心虛己，延見群臣，思求其故，然後敕躬自約，總正萬事，放遠讒說之黨，援納斷斷之介，〔一二〕退去貪殘之徒，進用賢良之吏，平刑罰，薄賦斂，恩澤加於百姓，誠為政之大本，應變之至務也。天下幸甚。書曰『天既付命正厥德』，〔一三〕言正德以順天也。又曰『天棐諶辭』，〔一四〕言有誠道，天輔之也。明承順天道在於崇德博施，加精致誠，孳孳而已。〔一五〕俗之祈禳小數，終無益於應天塞異，銷禍興福，〔一六〕較然甚明，無可疑惑。」〔一七〕","sentenceOrder":229},
  {"id":"s_work_han_thu_94_230","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「周書洪範之言。羞，進也。皇，大也。極，中也。」","sentenceOrder":230},
  {"id":"s_work_han_thu_94_231","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「如，若也。」","sentenceOrder":231},
  {"id":"s_work_han_thu_94_232","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　孟康曰：「朓，行疾也。側匿，行遲也。」師古曰：「朓音吐了反。」","sentenceOrder":232},
  {"id":"s_work_han_thu_94_233","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「沴，惡氣也，音戾。」","sentenceOrder":233},
  {"id":"s_work_han_thu_94_234","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　師古曰：「歲之朝，月之朝，日之朝，故曰三朝。」","sentenceOrder":234},
  {"id":"s_work_han_thu_94_235","chapterId":"ch_work_han_thu_94","textTraditional":"〔六〕　師古曰：「商書高宗肜日之辭也。假，至也。言先代至道之王必正其事。」","sentenceOrder":235},
  {"id":"s_work_han_thu_94_236","chapterId":"ch_work_han_thu_94","textTraditional":"〔七〕　師古曰：「（右）〔左〕讀曰（佑）〔佐〕。（佑）〔佐〕，助也。」","sentenceOrder":236},
  {"id":"s_work_han_thu_94_237","chapterId":"ch_work_han_thu_94","textTraditional":"〔八〕　師古曰：「言輕忽天戒，簡傲欺誣者，其罰必至。」","sentenceOrder":237},
  {"id":"s_work_han_thu_94_238","chapterId":"ch_work_han_thu_94","textTraditional":"〔九〕　師古曰：「周頌敬之篇。顯，明也。思，辭也。言天甚明察，宜敬之，以承受天命甚難。」","sentenceOrder":238},
  {"id":"s_work_han_thu_94_239","chapterId":"ch_work_han_thu_94","textTraditional":"〔一０〕師古曰：「周頌我將之詩。言必敬天之威，於是乃得安。」","sentenceOrder":239},
  {"id":"s_work_han_thu_94_240","chapterId":"ch_work_han_thu_94","textTraditional":"〔一一〕師古曰：「兢兢，戒也。業業，危也。」","sentenceOrder":240},
  {"id":"s_work_han_thu_94_241","chapterId":"ch_work_han_thu_94","textTraditional":"〔一二〕師古曰：「援，引也。斷斷，專壹之貌。介謂一介之人。援音爰。」","sentenceOrder":241},
  {"id":"s_work_han_thu_94_242","chapterId":"ch_work_han_thu_94","textTraditional":"〔一三〕師古曰：「商書高宗肜日之辭。言既受天命，宜正其德。」","sentenceOrder":242},
  {"id":"s_work_han_thu_94_243","chapterId":"ch_work_han_thu_94","textTraditional":"〔一四〕師古曰：「周書大誥之辭。棐，輔也。諶，誠也。諶辭，至誠之辭也。棐音匪。諶音上林反。」","sentenceOrder":243},
  {"id":"s_work_han_thu_94_244","chapterId":"ch_work_han_thu_94","textTraditional":"〔一五〕師古曰：「孳孳，不怠也。孳音茲。」","sentenceOrder":244},
  {"id":"s_work_han_thu_94_245","chapterId":"ch_work_han_thu_94","textTraditional":"〔一六〕師古曰：「祈，求福也。禳，除禍也。」","sentenceOrder":245},
  {"id":"s_work_han_thu_94_246","chapterId":"ch_work_han_thu_94","textTraditional":"〔一七〕師古曰：「較，明貌也，音角。」","sentenceOrder":246},
  {"id":"s_work_han_thu_94_247","chapterId":"ch_work_han_thu_94","textTraditional":"書奏，上說，〔一〕賜光束帛，拜為光祿大夫，秩中二千石，給事中，位次丞相。詔光舉可尚書令者封上，光謝曰：「臣以朽材，前比歷位典大職，卒無尺寸之效，〔二〕幸免罪誅，全保首領，今復拔擢，備內朝臣，與聞政事。〔三〕臣光智謀淺短，犬馬齒臷，〔四〕誠恐一旦顛仆，無以報稱。〔五〕竊見國家故事，尚書以久次轉遷，非有踔絕之能，不相踰越。〔六〕尚書僕射敞，公正勤職，通敏於事，可尚書令。謹封上。」敞以舉故，為東平太守。敞姓成公，東海人也。","sentenceOrder":247},
  {"id":"s_work_han_thu_94_248","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":248},
  {"id":"s_work_han_thu_94_249","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「卒，終也。」","sentenceOrder":249},
  {"id":"s_work_han_thu_94_250","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「與讀曰豫。」","sentenceOrder":250},
  {"id":"s_work_han_thu_94_251","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「臷，老也，讀與耋同。今書本有作截字者，俗寫誤也。」","sentenceOrder":251},
  {"id":"s_work_han_thu_94_252","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　師古曰：「稱，副也。」","sentenceOrder":252},
  {"id":"s_work_han_thu_94_253","chapterId":"ch_work_han_thu_94","textTraditional":"〔六〕　師古曰：「踔，高遠也，音竹角反。」","sentenceOrder":253},
  {"id":"s_work_han_thu_94_254","chapterId":"ch_work_han_thu_94","textTraditional":"光為大夫月餘，丞相嘉下獄死，〔一〕御史大夫賈延免。光復為御史大夫，二月（復）〔為〕丞相，復故國博山侯。上乃知光前免非其罪，以過近臣毀短光者，復免傅嘉，曰：「前為侍中，毀譖仁賢，誣愬大臣，令俊艾者久失其位。〔二〕嘉傾覆巧偽，挾姦以罔上，崇黨以蔽朝，傷善以肆意。〔三〕詩不云乎？『讒人罔極，交亂四國。』〔四〕其免嘉為庶人，歸故郡。」","sentenceOrder":254},
  {"id":"s_work_han_thu_94_255","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「王嘉也。」","sentenceOrder":255},
  {"id":"s_work_han_thu_94_256","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「艾讀曰乂。」","sentenceOrder":256},
  {"id":"s_work_han_thu_94_257","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「肆，極也。」","sentenceOrder":257},
  {"id":"s_work_han_thu_94_258","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「小雅青蠅之詩，解在車千秋傳。」","sentenceOrder":258},
  {"id":"s_work_han_thu_94_259","chapterId":"ch_work_han_thu_94","textTraditional":"明年，定三公官，光更為大司徒。會哀帝崩，太皇太后以新都侯王莽為大司馬，徵立中山王、是為平帝。帝年幼，太后稱制，委政於莽。初，哀帝罷黜王氏，故太后與莽怨丁、傅、董賢之黨。莽以光為舊相名儒，天下所信，太后敬之，備禮事光。所欲搏擊，輒為草，以太后指風光令上之，〔一〕厓眥莫不誅傷。〔二〕莽權日盛，光憂懼不知所出，上書乞骸骨。莽白太后：「帝幼少，宜置師傅。」徙光為帝太傅，位四輔，給事中，領宿衛供養，行內〔三〕署門戶，省服御食物。〔四〕明年，徙為太師，而莽為太傅。光常稱疾，不敢與莽並。有詔朝朔望，領城門兵。莽又風群臣奏莽功德，稱宰衡，位在諸侯王上，百官統焉。光愈恐，固稱疾辭位。太后詔曰：「太師光，聖人之後，先師之子，德行純淑，道術通明，居四輔職，輔道于帝。〔五〕今年耆有疾，俊艾大臣，惟國之重，其猶不可以闕焉。〔六〕書曰『無遺耇老』，〔七〕國之將興，尊師而重傅。其令太師毋朝，十日一賜餐。賜太師靈壽杖，〔八〕黃門令為太師省中坐置几，太師入省中用杖，賜餐十七物，〔九〕然後歸老于第，官屬按職如故。」〔一０〕","sentenceOrder":259},
  {"id":"s_work_han_thu_94_260","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「謂文書之槁草也。風讀曰諷。次下亦同。」","sentenceOrder":260},
  {"id":"s_work_han_thu_94_261","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「厓音崖。眥音漬。厓又音五懈反。眥又音仕懈反。解具在杜欽傳。」","sentenceOrder":261},
  {"id":"s_work_han_thu_94_262","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「行內，行在所之內中，猶言禁中也。」","sentenceOrder":262},
  {"id":"s_work_han_thu_94_263","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　師古曰：「省，視也。」","sentenceOrder":263},
  {"id":"s_work_han_thu_94_264","chapterId":"ch_work_han_thu_94","textTraditional":"〔五〕　師古曰：「道讀曰導。」","sentenceOrder":264},
  {"id":"s_work_han_thu_94_265","chapterId":"ch_work_han_thu_94","textTraditional":"〔六〕　師古曰：「艾讀曰乂。」","sentenceOrder":265},
  {"id":"s_work_han_thu_94_266","chapterId":"ch_work_han_thu_94","textTraditional":"〔七〕　師古曰：「周書召誥之辭也。言不遺老成之人也。」","sentenceOrder":266},
  {"id":"s_work_han_thu_94_267","chapterId":"ch_work_han_thu_94","textTraditional":"〔八〕　孟康曰：「扶老杖也。」服虔曰：「靈壽，木名。」師古曰：「木似竹，有枝節，長不過八九尺，圍三四寸，自然有合杖制，不須削治也。」","sentenceOrder":267},
  {"id":"s_work_han_thu_94_268","chapterId":"ch_work_han_thu_94","textTraditional":"〔九〕　師古曰：「食具有十七種物。」","sentenceOrder":268},
  {"id":"s_work_han_thu_94_269","chapterId":"ch_work_han_thu_94","textTraditional":"〔一０〕師古曰：「言十日一入朝，受此寵禮。它日則常在家自養，而其屬官依常各行職務。」","sentenceOrder":269},
  {"id":"s_work_han_thu_94_270","chapterId":"ch_work_han_thu_94","textTraditional":"光凡為御史大夫、丞相各再，壹為大司徒、太傅、太師，歷三世，居公輔位前後十七年。自為尚書，止不教授，後為卿，時會門下大生講問疑難，舉大義云。其弟子多成就為博士大夫者，見師居大位，幾得其助力，〔一〕光終無所薦舉，至或怨之。其公如此。","sentenceOrder":270},
  {"id":"s_work_han_thu_94_271","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「幾讀曰冀。」","sentenceOrder":271},
  {"id":"s_work_han_thu_94_272","chapterId":"ch_work_han_thu_94","textTraditional":"光年七十，元始五年薨。莽白太后，使九卿策贈以太師博山侯印綬，賜乘輿祕器，金錢雜帛。少府供張，諫大夫持節與謁者二人使護喪事，博士護行禮。太后亦遣中謁者持節視喪。公卿百官會弔送葬。載以乘輿轀輬及副各一乘，〔一〕羽林孤兒諸生合四百人輓送，車萬餘兩，道路皆舉音以過喪。〔二〕將作穿復土，可甲卒五百人，起墳如大將軍王鳳制度。諡曰簡烈侯。","sentenceOrder":272},
  {"id":"s_work_han_thu_94_273","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「轀輬車及副各一乘也。轀輬，解具在霍光傳。」","sentenceOrder":273},
  {"id":"s_work_han_thu_94_274","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「喪到之處，行道之人皆舉音哭，須過乃止。」","sentenceOrder":274},
  {"id":"s_work_han_thu_94_275","chapterId":"ch_work_han_thu_94","textTraditional":"初，光以丞相封，後益封，凡食邑萬一千戶。病甚，上書讓還七千戶，及還所賜一弟。","sentenceOrder":275},
  {"id":"s_work_han_thu_94_276","chapterId":"ch_work_han_thu_94","textTraditional":"子放嗣。莽篡位後，以光兄子永為大司馬，封侯。昆弟子至卿大夫四五人。始光父霸以初元元年為關內侯食邑。霸上書求奉孔子祭祀，元帝下詔曰：「其令師褒成君關內侯霸以所食邑八百戶祀孔子焉。」故霸還長子福名數於魯，奉夫子祀。霸薨，子福嗣。福薨，子房嗣。房薨，子莽嗣。元始元年，封周公、孔子後為列侯，食邑各二千戶。莽更封為褒成侯，後避王莽，更名均。","sentenceOrder":276},
  {"id":"s_work_han_thu_94_277","chapterId":"ch_work_han_thu_94","textTraditional":"馬宮字游卿，東海戚人也。治春秋嚴氏，以射策甲科為郎，遷楚長史，免官。後為丞相史司直。師丹薦宮行能高絜，遷廷尉平，青州刺史，汝南、九江太守，所在見稱。徵為詹事，光祿勳，右將軍，代孔光為大司徒，封扶德侯。光為太師薨，宮復代光為太師，兼司徒官。","sentenceOrder":277},
  {"id":"s_work_han_thu_94_278","chapterId":"ch_work_han_thu_94","textTraditional":"初，宮哀帝時與丞相御史雜議帝祖母傅太后諡，及元始中，王莽發傅太后陵徙歸定陶，以民葬之，追誅前議者。宮為莽所厚，獨不及，內慚懼，上書謝罪乞骸骨。莽以太皇太后詔賜宮策曰：「太師大司徒扶德侯上書言『前以光祿勳議故定陶共王母諡，曰「婦人以夫爵尊為號，諡宜曰孝元傅皇后，稱渭陵東園。」臣知妾不得體君，卑不得敵尊，而希指雷同，詭經辟說，〔一〕以惑誤上。為臣不忠，當伏斧鉞之誅，幸蒙洒心自新，〔二〕又令得保首領。伏自惟念，入稱四輔，出備三公，爵為列侯，誠無顏復望闕廷，無心復居官府，無宜復食國邑。願上太師大司徒扶德侯印綬，避賢者路。』下君章有司，皆以為四輔之職為國維綱，三公之任鼎足承君，不有鮮明固守，無以居位。如君言至誠可聽，惟君之惡在洒心前，不敢文過，朕甚多之，〔三〕不奪君之爵邑，以著『自古皆有死』之義。〔四〕其上太師大司徒印綬使者，以侯就弟。」王莽篡位，以宮為太子師，卒官。","sentenceOrder":278},
  {"id":"s_work_han_thu_94_279","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　師古曰：「詭，違。辟讀曰僻。」","sentenceOrder":279},
  {"id":"s_work_han_thu_94_280","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「洒音先禮反。」","sentenceOrder":280},
  {"id":"s_work_han_thu_94_281","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　師古曰：「多猶重也。」","sentenceOrder":281},
  {"id":"s_work_han_thu_94_282","chapterId":"ch_work_han_thu_94","textTraditional":"〔四〕　孟康曰：「以宮上書不文過為信，不奪其爵邑。」師古曰：「論語載孔子言曰：『自古皆有死，民無信不立』，故引之。」","sentenceOrder":282},
  {"id":"s_work_han_thu_94_283","chapterId":"ch_work_han_thu_94","textTraditional":"本姓馬矢，宮仕學，稱馬氏云。","sentenceOrder":283},
  {"id":"s_work_han_thu_94_284","chapterId":"ch_work_han_thu_94","textTraditional":"贊曰：自孝武興學，公孫弘以儒相，其後蔡義、韋賢、玄成、匡衡、張禹、翟方進、孔光、平當、馬宮及當子晏咸以儒宗居宰相位，服儒衣冠，〔一〕傳先王語，其醞藉可也，〔二〕然皆持祿保位，被阿諛之譏。彼以古人之跡見繩，烏能勝其任乎！〔三〕","sentenceOrder":284},
  {"id":"s_work_han_thu_94_285","chapterId":"ch_work_han_thu_94","textTraditional":"〔一〕　孟康曰：「方領逢掖之衣。」","sentenceOrder":285},
  {"id":"s_work_han_thu_94_286","chapterId":"ch_work_han_thu_94","textTraditional":"〔二〕　師古曰：「醞藉，謂如醞釀及薦藉，道其寬博重厚也。醞音於問反。藉音才夜反。」","sentenceOrder":286},
  {"id":"s_work_han_thu_94_287","chapterId":"ch_work_han_thu_94","textTraditional":"〔三〕　如淳曰：「跡謂既明且哲也。繩謂抨彈之也。」師古曰：「古人之跡，謂直道以事人也。烏，何也。抨音普耕反。」","sentenceOrder":287},
  {"id":"s_work_han_thu_94_288","chapterId":"ch_work_han_thu_94","textTraditional":"校勘記","sentenceOrder":288},
  {"id":"s_work_han_thu_94_289","chapterId":"ch_work_han_thu_94","textTraditional":"三三三二頁一０行　人情（以）〔忽〕不自知，　景祐、殿、局本都作「忽」。王先謙說作「忽」是。","sentenceOrder":289},
  {"id":"s_work_han_thu_94_290","chapterId":"ch_work_han_thu_94","textTraditional":"三三三三頁一二行　臣聞五帝不同（樂）〔禮〕，　景祐、殿本都作「禮」。","sentenceOrder":290},
  {"id":"s_work_han_thu_94_291","chapterId":"ch_work_han_thu_94","textTraditional":"三三四０頁　五行　（之道）〔道之〕衰莫不始乎梱內。　錢大昭說「之道」二字當乙。按殿、局本作「道之」，景祐本亦作「之道」。","sentenceOrder":291},
  {"id":"s_work_han_thu_94_292","chapterId":"ch_work_han_thu_94","textTraditional":"三三四一頁　六行　易家人卦之（象也）〔彖辭〕。　景祐、殿本都作「彖辭」。","sentenceOrder":292},
  {"id":"s_work_han_thu_94_293","chapterId":"ch_work_han_thu_94","textTraditional":"三三四六頁　三行　積十餘歲，衡封臨淮郡，〔四〕　注〔四〕原在「衡封」下。楊樹達說敦煌殘卷子本漢書此注在「臨淮郡」下，「衡封臨淮郡」五字屬讀。","sentenceOrder":293},
  {"id":"s_work_han_thu_94_294","chapterId":"ch_work_han_thu_94","textTraditional":"三三四六頁　八行　不（足）〔從〕故而以閩佰為界，解何？　殘卷本作「從」。","sentenceOrder":294},
  {"id":"s_work_han_thu_94_295","chapterId":"ch_work_han_thu_94","textTraditional":"三三四七頁　二行　〔晉灼曰：「舉郡而言耳，自封縣也。」〕　殘卷本多此十二字。","sentenceOrder":295},
  {"id":"s_work_han_thu_94_296","chapterId":"ch_work_han_thu_94","textTraditional":"三三四七頁　四行　令郡（故）〔改〕從平陵佰以為定實。　景祐、殿本都作「改」。","sentenceOrder":296},
  {"id":"s_work_han_thu_94_297","chapterId":"ch_work_han_thu_94","textTraditional":"三三四七頁一０行　至禹父徙家蓮（白）〔勺〕。　景祐、殿、局本都作「勺」，此誤。","sentenceOrder":297},
  {"id":"s_work_han_thu_94_298","chapterId":"ch_work_han_thu_94","textTraditional":"三三五０頁一０行　禹頓首謝恩，〔因〕歸誠，　宋祁說「恩」字下當有「因」字。王念孫說宋說是。殘卷本有「因」字。","sentenceOrder":298},
  {"id":"s_work_han_thu_94_299","chapterId":"ch_work_han_thu_94","textTraditional":"三三五一頁　五行　地震五（十六），　宋祁、劉敞都說「十六」兩字疑衍。　按景祐本無「十六」兩字。","sentenceOrder":299},
  {"id":"s_work_han_thu_94_300","chapterId":"ch_work_han_thu_94","textTraditional":"三三五一頁一六行　露（筮）易蓍於星宿下，　殿本無「蓍」字。","sentenceOrder":300},
  {"id":"s_work_han_thu_94_301","chapterId":"ch_work_han_thu_94","textTraditional":"三三五三頁一一行　高（第）為尚書，　景祐、殿本都無「第」字。","sentenceOrder":301},
  {"id":"s_work_han_thu_94_302","chapterId":"ch_work_han_thu_94","textTraditional":"三三五四頁一０行　（師古）〔服虔〕曰：「言已繕（事）書，　景祐、殿本都作「服虔」，無「事」字。","sentenceOrder":302},
  {"id":"s_work_han_thu_94_303","chapterId":"ch_work_han_thu_94","textTraditional":"三三五六頁　一行　此（其）〔具〕引令條之文也。　景祐、殿本都作「具」。","sentenceOrder":303},
  {"id":"s_work_han_thu_94_304","chapterId":"ch_work_han_thu_94","textTraditional":"三三五六頁一五行　使上不得直道（而）行。　景祐、殿本都無「而」字。","sentenceOrder":304},
  {"id":"s_work_han_thu_94_305","chapterId":"ch_work_han_thu_94","textTraditional":"三三五九頁一四行　天（右）〔左〕與王者，　景祐本作「左」，注同。王念孫說作「左」是。","sentenceOrder":305},
  {"id":"s_work_han_thu_94_306","chapterId":"ch_work_han_thu_94","textTraditional":"三三六二頁　四行　二月（復）〔為〕丞相，　景祐、殿、局本都作「為」。王先謙說作「為」是。","sentenceOrder":306},
  {"id":"s_work_han_thu_95_1","chapterId":"ch_work_han_thu_95","textTraditional":"王商字子威，涿郡蠡吾人也，〔一〕徙杜陵。商父武，武兄無故，皆以宣帝舅封。無故為平昌侯，武為樂昌侯。語在外戚傳。","sentenceOrder":1},
  {"id":"s_work_han_thu_95_2","chapterId":"ch_work_han_thu_95","textTraditional":"〔一〕　師古曰：「蠡音禮。」","sentenceOrder":2},
  {"id":"s_work_han_thu_95_3","chapterId":"ch_work_han_thu_95","textTraditional":"商少為太子中庶子，以肅敬敦厚稱。父薨，商嗣為侯，推財以分異母諸弟，身無所受，居喪哀慽。於是大臣薦商行可以厲群臣，義足以厚風俗，宜備近臣。繇是擢為諸曹侍中中郎將。〔一〕元帝時，至右將軍、光祿大夫。是時，定陶共王愛幸，幾代太子。〔二〕商為外戚重臣輔政，擁佑太子，頗有力焉。〔三〕","sentenceOrder":3},
  {"id":"s_work_han_thu_95_4","chapterId":"ch_work_han_thu_95","textTraditional":"〔一〕　師古曰：「繇讀與由同。」","sentenceOrder":4},
  {"id":"s_work_han_thu_95_5","chapterId":"ch_work_han_thu_95","textTraditional":"〔二〕　師古曰：「共讀曰恭。幾音鉅依反。」","sentenceOrder":5},
  {"id":"s_work_han_thu_95_6","chapterId":"ch_work_han_thu_95","textTraditional":"〔三〕　師古曰：「佑，助也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_95_7","chapterId":"ch_work_han_thu_95","textTraditional":"元帝崩，成帝即位，甚敬重商，徙為左將軍。而帝元舅大司馬大將軍王鳳顓權，行多驕僭。商論議不能平鳳，鳳知之，亦疏商。建始三年秋，京師民無故相驚，言大水至，百姓奔走相蹂躪，〔一〕〔老弱號呼〕，〔二〕長安中大亂。天子親御前殿，召公卿議。大將軍鳳以為太后與上及後宮可御船，令吏民上長安城以避水。群臣皆從鳳議。左將軍商獨曰：「自古無道之國，水猶不冒城郭。〔三〕今政治和平，世無兵革，上下相安，何因當有大水一日暴至？此必訛言也〔四〕，不宜令上城，重驚百姓。」〔五〕上乃止。有頃，長安中稍定，問之，果訛言。上於是美壯商之固守，數稱其議。而鳳大慚，自恨失言。","sentenceOrder":7},
  {"id":"s_work_han_thu_95_8","chapterId":"ch_work_han_thu_95","textTraditional":"〔一〕　師古曰：「蹂，踐也。躪，轢也。蹂音人九反。躪音藺。」","sentenceOrder":8},
  {"id":"s_work_han_thu_95_9","chapterId":"ch_work_han_thu_95","textTraditional":"〔二〕　〔師古曰：「呼音火故反。」〕","sentenceOrder":9},
  {"id":"s_work_han_thu_95_10","chapterId":"ch_work_han_thu_95","textTraditional":"〔三〕　師古曰：「冒，蒙覆也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_95_11","chapterId":"ch_work_han_thu_95","textTraditional":"〔四〕　師古曰：「訛，偽也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_95_12","chapterId":"ch_work_han_thu_95","textTraditional":"〔五〕　師古曰：「重音直用反。」","sentenceOrder":12},
  {"id":"s_work_han_thu_95_13","chapterId":"ch_work_han_thu_95","textTraditional":"明年，商代匡衡為丞相，益封千戶，天子甚尊任之。為人多質有威重，〔一〕長八尺餘，身體鴻大，容貌甚過絕人。河平四年，單于來朝，引見白虎殿。〔二〕丞相商坐未央廷中，單于前，拜謁商〔三〕。商起，離席與言，單于仰視商貌，大畏之，遷延卻退。天子聞而歎曰：「此真漢相矣！」","sentenceOrder":13},
  {"id":"s_work_han_thu_95_14","chapterId":"ch_work_han_thu_95","textTraditional":"〔一〕　師古曰：「多質，言不為文飾。」","sentenceOrder":14},
  {"id":"s_work_han_thu_95_15","chapterId":"ch_work_han_thu_95","textTraditional":"〔二〕　師古曰：「在未央宮中。」","sentenceOrder":15},
  {"id":"s_work_han_thu_95_16","chapterId":"ch_work_han_thu_95","textTraditional":"〔三〕　師古曰：「單于將見天子，而經未央廷中過也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_95_17","chapterId":"ch_work_han_thu_95","textTraditional":"初，大將軍鳳連昏楊肜為琅邪太守，〔一〕其郡有災害十四，已上。商部屬按問，〔二〕鳳以曉商〔三〕曰：「災異天事，非人力所為。肜素善吏，宜以為後。」〔四〕商不聽，竟奏免肜，奏果寑不下，鳳重以是怨商，〔五〕陰求其短，使人上書言商閨門內事。天子以為暗昧之過，不足以傷大臣，鳳固爭，下其事司隸。","sentenceOrder":17},
  {"id":"s_work_han_thu_95_18","chapterId":"ch_work_han_thu_95","textTraditional":"〔一〕　如淳曰：「連昏者，婚家之婚親也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_95_19","chapterId":"ch_work_han_thu_95","textTraditional":"〔二〕　如淳曰：「部屬猶差次。差次其屬令治之。」","sentenceOrder":19},
  {"id":"s_work_han_thu_95_20","chapterId":"ch_work_han_thu_95","textTraditional":"〔三〕　師古曰：「告語也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_95_21","chapterId":"ch_work_han_thu_95","textTraditional":"〔四〕　師古曰：「且勿按問也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_95_22","chapterId":"ch_work_han_thu_95","textTraditional":"〔五〕　師古曰：「重音直用反。」","sentenceOrder":22},
  {"id":"s_work_han_thu_95_23","chapterId":"ch_work_han_thu_95","textTraditional":"先是皇太后嘗詔問商女，欲以備後宮。時女病，商意亦難之，以病對，不入。及商以閨門事見考，自知為鳳所中，〔一〕惶怖，更欲內女為援，乃因新幸李婕妤家白見其女。","sentenceOrder":23},
  {"id":"s_work_han_thu_95_24","chapterId":"ch_work_han_thu_95","textTraditional":"〔一〕　師古曰：「中，傷也，音竹仲反。」","sentenceOrder":24},
  {"id":"s_work_han_thu_95_25","chapterId":"ch_work_han_thu_95","textTraditional":"會日有蝕之，太中大夫蜀郡張匡，其人佞巧，上書願對近臣陳日蝕咎。下朝者〔一〕左將軍丹等問匡，〔二〕對曰：「竊見丞相商作威作福，從外制中，取必於上，〔三〕性殘賊不仁，遣票輕吏微求人罪，〔四〕欲以立威，天下患苦之。前頻陽耿定上書言商與父傅通，及女弟淫亂，〔五〕奴殺其私夫，疑商教使。〔六〕章下有司，商私怨懟。〔七〕商子俊欲上書告商，俊妻左將軍丹女，持其書以示丹，丹惡其父子乖迕，〔八〕為女求去。商不盡忠納善以輔至德，知聖主崇孝，遠別不親，〔九〕後庭之事皆受命皇太后，太后前聞商有女，欲以備後宮，商言有固疾，後有耿定事，更詭道因李貴人家內女〔一０〕。執左道以亂政，〔一一〕誣罔誖大臣節，〔一二〕故應是而日蝕。周書曰：『以左道事君者誅。』〔一三〕易曰：『日中見昧，則折其右肱。』〔一四〕往者丞相周勃再建大功，及孝文時纖介怨恨，而日為之蝕，於是退勃使就國，卒無怵悐憂。〔一五〕今商無尺寸之功，而有三世之寵，〔一六〕身位三公，宗族為列侯、吏二千石、侍中諸曹，給事禁門內，連昏諸侯王，權寵至盛。審有內亂殺人怨懟之端，宜窮（意）〔竟〕考問。臣聞秦丞相呂不韋見王無子，意欲有秦國，即求好女以為妻，陰知其有身而獻之王，產始皇帝。及楚相春申君亦見王無子，心利楚國，即獻有身妻而產懷王。自漢興幾遭呂、霍之患，〔一七〕今商有不仁之性，乃因怨以內女，其姦謀未可測度。前孝景世七國反，將軍周亞夫以為即得雒陽劇孟，關東非漢之有。今商宗族權勢，合貲鉅萬計，私奴以千數，非特劇孟匹夫之徒也。且失道之至，親戚畔之，閨門內亂，父子相訐，〔一八〕而欲使之宣明聖化，調和海內，豈不謬哉！商視事五年，官職陵夷而大惡著於百姓，甚虧損盛德，有鼎折足之凶。〔一九〕臣愚以為聖主富於春秋，即位以來，未有懲姦之威，加以繼嗣未立，大異並見，尤宜誅討不忠，以遏未然。〔二０〕行之一人，則海內震動，百姦之路塞矣。」","sentenceOrder":25},
  {"id":"s_work_han_thu_95_26","chapterId":"ch_work_han_thu_95","textTraditional":"〔一〕　文穎曰：「令下朝者平之也。」孟康曰：「中朝臣也。」師古曰：「文說是也。下音胡稼反。」","sentenceOrder":26},
  {"id":"s_work_han_thu_95_27","chapterId":"ch_work_han_thu_95","textTraditional":"〔二〕　師古曰：「史丹也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_95_28","chapterId":"ch_work_han_thu_95","textTraditional":"〔三〕　師古曰：「意欲所行，必果之。」","sentenceOrder":28},
  {"id":"s_work_han_thu_95_29","chapterId":"ch_work_han_thu_95","textTraditional":"〔四〕　師古曰：「票，疾也。微謂私求之也。票音頻妙反，又音匹妙反。」","sentenceOrder":29},
  {"id":"s_work_han_thu_95_30","chapterId":"ch_work_han_thu_95","textTraditional":"〔五〕　師古曰：「傅謂傅婢也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_95_31","chapterId":"ch_work_han_thu_95","textTraditional":"〔六〕　師古曰：「私夫，女弟之私與姦通者。」","sentenceOrder":31},
  {"id":"s_work_han_thu_95_32","chapterId":"ch_work_han_thu_95","textTraditional":"〔七〕　師古曰：「懟音直類反。」","sentenceOrder":32},
  {"id":"s_work_han_thu_95_33","chapterId":"ch_work_han_thu_95","textTraditional":"〔八〕　師古曰：「迕，逆也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_95_34","chapterId":"ch_work_han_thu_95","textTraditional":"〔九〕　師古曰：「遠離女色而分別之，故云不親也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_95_35","chapterId":"ch_work_han_thu_95","textTraditional":"〔一０〕師古曰：「詭，違也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_95_36","chapterId":"ch_work_han_thu_95","textTraditional":"〔一一〕師古曰：「左道，僻左之道，謂不正。」","sentenceOrder":36},
  {"id":"s_work_han_thu_95_37","chapterId":"ch_work_han_thu_95","textTraditional":"〔一二〕師古曰：「誖，乖也，音布內反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_95_38","chapterId":"ch_work_han_thu_95","textTraditional":"〔一三〕師古曰：「逸書也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_95_39","chapterId":"ch_work_han_thu_95","textTraditional":"〔一四〕蘇林曰：「日者君之象，中者明之盛，盛而昧，折去右肱之臣，用無咎也。」師古曰：「此豐卦九三爻辭。」","sentenceOrder":39},
  {"id":"s_work_han_thu_95_40","chapterId":"ch_work_han_thu_95","textTraditional":"〔一五〕師古曰：「卒，終也。悐，古惕字。」","sentenceOrder":40},
  {"id":"s_work_han_thu_95_41","chapterId":"ch_work_han_thu_95","textTraditional":"〔一六〕師古曰：「自宣帝至成帝凡三主。」","sentenceOrder":41},
  {"id":"s_work_han_thu_95_42","chapterId":"ch_work_han_thu_95","textTraditional":"〔一七〕師古曰：「幾音鉅依反。」","sentenceOrder":42},
  {"id":"s_work_han_thu_95_43","chapterId":"ch_work_han_thu_95","textTraditional":"〔一八〕師古曰：「訐，告斥其罪也，音居謁反。」","sentenceOrder":43},
  {"id":"s_work_han_thu_95_44","chapterId":"ch_work_han_thu_95","textTraditional":"〔一九〕師古曰：「易鼎卦九四爻辭曰：『鼎折足，覆公餗，其形渥，凶。』餗，鼎實也，謂所亨之物也。渥，厚也。言鼎折其足，則覆喪其實，喻大臣非其任，則虧敗國典，故宜加以厚刑。」","sentenceOrder":44},
  {"id":"s_work_han_thu_95_45","chapterId":"ch_work_han_thu_95","textTraditional":"〔二０〕師古曰：「遏，止也。未然，謂未有其事，恐將然也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_95_46","chapterId":"ch_work_han_thu_95","textTraditional":"於是左將軍丹等奏：「商位三公，爵列侯，親受詔策為天下師，不遵法度以翼國家，〔一〕而回辟下媚以進其私，〔二〕執左道以亂政，為臣不忠，罔上不道，甫刑之辟，皆為上戮，罪名明白。臣請詔謁者召商詣若盧詔獄。」〔三〕上素重商，知匡言多險，制曰「弗治」。鳳固爭之，於是制詔御史：「蓋丞相以德輔翼國家，典領百寮，協和萬國，為職任莫重焉。今樂昌侯商為丞相，出入五年，未聞忠言嘉謀，而有不忠執左道之辜，陷于大辟。前商女弟內行不修，奴賊殺人，疑商教使，為商重臣，故抑而不窮。今或言商不以自悔而反怨懟，朕甚傷之。惟商與先帝有外親，未忍致于理。其赦商罪。使者收丞相印綬。」","sentenceOrder":46},
  {"id":"s_work_han_thu_95_47","chapterId":"ch_work_han_thu_95","textTraditional":"〔一〕　師古曰：「翼，助也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_95_48","chapterId":"ch_work_han_thu_95","textTraditional":"〔二〕　師古曰：「回，邪也。辟讀曰僻。」","sentenceOrder":48},
  {"id":"s_work_han_thu_95_49","chapterId":"ch_work_han_thu_95","textTraditional":"〔三〕　孟康曰：「若盧，獄名，屬少府，黃門內寺是也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_95_50","chapterId":"ch_work_han_thu_95","textTraditional":"商免相三日，發病〈區夂〉血薨，諡曰戾侯。而商子弟親屬為駙馬都尉、侍中、中常侍、諸曹大夫郎吏者，皆出補吏，莫得留給事宿衛者。有司奏商罪過未決，請除國邑。有詔長子安嗣爵為樂昌侯，至長樂衛尉、光祿勳。","sentenceOrder":50},
  {"id":"s_work_han_thu_95_51","chapterId":"ch_work_han_thu_95","textTraditional":"商死後，連年日蝕地震，直臣京兆尹王章上封事召見，訟商忠直無罪，言鳳顓權蔽主。鳳竟以法誅章，語在元后傳。至元始中，王莽為安漢公，誅不附己者，樂昌侯安見被以罪，自殺，國除。〔一〕","sentenceOrder":51},
  {"id":"s_work_han_thu_95_52","chapterId":"ch_work_han_thu_95","textTraditional":"〔一〕　師古曰：「被，加也，音皮義反。」","sentenceOrder":52},
  {"id":"s_work_han_thu_95_53","chapterId":"ch_work_han_thu_95","textTraditional":"史丹字君仲，魯國人也，徙杜陵。祖父恭有女弟，武帝時為衛太子良娣，產悼皇考。皇考者，孝宣帝父也。宣帝微時依倚史氏。〔一〕語在史良娣傳。及宣帝即尊位，恭已死，三子，高、曾、玄。曾、玄皆以外屬舊恩封，曾為將陵侯，玄平臺侯。高侍中貴幸，以發舉反者大司馬霍禹功封樂陵侯。宣帝疾病，拜高為大司馬車騎將軍，領尚書事。帝崩，太子襲尊號，是為孝元帝。高輔政五年，乞骸骨，賜安車駟馬黃金，罷就第。薨，諡曰安侯。","sentenceOrder":53},
  {"id":"s_work_han_thu_95_54","chapterId":"ch_work_han_thu_95","textTraditional":"〔一〕　師古曰：「倚音於綺反。」","sentenceOrder":54},
  {"id":"s_work_han_thu_95_55","chapterId":"ch_work_han_thu_95","textTraditional":"自元帝為太子時，丹以父高任為中庶子，侍從十餘年。元帝即位，為駙馬都尉侍中，出常驂乘，甚有寵。上以丹舊臣，皇考外屬，親信之，詔丹護太子家。是時，傅昭儀子定陶共王有材藝，子母俱愛幸，而太子頗有酒色之失，母王皇后無寵。","sentenceOrder":55},
  {"id":"s_work_han_thu_95_56","chapterId":"ch_work_han_thu_95","textTraditional":"建昭之間，元帝被疾，不親政事，留好音樂。〔一〕或置鼙鼓殿下，〔二〕天子自臨軒檻上，隤銅丸以擿鼓，〔三〕聲中嚴鼓之節。〔四〕後宮及左右習知音者莫能為，而定陶王亦能之，上數稱其材。丹進曰：「凡所謂材者，敏而好學，溫故知新，〔五〕皇太子是也。若乃器人於絲竹鼓鼙之間，則是陳惠、李微高於匡衡，可相國也。」〔六〕於是上嘿然而笑。〔七〕其後，中山哀王薨，太子前弔。哀王者，帝之少弟，與太子遊學相長大。〔八〕上望見太子，感念哀王，悲不能自止。太子既至前，不哀。上大恨曰：「安有人不慈仁而可奉宗廟為民父母者乎！」上以責謂丹。〔九〕丹免冠謝上曰：「臣誠見陛下哀痛中山王，至以感損。向者太子當進見，臣竊戒屬毋涕泣，感傷陛下。〔一０〕罪乃在臣，當死。」上以為然，意乃解。丹之輔相，皆此類也。","sentenceOrder":56},
  {"id":"s_work_han_thu_95_57","chapterId":"ch_work_han_thu_95","textTraditional":"〔一〕　孟康曰：「留意於音樂也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_95_58","chapterId":"ch_work_han_thu_95","textTraditional":"〔二〕　師古曰：「鼙本騎上之鼓，音步迷反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_95_59","chapterId":"ch_work_han_thu_95","textTraditional":"〔三〕　師古曰：「檻軒，闌版也。隤，下也。擿，投也。隤音頹。擿音持益反。一曰，擿，磓也，音丁歷反。磓音丁回反。」","sentenceOrder":59},
  {"id":"s_work_han_thu_95_60","chapterId":"ch_work_han_thu_95","textTraditional":"〔四〕　李奇曰：「莊嚴之鼓節也。」晉灼曰：「疾擊之鼓也。」師古曰：「李說是也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_95_61","chapterId":"ch_work_han_thu_95","textTraditional":"〔五〕　師古曰：「敏，速疾也。溫，厚也。溫故，厚蓄故事也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_95_62","chapterId":"ch_work_han_thu_95","textTraditional":"〔六〕　如淳曰：「器人，取人器能也。陳惠、李微是時好音者也。」服虔曰：「二人皆黃門鼓吹也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_95_63","chapterId":"ch_work_han_thu_95","textTraditional":"〔七〕　師古曰：「咲，古笑字。」","sentenceOrder":63},
  {"id":"s_work_han_thu_95_64","chapterId":"ch_work_han_thu_95","textTraditional":"〔八〕　師古曰：「同處（同）〔長〕養以至於壯大。」","sentenceOrder":64},
  {"id":"s_work_han_thu_95_65","chapterId":"ch_work_han_thu_95","textTraditional":"〔九〕　師古曰：「謂者，告語也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_95_66","chapterId":"ch_work_han_thu_95","textTraditional":"〔一０〕師古曰：「屬音之欲反。」","sentenceOrder":66},
  {"id":"s_work_han_thu_95_67","chapterId":"ch_work_han_thu_95","textTraditional":"竟寧元年，上寑疾，傅昭儀及定陶王常在左右，而皇后太子希得進見。上疾稍侵，意忽忽不平，〔一〕數問尚書以景帝時立膠東王故事。是時，太子長舅陽平侯王鳳為衛尉侍中，與皇后太子皆憂，不知所出。〔二〕丹以親密臣得侍視疾，候上間獨寢時，丹直入臥內，頓首伏青蒲上，〔三〕涕泣言曰：「皇太子以適長立，積十餘年，〔四〕名號繫於百姓，天下莫不歸心臣子。〔五〕見定陶王雅素愛幸，今者道路流言，為國生意，以為太子有動搖之議。審若此，公卿以下必以死爭，不奉詔。臣願先賜死以示群臣！」天子素仁，不忍見丹涕泣，言又切至，上意大感，喟然太息曰：「吾日困劣，而太子兩王幼少，意中戀戀，亦何不念乎！然無有此議。且皇后謹慎，先帝又愛太子，吾豈可違指！駙馬都尉安所受此語？」〔六〕丹即卻，頓首曰：「愚臣妄聞，罪當死！」〔七〕上因納，謂丹曰：「吾病寖加，恐不能自還。〔八〕善輔道太子，毋違我意！」〔九〕丹噓唏而起。〔一０〕太子由是遂為嗣矣。","sentenceOrder":67},
  {"id":"s_work_han_thu_95_68","chapterId":"ch_work_han_thu_95","textTraditional":"〔一〕　師古曰：「稍侵，言漸篤也。平，和也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_95_69","chapterId":"ch_work_han_thu_95","textTraditional":"〔二〕　師古曰：「不知計所出。」","sentenceOrder":69},
  {"id":"s_work_han_thu_95_70","chapterId":"ch_work_han_thu_95","textTraditional":"〔三〕　服虔曰：「青緣蒲席也。」應劭曰：「以青規地曰青蒲，自非皇后不得至此。」孟康曰：「以蒲青為席，用蔽地也。」師古曰：「應說是也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_95_71","chapterId":"ch_work_han_thu_95","textTraditional":"〔四〕　師古曰：「適讀曰嫡。」","sentenceOrder":71},
  {"id":"s_work_han_thu_95_72","chapterId":"ch_work_han_thu_95","textTraditional":"〔五〕　師古曰：「自託為臣子。」","sentenceOrder":72},
  {"id":"s_work_han_thu_95_73","chapterId":"ch_work_han_thu_95","textTraditional":"〔六〕　師古曰：「安，焉也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_95_74","chapterId":"ch_work_han_thu_95","textTraditional":"〔七〕　師古曰：「卻，退也，離青蒲上。」","sentenceOrder":74},
  {"id":"s_work_han_thu_95_75","chapterId":"ch_work_han_thu_95","textTraditional":"〔八〕　師古曰：「寖，漸也。不自還者，言當遂至崩亡也。還讀曰旋。」","sentenceOrder":75},
  {"id":"s_work_han_thu_95_76","chapterId":"ch_work_han_thu_95","textTraditional":"〔九〕　師古曰：「道讀曰導。」","sentenceOrder":76},
  {"id":"s_work_han_thu_95_77","chapterId":"ch_work_han_thu_95","textTraditional":"〔一０〕師古曰：「噓音虛。唏音許既反。」","sentenceOrder":77},
  {"id":"s_work_han_thu_95_78","chapterId":"ch_work_han_thu_95","textTraditional":"元帝竟崩，成帝初即位，擢丹為長樂衛尉，遷右將軍，賜爵關內侯，食邑三百戶，給事中，後徙左將軍、光祿大夫。鴻嘉元年，上遂下詔曰：「夫褒有德，賞元功，古今通義也。左將軍丹往時導朕以忠正，秉義醇壹，舊德茂焉。其封丹為武陽侯，國東海郯之武彊聚，戶千一百。」〔一〕","sentenceOrder":78},
  {"id":"s_work_han_thu_95_79","chapterId":"ch_work_han_thu_95","textTraditional":"〔一〕　如淳曰：「聚，字喻反。聚，邑居也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_95_80","chapterId":"ch_work_han_thu_95","textTraditional":"丹為人足知，愷弟愛人，〔一〕貌若儻蕩不備，〔二〕然心甚謹密，故尤得信於上。丹兄嗣父爵為侯，讓不受分。丹盡得父財，身又食大國邑，重以舊恩，數見褒賞，〔三〕賞賜累千金，僮奴以百數，後房妻妾數十人，內奢淫，好飲酒，極滋味聲色之樂。為將軍前後十六年，永始中病乞骸骨，上賜策曰：「左將軍寑病不衰，〔四〕願歸治疾，朕愍以官職之事久留將軍，使躬不瘳。使光祿勳賜將軍黃金五十斤，安車駟馬，其上將軍印綬。宜專精神，務近醫藥，以輔不衰。」","sentenceOrder":80},
  {"id":"s_work_han_thu_95_81","chapterId":"ch_work_han_thu_95","textTraditional":"〔一〕　師古曰：「愷，樂也。弟，易也。言有和樂簡易之德。」","sentenceOrder":81},
  {"id":"s_work_han_thu_95_82","chapterId":"ch_work_han_thu_95","textTraditional":"〔二〕　師古曰：「儻蕩，疏誕無檢也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_95_83","chapterId":"ch_work_han_thu_95","textTraditional":"〔三〕　師古曰：「重音直用反。」","sentenceOrder":83},
  {"id":"s_work_han_thu_95_84","chapterId":"ch_work_han_thu_95","textTraditional":"〔四〕　師古曰：「言病不損也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_95_85","chapterId":"ch_work_han_thu_95","textTraditional":"丹歸第數月薨，諡曰頃侯。有子男女二十人，九男皆以丹任並為侍中諸曹，親近在左右。史氏凡四人侯，至卿大夫二千石者十餘人，皆訖王莽乃絕，唯將陵侯曾無子，絕於身云。","sentenceOrder":85},
  {"id":"s_work_han_thu_95_86","chapterId":"ch_work_han_thu_95","textTraditional":"傅喜字稚游，河內溫人也，哀帝祖母定陶傅太后從父弟。少好學問，有志行。哀帝立為太子，成帝選喜為太子庶子。哀帝初即位，以喜為衛尉，遷右將軍。是時，王莽為大司馬，乞骸骨，避帝外家。上既聽莽退，眾庶歸望於喜。喜從弟孔鄉侯晏親與喜等，〔一〕而女為皇后。又帝舅陽安侯丁明，皆親以外屬封。喜執謙稱疾。傅太后始與政事，喜數諫之，〔二〕由是傅太后不欲令喜輔政。上於是用左將軍師丹代王莽為大司馬，賜喜黃金百斤，上將軍印綬，以光祿大夫養病。","sentenceOrder":86},
  {"id":"s_work_han_thu_95_87","chapterId":"ch_work_han_thu_95","textTraditional":"〔一〕　如淳曰：「俱傅太后從父弟也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_95_88","chapterId":"ch_work_han_thu_95","textTraditional":"〔二〕　師古曰：「與讀曰豫。」","sentenceOrder":88},
  {"id":"s_work_han_thu_95_89","chapterId":"ch_work_han_thu_95","textTraditional":"大司空何武、尚書令唐林皆上書言：「喜行義修絜，忠誠憂國，內輔之臣也，今以寑病，一旦遣歸，眾庶失望，皆曰傅氏賢子，以論議不合於定陶太后故退，百寮莫不為國恨之。忠臣，社稷之衛，魯以季友治亂，〔一〕楚以子玉輕重，〔二〕魏以無忌折衝，〔三〕項以范增存亡。故楚跨有南土，帶甲百萬，鄰國不以為難，子玉為將，則文公側席而坐，及其死也，君臣相慶。〔四〕百萬之眾，不如一賢，故秦行千金以間廉頗，〔五〕漢散萬金以疏亞父。〔六〕喜立於朝，陛下之光煇，傅氏之廢興也。」〔七〕上亦自重之。明年正月，乃徙師丹為大司空，而拜喜為大司馬，封高武侯。","sentenceOrder":89},
  {"id":"s_work_han_thu_95_90","chapterId":"ch_work_han_thu_95","textTraditional":"〔一〕　師古曰：「謂季氏亡，則魯不昌。」","sentenceOrder":90},
  {"id":"s_work_han_thu_95_91","chapterId":"ch_work_han_thu_95","textTraditional":"〔二〕　師古曰：「謂楚殺子玉而晉侯喜可知。」","sentenceOrder":91},
  {"id":"s_work_han_thu_95_92","chapterId":"ch_work_han_thu_95","textTraditional":"〔三〕　師古曰：「信陵君。」","sentenceOrder":92},
  {"id":"s_work_han_thu_95_93","chapterId":"ch_work_han_thu_95","textTraditional":"〔四〕　師古曰：「已解在上也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_95_94","chapterId":"ch_work_han_thu_95","textTraditional":"〔五〕　師古曰：「趙孝成王七年，秦與趙兵相距長平。趙將廉頗固壁不戰，秦乃使人反間於趙，曰：『秦之所惡，獨畏趙奢之子趙括為將耳。』趙王信之，因以括為將，代廉頗，而括軍遂敗，數十萬之眾降秦，秦皆阬之。」","sentenceOrder":94},
  {"id":"s_work_han_thu_95_95","chapterId":"ch_work_han_thu_95","textTraditional":"〔六〕　師古曰：「事在陳平傳。」","sentenceOrder":95},
  {"id":"s_work_han_thu_95_96","chapterId":"ch_work_han_thu_95","textTraditional":"〔七〕　如淳曰：「傅喜顯則傅氏興，其廢亦如之。」晉灼曰：「用喜於陛下有光明，而傅氏之廢復得興也。」師古曰：「如說是也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_95_97","chapterId":"ch_work_han_thu_95","textTraditional":"丁、傅驕奢，皆嫉喜之恭儉。又傅太后欲求稱尊號，與成帝母齊尊，喜與丞相孔光、大司空師丹共執正議。傅太后大怒，上不得已，先免師丹以感動喜，喜終不順。後數月，遂策免喜曰：「君輔政出入三年，未有昭然匡朕不逮，而本朝大臣遂其姦心，〔一〕咎由君焉。其上大司馬印綬，就第。」傅太后又自詔丞相御史曰：「高武侯喜無功而封，內懷不忠，附下罔上，與故大司空丹同心背畔，放命圮族，〔二〕虧損德化，罪惡雖在赦前，不宜奉朝請，其遣就國。」後又欲奪喜侯，上亦不聽。","sentenceOrder":97},
  {"id":"s_work_han_thu_95_98","chapterId":"ch_work_han_thu_95","textTraditional":"〔一〕　師古曰：「遂，成也，申也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_95_99","chapterId":"ch_work_han_thu_95","textTraditional":"〔二〕　應劭曰：「放棄教令，毀其族類。」","sentenceOrder":99},
  {"id":"s_work_han_thu_95_100","chapterId":"ch_work_han_thu_95","textTraditional":"喜在國三歲餘，哀帝崩，平帝即位，王莽用事，免傅氏官爵歸故郡，晏將妻子徙合浦。莽白太后下詔曰：「高武侯喜姿性端慤，論議忠直，〔一〕雖與故定陶太后有屬，終不順指從邪，介然守節，以故斥逐就國。傳不云乎？『歲寒然後知松柏之後凋也。』〔二〕其還喜長安，以故高安侯莫府賜喜，位特進，奉朝請。」喜雖外見褒賞，孤立憂懼，後復遣就國，以壽終。莽賜諡曰貞侯。子嗣，莽敗乃絕〔三〕。","sentenceOrder":100},
  {"id":"s_work_han_thu_95_101","chapterId":"ch_work_han_thu_95","textTraditional":"〔一〕　師古曰：「愨，謹也，音口角反。」","sentenceOrder":101},
  {"id":"s_work_han_thu_95_102","chapterId":"ch_work_han_thu_95","textTraditional":"〔二〕　師古曰：「論語載孔子之言，以喻有節操之人也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_95_103","chapterId":"ch_work_han_thu_95","textTraditional":"〔三〕　師古曰：「史不得其子名也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_95_104","chapterId":"ch_work_han_thu_95","textTraditional":"贊曰：自宣、元、成、哀外戚興者，許、史、三王、丁、傅之家，〔一〕皆重侯累將，窮貴極富，見其位矣，未見其人也。〔二〕陽平之王多有材能，好事慕名，其勢尤盛，曠貴最久。〔三〕然至於莽，亦以覆國。王商有剛毅節，廢黜以憂死，非其罪也。史丹父子相繼，高以重厚，位至三公。丹之輔道副主，掩惡揚美，傅會善意，〔四〕雖宿儒達士無以加焉。及其歷房闥，入臥內，推至誠，犯顏色，動寤萬乘，轉移大謀，卒成太子，安母后之位。「無言不讎」，終獲忠貞之報。〔五〕傅喜守節不傾，亦蒙後凋之賞。哀、平際會，禍福速哉！","sentenceOrder":104},
  {"id":"s_work_han_thu_95_105","chapterId":"ch_work_han_thu_95","textTraditional":"〔一〕　師古曰：「三王，謂卬成侯及商、鳳三家也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_95_106","chapterId":"ch_work_han_thu_95","textTraditional":"〔二〕　師古曰：「言無善人也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_95_107","chapterId":"ch_work_han_thu_95","textTraditional":"〔三〕　師古曰：「陽平謂王鳳之家也。言居非其位，是為曠官，故云曠貴。」","sentenceOrder":107},
  {"id":"s_work_han_thu_95_108","chapterId":"ch_work_han_thu_95","textTraditional":"〔四〕　師古曰：「道讀曰導。傅讀曰附。」","sentenceOrder":108},
  {"id":"s_work_han_thu_95_109","chapterId":"ch_work_han_thu_95","textTraditional":"〔五〕　師古曰：「大雅抑之詩曰：『無言不讎，無德不報。』故贊引之以喻丹也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_95_110","chapterId":"ch_work_han_thu_95","textTraditional":"校勘記","sentenceOrder":110},
  {"id":"s_work_han_thu_95_111","chapterId":"ch_work_han_thu_95","textTraditional":"三三七０頁　三行　〔老弱號呼〕，　景祐、殿本都有此四字，並有注文「師古曰呼音火故反」八字。","sentenceOrder":111},
  {"id":"s_work_han_thu_95_112","chapterId":"ch_work_han_thu_95","textTraditional":"三三七二頁一一行　宜窮（意）〔竟〕考問。　錢大昭說「意」當作「竟」。按景祐、殿本都作「竟」。","sentenceOrder":112},
  {"id":"s_work_han_thu_95_113","chapterId":"ch_work_han_thu_95","textTraditional":"三三七七頁　六行　同處（同）〔長〕養以至於壯大。景祐、殿本都作「長」。王先謙說作「長」是。","sentenceOrder":113},
  {"id":"s_work_han_thu_96_1","chapterId":"ch_work_han_thu_96","textTraditional":"薛宣字贛君，東海郯人也。〔一〕少為廷尉書佐都船獄史。後以大司農斗食屬察廉，補不其丞。〔二〕琅邪太守趙貢行縣，〔三〕見宣，甚說其能。〔四〕從宣歷行屬縣，〔五〕還至府，令妻子與相見，戒曰：「贛君至丞相，我兩子亦中丞相史。」察宣廉，遷樂浪都尉丞。〔六〕幽州刺史舉茂材，為宛句令。〔七〕大將軍王鳳聞其能，薦宣為長安令，治果有名，以明習文法詔補御史中丞。","sentenceOrder":1},
  {"id":"s_work_han_thu_96_2","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「贛音貢。郯音談。」","sentenceOrder":2},
  {"id":"s_work_han_thu_96_3","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「斗食者，祿少，一歲不滿百石，計日以斗為數也。不其，縣名也。其音基。」","sentenceOrder":3},
  {"id":"s_work_han_thu_96_4","chapterId":"ch_work_han_thu_96","textTraditional":"〔三〕　師古曰：「行音下更反。其下亦同。」","sentenceOrder":4},
  {"id":"s_work_han_thu_96_5","chapterId":"ch_work_han_thu_96","textTraditional":"〔四〕　師古曰：「說讀曰悅。」","sentenceOrder":5},
  {"id":"s_work_han_thu_96_6","chapterId":"ch_work_han_thu_96","textTraditional":"〔五〕　師古曰：「以宣自從也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_96_7","chapterId":"ch_work_han_thu_96","textTraditional":"〔六〕　師古曰：「趙貢察舉宣，故得遷也。樂音洛。浪音郎。」","sentenceOrder":7},
  {"id":"s_work_han_thu_96_8","chapterId":"ch_work_han_thu_96","textTraditional":"〔七〕　師古曰：「樂浪屬幽州。故為刺史所舉也。宛音於元反。句音劬。」","sentenceOrder":8},
  {"id":"s_work_han_thu_96_9","chapterId":"ch_work_han_thu_96","textTraditional":"是時，成帝初即位，宣為中丞，執法殿中，外總部刺史，上疏曰：「陛下至德仁厚，哀閔元元，躬有日仄之勞，而亡佚豫之樂，〔一〕允執聖道，刑罰惟中，〔二〕然而嘉氣尚凝，陰陽不和，〔三〕是臣下未稱，而聖化獨有不洽者也。臣竊伏思其一端，殆吏多苛政，政教煩碎，大率咎在部刺史，或不循守條職，〔四〕舉錯各以其意，多與郡縣事，〔五〕至開私門，聽讒佞，以求吏民過失，譴呵及細微，責義不量力。〔六〕郡縣相迫促，亦內相刻，流至眾庶。是故鄉黨闕於嘉賓之懽，九族忘其親親之恩，飲食周急之厚彌衰，送往勞來之禮不行。〔七〕夫人道不通，則陰陽否鬲，〔八〕和氣不興，未必不由此也。詩云：『民之失德，乾餱以愆。』〔九〕鄙語曰：『苛政親，煩苦傷恩。』方刺史奏事時，宜明申敕，〔一０〕使昭然知本朝之要務。臣愚不知治道唯明主察焉。」上嘉納之。","sentenceOrder":9},
  {"id":"s_work_han_thu_96_10","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「周書亡逸之篇稱文王之德曰『至于日中仄，弗皇暇食』，宣引此言也。仄，古側字也。佚與逸同。」","sentenceOrder":10},
  {"id":"s_work_han_thu_96_11","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「允，信也。中音竹仲反。」","sentenceOrder":11},
  {"id":"s_work_han_thu_96_12","chapterId":"ch_work_han_thu_96","textTraditional":"〔三〕　師古曰：「凝謂不通也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_96_13","chapterId":"ch_work_han_thu_96","textTraditional":"〔四〕　師古曰：「刺史所察，本有六條，今則踰越故事，信意舉劾，妄為苛刻也。六條解在百官公卿表。」","sentenceOrder":13},
  {"id":"s_work_han_thu_96_14","chapterId":"ch_work_han_thu_96","textTraditional":"〔五〕　師古曰：「錯，置也，音千故反。與讀曰豫。豫，干也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_96_15","chapterId":"ch_work_han_thu_96","textTraditional":"〔六〕　師古曰：「言求備於人。」","sentenceOrder":15},
  {"id":"s_work_han_thu_96_16","chapterId":"ch_work_han_thu_96","textTraditional":"〔七〕　師古曰：「勞音郎到反。來音郎代反。」","sentenceOrder":16},
  {"id":"s_work_han_thu_96_17","chapterId":"ch_work_han_thu_96","textTraditional":"〔八〕　師古曰：「否，閉也，音皮鄙反。鬲與隔同。」","sentenceOrder":17},
  {"id":"s_work_han_thu_96_18","chapterId":"ch_work_han_thu_96","textTraditional":"〔九〕　師古曰：「小雅伐木之詩也。餱，食也，解在元紀。餱音侯。」","sentenceOrder":18},
  {"id":"s_work_han_thu_96_19","chapterId":"ch_work_han_thu_96","textTraditional":"〔一０〕師古曰：「申，束也，謂約束也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_96_20","chapterId":"ch_work_han_thu_96","textTraditional":"宣數言政事便宜，舉奏部刺史郡國二千石，所貶退稱進，白黑分明，〔一〕繇是知名。〔二〕出為臨淮太守，政教大行。會陳留郡有大賊廢亂，〔三〕上徙宣為陳留太守，盜賊禁止，吏民敬其威信。入守左馮翊，滿歲稱職為真。","sentenceOrder":20},
  {"id":"s_work_han_thu_96_21","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「稱，舉也。白黑猶言清濁也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_96_22","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「繇讀與由同。」","sentenceOrder":22},
  {"id":"s_work_han_thu_96_23","chapterId":"ch_work_han_thu_96","textTraditional":"〔三〕　師古曰：「廢亂者，政教不行也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_96_24","chapterId":"ch_work_han_thu_96","textTraditional":"始高陵令（陽）〔楊〕湛、櫟陽令謝游皆貪猾不遜，持郡短長，前二千石數案不能竟。〔一〕及宣視事，詣府謁，宣設酒飯與相對，接待甚備。已而陰求其罪臧，具得所受取。宣察湛有改節敬宣之效，乃手自牒書，條其姦臧，〔二〕封與湛曰：「吏民條言君如牒，或議以為疑於主守盜。〔三〕馮翊敬重令，又念十金法重，不忍相暴章。〔四〕故密以手書相曉，欲君自圖進退，可復伸眉於後。〔五〕即無其事，復封還記，得為君分明之。」〔六〕湛自知罪臧皆應記，〔七〕而宣辭語溫潤，無傷害意。湛即時解印綬付吏，為記謝宣，終無怨言。而櫟陽令游自以大儒有名，輕宣。宣獨移書顯責之曰：「告櫟陽令：吏民言令治行煩苛，適罰作使千人以上；〔八〕賊取錢財數十萬，給為非法；〔九〕賣買聽任富吏，賈數不可知。〔一０〕證驗以明白，欲遣吏考案，恐負舉者，恥辱儒士，〔一一〕故使掾平鐫令〔一二〕。孔子曰：『陳力就列，不能者止。』〔一三〕令詳思之，方調守。」〔一四〕游得檄，亦解印綬去。","sentenceOrder":24},
  {"id":"s_work_han_thu_96_25","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「雖每案驗之，不能窮竟其事。」","sentenceOrder":25},
  {"id":"s_work_han_thu_96_26","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「牒書謂書於簡牒也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_96_27","chapterId":"ch_work_han_thu_96","textTraditional":"〔三〕　孟康曰：「法有主守盜，斷官錢自入己也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_96_28","chapterId":"ch_work_han_thu_96","textTraditional":"〔四〕　師古曰：「依當時律條，臧直十金，則至重罪。」","sentenceOrder":28},
  {"id":"s_work_han_thu_96_29","chapterId":"ch_work_han_thu_96","textTraditional":"〔五〕　師古曰：「伸眉，言無憂也。且令自去職不廢，其後更為官。」","sentenceOrder":29},
  {"id":"s_work_han_thu_96_30","chapterId":"ch_work_han_thu_96","textTraditional":"〔六〕　師古曰：「記謂所與湛書也。分明謂考問使知清白也。宣恐其距諱，即欲驗治之。」","sentenceOrder":30},
  {"id":"s_work_han_thu_96_31","chapterId":"ch_work_han_thu_96","textTraditional":"〔七〕　師古曰：「與宣書記相當。」","sentenceOrder":31},
  {"id":"s_work_han_thu_96_32","chapterId":"ch_work_han_thu_96","textTraditional":"〔八〕　師古曰：「適讀曰謫。」","sentenceOrder":32},
  {"id":"s_work_han_thu_96_33","chapterId":"ch_work_han_thu_96","textTraditional":"〔九〕　師古曰：「言斂取錢財，以供給興造非法之用。」","sentenceOrder":33},
  {"id":"s_work_han_thu_96_34","chapterId":"ch_work_han_thu_96","textTraditional":"〔一０〕師古曰：「賈讀曰價。」","sentenceOrder":34},
  {"id":"s_work_han_thu_96_35","chapterId":"ch_work_han_thu_96","textTraditional":"〔一一〕師古曰：「游本因薦舉得官，而身又是儒者，故云然。」","sentenceOrder":35},
  {"id":"s_work_han_thu_96_36","chapterId":"ch_work_han_thu_96","textTraditional":"〔一二〕如淳曰：「平鐫，激切使之自知過也。」晉灼曰：「王常為光武鐫說其將帥。此為徐以微言鐫鑿遣之也。」師古曰：「平，掾之名。鐫謂琢鑿也。鐫音子全反。」","sentenceOrder":36},
  {"id":"s_work_han_thu_96_37","chapterId":"ch_work_han_thu_96","textTraditional":"〔一三〕師古曰：「論語載孔子之答冉有、季路之言也。列，次也。言自審己之力用而就官次，不能則退。」","sentenceOrder":37},
  {"id":"s_work_han_thu_96_38","chapterId":"ch_work_han_thu_96","textTraditional":"〔一四〕師古曰：「言欲選人且代游守令職。」","sentenceOrder":38},
  {"id":"s_work_han_thu_96_39","chapterId":"ch_work_han_thu_96","textTraditional":"又頻陽縣北當上郡、西河，為數郡湊，多盜賊。其令平陵薛恭本縣孝者，功次稍遷，未嘗治民，職不辦。而粟邑縣小，辟在山中〔一〕，民謹樸易治。令鉅鹿尹賞久郡用事吏，為樓煩長，舉茂材，遷在粟。宣即以令奏賞與恭換縣。〔二〕二人視事數月，而兩縣皆治。宣因移書勞勉之曰：「昔孟公綽優於趙魏而不宜滕薛，〔三〕故或以德顯，或以功舉，『君子之道，焉可憮也！』〔四〕屬縣各有賢君，馮翊垂拱蒙成。〔五〕願勉所職，卒功業。」〔六〕","sentenceOrder":39},
  {"id":"s_work_han_thu_96_40","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「辟讀曰僻。」","sentenceOrder":40},
  {"id":"s_work_han_thu_96_41","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「時令條有材不稱職得改之。」","sentenceOrder":41},
  {"id":"s_work_han_thu_96_42","chapterId":"ch_work_han_thu_96","textTraditional":"〔三〕　師古曰：「孟公綽，魯大夫也。論語云『孔子曰：孟公綽為趙魏老則優，不可以為滕薛大夫。』言器能各有所施也。趙魏，晉之卿族。老謂家之長相也。滕薛，小國諸侯也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_96_43","chapterId":"ch_work_han_thu_96","textTraditional":"〔四〕　蘇林曰：「憮，同也，兼也。」晉灼曰：「憮音誣。」師古曰：「論語載子夏之言。謂行業不同，所守各異，唯聖人為能體備之。」","sentenceOrder":43},
  {"id":"s_work_han_thu_96_44","chapterId":"ch_work_han_thu_96","textTraditional":"〔五〕　師古曰：「自言端拱無為而受縣之成功。」","sentenceOrder":44},
  {"id":"s_work_han_thu_96_45","chapterId":"ch_work_han_thu_96","textTraditional":"〔六〕　師古曰：「卒，終也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_96_46","chapterId":"ch_work_han_thu_96","textTraditional":"宣得郡中吏民罪名，輒召告其縣長吏，使自行罰。曉曰：「府所以不自發舉者，不欲代縣治，奪賢令長名也。」長吏莫不喜懼，免冠謝宣歸恩受戒者。","sentenceOrder":46},
  {"id":"s_work_han_thu_96_47","chapterId":"ch_work_han_thu_96","textTraditional":"宣為吏賞罰明，用法平而必行，所居皆有條教可紀，多仁恕愛利。〔一〕池陽令舉廉吏獄掾王立，府未及召，聞立受囚家錢。宣責讓縣，縣案驗獄掾，乃其妻獨受繫者錢萬六千，受之再宿，獄掾實不知。掾慚恐自殺。宣聞之，移書池陽曰：「縣所舉廉吏獄掾王立，家私受賕，而立不知，殺身以自明。立誠廉士，甚可閔惜！其以府決曹掾書立之柩，以顯其魂。〔二〕府掾史素與立相知者，皆予送葬。」","sentenceOrder":47},
  {"id":"s_work_han_thu_96_48","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「愛人而安利也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_96_49","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「以此職追贈。」","sentenceOrder":49},
  {"id":"s_work_han_thu_96_50","chapterId":"ch_work_han_thu_96","textTraditional":"及日至休吏，〔一〕賊曹掾張扶獨不肯休，坐曹治事。宣出教曰：「蓋禮貴和，人道尚通。日至，吏以令休，所繇來久。〔二〕曹雖有公職事，家亦望私恩意。掾宜從眾，歸對妻子，設酒肴，請鄰里，壹笑相樂，〔三〕斯亦可矣！」扶慚愧。官屬善之。","sentenceOrder":50},
  {"id":"s_work_han_thu_96_51","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「冬夏至之日不省官事，故休吏。」","sentenceOrder":51},
  {"id":"s_work_han_thu_96_52","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「繇讀與由同。由，從也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_96_53","chapterId":"ch_work_han_thu_96","textTraditional":"〔三〕　應劭曰：「以壺矢相樂也。」晉灼曰：「書篆形『壹笑』字象壺矢，因曰壺矢。此說非也。」師古曰：「晉說是也。壹笑，謂一為歡笑耳。关，古笑字也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_96_54","chapterId":"ch_work_han_thu_96","textTraditional":"宣為人好威儀，進止雍容，甚可觀也。性密靜有思，〔一〕思省吏職，求其便安。〔二〕下至財用筆研，皆為設方略，利用而省費。〔三〕吏民稱之，郡中清靜。遷為少府，共張職辦。〔四〕","sentenceOrder":54},
  {"id":"s_work_han_thu_96_55","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「有智思也，音先寺反。」","sentenceOrder":55},
  {"id":"s_work_han_thu_96_56","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「省，視也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_96_57","chapterId":"ch_work_han_thu_96","textTraditional":"〔三〕　師古曰：「利，便也。省，減也。便於用而減於費也。省音所領反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_96_58","chapterId":"ch_work_han_thu_96","textTraditional":"〔四〕　師古曰：「共讀曰供，音居用反。張音竹亮反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_96_59","chapterId":"ch_work_han_thu_96","textTraditional":"月餘，御史大夫于永卒，谷永上疏曰：「帝王之德莫大於知人，知人則百僚任職，天工不曠。〔一〕故皋陶曰：『知人則哲，能官人。』〔二〕御史大夫內承本朝之風化，外佐丞相統理天下，任重職大，非庸材所能堪。今當選於群卿，以充其缺。得其人則萬姓欣喜，百僚說服；〔三〕不得其人則大職墮斁，王功不興。〔四〕虞帝之明，在茲壹舉，可不致詳！竊見少府宣，材茂行絜，達於從政，前為御史中丞，執憲轂下，〔五〕不吐剛茹柔，〔六〕舉錯時當；〔七〕出守臨淮、陳留，二郡稱治；為左馮翊，崇教養善，威德並行，眾職修理，姦軌絕息，辭訟者歷年不至丞相府，赦後餘盜賊什分三輔之一〔八〕。功效卓爾，自左內史初置以來未嘗有也。〔九〕孔子曰：『如有所譽，其有所試。』〔一０〕宣考績功課，簡在兩府，〔一一〕不敢過稱以奸欺誣之罪。〔一二〕臣聞賢材莫大於治人，宣已有效。其法律任廷尉有餘，經術文雅足以謀王體，斷國論；身兼數器，有『退食自公』之節。〔一三〕宣無私黨游說之助，臣恐陛下忽於羔羊之詩，舍公實之臣，任華虛之譽，是用越職，陳宣行能，唯陛下留神考察。」上然之，遂以宣為御史大夫。","sentenceOrder":59},
  {"id":"s_work_han_thu_96_60","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「工，官也。曠，空也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_96_61","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「虞書皋陶謨之辭也。哲，智也。無所不知，故能官人也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_96_62","chapterId":"ch_work_han_thu_96","textTraditional":"〔三〕　師古曰：「說讀曰悅。」","sentenceOrder":62},
  {"id":"s_work_han_thu_96_63","chapterId":"ch_work_han_thu_96","textTraditional":"〔四〕　師古曰：「墮，毀也。斁，壞也。墮音火規反。斁音丁固反。」","sentenceOrder":63},
  {"id":"s_work_han_thu_96_64","chapterId":"ch_work_han_thu_96","textTraditional":"〔五〕　師古曰：「言在天子輦轂之下。」","sentenceOrder":64},
  {"id":"s_work_han_thu_96_65","chapterId":"ch_work_han_thu_96","textTraditional":"〔六〕　師古曰：「大雅（蒸人）〔烝民〕之詩云『惟仲山甫，剛亦不吐，柔亦不茹』，言其平正也。茹，食也，音人庶反。」","sentenceOrder":65},
  {"id":"s_work_han_thu_96_66","chapterId":"ch_work_han_thu_96","textTraditional":"〔七〕　師古曰：「言其合時而當理也。當音丁浪反。」","sentenceOrder":66},
  {"id":"s_work_han_thu_96_67","chapterId":"ch_work_han_thu_96","textTraditional":"〔八〕　文穎曰：「減三輔之賊什九也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_96_68","chapterId":"ch_work_han_thu_96","textTraditional":"〔九〕　師古曰：「馮翊本左內史之地，故云然。」","sentenceOrder":68},
  {"id":"s_work_han_thu_96_69","chapterId":"ch_work_han_thu_96","textTraditional":"〔一０〕師古曰：「論語載孔子之言也。所以言譽人者，必當試之以事。」","sentenceOrder":69},
  {"id":"s_work_han_thu_96_70","chapterId":"ch_work_han_thu_96","textTraditional":"〔一一〕師古曰：「簡，大也，一曰明也。兩府，丞相、御史府也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_96_71","chapterId":"ch_work_han_thu_96","textTraditional":"〔一二〕師古曰：「過稱，謂踰其實而妄稱譽之也。奸，犯也，音干。」","sentenceOrder":71},
  {"id":"s_work_han_thu_96_72","chapterId":"ch_work_han_thu_96","textTraditional":"〔一三〕師古曰：「自，從也。召南羔羊之時，美在位皆節儉正直。其詩曰：『退食自公，委蛇委蛇。』言卿大夫履行清絜，減退膳食，率從公道也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_96_73","chapterId":"ch_work_han_thu_96","textTraditional":"數月，代張禹為丞相，封高陽侯，食邑千戶。宣除趙貢兩子為史。貢者，趙廣漢之兄子也，為吏亦有能名。宣為相，府辭訟例不滿萬錢不為移書，後皆遵用薛侯故事。然官屬譏其煩碎無大體，不稱賢也。時天子好儒雅，宣經術又淺，上亦輕焉。","sentenceOrder":73},
  {"id":"s_work_han_thu_96_74","chapterId":"ch_work_han_thu_96","textTraditional":"久之，廣漢郡盜賊群起，丞相御史遣掾史逐捕不能克。上乃拜河東都尉趙護為廣漢太守，以軍法從事。數月，斬其渠帥鄭躬，〔一〕降者數千人，乃平。會邛成太后崩，喪事倉卒，吏賦斂以趨辦。〔二〕其後上聞之，以過丞相御史，遂冊免宣曰：「君為丞相，出入六年，忠孝之行，率先百僚，朕無聞焉。〔三〕朕既不明，變異數見，歲比不登，倉廩空虛，〔四〕百姓飢饉，流離道路，疾疫死者以萬數，人至相食，盜賊並興，群職曠廢，是朕之不德而股肱不良也。乃者廣漢群盜橫恣，殘賊吏民，朕惻然傷之，數以問君，君對輒不如其實。西州鬲絕，幾不為郡。〔五〕三輔賦斂無度，酷吏並緣為姦，〔六〕侵擾百姓，詔君案驗，復無欲得事實之意。九卿以下，咸承風指，同時陷于謾欺之辜，咎繇君焉！〔七〕有司法君領職解嫚，〔八〕開謾欺之路，傷薄風化，無以帥示四方。不忍致君于理，其上丞相高陽侯印綬，罷歸。」","sentenceOrder":74},
  {"id":"s_work_han_thu_96_75","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「渠，大也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_96_76","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「邛成太后，宣帝王皇后也。趨讀曰趣。言苟取辦。」","sentenceOrder":76},
  {"id":"s_work_han_thu_96_77","chapterId":"ch_work_han_thu_96","textTraditional":"〔三〕　師古曰：「不聞其有此行也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_96_78","chapterId":"ch_work_han_thu_96","textTraditional":"〔四〕　師古曰：「比，頻也。登，成也。年穀不成。」","sentenceOrder":78},
  {"id":"s_work_han_thu_96_79","chapterId":"ch_work_han_thu_96","textTraditional":"〔五〕　師古曰：「鬲與隔同。幾音鉅依反。」","sentenceOrder":79},
  {"id":"s_work_han_thu_96_80","chapterId":"ch_work_han_thu_96","textTraditional":"〔六〕　師古曰：「並音步浪反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_96_81","chapterId":"ch_work_han_thu_96","textTraditional":"〔七〕　師古曰：「謾，誑也，音慢，又音莫干反。繇讀與由同。」","sentenceOrder":81},
  {"id":"s_work_han_thu_96_82","chapterId":"ch_work_han_thu_96","textTraditional":"〔八〕　師古曰：「法謂據法以劾也。解讀曰懈。嫚與慢同。」","sentenceOrder":82},
  {"id":"s_work_han_thu_96_83","chapterId":"ch_work_han_thu_96","textTraditional":"初，宣為丞相，而翟方進為司直。宣知方進名儒，有宰相器，深結厚焉。後方進竟代為丞相，思宣舊恩，宣免後二歲，薦宣明習文法，練國制度，〔一〕前所坐過薄，可復進用。上徵宣，復爵高陽侯，加寵特進，位次師安昌侯，給事中，視尚書事。宣復尊重。任政數年，後坐善定陵侯淳于長罷就第。","sentenceOrder":83},
  {"id":"s_work_han_thu_96_84","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「練猶熟也。言其詳熟。」","sentenceOrder":84},
  {"id":"s_work_han_thu_96_85","chapterId":"ch_work_han_thu_96","textTraditional":"初，宣有兩弟，明、修。明至南陽太守。修歷郡守、京兆尹、少府，善交接，得州里之稱。後母常從修居官。宣為丞相時，修為臨菑令，宣迎後母，修不遣。後母病死，修去官持服。宣謂修三年服少能行之者，兄弟相駮不可，〔一〕修遂竟服，繇是兄弟不和。〔二〕","sentenceOrder":85},
  {"id":"s_work_han_thu_96_86","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「駮者，執意不同，猶如色之間雜。」","sentenceOrder":86},
  {"id":"s_work_han_thu_96_87","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「繇讀與由同。」","sentenceOrder":87},
  {"id":"s_work_han_thu_96_88","chapterId":"ch_work_han_thu_96","textTraditional":"久之，哀帝初即位，博士申咸給事中，亦東海人也，毀宣不供養行喪服，薄於骨肉，前以不忠孝免，不宜復列封侯在朝省。宣子況為右曹侍郎，數聞其語，賕客楊明，欲令創咸面目，使不居位。〔一〕會司隸缺，況恐咸為之，遂令明遮斫咸宮門外，斷鼻脣，身八創。","sentenceOrder":88},
  {"id":"s_work_han_thu_96_89","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「創謂傷之也，音初良反。其下並同。」","sentenceOrder":89},
  {"id":"s_work_han_thu_96_90","chapterId":"ch_work_han_thu_96","textTraditional":"事下有司，御史中丞眾等奏：「況朝臣，父故宰相，再封列侯，不相敕丞化，而骨肉相疑，疑咸受修言以謗毀宣。咸所言皆宣行跡，眾人所共見，公家所宜聞。況知咸給事中，恐為司隸舉奏宣，而公令明等迫切宮闕，要遮創戮近臣於大道人眾中，欲以鬲塞聰明，杜絕論議之端。〔一〕桀黠無所畏忌，萬眾讙譁，流聞四方，不與凡民忿怒爭鬥者同。臣聞敬近臣，為近主也。禮，下公門，式路馬，〔二〕君畜產且猶敬之。春秋之義，意惡功遂，不免於誅，〔三〕上浸之源不可長也。〔四〕況首為惡，明手傷，功意俱惡，〔五〕皆大不敬。明當以重論，及況皆棄市。」廷尉直以為「律曰『鬥以刃傷人，完為城旦，其賊加罪一等，與謀者同罪。』詔書無以詆欺成罪。〔六〕傳曰：『遇人不以義而見疻者，與痏人之罪鈞，惡不直也。』〔七〕咸厚善修，而數稱宣惡，流聞不誼，不可謂直。〔八〕況以故傷咸，計謀已定，後聞置司隸，因前謀而趣明，〔九〕非以恐咸為司隸故造謀也。本爭私變，雖於掖門外傷咸道中，與凡民爭鬥無異。殺人者死，傷人者刑，古今之通道，三代所不易也。孔子曰：『必也正名。』名不正，則至於刑罰不中；刑罰不中，而民無所錯手足。〔一０〕今以況為首惡，明手傷為大不敬，公私無差。春秋之義，原心定罪。〔一一〕原況以父見謗發忿怒，無它大惡。加詆欺，輯小過成大辟，〔一二〕陷死刑，違明詔，恐非法意，不可施行。聖王不以怒增刑。明當以賊傷人不直，〔一三〕況與謀者皆爵減完為城旦。」〔一四〕上以問公卿議臣。丞相孔光、大司空師丹以中丞議是，自將軍以下至博士議郎皆是廷尉。況竟減罪一等，徙敦煌。宣坐免為庶人，歸故郡，卒於家。","sentenceOrder":90},
  {"id":"s_work_han_thu_96_91","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「鬲與隔同。杜，塞也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_96_92","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「過公門則下車，見路馬則撫式，蓋崇敬也。式，車前橫木。」","sentenceOrder":92},
  {"id":"s_work_han_thu_96_93","chapterId":"ch_work_han_thu_96","textTraditional":"〔三〕　師古曰：「遂，成也。言舉意不善，雖有成功猶加誅。」","sentenceOrder":93},
  {"id":"s_work_han_thu_96_94","chapterId":"ch_work_han_thu_96","textTraditional":"〔四〕　師古曰：「浸，近也。言傷戮大臣，有所逼近也。浸字或作侵。侵，犯也，其義兩通。長音竹兩反。」","sentenceOrder":94},
  {"id":"s_work_han_thu_96_95","chapterId":"ch_work_han_thu_96","textTraditional":"〔五〕　孟康曰：「手傷人為功，使人行傷人者為意。」","sentenceOrder":95},
  {"id":"s_work_han_thu_96_96","chapterId":"ch_work_han_thu_96","textTraditional":"〔六〕　師古曰：「詆，毀也，音丁禮反。」","sentenceOrder":96},
  {"id":"s_work_han_thu_96_97","chapterId":"ch_work_han_thu_96","textTraditional":"〔七〕　應劭曰：「以杖手敺擊人，剝其皮膚，腫起青黑而無創瘢者，律謂疻痏。遇人不以義為不直，雖見敺與敺人罪同也。」師古曰：「疻音侈。痏音鮪。」","sentenceOrder":97},
  {"id":"s_work_han_thu_96_98","chapterId":"ch_work_han_thu_96","textTraditional":"〔八〕　師古曰：「言咸為修而毀宣，是不誼而不直。」","sentenceOrder":98},
  {"id":"s_work_han_thu_96_99","chapterId":"ch_work_han_thu_96","textTraditional":"〔九〕　師古曰：「趣讀曰促。」","sentenceOrder":99},
  {"id":"s_work_han_thu_96_100","chapterId":"ch_work_han_thu_96","textTraditional":"〔一０〕師古曰：「論語載孔子之言也。錯，置也，音千故反。」","sentenceOrder":100},
  {"id":"s_work_han_thu_96_101","chapterId":"ch_work_han_thu_96","textTraditional":"〔一一〕師古曰：「原謂尋其本也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_96_102","chapterId":"ch_work_han_thu_96","textTraditional":"〔一二〕師古曰：「輯與集同。集，合也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_96_103","chapterId":"ch_work_han_thu_96","textTraditional":"〔一三〕師古曰：「以其受賕也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_96_104","chapterId":"ch_work_han_thu_96","textTraditional":"〔一四〕師古曰：「以其身有爵級，故得減罪而為完也。況身及同謀之人，皆從此科。」","sentenceOrder":104},
  {"id":"s_work_han_thu_96_105","chapterId":"ch_work_han_thu_96","textTraditional":"宣子惠亦至二千石。始惠為彭城令，宣從臨淮遷至陳留，過其縣，橋梁郵亭不修。〔一〕宣心知惠不能，留彭城數日，案行舍中，處置什器，〔二〕觀視園菜，終不問惠以吏事。惠自知治縣不稱宣意，遣門下掾送宣至陳留，令掾進見，自從其所問宣不教戒惠吏職之意。〔三〕宣笑曰：「吏道以法令為師，可問而知。及能與不能，自有資材，何可學也？」眾人傳稱，以宣言為然。","sentenceOrder":105},
  {"id":"s_work_han_thu_96_106","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「郵，行書之舍，亦如今之驛及行道館舍也，音尤。」","sentenceOrder":106},
  {"id":"s_work_han_thu_96_107","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「處，安也。什器，為生之具也，解在平紀。」","sentenceOrder":107},
  {"id":"s_work_han_thu_96_108","chapterId":"ch_work_han_thu_96","textTraditional":"〔三〕　師古曰：「若自出其意，不云惠使之言。」","sentenceOrder":108},
  {"id":"s_work_han_thu_96_109","chapterId":"ch_work_han_thu_96","textTraditional":"初，宣後封為侯時，妻死，而敬武長公主寡居，上令宣尚焉。及宣免歸故郡，公主留京師。後宣卒，主上書願還宣葬延陵，奏可。況私從敦煌歸長安，會赦，因留與主私亂。哀帝外家丁、傅貴，主附事之，而疏王氏。元始中，莽自尊為安漢公，主又出言非莽。而況與呂寬相善，及寬事覺時，莽并治況，發揚其罪，使使者以太皇太后詔賜主藥。主怒曰：「劉氏孤弱，王氏擅朝，排擠宗室，〔一〕且嫂何與取妹披抉其閨門而殺之？」〔二〕使者迫守主，〔三〕遂飲藥死。況梟首於市。白太后云主暴病薨。太后欲臨其喪，莽固爭，乃止。","sentenceOrder":109},
  {"id":"s_work_han_thu_96_110","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「擠，墜也，音子詣反。」","sentenceOrder":110},
  {"id":"s_work_han_thu_96_111","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「敬武公主，宣帝女也，故謂元后為嫂。披，發也。抉，挑也。與讀曰豫。豫，干也。言此事不干於嫂也。抉音一穴反。挑音它凋反。」","sentenceOrder":111},
  {"id":"s_work_han_thu_96_112","chapterId":"ch_work_han_thu_96","textTraditional":"〔三〕　師古曰：「守而逼之。」","sentenceOrder":112},
  {"id":"s_work_han_thu_96_113","chapterId":"ch_work_han_thu_96","textTraditional":"朱博字子元，杜陵人也。家貧，少時給事縣為亭長，好客少年，捕搏敢行。〔一〕稍遷為功曹，伉俠好交，〔二〕隨從士大夫，不避風雨。是時，前將軍望之子蕭育、御史大夫萬年子陳咸以公卿子著材知名，博皆友之矣。時諸陵縣屬太常，博以太常掾察廉，補安陵丞。後去官入京兆，歷曹史列掾，出為督郵書掾，所部職辦，郡中稱之。","sentenceOrder":113},
  {"id":"s_work_han_thu_96_114","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「好賓客及少年而追捕擊搏無所避也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_96_115","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「伉，健也，音口浪反。」","sentenceOrder":115},
  {"id":"s_work_han_thu_96_116","chapterId":"ch_work_han_thu_96","textTraditional":"而陳咸為御史中丞，坐漏泄省中語下獄。博去吏，間步至廷尉中，〔一〕候伺咸事。咸掠治困篤，博詐得為醫入獄，得見咸，具知其所坐罪。博出獄，又變姓名，為咸驗治數百，〔二〕卒免咸死罪。咸得論出，而博以此顯名，為郡功曹。","sentenceOrder":116},
  {"id":"s_work_han_thu_96_117","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「去吏，自解職也。間步，謂步行而伺間隙以去。」","sentenceOrder":117},
  {"id":"s_work_han_thu_96_118","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「謂被掠笞也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_96_119","chapterId":"ch_work_han_thu_96","textTraditional":"久之，成帝即位，大將軍王鳳秉政，奏請陳咸為長史。咸薦蕭育、朱博除莫府屬，鳳甚奇之，舉博櫟陽令，徙雲陽、平陵（三）〔二〕縣，以高弟入為長安令。京師治理，遷冀州刺史。","sentenceOrder":119},
  {"id":"s_work_han_thu_96_120","chapterId":"ch_work_han_thu_96","textTraditional":"博本武吏，不更文法，〔一〕及為刺史行部，〔二〕吏民數百人遮道自言，官寺盡滿。從事白請且留此縣錄見諸自言者，事畢乃發，欲以觀試博。博心知之，告外趣駕。〔三〕既白駕辦，博出就車見自言者，使從事明敕告吏民：「欲言縣丞尉者，刺史不察黃綬，各自詣郡。〔四〕欲言二千石墨綬長吏者，使者行部還，詣治所。〔五〕其民為吏所冤，及言盜賊辭訟事，各使屬其部從事。」〔六〕博駐車決遣，四五百人皆罷去，如神。吏民大驚，不意博應事變乃至於此。後博徐問，果老從事教民聚會。博殺此吏，州郡畏博威嚴。徙為并州刺史，護漕都尉，遷琅邪太守。","sentenceOrder":120},
  {"id":"s_work_han_thu_96_121","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「更，歷也，音工衡反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_96_122","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「行音下更反。」","sentenceOrder":122},
  {"id":"s_work_han_thu_96_123","chapterId":"ch_work_han_thu_96","textTraditional":"〔三〕　師古曰：「趣讀曰促。」","sentenceOrder":123},
  {"id":"s_work_han_thu_96_124","chapterId":"ch_work_han_thu_96","textTraditional":"〔四〕　師古曰：「丞尉職卑皆黃綬。」","sentenceOrder":124},
  {"id":"s_work_han_thu_96_125","chapterId":"ch_work_han_thu_96","textTraditional":"〔五〕　師古曰：「治所，刺史所止理事處。」","sentenceOrder":125},
  {"id":"s_work_han_thu_96_126","chapterId":"ch_work_han_thu_96","textTraditional":"〔六〕　師古曰：「屬，委也，音之欲反。」","sentenceOrder":126},
  {"id":"s_work_han_thu_96_127","chapterId":"ch_work_han_thu_96","textTraditional":"齊郡舒緩養名，〔一〕博新視事，右曹掾史皆移病臥。〔二〕博問其故，對言「惶恐！〔三〕故事二千石新到，輒遣吏存問致意，乃敢起就職。」博奮髯抵几曰：〔四〕「觀齊兒欲以此為俗邪！」乃召見諸曹史書佐及縣大吏，選視其可用者，出教置之。〔五〕皆斥罷諸病吏，白巾走出府門。郡中大驚。頃之，門下掾贛遂耆老大儒，教授數百人，拜起舒遲。博出教主簿：〔六〕「贛老生不習吏禮，主簿且教拜起，閑習乃止。」又敕功曹：「官屬多褒衣大袑，〔七〕不中節度，自今掾史衣皆令去地三寸。」博尤不愛諸生，所至郡輒罷去議曹，曰：「豈可復置謀曹邪！」文學儒吏時有奏記稱說云云，博見謂曰：「如太守漢吏，奉三尺律令以從事耳，亡奈生所言聖人道何也〔八〕！且持此道歸，堯舜君出，為陳說之。」其折逆人如此。視事數年，大改其俗，掾史禮節如楚、趙吏。","sentenceOrder":127},
  {"id":"s_work_han_thu_96_128","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「言齊人之俗，其性遲緩，多自高大以養名聲。」","sentenceOrder":128},
  {"id":"s_work_han_thu_96_129","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「右曹，上曹也。移病，謂移書言病也，一曰以病而移居也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_96_130","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「言懼新太守之威。」","sentenceOrder":130},
  {"id":"s_work_han_thu_96_131","chapterId":"ch_work_han_thu_96","textTraditional":"〔四〕　師古曰：「髯，頰毛也。抵，擊也，音紙。」","sentenceOrder":131},
  {"id":"s_work_han_thu_96_132","chapterId":"ch_work_han_thu_96","textTraditional":"〔五〕　師古曰：「皆新補置，以代移病者。」","sentenceOrder":132},
  {"id":"s_work_han_thu_96_133","chapterId":"ch_work_han_thu_96","textTraditional":"〔六〕　師古曰：「以此教告主簿。」","sentenceOrder":133},
  {"id":"s_work_han_thu_96_134","chapterId":"ch_work_han_thu_96","textTraditional":"〔七〕　師古曰：「袑音紹，謂大袴也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_96_135","chapterId":"ch_work_han_thu_96","textTraditional":"〔八〕　師古曰：「言不能用。」","sentenceOrder":135},
  {"id":"s_work_han_thu_96_136","chapterId":"ch_work_han_thu_96","textTraditional":"博治郡，常令屬縣各用其豪桀以為大吏，文武從宜。〔一〕縣有劇賊及它非常，博輒移書以詭責之。其盡力有效，必加厚賞；懷詐不稱，誅罰輒行。〔二〕以是豪強慹服。〔三〕姑幕縣有群輩八人報仇廷中，皆不得。〔四〕長吏自繫書言府，賊曹掾史自白請至姑幕。事留不出。功曹諸掾即皆自白，復不出。於是府丞詣閤，博乃見丞掾曰：「以為縣自有長吏，府未嘗與也，丞掾謂府當與之邪？」〔五〕閤下書佐入，博口占檄文曰：〔六〕「府告姑幕令丞：言賊發不得，有書。〔七〕檄到，令丞就職，游徼王卿力有餘，如律令！」〔八〕王卿得敕惶怖，親屬失色，晝夜馳騖，十餘日間捕得五人。博復移書曰：「王卿憂公甚效！檄到，齎伐閱詣府。〔九〕部掾以下亦可用，漸盡其餘矣。」〔一０〕其操持下，皆此類也。","sentenceOrder":136},
  {"id":"s_work_han_thu_96_137","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「各因其材而任之。」","sentenceOrder":137},
  {"id":"s_work_han_thu_96_138","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「稱，副也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_96_139","chapterId":"ch_work_han_thu_96","textTraditional":"〔三〕　師古曰：「慹音之涉反。」","sentenceOrder":139},
  {"id":"s_work_han_thu_96_140","chapterId":"ch_work_han_thu_96","textTraditional":"〔四〕　師古曰：「於縣廷之中報仇殺人，而其賊亡，捕不得也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_96_141","chapterId":"ch_work_han_thu_96","textTraditional":"〔五〕　師古曰：「與讀皆曰豫。」","sentenceOrder":141},
  {"id":"s_work_han_thu_96_142","chapterId":"ch_work_han_thu_96","textTraditional":"〔六〕　師古曰：「隱度其言口授之。占音之贍反。」","sentenceOrder":142},
  {"id":"s_work_han_thu_96_143","chapterId":"ch_work_han_thu_96","textTraditional":"〔七〕　師古曰：「言已得縣之文書如此。」","sentenceOrder":143},
  {"id":"s_work_han_thu_96_144","chapterId":"ch_work_han_thu_96","textTraditional":"〔八〕　師古曰：「游徼職主捕盜賊，故云如律令。」","sentenceOrder":144},
  {"id":"s_work_han_thu_96_145","chapterId":"ch_work_han_thu_96","textTraditional":"〔九〕　師古曰：「伐，功勞也。閱，所經歷也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_96_146","chapterId":"ch_work_han_thu_96","textTraditional":"〔一０〕師古曰：「部掾，所部之掾也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_96_147","chapterId":"ch_work_han_thu_96","textTraditional":"以高弟入守左馮翊，滿歲為真。其治左馮翊，文理聰明殊不及薛宣，而多武譎，網絡張設，少愛利，敢誅殺。〔一〕然亦縱舍，時有大貸，〔二〕下吏以此為盡力。","sentenceOrder":147},
  {"id":"s_work_han_thu_96_148","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「言少仁愛而不能便利於人。」","sentenceOrder":148},
  {"id":"s_work_han_thu_96_149","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「縱，放也。舍，置也。貸謂寬假於下也，音吐戴反。」","sentenceOrder":149},
  {"id":"s_work_han_thu_96_150","chapterId":"ch_work_han_thu_96","textTraditional":"長陵大姓尚方禁〔一〕少時嘗盜人妻，見斫，創著其頰。府功曹受賂，白除禁調守尉。博聞知，以它事召見，視其面，果有瘢。〔二〕博辟左右問禁：〔三〕「是何等創也？」禁自知情得，〔四〕叩頭服狀。博笑曰：「（大）丈夫固時有是。〔五〕馮翊欲洒卿恥，抆拭用禁，〔六〕能自效不？」禁且喜且懼，對曰：「必死！」〔七〕博因敕禁：「毋得泄語，有便宜，輒記言。」〔八〕因親信之以為耳目。禁晨夜發起部中盜賊及它伏姦，有功效。博擢禁連守縣令。久之，召見功曹，閉閤數責以禁等事，與筆札（便）〔使〕自記，「積受取一錢以上，無得有所匿。〔九〕欺謾半言，斷頭矣！」〔一０〕功曹惶怖，具自疏姦臧，大小不敢隱。博知其對以實，乃令就席，受敕自改而已。投刀使削所記，遣出就職。功曹後常戰栗，不敢蹉跌，〔一一〕博遂成就之。〔一二〕","sentenceOrder":150},
  {"id":"s_work_han_thu_96_151","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「姓尚方，名禁。」","sentenceOrder":151},
  {"id":"s_work_han_thu_96_152","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「瘢，創痕也，音盤。痕音胡恩反。」","sentenceOrder":152},
  {"id":"s_work_han_thu_96_153","chapterId":"ch_work_han_thu_96","textTraditional":"〔三〕　師古曰：「辟讀曰闢。」","sentenceOrder":153},
  {"id":"s_work_han_thu_96_154","chapterId":"ch_work_han_thu_96","textTraditional":"〔四〕　師古曰：「言其得被斫之情狀。」","sentenceOrder":154},
  {"id":"s_work_han_thu_96_155","chapterId":"ch_work_han_thu_96","textTraditional":"〔五〕　師古曰：「言情Q欲Y之事，人所不免。」","sentenceOrder":155},
  {"id":"s_work_han_thu_96_156","chapterId":"ch_work_han_thu_96","textTraditional":"〔六〕　師古曰：「抆拭，摩也。洒音先禮反。抆音文粉反。」","sentenceOrder":156},
  {"id":"s_work_han_thu_96_157","chapterId":"ch_work_han_thu_96","textTraditional":"〔七〕　師古曰：「言盡死力也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_96_158","chapterId":"ch_work_han_thu_96","textTraditional":"〔八〕　師古曰：「不令泄抆拭之言，而外有便宜之事，為書記以言於博。」","sentenceOrder":158},
  {"id":"s_work_han_thu_96_159","chapterId":"ch_work_han_thu_96","textTraditional":"〔九〕　師古曰：「積累前後受取之事。」","sentenceOrder":159},
  {"id":"s_work_han_thu_96_160","chapterId":"ch_work_han_thu_96","textTraditional":"〔一０〕師古曰：「謾，誑也，音慢，又音莫連反。」","sentenceOrder":160},
  {"id":"s_work_han_thu_96_161","chapterId":"ch_work_han_thu_96","textTraditional":"〔一一〕師古曰：「蹉音千何反。跌音徒結反。」","sentenceOrder":161},
  {"id":"s_work_han_thu_96_162","chapterId":"ch_work_han_thu_96","textTraditional":"〔一二〕師古曰：「言進達也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_96_163","chapterId":"ch_work_han_thu_96","textTraditional":"遷為大司農。歲餘，坐小法，左遷犍為太守。先是南蠻若兒數為寇盜，〔一〕博厚結其昆弟，使為反間，襲殺之，〔二〕郡中清。","sentenceOrder":163},
  {"id":"s_work_han_thu_96_164","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「若兒，其豪長之名。」","sentenceOrder":164},
  {"id":"s_work_han_thu_96_165","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「間音居莧反。」","sentenceOrder":165},
  {"id":"s_work_han_thu_96_166","chapterId":"ch_work_han_thu_96","textTraditional":"徙為山陽太守，病免官。復徵為光祿大夫，遷廷尉，職典決疑，當讞平天下獄。博恐為官屬所誣，視事，召見正監典法掾史，謂曰：「廷尉本起於武吏，不通法律，幸有眾賢，亦何憂！然廷尉治郡斷獄以來且二十年，亦獨耳剽日久，〔一〕三尺律令，人事出其中。〔二〕掾史試與正監共撰前世決事吏議難知者數十事，持以問廷尉，得〔為〕諸君覆意之。」〔三〕正監以為博苟強，意未必能然，即共條白焉。博皆召掾史，並坐而問，為平處其輕重，十中八九。〔四〕官屬咸服博之疏略，材過人也。每遷徙易官，所到輒出奇譎如此，以明示下為不可欺者。","sentenceOrder":166},
  {"id":"s_work_han_thu_96_167","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「剽，劫也，猶言行聽也。剽音頻妙反。」","sentenceOrder":167},
  {"id":"s_work_han_thu_96_168","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「言可以人情知之。」","sentenceOrder":168},
  {"id":"s_work_han_thu_96_169","chapterId":"ch_work_han_thu_96","textTraditional":"〔三〕　如淳曰：「但欲用意覆之，不近法律事故也。」師古曰：「覆音芳目反。」","sentenceOrder":169},
  {"id":"s_work_han_thu_96_170","chapterId":"ch_work_han_thu_96","textTraditional":"〔四〕　師古曰：「中音竹仲反。」","sentenceOrder":170},
  {"id":"s_work_han_thu_96_171","chapterId":"ch_work_han_thu_96","textTraditional":"久之，遷後將軍，與紅陽侯立相善。立有罪就國，有司奏立黨友，博坐免。後歲餘，哀帝即位，以博名臣，召見，起家復為光祿大夫，遷為京兆尹，數月超為大司空。","sentenceOrder":171},
  {"id":"s_work_han_thu_96_172","chapterId":"ch_work_han_thu_96","textTraditional":"初，漢興襲秦官，置丞相、御史大夫、太尉。至武帝罷太尉，始置大司馬以冠將軍之號，非有印綬官屬也。及成帝時，何武為九卿，建言「古者民樸事約，〔一〕國之輔佐必得賢聖，然猶則天三光，備三公官，各有分職。〔二〕今末俗（文）〔之〕弊，政事煩多，宰相之材不能及古，而丞相獨兼三公之事，所以久廢而不治也。宜建三公官，定卿大夫之任，分職授政，以考功效。」其後上以問師安昌侯張禹，禹以為然。時曲陽侯王根為大司馬票騎將軍，而何武為御史大夫。於是上賜曲陽侯根大司馬印綬，置官屬，罷票騎將軍官，以御史大夫何武為大司空，封列侯，皆增奉如丞相，〔三〕以備三公官焉。議者多以為古今異制，漢自天下之號下至佐史皆不同於古，而獨改三公，職事難分明，無益於治亂。是時御史府吏舍百餘區井水皆竭；又其府中列柏樹，常有野烏數千棲宿其上，晨去暮來，號曰「朝夕烏」，烏去不來者數月，長老異之。〔四〕後二歲餘，朱博為大司空，奏言「帝王之道不必相襲，各繇時務。〔五〕高皇帝以聖德受命，建立鴻業，置御史大夫，位次丞相，典正法度，以職相參，總領百官，上下相監臨，歷載二百年，天下安寧。今更為大司空，與丞相同位，未獲嘉祐。故事，選郡國守相高第為中二千石，選中二千石為御史大夫，任職者為丞相，位次有序，所以尊聖德，重國相也。今中二千石未更御史大夫而為丞相，〔六〕權輕，非所以重國政也。臣愚以為大司空官可罷，復置御史大夫，遵奉舊制。臣願盡力，以御史大夫為百僚率。」哀帝從之，乃更拜博為御史大夫。會大司馬喜免，以陽安侯丁明為大司馬衛將軍，置官屬，大司馬冠號如故事。後四歲，哀帝遂改丞相為大司徒，復置大司空、大司馬焉。","sentenceOrder":172},
  {"id":"s_work_han_thu_96_173","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「立此議而奏之也。約，少也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_96_174","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「則，法也。三光，日、月、星也。分音扶問反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_96_175","chapterId":"ch_work_han_thu_96","textTraditional":"〔三〕　師古曰：「奉音扶用反。」","sentenceOrder":175},
  {"id":"s_work_han_thu_96_176","chapterId":"ch_work_han_thu_96","textTraditional":"〔四〕　師古曰：「史言此者，著御史大夫之職當休廢也。」","sentenceOrder":176},
  {"id":"s_work_han_thu_96_177","chapterId":"ch_work_han_thu_96","textTraditional":"〔五〕　師古曰：「繇讀與由同。」","sentenceOrder":177},
  {"id":"s_work_han_thu_96_178","chapterId":"ch_work_han_thu_96","textTraditional":"〔六〕　師古曰：「更，經也，音工衡反。」","sentenceOrder":178},
  {"id":"s_work_han_thu_96_179","chapterId":"ch_work_han_thu_96","textTraditional":"初，何武為大司空，又與丞相方進共奏言：「古選諸侯賢者以為州伯，書曰『咨十有二牧』，〔一〕所以廣聰明，燭幽隱也。今部刺史居牧伯之位，秉一州之統，選第大吏，所薦位高至九卿，所惡立退，任重職大。春秋之義，用貴治賤，不以卑臨尊。刺史位下大夫，而臨二千石，輕重不相準，失位次之序。臣請罷刺史，更置州牧，以應古制。」奏可，及博奏復御史大夫官，又奏言：「漢家至德溥大，宇內萬里，〔二〕立置郡縣。部刺史奉使典州，督察郡國吏民安寧，故事居部九歲舉為守相，其有異材功效著者輒登擢，秩卑而賞厚，咸勸功樂進。〔三〕前丞相方進奏罷刺史，更置州牧，秩真二千石，位次九卿。九卿缺，以高弟補，其中材則苟自守而已，恐功效陵夷，〔四〕姦軌不禁。臣請罷州牧，置刺史如故。」奏可。","sentenceOrder":179},
  {"id":"s_work_han_thu_96_180","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「虞書舜典之辭也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_96_181","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「溥與普同。」","sentenceOrder":181},
  {"id":"s_work_han_thu_96_182","chapterId":"ch_work_han_thu_96","textTraditional":"〔三〕　師古曰：「勸功，自勸勉而立功也。」","sentenceOrder":182},
  {"id":"s_work_han_thu_96_183","chapterId":"ch_work_han_thu_96","textTraditional":"〔四〕　師古曰：「陵夷，漸廢替。」","sentenceOrder":183},
  {"id":"s_work_han_thu_96_184","chapterId":"ch_work_han_thu_96","textTraditional":"博為人廉儉，不好酒色游宴。自微賤至富貴，食不重味，案上不過三桮。夜寑早起，妻希見其面。有一女，無男。然好樂士大夫，為郡守九卿，賓客滿門，欲仕宦者薦舉之，欲報仇怨者解劍以帶之。其趨事待士如是，博以此自立，然終用敗。","sentenceOrder":184},
  {"id":"s_work_han_thu_96_185","chapterId":"ch_work_han_thu_96","textTraditional":"初，哀帝祖母定陶太后欲求稱尊號，太后從弟高武侯傅喜為大司馬，與丞相孔光、大司空師丹共持正議。孔鄉侯傅晏亦太后從弟，諂諛欲順指，會博新徵用為京兆尹，與交結，謀成尊號，以廣孝道。繇是師丹先免，〔一〕博代為大司空，數燕見奏封事，言「丞相光志在自守，不能憂國；大司馬喜至尊至親，阿黨大臣，無益政治。」上遂罷喜遣就國，免光為庶人，以博代光為丞相，封陽鄉侯，食邑二千戶。博上書讓曰：「故事封丞相不滿千戶，而獨臣過制，誠慚懼，願還千戶。」上許焉。傅太后怨傅喜不已，使孔鄉侯晏風丞相，令奏免喜侯。〔二〕博受詔，與御史大夫趙玄議，玄言「事已前決，得無不宜？」〔三〕博曰：「已許孔鄉侯有指。匹夫相要，尚相得死，何況至尊？博唯有死耳！」玄即許可。博惡獨斥奏喜，以故大司空氾鄉侯何武前亦坐過免就國，〔四〕事與喜相似，即并奏：「喜、武前在位，皆無益於治，雖已退免，爵土之封非所當得也。請皆免為庶人。」上知傅太后素常怨喜，疑博、玄承指，即召玄詣尚書問狀。玄辭服，有詔左將軍彭宣與中朝者雜問。宣等劾奏：「博宰相，玄上卿，晏以外親封位特進，股肱大臣，上所信任，不思竭誠奉公，務廣恩化，為百寮先，皆知喜、武前已蒙恩詔決，事更三赦，〔五〕博執左道，虧損上恩，以結信貴戚，背君鄉臣，〔六〕傾亂政治，姦人之雄，附下罔上，為臣不忠不道；玄知博所言非法，枉義附從，大不敬；晏與博議免喜，失禮不敬。臣請詔謁者召博、玄、晏詣廷尉詔獄。」制曰：「將軍、中二千石、二千石、諸大夫、博士、議郎議。」右將軍蟜望等四十四人〔七〕以為「如宣等言，可許。」諫大夫龔勝等十四人以為「春秋之義，姦以事君，常刑不舍。〔八〕魯大夫叔孫僑如欲顓公室，譖其族兄季孫行父於晉，晉執囚行父以亂魯國，春秋重而書之〔九〕。今晏放命圮族，干亂朝政，要大臣以罔上，本造計謀，職為亂階，〔一０〕宜與博、玄同罪，罪皆不道。」上減玄死罪三等，削晏戶四分之一，假謁者節召丞相詣廷尉詔獄。博自殺，國除。","sentenceOrder":185},
  {"id":"s_work_han_thu_96_186","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「繇讀與由同。」","sentenceOrder":186},
  {"id":"s_work_han_thu_96_187","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「風讀曰諷。」","sentenceOrder":187},
  {"id":"s_work_han_thu_96_188","chapterId":"ch_work_han_thu_96","textTraditional":"〔三〕　師古曰：「得無猶言無乃也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_96_189","chapterId":"ch_work_han_thu_96","textTraditional":"〔四〕　師古曰：「氾音凡。」","sentenceOrder":189},
  {"id":"s_work_han_thu_96_190","chapterId":"ch_work_han_thu_96","textTraditional":"〔五〕　師古曰：「詔已罷官，事又經三赦也。更音工衡反。」","sentenceOrder":190},
  {"id":"s_work_han_thu_96_191","chapterId":"ch_work_han_thu_96","textTraditional":"〔六〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":191},
  {"id":"s_work_han_thu_96_192","chapterId":"ch_work_han_thu_96","textTraditional":"〔七〕　師古曰：「蟜音矯。」","sentenceOrder":192},
  {"id":"s_work_han_thu_96_193","chapterId":"ch_work_han_thu_96","textTraditional":"〔八〕　師古曰：「舍，置也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_96_194","chapterId":"ch_work_han_thu_96","textTraditional":"〔九〕　師古曰：「僑如，叔孫宣伯也。行父，季文子也。宣伯通於成公之母穆姜，欲去季孟而取其室，使告晉曰：『魯之有季孟，猶晉之有欒范也，政令於是乎成。今其謀曰晉政多門，不可從也。若欲得志於魯，請止行父而殺之。不然，歸必畔矣。』晉人執文子于苕丘。事在成十六年。」","sentenceOrder":194},
  {"id":"s_work_han_thu_96_195","chapterId":"ch_work_han_thu_96","textTraditional":"〔一０〕師古曰：「此引詩小雅巧言之章也。職，主也。階者，基之漸也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_96_196","chapterId":"ch_work_han_thu_96","textTraditional":"初博以御史為丞相，封陽鄉侯，玄以少府為御史大夫，並拜於前殿，延登受策，有音如鍾聲。語在五行志。","sentenceOrder":196},
  {"id":"s_work_han_thu_96_197","chapterId":"ch_work_han_thu_96","textTraditional":"贊曰：薛宣、朱博皆起佐史，歷位以登宰相。宣所在而治，為世吏師，及居大位，以苛察失名，〔一〕器誠有極也。博馳騁進取，不思道德，已亡可言，〔二〕又見孝成之世委任大臣，假借用權。〔三〕世主已更，好惡異前，〔四〕復附丁、傅，稱順孔鄉。〔五〕事發見詰，遂陷誣罔，辭窮情得，仰藥飲鴆。〔六〕孔子曰：「久矣哉，由之行詐也！」博亦然哉！〔七〕","sentenceOrder":197},
  {"id":"s_work_han_thu_96_198","chapterId":"ch_work_han_thu_96","textTraditional":"〔一〕　師古曰：「苛，（副）〔細〕也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_96_199","chapterId":"ch_work_han_thu_96","textTraditional":"〔二〕　師古曰：「言其事行不足可道也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_96_200","chapterId":"ch_work_han_thu_96","textTraditional":"〔三〕　鄧展曰：「假音休假。借音以物借人。」","sentenceOrder":200},
  {"id":"s_work_han_thu_96_201","chapterId":"ch_work_han_thu_96","textTraditional":"〔四〕　師古曰：「更，改也。」","sentenceOrder":201},
  {"id":"s_work_han_thu_96_202","chapterId":"ch_work_han_thu_96","textTraditional":"〔五〕　師古曰：「稱，副也。副其所求而順其意也。稱音尺孕反。」","sentenceOrder":202},
  {"id":"s_work_han_thu_96_203","chapterId":"ch_work_han_thu_96","textTraditional":"〔六〕　師古曰：「仰藥謂仰頭而飲藥也。」","sentenceOrder":203},
  {"id":"s_work_han_thu_96_204","chapterId":"ch_work_han_thu_96","textTraditional":"〔七〕　師古曰：「論語云子疾病，子路欲使門人為臣。子曰：『久矣哉，由之行詐也！無臣而為有臣，吾誰欺？欺天乎？』故贊引之。」","sentenceOrder":204},
  {"id":"s_work_han_thu_96_205","chapterId":"ch_work_han_thu_96","textTraditional":"校勘記","sentenceOrder":205},
  {"id":"s_work_han_thu_96_206","chapterId":"ch_work_han_thu_96","textTraditional":"三三八七頁一一行　始高陵令（陽）〔楊〕湛、　景祐、殿本都作「楊」。","sentenceOrder":206},
  {"id":"s_work_han_thu_96_207","chapterId":"ch_work_han_thu_96","textTraditional":"三三九二頁　九行　大雅（蒸人）〔烝民〕之詩，　殿本作「烝民」，景祐本作「烝人」。","sentenceOrder":207},
  {"id":"s_work_han_thu_96_208","chapterId":"ch_work_han_thu_96","textTraditional":"三三九九頁　四行　徙雲陽、平陵（三）〔二〕縣，　楊樹達說「三」當作「二」，景祐本亦誤。","sentenceOrder":208},
  {"id":"s_work_han_thu_96_209","chapterId":"ch_work_han_thu_96","textTraditional":"三四０二頁一０行　（大）丈夫固時有是。　景祐本無「大」字。王念孫說「大」字後人所加。","sentenceOrder":209},
  {"id":"s_work_han_thu_96_210","chapterId":"ch_work_han_thu_96","textTraditional":"三四０二頁一三行　與筆札（便）〔使〕自記，　景祐、殿本都作「使」。朱一新作「使」是。","sentenceOrder":210},
  {"id":"s_work_han_thu_96_211","chapterId":"ch_work_han_thu_96","textTraditional":"三四０四頁　三行　得〔為〕諸君覆意之。　景祐、殿本都有「為」字，此脫。","sentenceOrder":211},
  {"id":"s_work_han_thu_96_212","chapterId":"ch_work_han_thu_96","textTraditional":"三四０四頁一四行　今末俗（文）〔之〕弊，政事煩多。　景祐、殿本都作「之」。","sentenceOrder":212},
  {"id":"s_work_han_thu_96_213","chapterId":"ch_work_han_thu_96","textTraditional":"三四０九頁一一行　苛，（副）〔細〕也。　景祐、殿本都作「細」，此誤。","sentenceOrder":213},
  {"id":"s_work_han_thu_97_1","chapterId":"ch_work_han_thu_97","textTraditional":"翟方進字子威，汝南上蔡人也。家世微賤，至方進父翟公，好學，為郡文學。方進年十二三，失父孤學，給事太守府為小史，號遲頓不及事，〔一〕數為掾史所詈辱。方進自傷，乃從汝南蔡父相問己能所宜。〔二〕蔡父大奇其形貌，謂曰：「小史有封侯骨，當以經術進，努力為諸生學問。」方進既厭為小史，聞蔡父言，心喜，因病歸家，辭其後母，欲西至京師受經。母憐其幼，隨之長安，織屨以給方進讀，經博士受春秋。積十餘年，經學明習，徒眾日廣，諸儒稱之。以射策甲科為郎。二三歲，舉明經，遷議郎。","sentenceOrder":1},
  {"id":"s_work_han_thu_97_2","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「頓讀曰鈍。」","sentenceOrder":2},
  {"id":"s_work_han_thu_97_3","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「言從何術藝可以自達。」","sentenceOrder":3},
  {"id":"s_work_han_thu_97_4","chapterId":"ch_work_han_thu_97","textTraditional":"是時宿儒有清河胡常，〔一〕與方進同經。常為先進，名譽出方進下，〔二〕心害其能，論議不右方進。〔三〕方進知之，候伺常大都授時，〔四〕遣門下諸生至常所問大義疑難，因記其說。如是者久之，常知方進之宗讓己，〔五〕內不自得，其後居士大夫之間未嘗不稱述方進，遂相親友。","sentenceOrder":4},
  {"id":"s_work_han_thu_97_5","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「宿，久舊也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_97_6","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「常宦學雖在前，而名譽不及方進。」","sentenceOrder":6},
  {"id":"s_work_han_thu_97_7","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「毀短也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_97_8","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「都授，謂總集諸生大講授也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_97_9","chapterId":"ch_work_han_thu_97","textTraditional":"〔五〕　師古曰：「宗，尊也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_97_10","chapterId":"ch_work_han_thu_97","textTraditional":"河平中，方進轉為博士。數年，遷朔方刺史，居官不煩苛，所察應條輒舉，甚有威名。再三奏事，〔一〕遷為丞相司直。從上甘泉，行馳道中，司隸校尉陳慶劾奏方進，沒入車馬。既至甘泉宮，會殿中，慶與廷尉范延壽語，時慶有章劾，自道：「行事以贖論，〔二〕今尚書持我事來，當於此決。前我為尚書時，嘗有所奏事，忽忘之，留月餘。」〔三〕方進於是舉劾慶曰：「案慶奉使刺舉大臣，故為尚書，知機事周密壹統，明主躬親不解。〔四〕慶有罪未伏誅，無恐懼心，豫自設不坐之比。〔五〕又暴揚尚書事，言遲疾無所在，虧損聖德之聰明，奉詔不謹，皆不敬，〔六〕臣謹以劾。」慶坐免官。","sentenceOrder":10},
  {"id":"s_work_han_thu_97_11","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「刺史歲盡輒奏事京師也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_97_12","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「當祭泰畤時，行事有闕失，罪合贖。」","sentenceOrder":12},
  {"id":"s_work_han_thu_97_13","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「言此者，冀尚書忘己之事不奏。」","sentenceOrder":13},
  {"id":"s_work_han_thu_97_14","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「解讀曰懈。」","sentenceOrder":14},
  {"id":"s_work_han_thu_97_15","chapterId":"ch_work_han_thu_97","textTraditional":"〔五〕　師古曰：「比，例也，音必寐反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_97_16","chapterId":"ch_work_han_thu_97","textTraditional":"〔六〕　師古曰：「既自云不坐，又言遲疾無所在，此之二條於法皆為不敬。」","sentenceOrder":16},
  {"id":"s_work_han_thu_97_17","chapterId":"ch_work_han_thu_97","textTraditional":"會北地浩商為義渠長所捕，亡，〔一〕長取其母，與豭豬連繫都亭下。〔二〕商兄弟會賓客，自稱司隸掾、長安縣尉，殺義渠長妻子六人，亡。丞相、御史請遣掾史與司隸校尉、部刺史并力逐捕，察無狀者，〔三〕奏可。司隸校尉涓勳奏言：「春秋之義，王人微者序乎諸侯之上，尊王命也。臣幸得奉使，以督察公卿以下為職，〔四〕今丞相宣請遣掾史，以宰士督察天子奉使命大夫，〔五〕甚誖逆順之理。〔六〕宣本不師受經術，因事以立姦威。案浩商所犯，一家之禍耳，而宣欲專權作威，乃害於乃國，不可之大者。〔七〕願下中朝特進列侯、將軍以下，正國法度。」議者以為丞相掾不宜移書督趣司隸。〔八〕會浩商捕得伏誅，家屬徙合浦。","sentenceOrder":17},
  {"id":"s_work_han_thu_97_18","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「義渠，北地之縣也。商被縣長捕而逃亡。」","sentenceOrder":18},
  {"id":"s_work_han_thu_97_19","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「以深辱之。豭，牡豕也，音家。」","sentenceOrder":19},
  {"id":"s_work_han_thu_97_20","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「無狀，謂商及義渠長本狀之違曲也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_97_21","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「督，視也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_97_22","chapterId":"ch_work_han_thu_97","textTraditional":"〔五〕　師古曰：「謂丞相掾史為宰士者，言其宰相之屬官，而位為士也。奉使命大夫，謂司隸也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_97_23","chapterId":"ch_work_han_thu_97","textTraditional":"〔六〕　師古曰：「誖，乖也，音布內反。」","sentenceOrder":23},
  {"id":"s_work_han_thu_97_24","chapterId":"ch_work_han_thu_97","textTraditional":"〔七〕　師古曰：「周書洪範云『臣之有作福作威，乃凶于乃國，害于厥躬』，故引之。」","sentenceOrder":24},
  {"id":"s_work_han_thu_97_25","chapterId":"ch_work_han_thu_97","textTraditional":"〔八〕　師古曰：「趣讀曰促。」","sentenceOrder":25},
  {"id":"s_work_han_thu_97_26","chapterId":"ch_work_han_thu_97","textTraditional":"故事，司隸校尉位在司直下，初除，謁兩府，〔一〕其有所會，居中二千石前，與司直並迎丞相、御史。初，方進新視事，而涓勳亦初拜為司隸，不肯謁丞相、御史大夫，後朝會相見，禮節又倨。〔二〕方進陰察之，勳私過光祿勳辛慶忌，又出逢帝舅成都侯商道路，下車立，〈須，彡下加立〉過，乃就車。〔三〕於是方進舉奏其狀，因曰：「臣聞國家之興，尊尊而敬長，爵位上下之禮，王道綱紀。〔四〕春秋之義，尊上公謂之宰，海內無不統焉。丞相進見聖主，御坐為起，在輿為下。〔五〕群臣宜皆承順聖化，以視四方。〔六〕勳吏二千石，幸得奉使，不遵禮儀，輕謾宰相，賤易上卿，〔七〕而又詘節失度，邪諂無常，〔八〕色厲內荏。〔九〕墮國體，〔一０〕亂朝廷之序，不宜處位。臣請下丞相免勳。」","sentenceOrder":26},
  {"id":"s_work_han_thu_97_27","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「丞相及御史也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_97_28","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「倨，傲也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_97_29","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「〈須，彡下加立〉，待也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_97_30","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「言王道綱紀以尊卑上下之禮為大也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_97_31","chapterId":"ch_work_han_thu_97","textTraditional":"〔五〕　師古曰：「漢舊儀云皇帝見丞相起，謁者贊稱曰『皇帝為丞相起』。起立乃坐。皇帝在道，丞相迎謁，謁者贊稱曰『皇帝為丞相下輿』。立乃升車。」","sentenceOrder":31},
  {"id":"s_work_han_thu_97_32","chapterId":"ch_work_han_thu_97","textTraditional":"〔六〕　師古曰：「視讀曰示。」","sentenceOrder":32},
  {"id":"s_work_han_thu_97_33","chapterId":"ch_work_han_thu_97","textTraditional":"〔七〕　師古曰：「謾讀與慢同。易音弋豉反。」","sentenceOrder":33},
  {"id":"s_work_han_thu_97_34","chapterId":"ch_work_han_thu_97","textTraditional":"〔八〕　師古曰：「讇，古諂字也。私過辛慶忌，見王商而下車，是邪諂也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_97_35","chapterId":"ch_work_han_thu_97","textTraditional":"〔九〕　應劭曰：「荏，屈橈也。」師古曰：「論語稱孔子曰：『色厲而內荏，譬諸小人，其猶穿窬之盜也與！』言外色莊厲而內懷荏弱，故方進引以為言。」","sentenceOrder":35},
  {"id":"s_work_han_thu_97_36","chapterId":"ch_work_han_thu_97","textTraditional":"〔一０〕師古曰：「墮，毀也，音火規反。」","sentenceOrder":36},
  {"id":"s_work_han_thu_97_37","chapterId":"ch_work_han_thu_97","textTraditional":"時太中大夫平當給事中，奏言「方進國之司直，不自敕正以先群下，前親犯令行馳道中，司隸慶平心舉劾，方進不自責悔而內挾私恨，伺記慶之從容語言，〔一〕以詆欺成罪。〔二〕後丞相宣以一不道賊，〔三〕請遣掾督趣司隸校尉，司隸校尉勳自奏暴於朝廷，今方進復舉奏勳。議者以為方進不以道德輔正丞相，苟阿助大臣，欲必勝立威，〔四〕宜抑絕其原。勳素行公直，姦人所惡，可少寬假，使遂其功名。」上以方進所舉應科，不得用逆詐廢正法，〔五〕遂貶勳為昌陵令。方進旬歲間免兩司隸，〔六〕朝廷由是憚之。丞相宣甚器重焉，常誡掾史：「謹事司直，翟君必在相位，不久。」","sentenceOrder":37},
  {"id":"s_work_han_thu_97_38","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「從音七容反。」","sentenceOrder":38},
  {"id":"s_work_han_thu_97_39","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「詆，毀也，音丁禮反。」","sentenceOrder":39},
  {"id":"s_work_han_thu_97_40","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　如淳曰：「律，殺不辜一家三人為不道。」","sentenceOrder":40},
  {"id":"s_work_han_thu_97_41","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「必勝，必取勝。」","sentenceOrder":41},
  {"id":"s_work_han_thu_97_42","chapterId":"ch_work_han_thu_97","textTraditional":"〔五〕　師古曰：「逆詐者，謂以詐意逆猜人也。逆，迎也。論語（曰子）〔子曰〕『不逆詐』。」","sentenceOrder":42},
  {"id":"s_work_han_thu_97_43","chapterId":"ch_work_han_thu_97","textTraditional":"〔六〕　師古曰：「旬，遍也，滿也。旬歲猶言滿歲也，若十日之一周。」","sentenceOrder":43},
  {"id":"s_work_han_thu_97_44","chapterId":"ch_work_han_thu_97","textTraditional":"是時起昌陵，營作陵邑，貴戚近臣子弟賓客多辜榷為姦利者〔一〕，方進部掾史覆案，發大姦贓數千萬。上以為任公卿，〔二〕欲試以治民，徙方進為京兆尹，（博）〔搏〕擊豪彊，京師畏之。時胡常為青州刺史，聞之，與方進書曰：「竊聞政令甚明，為京兆能，則恐有所不宜。」〔三〕方進心知所謂，其後少弛威嚴。〔四〕","sentenceOrder":44},
  {"id":"s_work_han_thu_97_45","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「榷，專也。辜榷者，言己自專之，它人取者輒有辜罪。」","sentenceOrder":45},
  {"id":"s_work_han_thu_97_46","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「任，堪也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_97_47","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「言當犯迕貴戚而見毀。」","sentenceOrder":47},
  {"id":"s_work_han_thu_97_48","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「弛，解也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_97_49","chapterId":"ch_work_han_thu_97","textTraditional":"居官三歲，永始二年遷御史大夫。數月，會丞相薛宣坐廣漢盜賊群起及太皇太后喪時三輔吏並徵發為姦，〔一〕免為庶人。方進亦坐為京兆尹時奉喪事煩擾百姓，左遷執金吾。二十餘日，丞相官缺，群臣多舉方進，上亦器其能，遂擢方進為丞相，封高陵侯，食邑千戶。身既富貴，而後母尚在，方進內行修飾，供養甚篤。〔二〕及後母終，既葬三十六日，除服起視事，以為身備漢相，不敢踰國家之制〔三〕。為相公絜，請託不行郡國。〔四〕持法刻深，舉奏牧守九卿，峻文深詆，〔五〕中傷者尤多。如陳咸、朱博、蕭育、逢信、孫閎之屬，皆京師世家，以材能少歷牧守列卿，知名當世，而方進特立後起，十餘年間至宰相，據法以彈咸等，皆罷退之。","sentenceOrder":49},
  {"id":"s_work_han_thu_97_50","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「並音步浪反。」","sentenceOrder":50},
  {"id":"s_work_han_thu_97_51","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「飾，謹也。篤，厚也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_97_52","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「漢制自文帝遺詔之後，國家遵以為常。大功十五日，小功十四日，緦麻七日。方進自以大臣，故云不敢踰制。」","sentenceOrder":52},
  {"id":"s_work_han_thu_97_53","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「言不以私事託於四方郡國。」","sentenceOrder":53},
  {"id":"s_work_han_thu_97_54","chapterId":"ch_work_han_thu_97","textTraditional":"〔五〕　師古曰：「詆，毀也，音丁禮反。」","sentenceOrder":54},
  {"id":"s_work_han_thu_97_55","chapterId":"ch_work_han_thu_97","textTraditional":"初咸最先進，自元帝初為御史中丞顯名朝廷矣。成帝初即位，擢為部刺史，歷楚國、北海、東郡太守。陽朔中，京兆尹王章譏切大臣，而薦琅邪太守馮野王可代大將軍王鳳輔政，東郡太守陳咸可御史大夫。是時方進甫從博士為刺史云。〔一〕後方進為京兆尹，咸從南陽太守入為少府，與方進厚善。先是逢信已從高弟郡守歷京兆、太僕為衛尉矣，官簿皆在方進之右。〔二〕及御史大夫缺，三人皆名卿，俱在選中，而方進得之。會丞相宣有事與方進相連，上使五二千石雜問丞相、御史，〔三〕咸詰責方進，冀得其處，方進心恨。初大將軍鳳奏除陳湯為中郎，與從事。〔四〕鳳薨後，從弟車騎將軍音代鳳輔政，亦厚湯。逢信、陳咸皆與湯善，湯數稱之於鳳、音所。久之，音薨，鳳弟成都侯商復為大司馬衛將軍輔政。商素憎陳湯，白其罪過，下有司案驗，遂免湯，徙敦煌。時方進新為丞相，陳咸內懼不安，乃令小冠杜子夏往觀其意，微自解說。〔五〕子夏既過方進，揣知其指，不敢發言。〔六〕居亡何，〔七〕方進奏咸與逢信「邪枉貪汙，營私多欲。皆知陳湯姦佞傾覆，利口不軌，而親交賂遺，以求薦舉。後為少府，數饋遺湯。信、咸幸得備九卿，不思盡忠正身，內自知行辟亡功效，〔八〕而官媚邪臣，欲以徼幸，苟得亡恥。孔子曰：『鄙夫可與事君也與哉！』〔九〕咸、信之謂也。過惡暴見，不宜處位，臣請免以示天下。」奏可。","sentenceOrder":55},
  {"id":"s_work_han_thu_97_56","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「甫，始也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_97_57","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「簿謂伐閱也。簿音主簿之簿。」","sentenceOrder":57},
  {"id":"s_work_han_thu_97_58","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　晉灼曰：「大臣獄重，故以秩二千石五人詰責之。」","sentenceOrder":58},
  {"id":"s_work_han_thu_97_59","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「每有政事皆與謀之而行也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_97_60","chapterId":"ch_work_han_thu_97","textTraditional":"〔五〕　師古曰：「解說猶今言分疏。」","sentenceOrder":60},
  {"id":"s_work_han_thu_97_61","chapterId":"ch_work_han_thu_97","textTraditional":"〔六〕　師古曰：「揣謂探求之，音初委反。」","sentenceOrder":61},
  {"id":"s_work_han_thu_97_62","chapterId":"ch_work_han_thu_97","textTraditional":"〔七〕　師古曰：「無何猶言無幾，謂少時。」","sentenceOrder":62},
  {"id":"s_work_han_thu_97_63","chapterId":"ch_work_han_thu_97","textTraditional":"〔八〕　師古曰：「辟讀曰僻。」","sentenceOrder":63},
  {"id":"s_work_han_thu_97_64","chapterId":"ch_work_han_thu_97","textTraditional":"〔九〕　師古曰：「論語載孔子之言也，謂鄙夫不可與事君也。與哉，與讀曰歟。」","sentenceOrder":64},
  {"id":"s_work_han_thu_97_65","chapterId":"ch_work_han_thu_97","textTraditional":"後二歲餘，詔舉方正直言之士，紅陽侯立舉咸對策，拜為光祿大夫給事中。方進復奏：「咸前為九卿，坐為貪邪免，自知罪惡暴陳，依託紅陽侯立徼幸，有司莫敢舉奏。冒濁苟容，〔一〕不顧恥辱，不當蒙方正舉，備內朝臣。」并劾紅陽侯立選舉故不以實。有詔免咸，勿劾立。","sentenceOrder":65},
  {"id":"s_work_han_thu_97_66","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「冒，貪蔽也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_97_67","chapterId":"ch_work_han_thu_97","textTraditional":"後數年，皇太后姊子侍中衛尉定陵侯淳于長有罪，上以太后故，免官勿治罪。有司奏請遣長就國，長以金錢與立，立上封事為長求留曰：「陛下既託文以皇太后故，〔一〕誠不可更有它計。」〔二〕後長陰事發，遂下獄。方進劾立「懷姦邪，亂朝政，欲傾誤要主上，狡猾不道，請下獄。」上曰：「紅陽侯，朕之舅，不忍致法，遣就國。」於是方進復奏立黨友曰：「立素行積為不善，眾人所共知。邪臣自結，附託為黨，庶幾立與政事，欲獲其利。〔三〕今立斥逐就國，所交結尤著者，不宜備大臣，為郡守。案後將軍朱博、鉅鹿太守孫閎、故光祿大夫陳咸與立交通厚善，相與為腹心，有背公死黨之信，〔四〕欲相攀援，死而後已；〔五〕皆內有不仁之性，而外有雋材，過絕（於）人〔倫〕，勇猛果敢，處事不疑，所居皆尚殘賊酷虐，苛刻慘毒以立威，而亡纖介愛利之風。〔六〕天下所共知，愚者猶惑。孔子曰：『人而不仁如禮何！人而不仁如樂何！』〔七〕言不仁之人，亡所施用；不仁而多材，國之患也。此三人皆內懷姦猾，國之所患，而深相與結，信於貴戚姦臣，此國家大憂，大臣所宜沒身而爭也。〔八〕昔季孫行父有言曰：『見有善於君者愛之，若孝子之養父母也；見不善者誅之，若鷹鸇之逐鳥爵也。』〔九〕翅翼雖傷，不避也。貴戚彊黨之眾誠難犯，犯之，眾敵並怨，善惡相冒。〔一０〕臣幸得備宰相，不敢不盡死。請免博、閎、咸歸故郡，以銷姦雄之黨，絕群邪之望。」奏可。咸既廢錮，復徙故郡，以憂發疾而死。","sentenceOrder":67},
  {"id":"s_work_han_thu_97_68","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　蘇林曰：「託於詔文也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_97_69","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「言不宜遣長就國。」","sentenceOrder":69},
  {"id":"s_work_han_thu_97_70","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「與讀曰豫。」","sentenceOrder":70},
  {"id":"s_work_han_thu_97_71","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「死黨，盡死力於朋黨也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_97_72","chapterId":"ch_work_han_thu_97","textTraditional":"〔五〕　師古曰：「援，引也。已，止也。援音爰。」","sentenceOrder":72},
  {"id":"s_work_han_thu_97_73","chapterId":"ch_work_han_thu_97","textTraditional":"〔六〕　師古曰：「愛利，謂仁愛而欲安利人也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_97_74","chapterId":"ch_work_han_thu_97","textTraditional":"〔七〕　師古曰：「論語載孔子之言也。言用不仁之人，則禮樂廢壞。」","sentenceOrder":74},
  {"id":"s_work_han_thu_97_75","chapterId":"ch_work_han_thu_97","textTraditional":"〔八〕　師古曰：「沒，盡也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_97_76","chapterId":"ch_work_han_thu_97","textTraditional":"〔九〕　師古曰：「事見左氏傳。行父，魯卿季文子也。鸇似鷂而小，今謂之鸇。鸇音之然反。」","sentenceOrder":76},
  {"id":"s_work_han_thu_97_77","chapterId":"ch_work_han_thu_97","textTraditional":"〔一０〕師古曰：「冒，覆蔽也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_97_78","chapterId":"ch_work_han_thu_97","textTraditional":"方進知能有餘，兼通文法吏事，以儒雅緣飭法律，號為通明相，天子甚器重之，奏事亡不當意，內求人主微指以固其位。初，定陵侯淳于長雖外戚，然以能謀議為九卿，新用事，方進獨與長交，稱薦之。及長坐大逆誅，諸所厚善皆坐長免，上以方進大臣，又素重之，為隱諱。方進內慚，上疏謝罪乞骸骨。上報曰：「定陵侯長已伏其辜，君雖交通，傳不云乎，朝過夕改，君子與之，〔一〕君何疑焉？其專心壹意毋怠，近醫藥以自持。」方進乃起視事，條奏長所厚善京兆尹孫寶、右扶風蕭育，刺史二千石以上免二十餘人，其見任如此。","sentenceOrder":78},
  {"id":"s_work_han_thu_97_79","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「與，許也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_97_80","chapterId":"ch_work_han_thu_97","textTraditional":"方進雖受穀梁，然好左氏傳、天文星曆，其左氏則國師劉歆，星曆則長安令田終術師也。〔一〕厚李尋，以為議曹。為相九歲，綏和二年春熒惑守心，尋奏記言：「應變之權，君侯所自明。往者數白，三光垂象，變動見端，〔二〕山川水泉，反理視患，〔三〕民人訛謠，斥事感名。〔四〕三者既效，可為寒心。今提揚眉，矢貫中，〔五〕狼奮角，弓且張，〔六〕金歷庫，土逆度，〔七〕輔湛沒，火守舍，〔八〕萬歲之期，近慎朝暮。〔九〕上無惻怛濟世之功，下無推讓避賢之效，欲當大位，為具臣以全身，難矣！〔一０〕大責日加，安得但保斥逐之戮？〔一一〕闔府三百餘人，唯君侯擇其中，與盡節轉凶。」〔一二〕","sentenceOrder":80},
  {"id":"s_work_han_thu_97_81","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　如淳曰：「劉歆及田終術二人皆受學於方進。」","sentenceOrder":81},
  {"id":"s_work_han_thu_97_82","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　張晏曰：「九年之中而日三食，月朓側匿，星孛營室、東井，熒惑守心。」","sentenceOrder":82},
  {"id":"s_work_han_thu_97_83","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　張晏曰：「元延中，瑉山崩，壅江，江水不流。山地之鎮，宜固而崩。水逆流，反於常理，所以示人患也。」師古曰：「視讀曰示。」","sentenceOrder":83},
  {"id":"s_work_han_thu_97_84","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　如淳曰：「斥事，井水溢之事也。有言溢者，後果井溢。感名，『燕燕尾涎涎』是也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_97_85","chapterId":"ch_work_han_thu_97","textTraditional":"〔五〕　服虔曰：「提，攝提星也。揚眉，揚其芒角也。矢，枉矢也。」孟康曰：「綏和元年正月，枉矢從東南入北斗攝提與北斗杓建寅貫攝提中是也。」張晏曰：「矢一星。貫中者，謂正直弧中也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_97_86","chapterId":"ch_work_han_thu_97","textTraditional":"〔六〕　張晏曰：「狼，一星。奮角者，有芒角也。狼芒角則盜賊起。天弓九星不欲明，明猶張也，兵起之象。」","sentenceOrder":86},
  {"id":"s_work_han_thu_97_87","chapterId":"ch_work_han_thu_97","textTraditional":"〔七〕　張晏曰：「庫二十星在軫南。金，太白也，歷武庫則兵起。土，鎮星也。逆度，逆行也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_97_88","chapterId":"ch_work_han_thu_97","textTraditional":"〔八〕　張晏曰：「北斗第四星旁一小星曰輔，沈沒不見，則天下之兵銷。三十日為守舍，謂日月所經宿舍也。一曰火守舍，熒惑守心。」師古曰：「湛讀曰沈。」","sentenceOrder":88},
  {"id":"s_work_han_thu_97_89","chapterId":"ch_work_han_thu_97","textTraditional":"〔九〕　師古曰：「萬歲之期，謂死也。慎朝暮者，言其事在朝夕。」","sentenceOrder":89},
  {"id":"s_work_han_thu_97_90","chapterId":"ch_work_han_thu_97","textTraditional":"〔一０〕師古曰：「具謂，具位之臣，無功德也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_97_91","chapterId":"ch_work_han_thu_97","textTraditional":"〔一一〕師古曰：「言其事重，不但斥逐而已也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_97_92","chapterId":"ch_work_han_thu_97","textTraditional":"〔一二〕師古曰：「三百餘人，謂丞相之官屬也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_97_93","chapterId":"ch_work_han_thu_97","textTraditional":"方進憂之，不知所出。會郎賁麗善為星，〔一〕言大臣宜當之。上乃召見方進。還歸，未及引決，上遂賜冊曰：「皇帝問丞相：君有孔子之慮，孟賁之勇，朕嘉與君同心一意，庶幾有成。惟君登位，於今十年，災害並臻，民被飢餓，加以疾疫溺死，關門牡開，〔二〕失國守備，盜賊黨輩。〔三〕吏民殘賊，毆殺良民，〔四〕斷獄歲歲多前。上書言事，交錯道路，懷姦朋黨，相為隱蔽，皆亡忠慮，群下兇兇，更相嫉妒，〔五〕其咎安在？觀君之治，無欲輔朕富民便安元元之念。間者郡國穀雖頗孰，〔六〕百姓不足者尚眾，前去城郭，未能盡還，夙夜未嘗忘焉。朕惟往時之用，與今一也，〔七〕百僚用度各有數。君不量多少，一聽群下言，用度不足，奏請一切增賦，稅城郭堧及園田，過更，算馬牛羊，〔八〕增益鹽鐵，變更無常。朕既不明，隨奏許可，（使）〔後〕議者以為不便，制詔下君，君云賣酒醪。後請止，未盡月復奏議令賣酒醪。朕誠怪君，何持容容之計，無忠固意，〔九〕將何以輔朕帥道群下？而欲久蒙顯尊之位，豈不難哉〔一０〕！傳曰：『高而不危，所以長守貴也。』〔一一〕欲退君位，尚未忍。君其孰念詳計，塞絕姦原，憂國如家，務便百姓以輔朕。朕既已改，君其自思，強食慎職。使尚書令賜君上尊酒十石，養牛一，君審處焉。」","sentenceOrder":93},
  {"id":"s_work_han_thu_97_94","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「賁，姓也。麗，名也。賁音肥。」","sentenceOrder":94},
  {"id":"s_work_han_thu_97_95","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　張晏曰：「元延元年，章門、函谷門牡自亡。」","sentenceOrder":95},
  {"id":"s_work_han_thu_97_96","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「黨眾多。」","sentenceOrder":96},
  {"id":"s_work_han_thu_97_97","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「毆，擊也，音一口反。」","sentenceOrder":97},
  {"id":"s_work_han_thu_97_98","chapterId":"ch_work_han_thu_97","textTraditional":"〔五〕　師古曰：「更音工衡反。」","sentenceOrder":98},
  {"id":"s_work_han_thu_97_99","chapterId":"ch_work_han_thu_97","textTraditional":"〔六〕　師古曰：「間謂近者以來也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_97_100","chapterId":"ch_work_han_thu_97","textTraditional":"〔七〕　師古曰：「謂財用也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_97_101","chapterId":"ch_work_han_thu_97","textTraditional":"〔八〕　張晏曰：「一切，權時也。堧，城郭旁地。園田入多，益其稅也。百人為卒，取一人所贍常為之月用二千，使人直之，謂之過更。又牛馬羊頭數出稅，算千輸二十也。」師古曰：「堧音人緣反，解在食貨志。」","sentenceOrder":101},
  {"id":"s_work_han_thu_97_102","chapterId":"ch_work_han_thu_97","textTraditional":"〔九〕　師古曰：「容容，隨眾上下也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_97_103","chapterId":"ch_work_han_thu_97","textTraditional":"〔一０〕師古曰：「蒙，冒也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_97_104","chapterId":"ch_work_han_thu_97","textTraditional":"〔一一〕師古曰：「孝經之言也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_97_105","chapterId":"ch_work_han_thu_97","textTraditional":"方進即日自殺。〔一〕上祕之，遣九卿冊贈以丞相高陵侯印綬，賜乘輿祕器，少府供張，柱檻皆衣素。〔二〕天子親臨弔者數至，禮賜異於它相故事。〔三〕諡曰恭侯。長子宣嗣。","sentenceOrder":105},
  {"id":"s_work_han_thu_97_106","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　如淳曰：「漢儀注有天地大變，天下大過，皇帝使侍中持節乘四白馬，賜上尊酒十斛，牛一頭，策告殃咎。使者去半道，丞相即上病。使者還，未白事，尚書以丞相不起病聞。」","sentenceOrder":106},
  {"id":"s_work_han_thu_97_107","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「柱，屋柱也。檻，軒前闌版也。皆以白素衣之。」","sentenceOrder":107},
  {"id":"s_work_han_thu_97_108","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「漢舊儀云丞相有疾，皇帝法駕親至問疾，從西門入。即薨，移居第中，車駕往弔，贈棺、棺斂具，賜錢、葬地。葬日，公卿已下會葬焉。」","sentenceOrder":108},
  {"id":"s_work_han_thu_97_109","chapterId":"ch_work_han_thu_97","textTraditional":"宣字太伯，亦明經篤行，君子人也。及方進在，為關都尉、南郡太守。〔一〕","sentenceOrder":109},
  {"id":"s_work_han_thu_97_110","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「言方進未死之時宣已為此官。」","sentenceOrder":110},
  {"id":"s_work_han_thu_97_111","chapterId":"ch_work_han_thu_97","textTraditional":"少子曰義。義字文仲，少以父任為郎，稍遷諸曹，年二十出為南陽都尉。宛令劉立與曲陽侯為婚，又素著名州郡，輕義年少。義行太守事，行縣至宛，〔一〕丞相史在傳舍。立持酒肴謁丞相史，對飲未訖，會義亦往，外吏白都尉方至，立語言自若。〔二〕須臾義至，內謁徑入，〔三〕立乃走下。義既還，大怒，陽以他事召立至，以主守盜十金，賊殺不辜，部掾夏恢等收縛立，傳送鄧獄。〔四〕恢亦以宛大縣，恐見篡奪，白義可因隨後行縣送鄧。〔五〕義曰：「欲令都尉自送，則如勿收邪！」〔六〕載環宛市乃送，〔七〕吏民不敢動，威震南陽。","sentenceOrder":111},
  {"id":"s_work_han_thu_97_112","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「行音下更反。其下並同。」","sentenceOrder":112},
  {"id":"s_work_han_thu_97_113","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「自若，言如故。」","sentenceOrder":113},
  {"id":"s_work_han_thu_97_114","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「內謁，猶今之通名也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_97_115","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「部分其掾而遣之。鄧亦南陽之縣。」","sentenceOrder":115},
  {"id":"s_work_han_thu_97_116","chapterId":"ch_work_han_thu_97","textTraditional":"〔五〕　師古曰：「因太守行縣，以立自隨，即送鄧之獄。」","sentenceOrder":116},
  {"id":"s_work_han_thu_97_117","chapterId":"ch_work_han_thu_97","textTraditional":"〔六〕　師古曰：「言若都尉自送至獄，不如本不收治。」","sentenceOrder":117},
  {"id":"s_work_han_thu_97_118","chapterId":"ch_work_han_thu_97","textTraditional":"〔七〕　師古曰：「環，繞也，音下串反。」","sentenceOrder":118},
  {"id":"s_work_han_thu_97_119","chapterId":"ch_work_han_thu_97","textTraditional":"立家輕騎馳從武關入語曲陽侯，曲陽侯白成帝，帝以問丞相。方進遣吏敕義出宛令。宛令已出，吏還白狀。方進曰：「小兒未知為吏也，其意以為入獄當輒死矣。」〔一〕","sentenceOrder":119},
  {"id":"s_work_han_thu_97_120","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「謂其不知立有所恃挾以自免脫。」","sentenceOrder":120},
  {"id":"s_work_han_thu_97_121","chapterId":"ch_work_han_thu_97","textTraditional":"後義坐法免，起家而為弘農太守，遷河（南）〔內〕太守，青州牧。所居著名，有父風烈。徙為東郡太守。","sentenceOrder":121},
  {"id":"s_work_han_thu_97_122","chapterId":"ch_work_han_thu_97","textTraditional":"數歲，平帝崩，王莽居攝，義心惡之，乃謂姊子上蔡陳豐曰：「新都侯攝天子位，號令天下，故擇宗室幼稚者以為孺子，依託周公輔成王之義，且以觀望，〔一〕必代漢家，其漸可見。方今宗室衰弱，外無彊蕃，天下傾首服從，莫能亢扞國難。吾幸得備宰相子，身守大郡，父子受漢厚恩，義當為國討賊，以安社稷。欲舉兵西誅不當攝者，選宗室子孫輔而立之。設令時命不成，死國埋名，猶可以不慚於先帝。〔二〕今欲發之，乃肯從我乎？」〔三〕豐年十八，勇壯，許諾。","sentenceOrder":122},
  {"id":"s_work_han_thu_97_123","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「言漸試天下人心。」","sentenceOrder":123},
  {"id":"s_work_han_thu_97_124","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「埋名，謂身埋而名立。」","sentenceOrder":124},
  {"id":"s_work_han_thu_97_125","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「乃，汝也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_97_126","chapterId":"ch_work_han_thu_97","textTraditional":"義遂與東郡都尉劉宇、嚴鄉侯劉信、信弟武平侯劉璜結謀。及東郡王孫慶素有勇略，以明兵法，徵在京師，義乃詐移書以重罪傳逮慶。〔一〕於是以九月都試日〔二〕斬觀令，〔三〕因勒其車騎材官士，募郡中勇敢，部署將帥。嚴鄉侯信者，東平王雲子也。雲誅死，信兄開明嗣為王，薨，無子，而信子匡復立為王，故義舉兵并東平，立信為天子。義自號大司馬柱天大將軍，以東平王傅蘇隆為丞相，中尉皋丹為御史大夫，移檄郡國，言莽鴆殺孝平皇帝，矯攝尊號，今天子已立，共行天罰。〔四〕郡國皆震，比至山陽，眾十餘萬。〔五〕","sentenceOrder":126},
  {"id":"s_work_han_thu_97_127","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「追赴獄也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_97_128","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　如淳曰：「太守、都尉、令長、丞尉會都試，課殿最也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_97_129","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　文穎曰：「觀，縣名。」師古曰：「音工喚反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_97_130","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「共讀曰恭。」","sentenceOrder":130},
  {"id":"s_work_han_thu_97_131","chapterId":"ch_work_han_thu_97","textTraditional":"〔五〕　師古曰：「比音必寐反。」","sentenceOrder":131},
  {"id":"s_work_han_thu_97_132","chapterId":"ch_work_han_thu_97","textTraditional":"莽聞之，大懼，乃拜其黨親輕車將軍成武侯孫建為奮武將軍，光祿勳成都侯王邑為虎牙將軍，明義侯王駿為強弩將軍，春王城門校尉王況為震威將軍，〔一〕宗伯忠孝侯劉宏為奮衝將軍，中少府建威侯王昌為中堅將軍，中郎將震羌侯竇兄為奮威將軍，〔二〕凡七人，自擇除關西人為校尉軍吏，將關東甲卒，發奔命以擊義焉。復以太僕武讓為積弩將軍屯函谷關，將作大匠蒙鄉侯逯並為橫野將軍屯武關〔三〕，羲和紅休侯劉歆為揚武將軍屯宛，太保後丞丞陽侯甄邯為大將軍屯霸上，〔四〕常鄉侯王惲為車騎將軍屯平樂館，騎都尉王晏為建威將軍屯城北，城門校尉趙恢為城門將軍，皆勒兵自備。","sentenceOrder":132},
  {"id":"s_work_han_thu_97_133","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「春王，長安城東出北頭第一門也。本名宣平門，莽更改焉。」","sentenceOrder":133},
  {"id":"s_work_han_thu_97_134","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「兄讀曰況。」","sentenceOrder":134},
  {"id":"s_work_han_thu_97_135","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「逯，姓也。並，名也。逯音祿，又音鹿。今東郡有逯姓，二音並行。書本逯字或作逮。今河朔有逮姓，自呼音徒戴反，其義兩通。」","sentenceOrder":135},
  {"id":"s_work_han_thu_97_136","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「丞陽侯音烝。」","sentenceOrder":136},
  {"id":"s_work_han_thu_97_137","chapterId":"ch_work_han_thu_97","textTraditional":"莽日抱孺子（謂）〔會〕群臣而稱曰：「昔成王幼，周公攝政，而管蔡挾祿父以畔，〔一〕今翟義亦挾劉信而作亂。自古大聖猶懼此，況臣莽之斗筲！」〔二〕群臣皆曰：「不遭此變，不章聖德。」莽於是依周書作大誥，〔三〕曰：","sentenceOrder":137},
  {"id":"s_work_han_thu_97_138","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「祿父，紂子也。父讀曰甫。」","sentenceOrder":138},
  {"id":"s_work_han_thu_97_139","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「斗筲，自喻材器小也，解在公孫劉田傳。」","sentenceOrder":139},
  {"id":"s_work_han_thu_97_140","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「武王崩，周公相成王而三監、淮夷叛，周公作大誥。莽自比周公，故依放其事。」","sentenceOrder":140},
  {"id":"s_work_han_thu_97_141","chapterId":"ch_work_han_thu_97","textTraditional":"惟居攝二年十月甲子，攝皇帝若曰：大誥道諸侯王三公列侯于汝卿大夫元士御事。〔一〕不弔，天降喪于趙、傅、丁、董。〔二〕洪惟我幼沖孺子，當承繼嗣無疆大歷服事，〔三〕予未遭其明悊能道民於安，況其能往知天命！〔四〕熙！我念孺子，若涉淵水，〔五〕予惟往求朕所濟度，奔走〔六〕以傅近奉承高皇帝所受命，〔七〕予豈敢自比於前人乎！〔八〕天降威明，用寧帝室，遺我居攝寶龜。〔九〕太皇太后以丹石之符，乃紹天明意，〔一０〕詔予即命居攝踐祚，如周公故事。","sentenceOrder":141},
  {"id":"s_work_han_thu_97_142","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　應劭曰：「言以大道告於諸侯以下也。御事，主事也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_97_143","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　應劭曰：「趙飛燕、傅太后、丁太后、董賢也。」師古曰：「不弔，言不為天所弔閔。降，下也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_97_144","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「洪，大也。惟，思也。沖，稚也。大思幼稚孺子，當承繼漢家無竟之歷，服行政事。」","sentenceOrder":144},
  {"id":"s_work_han_thu_97_145","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「予，莽自稱也。言不遭遇明智之人以自輔佐，而道百姓於安，蓋為謙辭也。道讀曰導。」","sentenceOrder":145},
  {"id":"s_work_han_thu_97_146","chapterId":"ch_work_han_thu_97","textTraditional":"〔五〕　師古曰：「熙，嘆辭。」","sentenceOrder":146},
  {"id":"s_work_han_thu_97_147","chapterId":"ch_work_han_thu_97","textTraditional":"〔六〕　師古曰：「言我當求所以濟度之，故奔走盡力，不憚勤勞。」","sentenceOrder":147},
  {"id":"s_work_han_thu_97_148","chapterId":"ch_work_han_thu_97","textTraditional":"〔七〕　師古曰：「傅讀曰附。近音其靳反。」","sentenceOrder":148},
  {"id":"s_work_han_thu_97_149","chapterId":"ch_work_han_thu_97","textTraditional":"〔八〕　師古曰：「前人謂周公。」","sentenceOrder":149},
  {"id":"s_work_han_thu_97_150","chapterId":"ch_work_han_thu_97","textTraditional":"〔九〕　師古曰：「威明猶言明威也。遺音弋季反。」","sentenceOrder":150},
  {"id":"s_work_han_thu_97_151","chapterId":"ch_work_han_thu_97","textTraditional":"〔一０〕師古曰：「紹，承也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_97_152","chapterId":"ch_work_han_thu_97","textTraditional":"反虜故東郡太守翟義擅興師動眾，曰「有大難于西土，西土人亦不靖。」〔一〕於是動嚴鄉侯信，誕敢犯祖亂宗之序。〔二〕天降威遺我寶龜，固知我國有呰災，使民不安，〔三〕是天反復右我漢國也。〔四〕粵其聞日，〔五〕宗室之俊有四百人，〔六〕民獻儀九萬夫，〔七〕予敬以終於此謀繼嗣圖功。〔八〕我有大事，休，予卜并吉，〔九〕故我出大將告郡太守諸侯相令長曰：「予得吉卜，予惟以汝于伐東郡嚴鄉逋播臣。」〔一０〕爾國君或者無不反曰：「難大，民亦不靜，亦惟在帝宮諸侯宗室，於小子族父，敬不可征。」〔一一〕帝不違卜，〔一二〕故予為沖人長思厥難曰：「烏虖！義、信所犯，誠動鰥寡，哀哉！」〔一三〕予遭天役遺，大解難於予身，以為孺子，不身自卹。〔一四〕","sentenceOrder":152},
  {"id":"s_work_han_thu_97_153","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「曰者，述翟義之言云爾也。西土謂（西京）〔京師〕也，言在東郡之西也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_97_154","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「誕，大也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_97_155","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「呰，病也。言天所以降威遺龜者，知國有災病，義、信當反，天下不安之故也。呰讀與疵同。」","sentenceOrder":155},
  {"id":"s_work_han_thu_97_156","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「復音扶目反。右讀曰祐。」","sentenceOrder":156},
  {"id":"s_work_han_thu_97_157","chapterId":"ch_work_han_thu_97","textTraditional":"〔五〕　孟康曰：「翟義反書上聞日也。」師古曰：「粵，發語辭也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_97_158","chapterId":"ch_work_han_thu_97","textTraditional":"〔六〕　孟康曰：「諸劉見在者。」","sentenceOrder":158},
  {"id":"s_work_han_thu_97_159","chapterId":"ch_work_han_thu_97","textTraditional":"〔七〕　孟康曰：「民之表儀，謂賢者。」","sentenceOrder":159},
  {"id":"s_work_han_thu_97_160","chapterId":"ch_work_han_thu_97","textTraditional":"〔八〕　師古曰：「我用此宗室之俊及獻儀者共謀圖國事，終成其功。」","sentenceOrder":160},
  {"id":"s_work_han_thu_97_161","chapterId":"ch_work_han_thu_97","textTraditional":"〔九〕　師古曰：「大事，戎事也。言人謀既從，卜又并吉，是為美也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_97_162","chapterId":"ch_work_han_thu_97","textTraditional":"〔一０〕師古曰：「逋，亡也。播，散也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_97_163","chapterId":"ch_work_han_thu_97","textTraditional":"〔一一〕師古曰：「言爾等國君或有言曰，禍難既大，眾庶不安，又劉信國之宗室，於孺子為族父，當加禮敬，不可征討。」","sentenceOrder":163},
  {"id":"s_work_han_thu_97_164","chapterId":"ch_work_han_thu_97","textTraditional":"〔一二〕師古曰：「卜既得吉，天命不違。」","sentenceOrder":164},
  {"id":"s_work_han_thu_97_165","chapterId":"ch_work_han_thu_97","textTraditional":"〔一三〕師古曰：「無妻無夫之人亦同受其害，故可哀哉。」","sentenceOrder":165},
  {"id":"s_work_han_thu_97_166","chapterId":"ch_work_han_thu_97","textTraditional":"〔一四〕師古曰：「言天以漢家役事遺我，而令身解其難，故我征伐以為孺子除亂，非自憂己身也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_97_167","chapterId":"ch_work_han_thu_97","textTraditional":"予義彼國君泉陵侯上書〔一〕曰：「成王幼弱，周公踐天子位以治天下，六年，朝諸侯於明堂，制禮樂，班度量，而天下大服。〔二〕太皇太后承順天心，成居攝之義。皇太子為孝平皇帝子，〔三〕年在襁褓，宜且為子，知為人子道，令皇太后得加慈母恩。畜養成就，加元服，然後復（予）〔子〕明辟。」〔四〕","sentenceOrder":167},
  {"id":"s_work_han_thu_97_168","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　應劭曰：「泉陵侯，劉慶也。上書令莽行天子事。」","sentenceOrder":168},
  {"id":"s_work_han_thu_97_169","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「班謂布行也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_97_170","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「皇太子即謂孺子。」","sentenceOrder":170},
  {"id":"s_work_han_thu_97_171","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「辟，君也。以明君之事還孺子。」","sentenceOrder":171},
  {"id":"s_work_han_thu_97_172","chapterId":"ch_work_han_thu_97","textTraditional":"熙！為我孺子之故，〔一〕予惟趙、傅、丁、董之亂，遏絕繼嗣，變剝適庶，危亂漢朝，以成三阸，〔二〕隊極厥命。〔三〕烏虖！害其可不旅力同心戒之哉！〔四〕予不敢僭上帝命。〔五〕天休於安帝室，興我漢國，惟卜用克綏受茲命。〔六〕今天其相民，況亦惟卜用！〔七〕","sentenceOrder":172},
  {"id":"s_work_han_thu_97_173","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「重歎而言。」","sentenceOrder":173},
  {"id":"s_work_han_thu_97_174","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　晉灼曰：「古厄字。」服虔曰：「厄，會也，謂三七二百一十歲。」師古曰：「適讀曰嫡。」","sentenceOrder":174},
  {"id":"s_work_han_thu_97_175","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「隊，隕也。極，盡也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_97_176","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「害讀曰曷。曷，何也。旅，陳也。」","sentenceOrder":176},
  {"id":"s_work_han_thu_97_177","chapterId":"ch_work_han_thu_97","textTraditional":"〔五〕　師古曰：「僭，不信也。言順天命而征討。」","sentenceOrder":177},
  {"id":"s_work_han_thu_97_178","chapterId":"ch_work_han_thu_97","textTraditional":"〔六〕　師古曰：「言天美於興復漢國，故我惟用卜吉，能安受此命。」","sentenceOrder":178},
  {"id":"s_work_han_thu_97_179","chapterId":"ch_work_han_thu_97","textTraditional":"〔七〕　師古曰：「言天道當思助人，況更用卜，吉可知矣。」","sentenceOrder":179},
  {"id":"s_work_han_thu_97_180","chapterId":"ch_work_han_thu_97","textTraditional":"太皇太后肇有元城沙鹿之右，〔一〕陰精女主聖明之祥〔二〕，配元生成，以興我天下之符，遂獲西王母之應，〔三〕神靈之徵，〔四〕以祐我帝室，以安我大宗，以紹我後嗣，以繼我漢功。厥害適統不宗元緒者，辟不違親，辜不避戚。〔五〕夫豈不愛？亦惟帝室。〔六〕是以廣立王侯，並建曾玄，俾屏我京師，綏撫宇內；〔七〕傅徵儒生，講道於廷，論序乖繆，制禮作樂，同律度量，混壹風俗；〔八〕正天地之位，昭郊宗之禮，定五畤廟祧，咸秩亡文；〔九〕建靈臺，立明堂，設辟雍，張太學，尊中宗、高宗之號。〔一０〕昔我高宗崇德建武，克綏西域，以受白虎威勝之瑞，〔一一〕天地判合，乾坤序德。〔一二〕太皇太后臨政，有龜龍麟鳳之應，五德嘉符，相因而備。河圖雒書遠自昆侖，出於重野。〔一三〕古讖著言，肆今享實。〔一四〕此乃皇天上帝所以安我帝室，俾我成就洪烈也。〔一五〕烏虖！天（用）〔明〕威輔漢始而大大矣。〔一六〕爾有惟舊人泉陵侯之言，爾不克遠省，爾豈知太皇太后若此勤哉！〔一七〕","sentenceOrder":180},
  {"id":"s_work_han_thu_97_181","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　張晏曰：「沙鹿在元城縣。春秋時沙鹿崩，王莽以為元后之祥，語在元后傳。」師古曰：「右讀曰祐。」","sentenceOrder":181},
  {"id":"s_work_han_thu_97_182","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　李奇曰：「李親懷元后，夢月入懷，陰精女主之祥。」","sentenceOrder":182},
  {"id":"s_work_han_thu_97_183","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　孟康曰：「民傳祀西王母之應也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_97_184","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「徵，證也。」","sentenceOrder":184},
  {"id":"s_work_han_thu_97_185","chapterId":"ch_work_han_thu_97","textTraditional":"〔五〕　師古曰：「其有害國之正統，不尊大緒者，當速加刑辟，不避親戚。適讀曰嫡。」","sentenceOrder":185},
  {"id":"s_work_han_thu_97_186","chapterId":"ch_work_han_thu_97","textTraditional":"〔六〕　師古曰：「非不愛此人，但為帝室不得止。」","sentenceOrder":186},
  {"id":"s_work_han_thu_97_187","chapterId":"ch_work_han_thu_97","textTraditional":"〔七〕　師古曰：「屏謂蔽捍其難也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_97_188","chapterId":"ch_work_han_thu_97","textTraditional":"〔八〕　師古曰：「混亦同也，音胡本反。」","sentenceOrder":188},
  {"id":"s_work_han_thu_97_189","chapterId":"ch_work_han_thu_97","textTraditional":"〔九〕　孟康曰：「諸廢祀無文籍皆祭之。」","sentenceOrder":189},
  {"id":"s_work_han_thu_97_190","chapterId":"ch_work_han_thu_97","textTraditional":"〔一０〕服虔曰：「宣帝、元帝也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_97_191","chapterId":"ch_work_han_thu_97","textTraditional":"〔一一〕應劭曰：「元帝誅滅郅支單于，懷輯西域，時有獻白虎者，所以威遠勝猛也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_97_192","chapterId":"ch_work_han_thu_97","textTraditional":"〔一二〕師古曰：「言元帝既有威德，太后又兆符應，則是天地乾坤夫妻之義相配合也。判之言片也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_97_193","chapterId":"ch_work_han_thu_97","textTraditional":"〔一三〕師古曰：「昆侖河所出，重野洛所出，皆有圖書，故本言之。野，古野字。」","sentenceOrder":193},
  {"id":"s_work_han_thu_97_194","chapterId":"ch_work_han_thu_97","textTraditional":"〔一四〕師古曰：「肆，故也。言有其讖，故今當其實。」","sentenceOrder":194},
  {"id":"s_work_han_thu_97_195","chapterId":"ch_work_han_thu_97","textTraditional":"〔一五〕師古曰：「洪，大也。烈，業也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_97_196","chapterId":"ch_work_han_thu_97","textTraditional":"〔一六〕師古曰：「言因此難更以強大。」","sentenceOrder":196},
  {"id":"s_work_han_thu_97_197","chapterId":"ch_work_han_thu_97","textTraditional":"〔一七〕師古曰：「言爾當思久舊之人泉陵侯所言，爾不克遠省識古事，豈知太后之勤乎？」","sentenceOrder":197},
  {"id":"s_work_han_thu_97_198","chapterId":"ch_work_han_thu_97","textTraditional":"天毖勞我成功所，〔一〕予不敢不極卒安皇帝之所圖事〔二〕。肆予告我諸侯王公列侯卿大夫元士御事：〔三〕天輔誠辭，〔四〕天其累我以民，予害敢不於祖宗安人圖功所終？〔五〕天亦惟勞我民，若有疾，予害敢不於祖宗所受休輔？〔六〕予聞孝子善繼人之意，忠臣善成人之事。予思若考作室，厥子堂而構之；〔七〕厥父菑，厥子播而穫之。〔八〕予害敢不於身撫祖宗之所受大命？〔九〕若祖宗乃有效湯武伐厥子，民長其勸弗救。〔一０〕烏虖肆哉！〔一一〕諸侯王公列侯卿大夫元士御事，其勉助國道明！〔一二〕亦惟宗室之俊，民之表儀，迪知上帝命。〔一三〕〔粵天輔誠，爾不得易定！〕〔一四〕況今天降定于漢國，惟大艱人翟義、劉信大逆，欲相伐於厥室，豈亦知命之不易乎？〔一五〕予永念曰天惟喪翟義、劉信，若嗇夫，予害敢不終予畝？〔一六〕天亦惟休於祖宗，予害其極卜，害敢不（卜）〔于〕從？〔一七〕率寧人有旨疆土，況今卜并吉！〔一八〕故予大以爾東征，命不僭差，〔一九〕卜陳惟若此。〔二０〕","sentenceOrder":198},
  {"id":"s_work_han_thu_97_199","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　孟康曰：「天慎勞我國家成功之所在。」","sentenceOrder":199},
  {"id":"s_work_han_thu_97_200","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「卒，終也。言我不敢不終祖宗之業，安帝室所謀之事。」","sentenceOrder":200},
  {"id":"s_work_han_thu_97_201","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「肆，陳也，陳其理而告之。」","sentenceOrder":201},
  {"id":"s_work_han_thu_97_202","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「言有至誠之辭則為天所輔。」","sentenceOrder":202},
  {"id":"s_work_han_thu_97_203","chapterId":"ch_work_han_thu_97","textTraditional":"〔五〕　師古曰：「累，託也。言天以百姓託我，我曷敢不謀終祖宗安人之功也。累音力瑞反。害讀曰曷。下皆類此。」","sentenceOrder":203},
  {"id":"s_work_han_thu_97_204","chapterId":"ch_work_han_thu_97","textTraditional":"〔六〕　師古曰：「言天欲撫勞我眾，眾若有疾苦，我曷敢不順祖宗之意，休息而輔助之。勞，來到反。」","sentenceOrder":204},
  {"id":"s_work_han_thu_97_205","chapterId":"ch_work_han_thu_97","textTraditional":"〔七〕　師古曰：「父有作室之意，則子當築（室）〔堂〕而（御名）〔構〕棼橑以成之。」","sentenceOrder":205},
  {"id":"s_work_han_thu_97_206","chapterId":"ch_work_han_thu_97","textTraditional":"〔八〕　師古曰：「父菑耕其田，子當布種而收穫之。反土為菑。一曰田一歲曰菑。」","sentenceOrder":206},
  {"id":"s_work_han_thu_97_207","chapterId":"ch_work_han_thu_97","textTraditional":"〔九〕　師古曰：「作室農人猶不棄其本業，我於今日不得有避而不征討叛逆也。」","sentenceOrder":207},
  {"id":"s_work_han_thu_97_208","chapterId":"ch_work_han_thu_97","textTraditional":"〔一０〕師古曰：「譬有人來伐其子，而長養彼心，反勸助之，弗救其子者，正以子惡故也。言湯武疾惡，其心亦然，今所征討不得避親，當以公義。」","sentenceOrder":208},
  {"id":"s_work_han_thu_97_209","chapterId":"ch_work_han_thu_97","textTraditional":"〔一一〕師古曰：「肆，陳也，勸令陳力。」","sentenceOrder":209},
  {"id":"s_work_han_thu_97_210","chapterId":"ch_work_han_thu_97","textTraditional":"〔一二〕師古曰：「道，由也。言當由於明智之事，以助國也。」","sentenceOrder":210},
  {"id":"s_work_han_thu_97_211","chapterId":"ch_work_han_thu_97","textTraditional":"〔一三〕師古曰：「迪亦道也，言當遵道而知天命。」","sentenceOrder":211},
  {"id":"s_work_han_thu_97_212","chapterId":"ch_work_han_thu_97","textTraditional":"〔一四〕〔師古曰：「粵，辭也。天道輔誠，爾不得改易天之定命。」〕","sentenceOrder":212},
  {"id":"s_work_han_thu_97_213","chapterId":"ch_work_han_thu_97","textTraditional":"〔一五〕師古曰：「言義、信不知天命不可改易，乃大為艱難以干國紀，是自相謀誅伐其室也。囏，古艱字。」","sentenceOrder":213},
  {"id":"s_work_han_thu_97_214","chapterId":"ch_work_han_thu_97","textTraditional":"〔一六〕師古曰：「嗇夫治田，志除草穢。天之欲喪義、信，事亦如之。我當順天以終竟田畝之事。」","sentenceOrder":214},
  {"id":"s_work_han_thu_97_215","chapterId":"ch_work_han_thu_97","textTraditional":"〔一七〕師古曰：「言天美祖宗之事，我何其極卜法，敢不往從，言必從也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_97_216","chapterId":"ch_work_han_thu_97","textTraditional":"〔一八〕師古曰：「言循祖宗之業，務在安人而美疆土，況今卜并吉乎！言不可不從也。」","sentenceOrder":216},
  {"id":"s_work_han_thu_97_217","chapterId":"ch_work_han_thu_97","textTraditional":"〔一九〕師古曰：「言必信之矣。」","sentenceOrder":217},
  {"id":"s_work_han_thu_97_218","chapterId":"ch_work_han_thu_97","textTraditional":"〔二０〕師古曰：「卜兆陳列惟如此。」","sentenceOrder":218},
  {"id":"s_work_han_thu_97_219","chapterId":"ch_work_han_thu_97","textTraditional":"乃遣大夫桓譚等班行諭告當反位孺子之意。還，封譚為明告里附城。〔一〕","sentenceOrder":219},
  {"id":"s_work_han_thu_97_220","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「明告者，以其出使能明告諭於外也。附城，云如古附庸也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_97_221","chapterId":"ch_work_han_thu_97","textTraditional":"諸將東（破）〔至〕陳留菑，〔一〕與義會戰，破之，斬劉璜首。莽大喜，復下詔曰：「太皇太后遭家不造，國統三絕，〔二〕絕輒復續，恩莫厚焉，信莫立焉。孝平皇帝短命蚤崩，〔三〕幼嗣孺沖，詔予居攝。予承明詔，奉社稷之任，持大宗之重，養六尺之託，受天下之寄，戰戰兢兢，不敢安息。伏念太皇太后惟經藝分析，王道離散，〔四〕漢家制作之業獨未成就，故博徵儒士，大興典制，備物致用，立功成器，以為天下利。王道粲然，基業既著，千載之廢，百世之遺，於今乃成，道德庶幾於唐虞，功烈比齊於殷周。〔五〕今翟義、劉信等謀反大逆，流言惑眾，欲以篡位，賊害我孺子，罪深於管蔡，惡甚於禽獸。信父故東平王雲，不孝不謹，親毒殺其父思王，名曰鉅鼠，〔六〕後雲竟坐大逆誅死。義父故丞相方進，險詖陰賊，〔七〕兄宣靜言令色，外巧內嫉，〔八〕所殺鄉邑汝南者數十人。今積惡二家，迷惑相得，此時命當殄，天所滅也。義始發兵，上書言宇、信等與東平相輔謀反，〔九〕執捕械繫，欲以威民，先自相被以反逆大惡，〔一０〕轉相捕械，此其破殄之明證也。已捕斬斷信二子穀鄉侯章、德廣侯鮪，義母練、兄宣、親屬二十四人皆磔暴于長安都巿四通之衢。當其斬時，觀者重疊，〔一一〕天氣和清，可謂當矣。命遣大將軍共行皇天之罰，〔一二〕討海內之讎，功效著焉，予甚嘉之。司馬法不云乎？『賞不踰時。』欲民速睹為善之利也。今先封車騎都尉孫賢等五十五人皆為列侯，戶邑之數別下。遣使者持黃金印、赤韍縌、朱輪車，即軍中拜授。」〔一三〕因大赦天下。","sentenceOrder":221},
  {"id":"s_work_han_thu_97_222","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　孟康曰：「菑，故戴國，在梁，後屬陳留，今曰考城。」","sentenceOrder":222},
  {"id":"s_work_han_thu_97_223","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「謂成帝、哀帝、平帝皆無子矣。」","sentenceOrder":223},
  {"id":"s_work_han_thu_97_224","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「蚤，古早字。」","sentenceOrder":224},
  {"id":"s_work_han_thu_97_225","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「惟，思也。」","sentenceOrder":225},
  {"id":"s_work_han_thu_97_226","chapterId":"ch_work_han_thu_97","textTraditional":"〔五〕　師古曰：「烈，業也。」","sentenceOrder":226},
  {"id":"s_work_han_thu_97_227","chapterId":"ch_work_han_thu_97","textTraditional":"〔六〕　師古曰：「鉅，大也。莽誣雲呼其父曰鉅鼠也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_97_228","chapterId":"ch_work_han_thu_97","textTraditional":"〔七〕　師古曰：「詖，佞也，音彼義反。」","sentenceOrder":228},
  {"id":"s_work_han_thu_97_229","chapterId":"ch_work_han_thu_97","textTraditional":"〔八〕　師古曰：「靜，安也。令，善也。言其陽為安靜之言，外有善色，而實嫉害也。」","sentenceOrder":229},
  {"id":"s_work_han_thu_97_230","chapterId":"ch_work_han_thu_97","textTraditional":"〔九〕　師古曰：「輔者，東平王相之名也。」","sentenceOrder":230},
  {"id":"s_work_han_thu_97_231","chapterId":"ch_work_han_thu_97","textTraditional":"〔一０〕師古曰：「被，加也，音皮義反。」","sentenceOrder":231},
  {"id":"s_work_han_thu_97_232","chapterId":"ch_work_han_thu_97","textTraditional":"〔一一〕師古曰：「言人多而聚積。」","sentenceOrder":232},
  {"id":"s_work_han_thu_97_233","chapterId":"ch_work_han_thu_97","textTraditional":"〔一二〕師古曰：「共讀曰恭。」","sentenceOrder":233},
  {"id":"s_work_han_thu_97_234","chapterId":"ch_work_han_thu_97","textTraditional":"〔一三〕服虔曰：「縌即今之綬也。」師古曰：「韍，所以繫印也。縌者，系也，謂逆受之也。即，就也。韍音弗。縌音逆。」","sentenceOrder":234},
  {"id":"s_work_han_thu_97_235","chapterId":"ch_work_han_thu_97","textTraditional":"於是吏士精銳遂攻圍義於圉城，破之，義與劉信棄軍庸亡。〔一〕至固始界中捕得義，尸磔陳都巿。卒不得信。","sentenceOrder":235},
  {"id":"s_work_han_thu_97_236","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　孟康曰：「謂挺身逃亡，如奴庸也。」","sentenceOrder":236},
  {"id":"s_work_han_thu_97_237","chapterId":"ch_work_han_thu_97","textTraditional":"初，三輔聞翟義起，自茂陵以西至汧二十三縣盜賊並發，趙明、霍鴻等自稱將軍，攻燒官寺，殺右輔都尉及斄令，〔一〕劫略吏民，眾十餘萬，火見未央宮前殿。莽晝夜抱孺子禱宗廟。復拜衛尉王級為虎賁將軍，大鴻臚望鄉侯閻遷為折衝將軍，與甄邯、王晏西擊趙明等。正月，虎牙將軍王邑等自關東還，便引兵西。彊弩將軍王駿以無功免，揚武將軍劉歆歸故官。復以邑弟侍中王奇為揚武將軍，城門將軍趙恢為彊弩將軍，中郎將李棽為厭難將軍，〔二〕復將兵西。二月，明等殄滅，諸縣悉平，還師振旅。莽乃置酒白虎殿，勞饗將帥，大封拜。先是益州蠻夷及金城塞外羌反畔，時州郡擊破之。莽乃并錄，以小大為差，封侯伯子男凡三百九十五人，曰「皆以奮怒，東指西擊，羌寇蠻盜，反虜逆賊，不得旋踵，應時殄滅，天子咸服」之功封云。莽於是自謂大得天人之助，至其年十二月，遂即真矣。","sentenceOrder":237},
  {"id":"s_work_han_thu_97_238","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「斄讀曰邰。」","sentenceOrder":238},
  {"id":"s_work_han_thu_97_239","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「棽音所林反。」","sentenceOrder":239},
  {"id":"s_work_han_thu_97_240","chapterId":"ch_work_han_thu_97","textTraditional":"初，義所收宛令劉立聞義舉兵，上書願備軍吏為國討賊，內報私怨。莽擢立為陳留太守，封明德侯。","sentenceOrder":240},
  {"id":"s_work_han_thu_97_241","chapterId":"ch_work_han_thu_97","textTraditional":"始，義兄宣居長安，先義未發，家數有怪，〔一〕夜聞哭聲，聽之不知所在。宣教授諸生滿堂，有狗從外入，齧其中庭群鴈數十，比驚救之，已皆斷頭。〔二〕狗走出門，求不知處。宣大惡之，謂後母曰：「東郡太守文仲素俶儻，〔三〕今數有惡怪，恐有妄為而大禍至也。大夫人可歸，為棄去宣家者以避害。」〔四〕母不肯去，後數月敗。","sentenceOrder":241},
  {"id":"s_work_han_thu_97_242","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「言義未發兵之前。」","sentenceOrder":242},
  {"id":"s_work_han_thu_97_243","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「比音必寐反。」","sentenceOrder":243},
  {"id":"s_work_han_thu_97_244","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「俶音土歷反。」","sentenceOrder":244},
  {"id":"s_work_han_thu_97_245","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「言歸其本族，自絕於翟氏。」","sentenceOrder":245},
  {"id":"s_work_han_thu_97_246","chapterId":"ch_work_han_thu_97","textTraditional":"莽盡壞義第宅，汙池之。〔一〕發父方進及先祖冢在汝南者，燒其棺柩，夷滅三族，誅及種嗣，至皆同坑，以棘五毒并葬之。〔二〕而下詔曰：「蓋聞古者伐不敬，取其鯨鯢築武軍，封以為大戮，於是乎有京觀以懲淫慝。〔三〕乃者反虜劉信、翟義誖逆作亂於東，而芒竹群盜趙明、霍鴻造逆西土，〔四〕遣武將征討，咸伏其辜。惟信、義等始發自濮陽，結姦無鹽，殄滅於圉。趙明依阻槐里環隄，〔五〕霍鴻負倚盩厔芒竹，〔六〕咸用破碎，亡有餘類。其取反虜逆賊之鯨鯢，聚之通路之旁，濮陽、無鹽、圉、槐里、盩厔凡五所，各方六丈，高六尺，築為武軍，封以為大戮，薦樹之棘。〔七〕建表木，高丈六尺。〔八〕書曰『反虜逆賊鯨鯢』，在所長吏常以秋循行，〔九〕勿令壞敗，以懲淫慝焉。」","sentenceOrder":246},
  {"id":"s_work_han_thu_97_247","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「汙，停水也，音烏。」","sentenceOrder":247},
  {"id":"s_work_han_thu_97_248","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　如淳曰：「野葛、狼毒之屬也。」","sentenceOrder":248},
  {"id":"s_work_han_thu_97_249","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「此左傳載楚莊王之辭也。鯨鯢，大魚為害者也。以此比敵人之勇桀者。京，高丘也。觀謂如闕形也。懲，創乂也。慝，惡也。〈魚畺〉，古鯨字，音其京反。鯢音五奚反。觀音工喚反。」","sentenceOrder":249},
  {"id":"s_work_han_thu_97_250","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「芒竹在盩厔南界，芒水之曲而多竹林也，即（中）〔今〕司竹園是其地矣。芒音亡。」","sentenceOrder":250},
  {"id":"s_work_han_thu_97_251","chapterId":"ch_work_han_thu_97","textTraditional":"〔五〕　師古曰：「槐里縣界其中有環曲之隄，而明依之以自固也。」","sentenceOrder":251},
  {"id":"s_work_han_thu_97_252","chapterId":"ch_work_han_thu_97","textTraditional":"〔六〕　師古曰：「負，恃也。倚音於綺反。」","sentenceOrder":252},
  {"id":"s_work_han_thu_97_253","chapterId":"ch_work_han_thu_97","textTraditional":"〔七〕　師古曰：「薦讀曰荐。荐，重也，聚也。」","sentenceOrder":253},
  {"id":"s_work_han_thu_97_254","chapterId":"ch_work_han_thu_97","textTraditional":"〔八〕　師古曰：「表者，所以標明也。」","sentenceOrder":254},
  {"id":"s_work_han_thu_97_255","chapterId":"ch_work_han_thu_97","textTraditional":"〔九〕　師古曰：「行音下更反。」","sentenceOrder":255},
  {"id":"s_work_han_thu_97_256","chapterId":"ch_work_han_thu_97","textTraditional":"初，汝南舊有鴻隙大陂，郡以為饒，〔一〕成帝時，關東數水，陂溢為害。方進為相，與御史大夫孔光共遣掾行（事）〔視〕，〔二〕以為決去陂水，其地肥美，省隄防費而無水憂，遂奏罷之。及翟氏滅，鄉里歸惡，言方進請陂下良田不得而奏罷陂云。王莽時常枯旱，郡中追怨方進，童謠曰：「壞陂誰？翟子威。飯我豆食羹芋魁。〔三〕反乎覆，陂當復。〔四〕誰云者？兩黃鵠。」〔五〕","sentenceOrder":256},
  {"id":"s_work_han_thu_97_257","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「鴻隙，陂名，藉其溉灌及魚鱉萑蒲之利，以多財用。」","sentenceOrder":257},
  {"id":"s_work_han_thu_97_258","chapterId":"ch_work_han_thu_97","textTraditional":"〔二〕　師古曰：「行音下更反。」","sentenceOrder":258},
  {"id":"s_work_han_thu_97_259","chapterId":"ch_work_han_thu_97","textTraditional":"〔三〕　師古曰：「言田無溉灌，不生秔稻，又無黍稷，但有豆及芋也。豆食者，豆為飯也。羹芋魁者，以芋根為羹也。飯音扶晚反。食音飤。」","sentenceOrder":259},
  {"id":"s_work_han_thu_97_260","chapterId":"ch_work_han_thu_97","textTraditional":"〔四〕　師古曰：「事之反覆無常，言禍兮福所倚。」","sentenceOrder":260},
  {"id":"s_work_han_thu_97_261","chapterId":"ch_work_han_thu_97","textTraditional":"〔五〕　師古曰：「託言有神來告之。」","sentenceOrder":261},
  {"id":"s_work_han_thu_97_262","chapterId":"ch_work_han_thu_97","textTraditional":"司徒掾班彪曰：「丞相方進以孤童攜老母，羈旅入京師，身為儒宗，致位宰相，盛矣。當莽之起，蓋乘天威，雖有賁育，奚益於敵？〔一〕義不量力，懷忠憤發，以隕其宗，悲夫！」","sentenceOrder":262},
  {"id":"s_work_han_thu_97_263","chapterId":"ch_work_han_thu_97","textTraditional":"〔一〕　師古曰：「賁謂孟賁，育謂夏育，皆古之勇士。言得之無益，不能敵莽也。賁音奔。」","sentenceOrder":263},
  {"id":"s_work_han_thu_97_264","chapterId":"ch_work_han_thu_97","textTraditional":"校勘記","sentenceOrder":264},
  {"id":"s_work_han_thu_97_265","chapterId":"ch_work_han_thu_97","textTraditional":"三四一六頁　三行　論語（曰子）〔子曰〕『不逆詐』。　殿本作「子曰」。王先謙說殿本是。按景祐本亦誤倒。","sentenceOrder":265},
  {"id":"s_work_han_thu_97_266","chapterId":"ch_work_han_thu_97","textTraditional":"三四一六頁　六行　（博）〔搏〕擊豪彊，　景祐、殿本都作「搏」。王先謙說作「搏」是。","sentenceOrder":266},
  {"id":"s_work_han_thu_97_267","chapterId":"ch_work_han_thu_97","textTraditional":"三四一九頁一四行　而外有俊材，過絕（於）人〔倫〕；　景祐本無「於」字。景祐、殿本都有「倫」字。","sentenceOrder":267},
  {"id":"s_work_han_thu_97_268","chapterId":"ch_work_han_thu_97","textTraditional":"三四二三頁　五行　（使）〔後〕議者以為不便，　景祐、殿本都作「後」，此誤。","sentenceOrder":268},
  {"id":"s_work_han_thu_97_269","chapterId":"ch_work_han_thu_97","textTraditional":"三四二五頁一六行　遷河（南）內太守，　景祐、殿本都作「河內」。","sentenceOrder":269},
  {"id":"s_work_han_thu_97_270","chapterId":"ch_work_han_thu_97","textTraditional":"三四二八頁　三行　莽日抱孺子（謂）〔會〕群臣而稱曰：　景祐、殿、局本都作「會」。朱一新說作「會」是。","sentenceOrder":270},
  {"id":"s_work_han_thu_97_271","chapterId":"ch_work_han_thu_97","textTraditional":"三四二八頁一二行　予惟往求朕所濟度，奔走〔六〕以傅近奉承高皇帝所受命，　王念孫說「奔走」當屬下句。皮錫瑞說王說是。","sentenceOrder":271},
  {"id":"s_work_han_thu_97_272","chapterId":"ch_work_han_thu_97","textTraditional":"三四三０頁　二行　西土謂（西京）〔京師〕也。　景祐、殿本都作「京師」。","sentenceOrder":272},
  {"id":"s_work_han_thu_97_273","chapterId":"ch_work_han_thu_97","textTraditional":"三四三一頁　三行　然後復（予）〔子〕明辟。　景祐、殿、局本都作「子」。王先謙說作「子」是。","sentenceOrder":273},
  {"id":"s_work_han_thu_97_274","chapterId":"ch_work_han_thu_97","textTraditional":"三四三二頁一０行　天（用）〔明〕威輔漢始而大大矣。　景祐、殿本都作「明」。朱一新說作「明」是。","sentenceOrder":274},
  {"id":"s_work_han_thu_97_275","chapterId":"ch_work_han_thu_97","textTraditional":"三四三四頁　四行　〔粵天輔誠，爾不得易定！〕　景祐、殿本都有此九字，此脫，注十九字亦脫。","sentenceOrder":275},
  {"id":"s_work_han_thu_97_276","chapterId":"ch_work_han_thu_97","textTraditional":"三四三四頁　六行　害敢不（卜）〔于〕從？　景祐、殿本都作「于」。按注云「往從」，作「于」是。","sentenceOrder":276},
  {"id":"s_work_han_thu_97_277","chapterId":"ch_work_han_thu_97","textTraditional":"三四三四頁一四行　則子當築（室）〔堂〕而（御名）〔構〕棼橑以成之。　景祐、殿本「室」都作「堂」，「御名」都作「構」。","sentenceOrder":277},
  {"id":"s_work_han_thu_97_278","chapterId":"ch_work_han_thu_97","textTraditional":"三四三五頁一五行　諸將東（破）〔至〕陳留菑，　景祐、殿本都作「至」。錢大昭說「破」字誤。","sentenceOrder":278},
  {"id":"s_work_han_thu_97_279","chapterId":"ch_work_han_thu_97","textTraditional":"三四四０頁　一行　即（中）〔今〕司竹園是其地矣。　景祐、殿本都作「今」，此誤。","sentenceOrder":279},
  {"id":"s_work_han_thu_97_280","chapterId":"ch_work_han_thu_97","textTraditional":"三四四０頁　八行　共遣掾行（事）〔視〕，　景祐、殿本都作「視」，此誤。","sentenceOrder":280},
  {"id":"s_work_han_thu_98_1","chapterId":"ch_work_han_thu_98","textTraditional":"谷永字子雲，長安人也。父吉，為衛司馬，使送郅支單于侍子，〔一〕為郅支所殺，語在陳湯傳。永少為長安小史，後博學經書。建昭中，御史大夫繁延壽〔二〕聞其有茂材，除補屬，舉為太常丞，數上疏言得失。","sentenceOrder":1},
  {"id":"s_work_han_thu_98_2","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「為使而送之還本國也。郅音質。」","sentenceOrder":2},
  {"id":"s_work_han_thu_98_3","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「即李延壽也。一姓繁，音蒲何反。」","sentenceOrder":3},
  {"id":"s_work_han_thu_98_4","chapterId":"ch_work_han_thu_98","textTraditional":"建始三年冬，日食地震同日俱發，詔舉方正直言極諫之士，太常陽城侯劉慶忌舉永待詔公車。對曰：","sentenceOrder":4},
  {"id":"s_work_han_thu_98_5","chapterId":"ch_work_han_thu_98","textTraditional":"陛下秉至聖之純德，懼天地之戒異，飭身修政，〔一〕納問公卿，又下明詔，帥舉直言，〔二〕燕見紬繹，以求咎愆，〔三〕使臣等得造明朝，承聖問。〔四〕臣材朽學淺，不通政事。竊聞明王即位，正五事，建大中，以承天心，〔五〕則庶徵序於下，日月理於上；〔六〕如人君淫溺後宮，般樂游田，〔七〕五事失於躬，大中之道不立，則咎徵降而六極至。〔八〕凡災異之發，各象過失，以類告人。乃十二月朔戊申，日食婺女之分，地震蕭牆之內，〔九〕二者同日俱發，以丁寧陛下，〔一０〕厥咎不遠，宜厚求諸身。〔一一〕意豈陛下志在閨門，未卹政事，不慎舉錯，〔一二〕婁失中與？〔一三〕內寵大盛，女不遵道，嫉妒專上，妨繼嗣與？古之王者廢五事之中，失夫婦之紀，妻妾得意，謁行於內，勢行於外，至覆傾國家，或亂陰陽。〔一四〕昔褒姒用國，宗周以喪；〔一五〕閻妻驕扇，日以不臧。〔一六〕此其效也。經曰：「皇極，皇建其有極。」〔一七〕傳曰：「皇之不極，是謂不建，時則有日月亂行。」","sentenceOrder":5},
  {"id":"s_work_han_thu_98_6","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「飭與敕同。敕，整也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_98_7","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「帥舉，謂公卿守相皆令舉也。帥字或作師。師，眾也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_98_8","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「紬讀曰抽。紬繹者，引其端緒也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_98_9","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「造，至也，音千到反。」","sentenceOrder":9},
  {"id":"s_work_han_thu_98_10","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「五事，貌、言、視、聽、思也。大中即皇極也。解在五行志。」","sentenceOrder":10},
  {"id":"s_work_han_thu_98_11","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「庶，眾也。徵，證也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_98_12","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　師古曰：「如，若也。般讀與盤同。」","sentenceOrder":12},
  {"id":"s_work_han_thu_98_13","chapterId":"ch_work_han_thu_98","textTraditional":"〔八〕　師古曰：「六極，謂一曰凶短折，二曰疾，三曰憂，四曰貧，五曰惡，六曰弱。」","sentenceOrder":13},
  {"id":"s_work_han_thu_98_14","chapterId":"ch_work_han_thu_98","textTraditional":"〔九〕　師古曰：「蕭牆，屏牆也，解在五行志。」","sentenceOrder":14},
  {"id":"s_work_han_thu_98_15","chapterId":"ch_work_han_thu_98","textTraditional":"〔一０〕師古曰：「丁寧謂再三告示也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_98_16","chapterId":"ch_work_han_thu_98","textTraditional":"〔一一〕師古曰：「厚猶深也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_98_17","chapterId":"ch_work_han_thu_98","textTraditional":"〔一二〕師古曰：「志在閨門，謂留心於女色也。錯，置也，音千故反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_98_18","chapterId":"ch_work_han_thu_98","textTraditional":"〔一三〕師古曰：「婁，古屢字也。與讀曰歟。下皆類此。」","sentenceOrder":18},
  {"id":"s_work_han_thu_98_19","chapterId":"ch_work_han_thu_98","textTraditional":"〔一四〕師古曰：「謁，請也。內則所請必行，外則擅其權力，言女寵盛也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_98_20","chapterId":"ch_work_han_thu_98","textTraditional":"〔一五〕師古曰：「褒姒，褒人所獻之女也。幽王惑之，卒有犬戎之禍。」","sentenceOrder":20},
  {"id":"s_work_han_thu_98_21","chapterId":"ch_work_han_thu_98","textTraditional":"〔一六〕師古曰：「閻，嬖寵之族也。扇，熾也。臧，善也。魯詩小雅十月之交篇曰『此日而食，于何不臧』，又曰『閻妻扇方處』，言厲王無道，內寵熾盛，政化失理，故致災異，日為之食，為不善也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_98_22","chapterId":"ch_work_han_thu_98","textTraditional":"〔一七〕師古曰：「周書洪範之辭也。皇，大也。極，中也。大立其有中，所以行九疇之義也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_98_23","chapterId":"ch_work_han_thu_98","textTraditional":"陛下踐至尊之祚為天下主，奉帝王之職以統群生，方內之治亂，在陛下所執。〔一〕誠留意於正身，勉強於力行，損燕私之閒以勞天下，〔二〕放去淫溺之樂，罷歸倡優之笑，〔三〕絕卻不享之義，慎節游田之虞，〔四〕起居有常，循禮而動，躬親政事，致行無倦，安服若性。〔五〕經曰：「繼自今嗣王，其毋淫于酒，毋逸于游田，惟正之共。」〔六〕未有身治正而臣下邪者也。","sentenceOrder":23},
  {"id":"s_work_han_thu_98_24","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「方內，四方之內也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_98_25","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「損，減也。閒讀曰閑。勞，憂也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_98_26","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「关，古笑字。」","sentenceOrder":26},
  {"id":"s_work_han_thu_98_27","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「卻，退也。享，當也。言所為不善，不當天心也。一曰天不祐之，不歆享其祀也。虞與娛同。」","sentenceOrder":27},
  {"id":"s_work_han_thu_98_28","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「致，至也。安心而服行之，如天性自然也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_98_29","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「周書無逸之辭也。言從今以往，繼業嗣立之王毋過欲於酒，毋放於田獵，惟宜正身恭己也。共讀曰恭。」","sentenceOrder":29},
  {"id":"s_work_han_thu_98_30","chapterId":"ch_work_han_thu_98","textTraditional":"夫妻之際，王事綱紀，安危之機，聖王所致慎也。昔舜飭正二女，以崇至德；〔一〕楚莊忍絕丹姬，以成伯功；〔二〕幽王惑於褒姒，周德降亡；魯桓脅於齊女，社稷以傾。〔三〕誠修後宮之政，明尊卑之序，貴者不得嫉妒專寵，以絕驕嫚之端，抑褒、閻之亂，賤者咸得秩進，各得厥職，〔四〕以廣繼嗣之統，息白華之怨，〔五〕後宮親屬，饒之以財，勿與政事，〔六〕以遠皇父之類，損妻黨之權，〔七〕未有閨門治而天下亂者也。","sentenceOrder":30},
  {"id":"s_work_han_thu_98_31","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「虞書堯典云『釐降二女于媯汭，嬪于虞』。謂堯以二女妻舜，觀其治家，欲使治國，而舜謹敕正躬以待二女，其德益崇，遂受堯禪也。飭與敕同。」","sentenceOrder":31},
  {"id":"s_work_han_thu_98_32","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　應劭曰：「楚莊王得丹姬，三月不聽朝。保申諫，忍絕不復見，乃勤政事，遂為盟主也。」師古曰：「丹姬是楚文王姬也。莊王用申公巫臣之諫，不納夏姬。谷永集丹字作夏，是也。今此傳作丹，轉寫誤耳。應氏就而謬釋，非本實也。伯讀曰霸。」","sentenceOrder":32},
  {"id":"s_work_han_thu_98_33","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「解並在五行志。」","sentenceOrder":33},
  {"id":"s_work_han_thu_98_34","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「秩，次也，以次而進御也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_98_35","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「詩小雅白華之篇也。幽王惑於褒姒而黜申后，故國人作此詩以刺之。永言此者，譏成帝專寵趙昭儀也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_98_36","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「與讀曰豫。」","sentenceOrder":36},
  {"id":"s_work_han_thu_98_37","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　師古曰：「皇父，周卿士也。小雅十月之交詩曰『皇父卿士，番惟司徒』，刺厲王淫於色，故皇父之屬因嬖寵而為官也。遠音于萬反。父讀曰甫。」","sentenceOrder":37},
  {"id":"s_work_han_thu_98_38","chapterId":"ch_work_han_thu_98","textTraditional":"治遠自近始，習善在左右。昔龍筦納言，而帝命惟允；〔一〕四輔既備，成王靡有過事。〔二〕誠敕正左右齊栗之臣，〔三〕戴金貂之飾執常伯之職者〔四〕皆使學先王之道，知君臣之義，濟濟謹孚，無敖戲驕恣之過，〔五〕則左右肅艾，〔六〕群僚仰法，化流四方。經曰：「亦惟先正克左右。」〔七〕未有左右正而百官枉者也。〔八〕","sentenceOrder":38},
  {"id":"s_work_han_thu_98_39","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「龍，舜臣名也。筦字與管同。管，主也。虞書舜典曰帝曰：『龍，命汝作納言，夙夜出納朕命惟允。』允，信也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_98_40","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「四輔，謂左輔、右弼、前疑、後丞也。周書洛誥稱成王曰：『誕保文武受命，亂為四輔。』」","sentenceOrder":40},
  {"id":"s_work_han_thu_98_41","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　孟康曰：「左右謂尚書官也。齊栗，言其整齊萬事，（嘗）〔常〕戰栗謹敬也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_98_42","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「常伯，侍中也。伯，長也，常使長事者也。一曰常任使之人，此為長也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_98_43","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「孚，信也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_98_44","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「肅，敬也。艾讀曰乂。乂，治也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_98_45","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　師古曰：「周書君牙之辭也。言王者欲正百官，要在能先正其左右近臣也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_98_46","chapterId":"ch_work_han_thu_98","textTraditional":"〔八〕　師古曰：「枉，曲也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_98_47","chapterId":"ch_work_han_thu_98","textTraditional":"治天下者尊賢考功則治，簡賢違功則亂。〔一〕誠審思治人之術，歡樂得賢之福，論材選士，必試於職，明度量以程能，考功實以定德，〔二〕無用比周之虛譽，毋聽寖潤之譖愬，〔三〕則抱功修職之吏無蔽傷之憂，比周邪偽之徒不得即工，〔四〕小人日銷，俊艾日隆。〔五〕經曰：「三載考績，三考黜陟幽明。」〔六〕又曰：「九德咸事，俊艾在官。」〔七〕未有功賞得於前眾賢布於官而不治者也。","sentenceOrder":47},
  {"id":"s_work_han_thu_98_48","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「簡，略也，謂輕慢也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_98_49","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「程，效也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_98_50","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「比周，言阿黨親密也。寖潤，積漸之深也。比音頻寐反。」","sentenceOrder":50},
  {"id":"s_work_han_thu_98_51","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　李奇曰：「即，就也。工，官也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_98_52","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「艾讀曰乂。其下亦同。」","sentenceOrder":52},
  {"id":"s_work_han_thu_98_53","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「虞書舜典之辭也。言居官者三年一考其功，三考則退其幽闇無功者，升其昭明有功者。」","sentenceOrder":53},
  {"id":"s_work_han_thu_98_54","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　師古曰：「虞書咎繇謨之辭也。言使九德之人皆用事，俊桀治能之士並在官也。九德，謂寬而栗，柔而立，愿而恭，亂而敬，擾而毅，直而溫，簡而廉，剛而塞，強而義。」","sentenceOrder":54},
  {"id":"s_work_han_thu_98_55","chapterId":"ch_work_han_thu_98","textTraditional":"堯遭洪水之災，天下分絕為十二州，制遠之道微〔一〕而無乖畔之難者，德厚恩深，無怨於下也。秦居平土，一夫大呼而海內崩析者，〔二〕刑罰深酷，吏行殘賊也。夫違天害德，為上取怨於下，莫甚乎殘賊之吏。誠放退殘賊酷暴之吏（一）〔錮〕廢勿用，益選溫良上德之士以親萬姓，〔三〕平刑釋冤以理民命，〔四〕務省繇役，毋奪民時，薄收賦稅，毋殫民財，〔五〕使天下黎元咸安家樂業，不苦踰時之役，〔六〕不患苛暴之政，不疾酷烈之吏，〔七〕雖有唐堯之大災，民無離上之心。〔八〕經曰：「懷保小人，惠于鰥寡。〔九〕」未有德厚吏良而民畔者也。","sentenceOrder":55},
  {"id":"s_work_han_thu_98_56","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　孟康曰：「本九州，洪水隔分，更為十二州，處所離遠，相制之道微也。」師古曰：「十二州謂冀、兗、豫、青、徐、荊、揚、雍、梁、幽、并、營也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_98_57","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「呼音火故反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_98_58","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「親謂愛養之。」","sentenceOrder":58},
  {"id":"s_work_han_thu_98_59","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「釋，解也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_98_60","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「殫，盡也，音單。」","sentenceOrder":60},
  {"id":"s_work_han_thu_98_61","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「古者行役不踰時。時謂三月，是為一（月）〔時〕。」","sentenceOrder":61},
  {"id":"s_work_han_thu_98_62","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　師古曰：「言免此疾患。」","sentenceOrder":62},
  {"id":"s_work_han_thu_98_63","chapterId":"ch_work_han_thu_98","textTraditional":"〔八〕　師古曰：「堯遭洪水，故云大災。」","sentenceOrder":63},
  {"id":"s_work_han_thu_98_64","chapterId":"ch_work_han_thu_98","textTraditional":"〔九〕　師古曰：「周書無逸之辭也。懷，和也。保，安也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_98_65","chapterId":"ch_work_han_thu_98","textTraditional":"臣聞災異，皇天所以譴告人君過失，猶嚴父之明誡。畏懼敬改，則禍銷福降；忽然簡易，則咎罰不除。經曰：「饗用五福，畏用六極。」〔一〕傳曰：「六沴作見，若不共御，六罰既侵，六極其下。」〔二〕今三年之間，災異鋒起，小大畢具，所行不享上帝，〔三〕上帝不豫，〔四〕炳然甚著。不求之身，無所改正，疏舉廣謀，又不用其言，〔五〕是循不享之跡，無謝過之實也，天責愈深。此五者，王事之綱紀，南面之急務，唯陛下留神。","sentenceOrder":65},
  {"id":"s_work_han_thu_98_66","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「周書洪範之辭。饗，當也。言所行當於天心，則降以五福；若所為不善，則以六極畏罰之。五福，一曰壽，二曰富，三曰康寧，四曰攸好德，五曰考終命。六極之解已具於前。」","sentenceOrder":66},
  {"id":"s_work_han_thu_98_67","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「此洪範之傳也。沴，災氣也。共讀曰恭。御讀曰禦。言敬而修德以禦災。」","sentenceOrder":67},
  {"id":"s_work_han_thu_98_68","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「享，當也。不當天心。」","sentenceOrder":68},
  {"id":"s_work_han_thu_98_69","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「豫，悅也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_98_70","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　晉灼曰：「疏，遠也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_98_71","chapterId":"ch_work_han_thu_98","textTraditional":"對奏，天子異焉，特召見永。","sentenceOrder":71},
  {"id":"s_work_han_thu_98_72","chapterId":"ch_work_han_thu_98","textTraditional":"其夏，皆令諸方正對策，語在杜欽傳。永對畢，因曰：「臣前幸得條對災異之效，禍亂所極，言關於聖聰。書陳於前，陛下委棄不納，而更使方正對策，背可懼之大異，問不急之常論，廢承天之至言，角無用之虛文，〔一〕欲末殺災異，滿讕誣天，〔二〕是故皇天勃然發怒，甲己之間暴風三溱，拔樹折木，〔三〕此天至明不可欺之效也。」上特復問永，永對曰：「日食地震，皇后貴妾專寵所致。」語在五行志。","sentenceOrder":72},
  {"id":"s_work_han_thu_98_73","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「角，竟也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_98_74","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「末殺，掃滅也。滿讕謂欺罔也。殺音先曷反。讕音來亶反。」","sentenceOrder":74},
  {"id":"s_work_han_thu_98_75","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「自甲至己，凡六日也。溱與臻同。臻，至也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_98_76","chapterId":"ch_work_han_thu_98","textTraditional":"是時，上初即位，謙讓委政元舅大將軍王鳳，議者多歸咎焉。永知鳳方見柄用，〔一〕陰欲自託，乃復曰：","sentenceOrder":76},
  {"id":"s_work_han_thu_98_77","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「言任用之授以權也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_98_78","chapterId":"ch_work_han_thu_98","textTraditional":"方今四夷賓服，皆為臣妾，北無薰粥冒頓之患，〔一〕南無趙佗、呂嘉之難，三垂晏然，靡有兵革之警。〔二〕諸侯大者乃食數縣，漢吏制其權柄，不得有為，亡吳、楚、燕、梁之勢。百官盤互，親疏相錯，〔三〕骨肉大臣有申伯之忠，〔四〕洞洞屬屬，小心畏忌，〔五〕無重合、安陽、博陸之亂。〔六〕三者無毛髮之辜，不可歸咎諸舅。此欲以政事過差丞相父子、中尚書宦官，檻塞大異，皆瞽說欺天者也。〔七〕竊恐陛下舍昭昭之白過，忽天地之明戒，聽晻昧之瞽說，〔八〕歸咎乎無辜，倚異乎政事，〔九〕重失天心，〔一０〕不可之大者也。〔一一〕","sentenceOrder":78},
  {"id":"s_work_han_thu_98_79","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「粥音（戈）〔弋〕六反。」","sentenceOrder":79},
  {"id":"s_work_han_thu_98_80","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「晏，安也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_98_81","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「盤互，盤結而交互也。錯，間雜也。互字或作牙，言如豕牙之盤曲，犬牙之相入也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_98_82","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「申伯，周申后之父。」","sentenceOrder":82},
  {"id":"s_work_han_thu_98_83","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「洞洞，驚肅也。屬屬，專謹也。洞音動。屬音之欲反。」","sentenceOrder":83},
  {"id":"s_work_han_thu_98_84","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「重合，莽通；安陽，上官桀；博陸，霍禹也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_98_85","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　師古曰：「檻，義取檻柙之檻。檻，猶閉也，其字從木。瞽說，言不中道，若無目之人也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_98_86","chapterId":"ch_work_han_thu_98","textTraditional":"〔八〕　師古曰：「舍謂留也。晻字與暗同，又音一感反。」","sentenceOrder":86},
  {"id":"s_work_han_thu_98_87","chapterId":"ch_work_han_thu_98","textTraditional":"〔九〕　師古曰：「倚，依也，音於綺反。次下亦同。」","sentenceOrder":87},
  {"id":"s_work_han_thu_98_88","chapterId":"ch_work_han_thu_98","textTraditional":"〔一０〕師古曰：「重音直用反。」","sentenceOrder":88},
  {"id":"s_work_han_thu_98_89","chapterId":"ch_work_han_thu_98","textTraditional":"〔一一〕師古曰：「此則為大不可也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_98_90","chapterId":"ch_work_han_thu_98","textTraditional":"陛下即位，委任遵舊，未有過政。元年正月，白氣較然起乎東方，〔一〕至其四月，黃濁四塞，覆冒京師，申以大水，著以震蝕。〔二〕各有占應，相為表裏，百官庶事無所歸倚，陛下獨不怪與？〔三〕白氣起東方，賤人將興之表也；黃濁冒京師，王道微絕之應也。夫賤人當起而京師道微，二者已醜。〔四〕陛下誠深察愚臣之言，致懼天地之異，長思宗廟之計，改往反過，抗湛溺之意，解偏駮之愛，〔五〕奮乾剛之威，平天覆之施，使列妾得人人更進，猶尚未足也，〔六〕急復益納宜子婦人，毋擇好醜，毋避嘗字，〔七〕毋論年齒。推法言之，陛下得繼嗣於微賤之間，乃反為福。得繼嗣而已，母非有賤也。〔八〕後宮女史使令有直意者，廣求於微賤之間，〔九〕以遇天所開右，〔一０〕慰釋皇太后之憂慍，〔一一〕解謝上帝之譴怒，則繼嗣蕃滋，災異訖息。〔一二〕陛下則不深察愚臣之言，忽於天地之戒，咎根不除，水雨之災，山石之異，將發不久；發則災異已極，天變成形，臣雖欲捐身關策，不及事已。〔一三〕","sentenceOrder":90},
  {"id":"s_work_han_thu_98_91","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「較，明貌。」","sentenceOrder":91},
  {"id":"s_work_han_thu_98_92","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「申，重也。著，明也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_98_93","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「倚音於綺反。與讀曰歟。」","sentenceOrder":93},
  {"id":"s_work_han_thu_98_94","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「已，甚也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_98_95","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「抗，舉也。湛讀曰沈。駮，不周普也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_98_96","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「更，互也，音工衡反。」","sentenceOrder":96},
  {"id":"s_work_han_thu_98_97","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　如淳曰：「王鳳上小妻弟以納後宮，以嘗字乳。王章言之，坐死。今永及此，為鳳洗前過也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_98_98","chapterId":"ch_work_han_thu_98","textTraditional":"〔八〕　師古曰：「苟得子耳，勿論其母之貴賤。」","sentenceOrder":98},
  {"id":"s_work_han_thu_98_99","chapterId":"ch_work_han_thu_98","textTraditional":"〔九〕　師古曰：「（求）〔直〕，當也。令音力成反。」","sentenceOrder":99},
  {"id":"s_work_han_thu_98_100","chapterId":"ch_work_han_thu_98","textTraditional":"〔一０〕師古曰：「右讀曰佑。佑，助也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_98_101","chapterId":"ch_work_han_thu_98","textTraditional":"〔一一〕師古曰：「釋，散也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_98_102","chapterId":"ch_work_han_thu_98","textTraditional":"〔一二〕師古曰：「蕃，多也。訖，止也。蕃音扶元反。」","sentenceOrder":102},
  {"id":"s_work_han_thu_98_103","chapterId":"ch_work_han_thu_98","textTraditional":"〔一三〕師古曰：「言禍敗既成，不可如何也。已，語終辭也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_98_104","chapterId":"ch_work_han_thu_98","textTraditional":"疏賤之臣，至敢直陳天意，斥譏帷幄之私，欲間離貴后盛妾，〔一〕自知忤心逆耳，必不免於湯鑊之誅。此天保右漢家，使臣敢直言也。〔二〕三上封事，然後得召；待詔一旬，然後得見。夫由疏賤納至忠，甚苦；〔三〕由至尊聞天意，甚難。語不可露，願具書所言，因侍中奏陛下，以示腹心大臣。〔四〕腹心大臣以為非天意，臣當伏妄言之誅；即以為誠天意也，奈何忘國家大本，背天意而從欲！〔五〕唯陛下省察熟念，厚為宗廟計。","sentenceOrder":104},
  {"id":"s_work_han_thu_98_105","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「間音居莧反。」","sentenceOrder":105},
  {"id":"s_work_han_thu_98_106","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「右讀曰佑。」","sentenceOrder":106},
  {"id":"s_work_han_thu_98_107","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「由，從也。苦，勞苦也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_98_108","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　如淳曰：「永為鳳言，而言示腹心大臣，無不可矣。」","sentenceOrder":108},
  {"id":"s_work_han_thu_98_109","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「從讀曰縱。」","sentenceOrder":109},
  {"id":"s_work_han_thu_98_110","chapterId":"ch_work_han_thu_98","textTraditional":"時對者數十人，永與杜欽為上第焉。上皆以其書示後宮。後上嘗賜許皇后書，采永言以責之，語在外戚傳。","sentenceOrder":110},
  {"id":"s_work_han_thu_98_111","chapterId":"ch_work_han_thu_98","textTraditional":"永既陰為大將軍鳳說矣，能實最高，由是擢為光祿大夫。永奏書謝鳳曰：「永斗筲之材，〔一〕質薄學朽，無一日之雅，左右之介，〔二〕將軍說其狂言，〔三〕擢之皂衣之吏，廁之爭臣之末，不聽浸潤之譖，不食膚受之愬，〔四〕雖齊桓晉文用士篤密，察父悊兄覆育子弟，誠無以加！〔五〕昔豫子吞炭壞形以奉見異，〔六〕齊客隕首公門以報恩施，〔七〕知氏、孟嘗猶有死士，何況將軍之門！」鳳遂厚之。","sentenceOrder":111},
  {"id":"s_work_han_thu_98_112","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「筲，竹器也。斗筲，喻小而不大也。解在公孫劉田傳。筲音所交反。」","sentenceOrder":112},
  {"id":"s_work_han_thu_98_113","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「雅，素也。介，紹也。言非宿素之交，又無介紹而進也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_98_114","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「說讀曰悅。」","sentenceOrder":114},
  {"id":"s_work_han_thu_98_115","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「食猶受納也。膚受，謂初入皮膚至骨髓，言其深也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_98_116","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「察，明也。悊，智也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_98_117","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「豫讓也。為智伯報讎，欲殺趙襄子，恐人識之，故吞炭以變其聲，釁面以壞其形，云『智伯國士遇我』故也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_98_118","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　師古曰：「舍人魏子三收邑入，不與孟嘗。孟嘗怒之，魏子曰：『假與賢者。』齊湣王受讒，孟嘗出奔，魏子所與粟賢者到宮門自剄，以明孟嘗之心。」","sentenceOrder":118},
  {"id":"s_work_han_thu_98_119","chapterId":"ch_work_han_thu_98","textTraditional":"數年，出為安定太守。時上諸舅皆修經書，任政事。平阿侯譚年次當繼大將軍鳳輔政，尤與永善。陽朔中，鳳薨。鳳病困，薦從弟御史大夫音以自代。上從之，以音為大司馬車騎將軍，領尚書事，而平阿侯譚位特進，領城門兵。永聞之，與譚書曰：「君侯躬周召之德，執管晏之操，〔一〕敬賢下士，樂善不倦，〔二〕宜在上將久矣，以大將軍在，故抑鬱於家，不得舒憤。今大將軍不幸蚤薨，〔三〕絫親疏，序材能，宜在君侯。〔四〕拜吏之日，京師士大夫悵然失望。此皆永等愚劣，不能褒揚萬（一）〔分〕。〔五〕屬聞以特進領城門兵，〔六〕是則車騎將軍秉政雍容于內，而至戚賢舅執管籥於外也。愚竊不為君侯喜。宜深辭職，自陳淺薄不足以固城門之守，收太伯之讓，保謙謙之路，〔七〕闔門高枕，為知者首。願君侯與博覽者參之，〔八〕小子為君侯安此。」譚得其書大感，遂辭讓不受領城門職。由是譚、音相與不平。","sentenceOrder":119},
  {"id":"s_work_han_thu_98_120","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「召讀曰邵。其下亦同。」","sentenceOrder":120},
  {"id":"s_work_han_thu_98_121","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「下音胡亞反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_98_122","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「蚤，古早字。」","sentenceOrder":122},
  {"id":"s_work_han_thu_98_123","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「絫，古累字。累親疏，謂積累其次而計之。」","sentenceOrder":123},
  {"id":"s_work_han_thu_98_124","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「言萬分之一。」","sentenceOrder":124},
  {"id":"s_work_han_thu_98_125","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「屬，近也，音之欲反。」","sentenceOrder":125},
  {"id":"s_work_han_thu_98_126","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　師古曰：「太伯，王季之兄也，讓不為嗣而適吳越。」","sentenceOrder":126},
  {"id":"s_work_han_thu_98_127","chapterId":"ch_work_han_thu_98","textTraditional":"〔八〕　師古曰：「參詳其事。」","sentenceOrder":127},
  {"id":"s_work_han_thu_98_128","chapterId":"ch_work_han_thu_98","textTraditional":"永遠為郡吏，恐為音所危，病滿三月免。音奏請永補營軍司馬，永數謝罪自陳，得轉為長史。","sentenceOrder":128},
  {"id":"s_work_han_thu_98_129","chapterId":"ch_work_han_thu_98","textTraditional":"音用從舅越親輔政，威權損於鳳時。永復說音曰：「將軍履上將之位，食膏腴之都，任周召之職，擁天下之樞，〔一〕可謂富貴之極，人臣無二，天下之責四面至矣，將何以居之？宜夙夜孳孳，〔二〕執伊尹之彊德，以守職匡上，誅惡不避親愛，舉善不避仇讎，以章至公，立信四方。〔三〕篤行三者，乃可以長堪重任，久享盛寵。〔四〕太白出西方六十日，法當參天，今已過期，〔五〕尚在桑榆之間，質弱而行遲，形小而光微。〔六〕熒惑角怒明大，逆行守尾。其逆，常也；守尾，變也。意豈將軍忘湛漸之義，委曲從順，〔七〕所執不彊，不廣用士，尚有好惡之忌，蕩蕩之德未純，〔八〕方與將相大臣乖離之萌也？何故始襲司馬之號，俄而金火並有此變？上天至明，不虛見異，唯將軍畏之慎之，深思其故，改求其路，以享天意。」音猶不平，薦永為護菀使者。","sentenceOrder":129},
  {"id":"s_work_han_thu_98_130","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「擁，持也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_98_131","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「孳孳，不怠也。孳與孜同。」","sentenceOrder":131},
  {"id":"s_work_han_thu_98_132","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「章，明也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_98_133","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「篤，厚也。享，當也。」","sentenceOrder":133},
  {"id":"s_work_han_thu_98_134","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　服虔曰：「太白出，當居天三分之一。已過期，言其行遲，在戌亥之間。」","sentenceOrder":134},
  {"id":"s_work_han_thu_98_135","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　如淳曰：「言其行遲象王音也。永見音為司馬，以疏間親，自以位過，故以太白喻司馬，司馬主兵故也。是永之佞曲從苟合也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_98_136","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　師古曰：「湛讀曰沈。漸讀曰潛。周書洪範曰：『沈潛剛克』，言人性沈密（謂）〔而〕潛深者，行之以剛則能堪也，故激勸之云爾。」","sentenceOrder":136},
  {"id":"s_work_han_thu_98_137","chapterId":"ch_work_han_thu_98","textTraditional":"〔八〕　師古曰：「此永自知有忤於音，故以斯言自救解。」","sentenceOrder":137},
  {"id":"s_work_han_thu_98_138","chapterId":"ch_work_han_thu_98","textTraditional":"音薨，成都侯商代為大司馬衛將軍，永乃遷為涼州刺史。奏事京師訖，當之部，時有黑龍見東萊，上使尚書問永，受所欲言。〔一〕永對曰：","sentenceOrder":138},
  {"id":"s_work_han_thu_98_139","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「永有所言，令尚書即受之。」","sentenceOrder":139},
  {"id":"s_work_han_thu_98_140","chapterId":"ch_work_han_thu_98","textTraditional":"輒上聞，〔一〕則商周不易姓而迭興，三正不變改而更用。〔二〕夏商之將亡也，行道之人皆知之，〔三〕晏然自以若天有日莫能危，〔四〕是故惡日廣而不自知，大命傾而不寤。易曰：「危者有其安者也，亡者保其存者也。」〔五〕陛下誠垂寬明之聽，無忌諱之誅，使芻蕘之臣得盡所聞於前，不懼於後患，直言之路開，則四方眾賢不遠千里，輻湊陳忠，群臣之上願，社稷之長福也。","sentenceOrder":140},
  {"id":"s_work_han_thu_98_141","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「如，若也。有即上聞。」","sentenceOrder":141},
  {"id":"s_work_han_thu_98_142","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「迭音徒結反。更音工衡反。」","sentenceOrder":142},
  {"id":"s_work_han_thu_98_143","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「凡在道路行者也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_98_144","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「自謂如日在天而無有能傷危也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_98_145","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「下繫之辭也。言安必思危，存不忘亡，乃得保其安存。」","sentenceOrder":145},
  {"id":"s_work_han_thu_98_146","chapterId":"ch_work_han_thu_98","textTraditional":"漢家行夏正，夏正色黑，黑龍，同姓之象也。〔一〕龍陽德，由小之大，〔二〕故為王者瑞應。未知同姓有見本朝無繼嗣之慶，多危殆之隙，欲因擾亂舉兵而起者邪？將動心冀為後者，殘賊不仁，若廣陵、昌邑之類？臣愚不能處也。〔三〕元年九月黑龍見，其晦，日有食之。今年二月己未夜星隕，乙酉，日有食之。六月之間，大異四發，二而同月，三代之末，春秋之亂，未嘗有也。臣聞三代所以隕社稷喪宗廟者，皆由婦人與群惡沈湎於酒。書曰：「乃用婦人之言，自絕于天；」〔四〕「四方之述逃多罪。是宗是長，是信是使。〔五〕」詩云：「燎之方陽，寧或滅之？赫赫宗周，褒姒滅之！」〔六〕易曰：「濡其首，有孚失是。」〔七〕秦所以二世十六年而亡者，養生泰奢，奉終泰厚也。二者陛下兼而有之，臣請略陳其效。","sentenceOrder":146},
  {"id":"s_work_han_thu_98_147","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　張晏曰：「夏以建寅為正，萬物在地中，色黑，今黑龍見，同姓象也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_98_148","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「言因小以至大。」","sentenceOrder":148},
  {"id":"s_work_han_thu_98_149","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「處謂斷決也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_98_150","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「今文周書泰誓之辭。婦人，妲己。言紂用妲己之言，自取殄滅，非天絕之。」","sentenceOrder":150},
  {"id":"s_work_han_thu_98_151","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「亦泰誓之辭也。宗，尊也。言紂容納逃亡多罪之人，親信使用，尊而長之。」","sentenceOrder":151},
  {"id":"s_work_han_thu_98_152","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「小雅正月之詩。滅亦滅也，言火燎方熾，寧有能滅之者乎？而宗周之盛，乃為褒姒所滅，怨其甚也。滅音呼悅反。」","sentenceOrder":152},
  {"id":"s_work_han_thu_98_153","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　師古曰：「未濟上九爻辭也。言耽樂無節，飲酒濡首，有信之道於是遂失也。濡，濕也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_98_154","chapterId":"ch_work_han_thu_98","textTraditional":"易曰「在中餽，無攸遂」，〔一〕言婦人不得與事也。〔二〕詩曰：「懿厥悊婦，為梟為鴟；」「匪降自天，生自婦人。」〔三〕建始、河平之際，許、班之貴，頃動前朝，〔四〕熏灼四方，賞賜無量，空虛內臧，女寵至極，不可上矣；〔五〕今之後起，天所不饗，什倍於前。〔六〕廢先帝法度，聽用其言，官秩不當，縱釋王誅，〔七〕驕其親屬，假之威權，從橫亂政，〔八〕刺舉之吏，莫敢奉憲。又以掖庭獄大為亂阱，〔九〕榜箠〈疒朁〉於炮格，〔一０〕絕滅人命，主為趙、李報德復怨，〔一一〕反除白罪，建治正吏，〔一二〕多繫無辜，掠立迫恐，〔一三〕至為人起責，分利受謝。〔一四〕生入死出者，不可勝數。是以日食再既，〔一五〕以昭其辜。〔一六〕","sentenceOrder":154},
  {"id":"s_work_han_thu_98_155","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「家人六二爻辭也。餽與饋同。饋，食也。言婦人之道居中主食，遜順而已，無所必遂。」","sentenceOrder":155},
  {"id":"s_work_han_thu_98_156","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「與讀曰豫。」","sentenceOrder":156},
  {"id":"s_work_han_thu_98_157","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「大雅瞻卬之詩。懿，美也。悊，智也。言幽王以悊婦為美，實乃為梟鴟也。婦謂褒姒也。梟鴟，惡聲之鳥，故以諭焉。又言此禍亂非從天而下，以寵褒姒之故，生此災耳。」","sentenceOrder":157},
  {"id":"s_work_han_thu_98_158","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「許皇后及班婕妤之家。」","sentenceOrder":158},
  {"id":"s_work_han_thu_98_159","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「上猶加也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_98_160","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　如淳曰：「謂趙、李本從卑賤起也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_98_161","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　師古曰：「縱，放也。釋，解也。王誅，謂王法當誅者。」","sentenceOrder":161},
  {"id":"s_work_han_thu_98_162","chapterId":"ch_work_han_thu_98","textTraditional":"〔八〕　師古曰：「從音子用反。橫音胡孟反。」","sentenceOrder":162},
  {"id":"s_work_han_thu_98_163","chapterId":"ch_work_han_thu_98","textTraditional":"〔九〕　師古曰：「穿地為坑阱以拘繫人也。亂者，言其非正而又多也。阱音材性反。」","sentenceOrder":163},
  {"id":"s_work_han_thu_98_164","chapterId":"ch_work_han_thu_98","textTraditional":"〔一０〕師古曰：「〈疒朁〉，痛也。炮格，紂所作刑也。膏塗銅柱，加之（以）火上，令罪人行其上，輒墮炭中，笑而以為樂。〈疒朁〉音千感反。」","sentenceOrder":164},
  {"id":"s_work_han_thu_98_165","chapterId":"ch_work_han_thu_98","textTraditional":"〔一一〕師古曰：「復亦報也，音扶福反。」","sentenceOrder":165},
  {"id":"s_work_han_thu_98_166","chapterId":"ch_work_han_thu_98","textTraditional":"〔一二〕師古曰：「反讀曰幡。罪之明白者反而除之，吏之公正者建議劾治也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_98_167","chapterId":"ch_work_han_thu_98","textTraditional":"〔一三〕師古曰：「掠笞服之，立其罪名。」","sentenceOrder":167},
  {"id":"s_work_han_thu_98_168","chapterId":"ch_work_han_thu_98","textTraditional":"〔一四〕師古曰：「言富賈有錢，假託其名，代之為主，放與它人，以取利息而共分之，或受報謝，別取財物。」","sentenceOrder":168},
  {"id":"s_work_han_thu_98_169","chapterId":"ch_work_han_thu_98","textTraditional":"〔一五〕孟康曰：「既，盡也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_98_170","chapterId":"ch_work_han_thu_98","textTraditional":"〔一六〕師古曰：「昭，明也。」","sentenceOrder":170},
  {"id":"s_work_han_thu_98_171","chapterId":"ch_work_han_thu_98","textTraditional":"王者必先自絕，然后天絕之。陛下棄萬乘之至貴，樂家人之賤事，〔一〕厭高美之尊號，好匹夫之卑字，〔二〕崇聚僄輕無義小人以為私客，〔三〕數離深宮之固，挺身晨夜，與群小相隨，〔四〕烏集雜會，飲醉吏民之家，〔五〕亂服共坐，流湎媟嫚，溷殽無別，閔免遁樂，晝夜在路。〔六〕典門戶奉宿衛之臣執干戈而守空宮，公卿百僚不知陛下所在，積數年矣。","sentenceOrder":171},
  {"id":"s_work_han_thu_98_172","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「謂私畜田及奴婢財物。」","sentenceOrder":172},
  {"id":"s_work_han_thu_98_173","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　孟康曰：「成帝好微行，更作私字以相呼。」","sentenceOrder":173},
  {"id":"s_work_han_thu_98_174","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「僄，疾也，音頻妙反，又音匹妙反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_98_175","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「挺。引也，音大鼎反。」","sentenceOrder":175},
  {"id":"s_work_han_thu_98_176","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「言聚散不恆，如烏鳥之集。」","sentenceOrder":176},
  {"id":"s_work_han_thu_98_177","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「閔免猶黽勉也。遁，流遁也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_98_178","chapterId":"ch_work_han_thu_98","textTraditional":"王者以民為基，民以財為本，財竭則下畔，下畔則上亡。是以明王愛養基本，不敢窮極，使民如承大祭。〔一〕今陛下輕奪民財，不愛民力，聽邪臣之計，去高敞初陵，捐十年功緒，〔二〕改作昌陵，反天地之性，因下為高，積土為山，發徒起邑，並治宮館，大興繇役，重增賦斂，徵（法）〔發〕如雨，〔三〕役百乾谿，費疑驪山，〔四〕靡敝天下，〔五〕五年不成而後反故，又廣盱營表，〔六〕發人冢墓，斷截骸骨，暴揚尸柩。百姓財竭力盡，愁恨感天，災異婁降，饑饉仍臻。〔七〕流散冗食，餧死於道，以百萬數。〔八〕公家無一年之畜，百姓無旬日之儲，〔九〕上下俱匱，無以相救。詩云：「殷監不遠，在夏后之世。」〔一０〕願陛下追觀夏、商、周、秦所以失之，以鏡考己行。〔一一〕有不合者，臣當伏妄言之誅！〔一二〕","sentenceOrder":178},
  {"id":"s_work_han_thu_98_179","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「言常畏慎。」","sentenceOrder":179},
  {"id":"s_work_han_thu_98_180","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「緒謂功作之端次。」","sentenceOrder":180},
  {"id":"s_work_han_thu_98_181","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「言其多也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_98_182","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「疑讀曰儗。儗，比也。言勞役之功百倍於楚靈王，費財之廣比於秦始皇。」","sentenceOrder":182},
  {"id":"s_work_han_thu_98_183","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「靡，散也，音式皮反。」","sentenceOrder":183},
  {"id":"s_work_han_thu_98_184","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　晉灼曰：「盱音吁。盱，大也。」","sentenceOrder":184},
  {"id":"s_work_han_thu_98_185","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　師古曰：「婁，古屢字也。仍，頻也。」","sentenceOrder":185},
  {"id":"s_work_han_thu_98_186","chapterId":"ch_work_han_thu_98","textTraditional":"〔八〕　師古曰：「冗亦散也。餧，餓也。冗音人勇反。餧音乃賄反。」","sentenceOrder":186},
  {"id":"s_work_han_thu_98_187","chapterId":"ch_work_han_thu_98","textTraditional":"〔九〕　師古曰：「畜讀曰蓄。」","sentenceOrder":187},
  {"id":"s_work_han_thu_98_188","chapterId":"ch_work_han_thu_98","textTraditional":"〔一０〕師古曰：「大雅蕩之詩也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_98_189","chapterId":"ch_work_han_thu_98","textTraditional":"〔一一〕師古曰：「鏡謂監照之。考，校也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_98_190","chapterId":"ch_work_han_thu_98","textTraditional":"〔一二〕師古曰：「言上之所為，違於節儉，皆與永言同。」","sentenceOrder":190},
  {"id":"s_work_han_thu_98_191","chapterId":"ch_work_han_thu_98","textTraditional":"漢興九世，百九十餘載，繼體之主七，皆承天順道，遵先祖法度，或以中興，或以治安。至於陛下，獨違道縱欲，輕身妄行，當盛壯之隆，無繼嗣之福，有危亡之憂，積失君道，不合天意，亦已多矣。為人後嗣，守人功業，如此，豈不負哉！方今社稷宗廟禍福安危之機在於陛下，陛下誠肯發明聖之德，昭然遠寤，畏此上天之威怒，深懼危亡之徵兆，蕩滌邪辟之惡志，〔一〕厲精致政，專心反道〔二〕，絕群小之私客，免不正之詔除，〔三〕悉罷北宮私奴車馬惰出之具，〔四〕克己復禮，毋貳微行出飲之過，〔五〕以防迫切之禍，深惟日食再既之意，抑損椒房玉堂之盛寵，〔六〕毋聽後宮之請謁，除掖庭之亂獄，出炮格之陷阱，誅戮邪佞之臣及左右執左道以事上者以塞天下之望，且寑初陵之作，止諸繕治宮室，闕更減賦，盡休力役，〔七〕存卹振捄困乏之人以弭遠方，〔八〕厲崇忠直，放退殘賊，無使素餐之吏久尸厚祿，以次貫行，固執無違，〔九〕夙夜孳孳，婁省無怠，〔一０〕舊衍畢改，新德既章，〔一一〕纖介之邪不復載心，則赫赫大異庶幾可銷，天命去就庶幾可復，〔一二〕社稷宗廟庶幾可保。唯陛下留神反覆，熟省臣言。臣幸得備邊部之吏，不知本朝失得，瞽言觸忌諱，罪當萬死。","sentenceOrder":191},
  {"id":"s_work_han_thu_98_192","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「辟讀曰僻。」","sentenceOrder":192},
  {"id":"s_work_han_thu_98_193","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「反猶還也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_98_194","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「除謂除補為官者。」","sentenceOrder":194},
  {"id":"s_work_han_thu_98_195","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「媠亦惰字耳。惰出，惰游也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_98_196","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「貳謂重為之也。論語稱孔子云顏回『不貳過』。」","sentenceOrder":196},
  {"id":"s_work_han_thu_98_197","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「椒房，皇后所居。玉堂，嬖幸之舍也。」","sentenceOrder":197},
  {"id":"s_work_han_thu_98_198","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　師古曰：「闕亦謂減削之。更謂更卒也，音工衡反。」","sentenceOrder":198},
  {"id":"s_work_han_thu_98_199","chapterId":"ch_work_han_thu_98","textTraditional":"〔八〕　師古曰：「捄，古救字也。弭，安也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_98_200","chapterId":"ch_work_han_thu_98","textTraditional":"〔九〕　師古曰：「貫，聯續也。謂上所陳眾條諸事，宜次第相續行之，不當更違異也。貫音工端反。」","sentenceOrder":200},
  {"id":"s_work_han_thu_98_201","chapterId":"ch_work_han_thu_98","textTraditional":"〔一０〕師古曰：「婁，古屢字也。屢省，屢自觀省也。」","sentenceOrder":201},
  {"id":"s_work_han_thu_98_202","chapterId":"ch_work_han_thu_98","textTraditional":"〔一一〕師古曰：「章，明也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_98_203","chapterId":"ch_work_han_thu_98","textTraditional":"〔一二〕師古曰：「去就者，言去離無德而就有德。」","sentenceOrder":203},
  {"id":"s_work_han_thu_98_204","chapterId":"ch_work_han_thu_98","textTraditional":"成帝性寬而好文辭，又久無繼嗣，數為微行，多近幸小臣，趙、李從微賤專寵，皆皇太后與諸舅夙夜所常憂。至親難數言，故推永等使因天變而切諫，勸上納用之。永自知有內應，展意無所依違，〔一〕每言事輒見答禮。〔二〕至上此對，上大怒。衛將軍商密擿永令發去。〔三〕上使侍御史收永，敕過交道廄者勿追。〔四〕御史不及永，還，上意亦解，自悔。明年，徵永為太中大夫，遷光祿大夫給事中。","sentenceOrder":204},
  {"id":"s_work_han_thu_98_205","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「展，申也。」","sentenceOrder":205},
  {"id":"s_work_han_thu_98_206","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「加禮而答之。」","sentenceOrder":206},
  {"id":"s_work_han_thu_98_207","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「擿謂發動之，音它歷反。」","sentenceOrder":207},
  {"id":"s_work_han_thu_98_208","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　晉灼曰：「交道廄去長安六十里，近延陵。」","sentenceOrder":208},
  {"id":"s_work_han_thu_98_209","chapterId":"ch_work_han_thu_98","textTraditional":"元延元年，為北地太守。時災異尤數，永當之官，上使衛尉淳于長受永所欲言。永對曰：","sentenceOrder":209},
  {"id":"s_work_han_thu_98_210","chapterId":"ch_work_han_thu_98","textTraditional":"臣永幸得以愚朽之材為太中大夫，備拾遺之臣，從朝者之後，進不能盡思納忠輔宣聖德，退無被堅執銳討不義之功，猥蒙厚恩，仍遷至北地太守。絕命隕首，身膏（草野）〔野草〕，不足以報塞萬分。陛下聖德寬仁，不遺易忘之臣，〔一〕垂周文之聽，下及芻蕘之愚，有詔使衛尉受臣永所欲言。臣聞事君之義，有言責者盡其忠〔二〕，有官守者修其職。臣永幸得免於言責之辜，有官守之任，〔三〕當畢力遵職，養綏百姓而已，〔四〕不宜復關得失之辭。忠臣之於上，志在過厚，是故遠不違君，死不忘國。昔史魚既沒，餘忠未訖，委柩後寑，以屍達誠；〔五〕汲黯身外思內，發憤舒憂，遺言李息〔六〕。經曰：「雖爾身在外，乃心無不在王室。」〔七〕臣永幸得給事中出入三年，雖執干戈守邊垂，思慕之心常存於省闥，是以敢越郡吏之職，陳累年之憂。","sentenceOrder":210},
  {"id":"s_work_han_thu_98_211","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「易忘，言其微賤不足記也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_98_212","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「謂職當諫爭。」","sentenceOrder":212},
  {"id":"s_work_han_thu_98_213","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「言不為諫官，但郡守耳。」","sentenceOrder":213},
  {"id":"s_work_han_thu_98_214","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「綏，安也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_98_215","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　如淳曰：「禮，大夫殯於正室，士於適室。韓非曰史魚卒，委柩後寑，衛君弔而問之，曰：『不能進蘧伯玉，退彌子瑕，以屍諫也。』」","sentenceOrder":215},
  {"id":"s_work_han_thu_98_216","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「謂論張湯也，事見黯傳。」","sentenceOrder":216},
  {"id":"s_work_han_thu_98_217","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　師古曰：「周書康王之誥也。言諸蕃屏之臣，身雖在外，其心常當忠篤而在王室。」","sentenceOrder":217},
  {"id":"s_work_han_thu_98_218","chapterId":"ch_work_han_thu_98","textTraditional":"臣聞天生蒸民，不能相治，〔一〕為立王者以統理之，方制海內非為天子，列土封疆非為諸侯，皆以為民也。垂三統，列三正，去無道，開有德，不私一姓，明天下乃天下之天下，非一人之天下也。王者躬行道德，承順天地，博愛仁恕，恩及行葦，〔二〕籍稅取民不過常法，宮室車服不踰制度，事節財足，黎庶和睦，則卦氣理效，五徵時序，百姓壽考，庶屮蕃滋，〔三〕符瑞並降，以昭保右。〔四〕失道妄行，逆天暴物，窮奢極欲，湛湎荒淫，〔五〕婦言是從，誅逐仁賢，離逖骨肉，群小用事，〔六〕峻刑重賦，百姓愁怨，則卦氣悖亂，咎徵著郵，〔七〕上天震怒，災異婁降，日月薄食，五星失行，山崩川潰，水泉踊出，妖孽並見，茀星耀光，〔八〕饑饉荐臻，百姓短折，萬物夭傷。終不改寤，惡洽變備，不復譴告，更命有德。詩云：「乃眷西顧，此惟予宅。」〔九〕","sentenceOrder":218},
  {"id":"s_work_han_thu_98_219","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「蒸，眾也。」","sentenceOrder":219},
  {"id":"s_work_han_thu_98_220","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「詩大雅行葦之篇曰『敦彼行葦，牛羊勿踐履』，言政化所及，仁道霑被，雖草木至賤，無所殘傷。」","sentenceOrder":220},
  {"id":"s_work_han_thu_98_221","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「庶，眾也。屮，古草字也。蕃，多也，音扶元反。」","sentenceOrder":221},
  {"id":"s_work_han_thu_98_222","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「保，安也。右，助也。言為天所安助也。右讀曰佑。」","sentenceOrder":222},
  {"id":"s_work_han_thu_98_223","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「湛讀曰沈。」","sentenceOrder":223},
  {"id":"s_work_han_thu_98_224","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「逖，遠也。」","sentenceOrder":224},
  {"id":"s_work_han_thu_98_225","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　師古曰：「悖，乖也。郵字與尤同。尤，過也。悖音布內反。」","sentenceOrder":225},
  {"id":"s_work_han_thu_98_226","chapterId":"ch_work_han_thu_98","textTraditional":"〔八〕　師古曰：「茀與孛同，音步內反。」","sentenceOrder":226},
  {"id":"s_work_han_thu_98_227","chapterId":"ch_work_han_thu_98","textTraditional":"〔九〕　師古曰：「大雅皇矣之詩也。言天以殷紂為惡不變，乃眷然西顧，見文王之德，而與之宅居也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_98_228","chapterId":"ch_work_han_thu_98","textTraditional":"夫去惡奪弱，遷命賢聖，天地之常經，百王之所同也。加以功德有厚薄，期質有修短，時世有中季，天道有盛衰。〔一〕陛下承八世之功業，當陽數之標季，〔二〕涉三七之節紀，〔三〕遭无妄之卦運，〔四〕直百六之災阨。〔五〕三難異科，雜焉同會。〔六〕建始元年以來二十載間，群災大異，交錯鋒起，多於春秋所書。八世著記，久不塞除，〔七〕重以今年正月己亥朔日有食之，〔八〕三朝之會，〔九〕四月丁酉四方眾星白晝流隕，七月辛未彗星橫天。乘三難之際會，畜眾多之災異，〔一０〕因之以饑饉，接之以不贍。彗星，極異也，土精所生，流隕之應出於飢變之後，兵亂作矣，厥期不久，隆德積善，懼不克濟。〔一一〕內則為深宮後庭將有驕臣悍妾醉酒狂悖卒起之敗，〔一二〕北宮苑囿街巷之中臣妾之家幽閒之處〔一三〕徵舒、崔杼之亂；〔一四〕外則為諸夏下土將有樊並、蘇令、陳勝、項梁奮臂之禍。內亂朝暮，日戒諸夏，〔一五〕舉兵以火角為期〔一六〕。安危之分界，宗廟之至憂，〔一七〕臣永所以破膽寒心，〔一八〕豫言之累年。下有其萌，然後變見於上，〔一九〕可不致慎！","sentenceOrder":228},
  {"id":"s_work_han_thu_98_229","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「中讀曰仲。」","sentenceOrder":229},
  {"id":"s_work_han_thu_98_230","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　孟康曰：「陽九之末季也。」師古曰：「標音必遙反。」","sentenceOrder":230},
  {"id":"s_work_han_thu_98_231","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　孟康曰：「至平帝乃三七二百一十歲之厄，今已涉向其節紀。」","sentenceOrder":231},
  {"id":"s_work_han_thu_98_232","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　應劭曰：「天必先雲而後雷，雷而後雨，而今無雲而雷。无妄者，無所望也。萬物无所望於天，災異之最大者也。」師古曰：「取易之无妄卦為義。」","sentenceOrder":232},
  {"id":"s_work_han_thu_98_233","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「直，當也。」","sentenceOrder":233},
  {"id":"s_work_han_thu_98_234","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「雜謂相參也。一曰雜音先合反。雜焉，總萃貌。」","sentenceOrder":234},
  {"id":"s_work_han_thu_98_235","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　李奇曰：「高祖以來至元帝，著記災異未塞除也。」","sentenceOrder":235},
  {"id":"s_work_han_thu_98_236","chapterId":"ch_work_han_thu_98","textTraditional":"〔八〕　師古曰：「重音直用反。」","sentenceOrder":236},
  {"id":"s_work_han_thu_98_237","chapterId":"ch_work_han_thu_98","textTraditional":"〔九〕　師古曰：「歲月日三者之始，故云三朝。」","sentenceOrder":237},
  {"id":"s_work_han_thu_98_238","chapterId":"ch_work_han_thu_98","textTraditional":"〔一０〕師古曰：「畜讀曰蓄。蓄，積聚也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_98_239","chapterId":"ch_work_han_thu_98","textTraditional":"〔一一〕師古曰：「修德積善尚恐不濟，況不隆不積者乎。」","sentenceOrder":239},
  {"id":"s_work_han_thu_98_240","chapterId":"ch_work_han_thu_98","textTraditional":"〔一二〕師古曰：「卒讀曰猝。」","sentenceOrder":240},
  {"id":"s_work_han_thu_98_241","chapterId":"ch_work_han_thu_98","textTraditional":"〔一三〕師古曰：「閒讀曰閑。」","sentenceOrder":241},
  {"id":"s_work_han_thu_98_242","chapterId":"ch_work_han_thu_98","textTraditional":"〔一四〕師古曰：「陳夏徵舒殺其君平國，齊崔杼弒其君光。」","sentenceOrder":242},
  {"id":"s_work_han_thu_98_243","chapterId":"ch_work_han_thu_98","textTraditional":"〔一五〕師古曰：「內亂，則禍在朝暮；諸夏，則日戒有兵。」","sentenceOrder":243},
  {"id":"s_work_han_thu_98_244","chapterId":"ch_work_han_thu_98","textTraditional":"〔一六〕張晏曰：「以熒惑芒角為期。」","sentenceOrder":244},
  {"id":"s_work_han_thu_98_245","chapterId":"ch_work_han_thu_98","textTraditional":"〔一七〕師古曰：「分音扶問反。」","sentenceOrder":245},
  {"id":"s_work_han_thu_98_246","chapterId":"ch_work_han_thu_98","textTraditional":"〔一八〕師古曰：「言懼甚。」","sentenceOrder":246},
  {"id":"s_work_han_thu_98_247","chapterId":"ch_work_han_thu_98","textTraditional":"〔一九〕師古曰：「萌謂事之始生，如草木萌牙者也。」","sentenceOrder":247},
  {"id":"s_work_han_thu_98_248","chapterId":"ch_work_han_thu_98","textTraditional":"禍起細微，姦生所易。〔一〕願陛下正君臣之義，無復與群小媟黷燕飲；〔二〕中黃門後庭素驕慢不謹嘗以醉酒失臣禮者，悉出勿留。勤三綱之嚴，修後宮之政，〔三〕抑遠驕妒之寵，崇近婉順之行，加惠失志之人，懷柔怨恨之心。〔四〕保至尊之重，秉帝王之威，朝覲法出而後駕，陳兵清道而後行，無復輕身獨出，飲食臣妾之家。三者既除，內亂之路塞矣。","sentenceOrder":248},
  {"id":"s_work_han_thu_98_249","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「易，輕也，音弋豉反。」","sentenceOrder":249},
  {"id":"s_work_han_thu_98_250","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「媟，狎也。黷，汙也。」","sentenceOrder":250},
  {"id":"s_work_han_thu_98_251","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「三綱，君臣、父子、夫婦也。」","sentenceOrder":251},
  {"id":"s_work_han_thu_98_252","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「懷，和也。」","sentenceOrder":252},
  {"id":"s_work_han_thu_98_253","chapterId":"ch_work_han_thu_98","textTraditional":"諸夏舉兵，萌在民饑饉而吏不卹，興於百姓困而賦斂重，發於下怨離而上不知。易曰：「屯其膏，小貞吉，大貞凶。」〔一〕傳曰：「飢而不損茲謂泰，厥災水，厥咎亡。」〔二〕訞辭曰：「關動牡飛，辟為無道，臣為非，厥咎亂臣謀篡。」〔三〕王者遭衰難之世，有飢饉之災，不損用而大自潤，故凶；百姓困貧無以共求，〔四〕愁悲怨恨，故水；城關守國之固，固將去焉，故牡飛。往年郡國二十一傷於水災，禾黍不入。今年蠶麥咸惡。百川沸騰，江河溢決，大水泛濫郡國十五有餘。比年喪稼，〔五〕時過無宿麥。〔六〕百姓失業流散，群輩守關。〔七〕大異較炳如彼，水災浩浩，黎庶窮困如此，宜損常稅小自潤之時，〔八〕而有司奏請加賦，甚繆經義，逆於民心，布怨趨禍之道也。牡飛之狀，殆為此發。古者穀不登虧膳，災婁至損服，凶年不塈塗，明王之制也。〔九〕詩云：「凡民有喪，扶服捄之。」〔一０〕論語曰：「百姓不足，君孰予足？」〔一一〕臣願陛下勿許加賦之奏，益減大官、導官、中御府、均官、掌畜、廩犧用度，止尚方、織室、京師郡國工服官發輸造作，以助大司農。流恩廣施，振贍困乏，開關梁，內流民，恣所欲之，〔一二〕以救其急。立春，遣使者循行風俗，宣布聖德，〔一三〕存卹孤寡，問民所苦，勞二千石，〔一四〕敕勸耕桑，毋奪農時，以慰綏元元之心，防塞大姦之隙。〔一五〕諸夏之亂，庶幾可息。","sentenceOrder":253},
  {"id":"s_work_han_thu_98_254","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　孟康曰：「膏者所以潤人肌膚，爵祿亦所以養人者也。小貞，臣也。大貞，君也。遭屯難飢荒，君當開倉廩，振百姓，而反吝，則凶；臣吝嗇，則吉。論語曰：『出內之吝，謂之有司。』」師古曰：「易屯卦九五爻辭。」","sentenceOrder":254},
  {"id":"s_work_han_thu_98_255","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「洪範傳之辭。」","sentenceOrder":255},
  {"id":"s_work_han_thu_98_256","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「易訞占之辭也。訞即妖字耳。」","sentenceOrder":256},
  {"id":"s_work_han_thu_98_257","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「共讀曰供。無以供在上之所求。」","sentenceOrder":257},
  {"id":"s_work_han_thu_98_258","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「比，頻也。」","sentenceOrder":258},
  {"id":"s_work_han_thu_98_259","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「時過者，失時不得種也。秋種夏收，故云宿麥。」","sentenceOrder":259},
  {"id":"s_work_han_thu_98_260","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　如淳曰：「欲入就賤穀也。」","sentenceOrder":260},
  {"id":"s_work_han_thu_98_261","chapterId":"ch_work_han_thu_98","textTraditional":"〔八〕　師古曰：「言所潤益於己者，當減小之。」","sentenceOrder":261},
  {"id":"s_work_han_thu_98_262","chapterId":"ch_work_han_thu_98","textTraditional":"〔九〕　師古曰：「塈，如今仰泥屋也，音許既反。」","sentenceOrder":262},
  {"id":"s_work_han_thu_98_263","chapterId":"ch_work_han_thu_98","textTraditional":"〔一０〕師古曰：「邶國谷風之詩。服音蒲北反。捄，古救字。」","sentenceOrder":263},
  {"id":"s_work_han_thu_98_264","chapterId":"ch_work_han_thu_98","textTraditional":"〔一一〕師古曰：「論語載有若對魯哀公之辭也。言百姓不足，君安得獨足乎？」","sentenceOrder":264},
  {"id":"s_work_han_thu_98_265","chapterId":"ch_work_han_thu_98","textTraditional":"〔一二〕師古曰：「之，往也。」","sentenceOrder":265},
  {"id":"s_work_han_thu_98_266","chapterId":"ch_work_han_thu_98","textTraditional":"〔一三〕師古曰：「行音下更反。」","sentenceOrder":266},
  {"id":"s_work_han_thu_98_267","chapterId":"ch_work_han_thu_98","textTraditional":"〔一四〕師古曰：「勞，慰勉也。二千石，謂郡守、諸侯相也，音來到反。」","sentenceOrder":267},
  {"id":"s_work_han_thu_98_268","chapterId":"ch_work_han_thu_98","textTraditional":"〔一五〕師古曰：「綏，安也。」","sentenceOrder":268},
  {"id":"s_work_han_thu_98_269","chapterId":"ch_work_han_thu_98","textTraditional":"臣聞上主可與為善而不可與為惡，下主可與為惡而不可與為善。陛下天然之性，疏通聰敏，上主之姿也。〔一〕少省愚臣之言，感寤三難，〔二〕深畏大異，定心為善，捐忘邪志，毋貳舊愆，厲精致（改）〔政〕，至誠應天，則積異塞於上，禍亂伏於下，何憂患之有？竊恐陛下公志未專，私好頗存，尚愛群小，不肯為耳！","sentenceOrder":269},
  {"id":"s_work_han_thu_98_270","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「姿，材也。」","sentenceOrder":270},
  {"id":"s_work_han_thu_98_271","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「省，視也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_98_272","chapterId":"ch_work_han_thu_98","textTraditional":"對奏，天子甚感其言。","sentenceOrder":272},
  {"id":"s_work_han_thu_98_273","chapterId":"ch_work_han_thu_98","textTraditional":"永於經書，汎為疏達，〔一〕與杜欽、杜鄴略等，不能洽浹如劉向父子及揚雄也。其於天官、京氏易最密，故善言災異，前後所上四十餘事，略相反覆，專攻上身與後宮而已。黨於王氏，上亦知之，不甚親信也。","sentenceOrder":273},
  {"id":"s_work_han_thu_98_274","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「汎，普也，音敷劍反。」","sentenceOrder":274},
  {"id":"s_work_han_thu_98_275","chapterId":"ch_work_han_thu_98","textTraditional":"永所居任職，〔一〕為北地太守歲餘，衛將軍商薨，曲陽侯根為票騎將軍，薦永，徵入為大司農。歲餘，永病，三月，有司奏請免。故事，公卿病，輒賜告，至永獨即時免。數月，卒於家。本名並，以尉氏樊並反，更名永云。","sentenceOrder":275},
  {"id":"s_work_han_thu_98_276","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「言所處之官皆稱職。」","sentenceOrder":276},
  {"id":"s_work_han_thu_98_277","chapterId":"ch_work_han_thu_98","textTraditional":"杜鄴字子夏，本魏郡繁陽人也。祖父及父積功勞皆至郡守，武帝時徙茂陵。鄴少孤，其母張敞女。鄴壯，從敞子吉學問，得其家書。以孝廉為郎。","sentenceOrder":277},
  {"id":"s_work_han_thu_98_278","chapterId":"ch_work_han_thu_98","textTraditional":"與車騎將軍王音善。平阿侯譚不受城門職，後薨，上閔悔之，乃復令譚弟成都侯商位特進，領城門兵，得舉吏如將軍府。鄴見音前與平阿有隙，即說音曰：「鄴聞人情，恩深者其養謹，愛至者其求詳。〔一〕夫戚而不見殊，孰能無怨？〔二〕此棠棣、角弓之詩所為作也。〔三〕昔秦伯有千乘之國，而不能容其母弟，春秋亦書而譏焉〔四〕。周召則不然，〔五〕忠以相輔，義以相匡，同己之親，等己之尊，不以聖德獨兼國寵，又不為長專受榮任，分職於陝，並為弼疑〔六〕。故內無感恨之隙，外無侵侮之羞，〔七〕俱享天祐，兩荷高名者，蓋以此也。竊見成都侯以特進領城門兵，復有詔得舉吏如五府，此明詔所欲寵也。將軍宜承順聖意，加異往時，每事凡議，必與及之，指為誠發，出於將軍，則孰敢不說諭？〔八〕昔文侯寤大鴈之獻而父子益親，〔九〕陳平共壹飯之篹而將相加驩，〔一０〕所接雖在楹階俎豆之間，其於為國折衝厭難，豈不遠哉！〔一一〕竊慕倉唐、陸子之義，所白奥內，唯深察焉。」〔一二〕音甚嘉其言，由是與成都侯商親密，二人皆重鄴。後以病去郎。商為大司馬衛將軍，除鄴主簿，以為腹心，舉侍御史。哀帝即位，遷為涼州刺史。鄴居職寬舒，少威嚴，數年以病免。","sentenceOrder":278},
  {"id":"s_work_han_thu_98_279","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「詳，悉也。」","sentenceOrder":279},
  {"id":"s_work_han_thu_98_280","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「戚，近也。殊謂異於疏也。」","sentenceOrder":280},
  {"id":"s_work_han_thu_98_281","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「棠棣、角弓皆小雅篇名也。棠棣美燕兄弟，角弓刺不親九族也。」","sentenceOrder":281},
  {"id":"s_work_han_thu_98_282","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「秦景公母弟公子鍼有寵於其父桓公，景公立，鍼懼而奔晉。事在昭元年，故經書『秦伯之弟鍼出奔晉』。傳曰『稱弟，罪秦伯也』。」","sentenceOrder":282},
  {"id":"s_work_han_thu_98_283","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「言周公召公無私怨也。」","sentenceOrder":283},
  {"id":"s_work_han_thu_98_284","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「分職於陝，謂自陝以東周公主之，自陝以西召公主之。陝即今陝州縣也，音式冉反。而說者妄云分郟是潁川郟縣，繆矣。弼疑，謂左輔右弼前疑後承也。」","sentenceOrder":284},
  {"id":"s_work_han_thu_98_285","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　師古曰：「感音胡闇反。」","sentenceOrder":285},
  {"id":"s_work_han_thu_98_286","chapterId":"ch_work_han_thu_98","textTraditional":"〔八〕　師古曰：「言此之意指皆出忠誠，彼必和悅，無憂乖異也。說讀曰悅。」","sentenceOrder":286},
  {"id":"s_work_han_thu_98_287","chapterId":"ch_work_han_thu_98","textTraditional":"〔九〕　師古曰：「魏文侯廢太子擊，立擊弟訢，封擊於中山，三年不往來。擊臣趙倉唐進大鴈於文侯，應對以禮，文侯感寤，廢訢而召立擊，父子更親也。」","sentenceOrder":287},
  {"id":"s_work_han_thu_98_288","chapterId":"ch_work_han_thu_98","textTraditional":"〔一０〕師古曰：「陳平用陸賈說，以五百金為絳侯具食是也。共讀曰供。」","sentenceOrder":288},
  {"id":"s_work_han_thu_98_289","chapterId":"ch_work_han_thu_98","textTraditional":"〔一一〕師古曰：「厭音一葉反。」","sentenceOrder":289},
  {"id":"s_work_han_thu_98_290","chapterId":"ch_work_han_thu_98","textTraditional":"〔一二〕師古曰：「奥內，室中隱奥之處也。」","sentenceOrder":290},
  {"id":"s_work_han_thu_98_291","chapterId":"ch_work_han_thu_98","textTraditional":"是時，帝祖母定陶傅太后稱皇太太后，帝母丁姬稱帝太后，而皇后即傅太后從弟子也。傅氏侯者三人，丁氏侯者二人。又封傅太后同母弟子鄭業為陽信侯。傅太后尤與政專權。〔一〕元壽元年正月朔，上以皇后父孔鄉侯傅晏為大司馬衛將軍，而帝舅陽安侯丁明為大司馬票騎將軍。臨拜，日食，詔舉方正直言。扶陽侯韋育舉鄴方正，鄴對曰：","sentenceOrder":291},
  {"id":"s_work_han_thu_98_292","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「與讀曰豫。」","sentenceOrder":292},
  {"id":"s_work_han_thu_98_293","chapterId":"ch_work_han_thu_98","textTraditional":"臣聞禽息憂國，碎首不恨；〔一〕卞和獻寶，刖足願之〔二〕。臣幸得奉直言之詔，無二者之危，敢不極陳！臣聞陽尊陰卑，卑者隨尊，尊者兼卑，天之道也。是以男雖賤，各為其家陽；女雖貴，猶為其國陰。故禮明三從之義，〔三〕雖有文母之德，必繫於子〔四〕。春秋不書紀侯之母，陰義殺也。〔五〕昔鄭伯隨姜氏之欲，終有叔段篡國之禍；周襄王內迫惠后之難，而遭居鄭之危。〔六〕漢興，呂太后權私親屬，又以外孫為孝惠后，是時繼嗣不明，凡事多晻〔七〕，晝昏冬雷之變，不可勝載。竊見陛下行不偏之政，每事約儉，非禮不動，誠欲正身與天下更始也。然嘉瑞未應，而日食地震，民訛言行籌，傳相驚恐。案春秋災異，以指象為言語，〔八〕故在於得一類而達之也。日食，明陽為陰所臨，坤卦乘離，明夷之象也。〔九〕坤以法地，為土為母，以安靜為德。震，不陰之效也。〔一０〕占象甚明，臣敢不直言其事！","sentenceOrder":293},
  {"id":"s_work_han_thu_98_294","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　應劭曰：「禽息，秦大夫，薦百里奚而不見納。繆公出，當車以頭擊闑，腦乃播出，曰『臣生無補於國而不如死也！』繆公感寤而用百里奚，秦以大治。」","sentenceOrder":294},
  {"id":"s_work_han_thu_98_295","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「解在鄒陽傳。」","sentenceOrder":295},
  {"id":"s_work_han_thu_98_296","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「謂婦人在家從父，既嫁從夫，夫死從子。」","sentenceOrder":296},
  {"id":"s_work_han_thu_98_297","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「文母，文王之妃太姒也。」","sentenceOrder":297},
  {"id":"s_work_han_thu_98_298","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「隱（三）〔二〕年『紀侯使（履）〔裂〕繻來逆女』。公羊傳曰『婚禮不稱主人』，主人謂婿也。『不稱母，母不通也。』殺謂減降也，音所例反。」","sentenceOrder":298},
  {"id":"s_work_han_thu_98_299","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「解並在前。」","sentenceOrder":299},
  {"id":"s_work_han_thu_98_300","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　師古曰：「晻與暗同。」","sentenceOrder":300},
  {"id":"s_work_han_thu_98_301","chapterId":"ch_work_han_thu_98","textTraditional":"〔八〕　師古曰：「謂天不言，但以景象指意告喻人。」","sentenceOrder":301},
  {"id":"s_work_han_thu_98_302","chapterId":"ch_work_han_thu_98","textTraditional":"〔九〕　應劭曰：「明夷之卦：『上六，不明晦，初登于天，後入于地。』明夷者，明傷也。初登于天者，初為天子，言以善聞于天也。後入于地者，傷賢害仁，佞惡在朝，必以惡終入于地也。」","sentenceOrder":302},
  {"id":"s_work_han_thu_98_303","chapterId":"ch_work_han_thu_98","textTraditional":"〔一０〕師古曰：「言地當安靜而今乃震，是為不遵陰道也。」","sentenceOrder":303},
  {"id":"s_work_han_thu_98_304","chapterId":"ch_work_han_thu_98","textTraditional":"昔曾子問從令之義，孔子曰：「是何言與！」〔一〕善閔子騫守禮不苟，從親所行，無非理者，故無可間也。〔二〕前大司馬新都侯莽退伏弟家，以詔策決，復遣就國。高昌侯宏去蕃自絕，猶受封土。〔三〕制書侍中駙馬都尉遷不忠巧佞，免歸故郡，〔四〕間未旬月，則有詔還，大臣奏正其罰，卒不得遣，而反兼官奉使，顯寵過故。及陽信侯業，皆緣私君國，非功義所止。〔五〕諸外家昆弟無賢不肖，並侍帷幄，布在列位，〔六〕或典兵衛，或將軍屯，寵意并於一家，積貴之勢，世所希見所希聞也。至乃并置大司馬將軍之官。皇甫雖盛，三桓雖隆，魯為作三軍，無以甚此。當拜之日，晻然日食〔七〕。不在前後，臨事而發者，明陛下謙遜無專，承指非一，所言輒聽，所欲輒隨，〔八〕有罪惡者不坐辜罰，無功能者畢受官爵，流漸積猥，正尤在是，〔九〕欲令昭昭以覺聖朝。昔詩人所刺，春秋所譏，指象如此，殆不在它。由後視前，忿邑非之，〔一０〕逮身所行，不自鏡見，則以為可，計之過者。〔一一〕疏賤獨偏見，疑內亦有此類。〔一二〕天變不空，保右世主如此之至，奈何不應！〔一三〕","sentenceOrder":304},
  {"id":"s_work_han_thu_98_305","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「曾子問子：『從父之令，可謂孝乎？』孔子非之。事見孝經。與讀曰歟。」","sentenceOrder":305},
  {"id":"s_work_han_thu_98_306","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「論語稱孔子曰『孝哉閔子騫，人不間於其父母昆弟之言』是也。間音居莧反。」","sentenceOrder":306},
  {"id":"s_work_han_thu_98_307","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「董宏也。」","sentenceOrder":307},
  {"id":"s_work_han_thu_98_308","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「傅遷也。」","sentenceOrder":308},
  {"id":"s_work_han_thu_98_309","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「謂緣私恩而得封爵為一國之君耳，非有功而侯也。」","sentenceOrder":309},
  {"id":"s_work_han_thu_98_310","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「不問賢與不肖，皆親近在位。」","sentenceOrder":310},
  {"id":"s_work_han_thu_98_311","chapterId":"ch_work_han_thu_98","textTraditional":"〔七〕　師古曰：「晻音烏感反。」","sentenceOrder":311},
  {"id":"s_work_han_thu_98_312","chapterId":"ch_work_han_thu_98","textTraditional":"〔八〕　師古曰：「謂皆迫於太后也。」","sentenceOrder":312},
  {"id":"s_work_han_thu_98_313","chapterId":"ch_work_han_thu_98","textTraditional":"〔九〕　師古曰：「尤，過也。言過惡正在於此。」","sentenceOrder":313},
  {"id":"s_work_han_thu_98_314","chapterId":"ch_work_han_thu_98","textTraditional":"〔一０〕師古曰：「由，從也。邑，於邑也。」","sentenceOrder":314},
  {"id":"s_work_han_thu_98_315","chapterId":"ch_work_han_thu_98","textTraditional":"〔一一〕師古曰：「逮，及也。鏡，鑒照也。自以所行為可，是計策之誤也。」","sentenceOrder":315},
  {"id":"s_work_han_thu_98_316","chapterId":"ch_work_han_thu_98","textTraditional":"〔一二〕如淳曰：「在外而賤舉錯有過失，為主上所疑也。」師古曰：「此說非也。言天子不自見其過。疏賤獨偏見，鄴自謂傍觀而見之也。疑內亦有此類，謂後宮嬖幸非理寵遇，亦有如傅遷、鄭業等妄受恩賞者。」","sentenceOrder":316},
  {"id":"s_work_han_thu_98_317","chapterId":"ch_work_han_thu_98","textTraditional":"〔一三〕（應劭）〔師古〕曰：「右讀曰佑。應謂應天戒而修德政。」","sentenceOrder":317},
  {"id":"s_work_han_thu_98_318","chapterId":"ch_work_han_thu_98","textTraditional":"臣聞野雞著怪，高宗深動；〔一〕大風暴過，成王怛然〔二〕。願陛下加致精誠，思承始初，事稽諸古，〔三〕以厭下心，〔四〕則黎庶群生無不說喜，〔五〕上帝百神收還威怒，禎祥福祿何嫌不報！〔六〕","sentenceOrder":318},
  {"id":"s_work_han_thu_98_319","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「謂雉升鼎耳，故懼而修德，解在五行志。」","sentenceOrder":319},
  {"id":"s_work_han_thu_98_320","chapterId":"ch_work_han_thu_98","textTraditional":"〔二〕　師古曰：「謂成王信流言而疑周公，天乃雷電以風，禾盡偃，大木斯拔，王乃啟金縢之書，悔而還周公。」","sentenceOrder":320},
  {"id":"s_work_han_thu_98_321","chapterId":"ch_work_han_thu_98","textTraditional":"〔三〕　師古曰：「每事皆考於古昔。」","sentenceOrder":321},
  {"id":"s_work_han_thu_98_322","chapterId":"ch_work_han_thu_98","textTraditional":"〔四〕　師古曰：「厭，滿也，音一贍反。」","sentenceOrder":322},
  {"id":"s_work_han_thu_98_323","chapterId":"ch_work_han_thu_98","textTraditional":"〔五〕　師古曰：「說讀曰悅。」","sentenceOrder":323},
  {"id":"s_work_han_thu_98_324","chapterId":"ch_work_han_thu_98","textTraditional":"〔六〕　師古曰：「嫌，疑也。」","sentenceOrder":324},
  {"id":"s_work_han_thu_98_325","chapterId":"ch_work_han_thu_98","textTraditional":"鄴未拜，病卒。鄴言民訛言行籌，及谷永言王者買私田，彗星隕石牡飛之占，語在五行志。","sentenceOrder":325},
  {"id":"s_work_han_thu_98_326","chapterId":"ch_work_han_thu_98","textTraditional":"初，鄴從張吉學，吉子竦又幼孤，從鄴學問，亦著於世，尤長小學。〔一〕鄴子林，清靜好古，亦有雅材，建武中歷位列卿，至大司空。其正文字過於鄴、竦，故世言小學者由杜公。","sentenceOrder":326},
  {"id":"s_work_han_thu_98_327","chapterId":"ch_work_han_thu_98","textTraditional":"〔一〕　師古曰：「小學，謂文字之學也。周禮『八歲入小學，保氏教國子以六書』，故因名云。」","sentenceOrder":327},
  {"id":"s_work_han_thu_98_328","chapterId":"ch_work_han_thu_98","textTraditional":"贊曰：孝成之世，委政外家，諸舅持權，重於丁、傅在孝哀時。故杜鄴敢譏丁、傅，而欽、永不敢言王氏，其勢然也。及欽欲挹損鳳權，而鄴附會音、商。永陳三七之戒，斯為","sentenceOrder":328},
  {"id":"s_work_han_thu_99_1","chapterId":"ch_work_han_thu_99","textTraditional":"何武字君公，蜀郡郫縣人也。〔一〕宣帝時，天下和平，四夷賓服，神爵、五鳳之間婁蒙瑞應。〔二〕而益州刺史王襄使辯士王褒頌漢德，作中和、樂職、宣布詩三篇。〔三〕武年十四五，與成都楊覆眾等共習歌之。是時，宣帝循武帝故事，求通達茂異士，召見武等於宣室。〔四〕上曰：「此盛德之事，吾何足以當之哉！」以褒為待詔，武等賜帛罷。","sentenceOrder":1},
  {"id":"s_work_han_thu_99_2","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「郫音疲。」","sentenceOrder":2},
  {"id":"s_work_han_thu_99_3","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「婁，古屢字也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_99_4","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「中和者，言政教隆平，得中和之道也。樂職，謂百官萬姓樂得其常道也。宣布，德化周洽，遍於四海也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_99_5","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「殿名也，解在賈誼傳。」","sentenceOrder":5},
  {"id":"s_work_han_thu_99_6","chapterId":"ch_work_han_thu_99","textTraditional":"武詣博士受業，治易。以射策甲科為郎，與翟方進交志相友。光祿勳舉四行，〔一〕遷為鄠令，坐法免歸。","sentenceOrder":6},
  {"id":"s_work_han_thu_99_7","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「元帝永光元年詔舉質樸、敦厚、遜讓、有行義各一人。時詔書又令光祿歲以此科第郎從官，故武以此四行得舉之也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_99_8","chapterId":"ch_work_han_thu_99","textTraditional":"武兄弟五人，皆為郡吏，郡縣敬憚之。武弟顯家有巿籍，租常不入，縣數負其課。〔一〕巿嗇夫求商捕辱顯家，〔二〕顯怒，欲以吏事中商。〔三〕武曰：「以吾家租賦繇役不為眾先，奉公吏不亦宜乎！」武卒白太守，召商為卒吏，州里聞之皆服焉。","sentenceOrder":8},
  {"id":"s_work_han_thu_99_9","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「以顯家不入租，故每令縣負課殿。」","sentenceOrder":9},
  {"id":"s_work_han_thu_99_10","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「求，姓；商，名也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_99_11","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「中傷之也，又音竹仲反。」","sentenceOrder":11},
  {"id":"s_work_han_thu_99_12","chapterId":"ch_work_han_thu_99","textTraditional":"久之，太僕王音舉武賢良方正，徵對策，拜為諫大夫，遷揚州刺史。所舉奏二千石長吏必先露章，服罪者為虧除，免之而已；〔一〕不服，極法奏之，抵罪或至死。","sentenceOrder":12},
  {"id":"s_work_han_thu_99_13","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「虧，減也。減（係）〔除〕其狀，直令免去也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_99_14","chapterId":"ch_work_han_thu_99","textTraditional":"九江太守戴聖，禮經號小戴者也，行治多不法，前刺史以其大儒，優容之。及武為刺史，行部錄囚徒，有所舉以屬郡。〔一〕聖曰：「後進生何知，乃欲亂人治！」〔二〕皆無所決。武使從事廉得其罪，〔三〕聖懼，自免。後為博士，毀武於朝廷。武聞之，終不揚其惡。而聖子賓客為群盜，得，〔四〕繫廬江，聖自以子必死。武平心決之，卒得不死。自是後，聖慚服。武每奏事至京師，〔五〕聖未嘗不造門謝恩。〔六〕","sentenceOrder":14},
  {"id":"s_work_han_thu_99_15","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「屬，委也，音之欲反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_99_16","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「言武仕學未久，故謂之後進生也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_99_17","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「廉，察也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_99_18","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「聚為群盜而吏捕得也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_99_19","chapterId":"ch_work_han_thu_99","textTraditional":"〔五〕　師古曰：「刺史每歲盡，則入奏事於京師也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_99_20","chapterId":"ch_work_han_thu_99","textTraditional":"〔六〕　師古曰：「造，至也，音千到反。」","sentenceOrder":20},
  {"id":"s_work_han_thu_99_21","chapterId":"ch_work_han_thu_99","textTraditional":"武為刺史，二千石有罪，應時舉奏，其餘賢與不肖敬之如一，是以郡國各重其守相，州中清平。行部必先即學官見諸生，〔一〕試其誦論，問以得失，然後入傳舍，出記問墾田頃畝，五穀美惡，〔二〕已乃見二千石，以為常。〔三〕","sentenceOrder":21},
  {"id":"s_work_han_thu_99_22","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「即，就也。學官，學舍也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_99_23","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「記謂教命之書。」","sentenceOrder":23},
  {"id":"s_work_han_thu_99_24","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「常依次第也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_99_25","chapterId":"ch_work_han_thu_99","textTraditional":"初，武為郡吏時，事太守何壽。壽知武有宰相器，以其同姓故厚之。後壽為大司農，其兄子為廬江長史。時武奏事在邸，壽兄子適在長安，壽為具召武弟顯及故人楊覆眾等，〔一〕酒酣，見其兄子〔二〕，曰：「此子揚州長史，〔三〕材能駑下，未嘗省見。」〔四〕顯等甚慚，退以謂武，武曰：「刺史古之方伯，上所委任，一州表率也，職在進善退惡。吏治行有茂異，民有隱逸，乃當召見，不可有所私問。」顯、覆眾強之，不得已召見，賜卮酒。〔五〕歲中，廬江太守舉之。〔六〕其守法見憚如此。","sentenceOrder":25},
  {"id":"s_work_han_thu_99_26","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「具謂酒食之具也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_99_27","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「令出見顯等。」","sentenceOrder":27},
  {"id":"s_work_han_thu_99_28","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「言揚州部內長史也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_99_29","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「省，視也。言不為武所識拔也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_99_30","chapterId":"ch_work_han_thu_99","textTraditional":"〔五〕　師古曰：「對賜一卮之酒也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_99_31","chapterId":"ch_work_han_thu_99","textTraditional":"〔六〕　師古曰：「終得武之力助也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_99_32","chapterId":"ch_work_han_thu_99","textTraditional":"為刺史五歲，入為丞相司直，丞相薛宣敬重之。出為清河太守，數歲，坐郡中被災害什四以上免。久之，大司馬曲陽侯王根薦武，徵為諫大夫。遷兗州刺史，入為司隸校尉，徙京兆尹。二歲，坐舉方正所舉者召見槃辟雅拜，〔一〕有司以為詭眾虛偽。〔二〕武坐左遷楚內史，遷沛郡太守，復入為廷尉。綏和（三）〔元〕年，御史大夫孔光左遷廷尉，武為御史大夫。成帝欲修辟雍，通三公官，〔三〕即改御史大夫為大司空。〔四〕武更為大司空，封氾鄉侯，食邑千戶。氾鄉在琅邪不其，〔五〕哀帝初即位，褒賞大臣，更以南陽犨之博望鄉為氾鄉侯國，〔六〕增邑千戶。","sentenceOrder":32},
  {"id":"s_work_han_thu_99_33","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　服虔曰：「行禮容拜也。」師古曰：「槃辟猶言槃旋也。辟音闢。」","sentenceOrder":33},
  {"id":"s_work_han_thu_99_34","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「詭，違也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_99_35","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「通，開也，謂更開置之。」","sentenceOrder":35},
  {"id":"s_work_han_thu_99_36","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「就其所任之人而并官俱改，不別拜授也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_99_37","chapterId":"ch_work_han_thu_99","textTraditional":"〔五〕　師古曰：「為後改食博望鄉，故此指言在琅邪不其也。氾音凡。其音基。」","sentenceOrder":37},
  {"id":"s_work_han_thu_99_38","chapterId":"ch_work_han_thu_99","textTraditional":"〔六〕　師古曰：「犨音昌牛反。」","sentenceOrder":38},
  {"id":"s_work_han_thu_99_39","chapterId":"ch_work_han_thu_99","textTraditional":"武為人仁厚，好進士，獎稱人之善。〔一〕為楚內史厚兩龔，在沛郡厚兩唐，〔二〕及為公卿，薦之朝廷。此人顯於世者，何侯力也，世以此多焉。〔三〕然疾朋黨，問文吏必於儒者，問儒者必於文吏，以相參檢。欲除吏，先為科例以防請託。其所居亦無赫赫名，去後常見思。","sentenceOrder":39},
  {"id":"s_work_han_thu_99_40","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「獎，勸也，進而勸之。」","sentenceOrder":40},
  {"id":"s_work_han_thu_99_41","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「兩龔，龔勝、龔舍也。兩唐，唐林、唐尊也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_99_42","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「多，重也，重武進賢也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_99_43","chapterId":"ch_work_han_thu_99","textTraditional":"及為御史大夫司空，與丞相方進共奏言：「往者諸侯王斷獄治政，內史典獄事，相總綱紀輔王，中尉備盜賊。今王不斷獄與政，〔一〕中尉官罷，職并內史，郡國守相委任，所以壹統信，安百姓也〔二〕。今內史位卑而權重，威職相踰，不統尊者，難以為治。臣請相如太守，內史如都尉，以順尊卑之序，平輕重之權。」制曰：「可。」以內史為中尉。初武為九卿時，奏言宜置三公官，又與方進共奏罷刺史，更置州牧，後皆復復故，〔三〕語在朱博傳。唯內史事施行。","sentenceOrder":43},
  {"id":"s_work_han_thu_99_44","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「與讀曰豫。」","sentenceOrder":44},
  {"id":"s_work_han_thu_99_45","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「令百姓信之而安附也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_99_46","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「又依其舊也。下復音扶目反。」","sentenceOrder":46},
  {"id":"s_work_han_thu_99_47","chapterId":"ch_work_han_thu_99","textTraditional":"多所舉奏，號為煩碎，不稱賢公。功名略比薛宣，其材不及也，而經術正直過之。武後母在郡，遣吏歸迎。會成帝崩，吏恐道路有盜賊，後母留止，左右或譏武事親不篤。〔一〕哀帝亦欲改易大臣，遂策免武曰：「君舉錯煩苛，不合眾心，〔二〕孝聲不聞，惡名流行，無以率示四方。其上大司空印綬，罷歸就國。」後五歲，諫大夫鮑宣數稱冤之，天子感丞相王嘉之對，而高安侯董賢亦薦武，武由是復徵為御史大夫。月餘，徙為前將軍。","sentenceOrder":47},
  {"id":"s_work_han_thu_99_48","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「左右謂天子側近之臣。」","sentenceOrder":48},
  {"id":"s_work_han_thu_99_49","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「錯，置也，音千故反。」","sentenceOrder":49},
  {"id":"s_work_han_thu_99_50","chapterId":"ch_work_han_thu_99","textTraditional":"先是，新都侯王莽就國，數年，上以太皇太后故徵莽還京師。莽從弟成都侯王邑為侍中，矯稱太皇太后指白哀帝，為莽求特進給事中。哀帝復請之，事發覺。〔一〕太后為謝，上以太后故不忍誅之，左遷邑為西河屬國都尉，削千戶。後有詔舉大常，莽私從武求舉，武不敢舉。後數月，哀帝崩，太后即日引莽入，收大司馬董賢印綬，詔有司舉可大司馬者。莽故大司馬，辭位辟丁、傅，〔二〕眾庶稱以為賢，又太后近親，自大司徒孔光以下舉朝皆舉莽。武為前將軍，素與左將軍公孫祿相善，二人獨謀，以為往時孝惠、孝昭少主之世，外戚呂、霍、上官持權，幾危社稷，〔三〕今孝成、孝哀比世無嗣，〔四〕方當選立親近輔幼主，不宜令異姓大臣持權，〔五〕親疏相錯，為國計便。〔六〕於是武舉公孫祿可大司馬，而祿亦舉武。太后竟自用莽為大司馬。莽風有司劾奏武、公孫祿互相稱舉，〔七〕皆免。","sentenceOrder":50},
  {"id":"s_work_han_thu_99_51","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「哀帝反更以此事請於太后，太后本無此言，故矯事發覺也。復音扶目反。」","sentenceOrder":51},
  {"id":"s_work_han_thu_99_52","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「辟讀曰避。」","sentenceOrder":52},
  {"id":"s_work_han_thu_99_53","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「幾音鉅依反。」","sentenceOrder":53},
  {"id":"s_work_han_thu_99_54","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「比，頻也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_99_55","chapterId":"ch_work_han_thu_99","textTraditional":"〔五〕　師古曰：「異姓謂非宗室及外戚。」","sentenceOrder":55},
  {"id":"s_work_han_thu_99_56","chapterId":"ch_work_han_thu_99","textTraditional":"〔六〕　師古曰：「錯謂間雜也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_99_57","chapterId":"ch_work_han_thu_99","textTraditional":"〔七〕　師古曰：「風讀曰諷。」","sentenceOrder":57},
  {"id":"s_work_han_thu_99_58","chapterId":"ch_work_han_thu_99","textTraditional":"武就國後，莽寖盛，為宰衡，〔一〕陰誅不附己者。元始三年，呂寬等事起。時大司空甄豐承莽風指，〔二〕遣使者乘傳案治黨與，〔三〕連引諸所欲誅，上黨鮑宣，南陽彭偉、杜公子，〔四〕郡國豪桀坐死者數百人。武在見誣中，大理正檻車徵武，武自殺。眾人多冤武者，莽欲厭眾意，令武子況嗣為侯，〔五〕諡武曰剌侯。〔六〕莽篡位，免況為庶人。","sentenceOrder":58},
  {"id":"s_work_han_thu_99_59","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「寖，漸也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_99_60","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「風謂風采也。指，意也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_99_61","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「傳音張戀反。」","sentenceOrder":61},
  {"id":"s_work_han_thu_99_62","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「彭偉及杜公子二人皆南陽人。」","sentenceOrder":62},
  {"id":"s_work_han_thu_99_63","chapterId":"ch_work_han_thu_99","textTraditional":"〔五〕　師古曰：「厭，滿也，音一贍反。」","sentenceOrder":63},
  {"id":"s_work_han_thu_99_64","chapterId":"ch_work_han_thu_99","textTraditional":"〔六〕　師古曰：「剌音來曷反。」","sentenceOrder":64},
  {"id":"s_work_han_thu_99_65","chapterId":"ch_work_han_thu_99","textTraditional":"王嘉字公仲，平陵人也。以明經射策甲科為郎，坐戶殿門失闌免。〔一〕光祿勳于永除為掾，察廉為南陵丞，〔二〕復察廉為長陵尉。鴻嘉中，舉敦朴能直言，召見宣室，對政事得失，超遷太中大夫。出為九江、河南太守，治甚有聲。徵入為大鴻臚，徙京兆尹，遷御史大夫。建平三年代平當為丞相，封新甫侯，加食邑千一百戶。","sentenceOrder":65},
  {"id":"s_work_han_thu_99_66","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「戶，止也。嘉掌守殿門，止不當入者而失闌入之，故坐免也。春秋左氏傳曰『屈蕩戶之』。」","sentenceOrder":66},
  {"id":"s_work_han_thu_99_67","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「南陵，縣名，屬宣（州）〔城〕。」","sentenceOrder":67},
  {"id":"s_work_han_thu_99_68","chapterId":"ch_work_han_thu_99","textTraditional":"嘉為人剛直嚴毅有威重，上甚敬之。哀帝初立，欲匡成帝之政，多所變動，〔一〕嘉上疏曰：","sentenceOrder":68},
  {"id":"s_work_han_thu_99_69","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「匡，正也，正其乖失者。」","sentenceOrder":69},
  {"id":"s_work_han_thu_99_70","chapterId":"ch_work_han_thu_99","textTraditional":"臣聞聖王之功在於得人。孔子曰：「材難，不其然與！〔一〕」「故繼世立諸侯，象賢也。」〔二〕雖不能盡賢，天子為擇臣，立命卿以輔之。〔三〕居是國也，累世尊重，然後士民之眾附焉，是以教化行而治功立。今之郡守重於古諸侯，往者致選賢材，賢材難得，拔擢可用者，或起於囚徒。昔魏尚坐事繫，文帝感馮唐之言，遣使持節赦其罪，拜為雲中太守，匈奴忌之。武帝擢韓安國於徒中，拜為梁內史，骨肉以安。〔四〕張敞為京兆尹，有罪當免，黠吏知而犯敞，敞收殺之，其家自冤，使者覆獄，劾敞賊殺人，〔五〕上逮捕不下，〔六〕會免，亡命數十日，宣帝徵敞拜為冀州刺史，卒獲其用。前世非私此三人，貪其材器有益於公家也。","sentenceOrder":70},
  {"id":"s_work_han_thu_99_71","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「論語載孔子之言也。材難，謂有賢材者難得也。與讀曰歟。」","sentenceOrder":71},
  {"id":"s_work_han_thu_99_72","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「象其先父祖之賢耳，非必其人皆有德也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_99_73","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「命卿，命於天子者也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_99_74","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「言梁孝王得免罪也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_99_75","chapterId":"ch_work_han_thu_99","textTraditional":"〔五〕　師古曰：「覆音芳目反。」","sentenceOrder":75},
  {"id":"s_work_han_thu_99_76","chapterId":"ch_work_han_thu_99","textTraditional":"〔六〕　師古曰：「言使者上奏請逮捕敞，而天子不下其事也。下音胡稼反。」","sentenceOrder":76},
  {"id":"s_work_han_thu_99_77","chapterId":"ch_work_han_thu_99","textTraditional":"孝文時，吏居官者或長子孫，以官為氏，倉氏、庫氏則倉庫吏之後也。其二千石長吏亦安官樂職，然後上下相望，莫有苟且之意。其後稍稍變易，公卿以下傳相促急，又數改更政事，〔一〕司隸、部刺史察過悉劾，發揚陰私，〔二〕吏或居官數月而退，送故迎新，交錯道路。中材苟容求全，〔三〕下材懷危內顧，〔四〕壹切營私者多。二千石益輕賤，吏民慢易之。〔五〕或持其微過，增加成罪，言於刺史、司隸，或至上書章下；〔六〕眾庶知其易危，〔七〕小失意則有離畔之心。前山陽亡徒蘇令等從橫，〔八〕吏士臨難，莫肯伏節死義，以守相威權素奪也。〔九〕孝成皇帝悔之，下詔書，二千石不為縱，〔一０〕遣使者賜金，尉厚其意，誠以為國家有急，取辦於二千石，二千石尊重難危，乃能使下。","sentenceOrder":77},
  {"id":"s_work_han_thu_99_78","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「更亦變也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_99_79","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「悉，盡也。言事無大小盡皆舉劾，過於所察之條也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_99_80","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「不敢操持群下也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_99_81","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「常恐獲罪，每為私計也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_99_82","chapterId":"ch_work_han_thu_99","textTraditional":"〔五〕　師古曰：「易亦輕也，音弋豉反。」","sentenceOrder":82},
  {"id":"s_work_han_thu_99_83","chapterId":"ch_work_han_thu_99","textTraditional":"〔六〕　師古曰：「依其所上之章而下令治之。」","sentenceOrder":83},
  {"id":"s_work_han_thu_99_84","chapterId":"ch_work_han_thu_99","textTraditional":"〔七〕　師古曰：「言易可（輕）〔傾〕危也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_99_85","chapterId":"ch_work_han_thu_99","textTraditional":"〔八〕　師古曰：「從音子用反。橫音胡孟反。」","sentenceOrder":85},
  {"id":"s_work_han_thu_99_86","chapterId":"ch_work_han_thu_99","textTraditional":"〔九〕　師古曰：「守，郡守也。相，諸侯相也。素奪，謂先不假之威權也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_99_87","chapterId":"ch_work_han_thu_99","textTraditional":"〔一０〕孟康曰：「二千石不以故縱為罪，所以優也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_99_88","chapterId":"ch_work_han_thu_99","textTraditional":"孝宣皇帝愛其良民吏，〔一〕有章劾，事留中，會赦壹解。〔二〕故事，尚書希下章，為煩擾百姓，證驗繫治，或死獄中，章文必有「敢告之」字乃下。〔三〕唯陛下留神於擇賢，記善忘過，容忍臣子，勿責以備。〔四〕二千石、部刺史、三輔縣令有材任職者，人情不能不有過差，宜可闊略，〔五〕令盡力者有所勸。此方今急務，國家之利也。前蘇令發，〔六〕欲遣大夫使逐問狀，時見大夫無可使者，〔七〕召盩厔令尹逢拜為諫大夫遣之。（令）〔今〕諸大夫有材能者甚少，宜豫畜養可成就者，則士赴難不愛其死；臨事倉卒乃求，非所以明朝廷也。","sentenceOrder":88},
  {"id":"s_work_han_thu_99_89","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「良，善也。良人吏，善治百姓者。」","sentenceOrder":89},
  {"id":"s_work_han_thu_99_90","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「不即下治其事，恐為擾動，故每留中。或經赦令，一切皆解散也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_99_91","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「所以丁寧告者之辭，絕其相誣也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_99_92","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「不求備於一人也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_99_93","chapterId":"ch_work_han_thu_99","textTraditional":"〔五〕　師古曰：「當寬恕其小罪也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_99_94","chapterId":"ch_work_han_thu_99","textTraditional":"〔六〕　師古曰：「謂蘇令等初發起為盜賊也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_99_95","chapterId":"ch_work_han_thu_99","textTraditional":"〔七〕　師古曰：「謂見在大夫皆不堪為使也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_99_96","chapterId":"ch_work_han_thu_99","textTraditional":"嘉因薦儒者公孫光、滿昌及能吏蕭咸、薛修等，皆故二千石有名稱。天子納而用之。","sentenceOrder":96},
  {"id":"s_work_han_thu_99_97","chapterId":"ch_work_han_thu_99","textTraditional":"會息夫躬、孫寵等因中常侍宋弘上書告東平王雲祝詛，又與后舅伍宏謀弒上為逆，雲等伏誅，躬、寵擢為吏二千石。是時，侍中董賢愛幸於上，上欲侯之而未有所緣，傅嘉勸上因東平事以封賢。上於是定躬、寵告東平本章，〔一〕掇去宋弘，更言因董賢以聞，〔二〕欲以其功侯之，皆先賜爵關內侯。頃之，欲封賢等，上心憚嘉，乃先使皇后父孔鄉侯傅晏持詔書視丞相御史。〔三〕於是嘉與御史大夫賈延上封事言：「竊見董賢等三人始賜爵，眾庶匈匈，咸曰賢貴，其餘并蒙恩，〔四〕至今流言未解。陛下仁恩於賢等不已，宜暴賢等本奏語言，〔五〕延問公卿大夫博士議郎，考合古今，明正其義，然後乃加爵土；不然，恐大失眾心，海內引領而議。暴平其事，必有言當封者，在陛下所從；天下雖不說，咎有所分，〔六〕不獨在陛下。前定陵侯淳于長初封，其事亦議。大司農谷永以長當封，眾人歸咎於永，先帝不獨蒙其譏。〔七〕臣嘉、臣延材駑不稱，死有餘責。〔八〕知順指不迕，可得容身須臾，〔九〕所以不敢者，思報厚恩也。」上感其言，止，數月，遂下詔封賢等，因以切責公卿曰：「朕居位以來，寢疾未瘳，〔一０〕反逆之謀相連不絕，賊亂之臣近侍帷幄。前東平王雲與后謁祝詛朕，使侍醫伍宏等內侍案脈，〔一一〕幾危社稷，殆莫甚焉！〔一二〕昔楚有子玉得臣，晉文為之側席而坐；〔一三〕近事，汲黯折淮南之謀。今雲等至有圖弒天子逆亂之謀者，是公卿股肱莫能悉心務聰明以銷厭未萌之故。〔一四〕賴宗廟之靈，侍中駙馬都尉賢等發覺以聞，咸伏厥辜。書不云乎？『用德章厥善。』〔一五〕其封賢為高安侯、南陽太守寵為方陽侯、左曹光祿大夫躬為宜陵侯。」","sentenceOrder":97},
  {"id":"s_work_han_thu_99_98","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「定謂改治也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_99_99","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「掇讀曰剟。剟，削也，削去其名也。　音竹劣反。」","sentenceOrder":99},
  {"id":"s_work_han_thu_99_100","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「視讀曰示。」","sentenceOrder":100},
  {"id":"s_work_han_thu_99_101","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「言董賢以貴寵故妄得封，而躬、寵等遂蒙恩。」","sentenceOrder":101},
  {"id":"s_work_han_thu_99_102","chapterId":"ch_work_han_thu_99","textTraditional":"〔五〕　師古曰：「暴謂章露也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_99_103","chapterId":"ch_work_han_thu_99","textTraditional":"〔六〕　師古曰：「說讀曰悅。」","sentenceOrder":103},
  {"id":"s_work_han_thu_99_104","chapterId":"ch_work_han_thu_99","textTraditional":"〔七〕　師古曰：「蒙，被也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_99_105","chapterId":"ch_work_han_thu_99","textTraditional":"〔八〕　師古曰：「稱，副也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_99_106","chapterId":"ch_work_han_thu_99","textTraditional":"〔九〕　師古曰：「迕，逆也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_99_107","chapterId":"ch_work_han_thu_99","textTraditional":"〔一０〕師古曰：「瘳，差也，音丑留反。」","sentenceOrder":107},
  {"id":"s_work_han_thu_99_108","chapterId":"ch_work_han_thu_99","textTraditional":"〔一一〕師古曰：「案謂切診也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_99_109","chapterId":"ch_work_han_thu_99","textTraditional":"〔一二〕師古曰：「幾音鉅依反。殆亦危也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_99_110","chapterId":"ch_work_han_thu_99","textTraditional":"〔一三〕師古曰：「已解於上。」","sentenceOrder":110},
  {"id":"s_work_han_thu_99_111","chapterId":"ch_work_han_thu_99","textTraditional":"〔一四〕師古曰：「悉，盡也。務聰明者，廣視聽也。厭音一涉反。」","sentenceOrder":111},
  {"id":"s_work_han_thu_99_112","chapterId":"ch_work_han_thu_99","textTraditional":"〔一五〕師古曰：「商書盤庚之辭也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_99_113","chapterId":"ch_work_han_thu_99","textTraditional":"後數月，日食，舉直言，嘉復奏封事曰：","sentenceOrder":113},
  {"id":"s_work_han_thu_99_114","chapterId":"ch_work_han_thu_99","textTraditional":"臣聞咎繇戒帝舜曰：「亡敖佚欲有國，兢兢業業，一日二日萬機。」〔一〕箕子戒武王曰：「臣無有作威作福，亡有玉食；臣之有作威作福玉食，害于而家，凶于而國，人用側頗辟，民用僭慝。」〔二〕言如此則逆尊卑之序，亂陰陽之統，而害及王者，其國極危。國人傾仄不正，民用僭差不壹，此君不由法度，上下失序之敗也。武王躬履此道，隆至成康。〔三〕自是以後，縱心恣欲，法度陵遲〔四〕，至於臣弒君，子弒父。父子至親，失禮患生，何況異姓之臣？孔子曰：「道千乘之國，敬事而信，節用而愛人，使民以時。」〔五〕孝文皇帝備行此道，海內蒙恩，為漢太宗。孝宣皇帝賞罰信明，施與有節，記人之功，忽於小過，〔六〕以致治平。孝元皇帝奉承大業，溫恭少欲，都內錢四十萬萬，水衡錢二十五萬萬，少府錢十八萬萬。〔七〕嘗幸上林，後宮馮貴人從臨獸圈，猛獸驚出，貴人前當之，元帝嘉美其義，賜錢五萬。〔八〕掖庭見親，有加賞賜，屬其人勿眾謝。〔九〕示平惡偏，重失人心，賞賜節約。是時外戚貲千萬者少耳，故少府水衡見錢多也。〔一０〕雖遭初元、永光凶年飢饉，加有西羌之變，外奉師旅，內振貧民，終無傾危之憂，以府臧內充實也。孝成皇帝時，諫臣多言燕出之害，〔一一〕及女寵專愛，耽於酒色，損德傷年，其言甚切，然終不怨怒也。寵臣淳于長、張放、史育，育數貶退，家貲不滿千萬，放斥逐就國，長榜死於獄。〔一二〕不以私愛害公義，故雖多內譏，朝廷安平，〔一三〕傳業陛下。","sentenceOrder":114},
  {"id":"s_work_han_thu_99_115","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「虞書咎繇謨之辭也。言有國之人不可傲慢逸欲，但當戒慎危懼，以理萬事之機也。敖讀曰傲。」","sentenceOrder":115},
  {"id":"s_work_han_thu_99_116","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「周書洪範載箕子對武王之辭也。玉食，精好如玉也。而，汝也。頗，偏也。僭，不信也。慝，惡也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_99_117","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「言武王能履法度，故至成康之時，德化隆盛也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_99_118","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「陵遲即陵夷也，言漸頹替也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_99_119","chapterId":"ch_work_han_thu_99","textTraditional":"〔五〕　師古曰：「論語載孔子之言也。道，治也。千乘謂兵車千乘，說在刑法志。」","sentenceOrder":119},
  {"id":"s_work_han_thu_99_120","chapterId":"ch_work_han_thu_99","textTraditional":"〔六〕　師古曰：「忽，忘也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_99_121","chapterId":"ch_work_han_thu_99","textTraditional":"〔七〕　師古曰：「言不費用，故蓄積也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_99_122","chapterId":"ch_work_han_thu_99","textTraditional":"〔八〕　師古曰：「此言雖嘉其義而賞亦不多。」","sentenceOrder":122},
  {"id":"s_work_han_thu_99_123","chapterId":"ch_work_han_thu_99","textTraditional":"〔九〕　師古曰：「掖庭宮人，有親戚來見而帝賜之者，屬其家勿使於眾人中謝也。屬音之欲反。」","sentenceOrder":123},
  {"id":"s_work_han_thu_99_124","chapterId":"ch_work_han_thu_99","textTraditional":"〔一０〕師古曰：「見在之錢也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_99_125","chapterId":"ch_work_han_thu_99","textTraditional":"〔一一〕師古曰：「燕出謂微行也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_99_126","chapterId":"ch_work_han_thu_99","textTraditional":"〔一二〕師古曰：「榜，笞擊也，音彭。」","sentenceOrder":126},
  {"id":"s_work_han_thu_99_127","chapterId":"ch_work_han_thu_99","textTraditional":"〔一三〕師古曰：「雖有好內之譏，而不害政也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_99_128","chapterId":"ch_work_han_thu_99","textTraditional":"陛下在國之時，好詩書，上儉節，徵來所過道上稱誦德美，此天下所以回心也。〔一〕初即位，易帷帳，去錦繡，乘輿席緣綈繒而已。〔二〕共皇寢廟比比當作，〔三〕憂閔元元，惟用度不足〔四〕，以義割恩，輒且止息，今始作治。而駙馬都尉董賢亦起官寺上林中，又為賢治大第，開門鄉北闕，〔五〕引王渠灌園池，〔六〕使者護作，〔七〕賞賜吏卒，甚於治宗廟。賢母病，長安廚給祠具，〔八〕道中過者皆飲食。〔九〕為賢治器，器成，奏御乃行，或物好，特賜其工，自貢獻宗廟三宮，猶不至此。〔一０〕賢家有賓婚及見親，諸官並共，〔一一〕賜及倉頭奴婢，人十萬錢。使者護視，發取市物，百賈震動，〔一二〕道路讙譁，群臣惶惑。詔書罷菀，而以賜賢二千餘頃，均田之制從此墮壞。〔一三〕奢僭放縱，變亂陰陽，災異眾多，百姓訛言，持籌相驚，〔一四〕被髮徒跣而走，乘馬者馳，天惑其意，不能自止。或以為籌者策失之戒也。陛下素仁智慎事，今而有此大譏。","sentenceOrder":128},
  {"id":"s_work_han_thu_99_129","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「望為治也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_99_130","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「綈，厚繒也，音徒奚反。」","sentenceOrder":130},
  {"id":"s_work_han_thu_99_131","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「共皇，哀帝之父，即定陶恭王也。比比猶頻頻也。共讀曰恭。」","sentenceOrder":131},
  {"id":"s_work_han_thu_99_132","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「惟，思也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_99_133","chapterId":"ch_work_han_thu_99","textTraditional":"〔五〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":133},
  {"id":"s_work_han_thu_99_134","chapterId":"ch_work_han_thu_99","textTraditional":"〔六〕　蘇林曰：「王渠，官渠也，猶今御溝也。」晉灼曰：「渠名也，在城東覆盎門外。」師古曰：「晉說是。」","sentenceOrder":134},
  {"id":"s_work_han_thu_99_135","chapterId":"ch_work_han_thu_99","textTraditional":"〔七〕　師古曰：「護，監視也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_99_136","chapterId":"ch_work_han_thu_99","textTraditional":"〔八〕　師古曰：「長安有廚官，主為官食。」","sentenceOrder":136},
  {"id":"s_work_han_thu_99_137","chapterId":"ch_work_han_thu_99","textTraditional":"〔九〕　如淳曰：「禱於道中，故行人皆得飲食。」","sentenceOrder":137},
  {"id":"s_work_han_thu_99_138","chapterId":"ch_work_han_thu_99","textTraditional":"〔一０〕師古曰：「三宮，天子、太后、皇后也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_99_139","chapterId":"ch_work_han_thu_99","textTraditional":"〔一一〕師古曰：「見親，親戚相見也。並供，言百官各以所掌事及財物就供之。共讀曰供。」","sentenceOrder":139},
  {"id":"s_work_han_thu_99_140","chapterId":"ch_work_han_thu_99","textTraditional":"〔一二〕師古曰：「賈謂販賣之人也。言百賈者，非一之稱也。賈音古。」","sentenceOrder":140},
  {"id":"s_work_han_thu_99_141","chapterId":"ch_work_han_thu_99","textTraditional":"〔一三〕孟康曰：「自公卿以下至於吏民名曰均田，皆有頃數，於品制中令均等。今賜賢二千餘頃，則壞其等制也。」師古曰：「菀，古苑字。墮音火規反。」","sentenceOrder":141},
  {"id":"s_work_han_thu_99_142","chapterId":"ch_work_han_thu_99","textTraditional":"〔一四〕師古曰：「言行西王母籌也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_99_143","chapterId":"ch_work_han_thu_99","textTraditional":"孔子曰：「危而不持，顛而不扶，則將安用彼相矣！」〔一〕臣嘉幸得備位，竊內悲傷不能通愚忠之信；身死有益於國，不敢自惜。唯陛下慎己之所獨鄉，察眾人之所共疑。〔二〕往者寵臣鄧通、韓嫣〔三〕驕貴失度，逸豫無厭，小人不勝情Q欲Y，卒陷罪辜。〔四〕亂國亡驅，不終其祿，所謂愛之適足以害之者也。宜深覽前世，以節賢寵，全安其命。","sentenceOrder":143},
  {"id":"s_work_han_thu_99_144","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「論語稱季氏將伐顓臾，冉有、季路見於孔子，孔子以此言責之，以其不匡諫也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_99_145","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":145},
  {"id":"s_work_han_thu_99_146","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「嫣音偃。」","sentenceOrder":146},
  {"id":"s_work_han_thu_99_147","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「卒，終也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_99_148","chapterId":"ch_work_han_thu_99","textTraditional":"於是上寖不說，〔一〕而愈愛賢，不能自勝。","sentenceOrder":148},
  {"id":"s_work_han_thu_99_149","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「〈寖，中“彐改帚”〉，漸也。說讀曰悅。」","sentenceOrder":149},
  {"id":"s_work_han_thu_99_150","chapterId":"ch_work_han_thu_99","textTraditional":"會祖母傅太后薨，上因託傅太后遺詔，令成帝母王太后下丞相御史，益封賢二千戶，及賜孔鄉侯、汝昌侯、陽新侯國。〔一〕嘉封還詔書，〔二〕因奏封事諫上及太后曰：「臣聞爵祿土地，天之有也。書云：『天命有德，五服五章哉！』〔三〕王者代天爵人，尤宜慎之。裂地而封，不得其宜，則眾庶不服，感動陰陽，其害疾自深。〔四〕今聖體久不平，此臣嘉所內懼也。高安侯賢，佞幸之臣，陛下傾爵位以貴之，單貨財以富之，〔五〕損至尊以寵之，〔六〕主威已黜，府藏已竭，唯恐不足。財皆民力所為，孝文皇帝欲起露臺，重百金之費，克己不作。今賢散公賦以施私惠，一家至受千金，往古以來貴臣未嘗有此，流聞四方，皆同怨之。里諺曰：『千人所指，無病而死。』臣常為之寒心。今太皇太后以永信太后遺詔，詔丞相御史益賢戶，賜三侯國，臣嘉竊惑。山崩地動，日食於三朝，〔七〕皆陰侵陽之戒也。前賢已再封，晏、商再易邑，業緣私橫求，恩已過厚，〔八〕求索自恣，不知厭足，甚傷尊（卑）〔尊〕之義，不可以示天下，為害痛矣！臣驕侵罔，陰陽失節，〔九〕氣感相動，害及身體。陛下寢疾久不平，繼嗣未立，宜思正萬事，順天人之心，以求福祐，柰何輕身肆意，〔一０〕不念高祖之勤苦垂立制度欲傳之於無窮哉！孝經曰：『天子有爭臣七人，雖無道，不失其天下。』〔一一〕臣謹封上詔書，不敢露見，非愛死而不自法，恐天下聞之，故不敢自劾。愚（贛）〔戇〕數犯忌諱，唯陛下省察。」","sentenceOrder":150},
  {"id":"s_work_han_thu_99_151","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「傅晏、傅商、鄭業也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_99_152","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「還謂卻上之於天子也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_99_153","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「虞書咎繇謨之辭也。言皇天命於有德者以居列位，天子諸侯卿大夫士尊卑之服采章各異也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_99_154","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「言此氣損害，故令天子身自有疾也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_99_155","chapterId":"ch_work_han_thu_99","textTraditional":"〔五〕　師古曰：「單，盡也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_99_156","chapterId":"ch_work_han_thu_99","textTraditional":"〔六〕　師古曰：「言上意傾惑，為下所窺也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_99_157","chapterId":"ch_work_han_thu_99","textTraditional":"〔七〕　師古曰：「歲月日之朝也。已解於上。」","sentenceOrder":157},
  {"id":"s_work_han_thu_99_158","chapterId":"ch_work_han_thu_99","textTraditional":"〔八〕　師古曰：「橫音胡孟反。」","sentenceOrder":158},
  {"id":"s_work_han_thu_99_159","chapterId":"ch_work_han_thu_99","textTraditional":"〔九〕　師古曰：「罔謂誣蔽也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_99_160","chapterId":"ch_work_han_thu_99","textTraditional":"〔一０〕師古曰：「肆，放也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_99_161","chapterId":"ch_work_han_thu_99","textTraditional":"〔一一〕師古曰：「言上能納諫，則免於過惡也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_99_162","chapterId":"ch_work_han_thu_99","textTraditional":"初，廷尉梁相與丞相長史、御史中丞及五二千石雜治東平王雲獄，時冬月未盡二旬，而相心疑雲冤，獄有飾辭，〔一〕奏欲傳之長安，〔二〕更下公卿覆治。尚書令鞫譚、僕射宗伯鳳以為可許。〔三〕天子以相等皆見上體不平，外內顧望，操持兩心，〔四〕幸雲踰冬，無討賊疾惡主讎之意，制詔免相等皆為庶人。後數月大赦，嘉奏封事薦相等明習治獄，「相計謀深沈，譚頗知雅文，鳳經明行修，聖王有計功除過，〔五〕臣竊為朝廷惜此三人。」書奏，上不能平。〔六〕後二十餘日，嘉封還益董賢戶事，上乃發怒，召嘉詣尚書，責問以「相等前坐在位不盡忠誠，外附諸侯，操持兩心，背人臣之義，今所稱相等材美，足以相計除罪。君以道德，位在三公，以總方略一統萬類分明善惡為職，知相等罪惡陳列，著聞天下，時輒以自劾，今又稱譽相等，云為朝廷惜之。大臣舉錯，恣心自在，〔七〕迷國罔上，近由君始，將謂遠者何！〔八〕對狀。」〔九〕嘉免冠謝罪。","sentenceOrder":162},
  {"id":"s_work_han_thu_99_163","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「假飾之辭，非其實也。」","sentenceOrder":163},
  {"id":"s_work_han_thu_99_164","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「傳謂移其獄事也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_99_165","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「鞫及宗伯皆姓也。鞫音居六反。」","sentenceOrder":165},
  {"id":"s_work_han_thu_99_166","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「操音千高反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_99_167","chapterId":"ch_work_han_thu_99","textTraditional":"〔五〕　師古曰：「收采其功，以（明）〔免〕罪過也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_99_168","chapterId":"ch_work_han_thu_99","textTraditional":"〔六〕　師古曰：「心怒也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_99_169","chapterId":"ch_work_han_thu_99","textTraditional":"〔七〕　師古曰：「錯，置也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_99_170","chapterId":"ch_work_han_thu_99","textTraditional":"〔八〕　師古曰：「近臣尚然，則遠者固宜爾也。」","sentenceOrder":170},
  {"id":"s_work_han_thu_99_171","chapterId":"ch_work_han_thu_99","textTraditional":"〔九〕　師古曰：「敕令具對也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_99_172","chapterId":"ch_work_han_thu_99","textTraditional":"事下將軍中朝者。光祿大夫孔光、左將軍公孫祿、右將軍王安、光祿勳馬宮、光祿大夫龔勝劾嘉迷國罔上不道，請與廷尉雜治。勝獨以為嘉備宰相，諸事並廢，咎由嘉生；〔一〕嘉坐薦相等，微薄，以應迷國罔上不道，恐不可以示天下。遂可光等奏。","sentenceOrder":172},
  {"id":"s_work_han_thu_99_173","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「孔光以下眾共劾嘉，而勝獨為異議也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_99_174","chapterId":"ch_work_han_thu_99","textTraditional":"光等請謁者召嘉詣廷尉詔獄，制曰：「票騎將軍、御史大夫、中二千石、二千石、諸大夫、博士、議郎議。」衛尉雲等五十人以為「如光等言可許」。議郎龔等以為「嘉言事前後相違，無所執守，不任宰相之職，宜奪爵土，免為庶人。」永信少府猛等十人以為「聖王斷獄，必先原心定罪，探意立情，故死者不抱恨而入地，生者不銜怨而受罪。明主躬聖德，重大臣刑辟，廣延有司議，欲使海內咸服。嘉罪名雖應法，聖王之於大臣，在輿為下，御坐則起，〔一〕疾病視之無數，死則臨弔之，廢宗廟之祭，進之以禮，退之以義，誄之以行〔二〕。案嘉本以相等為罪，罪惡雖著，大臣括髮關械、裸躬就笞，〔三〕非所以重國褒宗廟也。今春月寒氣錯繆，霜露數降，宜示天下以寬和。臣等不知大義，唯陛下察焉。」有詔假謁者節，召丞相詣廷尉詔獄。","sentenceOrder":174},
  {"id":"s_work_han_thu_99_175","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「解在翟方進傳。」","sentenceOrder":175},
  {"id":"s_work_han_thu_99_176","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「言大臣之死，積累其行而為誄也。誄者，累德行之文。」","sentenceOrder":176},
  {"id":"s_work_han_thu_99_177","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「括，結也。關，貫也。祼，露也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_99_178","chapterId":"ch_work_han_thu_99","textTraditional":"使者既到府，掾史涕泣，共和藥進嘉，嘉不肯服。主簿曰：「將相不對理陳冤，相踵以為故事，〔一〕君侯宜引決。」〔二〕使者危坐府門上。〔三〕主簿復前進藥，嘉引藥杯以擊地，謂官屬曰：「丞相幸得備位三公，奉職負國，當伏刑都市以示萬眾。丞相豈兒女子邪，何謂咀藥而死！」〔四〕嘉遂裝出，見使者再拜受詔，乘吏小車，去蓋不冠，隨使者詣廷尉。廷尉收嘉丞相新甫侯印綬，縛嘉載致都船詔獄。","sentenceOrder":178},
  {"id":"s_work_han_thu_99_179","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「踵由躡也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_99_180","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「令自殺也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_99_181","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「以逼促嘉也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_99_182","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「咀，嚼也，音才汝反。」","sentenceOrder":182},
  {"id":"s_work_han_thu_99_183","chapterId":"ch_work_han_thu_99","textTraditional":"上聞嘉生自詣吏，大怒，使將軍以下與五二千石雜治。吏詰問嘉，嘉對曰：「案事者思得實。竊見相等前治東平王獄，不以雲為不當死，欲關公卿示重慎；置驛馬傳囚，勢不得踰冬月，誠不見其外內顧望阿附為雲驗。復幸得蒙大赦，相等皆良善吏，臣竊為國惜賢，不私此三人。」獄吏曰：「苟如此，則君何以為罪猶當？有以負國，不空入獄矣。」吏稍侵辱嘉，嘉喟然卬天嘆曰：〔一〕「幸得充備宰相，不能進賢退不肖，以是負國，死有餘責。」吏問賢不肖主名，嘉曰：「賢，故丞相孔光、故大司空何武，不能進；惡，高安侯董賢父子，佞邪亂朝，而不能退。罪當死，死無所恨。」嘉繫獄二十餘日，不食歐血而死。帝舅大司馬票騎將軍丁明素重嘉而憐之，上遂免明，以董賢代之，語在賢傳。","sentenceOrder":183},
  {"id":"s_work_han_thu_99_184","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「卬讀曰仰。」","sentenceOrder":184},
  {"id":"s_work_han_thu_99_185","chapterId":"ch_work_han_thu_99","textTraditional":"嘉為相三年誅，國除。死後上覽其對而思嘉言，復以孔光代嘉為丞相，徵用何武為御史大夫。元始四年，詔書追錄忠臣，封嘉子崇為新甫侯，追諡嘉為忠侯。，","sentenceOrder":185},
  {"id":"s_work_han_thu_99_186","chapterId":"ch_work_han_thu_99","textTraditional":"師丹字仲公，琅邪東武人也。治詩，事匡衡。舉孝廉為郎。元帝末，為博士，免。建始中，州舉茂材，復補博士，出為東平王太傅。丞相方進、御史大夫孔光舉丹論議深博，廉正守道，徵入為光祿大夫、丞相司直。數月，復以光祿大夫給事中，由是為少府、光祿勳、侍中，甚見尊重。成帝末年，立定陶王為皇太子，以丹為太子太傅。哀帝即位，為左將軍，賜爵關內侯，食邑，領尚書事，遂代王莽為大司馬，封高樂侯。月餘，徙為大司空。","sentenceOrder":186},
  {"id":"s_work_han_thu_99_187","chapterId":"ch_work_han_thu_99","textTraditional":"上少在國，見成帝委政外家，王氏僭盛，常內邑邑。即位，多欲有所匡正。封拜丁、傅，奪王氏權。丹自以師傅居三公位，得信於上，上書言：「古者諒闇不言，聽於冢宰，〔一〕三年無改於父之道。〔二〕前大行尸柩在堂，而官爵臣等以及親屬，赫然皆貴寵。封舅為陽安侯，皇后尊號未定，豫封父為孔鄉侯。出侍中王邑、射聲校尉王邯等。詔書比下，變動政事，〔三〕卒暴無漸。〔四〕臣縱不能明陳大義，復曾不能牢讓爵位，〔五〕相隨空受封侯，增益陛下之過。問者郡國多地動，水出流殺人民，日月不明，五星失行，此皆舉錯失中，號令不定，法度失理，陰陽溷濁之（患）〔應〕也。〔六〕臣伏惟人情無子，年雖六七十，猶博取而廣求。〔七〕孝成皇帝深見天命，燭知至德，〔八〕以壯年克己，立陛下為嗣。先帝暴棄天下而陛下繼體，四海安寧，百姓不懼，此先帝聖德當合天人之功也。臣聞天威不違顏咫尺，〔九〕願陛下深思先帝所以建立陛下之意，且克己躬行以觀群下之從化。天下者，陛下之家也，胏附何患不富貴，不宜倉卒。先帝不量臣愚，以為太傅，陛下以臣託師傅，故亡功德而備鼎足，封大國，加賜黃金，位為三公，職在左右，〔一０〕不能盡忠補過，而令庶人竊議，災異數見，此臣之大罪也。臣不敢言乞骸骨歸於海濱，恐嫌於偽。誠慚負重責，義不得不盡死。」書數十上，多切直之言。","sentenceOrder":187},
  {"id":"s_work_han_thu_99_188","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「論語云子張曰：『書云高宗諒闇，三年不言。』孔子曰：『何必高宗，古之人皆然。君薨，百官總己以聽於冢宰三年。』諒，信也。闇，默然也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_99_189","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「論語稱孔子曰：『父在觀其志，父沒觀其行；三年無改於父之道，可謂孝矣。』」","sentenceOrder":189},
  {"id":"s_work_han_thu_99_190","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「比，頻也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_99_191","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「卒讀曰猝。」","sentenceOrder":191},
  {"id":"s_work_han_thu_99_192","chapterId":"ch_work_han_thu_99","textTraditional":"〔五〕　師古曰：「牢，堅也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_99_193","chapterId":"ch_work_han_thu_99","textTraditional":"〔六〕　師古曰：「溷音胡頓反。」","sentenceOrder":193},
  {"id":"s_work_han_thu_99_194","chapterId":"ch_work_han_thu_99","textTraditional":"〔七〕　師古曰：「取讀曰娶。」","sentenceOrder":194},
  {"id":"s_work_han_thu_99_195","chapterId":"ch_work_han_thu_99","textTraditional":"〔八〕　師古曰：「燭，照也。至德，指謂哀帝。」","sentenceOrder":195},
  {"id":"s_work_han_thu_99_196","chapterId":"ch_work_han_thu_99","textTraditional":"〔九〕　師古曰：「言常若在前，宜自肅懼也。」","sentenceOrder":196},
  {"id":"s_work_han_thu_99_197","chapterId":"ch_work_han_thu_99","textTraditional":"〔一０〕師古曰：「左右，助也。左讀曰佐。右讀曰佑。」","sentenceOrder":197},
  {"id":"s_work_han_thu_99_198","chapterId":"ch_work_han_thu_99","textTraditional":"初，哀帝即位，成帝母稱太皇太后，成帝趙皇后稱皇太后，而上祖母傅太后與母丁后皆在國邸，自以定陶共王為稱。高昌侯董宏上書言：「秦莊襄王母本夏氏，而為華陽夫人所子，〔一〕及即位後，俱稱太后。宜立定陶共王后為皇太后。」事下有司，時丹以左將軍與大司馬王莽共劾奏宏「知皇太后至尊之號，天下一統，而稱引亡秦以為比喻，詿誤聖朝，非所宜言，大不道。」上新立，謙讓，納用莽、丹言，免宏為庶人。傅太后大怒。要上欲必稱尊號，上於是追尊定陶共王為共皇，尊傅太后為共皇太后，丁后為共皇后。郎中令泠褒、黃門郎段猶等復奏言：〔二〕「定陶共皇太后、共皇后皆不宜復引定陶蕃國之名以冠大號，車馬衣服宜皆稱皇之意，〔三〕置吏二千石以下各供厥職，〔四〕又宜為共皇立廟京師。」上復下其議，有司皆以為宜如褒、猶言。丹議獨曰：「聖王制禮取法於天地，故尊卑之禮明則人倫之序正，人倫之序正則乾坤得其位而陰陽順其節，人主與萬民俱蒙祐福，尊卑者，所以正天地之位，不可亂也。今定陶共皇太后、共皇后以定陶共為號者，母從子妻從夫之義也。欲立官置吏，車服與太皇太后並，非所以明尊卑亡二上之義也。定陶共皇號諡已前定，義不得復改。禮：『父為士，子為天子，祭以天子，其尸服以士服。』子亡爵父之義，尊父母也。為人後者為之子，故為所後服斬衰三年，而降其父母期，明尊本祖而重正統也。孝成皇帝聖恩深遠，故為共王立後，奉承祭祀，今共皇長為一國太祖，萬世不毀，恩義已備。陛下既繼體先帝，持重大宗，承宗廟天地社稷之祀，義不得復奉定陶共皇祭入其廟。今欲立廟於京師，而使臣下祭之，是無主也。又親盡當毀，空去一國太祖不墮之祀，〔五〕而就無主當毀不正之禮，非所以尊厚共皇也。」丹由是浸不合上意。〔六〕","sentenceOrder":198},
  {"id":"s_work_han_thu_99_199","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「莊襄王，始皇之父也。華陽夫人，孝文王之夫人也。子謂養以為子也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_99_200","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「泠音零。」","sentenceOrder":200},
  {"id":"s_work_han_thu_99_201","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「皇者，至尊之號，其服御宜皆副稱之也。稱音尺孕反。」","sentenceOrder":201},
  {"id":"s_work_han_thu_99_202","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「謂詹事、太僕、少府等眾官也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_99_203","chapterId":"ch_work_han_thu_99","textTraditional":"〔五〕　師古曰：「墮亦毀也，音火規反。」","sentenceOrder":203},
  {"id":"s_work_han_thu_99_204","chapterId":"ch_work_han_thu_99","textTraditional":"〔六〕　師古曰：「浸，漸也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_99_205","chapterId":"ch_work_han_thu_99","textTraditional":"會有上書言古者以龜貝為貨，今以錢易之，民以故貧，宜可改幣。上以問丹，丹對言可改。章下有司議，皆以為行錢以來久，難卒變易。〔一〕丹老人，忘其前語，後從公卿議。又丹使吏書奏，吏私寫其草，丁、傅子弟聞之，使人上書告丹上封事行道人遍持其書。上以問將軍中朝臣，皆對曰：「忠臣不顯諫，大臣奏事不宜漏泄，令吏民傳寫流聞四方。『臣不密則失身』，〔二〕宜下廷尉治。」事下廷尉，廷尉劾丹大不敬。事未決，給事中博士申咸、炔欽上書，〔三〕言「丹經行無比，〔四〕自近世大臣能若丹者少。發憤懣，奏封事，不及深思遠慮，使主簿書，漏泄之過不在丹。以此貶黜，恐不厭眾心。」〔五〕尚書劾咸、欽：「幸得以儒官選擢備腹心，上所折中定疑，〔六〕知丹社稷重臣，議罪處罰，國之所慎，咸、欽初傅經義以為當治，〔七〕事以暴列，乃復上書妄稱譽丹，前後相違，不敬。」上貶咸、欽秩各二等，遂策免丹曰：「夫三公者，朕之腹心也，輔善相過，匡率百僚，和合天下者也。朕既不明，委政於公，間者陰陽不調，寒暑失常，變異婁臻，〔八〕山崩地震，河決泉涌，流殺人民，百姓流連，無所歸心，司空之職尤廢焉。君在位出入三年，未聞忠言嘉謀，而反有朋黨相進不公之名。乃者以挺力田議改幣章示君，〔九〕君內為朕建可改不疑；〔一０〕以君之言博考朝臣，君乃希眾雷同，外以為不便，令觀聽者歸非於朕。朕隱忍不宣，為君受愆。朕疾夫比周之徒〔一一〕虛偽壞化，寖以成俗，故屢以書飭君，〔一二〕幾君省過求己，〔一三〕而反不受，退有後言。及君奏封事，傳於道路，布聞朝市，言事者以為大臣不忠，辜陷重辟，獲虛采名，謗譏匈匈，流於四方。腹心如此，謂疏者何？殆謬於二人同心之利焉，〔一四〕將何以率示群下，附親遠方？朕惟君位尊任重，慮不周密，懷諼迷國，〔一五〕進退違命，反覆異言，甚為君恥之，非所以共承天地，永保國家之意。〔一六〕以君嘗託傅位，未忍考於理，已詔有司赦君勿治。其上大司空高樂侯印綬，罷歸。」","sentenceOrder":205},
  {"id":"s_work_han_thu_99_206","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「卒讀曰猝。」","sentenceOrder":206},
  {"id":"s_work_han_thu_99_207","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「易上繫之辭。」","sentenceOrder":207},
  {"id":"s_work_han_thu_99_208","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　蘇林曰：「炔音桂。」","sentenceOrder":208},
  {"id":"s_work_han_thu_99_209","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「比音必寐反。」","sentenceOrder":209},
  {"id":"s_work_han_thu_99_210","chapterId":"ch_work_han_thu_99","textTraditional":"〔五〕　師古曰：「厭音一贍反。」","sentenceOrder":210},
  {"id":"s_work_han_thu_99_211","chapterId":"ch_work_han_thu_99","textTraditional":"〔六〕　師古曰：「折，斷也。取其言以斷事之中而定所疑。」","sentenceOrder":211},
  {"id":"s_work_han_thu_99_212","chapterId":"ch_work_han_thu_99","textTraditional":"〔七〕　師古曰：「傅讀曰附。」","sentenceOrder":212},
  {"id":"s_work_han_thu_99_213","chapterId":"ch_work_han_thu_99","textTraditional":"〔八〕　師古曰：「婁，古屢字。」","sentenceOrder":213},
  {"id":"s_work_han_thu_99_214","chapterId":"ch_work_han_thu_99","textTraditional":"〔九〕　師古曰：「挺，引拔也，謂特拔異力田之人優寵之也。挺音徒鼎反。而說者以挺為縣名，失之遠矣。」","sentenceOrder":214},
  {"id":"s_work_han_thu_99_215","chapterId":"ch_work_han_thu_99","textTraditional":"〔一０〕師古曰：「共立此議也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_99_216","chapterId":"ch_work_han_thu_99","textTraditional":"〔一一〕師古曰：「比音頻寐反。」","sentenceOrder":216},
  {"id":"s_work_han_thu_99_217","chapterId":"ch_work_han_thu_99","textTraditional":"〔一二〕師古曰：「飭與敕同。」","sentenceOrder":217},
  {"id":"s_work_han_thu_99_218","chapterId":"ch_work_han_thu_99","textTraditional":"〔一三〕師古曰：「省，視也。自求諸己，不尤人也。幾音冀。」","sentenceOrder":218},
  {"id":"s_work_han_thu_99_219","chapterId":"ch_work_han_thu_99","textTraditional":"〔一四〕師古曰：「易上繫辭曰『二人同心，其利斷金』，故詔書引之。」","sentenceOrder":219},
  {"id":"s_work_han_thu_99_220","chapterId":"ch_work_han_thu_99","textTraditional":"〔一五〕師古曰：「諼，詐也，音虛袁反。」","sentenceOrder":220},
  {"id":"s_work_han_thu_99_221","chapterId":"ch_work_han_thu_99","textTraditional":"〔一六〕師古曰：「共讀曰恭。」","sentenceOrder":221},
  {"id":"s_work_han_thu_99_222","chapterId":"ch_work_han_thu_99","textTraditional":"尚書令唐林上疏曰：「竊見免大司空丹策書，泰深痛切，君子作文，為賢者諱。丹經為世儒宗，德為國黃耇，〔一〕親傅聖躬，位在三公，所坐者微，海內未見其大過，事既已往，免爵大重，京師識者咸以為宜復丹邑爵，使奉朝請，〔二〕四方所瞻卬也。〔三〕惟陛下財覽眾心，有以尉復師傅之臣。」〔四〕上從林言，下詔賜丹爵關內侯，食邑三百戶。","sentenceOrder":222},
  {"id":"s_work_han_thu_99_223","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「黃耇，老人之稱也。黃謂白髮落更生黃者也。耇，老人面色不淨如垢也。」","sentenceOrder":223},
  {"id":"s_work_han_thu_99_224","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「識者，謂有識之人也。請音材性反。」","sentenceOrder":224},
  {"id":"s_work_han_thu_99_225","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「卬讀曰仰。」","sentenceOrder":225},
  {"id":"s_work_han_thu_99_226","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「財與裁同。復，報也，音扶目反。」","sentenceOrder":226},
  {"id":"s_work_han_thu_99_227","chapterId":"ch_work_han_thu_99","textTraditional":"丹既免數月，上用朱博議，尊傅太后為皇太太后，丁后為帝太后，與太皇太后及皇太后同尊，又為共皇立廟京師，儀如孝元皇帝。博遷為丞相，復與御史大夫趙玄奏言：「前高昌侯宏首建尊號之議，而為丹所劾奏，免為庶人。時天下衰麤，委政於丹。〔一〕丹不深惟褒廣尊親之義而妄稱說，抑貶尊號，虧損孝道，不忠莫大焉。陛下聖仁，昭然定尊號，宏以忠孝復封高昌侯。丹惡逆暴著，雖蒙赦令，不宜有爵邑，請免為庶人。」奏可。丹於是廢歸鄉里者數年。","sentenceOrder":227},
  {"id":"s_work_han_thu_99_228","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「言新有成帝之喪，斬衰麤服，故天子不親政事也。」","sentenceOrder":228},
  {"id":"s_work_han_thu_99_229","chapterId":"ch_work_han_thu_99","textTraditional":"平帝即位，新都侯王莽白太皇太后發掘傅太后、丁太后冢，奪其璽綬，更以民葬之，定陶隳廢共皇廟。〔一〕諸造議泠褒、段猶等皆徙合浦，復免高昌侯宏為庶人。徵丹詣公車，賜爵關內侯，食故邑。數月，太皇太后詔大司徒、大司空曰：「夫褒有德，賞元功，先聖之制，百王不易之道也。故定陶太后造稱僭號，甚悖義理。〔二〕關內侯師丹端誠於國，不顧患難，執忠節，據聖法，分明尊卑之制，確然有柱石之固，臨大節而不可奪，可謂社稷之臣矣。有司條奏邪臣建定稱號者已放退，而丹功賞未加，殆繆乎先賞後罰之義，非所以章有德報厥功也。其以厚丘之中鄉戶二千一百封丹為義陽侯。」月餘薨，諡曰節侯。子業嗣，王莽敗乃絕。","sentenceOrder":229},
  {"id":"s_work_han_thu_99_230","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「隳音火規反。」","sentenceOrder":230},
  {"id":"s_work_han_thu_99_231","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「悖，乖也，音布內反。」","sentenceOrder":231},
  {"id":"s_work_han_thu_99_232","chapterId":"ch_work_han_thu_99","textTraditional":"贊曰：何武之舉，王嘉之爭，師丹之議，〔一〕考其禍福，乃效於後。〔二〕當王莽之作，外內咸服，董賢之愛，疑於親戚，〔三〕武、嘉區區，以一蕢障江河，用沒其身。〔四〕丹與董宏更受賞罰，〔五〕哀哉！故曰「依世則廢道，違俗則（免）〔危〕殆」，〔六〕此古人所以難受爵位者也。","sentenceOrder":232},
  {"id":"s_work_han_thu_99_233","chapterId":"ch_work_han_thu_99","textTraditional":"〔一〕　師古曰：「何武舉公孫祿為大司馬，王嘉爭益董賢封邑，師丹議丁、傅不宜稱尊號。」","sentenceOrder":233},
  {"id":"s_work_han_thu_99_234","chapterId":"ch_work_han_thu_99","textTraditional":"〔二〕　師古曰：「終以王莽篡位，董賢遇禍，丁、傅喪敗。」","sentenceOrder":234},
  {"id":"s_work_han_thu_99_235","chapterId":"ch_work_han_thu_99","textTraditional":"〔三〕　師古曰：「疑讀曰擬。擬，比也。」","sentenceOrder":235},
  {"id":"s_work_han_thu_99_236","chapterId":"ch_work_han_thu_99","textTraditional":"〔四〕　師古曰：「蕢，織草為器，所以盛土也。一蕢之土，固不能障塞江河，是以其身沉沒也。蕢音匱。」","sentenceOrder":236},
  {"id":"s_work_han_thu_99_237","chapterId":"ch_work_han_thu_99","textTraditional":"〔五〕　師古曰：「更，互也。宏初建議尊號，為丹所劾而免爵土。及丹廢黜，宏復獲封。至王莽執政，宏為庶人，丹受國邑。故云互受賞罰也。更音工衡反。」","sentenceOrder":237},
  {"id":"s_work_han_thu_99_238","chapterId":"ch_work_han_thu_99","textTraditional":"〔六〕　師古曰：「言隨時曲直則廢於正道，違忤流俗則其身不安也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_99_239","chapterId":"ch_work_han_thu_99","textTraditional":"校勘記","sentenceOrder":239},
  {"id":"s_work_han_thu_99_240","chapterId":"ch_work_han_thu_99","textTraditional":"三四八二頁一一行　減（係）〔除〕其狀，直令免去也。　景祐、殿本都作「除」。王先謙說作「除」是。","sentenceOrder":240},
  {"id":"s_work_han_thu_99_241","chapterId":"ch_work_han_thu_99","textTraditional":"三四八四頁一三行　綏和（三）〔元〕年，　景祐、殿本都作「元」。朱一新說作「三」誤。","sentenceOrder":241},
  {"id":"s_work_han_thu_99_242","chapterId":"ch_work_han_thu_99","textTraditional":"三四八八頁一四行　屬宣（州）〔城〕。　景祐、殿本都作「宣城」。","sentenceOrder":242},
  {"id":"s_work_han_thu_99_243","chapterId":"ch_work_han_thu_99","textTraditional":"三四九０頁一五行　言易可（輕）〔傾〕危也。　景祐、殿本都作「傾」，王先謙說作「傾」是。","sentenceOrder":243},
  {"id":"s_work_han_thu_99_244","chapterId":"ch_work_han_thu_99","textTraditional":"三四九一頁　七行　（令）〔今〕諸大夫有材能者甚少，　景祐、殿、局本都作「今」，此誤。","sentenceOrder":244},
  {"id":"s_work_han_thu_99_245","chapterId":"ch_work_han_thu_99","textTraditional":"三四九八頁一一行　甚傷尊（卑）〔尊〕之義，　景祐、殿本都作「尊尊」，通鑑同。","sentenceOrder":245},
  {"id":"s_work_han_thu_99_246","chapterId":"ch_work_han_thu_99","textTraditional":"三四九八頁一五行　愚（贛）〔戇〕數犯忌諱，　景祐、殿本都作「戇」。王先謙說此脫「戇」下「心」。","sentenceOrder":246},
  {"id":"s_work_han_thu_99_247","chapterId":"ch_work_han_thu_99","textTraditional":"三五００頁一０行　收采其功，以（明）〔免〕罪過也。　景祐、殿本都作「免」。王先謙說作「免」是。","sentenceOrder":247},
  {"id":"s_work_han_thu_99_248","chapterId":"ch_work_han_thu_99","textTraditional":"三五０四頁　二行　陰陽溷濁之（患）〔應〕也。　景祐、殿本都作「應」。","sentenceOrder":248},
  {"id":"s_work_han_thu_99_249","chapterId":"ch_work_han_thu_99","textTraditional":"三五一０頁一三行　違俗則（免）〔危〕殆，　景祐、殿本都作「危」。","sentenceOrder":249},
  {"id":"s_work_han_thu_100_1","chapterId":"ch_work_han_thu_100","textTraditional":"師古曰：「自長楊賦以後分為下卷。」","sentenceOrder":1},
  {"id":"s_work_han_thu_100_2","chapterId":"ch_work_han_thu_100","textTraditional":"揚雄字子雲，蜀郡成都人也。其先出自有周伯僑者，以支庶初食采於晉之（楊）〔揚〕，〔一〕因氏焉，不知伯僑周何別也。〔二〕揚在河、汾之間，〔三〕周衰而揚氏或稱侯，號曰揚侯。會晉六卿爭權，韓、魏、趙興而范中行、知伯弊。當是時，偪揚侯，〔四〕揚侯逃於楚巫山，因家焉。〔五〕楚漢之興也，揚氏溯江上，處巴江州。〔六〕而揚季官至廬江太守，漢元鼎間避仇復溯江上，處瑉山之陽曰郫，〔七〕有田一〈土廛〉，有宅一區，〔八〕世世以農桑為業。自季至雄，五世而傳一子，故雄亡它揚於蜀。〔九〕","sentenceOrder":2},
  {"id":"s_work_han_thu_100_3","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「采，官也。以官受地，謂之采地。」","sentenceOrder":3},
  {"id":"s_work_han_thu_100_4","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「別謂分系緒也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_100_5","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　應劭曰：「左傳霍、揚、韓、魏皆姬姓也。揚，今河東揚縣。」","sentenceOrder":5},
  {"id":"s_work_han_thu_100_6","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　晉灼曰：「漢名臣奏載張衡說，云晉大夫食采於揚，為揚氏，食我有罪而揚氏滅。無揚侯。有揚侯則非六卿所偪也。」師古曰：「晉說是也。雄之自序譜諜蓋為疏謬，范中行不與知伯同時滅，何得言當是時偪揚侯乎？偪，古逼（也）〔字〕。」","sentenceOrder":6},
  {"id":"s_work_han_thu_100_7","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　師古曰：「巫山，今在荊州西南也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_100_8","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　李奇曰：「江州，縣名也，巴郡所治也。」師古曰：「遡謂逆流而上也，音素。」","sentenceOrder":8},
  {"id":"s_work_han_thu_100_9","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　師古曰：「瑉山，江水所出也。山南曰陽。郫，縣名也。瑉音旻。郫音疲。」","sentenceOrder":9},
  {"id":"s_work_han_thu_100_10","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　晉灼曰：「周禮，上地夫一〈土廛〉，一百畝也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_100_11","chapterId":"ch_work_han_thu_100","textTraditional":"〔九〕　師古曰：「蜀諸姓揚者皆非雄族，故言雄無它揚。」","sentenceOrder":11},
  {"id":"s_work_han_thu_100_12","chapterId":"ch_work_han_thu_100","textTraditional":"雄少而好學，不為章句，訓詁通而已，〔一〕博覽無所不見。為人簡易佚蕩，〔二〕口吃不能劇談，〔三〕默而好深湛之思，〔四〕清靜亡為，少耆欲，〔五〕不汲汲於富貴，不戚戚於貧賤，〔六〕不修廉隅以徼名當世。〔七〕家產不過十金，乏無儋石之儲，晏如也。〔八〕自有大度，非聖哲之書不好也；非其意，雖富貴不事也。顧嘗好辭賦。〔九〕","sentenceOrder":12},
  {"id":"s_work_han_thu_100_13","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「詁謂指義也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_100_14","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　張晏曰：「佚音鐵。蕩音讜。」晉灼曰：「佚蕩，緩也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_100_15","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　鄭氏曰：「劇，甚也。」晉灼曰：「或作遽。遽，疾也。口吃不能疾言。」師古曰：「劇亦疾也，無煩作遽也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_100_16","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　師古曰：「湛讀曰沈。」","sentenceOrder":16},
  {"id":"s_work_han_thu_100_17","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　師古曰：「耆讀曰嗜。」","sentenceOrder":17},
  {"id":"s_work_han_thu_100_18","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　師古曰：「汲汲，欲速之義，如井汲之為也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_100_19","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　師古曰：「徼，要也，音工堯反。徼字或作激。激，發也，音工歷反。」","sentenceOrder":19},
  {"id":"s_work_han_thu_100_20","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　師古曰：「儋石，解在蒯通傳。」","sentenceOrder":20},
  {"id":"s_work_han_thu_100_21","chapterId":"ch_work_han_thu_100","textTraditional":"〔九〕　師古曰：「顧，反也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_100_22","chapterId":"ch_work_han_thu_100","textTraditional":"先是時，蜀有司馬相如，作賦甚弘麗溫雅，雄心壯之，每作賦，常擬之以為式。〔一〕又怪屈原文過相如，至不容，作離騷，自投江而死，悲其文，讀之未嘗不流涕也。以為君子得時則大行，不得時則龍蛇，〔二〕遇不遇命也，何必湛身哉！〔三〕乃作書，往往摭離騷文而反之，〔四〕自崏山投諸江流以弔屈原，名曰反離騷；又旁離騷作重一篇，名曰廣騷；〔五〕又旁惜誦以下至懷沙一卷，名曰畔牢愁。〔六〕畔牢愁、廣騷文多不載，獨載反離騷，其辭曰：","sentenceOrder":22},
  {"id":"s_work_han_thu_100_23","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「擬謂比象也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_100_24","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　應劭曰：「易曰『龍蛇之蟄，以存身也』。」師古曰：「大行，安步徐行。」","sentenceOrder":24},
  {"id":"s_work_han_thu_100_25","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「湛讀曰沈。謂投水而死。」","sentenceOrder":25},
  {"id":"s_work_han_thu_100_26","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　師古曰：「摭，拾取也，音之亦反。」","sentenceOrder":26},
  {"id":"s_work_han_thu_100_27","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　師古曰：「旁，依也，音步浪反。其下類此。重音直用反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_100_28","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　李奇曰：「畔，離也。牢，聊也。與君相離，愁而無聊也。」師古曰：「惜誦、懷沙皆屈原所作九章中之名也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_100_29","chapterId":"ch_work_han_thu_100","textTraditional":"有周氏之蟬嫣兮，或鼻祖於汾隅，〔一〕靈宗初諜伯僑兮，流于末之揚侯。〔二〕淑周楚之豐烈兮，超既離虖皇波，〔三〕因江潭而〈氵往〉記兮，欽弔楚之湘纍。〔四〕","sentenceOrder":29},
  {"id":"s_work_han_thu_100_30","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　應劭曰：「嬋嫣，連也，言與周氏親連也。」劉德曰：「鼻，始也。」師古曰：「雄自言系出周氏而食采於揚，故云始祖於汾隅也。嫣音於連反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_100_31","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　應劭曰：「諜，譜也，言從伯僑以來可得而敘也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_100_32","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　應劭曰：「淑，善也。言去汾隅從巫山得周楚之美烈也。超，速也。」晉灼曰：「離，歷也。皇，大也。」師古曰：「言其先祖所居經河及江也。河江，四瀆之水，故云大波也。虖，古乎字。其下並同。」","sentenceOrder":32},
  {"id":"s_work_han_thu_100_33","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　蘇林曰：「潭，水邊也。」鄧展曰：「〈氵往〉，往也。」李奇曰：「諸不以罪死曰纍，荀息、仇牧皆是也。屈原赴湘死，故曰湘纍也。」師古曰：「記，書記也，謂弔文也。言因江水之邊而投書記以往弔也。欽，敬也。潭音尋。〈氵往〉音于放反。纍音力追反。」","sentenceOrder":33},
  {"id":"s_work_han_thu_100_34","chapterId":"ch_work_han_thu_100","textTraditional":"惟天軌之不辟兮，何純絜而離紛！〔一〕紛纍以其淟涊兮，暗纍以其繽紛。〔二〕","sentenceOrder":34},
  {"id":"s_work_han_thu_100_35","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「天軌，猶言天路。辟，開也。離，遭也。紛，難也。言天路不開，故使純善貞絜之人遭此難也。易曰：『天地閉，賢人隱。』辟讀曰闢。」","sentenceOrder":35},
  {"id":"s_work_han_thu_100_36","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　應劭曰：「淟涊，穢濁也。」師古曰：「繽紛，交雜也。淟音吐典反。涊音乃典反。繽音匹人反。」","sentenceOrder":36},
  {"id":"s_work_han_thu_100_37","chapterId":"ch_work_han_thu_100","textTraditional":"漢十世之陽朔兮，招搖紀于周正，〔一〕正皇天之清則兮，度后土之方貞。〔二〕圖纍承彼洪族兮，又覽纍之昌辭，〔三〕帶鉤矩而佩衡兮，履欃槍以為綦。〔四〕素初貯厥麗服兮，何文肆而質！〔五〕資娵娃之珍髢兮，鬻九戎而索賴。〔六〕","sentenceOrder":37},
  {"id":"s_work_han_thu_100_38","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　晉灼曰：「十世數高祖、呂后至成帝也。成帝八年乃稱陽朔。」應劭曰：「招搖，斗杓星也，主天時。周正，十一月也。」蘇林曰：「言己以此時弔屈原也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_100_39","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　應劭曰：「平正司法者莫過於天，養物均調者莫過於地也。父伯庸名我為平以法天，字我為原以法地也。」晉灼曰：「此雄取離騷辭反之，應說是也。」師古曰：「應、晉二說皆非也。自漢十世以下，四句不道屈原也，此乃雄自論己心所履行取法天地耳。自圖纍以下方論屈原云也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_100_40","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「圖，按其本系之圖書也。洪，大也。覽，省視也。昌，美也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_100_41","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　應劭曰：「鉤，規也。矩，方也。衡，平也。」鄧展曰：「欃槍，妖星也。」晉灼曰：「綦，履跡也。此反屈原雖佩帶方平之行，而蹈惡人跡，以致放退也。」師古曰：「綦，履下飾也。欃音初咸反。槍音初行反。綦音其。」","sentenceOrder":41},
  {"id":"s_work_han_thu_100_42","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　應劭曰：「貯，積也。肆，放也。，狹也。」如淳曰：「文肆者，楚辭遠游乘龍之言也。質者，恨世不用己而自沈也。」師古曰：「麗服謂『扈江離與辟芷，紉秋蘭以為佩』之類是也。音械。」","sentenceOrder":42},
  {"id":"s_work_han_thu_100_43","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　孟康曰：「娵，閭娵也。娃，吳娃也。髢，髮也。賴，得也。九戎被髮，髢雖珍好，無所用也。」師古曰：「娵、娃皆美女也。賴，利也。言屈原以高行仕楚，亦猶資美女之髢賣於九戎而求其利，必不得也。娵音子踰反。娃音烏佳反。髢音徒計反。」","sentenceOrder":43},
  {"id":"s_work_han_thu_100_44","chapterId":"ch_work_han_thu_100","textTraditional":"鳳皇翔於蓬陼兮，豈鴐鵝之能捷！〔一〕騁驊騮以曲艱兮，驢騾連蹇而齊足。〔二〕枳棘之榛榛兮，蝯貁擬而不敢下，〔三〕靈修既信椒、蘭之唼佞兮，吾纍忽焉而不蚤睹？〔四〕","sentenceOrder":44},
  {"id":"s_work_han_thu_100_45","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　應劭曰：「蓬陼，蓬萊之陼也，在海中。」晉灼曰：「捷，及也。」師古曰：「鴐鵝，鳥名也，解在司馬相如傳。鴐音加。」","sentenceOrder":45},
  {"id":"s_work_han_thu_100_46","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「驊騮，駿馬名也，其色如華而赤也。言使駿馬馳騖於屈曲艱阻之中，則與驢騾齊足也。驊音華。連音力展反。囏，古艱字。」","sentenceOrder":46},
  {"id":"s_work_han_thu_100_47","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「榛榛，梗穢貌也。蝯，善攀援。貁似猴，卬鼻而長尾。擬，疑也。榛音臻，又士臻反。貁音弋授反。」","sentenceOrder":47},
  {"id":"s_work_han_thu_100_48","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　服虔曰：「靈修，楚王也。」蘇林曰：「椒、蘭，令尹子椒、子蘭也。」師古曰：「蚤，古早字也。唼佞，譖言也。唼音妾。」","sentenceOrder":48},
  {"id":"s_work_han_thu_100_49","chapterId":"ch_work_han_thu_100","textTraditional":"衿芰茄之綠衣兮，被夫容之朱裳，〔一〕芳酷烈而莫聞兮，（固）不如襞而幽之離房。〔二〕閨中容競淖約兮，相態以麗佳〔三〕，知眾嫭之嫉妒兮，何必颺纍之蛾眉？〔四〕","sentenceOrder":49},
  {"id":"s_work_han_thu_100_50","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　應劭曰：「衿音衿系之衿。衿，帶也。芰，陵也。」師古曰：「衿音其禁反。茄亦荷字也，見張揖古今字譜。被音披，又音皮義反。」","sentenceOrder":50},
  {"id":"s_work_han_thu_100_51","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「襞，疊衣也。離房，別房也。襞音壁。」","sentenceOrder":51},
  {"id":"s_work_han_thu_100_52","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　應劭曰：「眾士競善，猶女競容也。」師古曰：「淖約，善容止也。相態以麗佳，言競為佳麗之態以相傾也。淖音綽。」","sentenceOrder":52},
  {"id":"s_work_han_thu_100_53","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　晉灼曰：「離騷云『眾女嫉余之蛾眉』。」師古曰：「嫭，美貌也。颺，古揚字也。蛾眉，形若蠶蛾眉也。此亦譏屈原自舉蛾眾嫉之。嫭音胡故反。睂，古眉字。」","sentenceOrder":53},
  {"id":"s_work_han_thu_100_54","chapterId":"ch_work_han_thu_100","textTraditional":"懿神龍之淵潛，俟慶雲而將舉，亡春風之被離兮，孰焉知龍之所處？〔一〕愍吾纍之眾芬兮，颺煜煜之芳苓，遭季夏之凝霜兮，慶夭悴而喪榮。〔二〕","sentenceOrder":54},
  {"id":"s_work_han_thu_100_55","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　晉灼曰：「龍俟風雲而後升，士須明君而後進。國無道則愚，誰知其所邪？」師古曰：「懿，美也。俟，待也。龍以潛居待雲為美，以譏屈原不能隱德，自取禍也。被讀曰披。」","sentenceOrder":55},
  {"id":"s_work_han_thu_100_56","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　晉灼曰：「雄愍屈原光香，奄先秋遇凋，生亦不辰也。」張晏曰：「慶，辭也。」師古曰：「煜煜，光盛。苓，香草名，音零。慶讀與羌同。顇，古悴字。」","sentenceOrder":56},
  {"id":"s_work_han_thu_100_57","chapterId":"ch_work_han_thu_100","textTraditional":"橫江、湘以南〈氵往〉兮，云走乎彼蒼吾，馳江潭之汎溢兮，將折衷虖重華。〔一〕舒中情之煩或兮，恐重華之不纍與，〔二〕陵陽侯之素波兮，豈吾纍之獨見許？〔三〕","sentenceOrder":57},
  {"id":"s_work_han_thu_100_58","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　應劭曰：「舜葬蒼梧，在江湘之南，屈原欲啟質聖人，陳己情要也。」師古曰：「〈氵往〉，往也。走，趣也。重華，舜名也。〈氵往〉音于放反。走音奏。潭音尋。衷音竹仲反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_100_59","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　張晏曰：「舜聖，卒避父害以全身，資於事父以事君，恐不與屈原為黨與。」","sentenceOrder":59},
  {"id":"s_work_han_thu_100_60","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　應劭曰：「陽侯，古之諸侯也，有罪自投江，其神為大波。陵，乘也。言屈原襲陽侯之罪，而欲折中求舜，未必獨見然許之也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_100_61","chapterId":"ch_work_han_thu_100","textTraditional":"精瓊靡與秋菊兮，將以延夫天年；臨汨羅而自隕兮，恐日薄於西山。〔一〕解扶桑之總轡兮，縱令之遂奔馳，〔二〕鸞皇騰而不屬兮，豈獨飛廉與雲師！〔三〕","sentenceOrder":61},
  {"id":"s_work_han_thu_100_62","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　應劭曰：「精，細；靡，屑也。瓊，玉之華也。」晉灼曰：「離騷云『精瓊靡以為粻兮』，『予夕餐秋菊之落英』。又曰『老冉冉其將至』，『日忽忽其將暮』。」師古曰：「此又譏屈原，云瓊靡秋菊，將以延年，崦嵫忽迫，喜於未暮，何乃自投汨羅，言行相反！」","sentenceOrder":62},
  {"id":"s_work_han_thu_100_63","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　應劭曰：「總，結也。扶桑，日所拂木也。」晉灼曰：「離騷云『總余轡於扶桑，聊消搖以相羊』。屈原言結我車轡於扶桑，以留日之入，人年得不老。日以喻君，而反離朝自沈，解轡縱君，使遂奔馳也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_100_64","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　應劭曰：「楚辭云『鸞皇為余先戒兮』，『後飛廉使奔屬』，『雲師告余以未具』。飛廉，風伯也。雲師，豐隆也。鸞皇，俊鳥也。」晉灼曰：「已縱其轡使之奔馳，鸞皇迅飛亦無所及，非獨飛廉、雲師，言莊嚴未具，使君不適道也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_100_65","chapterId":"ch_work_han_thu_100","textTraditional":"卷薜芷與若蕙兮，臨湘淵而投之；棍申椒與菌桂兮，赴江湖而漚之。〔一〕費椒稰以要神兮，又勤索彼瓊茅，〔二〕違靈氛而不從兮，反湛身於江皋！〔三〕","sentenceOrder":65},
  {"id":"s_work_han_thu_100_66","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「離騷云『貫薜荔之落蘂』，『雜杜衡與芳芷』，『又樹蕙之百畝』，『雜申椒與菌桂』，皆以自喻德行芬芳也。今何為自投江湘而喪此芳乎？棍，大束也。漚，漬也，今漚麻也。棍音下本反，漚音一搆反。又音一侯反。」","sentenceOrder":66},
  {"id":"s_work_han_thu_100_67","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　孟康曰：「椒稰，以椒香米饌也。離騷曰『懷椒稰而要之』。」晉灼曰：「離騷云『索瓊茅以莛篿』。」師古曰：「索，求也。瓊茅，靈草也。筳篿，析竹所用卜也。稰音所，又音思呂反。筳音廷。篿音專。」","sentenceOrder":67},
  {"id":"s_work_han_thu_100_68","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　晉灼曰：「靈氛，古之善占者。離騷曰『欲從靈氛之吉占兮，心猶豫而狐疑』。」師古曰：「既不從靈氛之占，何為費椒稰而勤瓊茅也？湛讀曰沈。江皋，江水邊之游地也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_100_69","chapterId":"ch_work_han_thu_100","textTraditional":"纍既乑夫傅說兮，奚不信而遂行？〔一〕徒恐鷤〈圭鳥〉之將鳴兮，顧先百草為不芳！〔二〕","sentenceOrder":69},
  {"id":"s_work_han_thu_100_70","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　晉灼曰：「乑，慕也。離騷曰『說操築於傅巖兮，武丁用之而不疑』。」師古曰：「乑，古攀字。既攀援傅說，何不信其所行，自見用而遂去？」","sentenceOrder":70},
  {"id":"s_work_han_thu_100_71","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「離騷云『鷤〈圭鳥〉之先鳴兮，使夫百草為不芳』。雄言終以自沈，何惜芳草而憂鷤〈圭鳥〉也？〈圭鳥〉，鴃字也。鷤鴃鳥一名買〈金危〉，一名子規，一名杜鵑，常以立夏鳴，鳴則眾芳皆歇。鷤音大系反。〈圭鳥〉音桂。鷤字或作鶗，亦音題。鴃又音決。〈金危〉音詭。」","sentenceOrder":71},
  {"id":"s_work_han_thu_100_72","chapterId":"ch_work_han_thu_100","textTraditional":"初纍棄彼虙妃兮，更思瑤臺之逸女，〔一〕抨雄鴆以作媒兮，何百離而曾不壹耦！〔二〕乘雲蜺之旖柅兮，望昆侖以樛流，覽四荒而顧懷兮，奚必云女彼高丘？〔三〕","sentenceOrder":72},
  {"id":"s_work_han_thu_100_73","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「離騷云『吾命豐隆乘雲兮，求虙妃之所在』，又曰『望瑤臺之偃蹇兮，見有娀之佚女』。此又譏其執心不定也。虙妃，古神女。有娀女，即簡狄也。虙讀曰伏。」","sentenceOrder":73},
  {"id":"s_work_han_thu_100_74","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「離騷云『吾令鴆為媒兮，鴆告余以不好，雄鴆之鳴逝兮，余猶惡其佻巧』，故云百離不一耦也。抨，使也。耦，合也。抨音普耕反。」","sentenceOrder":74},
  {"id":"s_work_han_thu_100_75","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　蘇林曰：「離騷云『登閬風而緤馬，忽反顧以流涕，哀高丘之無女。』女以喻士，高丘謂楚也。」師古曰：「離騷又云『揚雲蜺之晻藹』。閬風在昆侖山上，故云望昆侖也。旖柅，雲貌也。樛流猶周流也。女，仕也，何必要仕於楚也。旖音於綺反。旎音女綺反。樛音居虯反。女音尼據反。」","sentenceOrder":75},
  {"id":"s_work_han_thu_100_76","chapterId":"ch_work_han_thu_100","textTraditional":"既亡鸞車之幽藹兮，（焉）駕八龍之委蛇？〔一〕臨江瀕而掩涕兮，何有九招與九歌？〔二〕夫聖哲之（不）遭兮，固時命之所有；雖增欷以於邑兮，吾恐靈修之不纍改。〔三〕昔仲尼之去魯兮，婓婓遲遲而周邁，〔四〕終回復於舊都兮，何必湘淵與濤瀨！〔五〕溷漁父之餔歠兮，絜沐浴之振衣，〔六〕棄由、聃之所珍兮，蹠彭咸之所遺！〔七〕","sentenceOrder":76},
  {"id":"s_work_han_thu_100_77","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　晉灼曰：「離騷云『駕八龍之蜿蜿兮，載雲旗之委蛇』。」師古曰：「言既無鸞車，則不得云駕八龍也。幽藹猶晻藹也。蛇音移。」","sentenceOrder":77},
  {"id":"s_work_han_thu_100_78","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　晉灼曰：「離騷云『攬茹蕙以掩涕』，又曰『奏九歌以舞韶』。」師古曰：「此又譏其哀樂不相副也。招讀曰韶。」","sentenceOrder":78},
  {"id":"s_work_han_thu_100_79","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「離騷云『曾歔欷余鬱邑兮，哀朕時之不當』。增，重也。雄言自古聖哲，皆有不遇，屈原雖自歎於邑，而楚王終不改寤也。於邑，短氣也。於音烏。邑音烏合反。於邑亦讀如本字。」","sentenceOrder":79},
  {"id":"s_work_han_thu_100_80","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　師古曰：「婓婓，往來貌也。音芳非反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_100_81","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　師古曰：「言孔子去其本邦，遲遲系戀，意在舊都，裴回反覆。屈原何獨不懷鄢郢而赴江湘也？濤，大波也。瀨，急流也。濤音大高反。」","sentenceOrder":81},
  {"id":"s_work_han_thu_100_82","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　師古曰：「漁父云『何不餔其糟而歠其醨』？屈原以為溷濁，不肯從之，乃云：『新沐者必彈冠，新浴者必振衣也。』餔音必胡反。歠音昌悅反。」","sentenceOrder":82},
  {"id":"s_work_han_thu_100_83","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　師古曰：「由，許由也。聃，老聃也。二人守道，不為時俗所汙，然保己全身，無殘辱之醜。彭咸，殷之介士也，不得其志，投江而死。此又非屈原不慕由、聃高蹤，而遵彭咸遺蹟。蹠，蹈也，（亦）〔音〕之亦反。」","sentenceOrder":83},
  {"id":"s_work_han_thu_100_84","chapterId":"ch_work_han_thu_100","textTraditional":"孝成帝時，客有薦雄文似相如者，上方郊祠甘泉泰畤、汾陰后土，以求繼嗣，召雄待詔承明之庭。〔一〕正月，從上甘泉，還奏甘泉賦以風。〔二〕其辭曰：","sentenceOrder":84},
  {"id":"s_work_han_thu_100_85","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「承明殿在未央宮。」","sentenceOrder":85},
  {"id":"s_work_han_thu_100_86","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「風讀曰諷。」","sentenceOrder":86},
  {"id":"s_work_han_thu_100_87","chapterId":"ch_work_han_thu_100","textTraditional":"惟漢十世，將郊上玄，定泰畤，雍神休，尊明號，〔一〕同符三皇，錄功五帝，卹胤錫羨，拓跡開統。〔二〕於是乃命群僚，歷吉日，協靈辰，〔三〕星陳而天行。〔四〕詔招搖與泰陰兮，伏鉤陳使當兵，〔五〕屬堪輿以壁壘兮，梢夔魖而抶獝狂。〔六〕八神奔而警蹕兮，振殷轔而軍裝；〔七〕蚩尤之倫帶干將而秉玉戚兮，飛蒙茸而走陸梁。〔八〕齊總總撙撙，其相膠葛兮，猋駭雲訊，奮以方攘；〔九〕駢羅列布，鱗以雜沓兮，柴虒參差，魚頡而鳥〈目行〉；〔一０〕翕赫曶霍，霧集蒙合兮，半散照爛，粲以成章。〔一一〕","sentenceOrder":87},
  {"id":"s_work_han_thu_100_88","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　晉灼曰：「雍，祐也。休，美也。言見祐護以休美之祥也。」師古曰：「雍，聚也。明號，謂總三皇五帝之號而稱皇帝也。雍讀曰擁。」","sentenceOrder":88},
  {"id":"s_work_han_thu_100_89","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　應劭曰：「卹，憂也。胤，續也。錫，與也。羨，饒也。拓，廣也。時成帝憂無繼嗣，故修祠泰畤、后土，言神明饒與福祥，廣跡而開統也。」師古曰：「羨音弋戰反。拓音託。」","sentenceOrder":89},
  {"id":"s_work_han_thu_100_90","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「歷選吉日而合善時也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_100_91","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　師古曰：「如星之陳，象天之行也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_100_92","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　張晏曰：「禮記云『招搖在上，急繕其怒』。太陰，歲後三辰也。」服虔曰：「鉤陳，紫宮外營陳星。」","sentenceOrder":92},
  {"id":"s_work_han_thu_100_93","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　張晏曰：「堪輿，天地總名也。」孟康曰：「堪輿，神名，造圖宅書者。木石之怪曰夔，夔神如龍，有角，人面。魖，耗鬼也。獝狂亦惡鬼也。今皆梢而去之。」師古曰：「堪輿，張說是也。屬，委也，以壁壘委之。梢，擊也。抶，笞也。梢音山交反。魖音虛。屬音之欲反。抶音丑乙反。獝音揆聿反。」","sentenceOrder":93},
  {"id":"s_work_han_thu_100_94","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　師古曰：「自招搖至獝狂，凡八神也。殷轔，盛貌也。軍裝，為軍戎之飾裝也。轔音來忍反。」","sentenceOrder":94},
  {"id":"s_work_han_thu_100_95","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　張晏曰：「玉戚，以玉為戚柲也。」晉灼曰：「飛者蒙茸而亂，走者陸梁而跳也。」師古曰：「茸音人蒙反。柲，柄也，音祕。」","sentenceOrder":95},
  {"id":"s_work_han_thu_100_96","chapterId":"ch_work_han_thu_100","textTraditional":"〔九〕　晉灼曰：「方攘，半散也。」師古曰：「總總撙撙，聚貌也。膠葛猶言膠加也。訊亦奮訊也。撙音子本反。訊音信。攘音人羊反。」","sentenceOrder":96},
  {"id":"s_work_han_thu_100_97","chapterId":"ch_work_han_thu_100","textTraditional":"〔一０〕師古曰：「柴虒參差，不齊貌也。頡〈目行〉，上下也。柴音初蟻反。虒音豸。參音初林反。頡音胡結反。〈目行〉音胡剛反。」","sentenceOrder":97},
  {"id":"s_work_han_thu_100_98","chapterId":"ch_work_han_thu_100","textTraditional":"〔一一〕師古曰：「翕赫曶霍，開合之貌也。霧，地氣發也。蒙，天氣下也。如霧之集，如蒙之合也。半散照爛，言其分布而光明也。曶讀與忽同。」","sentenceOrder":98},
  {"id":"s_work_han_thu_100_99","chapterId":"ch_work_han_thu_100","textTraditional":"於是乘輿乃登夫鳳皇兮翳華芝，〔一〕駟蒼螭兮六素虯〔二〕，蠖略蕤綏，灕虖幓纚。〔三〕帥爾陰閉，霅然陽開，〔四〕騰清霄而軼浮景兮，夫何旟旐郅偈之旖柅也！〔五〕流星旄以電燭兮，咸翠蓋而鸞旗。〔六〕敦萬騎於中營兮，方玉車之千乘。〔七〕聲駍隱以陸離兮，輕先疾雷而馺遺風。〔八〕陵高衍之嵱嵷兮，超紆譎之清澄。〔九〕登椽欒而羾天門兮，馳閶闔而入凌兢。〔一０〕","sentenceOrder":99},
  {"id":"s_work_han_thu_100_100","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「鳳皇者，車以鳳皇為飾也。翳，蔽也。以華芝為蔽也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_100_101","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「四、六，駕數也，言或四或六也。螭似龍，一名地螻。虯即龍之無角者。」","sentenceOrder":101},
  {"id":"s_work_han_thu_100_102","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「蠖略蕤綏，虯螭貌也。灕虖幓纚，車飾貌也。蠖音於鑊反。灕音離。幓森，其字從巾。纚音所宜反。」","sentenceOrder":102},
  {"id":"s_work_han_thu_100_103","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　晉灼曰：「帥，聚也。霅，散也。」師古曰：「霅音所甲反，又音先合反。」","sentenceOrder":103},
  {"id":"s_work_han_thu_100_104","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　師古曰：「騰，升也。霄，日旁氣也。軼，過也。畫鳥隼曰旟，龜蛇曰旐。郅偈，竿杠之狀也。旖柅，旒縿之形也。郅音吉，又音質。偈音居桀反。旖音猗。柅音女支反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_100_105","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　師古曰：「如星之流，如電之照也。咸，皆也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_100_106","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　師古曰：「敦讀曰屯。屯，聚也。方，並也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_100_107","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　師古曰：「馺然，疾意也。駍音普萌反。馺音先合反。」","sentenceOrder":107},
  {"id":"s_work_han_thu_100_108","chapterId":"ch_work_han_thu_100","textTraditional":"〔九〕　孟康曰：「衍，無厓岸也。紆譎，曲折也。」李奇曰：「嵱音踊。嵷音竦。」如淳曰：「嵱嵷，上下眾多貌。」師古曰：「衍即所謂墳衍者也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_100_109","chapterId":"ch_work_han_thu_100","textTraditional":"〔一０〕服虔曰：「椽欒，甘泉南山也。」李奇曰：「羾音貢。」蘇林曰：「羾，至也。」師古曰：「入凌兢者，（亦）〔言〕寒涼戰栗之處也。兢音鉅陵反。」","sentenceOrder":109},
  {"id":"s_work_han_thu_100_110","chapterId":"ch_work_han_thu_100","textTraditional":"是時未轃夫甘泉也，乃望通天之繹繹。〔一〕下陰潛以慘廩兮，上洪紛而相錯；〔二〕直嶢嶢以造天兮，厥高慶而不可虖疆度。〔三〕平原唐其壇曼兮，列新雉於林薄；〔四〕攢并閭與茇{艹舌}兮，紛被麗其亡鄂。〔五〕崇丘陵之駊騀兮，深溝嶔巖而為谷；〔六〕〈辶{山王}〉〈辶{山王}〉離宮般以相燭兮，封巒石關施靡虖延屬。〔七〕","sentenceOrder":110},
  {"id":"s_work_han_thu_100_111","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「轃與臻同，轃，至也。通天，臺名也。言雖未至甘泉，則遙望見通天臺也。繹繹，相連貌。」","sentenceOrder":111},
  {"id":"s_work_han_thu_100_112","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「慘廩，亦寒涼之意也。洪，大也。紛，亂雜也。錯，互也。廩讀如本字，又音來感反。」","sentenceOrder":112},
  {"id":"s_work_han_thu_100_113","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「嶢嶢，高貌。造，至也。慶，發語辭也。疆，境也。度，量也。言此臺至天，其高不可究竟而量度也。嶢音堯。造音千到反。慶讀曰羌。度音大各反。」","sentenceOrder":113},
  {"id":"s_work_han_thu_100_114","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　鄧展曰：「唐，道也。」服虔曰：「新雉，香草也。雉、夷聲相近。」師古曰：「言平原之道壇曼然廣大，又列樹辛夷於林薄之間也。草藂生曰薄。新雉即辛夷耳，為樹甚大，非香草也。其木枝葉皆芳，一名新矧。壇音徒旦反。曼音莫旦反。」","sentenceOrder":114},
  {"id":"s_work_han_thu_100_115","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　如淳曰：「并閭，其葉隨時政，政平則平，政不平則傾也。」師古曰：「如氏所說自是平慮耳。此并閭謂椶樹也。茇{艹舌}，草名也。鄂，垠也。茇音步末反。{艹舌}音括。被，皮義反。麗讀如本字。被麗又音披離。」","sentenceOrder":115},
  {"id":"s_work_han_thu_100_116","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　蘇林曰：「駊騀音叵我。」師古曰：「駊騀，高大狀也。嶔巖，深險貌也。嶔音口銜反。」","sentenceOrder":116},
  {"id":"s_work_han_thu_100_117","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　應劭曰：「言秦離宮三百，武帝復往往修治之。」師古曰：「〈辶{山王}〉，古往字。往往，言所往之處則有之。般，連貌也。燭，照也。封巒、石關皆宮名也。施靡，相及貌。屬，連也。般音盤。施音弋爾反。屬音之欲反。」","sentenceOrder":117},
  {"id":"s_work_han_thu_100_118","chapterId":"ch_work_han_thu_100","textTraditional":"於是大夏雲譎波詭，嶊嶉而成觀，〔一〕仰撟首以高視兮，目冥眴而亡見。〔二〕正瀏濫以弘惝兮，指東西之漫漫，〔三〕徒回回以徨徨兮，魂固眇眇而昏亂。〔四〕據軨軒而周流兮，忽軮軋而亡垠。〔五〕翠玉樹之青蔥兮，壁馬犀之瞵〈王扁〉。〔六〕金人仡仡其承鍾虡兮，嵌巖巖其龍鱗，〔七〕揚光曜之燎燭兮，乘景炎之炘炘，〔八〕配帝居之縣圃兮，象泰壹之威神。〔九〕洪臺掘其獨出兮，〈扌致〉北極之嶟嶟，〔一０〕列宿乃施於上榮兮，日月纔經於柍桭，〔一一〕雷鬱律而巖突兮，電倏忽於牆藩。〔一二〕鬼魅不能自還兮，半長途而下顛。〔一三〕歷倒景而絕飛梁兮，浮蔑蠓而撇天。〔一四〕","sentenceOrder":118},
  {"id":"s_work_han_thu_100_119","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　孟康曰：「言夏屋變巧，乃為雲氣水波相譎詭也。嶊嶉，材木之崇積貌也。」晉灼曰：「嶊音〈輕，中“車改赤”〉水反。」師古曰：「嶉音子水反。觀謂形也，音工喚反。〈輕，中“車改赤”〉音丑成反。」","sentenceOrder":119},
  {"id":"s_work_han_thu_100_120","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「撟，舉也。冥眴，視不諦也。撟與矯同，其字從手。冥音莫見反。眴音州縣之縣。」","sentenceOrder":120},
  {"id":"s_work_han_thu_100_121","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　服虔曰：「惝音敞。」師古曰：「瀏濫猶汎濫。弘惝，高大也。漫漫，長也。瀏音劉。」","sentenceOrder":121},
  {"id":"s_work_han_thu_100_122","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　師古曰：「言駭其深博。」","sentenceOrder":122},
  {"id":"s_work_han_thu_100_123","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　師古曰：「軨軒謂前軒之軨也。軨者，軒間小木也，字與櫺同。周流，周視也。軮軋，遠相映也。軨音零。軮音烏朗反。軋音於黠反。」","sentenceOrder":123},
  {"id":"s_work_han_thu_100_124","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　應劭曰：「瞵音鄰。」晉灼曰：「〈王扁〉音豳。」師古曰：「玉樹者，武帝所作，集眾寶為之，用供神也，非謂自然生之。而左思不曉其意，以為非本土所出，蓋失之矣。馬犀者，馬腦及犀角也。以此二種飾殿之壁。瞵〈王扁〉，文貌。」","sentenceOrder":124},
  {"id":"s_work_han_thu_100_125","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　師古曰：「仡仡，勇健狀。嵌，開張貌，言其鱗甲開張，若真龍之形也。仡音魚乙反，又音其乞反。嵌音火敢反。」","sentenceOrder":125},
  {"id":"s_work_han_thu_100_126","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　師古曰：「炘炘，光盛貌也。炎音弋贍反。炘音欣。」","sentenceOrder":126},
  {"id":"s_work_han_thu_100_127","chapterId":"ch_work_han_thu_100","textTraditional":"〔九〕　服虔曰：「曾城、縣圃、閬風，昆侖之山三重也，天帝神在其上。」","sentenceOrder":127},
  {"id":"s_work_han_thu_100_128","chapterId":"ch_work_han_thu_100","textTraditional":"〔一０〕應劭曰：「掘，特貌也。〈扌致〉，至也。」晉灼曰：「嶟嶟，穊〈扌致〉也。」師古曰：「言高臺特出乃至北極，其狀竦峭，嶟嶟然也。掘音其勿反。〈扌致〉音竹指反。嶟音千旬反，又音遵。」","sentenceOrder":128},
  {"id":"s_work_han_thu_100_129","chapterId":"ch_work_han_thu_100","textTraditional":"〔一一〕服虔曰：「柍，中央也。桭，屋梠也。」師古曰：「施，延也。榮，屋翼也。凡此者言屋宇高大之甚。施音弋豉反。柍音央。桭音辰。一曰施，直謂安施（音）之耳，讀如本字。」","sentenceOrder":129},
  {"id":"s_work_han_thu_100_130","chapterId":"ch_work_han_thu_100","textTraditional":"〔一二〕師古曰：「鬱律，雷聲也。倏忽，電光也。藩，藩籬也。倏音式六反。藩音甫元反。」","sentenceOrder":130},
  {"id":"s_work_han_thu_100_131","chapterId":"ch_work_han_thu_100","textTraditional":"〔一三〕師古曰：「言屋之高深，雖鬼魅亦不能至其極而反，故於長途之半而顛墜也。還讀曰旋，或作逮。逮，及也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_100_132","chapterId":"ch_work_han_thu_100","textTraditional":"〔一四〕晉灼曰：「飛梁，浮道之橋也。蔑蠓，（疾）〔蚊〕也。」師古曰：「撇猶拂也。蠓音莫孔反。撇音匹列反，又音普結反。」","sentenceOrder":132},
  {"id":"s_work_han_thu_100_133","chapterId":"ch_work_han_thu_100","textTraditional":"左欃槍右玄冥兮，前熛闕後應門；〔一〕陰西海與幽都兮，涌醴汨以生川。〔二〕蛟龍連蜷於東厓兮，白虎敦圉虖昆侖。〔三〕覽樛流於高光兮，溶方皇於西清。〔四〕前殿崔巍兮，和氏瓏玲〔五〕，炕浮柱之飛榱兮，神莫莫而扶傾，〔六〕閌閬閬其寥廓兮，似紫宮之崢嶸。〔七〕駢交錯而曼衍兮，〈山妥〉嶵隗虖其相嬰。〔八〕乘雲閣而上下兮，紛蒙籠以掍成。〔九〕曳紅采之流離兮，颺翠氣之冤延。〔一０〕襲琁室與傾宮兮，若登高妙遠，肅虖臨淵。〔一一〕","sentenceOrder":133},
  {"id":"s_work_han_thu_100_134","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　晉灼曰：「大人賦『檻欃槍以為旌』。又曰『左玄冥而右黔雷』。雄擬相如故云爾。熛闕，赤色之闕，南方之帝曰赤熛怒，應門正在熛闕之內也。」師古曰：「熛音匹遙反。」","sentenceOrder":134},
  {"id":"s_work_han_thu_100_135","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　如淳曰：「言闕之高乃陰西海也。」師古曰：「蔭映西海也，以及幽都。幽都，北方絕遠之地也。涌醴，醴泉涌出汨汨然也。汨音于筆反。」","sentenceOrder":135},
  {"id":"s_work_han_thu_100_136","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「連蜷，卷曲貌。敦圉，盛怒也。言甘泉宮中皆有此象也。蜷音拳，敦音屯。」","sentenceOrder":136},
  {"id":"s_work_han_thu_100_137","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　服虔曰：「高光，宮名也。」師古曰：「樛流，屈折也。溶然，閑暇貌也。方皇，彷徨也。西清，西廂清閒之處也。溶音容。」","sentenceOrder":137},
  {"id":"s_work_han_thu_100_138","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　孟康曰：「以和氏璧為梁壁帶也，其聲玲瓏也。」晉灼曰：「以黃金為壁帶，含藍田璧。瓏玲，明見貌也。」師古曰：「崔巍，高貌。瓏玲，晉說是也。崔音才回反。巍音五回反。瓏音聾。玲音零。」","sentenceOrder":138},
  {"id":"s_work_han_thu_100_139","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　師古曰：「炕與抗同。抗，舉也。榱，屋椽也。言舉立浮柱而駕飛榱，其形危竦，有神於闇莫之中扶持，故不傾也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_100_140","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　師古曰：「閌，高門貌。閬閬，空虛也。寥廓，宏遠也。紫宮，天帝之宮也。崢嶸，深邃也。閌音抗。閬音浪。寥音僚。崢音仕耕反。嶸音宏。」","sentenceOrder":140},
  {"id":"s_work_han_thu_100_141","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　師古曰：「言宮室臺觀相連不絕也。〈山妥〉，安施之貌。嶵隗猶崔巍也。衍音（赤）〔亦〕戰反。〈山妥〉音它賄反。嶵音罪。隗音五賄反。」","sentenceOrder":141},
  {"id":"s_work_han_thu_100_142","chapterId":"ch_work_han_thu_100","textTraditional":"〔九〕　師古曰：「乘，登也。雲閣，亦言其高入於雲也。蒙籠，深通貌。掍成，言其有若自然也。掍音胡本反。」","sentenceOrder":142},
  {"id":"s_work_han_thu_100_143","chapterId":"ch_work_han_thu_100","textTraditional":"〔一０〕師古曰：「言宮室曠大，自然有紅翠之氣。」","sentenceOrder":143},
  {"id":"s_work_han_thu_100_144","chapterId":"ch_work_han_thu_100","textTraditional":"〔一一〕服虔曰：「襲，繼也。桀作琁室，紂作傾宮，以此微諫也。」應劭曰：「登高遠望，當以亡國為戒，若臨深淵也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_100_145","chapterId":"ch_work_han_thu_100","textTraditional":"回猋肆其碭駭兮，翍桂椒，鬱栘楊。〔一〕香芬茀以窮隆兮，擊薄櫨而將榮。〔二〕薌呹肸以掍根兮，聲駍隱而歷鍾，〔三〕排玉戶而颺金鋪兮，發蘭惠與穹窮。〔四〕惟弸彋其拂汨兮，稍暗暗而靚深。〔五〕陰陽清濁穆羽相和兮，若夔、牙之調琴。〔六〕般、倕棄其剞劂兮，王爾投其鉤繩。〔七〕雖方征僑與偓佺兮，猶仿佛其若夢。〔八〕","sentenceOrder":145},
  {"id":"s_work_han_thu_100_146","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「回猋，回風也。肆，放也。碭，過也。駭，動也。翍，古披字。鬱，聚也。栘，唐棣也。楊，楊樹也。言回風放起，過動眾樹，則桂椒披散而栘楊鬱聚也。碭音徒浪反。栘音移。」","sentenceOrder":146},
  {"id":"s_work_han_thu_100_147","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「言桂椒香氣乃擊薄櫨及屋翼也。薄，枅也。櫨音盧。」","sentenceOrder":147},
  {"id":"s_work_han_thu_100_148","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「又言風之動樹，聲響振起眾根合，駍隱而盛，歷入殿上之鍾也。根猶株也。薌讀與響同。呹音丑乙反。肸音許乙反。掍音下本反。駍音普耕反。」","sentenceOrder":148},
  {"id":"s_work_han_thu_100_149","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　李奇曰：「鋪，門首也。」師古曰：「言風之所至，又排門揚鋪，擊動鍰鈕，回旋入宮，發奮眾芳。」","sentenceOrder":149},
  {"id":"s_work_han_thu_100_150","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　蘇林曰：「弸音石墮井弸爾之弸。彋音宏。」孟康曰：「弸彋，風吹帷帳鼓貌。」師古曰：「拂汨亦風動貌。暗暗，幽隱。靚即靜字耳。弸音普萌反。拂音普密反。汨音于密反。暗音烏感反。」","sentenceOrder":150},
  {"id":"s_work_han_thu_100_151","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　張晏曰：「聲細不過羽，穆然相和也。」師古曰：「夔，舜典樂也。牙，伯牙也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_100_152","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　應劭曰：「剞，曲刃也。劂，曲鑿也。」師古曰：「般，公輸般也。倕，共工也。王爾亦巧人也，見淮南子。言土木之功窮極巧麗，故令般、倕之徒棄其常法也。般讀與班同。倕音垂。剞音居爾反。劂音居衛反。」","sentenceOrder":152},
  {"id":"s_work_han_thu_100_153","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　晉灼曰：「方，常也。征，行也。言宮觀之高峻，雖使仙人常行其上，恐遽不識其形觀，猶仿佛若夢也。」師古曰：「方謂並行也。征僑，姓征名伯僑，仙人也。偓佺亦仙人名。偓音屋。佺音詮。仿佛即髣彿字也。征，郊祀志作正字，其音同。」","sentenceOrder":153},
  {"id":"s_work_han_thu_100_154","chapterId":"ch_work_han_thu_100","textTraditional":"於是事變物化，目駭耳回，〔一〕蓋天子穆然珍臺閒館琁題玉英蜵蜎蠖濩之中，〔二〕惟夫所以澄心清魂，儲精垂思，〔三〕感動天地，逆釐三神者。〔四〕乃搜逑索耦皋、伊之徒，冠倫魁能〔五〕，函甘棠之惠，挾東征之意，〔六〕相與齊虖陽靈之宮。〔七〕靡薜荔而為席兮，折瓊枝以為芳，〔八〕噏清雲之流瑕兮，飲若木之露英，〔九〕集虖禮神之囿，登乎頌祇之堂。〔一０〕建光燿之長旓兮，昭華覆之威威，〔一一〕攀琁璣而下視兮，行遊目虖三危，陳眾車（所）〔於〕東阬兮，肆玉釱而下馳，漂龍淵而還九垠兮，窺地底而上回。〔一二〕風傱傱而扶轄兮，鸞鳳紛其御蕤，〔一三〕梁弱水之濎濴兮，躡不周之逶蛇，〔一四〕想西王母欣然而上壽兮，屏玉女而卻虙妃。〔一五〕玉女無所眺其清盧兮，虙妃曾不得施其蛾眉。〔一六〕方攬道德之精剛兮，（眸）〔侔〕神明與之為資。〔一七〕","sentenceOrder":154},
  {"id":"s_work_han_thu_100_155","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「言驚視聽也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_100_156","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　應劭曰：「題，頭也。榱椽之頭，皆以玉飾，言其英華相燭也。」張晏曰：「蜵蜎蠖濩，刻鏤之形。」師古曰：「穆然，天子之容也。蜵蜎蠖濩，言屋中之深廣也。閒讀曰閑。蜵音一兗反。蜎音下兗反。蠖音烏郭反。濩音胡郭反。」","sentenceOrder":156},
  {"id":"s_work_han_thu_100_157","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「言絜精以待，冀神降福。」","sentenceOrder":157},
  {"id":"s_work_han_thu_100_158","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　師古曰：「釐讀曰禧。禧，福也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_100_159","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　應劭曰：「冠其群倫魁桀也。」師古曰：「言選擇賢臣，可匹耦於古賢皋陶、伊尹之類，冠等倫而魁桀。」","sentenceOrder":159},
  {"id":"s_work_han_thu_100_160","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　師古曰：「甘棠之惠，邵公奭也。東征之意，周公旦也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_100_161","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　師古曰：「齊，同也，同集於此也。祭天之處，故曰陽靈之宮也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_100_162","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　師古曰：「靡，纖密也，謂纖織之也。一曰靡謂偃而靡之藉地也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_100_163","chapterId":"ch_work_han_thu_100","textTraditional":"〔九〕　師古曰：「言其齋戒自新，居處飲食皆芳絜也。瑕謂日旁赤氣也。露英，言其英華之露。」","sentenceOrder":163},
  {"id":"s_work_han_thu_100_164","chapterId":"ch_work_han_thu_100","textTraditional":"〔一０〕師古曰：「頌，歌也，登以祭也。地神曰祇。」","sentenceOrder":164},
  {"id":"s_work_han_thu_100_165","chapterId":"ch_work_han_thu_100","textTraditional":"〔一一〕服虔曰：「昭，明也。華覆，華蓋也。」師古曰：「威威猶威蕤也。旓，旗之旒也，一曰燕尾。旓音所交反。」","sentenceOrder":165},
  {"id":"s_work_han_thu_100_166","chapterId":"ch_work_han_thu_100","textTraditional":"〔一二〕張晏曰：「三危，山名也。」晉灼曰：「釱，車轄也。九垠，九垓也。」師古曰：「假設言周流曠遠，升降天地，為神通一也。肆，放也。阬，大阜也，讀與岡同。釱音大，又音弟。還讀曰旋。」","sentenceOrder":166},
  {"id":"s_work_han_thu_100_167","chapterId":"ch_work_han_thu_100","textTraditional":"〔一三〕師古曰：「傱傱，前進之意也。御猶乘也。蕤，車之垂飾纓蕤也。傱音竦。今書御字或作銜者，俗妄改也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_100_168","chapterId":"ch_work_han_thu_100","textTraditional":"〔一四〕服虔曰：「昆侖之東有弱水，度之若濎濴耳。」師古曰：「濎濴，小水之貌。不周，山名。逶蛇亦言不艱難也。濎音吐定反。濴音熒。又音胡鎣反。蛇音移。」","sentenceOrder":168},
  {"id":"s_work_han_thu_100_169","chapterId":"ch_work_han_thu_100","textTraditional":"〔一五〕師古曰：「西王母在西方，周穆王所見者也。玉女、虙妃，皆神女也。虙讀曰伏。」","sentenceOrder":169},
  {"id":"s_work_han_thu_100_170","chapterId":"ch_work_han_thu_100","textTraditional":"〔一六〕服虔曰：「盧，目童子也。」","sentenceOrder":170},
  {"id":"s_work_han_thu_100_171","chapterId":"ch_work_han_thu_100","textTraditional":"〔一七〕晉灼曰：「等天地之忖量也。」師古曰：「攬，總也，音覽，其字從手。」","sentenceOrder":171},
  {"id":"s_work_han_thu_100_172","chapterId":"ch_work_han_thu_100","textTraditional":"於是欽祡宗祈。燎熏皇天，〔一〕招繇泰壹。舉洪頤，樹靈旗。〔二〕樵蒸焜上，配藜四施，〔三〕東燭倉海，西燿流沙，北爌幽都，南煬丹厓。〔四〕玄瓚觩〈角翏〉，秬鬯泔淡，〔五〕肸嚮豐融，懿懿芬芬。〔六〕炎感黃龍兮，熛訛碩麟，〔七〕選巫咸兮叫帝閽，開天庭兮延群神。〔八〕儐暗藹兮降清壇，瑞穰穰兮委如山。〔九〕","sentenceOrder":172},
  {"id":"s_work_han_thu_100_173","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「欽，敬也。祡，積祡也。宗，尊也。祈，求福也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_100_174","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　張晏曰：「招搖、泰壹，皆神名也。」服虔曰：「洪頤，旗名也。」李奇曰：「欲伐南越，告祈太一，畫旗樹太一壇上，名靈旗，以指所伐之國也。見郊祀志。」","sentenceOrder":174},
  {"id":"s_work_han_thu_100_175","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　張晏曰：「配藜，披離也。」師古曰：「樵，木薪也。蒸，麻幹也。焜，同也。言以樵及蒸燎火，炎上於天，又披離四出。」","sentenceOrder":175},
  {"id":"s_work_han_thu_100_176","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　服虔曰：「丹厓，丹水之厓也。」師古曰：「爌，古晃字。煬，熱也。言祡燎之光遠及四表也。煬音弋向反。」","sentenceOrder":176},
  {"id":"s_work_han_thu_100_177","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　服虔曰：「以玄玉飾之，故曰玄瓚。」張晏曰：「瓚受五升，口徑八寸，以圭為柄，用灌鬯。觩〈角翏〉，其貌也。」應劭曰：「泔淡，滿也。」師古曰：「觩音虯。〈角翏〉音力幽反。泔音胡感反。淡音大敢反。」","sentenceOrder":177},
  {"id":"s_work_han_thu_100_178","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　師古曰：「言秬鬯之芬烈也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_100_179","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　師古曰：「言光炎熛盛，感神物也，訛，化也。碩，大也。熛音必遙反。」","sentenceOrder":179},
  {"id":"s_work_han_thu_100_180","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　服虔曰：「令巫祝叫呼天門也。」師古曰：「巫咸，古神巫之名。」","sentenceOrder":180},
  {"id":"s_work_han_thu_100_181","chapterId":"ch_work_han_thu_100","textTraditional":"〔九〕　張晏曰：「儐，贊也。」師古曰：「暗藹，神之形影也。穰穰，多也。委，積也。暗音烏感反。」","sentenceOrder":181},
  {"id":"s_work_han_thu_100_182","chapterId":"ch_work_han_thu_100","textTraditional":"於是事畢功弘，回車而歸，度三巒兮偈棠棃。〔一〕天閫決兮地垠開，八荒協兮萬國諧。〔二〕登長平兮雷鼓磕，天聲起兮勇士厲，〔三〕雲飛揚兮雨滂沛，于胥德兮麗萬世。〔四〕","sentenceOrder":182},
  {"id":"s_work_han_thu_100_183","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「三巒即封巒，觀名也。棠梨，宮名。偈讀曰憩。」","sentenceOrder":183},
  {"id":"s_work_han_thu_100_184","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「天閫，天門之閫也。決亦開也。言德澤普洽無極限也。」","sentenceOrder":184},
  {"id":"s_work_han_thu_100_185","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「長平，涇水上阪名也。磕，擊鼓聲也。天聲，聲至天也。聲字或作嚴，言擊嚴鼓也。厲，奮也。」","sentenceOrder":185},
  {"id":"s_work_han_thu_100_186","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　師古曰：「于，曰也。胥，皆也。麗，美也。沛音普大反。」","sentenceOrder":186},
  {"id":"s_work_han_thu_100_187","chapterId":"ch_work_han_thu_100","textTraditional":"亂曰：〔一〕崇崇圜丘，隆隱天兮，〔二〕登降峛崺，單埢垣兮。〔三〕增宮嵾差，駢嵯峨兮，〔四〕岭巆嶙峋，洞亡厓兮〔五〕。上天之縡，杳旭卉兮，〔六〕聖皇穆穆，信厥對兮。〔七〕來祗郊禋，神所依兮，〔八〕俳佪招搖，靈屖遲兮。〔九〕煇光眩燿，隆厥福兮，〔一０〕子子孫孫，長亡極兮。","sentenceOrder":187},
  {"id":"s_work_han_thu_100_188","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「亂者，理也，總理一賦之終也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_100_189","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「言其高。」","sentenceOrder":189},
  {"id":"s_work_han_thu_100_190","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「峛崺，上下之道也。單，周也。埢垣，圜貌也。峛音力爾反。崺音弋爾反。單音蟬。埢音拳。」","sentenceOrder":190},
  {"id":"s_work_han_thu_100_191","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　師古曰：「增，重也。嵾差，不齊也。駢，並也。嵾音初林反。駢音步千反。嵯音材何反。峨音娥。」","sentenceOrder":191},
  {"id":"s_work_han_thu_100_192","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　師古曰：「岭巆，深邃貌。嶙峋，節級貌。岭音零。巆音營。嶙音鄰。峋音荀。」","sentenceOrder":192},
  {"id":"s_work_han_thu_100_193","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　師古曰：「縡，事也。杳，高遠也。旭卉，疾速也。縡讀與載同。」","sentenceOrder":193},
  {"id":"s_work_han_thu_100_194","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　李奇曰：「對，配也。能與天地相配也。詩云『帝作邦作對。』」師古曰：「穆穆，美也。信，實也。」","sentenceOrder":194},
  {"id":"s_work_han_thu_100_195","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　師古曰：「言以祗敬而來郊祭禋饗，則神祇依附。」","sentenceOrder":195},
  {"id":"s_work_han_thu_100_196","chapterId":"ch_work_han_thu_100","textTraditional":"〔九〕　師古曰：「言神久留安處，不即去也。招音上遙反。屖音栖。遲音（又）〔丈〕夷反。」","sentenceOrder":196},
  {"id":"s_work_han_thu_100_197","chapterId":"ch_work_han_thu_100","textTraditional":"〔一０〕師古曰：「眩音州縣之縣。」","sentenceOrder":197},
  {"id":"s_work_han_thu_100_198","chapterId":"ch_work_han_thu_100","textTraditional":"甘泉本因秦離宮，既奢泰，〔一〕而武帝復增通天、高光、迎風。宮外近則洪厓、旁皇、儲胥、弩阹，遠則石關、封巒、枝鵲、露寒、棠梨、師得，遊觀屈奇瑰瑋，〔二〕非木摩而不彫，牆塗而不畫，周宣所考，般庚所遷，夏卑宮室，唐虞棌椽三等之制也。〔三〕且為其已久矣，非成帝所造，欲諫則非時，欲默則不能已，故遂推而隆之，乃上比於帝室紫宮，〔四〕若曰此非人力之所（能）〔為〕，黨鬼神可也。〔五〕又是時趙昭儀方大幸，每上甘泉，常法從，〔六〕在屬車間豹尾中。〔七〕故雄聊盛言車騎之眾，參麗之駕，非所以感動天地，逆釐三神。〔八〕又言「屏玉女，卻虙妃」，以微戒齊肅之事。賦成奏之，天子異焉。","sentenceOrder":198},
  {"id":"s_work_han_thu_100_199","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「本秦之林光宮也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_100_200","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「棠梨宮在甘泉苑垣外，師得宮在櫟陽界，其餘皆甘泉苑垣內之宮觀也。阹音袪。」","sentenceOrder":200},
  {"id":"s_work_han_thu_100_201","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「小雅斯干之詩序曰：『宣王考室也。』考謂成也。般庚，殷王名也。遷謂遷都亳也。唐虞謂堯舜也。棌，柞木也。三等，土階三等，言不過也。棌音采，又音菜，其字從木。」","sentenceOrder":201},
  {"id":"s_work_han_thu_100_202","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　師古曰：「帝謂天也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_100_203","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　師古曰：「黨音它莽反。」","sentenceOrder":203},
  {"id":"s_work_han_thu_100_204","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　師古曰：「法從者，以言法當從耳，非失禮也。一曰從法駕也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_100_205","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　服虔曰：「大駕屬車八十一乘，作三行，尚書御史乘之。最後一乘縣豹尾，豹尾以前皆為省中。」","sentenceOrder":205},
  {"id":"s_work_han_thu_100_206","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　師古曰：「參，三神也。麗，偶也。」","sentenceOrder":206},
  {"id":"s_work_han_thu_100_207","chapterId":"ch_work_han_thu_100","textTraditional":"其三月，將祭后土，上乃帥群臣橫大河，湊汾陰。〔一〕既祭，行遊介山，回安邑，〔二〕顧龍門，覽鹽池，〔三〕登歷觀，〔四〕陟西岳以望八荒，跡殷周之虛，眇然以思唐虞之風。〔五〕雄以為臨川羨魚不如歸而結罔，〔六〕還，上河東賦以勸，其辭曰：","sentenceOrder":207},
  {"id":"s_work_han_thu_100_208","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「橫，橫度之也。湊，趣也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_100_209","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「介山在汾陰東北。回謂遶過。」","sentenceOrder":209},
  {"id":"s_work_han_thu_100_210","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「龍門山在今蒲州龍門縣北。鹽池在今虞州安邑縣南。」","sentenceOrder":210},
  {"id":"s_work_han_thu_100_211","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　師古曰：「歷山上有觀也。」晉灼曰：「在河東蒲阪縣。」","sentenceOrder":211},
  {"id":"s_work_han_thu_100_212","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　師古曰：「陟，升也。西岳華山之上高峻，故言以望八荒。殷都河內，周在岐豐，堯都平陽，舜都蒲阪，皆可（相）〔想〕見，故云跡殷周之墟，思唐虞之風也。虛讀曰墟。」","sentenceOrder":212},
  {"id":"s_work_han_thu_100_213","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　師古曰：「言成帝追觀先代遺跡，思欲齊其德號，故雄勸令自興至治，以儗帝皇之風。」","sentenceOrder":213},
  {"id":"s_work_han_thu_100_214","chapterId":"ch_work_han_thu_100","textTraditional":"伊年暮春，將瘞后土，〔一〕禮靈祇，謁汾陰于東郊，〔二〕因茲以勒崇垂鴻，發祥隤祉，欽若神明者，盛哉鑠乎，越不可載已！〔三〕於是命群臣，齊法服，整靈輿，乃撫翠鳳之駕，六先景之乘，〔四〕掉奔星之流旃，彏天狼之威弧。〔五〕張燿日之玄旄，揚左纛，被雲梢。〔六〕奮電鞭，驂雷輜，〔七〕鳴洪鍾，建五旗。〔八〕（義）〔羲〕和司日，顏倫奉輿，〔九〕風發飆拂，神騰鬼趡〔一０〕；千乘霆亂，萬騎屈橋，〔一一〕嘻嘻旭旭，天地稠{山敖}。〔一二〕簸丘跳巒，涌渭躍涇。〔一三〕秦神下讋，跖魂負沴；〔一四〕河靈矍踢，掌華蹈衰。〔一五〕遂臻陰宮，穆穆肅肅，蹲蹲如也。〔一六〕","sentenceOrder":214},
  {"id":"s_work_han_thu_100_215","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「伊，是也，謂是祠甘泉之年也。祭地曰瘞薶，故曰瘞后土。瘞音乙例反。」","sentenceOrder":215},
  {"id":"s_work_han_thu_100_216","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「京師之東故曰東郊也。」","sentenceOrder":216},
  {"id":"s_work_han_thu_100_217","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「勒崇垂鴻，勒崇名而垂鴻業也。隤，降也。祉，福也。欽，敬也。若，順也。鑠，美也。越，曰也。已，辭也。言發祥降福，敬順神明，其事盛美，不可盡載。」","sentenceOrder":217},
  {"id":"s_work_han_thu_100_218","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　師古曰：「翠鳳之駕，天子所乘車，為鳳形而飾以翠羽也。先景，為馬行速疾，常在景前也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_100_219","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　晉灼曰：「有狼、弧之星也。」師古曰：「彏，急張也，音钁。」","sentenceOrder":219},
  {"id":"s_work_han_thu_100_220","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　張晏曰：「雲梢，梢雲也。」師古曰：「梢與旓同。旓者，旌旗之流，以雲為旓也。被音皮義反。」","sentenceOrder":220},
  {"id":"s_work_han_thu_100_221","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　師古曰：「輜，衣車也。淮南子云『電以為鞭策，雷以為車輪』，故雄用此言也。」","sentenceOrder":221},
  {"id":"s_work_han_thu_100_222","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　師古曰：「洪，大也。尚書大傳云『天子左右五鍾，天子將出則撞黃鍾之鍾，左五鍾皆應，入則撞蕤賓之鍾，右五鍾皆應。』漢舊儀云皇帝車駕建五旗。蓋謂五色之旗也，以木牛承其下，取其負重致遠。」","sentenceOrder":222},
  {"id":"s_work_han_thu_100_223","chapterId":"ch_work_han_thu_100","textTraditional":"〔九〕　師古曰：「倫，古善御者也。羲和，日御名。」","sentenceOrder":223},
  {"id":"s_work_han_thu_100_224","chapterId":"ch_work_han_thu_100","textTraditional":"〔一０〕師古曰：「飆，回風也。趡，走也。飆音必遙反。趡音子笑反，又音才笑反。」","sentenceOrder":224},
  {"id":"s_work_han_thu_100_225","chapterId":"ch_work_han_thu_100","textTraditional":"〔一一〕師古曰：「霆亂，言如雷霆之盛而亂動也。屈橋，（言）壯捷貌。屈音其勿反。橋音其召反。」","sentenceOrder":225},
  {"id":"s_work_han_thu_100_226","chapterId":"ch_work_han_thu_100","textTraditional":"〔一二〕服虔曰：「稠{山敖}，動搖貌。」師古曰：「嘻嘻旭旭，自得之貌。嘻音許其反。稠音徒弔反。{山敖}音五到反。」","sentenceOrder":226},
  {"id":"s_work_han_thu_100_227","chapterId":"ch_work_han_thu_100","textTraditional":"〔一三〕師古曰：「山小而銳曰巒。言車騎之威，訇隱之盛，至於涌躍涇、渭，跳簸丘山者也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_100_228","chapterId":"ch_work_han_thu_100","textTraditional":"〔一四〕蘇林曰：「秦文公時庭中有怪化為牛，走到南山梓樹中，伐梓樹，後化入豐水，文公惡之，故作其象以厭焉。今之茸頭是也，故曰秦神。」服虔曰：「沴，河岸之坻也。」晉灼曰：「沴，渚也。」師古曰：「跖，蹈也。言此神怖讋，下入水中自蹈其魂而負沴渚，蓋戚懼之甚也。跖音之亦反。坻音直尸反。」","sentenceOrder":228},
  {"id":"s_work_han_thu_100_229","chapterId":"ch_work_han_thu_100","textTraditional":"〔一五〕蘇林曰：「河靈，巨靈也。華，華山也。衰，衰山也。掌據之，足蹈之也。踢音試郎反。」服虔曰：「踢音石反。」師古曰：「矍踢，驚動之貌。矍音钁。踢音惕，二音並通。〈不，形似〉，古掌字。凡言此者，以車騎之眾，羽旄之盛，故秦神、河靈莫不恐懼而自放也。」","sentenceOrder":229},
  {"id":"s_work_han_thu_100_230","chapterId":"ch_work_han_thu_100","textTraditional":"〔一六〕師古曰：「陰宮，汾陰之宮也。穆穆，靜也。肅肅，敬也。蹲蹲，行有節也。蹲音千旬反。」","sentenceOrder":230},
  {"id":"s_work_han_thu_100_231","chapterId":"ch_work_han_thu_100","textTraditional":"靈祇既鄉，五位時敘，〔一〕絪縕玄黃，將紹厥後。〔二〕於是靈輿安步，周流容與，〔三〕以覽虖介山。嗟文公而愍推兮，勤大禹於龍門，〔四〕灑沈（葘）〔災〕於豁瀆兮，播九河於東瀕〔五〕。登歷觀而遙望兮，聊浮游以經營。樂往昔之遺風兮，喜虞氏之所耕。〔六〕瞰帝唐之嵩高兮，眽隆周之大寧。〔七〕汨低回而不能去兮，行睨陔下與彭城。〔八〕濊南巢之坎坷兮，易豳岐之夷平。〔九〕乘翠龍而超河兮，陟西岳之嶢崝。〔一０〕雲霏霏而來迎兮，澤滲灕而下降，〔一一〕鬱蕭條其幽藹兮，滃汎沛以豐隆。〔一二〕叱風伯於南北兮，呵雨師於西東，〔一三〕參天地而獨立兮，廓盪盪其亡雙。〔一四〕","sentenceOrder":231},
  {"id":"s_work_han_thu_100_232","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「鄉讀曰嚮。」服虔曰：「五位，五方之神。」","sentenceOrder":232},
  {"id":"s_work_han_thu_100_233","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「絪縕，天地合氣也。玄黃，天地色也。易下繫辭曰：『天地絪縕，萬物化淳。』坤文言曰：『玄黃者，天地之雜色也。天玄而地黃。』將，大也。言天地之氣大興發於祭祀之後。絪音因。縕音於云反。」","sentenceOrder":233},
  {"id":"s_work_han_thu_100_234","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「靈輿，天子之輿也。容暇而安豫也。與讀曰豫。」","sentenceOrder":234},
  {"id":"s_work_han_thu_100_235","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　師古曰：「龍門山，禹鑿之以通河水，故勤勞之。」","sentenceOrder":235},
  {"id":"s_work_han_thu_100_236","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　師古曰：「灑，分也。（葘）〔葘〕，古災字也。沈災，洪水也。豁，開也。瀆謂江、河、淮、濟也。播，布也。九河名在地理志。東瀕，東海之瀕也。禹分治洪水之災，通之四瀆，布散九河於東海之瀕也。灑音所宜反。瀕音頻，又音賓。」","sentenceOrder":236},
  {"id":"s_work_han_thu_100_237","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　師古曰：「舜耕歷山，故云然。」","sentenceOrder":237},
  {"id":"s_work_han_thu_100_238","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　師古曰：「瞰、眽，皆視也。帝唐，堯也。嵩亦高也。嵩高者，謂孔子云『巍巍乎唯天為大，唯堯則之』也。一曰：堯曾遊於陽城，故於嵩高山瞰其遺蹟也。大寧者，詩大雅云『濟濟多士，文王以寧』。瞰音苦濫反。眽即覓字。」","sentenceOrder":238},
  {"id":"s_work_han_thu_100_239","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　應劭曰：「睨，不正視也。彭城，項羽所都也。」晉灼曰：「陔下，項羽敗處也。」師古曰：「汨，往意也。低回猶言徘徊也。行，且也，意且欲往睹也。汨音于筆反。睨音五系反。」","sentenceOrder":239},
  {"id":"s_work_han_thu_100_240","chapterId":"ch_work_han_thu_100","textTraditional":"〔九〕　李奇曰：「南巢，桀敗處也。易，樂也。」師古曰：「濊與穢同。坎坷，不平貌。坎音口紺反。坷音口賀反。易音弋豉反。」","sentenceOrder":240},
  {"id":"s_work_han_thu_100_241","chapterId":"ch_work_han_thu_100","textTraditional":"〔一０〕師古曰：「翠龍，穆天子所乘馬也。西岳即華山也。嶢崝謂嶕嶢而崝嶸也。嶢音堯。崝音士耕反。」","sentenceOrder":241},
  {"id":"s_work_han_thu_100_242","chapterId":"ch_work_han_thu_100","textTraditional":"〔一一〕師古曰：「{雨飛}，古霏字。{雨飛}{雨飛}，雲起貌。澤，雨露也。滲灕，流貌也。降，下也。滲音淋。灕音離。降音湖江反。」","sentenceOrder":242},
  {"id":"s_work_han_thu_100_243","chapterId":"ch_work_han_thu_100","textTraditional":"〔一二〕師古曰：「皆雲雨之貌。滃音烏孔反。汎音敷劍反。沛音普蓋反。」","sentenceOrder":243},
  {"id":"s_work_han_thu_100_244","chapterId":"ch_work_han_thu_100","textTraditional":"〔一三〕師古曰：「言皆從命也。」","sentenceOrder":244},
  {"id":"s_work_han_thu_100_245","chapterId":"ch_work_han_thu_100","textTraditional":"〔一四〕師古曰：「天地曰二儀，王者大位，與之合德，故曰參天地。參之言三也。盪盪，大貌。」","sentenceOrder":245},
  {"id":"s_work_han_thu_100_246","chapterId":"ch_work_han_thu_100","textTraditional":"遵逝虖歸來，〔一〕以函夏之大漢兮，彼曾何足與比功〔二〕？建乾坤之貞兆兮，將悉總之以群龍。〔三〕麗鉤芒與驂蓐收兮，服玄冥及祝融。〔四〕敦眾神使式道兮，奮六經以攄頌。〔五〕隃於穆之緝熙兮，過清廟之雝雝；〔六〕軼五帝之遐跡兮，躡三皇之高蹤。〔七〕既發軔於平盈兮，誰謂路遠而不能從？〔八〕","sentenceOrder":246},
  {"id":"s_work_han_thu_100_247","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「遵路而旋京師也。」","sentenceOrder":247},
  {"id":"s_work_han_thu_100_248","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　服虔曰：「函夏，函諸夏也。」師古曰：「函，包容也。彼謂堯、舜、殷、周也。函讀與含同。」","sentenceOrder":248},
  {"id":"s_work_han_thu_100_249","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　張晏曰：「乾六爻悉稱龍也。」","sentenceOrder":249},
  {"id":"s_work_han_thu_100_250","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　師古曰：「鉤芒，東方神。蓐收，西方神。玄冥，北方神。祝融，南方神。麗，並駕也。驂，三馬也。言皆役服也。」","sentenceOrder":250},
  {"id":"s_work_han_thu_100_251","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　師古曰：「敦，勉也。式，表也。六經謂易、詩、書、春秋、禮、樂也。攄，散也。頌謂詩頌，所以美盛德之形容也，言發其志而為歌頌也。攄音丑於反。頌讀曰容。」","sentenceOrder":251},
  {"id":"s_work_han_thu_100_252","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　師古曰：「周頌清廟之詩云『於穆清廟，肅雍顯相』，昊天有成命之詩曰『於緝熙』，言漢德之盛，皆過之也。隃讀與踰同。於讀曰烏。」","sentenceOrder":252},
  {"id":"s_work_han_thu_100_253","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　師古曰：「軼亦過也，音逸。」","sentenceOrder":253},
  {"id":"s_work_han_thu_100_254","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　服虔曰：「軔，止車之木，將行，故發去。平盈之地無高下也。」師古曰：「軔音刃。」","sentenceOrder":254},
  {"id":"s_work_han_thu_100_255","chapterId":"ch_work_han_thu_100","textTraditional":"其十二月羽獵，〔一〕雄從。以為昔在二帝三王，〔二〕宮館臺榭沼池苑囿林麓藪澤財足以奉郊廟，御賓客，充庖廚而已，〔三〕不奪百姓膏腴穀土桑柘之地。女有餘布，男有餘粟，國家殷富，上下交足，故甘露零其庭，醴泉流其唐，〔四〕鳳皇巢其樹，黃龍游其沼，麒麟臻其囿，神爵棲其林。昔者禹任益虞而上下和，屮木茂；〔五〕成湯好田而天下用足；文王囿百里，民以為尚小；齊宣王囿四十里，民以為大：裕民之與奪民也。〔六〕武帝廣開上林，南至宜春、鼎胡、御宿、昆吾，〔七〕旁南山而西，至長楊、五柞，〔八〕北繞黃山，瀕渭而東，〔九〕周袤數百里。〔一０〕穿昆明象滇河，〔一一〕營建章、鳳闕、神明、馺娑，〔一二〕漸臺、泰液〔一三〕象海水周流方丈、瀛洲、蓬萊。〔一四〕游觀侈靡，窮妙極麗。雖頗割其三垂以贍齊民，〔一五〕然至羽獵田車戎馬器械儲偫禁禦所營，〔一六〕尚泰奢麗誇詡，〔一七〕非堯、舜、成湯、文王三驅之意也。〔一八〕又恐後世復修前好，不折中以泉臺，〔一九〕故聊因校獵賦以風，〔二０〕其辭曰：","sentenceOrder":255},
  {"id":"s_work_han_thu_100_256","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　服虔曰：「士負羽。」","sentenceOrder":256},
  {"id":"s_work_han_thu_100_257","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　應劭曰：「二帝，堯、舜。三王，夏、殷、周。」","sentenceOrder":257},
  {"id":"s_work_han_thu_100_258","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「財讀與纔同。御，侍也。充，當也。」","sentenceOrder":258},
  {"id":"s_work_han_thu_100_259","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　應劭曰：「爾雅『廟中路謂之唐』。」","sentenceOrder":259},
  {"id":"s_work_han_thu_100_260","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　師古曰：「益，臣名也，任以為虞。虞，主山澤之官也。上，山也。下，平地也。屮，古草字。」","sentenceOrder":260},
  {"id":"s_work_han_thu_100_261","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　師古曰：「裕，饒也。」","sentenceOrder":261},
  {"id":"s_work_han_thu_100_262","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　晉灼曰：「鼎胡，宮也，黃圖以為在藍田。昆吾，地名也，有亭。」師古曰：「宜春近下杜，御宿在樊川西也。」","sentenceOrder":262},
  {"id":"s_work_han_thu_100_263","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　師古曰：「旁音步浪反。」","sentenceOrder":263},
  {"id":"s_work_han_thu_100_264","chapterId":"ch_work_han_thu_100","textTraditional":"〔九〕　師古曰：「循渭水涯而東也。瀕音頻，又音賓。」","sentenceOrder":264},
  {"id":"s_work_han_thu_100_265","chapterId":"ch_work_han_thu_100","textTraditional":"〔一０〕師古曰：「袤，長也，音茂。」","sentenceOrder":265},
  {"id":"s_work_han_thu_100_266","chapterId":"ch_work_han_thu_100","textTraditional":"〔一一〕師古曰：「滇音丁賢反。」","sentenceOrder":266},
  {"id":"s_work_han_thu_100_267","chapterId":"ch_work_han_thu_100","textTraditional":"〔一二〕師古曰：「殿名也。（師古曰）馺音先合反。娑音先河反。」","sentenceOrder":267},
  {"id":"s_work_han_thu_100_268","chapterId":"ch_work_han_thu_100","textTraditional":"〔一三〕師古曰：「漸臺在泰液池中。漸，浸也，言為池水所浸也。」","sentenceOrder":268},
  {"id":"s_work_han_thu_100_269","chapterId":"ch_work_han_thu_100","textTraditional":"〔一四〕服虔曰：「海中三山名。法效象之。」","sentenceOrder":269},
  {"id":"s_work_han_thu_100_270","chapterId":"ch_work_han_thu_100","textTraditional":"〔一五〕師古曰：「贍，給也。齊人，解在食貨志。」","sentenceOrder":270},
  {"id":"s_work_han_thu_100_271","chapterId":"ch_work_han_thu_100","textTraditional":"〔一六〕師古曰：「營謂（園）〔圍〕守也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_100_272","chapterId":"ch_work_han_thu_100","textTraditional":"〔一七〕師古曰：「詡，大也，音許羽反。」","sentenceOrder":272},
  {"id":"s_work_han_thu_100_273","chapterId":"ch_work_han_thu_100","textTraditional":"〔一八〕師古曰：「三驅，古射獵之等也。一為籩豆，二為賓客，三為充君之庖也。」","sentenceOrder":273},
  {"id":"s_work_han_thu_100_274","chapterId":"ch_work_han_thu_100","textTraditional":"〔一九〕服虔曰：「魯莊公築泉臺，非禮也，至文公毀之，公羊譏云：『先祖為之而毀之，勿居而已。』今揚雄以宮觀之盛，非成帝所造，勿修而已，當以泉臺折中也。」","sentenceOrder":274},
  {"id":"s_work_han_thu_100_275","chapterId":"ch_work_han_thu_100","textTraditional":"〔二０〕師古曰：「校獵謂圍守禽獸而大獵也。風讀曰諷。」","sentenceOrder":275},
  {"id":"s_work_han_thu_100_276","chapterId":"ch_work_han_thu_100","textTraditional":"或稱戲農，豈或帝王之彌文哉？〔一〕論者云否，各亦並時而得宜，奚必同條而共貫？〔二〕則泰山之封，烏得七十而有二儀？〔三〕是以創業垂統者俱不見其爽，遐邇五三孰知其是非？〔四〕遂作頌曰：麗哉神聖，處於玄宮，富既與地虖侔訾，貴正與天虖比崇。〔五〕齊桓曾不足使扶轂，楚嚴未足以為驂乘；陿三王之阨薜，嶠高舉而大興；〔六〕歷五帝之寥廓，涉三皇之登閎；〔七〕建道德以為師，友仁義與為朋。","sentenceOrder":276},
  {"id":"s_work_han_thu_100_277","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「設或人云，言儉質者皆舉伏戲、神農為之首，是則豈謂後代帝王彌加文飾乎？故論者答之於下也。論者，雄自謂也。彌猶稍稍也。諸家之釋，皆不當意，徒為煩雜，故無所取。」","sentenceOrder":277},
  {"id":"s_work_han_thu_100_278","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「所尚不必同也。」","sentenceOrder":278},
  {"id":"s_work_han_thu_100_279","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　孟康曰：「言封禪各異也。」師古曰：「若不如是，於何得七十二儀也？」","sentenceOrder":279},
  {"id":"s_work_han_thu_100_280","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　師古曰：「爽，差也。創業垂統，皆無差忒。五帝三王，誰是誰非，言文質政教各不同也。」","sentenceOrder":280},
  {"id":"s_work_han_thu_100_281","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　師古曰：「頌漢德也。玄宮，言清淨也。訾與貲同。」","sentenceOrder":281},
  {"id":"s_work_han_thu_100_282","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　師古曰：「薜亦僻字也。嶠，舉步貌也，音去昭反。」","sentenceOrder":282},
  {"id":"s_work_han_thu_100_283","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　師古曰：「寥廓，空曠也。登閎，高遠也。寥音聊。」","sentenceOrder":283},
  {"id":"s_work_han_thu_100_284","chapterId":"ch_work_han_thu_100","textTraditional":"於是玄冬季月，天地隆烈，〔一〕萬物權輿於內，徂落於外，〔二〕帝將惟田于靈之囿，〔三〕開北垠，受不周之制，〔四〕以終始顓頊、玄冥之統。〔五〕乃詔虞人典澤，東延昆鄰，西馳闛闔。〔六〕儲積共偫，戍卒夾道，〔七〕斬叢棘，夷野草，〔八〕禦自汧、渭，經營酆、鎬，〔九〕章皇周流，出入日月，天與地杳。〔一０〕爾乃虎路三嵕以為司馬，圍經百里而為殿門。〔一一〕外則正南極海，邪界虞淵，〔一二〕鴻濛沆茫，碣以崇山。〔一三〕營合圍會，然后先置虖白楊之南，昆明靈沼之東。〔一四〕賁育之倫，蒙盾負羽，杖鏌邪而羅者以萬計，〔一五〕其餘荷垂天之畢，張竟野之罘，靡日月之朱竿，曳彗星之飛旗。〔一六〕青雲為紛，紅蜺為繯，屬之虖昆侖之虛，〔一七〕渙若天星之羅，浩如濤水之波，〔一八〕淫淫與與，前後要遮。〔一九〕欃槍為闉，明月為候，〔二０〕熒惑司命，天弧發射，〔二一〕鮮扁陸離，駢衍佖路。〔二二〕徽車輕武，鴻絧緁獵，〔二三〕殷殷軫軫，被陵緣阪，窮冥極遠者，相與迾虖高原之上；〔二四〕羽騎營營，昈分殊事，〔二五〕繽紛往來，轠轤不絕，若光若滅者，布虖青林之下。〔二六〕","sentenceOrder":284},
  {"id":"s_work_han_thu_100_285","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「北方色黑，故曰玄冬。隆烈者，陰氣盛。」","sentenceOrder":285},
  {"id":"s_work_han_thu_100_286","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「權輿，始也。徂落，死也。言草木萌牙始生於內，而枝葉凋毀死傷於外也。」","sentenceOrder":286},
  {"id":"s_work_han_thu_100_287","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「靈囿，有靈德之苑囿也。詩大雅靈臺之篇曰『王在靈囿』。」","sentenceOrder":287},
  {"id":"s_work_han_thu_100_288","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　孟康曰：「西北為不周風，謂冬時也。」師古曰：「垠，厓也，音銀。」","sentenceOrder":288},
  {"id":"s_work_han_thu_100_289","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　應劭曰：「顓頊、玄冥，皆北方之神，主殺戮也。」","sentenceOrder":289},
  {"id":"s_work_han_thu_100_290","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　張晏曰：「東至昆明之邊也。」師古曰：「昆明池邊也。闛闔，門名也。闛讀與閶同也，又音吐郎反。」","sentenceOrder":290},
  {"id":"s_work_han_thu_100_291","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　師古曰：「共讀曰供。偫音丈紀反。」","sentenceOrder":291},
  {"id":"s_work_han_thu_100_292","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　師古曰：「夷，平也。」","sentenceOrder":292},
  {"id":"s_work_han_thu_100_293","chapterId":"ch_work_han_thu_100","textTraditional":"〔九〕　應劭曰：「禦，禁也。」師古曰：「將獵其中，故止禁不得人行及獸出也。汧、渭以東，酆、鎬以西，皆為獵圍也。」","sentenceOrder":293},
  {"id":"s_work_han_thu_100_294","chapterId":"ch_work_han_thu_100","textTraditional":"〔一０〕師古曰：「章皇周流，言匝遍也，謂苑囿之大，遙望日月皆從中出入，而天地之際杳然縣遠也。說者反以杳為沓，解云重沓，非唯乖理，蓋以失韻。」","sentenceOrder":294},
  {"id":"s_work_han_thu_100_295","chapterId":"ch_work_han_thu_100","textTraditional":"〔一一〕晉灼曰：「路音落。」服虔曰：「以竹虎落此山也。」應劭曰：「外門為司馬門，殿門在內也。」師古曰：「落，纍也，以繩周繞之也。三嵕，三峰聚之山也。嵕音子公反。」","sentenceOrder":295},
  {"id":"s_work_han_thu_100_296","chapterId":"ch_work_han_thu_100","textTraditional":"〔一二〕應劭曰：「虞淵，日所入。」","sentenceOrder":296},
  {"id":"s_work_han_thu_100_297","chapterId":"ch_work_han_thu_100","textTraditional":"〔一三〕師古曰：「鴻濛沆茫，廣大貌。碣，山特立貌。鴻音胡孔反。濛音莫孔反。沆音胡浪反。茫音莽。碣音竭。」","sentenceOrder":297},
  {"id":"s_work_han_thu_100_298","chapterId":"ch_work_han_thu_100","textTraditional":"〔一四〕張晏曰：「先置供具於前。」服虔曰：「白楊，觀名。」","sentenceOrder":298},
  {"id":"s_work_han_thu_100_299","chapterId":"ch_work_han_thu_100","textTraditional":"〔一五〕師古曰：「賁，孟賁也。育，夏育也。皆古之勇士也。鏌邪，大戟也。羅，列遮禽獸。鏌音莫。邪音弋奢反。」","sentenceOrder":299},
  {"id":"s_work_han_thu_100_300","chapterId":"ch_work_han_thu_100","textTraditional":"〔一六〕如淳曰：「垂天，言長大如天之垂也。」師古曰：「畢，田罔也。罘，幡車罔也。」","sentenceOrder":300},
  {"id":"s_work_han_thu_100_301","chapterId":"ch_work_han_thu_100","textTraditional":"〔一七〕師古曰：「紛，眊也。繯，系也。屬，綴也。昆侖，西極之山也。繯音下犬反。屬音之欲反。虛讀曰墟。」","sentenceOrder":301},
  {"id":"s_work_han_thu_100_302","chapterId":"ch_work_han_thu_100","textTraditional":"〔一八〕師古曰：「天星之羅，言布列也。濤水之波，言廣大。」","sentenceOrder":302},
  {"id":"s_work_han_thu_100_303","chapterId":"ch_work_han_thu_100","textTraditional":"〔一九〕師古曰：「淫淫與與，往來貌。」","sentenceOrder":303},
  {"id":"s_work_han_thu_100_304","chapterId":"ch_work_han_thu_100","textTraditional":"〔二０〕孟康曰：「闉，鬥戰自障蔽，如城門外女垣也。」","sentenceOrder":304},
  {"id":"s_work_han_thu_100_305","chapterId":"ch_work_han_thu_100","textTraditional":"〔二一〕張晏曰：「熒惑，法使，司不祥。天弧，虛、危上二星也。」","sentenceOrder":305},
  {"id":"s_work_han_thu_100_306","chapterId":"ch_work_han_thu_100","textTraditional":"〔二二〕師古曰：「鮮扁，輕疾貌。駢衍，言其並廣大也。佖，次比也，一曰滿也。扁音篇。駢音步千反。佖音頻一反。又音步結反。」","sentenceOrder":306},
  {"id":"s_work_han_thu_100_307","chapterId":"ch_work_han_thu_100","textTraditional":"〔二三〕師古曰：「徽車，有徽（熾）〔幟〕之車也。鴻絧，直馳貌。緁獵，相差次也。鴻音胡孔反。絧音徒孔反。緁音捷。」","sentenceOrder":307},
  {"id":"s_work_han_thu_100_308","chapterId":"ch_work_han_thu_100","textTraditional":"〔二四〕師古曰：「殷軫，盛也。冥，幽深也。殷讀曰隱。」","sentenceOrder":308},
  {"id":"s_work_han_thu_100_309","chapterId":"ch_work_han_thu_100","textTraditional":"〔二五〕蘇林曰：「昈，明也。」師古曰：「營營，周旋貌也。言其服飾分明，各殊異也。昈音戶。」","sentenceOrder":309},
  {"id":"s_work_han_thu_100_310","chapterId":"ch_work_han_thu_100","textTraditional":"〔二六〕孟康曰：「轠轤，連屬貌。」如淳曰：「轠音雷。轤音盧。」師古曰：「繽紛，眾疾也。轠轤，環轉也。繽音匹人反。」","sentenceOrder":310},
  {"id":"s_work_han_thu_100_311","chapterId":"ch_work_han_thu_100","textTraditional":"於是天子乃以陽晁始出虖玄宮，〔一〕撞鴻鍾，建九（流）〔旒〕，六白虎，載靈輿，蚩尤並轂，蒙公先驅。〔二〕立歷天之旂，曳捎星之旃，〔三〕辟歷列缺，吐火施鞭。〔四〕萃傱允溶，淋離廓落，戲八鎮而開關；〔五〕飛廉、雲師，吸嚊潚率，鱗羅布列，攢以龍翰。〔六〕秋秋蹌蹌，入西園，切神光；〔七〕望平樂，徑竹林，〔八〕蹂惠圃，踐蘭唐。〔九〕舉烽烈火，轡者施披，〔一０〕方馳千駟，校騎萬師。〔一一〕虓虎之陳，從橫膠輵，猋泣雷厲，驞駍駖磕，〔一二〕洶洶旭旭，天動地岋。〔一三〕羨漫半散，蕭條數千萬里外。〔一四〕","sentenceOrder":311},
  {"id":"s_work_han_thu_100_312","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「陽朝，日出之後也。北方之宮，故曰玄宮。」","sentenceOrder":312},
  {"id":"s_work_han_thu_100_313","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　服虔曰：「蒙公，蒙恬也。」孟康曰：「神名也。」師古曰：「服說是也。並音步浪反。」","sentenceOrder":313},
  {"id":"s_work_han_thu_100_314","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「歷，經也。捎猶拂也。歷天捎雲，言其高也。捎音所交反。」","sentenceOrder":314},
  {"id":"s_work_han_thu_100_315","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　應劭曰：「辟歷，雷也。列缺，天隙電照也。」師古曰：「言獵火之燿，及馳騎奮鞭，如電吐光，及象其疾。」","sentenceOrder":315},
  {"id":"s_work_han_thu_100_316","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　應劭曰：「四方四隅為八鎮。」如淳曰：「不言九者，一鎮在中，天子居之故也。」師古曰：「戲讀曰麾，謂指麾八鎮使之開關也。傱音先勇反，又音叢。溶音容。」","sentenceOrder":316},
  {"id":"s_work_han_thu_100_317","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　師古曰：「吸嚊，開張也。潚率，聚斂也。言布列則如魚鱗之羅，攢聚則如龍之豪翰。嚊音許冀反。潚音肅。翰合韻音韓。」","sentenceOrder":317},
  {"id":"s_work_han_thu_100_318","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　師古曰：「秋秋蹌蹌，騰驤之貌。切神光者，言車之眾（飭）〔飾〕相切靡而光起，有若神也。蹌音千羊反。」","sentenceOrder":318},
  {"id":"s_work_han_thu_100_319","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　張晏曰：「平樂，館名也。」晉灼曰：「在上林中。」","sentenceOrder":319},
  {"id":"s_work_han_thu_100_320","chapterId":"ch_work_han_thu_100","textTraditional":"〔九〕　師古曰：「惠圃，惠草之圃也。蘭唐，陂唐之上多生蘭也。」","sentenceOrder":320},
  {"id":"s_work_han_thu_100_321","chapterId":"ch_work_han_thu_100","textTraditional":"〔一０〕師古曰：「轡者，御人執轡也。」","sentenceOrder":321},
  {"id":"s_work_han_thu_100_322","chapterId":"ch_work_han_thu_100","textTraditional":"〔一一〕師古曰：「方馳，並驅也。校騎，騎而為部校者也。」","sentenceOrder":322},
  {"id":"s_work_han_thu_100_323","chapterId":"ch_work_han_thu_100","textTraditional":"〔一二〕服虔曰：「虓音哮。」鄧展曰：「泣音粒。」師古曰：「哮虎之陳，謂勇士奮怒，狀如猛獸而為行陳也。泣，猋風疾貌也。驞駍駖磕，皆聲響眾盛也。哮音火交反。輵音葛。驞音匹人反。駍音普萌反。駖音力莖反。磕音口盍反。」","sentenceOrder":323},
  {"id":"s_work_han_thu_100_324","chapterId":"ch_work_han_thu_100","textTraditional":"〔一三〕蘇林曰：「岋音岋岋動搖之岋。」師古曰：「洶音匈。岋音五合反。」","sentenceOrder":324},
  {"id":"s_work_han_thu_100_325","chapterId":"ch_work_han_thu_100","textTraditional":"〔一四〕師古曰：「羨音弋戰反。」","sentenceOrder":325},
  {"id":"s_work_han_thu_100_326","chapterId":"ch_work_han_thu_100","textTraditional":"若夫壯士慷慨，殊鄉別趣，〔一〕東西南北，騁耆奔欲〔二〕。拕蒼豨，跋犀犛，蹶浮麋。〔三〕斮巨狿，搏玄蝯，〔四〕騰空虛，距連卷。〔五〕踔夭蟜，娭澗門，〔六〕莫莫紛紛，山谷為之風猋，林叢為之生塵。〔七〕及至獲夷之徒，蹶松柏，掌疾梨；〔八〕獵蒙蘢，轔輕飛；〔九〕履般首，帶修蛇；〔一０〕鉤赤豹，摼象犀；〔一一〕跇巒阬，超唐陂。〔一二〕車騎雲會，登降闇藹，〔一三〕泰華為旒，熊耳為綴。〔一四〕木仆山還，漫若天外，〔一五〕儲與虖大溥，聊浪虖宇內。〔一六〕","sentenceOrder":326},
  {"id":"s_work_han_thu_100_327","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":327},
  {"id":"s_work_han_thu_100_328","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「言隨其所欲而各馳騁取之也。耆讀曰嗜。欲，合韻音弋樹反。」","sentenceOrder":328},
  {"id":"s_work_han_thu_100_329","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　張晏曰：「跋，躡也。」鄭氏曰：「蹶音馬蹄蹶之蹶。」師古曰：「拕，曳也。跋，反戾也。蹶，蹴也。浮麋，水上浮者也。拕音佗。跋音步末反。」","sentenceOrder":329},
  {"id":"s_work_han_thu_100_330","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　師古曰：「斮，斬也。狿，獸名也。解在司馬相如傳。斮音側略反。」","sentenceOrder":330},
  {"id":"s_work_han_thu_100_331","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　張晏曰：「連卷之木也。」師古曰：「距即拒字也。卷音拳。」","sentenceOrder":331},
  {"id":"s_work_han_thu_100_332","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　師古曰：「踔，走也。夭蟜亦木枝曲也。娭，戲也。踔音丑孝反，又音徒釣反。蟜音矯。娭音許其反。」","sentenceOrder":332},
  {"id":"s_work_han_thu_100_333","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　師古曰：「莫莫，塵埃貌。紛紛，亂起貌。」","sentenceOrder":333},
  {"id":"s_work_han_thu_100_334","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　服虔曰：「獲夷，能獲夷狄者也。」師古曰：「掌，以掌擊也。」","sentenceOrder":334},
  {"id":"s_work_han_thu_100_335","chapterId":"ch_work_han_thu_100","textTraditional":"〔九〕　師古曰：「蒙蘢，草木所蒙蔽處也。轔，轢也。輕飛猶言輕禽也。轔音吝。」","sentenceOrder":335},
  {"id":"s_work_han_thu_100_336","chapterId":"ch_work_han_thu_100","textTraditional":"〔一０〕如淳曰：「般音班。班首，虎之類也。」師古曰：「履謂踐履之也。修，長也。」","sentenceOrder":336},
  {"id":"s_work_han_thu_100_337","chapterId":"ch_work_han_thu_100","textTraditional":"〔一一〕師古曰：「摼，古牽字。」","sentenceOrder":337},
  {"id":"s_work_han_thu_100_338","chapterId":"ch_work_han_thu_100","textTraditional":"〔一二〕師古曰：「跇，渡也。巒阬，並解於上。唐陂，陂之有隄唐者也。阬音剛。跇音弋制反。」","sentenceOrder":338},
  {"id":"s_work_han_thu_100_339","chapterId":"ch_work_han_thu_100","textTraditional":"〔一三〕師古曰：「闇音烏感反。」","sentenceOrder":339},
  {"id":"s_work_han_thu_100_340","chapterId":"ch_work_han_thu_100","textTraditional":"〔一四〕師古曰：「旒，旌旗之旒也。綴，所以縣旌也。」","sentenceOrder":340},
  {"id":"s_work_han_thu_100_341","chapterId":"ch_work_han_thu_100","textTraditional":"〔一五〕如淳曰：「還音旋。言山為之回旋也。」","sentenceOrder":341},
  {"id":"s_work_han_thu_100_342","chapterId":"ch_work_han_thu_100","textTraditional":"〔一六〕服虔曰：「儲與，相羊也。溥，水厓也。」師古曰：「聊浪，言游放也。與音餘。溥音普，浪音琅。」","sentenceOrder":342},
  {"id":"s_work_han_thu_100_343","chapterId":"ch_work_han_thu_100","textTraditional":"於是天清日晏，〔一〕逢蒙列眥，羿氏控弦。〔二〕皇車幽輵，光純天地，〔三〕望舒彌轡，〔四〕翼乎徐至於上蘭。〔五〕移圍徙陳，浸淫蹴部，〔六〕曲隊堅重，各按行伍。〔七〕壁壘天旋，神抶電擊，〔八〕逢之則碎，近之則破，鳥不及飛，獸不得過，軍驚師駭，刮野埽地。〔九〕及至罕車飛揚，武騎聿皇；〔一０〕蹈飛豹，絹嘄陽；〔一一〕追天寶，出一方；〔一二〕應駍聲，擊流光。野盡山窮，囊括其雌雄，〔一三〕沈沈容容，遙噱虖紘中。〔一四〕三軍芒然，窮冘閼與，〔一五〕亶觀夫票禽之紲隃，犀兕之抵觸，熊羆之挐攫，虎豹之凌遽，〔一六〕徒角搶題注，蹙竦讋怖，魂亡魄失，觸輻關脰。〔一七〕妄發期中，進退履獲，〔一八〕創淫輪夷，丘累陵聚。〔一九〕","sentenceOrder":343},
  {"id":"s_work_han_thu_100_344","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「晏，無雲也。」","sentenceOrder":344},
  {"id":"s_work_han_thu_100_345","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「逢蒙及羿，皆古善射者。列，整也。控，引也。」","sentenceOrder":345},
  {"id":"s_work_han_thu_100_346","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　李奇曰：「純，緣也。」師古曰：「幽輵，車聲也。輵音一轄反。純音之允反。」","sentenceOrder":346},
  {"id":"s_work_han_thu_100_347","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　師古曰：「望舒，月御也。彌，斂也。言天子之車斂轡徐行，故假望舒為言耳。彌音莫爾反。」","sentenceOrder":347},
  {"id":"s_work_han_thu_100_348","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　晉灼曰：「上蘭觀在上林中。」","sentenceOrder":348},
  {"id":"s_work_han_thu_100_349","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　師古曰：「部，軍之部校也，言稍聚逼而重。蹴音千欲反。」","sentenceOrder":349},
  {"id":"s_work_han_thu_100_350","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　師古曰：「隊亦部也。按，依也。隊音徒內反。行音胡郎反。」","sentenceOrder":350},
  {"id":"s_work_han_thu_100_351","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　師古曰：「言所抶擊如鬼神雷電也。抶音丑乙反。」","sentenceOrder":351},
  {"id":"s_work_han_thu_100_352","chapterId":"ch_work_han_thu_100","textTraditional":"〔九〕　師古曰：「言殺獲皆盡，無遺餘也。掃音先早反。」","sentenceOrder":352},
  {"id":"s_work_han_thu_100_353","chapterId":"ch_work_han_thu_100","textTraditional":"〔一０〕師古曰：「罕車，畢罕之車也。聿皇，疾貌。」","sentenceOrder":353},
  {"id":"s_work_han_thu_100_354","chapterId":"ch_work_han_thu_100","textTraditional":"〔一一〕師古曰：「嘄陽，費費也，人面黑身，有毛，反踵，見人則笑，脣蔽其目。絹音工犬反。嘄音工聊反。費音扶味反。」","sentenceOrder":354},
  {"id":"s_work_han_thu_100_355","chapterId":"ch_work_han_thu_100","textTraditional":"〔一二〕應劭曰：「天寶，陳寶也。」晉灼曰：「天寶雞頭人身。」","sentenceOrder":355},
  {"id":"s_work_han_thu_100_356","chapterId":"ch_work_han_thu_100","textTraditional":"〔一三〕如淳曰：「陳寶神來下時，駍然有聲，又有光精也。」應劭曰：「下時窮極山川天地之間，然後得其雌雄也。」師古曰：「雄在陳倉，雌在南陽也。故云野盡山窮也。駍音普萌反。」","sentenceOrder":356},
  {"id":"s_work_han_thu_100_357","chapterId":"ch_work_han_thu_100","textTraditional":"〔一四〕師古曰：「口內之上下名為噱，言禽獸奔走倦極，皆遙張噱吐舌於紭罔之中也。」師古曰：「噱音其略反。紭，古紘字。」","sentenceOrder":357},
  {"id":"s_work_han_thu_100_358","chapterId":"ch_work_han_thu_100","textTraditional":"〔一五〕孟康曰：「冘，行也。閼，止也。言三軍之盛，窮閼禽獸，使不得逸漏也。」晉灼曰：「閼與，容貌也。」師古曰：「閼與，容暇之貌也。芒音莫郎反。冘音淫。閼音於庶反。與音豫。」","sentenceOrder":358},
  {"id":"s_work_han_thu_100_359","chapterId":"ch_work_han_thu_100","textTraditional":"〔一六〕師古曰：「亶讀曰但。票禽，輕疾之禽也。紲與跇同。紲，度也。隃與踰同。挐，牽引也。攫，搏持之也。凌，戰栗也。遽，惶也。票音頻妙反。紲音弋制反。觸，合韻音昌樹反。挐音女居反。攫音钁。遽音詎。」","sentenceOrder":359},
  {"id":"s_work_han_thu_100_360","chapterId":"ch_work_han_thu_100","textTraditional":"〔一七〕師古曰：「徒亦但也。搶猶刺也。題，頟也。脰，頸也。言眾獸迫急，以角搶地，以頟注地，或自觸車輻，關頸而死也。搶音千羊反。蹙音子育反。脰音豆。」","sentenceOrder":360},
  {"id":"s_work_han_thu_100_361","chapterId":"ch_work_han_thu_100","textTraditional":"〔一八〕師古曰：「言矢雖妄發而必有中，進則履之，退則獲之。」","sentenceOrder":361},
  {"id":"s_work_han_thu_100_362","chapterId":"ch_work_han_thu_100","textTraditional":"〔一九〕師古曰：「淫，過也。夷，平也。言創過大，血流平於車輪也。丘累陵聚，言其積多。」","sentenceOrder":362},
  {"id":"s_work_han_thu_100_363","chapterId":"ch_work_han_thu_100","textTraditional":"於是禽殫中衰，〔一〕相與集於靖冥之館，〔二〕以臨珍池。灌以岐梁，溢以江河，〔三〕東瞰目盡，西暢亡厓，〔四〕隨珠和氏，焯爍其陂。〔五〕玉石嶜崟，眩燿青熒，〔六〕漢女水潛，怪物暗冥，不可殫形。〔七〕玄鸞孔雀，翡翠垂榮，〔八〕王雎關關，鴻鴈嚶嚶，〔九〕群娭虖其中，噍噍昆鳴；〔一０〕鳧鷖振鷺，上下砰磕，聲若雷霆。〔一一〕乃使文身之技，水格鱗蟲，〔一二〕凌堅冰，犯嚴淵，探巖排碕，薄索蛟螭，〔一三〕蹈獱獺，據黿鼉，〔一四〕抾靈蠵。〔一五〕入洞穴，出蒼梧，〔一六〕乘鉅鱗，騎京魚〔一七〕。浮彭蠡，目有虞。〔一八〕方椎夜光之流離，剖明月之珠胎，〔一九〕鞭洛水之虙妃，餉屈原與彭胥。〔二０〕","sentenceOrder":363},
  {"id":"s_work_han_thu_100_364","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「殫，盡也。中，射中也，音竹仲反。」","sentenceOrder":364},
  {"id":"s_work_han_thu_100_365","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　晉灼曰：「靖冥，深閑之館。」","sentenceOrder":365},
  {"id":"s_work_han_thu_100_366","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　晉灼曰：「梁，梁山也。」服虔曰：「珍池，山下之流也。」","sentenceOrder":366},
  {"id":"s_work_han_thu_100_367","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　師古曰：「瞰，視也。目盡，極望〔也〕亡厓（也），言廣遠也。」","sentenceOrder":367},
  {"id":"s_work_han_thu_100_368","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　師古曰：「焯，古灼字也。焯爍，光貌。爍音式藥反。」","sentenceOrder":368},
  {"id":"s_work_han_thu_100_369","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　師古曰：「玉石，石之似玉者也。嶜崟，高銳貌。青熒，言其色青而有光熒也。嶜音仕金反。崟音牛林反。」","sentenceOrder":369},
  {"id":"s_work_han_thu_100_370","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　應劭曰：「漢女，鄭交甫所逢二女，弄大珠，大如荊雞子。」師古曰：「不可殫形，不能盡其形貌之狀。」","sentenceOrder":370},
  {"id":"s_work_han_thu_100_371","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　師古曰：「言其毛羽有光華。」","sentenceOrder":371},
  {"id":"s_work_han_thu_100_372","chapterId":"ch_work_han_thu_100","textTraditional":"〔九〕　師古曰：「王雎，雎鳩也。關關，和聲也。嚶嚶，相命〔聲〕也。嚶音於行反。」","sentenceOrder":372},
  {"id":"s_work_han_thu_100_373","chapterId":"ch_work_han_thu_100","textTraditional":"〔一０〕師古曰：「娭，戲也。昆，同也。娭音許其反。噍音子由反。」","sentenceOrder":373},
  {"id":"s_work_han_thu_100_374","chapterId":"ch_work_han_thu_100","textTraditional":"〔一一〕師古曰：「鳧，水鳥，即今之野鴨也。鷖，鳥屬也。鷺，白鳥也。振者，言振羽翼而飛也。詩大雅曰『鳧鷖在涇』，周頌曰『振鷺于飛』，三者皆水鳥也。言其群飛上下，翅翼之聲若雷霆也。鷖音音烏奚反。砰音普萌反。」","sentenceOrder":374},
  {"id":"s_work_han_thu_100_375","chapterId":"ch_work_han_thu_100","textTraditional":"〔一二〕服虔曰：「文身，越人也，能入水取物。」","sentenceOrder":375},
  {"id":"s_work_han_thu_100_376","chapterId":"ch_work_han_thu_100","textTraditional":"〔一三〕師古曰：「嚴，言不可犯也。巖，水岸嶔巖之處也。碕，曲岸也。薄，迫也。索，搜求也。碕音鉅依反。嶔音口銜反。」","sentenceOrder":376},
  {"id":"s_work_han_thu_100_377","chapterId":"ch_work_han_thu_100","textTraditional":"〔一四〕蘇林曰：「獱音賓。」師古曰：「獺，形如狗，在水中食魚。獱，小獺也。獺音它曷反。」","sentenceOrder":377},
  {"id":"s_work_han_thu_100_378","chapterId":"ch_work_han_thu_100","textTraditional":"〔一五〕鄭氏曰：「抾音怯。」應劭曰：「蠵，大龜也。雄曰毒冒，雌曰觜蠵。」師古曰：「抾，挹（抆）〔取〕也，又音袪。蠵音弋隨反，又音攜。」","sentenceOrder":378},
  {"id":"s_work_han_thu_100_379","chapterId":"ch_work_han_thu_100","textTraditional":"〔一六〕晉灼曰：「洞穴，禹穴也。」師古曰：「洞，通也。」","sentenceOrder":379},
  {"id":"s_work_han_thu_100_380","chapterId":"ch_work_han_thu_100","textTraditional":"〔一七〕師古曰：「京，大也，或讀為鯨。鯨，大魚也。」","sentenceOrder":380},
  {"id":"s_work_han_thu_100_381","chapterId":"ch_work_han_thu_100","textTraditional":"〔一八〕應劭曰：「彭蠡，大澤，在豫章。」師古曰：「目猶視也，望也。有虞謂舜陟方在江南，言遙望也。」","sentenceOrder":381},
  {"id":"s_work_han_thu_100_382","chapterId":"ch_work_han_thu_100","textTraditional":"〔一九〕師古曰：「珠在蛤中若懷妊然，故謂之胎也。椎音直佳反，其字從木。」","sentenceOrder":382},
  {"id":"s_work_han_thu_100_383","chapterId":"ch_work_han_thu_100","textTraditional":"〔二０〕師古曰：「彭，彭咸，胥，伍子胥，皆水死者。虙讀曰伏。」","sentenceOrder":383},
  {"id":"s_work_han_thu_100_384","chapterId":"ch_work_han_thu_100","textTraditional":"於茲虖鴻生鉅儒，俄軒冕，雜衣裳，〔一〕修唐典，匡雅頌，揖讓於前。〔二〕昭光振燿，蠁曶如神，〔三〕仁聲惠於北狄，武義動於南鄰。〔四〕是以旃裘之王，胡貉之長，移珍來享，抗手稱臣。〔五〕前入圍口，後陳盧山。〔六〕群公常伯楊朱、墨翟之徒〔七〕喟然稱曰：〔八〕「崇哉乎德，雖有唐、虞、大夏、成周之隆，何以侈茲！太古之覲東嶽，禪梁基，舍此世也，其誰與哉？」","sentenceOrder":384},
  {"id":"s_work_han_thu_100_385","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　師古曰：「俄俄，陳舉之貌。雜者，言衣與裳皆雜色也。」","sentenceOrder":385},
  {"id":"s_work_han_thu_100_386","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　師古曰：「匡，正也。」","sentenceOrder":386},
  {"id":"s_work_han_thu_100_387","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「蠁與嚮同。曶與忽同。」","sentenceOrder":387},
  {"id":"s_work_han_thu_100_388","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　師古曰：「南方有金鄰之國，極遠也，故云南鄰。一曰，鄰邑也。」","sentenceOrder":388},
  {"id":"s_work_han_thu_100_389","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　如淳曰：「以物與人曰移。」師古曰：「貉，東北夷也。享，獻也。抗，舉手也，言其肅恭合掌而拜也。貉音莫百反。」","sentenceOrder":389},
  {"id":"s_work_han_thu_100_390","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　孟康曰：「單于南庭山也。」","sentenceOrder":390},
  {"id":"s_work_han_thu_100_391","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　師古曰：「常伯，侍中也。解在谷永傳。楊朱、墨翟，取古賢以為喻也。」","sentenceOrder":391},
  {"id":"s_work_han_thu_100_392","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　師古曰：「喟，歎息也，音丘位反。」","sentenceOrder":392},
  {"id":"s_work_han_thu_100_393","chapterId":"ch_work_han_thu_100","textTraditional":"上猶謙讓而未俞也，〔一〕方將上獵三靈之流，下決醴泉之滋，〔二〕發黃龍之穴，窺鳳皇之巢，臨麒麟之囿，幸神雀之林；奢雲夢，侈孟諸，〔三〕非章華，是靈臺，〔四〕罕徂離宮而輟觀游，〔五〕土事不飾，木功不彫，承民乎農桑，〔六〕勸之以弗迨，儕男女使莫違；〔七〕恐貧窮者不遍被洋溢之饒，開禁苑，散公儲，創道德之囿，弘仁惠之虞，〔八〕馳弋乎神明之囿，覽觀乎群臣之有亡；放雉菟，收罝罘，麋鹿芻蕘與百姓共之，〔九〕蓋所以臻茲也。於是醇洪鬯之德，豐茂世之規，〔一０〕加勞三皇，勗勤五帝，不亦至乎！乃祗莊雍穆之徒，〔一一〕立君臣之節，崇賢聖之業，未皇苑囿之麗，游獵之靡也，〔一二〕因回軫還衡，〔一三〕背阿房，反未央。","sentenceOrder":393},
  {"id":"s_work_han_thu_100_394","chapterId":"ch_work_han_thu_100","textTraditional":"〔一〕　張晏曰：「俞，然也。」師古曰：「俞音踰。」","sentenceOrder":394},
  {"id":"s_work_han_thu_100_395","chapterId":"ch_work_han_thu_100","textTraditional":"〔二〕　如淳曰：「三靈，日月星垂象之應也。」師古曰：「流者，言其和液下流。」","sentenceOrder":395},
  {"id":"s_work_han_thu_100_396","chapterId":"ch_work_han_thu_100","textTraditional":"〔三〕　師古曰：「雲夢，楚藪澤名也。春秋昭公三年『楚靈王與鄭伯田于江南之夢』。孟諸，宋藪澤名。文公十年『楚穆王欲伐宋，昭公導之以田孟諸』。言今皆以二者為奢侈而改也。」","sentenceOrder":396},
  {"id":"s_work_han_thu_100_397","chapterId":"ch_work_han_thu_100","textTraditional":"〔四〕　師古曰：「言以楚靈王章華之臺為非，而周文王靈臺之制為是也。」","sentenceOrder":397},
  {"id":"s_work_han_thu_100_398","chapterId":"ch_work_han_thu_100","textTraditional":"〔五〕　師古曰：「罕，希也。徂，往也。輟，止也。」","sentenceOrder":398},
  {"id":"s_work_han_thu_100_399","chapterId":"ch_work_han_thu_100","textTraditional":"〔六〕　師古曰：「承，舉也。」","sentenceOrder":399},
  {"id":"s_work_han_thu_100_400","chapterId":"ch_work_han_thu_100","textTraditional":"〔七〕　師古曰：「儕，耦也。違謂失婚姻時也。儕音仕皆反。」","sentenceOrder":400},
  {"id":"s_work_han_thu_100_401","chapterId":"ch_work_han_thu_100","textTraditional":"〔八〕　師古曰：「虞與娛同。」","sentenceOrder":401},
  {"id":"s_work_han_thu_100_402","chapterId":"ch_work_han_thu_100","textTraditional":"〔九〕　師古曰：「芻所以（飯）〔飤〕牛馬。蕘，草薪。」","sentenceOrder":402},
  {"id":"s_work_han_thu_100_403","chapterId":"ch_work_han_thu_100","textTraditional":"〔一０〕師古曰：「洪，大也。鬯與暢同。暢，通也。」","sentenceOrder":403},
  {"id":"s_work_han_thu_100_404","chapterId":"ch_work_han_thu_100","textTraditional":"〔一一〕師古曰：「祇莊，敬也。雍穆，和也。」","sentenceOrder":404},
  {"id":"s_work_han_thu_100_405","chapterId":"ch_work_han_thu_100","textTraditional":"〔一二〕師古曰：「皇，暇也。」","sentenceOrder":405},
  {"id":"s_work_han_thu_100_406","chapterId":"ch_work_han_thu_100","textTraditional":"〔一三〕師古曰：「軫，輿後橫木也。衡，轅前橫木也。」","sentenceOrder":406},
  {"id":"s_work_han_thu_100_407","chapterId":"ch_work_han_thu_100","textTraditional":"校勘記","sentenceOrder":407},
  {"id":"s_work_han_thu_100_408","chapterId":"ch_work_han_thu_100","textTraditional":"三五一三頁　四行　以支庶初食采於晉之（楊）〔揚〕。　景祐、殿本都作「揚」，下文及注原作「楊」者並照改。","sentenceOrder":408},
  {"id":"s_work_han_thu_100_409","chapterId":"ch_work_han_thu_100","textTraditional":"三五一四頁　二行　偪，古逼（也）〔字〕。　殿本作「字」。王先謙說殿本是。","sentenceOrder":409},
  {"id":"s_work_han_thu_100_410","chapterId":"ch_work_han_thu_100","textTraditional":"三五一八頁　七行　（固）不如襞而幽之離房。　景祐、殿本都無「固」字。","sentenceOrder":410},
  {"id":"s_work_han_thu_100_411","chapterId":"ch_work_han_thu_100","textTraditional":"三五二一頁一三行　（焉）駕八龍之委蛇？　景祐、殿本都無「焉」字。","sentenceOrder":411},
  {"id":"s_work_han_thu_100_412","chapterId":"ch_work_han_thu_100","textTraditional":"三五二一頁一四行　夫聖哲之（不）遭兮，　景祐、殿本都無「不」字。","sentenceOrder":412},
  {"id":"s_work_han_thu_100_413","chapterId":"ch_work_han_thu_100","textTraditional":"三五二二頁一二行　（亦）〔音〕之亦反。　景祐、殿、局本都作「音」，此誤。","sentenceOrder":413},
  {"id":"s_work_han_thu_100_414","chapterId":"ch_work_han_thu_100","textTraditional":"三五二五頁一０行　（亦）〔言〕寒涼戰栗之處也。　景祐、殿本都作「言」，此誤。","sentenceOrder":414},
  {"id":"s_work_han_thu_100_415","chapterId":"ch_work_han_thu_100","textTraditional":"三五二八頁　一行　一曰施，直謂安施（音）之耳，　景祐本無「音」字，此衍。","sentenceOrder":415},
  {"id":"s_work_han_thu_100_416","chapterId":"ch_work_han_thu_100","textTraditional":"三五二八頁　四行　蔑蠓，（疾）〔蚊〕也。　殿、局本都作「蚊」。","sentenceOrder":416},
  {"id":"s_work_han_thu_100_417","chapterId":"ch_work_han_thu_100","textTraditional":"三五二九頁　六行　衍音（赤）〔亦〕戰反。　景祐、殿、局本都作「亦」，此誤。","sentenceOrder":417},
  {"id":"s_work_han_thu_100_418","chapterId":"ch_work_han_thu_100","textTraditional":"三五三０頁一五行　冠倫魁能，〔五〕　注〔五〕原在「能」字上，明顏師古以「冠倫魁」斷句。劉攽、劉敞、齊召南、王先謙都說「能」字當屬上讀，文選同。","sentenceOrder":418},
  {"id":"s_work_han_thu_100_419","chapterId":"ch_work_han_thu_100","textTraditional":"三五三一頁　二行　陳眾車（所）〔於〕東阬兮，　景祐、殿本都作「於」。王先謙說作「於」是。","sentenceOrder":419},
  {"id":"s_work_han_thu_100_420","chapterId":"ch_work_han_thu_100","textTraditional":"三五三一頁　五行　（眸）〔侔〕神明與之為資。　景祐、殿本都作「侔」。","sentenceOrder":420},
  {"id":"s_work_han_thu_100_421","chapterId":"ch_work_han_thu_100","textTraditional":"三五三二頁一０行　招繇泰壹，　王先謙說招搖雖亦神名，施於此處則不類。按禮樂志「體招搖若永望」。顏注「申動貌」。下文「徘徊招搖」同。","sentenceOrder":421},
  {"id":"s_work_han_thu_100_422","chapterId":"ch_work_han_thu_100","textTraditional":"三五三四頁一二行　遲音（又）〔丈〕夷反。　景祐本作「丈」。王先謙說作「丈」是。","sentenceOrder":422},
  {"id":"s_work_han_thu_100_423","chapterId":"ch_work_han_thu_100","textTraditional":"三五三五頁　二行　若曰此非人力之所（能）〔為〕，　景祐、殿本都作「為」。","sentenceOrder":423},
  {"id":"s_work_han_thu_100_424","chapterId":"ch_work_han_thu_100","textTraditional":"三五三六頁　五行　皆可（相）〔想〕見，　殿本作「想」。王先謙說作「想」是。","sentenceOrder":424},
  {"id":"s_work_han_thu_100_425","chapterId":"ch_work_han_thu_100","textTraditional":"三五三六頁一一行　（義）〔羲〕和司日，　景祐、汲古、殿、局本都作「羲」，此誤。","sentenceOrder":425},
  {"id":"s_work_han_thu_100_426","chapterId":"ch_work_han_thu_100","textTraditional":"三五三七頁一一行　屈橋，（言）壯捷貌。　景祐、殿本都無「言」字，此衍。","sentenceOrder":426},
  {"id":"s_work_han_thu_100_427","chapterId":"ch_work_han_thu_100","textTraditional":"三五三八頁　五行　灑沈（葘）〔災〕於豁瀆兮，　錢大昭說「葘」當作「災」。按殿本作「災」。","sentenceOrder":427},
  {"id":"s_work_han_thu_100_428","chapterId":"ch_work_han_thu_100","textTraditional":"三五四二頁　二行　（師古曰）馺音先合反。　景祐、殿本都無「師古曰」三字，此衍。","sentenceOrder":428},
  {"id":"s_work_han_thu_100_429","chapterId":"ch_work_han_thu_100","textTraditional":"三五四二頁　六行　營謂（園）〔圍〕守也。　景祐、殿本都作「圍」，此誤。","sentenceOrder":429},
  {"id":"s_work_han_thu_100_430","chapterId":"ch_work_han_thu_100","textTraditional":"三五四五頁一三行　徽車，有徽（熾）〔幟〕之車也。　景祐、殿本都作「幟」，此誤。","sentenceOrder":430},
  {"id":"s_work_han_thu_100_431","chapterId":"ch_work_han_thu_100","textTraditional":"三五四五頁一七行　撞鴻鍾，建九（流）〔旒〕。　景祐、殿本都作「旒」。","sentenceOrder":431},
  {"id":"s_work_han_thu_100_432","chapterId":"ch_work_han_thu_100","textTraditional":"三五四六頁一四行　言車之眾（飭）〔飾〕　殿本作「飾」。王先謙說殿本是。","sentenceOrder":432},
  {"id":"s_work_han_thu_100_433","chapterId":"ch_work_han_thu_100","textTraditional":"三五五一頁　五行　目盡，極望〔也〕。亡厓（也），言廣遠也。　殿本「也」字在「極望」下。王先謙說殿本是。","sentenceOrder":433},
  {"id":"s_work_han_thu_100_434","chapterId":"ch_work_han_thu_100","textTraditional":"三五五一頁一０行　相命〔聲〕也。　景祐、殿本都有「聲」字。","sentenceOrder":434},
  {"id":"s_work_han_thu_100_435","chapterId":"ch_work_han_thu_100","textTraditional":"三五五二頁　一行　抾，挹（抆）〔取〕也。　景祐、殿、局本都作「取」。","sentenceOrder":435},
  {"id":"s_work_han_thu_100_436","chapterId":"ch_work_han_thu_100","textTraditional":"三五五四頁　六行　芻所以（飯）〔飤〕牛馬。　景祐、殿本都作「飤」。","sentenceOrder":436},
  {"id":"s_work_han_thu_101_1","chapterId":"ch_work_han_thu_101","textTraditional":"明年，上將大誇胡人以多禽獸，秋，命右扶風發民入南山，西自褒斜，東至弘農，南敺漢中，〔一〕張羅罔罝罘，捕熊羆豪豬虎豹狖玃狐菟麋鹿，〔二〕載以檻車，輸長楊射熊館。〔二〕以罔為周阹，〔四〕（從）〔縱〕禽獸其中，令胡人手搏之，自取其獲，上親臨觀焉。是時，農民不得收斂。雄從至射熊館，還，上長楊賦，聊因筆墨之成文章，故藉翰林以為主人，子墨為客卿以風。〔五〕其辭曰：","sentenceOrder":1},
  {"id":"s_work_han_thu_101_2","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「褒斜，南山二谷名也。漢中，今梁州也。斜音弋奢反。」","sentenceOrder":2},
  {"id":"s_work_han_thu_101_3","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「狖似獮猴，仰鼻而長尾。玃亦獮猴類也，長臂善搏。玃身長，金色。狖音弋授反。玃音钁。」","sentenceOrder":3},
  {"id":"s_work_han_thu_101_4","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　師古曰：「長楊，宮名也，在盩厔縣，其中有射熊館。」","sentenceOrder":4},
  {"id":"s_work_han_thu_101_5","chapterId":"ch_work_han_thu_101","textTraditional":"〔四〕　李奇曰：「阹，遮禽獸圍陳也。」師古曰：「阹音袪。」","sentenceOrder":5},
  {"id":"s_work_han_thu_101_6","chapterId":"ch_work_han_thu_101","textTraditional":"〔五〕　師古曰：「藉，借也。風讀曰諷。」","sentenceOrder":6},
  {"id":"s_work_han_thu_101_7","chapterId":"ch_work_han_thu_101","textTraditional":"子墨客卿問於翰林主人曰：「蓋聞聖主之養民也，仁霑而恩洽，動不為身。〔一〕今年獵長楊，先命右扶風，左太華而右褒斜，〔二〕椓（截）〔巀〕嶭而為弋，紆南山以為罝，〔三〕羅千乘於林莽，列萬騎於山隅，〔四〕帥軍踤阹，錫戎獲胡。〔五〕搤熊羆，拕豪豬，〔六〕木雍槍纍，以為儲胥，〔七〕此天下之窮覽極觀也。雖然，亦頗擾于農民。三旬有餘，其廑至矣，〔八〕而功不圖，〔九〕恐不識者，外之則以為娛樂之遊，內之則不以為乾豆之事，〔一０〕豈為民乎哉！且人君以玄默為神，澹泊為德，〔一一〕今樂遠出以露威靈，〔一二〕數搖動以罷車甲，〔一三〕本非人主之急務也。蒙竊或焉。」〔一四〕","sentenceOrder":7},
  {"id":"s_work_han_thu_101_8","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「言憂百姓也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_101_9","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「太華即西嶽華山。」","sentenceOrder":9},
  {"id":"s_work_han_thu_101_10","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　師古曰：「巀嶭即所謂嵯峨山也，在京師之北。凡言此者，示獵圍之寬廣也。巀嶭音截齧，又音材葛反，又音五葛反。」","sentenceOrder":10},
  {"id":"s_work_han_thu_101_11","chapterId":"ch_work_han_thu_101","textTraditional":"〔四〕　師古曰：「草平曰莽。」","sentenceOrder":11},
  {"id":"s_work_han_thu_101_12","chapterId":"ch_work_han_thu_101","textTraditional":"〔五〕　師古曰：「踤，足蹴之也。錫戎獲胡，言以禽獸賦戎狄，令胡人獲取之。踤音才恤反。」","sentenceOrder":12},
  {"id":"s_work_han_thu_101_13","chapterId":"ch_work_han_thu_101","textTraditional":"〔六〕　師古曰：「搤，捉持之也。豪豬亦名帚豲也，自為牝牡者也。搤音厄。拕音佗。豲音（完）〔桓〕。」","sentenceOrder":13},
  {"id":"s_work_han_thu_101_14","chapterId":"ch_work_han_thu_101","textTraditional":"〔七〕　蘇林曰：「木擁柵其外，又以竹槍纍為外儲也。」服虔曰：「儲胥猶言有餘也。」師古曰：「儲，峙也。胥，須也。以木擁槍及纍繩連結以為儲胥，言有儲畜以待所須也。槍音千羊反。纍音力佳反。」","sentenceOrder":14},
  {"id":"s_work_han_thu_101_15","chapterId":"ch_work_han_thu_101","textTraditional":"〔八〕　師古曰：「廑，古勤字。」","sentenceOrder":15},
  {"id":"s_work_han_thu_101_16","chapterId":"ch_work_han_thu_101","textTraditional":"〔九〕　張晏曰：「不可圖畫以示後人。」師古曰：「此說非也。圖，謀也，言百姓甚勤勞矣，而不見謀贍恤之事。」","sentenceOrder":16},
  {"id":"s_work_han_thu_101_17","chapterId":"ch_work_han_thu_101","textTraditional":"〔一０〕師古曰：「乾豆，三驅之一也。乾豆者，言為脯羞以充實豆，薦宗廟。」","sentenceOrder":17},
  {"id":"s_work_han_thu_101_18","chapterId":"ch_work_han_thu_101","textTraditional":"〔一一〕師古曰：「澹泊，安靜也。澹音徒濫反。泊音步各反，又音魄。」","sentenceOrder":18},
  {"id":"s_work_han_thu_101_19","chapterId":"ch_work_han_thu_101","textTraditional":"〔一二〕師古曰：「露謂顯暴不深固。」","sentenceOrder":19},
  {"id":"s_work_han_thu_101_20","chapterId":"ch_work_han_thu_101","textTraditional":"〔一三〕師古曰：「罷讀曰疲。」","sentenceOrder":20},
  {"id":"s_work_han_thu_101_21","chapterId":"ch_work_han_thu_101","textTraditional":"〔一四〕師古曰：「蒙，自謂蒙蔽也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_101_22","chapterId":"ch_work_han_thu_101","textTraditional":"翰林主人曰：「吁，謂之茲邪！〔一〕若客，所謂知其一未睹其二，見其外不識其內者也。僕嘗倦談，不能一二其詳，〔二〕請略舉凡，而客自覽其切焉。」〔三〕","sentenceOrder":22},
  {"id":"s_work_han_thu_101_23","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「吁，疑怪之辭也。謂茲邪，猶云何為如此也。吁音于。」","sentenceOrder":23},
  {"id":"s_work_han_thu_101_24","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「詳，悉也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_101_25","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　師古曰：「凡，大指也。切，要也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_101_26","chapterId":"ch_work_han_thu_101","textTraditional":"客曰：「唯，唯。」","sentenceOrder":26},
  {"id":"s_work_han_thu_101_27","chapterId":"ch_work_han_thu_101","textTraditional":"主人曰：「昔有彊秦，封豕其士，窫窳其民，鑿齒之徒相與摩牙而爭之，〔一〕豪俊麋沸雲擾，群黎為之不康。〔二〕於是上帝眷顧高祖，高祖奉命，順斗極，運天關，橫鉅海，票昆侖，〔三〕提劍而叱之，所麾城（搟）〔摲〕邑，下將降旗，〔四〕一日之戰，不可殫記。〔五〕當此之勤，頭蓬不暇疏，飢不及餐，〔六〕鞮鍪生蟣蝨，介冑被霑汗，〔七〕以為萬姓請命虖皇天。乃展民之所詘，振民之所乏，〔八〕規億載，恢帝業，七年之間而天下密如也。〔九〕","sentenceOrder":27},
  {"id":"s_work_han_thu_101_28","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　應劭曰：「淮南子云，堯之時窫窳、封豨、鑿齒皆為民害。窫窳類貙，虎爪食人。」服虔曰：「鑿齒〔齒〕長五寸，似鑿，亦食人。」李奇曰：「以喻秦貪婪，殘食其民也。」師古曰：「封，大也。窫音於黠反。窳音愈。」","sentenceOrder":28},
  {"id":"s_work_han_thu_101_29","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「黎，眾；康，安也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_101_30","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　師古曰：「票猶言搖動也，音匹昭反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_101_31","chapterId":"ch_work_han_thu_101","textTraditional":"〔四〕　李奇曰：「（搟）〔摲〕音車幰之幰。」師古曰：「（搟）〔摲〕，舉手擬之也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_101_32","chapterId":"ch_work_han_thu_101","textTraditional":"〔五〕　師古曰：「殫，盡也。不可盡記，言其多也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_101_33","chapterId":"ch_work_han_thu_101","textTraditional":"〔六〕　師古曰：「蓬謂髮亂如蓬也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_101_34","chapterId":"ch_work_han_thu_101","textTraditional":"〔七〕　師古曰：「鞮鍪即兜鍪也。鞮音丁奚反。鍪音牟。蟣音居豈反。」","sentenceOrder":34},
  {"id":"s_work_han_thu_101_35","chapterId":"ch_work_han_thu_101","textTraditional":"〔八〕　師古曰：「展，申也。振，起也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_101_36","chapterId":"ch_work_han_thu_101","textTraditional":"〔九〕　師古曰：「密，靜也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_101_37","chapterId":"ch_work_han_thu_101","textTraditional":"「逮至聖文，隨風乘流，方垂意於至寧，躬服節儉，綈衣不敝，革鞜不穿，〔一〕大夏不居，木器無文。〔二〕於是後宮賤玳瑁而疏珠璣，卻翡翠之飾，除彫瑑之巧，〔三〕惡麗靡而不近，斥芬芳而不御，〔四〕抑止絲竹晏衍之樂，憎聞鄭衛幼眇之聲，〔五〕是以玉衡正而太階平也。〔六〕","sentenceOrder":37},
  {"id":"s_work_han_thu_101_38","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「言不穿敝而已，無取紛華也。鞜，革履，音踏。」","sentenceOrder":38},
  {"id":"s_work_han_thu_101_39","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「大夏，夏屋也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_101_40","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　師古曰：「瑑，刻鏤也。瑑音篆。」","sentenceOrder":40},
  {"id":"s_work_han_thu_101_41","chapterId":"ch_work_han_thu_101","textTraditional":"〔四〕　師古曰：「斥，卻也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_101_42","chapterId":"ch_work_han_thu_101","textTraditional":"〔五〕　師古曰：「衍音弋戰反。幼音一笑反。眇音妙。」","sentenceOrder":42},
  {"id":"s_work_han_thu_101_43","chapterId":"ch_work_han_thu_101","textTraditional":"〔六〕　師古曰：「玉衡，天儀也。太階，解在東方朔傳。」","sentenceOrder":43},
  {"id":"s_work_han_thu_101_44","chapterId":"ch_work_han_thu_101","textTraditional":"「其後熏鬻作虐，東夷橫畔，〔一〕羌戎睚眥，閩越相亂，〔二〕遐萌為之不安，中國蒙被其難。〔三〕於是聖武勃怒，爰整其旅，乃命票、衛，〔四〕汾沄沸渭，雲合電發，〔五〕猋騰波流，機駭鋒軼，〔六〕疾如奔星，擊如震霆，〔七〕砰轒轀，破穹廬，〔八〕腦沙幕，髓余吾。〔九〕遂獵乎王延。〔一０〕敺橐它，燒〈火鼏〉蠡，〔一一〕分梨單于，磔裂屬國，〔一二〕夷阬谷，拔鹵莽，刊山石，〔一三〕蹂屍輿廝，係累老弱，〔一四〕兗鋋瘢耆、金鏃淫夷者數十萬人，〔一五〕皆稽顙樹頷，扶服蛾伏，〔一六〕二十餘年矣，尚不敢惕息。〔一七〕夫天兵四臨，幽都先加，〔一八〕回戈邪指，南越相夷，〔一九〕靡節西征，羌僰東馳。是以遐方疏俗殊鄰絕黨之域，〔二０〕自上仁所不化，茂德所不綏，莫不蹻足抗手，請獻厥珍，〔二一〕使海內澹然，〔二二〕永亡邊城之災，金革之患。","sentenceOrder":44},
  {"id":"s_work_han_thu_101_45","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「鬻音弋六反。橫音胡孟反。」","sentenceOrder":45},
  {"id":"s_work_han_thu_101_46","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「睚眥，瞋目貌。睚音五懈反。眥音仕懈反。睚字或作矔，矔者怒其目眥也，音工喚反。」","sentenceOrder":46},
  {"id":"s_work_han_thu_101_47","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　師古曰：「遐，遠也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_101_48","chapterId":"ch_work_han_thu_101","textTraditional":"〔四〕　師古曰：「票，票騎霍去病。衛，衛青也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_101_49","chapterId":"ch_work_han_thu_101","textTraditional":"〔五〕　師古曰：「汾沄沸渭，奮擊貌。汾音紛，紜音雲。」","sentenceOrder":49},
  {"id":"s_work_han_thu_101_50","chapterId":"ch_work_han_thu_101","textTraditional":"〔六〕　師古曰：「猋，疾風也。騰，舉也。蠭與鋒同。軼，過也。如機之駭，如蠭之過，言其疾也。軼與逸同。」","sentenceOrder":50},
  {"id":"s_work_han_thu_101_51","chapterId":"ch_work_han_thu_101","textTraditional":"〔七〕　師古曰：「霆，雷之急者，音廷。」","sentenceOrder":51},
  {"id":"s_work_han_thu_101_52","chapterId":"ch_work_han_thu_101","textTraditional":"〔八〕　應劭曰：「轒轀，匈奴車也。」師古曰：「穹廬，氈帳也。轒音扶云反。轀音於云反。」","sentenceOrder":52},
  {"id":"s_work_han_thu_101_53","chapterId":"ch_work_han_thu_101","textTraditional":"〔九〕　師古曰：「腦塗沙幕地，〈髓，去辶〉入余吾水，言其大破死亡。〈髓，去辶〉，古髓字。」","sentenceOrder":53},
  {"id":"s_work_han_thu_101_54","chapterId":"ch_work_han_thu_101","textTraditional":"〔一０〕孟康曰：「匈奴王廷也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_101_55","chapterId":"ch_work_han_thu_101","textTraditional":"〔一一〕張晏曰：「〈火鼏〉蠡，乾酪也，以為酪母。燒之，壞其養生之具也。」師古曰：「〈火鼏〉音覓。蠡音黎，又音來戈反。」","sentenceOrder":55},
  {"id":"s_work_han_thu_101_56","chapterId":"ch_work_han_thu_101","textTraditional":"〔一二〕師古曰：「梨與剺同，謂剝析也。剺音力私反。」","sentenceOrder":56},
  {"id":"s_work_han_thu_101_57","chapterId":"ch_work_han_thu_101","textTraditional":"〔一三〕師古曰：「鹵莽，淺草之地也。阬音口衡反。莽音莫戶反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_101_58","chapterId":"ch_work_han_thu_101","textTraditional":"〔一四〕師古曰：「言已死則蹂踐其屍，破傷者則輿之而行也。廝，破折也，音斯。累音力追反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_101_59","chapterId":"ch_work_han_thu_101","textTraditional":"〔一五〕如淳曰：「兗，括也。」孟康曰：「瘢耆，馬脊創瘢處也。」蘇林曰：「以耆字為著字。著音僨之著，鏃著其頭也。」師古曰：「鋋，鐵矜小矛也。淫夷，過傷也。據如、孟氏之說，則箭括及鋋所中，皆有創瘢於耆，而被金鏃過傷者復眾也。如蘇氏以耆字為著字，依其所釋，則括及鋋所傷皆有瘢，又著金鏃於頭上而過傷者亦多矣。用字既別，分句不同。據今書本多作耆字，宜從孟說。鋋音蟬，又音延。著音竹略反。矜音巨巾反。」","sentenceOrder":59},
  {"id":"s_work_han_thu_101_60","chapterId":"ch_work_han_thu_101","textTraditional":"〔一六〕如淳曰：「叩頭時項下向，則頷樹上向也。」師古曰：「樹，豎也。頷音胡感反。服音蒲北反。蛾與蟻同。蛾伏者，言其伏如蟲蟻也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_101_61","chapterId":"ch_work_han_thu_101","textTraditional":"〔一七〕師古曰：「惕息，懼而小息也。息，出入氣也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_101_62","chapterId":"ch_work_han_thu_101","textTraditional":"〔一八〕師古曰：「幽都，北方，謂匈奴。」","sentenceOrder":62},
  {"id":"s_work_han_thu_101_63","chapterId":"ch_work_han_thu_101","textTraditional":"〔一九〕師古曰：「夷，傷也，一曰平殄也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_101_64","chapterId":"ch_work_han_thu_101","textTraditional":"〔二０〕師古曰：「疏亦遠也。鄰，邑也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_101_65","chapterId":"ch_work_han_thu_101","textTraditional":"〔二一〕師古曰：「蹻，舉也，音矯。」","sentenceOrder":65},
  {"id":"s_work_han_thu_101_66","chapterId":"ch_work_han_thu_101","textTraditional":"〔二二〕師古曰：「澹，安也，音徒濫反。」","sentenceOrder":66},
  {"id":"s_work_han_thu_101_67","chapterId":"ch_work_han_thu_101","textTraditional":"「今朝廷純仁，遵道顯義，并包書林，聖風雲靡；〔一〕英華沈浮，洋溢八區，普天所覆，莫不沾濡；士有不談王道者則樵夫笑之。〔二〕故意者以為事罔隆而不殺，物靡盛而不虧，〔三〕故平不肆險，安不忘危。〔四〕乃時以有年出兵，整輿竦戎，〔五〕振師五莋，習馬長楊，〔六〕簡力狡獸，校武票禽。〔七〕乃萃然登南山，瞰烏弋，〔八〕西厭月〈出骨〉，東震日域。〔九〕又恐後世迷於一時之事，常以此取國家之大務，淫荒田獵，陵夷而不禦也，〔一０〕是以車不安軔，日未靡旃，從者仿佛，委屬而還；〔一一〕亦所以奉太宗之烈，遵文武之度，復三王之田，反五帝之虞；〔一二〕使農不輟耰，工不下機，〔一三〕婚姻以時，男女莫違；〔一四〕出愷弟，行簡易，矜劬勞，休力役；〔一五〕見百年，存孤弱，帥與之，同苦樂。然後陳鐘鼓之樂，鳴鞀磬之和，建碣磍之虡，〔一六〕拮隔鳴球，掉八列之舞；〔一七〕酌允鑠，肴樂胥，〔一八〕聽廟中之雍雍，受神人之福祜；〔一九〕歌投頌，吹合雅。其勤若此，故真神之所勞也〔二０〕。方將俟元符，〔二一〕以禪梁甫之基，增泰山之高，延光于將來，比榮乎往號，豈徒欲淫覽浮觀，馳騁梗稻之地，周流梨栗之林，蹂踐芻蕘，誇詡眾庶，盛狖玃之收，多麋鹿之獲哉！且盲不見咫尺，而離婁燭千里之隅；〔二二〕客徒愛胡人之獲我禽獸，曾不知我亦已獲其王侯。」","sentenceOrder":67},
  {"id":"s_work_han_thu_101_68","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「靡，合韻音武義反。」","sentenceOrder":68},
  {"id":"s_work_han_thu_101_69","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「樵夫，采樵之人。」","sentenceOrder":69},
  {"id":"s_work_han_thu_101_70","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　師古曰：「罔、靡，皆無也。殺，衰也。音所例反。」","sentenceOrder":70},
  {"id":"s_work_han_thu_101_71","chapterId":"ch_work_han_thu_101","textTraditional":"〔四〕　服虔曰：「肆，棄也。」師古曰：「肆，放也，不放心於險而嘗思念也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_101_72","chapterId":"ch_work_han_thu_101","textTraditional":"〔五〕　師古曰：「有年，有豐年也。因豐年而時出兵也。竦，勸也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_101_73","chapterId":"ch_work_han_thu_101","textTraditional":"〔六〕　師古曰：「振亦整也。莋與柞同。」","sentenceOrder":73},
  {"id":"s_work_han_thu_101_74","chapterId":"ch_work_han_thu_101","textTraditional":"〔七〕　師古曰：「校，計量也。票禽，輕疾之禽也。票音頻妙反，又音匹妙反。」","sentenceOrder":74},
  {"id":"s_work_han_thu_101_75","chapterId":"ch_work_han_thu_101","textTraditional":"〔八〕　晉灼曰：「萃，集也。」服虔曰：「三十六國，烏弋最在其西。」師古曰：「瞰，遠視也。音口濫反。」","sentenceOrder":75},
  {"id":"s_work_han_thu_101_76","chapterId":"ch_work_han_thu_101","textTraditional":"〔九〕　服虔曰：「〈出骨〉音窟穴。月〈出骨〉，月所生也。」師古曰：「日域，日初出之處也。厭音一涉反。」","sentenceOrder":76},
  {"id":"s_work_han_thu_101_77","chapterId":"ch_work_han_thu_101","textTraditional":"〔一０〕師古曰：「禦，止也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_101_78","chapterId":"ch_work_han_thu_101","textTraditional":"〔一一〕張晏曰：「從者見仿佛，委釋迴旋。」師古曰：「車不安軔，未及止也。日未靡旃，不移景也。仿佛讀曰髣彿。骩，古委字也。屬音之欲反。還讀曰旋也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_101_79","chapterId":"ch_work_han_thu_101","textTraditional":"〔一二〕師古曰：「虞與娛同，合韻音牛具反。」","sentenceOrder":79},
  {"id":"s_work_han_thu_101_80","chapterId":"ch_work_han_thu_101","textTraditional":"〔一三〕師古曰：「耰，摩田之器也。音憂。」","sentenceOrder":80},
  {"id":"s_work_han_thu_101_81","chapterId":"ch_work_han_thu_101","textTraditional":"〔一四〕師古曰：「已解於上也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_101_82","chapterId":"ch_work_han_thu_101","textTraditional":"〔一五〕師古曰：「易，合韻音弋赤反。」","sentenceOrder":82},
  {"id":"s_work_han_thu_101_83","chapterId":"ch_work_han_thu_101","textTraditional":"〔一六〕孟康曰：「碣磍，刻猛獸為之，故其形碣磍而盛怒也。」師古曰：「鞀，古鼗字。鞀，小鼓也。碣音一轄反。磍音轄。」","sentenceOrder":83},
  {"id":"s_work_han_thu_101_84","chapterId":"ch_work_han_thu_101","textTraditional":"〔一七〕師古曰：「拮隔，擊考也。鳴球，玉磬也。掉，搖也，搖身而舞也。一曰：拮隔，彈鼓也。鳴球，以玉飾琴瑟也。拮音居黠反。球音求，又音虯。掉音徒釣反。」","sentenceOrder":84},
  {"id":"s_work_han_thu_101_85","chapterId":"ch_work_han_thu_101","textTraditional":"〔一八〕張晏曰：「允，信也。鑠，美也。言酌信義以當酒，帥禮樂以為肴也。」師古曰：「小雅車攻之詩曰『允矣君子，展也大成』，周頌酌之詩曰『於鑠王師』，小雅桑扈之詩曰『君子樂胥』，故引之為言也。胥音先呂反。」","sentenceOrder":85},
  {"id":"s_work_han_thu_101_86","chapterId":"ch_work_han_thu_101","textTraditional":"〔一九〕師古曰：「大雅思齊之詩曰『雍雍在宮，肅肅在廟』，小雅桑扈之詩曰『受天之祜』。祜，福也，音戶。」","sentenceOrder":86},
  {"id":"s_work_han_thu_101_87","chapterId":"ch_work_han_thu_101","textTraditional":"〔二０〕師古曰：「大雅旱麓之詩曰『愷弟君子，神所勞矣』。勞謂勞來之，猶言勸勉也，故雄引之云。勞音郎到反。」","sentenceOrder":87},
  {"id":"s_work_han_thu_101_88","chapterId":"ch_work_han_thu_101","textTraditional":"〔二一〕師古曰：「元，善也。符，瑞也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_101_89","chapterId":"ch_work_han_thu_101","textTraditional":"〔二二〕師古曰：「離婁，古明目者。一號離朱。燭，照也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_101_90","chapterId":"ch_work_han_thu_101","textTraditional":"言未卒，墨客降席再拜稽首曰：「大哉體乎！允非小子之所能及也。〔一〕乃今日發矇，廓然已昭矣！」","sentenceOrder":90},
  {"id":"s_work_han_thu_101_91","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「允，信也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_101_92","chapterId":"ch_work_han_thu_101","textTraditional":"哀帝時丁、傅、董賢用事，諸附離之者或起家至二千石。〔一〕時雄方草太玄，有以自守，泊如也。〔二〕或謿雄以玄尚白，〔三〕而雄解之，號曰解謿。其辭曰：","sentenceOrder":92},
  {"id":"s_work_han_thu_101_93","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「離，著也，音麗。」","sentenceOrder":93},
  {"id":"s_work_han_thu_101_94","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「泊，安靜也，音步各反。」","sentenceOrder":94},
  {"id":"s_work_han_thu_101_95","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　師古曰：「玄，黑色也。言雄作之不成，其色猶白，故無祿位也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_101_96","chapterId":"ch_work_han_thu_101","textTraditional":"客謿揚子曰：「吾聞上世之士，人綱人紀，〔一〕不生則已，生則上尊人君，下榮父母，析人之圭，儋人之爵，〔二〕懷人之符，分人之祿，紆青拕紫，朱丹其轂。〔三〕今子幸得遭明盛之世，處不諱之朝，與群賢同行，〔四〕歷金門上玉堂有日矣，〔五〕曾不能畫一奇，出一策，上說人主，下談公卿。目如燿星，舌如電光，壹從壹衡，論者莫當，〔六〕顧而作太玄五千文，〔七〕支葉扶疏，獨說十餘萬言，〔八〕深者入黃泉，高者出蒼天，大者含元氣，纖者入無倫，〔九〕然而位不過侍郎，擢纔給事黃門。〔一０〕意者玄得毋尚白乎？何為官之拓落也？」〔一一〕","sentenceOrder":96},
  {"id":"s_work_han_thu_101_97","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「為眾人之綱紀也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_101_98","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「析亦分也。儋，荷負也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_101_99","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　師古曰：「青紫謂綬之色也。紆，縈也。拕，曳也。拕音吐賀反，又音徒可反。」","sentenceOrder":99},
  {"id":"s_work_han_thu_101_100","chapterId":"ch_work_han_thu_101","textTraditional":"〔四〕　師古曰：「同行謂同行列。」","sentenceOrder":100},
  {"id":"s_work_han_thu_101_101","chapterId":"ch_work_han_thu_101","textTraditional":"〔五〕　應劭曰：「金門，金馬門也。」晉灼曰：「黃圖有大玉堂、小玉堂殿也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_101_102","chapterId":"ch_work_han_thu_101","textTraditional":"〔六〕　師古曰：「從音子容反。」","sentenceOrder":102},
  {"id":"s_work_han_thu_101_103","chapterId":"ch_work_han_thu_101","textTraditional":"〔七〕　師古曰：「顧，反也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_101_104","chapterId":"ch_work_han_thu_101","textTraditional":"〔八〕　師古曰：「扶疏，分布也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_101_105","chapterId":"ch_work_han_thu_101","textTraditional":"〔九〕　師古曰：「纖微之甚，無等倫。」","sentenceOrder":105},
  {"id":"s_work_han_thu_101_106","chapterId":"ch_work_han_thu_101","textTraditional":"〔一０〕師古曰：「纔，淺也，言僅得之也。纔音才。」","sentenceOrder":106},
  {"id":"s_work_han_thu_101_107","chapterId":"ch_work_han_thu_101","textTraditional":"〔一一〕師古曰：「拓落，不耦也。拓音託。」","sentenceOrder":107},
  {"id":"s_work_han_thu_101_108","chapterId":"ch_work_han_thu_101","textTraditional":"揚子笑而應之曰：「客徒欲朱丹吾轂，不知一跌將赤吾之族也！〔一〕往者周罔解結，群鹿爭逸，〔二〕離為十二，合為六七，〔三〕四分五剖，並為戰國。〔四〕士無常君，國亡定臣，得士者富，失士者貧，矯翼厲翮，恣意所存，〔五〕故士或自盛以橐，或鑿坏之遁。〔六〕是故騶衍以頡亢而取世資，〔七〕孟軻雖連蹇，猶為萬乘師。〔八〕","sentenceOrder":108},
  {"id":"s_work_han_thu_101_109","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「跌，足失厝也。見誅殺者必流血，故云赤族。跌音徒結反。」","sentenceOrder":109},
  {"id":"s_work_han_thu_101_110","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「謂戰國時諸侯也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_101_111","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　師古曰：「十二，謂魯、衛、齊、楚、宋、鄭、燕、秦、韓、趙、魏、中山也。六七者，齊、趙、韓、魏、燕、楚六國及秦為七也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_101_112","chapterId":"ch_work_han_thu_101","textTraditional":"〔四〕　晉灼曰：「道其分離之意，四分則交五而裂如田字。」","sentenceOrder":112},
  {"id":"s_work_han_thu_101_113","chapterId":"ch_work_han_thu_101","textTraditional":"〔五〕　師古曰：「言來去如鳥之飛，各任所息也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_101_114","chapterId":"ch_work_han_thu_101","textTraditional":"〔六〕　應劭曰：「自盛以橐，謂范雎也。鑿坏，謂顏闔也。魯君聞顏闔賢，欲以為相，使者往聘，因鑿後垣而亡。坏，壁也。」蘇林曰：「坏音陪。」師古曰：「又音普回反。」","sentenceOrder":114},
  {"id":"s_work_han_thu_101_115","chapterId":"ch_work_han_thu_101","textTraditional":"〔七〕　應劭曰：「衍，齊人也。著書所言皆天事，故齊人曰『談天衍』。遊諸侯，所言則以為迂闊遠於事情，然終不屈。嘗仕於齊，位至卿。」師古曰：「頡亢，上下不定也。頡音下結反。亢音湖浪反。」","sentenceOrder":115},
  {"id":"s_work_han_thu_101_116","chapterId":"ch_work_han_thu_101","textTraditional":"〔八〕　張晏曰：「連蹇，難也，言值世之屯難也。」師古曰：「連音輦。」","sentenceOrder":116},
  {"id":"s_work_han_thu_101_117","chapterId":"ch_work_han_thu_101","textTraditional":"「今大漢左東海，右渠搜，前番禺，後陶塗。〔一〕東南一尉，〔二〕西北一候。〔三〕徽以糾墨，製以質鈇，〔四〕散以禮樂，風以詩書，〔五〕曠以歲月，結以倚廬。〔六〕天下之士，雷動雲合，魚鱗雜襲，咸營于八區，〔七〕家家自以為稷契，人人自以為咎繇，戴縰垂纓而談者皆擬於阿衡，〔八〕五尺童子羞比晏嬰與夷吾；〔九〕當塗者入青雲，失路者委溝渠，旦握權則為卿相，夕失勢則為匹夫；譬若江湖之雀，勃解之鳥，乘雁集不為之多，雙鳧飛不為之少。〔一０〕昔三仁去而殷虛，〔一一〕二老歸而周熾，〔一二〕子胥死而吳亡，種、蠡存而粵伯，〔一三〕五羖入而秦喜，樂毅出而燕懼，〔一四〕范雎以折摺而危穰侯，〔一五〕蔡澤雖噤吟而笑唐舉〔一六〕。故當其有事也，非蕭、曹、子房、平、勃、樊、霍則不能安；當其亡事也，章句之徒相與坐而守之，亦亡所患。〔一七〕故世亂，則聖哲馳騖而不足；世治，則庸夫高枕而有餘。","sentenceOrder":117},
  {"id":"s_work_han_thu_101_118","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　如淳曰：「小國也。」師古曰：「騊駼馬出北海上。今此云後陶塗，則是北方國名也。本國出馬，因以為名。今書本陶字有作椒者，流俗所改。」","sentenceOrder":118},
  {"id":"s_work_han_thu_101_119","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　孟康曰：「會稽東部都尉也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_101_120","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　孟康曰：「敦煌玉門關候也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_101_121","chapterId":"ch_work_han_thu_101","textTraditional":"〔四〕　師古曰：「言有罪者則係於徽墨，尤惡者則斬以鈇質也。徽、糾、墨，皆繩也。質，鍖也。鈇，莝刃也，音膚。鍖音竹林反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_101_122","chapterId":"ch_work_han_thu_101","textTraditional":"〔五〕　師古曰：「風，化也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_101_123","chapterId":"ch_work_han_thu_101","textTraditional":"〔六〕　孟康曰：「在倚廬行服三年也。」應劭曰：「漢律以不為親行三年服不得選舉。」師古曰：「倚廬，倚牆至地而為之，無楣柱。倚音於綺反。」","sentenceOrder":123},
  {"id":"s_work_han_thu_101_124","chapterId":"ch_work_han_thu_101","textTraditional":"〔七〕　師古曰：「八區，八方也。」","sentenceOrder":124},
  {"id":"s_work_han_thu_101_125","chapterId":"ch_work_han_thu_101","textTraditional":"〔八〕　師古曰：「縰，韜髮者也，音山爾反。」","sentenceOrder":125},
  {"id":"s_work_han_thu_101_126","chapterId":"ch_work_han_thu_101","textTraditional":"〔九〕　師古曰：「夷吾，管仲也。羞比之也，以其不為王者之佐。」","sentenceOrder":126},
  {"id":"s_work_han_thu_101_127","chapterId":"ch_work_han_thu_101","textTraditional":"〔一０〕應劭曰：「乘鴈，四鴈也。」師古曰：「雀字或作厓。鳥字或作島。島，海中山也，其義兩通。乘音食證反。」","sentenceOrder":127},
  {"id":"s_work_han_thu_101_128","chapterId":"ch_work_han_thu_101","textTraditional":"〔一一〕師古曰：「論語稱『微子去之，箕子為之奴，比干諫而死』。孔子曰：『殷有三仁焉。』虛，空也。一曰虛讀曰墟，言其亡國為丘墟。」","sentenceOrder":128},
  {"id":"s_work_han_thu_101_129","chapterId":"ch_work_han_thu_101","textTraditional":"〔一二〕應劭曰：「二老，伯夷、太公也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_101_130","chapterId":"ch_work_han_thu_101","textTraditional":"〔一三〕師古曰：「伯讀曰霸。」","sentenceOrder":130},
  {"id":"s_work_han_thu_101_131","chapterId":"ch_work_han_thu_101","textTraditional":"〔一四〕師古曰：「五羖謂百里奚也。買以羖羊之皮五，故稱五羖也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_101_132","chapterId":"ch_work_han_thu_101","textTraditional":"〔一五〕晉灼曰：「摺，古拉字也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_101_133","chapterId":"ch_work_han_thu_101","textTraditional":"〔一六〕師古曰：「噤吟，顉頤之貌。澤從唐舉相，謂之曰：『聖人不相，殆先生乎！』澤曰：『吾自知富貴。』噤音鉅錦反。吟音魚錦反。舉，合韻音居御反。」","sentenceOrder":133},
  {"id":"s_work_han_thu_101_134","chapterId":"ch_work_han_thu_101","textTraditional":"〔一七〕師古曰：「章句小儒也。患，合韻音胡關反。」","sentenceOrder":134},
  {"id":"s_work_han_thu_101_135","chapterId":"ch_work_han_thu_101","textTraditional":"「夫上世之士，或解縛而相，〔一〕或釋褐而傅；〔二〕或倚夷門而笑，〔三〕或橫江潭而漁；〔四〕或七十說而不遇，〔五〕或立談間而封侯；〔六〕或枉千乘於陋巷，〔七〕或擁帚彗而先驅。〔八〕是以士頗得信其舌而奮其筆，〔九〕窒隙蹈瑕而無所詘也〔一０〕。當今縣令不請士，郡守不迎師，群卿不揖客，將相不俛眉〔一一〕；言奇者見疑，行殊者得辟，〔一二〕是以欲談者宛舌而固聲，欲行者擬足而投跡。〔一三〕鄉使上世之士處虖今，〔一四〕策非甲科，行非孝廉，舉非方正，獨可抗疏，時道是非，〔一五〕高得待詔，下觸聞罷，〔一六〕又安得青紫？","sentenceOrder":135},
  {"id":"s_work_han_thu_101_136","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　孟康曰：「管仲也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_101_137","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　孟康曰：「甯戚也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_101_138","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　應劭曰：「侯嬴也。為夷門卒，秦伐趙，趙求救，無忌將十餘人往辭嬴，嬴無所戒。更還，嬴笑之，以謀告無忌也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_101_139","chapterId":"ch_work_han_thu_101","textTraditional":"〔四〕　（師古）〔服虔〕曰：「漁父也。」師古曰：「江潭而漁，潭音尋，漁，合韻音牛助反。」","sentenceOrder":139},
  {"id":"s_work_han_thu_101_140","chapterId":"ch_work_han_thu_101","textTraditional":"〔五〕　應劭曰：「孔丘也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_101_141","chapterId":"ch_work_han_thu_101","textTraditional":"〔六〕　服虔曰：「薛公也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_101_142","chapterId":"ch_work_han_thu_101","textTraditional":"〔七〕　應劭曰：「齊有小臣稷，桓公一日三至而不得見，從者曰：『可以止矣！』桓公曰：『士之傲爵祿者，固輕其主，主傲霸王者亦輕其士，縱彼傲爵祿者，吾庸敢傲霸王乎！』遂見之。」","sentenceOrder":142},
  {"id":"s_work_han_thu_101_143","chapterId":"ch_work_han_thu_101","textTraditional":"〔八〕　應劭曰：「鄒衍之燕，昭王郊迎，擁彗為之先驅也。」師古曰：「彗亦以掃者也，音似歲反。」","sentenceOrder":143},
  {"id":"s_work_han_thu_101_144","chapterId":"ch_work_han_thu_101","textTraditional":"〔九〕　師古曰：「信讀曰申。」","sentenceOrder":144},
  {"id":"s_work_han_thu_101_145","chapterId":"ch_work_han_thu_101","textTraditional":"〔一０〕李奇曰：「君臣上下，有釁罅瑕隙乖離之漸，則可抵而取也。」師古曰：「窒，窒塞也。罅音呼駕反。」","sentenceOrder":145},
  {"id":"s_work_han_thu_101_146","chapterId":"ch_work_han_thu_101","textTraditional":"〔一一〕師古曰：「自高抗也。俛，低也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_101_147","chapterId":"ch_work_han_thu_101","textTraditional":"〔一二〕師古曰：「辟，罪法。」","sentenceOrder":147},
  {"id":"s_work_han_thu_101_148","chapterId":"ch_work_han_thu_101","textTraditional":"〔一三〕師古曰：「宛，屈也。固，閉也。擬，疑也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_101_149","chapterId":"ch_work_han_thu_101","textTraditional":"〔一四〕師古曰：「鄉讀曰嚮。」","sentenceOrder":149},
  {"id":"s_work_han_thu_101_150","chapterId":"ch_work_han_thu_101","textTraditional":"〔一五〕師古曰：「抗，舉也，謂上之也。疏者，疏條其事而言之。疏音所據反。」","sentenceOrder":150},
  {"id":"s_work_han_thu_101_151","chapterId":"ch_work_han_thu_101","textTraditional":"〔一六〕師古曰：「報聞而罷之。」","sentenceOrder":151},
  {"id":"s_work_han_thu_101_152","chapterId":"ch_work_han_thu_101","textTraditional":"「且吾聞之，炎炎者滅，隆隆者絕；觀雷觀火，為盈為實，天收其聲，地藏其熱。〔一〕高明之家，鬼瞰其室。〔二〕攫挐者亡，默默者存；〔三〕位極者宗危，自守者身全。是故知玄知默，守道之極；爰清爰靜，游神之廷；〔四〕惟寂惟寞，守德之宅。世異事變，人道不殊，彼我易時，未知何如。〔五〕今子乃以鴟梟而笑鳳皇，執蝘蜓而謿龜龍，〔六〕不亦病乎！子徒笑我玄之尚白，吾亦笑子之病甚，不遭臾跗、扁鵲，〔七〕悲夫！」","sentenceOrder":152},
  {"id":"s_work_han_thu_101_153","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「炎炎，火光也。隆隆，雷聲也。人之觀火聽雷，謂其盈實，終以天收雷聲，地藏火熱，則為虛無。言極盛者亦滅亡也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_101_154","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　李奇曰：「鬼神害盈而福謙也。」師古曰：「瞰，視也。音口濫反。」","sentenceOrder":154},
  {"id":"s_work_han_thu_101_155","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　師古曰：「攫挐，妄有搏執牽引也。挐音女居反。」","sentenceOrder":155},
  {"id":"s_work_han_thu_101_156","chapterId":"ch_work_han_thu_101","textTraditional":"〔四〕　師古曰：「靜，合韻音才性反。」","sentenceOrder":156},
  {"id":"s_work_han_thu_101_157","chapterId":"ch_work_han_thu_101","textTraditional":"〔五〕　李奇曰：「或能勝之。」","sentenceOrder":157},
  {"id":"s_work_han_thu_101_158","chapterId":"ch_work_han_thu_101","textTraditional":"〔六〕　師古曰：「蝘蜓，蜥蜴也。蝘音烏典反。蜓音殄。」","sentenceOrder":158},
  {"id":"s_work_han_thu_101_159","chapterId":"ch_work_han_thu_101","textTraditional":"〔七〕　師古曰：「二人皆古之良醫也。跗音甫無反。」","sentenceOrder":159},
  {"id":"s_work_han_thu_101_160","chapterId":"ch_work_han_thu_101","textTraditional":"客曰：「然則靡玄無所成名乎？〔一〕范、蔡以下何必玄哉？」","sentenceOrder":160},
  {"id":"s_work_han_thu_101_161","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「靡亦無。」","sentenceOrder":161},
  {"id":"s_work_han_thu_101_162","chapterId":"ch_work_han_thu_101","textTraditional":"揚子曰：「范雎，魏之亡命也，折脅拉髂，免於徽索，〔一〕翕肩蹈背，扶服入橐，〔二〕激卬萬乘之主，〔三〕界涇陽抵穰侯而代之，〔四〕當也。〔五〕蔡澤，山東之匹夫也，顉頤折頞，涕涶流沫，〔六〕西揖彊秦之相，搤其咽，炕其氣，附其背而奪其位〔七〕，時也。〔八〕天下已定，金革已平，都於雒陽，婁敬委輅脫輓，掉三寸之舌，〔九〕建不拔之策，舉中國徙之長安，〔一０〕適也。〔一一〕五帝垂典，三王傳禮，百世不易，叔孫通起於枹鼓之間〔一二〕，解甲投戈，遂作君臣之儀，得也。〔一三〕甫刑靡敝，秦法酷烈，〔一四〕聖漢權制，而蕭何造律，宜也。〔一五〕故有造蕭何律於唐虞之世，則誖矣；〔一六〕有作叔孫通儀於夏殷之時，則惑矣；有建婁敬之策於成周之世，則繆矣；有談范、蔡之說於金、張、許、史之間，則狂矣。〔夫〕蕭規曹隨，〔一七〕留侯畫策，陳平出奇，功若泰山，嚮若阺隤，〔一八〕唯其人之贍知哉，亦會其時之可為也。〔一九〕故為可為於可為之時，則從；為不可為於不可為之時；則凶。夫藺先生收功於章臺，〔二０〕四皓采榮於南山，〔二一〕公孫創業於金馬，〔二二〕票騎發跡於祁連，〔二三〕司馬長卿竊訾於卓氏，東方朔割（名）〔炙〕於細君。〔二四〕僕誠不能與此數公者並，故默然獨守吾太玄。」","sentenceOrder":162},
  {"id":"s_work_han_thu_101_163","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「髂，骨也。徽，繩也。髂音格。」","sentenceOrder":163},
  {"id":"s_work_han_thu_101_164","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「翕，斂也。服音蒲北反。」","sentenceOrder":164},
  {"id":"s_work_han_thu_101_165","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　如淳曰：「卬，怒也。言秦安得王，獨太后穰侯耳。」師古曰：「卬讀曰仰。」","sentenceOrder":165},
  {"id":"s_work_han_thu_101_166","chapterId":"ch_work_han_thu_101","textTraditional":"〔四〕　蘇林曰：「抵音紙。界，間其兄弟使疏。」應劭曰：「涇陽，秦昭王弟，貴用事也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_101_167","chapterId":"ch_work_han_thu_101","textTraditional":"〔五〕　師古曰：「言當其際。」","sentenceOrder":167},
  {"id":"s_work_han_thu_101_168","chapterId":"ch_work_han_thu_101","textTraditional":"〔六〕　師古曰：「顉，曲頤也，音欽。」","sentenceOrder":168},
  {"id":"s_work_han_thu_101_169","chapterId":"ch_work_han_thu_101","textTraditional":"〔七〕　張晏曰：「蔡澤說范雎以功成身退，禍福之機。適值雎有間於王，因薦以自代。」師古曰：「搤謂急持之。咽，頸也。炕，絕也。咽音一千反。炕音抗。」","sentenceOrder":169},
  {"id":"s_work_han_thu_101_170","chapterId":"ch_work_han_thu_101","textTraditional":"〔八〕　師古曰：「遇其時。」","sentenceOrder":170},
  {"id":"s_work_han_thu_101_171","chapterId":"ch_work_han_thu_101","textTraditional":"〔九〕　師古曰：「輅音胡格反。輓音晚。掉音徒釣反。解在劉敬傳。」","sentenceOrder":171},
  {"id":"s_work_han_thu_101_172","chapterId":"ch_work_han_thu_101","textTraditional":"〔一０〕師古曰：「不拔，謂其堅固不拔也。中國謂京師。」","sentenceOrder":172},
  {"id":"s_work_han_thu_101_173","chapterId":"ch_work_han_thu_101","textTraditional":"〔一一〕師古曰：「中其適。」","sentenceOrder":173},
  {"id":"s_work_han_thu_101_174","chapterId":"ch_work_han_thu_101","textTraditional":"〔一二〕師古曰：「枹音孚。」","sentenceOrder":174},
  {"id":"s_work_han_thu_101_175","chapterId":"ch_work_han_thu_101","textTraditional":"〔一三〕師古曰：「得其所。」","sentenceOrder":175},
  {"id":"s_work_han_thu_101_176","chapterId":"ch_work_han_thu_101","textTraditional":"〔一四〕師古曰：「靡，散也，音縻。」","sentenceOrder":176},
  {"id":"s_work_han_thu_101_177","chapterId":"ch_work_han_thu_101","textTraditional":"〔一五〕師古曰：「合其宜。」","sentenceOrder":177},
  {"id":"s_work_han_thu_101_178","chapterId":"ch_work_han_thu_101","textTraditional":"〔一六〕師古曰：「誖，乖也，音布內反。」","sentenceOrder":178},
  {"id":"s_work_han_thu_101_179","chapterId":"ch_work_han_thu_101","textTraditional":"〔一七〕師古曰：「隨，從也。言蕭何始作規模，曹參因而從之。」","sentenceOrder":179},
  {"id":"s_work_han_thu_101_180","chapterId":"ch_work_han_thu_101","textTraditional":"〔一八〕師古曰：「阺音氐。巴蜀人名山旁堆欲墮落曰阺。應劭以為天水隴氐，失之矣。氐音丁禮反。」","sentenceOrder":180},
  {"id":"s_work_han_thu_101_181","chapterId":"ch_work_han_thu_101","textTraditional":"〔一九〕師古曰：「非唯其人贍知，乃會時之可為也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_101_182","chapterId":"ch_work_han_thu_101","textTraditional":"〔二０〕孟康曰：「秦昭王、趙成王飲於此臺，藺相如前折昭王也。」晉灼曰：「相如獻璧於此臺。」師古曰：「晉說是也，謂齎璧入秦，秦不與趙地，相如詭取其璧，使人間以歸趙也。史記始皇本紀云章臺在渭南，而秦、趙會飲乃在黽池，非章臺也，孟說失之。」","sentenceOrder":182},
  {"id":"s_work_han_thu_101_183","chapterId":"ch_work_han_thu_101","textTraditional":"〔二一〕師古曰：「榮者，謂聲名也。一曰，榮謂草木之英，采取以充食。」","sentenceOrder":183},
  {"id":"s_work_han_thu_101_184","chapterId":"ch_work_han_thu_101","textTraditional":"〔二二〕孟康曰：「公孫弘對策金馬門。」","sentenceOrder":184},
  {"id":"s_work_han_thu_101_185","chapterId":"ch_work_han_thu_101","textTraditional":"〔二三〕師古曰：「霍去病也。祁音止夷反。」","sentenceOrder":185},
  {"id":"s_work_han_thu_101_186","chapterId":"ch_work_han_thu_101","textTraditional":"〔二四〕師古曰：「割，損也。言以肉歸遺細君，是損割其名。」","sentenceOrder":186},
  {"id":"s_work_han_thu_101_187","chapterId":"ch_work_han_thu_101","textTraditional":"雄以為賦者，將以風也，〔一〕必推類而言，極麗靡之辭，閎侈鉅衍，競於使人不能加也，〔二〕既乃歸之於正，然覽者已過矣〔三〕。往時武帝好神仙，相如上大人賦，欲以風，〔四〕帝反縹縹有陵雲之志。〔五〕繇是言之，賦勸而不止，明矣。〔六〕又頗似俳優淳于髡、優孟之徒，〔七〕非法度所存，賢人君子詩賦之正也，於是輟不復為。〔八〕而大潭思渾天，〔九〕參摹而四分之，〔一０〕極於八十一。旁則三摹九据，〔一一〕極之七百二十九贊，亦自然之道也。故觀易者，見其卦而名之；觀玄者，數其畫而定之。玄首四重者，非卦也，數也。其用自天元推一晝一夜陰陽數度律曆之紀，九九大運，與天終始。故玄三方、九州、二十七部、八十一家、二百四十三表、七百二十九贊，分為三卷，曰一二三，與泰初歷相應，亦有顓頊之曆焉。〈扌筮〉之以三策，〔一二〕關之以休咎，絣之以象類，〔一三〕播之以人事，〔一四〕文之以五行，擬之以道德仁義禮知。無主無名，要合五經，苟非其事，文不虛生。為其泰曼漶而不可知，〔一五〕故有首、衝、錯、測、攡、瑩、數、文、掜、圖、告十一篇，〔一六〕皆以解剝玄體，離散其文，章句尚不存焉。〔一七〕玄文多，故不著；觀之者難知，學之者難成。客有難玄大深，眾人之不好也，雄解之，號曰解難。其辭曰：","sentenceOrder":187},
  {"id":"s_work_han_thu_101_188","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「風讀曰諷，下以諷刺上也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_101_189","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「言專為廣大之言。」","sentenceOrder":189},
  {"id":"s_work_han_thu_101_190","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　師古曰：「言其末篇反從之正道，故觀覽之者但得浮華，而無益於諷諫也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_101_191","chapterId":"ch_work_han_thu_101","textTraditional":"〔四〕　師古曰：「風讀曰諷。」","sentenceOrder":191},
  {"id":"s_work_han_thu_101_192","chapterId":"ch_work_han_thu_101","textTraditional":"〔五〕　師古曰：「縹音匹昭反。」","sentenceOrder":192},
  {"id":"s_work_han_thu_101_193","chapterId":"ch_work_han_thu_101","textTraditional":"〔六〕　師古曰：「繇讀與由同。」","sentenceOrder":193},
  {"id":"s_work_han_thu_101_194","chapterId":"ch_work_han_thu_101","textTraditional":"〔七〕　師古曰：「髡、孟皆滑稽。」","sentenceOrder":194},
  {"id":"s_work_han_thu_101_195","chapterId":"ch_work_han_thu_101","textTraditional":"〔八〕　師古曰：「輟，止也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_101_196","chapterId":"ch_work_han_thu_101","textTraditional":"〔九〕　師古曰：「潭，深也。渾天，天象也。渾音胡昆反。」","sentenceOrder":196},
  {"id":"s_work_han_thu_101_197","chapterId":"ch_work_han_thu_101","textTraditional":"〔一０〕蘇林曰：「三（拆）〔析〕而四分天之宿度甲乙也。」","sentenceOrder":197},
  {"id":"s_work_han_thu_101_198","chapterId":"ch_work_han_thu_101","textTraditional":"〔一一〕晉灼曰：「据，今據字也。據猶位也，處也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_101_199","chapterId":"ch_work_han_thu_101","textTraditional":"〔一二〕蘇林曰：「三三而分之。」師古曰：「〈扌筮〉音食列反。」","sentenceOrder":199},
  {"id":"s_work_han_thu_101_200","chapterId":"ch_work_han_thu_101","textTraditional":"〔一三〕晉灼曰：「絣，雜也。」師古曰：「絣，併也。音并。」","sentenceOrder":200},
  {"id":"s_work_han_thu_101_201","chapterId":"ch_work_han_thu_101","textTraditional":"〔一四〕師古曰：「播，布也。」","sentenceOrder":201},
  {"id":"s_work_han_thu_101_202","chapterId":"ch_work_han_thu_101","textTraditional":"〔一五〕張揖曰：「曼音滿。漶音緩。」師古曰：「曼漶，不分別貌，猶言濛鴻也。曼音莫幹反。漶音奐。」","sentenceOrder":202},
  {"id":"s_work_han_thu_101_203","chapterId":"ch_work_han_thu_101","textTraditional":"〔一六〕晉灼曰：「攡音離。」服虔曰：「掜音睨。」師古曰：「攡音摛。」","sentenceOrder":203},
  {"id":"s_work_han_thu_101_204","chapterId":"ch_work_han_thu_101","textTraditional":"〔一七〕師古曰：「玄中之文雖有章句，其旨深妙，尚不能盡存，故解剝而離散也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_101_205","chapterId":"ch_work_han_thu_101","textTraditional":"客難揚子曰：「凡著書者，為眾人之所好也，美味期乎合口，工聲調於比耳。〔一〕今吾子乃抗辭幽說，閎意眇指，〔二〕獨馳騁於有亡之際，而陶冶大鑪，旁薄群生，〔三〕歷覽者茲年矣，而殊不寤。〔四〕亶費精神於此，而煩學者於彼，〔五〕譬畫者畫於無形，弦者放於無聲，殆不可乎？」〔六〕","sentenceOrder":205},
  {"id":"s_work_han_thu_101_206","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「比，和也，音頻二反。」","sentenceOrder":206},
  {"id":"s_work_han_thu_101_207","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「眇讀曰妙。」","sentenceOrder":207},
  {"id":"s_work_han_thu_101_208","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　師古曰：「旁薄猶言蕩薄也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_101_209","chapterId":"ch_work_han_thu_101","textTraditional":"〔四〕　師古曰：「茲，益也。茲年，言其久也。不寤，不曉其意。」","sentenceOrder":209},
  {"id":"s_work_han_thu_101_210","chapterId":"ch_work_han_thu_101","textTraditional":"〔五〕　師古曰：「亶讀曰但。」","sentenceOrder":210},
  {"id":"s_work_han_thu_101_211","chapterId":"ch_work_han_thu_101","textTraditional":"〔六〕　師古曰：「放，依也。殆，近也。放音甫往反。」","sentenceOrder":211},
  {"id":"s_work_han_thu_101_212","chapterId":"ch_work_han_thu_101","textTraditional":"揚子曰：「俞。〔一〕若夫閎言崇議，幽微之塗，蓋難與覽者同也。昔人有觀象於天，視度於地，察法於人者，天麗且彌，地普而深，〔二〕昔人之辭，乃玉乃金。〔三〕彼豈好為艱難哉？勢不得已也。〔四〕獨不見夫翠虯絳螭之將登虖天，〔五〕必聳身於倉梧之淵；不階浮雲，翼疾風，虛舉而上升，則不能撠膠葛，騰九閎。〔六〕日月之經不千里，則不能燭六合，燿八紘；〔七〕泰山之高不嶕嶢，則不能浡滃雲而散歊烝。〔八〕是以宓犧氏之作易也，〔九〕綿絡天地，經以八卦，文王附六爻，〔一０〕孔子錯其象而彖其辭，然後發天地之臧，定萬物之基。典謨之篇，雅頌之聲，不溫純深潤，則不足以揚鴻烈而章緝熙。〔一一〕蓋胥靡為宰，〔一二〕寂寞為尸〔一三〕；大味必淡，大音必希；〔一四〕大語叫叫，大道低回。〔一五〕是以聲之眇者不可同於眾人之耳，〔六〕形之美者不可棍於世俗之目，〔一七〕辭之衍者不可齊於庸人之聽。〔一八〕今夫弦者，高張急徽，追趨逐耆，則坐者不期而附矣；〔一九〕試為之施咸池，揄六莖，發（蕭）〔簫〕韶，詠九成，則莫有和也。〔二０〕是故鍾期死，伯牙絕弦破琴而不肯與眾鼓；〔二一〕獿人亡，則匠石輟斤而不敢妄斲。〔二二〕師曠之調鍾，俟知音者之在後也；〔二三〕孔子作春秋，幾君子之前睹也。〔二四〕老聃有遺言，貴知我者希，〔二五〕此非其操與！」〔二六〕","sentenceOrder":212},
  {"id":"s_work_han_thu_101_213","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「俞，然也。音踰。」","sentenceOrder":213},
  {"id":"s_work_han_thu_101_214","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「麗，著也，日月星辰之所著也。彌，廣也。普，遍也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_101_215","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　師古曰：「貞實美麗如金玉也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_101_216","chapterId":"ch_work_han_thu_101","textTraditional":"〔四〕　師古曰：「已，此也。」","sentenceOrder":216},
  {"id":"s_work_han_thu_101_217","chapterId":"ch_work_han_thu_101","textTraditional":"〔五〕　師古曰：「虯、螭，解並在前。」","sentenceOrder":217},
  {"id":"s_work_han_thu_101_218","chapterId":"ch_work_han_thu_101","textTraditional":"〔六〕　師古曰：「撠，挶也。膠葛，上清之氣也。騰，升也。九閎，九天之門。撠音戟。挶音居足反。」","sentenceOrder":218},
  {"id":"s_work_han_thu_101_219","chapterId":"ch_work_han_thu_101","textTraditional":"〔七〕　師古曰：「燭，照也。六合，謂天地四方。八紘，八方之綱維也。紘音宏。」","sentenceOrder":219},
  {"id":"s_work_han_thu_101_220","chapterId":"ch_work_han_thu_101","textTraditional":"〔八〕　師古曰：「嶕嶢，高貌也。浡滃，盛也。滃，雲氣貌。歊烝，氣上出也。嶕嶢音樵堯。浡音勃。滃音一孔反。歊音許昭反。」","sentenceOrder":220},
  {"id":"s_work_han_thu_101_221","chapterId":"ch_work_han_thu_101","textTraditional":"〔九〕　師古曰：「宓音伏。」","sentenceOrder":221},
  {"id":"s_work_han_thu_101_222","chapterId":"ch_work_han_thu_101","textTraditional":"〔一０〕　師古曰：「因而重之。」","sentenceOrder":222},
  {"id":"s_work_han_thu_101_223","chapterId":"ch_work_han_thu_101","textTraditional":"〔一一〕　師古曰：「造化鴻大也。烈，業也。緝熙，光明也。」","sentenceOrder":223},
  {"id":"s_work_han_thu_101_224","chapterId":"ch_work_han_thu_101","textTraditional":"〔一二〕　李奇曰：「造化之神，宰割萬物也。」張晏曰：「胥，相也。靡，無也。言相師以無為作宰者也。」","sentenceOrder":224},
  {"id":"s_work_han_thu_101_225","chapterId":"ch_work_han_thu_101","textTraditional":"〔一三〕　李奇曰：「道化以寂寞為主。」","sentenceOrder":225},
  {"id":"s_work_han_thu_101_226","chapterId":"ch_work_han_thu_101","textTraditional":"〔一四〕　師古曰：「淡謂無至味也，音徒濫反。」","sentenceOrder":226},
  {"id":"s_work_han_thu_101_227","chapterId":"ch_work_han_thu_101","textTraditional":"〔一五〕　師古曰：「叫叫，遠聲也。低回，紆衍也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_101_228","chapterId":"ch_work_han_thu_101","textTraditional":"〔一六〕　〔師古曰〕：「眇讀曰妙」。","sentenceOrder":228},
  {"id":"s_work_han_thu_101_229","chapterId":"ch_work_han_thu_101","textTraditional":"〔一七〕　師古曰：「棍亦同也，音胡本反。」","sentenceOrder":229},
  {"id":"s_work_han_thu_101_230","chapterId":"ch_work_han_thu_101","textTraditional":"〔一八〕　師古曰：「衍，旁廣也。」","sentenceOrder":230},
  {"id":"s_work_han_thu_101_231","chapterId":"ch_work_han_thu_101","textTraditional":"〔一九〕　師古曰：「徽，琴徽也，所以表發撫抑之處。追趨逐耆，隨所趨嚮愛嗜而追逐之也。趨讀曰趣。耆讀曰嗜。」","sentenceOrder":231},
  {"id":"s_work_han_thu_101_232","chapterId":"ch_work_han_thu_101","textTraditional":"〔二０〕　師古曰：「揄，引也。和，應也。揄音踰。和音胡臥反。」","sentenceOrder":232},
  {"id":"s_work_han_thu_101_233","chapterId":"ch_work_han_thu_101","textTraditional":"〔二一〕　師古曰：「解在司馬遷傳。」","sentenceOrder":233},
  {"id":"s_work_han_thu_101_234","chapterId":"ch_work_han_thu_101","textTraditional":"〔二二〕　服虔曰：「獿，古之善塗塈者也。施廣領大袖以仰塗，而領袖不汙。有小飛泥誤著其鼻，因令匠石揮斤而斲，知匠石之善斲，故敢使之也。」師古曰：「塈即今之仰泥也。獿，抆拭也，故謂塗者為獿人。獿音乃高反，又音乃回反。今書本獿字有作郢者，流俗改之。塈音許既反。」","sentenceOrder":234},
  {"id":"s_work_han_thu_101_235","chapterId":"ch_work_han_thu_101","textTraditional":"〔二三〕　應劭曰：「晉平公鍾，工者以為調矣，師曠曰：『臣竊聽之，知其不調也。』至於師涓，而果知鍾之不調。是師曠欲善調之鍾，為後世之有知音。」","sentenceOrder":235},
  {"id":"s_work_han_thu_101_236","chapterId":"ch_work_han_thu_101","textTraditional":"〔二四〕　師古曰：「幾讀曰冀。」","sentenceOrder":236},
  {"id":"s_work_han_thu_101_237","chapterId":"ch_work_han_thu_101","textTraditional":"〔二五〕　師古曰：「老子德經云：『知我者希，則我貴矣。』」","sentenceOrder":237},
  {"id":"s_work_han_thu_101_238","chapterId":"ch_work_han_thu_101","textTraditional":"〔二六〕　師古曰：「與讀曰歟。」","sentenceOrder":238},
  {"id":"s_work_han_thu_101_239","chapterId":"ch_work_han_thu_101","textTraditional":"雄見諸子各以其知舛馳，〔一〕大氐詆訾聖人，即為怪迂，析辯詭辭，以撓世事，〔二〕雖小辯，終破大道而或眾，使溺於所聞而不自知其非也。及太史公記六國，歷楚漢，（記）〔訖〕麟止，不與聖人同，是非頗謬於經。〔三〕故人時有問雄者，常用法應之，譔以為十三卷，〔四〕象論語，號曰法言。法言文多不著，獨著其目：〔五〕","sentenceOrder":239},
  {"id":"s_work_han_thu_101_240","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「舛，相背。」","sentenceOrder":240},
  {"id":"s_work_han_thu_101_241","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「大氐，大歸也。詆訾，毀也。迂，遠也。析，分也。詭，異也。言諸子之書，大歸皆非毀周孔之教，為巧辯異辭以攪亂時政也。訾音紫。迂音于。撓音火高反，其字從手也。」","sentenceOrder":241},
  {"id":"s_work_han_thu_101_242","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　師古曰：「頗音普我反。」","sentenceOrder":242},
  {"id":"s_work_han_thu_101_243","chapterId":"ch_work_han_thu_101","textTraditional":"〔四〕　師古曰：「譔與撰同。」","sentenceOrder":243},
  {"id":"s_work_han_thu_101_244","chapterId":"ch_work_han_thu_101","textTraditional":"〔五〕　師古曰：「雄（以）〔有〕序，著篇之意。」","sentenceOrder":244},
  {"id":"s_work_han_thu_101_245","chapterId":"ch_work_han_thu_101","textTraditional":"天降生民，倥侗顓蒙，〔一〕恣于情性，聰明不開，訓諸理。〔二〕譔學行第一。","sentenceOrder":245},
  {"id":"s_work_han_thu_101_246","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　鄭氏曰：「童蒙無所知也。」師古曰：「倥音空。侗音同。顓與專同。」","sentenceOrder":246},
  {"id":"s_work_han_thu_101_247","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「訓，告也。」","sentenceOrder":247},
  {"id":"s_work_han_thu_101_248","chapterId":"ch_work_han_thu_101","textTraditional":"降周迄孔，成于王道，〔一〕終後誕章乖離，諸子圖微〔二〕。譔吾子第二。","sentenceOrder":248},
  {"id":"s_work_han_thu_101_249","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「周，周公旦也。迄，至也。孔，孔子也。言自周公以降至於孔子，設教垂法，皆帝王之道。」","sentenceOrder":249},
  {"id":"s_work_han_thu_101_250","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「言其後澆末，虛誕益章，乖於七十弟子所謀微妙之言。」","sentenceOrder":250},
  {"id":"s_work_han_thu_101_251","chapterId":"ch_work_han_thu_101","textTraditional":"事有本真，陳施於億，〔一〕動不克咸，〔二〕本諸身。譔修身第三。","sentenceOrder":251},
  {"id":"s_work_han_thu_101_252","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　李奇曰：「布陳於億萬事也。」","sentenceOrder":252},
  {"id":"s_work_han_thu_101_253","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　李奇曰：「不能皆善也。」","sentenceOrder":253},
  {"id":"s_work_han_thu_101_254","chapterId":"ch_work_han_thu_101","textTraditional":"芒芒天道，在昔聖考，〔一〕過則失中，不及則不至，不可姦罔。〔二〕譔問道第四。","sentenceOrder":254},
  {"id":"s_work_han_thu_101_255","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　李奇曰：「聖人能成天道。」","sentenceOrder":255},
  {"id":"s_work_han_thu_101_256","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　蘇林曰：「罔，誣也。言不可作姦誣於聖道。」","sentenceOrder":256},
  {"id":"s_work_han_thu_101_257","chapterId":"ch_work_han_thu_101","textTraditional":"神心曶怳，經緯萬方，〔一〕事繫諸道德仁誼禮。譔問神第五。","sentenceOrder":257},
  {"id":"s_work_han_thu_101_258","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「曶讀與忽同。」","sentenceOrder":258},
  {"id":"s_work_han_thu_101_259","chapterId":"ch_work_han_thu_101","textTraditional":"明哲煌煌，旁燭亡疆，〔一〕遜于不虞，以保天命。〔二〕譔問明第六。","sentenceOrder":259},
  {"id":"s_work_han_thu_101_260","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「煌煌，盛貌也。燭，照也。無疆猶無極也。」","sentenceOrder":260},
  {"id":"s_work_han_thu_101_261","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　李奇曰：「常行遜順，備不虞。」","sentenceOrder":261},
  {"id":"s_work_han_thu_101_262","chapterId":"ch_work_han_thu_101","textTraditional":"假言周于天地，贊于神明，〔一〕幽弘橫廣，絕于邇言〔二〕。譔寡見第七。","sentenceOrder":262},
  {"id":"s_work_han_thu_101_263","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「假，至也。」","sentenceOrder":263},
  {"id":"s_work_han_thu_101_264","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　李奇曰：「理過近世人之言也。」","sentenceOrder":264},
  {"id":"s_work_han_thu_101_265","chapterId":"ch_work_han_thu_101","textTraditional":"聖人聰明淵懿，繼天測靈，冠于群倫，經諸范。〔一〕譔五百〔二〕第八。","sentenceOrder":265},
  {"id":"s_work_han_thu_101_266","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「經，常也。范，法也。」","sentenceOrder":266},
  {"id":"s_work_han_thu_101_267","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　鄧展曰：「五百歲聖人一出。」","sentenceOrder":267},
  {"id":"s_work_han_thu_101_268","chapterId":"ch_work_han_thu_101","textTraditional":"立政鼓眾，動化天下，莫上於中和，〔一〕中和之發，在於哲民情。〔二〕譔先知第九。","sentenceOrder":268},
  {"id":"s_work_han_thu_101_269","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　鄧展曰：「鼓亦動也。」","sentenceOrder":269},
  {"id":"s_work_han_thu_101_270","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「哲，知也。」","sentenceOrder":270},
  {"id":"s_work_han_thu_101_271","chapterId":"ch_work_han_thu_101","textTraditional":"仲尼以來，國君將相卿士名臣參差不齊，〔一〕壹槩諸聖。〔二〕譔重黎第十。","sentenceOrder":271},
  {"id":"s_work_han_thu_101_272","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「言志業不同也。參音初林反。」","sentenceOrder":272},
  {"id":"s_work_han_thu_101_273","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「〔一〕以聖人大道槩平。槩音工代反。」","sentenceOrder":273},
  {"id":"s_work_han_thu_101_274","chapterId":"ch_work_han_thu_101","textTraditional":"仲尼之後，訖于漢道，德行顏、閔，股肱蕭、曹，爰及名將尊卑之條，稱述品藻。〔一〕譔淵騫第十一。","sentenceOrder":274},
  {"id":"s_work_han_thu_101_275","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「品藻者，定其差品及文質。」","sentenceOrder":275},
  {"id":"s_work_han_thu_101_276","chapterId":"ch_work_han_thu_101","textTraditional":"君子純終領聞，〔一〕蠢迪檢押，〔二〕旁開聖則。譔君子第十二。","sentenceOrder":276},
  {"id":"s_work_han_thu_101_277","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　李奇曰：「領理所聞也。」師古曰：「純，善也。領，令也。聞，名也。言君子之道能善於終而不失令名。」","sentenceOrder":277},
  {"id":"s_work_han_thu_101_278","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「蠢，動也。迪，道也，由也。檢押猶隱括也。言動由檢押也。音狎。」","sentenceOrder":278},
  {"id":"s_work_han_thu_101_279","chapterId":"ch_work_han_thu_101","textTraditional":"孝莫大於寧親，寧親莫大於寧神，寧神莫大於四表之驩心。〔一〕譔孝至第十三。","sentenceOrder":279},
  {"id":"s_work_han_thu_101_280","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「寧，安也。言大孝之在於尊嚴袓考，安其神靈。所以得然者，以得四方之外驩心。」","sentenceOrder":280},
  {"id":"s_work_han_thu_101_281","chapterId":"ch_work_han_thu_101","textTraditional":"贊曰：雄之自序云爾。〔一〕初，雄年四十餘，自蜀來至游京師，大司馬車騎將軍王音奇其文雅，召以為門下史，薦雄待詔，歲餘，奏羽獵賦，除為郎，給事黃門，與王莽、劉歆並。哀帝之初，又與董賢同官。當成、哀、平間，莽、賢皆為三公，權傾人主，所薦莫不拔擢，而雄三世不徙官。及莽篡位，談說之士用符命稱功德獲封爵者甚眾，雄復不侯，以耆老久次轉為大夫，恬於勢利乃如是。〔二〕實好古而樂道，其意欲求文章成名於後世，以為經莫大於易，故作太玄；傳莫大於論語，作法言；史篇莫善於倉頡，作訓纂；箴莫善於虞箴，作州箴；〔三〕賦莫深於離騷，反而廣之；辭莫麗於相如，作四賦：皆斟酌其本，相與放依而馳騁云。〔四〕用心於內，不求於外，於時人皆曶之；〔五〕唯劉歆及范逡敬焉，〔六〕而桓譚以為絕倫。〔七〕","sentenceOrder":281},
  {"id":"s_work_han_thu_101_282","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「自法言目之前，皆是雄本自序之文也。」","sentenceOrder":282},
  {"id":"s_work_han_thu_101_283","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「恬，安也。」","sentenceOrder":283},
  {"id":"s_work_han_thu_101_284","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　晉灼曰：「九州之箴也。」","sentenceOrder":284},
  {"id":"s_work_han_thu_101_285","chapterId":"ch_work_han_thu_101","textTraditional":"〔四〕　師古曰：「放音甫往反。」","sentenceOrder":285},
  {"id":"s_work_han_thu_101_286","chapterId":"ch_work_han_thu_101","textTraditional":"〔五〕　師古曰：「曶與忽同，謂輕也。」","sentenceOrder":286},
  {"id":"s_work_han_thu_101_287","chapterId":"ch_work_han_thu_101","textTraditional":"〔六〕　師古曰：「逡音千旬反。」","sentenceOrder":287},
  {"id":"s_work_han_thu_101_288","chapterId":"ch_work_han_thu_101","textTraditional":"〔七〕　師古曰：「無比類。」","sentenceOrder":288},
  {"id":"s_work_han_thu_101_289","chapterId":"ch_work_han_thu_101","textTraditional":"王莽時，劉歆、甄豐皆為上公，莽既以符命自立，即位之後欲絕其原以神前事，而豐子尋、歆子棻復獻之。〔一〕莽誅豐父子，投棻四裔，辭所連及，便收不請。〔二〕時雄校書天祿閣上，治獄使者來，欲收雄，雄恐不能自免，乃從閣上自投下，幾死。〔三〕莽聞之曰：「雄素不與事，何故在此？」〔四〕間請問其故，〔五〕乃劉棻嘗從雄學作奇字，〔六〕雄不知情。〔七〕有詔勿問。然京師為之語曰：「惟寂寞，自投閣；爰清靜，作符命。」〔八〕","sentenceOrder":289},
  {"id":"s_work_han_thu_101_290","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「棻亦枌字也。音扶云反。」","sentenceOrder":290},
  {"id":"s_work_han_thu_101_291","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「不須奏請。」","sentenceOrder":291},
  {"id":"s_work_han_thu_101_292","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　師古曰：「幾音鉅依反。」","sentenceOrder":292},
  {"id":"s_work_han_thu_101_293","chapterId":"ch_work_han_thu_101","textTraditional":"〔四〕　師古曰：「與讀曰豫。」","sentenceOrder":293},
  {"id":"s_work_han_thu_101_294","chapterId":"ch_work_han_thu_101","textTraditional":"〔五〕　師古曰：「使人密問之。」","sentenceOrder":294},
  {"id":"s_work_han_thu_101_295","chapterId":"ch_work_han_thu_101","textTraditional":"〔六〕　師古曰：「古文之異者。」","sentenceOrder":295},
  {"id":"s_work_han_thu_101_296","chapterId":"ch_work_han_thu_101","textTraditional":"〔七〕　師古曰：「不知獻符命之事也。」","sentenceOrder":296},
  {"id":"s_work_han_thu_101_297","chapterId":"ch_work_han_thu_101","textTraditional":"〔八〕　師古曰：「以雄解謿之言譏之也。今流俗本云：『惟寂惟寞，自投於閣；爰清爰靜，作符命。』妄增之。」","sentenceOrder":297},
  {"id":"s_work_han_thu_101_298","chapterId":"ch_work_han_thu_101","textTraditional":"雄以病免，復召為大夫。家素貧，耆酒，〔一〕人希至其門。時有好事者載酒肴從游學，而鉅鹿侯芭常從雄居，〔二〕受其太玄、法言焉。劉歆亦嘗觀之，謂雄曰：「空自苦！今學者有祿利，然尚不能明易，又如玄何？〔三〕吾恐後人用覆醬瓿也。」〔四〕雄笑而不應。年七十一，天鳳五年卒，侯芭為起墳，喪之三年。","sentenceOrder":298},
  {"id":"s_work_han_thu_101_299","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「耆讀曰嗜。」","sentenceOrder":299},
  {"id":"s_work_han_thu_101_300","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　服虔曰：「芭音葩。」","sentenceOrder":300},
  {"id":"s_work_han_thu_101_301","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　師古曰：「言無奈之何。」","sentenceOrder":301},
  {"id":"s_work_han_thu_101_302","chapterId":"ch_work_han_thu_101","textTraditional":"〔四〕　師古曰：「瓿音部。小甖也。」","sentenceOrder":302},
  {"id":"s_work_han_thu_101_303","chapterId":"ch_work_han_thu_101","textTraditional":"時大司空王邑、納言嚴尤聞雄死，謂桓譚曰：「子嘗稱揚雄書，豈能傳於後世乎？」譚曰：「必傳。顧君與譚不及見也。〔一〕凡人賤近而貴遠，親見揚子雲祿位容貌不能動人，故輕其書。昔老聃著虛無之言兩篇，〔二〕薄仁義，非禮學，然後世好之者尚以為過於五經，自漢文景之君及司馬遷皆有是言。今揚子之書文義至深，而論不詭於聖人，〔三〕若使遭遇時君，更閱賢知，為所稱善，〔四〕則必度越諸子矣。」〔五〕諸儒或譏以為雄非聖人而作經，猶春秋吳楚之君僭號稱王，蓋誅絕之罪也。〔六〕自雄之沒至今四十餘年，其法言大行，而玄終不顯，然篇籍具存。","sentenceOrder":303},
  {"id":"s_work_han_thu_101_304","chapterId":"ch_work_han_thu_101","textTraditional":"〔一〕　師古曰：「顧，念也。」","sentenceOrder":304},
  {"id":"s_work_han_thu_101_305","chapterId":"ch_work_han_thu_101","textTraditional":"〔二〕　師古曰：「謂道德經也。」","sentenceOrder":305},
  {"id":"s_work_han_thu_101_306","chapterId":"ch_work_han_thu_101","textTraditional":"〔三〕　師古曰：「詭，違也。聖人謂周公、孔子。」","sentenceOrder":306},
  {"id":"s_work_han_thu_101_307","chapterId":"ch_work_han_thu_101","textTraditional":"〔四〕　師古曰：「更音工衡反。」","sentenceOrder":307},
  {"id":"s_work_han_thu_101_308","chapterId":"ch_work_han_thu_101","textTraditional":"〔五〕　師古曰：「度，過也。」","sentenceOrder":308},
  {"id":"s_work_han_thu_101_309","chapterId":"ch_work_han_thu_101","textTraditional":"〔六〕　師古曰：「絕謂無胤嗣也。」","sentenceOrder":309},
  {"id":"s_work_han_thu_101_310","chapterId":"ch_work_han_thu_101","textTraditional":"校勘記","sentenceOrder":310},
  {"id":"s_work_han_thu_101_311","chapterId":"ch_work_han_thu_101","textTraditional":"三五五七頁　五行　（從）〔縱〕禽獸其中，　景祐、汲古、殿、局本都作「縱」，文選同。","sentenceOrder":311},
  {"id":"s_work_han_thu_101_312","chapterId":"ch_work_han_thu_101","textTraditional":"三五五八頁　二行　椓（截）〔巀〕嶭而為弋，　殿本作「巀」，文選同。按注作「巀」，各本並同。","sentenceOrder":312},
  {"id":"s_work_han_thu_101_313","chapterId":"ch_work_han_thu_101","textTraditional":"三五五八頁一四行　豲音（完）〔桓〕。　景祐、殿本都作「桓」。","sentenceOrder":313},
  {"id":"s_work_han_thu_101_314","chapterId":"ch_work_han_thu_101","textTraditional":"三五五九頁一六行　所麾城（搟）〔摲〕邑，　景祐本作「摲」，注同，文選正文及注並同。","sentenceOrder":314},
  {"id":"s_work_han_thu_101_315","chapterId":"ch_work_han_thu_101","textTraditional":"三五六０頁　三行　鑿齒〔齒〕長五寸，　殿局本都重「齒」字，文選李注同。","sentenceOrder":315},
  {"id":"s_work_han_thu_101_316","chapterId":"ch_work_han_thu_101","textTraditional":"三五七０頁一三行　（師古）〔服虔〕曰：　殿本作「服虔」。","sentenceOrder":316},
  {"id":"s_work_han_thu_101_317","chapterId":"ch_work_han_thu_101","textTraditional":"三五七三頁　一行　〔夫〕蕭規曹隨，　景祐、殿本都有「夫」字，文選同。","sentenceOrder":317},
  {"id":"s_work_han_thu_101_318","chapterId":"ch_work_han_thu_101","textTraditional":"三五七三頁　五行　割（名）〔炙〕於細君。文選作「炙」。顧炎武說「名」字是炙字之誤，文選可證。","sentenceOrder":318},
  {"id":"s_work_han_thu_101_319","chapterId":"ch_work_han_thu_101","textTraditional":"三五七六頁　八行　三（拆）〔析〕而四分天之宿度甲乙也。　景祐、殿、局本都作「析」。","sentenceOrder":319},
  {"id":"s_work_han_thu_101_320","chapterId":"ch_work_han_thu_101","textTraditional":"三五七八頁　四行　發（蕭）〔簫〕韶，　殿本作「簫」。王先謙說殿本是。","sentenceOrder":320},
  {"id":"s_work_han_thu_101_321","chapterId":"ch_work_han_thu_101","textTraditional":"三五七九頁　七行　〔師古曰〕：　王先謙說各本都脫此三字。","sentenceOrder":321},
  {"id":"s_work_han_thu_101_322","chapterId":"ch_work_han_thu_101","textTraditional":"三五八０頁　五行　（記）〔訖〕麟止，　錢大昭說「記」當作「訖」。　按景祐、殿、局本都作「訖」。","sentenceOrder":322},
  {"id":"s_work_han_thu_101_323","chapterId":"ch_work_han_thu_101","textTraditional":"三五八０頁一三行　雄（以）〔有〕序，　景祐、殿本都作「有」。","sentenceOrder":323},
  {"id":"s_work_han_thu_101_324","chapterId":"ch_work_han_thu_101","textTraditional":"三五八二頁一０行　〔一〕以聖人大道槩平。　景祐本有「一」字。","sentenceOrder":324},
  {"id":"s_work_han_thu_102_1","chapterId":"ch_work_han_thu_102","textTraditional":"古之儒者，博學虖六藝之文。〔一〕六（學）〔藝〕者，王教之典籍，先聖所以明天道，正人倫，致至治之成法也。周道既衰，壞於幽厲，禮樂征伐自諸侯出，陵夷二百餘年而孔子興，〔二〕以聖德遭季世，知言之不用而道不行，乃歎曰：「鳳鳥不至，河不出圖，吾已矣夫！」〔三〕「文王既沒，文不在茲乎？」〔四〕於是應聘諸侯，以答禮行誼。〔五〕西入周，南至楚，畏匡厄陳，〔六〕奸七十餘君。〔七〕適齊聞韶，三月不知肉味；〔八〕自衛反魯，然後樂正，雅頌各得其所。〔九〕究觀古今之篇籍，乃稱曰：「大哉，堯之為君也！唯天為大，唯堯則之。〔一０〕巍巍乎其有成功也，煥乎其有文章（也）！」〔一一〕又（云）〔曰〕：「周監於二（世）〔代〕，郁郁乎文哉！吾從周。」〔一二〕於是敘書則斷堯典，〔一三〕稱樂則法韶舞，〔一四〕論詩則首周南。〔一五〕綴周之禮，因魯春秋，舉十二公行事，繩之以文武之道，成一王法，〔一六〕至獲麟而止。蓋晚而好易，讀之韋編三絕，而為之傳。〔一七〕皆因近聖之事，〈古“以”字，形似吕〉立先王之教，故曰：「述而不作，信而好古；」「下學而上達，知我者其天乎！」","sentenceOrder":1},
  {"id":"s_work_han_thu_102_2","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「六藝謂易、禮、樂，詩、書、春秋。」","sentenceOrder":2},
  {"id":"s_work_han_thu_102_3","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「陵夷，言漸穨替。」","sentenceOrder":3},
  {"id":"s_work_han_thu_102_4","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「論語載孔子之言也。鳳鳥、河圖，皆王者之瑞。自傷有德而無位，故云已矣。」","sentenceOrder":4},
  {"id":"s_work_han_thu_102_5","chapterId":"ch_work_han_thu_102","textTraditional":"〔四〕　師古曰：「言文王久已沒矣，文章之事豈不在此乎？蓋自謂也。亦見論語。」","sentenceOrder":5},
  {"id":"s_work_han_thu_102_6","chapterId":"ch_work_han_thu_102","textTraditional":"〔五〕　師古曰：「答禮，謂有問禮者則為應答而申明之。」","sentenceOrder":6},
  {"id":"s_work_han_thu_102_7","chapterId":"ch_work_han_thu_102","textTraditional":"〔六〕　師古曰：「匡，邑名，即陳留匡城縣。孔子貌類陽貨，陽貨嘗有怨於匡，匡人見孔子，以為陽貨也，故圍而欲害之，後得免耳。厄陳，謂在陳絕糧也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_102_8","chapterId":"ch_work_han_thu_102","textTraditional":"〔七〕　師古曰：「奸音干。」","sentenceOrder":8},
  {"id":"s_work_han_thu_102_9","chapterId":"ch_work_han_thu_102","textTraditional":"〔八〕　師古曰：「美舜樂之善也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_102_10","chapterId":"ch_work_han_thu_102","textTraditional":"〔九〕　師古曰：「自衛反魯，謂哀十一年也。是時道衰樂廢，孔子還修正之，故雅頌各得其所。」","sentenceOrder":10},
  {"id":"s_work_han_thu_102_11","chapterId":"ch_work_han_thu_102","textTraditional":"〔一０〕師古曰：「言堯所行皆法天。」","sentenceOrder":11},
  {"id":"s_work_han_thu_102_12","chapterId":"ch_work_han_thu_102","textTraditional":"〔一一〕師古曰：「巍巍者，高貌。煥，明也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_102_13","chapterId":"ch_work_han_thu_102","textTraditional":"〔一二〕師古曰：「言周追視夏殷二代之制而損益之，故禮文大備也。郁郁，文章盛貌。自此以上，孔子之言，皆見論語。」","sentenceOrder":13},
  {"id":"s_work_han_thu_102_14","chapterId":"ch_work_han_thu_102","textTraditional":"〔一三〕師古曰：「謂尚書起自堯典也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_102_15","chapterId":"ch_work_han_thu_102","textTraditional":"〔一四〕師古曰：「論語云顏回問為邦，子曰：『行夏之時，乘殷之輅，服周之冕，樂則韶舞，放鄭聲。』韶，舜樂也，孔子歎其盡善盡美，故欲用之。」","sentenceOrder":15},
  {"id":"s_work_han_thu_102_16","chapterId":"ch_work_han_thu_102","textTraditional":"〔一五〕師古曰：「以關雎為始也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_102_17","chapterId":"ch_work_han_thu_102","textTraditional":"〔一六〕師古曰：「繩謂治正之。」","sentenceOrder":17},
  {"id":"s_work_han_thu_102_18","chapterId":"ch_work_han_thu_102","textTraditional":"〔一七〕師古曰：「編，所以聯次簡也。言愛玩之甚，故編簡之韋為之三絕也。傳謂彖、象、繫辭、文言、說卦之屬。」","sentenceOrder":18},
  {"id":"s_work_han_thu_102_19","chapterId":"ch_work_han_thu_102","textTraditional":"〔一八〕師古曰：「皆論語載孔子之言也。作者之謂聖，述者之謂明。故孔子自謙，言我但述者耳。下學上達，謂下學人事，上達天命也。行不違天，故唯天知我也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_102_20","chapterId":"ch_work_han_thu_102","textTraditional":"仲尼既沒，七十子之徒散遊諸侯，〔一〕大者為卿相師傅，小者友教士大夫，或隱而不見。故子張居陳，〔二〕澹臺子羽居楚，〔三〕子夏居西河，〔四〕子貢終於齊。〔五〕如田子方、段干木、吳起、禽滑氂之屬，皆受業於子夏之倫，為王者師。〔六〕是時，獨魏文侯好學。天下並爭於戰國，儒術既黜焉，然齊魯之間學者猶弗廢，至於威、宣之際，孟子、孫卿之列咸遵夫子之業而潤色之，以學顯於當世。〔七〕","sentenceOrder":20},
  {"id":"s_work_han_thu_102_21","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「七十子，謂弟子者七十七人也。稱七十者，但言其成數也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_102_22","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「子張姓顓孫，名師。」","sentenceOrder":22},
  {"id":"s_work_han_thu_102_23","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「子羽姓澹臺，名滅明。澹音徒甘反。」","sentenceOrder":23},
  {"id":"s_work_han_thu_102_24","chapterId":"ch_work_han_thu_102","textTraditional":"〔四〕　師古曰：「子夏姓卜，名商。」","sentenceOrder":24},
  {"id":"s_work_han_thu_102_25","chapterId":"ch_work_han_thu_102","textTraditional":"〔五〕　師古曰：「子貢姓端木，名賜。」","sentenceOrder":25},
  {"id":"s_work_han_thu_102_26","chapterId":"ch_work_han_thu_102","textTraditional":"〔六〕　師古曰：「子方以下皆魏人也。滑音于拔反。氂音離。」","sentenceOrder":26},
  {"id":"s_work_han_thu_102_27","chapterId":"ch_work_han_thu_102","textTraditional":"〔七〕　鄧展曰：「威、宣，齊二王。」","sentenceOrder":27},
  {"id":"s_work_han_thu_102_28","chapterId":"ch_work_han_thu_102","textTraditional":"及至秦始皇兼天下，燔詩書，殺術士，〔一〕六學從此缺矣。陳涉之王也，魯諸儒持孔氏禮器（而）〔往〕歸之，於是孔甲為涉博士，卒與俱死。〔二〕陳涉起匹夫，敺適戍以立號，〔三〕不滿歲而滅亡，其事至微淺，然而搢紳先生負禮器往委質為臣者何也？以秦禁其業，積怨而發憤於陳王也。","sentenceOrder":28},
  {"id":"s_work_han_thu_102_29","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「燔，焚也。今新豐縣溫湯之處號愍儒鄉，溫湯西南三里有馬谷，谷之西岸有阬，古老相傳以為秦阬儒處也。衛宏詔定古文官書序云：『秦既焚書，患苦天下不從所改更法，而諸生到者拜為郎，前後七百人，乃密令冬種瓜於驪山阬谷中溫處。瓜實成，詔博士諸生說之，人人不同，乃命就視之。為伏機，詩生賢儒皆至焉，方相難不決，因發機，從上填之以土，皆壓，終乃無聲。』此則閔儒之地，其不謬矣。燔音扶元反。」","sentenceOrder":29},
  {"id":"s_work_han_thu_102_30","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「孔光傳云：『鮒為陳涉博士，死陳下。』今此云孔甲，將名鮒而字甲也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_102_31","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「敺與驅同。適讀曰謫。」","sentenceOrder":31},
  {"id":"s_work_han_thu_102_32","chapterId":"ch_work_han_thu_102","textTraditional":"及高皇帝誅項籍，引兵圍魯，魯中諸儒尚講誦習禮，弦歌之音不絕，豈非聖人遺化好學之國哉？於是諸儒始得修其經學，講習大射鄉飲之禮。叔孫通作漢禮儀，因為奉常，諸弟子共定者，咸為選首，然後喟然興於學。〔一〕然尚有干戈，平定四海，〔二〕亦未皇庠序之事也。〔三〕孝惠、高后時，公卿皆武力功臣。孝文時頗登用，〔四〕然孝文本好刑名之言。及至孝景，不任儒，竇太后又好黃老術，故諸博士具官待問，未有進者。〔五〕","sentenceOrder":32},
  {"id":"s_work_han_thu_102_33","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「喟然，歎息貌，音丘位反。」","sentenceOrder":33},
  {"id":"s_work_han_thu_102_34","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「言陳豨、盧綰、韓信、黥布之徒相次反叛征伐也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_102_35","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「皇，暇也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_102_36","chapterId":"ch_work_han_thu_102","textTraditional":"〔四〕　師古曰：「言少用文學之士。」","sentenceOrder":36},
  {"id":"s_work_han_thu_102_37","chapterId":"ch_work_han_thu_102","textTraditional":"〔五〕　師古曰：「具官，謂備員而已。」","sentenceOrder":37},
  {"id":"s_work_han_thu_102_38","chapterId":"ch_work_han_thu_102","textTraditional":"漢興，言易自淄川田生；言書自濟南伏生；言詩，於魯則申培公，於齊則轅固生，〔一〕燕則韓太傅；〔二〕言禮，則魯高堂生；言春秋，於齊則胡毋生，於趙則董仲舒。及竇太后崩，武安君田蚡為丞相，黜黃老、刑名百家之言，延文學儒者以百數，而公孫弘以治春秋為丞相封侯，天下學士靡然鄉風矣。〔三〕","sentenceOrder":38},
  {"id":"s_work_han_thu_102_39","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「培、固者，其人名；公、生者，其號也。它皆類此。培音陪。」","sentenceOrder":39},
  {"id":"s_work_han_thu_102_40","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「名嬰也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_102_41","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":41},
  {"id":"s_work_han_thu_102_42","chapterId":"ch_work_han_thu_102","textTraditional":"弘為學官，悼道之鬱滯，乃請曰：「丞相、御史言：〔一〕制曰『蓋聞導民以禮，風之以樂。〔二〕婚姻者，居室之大倫也。〔三〕今禮廢樂崩，朕甚愍焉，故詳延天下方聞之士，咸登諸朝。〔四〕其令禮官勸學，講議洽聞，舉遺興禮，以為天下先。〔五〕太常議，予博士弟子，崇鄉里之化，以厲賢材焉。』〔六〕謹與太常臧、博士平等議，〔七〕曰：聞三代之道，鄉里有教，夏曰校，殷曰庠，周曰序。〔八〕其勸善也，顯之朝廷；其懲惡也，加之刑罰。故教化之行也，建首善自京師始，繇內及外。〔九〕今陛下昭至德，開大明，配天地，本人倫，勸學興禮，崇化厲賢，以風四方，太平之原也。〔一０〕古者政教未洽，不備其禮，請因舊官而興焉。為博士官置弟子五十人，復其身。〔一一〕太常擇民年十八以上儀狀端正者，補博士弟子。郡國縣官有好文學，敬長上，肅政教，順鄉里，出入不悖，〔一二〕所聞，令相長丞上屬所二千石。〔一三〕二千石謹察可者，常與計偕，〔一四〕詣太常，得受業如弟子。一歲皆輒課，能通一藝以上，補文學掌故缺；其高第可以為郎中，太常籍奏。〔一五〕即有秀才異等，輒以名聞。其不事學若下材，及不能通一藝，輒罷之，而請諸能稱者。〔一六〕臣謹案詔書律令下者，〔一七〕明天人分際，通古今之誼，〔一八〕文章爾雅，訓辭深厚，〔一九〕恩施甚美。小吏淺聞，弗能究宣，亡以明布諭下。以治禮掌故以文學禮義為官，遷留滯。〔二０〕請選擇其秩比二百石以上及吏百石通一藝以上補左右內史、大行卒史，〔二一〕比百石以下補郡太守卒史，皆各二人，〔二二〕邊郡一人。先用誦多者，不足，擇掌故以補中二千石屬，〔二三〕文學掌故補郡屬，備員。〔二四〕請著功令。〔二五〕它如律令。〔二六〕」","sentenceOrder":42},
  {"id":"s_work_han_thu_102_43","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「自此以下皆弘奏請之辭。」","sentenceOrder":43},
  {"id":"s_work_han_thu_102_44","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「風，化也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_102_45","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「倫，理也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_102_46","chapterId":"ch_work_han_thu_102","textTraditional":"〔四〕　師古曰：「詳，悉也。方，道也。有道及博聞之士也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_102_47","chapterId":"ch_work_han_thu_102","textTraditional":"〔五〕　師古曰：「舉遺，謂經典遺逸者求而舉之。」","sentenceOrder":47},
  {"id":"s_work_han_thu_102_48","chapterId":"ch_work_han_thu_102","textTraditional":"〔六〕　師古曰：「厲，勸勉之也，一曰砥厲也。自此以上，弘所引詔文。」","sentenceOrder":48},
  {"id":"s_work_han_thu_102_49","chapterId":"ch_work_han_thu_102","textTraditional":"〔七〕　師古曰：「臧，孔臧也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_102_50","chapterId":"ch_work_han_thu_102","textTraditional":"〔八〕　師古曰：「教，效也。言可效道藝也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_102_51","chapterId":"ch_work_han_thu_102","textTraditional":"〔九〕　師古曰：「繇音由。由，從也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_102_52","chapterId":"ch_work_han_thu_102","textTraditional":"〔一０〕師古曰：「風，化也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_102_53","chapterId":"ch_work_han_thu_102","textTraditional":"〔一一〕師古曰：「復音方目反。」","sentenceOrder":53},
  {"id":"s_work_han_thu_102_54","chapterId":"ch_work_han_thu_102","textTraditional":"〔一二〕師古曰：「悖，乖也，音布內反。」","sentenceOrder":54},
  {"id":"s_work_han_thu_102_55","chapterId":"ch_work_han_thu_102","textTraditional":"〔一三〕師古曰：「聞謂聞其部屬有此人也。令，縣令；相，侯相；長，縣長；丞，縣丞也。二千石謂郡守及諸王相也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_102_56","chapterId":"ch_work_han_thu_102","textTraditional":"〔一四〕師古曰：「隨上計吏俱至京師。」","sentenceOrder":56},
  {"id":"s_work_han_thu_102_57","chapterId":"ch_work_han_thu_102","textTraditional":"〔一五〕師古曰：「為名籍而奏。」","sentenceOrder":57},
  {"id":"s_work_han_thu_102_58","chapterId":"ch_work_han_thu_102","textTraditional":"〔一六〕師古曰：「謂列其能通藝業而稱其任者，奏請補用之也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_102_59","chapterId":"ch_work_han_thu_102","textTraditional":"〔一七〕師古曰：「下謂班行也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_102_60","chapterId":"ch_work_han_thu_102","textTraditional":"〔一八〕師古曰：「分音扶問反。」","sentenceOrder":60},
  {"id":"s_work_han_thu_102_61","chapterId":"ch_work_han_thu_102","textTraditional":"〔一九〕師古曰：「爾雅，近正也，言詔辭雅正而深厚也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_102_62","chapterId":"ch_work_han_thu_102","textTraditional":"〔二０〕師古曰：「言治禮掌故之官本以有文學習禮義而為之，又所以遷擢留滯之人。」","sentenceOrder":62},
  {"id":"s_work_han_thu_102_63","chapterId":"ch_work_han_thu_102","textTraditional":"〔二一〕師古曰：「左右內史後為左馮翊、右扶風，而大行後為大鴻臚也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_102_64","chapterId":"ch_work_han_thu_102","textTraditional":"〔二二〕師古曰：「內地之郡，郡各補太守卒史二人也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_102_65","chapterId":"ch_work_han_thu_102","textTraditional":"〔二三〕蘇林曰：「屬亦曹史，今縣令文書解言屬某甲也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_102_66","chapterId":"ch_work_han_thu_102","textTraditional":"〔二四〕師古曰：「云備員者，示以升擢之非籍其實用也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_102_67","chapterId":"ch_work_han_thu_102","textTraditional":"〔二五〕師古曰：「新立此條，請以著於功令。功令，篇名，若今選舉令。」","sentenceOrder":67},
  {"id":"s_work_han_thu_102_68","chapterId":"ch_work_han_thu_102","textTraditional":"〔二六〕師古曰：「此外並如舊律令。」","sentenceOrder":68},
  {"id":"s_work_han_thu_102_69","chapterId":"ch_work_han_thu_102","textTraditional":"制曰：「可。」自此以來，公卿大夫士吏彬彬多文學之士矣〔一〕。","sentenceOrder":69},
  {"id":"s_work_han_thu_102_70","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「彬彬，文章貌，音斌。」","sentenceOrder":70},
  {"id":"s_work_han_thu_102_71","chapterId":"ch_work_han_thu_102","textTraditional":"昭帝時舉賢良文學，增博士弟子員滿百人，宣帝末增倍之。元帝好儒，能通一經者皆復。〔一〕數年，以用度不足，更為設員千人，郡國置五經百石卒史。成帝末，或言孔子布衣養徒三千人，今天子太學弟子少，於是增弟子員三千人。歲餘，復如故。平帝時王莽秉政，增元士之子得受業如弟子，勿以為員，〔二〕歲課甲科四十人為郎中，乙科二十人為太子舍人，丙科四十人補文學掌故云。","sentenceOrder":71},
  {"id":"s_work_han_thu_102_72","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「蠲其徭賦也。復音方目反。」","sentenceOrder":72},
  {"id":"s_work_han_thu_102_73","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「常員之外，更開此路。」","sentenceOrder":73},
  {"id":"s_work_han_thu_102_74","chapterId":"ch_work_han_thu_102","textTraditional":"自魯商瞿子木受易孔子，〔一〕以授魯橋庇子庸。〔二〕子庸授江東馯臂子弓。〔三〕子弓授燕周醜子家。子家授東武孫虞子乘。子乘授齊田何子裝。及秦禁學，易為筮卜之書，獨不禁，故傳受者不絕也。漢興，田何以齊田徙杜陵，號杜田生，〔四〕授東武王同子中、雒陽周王孫、丁寬、齊服生，皆著易傳數篇。〔五〕同授淄川楊何，字叔元，元光中徵為太中大夫。齊即墨成，至城陽相。〔六〕廣川孟但，為太子門大夫。魯周霸、莒衡胡、〔七〕臨淄主父偃，皆以易至大官。要言易者本之田何。","sentenceOrder":74},
  {"id":"s_work_han_thu_102_75","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「商瞿，姓也。瞿音衢。」","sentenceOrder":75},
  {"id":"s_work_han_thu_102_76","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「姓橋，名庇，字子庸。它皆類此。庇音必寐反。」","sentenceOrder":76},
  {"id":"s_work_han_thu_102_77","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「馯，姓也，音韓。」","sentenceOrder":77},
  {"id":"s_work_han_thu_102_78","chapterId":"ch_work_han_thu_102","textTraditional":"〔四〕　師古曰：「高祖用婁敬之言徙關東大族，故何以舊齊田氏見徙也。初徙時未為杜陵，蓋史家本其地追言之也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_102_79","chapterId":"ch_work_han_thu_102","textTraditional":"〔五〕　師古曰：「田生授王同、周王孫、丁寬、服生四人，而四人皆著易傳也。子中，王同字也。中讀曰仲。」","sentenceOrder":79},
  {"id":"s_work_han_thu_102_80","chapterId":"ch_work_han_thu_102","textTraditional":"〔六〕　師古曰：「姓即墨，名成。」","sentenceOrder":80},
  {"id":"s_work_han_thu_102_81","chapterId":"ch_work_han_thu_102","textTraditional":"〔七〕　師古曰：「莒人姓衡，名胡也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_102_82","chapterId":"ch_work_han_thu_102","textTraditional":"丁寬字子襄，梁人（一王）〔也。初〕梁項生從田何受易，時寬為項生從者，讀易精敏，材過項生，遂事何。學成，何謝寬。〔一〕寬東歸，何謂門人曰：「易以東矣。」〔二〕寬至雒陽，復從周王孫受古義，號周氏傳。景帝時，寬為梁孝王將軍距吳楚，號丁將軍，作易說三萬言，訓故舉大誼而已，〔三〕今小章句是也。寬授同郡碭田王孫。〔四〕王孫授施讎、孟喜、梁丘賀。繇是易有施、孟、梁丘之學。〔五〕","sentenceOrder":82},
  {"id":"s_work_han_thu_102_83","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「告令罷去。」","sentenceOrder":83},
  {"id":"s_work_han_thu_102_84","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「言丁寬（行）〔得〕其法術以去。」","sentenceOrder":84},
  {"id":"s_work_han_thu_102_85","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「故謂經之旨趣也。它皆類此。」","sentenceOrder":85},
  {"id":"s_work_han_thu_102_86","chapterId":"ch_work_han_thu_102","textTraditional":"〔四〕　師古曰：「碭者，梁郡之縣也，音唐，又音宕。」","sentenceOrder":86},
  {"id":"s_work_han_thu_102_87","chapterId":"ch_work_han_thu_102","textTraditional":"〔五〕　師古曰：「繇與由同。後類此。」","sentenceOrder":87},
  {"id":"s_work_han_thu_102_88","chapterId":"ch_work_han_thu_102","textTraditional":"施讎字長卿，沛人也。沛與碭相近。讎為童子，從田王孫受易。後讎徙長陵，田王孫為博士，復從卒業，〔一〕與孟喜、梁丘賀並為門人。謙讓，常稱學廢，不教授。及梁丘賀為少府，事多，及遣子臨分將門人張禹等從讎問。讎自匿不肯見，賀固請，不得已乃授臨等。於是賀薦讎：「結髮事師數十年，〔二〕賀不能及。」詔拜讎為博士。甘露中與五經諸儒雜論同異於石渠閣。〔三〕讎授張禹、琅邪魯伯。伯為會稽太守，禹至丞相。禹授淮陽彭宣、沛戴崇子平。崇為九卿，宣大司空。禹、宣皆有傳。魯伯授太山毛莫如少路、〔四〕琅邪邴丹曼容，著清名。莫如至常山太守。此其知名者也。繇是施家有張、彭之學。","sentenceOrder":88},
  {"id":"s_work_han_thu_102_89","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「卒，終也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_102_90","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「言從結髮為童丱，即從師學，著其早也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_102_91","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「三輔故事云石渠閣在未央殿北，以藏祕書也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_102_92","chapterId":"ch_work_han_thu_102","textTraditional":"〔四〕　師古曰：「姓毛，名莫如，字少路。」","sentenceOrder":92},
  {"id":"s_work_han_thu_102_93","chapterId":"ch_work_han_thu_102","textTraditional":"孟喜字長卿，東海蘭陵人也。父號孟卿，〔一〕善為禮、春秋，授后蒼、疏廣。世所傳后氏禮、疏氏春秋，皆出孟卿。孟卿以禮經多，春秋煩雜，乃使喜從田王孫受易。喜好自稱譽，得易家候陰陽災變書，詐言師田生且死時枕喜膝，獨傳喜，諸儒以此耀之。〔二〕同門梁丘賀疏通證明之，〔三〕曰：「田生絕於施讎手中，時喜歸東海，安得此事？」又蜀人趙賓好小數書，後為易，飾易文，以為「箕子明夷，陰陽氣亡箕子；箕子者，萬物方荄茲也。」〔四〕賓持論巧慧，易家不能難，皆曰「非古法也」。〔五〕云受孟喜，喜為名之。〔六〕後賓死，莫能持其說。喜因不肯仞，〔七〕以此不見信。喜舉孝廉為郎，曲臺署長，〔八〕病免，為丞相掾。博士缺，眾人薦喜。上聞喜改師法，遂不用喜。喜授同郡白光少子、沛翟牧子兄，〔九〕皆為博士。繇是有翟、孟、白之學。","sentenceOrder":93},
  {"id":"s_work_han_thu_102_94","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「時人以卿呼之，若言公矣。」","sentenceOrder":94},
  {"id":"s_work_han_thu_102_95","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「用為光榮也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_102_96","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「同門，同師學者也。疏通猶言分別也。證明，明其偽也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_102_97","chapterId":"ch_work_han_thu_102","textTraditional":"〔四〕　師古曰：「易明夷卦彖曰：『內文明而外柔順，以蒙大難。文王以之，利艱貞，晦其明也。內難而能正其志，箕子以之。』而六五爻辭曰：『箕子之明夷，利貞。』此箕子者，謂殷父師說洪範者也，而賓妄為說耳。荄茲，言其根荄方滋茂也。荄音該，又音皆。」","sentenceOrder":97},
  {"id":"s_work_han_thu_102_98","chapterId":"ch_work_han_thu_102","textTraditional":"〔五〕　師古曰：「心不服。」","sentenceOrder":98},
  {"id":"s_work_han_thu_102_99","chapterId":"ch_work_han_thu_102","textTraditional":"〔七〕　師古曰：「名之者，承取其名，云實授也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_102_100","chapterId":"ch_work_han_thu_102","textTraditional":"〔七〕　師古曰：「仞亦名也。仞音刃。」","sentenceOrder":100},
  {"id":"s_work_han_thu_102_101","chapterId":"ch_work_han_thu_102","textTraditional":"〔八〕　師古曰：「曲臺，殿名。署者，主供其事也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_102_102","chapterId":"ch_work_han_thu_102","textTraditional":"〔九〕　師古曰：「兄讀曰況。」","sentenceOrder":102},
  {"id":"s_work_han_thu_102_103","chapterId":"ch_work_han_thu_102","textTraditional":"梁丘賀字長翁，琅邪諸人也。以能心計，為武騎。從太中大夫京房受易。房者，淄川楊何弟子也。〔一〕房出為齊郡太守，賀更事田王孫。宣帝時，聞京房為易明，求其門人，得賀。賀時為都司空令，坐事，論免為庶人。待詔黃門數入說教侍中，〔二〕以召賀。賀入說，上善之，〔三〕以賀為郎。會八月飲酎，行祠孝昭廟，〔四〕先敺旄頭劍挺墮墬，首垂泥中，〔五〕刃鄉乘輿車，〔六〕馬驚。於是召賀筮之，有兵謀，不吉。上還，使有司侍祠。是時霍氏外孫代郡太守任宣坐謀反誅，〔七〕宣子章為公車丞，亡在渭城界中，夜玄服入廟，居郎間，〔八〕執戟立廟門，待上至，欲為逆。發覺，伏誅。故事，上常夜入廟，其後待明而入，自此始也。賀以筮有應，繇是近幸，為太中大夫，給事中，至少府。為人小心周密，上信重之。年老終官。傳子臨，亦入說，為黃門郎。甘露中，奉使問諸儒於石渠。臨學精孰，專行京房法。琅邪王吉通五經，聞臨說，善之。時宣帝選高材郎十人從臨講，吉乃使其子郎中駿上疏從臨受易。臨代五鹿充宗君孟為少府，駿御史大夫，自有傳。充宗授平陵士孫張仲方、〔九〕沛鄧彭祖子夏、齊衡咸長賓。張為博士，至揚州牧，光祿大夫給事中，家世傳業；彭祖，真定太傅；咸，王莽講學大夫。繇是粱丘有士孫、鄧、衡之學。","sentenceOrder":103},
  {"id":"s_work_han_thu_102_104","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「自別一京房，非焦延壽弟子為課吏法者。或書字誤耳，不當為京房。」","sentenceOrder":104},
  {"id":"s_work_han_thu_102_105","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「為諸侍中說經為教授。」","sentenceOrder":105},
  {"id":"s_work_han_thu_102_106","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「說於天子之前。」","sentenceOrder":106},
  {"id":"s_work_han_thu_102_107","chapterId":"ch_work_han_thu_102","textTraditional":"〔四〕　師古曰：「行謂天子出。」","sentenceOrder":107},
  {"id":"s_work_han_thu_102_108","chapterId":"ch_work_han_thu_102","textTraditional":"〔五〕　師古曰：「挺，引也，劍自然引拔出也。墬，古地字。」","sentenceOrder":108},
  {"id":"s_work_han_thu_102_109","chapterId":"ch_work_han_thu_102","textTraditional":"〔六〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":109},
  {"id":"s_work_han_thu_102_110","chapterId":"ch_work_han_thu_102","textTraditional":"〔七〕　師古曰：「霍光傳云任宣霍氏之婿，此云外孫，誤也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_102_111","chapterId":"ch_work_han_thu_102","textTraditional":"〔八〕　師古曰：「郎皆皂衣，故章玄服以廁也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_102_112","chapterId":"ch_work_han_thu_102","textTraditional":"〔九〕　師古曰：「姓士孫，名張，字仲方。」","sentenceOrder":112},
  {"id":"s_work_han_thu_102_113","chapterId":"ch_work_han_thu_102","textTraditional":"京房受易梁人焦延壽。〔一〕延壽云嘗從孟喜問易。會喜死，房以為延壽易即孟氏學，翟牧、白生不肯，皆曰非也。至成帝時，劉向校書，考易說，以為諸易家說皆祖田何、楊叔〔元〕、丁將軍，大誼略同，唯京氏為異，黨焦延壽獨得隱士之說，〔二〕託之孟氏，不相與同。房以明災異得幸，為石顯所譖誅，自有傳。房授東海殷嘉、河東姚平、河南乘弘，〔三〕皆為郎、博士。繇是易有京氏之學。","sentenceOrder":113},
  {"id":"s_work_han_thu_102_114","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「延壽其字，名贛。」","sentenceOrder":114},
  {"id":"s_work_han_thu_102_115","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「黨讀曰儻。」","sentenceOrder":115},
  {"id":"s_work_han_thu_102_116","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「乘，姓也，音食證反。」","sentenceOrder":116},
  {"id":"s_work_han_thu_102_117","chapterId":"ch_work_han_thu_102","textTraditional":"費直字長翁，東萊人也。〔一〕治易為郎，至單父令。〔二〕長於卦筮，亡章句，徒以彖象系辭十篇文言解說上下經。琅邪王璜平中能傳之。〔三〕璜又傳古文尚書。","sentenceOrder":117},
  {"id":"s_work_han_thu_102_118","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「費音扶味反。」","sentenceOrder":118},
  {"id":"s_work_han_thu_102_119","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「單音善。父音甫。」","sentenceOrder":119},
  {"id":"s_work_han_thu_102_120","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「中讀曰仲。」","sentenceOrder":120},
  {"id":"s_work_han_thu_102_121","chapterId":"ch_work_han_thu_102","textTraditional":"高相，沛人也。治易與費公同時，其學亦亡章句，專說陰陽災異，自言出於丁將軍。傳至相，相授子康及蘭陵毋將永。康以明易為郎，永至豫章都尉。及王莽居攝，東郡太守翟誼謀舉兵誅莽，事未發，康候知東郡有兵，私語門人，門人上書言之。後數月，翟誼兵起，莽召問，對受師高康。莽惡之，以為惑眾，斬康。繇是易有高氏學。高、費皆未嘗立於學官。","sentenceOrder":121},
  {"id":"s_work_han_thu_102_122","chapterId":"ch_work_han_thu_102","textTraditional":"伏生，濟南人也，〔一〕故為秦博士。孝文時，求能治尚書者，天下亡有，聞伏生治之，欲召。時伏生年九十餘，老不能行，於是詔太常，使掌故朝錯往受之。〔二〕秦時禁書，伏生壁藏之，其後大兵起，流亡。漢定，伏生求其書，亡數十篇，獨得二十九篇，即以教於齊、魯之間。齊學者由此頗能言尚書，山東大師亡不涉尚書以教。伏生教濟南張生及歐陽生。張生為博士，而伏生孫以治尚書徵，弗能明定。是後魯周霸、雒陽賈嘉頗能言尚書云。〔三〕","sentenceOrder":122},
  {"id":"s_work_han_thu_102_123","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　張晏曰：「名勝，伏生碑云也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_102_124","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「衛宏定古文尚書序云『伏生老，不能正言，言不可曉也，使其女傳言教錯。齊人語多與潁川異，錯所不知者凡十二三，略以其意屬讀而已。』」","sentenceOrder":124},
  {"id":"s_work_han_thu_102_125","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「嘉者，賈誼之孫也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_102_126","chapterId":"ch_work_han_thu_102","textTraditional":"歐陽生字和伯，千乘人也。事伏生，授倪寬。寬又受業孔安國，至御史大夫，自有傳。寬有俊材，初見武帝，語經學。上曰：「吾始以尚書為樸學，弗好，及聞寬說，可觀。」乃從寬問一篇。歐陽、大小夏侯氏學皆出於寬。寬授歐陽生子，世世相傳，至曾孫高子陽，為博士。〔一〕高孫地餘長賓以太子中庶子授太子，後為博士，論石渠。元帝即位，地餘侍中，貴幸，至少府。戒其子曰：「我死，官屬即送汝財物，慎毋受。汝九卿儒者子孫，以廉絜著，可以自成。」及地餘死，少府官屬共送數百萬，其子不受。天子聞而嘉之，賜錢百萬。地餘少子政為王莽講學大夫。由是尚書世有歐陽氏學。","sentenceOrder":126},
  {"id":"s_work_han_thu_102_127","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「名高，字子陽。」","sentenceOrder":127},
  {"id":"s_work_han_thu_102_128","chapterId":"ch_work_han_thu_102","textTraditional":"林尊字長賓，濟南人也。事歐陽高，為博士，論石渠。後至少府、太子太傅，授平陵平當、梁陳翁生。當至丞相，自有傳。翁生信都太傅，家世傳業。由是歐陽有平、陳之學。翁生授琅邪殷崇、楚國龔勝。崇為博士，勝右扶風，自有傳。而平當授九江朱普公文、上黨鮑宣。普為博士，宣司隸校尉，自有傳。徒眾尤盛，知名者也。","sentenceOrder":128},
  {"id":"s_work_han_thu_102_129","chapterId":"ch_work_han_thu_102","textTraditional":"夏侯勝，其先夏侯都尉，從濟南張生受尚書，以傳族子始昌。始昌傳勝，勝又事同郡蕑卿。〔一〕蕑卿者，倪寬門人。勝傳從兄子建，建又事歐陽高。勝至長信少府，建太子太傅，自有傳。由是尚書有大小夏侯之學。","sentenceOrder":129},
  {"id":"s_work_han_thu_102_130","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「蕑音姦。」","sentenceOrder":130},
  {"id":"s_work_han_thu_102_131","chapterId":"ch_work_han_thu_102","textTraditional":"周堪字少卿，齊人也。與孔霸俱事大夏侯勝。霸為博士。堪譯官令，論於石渠，經為最高，後為太子少傅，而孔霸以太中大夫授太子。及元帝即位，堪為光祿大夫，與蕭望之並領尚書事，為石顯等所譖，皆免官。望之自殺，上愍之，乃擢堪為光祿勳，語在劉向傳。堪授牟卿及長安許商長伯。牟卿為博士。霸以帝師賜爵號褒成君，傳子光，亦事牟卿，至丞相，自有傳。由是大夏侯有孔、許之學。商善為算，著五行論曆，四至九卿，號其門人沛唐林子高為德行，平陵吳章偉君為言語，重泉王吉少音為政事，齊炔欽幼卿為文學。〔一〕王莽時，林、吉為九卿，自表上師冢，大夫博士郎吏為許氏學者，各從門人，會車數百兩，儒者榮之。欽、章皆為博士，徒眾尤盛。章為王莽所誅。","sentenceOrder":131},
  {"id":"s_work_han_thu_102_132","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「依孔子目弟子顏回以下為四科也。炔音桂。」","sentenceOrder":132},
  {"id":"s_work_han_thu_102_133","chapterId":"ch_work_han_thu_102","textTraditional":"張山拊字長賓，平陵人也。〔一〕事小夏侯建，為博士，論石渠，至少府。授同縣李尋、鄭寬中少君、山陽張無故子儒、信都秦恭延君、陳留假倉子驕。無故善修章句，為廣陵太傅，守小夏侯說文。恭增師法至百萬言，〔二〕為城陽內史。倉以謁者論石渠，至膠東相。尋善說災異，為騎都尉，自有傳。寬中有俊材，以博士授太子，成帝即位，賜爵關內侯，食邑八百戶，遷光祿大夫，領尚書事，甚尊重。會疾卒，谷永上疏曰：「臣聞聖王尊師傅，褒賢俊，顯有功，生則致其爵祿，死則異其禮諡。昔周公薨，成王葬以變禮，而當天心。〔三〕公叔文子卒，衛侯加以美諡，著為後法。〔四〕近事，大司空朱邑、右扶風翁歸德茂夭年，孝宣皇帝愍冊厚賜，贊命之臣靡不激揚〔五〕。關內侯鄭寬中有顏子之美質，包商、偃之文學，〔六〕嚴然總五經之眇論，立師傅之顯位，〔七〕入則鄉唐虞之閎道，王法納乎聖聽，〔八〕出則參冢宰之重職，功列施乎政事，退食自公，私門不開，〔九〕散賜九族，田畝不益，德配周召，忠合羔羊，未得登司徒，有家臣，〔一０〕卒然早終，尤可悼痛！〔一一〕臣愚以為宜加其葬禮，賜之令諡，〔一二〕以章尊師褒賢顯功之德。」上弔贈寬中甚厚。由是小夏侯有鄭、張、秦、假、李氏之學。寬中授東郡趙玄，無故授沛唐尊，恭授魯馮賓。賓為博士，尊王莽太傅，玄哀帝御史大夫，至大官，知名者也。","sentenceOrder":133},
  {"id":"s_work_han_thu_102_134","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「拊音膚。」","sentenceOrder":134},
  {"id":"s_work_han_thu_102_135","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「言小夏侯本所說之文不多，而秦恭又更增益，故至百萬言也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_102_136","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「周公死，成王欲葬之於成周，天乃雷雨以風，禾盡偃，大木斯拔。國大恐。王乃葬周公於畢，示不敢臣也。事見尚書大傳，而與古文尚書不同。」","sentenceOrder":136},
  {"id":"s_work_han_thu_102_137","chapterId":"ch_work_han_thu_102","textTraditional":"〔四〕　師古曰：「公叔文子，衛大夫公叔發也。文子卒，其子請諡於君。君曰：『昔者衛國凶飢，夫子為粥與國之餓者，不亦惠乎？衛國有難，夫子以其死衛寡人，不亦貞乎？夫子聽衛國之政，修其班制，以與四鄰交，衛國社稷不辱，不亦文乎？謂夫子貞惠文子。』事見禮記檀弓。」","sentenceOrder":137},
  {"id":"s_work_han_thu_102_138","chapterId":"ch_work_han_thu_102","textTraditional":"〔五〕　師古曰：「贊，佐也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_102_139","chapterId":"ch_work_han_thu_102","textTraditional":"〔六〕　師古曰：「論語云『文學子游、子夏』。商，子夏名。偃，子游名。」","sentenceOrder":139},
  {"id":"s_work_han_thu_102_140","chapterId":"ch_work_han_thu_102","textTraditional":"〔七〕　師古曰：「嚴與儼同。眇讀曰妙。」","sentenceOrder":140},
  {"id":"s_work_han_thu_102_141","chapterId":"ch_work_han_thu_102","textTraditional":"〔八〕　師古曰：「鄉讀曰嚮。閎，大也。言陳聖王之法，聞於天子。」","sentenceOrder":141},
  {"id":"s_work_han_thu_102_142","chapterId":"ch_work_han_thu_102","textTraditional":"〔九〕　師古曰：「『退食自公』，召南羔羊詩之辭，言貶退所食之祿，而從至公之道也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_102_143","chapterId":"ch_work_han_thu_102","textTraditional":"〔一０〕師古曰：「司徒，掌禮教之官，言寬中學行堪為之也。家臣，若今諸公國官及府佐也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_102_144","chapterId":"ch_work_han_thu_102","textTraditional":"〔一一〕師古曰：「卒讀曰猝。」","sentenceOrder":144},
  {"id":"s_work_han_thu_102_145","chapterId":"ch_work_han_thu_102","textTraditional":"〔一二〕師古曰：「令，善也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_102_146","chapterId":"ch_work_han_thu_102","textTraditional":"孔氏有古文尚書，孔安國以今文字讀之，因以起其家逸書，得十餘篇，蓋尚書茲多於是矣。遭巫蠱，未立於學官。安國為諫大夫，授都尉朝，〔一〕而司馬遷亦從安國問故。遷書載堯典、禹貢、洪範、微子、金縢諸篇，多古文說。都尉朝授膠東庸生。庸生授清河胡常少子，〔二〕以明穀梁春秋為博士、部刺史，又傳左氏。常授虢徐敖。敖為右扶風掾，又傳毛詩，授王璜、平陵塗惲子真。子真授河南桑欽君長。王莽時，諸學皆立。劉歆為國師，璜、惲等皆貴顯。世所傳百兩篇者，出東萊張霸，分析合二十九篇以為數十，又采左氏傳、書敘為作首尾，凡百二篇。篇或數簡，文意淺陋。成帝時求其古文者，霸以能為百兩徵，以中書校之，非是。〔三〕霸辭受父，父有弟子尉氏樊並。時太中大夫平當、侍御史周敞勸上存之。〔四〕後樊並謀反，乃黜其書。","sentenceOrder":146},
  {"id":"s_work_han_thu_102_147","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　服虔曰：「朝名，都尉姓。」","sentenceOrder":147},
  {"id":"s_work_han_thu_102_148","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「少子，亦常字也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_102_149","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「以霸私增加分析，故與中書之文不同也。中書，天子所藏之書也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_102_150","chapterId":"ch_work_han_thu_102","textTraditional":"〔四〕　師古曰：「存者，立其學。」","sentenceOrder":150},
  {"id":"s_work_han_thu_102_151","chapterId":"ch_work_han_thu_102","textTraditional":"申公，魯人也。少與楚元王交俱事齊人浮丘伯受詩。漢興，高祖過魯，申公以弟子從師人見于魯南宮。呂太后時，浮丘伯在長安，楚元王遣子郢與申公俱卒學。〔一〕元王薨，郢嗣立為楚王，令申公傅太子戊。戊不好學，病申公。〔二〕及戊立為王，胥靡申公。〔三〕申公愧之，歸魯退居家教，終身不出門。復謝賓客，〔四〕獨王命召之乃往。弟子自遠方至受業者千餘人，申公獨以詩經為訓故以教，亡傳，〔五〕疑者則闕弗傳。蘭陵王臧既從受詩，已通，事景帝為太子少傅，免去。武帝初即位，臧乃上書宿衛，累遷，一歲至郎中令。及代趙綰亦嘗受詩申公，為御史大夫。綰、臧請立明堂以朝諸侯，不能就其事，〔六〕乃言師申公。於是上使使束帛加璧，安車以蒲裹輪，駕駟迎申公，弟子兩人乘軺傳從。〔七〕至，見上，上問治亂之事。申公時已八十餘，老，對曰：「為治者不（至）〔在〕多言，顧力行何如耳。」〔八〕是時上方好文辭，見申公對，默然。然已招致，既以為太中大夫，舍魯邸，〔九〕議明堂事。太皇竇太后喜老子言，不說儒術，〔一０〕得綰、臧之過，以讓上曰：「此欲復為新垣平也！」〔一一〕上因廢明堂事，下綰、臧吏，皆自殺。申公亦病免歸，數年卒。弟子為博士十餘人，孔安國至臨淮太守，周霸膠西內史，夏寬城陽內史，碭魯賜東海太守，蘭陵繆生長沙內史，徐偃膠西中尉，鄒人闕門慶忌膠東內史，〔一二〕其治官民皆有廉節稱。其學官弟子行雖不備，而至於大夫、郎、掌故以百數。申公卒以詩、春秋授，而瑕丘江公盡能傳之，徒眾最盛。及魯許生、免中徐公，〔一三〕皆守學教授。韋賢治詩，事（博士）大江公及許生，〔一四〕又治禮，至丞相。傳子玄成，以淮陽中尉論石渠，後亦至丞相。玄成及兄子賞以詩授哀帝，至大司馬車騎將軍，自有傳。由是魯詩有韋氏學。","sentenceOrder":151},
  {"id":"s_work_han_thu_102_152","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「郢即郢客也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_102_153","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「患苦也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_102_154","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「胥靡，相係而作役，解具在楚元王傳也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_102_155","chapterId":"ch_work_han_thu_102","textTraditional":"〔四〕　師古曰：「身即不出門，非受業弟子，其它賓客來者又謝遣之，不與相見也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_102_156","chapterId":"ch_work_han_thu_102","textTraditional":"〔五〕　師古曰：「口說其指，不為解說之傳。」","sentenceOrder":156},
  {"id":"s_work_han_thu_102_157","chapterId":"ch_work_han_thu_102","textTraditional":"〔六〕　師古曰：「就，成也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_102_158","chapterId":"ch_work_han_thu_102","textTraditional":"〔七〕　師古曰：「傳音張戀反。」","sentenceOrder":158},
  {"id":"s_work_han_thu_102_159","chapterId":"ch_work_han_thu_102","textTraditional":"〔八〕　師古曰：「顧，念也。力行，（為）〔謂〕勉力為行也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_102_160","chapterId":"ch_work_han_thu_102","textTraditional":"〔九〕　師古曰：「舍，止息也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_102_161","chapterId":"ch_work_han_thu_102","textTraditional":"〔一０〕師古曰：「喜音許既反。說讀曰悅。」","sentenceOrder":161},
  {"id":"s_work_han_thu_102_162","chapterId":"ch_work_han_thu_102","textTraditional":"〔一一〕師古曰：「讓，責也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_102_163","chapterId":"ch_work_han_thu_102","textTraditional":"〔一二〕李奇曰：「姓闕門，名慶忌。」","sentenceOrder":163},
  {"id":"s_work_han_thu_102_164","chapterId":"ch_work_han_thu_102","textTraditional":"〔一三〕蘇林曰：「免中，縣名也。」李奇曰：「邑名也。」師古曰：「李說是也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_102_165","chapterId":"ch_work_han_thu_102","textTraditional":"〔一四〕晉灼曰：「大江公即瑕丘江公也。以異下博士江公，故稱大。」","sentenceOrder":165},
  {"id":"s_work_han_thu_102_166","chapterId":"ch_work_han_thu_102","textTraditional":"王式字翁思，東平新桃人也。事免中徐公及許生。式為昌邑王師。昭帝崩，昌邑王嗣立，以行淫亂廢，昌邑群臣皆下獄誅，唯中尉王吉、郎中令龔遂以數諫減死論。式繫獄當死，治事使者責問曰：「師何以亡諫書？」式對曰：「臣以詩三百五篇朝夕授王，至於忠臣孝子之篇，未嘗不為王反復誦之也；〔一〕至於危亡失道之君，未嘗不流涕為王深陳之也。臣以三百五篇諫，是以亡諫書。」使者以聞，亦得減死論，歸家不教授。山陽張長安幼君〔二〕先事式，後東平唐長賓、沛褚少孫亦來事式，問經數篇，式謝曰：「聞之於師俱是矣，自潤色之。」〔三〕不肯復授。唐生、褚生應博士弟子選，詣博士，摳衣登堂，頌禮甚嚴，〔四〕試誦說，有法，疑者丘蓋不言。〔五〕諸博士驚問何師，對曰事式。皆素聞其賢，共薦式。詔除下為博士。〔六〕式徵來，衣博士衣而不冠，曰：「刑餘之人，何宜復充禮官？」既至，止舍中，會諸大夫博士，共持酒肉勞式，皆注意高仰之。〔七〕博士江公世為魯詩宗，〔八〕至江公著孝經說，心嫉式，謂歌吹諸生曰：〔九〕「歌驪駒。」〔一０〕式曰：「聞之於師：客歌驪駒，主人歌客毋庸歸。〔一一〕今日諸君為主人，日尚早，未可也。」江翁曰：「經何以言之？」〔一二〕式曰：「在曲禮。」江翁曰：「何狗曲也！」〔一三〕式恥之，陽醉逿墬。〔一四〕式客罷，讓諸生曰：「我本不欲來，〔一五〕諸生彊勸我，竟為豎子所辱！」遂謝病免歸，終於家。張生、唐生、褚生皆為博士。張生論石渠，至淮陽中尉。唐生楚太傅。由是魯詩有張、唐、褚氏之學。張生兄子游卿為諫大夫，以詩授元帝。其門人琅邪王扶為泗水中尉，陳留許晏為博士。由是張家有許氏學。初，薛廣德亦事王式，以博士論石渠，授龔舍。廣德至御史大夫，舍泰山太守，皆有傳。","sentenceOrder":166},
  {"id":"s_work_han_thu_102_167","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「復音方目反。」","sentenceOrder":167},
  {"id":"s_work_han_thu_102_168","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　李奇曰：「長安，名。」","sentenceOrder":168},
  {"id":"s_work_han_thu_102_169","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「言所聞師說具盡於此，若嫌簡略，任更潤色。」","sentenceOrder":169},
  {"id":"s_work_han_thu_102_170","chapterId":"ch_work_han_thu_102","textTraditional":"〔四〕　師古曰：「摳衣，謂以手內舉之，令離地也。摳音口侯反。頌讀曰容。」","sentenceOrder":170},
  {"id":"s_work_han_thu_102_171","chapterId":"ch_work_han_thu_102","textTraditional":"〔五〕　蘇林曰：「丘蓋不言，不知之意也。」如淳曰：「齊俗以不知為丘。」師古曰：「二說皆非也。論語載孔子曰：『蓋有不知而作之者，我無是也。』欲遵此意，故效孔子自稱丘耳。蓋者，發語之辭。」","sentenceOrder":171},
  {"id":"s_work_han_thu_102_172","chapterId":"ch_work_han_thu_102","textTraditional":"〔六〕　師古曰：「下除官之書也。下音胡嫁反。」","sentenceOrder":172},
  {"id":"s_work_han_thu_102_173","chapterId":"ch_work_han_thu_102","textTraditional":"〔七〕　師古曰：「勞音來到反。」","sentenceOrder":173},
  {"id":"s_work_han_thu_102_174","chapterId":"ch_work_han_thu_102","textTraditional":"〔八〕　師古曰：「為魯詩者所宗師也。」","sentenceOrder":174},
  {"id":"s_work_han_thu_102_175","chapterId":"ch_work_han_thu_102","textTraditional":"〔九〕　如淳曰：「其學官自有此法，酒坐歌吹以相樂也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_102_176","chapterId":"ch_work_han_thu_102","textTraditional":"〔一０〕服虔曰：「逸詩篇名也，見大戴禮。客欲去歌之。」文潁曰：「其辭云『驪駒在門，僕夫具存；驪駒在路，僕夫整駕』也。」","sentenceOrder":176},
  {"id":"s_work_han_thu_102_177","chapterId":"ch_work_han_thu_102","textTraditional":"〔一一〕文穎曰：「庸，用也。主人禮未畢，且無用歸也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_102_178","chapterId":"ch_work_han_thu_102","textTraditional":"〔一二〕師古曰：「於經何所有此言？」","sentenceOrder":178},
  {"id":"s_work_han_thu_102_179","chapterId":"ch_work_han_thu_102","textTraditional":"〔一三〕師古曰：「意怒，故妄發言。言狗者，輕賤之甚也。今流俗書本云何曲狗，妄改之也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_102_180","chapterId":"ch_work_han_thu_102","textTraditional":"〔一四〕師古曰：「逿，失據而倒也。墬，古地字。逿音徒浪反。」","sentenceOrder":180},
  {"id":"s_work_han_thu_102_181","chapterId":"ch_work_han_thu_102","textTraditional":"〔一五〕師古曰：「讓，責也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_102_182","chapterId":"ch_work_han_thu_102","textTraditional":"轅固，齊人也。以治詩孝景時為博士，與黃生爭論於上前。黃生曰：「湯武非受命，乃殺也。」固曰：「不然。夫桀紂荒亂，天下之心皆歸湯武，湯武因天下之心而誅桀紂，桀紂之民弗為使而歸湯武，湯武不得已而立，非受命（而）〔為〕何？」〔一〕黃生曰：「『冠雖敝必加於首，履雖新必貫於足。』〔二〕何者？上下之分也。〔三〕今桀紂雖失道，然君上也；湯武雖聖，臣下也。夫主有失行，臣不正言匡過以尊天子，反因過而誅之，代立南面，非殺而何？」固曰：「必若云，〔四〕是高皇帝代秦即天子之位，非邪？」於是上曰：「食肉毋食馬肝，未為不知味也；言學者毋言湯武受命，不為愚。〔五〕」遂罷。竇太后好老子書，召問固。固曰：「此家人言耳。」〔六〕太后怒曰：「安得司空城旦書乎！」〔七〕乃使固入圈擊彘。上知太后怒，而固直言無罪，乃假固利兵。〔八〕下，固刺彘正中其心，彘應手而倒。太后默然，亡以復罪。後上以固廉直，拜為清河太傅，疾免。武帝初即位，復以賢良徵。諸儒多嫉毀曰固老，罷歸之。時固己九十餘矣。公孫弘亦徵，仄目而事固。〔九〕固曰：「公孫子，務正學以言，無曲學以阿世！」諸齊以詩顯貴，皆固之弟子也。昌邑太傅夏侯始昌最明，自有傳。","sentenceOrder":182},
  {"id":"s_work_han_thu_102_183","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「此非受命更何為？」","sentenceOrder":183},
  {"id":"s_work_han_thu_102_184","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「語見太公六韜也。」","sentenceOrder":184},
  {"id":"s_work_han_thu_102_185","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「分音扶問反。」","sentenceOrder":185},
  {"id":"s_work_han_thu_102_186","chapterId":"ch_work_han_thu_102","textTraditional":"〔四〕　師古曰：「謂必如黃生之言。」","sentenceOrder":186},
  {"id":"s_work_han_thu_102_187","chapterId":"ch_work_han_thu_102","textTraditional":"〔五〕　師古曰：「馬肝有毒，食之憙殺人，幸得無食。言湯武為殺，是背經義，故以為喻也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_102_188","chapterId":"ch_work_han_thu_102","textTraditional":"〔六〕　師古曰：「家人言僮隸之屬。」","sentenceOrder":188},
  {"id":"s_work_han_thu_102_189","chapterId":"ch_work_han_thu_102","textTraditional":"〔七〕　服虔曰：「道家以儒法為急，比之於律令也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_102_190","chapterId":"ch_work_han_thu_102","textTraditional":"〔八〕　師古曰：「假，給與也。利兵，兵刃之利者。」","sentenceOrder":190},
  {"id":"s_work_han_thu_102_191","chapterId":"ch_work_han_thu_102","textTraditional":"〔九〕　師古曰：「言深憚之。」","sentenceOrder":191},
  {"id":"s_work_han_thu_102_192","chapterId":"ch_work_han_thu_102","textTraditional":"后蒼字近君，東海郯人也。事夏侯始昌。始昌通五經，蒼亦通詩禮，為博士，至少府，授翼奉、蕭望之、匡衡。奉為諫大夫，望之前將軍，衡丞相，皆有傳。衡授琅邪師丹、伏理斿君、潁川滿昌君都。君都為詹事，理高密太傅，家世傳業。丹大司空，自有傳。由是齊詩有翼、匡、師、伏之學。滿昌授九江張邯、琅邪皮容，皆至大官，徒眾尤盛。","sentenceOrder":192},
  {"id":"s_work_han_thu_102_193","chapterId":"ch_work_han_thu_102","textTraditional":"韓嬰，燕人也。孝文時為博士，景帝時至常山太傅。嬰推詩人之意，而作內外傳數萬言，其語頗與齊、魯間殊，然歸一也。淮南賁生受之。〔一〕燕趙間言詩者由韓生。韓生亦以易授人，推易意而為之傳。燕趙間好詩，故其易微，唯韓氏自傳之。武帝時，嬰嘗與董仲舒論於上前，其人精悍，處事分明，〔二〕仲舒不能難也。後其孫商為博士。孝宣時，涿郡韓生其後也，以易徵，待詔殿中，曰：「所受易即先太傅所傳也。嘗受韓詩，不如韓氏易深，太傅故專傳之。」司隸校尉蓋寬饒本受易於孟喜，見涿韓生說易而好之，即更從受焉。","sentenceOrder":193},
  {"id":"s_work_han_thu_102_194","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「賁音肥。」","sentenceOrder":194},
  {"id":"s_work_han_thu_102_195","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「悍，勇銳。」","sentenceOrder":195},
  {"id":"s_work_han_thu_102_196","chapterId":"ch_work_han_thu_102","textTraditional":"趙子，河內人也。事燕韓生，授同郡蔡誼。誼至丞相，自有傳。誼授同郡食子公與王吉。吉為昌邑〔王〕中尉，自有傳。食生為博士，授泰山栗豐。吉授淄川長孫順。順為博士，豐部刺史。由是韓詩有王、食、長孫之學。豐授山陽張就，順授東海髮福，皆至大官，徒眾尤盛。","sentenceOrder":196},
  {"id":"s_work_han_thu_102_197","chapterId":"ch_work_han_thu_102","textTraditional":"毛公，趙人也。治詩，為河間獻王博士，授同國貫長卿。長卿授解延年。延年為阿武令，授徐敖。敖授九江陳俠，為王莽講學大夫。由是言毛詩者，本之徐敖。","sentenceOrder":197},
  {"id":"s_work_han_thu_102_198","chapterId":"ch_work_han_thu_102","textTraditional":"漢興，魯高堂生傳士禮十七篇，而魯徐生善為頌。〔一〕孝文時，徐生以頌為禮官大夫，傳子至孫延、襄。〔二〕襄，其資性善為頌，不能通經；延頗能，未善也。襄亦以頌為大夫，至廣陵內史。延及徐氏弟子公戶滿意、（柏）〔桓〕生、單次皆為禮官大夫。〔三〕而瑕丘蕭奮以禮至淮陽太守。諸言禮為頌者由徐氏。","sentenceOrder":198},
  {"id":"s_work_han_thu_102_199","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　蘇林曰：「漢舊儀有二郎為此頌貌威儀事。有徐氏，徐氏後有張氏，不知經，但能盤辟為禮容。天下郡國有容史，皆詣魯學之。」師古曰：「頌讀與容同。下皆類此。」","sentenceOrder":199},
  {"id":"s_work_han_thu_102_200","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「延及襄二人。」","sentenceOrder":200},
  {"id":"s_work_han_thu_102_201","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「姓公戶，名滿意也。與桓生及單次凡三人。單音善。」","sentenceOrder":201},
  {"id":"s_work_han_thu_102_202","chapterId":"ch_work_han_thu_102","textTraditional":"孟卿，東海人也。事蕭奮，以授后倉、魯閭丘卿。倉說禮數萬言，號曰后氏曲臺記，〔一〕授沛聞人通漢子方、〔二〕梁戴德延君、戴聖次君、沛慶普孝公。孝公為東平太傅。德號大戴，為信都太傅；聖號小戴，以博士論石渠，至九江太守。由是禮有大戴、小戴、慶氏之學。通漢以太子舍人論石渠，至中山中尉。普授魯夏侯敬，又傳族子咸，為豫章太守。大戴授琅邪徐良斿卿，為博士、州牧、郡守，家世傳業。小戴授梁人橋仁季卿、楊榮子孫。〔三〕仁為大鴻臚，家世傳業，榮琅邪太守。由是大戴有徐氏，小戴有橋、楊氏之學。","sentenceOrder":202},
  {"id":"s_work_han_thu_102_203","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　服虔曰：「在曲臺校書著記，因以為名。」師古曰：「曲臺殿在未央宮。」","sentenceOrder":203},
  {"id":"s_work_han_thu_102_204","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　如淳曰：「聞人，姓也，名通漢，字子方。」","sentenceOrder":204},
  {"id":"s_work_han_thu_102_205","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「子孫，榮之字也。」","sentenceOrder":205},
  {"id":"s_work_han_thu_102_206","chapterId":"ch_work_han_thu_102","textTraditional":"胡母生字子都，齊人也。治公羊春秋，為景帝博士。與董仲舒同業，仲舒著書稱其德。年老，歸教於齊，齊之言春秋者宗事之，公孫弘亦頗受焉。而董生為江都相，自有傳。弟子遂之者，蘭陵褚大，東平嬴公，廣川段仲，溫呂步舒。〔一〕大至梁相，步舒丞相長史，唯嬴公守學不失師法，為昭帝諫大夫，授東海孟卿、魯眭孟。孟為符節令，坐說災異誅，自有傳。","sentenceOrder":206},
  {"id":"s_work_han_thu_102_207","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「遂謂名位成達者。」","sentenceOrder":207},
  {"id":"s_work_han_thu_102_208","chapterId":"ch_work_han_thu_102","textTraditional":"嚴彭祖字公子，東海下邳人也。與顏安樂俱事眭孟。孟弟子百餘人，唯彭祖、安樂為明，質問疑誼，各持所見。孟曰：「春秋之意，在二子矣！」孟死，彭祖、安樂各顓門教授。〔一〕由是公羊春秋有顏、嚴之學。彭祖為宣帝博士，至河南、東郡太守。以高第入為左馮翊，遷太子太傅，廉直不事權貴。或說曰：「天時不勝人事，君以不修小禮曲意，亡貴人左右之助，經誼雖高，不至宰相。願少自勉強！」彭祖曰：「凡通經術，固當修行先王之道，何可委曲從俗，苟求富貴乎！」彭祖竟以太傅官終。授琅邪王中，為元帝少府，〔二〕家世傳業。中授同郡公孫文、東門雲。雲為荊州刺史，文東平太傅，徒眾尤盛。雲坐為江賊拜辱命，下獄誅。〔三〕","sentenceOrder":208},
  {"id":"s_work_han_thu_102_209","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「顓與專同。專門言各自名家。」","sentenceOrder":209},
  {"id":"s_work_han_thu_102_210","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「中讀曰仲。」","sentenceOrder":210},
  {"id":"s_work_han_thu_102_211","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「逢見賊而拜也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_102_212","chapterId":"ch_work_han_thu_102","textTraditional":"顏安樂字公孫，魯國薛人，眭孟姊子也。家貧，為學精力，官至齊郡太守丞，後為仇家所殺。安樂授淮陽泠豐次君、〔一〕淄川任公。公為少府，豐淄川太守。由是顏家有泠、任之學。始貢禹事嬴公，成於眭孟，至御史大夫，疏廣事孟卿，至太子太傅，皆自有傳。廣授琅邪筦路，〔二〕路為御史中丞。禹授潁川堂谿惠，〔三〕惠授泰山冥都，〔四〕都為丞相史。都與路又事顏安樂，故顏氏復有筦、冥之學。路授孫寶，為大司農，自有傳。豐授馬宮、琅邪左咸。咸為郡守九卿，徒眾尤盛。（官）〔宮〕至大司徒，自有傳。","sentenceOrder":212},
  {"id":"s_work_han_thu_102_213","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「泠音零。」","sentenceOrder":213},
  {"id":"s_work_han_thu_102_214","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「筦亦管字也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_102_215","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「姓堂谿也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_102_216","chapterId":"ch_work_han_thu_102","textTraditional":"〔四〕　師古曰：「冥音莫零反。」","sentenceOrder":216},
  {"id":"s_work_han_thu_102_217","chapterId":"ch_work_han_thu_102","textTraditional":"瑕丘江公受穀梁春秋及詩於魯申公，傳子至孫為博士。武帝時，江公與董仲舒並。仲舒通五經，能持論，善屬文。江公吶於口，〔一〕上使與仲舒議，不如仲舒。而丞相公孫弘本為公羊學，比輯其議，卒用董生。〔二〕於是上因尊公羊家，詔太子受公羊春秋，由是公羊大興。太子既通，復私問穀梁而善之。其後浸微，〔三〕唯魯榮廣王孫、皓星公二人受焉。廣盡能傳其詩、春秋，高材捷敏，與公羊大師眭孟等論，數困之，〔四〕故好學者頗復受穀梁。沛蔡千秋少君、梁周慶幼君、丁姓子孫〔五〕皆從廣受。千秋又事皓星公，為學最篤。宣帝即位，聞衛太子好穀梁春秋，以問丞相韋賢、長信少府夏侯勝及侍中樂陵侯史高，皆魯人也，言穀梁子本魯學，公羊氏乃齊學也，宜興穀梁。時千秋為郎，召見，與公羊家並說，上善穀梁說，擢千秋為諫大夫給事中，後有過，左遷平陵令。復求能為穀梁者，莫及千秋。上愍其學且絕，乃以千秋為郎中戶將，〔六〕選郎十人從受。汝南尹更始翁君本自事千秋，能說矣，會千秋病死，徵江公孫為博士。劉向以故諫大夫通達待詔，受穀梁，欲令助之。江博士復死，乃徵周慶、丁姓待詔保宮，〔七〕使卒授十人。自元康中始講，至甘露元年，積十餘歲，皆明習。乃召五經名儒太子太傅蕭望之等大議殿中，平公羊、穀梁同異，各以經處是非。時公羊博士嚴彭祖、侍郎申輓、伊推、宋顯，〔八〕穀梁議郎尹更始、待詔劉向、周慶、丁姓並論。公羊家多不見從，願請內侍郎許廣，使者亦並內穀梁家中郎王亥，各五人，〔九〕議三十餘事。望之等十一人各以經誼對，多從穀梁。由是穀梁之學大盛。慶、姓皆為博士。〔一０〕姓至中山太傅，授楚申章昌曼君，〔一一〕為博士，至長沙太傅，徒眾尤盛。尹更始為諫大夫、長樂戶將，又受左氏傳，取其變理合者以為章句，傳子咸及翟方進、琅邪房鳳。咸至大司農，方進丞相，自有傳。","sentenceOrder":217},
  {"id":"s_work_han_thu_102_218","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「屬音之欲反。吶，古訥字。」","sentenceOrder":218},
  {"id":"s_work_han_thu_102_219","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「比，次也。輯，合也。比音頻寐反。輯與集同。」","sentenceOrder":219},
  {"id":"s_work_han_thu_102_220","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「浸，漸也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_102_221","chapterId":"ch_work_han_thu_102","textTraditional":"〔四〕　師古曰：「孟等窮屈也。」","sentenceOrder":221},
  {"id":"s_work_han_thu_102_222","chapterId":"ch_work_han_thu_102","textTraditional":"〔五〕　師古曰：「姓丁，名姓，字子孫。」","sentenceOrder":222},
  {"id":"s_work_han_thu_102_223","chapterId":"ch_work_han_thu_102","textTraditional":"〔六〕　師古曰：「戶將，官名，解在楊惲、蓋寬饒傳。」","sentenceOrder":223},
  {"id":"s_work_han_thu_102_224","chapterId":"ch_work_han_thu_102","textTraditional":"〔七〕　師古曰：「保宮，少府之屬宮也，本名居室。」","sentenceOrder":224},
  {"id":"s_work_han_thu_102_225","chapterId":"ch_work_han_thu_102","textTraditional":"〔八〕　師古曰：「輓音晚。」","sentenceOrder":225},
  {"id":"s_work_han_thu_102_226","chapterId":"ch_work_han_thu_102","textTraditional":"〔九〕　師古曰：「使者，謂當時詔遣監議者也。內（外）〔謂〕引入議所也。公羊家既請內許廣，而使者因並內王亥也。」","sentenceOrder":226},
  {"id":"s_work_han_thu_102_227","chapterId":"ch_work_han_thu_102","textTraditional":"〔一０〕師古曰：「周慶、丁姓，二人也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_102_228","chapterId":"ch_work_han_thu_102","textTraditional":"〔一一〕李奇曰：「姓申章，名昌，字曼君。」","sentenceOrder":228},
  {"id":"s_work_han_thu_102_229","chapterId":"ch_work_han_thu_102","textTraditional":"房鳳字子元，不其人也。〔一〕以射策乙科為太史掌故。太常舉方正，為縣令都尉，失官。大司馬票騎將軍王根奏除補長史，薦鳳明經通達，擢為光祿大夫，遷五官中郎將。時光祿勳王龔以外屬內卿，〔二〕與奉車都尉劉歆共校書，三人皆侍中。歆白左氏春秋可立，哀帝納之，以問諸儒，皆不對。歆於是數見丞相孔光，為言左氏以求助，光卒不肯。唯鳳、龔許歆，遂共移書責讓太常博士，語在歆傳。大司空師丹奏歆非毀先帝所立，上於是出龔等補吏，龔為弘農，歆河內，鳳九江太守，至青州牧。始江博士授胡常，常授梁蕭秉君房，王莽時為講學大夫。由是穀梁春秋有尹、胡、申章、房氏之學。","sentenceOrder":229},
  {"id":"s_work_han_thu_102_230","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「琅邪之縣也。其音基。」","sentenceOrder":230},
  {"id":"s_work_han_thu_102_231","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　如淳曰：「邛成太后親也。內卿光祿勳治宮中。」","sentenceOrder":231},
  {"id":"s_work_han_thu_102_232","chapterId":"ch_work_han_thu_102","textTraditional":"漢興，北平侯張蒼及梁太傅賈誼、京兆尹張敞、太中大夫劉公子皆修春秋左氏傳。誼為左氏傳訓故，授趙人貫公，為河間獻王博士，子長卿為蕩陰令，〔一〕授清河張禹長子。〔二〕禹與蕭望之同時為御史，數為望之言左氏，望之善之，上書數以稱說。後望之為太子太傅，薦禹於宣帝，徵禹待詔，未及問，會疾死。授尹更始，〔三〕更始傳子咸及翟方進、胡常。常授黎陽賈護季君，哀帝時待詔為郎，授蒼梧陳欽子佚，以左氏授王莽，至將軍。而劉歆從尹咸及翟方進受。由是言左氏者本之賈護、劉歆。","sentenceOrder":232},
  {"id":"s_work_han_thu_102_233","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「蕩陰，河內之縣也。蕩音湯。」","sentenceOrder":233},
  {"id":"s_work_han_thu_102_234","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　如淳曰：「非成帝師張禹也。」","sentenceOrder":234},
  {"id":"s_work_han_thu_102_235","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　師古曰：「禹先授更始。」","sentenceOrder":235},
  {"id":"s_work_han_thu_102_236","chapterId":"ch_work_han_thu_102","textTraditional":"贊曰：自武帝立五經博士，開弟子員，設科射策，勸以官祿，訖於元始，百有餘年，傳業者寖盛，支葉藩滋，〔一〕一經說至百餘萬言，大師眾至千餘人，蓋祿利之路然也。〔二〕初，書唯有歐陽，禮后，易楊，春秋公羊而已。至孝宣世，復立大小夏侯尚書，大小戴禮，施、孟、梁丘易，穀梁春秋。至元帝世，復立京氏易。平帝時，又立左氏春秋、毛詩、逸禮、古文尚書，所以罔羅遺失，兼而存之，是在其中矣。〔三〕","sentenceOrder":236},
  {"id":"s_work_han_thu_102_237","chapterId":"ch_work_han_thu_102","textTraditional":"〔一〕　師古曰：「寖，漸也。蕃，多也。滋，益也。」","sentenceOrder":237},
  {"id":"s_work_han_thu_102_238","chapterId":"ch_work_han_thu_102","textTraditional":"〔二〕　師古曰：「言為經學者則受爵祿而獲其利，所以益勸。」","sentenceOrder":238},
  {"id":"s_work_han_thu_102_239","chapterId":"ch_work_han_thu_102","textTraditional":"〔三〕　如淳曰：「雖有虛妄之說，是當在其中，故兼而存之。」","sentenceOrder":239},
  {"id":"s_work_han_thu_102_240","chapterId":"ch_work_han_thu_102","textTraditional":"校勘記","sentenceOrder":240},
  {"id":"s_work_han_thu_102_241","chapterId":"ch_work_han_thu_102","textTraditional":"三五八九頁　三行　六（學）〔藝〕者，　景祐本作「藝」。　王念孫說作「藝」是。","sentenceOrder":241},
  {"id":"s_work_han_thu_102_242","chapterId":"ch_work_han_thu_102","textTraditional":"三五八九頁　九行　煥乎其有文章（也）！　景祐本無「也」字，與今本論語同。","sentenceOrder":242},
  {"id":"s_work_han_thu_102_243","chapterId":"ch_work_han_thu_102","textTraditional":"三五八九頁　九行　又（云）〔曰〕：周監於二（世）〔代〕，「云」，景祐，殿本都作「曰」。「世」，景祐本作「代」，與今本論語同。","sentenceOrder":243},
  {"id":"s_work_han_thu_102_244","chapterId":"ch_work_han_thu_102","textTraditional":"三五八九頁一二行　「〈古“以”字，形似吕〉」（音以）立先王之教，　王先謙說「音以」二字後人妄加。按景祐本有，殿本無。","sentenceOrder":244},
  {"id":"s_work_han_thu_102_245","chapterId":"ch_work_han_thu_102","textTraditional":"三五九二頁　二行　魯諸儒持孔氏禮器（而）〔往〕歸之，　景祐、殿、局本都作「往」。","sentenceOrder":245},
  {"id":"s_work_han_thu_102_246","chapterId":"ch_work_han_thu_102","textTraditional":"三五九七頁　一行　商瞿子木　沈欽韓說，索隱商姓，瞿名，字子木，未有以商瞿為複姓者。","sentenceOrder":246},
  {"id":"s_work_han_thu_102_247","chapterId":"ch_work_han_thu_102","textTraditional":"三五九七頁一四行　梁人（一王）〔也。初〕梁項生從田何受易，　景祐、汲古、殿、局本都作「也初」，此誤。","sentenceOrder":247},
  {"id":"s_work_han_thu_102_248","chapterId":"ch_work_han_thu_102","textTraditional":"三五九八頁　四行　言丁寬（行）〔得〕其法術以去。　景祐、殿本都作「得」。","sentenceOrder":248},
  {"id":"s_work_han_thu_102_249","chapterId":"ch_work_han_thu_102","textTraditional":"三六０一頁一五行　楊叔〔元〕、　王先謙說，上文云楊何字叔元，藝文志班自注同，此脫「元」字。","sentenceOrder":249},
  {"id":"s_work_han_thu_102_250","chapterId":"ch_work_han_thu_102","textTraditional":"三六０八頁　九行　為治者不（至）〔在〕多言，　殿、局本都作「在」，史記同。","sentenceOrder":250},
  {"id":"s_work_han_thu_102_251","chapterId":"ch_work_han_thu_102","textTraditional":"三六０九頁　一行　事（博士）大江公及許生，　景祐本無「博士」二字。　王念孫說，據晉注，景祐本是。","sentenceOrder":251},
  {"id":"s_work_han_thu_102_252","chapterId":"ch_work_han_thu_102","textTraditional":"三六０九頁一一行　力行，（為）〔謂〕勉力為行也。　景祐、殿本都作「謂」。","sentenceOrder":252},
  {"id":"s_work_han_thu_102_253","chapterId":"ch_work_han_thu_102","textTraditional":"三六一二頁　五行　非受命（而）〔為〕何？　景祐、殿本都作「為」。朱一新說，按注則「為」字是。","sentenceOrder":253},
  {"id":"s_work_han_thu_102_254","chapterId":"ch_work_han_thu_102","textTraditional":"三六一四頁　六行　吉為昌邑〔王〕中尉，　景祐、殿本都有「王」字。","sentenceOrder":254},
  {"id":"s_work_han_thu_102_255","chapterId":"ch_work_han_thu_102","textTraditional":"三六一四頁一三行　（柏）〔桓〕生、　景祐、殿本都作「桓」。","sentenceOrder":255},
  {"id":"s_work_han_thu_102_256","chapterId":"ch_work_han_thu_102","textTraditional":"三六一七頁　六行　（官）〔宮〕至大司徒，自有傳。　劉攽說「官」當作「宮」。按劉說是，各本並誤。","sentenceOrder":256},
  {"id":"s_work_han_thu_102_257","chapterId":"ch_work_han_thu_102","textTraditional":"三六一九頁　八行　內（外）〔謂〕引入議所也。　景祐、殿、局本都作「謂」，此誤。","sentenceOrder":257},
  {"id":"s_work_han_thu_103_1","chapterId":"ch_work_han_thu_103","textTraditional":"師古曰：「循，順也，上順公法，下順人情也。」","sentenceOrder":1},
  {"id":"s_work_han_thu_103_2","chapterId":"ch_work_han_thu_103","textTraditional":"漢興之初，反秦之敝，與民休息，凡事簡易，禁罔疏闊，而相國蕭、曹以寬厚清靜為天下帥，〔一〕民作「畫一」之歌。〔二〕孝惠垂拱，高后女主，不出房闥，而天下晏然，民務稼穡，衣食滋殖〔三〕。至於文、景，遂移風易俗。是時循吏如河南守吳公、蜀守文翁之屬，皆謹身帥先，居以廉平，不至於嚴，而民從化。","sentenceOrder":2},
  {"id":"s_work_han_thu_103_3","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「帥，遵也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_103_4","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「謂歌曰：『蕭何為法，講若畫一；曹參代之，守而勿失。』」","sentenceOrder":4},
  {"id":"s_work_han_thu_103_5","chapterId":"ch_work_han_thu_103","textTraditional":"〔三〕　師古曰：「滋，益也。殖，生也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_103_6","chapterId":"ch_work_han_thu_103","textTraditional":"孝武之世，外攘四夷，內改法度，〔一〕民用彫敝，姦軌不禁。〔二〕時少能以化治稱者，惟江都相董仲舒、內史公孫弘、兒寬，居官可紀。三人皆儒者，通於世務，明習文法，以經術潤飾吏事，天子器之。仲舒數謝病去，弘、寬至三公。","sentenceOrder":6},
  {"id":"s_work_han_thu_103_7","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「攘，卻也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_103_8","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「不可禁。」","sentenceOrder":8},
  {"id":"s_work_han_thu_103_9","chapterId":"ch_work_han_thu_103","textTraditional":"孝昭幼沖，霍光秉政，承奢侈師旅之後，海內虛耗，光因循守職，無所改作。至於始元、元鳳之間，匈奴鄉化，百姓益富，〔一〕舉賢良文學，問民所疾苦，於是罷酒榷而議鹽鐵矣。","sentenceOrder":9},
  {"id":"s_work_han_thu_103_10","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":10},
  {"id":"s_work_han_thu_103_11","chapterId":"ch_work_han_thu_103","textTraditional":"及至孝宣，繇仄陋而登至尊，〔一〕興于閭閻，〔二〕知民事之囏難。自霍光薨後始躬萬機，厲精為治，五日一聽事，自丞相已下各奉職而進。及拜刺史守相，輒親見問，觀其所繇，退而考察所行以質其言，〔三〕有名實不相應，必知其所以然。常稱曰：「庶民所以安其田里而亡歎息愁恨之心者，政平訟理也。〔四〕與我共此者，其唯良二千石乎！」〔五〕以為太守，吏民之本也，數變易則下不安，民知其將久，不可欺罔，乃服從其教化。故二千石有治理效，輒以璽書勉厲，增秩賜金，或爵至關內侯，公卿缺則選諸所表以次用之。〔六〕是故漢世良吏，於是為盛，稱中興焉。若趙廣漢、韓延壽、尹翁歸、嚴延年、張敞之屬，皆稱其位，然任刑罰，或抵罪誅。〔七〕王成、黃霸、朱邑、龔遂、鄭弘、召信臣等，〔八〕所居民富，所去見思，生有榮號，死見奉祀，此廩廩庶幾德讓君子之遺風矣。〔九〕","sentenceOrder":11},
  {"id":"s_work_han_thu_103_12","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「仄，古側字。仄陋，言非正統，而身經微賤也。繇與由同。次下類此。」","sentenceOrder":12},
  {"id":"s_work_han_thu_103_13","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「閭，里門也。閻，里中門也。言從里巷而即大位也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_103_14","chapterId":"ch_work_han_thu_103","textTraditional":"〔三〕　師古曰：「質，正也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_103_15","chapterId":"ch_work_han_thu_103","textTraditional":"〔四〕　師古曰：「訟理，言所訟見理而無冤滯也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_103_16","chapterId":"ch_work_han_thu_103","textTraditional":"〔五〕　師古曰：「謂郡守、諸侯相。」","sentenceOrder":16},
  {"id":"s_work_han_thu_103_17","chapterId":"ch_work_han_thu_103","textTraditional":"〔六〕　師古曰：「所表，謂增秩賜金爵也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_103_18","chapterId":"ch_work_han_thu_103","textTraditional":"〔七〕　師古曰：「抵，至也，音丁禮反。」","sentenceOrder":18},
  {"id":"s_work_han_thu_103_19","chapterId":"ch_work_han_thu_103","textTraditional":"〔八〕　師古曰：「召讀曰邵。」","sentenceOrder":19},
  {"id":"s_work_han_thu_103_20","chapterId":"ch_work_han_thu_103","textTraditional":"〔九〕　師古曰：「廩廩，言有風采也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_103_21","chapterId":"ch_work_han_thu_103","textTraditional":"文翁，廬江舒人也。少好學，通春秋，以郡縣吏察舉。景帝末，為蜀郡守，仁愛好教化。見蜀地辟陋有蠻夷風，〔一〕文翁欲誘進之，乃選郡縣小吏開敏有材者張叔等十餘人親自飭厲，〔二〕遣詣京師，受業博士，或學律令。減省少府用度，買刀布蜀物，齎計吏以遺博士。〔三〕數歲，蜀生皆成就還歸，文翁以為右職，〔四〕用次察舉，官有至郡守刺史者。","sentenceOrder":21},
  {"id":"s_work_han_thu_103_22","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「辟讀曰僻。」","sentenceOrder":22},
  {"id":"s_work_han_thu_103_23","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「飭與敕同。」","sentenceOrder":23},
  {"id":"s_work_han_thu_103_24","chapterId":"ch_work_han_thu_103","textTraditional":"〔三〕　如淳曰：「金馬書刀，今賜計吏是也。作馬形於刀環內，以金鏤之。」晉灼曰：「刀，書刀；布，布刀也。舊時蜀郡工官作金馬書刀者，似佩刀形，金錯其拊。布刀，謂婦人割裂財布刀也。」師古曰：「少府，郡掌財物之府，以供太守者也。刀，凡蜀刀有環者也。布，蜀布細密（環）也。二者蜀人作之皆善，故齎以為貨，無限於書刀布刀也。如、晉二說皆煩而不當也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_103_25","chapterId":"ch_work_han_thu_103","textTraditional":"〔四〕　師古曰：「郡中高職也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_103_26","chapterId":"ch_work_han_thu_103","textTraditional":"又修起學官於成都市中，〔一〕招下縣子弟以為學官弟子，〔二〕為除更繇，〔三〕高者以補郡縣吏，次為孝弟力田。常選學官僮子，使在便坐受事。〔四〕每出行縣，益從學官諸生明經飭行者與俱，〔五〕使傳教令，出入閨閤。〔六〕縣邑吏民見而榮之，數年，爭欲為學官弟子，富人至出錢以求之。繇是大化，〔七〕蜀地學於京師者比齊魯焉。至武帝時，乃令天下郡國皆立學校官，自文翁為之始云。","sentenceOrder":26},
  {"id":"s_work_han_thu_103_27","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「學官，學之官舍也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_103_28","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「下縣，四郊之縣，非郡所治也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_103_29","chapterId":"ch_work_han_thu_103","textTraditional":"〔三〕　師古曰：「不令從役也。更音工衡反。繇讀曰徭。」","sentenceOrder":29},
  {"id":"s_work_han_thu_103_30","chapterId":"ch_work_han_thu_103","textTraditional":"〔四〕　師古曰：「便坐，別坐，可以視事，非正廷也。坐音財臥反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_103_31","chapterId":"ch_work_han_thu_103","textTraditional":"〔五〕　師古曰：「益，多也。飭，整也，讀與敕同。」","sentenceOrder":31},
  {"id":"s_work_han_thu_103_32","chapterId":"ch_work_han_thu_103","textTraditional":"〔六〕　師古曰：「閨閤，內中小門也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_103_33","chapterId":"ch_work_han_thu_103","textTraditional":"〔七〕　師古曰：「繇讀曰由。」","sentenceOrder":33},
  {"id":"s_work_han_thu_103_34","chapterId":"ch_work_han_thu_103","textTraditional":"文翁終於蜀，吏民為立祠堂，歲時祭祀不絕。至今巴蜀好文雅，文翁之化也。〔一〕","sentenceOrder":34},
  {"id":"s_work_han_thu_103_35","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「文翁學堂于今猶在益州城內。」","sentenceOrder":35},
  {"id":"s_work_han_thu_103_36","chapterId":"ch_work_han_thu_103","textTraditional":"王成，不知何郡人也。為膠東相，治甚有聲。宣帝最先褒之，地節三年下詔曰：「蓋聞有功不賞，有罪不誅，雖唐虞不能以化天下。今膠東相成，勞來不怠，〔一〕流民自占八萬餘口，〔二〕治有異等之效。〔三〕其賜成爵關內侯，秩中二千石。」未及徵用，會病卒官。後詔使丞相御史問郡國上計長吏守丞以政令得失，或對言前膠東相成偽自增加，以蒙顯賞，是後俗吏多為虛名云。","sentenceOrder":36},
  {"id":"s_work_han_thu_103_37","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「謂勸勉招懷百姓也。勞音郎到反。來音郎代反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_103_38","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「隱度名數而來附業也。占音之贍反。」","sentenceOrder":38},
  {"id":"s_work_han_thu_103_39","chapterId":"ch_work_han_thu_103","textTraditional":"〔三〕　師古曰：「異於常等。」","sentenceOrder":39},
  {"id":"s_work_han_thu_103_40","chapterId":"ch_work_han_thu_103","textTraditional":"黃霸字次公，淮陽陽夏人也，〔一〕以豪桀役使徙雲陵。〔二〕霸少學律令，喜為吏，〔三〕武帝末以待詔入錢賞官，補侍郎謁者，〔四〕坐同產有罪劾免。〔五〕後復入穀沈黎郡，補左馮翊二百石卒史。〔六〕馮翊以霸入財為官，不署右職，〔七〕使領郡錢穀計〔八〕。簿書正，以廉稱，〔九〕察補河東均輸長，〔一０〕復察廉為河南太守丞。霸為人明察內敏，〔一一〕又習文法，然溫良有讓，足知，善御眾。為丞，處議當於法，合人心，太守甚任之，吏民愛敬焉。","sentenceOrder":40},
  {"id":"s_work_han_thu_103_41","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「夏音工雅反。」","sentenceOrder":41},
  {"id":"s_work_han_thu_103_42","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「身為豪桀而役使鄉里人也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_103_43","chapterId":"ch_work_han_thu_103","textTraditional":"〔三〕　師古曰：「喜謂愛好也，音許吏反。」","sentenceOrder":43},
  {"id":"s_work_han_thu_103_44","chapterId":"ch_work_han_thu_103","textTraditional":"〔四〕　孟康曰：「賞官，主賞賜之官也。」師古曰：「此說非也，因入錢而見賞以官。」","sentenceOrder":44},
  {"id":"s_work_han_thu_103_45","chapterId":"ch_work_han_thu_103","textTraditional":"〔五〕　師古曰：「同產謂兄弟也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_103_46","chapterId":"ch_work_han_thu_103","textTraditional":"〔六〕　如淳曰：「三輔郡得仕用它郡人，而卒史獨二百石，所謂尤異者也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_103_47","chapterId":"ch_work_han_thu_103","textTraditional":"〔七〕　師古曰：「輕其為人也。右職，高職也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_103_48","chapterId":"ch_work_han_thu_103","textTraditional":"〔八〕　師古曰：「計謂出入之數也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_103_49","chapterId":"ch_work_han_thu_103","textTraditional":"〔九〕　師古曰：「言無所侵隱，故簿書皆正，不虛謬也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_103_50","chapterId":"ch_work_han_thu_103","textTraditional":"〔一０〕師古曰：「以廉見察而遷補。」","sentenceOrder":50},
  {"id":"s_work_han_thu_103_51","chapterId":"ch_work_han_thu_103","textTraditional":"〔一一〕師古曰：「內敏，言心思捷疾也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_103_52","chapterId":"ch_work_han_thu_103","textTraditional":"自武帝末，用法深。昭帝立，幼，大將軍霍光秉政，大臣爭權，上官桀等與燕王謀作亂，光既誅之，遂遵武帝法度，以刑罰痛繩群下，繇是俗吏上嚴酷以為能，〔一〕而霸獨用寬和為名。","sentenceOrder":52},
  {"id":"s_work_han_thu_103_53","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「繇讀與由同。」","sentenceOrder":53},
  {"id":"s_work_han_thu_103_54","chapterId":"ch_work_han_thu_103","textTraditional":"會宣帝即位，在民間時知百姓苦吏急也，聞霸持法平，召以為廷尉正，數決疑獄，庭中稱平。〔一〕守丞相長史，坐公卿大議廷中〔二〕知長信少府夏侯勝非議詔書大不敬，霸阿從不舉劾，皆下廷尉，〔三〕繫獄當死。霸因從勝受尚書獄中，再隃冬，〔四〕積三歲乃出，語在勝傳。勝出，復為諫大夫，令左馮翊宋畸舉霸賢良。勝又口薦霸於上，上擢霸為揚州刺史。三歲，宣帝下詔曰：「制詔御史：其以賢良高第揚州刺史霸為潁川太守，秩比二千石，居官賜車蓋，特高一丈，別駕主簿車，緹油屏泥於軾前，以章有德。」","sentenceOrder":54},
  {"id":"s_work_han_thu_103_55","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「此廷中謂廷尉之中。」","sentenceOrder":55},
  {"id":"s_work_han_thu_103_56","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「大議，總會議也。此廷中謂朝廷之中。」","sentenceOrder":56},
  {"id":"s_work_han_thu_103_57","chapterId":"ch_work_han_thu_103","textTraditional":"〔三〕　師古曰：「勝及霸俱下廷尉。」","sentenceOrder":57},
  {"id":"s_work_han_thu_103_58","chapterId":"ch_work_han_thu_103","textTraditional":"〔四〕師古曰：「隃與踰同。」","sentenceOrder":58},
  {"id":"s_work_han_thu_103_59","chapterId":"ch_work_han_thu_103","textTraditional":"時上垂意於治，數下恩澤詔書，吏不奉宣。〔一〕太守霸為選擇良吏，分部宣布詔令，〔二〕令民咸知上意。使郵亭鄉官皆畜雞豚，〔三〕以贍鰥寡貧窮者，然後為條教，置父老師帥伍長，班行之於民間，勸以為善防姦之意，及務耕桑，節用殖財，種樹畜養，去食穀馬。米鹽靡密，初若煩碎，〔四〕然霸精力能推行之。吏民見者，語次尋繹，〔五〕問它陰伏，以相參考。嘗欲有所司察，擇長年廉吏遣行，屬令周密。〔六〕吏出，不敢舍郵亭，〔七〕食於道旁，烏攫其肉。〔八〕民有欲詣府口言事者適見之，霸與語道此。後日吏還謁霸，霸見迎勞之，曰：「甚苦！食於道旁乃為烏所盜肉。」吏大驚，以霸具知其起居，所問豪氂不敢有所隱。鰥寡孤獨有死無以葬者，鄉部書言，霸具為區處，〔九〕某所大木可以為棺，某亭豬子可以祭，吏往皆如言。其識事聰明如此，〔一０〕吏民不知所出，〔一一〕咸稱神明。姦人去入它郡，盜賊日少。","sentenceOrder":59},
  {"id":"s_work_han_thu_103_60","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「不令百姓皆知也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_103_61","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「分音扶問反。」","sentenceOrder":61},
  {"id":"s_work_han_thu_103_62","chapterId":"ch_work_han_thu_103","textTraditional":"〔三〕　師古曰：「郵行書舍，謂傳送文書所止處，亦如今之驛館矣。鄉官者，鄉所治處也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_103_63","chapterId":"ch_work_han_thu_103","textTraditional":"〔四〕　師古曰：「米鹽，言碎而且細。」","sentenceOrder":63},
  {"id":"s_work_han_thu_103_64","chapterId":"ch_work_han_thu_103","textTraditional":"〔五〕　師古曰：「繹謂抽引而出也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_103_65","chapterId":"ch_work_han_thu_103","textTraditional":"〔六〕　師古曰：「屬，戒也。周密，不泄（陋）〔漏〕也。屬音之欲反。」","sentenceOrder":65},
  {"id":"s_work_han_thu_103_66","chapterId":"ch_work_han_thu_103","textTraditional":"〔七〕　師古曰：「舍，止也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_103_67","chapterId":"ch_work_han_thu_103","textTraditional":"〔八〕　師古曰：「攫，搏持之也。攫音钁。」","sentenceOrder":67},
  {"id":"s_work_han_thu_103_68","chapterId":"ch_work_han_thu_103","textTraditional":"〔九〕　師古曰：「區處謂分別而處置也，音昌汝反。」","sentenceOrder":68},
  {"id":"s_work_han_thu_103_69","chapterId":"ch_work_han_thu_103","textTraditional":"〔一０〕師古曰：「識，記也，音式二反。」","sentenceOrder":69},
  {"id":"s_work_han_thu_103_70","chapterId":"ch_work_han_thu_103","textTraditional":"〔一一〕師古曰：「不知其用何術也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_103_71","chapterId":"ch_work_han_thu_103","textTraditional":"霸力行教化而後誅罰，〔一〕務在成就全安長吏。〔二〕許丞老，病聾，〔三〕督郵白欲逐之，霸曰：「許丞廉吏，雖老，尚能拜起送迎，正頗重聽，何傷？且善助之，毋失賢者意。」或問其故，霸曰：「數易長吏，送故迎新之費及姦吏緣絕簿書盜財物，〔四〕公私費耗甚多，皆當出於民，所易新吏又未必賢，或不如其故，徒相益為亂。凡治道，去其泰甚者耳。」","sentenceOrder":71},
  {"id":"s_work_han_thu_103_72","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「力猶勤也。言先以德教化於下，若有弗從，然後用刑罰也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_103_73","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「不欲易代及損傷之也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_103_74","chapterId":"ch_work_han_thu_103","textTraditional":"〔三〕　如淳曰：「許縣丞。」","sentenceOrder":74},
  {"id":"s_work_han_thu_103_75","chapterId":"ch_work_han_thu_103","textTraditional":"〔四〕　師古曰：「緣，因也。因交代之際而棄匿簿書以盜官物也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_103_76","chapterId":"ch_work_han_thu_103","textTraditional":"霸以外寬內明得吏民心，戶口歲增，治為天下第一。徵守京兆尹，秩二千石。坐發民治馳道不先以聞，又發騎士詣北軍馬不適士〔一〕，劾乏軍興，連貶秩。有詔歸潁川太守官，以八百石居治如其前。前後八年，郡中愈治。是時鳳皇神爵數集郡國，潁川尤多。天子以霸治行終長者，下詔稱揚曰：「穎川太守霸，宣布詔令，百姓鄉化〔二〕，孝子弟弟貞婦順孫日以眾多，田者讓畔，道不拾遺，養視鰥寡，贍助貧窮，獄或八年亡重罪囚，吏民鄉于教化，興於行誼，可謂賢人君子矣。書不云乎？『股肱良哉！』〔三〕其賜爵關內侯，黃金百斤，秩中二千石。」而潁川孝弟有行義民、三老、力田，皆以差賜爵及帛。後數月，徵霸為太子太傅，遷御史大夫。","sentenceOrder":76},
  {"id":"s_work_han_thu_103_77","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　孟康曰：「關西人謂補滿為適。馬少士多，不相補滿也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_103_78","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「鄉讀曰嚮。下亦同。」","sentenceOrder":78},
  {"id":"s_work_han_thu_103_79","chapterId":"ch_work_han_thu_103","textTraditional":"〔三〕　師古曰：「虞書益稷之辭，已解於上。」","sentenceOrder":79},
  {"id":"s_work_han_thu_103_80","chapterId":"ch_work_han_thu_103","textTraditional":"五鳳三年，代丙吉為丞相，封建成侯，食邑六百戶。霸材長於治民，及為丞相，總綱紀號令，風采不及丙、魏、于定國，功名損於治郡。時京兆尹張敞舍鶡雀飛集丞相府，〔一〕霸以為神雀，議欲以聞。敞奏霸曰：「竊見丞相請與中二千石博士雜問郡國上計長吏守丞，為民興利除害成大化條其對，有耕者讓畔，男女異路，道不拾遺，及舉孝子弟弟貞婦者為一輩，先上殿，〔二〕舉而不知其人數者次之，不為條教者在後叩頭謝。丞相雖口不言，而心欲其為之也。長吏守丞對時，臣敞舍有鶡雀飛止丞相府屋上，丞相以下見者數百人。邊吏多知鶡雀者，問之，皆陽不知。丞相圖議上奏〔三〕曰：『臣問上計長吏守丞以興化條，〔四〕皇天報下神雀。』後知從臣敞舍來，乃止。郡國吏竊笑丞相仁厚有知略，微信奇怪也。昔汲黯為淮陽守，辭去之官，謂大行李息曰：『御史大夫張湯懷詐阿意，以傾朝廷，公不早白，與俱受戮矣。』息畏湯，終不敢言。後湯誅敗，上聞黯與息語，乃抵息罪而秩黯諸侯相，取其思竭忠也。臣敞非敢毀丞相也，誠恐群臣莫白，而長吏守丞畏丞相指，歸舍法令，各為私教，〔五〕務相增加，澆淳散樸，〔六〕並行偽貌，有名亡實，傾搖解怠，甚者為妖〔七〕。假令京師先行讓畔異路，道不拾遺，其實亡益廉貪貞淫之行，而以偽先天下，固未可也；即諸侯先行之，偽聲軼於京師，非細事也。〔八〕漢家承敝通變，造起律令，所以勸善禁姦，條貫詳備，不可復加。宜令貴臣明飭長吏守丞，〔九〕歸告二千石，舉三老孝弟力田孝廉廉吏務得其人，郡事皆以義法令撿式，〔一０〕毋得擅為條教；敢挾詐偽以奸名譽者，必先受戮，〔一一〕以正明好惡。」天子嘉納敞言，召上計吏，使侍中臨飭如敞指意。霸甚慚。","sentenceOrder":80},
  {"id":"s_work_han_thu_103_81","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　蘇林曰：「令虎賁所著鶡也。」師古曰：「蘇說非也。此鶡音芬，字本作鳻，此通用耳。鳻雀大而色青，出羌中，非武賁所著也。武賁鶡色黑，出上黨，以其鬥死不止，故用其尾飾武臣首云。今時俗人所謂鶡雞者也，音曷，非此鳻雀也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_103_82","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「丞相所坐屋也。古者屋之高嚴，通呼為殿，不必宮中也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_103_83","chapterId":"ch_work_han_thu_103","textTraditional":"〔三〕　師古曰：「圖，謀也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_103_84","chapterId":"ch_work_han_thu_103","textTraditional":"〔四〕　師古曰：「凡言條者，一一而疏舉之，若木條然也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_103_85","chapterId":"ch_work_han_thu_103","textTraditional":"〔五〕　師古曰：「舍，廢也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_103_86","chapterId":"ch_work_han_thu_103","textTraditional":"〔六〕　師古曰：「不雜為淳。以水澆之，則味（離）〔漓〕薄。樸，大質也，割之，散也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_103_87","chapterId":"ch_work_han_thu_103","textTraditional":"〔七〕　師古曰：「解讀曰懈。」","sentenceOrder":87},
  {"id":"s_work_han_thu_103_88","chapterId":"ch_work_han_thu_103","textTraditional":"〔八〕　師古曰：「軼，過也，音逸。」","sentenceOrder":88},
  {"id":"s_work_han_thu_103_89","chapterId":"ch_work_han_thu_103","textTraditional":"〔九〕　師古曰：「飭讀與敕同。次下類此。」","sentenceOrder":89},
  {"id":"s_work_han_thu_103_90","chapterId":"ch_work_han_thu_103","textTraditional":"〔一０〕師古曰：「撿，局也，音居儉反。」","sentenceOrder":90},
  {"id":"s_work_han_thu_103_91","chapterId":"ch_work_han_thu_103","textTraditional":"〔一一〕師古曰：「奸，求也，音干。」","sentenceOrder":91},
  {"id":"s_work_han_thu_103_92","chapterId":"ch_work_han_thu_103","textTraditional":"又樂陵侯史高以外屬舊恩侍中貴重，霸薦高可太尉。天子使尚書召問霸：「太尉官罷久矣，丞相兼之，所以偃武興文也。如國家不虞，邊境有事，〔一〕左右之臣皆將率也。夫宣明教化，通達幽隱，使獄無冤刑，邑無盜賊，君之職也。將相之官，朕之任焉。〔二〕侍中樂陵侯高帷幄近臣，朕之所自親，〔三〕君何越職而舉之？」尚書令受丞相對，霸免冠謝罪，數日乃決。〔四〕自是後不敢復有所請。然自漢興，言治民吏，以霸為首。","sentenceOrder":92},
  {"id":"s_work_han_thu_103_93","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「如，若也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_103_94","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「言欲拜將相事，自在朕也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_103_95","chapterId":"ch_work_han_thu_103","textTraditional":"〔三〕　師古曰：「具知其材質。」","sentenceOrder":95},
  {"id":"s_work_han_thu_103_96","chapterId":"ch_work_han_thu_103","textTraditional":"〔四〕　師古曰：「乃得免罪。」","sentenceOrder":96},
  {"id":"s_work_han_thu_103_97","chapterId":"ch_work_han_thu_103","textTraditional":"為丞相五歲，甘露三年薨，諡曰定侯。霸死後，樂陵侯高竟為大司馬。〔一〕霸子思侯賞嗣，為關都尉。薨，子忠侯輔嗣，至衛尉九卿。薨，子忠嗣侯，訖王莽乃絕。子孫為吏二千石者五六人。","sentenceOrder":97},
  {"id":"s_work_han_thu_103_98","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「史著此者，亦言霸奏高為太尉，適事宜也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_103_99","chapterId":"ch_work_han_thu_103","textTraditional":"始霸少為陽夏游徼，〔一〕與善相人者共載出，〔二〕見一婦人，相者言「此婦人當富貴，不然，相書不可用也。」霸推問之，乃其鄉里巫家女也。霸即取為妻，與之終身。為丞相後徙杜陵。","sentenceOrder":99},
  {"id":"s_work_han_thu_103_100","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「游徼，主徼巡盜賊者也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_103_101","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「同乘車。」","sentenceOrder":101},
  {"id":"s_work_han_thu_103_102","chapterId":"ch_work_han_thu_103","textTraditional":"朱邑字仲卿，廬江舒人也。少時為舒桐鄉嗇夫，廉平不苛，以愛利為行，〔一〕未嘗笞辱人，存問耆老孤寡，遇之有恩，所部吏民愛敬焉。遷補太守卒史，舉賢良為大司農丞，遷北海太守，以治行第一入為大司農。為人淳厚，篤於故舊，然性公正，不可交以私。天子器之，朝延敬焉。","sentenceOrder":102},
  {"id":"s_work_han_thu_103_103","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕師古曰：「仁愛於人而安利也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_103_104","chapterId":"ch_work_han_thu_103","textTraditional":"是時張敞為膠東相，與邑書曰：「明主游心太古，廣延茂士〔一〕，此誠忠臣謁思之時也。直敞遠守劇郡，馭於繩墨，〔二〕匈臆約結，固亡奇也。〔三〕雖有，亦安所施？〔四〕足下以清明之德，掌周稷之業，〔五〕猶飢者甘糟糠，穰歲餘粱肉。〔六〕何則？有亡之勢異也。昔陳平雖賢，須魏倩而後進；〔七〕韓信雖奇，賴蕭公而後信。〔八〕故事各達其時之英俊，若必伊尹、呂望而後薦之，則此人不因足下而進矣。」〔九〕邑感敞言，貢薦賢士大夫，多得其助者。身為列卿，居處儉節，祿賜以共九族鄉黨，〔一０〕家亡餘財。","sentenceOrder":104},
  {"id":"s_work_han_thu_103_105","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「茂，善也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_103_106","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「直讀曰值。」","sentenceOrder":106},
  {"id":"s_work_han_thu_103_107","chapterId":"ch_work_han_thu_103","textTraditional":"〔三〕　師古曰：「約，屈也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_103_108","chapterId":"ch_work_han_thu_103","textTraditional":"〔四〕　師古曰：「言在遠郡，無足展效也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_103_109","chapterId":"ch_work_han_thu_103","textTraditional":"〔五〕　師古曰：「司農主百穀，故云周稷之業。」","sentenceOrder":109},
  {"id":"s_work_han_thu_103_110","chapterId":"ch_work_han_thu_103","textTraditional":"〔六〕　師古曰：「穰歲，豐穰之歲。穰音攘。」","sentenceOrder":110},
  {"id":"s_work_han_thu_103_111","chapterId":"ch_work_han_thu_103","textTraditional":"〔七〕　蘇林曰：「魏無知也。」韋昭曰：「無知字也。」師古曰：「倩，士之美稱，故云魏倩也，而韋氏便以為無知之字，非也。譬猶謂汲黯為汲直黯，豈字直乎？且次下句云『賴蕭公而後信』，亦非何之字也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_103_112","chapterId":"ch_work_han_thu_103","textTraditional":"〔八〕　師古曰：「信謂為君上所信任也。一說信讀曰伸，得伸其材用也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_103_113","chapterId":"ch_work_han_thu_103","textTraditional":"〔九〕　師古曰：「言能自達也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_103_114","chapterId":"ch_work_han_thu_103","textTraditional":"〔一０〕師古曰：「共讀曰供。」","sentenceOrder":114},
  {"id":"s_work_han_thu_103_115","chapterId":"ch_work_han_thu_103","textTraditional":"神爵元年卒。天子閔惜，下詔稱揚曰：「大司農邑，廉潔守節，退食自公，亡彊外之交，束脩之餽，〔一〕可謂淑人君子。遭離凶災，朕甚閔之。〔二〕其賜邑子黃金百斤，以奉其祭祀。」","sentenceOrder":115},
  {"id":"s_work_han_thu_103_116","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「餽與饋同。」","sentenceOrder":116},
  {"id":"s_work_han_thu_103_117","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「離亦遭。」","sentenceOrder":117},
  {"id":"s_work_han_thu_103_118","chapterId":"ch_work_han_thu_103","textTraditional":"初邑病且死，屬其子〔一〕曰：「我故為桐鄉吏，其民愛我，必葬我桐鄉。後世子孫奉嘗我，不如桐鄉民。」〔二〕及死，其子葬之桐鄉西郭外，民果（然）共為邑起冢立祠，歲時祠祭，至今不絕。","sentenceOrder":118},
  {"id":"s_work_han_thu_103_119","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「屬音之欲反。」","sentenceOrder":119},
  {"id":"s_work_han_thu_103_120","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「嘗謂蒸嘗之祭。」","sentenceOrder":120},
  {"id":"s_work_han_thu_103_121","chapterId":"ch_work_han_thu_103","textTraditional":"龔遂字少卿，山陽南平陽人也。以明經為官，至昌邑郎中令，事王賀。賀動作多不正，遂為人忠厚，剛毅有大節，內諫爭於王，外責傅相，引經義，陳禍福，至於涕泣，蹇蹇亡已。〔一〕面刺王過，王至掩耳起走，曰「郎中令善媿人。」〔二〕及國中皆畏憚焉。〔三〕王嘗久與騶奴宰人游戲飲食，賞賜亡度，遂入見王，涕泣膝行，左右侍御皆出涕。王曰：「郎中令何為哭？」遂曰：「臣痛社稷危也！願賜清閒竭愚。」王辟左右，〔四〕遂曰：「大王知膠西王所以為無道亡乎？」王曰：「不知也。」曰：「臣聞膠西王有諛臣侯得，王所為儗於桀紂也，〔五〕得以為堯舜也。王說其諂諛，嘗與寑處，〔六〕唯得所言，以至於是。〔七〕今大王親近群小，漸漬邪惡所習，存亡之機，不可不慎也。臣請選郎通經術有行義者與王起居，坐則誦詩書，立則習禮容，宜有益。」王許之。遂乃選郎中張安等十人侍王。居數日，王皆（去逐）〔逐去〕安等。久之，宮中數有妖怪，王以問遂，遂以為有大憂，宮室將空，語在昌邑王傳。會昭帝崩，亡子，昌邑王賀嗣立，官屬皆徵入。王相安樂遷長樂衛尉，遂見安樂，流涕謂曰：「王立為天子，日益驕溢，諫之不復聽，今哀痛未盡，〔八〕日與近臣飲食作樂，鬥虎豹，召皮軒，車九流，驅馳東西，所為誖道〔九〕。古制寬，大臣有隱退，今去不得，陽狂恐知，身死為世戮，奈何？君，陛下故相，宜極諫爭。」王即位二十七日，卒以淫亂廢。昌邑群臣坐陷王於惡不道，皆誅，死者二百餘人，唯遂與中尉王陽以數諫爭得減死，髡為城旦。","sentenceOrder":121},
  {"id":"s_work_han_thu_103_122","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「蹇蹇，不阿順之意也。易蹇卦曰『王臣蹇蹇』。」","sentenceOrder":122},
  {"id":"s_work_han_thu_103_123","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「媿，古愧字。愧，辱也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_103_124","chapterId":"ch_work_han_thu_103","textTraditional":"〔三〕　師古曰：「王及國人皆憚之。」","sentenceOrder":124},
  {"id":"s_work_han_thu_103_125","chapterId":"ch_work_han_thu_103","textTraditional":"〔四〕　師古曰：「閒讀曰閑。辟音闢。」","sentenceOrder":125},
  {"id":"s_work_han_thu_103_126","chapterId":"ch_work_han_thu_103","textTraditional":"〔五〕　師古曰：「儗，比也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_103_127","chapterId":"ch_work_han_thu_103","textTraditional":"〔六〕　師古曰：「說讀曰悅。」","sentenceOrder":127},
  {"id":"s_work_han_thu_103_128","chapterId":"ch_work_han_thu_103","textTraditional":"〔七〕　師古曰：「唯用得之邪言，故至亡。」","sentenceOrder":128},
  {"id":"s_work_han_thu_103_129","chapterId":"ch_work_han_thu_103","textTraditional":"〔八〕　師古曰：「謂新居喪服。」","sentenceOrder":129},
  {"id":"s_work_han_thu_103_130","chapterId":"ch_work_han_thu_103","textTraditional":"〔九〕　師古曰：「誖，乖也，音布內反。」","sentenceOrder":130},
  {"id":"s_work_han_thu_103_131","chapterId":"ch_work_han_thu_103","textTraditional":"宣帝即位，久之，渤海左右郡歲飢，盜賊並起，〔一〕二千石不能禽制。上選能治者，丞相御史舉遂可用，上以為渤海太守。時遂年七十餘，召見，形貌短小，宣帝望見，不副所聞，心內輕焉，謂遂曰：「渤海廢亂，朕甚憂之。君欲何以息其盜賊，以稱朕意？」遂對曰：「海瀕遐遠，不霑聖化，〔二〕其民困於飢寒而吏不恤，故使陛下赤子盜弄陛下之兵於潢池中耳。〔三〕今欲使臣勝之邪，將安之也？」〔四〕上聞遂對，甚說，〔五〕答曰：「選用賢良，固欲安之也。」遂曰：「臣聞治亂民猶治亂繩，不可急也；唯緩之，然後可治。臣願丞相御史且無拘臣以文法，得一切便宜從事。」上許焉，加賜黃金，贈遣乘傳。至渤海界，〔六〕郡聞新太守至，發兵以迎，遂皆遣還，移書敕屬縣悉罷逐捕盜賊吏。諸持鉏鉤田器者皆為良民，吏無得問，〔七〕持兵者乃為盜賊。遂單車獨行至府，郡中翕然，盜賊亦皆罷。〔八〕渤海又多劫略相隨，聞遂教令，即時解散，棄其兵弩而持鉤鉏。盜賊於是悉平，民安土樂業。遂乃開倉廩假貧民，〔九〕選用良吏，尉安牧養焉。","sentenceOrder":131},
  {"id":"s_work_han_thu_103_132","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「左右謂側近相次者。」","sentenceOrder":132},
  {"id":"s_work_han_thu_103_133","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「瀕，涯也，音頻，又音賓。」","sentenceOrder":133},
  {"id":"s_work_han_thu_103_134","chapterId":"ch_work_han_thu_103","textTraditional":"〔三〕　師古曰：「赤子猶言初生幼小之意也。積水曰潢，（曰）〔音〕黃。」","sentenceOrder":134},
  {"id":"s_work_han_thu_103_135","chapterId":"ch_work_han_thu_103","textTraditional":"〔四〕　師古曰：「勝謂以威力克而殺之也。安謂以德化撫而安之。」","sentenceOrder":135},
  {"id":"s_work_han_thu_103_136","chapterId":"ch_work_han_thu_103","textTraditional":"〔五〕　師古曰：「說讀曰悅。」","sentenceOrder":136},
  {"id":"s_work_han_thu_103_137","chapterId":"ch_work_han_thu_103","textTraditional":"〔六〕　師古曰：「傳音張戀反。」","sentenceOrder":137},
  {"id":"s_work_han_thu_103_138","chapterId":"ch_work_han_thu_103","textTraditional":"〔七〕　師古曰：「鉤，鐮也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_103_139","chapterId":"ch_work_han_thu_103","textTraditional":"〔八〕　師古曰：「罷讀曰疲。言為盜賊久，心亦罷厭。」","sentenceOrder":139},
  {"id":"s_work_han_thu_103_140","chapterId":"ch_work_han_thu_103","textTraditional":"〔九〕　師古曰：「假謂給與。」","sentenceOrder":140},
  {"id":"s_work_han_thu_103_141","chapterId":"ch_work_han_thu_103","textTraditional":"遂見齊俗奢侈，好末技，不田作，乃躬率以儉約，勸民務農桑，令口種一樹榆、百本、五十本蔥、一畦韭，〔一〕家二母彘、五雞。〔二〕民有帶持刀劍者，使賣劍買牛，賣刀買犢，曰：「何為帶牛佩犢！」春夏不得不趨田畝，〔三〕秋冬課收斂，益蓄困實蔆芡。勞來循行，郡中皆有畜積，〔四〕吏民皆富實。獄訟止息。","sentenceOrder":141},
  {"id":"s_work_han_thu_103_142","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「每一口即如此種也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_103_143","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「每一家則如此養之也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_103_144","chapterId":"ch_work_han_thu_103","textTraditional":"〔三〕　師古曰：「趨讀曰趣。趣，嚮也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_103_145","chapterId":"ch_work_han_thu_103","textTraditional":"〔四〕　師古曰：「蔆，芰也。芡，雞頭也。勞來，勸勉也。畜讀（皆）曰蓄。芡音儉。勞音盧到反。來音盧代反。」","sentenceOrder":145},
  {"id":"s_work_han_thu_103_146","chapterId":"ch_work_han_thu_103","textTraditional":"數年，上遣使者徵遂，議曹王生願從。功曹以為王生素耆酒，亡節度，不可使。〔一〕遂不忍逆，從至京師。王生日飲酒，不視太守。〔二〕會遂引入宮，王生醉，從後呼，〔三〕曰：「明府且止，願有所白。」遂還問其故，〔四〕王生曰：「天子即問君何以治渤海，君不可有所陳對，宜曰『皆聖主之德，非小臣之力也』。」遂受其言。既至前，上果問以治狀，遂對如王生言。天子說其有讓，〔五〕笑曰：「君安得長者之言而稱之？」遂因前曰：「臣非知此，乃臣議曹教戒臣也。」上以遂年老不任公卿，拜為水衡都尉，議曹王生為水衡丞，以褒顯遂云。水衡典上林禁苑，共張宮館，〔六〕為宗廟取牲，官職親近，上甚重之，以官壽卒。〔七〕","sentenceOrder":146},
  {"id":"s_work_han_thu_103_147","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「耆讀曰嗜。」","sentenceOrder":147},
  {"id":"s_work_han_thu_103_148","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「日日恆飲酒也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_103_149","chapterId":"ch_work_han_thu_103","textTraditional":"〔三〕　師古曰：「呼音火故反。」","sentenceOrder":149},
  {"id":"s_work_han_thu_103_150","chapterId":"ch_work_han_thu_103","textTraditional":"〔四〕　師古曰：「還，回也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_103_151","chapterId":"ch_work_han_thu_103","textTraditional":"〔五〕　師古曰：「說讀曰悅。」","sentenceOrder":151},
  {"id":"s_work_han_thu_103_152","chapterId":"ch_work_han_thu_103","textTraditional":"〔六〕　師古曰：「共音居用反。張音知亮反。下亦同。」","sentenceOrder":152},
  {"id":"s_work_han_thu_103_153","chapterId":"ch_work_han_thu_103","textTraditional":"〔七〕　師古曰：「以壽終而卒於官也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_103_154","chapterId":"ch_work_han_thu_103","textTraditional":"召信臣字翁卿，九江壽春人也。〔一〕以明經甲科為郎，出補穀陽長。舉高第，遷上蔡長。其治視民如子，所居見稱述。超為零陵太守，病歸。復徵為諫大夫，遷南陽太守，其治如上蔡。","sentenceOrder":154},
  {"id":"s_work_han_thu_103_155","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕師古曰：「召讀曰（劭）〔邵〕。」","sentenceOrder":155},
  {"id":"s_work_han_thu_103_156","chapterId":"ch_work_han_thu_103","textTraditional":"信臣為人勤力有方略，好為民興利，務在富之。躬勸耕農，出入阡陌，止舍離鄉亭，〔一〕稀有安居時。行視郡中水泉，〔二〕開通溝瀆，起水門提閼凡數十處，〔三〕以廣溉灌，歲歲增加，多至三萬頃。民得其利，畜積有餘。〔四〕信臣為民作均水約束，〔五〕刻石立於田畔，以防分爭。禁止嫁娶送終奢靡，務出於儉約。府縣吏家子弟好游敖，不以田作為事，輒斥罷之，甚者案其不法，以視好惡〔六〕。其化大行，郡中莫不耕稼力田，百姓歸之，戶口增倍，盜賊獄訟衰止。吏民親愛信臣，號之曰召父。荊州刺史奏信臣為百姓興利，郡以殷富，賜黃金四十斤。遷河南太守，治行常為第一，復數增秩賜金。","sentenceOrder":156},
  {"id":"s_work_han_thu_103_157","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「言休息之時，皆在野次。」","sentenceOrder":157},
  {"id":"s_work_han_thu_103_158","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「行音下更反。」","sentenceOrder":158},
  {"id":"s_work_han_thu_103_159","chapterId":"ch_work_han_thu_103","textTraditional":"〔三〕　師古曰：「閼，所以壅水，音一曷反。」","sentenceOrder":159},
  {"id":"s_work_han_thu_103_160","chapterId":"ch_work_han_thu_103","textTraditional":"〔四〕　師古曰：「畜讀曰蓄。」","sentenceOrder":160},
  {"id":"s_work_han_thu_103_161","chapterId":"ch_work_han_thu_103","textTraditional":"〔五〕　師古曰：「言用之有次第也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_103_162","chapterId":"ch_work_han_thu_103","textTraditional":"〔六〕　師古曰：「視讀曰示。」","sentenceOrder":162},
  {"id":"s_work_han_thu_103_163","chapterId":"ch_work_han_thu_103","textTraditional":"竟寧中，徵為少府，列於九卿，奏請上林諸離遠宮館稀幸御者，勿復繕治共張，又奏省樂府黃門倡優諸戲，及宮館兵弩什器減過泰半。太官園種冬生蔥韭菜茹，覆以屋廡，〔一〕晝夜然蘊火，待溫氣乃生，〔二〕信臣以為此皆不時之物，有傷於人，不宜以奉供養，及它非法食物，悉奏罷，省費歲數千萬。〔三〕信臣年老以官卒。","sentenceOrder":163},
  {"id":"s_work_han_thu_103_164","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「廡，周室也。茹音人庶反。廡音舞。」","sentenceOrder":164},
  {"id":"s_work_han_thu_103_165","chapterId":"ch_work_han_thu_103","textTraditional":"〔二〕　師古曰：「{難灬}，古然字。蘊火，蓄火也。蘊音於云反。」","sentenceOrder":165},
  {"id":"s_work_han_thu_103_166","chapterId":"ch_work_han_thu_103","textTraditional":"〔三〕　師古曰：「素所費者，今皆省也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_103_167","chapterId":"ch_work_han_thu_103","textTraditional":"元始四年，詔書祀百辟卿士有益於民者，〔一〕蜀郡以文翁，九江以召父應詔書。歲時郡二千石率官屬行禮，奉祠信臣冢，而南陽亦為立祠。","sentenceOrder":167},
  {"id":"s_work_han_thu_103_168","chapterId":"ch_work_han_thu_103","textTraditional":"〔一〕　師古曰：「百辟，百官。」","sentenceOrder":168},
  {"id":"s_work_han_thu_103_169","chapterId":"ch_work_han_thu_103","textTraditional":"校勘記","sentenceOrder":169},
  {"id":"s_work_han_thu_103_170","chapterId":"ch_work_han_thu_103","textTraditional":"三六二六頁　三行　布，蜀布細密（環）也。　景祐本無「環」字，此衍。","sentenceOrder":170},
  {"id":"s_work_han_thu_103_171","chapterId":"ch_work_han_thu_103","textTraditional":"三六三０頁一二行　周密，不泄（陋）〔漏〕也。　景祐、殿本都作「漏」。王先謙說作「漏」是。","sentenceOrder":171},
  {"id":"s_work_han_thu_103_172","chapterId":"ch_work_han_thu_103","textTraditional":"三六三三頁一五行　以水澆之，則味（離）〔漓〕薄。　殿本作「漓」。王先謙說作「漓」是。","sentenceOrder":172},
  {"id":"s_work_han_thu_103_173","chapterId":"ch_work_han_thu_103","textTraditional":"三六三七頁　四行　民果（然）共為邑起冢立祠，　景祐本無「然」字。王念孫說「然」字後人所加。","sentenceOrder":173},
  {"id":"s_work_han_thu_103_174","chapterId":"ch_work_han_thu_103","textTraditional":"三六三八頁　二行　王皆（去逐）〔逐去〕安等，　景祐、殿本都作「逐去」。朱一新說此誤倒。","sentenceOrder":174},
  {"id":"s_work_han_thu_103_175","chapterId":"ch_work_han_thu_103","textTraditional":"三六三九頁一五行　積水曰潢，（曰）〔音〕黃。　景祐、殿本都作「音」，此誤。","sentenceOrder":175},
  {"id":"s_work_han_thu_103_176","chapterId":"ch_work_han_thu_103","textTraditional":"三六四０頁一四行　畜讀（皆）曰蓄。　景祐、殿本都無「皆」字。王先謙說此衍。","sentenceOrder":176},
  {"id":"s_work_han_thu_103_177","chapterId":"ch_work_han_thu_103","textTraditional":"三六四二頁　一行　召讀曰（劭）〔邵〕。　景祐、殿本都作「邵」。王先謙說作「邵」是。","sentenceOrder":177},
  {"id":"s_work_han_thu_104_1","chapterId":"ch_work_han_thu_104","textTraditional":"孔子曰：「導之以政，齊之以刑，民免而無恥；導之以德，齊之以禮，有恥且格。」〔一〕老氏稱：「上德不德，是以有德；下德不失德，是以無德。法令滋章，盜賊多有。」〔二〕信哉是言也！法令者，治之具，而非制治清濁之原也。〔三〕昔天下之罔嘗密矣，〔四〕然（不）〔姦〕軌愈起，其極也，上下相遁，至於不振。〔五〕當是之時，吏治若救火揚沸，〔六〕非武健嚴酷，惡能勝其任而媮快乎？〔七〕言道德者，溺於職矣。〔八〕故曰：「聽訟吾猶人也，必也使無訟乎！」〔九〕「下士聞道大笑之。」〔一０〕非虛言也。","sentenceOrder":1},
  {"id":"s_work_han_thu_104_2","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「論語載孔子之言也。格，至也。謂御以政刑，則人思苟免，不恥於惡；化以德禮，則下知愧辱，而至於治也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_104_3","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「老子德經之言也。上德體合自然，是以為德；下德務於修建，更以喪之。法令繁則巧詐益起，故多盜賊也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_104_4","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「言為治之體，亦須法令，而法令非治之本。」","sentenceOrder":4},
  {"id":"s_work_han_thu_104_5","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「謂秦時。」","sentenceOrder":5},
  {"id":"s_work_han_thu_104_6","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　師古曰：「遁，避也。言吏避於君，民避於吏，至乎喪敗，不可振救也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_104_7","chapterId":"ch_work_han_thu_104","textTraditional":"〔六〕　師古曰：「言迫急也。本敝不除，則其末難正。」","sentenceOrder":7},
  {"id":"s_work_han_thu_104_8","chapterId":"ch_work_han_thu_104","textTraditional":"〔七〕　師古曰：「惡讀曰烏。烏，於何也。媮，苟且也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_104_9","chapterId":"ch_work_han_thu_104","textTraditional":"〔八〕　師古曰：「溺謂沉滯而不舉也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_104_10","chapterId":"ch_work_han_thu_104","textTraditional":"〔九〕　師古曰：「論語載孔子之辭也。言使我聽獄訟，猶凡人耳，然而立政施德，則能使其絕於爭訟。」","sentenceOrder":10},
  {"id":"s_work_han_thu_104_11","chapterId":"ch_work_han_thu_104","textTraditional":"〔一０〕師古曰：「老子道經之言也。大道玄深，非其所及，故致笑也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_104_12","chapterId":"ch_work_han_thu_104","textTraditional":"漢興，破觚而為圜，斲琱而為樸，〔一〕號為罔漏吞舟之魚〔二〕。而吏治蒸蒸，不至於姦，〔三〕黎民艾安。〔四〕由是觀之，在彼不在此。〔五〕高后時，酷吏獨有侯封，刻轢宗室，侵辱功臣〔六〕。呂氏已敗，遂夷侯封之家。〔七〕孝景時，晁錯以刻深頗用術輔其資，〔八〕而七國之亂發怒於錯，錯卒被戮。〔九〕其後有郅都、甯成之倫。〔一０〕","sentenceOrder":12},
  {"id":"s_work_han_thu_104_13","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　孟康曰：「觚，方也。」師古曰：「去嚴刑而從簡易，抑巧偽而務敦厚也。琱謂刻鏤也，字與彫同。」","sentenceOrder":13},
  {"id":"s_work_han_thu_104_14","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「言其疏也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_104_15","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「蒸蒸，純一之貌也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_104_16","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「黎，庶也。艾讀曰乂。乂，治也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_104_17","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　師古曰：「言不在於嚴酷也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_104_18","chapterId":"ch_work_han_thu_104","textTraditional":"〔六〕　師古曰：「轢謂陵踐也，音來的反。」","sentenceOrder":18},
  {"id":"s_work_han_thu_104_19","chapterId":"ch_work_han_thu_104","textTraditional":"〔七〕　師古曰：「誅除也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_104_20","chapterId":"ch_work_han_thu_104","textTraditional":"〔八〕　師古曰：「資，材也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_104_21","chapterId":"ch_work_han_thu_104","textTraditional":"〔九〕　師古曰：「卒，終也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_104_22","chapterId":"ch_work_han_thu_104","textTraditional":"〔一０〕師古曰：「郅音之日反。」","sentenceOrder":22},
  {"id":"s_work_han_thu_104_23","chapterId":"ch_work_han_thu_104","textTraditional":"郅都，河東大陽人也。以郎事文帝。景帝時為中郎將，敢直諫，面折大臣於朝。嘗從入上林，賈姬在廁，〔一〕野彘入廁，上目都，〔二〕都不行。上欲自持兵救賈姬，都伏上前曰：「亡一姬復一姬進，天下所少寧姬等邪？陛下縱自輕，奈宗廟太后何？」上還，彘亦不傷賈姬。太后聞之，賜都金百斤，上亦賜金百斤，由此重都。","sentenceOrder":23},
  {"id":"s_work_han_thu_104_24","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「賈姬即賈夫人，生趙敬肅王彭祖、中山靖王勝者。」","sentenceOrder":24},
  {"id":"s_work_han_thu_104_25","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「動目以使也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_104_26","chapterId":"ch_work_han_thu_104","textTraditional":"濟南瞷氏宗人三百餘家，豪猾，〔一〕二千石莫能制，於是景帝拜都為濟南守。至則誅瞷氏首惡，餘皆股栗。〔二〕居歲餘，郡中不拾遺，旁十餘郡守畏都如大府。〔三〕","sentenceOrder":26},
  {"id":"s_work_han_thu_104_27","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　應劭曰：「瞷音馬瞷眼之瞷。」師古曰：「音閑。」","sentenceOrder":27},
  {"id":"s_work_han_thu_104_28","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「言懼之甚，至於股腳戰栗也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_104_29","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「言猶如統屬之也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_104_30","chapterId":"ch_work_han_thu_104","textTraditional":"都為人，勇有氣，公廉，不發私書，問遺無所受，請寄無所聽。常稱曰：「己背親而出，身固當奉職死節官下，終不顧妻子矣。」","sentenceOrder":30},
  {"id":"s_work_han_thu_104_31","chapterId":"ch_work_han_thu_104","textTraditional":"都遷為中尉，丞相條侯至貴居也，〔一〕而都揖丞相。是時民樸，畏罪自重，而都獨先嚴酷，致行法不避貴戚，列侯宗室見都側目而視，號曰「蒼鷹」。〔二〕","sentenceOrder":31},
  {"id":"s_work_han_thu_104_32","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「居，怠傲，讀與倨同。」","sentenceOrder":32},
  {"id":"s_work_han_thu_104_33","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「言其鷙擊之甚。」","sentenceOrder":33},
  {"id":"s_work_han_thu_104_34","chapterId":"ch_work_han_thu_104","textTraditional":"臨江王徵詣中尉府對簿，〔一〕臨江王欲得刀筆為書謝上，〔二〕而都禁吏弗與。魏其侯使人間予臨江王。〔三〕臨江王既得，為書謝上，因自殺。竇太后聞之，怒，以危法中都，〔四〕都免歸家。景帝乃使使即拜都為鴈門太守，〔五〕便道之官，〔六〕得以便宜從事。匈奴素聞郅都節，舉邊為引兵去，竟都死不近鴈門。匈奴至為偶人象都，〔七〕令騎馳射，莫能中，其見憚如此。匈奴患之。乃中都以漢法。景帝曰：「都忠臣。」欲釋之。〔八〕竇太后曰：「臨江王獨非忠臣乎？」於是斬都也。","sentenceOrder":34},
  {"id":"s_work_han_thu_104_35","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「簿者，獄辭之文書也，音步戶反。」","sentenceOrder":35},
  {"id":"s_work_han_thu_104_36","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「刀，所以削治書也。古者書於簡牘，故必用刀焉。」","sentenceOrder":36},
  {"id":"s_work_han_thu_104_37","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「伺間隙而私與也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_104_38","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「謂搆成其罪也。中音竹仲反。次下亦同。」","sentenceOrder":38},
  {"id":"s_work_han_thu_104_39","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　師古曰：「就家拜。」","sentenceOrder":39},
  {"id":"s_work_han_thu_104_40","chapterId":"ch_work_han_thu_104","textTraditional":"〔六〕　師古曰：「不令（致）〔至〕闕陳謝也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_104_41","chapterId":"ch_work_han_thu_104","textTraditional":"〔七〕　師古曰：「以木為人，象都之形也。偶，對也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_104_42","chapterId":"ch_work_han_thu_104","textTraditional":"〔八〕　師古曰：「釋，置也，解也。謂放免也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_104_43","chapterId":"ch_work_han_thu_104","textTraditional":"甯成，南陽穰人也。以郎謁者事景帝。好氣，為少吏，必陵其長吏；為人上，操下急如束溼。〔一〕猾賊任威。稍遷至濟南都尉，而郅都為守。始前數都尉步入府，因吏謁守如縣令，其畏都如此。及成往，直凌都出其上。都素聞其聲，善遇，與結驩。久之，都死，後長安左右宗室多犯法，〔二〕上召成為中尉。其治效郅都，其廉弗如，然宗室豪桀人皆惴恐。〔三〕","sentenceOrder":43},
  {"id":"s_work_han_thu_104_44","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「操，執持也。束溼，言其急之甚也。溼物則易束。操音千高反。」","sentenceOrder":44},
  {"id":"s_work_han_thu_104_45","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「長安左右，京邑之中也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_104_46","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「惴，戰栗也。人人皆戰恐也。惴音之瑞反。」","sentenceOrder":46},
  {"id":"s_work_han_thu_104_47","chapterId":"ch_work_han_thu_104","textTraditional":"武帝即位，徙為內史，外戚多毀成之短，抵罪髡鉗。是時九卿死即死，少被刑，而成刑極，自以為不復收，〔一〕乃解脫，詐刻傳出關歸家。〔二〕稱曰：「仕不至二千石，賈不至千萬，安可比人乎！」〔三〕乃貰貣陂田千餘頃，〔四〕假貧民，役使數千家。〔五〕數年，會赦，致產數千萬，為任俠，持吏長短，出從數十騎。其使民，威重於郡守。","sentenceOrder":47},
  {"id":"s_work_han_thu_104_48","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　如淳曰：「以被重刑，將不復見收用也。」師古曰：「刑極者，言殘毀之重也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_104_49","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「輒解脫鉗釱而亡去也。傳，所以出關之符也，音張戀反。」","sentenceOrder":49},
  {"id":"s_work_han_thu_104_50","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「賈謂販賣之。」","sentenceOrder":50},
  {"id":"s_work_han_thu_104_51","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「貰貣，假取之也。貣音吐得反。」","sentenceOrder":51},
  {"id":"s_work_han_thu_104_52","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　師古曰：「假謂雇賃也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_104_53","chapterId":"ch_work_han_thu_104","textTraditional":"周陽由，其父趙兼以淮南王舅侯周陽，〔一〕故因氏焉。〔二〕由以宗家任為郎，事文帝。景帝時，由為郡守。武帝即位，吏治尚脩謹，然由居二千石中最為暴酷驕恣。所愛者，撓法活之；所憎者，曲法滅之。〔三〕所居郡，必夷其豪。〔四〕為守，視都尉如令；為都尉，陵太守，奪之治。汲黯為忮，〔五〕司馬安之文惡，〔六〕俱在二千石列，同車未嘗敢均茵馮。〔七〕後由為河東都尉，與其守勝屠公爭權，相告言，〔八〕勝屠公當抵罪，（議）〔義〕不受刑，自殺，而由棄市。","sentenceOrder":53},
  {"id":"s_work_han_thu_104_54","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「封為周陽侯。」","sentenceOrder":54},
  {"id":"s_work_han_thu_104_55","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「遂改趙姓而為周陽也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_104_56","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「撓亦屈曲也，音女教反。」","sentenceOrder":56},
  {"id":"s_work_han_thu_104_57","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「平除之。」","sentenceOrder":57},
  {"id":"s_work_han_thu_104_58","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　師古曰：「忮，意堅也，音章豉反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_104_59","chapterId":"ch_work_han_thu_104","textTraditional":"〔六〕　孟康曰：「以文法傷害人也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_104_60","chapterId":"ch_work_han_thu_104","textTraditional":"〔七〕　師古曰：「茵，車中蓐也。馮，車中所馮者也。言此二人皆下讓由，故同車之時自處其偏側，不均敵也。馮讀曰凭。」","sentenceOrder":60},
  {"id":"s_work_han_thu_104_61","chapterId":"ch_work_han_thu_104","textTraditional":"〔八〕　師古曰：「勝屠，姓也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_104_62","chapterId":"ch_work_han_thu_104","textTraditional":"自甯成、周陽由之後，事益多，民巧法，大抵吏治類多成、由等矣。〔一〕","sentenceOrder":62},
  {"id":"s_work_han_thu_104_63","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「大抵，大歸也，音丁禮反。」","sentenceOrder":63},
  {"id":"s_work_han_thu_104_64","chapterId":"ch_work_han_thu_104","textTraditional":"趙禹，斄人也。〔一〕以佐史補中都官，〔二〕用廉為令史，事太尉周亞夫。亞夫為丞相，禹為丞相史，府中皆稱其廉平。然亞夫弗任，曰：「極知禹無害，〔三〕然文深，〔四〕不可以居大府。」武帝時，禹以刀筆吏積勞，遷為御史。上以為能，至中大夫。與張湯論定律令，作見知，吏傳相監司以法，盡自此始。","sentenceOrder":64},
  {"id":"s_work_han_thu_104_65","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「斄讀曰邰，扶風縣也，音胎。」","sentenceOrder":65},
  {"id":"s_work_han_thu_104_66","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「京師諸官為吏也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_104_67","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「無害，言無人能勝之者。」","sentenceOrder":67},
  {"id":"s_work_han_thu_104_68","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　應劭曰：「禹持文法深刻。」","sentenceOrder":68},
  {"id":"s_work_han_thu_104_69","chapterId":"ch_work_han_thu_104","textTraditional":"禹為人廉裾，〔一〕為吏以來，舍無食客。公卿相造請，〔二〕禹終不行報謝，務在絕知友賓客之請，〔三〕孤立行一意而已。見法輒取，亦不覆案求官屬陰罪。〔四〕嘗中廢，已為廷尉。始條侯以禹賊深，及禹為少府九卿，酷急。至晚節，事益多。吏務為嚴峻，而禹治加緩，名為平。王溫舒等後起，治峻禹。禹以老，徙為燕相。數歲，誖亂有罪，免歸。〔五〕後十餘年，以壽卒于家。","sentenceOrder":69},
  {"id":"s_work_han_thu_104_70","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「裾亦傲也，讀與倨同。」","sentenceOrder":70},
  {"id":"s_work_han_thu_104_71","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「造音千到反。」","sentenceOrder":71},
  {"id":"s_work_han_thu_104_72","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「以此意告報公卿。」","sentenceOrder":72},
  {"id":"s_work_han_thu_104_73","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「不見知者無所搜求也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_104_74","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　師古曰：「誖，惑也，言其心意昏惑也。誖音布內反。」","sentenceOrder":74},
  {"id":"s_work_han_thu_104_75","chapterId":"ch_work_han_thu_104","textTraditional":"義縱，河東人也。少年時嘗與張次公俱攻剽，為群盜。〔一〕縱有姊，以醫幸王太后。〔二〕太后問：「有子兄弟為官者乎？」姊曰：「有弟無行，不可。」太后乃告上，上拜義姁弟縱為中郎，〔三〕補上黨郡中令。治敢往，少溫籍，〔四〕縣無逋事，〔五〕舉第一。遷為長陵及長安令，直法行治，不避貴戚。以捕桉太后外孫脩成子中，〔六〕上以為能，遷為河內都尉。至則族滅其豪穰氏之屬，河內道不拾遺。而張次公亦為郎，以勇悍從軍，〔七〕敢深入，有功，封為岸頭侯。","sentenceOrder":75},
  {"id":"s_work_han_thu_104_76","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「剽，劫也，音頻妙反。」","sentenceOrder":76},
  {"id":"s_work_han_thu_104_77","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「武帝母。」","sentenceOrder":77},
  {"id":"s_work_han_thu_104_78","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　孟康曰：「姁，縱姊名也。」師古曰：「姁音許于反。」","sentenceOrder":78},
  {"id":"s_work_han_thu_104_79","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　服虔曰：「敢行暴害之政。」師古曰：「少溫籍，言無所含容也。溫音於問反。籍音才夜反。」","sentenceOrder":79},
  {"id":"s_work_han_thu_104_80","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　師古曰：「逋，亡也，負也，音必胡反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_104_81","chapterId":"ch_work_han_thu_104","textTraditional":"〔六〕　師古曰：「脩成君，王太后所生金氏女也。中者，其子名也，讀曰仲。」","sentenceOrder":81},
  {"id":"s_work_han_thu_104_82","chapterId":"ch_work_han_thu_104","textTraditional":"〔七〕　師古曰：「悍音胡旦反。」","sentenceOrder":82},
  {"id":"s_work_han_thu_104_83","chapterId":"ch_work_han_thu_104","textTraditional":"甯成家居，上欲以為郡守，御史大夫弘曰：〔一〕「臣居山東為小吏時，甯成為濟南都尉，其治如狼牧羊。成不可令治民。」上乃拜成為關都尉。歲餘，關吏稅肄郡國出入關者，〔二〕號曰：「寧見乳虎，無直甯成之怒。」〔三〕其暴如此。義縱自河內遷為南陽太守，聞甯成家居南陽，及至關，甯成側行送迎，然縱氣盛，弗為禮。至郡，逐桉甯氏，破碎其家。成坐有罪，及孔、暴之屬皆奔亡，〔四〕南陽吏民重足一跡。而平氏朱彊、杜衍杜周為縱爪牙之吏，任用，〔五〕遷為廷尉史。","sentenceOrder":83},
  {"id":"s_work_han_thu_104_84","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「公孫弘。」","sentenceOrder":84},
  {"id":"s_work_han_thu_104_85","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　李奇曰：「肄，閱也。」師古曰：「肄音弋二反。」","sentenceOrder":85},
  {"id":"s_work_han_thu_104_86","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「猛獸產乳，養護其子，則搏噬過常，故以喻也。直讀曰值，一曰直當。」","sentenceOrder":86},
  {"id":"s_work_han_thu_104_87","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「孔氏、暴氏二家素豪猾者。」","sentenceOrder":87},
  {"id":"s_work_han_thu_104_88","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　師古曰：「平氏、杜衍，二縣名也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_104_89","chapterId":"ch_work_han_thu_104","textTraditional":"軍數出定襄，定襄吏民亂敗，於是徙縱為定襄太守。縱至，掩定襄獄中重罪二百餘人，及賓客昆弟私入相視者亦二百餘人。縱壹切捕鞠，曰「為死罪解脫」。〔一〕是日皆報殺四百餘人。〔二〕郡中不寒而栗，猾民佐吏為治。〔三〕","sentenceOrder":89},
  {"id":"s_work_han_thu_104_90","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　孟康曰：「壹切皆捕之也。律，諸囚徒私解脫桎梏鉗赭，加罪一等；為人解脫，與同罪。縱鞠相賂餉者二百人以為解脫死罪，盡殺之。」師古曰：「鞠，窮也，謂窮治也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_104_91","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「奏請得報而論殺。」","sentenceOrder":91},
  {"id":"s_work_han_thu_104_92","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「百姓有素豪猾為罪惡者，今畏縱之嚴，反為吏耳目，助治公務以自效。」","sentenceOrder":92},
  {"id":"s_work_han_thu_104_93","chapterId":"ch_work_han_thu_104","textTraditional":"是時趙禹、張湯為九卿矣，然其治尚寬，輔法而行，縱以鷹擊毛摯為治。〔一〕後會更五銖錢白金起，〔二〕民為姦，京師尤甚，乃以縱為右內史，王溫舒為中尉。溫舒至惡，所為弗先言縱，縱必以氣陵之，〔三〕敗壞其功。其治，所誅殺甚多，然取為小治，姦益不勝，〔四〕直指始出矣。吏之治以斬殺縛束為務，閻奉以惡用矣。〔五〕縱廉，其治效郅都。上幸鼎湖，病久，已而卒起幸甘泉，〔六〕道不治。上怒曰：「縱以我為不行此道乎？」銜之。〔七〕至冬，楊可方受告緡，縱以為此亂民，部吏捕其為可使者。天子聞，使杜式治，以為廢格沮事，〔八〕棄縱市。後一歲，張湯亦死。","sentenceOrder":93},
  {"id":"s_work_han_thu_104_94","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「言如鷹隼之擊，奮毛羽執取飛鳥也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_104_95","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「更，改也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_104_96","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「言溫舒雖酷惡，而縱又甚也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_104_97","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　晉灼曰：「取音趣。」","sentenceOrder":97},
  {"id":"s_work_han_thu_104_98","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　師古曰：「閻奉以嚴惡之故而見任用，言時政尚急刻也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_104_99","chapterId":"ch_work_han_thu_104","textTraditional":"〔六〕　師古曰：「已謂病愈也。言帝久病，既得愈，而忽然即幸甘泉。卒讀曰猝。」","sentenceOrder":99},
  {"id":"s_work_han_thu_104_100","chapterId":"ch_work_han_thu_104","textTraditional":"〔七〕　師古曰：「銜，含也。苞含在心，以為過也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_104_101","chapterId":"ch_work_han_thu_104","textTraditional":"〔八〕　孟康曰：「武帝使楊可主告緡，沒入其財物，縱捕為可使者。此為廢格詔書，沮已成之事也。」師古曰：「沮，壞也，音材汝反。格讀曰閣。」","sentenceOrder":101},
  {"id":"s_work_han_thu_104_102","chapterId":"ch_work_han_thu_104","textTraditional":"王溫舒，陽陵人也。少時椎埋為姦。〔一〕已而試縣亭長，〔一〕數廢。數為吏，以治獄至廷尉史。事張湯，遷為御史，督盜賊，殺傷甚多。稍遷至廣平都尉，擇郡中豪敢往吏十餘人為爪牙，〔三〕皆把其陰重罪，〔四〕而縱使督盜賊，〔五〕快其意所欲得。此人雖有百罪，弗法；〔六〕即有避回，夷之，亦滅宗。〔七〕以故齊趙之郊盜不敢近廣平，廣平聲為道不拾遺。上聞，遷為河內太守。","sentenceOrder":102},
  {"id":"s_work_han_thu_104_103","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「椎殺人而埋之。椎音直追反，其字從木。」","sentenceOrder":103},
  {"id":"s_work_han_thu_104_104","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「試，補也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_104_105","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「豪桀而性果敢，一往無所顧者，以為吏也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_104_106","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「把音布馬反。」","sentenceOrder":106},
  {"id":"s_work_han_thu_104_107","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　師古曰：「縱，放也。督，察視也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_104_108","chapterId":"ch_work_han_thu_104","textTraditional":"〔六〕　師古曰：「言所捕盜賊得其人而快溫舒意者，則不問其先所犯罪也。法謂行法也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_104_109","chapterId":"ch_work_han_thu_104","textTraditional":"〔七〕　師古曰：「避回，謂不盡意捕擊也。回音胡內反。」","sentenceOrder":109},
  {"id":"s_work_han_thu_104_110","chapterId":"ch_work_han_thu_104","textTraditional":"素居廣平時，皆知河內豪姦之家。及往，以九月至，令郡具私馬五十疋，為驛自河內至長安，〔一〕部吏如居廣平時方略，捕郡中豪猾，相連坐千餘家。上書請，大者至族，小者乃死，家盡沒入償臧。〔二〕奏行不過二日，得可，事論報，至流血十餘里。〔三〕河內皆怪其奏，以為神速。盡十二月，郡中無犬吠之盜。其頗不得，失之旁郡，追求，會春，溫舒頓足歎曰：「嗟乎，令冬月益展一月，卒吾事矣！」〔四〕其好殺行威不愛人如此。","sentenceOrder":110},
  {"id":"s_work_han_thu_104_111","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「以私馬於道上往往置驛也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_104_112","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「以臧致罪者，既沒入之，又令出倍臧，或收入官，或還其主也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_104_113","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「天子可其奏而論決之。殺人既多，故血流十餘里。」","sentenceOrder":113},
  {"id":"s_work_han_thu_104_114","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「立春之後，不復行刑，故云然。展，伸也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_104_115","chapterId":"ch_work_han_thu_104","textTraditional":"上聞之，以為能，遷為中尉。其治復放河內，〔一〕徒請召猜禍吏與從事，〔二〕河內則楊皆、麻戊，關中揚贛、成信等。〔三〕義縱為內史，憚之，未敢恣治。〔四〕及縱死，張湯敗後，徙為延尉。而尹齊為中尉坐法抵罪，溫舒復為中尉。為人少文，居它惛惛不辯，〔五〕至於中尉則心開。素習關中俗，知豪惡吏，豪惡吏盡復為用。吏苛察淫惡少年，投缿購告言姦，〔六〕置伯落長以收司姦。〔七〕溫舒多諂，善事有勢者；即無勢，視之如奴。有勢家，雖有姦如山，弗犯；無勢，雖貴戚，必侵辱。〔八〕舞文巧，請下戶之猾，以動大豪。〔九〕其治中尉如此。姦猾窮治，大氐盡靡爛獄中，〔一０〕行論無出者。其爪牙吏虎而冠。〔一一〕於是中尉部中中猾以下皆伏，有勢者為遊聲譽，稱治。數歲，其吏多以權貴富。〔一二〕","sentenceOrder":115},
  {"id":"s_work_han_thu_104_116","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「放，依也，音甫往反。」","sentenceOrder":116},
  {"id":"s_work_han_thu_104_117","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　應劭曰：「徒，但也。猜，疑也。取吏好猜疑作禍害者，任用之。」","sentenceOrder":117},
  {"id":"s_work_han_thu_104_118","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「此皆猜禍者。」","sentenceOrder":118},
  {"id":"s_work_han_thu_104_119","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「言溫舒憚縱，不得恣其酷暴。」","sentenceOrder":119},
  {"id":"s_work_han_thu_104_120","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　師古曰：「言為餘官則心意蒙蔽，職事不舉。惛音昏。」","sentenceOrder":120},
  {"id":"s_work_han_thu_104_121","chapterId":"ch_work_han_thu_104","textTraditional":"〔六〕　師古曰：「缿，所以受投書也，音項。解在趙廣漢傳也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_104_122","chapterId":"ch_work_han_thu_104","textTraditional":"〔七〕　師古曰：「伯亦長帥之稱也。置伯及邑落之長，以收捕司察姦人也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_104_123","chapterId":"ch_work_han_thu_104","textTraditional":"〔八〕　師古曰：「謂不居權要之職者。」","sentenceOrder":123},
  {"id":"s_work_han_thu_104_124","chapterId":"ch_work_han_thu_104","textTraditional":"〔九〕　師古曰：「弄法為巧，而治下戶之狡猾者，用諷動大豪之家。所以然者，為大豪中有權要，不可治故也。請謂奏請。」","sentenceOrder":124},
  {"id":"s_work_han_thu_104_125","chapterId":"ch_work_han_thu_104","textTraditional":"〔一０〕師古曰：「大氐，大歸也。靡，碎也。氐音丁禮反。靡音武皮反。」","sentenceOrder":125},
  {"id":"s_work_han_thu_104_126","chapterId":"ch_work_han_thu_104","textTraditional":"〔一一〕師古曰：「言其殘暴之甚也，非有人情。」","sentenceOrder":126},
  {"id":"s_work_han_thu_104_127","chapterId":"ch_work_han_thu_104","textTraditional":"〔一二〕師古曰：「為權貴之家所擁佑，故積受取致富者也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_104_128","chapterId":"ch_work_han_thu_104","textTraditional":"溫舒擊東越還，議有不中意，〔一〕坐以法免。是時上方欲作通天臺而未有人，溫舒請覆中尉脫卒，得數萬人作。〔二〕上說，〔三〕拜為少府。徙右內史，治如其故，姦邪少禁。坐法失官，復為右輔，行中尉，如故操。","sentenceOrder":128},
  {"id":"s_work_han_thu_104_129","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「不當天子意也。中音竹仲反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_104_130","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「覆校脫漏未為卒者也。脫音它活反。」","sentenceOrder":130},
  {"id":"s_work_han_thu_104_131","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「說讀曰悅。」","sentenceOrder":131},
  {"id":"s_work_han_thu_104_132","chapterId":"ch_work_han_thu_104","textTraditional":"歲餘，會宛軍發，〔一〕詔徵豪吏。溫舒匿其吏華成，及人有變告溫舒受員騎錢，它姦利事，罪至族，自殺。〔二〕其時兩弟及兩婚家亦各自坐它罪而族。光祿勳徐自為曰：「悲夫！夫古有三族，而王溫舒罪至同時而五族乎！」〔三〕溫舒死，家絫千金。〔四〕","sentenceOrder":132},
  {"id":"s_work_han_thu_104_133","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　孟康曰：「發兵伐大宛。」","sentenceOrder":133},
  {"id":"s_work_han_thu_104_134","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「員騎，騎之有正員也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_104_135","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「溫舒與弟同三族，而兩妻家各一，故為五也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_104_136","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「絫，古累字。」","sentenceOrder":136},
  {"id":"s_work_han_thu_104_137","chapterId":"ch_work_han_thu_104","textTraditional":"尹齊，東郡茌平人也。〔一〕以刀筆吏稍遷至御史。事張湯，湯數稱以為廉。武帝使督盜賊，斬伐不避貴勢。遷關都尉，聲甚於甯成。上以為能，拜為中尉。吏民益彫敝，輕齊木彊少文，〔二〕豪惡吏伏匿而善吏不能為治，〔三〕以故事多廢，抵罪。〔四〕後復為淮陽都尉。王溫舒敗後數年，病死，家直不滿五十金。所誅滅淮陽甚多，及死，仇家欲燒其尸，妻亡去，歸葬。","sentenceOrder":137},
  {"id":"s_work_han_thu_104_138","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「茌音仕疑反。」","sentenceOrder":138},
  {"id":"s_work_han_thu_104_139","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「木，質也，言如木石之為也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_104_140","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「惡吏不肯為用，獨善吏在，故不能治事也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_104_141","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「以職事多廢，故至於坐罪也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_104_142","chapterId":"ch_work_han_thu_104","textTraditional":"楊僕，宜陽人也。以千夫為吏。〔一〕河南守舉為御吏，使督盜賊關東，治放尹齊，〔二〕以敢擊行。〔三〕稍遷至主爵都尉，上以為能。南越反，拜為樓船將軍，有功，封將梁侯。東越反，上欲復使將，為其伐前勞，〔四〕以書敕責之曰：「將軍之功，獨有先破石門、尋陿，〔五〕非有斬將騫旗之實也，〔六〕烏足以驕人哉！〔七〕前破番禺，捕降者以為虜，掘死人以為獲，是一過也。建德、呂嘉逆罪不容於天下，〔八〕將軍擁精兵不窮追，超然以東越為援，是二過也。〔九〕士卒暴露連歲，為朝會不置酒，將軍不念其勤勞，而造佞巧，請乘傳行塞，〔一０〕因用歸家，懷銀黃，垂三組，夸鄉里，是三過也。〔一一〕失期內顧，以道惡為解，〔一二〕失尊尊之序，是四過也。欲請蜀刀，問君賈幾何，對曰率數百，〔一三〕武庫日出兵而陽不知，挾偽干君，是五過也。〔一四〕受詔不至蘭池宮，〔一五〕明日又不對。假令將軍之吏問之不對，令之不從，其罪何如？推此心以在外，江海之間可得信乎！今東越深入，將軍能率眾以掩過不？」僕惶恐，對曰：「願盡死贖罪！」與王溫舒俱破東越。後復與左將軍荀彘俱擊朝鮮，為彘所縛，語在朝鮮傳。還，免為庶人，病死。","sentenceOrder":142},
  {"id":"s_work_han_thu_104_143","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　孟康曰：「千夫若五大夫。武帝以軍用不足，令民出錢穀為之。」師古曰：「所謂武功賞官，以寵戰士。」","sentenceOrder":143},
  {"id":"s_work_han_thu_104_144","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「放，依也，音甫往反。」","sentenceOrder":144},
  {"id":"s_work_han_thu_104_145","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「果敢搏擊而行其治也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_104_146","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「伐謂矜恃也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_104_147","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　劉德曰：「南越中險地名也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_104_148","chapterId":"ch_work_han_thu_104","textTraditional":"〔六〕　師古曰：「騫與搴同。搴，拔取之。」","sentenceOrder":148},
  {"id":"s_work_han_thu_104_149","chapterId":"ch_work_han_thu_104","textTraditional":"〔七〕　師古曰：「烏，於何也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_104_150","chapterId":"ch_work_han_thu_104","textTraditional":"〔八〕　師古曰：「建德，南越王名也，尉佗玄孫也。呂嘉，其相也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_104_151","chapterId":"ch_work_han_thu_104","textTraditional":"〔九〕　師古曰：「以僕不窮追之故，令建德得以東越為援也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_104_152","chapterId":"ch_work_han_thu_104","textTraditional":"〔一０〕師古曰：「傳音張戀反。行音下更反。」","sentenceOrder":152},
  {"id":"s_work_han_thu_104_153","chapterId":"ch_work_han_thu_104","textTraditional":"〔一一〕師古曰：「銀，銀印也。黃，金印也。僕為主爵都尉，又為樓船將軍，并將梁侯三印，故三組也。組，印綬也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_104_154","chapterId":"ch_work_han_thu_104","textTraditional":"〔一二〕師古曰：「內顧，言思妻妾也。解謂自解說也，若今言分疏。」","sentenceOrder":154},
  {"id":"s_work_han_thu_104_155","chapterId":"ch_work_han_thu_104","textTraditional":"〔一三〕孟康曰：「僕嘗為將，請官蜀刀，詔問賈，答言比數率數百也。」師古曰：「賈讀曰價。」","sentenceOrder":155},
  {"id":"s_work_han_thu_104_156","chapterId":"ch_work_han_thu_104","textTraditional":"〔一四〕師古曰：「干，犯也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_104_157","chapterId":"ch_work_han_thu_104","textTraditional":"〔一五〕如淳曰：「本出軍時，欲使之蘭池宮，頓而不去。蘭池宮在渭城。」","sentenceOrder":157},
  {"id":"s_work_han_thu_104_158","chapterId":"ch_work_han_thu_104","textTraditional":"咸宣，楊人也。〔一〕以佐史給事河東守。衛將軍青使買馬河東，〔二〕見宣無害，言上，徵為廄丞。官事辦，稍遷至御史及〔中〕丞，使治主父偃及淮南反獄，所以微文深詆殺者甚眾，〔三〕稱為敢決疑。數廢數起，為御史及中丞者幾二十歲。〔四〕王溫舒為中尉，而宣為左內史。其治米鹽，〔五〕事小大皆關其手，自部署縣名曹寶物，官吏令丞弗得擅搖，痛以重法繩之。居官數年，壹切為小治辯，然獨宣以小至大，能自行之，難以為經。〔六〕中廢為右扶風，坐怒其吏成信，信亡藏上林中，宣使郿令將吏卒，〔七〕闌入上林中蠶室門攻亭格殺信，射中苑門，〔八〕宣下吏，為大逆當族，自殺。而杜周任用。","sentenceOrder":158},
  {"id":"s_work_han_thu_104_159","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「咸音減省之減。楊，河東之邑。」","sentenceOrder":159},
  {"id":"s_work_han_thu_104_160","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「將軍衛青充使而於河東買馬也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_104_161","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「詆，誣也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_104_162","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「幾音鉅依反。」","sentenceOrder":162},
  {"id":"s_work_han_thu_104_163","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　師古曰：「米鹽，細雜也。」","sentenceOrder":163},
  {"id":"s_work_han_thu_104_164","chapterId":"ch_work_han_thu_104","textTraditional":"〔六〕　師古曰：「經，常也，不可為常法也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_104_165","chapterId":"ch_work_han_thu_104","textTraditional":"〔七〕　師古曰：「郿，扶風縣也，音媚。」","sentenceOrder":165},
  {"id":"s_work_han_thu_104_166","chapterId":"ch_work_han_thu_104","textTraditional":"〔八〕　師古曰：「中音竹仲反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_104_167","chapterId":"ch_work_han_thu_104","textTraditional":"是時郡守尉諸侯相二千石欲為治者，大抵盡效王溫舒等，而吏民益輕犯法，盜賊滋起。〔一〕南陽有梅免、百政，〔二〕楚有段中、杜少，〔三〕齊有徐勃，燕趙之間有堅盧、范主之屬。大群至數千人，擅自號，攻城邑，取庫兵，釋死罪，〔四〕縛辱郡守都尉，殺二千石，為檄告縣趨具食；〔五〕小群以百數，掠鹵鄉里者不可稱數。於是上始使御史中丞、丞相長史使督之，〔六〕猶弗能禁，〔七〕乃使光祿大夫范昆、諸部都尉及故九卿張德等衣繡衣持節，虎符發兵以興擊，〔八〕斬首大部或至萬餘級。及以法誅通行飲食，坐相連郡，甚者數千人。數歲，乃頗得其渠率。〔九〕散卒失亡，復聚黨阻山川。往往而群，無可奈何。於是作沈命法，〔一０〕曰：「群盜起不發覺，發覺而弗捕滿品者，〔一一〕二千石以下至小吏主者皆死。」其後小吏畏誅，雖有盜弗敢發，恐不能得，坐課累府，府亦使不言。〔一二〕故盜賊寖多，〔一三〕上下相為匿，以避文法焉。","sentenceOrder":167},
  {"id":"s_work_han_thu_104_168","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「滋亦益也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_104_169","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「梅、百，皆姓也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_104_170","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「中讀曰仲。」","sentenceOrder":170},
  {"id":"s_work_han_thu_104_171","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「釋，解也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_104_172","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　師古曰：「趨讀曰促。」","sentenceOrder":172},
  {"id":"s_work_han_thu_104_173","chapterId":"ch_work_han_thu_104","textTraditional":"〔六〕　師古曰：「出為使者督察也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_104_174","chapterId":"ch_work_han_thu_104","textTraditional":"〔七〕　師古曰：「禁音居禽反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_104_175","chapterId":"ch_work_han_thu_104","textTraditional":"〔八〕　師古曰：「以軍興之法而討擊也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_104_176","chapterId":"ch_work_han_thu_104","textTraditional":"〔九〕　師古曰：「渠，大也。」","sentenceOrder":176},
  {"id":"s_work_han_thu_104_177","chapterId":"ch_work_han_thu_104","textTraditional":"〔一０〕應劭曰：「沈，沒也。敢蔽匿盜賊者，沒其命也。」孟康曰：「沈，藏匿也。命，亡逃也。」師古曰：「應說是。」","sentenceOrder":177},
  {"id":"s_work_han_thu_104_178","chapterId":"ch_work_han_thu_104","textTraditional":"〔一一〕師古曰：「品，率也，以人數為率也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_104_179","chapterId":"ch_work_han_thu_104","textTraditional":"〔一二〕孟康曰：「縣有盜賊，府亦并坐，使縣不言之也。」師古曰：「府，郡府也。累音力瑞反。」","sentenceOrder":179},
  {"id":"s_work_han_thu_104_180","chapterId":"ch_work_han_thu_104","textTraditional":"〔一三〕師古曰：「寖，漸也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_104_181","chapterId":"ch_work_han_thu_104","textTraditional":"田廣明字子公，鄭人也。〔一〕以郎為天水司馬。功次遷河南都尉，以殺伐為治。郡國盜賊並起，遷廣明為淮陽太守。歲餘，故城父令公孫勇與客胡倩等謀反，〔二〕倩詐稱光祿大夫，從車騎數十，言使督盜賊，止陳留傳舍，太守謁見，欲收取之。廣明覺知，發兵皆捕斬焉。而公孫勇衣繡衣，乘駟馬車至圉，〔三〕圉使小史侍之，亦知其非是，守尉魏不害與廄嗇夫江德、尉史蘇昌共收捕之。上封不害為當塗侯，德轑陽侯，〔四〕昌蒲侯。初，四人俱拜於前，小史竊言。武帝問：「言何？」對曰：「為侯者得東歸不？」上曰：「女欲不？貴矣。〔五〕女鄉名為何？」對曰：「名遺鄉。」上曰：「用遺汝矣。」〔六〕於是賜小史爵關內侯，食遺鄉六百戶。","sentenceOrder":181},
  {"id":"s_work_han_thu_104_182","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「京兆鄭縣，即今之華州。」","sentenceOrder":182},
  {"id":"s_work_han_thu_104_183","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「倩音千見反。」","sentenceOrder":183},
  {"id":"s_work_han_thu_104_184","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「陳留圉縣。」","sentenceOrder":184},
  {"id":"s_work_han_thu_104_185","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「轑音遼。」","sentenceOrder":185},
  {"id":"s_work_han_thu_104_186","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　師古曰：「言汝意欲歸不？吾今貴汝，謂賜之爵也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_104_187","chapterId":"ch_work_han_thu_104","textTraditional":"〔六〕　師古曰：「遺音弋季反。」","sentenceOrder":187},
  {"id":"s_work_han_thu_104_188","chapterId":"ch_work_han_thu_104","textTraditional":"上以廣明連禽大姦，徵入為大鴻臚，擢廣明兄雲中代為淮陽太守。昭帝時，廣明將兵擊益州，還，賜爵關內侯，徙衛尉。後出為左馮翊，治有能名。宣帝初立，代蔡義為御史大夫，以前為馮翊與議定策，〔一〕封昌水侯。歲餘，以祁連將軍將兵擊匈奴，出塞至受降城。受降都尉前死，喪柩在堂，廣明召其寡妻與姦。既出不至質，〔二〕引軍空還。下太守杜延年簿責，〔三〕廣明自殺闕下，國除。兄雲中為淮陽守，亦敢誅殺，吏民守闕告之，竟坐棄市。","sentenceOrder":188},
  {"id":"s_work_han_thu_104_189","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「與讀曰豫。」","sentenceOrder":189},
  {"id":"s_work_han_thu_104_190","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　服虔曰：「質，所期處也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_104_191","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「簿音步戶反。」","sentenceOrder":191},
  {"id":"s_work_han_thu_104_192","chapterId":"ch_work_han_thu_104","textTraditional":"田延年字子賓，先齊諸田也，徙陽陵。〔一〕延年以材略給事大將軍莫府，霍光重之，遷為長史。出為河東太守，選拔尹翁歸等以為爪牙，誅鉏豪彊，姦邪不敢發。以選入為大司農。會昭帝崩，昌邑王嗣位，淫亂，霍將軍憂懼，與公卿議廢之，莫敢發言。延年按劍，延叱群臣，〔二〕即日議決，語在光傳。宣帝即位，延年以決疑定策封陽成侯。","sentenceOrder":192},
  {"id":"s_work_han_thu_104_193","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「高祖時徙之，其地後為陽陵縣。」","sentenceOrder":193},
  {"id":"s_work_han_thu_104_194","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「止於朝廷之中而叱之也，若言廷爭矣。」","sentenceOrder":194},
  {"id":"s_work_han_thu_104_195","chapterId":"ch_work_han_thu_104","textTraditional":"先是，茂陵富人焦氏、賈氏以數千萬陰積貯炭葦諸下里物。〔一〕昭帝大行時，方上事暴起，〔二〕用度未辦，延年奏言「商賈或豫收方上不祥器物，冀其疾用，欲以求利，〔三〕非民臣所當為。請沒入縣官。」奏可。富人亡財者皆怨，出錢求延年罪。初，大司農取民牛車三萬兩為僦，〔四〕載沙便橋下，送致方上，車直千錢，延年上簿詐增僦直車二千，凡六千萬，盜取其半。焦、賈兩家告其事，下丞相府。丞相議奏延年「主守盜三千萬，不道」。霍將軍召問延年，欲為道地，〔五〕延年抵曰：〔六〕「本出將軍之門，蒙此爵位，〔七〕無有是事。」光曰：「即無事，當窮竟。」〔八〕御史大夫田廣明謂太僕杜延年：「春秋之義，以功覆過。當廢昌邑王時，非田子賓之言大事不成。今縣官出三千萬自乞之何哉？〔九〕願以愚言白大將軍。」延年言之大將軍，大將軍曰：「誠然，實勇士也！當發大議時，震動朝廷。」光因舉手自撫心曰：「使我至今病悸！〔一０〕謝田大夫曉大司農，通往就獄，得公議之。」〔一一〕田大夫使人語延年，延年曰：「幸縣官寬我耳，何面目入牢獄，使眾人指笑我，卒徒唾吾背乎！」即閉閣獨居齊舍，〔一二〕偏袒持刀東西步。數日，使者召延年詣廷尉。聞鼓聲，自刎死，〔一三〕國除。","sentenceOrder":195},
  {"id":"s_work_han_thu_104_196","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　孟康曰：「死者歸蒿里，葬地下，故曰下里。」師古曰：「以數千萬錢為本，而貯此物也。」","sentenceOrder":196},
  {"id":"s_work_han_thu_104_197","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「方上謂壙中也。昭帝暴崩，故其事倉猝。」","sentenceOrder":197},
  {"id":"s_work_han_thu_104_198","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「疾，速也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_104_199","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「一乘為一兩。僦謂賃之與雇直也，音子就反。」","sentenceOrder":199},
  {"id":"s_work_han_thu_104_200","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　師古曰：「為之開通道路，使有安全之地也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_104_201","chapterId":"ch_work_han_thu_104","textTraditional":"〔六〕　師古曰：「抵，拒諱也，音丁禮反。」","sentenceOrder":201},
  {"id":"s_work_han_thu_104_202","chapterId":"ch_work_han_thu_104","textTraditional":"〔七〕　師古曰：「延年嘗給事莫府，又為大將軍長史，故云然也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_104_203","chapterId":"ch_work_han_thu_104","textTraditional":"〔八〕　師古曰：「即無實事，當令有司窮治，盡其理。」","sentenceOrder":203},
  {"id":"s_work_han_thu_104_204","chapterId":"ch_work_han_thu_104","textTraditional":"〔九〕　師古曰：「自謂乞與之也。乞音氣。」","sentenceOrder":204},
  {"id":"s_work_han_thu_104_205","chapterId":"ch_work_han_thu_104","textTraditional":"〔一０〕師古曰：「悸，心動也，音揆。」","sentenceOrder":205},
  {"id":"s_work_han_thu_104_206","chapterId":"ch_work_han_thu_104","textTraditional":"〔一一〕師古曰：「曉者，告白意指也。通者，從公家通理也。光忿其拒諱，故不佑之。」","sentenceOrder":206},
  {"id":"s_work_han_thu_104_207","chapterId":"ch_work_han_thu_104","textTraditional":"〔一二〕師古曰：「齊讀曰齋。」","sentenceOrder":207},
  {"id":"s_work_han_thu_104_208","chapterId":"ch_work_han_thu_104","textTraditional":"〔一三〕晉灼曰：「使者至司農，司農發詔書，故鳴鼓也。」師古曰：「刎謂斷頸也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_104_209","chapterId":"ch_work_han_thu_104","textTraditional":"嚴延年字次卿，東海下邳人也。其父為丞相掾，延年少學法律丞相府，歸為郡吏。以選除補御史掾，舉侍御史。是時大將軍霍光廢昌邑王，尊立宣帝。宣帝初即位，延年劾奏光「擅廢立，亡人臣禮，不道」。奏雖寢，然朝廷肅焉敬憚。延年後復劾大司農田延年持兵干屬車，〔一〕大司農自訟不干屬車。事下御史中丞，譴責延年何以不移書宮殿門禁止大司農，而令得出入宮。於是覆劾延年闌內罪人，法至死。〔二〕延年亡命。會赦出，丞相御史府徵書同日到，延年以御史書先至，詣御史府，復為掾。宣帝識之，〔三〕拜為平陵令，坐殺不辜，去官。後為丞相掾，復擢好畤令。神爵中，西羌反，彊弩將軍許延壽請延年為長史，從軍敗西羌，還為涿郡太守。","sentenceOrder":209},
  {"id":"s_work_han_thu_104_210","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「干，犯也。屬車，天子後車也，音之欲反。」","sentenceOrder":210},
  {"id":"s_work_han_thu_104_211","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　張晏曰：「故事有所劾奏，並移宮門，禁止不得入。」師古曰：「覆，反也，反以此事劾之。覆音芳目反。」","sentenceOrder":211},
  {"id":"s_work_han_thu_104_212","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　張晏曰：「識其前劾霍光擅廢立。」","sentenceOrder":212},
  {"id":"s_work_han_thu_104_213","chapterId":"ch_work_han_thu_104","textTraditional":"時郡比得不能太守，〔一〕涿人畢野白等由是廢亂。〔二〕大姓西高氏、東高氏，〔三〕自郡吏以下皆畏避之，莫敢與啎，〔四〕咸曰：「寧負二千石，無負豪大家。」賓客放為盜賊，〔五〕發，輒入高氏，吏不敢追。浸浸日多，〔六〕道路張弓拔刃，然後敢行，其亂如此。延年至，遣掾蠡吾趙繡桉高氏得其死罪。繡見延年新將，〔七〕心內懼，即為兩劾，欲先白其輕者，觀延年意怒，乃出其重劾。延年已知其如此矣。趙掾至，果白其輕者，延年索懷中，得重劾，〔八〕即收送獄。夜入，晨將至市論殺之，先所桉者死，〔九〕吏皆股弁。〔一０〕更遣吏分考兩高，窮竟其姦，誅殺各數十人。郡中震恐，道不拾遺。","sentenceOrder":213},
  {"id":"s_work_han_thu_104_214","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「比，頻也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_104_215","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「廢公法而狡亂也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_104_216","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「兩高氏各以所居東西為號者。」","sentenceOrder":216},
  {"id":"s_work_han_thu_104_217","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「啎，逆也，音悟。」","sentenceOrder":217},
  {"id":"s_work_han_thu_104_218","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　師古曰：「放，縱也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_104_219","chapterId":"ch_work_han_thu_104","textTraditional":"〔六〕　師古曰：「浸，漸也。」","sentenceOrder":219},
  {"id":"s_work_han_thu_104_220","chapterId":"ch_work_han_thu_104","textTraditional":"〔七〕　師古曰：「新為郡將也，謂郡守為郡將者，以其兼領武事也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_104_221","chapterId":"ch_work_han_thu_104","textTraditional":"〔八〕　師古曰：「索，搜也，音山客反。」","sentenceOrder":221},
  {"id":"s_work_han_thu_104_222","chapterId":"ch_work_han_thu_104","textTraditional":"〔九〕　師古曰：「在高氏前死。」","sentenceOrder":222},
  {"id":"s_work_han_thu_104_223","chapterId":"ch_work_han_thu_104","textTraditional":"〔一０〕師古曰：「股戰若弁。弁謂撫手也。」","sentenceOrder":223},
  {"id":"s_work_han_thu_104_224","chapterId":"ch_work_han_thu_104","textTraditional":"三歲，遷河南太守，賜黃金二十斤。豪彊脅息，〔一〕野無行盜，威震旁郡。其治務在摧折豪彊，扶助貧弱。貧弱雖陷法，曲文以出之；其豪桀侵小民者，以文內之。〔二〕眾人所謂當死者，一朝出之；所謂當生者，詭殺之。〔三〕吏民莫能測其意深淺，戰栗不敢犯禁。桉其獄，皆文致不可得反。〔四〕","sentenceOrder":224},
  {"id":"s_work_han_thu_104_225","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「脅，斂也。屏氣而息。」","sentenceOrder":225},
  {"id":"s_work_han_thu_104_226","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「飾文而入之為罪。」","sentenceOrder":226},
  {"id":"s_work_han_thu_104_227","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「詭，違正理而殺也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_104_228","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「致，至密也。言其文案整密也。反音幡。」","sentenceOrder":228},
  {"id":"s_work_han_thu_104_229","chapterId":"ch_work_han_thu_104","textTraditional":"延年為人短小精悍，敏捷於事，〔一〕雖子貢、冉有通藝於政事，不能絕也。吏忠盡節者，厚遇之如骨肉，皆親鄉之，〔二〕出身不顧，以是治下無隱情。然疾惡泰甚，中傷者多，尤巧為獄文，善史書，所欲誅殺，奏成於手，中主簿親近史不得聞知。奏可論死，奄忽如神。冬月，傳屬縣囚，會論府上，〔三〕流血數里，河南號曰「屠伯」。〔四〕令行禁止，郡中正清。","sentenceOrder":229},
  {"id":"s_work_han_thu_104_230","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「悍，勁也。」","sentenceOrder":230},
  {"id":"s_work_han_thu_104_231","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":231},
  {"id":"s_work_han_thu_104_232","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「總集郡府而論殺。」","sentenceOrder":232},
  {"id":"s_work_han_thu_104_233","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　鄧展曰：「言延年殺人，如屠兒之殺六畜。伯，長也。」","sentenceOrder":233},
  {"id":"s_work_han_thu_104_234","chapterId":"ch_work_han_thu_104","textTraditional":"是時張敞為京兆尹，素與延年善。敞治雖嚴，然尚頗有縱舍，聞延年用刑刻急，乃以書諭之曰：「昔韓盧之取菟也，上觀下獲，〔一〕不甚多殺。願次卿少緩誅罰，思行此術。」延年報曰：「河南天下喉咽，二周餘斃，〔二〕莠（甚）〔盛〕苗穢，何可不鉏也？」〔三〕自矜伐其能，終不衰止。時黃霸在潁川以寬恕為治，郡中亦平，婁蒙豐年，〔四〕鳳皇下，上賢焉，下詔稱揚其行，加金爵之賞。延年素輕霸為人，及比郡為守，褒賞反在己前，〔五〕心內不服。河南界中又有蝗蟲，府丞義出行蝗，還見延年，延年曰：「此蝗豈鳳皇食邪？」義又道司農中丞耿壽昌為常平倉，利百姓，延年曰：「丞相御史不知為也，當避位去。壽昌安得權此？」〔六〕後左馮翊缺，上欲徵延年，符已發，為其名酷復止。〔七〕延年疑少府梁丘賀毀之，心恨。會琅邪太守以視事久病，滿三月免，延年自知見廢，謂丞曰：「此人尚能去官，我反不能去邪？」〔八〕又延年察獄史廉，有臧不入身，〔九〕延年坐選舉不實貶秩，笑曰：「後敢復有舉人者矣！」〔一０〕丞義年老頗悖，〔一一〕素畏延年，恐見中傷。延年本嘗與義俱為丞相史，實親厚之，無意毀傷也，饋遺之甚厚。義愈益恐，自筮得死卦，忽忽不樂，取告至長安，〔一二〕上書言延年罪名十事。已拜奏，因飲藥自殺，以明不欺。事下御史丞按驗，有此數事，以結延年，〔一三〕坐怨望非謗政治不道棄市。","sentenceOrder":234},
  {"id":"s_work_han_thu_104_235","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　應劭曰：「韓盧，六國時韓氏之黑犬也。」孟康曰：「言良犬之取菟，仰觀人主之意而獲之，喻不妄殺。」","sentenceOrder":235},
  {"id":"s_work_han_thu_104_236","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「喉咽，言其所在襟要，如人體之有喉咽也。二周，東西周君國也。咽音一千反。」","sentenceOrder":236},
  {"id":"s_work_han_thu_104_237","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「莠，秕穀所（在）〔生〕也。苗，粟苗也。莠音誘。」","sentenceOrder":237},
  {"id":"s_work_han_thu_104_238","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「婁，古屢字。」","sentenceOrder":238},
  {"id":"s_work_han_thu_104_239","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　師古曰：「比，接近也，音頻二反。」","sentenceOrder":239},
  {"id":"s_work_han_thu_104_240","chapterId":"ch_work_han_thu_104","textTraditional":"〔六〕　師古曰：「作此倉非奇異之功也，公卿不知為之，是曠官也。壽昌安得擅此以為權乎？」","sentenceOrder":240},
  {"id":"s_work_han_thu_104_241","chapterId":"ch_work_han_thu_104","textTraditional":"〔七〕　應劭曰：「符，竹使符也，臧在符節臺，欲有所拜，召治書御史符節令發符下太尉也。」","sentenceOrder":241},
  {"id":"s_work_han_thu_104_242","chapterId":"ch_work_han_thu_104","textTraditional":"〔八〕　師古曰：「與丞言云爾。」","sentenceOrder":242},
  {"id":"s_work_han_thu_104_243","chapterId":"ch_work_han_thu_104","textTraditional":"〔九〕　師古曰：「延年察舉其獄史為廉，而此人乃有臧罪，然臧不入身也。」","sentenceOrder":243},
  {"id":"s_work_han_thu_104_244","chapterId":"ch_work_han_thu_104","textTraditional":"〔一０〕師古曰：「言己濫被貶秩，後人寧敢復舉人乎？」","sentenceOrder":244},
  {"id":"s_work_han_thu_104_245","chapterId":"ch_work_han_thu_104","textTraditional":"〔一一〕師古曰：「心思惑亂。悖音布內反。」","sentenceOrder":245},
  {"id":"s_work_han_thu_104_246","chapterId":"ch_work_han_thu_104","textTraditional":"〔一二〕師古曰：「取休假。」","sentenceOrder":246},
  {"id":"s_work_han_thu_104_247","chapterId":"ch_work_han_thu_104","textTraditional":"〔一三〕師古曰：「結，正其罪也。」","sentenceOrder":247},
  {"id":"s_work_han_thu_104_248","chapterId":"ch_work_han_thu_104","textTraditional":"初，延年母從東海來，欲從延年臘，〔一〕到雒陽，適見報囚。〔二〕母大驚，便止都亭，不肯入府。延年出至都亭謁母，母閉閤不見。延年免冠頓首閤下，良久，母乃見之，因數責延年：〔三〕幸得備郡守，專治千里，不聞仁愛教化，有以全安愚民，顧乘刑罰多刑殺人，〔四〕欲以立威，豈為民父母意哉！」延年服罪，重頓首謝〔五〕，因自為母御，歸府舍。母畢正臘，〔六〕謂延年：「天道神明，人不可獨殺。〔七〕我不意當老見壯子被刑戮也！〔八〕行矣！去女東歸，埽除墓地耳。」〔九〕遂去。歸郡，見昆弟宗人，復為言之。後歲餘，果敗。東海莫不賢知其母。〔一０〕延年兄弟五人皆有吏材，至大官，東海號曰「萬石嚴嫗」。〔一一〕次弟彭祖，至太子太傅，在儒林傳。","sentenceOrder":248},
  {"id":"s_work_han_thu_104_249","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　師古曰：「建丑之（日）〔月〕為臘祭，因會飲，若今之蜡節也。」","sentenceOrder":249},
  {"id":"s_work_han_thu_104_250","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「奏報行決也。」","sentenceOrder":250},
  {"id":"s_work_han_thu_104_251","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「數音所具反。」","sentenceOrder":251},
  {"id":"s_work_han_thu_104_252","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「顧，反也。乘，因也。」","sentenceOrder":252},
  {"id":"s_work_han_thu_104_253","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　師古曰：「重音直用反。」","sentenceOrder":253},
  {"id":"s_work_han_thu_104_254","chapterId":"ch_work_han_thu_104","textTraditional":"〔六〕　師古曰：「臘及正歲禮畢也。正音之盈反。」","sentenceOrder":254},
  {"id":"s_work_han_thu_104_255","chapterId":"ch_work_han_thu_104","textTraditional":"〔七〕　師古曰：「言多殺人者，己亦當死。」","sentenceOrder":255},
  {"id":"s_work_han_thu_104_256","chapterId":"ch_work_han_thu_104","textTraditional":"〔八〕　師古曰：「言素意不自謂如此也。」","sentenceOrder":256},
  {"id":"s_work_han_thu_104_257","chapterId":"ch_work_han_thu_104","textTraditional":"〔九〕　師古曰：「言待其喪至也。」","sentenceOrder":257},
  {"id":"s_work_han_thu_104_258","chapterId":"ch_work_han_thu_104","textTraditional":"〔一０〕師古曰：「稱其賢知也。」","sentenceOrder":258},
  {"id":"s_work_han_thu_104_259","chapterId":"ch_work_han_thu_104","textTraditional":"〔一一〕師古曰：「一門之中五二千石，故總云萬石。」","sentenceOrder":259},
  {"id":"s_work_han_thu_104_260","chapterId":"ch_work_han_thu_104","textTraditional":"尹賞字子心，鉅鹿楊氏人也。以郡吏察廉為樓煩長。舉茂材，粟邑令。左馮翊薛宣奏賞能治劇，徙為頻陽令，坐殘賊免。後以御史舉為鄭令。","sentenceOrder":260},
  {"id":"s_work_han_thu_104_261","chapterId":"ch_work_han_thu_104","textTraditional":"永治、元延間，上怠於政，貴戚驕恣，紅陽長仲兄弟交通輕俠，臧匿亡命。〔一〕而北地大豪浩商等報怨，殺義渠長妻子六人，往來長安中。丞相御史遣掾求逐黨與，詔書召捕，久之乃得。長安中姦滑浸多，閭里少年群輩殺吏，受賕報仇，〔二〕相與探丸為彈，〔三〕得赤丸者斫武吏，得黑丸者斫文吏，白者主治喪；〔四〕城中薄暮塵起，剽劫行者，死傷橫道，枹鼓不絕。〔五〕賞以三輔高第選守長安令，得壹切便宜從事。賞至，修治長安獄，穿地方深各數丈，致令辟為郭，〔六〕以大石覆其口，名為「虎穴」。乃部戶曹掾史，與鄉吏、亭長、里正、父老、伍人，〔七〕雜舉長安中輕薄少年惡子，〔八〕無市籍商販作務，而鮮衣凶服被鎧扞持刀兵者，悉籍記之，〔九〕得數百人。賞一朝會長安吏，車數百兩，分行收捕，皆劾以為通行飲食群盜。〔一０〕賞親閱，見十置一，〔一一〕其餘盡以次內虎穴中，百人為輩，覆以大石。數日壹發視，皆相枕藉死，便輿出，瘞寺門桓東，〔一二〕楬著其姓名，〔一三〕百日後，乃令死者家各自發取其尸。親屬號哭，道路皆歔欷。長安中歌之曰：「安所求子死？桓東少年場。〔一四〕生時諒不謹，枯骨後何葬？」〔一五〕賞所置皆其魁宿，〔一六〕或故吏善家子失計隨輕黠願自改者，財數十百人〔一七〕，皆貰其罪，〔一八〕詭令立功以自贖。〔一九〕盡力有效者，因親用之為爪牙，追捕甚精，甘耆姦惡，甚於凡吏。〔二０〕賞視事數月，盜賊止，郡國亡命散走，各歸其處，不敢闚長安。","sentenceOrder":261},
  {"id":"s_work_han_thu_104_262","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　鄧展曰：「紅陽姓，長仲字也。」如淳曰：「紅陽，南陽縣也。長姓，仲字也。」師古曰：「姓紅陽而兄字長，弟字仲。今書長字或作張者非也，後人所改耳。一曰紅陽侯王立之子，兄弟長少者也。」","sentenceOrder":262},
  {"id":"s_work_han_thu_104_263","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「或有自怨於吏，或受人賕賂報仇讎也。」","sentenceOrder":263},
  {"id":"s_work_han_thu_104_264","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「為彈丸作赤、黑、白三色，而共探取之也。彈音徒旦反。」","sentenceOrder":264},
  {"id":"s_work_han_thu_104_265","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「其黨與有為吏及它人所殺者，則主其喪事也。」","sentenceOrder":265},
  {"id":"s_work_han_thu_104_266","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　師古曰：「枹，擊鼓椎也，音孚。其字從木。」","sentenceOrder":266},
  {"id":"s_work_han_thu_104_267","chapterId":"ch_work_han_thu_104","textTraditional":"〔六〕　師古曰：「致謂積累之也。令辟，〈鹿瓦〉磚也。郭謂四周之內也。致讀如本字，又音綴。令音零。辟音避歷反。」","sentenceOrder":267},
  {"id":"s_work_han_thu_104_268","chapterId":"ch_work_han_thu_104","textTraditional":"〔七〕　師古曰：「五家為伍。伍人者，各其同伍之人也。」","sentenceOrder":268},
  {"id":"s_work_han_thu_104_269","chapterId":"ch_work_han_thu_104","textTraditional":"〔八〕　師古曰：「惡子，不承父母教命者。」","sentenceOrder":269},
  {"id":"s_work_han_thu_104_270","chapterId":"ch_work_han_thu_104","textTraditional":"〔九〕　師古曰：「凶服，危險之服。鎧，甲也，扞，臂衣也。籍記，為名籍以記之。」","sentenceOrder":270},
  {"id":"s_work_han_thu_104_271","chapterId":"ch_work_han_thu_104","textTraditional":"〔一０〕師古曰：「飲音於禁反。食讀曰飤。」","sentenceOrder":271},
  {"id":"s_work_han_thu_104_272","chapterId":"ch_work_han_thu_104","textTraditional":"〔一一〕師古曰：「置，放也。」","sentenceOrder":272},
  {"id":"s_work_han_thu_104_273","chapterId":"ch_work_han_thu_104","textTraditional":"〔一二〕如淳曰：「瘞，埋也。舊亭傳於四角面百步築土四方，上有屋，屋上有柱出，高丈餘，有大板貫柱四出，名曰桓表。縣所治夾兩邊各一桓。陳宋之俗言桓聲如和，今猶謂之和表。」師古曰：「即華表也。」","sentenceOrder":273},
  {"id":"s_work_han_thu_104_274","chapterId":"ch_work_han_thu_104","textTraditional":"〔一三〕師古曰：「楬，杙也。椓杙於瘞處而書死者名也。楬音竭，杙音弋，字並從木。」","sentenceOrder":274},
  {"id":"s_work_han_thu_104_275","chapterId":"ch_work_han_thu_104","textTraditional":"〔一四〕師古曰：「安猶焉也。死謂尸也。」","sentenceOrder":275},
  {"id":"s_work_han_thu_104_276","chapterId":"ch_work_han_thu_104","textTraditional":"〔一五〕師古曰：「諒，信也。葬字合韻音子郎反。」","sentenceOrder":276},
  {"id":"s_work_han_thu_104_277","chapterId":"ch_work_han_thu_104","textTraditional":"〔一六〕師古曰：「魁，根本也。宿，久舊也。」","sentenceOrder":277},
  {"id":"s_work_han_thu_104_278","chapterId":"ch_work_han_thu_104","textTraditional":"〔一七〕師古曰：「財與纔同。」","sentenceOrder":278},
  {"id":"s_work_han_thu_104_279","chapterId":"ch_work_han_thu_104","textTraditional":"〔一八〕師古曰：「貰，緩也。」","sentenceOrder":279},
  {"id":"s_work_han_thu_104_280","chapterId":"ch_work_han_thu_104","textTraditional":"〔一九〕師古曰：「詭，責也。」","sentenceOrder":280},
  {"id":"s_work_han_thu_104_281","chapterId":"ch_work_han_thu_104","textTraditional":"〔二０〕師古曰：「耆讀曰嗜。」","sentenceOrder":281},
  {"id":"s_work_han_thu_104_282","chapterId":"ch_work_han_thu_104","textTraditional":"江湖中多盜賊，以賞為江夏太守，捕格江賊及所誅吏民甚多，坐殘賊免。南山群盜起，以賞為右輔都尉，遷執金吾，督大姦猾。三輔吏民甚畏之。","sentenceOrder":282},
  {"id":"s_work_han_thu_104_283","chapterId":"ch_work_han_thu_104","textTraditional":"數年卒官。疾病且死，戒其諸子曰：「丈夫為吏，正坐殘賊免，追思其功效，則復進用矣。一坐軟弱不勝任免，終身廢棄無有赦時，其羞辱甚於貪汙坐臧。慎毋然！」賞四子皆至郡守，長子立為京兆尹，皆尚威嚴，有治辦名。","sentenceOrder":283},
  {"id":"s_work_han_thu_104_284","chapterId":"ch_work_han_thu_104","textTraditional":"贊曰：自郅都以下皆以酷烈為聲，然都抗直，引是非，爭大體。張湯以知阿邑人主，與俱上下，〔一〕時辯當否，國家賴其便。趙禹据法守正。〔二〕杜周從諛，以少言為重。張湯死後，罔密事叢〔三〕，以寖耗廢，〔四〕九卿奉職，救（國）〔過〕不給，〔五〕何暇論繩墨之外乎！自是以至哀、平，酷吏眾多，然莫足數，此其知名見紀者也。其廉者足以為儀表，〔六〕其汙者方略教道，壹切禁姦〔七〕，亦質有文武焉。雖酷，稱其位矣。〔八〕湯、周子孫貴盛，故別傳。〔九〕","sentenceOrder":284},
  {"id":"s_work_han_thu_104_285","chapterId":"ch_work_han_thu_104","textTraditional":"〔一〕　蘇林曰：「邑音人相悒納之悒。」師古曰：「如蘇氏之說，邑字音烏合反。然今之書本或作色字，以言阿諛，觀人主顏色而上下也。其義兩通。」","sentenceOrder":285},
  {"id":"s_work_han_thu_104_286","chapterId":"ch_work_han_thu_104","textTraditional":"〔二〕　師古曰：「据音據。」","sentenceOrder":286},
  {"id":"s_work_han_thu_104_287","chapterId":"ch_work_han_thu_104","textTraditional":"〔三〕　師古曰：「叢謂眾也。」","sentenceOrder":287},
  {"id":"s_work_han_thu_104_288","chapterId":"ch_work_han_thu_104","textTraditional":"〔四〕　師古曰：「寖，漸也。耗，亂也，音莫報反。」","sentenceOrder":288},
  {"id":"s_work_han_thu_104_289","chapterId":"ch_work_han_thu_104","textTraditional":"〔五〕　師古曰：「給，供也。」","sentenceOrder":289},
  {"id":"s_work_han_thu_104_290","chapterId":"ch_work_han_thu_104","textTraditional":"〔六〕　師古曰：「謂有儀形可表明者。」","sentenceOrder":290},
  {"id":"s_work_han_thu_104_291","chapterId":"ch_work_han_thu_104","textTraditional":"〔七〕　師古曰：「汙，濁也。道讀曰導。」","sentenceOrder":291},
  {"id":"s_work_han_thu_104_292","chapterId":"ch_work_han_thu_104","textTraditional":"〔八〕　師古曰：「稱音尺孕反。」","sentenceOrder":292},
  {"id":"s_work_han_thu_104_293","chapterId":"ch_work_han_thu_104","textTraditional":"〔九〕　師古曰：「言所以不列於酷吏之篇也。」","sentenceOrder":293},
  {"id":"s_work_han_thu_104_294","chapterId":"ch_work_han_thu_104","textTraditional":"校勘記","sentenceOrder":294},
  {"id":"s_work_han_thu_104_295","chapterId":"ch_work_han_thu_104","textTraditional":"三六四五頁　五行　然（不）〔姦〕軌愈起，　景祐、殿本都作「姦」。王先謙說作「姦」是。","sentenceOrder":295},
  {"id":"s_work_han_thu_104_296","chapterId":"ch_work_han_thu_104","textTraditional":"三六四九頁　五行　不令（致）〔至〕闕陳謝也。　景祐、殿本都作「至」。王先謙說作「至」是。","sentenceOrder":296},
  {"id":"s_work_han_thu_104_297","chapterId":"ch_work_han_thu_104","textTraditional":"三六五０頁一三行　（議）〔義〕不受刑，自殺，　劉敞、王先謙都說「議」當為「義」。史記不誤。","sentenceOrder":297},
  {"id":"s_work_han_thu_104_298","chapterId":"ch_work_han_thu_104","textTraditional":"三六五二頁　三行　公卿相造請，〔二〕禹終不行報謝，務在絕知友賓客之請，〔三〕孤立行一意而已。　注〔二〕原在「不行」下，明顏讀「報謝」屬下句。劉敞說「報謝」當屬上句。按史記此句作「禹終不報謝」，則劉說是。茲從殿本。","sentenceOrder":298},
  {"id":"s_work_han_thu_104_299","chapterId":"ch_work_han_thu_104","textTraditional":"三六五三頁一五行　及孔、暴之屬皆奔亡，〔四〕南陽吏民重足一跡。　注〔四〕原在「南陽」下。劉攽說「南陽」屬下句。按史記讀如劉說。","sentenceOrder":299},
  {"id":"s_work_han_thu_104_300","chapterId":"ch_work_han_thu_104","textTraditional":"三六六一頁一一行　稍遷至御史及〔中〕丞，　王先謙說史記「丞」作「中丞」，此奪。下文亦作「中丞」，尤其明證。","sentenceOrder":300},
  {"id":"s_work_han_thu_104_301","chapterId":"ch_work_han_thu_104","textTraditional":"三六七０頁　六行　莠（甚）〔盛〕苗穢，　景祐、殿本都作「盛」。","sentenceOrder":301},
  {"id":"s_work_han_thu_104_302","chapterId":"ch_work_han_thu_104","textTraditional":"三六七一頁　五行　莠，秕穀所（在）〔生〕也。　景祐、殿本都作「生」。王先謙說作「生」是。","sentenceOrder":302},
  {"id":"s_work_han_thu_104_303","chapterId":"ch_work_han_thu_104","textTraditional":"三六七二頁　八行　建丑之（日）〔月〕為臘祭，　景祐、殿本都作「月」，此誤。","sentenceOrder":303},
  {"id":"s_work_han_thu_104_304","chapterId":"ch_work_han_thu_104","textTraditional":"三六七六頁　三行　救（國）〔過〕不給，　景祐、殿本都作「過」。","sentenceOrder":304},
  {"id":"s_work_han_thu_105_1","chapterId":"ch_work_han_thu_105","textTraditional":"昔先王之制，自天子公侯卿大夫士至于皁隸抱關擊橛者，〔一〕其爵祿奉養宮室車服棺槨祭祀死生之制各有差品，小不得僭大，賤不得踰貴。夫然，故上下序而民志定。於是辯其土地川澤丘陵衍沃原隰之宜，〔二〕教民種樹畜養；〔三〕五穀六畜及至魚鱉鳥獸雚蒲材幹器械之資，〔四〕所以養生送終之具，靡不皆育。育之以時，而用之有節。屮木未落，斧斤不入於山林；〔五〕豺獺未祭，罝網不布於野澤；〔六〕鷹隼未擊，矰弋不施於徯隧。〔七〕既順時而取物，然猶山不茬櫱，澤不伐夭，〔八〕蝝魚麛卵，咸有常禁。〔九〕所以順時宣氣，蕃阜庶物，〔一０〕蓄足功用，如此之備也。〔一一〕然後四民因其土宜，各任智力，夙興夜寐，以治其業，相與通功易事，交利而俱贍，〔一二〕非有徵發期會，而遠近咸足。故易曰「后以財成輔相天地之宜，以左右民」，〔一三〕「備物致用，立成器以為天下利，莫大乎聖人」，〔一四〕此之謂也。管子云古之四民不得雜處〔一五〕。士相與言仁誼於閒宴，〔一六〕工相與議技巧於官府，商相與語財利於市井，〔一七〕農相與謀稼穡於田野，朝夕從事，不見異物而遷焉。〔一八〕故其父兄之教不肅而成，子弟之學不勞而能，各安其居而樂其業，甘其食而美其服，雖見奇麗紛華，非其所習，辟猶戎翟之與于越，不相入矣。〔一九〕是以欲寡而事節，財足而不爭。於是在民上者，道之以德，〔二０〕齊之以禮，故民有恥而且敬，貴誼而賤利。此三代之所以直道而行，不嚴而治之大略也。〔二一〕","sentenceOrder":1},
  {"id":"s_work_han_thu_105_2","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「皁，養馬者也。隸之言著也，屬著於人也。抱關，守門者也。擊橛，守夜擊木以警眾也。橛音土各反。」","sentenceOrder":2},
  {"id":"s_work_han_thu_105_3","chapterId":"ch_work_han_thu_105","textTraditional":"〔二〕　師古曰：「衍謂地平延者也。沃，水之所灌沃也。廣平曰原，下溼曰隰。」","sentenceOrder":3},
  {"id":"s_work_han_thu_105_4","chapterId":"ch_work_han_thu_105","textTraditional":"〔三〕　師古曰：「樹，殖也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_105_5","chapterId":"ch_work_han_thu_105","textTraditional":"〔四〕　師古曰：「雚，薍也，即今之荻也。械者，器之總名也。雚音桓。薍音五宦反。荻音敵。」","sentenceOrder":5},
  {"id":"s_work_han_thu_105_6","chapterId":"ch_work_han_thu_105","textTraditional":"〔五〕　師古曰：「禮記月令云：『季秋之月，草木黃落，乃伐薪為炭。』」","sentenceOrder":6},
  {"id":"s_work_han_thu_105_7","chapterId":"ch_work_han_thu_105","textTraditional":"〔六〕　師古曰：「禮記王制云：『獺祭魚，然後虞人入澤梁；豺祭獸，然後田獵。』月令：『孟春之月，獺祭魚。』『季秋之月，豺乃祭獸戮禽。』罝，兔網也，音嗟。」","sentenceOrder":7},
  {"id":"s_work_han_thu_105_8","chapterId":"ch_work_han_thu_105","textTraditional":"〔七〕　師古曰：「隼亦鷙鳥，即今所呼為鶻者也。月令：『孟秋之月，鷹乃祭鳥，用始行戮。』弋，繳射也。矰者，弋之矢也。徯隧，徑道也。矰音曾。徯音奚。隧音遂。鶻音胡骨反。」","sentenceOrder":8},
  {"id":"s_work_han_thu_105_9","chapterId":"ch_work_han_thu_105","textTraditional":"〔八〕　師古曰：「茬，古槎字也。槎，邪斫木也。櫱，髡斬之也。此夭謂草木之方長未成者也。槎音士牙反。櫱音五葛反。夭音烏老反。」","sentenceOrder":9},
  {"id":"s_work_han_thu_105_10","chapterId":"ch_work_han_thu_105","textTraditional":"〔九〕　師古曰：「蝝，小蟲也。麛，鹿子也。卵，鳥卵也。月令：『孟春之月，毋殺孩蟲，毋麛毋卵。』蝝音弋全反。麛音草奚反。」","sentenceOrder":10},
  {"id":"s_work_han_thu_105_11","chapterId":"ch_work_han_thu_105","textTraditional":"〔一０〕師古曰：「蕃，多也。阜，盛也。蕃音扶元反。」","sentenceOrder":11},
  {"id":"s_work_han_thu_105_12","chapterId":"ch_work_han_thu_105","textTraditional":"〔一一〕師古曰：「稸即蓄字。」","sentenceOrder":12},
  {"id":"s_work_han_thu_105_13","chapterId":"ch_work_han_thu_105","textTraditional":"〔一二〕師古曰：「言以其所有，交易所無，而不匱乏。」","sentenceOrder":13},
  {"id":"s_work_han_thu_105_14","chapterId":"ch_work_han_thu_105","textTraditional":"〔一三〕師古曰：「泰卦象辭也。后，君也。左右，助也。言王者資財用以成教，贊天地之化育，以救助其眾庶也。左右讀曰佐佑。」","sentenceOrder":14},
  {"id":"s_work_han_thu_105_15","chapterId":"ch_work_han_thu_105","textTraditional":"〔一四〕師古曰：「上繫之辭也。備物致用，謂備取百物而極其功用。」","sentenceOrder":15},
  {"id":"s_work_han_thu_105_16","chapterId":"ch_work_han_thu_105","textTraditional":"〔一五〕師古曰：「管仲之書也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_105_17","chapterId":"ch_work_han_thu_105","textTraditional":"〔一六〕師古曰：「閒讀曰閑。」","sentenceOrder":17},
  {"id":"s_work_han_thu_105_18","chapterId":"ch_work_han_thu_105","textTraditional":"〔一七〕師古曰：「凡言市井者，市交易之處，井共汲之所，故總而言之也。說者云因井而為市，其義非也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_105_19","chapterId":"ch_work_han_thu_105","textTraditional":"〔一八〕師古曰：「言非其本業則弗觀視，故能各精其事，不移易。」","sentenceOrder":19},
  {"id":"s_work_han_thu_105_20","chapterId":"ch_work_han_thu_105","textTraditional":"〔一九〕孟康曰：「于越，南方越名也。」師古曰：「于，發語聲也。戎蠻之語則然。于越猶句吳耳。辟讀曰譬。」","sentenceOrder":20},
  {"id":"s_work_han_thu_105_21","chapterId":"ch_work_han_thu_105","textTraditional":"〔二０〕師古曰：「道讀曰導。」","sentenceOrder":21},
  {"id":"s_work_han_thu_105_22","chapterId":"ch_work_han_thu_105","textTraditional":"〔二一〕師古曰：「直道而行，謂以德禮率下，不飾偽也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_105_23","chapterId":"ch_work_han_thu_105","textTraditional":"及周室衰，禮法墮，〔一〕諸侯刻桷丹楹，大夫山節藻梲，〔二〕八佾舞於庭，雍徹於堂。〔三〕其流至乎士庶人，莫不離制而棄本，稼穡之民少，商旅之民多，穀不足而貨有餘。","sentenceOrder":23},
  {"id":"s_work_han_thu_105_24","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「墮，毀也，音火規反。」","sentenceOrder":24},
  {"id":"s_work_han_thu_105_25","chapterId":"ch_work_han_thu_105","textTraditional":"〔二〕　師古曰：「桷，椽也。楹，柱也。節，栭也。山，刻為山形也。梲，侏儒柱也。藻謂刻鏤為水藻之文也。刻桷丹楹，魯桓宮也。山節藻梲，臧文仲也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_105_26","chapterId":"ch_work_han_thu_105","textTraditional":"〔三〕　師古曰：「八列舞於庭，謂季氏也。以雍樂徹食，三家則然，事見論語。」","sentenceOrder":26},
  {"id":"s_work_han_thu_105_27","chapterId":"ch_work_han_thu_105","textTraditional":"陵夷至乎桓、文之後，〔一〕禮誼大壞，上下相冒，國異政，家殊俗，耆欲不制，僭差亡極。〔二〕於是商通難得之貨，工作亡用之器，士設反道之行，以追時好而取世資。〔三〕偽民背實而要名，姦夫犯害而求利，篡弒取國者為王公，圉奪成家者為雄桀。〔四〕禮誼不足以拘君子，刑戮不足以威小人。富者木土被文錦，犬馬餘肉粟，而貧者裋褐不完，唅菽飲水。〔五〕其為編戶齊民，同列而以財力相君，雖為僕虜，猶亡慍色。故夫飾變詐為姦軌者，自足乎一世之間；守道循理者，不免於飢寒之患。其教自上興，繇法度之無限也。〔六〕故列其行事，以傳世變云。","sentenceOrder":27},
  {"id":"s_work_han_thu_105_28","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「齊桓、晉文也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_105_29","chapterId":"ch_work_han_thu_105","textTraditional":"〔二〕　師古曰：「耆讀曰嗜，其下並同。極，止也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_105_30","chapterId":"ch_work_han_thu_105","textTraditional":"〔三〕　師古曰：「追，逐也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_105_31","chapterId":"ch_work_han_thu_105","textTraditional":"〔四〕　師古曰：「圉謂禁守其人也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_105_32","chapterId":"ch_work_han_thu_105","textTraditional":"〔五〕　師古曰：「裋，布長襦也。褐，編枲衣也。裋音豎。唅亦含字也。菽，豆也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_105_33","chapterId":"ch_work_han_thu_105","textTraditional":"〔六〕　師古曰：「繇讀與由同。」","sentenceOrder":33},
  {"id":"s_work_han_thu_105_34","chapterId":"ch_work_han_thu_105","textTraditional":"昔粵王句踐困於會稽之上，乃用范蠡、計然。〔一〕計然曰：「知鬥則修備，時用則知物，二者形則萬貨之情可得見矣。〔二〕故旱則資舟，水則資車，物之理也。」〔三〕推此類而脩之，十年國富，厚賂戰士，遂報彊吳，刷會稽之恥。〔四〕范蠡歎曰：「計然之策，十用其五而得意。既以施國，吾欲施之家。」乃乘扁舟，〔五〕浮江湖，變姓名，適齊為鴟夷子皮，〔六〕之陶為朱公。〔七〕以為陶天下之中，諸侯四通，貨物所交易也，乃治產積居，與時逐〔八〕而不責於人。故善治產者，能擇人而任時。十九年之間三致千金，而再散分與貧友昆弟。後年衰老，聽子孫脩業而息之，〔九〕遂至鉅萬。故言富者稱陶朱。","sentenceOrder":34},
  {"id":"s_work_han_thu_105_35","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　孟康曰：「姓計名然，越臣也。」蔡謨曰：「計然者，范蠡所著書篇名耳，非人也。謂之計然者，所計而然也。群書所稱句踐之賢佐，種、蠡為首，豈聞復有姓計名然者乎？若有此人，越但用半策便以致霸，是功重於范蠡，蠡之師也，焉有如此而越國不記其事，書籍不見其名，史遷不述其傳乎？」師古曰：「蔡說謬矣。據古今人表，計然列在第四等，豈是范蠡書篇乎？計然一號計研，故賓戲曰『研、桑心計於無垠』，即謂此耳。計然者，濮上人也，博學無所不通，尤善計算，嘗南遊越，范蠡卑身事之。其書則有萬物錄，著五方所出，皆直述之。事見皇覽及晉中經簿。又吳越春秋及越絕書並作計倪，此則倪、研及然聲皆相近，實一人耳。何云書籍不見哉？」","sentenceOrder":35},
  {"id":"s_work_han_thu_105_36","chapterId":"ch_work_han_thu_105","textTraditional":"〔二〕　師古曰：「形，顯見。」","sentenceOrder":36},
  {"id":"s_work_han_thu_105_37","chapterId":"ch_work_han_thu_105","textTraditional":"〔三〕　師古曰：「旱極則水，水極則旱，故於旱時而預蓄舟，水時預蓄車，以待其貴，收其利也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_105_38","chapterId":"ch_work_han_thu_105","textTraditional":"〔四〕　師古曰：「刷謂拭除之也，音所劣反。」","sentenceOrder":38},
  {"id":"s_work_han_thu_105_39","chapterId":"ch_work_han_thu_105","textTraditional":"〔五〕　孟康曰：「特舟也。」師古曰：「音匹延反。」","sentenceOrder":39},
  {"id":"s_work_han_thu_105_40","chapterId":"ch_work_han_thu_105","textTraditional":"〔六〕　師古曰：「自號鴟夷者，言若盛酒之鴟夷，多所容受，而可卷懷，與時張弛也。鴟夷，皮之所為，故曰子皮。」","sentenceOrder":40},
  {"id":"s_work_han_thu_105_41","chapterId":"ch_work_han_thu_105","textTraditional":"〔七〕　孟康曰：「陶即今定陶也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_105_42","chapterId":"ch_work_han_thu_105","textTraditional":"〔八〕　孟康曰：「逐時而居買也。」師古曰：「此說非也。言豫居貨物隨時而逐利。」","sentenceOrder":42},
  {"id":"s_work_han_thu_105_43","chapterId":"ch_work_han_thu_105","textTraditional":"〔九〕　師古曰：「息，生也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_105_44","chapterId":"ch_work_han_thu_105","textTraditional":"子贛既學於仲尼，退而仕衛，〔一〕發貯鬻財曹、魯之間。〔二〕七十子之徒，賜最為饒，〔三〕而顏淵簞食瓢飲，在于陋巷。〔四〕子贛結駟連騎，束帛之幣聘享儲侯，所至，國君無不分庭與之抗禮。〔五〕然孔子賢顏淵而譏子贛，曰：「回也其庶乎，屢空。賜不受命，而貨殖焉，意則屢中。」〔六〕","sentenceOrder":44},
  {"id":"s_work_han_thu_105_45","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「孔子弟子，姓端木，名賜也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_105_46","chapterId":"ch_work_han_thu_105","textTraditional":"〔二〕　師古曰：「多有積貯，趣時而發。鬻，賣之也。鬻音弋六反。」","sentenceOrder":46},
  {"id":"s_work_han_thu_105_47","chapterId":"ch_work_han_thu_105","textTraditional":"〔三〕　師古曰：「言於弟子之中最為富。」","sentenceOrder":47},
  {"id":"s_work_han_thu_105_48","chapterId":"ch_work_han_thu_105","textTraditional":"〔四〕　師古曰：「簞，笥也。食，飯也。瓢，瓠勺也。一簞之飯，一瓢之飲，至貧也。簞音丁安反。食音似。瓢音頻遙反。」","sentenceOrder":48},
  {"id":"s_work_han_thu_105_49","chapterId":"ch_work_han_thu_105","textTraditional":"〔五〕　師古曰：「為賓主之禮。」","sentenceOrder":49},
  {"id":"s_work_han_thu_105_50","chapterId":"ch_work_han_thu_105","textTraditional":"〔六〕　師古曰：「論語載孔子之言也。顏回庶幾聖道，雖數空匱，而樂在其中。子贛不受教命，唯財是殖，億度是非，幸而中耳。意讀曰億。中音竹仲反。」","sentenceOrder":50},
  {"id":"s_work_han_thu_105_51","chapterId":"ch_work_han_thu_105","textTraditional":"白圭，周人也。當魏文侯時，李克務盡地力，而白圭樂觀時變，故人棄我取，人取我予。能薄飲食，忍嗜欲，節衣服，與用事僮僕同苦樂，趨時若猛獸摯鳥之發。故曰：「吾治生猶伊尹、呂尚之謀，孫吳用兵，商鞅行法是也。故智不足與權變，勇不足以決斷，仁不能以取予，彊不能以有守，雖欲學吾術，終不告也。」蓋天下言治生者祖白圭。〔一〕","sentenceOrder":51},
  {"id":"s_work_han_thu_105_52","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「祖，始也，以其法為本始也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_105_53","chapterId":"ch_work_han_thu_105","textTraditional":"猗頓用盬鹽起，〔一〕邯鄲郭縱以鑄冶成業，與王者埒富。〔二〕","sentenceOrder":53},
  {"id":"s_work_han_thu_105_54","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「猗頓，魯之窮士也。盬，鹽池也。於盬造鹽，故曰盬鹽。盬音古。」","sentenceOrder":54},
  {"id":"s_work_han_thu_105_55","chapterId":"ch_work_han_thu_105","textTraditional":"〔二〕　師古曰：「埒，等也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_105_56","chapterId":"ch_work_han_thu_105","textTraditional":"烏氏蠃畜牧，〔一〕及眾，斥賣，〔二〕求奇繒物，間獻戎王。〔三〕戎王十倍其償，予畜，畜至用谷量牛馬。〔四〕秦始皇令蠃比封君，以時與列臣朝請。〔五〕","sentenceOrder":56},
  {"id":"s_work_han_thu_105_57","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「氏音支，烏氏，姓也。蠃，名也。其人為畜牧之業也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_105_58","chapterId":"ch_work_han_thu_105","textTraditional":"〔二〕　師古曰：「畜牧蕃盛，其數多則出而賣之也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_105_59","chapterId":"ch_work_han_thu_105","textTraditional":"〔三〕　師古曰：「避時之禁，故伺閒隙私遺戎王。」","sentenceOrder":59},
  {"id":"s_work_han_thu_105_60","chapterId":"ch_work_han_thu_105","textTraditional":"〔四〕　師古曰：「言其數饒不可計算，故以山谷多少言之。」","sentenceOrder":60},
  {"id":"s_work_han_thu_105_61","chapterId":"ch_work_han_thu_105","textTraditional":"〔五〕　師古曰：「與讀曰豫。請音才性反。」","sentenceOrder":61},
  {"id":"s_work_han_thu_105_62","chapterId":"ch_work_han_thu_105","textTraditional":"巴寡婦清，〔一〕其先得丹穴，而擅其利數世，〔二〕家亦不訾。〔三〕清寡婦能守其業，用財自衛，人不敢犯。始皇以為貞婦而客之，為築女懷清臺。","sentenceOrder":62},
  {"id":"s_work_han_thu_105_63","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「以其行絜，故號曰清也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_105_64","chapterId":"ch_work_han_thu_105","textTraditional":"〔二〕　師古曰：「丹，丹砂也。穴者，山谷之穴出丹也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_105_65","chapterId":"ch_work_han_thu_105","textTraditional":"〔三〕　師古曰：「言資財眾多無限數。訾音子移反。」","sentenceOrder":65},
  {"id":"s_work_han_thu_105_66","chapterId":"ch_work_han_thu_105","textTraditional":"秦漢之制，列侯封君食租稅，歲率戶二百。千戶之君則二十萬，朝覲聘享出其中。庶民農工商賈，率亦歲萬息二千，百萬之家即二十萬，而更繇租賦出其中，〔一〕衣食好美矣。故曰陸地牧馬二百蹄，〔二〕牛千蹄角，〔三〕千足羊，〔四〕澤中千足彘，水居千石魚波，〔五〕山居千章之萩。〔六〕安邑千樹棗；燕、秦千樹栗；蜀、漢、江陵千樹橘；淮北滎南河濟之間千樹萩；〔七〕陳、夏千畝桼〔八〕；齊、魯千畝桑麻；渭川千畝竹；及名國萬家之城，帶郭千畝畝鐘之田，〔九〕若千畝卮茜，〔一０〕千畦薑韭：〔一一〕此其人皆與千戶侯等。","sentenceOrder":66},
  {"id":"s_work_han_thu_105_67","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「更音工衡反，繇讀曰徭。」","sentenceOrder":67},
  {"id":"s_work_han_thu_105_68","chapterId":"ch_work_han_thu_105","textTraditional":"〔二〕　孟康曰：「五十匹也。」師古曰：「蹄，古蹄字。」","sentenceOrder":68},
  {"id":"s_work_han_thu_105_69","chapterId":"ch_work_han_thu_105","textTraditional":"〔三〕　孟康曰：「百六十七頭也。馬貴而牛賤，以此為率也。」師古曰：「百六十七頭牛，則為蹄與角凡一千二也。言千者，舉成數也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_105_70","chapterId":"ch_work_han_thu_105","textTraditional":"〔四〕　師古曰：「凡言千足者，二百五十頭也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_105_71","chapterId":"ch_work_han_thu_105","textTraditional":"〔五〕　師古曰：「波讀曰陂。言有大陂養魚，一歲收千石魚也。說者不曉，及改其波字為皮，又讀為披，皆失之矣。」","sentenceOrder":71},
  {"id":"s_work_han_thu_105_72","chapterId":"ch_work_han_thu_105","textTraditional":"〔六〕　孟康曰：「萩任方章者千枚也。」師古曰：「大材曰章，解在百官公卿表。萩即楸樹字也。其下並同也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_105_73","chapterId":"ch_work_han_thu_105","textTraditional":"〔七〕　師古曰：「滎亦水名，濟水所溢作也，即今所謂滎澤也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_105_74","chapterId":"ch_work_han_thu_105","textTraditional":"〔八〕　師古曰：「陳，陳縣也，夏，夏縣也，皆屬淮陽。種桼樹而取其汁。夏音嘏。」","sentenceOrder":74},
  {"id":"s_work_han_thu_105_75","chapterId":"ch_work_han_thu_105","textTraditional":"〔九〕　孟康曰：「一鐘受六斛四斗。」師古曰：「一畝收鐘者凡千畝也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_105_76","chapterId":"ch_work_han_thu_105","textTraditional":"〔一０〕（師古）〔孟康〕曰：「茜草、卮子可用染也。」師古曰：「茜音千見反。」","sentenceOrder":76},
  {"id":"s_work_han_thu_105_77","chapterId":"ch_work_han_thu_105","textTraditional":"〔一一〕師古曰：「畦音攜。」","sentenceOrder":77},
  {"id":"s_work_han_thu_105_78","chapterId":"ch_work_han_thu_105","textTraditional":"諺曰：「以貧求富，農不如工，工不如商，刺繡文不如倚市門。」此言末業，貧者之資也。〔一〕通邑大都酤一歲千釀，〔二〕醯醬千瓨，〔三〕漿千儋，〔四〕屠牛羊彘千皮，穀糴千鐘，〔五〕薪槁千車，船長千丈，〔六〕木千章，竹竿萬个，〔七〕軺車百乘，〔八〕牛車千兩；〔九〕木器桼者千枚，銅器千鈞，〔一０〕素木鐵器若卮茜千石，〔一一〕馬蹄噭千，〔一二〕牛千足，羊彘千雙，〔一三〕童手指千，〔一四〕筋角丹沙千斤，其帛絮細布千鈞，文采千匹，〔一五〕荅布皮革千石，〔一六〕桼千大斗，〔一七〕糱麴鹽豉千合，〔一八〕鮐鮆千斤，〔一九〕鮿鮑千鈞，〔二０〕棗栗千石者三之，〔二一〕狐貂裘千皮，羔羊裘千石，〔二二〕旃席千具，它果采千種，〔二三〕子貸金錢千貫，節駔儈，〔二四〕貪賈三之，廉賈五之，〔二五〕亦比千乘之家，此其大率也。","sentenceOrder":78},
  {"id":"s_work_han_thu_105_79","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「言其易以得利也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_105_80","chapterId":"ch_work_han_thu_105","textTraditional":"〔二〕　師古曰：「千瓮以釀酒。」","sentenceOrder":80},
  {"id":"s_work_han_thu_105_81","chapterId":"ch_work_han_thu_105","textTraditional":"〔三〕　師古曰：「瓨，長頸甖也，受十升。瓨音胡雙反。」","sentenceOrder":81},
  {"id":"s_work_han_thu_105_82","chapterId":"ch_work_han_thu_105","textTraditional":"〔四〕　孟康曰：「儋，甖也。」師古曰：「儋，人儋之也，一儋兩甖。儋音丁濫反。」","sentenceOrder":82},
  {"id":"s_work_han_thu_105_83","chapterId":"ch_work_han_thu_105","textTraditional":"〔五〕　師古曰：「謂常糴取而居之。」","sentenceOrder":83},
  {"id":"s_work_han_thu_105_84","chapterId":"ch_work_han_thu_105","textTraditional":"〔六〕　師古曰：「總積船之丈數也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_105_85","chapterId":"ch_work_han_thu_105","textTraditional":"〔七〕　孟康曰：「个者，一个兩个。」師古曰：「个讀曰箇。箇，枚也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_105_86","chapterId":"ch_work_han_thu_105","textTraditional":"〔八〕　師古曰：「軺車，輕小之車也。軺音弋昭反。」","sentenceOrder":86},
  {"id":"s_work_han_thu_105_87","chapterId":"ch_work_han_thu_105","textTraditional":"〔九〕　師古曰：「車一乘曰一兩。謂之兩者，言其轅輪兩兩而耦。」","sentenceOrder":87},
  {"id":"s_work_han_thu_105_88","chapterId":"ch_work_han_thu_105","textTraditional":"〔一０〕孟康曰：「三十斤為一鈞。」","sentenceOrder":88},
  {"id":"s_work_han_thu_105_89","chapterId":"ch_work_han_thu_105","textTraditional":"〔一一〕孟康曰：「百二十斤為石。素木，素器也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_105_90","chapterId":"ch_work_han_thu_105","textTraditional":"〔一二〕師古曰：「噭，口也。蹄與口共千，則為馬二百也。噭音江釣反，又音口釣反。」","sentenceOrder":90},
  {"id":"s_work_han_thu_105_91","chapterId":"ch_work_han_thu_105","textTraditional":"〔一三〕師古曰：「彘即豕。」","sentenceOrder":91},
  {"id":"s_work_han_thu_105_92","chapterId":"ch_work_han_thu_105","textTraditional":"〔一四〕孟康曰：「童，奴婢也。古者無空手游口，皆有作務，作務須手指，故曰手指，以別馬牛蹄角也。」師古曰：「手指謂有巧伎者。指千則人百。」","sentenceOrder":92},
  {"id":"s_work_han_thu_105_93","chapterId":"ch_work_han_thu_105","textTraditional":"〔一五〕師古曰：「文，文繒也。帛之有色者曰采。」","sentenceOrder":93},
  {"id":"s_work_han_thu_105_94","chapterId":"ch_work_han_thu_105","textTraditional":"〔一六〕孟康曰：「荅布，白疊也。」師古曰：「麤厚之布也，其價賤，故與皮革同其量耳，非白疊也。荅者，厚重之貌，而讀者妄為榻音，非也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_105_95","chapterId":"ch_work_han_thu_105","textTraditional":"〔一七〕師古曰：「大斗者，異於量米粟之斗也。今俗猶有大量。」","sentenceOrder":95},
  {"id":"s_work_han_thu_105_96","chapterId":"ch_work_han_thu_105","textTraditional":"〔一八〕師古曰：「麴糱以斤石稱之，輕重齊則為合。鹽豉則斗斛量之，多少等亦為合。合者，相配偶之言耳。今西楚荊沔之俗賣鹽豉者，鹽豉各一升則各為裹而相隨焉，此則合也。說者不曉，乃讀為升合之合，又改作台，競為解說，失之遠矣。」","sentenceOrder":96},
  {"id":"s_work_han_thu_105_97","chapterId":"ch_work_han_thu_105","textTraditional":"〔一九〕師古曰：「鮐，海魚也。鮆，刀魚也，飲而不食者。鮐音胎，又音菭。鮆音薺，又音才爾反。而說者妄讀鮐為夷，非唯失於訓物，亦不知音矣。」","sentenceOrder":97},
  {"id":"s_work_han_thu_105_98","chapterId":"ch_work_han_thu_105","textTraditional":"〔二０〕師古曰：「鮿，膊魚也，即今不著鹽而乾者也。鮑，今之〈魚邑〉魚也。鮿魚輒。膊音普各反。〈魚邑〉音於業反。而說者乃讀鮑為鮠魚之鮠，音五回反，失義遠矣。鄭康成以為〈魚邑〉於煏室乾之，亦非也。煏室乾之，即鮿耳。蓋今巴荊人所呼鰎魚者是也。音居偃反。秦始皇載鮑亂臭，則是〈魚邑〉魚耳。而煏室乾者，本不臭也。煏音蒲北反。」","sentenceOrder":98},
  {"id":"s_work_han_thu_105_99","chapterId":"ch_work_han_thu_105","textTraditional":"〔二一〕師古曰：「三千石。」","sentenceOrder":99},
  {"id":"s_work_han_thu_105_100","chapterId":"ch_work_han_thu_105","textTraditional":"〔二二〕師古曰：「狐貂貴，故計其數；羔羊賤，故稱其量也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_105_101","chapterId":"ch_work_han_thu_105","textTraditional":"〔二三〕師古曰：「果采，謂於山野采取（栗）〔果〕實也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_105_102","chapterId":"ch_work_han_thu_105","textTraditional":"〔二四〕孟康曰：「節，節物貴賤也。謂除估儈，其餘利比於千乘之家也。」師古曰：「儈者，合會二家交易者也。駔者，其首率也。駔音子朗反。儈音工外反。」","sentenceOrder":102},
  {"id":"s_work_han_thu_105_103","chapterId":"ch_work_han_thu_105","textTraditional":"〔二五〕孟康曰：「貪賈，未當賣而賣，未當買而買，故得利少，而十得其三。廉賈，貴乃賣，賤乃買，故十得五也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_105_104","chapterId":"ch_work_han_thu_105","textTraditional":"蜀卓氏之先，趙人也，用鐵冶富。秦破趙，遷卓氏之蜀，夫妻推輦行。〔一〕諸遷虜少有餘財，爭與吏，求近處，處葭萌。〔二〕唯卓氏曰：「此地陿薄。吾聞崏山之下沃野，下有踆鴟，至死不飢〔三〕。民工作（市）〔布〕，易賈。」乃求遠遷。致之臨邛，大憙，即鐵山鼓鑄，〔四〕運籌算，賈滇、蜀民，〔五〕富至童八百人，田池射獵之樂擬於人君。","sentenceOrder":104},
  {"id":"s_work_han_thu_105_105","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「步車曰輦。」","sentenceOrder":105},
  {"id":"s_work_han_thu_105_106","chapterId":"ch_work_han_thu_105","textTraditional":"〔二〕　師古曰：「縣名也，地理志屬廣漢。葭音家。」","sentenceOrder":106},
  {"id":"s_work_han_thu_105_107","chapterId":"ch_work_han_thu_105","textTraditional":"〔三〕　孟康曰：「踆音蹲。水鄉多鴟，其山下有沃野灌溉。」師古曰：「孟說非也。踆鴟謂芋也，其根可食，以充糧，故無飢年。華陽國志曰汶山郡都安縣有大芋如蹲鴟也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_105_108","chapterId":"ch_work_han_thu_105","textTraditional":"〔四〕　師古曰：「即，就也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_105_109","chapterId":"ch_work_han_thu_105","textTraditional":"〔五〕　師古曰：「行販賣於滇、蜀之間也。滇音丁賢反。」","sentenceOrder":109},
  {"id":"s_work_han_thu_105_110","chapterId":"ch_work_han_thu_105","textTraditional":"程鄭，山東遷虜也，亦冶鑄，賈魋結民，富埒卓氏。〔一〕","sentenceOrder":110},
  {"id":"s_work_han_thu_105_111","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「魋結，西南夷也。言程鄭行賈，求利於其人也。埒，等也。魋音直追反。結讀曰髻。」","sentenceOrder":111},
  {"id":"s_work_han_thu_105_112","chapterId":"ch_work_han_thu_105","textTraditional":"程、卓既衰，至成、哀間，成都羅裒訾至鉅萬。初，裒賈京師，隨身數十百萬，〔一〕為平陵石氏持錢。其人彊力。石氏訾次如、苴，〔二〕親信，厚資遣之，令往來巴蜀，數年間致千餘萬。裒舉其半賂遺曲陽、定陵侯，〔三〕依其權力，賒貸郡國，人莫敢負。〔四〕擅鹽井之利，期年所得自倍，〔五〕遂殖其貨。","sentenceOrder":112},
  {"id":"s_work_han_thu_105_113","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「言其自有數十萬，且至百萬。」","sentenceOrder":113},
  {"id":"s_work_han_thu_105_114","chapterId":"ch_work_han_thu_105","textTraditional":"〔二〕　孟康曰：「平陵如氏，苴氏也。石氏勤力，故訾次二人也。」師古曰：「孟說非也。其人彊力，謂羅裒耳。訾次如、苴，自謂石氏之饒財也。苴音側于反。」","sentenceOrder":114},
  {"id":"s_work_han_thu_105_115","chapterId":"ch_work_han_thu_105","textTraditional":"〔三〕　師古曰：「謂王根、淳于長也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_105_116","chapterId":"ch_work_han_thu_105","textTraditional":"〔四〕　師古曰：「貸音吐戴反。」","sentenceOrder":116},
  {"id":"s_work_han_thu_105_117","chapterId":"ch_work_han_thu_105","textTraditional":"〔五〕　師古曰：「期音基。」","sentenceOrder":117},
  {"id":"s_work_han_thu_105_118","chapterId":"ch_work_han_thu_105","textTraditional":"宛孔氏之先，梁人也，用鐵冶為業。秦滅魏，遷孔氏南陽，大鼓鑄，規陂田，連騎游諸侯，因通商賈之利，有游閒公子之名。〔一〕然其贏得過當，瘉於孅嗇，〔二〕家致數千金，故南陽行賈盡法孔氏之雍容。","sentenceOrder":118},
  {"id":"s_work_han_thu_105_119","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「閒讀曰閑，言其志寬大，不在急促。公子者，公侯貴人之子也，言其舉動性行有似之也，若今言諸郎矣。」","sentenceOrder":119},
  {"id":"s_work_han_thu_105_120","chapterId":"ch_work_han_thu_105","textTraditional":"〔二〕　師古曰：「瘉讀為愈。愈，勝也。孅，細也。嗇，愛〈恡，去“忄”〉也。言其於利雖不汲汲苟得，然所獲贏餘多於細〈恡，去“忄”〉者也。孅與纖同。下云周人既孅，義亦類此。」","sentenceOrder":120},
  {"id":"s_work_han_thu_105_121","chapterId":"ch_work_han_thu_105","textTraditional":"魯人俗儉嗇，而丙氏尤甚，以鐵冶起，富至鉅萬。然家自父兄子弟約，頫有拾，卬有取，〔一〕貰貸行賈遍郡國。鄒、魯以其故，多去文學而趨利。","sentenceOrder":121},
  {"id":"s_work_han_thu_105_122","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「頫，古俯字也。俯仰必有所取拾，無鉅細好惡也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_105_123","chapterId":"ch_work_han_thu_105","textTraditional":"齊俗賤奴虜，而刀閒獨愛貴之。〔一〕桀黠奴，人之所患，唯刀閒收取，使之逐魚鹽商賈之利，或連車騎交守相，然愈益任之，終得其力，起數千萬。故曰「寧爵無刀」，〔二〕言能使豪奴自饒，而盡其力也。刀閒既衰，至成、哀間，臨淄姓偉訾五千萬。〔三〕","sentenceOrder":123},
  {"id":"s_work_han_thu_105_124","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「刀姓，閒名也。刀音貂。」","sentenceOrder":124},
  {"id":"s_work_han_thu_105_125","chapterId":"ch_work_han_thu_105","textTraditional":"〔二〕　孟康曰：「刀閒能畜豪奴，奴或有連車騎交守相。如自謂：『寧欲免去作民有爵邪？無將止為刀氏作奴乎？』無，發聲助也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_105_126","chapterId":"ch_work_han_thu_105","textTraditional":"〔三〕　師古曰：「姓姓，名偉。」","sentenceOrder":126},
  {"id":"s_work_han_thu_105_127","chapterId":"ch_work_han_thu_105","textTraditional":"周人既孅，而師史尤甚，轉轂百數，〔一〕賈郡國，無所不至。雒陽街居在齊秦楚趙之中，富家相矜以久賈，〔二〕過邑不入門。設用此等，故師史能致十千萬。〔三〕","sentenceOrder":127},
  {"id":"s_work_han_thu_105_128","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「轉轂，謂以車載物而逐利者。」","sentenceOrder":128},
  {"id":"s_work_han_thu_105_129","chapterId":"ch_work_han_thu_105","textTraditional":"〔二〕　孟康曰：「謂街巷居民無田地，皆相矜久賈在此諸國也。」師古曰：「此說非也。言雒陽之地居在諸國之中，要衝之所，若大街衢，故其賈人無所不至而多得利，不憚久行也。中音竹仲反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_105_130","chapterId":"ch_work_han_thu_105","textTraditional":"〔三〕　師古曰：「十千萬，即萬萬也。言其財至萬萬也。一曰至千萬者十焉。」","sentenceOrder":130},
  {"id":"s_work_han_thu_105_131","chapterId":"ch_work_han_thu_105","textTraditional":"師史既衰，至成、哀、王莽時，雒陽張長叔、薛子仲訾亦十千萬。莽皆以為納言士，欲法武帝，然不能得其利。〔一〕","sentenceOrder":131},
  {"id":"s_work_han_thu_105_132","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「法武帝者，言用卜式、東郭、咸陽、孔僅等為官也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_105_133","chapterId":"ch_work_han_thu_105","textTraditional":"宣曲任氏，其先為督道倉吏。〔一〕秦之敗也，豪桀爭取金玉，任氏獨窖倉粟。〔二〕楚漢相距滎陽，民不得耕種，米石至萬，而豪桀金玉盡歸任氏，任氏以此起富。富人奢侈，而任氏折節為力田畜。人爭取賤賈，任氏獨取貴善，〔三〕富者數世。〔四〕然任公家約，非田畜所生不衣食，公事不畢則不得飲酒食肉。〔五〕以此為閭里率，故富而主上重之。","sentenceOrder":133},
  {"id":"s_work_han_thu_105_134","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　孟康曰：「若今（史）〔吏〕督租穀使上道輸在所也。」師古曰：「於京師四方諸道督其租耳。道者，非謂上道也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_105_135","chapterId":"ch_work_han_thu_105","textTraditional":"〔二〕　師古曰：「取倉粟而窖臧之也。窖音工孝反。」","sentenceOrder":135},
  {"id":"s_work_han_thu_105_136","chapterId":"ch_work_han_thu_105","textTraditional":"〔三〕　師古曰：「言其居買之物，不計貴賤，唯在良美也。賈讀曰價。」","sentenceOrder":136},
  {"id":"s_work_han_thu_105_137","chapterId":"ch_work_han_thu_105","textTraditional":"〔四〕　師古曰：「折節力田，務於本業，先公後私，率道閭里，故云善富。」","sentenceOrder":137},
  {"id":"s_work_han_thu_105_138","chapterId":"ch_work_han_thu_105","textTraditional":"〔五〕　師古曰：「任公，任氏之父也。言家為此私約制也。晉灼以為任用公家之約，此說非也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_105_139","chapterId":"ch_work_han_thu_105","textTraditional":"塞之斥也，唯橋桃以致馬千匹，牛倍之，羊萬，粟以萬鍾計〔一〕。","sentenceOrder":139},
  {"id":"s_work_han_thu_105_140","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　孟康曰：「邊塞主斥候卒也。唯此一人能致富若此。」師古曰：「此說非也。塞斥者，言國家斥開邊塞，更令寬廣，故橋桃得恣其畜牧也。姓橋名桃。以萬鍾計者，不論斗斛千萬之數，每率舉萬鍾而計之者，其饒多也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_105_141","chapterId":"ch_work_han_thu_105","textTraditional":"吳楚兵之起，長安中列侯封君行從軍旅，齎貣子錢家，〔一〕子錢家以為關東成敗未決，莫肯予。唯（母）〔毋〕鹽氏出捐千金貸，〔二〕其息十之。三月，吳楚平。一歲之中，則（母）〔毋〕鹽氏息十倍，用此富關中。","sentenceOrder":141},
  {"id":"s_work_han_thu_105_142","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「行者須齎糧而出，於子錢家貣出也。貣謂求假之也，音吐得反。」","sentenceOrder":142},
  {"id":"s_work_han_thu_105_143","chapterId":"ch_work_han_thu_105","textTraditional":"〔二〕　師古曰：「貸謂假與之，音吐載反。」","sentenceOrder":143},
  {"id":"s_work_han_thu_105_144","chapterId":"ch_work_han_thu_105","textTraditional":"關中富商大賈，大氐盡諸田，〔一〕田牆、田蘭。韋家栗氏、安陵杜氏亦鉅萬。前富者既衰，自元、成訖王莽，京師富人杜陵樊嘉，茂陵摯網，平陵如氏、苴氏，長安丹王君房，豉樊少翁、王孫大卿，為天下高訾。〔二〕樊嘉五千萬，其餘皆鉅萬矣。王孫卿以財養士，與雄桀交，王莽以為京司市師，漢司東市令也。","sentenceOrder":144},
  {"id":"s_work_han_thu_105_145","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「氏讀曰抵。抵，歸也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_105_146","chapterId":"ch_work_han_thu_105","textTraditional":"〔二〕　師古曰：「王君房賣丹，樊少翁及王孫大卿賣豉，亦致高訾。訾讀與資同。高訾謂多資財。」","sentenceOrder":146},
  {"id":"s_work_han_thu_105_147","chapterId":"ch_work_han_thu_105","textTraditional":"此其章章尤著者也。其餘郡國富民兼業顓利，〔一〕以貨賂自行，取重於鄉里者，不可勝數。故秦楊以田農而甲一州，〔二〕翁伯以販脂而傾縣邑，張氏以賣醬而隃侈，質氏以洒削而鼎食，〔三〕濁氏以（冒）〔胃〕脯而連騎，〔四〕張里以馬醫而擊鍾，皆越法矣。然常循守事業，積累贏利，漸有所起。至於蜀卓，宛孔，齊之刀閒，公擅山川銅鐵魚鹽市井之入，運其籌策，上爭王者之利，下錮齊民之業，〔五〕皆陷不軌奢僭之惡。又況掘冢搏掩，犯姦成富，〔六〕曲叔、稽發、雍樂成之徒，〔七〕猶復齒列，〔八〕傷化敗俗，大亂之道也。","sentenceOrder":147},
  {"id":"s_work_han_thu_105_148","chapterId":"ch_work_han_thu_105","textTraditional":"〔一〕　師古曰：「顓與專同。」","sentenceOrder":148},
  {"id":"s_work_han_thu_105_149","chapterId":"ch_work_han_thu_105","textTraditional":"〔二〕　孟康曰：「以田地過限，從此而富，為州中第一也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_105_150","chapterId":"ch_work_han_thu_105","textTraditional":"〔三〕　服虔曰：「治刀劍者也。」如淳曰：「作刀劍削者。」師古曰：「二說皆非也。洒，濯也。削謂刀劍室也。謂人有刀劍削故惡者，主為洒刷之，去其垢穢，更飾令新也。洒音先禮反。削音先召反。」","sentenceOrder":150},
  {"id":"s_work_han_thu_105_151","chapterId":"ch_work_han_thu_105","textTraditional":"〔四〕　晉灼曰：「今太官常以十月作沸湯燖羊胃，以末椒薑坋之，暴使燥是也。」師古曰：「燖音似兼反。坋音蒲頓反。」","sentenceOrder":151},
  {"id":"s_work_han_thu_105_152","chapterId":"ch_work_han_thu_105","textTraditional":"〔五〕　師古曰：「錮亦謂專取之也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_105_153","chapterId":"ch_work_han_thu_105","textTraditional":"〔六〕　師古曰：「搏掩謂搏擊掩襲，取人物者也。搏字或作博。一說搏，六博也，掩，意錢之屬也，皆戲而賭取財物。」","sentenceOrder":153},
  {"id":"s_work_han_thu_105_154","chapterId":"ch_work_han_thu_105","textTraditional":"〔七〕　師古曰：「姓曲名叔，姓稽名發，姓雍名樂成也。稽音工奚反。」","sentenceOrder":154},
  {"id":"s_work_han_thu_105_155","chapterId":"ch_work_han_thu_105","textTraditional":"〔八〕　師古曰：「身為罪惡，尚復與良善之人齊齒並列。」","sentenceOrder":155},
  {"id":"s_work_han_thu_105_156","chapterId":"ch_work_han_thu_105","textTraditional":"校勘記","sentenceOrder":156},
  {"id":"s_work_han_thu_105_157","chapterId":"ch_work_han_thu_105","textTraditional":"三六八七頁　七行　（師古）〔孟康〕曰：景祐、殿、局本都作「孟康」。","sentenceOrder":157},
  {"id":"s_work_han_thu_105_158","chapterId":"ch_work_han_thu_105","textTraditional":"三六八九頁一三行　謂於山野采取（栗）〔果〕實也。　景祐、殿本都作「果」。王先謙說作「果」是。三六九０行　三行　民工作（市）〔布〕，　景祐、汲古、殿、局本都作「布」。","sentenceOrder":158},
  {"id":"s_work_han_thu_105_159","chapterId":"ch_work_han_thu_105","textTraditional":"三六九三頁　二行　人爭取賤賈，任氏獨取貴善，〔三〕富者數世。〔四〕　注〔三〕原在「貴」字下，明顏讀善字屬下。王念孫說，此當以「任氏獨取貴善」為句，「富者數世」為句。王先謙說王讀是。","sentenceOrder":159},
  {"id":"s_work_han_thu_105_160","chapterId":"ch_work_han_thu_105","textTraditional":"三六九三頁　四行　若今（史）〔吏〕督租穀使上道輸在所也。　景祐、殿本都作「吏」。","sentenceOrder":160},
  {"id":"s_work_han_thu_105_161","chapterId":"ch_work_han_thu_105","textTraditional":"三六九三頁一三行　唯（母）〔毋〕鹽氏出捐千斤貸，　殿本作「毋」，下同。按史記作「無」。","sentenceOrder":161},
  {"id":"s_work_han_thu_105_162","chapterId":"ch_work_han_thu_105","textTraditional":"三六九四頁　九行　濁氏以（冒）〔胃〕脯而連騎，　景祐、殿本都作「胃」，此誤。","sentenceOrder":162},
  {"id":"s_work_han_thu_106_1","chapterId":"ch_work_han_thu_106","textTraditional":"古者天子建國，諸侯立家，自卿大夫以至于庶人各有等差，是以民服事其上，而下無覬覦。〔一〕孔子曰：「天下有道，政不在大夫。」〔二〕百官有司奉法承令，以脩所職，失職有誅，侵官有罰。夫然，故上下相順，而庶事理焉。","sentenceOrder":1},
  {"id":"s_work_han_thu_106_2","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「覬，幸也。覦，欲也。幸得其所欲也。覬音冀。覦音踰，又音諭。」","sentenceOrder":2},
  {"id":"s_work_han_thu_106_3","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「論語載孔子之言也，謂權不移於下也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_106_4","chapterId":"ch_work_han_thu_106","textTraditional":"周室既微，禮樂征伐自諸侯出。桓文之後，大夫世權，陪臣執命。〔一〕陵夷至於戰國，合從連衡，力政爭彊。〔二〕繇是列國公子，魏有信陵，趙有平原，齊有孟嘗，楚有春申，〔三〕皆藉王公之勢，競為游俠，雞鳴狗盜，無不賓禮。〔四〕而趙相虞卿棄國捐君，以周窮交魏齊之厄；〔五〕信陵無忌竊符矯命，戮將專師，以赴平原之急：〔六〕皆以取重諸侯，顯名天下。搤腕而游談者，以四豪為稱首。〔七〕於是背公死黨之議成，守戰奉上之義廢矣。","sentenceOrder":4},
  {"id":"s_work_han_thu_106_5","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「齊桓、晉文，周之二霸也。陪，重也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_106_6","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「力政者，棄背禮義專任威力也。從音子容反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_106_7","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「繇讀與由同。信陵君魏無忌，平原君趙勝，孟嘗君田文，春申君黃歇。」","sentenceOrder":7},
  {"id":"s_work_han_thu_106_8","chapterId":"ch_work_han_thu_106","textTraditional":"〔四〕　師古曰：「謂孟嘗君用雞鳴而得亡出關，因狗盜而取狐白裘也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_106_9","chapterId":"ch_work_han_thu_106","textTraditional":"〔五〕　師古曰：「魏齊，虞卿之交也，將為范雎所殺，卿救之也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_106_10","chapterId":"ch_work_han_thu_106","textTraditional":"〔六〕　師古曰：「秦兵圍趙，趙相平原君告急於無忌，無忌因如姬以竊兵符，矯魏僖侯命代晉鄙為將，而令朱亥鎚殺晉鄙，遂率兵救趙，秦兵以卻，而趙得全。」","sentenceOrder":10},
  {"id":"s_work_han_thu_106_11","chapterId":"ch_work_han_thu_106","textTraditional":"〔七〕　師古曰：「搤，捉持也。掔，古手腕字也。四豪即魏信陵以下也。搤音厄。」","sentenceOrder":11},
  {"id":"s_work_han_thu_106_12","chapterId":"ch_work_han_thu_106","textTraditional":"及至漢興，禁網疏闊，未之匡改也。〔一〕是故代相陳豨從車千乘，而吳濞、淮南皆招賓客以千數。外戚大臣魏其、武安之屬競逐於京師，布衣游俠劇孟、郭解之徒馳騖於閭閻，權行州域，力折公侯。眾庶榮其名跡，覬而慕之。雖其陷於刑辟，自與殺身成名，若季路、仇牧，死而不悔也。〔二〕故曾子曰：「上失其道，民散久矣。〔三〕」非明王在上，視之以好惡，齊之以禮法，民曷繇知禁而反正乎！〔四〕","sentenceOrder":12},
  {"id":"s_work_han_thu_106_13","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「匡，正也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_106_14","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「季路，孔子弟子也，姓仲名由，衛人也。衛有蒯瞶之亂，季路聞之，故入赴難，遇孟黶石乞以戈擊之，斷纓。季路曰：『君子死，冠不免。』結纓而死。仇牧，宋大夫也。宋萬殺閔公，仇牧聞之，趨而至，手劍而叱之。萬臂擊仇牧，碎首，齒著于門闔。言游俠之徒自許節操，同於季路、仇牧。」","sentenceOrder":14},
  {"id":"s_work_han_thu_106_15","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「論語載（孔）〔曾〕子之言也，解在刑法志。」","sentenceOrder":15},
  {"id":"s_work_han_thu_106_16","chapterId":"ch_work_han_thu_106","textTraditional":"〔四〕　師古曰：「視讀曰示。繇讀曰由。」","sentenceOrder":16},
  {"id":"s_work_han_thu_106_17","chapterId":"ch_work_han_thu_106","textTraditional":"古之正法：五伯，三王之罪人也；〔一〕而六國，五伯之罪人也。夫四豪者，又六國之罪人也。況於郭解之倫，以匹夫之細，竊殺生之權，其罪已不容於誅矣。觀其溫良泛愛，振窮周急，謙退不伐，亦皆有絕異之姿。惜乎不入於道德，苟放縱於末流，殺身亡宗，非不幸也！","sentenceOrder":17},
  {"id":"s_work_han_thu_106_18","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「伯讀曰霸。下皆類此。」","sentenceOrder":18},
  {"id":"s_work_han_thu_106_19","chapterId":"ch_work_han_thu_106","textTraditional":"自魏其、武安、淮南之後，天子切齒，衛、霍改節。然郡國豪桀處處各有，京師親戚冠蓋相望，亦古今常道，莫足言者。唯成帝時，外家王氏賓客為盛，而樓護為帥。及王莽時，諸公之間陳遵為雄，閭里之俠原涉為魁。〔一〕","sentenceOrder":19},
  {"id":"s_work_han_thu_106_20","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「魁者，斗之所用盛而杓之本也。故言根本者皆云魁。」","sentenceOrder":20},
  {"id":"s_work_han_thu_106_21","chapterId":"ch_work_han_thu_106","textTraditional":"朱家，魯人，高祖同時也。魯人皆以儒教，而朱家用俠聞。所臧活豪士以百數，其餘庸人不可勝言。然終不伐其能，飲其德，〔一〕諸所嘗施，唯恐見之。振人不贍，先從貧賤始。家亡餘財，衣不兼采，食不重味，乘不過軥牛。〔二〕專趨人之急，甚於己私。〔三〕既陰脫季布之厄，及布尊貴，終身不見。自關以東，莫不延頸願交。楚田仲以俠聞，父事朱家，自以為行弗及也。田仲死後，有劇孟。","sentenceOrder":21},
  {"id":"s_work_han_thu_106_22","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　孟康曰：「有德於人，而不自美也。」師古曰：「飲，沒也，謂不稱顯。」","sentenceOrder":22},
  {"id":"s_work_han_thu_106_23","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　晉灼曰：「軥，軥枙也。軥牛，小牛也。」師古曰：「軥，重挽也，音工豆反。晉說是也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_106_24","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「趨讀曰趣。趣，向也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_106_25","chapterId":"ch_work_han_thu_106","textTraditional":"劇孟者，洛陽人也。周人以商賈為資，劇孟以俠顯。吳楚反時，條侯為太尉，乘傳東，〔一〕將至河南，得劇孟，喜曰：「吳楚舉大事而不求劇孟，吾知其無能為已。」〔二〕天下騷動，大將軍得之若一敵國云。劇孟行大類朱家，而好博，多少年之戲。然孟母死，自遠方送喪蓋千乘。及孟死，家無十金之財。而符離王孟，亦以俠稱江淮之間。〔三〕是時，濟南瞷氏、陳周膚亦以豪聞。〔四〕景帝聞之，使使盡誅此屬。其後，代諸白、梁韓毋辟、陽翟薛況、陝寒孺，紛紛復出焉。〔五〕","sentenceOrder":25},
  {"id":"s_work_han_thu_106_26","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「乘傳車而東，出為大將也。傳音張戀反。」","sentenceOrder":26},
  {"id":"s_work_han_thu_106_27","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「已，語終辭。」","sentenceOrder":27},
  {"id":"s_work_han_thu_106_28","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「符離，沛郡之縣也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_106_29","chapterId":"ch_work_han_thu_106","textTraditional":"〔四〕　師古曰：「瞷音閑。」","sentenceOrder":29},
  {"id":"s_work_han_thu_106_30","chapterId":"ch_work_han_thu_106","textTraditional":"〔五〕　師古曰：「代郡白姓非一家也，故稱諸焉。梁國人姓韓，名毋辟。陽翟屬潁川。陝即今陝州陝縣也。薛況、寒孺，皆人姓名也。辟讀曰避。」","sentenceOrder":30},
  {"id":"s_work_han_thu_106_31","chapterId":"ch_work_han_thu_106","textTraditional":"郭解，河內軹人也，〔一〕溫善相人許負外孫也。解父任俠，孝文時誅死。解為人靜悍，〔二〕不飲酒。少時陰賊感概，〔三〕不快意，所殺甚眾。以軀耤友報仇，〔四〕臧命作姦剽攻，〔五〕休乃鑄錢掘冢，〔六〕不可勝數。適有天幸，窘急常得脫，若遇赦。","sentenceOrder":31},
  {"id":"s_work_han_thu_106_32","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「軹音只。」","sentenceOrder":32},
  {"id":"s_work_han_thu_106_33","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「性沉靜而勇悍。」","sentenceOrder":33},
  {"id":"s_work_han_thu_106_34","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「陰賊者，陰懷賊害之意也。感概者，感意氣而立節概也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_106_35","chapterId":"ch_work_han_thu_106","textTraditional":"〔四〕　師古曰：「耤，古藉字。藉謂借助也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_106_36","chapterId":"ch_work_han_thu_106","textTraditional":"〔五〕　師古曰：「臧命，臧亡命之人也。剽，劫也。攻謂穿窬而盜也。剽音匹妙反。」","sentenceOrder":36},
  {"id":"s_work_han_thu_106_37","chapterId":"ch_work_han_thu_106","textTraditional":"〔六〕　師古曰：「不報仇剽攻，則鑄錢發冢也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_106_38","chapterId":"ch_work_han_thu_106","textTraditional":"及解年長，更折節為儉，以德報怨，厚施而薄望。然其自喜為俠益甚。〔一〕既已振人之命，不矜其功，〔二〕其陰賊著於心本發於睚眥如故云。〔三〕而少年慕其行，亦輒為報讎，不使知也。","sentenceOrder":38},
  {"id":"s_work_han_thu_106_39","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「自好喜為此名也。喜音許吏反。」","sentenceOrder":39},
  {"id":"s_work_han_thu_106_40","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「振謂舉救也。矜，夸恃也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_106_41","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「著音直略反。心本猶言本心也。睚音崖。眥音漬。睚眥又音五懈、士懈反，解具在杜欽傳。」","sentenceOrder":41},
  {"id":"s_work_han_thu_106_42","chapterId":"ch_work_han_thu_106","textTraditional":"解姊子負解之勢，〔一〕與人飲，使之釂，非其任，彊灌之〔二〕。人怒，刺殺解姊子，（去亡）〔亡去〕。解姊怒曰：「以翁伯時人殺吾子，賊不得！」〔三〕棄其尸道旁，弗葬，欲以辱解。解使人微知賊處。〔四〕賊窘自歸，〔五〕具以實告解。解曰：「公殺之當，吾兒不直。」遂去其賊，〔六〕罪其姊子，收而葬之。諸公聞之，皆多解之義，〔七〕益附焉。","sentenceOrder":42},
  {"id":"s_work_han_thu_106_43","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「負，恃也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_106_44","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「盡爵曰釂。其人不飲，而使盡爵，乃彊灌之，故怨怒也。釂音子笑反。彊音其兩反。」","sentenceOrder":44},
  {"id":"s_work_han_thu_106_45","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「翁伯，解字也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_106_46","chapterId":"ch_work_han_thu_106","textTraditional":"〔四〕　師古曰：「微，伺問之也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_106_47","chapterId":"ch_work_han_thu_106","textTraditional":"〔五〕　師古曰：「窘，困急。」","sentenceOrder":47},
  {"id":"s_work_han_thu_106_48","chapterId":"ch_work_han_thu_106","textTraditional":"〔六〕　師古曰：「除去其罪也。去音丘呂反。」","sentenceOrder":48},
  {"id":"s_work_han_thu_106_49","chapterId":"ch_work_han_thu_106","textTraditional":"〔七〕　師古曰：「多猶重也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_106_50","chapterId":"ch_work_han_thu_106","textTraditional":"解出，人皆避，有一人獨箕踞視之。解問其姓名，客欲殺之。解曰：「居邑屋不見敬，是吾德不脩也，〔一〕彼何罪！」乃陰請尉史曰：「是人吾所重，至踐更時脫之。」〔二〕每至直更，數過，吏弗求。〔三〕怪之，問其故，解使脫之。箕踞者乃肉袒謝罪。少年聞之，愈益慕解之行。","sentenceOrder":50},
  {"id":"s_work_han_thu_106_51","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「邑屋猶今人言村舍、巷舍也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_106_52","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「踐更，為踐更之卒也。脫，免也。更音工衡反。脫音它活反。」","sentenceOrder":52},
  {"id":"s_work_han_thu_106_53","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「直，當也，次當為更也。數音所角反。」","sentenceOrder":53},
  {"id":"s_work_han_thu_106_54","chapterId":"ch_work_han_thu_106","textTraditional":"洛陽人有相仇者，邑中賢豪居間以十數，終不聽。〔一〕客乃見解。解夜見仇家，仇家曲聽。〔二〕解謂仇家：「吾聞洛陽諸公在間，多不聽。今子幸而聽解，解奈何從它縣奪人邑賢大夫權乎！」乃夜去，不使人知，曰：「且毋庸，待我去，令洛陽豪居間乃聽。」〔三〕","sentenceOrder":54},
  {"id":"s_work_han_thu_106_55","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「居中間為道地和輯之，而不見許也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_106_56","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「屈曲從其言。」","sentenceOrder":56},
  {"id":"s_work_han_thu_106_57","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「庸，用也。且無用休，待洛陽豪更言之乃從其言也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_106_58","chapterId":"ch_work_han_thu_106","textTraditional":"解為人短小，恭儉，出未嘗有騎，〔一〕不敢乘車入其縣庭〔二〕。之旁郡國，為人請求事，事可出，出之；〔三〕不可者，各令厭其意，〔四〕然後乃敢嘗酒食。諸公以此嚴重之，爭為用。邑中少年及旁近縣豪夜半過門，常十餘車，請得解客舍養之。〔五〕","sentenceOrder":58},
  {"id":"s_work_han_thu_106_59","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「不以騎自隨也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_106_60","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「所屬之縣也。」","sentenceOrder":60},
  {"id":"s_work_han_thu_106_61","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　如淳曰：「事可為免出者，出之。」","sentenceOrder":61},
  {"id":"s_work_han_thu_106_62","chapterId":"ch_work_han_thu_106","textTraditional":"〔四〕　師古曰：「厭，滿也，音一贍反。」","sentenceOrder":62},
  {"id":"s_work_han_thu_106_63","chapterId":"ch_work_han_thu_106","textTraditional":"〔五〕　師古曰：「舍，止也。言解多藏亡命，喜事少年與解同志者，知亡命者多歸解，故夜將車來迎取其人居止而養之。」","sentenceOrder":63},
  {"id":"s_work_han_thu_106_64","chapterId":"ch_work_han_thu_106","textTraditional":"及徙豪茂陵也，解貧，不中訾。〔一〕吏恐，不敢不徙。衛將軍為言「郭解家貧，不中徙」。上曰：「解布衣，權至使將軍，此其家不貧！」〔二〕解徙，諸公送者出千餘萬。軹人楊季主子為縣掾，鬲之，〔三〕解兄子斷楊掾頭。解入關，關中賢豪知與不知，聞聲爭交驩。〔四〕邑人又殺楊季主，季主家上書人又殺闕下。〔五〕上聞，乃下吏捕解。解亡，置其母家室夏陽，身至臨晉。臨晉籍少翁素不知解，因出關。〔六〕籍少翁已出解。解傳太原，所過輒告主人處。吏逐跡至籍少翁，少翁自殺，口絕。久之得解，窮治所犯為，而解所殺，皆在赦前。","sentenceOrder":64},
  {"id":"s_work_han_thu_106_65","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「中，充也，言訾財不充合徙之數也。中音竹仲反。其下亦同。」","sentenceOrder":65},
  {"id":"s_work_han_thu_106_66","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「將軍為之言，是為其所使也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_106_67","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「鬲塞其送，不令解得之也。鬲與隔同。」","sentenceOrder":67},
  {"id":"s_work_han_thu_106_68","chapterId":"ch_work_han_thu_106","textTraditional":"〔四〕　師古曰：「知謂先相知。」","sentenceOrder":68},
  {"id":"s_work_han_thu_106_69","chapterId":"ch_work_han_thu_106","textTraditional":"〔五〕　師古曰：「於闕下殺上書人。」","sentenceOrder":69},
  {"id":"s_work_han_thu_106_70","chapterId":"ch_work_han_thu_106","textTraditional":"〔六〕　師古曰：「出解於關也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_106_71","chapterId":"ch_work_han_thu_106","textTraditional":"軹有儒生侍使者坐，客譽郭解，生曰：「解專以姦犯公法，何謂賢？」解客聞之，殺此生，斷舌。吏以責解，解實不知殺者，殺者亦竟莫知為誰。吏奏解無罪。御史大夫公孫弘議曰：「解布衣為任俠行權，以睚眥殺人，解不知，此罪甚於解知殺之。當大逆無道。」〔一〕遂族解。","sentenceOrder":71},
  {"id":"s_work_han_thu_106_72","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「當謂處斷其罪。」","sentenceOrder":72},
  {"id":"s_work_han_thu_106_73","chapterId":"ch_work_han_thu_106","textTraditional":"自是之後，俠者極眾，而無足數者。然關中長安樊中子，槐里趙王孫，長陵高公子，西河郭翁中，〔一〕太原魯翁孺，臨淮兒長卿，〔二〕東陽陳君孺，雖為俠而恂恂有退讓君子之風。〔三〕至若北道姚氏，西道諸杜，南道仇景，東道佗羽公子，〔四〕南陽趙調之徒，盜跖而居民間者耳，曷足道哉！此乃鄉者朱家所羞也。〔五〕","sentenceOrder":73},
  {"id":"s_work_han_thu_106_74","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「中讀皆曰仲。」","sentenceOrder":74},
  {"id":"s_work_han_thu_106_75","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「兒音五奚反。」","sentenceOrder":75},
  {"id":"s_work_han_thu_106_76","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「恂恂，謹信之貌也。音荀。」","sentenceOrder":76},
  {"id":"s_work_han_thu_106_77","chapterId":"ch_work_han_thu_106","textTraditional":"〔四〕　師古曰：「據京師而言，指其東西南北謂也。姓佗，名羽，字公子。佗，古他字。」","sentenceOrder":77},
  {"id":"s_work_han_thu_106_78","chapterId":"ch_work_han_thu_106","textTraditional":"〔五〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":78},
  {"id":"s_work_han_thu_106_79","chapterId":"ch_work_han_thu_106","textTraditional":"萭章字子夏，長安人也。〔一〕長安熾盛，街閭各有豪俠，章在城西柳市，〔二〕號曰「城西萭子夏」。為京兆尹門下督，從至殿中，〔三〕侍中諸侯貴人爭欲揖章，莫與京兆尹言者。章逡循甚懼。其後京兆不復從也。〔四〕","sentenceOrder":79},
  {"id":"s_work_han_thu_106_80","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「萭音拒。」","sentenceOrder":80},
  {"id":"s_work_han_thu_106_81","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「漢宮闕疏云細柳倉有柳市。」","sentenceOrder":81},
  {"id":"s_work_han_thu_106_82","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「章從京兆也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_106_83","chapterId":"ch_work_han_thu_106","textTraditional":"〔四〕　師古曰：「更不以章自隨也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_106_84","chapterId":"ch_work_han_thu_106","textTraditional":"與中書令石顯相善，亦得顯權力，門車常接轂。至成帝初，石顯坐專權擅勢免官，徙歸故郡。顯貲巨萬，當去，留床席器物數百萬直，欲以與章，章不受。賓客或問其故，章歎曰：「吾以布衣見哀於石君，〔一〕石君家破，不能有以安也，〔二〕而受其財物，此為石氏之禍，萭氏反當以為福邪！」諸公以是服而稱之。","sentenceOrder":84},
  {"id":"s_work_han_thu_106_85","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「言為石顯所哀憐。」","sentenceOrder":85},
  {"id":"s_work_han_thu_106_86","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「言力不能救。」","sentenceOrder":86},
  {"id":"s_work_han_thu_106_87","chapterId":"ch_work_han_thu_106","textTraditional":"河平中，王尊為京兆尹，捕擊豪俠，殺章及箭張回、〔一〕酒市趙君都、賈子光，〔二〕皆長安名豪，報仇怨養刺客者也。","sentenceOrder":87},
  {"id":"s_work_han_thu_106_88","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　服虔曰：「作箭者姓張，名回。」","sentenceOrder":88},
  {"id":"s_work_han_thu_106_89","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　服虔曰：「酒市中人也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_106_90","chapterId":"ch_work_han_thu_106","textTraditional":"樓護字君卿，齊人。父世醫也，護少隨父為醫長安，出入貴戚家。護誦醫經、本草、方術數十萬言，長者咸愛重之，共謂曰：「以君卿之材，何不宦學乎？」繇是辭其父，學經傳，〔一〕為京兆吏數年，甚得名譽。","sentenceOrder":90},
  {"id":"s_work_han_thu_106_91","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「繇讀與由同。」","sentenceOrder":91},
  {"id":"s_work_han_thu_106_92","chapterId":"ch_work_han_thu_106","textTraditional":"是時王氏方盛，賓客滿門，五侯兄弟爭名，其客各有所厚，不得左右，〔一〕唯護盡入其門，咸得其驩心。結士大夫，無所不傾，其交長者，尤見親而敬，眾以是服。為人短小精辯，論議常依名節，聽之者皆竦。與谷永俱為五侯上客，長安號曰「谷子雲筆札，樓君卿脣舌」，言其見信用也。母死，送葬者致車二三千兩，閭里歌之曰：「五侯治喪樓君卿。」","sentenceOrder":92},
  {"id":"s_work_han_thu_106_93","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「不相經過也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_106_94","chapterId":"ch_work_han_thu_106","textTraditional":"久之，平阿侯舉護方正，〔一〕為諫大夫，使郡國。護假貸〔二〕，多持幣帛，過齊，上書求上先人冢，因會宗族故人，各以親疏與束帛，一日散百金之費。使還，奏事稱意，擢為天水太守。數歲免，家長安中。時成都侯商為大司馬衛將軍，罷朝，欲候護，其主簿諫：「將軍至尊，不宜入閭巷。」商不聽，遂往至護家。家狹小，官屬立車下，久住移時，天欲雨，主簿謂西曹諸掾曰：「不肯彊諫，反雨立閭巷！」商還，或白主簿語，商恨，以他職事去主簿，終身廢錮。","sentenceOrder":94},
  {"id":"s_work_han_thu_106_95","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「王譚也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_106_96","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「官以物假貸貧人，令護監之。貸音吐戴反。」","sentenceOrder":96},
  {"id":"s_work_han_thu_106_97","chapterId":"ch_work_han_thu_106","textTraditional":"後護復以薦為廣漢太守。元始中，王莽為安漢公，專政，莽長子宇與妻兄呂寬謀以血塗莽第門，欲懼莽令歸政。發覺，莽大怒，殺宇，而呂寬亡。寬父素與護相知，寬至廣漢過護，不以事實語也。到數日，名捕寬詔書至，〔一〕護執寬。莽大喜，徵護入為前煇光，〔二〕封息鄉侯，列於九卿。","sentenceOrder":97},
  {"id":"s_work_han_thu_106_98","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「舉姓名而捕之也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_106_99","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「莽分三輔置前煇光，後丞烈，以護為之。煇音暉。」","sentenceOrder":99},
  {"id":"s_work_han_thu_106_100","chapterId":"ch_work_han_thu_106","textTraditional":"莽居攝，槐里大賊趙朋、霍鴻等群起，延入前煇光界，護坐免為庶人。其居位，爵祿賂遺所得亦緣手盡。既退居里巷，時五侯皆已死，年老失勢，賓客益衰。至王莽篡位，以舊恩召見護，封為樓舊里附城。〔一〕而成都侯商子邑為大司空，貴重，商故人皆敬事邑，唯護自安如舊節，邑亦父事之，不敢有闕。時請召賓客，邑居樽下，稱「賤子上壽」。〔二〕坐者百數，皆離席伏，護獨東鄉正坐，〔三〕字謂邑曰：「公子貴如何！」〔四〕","sentenceOrder":100},
  {"id":"s_work_han_thu_106_101","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「莽為此爵名，效古之附庸也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_106_102","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「言以父禮事。」","sentenceOrder":102},
  {"id":"s_work_han_thu_106_103","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":103},
  {"id":"s_work_han_thu_106_104","chapterId":"ch_work_han_thu_106","textTraditional":"〔四〕　蘇林曰：「邑字公子也。」","sentenceOrder":104},
  {"id":"s_work_han_thu_106_105","chapterId":"ch_work_han_thu_106","textTraditional":"初，護有故人呂公，無子，歸護。護身與呂公、妻與呂嫗同食。及護家居，妻子頗厭呂公。護聞之，流涕責其妻子曰：「呂公以故舊窮老託身於我，義所當奉。」遂養呂公終身。護卒，子嗣其爵。","sentenceOrder":105},
  {"id":"s_work_han_thu_106_106","chapterId":"ch_work_han_thu_106","textTraditional":"陳遵字孟公，杜陵人也。祖父遂，字長子，宣帝微時與有故，相隨博弈，〔一〕數負進。〔二〕及宣帝即位，用遂，稍遷至太原太守，乃賜遂璽書曰：「制詔太原太守：官尊祿厚，可以償博進矣。妻君寧時在旁，知狀。」〔三〕遂於是辭謝，因曰：「事在元平元年赦令前。」其見厚如此。元帝時，徵遂為京兆尹，至廷尉。","sentenceOrder":106},
  {"id":"s_work_han_thu_106_107","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「博，六博。弈，圍碁也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_106_108","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「進者，會禮之財也，謂博所賭也，解在高紀。一說進，勝也，帝博而勝，故遂有所負。」","sentenceOrder":108},
  {"id":"s_work_han_thu_106_109","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「史皇孫名進而此詔不諱之，蓋史家追書故有其字耳。君寧，遂妻名也。云妻知負博之狀者，著舊恩之深也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_106_110","chapterId":"ch_work_han_thu_106","textTraditional":"遵少孤，與張竦伯松俱為京兆史。竦博學通達，以廉儉自守，而遵放縱不拘，操行雖異，然相親友，哀帝之末俱著名字，為後進冠。〔一〕並入公府，公府掾史率皆羸車小馬，不上鮮明，而遵獨極輿馬衣服之好，門外車騎交錯。又日出醉歸，〔二〕曹事數廢。西曹以故事適之，〔三〕侍曹輒詣寺舍白遵曰：「陳卿今日以某事適。」遵曰：「滿百乃相聞。」故事，有百適者斥，滿百，西曹白請斥。大司徒馬宮大儒優士，又重遵，〔四〕謂西曹：「此人大度士，奈何以小文責之？」乃舉遵能治三輔劇縣，補郁夷令。〔五〕久之，與扶風相失，〔六〕自免去。","sentenceOrder":110},
  {"id":"s_work_han_thu_106_111","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　如淳曰：「為後進人士之冠首也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_106_112","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「言每日必出飲也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_106_113","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「案舊法令而罰之也。適讀曰謫。此下皆同。」","sentenceOrder":113},
  {"id":"s_work_han_thu_106_114","chapterId":"ch_work_han_thu_106","textTraditional":"〔四〕　師古曰：「優禮賢士，而尤敬重遵。」","sentenceOrder":114},
  {"id":"s_work_han_thu_106_115","chapterId":"ch_work_han_thu_106","textTraditional":"〔五〕　師古曰：「右扶風之縣。」","sentenceOrder":115},
  {"id":"s_work_han_thu_106_116","chapterId":"ch_work_han_thu_106","textTraditional":"〔六〕　師古曰：「意不相得也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_106_117","chapterId":"ch_work_han_thu_106","textTraditional":"槐里大賊趙朋、霍鴻等起，遵為校尉，擊朋、鴻有功，封嘉威侯。居長安中，列侯近臣貴戚皆重貴之。牧守當之官，及郡國豪桀至京師者，莫不相因到遵門。","sentenceOrder":117},
  {"id":"s_work_han_thu_106_118","chapterId":"ch_work_han_thu_106","textTraditional":"遵耆酒，〔一〕每大飲，賓客滿堂，輒關門，取客車轄投井中，雖有急，終不得去。〔二〕嘗有部刺史奏事，過遵，值其方飲，刺史大窮，候遵霑醉時，突入見遵母，〔三〕叩頭自白當對尚書有期會狀，母乃令從（從）〔後〕閤出去。〔四〕遵大率常醉，然事亦不廢。","sentenceOrder":118},
  {"id":"s_work_han_thu_106_119","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「耆讀曰嗜。」","sentenceOrder":119},
  {"id":"s_work_han_thu_106_120","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「既關閉門，又投車轄也。而說者便欲改轄字為錧，云門之錧籥，妄穿鑿耳。錧自主人所執，何煩投井也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_106_121","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「霑溼言其大醉也。霑音竹占反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_106_122","chapterId":"ch_work_han_thu_106","textTraditional":"〔四〕　師古曰：「以其前門關閉，故從後閤出之也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_106_123","chapterId":"ch_work_han_thu_106","textTraditional":"長八尺餘，長頭大鼻，容貌甚偉。略涉傳記，贍於文辭。性善書，與人尺牘，主皆藏去以為榮。〔一〕請求不敢逆，所到，衣冠懷之，唯恐在後。〔二〕時列侯有與遵同姓字者，每至人門，曰陳孟公，坐中莫不震動，既至而非，因號其人曰陳驚坐云。","sentenceOrder":123},
  {"id":"s_work_han_thu_106_124","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「去亦藏也，音丘呂反，又音舉。」","sentenceOrder":124},
  {"id":"s_work_han_thu_106_125","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「懷，來也，謂招來而禮之。」","sentenceOrder":125},
  {"id":"s_work_han_thu_106_126","chapterId":"ch_work_han_thu_106","textTraditional":"王莽素奇遵材，在位多稱譽者，繇是起為河南太守。〔一〕既至官，當遣從史西，召善書吏十人於前，治私書謝京師故人。遵馮几，〔二〕口占書吏，且省官事，〔三〕書數百封，親疏各有意，河南大驚。數月免。","sentenceOrder":126},
  {"id":"s_work_han_thu_106_127","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「繇讀與由同。」","sentenceOrder":127},
  {"id":"s_work_han_thu_106_128","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「馮讀曰憑。」","sentenceOrder":128},
  {"id":"s_work_han_thu_106_129","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「占，隱度也。口隱其辭以授吏也。占音之贍反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_106_130","chapterId":"ch_work_han_thu_106","textTraditional":"初，遵為河南太守，而弟級為荊州牧，當之官，俱過長安富人故淮陽王外家左氏飲食作樂。後司直陳崇聞之，劾奏「遵兄弟幸得蒙恩超等歷位，遵爵列侯，備郡守，級州牧奉使，皆以舉直察枉宣揚聖化為職，不正身自慎。始遵初除，乘藩車入閭巷，〔一〕過寡婦左阿君置酒歌謳，遵起舞跳梁，頓仆坐上，暮因留宿，為侍婢扶臥。遵知飲酒飫宴有節，〔二〕禮不入寡婦之門，而湛酒溷肴，〔三〕亂男女之別，輕辱爵位，羞汙印韍，〔四〕惡不可忍聞。臣請皆免。」遵既免，歸長安，賓客愈盛，飲食自若。〔五〕","sentenceOrder":130},
  {"id":"s_work_han_thu_106_131","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「藩車，車之有屏蔽者。」","sentenceOrder":131},
  {"id":"s_work_han_thu_106_132","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「宴食曰飫。飫音於庶反。」","sentenceOrder":132},
  {"id":"s_work_han_thu_106_133","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「湛讀曰沈，又音耽。」","sentenceOrder":133},
  {"id":"s_work_han_thu_106_134","chapterId":"ch_work_han_thu_106","textTraditional":"〔四〕　師古曰：「此韍謂印之組也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_106_135","chapterId":"ch_work_han_thu_106","textTraditional":"〔五〕　師古曰：「言自如其故。」","sentenceOrder":135},
  {"id":"s_work_han_thu_106_136","chapterId":"ch_work_han_thu_106","textTraditional":"久之，復為九江及河內都尉，凡三為二千石。而張竦亦至丹陽太守，封淑德侯。後俱免官，以列侯歸長安。竦居貧，無賓客，時時好事者從之質疑問事，論道經書而已。〔一〕而遵晝夜呼號，〔二〕車騎滿門，酒肉相屬。〔三〕","sentenceOrder":136},
  {"id":"s_work_han_thu_106_137","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「質，正也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_106_138","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「呼音火故反。」","sentenceOrder":138},
  {"id":"s_work_han_thu_106_139","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「屬，連續也。屬音之欲反。」","sentenceOrder":139},
  {"id":"s_work_han_thu_106_140","chapterId":"ch_work_han_thu_106","textTraditional":"先是黃門郎揚雄作酒箴以諷諫成帝，其文為酒客難法度士，譬之於物，曰：「子猶瓶矣。觀瓶之居，居井之眉，〔一〕處高臨深，動常近危。酒醪不入口，臧水滿懷，不得左右，牽於纆徽。一旦叀礙，為瓽所轠，〔二〕身提黃泉，骨肉為泥。〔三〕自用如此，不如鴟夷。〔四〕鴟夷滑稽，腹如大壺，〔五〕盡日盛酒，人復借酤。〔六〕常為國器，託於屬車，〔七〕出入兩宮，經營公家。繇是言之，酒何過乎！」〔八〕遵大喜之，〔九〕常謂張竦：「吾與爾猶是矣。足下諷誦經書，苦身自約，〔一０〕不敢差跌，〔一一〕而我放意自恣，浮湛俗間，〔一二〕官爵功名，不減於子，而差獨樂，顧不優邪！」〔一三〕竦曰：「人各有性，長短自裁。子欲為我亦不能，吾而效子亦敗矣。雖然，學我者易持，效子者雖將，吾常道也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_106_141","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「眉，井邊地，若人目上之有眉。」","sentenceOrder":141},
  {"id":"s_work_han_thu_106_142","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「纆徽，井索也。叀，縣也。瓽，井以甎為甃者也。轠，擊也。言瓶忽縣礙不得下，而為井瓽所擊，則破碎也。叀音上絹反。瓽音丁浪反。轠音雷。諸家之說，或以叀為疐，或音衛，又以瓽為{臨瓦}，皆失之。甃音側救反。」","sentenceOrder":142},
  {"id":"s_work_han_thu_106_143","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「提，擲也，擲入黃泉之中也。提音徒計反。」","sentenceOrder":143},
  {"id":"s_work_han_thu_106_144","chapterId":"ch_work_han_thu_106","textTraditional":"〔四〕　師古曰：「鴟夷，韋囊以盛酒，即今鴟夷（勝）〔幐〕也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_106_145","chapterId":"ch_work_han_thu_106","textTraditional":"〔五〕　師古曰：「滑稽，圜轉縱捨無窮之狀。滑音骨。稽音雞。」","sentenceOrder":145},
  {"id":"s_work_han_thu_106_146","chapterId":"ch_work_han_thu_106","textTraditional":"〔六〕　師古曰：「盡猶竟日也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_106_147","chapterId":"ch_work_han_thu_106","textTraditional":"〔七〕　師古曰：「天子屬車，常載酒食，故有鴟夷也。屬音之欲反。」","sentenceOrder":147},
  {"id":"s_work_han_thu_106_148","chapterId":"ch_work_han_thu_106","textTraditional":"〔八〕　師古曰：「繇讀與由同。其下類此。」","sentenceOrder":148},
  {"id":"s_work_han_thu_106_149","chapterId":"ch_work_han_thu_106","textTraditional":"〔九〕　師古曰：「喜，好愛也，音許吏反。」","sentenceOrder":149},
  {"id":"s_work_han_thu_106_150","chapterId":"ch_work_han_thu_106","textTraditional":"〔一０〕師古曰：「約猶束也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_106_151","chapterId":"ch_work_han_thu_106","textTraditional":"〔一一〕師古曰：「跌音徒結反。」","sentenceOrder":151},
  {"id":"s_work_han_thu_106_152","chapterId":"ch_work_han_thu_106","textTraditional":"〔一二〕師古曰：「湛讀曰沈。」","sentenceOrder":152},
  {"id":"s_work_han_thu_106_153","chapterId":"ch_work_han_thu_106","textTraditional":"〔一三〕師古曰：「顧，念也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_106_154","chapterId":"ch_work_han_thu_106","textTraditional":"及王莽敗，二人俱客於池陽，〔一〕竦為賊兵所殺。〔二〕更始至長安，大臣薦遵為大司馬護軍，與歸德侯劉颯俱使匈奴。〔三〕單于欲脅詘遵，遵陳利害，為言曲直，單于大奇之，遣還。會更始敗，遵留朔方，為賊所敗，時醉見殺。","sentenceOrder":154},
  {"id":"s_work_han_thu_106_155","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「左馮翊之縣也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_106_156","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　李奇曰：「竦知有賊當去，會反支日，不去，因為賊所殺。桓譚（曰）〔以〕為通人之蔽也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_106_157","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　鄧展曰：「颯音立。」","sentenceOrder":157},
  {"id":"s_work_han_thu_106_158","chapterId":"ch_work_han_thu_106","textTraditional":"原涉字巨先。祖父武帝時以豪桀自陽翟徙茂陵。〔一〕涉父哀帝時為南陽太守。天下殷富，大郡二千石死官，賦斂送葬皆千萬以上，妻子通共受之，以定產業。時又少行三年喪者。及涉父死，讓還南陽賻送，行喪冢廬三年，繇是顯名京師。禮畢，扶風謁請為議曹，〔二〕衣冠慕之輻輳。為大司徒史丹舉能治劇，為谷口令，〔三〕時年二十餘。谷口聞其名，不言而治。","sentenceOrder":158},
  {"id":"s_work_han_thu_106_159","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「陽翟，潁川之縣也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_106_160","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「禮畢，行喪終服也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_106_161","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「左馮翊之縣，今之雲陽谷口是其處也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_106_162","chapterId":"ch_work_han_thu_106","textTraditional":"先是涉季父為茂陵秦氏所殺，涉居谷口半歲所，自劾去官，欲報仇。谷口豪桀為殺秦氏，亡命歲餘，逢赦出。郡國諸豪及長安、五陵諸為氣節者皆歸慕之。〔一〕涉遂傾身與相待，人無賢不肖闐門〔二〕，在所閭里盡滿客。或譏涉曰：「子本吏二千石之世，結髮自修，以行喪推財禮讓為名，正復讎取仇，猶不失仁義，何故遂自放縱，為輕俠之徒乎？」涉應曰：「子獨不見家人寡婦邪？始自約敕之時，意乃慕宋伯姬及陳孝婦，〔三〕不幸壹為盜賊所汙，遂行淫失，〔四〕知其非禮，然不能自還。吾猶此矣！」〔五〕","sentenceOrder":162},
  {"id":"s_work_han_thu_106_163","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「五陵，謂長陵、安陵、陽陵、茂陵、平陵也。班固西都賦曰『南望杜、霸，北眺五陵』，是知霸陵、杜陵非此五陵之數也。而說者以為高祖以下至茂陵為五陵，失其本意。」","sentenceOrder":163},
  {"id":"s_work_han_thu_106_164","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「闐字與窴同，音大千反。」","sentenceOrder":164},
  {"id":"s_work_han_thu_106_165","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「伯姬，魯宣公女，嫁於宋恭公。恭公卒，伯姬寡居。至景公時，伯姬之宮夜火，左右曰：『夫人少避火。』伯姬曰：『婦人之義，保傅不具，夜不下堂。』遂逮於火而死。陳孝婦者，其夫當行，戒屬孝婦曰：『幸有老母，吾若不來，汝善養吾母。』孝婦曰：『諾。』夫果死，孝婦養姑愈謹。其父母將取嫁之，孝婦固欲自殺，父母懼而不取，遂使養姑。淮陽太守以聞，朝廷高其義，賜黃金四十斤，復之終身。號曰孝婦。」","sentenceOrder":165},
  {"id":"s_work_han_thu_106_166","chapterId":"ch_work_han_thu_106","textTraditional":"〔四〕　師古曰：「失讀曰泆。」","sentenceOrder":166},
  {"id":"s_work_han_thu_106_167","chapterId":"ch_work_han_thu_106","textTraditional":"〔五〕　師古曰：「還讀曰旋，謂反歸故操。」","sentenceOrder":167},
  {"id":"s_work_han_thu_106_168","chapterId":"ch_work_han_thu_106","textTraditional":"涉自以為前讓南陽賻送，身得其名，而令先人墳墓儉約，非孝也。乃大治起冢舍，周閣重門。初，武帝時，京兆尹曹氏葬茂陵，民謂其道為京兆仟。涉慕之，乃買地開道，立表署曰南陽仟，人不肯從，謂之原氏仟。費用皆卬富人長者，〔一〕然身衣服車馬纔具，妻子內困。專以振施貧窮赴人之急為務。人嘗置酒請涉，涉入里門，客有道涉所知母病避疾在里宅者。〔二〕涉即往候，叩門。家哭，涉因入弔，問以喪事。家無所有，涉曰：「但絜埽除沐浴，待涉。」還至主人，對賓客歎息曰：「人親臥地不收，涉何心鄉此！〔三〕願徹去酒食。」賓客爭問所當得，涉乃側席而坐，〔四〕削牘為疏，〔五〕具記衣被棺木，下至飯含之物，分付諸客。〔六〕諸客奔走市買，至日昳皆會。〔七〕涉親閱視已，謂主人：「願受賜矣。」既共飲食，涉獨不飽，乃載棺物，從賓客往至喪家，為棺斂勞來畢葬。〔八〕其周急待人如此。後人有毀涉者曰「姦人之雄也」，喪家子即時刺殺言者。","sentenceOrder":168},
  {"id":"s_work_han_thu_106_169","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「卬音牛向反。」","sentenceOrder":169},
  {"id":"s_work_han_thu_106_170","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「在此里之中宅上。」","sentenceOrder":170},
  {"id":"s_work_han_thu_106_171","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「鄉讀曰向。」","sentenceOrder":171},
  {"id":"s_work_han_thu_106_172","chapterId":"ch_work_han_thu_106","textTraditional":"〔四〕　師古曰：「禮有憂者，側席而坐。今涉卹人之喪，故側席。」","sentenceOrder":172},
  {"id":"s_work_han_thu_106_173","chapterId":"ch_work_han_thu_106","textTraditional":"〔五〕　師古曰：「牘，木簡也。疏音所慮反。」","sentenceOrder":173},
  {"id":"s_work_han_thu_106_174","chapterId":"ch_work_han_thu_106","textTraditional":"〔六〕　師古曰：「飯音扶晚反。含音胡紺反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_106_175","chapterId":"ch_work_han_thu_106","textTraditional":"〔七〕　師古曰：「昳音徒結反。」","sentenceOrder":175},
  {"id":"s_work_han_thu_106_176","chapterId":"ch_work_han_thu_106","textTraditional":"〔八〕　師古曰：「勞來謂慰勉賓客也。棺音工喚反。斂音力贍反。勞音郎到反。來音郎代反。」","sentenceOrder":176},
  {"id":"s_work_han_thu_106_177","chapterId":"ch_work_han_thu_106","textTraditional":"賓客多犯法，罪過數上聞。王莽數收繫欲殺，輒復赦出之。涉懼，求為卿府掾史，欲以避客。文母太后喪時，守復土校尉。〔一〕已為中郎，后免官。涉欲上冢，不欲會賓客，密獨與故人期會。涉單車敺上茂陵，〔二〕投暮，入其里宅，因自匿不見人。遣奴至市買肉，奴乘涉氣與屠爭言，斫傷屠者，亡。是時，茂陵守令尹公〔三〕新視事，涉未謁也，聞之大怒。知涉名豪，欲以示眾厲俗，遣兩吏脅守涉。至日中，奴不出，吏欲便殺涉去。涉迫窘不知所為。會涉所與期上冢者車數十乘到，皆諸豪也，共說尹公。尹公不聽，諸豪則曰：「原巨先奴犯法不得，使肉袒自縛，箭貫耳，詣廷門謝罪，於君威亦足矣。」尹公許之。涉如言謝，復服遣去。〔四〕","sentenceOrder":177},
  {"id":"s_work_han_thu_106_178","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　蘇林曰：「文母太后，元后也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_106_179","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「敺與驅同。」","sentenceOrder":179},
  {"id":"s_work_han_thu_106_180","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「守茂陵令，未真為之。」","sentenceOrder":180},
  {"id":"s_work_han_thu_106_181","chapterId":"ch_work_han_thu_106","textTraditional":"〔四〕　師古曰：「令涉如故著衣服也。復音扶目反。」","sentenceOrder":181},
  {"id":"s_work_han_thu_106_182","chapterId":"ch_work_han_thu_106","textTraditional":"初，涉與新豐富人祁太伯為友，太伯同母弟王游公素嫉涉，時為縣門下掾，說尹公曰：「君以守令辱原涉如是，一旦真令至，君復單車歸為府吏，涉刺客如雲，殺人皆不知主名，可為寒心。涉治冢舍，奢僭踰制，罪惡暴著，主上知之。今為君計，莫若墮壞涉冢舍，條奏其舊惡，〔一〕君必得真令。如此，涉亦不敢怨矣。」尹公如其計，莽果以為真令。涉繇此怨王游公，選賓客，遣長子初從車二十乘劫王游公家。游公母即祁太伯母也，諸客見之皆拜，傳曰「無驚祁夫人」。遂殺游公父及子，斷兩頭去。〔二〕","sentenceOrder":182},
  {"id":"s_work_han_thu_106_183","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「墮，毀也，音火規反。」","sentenceOrder":183},
  {"id":"s_work_han_thu_106_184","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「殺游公及其父。」","sentenceOrder":184},
  {"id":"s_work_han_thu_106_185","chapterId":"ch_work_han_thu_106","textTraditional":"涉性略似郭解，外溫仁謙遜，而內隱〔一〕好殺。睚眥於塵中，（獨）〔觸〕死者甚多。王莽末，東方兵起，諸王子弟多薦涉能得士死，可用。莽乃召見，責以罪惡，赦貰，〔二〕拜鎮戎大尹（天水太守）。涉至官無幾，長安敗，〔三〕郡縣諸假號起兵攻殺二千石長吏以應漢。諸假號素聞涉名，爭問原尹何在，拜謁之。時莽州牧使者依附涉者皆得活。傳送致涉長安，更始西屏將軍申屠建請涉與相見，大重之。故茂陵令尹公壞涉冢舍者為建主簿，涉本不怨也。涉從建所出，尹公故遮拜涉，謂曰：「易世矣，宜勿復相怨！」涉曰：「尹君，何壹魚肉涉也！」〔四〕涉用是怒，使客刺殺主簿。","sentenceOrder":185},
  {"id":"s_work_han_thu_106_186","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「隱，匿其情也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_106_187","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「貰謂寬其罪。」","sentenceOrder":187},
  {"id":"s_work_han_thu_106_188","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「無幾，言無多時也。幾音居豈反。」","sentenceOrder":188},
  {"id":"s_work_han_thu_106_189","chapterId":"ch_work_han_thu_106","textTraditional":"〔四〕　師古曰：「言以涉為魚肉，不以人遇之。」","sentenceOrder":189},
  {"id":"s_work_han_thu_106_190","chapterId":"ch_work_han_thu_106","textTraditional":"涉欲亡去，申屠建內恨恥之，陽言「吾欲與原巨先共鎮三輔，豈以一吏易之哉！」賓客通言，令涉自繫獄謝，建許之。賓客車數十乘共送涉至獄。建遣兵道徼取涉於車上，〔一〕送車分散馳，遂斬涉，縣之長安市。〔二〕","sentenceOrder":190},
  {"id":"s_work_han_thu_106_191","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「徼，要也，音工堯反。」","sentenceOrder":191},
  {"id":"s_work_han_thu_106_192","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「縣其首。」","sentenceOrder":192},
  {"id":"s_work_han_thu_106_193","chapterId":"ch_work_han_thu_106","textTraditional":"自哀、平間，郡國處處有豪桀，然莫足數。其名聞州郡者，霸陵杜君敖，池陽韓幼孺，馬領繡君賓，西河漕中叔，皆有謙退之風〔一〕。王莽居攝，誅鉏豪俠，名捕漕中叔，不能得。〔二〕素善強弩將軍孫建，莽疑建藏匿，泛以問建。〔三〕建曰：「臣名善之，誅臣足以塞責。」莽性果賊，無所容忍，然重建，不竟問，遂不得也。中叔子少游，復以俠聞於世云。","sentenceOrder":193},
  {"id":"s_work_han_thu_106_194","chapterId":"ch_work_han_thu_106","textTraditional":"〔一〕　師古曰：「馬領，北地之縣。繡、漕，皆姓也。漕音才到反。中讀曰仲。」","sentenceOrder":194},
  {"id":"s_work_han_thu_106_195","chapterId":"ch_work_han_thu_106","textTraditional":"〔二〕　師古曰：「指其名而捕之。」","sentenceOrder":195},
  {"id":"s_work_han_thu_106_196","chapterId":"ch_work_han_thu_106","textTraditional":"〔三〕　師古曰：「泛者，以常語問之，不切責也。泛音敷劍反。」","sentenceOrder":196},
  {"id":"s_work_han_thu_106_197","chapterId":"ch_work_han_thu_106","textTraditional":"校勘記","sentenceOrder":197},
  {"id":"s_work_han_thu_106_198","chapterId":"ch_work_han_thu_106","textTraditional":"三六九九頁　二行　論語載（孔）〔曾〕子之言也。　景祐、殿本都作「曾子」。","sentenceOrder":198},
  {"id":"s_work_han_thu_106_199","chapterId":"ch_work_han_thu_106","textTraditional":"三七００頁　六行　乘傳東，〔一〕將至河南，　注〔一〕原在「至」字上，明顏讀以「將」字斷句。王先謙說當從「東」字斷，「將」字屬下讀，不若顏說。","sentenceOrder":199},
  {"id":"s_work_han_thu_106_200","chapterId":"ch_work_han_thu_106","textTraditional":"三七０二頁　二行　人怒，刺殺解姊子，（去亡）〔亡去〕。　王先謙說史記作「亡去」，是，此誤倒。","sentenceOrder":200},
  {"id":"s_work_han_thu_106_201","chapterId":"ch_work_han_thu_106","textTraditional":"三七一０頁一三行　母乃令從（從）〔後〕閤出去。　王先謙說下「從」字誤。按景祐、殿、局本都作「後」。","sentenceOrder":201},
  {"id":"s_work_han_thu_106_202","chapterId":"ch_work_han_thu_106","textTraditional":"三七一三頁一一行　即今鴟夷（勝）〔幐〕也。　汲古、局本作「幐」，景祐、殿本作「滕」。按「幐」本字，「滕」借字，「勝」字誤。","sentenceOrder":202},
  {"id":"s_work_han_thu_106_203","chapterId":"ch_work_han_thu_106","textTraditional":"三七一四頁　九行　桓譚（曰）〔以〕為通人之蔽也。　景祐、殿本都作「以」。王先謙說作「以」是。","sentenceOrder":203},
  {"id":"s_work_han_thu_106_204","chapterId":"ch_work_han_thu_106","textTraditional":"三七一八頁　九行　睚眥於塵中，（獨）〔觸〕死者甚多。　王念孫說「獨」當作「觸」。","sentenceOrder":204},
  {"id":"s_work_han_thu_106_205","chapterId":"ch_work_han_thu_106","textTraditional":"三七一八頁一一行　拜鎮戎大尹（天水太守）。　錢大昕說「天水太守」四字疑本注文，後人誤入正文。","sentenceOrder":205},
  {"id":"s_work_han_thu_107_1","chapterId":"ch_work_han_thu_107","textTraditional":"漢興，佞幸寵臣，高祖時則有籍孺，孝惠有閎孺。　此兩人非有材能，但以婉媚貴幸，〔一〕與上臥起，公卿皆因關說。〔二〕故孝惠時，郎侍中皆冠鵔鸃，貝帶，〔三〕傅脂粉，化閎、籍之屬也。兩人徙家安陵。其後寵臣，孝文時士人則鄧通，宦者則趙談、北宮伯子；〔四〕孝武時士人則韓嫣，〔五〕宦者則李延年；孝元時宦者則弘恭、石顯；孝成時士人則張放、淳于長；孝哀時則有董賢。孝景、昭、宣時皆無寵臣。景帝唯有郎中令周仁。昭帝時，駙馬都尉秺侯金賞〔六〕嗣父車騎將軍日磾爵為侯，二人之寵取過庸，不篤。〔七〕宣帝時，侍中中郎將張彭祖少與帝微時同席研書，及帝即尊位，彭祖以舊恩封陽都侯，出常參乘，號為愛幸。其人謹敕，無所虧損，〔八〕為其小妻所毒薨，國除。","sentenceOrder":1},
  {"id":"s_work_han_thu_107_2","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「婉，順也。媚，悅也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_107_3","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「關說者，言由之而納說，亦如行者之有關津。」","sentenceOrder":3},
  {"id":"s_work_han_thu_107_4","chapterId":"ch_work_han_thu_107","textTraditional":"〔三〕　師古曰：「以鵔鸃毛羽飾冠，海貝飾帶。鵔鸃即鷩鳥也。鵔音峻。鸃音儀。說在司馬相如傳。」","sentenceOrder":4},
  {"id":"s_work_han_thu_107_5","chapterId":"ch_work_han_thu_107","textTraditional":"〔四〕　師古曰：「姓北宮，名伯子。」","sentenceOrder":5},
  {"id":"s_work_han_thu_107_6","chapterId":"ch_work_han_thu_107","textTraditional":"〔五〕　師古曰：「嫣音偃。」","sentenceOrder":6},
  {"id":"s_work_han_thu_107_7","chapterId":"ch_work_han_thu_107","textTraditional":"〔六〕　師古曰：「秺音丁護反。」","sentenceOrder":7},
  {"id":"s_work_han_thu_107_8","chapterId":"ch_work_han_thu_107","textTraditional":"〔七〕　師古曰：「纔過於常人耳，不能大厚也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_107_9","chapterId":"ch_work_han_thu_107","textTraditional":"〔八〕　師古曰：「敕，整也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_107_10","chapterId":"ch_work_han_thu_107","textTraditional":"鄧通，蜀郡南安人也，以濯船為黃頭郎。〔一〕文帝嘗夢欲上天，不能，有一黃頭郎推上天，顧見其衣尻帶後穿。〔二〕覺而之漸臺，〔三〕以夢中陰目求推者郎，〔四〕見鄧通，其衣後穿，夢中所見也。召問其名姓，姓鄧，名通。鄧猶登也，文帝甚說，〔五〕尊幸之，日日異。通亦愿謹，不好外交，〔六〕雖賜洗沐，不欲出。於是文帝賞賜通鉅萬以十數，〔七〕官至上大夫。","sentenceOrder":10},
  {"id":"s_work_han_thu_107_11","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「濯船，能持濯行船也。土勝水，其色黃，故刺船之郎皆著黃帽，因號曰黃頭郎也。濯讀曰擢，音直孝反。」","sentenceOrder":11},
  {"id":"s_work_han_thu_107_12","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「衣尻帶後，謂衣當尻上而居革帶之下處也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_107_13","chapterId":"ch_work_han_thu_107","textTraditional":"〔三〕　師古曰：「覺謂寢寐之寤也。未央殿西南有蒼池，池中有漸臺。覺音工孝反。」","sentenceOrder":13},
  {"id":"s_work_han_thu_107_14","chapterId":"ch_work_han_thu_107","textTraditional":"〔四〕　師古曰：「默而視之，求所夢者。」","sentenceOrder":14},
  {"id":"s_work_han_thu_107_15","chapterId":"ch_work_han_thu_107","textTraditional":"〔五〕　師古曰：「說讀曰悅。」","sentenceOrder":15},
  {"id":"s_work_han_thu_107_16","chapterId":"ch_work_han_thu_107","textTraditional":"〔六〕　師古曰：「專謹曰愿，音願，又音原。」","sentenceOrder":16},
  {"id":"s_work_han_thu_107_17","chapterId":"ch_work_han_thu_107","textTraditional":"〔七〕　師古曰：「每賜輒鉅萬，如此者十數。」","sentenceOrder":17},
  {"id":"s_work_han_thu_107_18","chapterId":"ch_work_han_thu_107","textTraditional":"文帝時間如通家游戲，〔一〕然通無他伎能，不能有所薦達，獨自謹身以媚上而已。上使善相人者相通，曰：「當貧餓死。」上曰：「能富通者在我，何說貧？」於是賜通蜀嚴道銅山，得自鑄錢。〔二〕鄧氏錢布天下，其富如此。","sentenceOrder":18},
  {"id":"s_work_han_thu_107_19","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「間謂投隙私行，不公顯也。如，往也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_107_20","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「嚴道屬蜀郡。縣有蠻夷曰道。」","sentenceOrder":20},
  {"id":"s_work_han_thu_107_21","chapterId":"ch_work_han_thu_107","textTraditional":"文帝嘗病癰，鄧通常為上嗽吮之。〔一〕上不樂，從容問曰：「天下誰最愛我者乎？」通曰：「宜莫若太子。」太子入問疾，上使太子齰癰〔二〕太子（嗽）〔齰〕癰而色難之。已而聞通嘗為上齰〔之〕，太子慚，繇是心恨通。〔三〕","sentenceOrder":21},
  {"id":"s_work_han_thu_107_22","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「嗽音山角反。吮音自兗反。」","sentenceOrder":22},
  {"id":"s_work_han_thu_107_23","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「齰，齧也，齧出其膿血。齰音仕客反。」","sentenceOrder":23},
  {"id":"s_work_han_thu_107_24","chapterId":"ch_work_han_thu_107","textTraditional":"〔三〕　師古曰：「繇讀與由同。其下類此。」","sentenceOrder":24},
  {"id":"s_work_han_thu_107_25","chapterId":"ch_work_han_thu_107","textTraditional":"及文帝崩，景帝立，鄧通免，家居。居無何，人有告通盜出徼外鑄錢，〔一〕下吏驗問，頗有，遂竟案，〔二〕盡沒入之，通家尚負責數鉅萬。〔三〕長公主賜鄧通，〔四〕吏輒隨沒入之，一簪不得著身。於是長公主乃令假衣食。〔五〕竟不得名一錢，寄死人家。","sentenceOrder":25},
  {"id":"s_work_han_thu_107_26","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「徼猶塞也。東北謂之塞，西南謂之徼。塞者，以障塞為名。徼者，取徼遮之義也。徼音工釣反。」","sentenceOrder":26},
  {"id":"s_work_han_thu_107_27","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「遂，成也，成其罪狀。」","sentenceOrder":27},
  {"id":"s_work_han_thu_107_28","chapterId":"ch_work_han_thu_107","textTraditional":"〔三〕　張晏曰：「顧人採銅鑄錢，未還庸直，而會沒入故也。」師古曰：「此說非也。積其前後所犯合沒官者數多，除其見在財物以外，尚有負官數鉅萬，故云吏輒隨沒入之耳，非負顧庸之私直。」","sentenceOrder":28},
  {"id":"s_work_han_thu_107_29","chapterId":"ch_work_han_thu_107","textTraditional":"〔四〕　師古曰：「即館陶長公主，文帝之女也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_107_30","chapterId":"ch_work_han_thu_107","textTraditional":"〔五〕　晉灼曰：「使假貸而私為償之也。」師古曰：「此說非也。公主給其衣食也，而號云假借之耳，非通自有也。恐吏沒入，故託云然。此所謂不得名一錢。」","sentenceOrder":30},
  {"id":"s_work_han_thu_107_31","chapterId":"ch_work_han_thu_107","textTraditional":"趙談者，以星氣幸，北宮伯子長者愛人，故親近，然皆不比鄧通。","sentenceOrder":31},
  {"id":"s_work_han_thu_107_32","chapterId":"ch_work_han_thu_107","textTraditional":"韓嫣字王孫，弓高侯穨當之孫也。武帝為膠東王時，嫣與上學書相愛。及上為太子，愈益親嫣。嫣善騎射，聰慧。上即位，欲事伐胡，而嫣先習兵，〔一〕以故益尊貴，官至上大夫，賞賜儗鄧通。〔二〕","sentenceOrder":32},
  {"id":"s_work_han_thu_107_33","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「言舊自便習。」","sentenceOrder":33},
  {"id":"s_work_han_thu_107_34","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「儗，比也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_107_35","chapterId":"ch_work_han_thu_107","textTraditional":"始時，嫣常與上共臥起。江都王入朝，從上獵上林中。天子車駕〈走畢〉道未行，〔一〕先使嫣乘副車，從數十百騎馳視獸。江都王望見，以為天子，辟從者，伏謁道旁。〔二〕嫣驅不見。既過，江都王怒，為皇太后泣，請得歸國〔三〕入宿衛，比韓嫣。太后繇此銜嫣。","sentenceOrder":35},
  {"id":"s_work_han_thu_107_36","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「已稱〈走畢〉，止行人訖，而天子未出也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_107_37","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「辟去其從者，而身獨伏謁也。辟音闢。」","sentenceOrder":37},
  {"id":"s_work_han_thu_107_38","chapterId":"ch_work_han_thu_107","textTraditional":"〔三〕　師古曰：「還爵封於天子也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_107_39","chapterId":"ch_work_han_thu_107","textTraditional":"嫣侍，出入永巷不禁，〔一〕以姦聞皇太后。太后怒，使使賜嫣死。上為謝，終不能得，嫣遂死。","sentenceOrder":39},
  {"id":"s_work_han_thu_107_40","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「言上恣其出入也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_107_41","chapterId":"ch_work_han_thu_107","textTraditional":"嫣弟說，亦愛幸，〔一〕以軍功封案道侯，巫蠱時為戾太子所殺。子增封龍雒侯，〔二〕大司馬車騎將軍，自有傳。〔三〕","sentenceOrder":41},
  {"id":"s_work_han_thu_107_42","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":42},
  {"id":"s_work_han_thu_107_43","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「雒字或作頟。」","sentenceOrder":43},
  {"id":"s_work_han_thu_107_44","chapterId":"ch_work_han_thu_107","textTraditional":"〔三〕　師古曰：「在韓信傳末。」","sentenceOrder":44},
  {"id":"s_work_han_thu_107_45","chapterId":"ch_work_han_thu_107","textTraditional":"李延年，中山人，身及父母兄弟皆故倡也。〔一〕延年坐法腐刑，給事狗監中。〔二〕女弟得幸於上，號李夫人，列外戚傳。延年善歌，為新變聲。是時上方興天地諸祠，欲造樂，令司馬相如等作詩頌。延年輒承意弦歌所造詩，為之新聲曲。而李夫人產昌邑王，延年繇是貴為協律都尉，佩二千石印綬，而與上臥起，其愛幸埒韓嫣。〔三〕久之，延年弟季與中人亂，出入驕恣。及李夫人卒後，其愛弛〔四〕，上遂誅延年兄弟宗族。","sentenceOrder":45},
  {"id":"s_work_han_thu_107_46","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「樂人也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_107_47","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「掌天子之狗，於其中供事也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_107_48","chapterId":"ch_work_han_thu_107","textTraditional":"〔三〕　師古曰：「埒，等齊。」","sentenceOrder":48},
  {"id":"s_work_han_thu_107_49","chapterId":"ch_work_han_thu_107","textTraditional":"〔四〕　師古曰：「弛，解也，音式爾反。」","sentenceOrder":49},
  {"id":"s_work_han_thu_107_50","chapterId":"ch_work_han_thu_107","textTraditional":"是後寵臣，大氐外戚之家也。〔一〕衛青、霍去病皆愛幸，然亦以功能自進。","sentenceOrder":50},
  {"id":"s_work_han_thu_107_51","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「氐，歸也，音丁禮反。」","sentenceOrder":51},
  {"id":"s_work_han_thu_107_52","chapterId":"ch_work_han_thu_107","textTraditional":"石顯字君房，濟南人；弘恭，沛人也。皆少坐法腐刑，為中黃門，以選為中尚書。宣帝時任中書官，恭明習法令故事，善為請奏，能稱其職。恭為令，顯為僕射。元帝即位數年，恭死，顯代為中書令。","sentenceOrder":52},
  {"id":"s_work_han_thu_107_53","chapterId":"ch_work_han_thu_107","textTraditional":"是時，元帝被疾，不親政事，方隆好於音樂，以顯久典事，中人無外黨，〔一〕精專可信任，遂委以政。事無小大，因顯白決，貴幸傾朝，百僚皆敬事顯。顯為人巧慧習事，能探得人主微指，內深賊，持詭辯以中傷人，〔二〕忤恨睚眥，輒被以危法。〔三〕初元中，前將軍蕭望之及光祿大夫周堪、宗正劉更生皆給事中。望之領尚書事，知顯專權邪辟，〔四〕建白以為「尚書百官之本，國家樞機，〔五〕宜以通明公正處之。武帝游宴後庭，故用宦者，非古制也。宜罷中書宦官，應古不近刑人。」〔六〕元帝不聽，繇是大與顯忤。後皆害焉，望之自殺，堪、更生廢錮，不得復進用，語在望之傳。後太中大夫張猛、魏郡太守京房、御史中丞陳咸、待詔賈捐之皆嘗奏封事，或召見，言顯短。顯求索其罪，房、捐之棄市，猛自殺於公車，咸抵罪，髡為城旦。及鄭令蘇建得顯私書奏之，後以它事論死。自是公卿以下畏顯，重足一跡。〔七〕","sentenceOrder":53},
  {"id":"s_work_han_thu_107_54","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「少骨肉之親，無婚姻之家也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_107_55","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「詭，違也，違道之辯。」","sentenceOrder":55},
  {"id":"s_work_han_thu_107_56","chapterId":"ch_work_han_thu_107","textTraditional":"〔三〕　師古曰：「被，加也，音皮義反。」","sentenceOrder":56},
  {"id":"s_work_han_thu_107_57","chapterId":"ch_work_han_thu_107","textTraditional":"〔四〕　師古曰：「辟讀曰僻。」","sentenceOrder":57},
  {"id":"s_work_han_thu_107_58","chapterId":"ch_work_han_thu_107","textTraditional":"〔五〕　師古曰：「立此議而白之。」","sentenceOrder":58},
  {"id":"s_work_han_thu_107_59","chapterId":"ch_work_han_thu_107","textTraditional":"〔六〕　師古曰：「禮『刑人不在君側』，故曰應古。」","sentenceOrder":59},
  {"id":"s_work_han_thu_107_60","chapterId":"ch_work_han_thu_107","textTraditional":"〔七〕　師古曰：「言極恐懼，不敢自寬縱。」","sentenceOrder":60},
  {"id":"s_work_han_thu_107_61","chapterId":"ch_work_han_thu_107","textTraditional":"顯與中書僕射牢梁、少府五鹿充宗結為黨友，諸附倚者皆得寵位。〔一〕民歌之曰：「牢邪石邪，五鹿客邪！印何纍纍，綬若若邪！」〔二〕言其兼官據勢也。","sentenceOrder":61},
  {"id":"s_work_han_thu_107_62","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「倚，依也，音於綺反。」","sentenceOrder":62},
  {"id":"s_work_han_thu_107_63","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「纍纍，重積也。若若，長貌。纍音力追反。」","sentenceOrder":63},
  {"id":"s_work_han_thu_107_64","chapterId":"ch_work_han_thu_107","textTraditional":"顯見左將軍馮奉世父子為公卿著名，女又為昭儀在內，顯心欲附之，薦言昭儀兄謁者逡〔一〕修敕宜帷幄。〔二〕天子召見，欲以為侍中，逡請間言事。上聞逡言顯顓權，〔三〕天子大怒，罷逡歸郎官。其後御史大夫缺，群臣皆舉逡兄大鴻臚野王行能第一，天子以問顯，顯曰：「九卿無出野王者。然野王親昭儀兄，臣恐後世必以陛下度越眾賢，〔四〕私後宮親以為三公。」上曰：「善，吾不見是。」乃下詔嘉美野王，廢而不用，語在野王傳。","sentenceOrder":64},
  {"id":"s_work_han_thu_107_65","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「逡音千旬反。」","sentenceOrder":65},
  {"id":"s_work_han_thu_107_66","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「敕，整也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_107_67","chapterId":"ch_work_han_thu_107","textTraditional":"〔三〕　師古曰：「顓與專同。其下類此。」","sentenceOrder":67},
  {"id":"s_work_han_thu_107_68","chapterId":"ch_work_han_thu_107","textTraditional":"〔四〕　師古曰：「度，過也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_107_69","chapterId":"ch_work_han_thu_107","textTraditional":"〔五〕　師古曰：「言不見此理。」","sentenceOrder":69},
  {"id":"s_work_han_thu_107_70","chapterId":"ch_work_han_thu_107","textTraditional":"顯內自知擅權事柄在掌握，恐天子一旦納用左右耳目，有以間己，〔一〕乃時歸誠，取一信以為驗。顯嘗使至諸官有所徵發，顯先自白，恐後漏盡宮門閉，請使詔吏開門。上許之。顯故投夜還，稱詔開門入。後果有上書告顯顓命矯詔開宮門，天子聞之，笑以其書示顯。顯因泣曰：「陛下過私小臣，屬任以事，〔二〕群下無不嫉妒欲陷害臣者，事類如此非一，唯獨明主知之。愚臣微賤，誠不能以一軀稱快萬眾，〔三〕任天下之怨，〔四〕臣願歸樞機職，受後宮掃除之役，死無所恨，唯陛下哀憐財幸，〔五〕以此全活小臣。」天子以為然而憐之，數勞勉顯，加厚賞賜，賞賜及賂遺訾一萬萬。〔六〕","sentenceOrder":70},
  {"id":"s_work_han_thu_107_71","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「間音工莧反。」","sentenceOrder":71},
  {"id":"s_work_han_thu_107_72","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「過猶誤也。屬，委也。屬音之欲反。」","sentenceOrder":72},
  {"id":"s_work_han_thu_107_73","chapterId":"ch_work_han_thu_107","textTraditional":"〔三〕　師古曰：「稱音尺孕反。」","sentenceOrder":73},
  {"id":"s_work_han_thu_107_74","chapterId":"ch_work_han_thu_107","textTraditional":"〔四〕　師古曰：「任猶當也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_107_75","chapterId":"ch_work_han_thu_107","textTraditional":"〔五〕　師古曰：「財與裁同。」","sentenceOrder":75},
  {"id":"s_work_han_thu_107_76","chapterId":"ch_work_han_thu_107","textTraditional":"〔六〕　師古曰：「賂遺，謂百官群下所遺也。訾讀與貲同。」","sentenceOrder":76},
  {"id":"s_work_han_thu_107_77","chapterId":"ch_work_han_thu_107","textTraditional":"初，顯聞眾人匈匈，言己殺前將軍蕭望之。望之當世名儒，顯恐天下學士姍己，〔一〕病之。是時，明經著節士琅邪貢禹為諫大夫，顯使人致意，深自結納。顯因薦禹天子，歷位九卿，至御史大夫，禮事之甚備。議者於是稱顯，以為不妒譖望之矣。顯之設變詐以自解免取信人主者，皆此類也。","sentenceOrder":77},
  {"id":"s_work_han_thu_107_78","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「姍，古訕字。訕，謗也，音所諫反。」","sentenceOrder":78},
  {"id":"s_work_han_thu_107_79","chapterId":"ch_work_han_thu_107","textTraditional":"元帝晚節寢疾，〔一〕定陶恭王愛幸，顯擁祐太子頗有力。元帝崩，成帝初即位，遷顯為長信中太僕，秩中二千石。顯失倚，離權數月，丞相御史條奏顯舊惡，及其黨牢梁、陳順皆免官。顯與妻子徙歸故郡，憂滿不食，道病死。〔二〕諸所交結，以顯為官，皆廢罷。少府五鹿充宗左遷玄菟太守，御史中丞伊嘉為鴈門都尉。長安謠曰：「伊徙鴈，鹿徙菟，去牢與陳實無賈。」〔三〕","sentenceOrder":79},
  {"id":"s_work_han_thu_107_80","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「晚節猶言末時也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_107_81","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「滿讀曰懣，音悶。」","sentenceOrder":81},
  {"id":"s_work_han_thu_107_82","chapterId":"ch_work_han_thu_107","textTraditional":"〔三〕　師古曰：「賈讀曰價。」","sentenceOrder":82},
  {"id":"s_work_han_thu_107_83","chapterId":"ch_work_han_thu_107","textTraditional":"淳于長字子，魏郡元城人也。少以太后姊子為黃門郎，未進幸。會大將軍王鳳病，長侍病，晨夜扶丞左右，甚有甥舅之恩。鳳且終，以長屬託太后及帝。〔一〕帝嘉長義，拜為列校尉諸曹，遷水衡都尉侍中，至衛尉九卿。","sentenceOrder":83},
  {"id":"s_work_han_thu_107_84","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「屬音之欲反。」","sentenceOrder":84},
  {"id":"s_work_han_thu_107_85","chapterId":"ch_work_han_thu_107","textTraditional":"久之，趙飛燕貴幸，上欲立以為皇后，太后以其所出微，難之。長主往來通語東宮。〔一〕歲餘，趙皇后得立，上甚德之，乃追顯長前功，下詔曰：「前將作大匠解萬年奏請營作昌陵，罷弊海內，〔二〕侍中衛尉長數白宜止徙家反故處，〔三〕朕以長言下公卿，議者皆合長計。首建至策，民以康寧。〔四〕其賜長爵關內侯。」後遂封為定陵侯，大見信用，貴傾公卿。外交諸侯牧守，賂遺賞賜亦絫鉅萬。〔五〕多畜妻妾，淫於聲色，不奉法度。","sentenceOrder":85},
  {"id":"s_work_han_thu_107_86","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「主猶專。」","sentenceOrder":86},
  {"id":"s_work_han_thu_107_87","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「罷讀曰疲。」","sentenceOrder":87},
  {"id":"s_work_han_thu_107_88","chapterId":"ch_work_han_thu_107","textTraditional":"〔三〕　師古曰：「陵置邑，徙人以實之。長奏令止所徙之家各還本處。」","sentenceOrder":88},
  {"id":"s_work_han_thu_107_89","chapterId":"ch_work_han_thu_107","textTraditional":"〔四〕　師古曰：「康，安也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_107_90","chapterId":"ch_work_han_thu_107","textTraditional":"〔五〕　師古曰：「絫，古累字也。其下亦同。」","sentenceOrder":90},
  {"id":"s_work_han_thu_107_91","chapterId":"ch_work_han_thu_107","textTraditional":"初，許皇〔后〕坐執左道廢處長定宮，而后姊孊為龍頟思侯夫人，〔一〕寡居。長與孊私通，因取為小妻。許后因孊賂遺長，欲求復為婕妤。長受許后金錢乘輿服御物前後千餘萬，詐許為白上，立以為左皇后。孊每入長定宮，輒與孊書，戲侮許后，嫚易無不言。〔二〕交通書記，賂遺連年，是時，帝舅曲陽侯王根為大司馬票騎將軍，輔政數歲，久病，數乞骸骨。長以外親居九卿位，次第當代根。根兄子新都侯王莽心害長寵，私聞長取許孊，受長定宮賂遺。莽侍曲陽侯疾，因言「長見將軍久病，意喜，自以當代輔政，至對衣冠議語署置。」〔三〕具言其罪過。根怒曰：「即如是，何不白也？」莽曰：「未知將軍意，故未敢言。」根曰：「趣白東宮。」〔四〕莽求見太后，具言長驕佚，〔五〕欲代曲陽侯，對莽母上車，〔六〕私與長定貴人姊通，受取其衣物。太后亦怒曰：「兒至如此！往白之帝！」莽白上，上乃免長官，遣就國。","sentenceOrder":91},
  {"id":"s_work_han_thu_107_92","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　晉灼曰：「孊音靡。」","sentenceOrder":92},
  {"id":"s_work_han_thu_107_93","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「嫚，褻汙也。易，輕也。易音弋豉反。」","sentenceOrder":93},
  {"id":"s_work_han_thu_107_94","chapterId":"ch_work_han_thu_107","textTraditional":"〔三〕　師古曰：「自謂當輔政，故豫言某人為某官，某人為某事。」","sentenceOrder":94},
  {"id":"s_work_han_thu_107_95","chapterId":"ch_work_han_thu_107","textTraditional":"〔四〕　師古曰：「趣讀曰促。」","sentenceOrder":95},
  {"id":"s_work_han_thu_107_96","chapterId":"ch_work_han_thu_107","textTraditional":"〔五〕　師古曰：「佚讀與逸同。」","sentenceOrder":96},
  {"id":"s_work_han_thu_107_97","chapterId":"ch_work_han_thu_107","textTraditional":"〔六〕　師古曰：「莽母於長，舅之妻也，上車當於異處。便於前上，言不敬。」","sentenceOrder":97},
  {"id":"s_work_han_thu_107_98","chapterId":"ch_work_han_thu_107","textTraditional":"初，長為侍中，奉兩宮使，親密。〔一〕紅陽侯立獨不得為大司馬輔政，立自疑為長毀譖，常怨毒長。上知之。及長當就國也，立嗣子融從長請車騎，〔二〕長以珍寶因融重遺立，立因為長言。於是天子疑焉，下有司案驗。吏捕融，立令融自殺以滅口。上愈疑其有大姦，遂逮長繫洛陽詔獄窮治。長具服戲侮長定宮，〔三〕謀立左皇后，罪至大逆，死獄中。妻子當坐者徙合浦，母若歸故郡。〔四〕紅陽侯立就國。將軍卿大夫郡守坐長免罷者數十人。莽遂代根為大司馬。久之，還長母及子酺於長安。〔五〕後酺有罪，莽復殺之，徙其家屬〔歸〕故郡。","sentenceOrder":98},
  {"id":"s_work_han_thu_107_99","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「言為使者傳言語於太后及帝，欲立趙飛燕之類。」","sentenceOrder":99},
  {"id":"s_work_han_thu_107_100","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「嗣子謂嫡長子，當為嗣者也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_107_101","chapterId":"ch_work_han_thu_107","textTraditional":"〔三〕　師古曰：「〈亻母〉，古侮字。」","sentenceOrder":101},
  {"id":"s_work_han_thu_107_102","chapterId":"ch_work_han_thu_107","textTraditional":"〔四〕　師古曰：「若者，其母名。」","sentenceOrder":102},
  {"id":"s_work_han_thu_107_103","chapterId":"ch_work_han_thu_107","textTraditional":"〔五〕　師古曰：「酺音蒲。」","sentenceOrder":103},
  {"id":"s_work_han_thu_107_104","chapterId":"ch_work_han_thu_107","textTraditional":"始長以外親親近，〔一〕其愛幸不及富平侯張放。放常與上臥起，俱為微行出入。","sentenceOrder":104},
  {"id":"s_work_han_thu_107_105","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「親近謂近幸於天子。近音其靳反。」","sentenceOrder":105},
  {"id":"s_work_han_thu_107_106","chapterId":"ch_work_han_thu_107","textTraditional":"董賢字聖卿，雲陽人也。父恭，為御史，任賢為太子舍人。哀帝立，賢隨太子官為郎。〔一〕二歲餘，賢傳漏在殿下，〔二〕為人美麗自喜，〔三〕哀帝望見，說其儀貌，〔四〕識而問之，曰：「是舍人董賢邪？」因引上與語，拜為黃門郎，繇是始幸。問及其父為雲中侯，即日徵為霸陵令，遷光祿大夫。賢寵愛日甚，為駙馬都尉侍中，出則參乘，入御左右，旬月間賞賜絫鉅萬，貴震朝廷。常與上臥起。嘗晝寢，偏藉上袖，〔五〕上欲起，賢未覺，〔六〕不欲動賢，乃斷袖而起。其恩愛至此。賢亦性柔和便辟，善為媚以自固。每賜洗沐，不肯出，（嘗）〔常〕留中視醫藥。上以賢難歸，詔令賢妻得通引籍殿中，止賢廬，〔七〕若吏妻子居官寺舍。又（詔）〔召〕賢女弟以為昭儀，位次皇后，更名其舍為椒風，以配椒房云。〔八〕昭儀及賢與妻旦夕上下，並侍左右。賞賜昭儀及賢妻亦各千萬數。遷賢父為少府，賜爵關內侯，食邑，復徙為衛尉。又以賢妻父為將作大匠，弟為執金吾。詔將作大匠為賢起大第北闕下，重殿洞門，〔九〕木土之功窮極技巧，柱檻衣以綈錦。〔一０〕下至賢家僮僕皆受上賜，及武庫禁兵，上方珍寶。其選物上弟盡在董氏，而乘輿所服乃其副也。及至東園祕器，珠襦玉柙，豫以賜賢，無不備具。〔一一〕又令將作為賢起冢塋義陵旁，內為便房，剛柏題湊，〔一二〕外為徼道，周垣數里，門闕罘罳甚盛。","sentenceOrder":106},
  {"id":"s_work_han_thu_107_107","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「東宮官屬，隨例遷也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_107_108","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「傳漏，奏時刻。」","sentenceOrder":108},
  {"id":"s_work_han_thu_107_109","chapterId":"ch_work_han_thu_107","textTraditional":"〔三〕　師古曰：「喜音許吏反。」","sentenceOrder":109},
  {"id":"s_work_han_thu_107_110","chapterId":"ch_work_han_thu_107","textTraditional":"〔四〕　師古曰：「說讀曰悅。」","sentenceOrder":110},
  {"id":"s_work_han_thu_107_111","chapterId":"ch_work_han_thu_107","textTraditional":"〔五〕　師古曰：「藉謂身臥其上也。褏，古袖字。」","sentenceOrder":111},
  {"id":"s_work_han_thu_107_112","chapterId":"ch_work_han_thu_107","textTraditional":"〔六〕　師古曰：「覺，寐之寤也，音工效反。」","sentenceOrder":112},
  {"id":"s_work_han_thu_107_113","chapterId":"ch_work_han_thu_107","textTraditional":"〔七〕　師古曰：「廬謂殿中所宿止處也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_107_114","chapterId":"ch_work_han_thu_107","textTraditional":"〔八〕　師古曰：「皇后殿稱椒房。欲配其名，故曰椒風。」","sentenceOrder":114},
  {"id":"s_work_han_thu_107_115","chapterId":"ch_work_han_thu_107","textTraditional":"〔九〕　師古曰：「重殿謂有前後殿，洞門謂門門相當也。皆僭天子之制度者也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_107_116","chapterId":"ch_work_han_thu_107","textTraditional":"〔一０〕師古曰：「檻謂軒闌之板也。綈，厚繒也，音徒奚反。」","sentenceOrder":116},
  {"id":"s_work_han_thu_107_117","chapterId":"ch_work_han_thu_107","textTraditional":"〔一一〕師古曰：「東園，署名也。漢舊儀云東園祕器作棺梓，素木長二丈，崇廣四尺。珠襦，以珠為襦，如鎧狀，連縫之。以黃金為鏤，要以下，玉為柙，至足，亦縫以黃金為縷。」","sentenceOrder":117},
  {"id":"s_work_han_thu_107_118","chapterId":"ch_work_han_thu_107","textTraditional":"〔一二〕孟康曰：「堅剛之柏也。」師古曰：「題湊解在霍光傳。」","sentenceOrder":118},
  {"id":"s_work_han_thu_107_119","chapterId":"ch_work_han_thu_107","textTraditional":"上欲侯賢而未有緣。會待詔孫寵、息夫躬等告東平王雲后謁祠祀祝詛，〔一〕下有司治，皆伏其辜。上於是令躬、寵為因賢告東平事者，乃以其功下詔封賢為高安侯，躬宜陵侯，寵方陽侯，食邑各千戶。頃之，復益封賢二千戶。丞相王嘉內疑東平事冤，甚惡躬等，數諫爭，以賢為亂國制度，嘉竟坐言事下獄死。","sentenceOrder":119},
  {"id":"s_work_han_thu_107_120","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「謁者，后之名。」","sentenceOrder":120},
  {"id":"s_work_han_thu_107_121","chapterId":"ch_work_han_thu_107","textTraditional":"上初即位，祖母傅太后、母丁太后皆在，兩家先貴。傅太后從弟喜先為大司馬輔政，數諫，失太后指，免官。上舅丁明代為大司馬，亦任職，頗害賢寵，及丞相王嘉死，明甚憐之。上浸重賢，欲極其位，〔一〕而恨明如此，遂冊免明曰：「前東平王雲貪欲上位，祠祭祝詛，雲后舅伍宏以醫待詔，與校祕書郎楊閎結謀反逆，禍甚迫切。賴宗廟神靈，董賢等以聞，咸伏其辜。將軍從弟侍中奉車都尉吳、族父左曹屯騎校尉宣皆知宏及栩丹諸侯王后親，〔二〕而宣除用丹為御屬，吳與宏交通厚善，數稱薦宏。宏以附吳得興其惡心，因醫技進，幾危社稷，〔三〕朕以恭皇后故，不忍有云。〔四〕將軍位尊任重，既不能明威立義，折消未萌，〔五〕又不深疾雲、宏之惡，而懷非君上，阿為宣、吳，〔六〕反痛恨雲等揚言為群下所冤，又親見言伍宏善醫，死可惜也，〔七〕賢等獲封極幸。嫉妒忠良，非毀有功，於戲傷哉！〔八〕蓋『君親無將，將而誅之』。〔九〕是以季友鴆叔牙，春秋賢之；趙盾不討賊，謂之弒君。〔一０〕朕閔將軍陷于重刑，故以書飭。〔一一〕將軍遂非不改，復與丞相嘉相比，〔一二〕令嘉有依，得以罔上。有司致法將軍請獄治，朕惟噬膚之恩未忍，〔一三〕其上票騎將軍印綬，罷歸就第。」遂以賢代明為大司馬衛將軍，冊曰：「朕承天序，惟稽古建爾于公，以為漢輔。往悉爾心，統辟元戎〔一四〕，折衝綏遠，匡正庶事，允執其中。天下之眾，受制於朕，以將為命，以兵為威，可不慎與！」〔一五〕是時賢年二十二，雖為三公，常給事中，領尚書，百官因賢奏事。以父恭不宜在卿位，徙為光祿大夫，秩中二千石。弟寬信代賢為駙馬都尉。董氏親屬皆侍中諸曹奉朝請，寵在丁、傅之右矣。〔一六〕","sentenceOrder":121},
  {"id":"s_work_han_thu_107_122","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「浸，益也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_107_123","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「栩，姓也，音許羽反。」","sentenceOrder":123},
  {"id":"s_work_han_thu_107_124","chapterId":"ch_work_han_thu_107","textTraditional":"〔三〕　師古曰：「幾音鉅依反。」","sentenceOrder":124},
  {"id":"s_work_han_thu_107_125","chapterId":"ch_work_han_thu_107","textTraditional":"〔四〕　師古曰：「恭皇后，謂丁后，即哀帝母。」","sentenceOrder":125},
  {"id":"s_work_han_thu_107_126","chapterId":"ch_work_han_thu_107","textTraditional":"〔五〕　師古曰：「未萌，謂禍難之未生者。」","sentenceOrder":126},
  {"id":"s_work_han_thu_107_127","chapterId":"ch_work_han_thu_107","textTraditional":"〔六〕　師古曰：「以君上為非，懷此心也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_107_128","chapterId":"ch_work_han_thu_107","textTraditional":"〔七〕　師古曰：「見，見天子也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_107_129","chapterId":"ch_work_han_thu_107","textTraditional":"〔八〕　師古曰：「於讀曰烏，戲讀曰呼。」","sentenceOrder":129},
  {"id":"s_work_han_thu_107_130","chapterId":"ch_work_han_thu_107","textTraditional":"〔九〕　師古曰：「將謂將為逆亂也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_107_131","chapterId":"ch_work_han_thu_107","textTraditional":"〔一０〕師古曰：「季友，魯桓公少子，莊公母弟也。叔牙亦桓公子。莊公有疾，叔牙欲立其同母兄慶父，故季友使鍼季鴆之。公羊傳曰：『季子殺兄何善爾？誅不得避兄弟，君臣之義也。』趙盾，晉大夫趙宣子也，靈公欲殺之。宣子將出奔，而趙穿攻靈公於桃園，宣子未出山而復，太史書曰：『趙盾弒其君。』宣子曰：『不然』。曰：『子為正卿，亡不越境，反不討賊，非子而誰？』孔子曰：『董狐，古之良史也，書法不隱。趙宣子，古之良大夫也，為法受惡。』」","sentenceOrder":131},
  {"id":"s_work_han_thu_107_132","chapterId":"ch_work_han_thu_107","textTraditional":"〔一一〕師古曰：「飭與敕同。」","sentenceOrder":132},
  {"id":"s_work_han_thu_107_133","chapterId":"ch_work_han_thu_107","textTraditional":"〔一二〕師古曰：「比謂比周也，音頻寐反。」","sentenceOrder":133},
  {"id":"s_work_han_thu_107_134","chapterId":"ch_work_han_thu_107","textTraditional":"〔一三〕孟康曰：「易曰『噬膚滅鼻』。噬，食也。膚，膏也。喻爵祿恩澤加之，不忍誅也。」師古曰：「孟說非也。易噬嗑卦九二爻辭曰『噬膚滅鼻』。噬膚者，言自齧其肌膚。詔云，為明是恭后之親，有肌膚之愛，是以不忍加法，故引噬膚之言也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_107_135","chapterId":"ch_work_han_thu_107","textTraditional":"〔一四〕師古曰：「悉，盡也。統，領也。辟，君也。元戎，大眾也。言為元戎之主而統之也。辟音必亦反。」","sentenceOrder":135},
  {"id":"s_work_han_thu_107_136","chapterId":"ch_work_han_thu_107","textTraditional":"〔一五〕師古曰：「與讀曰歟。」","sentenceOrder":136},
  {"id":"s_work_han_thu_107_137","chapterId":"ch_work_han_thu_107","textTraditional":"〔一六〕師古曰：「右，上也。」","sentenceOrder":137},
  {"id":"s_work_han_thu_107_138","chapterId":"ch_work_han_thu_107","textTraditional":"明年，匈奴單于來朝，宴見，群臣在前。單于怪賢年少，以問譯，〔一〕上令譯報曰：「大司馬年少，以大賢居位。」單于乃起拜，賀漢得賢臣。","sentenceOrder":138},
  {"id":"s_work_han_thu_107_139","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「傳語之人也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_107_140","chapterId":"ch_work_han_thu_107","textTraditional":"初，丞相孔光為御史大夫，時賢父恭為御史，事光。及賢為大司馬，與光並為三公，上故令賢私過光。光雅恭謹。知上欲尊寵賢，及聞賢當來也，光警戒衣冠出門待，望見賢車乃卻入。賢至中門，光入閤，既下車，乃出拜謁，送迎甚謹，不敢以賓客均敵之禮。賢歸，上聞之喜，立拜光兩兄子為諫大夫常侍。賢繇是權與人主侔矣。〔一〕","sentenceOrder":140},
  {"id":"s_work_han_thu_107_141","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「侔，等也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_107_142","chapterId":"ch_work_han_thu_107","textTraditional":"是時，成帝外家王氏衰廢，唯平阿侯譚子去疾，哀帝為太子時為庶子得幸，及即位，為侍中騎都尉。上以王氏亡在位者，遂用舊恩親近去疾，復進其弟閎為中常侍。閎妻父蕭咸，前將軍望之子也，久為郡守，病免，為中郎將。兄弟並列，賢父恭慕之，欲與結婚姻。閎為賢弟駙馬都尉寬信求咸女為婦，咸惶恐不敢當，私謂閎曰：「董公為大司馬，冊文言『允執其中』，此乃堯禪舜之文，非三公故事，長老見者，莫不心懼。此豈家人子所能堪邪！」〔一〕閎性有知略，聞咸言，心亦悟。乃還報恭，深達咸自謙薄之意。恭歎曰：「我家何用負天下，而為人所畏如是！」意不說。〔二〕後上置酒麒麟殿，〔三〕賢父子親屬宴飲，王閎兄弟侍中中常侍皆在側。上有酒所，〔四〕從容視賢笑，〔五〕曰：「吾欲法堯禪舜，何如？」閎進曰：「天下乃高皇帝天下，非陛下之有也。陛下承宗廟，當傳子孫於亡窮。統業至重，天子亡戲言！」上默然不說，〔六〕左右皆恐。於是遣閎出，後不得復侍宴。","sentenceOrder":142},
  {"id":"s_work_han_thu_107_143","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「家人猶言庶人也，蓋咸自謂。」","sentenceOrder":143},
  {"id":"s_work_han_thu_107_144","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":144},
  {"id":"s_work_han_thu_107_145","chapterId":"ch_work_han_thu_107","textTraditional":"〔三〕　師古曰：「在未央宮。」","sentenceOrder":145},
  {"id":"s_work_han_thu_107_146","chapterId":"ch_work_han_thu_107","textTraditional":"〔四〕　師古曰：「言酒在體中。」","sentenceOrder":146},
  {"id":"s_work_han_thu_107_147","chapterId":"ch_work_han_thu_107","textTraditional":"〔五〕　師古曰：「從音千容反。」","sentenceOrder":147},
  {"id":"s_work_han_thu_107_148","chapterId":"ch_work_han_thu_107","textTraditional":"〔六〕　師古曰：「說讀曰悅。」","sentenceOrder":148},
  {"id":"s_work_han_thu_107_149","chapterId":"ch_work_han_thu_107","textTraditional":"賢第新成，功堅，〔一〕其外大門無故自壞，賢心惡之。後數月，哀帝崩。太皇太后召大司馬賢，引見東廂，問以喪事調度。賢內憂，不能對，免冠謝。太后曰：「新都侯莽前以大司馬奉送先帝大行，曉習故事，吾令莽佐君。」賢頓首幸甚。太后遣使者召莽。既至，以太后指使尚書劾賢帝病不親醫藥，禁止賢不得入出宮殿司馬中。賢不知所為，詣闕免冠徒跣謝。莽使謁者以太后詔即闕下冊賢〔二〕曰：「間者以來，陰陽不調，菑害並臻，〔三〕元元蒙辜。〔四〕夫三公，鼎足之輔也，高安侯賢未更事理，〔五〕為大司馬不合眾心，非所以折衝綏遠也。其收大司馬印綬，罷歸第。」即日賢與妻皆自殺，家惶恐夜葬。莽疑其詐死，有司奏請發賢棺，至獄診視。〔六〕莽復風大司徒光奏「賢〔七〕質性巧佞，翼姦以獲封侯，〔八〕父子專朝，兄弟並寵，多受賞賜，治第宅，遠冢壙，放效無極，不異王制，〔九〕費以萬萬計，國家為空虛。父子驕蹇。至不為使者禮，〔一０〕受賜不拜，罪惡暴著。賢自殺伏辜，死後父恭等不悔過，乃復以沙畫棺〔一一〕四時之色，左蒼龍，右白虎，上著金銀日月，玉衣珠璧以棺，〔一二〕至尊無以加。恭等幸得免於誅，不宜在中土。臣請收沒入財物縣官。諸以賢為官者皆免。」父恭、弟寬信與家屬徙合浦，母別歸故郡鉅鹿。長安中小民讙譁，鄉其弟哭，幾獲盜之。〔一三〕縣官斥賣董氏財凡四十三萬萬。賢既見發，臝診其尸，〔一四〕因埋獄中。","sentenceOrder":149},
  {"id":"s_work_han_thu_107_150","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「言盡功力而作之，極堅牢也。功字或作攻。攻，治也，言作治之甚堅牢。」","sentenceOrder":150},
  {"id":"s_work_han_thu_107_151","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「即，就也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_107_152","chapterId":"ch_work_han_thu_107","textTraditional":"〔三〕　師古曰：「菑，古災字。」","sentenceOrder":152},
  {"id":"s_work_han_thu_107_153","chapterId":"ch_work_han_thu_107","textTraditional":"〔四〕　師古曰：「蒙，被也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_107_154","chapterId":"ch_work_han_thu_107","textTraditional":"〔五〕　師古曰：「更，歷也，音工衡反。」","sentenceOrder":154},
  {"id":"s_work_han_thu_107_155","chapterId":"ch_work_han_thu_107","textTraditional":"〔六〕　師古曰：「謂發冢取其棺柩也。診，驗也，音軫。」","sentenceOrder":155},
  {"id":"s_work_han_thu_107_156","chapterId":"ch_work_han_thu_107","textTraditional":"〔七〕　師古曰：「風讀曰諷。光，孔光也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_107_157","chapterId":"ch_work_han_thu_107","textTraditional":"〔八〕　師古曰：「翼，進也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_107_158","chapterId":"ch_work_han_thu_107","textTraditional":"〔九〕　師古曰：「放，依也，音甫往反。」","sentenceOrder":158},
  {"id":"s_work_han_thu_107_159","chapterId":"ch_work_han_thu_107","textTraditional":"〔一０〕師古曰：「言不敬天子之使。」","sentenceOrder":159},
  {"id":"s_work_han_thu_107_160","chapterId":"ch_work_han_thu_107","textTraditional":"〔一一〕師古曰：「以朱砂塗之，而又雕畫也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_107_161","chapterId":"ch_work_han_thu_107","textTraditional":"〔一二〕師古曰：「以此物棺斂也。棺音工喚反。」","sentenceOrder":161},
  {"id":"s_work_han_thu_107_162","chapterId":"ch_work_han_thu_107","textTraditional":"〔一三〕師古曰：「陽往哭之，實欲竊盜也。鄉讀曰嚮。幾讀曰冀。」","sentenceOrder":162},
  {"id":"s_work_han_thu_107_163","chapterId":"ch_work_han_thu_107","textTraditional":"〔一四〕師古曰：「臝，露形也，音郎果反。」","sentenceOrder":163},
  {"id":"s_work_han_thu_107_164","chapterId":"ch_work_han_thu_107","textTraditional":"賢所厚吏沛朱詡自劾去大司馬府，買棺衣收賢尸葬之。王莽聞之而大怒，以它罪擊殺詡。詡子浮建武中貴顯，至大司馬，司空，封侯。而王閎王莽時為牧守，所居見紀，莽敗乃去官。世祖下詔曰：「武王克殷，表商容之閭。〔一〕閎修善謹敕，兵起，吏民獨不爭其頭首。今以閎子補吏。」至墨綬率官，蕭咸外孫云。","sentenceOrder":164},
  {"id":"s_work_han_thu_107_165","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「商容，殷賢人。」","sentenceOrder":165},
  {"id":"s_work_han_thu_107_166","chapterId":"ch_work_han_thu_107","textTraditional":"贊曰：柔曼之傾意，〔一〕非獨女德，蓋亦有男色焉。觀籍、閎、鄧、韓之徒非一，而董賢之寵尤盛，父子並為公卿，可謂貴重人臣無二矣。然進不繇道，〔二〕位過其任，莫能有終，所謂愛之適足以害之者也。漢世衰於元、成，壞於哀、平。哀、平之際，國多釁矣。〔三〕主疾無嗣，弄臣為輔，鼎足不彊，棟幹微撓。〔四〕一朝帝崩，姦臣擅命，董賢縊死，丁、傅流放，辜及母后，奪位幽廢，〔五〕咎在親便嬖，所任非仁賢。故仲尼著「損者三友」，〔六〕王者不私人以官，殆為此也。〔七〕","sentenceOrder":166},
  {"id":"s_work_han_thu_107_167","chapterId":"ch_work_han_thu_107","textTraditional":"〔一〕　師古曰：「曼，澤也，言其質柔而色理光澤也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_107_168","chapterId":"ch_work_han_thu_107","textTraditional":"〔二〕　師古曰：「言本不以德進。繇讀與由同。」","sentenceOrder":168},
  {"id":"s_work_han_thu_107_169","chapterId":"ch_work_han_thu_107","textTraditional":"〔三〕　師古曰：「釁謂間隙也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_107_170","chapterId":"ch_work_han_thu_107","textTraditional":"〔四〕　師古曰：「撓，弱也，音女教反。」","sentenceOrder":170},
  {"id":"s_work_han_thu_107_171","chapterId":"ch_work_han_thu_107","textTraditional":"〔五〕　師古曰：「謂貶皇太后趙氏為孝成皇后，退居北宮，哀皇后傅氏退居桂宮。」","sentenceOrder":171},
  {"id":"s_work_han_thu_107_172","chapterId":"ch_work_han_thu_107","textTraditional":"〔六〕　師古曰：「論語稱孔子曰『損者三友：友便辟，友善柔，友便佞，損矣。』」","sentenceOrder":172},
  {"id":"s_work_han_thu_107_173","chapterId":"ch_work_han_thu_107","textTraditional":"〔七〕　師古曰：「殆，近也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_107_174","chapterId":"ch_work_han_thu_107","textTraditional":"校勘記","sentenceOrder":174},
  {"id":"s_work_han_thu_107_175","chapterId":"ch_work_han_thu_107","textTraditional":"三七二三頁一０行　太子（嗽）〔齰〕癰而色難之。已而聞通嘗為上齰〔之〕，　景祐、殿本「嗽」作「齰」，下「齰」字下有「之」字。","sentenceOrder":175},
  {"id":"s_work_han_thu_107_176","chapterId":"ch_work_han_thu_107","textTraditional":"三七二三頁一六行　遂竟案，〔二〕　注〔二〕原在「遂」字下。劉攽說，「遂」字屬下句。王先謙說劉說是。","sentenceOrder":176},
  {"id":"s_work_han_thu_107_177","chapterId":"ch_work_han_thu_107","textTraditional":"三七三一頁　八行　初，許皇〔后〕坐執左道　景祐、殿、局本都有「后」字，此脫。","sentenceOrder":177},
  {"id":"s_work_han_thu_107_178","chapterId":"ch_work_han_thu_107","textTraditional":"三七三二頁一三行　徙其家屬〔歸〕故郡。　景祐、殿本有「歸」字。王先謙說有「歸」字是。","sentenceOrder":178},
  {"id":"s_work_han_thu_107_179","chapterId":"ch_work_han_thu_107","textTraditional":"三七三三頁一０行　（嘗）〔常〕留中視醫藥。　景祐、殿本都作「常」。王先謙說作「常」是。","sentenceOrder":179},
  {"id":"s_work_han_thu_107_180","chapterId":"ch_work_han_thu_107","textTraditional":"三七三三頁一一行　又（詔）〔召〕賢女弟以為昭儀，　景祐、殿本都作「召」。楊樹達說作「召」是。","sentenceOrder":180},
  {"id":"s_work_han_thu_108_1","chapterId":"ch_work_han_thu_108","textTraditional":"匈奴，其先夏后氏之苗裔，曰淳維。〔一〕唐虞以上有山戎、獫允、薰粥，〔二〕居于北邊，隨草畜牧而轉移。其畜之所多則馬、牛、羊，其奇畜則橐佗、驢、驘、駃騠、騊駼、驒奚。〔三〕逐水草遷徙，無城郭常居耕田之業，然亦各有分地。〔四〕無文書，以言語為約束。兒能騎羊，引弓射鳥鼠，〔五〕少長則射狐菟，〔六〕肉食。〔七〕士力能彎弓，盡為甲騎。其俗，寬則隨畜田獵禽獸為生業，急則人習戰攻以侵伐，〔八〕其天性也。其長兵則弓矢，短兵則刀鋋。〔九〕利則進，不利則退，不羞遁走。苟利所在，不知禮義。自君王以下咸食畜肉，衣其皮革，被旃裘。壯者食肥美，老者飲食其餘。貴壯健，賤老弱。父死，妻其後母；兄弟死，皆取其妻妻之。其俗有名不諱而無字。","sentenceOrder":1},
  {"id":"s_work_han_thu_108_2","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「以殷時始奔北邊。」","sentenceOrder":2},
  {"id":"s_work_han_thu_108_3","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「皆匈奴別號。獫音險。粥音（戈）〔弋〕六反。」","sentenceOrder":3},
  {"id":"s_work_han_thu_108_4","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「橐佗，言能負橐囊而馱物也。驘，驢種而馬生也。駃騠，俊馬也，生七日而超其母。騊駼，馬類也。生北海。驒奚，駏驉類也。佗音徒何反。駃音決。騠音提。騊音桃。駼音塗。驒音顛。」","sentenceOrder":4},
  {"id":"s_work_han_thu_108_5","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「分音扶問反。其下亦同。」","sentenceOrder":5},
  {"id":"s_work_han_thu_108_6","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「言其幼小則能射。」","sentenceOrder":6},
  {"id":"s_work_han_thu_108_7","chapterId":"ch_work_han_thu_108","textTraditional":"〔六〕　師古曰：「少長言漸大。」","sentenceOrder":7},
  {"id":"s_work_han_thu_108_8","chapterId":"ch_work_han_thu_108","textTraditional":"〔七〕　師古曰：「言無米粟，唯食肉。」","sentenceOrder":8},
  {"id":"s_work_han_thu_108_9","chapterId":"ch_work_han_thu_108","textTraditional":"〔八〕　師古曰：「人人皆習之。」","sentenceOrder":9},
  {"id":"s_work_han_thu_108_10","chapterId":"ch_work_han_thu_108","textTraditional":"〔九〕　師古曰：「鋋，鐵把小矛也，音蟬。」","sentenceOrder":10},
  {"id":"s_work_han_thu_108_11","chapterId":"ch_work_han_thu_108","textTraditional":"夏道衰，而公劉失其稷官，變于西戎，〔一〕邑于豳。〔二〕其後三百有餘歲，戎狄攻太王亶父，〔三〕亶父亡走于岐下，〔四〕豳人悉從亶父而邑焉，作周。〔五〕其後百有餘歲，周西伯昌伐畎夷。〔六〕後十有餘年，武王伐紂而營雒邑，復居于酆鎬，放逐戎夷涇、洛之北，〔七〕以時入貢，名曰荒服。其後二百有餘年，周道衰，而周穆王伐畎戎，〔八〕得四白狼四白鹿以歸。自是之後，荒服不至。於是作呂刑之辟。〔九〕至穆王之孫懿王時，王室遂衰，戎狄交侵，暴虐中國。中國被其苦，詩人始作，疾而歌之，曰：「靡室靡家，獫允之故；」「豈不日戒，獫允孔棘。」〔一０〕至懿王曾孫宣王，興師命將以征伐之，詩人美大其功，曰：「薄伐獫狁，至於太原；〔一一〕」「出車彭彭」，「城彼朔方。」〔一二〕是時四夷賓服，稱為中興。","sentenceOrder":11},
  {"id":"s_work_han_thu_108_12","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「公劉，后稷之曾孫也。變，化也，謂行化於其俗。」","sentenceOrder":12},
  {"id":"s_work_han_thu_108_13","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「即今之豳州是其地也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_108_14","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「自公劉至亶父凡九君也。父讀曰甫。」","sentenceOrder":14},
  {"id":"s_work_han_thu_108_15","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「岐山之下。」","sentenceOrder":15},
  {"id":"s_work_han_thu_108_16","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「始作周國也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_108_17","chapterId":"ch_work_han_thu_108","textTraditional":"〔六〕　師古曰：「西伯昌即文王也。畎音工犬反。畎夷即畎戎也，又曰昆夷。昆字或作混，又作緄，二字並音工本反。昆、緄、畎聲相近耳。亦曰犬戎也。山海經云：『黃帝生苗龍，苗龍生融吾，融吾生弄明，弄明生白犬。白犬有二，牝牡，為犬戎。』許氏說文解字曰『赤狄本犬種也』，故字從犬。」","sentenceOrder":17},
  {"id":"s_work_han_thu_108_18","chapterId":"ch_work_han_thu_108","textTraditional":"〔七〕　師古曰：「此洛即漆沮水也，本出上郡雕陰泰冒山，而東南入于渭。」","sentenceOrder":18},
  {"id":"s_work_han_thu_108_19","chapterId":"ch_work_han_thu_108","textTraditional":"〔八〕　師古曰：「穆王，成王孫，康王子也。」","sentenceOrder":19},
  {"id":"s_work_han_thu_108_20","chapterId":"ch_work_han_thu_108","textTraditional":"〔九〕　師古曰：「即尚書呂刑篇是也。辟，法也，音闢。」","sentenceOrder":20},
  {"id":"s_work_han_thu_108_21","chapterId":"ch_work_han_thu_108","textTraditional":"〔一０〕師古曰：「小雅采薇之詩也。孔，甚也。棘，急也。言征役踰時，靡有室家夫婦之道者，以有獫允之難故也。豈不日日相警戒乎？獫允之難甚急。」","sentenceOrder":21},
  {"id":"s_work_han_thu_108_22","chapterId":"ch_work_han_thu_108","textTraditional":"〔一一〕師古曰：「小雅六月之詩也。薄伐，言逐出也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_108_23","chapterId":"ch_work_han_thu_108","textTraditional":"〔一二〕師古曰：「小雅出車之詩也。彭彭，盛也。朔方，北方也。言獫允既去，北方安靜，乃築城以守。」","sentenceOrder":23},
  {"id":"s_work_han_thu_108_24","chapterId":"ch_work_han_thu_108","textTraditional":"至于幽王，用寵姬褒姒之故，與申（后）〔侯〕有隙。〔一〕申侯怒而與畎戎共攻殺幽王于麗山之下，〔二〕遂取周之地，鹵獲而居于涇渭之間，侵暴中國。秦襄公救周，於是周平王去酆鎬而東徙于雒邑。〔三〕當時秦襄公伐戎至廄，〔四〕始列為諸侯。後六十有五年，而山戎越燕而伐齊，齊釐公與戰于齊郊。〔五〕後四十四年，而山戎伐燕。燕告急齊，齊桓公北伐山戎，山戎走。後二十餘年，而戎翟至雒邑，伐周襄王，〔六〕襄王出奔于鄭之氾邑。〔七〕初，襄王欲伐鄭，故取翟女為后，與翟共伐鄭。已而黜翟后，翟后怨，而襄王繼母曰惠后，有子帶，欲立之，於是惠后與翟后、子帶為內應，開戎翟，戎翟以故得入，破逐襄王，而立子帶為王。於是戎翟或居於陸渾，〔八〕東至于衛，侵盜尤甚。周襄王既居外四年，乃使使告急於晉。晉文公初立，欲修霸業，乃興師伐戎翟，誅子帶，迎內襄王于洛邑。","sentenceOrder":24},
  {"id":"s_work_han_thu_108_25","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「幽王，宣王之子。」","sentenceOrder":25},
  {"id":"s_work_han_thu_108_26","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「麗讀曰驪。」","sentenceOrder":26},
  {"id":"s_work_han_thu_108_27","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「平王，幽王之子。」","sentenceOrder":27},
  {"id":"s_work_han_thu_108_28","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「廄，古岐字。」","sentenceOrder":28},
  {"id":"s_work_han_thu_108_29","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「釐讀曰僖。」","sentenceOrder":29},
  {"id":"s_work_han_thu_108_30","chapterId":"ch_work_han_thu_108","textTraditional":"〔六〕　師古曰：「襄王，惠王之子。」","sentenceOrder":30},
  {"id":"s_work_han_thu_108_31","chapterId":"ch_work_han_thu_108","textTraditional":"〔七〕　蘇林曰：「氾音凡，今潁川襄城是也。」師古曰：「以襄王嘗處之，因號襄城。」","sentenceOrder":31},
  {"id":"s_work_han_thu_108_32","chapterId":"ch_work_han_thu_108","textTraditional":"〔八〕　師古曰：「今伊闕南陸渾山川是其地。」","sentenceOrder":32},
  {"id":"s_work_han_thu_108_33","chapterId":"ch_work_han_thu_108","textTraditional":"當是時，秦晉為強國。晉文公攘戎翟，居于西河圜、洛之間〔一〕，號曰赤翟、白翟。〔二〕而秦穆公得由余，西戎八國服於秦。故隴以西有綿諸、畎戎、狄獂之戎，〔三〕在岐、梁、涇、漆之北有義渠、大荔、烏氏、朐衍之戎，〔四〕而晉北有林胡、樓煩之戎，燕北有東胡、山戎。〔五〕各分散谿谷，自有君長，往往而聚者百有餘戎，然莫能相壹。","sentenceOrder":33},
  {"id":"s_work_han_thu_108_34","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　晉灼曰：「圜音嚚。三倉作圁。地理志『圜水出上郡白土縣西，東流入河。」師古曰：「圜水即今銀州銀水是也。書本作圁，晉說是也。後轉寫者誤為圜耳。洛水亦謂漆沮。」","sentenceOrder":34},
  {"id":"s_work_han_thu_108_35","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「春秋所書晉師滅赤狄潞氏，郤缺獲白狄子者。」","sentenceOrder":35},
  {"id":"s_work_han_thu_108_36","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「皆在天水界，即綿諸道及貆道是也。獂音（完）〔桓〕。」","sentenceOrder":36},
  {"id":"s_work_han_thu_108_37","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「此漆水在新平。荔音隸。氏音支。朐音許于反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_108_38","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　服虔曰：「烏桓之先也，後為鮮卑。」","sentenceOrder":38},
  {"id":"s_work_han_thu_108_39","chapterId":"ch_work_han_thu_108","textTraditional":"自是之後百有餘年，晉悼公使魏絳和戎翟，戎翟朝晉。後百有餘年，趙襄子踰句注而破之，并代以臨胡貉。〔一〕後與韓魏共滅知伯，分晉地而有之，則趙有代、句注以北，而魏有西河、上郡，以與戎界邊。其後，義渠之戎築城郭以自守，而秦稍蠶食之，至於惠王，遂拔義渠二十五城。惠王伐魏，魏盡入西河及上郡于秦。秦昭王時，義渠戎王與宣太后亂，有二子。〔二〕宣太后詐而殺義渠戎王於甘泉，遂起兵伐滅義渠。於是秦有隴西、北地、上郡，築長城以距胡。而趙武靈王亦變俗胡服，習騎射，北破林胡、樓煩，自代並陰山下至高闕為塞，〔三〕而置雲中、雁門、代郡。其後燕有賢將秦開，為質於胡，胡甚信之。歸而襲破東胡，〔東胡〕卻千餘里。〔四〕與荊軻刺秦王秦舞陽者，開之孫也。燕亦築長城，自造陽至襄平，〔五〕置上谷、漁陽、右北平、遼西、遼東郡以距胡。當是時，冠帶戰國七，而三國邊於匈奴。〔六〕其後趙將李牧時，匈奴不敢入趙邊。後秦滅六國，而始皇帝使蒙恬將數十萬之（物）〔眾〕北擊胡，悉收河南地，因河為塞，築四十四縣城臨河，徙適戍以充之。〔七〕而通直道，自九原至雲陽，因邊山險，塹谿谷，可繕者繕之，〔八〕起臨洮至遼東萬餘里。又度河據陽山北假中。〔九〕","sentenceOrder":39},
  {"id":"s_work_han_thu_108_40","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「貉音莫伯反。」","sentenceOrder":40},
  {"id":"s_work_han_thu_108_41","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「即昭王母也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_108_42","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「並音步浪反。高闕，解在衛青霍去病傳。」","sentenceOrder":42},
  {"id":"s_work_han_thu_108_43","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「卻，退也，音丘略反。」","sentenceOrder":43},
  {"id":"s_work_han_thu_108_44","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「造陽，地名，在上谷界。襄平即遼東所治也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_108_45","chapterId":"ch_work_han_thu_108","textTraditional":"〔六〕　如淳曰：「燕、趙、秦。」","sentenceOrder":45},
  {"id":"s_work_han_thu_108_46","chapterId":"ch_work_han_thu_108","textTraditional":"〔七〕　師古曰：「適讀曰謫。有罪謫合徙戍者，令徙居之。」","sentenceOrder":46},
  {"id":"s_work_han_thu_108_47","chapterId":"ch_work_han_thu_108","textTraditional":"〔八〕　師古曰：「繕，補也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_108_48","chapterId":"ch_work_han_thu_108","textTraditional":"〔九〕　師古曰：「北假，地名。」","sentenceOrder":48},
  {"id":"s_work_han_thu_108_49","chapterId":"ch_work_han_thu_108","textTraditional":"當是時，東胡強而月氏盛。〔一〕匈奴單于曰頭曼，〔二〕頭曼不勝秦，北徙。十有餘年而蒙恬死，諸侯畔秦，中國擾亂，諸秦所徙適邊者皆復去，〔三〕於是匈奴得寬，復稍度河南與中國界於故塞。","sentenceOrder":49},
  {"id":"s_work_han_thu_108_50","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「氏音支。」","sentenceOrder":50},
  {"id":"s_work_han_thu_108_51","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「曼音莫安反。」","sentenceOrder":51},
  {"id":"s_work_han_thu_108_52","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「適音謫。」","sentenceOrder":52},
  {"id":"s_work_han_thu_108_53","chapterId":"ch_work_han_thu_108","textTraditional":"單于有太子，名曰冒頓。後有愛閼氏，生少子，〔一〕頭曼欲廢冒頓而立少子，乃使冒頓質於月氏。冒頓既質，而頭曼急擊月氏。月氏欲殺冒頓，冒頓盜其善馬，騎亡歸。頭曼以為壯，令將萬騎。冒頓乃作鳴鏑，〔二〕習勒其騎射，〔三〕令曰：「鳴鏑所射而不悉射者斬。」行獵獸，有不射鳴鏑所射輒斬之。已而，冒頓以鳴鏑自射善馬，左右或莫敢射，冒頓立斬之。居頃之，復以鳴鏑自射其愛妻，左右或頗恐，不敢射，復斬之。頃之，冒頓出獵，以鳴鏑射單于善馬，左右皆射之。於是冒頓知其左右可用，從其父單于頭曼獵，以鳴鏑射頭曼，其左右皆隨鳴鏑而射殺頭曼，盡誅其後母與弟及大臣不聽從者。於是冒頓自立為單于。","sentenceOrder":53},
  {"id":"s_work_han_thu_108_54","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「閼氏，匈奴皇后號也。閼音於連反。氏音支。」","sentenceOrder":54},
  {"id":"s_work_han_thu_108_55","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　應劭曰：「髐箭也。」師古曰：「鏑音嫡。髐音呼交反。」","sentenceOrder":55},
  {"id":"s_work_han_thu_108_56","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「勒其所部騎，皆習射也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_108_57","chapterId":"ch_work_han_thu_108","textTraditional":"冒頓既立，時東胡強，聞冒頓殺父自立，乃使使謂冒頓曰：「欲得頭曼時號千里馬。」冒頓問群臣，群臣皆曰：「此匈奴寶馬也，勿予。」冒頓曰：「奈何與人鄰國愛一馬乎？」遂與之。頃之，東胡以為冒頓畏之，使使謂冒頓曰：「欲得單于一閼氏。」冒頓復問左右，左右皆怒曰：「東胡無道，乃求閼氏！請擊之。」冒頓曰：「奈何與人鄰國愛一女子乎？」遂取所愛閼氏予東胡。東胡王愈驕，西侵。與匈奴中間有棄地莫居千餘里，各居其邊為甌脫。〔一〕東胡使使謂冒頓曰：「匈奴所與我界甌脫外棄地，匈奴不能至也，吾欲有之。」冒頓問群臣，或曰：「此棄地，予之。」於是冒頓大怒，曰：「地者，國之本也，奈何予人！」諸言與者，皆斬之。冒頓上馬，令國中有後者斬，遂東襲擊東胡。東胡初輕冒頓，不為備。及冒頓以兵至，大破滅東胡王，虜其民眾畜產。既歸，西擊走月氏，南并樓煩、白羊河南王，〔二〕悉復收秦所使蒙恬所奪匈奴地者，與漢關故河南塞，至朝那、膚施，〔三〕遂侵燕、代。是時漢方與項羽相距，中國罷於兵革，〔四〕以故冒頓得自強，控弦之士三十餘萬。〔五〕","sentenceOrder":57},
  {"id":"s_work_han_thu_108_58","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　服虔曰：「甌脫，作土室以伺也。」師古曰：「境上候望之處，若今之伏宿（處）〔舍〕也。甌音一侯反。脫音土活反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_108_59","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「二王之居在河南。」","sentenceOrder":59},
  {"id":"s_work_han_thu_108_60","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「朝那屬安定。膚施屬上郡。」","sentenceOrder":60},
  {"id":"s_work_han_thu_108_61","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「罷讀曰疲。」","sentenceOrder":61},
  {"id":"s_work_han_thu_108_62","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「控，引也。控弦，言能引弓者。」","sentenceOrder":62},
  {"id":"s_work_han_thu_108_63","chapterId":"ch_work_han_thu_108","textTraditional":"自淳維以至頭曼千有餘歲，時大時小，別散分離，尚矣，〔一〕其世傳不可得而次。然至冒頓，而匈奴最強大，盡服從北夷，而南與諸夏為敵國，其世（信）〔姓〕官號可得而記云。","sentenceOrder":63},
  {"id":"s_work_han_thu_108_64","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「尚，久遠。」","sentenceOrder":64},
  {"id":"s_work_han_thu_108_65","chapterId":"ch_work_han_thu_108","textTraditional":"單于姓攣鞮氏，〔一〕其國稱之曰「撐犁孤塗單于」。〔二〕匈奴謂天為「撐犁」，謂子為「孤塗」，單于者，廣大之貌也，言其象天單于然也。置左右賢王，左右谷蠡，〔三〕左右大將，左右大都尉，左右大當戶，左右骨都侯。匈奴謂賢曰「屠耆」，故常以太子為左屠耆王。自左右賢王以下至當戶，大者萬餘騎，小者數千，凡二十四長，立號曰「萬騎」。其大臣皆世官。呼衍氏，蘭氏，〔四〕其後有須卜氏，此三姓，其貴種也。諸左王將居東方，直上谷以東，〔五〕接穢貉、朝鮮；右王將居西方，直上郡以西，接氐、羌；而單于庭直代、雲中。各有分地，逐水草移徙。而左右賢王、左右谷蠡最大國，左右骨都侯輔政。諸二十四長，亦各自置千長、百長、什長、裨小王、〔六〕相、都尉、當戶、且渠之屬。〔七〕","sentenceOrder":65},
  {"id":"s_work_han_thu_108_66","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「攣音力全反。鞮音丁奚反。」","sentenceOrder":66},
  {"id":"s_work_han_thu_108_67","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　蘇林曰：「撐音牚距之牚。」師古曰：「音丈庚反。」","sentenceOrder":67},
  {"id":"s_work_han_thu_108_68","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「谷音鹿。蠡音盧奚反。」","sentenceOrder":68},
  {"id":"s_work_han_thu_108_69","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「呼衍，即今鮮卑姓呼延者是也。蘭姓今亦有之。」","sentenceOrder":69},
  {"id":"s_work_han_thu_108_70","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「直，當也。其下亦同也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_108_71","chapterId":"ch_work_han_thu_108","textTraditional":"〔六〕　師古曰：「裨音頻移反。」","sentenceOrder":71},
  {"id":"s_work_han_thu_108_72","chapterId":"ch_work_han_thu_108","textTraditional":"〔七〕　師古曰：「且音子餘反。今之沮渠姓，蓋本因此官。」","sentenceOrder":72},
  {"id":"s_work_han_thu_108_73","chapterId":"ch_work_han_thu_108","textTraditional":"歲正月，諸長小會單于庭，祠。五月，大會龍城，祭其先、天地、鬼神。秋，馬肥，大會蹛林，課校人畜計。〔一〕其法，拔刃尺者死，坐盜者沒入其家；有罪，小者軋，〔二〕大者死。獄久者不滿十日，一國之囚不過數人。而單于朝出營，拜日之始生，夕拜月。其坐，長左而北向。〔三〕日上戊已。其送死，有棺槨金銀衣裳，而無封樹喪服；近幸臣妾從死者，多至數十百人。〔四〕舉事常隨月，盛壯以攻戰，月虧則退兵。其攻戰，斬首虜賜一卮酒，而所得鹵獲因以予之，得人以為奴婢。故其戰，人人自為趨利，〔五〕善為誘兵以包敵。〔六〕故其逐利，如鳥之集；其困敗，瓦解雲散矣。戰而扶轝死者，盡得死者家財。","sentenceOrder":73},
  {"id":"s_work_han_thu_108_74","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　服虔曰：「蹛音帶，匈奴秋社八月中皆會祭處也。」師古曰：「蹛者，繞林木而祭也。鮮卑之俗，自古相傳，秋天之祭，無林木者尚豎柳枝，眾騎馳遶三周乃止。此其遺法。計者，人畜之數。」","sentenceOrder":74},
  {"id":"s_work_han_thu_108_75","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　服虔曰：「刃刻其面也。」如淳曰：「軋，檛杖也。」師古曰：「二說皆非也。軋謂輾轢其骨節，若今之厭踝者也。軋音於黠反。輾音女展反。」","sentenceOrder":75},
  {"id":"s_work_han_thu_108_76","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「左者，以左為尊。」","sentenceOrder":76},
  {"id":"s_work_han_thu_108_77","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「或數十人，或百人。」","sentenceOrder":77},
  {"id":"s_work_han_thu_108_78","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「趨讀曰趣。趣，向也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_108_79","chapterId":"ch_work_han_thu_108","textTraditional":"〔六〕　師古曰：「包裹取之。」","sentenceOrder":79},
  {"id":"s_work_han_thu_108_80","chapterId":"ch_work_han_thu_108","textTraditional":"後北服渾窳、屈射、丁零、隔昆、（龍）新{艹犁}之國。〔一〕於是匈奴貴人大臣皆服，以冒頓為賢。","sentenceOrder":80},
  {"id":"s_work_han_thu_108_81","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「五小國也。渾音胡昆反。窳音（戈）〔弋〕主反。{艹犁}音犁。」","sentenceOrder":81},
  {"id":"s_work_han_thu_108_82","chapterId":"ch_work_han_thu_108","textTraditional":"是時，漢初定，徙韓王信於代，都馬邑。匈奴大攻圍馬邑，韓信降匈奴。匈奴得信，因引兵南踰句注，攻太原，至晉陽下。高帝自將兵往擊之。會冬大寒雨雪，〔一〕卒之墮指者十二三，於是冒頓陽敗走，誘漢兵。漢兵逐擊冒頓，冒頓匿其精兵，見其羸弱，於是漢悉兵，多步兵，三十二萬，北逐之。高帝先至平城，步兵未盡到，冒頓縱精兵三十餘萬騎圍高帝於白登，七日，〔二〕漢兵中外不得相救餉。匈奴騎，其西方盡白，東方盡駹，北方盡驪，南方盡騂馬。〔三〕高帝乃使使間厚遺閼氏，〔四〕閼氏乃謂冒頓曰：「兩主不相困。今得漢地，單于終非能居之。且漢主有神，單于察之。」冒頓與韓信將王黃、趙利期，而兵久不來，疑其與漢有謀，亦取閼氏之言，乃開圍一角。於是高皇帝令士皆持滿傅矢外鄉，從解角直出，〔五〕得與大軍合，而冒頓遂引兵去。漢亦引兵罷，使劉敬結和親之約。","sentenceOrder":82},
  {"id":"s_work_han_thu_108_83","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「雨音于具反。」","sentenceOrder":83},
  {"id":"s_work_han_thu_108_84","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「白登在平城東南，去平城十餘里。」","sentenceOrder":84},
  {"id":"s_work_han_thu_108_85","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「駹，青馬也。驪，深黑；騂，赤馬也。駹音尨。騂音先營反。」","sentenceOrder":85},
  {"id":"s_work_han_thu_108_86","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「求間隙而私遺之。」","sentenceOrder":86},
  {"id":"s_work_han_thu_108_87","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「傅讀曰附。鄉讀曰嚮。言滿引弓弩注矢外捍，從解圍之隅（直角）〔角直〕以出去。」","sentenceOrder":87},
  {"id":"s_work_han_thu_108_88","chapterId":"ch_work_han_thu_108","textTraditional":"是後韓信為匈奴將，及趙利、王黃等數背約，侵盜代、鴈門、雲中。居無幾何，陳豨反，〔一〕與韓信合謀擊代。漢使樊噲往擊之，復收代、鴈門、雲中郡縣，不出塞。是時匈奴以漢將數率眾往降〔二〕，故冒頓常往來侵盜代地。於是高祖患之，乃使劉敬奉宗室女翁主為單于閼氏，〔三〕歲奉匈奴絮繒酒食物各有數，約為兄弟以和親，冒頓乃少止。後燕王盧綰復反，率其黨且萬人降匈奴，往來苦上谷以東，終高祖世。","sentenceOrder":88},
  {"id":"s_work_han_thu_108_89","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「無幾何，言無多時也。幾音居豈反。」","sentenceOrder":89},
  {"id":"s_work_han_thu_108_90","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「即謂韓信、陳豨之屬耳。」","sentenceOrder":90},
  {"id":"s_work_han_thu_108_91","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「諸王女曰翁主者，言其父自主婚。」","sentenceOrder":91},
  {"id":"s_work_han_thu_108_92","chapterId":"ch_work_han_thu_108","textTraditional":"孝惠、高后時，冒頓寖驕，〔一〕乃為書，使使遺高后曰：「孤僨之君，〔二〕生於沮澤之中，〔三〕長於平野牛馬之域，數至邊境，願遊中國。陛下獨立，孤僨獨居。兩主不樂，無以自虞，〔四〕願以所有，易其所無。」高后大怒，召丞相平及樊噲、季布等，議斬其使者，發兵而擊之。樊噲曰：「臣願得十萬眾，橫行匈奴中。」問季布，布曰：「噲可斬也！前陳豨反於代，漢兵三十二萬，噲為上將軍，時匈奴圍高帝於平城，噲不能解圍。天下歌之曰：『平城之下亦誠苦！七日不食，不能彀弩。』〔五〕今歌吟之聲未絕，傷痍者甫起，〔六〕而噲欲搖動天下，妄言以十萬眾橫行，是面謾也。〔七〕且夷狄譬如禽獸，得其善言不足喜，惡言不足怒也。」高后曰：「善。」令大謁者張澤報書曰：「單于不忘弊邑，賜之以書，弊邑恐懼。退日自圖，〔八〕年老氣衰，髮齒墮落，行步失度，單于過聽，不足以自汙。〔九〕弊邑無罪，宜在見赦。竊有御車二乘，馬二駟，以奉常駕。」冒頓得書，復使使來謝曰：「未嘗聞中國禮義，陛下幸而赦之。」因獻馬，遂和親。","sentenceOrder":92},
  {"id":"s_work_han_thu_108_93","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「寖，漸也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_108_94","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　如淳曰：「僨，仆也。猶言不能自立也。」師古曰：「僨音方問反。」","sentenceOrder":94},
  {"id":"s_work_han_thu_108_95","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「沮，浸溼之地，音子豫反。」","sentenceOrder":95},
  {"id":"s_work_han_thu_108_96","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「虞與娛同。」","sentenceOrder":96},
  {"id":"s_work_han_thu_108_97","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「彀，張也，音工豆反。」","sentenceOrder":97},
  {"id":"s_work_han_thu_108_98","chapterId":"ch_work_han_thu_108","textTraditional":"〔六〕　師古曰：「唫，古吟字。痍，創也。甫，始也。痍音夷。」","sentenceOrder":98},
  {"id":"s_work_han_thu_108_99","chapterId":"ch_work_han_thu_108","textTraditional":"〔七〕　師古曰：「謾，欺誑也，音慢，又音莫連反。」","sentenceOrder":99},
  {"id":"s_work_han_thu_108_100","chapterId":"ch_work_han_thu_108","textTraditional":"〔八〕　師古曰：「圖，謀也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_108_101","chapterId":"ch_work_han_thu_108","textTraditional":"〔九〕　師古曰：「過，誤也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_108_102","chapterId":"ch_work_han_thu_108","textTraditional":"至孝文即位，復修和親。其三年夏，匈奴右賢王入居河南地為寇，於是文帝下詔曰：「漢與匈奴約為昆弟，無侵害邊境，所以輸遺匈奴甚厚。今右賢王離其國，將眾居河南地，非常故。〔一〕往來入塞，捕殺吏卒，敺侵上郡保塞蠻夷，令不得居其故。〔二〕陵轢邊吏，入盜，甚驁無道，〔三〕非約也。其發邊吏車騎八萬詣高奴，〔四〕遣丞相灌嬰將擊右賢王。」右賢王走出塞，文帝幸太原。是時，濟北王反，文帝歸，罷丞相擊胡之兵。","sentenceOrder":102},
  {"id":"s_work_han_thu_108_103","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「言異於常，非舊事。」","sentenceOrder":103},
  {"id":"s_work_han_thu_108_104","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「敺與驅同。保塞蠻夷，謂本來屬漢而居邊塞自保守。」","sentenceOrder":104},
  {"id":"s_work_han_thu_108_105","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「轢音來各反。驁與傲同。」","sentenceOrder":105},
  {"id":"s_work_han_thu_108_106","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「上郡之縣也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_108_107","chapterId":"ch_work_han_thu_108","textTraditional":"其明年，單于遺漢書曰：「天所立匈奴大單于敬問皇帝無恙。前時皇帝言和親事，稱書意合驩。〔一〕漢邊吏侵侮右賢王，右賢王不請，〔二〕聽後義盧侯難支等計，與漢吏相恨，絕二主之約，離昆弟之親。皇帝讓書再至，發使以書報，不來，漢使不至。〔三〕漢以其故不和，鄰國不附。今以少吏之敗約，〔四〕故罰右賢王，使至西方求月氏擊之。以天之福，吏卒良，馬力強，以滅夷月氏，〔五〕盡斬殺降下定之。樓蘭、烏孫、呼揭及其旁二十六國皆已為匈奴。〔六〕諸引弓之民并為一家，北州以定。願寢兵休士養馬，除前事，復故約，〔七〕以安邊民，以應古始，使少者得成其長，老者得安其處，世世平樂。未得皇帝之志，故使郎中係虖淺奉書請，〔八〕獻橐佗一，騎馬二，駕二駟。〔九〕皇帝即不欲匈奴近塞，則且詔吏民遠舍〔一０〕。使者至，即遣之。」六月中，來至新望之地。〔一一〕書至，漢議擊與和親孰便，公卿皆曰：「單于新破月氏，乘勝，不可擊也。且得匈奴地，澤鹵非可居也，和親甚便。」漢許之。","sentenceOrder":107},
  {"id":"s_work_han_thu_108_108","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「稱，副也。言與所遺書意相副，而共結驩親。」","sentenceOrder":108},
  {"id":"s_work_han_thu_108_109","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「不告單于也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_108_110","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「讓書，有責讓之言也。謂匈奴再得漢書，而發使將書以報漢。漢留其使不得來還，而漢又更不發使至匈奴也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_108_111","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「少吏猶言小吏。」","sentenceOrder":111},
  {"id":"s_work_han_thu_108_112","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「夷，平也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_108_113","chapterId":"ch_work_han_thu_108","textTraditional":"〔六〕　師古曰：「皆入匈奴國也。揭音丘列反。」","sentenceOrder":113},
  {"id":"s_work_han_thu_108_114","chapterId":"ch_work_han_thu_108","textTraditional":"〔七〕　師古曰：「復音扶目反。」","sentenceOrder":114},
  {"id":"s_work_han_thu_108_115","chapterId":"ch_work_han_thu_108","textTraditional":"〔八〕　師古曰：「虖音火姑反。」","sentenceOrder":115},
  {"id":"s_work_han_thu_108_116","chapterId":"ch_work_han_thu_108","textTraditional":"〔九〕　師古曰：「騎馬，堪為騎也。駕，可駕車也。二駟，八匹。」","sentenceOrder":116},
  {"id":"s_work_han_thu_108_117","chapterId":"ch_work_han_thu_108","textTraditional":"〔一０〕師古曰：「舍，居止也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_108_118","chapterId":"ch_work_han_thu_108","textTraditional":"〔一一〕服虔曰：「漢界上塞下之地。」","sentenceOrder":118},
  {"id":"s_work_han_thu_108_119","chapterId":"ch_work_han_thu_108","textTraditional":"孝文前六年，遺匈奴書曰：「皇帝敬問匈奴大單于無恙。使係虖淺遺朕書，云『願寢兵休（事）〔士〕，除前事，復故約，以安邊民，世世平樂』，朕甚嘉之。此古聖王之志也。漢與匈奴約為兄弟，所以遺單于甚厚。背約離兄弟之親者，常在匈奴。然右賢王事已在赦前，勿深誅。單于若稱書意，明告諸吏，使無負約，有信，敬如單于書。使者言單于自將并國有功，甚苦兵事。服繡袷綺衣、長襦、錦袍各一，〔一〕比疏一，〔二〕黃金飭具帶一，黃金犀毗一，〔三〕繡十匹，錦二十匹，赤綈、綠繒各四十匹，〔四〕使中大夫意、謁者令肩遺單于。」","sentenceOrder":119},
  {"id":"s_work_han_thu_108_120","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「服者，言天子自所服也。袷者，衣無絮也。繡袷綺衣，以繡為表，綺為裏也。袷音工洽反。」","sentenceOrder":120},
  {"id":"s_work_han_thu_108_121","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「辮髮之飭也，以金為之。比音頻寐反。疏字或作余。」","sentenceOrder":121},
  {"id":"s_work_han_thu_108_122","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　孟康曰：「要中大帶也。」張晏曰：「鮮卑郭洛帶，瑞獸名也，東胡好服之。」師古曰：「犀毗，胡帶之鉤也。亦曰鮮卑，亦謂師比，總一物也，語有輕重耳。」","sentenceOrder":122},
  {"id":"s_work_han_thu_108_123","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「繒者，帛之總稱。綈，厚繒也，音徒奚反。」","sentenceOrder":123},
  {"id":"s_work_han_thu_108_124","chapterId":"ch_work_han_thu_108","textTraditional":"後頃之，冒頓死，子稽粥立，〔一〕號曰老上單于。","sentenceOrder":124},
  {"id":"s_work_han_thu_108_125","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「稽音雞。粥音育。」","sentenceOrder":125},
  {"id":"s_work_han_thu_108_126","chapterId":"ch_work_han_thu_108","textTraditional":"老上稽粥單于初立，文帝復遣宗人女翁主為單于閼氏，〔一〕使宦者燕人中行說傅翁主。〔二〕說不欲行，漢強使之。說曰：「必我也，為漢患者。」〔三〕中行說既至，因降單于，單于愛幸之。","sentenceOrder":126},
  {"id":"s_work_han_thu_108_127","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「宗人女，亦諸侯王之女。」","sentenceOrder":127},
  {"id":"s_work_han_thu_108_128","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「姓中行，名說也。行音胡郎反。說讀曰悅。」","sentenceOrder":128},
  {"id":"s_work_han_thu_108_129","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「言我必於漢生患。」","sentenceOrder":129},
  {"id":"s_work_han_thu_108_130","chapterId":"ch_work_han_thu_108","textTraditional":"初，單于好漢繒絮食物，中行說曰：「匈奴人眾不能當漢之一郡，然所以強之者，以衣食異，無卬於漢。〔一〕今單于變俗好漢物，漢物不過什二，則匈奴盡歸於漢矣。〔二〕其得漢絮繒，以馳草棘中，衣袴皆裂弊，以視不如旃裘堅善也；〔三〕得漢食物皆去之，〔四〕以視不如重酪之便美也。」〔五〕於是說教單于左右疏記，以計識其人眾畜牧。〔六〕","sentenceOrder":130},
  {"id":"s_work_han_thu_108_131","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「卬音牛向反。」","sentenceOrder":131},
  {"id":"s_work_han_thu_108_132","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「言漢費物十分之二，則盡得匈奴之眾也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_108_133","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「視讀曰示。下皆類此。」","sentenceOrder":133},
  {"id":"s_work_han_thu_108_134","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「去，棄也，音丘呂反。」","sentenceOrder":134},
  {"id":"s_work_han_thu_108_135","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「重，乳汁也。重音竹用反，字本作湩，其音則同。」","sentenceOrder":135},
  {"id":"s_work_han_thu_108_136","chapterId":"ch_work_han_thu_108","textTraditional":"〔六〕　師古曰：「說者，舉中行說之名也。疏，分條之也。識亦記，音式志反。」","sentenceOrder":136},
  {"id":"s_work_han_thu_108_137","chapterId":"ch_work_han_thu_108","textTraditional":"漢遺單于書，以尺一牘，辭曰「皇帝敬問匈奴大單于無恙」，所以遺物及言語云云。中行說令單于以尺二寸牘，及印封皆令廣長大，倨驁其辭〔一〕曰「天地所生日月所置匈奴大單于敬問漢皇帝無恙」，所以遺物言語亦云云。","sentenceOrder":137},
  {"id":"s_work_han_thu_108_138","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「倨，慢也。驁與傲同。」","sentenceOrder":138},
  {"id":"s_work_han_thu_108_139","chapterId":"ch_work_han_thu_108","textTraditional":"漢使或言匈奴俗賤老，中行說窮漢使曰：「而漢俗屯戍從軍當發者，其親豈不自奪溫厚肥美齎送飲食行者乎？」〔一〕漢使曰：「然。」說曰：「匈奴明以攻戰為事，老弱不能鬥，故以其肥美飲食壯健以自衛，如此父子各得相保，何以言匈奴輕老也？」漢使曰：「匈奴父子同穹廬臥。〔二〕父死，妻其後母；兄弟死，盡妻其妻。無冠帶之節，闕庭之禮。」中行說曰：「匈奴之俗，食畜肉，飲其汁，衣其皮；畜食草飲水，隨時轉移。故其急則人習騎射，寬則人樂無事。約束徑，易行；君臣簡，可久。〔三〕一國之政猶一體也。父兄死，則妻其妻，惡種姓之失也。故匈奴雖亂，必立宗種。今中國雖陽不取其父兄之妻，親屬益疏則相殺，至到易姓，皆從此類也。且禮義之敝，上下交怨，而室屋之極，生力屈焉。〔四〕夫力耕桑以求衣食，〔五〕築城郭以自備，故其民急則不習戰攻，緩則罷於作業。〔六〕嗟土室之人，顧無喋喋佔佔，冠固何當！」〔七〕自是之後，漢使欲辯論者，中行說輒曰：「漢使毋多言，顧漢所輸匈奴繒絮米糱，令其量中，必善美而已，〔八〕何以言為乎？且所給備善則已，不備善而苦惡，則候秋孰，以騎馳蹂乃稼穡也。」〔九〕日夜教單于候利害處。","sentenceOrder":139},
  {"id":"s_work_han_thu_108_140","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「而，汝也。飲音於禁反。食音似。其下亦同。」","sentenceOrder":140},
  {"id":"s_work_han_thu_108_141","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「穹廬，旃帳也。其形穹隆，故曰穹廬。」","sentenceOrder":141},
  {"id":"s_work_han_thu_108_142","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「徑，直也。簡，率也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_108_143","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「言忠信衰薄，彊為禮義，故其末流，怨恨彌起。棟宇之作，土木競勝，勞役既重，所以力屈。屈，盡也，音其勿反。」","sentenceOrder":143},
  {"id":"s_work_han_thu_108_144","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「力謂竭力也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_108_145","chapterId":"ch_work_han_thu_108","textTraditional":"〔六〕　師古曰：「罷讀曰疲。」","sentenceOrder":145},
  {"id":"s_work_han_thu_108_146","chapterId":"ch_work_han_thu_108","textTraditional":"〔七〕　師古曰：「嗟者，歎愍之言也。喋喋，利口也。佔佔，衣裳貌也。言漢人且當思念，無為喋喋佔佔耳。雖自謂著冠，何所當益也。喋音牒。佔音昌占反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_108_147","chapterId":"ch_work_han_thu_108","textTraditional":"〔八〕　師古曰：「顧，念也。中猶滿也。量中者，滿其數也。中音竹仲反。」","sentenceOrder":147},
  {"id":"s_work_han_thu_108_148","chapterId":"ch_work_han_thu_108","textTraditional":"〔九〕　師古曰：「苦猶麤也。蹂，踐也。乃，汝也。蹂音人九反。」","sentenceOrder":148},
  {"id":"s_work_han_thu_108_149","chapterId":"ch_work_han_thu_108","textTraditional":"孝文十四年，匈奴單于十四萬騎入朝那蕭關，殺北地都尉卬，虜人民畜產甚多，遂至彭陽。〔一〕使騎兵入燒回中宮，〔二〕候騎至雍甘泉。於是文帝以中尉周舍、郎中令張武為將軍，發車千乘，十萬騎，軍長安旁以備胡寇。而拜昌侯盧卿為上郡將軍，甯侯魏遫為北地將軍，〔三〕隆慮侯周灶為隴西將軍，〔四〕東陽侯張相如為大將軍，成侯董赤為將軍，〔五〕大發車騎往擊胡。單于留塞內月餘，漢逐出塞即還，不能有所殺。匈奴日以驕，歲入邊，殺略人民甚眾，雲中、遼東最甚，郡萬餘人。漢甚患之，乃使使遺匈奴書，單于亦使當戶報謝，復言和親事。","sentenceOrder":149},
  {"id":"s_work_han_thu_108_150","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　服虔曰：「安定縣也。」師古曰：「即今彭原縣是。」","sentenceOrder":150},
  {"id":"s_work_han_thu_108_151","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「回中，地在安定，其中有宮也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_108_152","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「遫，古速字。」","sentenceOrder":152},
  {"id":"s_work_han_thu_108_153","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「慮音廬。」","sentenceOrder":153},
  {"id":"s_work_han_thu_108_154","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「文紀言建成侯，此言成侯，紀傳不同，當有誤。」","sentenceOrder":154},
  {"id":"s_work_han_thu_108_155","chapterId":"ch_work_han_thu_108","textTraditional":"孝文後二年，使使（遣）〔遺〕匈奴書曰：「皇帝敬問匈奴大單于無恙。使當戶且渠雕渠難、郎中韓遼遺朕馬二匹，已至，敬受〔一〕。先帝制，長城以北引弓之國受令單于，長城以內冠帶之室朕亦制之，使萬民耕織，射獵衣食，父子毋離，臣主相安，（居）〔俱〕無暴虐。今聞渫惡民貪降其趨，〔二〕背義絕約，忘萬民之命，離兩主之驩，然其事已在前矣。書云『二國已和親，兩主驩說，〔三〕寢兵休卒養馬，〔四〕世世昌樂，翕然更始』，朕甚嘉之。聖者日新，改作更始，使老者得息，幼者得長，各保其首領，而終其天年。朕與單于俱由此道，〔五〕順天恤民，世世相傳，施之無窮，天下莫不咸嘉。（使）漢與匈奴鄰敵之國，匈奴處北地，寒，殺氣早降，故詔吏遺單于秫糱金帛綿絮它物歲有數。今天下大安，萬民熙熙，〔六〕獨朕與單于為之父母。朕追念前事，薄物細故，謀臣計失，皆不足以離昆弟之驩。〔七〕朕聞天不頗覆，地不偏載。〔八〕朕與單于皆捐細故，俱蹈大道（也），〔九〕墮壞前惡，以圖長久，〔一０〕使兩國之民若一家子。元元萬民，下及魚鱉，上及飛鳥，跂行喙息蝡動之類，〔一一〕莫不就安利，避危殆。故來者不止，天之道也。俱去前事，〔一二〕朕釋逃虜民，〔一三〕單于毋言章尼等。〔一四〕朕聞古之帝王，約分明而不食言。〔一五〕單于留志，天下大安，〔一六〕和親之後，漢過不先。〔一七〕單于其察之。」","sentenceOrder":155},
  {"id":"s_work_han_thu_108_156","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「當戶且渠者，一人為二官。雕渠難者，其姓名。」","sentenceOrder":156},
  {"id":"s_work_han_thu_108_157","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　晉灼曰：「渫音渫水之渫。邪惡不正之民。」師古曰：「渫音先列反。降，下也，謂下意於利也。趨讀曰趣。」","sentenceOrder":157},
  {"id":"s_work_han_thu_108_158","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「說讀曰悅。」","sentenceOrder":158},
  {"id":"s_work_han_thu_108_159","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「寢，息也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_108_160","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「由，從也，用也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_108_161","chapterId":"ch_work_han_thu_108","textTraditional":"〔六〕　師古曰：「和樂貌。」","sentenceOrder":161},
  {"id":"s_work_han_thu_108_162","chapterId":"ch_work_han_thu_108","textTraditional":"〔七〕　師古曰：「細故，小事也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_108_163","chapterId":"ch_work_han_thu_108","textTraditional":"〔八〕　師古曰：「頗亦偏也，音普何反。」","sentenceOrder":163},
  {"id":"s_work_han_thu_108_164","chapterId":"ch_work_han_thu_108","textTraditional":"〔九〕　師古曰：「捐，棄也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_108_165","chapterId":"ch_work_han_thu_108","textTraditional":"〔一０〕師古曰：「墮，毀也。圖，謀也。墮音火規反。」","sentenceOrder":165},
  {"id":"s_work_han_thu_108_166","chapterId":"ch_work_han_thu_108","textTraditional":"〔一一〕師古曰：「跂行，凡有足而行者也。喙息，凡以口出氣者也。蝡蝡，動貌。跂音岐。喙音許穢反。蝡音人兗反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_108_167","chapterId":"ch_work_han_thu_108","textTraditional":"〔一二〕師古曰：「去，除也，音丘呂反。」","sentenceOrder":167},
  {"id":"s_work_han_thu_108_168","chapterId":"ch_work_han_thu_108","textTraditional":"〔一三〕師古曰：「謂漢人逃入匈奴者，（今）〔令〕不追。」","sentenceOrder":168},
  {"id":"s_work_han_thu_108_169","chapterId":"ch_work_han_thu_108","textTraditional":"〔一四〕師古曰：「背單于降漢者。」","sentenceOrder":169},
  {"id":"s_work_han_thu_108_170","chapterId":"ch_work_han_thu_108","textTraditional":"〔一五〕師古曰：「凡云食言者，終為不信，棄其前言，如食而盡。」","sentenceOrder":170},
  {"id":"s_work_han_thu_108_171","chapterId":"ch_work_han_thu_108","textTraditional":"〔一六〕師古曰：「留志謂計念和親。」","sentenceOrder":171},
  {"id":"s_work_han_thu_108_172","chapterId":"ch_work_han_thu_108","textTraditional":"〔一七〕師古曰：「言更不負約。」","sentenceOrder":172},
  {"id":"s_work_han_thu_108_173","chapterId":"ch_work_han_thu_108","textTraditional":"單于既約和親，於是制詔御史：「匈奴大單于遺朕書，和親已定，亡人不足以益眾廣地，匈奴無入塞，漢無出塞，犯今約者殺之，可以久親，後無咎，俱便。朕已許。其布告天下，使明知之。」","sentenceOrder":173},
  {"id":"s_work_han_thu_108_174","chapterId":"ch_work_han_thu_108","textTraditional":"後四年，老上單于死，子軍臣單于立，而中行說復事之。漢復與匈奴和親。","sentenceOrder":174},
  {"id":"s_work_han_thu_108_175","chapterId":"ch_work_han_thu_108","textTraditional":"軍臣單于立歲餘，匈奴復絕和親，大入上郡、雲中各三萬騎，所殺略甚眾。於是漢使三將軍軍屯北地，代屯句注，趙屯飛狐口，〔一〕緣邊亦各堅守以備胡寇。又置三將軍，軍長安西細柳、渭北棘門、霸上以備胡。胡騎入代句注邊，烽火通於甘泉、長安。數月，漢兵至邊，匈奴亦遠塞，〔二〕漢兵亦罷。後歲餘，文帝崩，景帝立，而趙王遂乃陰使於匈奴。吳楚反，欲與趙合謀入邊。漢圍破趙，匈奴亦止。自是後，景帝復與匈奴和親，通關市，給遺單于，遣翁主如故約。終景帝世，時時小入盜邊，無大寇。","sentenceOrder":175},
  {"id":"s_work_han_thu_108_176","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「險阨之處，在代郡之南，南衝燕趙之中。」","sentenceOrder":176},
  {"id":"s_work_han_thu_108_177","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「遠，離也，音于萬反。」","sentenceOrder":177},
  {"id":"s_work_han_thu_108_178","chapterId":"ch_work_han_thu_108","textTraditional":"武帝即位，明和親約束，厚遇關市，饒給之。匈奴自單于以下皆親漢，往來長城下。","sentenceOrder":178},
  {"id":"s_work_han_thu_108_179","chapterId":"ch_work_han_thu_108","textTraditional":"漢使馬邑人聶翁壹〔一〕間闌出物與匈奴交易，〔二〕陽為賣馬邑城以誘單于。單于信之，而貪馬邑財物，乃以十萬騎入武州塞。漢伏兵三十餘萬馬邑旁，御史大夫韓安國為護軍將軍，護四將軍以伏單于。〔三〕單于既入漢塞，未至馬邑百餘里，見畜布野而無人牧者，怪之，乃攻亭。時雁門尉史行徼，見寇，保此亭，〔四〕單于得，欲刺之。尉史知漢謀，乃下，〔五〕具告單于。單于大驚，曰：「吾固疑之。」乃引兵還。出曰：「吾得尉史，天也。」以尉史為天王。漢兵約單于入馬邑而縱（兵），〔六〕單于不至，以故無所得。將軍王恢部出代擊胡輜重，〔七〕聞單于還，兵多，不敢出。漢以恢本建造兵謀而不進，誅恢。自是後，匈奴絕和親，攻當路塞，〔八〕往往入盜於邊，不可勝數。然匈奴貪，尚樂關市，耆漢財物，〔九〕漢亦通關市不絕以中之。〔一０〕","sentenceOrder":179},
  {"id":"s_work_han_thu_108_180","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「姓聶名壹。翁者，老人之稱也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_108_181","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　孟康曰：「私出塞交易。」","sentenceOrder":181},
  {"id":"s_work_han_thu_108_182","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「伏兵而待單于也。」","sentenceOrder":182},
  {"id":"s_work_han_thu_108_183","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「漢律，近塞郡皆置尉，百里一人，士史、尉史各二人巡行徼塞也。行音下孟反。」","sentenceOrder":183},
  {"id":"s_work_han_thu_108_184","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「尉史在亭樓上，虜欲以矛戟刺之，懼，乃自下以謀告。」","sentenceOrder":184},
  {"id":"s_work_han_thu_108_185","chapterId":"ch_work_han_thu_108","textTraditional":"〔六〕　師古曰：「放兵以擊單于。」","sentenceOrder":185},
  {"id":"s_work_han_thu_108_186","chapterId":"ch_work_han_thu_108","textTraditional":"〔七〕　師古曰：「重音直用反。」","sentenceOrder":186},
  {"id":"s_work_han_thu_108_187","chapterId":"ch_work_han_thu_108","textTraditional":"〔八〕　師古曰：「塞之當行道處者。」","sentenceOrder":187},
  {"id":"s_work_han_thu_108_188","chapterId":"ch_work_han_thu_108","textTraditional":"〔九〕　師古曰：「耆讀曰嗜。」","sentenceOrder":188},
  {"id":"s_work_han_thu_108_189","chapterId":"ch_work_han_thu_108","textTraditional":"〔一０〕師古曰：「以關市中其意。中音竹仲反。」","sentenceOrder":189},
  {"id":"s_work_han_thu_108_190","chapterId":"ch_work_han_thu_108","textTraditional":"自馬邑軍後五歲之秋，漢使四將各萬騎擊胡關市下。將軍衛青出上谷，至龍城，得胡首虜七百人。公孫賀出雲中，無所得。公孫敖出代郡，為胡所敗七千。李廣出雁門，為胡所敗，匈奴生得廣，廣道亡歸。〔一〕漢囚敖、廣，敖、廣贖為庶人。其冬，匈奴數千人盜邊，漁陽尤甚。漢使將軍韓安國屯漁陽備胡。其明年秋，匈奴二萬騎入漢，殺遼西太守，略二千餘人。又敗漁陽太守軍千餘人，圍將軍安國。〔二〕安國時千餘騎亦且盡，會燕救之，至，匈奴乃去，又入雁門殺略千餘人。於是漢使將軍衛青將三萬騎出雁門，李息出代郡，擊胡，得首虜數千。其明年，衛青復出雲中以西至隴西，擊胡之樓煩、白羊王於河南，得胡首虜數千，羊百餘萬。於是漢遂取河南地，築朔方，復繕故秦時蒙恬所為塞，因河而為固。漢亦棄上谷之斗辟縣造陽地以予胡。〔三〕是歲，元朔二年也。","sentenceOrder":190},
  {"id":"s_work_han_thu_108_191","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「於道上亡還。」","sentenceOrder":191},
  {"id":"s_work_han_thu_108_192","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「即韓安國也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_108_193","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　孟康曰：「縣斗辟曲近胡。」師古曰：「斗，絕也。縣之斗曲入匈奴界者，其中造陽地也。辟讀曰僻。」","sentenceOrder":193},
  {"id":"s_work_han_thu_108_194","chapterId":"ch_work_han_thu_108","textTraditional":"其後冬，軍臣單于死，其弟左谷蠡王伊穉斜自立為單于，攻敗軍臣單于太子於單。於單亡降漢，漢封於單為陟安侯，數月死。","sentenceOrder":194},
  {"id":"s_work_han_thu_108_195","chapterId":"ch_work_han_thu_108","textTraditional":"伊穉斜單于既立，其夏，匈奴數萬騎入代郡，殺太守共友，〔一〕略千餘人。秋，又入鴈門，殺略千餘人。其明年，又入代郡、定襄、上郡，各三萬騎，殺略數千人。匈奴右賢王怨漢奪之河南地而築朔方，數寇盜邊，及入河南，侵擾朔方，殺略吏民甚眾。","sentenceOrder":195},
  {"id":"s_work_han_thu_108_196","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「共友，太守姓名也。共讀曰龔。」","sentenceOrder":196},
  {"id":"s_work_han_thu_108_197","chapterId":"ch_work_han_thu_108","textTraditional":"其明年春，漢遣衛青將六將軍十餘萬人出朔方高闕。右賢王以為漢兵不能至，飲酒醉。漢兵出塞六七百里，夜圍右賢王。右賢王大驚，脫身逃走，精騎往往隨後去。漢將軍得右賢王人眾男女萬五千人，裨小王十餘人。其秋，匈奴萬騎入代郡，殺都尉朱央，略千餘人。","sentenceOrder":197},
  {"id":"s_work_han_thu_108_198","chapterId":"ch_work_han_thu_108","textTraditional":"其明年春，漢復遣大將軍衛青將六將軍，十餘萬騎，仍再出定襄數百里〔一〕擊匈奴，得首虜前後萬九千餘級，而漢亦亡兩將軍，三千餘騎。右將軍建得以身脫，而前將軍翕侯趙信兵不利，降匈奴。趙信者，故胡小王，降漢，漢封為翕侯，以前將軍與右將軍并軍，介獨遇單于兵，故盡沒。〔二〕單于既得翕侯，以為自次王，〔三〕用其姊妻之，與謀漢。信教單于益北絕幕，〔四〕以誘罷漢兵，徼極而取之，〔五〕毋近塞。〔六〕單于從之。其明年，胡數萬騎入上谷，殺數百人。","sentenceOrder":198},
  {"id":"s_work_han_thu_108_199","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「仍，頻也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_108_200","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　晉灼曰：「介音戛。」師古曰：「介，特也。本雖并軍，至遇單于時特也。介讀如本字。」","sentenceOrder":200},
  {"id":"s_work_han_thu_108_201","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「自次者，尊重次於單于。」","sentenceOrder":201},
  {"id":"s_work_han_thu_108_202","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「直度曰絕。」","sentenceOrder":202},
  {"id":"s_work_han_thu_108_203","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「罷讀曰疲。徼，要也。誘令疲，要其困極，然後取之。徼音工堯反。」","sentenceOrder":203},
  {"id":"s_work_han_thu_108_204","chapterId":"ch_work_han_thu_108","textTraditional":"〔六〕　師古曰：「不近塞居，所以疲勞漢兵也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_108_205","chapterId":"ch_work_han_thu_108","textTraditional":"其明年春，漢復遣大將軍衛青將六將軍，十餘萬騎，仍再出定襄數百里〔一〕擊匈奴，得……","sentenceOrder":205},
  {"id":"s_work_han_thu_108_206","chapterId":"ch_work_han_thu_108","textTraditional":"明年春，漢使票騎將軍去病將萬騎出隴西，過焉耆山千餘里，得胡首虜八千餘級，得休屠王祭天金人。〔一〕其夏，票騎將軍復與合騎侯數萬騎出隴西、北地二千里，過居延，攻祁連山，得胡首虜三萬餘級，裨小王以下十餘人。是時，匈奴亦來入代郡、鴈門，殺略數百人。漢使博望侯及李將軍廣出右北平，擊匈奴左賢王。左賢王圍李廣，廣軍四千人死者過半，殺虜亦過當。會博望侯軍救至，李將軍得脫，盡亡其軍。合騎侯後票騎將軍期，及博望侯皆當死，贖為庶人。","sentenceOrder":206},
  {"id":"s_work_han_thu_108_207","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　孟康曰：「匈奴祭天處本在雲陽甘泉山下，秦擊奪其地，後徙之休屠王右地，故休屠有祭天金人象也。」師古曰：「作金人以為天神之主而祭之，即今佛像是其遺法。」","sentenceOrder":207},
  {"id":"s_work_han_thu_108_208","chapterId":"ch_work_han_thu_108","textTraditional":"其秋，單于怒昆邪王、休屠王居西方為漢所殺虜數萬人，欲召誅之。昆邪、休屠王恐，謀降漢，漢使票騎將軍迎之。昆邪王殺休屠王，并將其眾降漢，凡四萬餘人，號十萬。於是漢已得昆邪，則隴西、北地、河西益少胡寇，徙關東貧民處所奪匈奴河南地新秦中以實之，〔一〕（西）〔而〕減北地以西戍卒半。明年春，匈奴入右北平、定襄各數萬騎，殺略千餘人。","sentenceOrder":208},
  {"id":"s_work_han_thu_108_209","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「新秦，解在食貨志。」","sentenceOrder":209},
  {"id":"s_work_han_thu_108_210","chapterId":"ch_work_han_thu_108","textTraditional":"其〔明〕年春，漢謀以為「翕侯信為單于計，居幕北，以為漢兵不能至」。乃粟馬，〔一〕發十萬騎，私負從馬凡十四萬匹，〔二〕糧重不與焉。〔三〕令大將軍青、票騎將軍去病中分軍，大將軍出定襄，票騎將軍出代，咸約絕幕擊匈奴。〔四〕單于聞之，遠甚輜重，〔五〕以精兵待於幕北。與漢大將軍接戰一日，會暮，大風起，漢兵縱左右翼圍單于。單于自度戰不能與漢兵，〔六〕遂獨與壯騎數百潰漢圍西北遁走。漢兵夜追之不得，行捕斬首虜凡萬九千級，〔七〕北至窴顏山趙信城而還。〔八〕","sentenceOrder":210},
  {"id":"s_work_han_thu_108_211","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「以粟秣馬也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_108_212","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「私負衣裝者及私將馬從者，皆非公家發與之限。」","sentenceOrder":212},
  {"id":"s_work_han_thu_108_213","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「負戴糧食者。重音直用反。與讀曰豫。」","sentenceOrder":213},
  {"id":"s_work_han_thu_108_214","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「約謂為其要。」","sentenceOrder":214},
  {"id":"s_work_han_thu_108_215","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「徙其輜重令遠去。」","sentenceOrder":215},
  {"id":"s_work_han_thu_108_216","chapterId":"ch_work_han_thu_108","textTraditional":"〔六〕　師古曰：「與猶如也。度音徒各反。」","sentenceOrder":216},
  {"id":"s_work_han_thu_108_217","chapterId":"ch_work_han_thu_108","textTraditional":"〔七〕　師古曰：「且行且捕斬之。」","sentenceOrder":217},
  {"id":"s_work_han_thu_108_218","chapterId":"ch_work_han_thu_108","textTraditional":"〔八〕　孟康曰：「趙信所作，因以名城。」師古曰：「窴音徒千反。」","sentenceOrder":218},
  {"id":"s_work_han_thu_108_219","chapterId":"ch_work_han_thu_108","textTraditional":"單于之走，其兵往往與漢軍相亂而隨單于。單于久不與其大眾相得，右谷蠡王以為單于死，乃自立為單于。真單于復得其眾，右谷蠡乃去號，復其故位。","sentenceOrder":219},
  {"id":"s_work_han_thu_108_220","chapterId":"ch_work_han_thu_108","textTraditional":"票騎之出代二千餘里，與左王接戰，漢兵得胡首虜凡七萬餘人，左王將皆遁走。票騎封於狼居胥山，禪姑衍，臨翰海而還。","sentenceOrder":220},
  {"id":"s_work_han_thu_108_221","chapterId":"ch_work_han_thu_108","textTraditional":"是後匈奴遠遁，而幕南無王庭。漢度河自朔方以西至令居，〔一〕往往通渠置田官，吏卒五六萬人，稍蠶食，地接匈奴以北。〔二〕","sentenceOrder":221},
  {"id":"s_work_han_thu_108_222","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「令音零。下亦類此。」","sentenceOrder":222},
  {"id":"s_work_han_thu_108_223","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「其地相接不絕。」","sentenceOrder":223},
  {"id":"s_work_han_thu_108_224","chapterId":"ch_work_han_thu_108","textTraditional":"初，漢兩將大出圍單于，所殺虜八九萬，而漢士物故者亦萬數，〔一〕漢馬死者十餘萬匹。匈奴雖病，遠去，而漢馬亦少，無以復往。單于用趙信計，遣使好辭請和親。天子下其議，或言和親，或言遂臣之。丞相長史任敞曰：「匈奴新困，宜使為外臣，朝請於邊。〔二〕」漢使敞使於單于。單于聞敞計，大怒，留之不遣。先是漢亦有所降匈奴使者，單于亦輒留漢使相當。漢方復收士馬，會票騎將軍去病死，於是漢久不北擊胡。","sentenceOrder":224},
  {"id":"s_work_han_thu_108_225","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「物故謂死也。」","sentenceOrder":225},
  {"id":"s_work_han_thu_108_226","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「請音材性反。」","sentenceOrder":226},
  {"id":"s_work_han_thu_108_227","chapterId":"ch_work_han_thu_108","textTraditional":"數歲，伊稚斜單于立十三年死，子烏維立為單于。是歲，元鼎三年也。烏維單于立，而漢武帝始出巡狩郡縣。其後漢方南誅兩越，不擊匈奴，匈奴亦不入邊。","sentenceOrder":227},
  {"id":"s_work_han_thu_108_228","chapterId":"ch_work_han_thu_108","textTraditional":"烏維立三年，漢已滅兩越，遣故太僕公孫賀將萬五千騎出九原二千餘里，至浮苴井，〔一〕從票侯趙破奴萬餘騎出令居數千里，至匈奴河水，〔二〕皆不見匈奴一人而還。","sentenceOrder":228},
  {"id":"s_work_han_thu_108_229","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「苴音子餘反。武紀苴字作沮，其音同。」","sentenceOrder":229},
  {"id":"s_work_han_thu_108_230","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　臣瓚曰：「水名也。去令居千里。」","sentenceOrder":230},
  {"id":"s_work_han_thu_108_231","chapterId":"ch_work_han_thu_108","textTraditional":"是時，天子巡邊，親至朔方，勒兵十八萬騎以見武節，〔一〕而使郭吉風告單于。〔二〕既至匈奴，匈奴主客問所使，〔三〕郭吉卑體好言曰：「吾見單于而口言。」單于見吉，吉曰：「南越王頭已縣於漢北闕下。今單于即能前與漢戰，天子自將兵待邊；即不能，亟南面而臣於漢。〔四〕何但遠走，亡匿於幕北寒苦無水草之地為？〔五〕」語卒，單于大怒，立斬主客見者，而留郭吉不歸，遷辱之北海上。而單于終不肯為寇於漢邊，休養士馬，習射獵，數使使好辭甘言求和親。","sentenceOrder":231},
  {"id":"s_work_han_thu_108_232","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「見，示也。」","sentenceOrder":232},
  {"id":"s_work_han_thu_108_233","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「風讀曰諷。」","sentenceOrder":233},
  {"id":"s_work_han_thu_108_234","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「主客，主接諸客者也。問以何事而來。」","sentenceOrder":234},
  {"id":"s_work_han_thu_108_235","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「亟，急也，音居力反。」","sentenceOrder":235},
  {"id":"s_work_han_thu_108_236","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「但，空也。」","sentenceOrder":236},
  {"id":"s_work_han_thu_108_237","chapterId":"ch_work_han_thu_108","textTraditional":"漢使王烏等闚匈奴。匈奴法，漢使不去節，不以墨黥其面，不得入穹廬。〔一〕王烏，北地人，習胡俗，去其節，黥面入廬。單于愛之，陽許曰：「吾為遣其太子入質於漢，以求和親。」〔二〕","sentenceOrder":237},
  {"id":"s_work_han_thu_108_238","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「以墨黥面也。」","sentenceOrder":238},
  {"id":"s_work_han_thu_108_239","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「言為王烏故遣太子入質。」","sentenceOrder":239},
  {"id":"s_work_han_thu_108_240","chapterId":"ch_work_han_thu_108","textTraditional":"漢使楊信使於匈奴。是時漢東拔濊貉、朝鮮以為郡，〔一〕而西置酒泉郡以隔絕胡與羌通之路。又西通月氏、大夏，以翁主妻烏孫王，以分匈奴西方之援國。又北益廣田至眩雷為塞，〔二〕而匈奴終不敢以為言。是歲，翕侯信死，漢用事者以匈奴已弱，可臣從也。楊信為人剛直屈強，素非貴臣也，〔三〕單于不親。欲召入，不肯去節，乃坐穹廬外見楊信。楊信說單于曰：「即欲和親，以單于太子為質於漢。」單于曰：「非故約。故約，漢常遣翁主，給繒絮食物有品，以和親，〔四〕而匈奴亦不復擾邊。今乃欲反古，〔五〕令吾太子為質，無幾矣。」〔六〕匈奴俗，見漢使非中貴人，其儒生，以為欲說，折其辭辯；少年，以為欲刺，折其氣。每漢兵入匈奴，匈奴輒報償。漢留匈奴使，匈奴亦留漢使，必得當乃止。","sentenceOrder":240},
  {"id":"s_work_han_thu_108_241","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「濊與穢同，亦或作薉。」","sentenceOrder":241},
  {"id":"s_work_han_thu_108_242","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　服虔曰：「眩雷，地在烏孫北也。眩音州縣之縣。」","sentenceOrder":242},
  {"id":"s_work_han_thu_108_243","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「屈音其勿反。強音其兩反。」","sentenceOrder":243},
  {"id":"s_work_han_thu_108_244","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「品謂等差也。」","sentenceOrder":244},
  {"id":"s_work_han_thu_108_245","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「反，違也。」","sentenceOrder":245},
  {"id":"s_work_han_thu_108_246","chapterId":"ch_work_han_thu_108","textTraditional":"〔六〕　師古曰：「言遣太子為質，則匈奴國中所餘者無幾，皆當盡也。幾音居豈反。」","sentenceOrder":246},
  {"id":"s_work_han_thu_108_247","chapterId":"ch_work_han_thu_108","textTraditional":"楊信既歸，漢使王烏等如匈奴。匈奴復諂以甘言，〔一〕欲多得漢財物，紿王烏曰：「吾欲入漢〔二〕見天子，面相結為兄弟。」王烏歸報漢，漢為單于築邸于長安。匈奴曰：「非得漢貴人使，吾不與誠語。」〔三〕匈奴使其貴人至漢，病，服藥欲愈之，不幸而死。漢使路充國佩二千石印綬，使送其喪，厚幣直數千金。單于以為漢殺吾貴使者，乃留路充國不歸。諸所言者，單于特空紿王烏，〔四〕殊無意入漢，遣太子來質。於是匈奴數使奇兵侵犯漢邊。漢乃拜郭昌為拔胡將軍，及浞野侯屯朔方以東，備胡。〔五〕","sentenceOrder":247},
  {"id":"s_work_han_thu_108_248","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「讇，古諂字。」","sentenceOrder":248},
  {"id":"s_work_han_thu_108_249","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「紿，詐也。」","sentenceOrder":249},
  {"id":"s_work_han_thu_108_250","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「誠，實也。」","sentenceOrder":250},
  {"id":"s_work_han_thu_108_251","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「特，但也。」","sentenceOrder":251},
  {"id":"s_work_han_thu_108_252","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「浞野侯，趙破奴也。浞音仕角反。」","sentenceOrder":252},
  {"id":"s_work_han_thu_108_253","chapterId":"ch_work_han_thu_108","textTraditional":"烏維單于立十歲死，子詹師廬立，年少，號為兒單于。是歲，元封六年也。自是後，單于益西北。左方兵直雲中，右方兵直酒泉、敦煌。","sentenceOrder":253},
  {"id":"s_work_han_thu_108_254","chapterId":"ch_work_han_thu_108","textTraditional":"兒單于立，漢使兩使，一人弔單于，一人弔右賢王，欲以乖其國。使者入匈奴，匈奴悉將致單于。單于怒而悉留漢使。漢使留匈奴者前後十餘輩，而匈奴使來漢，亦輒留之相當。","sentenceOrder":254},
  {"id":"s_work_han_thu_108_255","chapterId":"ch_work_han_thu_108","textTraditional":"是歲，漢使貳師將軍西伐大宛，而令因杅將軍築受降城。〔一〕其冬，匈奴大雨雪，〔二〕畜多飢寒死，而單于年少，好殺伐，國中多不安。左大都尉欲殺單于，使人間告漢〔三〕曰：「我欲殺單于降漢，漢遠，漢即來兵近我，我即發。」〔四〕初漢聞此言，故築受降城，猶以為遠。","sentenceOrder":255},
  {"id":"s_work_han_thu_108_256","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「杅音于。」","sentenceOrder":256},
  {"id":"s_work_han_thu_108_257","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「雨音于具反。」","sentenceOrder":257},
  {"id":"s_work_han_thu_108_258","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「私來報。」","sentenceOrder":258},
  {"id":"s_work_han_thu_108_259","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「來兵，言以兵來也。」","sentenceOrder":259},
  {"id":"s_work_han_thu_108_260","chapterId":"ch_work_han_thu_108","textTraditional":"其明年春，漢使浞野侯破奴將二萬騎出朔方北二千餘里，〔一〕期至浚稽山而還。〔二〕浞野侯既至期，左大都尉欲發而覺，單于誅之，發兵擊浞野侯。浞野侯行捕首虜數千人。還，未至受降城四百里，匈奴八萬騎圍之。浞野侯夜出自求水，匈奴生得浞野侯，因急擊其軍。軍吏畏亡將而誅，莫相勸而歸，軍遂沒於匈奴。單于大喜，遂遣兵攻受降城，不能下，乃侵入邊而去。明年，單于欲自攻受降城，未到，病死。","sentenceOrder":260},
  {"id":"s_work_han_thu_108_261","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「以迎左大都尉。」","sentenceOrder":261},
  {"id":"s_work_han_thu_108_262","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「浚音俊。稽音雞。在武威北。」","sentenceOrder":262},
  {"id":"s_work_han_thu_108_263","chapterId":"ch_work_han_thu_108","textTraditional":"兒單于立三歲而死。子少，匈奴乃立其季父烏維單于弟右賢王句黎湖為單于。〔一〕是歲，太初三年也。","sentenceOrder":263},
  {"id":"s_work_han_thu_108_264","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「句音鉤。」","sentenceOrder":264},
  {"id":"s_work_han_thu_108_265","chapterId":"ch_work_han_thu_108","textTraditional":"句黎湖單于立，漢使光祿徐自為出五原塞數百里，遠者千里，築城障列亭至盧朐，〔一〕而使游擊將軍韓說、長平侯衛伉屯其旁〔二〕，使強弩都尉路博德築居延澤上。","sentenceOrder":265},
  {"id":"s_work_han_thu_108_266","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「盧朐，山名也。朐音劬。」","sentenceOrder":266},
  {"id":"s_work_han_thu_108_267","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「說讀曰悅。伉音抗，即衛青子。」","sentenceOrder":267},
  {"id":"s_work_han_thu_108_268","chapterId":"ch_work_han_thu_108","textTraditional":"其秋，匈奴大入雲中、定襄、五原、朔方，殺略數千人，敗數二千石而去，行壞光祿所築亭障。又使右賢王入酒泉、張掖，略數千人。會任文擊救，〔一〕盡復失其所得而去。聞貳師將軍破大宛，斬其王還，單于欲遮之，不敢，其冬病死。","sentenceOrder":268},
  {"id":"s_work_han_thu_108_269","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　服虔曰：「任文，漢將也。」師古曰：「擊救者，擊匈奴而自救漢人。」","sentenceOrder":269},
  {"id":"s_work_han_thu_108_270","chapterId":"ch_work_han_thu_108","textTraditional":"句黎湖單于立一歲死，其弟左大都尉且鞮侯立為單于。〔一〕","sentenceOrder":270},
  {"id":"s_work_han_thu_108_271","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「且音子余反。鞮音丁奚反。」","sentenceOrder":271},
  {"id":"s_work_han_thu_108_272","chapterId":"ch_work_han_thu_108","textTraditional":"漢既誅大宛，威震外國，天子意欲遂困胡，乃下詔曰：「高皇帝遺朕平城之憂，〔一〕高后時單于書絕悖逆。昔齊襄公復九世之讎，春秋大之。」〔二〕是歲，太初四年也。","sentenceOrder":272},
  {"id":"s_work_han_thu_108_273","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「遺，留也。」","sentenceOrder":273},
  {"id":"s_work_han_thu_108_274","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「公羊傳莊四年春，齊襄公滅紀，復讎也。襄公之九世祖昔為紀侯所譖，而亨殺于周，故襄公滅紀也。九世猶可以復讎乎？曰：雖百世可也。」","sentenceOrder":274},
  {"id":"s_work_han_thu_108_275","chapterId":"ch_work_han_thu_108","textTraditional":"且鞮侯單于初立，恐漢襲之，盡歸漢使之不降者路充國等於漢。單于乃自謂「我兒子，安敢望漢天子！漢天子，我丈人行。」〔一〕漢遣中郎將蘇武厚幣賂遺單于，單于益驕，禮甚倨，非漢所望也。明年，浞野侯破奴得亡歸漢。","sentenceOrder":275},
  {"id":"s_work_han_thu_108_276","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「丈人，尊老之稱也。行音胡浪反。」","sentenceOrder":276},
  {"id":"s_work_han_thu_108_277","chapterId":"ch_work_han_thu_108","textTraditional":"其明年，漢使貳師將軍將三萬騎出酒泉，擊右賢王於天山，得首虜萬餘級而還。匈奴大圍貳師，幾不得脫。〔一〕漢兵物故什六七。〔一〕漢又使因杅將軍出西河，與強弩都尉會涿邪山，亡所得。使騎都尉李陵將步兵五千人出居延北千餘里，與單于會，合戰，陵所殺傷萬餘人，兵食盡，欲歸，單于圍陵，陵降匈奴，其兵得脫歸漢者四百人。單于乃貴陵，以其女妻之。","sentenceOrder":277},
  {"id":"s_work_han_thu_108_278","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「幾音鉅依反。」","sentenceOrder":278},
  {"id":"s_work_han_thu_108_279","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「物故謂死也。」","sentenceOrder":279},
  {"id":"s_work_han_thu_108_280","chapterId":"ch_work_han_thu_108","textTraditional":"後二歲，漢使貳師將軍六萬騎，步兵七萬，出朔方；強弩都尉路博德將萬餘人，與貳師會；游擊將軍說步兵三萬人，出五原；〔一〕因杅將軍敖將騎萬，步兵三萬人，出雁門。匈奴聞，悉遠其累重於余吾水北，〔二〕而單于以十萬待水南，與貳師接戰。貳師解而引歸，與單于連鬥十餘日。游擊亡所得。因杅與左賢王戰，不利，引歸。","sentenceOrder":280},
  {"id":"s_work_han_thu_108_281","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「即上韓說也。」","sentenceOrder":281},
  {"id":"s_work_han_thu_108_282","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「累重謂妻子資產也。累音力瑞反。重音直用反。」","sentenceOrder":282},
  {"id":"s_work_han_thu_108_283","chapterId":"ch_work_han_thu_108","textTraditional":"明年，且鞮侯單于死，立五年，長子左賢王立為狐鹿姑單于。是歲，太始元年也。","sentenceOrder":283},
  {"id":"s_work_han_thu_108_284","chapterId":"ch_work_han_thu_108","textTraditional":"初，且鞮侯兩子，長為左賢王，次為左大將，病且死，言立左賢王。左賢王未至，貴人以為有病，更立左大將為單于。左賢王聞之，不敢進。左大將使人召左賢王而讓位焉。左賢王辭以病，左大將不聽，謂曰：「即不幸死，傳之於我。」左賢王許之，遂立為狐鹿姑單于。","sentenceOrder":284},
  {"id":"s_work_han_thu_108_285","chapterId":"ch_work_han_thu_108","textTraditional":"狐鹿姑單于立，以左大將為左賢王，數年病死，其子先賢撣不得代，〔一〕更以為日逐王。日逐王者，賤於左賢王。單于自以其子為左賢王。","sentenceOrder":285},
  {"id":"s_work_han_thu_108_286","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「撣音纏。」","sentenceOrder":286},
  {"id":"s_work_han_thu_108_287","chapterId":"ch_work_han_thu_108","textTraditional":"單于既立六年，而匈奴入上谷、五原，殺略吏民。其年，匈奴復入五原、酒泉，殺兩部都尉。於是漢遣貳師將軍七萬人出五原，御史大夫商丘成將三萬餘人出西河，重合侯莽通將四萬騎出酒泉千餘里。單于聞漢兵大出，悉遣其輜重，徙趙信城北邸郅居水。〔一〕左賢王驅其人民度余吾水六七百里，居兜銜山。單于自將精兵左安侯度姑且水。〔二〕","sentenceOrder":287},
  {"id":"s_work_han_thu_108_288","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「邸，至也，音丁禮反。郅音之日反。」","sentenceOrder":288},
  {"id":"s_work_han_thu_108_289","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「且音子余反。」","sentenceOrder":289},
  {"id":"s_work_han_thu_108_290","chapterId":"ch_work_han_thu_108","textTraditional":"御史大夫軍至追（斜）〔邪〕徑，無所見，還。〔一〕匈奴使大將與李陵將三萬餘騎追漢軍，至浚稽山合，轉戰九日，漢兵陷陳卻敵，殺傷虜甚眾。至蒲奴水，虜不利，還去。","sentenceOrder":290},
  {"id":"s_work_han_thu_108_291","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「從疾道而追之，不見虜而還也。邪音似嗟反。」","sentenceOrder":291},
  {"id":"s_work_han_thu_108_292","chapterId":"ch_work_han_thu_108","textTraditional":"重合侯軍至天山，匈奴使大將偃渠與左右呼知王將二萬餘騎要漢兵，見漢兵強，引去。重合侯無所得失。是時，漢恐車師兵遮重合侯，乃遣闓陵侯將兵別圍車師，〔一〕盡得其王民眾而還。","sentenceOrder":292},
  {"id":"s_work_han_thu_108_293","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「闓讀與開同。」","sentenceOrder":293},
  {"id":"s_work_han_thu_108_294","chapterId":"ch_work_han_thu_108","textTraditional":"貳師將軍將出塞，匈奴使右大都尉與衛律將五千騎要擊漢軍於夫羊句山狹。〔一〕貳師遣屬國胡騎二千與戰，虜兵壞散，死傷者數百人。漢軍乘勝追北，至范夫人城，〔二〕匈奴奔走，莫敢距敵。會貳師妻子坐巫蠱收，聞之憂懼。其掾胡亞夫亦避罪從軍，說貳師曰：「夫人室家皆在吏，若還不稱意，適與獄會，郅居以北可復得見乎？」〔三〕貳師由是狐疑，欲深入要功，遂北至郅居水上。虜已去，貳師遣護軍將二萬騎度郅居之水。一日，逢左賢王左大將，將二萬騎與漢軍合戰一日，漢軍殺左大將，虜死傷甚眾。軍長史與決眭都尉煇渠侯謀〔四〕曰：「將軍懷異心，欲危眾求功，恐必敗。」謀共執貳師。貳師聞之，斬長史，引兵還至速邪烏燕然山。〔五〕單于知漢軍勞倦，自將五萬騎遮擊貳師，相殺傷甚眾。夜塹漢軍前，深數尺，從後急擊之，軍大亂敗，貳師降。單于素知其漢大將貴臣，以女妻之，尊寵在衛律上。","sentenceOrder":294},
  {"id":"s_work_han_thu_108_295","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　服虔曰：「夫羊，地名也。」師古曰：「句山，西山也。句音鉤。」","sentenceOrder":295},
  {"id":"s_work_han_thu_108_296","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　應劭曰：「本漢將築此城。將亡，其妻率餘眾完保之，因以為名也。」張晏曰：「范氏能胡詛者。」","sentenceOrder":296},
  {"id":"s_work_han_thu_108_297","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　如淳曰：「以就誅後，雖復欲降匈奴，不可得。」","sentenceOrder":297},
  {"id":"s_work_han_thu_108_298","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　晉灼曰：「本匈奴官也。功臣表歸義侯僕多子（{雨回}）〔雷〕後以屬國都尉擊匈奴，封煇渠。煇渠，魯（閎）〔陽〕縣也。」師古曰：「眭音息隨反。煇音輝。僕多者，字當為朋。」","sentenceOrder":298},
  {"id":"s_work_han_thu_108_299","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「速邪烏，地名也，燕然山在其中。燕（一音）〔音一〕千反。」","sentenceOrder":299},
  {"id":"s_work_han_thu_108_300","chapterId":"ch_work_han_thu_108","textTraditional":"其明年，單于遣使遺漢書云：「南有大漢，北有強胡。胡者，天之驕子也，不為小禮以自煩。今欲與漢闓大關，取漢女為妻，〔一〕歲給遺我糱酒萬石，稷米五千斛，〔二〕雜繒萬匹，它如故約，則邊不相盜矣。」漢遣使者報送其使，單于使左右難漢使者，曰：「漢，禮義國也。貳師道前太子發兵反，何也？」使者曰：「然。乃丞相私與太子爭鬥，太子發兵欲誅丞相，丞相誣之，故誅丞相。此子弄父兵，罪當笞，小過耳。孰與冒頓單于身殺其父代立，常妻後母，禽獸行也！」單于留使者，三歲乃得還。","sentenceOrder":300},
  {"id":"s_work_han_thu_108_301","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「闓讀與開同。」","sentenceOrder":301},
  {"id":"s_work_han_thu_108_302","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「以糱為酒，味尤甜，稷米，稷粟米也。」","sentenceOrder":302},
  {"id":"s_work_han_thu_108_303","chapterId":"ch_work_han_thu_108","textTraditional":"貳師在匈奴歲餘，衛律害其寵，會母閼氏病，〔一〕律飭胡巫〔二〕言先單于怒，曰：「胡攻時祠兵，常言得貳師以社，〔三〕今何故不用？」於是收貳師，貳師（怒）〔罵〕曰：「我死必滅匈奴！」遂屠貳師以祠。會連雨雪數月，畜產死，人民疫病，穀稼不孰，〔四〕單于恐，為貳師立祠室。","sentenceOrder":303},
  {"id":"s_work_han_thu_108_304","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「單于之母也。」","sentenceOrder":304},
  {"id":"s_work_han_thu_108_305","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「飭與敕同。」","sentenceOrder":305},
  {"id":"s_work_han_thu_108_306","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「以祠社。」","sentenceOrder":306},
  {"id":"s_work_han_thu_108_307","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「北方早寒，雖不宜（黍）〔禾〕稷，匈奴中亦種黍穄。」","sentenceOrder":307},
  {"id":"s_work_han_thu_108_308","chapterId":"ch_work_han_thu_108","textTraditional":"自貳師沒後，漢新失大將軍士卒數萬人，不復出兵。三歲，武帝崩。前此者，漢兵深入窮追二十餘年，匈奴孕重墯殰，罷極苦之〔一〕。自單于以下常有欲和親計。","sentenceOrder":308},
  {"id":"s_work_han_thu_108_309","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「孕重，懷任者也。墯，落也。殰，敗也，音讀。罷讀曰疲。極，困也。苦之，心厭苦也。」","sentenceOrder":309},
  {"id":"s_work_han_thu_108_310","chapterId":"ch_work_han_thu_108","textTraditional":"後三年，單于欲求和親，會病死。初，單于有異母弟為左大都尉，賢，國人鄉之，〔一〕母閼氏恐單于不立子而立左大都尉也，乃私使殺之。左大都尉同母兄怨，遂不肯復會單于庭。又單于病且死，謂諸貴人：「我子少，不能治國，立弟右谷蠡王。」及單于死，衛律等與顓渠閼氏謀，匿單于死，詐撟單于令，〔二〕與貴人飲盟，更立子左谷蠡王為壺衍鞮單于。是歲，始元二年也。","sentenceOrder":310},
  {"id":"s_work_han_thu_108_311","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「鄉讀曰嚮。謂悉皆附之。」","sentenceOrder":311},
  {"id":"s_work_han_thu_108_312","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「撟與矯同，其字從手。矯，託也。」","sentenceOrder":312},
  {"id":"s_work_han_thu_108_313","chapterId":"ch_work_han_thu_108","textTraditional":"壺衍鞮單于既立，風謂漢使者，言欲和親。〔一〕左賢王、右谷蠡王以不得立怨望，率其眾欲南歸漢。恐不能自致，即脅盧屠王，欲與西降烏孫，謀擊匈奴。盧屠王告之，單于使人驗問，右谷蠡王不服，反以其罪罪盧屠王，國人皆冤之。於是二王去居其所，未嘗肯會龍城。〔二〕","sentenceOrder":313},
  {"id":"s_work_han_thu_108_314","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「風讀曰諷，謂不正言也。」","sentenceOrder":314},
  {"id":"s_work_han_thu_108_315","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「各自居其本處，不復會龍城祭。」","sentenceOrder":315},
  {"id":"s_work_han_thu_108_316","chapterId":"ch_work_han_thu_108","textTraditional":"後二年秋，匈奴入代，殺都尉。單于年少初立，母閼氏不正，國內乖離，常恐漢兵襲之。於是衛律為單于謀「穿井築城，治樓以藏穀，與秦人守之。〔一〕漢兵至，無奈我何。」即穿井數百，伐材數千。或曰胡人不能守城，是遺漢糧也，〔二〕衛律於是止，乃更謀歸漢使不降者蘇武、馬宏等。馬宏者，前副光祿大夫王忠使西國，為匈奴所遮，忠戰死，馬宏生得，亦不肯降。故匈奴歸此二人，欲以通善意。是時，單于立三歲矣。","sentenceOrder":316},
  {"id":"s_work_han_thu_108_317","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「秦時有人亡入匈奴者，今其子孫尚號秦人。」","sentenceOrder":317},
  {"id":"s_work_han_thu_108_318","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「遺音弋季反。」","sentenceOrder":318},
  {"id":"s_work_han_thu_108_319","chapterId":"ch_work_han_thu_108","textTraditional":"明年，匈奴發左右部二萬騎，為四隊，〔一〕並入邊為寇。漢兵追之，斬首獲虜九千人，生得甌脫王，漢無所失亡。匈奴見甌脫王在漢，恐以為道擊之，〔二〕即西北遠去，不敢南逐水草，發人民屯甌脫。明年，復遣九千騎屯受降城以備漢，北橋余吾，令可度，〔三〕以備奔走。〔四〕是時，衛律已死。衛律在時，常言和親之利，匈奴不信，及死後，兵數困，國益貧。單于弟左谷蠡王思衛律言，欲和親而恐漢不聽，故不肯先言，常使左右風漢使者。〔五〕然其侵盜益希，遇漢使愈厚，欲以漸致和親，漢亦羈縻之。其後，左谷蠡王死。明年，單于使犁汙王窺邊，言酒泉、張掖兵益弱，出兵試擊，冀可復得其地。時漢先得降者，聞其計，天子詔邊警備。後無幾，右賢王、犁汙王四千騎〔六〕分三隊，入日勒、屋蘭、番和。〔七〕張掖太守、屬國都尉發兵擊，大破之，得脫者數百人。屬國千長義渠王騎士射殺犁汙王，〔八〕賜黃金二百斤，馬二百匹，因封為犁汙王。屬國都尉郭忠封成安侯。自是後，匈奴不敢入張掖。","sentenceOrder":319},
  {"id":"s_work_han_thu_108_320","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「隊，部也，音徒內反。」","sentenceOrder":320},
  {"id":"s_work_han_thu_108_321","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「道讀曰導。」","sentenceOrder":321},
  {"id":"s_work_han_thu_108_322","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「於余吾水上作橋。」","sentenceOrder":322},
  {"id":"s_work_han_thu_108_323","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「擬有迫急，北走避漢，從此橋度也。」","sentenceOrder":323},
  {"id":"s_work_han_thu_108_324","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「風讀曰諷。」","sentenceOrder":324},
  {"id":"s_work_han_thu_108_325","chapterId":"ch_work_han_thu_108","textTraditional":"〔六〕　師古曰：「無幾謂不多時也。幾音居豈反。」","sentenceOrder":325},
  {"id":"s_work_han_thu_108_326","chapterId":"ch_work_han_thu_108","textTraditional":"〔七〕　師古曰：「皆張掖縣也。番音盤。」","sentenceOrder":326},
  {"id":"s_work_han_thu_108_327","chapterId":"ch_work_han_thu_108","textTraditional":"〔八〕　師古曰：「千長者，千人之長。」","sentenceOrder":327},
  {"id":"s_work_han_thu_108_328","chapterId":"ch_work_han_thu_108","textTraditional":"其明年，匈奴三千餘騎入五原，略殺數千人，後數萬騎南旁塞獵，〔一〕行攻塞外亭（長）〔障〕，略取吏民去。是時漢邊郡烽火候望精明，匈奴為邊寇者少利，希復犯塞。漢復得匈奴降者，言烏桓嘗發先單于冢，匈奴怨之，方發二萬騎擊烏桓。大將軍霍光欲發兵（要）〔邀〕擊之，〔二〕以問護軍都尉趙充國。充國以為「烏桓間數犯塞，〔三〕今匈奴擊之，於漢便。又匈奴希寇盜，北邊幸無事。蠻夷自相攻擊，而發兵要之，招寇生事，非計也。」光更問中郎將范明友，明友言可擊。於是拜明友為度遼將軍，將二萬騎出遼東。匈奴聞漢兵至，引去。初，光誠明友：「兵不空出，即後匈奴，遂擊烏桓。」〔四〕烏桓時新中匈奴兵，〔五〕明友既後匈奴，因乘烏桓敝，擊之，斬首六千餘級，獲三王首，還，封為平陵侯。","sentenceOrder":328},
  {"id":"s_work_han_thu_108_329","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「旁音步浪反。」","sentenceOrder":329},
  {"id":"s_work_han_thu_108_330","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「邀迎而擊之。邀音工堯反。」","sentenceOrder":330},
  {"id":"s_work_han_thu_108_331","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「間即中間也，猶言比日也。」","sentenceOrder":331},
  {"id":"s_work_han_thu_108_332","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「後匈奴者，言兵遲後，邀匈奴不及。」","sentenceOrder":332},
  {"id":"s_work_han_thu_108_333","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「為匈奴所中傷。」","sentenceOrder":333},
  {"id":"s_work_han_thu_108_334","chapterId":"ch_work_han_thu_108","textTraditional":"匈奴繇是恐，〔一〕不能出兵。即使使之烏孫，求欲得漢公主。擊烏孫，取車延、惡師地。烏孫公主上書，下公卿議救，未決。昭帝崩，宣帝即位，烏孫昆彌復上書，言「連為匈奴所侵削，昆彌願發國半精兵人馬五萬匹，盡力擊匈奴，唯天子出兵，哀救公主！」本始二年，漢大發關東輕銳士，選郡國吏三百石伉健習騎射者，皆從軍〔二〕。遣御史大夫田廣明為祈連將軍，四萬餘騎，出西河；度遼將軍范明友三萬餘騎，出張掖；前將軍韓增三萬餘騎，出雲中；後將軍趙充國為蒲類將軍，三萬餘騎，出酒泉；雲中太守田順為虎牙將軍，三萬餘騎，出五原：凡五將軍，兵十餘萬騎，出塞各二千餘里。及校尉常惠使護發兵烏孫西域，昆彌自將翕侯以下五萬餘騎從西方入，與五將軍兵凡二十餘萬眾。匈奴聞漢兵大出，老弱奔走，敺畜產遠遁逃〔三〕，是以五將少所得。","sentenceOrder":334},
  {"id":"s_work_han_thu_108_335","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「繇讀與由同。」","sentenceOrder":335},
  {"id":"s_work_han_thu_108_336","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「伉音古浪反。」","sentenceOrder":336},
  {"id":"s_work_han_thu_108_337","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「犇，古奔字。敺與驅同。」","sentenceOrder":337},
  {"id":"s_work_han_thu_108_338","chapterId":"ch_work_han_thu_108","textTraditional":"度遼將軍出塞千二百餘里，至蒲離候水，斬首捕虜七百餘級，鹵獲馬牛羊萬餘。前將軍出塞千二百餘里，至烏員，〔一〕斬首捕虜，至候山百餘級，〔二〕鹵馬牛羊二千餘。蒲類將軍兵當與烏孫合擊匈奴蒲類澤，烏孫先期至而去，漢兵不與相及。蒲類將軍出塞千八百餘里，西去候山，斬首捕虜，得單于使者蒲陰王以下三百餘級，鹵馬牛羊七千餘。聞虜已引去，皆不至期還。天子薄其過，寬而不罪。祁連將軍出塞千六百里，至雞秩山，斬首捕虜十九級，獲牛馬羊百餘。逢漢使匈奴還者冉弘等，言雞秩山西有虜眾，祁連即戒弘，使言無虜，欲還兵。御史屬公孫益壽諫，以為不可，祁連不聽，遂引兵還。虎牙將軍出塞八百餘里，至丹余吾水上，即止兵不進，斬首捕虜千九百餘級，鹵馬牛羊七萬餘，引兵還。上以虎牙將軍不至期，詐增鹵獲，而祁連知虜在前，逗遛不進，〔三〕皆下吏自殺。擢公孫益壽為侍御史。校尉常惠與烏孫兵至右谷蠡庭，獲單于父行〔四〕及嫂、居次、名王、犁汙都尉、千長、將以下三萬九千萬餘級，虜馬牛羊驢驘橐駝七十餘萬。漢封惠為長羅侯。然匈奴民眾死傷而去者，及畜產遠移死（于）〔亡〕不可數勝。於是匈奴遂衰耗，〔五〕怨烏孫。","sentenceOrder":338},
  {"id":"s_work_han_thu_108_339","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「烏員，地名也，音云。」","sentenceOrder":339},
  {"id":"s_work_han_thu_108_340","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「候山，山名也。於此山斬捕得人。」","sentenceOrder":340},
  {"id":"s_work_han_thu_108_341","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　孟康曰：「律語也，謂軍行頓止，稽留不進也。」師古曰：「逗讀與住同，又音豆。」","sentenceOrder":341},
  {"id":"s_work_han_thu_108_342","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「行音胡浪反。」","sentenceOrder":342},
  {"id":"s_work_han_thu_108_343","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「耗，減也，音呼到反。」","sentenceOrder":343},
  {"id":"s_work_han_thu_108_344","chapterId":"ch_work_han_thu_108","textTraditional":"其冬，單于自將萬騎擊烏孫，頗得老弱，欲還。會天大雨雪〔一〕，一日深丈餘，人民畜產凍死，還者不能什一。於是丁令乘弱攻其北，〔二〕烏桓入其東，烏孫擊其西。凡三國所殺數萬級，馬數萬匹，牛羊甚眾。又重以餓死，〔三〕人民死者什三，畜產什五，匈奴大虛弱，諸國羈屬者皆瓦解，攻盜不能理。其後漢出三千餘騎，為三道，並入匈奴，捕虜得數千人還。匈奴終不敢取當，〔四〕茲欲鄉和親，〔五〕而邊境少事矣。","sentenceOrder":344},
  {"id":"s_work_han_thu_108_345","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「雨音于具反。」","sentenceOrder":345},
  {"id":"s_work_han_thu_108_346","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「令音零。」","sentenceOrder":346},
  {"id":"s_work_han_thu_108_347","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「重音直用反。」","sentenceOrder":347},
  {"id":"s_work_han_thu_108_348","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「當者，報其直。」","sentenceOrder":348},
  {"id":"s_work_han_thu_108_349","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「茲，益也。鄉讀曰嚮。」","sentenceOrder":349},
  {"id":"s_work_han_thu_108_350","chapterId":"ch_work_han_thu_108","textTraditional":"壺衍鞮單于立十七年死，弟左賢王立，為虛閭權渠單于。是歲，地節二年也。","sentenceOrder":350},
  {"id":"s_work_han_thu_108_351","chapterId":"ch_work_han_thu_108","textTraditional":"虛閭權渠單于立，以右大將女為大閼氏，而黜前單于所幸顓渠閼氏。顓渠閼氏父左大且渠怨望。是時匈奴不能為邊寇，於是漢罷外城，以休百姓。〔一〕單于聞之喜，召貴人謀，欲與漢和親。左大且渠心害其事，曰：「前漢使來，兵隨其後，今亦效漢發兵，先使使者入。」乃自請與呼盧訾王各將萬騎南旁塞獵，相逢俱入。〔二〕行未到，會三騎亡降漢，言匈奴欲為寇。於是天子詔發邊騎屯要害處，使大將軍軍監治眾等四人〔三〕將五千騎，分三隊，〔四〕出塞各數百里，捕得虜各數十人而還。時匈奴亡其三騎，不敢入，即引去。是歲也，匈奴飢，人民畜產死十六七。又發兩屯各萬騎以備漢。其秋，匈奴前所得西嗕居左地者，〔五〕其君長以下數千人皆驅畜產行，與甌脫戰，所戰殺傷甚眾，遂南降漢。","sentenceOrder":351},
  {"id":"s_work_han_thu_108_352","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「外城，塞外諸城。」","sentenceOrder":352},
  {"id":"s_work_han_thu_108_353","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「訾音子移反。旁音步浪反。」","sentenceOrder":353},
  {"id":"s_work_han_thu_108_354","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「治眾者，軍監之名。」","sentenceOrder":354},
  {"id":"s_work_han_thu_108_355","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「隊音徒內反。」","sentenceOrder":355},
  {"id":"s_work_han_thu_108_356","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　孟康曰：「嗕音辱，匈奴種也。」師古曰：「嗕音奴獨反。」","sentenceOrder":356},
  {"id":"s_work_han_thu_108_357","chapterId":"ch_work_han_thu_108","textTraditional":"其明年，西域城郭共擊匈奴，取車師國，〔一〕得其王及人眾而去。單于復以車師王昆弟兜莫為車師王，收其餘民東徙，不敢居故地。而漢益遣屯士分田車師地以實之。其明年，匈奴怨諸國共擊車師，遣左右大將各萬餘騎屯田右地，欲以侵迫烏孫西域。後二歲，匈奴遣左右奧鞬各六千騎，〔二〕與左大將再擊漢之田車師城者，不能下。其明年，丁令比三歲入盜匈奴，〔三〕殺略人民數千，驅馬畜去。匈奴遣萬餘騎往擊之，無所得。其明年，單于將十萬餘騎旁塞獵，〔四〕欲入邊寇。未至，會其民題除渠堂亡降漢言狀，漢以為言兵鹿奚盧侯，而遣後將軍趙充國將兵四萬餘騎屯緣邊九郡備虜。月餘，單于病歐血，因不敢入，還去，即罷兵。乃使題王都犁胡次等入漢，請和親，未報，會單于死。是歲，神爵二年也。","sentenceOrder":357},
  {"id":"s_work_han_thu_108_358","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「城郭謂諸國為城居者。」","sentenceOrder":358},
  {"id":"s_work_han_thu_108_359","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「奧音郁。鞬音居言反。」","sentenceOrder":359},
  {"id":"s_work_han_thu_108_360","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「比，頻也。」","sentenceOrder":360},
  {"id":"s_work_han_thu_108_361","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「旁音步浪反。」","sentenceOrder":361},
  {"id":"s_work_han_thu_108_362","chapterId":"ch_work_han_thu_108","textTraditional":"虛閭權渠單于立九年死。自始立而黜顓渠閼氏，顓渠閼氏即與右賢王私通。右賢王會龍城而去，顓渠閼氏語以單于病甚，且勿遠。後數日，單于死。郝宿王刑未央使人召諸王，未至，〔一〕顓渠閼氏與其弟左大且渠都隆奇謀，立右賢王屠耆堂為握衍朐鞮單于。握衍朐鞮單于者，代父為右賢王，〔二〕烏維單于耳孫也。","sentenceOrder":362},
  {"id":"s_work_han_thu_108_363","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「郝音呼各反。」","sentenceOrder":363},
  {"id":"s_work_han_thu_108_364","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「朐音劬。」","sentenceOrder":364},
  {"id":"s_work_han_thu_108_365","chapterId":"ch_work_han_thu_108","textTraditional":"握衍朐鞮單于立，復修和親，遣弟伊酋若王勝之入漢獻見。〔一〕單于初立，凶惡，盡殺虛閭權渠時用事貴人刑未央等，而任用顓渠閼氏弟都隆奇，又盡免虛閭權渠子弟近親，而自以其子弟代之。虛閭權渠單于子稽侯狦既不得立，〔二〕亡歸妻父烏禪幕。〔三〕烏禪幕者，本烏孫、康居間小國，數見侵暴，率其眾數千人降匈奴，狐鹿姑單于以其弟子日逐王姊妻之，使長其眾，居右地。〔四〕日逐王先賢撣，其父左賢王當為單于，讓狐鹿姑單于，狐鹿姑單于許立之。國人以故頗言日逐王當為單于。日逐王素與握衍朐鞮單于有隙，即率其眾數萬騎歸漢。漢封日逐王為歸德侯。單于更立其從兄薄胥堂為日逐王。〔五〕","sentenceOrder":365},
  {"id":"s_work_han_thu_108_366","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「酋音材由反。」","sentenceOrder":366},
  {"id":"s_work_han_thu_108_367","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「〈犭冊〉音先安反，又音所姦反。」","sentenceOrder":367},
  {"id":"s_work_han_thu_108_368","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「禪音蟬。」","sentenceOrder":368},
  {"id":"s_work_han_thu_108_369","chapterId":"ch_work_han_thu_108","textTraditional":"〔四〕　師古曰：「長，眾為之長帥。」","sentenceOrder":369},
  {"id":"s_work_han_thu_108_370","chapterId":"ch_work_han_thu_108","textTraditional":"〔五〕　師古曰：「胥音先余反。」","sentenceOrder":370},
  {"id":"s_work_han_thu_108_371","chapterId":"ch_work_han_thu_108","textTraditional":"明年，單于又殺先賢撣兩弟。烏禪幕請之，不聽，心恚。其後左奧鞬王死，單于自立其小子為奧鞬王，留庭。奧鞬貴人共立故奧鞬王子為王，與俱東徙。單于遣右丞相將萬騎往擊之，失亡數千人，不勝。時單于已立二歲，暴虐殺伐，國中不附。及太子、左賢王數讒左地貴人，左地貴人皆怨。其明年，烏桓擊匈奴東邊姑夕王，頗得人民，單于怒。姑夕王恐，即與烏禪幕及左地貴人共立稽侯〈犭冊〉為呼韓邪單于，發左地兵四五萬人，西擊握衍朐鞮單于，至姑且水北。〔一〕未戰，握衍朐鞮單于兵敗走，使人報其弟右賢王曰：「匈奴共攻我，若肯發兵助我乎？」〔二〕右賢王曰：「若不愛人，殺昆弟諸貴人。各自死若處，無來汙我。」〔三〕握衍朐鞮單于恚，自殺。左大且渠都隆奇亡之右賢王所，其民眾盡降呼韓邪單于。是歲，神爵四年也。握衍朐鞮單于立三年而敗。","sentenceOrder":371},
  {"id":"s_work_han_thu_108_372","chapterId":"ch_work_han_thu_108","textTraditional":"〔一〕　師古曰：「且音子余反。」","sentenceOrder":372},
  {"id":"s_work_han_thu_108_373","chapterId":"ch_work_han_thu_108","textTraditional":"〔二〕　師古曰：「若，汝也。其下亦同。」","sentenceOrder":373},
  {"id":"s_work_han_thu_108_374","chapterId":"ch_work_han_thu_108","textTraditional":"〔三〕　師古曰：「言於汝所居處自死。」","sentenceOrder":374},
  {"id":"s_work_han_thu_108_375","chapterId":"ch_work_han_thu_108","textTraditional":"校勘記","sentenceOrder":375},
  {"id":"s_work_han_thu_108_376","chapterId":"ch_work_han_thu_108","textTraditional":"三七四三頁一二行　粥音（戈）〔弋〕六反，　景祐、殿本都作「戈」，此誤。","sentenceOrder":376},
  {"id":"s_work_han_thu_108_377","chapterId":"ch_work_han_thu_108","textTraditional":"三七四五頁一六行　與申（后）〔侯〕有隙。　景祐、殿本都作「侯」。王先謙說「后」字誤。","sentenceOrder":377},
  {"id":"s_work_han_thu_108_378","chapterId":"ch_work_han_thu_108","textTraditional":"三七四七頁　七行　獂音（完）〔桓〕。　景祐、殿本都作「桓」。","sentenceOrder":378},
  {"id":"s_work_han_thu_108_379","chapterId":"ch_work_han_thu_108","textTraditional":"三七八四頁　二行　〔東胡〕卻千餘里。　景祐、殿本都重「東胡」二字。","sentenceOrder":379},
  {"id":"s_work_han_thu_108_380","chapterId":"ch_work_han_thu_108","textTraditional":"三七四八頁　四行　而始皇帝使蒙恬將數十萬之（物）〔眾〕北擊胡，　景祐、殿本都作「眾」，史記同，此誤。","sentenceOrder":380},
  {"id":"s_work_han_thu_108_381","chapterId":"ch_work_han_thu_108","textTraditional":"三七五０頁一二行　若今之伏宿（處）〔舍〕也。　景祐、殿本都作「舍」。","sentenceOrder":381},
  {"id":"s_work_han_thu_108_382","chapterId":"ch_work_han_thu_108","textTraditional":"三七五一頁　四行　其世（信）〔姓〕官號可得而記云。　景祐、殿本都作「姓」，此誤。","sentenceOrder":382},
  {"id":"s_work_han_thu_108_383","chapterId":"ch_work_han_thu_108","textTraditional":"三七五三頁　六行　（龍）新{艹犁}之國。　王念孫、沈欽韓都說「龍」字衍。按史記作「薪犁之國」。","sentenceOrder":383},
  {"id":"s_work_han_thu_108_384","chapterId":"ch_work_han_thu_108","textTraditional":"三七五三頁　八行　窳音（戈）〔弋〕主反。　景祐、殿本都作「弋」，此誤。","sentenceOrder":384},
  {"id":"s_work_han_thu_108_385","chapterId":"ch_work_han_thu_108","textTraditional":"三七五四頁　七行　從解圍之隅（直角）〔角直〕以出去。　殿本作「角直」。王先謙說殿本是。","sentenceOrder":385},
  {"id":"s_work_han_thu_108_386","chapterId":"ch_work_han_thu_108","textTraditional":"三七五八頁　四行　願寢兵休（事）〔士〕。　景祐、殿、局本都作「士」，此誤。","sentenceOrder":386},
  {"id":"s_work_han_thu_108_387","chapterId":"ch_work_han_thu_108","textTraditional":"三七六二頁　九行　使使（遣）〔遺〕匈奴書曰：　景祐、汲古、殿、局本都作「遺」，此誤。","sentenceOrder":387},
  {"id":"s_work_han_thu_108_388","chapterId":"ch_work_han_thu_108","textTraditional":"三七六二頁一一行　（居）〔俱〕無暴虐。　景祐、殿本都作「俱」，此誤。","sentenceOrder":388},
  {"id":"s_work_han_thu_108_389","chapterId":"ch_work_han_thu_108","textTraditional":"三七六二頁一五行　天下莫不咸嘉。（使）漢與匈奴鄰敵之國，　劉奉世疑「使」字衍。王念孫據史記以為「使」是「便」之誤，「嘉」字後人所加，存參。","sentenceOrder":389},
  {"id":"s_work_han_thu_108_390","chapterId":"ch_work_han_thu_108","textTraditional":"三七六三頁　三行　俱蹈大道（也），　劉敞說「也」字衍。按史記無「也」字。","sentenceOrder":390},
  {"id":"s_work_han_thu_108_391","chapterId":"ch_work_han_thu_108","textTraditional":"三七六四頁　三行　（今）〔令〕不追。　景祐、殿本都作「令」，此誤。","sentenceOrder":391},
  {"id":"s_work_han_thu_108_392","chapterId":"ch_work_han_thu_108","textTraditional":"三七六五頁一０行　漢兵約單于入馬邑而縱（兵），　王念孫說「縱」下「兵」字後人以意加之也，史記無。","sentenceOrder":392},
  {"id":"s_work_han_thu_108_393","chapterId":"ch_work_han_thu_108","textTraditional":"三七六九頁　九行　（西）〔而〕減北地以西戍卒半。　劉敞說「西」當作「而」。按史記作「而」。","sentenceOrder":393},
  {"id":"s_work_han_thu_108_394","chapterId":"ch_work_han_thu_108","textTraditional":"三七六九頁一一行　其〔明〕年春，　朱一新說此脫「明」字。王先謙說史記亦有「明」字。","sentenceOrder":394},
  {"id":"s_work_han_thu_108_395","chapterId":"ch_work_han_thu_108","textTraditional":"三七七九頁　三行　御史大夫軍至追（斜）〔邪〕徑，無所見，還。　景祐、殿本都作「邪」。　王先謙說作「邪」是。王念孫說「追邪徑」是地名，與顏注異。","sentenceOrder":395},
  {"id":"s_work_han_thu_108_396","chapterId":"ch_work_han_thu_108","textTraditional":"三七八０頁　七行　歸義侯僕多子（{雨回}）〔雷〕後以屬國都尉擊匈奴。封煇渠。煇渠，魯（閎）〔陽〕縣也。　景祐、殿本「{雨回}」作「雷」。「閎」作「陽」。","sentenceOrder":396},
  {"id":"s_work_han_thu_108_397","chapterId":"ch_work_han_thu_108","textTraditional":"三七八０頁　九行　燕（一音）〔音一〕千反。　景祐、殿、局本都作「一千」，此誤倒。","sentenceOrder":397},
  {"id":"s_work_han_thu_108_398","chapterId":"ch_work_han_thu_108","textTraditional":"三七八一頁　三行　貳師（怒）〔罵〕曰：　景祐、殿本都作「罵」。","sentenceOrder":398},
  {"id":"s_work_han_thu_108_399","chapterId":"ch_work_han_thu_108","textTraditional":"三七八一頁　九行　雖不宜（黍）〔禾〕稷，匈奴中亦種黍穄。　景祐、殿本都作「禾」。","sentenceOrder":399},
  {"id":"s_work_han_thu_108_400","chapterId":"ch_work_han_thu_108","textTraditional":"三七八四頁　六行　行攻塞外亭（長）〔障〕，　錢大昭說「長」當作「障」，按景祐、殿本都作「障」。","sentenceOrder":400},
  {"id":"s_work_han_thu_108_401","chapterId":"ch_work_han_thu_108","textTraditional":"三七八四頁　八行　大將軍霍光欲發兵（要）〔邀〕擊之，　錢大昭說「要」依注當作「邀」。按景祐、殿本都作「邀」。","sentenceOrder":401},
  {"id":"s_work_han_thu_108_402","chapterId":"ch_work_han_thu_108","textTraditional":"三七八六頁一一行　及畜產遠移死（于）〔亡〕不可勝數。　錢大昭說「于」當作「亡」。按景祐、殿、局都作「亡」。","sentenceOrder":402},
  {"id":"s_work_han_thu_109_1","chapterId":"ch_work_han_thu_109","textTraditional":"呼韓邪單于歸庭數月，罷兵使各歸故地，乃收其兄呼屠吾斯在民間者立為左谷蠡王，使人告右賢貴人，欲令殺右賢王。其冬，都隆奇與右賢王共立日逐王薄胥堂為屠耆單于，發兵數萬人東襲呼韓邪單于。呼韓邪單于兵敗走，屠耆單于還，以其長子都塗吾西為左谷蠡王，少子姑瞀樓頭為右谷蠡王，〔一〕留居單于庭。","sentenceOrder":1},
  {"id":"s_work_han_thu_109_2","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「瞀音莫搆反。」","sentenceOrder":2},
  {"id":"s_work_han_thu_109_3","chapterId":"ch_work_han_thu_109","textTraditional":"明年秋，屠耆單于使日逐王先賢撣兄右奧鞬王為烏藉都尉〔一〕各二萬騎，屯東方以備呼韓邪單于。是時，西方呼揭王來與唯犁當戶謀，〔二〕共讒右賢王，言欲自立為烏藉單于。屠耆單于殺右賢王父子，後知其冤，復殺唯犁當戶。於是呼揭王恐，遂畔去，自立為呼揭單于。右奧鞬王聞之，即自立為車犁單于。烏藉都尉亦自立為烏藉單于。凡五單于。屠耆單于自將兵東擊車犁單于，使都隆奇擊烏藉。烏藉、車犁皆敗，西北走，與呼揭單于兵合為四萬人。烏藉、呼揭皆去單于號，共并力尊輔車犁單于。屠耆單于聞之，使左大將、都尉將四萬騎屯東方，以備呼韓邪單于，自將四萬騎西擊車犁單于。車犁單于敗，西北走，屠耆單于即引西南，留闟敦地。〔三〕","sentenceOrder":3},
  {"id":"s_work_han_thu_109_4","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「撣音纏。奧音郁。鞬音居言反。」","sentenceOrder":4},
  {"id":"s_work_han_thu_109_5","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「揭音丘例反。唯音弋癸反。」","sentenceOrder":5},
  {"id":"s_work_han_thu_109_6","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「闟音蹋。敦音頓，又音對。」","sentenceOrder":6},
  {"id":"s_work_han_thu_109_7","chapterId":"ch_work_han_thu_109","textTraditional":"其明年，呼韓邪單于遣其弟右谷蠡王等西襲屠耆單于屯兵，殺略萬餘人。屠耆單于聞之，即自將六萬騎擊呼韓邪單于，行千里，未至嗕姑地，〔一〕逢呼韓邪單于兵可四萬人，合戰。屠耆單于兵敗，自殺。都隆奇乃與屠耆少子右谷蠡王姑瞀樓頭亡歸漢，車犁單于東降呼韓邪單于。呼韓邪單于左大將烏厲屈與父呼遫累烏厲溫敦〔二〕皆見匈奴亂，率其眾數萬人南降漢。封烏厲屈為新城侯，烏厲溫敦為義陽侯。是時李陵子復立烏藉都尉為單于，呼韓邪單于捕斬之，遂復都單于庭，然眾裁數萬人。屠耆單于從弟休旬王將所主五六百騎，擊殺左大且渠，并其兵，至右地，自立為閏振單于，在西邊。其後，呼韓邪單于兄左賢王呼屠吾斯亦自立為郅支骨都侯單于，在東邊。其後二年，閏振單于率其眾東擊郅支單于。郅支單于與戰，殺之，并其兵，遂進攻呼韓邪。呼韓邪破，其兵走，郅支都單于庭。","sentenceOrder":7},
  {"id":"s_work_han_thu_109_8","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「嗕音乃穀反。」","sentenceOrder":8},
  {"id":"s_work_han_thu_109_9","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「呼遫累者，其官號也。遫，古速字也。累音力追反。」","sentenceOrder":9},
  {"id":"s_work_han_thu_109_10","chapterId":"ch_work_han_thu_109","textTraditional":"呼韓邪之敗也，左伊秩訾王為呼韓邪計，勸令稱臣入朝事漢，從漢求助，如此匈奴乃定。呼韓邪議問諸大臣，皆曰：「不可。匈奴之俗，本上氣力而下服役，〔一〕以馬上戰鬥為國，故有威名於百蠻。戰死，壯士所有也。〔二〕今兄弟爭國，不在兄則在弟，雖死猶有威名，子孫常長諸國。〔三〕漢雖彊，猶不能兼并匈奴，奈何亂先古之制，臣事於漢，卑辱先單于，〔四〕為諸國所笑！雖如是而安，何以復長百蠻！」左伊秩訾曰：「不然。彊弱有時，今漢方盛，烏孫城郭諸國皆為臣妾。〔五〕自且鞮侯單于以來，匈奴日削，不能取復〔六〕，雖屈彊於此，未嘗一日安也。〔七〕今事漢則安存，不事則危亡，計何以過此！」諸大人相難久之。呼韓邪從其計，引眾南近塞，遣子右賢王銖婁渠堂入侍。〔八〕郅支單于亦遣子右大將駒于利受入侍。是歲，甘露元年也。","sentenceOrder":10},
  {"id":"s_work_han_thu_109_11","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「以服役於人為下。」","sentenceOrder":11},
  {"id":"s_work_han_thu_109_12","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「言人皆有此事耳。」","sentenceOrder":12},
  {"id":"s_work_han_thu_109_13","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「為諸國之長帥也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_109_14","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「言忝辱之更令卑下也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_109_15","chapterId":"ch_work_han_thu_109","textTraditional":"〔五〕　師古曰：「謂西域諸國為城郭而居也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_109_16","chapterId":"ch_work_han_thu_109","textTraditional":"〔六〕　師古曰：「且音子餘反。復音扶目反。」","sentenceOrder":16},
  {"id":"s_work_han_thu_109_17","chapterId":"ch_work_han_thu_109","textTraditional":"〔七〕　師古曰：「屈音其勿反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_109_18","chapterId":"ch_work_han_thu_109","textTraditional":"〔八〕　師古曰：「婁音力于反。」","sentenceOrder":18},
  {"id":"s_work_han_thu_109_19","chapterId":"ch_work_han_thu_109","textTraditional":"明年，呼韓邪單于款五原塞，〔一〕願朝三年正月。〔二〕漢遣車騎都尉韓昌迎，發過所七郡郡二千騎，為陳道上。〔三〕單于正月朝天子于甘泉宮，漢寵以殊禮，位在諸侯王上，贊謁稱臣而不名。賜以冠帶衣裳，黃金璽盭綬，〔四〕玉具劍，〔五〕佩刀，弓一張，矢四發，〔六〕〈啔，中“口改木”〉戟十，〔七〕安車一乘，鞍勒一具，〔八〕馬十五匹，黃金二十斤，錢二十萬，衣被七十七襲，〔九〕錦鏽綺縠雜帛八千匹，絮六千斤。禮畢，使使者道單于先行，宿長平。〔一０〕上自甘泉宿池陽宮。上登長平，詔單于毋謁，〔一一〕其左右當戶之群臣皆得列觀，及諸蠻夷君長王侯數萬，咸迎於渭橋下，夾道陳。上登渭橋，咸稱萬歲。單于就邸，留月餘，遣歸國。單于自請願留居光祿塞下，〔一二〕有急保漢受降城。〔一三〕漢遣長樂衛尉高昌侯董忠、車騎都尉韓昌將騎萬六千，又發邊郡士馬以千數，送單于出朔方雞鹿塞。〔一四〕詔忠等留衛單于，助誅不服，又轉邊穀米糒，〔一五〕前後三萬四千斛，給贍其食。是歲，郅支單于亦遣使奉獻，漢遇之甚厚。明年，兩單于俱遣使朝獻，漢待呼韓邪使有加。明年，呼韓邪單于復入朝，禮賜如初，加衣百一十襲，錦帛九千匹，絮八千斤。以有屯兵，故不復發騎為送。","sentenceOrder":19},
  {"id":"s_work_han_thu_109_20","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「款，叩也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_109_21","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「會正旦之朝賀也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_109_22","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「所過之郡，每為發兵陳列於道，以為寵衛也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_109_23","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「盭，古戾字。戾，草名也。以戾染綬，亦諸侯王之制也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_109_24","chapterId":"ch_work_han_thu_109","textTraditional":"〔五〕　孟康曰：「摽首鐔衛盡用玉為之也。」師古曰：「鐔，劍口旁橫出者也。衛，劍鼻也。鐔音淫。衛字本作彘，其音同耳。」","sentenceOrder":24},
  {"id":"s_work_han_thu_109_25","chapterId":"ch_work_han_thu_109","textTraditional":"〔六〕　服虔曰：「發，十二矢也。」韋昭曰：「射禮三而止，每射四矢，故以十二為一發也。」師古曰：「發猶今言箭一放兩放也。今則以一矢為一放也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_109_26","chapterId":"ch_work_han_thu_109","textTraditional":"〔七〕　師古曰：「〈啔，中“口改木”〉戟，有衣之戟也。〈啔，中“口改木”〉音啟。」","sentenceOrder":26},
  {"id":"s_work_han_thu_109_27","chapterId":"ch_work_han_thu_109","textTraditional":"〔八〕　師古曰：「勒，馬轡也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_109_28","chapterId":"ch_work_han_thu_109","textTraditional":"〔九〕　師古曰：「一稱為一襲，猶今人之言一副衣服也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_109_29","chapterId":"ch_work_han_thu_109","textTraditional":"〔一０〕師古曰：「道讀曰導。長平，涇水上阪也，解在宣紀。」","sentenceOrder":29},
  {"id":"s_work_han_thu_109_30","chapterId":"ch_work_han_thu_109","textTraditional":"〔一一〕師古曰：「不令拜也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_109_31","chapterId":"ch_work_han_thu_109","textTraditional":"〔一二〕師古曰：「徐自為所築者也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_109_32","chapterId":"ch_work_han_thu_109","textTraditional":"〔一三〕師古曰：「保，守也。於此自守。」","sentenceOrder":32},
  {"id":"s_work_han_thu_109_33","chapterId":"ch_work_han_thu_109","textTraditional":"〔一四〕師古曰：「在朔方窳渾縣西北。」","sentenceOrder":33},
  {"id":"s_work_han_thu_109_34","chapterId":"ch_work_han_thu_109","textTraditional":"〔一五〕師古曰：「糒，乾飯也，音備。」","sentenceOrder":34},
  {"id":"s_work_han_thu_109_35","chapterId":"ch_work_han_thu_109","textTraditional":"始郅支單于以為呼韓邪降漢，兵弱不能復自還，即引其眾西，欲攻定右地。又屠耆單于小弟本侍呼韓邪，亦亡之右地，收兩兄餘兵得數千人，自立為伊利目單于，道逢郅支，合戰，郅支殺之，并其兵五萬餘人。聞漢出兵穀助呼韓邪，即遂留居右地。自度力不能定匈奴，〔一〕乃益西近烏孫，欲與并力，遣使見小昆彌烏就屠。烏就屠見呼韓邪為漢所擁，郅支亡虜，欲攻之以稱漢，〔二〕乃殺郅支使，持頭送都護在所，發八千騎迎郅支。郅支見烏孫兵多，其使又不反，勒兵逢擊烏孫，破之。〔三〕因北擊烏揭，〔四〕烏揭降。發其兵西破堅昆，北降丁令，〔五〕并三國。數遣兵擊烏孫，常勝之。堅昆東去單于庭七千里，南去車師五千里，郅支留都之。","sentenceOrder":35},
  {"id":"s_work_han_thu_109_36","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「度音徒各反。」","sentenceOrder":36},
  {"id":"s_work_han_thu_109_37","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「稱漢朝之意也。稱音尺孕反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_109_38","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「以兵逆之，相逢即擊，故云逢擊。」","sentenceOrder":38},
  {"id":"s_work_han_thu_109_39","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「揭音丘例反。」","sentenceOrder":39},
  {"id":"s_work_han_thu_109_40","chapterId":"ch_work_han_thu_109","textTraditional":"〔五〕　師古曰：「令音零。」","sentenceOrder":40},
  {"id":"s_work_han_thu_109_41","chapterId":"ch_work_han_thu_109","textTraditional":"元帝初即位，呼韓邪單于復上書，言民眾困乏。漢詔雲中、五原郡轉穀二萬斛以給焉。邪支單于自以道遠，又怨漢擁護呼韓邪，遣使上書求侍子。漢遣谷吉送之，郅支殺吉。漢不知吉音問，而匈奴降者言聞甌脫皆殺之。〔一〕呼韓邪單于使來，漢輒簿責之甚急。〔二〕明年，漢遣車騎都尉韓昌、光祿大夫張猛送呼韓邪單于侍子，求問吉等，因赦其罪，勿令自疑。〔三〕昌、猛見單于民眾益盛，塞下禽獸盡，單于足以自衛，不畏郅支。聞其大臣多勸單于北歸者，〔四〕恐北去後難約束，〔五〕昌、猛即與為盟約曰：「自今以來，漢與匈奴合為一家，世世毋得相詐相攻。有竊盜者，相報，行其誅，償其物；〔六〕有寇，發兵相助。漢與匈奴敢先背約者，受天不祥。令其世世子孫盡如盟。」昌、猛與單于及大臣俱登匈奴諾水東山，〔七〕刑白馬，單于以徑路刀金留犁撓酒，〔八〕以老上單于所破月氏王頭為飲器者共飲血盟。昌、猛還奏事，公卿議者以為「單于保塞為藩，雖欲北去，猶不能為危害。昌、猛擅以漢國世世子孫與夷狄詛盟，令單于得以惡言上告于天，羞國家，傷威重，〔九〕不可得行。宜遣使往告祠天，與解盟。昌、猛奉使無狀，罪至不道。」〔一０〕上薄其過，〔一一〕有詔昌、猛以贖論，勿解盟。其後呼韓邪竟北歸庭，人眾稍稍歸之，國中遂定。","sentenceOrder":41},
  {"id":"s_work_han_thu_109_42","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「於甌脫得聲問，云殺之。」","sentenceOrder":42},
  {"id":"s_work_han_thu_109_43","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「簿責，以文簿一一責之也。簿音步戶反。」","sentenceOrder":43},
  {"id":"s_work_han_thu_109_44","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「疑者，疑漢欲討伐也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_109_45","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「塞下無禽獸，則射獵無所得，又不畏郅支，故欲北歸舊處。」","sentenceOrder":45},
  {"id":"s_work_han_thu_109_46","chapterId":"ch_work_han_thu_109","textTraditional":"〔五〕　師古曰：「不可更共為言要。」","sentenceOrder":46},
  {"id":"s_work_han_thu_109_47","chapterId":"ch_work_han_thu_109","textTraditional":"〔六〕　師古曰：「漢人為盜於匈奴，匈奴人為盜於漢，皆相告報而誅償。」","sentenceOrder":47},
  {"id":"s_work_han_thu_109_48","chapterId":"ch_work_han_thu_109","textTraditional":"〔七〕　師古曰：「諾水即今突厥地諾真水也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_109_49","chapterId":"ch_work_han_thu_109","textTraditional":"〔八〕　應劭曰：「徑路，匈奴寶刀也。金，契金也。留犁，飯匕也。撓，和也。契金著酒中，撓攪飲之。」師古曰：「契，刻；撓，攪也，音呼高反。」","sentenceOrder":49},
  {"id":"s_work_han_thu_109_50","chapterId":"ch_work_han_thu_109","textTraditional":"〔九〕　師古曰：「羞，辱也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_109_51","chapterId":"ch_work_han_thu_109","textTraditional":"〔一０〕師古曰：「無狀，蓋無善狀。」","sentenceOrder":51},
  {"id":"s_work_han_thu_109_52","chapterId":"ch_work_han_thu_109","textTraditional":"〔一一〕師古曰：「以其罪過為輕薄。」","sentenceOrder":52},
  {"id":"s_work_han_thu_109_53","chapterId":"ch_work_han_thu_109","textTraditional":"郅支既殺使者，自知負漢，又聞呼韓邪益彊，恐見襲擊，欲遠去。會康居王數為烏孫所困，與諸翕侯計，以為匈奴大國，烏孫素服屬之，今郅支單于困阨在外，可迎置東邊，使合兵取烏孫以立之，〔一〕長無匈奴憂矣。即使使至堅昆通語郅支。郅支素恐，又怨烏孫，聞康居計，大說，〔二〕遂與相結，引兵而西。康居亦遣貴人，橐它驢馬數千匹，迎郅支。郅支人眾中寒道死，〔三〕餘財三千人到康居。〔四〕其後，都護甘延壽與副陳湯發兵即康居誅斬郅支，〔五〕語在延壽、湯傳。","sentenceOrder":53},
  {"id":"s_work_han_thu_109_54","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「言與郅支并力共滅烏孫，以其地立郅支，令居之也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_109_55","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":55},
  {"id":"s_work_han_thu_109_56","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「中寒，傷於寒也。道死，死於道上也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_109_57","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「財與纔同。」","sentenceOrder":57},
  {"id":"s_work_han_thu_109_58","chapterId":"ch_work_han_thu_109","textTraditional":"〔五〕　師古曰：「即，就也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_109_59","chapterId":"ch_work_han_thu_109","textTraditional":"郅支既誅，呼韓邪單于且喜且懼，上書言曰：「常願謁見天子，誠以郅支在西方，恐其與烏孫俱來擊臣，以故未得至漢。今郅支已伏誅，願入朝見。」竟寧元年，單于復入朝，禮賜如初，加衣服錦帛絮，皆倍於黃龍時。單于自言願婿漢氏以自親。〔一〕元帝以後宮良家子王牆字昭君賜單于。單于驩喜，上書願保塞上谷以西至敦煌，〔二〕傳之無窮，請罷邊備塞吏卒，以休天子人民。天子令下有司議，議者皆以為便。郎中侯應習邊事，以為不可許。上問狀，應曰：「周秦以來，匈奴暴桀，寇侵邊境，漢興，尤被其害。臣聞北邊塞至遼東，外有陰山，東西千餘里，草木茂盛，多禽獸，本冒頓單于依阻其中，治作弓矢，來出為寇，是其苑囿也。至孝武世，出師征伐，斥奪此地，攘之於幕北。〔三〕建塞徼，起亭隧，〔四〕築外城，設屯戍，以守之，然後邊境得用少安。幕北地平，少草木，多大沙，匈奴來寇，少所蔽隱，從塞以南，徑深山谷，往來差難。邊長老言匈奴失陰山之後，過之未嘗不哭也。如罷備塞戍卒，示夷狄之大利，不可一也。今聖德廣被，天覆匈奴，〔五〕匈奴得蒙全活之恩，稽首來臣。夫夷狄之情，困則卑順，彊則驕逆，天性然也。前以罷外城，省亭隧，今裁足以候望通烽火而已。古者安不忘危，不可復罷，二也。中國有禮義之教，刑罰之誅，愚民猶尚犯禁，又況單于，能必其眾不犯約哉！三也。〔六〕自中國尚建關梁以制諸侯，所以絕臣下之覬欲也。〔七〕設塞徼，置屯戍，非獨為匈奴而已，亦為諸屬國降民，本故匈奴之人，恐其思舊逃亡，四也。近西羌保塞，與漢人交通，吏民貪利，侵盜其畜產妻子，以此怨恨，起而背畔，世世不絕。今罷乘塞，則生嫚易分爭之漸，五也。〔八〕往者從軍多沒不還者，子孫貧困，一旦亡出，從其親戚，六也。又邊人奴婢愁苦，欲亡者多，曰『聞匈奴中樂，無奈候望急何！』然時有七出塞者，七也。盜賊桀黠，群輩犯法，如其窘急，亡走北出，則不可制，八也。起塞以來百有餘年，非皆以土垣也，或因山巖石，木柴僵落，谿谷水門，〔九〕稍稍平之，卒徒築治，功費久遠，不可勝計。臣恐議者不深慮其終始，欲以壹切省繇戍，〔一０〕十年之外，百歲之內，卒有它變，障塞破壞，亭隧滅絕，當更發屯繕治，累世之功不可卒復，九也。〔一一〕如罷戍卒，省候望，單于自以保塞守御，必深德漢，〔一二〕請求無已。小失其意，則不可測。開夷狄之隙，虧中國之固，十也。非所以永持至安，威制百蠻之長策也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_109_60","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「言欲取漢女而身為漢家婿。」","sentenceOrder":60},
  {"id":"s_work_han_thu_109_61","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「保，守也。自請保守之，令無寇盜。」","sentenceOrder":61},
  {"id":"s_work_han_thu_109_62","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「斥，開也。攘，卻也，音人羊反。」","sentenceOrder":62},
  {"id":"s_work_han_thu_109_63","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「隧謂深開小道而行，避敵鈔寇也。隧音遂。」","sentenceOrder":63},
  {"id":"s_work_han_thu_109_64","chapterId":"ch_work_han_thu_109","textTraditional":"〔五〕　師古曰：「如天之覆也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_109_65","chapterId":"ch_work_han_thu_109","textTraditional":"〔六〕　師古曰：「必，極也，極保之也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_109_66","chapterId":"ch_work_han_thu_109","textTraditional":"〔七〕　師古曰：「覬音冀。」","sentenceOrder":66},
  {"id":"s_work_han_thu_109_67","chapterId":"ch_work_han_thu_109","textTraditional":"〔八〕　師古曰：「乘塞，登之而守也。嫚易猶相欺侮也。易音弋豉反。」","sentenceOrder":67},
  {"id":"s_work_han_thu_109_68","chapterId":"ch_work_han_thu_109","textTraditional":"〔九〕　師古曰：「僵落，謂山上樹木摧折或立死枯僵墮落者。僵音薑。」","sentenceOrder":68},
  {"id":"s_work_han_thu_109_69","chapterId":"ch_work_han_thu_109","textTraditional":"〔一０〕師古曰：「壹切謂權時也，解在平紀。繇讀曰傜。」","sentenceOrder":69},
  {"id":"s_work_han_thu_109_70","chapterId":"ch_work_han_thu_109","textTraditional":"〔一一〕師古曰：「卒讀皆曰猝。」","sentenceOrder":70},
  {"id":"s_work_han_thu_109_71","chapterId":"ch_work_han_thu_109","textTraditional":"〔一二〕師古曰：「於漢自稱恩德也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_109_72","chapterId":"ch_work_han_thu_109","textTraditional":"對奏，天子有詔：「勿議罷邊塞事。」使車騎將軍口諭單于〔一〕曰：「單于上書願罷北邊吏士屯戍，子孫世世保塞。單于鄉慕禮義，〔二〕所以為民計者甚厚，此長久之策也，朕甚嘉之。中國四方皆有關梁障塞，非獨以備塞外也，亦以防中國姦邪放縱，出為寇害，故明法度以專眾心也。敬諭單于之意，〔三〕朕無疑焉。為單于怪其不罷，故使大司馬車騎將軍嘉曉單于。」單于謝曰：「愚不知大計，天子幸使大臣告語，甚厚！」","sentenceOrder":72},
  {"id":"s_work_han_thu_109_73","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「將軍許嘉也。諭謂曉告。」","sentenceOrder":73},
  {"id":"s_work_han_thu_109_74","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":74},
  {"id":"s_work_han_thu_109_75","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「言已曉知其意也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_109_76","chapterId":"ch_work_han_thu_109","textTraditional":"初，左伊秩訾為呼韓邪畫計歸漢，竟以安定。其後或讒伊秩訾自伐其功，常鞅鞅，〔一〕呼韓邪疑之。左伊秩訾懼誅，將其眾千餘人降漢，漢以為關內侯，食邑三百戶，令佩其王印綬。〔二〕及竟寧中，呼韓邪來朝，與伊秩訾相見，謝曰：「王為我計甚厚，令匈奴至今安寧，王之力也，德豈可忘！我失王意，使王去不復顧留，〔三〕皆我過也。今欲白天子，請王歸庭。」伊秩訾曰：「單于賴天命，自歸於漢，得以安寧，單于神靈，天子之祐也，我安得力！既已降漢，又復歸匈奴，是兩心也。願為單于侍（史）〔使〕於漢，不敢聽命。」（四）單于固請不能得而歸。","sentenceOrder":76},
  {"id":"s_work_han_thu_109_77","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「伐謂矜其功力。」","sentenceOrder":77},
  {"id":"s_work_han_thu_109_78","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「雖於漢為關內侯，而依匈奴王號與印綬。」","sentenceOrder":78},
  {"id":"s_work_han_thu_109_79","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「言不復顧念而留住匈奴中。」","sentenceOrder":79},
  {"id":"s_work_han_thu_109_80","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「言為單于充使，留侍於漢，不能還匈奴。」","sentenceOrder":80},
  {"id":"s_work_han_thu_109_81","chapterId":"ch_work_han_thu_109","textTraditional":"王昭君號寧胡閼氏，〔一〕生一男伊屠智牙師，為右日逐王。呼韓邪立二十八年，建始二年死。始呼韓邪嬖左伊秩訾兄呼衍王女二人。長女顓渠閼氏，生二子，長曰且莫車，〔二〕次曰囊知牙斯。少女為大閼氏，生四子，長曰雕陶莫皋，次曰且麋胥，〔三〕皆長於且莫車，少子咸、樂二人，皆小於囊知牙斯。又它閼氏子十餘人。顓渠閼氏貴，且莫車愛。呼韓邪病且死，欲立且莫車，其母顓渠閼氏曰：「匈奴亂十餘年，不絕如髮，賴蒙漢力，故得復安。今平定未久，人民創艾戰鬥，〔四〕且莫車年少，百姓未附，恐復危國。我與大閼氏一家共子，〔五〕不如立雕陶莫皋。」大閼氏曰：「且莫車雖少，大臣共持國事，今舍貴立賤，後世必亂。」〔六〕單于卒從顓渠閼氏計，立雕陶莫皋，約令傳國與弟。呼韓邪死，雕陶莫皋立，為復株絫若鞮單于。〔七〕","sentenceOrder":81},
  {"id":"s_work_han_thu_109_82","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「言胡得之，國以安寧也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_109_83","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「且音子餘反。」","sentenceOrder":83},
  {"id":"s_work_han_thu_109_84","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「且音子餘反。胥音先於反。」","sentenceOrder":84},
  {"id":"s_work_han_thu_109_85","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「創音初亮反。艾讀曰乂。」","sentenceOrder":85},
  {"id":"s_work_han_thu_109_86","chapterId":"ch_work_han_thu_109","textTraditional":"〔五〕　師古曰：「一家，言親姊妹也。共子，兩人所生恩慈無別也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_109_87","chapterId":"ch_work_han_thu_109","textTraditional":"〔六〕　師古曰：「舍謂棄置也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_109_88","chapterId":"ch_work_han_thu_109","textTraditional":"〔七〕　師古曰：「復音服。絫音力追反。」","sentenceOrder":88},
  {"id":"s_work_han_thu_109_89","chapterId":"ch_work_han_thu_109","textTraditional":"復株絫若鞮單于立，遣子右致盧兒王醯諧屠奴侯入侍，以且麋胥為左賢王，且莫車為左谷蠡王，囊知牙斯為右賢王。復株絫單于復妻王昭君，生二女，長女云為須卜居次，〔一〕小女為當于居次。〔二〕","sentenceOrder":89},
  {"id":"s_work_han_thu_109_90","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　李奇曰：「居次者，女之號，若漢言公主也。」文穎曰：「須卜氏，匈奴貴族也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_109_91","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　文穎曰：「當于亦匈奴大族也。」師古曰：「須卜、當于，皆其夫家氏族。」","sentenceOrder":91},
  {"id":"s_work_han_thu_109_92","chapterId":"ch_work_han_thu_109","textTraditional":"河平元年，單于遣右皋林王伊邪莫演等奉獻朝正月。〔一〕既罷，遣使者送至蒱反。〔二〕伊故事，受其降。光祿大夫谷永、議郎杜欽以為「漢興，匈奴數為邊害，故設金爵之賞以待降者。今單于詘體稱臣，列為北藩，遣使朝賀，無有二心，漢家接之，宜異於往時。今既享單于聘貢之質，〔三〕而更受其逋逃之臣，是貪一夫之得而失一國之心，擁有罪之臣而絕慕義之君也。假令單于初立，欲委身中國，未知利害，〔四〕私使伊邪莫演詐降以卜吉凶，受之虧德沮善，〔五〕今單于自疏，不親邊吏；或者設為反間，欲因而生隙，〔六〕受之適合其策，使得歸曲而直責。〔七〕此誠邊竟安危之原，師旅動靜之首，〔八〕不可不詳也。不如勿受，以昭日月之信，抑詐諼之謀，懷附親之心，便」。〔九〕對奏，天子從之。遣中郎將王舜往問降狀。伊邪莫演曰：「我病狂妄言耳。」遣去。歸到，官位如故，不肯令見漢使。明年，單于上書願朝河平四年正月，遂入朝，加賜錦繡繒帛二萬匹，絮二萬斤，它如竟寧時。","sentenceOrder":92},
  {"id":"s_work_han_thu_109_93","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「演音衍。」","sentenceOrder":93},
  {"id":"s_work_han_thu_109_94","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「河東之縣也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_109_95","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「享，當也。質，誠也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_109_96","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「假令猶言或當也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_109_97","chapterId":"ch_work_han_thu_109","textTraditional":"〔五〕　師古曰：「沮，壞也，音材汝反。」","sentenceOrder":97},
  {"id":"s_work_han_thu_109_98","chapterId":"ch_work_han_thu_109","textTraditional":"〔六〕　師古曰：「間音居莧反。」","sentenceOrder":98},
  {"id":"s_work_han_thu_109_99","chapterId":"ch_work_han_thu_109","textTraditional":"〔七〕　師古曰：「歸曲於漢，而以直義來責也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_109_100","chapterId":"ch_work_han_thu_109","textTraditional":"〔八〕　師古曰：「竟讀曰境。」","sentenceOrder":100},
  {"id":"s_work_han_thu_109_101","chapterId":"ch_work_han_thu_109","textTraditional":"〔九〕　師古曰：「諼，詐辭也，音許遠反。」","sentenceOrder":101},
  {"id":"s_work_han_thu_109_102","chapterId":"ch_work_han_thu_109","textTraditional":"復株絫單于立十歲，鴻嘉元年死。弟且麋胥立，為搜諧若鞮單于。","sentenceOrder":102},
  {"id":"s_work_han_thu_109_103","chapterId":"ch_work_han_thu_109","textTraditional":"搜諧單于立，遣子左祝都韓王朐留斯侯入侍，〔一〕以且莫車為左賢王。搜諧單于立八歲，元延元年，為朝二年發行，〔二〕未入塞，病死。弟且莫車立，為車牙若鞮單于。","sentenceOrder":103},
  {"id":"s_work_han_thu_109_104","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「朐音許于反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_109_105","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「欲會二年歲首之朝（會）〔禮〕，故豫發其國而行。」","sentenceOrder":105},
  {"id":"s_work_han_thu_109_106","chapterId":"ch_work_han_thu_109","textTraditional":"搜諧單于立，遣子左祝都韓王朐留斯侯入侍，〔一〕以且莫車為左賢王。搜諧單于立八","sentenceOrder":106},
  {"id":"s_work_han_thu_109_107","chapterId":"ch_work_han_thu_109","textTraditional":"車牙單于立，遣子右於涂仇撣王烏夷當入侍，〔一〕以囊知牙斯為左賢王。車牙單于立四歲，綏和元年死。弟囊知牙斯立，為烏珠留若鞮單于。","sentenceOrder":107},
  {"id":"s_work_han_thu_109_108","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「涂音徒。撣音纏。」","sentenceOrder":108},
  {"id":"s_work_han_thu_109_109","chapterId":"ch_work_han_thu_109","textTraditional":"烏珠留單于立，以第二閼氏子樂為左賢王，以第五閼氏子輿為右賢王，〔一〕遣子右股奴王烏鞮牙斯入侍。漢遣中郎將夏侯藩、副校尉韓容使匈奴。時帝舅大司馬票騎將軍王根領尚書事，或說根曰：「匈奴有斗入漢地，直張掖郡，〔二〕生奇材木，箭竿就羽，〔三〕如得之，於邊甚饒，國家有廣地之實，將軍顯功，垂於無窮。」根為上言其利，上直欲從單于求之，〔四〕為有不得，傷命損威。〔五〕根即但以上指曉藩，令從藩所說而求之。〔六〕藩至匈奴，以語次說單于曰：「竊見匈奴斗入漢地，直張掖郡。漢三都尉居塞上，士卒數百人寒苦，候望久勞。單于宜上書獻此地，直斷閼之，省兩都尉士卒數百人，以復天子厚恩，〔七〕其報必大。」〔八〕單于曰：「此天子詔語邪，將從使者所求也？」藩曰：「詔指也，然藩亦為單于畫善計耳。」單于曰：「孝宣、孝元皇帝哀憐父呼韓邪單于，從長城以北匈奴有之。此溫偶駼王所居地也，〔九〕未曉其形狀所生，請遣使問之。」〔一０〕藩、容歸漢。從復使匈奴，至則求地。單于曰：「父兄傳五世，漢不求此地，至知獨求，何也？已問溫偶駼王，匈奴西邊諸侯作穹廬及車，皆仰此山材木，〔一一〕且先父地，不敢失也。」藩還，遷為太原太守。單于遣使上書，以藩求地狀聞。詔報單于曰：「藩擅稱詔從單于求地，法當死，更大赦二，〔一二〕今徙藩為濟南太守，不令當匈奴。」明年，侍子死，歸葬。復遣子左於駼仇撣王稽留昆入侍。〔一三〕","sentenceOrder":109},
  {"id":"s_work_han_thu_109_110","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「此二人皆烏珠留之弟也。第二閼氏，即上所謂大閼氏也。第五閼氏，亦呼韓邪單于之閼氏。」","sentenceOrder":110},
  {"id":"s_work_han_thu_109_111","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「斗，絕也。宜，當也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_109_112","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「就，大雕也，黃頭赤目，其羽可為箭。竿音工旱反。」","sentenceOrder":112},
  {"id":"s_work_han_thu_109_113","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「直猶正耳。」","sentenceOrder":113},
  {"id":"s_work_han_thu_109_114","chapterId":"ch_work_han_thu_109","textTraditional":"〔五〕　師古曰：「詔命不行，故云傷命也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_109_115","chapterId":"ch_work_han_thu_109","textTraditional":"〔六〕　師古曰：「自以藩意說單于而求之。」","sentenceOrder":115},
  {"id":"s_work_han_thu_109_116","chapterId":"ch_work_han_thu_109","textTraditional":"〔七〕　師古曰：「復亦報。」","sentenceOrder":116},
  {"id":"s_work_han_thu_109_117","chapterId":"ch_work_han_thu_109","textTraditional":"〔八〕　師古曰：「漢得此地，必厚報賞單于。」","sentenceOrder":117},
  {"id":"s_work_han_thu_109_118","chapterId":"ch_work_han_thu_109","textTraditional":"〔九〕　師古曰：「偶音五口反。駼音塗。次下亦同。」","sentenceOrder":118},
  {"id":"s_work_han_thu_109_119","chapterId":"ch_work_han_thu_109","textTraditional":"〔一０〕師古曰：「所生，謂山之所出草木、鳥獸為用者。」","sentenceOrder":119},
  {"id":"s_work_han_thu_109_120","chapterId":"ch_work_han_thu_109","textTraditional":"〔一一〕師古曰：「謂諸小王為諸侯者，效中國之言耳。仰音牛向反。」","sentenceOrder":120},
  {"id":"s_work_han_thu_109_121","chapterId":"ch_work_han_thu_109","textTraditional":"〔一二〕師古曰：「更，經也，音功衡反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_109_122","chapterId":"ch_work_han_thu_109","textTraditional":"〔一三〕師古曰：「撣音纏。稽音雞。」","sentenceOrder":122},
  {"id":"s_work_han_thu_109_123","chapterId":"ch_work_han_thu_109","textTraditional":"至哀帝建平二年，烏孫庶子卑援疐〔一〕翕侯人眾入匈奴西界，寇盜牛畜，頗殺其民。單于聞之，遣左大當戶烏夷泠〔二〕將五千騎擊烏孫，殺數百人，略千餘人，敺牛畜去。〔三〕卑援疐恐，遣子趨逯為質匈奴。〔四〕單于受，以狀聞。漢遣中郎將丁野林、副校尉公乘音使匈奴，責讓單于，告令還歸卑援疐質子。單于受詔，遣歸。","sentenceOrder":123},
  {"id":"s_work_han_thu_109_124","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「援音爰。疐音竹二反。」","sentenceOrder":124},
  {"id":"s_work_han_thu_109_125","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「泠音零。」","sentenceOrder":125},
  {"id":"s_work_han_thu_109_126","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「敺與驅同。」","sentenceOrder":126},
  {"id":"s_work_han_thu_109_127","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「逯音錄。」","sentenceOrder":127},
  {"id":"s_work_han_thu_109_128","chapterId":"ch_work_han_thu_109","textTraditional":"建平四年，單于上書願朝五年。時哀帝被疾，或言匈奴從上游來厭人，〔一〕自黃龍、竟寧時，單于朝中國輒有大故。〔二〕上由是難之，以問公卿，亦以為虛費府帑，〔三〕可且勿許。單于使辭去，未發，黃門郎揚雄上書諫曰：","sentenceOrder":128},
  {"id":"s_work_han_thu_109_129","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　服虔曰：「游猶流也。河水從西北來，故曰上游也。」師古曰：「上游，亦總謂地形耳，不必係於河水也。厭音一涉反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_109_130","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「大故謂國之大喪。」","sentenceOrder":130},
  {"id":"s_work_han_thu_109_131","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「府，物所聚也。帑，藏金帛之所也，音它莽反，又音奴。」","sentenceOrder":131},
  {"id":"s_work_han_thu_109_132","chapterId":"ch_work_han_thu_109","textTraditional":"臣聞六經之治，貴於未亂；兵家之勝，貴於未戰。〔一〕二者皆微，〔二〕然而大事之本，不可不察也。今單于上書求朝，國家不許而辭之，臣愚以為漢與匈奴從此隙矣。本北地之狄，五帝所不能臣，三王所不能制，其不可使隙甚明。臣不敢遠稱，請引秦以來明之：","sentenceOrder":132},
  {"id":"s_work_han_thu_109_133","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「已亂而後治之，戰鬥而後獲勝，則不足貴。」","sentenceOrder":133},
  {"id":"s_work_han_thu_109_134","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「微謂精妙也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_109_135","chapterId":"ch_work_han_thu_109","textTraditional":"以秦始皇之彊，蒙恬之威，帶甲四十餘萬，然不敢窺西河，乃築長城以界之。會漢初興，以高祖之威靈，三十萬眾困於平城，士或七日不食。時奇譎之士石畫之臣甚眾，〔一〕卒其所以脫者，世莫得而言也。〔二〕又高皇后嘗忿匈奴，群臣庭議，樊噲請以十萬眾橫行匈奴中，季布曰：「噲可斬也，妄阿順指！」於是大臣權書遺之，〔三〕然後匈奴之結解，中國之憂平。及孝文時，匈奴侵暴北邊，候騎至雍甘泉，京師大駭，發三將軍屯細柳、棘門、霸上以備之，數月乃罷。孝武即位，設馬邑之權，欲誘匈奴，使韓安國將三十萬眾徼於便墬，〔四〕　匈奴覺之而去，徒費財勞師，一虜不可得見，況單于之面乎！其後深惟社稷之計，規恢萬載之策，〔五〕乃大興師數十萬，使衛青、霍去病操兵，前後十餘年。〔六〕於是浮西河，絕大幕，破寘顏，襲王庭，窮極其地，追奔逐北，封狼居胥山，禪於姑衍，以臨翰海，〔七〕虜名王貴人以百數。自是之後，匈奴震怖，益求和親，然而未肯稱臣也。","sentenceOrder":135},
  {"id":"s_work_han_thu_109_136","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　鄧展曰：「石，大也。」師古曰：「石言堅固如石也。畫，計策也，音獲。」","sentenceOrder":136},
  {"id":"s_work_han_thu_109_137","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「卒，終也。莫得而言，謂自免之計，其事醜惡，故不傳。」","sentenceOrder":137},
  {"id":"s_work_han_thu_109_138","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「以權道為書，順辭以答之。」","sentenceOrder":138},
  {"id":"s_work_han_thu_109_139","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「徼，要也，音工堯反。墬，古地字。」","sentenceOrder":139},
  {"id":"s_work_han_thu_109_140","chapterId":"ch_work_han_thu_109","textTraditional":"〔五〕　師古曰：「恢，大也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_109_141","chapterId":"ch_work_han_thu_109","textTraditional":"〔六〕　師古曰：「操，持也，音千高反。」","sentenceOrder":141},
  {"id":"s_work_han_thu_109_142","chapterId":"ch_work_han_thu_109","textTraditional":"〔七〕　師古曰：「積土為封，而又禪祭也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_109_143","chapterId":"ch_work_han_thu_109","textTraditional":"且夫前世豈樂傾無量之費，役無罪之人，快心於狼望之北哉？〔一〕以為不壹勞者不久佚，不蹔費者不永寧，〔二〕是以忍百萬之師以摧餓虎之喙，運府庫之財填盧山之壑而不悔也。〔三〕至本始之初，匈奴有桀心，〔四〕欲掠烏孫，侵公主，乃發五將之師十五萬騎獵其南，而長羅侯以烏孫五萬騎震其西，皆至質而還。〔五〕時鮮有所獲，〔六〕徒奮揚威武，明漢兵若雷風耳。雖空行空反，尚誅兩將軍。故北狄不服，中國未得高枕安寢也。逮至元康、神爵之間，大化神明，鴻恩溥洽，而匈奴內亂，五單于爭立，日逐、呼韓邪攜國歸（死）〔化〕，扶伏稱臣，〔七〕然尚羈縻之，計不顓制。〔八〕自此之後，欲朝者不距，不欲者不彊。〔九〕何者？外國天性忿鷙〔一０〕，形容魁健，〔一一〕負力怙氣，〔一二〕難化以善，易〈頴，中“頁改聿”〉以惡，〔一三〕其彊難詘，其和難得。故未服之時，勞師遠攻，傾國殫貨，伏尸流血，破堅拔敵，如彼之難也；既服之後，慰薦撫循，交接賂遺，威儀俯仰，如此之備也。往時嘗屠大宛之城，蹈烏桓之壘，探姑繒之壁，〔一四〕籍蕩姐之場，〔一五〕艾朝鮮之旃，拔兩越之旗，〔一六〕近不過旬月之役，遠不離二時之勞，〔一七〕固已犁其庭，掃其閭，〔一八〕郡縣而置之，雲徹席卷，後無餘菑。〔一九〕唯北狄為不然，真中國之堅敵也，三垂比之懸矣，前世重之茲甚，〔二０〕未易可輕也。","sentenceOrder":143},
  {"id":"s_work_han_thu_109_144","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「匈奴中地名也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_109_145","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「佚與逸同。」","sentenceOrder":145},
  {"id":"s_work_han_thu_109_146","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「喙，口也，摧百萬之師於獸口也。盧山，匈奴中山也。喙音許穢反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_109_147","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「桀，堅也。言其起立不順。」","sentenceOrder":147},
  {"id":"s_work_han_thu_109_148","chapterId":"ch_work_han_thu_109","textTraditional":"〔五〕　師古曰：「質，信也，謂所期處。」","sentenceOrder":148},
  {"id":"s_work_han_thu_109_149","chapterId":"ch_work_han_thu_109","textTraditional":"〔六〕　師古曰：「鮮，少也，音先踐反。」","sentenceOrder":149},
  {"id":"s_work_han_thu_109_150","chapterId":"ch_work_han_thu_109","textTraditional":"〔七〕　師古曰：「伏音蒲北反。」","sentenceOrder":150},
  {"id":"s_work_han_thu_109_151","chapterId":"ch_work_han_thu_109","textTraditional":"〔八〕　師古曰：「顓與專同。專制謂以為臣妾也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_109_152","chapterId":"ch_work_han_thu_109","textTraditional":"〔九〕　師古曰：「彊音其兩反。」","sentenceOrder":152},
  {"id":"s_work_han_thu_109_153","chapterId":"ch_work_han_thu_109","textTraditional":"〔一０〕師古曰：「鷙，佷也，音竹二反。」","sentenceOrder":153},
  {"id":"s_work_han_thu_109_154","chapterId":"ch_work_han_thu_109","textTraditional":"〔一一〕師古曰：「魁，大也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_109_155","chapterId":"ch_work_han_thu_109","textTraditional":"〔一二〕師古曰：「負，恃也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_109_156","chapterId":"ch_work_han_thu_109","textTraditional":"〔一三〕師古曰：「〈頴，中“頁改聿”〉謂附屬之也。惡謂威也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_109_157","chapterId":"ch_work_han_thu_109","textTraditional":"〔一四〕師古曰：「姑繪，謂西南夷種也，在益州，見昭紀也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_109_158","chapterId":"ch_work_han_thu_109","textTraditional":"〔一五〕劉德曰：「羌屬也。」師古曰：「籍猶蹈也。姐音紫。」","sentenceOrder":158},
  {"id":"s_work_han_thu_109_159","chapterId":"ch_work_han_thu_109","textTraditional":"〔一六〕師古曰：「艾讀曰刈。刈，絕也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_109_160","chapterId":"ch_work_han_thu_109","textTraditional":"〔一七〕師古曰：「離，歷也。三月為一時。」","sentenceOrder":160},
  {"id":"s_work_han_thu_109_161","chapterId":"ch_work_han_thu_109","textTraditional":"〔一八〕師古曰：「犁，耕也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_109_162","chapterId":"ch_work_han_thu_109","textTraditional":"〔一九〕師古曰：「菑，古災字也。」","sentenceOrder":162},
  {"id":"s_work_han_thu_109_163","chapterId":"ch_work_han_thu_109","textTraditional":"〔二０〕師古曰：「茲，益也。」","sentenceOrder":163},
  {"id":"s_work_han_thu_109_164","chapterId":"ch_work_han_thu_109","textTraditional":"今單于歸義，懷款誠之心，欲離其庭，陳見於前，此乃上世之遺策，神靈之所想望，國家雖費，不得已者也。〔一〕奈何距以來厭之辭，疏以無日之期，消往昔之恩，開將來之隙！夫款而隙之，使有恨心，負前言，緣往辭，〔二〕歸怨於漢，因以自絕，終無北面之心，威之不可，諭之不能，焉得不為大憂乎！夫明者視於無形，聰者聽於無聲，誠先於未然，即蒙恬、樊噲不復施，棘門、細柳不復備，馬邑之策安所設，衛、霍之功何得用，五將之威安所震？〔三〕不然，壹有隙之後，雖智者勞心於內，辯者轂擊於外，〔四〕猶不若未然之時也。且往者圖西域，制車師，〔五〕置城郭都護三十六國，費歲以大萬計者，〔六〕豈為康居、烏孫能踰白龍堆而寇西邊哉？〔七〕乃以制匈奴也。夫百年勞之，一日失之，費十而愛一，臣竊為國不安也。唯陛下少留意於未亂未戰，以遏邊萌之禍。","sentenceOrder":164},
  {"id":"s_work_han_thu_109_165","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「已，止也。」","sentenceOrder":165},
  {"id":"s_work_han_thu_109_166","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「言單于因緣往昔和好之辭以怨漢也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_109_167","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「先於未然，謂計策素定，禦難折衝。」","sentenceOrder":167},
  {"id":"s_work_han_thu_109_168","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「轂擊，言使車交馳，其轂相擊也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_109_169","chapterId":"ch_work_han_thu_109","textTraditional":"〔五〕　師古曰：「圖，謀也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_109_170","chapterId":"ch_work_han_thu_109","textTraditional":"〔六〕　師古曰：「財用之費，一歲數百萬也。」","sentenceOrder":170},
  {"id":"s_work_han_thu_109_171","chapterId":"ch_work_han_thu_109","textTraditional":"〔七〕　孟康曰：「龍堆形如土龍身，無頭有尾，高大者二三丈，埤者丈餘，皆東北向，相似也，在西域中。」","sentenceOrder":171},
  {"id":"s_work_han_thu_109_172","chapterId":"ch_work_han_thu_109","textTraditional":"書奏，天子寤焉，召還匈奴使者，更報單于書而許之。賜雄帛五十匹，黃金十斤。單于未發，會病，復遣使願朝明年。故事，單于朝，從名王以下及從者二百餘人。單于又上書言：「蒙天子神靈，人民盛壯，願從五百人入朝，以明天子盛德。」上皆許之。","sentenceOrder":172},
  {"id":"s_work_han_thu_109_173","chapterId":"ch_work_han_thu_109","textTraditional":"元壽二年，單于來朝，上以太歲厭勝所在，〔一〕舍之上林苑蒲陶宮。〔二〕告之以加敬於單于，〔三〕單于知之。加賜衣三百七十襲，錦繡繒帛三萬匹，絮三萬斤，它如河平時。既罷，遣中郎將韓況送單于。單于出塞，到休屯井，北度車田盧水，道里回遠。〔四〕況等乏食，單于乃給其糧，失期不還五十餘日。","sentenceOrder":173},
  {"id":"s_work_han_thu_109_174","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「厭音一涉反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_109_175","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「舍，止宿。」","sentenceOrder":175},
  {"id":"s_work_han_thu_109_176","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「云以敬於單于，故令止上林。」","sentenceOrder":176},
  {"id":"s_work_han_thu_109_177","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「回音胡內反。」","sentenceOrder":177},
  {"id":"s_work_han_thu_109_178","chapterId":"ch_work_han_thu_109","textTraditional":"初，上遣稽留昆隨單于去，到國，復遣稽留昆同母兄右大且方與婦入侍。〔一〕還歸，復遣且方同母兄左日逐王都與婦入侍。是時，漢平帝幼，太皇太后稱制，新都侯王莽秉政，欲說太后以威德至盛異於前，〔二〕乃風單于〔三〕令遣王昭君女須卜居次云入侍〔四〕太后，所以賞賜之甚厚。","sentenceOrder":178},
  {"id":"s_work_han_thu_109_179","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「且音子閭反。」","sentenceOrder":179},
  {"id":"s_work_han_thu_109_180","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「說讀曰悅。以此事取悅於太后。」","sentenceOrder":180},
  {"id":"s_work_han_thu_109_181","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　帥古曰：「風讀曰諷。」","sentenceOrder":181},
  {"id":"s_work_han_thu_109_182","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「云者，其女名。」","sentenceOrder":182},
  {"id":"s_work_han_thu_109_183","chapterId":"ch_work_han_thu_109","textTraditional":"會西域車師後王句姑、〔一〕去胡來王唐兜〔二〕皆怨恨都護校尉，將妻子人民亡降匈奴，語在西域傳。單于受置左谷蠡地，遣使上書言狀曰：「臣謹已受。」詔書中郎將韓隆、王昌、副校尉甄阜、侍中謁者帛敞、長水校尉王歙使匈奴，〔三〕告單于曰：「西域內屬，不當得受，〔四〕今遣之。」〔五〕單于曰：「孝宣、孝元皇帝哀憐，為作約束，自長城以南天子有之，長城以北單于有之。有犯塞，輒以狀聞；有降者，不得受。臣知父呼韓邪單于蒙無量之恩，死遺言曰：『有從中國來降者，勿受，輒送至塞，以報天子厚恩。』此外國也，得受之。」使者曰：「匈奴骨肉相攻，國幾絕，〔六〕蒙中國大恩，危亡復續，妻子完安，累世相繼，宜有以報厚恩。」單于叩頭謝罪，執二虜還付使者。詔使中郎將王萌待西域惡都奴界上逆受。〔七〕單于遣使送到國，因請其罪。使者以聞，有詔不聽，〔八〕會西域諸國王斬以示之。乃造設四條：〔九〕中國人亡入匈奴者，烏孫亡降匈奴者，西域諸國佩中國印綬降匈奴者，烏桓降匈奴者，皆不得受。遣中郎將王駿、王昌、副校尉甄阜、王尋使匈奴，班四條與單于，雜函封，〔一０〕付單于，令奉行，因收故宣帝所為約束封函還。時，莽奏令中國不得有二名，因使使者以風單于，〔一一〕宜上書慕化，為一名，漢必加厚賞。單于從之，上書言：「幸得備藩臣，竊樂太平聖制，臣故名囊知牙斯，今謹更名曰知。」莽大說，〔一二〕白太后，遣使者答諭，厚賞賜焉。","sentenceOrder":183},
  {"id":"s_work_han_thu_109_184","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「句音鉤。」","sentenceOrder":184},
  {"id":"s_work_han_thu_109_185","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「為其去胡而來降漢，故以為王號。」","sentenceOrder":185},
  {"id":"s_work_han_thu_109_186","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「歙音翁。」","sentenceOrder":186},
  {"id":"s_work_han_thu_109_187","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「既屬漢家，不得復臣匈奴。」","sentenceOrder":187},
  {"id":"s_work_han_thu_109_188","chapterId":"ch_work_han_thu_109","textTraditional":"〔五〕　師古曰：「今既遣還。」","sentenceOrder":188},
  {"id":"s_work_han_thu_109_189","chapterId":"ch_work_han_thu_109","textTraditional":"〔六〕　師古曰：「幾音鉅依反。」","sentenceOrder":189},
  {"id":"s_work_han_thu_109_190","chapterId":"ch_work_han_thu_109","textTraditional":"〔七〕　服虔曰：「惡都奴，西域之谷名也。」師古曰：「逆受，迎而受之。」","sentenceOrder":190},
  {"id":"s_work_han_thu_109_191","chapterId":"ch_work_han_thu_109","textTraditional":"〔八〕　師古曰：「不免其罪。」","sentenceOrder":191},
  {"id":"s_work_han_thu_109_192","chapterId":"ch_work_han_thu_109","textTraditional":"〔九〕　師古曰：「更新為此制也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_109_193","chapterId":"ch_work_han_thu_109","textTraditional":"〔一０〕師古曰：「與璽書同一函而封之。」","sentenceOrder":193},
  {"id":"s_work_han_thu_109_194","chapterId":"ch_work_han_thu_109","textTraditional":"〔一一〕師古曰：「風讀曰諷。」","sentenceOrder":194},
  {"id":"s_work_han_thu_109_195","chapterId":"ch_work_han_thu_109","textTraditional":"〔一二〕師古曰：「說讀曰悅。」","sentenceOrder":195},
  {"id":"s_work_han_thu_109_196","chapterId":"ch_work_han_thu_109","textTraditional":"漢既班四條，後護烏桓使者告烏桓民，毋得復與匈奴皮布稅。匈奴以故事遣使者責烏桓稅，〔一〕匈奴人民婦女欲賈販者皆隨往焉。烏桓距曰：「奉天子詔條，（之）〔不〕當予匈奴稅。」匈奴使怒，收烏桓酋豪，縛到懸之。酋豪昆弟怒，共（入）〔殺〕匈奴使及其官屬，收略婦女馬牛。單于聞之，遣使發左賢王兵入烏桓責殺使者，因攻擊之。烏桓分散，或走上山，或東保塞。匈奴頗殺人民，敺婦女弱小且千人去，〔二〕置左地，告烏桓曰：「持馬畜皮布來贖之。」烏桓見略者親屬二千餘人持財畜往贖，匈奴受，留不遣。〔三〕","sentenceOrder":196},
  {"id":"s_work_han_thu_109_197","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「故時常稅，是以求之。」","sentenceOrder":197},
  {"id":"s_work_han_thu_109_198","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「敺與驅同。」","sentenceOrder":198},
  {"id":"s_work_han_thu_109_199","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「受其皮布而留人不遣。」","sentenceOrder":199},
  {"id":"s_work_han_thu_109_200","chapterId":"ch_work_han_thu_109","textTraditional":"王莽之篡位也，建國元年，遣五威將王駿率甄阜、王颯、陳饒、帛敞、丁業六人，〔一〕多齎金帛，重遺單于，諭曉以受命代漢狀，因易單于故印。故印文曰「匈奴單于璽」，莽更曰「新匈奴單于章」。〔二〕將率既至，授單于印紱，〔三〕詔令上故印紱。單于再拜受詔。譯前，欲解取故印紱，單于舉掖授之。左姑夕侯蘇從旁謂單于曰：「未見新印文，宜且勿與。」單于止，不肯與。請使者坐穹廬，單于欲前為壽。五威將曰：「故印紱當以時上。」單于曰：「諾。」復舉掖授譯。蘇復曰：「未見印文，且勿與。」單于曰：「印文何由變更！」遂解故印紱奉上，將率受。著新紱，不解視印，飲食至夜乃罷。右率陳饒謂諸將率曰：「鄉者姑夕侯疑印文，幾令單于不與人〔四〕。如令視印，見其變改，必求故印，此非辭說所能距也。既得而復失之，辱命莫大焉。不如椎破故印，以絕禍根。」將率猶與，莫有應者。〔五〕饒，燕士，果悍，〔六〕即引斧椎壞之。明日，單于果遣右骨都侯當白將率曰：「漢賜單于印，言『璽』不言『章』，又無『漢』字，諸王已下乃有『漢』言『章』。今（印）〔即〕去『璽』加『新』，與臣下無別。願得故印。」將率示以故印，謂曰：「新室順天制作，故印隨將率所自為破壞。單于宜奉天命，奉新室之制。」當還白，單于知已無可奈何，又多得賂遺，即遣弟右賢王輿奉馬牛隨將率入謝，因上書求故印。","sentenceOrder":200},
  {"id":"s_work_han_thu_109_201","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「颯音立。」","sentenceOrder":201},
  {"id":"s_work_han_thu_109_202","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「新者，莽自係其國號。」","sentenceOrder":202},
  {"id":"s_work_han_thu_109_203","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「紱者，印之組也，音弗。」","sentenceOrder":203},
  {"id":"s_work_han_thu_109_204","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「鄉讀曰嚮。幾音鉅音依反。」","sentenceOrder":204},
  {"id":"s_work_han_thu_109_205","chapterId":"ch_work_han_thu_109","textTraditional":"〔五〕　師古曰：「與讀曰豫。」","sentenceOrder":205},
  {"id":"s_work_han_thu_109_206","chapterId":"ch_work_han_thu_109","textTraditional":"〔六〕　師古曰：「果，決也。悍，勇也，音胡幹反。」","sentenceOrder":206},
  {"id":"s_work_han_thu_109_207","chapterId":"ch_work_han_thu_109","textTraditional":"將率還到左犁汗王咸所居地，見烏桓民多，以問咸。咸具言狀，〔一〕將率曰：「前封四條，不得受烏桓降者，亟還之。」〔二〕咸曰：「請密與單于相聞，得語，歸之。」單于使咸報曰：「當從塞內還之邪，從塞外還之邪？」將率不敢顓決，以聞。詔報，從塞外還之。","sentenceOrder":207},
  {"id":"s_work_han_thu_109_208","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「謂前驅略得婦女弱小，贖之不還者。」","sentenceOrder":208},
  {"id":"s_work_han_thu_109_209","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「亟，急也，音居力反。」","sentenceOrder":209},
  {"id":"s_work_han_thu_109_210","chapterId":"ch_work_han_thu_109","textTraditional":"單于始用夏侯藩求地有距漢語，後以求稅烏桓不得，因寇略其人民，釁由是生，重以印文改易，〔一〕故怨恨。乃遣右大且渠蒲呼盧訾等十餘人將兵眾萬騎，以謢送烏桓為名，〔二〕勒兵朔方塞下。朔方太守以聞。","sentenceOrder":210},
  {"id":"s_work_han_thu_109_211","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「重音直用反。」","sentenceOrder":211},
  {"id":"s_work_han_thu_109_212","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「陽言云護送烏桓人眾，實來為寇。」","sentenceOrder":212},
  {"id":"s_work_han_thu_109_213","chapterId":"ch_work_han_thu_109","textTraditional":"明年，西域車師後王須置離謀降匈奴，都護但欽誅斬之。置離兄狐蘭支將人眾二千餘人，敺畜產，舉國亡降匈奴，〔一〕單于受之。狐蘭支與匈奴共入寇，擊車師，殺後成長，〔二〕傷都護司馬，復還入匈奴。","sentenceOrder":213},
  {"id":"s_work_han_thu_109_214","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「敺與驅同。舉其一國人皆亡降也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_109_215","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「後成，車師小國名也。長，其長帥也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_109_216","chapterId":"ch_work_han_thu_109","textTraditional":"時戊己校尉史陳良、終帶、司馬丞韓玄、右曲候任商等見西域頗背叛，聞匈奴欲大侵，恐并死，即謀劫略吏卒數百人，共殺戊己校尉刀護，〔一〕遣人與匈奴南犁汗王南將軍相聞。匈奴南將軍二千騎入西域迎良等，良等盡脅略戊己校尉吏士男女二千餘人入匈奴。玄、商留南將軍所，良、帶徑至單于庭，人眾別置零吾水上田居。單于號良、帶曰烏桓都將軍，留居單于所，數呼與飲食。西域都護但欽上書言匈奴南將軍右伊秩訾將人眾寇擊諸國。莽於是大分匈奴為十五單于，遣中郎將藺苞、副校尉戴級將兵萬騎，多齎珍寶至雲中塞下，招誘呼韓邪單于諸子，欲以次拜之。使譯出塞誘呼右犁汗王咸、咸子登、助三人，至則脅拜咸為孝單于，賜安車鼓車各一，黃金千斤，雜繒千匹，戲戟十；〔二〕拜助為順單于，賜黃金五百斤；傳送助、登長安。莽封苞為宣威公，拜為虎牙將軍；封級為揚威公，拜為虎賁將軍。單于聞之，怒曰：「先單于受漢宣帝恩，不可負也。今天子非宣帝子孫，何以得立？」遣左骨都侯、右伊秩訾王呼盧訾及左賢王樂將兵入雲中益壽塞，大殺吏民。是歲，建國三年也。","sentenceOrder":216},
  {"id":"s_work_han_thu_109_217","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「刀音貂。」","sentenceOrder":217},
  {"id":"s_work_han_thu_109_218","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「戲戟，有旗之戟也。戲音許宜反，又音麾。」","sentenceOrder":218},
  {"id":"s_work_han_thu_109_219","chapterId":"ch_work_han_thu_109","textTraditional":"是後，單于歷告左右部都尉、諸邊王，入塞寇盜，大輩萬餘，中輩數千，少者數百，殺鴈門、朔方太守、都尉，略吏民畜產不可勝數，緣邊虛耗。莽新即位，怙府庫之富欲立威，乃拜十二部將率，發郡國勇士，武庫精兵，各有所屯守，轉委輸於邊。議滿三十萬眾，齎三百日糧，同時十道並出，窮追匈奴，內之于丁令，〔一〕因分其地，立呼韓邪十五子。","sentenceOrder":219},
  {"id":"s_work_han_thu_109_220","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「逐之遣入丁令地。令音零。」","sentenceOrder":220},
  {"id":"s_work_han_thu_109_221","chapterId":"ch_work_han_thu_109","textTraditional":"莽將嚴尤諫曰：「臣聞匈奴為害，所從來久矣，未聞上世有必征之者也。後世三家周、秦、漢征之，然皆未有得上策者也。周得中策，漢得下策，秦無策焉。當周宣王時，獫允內侵，至于涇陽，命將征之，盡境而還。其視戎狄之侵，譬猶蚊虻之螫，敺之而已。〔一〕故天下稱明，是為中策。漢武帝選將練兵，約齎輕糧，深入遠戍，〔二〕雖有克獲之功，胡輒報之，兵連禍結三十餘年，中國罷耗，匈奴亦創艾，〔三〕而天下稱武，是為下策。秦始皇不忍小恥而輕民力，築長城之固，延袤萬里，〔四〕轉輸之行，起於負海，疆境既完，中國內竭，以喪社稷，是為無策。今天下遭陽九之阨，比年饑饉，西北邊尤甚。發三十萬眾，具三百日糧，東援海代，南取江淮，然後乃備。〔五〕計其道里，一年尚未集合，兵先至者聚居暴露，師老械弊，勢不可用，此一難也。邊既空虛，不能奉軍糧，內調郡國，不相及屬，此二難也。〔六〕計一人三百日食，用糒十八斛，非牛力不能勝；牛又當自齎食，加二十斛，重矣。胡地沙鹵，多乏水草以往事揆之，軍出未滿百日，牛必物故且盡，〔七〕餘糧尚多，人不能負，此三難也。胡地秋冬甚寒，春夏甚風，多齎釜鍑薪炭，重不可勝，〔八〕食糒飲水，以歷四時，師有疾疫之憂，是故前世伐胡，不過百日，非不欲久，勢力不能，此四難也。輜重自隨，則輕銳者少，〔九〕不得疾行，虜徐遁逃，勢不能及，幸而逢虜，又累輜重，〔一０〕如遇險阻，銜尾相隨，〔一一〕虜要遮前後，危殆不測，此五難也。大用民力，功不可必立，臣伏憂之。今既發兵，宜縱先至者，令臣尤等深入霆擊，且以創艾胡虜。」〔一二〕莽不聽尤言，轉兵穀如故，天下騷動。","sentenceOrder":221},
  {"id":"s_work_han_thu_109_222","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「{民〈虫虫〉}，古蚊字也。蝱音盲。螫音式亦反。敺與驅同。」","sentenceOrder":222},
  {"id":"s_work_han_thu_109_223","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「約，少也。少齎衣裝。」","sentenceOrder":223},
  {"id":"s_work_han_thu_109_224","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「罷讀曰疲。耗，損也。創音初向反。艾讀曰乂。次下亦同。」","sentenceOrder":224},
  {"id":"s_work_han_thu_109_225","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「袤，長也，音茂。」","sentenceOrder":225},
  {"id":"s_work_han_thu_109_226","chapterId":"ch_work_han_thu_109","textTraditional":"〔五〕　師古曰：「援，引也，音爰。」","sentenceOrder":226},
  {"id":"s_work_han_thu_109_227","chapterId":"ch_work_han_thu_109","textTraditional":"〔六〕　師古曰：「調，發也，音徒釣反。屬音之欲反。」","sentenceOrder":227},
  {"id":"s_work_han_thu_109_228","chapterId":"ch_work_han_thu_109","textTraditional":"〔七〕　師古曰：「物故謂死也。」","sentenceOrder":228},
  {"id":"s_work_han_thu_109_229","chapterId":"ch_work_han_thu_109","textTraditional":"〔八〕　師古曰：「鬴，古釜字也。鍑，釜之大口者也。鍑音富。」","sentenceOrder":229},
  {"id":"s_work_han_thu_109_230","chapterId":"ch_work_han_thu_109","textTraditional":"〔九〕　師古曰：「重音直用反。其下亦同。」","sentenceOrder":230},
  {"id":"s_work_han_thu_109_231","chapterId":"ch_work_han_thu_109","textTraditional":"〔一０〕師古曰：「累音力瑞反。」","sentenceOrder":231},
  {"id":"s_work_han_thu_109_232","chapterId":"ch_work_han_thu_109","textTraditional":"〔一一〕師古曰：「銜，馬銜也。尾，馬尾也。言前後單行，不得並驅。」","sentenceOrder":232},
  {"id":"s_work_han_thu_109_233","chapterId":"ch_work_han_thu_109","textTraditional":"〔一二〕師古曰：「請率見到之兵，且以擊虜。」","sentenceOrder":233},
  {"id":"s_work_han_thu_109_234","chapterId":"ch_work_han_thu_109","textTraditional":"咸既受莽孝單于之號，馳出塞歸庭，具以見脅狀白單于。單于更以為於粟置支侯，匈奴賤官也。後助病死，莽以登代助為順單于。","sentenceOrder":234},
  {"id":"s_work_han_thu_109_235","chapterId":"ch_work_han_thu_109","textTraditional":"厭難將軍陳欽、〔一〕震狄將軍王巡屯雲中葛邪塞。是時，匈奴數為邊寇，殺將率吏士，略人民，敺畜產去甚眾。〔二〕捕得虜生口驗問，皆曰孝單于咸子角數為寇。兩將以聞。四年，莽會諸蠻夷，斬咸子登於長安市。","sentenceOrder":235},
  {"id":"s_work_han_thu_109_236","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「厭音一涉反。」","sentenceOrder":236},
  {"id":"s_work_han_thu_109_237","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「敺與驅同。」","sentenceOrder":237},
  {"id":"s_work_han_thu_109_238","chapterId":"ch_work_han_thu_109","textTraditional":"初，北邊自宣帝以來，數世不見煙火之警，人民熾盛，牛馬布野。及莽撓亂匈奴，與之構難，〔一〕邊民死亡係獲，又十二部兵久屯而不出，吏士罷弊，〔二〕數年之間，北邊虛空，野有暴骨矣。","sentenceOrder":238},
  {"id":"s_work_han_thu_109_239","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「撓，攪也，音火高反。」","sentenceOrder":239},
  {"id":"s_work_han_thu_109_240","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「罷讀曰疲。」","sentenceOrder":240},
  {"id":"s_work_han_thu_109_241","chapterId":"ch_work_han_thu_109","textTraditional":"烏珠留單于立二十一歲，建國五年死。匈奴用事大臣右骨都侯須卜當，即王昭君女伊墨居次云之婿也。云常欲與中國和親，又素與咸厚善，見咸前後為莽所拜，故遂越輿而立咸為烏累若鞮單于。〔一〕","sentenceOrder":241},
  {"id":"s_work_han_thu_109_242","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「累音力追反。」","sentenceOrder":242},
  {"id":"s_work_han_thu_109_243","chapterId":"ch_work_han_thu_109","textTraditional":"烏累單于咸立，以弟輿為左谷蠡王。烏珠留單于子蘇屠胡本為左賢王，以弟屠耆閼氏子盧渾為右賢王。〔一〕烏珠留單于在時，左賢王數死，以為其號不祥，更易命左賢王曰「護于」。護于之尊最貴，次當為單于，故烏珠留單于授其長子以為護于，欲傳以國。咸怨烏珠留單于貶賤己號，不欲傳國，及立，貶護于為左屠耆王。云、當遂勸咸和親。","sentenceOrder":243},
  {"id":"s_work_han_thu_109_244","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「渾音胡昆反。」","sentenceOrder":244},
  {"id":"s_work_han_thu_109_245","chapterId":"ch_work_han_thu_109","textTraditional":"天鳳元年，云、當遣人之西河虎猛制虜塞下，〔一〕告塞吏曰欲見和親侯。和親侯王歙者，王昭君兄子也。〔二〕中部都尉以聞。莽遣歙、歙弟騎都尉展德侯颯使匈奴，〔三〕賀單于初立，賜黃金衣被繒帛，紿言侍子登在，因購求陳良、終帶等。單于盡收四人及手殺校尉刀護賊芝音妻子以下二十七人，皆械檻付使者，遣廚唯姑夕王富等四十人送歙、颯。莽作焚如之刑，燒殺陳良等，〔四〕罷諸將率屯兵，但置游擊都尉。單于貪莽賂遺，故外不失漢故事，然內利寇掠。又使還，知子登前死，怨恨，寇虜從左地入，不絕。〔五〕使者問單于，輒曰：「烏桓與匈奴無狀黠民共為寇入塞，譬如中國有盜賊耳！咸初立持國，威信尚淺，盡力禁止，不敢有二心。」","sentenceOrder":245},
  {"id":"s_work_han_thu_109_246","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「虎猛，縣名，制虜塞在其界。」","sentenceOrder":246},
  {"id":"s_work_han_thu_109_247","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「歙音翕。」","sentenceOrder":247},
  {"id":"s_work_han_thu_109_248","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「颯音立。」","sentenceOrder":248},
  {"id":"s_work_han_thu_109_249","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　應劭曰：「易有焚如、死如、棄如之言，莽依此作刑名也。」如淳曰：「焚如、死如、棄如者，謂不孝子也。不畜於父母，不容於朋友，故燒殺棄之，莽依此作刑名也。」師古曰：「易離卦九四爻辭也。」","sentenceOrder":249},
  {"id":"s_work_han_thu_109_250","chapterId":"ch_work_han_thu_109","textTraditional":"〔五〕　師古曰：「入為寇而虜掠。」","sentenceOrder":250},
  {"id":"s_work_han_thu_109_251","chapterId":"ch_work_han_thu_109","textTraditional":"天鳳二年五月，莽復遣歙與五威將王咸率伏黯、丁業等六人，使送右廚唯姑夕王，因奉歸前所斬侍子登及諸貴人從者喪，皆載以常車。〔一〕至塞下，單于遣云、當子男大且渠奢等至塞迎。咸等至，多遺單于金珍，因諭說改其號，號匈奴曰「恭奴」，單于曰「善于」，賜印綬。封骨都侯當為後安公，當子男奢為後安侯。單于貪莽金幣，故曲聽之，然寇盜如故。咸、歙又以陳良等購金付云、當，令自差與之。〔二〕十二月，還入塞，莽大喜，賜歙錢二百萬，悉封黯等。","sentenceOrder":251},
  {"id":"s_work_han_thu_109_252","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　劉德曰：「縣易車也。舊司農出錢市車，縣次易牛也。」","sentenceOrder":252},
  {"id":"s_work_han_thu_109_253","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「差其次第多少。」","sentenceOrder":253},
  {"id":"s_work_han_thu_109_254","chapterId":"ch_work_han_thu_109","textTraditional":"單于咸立五歲，天鳳五年死，弟左賢王輿立，為呼都而尸道皋若鞮單于。匈奴謂孝曰「若鞮」。自呼韓邪後，與漢親密，見漢諡帝為「孝」，慕之，故皆為「若鞮」。","sentenceOrder":254},
  {"id":"s_work_han_thu_109_255","chapterId":"ch_work_han_thu_109","textTraditional":"呼都而尸單于輿既立，貪利賞賜，遣大且渠奢與云女弟當（戶）〔于〕居次子醯櫝王〔一〕俱奉獻至長安。莽遣和親侯歙與奢等俱至制虜塞下，與云、當會，因以兵迫脅，將至長安。云、當小男從塞下得脫，歸匈奴。當至長安，莽拜為須卜單于，欲出大兵以輔立之。兵調度亦不合，而匈奴愈怒，並入北邊，北邊由是壞敗。會當病死，莽以其庶女陸逯任妻後安公奢，〔二〕所以尊寵之甚厚，終為欲出兵立之者。〔三〕會漢兵誅莽，云、奢亦死。","sentenceOrder":255},
  {"id":"s_work_han_thu_109_256","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「櫝音讀。」","sentenceOrder":256},
  {"id":"s_work_han_thu_109_257","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「陸逯，邑也。莽改公主曰任。奢本為侯，莽以女妻之，故進爵為公。」師古曰：「逯音錄。任音壬。」","sentenceOrder":257},
  {"id":"s_work_han_thu_109_258","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「言為此計意不止。」","sentenceOrder":258},
  {"id":"s_work_han_thu_109_259","chapterId":"ch_work_han_thu_109","textTraditional":"更始二年冬，漢遣中郎將歸德侯颯、大司馬護軍陳遵使匈奴，授單于漢舊制璽綬，王侯以下印綬，因送云、當餘親屬貴人從者。單于輿驕，謂遵、颯曰：「匈奴本與漢為兄弟，匈奴中亂，〔一〕孝宣皇帝輔立呼韓邪單于，故稱臣以尊漢。今漢亦大亂，為王莽所篡，匈奴亦出兵擊莽，空其邊境，令天下騷動思漢，莽卒以敗而漢復興，亦我力也，當復尊我！」遵與相牚距，〔二〕單于終持此言。其明年夏，還。會赤眉入長安，更始敗。","sentenceOrder":259},
  {"id":"s_work_han_thu_109_260","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「言中間之時也，讀如本字，又音竹仲反。」","sentenceOrder":260},
  {"id":"s_work_han_thu_109_261","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「牚謂支柱也。音丈庚反，又丑庚反。」","sentenceOrder":261},
  {"id":"s_work_han_thu_109_262","chapterId":"ch_work_han_thu_109","textTraditional":"贊曰：書戒「蠻夷猾夏」，〔一〕詩稱「戎狄是膺」，〔二〕春秋「有道守在四夷」，〔三〕久矣夷狄之為患也。故自漢興，忠言嘉謀之臣曷嘗不運籌策相與爭於廟堂之上乎？高祖時則劉敬，呂后時樊噲、季布，孝文時賈誼、朝錯，孝武時王恢、韓安國、朱買臣、公孫弘、董仲舒，人持所見，各有同異，然總其要，歸兩科而已。縉紳之儒則守和親，介冑之士則言征伐，皆偏見一時之利害，而未究匈奴之終始也。自漢興以至于今，曠世歷年，多於春秋，其與匈奴，有脩文而和親之矣，有用武而克伐之矣，有卑下而承事之矣，〔四〕有威服而臣畜之矣，詘伸異變，強弱相反，是故其詳可得而言也。","sentenceOrder":262},
  {"id":"s_work_han_thu_109_263","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「虞書舜典載舜命皋陶作士之言也。猾，亂也。夏謂中夏諸國也。」","sentenceOrder":263},
  {"id":"s_work_han_thu_109_264","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「魯頌閟宮之詩，美僖公興師與齊桓討難。膺，當也。」","sentenceOrder":264},
  {"id":"s_work_han_thu_109_265","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「春秋左氏傳昭（三十二）〔二十三〕年楚囊瓦為令尹，城郢。沈尹戍曰：『古者天子，守在四夷，』言德及遠。」","sentenceOrder":265},
  {"id":"s_work_han_thu_109_266","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「下音胡亞反。」","sentenceOrder":266},
  {"id":"s_work_han_thu_109_267","chapterId":"ch_work_han_thu_109","textTraditional":"昔和親之論，發於劉敬。是時天下初定，新遭平城之難，故從其言，約結和親，賂遺單于，冀以救安邊境。孝惠、高后時遵而不違，匈奴寇盜不為衰止，而單于反以加驕倨。逮至孝文，與通關市，妻以漢女，增厚其賂，歲以千金，而匈奴數背約束，邊境屢被其害。是以文帝中年，赫然發憤，遂躬戎服，親御鞍馬，從六郡良家材力之士，〔一〕馳射上林，講習戰陳，聚天下精兵，軍於廣武，顧問馮唐，與論將帥，喟然歎息，思古名臣，此則和親無益，已然之明效也。","sentenceOrder":267},
  {"id":"s_work_han_thu_109_268","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「六郡，謂隴西、天水、安定、北地、上郡、西河也。其安定、天水、西河，武帝所置耳，史本其土地，而追言也。」","sentenceOrder":268},
  {"id":"s_work_han_thu_109_269","chapterId":"ch_work_han_thu_109","textTraditional":"仲舒親見四世之事，猶復欲守舊文，頗增其約。以為「義動君子，利動貪人，如匈奴者，非可以仁義說也。〔一〕獨可說以厚利，結之於天耳。〔二〕故與之厚利以沒其意，〔三〕與盟於天以堅其約，質其愛子以累其心，〔四〕匈奴雖欲展轉，奈失重利何，奈欺上天何，奈殺愛子何。〔五〕夫賦斂行賂不足以當三軍之費，城郭之固無以異於貞士之約，〔六〕而使邊城守境之民父兄緩帶，稚子咽哺，〔七〕胡馬不窺於長城，而羽檄不行於中國，不亦便於天下乎！」察仲舒之論，考諸行事，乃知其未合於當時，而有闕於後世也。當孝武時，雖征伐克獲，而士馬物故亦略相當；雖開河南之野，建朔方之郡，亦棄造陽之北九百餘里。匈奴人民每來降漢，單于亦輒拘留漢使以相報復，〔八〕其桀驁尚如斯，〔九〕安肯以愛子而為質乎？此不合當時之言也。若不置質，空約和親，是襲孝文既往之悔，而長匈奴無已之詐也。〔一０〕夫邊城不選守境武略之臣，脩障隧備塞之具，厲長戟勁弩之械，恃吾所以待邊寇。而務賦斂於民，遠行貨賂，割剝百姓，以奉寇讎。信甘言，守空約，而幾胡馬之不窺，不已過乎！〔一一〕","sentenceOrder":269},
  {"id":"s_work_han_thu_109_270","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「此說謂勸諭。」","sentenceOrder":270},
  {"id":"s_work_han_thu_109_271","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「此說讀曰悅。」","sentenceOrder":271},
  {"id":"s_work_han_thu_109_272","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「沒，溺也。」","sentenceOrder":272},
  {"id":"s_work_han_thu_109_273","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「累音力瑞反。」","sentenceOrder":273},
  {"id":"s_work_han_thu_109_274","chapterId":"ch_work_han_thu_109","textTraditional":"〔五〕　師古曰：「展轉，為移動其心。」","sentenceOrder":274},
  {"id":"s_work_han_thu_109_275","chapterId":"ch_work_han_thu_109","textTraditional":"〔六〕　晉灼曰：「堅城固守，不勝遣貞士為和親之約也。」","sentenceOrder":275},
  {"id":"s_work_han_thu_109_276","chapterId":"ch_work_han_thu_109","textTraditional":"〔七〕　師古曰：「咽，吞也。哺謂所食在口者也。咽音宴。哺音捕。」","sentenceOrder":276},
  {"id":"s_work_han_thu_109_277","chapterId":"ch_work_han_thu_109","textTraditional":"〔八〕　師古曰：「復音扶目反。」","sentenceOrder":277},
  {"id":"s_work_han_thu_109_278","chapterId":"ch_work_han_thu_109","textTraditional":"〔九〕　師古曰：「驁與傲同。」","sentenceOrder":278},
  {"id":"s_work_han_thu_109_279","chapterId":"ch_work_han_thu_109","textTraditional":"〔一０〕師古曰：「襲，重也，重疊為其事。」","sentenceOrder":279},
  {"id":"s_work_han_thu_109_280","chapterId":"ch_work_han_thu_109","textTraditional":"〔一一〕師古曰：「幾讀曰冀。」","sentenceOrder":280},
  {"id":"s_work_han_thu_109_281","chapterId":"ch_work_han_thu_109","textTraditional":"至孝宣之世，承武帝奮擊之威，直匈奴百年之運，〔一〕因其壞亂幾亡之阨，〔二〕權時施宜，覆以威德，然後單于稽首臣服，遣子入侍，（二）〔三〕世稱藩，賓於漢庭。是時邊城晏閉。牛馬布野，〔三〕三世無犬吠之警，菞庶亡干戈之役。〔四〕","sentenceOrder":281},
  {"id":"s_work_han_thu_109_282","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「直，當也。」","sentenceOrder":282},
  {"id":"s_work_han_thu_109_283","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「幾，近也，音鉅依反。」","sentenceOrder":283},
  {"id":"s_work_han_thu_109_284","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「晏，晚也。」","sentenceOrder":284},
  {"id":"s_work_han_thu_109_285","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「菞，古黎字。」","sentenceOrder":285},
  {"id":"s_work_han_thu_109_286","chapterId":"ch_work_han_thu_109","textTraditional":"後六十餘載之間，遭王莽篡位，始開邊隙，單于由是歸怨自絕，莽遂斬其侍子，邊境之禍搆矣。故呼韓邪始朝於漢，漢議其儀，而蕭望之曰：「戎狄荒服，言其來服荒忽無常，時至時去，宜待以客禮，讓而不臣。如其後嗣遁逃竄伏，〔一〕使於中國不為叛臣。」及孝元時，議罷守塞之備，侯應以為不可，可謂盛不忘衰，安必思危，遠見識微之明矣。至單于咸棄其愛子，昧利不顧，〔二〕侵掠所獲，歲鉅萬計，而和親賂遺，不過千金，安在其不棄質而失重利也？仲舒之言，漏於是矣。","sentenceOrder":286},
  {"id":"s_work_han_thu_109_287","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「〈辶彖〉，古遁字。」","sentenceOrder":287},
  {"id":"s_work_han_thu_109_288","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「昧，貪也，音妹。」","sentenceOrder":288},
  {"id":"s_work_han_thu_109_289","chapterId":"ch_work_han_thu_109","textTraditional":"夫規事建議，不圖萬世之固，而媮恃一時之事者，未（必）〔可〕以經遠也。〔一〕若乃征伐之功，秦漢行事，嚴尤論之當矣。故先王度土，中立封畿，〔二〕分九州，列五服，〔三〕物土貢，制外內，〔四〕或脩刑政，或詔文德，遠近之勢異也。是以春秋內諸夏而外夷狄。〔五〕夷狄之人貪而好利，被髮左衽，人面獸心。其與中國殊章服，異習俗，飲食不同，言語不通，辟居北垂寒露之野，〔六〕逐草隨畜，射獵為生，隔以山谷，雍以沙幕，〔七〕天地所以絕外內也。是故聖王禽獸畜之，不與約誓，不就攻伐；約之則費賂而見欺，攻之則勞師而詔寇。其地不可耕而食也，其民不可臣而畜也，是以外而不內，疏而不戚，〔八〕政教不及其人，正朔不加其國；來則懲而御之，去則備而守之。〔九〕其慕義而貢獻，則接之以禮讓，羈靡不絕，使曲在彼，蓋聖王制御蠻夷之常道也。","sentenceOrder":289},
  {"id":"s_work_han_thu_109_290","chapterId":"ch_work_han_thu_109","textTraditional":"〔一〕　師古曰：「媮音偷同。」","sentenceOrder":290},
  {"id":"s_work_han_thu_109_291","chapterId":"ch_work_han_thu_109","textTraditional":"〔二〕　師古曰：「度音大各反。中音竹仲反。」","sentenceOrder":291},
  {"id":"s_work_han_thu_109_292","chapterId":"ch_work_han_thu_109","textTraditional":"〔三〕　師古曰：「九州、五服，解並在前。」","sentenceOrder":292},
  {"id":"s_work_han_thu_109_293","chapterId":"ch_work_han_thu_109","textTraditional":"〔四〕　師古曰：「物土貢者，各因其土所生之物而貢之也。制外內，謂五服之差，遠近異制。」","sentenceOrder":293},
  {"id":"s_work_han_thu_109_294","chapterId":"ch_work_han_thu_109","textTraditional":"〔五〕　師古曰：「春秋成十五年『諸侯會吳於鍾離』。公羊傳曰：『曷為殊會？吳外也。曷為外？春秋內中國而外諸夏，內諸夏而外夷狄也。』」","sentenceOrder":294},
  {"id":"s_work_han_thu_109_295","chapterId":"ch_work_han_thu_109","textTraditional":"〔六〕　師古曰：「辟讀曰僻。」","sentenceOrder":295},
  {"id":"s_work_han_thu_109_296","chapterId":"ch_work_han_thu_109","textTraditional":"〔七〕　師古曰：「雍讀曰壅。」","sentenceOrder":296},
  {"id":"s_work_han_thu_109_297","chapterId":"ch_work_han_thu_109","textTraditional":"〔八〕　師古曰：「戚，近也。」","sentenceOrder":297},
  {"id":"s_work_han_thu_109_298","chapterId":"ch_work_han_thu_109","textTraditional":"〔九〕　師古曰：「懲謂使其創乂。」","sentenceOrder":298},
  {"id":"s_work_han_thu_109_299","chapterId":"ch_work_han_thu_109","textTraditional":"校勘記","sentenceOrder":299},
  {"id":"s_work_han_thu_109_300","chapterId":"ch_work_han_thu_109","textTraditional":"三八０六頁　八行　願為單于侍（史）〔使〕於漢，景祐、殿、局本都作「使」。王先謙說作「使」是。","sentenceOrder":300},
  {"id":"s_work_han_thu_109_301","chapterId":"ch_work_han_thu_109","textTraditional":"三八０九頁一三行　欲會二年歲首之朝（會）〔禮〕，景祐、殿本都作「禮」。","sentenceOrder":301},
  {"id":"s_work_han_thu_109_302","chapterId":"ch_work_han_thu_109","textTraditional":"三八一四頁　五行　快心於狼望之北哉？　王先謙據通鑑胡注，以「狼望」為狼煙候望之地，與顏注異。","sentenceOrder":302},
  {"id":"s_work_han_thu_109_303","chapterId":"ch_work_han_thu_109","textTraditional":"三八一四頁一０行　呼韓邪攜國歸（死）〔化〕，王念孫說「歸死」二字於義不可通，漢記孝哀紀、通典邊防十一並作「歸化」。","sentenceOrder":303},
  {"id":"s_work_han_thu_109_304","chapterId":"ch_work_han_thu_109","textTraditional":"三八二０頁　五行　（之）〔不〕當予匈奴稅。　錢大昭說「之」當作「不」。　按景祐、殿、局本都作「不」。","sentenceOrder":304},
  {"id":"s_work_han_thu_109_305","chapterId":"ch_work_han_thu_109","textTraditional":"三八二０頁　六行　共（入）〔殺〕匈奴使及其官屬，　錢大昭說「入」當作「殺」。按景本、殿、局本都作「殺」。","sentenceOrder":305},
  {"id":"s_work_han_thu_109_306","chapterId":"ch_work_han_thu_109","textTraditional":"三八二一頁　八行　今（印）〔即〕去『璽』加『新』，　景佑本作「即」。王念孫說作「即」是，即者若也。","sentenceOrder":306},
  {"id":"s_work_han_thu_109_307","chapterId":"ch_work_han_thu_109","textTraditional":"三八二九頁　二行　云女弟當（戶）〔于〕居次　王先謙說「戶」當為「于」。按見上文。","sentenceOrder":307},
  {"id":"s_work_han_thu_109_308","chapterId":"ch_work_han_thu_109","textTraditional":"三八三０頁　二行　春秋「有道守在四夷」，　楊樹達說，賈子春秋篇「天子有道，守在四夷」，此春秋舊說。「有道」二字當在引號內。","sentenceOrder":308},
  {"id":"s_work_han_thu_109_309","chapterId":"ch_work_han_thu_109","textTraditional":"三八三０頁一一行　春秋左氏傳昭（三十二）〔二十三〕年　按作當「二十三年」，各本並誤。","sentenceOrder":309},
  {"id":"s_work_han_thu_109_310","chapterId":"ch_work_han_thu_109","textTraditional":"三八三二頁一六行　（二）〔三〕世稱藩，　景祐、殿、局本都作「三」。王先謙說作「三」是。","sentenceOrder":310},
  {"id":"s_work_han_thu_109_311","chapterId":"ch_work_han_thu_109","textTraditional":"三八三三頁一四行　未（必）〔可〕以經遠也。　景祐、殿本都作「可」。王先謙說作「可」是。","sentenceOrder":311},
  {"id":"s_work_han_thu_110_1","chapterId":"ch_work_han_thu_110","textTraditional":"（西）〔南〕夷君長以十數，夜郎最大。〔一〕其西，靡莫之屬以十數，滇最大。〔二〕自滇以北，君長以十數，邛都最大。〔三〕此皆椎結，〔四〕耕田，有邑聚。其外，西至桐師以東，北至葉榆，〔五〕外為巂、昆明，〔六〕編髮，〔七〕隨畜移徙，亡常處，亡君長，地方可數千里。自巂以東北，君長以十數，徙、莋都最大。〔八〕自莋以東北，君長以十數，冉駹最大。〔九〕其俗，或土著，或移徙。〔一０〕在蜀之西。自駹以東北，君長以十數，白馬最大，皆氐類也。此皆巴蜀西南外蠻夷也。","sentenceOrder":1},
  {"id":"s_work_han_thu_110_2","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「後為縣，屬牂柯郡。」","sentenceOrder":2},
  {"id":"s_work_han_thu_110_3","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「地有滇池，因為名也。滇音顛。」","sentenceOrder":3},
  {"id":"s_work_han_thu_110_4","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「今之邛州本其地。」","sentenceOrder":4},
  {"id":"s_work_han_thu_110_5","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「椎音直追反。結讀曰髻。為髻如椎之形也。陸賈傳及貨殖傳皆作魋字，音義同耳。此下朝鮮傳亦同。」","sentenceOrder":5},
  {"id":"s_work_han_thu_110_6","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「葉榆，澤名，因以立號，後為縣，屬益州郡。」","sentenceOrder":6},
  {"id":"s_work_han_thu_110_7","chapterId":"ch_work_han_thu_110","textTraditional":"〔六〕　師古曰：「巂即之今巂州也。昆明又在其西南，即今之南寧州，諸爨所居，是其地也。巂音髓。」","sentenceOrder":7},
  {"id":"s_work_han_thu_110_8","chapterId":"ch_work_han_thu_110","textTraditional":"〔七〕　師古曰：「編音步典反。」","sentenceOrder":8},
  {"id":"s_work_han_thu_110_9","chapterId":"ch_work_han_thu_110","textTraditional":"〔八〕　師古曰：「徙及莋都，二國也。徙後為徙縣，屬蜀郡。莋都後為沈黎郡。徙音斯。莋音材各反。」","sentenceOrder":9},
  {"id":"s_work_han_thu_110_10","chapterId":"ch_work_han_thu_110","textTraditional":"〔九〕　師古曰：「今夔州、開州首領多姓冉者，本皆冉種也。駹音尨。」","sentenceOrder":10},
  {"id":"s_work_han_thu_110_11","chapterId":"ch_work_han_thu_110","textTraditional":"〔一０〕師古曰：「土著，謂有常處著於土地也。著音直略反。」","sentenceOrder":11},
  {"id":"s_work_han_thu_110_12","chapterId":"ch_work_han_thu_110","textTraditional":"始楚威王時，使將軍莊蹻將兵循江上，〔一〕略巴、黔中以西。〔二〕莊蹻者，楚莊王苗裔也。蹻至滇池，方三百里，〔三〕旁平地肥饒數千里，〔四〕以兵威定屬楚。欲歸報，會秦擊奪楚巴、黔中郡，道塞不通，因乃以其眾王滇，變服，從其俗，以長之。〔五〕秦時嘗破，略通五尺道，〔六〕諸此國頗置吏焉。十餘歲，秦滅。及漢興，皆棄此國而關蜀故徼。〔七〕巴屬民或竊出商賈，取其莋馬、僰僮、旄牛，以此巴蜀殷富。","sentenceOrder":12},
  {"id":"s_work_han_thu_110_13","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「循，順也。謂緣江而上也。蹻音居略反。」","sentenceOrder":13},
  {"id":"s_work_han_thu_110_14","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「黔中，即今黔州是其地，本巴人也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_110_15","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「地理志益州滇池縣，其澤在西北。華陽國志云澤下流淺狹，狀如倒池，故云滇池。」","sentenceOrder":15},
  {"id":"s_work_han_thu_110_16","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「池旁之地也。」","sentenceOrder":16},
  {"id":"s_work_han_thu_110_17","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「為其長帥也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_110_18","chapterId":"ch_work_han_thu_110","textTraditional":"〔六〕　師古曰：「其處險阨，故道纔廣五尺。」","sentenceOrder":18},
  {"id":"s_work_han_thu_110_19","chapterId":"ch_work_han_thu_110","textTraditional":"〔七〕　師古曰：「西南之徼，猶北方塞也。徼音工釣反。」","sentenceOrder":19},
  {"id":"s_work_han_thu_110_20","chapterId":"ch_work_han_thu_110","textTraditional":"建元六年，大行王恢擊東粵，東粵殺王郢以報。恢因兵威使番陽令唐蒙風曉南粵。〔一〕南粵食蒙蜀枸醬，〔二〕蒙問所從來，曰：「道西北牂柯江，〔三〕江廣數里，出番禺城下。」〔四〕蒙歸至長安，問蜀賈人，獨蜀出枸醬，多持竊出市夜郎。夜郎者，臨牂柯江，江廣百餘步，足以行船。南粵以財物役屬夜郎，西至桐師，然亦不能臣使也。蒙乃上書說上曰：「南粵王黃屋左纛，〔五〕地東西萬餘里，名為外臣，實一州主。今以長沙、豫章往，水道多絕，難行。竊聞夜郎所有精兵可得十萬，浮船牂柯，出不意，此制粵一奇也。誠以漢之強，巴蜀之饒，通夜郎道，為置吏，甚易。」上許之。乃拜蒙以郎中將，將千人，食重萬餘人，〔六〕從巴（莋）〔苻〕關入，遂見夜郎侯多同。〔七〕厚賜，諭以威德，約為置吏，使其子為令。〔八〕夜郎旁小邑皆貪漢繒帛，以為漢道險，終不能有也，乃且聽蒙約。還報，乃以為犍為郡。發巴蜀卒治道，自僰道指牂柯江。蜀人司馬相如亦言西夷邛、莋可置郡。使相如以郎中將往諭，皆如南夷，為置一都尉，十餘縣，屬蜀。","sentenceOrder":20},
  {"id":"s_work_han_thu_110_21","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「番音蒲何反。風讀曰諷。」","sentenceOrder":21},
  {"id":"s_work_han_thu_110_22","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　晉灼曰：「枸音矩。」劉德曰：「枸樹如桑，其椹長二三寸，味酢。取其實以為醬，美，蜀人以為珍味。」師古曰：「劉說非也。子形如（赤）〔桑〕椹耳。緣木而生，非樹也。子又不長二三寸，味尤辛，不酢。今宕渠則有之。食讀曰飤。」","sentenceOrder":22},
  {"id":"s_work_han_thu_110_23","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「道，由也，由此而來也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_110_24","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「番音普安反。禺音隅。」","sentenceOrder":24},
  {"id":"s_work_han_thu_110_25","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「言為天子之車服。」","sentenceOrder":25},
  {"id":"s_work_han_thu_110_26","chapterId":"ch_work_han_thu_110","textTraditional":"〔六〕　師古曰：「食糧及衣重也。重音直用反。」","sentenceOrder":26},
  {"id":"s_work_han_thu_110_27","chapterId":"ch_work_han_thu_110","textTraditional":"〔七〕　師古曰：「多同，其侯名也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_110_28","chapterId":"ch_work_han_thu_110","textTraditional":"〔八〕　師古曰：「比之於漢縣也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_110_29","chapterId":"ch_work_han_thu_110","textTraditional":"當是時，巴蜀四郡通西南夷道，載轉相饟。〔一〕數歲，道不通，士罷餓餧，離暑溼，死者甚眾。〔二〕西南夷又數反，發兵興擊，耗費亡功。〔三〕上患之，使公孫弘往視問焉。還報，言其不便。及弘為御史大夫，時方築朔方，據河逐胡，弘等因言西南夷為害，〔四〕可且罷，專力事匈奴。上許之，罷西夷，獨置南夷兩縣一都尉，稍令犍為自保就。〔五〕","sentenceOrder":29},
  {"id":"s_work_han_thu_110_30","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「饟，古餉字。」","sentenceOrder":30},
  {"id":"s_work_han_thu_110_31","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「罷讀曰疲。餧，飢也。離，遭也。餧音能賄反。」","sentenceOrder":31},
  {"id":"s_work_han_thu_110_32","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「耗，損也，音呼到反。」","sentenceOrder":32},
  {"id":"s_work_han_thu_110_33","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「言通西南夷大為損害。」","sentenceOrder":33},
  {"id":"s_work_han_thu_110_34","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「令自保守，且脩成其郡縣。」","sentenceOrder":34},
  {"id":"s_work_han_thu_110_35","chapterId":"ch_work_han_thu_110","textTraditional":"及元狩元年，博望侯張騫言使大夏時，見蜀布、邛竹杖，問所從來，曰「從東南身毒國，〔一〕可數千里，得蜀賈人市。」或聞邛西可二千里有身毒國。騫因盛言大夏在漢西南，慕中國，患匈奴隔其道，誠通蜀，身毒國道便近，又亡害。於是天子乃令王然于、柏始昌、呂越人等十餘輩間出西南夷，〔二〕指求身毒國。至滇，滇王當羌乃留為求道。〔三〕四歲餘，皆閉昆明，莫能通。〔四〕滇王與漢使言：「漢孰與我大？」〔五〕及夜郎侯亦然。各自以一州王，不知漢廣大。使者還，因盛言滇大國，足事親附。〔六〕天子注意焉。","sentenceOrder":35},
  {"id":"s_work_han_thu_110_36","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「即天竺也，亦曰捐篤也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_110_37","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「求間隙而出也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_110_38","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「當羌，滇王名。」","sentenceOrder":38},
  {"id":"s_work_han_thu_110_39","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「為昆明所閉塞。」","sentenceOrder":39},
  {"id":"s_work_han_thu_110_40","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「與猶如。」","sentenceOrder":40},
  {"id":"s_work_han_thu_110_41","chapterId":"ch_work_han_thu_110","textTraditional":"〔六〕　師古曰：「言可專事招來之，令其親附。」","sentenceOrder":41},
  {"id":"s_work_han_thu_110_42","chapterId":"ch_work_han_thu_110","textTraditional":"及至南粵反，上使馳義侯因犍為發南夷兵。且蘭君恐遠行，旁國虜其老弱，〔一〕乃與其眾反，殺使者及犍為太守。漢乃發巴蜀罪人當擊南粵者八校尉擊之。會越已破，漢八校尉不下，中郎將郭昌、衛廣引兵還，行誅隔滇道者且蘭，〔二〕斬首數萬，遂平南夷為牂柯郡。夜郎侯始倚南粵，南粵已滅，還誅反者，〔三〕夜郎遂入朝，上以為夜郎王。南粵破後，及漢誅且蘭、邛君，并殺莋侯，冉駹皆震恐，請臣置吏。以邛都為粵巂郡，莋都為沈黎郡，冉駹為文山郡，廣漢西白馬為武都郡。","sentenceOrder":42},
  {"id":"s_work_han_thu_110_43","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「恐發兵與漢行後，其國空虛，而旁國來寇，鈔取其老弱也。且音子餘反。」","sentenceOrder":43},
  {"id":"s_work_han_thu_110_44","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「言因軍行而便誅之也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_110_45","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「謂軍還而誅且蘭。」","sentenceOrder":45},
  {"id":"s_work_han_thu_110_46","chapterId":"ch_work_han_thu_110","textTraditional":"使王然于以粵破及誅南夷兵威風諭滇王入朝。〔一〕滇王者，其眾數萬人，其旁東北勞深、靡莫皆同姓相杖，未肯聽。〔二〕勞、莫數侵犯使者吏卒。元封二年，天子發巴蜀兵擊滅勞深、靡莫，以兵臨滇。滇王始首善，以故弗誅。〔三〕滇王離西夷，〔四〕滇舉國降，請置吏入朝。於是以為益州郡，賜滇王王印，復長其民。〔五〕西南夷君長以百數，獨夜郎、滇受王印。滇，小邑也，最寵焉。","sentenceOrder":46},
  {"id":"s_work_han_thu_110_47","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「風讀曰諷。」","sentenceOrder":47},
  {"id":"s_work_han_thu_110_48","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「杖猶倚也，相依倚為援而不聽滇王入朝也。杖音直亮反。」","sentenceOrder":48},
  {"id":"s_work_han_thu_110_49","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「言初始以來，常有善意。」","sentenceOrder":49},
  {"id":"s_work_han_thu_110_50","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「言東嚮事漢。」","sentenceOrder":50},
  {"id":"s_work_han_thu_110_51","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「為之長帥。」","sentenceOrder":51},
  {"id":"s_work_han_thu_110_52","chapterId":"ch_work_han_thu_110","textTraditional":"後二十三歲，孝昭始元元年，益州廉頭、姑繒民反，殺長吏。牂柯、談指、同並等二十四邑，凡三萬餘人皆反。〔一〕遣水衡都尉發蜀郡、犍為奔命萬餘人〔二〕擊牂柯，大破之。後三歲，姑繒、葉榆復反，遣水衡都尉呂辟胡將郡兵擊之。〔三〕辟胡不進，蠻夷遂殺益州太守，乘勝與辟胡戰，士戰及溺死者四千餘人。明年，復遣軍正王平與大鴻臚田廣明等並進，大破益州，斬首捕虜五萬餘級，獲畜產十餘萬。上曰：「鉤町侯亡波率其邑君長人民擊反者，〔四〕斬首捕虜有功，其立亡波為鉤町王。大鴻臚廣明賜爵關內侯，食邑三百戶。」後間歲，武都氐人反，〔五〕遣執金吾馬適建、龍頟侯韓增與大鴻臚廣明將兵擊之。","sentenceOrder":52},
  {"id":"s_work_han_thu_110_53","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「並音伴。」","sentenceOrder":53},
  {"id":"s_work_han_thu_110_54","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「犇，古奔字。奔命，解在昭紀。」","sentenceOrder":54},
  {"id":"s_work_han_thu_110_55","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「辟音璧。」","sentenceOrder":55},
  {"id":"s_work_han_thu_110_56","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「鉤音鉅于反。町音大鼎反。」","sentenceOrder":56},
  {"id":"s_work_han_thu_110_57","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「間歲，隔一歲。」","sentenceOrder":57},
  {"id":"s_work_han_thu_110_58","chapterId":"ch_work_han_thu_110","textTraditional":"至成帝河平中，夜郎王興與鉤町王禹、漏臥侯俞〔一〕更舉兵相攻。〔二〕牂柯太守請發兵誅興等，議者以為道遠不可擊，乃遣太中大夫蜀郡張匡持節和解。興等不從命，刻木象漢吏，立道旁射之。杜欽說大將軍王鳳曰：「太中大夫匡使和解蠻夷王侯，王侯受詔，已復相攻，輕易漢使，不憚國威，其效可見。恐議者選耎，復守和解〔三〕，太守察動靜，有變乃以聞。如此，則復曠一時，〔四〕王侯得收獵其眾，申固其謀，黨助眾多，各不勝忿，必相殄滅。自知罪成，狂犯守尉，〔五〕遠臧溫暑毒草之地，雖有孫吳將，賁育士，〔六〕若入水火，往必焦沒，知勇亡所施。屯田守之，費不可勝量。宜因其罪惡未成，未疑漢家加誅，陰敕旁郡守尉練士馬，〔七〕大司農豫調穀積要害處，〔八〕選任職太守往，以秋涼時入，誅其王侯尤不軌者。即以為不毛之地，亡用之民，聖王不以勞中國，〔九〕宜罷郡，放棄其民，絕其王侯勿復通。如以先帝所立累世之功不可墮壞，〔一０〕亦宜因其萌牙，早斷絕之，及已成形然後戰師，則萬姓被害。」","sentenceOrder":58},
  {"id":"s_work_han_thu_110_59","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　孟康曰：「漏臥，夷邑名，後為縣。」師古曰：「俞音踰。」","sentenceOrder":59},
  {"id":"s_work_han_thu_110_60","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「更，互也，音工衡反。」","sentenceOrder":60},
  {"id":"s_work_han_thu_110_61","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「選耎，怯不前之意也。選音息袞反。耎音人兗反。」","sentenceOrder":61},
  {"id":"s_work_han_thu_110_62","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「曠，空也。一時，（二）〔三〕月也。言空廢一時不早發兵也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_110_63","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「言起狂勃之心而殺守尉也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_110_64","chapterId":"ch_work_han_thu_110","textTraditional":"〔六〕　師古曰：「孫，孫武也。吳，吳起也。賁，孟賁也。育，夏育也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_110_65","chapterId":"ch_work_han_thu_110","textTraditional":"〔七〕　師古曰：「練，簡也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_110_66","chapterId":"ch_work_han_thu_110","textTraditional":"〔八〕　師古曰：「調，發也。要害者，在我為要，於敵為害也。調音徒釣反。」","sentenceOrder":66},
  {"id":"s_work_han_thu_110_67","chapterId":"ch_work_han_thu_110","textTraditional":"〔九〕　師古曰：「即猶若也。不毛，言不生草木。」","sentenceOrder":67},
  {"id":"s_work_han_thu_110_68","chapterId":"ch_work_han_thu_110","textTraditional":"〔一０〕師古曰：「如亦若也。墮，毀也，音火規反。」","sentenceOrder":68},
  {"id":"s_work_han_thu_110_69","chapterId":"ch_work_han_thu_110","textTraditional":"大將軍鳳於是薦金城司馬陳立為牂柯太守。立者，臨邛人，前為連然長，不韋令，〔一〕蠻夷畏之。及至牂柯，諭告夜郎王興，興不從命，立請誅之。未報，乃從吏數十人出行縣，〔二〕至興國且同亭，〔三〕召興。興將數千人往至亭，從邑君數十人入見立。立數責，因斷頭。〔四〕邑君曰：「將軍誅亡狀，為民除害，願出曉士眾。」以興頭示之，皆釋兵降。〔五〕鉤町王禹、漏臥侯俞震恐，入粟千斛，牛羊勞吏士。立還歸郡，興妻父翁指與興子邪務收餘兵，迫脅旁二十二邑反。至冬，立奏募諸夷與都尉長史分將攻翁指等。翁指據阨為壘，立使奇兵絕其饟道，縱反間以誘其眾。〔六〕都尉萬年曰：「兵久不決，費不可共。」〔七〕引兵獨進，敗走，趨立營。〔八〕立怒，叱戲下令格之。〔九〕都尉復還戰，立引兵救之。時天大旱，立攻絕其水道。蠻夷共斬翁指，持首出降。立已平定西夷，徵詣京師。會巴郡有盜賊，復以立為巴郡太守，秩中二千石居，賜爵左庶長。〔一０〕徙為天水太守，勸民農桑為天下最，賜金四十斤。入為左曹衛將軍、護軍都尉，卒官。","sentenceOrder":69},
  {"id":"s_work_han_thu_110_70","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　蘇林曰：「皆益州縣也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_110_71","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「行音下更反。」","sentenceOrder":71},
  {"id":"s_work_han_thu_110_72","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「且音子餘反。」","sentenceOrder":72},
  {"id":"s_work_han_thu_110_73","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「數音所具反。」","sentenceOrder":73},
  {"id":"s_work_han_thu_110_74","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「釋，解也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_110_75","chapterId":"ch_work_han_thu_110","textTraditional":"〔六〕　師古曰：「間音居莧反。」","sentenceOrder":75},
  {"id":"s_work_han_thu_110_76","chapterId":"ch_work_han_thu_110","textTraditional":"〔七〕　師古曰：「共讀曰供。」","sentenceOrder":76},
  {"id":"s_work_han_thu_110_77","chapterId":"ch_work_han_thu_110","textTraditional":"〔八〕　師古曰：「趨讀曰趣。趣，向也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_110_78","chapterId":"ch_work_han_thu_110","textTraditional":"〔九〕　師古曰：「戲音許宜反，又音麾。解在高紀及灌夫傳。」","sentenceOrder":78},
  {"id":"s_work_han_thu_110_79","chapterId":"ch_work_han_thu_110","textTraditional":"〔一０〕師古曰：「第十爵也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_110_80","chapterId":"ch_work_han_thu_110","textTraditional":"王莽篡位，改漢制，貶鉤町王以為侯。王邯怨恨，〔一〕牂柯大尹周欽詐殺邯。邯弟承攻殺欽，州郡擊之，不能服。三邊蠻夷愁擾盡反，復殺益州大尹程隆。莽遣平蠻將軍馮茂發巴、蜀、犍為吏士，賦斂取足於民，以擊益州。出入三年，疾疫死者什七，巴、蜀騷動。莽徵茂還，誅之。更遣寧始將軍廉丹與庸部牧史熊〔二〕大發天水、隴西騎士，廣漢、巴、蜀、犍為吏民十萬人，轉輸者合二十萬人，擊之。始至，頗斬首數千，其後軍糧前後不相及，士卒飢疫，三歲餘死者數萬。而粵嶲蠻夷任貴亦殺太守枚根，自立為邛穀王。〔三〕會莽敗漢興，誅貴，復舊號云。〔四〕","sentenceOrder":80},
  {"id":"s_work_han_thu_110_81","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「邯，其王名也。邯音酣。」","sentenceOrder":81},
  {"id":"s_work_han_thu_110_82","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「莽改益州為庸部。」","sentenceOrder":82},
  {"id":"s_work_han_thu_110_83","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「枚根，太守之姓名。」","sentenceOrder":83},
  {"id":"s_work_han_thu_110_84","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「此漢興者，謂光武中興也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_110_85","chapterId":"ch_work_han_thu_110","textTraditional":"南粵王趙佗，真定人也。〔一〕秦并天下，略定揚粵，〔二〕置桂林、南海、象郡，以適徙民與粵雜處。〔三〕十三歲，至二世時，南海尉任囂〔四〕病且死，召龍川令趙佗〔五〕語曰「聞陳勝等作亂，豪桀叛秦相立，南海辟遠，恐盜兵侵此。〔六〕吾欲興兵絕新道，〔七〕自備待諸侯變，會疾甚。且番禺負山險阻，〔八〕南北東西數千里，頗有中國人相輔，此亦一州之主，可為國。郡中長吏亡足與謀者，故召公告之。」即被佗書，行南海尉事。〔九〕囂死，佗即移檄告橫浦、陽山、湟谿關〔一０〕曰：「盜兵且至，急絕道聚兵自守。」因稍以法誅秦所置吏，以其黨為守假。〔一一〕秦已滅，佗即擊并桂林、象郡，自立為南粵武王。","sentenceOrder":85},
  {"id":"s_work_han_thu_110_86","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「真定，本趙國之縣也。佗音徒何反。」","sentenceOrder":86},
  {"id":"s_work_han_thu_110_87","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「本揚州之分，故云揚粵。」","sentenceOrder":87},
  {"id":"s_work_han_thu_110_88","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「適讀曰謫。謫有罪者，徙之於越地，與其土人雜居。」","sentenceOrder":88},
  {"id":"s_work_han_thu_110_89","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「囂音敖。」","sentenceOrder":89},
  {"id":"s_work_han_thu_110_90","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「龍川，南海之縣也，即今之循州。」","sentenceOrder":90},
  {"id":"s_work_han_thu_110_91","chapterId":"ch_work_han_thu_110","textTraditional":"〔六〕　師古曰：「辟讀曰僻。」","sentenceOrder":91},
  {"id":"s_work_han_thu_110_92","chapterId":"ch_work_han_thu_110","textTraditional":"〔七〕　師古曰：「秦所開越道也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_110_93","chapterId":"ch_work_han_thu_110","textTraditional":"〔八〕　師古曰：「負，偝也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_110_94","chapterId":"ch_work_han_thu_110","textTraditional":"〔九〕　師古曰：「被，加也，音皮義反。」","sentenceOrder":94},
  {"id":"s_work_han_thu_110_95","chapterId":"ch_work_han_thu_110","textTraditional":"〔一０〕師古曰：「湟音皇。」","sentenceOrder":95},
  {"id":"s_work_han_thu_110_96","chapterId":"ch_work_han_thu_110","textTraditional":"〔一一〕師古曰：「令為郡縣之職，或守或假也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_110_97","chapterId":"ch_work_han_thu_110","textTraditional":"高帝已定天下，為中國勞苦，故釋佗不誅。〔一〕十一年，遣陸賈立佗為南粵王，與剖符通使，使和輯百粵，〔二〕毋為南邊害，與長沙接境。","sentenceOrder":97},
  {"id":"s_work_han_thu_110_98","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「釋，置也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_110_99","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「輯與集同也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_110_100","chapterId":"ch_work_han_thu_110","textTraditional":"高后時，有司請禁粵關巿鐵器。佗曰：「高皇帝立我，通使物，今高后聽讒臣，別異蠻夷，鬲絕器物，〔一〕此必長沙王計，欲倚中國，〔二〕擊滅南海并王之，自為功也。」於是佗乃自尊號為南武帝，發兵攻長沙邊，敗數縣焉。高后遣將軍隆慮侯灶擊之，〔三〕會暑溼，士卒大疫，兵不能隃領。〔四〕歲餘，高后崩，即罷兵。佗因此以兵威財物賂遺閩粵、西甌駱，役屬焉。〔五〕東西萬餘里。乃乘黃屋左纛，稱制，與中國侔。〔六〕","sentenceOrder":100},
  {"id":"s_work_han_thu_110_101","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「鬲與隔同。」","sentenceOrder":101},
  {"id":"s_work_han_thu_110_102","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「倚音於綺反。」","sentenceOrder":102},
  {"id":"s_work_han_thu_110_103","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「周灶也。慮音廬。」","sentenceOrder":103},
  {"id":"s_work_han_thu_110_104","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「隃與踰同。下皆類此。」","sentenceOrder":104},
  {"id":"s_work_han_thu_110_105","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「西甌即駱越也。言西者，以別東甌也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_110_106","chapterId":"ch_work_han_thu_110","textTraditional":"〔六〕　師古曰：「侔，等也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_110_107","chapterId":"ch_work_han_thu_110","textTraditional":"文帝元年，初鎮撫天下，使告諸侯四夷從代來即位意，諭盛德焉。〔一〕乃為佗親冢在真定置守邑，〔二〕歲時奉祀。召其從昆弟，尊官厚賜寵之。詔丞相平舉可使粵者，平言陸賈先帝時使粵。上召賈為太中大夫，謁者一人為副使，賜佗書曰：「皇帝謹問南粵王，甚苦心勞意。朕，高皇帝側室之子，〔三〕棄外奉北藩于代，道里遼遠，壅蔽樸愚，未嘗致書。〔四〕高皇帝棄群臣，孝惠皇帝即世，高后（白）〔自〕臨事，不幸有疾，日進不衰，〔五〕以故誖暴乎治。〔六〕諸呂為變故亂法，不能獨制，乃取它姓子為孝惠皇帝嗣。賴宗廟之靈，功臣之力，誅之已畢。朕以王侯吏不釋之故，〔七〕不得不立，今即位。乃者聞王遺將軍隆慮侯書，求親昆弟，請罷長沙兩將軍〔八〕。朕以王書罷將軍博陽侯，親昆弟在真定者，已遣人存問。脩治先人冢。前日聞王發兵於邊，為寇災不止。當其時長沙苦之，南郡尤甚，雖王之國，庸獨利乎！〔九〕必多殺士卒，傷良將吏，寡人之妻，孤人之子，獨人父母，得一亡十，朕不忍為也。朕欲定地犬牙相入者，以問吏，吏曰『高皇帝所以介長沙土也』，〔一０〕朕不得擅變焉。吏曰：『得王之地不足以為大，得王之財不足以為富，服領以南，王自治之。』〔一一〕雖然，王之號為帝。兩帝並立，亡一乘之使以通其道，是爭也；爭而不讓，仁者不為也。願與王分棄前患，〔一二〕終今以來，通使如故。〔一三〕故使賈馳諭告王朕意，王亦受之，毋為寇災矣。上褚五十衣，中褚三十衣，下褚二十衣，遺王。〔一四〕願王聽樂娛憂，存問鄰國。」〔一五〕","sentenceOrder":107},
  {"id":"s_work_han_thu_110_108","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「言不以威武加於遠方也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_110_109","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「親謂父母也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_110_110","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「言非正嫡所生也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_110_111","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「言未得通使於越。」","sentenceOrder":111},
  {"id":"s_work_han_thu_110_112","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「言疾病益甚也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_110_113","chapterId":"ch_work_han_thu_110","textTraditional":"〔六〕　師古曰：「誖，乖也，音布內反。」","sentenceOrder":113},
  {"id":"s_work_han_thu_110_114","chapterId":"ch_work_han_thu_110","textTraditional":"〔七〕　孟康曰：「辭讓帝位不見置也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_110_115","chapterId":"ch_work_han_thu_110","textTraditional":"〔八〕　師古曰：「佗之昆弟在故鄉者求訪之，而兩將軍將兵擊越者請罷之，以賓附於漢也。言親昆弟者，謂有服屬者也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_110_116","chapterId":"ch_work_han_thu_110","textTraditional":"〔九〕　師古曰：「言越兵寇邊，長沙、南郡皆厭苦之。而漢軍亦當相拒，方有戰鬥，於越亦非利也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_110_117","chapterId":"ch_work_han_thu_110","textTraditional":"〔一０〕師古曰：「介，隔也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_110_118","chapterId":"ch_work_han_thu_110","textTraditional":"〔一一〕蘇林曰：「山領名也。」如淳曰：「長沙南界也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_110_119","chapterId":"ch_work_han_thu_110","textTraditional":"〔一二〕師古曰：「彼此共棄，故云分。」","sentenceOrder":119},
  {"id":"s_work_han_thu_110_120","chapterId":"ch_work_han_thu_110","textTraditional":"〔一三〕師古曰：「從今通使至於終久，故云終今以來也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_110_121","chapterId":"ch_work_han_thu_110","textTraditional":"〔一四〕師古曰：「以綿裝衣曰褚。上中下者，綿之多少薄厚之差也。褚音竹呂反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_110_122","chapterId":"ch_work_han_thu_110","textTraditional":"〔一五〕師古曰：「謂東越及甌駱等。」","sentenceOrder":122},
  {"id":"s_work_han_thu_110_123","chapterId":"ch_work_han_thu_110","textTraditional":"陸賈至，南粵王恐，乃頓首謝，願奉明詔，長為藩臣，奉貢職。於是下令國中曰：「吾聞兩雄不俱立，兩賢不並世。漢皇帝賢天子。自今以來，去帝制黃屋左纛。」因為書稱：「蠻夷大長老夫臣佗昧死再拜上書皇帝陛下：老夫故粵吏也，高皇帝幸賜臣佗璽，以為南粵王，使為外臣，時內貢職。〔一〕孝惠皇帝即位，義不忍絕，所以賜老夫者厚甚。高后自臨用事，近細士，信讒臣，〔二〕別異蠻夷，出令曰：『毋予蠻夷外粵金鐵田器；馬牛羊〔三〕即予，予牡，毋與牝。』〔四〕老夫處辟，馬牛羊齒已長，〔五〕自以祭祀不脩，有死罪，使內史藩、中尉高、御史平凡三輩上書謝過，皆不反。又風聞老夫父母墳墓已壞削，兄弟宗族已誅論。〔六〕吏相與議曰：『今內不得振於漢，外亡以自高異。』〔七〕故更號為帝，自帝其國，非敢有害於天下也。高皇后聞之大怒，削去南粵之籍，使使不通。老夫竊疑長沙王讒臣，故敢發兵以伐其邊。且南方卑溼，蠻夷中西有西甌，其眾半羸，〔八〕南面稱王；東有閩粵，其眾數千人，亦稱王；西北有長沙，其半蠻夷，亦稱王。〔九〕老夫故敢妄竊帝號，聊以自娛。老夫身定百邑之地，東西南北數千萬里，帶甲百萬有餘，然北面而臣事漢，何也？不敢背先人之故。老夫處粵四十九年，于今抱孫焉。然夙興夜寐，寢不安席，食不甘味，目不視靡曼之色，耳不聽鍾鼓之音者，以不得事漢也。今陛下幸哀憐，復故號，〔一０〕通使漢如故，老夫死骨不腐，改號不敢為帝矣！謹北面因使者獻白璧一雙，翠鳥千，犀角十，紫貝五百，桂蠹一器，〔一一〕生翠四十雙，孔雀二雙。昧死再拜，以聞皇帝陛下。」","sentenceOrder":123},
  {"id":"s_work_han_thu_110_124","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「言以時輸入貢職。」","sentenceOrder":124},
  {"id":"s_work_han_thu_110_125","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「細士猶言小人也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_110_126","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「言非中國，故云外越。」","sentenceOrder":126},
  {"id":"s_work_han_thu_110_127","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「恐其蕃息。」","sentenceOrder":127},
  {"id":"s_work_han_thu_110_128","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「辟讀曰僻。齒已長，謂老矣。」","sentenceOrder":128},
  {"id":"s_work_han_thu_110_129","chapterId":"ch_work_han_thu_110","textTraditional":"〔六〕　師古曰：「風聞，聞風聲。」","sentenceOrder":129},
  {"id":"s_work_han_thu_110_130","chapterId":"ch_work_han_thu_110","textTraditional":"〔七〕　師古曰：「振，起也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_110_131","chapterId":"ch_work_han_thu_110","textTraditional":"〔八〕　師古曰：「羸謂劣弱也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_110_132","chapterId":"ch_work_han_thu_110","textTraditional":"〔九〕　師古曰：「言長沙之國半雜蠻夷之人。」","sentenceOrder":132},
  {"id":"s_work_han_thu_110_133","chapterId":"ch_work_han_thu_110","textTraditional":"〔一０〕師古曰：「復音扶目反。」","sentenceOrder":133},
  {"id":"s_work_han_thu_110_134","chapterId":"ch_work_han_thu_110","textTraditional":"〔一一〕應劭曰：「桂樹中蝎蟲也。」蘇林曰：「漢舊常以獻陵廟，載以赤轂小車。」師古曰：「此蟲食桂，故味辛，而漬之以蜜食之也。蠹音丁故反。」","sentenceOrder":134},
  {"id":"s_work_han_thu_110_135","chapterId":"ch_work_han_thu_110","textTraditional":"陸賈還報，文帝大說。〔一〕遂至孝景時，稱臣遣使入朝請〔二〕。然其居國，竊如故號；其使天子，稱王朝命如諸侯。","sentenceOrder":135},
  {"id":"s_work_han_thu_110_136","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":136},
  {"id":"s_work_han_thu_110_137","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「請音才性反。」","sentenceOrder":137},
  {"id":"s_work_han_thu_110_138","chapterId":"ch_work_han_thu_110","textTraditional":"至武帝建元四年，佗孫胡為南粵王。立三年，閩粵王郢興兵南擊邊邑。粵使人上書曰：「兩粵俱為藩臣，毋擅興兵相攻擊。今東粵擅興兵侵臣，臣不敢興兵，唯天子詔之。」於是天子多南粵義，〔一〕守職約，〔二〕為興師，遣兩將軍往討閩粵。兵未隃領，閩粵王弟餘善殺郢以降，於是罷兵。","sentenceOrder":138},
  {"id":"s_work_han_thu_110_139","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「多猶重也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_110_140","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「守藩臣之職，而不踰約制。」","sentenceOrder":140},
  {"id":"s_work_han_thu_110_141","chapterId":"ch_work_han_thu_110","textTraditional":"天子使嚴助往諭意，南粵王胡頓首曰：「天子乃興兵誅閩粵，死亡以報德！」遣太子嬰齊入宿衛。謂助曰：「國新被寇，使者行矣。胡方日夜裝入見天子。」助去後，其大臣諫胡曰：「漢興兵誅郢，亦行以驚動南粵。且先王言事天子期毋失禮，要之不可以怵好語入見。〔一〕入見則不得復歸，亡國之勢也。」於是胡稱病，竟不入見。後十餘歲，胡實病甚，太子嬰齊請歸。胡薨，諡曰文王。","sentenceOrder":141},
  {"id":"s_work_han_thu_110_142","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「怵，誘也。不可被誘怵以好語而入漢朝也。怵音先聿反。」","sentenceOrder":142},
  {"id":"s_work_han_thu_110_143","chapterId":"ch_work_han_thu_110","textTraditional":"嬰齊嗣立，即臧其先武帝、文帝璽。〔一〕嬰齊在長安時，取邯鄲摎氏女，〔二〕生子興。及即位，上書請立摎氏女為后，興為嗣。漢數使使者風諭，〔三〕嬰齊猶尚樂擅殺生自恣，懼入見，要以用漢法，比內諸侯，固稱病，遂不入見。遣子次公入宿衛，嬰齊薨，諡為明王。","sentenceOrder":143},
  {"id":"s_work_han_thu_110_144","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　李奇曰：「去其僭號。」","sentenceOrder":144},
  {"id":"s_work_han_thu_110_145","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「摎音居虯反。」","sentenceOrder":145},
  {"id":"s_work_han_thu_110_146","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「風讀曰諷。諷諭令入朝。」","sentenceOrder":146},
  {"id":"s_work_han_thu_110_147","chapterId":"ch_work_han_thu_110","textTraditional":"太子興嗣立，其母為太后，太后自未為嬰齊妻時，曾與霸陵人安國少季通。〔一〕及嬰齊薨後，元鼎四年，漢使安國少季諭王、王太后入朝，令辯士諫大夫終軍等宣其辭，勇士魏臣等輔其決，〔二〕衛尉路博德將兵屯桂陽，待使者。王年少，太后中國人，安國少季往，復與私通，國人頗知之，多不附太后。太后恐亂起，亦欲倚漢威〔三〕，勸王及幸臣求內屬。即因使者上書，請比內諸侯，三歲壹朝，除邊關。於是天子許之，賜其丞相呂嘉銀印，及內史、中尉、太傅印，餘得自置。〔四〕除其故黥劓刑，用漢法。諸使者皆留填撫之。〔五〕王、王太后飭治行裝重資，為入朝具。","sentenceOrder":147},
  {"id":"s_work_han_thu_110_148","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「姓安國，字少季。」","sentenceOrder":148},
  {"id":"s_work_han_thu_110_149","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「助令決策也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_110_150","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「倚音於綺反。」","sentenceOrder":150},
  {"id":"s_work_han_thu_110_151","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「丞相、內史、中尉、太傅之外，皆任其國自選置，不受漢之印綬。」","sentenceOrder":151},
  {"id":"s_work_han_thu_110_152","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「填音竹刃反。」","sentenceOrder":152},
  {"id":"s_work_han_thu_110_153","chapterId":"ch_work_han_thu_110","textTraditional":"相呂嘉年長矣，相三王，宗族官貴為長吏七十餘人，男盡尚王女，女盡嫁王子弟宗室，及蒼梧秦王有連。〔一〕其居國中甚重，粵人信之，多為耳目者，得眾心愈於王。〔二〕王之上書，數諫止王，王不聽。有畔心，數稱病不見漢使者。使者注意嘉，勢未能誅。王、王太后亦恐嘉等先事發，欲介使者權，謀誅嘉等。〔三〕置酒請使者，大臣皆侍坐飲。嘉弟為將，將卒居宮外。酒行，太后謂嘉：「南粵內屬，國之利，而相君苦不便者，何也？」以激怒使者。使者狐疑相杖，遂不敢發。〔四〕嘉見耳目非是，〔五〕即趨出。太后怒，欲鏦嘉以矛，〔六〕王止太后。嘉遂出，介弟兵就舍，〔七〕稱病，不肯見王及使者。乃陰謀作亂，王素亡意誅嘉，嘉知之，以故數月不發。太后獨欲誅嘉等，力又不能。","sentenceOrder":153},
  {"id":"s_work_han_thu_110_154","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　孟康曰：「蒼梧，越中王，自名為秦王。連，親婚也。」晉灼曰：「秦王即下趙光也。趙本與秦同姓，故曰秦王。」","sentenceOrder":154},
  {"id":"s_work_han_thu_110_155","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「愈，勝也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_110_156","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰；「介，恃也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_110_157","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「杖音直亮反。」","sentenceOrder":157},
  {"id":"s_work_han_thu_110_158","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「異於常也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_110_159","chapterId":"ch_work_han_thu_110","textTraditional":"〔六〕　師古曰：「鏦謂撞刺之也，音{穴怱}。」","sentenceOrder":159},
  {"id":"s_work_han_thu_110_160","chapterId":"ch_work_han_thu_110","textTraditional":"〔七〕　李奇曰：「介，被也。」師古曰：「介，甲也，被甲而自衛也，弟兵即上所云弟將卒居外者。」","sentenceOrder":160},
  {"id":"s_work_han_thu_110_161","chapterId":"ch_work_han_thu_110","textTraditional":"天子聞之，罪使者怯亡決。又以為王、王太后已附漢，獨呂嘉為亂，不足以興兵，欲使莊參以二千人往。參曰：「以好往，數人足；以武往，二千人亡足以為也。」辭不可，天子罷參兵。郟壯士故濟北相韓千秋〔一〕奮曰：「以區區粵，又有王應，獨呂嘉為害，願得勇士三百人，必斬嘉以報。」於是天子遣千秋與王太后弟摎樂將二千人往。入粵境，呂嘉乃遂反，下令國中曰：「王年少。太后中國人，又與使者亂，專欲內屬，盡持先王寶入獻天子以自媚，多從人，行至長安，虜賣以為僮。取自脫一時利，亡顧趙氏社稷為萬世慮之意。」乃與其弟將卒攻殺太后、王，盡殺漢使者。遣人告蒼梧秦王及其諸郡縣，立明王長男粵妻子術陽侯建德為王。而韓千秋兵之入也，破數小邑。其後粵直開道給食，〔二〕未至番禺四十里，粵以兵擊千秋等，滅之。使人函封漢使節置塞上，好為謾辭謝罪，〔三〕發兵守要害處。於是天子曰：「韓千秋雖亡成功，亦軍鋒之冠。〔四〕封其子延年為成安侯。摎樂，其姊為王太后，首願屬漢，封其子廣德為龒侯。〔五〕」乃赦天下，曰：「天子微弱，諸侯力政，譏臣不討賊。〔六〕呂嘉、建德等反，自立晏如，〔七〕令粵人及江淮以南樓船十萬師往討之。」","sentenceOrder":161},
  {"id":"s_work_han_thu_110_162","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「潁川郟縣人也。郟音夾。」","sentenceOrder":162},
  {"id":"s_work_han_thu_110_163","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「縱之令深入，然後誅滅之。」","sentenceOrder":163},
  {"id":"s_work_han_thu_110_164","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「謾，誑也，音慢，又音莫連反。」","sentenceOrder":164},
  {"id":"s_work_han_thu_110_165","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「言最為首也。」","sentenceOrder":165},
  {"id":"s_work_han_thu_110_166","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　晉灼曰：「龒，古龍字。」","sentenceOrder":166},
  {"id":"s_work_han_thu_110_167","chapterId":"ch_work_han_thu_110","textTraditional":"〔六〕　師古曰：「力政謂以兵力相加也。譏臣不討賊者，春秋之義。」","sentenceOrder":167},
  {"id":"s_work_han_thu_110_168","chapterId":"ch_work_han_thu_110","textTraditional":"〔七〕　師古曰：「言自相置立，而心安泰無恐懼。」","sentenceOrder":168},
  {"id":"s_work_han_thu_110_169","chapterId":"ch_work_han_thu_110","textTraditional":"元鼎五年秋，衛尉路博德為伏波將軍，出桂陽，下湟水；〔一〕主爵都尉楊僕為樓船將軍，出豫章，下橫浦；故歸義粵侯二人為戈船、下瀨將軍，〔二〕出零陵，或下離水，或抵蒼梧；使馳義侯因巴蜀罪人，發夜郎兵，下牂柯江：咸會番禺。","sentenceOrder":169},
  {"id":"s_work_han_thu_110_170","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「湟音皇。」","sentenceOrder":170},
  {"id":"s_work_han_thu_110_171","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「從粵來歸義，而漢封之。」","sentenceOrder":171},
  {"id":"s_work_han_thu_110_172","chapterId":"ch_work_han_thu_110","textTraditional":"六年冬，樓船將軍將精卒先陷尋陿，破石門，得粵船粟，因推而前，挫粵鋒，以粵數萬人待伏波將軍。伏波將軍將罪人，道遠後期，與樓船會乃有千餘人，遂俱進。樓船居前，至番禺，建德、嘉皆城守。樓船自擇便處，居東南面，伏波居西北面。會暮，樓船攻敗粵人，縱火燒城。粵素聞伏波，莫，不知其兵多少。〔一〕伏波乃為營〔二〕，遣使招降者，賜印綬，復縱令相招。〔三〕樓船力攻燒敵，〔四〕反敺而入伏波營中。〔五〕遲旦，城中皆降伏波。〔六〕呂嘉、建德以夜與其屬數百人亡入海。伏波又問降者，知嘉所之，遣人追。故其校司馬蘇弘得建德，為海常侯；〔七〕粵郎都稽得嘉，為臨蔡侯。〔八〕","sentenceOrder":172},
  {"id":"s_work_han_thu_110_173","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「莫讀曰暮。」","sentenceOrder":173},
  {"id":"s_work_han_thu_110_174","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「設營壘以待降者。」","sentenceOrder":174},
  {"id":"s_work_han_thu_110_175","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「來降者即賜以侯印，而放令還，更相招諭之也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_110_176","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「力，盡力也。」","sentenceOrder":176},
  {"id":"s_work_han_thu_110_177","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「敺與驅同。」","sentenceOrder":177},
  {"id":"s_work_han_thu_110_178","chapterId":"ch_work_han_thu_110","textTraditional":"〔六〕　師古曰：「遲音丈二反。解在高紀。」","sentenceOrder":178},
  {"id":"s_work_han_thu_110_179","chapterId":"ch_work_han_thu_110","textTraditional":"〔七〕　師古曰：「校之司馬，若今行軍總管司馬也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_110_180","chapterId":"ch_work_han_thu_110","textTraditional":"〔八〕　孟康曰：「越中所自置郎也。」師古曰：「稽音雞。」","sentenceOrder":180},
  {"id":"s_work_han_thu_110_181","chapterId":"ch_work_han_thu_110","textTraditional":"蒼梧王趙光與粵王同姓，聞漢兵至，降，為隨桃侯。（又）〔及〕粵揭陽令史定降漢，為安道侯。〔一〕粵將畢取以軍降，為膫侯。〔二〕粵桂林監居翁〔三〕諭告甌駱四十餘萬口降，為湘城侯。戈船、下瀨將軍兵及馳義侯所發夜郎兵未下，南粵已平。遂以其地為儋耳、珠崖、南海、蒼梧、鬱林、合浦、交阯、九真、日南九郡。伏波將軍益封。樓船將軍以推鋒陷堅為將梁侯。","sentenceOrder":181},
  {"id":"s_work_han_thu_110_182","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　蘇林曰：「揭音羯。南海縣。」","sentenceOrder":182},
  {"id":"s_work_han_thu_110_183","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「越將姓畢名取也。功臣表膫屬南陽，音來彫反。」","sentenceOrder":183},
  {"id":"s_work_han_thu_110_184","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　服虔曰：「桂林部監也。姓居名翁。」","sentenceOrder":184},
  {"id":"s_work_han_thu_110_185","chapterId":"ch_work_han_thu_110","textTraditional":"自尉佗王凡五世，九十三歲而亡。","sentenceOrder":185},
  {"id":"s_work_han_thu_110_186","chapterId":"ch_work_han_thu_110","textTraditional":"閩粵王無諸及粵東海王搖，其先皆粵王句踐之後也，姓騶氏。秦并天下，廢為君長，以其地為閩中郡。〔一〕及諸侯畔秦，無諸、搖率粵歸番陽令吳芮，所謂番君者也，〔二〕從諸侯滅秦。當是時，項羽主命，不王也，〔三〕以故不佐楚。漢擊項籍，無諸、搖帥粵人佐漢。漢五年，復立無諸為閩粵王，王閩中故地，都冶。〔四〕孝惠三年，舉高帝時粵功，〔五〕曰閩君搖功多，其民便附，乃立搖為東海王，都東甌，世號曰東甌王。","sentenceOrder":186},
  {"id":"s_work_han_thu_110_187","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「即今之泉州建安是也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_110_188","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「吳芮號也。番音蒲河反。」","sentenceOrder":188},
  {"id":"s_work_han_thu_110_189","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　孟康曰：「主號命諸侯，不王無諸、搖等也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_110_190","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「地名，即侯官縣是也。冶音弋者反。」","sentenceOrder":190},
  {"id":"s_work_han_thu_110_191","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「追論其功。」","sentenceOrder":191},
  {"id":"s_work_han_thu_110_192","chapterId":"ch_work_han_thu_110","textTraditional":"后數世，〔一〕孝景三年，吳王濞反，欲從閩粵，〔二〕閩粵未肯行，獨東甌從。及吳破，東甌受漢購，殺吳王丹徒，以故得不誅。","sentenceOrder":192},
  {"id":"s_work_han_thu_110_193","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「后與後同，古通用字。」","sentenceOrder":193},
  {"id":"s_work_han_thu_110_194","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「招粵令從也。」","sentenceOrder":194},
  {"id":"s_work_han_thu_110_195","chapterId":"ch_work_han_thu_110","textTraditional":"吳王子駒亡走閩粵，怨東甌殺其父，常勸閩粵擊東甌。建元三年，閩粵發兵圍東甌，東甌使人告急天子。天子問太尉田蚡，蚡對曰：「粵人相攻擊，固其常，不足以煩中國往救也。」中大夫嚴助詰蚡，言當救。天子遣助發會稽郡兵浮海救之，語具在助傳。漢兵未至，閩粵引兵去。東粵請舉國徙中國，乃悉與眾處江淮之間。","sentenceOrder":195},
  {"id":"s_work_han_thu_110_196","chapterId":"ch_work_han_thu_110","textTraditional":"六年，閩粵擊南粵，南粵守天子約，不敢擅發兵，而以聞。上遣大行王恢出豫章，大司農韓安國出會稽，皆為將軍。兵未隃領，閩粵王郢發兵距險。其弟餘善與宗族謀曰：「王以擅發兵，不請，故天子兵來誅。漢兵眾強，即幸勝之，後來益多，〔一〕滅國乃止。今殺王以謝天子，天子罷兵，固國完。不聽乃力戰，不勝即亡入海。」皆曰：「善。」即鏦殺王，〔二〕使使奉其頭致大行。大行曰：「所為來者，誅王。王頭至，不戰而殞，利莫大焉。」乃以便宜案兵告大司農軍，而使使奉王頭馳報天子。詔罷兩將軍兵，曰：「郢等首惡，獨無諸孫繇君丑不與謀。」〔三〕乃使郎中將立丑為粵繇王，奉閩粵祭祀。","sentenceOrder":196},
  {"id":"s_work_han_thu_110_197","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「言漢地廣大，兵眾盛強，今雖勝之，後必更來也。」","sentenceOrder":197},
  {"id":"s_work_han_thu_110_198","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「鏦音初江反。」","sentenceOrder":198},
  {"id":"s_work_han_thu_110_199","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　張晏曰：「繇，邑號也。」師古曰：「繇音搖。與讀曰豫。」","sentenceOrder":199},
  {"id":"s_work_han_thu_110_200","chapterId":"ch_work_han_thu_110","textTraditional":"餘善以殺郢，威行國中，民多屬，竊自立為王，繇王不能制。上聞之，為餘善不足復興師，曰：「餘善首誅郢，師得不勞。」因立餘善為東粵王，與繇王並處。","sentenceOrder":200},
  {"id":"s_work_han_thu_110_201","chapterId":"ch_work_han_thu_110","textTraditional":"至元鼎五年，南粵反，餘善上書請以卒八（十）〔千〕從樓船擊呂嘉等。兵至揭陽，以海風波為解，〔一〕不行，持兩端，陰使南粵。〔二〕及漢破番禺，樓船將軍僕上書願請引兵擊東粵。上以士卒勞倦，不許。罷兵，令諸校留屯豫章梅領待命。〔三〕","sentenceOrder":201},
  {"id":"s_work_han_thu_110_202","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「解者，自解說，若今言分疏。」","sentenceOrder":202},
  {"id":"s_work_han_thu_110_203","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「遣使與相知。」","sentenceOrder":203},
  {"id":"s_work_han_thu_110_204","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「聽詔命也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_110_205","chapterId":"ch_work_han_thu_110","textTraditional":"明年秋，餘善聞樓船請誅之，漢兵留境，且往，〔一〕乃遂發兵距漢道，號將軍騶力等為「吞漢將軍」，入白沙、武林、梅領，殺漢三校尉。是時，漢使大司農張成、故山州侯齒將屯，〔二〕不敢擊，卻就便處，〔三〕皆坐畏懦誅。餘善刻「武帝」璽自立，詐其民，為妄言。〔四〕上遣橫海將軍韓說出句章，〔五〕浮海從東方往；樓船將軍僕出武林，〔六〕中尉王溫舒出梅領，粵侯為戈船、下瀨將軍出如邪、白沙，元封元年冬，咸入東粵。東粵素發兵距嶮，使徇北將軍守武林，敗樓船軍數校尉，殺長史。樓船軍卒錢唐榬終古斬徇北將軍，〔七〕為語兒侯。〔八〕自兵未往。","sentenceOrder":205},
  {"id":"s_work_han_thu_110_206","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「言兵在境首，恐將來討之。」","sentenceOrder":206},
  {"id":"s_work_han_thu_110_207","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「齒，城陽恭王子也，舊封山州侯。」","sentenceOrder":207},
  {"id":"s_work_han_thu_110_208","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「卻，退也，音丘略反。」","sentenceOrder":208},
  {"id":"s_work_han_thu_110_209","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「妄自尊大也。」","sentenceOrder":209},
  {"id":"s_work_han_thu_110_210","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「說讀曰悅。句章，會稽之縣。」","sentenceOrder":210},
  {"id":"s_work_han_thu_110_211","chapterId":"ch_work_han_thu_110","textTraditional":"〔六〕　師古曰：「楊僕也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_110_212","chapterId":"ch_work_han_thu_110","textTraditional":"〔七〕　師古曰：「錢唐，會稽縣也。榬，姓；終古，名也。榬音袁。」","sentenceOrder":212},
  {"id":"s_work_han_thu_110_213","chapterId":"ch_work_han_thu_110","textTraditional":"〔八〕　孟康曰：「越中地也。今吳南亭是。」師古曰：「語字或作篽，或作籞，其音同。」","sentenceOrder":213},
  {"id":"s_work_han_thu_110_214","chapterId":"ch_work_han_thu_110","textTraditional":"故粵衍侯吳陽前在漢，漢使歸諭餘善，不聽。及橫海軍至，陽以其邑七百人反，攻粵軍於漢陽。及故粵建成侯敖與繇王居股謀，俱殺餘善，以其眾降橫海軍。封居股為東成侯，萬戶；封敖為開陵侯〔一〕；封陽為卯石侯，〔二〕橫海將軍說為按道侯，橫海校尉福為繚嫈侯。〔三〕福者，城陽王子，故為海常侯，坐法失爵，從軍亡功，以宗室故侯。及東粵將多軍，〔四〕漢兵至，棄軍降，封為無錫侯。故甌駱將左黃同斬西于王，封為下鄜侯。〔五〕","sentenceOrder":214},
  {"id":"s_work_han_thu_110_215","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「功臣表云開陵侯建成以故東粵建成侯斬餘善侯，二千戶。而此傳云名敖，疑表誤。」","sentenceOrder":215},
  {"id":"s_work_han_thu_110_216","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「功臣表作外石，與此不同，疑表誤。」","sentenceOrder":216},
  {"id":"s_work_han_thu_110_217","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「繚音遼。嫈音於耕反。」","sentenceOrder":217},
  {"id":"s_work_han_thu_110_218","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　李奇曰：「多軍，名。」","sentenceOrder":218},
  {"id":"s_work_han_thu_110_219","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「鄜音郛。」","sentenceOrder":219},
  {"id":"s_work_han_thu_110_220","chapterId":"ch_work_han_thu_110","textTraditional":"於是天子曰「東粵陿多阻，閩粵悍，數反覆」，〔一〕詔軍吏皆將其民徙處江淮之間。東粵地遂虛。","sentenceOrder":220},
  {"id":"s_work_han_thu_110_221","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「悍，勇也。」","sentenceOrder":221},
  {"id":"s_work_han_thu_110_222","chapterId":"ch_work_han_thu_110","textTraditional":"朝鮮王滿，燕人。自始燕時，嘗略屬真番、朝鮮，〔一〕為置吏築障。〔二〕秦滅燕，屬遼東外徼。漢興，為遠難守，復修遼東故塞，至浿水為界，〔三〕屬燕。燕王盧綰反，入匈奴，滿亡命，聚黨千餘人，椎結蠻夷服而東走出塞，度浿水，居秦故空地上下障，稍役屬真番、朝鮮蠻夷及故燕、齊亡在者王之，〔四〕都王險。〔五〕","sentenceOrder":222},
  {"id":"s_work_han_thu_110_223","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「戰國時燕國略得此地。」","sentenceOrder":223},
  {"id":"s_work_han_thu_110_224","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「障，所以自障蔽也，音之亮反。」","sentenceOrder":224},
  {"id":"s_work_han_thu_110_225","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「浿水在樂浪縣，音普蓋反。」","sentenceOrder":225},
  {"id":"s_work_han_thu_110_226","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「燕、齊之人亡居此地，及真番、朝鮮蠻夷皆屬滿也。」","sentenceOrder":226},
  {"id":"s_work_han_thu_110_227","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　李奇曰：「地名也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_110_228","chapterId":"ch_work_han_thu_110","textTraditional":"會孝惠、高后天下初定，遼東太守即約滿為外臣，保塞外蠻夷，毋使盜邊；蠻夷君長欲入見天子，勿得禁止。以聞，上許之，以故滿得以兵威財物侵降其旁小邑，真番、臨屯皆來服屬，方數千里。","sentenceOrder":228},
  {"id":"s_work_han_thu_110_229","chapterId":"ch_work_han_thu_110","textTraditional":"傳子至孫右渠，〔一〕所誘漢亡人滋多，〔二〕又未嘗入見〔三〕；真番、辰國欲上書見天子，又雍閼弗通。〔四〕元封二年，漢使涉何譙諭右渠，終不肯奉詔。〔五〕何去至界，臨浿水，使馭刺殺送何者朝鮮裨王長，〔六〕即渡水，馳入塞，遂歸報天子曰「殺朝鮮將」。上為其名美，弗詰，拜何為遼東東部都尉。朝鮮怨何，發兵攻襲，殺何。","sentenceOrder":229},
  {"id":"s_work_han_thu_110_230","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「滿死傳子，子死傳孫。右渠者，其孫名也。」","sentenceOrder":230},
  {"id":"s_work_han_thu_110_231","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「滋，益也。」","sentenceOrder":231},
  {"id":"s_work_han_thu_110_232","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「不朝見天子也。」","sentenceOrder":232},
  {"id":"s_work_han_thu_110_233","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「辰謂辰韓之國也。雍讀曰壅。」","sentenceOrder":233},
  {"id":"s_work_han_thu_110_234","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰；「譙，責讓也，音才笑反。」","sentenceOrder":234},
  {"id":"s_work_han_thu_110_235","chapterId":"ch_work_han_thu_110","textTraditional":"〔六〕　師古曰；「長者，裨王名也。送何至浿水，何因刺殺之。」","sentenceOrder":235},
  {"id":"s_work_han_thu_110_236","chapterId":"ch_work_han_thu_110","textTraditional":"天子募罪人擊朝鮮。其秋，遣樓船將軍楊僕從齊浮勃海，兵五萬，左將軍荀彘出遼東，誅右渠。右渠發兵距險。左將軍卒多率遼東士〔一〕兵先縱，敗散。多還走，坐法斬。〔二〕樓船將齊兵七千人先至王險。右渠城守，窺知樓船軍少，即出擊樓船，樓船軍敗走。將軍僕失其眾，遁山中十餘日，稍求收散卒，復聚。左將軍擊朝鮮浿水西軍，未能破。","sentenceOrder":236},
  {"id":"s_work_han_thu_110_237","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　如淳曰：「遼東兵多也。」","sentenceOrder":237},
  {"id":"s_work_han_thu_110_238","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「於法合斬。」","sentenceOrder":238},
  {"id":"s_work_han_thu_110_239","chapterId":"ch_work_han_thu_110","textTraditional":"天子為兩將未有利，乃使衛山因兵威往諭右渠。右渠見使者，頓首謝：「願降，恐將詐殺臣；今見信節，請服降。」遣太子入謝，獻馬五千匹，及餽軍糧。〔一〕人眾萬餘持兵，方度浿水，使者及左將軍疑其為變，謂太子已服降，宜令人毋持兵。太子亦疑使者左將軍詐之，遂不度浿水，復引歸。山報，天子誅山。","sentenceOrder":239},
  {"id":"s_work_han_thu_110_240","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「餽亦饋字。」","sentenceOrder":240},
  {"id":"s_work_han_thu_110_241","chapterId":"ch_work_han_thu_110","textTraditional":"左將軍破浿水上軍，乃前至城下，圍其西北。樓船亦往會，居城南。右渠遂堅城守，數月未能下。","sentenceOrder":241},
  {"id":"s_work_han_thu_110_242","chapterId":"ch_work_han_thu_110","textTraditional":"左將軍素侍中，幸，〔一〕將燕代卒，悍，乘勝，軍多驕。樓船將齊卒，入海已多敗亡，其先與右渠戰，困辱亡卒，卒皆恐，將心慚，其圍右渠，常持和節。左將軍急擊之，朝鮮大臣乃陰間使人私約降樓船，〔二〕往來言，尚未肯決。左將軍數與樓船期戰，樓船欲就其約，不會左將軍亦使人求間隙降下朝鮮，不肯，心附樓船。以故兩將不相得。左將軍心意樓船前有失軍罪，〔三〕今與朝鮮和善而又不降，疑其有反計，未敢發。天子曰：「將率不能前，乃使衛山諭降右渠，不能顓決，與左將軍相誤，卒沮約。〔四〕今兩將圍城又乖異，以故久不決。」使故濟南太守公孫遂往正之，有便宜得以從事。遂至，左將軍曰：「朝鮮當下久矣，不下者，樓船數期不會。」具以素所意告遂曰：「今如此不取，恐為大害，非獨樓船，又且與朝鮮共滅吾軍。」遂亦以為然，而以節召樓船將軍入左將軍軍計事，即今左將軍戲下執縛樓船將軍，〔五〕并其軍。以報，天子（許）〔誅〕遂。","sentenceOrder":242},
  {"id":"s_work_han_thu_110_243","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰：「親幸於天子。」","sentenceOrder":243},
  {"id":"s_work_han_thu_110_244","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「與樓船為要約而請降。」","sentenceOrder":244},
  {"id":"s_work_han_thu_110_245","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「意，疑也。」","sentenceOrder":245},
  {"id":"s_work_han_thu_110_246","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「顓與專同。卒，終也。沮，壞也。」","sentenceOrder":246},
  {"id":"s_work_han_thu_110_247","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「戲讀與麾同。」","sentenceOrder":247},
  {"id":"s_work_han_thu_110_248","chapterId":"ch_work_han_thu_110","textTraditional":"左將軍已并兩軍，即急擊朝鮮。朝鮮相路人、相韓陶、尼谿相參、將軍王唊〔一〕相與謀曰：「始欲降樓船，樓船今執，獨左將軍并將，戰益急，恐不能與，〔二〕王又不肯降。」陶、唊路人皆亡降漢。路人道死。元封三年夏，尼谿相參乃使人殺朝鮮王右渠來降。王險城未下，故右渠之大臣成已又反，復攻吏。左將軍使右渠子長、〔三〕降相路人子最，〔四〕告諭其民，誅成已。故遂定朝鮮為真番、臨屯、樂浪、玄菟四郡。封參為澅清侯，〔五〕陶為秋苴侯，〔六〕唊為平州侯，長為幾侯。最以父死頗有功，為沮陽侯。左將軍徵至，坐爭功相嫉乖計，棄市。樓船將軍亦坐兵至列口當待左將軍，〔七〕擅先縱，失亡多，當誅，贖為庶人。","sentenceOrder":248},
  {"id":"s_work_han_thu_110_249","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　應劭曰：「凡五人也，戎狄不知官紀，故皆稱相。」師古曰：「相路人一也，相韓陶二也，尼谿相參三也，將軍王唊四也。應氏乃云五人，誤讀為句，謂尼谿人名，失之矣。不當尋下文乎？唊音頰。」","sentenceOrder":249},
  {"id":"s_work_han_thu_110_250","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　如淳曰：「不能與左將軍相持也。」師古曰：「此說非也。不能與猶言不如也。」","sentenceOrder":250},
  {"id":"s_work_han_thu_110_251","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「右渠之子名長。」","sentenceOrder":251},
  {"id":"s_work_han_thu_110_252","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰：「相路人前已降漢而死於道，故謂之降相。最者，其子名。」","sentenceOrder":252},
  {"id":"s_work_han_thu_110_253","chapterId":"ch_work_han_thu_110","textTraditional":"〔五〕　師古曰：「澅音獲。」","sentenceOrder":253},
  {"id":"s_work_han_thu_110_254","chapterId":"ch_work_han_thu_110","textTraditional":"〔六〕　晉灼曰：「功臣表秋苴屬勃海。」師古曰：「苴音千餘反。」","sentenceOrder":254},
  {"id":"s_work_han_thu_110_255","chapterId":"ch_work_han_thu_110","textTraditional":"〔七〕　蘇林曰：「列口，縣名也。度海先得之。」","sentenceOrder":255},
  {"id":"s_work_han_thu_110_256","chapterId":"ch_work_han_thu_110","textTraditional":"贊曰：楚、粵之先，歷世有土。及周之衰，楚地方五千里，而句踐亦以粵伯。〔一〕秦滅諸侯，唯楚尚有滇王。漢誅西南夷，獨滇復寵。及東粵滅國遷眾，繇王居股等猶為萬戶侯。三方之開，皆自好事之臣。故西南夷發於唐蒙、司馬相如，兩粵起嚴助、朱買臣，朝鮮由涉何。遭世富盛，〔動〕能成功，然已勤矣。〔二〕追觀太宗填撫尉佗，〔三〕豈古所謂「招攜以禮，懷遠以德」者哉！〔四〕","sentenceOrder":256},
  {"id":"s_work_han_thu_110_257","chapterId":"ch_work_han_thu_110","textTraditional":"〔一〕　師古曰；「伯讀曰霸。」","sentenceOrder":257},
  {"id":"s_work_han_thu_110_258","chapterId":"ch_work_han_thu_110","textTraditional":"〔二〕　師古曰：「已，甚也。言其事甚勤勞。」","sentenceOrder":258},
  {"id":"s_work_han_thu_110_259","chapterId":"ch_work_han_thu_110","textTraditional":"〔三〕　師古曰：「言文帝以恩德安撫之也。填音竹刃反。」","sentenceOrder":259},
  {"id":"s_work_han_thu_110_260","chapterId":"ch_work_han_thu_110","textTraditional":"〔四〕　師古曰；「春秋左氏傳僖七年諸侯盟于甯母，管仲言於齊侯曰：『臣聞之，招攜以禮，懷遠以德。』攜謂離貳者也。懷，來也。言有離貳者則招集之，恃險遠者則懷來之也。故贊引之。」","sentenceOrder":260},
  {"id":"s_work_han_thu_110_261","chapterId":"ch_work_han_thu_110","textTraditional":"校勘記","sentenceOrder":261},
  {"id":"s_work_han_thu_110_262","chapterId":"ch_work_han_thu_110","textTraditional":"三八三七頁　三行　（西）〔南〕夷君長以十數，　錢大昭說「西」當作「南」。按景祐、殿、局本都作「南」。","sentenceOrder":262},
  {"id":"s_work_han_thu_110_263","chapterId":"ch_work_han_thu_110","textTraditional":"三八三九頁　九行　從巴（莋）〔苻〕關入，　王念孫說「莋」是「苻」之誤。　按景祐本正作「苻」。","sentenceOrder":263},
  {"id":"s_work_han_thu_110_264","chapterId":"ch_work_han_thu_110","textTraditional":"三八四０頁　一行　子形如（赤）〔桑〕椹耳。　景祐、殿、局本都作「桑」。","sentenceOrder":264},
  {"id":"s_work_han_thu_110_265","chapterId":"ch_work_han_thu_110","textTraditional":"三八四四頁一二行　一時，（二）〔三〕月也。　景祐、汲古、殿、局本都作「三」，　此誤。","sentenceOrder":265},
  {"id":"s_work_han_thu_110_266","chapterId":"ch_work_han_thu_110","textTraditional":"三八四九頁一０行　高后（白）〔自〕臨事，　景祐、汲古、殿、局本都作「自」。　王先謙說「白」乃轉寫誤耳。","sentenceOrder":266},
  {"id":"s_work_han_thu_110_267","chapterId":"ch_work_han_thu_110","textTraditional":"三八五八頁一五行　（又）〔及〕粵揭陽令史定降漢，　景祐、殿本都作「及」。","sentenceOrder":267},
  {"id":"s_work_han_thu_110_268","chapterId":"ch_work_han_thu_110","textTraditional":"三八六一頁　九行　以卒八（十）〔千〕　景祐、殿、局本都作「千」。王先謙說作「千」是。","sentenceOrder":268},
  {"id":"s_work_han_thu_110_269","chapterId":"ch_work_han_thu_110","textTraditional":"三八六五頁　五行　左將軍卒多率遼東〔一〕士兵先縱，　王先謙說史記作「卒正多」，　多是卒正名，如解非。","sentenceOrder":269},
  {"id":"s_work_han_thu_110_270","chapterId":"ch_work_han_thu_110","textTraditional":"三八六六頁一一行　天子（許）〔誅〕遂。　王先謙說史記贊「荀彘爭勞，與遂皆誅」，作「誅」無疑。　按各本皆誤。","sentenceOrder":270},
  {"id":"s_work_han_thu_110_271","chapterId":"ch_work_han_thu_110","textTraditional":"三八六八頁　四行　〔動〕能成功，　景祐、殿本都有「動」字。","sentenceOrder":271},
  {"id":"s_work_han_thu_111_1","chapterId":"ch_work_han_thu_111","textTraditional":"師古曰：「自烏孫國已後分為下卷。」","sentenceOrder":1},
  {"id":"s_work_han_thu_111_2","chapterId":"ch_work_han_thu_111","textTraditional":"西域以孝武時始通，本三十六國，其後稍分至五十餘，〔一〕皆在匈奴之西，烏孫之南。南北有大山，中央有河，東西六千餘里，南北千餘里。東則接漢，阨以玉門、陽關，〔二〕西則限以蔥嶺。〔三〕其南山，東出金城，與漢南山屬焉。〔四〕其河有兩原：一出蔥嶺山，一出于闐。〔五〕于闐在南山下，其河北流，與蔥嶺河合，東注蒲昌海。蒲昌海，一名鹽澤者也，去玉門、陽關三百餘里，廣袤三百里。〔六〕其水亭居，冬夏不增減，皆以為潛行地下，南出於積石，為中國河云。","sentenceOrder":2},
  {"id":"s_work_han_thu_111_3","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「司馬彪續漢書云至于哀、平，有五十五國也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_111_4","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　孟康曰：「（陽）〔二〕關皆在敦煌西界。」師古曰：「阨，塞也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_111_5","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「西河舊事云蔥嶺其山高大，上悉生蔥，故以名焉。」","sentenceOrder":5},
  {"id":"s_work_han_thu_111_6","chapterId":"ch_work_han_thu_111","textTraditional":"〔四〕　師古曰：「屬，聯也，音之欲反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_111_7","chapterId":"ch_work_han_thu_111","textTraditional":"〔五〕　師古曰：「闐字與寘同，音徒賢反，又音徒見反。」","sentenceOrder":7},
  {"id":"s_work_han_thu_111_8","chapterId":"ch_work_han_thu_111","textTraditional":"〔六〕　師古曰：「袤，長也，音茂。」","sentenceOrder":8},
  {"id":"s_work_han_thu_111_9","chapterId":"ch_work_han_thu_111","textTraditional":"自玉門、陽關出西域有兩道。從鄯善傍南山北，波河西行至莎車，為南道；〔一〕南道西踰蔥嶺則出大月氏、安息。〔二〕自車師前王廷隨北山，波河西行至疏勒，為北道；北道西踰蔥嶺則出大宛、康居、奄蔡焉（耆）。","sentenceOrder":9},
  {"id":"s_work_han_thu_111_10","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「波河，循河也。鄯音上扇反。傍音步浪反。波音彼義反。此下皆同也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_111_11","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「氏音支。」","sentenceOrder":11},
  {"id":"s_work_han_thu_111_12","chapterId":"ch_work_han_thu_111","textTraditional":"西域諸國大率土著，〔一〕有城郭田畜，與匈奴、烏孫異俗，故皆役屬匈奴。〔二〕匈奴西邊日逐王置僮僕都尉，使領西域，常居焉耆、危須、尉黎間，賦稅諸國，取富給焉。〔三〕","sentenceOrder":12},
  {"id":"s_work_han_thu_111_13","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「言著土地而有常居，不隨畜牧移徙也。著音直略反。」","sentenceOrder":13},
  {"id":"s_work_han_thu_111_14","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「服屬於匈奴，為其所役使也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_111_15","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「給，足也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_111_16","chapterId":"ch_work_han_thu_111","textTraditional":"自周衰，戎狄錯居涇渭之北。〔一〕及秦始皇攘卻戎狄，築長城，界中國，〔二〕然西不過臨洮。〔三〕","sentenceOrder":16},
  {"id":"s_work_han_thu_111_17","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「錯，雜也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_111_18","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「為中國之竟界也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_111_19","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「洮音土高反。」","sentenceOrder":19},
  {"id":"s_work_han_thu_111_20","chapterId":"ch_work_han_thu_111","textTraditional":"漢興至于孝武，事征四夷，廣威德，而張騫始開西域之跡。其後驃騎將軍擊破匈奴右地，降渾邪、休屠王，〔一〕遂空其地，始築令居以西，〔二〕初置酒泉郡，後稍發徙民充實之，分置武威、張掖、敦煌，〔三〕列四郡，據兩關焉。自貳師將軍伐大宛之後，西域震懼，多遣使來貢獻，漢使西域者益得職。〔四〕於是自敦煌西至鹽澤，往往起亭，而輪臺、渠犁皆有田卒數百人，置使者校尉領護，〔五〕以給使外國者。〔六〕","sentenceOrder":20},
  {"id":"s_work_han_thu_111_21","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「屠音除。」","sentenceOrder":21},
  {"id":"s_work_han_thu_111_22","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「令音鈴。」","sentenceOrder":22},
  {"id":"s_work_han_thu_111_23","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「敦音徒門反。」","sentenceOrder":23},
  {"id":"s_work_han_thu_111_24","chapterId":"ch_work_han_thu_111","textTraditional":"〔四〕　師古曰：「賞其勤勞，皆得拜職也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_111_25","chapterId":"ch_work_han_thu_111","textTraditional":"〔五〕　師古曰：「統領保護營田之事也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_111_26","chapterId":"ch_work_han_thu_111","textTraditional":"〔六〕　師古曰：「收其所種五穀以供之。」","sentenceOrder":26},
  {"id":"s_work_han_thu_111_27","chapterId":"ch_work_han_thu_111","textTraditional":"至宣帝時，遣衛司馬使護鄯善以西數國。及破姑師，未盡殄〔一〕，分以為車師前後王及山北六國。時漢獨護南道，未能盡并北道也，然匈奴不自安矣。其後日逐王畔單于，將眾來降，護鄯善以西使者鄭吉迎之。既至漢，封日逐王為歸德侯，吉為安遠侯。是歲，神爵三年也。乃因使吉并護北道，故號曰都護。都護之起，自吉置矣。〔二〕僮僕都尉由此罷，匈奴益弱，不得近西域。於是徙屯田，田於北胥鞬，〔三〕披莎車之地，〔四〕屯田校尉始屬都護。都護督察烏孫、康居諸外國〔五〕動靜，有變以聞。可安輯，安輯之；可擊，擊之。〔六〕都護治烏壘城，去陽關二千七百三十八里，與渠犁田官相近，土地肥饒，於西域為中，故都護治焉。","sentenceOrder":27},
  {"id":"s_work_han_thu_111_28","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「雖破其國，未能滅之。」","sentenceOrder":28},
  {"id":"s_work_han_thu_111_29","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「都猶總也，言總護南北之道。」","sentenceOrder":29},
  {"id":"s_work_han_thu_111_30","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「胥鞬，地名也。胥音先餘反。鞬音居言反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_111_31","chapterId":"ch_work_han_thu_111","textTraditional":"〔四〕　師古曰：「披，分也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_111_32","chapterId":"ch_work_han_thu_111","textTraditional":"〔五〕　師古曰：「督，視也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_111_33","chapterId":"ch_work_han_thu_111","textTraditional":"〔六〕　師古曰：「輯與集同。」","sentenceOrder":33},
  {"id":"s_work_han_thu_111_34","chapterId":"ch_work_han_thu_111","textTraditional":"至元帝時，復置戊己校尉，屯田車師前王庭。是時匈奴東蒲類王茲力支將人眾千七百餘人降都護，都護分車師後王之西為烏貪訾離地以處之。","sentenceOrder":34},
  {"id":"s_work_han_thu_111_35","chapterId":"ch_work_han_thu_111","textTraditional":"自宣、元後，單于稱藩臣，西域服從，其土地山川王侯戶數道里遠近翔實矣。〔一〕","sentenceOrder":35},
  {"id":"s_work_han_thu_111_36","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「翔與詳同，假借用耳。」","sentenceOrder":36},
  {"id":"s_work_han_thu_111_37","chapterId":"ch_work_han_thu_111","textTraditional":"出陽關，自近者始，曰婼羌。〔一〕婼羌國王號去胡來王。〔二〕去陽關千八百里，去長安六千三百里，辟在西南，不當孔道。〔三〕戶四百五十，口千七百五十，勝兵者五百人。西與且末接。〔四〕隨畜逐水草，不田作，仰鄯善、且末穀。〔五〕山有鐵，自作兵，兵有弓、矛、服刀、劍、甲。〔六〕西北至鄯善，乃當道云。","sentenceOrder":37},
  {"id":"s_work_han_thu_111_38","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　孟康曰：「婼音兒。」師古曰：「音而遮反。」","sentenceOrder":38},
  {"id":"s_work_han_thu_111_39","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「言去離胡戎來附漢也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_111_40","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「辟讀曰僻。孔道者，穿山險而為道，猶今言穴徑耳。」","sentenceOrder":40},
  {"id":"s_work_han_thu_111_41","chapterId":"ch_work_han_thu_111","textTraditional":"〔四〕　師古曰：「且音子餘反。」","sentenceOrder":41},
  {"id":"s_work_han_thu_111_42","chapterId":"ch_work_han_thu_111","textTraditional":"〔五〕　師古曰：「賴以自給也。仰音牛向反。」","sentenceOrder":42},
  {"id":"s_work_han_thu_111_43","chapterId":"ch_work_han_thu_111","textTraditional":"〔六〕　劉德曰：「服刀，拍髀也。」師古曰：「拍音貊。髀音俾，又音陛。」","sentenceOrder":43},
  {"id":"s_work_han_thu_111_44","chapterId":"ch_work_han_thu_111","textTraditional":"鄯善國，本名樓蘭，王治扜泥城，〔一〕去陽關千六百里，去長安六千一百里。戶千五百七十，口萬四千一百，勝兵二千九百十二人。輔國侯、卻胡侯、〔二〕鄯善都尉、擊車師都尉、左右且渠、擊車師君各一人，譯長二人。西北去都護治所千七百八十五里，至山國千三百六十五里，〔三〕西北至車師千八百九十里。地沙鹵，少田，寄田仰穀旁國。〔四〕國出玉，多葭葦、檉柳、胡桐、白草。〔五〕民隨畜牧逐水草，有驢馬，多橐它。〔六〕能作兵，與婼羌同。","sentenceOrder":44},
  {"id":"s_work_han_thu_111_45","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「扜音一胡反。」","sentenceOrder":45},
  {"id":"s_work_han_thu_111_46","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「卻音丘略反，其字從卩，卩音節。下皆類此。」","sentenceOrder":46},
  {"id":"s_work_han_thu_111_47","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「此國山居，故名山國也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_111_48","chapterId":"ch_work_han_thu_111","textTraditional":"〔四〕　師古曰：「寄於它國種田，又糴旁國之穀也。仰音牛向反。」","sentenceOrder":48},
  {"id":"s_work_han_thu_111_49","chapterId":"ch_work_han_thu_111","textTraditional":"〔五〕　孟康曰：「白草，草之白者。胡桐似桑而多曲。」師古曰：「檉柳，河柳也，今謂之赤檉。白草似莠而細，無芒，其乾孰時正白色，牛馬所嗜也。胡桐亦似桐，不類桑也。蟲食其樹而沫出下流者，俗名為胡桐淚，言似眼淚也，可以汗金銀也，今工匠皆用之。流俗語訛呼淚為律。檉音丑成反。」","sentenceOrder":49},
  {"id":"s_work_han_thu_111_50","chapterId":"ch_work_han_thu_111","textTraditional":"〔六〕　師古曰：「它，古他字也，音徒何反。」","sentenceOrder":50},
  {"id":"s_work_han_thu_111_51","chapterId":"ch_work_han_thu_111","textTraditional":"初，武帝感張騫之言，甘心欲通大宛諸國，使者相望於道，一歲中多至十餘輩。樓蘭、姑師當道，苦之，〔一〕攻劫漢使王恢等，又數為匈奴耳目，令其兵遮漢使。漢使多言其國有城邑，兵弱易擊。於是武帝遣從票侯趙破奴將屬國騎〔二〕及郡兵數萬擊姑師。王恢數為樓蘭所苦，上令恢佐破奴將兵。破奴與輕騎七百人先至，虜樓蘭王，遂破姑師，因暴兵威以動烏孫、大宛之屬。〔三〕還，封破奴為浞野侯，恢為浩侯。〔四〕於是漢列亭障至玉門矣。","sentenceOrder":51},
  {"id":"s_work_han_thu_111_52","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「每供給使者受其勞費，故厭苦之。」","sentenceOrder":52},
  {"id":"s_work_han_thu_111_53","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「屬國謂諸外國屬漢也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_111_54","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「暴謂顯揚也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_111_55","chapterId":"ch_work_han_thu_111","textTraditional":"〔四〕　蘇林曰：「浩音昊。」","sentenceOrder":55},
  {"id":"s_work_han_thu_111_56","chapterId":"ch_work_han_thu_111","textTraditional":"樓蘭既降服貢獻，匈奴聞，發兵擊之。於是樓蘭遣一子質匈奴，一子質漢。後貳師軍擊大宛，匈奴欲遮之，貳師兵盛不敢當，即遣騎因樓蘭候漢使後過者，欲絕勿通。時漢軍正任文將兵屯玉門關，為貳師後距，〔一〕捕得生口，知狀以聞。上詔文便道引兵捕樓蘭王。將詣闕，簿責王，〔二〕對曰：「小國在大國間，不兩屬無以自安。願徙國入居漢地。」上直其言，遣歸國，〔三〕亦因使候司匈奴。匈奴自是不甚親信樓蘭。","sentenceOrder":56},
  {"id":"s_work_han_thu_111_57","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「後距者，居後以距敵。」","sentenceOrder":57},
  {"id":"s_work_han_thu_111_58","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「以文簿一一責之。簿音（簿）〔步〕戶反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_111_59","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「以其言為直。」","sentenceOrder":59},
  {"id":"s_work_han_thu_111_60","chapterId":"ch_work_han_thu_111","textTraditional":"征和元年，樓蘭王死，國人來請質子在漢者，欲立之。質子常坐漢法，下蠶室宮刑，故不遣。報曰：「侍子，天子愛之，不能遣。其更立其次當立者。」樓蘭更立王，漢復責其質子，亦遣一子質匈奴。後王又死，匈奴先聞之，遣質子歸，得立為王。〔一〕漢遣使詔新王，令入朝，天子將加厚賞。樓蘭王後妻，故繼母也，謂王曰：「先王遣兩子質漢皆不還，奈何欲往朝乎？」王用其計，謝使曰：「新立，國未定，願待後年入見天子。」然樓蘭國最在東垂，近漢，當白龍堆，乏水草，常主發導，負水儋糧，送迎漢使，又數為吏卒所寇，懲艾不便與漢通。〔二〕後復為匈奴反間，〔三〕數遮殺漢使。其弟尉屠耆降漢，具言狀。","sentenceOrder":60},
  {"id":"s_work_han_thu_111_61","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「匈奴在漢前聞樓蘭王死，故即遣質子還也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_111_62","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「艾讀曰乂。」","sentenceOrder":62},
  {"id":"s_work_han_thu_111_63","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「間音居莧反。」","sentenceOrder":63},
  {"id":"s_work_han_thu_111_64","chapterId":"ch_work_han_thu_111","textTraditional":"元鳳四年，大將軍霍光白遣平樂監傅介子往刺其王。介子輕將勇敢士，齎金幣，揚言以賜外國為名。既至樓蘭，詐其王欲賜之，王喜，與介子飲，醉，將其王屏語，壯士二人從後刺殺之，貴人左右皆散走。介子告諭以「王負漢罪，天子遣我誅王，當更立王弟尉屠耆在漢者。漢兵方至，毋敢動，自令滅國矣！」介子遂斬王嘗歸首，〔一〕馳傳詣闕，〔二〕縣首北闕下。封介子為義陽侯。乃立尉屠耆為王，更名其國為鄯善，為刻印章，賜宮女為夫人，備車騎輜重，〔三〕丞相〔將軍〕率百官送至橫門外，〔四〕祖而遣之。〔五〕王自請天子曰：「身在漢久，今歸，單弱，而前王有子在，恐為所殺。國中有伊循城，其地肥美，願漢遣（二）〔一〕將屯田積穀，令臣得依其威重。」於是漢遣司馬一人、吏士四十人，田伊循以填撫之。〔六〕其後更置都尉。伊循官置始此矣。","sentenceOrder":64},
  {"id":"s_work_han_thu_111_65","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「嘗歸者，其王名也。昭紀言安歸，今此作嘗歸，紀傳不同，當有誤者。」","sentenceOrder":65},
  {"id":"s_work_han_thu_111_66","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「傳音張戀反。」","sentenceOrder":66},
  {"id":"s_work_han_thu_111_67","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「重音直用反。」","sentenceOrder":67},
  {"id":"s_work_han_thu_111_68","chapterId":"ch_work_han_thu_111","textTraditional":"〔四〕　孟康曰：「橫音光。」","sentenceOrder":68},
  {"id":"s_work_han_thu_111_69","chapterId":"ch_work_han_thu_111","textTraditional":"〔五〕　師古曰：「為設祖道之禮也。」","sentenceOrder":69},
  {"id":"s_work_han_thu_111_70","chapterId":"ch_work_han_thu_111","textTraditional":"〔六〕　師古曰：「填音竹刃反。」","sentenceOrder":70},
  {"id":"s_work_han_thu_111_71","chapterId":"ch_work_han_thu_111","textTraditional":"鄯善當漢道衝，西通且末七百二十里。自且末以往皆種五穀，土地草木，畜產作兵，略與漢同，有異乃記云。","sentenceOrder":71},
  {"id":"s_work_han_thu_111_72","chapterId":"ch_work_han_thu_111","textTraditional":"且末國，王治且末城，去長安六千八百二十里。戶二百三十，口千六百一十，勝兵三百二十人。輔國侯、左右將、譯長各一人。西北至都護治所二千二百五十八里，北接尉犁，南至小宛可三日行。有蒲陶諸果。西通精絕二千里。","sentenceOrder":72},
  {"id":"s_work_han_thu_111_73","chapterId":"ch_work_han_thu_111","textTraditional":"小宛國，王治扜零城，〔一〕去長安七千二百一十里。戶百五十，口千五十，勝兵二百人。輔國侯、左右都尉各一人。西北至都護治所二千五百五十八里，東與婼羌接，辟南不當道。〔二〕","sentenceOrder":73},
  {"id":"s_work_han_thu_111_74","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「扜音烏。」","sentenceOrder":74},
  {"id":"s_work_han_thu_111_75","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「辟讀曰僻。下皆類此。」","sentenceOrder":75},
  {"id":"s_work_han_thu_111_76","chapterId":"ch_work_han_thu_111","textTraditional":"精絕國，王治精絕城，去長安八千八百二十里。戶四百八十，口三千三百六十，勝兵五百人。精絕都尉、左右將、譯長各一人。北至都護治所二千七百二十三里，南至戎盧國四日行，地阨陿，西通扜彌四百六十里。〔一〕","sentenceOrder":76},
  {"id":"s_work_han_thu_111_77","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「扜音烏。」","sentenceOrder":77},
  {"id":"s_work_han_thu_111_78","chapterId":"ch_work_han_thu_111","textTraditional":"戎盧國，王治卑品城，去長安八千三百里。戶二百四十，口千六百一十，勝兵三百人。東北至都護治所二千八百五十八里，東與小宛、南與婼羌、西與渠勒接，辟南不當道。","sentenceOrder":78},
  {"id":"s_work_han_thu_111_79","chapterId":"ch_work_han_thu_111","textTraditional":"扜彌國，王治扜彌城，去長安九千二百八十里。戶三千三百四十，口二萬四十，勝兵三千五百四十人。輔國侯、左右將、左右都尉、左右騎君各一人，譯長二人。東北至都護治所三千五百五十三里，南與渠勒、東北與龜茲、西北與姑墨接，〔一〕西通于闐三百九十里。今名寧彌。","sentenceOrder":79},
  {"id":"s_work_han_thu_111_80","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「龜音丘。茲音慈。」","sentenceOrder":80},
  {"id":"s_work_han_thu_111_81","chapterId":"ch_work_han_thu_111","textTraditional":"渠勒國，王治鞬都城，〔一〕去長安九千九百五十里。戶三百一十，口二千一百七十，勝兵三百人。東北至都護治所三千八百五十二里，東與戎盧、西與婼羌、北與扜彌接。","sentenceOrder":81},
  {"id":"s_work_han_thu_111_82","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「鞬音居言反。」","sentenceOrder":82},
  {"id":"s_work_han_thu_111_83","chapterId":"ch_work_han_thu_111","textTraditional":"于闐國，王治西城，去長安九千六百七十里。戶三千三百，口萬九千三百，勝兵二千四百人。輔國侯、左右將、左右騎君、東西城長、譯長各一人。東北至都護治所三千九百四十七里，南與婼羌接，北與姑墨接。于闐之西，水皆西流，注西海；其東，水東流，注鹽澤，河原出焉。〔一〕多玉石。〔二〕西通皮山三百八十里。","sentenceOrder":83},
  {"id":"s_work_han_thu_111_84","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　蘇林曰：「即中國河也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_111_85","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「玉石，玉之璞也。一曰石之似玉也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_111_86","chapterId":"ch_work_han_thu_111","textTraditional":"皮山國，王治皮山城，去長安萬五十里。戶五百，口三千五百，勝兵五百人。左右將、左右都尉、騎君、譯長各一人。東北至都護治所四千二百九十二里，西南至烏秅國千三百四十里，〔一〕南與天篤接，北至姑墨千四百五十里，西南當罽賓、烏弋山離道，西北通莎車三百八十里。","sentenceOrder":86},
  {"id":"s_work_han_thu_111_87","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　鄭氏曰：「烏秅音鷃拏。」師古曰：「烏音一加反。秅音直加反。急言之聲如鷃拏耳，非正音也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_111_88","chapterId":"ch_work_han_thu_111","textTraditional":"烏秅國，王治烏秅城，去長安九千九百五十里。戶四百九十，口二千七百三十三，勝兵七百四十人。東北至都護治所四千八百九十二里，北與子合、蒲犁，西與難兜接。山居，田石間。有白草。累石為室。民接手飲。〔一〕出小步馬，〔二〕有驢無牛。其西則有縣度，〔三〕去陽關五千八百八十八里，去都護治所五千二（百）〔十〕里。縣度者，石山也，谿谷不通，以繩索相引而度云。","sentenceOrder":88},
  {"id":"s_work_han_thu_111_89","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「自高山下谿澗中飲水，故接連其手，如蝯之為。」","sentenceOrder":89},
  {"id":"s_work_han_thu_111_90","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　孟康曰：「種小能步也。」師古曰：「此說非也。小，細也。細步，〔言其〕能蹀足，即今所謂百步千跡者也。豈謂其小種乎？」","sentenceOrder":90},
  {"id":"s_work_han_thu_111_91","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「縣繩而度也。縣，古懸字耳。」","sentenceOrder":91},
  {"id":"s_work_han_thu_111_92","chapterId":"ch_work_han_thu_111","textTraditional":"西夜國，王號子合王，治呼犍谷，〔一〕去長安萬二百五十里。戶三百五十，口四千，勝兵千人。東北到都護治所五千四十六里，東與皮山、西南與烏秅、北與莎車、西與蒲犁接。蒲犁（反）〔及〕依耐、無雷國〔二〕皆西夜類也。西夜與胡異，其種類羌氐行國，〔三〕隨畜逐水草往來。而子合土地出玉石。","sentenceOrder":92},
  {"id":"s_work_han_thu_111_93","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「犍音鉅言反。」","sentenceOrder":93},
  {"id":"s_work_han_thu_111_94","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「耐音奴代反。」","sentenceOrder":94},
  {"id":"s_work_han_thu_111_95","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「言不土著也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_111_96","chapterId":"ch_work_han_thu_111","textTraditional":"蒲犁國，王治蒲犁谷，去長安九千五百五十里。戶六百五十，口五千，勝兵二千人。東北至都護治所五千三百九十六里，東至莎車五百四十里，北至疏勒五百五十里，南與西夜子合接，西至無雷五百四十里。侯、都尉各一人。寄田莎車。種俗與子合同。","sentenceOrder":96},
  {"id":"s_work_han_thu_111_97","chapterId":"ch_work_han_thu_111","textTraditional":"依耐國，王治去長安萬一百五十里。戶一百二十五，口六百七十，勝兵三百五十人。東北至都護治所二千七百三十里，至莎車五百四十里，至無雷五百四十里，北至疏勒六百五十里，南與子合接，俗相與同。〔一〕少穀，寄田疏勒、莎車。","sentenceOrder":97},
  {"id":"s_work_han_thu_111_98","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「與子合同風俗也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_111_99","chapterId":"ch_work_han_thu_111","textTraditional":"無雷國，王治盧城，去長安九千九百五十里。戶千，口七千，勝兵三千人。東北至都護治所二千四百六十五里，南至蒲犁五百四十里，南與烏秅、北與捐毒、西與大月氏接。〔一〕衣服類烏孫，俗與子合同。","sentenceOrder":99},
  {"id":"s_work_han_thu_111_100","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「捐毒即身毒、天篤也，本皆一名，語有輕重耳。」","sentenceOrder":100},
  {"id":"s_work_han_thu_111_101","chapterId":"ch_work_han_thu_111","textTraditional":"難兜國，王治去長安萬一百五十里。戶五千，口三萬一千，勝兵八千人。東北至都護治所二千八百五十里，西至無雷三百四十里，西南至罽賓三百三十里，南與婼羌、北與休循、西與大月氏接。種五穀、蒲陶諸果。有銀銅鐵，作兵與諸國同，屬罽賓。","sentenceOrder":101},
  {"id":"s_work_han_thu_111_102","chapterId":"ch_work_han_thu_111","textTraditional":"罽賓國，王治循鮮城，去長安萬二千二百里。不屬都護。戶口勝兵多，大國也。東北至都護治所六千八百四十里，東至烏秅國二千二百五十里，東北至難兜國九日行，西北與大月氏、西南與烏弋山離接。","sentenceOrder":102},
  {"id":"s_work_han_thu_111_103","chapterId":"ch_work_han_thu_111","textTraditional":"昔匈奴破大月氏，大月氏西君大夏，而塞王南君罽賓。〔一〕塞種分散，往往為數國。〔二〕自疏勒以西北，休循、捐毒之屬，皆故塞種也。","sentenceOrder":103},
  {"id":"s_work_han_thu_111_104","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「君謂為之君也。塞音先得反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_111_105","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「即所謂釋種者也，亦語有輕重耳。」","sentenceOrder":105},
  {"id":"s_work_han_thu_111_106","chapterId":"ch_work_han_thu_111","textTraditional":"罽賓地平，溫和，有目宿，雜草奇木，檀、櫰、梓、竹、漆〔一〕。種五穀、蒲陶諸果，糞治園田。地下溼，生稻，冬食生菜。其民巧，雕文刻鏤，治宮室，織罽，剌文繡，好治食。有金銀銅錫，以為器。市列。〔二〕以金銀為錢，文為騎馬，幕為人面。〔三〕出封牛、水牛、象、大狗、沐猴、孔爵、〔四〕珠璣、珊瑚、虎魄、璧流離。〔五〕它畜與諸國同。","sentenceOrder":106},
  {"id":"s_work_han_thu_111_107","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「櫰音懷。即槐之類也，葉大而黑也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_111_108","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「市有列肆，亦如中國也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_111_109","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　張晏曰：「錢文面作騎馬形，漫面作人面目也。」如淳曰：「幕音漫。」師古曰：「幕即漫耳，無勞借音。今所呼幕皮者，亦謂其平而無文也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_111_110","chapterId":"ch_work_han_thu_111","textTraditional":"〔四〕　師古曰：「封牛，項上隆起者也。郭義恭廣志云罽賓大狗大如驢，赤色，數里搖鞉以呼之。沐猴即獮猴也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_111_111","chapterId":"ch_work_han_thu_111","textTraditional":"〔五〕　孟康曰：「流離青色如玉。」師古曰：「魏略云大秦國出赤、白、黑、黃、青、綠、縹、紺、紅、紫十種流離。孟言青色，不博通也。此蓋自然之物，采澤光潤，踰於眾玉，其色不恆。今俗所用，皆銷（洽）〔治〕石汁，加以眾藥，灌而為之，尤虛脆不貞，實非真物。」","sentenceOrder":111},
  {"id":"s_work_han_thu_111_112","chapterId":"ch_work_han_thu_111","textTraditional":"自武帝始通罽賓，自以絕遠，漢兵不能至，其王烏頭勞數剽殺漢使。〔一〕烏頭勞死，子代立，遣使奉獻。漢使關都尉文忠送其使。王復欲害忠，忠覺之，乃與容屈王子陰末赴共合謀，攻罽賓，殺其王，立陰末赴為罽賓王，授印綬。後軍候趙德使罽賓。與陰末赴相失，〔二〕陰末赴鎖琅當德，〔三〕殺副已下七十餘人，遣使者上書謝。孝元帝以絕域不錄，放其使者於縣度，絕而不通。","sentenceOrder":112},
  {"id":"s_work_han_thu_111_113","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「剽，劫也，音頻妙反。」","sentenceOrder":113},
  {"id":"s_work_han_thu_111_114","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「相失意也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_111_115","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「琅當，長鎖也，若今之禁繫人鎖矣。琅音郎。」","sentenceOrder":115},
  {"id":"s_work_han_thu_111_116","chapterId":"ch_work_han_thu_111","textTraditional":"成帝時，復遣使獻謝罪，漢欲遣使者報送其使，杜欽說大將軍王鳳曰：「前罽賓王陰末赴本漢所立，後卒畔逆。〔一〕夫德莫大於有國子民，罪莫大於執殺使者，所以不報恩，不懼誅者，自知絕遠，兵不至也。有求則卑辭，無欲則嬌嫚，終不可懷服。凡中國所以為通厚蠻夷，{匧心}快其求者，為壤比而為寇也。〔二〕今縣度之阨，非罽賓所能越也。其鄉慕，不足以安西域；〔三〕雖不附，不能危城郭。〔四〕前親逆節，惡暴西域，〔五〕故絕而不通；今悔過來，而無親屬貴人，奉獻者皆行賈賤人，欲通貨市買，以獻為名，故煩使者送至縣度，恐失實見欺。凡遣使送客者，欲為防護寇害也。起皮山南，更不屬漢之國四五，〔六〕斥候士百餘人，五分夜擊刀斗自守，〔七〕尚時為所侵盜。驢畜負糧，須諸國稟食，得以自贍。〔八〕國或貧小不能食，或桀黠不肯給，擁彊漢之節，餒山谷之間，〔九〕乞匄無所得，〔一０〕離一二旬則人畜棄捐曠野而不反。〔一一〕又歷大頭痛、小頭痛之山，赤土、身熱之阪，令人身熱無色，頭痛嘔吐，驢畜盡然。〔一二〕又有三池、盤石阪，道陿者尺六七寸，長者徑三十里。臨崢嶸不測之深，〔一三〕行者騎步相持，繩索相引，二千餘里乃到縣度。畜隊，未半阬谷盡靡碎；〔一四〕人墮，勢不得相收視。險阻危害，不可勝言。聖王分九州，制五服，〔一五〕務盛內，不求外。今遣使者承至尊之命，送蠻夷之賈，勞吏士之眾，涉危難之路，罷弊所恃以事無用，〔一六〕非久長計也。使者業已受節，可至皮山而還。」〔一七〕於是鳳白從欽言。罽賓實利賞賜賈市，其使數年而壹至云。","sentenceOrder":116},
  {"id":"s_work_han_thu_111_117","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「卒，終也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_111_118","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「比，近也。為其土壤接近，能為寇也。{匧心}音苦頰反，比音頻寐反。」","sentenceOrder":118},
  {"id":"s_work_han_thu_111_119","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":119},
  {"id":"s_work_han_thu_111_120","chapterId":"ch_work_han_thu_111","textTraditional":"〔四〕　師古曰：「城郭，總謂西域諸國也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_111_121","chapterId":"ch_work_han_thu_111","textTraditional":"〔五〕　師古曰：「暴謂章露也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_111_122","chapterId":"ch_work_han_thu_111","textTraditional":"〔六〕　師古曰：「言經歷不屬漢者凡四五國也。更音工衡反。」","sentenceOrder":122},
  {"id":"s_work_han_thu_111_123","chapterId":"ch_work_han_thu_111","textTraditional":"〔七〕　師古曰：「夜有五更，故分而持之也。刀斗，解在李廣傳。」","sentenceOrder":123},
  {"id":"s_work_han_thu_111_124","chapterId":"ch_work_han_thu_111","textTraditional":"〔八〕　師古曰：「稟，給也。贍，足也。食讀曰飤。次下並同。」","sentenceOrder":124},
  {"id":"s_work_han_thu_111_125","chapterId":"ch_work_han_thu_111","textTraditional":"〔九〕　師古曰：「餒，飢也，音能賄反。」","sentenceOrder":125},
  {"id":"s_work_han_thu_111_126","chapterId":"ch_work_han_thu_111","textTraditional":"〔一０〕師古曰：「匄亦乞也，音工大反。」","sentenceOrder":126},
  {"id":"s_work_han_thu_111_127","chapterId":"ch_work_han_thu_111","textTraditional":"〔一一〕師古曰：「離亦歷也。曠，空也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_111_128","chapterId":"ch_work_han_thu_111","textTraditional":"〔一二〕師古曰：「嘔音一口反。」","sentenceOrder":128},
  {"id":"s_work_han_thu_111_129","chapterId":"ch_work_han_thu_111","textTraditional":"〔一三〕師古曰：「崢嶸，深險之貌也。崢音仕耕反。嶸音宏。」","sentenceOrder":129},
  {"id":"s_work_han_thu_111_130","chapterId":"ch_work_han_thu_111","textTraditional":"〔一四〕師古曰：「隊亦墮也。靡，散也。隊音直類反。靡音縻。」","sentenceOrder":130},
  {"id":"s_work_han_thu_111_131","chapterId":"ch_work_han_thu_111","textTraditional":"〔一五〕師古曰：「九州：冀、兗、豫、青、徐、荊、揚、梁、雍也。五服：侯、甸、綏、要、荒。」","sentenceOrder":131},
  {"id":"s_work_han_thu_111_132","chapterId":"ch_work_han_thu_111","textTraditional":"〔一六〕師古曰：「罷讀曰疲。所恃，謂中國之人也。無用，謂遠方蠻夷之國。」","sentenceOrder":132},
  {"id":"s_work_han_thu_111_133","chapterId":"ch_work_han_thu_111","textTraditional":"〔一七〕師古曰：「言已立計遣之，不能即止，可至皮山也。」","sentenceOrder":133},
  {"id":"s_work_han_thu_111_134","chapterId":"ch_work_han_thu_111","textTraditional":"烏弋山離國，王去長安萬二千二百里。不屬都護。戶口勝兵，大國也。東北至都護治所六十日行，東與罽賓、北與撲挑、西與犁靬、條支接。〔一〕","sentenceOrder":134},
  {"id":"s_work_han_thu_111_135","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「撲音布木反。犁讀與驪同。靬音鉅連反，又鉅言反。」","sentenceOrder":135},
  {"id":"s_work_han_thu_111_136","chapterId":"ch_work_han_thu_111","textTraditional":"行可百餘日，乃至條支。國臨西海，暑溼，田稻。有大鳥，卵如甕。〔一〕人眾甚多，往往有小君長，安息役屬之，以為外國。〔二〕善眩。〔三〕安息長老傳聞條支有弱水、西王母。亦未嘗見也〔四〕。自條支乘水西行，可百餘日，近日所入云。","sentenceOrder":136},
  {"id":"s_work_han_thu_111_137","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「甕，汲水瓶也，音於龍反。」","sentenceOrder":137},
  {"id":"s_work_han_thu_111_138","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「安息以條支為外國，如言蕃國也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_111_139","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「眩讀與幻同，解在張騫傳。」","sentenceOrder":139},
  {"id":"s_work_han_thu_111_140","chapterId":"ch_work_han_thu_111","textTraditional":"〔四〕　師古曰：「玄中記云『昆侖之弱水，鴻毛不能起』也。爾雅曰『觚竹、北戶、西王母、日下，謂之四荒』也。」","sentenceOrder":140},
  {"id":"s_work_han_thu_111_141","chapterId":"ch_work_han_thu_111","textTraditional":"烏弋地暑熱莽平，〔一〕其草木、畜產、五穀、果菜、食飲、宮室、市列、錢貨、兵器、金珠之屬皆與罽賓同，而有桃拔、師子、犀牛。〔二〕俗重妄殺。〔三〕其錢獨文為人頭。幕為騎馬。以金銀飾杖。〔四〕絕遠，漢使希至。自玉門、陽關出南道，歷鄯善而南行，至烏弋山離，南道極矣。","sentenceOrder":141},
  {"id":"s_work_han_thu_111_142","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「言有草莽而平坦也。一曰莽莽平野之貌。」","sentenceOrder":142},
  {"id":"s_work_han_thu_111_143","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　孟康曰：「桃拔一名符拔，似鹿，長尾，一角者或為天鹿，（者）兩角〔者〕或為辟邪。師子似虎，正黃有〈冉頁〉耏，尾端茸毛大如斗。」師古曰：「師子即爾雅所謂狻猊也。狻音酸。猊音倪。拔音步葛反。耏亦頰旁毛也，音而。茸音人庸反。」","sentenceOrder":143},
  {"id":"s_work_han_thu_111_144","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「重，難也。言其仁愛不妄殺也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_111_145","chapterId":"ch_work_han_thu_111","textTraditional":"〔四〕　師古曰：「杖謂所持兵器也，音直亮反。」","sentenceOrder":145},
  {"id":"s_work_han_thu_111_146","chapterId":"ch_work_han_thu_111","textTraditional":"安息國，王治番兜城，〔一〕去長安萬一千六百里。不屬都護。北與康居、東與烏弋山離、西與條支接。土地風氣，物類所有，民俗與烏弋、罽賓同。亦以銀為錢，文獨為王面，幕為夫人面。王死輒更鑄錢。有大馬爵。〔二〕其屬小大數百城，地方數千里，最大國也。臨媯水，商賈車船行旁國。書革，旁行為書記。〔三〕","sentenceOrder":146},
  {"id":"s_work_han_thu_111_147","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　蘇林曰：「番音盤。」","sentenceOrder":147},
  {"id":"s_work_han_thu_111_148","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「廣志云『大爵，頸及膺身，蹄似橐駝，色蒼，舉頭高八九尺，張翅丈餘，食大麥』。」","sentenceOrder":148},
  {"id":"s_work_han_thu_111_149","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　服虔曰：「橫行為書記也。」師古曰：「今西方胡國及南方林邑之徒，書皆橫行，不直下也。革為皮之不柔者。」","sentenceOrder":149},
  {"id":"s_work_han_thu_111_150","chapterId":"ch_work_han_thu_111","textTraditional":"武帝始遣使至安息，王令將將二萬騎迎於東界。東界去王都數千里，行比至，過數十城，人民相屬。〔一〕因發使隨漢使者來觀漢地，以大鳥卵及犁靬眩人獻於漢，天子大說。〔二〕安息東則大月氏。","sentenceOrder":150},
  {"id":"s_work_han_thu_111_151","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「屬，聯也，音之欲反。」","sentenceOrder":151},
  {"id":"s_work_han_thu_111_152","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":152},
  {"id":"s_work_han_thu_111_153","chapterId":"ch_work_han_thu_111","textTraditional":"大月氏國，治監氏城，去長安萬一千六百里。不屬都護。戶十萬，口四十萬，勝兵十萬人。東至都護治所四千七百四十里，西至安息四十九日行，南與罽賓接。土地風氣，物類所有，民俗錢貨，與安息同。出一封橐駝。〔一〕","sentenceOrder":153},
  {"id":"s_work_han_thu_111_154","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「脊上有一封也，封言其隆高，若封土也。今俗呼為封牛。封音峰。」","sentenceOrder":154},
  {"id":"s_work_han_thu_111_155","chapterId":"ch_work_han_thu_111","textTraditional":"大月氏本行國也，隨畜移徙，與匈奴同俗。控弦十餘萬，故彊輕匈奴。〔一〕本居敦煌、祁連間，至冒頓單于攻破月氏，而老上單于殺月氏，以其頭為飲器，月氏乃遠去，過大宛，西擊大夏而臣之〔二〕，都媯水北為王庭。其餘小眾不能去者，保南山羌，號小月氏。","sentenceOrder":155},
  {"id":"s_work_han_thu_111_156","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「自恃其彊盛，而輕易匈奴也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_111_157","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「解在張騫傳。」","sentenceOrder":157},
  {"id":"s_work_han_thu_111_158","chapterId":"ch_work_han_thu_111","textTraditional":"大夏本無大君長，城邑往往置小長，民弱畏戰，故月氏徙來，皆臣畜之，共稟漢使者。〔一〕有五翕侯：〔二〕一曰休密翕侯，治和墨城，去都護二千八百四十一里，去陽關七千八百二里；二曰雙靡翕侯，治雙靡城，去都護三千七百四十一里，去陽關七千七百八十二里；三曰貴霜翕侯，治護澡城，〔五〕去都護五千九百四十里，去陽關七千九百八十二里；四曰肸頓翕侯，〔四〕治薄茅城，去都護五千九百六十二里，去陽關八千二百二里；五曰高附歙侯，治高附城，去都護六千四十一里，去陽關九千二百八十三里。凡五翕侯，皆屬大月氏。","sentenceOrder":158},
  {"id":"s_work_han_thu_111_159","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「同受節度也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_111_160","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「歙即翕字。」","sentenceOrder":160},
  {"id":"s_work_han_thu_111_161","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「澡音藻。」","sentenceOrder":161},
  {"id":"s_work_han_thu_111_162","chapterId":"ch_work_han_thu_111","textTraditional":"〔四〕　師古曰：「肸音許乙反。」","sentenceOrder":162},
  {"id":"s_work_han_thu_111_163","chapterId":"ch_work_han_thu_111","textTraditional":"康居國，王冬治樂越匿地。〔一〕到卑闐城。〔二〕去長安萬二千三百里。不屬都護。至越匿地馬行七日，至王夏所居蕃內九千一百四里。〔三〕戶十二萬，口六十萬，勝兵十二萬人。東至都護治所五千五百五十里。與大月氏同俗。東羈事匈奴。〔四〕","sentenceOrder":163},
  {"id":"s_work_han_thu_111_164","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「樂音來各反。」","sentenceOrder":164},
  {"id":"s_work_han_thu_111_165","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「闐音徒千反。」","sentenceOrder":165},
  {"id":"s_work_han_thu_111_166","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「王每冬寒夏暑，則徙別居不一處。」","sentenceOrder":166},
  {"id":"s_work_han_thu_111_167","chapterId":"ch_work_han_thu_111","textTraditional":"〔四〕　師古曰：「為匈奴所羈牽也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_111_168","chapterId":"ch_work_han_thu_111","textTraditional":"宣帝時，匈奴乖亂，五單于並爭，漢擁立呼韓邪單于，而郅支單于怨望，殺漢使者，西阻康居。〔一〕其後都護甘延壽、副校尉陳湯發戊已校尉西域諸國兵至康居，誅滅郅支單于，語在甘延壽、陳湯傳。是歲，元帝建昭三年也。","sentenceOrder":168},
  {"id":"s_work_han_thu_111_169","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「依其險阻，以自保固也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_111_170","chapterId":"ch_work_han_thu_111","textTraditional":"至成帝時，康居遣子侍漢，貢獻，然自以絕遠，獨驕嫚，不肯與諸國相望。都護郭舜數上言：「本匈奴盛時，非以兼有烏孫、康居故也；及其稱臣妾，非以失二國也。漢雖皆受其質子，然三國內相輸遺，交通如故，亦相候司，見便則發；合不能相親信，離不能相臣役。以今言之，結配烏孫竟未有益，反為中國生事。然烏孫既結在前，今與匈奴俱稱臣，義不可距。而康居驕黠，訖不肯拜使者。〔一〕都護吏至其國，坐之烏孫諸使下，王及貴人先飲食已，乃飲啗都護吏〔二〕，故為無所省以夸旁國。〔三〕以此度之，何故遣子入侍？其欲賈市為好，辭之詐也。匈奴百蠻大國，〔四〕今事漢甚備，聞康居不拜，且使單于有自下之意，〔五〕宜歸其侍子，絕勿復使，〔六〕以章漢家不通無禮之國。敦煌、酒泉小郡及南道八國，給使者往來人馬驢橐駝食，皆苦之。〔七〕空罷耗所過，送迎驕黠絕遠之國。〔八〕非至計也。」漢為其新通，重致遠人，〔九〕終羈縻而未絕。","sentenceOrder":170},
  {"id":"s_work_han_thu_111_171","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「訖，竟也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_111_172","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「飲音於禁反，啗音徒濫反。」","sentenceOrder":172},
  {"id":"s_work_han_thu_111_173","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「言故不省視漢使也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_111_174","chapterId":"ch_work_han_thu_111","textTraditional":"〔四〕　師古曰：「於百蠻之中，最大國也。」","sentenceOrder":174},
  {"id":"s_work_han_thu_111_175","chapterId":"ch_work_han_thu_111","textTraditional":"〔五〕　師古曰：「言單于見康居不事漢，以之為高，自以事漢為太卑，而欲改志也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_111_176","chapterId":"ch_work_han_thu_111","textTraditional":"〔六〕　師古曰：「不通使於其國也。」","sentenceOrder":176},
  {"id":"s_work_han_thu_111_177","chapterId":"ch_work_han_thu_111","textTraditional":"〔七〕　師古曰：「言二郡八國皆以此事為困苦。」","sentenceOrder":177},
  {"id":"s_work_han_thu_111_178","chapterId":"ch_work_han_thu_111","textTraditional":"〔八〕　師古曰：「所過，所經過之處。驕黠謂唐居使也。罷讀曰疲。耗音呼到反。」","sentenceOrder":178},
  {"id":"s_work_han_thu_111_179","chapterId":"ch_work_han_thu_111","textTraditional":"〔九〕　師古曰：「以此聲名為重也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_111_180","chapterId":"ch_work_han_thu_111","textTraditional":"其康居西北可二千里，有奄蔡國。控弦者十餘萬（大）〔人〕。與康居同俗。臨大澤，無崖，蓋北海云。","sentenceOrder":180},
  {"id":"s_work_han_thu_111_181","chapterId":"ch_work_han_thu_111","textTraditional":"康居有小王五：一曰蘇王，治蘇城，〔一〕去都護五千七百七十六里，去陽關八千二十五里；二曰附墨王，治附墨城，去都護五千七百六十七里，去陽關八千二十五里；三曰窳匿王，〔二〕治窳匿城，去都護五千二百六十六里，去陽關七千五百二十五里；四曰罽王，治罽城，去都護六千二百九十六里，去陽關八千五百五十五里；五曰奧鞬王，〔三〕治奧鞬城，去都護六千九百六里，去陽關八千三百五十五里。凡五王，屬康居。","sentenceOrder":181},
  {"id":"s_work_han_thu_111_182","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「音下戒反。」","sentenceOrder":182},
  {"id":"s_work_han_thu_111_183","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「窳音庾。」","sentenceOrder":183},
  {"id":"s_work_han_thu_111_184","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「奧音於六反。鞬音居言反。」","sentenceOrder":184},
  {"id":"s_work_han_thu_111_185","chapterId":"ch_work_han_thu_111","textTraditional":"大宛國，王治貴山城，去長安萬二千（二）〔五〕百五十里。戶六萬，口三十萬，勝兵六萬人。副王，輔國王各一人。東至都護治所四千三十一里，北至康居卑闐城千五百一十里，西南至大月氏六百九十里。北與康居、南與大月氏接，土地風氣物類民俗與大月氏、安息同。大宛左右以蒲陶為酒，富人藏酒至萬餘石，久者至數十歲不敗。俗耆酒，馬耆目宿。〔一〕","sentenceOrder":185},
  {"id":"s_work_han_thu_111_186","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「耆讀曰嗜。」","sentenceOrder":186},
  {"id":"s_work_han_thu_111_187","chapterId":"ch_work_han_thu_111","textTraditional":"宛別邑七十餘城，多善馬。馬汗血，言其先天馬子也。〔一〕","sentenceOrder":187},
  {"id":"s_work_han_thu_111_188","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　（師古）〔孟康〕曰：「言大宛國有高山，其上有馬不可得，因取五色母馬置其下與集，生駒，皆汗血，因號曰天馬子云。」","sentenceOrder":188},
  {"id":"s_work_han_thu_111_189","chapterId":"ch_work_han_thu_111","textTraditional":"張騫始為武帝言之，上遣使者持千金及金馬，以請宛善馬。宛王以漢絕遠，大兵不能至，愛其寶馬不肯與。漢使妄言，〔一〕宛遂攻殺漢使，取其財物。於是天子遣貳師將軍李廣利將兵前後十餘萬人伐宛，連四年。宛人斬其王毋寡首，獻馬三千匹，漢軍乃還，語在張騫傳。貳師既斬宛王，更立貴人素遇漢善者名昧蔡為宛王。〔二〕後歲餘，宛貴人以為昧蔡諂，使我國遇屠，〔三〕相與（兵）〔共〕殺昧蔡，立毋寡弟蟬封為王，遣子入侍，質於漢，漢因使使賂賜鎮撫之。又發（數）〔使〕十餘輩，抵宛西諸國〔四〕求（其）〔奇〕物，因風諭以（代）〔伐〕宛之威。〔五〕宛王蟬封與漢約，歲獻天馬二匹。漢使采蒲陶、目宿種歸。天子以天馬多，又外國使來眾，益種蒲陶、目宿離宮館旁，極望焉。〔六〕","sentenceOrder":189},
  {"id":"s_work_han_thu_111_190","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「謂詈辱宛王。」","sentenceOrder":190},
  {"id":"s_work_han_thu_111_191","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「昧音秣。蔡音千曷反。」","sentenceOrder":191},
  {"id":"s_work_han_thu_111_192","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「讇，古諂字。」","sentenceOrder":192},
  {"id":"s_work_han_thu_111_193","chapterId":"ch_work_han_thu_111","textTraditional":"〔四〕　師古曰：「抵，至也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_111_194","chapterId":"ch_work_han_thu_111","textTraditional":"〔五〕　師古曰：「風讀曰諷。」","sentenceOrder":194},
  {"id":"s_work_han_thu_111_195","chapterId":"ch_work_han_thu_111","textTraditional":"〔六〕　師古曰：「今北道諸州舊安定、北地之境往往有目宿者，皆漢時所種也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_111_196","chapterId":"ch_work_han_thu_111","textTraditional":"自宛以西至安息國，雖頗異言，然大同，自相曉知也。其人皆深目，多須敘。善賈市，爭分銖。貴女子；女子所言，丈夫乃決正。其地（皆）〔無〕絲漆，不知鑄鐵器。及漢使亡卒降，教鑄作它兵器。〔一〕得漢黃白金，輒以為器，不用為幣。","sentenceOrder":196},
  {"id":"s_work_han_thu_111_197","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「漢使至其國及有亡卒降其國者，皆教之也。」","sentenceOrder":197},
  {"id":"s_work_han_thu_111_198","chapterId":"ch_work_han_thu_111","textTraditional":"自烏孫以西至安息，近匈奴。匈奴嘗困月氏，〔一〕故匈奴使持單于一信到國，國傳送食，〔二〕不敢留苦。〔三〕及至漢使，非出幣物不得食，不市畜不得騎，所以然者，以遠漢，而漢多財物，〔四〕故必市乃得所欲。及呼韓邪單于朝漢，後咸尊漢矣。","sentenceOrder":198},
  {"id":"s_work_han_thu_111_199","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「困，苦也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_111_200","chapterId":"ch_work_han_thu_111","textTraditional":"〔二〕　師古曰：「言畏之甚也。食讀曰飤。」","sentenceOrder":200},
  {"id":"s_work_han_thu_111_201","chapterId":"ch_work_han_thu_111","textTraditional":"〔三〕　師古曰：「不敢留連及困苦之也。」","sentenceOrder":201},
  {"id":"s_work_han_thu_111_202","chapterId":"ch_work_han_thu_111","textTraditional":"〔四〕　師古曰：「遠音于萬反。」","sentenceOrder":202},
  {"id":"s_work_han_thu_111_203","chapterId":"ch_work_han_thu_111","textTraditional":"桃槐國，王去長安萬一千八十里。〔一〕戶七百，口五千，勝兵千人。","sentenceOrder":203},
  {"id":"s_work_han_thu_111_204","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「槐音回。」","sentenceOrder":204},
  {"id":"s_work_han_thu_111_205","chapterId":"ch_work_han_thu_111","textTraditional":"休循國，王治鳥飛谷，在蔥嶺西，去長安萬二百一十里。戶三百五十八，口千三十，勝兵四百八十人。東至都護治所三千一百二十一里，至捐毒衍敦谷二百六十里，西北至大宛國九百二十里，西至大月氏千六百一十里。民俗衣服類烏孫，因畜隨水草，本故塞種也。","sentenceOrder":205},
  {"id":"s_work_han_thu_111_206","chapterId":"ch_work_han_thu_111","textTraditional":"捐毒國，王治衍敦谷，去長安九千八百六十里。戶三百八十，口千一百，勝兵五百人。東至都護治所二千八百六十一里。至疏勒。南與蔥領屬，〔一〕無人民。西上蔥領，則休循也。西北至大宛千三十里，北與烏孫接。衣服類烏孫，隨水草，依蔥領，本塞種也。","sentenceOrder":206},
  {"id":"s_work_han_thu_111_207","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「屬，聯也，音之欲反。」","sentenceOrder":207},
  {"id":"s_work_han_thu_111_208","chapterId":"ch_work_han_thu_111","textTraditional":"莎車國，王治莎車城，去長安九千九百五十里。戶二千三百三十九，口萬六千三百七十三，勝兵三千四十九人。輔國侯、左右將、左右騎君、備西夜君各一人，都尉二人，譯長四人。東北至都護治所四千七百四十六里，西至疏勒五百六十里，西南至蒲犁七百四十里。有鐵山，出青玉。","sentenceOrder":208},
  {"id":"s_work_han_thu_111_209","chapterId":"ch_work_han_thu_111","textTraditional":"宣帝時，烏孫公主小子萬年，莎車王愛之。莎車王無子死，死時萬年在漢。莎車國人計欲自託於漢，又欲得烏孫心，即上書請萬年為莎車王。漢許之，遣使者奚充國送萬年。萬年初立，暴惡，國人不說。〔一〕莎車王弟呼屠徵殺萬年，并殺漢使者，自立為王，約諸國背漢。會衛候馮奉世使送大宛客，即以便宜發諸國兵擊殺之，更立它昆弟子為莎車王。還，拜奉世為光祿大夫。是歲，元康元年也。","sentenceOrder":209},
  {"id":"s_work_han_thu_111_210","chapterId":"ch_work_han_thu_111","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":210},
  {"id":"s_work_han_thu_111_211","chapterId":"ch_work_han_thu_111","textTraditional":"疏勒國，王治疏勒城，去長安九千三百五十里。戶千五百一十，口萬八千六百四十七，勝兵二千人。疏勒侯、擊胡侯、輔國侯、都尉、左右將、左右騎君、左右譯長各一人。東至都護治所二千二百一十里，南至莎車五百六十里。有市列，西當大月氏、大宛、康居道也。","sentenceOrder":211},
  {"id":"s_work_han_thu_111_212","chapterId":"ch_work_han_thu_111","textTraditional":"尉頭國，王治尉頭谷，去長安八千六百五十里。戶三百，口二千三百，勝兵八百人。左右都尉各一人，左右騎君各一人。東至都護治所千四百一十一里，南與疏勒接，山道不通，西至捐毒千三百一十四里，徑道馬行二日。田畜隨水草，衣服類烏孫。","sentenceOrder":212},
  {"id":"s_work_han_thu_111_213","chapterId":"ch_work_han_thu_111","textTraditional":"校勘記","sentenceOrder":213},
  {"id":"s_work_han_thu_111_214","chapterId":"ch_work_han_thu_111","textTraditional":"三八七一頁一一行　（陽）〔二〕關皆在敦煌西界。　景祐、殿本都作「二」，此誤。","sentenceOrder":214},
  {"id":"s_work_han_thu_111_215","chapterId":"ch_work_han_thu_111","textTraditional":"三八七二頁　五行　北道西踰蔥嶺則出大宛、康居、奄蔡焉（耆）。　景祐本無「耆」字。　王念孫說景祐本是，「焉」字絕句，「耆」字後人妄加之。","sentenceOrder":215},
  {"id":"s_work_han_thu_111_216","chapterId":"ch_work_han_thu_111","textTraditional":"三八七七頁一０行　簿音（簿）〔步〕戶反。　景祐、殿本都作「步」，此誤。","sentenceOrder":216},
  {"id":"s_work_han_thu_111_217","chapterId":"ch_work_han_thu_111","textTraditional":"三八七八頁一二行　丞相〔將軍〕率百官送至橫門外，　景祐、殿本都有「將軍」二字。","sentenceOrder":217},
  {"id":"s_work_han_thu_111_218","chapterId":"ch_work_han_thu_111","textTraditional":"三八七八頁一三行　願漢遣（二）〔一〕將屯田積穀，　景祐、殿本都作「一」。王先謙說作「一」是。","sentenceOrder":218},
  {"id":"s_work_han_thu_111_219","chapterId":"ch_work_han_thu_111","textTraditional":"三八八二頁　七行　去都護治所五千二（百）〔十〕里。　景祐、殿本都作「十」。","sentenceOrder":219},
  {"id":"s_work_han_thu_111_220","chapterId":"ch_work_han_thu_111","textTraditional":"三八八二頁一０行　細步，〔言其〕能蹀足，　景祐、殿本都有「言其」二字。","sentenceOrder":220},
  {"id":"s_work_han_thu_111_221","chapterId":"ch_work_han_thu_111","textTraditional":"三八八三頁　二行　蒲犁（反）〔及〕依耐、　景祐、殿本都作「及」，此誤。","sentenceOrder":221},
  {"id":"s_work_han_thu_111_222","chapterId":"ch_work_han_thu_111","textTraditional":"三八八五頁一三行　皆銷（洽）〔治〕石汁，　景祐、殿本都作「治」。王先謙說疑是「冶」字。","sentenceOrder":222},
  {"id":"s_work_han_thu_111_223","chapterId":"ch_work_han_thu_111","textTraditional":"三八八九頁　八行　（者）兩角〔者〕或為辟邪。　景祐、殿本都作「兩角者」，此誤倒。","sentenceOrder":223},
  {"id":"s_work_han_thu_111_224","chapterId":"ch_work_han_thu_111","textTraditional":"三八九三頁一五行　控弦者十餘萬（大）〔人〕。　殿本作「人」，景祐本作「大」。王先謙說作「人」是。","sentenceOrder":224},
  {"id":"s_work_han_thu_111_225","chapterId":"ch_work_han_thu_111","textTraditional":"三八九四頁　九行　去長安萬二千（二）〔五〕百五十里。　景祐、殿本都作「五」。","sentenceOrder":225},
  {"id":"s_work_han_thu_111_226","chapterId":"ch_work_han_thu_111","textTraditional":"三八九五頁　一行　（師古）〔孟康〕曰：　景祐、殿本都作「孟康」。","sentenceOrder":226},
  {"id":"s_work_han_thu_111_227","chapterId":"ch_work_han_thu_111","textTraditional":"三八九五頁　七行　相與（兵）〔共〕殺昧蔡，　景祐、殿本都作「共」，此誤。","sentenceOrder":227},
  {"id":"s_work_han_thu_111_228","chapterId":"ch_work_han_thu_111","textTraditional":"三八九五頁　八行　又發（數）〔使〕十餘輩，抵宛西諸國〔四〕求（其）〔奇〕物，因風諭以（代）〔伐〕宛之威。　景祐、殿本「數」都作「使」，「其」都作「奇」，「代」都作「伐」。","sentenceOrder":228},
  {"id":"s_work_han_thu_111_229","chapterId":"ch_work_han_thu_111","textTraditional":"三八九六頁　二行　其地（皆）〔無〕絲漆，　王念孫說「皆」當為「無」，通典正作「無絲漆」。按史記大宛傳作「皆無絲漆」。","sentenceOrder":229},
  {"id":"s_work_han_thu_112_1","chapterId":"ch_work_han_thu_112","textTraditional":"烏孫國，大昆彌治赤谷城，〔一〕去長安八千九百里。戶十二萬，口六十三萬，勝兵十八萬八千八百人。相，大祿，左右大將二人，侯三人，大將、都尉各一人，大監二人，大吏一人，舍中大吏二人，騎君一人。東至都護治所千七百二十一里，西至康居蕃內地五千里。地莽平。多雨，寒。山多松樠。〔二〕不田作種樹，〔三〕隨畜逐水草，與匈奴同俗。國多馬，富人至四五千匹。民剛惡，貪（狠）〔狼〕無信，多寇盜，最為彊國。故服匈奴，〔四〕後盛大，取羈屬，不肯往朝會。〔五〕東與匈奴、西北與康居、西與大宛、南與城郭諸國相接。本塞地也，大月氏西破走塞王，塞王南越縣度，大月氏居其地。後烏孫昆莫擊破大月氏，大月氏徙西臣大夏，而烏孫昆莫居之，故烏孫民有塞種、大月氏種云。","sentenceOrder":1},
  {"id":"s_work_han_thu_112_2","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「烏孫於西域諸戎其形最異。今之胡人青眼、赤須，狀類彌猴者，本其種也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_112_3","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　師古曰：「莽平謂有草莽而平坦也。一曰莽莽平野之貌。樠，木名，其心似松，音武元反。」","sentenceOrder":3},
  {"id":"s_work_han_thu_112_4","chapterId":"ch_work_han_thu_112","textTraditional":"〔三〕　師古曰：「樹，植也。」","sentenceOrder":4},
  {"id":"s_work_han_thu_112_5","chapterId":"ch_work_han_thu_112","textTraditional":"〔四〕　師古曰：「故謂舊時也。服，屬於匈奴也。」","sentenceOrder":5},
  {"id":"s_work_han_thu_112_6","chapterId":"ch_work_han_thu_112","textTraditional":"〔五〕　師古曰：「言纔羈縻屬之而已。」","sentenceOrder":6},
  {"id":"s_work_han_thu_112_7","chapterId":"ch_work_han_thu_112","textTraditional":"始張騫言烏孫本與大月氏共在敦煌間，今烏孫雖彊大，可厚賂招，令東居故地，妻以公主，與為昆弟，以制匈奴。語在張騫傳。武帝即位，令騫齎金幣往。昆莫見騫如單于禮，〔一〕騫大慚，謂曰：「天子致賜，王不拜，則還賜。」〔二〕昆莫起拜，其它如故。","sentenceOrder":7},
  {"id":"s_work_han_thu_112_8","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「昆莫自比於單于。」","sentenceOrder":8},
  {"id":"s_work_han_thu_112_9","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　師古曰：「還賜，謂將賜物還歸漢也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_112_10","chapterId":"ch_work_han_thu_112","textTraditional":"初，昆莫有十餘子，中子大祿彊，善將，〔一〕將眾萬餘騎別居。大祿兄太子，太子有子曰岑陬。〔二〕太子蚤死，〔三〕謂昆莫曰：「必以岑陬為太子。」昆莫哀許之。大祿怒，乃收其昆弟，將眾畔，謀攻岑陬。昆莫與岑陬萬餘騎，令別居，昆莫亦自有萬餘騎以自備。國分為三，大總羈屬昆莫。騫既致賜，諭指曰：「烏孫能東居故地，則漢遣公主為夫人，結為昆弟，共距匈奴，不足破也。」烏孫遠漢，未知其大小，〔四〕又近匈奴，服屬日久，其大臣皆不欲徙。昆莫年老國分，不能專制，乃發使送騫，因獻馬數十匹報謝。其使見漢人眾富厚，歸其國，其國後乃益重漢。","sentenceOrder":10},
  {"id":"s_work_han_thu_112_11","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「言其材力優彊，能為將。」","sentenceOrder":11},
  {"id":"s_work_han_thu_112_12","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　師古曰：「岑音仕林反。陬音子侯反。」","sentenceOrder":12},
  {"id":"s_work_han_thu_112_13","chapterId":"ch_work_han_thu_112","textTraditional":"〔三〕　師古曰：「蚤，古早字。」","sentenceOrder":13},
  {"id":"s_work_han_thu_112_14","chapterId":"ch_work_han_thu_112","textTraditional":"〔四〕　師古曰：「遠音于萬反。」","sentenceOrder":14},
  {"id":"s_work_han_thu_112_15","chapterId":"ch_work_han_thu_112","textTraditional":"匈奴聞其與漢通，怒欲擊之。又漢使烏孫，乃出其南，抵大宛、月氏，相屬不絕。〔一〕烏孫於是恐，使使獻馬，願得尚漢公主，為昆弟。天子問群臣，議許，曰：「必先內聘，然後遣女。」烏孫以馬千匹聘。〔二〕漢元封中，遣江都王建女細君為公主，以妻焉。賜乘輿服御物，為備官屬宦官侍御數百人，贈送甚盛。烏孫昆莫以為右夫人。匈奴亦遣女妻昆莫，昆莫以為左夫人。","sentenceOrder":15},
  {"id":"s_work_han_thu_112_16","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「抵，至也。屬音之欲反。」","sentenceOrder":16},
  {"id":"s_work_han_thu_112_17","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　師古曰：「入聘財。」","sentenceOrder":17},
  {"id":"s_work_han_thu_112_18","chapterId":"ch_work_han_thu_112","textTraditional":"公主至其國，自治宮室居，歲時一再與昆莫會，置酒飲食，以幣帛賜王左右貴人。昆莫年老，語言不通，公主悲愁，自為作歌曰：「吾家嫁我兮天一方，遠託異國兮烏孫王。穹廬為室兮旃為牆，以肉為食兮酪為漿。〔一〕居常土思兮心內傷，〔二〕願為黃鵠兮歸故鄉。」〔三〕天子聞而憐之，間歲遣使者持帷帳錦繡給遺焉。〔四〕","sentenceOrder":18},
  {"id":"s_work_han_thu_112_19","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「食謂飯，音飤。」","sentenceOrder":19},
  {"id":"s_work_han_thu_112_20","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　師古曰：「土思，謂憂思而懷本土。」","sentenceOrder":20},
  {"id":"s_work_han_thu_112_21","chapterId":"ch_work_han_thu_112","textTraditional":"〔三〕　師古曰：「鵠音下督反。」","sentenceOrder":21},
  {"id":"s_work_han_thu_112_22","chapterId":"ch_work_han_thu_112","textTraditional":"〔四〕　師古曰：「間歲者，謂每隔一歲而往也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_112_23","chapterId":"ch_work_han_thu_112","textTraditional":"昆莫年老，欲使其孫岑陬尚公主。公主不聽，上書言狀，天子報曰：「從其國俗，欲與烏孫共滅胡。」岑陬遂妻公主。昆莫死，岑陬代立。岑陬者，官號也，名軍須靡。昆莫，王號也，名獵驕靡。後書「昆彌」云。〔一〕岑陬尚江都公主，生一女少夫。〔二〕公主死，漢復以楚王戊之孫解憂為公主，妻岑陬。岑陬胡婦子泥靡尚小，岑陬且死，以國與季父大祿子翁歸靡，曰：「泥靡大，以國歸之。」","sentenceOrder":23},
  {"id":"s_work_han_thu_112_24","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「昆莫本是王號，而其人名獵驕靡，故書云昆彌。昆取昆莫，彌取驕靡。彌、靡音有輕重耳，蓋本一也。後遂以昆彌為其王號也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_112_25","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　師古曰：「名少夫。」","sentenceOrder":25},
  {"id":"s_work_han_thu_112_26","chapterId":"ch_work_han_thu_112","textTraditional":"翁歸靡既立，號肥王，復尚楚主解憂，生三男兩女：長男曰元貴靡；次曰萬年，為莎車王；次曰大樂，為左大將；長女弟史為龜茲王絳賓妻；小女素光為若呼翕侯妻。〔一〕","sentenceOrder":26},
  {"id":"s_work_han_thu_112_27","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「弟史、素光皆女名。」","sentenceOrder":27},
  {"id":"s_work_han_thu_112_28","chapterId":"ch_work_han_thu_112","textTraditional":"昭帝時，公主上書，言「匈奴發騎田車師，車師與匈奴為一，共侵烏孫，唯天子幸救之！」漢養士馬，議欲擊匈奴。會昭帝崩，宣帝初即位，公主及昆彌皆遣使上書，言「匈奴復連發大兵侵擊烏孫，取車延、惡師地，收人民去，使使謂烏孫趣持公主來，〔一〕欲隔絕漢。昆彌願發國半精兵，自給人馬五萬騎，盡力擊匈奴。唯天子出兵以救公主、昆彌。」漢兵大發十五萬騎，五將軍分道並出。語在匈奴傳。遣校尉常惠使持節護烏孫兵，昆彌自將翕侯以下五萬騎從西方入，至右谷蠡王庭，獲單于父行及嫂、居次、名王、犁汙都尉、千長、騎將以下四萬級，馬牛羊驢橐駝七十餘萬頭，烏孫皆自取所虜獲。還，封惠為長羅侯。是歲，本始三年也。漢遣惠持金幣賜烏孫貴人有功者。","sentenceOrder":28},
  {"id":"s_work_han_thu_112_29","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「趣讀曰促。」","sentenceOrder":29},
  {"id":"s_work_han_thu_112_30","chapterId":"ch_work_han_thu_112","textTraditional":"元康二年，烏孫昆彌因惠上書：「願以漢外孫元貴靡為嗣，得令復尚漢公主，結婚重親，畔絕匈奴，願聘馬驘各千匹。」詔下公卿議，大鴻臚蕭望之以為「烏孫絕域，變故難保，不可許。」上美烏孫新立大功，又重絕故業，〔一〕遣使者至烏孫，先迎取聘。昆彌及太子、左右大將、都尉皆遣使，凡三百餘人，入漢迎取少主。上乃以烏孫主解憂弟子相夫為公主，置官屬侍御百餘人，舍上林中，學烏孫言。〔二〕天子自臨平樂觀，會匈奴使者、外國君長大角抵，設樂而遣之。使長（盧）〔羅〕侯光祿大夫惠為副，凡持節者四人，送少主至敦煌。未出塞，聞烏孫昆彌翁歸靡死，烏孫貴人共從本約，立岑陬子泥靡代為昆彌，號狂王。惠上書：「願留少主敦煌，惠馳至烏孫責讓不立元貴靡為昆彌，還迎少主。」事下公卿，望之復以為「烏孫持兩端，難約結。前公主在烏孫四十餘年，恩愛不親密，邊竟未得安，〔三〕此已事之驗也。今少主以元貴靡不立而還，信無負於夷狄，中國之福也。少主不止，繇役將興，其原起此。」天子從之，徵還少主。","sentenceOrder":30},
  {"id":"s_work_han_thu_112_31","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「重，難也。故業，謂先與烏孫婚親也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_112_32","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　師古曰：「舍，止也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_112_33","chapterId":"ch_work_han_thu_112","textTraditional":"〔三〕　師古曰：「竟讀曰境。」","sentenceOrder":33},
  {"id":"s_work_han_thu_112_34","chapterId":"ch_work_han_thu_112","textTraditional":"狂王復尚楚主解憂，生一男鴟靡，不與主和，又暴惡失眾。漢使衛司馬魏和意、副候任昌送侍子，公主言狂王為烏孫所患苦，易誅也。遂謀置酒會，罷，使士拔劍擊之。劍旁下，〔一〕狂王傷，上馬馳去。其子細沈瘦〔二〕會兵圍和意、昌及公主於赤谷城。數月，都護鄭吉發諸國兵救之，乃解去。漢遣中郎將張遵持醫藥治狂王，賜金二十斤，采繒。因收和意、昌係瑣，從尉犁檻車至長安，斬之。車騎將軍長史張翁留驗公主與使者謀殺狂王狀，主不服，叩頭謝，張翁捽主頭罵詈。〔三〕主上書，翁還，坐死。副使季都別將醫養視狂王，狂王從十餘騎送之。都還，坐知狂王當誅，見便不發，下蠶室。","sentenceOrder":34},
  {"id":"s_work_han_thu_112_35","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「不正下（之）。」","sentenceOrder":35},
  {"id":"s_work_han_thu_112_36","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　師古曰：「瘦音搜。」","sentenceOrder":36},
  {"id":"s_work_han_thu_112_37","chapterId":"ch_work_han_thu_112","textTraditional":"〔三〕　師古曰：「捽，持其頭，音材兀反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_112_38","chapterId":"ch_work_han_thu_112","textTraditional":"初，肥王翁歸靡胡婦子烏就屠，狂王傷時驚，與諸翕侯俱去，居北山中，揚言母家匈奴兵來，故眾歸之。後逐襲殺狂王，自立為昆彌。漢遣破羌將軍辛武賢將兵萬五千人至敦煌，遣使者案行表，穿卑鞮侯井以西，〔一〕欲通渠轉穀，積居廬倉以討之。","sentenceOrder":38},
  {"id":"s_work_han_thu_112_39","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　孟康曰：「大井六通渠也，下泉流湧出，在白龍堆東土山下。」","sentenceOrder":39},
  {"id":"s_work_han_thu_112_40","chapterId":"ch_work_han_thu_112","textTraditional":"初，楚主侍者馮嫽〔一〕能史書，習事，嘗持漢節為公主使，行賞賜於城郭諸國，敬信之，號曰馮夫人。為烏孫右大將妻，右大將與烏就屠相愛，都護鄭吉使馮夫人說烏就屠，以漢兵方出，必見滅，不如降。烏就屠恐，曰：「願得小號。」宣帝徵馮夫人，自問狀。遣謁者竺次、期門甘廷壽為副，送馮夫人。馮夫人錦車持節，〔二〕詔（焉）烏就屠詣長羅侯赤谷城，立元貴靡為大昆彌，烏就屠為小昆彌，皆賜印綬。破羌將軍不出塞還。後烏就屠不盡歸諸翕侯民眾，漢復遣長羅侯惠將三校屯赤谷，因為分別其人民地界，大昆彌戶六萬餘，小昆彌戶四萬餘，然眾心皆附小昆彌。","sentenceOrder":40},
  {"id":"s_work_han_thu_112_41","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「音了。嫽者，慧也，故以為名。」","sentenceOrder":41},
  {"id":"s_work_han_thu_112_42","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　服虔曰：「錦車，以錦衣車也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_112_43","chapterId":"ch_work_han_thu_112","textTraditional":"元貴靡、鴟靡皆病死，公主上書言年老土思，願得歸骸骨，葬漢地。天子閔而迎之，公主與烏孫男女三人俱來至京師。是歲，甘露三年也。時年且七十，賜以公主田宅奴婢，奉養甚厚，朝見儀比公主。後二歲卒，三孫因留守墳墓云。","sentenceOrder":43},
  {"id":"s_work_han_thu_112_44","chapterId":"ch_work_han_thu_112","textTraditional":"元貴靡子星靡代為大昆彌，弱，〔一〕馮夫人上書，願使烏孫鎮撫星（彌）〔靡〕。漢遣之，卒百人送（烏孫）焉。都護韓宣奏，烏孫大吏、大祿、大監皆可以賜金印紫綬，以尊輔大昆彌，漢許之。後都護韓宣復奏，星靡怯弱，可免，更以季父左大將樂代為昆彌，漢不許。後段會宗為都護，招還亡畔，安定之。〔二〕","sentenceOrder":44},
  {"id":"s_work_han_thu_112_45","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「言其尚幼少。」","sentenceOrder":45},
  {"id":"s_work_han_thu_112_46","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　師古曰：「有人眾亡畔者，皆招而還之，故安定也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_112_47","chapterId":"ch_work_han_thu_112","textTraditional":"星靡死，子雌栗靡代。小昆彌烏就屠死，子拊離代立，〔一〕為弟日貳所殺。漢遣使者立拊離子安日為小昆彌。日貳亡，阻康居。漢徙己校屯姑墨，〔二〕欲候便討焉。安日使貴人姑莫匿等三人詐亡從日貳，刺殺之。〔三〕都護廉褒賜姑莫匿等金人二十斤，繒三百匹。","sentenceOrder":47},
  {"id":"s_work_han_thu_112_48","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「拊讀與撫同。」","sentenceOrder":48},
  {"id":"s_work_han_thu_112_49","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　師古曰：「有戊己兩校兵，此直徙己校也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_112_50","chapterId":"ch_work_han_thu_112","textTraditional":"〔三〕　師古曰：「詐畔亡而投之，因得以刺殺。」","sentenceOrder":50},
  {"id":"s_work_han_thu_112_51","chapterId":"ch_work_han_thu_112","textTraditional":"後安日為降民所殺，漢立其弟末振將代。時大昆彌雌栗靡健，翕侯皆畏服之，告民牧馬畜無使入牧，〔一〕國中大安和翁歸靡時〔二〕。小昆（靡）〔彌〕末振將恐為所并，使貴人烏日領詐降刺殺雌栗靡。漢欲以兵討之而未能，遣中郎將段會宗持金幣與都護圖方略，立雌栗靡季父公主孫伊秩靡為大昆彌。漢沒入小昆彌侍子在京師者。久之，大昆彌翕侯難栖殺末振將，末振將兄安日子安犁莠代為小昆彌。〔三〕漢恨不自（責）誅末振將，復使段會宗即斬其太子番丘。〔四〕還，賜爵關內侯。是歲，元延二年也。","sentenceOrder":51},
  {"id":"s_work_han_thu_112_52","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「勿入昆彌牧中，恐其相擾也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_112_53","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　師古曰：「勝於翁歸靡時也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_112_54","chapterId":"ch_work_han_thu_112","textTraditional":"〔三〕　師古曰：「末振將之兄名安日，安日之子名安犁靡。」","sentenceOrder":54},
  {"id":"s_work_han_thu_112_55","chapterId":"ch_work_han_thu_112","textTraditional":"〔四〕　師古曰：「番音盤。」","sentenceOrder":55},
  {"id":"s_work_han_thu_112_56","chapterId":"ch_work_han_thu_112","textTraditional":"會宗以翕侯難栖殺末振將，雖不指為漢，合於討賊，奏以為堅守都尉。責大祿、大吏、大監以雌栗靡見殺狀，奪金印紫綬，更與銅墨云。末振將弟卑爰疐〔一〕本共謀殺大昆彌，將眾八萬餘口北附康居，謀欲藉兵〔二〕兼并兩昆彌。兩昆彌畏之，親倚都護。〔三〕","sentenceOrder":56},
  {"id":"s_work_han_thu_112_57","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「疐音竹二反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_112_58","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　師古曰：「藉，借也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_112_59","chapterId":"ch_work_han_thu_112","textTraditional":"〔三〕　師古曰：「倚，依附也，音於綺反。」","sentenceOrder":59},
  {"id":"s_work_han_thu_112_60","chapterId":"ch_work_han_thu_112","textTraditional":"哀帝元壽二年，大昆彌伊秩靡與單于並入朝，漢以為榮。至元始中，卑爰疐殺烏日領以自效，漢封為歸義侯。兩昆彌皆弱，卑爰疐侵陵，都護孫建襲殺之。自烏孫分立兩昆彌後，漢用憂勞，且無寧歲。〔一〕","sentenceOrder":60},
  {"id":"s_work_han_thu_112_61","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「言或鎮撫，或威制之，故多事也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_112_62","chapterId":"ch_work_han_thu_112","textTraditional":"姑墨國，王治南城，去長安八千一百五十里。戶三千五百，口二萬四千五百，勝兵四千五百人。姑墨侯、輔國侯、都尉、左右將、左右騎君各一人，譯長二人。東至都護治所（一）〔二〕千二十一里，南至（於）〔于〕闐馬行十五日，北與烏孫接。出銅、鐵、雌黃。東通龜茲六百七十里。王莽時，姑墨王丞殺溫宿王，并其國。","sentenceOrder":62},
  {"id":"s_work_han_thu_112_63","chapterId":"ch_work_han_thu_112","textTraditional":"溫宿國，王治溫宿城，〔一〕去長安八千三百五十里。戶二千二百，口八千四百，勝兵千五百人。輔國侯、左右將、左右都尉、左右騎君、譯長各二人。東至都護治所二千三百八十里，西至尉頭三百里，北至烏孫赤谷六百一十里。土地物類所有與鄯善諸國同。東通姑墨二百七十里。","sentenceOrder":63},
  {"id":"s_work_han_thu_112_64","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「今雍州醴泉縣北有山名溫宿嶺者，本因漢時得溫宿國人令居此地田牧，因以為名。」","sentenceOrder":64},
  {"id":"s_work_han_thu_112_65","chapterId":"ch_work_han_thu_112","textTraditional":"龜茲國，王治延城，去長安七千四百八十里。戶六千九百七十，口八萬一千三百一十七，勝兵二萬一千七十六人。大都尉丞、輔國侯、安國侯、擊胡侯、卻胡都尉、擊車師都尉、左右將、左右都尉、左右騎君、左右力輔君各一人，東西南北部千長各二人，卻胡君三人，譯長四人。南與精絕、東南與且末、西南與杅彌、北與烏孫、西與姑墨接。〔一〕能鑄冶，有鉛。東至都護治所烏壘城三百五十里。","sentenceOrder":65},
  {"id":"s_work_han_thu_112_66","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「杅音烏。」","sentenceOrder":66},
  {"id":"s_work_han_thu_112_67","chapterId":"ch_work_han_thu_112","textTraditional":"烏壘，戶百一十，口千二百，勝兵三百人。城都尉、譯長各一人。與都護同治。其南三百三十里至渠犁。","sentenceOrder":67},
  {"id":"s_work_han_thu_112_68","chapterId":"ch_work_han_thu_112","textTraditional":"渠犁，城都尉一人，戶百三十，口千四百八十，勝兵百五十人。東北與尉犁、東南與且末、南與精絕接。西有河，至龜茲五百八十里。","sentenceOrder":68},
  {"id":"s_work_han_thu_112_69","chapterId":"ch_work_han_thu_112","textTraditional":"自武帝初通西域，置校尉，屯田渠犁。是時軍旅連出，師行三十二年，海內虛耗。征和中，貳師將軍李廣利以軍降匈奴。上既悔遠征伐，而搜粟都尉桑弘羊與丞相御史奏言：「故輪臺（以）東捷枝、渠犁皆故國，地廣，饒水草，有溉田五千頃以上，處溫和，田美，可益通溝渠，種五穀，與中國同時孰。其旁國少錐刀，貴黃金采繒，可以易穀食，宜給足不（可）乏。〔一〕臣愚以為可遣屯田卒詣故輪臺以東，置校尉三人分護，各舉圖地形，通利溝渠，務使以時益種五穀。〔二〕張掖、酒泉遣騎假司馬為斥候，屬校尉，事有便宜，因騎置以聞。〔三〕田一歲，有積穀，募民壯健有累重敢徙者詣田所，〔四〕就畜積為本業，〔五〕益墾溉田，稍築列亭，連城而西，以威西國，輔烏孫，為便。臣謹遣徵事臣昌分部行邊，〔六〕嚴敕太守都尉明｛逢火｝火，選士馬，謹斥候，蓄茭草。願陛下遣使使西國，以安其意。臣昧死請。」","sentenceOrder":69},
  {"id":"s_work_han_thu_112_70","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「言以錐刀及黃金綵繒與此旁國易穀食，可以給田卒，不憂乏糧也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_112_71","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　師古曰：「益，多也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_112_72","chapterId":"ch_work_han_thu_112","textTraditional":"〔三〕　師古曰：「騎置即今之驛馬也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_112_73","chapterId":"ch_work_han_thu_112","textTraditional":"〔四〕　師古曰：「累重謂妻子家屬也。累音力瑞反。重音直用反。」","sentenceOrder":73},
  {"id":"s_work_han_thu_112_74","chapterId":"ch_work_han_thu_112","textTraditional":"〔五〕　師古曰：「畜讀曰蓄。」","sentenceOrder":74},
  {"id":"s_work_han_thu_112_75","chapterId":"ch_work_han_thu_112","textTraditional":"〔六〕　師古曰：「分音扶問反。行音下更反。」","sentenceOrder":75},
  {"id":"s_work_han_thu_112_76","chapterId":"ch_work_han_thu_112","textTraditional":"上乃下詔，深陳既往之悔，曰：「前有司奏，欲益民賦三十助邊用，〔一〕是重困老弱孤獨也。〔二〕而今又請遣卒田輪臺。輪臺西於車師千餘里，前開陵侯擊車師時，〔三〕危須、尉犁、樓蘭六國子弟在京師者皆先歸，發畜食迎漢軍，〔四〕又自發兵，凡數萬人，王各自將，共圍車師，降其王。諸國兵便罷，力不能復至道上食漢軍。〔五〕漢軍破城，食至多，然士自載不足以竟師，〔六〕彊者盡食畜產，羸者道死數千人。朕發酒泉驢橐駝負食，出玉門迎軍。吏卒起張掖，不甚遠，然尚廝留甚眾。〔七〕曩者，朕之不明，以軍候弘上書言『匈奴縛馬前後足，置城下，馳言「秦人，我匄若馬」』，〔八〕又漢使者久留不還，故興（師）遣貳師將軍，〔九〕欲以為使者威重也。古者卿大夫與謀，〔一０〕參以蓍龜，不吉不行。〔一一〕乃者以縛馬書遍視丞相御史二千石諸大夫郎為文學者，〔一二〕乃至郡屬國都尉成忠、趙破奴等，皆以『虜自縛其馬，不祥甚哉！』或以為『欲以見彊，〔一三〕夫不足者視人有餘。』〔一四〕易之，卦得大過，爻在九五，〔一五〕匈奴困敗。公車方士、太史治星望氣，及太卜龜蓍，皆以為吉，匈奴必破，時不可再得也。〔一六〕又曰『北伐行將，於釜山必克。』〔一七〕卦諸將，貳師最吉。〔一八〕故朕親發貳師下釜山，詔之必毋深入。今計謀卦兆皆反繆。〔一九〕重合侯（毋）〔得〕虜侯者，言『聞漢軍當來，匈奴使巫埋羊牛所出諸道及水上以詛軍。〔二０〕單于遺天子馬裘，常使巫祝之。縛馬者，詛軍事也。』又卜『漢軍一將不吉』。匈奴常言『漢極大，然不能飢渴〔二一〕，失一狼，走千羊。』乃者貳師敗，軍士死略離散，〔二二〕悲痛常在朕心。今請遠田輪臺，欲起亭隧，〔二三〕是擾勞天下，非所以優民也。今朕不忍聞。大鴻臚等又議，欲募囚徒送匈奴使者，明封侯之賞以報忿，五伯所弗能為也。〔二四〕且匈奴得漢降者，常提掖搜索，問以所聞。〔二五〕今邊塞未正，闌出不禁，障候長吏使卒獵獸，以皮肉為利，卒苦而烽火乏，失亦上集不得，〔二六〕後降者來，若捕生口虜，乃知之。〔二七〕當今務在禁苛暴，止擅賦，力本農，脩馬復令，〔二八〕以補缺，毋乏武備而已。郡國二千石各上進畜馬方略補邊狀，與計對。」〔二九〕由是不復出軍。而封丞相車千秋為富民侯，以明休息，思富養民也。","sentenceOrder":76},
  {"id":"s_work_han_thu_112_77","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「三十者，每口轉增三十錢也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_112_78","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　師古曰：「重音直用反。」","sentenceOrder":78},
  {"id":"s_work_han_thu_112_79","chapterId":"ch_work_han_thu_112","textTraditional":"〔三〕　晉灼曰：「開陵侯，匈奴介和王來降者。」","sentenceOrder":79},
  {"id":"s_work_han_thu_112_80","chapterId":"ch_work_han_thu_112","textTraditional":"〔四〕　師古日：「畜謂馬牛羊等也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_112_81","chapterId":"ch_work_han_thu_112","textTraditional":"〔五〕　師古曰：「食讀曰飤。」","sentenceOrder":81},
  {"id":"s_work_han_thu_112_82","chapterId":"ch_work_han_thu_112","textTraditional":"〔六〕　師古曰：「士雖各自載糧，而在道已盡。至於歸塗，尚苦乏食不足，不能終師旅之事也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_112_83","chapterId":"ch_work_han_thu_112","textTraditional":"〔七〕　師古曰：「廝留，言其前後離廝，不相逮及也。廝音斯。」","sentenceOrder":83},
  {"id":"s_work_han_thu_112_84","chapterId":"ch_work_han_thu_112","textTraditional":"〔八〕　師古曰：「謂中國人為秦人，習故言也。匄，乞與也。若，汝也。乞音氣。」","sentenceOrder":84},
  {"id":"s_work_han_thu_112_85","chapterId":"ch_work_han_thu_112","textTraditional":"〔九〕　師古曰：「與軍而遣之。」","sentenceOrder":85},
  {"id":"s_work_han_thu_112_86","chapterId":"ch_work_han_thu_112","textTraditional":"〔一０〕師古曰：「與讀曰豫。」","sentenceOrder":86},
  {"id":"s_work_han_thu_112_87","chapterId":"ch_work_han_thu_112","textTraditional":"〔一一〕師古曰：「謂共卿大夫謀事，尚不專決，猶雜問蓍龜也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_112_88","chapterId":"ch_work_han_thu_112","textTraditional":"〔一二〕師古曰：「視讀曰示。為文學，謂學經書之人。」","sentenceOrder":88},
  {"id":"s_work_han_thu_112_89","chapterId":"ch_work_han_thu_112","textTraditional":"〔一三〕師古曰：「見，顯示。」","sentenceOrder":89},
  {"id":"s_work_han_thu_112_90","chapterId":"ch_work_han_thu_112","textTraditional":"〔一四〕師古曰：「言其夸張也。視亦讀曰示。」","sentenceOrder":90},
  {"id":"s_work_han_thu_112_91","chapterId":"ch_work_han_thu_112","textTraditional":"〔一五〕孟康曰：「其繇曰『枯楊生華』，象曰『枯楊生華，何可久也！』謂匈奴破不久也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_112_92","chapterId":"ch_work_han_thu_112","textTraditional":"〔一六〕師古曰：「今便利之時，後不可再得也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_112_93","chapterId":"ch_work_han_thu_112","textTraditional":"〔一七〕師古曰：「行將謂遣將率行也。釜山，山名也。鬴，古釜字。」","sentenceOrder":93},
  {"id":"s_work_han_thu_112_94","chapterId":"ch_work_han_thu_112","textTraditional":"〔一八〕師古曰：「上遣諸將，而於卦中貳師最吉也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_112_95","chapterId":"ch_work_han_thu_112","textTraditional":"〔一九〕師古曰：「言不效也。繆，妄也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_112_96","chapterId":"ch_work_han_thu_112","textTraditional":"〔二０〕師古曰：「於軍所行之道及水上埋牛羊。」","sentenceOrder":96},
  {"id":"s_work_han_thu_112_97","chapterId":"ch_work_han_thu_112","textTraditional":"〔二一〕師古曰：「能音耐。」","sentenceOrder":97},
  {"id":"s_work_han_thu_112_98","chapterId":"ch_work_han_thu_112","textTraditional":"〔二二〕師古曰：「言死及被虜略，并自離散也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_112_99","chapterId":"ch_work_han_thu_112","textTraditional":"〔二三〕師古曰：「隧者，依深險之處開通行道也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_112_100","chapterId":"ch_work_han_thu_112","textTraditional":"〔二四〕師古曰：「伯讀曰霸。五霸尚恥不為，況今大漢也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_112_101","chapterId":"ch_work_han_thu_112","textTraditional":"〔二五〕師古曰：「搜索者，恐其或私齎文書也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_112_102","chapterId":"ch_work_han_thu_112","textTraditional":"〔二六〕師古曰：「言邊塞有闌出逃亡之人，而（止）〔主〕者不禁。又長吏利於皮肉，多使障候之卒獵獸，故令烽火有乏。又其人勞苦，因致奔亡，凡有此失。皆不集於所（亡）〔上〕文書。」","sentenceOrder":102},
  {"id":"s_work_han_thu_112_103","chapterId":"ch_work_han_thu_112","textTraditional":"〔二七〕師古曰：「既不上書，所以當時不知，至有降者來，及捕生口，或虜得匈奴人言之，乃知此事。」","sentenceOrder":103},
  {"id":"s_work_han_thu_112_104","chapterId":"ch_work_han_thu_112","textTraditional":"〔二八〕孟康曰：「先是令長吏各以秩養馬，亭有牝馬，民養馬皆復不事。後馬多絕乏，至此復修之也。」師古曰：「此說非也。馬復，因養馬以免徭賦也。復音方目反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_112_105","chapterId":"ch_work_han_thu_112","textTraditional":"〔二九〕師古曰：「與上計者同來赴對也。」","sentenceOrder":105},
  {"id":"s_work_han_thu_112_106","chapterId":"ch_work_han_thu_112","textTraditional":"初，貳師將軍李廣利擊大宛，還過杅彌，杅彌遣太子賴丹為質於龜茲。廣利責龜茲曰：「外國皆臣屬於漢，龜茲何以得受杅彌質？」即將賴丹入至京師。昭帝乃用桑弘羊前議，以杅彌太子賴丹為校尉將軍，田輪臺，輪臺與渠犁地皆相連也。龜茲貴人姑翼謂其王曰：「賴丹本臣屬吾國，今佩漢印綬來，迫吾國而田，必為害。」王即殺賴丹，而上書謝漢，漢未能征。","sentenceOrder":106},
  {"id":"s_work_han_thu_112_107","chapterId":"ch_work_han_thu_112","textTraditional":"宣帝時，長羅侯常惠使烏孫還，便宜發諸國兵，〔一〕合五萬人攻龜茲，責以前殺校尉賴丹。龜茲王謝曰：「乃我先王時為貴人姑翼所誤，我無罪。」執姑翼詣惠，惠斬之。時烏孫公主遣女來至京師學鼓琴，漢遣侍郎樂奉送主女，過龜茲。龜茲前遣人至烏孫求公主女，未還。會女過龜茲，龜茲王留不遣，復使使報公主，主許之。後公主上書，願令女比宗室入朝，而龜茲王絳賓亦愛其夫人，上書言得尚漢外孫為昆弟，願與公主女俱入朝。元康元年，逐來朝賀。王及夫人皆賜印綬。夫人號稱公主，賜以車騎旗鼓，歌吹數十人，綺繡雜繒琦珍凡數千萬。〔二〕留且一年，厚贈送之。後數來朝賀，樂漢衣服制度，歸其國，治宮室，作徼道周衛，出入傳呼，撞鐘鼓，如漢家儀。外國胡人皆曰：「驢非驢，馬非馬，若龜茲王，所謂驘也。」絳賓死，其子丞德自謂漢外孫，成、哀帝時往來尤數，漢遇之亦甚親密。","sentenceOrder":107},
  {"id":"s_work_han_thu_112_108","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「以便宜擅發兵也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_112_109","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　師古曰：「琦音奇。」","sentenceOrder":109},
  {"id":"s_work_han_thu_112_110","chapterId":"ch_work_han_thu_112","textTraditional":"東通尉犁六百五十里。","sentenceOrder":110},
  {"id":"s_work_han_thu_112_111","chapterId":"ch_work_han_thu_112","textTraditional":"尉犁國，王治尉犁城，去長安六千七百五十里。戶千二百，口九千六百，勝兵二千人。尉犁侯、安世侯、左右將、左右都尉、擊胡君各一人，譯長二人。西至都護治所三百里，南與鄯善、且末接。","sentenceOrder":111},
  {"id":"s_work_han_thu_112_112","chapterId":"ch_work_han_thu_112","textTraditional":"危須國，王治危須城，去長安七千二百九十里。戶七百，口四千九百，勝兵二千人。擊胡侯、擊胡都尉、左右將、左右都尉、左右騎君、擊胡君、譯長各一人。西至都護治所五百里，至焉耆百里。","sentenceOrder":112},
  {"id":"s_work_han_thu_112_113","chapterId":"ch_work_han_thu_112","textTraditional":"焉耆國，王治員渠城，〔一〕去長安七千三百里。戶四千，口三萬二千一百，勝兵六千人。擊胡侯、卻胡侯、輔國侯、左右將、左右都尉、擊胡左右君、擊車師君、歸義車師君各一人，擊胡都尉、擊胡君各二人，譯長三人。西南至都護治所四百里，南至尉犁百里，北與烏孫接。近海水多魚。","sentenceOrder":113},
  {"id":"s_work_han_thu_112_114","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「員音于權反。」","sentenceOrder":114},
  {"id":"s_work_han_thu_112_115","chapterId":"ch_work_han_thu_112","textTraditional":"烏貪訾離國，王治于婁谷，去長安萬三百三十里。戶四十一，口二百三十一，勝兵五十七人。輔國侯、左右都尉各一人。東與單桓、南與且彌、西與烏孫接。〔一〕","sentenceOrder":115},
  {"id":"s_work_han_thu_112_116","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「且音子余反。」","sentenceOrder":116},
  {"id":"s_work_han_thu_112_117","chapterId":"ch_work_han_thu_112","textTraditional":"卑陸國，王治天山東乾當國，〔一〕去長安八千六百八十里。戶二百二十七，口千三百八十七，勝兵四百二十二人。輔國侯、左右將、左右都尉、左右譯長各一人。西南至都護治所千二百八十七里。","sentenceOrder":117},
  {"id":"s_work_han_thu_112_118","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「乾音干。」","sentenceOrder":118},
  {"id":"s_work_han_thu_112_119","chapterId":"ch_work_han_thu_112","textTraditional":"卑陸後國，王治番渠類谷，〔一〕去長安八千七百一十里。戶四百六十二，口千一百三十七，勝兵三百五十人。輔國侯、都尉、譯長各一人，將二人。東與郁立師、北與匈奴、西與劫國、南與車師接。","sentenceOrder":119},
  {"id":"s_work_han_thu_112_120","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「番音盤。」","sentenceOrder":120},
  {"id":"s_work_han_thu_112_121","chapterId":"ch_work_han_thu_112","textTraditional":"郁立師國，王治內咄谷，〔一〕去長安八千八百三十里。戶百九十，口千四百四十五，勝兵三百三十一人。輔國侯、左右都尉、譯長各一人。東與車師後城長、西與卑陸、北與匈奴接。","sentenceOrder":121},
  {"id":"s_work_han_thu_112_122","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「咄音丁忽反。」","sentenceOrder":122},
  {"id":"s_work_han_thu_112_123","chapterId":"ch_work_han_thu_112","textTraditional":"單桓國，王治單桓城，去長安八千八百七十里。戶二十七，口百九十四，勝兵四十五人。輔國侯、將、左右都尉、譯長各一人。","sentenceOrder":123},
  {"id":"s_work_han_thu_112_124","chapterId":"ch_work_han_thu_112","textTraditional":"蒲類國，王治天山西疏榆谷，去長安八千三百六十里。戶三百二十五，口二千三十二，勝兵七百九十九人。輔國侯、左右將、左右都尉各一人。西南至都護治所千三百八十七里。","sentenceOrder":124},
  {"id":"s_work_han_thu_112_125","chapterId":"ch_work_han_thu_112","textTraditional":"蒲類後國，王去長安八千六百三十里。戶百，口千七十，勝兵三百三十四人。輔國侯、將、左右都尉、譯長各一人。","sentenceOrder":125},
  {"id":"s_work_han_thu_112_126","chapterId":"ch_work_han_thu_112","textTraditional":"西且彌國，王治天山東于大谷，〔一〕去長安八千六百七十里。戶三百三十二，口千九百二十六，勝兵七百三十八人。西且彌侯、左右將、左右騎君各一人。西南至都護治所千四百八十七里。","sentenceOrder":126},
  {"id":"s_work_han_thu_112_127","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「且音子余反。」","sentenceOrder":127},
  {"id":"s_work_han_thu_112_128","chapterId":"ch_work_han_thu_112","textTraditional":"東且彌國，王治天山東兌虛谷，去長安八千二百五十里。戶百九十一，口千九百四十八，勝兵五百七十二人。東且彌侯、左右都尉各一人。西南至都護治所千五百八十七里。","sentenceOrder":128},
  {"id":"s_work_han_thu_112_129","chapterId":"ch_work_han_thu_112","textTraditional":"劫國，王治天山東丹渠谷，去長安八千五百七十里。戶九十九，口五百，勝兵百一十五人。輔國侯、都尉、譯長各一人。西南至都護治所千四百八十七里。","sentenceOrder":129},
  {"id":"s_work_han_thu_112_130","chapterId":"ch_work_han_thu_112","textTraditional":"狐胡國，王治車師柳谷，去長安八千二百里。戶五十五，口二百六十四，勝兵四十五人。輔國侯、左右都尉各一人。西至都護治所千一百四十七里，至焉耆七百七十里。","sentenceOrder":130},
  {"id":"s_work_han_thu_112_131","chapterId":"ch_work_han_thu_112","textTraditional":"山國，王去長安七千一百七十里。〔一〕戶四百五十，口五千，勝兵千人。輔國侯、左右將、左右都尉、譯長各一人。西至尉犁二百四十里，西北至焉耆百六十里，西至危須二百六十里，東南與鄯善、且末接。山出鐵，民山居，寄田糴穀於焉耆、危須。","sentenceOrder":131},
  {"id":"s_work_han_thu_112_132","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「常在山下居，不為城治也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_112_133","chapterId":"ch_work_han_thu_112","textTraditional":"車師前國，王治交河城。河水分流繞城下，故號交河。去長安八千一百五十里。戶七百，口六千五十，勝兵千八百六十五人。輔國侯、安國侯、左右將、都尉、歸漢都尉、車師君、通善君、鄉善君各一人，〔一〕譯長二人。西南至都護治所千八百七里，至焉耆八百三十五里。","sentenceOrder":133},
  {"id":"s_work_han_thu_112_134","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":134},
  {"id":"s_work_han_thu_112_135","chapterId":"ch_work_han_thu_112","textTraditional":"車師後（王）國，〔王〕治務塗谷，去長安八千九百五十里。戶五百九十五，口四千七百七十四，勝兵千八百九十人。擊胡侯、左右將、左右都尉、道民君、譯長各一人。〔一〕西南至都護治所千二百三十七里。","sentenceOrder":135},
  {"id":"s_work_han_thu_112_136","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「道讀曰導。」","sentenceOrder":136},
  {"id":"s_work_han_thu_112_137","chapterId":"ch_work_han_thu_112","textTraditional":"車師都尉國，戶四十，口三百三十三，勝兵八十四人。","sentenceOrder":137},
  {"id":"s_work_han_thu_112_138","chapterId":"ch_work_han_thu_112","textTraditional":"車師後城長國，戶百五十四，口九百六十，勝兵二百六十人。","sentenceOrder":138},
  {"id":"s_work_han_thu_112_139","chapterId":"ch_work_han_thu_112","textTraditional":"武帝天漢二年，以匈奴降者介和王為開陵侯，將樓蘭國兵始擊車師，匈奴遣右賢王將數萬騎救之，漢兵不利，引去。征和四年，遣重合侯馬通將四萬騎擊匈奴，道過車師北，復遣開陵侯將樓蘭、尉犁、危須凡六國兵別擊車師，勿令得遮重合侯。諸國兵共圍車師，車師王降服，臣屬漢。","sentenceOrder":139},
  {"id":"s_work_han_thu_112_140","chapterId":"ch_work_han_thu_112","textTraditional":"昭帝時，匈奴復使四千騎田車師。宣帝即位，遣五將將兵擊匈奴，〔一〕車師田者驚去，車師復通於漢。匈奴怒，召其太子軍宿，欲以為質。軍宿，焉耆外孫，不欲質匈奴，亡走焉耆。車師王更立子烏貴為太子。及烏貴立為王，與匈奴結婚姻，教匈奴遮漢道通烏孫者。","sentenceOrder":140},
  {"id":"s_work_han_thu_112_141","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「謂本始二年御史大夫田廣明為祁連將軍，後將軍趙充國為蒲類將軍，雲中太守田順為武牙將軍，及度遼將軍范明友、前將軍韓增，凡五將也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_112_142","chapterId":"ch_work_han_thu_112","textTraditional":"地節二年，漢遣侍郎鄭吉、校尉司馬憙〔一〕將免刑罪人田渠犁，積穀，欲以攻車師。至秋收穀，吉、憙發城郭諸國兵萬餘人，自與所將田士千五百人共擊車師，攻交河城，破之。王尚在其北石城中，未得，會軍食盡，吉等且罷兵，歸渠犁田。（秋收）〔收秋〕畢，復發兵攻車師王於石城。王聞漢兵且至，北走匈奴求救，匈奴未為發兵。王來還，與貴人蘇猶議欲降漢，恐不見信。蘇猶教王擊匈奴邊國小蒲類，斬首，略其人民，以降吉。車師旁小金附國隨漢軍後盜車師，車師王復自請擊破金附。","sentenceOrder":142},
  {"id":"s_work_han_thu_112_143","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「憙音許吏反。」","sentenceOrder":143},
  {"id":"s_work_han_thu_112_144","chapterId":"ch_work_han_thu_112","textTraditional":"匈奴聞車師降漢，發兵攻車師，吉、憙引兵北逢之，匈奴不敢前。吉、憙即留一候與卒二十人留守王，吉等引兵歸渠犁。車師王恐匈奴兵復至而見殺也，乃輕騎奔烏孫，吉即迎其妻子置渠犁。東奏事，至酒泉，有詔還田渠犁及車師，益積穀以安西國，侵匈奴。吉還，傳送車師王妻子詣長安，賞賜甚厚，每朝會四夷，常尊顯以示之。於是吉始使吏卒三百人別田車師。得降者言，單于大臣皆曰「車師地肥美，近匈奴，使漢得之，多田積穀，必害人國，不可不爭也。」果遣騎來擊田者，吉乃與校尉盡將渠犁田士千五百人往田，匈奴復益遣騎來，漢田卒少不能當，保車師城中。匈奴將即其城下謂吉曰：〔一〕「單于必爭此地，不可田也。」圍城數日乃解。後常數千騎往來守車師，吉上書言：「車師去渠犁千餘里，間以河山，〔二〕北近匈奴，漢兵在渠犁者勢不能相救，願益田卒。」公卿議以為道遠煩費，可且罷車師田者。詔遣長羅侯〔三〕將張掖、酒泉騎出車師北千餘里，揚威武車師旁。胡騎引去，吉乃得出，歸渠犁，凡三校尉屯田。","sentenceOrder":144},
  {"id":"s_work_han_thu_112_145","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「即，就也。」","sentenceOrder":145},
  {"id":"s_work_han_thu_112_146","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　師古曰：「間，隔也，音居莧反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_112_147","chapterId":"ch_work_han_thu_112","textTraditional":"〔三〕　師古曰：「常惠也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_112_148","chapterId":"ch_work_han_thu_112","textTraditional":"車師王之走烏孫也，烏孫留不遣，遣使上書，願留車師王，備國有急，可從西道以擊匈奴。漢許之。於是漢召故車師太子軍宿在焉耆者，立以為王，盡徙車師國民令居渠犁，遂以車師故地與匈奴。車師王得近漢田官，與匈奴絕，亦安樂親漢。後漢使侍郎殷廣德責烏孫，求車師王烏（孫）貴，將詣闕，〔一〕賜第與其妻子居。是歲，元康四年也。其後置戊己校尉屯田，居車師故地。","sentenceOrder":148},
  {"id":"s_work_han_thu_112_149","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「烏孫遣其將之貴者入漢朝。」","sentenceOrder":149},
  {"id":"s_work_han_thu_112_150","chapterId":"ch_work_han_thu_112","textTraditional":"元始中，車師後王國有新道，出五船北，通玉門關，往來差近，戊己校尉徐普欲開以省道里半，避白龍堆之阨。車師後王姑句〔一〕以道當為拄置，〔二〕心不便也。地又頗與匈奴南將軍地接，普欲分明其界然後奏之，召姑句使證之，不肯，繫之。姑句數以牛羊賕吏，求出不得。姑句家矛端生火，其妻股紫陬〔三〕謂姑句曰：「矛端生火，此兵氣也，利以用兵。前車師前王為都護司馬所殺，今久繫必死，不如降匈奴。」即馳突出高昌壁，入匈奴。","sentenceOrder":150},
  {"id":"s_work_han_thu_112_151","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「句音鉤。」","sentenceOrder":151},
  {"id":"s_work_han_thu_112_152","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　師古曰：「拄者，支拄也。言有所置立，而支拄於己，故心不便也。拄音竹羽反，又音竹具反。其字從手，而讀之者或不曉，以拄為梁柱之柱，及分破其句，言置柱於心，皆失之矣。」","sentenceOrder":152},
  {"id":"s_work_han_thu_112_153","chapterId":"ch_work_han_thu_112","textTraditional":"〔三〕　師古曰：「陬音子侯反。」","sentenceOrder":153},
  {"id":"s_work_han_thu_112_154","chapterId":"ch_work_han_thu_112","textTraditional":"又去胡來王唐兜，國比大種赤水羌，〔一〕數相寇，不勝，告急都護。都護但欽不以時救助，唐兜困急，怨欽，東守玉門關。玉門關不內，即將妻子人民千餘人亡降匈奴。匈奴受之，而遣使上書言狀。是時，新都侯王莽秉政，遣中郎將王昌等使匈奴，告單于西域內屬，不當得受。單于謝罪，執二王以付使者。莽使中郎王萌待西域惡都奴界上逢受。〔二〕單于遣使送，因請其罪。〔三〕使者以聞，莽不聽，詔下會西域諸國王，陳軍斬姑句、唐兜以示之。","sentenceOrder":154},
  {"id":"s_work_han_thu_112_155","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「比，近也，音頻寐反。」","sentenceOrder":155},
  {"id":"s_work_han_thu_112_156","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　師古曰：「逢受謂先至待之，逢見即受取也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_112_157","chapterId":"ch_work_han_thu_112","textTraditional":"〔三〕　師古曰：「請免其罪也。」","sentenceOrder":157},
  {"id":"s_work_han_thu_112_158","chapterId":"ch_work_han_thu_112","textTraditional":"至莽篡位，建國二年，以廣新公甄豐為右伯，當出西域。車師後王須置離聞之，與其右將股鞮、左將尸泥支謀曰：〔一〕「聞甄公為西域太伯，當出，故事給使者牛羊穀芻茭，導譯，前五威將過，所給使尚未能備。今太伯復出，國益貧，恐不能稱。」〔二〕欲亡入匈奴。戊己校尉刀護聞之，〔三〕召置離驗問，辭服，乃械致都護但欽在所埒婁城。〔四〕置離人民知其不還，皆哭而送之。至，欽則斬置離。置離兄輔國侯狐蘭支將置離眾二千餘人，驅畜產，舉國亡降匈奴。〔五〕","sentenceOrder":158},
  {"id":"s_work_han_thu_112_159","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「鞮音丁奚反。」","sentenceOrder":159},
  {"id":"s_work_han_thu_112_160","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　師古曰：「不副所求也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_112_161","chapterId":"ch_work_han_thu_112","textTraditional":"〔三〕　師古曰：「刀音彫。」","sentenceOrder":161},
  {"id":"s_work_han_thu_112_162","chapterId":"ch_work_han_thu_112","textTraditional":"〔四〕　師古曰：「埒婁，城名。埒音劣。婁音樓。」","sentenceOrder":162},
  {"id":"s_work_han_thu_112_163","chapterId":"ch_work_han_thu_112","textTraditional":"〔五〕　師古曰：「盡率一國之眾也。」","sentenceOrder":163},
  {"id":"s_work_han_thu_112_164","chapterId":"ch_work_han_thu_112","textTraditional":"是時，莽易單于璽，單于恨怒，遂受狐蘭支降，遣兵與共寇擊車師，殺後城長，傷都護司馬，及狐蘭兵復還入匈奴。時戊己校尉刀護病，遣史陳良屯桓且谷備匈奴寇，〔一〕史終帶取糧食，司馬丞韓玄領諸壁，右曲候任商領諸壘，相與謀曰：「西域諸國頗背叛，匈奴欲大侵，要死。可殺校尉，將人眾降匈奴。」〔二〕即將數千騎至校尉府，脅諸亭令燔積薪，〔三〕分告諸壁曰：「匈奴十萬騎來入，吏士皆持兵，後者斬！」得三（百四）〔四百〕人，去校尉府數里止，晨火然。〔四〕校尉開門擊鼓收吏士，良等隨入，遂殺校尉刀護及子男四人、諸昆弟子男，獨遺婦女小兒。〔五〕止留戊己校尉城，遣人與匈奴南將軍相聞，南將軍以二千騎迎良等。良等盡脅略戊己校尉吏士男女二千餘人入匈奴。單于以良、帶為烏賁都尉。〔六〕","sentenceOrder":164},
  {"id":"s_work_han_thu_112_165","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「且音子余反。」","sentenceOrder":165},
  {"id":"s_work_han_thu_112_166","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　如淳曰：「言匈奴來侵，會當死耳，可降匈奴也。」師古曰：「要音一妙反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_112_167","chapterId":"ch_work_han_thu_112","textTraditional":"〔三〕　師古曰：「示為烽火也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_112_168","chapterId":"ch_work_han_thu_112","textTraditional":"〔四〕　師古曰：「{難灬}，古然字。」","sentenceOrder":168},
  {"id":"s_work_han_thu_112_169","chapterId":"ch_work_han_thu_112","textTraditional":"〔五〕　師古曰：「遺，留置不殺也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_112_170","chapterId":"ch_work_han_thu_112","textTraditional":"〔六〕　師古曰：「賁音奔。」","sentenceOrder":170},
  {"id":"s_work_han_thu_112_171","chapterId":"ch_work_han_thu_112","textTraditional":"後三歲，單于死，弟烏絫單于咸立，〔一〕復與莽和親。莽遣使者多齎金幣賂單于，購求陳良、終帶等。單于盡收四人及手殺刀護者芝音妻子以下二十七人，皆械檻車付使者。到長安，莽皆燒殺之。其後莽復欺詐單于，和親遂絕。匈奴大擊北邊，而西域亦瓦解。焉耆國近匈奴，先叛，殺都護但欽，莽不能討。","sentenceOrder":171},
  {"id":"s_work_han_thu_112_172","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「絫音力追反。」","sentenceOrder":172},
  {"id":"s_work_han_thu_112_173","chapterId":"ch_work_han_thu_112","textTraditional":"天鳳（二）〔三〕年，乃遣五威將王駿、西域都護李崇將戊己校尉出西域，諸國皆郊迎，送兵穀。焉耆詐降而聚兵自備。駿等將莎車、龜茲兵七千餘人，分為數部入焉耆，焉耆伏兵要遮駿。及姑墨、尉犁、危須國兵為反間，還共襲擊駿等，皆殺之。唯戊己校尉郭欽別將兵，後至焉耆。焉耆兵未還，欽擊殺其老弱，引兵還。莽封欽為剼胡子。〔一〕李崇收餘士，還保龜茲。數年莽死，崇遂沒，西域因絕。","sentenceOrder":173},
  {"id":"s_work_han_thu_112_174","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　鄧展曰：「剼音衫。」師古曰：「剼，絕也，音子小反。字本作劋，轉寫誤耳。」","sentenceOrder":174},
  {"id":"s_work_han_thu_112_175","chapterId":"ch_work_han_thu_112","textTraditional":"最凡國五十。自譯長、城長、君、監、吏、大祿、百長、千長、都尉、且渠、當戶、將、相至侯、王，皆佩漢印綬，凡三百七十六人。而康居、大月氏、安息、罽賓、烏弋之屬，皆以絕遠不在數中，其來貢獻則相與報，不督錄總領也。","sentenceOrder":175},
  {"id":"s_work_han_thu_112_176","chapterId":"ch_work_han_thu_112","textTraditional":"贊曰：孝武之世，圖制匈奴，患其兼從西國，結黨南羌，〔一〕乃表河（曲）〔西〕，列（西）〔四〕郡，開玉門，通西域，以斷匈奴右臂，隔絕南羌、月氏。單于失援，由是遠遁，而幕南無王庭。","sentenceOrder":176},
  {"id":"s_work_han_thu_112_177","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「圖，謀也。從音子容反。」","sentenceOrder":177},
  {"id":"s_work_han_thu_112_178","chapterId":"ch_work_han_thu_112","textTraditional":"遭值文、景玄默，養民五世，天下殷富，財力有餘，士馬彊盛。故能睹犀布、玳瑁則建珠崖七（部）〔郡〕，〔一〕感枸醬、竹杖則開牂柯、越嶲，〔二〕聞天馬、蒲陶則通大宛、安息。自是之後，明珠、文甲、通犀、翠羽之珍盈於後宮，〔三〕蒲梢、龍文、魚目、汗血之馬充於黃門，〔四〕鉅象、師子、猛犬、大雀之群食於外囿〔五〕。殊方異物，四面而至。於是廣開上林，穿昆明池，營千門萬戶之宮，立神明通天之臺，興造甲乙之帳，〔六〕落以隨珠和璧，〔七〕天子負黼依，襲翠被，馮玉几，而處其中。〔八〕設酒池肉林以饗四夷之客，作巴俞都盧、海中碭極、漫衍魚龍、角抵之戲以觀視之〔九〕。及賂遺贈送，萬里相奉，師旅之費，不可勝計。至於用度不足，乃榷酒酤，筦鹽鐵，鑄白金，造皮幣，算至車船，租及六畜。民力屈，財用竭，〔一０〕因之以凶年，寇盜並起，道路不通，直指之使始出，衣繡杖斧，斷斬於郡國，然後勝之。是以末年遂棄輪臺之地，而下哀痛之詔，豈非仁聖之所悔哉！且通西域，近有龍堆，遠則蔥嶺，身熱、頭痛、縣度之阨。淮南、杜欽、揚雄之論，皆以為此天地所以界別區域，絕外內也。書曰「西戎即序」，〔一一〕禹既就而序之，非上威服致其貢物也。","sentenceOrder":178},
  {"id":"s_work_han_thu_112_179","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「玳音代。瑁音妹。」","sentenceOrder":179},
  {"id":"s_work_han_thu_112_180","chapterId":"ch_work_han_thu_112","textTraditional":"〔二〕　師古曰：「枸音矩。」","sentenceOrder":180},
  {"id":"s_work_han_thu_112_181","chapterId":"ch_work_han_thu_112","textTraditional":"〔三〕　如淳曰：「文甲即玳瑁也。通犀，中央色白，通兩頭。」","sentenceOrder":181},
  {"id":"s_work_han_thu_112_182","chapterId":"ch_work_han_thu_112","textTraditional":"〔四〕　孟康曰：「四駿馬名也。」師古曰：「梢馬音所交反。」","sentenceOrder":182},
  {"id":"s_work_han_thu_112_183","chapterId":"ch_work_han_thu_112","textTraditional":"〔五〕　師古曰：「鉅亦大。」","sentenceOrder":183},
  {"id":"s_work_han_thu_112_184","chapterId":"ch_work_han_thu_112","textTraditional":"〔六〕　師古曰：「其數非一，以甲乙次第名之也。」","sentenceOrder":184},
  {"id":"s_work_han_thu_112_185","chapterId":"ch_work_han_thu_112","textTraditional":"〔七〕　師古曰：「落與絡同。」","sentenceOrder":185},
  {"id":"s_work_han_thu_112_186","chapterId":"ch_work_han_thu_112","textTraditional":"〔八〕　師古曰：「依讀曰扆。扆如小屏風，而畫為黼文也。白與黑謂之黼，又為斧形。襲，重衣也。被音皮義反。」","sentenceOrder":186},
  {"id":"s_work_han_thu_112_187","chapterId":"ch_work_han_thu_112","textTraditional":"〔九〕　晉灼曰：「都盧，國名也。」李奇曰：「都盧，體輕善緣者也。碭極，樂名也。」師古曰：「巴人，巴州人也。俞，水名，今渝州也。巴俞之人，所謂賨人也，勁銳善舞，本從高祖定三秦有功，高祖喜觀其舞，因令樂人習之，故有巴俞之樂。漫衍者，即張衡西京賦所云『巨獸百尋，是為漫延』者也。魚龍者，為舍利之獸，先戲於庭極，畢乃入殿前激水，化成比目魚，跳躍漱水。作霧障日，畢，化成黃龍八丈，出水敖戲於庭，炫燿日光。西京賦云『海鱗變而成龍』，即為此色也。俞音踰。碭音大浪反。衍音弋戰反。視讀曰示。觀示者，視之令觀也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_112_188","chapterId":"ch_work_han_thu_112","textTraditional":"〔一０〕師古曰：「屈音其勿反。」","sentenceOrder":188},
  {"id":"s_work_han_thu_112_189","chapterId":"ch_work_han_thu_112","textTraditional":"〔一一〕師古曰：「禹貢之辭也。序，次也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_112_190","chapterId":"ch_work_han_thu_112","textTraditional":"西域諸國，各有君長，兵眾分弱，無所統一，雖屬匈奴，不相親附。匈奴能得其馬畜旃罽，而不能統率與之進退。與漢隔絕，道里又遠，得之不為益，棄之不為損。盛德在我，無取於彼。故自建武以來，西域思漢威德，咸樂內屬。唯其小邑鄯善、車師，界迫匈奴，尚為所拘。而其大國莎車、于闐之屬，數遣使置質于漢，願請屬都護。聖上遠覽古今，因時之宜，羇縻不絕，辭而未許。雖大禹之序西戎，周公之讓白雉，太宗之卻走馬，義兼之矣，亦何以尚茲！〔一〕","sentenceOrder":190},
  {"id":"s_work_han_thu_112_191","chapterId":"ch_work_han_thu_112","textTraditional":"〔一〕　師古曰：「『西戎即序』，說已在前。昔周公相成王，越裳氏重九譯而獻白雉。至，王問周公，公曰：『德不加焉，則君子不饗其質；政不施焉，則君子不臣其遠。吾何以獲此物也？』譯曰：『吾受命國之黃耉「曰久矣天之無烈風雨雷也，意中國有聖人乎？盍往朝之，然後歸之。」』王稱先王之神所致，以薦宗廟。太宗，漢文帝也。卻走馬，謂有人獻千里馬，不受，還之，賜道路費也。老子德經曰『天下有道，卻走馬以糞』，故贊引也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_112_192","chapterId":"ch_work_han_thu_112","textTraditional":"校勘記","sentenceOrder":192},
  {"id":"s_work_han_thu_112_193","chapterId":"ch_work_han_thu_112","textTraditional":"三九０一頁　七行　貪（狠）〔狼〕無信，　景祐、殿本都作「狼」。","sentenceOrder":193},
  {"id":"s_work_han_thu_112_194","chapterId":"ch_work_han_thu_112","textTraditional":"三九０五頁一五行　使長（盧）〔羅〕侯光祿大夫惠為副，　錢大昭說「盧」當作「羅」。按景祐、殿本都作「羅」。","sentenceOrder":194},
  {"id":"s_work_han_thu_112_195","chapterId":"ch_work_han_thu_112","textTraditional":"三九０七頁　一行　不正下（之）。　景祐本無「之」字。殿本「之」作「也」。","sentenceOrder":195},
  {"id":"s_work_han_thu_112_196","chapterId":"ch_work_han_thu_112","textTraditional":"三九０七頁一一行　詔（焉）烏就屠詣長羅侯赤谷城，　錢大昭說「焉」字衍。按景祐、殿本都無「焉」字。","sentenceOrder":196},
  {"id":"s_work_han_thu_112_197","chapterId":"ch_work_han_thu_112","textTraditional":"三九０八頁　五行　願使烏孫鎮撫星（彌）〔靡〕，　景祐、殿、局本都作「靡」，此誤。","sentenceOrder":197},
  {"id":"s_work_han_thu_112_198","chapterId":"ch_work_han_thu_112","textTraditional":"三九０八頁　六行　卒百人送（烏孫）焉。　景祐本無「烏孫」二字。","sentenceOrder":198},
  {"id":"s_work_han_thu_112_199","chapterId":"ch_work_han_thu_112","textTraditional":"三九０九頁　三行　小昆（靡）〔彌〕末振將恐為所并，　景祐、殿本都作「彌」。王先謙說作「彌」是。","sentenceOrder":199},
  {"id":"s_work_han_thu_112_200","chapterId":"ch_work_han_thu_112","textTraditional":"三九０九頁　六行　漢恨不自（責）誅末振將，　景祐本無「責」字。","sentenceOrder":200},
  {"id":"s_work_han_thu_112_201","chapterId":"ch_work_han_thu_112","textTraditional":"三九一０頁　八行　東至都護治所（一）〔二〕千二十一里，南至（於）〔于〕闐　景祐、殿本「一」都作「二」，「於」都作「于」。","sentenceOrder":201},
  {"id":"s_work_han_thu_112_202","chapterId":"ch_work_han_thu_112","textTraditional":"三九一二頁　三行　故輪臺（以）東捷枝、渠犁皆故國，　景祐本無「以」字。","sentenceOrder":202},
  {"id":"s_work_han_thu_112_203","chapterId":"ch_work_han_thu_112","textTraditional":"三九一二頁　四行　宜給足不（可）乏。　王念孫說「可」字衍。","sentenceOrder":203},
  {"id":"s_work_han_thu_112_204","chapterId":"ch_work_han_thu_112","textTraditional":"三九一二頁　五行　務使以時益種五穀。〔二〕張掖、酒泉　注〔二〕原在「張掖酒泉」下。　齊召南說「張掖酒泉」當連下讀。茲從殿本。","sentenceOrder":204},
  {"id":"s_work_han_thu_112_205","chapterId":"ch_work_han_thu_112","textTraditional":"三九一三頁　六行　故興（師）遣貳師將軍，　景祐本無「師」字。錢大昭說無「師」字是。按通鑑亦無。","sentenceOrder":205},
  {"id":"s_work_han_thu_112_206","chapterId":"ch_work_han_thu_112","textTraditional":"三九一三頁一二行　重合侯（毋）〔得〕虜候者，　錢大昭說「毋」當作「得」。按景祐、殿本都作「得」。","sentenceOrder":206},
  {"id":"s_work_han_thu_112_207","chapterId":"ch_work_han_thu_112","textTraditional":"三九一五頁一五行　而（止）〔主〕者不禁。　景祐、殿本都作「主」，此誤。","sentenceOrder":207},
  {"id":"s_work_han_thu_112_208","chapterId":"ch_work_han_thu_112","textTraditional":"三九一五頁一六行　皆不集於所（亡）〔上〕文書。　景祐、殿、局本都作「上」，此誤。","sentenceOrder":208},
  {"id":"s_work_han_thu_112_209","chapterId":"ch_work_han_thu_112","textTraditional":"三九二一頁一０行　車師後（王）國，〔王〕　錢大昭說，依前後例當作「車師後國，王」。按殿本不誤。","sentenceOrder":209},
  {"id":"s_work_han_thu_112_210","chapterId":"ch_work_han_thu_112","textTraditional":"三九二二頁一四行　（秋收）〔收秋〕畢，　景祐、殿本都作「收秋」。","sentenceOrder":210},
  {"id":"s_work_han_thu_112_211","chapterId":"ch_work_han_thu_112","textTraditional":"三九二四頁　六行　求車師王烏（孫）貴，將詣闕，　錢大昕說此誤衍「孫」字，顏曲為之說。","sentenceOrder":211},
  {"id":"s_work_han_thu_112_212","chapterId":"ch_work_han_thu_112","textTraditional":"三九二六頁一一行　得三（百四）〔四百〕人，　景祐、殿本都作「四百」。","sentenceOrder":212},
  {"id":"s_work_han_thu_112_213","chapterId":"ch_work_han_thu_112","textTraditional":"三九二七頁一一行　天鳳（二）〔三〕年，　景祐、殿本都作「三」。","sentenceOrder":213},
  {"id":"s_work_han_thu_112_214","chapterId":"ch_work_han_thu_112","textTraditional":"三九二八頁　五行　乃表河（曲）〔西〕，列（西）〔四〕郡，　王念孫說「曲」當為「西」字之誤。下「西」字景祐本作「四」。錢大昭說作「四」是。","sentenceOrder":214},
  {"id":"s_work_han_thu_112_215","chapterId":"ch_work_han_thu_112","textTraditional":"三九二八頁　九行　七（部）〔郡〕，　景祐、殿本都作「郡」。","sentenceOrder":215},
  {"id":"s_work_han_thu_113_1","chapterId":"ch_work_han_thu_113","textTraditional":"自古受命帝王及繼體守文之君，〔一〕非獨內德茂也，蓋亦有外戚之助焉。夏之興也以塗山，〔二〕而桀之放也用末喜；〔三〕殷之興也以有娀（又）〔及〕有｛新女｝，〔四〕而紂之滅也嬖妲己；〔五〕周之興也以姜嫄及太任、太姒，〔六〕而幽王之禽也淫褒姒。〔七〕故易基乾坤，詩首關雎，〔八〕書美釐降，〔九〕春秋譏不親迎。〔一０〕夫婦之際，人道之大倫也。〔一一〕禮之用，唯昏姻為兢兢〔一二〕。夫樂調而四時和，陰陽之變，萬物之統也，可不慎與！〔一三〕人能弘道，末如命何。〔一四〕甚哉妃匹之愛，君不能得之臣，父不能得之子，況卑下乎！〔一五〕既驩合矣，或不能成子姓，〔一六〕成子姓矣，而不能要其終，豈非命也哉！孔子罕言命，蓋難言之。〔一七〕非通幽明之變，惡能識乎性命！〔一八〕","sentenceOrder":1},
  {"id":"s_work_han_thu_113_2","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「繼體謂嗣位也。守文，言遵成法，不用武功也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_113_3","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「禹娶塗山氏之女而生啟也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_113_4","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「末喜，桀之妃，有施氏女也，美於色，薄於德，女子行，丈夫心。桀常置末喜於膝上，聽用其言，昏亂失道。於是湯伐之，遂放桀，與末喜死於南巢。」","sentenceOrder":4},
  {"id":"s_work_han_thu_113_5","chapterId":"ch_work_han_thu_113","textTraditional":"〔四〕　師古曰：「有娀，國名，其女簡狄吞燕卵而生卨，為殷始祖。有｛新女｝氏女，湯妃也。娀音嵩。｛新女｝音詵。」","sentenceOrder":5},
  {"id":"s_work_han_thu_113_6","chapterId":"ch_work_han_thu_113","textTraditional":"〔五〕　師古曰：「妲己，紂之妃，有蘇氏女也，美好辯辭，興於姦宄，嬖幸於紂。紂用其言，毒虐眾庶。於是武王伐紂，戰於牧野，紂師倒戈，不為之戰。武王克殷，致天之罰，斬妲己頭，縣之於小白旗，以為紂之亡者，由此女也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_113_7","chapterId":"ch_work_han_thu_113","textTraditional":"〔六〕　師古曰：「姜嫄，有邰氏之女，帝嚳之妃也，履大人跡而生后稷，為周始祖。太任，文王母；太姒，武王母也。嫄音原。」","sentenceOrder":7},
  {"id":"s_work_han_thu_113_8","chapterId":"ch_work_han_thu_113","textTraditional":"〔七〕　師古曰：「謂黜申后而致犬戎，舉偽烽而諸侯莫救也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_113_9","chapterId":"ch_work_han_thu_113","textTraditional":"〔八〕　師古曰：「基亦始。」","sentenceOrder":9},
  {"id":"s_work_han_thu_113_10","chapterId":"ch_work_han_thu_113","textTraditional":"〔九〕　師古曰：「釐，理也。尚書堯典稱舜之美，云『釐降二女于媯汭』，言堯欲觀舜治跡，以己二女妻之，舜能以治降下二女，以成其德。」","sentenceOrder":10},
  {"id":"s_work_han_thu_113_11","chapterId":"ch_work_han_thu_113","textTraditional":"〔一０〕師古曰：「春秋公羊經：『隱二年，紀履須來逆女。』傳曰：『外逆女不書，此何以書？譏也。何譏爾？始不親迎也。』」","sentenceOrder":11},
  {"id":"s_work_han_thu_113_12","chapterId":"ch_work_han_thu_113","textTraditional":"〔一一〕師古曰：「倫，理也。」","sentenceOrder":12},
  {"id":"s_work_han_thu_113_13","chapterId":"ch_work_han_thu_113","textTraditional":"〔一二〕師古曰：「兢兢，戒慎也。」","sentenceOrder":13},
  {"id":"s_work_han_thu_113_14","chapterId":"ch_work_han_thu_113","textTraditional":"〔一三〕師古曰：「與讀曰歟。」","sentenceOrder":14},
  {"id":"s_work_han_thu_113_15","chapterId":"ch_work_han_thu_113","textTraditional":"〔一四〕師古曰：「末，無也。論語載孔子曰：『人能弘道，非道弘人。』又稱子路曰：『道之將興，命也；道之將廢，命也。公伯寮如命何？』故引之。」","sentenceOrder":15},
  {"id":"s_work_han_thu_113_16","chapterId":"ch_work_han_thu_113","textTraditional":"〔一五〕師古曰：「言雖君父之尊，不能奪其所好而移其本意。」","sentenceOrder":16},
  {"id":"s_work_han_thu_113_17","chapterId":"ch_work_han_thu_113","textTraditional":"〔一六〕師古曰：「姓，生也。」","sentenceOrder":17},
  {"id":"s_work_han_thu_113_18","chapterId":"ch_work_han_thu_113","textTraditional":"〔一七〕師古曰：「論語曰『子罕言利與命與仁』。罕者，希也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_113_19","chapterId":"ch_work_han_thu_113","textTraditional":"〔一八〕師古曰：「惡音烏，謂於何也。論語稱子貢曰：『夫子之文章可得而聞也，夫子之言性與天道不可得而聞也已矣！』謂孔子不言性命及天道。而學者誤讀，謂孔子之言自然與天道合，非唯失於文句，實乃大乖意旨。」","sentenceOrder":19},
  {"id":"s_work_han_thu_113_20","chapterId":"ch_work_han_thu_113","textTraditional":"漢興，因秦之稱號，帝母稱皇太后，祖母稱太皇太后，適稱皇后，〔一〕妾皆稱夫人。又有美人、良人、八子、七子、長使、少使之號焉。〔二〕至武帝制婕妤、娙娥、傛華、充依，各有爵位，〔三〕而元帝加昭儀之號，〔四〕凡十四等云。〔五〕昭儀位視丞相，爵比諸侯王。婕妤視上卿，比列侯。娙娥視中二千石，比關內侯。〔六〕傛華視真二千石，比大上造。〔七〕美人視二千石，比少上造。〔八〕八子視千石，比中更。〔九〕充依視千石，比左更。〔一０〕七子視八百石，比右庶長。〔一一〕良人視八百石，比左庶長。〔一二〕長使視六百石，比五大夫。〔一三〕少使視四百石，比公乘。〔一四〕五官視三百石。〔一五〕順常視二百石。無涓、共和、娛靈、保林、良使、夜者皆視百石。〔一六〕上家人子、中家人子視有秩斗食云。〔一七〕五官以下，葬司馬門外。〔一八〕","sentenceOrder":20},
  {"id":"s_work_han_thu_113_21","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「適讀曰嫡。后亦君也。天曰皇天，地曰后土，故天子之妃，以后為稱，取象二儀。」","sentenceOrder":21},
  {"id":"s_work_han_thu_113_22","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「良，善也。八、七，祿秩之差也。長使、少使，主供使者。」","sentenceOrder":22},
  {"id":"s_work_han_thu_113_23","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「婕，言接幸於上也。妤，美稱也。娙娥，皆美貌也。傛傛猶言奕奕也，便習之意也。充依，言充後庭而依秩序也。婕音接。妤音予，字或從女，其音同耳。娙音五經反。傛音容。」","sentenceOrder":23},
  {"id":"s_work_han_thu_113_24","chapterId":"ch_work_han_thu_113","textTraditional":"〔四〕　師古曰：「昭顯其儀，示隆重也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_113_25","chapterId":"ch_work_han_thu_113","textTraditional":"〔五〕　師古曰：「除皇后，自昭儀以下至秩百石，十四等。」","sentenceOrder":25},
  {"id":"s_work_han_thu_113_26","chapterId":"ch_work_han_thu_113","textTraditional":"〔六〕　師古曰：「中二千石，實得二千石也。中之言滿也。月得百八十斛，是為一歲凡得二千一百六十石。言二千者，舉成數耳。」","sentenceOrder":26},
  {"id":"s_work_han_thu_113_27","chapterId":"ch_work_han_thu_113","textTraditional":"〔七〕　師古曰：「真二千石，月得百五十斛，一歲凡得千八百石耳。大上造，第十六爵。」","sentenceOrder":27},
  {"id":"s_work_han_thu_113_28","chapterId":"ch_work_han_thu_113","textTraditional":"〔八〕　師古曰：「二千石，月得百二十斛，一歲凡得一千四百四十石耳。少上造，第十五爵。」","sentenceOrder":28},
  {"id":"s_work_han_thu_113_29","chapterId":"ch_work_han_thu_113","textTraditional":"〔九〕　師古曰：「中更，第十三爵也。更，公衡反，其下亦同。」","sentenceOrder":29},
  {"id":"s_work_han_thu_113_30","chapterId":"ch_work_han_thu_113","textTraditional":"〔一０〕師古曰：「左更，第十二爵。」","sentenceOrder":30},
  {"id":"s_work_han_thu_113_31","chapterId":"ch_work_han_thu_113","textTraditional":"〔一一〕師古曰：「右庶長，第十一爵。」","sentenceOrder":31},
  {"id":"s_work_han_thu_113_32","chapterId":"ch_work_han_thu_113","textTraditional":"〔一二〕師古曰：「左庶長，第十爵。」","sentenceOrder":32},
  {"id":"s_work_han_thu_113_33","chapterId":"ch_work_han_thu_113","textTraditional":"〔一三〕師古曰：「五大夫，第九爵。」","sentenceOrder":33},
  {"id":"s_work_han_thu_113_34","chapterId":"ch_work_han_thu_113","textTraditional":"〔一四〕師古曰：「公乘，第八爵。」","sentenceOrder":34},
  {"id":"s_work_han_thu_113_35","chapterId":"ch_work_han_thu_113","textTraditional":"〔一五〕師古曰：「五官，所掌亦象外之五官也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_113_36","chapterId":"ch_work_han_thu_113","textTraditional":"〔一六〕師古曰：「涓，絜也。無涓，言無所不絜也。共讀曰恭，言恭順而和柔也。娛靈，可以娛樂情靈也。保，安也。保林，言其可安眾如林也。良使，使令之善者也。夜者，主職夜事。令音力成反。」","sentenceOrder":36},
  {"id":"s_work_han_thu_113_37","chapterId":"ch_work_han_thu_113","textTraditional":"〔一七〕師古曰：「家人子者，言採擇良家子以入宮，未有職號，但稱家人子也。斗食謂佐史也。謂之斗食者，言一歲不滿百石，日食一斗二升。」","sentenceOrder":37},
  {"id":"s_work_han_thu_113_38","chapterId":"ch_work_han_thu_113","textTraditional":"〔一八〕服虔曰：「陵上司馬門之外。」","sentenceOrder":38},
  {"id":"s_work_han_thu_113_39","chapterId":"ch_work_han_thu_113","textTraditional":"高祖呂皇后，父呂公，單父人也，〔一〕好相人。高祖微時，呂公見而異之，乃以女妻高祖，生惠帝、魯元公主。高祖為漢王，元年封呂公為臨泗侯，二年立孝惠為太子。","sentenceOrder":39},
  {"id":"s_work_han_thu_113_40","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「單音善。父音甫。」","sentenceOrder":40},
  {"id":"s_work_han_thu_113_41","chapterId":"ch_work_han_thu_113","textTraditional":"後漢王得定陶戚姬，愛幸，生趙隱王如意。太子為人仁弱，高祖以為不類己，常欲廢之而立如意，「如意類我」。戚姬常從上之關東，日夜啼泣，欲立其子。呂后年長，常留守，希見，益疏。如意且立為趙王，留長安，幾代太子者數。〔一〕賴公卿大臣爭之，及叔孫通諫，用留侯之策，得無易。","sentenceOrder":41},
  {"id":"s_work_han_thu_113_42","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「幾音鉅依反。數音所角反。」","sentenceOrder":42},
  {"id":"s_work_han_thu_113_43","chapterId":"ch_work_han_thu_113","textTraditional":"呂后為人剛毅，佐高帝定天下，兄二人皆為列將，從征伐。長兄澤為周呂侯，次兄釋之為建成侯，逮高祖而侯者三人。高祖四年，臨泗侯呂公薨。","sentenceOrder":43},
  {"id":"s_work_han_thu_113_44","chapterId":"ch_work_han_thu_113","textTraditional":"高祖崩，惠帝立，呂后為皇太后，乃令永巷囚戚夫人，髡鉗衣赭衣，令舂。戚夫人舂且歌曰：「子為王，母為虜，終日舂薄暮，常與死為伍！〔一〕相離三千里，當誰使告女？」〔二〕太后聞之大怒，曰：「乃欲倚女子邪？」〔三〕乃召趙王誅之。使者三反，〔四〕趙相周昌不遣。太后召趙相，相徵至長安。使人復召趙王，王來。惠帝慈仁，知太后怒，自迎趙王霸上，入宮，挾與起居飲食。數月，帝晨出射，趙王不能蚤起，太后伺其獨居，使人持鴆飲之。遲帝還，趙王死。〔五〕太后遂斷戚夫人手足，去眼熏耳，飲瘖藥，〔六〕使居鞠域中，〔七〕名曰「人彘」。居數月，乃召惠帝視「人彘」。帝視而問知其戚夫人，乃大哭，因病，歲餘不能起。使人請太后曰：「此非人所為。臣為太后子，終不能復治天下！」〔八〕以此日飲為淫樂，不聽政，七年而崩。","sentenceOrder":44},
  {"id":"s_work_han_thu_113_45","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「與死罪者為伍也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_113_46","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「女讀曰汝。此下皆同。」","sentenceOrder":46},
  {"id":"s_work_han_thu_113_47","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「乃亦汝。」","sentenceOrder":47},
  {"id":"s_work_han_thu_113_48","chapterId":"ch_work_han_thu_113","textTraditional":"〔四〕　師古曰：「反，還也。三還猶今言三回也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_113_49","chapterId":"ch_work_han_thu_113","textTraditional":"〔五〕　師古曰：「遲音直二反，解在高紀。」","sentenceOrder":49},
  {"id":"s_work_han_thu_113_50","chapterId":"ch_work_han_thu_113","textTraditional":"〔六〕　師古曰：「去其眼精，以藥熏耳令聾也。瘖，不能言也，以瘖藥飲之也。飲音於禁反。瘖音於今反。」","sentenceOrder":50},
  {"id":"s_work_han_thu_113_51","chapterId":"ch_work_han_thu_113","textTraditional":"〔七〕　師古曰：「鞠域，如蹋鞠之域，謂窟室也。鞠音巨六反。」","sentenceOrder":51},
  {"id":"s_work_han_thu_113_52","chapterId":"ch_work_han_thu_113","textTraditional":"〔八〕　師古曰：「令太后視事，己自如太子然。」","sentenceOrder":52},
  {"id":"s_work_han_thu_113_53","chapterId":"ch_work_han_thu_113","textTraditional":"太后發喪，哭而泣不下。〔一〕留侯子張辟彊為侍中，年十五，謂丞相陳平曰：「太后獨有帝，今哭而不悲，君知其解未？」〔二〕陳平曰：「何解？」辟彊曰：「帝無壯子，太后畏君等。今請拜呂台、呂產為將，將兵居南北軍，及諸呂皆官，居中用事。如此則太后心安，君等幸脫禍矣！」〔三〕丞相如辟彊計請之，太后說，其哭乃哀。〔四〕呂氏權由此起。乃立孝惠後宮子為帝，太后臨朝稱制。復殺高祖子趙幽王友、共王恢〔五〕及燕（靈）王建〔子〕。遂立周呂侯子台為呂王，〔六〕台弟產為梁王，建城侯釋之子祿為趙王，台子通為燕王，又封諸呂凡六人皆為列侯，追尊父呂公為呂宣王，兄周呂侯為悼武王。","sentenceOrder":53},
  {"id":"s_work_han_thu_113_54","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「泣謂淚也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_113_55","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「解猶解說其意。」","sentenceOrder":55},
  {"id":"s_work_han_thu_113_56","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「脫，免也。」","sentenceOrder":56},
  {"id":"s_work_han_thu_113_57","chapterId":"ch_work_han_thu_113","textTraditional":"〔四〕　師古曰：「說讀曰悅。」","sentenceOrder":57},
  {"id":"s_work_han_thu_113_58","chapterId":"ch_work_han_thu_113","textTraditional":"〔五〕　師古曰：「共讀曰恭。」","sentenceOrder":58},
  {"id":"s_work_han_thu_113_59","chapterId":"ch_work_han_thu_113","textTraditional":"〔六〕　師古曰：「台音土來反。」","sentenceOrder":59},
  {"id":"s_work_han_thu_113_60","chapterId":"ch_work_han_thu_113","textTraditional":"太后持天下八年，病犬禍而崩，語在五行志。病困，以趙王祿為上將軍居北軍，梁王產為相國居南軍，戒產、祿曰：「高祖與大臣約，非劉氏王者天下共擊之，今王呂氏，大臣不平。我即崩，恐其為變，必據兵衛宮，慎毋送喪，為人所制。」太后崩，太尉周勃、丞相陳平、朱虛侯劉章等共誅產、祿，悉捕諸呂男女，無少長皆斬之。而迎立代王，是為孝文皇帝。","sentenceOrder":60},
  {"id":"s_work_han_thu_113_61","chapterId":"ch_work_han_thu_113","textTraditional":"孝惠張皇后。宣平侯敖尚帝姊魯元公主，有女。惠帝即位，呂太后欲為重親，以公主女配帝為皇后。欲其生子，萬方終無子，乃使陽為有身，取後宮美人子名之，〔一〕殺其母，立所名子為太子。","sentenceOrder":61},
  {"id":"s_work_han_thu_113_62","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「名為皇后子。」","sentenceOrder":62},
  {"id":"s_work_han_thu_113_63","chapterId":"ch_work_han_thu_113","textTraditional":"惠帝崩，太子立為帝，四年，乃自知非皇后子，出言曰：「太后安能殺吾母而名我！我壯即為所為。」〔一〕太后聞而患之，恐其作亂，乃幽之永巷，言帝病甚，左右莫得見。太后下詔廢之，語在高后紀。遂幽死，更立恆山王弘為皇帝，而以呂祿女為皇后。欲連根固本牢甚，〔二〕然而無益也。呂太后崩，大臣正之，卒滅呂氏。少帝恆山、淮南、濟川王，皆以非孝惠子誅。獨置孝惠皇后，廢處北宮〔三〕，孝文後元年薨，葬安陵，不起墳。","sentenceOrder":63},
  {"id":"s_work_han_thu_113_64","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「為其所為，謂所生之母也。並音于偽反。」","sentenceOrder":64},
  {"id":"s_work_han_thu_113_65","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「牢，堅也。」","sentenceOrder":65},
  {"id":"s_work_han_thu_113_66","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「置，留也。北宮，在未央宮之北。」","sentenceOrder":66},
  {"id":"s_work_han_thu_113_67","chapterId":"ch_work_han_thu_113","textTraditional":"高祖薄姬，文帝母也。父吳人，秦時與故魏王宗女魏媼通，生薄姬。而薄姬父死山陰，因葬焉。〔一〕及諸侯畔秦，魏豹立為王，而魏媼內其女於魏宮。許負相薄姬，當生天子。是時項羽方與漢王相距滎陽，天下未有所定。豹初與漢擊楚，及聞許負言，心喜，因背漢而中立，與楚連和。〔二〕漢使曹參等虜魏王豹，以其國為郡，而薄姬輸織室。豹已死，漢王入織室，見薄姬，有詔內後宮，歲餘不得幸。","sentenceOrder":67},
  {"id":"s_work_han_thu_113_68","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「山陰，會稽之縣。」","sentenceOrder":68},
  {"id":"s_work_han_thu_113_69","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「自謂當得天下。」","sentenceOrder":69},
  {"id":"s_work_han_thu_113_70","chapterId":"ch_work_han_thu_113","textTraditional":"始姬少時，與管夫人、趙子兒相愛，約曰：「先貴毋相忘！」已而管夫人、趙子兒先幸漢王。漢王四年，坐河南成皋靈臺，此兩美人侍，相與笑薄姬初時約。漢王問其故，兩人俱以實告。漢王心悽然憐薄姬，是日召欲幸之。對曰：「昨暮夢龍據妾胸。」上曰：「是貴徵也，吾為汝成之。」遂幸，有身。歲中生文帝，年八歲立為代王。自有子後，希見。高祖崩，諸幸姬戚夫人之屬，呂后怒，皆幽之不得出宮。而薄姬以希見故，得出從子之代，為代太后。太后弟薄昭從如代。〔一〕","sentenceOrder":70},
  {"id":"s_work_han_thu_113_71","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「如，往也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_113_72","chapterId":"ch_work_han_thu_113","textTraditional":"代王立十七年，高后崩。大臣議立後，疾外家呂氏彊暴，皆稱薄氏仁善，故迎立代王為皇帝，尊太后為皇太后，封弟昭為軹侯。〔一〕太后母亦前死，葬櫟陽北。乃追尊太后父為靈文侯，會稽郡致園邑三百家，長丞以下使奉守寢廟，上食祠如法。櫟陽亦置靈文夫人園，令如靈文侯園儀。太后蚤失父，其奉太后外家魏氏有力，〔二〕乃召復魏氏，〔三〕賞賜各以親疏受之。薄氏侯者一人。","sentenceOrder":72},
  {"id":"s_work_han_thu_113_73","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「軹音只。」","sentenceOrder":73},
  {"id":"s_work_han_thu_113_74","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「言太后為外家所養也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_113_75","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「優復之也。復音方目反。」","sentenceOrder":75},
  {"id":"s_work_han_thu_113_76","chapterId":"ch_work_han_thu_113","textTraditional":"太后後文帝二歲，孝景前二年崩，〔一〕葬南陵。〔二〕用呂后不合葬長陵，〔三〕故特自起陵，近文帝。","sentenceOrder":76},
  {"id":"s_work_han_thu_113_77","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「言文帝崩後二歲，太后乃崩。」","sentenceOrder":77},
  {"id":"s_work_han_thu_113_78","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「薄太后陵在霸陵之南，故稱南陵，即今所謂薄陵。」","sentenceOrder":78},
  {"id":"s_work_han_thu_113_79","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「以呂后是正嫡，故薄不得合葬也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_113_80","chapterId":"ch_work_han_thu_113","textTraditional":"孝文竇皇后，景帝母也，呂太后時以良家子選入宮。太后出宮人以賜諸王各五人，竇姬與在行中。〔一〕家在清河，願如趙，近家，〔二〕請其主遣宦者吏「必置我籍趙之伍乃」。〔三〕宦者忘之，誤置籍代伍中。籍奏，詔可。當行，竇姬涕泣，怨其宦者，不欲往，相彊乃肯行。至代，代王獨幸竇姬，生女嫖。〔四〕孝惠七年，生景帝。","sentenceOrder":80},
  {"id":"s_work_han_thu_113_81","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「與讀曰豫。」","sentenceOrder":81},
  {"id":"s_work_han_thu_113_82","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「如，往也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_113_83","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「主遣宦者吏，謂宦者為吏而主發遣宮人者也。籍謂名簿也。伍猶列也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_113_84","chapterId":"ch_work_han_thu_113","textTraditional":"〔四〕　師古曰：「嫖音匹昭反。」","sentenceOrder":84},
  {"id":"s_work_han_thu_113_85","chapterId":"ch_work_han_thu_113","textTraditional":"代王王后生四男，先代王未入立為帝而王后卒，及代王為帝後，王后所生四男更病死。〔一〕文帝立數月，公卿請立太子，而竇姬男最長，立為太子。竇姬為皇后，女為館陶長公主。〔二〕明年，封少子武為代王，後徙梁，〔三〕是為梁孝王。","sentenceOrder":85},
  {"id":"s_work_han_thu_113_86","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「更，互也，音公衡反。」","sentenceOrder":86},
  {"id":"s_work_han_thu_113_87","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「年最長，故謂長公主。」","sentenceOrder":87},
  {"id":"s_work_han_thu_113_88","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「初封代王，後更為梁王。」","sentenceOrder":88},
  {"id":"s_work_han_thu_113_89","chapterId":"ch_work_han_thu_113","textTraditional":"竇皇后親蚤卒，葬觀津。〔一〕於是薄太后乃詔有司追封竇后父為安成侯，母曰安成夫人，令清河置園邑二百家，長丞奉守，比靈文園法。","sentenceOrder":89},
  {"id":"s_work_han_thu_113_90","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「觀津，清河之縣也。觀音工喚反。」","sentenceOrder":90},
  {"id":"s_work_han_thu_113_91","chapterId":"ch_work_han_thu_113","textTraditional":"竇后兄長君。弟廣國字少君，年四五歲時，家貧，為人所略賣，其家不知處。傳十餘家至宜陽，為其主人入山作炭。暮臥岸下百餘人，岸崩，盡厭殺臥者，〔一〕少君獨脫不死。〔二〕自卜，數日當為侯。從其家之長安，〔三〕聞皇后新立，家在觀津，姓竇氏。廣國去時雖少，識其縣名及姓，又嘗與其姊采桑，墮，〔四〕用為符信，上書自陳。皇后言帝，召見問之，具言其故，果是。復問其所識，〔五〕曰：「姊去我西時，與我決傳舍中，匄沐沐我，已，飯我，乃去。」〔六〕於是竇皇后持之而泣，侍御左右皆悲。乃厚賜之，家於長安。絳侯、灌將軍等曰：「吾屬不死，命乃且縣此兩人。〔七〕此兩人所出微，不可不為擇師傅，又復放呂氏大事也。」〔八〕於是乃選長者之有節行者與居。竇長君、少君由此為退讓君子，不敢以富貴驕人。","sentenceOrder":91},
  {"id":"s_work_han_thu_113_92","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「厭音一甲反。」","sentenceOrder":92},
  {"id":"s_work_han_thu_113_93","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「脫，免也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_113_94","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「從其主家也。之，往也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_113_95","chapterId":"ch_work_han_thu_113","textTraditional":"〔四〕　師古曰：「墮謂墮樹。」","sentenceOrder":95},
  {"id":"s_work_han_thu_113_96","chapterId":"ch_work_han_thu_113","textTraditional":"〔五〕　師古曰：「識，記也，音式志反。」","sentenceOrder":96},
  {"id":"s_work_han_thu_113_97","chapterId":"ch_work_han_thu_113","textTraditional":"〔六〕　師古曰：「乞沐具而為之沐，沐訖又飯食之也。飯音扶晚反。」","sentenceOrder":97},
  {"id":"s_work_han_thu_113_98","chapterId":"ch_work_han_thu_113","textTraditional":"〔七〕　師古曰：「恐其後擅權，則將相大臣當被害。」","sentenceOrder":98},
  {"id":"s_work_han_thu_113_99","chapterId":"ch_work_han_thu_113","textTraditional":"〔八〕　師古曰：「放音甫往反。」","sentenceOrder":99},
  {"id":"s_work_han_thu_113_100","chapterId":"ch_work_han_thu_113","textTraditional":"竇皇后疾，失明。文帝幸邯鄲慎夫人、尹姬，皆無子。文帝崩，景帝立，皇后為皇太后，乃封廣國為章武侯。長君先死，封其子彭祖為南皮侯。吳楚反時，太后從昆弟子竇嬰俠，喜士，〔一〕為大將軍，破吳楚，封魏其侯。竇氏侯者凡三人。","sentenceOrder":100},
  {"id":"s_work_han_thu_113_101","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「喜音許吏反。」","sentenceOrder":101},
  {"id":"s_work_han_thu_113_102","chapterId":"ch_work_han_thu_113","textTraditional":"竇太后好黃帝、老子言，景帝及諸竇不得不讀老子尊其術。太后後景帝六歲，凡立五十一年，元光六年崩，〔一〕合葬霸陵。遺詔盡以東宮金錢財物賜長公主嫖。〔二〕至武帝時，魏其侯竇嬰為丞相，後誅。","sentenceOrder":102},
  {"id":"s_work_han_thu_113_103","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「武紀建元六年，太皇太后崩。此傳云後景帝六歲是也。而以建元為元光，則是參錯。又當言凡立四十五年，而云五十一。再三乖謬，皆是此傳誤。」","sentenceOrder":103},
  {"id":"s_work_han_thu_113_104","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「東宮，太后所居。」","sentenceOrder":104},
  {"id":"s_work_han_thu_113_105","chapterId":"ch_work_han_thu_113","textTraditional":"孝景薄皇后，孝文薄太后家女也。景帝為太子時，薄太后取以為太子妃。景帝立，立薄妃為皇后，無子無寵。立六年，薄太后崩，皇后廢。廢後四年薨，葬長安城東平望亭南。","sentenceOrder":105},
  {"id":"s_work_han_thu_113_106","chapterId":"ch_work_han_thu_113","textTraditional":"孝景王皇后，武帝母也。父王仲，槐里人也。母臧兒，故燕王臧荼孫也，為仲妻，生男信與兩女。而仲死，臧兒更嫁為長陵田氏婦，生男蚡、勝。臧兒長女嫁為金王孫婦，生一女矣，而臧兒卜筮曰兩女當貴，欲倚兩女，〔一〕奪金氏。金氏怒，不肯與決，乃內太子宮。太子幸愛之，生三女一男。男方在身時，王夫人夢日入其懷，以告太子，太子曰：「此貴徵也。」未生而文帝崩，景帝即位，王夫人生男。是時，薄皇后無子。後數歲，景帝立齊栗姬男為太子，而王夫人男為膠東王。","sentenceOrder":106},
  {"id":"s_work_han_thu_113_107","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「冀其貴而依倚之得尊寵也。倚音於綺反。」","sentenceOrder":107},
  {"id":"s_work_han_thu_113_108","chapterId":"ch_work_han_thu_113","textTraditional":"長公主嫖有女，欲與太子為妃，栗姬妒，而景帝諸美人皆因長公主見得貴幸，栗姬日怨怒，謝長主，不許。長主欲與王夫人，王夫人許之。會薄皇后廢，長公主日譖栗姬短。景帝嘗屬諸姬子，〔一〕曰：「吾百歲後，善視之。」栗姬怒不肯應，言不遜，景帝心銜之而未發也。","sentenceOrder":108},
  {"id":"s_work_han_thu_113_109","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「諸姬子，諸姬所生之子也。屬音之欲反。此下皆同。」","sentenceOrder":109},
  {"id":"s_work_han_thu_113_110","chapterId":"ch_work_han_thu_113","textTraditional":"長公主日譽王夫人男之美，帝亦自賢之。又耳曩者所夢日符〔一〕，計未有所定。王夫人又陰使人趣大臣立栗姬為皇后。〔二〕大行奏事，文曰：「『子以母貴，母以子貴。』今太子母號宜為皇后。」帝怒曰：「是乃所當言邪！」〔三〕遂案誅大行，而廢太子為臨江王。栗姬愈恚，不得見，以憂死。卒立王夫人為皇后，〔四〕男為太子。封皇后兄信為蓋侯。","sentenceOrder":110},
  {"id":"s_work_han_thu_113_111","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「耳常聽聞而記之也。符猶瑞應。」","sentenceOrder":111},
  {"id":"s_work_han_thu_113_112","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「趣音曰促。」","sentenceOrder":112},
  {"id":"s_work_han_thu_113_113","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「乃，汝也。言此事非汝所當得言。」","sentenceOrder":113},
  {"id":"s_work_han_thu_113_114","chapterId":"ch_work_han_thu_113","textTraditional":"〔四〕　師古曰：「卒，終也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_113_115","chapterId":"ch_work_han_thu_113","textTraditional":"初，皇后始入太子家，後女弟兒姁亦復入，〔一〕生四男。兒姁蚤卒，四子皆為王。〔二〕皇后長女為平陽公主，次南宮公主，次隆慮公主。〔三〕","sentenceOrder":115},
  {"id":"s_work_han_thu_113_116","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「姁音許于反。諸婦人之名字，音皆同。」","sentenceOrder":116},
  {"id":"s_work_han_thu_113_117","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「謂廣川惠王越，膠東康王寄，清河哀王乘，常山憲王舜。」","sentenceOrder":117},
  {"id":"s_work_han_thu_113_118","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「慮音廬。」","sentenceOrder":118},
  {"id":"s_work_han_thu_113_119","chapterId":"ch_work_han_thu_113","textTraditional":"皇后立九年，景帝崩。武帝即位，為皇太后，尊太后母臧兒為平原君，封田蚡為武安侯，勝為周陽侯。王氏、田氏侯者凡三人。蓋侯信好酒，田蚡、勝貪，巧於文辭。蚡至丞相，追尊王仲為共侯，〔一〕槐里起園邑二百家，長丞奉守。及平原君薨，從田氏葬長陵，亦置園邑如共侯法。","sentenceOrder":119},
  {"id":"s_work_han_thu_113_120","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「共讀曰恭。」","sentenceOrder":120},
  {"id":"s_work_han_thu_113_121","chapterId":"ch_work_han_thu_113","textTraditional":"初，皇太后微時所（謂）〔為〕金王孫生女俗，在民間，蓋諱之也。〔一〕武帝始立，韓嫣白之。〔二〕帝曰：「何為不蚤言？」乃車駕自往迎之。其家在長陵小市，直至其門，使左右入求之。家人驚恐，女逃匿。扶將出拜，帝下車立曰：「大姊，何藏之深也？」載至長樂宮，與俱謁太后，太后垂涕，女亦悲泣。帝奉酒，前為壽。錢千萬，奴婢三百人，公田百頃，甲第，以賜姊。太后謝曰：「為帝費。」因賜湯沐邑，號修成君。男女各一人，女嫁諸侯，男號修成子仲，以太后故，橫於京師。〔三〕太后凡立二十五年，後景帝十五歲，元朔三年崩，合葬陽陵。","sentenceOrder":121},
  {"id":"s_work_han_thu_113_122","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「言隨流俗而在閭巷，未顯貴。」","sentenceOrder":122},
  {"id":"s_work_han_thu_113_123","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「嫣音偃。」","sentenceOrder":123},
  {"id":"s_work_han_thu_113_124","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「橫音胡孟反。」","sentenceOrder":124},
  {"id":"s_work_han_thu_113_125","chapterId":"ch_work_han_thu_113","textTraditional":"孝武陳皇后，長公主嫖女也。曾祖父陳嬰與項羽俱起，後歸漢，為堂邑侯。傳子至孫午，午尚長公主，生女。","sentenceOrder":125},
  {"id":"s_work_han_thu_113_126","chapterId":"ch_work_han_thu_113","textTraditional":"初，武帝得立為太子，長主有力，取主女為妃。及帝即位，立為皇后，擅寵驕貴，十餘年而無子，聞衛子夫得幸，幾死者數焉。〔一〕上愈怒。后又挾婦人媚道，頗覺。元光五年，上遂窮治之，女子楚服等坐為皇后巫蠱祠祭祝詛，大逆無道，相連及誅者三百餘人。楚服梟首於市。使有司賜皇后策曰：「皇后失序，惑於巫祝，〔二〕不可以承天命。其上璽綬，罷退居長門宮。」","sentenceOrder":126},
  {"id":"s_work_han_thu_113_127","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「幾音鉅依反。數音所角反。」","sentenceOrder":127},
  {"id":"s_work_han_thu_113_128","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「言失德義之序，而妄祝詛也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_113_129","chapterId":"ch_work_han_thu_113","textTraditional":"明年，堂邑侯午薨，主男須嗣侯。主寡居，私近董偃。十餘年，主薨。須坐淫亂，兄弟爭財，當死，自殺，國除。後數年，廢后乃薨，葬霸陵郎官亭東。","sentenceOrder":129},
  {"id":"s_work_han_thu_113_130","chapterId":"ch_work_han_thu_113","textTraditional":"孝武衛皇后字子夫，生微也。其家號曰衛氏，出平陽侯邑。子夫為平陽主謳者。〔一〕武帝即位，數年無子。平陽主求良家女十餘人，飾置家。帝祓霸上，〔二〕還過平陽主。主見所偫美人，〔三〕帝不說。既飲，謳者進，帝獨說子夫。〔四〕帝起更衣，子夫侍尚衣〔五〕軒中，得幸。〔六〕還坐驩甚，賜平陽主金千斤。主因奏子夫送入宮。子夫上車，主拊其背曰：「行矣！〔七〕強飯勉之。〔八〕即貴，願無相忘！」入宮歲餘，不復幸。武帝擇宮人不中用者斥出之，子夫得見，涕泣請出。上憐之，復幸，遂有身，尊寵。召其兄衛長君、弟青侍中。而子夫生三女，元朔元年生男據，遂立為皇后。","sentenceOrder":130},
  {"id":"s_work_han_thu_113_131","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「齊歌曰謳，音一侯反。」","sentenceOrder":131},
  {"id":"s_work_han_thu_113_132","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　孟康曰：「祓，除也。於霸水上自祓除，今三月上巳祓禊也。」師古曰：「祓音廢。禊音系。」","sentenceOrder":132},
  {"id":"s_work_han_thu_113_133","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「偫，儲偫也。偫音丈紀反。」","sentenceOrder":133},
  {"id":"s_work_han_thu_113_134","chapterId":"ch_work_han_thu_113","textTraditional":"〔四〕　師古曰：「說皆讀曰悅。」","sentenceOrder":134},
  {"id":"s_work_han_thu_113_135","chapterId":"ch_work_han_thu_113","textTraditional":"〔五〕　如淳曰：「以帷帳障尊者也。」晉灼曰：「代侍五尚之衣。」師古曰：「二說皆非也。尚，主也。時於軒中侍帝，權主衣裳。」","sentenceOrder":135},
  {"id":"s_work_han_thu_113_136","chapterId":"ch_work_han_thu_113","textTraditional":"〔六〕　師古曰：「軒謂軒車，即今車之施幰者。」","sentenceOrder":136},
  {"id":"s_work_han_thu_113_137","chapterId":"ch_work_han_thu_113","textTraditional":"〔七〕　師古曰：「拊謂摩循之也。行矣，猶今言好去。」","sentenceOrder":137},
  {"id":"s_work_han_thu_113_138","chapterId":"ch_work_han_thu_113","textTraditional":"〔八〕　師古曰：「強音其兩反。飯音扶晚反。」","sentenceOrder":138},
  {"id":"s_work_han_thu_113_139","chapterId":"ch_work_han_thu_113","textTraditional":"先是衛長君死，乃以青為將軍，擊匈奴有功，封長平侯。青三子（皆）〔在〕襁褓中，皆為列侯。及皇后姊子霍去病亦以軍功為冠軍侯，至大司馬票騎將軍。青為大司馬大將軍。衛氏支屬侯者五人。青還，尚平陽主。","sentenceOrder":139},
  {"id":"s_work_han_thu_113_140","chapterId":"ch_work_han_thu_113","textTraditional":"皇后立七年，而男立為太子。後色衰，趙之王夫人、中山李夫人有寵，皆蚤卒。後有尹婕妤、鉤弋夫人更幸。〔一〕衛后立三十八年，遭巫蠱事起，江充為姦，太子懼不能自明，遂與皇后共誅充，發兵，兵敗，太子亡走。詔遣宗正劉長樂、執金吾劉敢奉策收皇后璽綬，自殺。黃門蘇文、姚定漢輿置公車令空舍，盛以小棺，瘞之城南桐柏。〔二〕衛氏悉滅。宣帝立，及改葬衛后，追諡曰思后，置園邑三百家，長丞周衛奉守焉。〔三〕","sentenceOrder":140},
  {"id":"s_work_han_thu_113_141","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「更，互也，音工衡反。」","sentenceOrder":141},
  {"id":"s_work_han_thu_113_142","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「瘞，薶也。桐柏，亭名也。瘞音於例反。」","sentenceOrder":142},
  {"id":"s_work_han_thu_113_143","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「葬在杜門外大道東，以倡優雜伎千人樂其園，故號千人聚。其地在今長安城內金城坊西北隅是。」","sentenceOrder":143},
  {"id":"s_work_han_thu_113_144","chapterId":"ch_work_han_thu_113","textTraditional":"孝武李夫人，本以倡進。〔一〕初，夫人兄延年性知音，善歌舞，武帝愛之。每為新聲變曲，聞者莫不感動。延年侍上起舞，歌曰：「北方有佳人，絕世而獨立，一顧傾人城，再顧傾人國。寧不知傾城與傾國，佳人難再得！」〔二〕上嘆息曰：「善！世豈有此人乎？」平陽主因言延年有女弟，上乃召見之，實妙麗善舞。由是得幸，生一男，是為昌邑哀王。李夫人少而蚤卒，上憐閔焉，圖畫其形於甘泉宮。及衛思后廢後四年，武帝崩，大將軍霍光緣上雅意，以李夫人配食，〔三〕追上尊號曰孝武皇后。","sentenceOrder":144},
  {"id":"s_work_han_thu_113_145","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「倡，樂人，音昌。」","sentenceOrder":145},
  {"id":"s_work_han_thu_113_146","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「非不〈恡，去“忄”〉惜城與國也，但以佳人難得，愛悅之深，不覺傾覆。」","sentenceOrder":146},
  {"id":"s_work_han_thu_113_147","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「緣，因也。雅意，素舊之意。」","sentenceOrder":147},
  {"id":"s_work_han_thu_113_148","chapterId":"ch_work_han_thu_113","textTraditional":"初，李夫人病篤，上自臨候之，夫人蒙被謝曰：「妾久寢病，形貌毀壞，不可以見帝。願以王及兄弟為託。」上曰：「夫人病甚，殆將不起，一見我屬託王及兄弟，豈不快哉？」夫人曰：「婦人貌不修飾，不見君父。妾不敢以燕惰見帝。」〔一〕上曰：「夫人弟一見我，〔二〕將加賜千金，而予兄弟尊官。」夫人曰：「尊官在帝，不在一見。」上復言欲必見之，夫人遂轉鄉歔欷而不復言。〔三〕於是上不說而起。〔四〕夫人姊妹讓之曰：〔五〕「貴人獨不可一見上屬託兄弟邪？何為恨上如此？」夫人曰：「所以不欲見帝者，乃欲以深託兄弟也。我以容貌之好，得從微賤愛幸於上。夫以色事人者，色衰而愛弛，〔六〕愛弛則恩絕。上所以攣攣顧念我者，乃以平生容貌也。〔七〕今見我毀壞，顏色非故，必畏惡吐棄我，意尚肯復追思閔錄其兄弟哉！」及夫人卒，上以后禮葬焉。其後，上以夫人兄李廣利為貳師將軍，封海西侯，延年為協律都尉。","sentenceOrder":148},
  {"id":"s_work_han_thu_113_149","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「媠與惰同。謂不嚴飾。」","sentenceOrder":149},
  {"id":"s_work_han_thu_113_150","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「弟，但也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_113_151","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「鄉讀曰嚮，轉面而嚮裏也。歔音虛。欷音許既反。」","sentenceOrder":151},
  {"id":"s_work_han_thu_113_152","chapterId":"ch_work_han_thu_113","textTraditional":"〔四〕　師古曰：「說讀曰悅。」","sentenceOrder":152},
  {"id":"s_work_han_thu_113_153","chapterId":"ch_work_han_thu_113","textTraditional":"〔五〕　師古曰：「讓，責也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_113_154","chapterId":"ch_work_han_thu_113","textTraditional":"〔六〕　師古曰：「弛，解也，音式爾反。」","sentenceOrder":154},
  {"id":"s_work_han_thu_113_155","chapterId":"ch_work_han_thu_113","textTraditional":"〔七〕　師古曰：「攣音力全反，又讀曰戀。」","sentenceOrder":155},
  {"id":"s_work_han_thu_113_156","chapterId":"ch_work_han_thu_113","textTraditional":"上思念李夫人不已，方士齊人少翁言能致其神。乃夜張燈燭，設帷帳，陳酒肉，而令上居他帳，遙望好女如李夫人之貌，還幄坐而步。〔一〕又不得就視，上愈益相思悲感，為作詩曰：「是邪，非邪？〔二〕立而望之，偏何姍姍其來遲！」〔三〕令樂府諸音家絃歌之。上又自為作賦，以傷悼夫人，其辭曰：","sentenceOrder":156},
  {"id":"s_work_han_thu_113_157","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「夫人之神於幄中坐，又出而徐步。」","sentenceOrder":157},
  {"id":"s_work_han_thu_113_158","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「言所見之狀定是夫人以否。」","sentenceOrder":158},
  {"id":"s_work_han_thu_113_159","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「姍姍，行貌，音先安反。」","sentenceOrder":159},
  {"id":"s_work_han_thu_113_160","chapterId":"ch_work_han_thu_113","textTraditional":"美連娟以脩嫮兮，〔一〕命樔絕而不長，〔二〕飾新宮以延貯兮，泯不歸乎故鄉。〔三〕慘鬱鬱其蕪穢兮，隱處幽而懷傷，釋輿馬於山椒兮，奄修夜之不陽。〔四〕秋氣（潛）〔憯〕以淒淚兮，桂枝落而銷亡，〔五〕神煢煢以遙思兮，精浮游而出畺。託沈陰以壙久兮，惜蕃華之未央，〔六〕念窮極之不還兮，惟幼眇之相羊。〔七〕函荾荴以俟風兮，芳雜襲以彌章，〔八〕的容與以猗靡兮，縹飄姚虖愈莊。〔九〕燕淫衍而撫楹兮，連流視而娥揚，〔一０〕既激感而心逐兮，包紅顏而弗明。〔一一〕驩接狎以離別兮，宵寤夢之芒芒〔一二〕，忽遷化而不反兮，魄放逸以飛揚。何靈魂之紛紛兮，哀裴回以躊躇，〔一三〕勢路日以遠兮，遂荒忽而辭去。〔一四〕超兮西征，屑兮不見。〔一五〕寢淫敞{艹兄}，寂兮無音，〔一六〕思若流波，怛兮在心。〔一七〕","sentenceOrder":160},
  {"id":"s_work_han_thu_113_161","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「嫮，美也。連娟，纖弱也。嫮音互。娟音一全反。」","sentenceOrder":161},
  {"id":"s_work_han_thu_113_162","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「樔，截也，音子小反。」","sentenceOrder":162},
  {"id":"s_work_han_thu_113_163","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「新宮，待神之處。貯與佇同。佇，待也。泯然，滅絕意。」","sentenceOrder":163},
  {"id":"s_work_han_thu_113_164","chapterId":"ch_work_han_thu_113","textTraditional":"〔四〕　孟康曰：「山椒，山陵也，置輿馬於山陵也。」師古曰：「自慘鬱鬱以下，皆言夫人身處墳墓而隱翳也。修，長也。陽，明也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_113_165","chapterId":"ch_work_han_thu_113","textTraditional":"〔五〕　師古曰：「淒淚，寒涼之意也。桂枝芳香，亦喻夫人也。憯音千感反。淚音戾。」","sentenceOrder":165},
  {"id":"s_work_han_thu_113_166","chapterId":"ch_work_han_thu_113","textTraditional":"〔六〕　師古曰：「沈陰，言在地下也。壙與曠同。未央猶未半也。言年歲未半，而早落蕃華，故痛惜之。蕃音扶元反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_113_167","chapterId":"ch_work_han_thu_113","textTraditional":"〔七〕　師古曰：「惟，思也。幼眇猶窈窕也。相羊，翱翔也。幼音一小反。相音襄。」","sentenceOrder":167},
  {"id":"s_work_han_thu_113_168","chapterId":"ch_work_han_thu_113","textTraditional":"〔八〕　李奇曰：「荴音敷。」孟康曰：「荾音綏，華中齊也。夫人之色如春華含荾敷散，以待風也。」師古曰：「雜襲，重積也。」","sentenceOrder":168},
  {"id":"s_work_han_thu_113_169","chapterId":"ch_work_han_thu_113","textTraditional":"〔九〕　孟康曰：「言夫人之顏色的然盛美，雖在風中縹姚，愈益端嚴也。」師古曰：「縹音匹妙反。」","sentenceOrder":169},
  {"id":"s_work_han_thu_113_170","chapterId":"ch_work_han_thu_113","textTraditional":"〔一０〕師古曰：「追述平生歡宴之時也。娥揚，揚其娥眉。」","sentenceOrder":170},
  {"id":"s_work_han_thu_113_171","chapterId":"ch_work_han_thu_113","textTraditional":"〔一一〕晉灼曰：「包，藏也。謂夫人藏其顏色，不肯見帝屬其家室也。」師古曰：「此說非也。　心逐者，帝自言中心追逐夫人不能已也。包紅顏者，言在墳墓之中不可見也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_113_172","chapterId":"ch_work_han_thu_113","textTraditional":"〔一二〕師古曰：「言絕接狎之驩，而遂離別也。宵，夜也。芒芒，無知之貌也。芒音莫郎反。」","sentenceOrder":172},
  {"id":"s_work_han_thu_113_173","chapterId":"ch_work_han_thu_113","textTraditional":"〔一三〕師古曰：「躊躇，住足也。躊音疇。躇合韻音丈預反。」","sentenceOrder":173},
  {"id":"s_work_han_thu_113_174","chapterId":"ch_work_han_thu_113","textTraditional":"〔一四〕師古曰：「荒音呼廣反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_113_175","chapterId":"ch_work_han_thu_113","textTraditional":"〔一五〕師古曰：「屑然，疾意也。以日為喻，故言西征。」","sentenceOrder":175},
  {"id":"s_work_han_thu_113_176","chapterId":"ch_work_han_thu_113","textTraditional":"〔一六〕師古曰：「{艹兄}，古怳字。」","sentenceOrder":176},
  {"id":"s_work_han_thu_113_177","chapterId":"ch_work_han_thu_113","textTraditional":"〔一七〕師古曰：「流波，言恩寵不絕也。怛，悼也，音丁曷反。」","sentenceOrder":177},
  {"id":"s_work_han_thu_113_178","chapterId":"ch_work_han_thu_113","textTraditional":"亂曰：〔一〕佳俠函光，隕朱榮兮，〔二〕嫉妒闟（葺）〔茸〕，將安程兮！〔三〕方時隆盛，年夭傷兮，〔四〕弟子增欷，洿沬悵兮。〔五〕悲愁於邑，喧不可止兮。〔六〕嚮不虛應，亦云己兮。〔七〕嫶妍太息，嘆稚子兮，〔八〕懰慄不言，倚所恃兮。〔九〕仁者不誓，豈約親兮？〔一０〕既往不來，申以信兮。〔一一〕去彼昭昭，就冥冥兮，既下新宮，不復故庭兮。〔一二〕嗚呼哀哉，想魂靈兮！","sentenceOrder":178},
  {"id":"s_work_han_thu_113_179","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「亂，理也，總理賦中之意。」","sentenceOrder":179},
  {"id":"s_work_han_thu_113_180","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　孟康曰：「佳俠猶佳麗。」","sentenceOrder":180},
  {"id":"s_work_han_thu_113_181","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「言嫉妒闟茸之徒不足與夫人為程品也。闟茸，眾賤之稱也。闟音吐獵反。茸音人勇反。」","sentenceOrder":181},
  {"id":"s_work_han_thu_113_182","chapterId":"ch_work_han_thu_113","textTraditional":"〔四〕　師古曰：「傷合韻音式向反。」","sentenceOrder":182},
  {"id":"s_work_han_thu_113_183","chapterId":"ch_work_han_thu_113","textTraditional":"〔五〕　應劭曰：「弟，夫人弟兄也。子，昌邑王也。」孟康曰：「洿沬，涕洟也。」晉灼曰：「沬音水沬面之沬。言涕淚洿集覆面下也。」師古曰：「沬，晉說是也。悵，惆悵也。洿音烏。洿，下也。沬音呼內反，字從午未之未也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_113_184","chapterId":"ch_work_han_thu_113","textTraditional":"〔六〕　師古曰：「朝鮮之間謂小兒泣不止名為喧，音許遠反。」","sentenceOrder":184},
  {"id":"s_work_han_thu_113_185","chapterId":"ch_work_han_thu_113","textTraditional":"〔七〕　師古曰：「嚮讀曰響。響之隨聲，必當有應，而今涕泣（從）〔徒〕自已耳，夫人不知之，是虛其應。」","sentenceOrder":185},
  {"id":"s_work_han_thu_113_186","chapterId":"ch_work_han_thu_113","textTraditional":"〔八〕　孟康曰：「夫人蒙被，歔欷不見，帝哀其子小而孤也。」晉灼曰：「三輔謂憂愁面省瘦曰嫶冥。嫶冥猶嫶妍也。」師古曰：「嫶音在消反。」","sentenceOrder":186},
  {"id":"s_work_han_thu_113_187","chapterId":"ch_work_han_thu_113","textTraditional":"〔九〕　孟康曰：「恃平日之恩，知上必感念之也。」師古曰：「懰慄，哀愴之意也。懰音劉。慄音栗。」","sentenceOrder":187},
  {"id":"s_work_han_thu_113_188","chapterId":"ch_work_han_thu_113","textTraditional":"〔一０〕如淳曰：「仁者之行惠尚一不以為恩施，豈有親親而反當以言約乎？」","sentenceOrder":188},
  {"id":"s_work_han_thu_113_189","chapterId":"ch_work_han_thu_113","textTraditional":"〔一一〕師古曰：「死者一往不返，情念酷痛，重以此心為信，不有忽忘也。信合韻音新。」","sentenceOrder":189},
  {"id":"s_work_han_thu_113_190","chapterId":"ch_work_han_thu_113","textTraditional":"〔一二〕師古曰：「故庭謂平生所居室之庭也。復音扶目反。」","sentenceOrder":190},
  {"id":"s_work_han_thu_113_191","chapterId":"ch_work_han_thu_113","textTraditional":"其後李延年弟季坐姦亂後宮，廣利降匈奴，家族滅矣。","sentenceOrder":191},
  {"id":"s_work_han_thu_113_192","chapterId":"ch_work_han_thu_113","textTraditional":"孝武鉤弋趙婕妤，昭帝母也，家在河間。武帝巡狩過河間，望氣者言此有奇女，天子亟使使召之。既至，女兩手皆拳，上自披之，手即時伸。由是得幸，號曰拳夫人。先是其父坐法宮刑，為中黃門，死長安，葬雍門。〔一〕","sentenceOrder":192},
  {"id":"s_work_han_thu_113_193","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「雍門在長安西北孝里西南，去長安三十里。廣記云趙父冢在門西也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_113_194","chapterId":"ch_work_han_thu_113","textTraditional":"拳夫人進為婕妤，居鉤弋宮，〔一〕大有寵，（元）〔太〕始三年生昭帝，號鉤弋子。任身十四月乃生，上曰：「聞昔堯十四月而生，今鉤弋亦然。」乃命其所生門曰堯母門。後衛太子敗，而燕王旦、廣陵王胥多過失，寵姬王夫人男齊懷王、李夫人男昌邑哀王皆蚤薨，鉤弋子年五六歲，壯大多知，〔二〕上常言「類我」，又感其生與眾異，甚奇愛之，心欲立焉，以其年稚母少，恐女主顓恣亂國家，猶與久之。〔三〕","sentenceOrder":194},
  {"id":"s_work_han_thu_113_195","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「黃圖鉤弋宮在城外，漢武故事曰在直門南也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_113_196","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「壯大者，言其形體偉大。」","sentenceOrder":196},
  {"id":"s_work_han_thu_113_197","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「與讀曰豫。」","sentenceOrder":197},
  {"id":"s_work_han_thu_113_198","chapterId":"ch_work_han_thu_113","textTraditional":"鉤弋婕妤從幸甘泉，有過見譴，以憂死，〔一〕因葬雲陽。〔二〕後上疾病，乃立鉤弋子為皇太子。拜奉車都尉霍光為大司馬大將軍，輔少主。明日，帝崩。昭帝即位，追尊鉤弋婕妤為皇太后，發卒二萬人起雲陵，邑三千戶。追尊外祖趙父為順成侯，詔右扶風置園邑二百家，長丞奉守如法。順成侯有姊君姁，賜錢二百萬，奴婢第宅以充實焉。諸昆弟各以親疏受賞賜。趙氏無在位者，唯趙父追封。","sentenceOrder":198},
  {"id":"s_work_han_thu_113_199","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「譴，責也，音口羨反。」","sentenceOrder":199},
  {"id":"s_work_han_thu_113_200","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「在甘泉宮南，今土俗人嘑為女陵。」","sentenceOrder":200},
  {"id":"s_work_han_thu_113_201","chapterId":"ch_work_han_thu_113","textTraditional":"孝昭上官皇后。祖父桀，隴西上邽人也。少時為羽林期門郎，從武帝上甘泉，天大風，車不得行，解蓋授桀。桀奉蓋，雖風常屬車；〔一〕雨下，蓋輒御。上奇其材力，遷未央廄令。上嘗體不安，及愈，見馬，〔二〕馬多瘦，上大怒：「令以我不復見馬邪！」欲下吏，桀頓首曰：「臣聞聖體不安，日夜憂懼，意誠不在馬。」〔三〕言未卒，泣數行下。上以為忠，由是親近，為侍中，稍遷至太僕。武帝疾病，以霍光為大將軍，太僕桀為左將軍，皆受遺詔輔少主。以前捕斬反者莽通功，封桀為安陽侯。","sentenceOrder":201},
  {"id":"s_work_han_thu_113_202","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「屬，連也，音之欲反。」","sentenceOrder":202},
  {"id":"s_work_han_thu_113_203","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「見謂呈見之，音胡電反。」","sentenceOrder":203},
  {"id":"s_work_han_thu_113_204","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「誠，實也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_113_205","chapterId":"ch_work_han_thu_113","textTraditional":"初，桀子安取霍光女，結婚相親，光每休沐出，桀常代光入決事。昭帝始立，年八歲，帝長姊鄂邑蓋長公主居禁中，共養帝。〔一〕蓋主私近子客河間丁外人。〔二〕上與大將軍聞之，不絕主驩，有詔外人侍長主。長主內周陽氏女，令配耦帝。時上官安有女，即霍光外孫，安因光欲內之。光以為尚幼，不聽。安素與丁外人善，說外人曰：「聞長主內女，安子容貌端正，誠因長主時得入為后，〔三〕以臣父子在朝而有椒房之重，〔四〕成之在於足下，漢家故事常以列侯尚主，足下何憂不封侯乎？」外人喜，言於長主。長主以為然，詔召安女入為婕妤，安為騎都尉。月餘，遂立為皇后，年甫六歲。〔五〕","sentenceOrder":205},
  {"id":"s_work_han_thu_113_206","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「共音居用反。養音弋亮反。」","sentenceOrder":206},
  {"id":"s_work_han_thu_113_207","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「子客，子之賓客也。外人，其名也。」","sentenceOrder":207},
  {"id":"s_work_han_thu_113_208","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「以時得入。」","sentenceOrder":208},
  {"id":"s_work_han_thu_113_209","chapterId":"ch_work_han_thu_113","textTraditional":"〔四〕　師古曰：「椒房，殿名，在未央宮，皇后所居。」","sentenceOrder":209},
  {"id":"s_work_han_thu_113_210","chapterId":"ch_work_han_thu_113","textTraditional":"〔五〕　師古曰：「甫，始也。」","sentenceOrder":210},
  {"id":"s_work_han_thu_113_211","chapterId":"ch_work_han_thu_113","textTraditional":"安以后父封桑樂侯，食邑千五百戶，遷車騎將軍，日以驕淫。受賜殿中，出對賓客言：「與我婿飲，大樂！」見其服飾，使人歸，欲自燒物。安醉則裸行內，與後母及父諸良人、侍御皆亂。〔一〕子病死，仰而罵天。數守大將軍光，為丁外人求侯，〔二〕及桀欲妄官祿外人，〔三〕光執正，皆不聽。又桀妻父所幸充國為太醫監，闌入殿中，下獄當死。冬月且盡，蓋主為充國入馬二十匹贖罪，乃得減死論。於是桀、安父子深怨光而重德蓋主。知燕王旦帝兄，不得立，亦怨望，桀、安即記光過失予燕王，令上書告之，又為丁外人求侯。燕王大喜，上書稱：「子路喪姊，期而不除，孔子非之。子路曰：『由不幸寡兄弟，不忍除之。』〔四〕故曰：『觀過知仁』。〔五〕今臣與陛下獨有長公主為姊，陛下幸使丁外人侍之，外人宜蒙爵號。」書奏，上以問光，光執不許。及告光罪過，上又疑之，愈親光而疏桀、安。桀、安寖恚，〔六〕遂結黨與謀殺光，誘徵燕王至而誅之，因廢帝而立桀。或曰：「當如皇后何？」安曰：「逐麋之狗，當顧菟邪〔七〕！且用皇后為尊，一旦人主意有所移，雖欲為家人亦不可得，〔八〕此百世之一時也。」事發覺，燕王、蓋主皆自殺。語在霍光傳。桀、安宗族既滅，皇后以年少不與謀，〔九〕亦光外孫，故得不廢。皇后母前死，葬茂陵郭東，追尊曰敬夫人，置園邑二百家，長丞奉守如法。皇后自使私奴婢守桀、安冢。〔一０〕","sentenceOrder":211},
  {"id":"s_work_han_thu_113_212","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「良人謂妾也。侍御則兼婢矣。」","sentenceOrder":212},
  {"id":"s_work_han_thu_113_213","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「守，求請之。」","sentenceOrder":213},
  {"id":"s_work_han_thu_113_214","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「不由材德，故云妄。」","sentenceOrder":214},
  {"id":"s_work_han_thu_113_215","chapterId":"ch_work_han_thu_113","textTraditional":"〔四〕　師古曰：「事見禮記。由，子路之名。」","sentenceOrder":215},
  {"id":"s_work_han_thu_113_216","chapterId":"ch_work_han_thu_113","textTraditional":"〔五〕　師古曰：「論語云孔子曰：『人之過也，各於其黨，觀過斯知仁矣。』引此言者，謂子路厚於骨肉，雖違禮制，是其仁愛。」","sentenceOrder":216},
  {"id":"s_work_han_thu_113_217","chapterId":"ch_work_han_thu_113","textTraditional":"〔六〕　師古曰：「寖，漸也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_113_218","chapterId":"ch_work_han_thu_113","textTraditional":"〔七〕　師古曰：「言所求者大，不顧小也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_113_219","chapterId":"ch_work_han_thu_113","textTraditional":"〔八〕　師古曰：「家人，言凡庶匹夫。」","sentenceOrder":219},
  {"id":"s_work_han_thu_113_220","chapterId":"ch_work_han_thu_113","textTraditional":"〔九〕　師古曰：「與讀曰豫。」","sentenceOrder":220},
  {"id":"s_work_han_thu_113_221","chapterId":"ch_work_han_thu_113","textTraditional":"〔一０〕　師古曰：「廟記云上官桀、安冢並在霍光冢東，東去夏侯勝冢二十步。」","sentenceOrder":221},
  {"id":"s_work_han_thu_113_222","chapterId":"ch_work_han_thu_113","textTraditional":"光欲皇后擅寵有子，帝時體不安，左右及醫皆阿意，言宜禁內，雖宮人使令皆為窮絝，多其帶，〔一〕後宮莫有進者。","sentenceOrder":222},
  {"id":"s_work_han_thu_113_223","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　服虔曰：「窮絝，有前後當，不得交通也。」師古曰：「使令，所使之人也。絝，古袴字也。窮絝即今之緄襠袴也。令音力征反。緄音下昆反。」","sentenceOrder":223},
  {"id":"s_work_han_thu_113_224","chapterId":"ch_work_han_thu_113","textTraditional":"皇后立十歲而昭帝崩，后年十四五云。昌邑王賀徵即位，尊皇后為皇太后。光與太后共廢王賀，立孝宣帝。宣帝即位，為太皇太后。凡立四十七年，年五十二，建昭二年崩，合葬平陵。","sentenceOrder":224},
  {"id":"s_work_han_thu_113_225","chapterId":"ch_work_han_thu_113","textTraditional":"衛太子史良娣，宣帝祖母也。太子有妃，有良娣，有孺子，妻妾凡三等，子皆稱皇孫。史良娣家本魯國，有母貞君，兄恭。以元鼎四年入為良娣，生男進，號史皇孫。〔一〕","sentenceOrder":225},
  {"id":"s_work_han_thu_113_226","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「進者，皇孫之名。」","sentenceOrder":226},
  {"id":"s_work_han_thu_113_227","chapterId":"ch_work_han_thu_113","textTraditional":"武帝末，巫蠱事起，衛太子及良娣、史皇孫皆遭害。史皇孫有一男，號皇曾孫，時生數月，猶坐太子繫獄，積五歲乃遭赦。治獄使者邴吉憐皇曾孫無所歸，載以（附）〔付〕史恭。恭母貞君年老，見孫孤，甚哀之，自養視焉。","sentenceOrder":227},
  {"id":"s_work_han_thu_113_228","chapterId":"ch_work_han_thu_113","textTraditional":"後曾孫收養於掖庭，遂登至尊位，是為宣帝。而貞君及恭已死，恭三子皆以舊恩封。長子高為樂陵侯，曾為將陵侯，玄為平臺侯，及高子丹以功德封武陽侯，侯者凡四人。高至大司馬車騎將軍，丹左將軍，自有傳。","sentenceOrder":228},
  {"id":"s_work_han_thu_113_229","chapterId":"ch_work_han_thu_113","textTraditional":"史皇孫王夫人，宣帝母也，名翁須，太始中得幸於史皇孫。皇孫妻妾無號位，皆稱家人子。征和二年，生宣帝。帝生數月，衛太子、皇孫敗，家人子皆坐誅，莫有收葬者，唯宣帝得全。即尊位後，追尊母王夫人諡曰悼后，祖母史良娣曰戾后，皆改葬，起園邑，長丞奉守。語在戾太子傳。地節三年，求得外祖母王媼，媼男無故，無故弟武皆隨使者詣闕。時乘黃牛車，故百姓謂之黃牛嫗。","sentenceOrder":229},
  {"id":"s_work_han_thu_113_230","chapterId":"ch_work_han_thu_113","textTraditional":"初，上即位，數遣使者求外家，久遠，多似類而非是。既得王媼，令太中大夫任宣與丞相御史屬雜考問鄉里識知者，皆曰王嫗。嫗言名妄人，家本涿郡蠡吾平鄉。〔一〕年十四嫁為同鄉王更得妻。更得死，嫁為廣望王迺始婦，〔二〕產子男無故、武，女翁須。翁須年八九歲時，寄居廣望節侯子劉仲卿宅，仲卿謂迺始曰：「予我翁須，自養長之。」媼為翁須作縑單衣，〔三〕送仲卿家。仲卿教翁須歌舞，往來歸取冬夏衣。居四五歲，翁須來言「邯鄲賈長兒求歌舞者，仲卿欲以我與之。」媼即與翁須逃走，之平鄉。〔四〕仲卿載迺始共求媼，媼惶急，將翁須歸，曰：「兒居君家，非受一錢也，〔五〕奈何欲予它人？」仲卿詐曰：「不也。」後數日，翁須乘長兒車馬過門，呼曰：「我果見行，〔六〕當之柳宿。」〔七〕媼與迺始之柳宿，見翁須相對涕泣，謂曰：「我欲為汝自言。」〔八〕翁須曰：「母置之，〔九〕何家不可以居？〔一０〕自言無益也。」媼與迺始還求錢用，隨逐至中山盧奴，見翁須與歌舞等比五人同處，〔一一〕媼與翁須共宿。明日，迺始留視翁須，媼還求錢，欲隨至邯鄲。媼歸，糶買未具，迺始來歸曰：「翁須已去，我無錢用隨也。」因絕至今，不聞其問。賈長兒妻貞及從者師遂辭：〔一二〕「往二十歲，太子舍人侯明從長安來求歌舞者，請翁須等五人。長兒使遂送至長安，皆入太子家。」及廣望三老更始、劉仲卿妻其等四十五人辭，皆驗。〔一三〕宣奏王媼悼后母明白，上皆召見，賜無故、武爵關內侯，旬月間，賞賜以鉅萬計。頃之，制詔御史賜外祖母號為博平君，以博平、蠡吾兩縣戶萬一千為湯沐邑。封舅無故為平昌侯，武為樂昌侯，食邑各六千戶。","sentenceOrder":230},
  {"id":"s_work_han_thu_113_231","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「蠡音禮。」","sentenceOrder":231},
  {"id":"s_work_han_thu_113_232","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「廣望亦涿郡之縣。」","sentenceOrder":232},
  {"id":"s_work_han_thu_113_233","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「縑即今之絹也。音兼。」","sentenceOrder":233},
  {"id":"s_work_han_thu_113_234","chapterId":"ch_work_han_thu_113","textTraditional":"〔四〕　師古曰：「之，往也。」","sentenceOrder":234},
  {"id":"s_work_han_thu_113_235","chapterId":"ch_work_han_thu_113","textTraditional":"〔五〕　師古曰：「言未嘗得其聘幣。」","sentenceOrder":235},
  {"id":"s_work_han_thu_113_236","chapterId":"ch_work_han_thu_113","textTraditional":"〔六〕　師古曰：「呼音火故反。」","sentenceOrder":236},
  {"id":"s_work_han_thu_113_237","chapterId":"ch_work_han_thu_113","textTraditional":"〔七〕　蘇林曰：「聚邑名也，在中山盧奴東北三十里。」","sentenceOrder":237},
  {"id":"s_work_han_thu_113_238","chapterId":"ch_work_han_thu_113","textTraditional":"〔八〕　師古曰：「言自訟理，不肯行。」","sentenceOrder":238},
  {"id":"s_work_han_thu_113_239","chapterId":"ch_work_han_thu_113","textTraditional":"〔九〕　師古曰：「置之猶言（在）〔任〕聽之，不須自言。」","sentenceOrder":239},
  {"id":"s_work_han_thu_113_240","chapterId":"ch_work_han_thu_113","textTraditional":"〔一０〕師古曰：「言所去處，皆可安居。」","sentenceOrder":240},
  {"id":"s_work_han_thu_113_241","chapterId":"ch_work_han_thu_113","textTraditional":"〔一一〕師古曰：「比音必寐反。」","sentenceOrder":241},
  {"id":"s_work_han_thu_113_242","chapterId":"ch_work_han_thu_113","textTraditional":"〔一二〕師古曰：「辭，對辭。」","sentenceOrder":242},
  {"id":"s_work_han_thu_113_243","chapterId":"ch_work_han_thu_113","textTraditional":"〔一三〕師古曰：「其者，仲卿妻之名。」","sentenceOrder":243},
  {"id":"s_work_han_thu_113_244","chapterId":"ch_work_han_thu_113","textTraditional":"初，迺始以本始四年病死，後三歲，家乃富貴，追賜諡曰思成侯。詔涿郡治冢室，置園邑四百家，長丞奉守如法。歲餘，博平君薨，諡曰思成夫人。詔徙思成侯合葬奉明顧成廟南，置園邑長丞，〔一〕罷涿郡思成園。王氏侯者二人，無故子接為大司馬車騎將軍，而武子商至丞相，自有傳。","sentenceOrder":244},
  {"id":"s_work_han_thu_113_245","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「本號廣明，故戾太子傳云皇孫及王夫人皆葬廣明，其後以置園邑奉守，改曰奉明。」","sentenceOrder":245},
  {"id":"s_work_han_thu_113_246","chapterId":"ch_work_han_thu_113","textTraditional":"孝宣許皇后，元帝母也。父廣漢，昌邑人，少時為昌邑王郎。從武帝上甘泉，誤取它郎鞍以被其馬，發覺，吏劾從行而盜，當死，有詔募下蠶室。〔一〕後為宦者丞。上官桀謀反時，廣漢部索，〔二〕其殿中廬有索長數尺可以縛人者數千杖，滿一篋緘封，〔三〕廣漢索不得，它吏往得之。〔四〕廣漢坐論為鬼薪，輸掖庭，後為暴室嗇夫。時宣帝養於掖庭，號皇曾孫，與廣漢同寺居。〔五〕時掖庭令張賀，本衛太子家吏，及太子敗，賀坐下刑，以舊恩養視皇曾孫甚厚。及曾孫壯大，賀欲以女孫妻之。是時，昭帝始冠，長八尺二寸。賀弟安世為右將軍，與霍將軍同心輔政，聞賀稱譽皇曾孫，欲妻以女，安世怒曰：「曾孫乃衛太子後也，幸得以庶人衣食縣官，足矣，勿復言予女事。」於是賀止。時許廣漢有女平君，年十四五，當為內者令歐侯氏子婦。〔六〕臨當入，歐侯氏子死。其母將行卜相，〔七〕言當大貴，母獨喜。賀聞許嗇夫有女，乃置酒請之，〔八〕酒酣，為言「曾孫體近，下人，乃關內侯，〔九〕可妻也。」廣漢許諾。明日嫗聞之，怒。〔一０〕廣漢重令為介，〔一一〕遂與曾孫，一歲生元帝。數月，曾孫立為帝，平君為婕妤。是時，霍將軍有小女，與皇太后有親。公卿議更立皇后，皆心儀霍將軍女，〔一二〕亦未有言。上乃詔求微時故劍，大臣知指，白立許婕妤為皇后。既立，霍光以后父廣漢刑人不宜君國，歲餘乃封為昌成君。","sentenceOrder":246},
  {"id":"s_work_han_thu_113_247","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　孟康曰：「死罪囚欲就宮者聽之。」","sentenceOrder":247},
  {"id":"s_work_han_thu_113_248","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「部分搜索罪人也。索音山客反。」","sentenceOrder":248},
  {"id":"s_work_han_thu_113_249","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「殿中廬，桀所止宿廬舍在宮中者也。緘，束篋也，音工咸反。」","sentenceOrder":249},
  {"id":"s_work_han_thu_113_250","chapterId":"ch_work_han_thu_113","textTraditional":"〔四〕　師古曰：「須得此繩索者，用為桀之反具。」","sentenceOrder":250},
  {"id":"s_work_han_thu_113_251","chapterId":"ch_work_han_thu_113","textTraditional":"〔五〕　師古曰：「寺者，掖庭之官舍。」","sentenceOrder":251},
  {"id":"s_work_han_thu_113_252","chapterId":"ch_work_han_thu_113","textTraditional":"〔六〕　師古曰：「歐侯，姓也。歐音烏溝反。」","sentenceOrder":252},
  {"id":"s_work_han_thu_113_253","chapterId":"ch_work_han_thu_113","textTraditional":"〔七〕　師古曰：「將領自隨而行卜。」","sentenceOrder":253},
  {"id":"s_work_han_thu_113_254","chapterId":"ch_work_han_thu_113","textTraditional":"〔八〕　師古曰：「請，召也。召嗇夫飲酒也。」","sentenceOrder":254},
  {"id":"s_work_han_thu_113_255","chapterId":"ch_work_han_thu_113","textTraditional":"〔九〕　師古曰：「言曾孫之身於帝為近親，縱其人材下劣，尚作關內侯。書本或無人字。」","sentenceOrder":255},
  {"id":"s_work_han_thu_113_256","chapterId":"ch_work_han_thu_113","textTraditional":"〔一０〕師古曰：「廣漢之妻不欲與曾孫。」","sentenceOrder":256},
  {"id":"s_work_han_thu_113_257","chapterId":"ch_work_han_thu_113","textTraditional":"〔一一〕師古曰：「更令人作媒而結婚姻。重音直用反。」","sentenceOrder":257},
  {"id":"s_work_han_thu_113_258","chapterId":"ch_work_han_thu_113","textTraditional":"〔一二〕服虔曰：「儀音螘。」晉灼曰：「儀，向也。」師古曰：「晉說是也，謂附向之。」","sentenceOrder":258},
  {"id":"s_work_han_thu_113_259","chapterId":"ch_work_han_thu_113","textTraditional":"霍光夫人顯欲貴其小女，道無從。〔一〕明年，許皇后當娠，病。女醫淳于衍者，霍氏所愛，嘗入宮侍皇后疾。衍夫賞為掖庭戶衛，謂衍「可過辭霍夫人行，〔二〕為我求安池監。」衍如言報顯。顯因生心，辟左右，〔三〕字謂衍：「少夫幸報我以事，〔四〕我亦欲報少夫，可乎？」〔五〕衍曰：「夫人所言，何等不可者！」〔六〕顯曰：「將軍素愛小女成君，欲奇貴之，願以累少夫。」〔七〕衍曰：「何謂邪？」顯曰：「婦人免乳大故，十死一生。〔八〕今皇后當免身，可因投毒藥去也，〔九〕成君即得為皇后矣。如蒙力事成，富貴與少夫共之。」衍曰：「藥雜治，當先嘗，安可？」〔一０〕顯曰：「在少夫為之耳。將軍領天下，誰敢言者？緩急相護，但恐少夫無意耳！」衍良久曰：「願盡力。」即擣附子，齎入長定宮。皇后免身後，衍取附子并合大醫大丸以飲皇后。〔一一〕有頃曰：「我頭岑岑也，藥中得無有毒？」〔一二〕對曰：「無有。」遂加煩懣，崩。〔一三〕衍出，過見顯，相勞問，〔一四〕亦未敢重謝衍。〔一五〕後人有上書告諸醫侍疾無狀者，皆收繫詔獄，劾不道。顯恐（事）急，即以狀具語光，因曰：「既失計為之，無令吏急衍！」光驚鄂，默然不應。其後奏上，署衍勿論。〔一六〕","sentenceOrder":259},
  {"id":"s_work_han_thu_113_260","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「從，因也，由也。無由得內其女。」","sentenceOrder":260},
  {"id":"s_work_han_thu_113_261","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「過辭夫人，乃行入宮也。」","sentenceOrder":261},
  {"id":"s_work_han_thu_113_262","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「辟音闢，謂屏去之。」","sentenceOrder":262},
  {"id":"s_work_han_thu_113_263","chapterId":"ch_work_han_thu_113","textTraditional":"〔四〕　如淳曰：「稱衍字曰少夫，親之也。」晉灼曰：「報我以事，謂求池監也。」","sentenceOrder":263},
  {"id":"s_work_han_thu_113_264","chapterId":"ch_work_han_thu_113","textTraditional":"〔五〕　晉灼曰：「報少夫謀弒許后事。」","sentenceOrder":264},
  {"id":"s_work_han_thu_113_265","chapterId":"ch_work_han_thu_113","textTraditional":"〔六〕　師古曰：「無事而不可。」","sentenceOrder":265},
  {"id":"s_work_han_thu_113_266","chapterId":"ch_work_han_thu_113","textTraditional":"〔七〕　師古曰：「累，託也，音力瑞反。」","sentenceOrder":266},
  {"id":"s_work_han_thu_113_267","chapterId":"ch_work_han_thu_113","textTraditional":"〔八〕　師古曰：「免乳謂產子也。大故，大事也。乳音人喻反。」","sentenceOrder":267},
  {"id":"s_work_han_thu_113_268","chapterId":"ch_work_han_thu_113","textTraditional":"〔九〕　師古曰：「去謂除去皇后也，音丘呂反。」","sentenceOrder":268},
  {"id":"s_work_han_thu_113_269","chapterId":"ch_work_han_thu_113","textTraditional":"〔一０〕師古曰：「與眾醫共雜治之，人有先嘗者，何可行毒？」","sentenceOrder":269},
  {"id":"s_work_han_thu_113_270","chapterId":"ch_work_han_thu_113","textTraditional":"〔一一〕晉灼曰：「大丸，今澤蘭丸之屬。」","sentenceOrder":270},
  {"id":"s_work_han_thu_113_271","chapterId":"ch_work_han_thu_113","textTraditional":"〔一二〕師古曰：「岑岑，痺悶之意。」","sentenceOrder":271},
  {"id":"s_work_han_thu_113_272","chapterId":"ch_work_han_thu_113","textTraditional":"〔一三〕師古曰：「懣音滿，又音悶。」","sentenceOrder":272},
  {"id":"s_work_han_thu_113_273","chapterId":"ch_work_han_thu_113","textTraditional":"〔一四〕師古曰：「勞音來到反。」","sentenceOrder":273},
  {"id":"s_work_han_thu_113_274","chapterId":"ch_work_han_thu_113","textTraditional":"〔一五〕師古曰：「恐人知覺之。」","sentenceOrder":274},
  {"id":"s_work_han_thu_113_275","chapterId":"ch_work_han_thu_113","textTraditional":"〔一六〕李奇曰：「光題其奏也。」師古曰：「言之於帝，故解釋耳，光不自署也。」","sentenceOrder":275},
  {"id":"s_work_han_thu_113_276","chapterId":"ch_work_han_thu_113","textTraditional":"許后立三年而崩，諡曰恭哀皇后，葬杜南，是為杜陵南園。〔一〕後五年，立皇太子，乃封太子外祖父昌成君廣漢為平恩侯，位特進。後四年，復封廣漢兩弟，舜為博望侯，延壽為樂成侯。許氏侯者凡三人。廣漢薨，諡曰戴侯，無子，絕。葬南園旁，置邑三百家，長丞奉守如法。宣帝以延壽為大司馬車騎將軍，輔政。元帝即位，復封延壽中子嘉為平恩侯，奉戴侯後，亦為大司馬車騎將軍。","sentenceOrder":276},
  {"id":"s_work_han_thu_113_277","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「即今之所謂小陵者，去杜陵十八里。」","sentenceOrder":277},
  {"id":"s_work_han_thu_113_278","chapterId":"ch_work_han_thu_113","textTraditional":"孝宣霍皇后，大司馬大將軍博陸侯光女也。母顯，既使淳于衍陰殺許后，顯因為成君衣補，〔一〕治入宮具，勸光內之，果立為皇后。","sentenceOrder":278},
  {"id":"s_work_han_thu_113_279","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「謂縫作嫁時衣被也。為音于偽反。」","sentenceOrder":279},
  {"id":"s_work_han_thu_113_280","chapterId":"ch_work_han_thu_113","textTraditional":"初許后起微賤，登至尊日淺，從官車服甚節儉，五日一朝皇太后於長樂宮，親奉案上食，以婦道共養。及霍后立，亦修許后故事。而皇太后親霍后之姊子，故常竦體，敬而禮之。皇后轝駕侍從甚盛，賞賜官屬以千萬計，與許后時縣絕矣。上亦寵之，顓房燕。〔一〕立三歲而光薨。後一歲，上立許后男為太子，昌成君者為平恩侯。顯怒恚不食，歐血，曰：「此乃民間時子，安得立？即后有子，反為王邪！」復教皇后令毒太子。皇后數召太子賜食，保阿輒先嘗之，后挾毒不得行。後殺許后事頗泄，顯遂與諸婿昆弟謀反，發覺，皆誅滅。使有司賜皇后策曰：「皇后熒惑失道，懷不德，挾毒與母博陸宣成侯夫人顯謀欲危太子，無人母之恩，不宜奉宗廟衣服，不可以承天命。烏呼傷哉！其退避宮，上璽綬有司。」霍后立五年，廢處昭臺宮。〔二〕後十二歲，徙雲林館，乃自殺，葬昆吾亭東。〔三〕","sentenceOrder":280},
  {"id":"s_work_han_thu_113_281","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「顓與專同。」","sentenceOrder":281},
  {"id":"s_work_han_thu_113_282","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「在上林中。」","sentenceOrder":282},
  {"id":"s_work_han_thu_113_283","chapterId":"ch_work_han_thu_113","textTraditional":"〔三〕　師古曰：「昆吾，地名，在藍田。」","sentenceOrder":283},
  {"id":"s_work_han_thu_113_284","chapterId":"ch_work_han_thu_113","textTraditional":"初，霍光及兄驃騎將軍去病皆自以功伐封侯居位，宣帝以光故，封去病孫山、山弟雲皆為列侯，侯者前後四人。","sentenceOrder":284},
  {"id":"s_work_han_thu_113_285","chapterId":"ch_work_han_thu_113","textTraditional":"孝宣王皇后。其先高祖時有功賜爵關內侯，自沛徙長陵，傳爵至后父奉光。奉光少時好鬥雞，宣帝在民間數與奉光會，相識。奉光有女年十餘歲，每當適人，所當適輒死，故久不行。及宣帝即位，召入後宮，稍進為婕妤。是時，館陶（主）〔王〕母華婕妤〔一〕及淮陽憲王母張婕妤、楚孝王母衛婕妤皆愛幸。","sentenceOrder":285},
  {"id":"s_work_han_thu_113_286","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「華音戶花反。」","sentenceOrder":286},
  {"id":"s_work_han_thu_113_287","chapterId":"ch_work_han_thu_113","textTraditional":"霍皇后廢後，上憐許太子蚤失母，〔一〕幾為霍氏所害，〔二〕於是乃選後宮素謹慎而無子者，遂立王婕妤為皇后，令母養太子。自為后後，希見無寵。封父奉光為邛成侯。立十六年，宣帝崩，元帝即位，為皇太后。封太后兄舜為安平侯。後二年，奉光薨，諡曰共侯，葬長門南，置園邑二百家，長丞奉守如法。元帝崩，成帝即位，為太皇太后。復爵太皇太后弟駿為關內侯，食邑千戶。王氏列侯二人，關內侯一人。舜子章，章從弟咸，皆至左右將軍。時成帝母亦姓王氏，故世號太皇太后為邛成太后。","sentenceOrder":287},
  {"id":"s_work_han_thu_113_288","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「許后所生，故曰許太子。」","sentenceOrder":288},
  {"id":"s_work_han_thu_113_289","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「幾音巨依反。」","sentenceOrder":289},
  {"id":"s_work_han_thu_113_290","chapterId":"ch_work_han_thu_113","textTraditional":"邛成太后凡立四十九年，年七十餘，永始元年崩，合葬杜陵，稱東園。〔一〕奉光孫勳坐法免。元始中，成帝太后下詔曰：「孝宣王皇后，朕之姑，深念奉質共脩之義，恩結于心。〔二〕惟邛成共侯國廢祀絕，朕甚閔焉。其封共侯曾孫堅固為邛成侯。」至王莽乃絕。","sentenceOrder":290},
  {"id":"s_work_han_thu_113_291","chapterId":"ch_work_han_thu_113","textTraditional":"〔一〕　師古曰：「雖同塋兆而別為墳，王后陵次宣帝陵東，故曰東園也。」","sentenceOrder":291},
  {"id":"s_work_han_thu_113_292","chapterId":"ch_work_han_thu_113","textTraditional":"〔二〕　師古曰：「質讀曰贄。」","sentenceOrder":292},
  {"id":"s_work_han_thu_113_293","chapterId":"ch_work_han_thu_113","textTraditional":"校勘記","sentenceOrder":293},
  {"id":"s_work_han_thu_113_294","chapterId":"ch_work_han_thu_113","textTraditional":"三九三三頁　四行　殷之興也以有娀（又）〔及〕有｛新女｝，　景祐、殿、局本都作「及」。王先謙說作「及」是。","sentenceOrder":294},
  {"id":"s_work_han_thu_113_295","chapterId":"ch_work_han_thu_113","textTraditional":"三九三九頁　四行　燕（靈）王建〔子〕。　景祐本無「靈」字，有「子」字。周壽昌說何焯校本同，何校是。","sentenceOrder":295},
  {"id":"s_work_han_thu_113_296","chapterId":"ch_work_han_thu_113","textTraditional":"三九四七頁一四行　皇太后微時所（謂）〔為〕金王孫生女俗，在民間，蓋諱之也。　景祐、殿本都作「為」。錢大昕說「俗」是金氏女之名。王先謙說錢說是，顏注誤。","sentenceOrder":296},
  {"id":"s_work_han_thu_113_297","chapterId":"ch_work_han_thu_113","textTraditional":"三九五０頁　七行　青三子（皆）〔在〕襁褓中，皆為列侯。　景祐、殿、局本都作「在」，此誤。","sentenceOrder":297},
  {"id":"s_work_han_thu_113_298","chapterId":"ch_work_han_thu_113","textTraditional":"三九五三頁　五行　秋氣（潛）〔憯〕以淒淚兮，　景祐、殿、局本都作「憯」。王先謙說作「憯」是。","sentenceOrder":298},
  {"id":"s_work_han_thu_113_299","chapterId":"ch_work_han_thu_113","textTraditional":"三九五四頁一七行　嫉妒闟（葺）〔茸〕，　景祐、殿、局本都作「茸」。","sentenceOrder":299},
  {"id":"s_work_han_thu_113_300","chapterId":"ch_work_han_thu_113","textTraditional":"三九五五頁一二行　而今涕泣（從）〔徒〕自已耳，　殿本作「徒」。王先謙說作「徒」是。","sentenceOrder":300},
  {"id":"s_work_han_thu_113_301","chapterId":"ch_work_han_thu_113","textTraditional":"三九五六頁　八行　（元）〔太〕始三年生昭帝，　景祐本作「太」。王念孫、朱一新都說作「太」是。","sentenceOrder":301},
  {"id":"s_work_han_thu_113_302","chapterId":"ch_work_han_thu_113","textTraditional":"三九六一頁　五行　載以（附）〔付〕史恭。　景祐、殿本都作「付」。王先謙說作「付」是。","sentenceOrder":302},
  {"id":"s_work_han_thu_113_303","chapterId":"ch_work_han_thu_113","textTraditional":"三九六三頁一一行　置之猶言（在）〔任〕聽之。　景祐、殿、局本都作「任」，此誤。","sentenceOrder":303},
  {"id":"s_work_han_thu_113_304","chapterId":"ch_work_han_thu_113","textTraditional":"三九六六頁一一行　顯恐（事）急，　景祐本無「事」字。王念孫說「事」字衍。","sentenceOrder":304},
  {"id":"s_work_han_thu_113_305","chapterId":"ch_work_han_thu_113","textTraditional":"三九六九頁　九行　館陶（主）〔王〕母華婕妤，　景祐、殿本都作「王」。","sentenceOrder":305},
  {"id":"s_work_han_thu_114_1","chapterId":"ch_work_han_thu_114","textTraditional":"孝元王皇后，成帝母也。家凡十侯，五大司馬，〔一〕外戚莫盛焉。自有傳。","sentenceOrder":1},
  {"id":"s_work_han_thu_114_2","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「十侯者，陽平頃侯禁、禁子敬侯鳳、安成侯崇、平阿侯譚、成都侯商、紅陽侯立、曲陽侯根、高平侯逢時、安陽侯音、新都侯莽也。五大司馬者，鳳、音、商、根、莽也。一曰，鳳嗣禁為侯，不當重數。而十人者，淳于長即其一也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_114_3","chapterId":"ch_work_han_thu_114","textTraditional":"孝成許皇后，大司馬車騎將軍平恩侯嘉女也。元帝悼傷母恭哀后居位日淺而遭霍氏之辜，故選嘉女以配皇太子。初入太子家，上令中常侍黃門親近者侍送，還白太子懽說狀，〔一〕元帝喜謂左右：「酌酒賀我！」左右皆稱萬歲。久之，有一男，失之。及成帝即位，立許妃為皇后，復生一女，失之。","sentenceOrder":3},
  {"id":"s_work_han_thu_114_4","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":4},
  {"id":"s_work_han_thu_114_5","chapterId":"ch_work_han_thu_114","textTraditional":"初后父嘉自元帝時為大司馬車騎將軍輔政，已八九年矣。及成帝立，復以元舅陽平侯王鳳為大司馬大將軍，與嘉並。杜欽以為故事后父重於帝舅，乃說鳳曰：「車騎將軍至貴，將軍宜尊（重）之敬之，無失其意。蓋輕細微眇之漸，必生乖忤之患，〔一〕不可不慎。衛將軍之日盛於蓋侯，〔二〕近世之事，語尚在於長老之耳，唯將軍察焉。」久之，上欲專委任鳳，乃策嘉曰：「將軍家重身尊，不宜以吏職自絫。〔三〕賜黃金二百斤，以特進侯就朝位。」後歲餘薨，諡曰恭侯。","sentenceOrder":5},
  {"id":"s_work_han_thu_114_6","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「眇亦細也。忤，違也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_114_7","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「衛將軍，衛青也，武帝衛皇后之弟。蓋侯，王信也，武帝之舅。」","sentenceOrder":7},
  {"id":"s_work_han_thu_114_8","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「絫，古累字也，音力瑞反。」","sentenceOrder":8},
  {"id":"s_work_han_thu_114_9","chapterId":"ch_work_han_thu_114","textTraditional":"后聰慧，善史書，自為妃至即位，常寵於上，後宮希得進見。皇太后及帝舅憂上無繼嗣，時又數有災異，劉向、谷永等皆陳其咎在於後宮。上然其言。於是省減椒房掖廷用度。〔一〕皇后乃上疏曰：","sentenceOrder":9},
  {"id":"s_work_han_thu_114_10","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「椒房殿皇后所居。」","sentenceOrder":10},
  {"id":"s_work_han_thu_114_11","chapterId":"ch_work_han_thu_114","textTraditional":"妾誇布服糲食，〔一〕加以幼稚愚惑，不明義理，幸得免離茅屋之下，備後宮埽除。蒙過誤之寵，居非命所當託，洿穢不修，曠職尸官，〔二〕數逆至法，踰越制度，當伏放流之誅，不足以塞責。乃壬寅日大長秋受詔：「椒房儀法，御服輿駕，所發諸官署，及所造作，遺賜外家群臣妾，〔三〕皆如竟寧以前故事。」妾伏自念，入椒房以來，遺賜外家未嘗踰故事，每輒決上，〔四〕可覆問也。〔五〕今誠時世異制，長短相補，不出漢制而已，纖微之間，未必可同。若竟寧前與黃龍前，豈相放哉？〔六〕家吏不曉，〔七〕今壹受詔如此，且使妾搖手不得。今言無得發取諸官，殆謂未央宮不屬妾，不宜獨取也。〔八〕言妾家府亦不當得，妾竊惑焉。〔九〕幸得賜湯沐邑以自奉養，亦小發取其中，何害於誼而不可哉？又詔書言服御所造，皆如竟寧前，吏誠不能揆其意，即且令妾被服所為不得不如前。〔一０〕設妾欲作某屏風張於某所，曰故事無有，或不能得，則必繩妾以詔書矣。〔一一〕此二事誠不可行，唯陛下省察。","sentenceOrder":11},
  {"id":"s_work_han_thu_114_12","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　孟康曰：「誇，大也，大布之衣也。糲，粗米也。」師古曰：「言在家時野賤也。誇音夸。糲音剌。」","sentenceOrder":12},
  {"id":"s_work_han_thu_114_13","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「洿與汙同。曠，空也。尸，主也，妄主其官。」","sentenceOrder":13},
  {"id":"s_work_han_thu_114_14","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「外家謂后之家族，言在外也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_114_15","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「每事皆奏決於天子，乃敢行也。上音時掌反。」","sentenceOrder":15},
  {"id":"s_work_han_thu_114_16","chapterId":"ch_work_han_thu_114","textTraditional":"〔五〕　師古曰：「覆音芳目反。」","sentenceOrder":16},
  {"id":"s_work_han_thu_114_17","chapterId":"ch_work_han_thu_114","textTraditional":"〔六〕　晉灼曰：「竟寧，元帝時也。黃龍，宣帝時也。言二帝奢儉不同，豈相放哉？」師古曰：「放，依也，音甫往反。」","sentenceOrder":17},
  {"id":"s_work_han_thu_114_18","chapterId":"ch_work_han_thu_114","textTraditional":"〔七〕　師古曰：「家吏，皇后之官屬。」","sentenceOrder":18},
  {"id":"s_work_han_thu_114_19","chapterId":"ch_work_han_thu_114","textTraditional":"〔八〕　師古曰：「未央宮天子之宮，故其財物皇后不得取也。今言者，謂詔書新有所限約之言。」","sentenceOrder":19},
  {"id":"s_work_han_thu_114_20","chapterId":"ch_work_han_thu_114","textTraditional":"〔九〕　師古曰：「此言，謂家吏之言。」","sentenceOrder":20},
  {"id":"s_work_han_thu_114_21","chapterId":"ch_work_han_thu_114","textTraditional":"〔一０〕師古曰：「詔書本云奢儉之制，如竟寧耳，而吏乃謂衣服處置一一如之也。被音皮義反。」","sentenceOrder":21},
  {"id":"s_work_han_thu_114_22","chapterId":"ch_work_han_thu_114","textTraditional":"〔一一〕師古曰：「言或有所求，吏不肯備，因云詔書不許也。」","sentenceOrder":22},
  {"id":"s_work_han_thu_114_23","chapterId":"ch_work_han_thu_114","textTraditional":"（官）〔宦〕吏忮佷，必欲自勝。〔一〕幸妾尚貴時，猶以不急事操人，〔二〕況今日日益侵，又獲此詔，其操約人，豈有所訴？陛下見妾在椒房，終不肯給妾纖微內邪？〔三〕若不私府小取，將安所仰乎？〔四〕舊故，中宮乃私奪左右之賤繒，及發乘輿服繒，言為待詔補，已而貿易其中。〔五〕左右多竊怨者，甚恥為之。又故事以特牛祠大父母，戴侯、敬侯皆得蒙恩以太牢祠，今當率如故事，唯陛下哀之！","sentenceOrder":23},
  {"id":"s_work_han_thu_114_24","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「（官）〔宦〕吏，奄人為皇后吏也。忮，堅也。忮音之豉反。」","sentenceOrder":24},
  {"id":"s_work_han_thu_114_25","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「尚貴時，謂昔被寵遇之時也。操，持也，音千高反。次下亦同。」","sentenceOrder":25},
  {"id":"s_work_han_thu_114_26","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「言皇后自有湯沐，故更無它纖毫給賜。」","sentenceOrder":26},
  {"id":"s_work_han_thu_114_27","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「內邪，言內中所須者也。邪，語辭也。仰音牛向反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_114_28","chapterId":"ch_work_han_thu_114","textTraditional":"〔五〕　師古曰：「託言此繒擬待別詔有所補浣，而私換易取其好者以自用。」","sentenceOrder":28},
  {"id":"s_work_han_thu_114_29","chapterId":"ch_work_han_thu_114","textTraditional":"今吏甫受詔讀記，〔一〕直豫言使后知之，非可復若私府有所取也。〔二〕其萌牙所以約制妾者，恐失人理。〔三〕今但損車駕，及毋若未央宮有所發，遺賜衣服如故事，則可矣。〔四〕其餘誠太迫急，奈何？妾薄命，端遇竟寧前。〔五〕竟寧前於今世而比之，豈可耶？〔六〕故時酒肉有所賜外家，輒上表乃決。又故杜陵梁美人歲時遺酒一石，肉百斤耳。〔七〕妾甚少之，遺田八子誠不可若是〔八〕。事率眾多，不可勝以文陳。〔九〕俟自見，索言之，〔一０〕唯陛下深察焉！","sentenceOrder":29},
  {"id":"s_work_han_thu_114_30","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「甫，始也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_114_31","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「若謂如未奉詔之前也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_114_32","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「萌牙，言其初始發，意若草木之方生也。」","sentenceOrder":32},
  {"id":"s_work_han_thu_114_33","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「言今止當減損車馬制度，及不得同未央宮輒有發取，妄遺賜人，於事則可。而后之衣服，自當如舊也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_114_34","chapterId":"ch_work_han_thu_114","textTraditional":"〔五〕　師古曰：「端，正也。言不得以他時為比例，而正依竟寧前也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_114_35","chapterId":"ch_work_han_thu_114","textTraditional":"〔六〕　師古曰：「言今時國家制度眾事比竟寧前，不肯皆同也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_114_36","chapterId":"ch_work_han_thu_114","textTraditional":"〔七〕　蘇林曰：「宣帝美人也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_114_37","chapterId":"ch_work_han_thu_114","textTraditional":"〔八〕　師古曰：「當多於梁美人也。」","sentenceOrder":37},
  {"id":"s_work_han_thu_114_38","chapterId":"ch_work_han_thu_114","textTraditional":"〔九〕　師古曰：「率猶計也，類也。言以文書陳之不可勝書。」","sentenceOrder":38},
  {"id":"s_work_han_thu_114_39","chapterId":"ch_work_han_thu_114","textTraditional":"〔一０〕師古曰：「俟，待也。自見，后自見於天子也。索，盡也。見音胡電反。索音先各反。」","sentenceOrder":39},
  {"id":"s_work_han_thu_114_40","chapterId":"ch_work_han_thu_114","textTraditional":"上於是采劉向、谷永之言以報曰：","sentenceOrder":40},
  {"id":"s_work_han_thu_114_41","chapterId":"ch_work_han_thu_114","textTraditional":"皇帝問皇后，所言事聞之。夫日者眾陽之宗，天光之貴，王者之象，人君之位也。夫以陰而侵陽，虧其正體，是非下陵上，妻乘夫，賤踰貴之變與？〔一〕春秋二百四十二年，變異為眾，莫若日蝕大。自漢興，日蝕亦為呂、霍之屬見。以今揆之，豈有此等之效與？〔二〕諸侯拘迫漢制，牧相執持之也，〔三〕又安獲齊、趙七國之難？將相大臣褢誠秉忠，唯義是從，〔四〕又惡有上官、博陸、宣成之謀？〔五〕若乃徒步豪桀，非有陳勝、項梁之群也；匈奴、夷狄，非有冒頓、郅支之倫也。方外內鄉，百蠻賓服，〔六〕殊俗慕義，八州懷德，雖使其懷挾邪意，猶不足憂，又況其無乎？求於夷狄無有，求於臣下無有，微後宮也當，何以塞之？〔七〕","sentenceOrder":41},
  {"id":"s_work_han_thu_114_42","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「與讀曰歟。」","sentenceOrder":42},
  {"id":"s_work_han_thu_114_43","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「與讀曰歟。」","sentenceOrder":43},
  {"id":"s_work_han_thu_114_44","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「牧，州牧也。相，諸侯王相也。」","sentenceOrder":44},
  {"id":"s_work_han_thu_114_45","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「褢，古懷字。」","sentenceOrder":45},
  {"id":"s_work_han_thu_114_46","chapterId":"ch_work_han_thu_114","textTraditional":"〔五〕　師古曰：「惡，於何也。上官，上官桀、安也。博陸，博陸侯霍禹也。宣成，宣成侯夫人顯也。惡音烏。」","sentenceOrder":46},
  {"id":"s_work_han_thu_114_47","chapterId":"ch_work_han_thu_114","textTraditional":"〔六〕　師古曰：「鄉讀曰嚮。內嚮，皆嚮中國也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_114_48","chapterId":"ch_work_han_thu_114","textTraditional":"〔七〕　師古曰：「微，無也，猶言非也。塞，當也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_114_49","chapterId":"ch_work_han_thu_114","textTraditional":"日者，建始元年正月，〔一〕白氣出於營室。營室者，天子之後宮也。正月於尚書為皇極。皇極者，王氣之極也。白者西方之氣，其於春當廢。今正於（王）〔皇〕極之月，興廢氣於後宮，視后妾無能懷任保全者，〔二〕以著繼嗣之微，賤人將起也。〔三〕至其九月，流星如瓜，出於文昌，貫紫宮，尾委曲如龍，臨於鉤陳，此又章顯前尤，著在內也。〔四〕其後則有北宮井溢，南流逆理，數郡水出，流殺人民。後則訛言傳相驚震，女童入殿，咸莫覺知。〔五〕夫河者水陰，四瀆之長，今乃大決，沒漂陵邑，〔六〕斯昭陰盛盈溢，違經絕紀之應也。乃昔之月，鼠巢于樹，野鵲變色。五月庚子，鳥焚其巢太山之域。易曰：「鳥焚其巢，旅人先笑後號咷。喪牛于易，凶。」〔七〕言王者處民上，如鳥之處巢也，不顧卹百姓，百姓畔而去之，若鳥之自焚也，雖先快意說笑，〔八〕其後必號而無及也。百姓喪其君，若牛亡其毛也，故稱凶。泰山，王者易姓告代之處，今正於岱宗之山，甚可懼也。三月癸未，大風自西搖祖宗寢廟，揚裂帷席，折拔樹木，頓僵車輦，毀壞檻屋，災及宗廟，足為寒心！四月己亥，日蝕東井，轉旋且索，與既無異。〔九〕己猶戊也，亥復水也，〔一０〕明陰盛，咎在內。於戊己，虧君體，著絕世於皇極，顯禍敗及京都。於東井，變怪眾備，末重益大，來數益甚。成形之禍月以迫切，不救之患日寖婁深，〔一一〕咎敗灼灼若此，豈可以忽哉！〔一二〕","sentenceOrder":49},
  {"id":"s_work_han_thu_114_50","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「日者猶言往日也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_114_51","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「視讀曰示。」","sentenceOrder":51},
  {"id":"s_work_han_thu_114_52","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「著，明也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_114_53","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「尤，過也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_114_54","chapterId":"ch_work_han_thu_114","textTraditional":"〔五〕　師古曰：「謂陳持弓也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_114_55","chapterId":"ch_work_han_thu_114","textTraditional":"〔六〕　師古曰：「大阜曰陵。」","sentenceOrder":55},
  {"id":"s_work_han_thu_114_56","chapterId":"ch_work_han_thu_114","textTraditional":"〔七〕　師古曰：「咲，古笑字也。咷音桃。解並在谷永傳。」","sentenceOrder":56},
  {"id":"s_work_han_thu_114_57","chapterId":"ch_work_han_thu_114","textTraditional":"〔八〕　師古曰：「說讀曰悅。」","sentenceOrder":57},
  {"id":"s_work_han_thu_114_58","chapterId":"ch_work_han_thu_114","textTraditional":"〔九〕　師古曰：「轉旋且索，言須臾之間則欲盡也。既亦盡耳，春秋書『日有食之，既』。故詔引以為言也。索音先各反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_114_59","chapterId":"ch_work_han_thu_114","textTraditional":"〔一０〕張晏曰：「己戊皆中宮，為君。亥為水，陰氣也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_114_60","chapterId":"ch_work_han_thu_114","textTraditional":"〔一一〕師古曰：「寖，甚也。婁，古屢字。」","sentenceOrder":60},
  {"id":"s_work_han_thu_114_61","chapterId":"ch_work_han_thu_114","textTraditional":"〔一二〕師古曰：「灼灼，明白貌也。忽，怠忘也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_114_62","chapterId":"ch_work_han_thu_114","textTraditional":"書云「高宗肜日，粵有雊雉。〔一〕祖己曰：『惟先假王正厥事。』」又曰「雖休勿休，惟敬五刑，以成三德。」〔二〕即飭椒房及掖庭耳。〔三〕今皇后有所疑，便不便，其條刺，使大長秋來白之。〔四〕吏拘於法，亦安足過？蓋矯枉者過宜，古今同之。〔五〕且財（帛）〔幣〕之省，特牛之祠，其於皇后，所以扶助德美，為華寵也。咎根不除，災變相襲，〔六〕祖宗且不血食，何戴侯也！傳不云乎？「以約失之者鮮。」〔七〕審皇后欲從其奢與？〔八〕朕亦當法孝武皇帝也，如此則甘泉、建章可復興矣。世俗歲殊，時變日化，遭事制宜，因時而移，舊之非者，何可放焉！〔九〕君子之道，樂因循而重改作。昔魯人為長府，閔子騫曰：「仍舊貫如之何？何必改作！」〔一０〕蓋惡之也。詩云：「雖無老成人，尚有典刑，曾是莫聽，大命以傾。」〔一一〕孝文皇帝，朕之師也。皇太后，皇后成法也。假使太后在彼時不如職，今見親厚，又惡可以踰乎！〔一二〕皇后其刻心秉德，毋違先后之制度，力誼勉行，稱順婦道，〔一三〕減省群事，謙約為右。〔一四〕其孝東宮，毋闕朔望，〔一五〕推誠永究，爰何不臧！〔一六〕養名顯行，以息眾讙，〔一七〕垂則列妾，使有法焉。〔一八〕皇后深惟毋忽！","sentenceOrder":62},
  {"id":"s_work_han_thu_114_63","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「肜音弋中反。」","sentenceOrder":63},
  {"id":"s_work_han_thu_114_64","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「解並在谷永傳。」","sentenceOrder":64},
  {"id":"s_work_han_thu_114_65","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「謂祖己所言皆以戒後宮也。飭與敕同。」","sentenceOrder":65},
  {"id":"s_work_han_thu_114_66","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「條謂分條之也。刺謂書之於刺板也。刺音千賜反。」","sentenceOrder":66},
  {"id":"s_work_han_thu_114_67","chapterId":"ch_work_han_thu_114","textTraditional":"〔五〕　師古曰：「矯，正也。枉，曲也。言意在正曲，遂過於直。」","sentenceOrder":67},
  {"id":"s_work_han_thu_114_68","chapterId":"ch_work_han_thu_114","textTraditional":"〔六〕　師古曰：「襲，重累也。」","sentenceOrder":68},
  {"id":"s_work_han_thu_114_69","chapterId":"ch_work_han_thu_114","textTraditional":"〔七〕　師古曰：「論語載孔子之言也。鮮，少也。謂能行儉約而有過失之事，如此者少也。鮮音先踐反。」","sentenceOrder":69},
  {"id":"s_work_han_thu_114_70","chapterId":"ch_work_han_thu_114","textTraditional":"〔八〕　師古曰：「與讀曰歟。」","sentenceOrder":70},
  {"id":"s_work_han_thu_114_71","chapterId":"ch_work_han_thu_114","textTraditional":"〔九〕　師古曰：「放音甫往反。」","sentenceOrder":71},
  {"id":"s_work_han_thu_114_72","chapterId":"ch_work_han_thu_114","textTraditional":"〔一０〕師古曰：「事見論語。長府，藏貨之府也。閔子騫，孔子弟子也。名損。仍，因也。貫，事也。因舊事則可，何乃復更改作乎？」","sentenceOrder":72},
  {"id":"s_work_han_thu_114_73","chapterId":"ch_work_han_thu_114","textTraditional":"〔一一〕師古曰：「大雅蕩之詩也。老成人，舊故之臣也。典刑，常法也。言闇亂之時不用舊法，以至傾危。」","sentenceOrder":73},
  {"id":"s_work_han_thu_114_74","chapterId":"ch_work_han_thu_114","textTraditional":"〔一二〕師古曰：「言假令太后昔時不得其志，不依常理，而皇后今被親厚，何可踰於太后制度乎？婦不可踰姑也。惡音烏。」","sentenceOrder":74},
  {"id":"s_work_han_thu_114_75","chapterId":"ch_work_han_thu_114","textTraditional":"〔一三〕師古曰：「稱，副也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_114_76","chapterId":"ch_work_han_thu_114","textTraditional":"〔一四〕師古曰：「以謙約為先。」","sentenceOrder":76},
  {"id":"s_work_han_thu_114_77","chapterId":"ch_work_han_thu_114","textTraditional":"〔一五〕師古曰：「東宮，太后所居也。朔望，朝謁之禮也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_114_78","chapterId":"ch_work_han_thu_114","textTraditional":"〔一六〕師古曰：「究，竟也。爰，于也。臧，善也。于何不善，言何事而不善也。」","sentenceOrder":78},
  {"id":"s_work_han_thu_114_79","chapterId":"ch_work_han_thu_114","textTraditional":"〔一七〕師古曰：「讙，譁，眾議也，音許元反。」","sentenceOrder":79},
  {"id":"s_work_han_thu_114_80","chapterId":"ch_work_han_thu_114","textTraditional":"〔一八〕師古曰：「言垂法於後宮，使皆遵行也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_114_81","chapterId":"ch_work_han_thu_114","textTraditional":"是時大將軍鳳用事，威權尤盛。其後，比三年日蝕，〔一〕言事者頗歸咎於鳳矣。而谷永等遂著之許氏，許氏自知為鳳所不佑。〔二〕久之，皇后寵亦益衰，而後宮多新愛。后姊平安剛侯夫人謁等為媚道祝謯後宮有身者王美人及鳳等，〔三〕事發覺，太后大怒，下吏考問，謁等誅死，許后坐廢處昭臺宮，〔四〕親屬皆歸故郡山陽，后弟子平恩侯旦就國。凡立十四年而廢，在昭臺歲餘，還徙長定宮。〔五〕","sentenceOrder":81},
  {"id":"s_work_han_thu_114_82","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「比，頻也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_114_83","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「佑，助也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_114_84","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「謯，古詛字。」","sentenceOrder":84},
  {"id":"s_work_han_thu_114_85","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「在上林苑中。」","sentenceOrder":85},
  {"id":"s_work_han_thu_114_86","chapterId":"ch_work_han_thu_114","textTraditional":"〔五〕　師古曰：「三輔黃圖林光宮有長定宮。」","sentenceOrder":86},
  {"id":"s_work_han_thu_114_87","chapterId":"ch_work_han_thu_114","textTraditional":"後九年，上憐許氏，下詔曰：「蓋聞仁不遺遠，誼不忘親。前平安剛侯夫人謁坐大逆罪，家屬幸蒙赦令，歸故郡。朕惟平恩戴侯，先帝外祖，魂神廢棄，莫奉祭祀，念之未嘗忘于心。其還平恩侯旦及親屬在山陽郡者。」是歲，廢后敗。先是廢后姊孊寡居，與定陵侯淳于長私通，〔一〕因為之小妻。長紿之曰：〔二〕「我能白東宮，復立許后為左皇后。」廢后因孊私賂遺長，數通書記相報謝。長書有誖謾，〔三〕發覺，天子使廷尉孔光持節賜廢后藥，自殺，葬延陵交道廄西。","sentenceOrder":87},
  {"id":"s_work_han_thu_114_88","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「孊者，后姊之名也，音靡。」","sentenceOrder":88},
  {"id":"s_work_han_thu_114_89","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「紿，誑也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_114_90","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「誖，惑亂也。謾，媟汙也。誖音布內反。謾與慢同。」","sentenceOrder":90},
  {"id":"s_work_han_thu_114_91","chapterId":"ch_work_han_thu_114","textTraditional":"孝成班婕妤，帝初即位選入後宮。始為少使，蛾而大幸，〔一〕為婕妤，居增成舍，〔二〕再就館，〔三〕有男，數月失之。成帝遊於後庭，嘗欲與婕妤同輦載，婕妤辭曰：「觀古圖畫，賢聖之君皆有名臣在側，三代末主乃有嬖女，〔四〕今欲同輦，得無近似之乎？」〔五〕上善其言而止。太后聞之，喜曰：「古有樊姬，今有班婕妤。」〔六〕婕妤誦詩及窈窕、德象、女師之篇。〔七〕每進見上疏，依則古禮。〔八〕","sentenceOrder":91},
  {"id":"s_work_han_thu_114_92","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　如淳曰：「蛾，無幾之頃也。」師古曰：「蛾與俄同，古字通用。」","sentenceOrder":92},
  {"id":"s_work_han_thu_114_93","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　應劭曰：「後宮有八區，增成第三也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_114_94","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　蘇林曰：「外舍產子也。」晉灼曰：「謂陽祿與柘觀。」","sentenceOrder":94},
  {"id":"s_work_han_thu_114_95","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「嬖，愛也，音必計反。」","sentenceOrder":95},
  {"id":"s_work_han_thu_114_96","chapterId":"ch_work_han_thu_114","textTraditional":"〔五〕　師古曰：「近音鉅靳反。」","sentenceOrder":96},
  {"id":"s_work_han_thu_114_97","chapterId":"ch_work_han_thu_114","textTraditional":"〔六〕　張晏曰：「楚王好田，樊姬為不食禽獸之肉。」","sentenceOrder":97},
  {"id":"s_work_han_thu_114_98","chapterId":"ch_work_han_thu_114","textTraditional":"〔七〕　師古曰：「詩謂關雎以下也。窈窕、德象、女師之篇，皆古箴戒之書也。故傳云誦詩及窈窕以下諸篇，明詩外別有此篇耳。而說者便謂窈窕等即是詩篇，蓋失之矣。」","sentenceOrder":98},
  {"id":"s_work_han_thu_114_99","chapterId":"ch_work_han_thu_114","textTraditional":"〔八〕　師古曰：「則，法也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_114_100","chapterId":"ch_work_han_thu_114","textTraditional":"自鴻嘉後，上稍隆於內寵。婕妤進侍者李平，平得幸，立為婕妤。上曰：「始衛皇后亦從微起。」乃賜平姓曰衛，所謂衛婕妤也。其後趙飛燕姊弟亦從自微賤興，踰越禮制，寖盛於前。〔一〕班婕妤及許皇后皆失寵，稀復進見。鴻嘉三年，趙飛燕譖告許皇后、班婕妤挾媚道，祝詛後宮，詈及主上。許皇后坐廢。考問班婕妤，婕妤對曰：「妾聞『死生有命，富貴在天。』〔二〕修正尚未蒙福，為邪欲以何望？使鬼神有知，不受不臣之愬；〔三〕如其無知，愬之何益？故不為也。」上善其對，憐憫之，賜黃金百斤。","sentenceOrder":100},
  {"id":"s_work_han_thu_114_101","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「隃與踰同。寖，漸也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_114_102","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「論語載子夏對司馬牛之言也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_114_103","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「祝詛主上是不臣也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_114_104","chapterId":"ch_work_han_thu_114","textTraditional":"趙氏姊弟驕妒，婕妤恐久見危，求共養太后長信宮，〔一〕上許焉。婕妤退處東宮，作賦自傷悼，其辭曰：","sentenceOrder":104},
  {"id":"s_work_han_thu_114_105","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「共音居用反。養音弋向反。」","sentenceOrder":105},
  {"id":"s_work_han_thu_114_106","chapterId":"ch_work_han_thu_114","textTraditional":"承祖考之遺德兮，何性命之淑靈，〔一〕登薄軀於宮闕兮，充下陳於後庭。〔二〕蒙聖皇之渥惠兮，當日月之盛明，〔三〕揚光烈之翕赫兮，奉隆寵於增成。既過幸於非位兮，竊庶幾乎嘉時，〔四〕每寤寐而絫息兮，申佩離以自思，〔五〕陳女圖以鏡監兮，顧女史而問詩。悲晨婦之作戒兮，〔六〕哀褒、閻之為郵；〔七〕美皇、英之女虞兮，榮任、姒之母周。〔八〕雖愚陋其靡及兮，敢舍心而忘茲？〔九〕歷年歲而悼懼兮，閔蕃華之不滋。〔一０〕痛陽祿與柘館兮，仍繈褓而離災，〔一一〕豈妾人之殃咎兮？將天命之不可求。","sentenceOrder":106},
  {"id":"s_work_han_thu_114_107","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「何，任也，負也。」","sentenceOrder":107},
  {"id":"s_work_han_thu_114_108","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「陳，列也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_114_109","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「渥，厚也。」","sentenceOrder":109},
  {"id":"s_work_han_thu_114_110","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「嘉，善也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_114_111","chapterId":"ch_work_han_thu_114","textTraditional":"〔五〕　師古曰：「絫息，言懼而喘息也。離，袿衣之帶也。女子適人，父親結其離而戒之，故云自思也。絫，古累字。」","sentenceOrder":111},
  {"id":"s_work_han_thu_114_112","chapterId":"ch_work_han_thu_114","textTraditional":"〔六〕　張晏曰：「書云『牝雞之晨，惟家之索』，喻婦人無男事也。」","sentenceOrder":112},
  {"id":"s_work_han_thu_114_113","chapterId":"ch_work_han_thu_114","textTraditional":"〔七〕　師古曰：「小雅刺幽王之詩曰『赫赫宗周，褒姒滅之』，『閻妻煽方處』，故云為郵。郵，過也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_114_114","chapterId":"ch_work_han_thu_114","textTraditional":"〔八〕　師古曰：「皇，娥皇，英，女英，堯之二女也。女，妻也。虞，虞舜也。任，太任，文王之母；姒，太姒，武王之母也。女虞，女音尼據反。」","sentenceOrder":114},
  {"id":"s_work_han_thu_114_115","chapterId":"ch_work_han_thu_114","textTraditional":"〔九〕　師古曰：「舍，息也。」","sentenceOrder":115},
  {"id":"s_work_han_thu_114_116","chapterId":"ch_work_han_thu_114","textTraditional":"〔一０〕師古曰：「滋，益也。言時逝不留，華色落也。蕃音扶元反。」","sentenceOrder":116},
  {"id":"s_work_han_thu_114_117","chapterId":"ch_work_han_thu_114","textTraditional":"〔一一〕服虔曰：「二館名也，生子此館，皆失之也。」師古曰：「二觀並在上林中。仍，頻也。離，遭也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_114_118","chapterId":"ch_work_han_thu_114","textTraditional":"白日忽已移光兮，遂晻莫而昧幽，〔一〕猶被覆載之厚德兮，不廢捐於罪郵。〔二〕奉共養于東宮兮，託長信之末流，〔三〕共洒埽於帷幄兮，永終死以為期。〔四〕願歸骨於山足兮，依松柏之餘休。〔五〕","sentenceOrder":118},
  {"id":"s_work_han_thu_114_119","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「晻與暗同，又音烏感反。莫讀曰暮。一曰，莫，靜也，讀如本字。」","sentenceOrder":119},
  {"id":"s_work_han_thu_114_120","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「言主上之恩比於天地，雖有罪過，不廢棄也。被音皮義反。」","sentenceOrder":120},
  {"id":"s_work_han_thu_114_121","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「末流謂恩顧之末也。一曰流謂等列也。共音居用反。養音弋向反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_114_122","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「共音居容反。洒音灑，又音所寄反。埽音先到反。」","sentenceOrder":122},
  {"id":"s_work_han_thu_114_123","chapterId":"ch_work_han_thu_114","textTraditional":"〔五〕　師古曰：「山足謂陵下也。休，蔭也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_114_124","chapterId":"ch_work_han_thu_114","textTraditional":"重曰：〔一〕潛玄宮兮幽以清，應門閉兮禁闥扃。〔二〕華殿塵兮玉階菭，中庭萋兮綠草生。〔三〕廣室陰兮帷幄暗，房櫳虛兮風泠泠。〔四〕感帷裳兮發紅羅，紛綷縩兮紈素聲。〔五〕神眇眇兮密靚處，君不御兮誰為榮？〔六〕俯視兮丹墀，思君兮履綦。〔七〕仰視兮雲屋，雙涕兮橫流。〔八〕顧左右兮和顏，酌羽觴兮銷憂〔九〕。惟人生兮一世，忽一過兮若浮。已獨享兮高明，處生民兮極休。〔一０〕勉虞精兮極樂，與福祿兮無期。〔一一〕綠衣兮白華，自古兮有之。〔一二〕","sentenceOrder":124},
  {"id":"s_work_han_thu_114_125","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「重者，情志未申，更作賦也。音直用反。」","sentenceOrder":125},
  {"id":"s_work_han_thu_114_126","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「正門謂之應門。扃，短關也，音工熒反。」","sentenceOrder":126},
  {"id":"s_work_han_thu_114_127","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「菭，水氣所生也。萋萋，青草貌也。菭音臺。萋音妻。」","sentenceOrder":127},
  {"id":"s_work_han_thu_114_128","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「櫳，疏檻也，音來東反。泠音零。」","sentenceOrder":128},
  {"id":"s_work_han_thu_114_129","chapterId":"ch_work_han_thu_114","textTraditional":"〔五〕　師古曰：「感，動也。言風動發帷裳羅綺也。綷縩，衣聲也。綷音千賄反。縩音蔡。」","sentenceOrder":129},
  {"id":"s_work_han_thu_114_130","chapterId":"ch_work_han_thu_114","textTraditional":"〔六〕　師古曰：「靚字與靜同。」","sentenceOrder":130},
  {"id":"s_work_han_thu_114_131","chapterId":"ch_work_han_thu_114","textTraditional":"〔七〕　孟康曰：「丹墀，赤地也。」師古曰：「綦，履下飾也。言視殿上之地，則想君履綦之跡也。綦音其。」","sentenceOrder":131},
  {"id":"s_work_han_thu_114_132","chapterId":"ch_work_han_thu_114","textTraditional":"〔八〕　師古曰：「雲屋，言其黮{雨對}，狀若雲也。黮音徒感反。{雨對}音徒對反。」","sentenceOrder":132},
  {"id":"s_work_han_thu_114_133","chapterId":"ch_work_han_thu_114","textTraditional":"〔九〕　劉德曰：「酒行疾如羽也。」孟康曰：「羽觴，爵也，作生爵形，有頭尾羽翼。」如淳曰：「以玳瑁覆翠羽於下徹上見。」師古曰：「孟說是也。」","sentenceOrder":133},
  {"id":"s_work_han_thu_114_134","chapterId":"ch_work_han_thu_114","textTraditional":"〔一０〕師古曰：「享，當也。休，美也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_114_135","chapterId":"ch_work_han_thu_114","textTraditional":"〔一一〕師古曰：「此虞與娛同。」","sentenceOrder":135},
  {"id":"s_work_han_thu_114_136","chapterId":"ch_work_han_thu_114","textTraditional":"〔一二〕師古曰：「綠衣，詩鄁風刺妾上僭夫人失位。白華，小雅篇，周人刺幽王黜申后也。」","sentenceOrder":136},
  {"id":"s_work_han_thu_114_137","chapterId":"ch_work_han_thu_114","textTraditional":"至成帝崩，婕妤充奉園陵，薨，因葬園中。","sentenceOrder":137},
  {"id":"s_work_han_thu_114_138","chapterId":"ch_work_han_thu_114","textTraditional":"孝成趙皇后，本長安宮人。〔一〕初生時，父母不舉，三日不死，乃收養之。及壯，屬陽阿主家，〔二〕學歌舞，號曰飛燕。〔三〕成帝嘗微行出，過陽阿主，作樂。上見飛燕而說之，〔四〕召入宮，大幸。有女弟復召入，俱為婕妤，貴傾後宮。","sentenceOrder":138},
  {"id":"s_work_han_thu_114_139","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「本宮人以賜陽阿主家也。宮人者，省中侍使官婢，名曰宮人，非天子掖庭中也。事見漢舊儀。言長安者，以別甘泉等諸宮省也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_114_140","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「陽阿，平原之縣也。今俗事阿字作河。又或為河陽，皆後人所妄改耳。」","sentenceOrder":140},
  {"id":"s_work_han_thu_114_141","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「以其體輕故也。」","sentenceOrder":141},
  {"id":"s_work_han_thu_114_142","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「說讀曰悅。」","sentenceOrder":142},
  {"id":"s_work_han_thu_114_143","chapterId":"ch_work_han_thu_114","textTraditional":"許后之廢也，上欲立趙婕妤。皇太后嫌其所出微甚，難之。太后姊子淳于長為侍中，數往來傳語，得太后指，上立封趙婕妤父臨為成陽侯。後月餘，乃立婕妤為皇后。追以長前白罷昌陵功，封為定陵侯。","sentenceOrder":143},
  {"id":"s_work_han_thu_114_144","chapterId":"ch_work_han_thu_114","textTraditional":"皇后既立，後寵少衰，而弟絕幸，為昭儀。居昭陽舍，其中庭彤朱，而殿上髤漆，〔一〕切皆銅沓（冒）黃金塗，〔二〕白玉階〔三〕，壁帶往往為黃金釭，函藍田璧，明珠、翠羽飾之，〔四〕自後宮未嘗有焉。姊弟顓寵十餘年，卒皆無子。〔五〕","sentenceOrder":144},
  {"id":"s_work_han_thu_114_145","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「以漆漆物謂之髤，音許求反，又許昭反。今關東俗，器物一再著漆者謂之捎漆。捎即髤聲之轉重耳。髤字或作髹，音義亦與髤同。今關西俗云墨髤盤，朱髤盤，其音如此，兩義並通。」","sentenceOrder":145},
  {"id":"s_work_han_thu_114_146","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「切，門限也，音千結反。沓，冒其頭也。塗，以金塗銅上也。沓音它合反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_114_147","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「階，所由升殿陛也。」","sentenceOrder":147},
  {"id":"s_work_han_thu_114_148","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　服虔曰：「釭，壁中之橫帶也。」晉灼曰：「以金環飾之也。」師古曰：「壁帶，壁之橫木露出如帶者也。於壁帶之中，往往以金為釭，若車釭之形也。其釭中著玉璧、明珠、翠羽耳。藍田，山名，出美玉。釭音工，流俗讀之音江，非也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_114_149","chapterId":"ch_work_han_thu_114","textTraditional":"〔五〕　師古曰：「顓與專同。卒，終也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_114_150","chapterId":"ch_work_han_thu_114","textTraditional":"末年，定陶王來朝，王祖母傅太后私賂遺趙皇后、昭儀，定陶王竟為太子。","sentenceOrder":150},
  {"id":"s_work_han_thu_114_151","chapterId":"ch_work_han_thu_114","textTraditional":"明年春，成帝崩。帝素彊，無疾病。是時楚思王衍、梁王立來朝，明旦當辭去，上宿供張白虎殿。〔一〕又欲拜左將軍孔光為丞相，已刻侯印書贊。〔二〕昏夜平善，鄉晨，傅絝韤〔三〕欲起，因失衣，不能言，晝漏上十刻而崩。民間歸罪趙昭儀，皇太后詔大司馬莽、丞相大司空曰：「皇帝暴崩，群眾讙譁怪之。掖庭令輔等在後庭左右，侍燕迫近，雜與御史、丞相、廷尉治問皇帝起居發病狀。」趙昭儀自殺。","sentenceOrder":151},
  {"id":"s_work_han_thu_114_152","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「白虎殿在未央宮中。供音居用反。張音竹亮反。」","sentenceOrder":152},
  {"id":"s_work_han_thu_114_153","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「贊謂延拜之文。」","sentenceOrder":153},
  {"id":"s_work_han_thu_114_154","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　應劭曰：「傅，著也。」師古曰：「鄉讀曰嚮。傅讀曰附。絝，古袴字也。韤音武伐反。」","sentenceOrder":154},
  {"id":"s_work_han_thu_114_155","chapterId":"ch_work_han_thu_114","textTraditional":"哀帝既立，尊趙皇后為皇太后，封太后弟侍中駙馬都尉欽為新成侯。趙氏侯者凡二人。後數月，司隸解光奏言：","sentenceOrder":155},
  {"id":"s_work_han_thu_114_156","chapterId":"ch_work_han_thu_114","textTraditional":"臣聞許美人及故中宮史曹宮皆御幸孝成皇帝，產子，子隱不見。","sentenceOrder":156},
  {"id":"s_work_han_thu_114_157","chapterId":"ch_work_han_thu_114","textTraditional":"臣遣從事掾業、史望〔一〕驗問知狀者掖庭獄丞籍武，故中黃門王舜、吳恭、靳嚴，官婢曹曉、道房、張棄，故趙昭儀御者于客子、王偏、臧兼等，皆曰宮即曉子女，前屬中宮，為學事史，通詩，授皇后。房與宮對食，〔二〕元延元年中宮語房曰：「陛下幸宮。」後數月，曉入殿中，見宮腹大，問宮。宮曰：「御幸有身。」其十月中，宮乳掖庭牛官令舍，〔三〕有婢六人。中黃門田客持詔記，盛綠綈方底，〔四〕封御史中丞印，予武曰：「取牛官令舍婦人新產兒，婢六人，盡置暴室獄，毋問兒男女，誰兒也！」武迎置獄。宮曰：「善臧我兒胞，〔五〕丞知是何等兒也！」〔六〕後三日，客持詔記與武，問「兒死未？手書對牘背。」〔七〕武即書對：「兒見在，未死。」有頃，客出曰：「上與昭儀大怒，奈何不殺？」武叩頭啼曰：「不殺兒，自知當死；殺之，亦死！」即因客奏封事，曰：「陛下未有繼嗣，子無貴賤，唯留意！」奏入，客復持詔記予武曰：「今夜漏上五刻，持兒與舜，會東交掖門。」武因問客：「陛下得武書，意何如？」曰：「憆也。」〔八〕武以兒付舜。舜受詔，內兒殿中，為擇乳母，告「善養兒，且有賞。毋令漏泄！」舜擇棄為乳母，時兒生八九日。後三日，客復持詔記，封如前予武，中有封小綠篋，記曰：「告武以篋中物書予獄中婦人，武自臨飲之。」〔九〕武發篋中有裹藥二枚，赫蹄書，〔一０〕曰「告偉能：努力飲此藥，不可復入。女自知之！」〔一一〕偉能即宮。宮讀書已，曰：「果也，欲姊弟擅天下！我兒男也，額上有壯髮，類孝元皇帝。〔一二〕今兒安在？危殺之矣！〔一三〕奈何令長信得聞之？」〔一四〕宮飲藥死。後宮婢六人召入，出語武曰：「昭儀言『女無過。〔一五〕寧自殺邪，若外家也？』〔一六〕我曹言願自殺。」〔一七〕即自繆死。〔一八〕武皆表奏狀。棄所養兒十一日，〔一九〕宮長李南以詔書取兒去，〔二０〕不知所置。〔二一〕","sentenceOrder":157},
  {"id":"s_work_han_thu_114_158","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「業者掾之名，望者史之名也，皆不言其姓。」","sentenceOrder":158},
  {"id":"s_work_han_thu_114_159","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　應劭曰：「宮人自相與為夫婦名對食，甚相妒忌也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_114_160","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「乳，產也，音而具反。下皆類此。」","sentenceOrder":160},
  {"id":"s_work_han_thu_114_161","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「綈，厚繒也。綠，其色也。方底，盛書囊，形若今之算幐耳。綈音大奚反。」","sentenceOrder":161},
  {"id":"s_work_han_thu_114_162","chapterId":"ch_work_han_thu_114","textTraditional":"〔五〕　師古曰：「胞謂胎之衣也，音苞。」","sentenceOrder":162},
  {"id":"s_work_han_thu_114_163","chapterId":"ch_work_han_thu_114","textTraditional":"〔六〕　師古曰：「意言是天子兒耳。」","sentenceOrder":163},
  {"id":"s_work_han_thu_114_164","chapterId":"ch_work_han_thu_114","textTraditional":"〔七〕　師古曰：「牘，木簡也。時以為詔記問之，故令於背上書對辭。」","sentenceOrder":164},
  {"id":"s_work_han_thu_114_165","chapterId":"ch_work_han_thu_114","textTraditional":"〔八〕　服虔曰：「憆，直視貌也。」師古曰：「憆音丑庚反。字本作瞠，其音同耳。」","sentenceOrder":165},
  {"id":"s_work_han_thu_114_166","chapterId":"ch_work_han_thu_114","textTraditional":"〔九〕　師古曰：「飲音於禁反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_114_167","chapterId":"ch_work_han_thu_114","textTraditional":"〔一０〕孟康曰：「蹄猶地也，染紙素令赤而書之，若今黃紙也。」鄧展曰：「赫音兄弟鬩牆之鬩。」應劭曰：「赫蹄，薄小紙也。」晉灼曰：「今謂薄小物為鬩蹄。鄧音應說是也。」師古曰：「孟說非也。今書本赫字或作擊。」","sentenceOrder":167},
  {"id":"s_work_han_thu_114_168","chapterId":"ch_work_han_thu_114","textTraditional":"〔一一〕師古曰：「女讀曰汝。」","sentenceOrder":168},
  {"id":"s_work_han_thu_114_169","chapterId":"ch_work_han_thu_114","textTraditional":"〔一二〕師古曰：「壯髮，當頟前侵下而生，今俗呼為圭頭者是也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_114_170","chapterId":"ch_work_han_thu_114","textTraditional":"〔一三〕師古曰：「危，險也。猶今人言險不殺耳。」","sentenceOrder":170},
  {"id":"s_work_han_thu_114_171","chapterId":"ch_work_han_thu_114","textTraditional":"〔一四〕師古曰：「謂太后。」","sentenceOrder":171},
  {"id":"s_work_han_thu_114_172","chapterId":"ch_work_han_thu_114","textTraditional":"〔一五〕師古曰：「言我知汝無罪過也。女讀曰汝。」","sentenceOrder":172},
  {"id":"s_work_han_thu_114_173","chapterId":"ch_work_han_thu_114","textTraditional":"〔一六〕晉灼曰：「寧便自殺，出至外舍死也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_114_174","chapterId":"ch_work_han_thu_114","textTraditional":"〔一七〕師古曰：「曹，輩也。」","sentenceOrder":174},
  {"id":"s_work_han_thu_114_175","chapterId":"ch_work_han_thu_114","textTraditional":"〔一八〕晉灼曰：「繆音繆縛之繆。」鄭氏曰：「自縊也。」師古曰：「繆，絞也，音居虯反。」","sentenceOrder":175},
  {"id":"s_work_han_thu_114_176","chapterId":"ch_work_han_thu_114","textTraditional":"〔一九〕師古曰：「棄謂張棄也。」","sentenceOrder":176},
  {"id":"s_work_han_thu_114_177","chapterId":"ch_work_han_thu_114","textTraditional":"〔二０〕晉灼曰：「漢儀注有女長御，比侍中。宮長豈此邪？」","sentenceOrder":177},
  {"id":"s_work_han_thu_114_178","chapterId":"ch_work_han_thu_114","textTraditional":"〔二一〕師古曰：「終竟不知置何所也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_114_179","chapterId":"ch_work_han_thu_114","textTraditional":"許美人前在上林涿沐館，數召入飾室中若舍，〔一〕一歲再三召，留數月或半歲御幸。元延二年褱子，〔二〕其十一月乳。〔三〕詔使嚴持乳毉及五種和藥丸三，送美人所。後客子、偏、兼聞昭儀謂成帝曰：「常紿我言從（宮中）〔中宮〕來，〔四〕即從中宮來，許美人兒何從生中？許氏竟當復立邪！」〔五〕懟，以手自擣，〔六〕以頭擊壁戶柱，從床上自投地，啼泣不肯食，曰：「今當安置我，欲歸耳！」帝曰：「今故告之，反怒為！〔七〕殊不可曉也。」〔八〕帝亦不食。昭儀曰：「陛下自知是，不食為何？〔九〕陛下常自言『約不負女』，〔一０〕今美人有子，竟負約，謂何？」帝曰：「約以趙氏，故不立許氏。使天下無出趙氏上者，毋憂也！」後詔使嚴持綠囊書予許美人，告嚴曰：「美人當有以予女，受來，置飾室中簾南。」〔一一〕美人以葦篋一合盛所生兒，緘封，及綠囊報書予嚴。嚴持篋書，置飾室簾南去。帝與昭儀坐，使客子解篋緘。未已，〔一二〕帝使客子、偏、兼皆出，自閉戶，獨與昭儀在。須臾開戶，呼客子、偏、兼，使緘封篋及綠綈方底，推置屏風東。恭受詔，持篋方底予武，皆封以御史中丞印，曰：「告武：篋中有死兒，埋屏處，勿令人知。」武穿獄樓垣下為坎，埋其中。","sentenceOrder":179},
  {"id":"s_work_han_thu_114_180","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「或暫入，或留止也。」","sentenceOrder":180},
  {"id":"s_work_han_thu_114_181","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「褱，本懷字。」","sentenceOrder":181},
  {"id":"s_work_han_thu_114_182","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「乳謂產子也，音而樹反。其下亦同。」","sentenceOrder":182},
  {"id":"s_work_han_thu_114_183","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「紿，誑也。中宮，皇后所居。」","sentenceOrder":183},
  {"id":"s_work_han_thu_114_184","chapterId":"ch_work_han_thu_114","textTraditional":"〔五〕　晉灼曰：「昭儀前要帝不得立許美人為皇后，而今有子中，許氏竟當復立為皇后邪！此前約之言也。」師古曰：「此說非也。言美人在內中，何從得兒而生也，故言何從生中。次此下，乃始言約耳。」","sentenceOrder":184},
  {"id":"s_work_han_thu_114_185","chapterId":"ch_work_han_thu_114","textTraditional":"〔六〕　師古曰：「懟，怨怒也。擣，築也。懟音直類反。」","sentenceOrder":185},
  {"id":"s_work_han_thu_114_186","chapterId":"ch_work_han_thu_114","textTraditional":"〔七〕　師古曰：「故以許美人產子告汝，何為反怒？」","sentenceOrder":186},
  {"id":"s_work_han_thu_114_187","chapterId":"ch_work_han_thu_114","textTraditional":"〔八〕　師古曰：「言其不可告語也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_114_188","chapterId":"ch_work_han_thu_114","textTraditional":"〔九〕　師古曰：「何為不食也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_114_189","chapterId":"ch_work_han_thu_114","textTraditional":"〔一０〕師古曰：「女讀曰汝。次下亦同。」","sentenceOrder":189},
  {"id":"s_work_han_thu_114_190","chapterId":"ch_work_han_thu_114","textTraditional":"〔一一〕師古曰：「簾，戶簾也，音廉。」","sentenceOrder":190},
  {"id":"s_work_han_thu_114_191","chapterId":"ch_work_han_thu_114","textTraditional":"〔一二〕師古曰：「緘，束篋之繩也，音居咸反。」","sentenceOrder":191},
  {"id":"s_work_han_thu_114_192","chapterId":"ch_work_han_thu_114","textTraditional":"故長定許貴人及故成都、平阿侯家婢王業、任孋、公孫習前免為庶人，〔一〕詔召入，屬昭儀為私婢。成帝崩，未幸梓宮，〔二〕倉卒悲哀之時，昭儀自知罪惡大，知業等故許氏、王氏婢，恐事泄，而以大婢羊子等賜予業等各且十人，以慰其意，屬無道我家過失。〔三〕","sentenceOrder":192},
  {"id":"s_work_han_thu_114_193","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「孋音麗。」","sentenceOrder":193},
  {"id":"s_work_han_thu_114_194","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「言未入斂也。」","sentenceOrder":194},
  {"id":"s_work_han_thu_114_195","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「屬音之欲反。」","sentenceOrder":195},
  {"id":"s_work_han_thu_114_196","chapterId":"ch_work_han_thu_114","textTraditional":"元延二年五月，故掖庭令吾丘遵謂武曰：〔一〕「掖庭丞吏以下皆與昭儀合通，無可與語者，獨欲與武有所言。我無子，武有子，是家輕族人，得無不敢乎？〔二〕掖庭中御幸生子者輒死，又飲藥傷墯者無數，欲與武共言之大臣，票騎將軍貪耆錢，不足計事，〔三〕奈何令長信得聞之？」遵後病困，謂武：「今我已死，前所語事，武不能獨為也，慎語！」〔四〕","sentenceOrder":196},
  {"id":"s_work_han_thu_114_197","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「姓吾丘，名遵。」","sentenceOrder":197},
  {"id":"s_work_han_thu_114_198","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　蘇林曰：「是家謂成帝也。不敢斥，故言是家。」師古曰：「遵自以無子，故無所顧懼，武既有子，恐禍相及，當止不敢言也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_114_199","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「耆讀曰嗜。」","sentenceOrder":199},
  {"id":"s_work_han_thu_114_200","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「言汝脫不能獨為，勿漏泄其語。」","sentenceOrder":200},
  {"id":"s_work_han_thu_114_201","chapterId":"ch_work_han_thu_114","textTraditional":"皆在今年四月丙辰赦令前。臣謹案永光三年男子忠等發長陵傅夫人冢。事更大赦，〔一〕孝元皇帝下詔曰：「（比）〔此〕朕不當所得赦也。」窮治，盡伏辜，天下以為當。魯嚴公夫人殺世子，齊桓召而誅焉，春秋予之。〔二〕趙昭儀傾亂聖朝，親滅繼嗣，家屬當伏天誅。前平安剛侯夫人謁坐大逆，同產當坐，以蒙赦令，歸故郡。今昭儀所犯尤誖逆，罪重於謁，而同產親屬皆在尊貴之位，迫近幃幄，〔三〕群下寒心，非所以懲惡崇誼示四方也。請事窮竟，丞相以下議正法。","sentenceOrder":201},
  {"id":"s_work_han_thu_114_202","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「更音工衡反。」","sentenceOrder":202},
  {"id":"s_work_han_thu_114_203","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「嚴公夫人謂哀姜也。予謂許予之也。解具在五行志。」","sentenceOrder":203},
  {"id":"s_work_han_thu_114_204","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「近音鉅靳反。」","sentenceOrder":204},
  {"id":"s_work_han_thu_114_205","chapterId":"ch_work_han_thu_114","textTraditional":"哀帝於是免新成侯趙欽、欽兄子成陽侯訢，皆為庶人，將家屬徙遼西郡。時議郎耿育上疏言：","sentenceOrder":205},
  {"id":"s_work_han_thu_114_206","chapterId":"ch_work_han_thu_114","textTraditional":"臣聞繼嗣失統，廢適立庶，〔一〕聖人法禁，古今至戒。然大伯見歷知適，逡循固讓，〔二〕委身吳粵，權變所設，不計常法，致位王季，以崇聖嗣，卒有天下，〔三〕子孫承業，七八百載，功冠三王，道德最備，是以尊號追及大王。故世必有非常之變，然後乃有非常之謀。孝成皇帝自知繼嗣不以時立，念雖末有皇子，萬歲之後未能持國，〔四〕權柄之重，制於女主，女主驕盛則耆欲無極，〔五〕少主幼弱則大臣不使，〔六〕世無周公抱負之輔，恐危社稷，傾亂天下。知陛下有賢聖通明之德，仁孝子愛之恩，懷獨見之明，內斷於身，故廢後宮就館之漸，絕微嗣禍亂之根，〔七〕乃欲致位陛下以安宗廟。愚臣既不能深援安危，定金匱之計，〔八〕又不知推演聖德，述先帝之志，〔九〕乃反覆校省內，暴露私燕，〔一０〕誣汙先帝傾惑之過，成結寵妾妒媚之誅，甚失賢聖遠見之明，逆負先帝憂國之意。","sentenceOrder":206},
  {"id":"s_work_han_thu_114_207","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「適讀曰嫡。次下亦同。」","sentenceOrder":207},
  {"id":"s_work_han_thu_114_208","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「歷謂王季，即文王之父也。知適謂知其當為適嗣也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_114_209","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「卒，終也。」","sentenceOrder":209},
  {"id":"s_work_han_thu_114_210","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「末，晚暮也。萬歲，言晏駕也。」","sentenceOrder":210},
  {"id":"s_work_han_thu_114_211","chapterId":"ch_work_han_thu_114","textTraditional":"〔五〕　師古曰：「耆讀曰嗜。」","sentenceOrder":211},
  {"id":"s_work_han_thu_114_212","chapterId":"ch_work_han_thu_114","textTraditional":"〔六〕　師古曰：「不使，不可使從命也。」","sentenceOrder":212},
  {"id":"s_work_han_thu_114_213","chapterId":"ch_work_han_thu_114","textTraditional":"〔七〕　師古曰：「微嗣者，謂幼主也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_114_214","chapterId":"ch_work_han_thu_114","textTraditional":"〔八〕　師古曰：「愚臣謂解光等也。援，引也。金匱，言長久之法可藏於金匱石室者也。援音爰。」","sentenceOrder":214},
  {"id":"s_work_han_thu_114_215","chapterId":"ch_work_han_thu_114","textTraditional":"〔九〕　師古曰：「演，廣也，音弋善反。」","sentenceOrder":215},
  {"id":"s_work_han_thu_114_216","chapterId":"ch_work_han_thu_114","textTraditional":"〔一０〕師古曰：「私燕謂成帝閑宴之私也。覆音芳目反。」","sentenceOrder":216},
  {"id":"s_work_han_thu_114_217","chapterId":"ch_work_han_thu_114","textTraditional":"夫論大德不拘俗，立大功不合眾，此乃孝成皇帝至思所以萬萬於眾臣，陛下聖德盛茂所以符合於皇天也，豈當世庸庸斗筲之臣所能及哉！且褒廣將順君父之美，匡捄銷滅既往之過，〔一〕古今通義也。事不當時固爭，防禍於未然，各隨指阿從，以求容媚，晏駕之後，尊號已定，萬事已訖，乃探追不及之事，訐揚幽昧之過，〔二〕此臣所深痛也！","sentenceOrder":217},
  {"id":"s_work_han_thu_114_218","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「捄，古救字。」","sentenceOrder":218},
  {"id":"s_work_han_thu_114_219","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「訐音居謁反。」","sentenceOrder":219},
  {"id":"s_work_han_thu_114_220","chapterId":"ch_work_han_thu_114","textTraditional":"願下有司議，即如臣言，宜宣布天下，使咸曉知先帝聖意所起。不然，空使謗議上及山陵，下流後世，遠聞百蠻，近布海內，甚非先帝託後之意也。蓋孝子善述父之志，善成人之事，唯陛下省察！","sentenceOrder":220},
  {"id":"s_work_han_thu_114_221","chapterId":"ch_work_han_thu_114","textTraditional":"哀帝為太子，亦頗得趙太后力，遂不竟其事。傅太后恩趙太后，趙太后亦歸心，〔一〕故成帝母及王氏皆怨之。","sentenceOrder":221},
  {"id":"s_work_han_thu_114_222","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「恩謂以厚恩接遇之。一曰，恩謂銜其立哀帝為嗣之恩也。」","sentenceOrder":222},
  {"id":"s_work_han_thu_114_223","chapterId":"ch_work_han_thu_114","textTraditional":"哀帝崩，王莽白太后詔有司曰：「前皇太后與昭儀俱侍帷幄，姊弟專寵錮寢，執賊亂之謀，殘滅繼嗣以危宗廟，誖天犯祖，〔一〕無為天下母之義。貶皇太后為孝成皇后，〔二〕徙居北宮。」後月餘，復下詔曰：「皇后自知罪惡深大，朝請希闊，〔三〕失婦道，無共養之禮，而有狼虎之毒，〔四〕宗室所怨，海內之讎也，而尚在小君之位，誠非皇天之心。夫小不忍亂大謀，恩之所不能已者義之所割也，〔五〕今廢皇后為庶人，就其園。」是日自殺。凡立十六年而誅。先是有童謠曰：「燕燕，尾涎涎，〔六〕張公子，時相見。木門倉琅根，燕飛來，啄皇孫。皇孫死，燕啄矢。」成帝每微行出，常與張放俱，而稱富平侯家，故曰張公子。倉琅根，宮門銅鍰也。〔七〕","sentenceOrder":223},
  {"id":"s_work_han_thu_114_224","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「誖，違也。祖，先帝也。」","sentenceOrder":224},
  {"id":"s_work_han_thu_114_225","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　晉灼曰：「使哀帝不母，罪之也。」","sentenceOrder":225},
  {"id":"s_work_han_thu_114_226","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「請，謁也。闊猶闕也。」","sentenceOrder":226},
  {"id":"s_work_han_thu_114_227","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「共讀曰供，音居用反。養音弋向反。其下並同。」","sentenceOrder":227},
  {"id":"s_work_han_thu_114_228","chapterId":"ch_work_han_thu_114","textTraditional":"〔五〕　師古曰：「言以義割恩也。」","sentenceOrder":228},
  {"id":"s_work_han_thu_114_229","chapterId":"ch_work_han_thu_114","textTraditional":"〔六〕　師古曰：「涎涎，光澤之貌也，音徒見反。」","sentenceOrder":229},
  {"id":"s_work_han_thu_114_230","chapterId":"ch_work_han_thu_114","textTraditional":"〔七〕　師古曰：「鍰讀與環同。」","sentenceOrder":230},
  {"id":"s_work_han_thu_114_231","chapterId":"ch_work_han_thu_114","textTraditional":"孝元傅昭儀，哀帝祖母也。父河內溫人，蚤卒，母更嫁為魏郡鄭翁妻，生男惲。昭儀少為上官太后才人，自元帝為太子，得進幸。元帝即位，立為婕妤，甚有寵。為人有材略，善事人，下至宮人左右，飲酒酹地，皆祝延之。〔一〕產一男一女，女為平都公主，男為定陶恭王。恭王有材藝，尤愛於上。元帝既重傅婕妤，及馮婕妤亦幸，生中山孝王，上欲殊之於後宮，以二人皆有子為王，上尚在，未得稱太后，乃更號曰昭儀，賜以印綬，在婕妤上。昭其儀，尊之也。至成、哀時，趙昭儀、董昭儀皆無子，猶稱焉。","sentenceOrder":231},
  {"id":"s_work_han_thu_114_232","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「酹，以酒沃地也。祝延，祝之使長年也。酹音來外反。祝音之受反。」","sentenceOrder":232},
  {"id":"s_work_han_thu_114_233","chapterId":"ch_work_han_thu_114","textTraditional":"元帝崩，傅昭儀隨王歸國，稱定陶太后。後十年，恭王薨，子代為王。王母曰丁姬。傅太后躬自養視，既壯大，成帝無繼嗣。時中山孝王在。元延四年，孝王及定陶王皆入朝。傅太后多以珍寶賂遺趙昭儀及帝舅票騎將軍王根，陰為王求漢嗣。皆見上無子，欲豫自結為久長計，更稱譽定陶王。〔一〕上亦自器之，明年，遂徵定陶王立為太子，語在哀紀。月餘，天子立楚孝王孫景為定陶王，奉恭王後。太子議欲謝，少傅閻崇以為「春秋不以父命廢王父命，〔二〕為人後之禮不得顧私親，不當謝。」太傅趙玄以為當謝，太子從之。詔問所以謝狀，尚書劾奏玄，左遷少府，以光祿勳師丹為太傅。詔傅太后與太子母丁姬自居定陶國邸。下有司議皇太子得與傅太后、丁姬相見不，有司奏議不得相見。頃之，成帝母王太后欲令傅太后、丁姬十日一至太子家，成帝曰：「太子丞正統，當共養陛下，不得復顧私親。」王太后曰：「太子小，而傅太后抱養之，今至太子家，以乳母恩耳，不足有所妨。」於是令傅太后得至太子家。丁姬以不小養太子，獨不得。","sentenceOrder":233},
  {"id":"s_work_han_thu_114_234","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「更音工衡反。」","sentenceOrder":234},
  {"id":"s_work_han_thu_114_235","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「王父謂祖也。」","sentenceOrder":235},
  {"id":"s_work_han_thu_114_236","chapterId":"ch_work_han_thu_114","textTraditional":"成帝崩，哀帝即位。王太后詔令傅太后、丁姬十日一至未央宮。高昌侯董宏希指，〔一〕上書言宜立丁姬為帝太后。師丹劾奏「宏懷邪誤朝，不道。」上初即位，謙讓，從師丹言止。後乃白令王太后下詔，尊定陶恭王為恭皇。哀帝因是曰：「春秋『母以子貴』，尊傅太后為恭皇太后，丁姬為恭皇后，各置左右詹事，食邑如長信宮、中宮。追尊恭皇太后父為崇祖侯，恭皇后父為褒德侯。」後歲餘，遂下詔曰：「漢家之制，推親親以顯尊尊，定陶恭皇之號不宜復稱定陶。其尊恭皇太后為帝太太后，丁后為帝太后。」後又更號帝太太后為皇太太后，稱永信宮，帝太后稱中安宮，而成帝母太皇太后本稱長信宮，成帝趙后為皇太后，並四太后，各置少府、太僕，秩皆中二千石。為恭皇立寢廟於京師，比宣帝父悼皇考制度，序昭穆於前殿。〔二〕","sentenceOrder":236},
  {"id":"s_work_han_thu_114_237","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「希望天子意指也。」","sentenceOrder":237},
  {"id":"s_work_han_thu_114_238","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　如淳曰：「廟之前曰殿，半以後曰寢。」","sentenceOrder":238},
  {"id":"s_work_han_thu_114_239","chapterId":"ch_work_han_thu_114","textTraditional":"傅太后父同產弟四人，曰子孟、中叔、子元、幼君。〔一〕子孟子喜至大司馬，封高武侯。中叔子晏亦大司馬，封孔鄉侯。幼君子商封汝昌侯，為太后父崇祖侯後，更號崇祖曰汝昌哀侯。太后同母弟鄭惲前死，以惲子業為陽信侯，追尊惲為陽信節侯。鄭氏、傅氏侯者凡六人，大司馬二人，九卿二千石六人，侍中諸曹十餘人。","sentenceOrder":239},
  {"id":"s_work_han_thu_114_240","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「中讀曰仲。」","sentenceOrder":240},
  {"id":"s_work_han_thu_114_241","chapterId":"ch_work_han_thu_114","textTraditional":"傅太后既尊，後尤驕，與成帝母語，至謂之嫗。與中山孝王母馮太后並事元帝，追怨之，陷以祝詛罪，令自殺。元壽元年崩，合葬渭陵，稱孝元傅皇后云。","sentenceOrder":241},
  {"id":"s_work_han_thu_114_242","chapterId":"ch_work_han_thu_114","textTraditional":"定陶丁姬，哀帝母也，易祖師丁將軍之玄孫。〔一〕家在山陽瑕丘，父至廬江太守。始定陶恭王先為山陽王，而丁氏內其女為姬。王后姓張氏，其母鄭禮，即傅太后同母弟也。太后以親戚故，欲其有子，然終無有。唯丁姬河平四年生哀帝。丁姬為帝太后，兩兄忠、明。明以帝舅封陽安侯。忠蚤死，封忠子滿為平周侯。太后叔父憲、望。望為左將軍，憲為太僕。明為大司馬票騎將軍輔政。丁氏侯者凡二人，大司馬一人，將軍、九卿、二千石六人，等中諸曹亦十餘人。丁、傅以一二年間暴興尤盛。然哀帝不甚假以權勢，權勢不如王氏在成帝世也。","sentenceOrder":242},
  {"id":"s_work_han_thu_114_243","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「（始祖）〔祖，始〕也。儒林傳丁寬易之始師。」","sentenceOrder":243},
  {"id":"s_work_han_thu_114_244","chapterId":"ch_work_han_thu_114","textTraditional":"建平二年，丁太后崩。上曰：「詩云『穀則異室，死則同穴』。〔一〕昔季武子成寢，杜氏之墓在西階下，請合葬而許之。〔二〕附葬之禮，自周興焉。孝子事亡如事存，帝太后宜起陵恭皇之園。」遣大司馬票騎將軍明東送葬于定陶，貴震山東。","sentenceOrder":244},
  {"id":"s_work_han_thu_114_245","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「王國大車之詩也。穀，生也。」","sentenceOrder":245},
  {"id":"s_work_han_thu_114_246","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「事見禮記。」","sentenceOrder":246},
  {"id":"s_work_han_thu_114_247","chapterId":"ch_work_han_thu_114","textTraditional":"哀帝崩，王莽秉政，使有司舉奏丁、傅罪惡。莽以太皇太后詔皆免官爵，丁氏徙歸故郡。莽奏貶傅太后號為定陶共王母，丁太后號曰丁姬。","sentenceOrder":247},
  {"id":"s_work_han_thu_114_248","chapterId":"ch_work_han_thu_114","textTraditional":"元始五年，莽復言「共王母、丁姬前不臣妾，〔一〕至葬渭陵，冢高與元帝山齊，懷帝太后、皇太太后璽綬以葬，〔二〕不應禮。禮有改葬，請發共王母及丁姬冢，取其璽綬消滅，徙共王母及丁姬歸定陶，葬共王冢次，而葬丁姬復其故。」〔三〕太后以為既已之事，不須復發。莽固爭之，太后詔曰：「因故棺為致槨作冢，〔四〕祠以太牢。」謁者護既發傅太后冢，崩壓殺數百人；開丁姬槨戶，火出炎四五丈，〔五〕吏卒以水沃滅乃得入，燒燔槨中器物。","sentenceOrder":248},
  {"id":"s_work_han_thu_114_249","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「不遵臣妾之道。」","sentenceOrder":249},
  {"id":"s_work_han_thu_114_250","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「懷謂挾之以自隨也。」","sentenceOrder":250},
  {"id":"s_work_han_thu_114_251","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「復音扶目反。」","sentenceOrder":251},
  {"id":"s_work_han_thu_114_252","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「致謂累也。」","sentenceOrder":252},
  {"id":"s_work_han_thu_114_253","chapterId":"ch_work_han_thu_114","textTraditional":"〔五〕　師古曰：「炎音弋贍反。」","sentenceOrder":253},
  {"id":"s_work_han_thu_114_254","chapterId":"ch_work_han_thu_114","textTraditional":"莽復奏言：「前共王母生，僭居桂宮，皇天震怒，災其正殿；丁姬死，葬踰制度，今火焚其槨。此天見變以告，當改如媵妾也。臣前奏請葬丁姬復故，非是。〔一〕共王母及丁姬棺皆名梓宮，珠玉之衣非藩妾服，請更以木棺代，去珠玉衣，葬丁姬媵妾之次。」奏可。既開傅太后棺，臭聞數里。公卿在位皆阿莽指，入錢帛，遣子弟及諸生四夷，凡十餘萬人，操持作具，助將作掘平共王母、丁姬故冢，二旬間皆平。莽又周棘其處以為世戒云。〔二〕時有群燕數千，銜土投丁姬穿中。〔三〕丁、傅既敗，孔鄉侯晏將家屬徙合浦，宗族皆歸故郡。唯高武侯喜得全，自有傳。","sentenceOrder":254},
  {"id":"s_work_han_thu_114_255","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「言尚太優僭也。」","sentenceOrder":255},
  {"id":"s_work_han_thu_114_256","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「以棘周繞也。」","sentenceOrder":256},
  {"id":"s_work_han_thu_114_257","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「穿謂壙中也。」","sentenceOrder":257},
  {"id":"s_work_han_thu_114_258","chapterId":"ch_work_han_thu_114","textTraditional":"孝哀傅皇后，定陶太后從弟子也。哀帝為定陶王時，傅太后欲重親，取以配王。王入為漢太子，傅氏女為妃。哀帝即位，成帝大行尚在前殿，而傅太后封傅妃父晏為孔鄉侯，與帝舅陽安侯丁明同日俱封。時師丹諫，以為「天下自王者所有，親戚何患不富貴？而倉卒若是，其不久長矣！」晏封後月餘，傅妃立為皇后。傅氏既盛，晏最尊重。哀帝崩，王莽白太皇太后詔曰：「定陶共王太后與孔鄉侯晏同心合謀，背恩忘本，專恣不軌，與至尊同稱號，終沒，至乃配食於左坐，〔一〕誖逆無道。今令孝哀皇后退就桂宮。」後月餘，復與孝成趙皇后俱廢為庶人，就其園自殺。","sentenceOrder":258},
  {"id":"s_work_han_thu_114_259","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　應劭曰：「若禮以其妃配者也。坐於左而並食。」師古曰：「坐音材臥反。」","sentenceOrder":259},
  {"id":"s_work_han_thu_114_260","chapterId":"ch_work_han_thu_114","textTraditional":"孝元馮昭儀，平帝祖母也。元帝即位二年，以選入後宮。時父奉世為執金吾。昭儀始為長使，數月至美人，後五年就館生男，拜為婕妤。時父奉世為右將軍光祿勳，奉世長男野王為左馮翊，父子並居朝廷，議者以為器能當其位，非用女寵故也。而馮婕妤內寵與傅昭儀等。","sentenceOrder":260},
  {"id":"s_work_han_thu_114_261","chapterId":"ch_work_han_thu_114","textTraditional":"建昭中，上幸虎圈鬥獸，後宮皆坐。熊佚出圈，〔一〕攀檻欲上殿。左右貴人傅昭儀等皆驚走，馮婕妤直前當熊而立，左右格殺熊。上問：「人情驚懼，何故前當熊？」婕妤對曰：「猛獸得人而止，妾恐熊至御坐，故以身當之。」元帝嗟嘆，以此倍敬重焉。傅昭儀等皆慚。明年夏，馮婕妤男立為信都王，尊婕妤為昭儀。元帝崩，為信都太后，與王俱居儲元宮。〔二〕河平中，隨王之國。後徙中山，是為孝王。","sentenceOrder":261},
  {"id":"s_work_han_thu_114_262","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「佚字與逸同。」","sentenceOrder":262},
  {"id":"s_work_han_thu_114_263","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「黃圖在上林苑中。」","sentenceOrder":263},
  {"id":"s_work_han_thu_114_264","chapterId":"ch_work_han_thu_114","textTraditional":"後徵定陶王為太子，封中山王舅參為宜鄉侯。參，馮太后少弟也。是歲，孝王薨，有一男，嗣為王，時未滿歲，有眚病，〔一〕太后自養視，數禱祠解。〔二〕","sentenceOrder":264},
  {"id":"s_work_han_thu_114_265","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　孟康曰：「災眚之眚，謂妖病也。」服虔曰：「身盡青也。」蘇林曰：「名為肝厥，發時脣口手足十指甲皆青。」師古曰：「下云禱祠解舍，孟說是也。未滿歲者，謂為王未滿歲也。眚音所領反，字不作青，服、（虔）〔蘇〕誤也。」","sentenceOrder":265},
  {"id":"s_work_han_thu_114_266","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「解音懈。」","sentenceOrder":266},
  {"id":"s_work_han_thu_114_267","chapterId":"ch_work_han_thu_114","textTraditional":"哀帝即位，遣中郎謁者張由將毉治中山小王。由素有狂易病〔一〕，病發怒去，西歸長安。尚書簿責擅去狀，〔二〕由恐，因誣言中山太后祝詛上及太后。太后即傅昭儀也，素常怨馮太后，因是遣御史丁玄案驗，盡收御者官吏及馮氏昆弟在國者百餘人，分繫雒陽、魏郡、鉅鹿。數十日無所得，更使中謁者令史立〔三〕與丞相長史大鴻臚丞雜治。立受傅太后指，幾得封侯，〔四〕治馮太后女弟習及寡弟婦君之，死者數十人。巫劉吾服祝詛。毉徐遂成言習、君之曰「武帝時毉修氏刺治武帝得二千萬耳，〔五〕今愈上，不得封侯，不如殺上，令中山王代，可得封。」立等劾奏祝詛謀反，大逆。責問馮太后，無服辭。立曰：「熊之上殿何其勇，今何怯哉！」太后還謂左右：「此乃中語，前世事，〔六〕吏何用知之？是欲陷我效也！」〔七〕乃飲藥自殺。","sentenceOrder":267},
  {"id":"s_work_han_thu_114_268","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「狂易者，狂而變易常性也。」","sentenceOrder":268},
  {"id":"s_work_han_thu_114_269","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「簿責，以文簿一一責問也。」","sentenceOrder":269},
  {"id":"s_work_han_thu_114_270","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「官為中謁者令，姓史，名立。」","sentenceOrder":270},
  {"id":"s_work_han_thu_114_271","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「幾讀曰冀。」","sentenceOrder":271},
  {"id":"s_work_han_thu_114_272","chapterId":"ch_work_han_thu_114","textTraditional":"〔五〕　師古曰：「刺治謂箴之。」","sentenceOrder":272},
  {"id":"s_work_han_thu_114_273","chapterId":"ch_work_han_thu_114","textTraditional":"〔六〕　師古曰：「中語，謂宮中之言語也。」","sentenceOrder":273},
  {"id":"s_work_han_thu_114_274","chapterId":"ch_work_han_thu_114","textTraditional":"〔七〕　師古曰：「效，徵驗也。」","sentenceOrder":274},
  {"id":"s_work_han_thu_114_275","chapterId":"ch_work_han_thu_114","textTraditional":"先未死，有司請誅之，上不忍致法，廢為庶人，徙雲陽宮。既死，有司復奏「太后死在未廢前。」有詔以諸侯王太后儀葬之。宜鄉侯參、君之、習夫及子當相坐者，或自殺，或伏法。參女弁為孝王后，有兩女，有司奏免為庶人，與馮氏宗族徙歸故郡。張由以先告賜爵關內侯，史立遷中太僕。","sentenceOrder":275},
  {"id":"s_work_han_thu_114_276","chapterId":"ch_work_han_thu_114","textTraditional":"哀帝崩，大司徒孔光奏「由前誣告骨肉，立陷人入大辟，為國家結怨於天下，以取秩遷，獲爵邑，幸蒙赦令，請免為庶人，徙合浦」云。","sentenceOrder":276},
  {"id":"s_work_han_thu_114_277","chapterId":"ch_work_han_thu_114","textTraditional":"中山衛姬，平帝母也。父子豪，中山盧奴人，官至衛尉。子豪女弟為宣帝婕妤，生楚孝王；長女又為元帝婕妤，生平陽公主。成帝時，中山孝王無子，上以衛氏吉祥，以子豪少女配孝王。元延四年，生平帝。","sentenceOrder":277},
  {"id":"s_work_han_thu_114_278","chapterId":"ch_work_han_thu_114","textTraditional":"〔平帝〕年二歲，孝王薨，代為王。哀帝崩，無嗣，太皇太后與新都侯莽迎中山王立為帝。莽欲顓國權，懲丁、傅行事，〔一〕以帝為成帝後，母衛姬及外家不當得至京師。乃更立宗室桃鄉侯子成都為中山王，奉孝王後，遣少傅左將軍甄豐賜衛姬璽綬，即拜為中山孝王后，以苦陘縣為湯沐邑。又賜帝舅衛寶、寶弟玄爵關內侯。賜帝三妹，謁臣號修義君，哉皮為承禮君，鬲子為尊德君，〔二〕食邑各二千戶。莽長子宇非莽隔絕衛氏，恐久後受禍，即私與衛寶通書記，教衛后上書謝恩，因陳丁、傅舊惡，幾得至京師。〔三〕莽白太皇太后詔有司曰：「中山孝王后深分明為人後之義，條陳故定陶傅太后、丁姬誖天逆理，上僭位號，〔四〕徙定陶王於信都，為共王立廟於京師，如天子制，不畏天命，侮聖人言，〔五〕壞亂法度，居非其制，稱非其號。是以皇天震怒，火燒其殿，六年之間大命不遂，禍殃仍重〔六〕，竟令孝哀帝受其餘災，大失天心，夭命暴崩，又令共王祭祀絕廢，精魂無所依歸。朕惟孝王后深說經義，明鏡聖法，懼古人之禍敗，近事之咎殃，畏天命，奉聖言，是乃久保一國，長獲天祿，而令孝王永享無彊之祀，福祥之大者也。朕甚嘉之。夫褒義賞善，聖王之制，其以中山故安戶七千益中山后湯沐邑，加賜及中山王黃金各百斤，增傅相以下秩。」","sentenceOrder":278},
  {"id":"s_work_han_thu_114_279","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「懲，創艾也。」","sentenceOrder":279},
  {"id":"s_work_han_thu_114_280","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「鬲音歷。」","sentenceOrder":280},
  {"id":"s_work_han_thu_114_281","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「幾讀曰冀。」","sentenceOrder":281},
  {"id":"s_work_han_thu_114_282","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「誖，違也。」","sentenceOrder":282},
  {"id":"s_work_han_thu_114_283","chapterId":"ch_work_han_thu_114","textTraditional":"〔五〕　師古曰：「論語稱孔子曰：『君子有三畏：畏天命，畏大人，畏聖人之言。小人不知天命而不畏也，狎大人，侮聖人之言。』故此文引之也。〈亻毋〉，古侮字。」","sentenceOrder":283},
  {"id":"s_work_han_thu_114_284","chapterId":"ch_work_han_thu_114","textTraditional":"〔六〕　師古曰：「遂猶延也。重音直用反。」","sentenceOrder":284},
  {"id":"s_work_han_thu_114_285","chapterId":"ch_work_han_thu_114","textTraditional":"衛后日夜啼泣，思見帝，而但益戶邑。宇復教令上書求至京師。會事發覺，莽殺宇，盡誅衛氏支屬。衛寶女為中山王后，免后，徙合浦。〔一〕唯衛后在，〔二〕王莽篡國，廢為家人，後歲餘卒，葬孝王旁。","sentenceOrder":285},
  {"id":"s_work_han_thu_114_286","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「黜其后位而徙也。」","sentenceOrder":286},
  {"id":"s_work_han_thu_114_287","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「中山孝王后也。」","sentenceOrder":287},
  {"id":"s_work_han_thu_114_288","chapterId":"ch_work_han_thu_114","textTraditional":"孝平王皇后，安漢公太傅大司馬莽女也。平帝即位，年九歲，成帝母太皇太后稱制，而莽秉政。莽欲依霍光故事，以女配帝，太后意不欲也。莽設變詐，令女必入，因以自重，事在莽傳。太后不得已而許之，遣長樂少府夏侯藩、宗正劉宏、少府宗伯鳳、尚書令平晏納采，〔一〕太師光、大司徒馬宮、大司空甄豐、左將軍孫建、執金吾尹賞、行太常事太中大夫劉歆及太卜、太史令以下四十九人賜皮弁素績，〔二〕以禮雜卜筮，太牢祠宗廟，待吉月日。明年春，遣大司徒宮、大司空豐、左將軍建、右將軍甄邯、光祿大夫歆奉乘輿法駕，迎皇后於安漢公第。〔三〕宮、豐、歆授皇后璽紱，〔四〕登車稱警蹕，便時上林延壽門，〔五〕入未央宮前殿。群臣就位行禮，大赦天下。益封父安漢公地滿百里，賜迎皇后及行禮者，自三公以下至騶宰執事長樂、未央宮、安漢公第者，皆增秩，賜金帛各有差。皇后立三月，以禮見高廟。尊父安漢公號曰宰衡，位在諸侯王上。賜公夫人號曰功顯君，食邑。封公子安為褒新侯，臨為賞都侯。","sentenceOrder":288},
  {"id":"s_work_han_thu_114_289","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「官為少府，姓宗伯，名鳳也。納采者，禮記云婚禮納采問名，謂采擇其可者。」","sentenceOrder":289},
  {"id":"s_work_han_thu_114_290","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「皮弁，以鹿皮為冠，形如人手之弁合也。素績謂素裳也。朱衣而素裳。績字或作積。積謂襞積之，若今之襈為也。」","sentenceOrder":290},
  {"id":"s_work_han_thu_114_291","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「本自莽第，以皇后在是，因呼曰宮。」","sentenceOrder":291},
  {"id":"s_work_han_thu_114_292","chapterId":"ch_work_han_thu_114","textTraditional":"〔四〕　師古曰：「紱，所以繫璽，音茀。」","sentenceOrder":292},
  {"id":"s_work_han_thu_114_293","chapterId":"ch_work_han_thu_114","textTraditional":"〔五〕　師古曰：「取時日之便也，音頻面反。」","sentenceOrder":293},
  {"id":"s_work_han_thu_114_294","chapterId":"ch_work_han_thu_114","textTraditional":"后立歲餘，平帝崩。莽立孝宣帝玄孫嬰為孺子，莽攝帝位，尊皇后為皇太后。三年，莽即真，以嬰為定安公，改皇太后號為定安公太后。太后時年十八矣，為人婉瘱有節操。〔一〕自劉氏廢，常稱疾不朝會。莽敬憚傷哀，欲嫁之，乃更號為黃皇室主，〔二〕令立國將軍成新公孫建世子襐飾將毉往問疾。〔三〕后大怒，笞鞭其旁侍御。因發病，不肯起，莽遂不復彊也。及漢兵誅莽，燔燒未央宮，后曰：「何面目以見漢家！」自投火中而死。","sentenceOrder":294},
  {"id":"s_work_han_thu_114_295","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「婉，順也。瘱，靜也，音烏計反。」","sentenceOrder":295},
  {"id":"s_work_han_thu_114_296","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「莽自謂土德，故云黃皇。室主者，若漢之稱公主。」","sentenceOrder":296},
  {"id":"s_work_han_thu_114_297","chapterId":"ch_work_han_thu_114","textTraditional":"〔三〕　師古曰：「襐，盛飾也，音丈，又音象。一曰，襐，首飾也，在兩耳後，刻鏤而為之。」","sentenceOrder":297},
  {"id":"s_work_han_thu_114_298","chapterId":"ch_work_han_thu_114","textTraditional":"贊曰：易著吉凶而言謙盈之效，天地鬼神至于人道靡不同之〔一〕。夫女寵之興，繇至微而體至尊，〔二〕窮富貴而不以功，此固道家所畏，禍福之宗也。序自漢興，終于孝平，外戚後庭色寵著聞二十有餘人，然其保位全家者，唯文、景、武帝太后及邛成后四人而已。至如史良娣、王悼后、許恭哀后身皆夭折不辜，而家依託舊恩，不敢縱恣，是以能全。其餘大者夷滅，小者放流，烏呼！鑒茲行事，變亦備矣。","sentenceOrder":298},
  {"id":"s_work_han_thu_114_299","chapterId":"ch_work_han_thu_114","textTraditional":"〔一〕　師古曰：「易謙卦曰『天道虧盈而益謙，地道變盈而流謙，鬼神害盈而福謙，人道惡盈而好謙』。」","sentenceOrder":299},
  {"id":"s_work_han_thu_114_300","chapterId":"ch_work_han_thu_114","textTraditional":"〔二〕　師古曰：「繇與由同。」","sentenceOrder":300},
  {"id":"s_work_han_thu_114_301","chapterId":"ch_work_han_thu_114","textTraditional":"校勘記","sentenceOrder":301},
  {"id":"s_work_han_thu_114_302","chapterId":"ch_work_han_thu_114","textTraditional":"三九七四頁　三行　將軍宜尊（重）之敬之，　景祐本無「重」字。","sentenceOrder":302},
  {"id":"s_work_han_thu_114_303","chapterId":"ch_work_han_thu_114","textTraditional":"三九七四頁一四行　妾誇布服糲食，　李慈銘說孟注不可通，「誇」蓋許后之名。楊樹達說李說是。","sentenceOrder":303},
  {"id":"s_work_han_thu_114_304","chapterId":"ch_work_han_thu_114","textTraditional":"三九七六頁　五行　（官）〔宦〕吏忮佷，　景祐、殿、局本都作「宦」，注同。","sentenceOrder":304},
  {"id":"s_work_han_thu_114_305","chapterId":"ch_work_han_thu_114","textTraditional":"三九七六頁　六行　終不肯給妾纖微內邪？〔三〕　注〔三〕原在「纖微」下，明顏讀「內邪」屬下句。　周壽昌、楊樹達都說當屬上句讀。「纖微內」即上所云「纖微之間」。","sentenceOrder":305},
  {"id":"s_work_han_thu_114_306","chapterId":"ch_work_han_thu_114","textTraditional":"三九七八頁一六行　今正於（王）〔皇〕極之月，　殿本作「皇」。","sentenceOrder":306},
  {"id":"s_work_han_thu_114_307","chapterId":"ch_work_han_thu_114","textTraditional":"三九八０頁一三行　且財（帛）〔幣〕之省，　景祐、殿本都作「幣」。","sentenceOrder":307},
  {"id":"s_work_han_thu_114_308","chapterId":"ch_work_han_thu_114","textTraditional":"三九八九頁　五行　切皆銅沓（冒）黃金塗，　景祐本無「冒」字。王念孫說「冒」字涉注文而衍。","sentenceOrder":308},
  {"id":"s_work_han_thu_114_309","chapterId":"ch_work_han_thu_114","textTraditional":"三九九三頁　七行　常紿我言從（宮中）〔中宮〕來，　景祐、殿、局本都作「中宮」，此誤倒。","sentenceOrder":309},
  {"id":"s_work_han_thu_114_310","chapterId":"ch_work_han_thu_114","textTraditional":"三九九六頁　三行　（比）〔此〕朕不當所得赦也。　殿本作「此」。王先謙說作「此」是。","sentenceOrder":310},
  {"id":"s_work_han_thu_114_311","chapterId":"ch_work_han_thu_114","textTraditional":"四００三頁　一行　（始祖）〔祖，始〕也。　景祐、殿本都作「祖始」。王先謙說作「祖始」是。","sentenceOrder":311},
  {"id":"s_work_han_thu_114_312","chapterId":"ch_work_han_thu_114","textTraditional":"四００六頁　六行　服、（虔）〔蘇〕誤也。　景祐、殿本都作「蘇」，此誤。","sentenceOrder":312},
  {"id":"s_work_han_thu_114_313","chapterId":"ch_work_han_thu_114","textTraditional":"四００八頁　三行　〔平帝〕年二歲，　景祐、殿本都有「平帝」二字。","sentenceOrder":313},
  {"id":"s_work_han_thu_114_314","chapterId":"ch_work_han_thu_114","textTraditional":"四０一０頁　二行　迎皇后於安漢公第。〔三〕宮、豐、歆授皇后璽紱，　注〔三〕原在「宮」字下，　顏以「宮」與「第」連文。董教增說此當以「第」為句，「宮」字連下「豐歆」讀，顏說失之。","sentenceOrder":314},
  {"id":"s_work_han_thu_115_1","chapterId":"ch_work_han_thu_115","textTraditional":"孝元皇后，王莽之姑也。莽自謂黃帝之後，其自本曰：〔一〕黃帝姓姚氏，八世生虞舜。舜起媯汭，以媯為姓。〔二〕至周武王封舜後媯滿於陳，是為胡公，十三世生完。完字敬仲，奔齊，〔三〕齊桓公以為卿，姓田氏。十一世，田和有齊國，（三）〔二〕世稱王，至王建為秦所滅。項羽起，封建孫安為濟北王。至漢興，安失國，齊人謂之「王家」，因以為氏。","sentenceOrder":1},
  {"id":"s_work_han_thu_115_2","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「述其本系。」","sentenceOrder":2},
  {"id":"s_work_han_thu_115_3","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「媯，水名也。水曲曰汭。言因水為姓也。汭音而銳反。」","sentenceOrder":3},
  {"id":"s_work_han_thu_115_4","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　師古曰：「犇，古奔字。」","sentenceOrder":4},
  {"id":"s_work_han_thu_115_5","chapterId":"ch_work_han_thu_115","textTraditional":"文、景間，安孫遂字伯紀，處東平陵，〔一〕生賀，字翁孺。為武帝繡衣御史，逐捕魏郡群盜堅盧等黨與，及吏畏懦逗遛當坐者〔二〕，翁孺皆縱不誅。它部御史暴勝之等奏殺二千石，誅千石以下〔三〕，及通行飲食坐連及者，大部至斬萬餘人，語見酷吏傳。翁孺以奉使不稱免，〔四〕嘆曰：「吾聞活千人有封子孫，吾所活者萬餘人，後世其興乎！」","sentenceOrder":5},
  {"id":"s_work_han_thu_115_6","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「濟南之縣。」","sentenceOrder":6},
  {"id":"s_work_han_thu_115_7","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「懦音乃喚反。逗音住，又音豆。」","sentenceOrder":7},
  {"id":"s_work_han_thu_115_8","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　師古曰：「二千石者，奏而殺之，其千石以下，則得專誅。」","sentenceOrder":8},
  {"id":"s_work_han_thu_115_9","chapterId":"ch_work_han_thu_115","textTraditional":"〔四〕　師古曰：「不稱謂不副所委。」","sentenceOrder":9},
  {"id":"s_work_han_thu_115_10","chapterId":"ch_work_han_thu_115","textTraditional":"翁孺既免，而與東平陵終氏為怨，乃徙魏郡元城委粟里，為三老，魏郡人德之。元城建公曰：〔一〕「昔春秋沙麓崩，晉史卜之，曰：『陰為陽雄，土火相乘，〔二〕故有沙麓崩。後六百四十五年，宜有聖女興。』其齊田乎！〔三〕今王翁孺徙，正直其地，〔四〕日月當之。元城郭東有五鹿之虛，即沙鹿地也。〔五〕後八十年，當有貴女興天下」云。","sentenceOrder":10},
  {"id":"s_work_han_thu_115_11","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　服虔曰：「元城人年老者也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_115_12","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　李奇曰：「此龜繇文也。陰，元后也。陽，漢也。王氏舜後，土也。漢，火也。故曰土火相乘，陰盛而沙麓崩。」","sentenceOrder":12},
  {"id":"s_work_han_thu_115_13","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　張晏曰：「陰數八，八八六十四。土數五，故六百四十五歲也。春秋僖十四年，沙麓崩，歲在乙亥，至〔哀帝元壽二年〕，哀帝崩，元后始攝政，歲在庚申，沙麓崩後六百四十五歲。」","sentenceOrder":13},
  {"id":"s_work_han_thu_115_14","chapterId":"ch_work_han_thu_115","textTraditional":"〔四〕　師古曰：「直亦當。」","sentenceOrder":14},
  {"id":"s_work_han_thu_115_15","chapterId":"ch_work_han_thu_115","textTraditional":"〔五〕　師古曰：「虛讀曰墟。」","sentenceOrder":15},
  {"id":"s_work_han_thu_115_16","chapterId":"ch_work_han_thu_115","textTraditional":"（王）翁孺生禁，字稚君，少學法律長安，為廷尉史。本始三年，生女政君，即元后也。禁有大志，不修廉隅，好酒色，多取傍妻，凡有四女八男：長女君俠，次即元后政君，次君力，次君弟；長男鳳孝卿，次曼元卿，譚子元，崇少子，商子夏，立子叔，根稚卿，逢時季卿。唯鳳、崇與元后政君同母。母，適妻，魏郡李氏女也。〔一〕後以妒去，更嫁為河內苟賓妻。","sentenceOrder":16},
  {"id":"s_work_han_thu_115_17","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「適讀曰嫡。」","sentenceOrder":17},
  {"id":"s_work_han_thu_115_18","chapterId":"ch_work_han_thu_115","textTraditional":"初，李親任政君在身，〔一〕夢月入其懷。及壯大，婉順得婦人道。嘗許嫁未行，所許者死。後東平王聘政君為姬，未入，王薨。禁獨怪之，使卜數者相政君，〔二〕「當大貴，不可言。」禁心以為然，乃教書，學鼓琴。五鳳中，獻政君，年十八矣，入掖庭為家人子。","sentenceOrder":18},
  {"id":"s_work_han_thu_115_19","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「任，懷任。」","sentenceOrder":19},
  {"id":"s_work_han_thu_115_20","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「數，計也。若言今之祿命書也。數音所具反。」","sentenceOrder":20},
  {"id":"s_work_han_thu_115_21","chapterId":"ch_work_han_thu_115","textTraditional":"歲餘，會皇太子所愛幸司馬良娣病，且死，謂太子曰：「妾死非天命，乃諸娣妾良人更祝詛殺我。」〔一〕太子憐之，且以為然。及司馬良娣死，太子悲恚發病，忽忽不樂，因以過怒諸娣妾，莫得進見者。久之，宣帝聞太子恨過諸娣妾，欲順適其意，乃令皇后擇後宮家人子可以虞侍太子者，〔二〕政君與在其中。〔三〕及太子朝，皇后乃見政君等五人，微令旁長御問知太子所欲。太子殊無意於五人者，不得已於皇后，〔四〕彊應曰：「此中一人可。」〔五〕是時政君坐近太子，又獨衣絳緣諸于，〔六〕長御即以為〔是〕。皇后使侍中杜輔、掖庭令濁賢交送政君太子宮，〔七〕見丙殿。得御幸，有身。先是者，太子後宮娣妾以十數，御幸久者七八年，莫有子，及王妃壹幸而有身。甘露三年，生成帝於甲館畫堂，為世適皇孫。〔八〕宣帝愛之，自名曰驁，字太孫，常置左右。","sentenceOrder":21},
  {"id":"s_work_han_thu_115_22","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「更音工衡反。」","sentenceOrder":22},
  {"id":"s_work_han_thu_115_23","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「此虞與娛同。」","sentenceOrder":23},
  {"id":"s_work_han_thu_115_24","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　師古曰：「與讀曰豫。」","sentenceOrder":24},
  {"id":"s_work_han_thu_115_25","chapterId":"ch_work_han_thu_115","textTraditional":"〔四〕　師古曰：「恐不副皇后意，故言不得已。」","sentenceOrder":25},
  {"id":"s_work_han_thu_115_26","chapterId":"ch_work_han_thu_115","textTraditional":"〔五〕　師古曰：「非其本心，故曰彊也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_115_27","chapterId":"ch_work_han_thu_115","textTraditional":"〔六〕　師古曰：「諸于，大掖衣，即袿衣之類也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_115_28","chapterId":"ch_work_han_thu_115","textTraditional":"〔七〕　師古曰：「濁，姓也。交送，謂侍中、掖庭令雜為使。」","sentenceOrder":28},
  {"id":"s_work_han_thu_115_29","chapterId":"ch_work_han_thu_115","textTraditional":"〔八〕　師古曰：「適讀曰嫡。」","sentenceOrder":29},
  {"id":"s_work_han_thu_115_30","chapterId":"ch_work_han_thu_115","textTraditional":"後三年，宣帝崩，太子即位，是為孝元帝。立太孫為太子，以母王妃為婕妤，封父禁為陽平侯。後三日，婕妤立為皇后，禁位特進，禁弟弘至長樂衛尉。永光二年，禁薨，諡曰頃侯。長子鳳嗣侯，為衛尉侍中。皇后自有子後，希復進見。太子壯大，寬博恭慎，語在成紀。其後幸酒，樂燕樂，〔一〕元帝不以為能。而傅昭儀有寵於上，生定陶共王。王多材藝，上甚愛之，坐則側席，行則同輦，〔二〕常有意欲廢太子而立共王。時鳳在位，與皇后、太子同心憂懼，賴侍中史丹擁右太子，〔三〕語在丹傳。上亦以皇后素謹慎，而太子先帝所常留意，故得不廢。","sentenceOrder":30},
  {"id":"s_work_han_thu_115_31","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「幸酒，好酒也。樂宴樂，好燕私之樂也。解具在成紀。」","sentenceOrder":31},
  {"id":"s_work_han_thu_115_32","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「側席謂附近御坐。」","sentenceOrder":32},
  {"id":"s_work_han_thu_115_33","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　師古曰：「右讀曰佑，助也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_115_34","chapterId":"ch_work_han_thu_115","textTraditional":"元帝崩，太子立，是為孝成帝。尊皇后為皇太后，以鳳為大司馬大將軍領尚書事，益封五千戶。王氏之興自鳳始。又封太后同母弟崇為安成侯，食邑萬戶。鳳庶弟譚等皆賜爵關內侯，食邑。","sentenceOrder":34},
  {"id":"s_work_han_thu_115_35","chapterId":"ch_work_han_thu_115","textTraditional":"其夏，黃霧四塞終日。〔一〕天子以問諫大夫楊興、博士駟勝等，對皆以為「陰盛侵陽之氣也。高祖之約也，非功臣不侯，今太后諸弟皆以無功為侯，非高祖之約，外戚未曾有也，故天為見異。」〔二〕言事者多以為然。鳳於是懼，上書辭謝曰：「陛下即位，思慕諒闇，〔三〕故詔臣鳳典領尚書事，上無以明聖德，下無以益政治。今有茀星天地赤黃之異，〔四〕咎在臣鳳，當伏顯戮，以謝天下。今諒闇已畢，大義皆舉，宜躬親萬機，以承天心。」因乞骸骨辭職。上報曰：「朕承先帝聖緒，涉道未深，不明事情，是以陰陽錯繆，日月無光，赤黃之氣，充塞天下。咎在朕躬，今大將軍乃引過自予，欲上尚書事，歸大將軍印綬，罷大司馬官，是明朕之不德也。朕委將軍以事，誠欲庶幾有成，顯先祖之功德。將軍其專心固意，輔朕之不逮，毋有所疑。」","sentenceOrder":35},
  {"id":"s_work_han_thu_115_36","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「塞，滿也。言四方皆滿。」","sentenceOrder":36},
  {"id":"s_work_han_thu_115_37","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「見，顯示。」","sentenceOrder":37},
  {"id":"s_work_han_thu_115_38","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　師古曰：「商書云『高宗諒闇』。諒，信；闇，默也。言居父喪信默，三年不言也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_115_39","chapterId":"ch_work_han_thu_115","textTraditional":"〔四〕　師古曰：「茀與孛同。」","sentenceOrder":39},
  {"id":"s_work_han_thu_115_40","chapterId":"ch_work_han_thu_115","textTraditional":"後五年，諸吏散騎安成侯崇薨，謚曰共侯。有遺腹子奉世嗣侯，太后甚哀之。明年，河平二年，上悉封舅譚為平阿侯，商成都侯，立紅陽侯，根曲陽侯，逢時高平侯。五人同日封，故世謂之「五侯」。太后同產唯曼蚤卒，〔一〕餘畢侯矣。太后母李親，苟氏妻，生一男名參，寡居。頃侯禁在時，太后令禁還李親。〔二〕太后憐參，欲以田蚡為比而封之。〔三〕上曰：「封田氏，非正也。」以參為侍中水衡都尉。王氏子弟皆卿大夫侍中諸曹，分據勢官滿朝廷。","sentenceOrder":40},
  {"id":"s_work_han_thu_115_41","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　張晏曰：「同父則為同產，不必同母也。上言唯鳳、崇同母也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_115_42","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「召還王氏。」","sentenceOrder":42},
  {"id":"s_work_han_thu_115_43","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　李奇曰：「田蚡與孝景王后同母異父，得封故也。」師古曰：「比，例也，音必寐反。」","sentenceOrder":43},
  {"id":"s_work_han_thu_115_44","chapterId":"ch_work_han_thu_115","textTraditional":"大將軍鳳用事，上遂謙讓無所顓。〔一〕左右常薦光祿大夫劉向少子歆通達有異材。上召見歆，誦讀詩賦，甚說之，〔二〕欲以為中常侍，召取衣冠。臨當拜，左右皆曰：「未曉大將軍。」〔三〕上曰：「此小事，何須關大將軍？」左右叩頭爭之。上於是語鳳，鳳以為不可，乃止。其見憚如此。","sentenceOrder":44},
  {"id":"s_work_han_thu_115_45","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「顓與專同。凡事皆不自專也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_115_46","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":46},
  {"id":"s_work_han_thu_115_47","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　師古曰：「曉猶白。」","sentenceOrder":47},
  {"id":"s_work_han_thu_115_48","chapterId":"ch_work_han_thu_115","textTraditional":"上即位數年，無繼嗣，體常不平。〔一〕定陶共王來朝，太后與上承先帝意，遇共王甚厚，賞賜十倍於它王，不以往事為纖介。〔二〕共王之來朝也，天子留，不遣歸國。上謂共王：「我未有子，人命不諱，〔三〕一朝有它，且不復相見。〔四〕爾長留侍我矣！」其後天子疾益有瘳，共王因留國邸，旦夕侍上，上甚親重。大將軍鳳心不便共王在京師，會日蝕，鳳因言「日蝕陰盛之象，為非常異。定陶王雖親，於禮當奉藩在國。今留侍京師，詭正非常，〔五〕故天見戒。〔六〕宜遣王之國。」上不得已於鳳而許之。〔七〕共王辭去，上與相對〔涕〕泣而決。","sentenceOrder":48},
  {"id":"s_work_han_thu_115_49","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「言多疾疢。」","sentenceOrder":49},
  {"id":"s_work_han_thu_115_50","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「往事，謂先帝時欲以代太子也。言無纖介之嫌怒。」","sentenceOrder":50},
  {"id":"s_work_han_thu_115_51","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　師古曰：「人命無常，不可諱。」","sentenceOrder":51},
  {"id":"s_work_han_thu_115_52","chapterId":"ch_work_han_thu_115","textTraditional":"〔四〕　師古曰：「它謂晏駕也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_115_53","chapterId":"ch_work_han_thu_115","textTraditional":"〔五〕　師古曰：「詭，違也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_115_54","chapterId":"ch_work_han_thu_115","textTraditional":"〔六〕　師古曰：「見，顯示。」","sentenceOrder":54},
  {"id":"s_work_han_thu_115_55","chapterId":"ch_work_han_thu_115","textTraditional":"〔七〕　師古曰：「言迫於鳳不得止。」","sentenceOrder":55},
  {"id":"s_work_han_thu_115_56","chapterId":"ch_work_han_thu_115","textTraditional":"京兆尹王章素剛直敢言，以為鳳建遣共王之國非是，〔一〕乃奏封事言日蝕之咎矣。天子召見章，延問以事，章對曰：「天道聰明，（佐）〔佑〕善而災惡，以瑞異為符效。今陛下以未有繼嗣，引近定陶王，〔二〕所以承宗廟，重社稷，上順天心，下安百姓。此正義善事，當有祥瑞，何故致災異？災異之發，為大臣顓政者也。今聞大將軍猥歸日蝕之咎於定陶王，〔三〕建遣之國，苟欲使天子孤立於上，顓擅朝事以便其私，非忠臣也。且日蝕，陰侵陽臣顓君之咎，今政事大小皆自鳳出，天子曾不一舉手，鳳不內省責，反歸咎善人，推遠定陶王。〔四〕且鳳誣罔不忠，非一事也。前丞相樂昌侯商〔五〕本以先帝外屬，內行篤，有威重，位歷將相，國家柱石臣也，其人守正，不肯詘節隨鳳委曲，卒用閨門之事為鳳所罷，身以憂死，眾庶愍之。又鳳知其小婦弟張美人已嘗適人，〔六〕於禮不宜配御至尊，託以為宜子，內之後宮，苟以私其妻弟。聞張美人未嘗任身就館也。〔七〕且羌胡尚殺首子以盪腸正世，〔八〕況於天子而近已出之女也！此三者皆大事，陛下所自見，足以知其餘，及它所不見者。〔九〕鳳不可令久典事，宜退使就第，選忠賢以代之。」","sentenceOrder":56},
  {"id":"s_work_han_thu_115_57","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「建立其議也。」","sentenceOrder":57},
  {"id":"s_work_han_thu_115_58","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「近音巨靳反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_115_59","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　師古曰：「猥猶曲也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_115_60","chapterId":"ch_work_han_thu_115","textTraditional":"〔四〕　師古曰：「遠音于萬反。」","sentenceOrder":60},
  {"id":"s_work_han_thu_115_61","chapterId":"ch_work_han_thu_115","textTraditional":"〔五〕　師古曰：「王商也。」","sentenceOrder":61},
  {"id":"s_work_han_thu_115_62","chapterId":"ch_work_han_thu_115","textTraditional":"〔六〕　師古曰：「小婦，妾也。弟謂女弟，即妹也。」","sentenceOrder":62},
  {"id":"s_work_han_thu_115_63","chapterId":"ch_work_han_thu_115","textTraditional":"〔七〕　師古曰：「是則不為宜子，明鳳所言非實。」","sentenceOrder":63},
  {"id":"s_work_han_thu_115_64","chapterId":"ch_work_han_thu_115","textTraditional":"〔八〕　師古曰：「盪，洗滌也。言婦初來所生之子或它姓。」","sentenceOrder":64},
  {"id":"s_work_han_thu_115_65","chapterId":"ch_work_han_thu_115","textTraditional":"〔九〕　師古曰：「以所見者譬之，則不見者可知。」","sentenceOrder":65},
  {"id":"s_work_han_thu_115_66","chapterId":"ch_work_han_thu_115","textTraditional":"自鳳之白罷商後遣定陶王也，上不能平。及聞章言，天子感寤，納之，謂章曰：「微京兆尹直言，吾不聞社稷計！〔一〕且唯賢知賢，君試為朕求可以自輔者。」於是章奏封事，薦中山孝王舅琅邪太守馮野王「先帝時歷二卿，忠信質直，知謀有餘。野王以王舅出，以賢復入，明聖主樂進賢也。」上自為太子時數聞野王先帝名卿，聲譽出鳳遠甚，方倚欲以代鳳。","sentenceOrder":66},
  {"id":"s_work_han_thu_115_67","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「微，無也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_115_68","chapterId":"ch_work_han_thu_115","textTraditional":"初，章每召見，上輒辟左右。〔一〕時太后從弟長樂衛尉弘子侍中音〔二〕獨側聽，具知章言，以語鳳。鳳聞之，稱病出就第，上疏乞骸骨，謝上曰：「臣材駑愚戇，得以外屬兄弟七人封為列侯，宗族蒙恩，賞賜無量。輔政出入七年，國家委任臣鳳，所言輒聽，薦士常用。無一功善，陰陽不調，災異數見，咎在臣鳳奉職無狀，此臣一當退也。五經傳記，師所誦說，咸以日蝕之咎在於大臣非其人，易曰『折其右肱』，〔三〕此臣二當退也。河平以來，臣久病連年，數出在外，曠職素餐，此臣三當退也。〔四〕陛下以皇太后故不忍誅廢，臣猶自知當遠流放，又重自念，〔五〕兄弟宗族所蒙不測，當殺身靡骨死輦轂下，〔六〕不當以無益之故有離寑門之心。誠歲餘以來，所苦加侵，〔七〕日日益甚，不勝大願，願乞骸骨，歸自治養，冀賴陛下神靈，未理髮齒，期月之間，幸得瘳愈，復望帷幄，不然，必寘溝壑。臣以非材見私，天下知臣受恩深也；以病得全骸骨歸，天下知臣被恩見哀，重巍巍也。〔八〕進退於國為厚，萬無纖介之議。〔九〕唯陛下哀憐！」其辭指甚哀，太后聞之為垂涕，不御食。","sentenceOrder":68},
  {"id":"s_work_han_thu_115_69","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「辟讀曰闢。」","sentenceOrder":69},
  {"id":"s_work_han_thu_115_70","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「弘者，太后之叔父也。音則從父弟。」","sentenceOrder":70},
  {"id":"s_work_han_thu_115_71","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　師古曰：「豐卦九三爻辭也。肱，臂也。」","sentenceOrder":71},
  {"id":"s_work_han_thu_115_72","chapterId":"ch_work_han_thu_115","textTraditional":"〔四〕　師古曰：「空廢職任，徒受祿秩也。」","sentenceOrder":72},
  {"id":"s_work_han_thu_115_73","chapterId":"ch_work_han_thu_115","textTraditional":"〔五〕　師古曰：「重音直用反。」","sentenceOrder":73},
  {"id":"s_work_han_thu_115_74","chapterId":"ch_work_han_thu_115","textTraditional":"〔六〕　師古曰：「靡，碎也，音武皮反。」","sentenceOrder":74},
  {"id":"s_work_han_thu_115_75","chapterId":"ch_work_han_thu_115","textTraditional":"〔七〕　師古曰：「誠，實也。」","sentenceOrder":75},
  {"id":"s_work_han_thu_115_76","chapterId":"ch_work_han_thu_115","textTraditional":"〔八〕　師古曰：「巍巍，高貌。重音直用反。」","sentenceOrder":76},
  {"id":"s_work_han_thu_115_77","chapterId":"ch_work_han_thu_115","textTraditional":"〔九〕　師古曰：「論者不云疏斥外戚也。」","sentenceOrder":77},
  {"id":"s_work_han_thu_115_78","chapterId":"ch_work_han_thu_115","textTraditional":"上少而親倚鳳，弗忍廢，乃報鳳曰：「朕秉事不明，政事多闕，故天變（屢）〔婁〕臻，咸在朕躬。〔一〕將軍乃深引過自予，欲乞骸骨而退，則朕將何嚮焉！書不云乎？『公毋困我。』〔二〕務專精神，安心自持，期於亟瘳，稱朕意焉。」〔三〕於是鳳起視事。上使尚書劾奏章「知野王前以王舅出補吏，而私薦之，欲令在朝阿附諸侯；又知張美人體御至尊，而妄稱引羌胡殺子蕩腸，非所宜言。」遂下章吏。廷尉致其大逆罪，以為「比上夷狄，欲絕繼嗣之端；背畔天子，私為定陶王。」章死獄中，妻子徙合浦。","sentenceOrder":78},
  {"id":"s_work_han_thu_115_79","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　〔師古曰：「婁，古屢字。」〕","sentenceOrder":79},
  {"id":"s_work_han_thu_115_80","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「周書洛誥載成王告周公辭也。言公必須留京師，毋得遠去，而令我困。」","sentenceOrder":80},
  {"id":"s_work_han_thu_115_81","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　師古曰：「亟，急。瘳，差也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_115_82","chapterId":"ch_work_han_thu_115","textTraditional":"自是公卿見鳳，側目而視，郡國守相刺史皆出其門。〔一〕又以侍中太僕音為御史大夫，列于三公。而五侯群弟，爭為奢侈，賂遺珍寶，四面而至；後庭姬妾，各數十人，僮奴以千百數，羅鐘磬，舞鄭女，作倡優，狗馬馳逐；大治第室，起土山漸臺，洞門高廊閣道，連屬彌望。〔二〕百姓歌之曰：「五侯初起，曲陽最怒，壞決高都，連竟外杜，〔三〕土山漸臺西白虎。」〔四〕〔其〕奢僭如此。然皆通敏人事，好士養賢，傾財施予，以相高尚。","sentenceOrder":82},
  {"id":"s_work_han_thu_115_83","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「言為其家寮屬者，皆得大官。」","sentenceOrder":83},
  {"id":"s_work_han_thu_115_84","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「彌，竟也。言望之極目也。屬音之欲反。」","sentenceOrder":84},
  {"id":"s_work_han_thu_115_85","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　服虔曰：「壞決高都水入長安。高都水在長安西也。」孟康曰：「杜、鄠二縣之間田畝一金。言其境自長安至杜陵也。」李奇曰：「長安有高都、（水）〔外〕杜里，既壞決高都作殿，復衍及外杜里。」師古曰：「成都侯商自擅穿帝城引水耳，曲陽無此事。又雖大作第宅，不得從長安至杜陵也。（按）李說為（近）是。」","sentenceOrder":85},
  {"id":"s_work_han_thu_115_86","chapterId":"ch_work_han_thu_115","textTraditional":"〔四〕　師古曰：「皆放效天子之制也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_115_87","chapterId":"ch_work_han_thu_115","textTraditional":"鳳輔政凡十一歲。陽朔三年秋，鳳病，天子數自臨問，親執其手，涕泣曰：「將軍病，如有不可言，平阿侯譚次將軍矣。」〔一〕鳳頓首泣曰：「譚等雖與臣至親，行皆奢僭，無以率導百姓，不如御史大夫音謹敕，〔二〕臣敢以死保之。」及鳳且死，上疏謝上，復固薦音自代，〔言〕譚等五人必不可用。天子然之。","sentenceOrder":87},
  {"id":"s_work_han_thu_115_88","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「不可言，謂死也，不欲斥言之。」","sentenceOrder":88},
  {"id":"s_work_han_thu_115_89","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「敕，整也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_115_90","chapterId":"ch_work_han_thu_115","textTraditional":"初，譚倨，不肯事鳳，〔一〕而音敬鳳，卑恭如子，故薦之。鳳薨，天子臨弔贈寵，送以輕車介士，軍陳自長安至渭陵，諡曰敬成侯。子襄嗣侯，為衛尉。御史大夫音竟代鳳為大司馬車騎將軍，而平阿侯譚位特進，領城門兵。谷永說譚，令讓不受城門職，由是與音不平，語在永傳。","sentenceOrder":90},
  {"id":"s_work_han_thu_115_91","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「倨，慢也，音據。」","sentenceOrder":91},
  {"id":"s_work_han_thu_115_92","chapterId":"ch_work_han_thu_115","textTraditional":"音既以從舅越親用事，小心親職，歲餘，上下詔曰：「車騎將軍音宿衛忠正，勤勞國家，前為御史大夫，以外親宜典兵馬，入為將軍，不獲宰相之封，朕甚慊焉！其封音為安陽侯，食邑與五侯等，俱三千戶。」","sentenceOrder":92},
  {"id":"s_work_han_thu_115_93","chapterId":"ch_work_han_thu_115","textTraditional":"初，成都侯商嘗病，欲避暑，從上借明光宮。〔一〕後又穿長安城，引內灃水注第中大陂以行船，立羽蓋，張周帷，輯濯越歌。〔二〕上幸商第，見穿城引水，意恨，內銜之，未言。後微行出，過曲陽侯第，又見園中土山漸臺似類白虎殿。〔三〕於是上怒，以讓車騎將軍音。商、根兄弟欲自黥劓謝太后。上聞之大怒，乃使尚書責問司隸校尉、京兆尹「知成都侯商擅穿帝城，決引灃水，曲陽侯根驕奢僭上，赤墀青瑣，〔四〕紅陽侯立父子臧匿姦猾亡命，賓客為群盜，司隸、京兆皆阿縱不舉奏正法。」二人頓首省戶下。又賜車騎將軍音策書曰：「外家何甘樂禍敗，〔五〕而欲自黥劓，相戮辱於太后前，傷慈母之心，以危亂國！外家宗族彊，上一身浸弱日久，〔六〕今將一施之。〔七〕君其召諸侯，令待府舍。」〔八〕是日，詔尚書奏文帝時誅將軍薄昭故事。車騎將軍音藉槁請罪，〔九〕商、立、根皆負斧質謝。上不忍誅，然後得已。","sentenceOrder":93},
  {"id":"s_work_han_thu_115_94","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「黃圖云明光宮在城內，近桂宮也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_115_95","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「輯與楫同，濯與櫂同，皆所以行船也。令執楫櫂人為越歌也。輯為櫂之短者也。今吳越之人呼為橈，音饒。越歌，為越之歌。」","sentenceOrder":95},
  {"id":"s_work_han_thu_115_96","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　師古曰：「黃圖云在未央宮。」","sentenceOrder":96},
  {"id":"s_work_han_thu_115_97","chapterId":"ch_work_han_thu_115","textTraditional":"〔四〕　孟康曰：「以青畫戶邊鏤中，天子制也。」如淳曰：「門楣格再重，如人衣領再重，裏者青，名曰青瑣，天子門制也。」師古曰：「孟說是。青瑣者，刻為連環文，而青塗之也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_115_98","chapterId":"ch_work_han_thu_115","textTraditional":"〔五〕　師古曰：「言此罪過，並身自為之。」","sentenceOrder":98},
  {"id":"s_work_han_thu_115_99","chapterId":"ch_work_han_thu_115","textTraditional":"〔六〕　師古曰：「寖，漸也。」","sentenceOrder":99},
  {"id":"s_work_han_thu_115_100","chapterId":"ch_work_han_thu_115","textTraditional":"〔七〕　師古曰：「行刑罰。」","sentenceOrder":100},
  {"id":"s_work_han_thu_115_101","chapterId":"ch_work_han_thu_115","textTraditional":"〔八〕　師古曰：「令總集音之府舍，待詔命。」","sentenceOrder":101},
  {"id":"s_work_han_thu_115_102","chapterId":"ch_work_han_thu_115","textTraditional":"〔九〕　師古曰：「自坐槁上，言就刑戮也。」","sentenceOrder":102},
  {"id":"s_work_han_thu_115_103","chapterId":"ch_work_han_thu_115","textTraditional":"久之，平阿侯譚薨，諡曰安侯，子仁嗣侯。太后憐弟曼蚤死，獨不封，曼寡婦渠供養東宮，子莽幼孤不及等比，〔一〕常以為語。平阿侯譚、成都侯商及在位多稱莽者。久之，上復下詔追封曼為新都哀侯，而子莽嗣爵為新都侯。後又封太后姊子淳于長為定陵侯。王氏親屬，侯者凡十人。","sentenceOrder":103},
  {"id":"s_work_han_thu_115_104","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「比音必寐反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_115_105","chapterId":"ch_work_han_thu_115","textTraditional":"上悔廢平阿侯譚不輔政而薨也，乃復進成都侯商以特進，領城門兵，置幕府，得舉吏如將軍。杜鄴說車騎將軍音令親附商，語在鄴傳。王氏爵位日盛，唯音為修整，數諫正，有忠節，輔政八年，薨。弔贈如大將軍，諡曰敬侯。子舜嗣侯，為太僕侍中。特進成都侯商代音為大司馬衛將軍，而紅陽侯立位特進，領城門兵。商輔政四歲，病乞骸骨，天子憫之，更以為大將軍，益封二千戶，賜錢百萬。商薨，弔贈如大將軍故事，諡曰景成侯，子況嗣侯。紅陽侯立次當輔政，有罪過，語在孫寶傳。上乃廢立而用光祿勳曲陽侯根為大司馬票騎將軍，歲餘益封千七百戶。高平侯逢時無材能名稱，是歲薨，諡曰戴侯，子買之嗣侯。","sentenceOrder":105},
  {"id":"s_work_han_thu_115_106","chapterId":"ch_work_han_thu_115","textTraditional":"綏和元年，上即位二十餘年無繼嗣，而定陶共王已薨，子嗣立為王。王祖母定陶傅太后重賂遺票騎將軍根，為王求漢嗣，根為言，上亦欲立之，遂徵定陶王為太子。時根輔政五歲矣，乞骸骨，上乃益封根五千戶，賜安車駟馬，黃金五百斤，罷就第。","sentenceOrder":106},
  {"id":"s_work_han_thu_115_107","chapterId":"ch_work_han_thu_115","textTraditional":"先是定陵侯淳于長以外屬能謀議，為衛尉侍中，在輔政之次。是歲，新都侯莽告長伏罪與紅陽侯立相連，〔一〕長下獄死，立就國，語在長傳。故曲陽侯根薦莽以自代，上亦以為莽有忠直節，遂擢莽從侍中騎都尉光祿大夫為大司馬。","sentenceOrder":107},
  {"id":"s_work_han_thu_115_108","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「伏罪，謂舊罪陰伏未發者也。」","sentenceOrder":108},
  {"id":"s_work_han_thu_115_109","chapterId":"ch_work_han_thu_115","textTraditional":"歲餘，成帝崩，哀帝即位。太后詔莽就第，避帝外家。哀帝初優莽，不聽。莽上書固乞骸骨而退。上乃下詔曰：「曲陽侯根前在位，建社稷策。侍中太僕安陽侯舜往時護太子家，導朕，忠誠專壹，有舊恩。新都侯莽憂勞國家，執義堅固，庶幾與為治，太皇太后詔休就第，朕甚閔焉。其益封根二千戶，舜五百戶，莽三百五十戶。以莽為特進，朝朔望。」又還紅陽侯立京師。哀帝少而聞知王氏驕盛，心不能善，以初立，故優之。","sentenceOrder":109},
  {"id":"s_work_han_thu_115_110","chapterId":"ch_work_han_thu_115","textTraditional":"後月餘，司隸校尉解光奏：「曲陽根宗重身尊，三世據權，五將秉政，天下輻湊自效。〔一〕根行貪邪，臧累鉅萬，縱橫恣意，〔二〕大治（第宅）〔室第〕，第中起土山，立兩市，殿上赤墀，戶青瑣；遊觀射獵，使奴從者被甲持弓弩，陳為步兵；止宿離宮，水衡共張，〔三〕發民治道，百姓苦其役。內懷姦邪，欲筦朝政，〔四〕推親近吏主簿張業以為尚書，蔽上壅下，內塞王路，外交藩臣，驕奢僭上，壞亂制度。案根骨肉至親，社稷大臣，〔五〕先帝棄天下，根不悲哀思慕，山陵未成，公聘取故掖庭女樂五官殷嚴、王飛君等，〔六〕置酒歌舞，捐忘先帝厚恩，背臣子義。及根兄子成都侯況幸得以外親繼父為列侯侍中，不思報厚恩，亦聘取故掖庭貴人以為妻，皆無人臣禮，大不敬不道。」於是天子曰：「先帝遇根、況父子，至厚也，今乃背忘恩義！」以根嘗建社稷之策，〔七〕遣就國。免況為庶人，歸故郡。根及況父商所薦舉為官者，皆罷。","sentenceOrder":110},
  {"id":"s_work_han_thu_115_111","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「效，獻也，獻其款誠。」","sentenceOrder":111},
  {"id":"s_work_han_thu_115_112","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「橫音胡孟反。」","sentenceOrder":112},
  {"id":"s_work_han_thu_115_113","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　師古曰：「共音居用反。張音竹亮反。」","sentenceOrder":113},
  {"id":"s_work_han_thu_115_114","chapterId":"ch_work_han_thu_115","textTraditional":"〔四〕　師古曰：「筦與管同。」","sentenceOrder":114},
  {"id":"s_work_han_thu_115_115","chapterId":"ch_work_han_thu_115","textTraditional":"〔五〕　師古曰：「至親謂於成帝為舅。」","sentenceOrder":115},
  {"id":"s_work_han_thu_115_116","chapterId":"ch_work_han_thu_115","textTraditional":"〔六〕　如淳曰：「五官，官名也。外戚傳曰五官視三百石。」","sentenceOrder":116},
  {"id":"s_work_han_thu_115_117","chapterId":"ch_work_han_thu_115","textTraditional":"〔七〕　師古曰：「謂立哀帝為嗣也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_115_118","chapterId":"ch_work_han_thu_115","textTraditional":"後二歲，傅太后、帝母丁姬皆稱尊號。有司奏「新都侯莽前為大司馬，貶抑尊號之議，虧損孝道，及平阿侯仁臧匿趙昭儀親屬，皆就國。」天下多冤王氏。","sentenceOrder":118},
  {"id":"s_work_han_thu_115_119","chapterId":"ch_work_han_thu_115","textTraditional":"諫大夫楊宣上封事言：「孝成皇帝深惟宗廟之重，稱述陛下至德以承天序，聖策深遠，恩德至厚。惟念先帝之意，豈不欲以陛下自代，奉承東宮哉！〔一〕太皇太后春秋七十，數更憂傷，〔二〕敕令親屬引領以避丁、傅。〔三〕行道之人為之隕涕，況於陛下，時登高遠望，獨不慚於延陵乎！」哀帝深感其言，復封商中子邑為成都侯。","sentenceOrder":119},
  {"id":"s_work_han_thu_115_120","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「言供養太后。」","sentenceOrder":120},
  {"id":"s_work_han_thu_115_121","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「更，經也，音工衡反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_115_122","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　師古曰：「引領，自引首領而退也。」","sentenceOrder":122},
  {"id":"s_work_han_thu_115_123","chapterId":"ch_work_han_thu_115","textTraditional":"元壽元年，日蝕。賢良對策多訟新都侯莽者，上於是徵莽及平阿侯仁還京師侍太后。曲陽侯根薨，國除。","sentenceOrder":123},
  {"id":"s_work_han_thu_115_124","chapterId":"ch_work_han_thu_115","textTraditional":"明年，哀帝崩，無子，太皇太后以莽為大司馬，與共徵立中山王奉哀帝後，是為平帝。帝年九歲，（常）〔當〕年被疾，太后臨朝，委政於莽，莽顓威福。紅陽侯立莽諸父，平阿侯仁素剛直，莽內憚之，令大臣以罪過奏遣立、仁就國。莽日誑燿太后，言輔政致太平，群臣奏請尊莽為安漢公。後遂遣使者迫守立、仁令自殺，賜立諡曰荒侯，子柱嗣，仁諡曰刺侯，子術嗣。是歲，元始三年也。明年，莽風群臣奏立莽女為皇后。〔一〕又奏尊莽為宰衡，莽母及兩子皆封為列侯，語在莽傳。","sentenceOrder":124},
  {"id":"s_work_han_thu_115_125","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「風讀曰諷。」","sentenceOrder":125},
  {"id":"s_work_han_thu_115_126","chapterId":"ch_work_han_thu_115","textTraditional":"莽既外壹群臣，令稱己功德，又內媚事旁側長御以下，賂遺以千萬數。白尊太后姊妹君俠為廣恩君，君力為廣惠君，君弟為廣施君，皆食湯沐邑，日夜共譽莽。莽又知太后婦人厭居深宮中，莽欲虞樂以市其權，〔一〕乃令太后四時車駕巡狩四郊，〔二〕存見孤寡貞婦。春幸繭館，〔三〕率皇后列侯夫人桑，遵霸水而祓除；〔四〕夏遊篽宿、鄠、杜之間；〔五〕秋歷東館，望昆明，集黃山宮；冬饗飲飛羽，〔六〕校獵上蘭，〔七〕登長平館，〔八〕臨涇水而覽焉。太后所至屬縣，輒施恩惠，賜民錢帛牛酒，歲以為常。太后從容言曰：〔九〕「我始入太子家時，見於丙殿，至今五六十歲尚頗識之。」〔一０〕莽因曰：「太子宮幸近，可壹往遊觀，不足以為勞。」於是太后幸太子宮，甚說。〔一一〕太后旁弄兒病在外舍，〔一二〕莽自親候之。其欲得太后意如此。","sentenceOrder":126},
  {"id":"s_work_han_thu_115_127","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　張晏曰：「以遊觀之樂易其權，若市買。」師古曰：「此虞與娛同。」","sentenceOrder":127},
  {"id":"s_work_han_thu_115_128","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「邑外謂之郊，近二十里也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_115_129","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　師古曰：「漢宮閣疏云上林苑有繭觀，蓋蠶繭之所也。」","sentenceOrder":129},
  {"id":"s_work_han_thu_115_130","chapterId":"ch_work_han_thu_115","textTraditional":"〔四〕　師古曰：「桑，採桑也。遵，循也，謂緣水邊。」","sentenceOrder":130},
  {"id":"s_work_han_thu_115_131","chapterId":"ch_work_han_thu_115","textTraditional":"〔五〕　師古曰：「篽宿苑在長安城南，今之御宿川是也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_115_132","chapterId":"ch_work_han_thu_115","textTraditional":"〔六〕　師古曰：「黃山宮在槐里。飛羽殿在未央宮中。羽字或作雨。」","sentenceOrder":132},
  {"id":"s_work_han_thu_115_133","chapterId":"ch_work_han_thu_115","textTraditional":"〔七〕　師古曰：「上蘭，觀名也，在上林中。」","sentenceOrder":133},
  {"id":"s_work_han_thu_115_134","chapterId":"ch_work_han_thu_115","textTraditional":"〔八〕　師古曰：「在長平阪也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_115_135","chapterId":"ch_work_han_thu_115","textTraditional":"〔九〕　師古曰：「從音千容反。」","sentenceOrder":135},
  {"id":"s_work_han_thu_115_136","chapterId":"ch_work_han_thu_115","textTraditional":"〔一０〕師古曰：「識，記也，音式志反。」","sentenceOrder":136},
  {"id":"s_work_han_thu_115_137","chapterId":"ch_work_han_thu_115","textTraditional":"〔一一〕師古曰：「說讀曰悅。」","sentenceOrder":137},
  {"id":"s_work_han_thu_115_138","chapterId":"ch_work_han_thu_115","textTraditional":"〔一二〕服虔曰：「官婢侍史生兒，取以作弄兒也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_115_139","chapterId":"ch_work_han_thu_115","textTraditional":"平帝崩，無子，莽徵宣帝玄孫選最少者廣戚侯子劉嬰，年二歲，託以卜相為最吉。乃風公卿奏請立嬰為孺子，〔一〕令宰衡安漢公莽踐祚居攝，如周公傅成王故事。太后不以為可，力不能禁，於是莽遂為攝皇帝，改元稱制焉。俄而宗室安眾侯劉崇及東郡太守翟義等惡之，更舉兵欲誅莽。〔二〕太后聞之，曰：「人心不相遠也。〔三〕我雖婦人，亦知莽必以是自危，不可。」其後，莽遂以符命自立為真皇帝，先奉諸符瑞以白太后，太后大驚。","sentenceOrder":139},
  {"id":"s_work_han_thu_115_140","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「風讀曰諷。」","sentenceOrder":140},
  {"id":"s_work_han_thu_115_141","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「更音工衡反。」","sentenceOrder":141},
  {"id":"s_work_han_thu_115_142","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　師古曰：「言所見者同。」","sentenceOrder":142},
  {"id":"s_work_han_thu_115_143","chapterId":"ch_work_han_thu_115","textTraditional":"初，漢高祖入咸陽至霸上，秦王子嬰降於軹道，奉上始皇璽。及高祖誅項籍，即天子位，因御服其璽，世世傳受，號曰漢傳國璽。以孺子未立，璽臧長樂宮。及莽即位，請璽，太后不肯授莽。莽使安陽侯舜諭指。舜素謹敕，太后雅愛信之。舜既見，太后知其為莽求璽，怒罵之曰：「而屬父子宗族蒙漢家力，富貴累世，〔一〕既無以報，受人孤寄，乘便利時，奪取其國，〔二〕不復顧恩義。人如此者，狗豬不食其餘，〔三〕天子豈有而兄弟邪！且若自以金匱符命為新皇帝，〔四〕變更正朔服制，亦當自更作璽，傳之萬世，何用此亡國不祥璽為，而欲求之？我漢家老寡婦，旦暮且死，欲與此璽俱葬，終不可得！」太后因涕泣而言，旁側長御以下皆垂涕。舜亦悲不能自止，良久乃仰謂太后：「臣等已無可言者。〔五〕莽必欲得傳國璽，太后寧能終不與邪！」太后聞舜語切，恐莽欲脅之，乃出漢傳國璽，投之地以授舜，曰：「我老已死，（知）〔如〕而兄弟，今族滅也！」舜既得傳國璽，奏之，莽大說，〔六〕乃為太后置酒未央宮漸臺，大縱眾樂。","sentenceOrder":143},
  {"id":"s_work_han_thu_115_144","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「而，汝也。」","sentenceOrder":144},
  {"id":"s_work_han_thu_115_145","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「孤寄，言以孤寄託之。」","sentenceOrder":145},
  {"id":"s_work_han_thu_115_146","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　師古曰：「言惡賤。」","sentenceOrder":146},
  {"id":"s_work_han_thu_115_147","chapterId":"ch_work_han_thu_115","textTraditional":"〔四〕　師古曰：「若亦汝。」","sentenceOrder":147},
  {"id":"s_work_han_thu_115_148","chapterId":"ch_work_han_thu_115","textTraditional":"〔五〕　師古曰：「言不可諫止。」","sentenceOrder":148},
  {"id":"s_work_han_thu_115_149","chapterId":"ch_work_han_thu_115","textTraditional":"〔六〕　師古曰：「說讀曰悅。」","sentenceOrder":149},
  {"id":"s_work_han_thu_115_150","chapterId":"ch_work_han_thu_115","textTraditional":"莽又欲改太后漢家舊號，易其璽綬，恐不見聽，而莽疏屬王諫欲諂莽，上書言：「皇天廢去漢而命立新室，太皇太后不宜稱尊號，當隨漢廢，以奉天命。」莽乃車駕至東宮，親以其書白太后。太后曰：「此言是也！」〔一〕莽因曰：「此誖德之臣也，〔二〕罪當誅！」於是冠軍張永獻符命銅璧，文言「太皇太后當為新室文母太皇太后」。〔三〕莽乃下詔曰：「予視群公，咸曰『休哉！〔四〕其文字非刻非畫，厥性自然。』予伏念皇天命予為子，更命太皇太后為『新室文母太皇太后』，協于新（室）故交代之際，信於漢氏。哀帝之代，世傳行詔籌，為西王母共具之祥，〔五〕當為歷代（為）母，昭然著明。予祗畏天命，敢不欽承！謹以令月吉日，親率群公諸侯卿士，奉上皇太后璽紱，〔六〕以當順天心，光于四海焉。」太后聽許。莽於是鴆殺王諫，而封張永為貢符子。","sentenceOrder":150},
  {"id":"s_work_han_thu_115_151","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「恚懟之辭也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_115_152","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「誖，乖也，音布內反。」","sentenceOrder":152},
  {"id":"s_work_han_thu_115_153","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　服虔曰：「銅璧，如璧形，以銅為之也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_115_154","chapterId":"ch_work_han_thu_115","textTraditional":"〔四〕　師古曰：「視讀曰示。休，美也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_115_155","chapterId":"ch_work_han_thu_115","textTraditional":"〔五〕　師古曰：「共音居用反。」","sentenceOrder":155},
  {"id":"s_work_han_thu_115_156","chapterId":"ch_work_han_thu_115","textTraditional":"〔六〕　師古曰：「（比）〔此〕紱謂璽之組也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_115_157","chapterId":"ch_work_han_thu_115","textTraditional":"初，莽為安漢公時，又諂太后，奏尊元帝廟為高宗，太后晏駕後當以禮配食云。及莽改〔號〕太后為新室文母，絕之於漢，不令得體元帝。墮壞孝元廟，〔一〕更為文母太后起廟，獨置孝元廟故殿以為文母篹食堂，〔二〕既成，名曰長壽宮。以太后在，故未謂之廟。莽以太后好出遊觀，乃車駕置酒長壽宮，請太后。既至，見孝元廟廢徹塗地，太后驚，泣曰：「此漢家宗廟，皆有神靈，與何治而壞之〔三〕！且使鬼神無知，又何用廟為！如令有知，我乃人之妃妾，豈宜辱帝之堂以陳饋食哉！」私謂左右曰：「此人嫚神多矣，能久得祐乎！」飲酒不樂而罷。","sentenceOrder":157},
  {"id":"s_work_han_thu_115_158","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「墮，毀也，音火規反。」","sentenceOrder":158},
  {"id":"s_work_han_thu_115_159","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　孟康曰：「篹音撰。」晉灼曰：「篹，具也。」","sentenceOrder":159},
  {"id":"s_work_han_thu_115_160","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　師古曰：「與音預。言此何罪，於汝無所（過）〔干〕預，何為毀壞之！」","sentenceOrder":160},
  {"id":"s_work_han_thu_115_161","chapterId":"ch_work_han_thu_115","textTraditional":"自莽篡位後，知太后怨恨，求所以媚太后無不為，然愈不說〔一〕。莽更漢家黑貂，著黃貂，〔二〕又改漢正朔伏臘日。太后令其官屬黑貂，至漢家正臘日，獨與其左右相對飲酒食。","sentenceOrder":161},
  {"id":"s_work_han_thu_115_162","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":162},
  {"id":"s_work_han_thu_115_163","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　孟康曰：「侍中所著貂也。莽更漢制也。」師古曰：「更亦改。」","sentenceOrder":163},
  {"id":"s_work_han_thu_115_164","chapterId":"ch_work_han_thu_115","textTraditional":"太后年八十四，建國五年二月癸丑崩。三月乙酉，合葬渭陵。莽詔大夫揚雄作誄曰：「太陰之精，沙麓之靈，作合於漢，配元生成。」著其協於元城沙麓。（泰）〔太〕陰精者，謂夢月也。太后崩後十年，漢兵誅莽。","sentenceOrder":164},
  {"id":"s_work_han_thu_115_165","chapterId":"ch_work_han_thu_115","textTraditional":"初，紅陽侯立就國南陽，與諸劉結恩，立少子丹為中山太守。世祖初起，丹降為將軍，戰死。上閔之，封丹子泓為武桓侯，至今〔一〕。","sentenceOrder":165},
  {"id":"s_work_han_thu_115_166","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「泓音於宏反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_115_167","chapterId":"ch_work_han_thu_115","textTraditional":"司徒掾班彪曰：三代以來，春秋所記，王公國君，與其失世，稀不以女寵。漢興，后妃之家呂、霍、上官，幾危國者數矣。〔一〕及王莽之興，由孝元后歷漢四世為天下母，饗國六十餘載，群弟世權，更持國柄，〔二〕五將十侯，卒成新都。位號已移於天下，而元后卷卷猶握一璽，〔二〕不欲以授莽，婦人之仁，悲夫！","sentenceOrder":167},
  {"id":"s_work_han_thu_115_168","chapterId":"ch_work_han_thu_115","textTraditional":"〔一〕　師古曰：「幾音巨依反。數音所角反。」","sentenceOrder":168},
  {"id":"s_work_han_thu_115_169","chapterId":"ch_work_han_thu_115","textTraditional":"〔二〕　師古曰：「更音工衡反。」","sentenceOrder":169},
  {"id":"s_work_han_thu_115_170","chapterId":"ch_work_han_thu_115","textTraditional":"〔三〕　師古曰：「卷音其圓反。解在劉向傳。」","sentenceOrder":170},
  {"id":"s_work_han_thu_115_171","chapterId":"ch_work_han_thu_115","textTraditional":"校勘記","sentenceOrder":171},
  {"id":"s_work_han_thu_115_172","chapterId":"ch_work_han_thu_115","textTraditional":"四０一三頁　五行　田和有齊國，（三）〔二〕世稱王。　宋祁說舊本「三」作「二」。按景祐本作「二」。楊樹達說實五世。","sentenceOrder":172},
  {"id":"s_work_han_thu_115_173","chapterId":"ch_work_han_thu_115","textTraditional":"四０一四頁一二行　至〔哀帝元壽二年〕，哀帝崩，　景祐、殿本都有「至」下六字。","sentenceOrder":173},
  {"id":"s_work_han_thu_115_174","chapterId":"ch_work_han_thu_115","textTraditional":"四０一四頁一六行　（王）翁孺生禁，　景祐、殿本都無「王」字。","sentenceOrder":174},
  {"id":"s_work_han_thu_115_175","chapterId":"ch_work_han_thu_115","textTraditional":"四０一五頁一五行　長御即以為〔是〕。　錢大昭說「為」下脫「是」字。按景祐、殿、局本都不脫。","sentenceOrder":175},
  {"id":"s_work_han_thu_115_176","chapterId":"ch_work_han_thu_115","textTraditional":"四０一九頁一二行　上與相對〔涕〕泣而決。　景祐、殿本有「涕」字。","sentenceOrder":176},
  {"id":"s_work_han_thu_115_177","chapterId":"ch_work_han_thu_115","textTraditional":"四０二０頁　六行　天道聰明，（佐）〔佑〕善而災惡，　景祐、殿本都作「佑」。","sentenceOrder":177},
  {"id":"s_work_han_thu_115_178","chapterId":"ch_work_han_thu_115","textTraditional":"四０二三頁　五行　故天變（屢）〔婁〕臻，　景祐、殿本都作「婁」，並有師古注四字。","sentenceOrder":178},
  {"id":"s_work_han_thu_115_179","chapterId":"ch_work_han_thu_115","textTraditional":"四０二四頁　二行　〔其〕奢僭如此。　景祐、汲古、殿、局本都有「其」字，此脫。","sentenceOrder":179},
  {"id":"s_work_han_thu_115_180","chapterId":"ch_work_han_thu_115","textTraditional":"四０二四頁　六行　長安有高都、（水）〔外〕杜里，　景祐本作「外」。","sentenceOrder":180},
  {"id":"s_work_han_thu_115_181","chapterId":"ch_work_han_thu_115","textTraditional":"四０二四頁　七行　（按）李說為（近）是。　景祐、殿本都無「按」字、「近」字。","sentenceOrder":181},
  {"id":"s_work_han_thu_115_182","chapterId":"ch_work_han_thu_115","textTraditional":"四０二四頁一一行　〔言〕譚等五人必不可用。　景祐、殿本都有「言」字，此脫。","sentenceOrder":182},
  {"id":"s_work_han_thu_115_183","chapterId":"ch_work_han_thu_115","textTraditional":"四０二八頁　六行　大治（第宅）〔室第〕，　景祐、殿本都作「室第」。","sentenceOrder":183},
  {"id":"s_work_han_thu_115_184","chapterId":"ch_work_han_thu_115","textTraditional":"四０三０頁　三行　帝年九歲，（常）〔當〕年被疾，　景祐本作「當」。","sentenceOrder":184},
  {"id":"s_work_han_thu_115_185","chapterId":"ch_work_han_thu_115","textTraditional":"四０三二頁一五行　（知）〔如〕而兄弟，今族滅也！　景祐本作「如」。楊樹達說作「如」是。","sentenceOrder":185},
  {"id":"s_work_han_thu_115_186","chapterId":"ch_work_han_thu_115","textTraditional":"四０三三頁一三行　協于新（室）故交代之際，　何焯、李慈銘、楊樹達都說「室」字衍。","sentenceOrder":186},
  {"id":"s_work_han_thu_115_187","chapterId":"ch_work_han_thu_115","textTraditional":"四０三三頁一四行　當為歷代（為）母，　楊樹達說「為母」「為」字疑因上文「為」字而衍。按讀為「當歷代為母」亦通。","sentenceOrder":187},
  {"id":"s_work_han_thu_115_188","chapterId":"ch_work_han_thu_115","textTraditional":"四０三四頁　七行　（比）〔此〕紱謂璽之組也。　景祐、殿本都作「此」，此誤。","sentenceOrder":188},
  {"id":"s_work_han_thu_115_189","chapterId":"ch_work_han_thu_115","textTraditional":"四０三四頁　八行　及莽改〔號〕太后為新室文母，　景祐、殿本都有「號」字。","sentenceOrder":189},
  {"id":"s_work_han_thu_115_190","chapterId":"ch_work_han_thu_115","textTraditional":"四０三五頁　一行　於汝無所（過）〔干〕預，　景祐、殿、局本都作「干」。","sentenceOrder":190},
  {"id":"s_work_han_thu_115_191","chapterId":"ch_work_han_thu_115","textTraditional":"四０三五頁　七行　（泰）〔太〕陰精者，　殿本作「太」。","sentenceOrder":191},
  {"id":"s_work_han_thu_116_1","chapterId":"ch_work_han_thu_116","textTraditional":"王莽字巨君，孝元皇后之弟子也。元后父及兄弟皆以元、成世封侯，居位輔政，家凡九侯、五大司馬，語在元后傳。〔一〕唯莽父曼蚤死，不侯。〔二〕莽群兄弟皆將軍五侯子，乘時侈靡，〔三〕以輿馬聲色佚游相高，〔四〕莽獨孤貧，因折節為恭儉。受禮經，師事沛郡陳參，勤身博學，被服如儒生。〔五〕事母及寡嫂，養孤兄子，行甚敕備。〔六〕又外交英俊，內事諸父，曲有禮意。陽朔中，世父大將軍鳳病，〔七〕莽侍疾，親嘗藥，亂首垢面，不解衣帶連月。鳳且死，以託太后及帝，拜為黃門郎，遷射聲校尉。","sentenceOrder":1},
  {"id":"s_work_han_thu_116_2","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「外戚傳言十侯，此云九侯，以鳳本嗣禁為侯。」","sentenceOrder":2},
  {"id":"s_work_han_thu_116_3","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「蚤，古早字。」","sentenceOrder":3},
  {"id":"s_work_han_thu_116_4","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「乘，因也，因貴戚之時。」","sentenceOrder":4},
  {"id":"s_work_han_thu_116_5","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「佚字與逸同。」","sentenceOrder":5},
  {"id":"s_work_han_thu_116_6","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「被音皮義反。」","sentenceOrder":6},
  {"id":"s_work_han_thu_116_7","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「敕，整也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_116_8","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　師古曰：「謂伯父也，以居長嫡而繼統也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_116_9","chapterId":"ch_work_han_thu_116","textTraditional":"久之，叔父成都侯商上書，願分戶邑以封莽，及長樂少府戴崇、侍中金涉、胡騎校尉箕閎、上谷都尉陽並、中郎陳湯，皆當世名士，咸為莽言，上由是賢莽。永始元年，封莽為新都侯，國南陽新野之都鄉，千五百戶。遷騎都尉光祿大夫侍中，宿衛謹敕，爵位益尊，節操愈謙。散輿馬衣裘，振施賓客，〔一〕家無所餘。收贍名士，交結將相卿大夫甚眾。故在位更推薦之，〔二〕游者為之談說，虛譽隆洽，傾其諸父矣。敢為激發之行，處之不慚恧。〔三〕","sentenceOrder":9},
  {"id":"s_work_han_thu_116_10","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「振，舉也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_116_11","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「更音工衡反。」","sentenceOrder":11},
  {"id":"s_work_han_thu_116_12","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「激，急動也。恧，愧也。激音工歷反。恧音女六反。」","sentenceOrder":12},
  {"id":"s_work_han_thu_116_13","chapterId":"ch_work_han_thu_116","textTraditional":"莽兄永為諸曹，蚤死，有子光，莽使學博士門下。莽休沐出，振車騎，〔一〕奉羊酒，勞遺其師，恩施下竟同學。〔二〕諸生縱觀，長老嘆息。光年小於莽子宇，莽使同日內婦，賓客滿堂。須臾，一人言太夫人苦某痛，當飲某藥，比客罷者數起焉。〔三〕（為）〔嘗〕私買侍婢，昆弟或頗聞知，莽因曰：「後將軍朱子元無子，〔四〕莽聞此兒種宜子，〔五〕為買之。」即日以婢奉子元。其匿情求名如此。","sentenceOrder":13},
  {"id":"s_work_han_thu_116_14","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「振，整也。一曰，振，張起也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_116_15","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「竟，周遍也。」","sentenceOrder":15},
  {"id":"s_work_han_thu_116_16","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「比音必寐反。數音所角反。」","sentenceOrder":16},
  {"id":"s_work_han_thu_116_17","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「謂朱博。」","sentenceOrder":17},
  {"id":"s_work_han_thu_116_18","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「此兒謂所買婢也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_116_19","chapterId":"ch_work_han_thu_116","textTraditional":"是時，太后姊子淳于長以材能為九卿，先進在莽右。〔一〕莽陰求其罪過，因大司馬曲陽侯根白之，長伏誅，莽以獲忠直，語在長傳。根因乞骸骨，薦莽自代，上遂擢為大司馬。是歲，綏和元年也，年三十八矣。莽既拔出同列，繼四父而輔政，〔二〕欲令名譽過前人，遂克己不倦，聘諸賢良以為掾史，賞賜邑錢悉以享士，愈為儉約。母病，公卿列侯遣夫人問疾，莽妻迎之，衣不曳地，布蔽膝。見之者以為僮使，問知其夫人，皆驚。","sentenceOrder":19},
  {"id":"s_work_han_thu_116_20","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「名位居其右。右，前也。」","sentenceOrder":20},
  {"id":"s_work_han_thu_116_21","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「鳳、商、音、根四人皆為大司馬，而莽之諸父也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_116_22","chapterId":"ch_work_han_thu_116","textTraditional":"輔政歲餘，成帝崩，哀帝即位，尊皇太后為太皇太后。太后詔莽就第，避帝外家。莽上疏乞骸骨，哀帝遣尚書令詔莽曰：「先帝委政於君而棄群臣，朕得奉宗廟，誠嘉與君同心合意。今君移病求退〔一〕，以著朕之不能奉順先帝之意，〔二〕朕甚悲傷焉。已詔尚書待君奏事。」又遣丞相孔光、大司空何武、左將軍師丹、衛尉傅喜白太后曰：「皇帝聞太后詔，甚悲。大司馬即不起，皇帝即不敢聽政。」太后復令莽視事。","sentenceOrder":22},
  {"id":"s_work_han_thu_116_23","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「移書言病也。一曰，以病而移居也。」","sentenceOrder":23},
  {"id":"s_work_han_thu_116_24","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「著，明也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_116_25","chapterId":"ch_work_han_thu_116","textTraditional":"時哀帝祖母定陶傅太后、母丁姬在，高昌侯董宏上書言：「春秋之義，母以子貴，丁姬宜上尊號。」莽與師丹共劾宏誤朝不道，語在丹傳。後日，未央宮置酒，內者令為傅太后張幄，坐於太皇太后坐旁。〔一〕莽案行，責內者令曰：「定陶太后藩妾，何以得與至尊並！」徹去，更設坐。傅太后聞之，大怒，不肯會，重怨恚莽。〔二〕莽復乞骸骨，哀帝賜莽黃金五百斤，安車駟馬，罷就第。公卿大夫多稱之者，上乃加恩寵，置使家，中黃門〔三〕十日一賜餐。下詔曰：「新都侯莽憂勞國家，執義堅固，朕庶幾與為治。太皇太后詔莽就第，朕甚閔焉。其以黃郵聚戶三百五十益封莽，〔四〕位特進，給事中，朝朔望見禮如三公，〔五〕車駕乘綠車從。」〔六〕後二歲，傅太后、丁姬皆稱尊號，丞相朱博奏：「莽前不廣尊尊之義，抑貶尊號，虧損孝道，當伏顯戮，幸蒙赦令，不宜有爵土，請免為庶人。」上曰：「以莽與太皇太后有屬，勿免，遣就國。」","sentenceOrder":25},
  {"id":"s_work_han_thu_116_26","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「坐，並音材臥反。」","sentenceOrder":26},
  {"id":"s_work_han_thu_116_27","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「會謂至置酒所也。重音直用反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_116_28","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　蘇林曰：「使黃門在其家中為使令。」","sentenceOrder":28},
  {"id":"s_work_han_thu_116_29","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　服虔曰：「黃郵在南陽棘陽縣。」","sentenceOrder":29},
  {"id":"s_work_han_thu_116_30","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「見天子之禮也。見音胡電反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_116_31","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「綠車，皇孫之車，天子出行，令莽乘之以從，所以寵也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_116_32","chapterId":"ch_work_han_thu_116","textTraditional":"莽杜門自守，其中子獲殺奴，〔一〕莽切責獲，令自殺。在國三歲，吏上書冤訟莽者以百數。〔二〕元壽元年，日食，賢良周護、宋崇等對策深頌莽功德，上於是徵莽。","sentenceOrder":32},
  {"id":"s_work_han_thu_116_33","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「獲者，莽子之名也。今書本有作護字者，流俗所改耳。」","sentenceOrder":33},
  {"id":"s_work_han_thu_116_34","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「言其合管朝政，不當就國也。」","sentenceOrder":34},
  {"id":"s_work_han_thu_116_35","chapterId":"ch_work_han_thu_116","textTraditional":"始莽就國，南陽太守以莽貴重，選門下掾宛孔休守新都相。〔一〕休謁見莽，莽盡禮自納，休亦聞其名，與相答。後莽疾，休候之，莽緣恩意，進其玉具寶劍，欲以為好。〔二〕休不肯受，莽因曰：「誠見君面有瘢，〔三〕美玉可以滅瘢，欲獻其瑑耳。」即解其瑑〔四〕，休復辭讓。莽曰：「君嫌其賈邪？」〔五〕遂椎碎之，〔六〕自裹以進休，休乃受。及莽徵去，欲見休，休稱疾不見。","sentenceOrder":35},
  {"id":"s_work_han_thu_116_36","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「姓孔名休，宛縣人。」","sentenceOrder":36},
  {"id":"s_work_han_thu_116_37","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「結歡好也，音呼到反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_116_38","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「瘢，創痕也。痕音下恩反。」","sentenceOrder":38},
  {"id":"s_work_han_thu_116_39","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　服虔曰：「瑑音衛。」蘇林曰：「劍鼻也。」師古曰：「瑑字本作，從王彘聲，後轉寫者訛也。瑑自雕瑑字耳，音（彖）〔篆〕也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_116_40","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「賈讀曰價，言其所有價直也。」","sentenceOrder":40},
  {"id":"s_work_han_thu_116_41","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「椎音直追反，其字從木。」","sentenceOrder":41},
  {"id":"s_work_han_thu_116_42","chapterId":"ch_work_han_thu_116","textTraditional":"莽還京師歲餘，哀帝崩，無子，而傅太后、丁太后皆先薨，太皇太后即日駕之未央宮收取璽綬，遣使者馳召莽。詔尚書，諸發兵符節，百官奏事，中黃門、期門兵皆屬莽。莽白：「大司馬高安侯董賢年少，不合眾心，收印綬。」賢即日自殺。太后詔公卿舉可大司馬者，大司徒孔光，大司空彭宣舉莽，前將軍何武、後將軍公孫祿互相舉。太后拜莽為大司馬，與議立嗣。安陽侯王舜莽之從弟，其人修飭〔一〕，太后所信愛也，莽白以舜為車騎將軍，使迎中山王奉成帝後，是為孝平皇帝。帝年九歲，太后臨朝稱制，委政於莽。莽白趙氏前害皇子，傅氏驕僭，遂廢孝成趙皇后、孝哀傅皇后，皆令自殺，語在外戚傳。","sentenceOrder":42},
  {"id":"s_work_han_thu_116_43","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「飭讀與敕同。敕，整也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_116_44","chapterId":"ch_work_han_thu_116","textTraditional":"莽以大司徒孔光名儒，相三主，太后所敬，天下信之，於是盛尊事光，引光女婿甄邯為侍中奉車都尉。諸哀帝外戚及大臣居位素所不說者，〔一〕莽皆傅致其罪，〔二〕為請奏，令邯持與光。光素畏慎，不敢不上之，莽白太后，輒可其奏。於是前將軍何武、後將軍公孫祿坐互相舉免，丁、傅及董賢親屬皆免官爵，徙遠方。紅陽侯立太后親弟，雖不居位，莽以諸父內敬憚之，畏立從容言太后，令己不得肆意，〔三〕乃復令光奏立舊惡：「前知定陵侯淳于長犯大逆罪，多受其賂，為言誤朝；〔四〕後白以官婢楊寄私子為皇子，眾言曰呂氏、少帝復出，紛紛為天下所疑，難以示來世，成襁褓之功。請遣立就國。」太后不聽。莽曰：「今漢家衰，比世無嗣，〔五〕太后獨代幼主統政，誠可畏懼，力用公正先天下，尚恐不從，〔六〕今以私恩逆大臣議如此，群下傾邪，亂從此起！宜可且遣就國，安後復徵召之。」〔七〕太后不得已，遣立就國。莽之所以脅持上下，皆此類也。","sentenceOrder":44},
  {"id":"s_work_han_thu_116_45","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":45},
  {"id":"s_work_han_thu_116_46","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「傅讀曰附。附益而引致之令入罪。」","sentenceOrder":46},
  {"id":"s_work_han_thu_116_47","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「肆，放也，」","sentenceOrder":47},
  {"id":"s_work_han_thu_116_48","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「妄稱譽之，誤惑朝廷也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_116_49","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「比，頻也。」","sentenceOrder":49},
  {"id":"s_work_han_thu_116_50","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「力，勉力。」","sentenceOrder":50},
  {"id":"s_work_han_thu_116_51","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　師古曰：「安猶徐也。」","sentenceOrder":51},
  {"id":"s_work_han_thu_116_52","chapterId":"ch_work_han_thu_116","textTraditional":"於是附順者拔擢，忤恨者誅滅。王舜、王邑為腹心，甄豐、甄邯主擊斷，平晏領機事，劉歆典文章，孫建為爪牙。豐子尋、歆子棻、〔一〕涿郡崔發、南陽陳崇皆以材能幸於莽。莽色厲而言方，〔二〕欲有所為，微見風采，〔三〕黨與承其指意而顯奏之，莽稽首涕泣，固推讓焉，上以惑太后，下用示信於眾庶。","sentenceOrder":52},
  {"id":"s_work_han_thu_116_53","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「棻或作〈暂缺F56D〉字，音扶云反。」","sentenceOrder":53},
  {"id":"s_work_han_thu_116_54","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「外示凜厲之色，而假為方直之言。」","sentenceOrder":54},
  {"id":"s_work_han_thu_116_55","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「見音胡電反。」","sentenceOrder":55},
  {"id":"s_work_han_thu_116_56","chapterId":"ch_work_han_thu_116","textTraditional":"始，風益州令塞外蠻夷獻白雉，〔一〕元始元年正月，莽白太后下詔，以白雉薦宗廟。群臣因奏言太后「委任大司馬莽定策安宗廟。故大司馬霍光有安宗廟之功，益封三萬戶，疇其爵邑，比蕭相國。莽宜如光故事。」太后問公卿曰：「誠以大司馬有大功當著之邪？〔二〕將以骨肉故欲異之也？」於是群臣乃盛陳「莽功德致周成白雉之瑞，千載同符。聖王之法，臣有大功則生有美號，故周公及身在而託號於周。莽有定國安漢家之大功，宜賜號曰安漢公，益戶，疇爵邑，上應古制，下準行事，以順天心。」太后詔尚書具其事。","sentenceOrder":56},
  {"id":"s_work_han_thu_116_57","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「風讀曰諷。下皆類此。」","sentenceOrder":57},
  {"id":"s_work_han_thu_116_58","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「著，明也。」","sentenceOrder":58},
  {"id":"s_work_han_thu_116_59","chapterId":"ch_work_han_thu_116","textTraditional":"莽上書言：「臣與孔光、王舜、甄豐、甄邯共定策，今願獨條光等功賞，寑置臣莽，勿隨輩列。」甄邯白太后下詔曰：「『無偏無黨，王道蕩蕩。』〔一〕屬有親者，義不得阿。君有安宗廟之功，不可以骨肉故蔽隱不揚。君其勿辭。」莽復上書讓。太后詔謁者引莽待殿東箱，莽稱疾不肯入。太后使尚書令恂詔之曰：「君以選故而辭以疾，〔二〕君任重，不可闕，以時亟起。」〔三〕莽遂固辭。太后復使長信太僕閎承制召莽，莽固稱疾。左右白太后，宜勿奪莽意，但條孔光等，莽乃肯起。太后下詔曰：「太傅博山侯光宿衛四世，世為傅相，忠孝仁篤，行義顯著，建議定策，益封萬戶，以光為太師，與四輔之政。〔四〕車騎將軍安陽侯舜積累仁孝，使迎中山王，折衝萬里，功德茂著，益封萬戶，以舜為太保。左將軍光祿勳豐宿衛三世，忠信仁篤，〔五〕使迎中山王，輔導共養，以安宗廟，〔六〕封豐為廣陽侯，食邑五千戶，以豐為少傅。皆授四輔之職，疇其爵邑，各賜第一區。侍中奉車都尉邯宿衛勤勞，建議定策，封邯為承陽侯，食邑二千四百戶。」〔七〕四人既受賞，莽尚未起，群臣復上言：「莽雖克讓，朝所宜章，以時加賞，明重元功，無使百僚元元失望。」太后乃下詔曰：「大司馬新都侯莽三世為三公，典周公之職，建萬世策，功（能）〔德〕為忠臣宗，化流海內，遠人慕義，越裳氏重譯獻白雉。其以召陵、新息二縣戶二萬八千益封莽，復其後嗣，疇其爵邑，〔八〕封功如蕭相國。以莽為太傅，幹四輔之事，號曰安漢公。以故蕭相國甲第為安漢公第，定著於令，傳之無窮。」","sentenceOrder":59},
  {"id":"s_work_han_thu_116_60","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「尚書洪範之言也。蕩蕩，廣平之貌也。故引之。」","sentenceOrder":60},
  {"id":"s_work_han_thu_116_61","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「選，善也。國家欲褒其善，加號疇邑，乃以疾辭。」","sentenceOrder":61},
  {"id":"s_work_han_thu_116_62","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「亟，急也，音居力反。」","sentenceOrder":62},
  {"id":"s_work_han_thu_116_63","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「與讀曰豫。」","sentenceOrder":63},
  {"id":"s_work_han_thu_116_64","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「篤，厚也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_116_65","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「共音居用反。養音弋亮反。」","sentenceOrder":65},
  {"id":"s_work_han_thu_116_66","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　師古曰：「承音蒸。」","sentenceOrder":66},
  {"id":"s_work_han_thu_116_67","chapterId":"ch_work_han_thu_116","textTraditional":"〔八〕　師古曰：「復音方目反。」","sentenceOrder":67},
  {"id":"s_work_han_thu_116_68","chapterId":"ch_work_han_thu_116","textTraditional":"於是莽為惶恐，不得已而起受策。策曰：「漢危無嗣，而公定之；四輔之職，三公之任，而公幹之；群僚眾位，而公宰之：功德茂著，宗廟以安，蓋白雉之瑞，周成象焉。〔一〕故賜嘉號曰安漢公，輔翼于帝，期於致平，〔二〕毋違朕意。」莽受太傅安漢公號，讓還益封疇爵邑事，云願須百姓家給，然後加賞。〔三〕群公復爭，太后詔曰：「公自期百姓家給，是以聽之。其令公奉、舍人、賞賜皆倍故。〔四〕百姓家給人足，大司徒、大司空以聞。」莽復讓不受，而建言宜立諸侯王後及高祖以來功臣子孫，大者封侯，或賜爵關內侯食邑，然後及諸在位，各有第序。上尊宗廟，增加禮樂；下惠士民鰥寡，恩澤之政無所不施。語在平紀。","sentenceOrder":68},
  {"id":"s_work_han_thu_116_69","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「言莽致白雉之瑞，有周公相成王之象。」","sentenceOrder":69},
  {"id":"s_work_han_thu_116_70","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「致太平。」","sentenceOrder":70},
  {"id":"s_work_han_thu_116_71","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「給，足也。家給，家家自足。」","sentenceOrder":71},
  {"id":"s_work_han_thu_116_72","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「奉，所食之奉也。舍人，私府吏員也。倍故，數多於（人）〔故〕各一倍也。奉音扶用反。」","sentenceOrder":72},
  {"id":"s_work_han_thu_116_73","chapterId":"ch_work_han_thu_116","textTraditional":"莽既說眾庶，〔一〕又欲專斷，知太后猒政，乃風公卿〔二〕奏言：「往者，吏以功次遷至二千石，及州部所舉茂材異等吏，率多不稱，宜皆見安漢公。又太后不宜親省小事。」令太后下詔曰：「皇帝幼年，朕且統政，比加元服。〔三〕今眾事煩碎，朕春秋高，精氣不堪，殆非所以安躬體而育養皇帝者也。故選忠賢，立四輔，群下勸職，永以康寧。孔子曰：『巍巍乎，舜禹之有天下而不與焉！』〔四〕自今以來，（非）〔惟〕封爵乃以聞。他事，安漢公、四輔平決。州牧、二千石及茂材吏初除奏事者，輒引入至近署對安漢公，考故官，問新職，以知其稱否。」於是莽人人延問，致密恩意，厚加贈送，其不合指，顯奏免之，權與人主侔矣。","sentenceOrder":73},
  {"id":"s_work_han_thu_116_74","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":74},
  {"id":"s_work_han_thu_116_75","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「風讀曰諷。」","sentenceOrder":75},
  {"id":"s_work_han_thu_116_76","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「比至平帝加元服以來，太后且統政也。比音必寐反。」","sentenceOrder":76},
  {"id":"s_work_han_thu_116_77","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「論語載孔子之言也。巍巍，高貌也。言舜禹之治天下，委任賢臣以成其功，而不身親其事也。與讀曰豫。」","sentenceOrder":77},
  {"id":"s_work_han_thu_116_78","chapterId":"ch_work_han_thu_116","textTraditional":"莽欲以虛名說太后，〔一〕白言「親承前孝哀丁、傅奢侈之後，百姓未贍者多，太后宜且衣繒練，頗損膳，以視天下。」〔二〕莽因上書，願出錢百萬，獻田三十頃，付大司農助給貧民。於是公卿皆慕效焉。莽帥群臣奏言：「陛下春秋尊，久衣重練，減御膳，誠非所以輔精氣，育皇帝，安宗廟也。臣莽數叩頭省戶下，白爭未見許。今幸賴陛下德澤，間者風雨時，甘露降，神芝生，蓂莢、朱草、嘉禾，休徵同時並至。〔三〕臣莽等不勝大願，願陛下愛精休神，闊略思慮，〔四〕遵帝王之常服，復太官之法膳，使臣子各得盡驩心，備共養。惟哀省察！」莽又令太后下詔曰：「蓋聞母后之義，思不出乎門閾。〔五〕國不蒙佑，皇帝年在襁褓，未任親政，戰戰兢兢，懼於宗廟之不安。國家之大綱，微朕孰當統之？〔六〕是以孔子見南子，周公居攝，蓋權時也。〔七〕勤身極思，憂勞未綏，故國奢則視之以儉〔八〕，矯枉者過其正，而朕不身帥，將謂天下何！夙夜夢想，五穀豐孰，百姓家給，比皇帝加元服，委政而授焉。〔九〕今誠未皇于輕靡而備味，〔一０〕庶幾與百僚有成，其勗之哉！」〔一一〕每有水旱，莽輒素食，〔一二〕左右以白。太后遣使者詔莽曰：「聞公菜食，憂民深矣。今秋幸孰，公勤於職，以時食肉，愛身為國。」","sentenceOrder":78},
  {"id":"s_work_han_thu_116_79","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":79},
  {"id":"s_work_han_thu_116_80","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「繒練謂帛無文者。視讀曰示。」","sentenceOrder":80},
  {"id":"s_work_han_thu_116_81","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「休，美也。徵，證也。」","sentenceOrder":81},
  {"id":"s_work_han_thu_116_82","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「闊，寬也。略，簡也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_116_83","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「閾，門橛也，音域。」","sentenceOrder":83},
  {"id":"s_work_han_thu_116_84","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「微，無也。」","sentenceOrder":84},
  {"id":"s_work_han_thu_116_85","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　師古曰：「南子，衛靈公夫人。孔子欲說靈公以治道，故見南子也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_116_86","chapterId":"ch_work_han_thu_116","textTraditional":"〔八〕　師古曰：「視讀曰示。」","sentenceOrder":86},
  {"id":"s_work_han_thu_116_87","chapterId":"ch_work_han_thu_116","textTraditional":"〔九〕　師古曰：「比音必寐反。」","sentenceOrder":87},
  {"id":"s_work_han_thu_116_88","chapterId":"ch_work_han_thu_116","textTraditional":"〔一０〕師古曰：「皇，暇也。靡，細也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_116_89","chapterId":"ch_work_han_thu_116","textTraditional":"〔一一〕師古曰：「勗，勉也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_116_90","chapterId":"ch_work_han_thu_116","textTraditional":"〔一二〕師古曰：「素食即菜食也，解在霍光傳。」","sentenceOrder":90},
  {"id":"s_work_han_thu_116_91","chapterId":"ch_work_han_thu_116","textTraditional":"莽念中國已平，唯四夷未有異，乃遣使者齎黃金幣帛，重賂匈奴單于，使上書言：「聞中國譏二名，故名囊知牙斯今更名知，慕從聖制。」又遣王昭君女須卜居次入侍。所以誑耀媚事太后，下至旁側長御，方故萬端。","sentenceOrder":91},
  {"id":"s_work_han_thu_116_92","chapterId":"ch_work_han_thu_116","textTraditional":"莽既尊重，欲以女配帝為皇后，以固其權，奏言：「皇帝即位三年，長秋宮未建，液廷媵未充。〔一〕乃者，國家之難，本從亡嗣，配取不正。請考論五經，定取禮，〔二〕正十二女之義，以廣繼嗣。博采二王後及周公孔子世列侯在長安者適子女。」〔三〕事下有司，上眾女名，王氏女多在選中者。莽恐其與己女爭，即上言：「身亡德，子材下，不宜與眾女並采。」太后以為至誠，乃下詔曰：「王氏女，朕之外家，其勿采。」庶民、諸生、郎吏以上守闕上書者日千餘人，公卿大夫或詣廷中，或伏省戶下，咸言：「明詔聖德巍巍如彼，安漢公盛勳堂堂若此，今當立后，獨奈何廢公女？天下安所歸命！願得公女為天下母。」莽遣長史以下分部曉止公卿及諸生，〔四〕而上書者愈甚。太后不得已，聽公卿采莽女。莽復自白：「宜博選眾女。」公卿爭曰：「不宜采諸女以貳正統。」〔五〕莽白：「願見女。」太后遣長樂少府、宗正、尚書令納采見女，還奏言：「公女漸漬德化，有窈窕之容，〔六〕宜承（大）〔天〕序，奉祭祀。」有詔遣大司徒、大司空策告宗廟，雜加卜筮，皆曰：「兆遇金水王相，卦遇父母得位，〔七〕所謂『康強』之占，『逢吉』之符也。」信鄉侯佟上言：〔八〕「春秋，天子將娶於紀，則褒紀子稱侯，〔九〕安漢公國未稱古制。」〔一０〕事下有司，皆（白）〔曰〕：「古者天子封后父百里，尊而不臣，以重宗廟，孝之至也。佟言應禮，可許。請以新野田二萬五千六百頃益封莽，滿百里。」莽謝曰：「臣莽子女誠不足以配至尊，復聽眾議，益封臣莽。伏自惟念，得託肺腑，獲爵土，如使子女誠能奉稱聖德，臣莽國邑足以共朝貢，〔一一〕不須復加益地之寵。願歸所益。」太后許之。有司奏「故事，聘皇后黃金二萬斤，為錢二萬萬。」莽深辭讓，受四千萬，而以其三千三百萬予十一媵家。群臣復言：「今皇后受聘，踰群妾亡幾。」〔一二〕有詔，復益二千三百萬，合為三千萬。莽復以其千萬分予九族貧者。","sentenceOrder":92},
  {"id":"s_work_han_thu_116_93","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「液與掖同音通用。」","sentenceOrder":93},
  {"id":"s_work_han_thu_116_94","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「取皆讀曰娶。」","sentenceOrder":94},
  {"id":"s_work_han_thu_116_95","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「適讀曰嫡。謂妻所生也。」","sentenceOrder":95},
  {"id":"s_work_han_thu_116_96","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「分音扶問反。」","sentenceOrder":96},
  {"id":"s_work_han_thu_116_97","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「〔言〕皇后之位當在莽女也。」","sentenceOrder":97},
  {"id":"s_work_han_thu_116_98","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「窈窕，幽閑也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_116_99","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　孟康曰：「金水相生也。」張晏曰：「金王則水相也。遇父母，謂泰卦乾下坤上，天下於地，是配享之卦。」師古曰：「王音于放反。」","sentenceOrder":99},
  {"id":"s_work_han_thu_116_100","chapterId":"ch_work_han_thu_116","textTraditional":"〔八〕　師古曰：「王子侯表清河綱王子豹始封新鄉侯，傳爵至曾孫佟，王莽篡位賜姓王，即謂此也。而此傳作信鄉侯，古者新信同音故耳。佟音（從）〔徒〕冬反。」","sentenceOrder":100},
  {"id":"s_work_han_thu_116_101","chapterId":"ch_work_han_thu_116","textTraditional":"〔九〕　師古曰：「解在外戚恩澤侯表也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_116_102","chapterId":"ch_work_han_thu_116","textTraditional":"〔一０〕師古曰：「稱，副也，音尺孕反。其下亦同。」","sentenceOrder":102},
  {"id":"s_work_han_thu_116_103","chapterId":"ch_work_han_thu_116","textTraditional":"〔一一〕師古曰：「共讀曰供。」","sentenceOrder":103},
  {"id":"s_work_han_thu_116_104","chapterId":"ch_work_han_thu_116","textTraditional":"〔一二〕師古曰：「亡幾，不多也。亡讀曰無。幾音居豈反。其下並同。」","sentenceOrder":104},
  {"id":"s_work_han_thu_116_105","chapterId":"ch_work_han_thu_116","textTraditional":"陳崇時為大司徒司直，與張敞孫竦相善。竦者博通士，為崇草奏，稱莽功德，〔一〕崇奏之，曰：","sentenceOrder":105},
  {"id":"s_work_han_thu_116_106","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「草謂創立其文也。」","sentenceOrder":106},
  {"id":"s_work_han_thu_116_107","chapterId":"ch_work_han_thu_116","textTraditional":"竊見安漢公自初束脩，〔一〕值世俗隆奢麗之時，蒙兩宮厚骨肉之寵，〔二〕被諸父赫赫之光，〔三〕財饒勢足，亡所啎意〔四〕，然而折節行仁，克心履禮，拂世矯俗，確然特立；〔五〕惡衣惡食，陋車駑馬，妃匹無二，閨門之內，孝友之德，眾莫不聞；清靜樂道，溫良下士，〔六〕惠于故舊，篤于師友。孔子曰「未若貧而樂，富而好禮」，〔七〕公之謂矣。","sentenceOrder":107},
  {"id":"s_work_han_thu_116_108","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「束脩謂初學官之時。」","sentenceOrder":108},
  {"id":"s_work_han_thu_116_109","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「兩宮謂成帝及太后。」","sentenceOrder":109},
  {"id":"s_work_han_thu_116_110","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「被音皮義反。」","sentenceOrder":110},
  {"id":"s_work_han_thu_116_111","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「啎，逆也，無人能逆其意也。啎音五故反。」","sentenceOrder":111},
  {"id":"s_work_han_thu_116_112","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「拂，違也。矯，正也。拂音佛。」","sentenceOrder":112},
  {"id":"s_work_han_thu_116_113","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「下音胡嫁反。」","sentenceOrder":113},
  {"id":"s_work_han_thu_116_114","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　師古曰：「論語子貢問曰：『貧而無諂，富而無驕，何如？』孔子曰：『可也，未若貧而樂，富而好禮者也。』」","sentenceOrder":114},
  {"id":"s_work_han_thu_116_115","chapterId":"ch_work_han_thu_116","textTraditional":"及為侍中，故定陵侯淳于長有大逆罪，公不敢私，建白誅討。〔一〕周公誅管蔡，季子鴆叔牙，〔二〕公之謂矣。","sentenceOrder":115},
  {"id":"s_work_han_thu_116_116","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「首言其事也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_116_117","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「解並在前。」","sentenceOrder":117},
  {"id":"s_work_han_thu_116_118","chapterId":"ch_work_han_thu_116","textTraditional":"是以孝成皇帝命公大司馬，委以國統。孝哀即位，高昌侯董宏希指求美，造作二統，〔一〕公手劾之，以定大綱。建白定陶太后不宜在乘輿幄坐，〔二〕以明國體。詩曰「柔亦不茹，剛亦不吐，不侮鰥寡，不畏強圉」，〔三〕公之謂矣。","sentenceOrder":118},
  {"id":"s_work_han_thu_116_119","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　晉灼曰：「欲令丁姬為帝太后也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_116_120","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「坐音才臥反。」","sentenceOrder":120},
  {"id":"s_work_han_thu_116_121","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「大雅蒸人之詩，美仲山甫之德。茹，食也。強圉，強梁圉扞也。」","sentenceOrder":121},
  {"id":"s_work_han_thu_116_122","chapterId":"ch_work_han_thu_116","textTraditional":"深執謙退，推誠讓位。定陶太后欲立僭號，憚彼面刺幄坐之義，佞惑之雄，朱博之疇，懲此長、宏手劾之事，上下壹心，讒賊交亂，詭辟制度，遂成篡號，〔一〕斥逐仁賢，誅殘戚屬，而公被胥、原之訴，遠去就國，〔二〕朝政崩壞，綱紀廢弛，危亡之禍，不隧如髮。〔三〕詩云「人之云亡，邦國殄悴」，〔四〕公之謂矣。","sentenceOrder":122},
  {"id":"s_work_han_thu_116_123","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「詭，違也。辟讀曰僻。」","sentenceOrder":123},
  {"id":"s_work_han_thu_116_124","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　應劭曰：「胥、原，子胥、屈原也。」師古曰：「遠去朝廷，而就其侯國。」","sentenceOrder":124},
  {"id":"s_work_han_thu_116_125","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「弛，解也，音式爾反。隧音直類反。」","sentenceOrder":125},
  {"id":"s_work_han_thu_116_126","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「大雅瞻仰之詩也。殄，盡也。悴，病也。言為政不善，賢人奔亡矣，天下邦國盡困病也。顇與（萃）〔悴〕同，音才醉反。」","sentenceOrder":126},
  {"id":"s_work_han_thu_116_127","chapterId":"ch_work_han_thu_116","textTraditional":"當此之時，宮亡儲主，董賢據重，加以傅氏有女之援，〔一〕皆自知得罪天下，結讎中山，〔二〕則必同憂，斷金相翼，〔三〕藉假遺詔，頻用賞誅，先除所憚，急引所附，遂誣往冤，更徵遠屬，事勢張見，其不難矣！〔四〕賴公立入，即時退賢，及其黨親。當此之時，公運獨見之明，奮亡前之威，〔五〕盱衡厲色，振揚武怒〔六〕，乘其未堅，厭其未發，〔七〕震起機動，敵人摧折，雖有賁育不及持刺，〔八〕雖有樗里不及回知，〔九〕雖有鬼谷不及造次，〔一０〕是故董賢喪其魂魄，遂自絞殺。人不還踵，日不移晷，〔一一〕霍然四除，更為寧朝。非陛下莫引立公，非公莫克此禍。詩云「惟師尚父，時惟鷹揚，亮彼武王」，〔一二〕孔子曰「敏則有功」，〔一三〕公之謂矣。","sentenceOrder":127},
  {"id":"s_work_han_thu_116_128","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「謂哀帝傅皇后。」","sentenceOrder":128},
  {"id":"s_work_han_thu_116_129","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　張晏曰：「傅太后譖中山馮太后，陷以祝詛之罪。」","sentenceOrder":129},
  {"id":"s_work_han_thu_116_130","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「引易繫辭『二人同心，其利斷金』。翼，助也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_116_131","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「言哀帝既崩，丁、傅、董賢欲稱遺詔，樹立黨親，共立幼王，以據國權也。遠屬，國之宗室疏遠者也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_116_132","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「無前謂無有敢當之者。」","sentenceOrder":132},
  {"id":"s_work_han_thu_116_133","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　孟康曰：「眉上曰衡。盱衡，舉眉揚目也。」師古曰：「盱音許于反。」","sentenceOrder":133},
  {"id":"s_work_han_thu_116_134","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　師古曰：「厭音一涉反。」","sentenceOrder":134},
  {"id":"s_work_han_thu_116_135","chapterId":"ch_work_han_thu_116","textTraditional":"〔八〕　師古曰：「孟賁、夏育皆古勇士也。持刺謂持兵（力）〔刃〕以刺。」","sentenceOrder":135},
  {"id":"s_work_han_thu_116_136","chapterId":"ch_work_han_thu_116","textTraditional":"〔九〕　師古曰：「樗里子名疾，秦惠王之弟也，為秦相，時人號曰智囊。」","sentenceOrder":136},
  {"id":"s_work_han_thu_116_137","chapterId":"ch_work_han_thu_116","textTraditional":"〔一０〕師古曰：「鬼谷先生，蘇秦之師，善談說。」","sentenceOrder":137},
  {"id":"s_work_han_thu_116_138","chapterId":"ch_work_han_thu_116","textTraditional":"〔一一〕師古曰：「還讀曰旋。晷，景也。言其速疾。」","sentenceOrder":138},
  {"id":"s_work_han_thu_116_139","chapterId":"ch_work_han_thu_116","textTraditional":"〔一二〕師古曰：「大雅大明之詩也。師尚父，太公也。亮，助也。言太公武毅，若鷹之飛揚，佐助武王以克殷也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_116_140","chapterId":"ch_work_han_thu_116","textTraditional":"〔一三〕師古曰：「論語載孔子對子張之言也。敏，疾也。言應事速疾，乃能成功。」","sentenceOrder":140},
  {"id":"s_work_han_thu_116_141","chapterId":"ch_work_han_thu_116","textTraditional":"於是公乃白內故泗水相豐、斄令邯，〔一〕與大司徒光、車騎將軍舜建定社稷，奉節東迎，皆以功德受封益土，為國名臣。書曰「知人則哲」，〔二〕公之謂也。","sentenceOrder":141},
  {"id":"s_work_han_thu_116_142","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「甄豐、甄邯也。斄讀曰邰。」","sentenceOrder":142},
  {"id":"s_work_han_thu_116_143","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「虞書咎繇謨之辭也。哲，智也。」","sentenceOrder":143},
  {"id":"s_work_han_thu_116_144","chapterId":"ch_work_han_thu_116","textTraditional":"公卿咸歎公德，同盛公勳，皆以周公為比，〔一〕宜賜號安漢公，益封二縣，公皆不受。傳曰申包胥不受存楚之報，晏平仲不受輔齊之封，〔二〕孔子曰「能以禮讓為國乎何有」，〔三〕公之謂也。","sentenceOrder":144},
  {"id":"s_work_han_thu_116_145","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「比音必寐反。」","sentenceOrder":145},
  {"id":"s_work_han_thu_116_146","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「申包胥，楚大夫也。吳師入郢，楚昭王出奔，包胥如秦乞師，秦出師以救楚。昭王反國欲賞，包胥辭曰：『吾為君也，非為身也。』遂不受。晏平仲，齊大夫晏嬰也，以道佐齊景公。景公欲封之，讓而不受。」","sentenceOrder":146},
  {"id":"s_work_han_thu_116_147","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「論語載孔子之言也。解在董仲舒傳。」","sentenceOrder":147},
  {"id":"s_work_han_thu_116_148","chapterId":"ch_work_han_thu_116","textTraditional":"將為皇帝定立妃后，有司上名，公女為首，公深辭讓，迫不得已然後受詔。父子之親天性自然，欲其榮貴甚於為身，皇后之尊侔於天子，當時之會千載希有，然而公惟國家之統，揖大福之恩，〔一〕事事謙退，動而固辭。書曰「舜讓于德不嗣」，〔二〕公之謂矣。","sentenceOrder":148},
  {"id":"s_work_han_thu_116_149","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「揖謂讓而不當也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_116_150","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　（書）〔師古〕曰：「虞書舜典之辭，言舜自讓德薄，不足以繼帝堯之事也。」","sentenceOrder":150},
  {"id":"s_work_han_thu_116_151","chapterId":"ch_work_han_thu_116","textTraditional":"自公受策，以至于今，斖斖翼翼，日新其德，〔一〕增修雅素以命下國，〈俊，中“亻改彳”〉儉隆約以矯世俗，〔二〕割財損家以帥群下，彌躬執平以逮公卿，〔三〕教子尊學以隆國化。僮奴衣布，馬不秣穀，食飲之用，不過凡庶。詩云「溫溫恭人，如集于木」，〔四〕孔子曰「食無求飽，居無求安」，〔五〕公之謂矣。","sentenceOrder":151},
  {"id":"s_work_han_thu_116_152","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「斖斖，勉也。翼翼，敬也。斖音武匪反。」","sentenceOrder":152},
  {"id":"s_work_han_thu_116_153","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「〈俊，中“亻改彳”〉，退也。矯，正也。〈俊，中“亻改彳”〉音千旬反，其字從彳」","sentenceOrder":153},
  {"id":"s_work_han_thu_116_154","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「彌讀與弭同。」","sentenceOrder":154},
  {"id":"s_work_han_thu_116_155","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「小雅小宛之詩。溫溫，柔貌也。如集于木，恐墮墜耳。」","sentenceOrder":155},
  {"id":"s_work_han_thu_116_156","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「論語載孔子之言也。謂君子好學樂道，故志不在安飽。」","sentenceOrder":156},
  {"id":"s_work_han_thu_116_157","chapterId":"ch_work_han_thu_116","textTraditional":"克身自約，糴食逮給，〔一〕物物卬市，日闋亡儲。〔二〕又上書歸孝哀皇帝所益封邑，入錢獻田，殫盡舊業，為眾倡始。〔三〕於是小大鄉和，承風從化，〔四〕外則王公列侯，內則帷幄侍御，翕然同時，各竭所有，或入金錢，或獻田畝，以振貧窮，收贍不足者。昔令尹子文朝不及夕，魯公儀子不茹園葵，〔五〕公之謂矣。","sentenceOrder":157},
  {"id":"s_work_han_thu_116_158","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「纔得粗及僅足而已。」","sentenceOrder":158},
  {"id":"s_work_han_thu_116_159","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「物物卬市，言其衣食所須皆買之於市，不自營作，而不奪工商利也。闋，盡也。日闋，言當日即盡，不蓄積也。卬音牛向反。闋音空穴反。」","sentenceOrder":159},
  {"id":"s_work_han_thu_116_160","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「倡音尺尚反。」","sentenceOrder":160},
  {"id":"s_work_han_thu_116_161","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":161},
  {"id":"s_work_han_thu_116_162","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　張晏曰：「令尹子文自毀其家以紓楚國之難，仕而逃祿，朝不及夕也。」師古曰：「子文，楚令尹鬥穀於菟也。公儀子，魯國相公儀休也，拔其園葵，不奪園夫之利。食菜曰茹，音人諸反。」","sentenceOrder":162},
  {"id":"s_work_han_thu_116_163","chapterId":"ch_work_han_thu_116","textTraditional":"開門延士，下及白屋，〔一〕婁省朝政，綜管眾治，〔二〕親見牧守以下，考跡雅素，審知白黑。詩云「夙夜匪解，以事一人」，〔三〕易曰「終日乾乾，夕惕若厲」，〔四〕公之謂矣。","sentenceOrder":163},
  {"id":"s_work_han_thu_116_164","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「白屋，謂庶人以白茅覆屋者也。」","sentenceOrder":164},
  {"id":"s_work_han_thu_116_165","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「婁，古屢字。」","sentenceOrder":165},
  {"id":"s_work_han_thu_116_166","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「大雅烝人之詩也。一人，天子也。解讀曰懈。」","sentenceOrder":166},
  {"id":"s_work_han_thu_116_167","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「乾卦九三爻辭也。乾乾，自強之意。惕，懼也。厲，病也。」","sentenceOrder":167},
  {"id":"s_work_han_thu_116_168","chapterId":"ch_work_han_thu_116","textTraditional":"比三世為三公，再奉送大行，〔一〕秉冢宰職，填安國家，〔二〕四海輻（奏）〔湊〕，靡不得所。書曰「納于大麓，列風雷雨不迷」，〔三〕公之謂矣。","sentenceOrder":168},
  {"id":"s_work_han_thu_116_169","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「比，頻也。」","sentenceOrder":169},
  {"id":"s_work_han_thu_116_170","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「填音竹刃反。」","sentenceOrder":170},
  {"id":"s_work_han_thu_116_171","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「虞書舜典敘舜之德。麓，錄也。言堯使舜大錄萬機之政。一曰，山足曰麓。言有聖德，雖遇風雷不迷惑也。」","sentenceOrder":171},
  {"id":"s_work_han_thu_116_172","chapterId":"ch_work_han_thu_116","textTraditional":"此皆上世之所鮮，禹稷之所難，〔一〕而公包其終始，一以貫之，可謂備矣！〔二〕是以三年之間，化行如神，嘉瑞疊累，豈非陛下知人之效，得賢之致哉！故非獨君之受命也，臣之生亦不虛矣。是以伯禹錫玄圭，周公受郊祀，〔三〕蓋以達天之使，不敢擅天之功也。〔四〕揆公德行，為天下紀；〔五〕觀公功勳，為萬世基。基成而賞不配，紀立而褒不副，〔六〕誠非所以厚國家，順天心也。","sentenceOrder":172},
  {"id":"s_work_han_thu_116_173","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「鮮音先踐反。」","sentenceOrder":173},
  {"id":"s_work_han_thu_116_174","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「論語稱孔子謂曾子曰『參乎，吾道一以貫之』，謂忠恕。」","sentenceOrder":174},
  {"id":"s_work_han_thu_116_175","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「尚書禹貢云『禹錫玄圭，告厥成功』，言賞治水功成也。禮記明堂位曰：『成王幼弱，周公踐天子之位以治天下。七年，乃致政於成王。成王以周公為有勳勞於天下，封周公於曲阜，地方七百里，革車千乘，命魯公世世祀周公以天子禮樂。是以魯君孟春乘大路，旂十有二旒，日月之章，祀帝于郊，配以后稷，天子之禮也。』」","sentenceOrder":175},
  {"id":"s_work_han_thu_116_176","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「言天降賢材以助王者，王者當申達其用，而不敢自專。」","sentenceOrder":176},
  {"id":"s_work_han_thu_116_177","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「揆，度也。紀，理也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_116_178","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「配，對也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_116_179","chapterId":"ch_work_han_thu_116","textTraditional":"高皇帝褒賞元功，相國蕭何邑戶既倍，又蒙殊禮，奏事不名，入殿不趨，封其親屬十有餘人。樂善無厭，班賞亡遴，〔一〕苟有一策，即必爵之，是故公孫戎位在充郎，選繇旄頭，壹明樊噲，封二千戶。〔二〕孝文皇帝褒賞絳侯，益封萬戶，賜黃金五千斤。孝武皇帝卹錄軍功，裂三萬戶以封衛青，青子三人，或在繈褓，皆為通侯。孝宣皇帝顯著霍光，增戶命疇，封者三人，延及兄孫。夫絳侯即因漢藩之固，杖朱虛之鯁，依諸將之遞，據相扶之勢，其事雖醜，要不能遂。〔三〕霍光即席常任之重，乘大勝之威，未嘗遭時不行，陷假離朝，〔四〕朝之執事，亡非同類，割斷歷久，統政曠世，雖曰有功，所因亦易，然猶有計策不審過徵之累。〔五〕及至青、戎，摽末之功，〔六〕一言之勞，然猶皆蒙丘山之賞。課功絳、霍，造之與因也；比於青、戎，地之與天也。而公又有宰治之效，乃當上與伯禹、周公等盛齊隆，兼其褒賞，豈特與若云者同日而論哉？〔七〕然曾不得蒙青等之厚，臣誠惑之！","sentenceOrder":179},
  {"id":"s_work_han_thu_116_180","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「遴與〈恡，去“忄”〉同。」","sentenceOrder":180},
  {"id":"s_work_han_thu_116_181","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　孟康曰：「公孫戎奴也，高帝時為旄頭郎。」晉灼曰：「楚漢春秋上東圍項羽，聞樊噲反，旄頭公孫戎明之，卒不反，封戎二千戶。」師古曰：「此公孫戎耳，非戎奴也。戎奴自武帝時人，孟說誤矣。繇讀與由同。」","sentenceOrder":181},
  {"id":"s_work_han_thu_116_182","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　李奇曰：「言勃之功不遂，而霍光據席常任也。」晉灼曰：「醜，眾也。言勃欲誅諸呂，其事雖眾，要不能以呂后在時而遂意也。」師古曰：「二說皆非也。遞，繞也，謂相圍繞也。言絳侯之時，漢家外有藩屏盤石之固，內有朱虛骨鯁之強，諸將同心圍繞扶翼，呂氏之黨雖欲作亂，心懷醜惡，事必不成。言勃之功不足多也。遞音帶。」","sentenceOrder":182},
  {"id":"s_work_han_thu_116_183","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　服虔曰：「言光未嘗陷假不遇，而離去朝也。莽嘗退就國，是陷假也。」師古曰：「假，升也。陷假者，被陷害而去所升之位也。」","sentenceOrder":183},
  {"id":"s_work_han_thu_116_184","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「光誤徵昌邑王，不得其人也。累音力瑞反。」","sentenceOrder":184},
  {"id":"s_work_han_thu_116_185","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　服虔曰：「摽音刀末之摽。謂衛青、公孫戎也。」師古曰：「摽音匹遙反。」","sentenceOrder":185},
  {"id":"s_work_han_thu_116_186","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　師古曰：「若云，謂若向者所云絳、霍、青、戎也。」","sentenceOrder":186},
  {"id":"s_work_han_thu_116_187","chapterId":"ch_work_han_thu_116","textTraditional":"臣聞功亡原者賞不限，德亡首者褒不檢。〔一〕是故成王之（與）〔於〕周公也，度百里之限，〔二〕越九錫之檢，開七百里之宇，〔三〕兼商、奄之民，〔四〕賜以附庸殷民六族，〔五〕大路大旂，〔六〕封父之繁弱，夏后之璜，〔七〕祝宗卜史，〔八〕備物典策，〔九〕官司彝器，〔一０〕白牡之牲，〔一一〕郊望之禮。〔一二〕王曰：「叔父，建爾元子。」〔一三〕子父俱延拜而受之。〔一四〕可謂不檢亡原者矣。非特止此，六子皆封。〔一五〕詩曰：「亡言不讎，亡德不報。」〔一六〕報當如之，不如非報也。〔一七〕近觀行事，高祖之約非劉氏不王，然而番君得王長沙，下詔稱忠，定著於令，〔一八〕明有大信不拘於制也。春秋晉悼公用魏絳之策，諸夏服從。鄭伯獻樂，悼公於是以半賜之。絳深辭讓，晉侯曰：「微子，寡人不能濟河。夫賞，國之典，不可廢也。子其受之。」魏絳於是有金石之樂，春秋善之，〔一九〕取其臣竭忠以辭功，君知臣以遂賞也。今陛下既知公有周公功德，不行成王之褒賞，遂聽公之固辭，不顧春秋之明義，則民臣何稱，萬世何述？誠非所以為國也。臣愚以為宜恢公國，令如周公，〔二０〕建立公子，令如伯禽。所賜之品，亦皆如之。諸子之封，皆如六子。即群下較然輸忠，黎庶昭然感德。〔二一〕臣誠輸忠，民誠感德，則於王事何有？〔二二〕唯陛下深惟祖宗之重，敬畏上天之戒，儀形虞、周之盛，〔二三〕敕盡伯禽之賜，無遴周公之報，〔二四〕（今）〔令〕天法有設，後世有祖，〔二五〕天下幸甚！","sentenceOrder":187},
  {"id":"s_work_han_thu_116_188","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「無原，謂不可測其本原也。無首，謂無出其上者也。檢，局也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_116_189","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「度亦踰越也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_116_190","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「解並在前也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_116_191","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「商、奄，二國名。」","sentenceOrder":191},
  {"id":"s_work_han_thu_116_192","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「謂條氏、徐氏、蕭氏、索氏、長勺氏、尾勺氏也。」","sentenceOrder":192},
  {"id":"s_work_han_thu_116_193","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「解已在前也。」","sentenceOrder":193},
  {"id":"s_work_han_thu_116_194","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　師古曰：「封父，古諸侯也。繁弱，大弓名也。半璧曰璜。父讀曰甫。」","sentenceOrder":194},
  {"id":"s_work_han_thu_116_195","chapterId":"ch_work_han_thu_116","textTraditional":"〔八〕　師古曰：「太祝、太宗、太卜、太史，凡四官。」","sentenceOrder":195},
  {"id":"s_work_han_thu_116_196","chapterId":"ch_work_han_thu_116","textTraditional":"〔九〕　師古曰：「既有備物，而加之策書也。一曰，典策，春秋之制也。」","sentenceOrder":196},
  {"id":"s_work_han_thu_116_197","chapterId":"ch_work_han_thu_116","textTraditional":"〔一０〕師古曰：「官司，百官也。彝器，常用之器也。一曰，彝，祭宗廟酒器也。周禮有六彝。彝，法也，言器有所法象之貌耳。」","sentenceOrder":197},
  {"id":"s_work_han_thu_116_198","chapterId":"ch_work_han_thu_116","textTraditional":"〔一一〕師古曰：「明堂位曰『季夏六月，以禘禮祀周公於太廟，牲用白牡』。」","sentenceOrder":198},
  {"id":"s_work_han_thu_116_199","chapterId":"ch_work_han_thu_116","textTraditional":"〔一二〕師古曰：「郊即（上祀）〔祀上〕帝於郊也。望謂望山川而祭之也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_116_200","chapterId":"ch_work_han_thu_116","textTraditional":"〔一三〕師古曰：「魯頌閟宮之詩曰：『王曰叔父，建爾元子，俾侯于魯。』謂命周公以封伯禽為魯公也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_116_201","chapterId":"ch_work_han_thu_116","textTraditional":"〔一四〕師古曰：「謂周公拜前，魯公拜後。」","sentenceOrder":201},
  {"id":"s_work_han_thu_116_202","chapterId":"ch_work_han_thu_116","textTraditional":"〔一五〕師古曰：「周公六子，伯禽之弟也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_116_203","chapterId":"ch_work_han_thu_116","textTraditional":"〔一六〕師古曰：「大雅抑之詩也。讎，用也。有善言則用之，有德者必報之。一曰，讎，對也。賞當其言也。」","sentenceOrder":203},
  {"id":"s_work_han_thu_116_204","chapterId":"ch_work_han_thu_116","textTraditional":"〔一七〕服虔曰：「報賞當如其德，不如德者，非報也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_116_205","chapterId":"ch_work_han_thu_116","textTraditional":"〔一八〕師古曰：「謂吳芮也。解在芮傳。番音蒲河反。」","sentenceOrder":205},
  {"id":"s_work_han_thu_116_206","chapterId":"ch_work_han_thu_116","textTraditional":"〔一九〕師古曰：「事見左傳襄十一年。微，無也。」","sentenceOrder":206},
  {"id":"s_work_han_thu_116_207","chapterId":"ch_work_han_thu_116","textTraditional":"〔二０〕師古曰：「恢，大也。」","sentenceOrder":207},
  {"id":"s_work_han_thu_116_208","chapterId":"ch_work_han_thu_116","textTraditional":"〔二一〕師古曰：「較，明貌也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_116_209","chapterId":"ch_work_han_thu_116","textTraditional":"〔二二〕師古曰：「言臻其極無闕遺。」","sentenceOrder":209},
  {"id":"s_work_han_thu_116_210","chapterId":"ch_work_han_thu_116","textTraditional":"〔二三〕師古曰：「儀形謂則而象之。」","sentenceOrder":210},
  {"id":"s_work_han_thu_116_211","chapterId":"ch_work_han_thu_116","textTraditional":"〔二四〕師古曰：「敕，備也。遴與〈恡，去“忄”〉同。」","sentenceOrder":211},
  {"id":"s_work_han_thu_116_212","chapterId":"ch_work_han_thu_116","textTraditional":"〔二五〕師古曰：「祖，始也。以此為法之始。」","sentenceOrder":212},
  {"id":"s_work_han_thu_116_213","chapterId":"ch_work_han_thu_116","textTraditional":"太后以視群公，〔一〕群公方議其事，會呂寬事起。","sentenceOrder":213},
  {"id":"s_work_han_thu_116_214","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「視讀曰示。」","sentenceOrder":214},
  {"id":"s_work_han_thu_116_215","chapterId":"ch_work_han_thu_116","textTraditional":"初，莽欲擅權，白太后：「前哀帝立，背恩義，自貴外家丁、傅，撓亂國家，幾危社稷。〔一〕今帝以幼年復奉大宗，為成帝後，宜明一統之義，以戒前事，為後代法。」於是遣甄豐奉璽綬，即拜帝母衛姬為中山孝王后，賜帝舅衛寶、寶弟玄爵關內侯，皆留中山，不得至京師。莽子宇，非莽隔絕衛氏，恐帝長大後見怨。宇即私遣人與寶等通書，教令帝母上書求入。語在衛后傳。莽不聽。宇與師吳章及婦兄呂寬議其故，章以為莽不可諫，而好鬼神，可為變怪以驚懼之，章因推類說令歸政於衛氏。宇即使寬夜持血灑莽第，門吏發覺之，莽執宇送獄，飲藥死。宇妻焉懷子，〔二〕繫獄，須產子已，殺之。〔三〕莽奏言：「宇為呂寬等所詿誤，流言惑眾，（惡）與管蔡同罪，臣不敢隱，其誅。」甄邯等白太后下詔曰：「夫唐堯有丹朱，周文王有管蔡，此皆上聖亡奈下愚子何，以其性不可移也。公居周公之位，輔成王之主，而行管蔡之誅，不以親親害尊尊，朕甚嘉之。昔周公誅四國之後，大化乃成，至於刑錯。〔四〕公其專意翼國，期於致平。」〔五〕莽因是誅滅衛氏，窮治呂寬之獄，連引郡國豪桀素非議己者，內及敬武公主、〔六〕梁王立、紅陽侯立、平阿侯仁，使者迫守，皆自殺。死者以百數，海內震焉。大司馬護軍褒奏言：「安漢公遭子宇陷於管蔡之辜，子愛至深，為帝室故不敢顧私。惟宇遭罪，喟然憤發作書八篇，以戒子孫。宜班郡國，令學官以教授。」事下群公，請令天下吏能誦公戒者，以著官簿，比孝經。〔七〕","sentenceOrder":215},
  {"id":"s_work_han_thu_116_216","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「撓，擾也，音火高反。幾音巨依反。」","sentenceOrder":216},
  {"id":"s_work_han_thu_116_217","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「焉，其名。」","sentenceOrder":217},
  {"id":"s_work_han_thu_116_218","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「須，待也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_116_219","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「四國謂三監及淮夷耳。」","sentenceOrder":219},
  {"id":"s_work_han_thu_116_220","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「翼，助也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_116_221","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「元帝女弟也。」","sentenceOrder":221},
  {"id":"s_work_han_thu_116_222","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　師古曰：「著官簿，言用之得選舉也。」","sentenceOrder":222},
  {"id":"s_work_han_thu_116_223","chapterId":"ch_work_han_thu_116","textTraditional":"四年春，郊祀高祖以配天，宗祀孝文皇帝以配上帝。四月丁未，莽女立為皇后，大赦天下。遣大司徒司直陳崇等八人分行天下，覽觀風俗。〔一〕","sentenceOrder":223},
  {"id":"s_work_han_thu_116_224","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「行音下更反。」","sentenceOrder":224},
  {"id":"s_work_han_thu_116_225","chapterId":"ch_work_han_thu_116","textTraditional":"太保舜等奏言：「春秋列功德之義，太上有立德，其次有立功，其次有立言，唯至德大賢然後能之。其在人臣，則生有大賞，終為宗臣，殷之伊尹，周之周公是也。」及民上書者八千餘人，咸曰：「伊尹為阿衡，周公為太宰，周公享七子之封，有過上公之賞。宜如陳崇言。」章下有司，有司請「還前所益二縣及黃郵聚、新野田，采伊尹、周公稱號，加公為宰衡，位上公。掾史秩六百石。三公言事，稱『敢言之』。群吏毋得與公同名。出從期門二十人，羽林三十人，前後大車十乘。賜公太夫人號曰功顯君，食邑二千戶，黃金印赤韍。〔一〕封公子男二人，安為褒新侯，臨為賞都侯。加后聘三千七百萬，合為一萬萬，以明大禮。」太后臨前殿，親封拜。安漢公拜前，二子拜後，如周公故事。莽稽首辭讓，出奏封事，願獨受母號，還安、臨印韍及號位戶邑。事下太師光等，皆曰：「賞未足以直功，〔二〕謙約退讓，公之常節，終不可聽。」莽求見固讓。太后下詔曰：「公每見，叩頭流涕固辭，今移病，固當聽其讓，令視事邪？〔三〕將當遂行其賞，遣歸就第也？」光等曰：「安、臨親受印韍，策號通天，其義昭昭。黃郵、召陵、新野之田為入尤多，〔四〕皆止於公，公欲自損以成國化，宜可聽許。治平之化當以時成，宰衡之官不可世及。納徵錢，乃以尊皇后，非為公也。功顯君戶，止身不傳。褒新、賞都兩國合三千戶，甚少矣。忠臣之節，亦宜自屈，而信主上之義。〔五〕宜遣大司徒、大司空持節承制，詔公亟入視事。〔六〕詔尚書勿復受公之讓奏。」奏可。","sentenceOrder":225},
  {"id":"s_work_han_thu_116_226","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「此韍，印之組也。」","sentenceOrder":226},
  {"id":"s_work_han_thu_116_227","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「直，當也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_116_228","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「眡，古視字。」","sentenceOrder":228},
  {"id":"s_work_han_thu_116_229","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「召讀邵。」","sentenceOrder":229},
  {"id":"s_work_han_thu_116_230","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「信讀曰申。」","sentenceOrder":230},
  {"id":"s_work_han_thu_116_231","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「亟，急也，音居力反。」","sentenceOrder":231},
  {"id":"s_work_han_thu_116_232","chapterId":"ch_work_han_thu_116","textTraditional":"莽乃起視事，上書言：「臣以元壽二年六月戊午倉卒之夜，以新都侯引入未央宮；庚申拜為大司馬，充三公位；元始元年正月丙辰拜為太傅，賜號安漢公，備四輔官；今年四月甲子復拜為宰衡，位上公。臣莽伏自惟，爵為新都侯，號為安漢公，官為宰衡、太傅、大司馬，爵貴號尊官重，一身蒙大寵者五，誠非鄙臣所能堪。據元始三年，天下歲已復，官屬宜皆置。〔一〕穀梁傳曰：『天子之宰，通于四海。』〔二〕臣愚以為，宰衡官以正百僚平海內為職，而無印信，名實不副。臣莽無兼官之材，今聖朝既過誤而用之，臣請御史刻宰衡印章曰『宰衡太傅大司馬印』，成，授臣莽，上太傅與大司馬之印。」太后詔曰：「可。韍如相國，〔三〕朕親臨授焉。」莽乃復以所益納徵錢千萬，遺與長樂長御奉共養者。〔四〕太保舜奏言：「天下聞公不受千乘之土，辭萬金之幣，散財施予千萬數，莫不鄉化。〔五〕蜀郡男子路建等輟訟慚怍而退，雖文王卻虞芮何以加！〔六〕宜報告天下。」奏可。宰衡出，從大車前後各十乘，直事尚書郎、侍御史、謁者、中黃門、期門羽林。〔七〕宰衡常持節，所止，謁者代持之。〔八〕宰衡掾史秩六百石，三公稱「敢言之」。","sentenceOrder":232},
  {"id":"s_work_han_thu_116_233","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　如淳曰：「前時飢，省官職，今豐，宜復之也。」師古曰：「復音扶目反。」","sentenceOrder":233},
  {"id":"s_work_han_thu_116_234","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「宰，治也。治眾事者，謂大臣也。」","sentenceOrder":234},
  {"id":"s_work_han_thu_116_235","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「韍亦謂組也。」","sentenceOrder":235},
  {"id":"s_work_han_thu_116_236","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「太后之長御也。共音居用反。養音弋亮反。」","sentenceOrder":236},
  {"id":"s_work_han_thu_116_237","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":237},
  {"id":"s_work_han_thu_116_238","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「卻，退也。虞、芮，二國名也，並在河之東。二國之君相與爭田，久而不平，聞文王之德，乃往斷焉。入周之境，則耕者讓畔，行者讓路，乃相謂曰：『我小人也，不可以履君子之庭。』遂相讓，以其所爭為閑田而退。」","sentenceOrder":238},
  {"id":"s_work_han_thu_116_239","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　師古曰：「自此以上，皆從宰衡出。」","sentenceOrder":239},
  {"id":"s_work_han_thu_116_240","chapterId":"ch_work_han_thu_116","textTraditional":"〔八〕　師古曰：「相代而持也。」","sentenceOrder":240},
  {"id":"s_work_han_thu_116_241","chapterId":"ch_work_han_thu_116","textTraditional":"是歲，莽奏起明堂、辟雍、靈臺，為學者築舍萬區，作市、常滿倉，制度甚盛。立樂經，益博士員，經各五人。徵天下通一藝教授十一人以上，及有逸禮、古書、毛詩、周官、爾雅、天文、圖讖、鍾律、月令、兵法、史篇文字，〔一〕通知其意者，皆詣公車。網羅天下異能之士，至者前後千數，皆令記說廷中，將令正乖繆，壹異說云。群臣奏言：「昔周公奉繼體之嗣，據上公之尊，然猶七年制度乃定。夫明堂、辟雍，墮廢千載莫能興，〔二〕今安漢公起于第家，輔翼陛下，四年于茲，功德爛然。〔三〕公以八月載生魄庚子〔四〕奉使，朝用書〔五〕臨賦營築，越若翊辛丑，〔六〕諸生、庶民大和會，十萬眾並集，平作二旬，大功畢成。〔七〕唐虞發舉，成周造業，誠亡以加。宰衡位宜在諸侯王上，賜以束帛加璧，大國乘車、安車各一，〔八〕驪馬二駟。」〔九〕詔曰：「可。其議九錫之法。」","sentenceOrder":241},
  {"id":"s_work_han_thu_116_242","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　孟康曰：「史籀所作十五篇古文書也。」師古曰：「周宣王太史史籀所作大篆書也。籀音直救反。」","sentenceOrder":242},
  {"id":"s_work_han_thu_116_243","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「墮，毀也，音火規反。」","sentenceOrder":243},
  {"id":"s_work_han_thu_116_244","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「爛然，章明之貌。」","sentenceOrder":244},
  {"id":"s_work_han_thu_116_245","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「載，始也。魄，月魄也。」","sentenceOrder":245},
  {"id":"s_work_han_thu_116_246","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　孟康曰：「賦功役之書。」","sentenceOrder":246},
  {"id":"s_work_han_thu_116_247","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「翊，明也。辛丑者，庚子之明日也。越，發語辭也。」","sentenceOrder":247},
  {"id":"s_work_han_thu_116_248","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　師古曰：「平作，謂不促遽也。平字或作丕。丕亦大也。」","sentenceOrder":248},
  {"id":"s_work_han_thu_116_249","chapterId":"ch_work_han_thu_116","textTraditional":"〔八〕　服虔曰：「大國乘車，如大國王之乘車也。」","sentenceOrder":249},
  {"id":"s_work_han_thu_116_250","chapterId":"ch_work_han_thu_116","textTraditional":"〔九〕　師古曰：「驪馬，並駕也。」","sentenceOrder":250},
  {"id":"s_work_han_thu_116_251","chapterId":"ch_work_han_thu_116","textTraditional":"冬，大風吹長安城東門屋瓦且盡。","sentenceOrder":251},
  {"id":"s_work_han_thu_116_252","chapterId":"ch_work_han_thu_116","textTraditional":"五年正月，祫祭明堂，諸侯王二十八人，列侯百二十人，宗室子九百餘人，徵助祭。禮畢，封孝宣曾孫信等三十六人為列侯，餘皆益戶賜爵，金帛之賞各有數。是時，吏民以莽不受新野田而上書者前後四十八萬七千五百七十二人，及諸侯、王公、列侯、宗室見者皆叩頭言，宜亟加賞於安漢公。〔一〕於是莽上書曰：「臣以外屬，越次備位，未能奉稱。〔二〕伏念聖德純茂，承天當古，制禮以治民，作樂以移風，四海奔走，百蠻並轃，〔三〕辭去之日，莫不隕涕。非有款誠，豈可虛致？自諸侯王已下至於吏民，咸知臣莽上與陛下有葭莩之故，〔四〕又得典職，每歸功列德者，輒以臣莽為餘言。臣見諸侯面言事於前者，未嘗不流汗而慚愧也。雖性愚鄙，至誠自知，德薄位尊，力少任大，夙夜悼栗，常恐污辱聖朝。今天下治平，風俗齊同，百蠻率服，皆陛下聖德所自躬親，太師光、太保舜等輔政佐治，群卿大夫莫不忠良，故能以五年之間至致此焉。臣莽實無奇策異謀。奉承太后聖詔，宣之于下，不能得什一；受群賢之籌畫，而上以聞，不能得什伍。〔五〕當被無益之辜，所以敢且保首領須臾者，誠上休陛下餘光，而下依群公之故也。〔六〕陛下不忍眾言，輒下其章於議者。臣莽前欲立奏止，恐其遂不肯止。今大禮已行，助祭者畢辭，不勝至願，願諸章下議者皆寢勿上，使臣莽得盡力畢制禮作樂事。事成，以傳示天下，與海內平之。即有所間非，則臣莽當被詿上誤朝之罪；〔七〕如無他譴，得全命賜骸骨歸家，避賢者路，是臣之私願也。惟陛下哀憐財幸！」〔八〕甄邯等白太后，詔曰：「可。唯公功德光於天下，是以諸侯、王公、列侯、宗室、諸生、吏民翕然同辭，連守闕庭，故下其章。諸侯、宗室辭去之日，復見前重陳，〔九〕雖曉喻罷遣，猶不肯去。告以孟夏將行厥賞，莫不驩悅，稱萬歲而退。今公每見，輒流涕叩頭言願不受賞，賞即加不敢當位。方制作未定，事須公而決，故且聽公。制作畢成，群公以聞。究于前議，〔一０〕其九錫禮儀亟奏。」〔一一〕","sentenceOrder":252},
  {"id":"s_work_han_thu_116_253","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「亟，急也。」","sentenceOrder":253},
  {"id":"s_work_han_thu_116_254","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「稱音尺證反。」","sentenceOrder":254},
  {"id":"s_work_han_thu_116_255","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「轃即臻字也。」","sentenceOrder":255},
  {"id":"s_work_han_thu_116_256","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「葭，蘆也。莩者，其筩裏白皮也。言其輕薄而附著也，故以為喻。葭音加。莩音孚。」","sentenceOrder":256},
  {"id":"s_work_han_thu_116_257","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「言皆不曉，又遺忘也。」","sentenceOrder":257},
  {"id":"s_work_han_thu_116_258","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「休，庇廕也。」","sentenceOrder":258},
  {"id":"s_work_han_thu_116_259","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　師古曰：「間音居莧反。」","sentenceOrder":259},
  {"id":"s_work_han_thu_116_260","chapterId":"ch_work_han_thu_116","textTraditional":"〔八〕　師古曰：「此財與裁同，通用。」","sentenceOrder":260},
  {"id":"s_work_han_thu_116_261","chapterId":"ch_work_han_thu_116","textTraditional":"〔九〕　師古曰：「重音直用反。」","sentenceOrder":261},
  {"id":"s_work_han_thu_116_262","chapterId":"ch_work_han_thu_116","textTraditional":"〔一０〕師古曰：「究，竟也。」","sentenceOrder":262},
  {"id":"s_work_han_thu_116_263","chapterId":"ch_work_han_thu_116","textTraditional":"〔一一〕師古曰：「亟，急也。」","sentenceOrder":263},
  {"id":"s_work_han_thu_116_264","chapterId":"ch_work_han_thu_116","textTraditional":"於是公卿大夫、博士、議郎、列侯（富平侯）張純等九百二人皆曰：「聖帝明王招賢勸能，德盛者位高，功大者賞厚。故宗臣有九命上公之尊，則有九錫登等之寵。〔一〕今九族親睦，百姓既章，萬國和協，黎民時雍，〔二〕聖瑞畢溱，太平已洽。〔三〕帝者之盛莫隆於唐虞，而陛下任之；忠臣茂功莫著於伊周，而宰衡配之。所謂異時而興，如合符者也。謹以六藝通義，經文所見，周官、禮記宜於今者，為九命之錫。〔四〕臣請命錫。」奏可。策曰：","sentenceOrder":264},
  {"id":"s_work_han_thu_116_265","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　張晏曰：「宗臣有勳勞為上公，國所宗者也。周禮『上公九命』，九命。九賜也。」師古曰：「登等，謂升於常等也。」","sentenceOrder":265},
  {"id":"s_work_han_thu_116_266","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「章，明也。時，是也。雍亦和也。自此已上皆取堯典敘堯德之言也。」","sentenceOrder":266},
  {"id":"s_work_han_thu_116_267","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「溱亦與臻同。」","sentenceOrder":267},
  {"id":"s_work_han_thu_116_268","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「禮含文嘉云：『九錫者，車馬、衣服、樂懸、朱戶、納陛、武賁、鈇鉞、弓矢、秬鬯也。』」","sentenceOrder":268},
  {"id":"s_work_han_thu_116_269","chapterId":"ch_work_han_thu_116","textTraditional":"惟元始五年五月庚寅，太皇太后臨于前殿，延登，（請）〔親〕詔之曰：公進，虛聽朕言。〔一〕前公宿衛孝成皇帝十有六年，納策盡忠，白誅故定陵侯淳于長，以彌亂發姦，〔二〕登大司馬，職在內輔。孝哀皇帝即位，驕妾窺欲，姦臣萌亂，公手劾高昌侯董宏，改正故定陶共王母之僭坐。自是之後，朝臣論議，靡不據經。以病辭位，歸于第家，為賊臣所陷。就國之後，孝哀皇帝覺寤，復還公長安，臨病加劇，猶不忘公，復特進位。是夜倉卒，國無儲主，姦臣充朝，危殆甚矣。朕惟定國之計莫宜于公，引納于朝，即日罷退高安侯董賢，轉漏之間，忠策輒建，綱紀咸張。綏和、元壽，再遭大行，萬事畢舉，禍亂不作。輔朕五年，人倫之本正，天地之位定。〔三〕欽承神祇，經緯四時，復千載之廢，矯百世之失，〔四〕天下和會，大眾方輯。〔五〕詩之靈臺，書之作雒，鎬京之制，商邑之度，於今復興。〔六〕昭章先帝之元功，明著祖宗之令德，推顯嚴父配天之義，修立郊禘宗祀之禮，以光大孝。是以四海雍雍，萬國慕義，蠻夷殊俗，不召自至，漸化端冕，奉珍助祭。〔七〕尋舊本道，遵術重古，動而有成，事得厥中。至德要道，通於神明，祖考嘉享。光耀顯章，天符仍臻，元氣大同。麟鳳龜龍，眾祥之瑞，七百有餘。遂制禮作樂，有綏靖宗廟社稷之大勳。普天之下，惟公是賴，官在宰衡，位（在）〔為〕上公。今加九命之錫，其以助祭，共文武之職，〔八〕乃遂及厥祖。〔九〕於戲，豈不休哉！〔一０〕","sentenceOrder":269},
  {"id":"s_work_han_thu_116_270","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「進前虛己而聽也。」","sentenceOrder":270},
  {"id":"s_work_han_thu_116_271","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「彌讀曰弭。弭，止也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_116_272","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　張晏曰：「定冠婚之儀，徙南北之郊也。」","sentenceOrder":272},
  {"id":"s_work_han_thu_116_273","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　張晏曰：「封先代之後，立古文經，定迭毀之禮也。」","sentenceOrder":273},
  {"id":"s_work_han_thu_116_274","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「輯與集字同。」","sentenceOrder":274},
  {"id":"s_work_han_thu_116_275","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「靈臺，所以觀氣象者也。文王受命，作邑于豐，始立此臺，兆庶自勸，就其功作，故大雅靈臺之詩曰：『經始靈臺，經之營之，庶人攻之，不日成之。』作雒，謂周公營洛邑以為王都，所謂成周也。周書洛誥曰：『召公既相宅，周公往營成周，使來告卜，作洛誥。』豐、鎬相近，故總曰鎬京。成周既成，遷殷頑民使居之，故云商邑之度也。」","sentenceOrder":275},
  {"id":"s_work_han_thu_116_276","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　師古曰：「蠻夷漸染朝化而正衣冠，奉其國珍來助祭。」","sentenceOrder":276},
  {"id":"s_work_han_thu_116_277","chapterId":"ch_work_han_thu_116","textTraditional":"〔八〕　師古曰：「共讀曰供。」","sentenceOrder":277},
  {"id":"s_work_han_thu_116_278","chapterId":"ch_work_han_thu_116","textTraditional":"〔九〕　師古曰：「榮寵之命，上延其先祖也。」","sentenceOrder":278},
  {"id":"s_work_han_thu_116_279","chapterId":"ch_work_han_thu_116","textTraditional":"〔一０〕師古曰：「於戲讀曰嗚呼。休，美也。」","sentenceOrder":279},
  {"id":"s_work_han_thu_116_280","chapterId":"ch_work_han_thu_116","textTraditional":"於是莽稽首再拜，受綠韍袞冕衣裳，〔一〕瑒琫瑒珌，〔二〕句履，〔三〕鸞路乘馬，〔四〕龍旂九旒，皮弁素積，〔五〕戎路乘馬，〔六〕彤弓矢，盧弓矢，〔七〕左建朱鉞，右建金戚，〔八〕甲冑一具，〔九〕秬鬯二卣，〔一０〕圭瓚二，〔一一〕九命青玉珪二，〔一二〕朱戶納陛。〔一三〕署宗官、祝官、卜官、史官，虎賁三百人，家令丞各一人，宗、祝、卜、史官皆置嗇夫，佐安漢公。在中府外第，虎賁為門衛，當出入者傅籍。〔一四〕自四輔、三公有事府第，皆用傳。〔一五〕以楚王邸為安漢公第，大繕治，通周衛。祖禰廟及寢皆為朱戶納陛。陳崇又奏：「安漢公祠祖禰，出城門，城門校尉宜將騎士從。入有門衛，出有騎士，所以重國也。」奏可。","sentenceOrder":280},
  {"id":"s_work_han_thu_116_281","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「此韍謂蔽膝也，或謂韍韠。韍音弗。韠音畢。」","sentenceOrder":281},
  {"id":"s_work_han_thu_116_282","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　孟康曰：「瑒，玉名也。佩刀之飾，上曰琫，下曰珌。詩云『韠琫有珌』是也。」師古曰：「瑒音蕩。琫音布孔反。珌音必。」","sentenceOrder":282},
  {"id":"s_work_han_thu_116_283","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　孟康曰：「今齊祀履舄頭飾也。出履（一二）〔三〕寸。」師古曰：「其形歧頭。句音巨俱反。」","sentenceOrder":283},
  {"id":"s_work_han_thu_116_284","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「鸞路，路車之施鸞者也，解在禮樂志。四馬曰乘，音食證反。其下亦同。」","sentenceOrder":284},
  {"id":"s_work_han_thu_116_285","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「素積，素裳也。」","sentenceOrder":285},
  {"id":"s_work_han_thu_116_286","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「戎路，戎車也。」","sentenceOrder":286},
  {"id":"s_work_han_thu_116_287","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　師古曰：「彤，赤色。盧，黑色。」","sentenceOrder":287},
  {"id":"s_work_han_thu_116_288","chapterId":"ch_work_han_thu_116","textTraditional":"〔八〕　師古曰：「鉞戚皆斧屬。」","sentenceOrder":288},
  {"id":"s_work_han_thu_116_289","chapterId":"ch_work_han_thu_116","textTraditional":"〔九〕　師古曰：「冑，兠鍪。」","sentenceOrder":289},
  {"id":"s_work_han_thu_116_290","chapterId":"ch_work_han_thu_116","textTraditional":"〔一０〕師古曰：「秬鬯，香酒也。卣，中樽也，音攸，又音羊九反。」","sentenceOrder":290},
  {"id":"s_work_han_thu_116_291","chapterId":"ch_work_han_thu_116","textTraditional":"〔一一〕師古曰：「以圭為勺末。」","sentenceOrder":291},
  {"id":"s_work_han_thu_116_292","chapterId":"ch_work_han_thu_116","textTraditional":"〔一二〕師古曰：「青者，春色，東方生而長育萬物也。」","sentenceOrder":292},
  {"id":"s_work_han_thu_116_293","chapterId":"ch_work_han_thu_116","textTraditional":"〔一三〕孟康曰：「納，內也。謂鑿殿基際為陛，不使露也。」師古曰：「孟說是也。尊者不欲露而升陛，故內之於霤下也。諸家之釋，文句雖煩，義皆不了，故無取云。」","sentenceOrder":293},
  {"id":"s_work_han_thu_116_294","chapterId":"ch_work_han_thu_116","textTraditional":"〔一四〕師古曰：「傅猶著也，音附。」","sentenceOrder":294},
  {"id":"s_work_han_thu_116_295","chapterId":"ch_work_han_thu_116","textTraditional":"〔一五〕孟康曰：「傳，符也。」師古曰：「音張戀反。」","sentenceOrder":295},
  {"id":"s_work_han_thu_116_296","chapterId":"ch_work_han_thu_116","textTraditional":"其秋，莽以皇后有子孫瑞，通子午道。〔一〕子午道從杜陵直絕南山，徑漢中。〔二〕","sentenceOrder":296},
  {"id":"s_work_han_thu_116_297","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　張晏曰：「時年十四，始有婦人之道也。子，水；午，火也。水以天一為牡，火以地二為牝，故火為水妃，今通子午以協之。」","sentenceOrder":297},
  {"id":"s_work_han_thu_116_298","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「子，北方也。午，南方也。言通南北道相當，故謂之子午耳。今京城直南山有谷通梁、漢道者，名子午谷。又宜州西界，慶州東界，有山名子午嶺，計南北直相當。此則北山者是子，南山者是午，共為子午道。」","sentenceOrder":298},
  {"id":"s_work_han_thu_116_299","chapterId":"ch_work_han_thu_116","textTraditional":"風俗使者八人還，言天下風俗齊同，詐為郡國造歌謠，頌功德，凡三萬言。莽奏定著令。又奏為市無二賈，〔一〕官無獄訟，邑無盜賊，野無飢民，道不拾遺，男女異路之制，犯者象刑。〔二〕劉歆、陳崇等十二人皆以治明堂，宣教化，封為列侯。","sentenceOrder":299},
  {"id":"s_work_han_thu_116_300","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「言純質也。賈音價。」","sentenceOrder":300},
  {"id":"s_work_han_thu_116_301","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「象刑，解在武紀及刑法志。」","sentenceOrder":301},
  {"id":"s_work_han_thu_116_302","chapterId":"ch_work_han_thu_116","textTraditional":"莽既致太平，北化匈奴，東致海外，南懷黃支，唯西方未有加。乃遣中郎將平憲等多持金幣誘塞外羌，使獻地，願內屬。憲等奏言：「羌豪良願等種，人口可萬二千人，願為內臣，獻鮮水海、允谷鹽池，平地美草皆予漢民，自居險阻處為藩蔽。問良願降意，對曰：『太皇太后聖明，安漢公至仁，天下太平，五穀成孰，或禾長丈餘，或一粟三米，或不種自生，或蠒不蠶自成，甘露從天下，醴泉自地出，鳳皇來儀，神爵降集。從四歲以來，羌人無所疾苦，故思樂內屬。』宜以時處業，置屬國領護。」事下莽，莽復奏曰：「太后秉統數年，恩澤洋溢，和氣四塞，絕域殊俗，靡不慕義。越裳氏重譯獻白雉，黃支自三萬里貢生犀，東夷王度大海奉國珍，匈奴單于順制作，去二名，今西域良願等復舉地為臣妾，昔唐堯橫被四表，亦亡以加之。今謹案已有東海、南海、北海郡，未有西海郡，請受良願等所獻地為西海郡。臣又聞聖王序天文，定地理，因山川民俗以制州界。漢家地廣二帝三王，〔一〕凡十（三）〔二〕州，州名及界多不應經。堯典十有二州界，後定為九州。漢家廓地遼遠，州牧行部，遠者三萬餘里，不可為九。謹以經義正十二州名分界，以應正始。」奏可。又增法五十條，犯者徙之西海。徙者以千萬數，民始怨矣。","sentenceOrder":302},
  {"id":"s_work_han_thu_116_303","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　服虔曰：「唐虞及周要服之內方七千里，夏殷方三千里，漢地南北萬三千里也。」","sentenceOrder":303},
  {"id":"s_work_han_thu_116_304","chapterId":"ch_work_han_thu_116","textTraditional":"泉陵侯劉慶上書〔一〕言：「周成王幼少，稱孺子，周公居攝。今帝富於春秋，宜令安漢公行天子事，如周公。」群臣皆曰：「宜如慶言。」","sentenceOrder":304},
  {"id":"s_work_han_thu_116_305","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「王子侯年表『眾陵節侯賢，長沙定王子，本始四年戴侯真定嗣，二十二年薨，黃龍元年頃侯慶嗣。』此則是也。此傳及翟義傳並云泉陵，地理志泉陵屬零陵郡，而表作眾陵，表為誤也。」","sentenceOrder":305},
  {"id":"s_work_han_thu_116_306","chapterId":"ch_work_han_thu_116","textTraditional":"冬，熒惑入月中。","sentenceOrder":306},
  {"id":"s_work_han_thu_116_307","chapterId":"ch_work_han_thu_116","textTraditional":"平帝疾，莽作策，請命於泰畤，戴璧秉圭，願以身代。藏策金縢，置于前殿，敕諸公勿敢言。〔一〕十二月平帝崩，大赦天下。莽徵明禮者宗伯鳳等與定天下吏六百石以上皆服喪三年。奏尊孝成廟曰統宗，孝平廟曰元宗。時元帝世絕，而宣帝曾孫有見王五人，〔二〕列侯廣戚侯顯等四十八人，莽惡其長大，曰：「兄弟不得相為後。」乃選玄孫中最幼廣戚侯子嬰，年二歲，託以為卜相最吉。","sentenceOrder":307},
  {"id":"s_work_han_thu_116_308","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「詐依周公為武王請命，作金縢也。」","sentenceOrder":308},
  {"id":"s_work_han_thu_116_309","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「王之見在者。」","sentenceOrder":309},
  {"id":"s_work_han_thu_116_310","chapterId":"ch_work_han_thu_116","textTraditional":"是月，前煇光謝囂奏武功長孟通浚井得白石，〔一〕上圓下方，有丹書著石，〔二〕文曰「告安漢公莽為皇帝」。符命之起，自此始矣。莽使群公以白太后，太后曰：「此誣罔天下，不可施行！」太保舜謂太后：「事已如此，無可奈何，沮之力不能止。〔三〕又莽非敢有它，但欲稱攝以重其權，填服天下耳。」〔四〕太后聽許，舜等即共令太后下詔曰：「蓋聞天生眾民，不能相治，為之立君以統理之。君年幼稚，必有寄託而居攝焉，然後能奉天施而成地化，群生茂育。書不云乎？『天工，人其代之。』〔五〕朕以孝平皇帝幼年，且統國政，幾加元服，委政而屬之。〔六〕今短命而崩，嗚呼哀哉！已使有司徵孝宣皇帝玄孫二十三人，差度宜者，以嗣孝平皇帝之後。〔七〕玄孫年在繈褓，不得至德君子，孰能安之？安漢公莽輔政三世，比遭際會，安光漢室，〔八〕遂同殊風，至于制作，與周公異世同符。今前煇光囂、武功長通上言丹石之符，朕深思厥意，云『為皇帝』者，乃攝行皇帝之事也。夫有法成易，非聖人者亡法。其令安漢公居攝踐祚，如周公故事，以武功縣為安漢公采地，〔九〕名曰漢光邑。具禮儀奏。」","sentenceOrder":310},
  {"id":"s_work_han_thu_116_311","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「浚，抒治之也。囂音許驕反。浚音峻。抒音直呂反。」","sentenceOrder":311},
  {"id":"s_work_han_thu_116_312","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「著音直略反。」","sentenceOrder":312},
  {"id":"s_work_han_thu_116_313","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「沮，壞也，音才汝反。」","sentenceOrder":313},
  {"id":"s_work_han_thu_116_314","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「填音竹刃反。」","sentenceOrder":314},
  {"id":"s_work_han_thu_116_315","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「虞書咎繇謨之辭也。言人代天理治工事也。」","sentenceOrder":315},
  {"id":"s_work_han_thu_116_316","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「屬，付也。幾音曰冀。屬音之欲反。」","sentenceOrder":316},
  {"id":"s_work_han_thu_116_317","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　師古曰：「差度謂擇也。度音大各反。」","sentenceOrder":317},
  {"id":"s_work_han_thu_116_318","chapterId":"ch_work_han_thu_116","textTraditional":"〔八〕　師古曰：「比，頻也。」","sentenceOrder":318},
  {"id":"s_work_han_thu_116_319","chapterId":"ch_work_han_thu_116","textTraditional":"〔九〕　師古曰：「采，官也。以官受地，故謂之采。」","sentenceOrder":319},
  {"id":"s_work_han_thu_116_320","chapterId":"ch_work_han_thu_116","textTraditional":"於是群臣奏言：「太后聖德昭然，深見天意，詔令安漢公居攝。臣聞周成王幼少，周道未成，成王不能共事天地，修文武之烈。〔一〕周公權而居攝，則周道成，王室安；不居攝，則恐周隊失天命〔二〕。書曰：『我嗣事子孫，大不克共上下，遏失前人光，在家不知命不易。天應棐諶，乃亡隊命。』〔三〕說曰：〔四〕周公服天子之冕，南面而朝群臣，發號施令，常稱王命。召公賢人，不知聖人之意，故不說也。〔五〕禮明堂記曰：『周公朝諸侯於明堂，天子負斧依南面而立。』〔六〕謂『周公踐天子位，六年朝諸侯，制禮作樂，而天下大服』也。召公不說。時武王崩，縗麤未除。〔七〕由是言之，周公始攝則居天子之位，非乃六年而踐阼也。書逸嘉禾篇曰：『周公奉鬯立于阼階，延登，贊曰：「假王蒞政，勤和天下。」』此周公攝政，贊者所稱。〔八〕成王加元服，周公則致政。書曰『朕復子明辟』，〔九〕周公常稱王命，專行不報，故言我復子明君也。臣請安漢公居攝踐祚，服天子韍冕，〔一０〕背斧依于戶牖之間，南面朝群臣，聽政事。車服出入警蹕，民臣稱臣妾，皆如天子之制。郊祀天地，宗祀明堂，共祀宗廟，享祭群神，贊曰『假皇帝』，〔一一〕民臣謂之『攝皇帝』，自稱曰『予』。平決朝事，常以皇帝之詔稱『制』，以奉順皇天之心，輔翼漢室，保安孝平皇帝之幼嗣，遂寄託之義，隆治平之化。〔一二〕其朝見太皇太后、帝皇后，皆復臣節。自施政教於其宮家國采，如諸侯禮〔儀〕故事。臣昧死請。」太后詔曰：「可。」明年，改元曰居攝。","sentenceOrder":320},
  {"id":"s_work_han_thu_116_321","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「共讀曰恭。烈，業也。」","sentenceOrder":321},
  {"id":"s_work_han_thu_116_322","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「隊音直類反。」","sentenceOrder":322},
  {"id":"s_work_han_thu_116_323","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「周書君奭之篇也。邵公為保，周公為師，相成王為左右。邵公不悅，周公作君奭以告之。奭，召公名也。尊而呼之，故曰君也。言我恐後嗣子孫大不能恭承天地，絕失先王光大之道，不知受命之難。天所應輔唯在有誠，所以亡失其命也。共音恭。棐音匪。」","sentenceOrder":323},
  {"id":"s_work_han_thu_116_324","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「謂說經義也。」","sentenceOrder":324},
  {"id":"s_work_han_thu_116_325","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「召讀曰邵。說讀曰悅。次下並同。」","sentenceOrder":325},
  {"id":"s_work_han_thu_116_326","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「依讀曰扆。此下亦同。」","sentenceOrder":326},
  {"id":"s_work_han_thu_116_327","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　師古曰：「縗音千回反。」","sentenceOrder":327},
  {"id":"s_work_han_thu_116_328","chapterId":"ch_work_han_thu_116","textTraditional":"〔八〕　師古曰：「贊謂祭祝之辭也。」","sentenceOrder":328},
  {"id":"s_work_han_thu_116_329","chapterId":"ch_work_han_thu_116","textTraditional":"〔九〕　師古曰：「周書洛誥載周公告成王之辭，言我復還明君之政於子也。復音扶目反。」","sentenceOrder":329},
  {"id":"s_work_han_thu_116_330","chapterId":"ch_work_han_thu_116","textTraditional":"〔一０〕師古曰：「此韍亦謂裳韍也。」","sentenceOrder":330},
  {"id":"s_work_han_thu_116_331","chapterId":"ch_work_han_thu_116","textTraditional":"〔一一〕師古曰：「贊謂祭祝之辭也。共音恭。」","sentenceOrder":331},
  {"id":"s_work_han_thu_116_332","chapterId":"ch_work_han_thu_116","textTraditional":"〔一二〕師古曰：「遂，成也。」","sentenceOrder":332},
  {"id":"s_work_han_thu_116_333","chapterId":"ch_work_han_thu_116","textTraditional":"居攝元年正月，莽祀上帝於南郊，迎春於東郊，行大射禮於明堂，養三老五更，成禮而去。〔一〕置柱下五史，秩如御史，聽政事，侍旁記疏言行。","sentenceOrder":333},
  {"id":"s_work_han_thu_116_334","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「更音工衡反。」","sentenceOrder":334},
  {"id":"s_work_han_thu_116_335","chapterId":"ch_work_han_thu_116","textTraditional":"三月己丑，立宣帝玄孫嬰為皇太子，號曰孺子。以王舜為太傅左輔，甄豐為太阿右拂，〔一〕甄邯為太保後承。又置四少，秩皆二千石。","sentenceOrder":335},
  {"id":"s_work_han_thu_116_336","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「拂讀曰弼。」","sentenceOrder":336},
  {"id":"s_work_han_thu_116_337","chapterId":"ch_work_han_thu_116","textTraditional":"四月，安眾侯劉崇與相張紹謀曰：〔一〕「安漢公莽專制朝政，必危劉氏。天下非之者，乃莫敢先舉，此宗室恥也。吾帥宗族為先，海內必和。」紹等從者百餘人，遂進攻宛，不得入而敗。紹者，張竦之從兄也。竦與崇族父劉嘉詣闕自歸，莽赦弗罪。竦因為嘉作奏曰：","sentenceOrder":337},
  {"id":"s_work_han_thu_116_338","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「安眾康侯月，長沙定王子，崇即月之玄孫子也，見王子侯表。」","sentenceOrder":338},
  {"id":"s_work_han_thu_116_339","chapterId":"ch_work_han_thu_116","textTraditional":"建平、元壽之間，大統幾絕，宗室幾棄。〔一〕賴蒙陛下聖德，扶服振救，〔二〕遮扞匡衛，國命復延，宗室明目。臨朝統政，發號施令，動以宗室為始，登用九族為先。並錄支親，建立王侯，南面之孤，計以百數。收復絕屬，存亡續廢，〔三〕得比肩首，復為人者，嬪然成行，〔四〕所以藩漢國，輔漢宗也。建辟雍，立明堂，班天法，流聖化，朝群后，昭文德，宗室諸侯，咸益土地。天下喁喁，引領而歎，〔五〕頌聲洋洋，滿耳而入。〔六〕國家所以服此美，膺此名，饗此福，受此榮者，豈非太皇太后日昃之思，陛下夕惕之念哉！何謂？〔七〕亂則統其理，危則致其安，禍則引其福，絕則繼其統，幼則代其任，晨夜屑屑，寒暑勤勤，〔八〕無時休息，孳孳不已者，〔九〕凡以為天下，厚劉氏也。〔一０〕臣無愚智，民無男女，皆諭至意。〔一一〕","sentenceOrder":339},
  {"id":"s_work_han_thu_116_340","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「幾亦音巨依反。」","sentenceOrder":340},
  {"id":"s_work_han_thu_116_341","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「陛下謂莽也。服音蒲北反。」","sentenceOrder":341},
  {"id":"s_work_han_thu_116_342","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「復音扶目反。」","sentenceOrder":342},
  {"id":"s_work_han_thu_116_343","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「嬪然，多貌也。行，列也。嬪音匹人反。行音下郎反。」","sentenceOrder":343},
  {"id":"s_work_han_thu_116_344","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「喁喁，眾口向上也，音顒。」","sentenceOrder":344},
  {"id":"s_work_han_thu_116_345","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「論語載孔子曰：『師摯之始，關雎之亂，洋洋乎盈耳哉！』故竦引之也。洋音羊，又音翔。」","sentenceOrder":345},
  {"id":"s_work_han_thu_116_346","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　師古曰：「先為設問，復陳其事也。」","sentenceOrder":346},
  {"id":"s_work_han_thu_116_347","chapterId":"ch_work_han_thu_116","textTraditional":"〔八〕　師古曰：「屑屑猶切切，動作之意也。」","sentenceOrder":347},
  {"id":"s_work_han_thu_116_348","chapterId":"ch_work_han_thu_116","textTraditional":"〔九〕　師古曰：「孳孳，不怠之意也，音與孜同。」","sentenceOrder":348},
  {"id":"s_work_han_thu_116_349","chapterId":"ch_work_han_thu_116","textTraditional":"〔一０〕師古曰：「為音于偽反。」","sentenceOrder":349},
  {"id":"s_work_han_thu_116_350","chapterId":"ch_work_han_thu_116","textTraditional":"〔一一〕師古曰：「諭，曉也。」","sentenceOrder":350},
  {"id":"s_work_han_thu_116_351","chapterId":"ch_work_han_thu_116","textTraditional":"而安眾侯崇乃獨懷悖惑之心，操畔逆之慮，〔一〕興兵動眾，欲危宗廟，惡不忍聞，罪不容誅，誠臣子之仇，宗室之讎，國家之賊，天下之害也。是故親屬震落而告其罪，民人潰畔而棄其兵，進不跬步，退伏其殃。〔二〕百歲之母，孩提之子，〔三〕同時斷斬，懸頭竿杪，〔四〕珠珥在耳，首飾猶存，為計若此，豈不誖哉！〔五〕","sentenceOrder":351},
  {"id":"s_work_han_thu_116_352","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「悖，乖也。」","sentenceOrder":352},
  {"id":"s_work_han_thu_116_353","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「半步曰跬，謂一舉足也，音（宗）〔空〕橤反。」","sentenceOrder":353},
  {"id":"s_work_han_thu_116_354","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「嬰兒始孩，人所提挈，故曰孩提也。孩者，小兒笑也。」","sentenceOrder":354},
  {"id":"s_work_han_thu_116_355","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「杪，末也，音莫小反。」","sentenceOrder":355},
  {"id":"s_work_han_thu_116_356","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「誖，惑也，音布內反。」","sentenceOrder":356},
  {"id":"s_work_han_thu_116_357","chapterId":"ch_work_han_thu_116","textTraditional":"臣聞古者畔逆之國，既以誅討，（而）〔則〕豬其宮室以為汙池，納垢濁焉，〔一〕名曰凶虛，〔二〕雖生菜茹，而人不食〔三〕。四牆其社，覆上棧下，示不得通。〔四〕辨社諸侯，〔五〕出門見之，著以為戒。〔六〕方今天下聞崇之反也，咸欲騫衣手劍而叱之。其先至者，則拂其頸，〔七〕衝其匈，刃其軀，切其肌；後至者，欲撥其門，仆其牆，〔八〕夷其屋，焚其器，〔九〕應聲滌地，則時成創。〔一０〕而宗室尤甚，言必切齒焉。何則？以其背畔恩義，而不知重德之所在也。宗室所居或遠，嘉幸得先聞，不勝憤憤之願，願為宗室倡始，〔一一〕父子兄弟負籠荷鍤，馳之南陽，〔一二〕豬崇宮室，令如古制。及崇社宜如亳社，以賜諸侯，用永監戒。願下四輔公卿大夫議，以明好惡，視四方。〔一三〕","sentenceOrder":357},
  {"id":"s_work_han_thu_116_358","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　李奇曰：「掘其宮以為池，用貯水也。」師古曰：「豬謂畜水汙下也。汙音烏。」","sentenceOrder":358},
  {"id":"s_work_han_thu_116_359","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「虛讀曰墟。墟，故居也，言凶人所居也。」","sentenceOrder":359},
  {"id":"s_work_han_thu_116_360","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「所食之菜曰茹，音人庶反。」","sentenceOrder":360},
  {"id":"s_work_han_thu_116_361","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「棧謂以簀蔽之也。下則棧之，上則覆之，所以隔塞不通陰陽之氣。」","sentenceOrder":361},
  {"id":"s_work_han_thu_116_362","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　孟康曰：「辨，布也。布崇社國，國各作一，見以為戒也。」師古曰：「辨讀曰班。」","sentenceOrder":362},
  {"id":"s_work_han_thu_116_363","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「著，明也。」","sentenceOrder":363},
  {"id":"s_work_han_thu_116_364","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　師古曰：「拂，戾也，音佛。」","sentenceOrder":364},
  {"id":"s_work_han_thu_116_365","chapterId":"ch_work_han_thu_116","textTraditional":"〔八〕　師古曰：「仆，倒也。」","sentenceOrder":365},
  {"id":"s_work_han_thu_116_366","chapterId":"ch_work_han_thu_116","textTraditional":"〔九〕　師古曰：「夷，平也。」","sentenceOrder":366},
  {"id":"s_work_han_thu_116_367","chapterId":"ch_work_han_thu_116","textTraditional":"〔一０〕師古曰：「滌地猶言塗地。則時，即時也。創，傷也，音初良反。」","sentenceOrder":367},
  {"id":"s_work_han_thu_116_368","chapterId":"ch_work_han_thu_116","textTraditional":"〔一一〕師古曰：「倡音（先）〔昌〕向反。」","sentenceOrder":368},
  {"id":"s_work_han_thu_116_369","chapterId":"ch_work_han_thu_116","textTraditional":"〔一二〕師古曰：「籠，所以盛土也。鍤，鍫也。」","sentenceOrder":369},
  {"id":"s_work_han_thu_116_370","chapterId":"ch_work_han_thu_116","textTraditional":"〔一三〕師古曰：「視讀曰示。」","sentenceOrder":370},
  {"id":"s_work_han_thu_116_371","chapterId":"ch_work_han_thu_116","textTraditional":"於是莽大說。〔一〕公卿曰：「皆宜如嘉言。」莽白太后下詔曰：「惟嘉父子兄弟，雖與崇有屬，不敢阿私，或見萌牙，相率告之，及其禍成，同共讎之，應合古制，忠孝著焉。其以杜衍戶千封嘉為（師）〔帥〕禮侯，嘉子七人皆賜爵關內侯。」後又封竦為淑德侯。長安（謂）〔為〕之語曰：「欲求封，過張伯松；〔二〕力戰鬥，不如巧為奏。」莽又封南陽吏民有功者百餘人，汙池劉崇室宅。後謀反者，皆汙池云。","sentenceOrder":371},
  {"id":"s_work_han_thu_116_372","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「說讀曰悅。」","sentenceOrder":372},
  {"id":"s_work_han_thu_116_373","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「竦之字。」","sentenceOrder":373},
  {"id":"s_work_han_thu_116_374","chapterId":"ch_work_han_thu_116","textTraditional":"群臣復白：「劉崇等謀逆者，以莽權輕也。宜尊重以填海內。」〔一〕五月甲辰，太后詔莽朝見太后稱「假皇帝」。","sentenceOrder":374},
  {"id":"s_work_han_thu_116_375","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「填音竹刃反。」","sentenceOrder":375},
  {"id":"s_work_han_thu_116_376","chapterId":"ch_work_han_thu_116","textTraditional":"冬十月丙辰朔，日有食之。","sentenceOrder":376},
  {"id":"s_work_han_thu_116_377","chapterId":"ch_work_han_thu_116","textTraditional":"十二月，群臣奏請：「益安漢公宮及家吏，置率更令，廟、廄、廚長丞，中庶子，虎賁以下百餘人，又置衛士三百人。安漢公廬為攝省，府為攝殿，第為攝宮。」奏可。","sentenceOrder":377},
  {"id":"s_work_han_thu_116_378","chapterId":"ch_work_han_thu_116","textTraditional":"莽白太后下詔曰：「故太師光雖前薨，功效已列。太保舜、大司空豐、輕車將軍邯、步兵將軍建皆為誘進單于籌策，又典靈臺、明堂、辟雍、四郊，定制度，開子午道，與宰衡同心說德，〔一〕合意并力，功德茂著。封舜子匡為同心侯，林為說德侯，光孫壽為合意侯，豐孫匡為并力侯。益邯、建各三千戶。","sentenceOrder":378},
  {"id":"s_work_han_thu_116_379","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「說音悅。次下亦同。」","sentenceOrder":379},
  {"id":"s_work_han_thu_116_380","chapterId":"ch_work_han_thu_116","textTraditional":"是歲，西羌龐恬、傅幡等〔一〕怨莽奪其地作西海郡，反攻西海太守程永，永奔走。莽誅永，遣護羌校尉竇況擊之。","sentenceOrder":380},
  {"id":"s_work_han_thu_116_381","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「幡音敷元反，其字從巾。」","sentenceOrder":381},
  {"id":"s_work_han_thu_116_382","chapterId":"ch_work_han_thu_116","textTraditional":"二年春，竇況等擊破西羌。","sentenceOrder":382},
  {"id":"s_work_han_thu_116_383","chapterId":"ch_work_han_thu_116","textTraditional":"五月，更造貨：錯刀，一直五千；契刀，一直五百；大錢，一直五十，與五銖錢並行。民多盜鑄者。禁列侯以下不得挾黃金，輸御府受直，然卒不與直。","sentenceOrder":383},
  {"id":"s_work_han_thu_116_384","chapterId":"ch_work_han_thu_116","textTraditional":"九月，東郡太守翟義都試，勒車騎，因發奔命，立嚴鄉侯劉信為天子，〔一〕移檄郡國，言莽「毒殺平帝，攝天子位，欲絕漢室，今共行天罰誅莽。」〔二〕郡國疑惑，眾十餘萬。莽惶懼不能食，晝夜抱孺子告禱郊廟，放大誥作策，〔三〕遣諫大夫桓譚等班於天下，諭以攝位當反政孺子之意。〔四〕遣王邑、孫建等八將軍擊義，分屯諸關，守阨塞。槐里男子趙明、霍鴻等起兵，以和翟義，〔五〕相與謀曰：「諸將精兵悉東，京師空，可攻長安。」眾稍多，至且十萬人，莽恐，遣將軍王奇、王級將兵拒之。以太保甄邯為大將軍，受鉞高廟，領天下兵，左杖節，右把鉞，屯城外。王舜、甄豐晝夜循行殿中。〔六〕","sentenceOrder":384},
  {"id":"s_work_han_thu_116_385","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「東平煬王之子。」","sentenceOrder":385},
  {"id":"s_work_han_thu_116_386","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「共讀作（供）〔恭〕。」","sentenceOrder":386},
  {"id":"s_work_han_thu_116_387","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「放，依也。大誥，周書篇名，周公所作也。放音甫往反。」","sentenceOrder":387},
  {"id":"s_work_han_thu_116_388","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「諭，曉告（也）〔之〕。」","sentenceOrder":388},
  {"id":"s_work_han_thu_116_389","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「和音胡臥反。」","sentenceOrder":389},
  {"id":"s_work_han_thu_116_390","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「行音下更反。」","sentenceOrder":390},
  {"id":"s_work_han_thu_116_391","chapterId":"ch_work_han_thu_116","textTraditional":"十二月，王邑等破翟義於圉。司威陳崇使監軍〔一〕上書言：「陛下奉天洪範，心合寶龜，〔二〕膺受元命，豫知成敗，（感）〔咸〕應兆占，是謂配天。配天之主，慮則移氣，言則動物，施則成化。臣崇伏讀詔書下日，竊計其時，聖思始發，而反虜仍破；〔三〕詔文始書，反虜大敗；制書始下，反虜畢斬，眾將未及齊其鋒芒。臣崇未及盡其愚慮，而事已決矣。」莽大說。〔四〕","sentenceOrder":391},
  {"id":"s_work_han_thu_116_392","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「為使而監軍於外。」","sentenceOrder":392},
  {"id":"s_work_han_thu_116_393","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「心與龜合也。」","sentenceOrder":393},
  {"id":"s_work_han_thu_116_394","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「思，慮也。」","sentenceOrder":394},
  {"id":"s_work_han_thu_116_395","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「說讀曰悅。」","sentenceOrder":395},
  {"id":"s_work_han_thu_116_396","chapterId":"ch_work_han_thu_116","textTraditional":"三年春，地震。大赦天下。","sentenceOrder":396},
  {"id":"s_work_han_thu_116_397","chapterId":"ch_work_han_thu_116","textTraditional":"王邑等還京師，西與王級等合擊明、鴻，皆破滅，語在翟義傳。莽大置酒未央宮白虎殿，勞賜將帥。詔陳崇治校軍功，第其高下。莽乃上奏曰：「明聖之世，國多賢人，故唐虞之時，可比屋而封，至功成事就，則加賞焉。至於夏后塗山之會，執玉帛者萬國，諸侯執玉，附庸執帛。周武王孟津之上，尚有八百諸侯。周公居攝，郊祀后稷以配天，宗祀文王於明堂以配上帝，是以四海之內各以其職來祭，蓋諸侯千八百矣。禮記王制千七百餘國，是以孔子著孝經曰：『不敢遺小國之臣，而況於公侯伯子男乎？故得萬國之歡心以事其先王。』此天子之孝也。秦為亡道，殘滅諸侯以為郡縣，欲擅天下之利，故二世而亡。高皇帝受命除殘，考功施賞，建國數百，後稍衰微，其餘僅存。太皇太后躬統大綱，廣封功德以勸善，興滅繼絕以永世，是以大化流通，旦暮且成。遭羌寇害西海郡，反虜流言東郡，逆賊惑眾西土，忠臣孝子莫不奮怒，所征殄滅，盡備厥辜，天子咸寧。今制禮作樂，實考周爵五等，地四等，有明文；〔一〕殷爵三等，有其說，無其文。〔二〕孔子曰：『周監於二代，郁郁乎文哉！吾從周。』〔三〕臣請諸將帥當受爵邑者爵五等，地四等。」奏可。於是封者高為侯伯，次為子男，當賜爵關內侯者更名曰附城，凡數百人。擊西海者以「羌」為號，槐里以「武」為號，翟義以「虜」為號。","sentenceOrder":397},
  {"id":"s_work_han_thu_116_398","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　蘇林曰：「爵五等：公、侯、伯、子、男也。地四等：公一等，侯伯二等，子男三等，附庸四等。」","sentenceOrder":398},
  {"id":"s_work_han_thu_116_399","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「公一等，侯二等，伯、子、男三等。」","sentenceOrder":399},
  {"id":"s_work_han_thu_116_400","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「論語載孔子之言也。監，視也。二代，夏、殷也。郁郁，文章貌。」","sentenceOrder":400},
  {"id":"s_work_han_thu_116_401","chapterId":"ch_work_han_thu_116","textTraditional":"群臣復奏言：「太后修功錄德，遠者千載，近者當世，或以文封，或以武爵，深淺大小。靡不畢舉。今攝皇帝背依踐祚，宜異於宰國之時，制作雖未畢已，〔一〕宜進二子爵皆為公。春秋『善善及子孫』，『賢者之後，宜有土地』。成王廣封周公庶子六（子）〔人〕，皆有茅土。及漢家名相大將蕭、霍之屬，咸及支庶。兄子光，可先封為列侯；諸孫，制度畢已，大司徒、大司空上名，如前詔書。」太后詔曰：「進攝皇帝子褒新侯安為新舉公，賞都侯臨為褒新公，封光為衍功侯。」是時，莽還歸新都國，群臣復白以封莽孫宗為新都侯。莽既滅翟義，自謂威德日盛，獲天人助，遂謀即真之事矣。","sentenceOrder":401},
  {"id":"s_work_han_thu_116_402","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「已，止也。」","sentenceOrder":402},
  {"id":"s_work_han_thu_116_403","chapterId":"ch_work_han_thu_116","textTraditional":"九月，莽母功顯君死，意不在哀，令太后詔議其服。少阿、羲和劉歆與博士諸儒七十八人皆曰：「居攝之義，所以統立天功，興崇帝道，成就法度，安輯海內也。〔一〕昔殷成湯既沒，而太子蚤夭，其子太甲幼少不明，伊尹放諸桐宮而居攝，以興殷道。周武王既沒，周道未成，成王幼少，周公屏成王而居攝，以成周道。〔二〕是以殷有翼翼之化，〔三〕周有刑錯之功。〔四〕今太皇太后比遭家之不造，〔五〕委任安漢公宰尹群僚，衡平天下。〔六〕遭孺子幼少，未能共上下，〔七〕皇天降瑞，出丹石之符，是以太皇太后則天明命，詔安漢公居攝踐祚，將以成聖漢之業，與唐虞三代比隆也。攝皇帝遂開祕府，會群儒，制禮作樂，卒定庶官，茂成天功。〔八〕聖心周悉，卓爾獨見，發得周禮，以明因監，〔九〕則天稽古，而損益焉，猶仲尼之聞韶，〔一０〕日月之不可階，〔一一〕非聖哲之至，孰能若茲！綱紀咸張，成在一匱，〔一二〕此其所以保佑聖漢，安靖元元之效也。今功顯君薨，禮『庶子為後，為其母緦。』傳曰『與尊者為體，不敢服其私親也。』攝皇帝以聖德承皇天之命，受太后之詔居攝踐祚，奉漢大宗之後，上有天地社稷之重，下有元元萬機之憂，不得顧其私親。故太皇太后建厥元孫，俾侯新都，〔一三〕為哀侯後。明攝皇帝與尊者為體，承宗廟之祭，奉共養太皇太后，不得服其私親也。周禮曰『王為諸侯緦縗』，『弁而加環絰』，〔一四〕同姓則麻，異姓則葛。攝皇帝當為功顯君緦縗，弁而加麻環絰，如天子弔諸侯服，以應聖制。」莽遂行焉，凡壹弔再會，而令新都侯宗為主，服喪三年云。","sentenceOrder":403},
  {"id":"s_work_han_thu_116_404","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「輯字與集同。」","sentenceOrder":404},
  {"id":"s_work_han_thu_116_405","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「屏猶擁也。」","sentenceOrder":405},
  {"id":"s_work_han_thu_116_406","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「商頌殷武之詩曰『商邑翼翼，四方之極』，言商邑禮俗翼翼然可則傚，乃四方之中正也。」","sentenceOrder":406},
  {"id":"s_work_han_thu_116_407","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「謂成康之世囹圄空虛。」","sentenceOrder":407},
  {"id":"s_work_han_thu_116_408","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「比，頻也。周頌閔予小子之篇曰『遭家不造』。造，成也。故議者引之。」","sentenceOrder":408},
  {"id":"s_work_han_thu_116_409","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「宰，治也。尹，正也。衡，平也，言如稱之衡。」","sentenceOrder":409},
  {"id":"s_work_han_thu_116_410","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　師古曰：「共讀曰恭。上下謂天地。」","sentenceOrder":410},
  {"id":"s_work_han_thu_116_411","chapterId":"ch_work_han_thu_116","textTraditional":"〔八〕　師古曰：「茂，美也。」","sentenceOrder":411},
  {"id":"s_work_han_thu_116_412","chapterId":"ch_work_han_thu_116","textTraditional":"〔九〕　李奇曰：「殷因於夏禮，周監於二代。」","sentenceOrder":412},
  {"id":"s_work_han_thu_116_413","chapterId":"ch_work_han_thu_116","textTraditional":"〔一０〕師古曰：「孔子至齊郭門之外，遇一嬰兒，挈一壺，相與俱行，其視精，其心正，其行端。孔子謂御曰：『趣驅之，趣驅之，韶樂方作。』孔子至彼而及韶，聞之，三月不知肉味。言天縱多能而識微也，故取喻耳。」","sentenceOrder":413},
  {"id":"s_work_han_thu_116_414","chapterId":"ch_work_han_thu_116","textTraditional":"〔一一〕師古曰：「論語載子貢敘孔子德云：『他人賢者，丘陵也，猶可踰也。仲尼，日月也，無得而踰焉。』又曰：『夫子之不可及，猶天之不可階而升也。』」","sentenceOrder":414},
  {"id":"s_work_han_thu_116_415","chapterId":"ch_work_han_thu_116","textTraditional":"〔一二〕師古曰：「論語云孔子曰：『譬如為山，未成一匱，止吾止也。譬如平地，雖覆一匱，進吾往也。』匱者，織草為器，所以盛土也。言人修（德）行道〔德〕，有若為山，雖于平地，始覆一匱之土而作不止，可以得成，故吾欲往觀之。今此議者謂莽修行政化，致於太平，本由一匱也。」","sentenceOrder":415},
  {"id":"s_work_han_thu_116_416","chapterId":"ch_work_han_thu_116","textTraditional":"〔一三〕師古曰：「建，立也。元，長也。謂立莽孫宗為新都侯也。俾，使也。」","sentenceOrder":416},
  {"id":"s_work_han_thu_116_417","chapterId":"ch_work_han_thu_116","textTraditional":"〔一四〕師古曰：「於弁上加環絰也。謂之環者，言其輕細如環之形。」","sentenceOrder":417},
  {"id":"s_work_han_thu_116_418","chapterId":"ch_work_han_thu_116","textTraditional":"司威陳崇奏，衍功侯光私報執金吾竇況，令殺人，況為收繫，致其法。莽大怒，切責光。光母曰：「女自視孰與長孫、中孫？」〔一〕遂母子自殺，及況皆死。初，莽以事母、養嫂、撫兄子為名，及後悖虐，復以示公義焉。〔二〕令光子嘉嗣爵為侯。","sentenceOrder":418},
  {"id":"s_work_han_thu_116_419","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「長孫、中孫，莽子宇及獲字也。皆為莽所殺，故云然。中讀曰仲。」","sentenceOrder":419},
  {"id":"s_work_han_thu_116_420","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　服虔曰：「不舍光罪為公義。」","sentenceOrder":420},
  {"id":"s_work_han_thu_116_421","chapterId":"ch_work_han_thu_116","textTraditional":"莽下書曰：「遏密之義，訖于季冬，〔一〕正月郊祀，八音當奏。王公卿士，樂凡幾等？五聲八音，條各云何？其與所部儒生各盡精思，悉陳其義。」","sentenceOrder":421},
  {"id":"s_work_han_thu_116_422","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　張晏曰：「平帝以元始五年十二月崩，至此再期年也。」師古曰：「虞書：『放勳乃徂，百姓如喪考妣，三載，四海遏密八音。』遏，止也。密，靜也。謂不作樂也。故莽引之。」","sentenceOrder":422},
  {"id":"s_work_han_thu_116_423","chapterId":"ch_work_han_thu_116","textTraditional":"是歲廣饒侯劉京、車騎將軍千人扈雲、大保屬臧鴻奏符命。〔一〕京言齊郡新井，雲言巴郡石牛，鴻言扶風雍石，莽皆迎受。十一月甲子，莽上奏太后曰：「陛下至聖，遭家不造，遇漢十二世三七之阨，承天威命，詔臣莽居攝，受孺子之託，任天下之寄。臣莽兢兢業業，懼於不稱。〔二〕宗室廣饒侯劉京上書言：『七月中，齊郡臨淄縣昌興亭長辛當一暮數夢，曰：「吾，天公使也。天公使我告亭長曰：『攝皇帝當為真。』即不信我，此亭中當有新井。」亭長晨起視亭中，誠有新井，〔三〕入地且百尺。』十一月壬子，直建冬至，〔四〕巴郡石牛，戊午，雍石文，皆到于未央宮之前殿。臣與太保安陽侯舜等視，天風起，塵冥，風止，得銅符帛圖於石前，文曰：『天告帝符，獻者封侯。承天命，用神令。』騎都尉崔發等視說。〔五〕及前孝哀皇帝建平二年六月甲子下詔書，更為太初元將元年，案其本事，甘忠可、夏賀良讖書臧蘭臺。〔六〕臣莽以為元將元年者，大將居攝改元之文也，於今信矣。尚書康誥『王若曰：「孟侯，朕其弟，小子封。」』〔七〕此周公居攝稱王之文也。春秋隱公不言即位，攝也。此二經周公、孔子所定，蓋為後法。孔子曰：『畏天命，畏大人，畏聖人之言。』〔八〕臣莽敢不承用！臣請共事神祇宗廟，奏言太皇太后、孝平皇后，皆稱假皇帝。〔九〕其號令天下，天下奏言事，毋言『攝』。以居攝三年為初始元年，漏刻以百二十為度，用應天命。臣莽夙夜養育隆就孺子，〔一０〕令與周之成王比德，宣明太皇太后威德於萬方，期於富而教之。孺子加元服，復子明辟，如周公故事。」奏可。眾庶知其奉符命，指意群臣博議別奏，以視即真之漸矣。〔一一〕","sentenceOrder":423},
  {"id":"s_work_han_thu_116_424","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「千人，官名也，屬車騎將軍。扈其姓，雲其名。」","sentenceOrder":424},
  {"id":"s_work_han_thu_116_425","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「兢兢，慎也。業業，危也。」","sentenceOrder":425},
  {"id":"s_work_han_thu_116_426","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「誠，實也。」","sentenceOrder":426},
  {"id":"s_work_han_thu_116_427","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「壬子之日冬至，而其日當建。」","sentenceOrder":427},
  {"id":"s_work_han_thu_116_428","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「眡，古視字也。視其文而說其意也。」","sentenceOrder":428},
  {"id":"s_work_han_thu_116_429","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「蘭臺，掌圖籍之所。」","sentenceOrder":429},
  {"id":"s_work_han_thu_116_430","chapterId":"ch_work_han_thu_116","textTraditional":"〔七〕　師古曰：「孟，長也。孟侯者，言為諸侯之長也。封者，衛康叔名。」","sentenceOrder":430},
  {"id":"s_work_han_thu_116_431","chapterId":"ch_work_han_thu_116","textTraditional":"〔八〕　師古曰：「論語載孔子之言也，已解在上。」","sentenceOrder":431},
  {"id":"s_work_han_thu_116_432","chapterId":"ch_work_han_thu_116","textTraditional":"〔九〕　師古曰：「共音曰恭。」","sentenceOrder":432},
  {"id":"s_work_han_thu_116_433","chapterId":"ch_work_han_thu_116","textTraditional":"〔一０〕師古曰：「隆，長也。成就之使其長大也。」","sentenceOrder":433},
  {"id":"s_work_han_thu_116_434","chapterId":"ch_work_han_thu_116","textTraditional":"〔一一〕師古曰：「視讀曰示。」","sentenceOrder":434},
  {"id":"s_work_han_thu_116_435","chapterId":"ch_work_han_thu_116","textTraditional":"期門郎張充等六人謀共劫莽，立楚王。發覺，誅死。","sentenceOrder":435},
  {"id":"s_work_han_thu_116_436","chapterId":"ch_work_han_thu_116","textTraditional":"梓潼人哀章〔一〕學問長安，素無行，好為大言。見莽居攝，即作銅匱，為兩檢，署其一曰「天帝行璽金匱圖」，其一署曰「赤帝行璽某傳予黃帝金策書」。某者，高皇帝名也。書言王莽為真天子，皇太后如天命。圖書皆書莽大臣八人，又取令名王興、王盛，章因自竄姓名，〔二〕凡為十一人，皆署官爵，為輔佐。章聞齊井、石牛事下，即日昏時，衣黃衣，持匱至高廟，以付僕射。僕射以聞。戊辰，莽至高廟拜受金匱神嬗。〔三〕御王冠，謁太后，還坐未央宮前殿，下書曰：「予以不德，託于皇初祖考黃帝之後，皇始祖考虞帝之苗裔，而太皇太后之末屬。皇天上帝隆顯大佑，成命統序，符契圖文，金匱策書，神明詔告，屬予以天下兆民。〔四〕赤帝漢氏高皇帝之靈，承天命，傳國金策之書，予甚祗畏，敢不欽受！以戊辰直定，〔五〕御王冠，即真天子位，定有天下之號曰新。其改正朔，易服色，變犧牲，殊徽幟，異器制。〔六〕以十二月朔癸酉為建國元年正月之朔，以雞鳴為時。服色配德上黃，犧牲應正用白，使節之旄旛皆純黃，其署曰『新使五威節』，以承皇天上帝威命也。」","sentenceOrder":436},
  {"id":"s_work_han_thu_116_437","chapterId":"ch_work_han_thu_116","textTraditional":"〔一〕　師古曰：「梓潼，廣漢之縣也。潼音童。」","sentenceOrder":437},
  {"id":"s_work_han_thu_116_438","chapterId":"ch_work_han_thu_116","textTraditional":"〔二〕　師古曰：「竄謂廁著也。」","sentenceOrder":438},
  {"id":"s_work_han_thu_116_439","chapterId":"ch_work_han_thu_116","textTraditional":"〔三〕　師古曰：「嬗，古禪字。言有神命，使漢禪位於莽也。」","sentenceOrder":439},
  {"id":"s_work_han_thu_116_440","chapterId":"ch_work_han_thu_116","textTraditional":"〔四〕　師古曰：「屬，委付也，音之欲反。」","sentenceOrder":440},
  {"id":"s_work_han_thu_116_441","chapterId":"ch_work_han_thu_116","textTraditional":"〔五〕　師古曰：「於建除之次，其日當定。」","sentenceOrder":441},
  {"id":"s_work_han_thu_116_442","chapterId":"ch_work_han_thu_116","textTraditional":"〔六〕　師古曰：「徽幟，通謂旌旗之屬也。幟音式志反。」","sentenceOrder":442},
  {"id":"s_work_han_thu_116_443","chapterId":"ch_work_han_thu_116","textTraditional":"校勘記","sentenceOrder":443},
  {"id":"s_work_han_thu_116_444","chapterId":"ch_work_han_thu_116","textTraditional":"四０四０頁一四行　（為）〔嘗〕私買侍婢，　景祐、汲古、殿、局本都作「嘗」，此誤。","sentenceOrder":444},
  {"id":"s_work_han_thu_116_445","chapterId":"ch_work_han_thu_116","textTraditional":"四０四二頁一０行　上乃加恩寵，置使家，中黃門〔三〕十日一賜餐。　沈欽韓說「中黃門」當屬下讀，蘇林說非。","sentenceOrder":445},
  {"id":"s_work_han_thu_116_446","chapterId":"ch_work_han_thu_116","textTraditional":"四０四四頁　二行　瑑自雕瑑字耳，音（彖）〔篆〕也。　景祐本作「篆」。王先謙說作「篆」是。","sentenceOrder":446},
  {"id":"s_work_han_thu_116_447","chapterId":"ch_work_han_thu_116","textTraditional":"四０四七頁一二行　功（能）〔德〕為忠臣宗，　景祐、殿本都作「德」。楊樹達說作「德」是。","sentenceOrder":447},
  {"id":"s_work_han_thu_116_448","chapterId":"ch_work_han_thu_116","textTraditional":"四０四九頁　二行　倍故，數多於（人）〔故〕各一倍也。　景祐、殿本都作「故」。王先謙說作「故」是。","sentenceOrder":448},
  {"id":"s_work_han_thu_116_449","chapterId":"ch_work_han_thu_116","textTraditional":"四０四九頁　七行　自今以來，（非）〔惟〕封爵乃以聞。　汲古、殿、局本都作「惟」。王先謙說「非」字誤。","sentenceOrder":449},
  {"id":"s_work_han_thu_116_450","chapterId":"ch_work_han_thu_116","textTraditional":"四０五二頁　五行　宜承（大）〔天〕序，奉祭祀。　景祐、殿本都作「天」。王先謙說作「天」是。","sentenceOrder":450},
  {"id":"s_work_han_thu_116_451","chapterId":"ch_work_han_thu_116","textTraditional":"四０五二頁　八行　事下有司，皆（白）〔曰〕：　景祐、殿本都作「曰」。","sentenceOrder":451},
  {"id":"s_work_han_thu_116_452","chapterId":"ch_work_han_thu_116","textTraditional":"四０五三頁　四行　〔言〕皇后之位當在莽女也。　景祐、殿本都有「言」字。","sentenceOrder":452},
  {"id":"s_work_han_thu_116_453","chapterId":"ch_work_han_thu_116","textTraditional":"四０五三頁　九行　佟音（從）〔徒〕冬反。　景祐、殿本都作「徒」，此誤。","sentenceOrder":453},
  {"id":"s_work_han_thu_116_454","chapterId":"ch_work_han_thu_116","textTraditional":"四０五五頁一三行　顇與（萃）〔悴〕同，　殿本作「悴」。王先謙說作「悴」是。","sentenceOrder":454},
  {"id":"s_work_han_thu_116_455","chapterId":"ch_work_han_thu_116","textTraditional":"四０五六頁一四行　謂持兵（力）〔刃〕以刺。　景祐、汲古、殿、局本都作「刃」，此誤。","sentenceOrder":455},
  {"id":"s_work_han_thu_116_456","chapterId":"ch_work_han_thu_116","textTraditional":"四０五八頁　三行　（書）〔師古〕曰：　朱一新說「書曰」當作「師古曰」。","sentenceOrder":456},
  {"id":"s_work_han_thu_116_457","chapterId":"ch_work_han_thu_116","textTraditional":"四０五九頁一五行　四海輻（奏）〔湊〕，　景祐、殿、局本都作「湊」。王先謙說「奏」字誤。","sentenceOrder":457},
  {"id":"s_work_han_thu_116_458","chapterId":"ch_work_han_thu_116","textTraditional":"四０六二頁　九行　是故成王之（與）〔於〕周公也，　景祐、殿本都作「於」。王先謙說作「於」是。","sentenceOrder":458},
  {"id":"s_work_han_thu_116_459","chapterId":"ch_work_han_thu_116","textTraditional":"四０六三頁　六行　（今）〔令〕天法有設，　錢大昭說「今」當作「令」。按景祐、殿、局本都作「令」。","sentenceOrder":459},
  {"id":"s_work_han_thu_116_460","chapterId":"ch_work_han_thu_116","textTraditional":"四０六四頁　四行　郊即（上祀）〔祀上〕帝於郊也。　殿本作「祀上」。王先謙說殿本是。","sentenceOrder":460},
  {"id":"s_work_han_thu_116_461","chapterId":"ch_work_han_thu_116","textTraditional":"四０六五頁一０行　（惡）與管蔡同罪，　景祐本無「惡」字。","sentenceOrder":461},
  {"id":"s_work_han_thu_116_462","chapterId":"ch_work_han_thu_116","textTraditional":"四０七二頁一二行　列侯（富平侯）張純等　景祐本無「富平侯」三字。","sentenceOrder":462},
  {"id":"s_work_han_thu_116_463","chapterId":"ch_work_han_thu_116","textTraditional":"四０七三頁　五行　延登，（請）〔親〕詔之曰：　沈欽韓說「請」當為「親」。按景祐、殿本都作「親」。","sentenceOrder":463},
  {"id":"s_work_han_thu_116_464","chapterId":"ch_work_han_thu_116","textTraditional":"四０七四頁　三行　官在宰衡，位（在）〔為〕上公。　景祐、殿本都作「為」。","sentenceOrder":464},
  {"id":"s_work_han_thu_116_465","chapterId":"ch_work_han_thu_116","textTraditional":"四０七五頁一二行　出履（一二）〔三〕寸。　景祐本作「三」。","sentenceOrder":465},
  {"id":"s_work_han_thu_116_466","chapterId":"ch_work_han_thu_116","textTraditional":"四０七七頁一三行　凡十（三）〔二〕州，　景祐本作「三」，殿本作「二」。","sentenceOrder":466},
  {"id":"s_work_han_thu_116_467","chapterId":"ch_work_han_thu_116","textTraditional":"四０八一頁　三行　如諸侯禮〔儀〕故事。　王先謙說「禮」下脫「儀」字。按景祐、殿本都有。","sentenceOrder":467},
  {"id":"s_work_han_thu_116_468","chapterId":"ch_work_han_thu_116","textTraditional":"四０八四頁　八行　音（宗）〔空〕橤反。　景祐、殿本都作「空」。","sentenceOrder":468},
  {"id":"s_work_han_thu_116_469","chapterId":"ch_work_han_thu_116","textTraditional":"四０八四頁一二行　（而）〔則〕豬其宮室以為汙池，　景祐、殿本都作「則」。王先謙說作「則」是。","sentenceOrder":469},
  {"id":"s_work_han_thu_116_470","chapterId":"ch_work_han_thu_116","textTraditional":"四０八五頁一四行　倡音（先）〔昌〕向反。　殿本作「昌」。景祐本亦作「先」，疑「尺」字之誤。","sentenceOrder":470},
  {"id":"s_work_han_thu_116_471","chapterId":"ch_work_han_thu_116","textTraditional":"四０八六頁　三行　封嘉為（師）〔帥〕禮侯，　錢大昭說「師」當作「帥」。按通鑑作「率禮侯」，錢說是。","sentenceOrder":471},
  {"id":"s_work_han_thu_116_472","chapterId":"ch_work_han_thu_116","textTraditional":"四０八六頁　三行　長安（謂）〔為〕之語曰：　景祐、殿本都作「為」。","sentenceOrder":472},
  {"id":"s_work_han_thu_116_473","chapterId":"ch_work_han_thu_116","textTraditional":"四０八八頁　四行　共讀作（供）〔恭〕。　景祐、殿本都作「恭」。","sentenceOrder":473},
  {"id":"s_work_han_thu_116_474","chapterId":"ch_work_han_thu_116","textTraditional":"四０八八頁　六行　諭，曉告（也）〔之〕。　景祐、殿本都作「之」。","sentenceOrder":474},
  {"id":"s_work_han_thu_116_475","chapterId":"ch_work_han_thu_116","textTraditional":"四０八八頁一０行　（感）〔咸〕應兆占，　景祐、殿本都作「咸」。","sentenceOrder":475},
  {"id":"s_work_han_thu_116_476","chapterId":"ch_work_han_thu_116","textTraditional":"四０九０頁　七行　成王廣封周公庶子六（子）〔人〕，　景祐、殿本都作「人」。","sentenceOrder":476},
  {"id":"s_work_han_thu_116_477","chapterId":"ch_work_han_thu_116","textTraditional":"四０九二頁一三行　言人修（德）行道〔德〕，　景祐、殿本都作「修行道德」。","sentenceOrder":477},
  {"id":"s_work_han_thu_117_1","chapterId":"ch_work_han_thu_117","textTraditional":"始建國元年正月朔，莽帥公侯卿士奉皇太后璽韍，〔一〕上太皇太后，順符命，去漢號焉。","sentenceOrder":1},
  {"id":"s_work_han_thu_117_2","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「韍謂璽之組，音弗。」","sentenceOrder":2},
  {"id":"s_work_han_thu_117_3","chapterId":"ch_work_han_thu_117","textTraditional":"初，莽妻宜春侯王氏女，立為皇后。〔一〕本生四男：宇、獲、安、臨。二子前誅死，安頗荒忽，〔二〕乃以臨為皇太子，安為新嘉辟。〔三〕封宇子六人：千為功隆公，壽為功明公，吉為功成公，宗為功崇公，世為功昭公，利為功著公。大赦天下。","sentenceOrder":3},
  {"id":"s_work_han_thu_117_4","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「王訢為丞相，初封宜春侯，傳爵至孫咸。莽妻，咸之女。」","sentenceOrder":4},
  {"id":"s_work_han_thu_117_5","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「荒音呼廣反。」","sentenceOrder":5},
  {"id":"s_work_han_thu_117_6","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「辟，君也。謂之辟者，取為國君之義，音壁。」","sentenceOrder":6},
  {"id":"s_work_han_thu_117_7","chapterId":"ch_work_han_thu_117","textTraditional":"莽乃策命孺子曰：「咨爾嬰，昔皇天右乃太祖，〔一〕歷世十二，享國二百一十載，曆數在于予躬。詩不云乎？『侯服于周，天命靡常。』〔二〕封爾為定安公，永為新室賓。於戲！〔三〕敬天之休，〔四〕往踐乃位，毋廢予命。」又曰：「其以平原、安德、漯陰、鬲、重丘，凡戶萬，〔五〕地方百里，為定安公國。立漢祖宗之廟於其國，與周後並，行其正朔、服色。世世以事其祖宗，永以命德茂功，享歷代之祀焉。以孝平皇后為定安太后。」讀策畢，莽親執孺子手，流涕歔欷，〔六〕曰：「昔周公攝位，終得復子明辟，今予獨迫皇天威命，不得如意！」哀歎良久。中傅將孺子下殿，北面而稱臣。百僚陪位，莫不感動。","sentenceOrder":7},
  {"id":"s_work_han_thu_117_8","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「右讀曰佑。佑，助也。」","sentenceOrder":8},
  {"id":"s_work_han_thu_117_9","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「大雅文王之詩也。言殷之後嗣，乃為諸侯，服事周室，是天命無常也。謂微子為宋公也。」","sentenceOrder":9},
  {"id":"s_work_han_thu_117_10","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「於戲音曰嗚呼。」","sentenceOrder":10},
  {"id":"s_work_han_thu_117_11","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「休，美也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_117_12","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　師古曰：「五縣也。漯音它合反。鬲音與隔同。」","sentenceOrder":12},
  {"id":"s_work_han_thu_117_13","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　師古曰：「歔音虛。欷音許氣反。」","sentenceOrder":13},
  {"id":"s_work_han_thu_117_14","chapterId":"ch_work_han_thu_117","textTraditional":"又按金匱，輔臣皆封拜。以太傅、左輔、驃騎將軍安陽侯王舜為太師，封安新公；大司徒就德侯平晏為太傅，就新公；少阿、羲和、京兆尹紅休侯劉歆為國師，嘉新公；廣漢梓潼哀章為國將，美新公：是為四輔，位上公。太保、後承承陽侯甄邯〔一〕為大司馬，承新公；丕進侯王尋為大司徒，章新公；步兵將軍成都侯王邑為大司空，隆新公：是為三公。大阿、右拂、大司空、衛將軍廣陽侯甄豐〔二〕為更始將軍，廣新公；京兆王興為衛將軍，奉新公；輕車將軍成武侯孫建為立國將軍，成新公；京兆王盛為前將軍，崇新公：是為四將。凡十一公。王興者，故城門令史。王盛者，賣餅。莽按符命求得此姓名十餘人，兩人容貌應卜相，徑從布衣登用，以視神焉。〔三〕餘皆拜為郎。是日，封拜卿大夫、侍中、尚書官凡數百人。諸劉為郡守，皆徙為諫大夫。","sentenceOrder":14},
  {"id":"s_work_han_thu_117_15","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「承陽音烝陽。」","sentenceOrder":15},
  {"id":"s_work_han_thu_117_16","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「拂讀曰弼。」","sentenceOrder":16},
  {"id":"s_work_han_thu_117_17","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「視讀曰示。」","sentenceOrder":17},
  {"id":"s_work_han_thu_117_18","chapterId":"ch_work_han_thu_117","textTraditional":"改明光宮為定安館，定安太后居之。以故大鴻臚府為定安公第，皆置門衛使者監領。敕阿乳母不得與語，常在四壁中，〔一〕至於長大，不能名六畜。後莽以女孫宇子妻之。","sentenceOrder":18},
  {"id":"s_work_han_thu_117_19","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　孟康曰：「令定安公居四壁中，不得有所見。」","sentenceOrder":19},
  {"id":"s_work_han_thu_117_20","chapterId":"ch_work_han_thu_117","textTraditional":"莽策群司曰：「歲星司肅，東（獄）〔嶽〕太師典致時雨，〔一〕青煒登平，考景以晷。〔二〕熒惑司悊，南嶽太傅典致時奧，〔三〕赤煒頌平，考聲以律。〔四〕太白司艾，西嶽國師典致時陽，〔五〕白煒象平，考量以銓。〔六〕辰星司謀，北嶽國將典致時寒，〔七〕玄煒和平，考星以漏。〔八〕月刑元股左，司馬典致武應，考方法矩，〔九〕主司天文，欽若昊天，敬授民時，力來農事，以豐年穀。〔一０〕日德元厷右，司徒典致文瑞，考圜合規，〔一一〕主司人道，五教是輔，帥民承上，宣美風俗，五品乃訓。〔一二〕斗平元心中，司空典致物圖，考度以繩，〔一三〕主司地里，平治水土，掌名山川，眾殖鳥獸，蕃茂草木。」各策命以其職，如典誥之文。","sentenceOrder":20},
  {"id":"s_work_han_thu_117_21","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　應劭曰：「貌之不恭，是謂不肅。肅，敬也。厥罰常雨。常雨，水也。故申戒厥任，欲使雨澤以時也。」晉灼曰：「眾物生於東方，故戒太師也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_117_22","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　服虔曰：「煒音暉。」如淳曰：「青氣之光輝也。」晉灼曰：「言青陽之氣始升而上，以成萬物也。春秋分立表以正東西。東，日之始出也，故考景以晷屬焉。」","sentenceOrder":22},
  {"id":"s_work_han_thu_117_23","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　應劭曰：「視之不明，是謂不悊。悊，智也。厥罰常燠。燠，暑也。」晉灼曰：「南方，盛陽之位。太傅，師尊之稱，故戒之也。」師古曰：「奧音於六反。」","sentenceOrder":23},
  {"id":"s_work_han_thu_117_24","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　晉灼曰：「頌，寬頌也。夏，假也。物假大，乃宣平也。六月陰氣之始，故為地統。地之中數六，六為律，律有形有色，色尚黃，故考聲以律屬焉。」師古曰：「頌讀曰容。」","sentenceOrder":24},
  {"id":"s_work_han_thu_117_25","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　應劭曰：「言之不從，是謂不艾。艾，安也。厥罰常陽。陽，旱也。」師古曰：「艾讀曰乂。」","sentenceOrder":25},
  {"id":"s_work_han_thu_117_26","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　應劭曰：「量，斗斛也。銓，權衡也。」晉灼曰：「象，形也，萬物無不成形於西方，大小輕重皆可知，故稱量屬焉。」","sentenceOrder":26},
  {"id":"s_work_han_thu_117_27","chapterId":"ch_work_han_thu_117","textTraditional":"〔七〕　應劭曰：「聽之不聰，是謂不謀。謀，圖也。厥罰常寒。」晉灼曰：「北，伏也。陽氣伏於下，陰主殺，故戒國將。」","sentenceOrder":27},
  {"id":"s_work_han_thu_117_28","chapterId":"ch_work_han_thu_117","textTraditional":"〔八〕　應劭曰：「推五星行度以漏刻也。」晉灼曰：「和，合也。萬物皆合藏於北方，水又主平，故曰和平。曆度起於斗分，日月紀於攝提，攝提值斗杓所指以建時節，故考星屬焉。」","sentenceOrder":28},
  {"id":"s_work_han_thu_117_29","chapterId":"ch_work_han_thu_117","textTraditional":"〔九〕　張晏曰：「月為刑，司馬主武，又典天，故使主威刑也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_117_30","chapterId":"ch_work_han_thu_117","textTraditional":"〔一０〕師古曰：「欽，敬也。若，順也。力來，勸勉之也。來音郎代反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_117_31","chapterId":"ch_work_han_thu_117","textTraditional":"〔一一〕張晏曰：「日為陽位。」晉灼曰：「肱圜也。五教在寬，則和氣感物，四靈見象，故文瑞屬焉。」師古曰：「厷，古肱字。」","sentenceOrder":31},
  {"id":"s_work_han_thu_117_32","chapterId":"ch_work_han_thu_117","textTraditional":"〔一二〕師古曰：「五教，謂父義、母慈、兄友、弟恭、子孝也。五品即五常，謂仁、義、禮、智、信。」","sentenceOrder":32},
  {"id":"s_work_han_thu_117_33","chapterId":"ch_work_han_thu_117","textTraditional":"〔一三〕張晏曰：「斗，北斗也，主齊七政。司空主水土，土為中，故責之。」孟康曰：「易『河出圖，洛出書』，司空主水土，責以其物也。」晉灼曰：「中央為四季土。土者信，信者直，故為繩。」","sentenceOrder":33},
  {"id":"s_work_han_thu_117_34","chapterId":"ch_work_han_thu_117","textTraditional":"置大司馬司允，〔一〕大司徒司直，大司空司若，〔二〕位皆孤卿。更名大司農曰羲和，後更為納言，大理曰作士，太常曰秩宗，大鴻臚曰典樂，少府曰共工，〔三〕水衡都尉曰予虞，與三公司卿凡九卿，分屬三公。每一卿置大夫三人，一大夫置元士三人，凡二十七大夫，八十一元士，分主中都官諸職。更名光祿勳曰司中，太僕曰太御，衛尉曰太衛，執金吾曰奮武，中尉曰軍正，又置大贅官，主乘輿服御物，〔四〕後又典兵秩，位皆上卿，號曰六監。改郡太守曰大尹，都尉曰太尉，縣令長曰宰，御史曰執法，公車司馬曰王路四門，長樂宮曰常樂室，未央宮曰壽成室，前殿曰王路堂，〔五〕長安曰常安。更名秩百石曰庶士，三百石曰下士，四百石曰中士，五百石曰命士，六百石曰元士，千石曰下大夫，比二千石曰中大夫，二千石曰上大夫，中二千石曰卿。車服黻冕，各有差品。〔六〕又置司恭、司徒、司明、司聰、司中大夫及誦詩工、徹膳宰，以司過。策曰：「予聞上聖欲昭厥德，罔不慎修厥身，用綏于遠，是用建爾司于五事。毋隱尤，毋將虛，〔七〕好惡不愆，立于厥中。〔八〕於戲，勗哉！」〔九〕令王路設進善之旌，非謗之木，（欲）〔敢〕諫之鼓。〔一０〕諫大夫四人常坐王路門受言事者。","sentenceOrder":34},
  {"id":"s_work_han_thu_117_35","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「允，信也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_117_36","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「若，順也。」","sentenceOrder":36},
  {"id":"s_work_han_thu_117_37","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「共音曰龔。」","sentenceOrder":37},
  {"id":"s_work_han_thu_117_38","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「贅，聚也，言財物所聚也，音之銳反。」","sentenceOrder":38},
  {"id":"s_work_han_thu_117_39","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　服虔曰：「如言路寢也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_117_40","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　師古曰：「此黻謂衣裳之黻。」","sentenceOrder":40},
  {"id":"s_work_han_thu_117_41","chapterId":"ch_work_han_thu_117","textTraditional":"〔七〕　師古曰：「尤，過也。將，助也。虛謂虛美也。言勿隱吾過，而助為虛美。」","sentenceOrder":41},
  {"id":"s_work_han_thu_117_42","chapterId":"ch_work_han_thu_117","textTraditional":"〔八〕　師古曰：「愆，違也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_117_43","chapterId":"ch_work_han_thu_117","textTraditional":"〔九〕　師古曰：「於戲讀曰嗚呼。勗，勉也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_117_44","chapterId":"ch_work_han_thu_117","textTraditional":"〔一０〕師古曰：「非音曰誹。」","sentenceOrder":44},
  {"id":"s_work_han_thu_117_45","chapterId":"ch_work_han_thu_117","textTraditional":"封王氏齊縗之屬為侯，大功為伯，小功為子，緦麻為男，其女皆為任。〔一〕男以「睦」、女以「隆」為號焉，〔二〕皆授印韍〔三〕。令諸侯立太夫人、夫人、世子，亦受印韍。","sentenceOrder":45},
  {"id":"s_work_han_thu_117_46","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「任，充也。男服之義，男亦任也，音壬。」","sentenceOrder":46},
  {"id":"s_work_han_thu_117_47","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「睦、隆，皆其受封邑之號，取嘉名也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_117_48","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「韍亦印之組。次下並同。」","sentenceOrder":48},
  {"id":"s_work_han_thu_117_49","chapterId":"ch_work_han_thu_117","textTraditional":"又曰：「天無二日，土無二王，百王不易之道也。漢氏諸侯或稱王，至于四夷亦如之，違於古典，繆於一統。其定諸侯王之號皆稱公，及四夷僭號稱王者皆更為侯。」","sentenceOrder":49},
  {"id":"s_work_han_thu_117_50","chapterId":"ch_work_han_thu_117","textTraditional":"又曰：「帝王之道，相因而通；盛德之祚，百世享祀。予惟黃帝、帝少昊、帝顓頊、帝嚳、帝堯、帝舜、帝夏禹、皋陶、伊尹咸有聖德，假于皇天，〔一〕功烈巍巍，光施于遠。予甚嘉之，營求其後，將祚厥祀。」惟王氏，虞帝之後也，出自帝嚳；劉氏，堯之後也，出自顓頊。於是封姚恂為初睦侯，奉黃帝後；〔二〕梁護為脩遠伯，奉少昊後；〔三〕皇孫功隆公千，奉帝嚳後；劉歆為祁烈伯，奉顓頊後；國師劉歆子疊為伊休侯，奉堯後；〔四〕媯昌為始睦侯，奉虞帝後；山遵為褒謀子，奉皋陶後；伊玄為褒衡子，奉伊尹後。漢後定安公劉嬰，位為賓。周後衛公姬黨，更封為章平公，亦為賓。殷後宋公孔弘，運轉次移，更封為章昭侯，位為恪。〔五〕夏後遼西姒豐，封為章功侯，亦為恪。〔六〕四代古宗，宗祀于明堂，以配皇始祖考虞帝。周公後褒魯子姬就，宣尼公後褒成子孔鈞，已前定焉。","sentenceOrder":50},
  {"id":"s_work_han_thu_117_51","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「假，至也，升也，音工雅反。」","sentenceOrder":51},
  {"id":"s_work_han_thu_117_52","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　服虔曰：「姚，舜姓，故封為黃帝後。」","sentenceOrder":52},
  {"id":"s_work_han_thu_117_53","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　服虔曰：「以為伯益之後，故封之。」","sentenceOrder":53},
  {"id":"s_work_han_thu_117_54","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「上言紅休侯劉歆為國師嘉新公，今此云劉歆為祁烈伯，又言國師劉歆子為伊休侯，是則祁烈伯自別一劉歆，非國師也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_117_55","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　師古曰：「恪，敬也。言待之加敬，亦如賓也。周以舜後并杞、宋為三恪也。」","sentenceOrder":55},
  {"id":"s_work_han_thu_117_56","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　服虔曰：「姒，夏姓。」","sentenceOrder":56},
  {"id":"s_work_han_thu_117_57","chapterId":"ch_work_han_thu_117","textTraditional":"莽又曰：「予前在攝時，建郊宮，定祧廟，立社稷，〔一〕神祇報況，〔二〕或光自上復于下，流為烏，〔三〕或黃氣熏烝，昭燿章明，以著黃、虞之烈焉。〔四〕自黃帝至于濟南伯王，而祖世氏姓有五矣。〔五〕黃帝二十五子，分賜厥姓十有二氏。虞帝之先，受姓曰姚，其在陶唐曰媯，在周曰陳，在齊曰田，在濟南曰王。予伏念皇初祖考黃帝，皇始祖考虞帝，以宗祀于明堂，宜序於祖宗之親廟。其立祖廟五，親廟四，后夫人皆配食。郊祀黃帝以配天，黃后以配地〔六〕。以新都侯東弟為大禖，歲時以祀。〔七〕家之所尚，種祀天下。〔八〕姚、媯、陳、田、王氏凡五姓者，皆黃、虞苗裔，予之同族也。書不云乎？『惇序九族。』〔九〕其令天下上此五姓名籍于秩宗，皆以為宗室。世世復，無有所與。〔一０〕其元城王氏，勿令相嫁娶，以別族理親焉。」〔一一〕封陳崇為統睦侯，奉胡王後；〔一二〕田豐為世睦侯，奉敬王後。〔一三〕","sentenceOrder":57},
  {"id":"s_work_han_thu_117_58","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「遠祖曰祧，音吐堯反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_117_59","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「況，賜也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_117_60","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「復音扶目反。」","sentenceOrder":60},
  {"id":"s_work_han_thu_117_61","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「烈，餘業（反）〔也〕。自云承黃、虞之後。」","sentenceOrder":61},
  {"id":"s_work_han_thu_117_62","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　師古曰：「濟南伯王，莽之高祖。」","sentenceOrder":62},
  {"id":"s_work_han_thu_117_63","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　孟康曰：「黃帝之后也。」","sentenceOrder":63},
  {"id":"s_work_han_thu_117_64","chapterId":"ch_work_han_thu_117","textTraditional":"〔七〕　師古曰：「禖，祀也。立此大祠，常以歲時祀其先也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_117_65","chapterId":"ch_work_han_thu_117","textTraditional":"〔八〕　師古曰：「言國已立大禖祠先祖矣，其眾庶之家所尚者，各令傳祀勿絕，普天之下同其法。」","sentenceOrder":65},
  {"id":"s_work_han_thu_117_66","chapterId":"ch_work_han_thu_117","textTraditional":"〔九〕　師古曰：「虞書咎繇謨之辭也。惇，厚也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_117_67","chapterId":"ch_work_han_thu_117","textTraditional":"〔一０〕師古曰：「復音方目反。與讀曰預。」","sentenceOrder":67},
  {"id":"s_work_han_thu_117_68","chapterId":"ch_work_han_thu_117","textTraditional":"〔一一〕師古曰：「元城王氏不得與四姓昏娶，以其同祖也。餘它王氏，則不禁焉。」","sentenceOrder":68},
  {"id":"s_work_han_thu_117_69","chapterId":"ch_work_han_thu_117","textTraditional":"〔一二〕孟康曰：「追王陳胡公。」","sentenceOrder":69},
  {"id":"s_work_han_thu_117_70","chapterId":"ch_work_han_thu_117","textTraditional":"〔一三〕孟康曰：「追王陳敬仲。」","sentenceOrder":70},
  {"id":"s_work_han_thu_117_71","chapterId":"ch_work_han_thu_117","textTraditional":"天下牧守皆以前有翟義、趙明等領州郡，懷忠孝，封牧為男，守為附城。又封舊恩戴崇、金涉、箕閎、楊並等子皆為男。","sentenceOrder":71},
  {"id":"s_work_han_thu_117_72","chapterId":"ch_work_han_thu_117","textTraditional":"遣騎都尉囂等〔一〕分治黃帝園位於上都橋畤，〔二〕虞帝於零陵九疑，胡王於淮陽陳，敬王於齊臨淄，愍王於城陽莒，〔三〕伯王於濟南東平陵，孺王於魏郡元城，〔四〕使者四時致祠。其廟當作者，以天下初定，且祫祭於明堂太廟。","sentenceOrder":72},
  {"id":"s_work_han_thu_117_73","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「囂音許驕反。」","sentenceOrder":73},
  {"id":"s_work_han_thu_117_74","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「橋山之上，故曰橋畤也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_117_75","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　服虔曰：「齊愍王。」","sentenceOrder":75},
  {"id":"s_work_han_thu_117_76","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「莽之高祖名遂字伯紀，曾祖名賀字翁孺，故謂之伯王、孺王。」","sentenceOrder":76},
  {"id":"s_work_han_thu_117_77","chapterId":"ch_work_han_thu_117","textTraditional":"以漢高廟為文祖廟。〔一〕莽曰：「予之皇始祖考虞帝受嬗于唐，〔二〕漢氏初祖唐帝，世有傳國之象，〔三〕予復親受金策於漢高皇帝之靈。惟思褒厚前代，何有忘時？漢氏祖宗有七，〔四〕以禮立廟于定安國。其園寢廟在京師者，勿罷，祠薦如故。予以秋九月親入漢氏高、元、成、平之廟。諸劉更屬籍京兆大尹，勿解其復，各終厥身，〔五〕州牧數存問，勿令有侵冤。」","sentenceOrder":77},
  {"id":"s_work_han_thu_117_78","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「欲法舜受終於文祖。」","sentenceOrder":78},
  {"id":"s_work_han_thu_117_79","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「嬗，古禪字。」","sentenceOrder":79},
  {"id":"s_work_han_thu_117_80","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「堯傳舜，漢傳莽，自以舜後，故言有傳國之象。」","sentenceOrder":80},
  {"id":"s_work_han_thu_117_81","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　蘇林曰：「漢本祀祖宗有四，莽以元帝、成帝、平帝為宗，故有七。」","sentenceOrder":81},
  {"id":"s_work_han_thu_117_82","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　師古曰：「復音方目反。」","sentenceOrder":82},
  {"id":"s_work_han_thu_117_83","chapterId":"ch_work_han_thu_117","textTraditional":"又曰：「予前在大麓，至于攝假，〔一〕深惟漢氏三七之阨，赤德氣盡，思索廣求，〔二〕所以輔劉延期之（述）〔術〕，靡所不用。以故作金刀之利，幾以濟之。〔三〕然自孔子作春秋以為後王法，至于哀之十四而一代畢，協之於今，亦哀之十四也。〔四〕赤世計盡，終不可強濟。皇天明威，黃德當興，隆顯大命，屬予以天下。〔五〕今百姓咸言皇天革漢而立新，〔六〕廢劉而興王。夫『劉』之為字『卯、金、刀』也，正月剛卯，金刀之利，皆不得行。〔七〕博謀卿士，僉曰天人同應，昭然著明。其去剛卯莫以為佩，除刀錢勿以為利，承順天心，快百姓意。」乃更作小錢，徑六分，重一銖，文曰「小錢直一」，與前「大錢五十」者為二品，並行。欲防民盜鑄，乃禁不得挾銅炭。","sentenceOrder":83},
  {"id":"s_work_han_thu_117_84","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「大麓者，謂為大司馬、宰衡時，妄引『舜納于大麓，烈風雷雨不迷』也。攝假，謂初為攝皇帝，又為假皇帝。」","sentenceOrder":84},
  {"id":"s_work_han_thu_117_85","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「索亦求也，音山客反。」","sentenceOrder":85},
  {"id":"s_work_han_thu_117_86","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「幾讀曰冀。」","sentenceOrder":86},
  {"id":"s_work_han_thu_117_87","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　張晏曰：「漢哀帝即位六年，平帝五年，居攝三年，凡十四年。」","sentenceOrder":87},
  {"id":"s_work_han_thu_117_88","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　師古曰：「屬音之欲反。」","sentenceOrder":88},
  {"id":"s_work_han_thu_117_89","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　師古曰：「革，改也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_117_90","chapterId":"ch_work_han_thu_117","textTraditional":"〔七〕　服虔曰：「剛卯，以正月卯日作佩之，長三（尺）〔寸〕，廣一寸，四方，或用（五）〔玉〕，或用金，或用桃，著革帶佩之。今有玉在者，銘其一面曰『正月剛卯』。金刀，莽所鑄之錢也。」晉灼曰：「剛卯長一寸，廣五分，四方。當中央從穿作孔，以采絲（茸）〔葺〕其底，如冠纓頭蕤。刻其上面，作兩行書，文曰『正月剛卯既央，靈殳四方，赤青白黃，四色是當。帝令祝融，以教夔、龍，庶疫剛癉，莫我敢當。』其一銘曰『疾日嚴卯，帝令夔化，順爾固伏，化茲靈殳。既正既直，既觚既方，庶疫剛癉，莫我敢當。』」師古曰：「今往往有土中得玉剛卯者，案大小及文，服說是也。莽以劉字上有卯，下有金，旁又有刀，故禁剛卯及金刀也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_117_91","chapterId":"ch_work_han_thu_117","textTraditional":"（是歲）四月，徐鄉侯劉快結黨數千人起兵於其國。〔一〕快兄殷，故漢膠東王，時改為扶崇公。快舉兵攻即墨，殷閉城門，自繫獄。吏民距快，快敗走，至長廣死。莽曰：「昔予之祖濟南愍王困於燕寇，自齊臨淄出保于莒。宗人田單廣設奇謀，獲殺燕將，復定齊國。今即墨士大夫復同心殄滅反虜，予甚嘉其忠者，憐其無辜。其赦殷等，非快之妻子它親屬當坐者皆勿治。弔問死傷，賜亡者葬錢，人五萬。殷知大命，深疾惡快，以故輒伏厥辜。其滿殷國戶萬，地方百里。」又封符命臣十餘人。","sentenceOrder":91},
  {"id":"s_work_han_thu_117_92","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「快，膠東恭王子也。而王子侯表作炔，字從火，與此不同，疑表誤。」","sentenceOrder":92},
  {"id":"s_work_han_thu_117_93","chapterId":"ch_work_han_thu_117","textTraditional":"莽曰：「古者，設廬井八家，一夫一婦田百畝，什一而稅，則國給民富而頌聲作。〔一〕此唐虞之道，三代所遵行也。秦為無道，厚賦稅以自供奉，罷民力以極欲，〔二〕壞聖制，廢井田，是以兼并起，貪鄙生，強者規田以千數，弱者曾無立錐之居。又置奴婢之市，與牛馬同蘭，〔三〕制於民臣，顓斷其命。姦虐之人因緣為利，至略賣人妻子，逆天心，誖人倫，〔四〕繆於『天地之性人為貴』之義〔五〕。書曰『予則奴戮女』，〔六〕唯不用命者，然後被此辜矣。漢氏減輕田租，三十而稅一，常有更賦，罷癃咸出，〔七〕而豪民侵陵，分田劫假。厥名三十稅一，實什稅五也。〔八〕父子夫婦終年耕芸，〔九〕所得不足以自存。故富者犬馬餘菽粟，驕而為邪；貧者不厭糟糠，窮而為姦。〔一０〕俱陷于辜，刑用不錯。〔一一〕予前在大麓，始令天下公田口井，〔一二〕時則有嘉禾之祥，遭反虜逆賊且止。今更名天下田曰『王田』，奴婢曰『私屬』，皆不得賣買。其男口不盈八，而田過一井者，分餘田予九族鄰里鄉黨。故無田，今當受田者，如制度。敢有非井田聖制，無法惑眾者，投諸四裔，以禦魑魅〔一三〕，如皇始祖考虞帝故事。」","sentenceOrder":93},
  {"id":"s_work_han_thu_117_94","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「給，足也。」","sentenceOrder":94},
  {"id":"s_work_han_thu_117_95","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「罷讀曰疲。」","sentenceOrder":95},
  {"id":"s_work_han_thu_117_96","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「蘭謂遮蘭之，若牛馬蘭圈也。」","sentenceOrder":96},
  {"id":"s_work_han_thu_117_97","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「誖，亂也。誖音布內反。」","sentenceOrder":97},
  {"id":"s_work_han_thu_117_98","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　師古曰：「孝經稱孔子曰『天地之性人為貴』，故引之。性，生也。」","sentenceOrder":98},
  {"id":"s_work_han_thu_117_99","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　師古曰：「夏書甘誓之辭也。奴戮，戮之以為奴也。說書者以為帑，子也，戮及妻子。此說非也。泰誓云『囚奴正士』，豈及子之謂乎？女讀曰汝。」","sentenceOrder":99},
  {"id":"s_work_han_thu_117_100","chapterId":"ch_work_han_thu_117","textTraditional":"〔七〕　師古曰：「更音工衡反。罷音疲。癃音隆。」","sentenceOrder":100},
  {"id":"s_work_han_thu_117_101","chapterId":"ch_work_han_thu_117","textTraditional":"〔八〕　師古曰：「解並在食貨志。」","sentenceOrder":101},
  {"id":"s_work_han_thu_117_102","chapterId":"ch_work_han_thu_117","textTraditional":"〔九〕　師古曰：「芸字與耘同。」","sentenceOrder":102},
  {"id":"s_work_han_thu_117_103","chapterId":"ch_work_han_thu_117","textTraditional":"〔一０〕師古曰：「厭，飽也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_117_104","chapterId":"ch_work_han_thu_117","textTraditional":"〔一一〕師古曰：「錯，置也，音千故反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_117_105","chapterId":"ch_work_han_thu_117","textTraditional":"〔一二〕師古曰：「計口而為井田。」","sentenceOrder":105},
  {"id":"s_work_han_thu_117_106","chapterId":"ch_work_han_thu_117","textTraditional":"〔一三〕師古曰：「魑，山神也。魅，老物精也。魑音螭。魅音媚。」","sentenceOrder":106},
  {"id":"s_work_han_thu_117_107","chapterId":"ch_work_han_thu_117","textTraditional":"是時百姓便安漢五銖錢，以莽錢大小兩行難知，又數變改不信，皆私以五銖錢市買。訛言大錢當罷，莫肯挾。莽患之，復下書：「諸挾五銖錢，言大錢當罷者，比非井田制，投四裔。」於是農商失業，食貨俱廢，民人至涕泣於市道。及坐賣買田宅奴婢，鑄錢，自諸侯卿大夫至于庶民，抵罪者不可勝數。","sentenceOrder":107},
  {"id":"s_work_han_thu_117_108","chapterId":"ch_work_han_thu_117","textTraditional":"秋，遣五威將王奇等十二人班符命四十二篇於天下。德祥五事，符命二十五，福應十二，凡四十二篇。其德祥言文、宣之世黃龍見於成紀、新都，高祖考王伯墓門梓柱生枝葉之屬。符命言井石、金匱之屬。福應言雌雞化為雄之屬。其文爾雅依託，皆為作說，〔一〕大歸言莽當代漢有天下云。總而說之曰：「帝王受命，必有德祥之符瑞，協成五命，申以福應，〔二〕然後能立巍巍之功，傳于子孫，永享無窮之祚。故新室之興也，德祥發於漢三七九世之後。〔三〕肇命於新都，受瑞於黃支，〔四〕開王於武功，定命於子同，〔五〕成命於巴宕，〔六〕申福於十二應，天所以保祐新室者深矣，固矣！武功丹石出於漢氏平帝末年，火德銷盡，土德當代，皇天眷然，去漢與新，以丹石始命於皇帝。皇帝謙讓，以攝居之，未當天意，故其秋七月，天重以三能文馬。〔七〕皇帝復謙讓，未即位，故三以鐵契，四以石龜，五以虞符，六以文圭，七以玄印，八以茂陵石書，九以玄龍石，十以神井，十一以大神石，十二以銅符帛圖。申命之瑞，寖以顯著〔八〕，至于十二，以昭告新皇帝。皇帝深惟上天之威不可不畏，故去攝號，猶尚稱假，改元為初始，欲以承塞天命，克厭上帝之心。〔九〕然非皇天所以鄭重降符命之意。〔一０〕故是日天復決（其）以勉書。〔一一〕又侍郎王盱見人衣白布單衣，赤繢方領，〔一二〕冠小冠，立于王路殿前，謂盱曰：『今日天同色，以天下人民屬皇帝。〔一三〕』盱怪之，行十餘步，人忽不見。至丙寅暮，漢氏高廟有金匱圖策：『高帝承天命，以國傳新皇帝。』明旦，宗伯忠孝侯劉宏以聞，乃召公卿議，未決，而大神石人談曰：『趣新皇帝之高廟受命，毋留！』〔一四〕於是新皇帝立登車，之漢氏高廟受命。受命之日，丁卯也。丁，火，漢氏之德也。卯，劉姓所以為字也。明漢劉火德盡，而傳於新室也。皇帝謙謙，既備固讓，十二符應迫著，命不可辭，〔一五〕懼然祗畏，葦然閔漢氏之終不可濟，〔一六〕斖斖在左右之不得從意，〔一七〕為之三夜不御寢，三日不御食，延問公侯卿大夫，僉曰：『宜奉如上天威命。』於是乃改元定號，海內更始。新室既定，神祇懽喜，申以福應，吉瑞累仍。〔一八〕詩曰：『宜民宜人，受祿于天；保右命之，自天申之。』〔一九〕此之謂也。」五威將奉符命，齎印綬，王侯以下及吏官名更者，〔二０〕外及匈奴、西域，徼外蠻夷，皆即授新室印綬，因收故漢印綬。賜吏爵人二級，民爵人一級，女子百戶羊酒，蠻夷幣帛各有差。大赦天下。","sentenceOrder":108},
  {"id":"s_work_han_thu_117_109","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「爾雅，近正也。謂近於正經，依古義而為之說。」","sentenceOrder":109},
  {"id":"s_work_han_thu_117_110","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「五命，謂五行之次，相承以受命也。申，重也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_117_111","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　蘇林曰：「二百一十歲，九天子也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_117_112","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　孟康曰：「獻生犀。」","sentenceOrder":112},
  {"id":"s_work_han_thu_117_113","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　孟康曰：「梓潼縣也，莽改也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_117_114","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　晉灼曰：「巴郡宕渠縣也。」","sentenceOrder":114},
  {"id":"s_work_han_thu_117_115","chapterId":"ch_work_han_thu_117","textTraditional":"〔七〕　服虔曰：「三台星也。」晉灼曰：「許慎說，文馬縞身金精，周成王時犬戎獻之。」師古曰：「能音台。」","sentenceOrder":115},
  {"id":"s_work_han_thu_117_116","chapterId":"ch_work_han_thu_117","textTraditional":"〔八〕　師古曰：「寖，漸也。」","sentenceOrder":116},
  {"id":"s_work_han_thu_117_117","chapterId":"ch_work_han_thu_117","textTraditional":"〔九〕　師古曰：「塞，當也。厭，滿也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_117_118","chapterId":"ch_work_han_thu_117","textTraditional":"〔一０〕師古曰：「鄭重猶言頻煩也。重音直用反。」","sentenceOrder":118},
  {"id":"s_work_han_thu_117_119","chapterId":"ch_work_han_thu_117","textTraditional":"〔一一〕孟康曰：「哀章所作策書也。言數有瑞應，莽自謙居攝，天復決其疑，勸勉令為真也。」晉灼曰：「勉字當為龜。是日自復有龜書及天下金匱圖策事也。」師古曰：「孟說是。」","sentenceOrder":119},
  {"id":"s_work_han_thu_117_120","chapterId":"ch_work_han_thu_117","textTraditional":"〔一二〕師古曰：「繢者，會五采也。以布為單衣，以赤加繢為其方領也。盱音許于反。繢音胡內反。」","sentenceOrder":120},
  {"id":"s_work_han_thu_117_121","chapterId":"ch_work_han_thu_117","textTraditional":"〔一三〕師古曰：「同色者，言五方天神共齊其謀，同其顏色也。字或作包，包者，言天總包括天下人眾，而與莽也。其義兩通。屬，委也，音之欲反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_117_122","chapterId":"ch_work_han_thu_117","textTraditional":"〔一四〕師古曰：「趣讀曰促。」","sentenceOrder":122},
  {"id":"s_work_han_thu_117_123","chapterId":"ch_work_han_thu_117","textTraditional":"〔一五〕師古曰：「迫，促也。著，明也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_117_124","chapterId":"ch_work_han_thu_117","textTraditional":"〔一六〕師古曰：「懼音瞿。瞿然，自失之意也。葦然，變動之貌也。瞿音居具反。」","sentenceOrder":124},
  {"id":"s_work_han_thu_117_125","chapterId":"ch_work_han_thu_117","textTraditional":"〔一七〕師古曰：「斖斖，自勉之意。左右，助也。言欲助漢室而迫天命，不得從其本意也。左右音曰佐佑也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_117_126","chapterId":"ch_work_han_thu_117","textTraditional":"〔一八〕師古曰：「申，重也。仍，頻也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_117_127","chapterId":"ch_work_han_thu_117","textTraditional":"〔一九〕師古曰：「大雅假樂之詩也。言有功德宜於眾人者，則受天之福祿。天乃保安而佑助之，命以邦國也。申謂重其意也。右讀曰佑。」","sentenceOrder":127},
  {"id":"s_work_han_thu_117_128","chapterId":"ch_work_han_thu_117","textTraditional":"〔二０〕師古曰：「更，改也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_117_129","chapterId":"ch_work_han_thu_117","textTraditional":"五威將乘乾文車，〔一〕駕坤六馬，〔二〕背負鷩鳥之毛，服飾甚偉。〔三〕每一將各置左右前後中帥，凡五帥。衣冠車服駕馬，各如其方面色數。〔四〕將持節，稱太一之使；帥持幢，稱五帝之使。莽策命曰：「普天之下，迄于四表，〔五〕靡所不至。」其東出者，至玄菟、樂浪、高句驪、夫餘；〔六〕南出者，隃徼外，歷益州〔七〕，貶句町王為侯；西出者，至西域，盡改其王為侯；北出者，至匈奴庭，授單于印，改漢印文，去「璽」曰「章」。單于欲求故印，陳饒椎破之，語在匈奴傳。單于大怒，而句町、西域後卒以此皆畔。饒還，拜為大將軍，封威德子。","sentenceOrder":129},
  {"id":"s_work_han_thu_117_130","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　鄭氏曰：「畫天文象於車也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_117_131","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　鄭氏曰：「坤為牝馬。六，地數。」","sentenceOrder":131},
  {"id":"s_work_han_thu_117_132","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「鷩鳥，雉屬，即鵔鸃也。今俗呼之山雞，非也。鷩音鱉。」","sentenceOrder":132},
  {"id":"s_work_han_thu_117_133","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「色者，東方青，南方赤也。數者，若木數三，火數二之類也。」","sentenceOrder":133},
  {"id":"s_work_han_thu_117_134","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　師古曰：「迄亦至也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_117_135","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　師古曰：「夫餘，亦東北夷也。樂音洛。浪音郎。夫音扶。」","sentenceOrder":135},
  {"id":"s_work_han_thu_117_136","chapterId":"ch_work_han_thu_117","textTraditional":"〔七〕　師古曰：「隃字與踰同。」","sentenceOrder":136},
  {"id":"s_work_han_thu_117_137","chapterId":"ch_work_han_thu_117","textTraditional":"冬，雷，〔一〕桐華。","sentenceOrder":137},
  {"id":"s_work_han_thu_117_138","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「古雷字。」","sentenceOrder":138},
  {"id":"s_work_han_thu_117_139","chapterId":"ch_work_han_thu_117","textTraditional":"置五威司命，中城四關將軍。司命司上公以下，中城主十二城門。策命統睦侯陳崇曰：「咨爾崇。夫不用命者，亂之原也；大姦猾者，賊之本也；鑄偽金錢者，妨寶貨之道也；驕奢踰制者，兇害之端也；漏泄省中及尚書事者，『機事不密則害成』也；〔一〕拜爵王庭，謝恩私門者，祿去公室，政從亡矣：凡此六條，國之綱紀。是用建爾作司命，『柔亦不茹，剛亦不吐，不侮鰥寡，不畏強圉』，〔二〕帝命帥繇，統睦于朝。」〔三〕命說符侯崔發曰：「『重門擊〈木{广屰}〉，以待暴客。』〔四〕女作五威中城將軍，〔五〕中德既成，天下說符。」〔六〕命明威侯王級曰：「繞霤之固，南當荊楚。〔七〕女作五威前關將軍，振武奮衛，明威于前。」命尉睦侯王嘉曰：「羊頭之阨，北當趙燕。〔八〕女作五威後關將軍，壼口捶扼，尉睦于後。」〔九〕命（堂）〔掌〕威侯王奇曰：「肴黽之險，東當鄭衛。〔一０〕女作五威左關將軍，函谷批難，掌威于左。」〔一一〕命懷羌子王福曰：「汧隴之阻，西當戎狄。〔一二〕女作五威右關將軍，成固據守，懷羌于右。」","sentenceOrder":139},
  {"id":"s_work_han_thu_117_140","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「易上繫之辭曰『君不密則失臣，臣不密則失身，機事不密則害成』，故引之。」","sentenceOrder":140},
  {"id":"s_work_han_thu_117_141","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「引詩大雅美仲山甫之辭，其義並解於上。」","sentenceOrder":141},
  {"id":"s_work_han_thu_117_142","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「帥，循也。繇讀與由同。」","sentenceOrder":142},
  {"id":"s_work_han_thu_117_143","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「易下繫之辭也。擊〈木{广屰}〉，謂擊木以守夜也。暴客，謂姦暴之人來為寇害者也。〈木{广屰}〉音他各反。」","sentenceOrder":143},
  {"id":"s_work_han_thu_117_144","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　師古曰：「女讀曰汝。其下並同。」","sentenceOrder":144},
  {"id":"s_work_han_thu_117_145","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　師古曰：「說音悅。」","sentenceOrder":145},
  {"id":"s_work_han_thu_117_146","chapterId":"ch_work_han_thu_117","textTraditional":"〔七〕　服虔曰：「隘險之道。」師古曰：「謂之繞霤者，言四面塞阨，其道屈曲，谿谷之水，回繞而霤也。其處即今商州界七盤十二繞是也。霤音力救反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_117_147","chapterId":"ch_work_han_thu_117","textTraditional":"〔八〕　師古曰：「羊頭，山名，在上黨壺關縣。」","sentenceOrder":147},
  {"id":"s_work_han_thu_117_148","chapterId":"ch_work_han_thu_117","textTraditional":"〔九〕　師古曰：「壺口亦山名也。捶扼，謂據險阨而捶擊也。捶音之橤反。」","sentenceOrder":148},
  {"id":"s_work_han_thu_117_149","chapterId":"ch_work_han_thu_117","textTraditional":"〔一０〕師古曰：「肴，肴山也。黽，黽池也。皆在陝縣之東。黽音莫善反。」","sentenceOrder":149},
  {"id":"s_work_han_thu_117_150","chapterId":"ch_work_han_thu_117","textTraditional":"〔一一〕師古曰：「批謂糾閉之也。函谷故關，今在桃林縣界。批音步結反。」","sentenceOrder":150},
  {"id":"s_work_han_thu_117_151","chapterId":"ch_work_han_thu_117","textTraditional":"〔一二〕師古曰：「汧，扶風汧縣，有吳山、汧水之阻。隴謂隴阺也。汧隴相連。汧音苦堅反。阺音丁禮反。」","sentenceOrder":151},
  {"id":"s_work_han_thu_117_152","chapterId":"ch_work_han_thu_117","textTraditional":"又遣諫大夫五十人分鑄錢於郡國。","sentenceOrder":152},
  {"id":"s_work_han_thu_117_153","chapterId":"ch_work_han_thu_117","textTraditional":"是歲長安狂女子碧呼道中〔一〕曰：「高皇帝大怒，趣歸我國。不者，九月必殺汝！」〔二〕莽收捕殺之。治者掌寇大夫陳成自免去官。〔三〕真定劉都等謀舉兵，發覺，皆誅。真定、常山大雨雹〔四〕。","sentenceOrder":153},
  {"id":"s_work_han_thu_117_154","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「碧者，女子名也。呼，叫也，音火故反。」","sentenceOrder":154},
  {"id":"s_work_han_thu_117_155","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「趣讀曰促。」","sentenceOrder":155},
  {"id":"s_work_han_thu_117_156","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「狂妄之人，職在掌寇，故云治者。」","sentenceOrder":156},
  {"id":"s_work_han_thu_117_157","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「雨音于具反。」","sentenceOrder":157},
  {"id":"s_work_han_thu_117_158","chapterId":"ch_work_han_thu_117","textTraditional":"二年二月，赦天下。","sentenceOrder":158},
  {"id":"s_work_han_thu_117_159","chapterId":"ch_work_han_thu_117","textTraditional":"五威將帥七十二人還奏事，漢諸侯王為公者，悉上璽綬為民，無違命者。封將為子，帥為男。","sentenceOrder":159},
  {"id":"s_work_han_thu_117_160","chapterId":"ch_work_han_thu_117","textTraditional":"初設六筦之令。〔一〕命縣官酤酒，賣鹽鐵器，鑄錢，諸采取名山大澤眾物者稅之。又令市官收賤賣貴，賒貸予民，收息百月三〔二〕。犧和置酒士，郡一人，乘傳督酒利。〔三〕禁民不得挾弩鎧，徙西海。","sentenceOrder":160},
  {"id":"s_work_han_thu_117_161","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「筦亦管字也。管，主也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_117_162","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　如淳曰：「出百錢與民用，月收其息三錢也。」師古曰：「貸音吐戴反。」","sentenceOrder":162},
  {"id":"s_work_han_thu_117_163","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「督，視察之。傳音張戀反。」","sentenceOrder":163},
  {"id":"s_work_han_thu_117_164","chapterId":"ch_work_han_thu_117","textTraditional":"匈奴單于求故璽，莽不與，遂寇邊郡，殺略吏民。","sentenceOrder":164},
  {"id":"s_work_han_thu_117_165","chapterId":"ch_work_han_thu_117","textTraditional":"十一月，立國將軍建奏：「西域將欽上言，〔一〕九月辛巳，戊己校尉史陳良、終帶共賊殺校尉刁護，〔二〕劫略吏士，自稱廢漢大將軍，亡入匈奴。又今月癸酉，不知何一男子遮臣建車前，自稱『漢氏劉子輿，成帝下妻子也。〔三〕劉氏當復，〔四〕趣空宮。』〔五〕收繫男子，即常安姓武字仲。皆逆天違命，大逆無道。請論仲及陳良等親屬當坐著。奏可。漢氏高皇帝比著戒云，罷吏卒，為賓食〔六〕，誠欲承天心，全子孫也。其宗廟不當在常安城中，及諸劉為諸侯者當與漢俱廢。陛下至仁，久未定。前故安眾侯劉崇、徐鄉侯劉快、〔七〕陵鄉侯劉曾、〔八〕扶恩侯劉貴等〔九〕更聚眾謀反。〔一０〕今狂狡之虜或妄自稱亡漢將軍，或稱成帝子子輿，至犯夷滅，連未止者，此聖恩不蚤絕其萌牙故也。臣愚以為漢高皇帝為新室賓，享食明堂。成帝，異姓之兄弟，平帝，婿也，皆不宜復入其廟。元帝與皇太后為體，〔一一〕聖恩所隆，禮亦宜之。臣請漢氏諸廟在京師者皆罷。諸劉為諸侯者，以戶多少就五等之差；其為吏者皆罷，待除於家。〔一二〕上當天心，稱高皇帝神靈，〔一三〕塞狂狡之萌。」莽曰：「可。嘉新公國師以符命為予四輔，明德侯劉龔、率禮侯劉嘉等凡三十二人皆知天命，或獻天符，或貢昌言，〔一四〕或捕告反虜，厥功茂焉。諸劉與三十二人同宗共祖者勿罷，賜姓曰王。」唯國師以女配莽子，故不賜姓。改定安太后號曰黃皇室主，絕之於漢也。","sentenceOrder":165},
  {"id":"s_work_han_thu_117_166","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「但欽也。」","sentenceOrder":166},
  {"id":"s_work_han_thu_117_167","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「刁音貂。」","sentenceOrder":167},
  {"id":"s_work_han_thu_117_168","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「下妻猶言小妻。」","sentenceOrder":168},
  {"id":"s_work_han_thu_117_169","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「復音扶福反。」","sentenceOrder":169},
  {"id":"s_work_han_thu_117_170","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　師古曰：「趣讀曰促。」","sentenceOrder":170},
  {"id":"s_work_han_thu_117_171","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　師古曰：「比，頻也。言高帝頻戒云，勿使吏卒守漢廟，欲為寄食之賓於王氏廟中。」","sentenceOrder":171},
  {"id":"s_work_han_thu_117_172","chapterId":"ch_work_han_thu_117","textTraditional":"〔七〕　師古曰：「並解於上。」","sentenceOrder":172},
  {"id":"s_work_han_thu_117_173","chapterId":"ch_work_han_thu_117","textTraditional":"〔八〕　師古曰：「楚思王子。」","sentenceOrder":173},
  {"id":"s_work_han_thu_117_174","chapterId":"ch_work_han_thu_117","textTraditional":"〔九〕　師古曰：「不知誰子孫。」","sentenceOrder":174},
  {"id":"s_work_han_thu_117_175","chapterId":"ch_work_han_thu_117","textTraditional":"〔一０〕師古曰：「更音工衡反。」","sentenceOrder":175},
  {"id":"s_work_han_thu_117_176","chapterId":"ch_work_han_thu_117","textTraditional":"〔一一〕師古曰：「夫婦一體也。」","sentenceOrder":176},
  {"id":"s_work_han_thu_117_177","chapterId":"ch_work_han_thu_117","textTraditional":"〔一二〕師古曰：「罷黜其職，各使退歸，而言在家待遷除。」","sentenceOrder":177},
  {"id":"s_work_han_thu_117_178","chapterId":"ch_work_han_thu_117","textTraditional":"〔一三〕師古曰：「稱音尺孕反。」","sentenceOrder":178},
  {"id":"s_work_han_thu_117_179","chapterId":"ch_work_han_thu_117","textTraditional":"〔一四〕師古曰：「昌，當也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_117_180","chapterId":"ch_work_han_thu_117","textTraditional":"冬十二月，雷。","sentenceOrder":180},
  {"id":"s_work_han_thu_117_181","chapterId":"ch_work_han_thu_117","textTraditional":"更名匈奴單于曰降奴服于。莽曰：「降奴服于知〔一〕威侮五行，〔二〕背畔四條，〔三〕侵犯西域，廷及邊垂，為元元害，罪當夷滅。命遣立國將軍孫建等凡十二將，十道並出，共行皇天之威，罰于知之身。〔四〕惟知先祖故呼韓邪單于稽侯〈犭冊〉〔五〕累世忠孝，保塞守徼，不忍以一知之罪，滅稽侯〈犭冊〉之世。今分匈奴國土人民以為十五，立稽侯狦子孫十五人為單于。遣中郎將藺苞、戴級馳之塞下，召拜當為單于者。諸匈奴人當坐虜知之法者，皆赦除之。」遣五威將軍苗訢、虎賁將軍王況出五原，厭難將軍陳欽、震狄將軍王巡出雲中〔六〕，振武將軍王嘉、平狄將軍王萌出代郡，相威將軍李棽、鎮遠將軍李翁出西河，〔七〕誅貉將軍陽俊、討穢將軍嚴尤出漁陽，奮武將軍王駿、定胡將軍王晏出張掖，及褊裨以下百八十人。募天下囚徒、丁男、甲卒三十萬人，轉眾郡委輸五大夫衣裘、兵器、糧食，長吏送自負海江淮至北邊，使者馳傳督趣，以軍興法從事，〔八〕天下騷動。先至者屯邊郡，須畢具乃同時出。","sentenceOrder":181},
  {"id":"s_work_han_thu_117_182","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「知者，莽改單于之名也，本名囊知牙斯。」","sentenceOrder":182},
  {"id":"s_work_han_thu_117_183","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「引夏書甘誓之文。」","sentenceOrder":183},
  {"id":"s_work_han_thu_117_184","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「四條，莽所與作制者，事在匈奴傳。」","sentenceOrder":184},
  {"id":"s_work_han_thu_117_185","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「共讀曰恭。」","sentenceOrder":185},
  {"id":"s_work_han_thu_117_186","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　師古曰：「〈犭冊〉音刪，又音先安反。」","sentenceOrder":186},
  {"id":"s_work_han_thu_117_187","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　師古曰：「厭音一涉反。」","sentenceOrder":187},
  {"id":"s_work_han_thu_117_188","chapterId":"ch_work_han_thu_117","textTraditional":"〔七〕　師古曰：「棽音所林反。」","sentenceOrder":188},
  {"id":"s_work_han_thu_117_189","chapterId":"ch_work_han_thu_117","textTraditional":"〔八〕　師古曰：「傳音張戀反。趣音促。」","sentenceOrder":189},
  {"id":"s_work_han_thu_117_190","chapterId":"ch_work_han_thu_117","textTraditional":"莽以錢幣訖不行，〔一〕復下書曰：「民以食為命，以貨為資，是以八政以食為首。寶貨皆重則小用不給，皆輕則僦載煩費，〔二〕輕重大小各有差品，則用便而民樂。」於是造寶貨五品，語在食貨志。百姓不從，但行小大錢二品而已。盜鑄錢者不可禁，乃重其法，一家鑄錢，五家坐之，沒入為奴婢。吏民出入，持布錢以副符傳，〔三〕不持者，廚傳勿舍，關津苛留。〔四〕公卿皆持以入宮殿門，欲以重而行之。","sentenceOrder":190},
  {"id":"s_work_han_thu_117_191","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「訖，竟也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_117_192","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「僦，送也，一曰賃也，音子就反。」","sentenceOrder":192},
  {"id":"s_work_han_thu_117_193","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「舊法，行者持符傳，即不稽留。今更令持布錢，與符相副，乃得過也。傳音張戀反。其下亦同。」","sentenceOrder":193},
  {"id":"s_work_han_thu_117_194","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「廚，行道飲食處。傳，置驛之舍也。苛，問也，音何。」","sentenceOrder":194},
  {"id":"s_work_han_thu_117_195","chapterId":"ch_work_han_thu_117","textTraditional":"是時爭為符命封侯，其不為者相戲曰：「獨無天帝除書乎？」司令陳崇白莽曰：「此開姦臣作福之路而亂天命，宜絕其原。」莽亦厭之，遂使尚書大夫趙並驗治，非五威將率所班，皆下獄。","sentenceOrder":195},
  {"id":"s_work_han_thu_117_196","chapterId":"ch_work_han_thu_117","textTraditional":"初，甄豐、劉歆、王舜為莽腹心，倡導在位，〔一〕褒揚功德；「安漢」、「宰衡」之號及封莽母、兩子、兄子，皆豐等所共謀，而豐、舜、歆亦受其賜，並富貴矣，非復欲令莽居攝也。居攝之萌，出於泉陵侯劉慶、前煇光謝囂、長安令田終術。莽羽翼已成，意欲稱攝。豐等承順其意，莽輒復封舜、歆兩子及豐孫。豐等爵位已盛，心意既滿，又實畏漢宗室、天下豪桀。而疏遠欲進者，並作符命，莽遂據以即真，舜、歆內懼而已。豐素剛強，莽覺其不說，〔二〕故徙大阿、右拂、大司空豐，託符命文，為更始將軍，〔三〕與賣餅兒王盛同列。豐父子默默。時子尋為侍中京兆大尹茂德侯，即作符命，言新室當分陝，立二伯，〔四〕以豐為右伯，太傅平晏為左伯，如周召故事。莽即從之，拜豐為右伯。當述職西出，未行，尋復作符命，言故漢氏平帝后黃皇室主為尋之妻。莽以詐立，心疑大臣怨謗，欲震威以懼下，因是發怒曰：「黃皇室主天下母，此何謂也！」收捕尋。尋亡，豐自殺。尋隨方士入華山，歲餘捕得，辭連國師公歆子侍中東通靈將、五司大夫隆威侯棻，棻弟右曹長水校尉伐虜侯泳，大司空邑弟左（闕）〔關〕將軍（堂）〔掌〕威侯奇，及歆門人侍中騎都尉丁隆等，牽引公卿黨親列侯以下，死者數百人。尋手理有「天子」字，莽解其臂入視之，曰：「此一大子也，或曰一六子也。六者，戮也。明尋父子當戮死也。」乃流棻于幽州，放尋于三危，殛隆于羽山，〔五〕皆驛車載其屍傳致云。","sentenceOrder":196},
  {"id":"s_work_han_thu_117_197","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「倡音赤上反。」","sentenceOrder":197},
  {"id":"s_work_han_thu_117_198","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「說讀曰悅。」","sentenceOrder":198},
  {"id":"s_work_han_thu_117_199","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「拂讀曰弼。」","sentenceOrder":199},
  {"id":"s_work_han_thu_117_200","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「分陝者，欲依周公、召公故事，自陝以東周公主之，自陝以西召公主之。陝即今陝州，是其地也。伯，長也。陝音式冉反。」","sentenceOrder":200},
  {"id":"s_work_han_thu_117_201","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　師古曰：「效舜之罰共工等也。殛，誅也，音居力反。」","sentenceOrder":201},
  {"id":"s_work_han_thu_117_202","chapterId":"ch_work_han_thu_117","textTraditional":"莽為人侈口蹶顄，〔一〕露眼赤精，大聲而嘶。〔二〕長七尺五寸，好厚履高冠，以氂裝衣，〔三〕反膺高視，瞰臨左右。〔四〕是時有用方技待詔黃門者，或問以莽形貌，待詔曰：「莽所謂鴟目虎吻豺狼之聲者也，故能食人，亦當為人所食。」問者告之，莽誅滅待詔，而封告者。後常翳雲母屏面，〔五〕非親近莫得見也。","sentenceOrder":202},
  {"id":"s_work_han_thu_117_203","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「侈，大也。蹶，短也。顄，頤也。蹶音其月反。顄音胡感反。」","sentenceOrder":203},
  {"id":"s_work_han_thu_117_204","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「嘶，聲破也，音先奚反。」","sentenceOrder":204},
  {"id":"s_work_han_thu_117_205","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「毛之強曲者曰氂，以裝褚衣中，令其張起也。氂音力之反，字或作斄，音義同。」","sentenceOrder":205},
  {"id":"s_work_han_thu_117_206","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「瞰謂遠視也，音口濫反。」","sentenceOrder":206},
  {"id":"s_work_han_thu_117_207","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　師古曰：「屏面即便面，蓋扇之類也。解在張敞傳。」","sentenceOrder":207},
  {"id":"s_work_han_thu_117_208","chapterId":"ch_work_han_thu_117","textTraditional":"是歲，以初睦侯姚恂為寧始將軍。","sentenceOrder":208},
  {"id":"s_work_han_thu_117_209","chapterId":"ch_work_han_thu_117","textTraditional":"三年，莽曰：「百官改更，職事分移，律令儀法，未及悉定，且因漢律令儀法以從事。令公卿大夫諸侯二千石舉吏民有德行通政事能言語明文學者各一人，詣王路四門。」","sentenceOrder":209},
  {"id":"s_work_han_thu_117_210","chapterId":"ch_work_han_thu_117","textTraditional":"遣尚書大夫趙並使勞北邊，還言五原北假膏壤殖穀，〔一〕異時常置田官。乃以並為田禾將軍，發戍卒屯田北假，以助軍糧。","sentenceOrder":210},
  {"id":"s_work_han_thu_117_211","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「北假，地名也。膏壤，言其土肥美也。殖，生也。」","sentenceOrder":211},
  {"id":"s_work_han_thu_117_212","chapterId":"ch_work_han_thu_117","textTraditional":"是時諸將在邊，須大眾集，〔一〕吏士放縱，而內郡愁於徵發，民棄城郭流亡為盜賊，并州、平州尤甚。莽令七公六卿號皆兼稱將軍，遣著武將軍逯並等填名都，〔二〕中郎將、繡衣執法各五十五人，分填緣邊大郡，督大姦猾擅弄兵者，皆便為姦於外，撓亂州郡，〔三〕貨賂為市，侵漁百姓。莽下書曰：「虜知罪當夷滅，故遣猛將分十二部，將同時出，一舉而決絕之矣。內置司命軍正，外設軍監十有二人，誠欲以司不奉命，令軍人咸正也。今則不然，各為權勢，恐猲良民，〔四〕妄封人頸，得錢者去。〔五〕毒蠚並作，農民離散。〔六〕司監若此，可謂稱不？〔七〕自今以來，敢犯此者，輒捕繫，以名聞。」然猶放縱自若。","sentenceOrder":212},
  {"id":"s_work_han_thu_117_213","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「須，待也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_117_214","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「逯音錄。填音竹刃反。此下亦同。」","sentenceOrder":214},
  {"id":"s_work_han_thu_117_215","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「撓音火高反。其字從手。」","sentenceOrder":215},
  {"id":"s_work_han_thu_117_216","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「猲，以威力脅之也，音呼葛反。」","sentenceOrder":216},
  {"id":"s_work_han_thu_117_217","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　如淳曰：「權臣妄以法枉良人為僮僕，封其頸以別之也。得顧錢，乃去封。」","sentenceOrder":217},
  {"id":"s_work_han_thu_117_218","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　師古曰：「蠚音呼各反。」","sentenceOrder":218},
  {"id":"s_work_han_thu_117_219","chapterId":"ch_work_han_thu_117","textTraditional":"〔七〕　師古曰：「稱音尺孕反。」","sentenceOrder":219},
  {"id":"s_work_han_thu_117_220","chapterId":"ch_work_han_thu_117","textTraditional":"而藺苞、戴級到塞下，招誘單于弟咸、咸子登入塞，脅拜咸為孝單于，賜黃金千斤，錦繡甚多，遣去；將登至長安，拜為順單于，留邸。","sentenceOrder":220},
  {"id":"s_work_han_thu_117_221","chapterId":"ch_work_han_thu_117","textTraditional":"太師王舜自莽篡位後病悸，寖劇，死。〔一〕莽曰：「昔齊太公以淑德累世，為周氏太師，蓋予之所監也。〔二〕其以舜子延襲父爵，為安新公，延弟褒新侯匡為太師將軍，永為新室輔。」","sentenceOrder":221},
  {"id":"s_work_han_thu_117_222","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「心動曰悸。寖，漸也。悸音葵季反。」","sentenceOrder":222},
  {"id":"s_work_han_thu_117_223","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「監謂視見也。」","sentenceOrder":223},
  {"id":"s_work_han_thu_117_224","chapterId":"ch_work_han_thu_117","textTraditional":"為太子置師友各四人，秩以大夫。以故大司徒馬宮為師疑，故少府宗伯鳳為傅丞，博士袁聖為阿輔，京兆尹王嘉為保拂，〔一〕是為四師；故尚書令唐林為胥附，博士李充為奔走，〔二〕諫大夫趙襄為先後，中郎將廉丹為禦侮，是為四友。又置師友祭酒及侍中、諫議、六經祭酒各一人，凡九祭酒，秩上卿。琅邪左咸為講春秋、潁川滿昌為講詩、長安國由為講易、平陽唐昌為講書、沛郡陳咸為講禮、崔發為講樂祭酒。遣謁者持安車印綬，即拜楚國龔勝為太子師友祭酒，勝不應徵，不食而死。","sentenceOrder":224},
  {"id":"s_work_han_thu_117_225","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「拂讀曰弼。」","sentenceOrder":225},
  {"id":"s_work_han_thu_117_226","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「犇，古奔字。」","sentenceOrder":226},
  {"id":"s_work_han_thu_117_227","chapterId":"ch_work_han_thu_117","textTraditional":"寧始將軍姚恂免，侍中崇祿侯孔永為寧始將軍。","sentenceOrder":227},
  {"id":"s_work_han_thu_117_228","chapterId":"ch_work_han_thu_117","textTraditional":"是歲，池陽縣有小人景，長尺餘，或乘車馬，或步行，（據）〔操〕持萬物，小大各相稱，〔一〕三日止。","sentenceOrder":228},
  {"id":"s_work_han_thu_117_229","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「車馬及物皆稱其人之形。」","sentenceOrder":229},
  {"id":"s_work_han_thu_117_230","chapterId":"ch_work_han_thu_117","textTraditional":"瀕河郡蝗生。〔一〕","sentenceOrder":230},
  {"id":"s_work_han_thu_117_231","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「謂緣河南北諸郡。瀕音頻，又音賓。」","sentenceOrder":231},
  {"id":"s_work_han_thu_117_232","chapterId":"ch_work_han_thu_117","textTraditional":"河決魏郡，泛清河以東數郡。先是，莽恐河決為元城冢墓害。及決東去，元城不憂水，故遂不隄塞。","sentenceOrder":232},
  {"id":"s_work_han_thu_117_233","chapterId":"ch_work_han_thu_117","textTraditional":"四年二月，赦天下。","sentenceOrder":233},
  {"id":"s_work_han_thu_117_234","chapterId":"ch_work_han_thu_117","textTraditional":"夏，赤氣出東南，竟天。","sentenceOrder":234},
  {"id":"s_work_han_thu_117_235","chapterId":"ch_work_han_thu_117","textTraditional":"厭難將軍陳（歆）〔欽〕言捕虜生口，虜犯邊者皆孝單于咸子角所為。莽怒，斬其子登於長安，以視諸蠻夷。〔一〕","sentenceOrder":235},
  {"id":"s_work_han_thu_117_236","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「視音曰示。」","sentenceOrder":236},
  {"id":"s_work_han_thu_117_237","chapterId":"ch_work_han_thu_117","textTraditional":"大司馬甄邯死，寧始將軍孔永為大司馬，侍中大贅侯輔為寧始將軍。","sentenceOrder":237},
  {"id":"s_work_han_thu_117_238","chapterId":"ch_work_han_thu_117","textTraditional":"莽每當出，輒先索城中，名曰「橫」。〔一〕是月，橫五日。","sentenceOrder":238},
  {"id":"s_work_han_thu_117_239","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「索音山各反。橫音胡孟反。」","sentenceOrder":239},
  {"id":"s_work_han_thu_117_240","chapterId":"ch_work_han_thu_117","textTraditional":"莽至明堂，授諸侯茅土。下書曰：「予以不德，襲于聖祖，為萬國主。思安黎元，在于建侯，分州正域，以美風俗。追監前代，爰綱爰紀。惟在堯典，十有二州，衛有五服。〔一〕詩國十五，抪遍九州。〔二〕殷頌有『奄有九有』之言。〔三〕禹貢之九州無并、幽，周禮司馬則無徐、梁。帝王相改，各有云為。或昭其事，或大其本，厥義著明，其務一矣。昔周二后受命，故有東都、西都之居。予之受命，蓋亦如之。其以洛陽為新室東都，常安為新室西都。邦畿連體，各有采任。州從禹貢為九，爵從周氏有五。諸侯之員千有八百，附城之數亦如之，以俟有功。諸公一同，有眾萬戶，土方百里。侯伯一國，眾戶五千，土方七十里。子男一則，眾戶二千有五百，土方五十里。附城大者食邑九成，眾戶九百，土方三十里。自九以下，降殺以兩，〔四〕至於一成。〔五〕五差備具，合當一則。今已受茅土者，公十四人，侯九十三人，伯二十一人，子百七十一人，男四百九十七人，凡七百九十六人。附城千五百一十一人。九族之女為任者，八十三人。及漢氏女孫中山承禮君、遵德君、修義君更以為任。十有一公，九卿，十二大夫，二十四元士。定諸國邑采之處，使侍中講禮大夫孔秉等與州部眾郡曉知地理圖籍者，共校治于壽成朱鳥堂。予數與群公祭酒上卿親聽視，咸已通矣。夫褒德賞功，所以顯仁賢也；九族和睦，所以褒親親也。予永惟匪解，思稽前人，〔六〕將章黜陟，以明好惡，安元元焉。」以圖簿未定，未授國邑，且令受奉都內，月錢數千。〔七〕諸侯皆困乏，至有庸作者。","sentenceOrder":240},
  {"id":"s_work_han_thu_117_241","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「並解於上。」","sentenceOrder":241},
  {"id":"s_work_han_thu_117_242","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「謂周南、召南、衛、王、鄭、齊、魏、唐、秦、陳、鄶、曹、豳、魯、商，凡十五國也。一曰，周南、召南、邶、鄘、衛、王、鄭、齊、魏、唐、秦、陳、鄶、曹、豳，是為十五國。抪音普胡反。」","sentenceOrder":242},
  {"id":"s_work_han_thu_117_243","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「商頌玄鳥之詩，美湯有功德，故能覆有九州。」","sentenceOrder":243},
  {"id":"s_work_han_thu_117_244","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「兩兩而降也。殺音所例反。」","sentenceOrder":244},
  {"id":"s_work_han_thu_117_245","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　如淳曰：「十里為成。」","sentenceOrder":245},
  {"id":"s_work_han_thu_117_246","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　師古曰：「解音曰懈。稽，考也。」","sentenceOrder":246},
  {"id":"s_work_han_thu_117_247","chapterId":"ch_work_han_thu_117","textTraditional":"〔七〕　師古曰：「奉音扶用反。」","sentenceOrder":247},
  {"id":"s_work_han_thu_117_248","chapterId":"ch_work_han_thu_117","textTraditional":"中郎區博諫莽曰：〔一〕「井田雖聖王法，其廢久矣。周道既衰，而民不從。秦知順民之心，可以獲大利也，故滅廬井而置阡陌，遂王諸夏，訖今海內未厭其敝。今欲違民心，追復千載絕跡，〔二〕雖堯舜復起，而無百年之漸，弗能行也。天下初定，萬民新附，誠未可施行。」莽知民怨，乃下書曰：「諸名食王田，皆得賣之，勿拘以法。犯私買賣庶人者，且一切勿治。」","sentenceOrder":248},
  {"id":"s_work_han_thu_117_249","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「區，姓也，音一侯反。」","sentenceOrder":249},
  {"id":"s_work_han_thu_117_250","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「復音扶目反。」","sentenceOrder":250},
  {"id":"s_work_han_thu_117_251","chapterId":"ch_work_han_thu_117","textTraditional":"初，五威將帥出，改句町王以為侯，王邯怨怒不附。〔一〕莽諷牂柯大尹周歆詐殺邯。邯弟承起兵攻殺歆。先是，莽發高句驪兵，當伐胡，不欲行，郡強迫之，皆亡出塞，因犯法為寇。遼西大尹田譚追擊之，為所殺。州郡歸咎於高句驪侯騶。嚴尤奏言：「貉人犯法，不從騶起，正有它心，宜令州郡且尉安之。〔二〕今猥被以大罪，恐其遂畔，〔三〕夫餘之屬必有和者。〔四〕匈奴未克，夫餘、穢貉復起，此大憂也。」莽不尉安，穢貉遂反，詔尤擊之。尤誘高句驪侯騶至而斬焉，傳首長安。莽大說，下書曰：「乃者，命遣猛將，共行天罰，〔五〕誅滅虜知，分為十二部，或斷其右臂，或斬其左腋，或潰其胸腹，或紬其兩脅。〔六〕今年刑在東方，〔七〕誅貉之部先縱焉。捕斬虜騶，平定東域，虜知殄滅，在于漏刻。此乃天地群神社稷宗廟佑助之福，公卿大夫士民同心將率虓虎之力也。〔八〕予甚嘉之。其更名高句驪為下句驪，布告天下，令咸知焉。」於是貉人愈犯邊，東北與西南夷皆亂云。","sentenceOrder":251},
  {"id":"s_work_han_thu_117_252","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「邯，句町王之名也，音下甘反。」","sentenceOrder":252},
  {"id":"s_work_han_thu_117_253","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「假令騶有惡心，亦當且慰安。」","sentenceOrder":253},
  {"id":"s_work_han_thu_117_254","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「猥，多也，厚也。被，加也，音皮義反。」","sentenceOrder":254},
  {"id":"s_work_han_thu_117_255","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「和，應也，音胡臥反。」","sentenceOrder":255},
  {"id":"s_work_han_thu_117_256","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　師古曰：「共讀曰恭。」","sentenceOrder":256},
  {"id":"s_work_han_thu_117_257","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　師古曰：「紬音與抽同。」","sentenceOrder":257},
  {"id":"s_work_han_thu_117_258","chapterId":"ch_work_han_thu_117","textTraditional":"〔七〕　張晏曰：「是歲在壬申，刑在東方。」","sentenceOrder":258},
  {"id":"s_work_han_thu_117_259","chapterId":"ch_work_han_thu_117","textTraditional":"〔八〕　師古曰：「虓音火交反。」","sentenceOrder":259},
  {"id":"s_work_han_thu_117_260","chapterId":"ch_work_han_thu_117","textTraditional":"莽志方盛，以為四夷不足吞滅，專念稽古之事，復下書曰：「伏念予之皇始祖考虞帝，受終文祖，在璇璣玉衡以齊七政，遂類于上帝，禋于六宗，望秩于山川，遍于群神，巡狩五嶽，群后四朝，敷奏以言，明試以功。〔一〕予之受命即真，到于建國五年，已五載矣。陽九之阨既度，百六之會已過。歲在壽星，填在明堂，倉龍癸酉，德在中宮。〔二〕觀晉掌歲，龜策告從，〔三〕其以此年二月建寅之節東巡狩，具禮儀調度。」〔四〕群公奏請募吏民人馬布帛綿，又請內郡國十二買馬，發帛四十五萬匹，輸常安，前後毋相須。〔五〕至者過半，莽下書曰：「文母太后體不安，其且止待後。」","sentenceOrder":260},
  {"id":"s_work_han_thu_117_261","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「解並在前。」","sentenceOrder":261},
  {"id":"s_work_han_thu_117_262","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　服虔曰：「倉龍，太歲也。」張晏曰：「太歲起於甲寅為龍，東方倉。癸德在中宮也。」晉灼曰：「壽星，角亢也。東宮倉龍，房心也。心為明堂，填星所在，其國昌。莽自謂土也，土行主填星。癸德在中宮，宮又土也。」","sentenceOrder":262},
  {"id":"s_work_han_thu_117_263","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　孟康曰：「觀辰星進退。掌，主也。」晉灼曰：「國語晉文公以卯出酉入，過五鹿得土，歲在壽星，其日戊申。莽欲法之，以為吉祥。正以二月建寅之節東巡狩者，取萬物生之始也。視晉識太歲所在，宿度所合，卜筮皆吉，故法之。」","sentenceOrder":263},
  {"id":"s_work_han_thu_117_264","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「調音徒釣反。」","sentenceOrder":264},
  {"id":"s_work_han_thu_117_265","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　師古曰：「須，待也。」","sentenceOrder":265},
  {"id":"s_work_han_thu_117_266","chapterId":"ch_work_han_thu_117","textTraditional":"是歲，改十一公號，以「新」為「心」，後又改「心」為「信」。","sentenceOrder":266},
  {"id":"s_work_han_thu_117_267","chapterId":"ch_work_han_thu_117","textTraditional":"五年二月，文母皇太后崩，葬渭陵，與元帝合而溝絕之。〔一〕立廟於長安，新室世世獻祭。元帝配食，坐於床下。莽為太后服喪三年。","sentenceOrder":267},
  {"id":"s_work_han_thu_117_268","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　如淳曰：「葬於司馬門內，作溝絕之。」","sentenceOrder":268},
  {"id":"s_work_han_thu_117_269","chapterId":"ch_work_han_thu_117","textTraditional":"大司馬孔永乞骸骨，賜安車駟馬，以特進就朝位。同風侯逯並為大司馬。","sentenceOrder":269},
  {"id":"s_work_han_thu_117_270","chapterId":"ch_work_han_thu_117","textTraditional":"是時，長安民聞莽欲都雒陽，不肯繕治室宅，〔一〕或頗徹之。莽曰：「玄龍石文曰『定帝德，國雒陽』。符命著明，敢不欽奉！以始建國八年，歲纏星紀，〔二〕在雒陽之都。其謹繕脩常安之都，勿令壞敗。敢有犯者，輒以名聞，請其罪。」","sentenceOrder":270},
  {"id":"s_work_han_thu_117_271","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「繕，補也。」","sentenceOrder":271},
  {"id":"s_work_han_thu_117_272","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　孟康曰：「纏，居也。星紀在斗、牽牛間。」師古曰：「纏，踐歷也，音直連反。」","sentenceOrder":272},
  {"id":"s_work_han_thu_117_273","chapterId":"ch_work_han_thu_117","textTraditional":"是歲，烏孫大小昆彌遣使貢獻。大昆彌者，中國外孫也。其胡婦子為小昆彌，而烏孫歸附之。莽見匈奴諸邊並侵，意欲得烏孫心，乃遣使者引小昆彌使置大昆彌使上。保成師友祭酒滿昌劾奏使者曰：「夷狄以中國有禮誼，故詘而服從。大昆彌，君也，今序臣使於君使之上，非所以有夷狄也。奉使大不敬！」莽怒，免昌官。","sentenceOrder":273},
  {"id":"s_work_han_thu_117_274","chapterId":"ch_work_han_thu_117","textTraditional":"西域諸國以莽積失恩信，焉耆先畔，殺都護但欽。","sentenceOrder":274},
  {"id":"s_work_han_thu_117_275","chapterId":"ch_work_han_thu_117","textTraditional":"十一月，彗星出，二十餘日，不見。","sentenceOrder":275},
  {"id":"s_work_han_thu_117_276","chapterId":"ch_work_han_thu_117","textTraditional":"是歲，以犯挾銅炭者多，除其法。","sentenceOrder":276},
  {"id":"s_work_han_thu_117_277","chapterId":"ch_work_han_thu_117","textTraditional":"明年改元曰天鳳。","sentenceOrder":277},
  {"id":"s_work_han_thu_117_278","chapterId":"ch_work_han_thu_117","textTraditional":"天鳳元年正月，赦天下。","sentenceOrder":278},
  {"id":"s_work_han_thu_117_279","chapterId":"ch_work_han_thu_117","textTraditional":"莽曰：「予以二月建寅之節行巡狩之禮，太官齎糒乾肉，內者行張坐臥，〔一〕所過毋得有所給。〔二〕予之東巡，必躬載耒，每縣則耕，以勸東作。〔三〕予之南巡，必躬載耨，每縣則薅，以勸南偽。〔四〕予之西巡，必躬載銍，每縣則穫，以勸西成。予之北巡，必躬載拂，每縣則粟，以勸蓋藏。〔五〕畢北巡狩之禮，即于土中居雒陽之都焉。敢有趨讙犯法，輒以軍法從事。」〔六〕群公奏言：「皇帝至孝，往年文母聖體不豫，躬親供養，衣冠稀解。因遭棄群臣悲哀，顏色未復，飲食損少。今一歲四巡，道路萬里，春秋尊，非糒乾肉之所能堪。且無巡狩，須闋大服，以安聖體。〔七〕臣等盡力養牧兆民，奉稱明詔。」〔八〕莽曰：「群公、群牧、群司、諸侯、庶尹願盡力相帥養牧兆民，欲以稱予，繇此敬聽，〔九〕其勗之哉！毋食言焉。更以天鳳七年，歲在大梁，倉龍庚辰，行巡狩之禮。厥明年，歲在實沈，倉龍辛巳，即土之中雒陽之都。」乃遣太傅平晏、大司空王邑之雒陽，營相宅兆，圖起宗廟、社稷、郊兆云。","sentenceOrder":279},
  {"id":"s_work_han_thu_117_280","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「糒，乾飯也。張坐臥，謂帷帳茵席也。糒音備。」","sentenceOrder":280},
  {"id":"s_work_han_thu_117_281","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「言自齎食及帷帳以行，在路所經過，不須供費也。」","sentenceOrder":281},
  {"id":"s_work_han_thu_117_282","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「耒，耕曲木也，音力對反。」","sentenceOrder":282},
  {"id":"s_work_han_thu_117_283","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「耨，鉏也。薅，耘去草也。耨音奴豆反。薅音火高反。偽讀曰訛。訛，化也。」","sentenceOrder":283},
  {"id":"s_work_han_thu_117_284","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　師古曰：「拂音佛，所以擊治禾者也，今謂之連枷。粟謂治粟。」","sentenceOrder":284},
  {"id":"s_work_han_thu_117_285","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　劉德曰：「趨讙，走呼也。」","sentenceOrder":285},
  {"id":"s_work_han_thu_117_286","chapterId":"ch_work_han_thu_117","textTraditional":"〔七〕　師古曰：「闋，盡也，音口決反。」","sentenceOrder":286},
  {"id":"s_work_han_thu_117_287","chapterId":"ch_work_han_thu_117","textTraditional":"〔八〕　師古曰：「稱，副也。」","sentenceOrder":287},
  {"id":"s_work_han_thu_117_288","chapterId":"ch_work_han_thu_117","textTraditional":"〔九〕　師古曰：「繇讀與由同。」","sentenceOrder":288},
  {"id":"s_work_han_thu_117_289","chapterId":"ch_work_han_thu_117","textTraditional":"三月壬申晦，日有食之。大赦天下。策大司馬逯並曰：「日食無光，干戈不戢，其上大司馬印韍，就侯氏朝位。太傅平晏勿領尚書事，省侍中諸曹兼官者。以利苗男訢為大司馬。」〔一〕","sentenceOrder":289},
  {"id":"s_work_han_thu_117_290","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　如淳曰：「利苗，邑名。」","sentenceOrder":290},
  {"id":"s_work_han_thu_117_291","chapterId":"ch_work_han_thu_117","textTraditional":"莽即真，尤備大臣，抑奪下權，朝臣有言其過失者，輒拔擢。孔仁、趙博、費興等以敢擊大臣，故見信任，〔一〕擇名官而居之。公卿入宮，吏有常數，太傅平晏從吏過例，掖門僕射苛問不遜，〔二〕戊曹士收繫僕射。〔三〕莽大怒，使執法發車騎數百圍太傅府，捕士，即時死。大司空士夜過奉常亭，亭長苛之，告以官名，亭長醉曰：「寧有符傳邪？」〔四〕士以馬箠擊亭長，〔五〕亭長斬士，亡，郡縣逐之。家上書，〔六〕莽曰：「亭長奉公，勿逐。」大司空邑斥士以謝。國將哀章頗不清，莽為選置和叔，〔七〕敕曰：「非但保國將閨門，當保親屬在西州者。」諸公皆輕賤，而章尤甚。","sentenceOrder":291},
  {"id":"s_work_han_thu_117_292","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「費音扶味反。」","sentenceOrder":292},
  {"id":"s_work_han_thu_117_293","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「僕射苛問平晏，其言不遜。」","sentenceOrder":293},
  {"id":"s_work_han_thu_117_294","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　應劭曰：「莽自以土行，故使太傅置戊曹士。士，掾也。」蘇林曰：「士者，曹掾，屬公府，諸曹次第之名也。」師古曰：「應說是。」","sentenceOrder":294},
  {"id":"s_work_han_thu_117_295","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「傳音張戀反。」","sentenceOrder":295},
  {"id":"s_work_han_thu_117_296","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　師古曰：「箠，策也，音止繠反。」","sentenceOrder":296},
  {"id":"s_work_han_thu_117_297","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　師古曰：「亭長家上書自治。」","sentenceOrder":297},
  {"id":"s_work_han_thu_117_298","chapterId":"ch_work_han_thu_117","textTraditional":"〔七〕　師古曰：「特為置此官。」","sentenceOrder":298},
  {"id":"s_work_han_thu_117_299","chapterId":"ch_work_han_thu_117","textTraditional":"四月，隕霜，殺屮木，〔一〕海瀕尤甚。〔二〕六月，黃霧四塞。七月，大風拔樹，飛北闕直城門屋瓦。〔三〕雨雹，殺牛羊。","sentenceOrder":299},
  {"id":"s_work_han_thu_117_300","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「屮，古草字。」","sentenceOrder":300},
  {"id":"s_work_han_thu_117_301","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「邊海之地也。瀕音頻，又音賓。」","sentenceOrder":301},
  {"id":"s_work_han_thu_117_302","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「北闕直城門瓦皆飛也。直城門，長安城門名也，解在成紀。」","sentenceOrder":302},
  {"id":"s_work_han_thu_117_303","chapterId":"ch_work_han_thu_117","textTraditional":"莽以周官、王制之文，置卒正、連率、大尹，職如太守；屬令、屬長，職如都尉。置州牧、部監二十五人。見禮如三公。監位上大夫，各主五郡。公氏作牧，侯氏卒正，伯氏連率，子氏屬令，男氏屬長，皆世其官，其無爵者為尹。分長安城旁六鄉，置帥各一人。分三輔為六尉郡，〔一〕河東、河內、弘農、河南、潁川、南陽為六隊郡，〔二〕置大夫，職如太守；屬正，職如都尉。更名河南大尹曰保忠信卿。益河南屬縣滿三十。置六郊州長各一人，人主五縣。及它官名悉改。大郡至分為五。郡縣以亭為名者三百六十，以應符命文也。緣邊又置竟尉，以男為之。〔三〕諸侯國閒田，為黜陟增減云。〔四〕莽下書曰：「常安西都曰六鄉，眾縣曰六尉。義陽東都曰六州，眾縣曰六隊。粟米之內曰內郡，〔五〕其外曰近郡。有鄣徼者曰邊郡。合百二十有五郡。九州之內，縣二千二百有三。公作甸服，是為惟城；諸在侯服，是為惟寧；在采、任諸侯，是為惟翰；〔六〕在賓服，是為惟屏；〔七〕在揆文教，奮武衛，是為惟垣；在九州之外，是為惟藩：〔八〕各以其方為稱，總為萬國焉。」其後，歲復變更，一郡至五易名，而還復其故。吏民不能紀，每下詔書，輒繫其故名，曰：「制詔陳留大尹、太尉：其以益歲以南付新平。〔九〕新平，故淮陽。以雍丘以東付陳定。陳定，故梁郡。以封丘以東付治亭。治亭，故東郡。以陳留以西付祈隧。祈隧，故滎陽。陳留已無復有郡矣。大尹、太尉，皆詣行在所。」其號令變易，皆此類也。","sentenceOrder":303},
  {"id":"s_work_han_thu_117_304","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「三輔黃圖云：『渭城、安陵以西，北至栒邑、義渠十縣，屬京尉大夫府，居故長安寺；高陵以北十縣，屬師尉大夫府，居故廷尉府；新豐以東，至湖十縣，屬翊尉大夫府，居城東；霸陵、杜陵，東至藍田，西至武功、郁夷十縣，屬光尉大夫府，居城南；茂陵、槐里以西，至汧十縣，屬扶尉大夫府，居城西；長陵、池陽以北，至雲陽、祋祤十縣，屬列尉大夫府，居城北。』」","sentenceOrder":304},
  {"id":"s_work_han_thu_117_305","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「隊音遂。」","sentenceOrder":305},
  {"id":"s_work_han_thu_117_306","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「竟音曰境。」","sentenceOrder":306},
  {"id":"s_work_han_thu_117_307","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「閒音閑。以擬有功封賜，有罪黜陟也。」","sentenceOrder":307},
  {"id":"s_work_han_thu_117_308","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　師古曰：「禹貢去王城四百里納粟，五百里納米，皆在甸服之內。」","sentenceOrder":308},
  {"id":"s_work_han_thu_117_309","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　師古曰：「采，采服也。任，男服也。」","sentenceOrder":309},
  {"id":"s_work_han_thu_117_310","chapterId":"ch_work_han_thu_117","textTraditional":"〔七〕　師古曰：「賓服即古衛服也，取諸侯賓服以為名。」","sentenceOrder":310},
  {"id":"s_work_han_thu_117_311","chapterId":"ch_work_han_thu_117","textTraditional":"〔八〕　師古曰：「凡此惟城以下，取詩大雅板之篇云『价人惟藩，大師惟垣，大邦惟屏，大宗惟翰，懷德惟寧，宗子惟城』，以為名號也。解在諸侯王表。」","sentenceOrder":311},
  {"id":"s_work_han_thu_117_312","chapterId":"ch_work_han_thu_117","textTraditional":"〔九〕　蘇林曰：「陳留圉縣，莽改曰益歲。」","sentenceOrder":312},
  {"id":"s_work_han_thu_117_313","chapterId":"ch_work_han_thu_117","textTraditional":"令天下小學，戊子代甲子為六旬首。冠以戊子為元日，〔一〕昏以戊寅之旬為忌日。〔二〕百姓多不從者。","sentenceOrder":313},
  {"id":"s_work_han_thu_117_314","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「冠音工喚反。元，善也。」","sentenceOrder":314},
  {"id":"s_work_han_thu_117_315","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「昏謂娶妻也。」","sentenceOrder":315},
  {"id":"s_work_han_thu_117_316","chapterId":"ch_work_han_thu_117","textTraditional":"匈奴單于知死，弟咸立為單于，求和親。莽遣使者厚賂之，詐許還其侍子登，因購求陳良、終帶等。單于即執良等付使者，檻車詣長安。莽燔燒良等於城北，令吏民會觀之。","sentenceOrder":316},
  {"id":"s_work_han_thu_117_317","chapterId":"ch_work_han_thu_117","textTraditional":"緣邊大飢，人相食。諫大夫如普行邊兵，〔一〕還言「軍士久屯塞苦，邊郡無以相贍。今單于新和，宜因是罷兵。」校尉韓威進曰：「以新室之威而吞胡虜，無異口中蚤蝨。臣願得勇敢之士五千人，不齎斗糧，飢食虜肉，渴飲其血，可以橫行。」莽壯其言，以威為將軍。然采普言，徵還諸將在邊者。免陳欽等十八人，又罷四關填都尉諸屯兵。會匈奴使還，單于知侍子登前誅死，發兵寇邊，莽復發軍屯。於是邊民流入內郡，為人奴婢，乃禁吏民敢挾邊民者棄市。","sentenceOrder":317},
  {"id":"s_work_han_thu_117_318","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「行音下更反。」","sentenceOrder":318},
  {"id":"s_work_han_thu_117_319","chapterId":"ch_work_han_thu_117","textTraditional":"益州蠻夷殺大尹程隆，三邊盡反。遣平蠻將軍（馬）〔馮〕茂將兵擊之。","sentenceOrder":319},
  {"id":"s_work_han_thu_117_320","chapterId":"ch_work_han_thu_117","textTraditional":"寧始將軍侯輔免，講易祭酒戴參為寧始將軍。","sentenceOrder":320},
  {"id":"s_work_han_thu_117_321","chapterId":"ch_work_han_thu_117","textTraditional":"二年二月，置酒王路堂，公卿大夫皆佐酒。〔一〕大赦天下。","sentenceOrder":321},
  {"id":"s_work_han_thu_117_322","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「助行酒。」","sentenceOrder":322},
  {"id":"s_work_han_thu_117_323","chapterId":"ch_work_han_thu_117","textTraditional":"是時，日中見星。","sentenceOrder":323},
  {"id":"s_work_han_thu_117_324","chapterId":"ch_work_han_thu_117","textTraditional":"大司馬苗訢左遷司命，以延德侯陳茂為大司馬。","sentenceOrder":324},
  {"id":"s_work_han_thu_117_325","chapterId":"ch_work_han_thu_117","textTraditional":"訛言黃龍墮死黃山宮中，百姓奔走往觀者有萬數。莽惡之，〔一〕捕繫問語所從起，不能得。","sentenceOrder":325},
  {"id":"s_work_han_thu_117_326","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「莽自謂黃德，故有此妖。」","sentenceOrder":326},
  {"id":"s_work_han_thu_117_327","chapterId":"ch_work_han_thu_117","textTraditional":"單于咸既和親，求其子登屍，莽欲遣使送致，恐咸怨恨害使者，乃收前言當誅侍子者故將軍陳欽，以他罪繫獄。欽曰：「是欲以我為說於匈奴也。」〔一〕遂自殺。莽選儒生能顓對者〔二〕濟南王咸為大使，五威將琅邪伏黯等為帥，使送登屍。敕令掘單于知墓，棘鞭其屍。又令匈奴卻塞於漠北，責單于馬萬匹，牛三萬頭，羊十萬頭，及稍所略邊民生口在者皆還之。莽好為大言如此。咸到單于庭，陳莽威德，責單于背畔之罪，應敵從橫，單于不能詘，遂致命而還之。入塞，咸病死，封其子為伯，伏黯等皆為子。","sentenceOrder":327},
  {"id":"s_work_han_thu_117_328","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「說，解說也。託言以其前建議誅侍子，今故殺之。」","sentenceOrder":328},
  {"id":"s_work_han_thu_117_329","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「顓與專同。專對，謂應對無方，能專其事。」","sentenceOrder":329},
  {"id":"s_work_han_thu_117_330","chapterId":"ch_work_han_thu_117","textTraditional":"莽意以為制定則天下自平，故銳思於地里，制禮作樂，講合六經之說。公卿旦入暮出，議論連年不決，不暇省獄訟冤結民之急務。縣宰缺者，數年守兼，〔一〕一切貪殘日甚。中郎將、繡衣執法在郡國者，並乘權勢，傳相舉奏。又十一公士分布勸農桑，班時令，案諸章，冠蓋相望，交錯道路，召會吏民，逮捕證左，郡縣賦斂，遞相賕賂，白黑紛然，〔二〕守闕告訴者多。莽自見前顓權以得漢政，故務自〈扌監〉眾事，〔三〕有司受成苟免。〔四〕諸寶物名、帑藏、錢穀官，皆宦者領之；〔五〕吏民上封事書，宦官左右開發，尚書不得知。其畏備臣下如此。又好變改制度，政令煩多，當（奏）〔奉〕行者，輒質問乃以從事，〔六〕前後相乘，憒眊不渫。〔七〕莽常御燈火至明，猶不能勝。尚書因是為姦寢事，上書待報者連年不得去，拘繫郡縣者逢赦而後出，衛卒不交代三歲矣。穀常貴，邊兵二十餘萬人仰衣食，縣官愁苦。〔八〕五原、代郡尤被其毒，起為盜賊，數千人為輩，轉入旁郡。莽遣捕盜將軍孔仁將兵與郡縣合擊，歲餘乃定，邊郡亦略將盡。〔九〕","sentenceOrder":330},
  {"id":"s_work_han_thu_117_331","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「不拜正官，權令人守兼。」","sentenceOrder":331},
  {"id":"s_work_han_thu_117_332","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「白黑謂清濁也。紛然，亂意也，言清濁不分也。」","sentenceOrder":332},
  {"id":"s_work_han_thu_117_333","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「〈扌監〉與攬同，其字從手。」","sentenceOrder":333},
  {"id":"s_work_han_thu_117_334","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「莽事事自決，成熟乃以付吏，吏苟免罪責而已。」","sentenceOrder":334},
  {"id":"s_work_han_thu_117_335","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　師古曰：「帑音他莽反，又音奴。」","sentenceOrder":335},
  {"id":"s_work_han_thu_117_336","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　師古曰：「質，正也。」","sentenceOrder":336},
  {"id":"s_work_han_thu_117_337","chapterId":"ch_work_han_thu_117","textTraditional":"〔七〕　師古曰：「乘，積也，登也。憒眊，不明也。渫，散也，徹也。憒音工內反。眊音莫報反。」","sentenceOrder":337},
  {"id":"s_work_han_thu_117_338","chapterId":"ch_work_han_thu_117","textTraditional":"〔八〕　師古曰：「仰音牛向反。」","sentenceOrder":338},
  {"id":"s_work_han_thu_117_339","chapterId":"ch_work_han_thu_117","textTraditional":"〔九〕　師古曰：「言其逃亡，結為盜賊，在者少也。」","sentenceOrder":339},
  {"id":"s_work_han_thu_117_340","chapterId":"ch_work_han_thu_117","textTraditional":"邯鄲以北大雨霧，水出，深者數丈，流殺數千人。","sentenceOrder":340},
  {"id":"s_work_han_thu_117_341","chapterId":"ch_work_han_thu_117","textTraditional":"立國將軍孫建死，司命趙閎為立國將軍。寧始將軍戴參歸故官，南城將軍廉丹為寧始將軍。","sentenceOrder":341},
  {"id":"s_work_han_thu_117_342","chapterId":"ch_work_han_thu_117","textTraditional":"三年二月乙酉，地震，大雨雪，〔一〕關東尤甚，深者一丈，竹柏或枯。大司空王邑上書言：「視事八年，功業不效，司空之職尤獨廢頓，至乃有地震之變。願乞骸骨。」莽曰：「夫地有動有震，震者有害，動者不害。春秋記地震，易繫坤動，動靜辟脅，萬物生焉〔二〕。災異之變，各有云為。天地動威，以戒予躬，公何辜焉，而乞骸骨，非所以助予者也。使諸吏散騎司祿大衛脩寧男遵諭予意焉。」","sentenceOrder":342},
  {"id":"s_work_han_thu_117_343","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「雨音于具反。」","sentenceOrder":343},
  {"id":"s_work_han_thu_117_344","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「辟音闢。闢，開也。脅，收斂也。易上繫之辭曰：『夫坤，其動也闢，其靜也翕，是以廣生焉。』故莽引之也。翕脅之聲相近，義則同。」","sentenceOrder":344},
  {"id":"s_work_han_thu_117_345","chapterId":"ch_work_han_thu_117","textTraditional":"五月，莽下吏祿制度，曰：「予遭陽九之阨，百六之會，國用不足，民人騷動，自公卿以下，一月之祿十緵布二匹，〔一〕或帛一匹。予每念之，未嘗不戚焉。今阨會已度，府帑雖未能充，略頗稍給，其以六月朔庚寅始，賦吏祿皆如制度。」四輔公卿大夫士，下至輿僚，凡十五等。僚祿一歲六十六斛，稍以差增，上至四輔而為萬斛云。莽又曰：「『普天之下，莫非王土；率土之賓，莫非王臣。』〔二〕蓋以天下養焉。周禮膳羞百有二十品，今諸侯各食其同、國、則〔三〕；辟、任、附城食其邑；〔四〕公、卿、大夫、元士食其采。〔五〕多少之差，咸有條品。歲豐穰則充其禮，〔六〕有災害則有所損，與百姓同憂喜也。其用上計時通計，天下幸無災害者，太官膳羞備其品矣；即有災害，以什率多少而損膳焉。東嶽太師立國將軍保東方三州一部二十五郡；南嶽太傅前將軍保南方二州一部二十五郡；西嶽國師寧始將軍保西方一州二部二十五郡；北嶽國將衛將軍保北方二州一部二十五郡；大司馬保納卿、言卿、仕卿、作卿、京尉、扶尉、兆隊、右隊、中部左洎前七部；〔七〕大司徒保樂卿、典卿、宗卿、秩卿、翼尉、光尉、左隊、前隊、中部、右部，有五郡；大司空保予卿、虞卿、共卿、工卿、師尉、列尉、祈隊、後隊、中部洎後十郡；〔八〕及六司，六卿，皆隨所屬之公保其災害，亦以十率多少而損其祿。郎、從官、中都官吏食祿都內之委者，以太官膳羞備損而為節。〔九〕諸侯、辟、任、附城、群吏亦各保其災害。幾上下同心，〔一０〕勸進農業，安元元焉。」莽之制度煩碎如此，課計不可理，吏終不得祿，各因官職為姦，受取賕賂以自共給。〔一一〕","sentenceOrder":345},
  {"id":"s_work_han_thu_117_346","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　孟康曰：「緵，八十（緵）〔縷〕也。」師古曰：「緵音子公反。」","sentenceOrder":346},
  {"id":"s_work_han_thu_117_347","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「莽引小雅北山之詩也。」","sentenceOrder":347},
  {"id":"s_work_han_thu_117_348","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「謂公食同，侯伯食國，子男食則也。」","sentenceOrder":348},
  {"id":"s_work_han_thu_117_349","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「辟，君也。任，公主也。辟音壁。任音壬。」","sentenceOrder":349},
  {"id":"s_work_han_thu_117_350","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　師古曰：「謂因官職而食地也。」","sentenceOrder":350},
  {"id":"s_work_han_thu_117_351","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　師古曰：「穰音人掌反。」","sentenceOrder":351},
  {"id":"s_work_han_thu_117_352","chapterId":"ch_work_han_thu_117","textTraditional":"〔七〕　服虔曰：「大司馬保此官，皆如郡守也。」晉灼曰：「左與前故特七部。」師古曰：「洎亦臮字也。臮，及也。隊音遂。此下並同。」","sentenceOrder":352},
  {"id":"s_work_han_thu_117_353","chapterId":"ch_work_han_thu_117","textTraditional":"〔八〕　師古曰：「共讀曰龔。」","sentenceOrder":353},
  {"id":"s_work_han_thu_117_354","chapterId":"ch_work_han_thu_117","textTraditional":"〔九〕　師古曰：「言隨其多少。」","sentenceOrder":354},
  {"id":"s_work_han_thu_117_355","chapterId":"ch_work_han_thu_117","textTraditional":"〔一０〕師古曰：「幾音曰冀。」","sentenceOrder":355},
  {"id":"s_work_han_thu_117_356","chapterId":"ch_work_han_thu_117","textTraditional":"〔一一〕師古曰：「共讀曰供。」","sentenceOrder":356},
  {"id":"s_work_han_thu_117_357","chapterId":"ch_work_han_thu_117","textTraditional":"是月戊辰，長平館西岸崩，邕涇水不流，毀而北行。〔一〕遣大司空王邑行視，〔二〕還奏狀，群臣上壽，以為河圖所謂「以土填水」，〔三〕匈奴滅亡之祥也。乃遣并州牧宋弘、游擊都尉任萌等將兵擊匈奴，至邊止屯。","sentenceOrder":357},
  {"id":"s_work_han_thu_117_358","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「邕讀曰壅。」","sentenceOrder":358},
  {"id":"s_work_han_thu_117_359","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「行音下更反。」","sentenceOrder":359},
  {"id":"s_work_han_thu_117_360","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「填讀與鎮同。」","sentenceOrder":360},
  {"id":"s_work_han_thu_117_361","chapterId":"ch_work_han_thu_117","textTraditional":"七月辛酉，霸城門災，民間所謂青門也。〔一〕","sentenceOrder":361},
  {"id":"s_work_han_thu_117_362","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「三輔黃圖云長安城東出南頭名霸城門，俗以其色青，名曰青門。」","sentenceOrder":362},
  {"id":"s_work_han_thu_117_363","chapterId":"ch_work_han_thu_117","textTraditional":"戊子晦，日有食之。大赦天下。復令公卿大夫諸侯二千石舉四行各一人。〔一〕大司馬陳茂以日食免，武建伯嚴尤為大司馬。〔二〕","sentenceOrder":363},
  {"id":"s_work_han_thu_117_364","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「依漢光祿之四科。」","sentenceOrder":364},
  {"id":"s_work_han_thu_117_365","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　如淳曰：「莽之伯、子、男號也。」","sentenceOrder":365},
  {"id":"s_work_han_thu_117_366","chapterId":"ch_work_han_thu_117","textTraditional":"十月戊辰，王路朱鳥門鳴，晝夜不絕，崔發等曰：「虞帝闢四門，通四聰。〔一〕門鳴者，明當修先聖之禮，招四方之士也。」於是令群臣皆賀，所舉四行從朱鳥門入而對策焉。","sentenceOrder":366},
  {"id":"s_work_han_thu_117_367","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「虞書敘舜之德也，『闢四門，明四目，達四聰』，故引之。」","sentenceOrder":367},
  {"id":"s_work_han_thu_117_368","chapterId":"ch_work_han_thu_117","textTraditional":"平蠻將軍馮茂擊句町，士卒疾疫，死者什六七，賦斂民財什取五，益州虛耗而不克，徵還下獄死。更遣寧始將軍廉丹與庸部牧史熊擊句町，頗斬首，有勝。莽徵丹、熊，丹、熊願益調度，必克乃還。復大賦斂，就都大尹馮英不肯給，上言「自越巂遂久仇牛、同亭邪豆之屬反畔以來，積且十年，〔一〕郡縣距擊不已。續用馮茂，苟施一切之政。僰道以南，山險高深，茂多敺眾遠居，〔二〕費以億計，吏士離毒氣死者什七。〔三〕今丹、熊懼於自詭期會，〔四〕調發諸郡兵穀，復訾民取其十四，〔五〕空破梁州，功終不遂。〔六〕宜罷兵屯田，明設購賞。」莽怒，免英官。後頗覺寤，曰：「英亦未可厚非。」復以英為長沙連率。","sentenceOrder":368},
  {"id":"s_work_han_thu_117_369","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　服虔曰：「遂久，縣也。仇牛等越巂旁夷。」","sentenceOrder":369},
  {"id":"s_work_han_thu_117_370","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「敺讀與驅同。」","sentenceOrder":370},
  {"id":"s_work_han_thu_117_371","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「離，遭也。」","sentenceOrder":371},
  {"id":"s_work_han_thu_117_372","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「詭，責也。自以為憂責。」","sentenceOrder":372},
  {"id":"s_work_han_thu_117_373","chapterId":"ch_work_han_thu_117","textTraditional":"〔五〕　師古曰：「發人訾財，十取其四也。」","sentenceOrder":373},
  {"id":"s_work_han_thu_117_374","chapterId":"ch_work_han_thu_117","textTraditional":"〔六〕　師古曰：「遂，成也。」","sentenceOrder":374},
  {"id":"s_work_han_thu_117_375","chapterId":"ch_work_han_thu_117","textTraditional":"翟義黨王孫慶捕得，莽使太醫、尚方與巧屠共刳剝之，〔一〕量度五藏，〔二〕以竹筳導其脈，知所終始，〔三〕云可以治病。〔四〕","sentenceOrder":375},
  {"id":"s_work_han_thu_117_376","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「刳，剖也。音口胡反。」","sentenceOrder":376},
  {"id":"s_work_han_thu_117_377","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「度音徒各反。」","sentenceOrder":377},
  {"id":"s_work_han_thu_117_378","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「筳，竹挺也，音庭。」","sentenceOrder":378},
  {"id":"s_work_han_thu_117_379","chapterId":"ch_work_han_thu_117","textTraditional":"〔四〕　師古曰：「以知血脈之原，則盡攻療之道也。」","sentenceOrder":379},
  {"id":"s_work_han_thu_117_380","chapterId":"ch_work_han_thu_117","textTraditional":"是歲，遣大使五威將王駿、西域都護李崇將戊己校尉出西域，諸國皆郊迎貢獻焉。諸國前殺都護但欽，駿欲襲之，命佐帥何封、戊己校尉郭欽別將。〔一〕焉耆詐降，伏兵擊駿等，皆死。欽、封後到，襲擊老弱，從車師還入塞。莽拜欽為填外將軍，〔二〕封劋胡子〔三〕，何封為集胡男。西域自此絕。","sentenceOrder":380},
  {"id":"s_work_han_thu_117_381","chapterId":"ch_work_han_thu_117","textTraditional":"〔一〕　師古曰：「別領兵在後也。將音子亮反。」","sentenceOrder":381},
  {"id":"s_work_han_thu_117_382","chapterId":"ch_work_han_thu_117","textTraditional":"〔二〕　師古曰：「填音竹刃反。」","sentenceOrder":382},
  {"id":"s_work_han_thu_117_383","chapterId":"ch_work_han_thu_117","textTraditional":"〔三〕　師古曰：「劋音子小反。」","sentenceOrder":383},
  {"id":"s_work_han_thu_117_384","chapterId":"ch_work_han_thu_117","textTraditional":"校勘記","sentenceOrder":384},
  {"id":"s_work_han_thu_117_385","chapterId":"ch_work_han_thu_117","textTraditional":"四一０一頁一二行　東（獄）〔嶽〕太師　景祐、殿本都作「嶽」，此誤。","sentenceOrder":385},
  {"id":"s_work_han_thu_117_386","chapterId":"ch_work_han_thu_117","textTraditional":"四一０四頁　三行　（欲）〔敢〕諫之鼓。　景祐本作「敢」。王念孫說作「敢」是。","sentenceOrder":386},
  {"id":"s_work_han_thu_117_387","chapterId":"ch_work_han_thu_117","textTraditional":"四一０七頁　三行　烈，餘業（反）〔也〕。　景祐、殿本都作「也」，此誤。","sentenceOrder":387},
  {"id":"s_work_han_thu_117_388","chapterId":"ch_work_han_thu_117","textTraditional":"四一０九頁　一行　所以輔劉延期之（述）〔術〕，　景祐、殿、局本都作「術」，此誤。","sentenceOrder":388},
  {"id":"s_work_han_thu_117_389","chapterId":"ch_work_han_thu_117","textTraditional":"四一０九頁一五行　長三（尺）〔寸〕，廣一寸，四方，或用（五）〔玉〕，　景祐、殿、局本「尺」都作「寸」，通鑑注同。「五」都作「玉」，此誤，下同。","sentenceOrder":389},
  {"id":"s_work_han_thu_117_390","chapterId":"ch_work_han_thu_117","textTraditional":"四一一０頁　一行　以采絲（茸）〔葺〕其底，　殿本作「葺」。王先謙說殿本是。","sentenceOrder":390},
  {"id":"s_work_han_thu_117_391","chapterId":"ch_work_han_thu_117","textTraditional":"四一一０頁　五行　（是歲）四月，　景祐本無「是歲」二字。","sentenceOrder":391},
  {"id":"s_work_han_thu_117_392","chapterId":"ch_work_han_thu_117","textTraditional":"四一一三頁　七行　故是日天復決（其）以勉書。李慈銘說「其」字衍。","sentenceOrder":392},
  {"id":"s_work_han_thu_117_393","chapterId":"ch_work_han_thu_117","textTraditional":"四一一七頁　一行　命（堂）〔掌〕威侯王奇曰：　王念孫說「堂」當作「掌」。按下文「堂威」，通鑑作「掌威」。","sentenceOrder":393},
  {"id":"s_work_han_thu_117_394","chapterId":"ch_work_han_thu_117","textTraditional":"四一二三頁一二行　大司空邑弟左（闕）〔關〕將軍（堂）〔掌〕威侯奇，　錢大昭說「闕」當作「關」。按景祐、殿本都作「關」。王先謙說「堂」當作「掌」。通鑑並同。","sentenceOrder":394},
  {"id":"s_work_han_thu_117_395","chapterId":"ch_work_han_thu_117","textTraditional":"四一二七頁　六行　（據）〔操〕持萬物，　景祐、殿本都作「操」。王先謙說作「操」是。","sentenceOrder":395},
  {"id":"s_work_han_thu_117_396","chapterId":"ch_work_han_thu_117","textTraditional":"四一二八頁　一行　厭難將軍陳（歆）〔欽〕　楊樹達說上下文都作「欽」，「歆」是誤字。","sentenceOrder":396},
  {"id":"s_work_han_thu_117_397","chapterId":"ch_work_han_thu_117","textTraditional":"四一三九頁　三行　遣平蠻將軍（馬）〔馮〕茂將兵擊之。　景祐、殿本都作「馮」。","sentenceOrder":397},
  {"id":"s_work_han_thu_117_398","chapterId":"ch_work_han_thu_117","textTraditional":"四一四０頁一二行　當（奏）〔奉〕行者，　景祐、殿本都作「奉」。王先謙說「奏」字誤。","sentenceOrder":398},
  {"id":"s_work_han_thu_117_399","chapterId":"ch_work_han_thu_117","textTraditional":"四一四三頁　八行　緵，八十（緵）〔縷〕也。　景祐、殿、局本都作「縷」。","sentenceOrder":399},
  {"id":"s_work_han_thu_118_1","chapterId":"ch_work_han_thu_118","textTraditional":"四年五月，莽曰：「保成師友祭酒唐林、故諫議祭酒琅邪紀逡，〔一〕孝弟忠恕，敬上愛下，博通舊聞，德行醇備，至於黃髮，靡有愆失。〔二〕其封林為建德侯，逡為封德侯，位皆特進，見禮如三公。〔三〕賜弟一區，錢三百萬，授几杖焉。」","sentenceOrder":1},
  {"id":"s_work_han_thu_118_2","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「逡音千旬反，字或從彳，其音同耳。」","sentenceOrder":2},
  {"id":"s_work_han_thu_118_3","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「黃髮，老稱，謂白髮盡落，更生黃者。」","sentenceOrder":3},
  {"id":"s_work_han_thu_118_4","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「朝見之禮。」","sentenceOrder":4},
  {"id":"s_work_han_thu_118_5","chapterId":"ch_work_han_thu_118","textTraditional":"六月，更授諸侯茅土於明堂，曰：「予制作地理，建封五等，考之經藝，合之傳記，通於義理，論之思之，至於再三，自始建國之元以來九年于茲，乃今定矣。予親設文石之平，陳菁茅四色之土，〔一〕欽告于岱宗泰社后土、先祖先妣，以班授之。〔二〕各就厥國，養牧民人，用成功業。其在緣邊，若江南，非詔所召，遣侍于帝城者，納言掌貨大夫且調都內故錢，予其祿，〔三〕公歲八十萬，侯伯四十萬，子男二十萬。」然復不能盡得。莽好空言，慕古法，多封爵人，性實遴嗇，〔四〕託以地理未定，故且先賦茅土，用慰喜封者。","sentenceOrder":5},
  {"id":"s_work_han_thu_118_6","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「尚書禹貢『苞匭菁茅』，儒者以為菁，菜名也，茅，三脊茅也。而莽此言以菁茅為一物，則是謂善茅為菁茅也。土有五色，而此云四者，中央之土不以封也。菁音精。」","sentenceOrder":6},
  {"id":"s_work_han_thu_118_7","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「欽，敬也。班，布也。」","sentenceOrder":7},
  {"id":"s_work_han_thu_118_8","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「調謂發取之，音徒釣反。次下亦同。」","sentenceOrder":8},
  {"id":"s_work_han_thu_118_9","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「遴讀與吝同。」","sentenceOrder":9},
  {"id":"s_work_han_thu_118_10","chapterId":"ch_work_han_thu_118","textTraditional":"是歲，復明六筦之令。每一筦下，為設科條防禁，犯者罪至死，吏民抵罪者浸眾。又一切調上公以下諸有奴婢者，率一口出錢三千六百，天下愈愁，盜賊起。納言馮常以六筦諫，莽大怒，免常官。置執法左右刺姦。選用能吏侯霸等分督六尉、六隊，〔一〕如漢刺史，與三公士郡一人從事。","sentenceOrder":10},
  {"id":"s_work_han_thu_118_11","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「督，察也。隊音遂。」","sentenceOrder":11},
  {"id":"s_work_han_thu_118_12","chapterId":"ch_work_han_thu_118","textTraditional":"臨淮瓜田儀等為盜賊，依阻會稽長州，〔一〕琅邪女子呂母亦起。初，呂母子為縣吏，為宰所冤殺。〔二〕母散家財，以酤酒買兵弩，〔三〕陰厚貧窮少年，得百餘人，遂攻海曲縣，殺其宰以祭子墓。引兵入海，其眾浸多，後皆萬數。莽遣使者即赦盜賊，還言「盜賊解，輒復合。問其故，皆曰愁法禁煩苛，不得舉手。力作所得，不足以給貢稅。閉門自守，又坐鄰伍鑄錢挾銅，姦吏因以愁民。民窮，悉起為盜賊。」莽大怒，免之。其或順指，言「民驕黠當誅」，及言「時運適然，且滅不久」，莽說，輒遷之。〔四〕","sentenceOrder":12},
  {"id":"s_work_han_thu_118_13","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　服虔曰：「姓瓜田，名儀。」師古曰：「長州即枚乘所云長州之苑。」","sentenceOrder":13},
  {"id":"s_work_han_thu_118_14","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「宰，縣令。」","sentenceOrder":14},
  {"id":"s_work_han_thu_118_15","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「酤音姑。」","sentenceOrder":15},
  {"id":"s_work_han_thu_118_16","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「說讀曰悅。」","sentenceOrder":16},
  {"id":"s_work_han_thu_118_17","chapterId":"ch_work_han_thu_118","textTraditional":"是歲八月，莽親之南郊，鑄作威斗。威斗者，以五石銅為之〔一〕，若北斗，長二尺五寸，欲以厭勝眾兵。〔二〕既成，令司命負之，莽出在前，入在御旁。鑄斗日，大寒，百官人馬有凍死者。","sentenceOrder":17},
  {"id":"s_work_han_thu_118_18","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　李奇曰：「以五色藥石及銅為之。」蘇林曰：「以五色銅礦冶之。」師古曰：「李說是也。若今作鍮石之為。」","sentenceOrder":18},
  {"id":"s_work_han_thu_118_19","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「厭音一葉反。」","sentenceOrder":19},
  {"id":"s_work_han_thu_118_20","chapterId":"ch_work_han_thu_118","textTraditional":"五年正月朔，北軍南門災。","sentenceOrder":20},
  {"id":"s_work_han_thu_118_21","chapterId":"ch_work_han_thu_118","textTraditional":"以大司馬司允費興為荊州牧，見，問到部方略，興對曰：「荊、揚之民率依阻山澤，以漁采為業。〔一〕間者，國張六筦，稅山澤，妨奪民之利，連年久旱，百姓飢窮，故為盜賊。興到部，欲令明曉告盜賊歸田里，假貸犁牛種食，〔二〕闊其租賦，〔三〕幾可以解釋安集。」〔四〕莽怒，免興官。","sentenceOrder":21},
  {"id":"s_work_han_thu_118_22","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「漁謂捕魚也。采謂采取蔬果之屬。」","sentenceOrder":22},
  {"id":"s_work_han_thu_118_23","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「貸音土戴反。」","sentenceOrder":23},
  {"id":"s_work_han_thu_118_24","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「闊，寬也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_118_25","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「幾讀曰冀。」","sentenceOrder":25},
  {"id":"s_work_han_thu_118_26","chapterId":"ch_work_han_thu_118","textTraditional":"天下吏以不得奉祿，並為姦利，郡尹縣宰家累千金。莽下詔曰：「詳考始建國二年胡虜猾夏以來，諸軍吏及緣邊吏大夫以上為姦利增產致富者，收其家所有財產五分之四，以助邊急。」公府士馳傳天下，考覆貪饕，〔一〕開吏告其將，奴婢告其主，幾以禁姦，〔二〕姦愈甚。","sentenceOrder":26},
  {"id":"s_work_han_thu_118_27","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「傳音張戀反。饕音吐高反。」","sentenceOrder":27},
  {"id":"s_work_han_thu_118_28","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「幾讀曰冀。」","sentenceOrder":28},
  {"id":"s_work_han_thu_118_29","chapterId":"ch_work_han_thu_118","textTraditional":"皇孫功崇公宗坐自畫容貌，被服天子衣冠，刻印三：一曰「維祉冠存己夏處南山臧薄冰」，〔一〕二曰「肅聖寶繼」，〔二〕三曰「德封昌圖」。〔三〕又宗舅呂寬家前徙合浦，私與宗通，發覺按驗，宗自殺。莽曰：「宗屬為皇孫，爵為上公，知寬等叛逆族類，而與交通；刻銅印三，文意甚害，不知厭足，窺欲非望。春秋之義，『君親毋將，將而誅焉。』〔四〕迷惑失道，自取此辜，烏呼哀哉！宗本名會宗，以制作去二名，今復名會宗。貶厥爵，改厥號，賜諡為功崇繆伯，以諸伯之禮葬于故同穀城郡。」〔五〕宗姊妨為衛將軍王興夫人，祝詛姑，殺婢以絕口。事發覺，莽使中常侍{帶足}惲責問妨，〔六〕并以責興，皆自殺。事連及司命孔仁妻，亦自殺。仁見莽免冠謝，莽使尚書劾仁：「乘乾車，駕巛馬，左蒼龍，右白虎，前朱雀，後玄武，右杖威節，左負威斗，號曰赤星，非以驕仁，乃以尊新室之威命也。仁擅免天文冠，大不敬。」有詔勿劾，更易新冠。其好怪如此。〔七〕","sentenceOrder":29},
  {"id":"s_work_han_thu_118_30","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　文穎曰：「祉，福祚也。冠存己，欲襲代也。」應劭曰：「夏處南山，就陰涼也。臧薄冰，亦以除暑也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_118_31","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　應劭曰：「莽自謂承聖舜後，能肅敬，得天寶龜以立。宗欲繼其緒。」","sentenceOrder":31},
  {"id":"s_work_han_thu_118_32","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　蘇林曰：「宗自言以德見封，當遂昌熾，受天下圖籍。」","sentenceOrder":32},
  {"id":"s_work_han_thu_118_33","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「春秋公羊傳之辭也。以公子牙將為殺逆而誅之，故云然也。親謂父母也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_118_34","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「同者，宗所封一同之地。」","sentenceOrder":34},
  {"id":"s_work_han_thu_118_35","chapterId":"ch_work_han_thu_118","textTraditional":"〔六〕　師古曰：「{帶足}音帶，又音徒蓋反。」","sentenceOrder":35},
  {"id":"s_work_han_thu_118_36","chapterId":"ch_work_han_thu_118","textTraditional":"〔七〕　師古曰：「言莽性好為鬼神怪異之事。」","sentenceOrder":36},
  {"id":"s_work_han_thu_118_37","chapterId":"ch_work_han_thu_118","textTraditional":"以直道侯王涉為衛將軍。涉者，曲陽侯根子也。根，成帝世為大司馬，薦莽自代，莽恩之，〔一〕以為曲陽非令稱，〔二〕乃追諡根曰直道讓公，涉嗣其爵。","sentenceOrder":37},
  {"id":"s_work_han_thu_118_38","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「懷其舊恩也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_118_39","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「令，善也。曲陽之名，非善稱也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_118_40","chapterId":"ch_work_han_thu_118","textTraditional":"是歲，赤眉力子都、樊崇等以饑饉相聚，起於琅邪，轉鈔掠，眾皆萬數。遣使者發郡國兵擊之，不能克。","sentenceOrder":40},
  {"id":"s_work_han_thu_118_41","chapterId":"ch_work_han_thu_118","textTraditional":"六年春，莽見盜賊多，乃令太史推三萬六千歲曆紀，六歲一改元，布天下。下書曰：「紫閣圖曰『太一、黃帝皆僊上天，〔一〕張樂崑崙虔山之上。後世聖主得瑞者，當張樂秦終南山之上。』〔二〕予之不敏，奉行未明，乃今諭矣。復以寧始將軍為更始將軍，以順符命。易不云乎？『日新之謂盛德，生生之謂易。』〔三〕予其饗哉！」欲以誑燿百姓，銷解盜賊。眾皆笑之。","sentenceOrder":41},
  {"id":"s_work_han_thu_118_42","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「僊，古仙字。上，升也。」","sentenceOrder":42},
  {"id":"s_work_han_thu_118_43","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　服虔曰：「長安南山，詩所謂終南，故秦地，故言秦也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_118_44","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　李奇曰：「易道生諸當生者也。」師古曰：「下繫之辭。體化合變，故曰日新。」","sentenceOrder":44},
  {"id":"s_work_han_thu_118_45","chapterId":"ch_work_han_thu_118","textTraditional":"初獻新樂於明堂、太廟。群臣始冠麟韋之弁。〔一〕或聞其樂聲，曰：「清厲而哀，非興國之聲也。」","sentenceOrder":45},
  {"id":"s_work_han_thu_118_46","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　李奇曰：「鹿皮冠。」","sentenceOrder":46},
  {"id":"s_work_han_thu_118_47","chapterId":"ch_work_han_thu_118","textTraditional":"是時，關東饑旱數年，力子都等黨眾浸多。〔一〕更始將軍廉丹擊益州不能克，徵還。更遣復位後大司馬護軍郭興、庸部牧李曅擊蠻夷若豆等，太傅犧叔士孫喜清潔江湖之盜賊。而匈奴寇邊甚。莽乃大募天下丁男及死罪囚、吏民奴，名曰豬突豨勇，以為銳卒。一切稅天下吏民，訾三十取一，縑帛皆輸長安。令公卿以下至郡縣黃綬皆保養軍馬，〔二〕多少各以秩為差。又博募有奇技術可以攻匈奴者，將待以不次之位。言便宜者以萬數：或言能度水不用舟楫，〔三〕連馬接騎，濟百萬師；或言不持斗糧，服食藥物，三軍不飢；或言能飛，一日千里，可窺匈奴。莽輒試之，取大鳥翮為兩翼，〔四〕頭與身皆著毛，通引環紐，飛數百步墮。莽知其不可用，苟欲獲其名，皆拜為理軍，賜以車馬，待發。","sentenceOrder":47},
  {"id":"s_work_han_thu_118_48","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「浸，漸也。」","sentenceOrder":48},
  {"id":"s_work_han_thu_118_49","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「保者，言不許其有死失。」","sentenceOrder":49},
  {"id":"s_work_han_thu_118_50","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「楫，所以刺舟也，音集，其字從木。」","sentenceOrder":50},
  {"id":"s_work_han_thu_118_51","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「羽本曰翮，音胡隔反。」","sentenceOrder":51},
  {"id":"s_work_han_thu_118_52","chapterId":"ch_work_han_thu_118","textTraditional":"初，匈奴右骨都侯須卜當，其妻王昭君女也，嘗內附。莽遣昭君兄子和親侯王歙誘呼（嘗）〔當〕至塞下，脅將詣長安，強立以為須卜善于後安公。〔一〕始欲誘迎當，大司馬嚴尤諫曰：「當在匈奴右部，兵不侵邊，單于動靜，輒語中國，此方面之大助也。于今迎當置長安槁街，一胡人耳，〔二〕不如在匈奴有益。」莽不聽。既得當，欲遣尤與廉丹擊匈奴，皆賜姓徵氏，號二徵將軍，當誅單于輿而立當代之。〔三〕出車城西橫廄，未發。尤素有智略，非莽攻伐西夷，數諫不從，著古名將樂毅、白起不用之意及言邊事凡三篇，奏以風諫莽。〔四〕及當出廷議，尤固言匈奴可且以為後，先憂山東盜賊。莽大怒，乃策尤曰：「視事四年，蠻夷猾夏不能遏絕，寇賊姦宄不能殄滅，不畏天威，不用詔命，貌佷自臧，持必不移，〔五〕懷執異心，非沮軍議。〔六〕未忍致于理，其上大司馬武建伯印韍，〔七〕歸故郡。」以降符伯董忠為大司馬。","sentenceOrder":52},
  {"id":"s_work_han_thu_118_53","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「善于者，匈奴之號也。後安公者，中國之爵。兩加之。」","sentenceOrder":53},
  {"id":"s_work_han_thu_118_54","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「槁街，蠻夷館所在也，解在陳湯傳。槁音工早反。」","sentenceOrder":54},
  {"id":"s_work_han_thu_118_55","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「輿者，時見為單于之名。」","sentenceOrder":55},
  {"id":"s_work_han_thu_118_56","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「風讀曰諷。」","sentenceOrder":56},
  {"id":"s_work_han_thu_118_57","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「皃，古貌字也。貌佷，言其佷戾見於容貌也。臧，善也。自以為善，而固持其所見，不可移易。」","sentenceOrder":57},
  {"id":"s_work_han_thu_118_58","chapterId":"ch_work_han_thu_118","textTraditional":"〔六〕　師古曰：「沮，壞也，音材汝反。」","sentenceOrder":58},
  {"id":"s_work_han_thu_118_59","chapterId":"ch_work_han_thu_118","textTraditional":"〔七〕　師古曰：「韍者，印之組。」","sentenceOrder":59},
  {"id":"s_work_han_thu_118_60","chapterId":"ch_work_han_thu_118","textTraditional":"翼平連率田況奏郡縣訾民不實，〔一〕莽復三十稅一。以況忠言憂國，進爵為伯，賜錢二百萬。眾庶皆詈之。青、徐民多棄鄉里流亡，老弱死道路，壯者入賊中。","sentenceOrder":60},
  {"id":"s_work_han_thu_118_61","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「舉百姓貲財，不以實數。」","sentenceOrder":61},
  {"id":"s_work_han_thu_118_62","chapterId":"ch_work_han_thu_118","textTraditional":"夙夜連率韓博上言：「有奇士，長丈，大十圍，來至臣府，曰欲奮擊胡虜。自謂巨毋霸，出於蓬萊東南，五城西北昭如海瀕，〔一〕軺車不能載，三馬不能勝。即日以大車四馬，建虎旗，載霸詣闕。霸臥則枕鼓，以鐵箸食，此皇天所以輔新室也。願陛下作大甲高車，賁育之衣，遣大將一人與虎賁百人迎之於道。京師門戶不容者，開高大之，以視百蠻，〔二〕鎮安天下。」博意欲以風莽。〔三〕莽聞惡之，留霸在所新豐，〔四〕更其姓曰巨母氏，謂因文母太后而霸王符也。〔五〕徵博下獄，以非所宜言，棄市。","sentenceOrder":62},
  {"id":"s_work_han_thu_118_63","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「昭如，海名也。瀕，涯也，音頻，又音賓。」","sentenceOrder":63},
  {"id":"s_work_han_thu_118_64","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　晉灼曰：「視音曰示。」","sentenceOrder":64},
  {"id":"s_work_han_thu_118_65","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　晉灼曰：「諷言毋得篡盜而霸。」","sentenceOrder":65},
  {"id":"s_work_han_thu_118_66","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「在所，謂其見到之處。」","sentenceOrder":66},
  {"id":"s_work_han_thu_118_67","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「莽字巨君，若言文母出此人，使我致霸王。」","sentenceOrder":67},
  {"id":"s_work_han_thu_118_68","chapterId":"ch_work_han_thu_118","textTraditional":"明年改元曰地皇，從三萬六千歲曆號也。","sentenceOrder":68},
  {"id":"s_work_han_thu_118_69","chapterId":"ch_work_han_thu_118","textTraditional":"地皇元年正月乙未，赦天下。下書曰：「方出軍行師，敢有趨讙犯法者，輒論斬，毋須時，〔一〕盡歲止。」〔二〕於是春夏斬人都市，百姓震懼，道路以目。","sentenceOrder":69},
  {"id":"s_work_han_thu_118_70","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「趨讙，謂趨走而讙譁也。須，待也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_118_71","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「至此歲盡而止。」","sentenceOrder":71},
  {"id":"s_work_han_thu_118_72","chapterId":"ch_work_han_thu_118","textTraditional":"二月壬申，日正黑。莽惡之，下書曰：「乃者日中見昧，陰薄陽，黑氣為變，百姓莫不驚怪。兆域大將軍王匡遣吏考問上變事者，欲蔽上之明，是以適見于天，〔一〕以正于理，塞大異焉。」","sentenceOrder":72},
  {"id":"s_work_han_thu_118_73","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「適音謫。謫，責也，音徒厄反。見音胡電反。」","sentenceOrder":73},
  {"id":"s_work_han_thu_118_74","chapterId":"ch_work_han_thu_118","textTraditional":"莽見四方盜賊多，復欲厭之，〔一〕又下書曰：「予之皇初祖考黃帝定天下，將兵為上將軍，建華蓋，立斗獻，〔二〕內設大將，外置大司馬五人，大將軍二十五人，偏將軍百二十五人，裨將軍千二百五十人，校尉萬二千五百人，司馬三萬七千五百人，候十一萬二千五百人，當百二十二萬五千人，〔三〕士吏四十五萬人，士千三百五十萬人，〔四〕應協於易『弧矢之利，以威天下』。〔五〕予受符命之文，稽前人，將條備焉。」〔六〕於是置前後左右中大司馬之位，賜諸州牧號為大將軍，郡卒正、連帥、大尹為偏將軍，屬令長裨將軍，縣宰為校尉。乘傳使者經歷郡國，日且十輩，〔七〕倉無見穀〔八〕以給，傳車馬不能足，賦取道中車馬，〔九〕取辦於民。","sentenceOrder":74},
  {"id":"s_work_han_thu_118_75","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「厭音一葉反。」","sentenceOrder":75},
  {"id":"s_work_han_thu_118_76","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「獻音犧。謂斗魁及杓末，如勺之形也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_118_77","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　晉灼曰：「當亦官名也。」師古曰：「當百，官名，百非其數。」","sentenceOrder":77},
  {"id":"s_work_han_thu_118_78","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　晉灼曰：「自五大司馬至此皆以五乘之也。」師古曰：「晉說非也。從上計之，或五或十，或兩或三。」","sentenceOrder":78},
  {"id":"s_work_han_thu_118_79","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「易下繫辭曰：『弦木為弧，剡木為矢，弧矢之利，以威天下。』言所立將率，以合此意。木弓曰弧。」","sentenceOrder":79},
  {"id":"s_work_han_thu_118_80","chapterId":"ch_work_han_thu_118","textTraditional":"〔六〕　師古曰：「稽，考也，考法於前人也。」","sentenceOrder":80},
  {"id":"s_work_han_thu_118_81","chapterId":"ch_work_han_thu_118","textTraditional":"〔七〕　師古曰：「傳音張戀反。次下亦同。」","sentenceOrder":81},
  {"id":"s_work_han_thu_118_82","chapterId":"ch_work_han_thu_118","textTraditional":"〔八〕　師古曰：「見謂見在也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_118_83","chapterId":"ch_work_han_thu_118","textTraditional":"〔九〕　師古曰：「於道中行者，即執取之，以充事也。」","sentenceOrder":83},
  {"id":"s_work_han_thu_118_84","chapterId":"ch_work_han_thu_118","textTraditional":"七月，大風毀王路堂。復下書曰：「乃壬午餔時，有列風雷雨發屋折木之變，〔一〕予甚弁焉，予甚栗焉，予甚恐焉。〔二〕伏念一旬，迷乃解矣。〔三〕昔符命文立安為新遷王，〔四〕臨國雒陽，為統義陽王。是時予在攝假，謙不敢當，而以為公。其後金匱文至，議者皆曰：『臨國雒陽為統，謂據土中為新室統也，宜為皇太子。』自此後，臨久病，雖瘳不平，朝見挈茵輿行。〔五〕見王路堂者，張於西廂及後閣更衣中，〔六〕又以皇后被疾，臨且去本就舍，妃妾在東永巷。〔七〕壬午，列風毀王路西廂及後閣更衣中室。昭寧堂池東南榆樹大十圍，東僵，擊東閣，閣即東永巷之西垣也。皆破折瓦壞，發屋拔木，予甚驚焉。又候官奏月犯心前星，厥有占，予甚憂之。伏念紫閣圖文，太一、黃帝皆得瑞以僊，後世褒主當登終南山。〔八〕所謂新遷王者，乃太一新遷之後也。〔九〕統義陽王乃用五統以禮義登陽上遷之後也。臨有兄而稱太子，名不正。宣尼公曰：『名不正，則言不順，至於刑罰不中，民無錯手足。』〔一０〕惟即位以來，陰陽未和，風雨不時，數遇枯旱蝗螟為災，穀稼鮮耗，百姓苦飢，〔一一〕蠻夷猾夏，寇賊姦宄，人民正營，無所錯手足。〔一二〕深惟厥咎，在名不正焉。其立安為新遷王，臨為統義陽王，幾以保全二子〔一三〕，子孫千億，外攘四夷，內安中國焉。」","sentenceOrder":84},
  {"id":"s_work_han_thu_118_85","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「列風，暴列之風。」","sentenceOrder":85},
  {"id":"s_work_han_thu_118_86","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「弁，疾也。一曰弁，撫手也，言驚懼也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_118_87","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「先言列風雷雨，後言迷乃解矣，蓋取舜『納于大麓，列風雷雨不迷』以為言也。」","sentenceOrder":87},
  {"id":"s_work_han_thu_118_88","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　服虔曰：「安，莽第三子也。遷音仙。莽改汝南新蔡曰新遷。」師古曰：「遷猶僊耳，不勞假借音。」","sentenceOrder":88},
  {"id":"s_work_han_thu_118_89","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　服虔曰：「有疾以執茵輿之行也。」晉灼曰：「漢儀注皇后、婕妤乘輦，餘者以茵，四人舉以行。豈今之板輿而鋪茵乎？」師古曰：「晉說非也。此直謂坐茵褥之上，而令四人對舉茵之四角，輿而行，何謂板輿乎？」","sentenceOrder":89},
  {"id":"s_work_han_thu_118_90","chapterId":"ch_work_han_thu_118","textTraditional":"〔六〕　李奇曰：「張，帳也。」晉灼曰：「更衣中，謂朝賀易衣服處，室屋名也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_118_91","chapterId":"ch_work_han_thu_118","textTraditional":"〔七〕　師古曰：「言臨侍疾，故去其本所居，而來就此止息，是以妃妾在東永巷也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_118_92","chapterId":"ch_work_han_thu_118","textTraditional":"〔八〕　李奇曰：「褒主，大主也。」","sentenceOrder":92},
  {"id":"s_work_han_thu_118_93","chapterId":"ch_work_han_thu_118","textTraditional":"〔九〕　服虔曰：「太一、黃帝欲令安追繼其後也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_118_94","chapterId":"ch_work_han_thu_118","textTraditional":"〔一０〕師古曰：「論語載孔子對子路之言。錯，安置也，音千故反。莽追諡孔子為褒成宣尼公。」","sentenceOrder":94},
  {"id":"s_work_han_thu_118_95","chapterId":"ch_work_han_thu_118","textTraditional":"〔一一〕師古曰：「鮮，少也。耗，虛也。鮮音先踐反。耗音火到反。」","sentenceOrder":95},
  {"id":"s_work_han_thu_118_96","chapterId":"ch_work_han_thu_118","textTraditional":"〔一二〕師古曰：「正營，惶恐不安之意也。正音征。」","sentenceOrder":96},
  {"id":"s_work_han_thu_118_97","chapterId":"ch_work_han_thu_118","textTraditional":"〔一三〕師古曰：「幾讀曰冀。」","sentenceOrder":97},
  {"id":"s_work_han_thu_118_98","chapterId":"ch_work_han_thu_118","textTraditional":"是月，杜陵便殿乘輿虎文衣廢臧在室匣中者〔一〕出，自樹立外堂上，〔二〕良久乃委地。吏卒見者以聞，莽惡之，下書曰：「寶黃廝赤，〔三〕其令郎從官皆衣絳。」","sentenceOrder":98},
  {"id":"s_work_han_thu_118_99","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「匣，匱也，音狎。」","sentenceOrder":99},
  {"id":"s_work_han_thu_118_100","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「樹，豎也。」","sentenceOrder":100},
  {"id":"s_work_han_thu_118_101","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　服虔曰：「以黃為寶，自用其行氣也。廝赤，廝役賤者皆衣赤，賤漢行也。」","sentenceOrder":101},
  {"id":"s_work_han_thu_118_102","chapterId":"ch_work_han_thu_118","textTraditional":"望氣為數者多言有土功象，莽又見四方盜賊多，欲視為自安能建萬世之基者，〔一〕乃下書曰：「予受命遭陽九之厄，百六之會，府帑空虛，百姓匱乏，宗廟未修，且祫祭於明堂太廟，夙夜永念，非敢寧息。深惟吉昌莫良於今年，予乃卜波水之北，郎池之南，惟玉食。〔二〕予又卜金水之南，明堂之西，亦惟玉食。予將（新）〔親〕築焉。」於是遂營長安城南，提封百頃。九月甲申，莽立載行視，〔四〕親舉築三下。司徒王尋、大司空王邑持節，及侍中常侍執法杜林等數十人將作。〔五〕崔發、張邯說莽曰：「德盛者文縟，〔六〕宜崇其制度，宣視海內，〔七〕且令萬世之後無以復加也。」莽乃博徵天下工匠諸圖畫，以望法度算，及吏民以義入錢穀助作者，駱驛道路。〔八〕壞徹城西苑中建章、承光、包陽、大臺、儲元宮及平樂、當路、陽祿館，凡十餘所，〔九〕取其材瓦，以起九廟。是月，大雨六十餘日。令民入米六百斛為郎，其郎吏增秩賜爵至附城。九廟：一曰黃帝太初祖廟，二曰帝虞始祖昭廟，三曰陳胡王統祖穆廟，四曰齊敬王世祖昭廟，五曰濟北愍王王祖穆廟，凡五廟不墮云；〔一０〕六曰濟南伯王尊禰昭廟，七曰元城孺王尊禰穆廟，八曰陽平頃王戚禰昭廟，九曰新都顯王戚禰穆廟。殿皆重屋。太初祖廟東西南北各四十丈，高十七丈，餘廟半之。為銅薄櫨，〔一一〕飾以金銀琱文，〔一二〕窮極百工之巧。帶高增下，〔一三〕功費數百鉅萬，卒徒死者萬數。","sentenceOrder":102},
  {"id":"s_work_han_thu_118_103","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「視音示。」","sentenceOrder":103},
  {"id":"s_work_han_thu_118_104","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　劉德曰：「長安南也。」晉灼曰：「黃圖波、浪，二水名也，在甘泉苑中。」師古曰：「晉說非也。黃圖有西波池、郎池，皆在石城南上林中。玉食，謂龜為玉兆之文而墨食也。波音（波）〔彼〕皮反。」","sentenceOrder":104},
  {"id":"s_work_han_thu_118_105","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「蓋所謂金水之南，明堂之西。」","sentenceOrder":105},
  {"id":"s_work_han_thu_118_106","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「立載謂立而乘車也。行音下更反。」","sentenceOrder":106},
  {"id":"s_work_han_thu_118_107","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「將領築作之人。」","sentenceOrder":107},
  {"id":"s_work_han_thu_118_108","chapterId":"ch_work_han_thu_118","textTraditional":"〔六〕　師古曰：「文，禮文也。縟，繁也，音辱。」","sentenceOrder":108},
  {"id":"s_work_han_thu_118_109","chapterId":"ch_work_han_thu_118","textTraditional":"〔七〕　師古曰：「視讀曰示。」","sentenceOrder":109},
  {"id":"s_work_han_thu_118_110","chapterId":"ch_work_han_thu_118","textTraditional":"〔八〕　師古曰：「駱驛，言不絕。」","sentenceOrder":110},
  {"id":"s_work_han_thu_118_111","chapterId":"ch_work_han_thu_118","textTraditional":"〔九〕　師古曰：「自建章以下至陽祿，皆上林苑中館。」","sentenceOrder":111},
  {"id":"s_work_han_thu_118_112","chapterId":"ch_work_han_thu_118","textTraditional":"〔一０〕師古曰：「墮，毀也，音火規反。」","sentenceOrder":112},
  {"id":"s_work_han_thu_118_113","chapterId":"ch_work_han_thu_118","textTraditional":"〔一一〕師古曰：「薄櫨，柱上枅，即今所謂〈木沓〉也。櫨音盧。」","sentenceOrder":113},
  {"id":"s_work_han_thu_118_114","chapterId":"ch_work_han_thu_118","textTraditional":"〔一二〕師古曰：「琱字與彫同。」","sentenceOrder":114},
  {"id":"s_work_han_thu_118_115","chapterId":"ch_work_han_thu_118","textTraditional":"〔一三〕師古曰：「本因高地而建立之，其旁下者更增築。」","sentenceOrder":115},
  {"id":"s_work_han_thu_118_116","chapterId":"ch_work_han_thu_118","textTraditional":"鉅鹿男子馬適求等謀舉燕趙兵以誅莽，〔一〕大司空士王丹發覺以聞。莽遣三公大夫逮治黨與，〔二〕連及郡國豪傑數千人，皆誅死。封丹為輔國侯。","sentenceOrder":116},
  {"id":"s_work_han_thu_118_117","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「馬適，姓也。求，名也。」","sentenceOrder":117},
  {"id":"s_work_han_thu_118_118","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「逮，逮捕之也。已解於上。」","sentenceOrder":118},
  {"id":"s_work_han_thu_118_119","chapterId":"ch_work_han_thu_118","textTraditional":"自莽為不順時令，百姓怨恨，莽猶安之，又下書曰：「惟設此壹切之法以來，常安六鄉巨邑之都，枹鼓稀鳴，盜賊衰少，〔一〕百姓安土，歲以有年，此乃立權之力也。今胡虜未滅誅，蠻僰未絕焚，江湖海澤麻沸，盜賊未盡破殄，〔二〕又興奉宗廟社稷之大作，民眾動搖。今復壹切行此令，盡二年止之，以全元元，救愚姦。」","sentenceOrder":119},
  {"id":"s_work_han_thu_118_120","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「巨，大也。枹，所以擊鼓者也，音孚，其字從木。」","sentenceOrder":120},
  {"id":"s_work_han_thu_118_121","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「麻沸，言如亂麻而沸涌。」","sentenceOrder":121},
  {"id":"s_work_han_thu_118_122","chapterId":"ch_work_han_thu_118","textTraditional":"是歲，罷大小錢，更行貨布，長二寸五分，廣一寸，直貨錢二十五。貨錢徑一寸，重五銖，枚直一。兩品並行。敢盜鑄錢及偏行布貨，伍人知不發舉，皆沒入為官奴婢。〔一〕","sentenceOrder":122},
  {"id":"s_work_han_thu_118_123","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「伍人，同伍之人，若今伍保者也。」","sentenceOrder":123},
  {"id":"s_work_han_thu_118_124","chapterId":"ch_work_han_thu_118","textTraditional":"太傅平晏死，以予虞唐尊為太傅。尊曰：「國虛民貧，咎在奢泰。」乃身短衣小袖，乘牝馬柴車，〔一〕藉槁，瓦器，〔二〕又以歷遺公卿。〔三〕出見男女不異路者，尊自下車，以象刑赭幡汙染其衣。〔四〕莽聞而說之，〔五〕下詔申敕公卿思與厥齊。〔六〕封尊為平化侯。","sentenceOrder":124},
  {"id":"s_work_han_thu_118_125","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「柴車即棧車。」","sentenceOrder":125},
  {"id":"s_work_han_thu_118_126","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「藉槁，去蒲蒻也。瓦器，以瓦為食器。」","sentenceOrder":126},
  {"id":"s_work_han_thu_118_127","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「以瓦器盛食，遺公卿也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_118_128","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「赭幡，以赭汁漬巾幡。」","sentenceOrder":128},
  {"id":"s_work_han_thu_118_129","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「說讀曰悅。」","sentenceOrder":129},
  {"id":"s_work_han_thu_118_130","chapterId":"ch_work_han_thu_118","textTraditional":"〔六〕　師古曰：「令與尊同此操行也。論語稱孔子曰：『見賢思齊，』故莽云然。」","sentenceOrder":130},
  {"id":"s_work_han_thu_118_131","chapterId":"ch_work_han_thu_118","textTraditional":"是時，南郡張霸、江夏羊牧、王匡等起雲杜綠林，號曰下江兵，〔一〕眾皆萬餘人。武功中水鄉民三舍墊為池。〔二〕","sentenceOrder":131},
  {"id":"s_work_han_thu_118_132","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　晉灼曰：「本起江夏雲杜縣，後分西上，入南郡，屯藍田，故號下江兵也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_118_133","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「墊，陷也，音丁念反。」","sentenceOrder":133},
  {"id":"s_work_han_thu_118_134","chapterId":"ch_work_han_thu_118","textTraditional":"二年正月，以州牧位三公，刺舉怠解，〔一〕更置牧監副，秩元士，冠法冠，行事如漢刺史。","sentenceOrder":134},
  {"id":"s_work_han_thu_118_135","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「解讀曰懈。」","sentenceOrder":135},
  {"id":"s_work_han_thu_118_136","chapterId":"ch_work_han_thu_118","textTraditional":"是月，莽妻死，諡曰孝睦皇后，葬渭陵長壽園西，令永侍文母，名陵曰億年。初莽妻以莽數殺其子，涕泣失明，莽令太子臨居中養焉。莽妻旁侍者原碧，莽幸之。後臨亦通焉，恐事泄，謀共殺莽。臨妻愔，國師公女，〔一〕能為星，語臨宮中且有白衣會。臨喜，以為所謀且成。後貶為統義陽王，出在外第，愈憂恐。會莽妻病困，臨予書曰：「上於子孫至嚴，前長孫、中孫年俱三十而死。〔二〕今臣臨復適三十，誠恐一旦不保中室，則不知死命所在！」〔三〕莽侯妻疾，見其書，大怒，疑臨有惡意，不令得會喪。既葬，收原碧等考問，具服姦、謀殺狀。莽欲祕之，使殺案事使者司命從事，埋獄中，家不知所在。賜臨藥，臨不肯飲，自刺死。使侍中票騎將軍同說侯林賜魂衣璽韍，〔四〕策書曰：「符命文立臨為統義陽王，此言新室即位三萬六千歲後，為臨之後者乃當龍陽而起。前過聽議者，以臨為太子，有烈風之變，輒順符命，立為統義陽王。在此之前，自此之後，不作信順，弗蒙厥佑，夭年隕命，嗚呼哀哉！跡行賜諡，諡曰繆王。」又詔國師公：「臨本不知星，事從愔起。」愔亦自殺。","sentenceOrder":136},
  {"id":"s_work_han_thu_118_137","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「愔音一尋反。」","sentenceOrder":137},
  {"id":"s_work_han_thu_118_138","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「中讀曰仲。」","sentenceOrder":138},
  {"id":"s_work_han_thu_118_139","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　李奇曰：「中室，臨之母也。」晉灼曰：「長樂宮中殿也。」師古曰：「二說皆非也。中室，室中也。臨自言欲於室中自保全，不可得耳。」","sentenceOrder":139},
  {"id":"s_work_han_thu_118_140","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「說讀曰悅。」","sentenceOrder":140},
  {"id":"s_work_han_thu_118_141","chapterId":"ch_work_han_thu_118","textTraditional":"是月，新遷王安病死。初，莽為侯就國時，幸侍者增秩、懷能、開明。懷能生男興，增秩生男匡、女曅，開明生女捷，皆留新都國，以其不明故也。〔一〕及安疾甚，莽自病無子，為安作奏，使上言：「興等母雖微賤，屬猶皇子，不可以棄。」章視群公，〔二〕皆曰：「安友于兄弟，〔三〕宜及春夏加封爵。」於是以王車遣使者迎興等，封興為功脩公，匡為功建公，曅為睦脩任，捷為睦逮任。孫公明公壽病死，旬月四喪焉。莽壞漢孝武、孝昭廟，分葬子孫其中。","sentenceOrder":141},
  {"id":"s_work_han_thu_118_142","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「言侍者或與外人私通所生子女，不可分明也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_118_143","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「視讀曰示。以所上之章遍示之。」","sentenceOrder":143},
  {"id":"s_work_han_thu_118_144","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「友，愛也。善兄弟曰友。」","sentenceOrder":144},
  {"id":"s_work_han_thu_118_145","chapterId":"ch_work_han_thu_118","textTraditional":"魏成大尹李焉與卜者王況謀，況謂焉曰：「新室即位以來，民田奴婢不得賣買，數改錢貨，徵發煩數，軍旅騷動，四夷並侵，百姓怨恨，盜賊並起，漢家當復興。君姓李，李音徵，徵火也，〔一〕當為漢輔。」因為焉作讖書，言「文帝發忿，居地下趣軍，北告匈奴，南告越人。〔二〕江中劉信，執敵報怨，復續古先，四年當發軍。江湖有盜，自稱樊王，姓為劉氏，萬人成行，〔三〕不受赦令，欲動秦、雒陽。十一年當相攻，太白揚光，歲星入東井，其號當行。」〔四〕又言莽大臣吉凶，各有日期。會合十餘萬言。焉令吏寫其書，吏亡告之。莽遣使者即捕焉，獄治皆死。","sentenceOrder":145},
  {"id":"s_work_han_thu_118_146","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「徵音竹里反。」","sentenceOrder":146},
  {"id":"s_work_han_thu_118_147","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「趣讀曰促。」","sentenceOrder":147},
  {"id":"s_work_han_thu_118_148","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「行音胡郎反。」","sentenceOrder":148},
  {"id":"s_work_han_thu_118_149","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「號謂號令也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_118_150","chapterId":"ch_work_han_thu_118","textTraditional":"三輔盜賊麻起，〔一〕乃置捕盜都尉官，令執法謁者追擊長安中，建鳴鼓攻賊幡，而使者隨其後。遣太師犧仲景尚、更始將軍護軍王黨將兵擊青、徐，國師和仲曹放助郭興擊句町。轉天下穀幣詣西河、五原、朔方、漁陽，每一郡以百萬數，欲以擊匈奴。","sentenceOrder":150},
  {"id":"s_work_han_thu_118_151","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「言起者如亂麻也。」","sentenceOrder":151},
  {"id":"s_work_han_thu_118_152","chapterId":"ch_work_han_thu_118","textTraditional":"秋，隕霜殺菽，關東大饑，蝗。","sentenceOrder":152},
  {"id":"s_work_han_thu_118_153","chapterId":"ch_work_han_thu_118","textTraditional":"民犯鑄錢，伍人相坐，沒入為官奴婢。其男子檻車，兒女子步，以鐵鎖琅當其頸，傳詣鍾官，以十萬數。〔一〕到者易其夫婦，〔二〕愁苦死者什六七。孫喜、景尚、曹放等擊賊不能克，軍師放縱，百姓重困。〔三〕","sentenceOrder":153},
  {"id":"s_work_han_thu_118_154","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「琅當，長鎖也。鍾官，主鑄錢之官也。」","sentenceOrder":154},
  {"id":"s_work_han_thu_118_155","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「改相配匹，不依其舊也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_118_156","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「重音直用反。」","sentenceOrder":156},
  {"id":"s_work_han_thu_118_157","chapterId":"ch_work_han_thu_118","textTraditional":"莽以王況讖言荊楚當興，李氏為輔，欲厭之，〔一〕乃拜侍中掌牧大夫李棽為大將軍、揚州牧，賜名聖，〔二〕使將兵奮擊。","sentenceOrder":157},
  {"id":"s_work_han_thu_118_158","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「厭音一葉反。」","sentenceOrder":158},
  {"id":"s_work_han_thu_118_159","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「改其舊名，以聖代讖。棽音所林反。」","sentenceOrder":159},
  {"id":"s_work_han_thu_118_160","chapterId":"ch_work_han_thu_118","textTraditional":"上谷儲夏自請願說瓜田儀，〔一〕莽以為中郎，使出儀。〔二〕儀文降，未出而死。〔三〕莽求其尸葬之，為起冢、祠室，諡曰瓜寧殤男，幾以招來其餘，〔四〕然無肯降者。","sentenceOrder":160},
  {"id":"s_work_han_thu_118_161","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　服虔曰：「儲夏，人姓也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_118_162","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「說之令自出。」","sentenceOrder":162},
  {"id":"s_work_han_thu_118_163","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「上文書言降，而身未出。」","sentenceOrder":163},
  {"id":"s_work_han_thu_118_164","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「幾讀曰冀。」","sentenceOrder":164},
  {"id":"s_work_han_thu_118_165","chapterId":"ch_work_han_thu_118","textTraditional":"閏月丙辰，大赦天下，天下大服民私服在詔書前亦釋除。〔一〕","sentenceOrder":165},
  {"id":"s_work_han_thu_118_166","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　張晏曰：「莽妻本以此歲死，天下大服也。私服，自喪其親。皆除之。」","sentenceOrder":166},
  {"id":"s_work_han_thu_118_167","chapterId":"ch_work_han_thu_118","textTraditional":"郎陽成脩獻符命，言繼立民母，又曰：「黃帝以百二十女致神僊。」莽於是遣中散大夫、謁者各四十五人分行天下，〔一〕博采鄉里所高有淑女者上名。","sentenceOrder":167},
  {"id":"s_work_han_thu_118_168","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「行音下更反。」","sentenceOrder":168},
  {"id":"s_work_han_thu_118_169","chapterId":"ch_work_han_thu_118","textTraditional":"莽夢長樂宮銅人五枚起立，莽惡之，念銅人銘有「皇帝初兼天下」之文，即使尚方工鐫滅所夢銅人膺文。〔一〕又感漢高廟神靈〔二〕，遣虎賁武士入高廟，拔劍四面提擊，〔三〕斧壞戶牖，〔四〕桃湯赭鞭鞭灑屋壁，〔五〕令輕車校尉居其中，又令中軍北壘居高寢。〔六〕","sentenceOrder":169},
  {"id":"s_work_han_thu_118_170","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「鐫，鑿也，音子全反。」","sentenceOrder":170},
  {"id":"s_work_han_thu_118_171","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「謂夢見譴責。」","sentenceOrder":171},
  {"id":"s_work_han_thu_118_172","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「提，擲也，音徒計反。」","sentenceOrder":172},
  {"id":"s_work_han_thu_118_173","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「以斧斫壞之。」","sentenceOrder":173},
  {"id":"s_work_han_thu_118_174","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「桃湯灑之，赭鞭鞭之也。赭，赤也。」","sentenceOrder":174},
  {"id":"s_work_han_thu_118_175","chapterId":"ch_work_han_thu_118","textTraditional":"〔六〕　師古曰：「徙北軍壘之兵士於高廟寢中屯居也。」","sentenceOrder":175},
  {"id":"s_work_han_thu_118_176","chapterId":"ch_work_han_thu_118","textTraditional":"或言黃帝時建華蓋以登僊，莽乃造華蓋九重，高八丈一尺，金瑵羽葆，〔一〕載以祕機四輪車，〔二〕駕六馬，力士三百人黃衣幘，車上人擊鼓，輓者皆呼「登僊」。莽出，令在前。百官竊言「此似〈車耎〉車，非僊物也。」〔三〕","sentenceOrder":176},
  {"id":"s_work_han_thu_118_177","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「瑵讀曰爪。謂蓋弓頭為爪形。」","sentenceOrder":177},
  {"id":"s_work_han_thu_118_178","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　服虔曰：「蓋高八丈，其杠皆有屈膝，可上下屈申也。」師古曰：「言潛為機關，不使外見，故曰祕機也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_118_179","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「〈車耎〉車，載喪車，音而。」","sentenceOrder":179},
  {"id":"s_work_han_thu_118_180","chapterId":"ch_work_han_thu_118","textTraditional":"是歲，南郡秦豐眾且萬人。平原女子遲昭平能說（經博）〔博經〕以八投，〔一〕亦聚數千人在河阻中。莽召問群臣禽賊方略，皆曰：「此天囚行尸，命在漏刻。」故左將軍公孫祿徵來與議，〔二〕祿曰：「太史令宗宣典星曆，候氣變，以凶為吉，亂天文，誤朝廷。太傅平化侯飾虛偽以媮名位，『賊夫人之子』。〔三〕國師嘉信公顛倒五經，毀師法，令學士疑惑。明學男張邯、地理侯孫陽造井田，使民棄土業。犧和魯匡設六筦，以窮工商。說符侯崔發阿諛取容，令下情不上通。宜誅此數子以慰天下！」又言：「匈奴不可攻，當與和親。臣恐新室憂不在匈奴，而在封域之中也。」莽怒，使虎賁扶祿出。然頗采其言，左遷魯匡為五原卒正，以百姓怨非故。六筦非匡所獨造，莽厭眾意而出之。〔四〕","sentenceOrder":180},
  {"id":"s_work_han_thu_118_181","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　服虔曰：「博奕經，以八箭投之。」","sentenceOrder":181},
  {"id":"s_work_han_thu_118_182","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「與讀曰豫。」","sentenceOrder":182},
  {"id":"s_work_han_thu_118_183","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「論語稱子路使子羔為費宰，孔子曰『賊夫人之子』，言羔未知政道，而使宰邑，所以為賊害也。故祿引此而言。」","sentenceOrder":183},
  {"id":"s_work_han_thu_118_184","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「厭，滿也，音一豔反。」","sentenceOrder":184},
  {"id":"s_work_han_thu_118_185","chapterId":"ch_work_han_thu_118","textTraditional":"初，四方皆以飢寒窮愁起為盜賊，稍稍群聚，常思歲熟得歸鄉里。眾雖萬數，亶稱巨人、從事、三老、祭酒，〔一〕不敢略有城邑，轉掠求食，日闋而已。〔二〕諸長吏牧守皆自亂鬥中兵而死，〔三〕賊非敢欲殺之也，而莽終不諭其故。〔四〕是歲，大司馬士按章豫州，〔五〕為賊所獲，賊送付縣。士還，上書具言狀。莽大怒，下獄以為誣罔。因下書責七公曰：「夫吏者，理也。宣德明恩，以牧養民，仁之道也。抑強督姦，捕誅盜賊，義之節也。〔六〕今則不然。盜發不輒得，至成群黨，遮略乘傳宰士。〔七〕士得脫者，又妄自言『我責數賊「何故為是？」〔八〕賊曰「以貧窮故耳」。賊護出我。』今俗人議者率多若此。惟貧困飢寒，犯法為非，大者群盜，小者偷穴，不過二科，〔九〕今乃結謀連黨以千百數，是逆亂之大者，豈飢寒之謂邪？七公其嚴敕卿大夫、卒正、連率、庶尹，謹牧養善民，急捕殄盜賊。有不同心并力，疾惡黜賊，而妄曰飢寒所為，輒捕繫，請其罪。」於是群下愈恐，莫敢言賊情者，亦不得擅發兵，賊由是遂不制。","sentenceOrder":185},
  {"id":"s_work_han_thu_118_186","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「亶讀曰但。言不為大號。」","sentenceOrder":186},
  {"id":"s_work_han_thu_118_187","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「闋，盡也。隨日而盡也。闋音空穴反。」","sentenceOrder":187},
  {"id":"s_work_han_thu_118_188","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「中，傷也。」","sentenceOrder":188},
  {"id":"s_work_han_thu_118_189","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「不曉此意也。」","sentenceOrder":189},
  {"id":"s_work_han_thu_118_190","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「有上章相告者，就而按治之。」","sentenceOrder":190},
  {"id":"s_work_han_thu_118_191","chapterId":"ch_work_han_thu_118","textTraditional":"〔六〕　師古曰：「督謂察視也。」","sentenceOrder":191},
  {"id":"s_work_han_thu_118_192","chapterId":"ch_work_han_thu_118","textTraditional":"〔七〕　師古曰：「傳音張戀反。」","sentenceOrder":192},
  {"id":"s_work_han_thu_118_193","chapterId":"ch_work_han_thu_118","textTraditional":"〔八〕　師古曰：「數音所具反。」","sentenceOrder":193},
  {"id":"s_work_han_thu_118_194","chapterId":"ch_work_han_thu_118","textTraditional":"〔九〕　師古曰：「穴謂穿牆為盜也。」","sentenceOrder":194},
  {"id":"s_work_han_thu_118_195","chapterId":"ch_work_han_thu_118","textTraditional":"唯翼平連率田況素果敢，發民年十八以上四萬餘人，授以庫兵，與刻石為約。赤糜聞之，不敢入界。〔一〕況自劾奏，莽讓況：〔二〕「未賜虎符而擅發兵，此弄兵也，厥罪乏興。〔三〕以況自詭必禽滅賊，故且勿治。」〔四〕後況自請出界擊賊，所嚮皆破。莽以璽書令況領青、徐二州牧事。況上言：「盜賊始發，其原甚微，非部吏、伍人所能禽也。咎在長吏不為意，縣欺其郡，郡欺朝廷，實百言十，實千言百。朝廷忽略，不輒督責，遂至延曼連州，〔五〕乃遣將率，多發使者，傳相監趣。〔六〕郡縣力事上官，應塞詰對，〔七〕共酒食，具資用，以救斷斬，〔八〕不給復憂盜賊治官事。〔九〕將率又不能躬率吏士，戰則為賊所破，吏氣寖傷，徒費百姓。〔一０〕前幸蒙赦令，賊欲解散，或反遮擊，恐入山谷轉相告語，故郡縣降賊，皆更驚駭，恐見詐滅，因饑饉易動，旬日之間更十餘萬人，此盜賊所以多之故也。今雒陽以東，米石二千。竊見詔書，欲遣太師、更始將軍，二人爪牙重臣，多從人眾，道上空竭，少則亡以威視遠方。〔一一〕宜急選牧、尹以下，明其賞罰，收合離鄉。小國無城郭者，徙其老弱置大城中，積藏穀食，并力固守。賊來攻城，剛不能下，所過無食，勢不得群聚。如此，招之必降，擊之則滅。今空復多出將率，郡縣苦之，反甚於賊。宜盡徵還乘傳諸使者，以休息郡縣。委任臣況以二州盜賊，必平定之。」莽畏惡況，陰為發代，遣使者賜況璽書。使者至，見況，因令代監其兵。況隨使者西，到，拜為師尉大夫。況去，齊地遂敗。","sentenceOrder":195},
  {"id":"s_work_han_thu_118_196","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「糜，眉也。以朱塗眉，故曰赤眉。古字通用。」","sentenceOrder":196},
  {"id":"s_work_han_thu_118_197","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「讓，責也。」","sentenceOrder":197},
  {"id":"s_work_han_thu_118_198","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「擅發之罪，與乏軍興同科也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_118_199","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「詭，責也。自以乏為憂責。」","sentenceOrder":199},
  {"id":"s_work_han_thu_118_200","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「延音弋戰反。曼與蔓同。」","sentenceOrder":200},
  {"id":"s_work_han_thu_118_201","chapterId":"ch_work_han_thu_118","textTraditional":"〔六〕　師古曰：「趣讀曰促。」","sentenceOrder":201},
  {"id":"s_work_han_thu_118_202","chapterId":"ch_work_han_thu_118","textTraditional":"〔七〕　師古曰：「力，勤也。塞，當也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_118_203","chapterId":"ch_work_han_thu_118","textTraditional":"〔八〕　師古曰：「交懼斬死之刑也。共讀曰供。」","sentenceOrder":203},
  {"id":"s_work_han_thu_118_204","chapterId":"ch_work_han_thu_118","textTraditional":"〔九〕　師古曰：「給，暇也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_118_205","chapterId":"ch_work_han_thu_118","textTraditional":"〔一０〕師古曰：「寖，漸也。」","sentenceOrder":205},
  {"id":"s_work_han_thu_118_206","chapterId":"ch_work_han_thu_118","textTraditional":"〔一一〕師古曰：「視讀曰示。」","sentenceOrder":206},
  {"id":"s_work_han_thu_118_207","chapterId":"ch_work_han_thu_118","textTraditional":"三年正月，九廟蓋構成，納神主。莽謁見，大駕乘六馬，以五采毛為龍文衣，著角，長三尺。〔一〕華蓋車，元戎十乘在前。因賜治廟者司徒、大司空錢各千萬，侍中、中常侍以下皆封。封都匠仇延為邯淡里附城。〔二〕","sentenceOrder":207},
  {"id":"s_work_han_thu_118_208","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「以被馬上也。」","sentenceOrder":208},
  {"id":"s_work_han_thu_118_209","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「都匠，大匠也。邯音胡敢反。淡音大敢反。豐盛之意。」","sentenceOrder":209},
  {"id":"s_work_han_thu_118_210","chapterId":"ch_work_han_thu_118","textTraditional":"二月，霸橋災，數千人以水沃救，不滅。莽惡之，下書曰：「夫三皇象春，五帝象夏，三王象秋，五伯象冬。皇王，德運也；伯者，繼空續乏以成曆數，故其道駮。〔一〕惟常安御道多以所近為名。乃二月癸巳之夜，甲午之辰，火燒霸橋，從東方西行，至甲午夕，橋盡火滅。大司空行視考問，〔二〕或云寒民舍居橋下，〔三〕疑以火自燎，為此災也。〔四〕其明旦即乙未，立春之日也。予以神明聖祖黃虞遺統受命，至于地皇四年為十五年。正以三年終冬絕滅霸駮之橋，欲以興成新室統壹長存之道也。又戒此橋空東方之道。今東方歲荒民飢，道路不通，東岳太師亟科條，〔五〕開東方諸倉，賑貸窮乏，以施仁道。其更名霸館為長存館，霸橋為長存橋。」","sentenceOrder":210},
  {"id":"s_work_han_thu_118_211","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「伯皆讀曰霸。」","sentenceOrder":211},
  {"id":"s_work_han_thu_118_212","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「行音下更反。」","sentenceOrder":212},
  {"id":"s_work_han_thu_118_213","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「舍，止宿也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_118_214","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「燎謂炙令腝也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_118_215","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「亟，急也，音己力反。」","sentenceOrder":215},
  {"id":"s_work_han_thu_118_216","chapterId":"ch_work_han_thu_118","textTraditional":"是月，赤眉殺太師犧仲景尚。關東人相食。","sentenceOrder":216},
  {"id":"s_work_han_thu_118_217","chapterId":"ch_work_han_thu_118","textTraditional":"四月，遣太師王匡、更始將軍廉丹東，〔一〕祖都門外，〔二〕天大雨，霑衣止。長老歎曰：「是為泣軍！」莽曰：「惟陽九之阨，與害氣會，究于去年。枯旱霜蝗，飢饉薦臻，〔三〕百姓困乏，流離道路，于春尤甚，予甚悼之。今使東嶽太師特進褒新侯開東方諸倉，賑貸窮乏。太師公所不過道，分遣大夫謁者並開諸倉，以全元元。太師公因與廉丹大使五威司命位右大司馬更始將軍平均侯之兗州，填撫所掌，〔四〕及青、徐故不軌盜賊未盡解散，後復屯聚者，皆清潔之，期於安兆黎矣。」〔五〕太師、更始合將銳士十餘萬人，所過放縱。東方為之語曰：「寧逢赤眉，不逢太師！太師尚可，更始殺我！」卒如田況之言。","sentenceOrder":217},
  {"id":"s_work_han_thu_118_218","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「東謂東出也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_118_219","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「祖道送匡、丹於都門外。」","sentenceOrder":219},
  {"id":"s_work_han_thu_118_220","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「薦讀曰荐。荐，仍也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_118_221","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「之，往也。填音竹刃反。」","sentenceOrder":221},
  {"id":"s_work_han_thu_118_222","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「黎，眾也。」","sentenceOrder":222},
  {"id":"s_work_han_thu_118_223","chapterId":"ch_work_han_thu_118","textTraditional":"莽又多遣大夫謁者分教民煮草木為酪，酪不可食，重為煩費〔一〕。莽下書曰：「惟民困乏，雖溥開諸倉以賑贍之，〔二〕猶恐未足。其且開天下山澤之防，諸能采取山澤之物而順月令者，其恣聽之，勿令出稅。至地皇三十年如故，是王光上戊之六年也。〔三〕如令豪吏猾民辜而攉之，小民弗蒙，非予意也。〔四〕易不云乎？『損上益下，民說無疆。』〔五〕書云：『言之不從，是謂不艾。』〔六〕咨虖群公，可不憂哉！」〔七〕","sentenceOrder":223},
  {"id":"s_work_han_thu_118_224","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「重音直用反。」","sentenceOrder":224},
  {"id":"s_work_han_thu_118_225","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「溥與普同。」","sentenceOrder":225},
  {"id":"s_work_han_thu_118_226","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　孟康曰：「戊，土也，莽所作曆名。」","sentenceOrder":226},
  {"id":"s_work_han_thu_118_227","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「辜攉謂獨專其利，而令它人犯者得罪辜也。」","sentenceOrder":227},
  {"id":"s_work_han_thu_118_228","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「益卦彖辭也。言損上以益下，則人皆歡悅無窮竟。」","sentenceOrder":228},
  {"id":"s_work_han_thu_118_229","chapterId":"ch_work_han_thu_118","textTraditional":"〔六〕　師古曰：「洪範之言。艾讀曰乂。乂，治也。」","sentenceOrder":229},
  {"id":"s_work_han_thu_118_230","chapterId":"ch_work_han_thu_118","textTraditional":"〔七〕　師古曰：「咨者，歎息之言。」","sentenceOrder":230},
  {"id":"s_work_han_thu_118_231","chapterId":"ch_work_han_thu_118","textTraditional":"是時下江兵盛，新巿朱鮪、平林陳牧等皆復聚眾，攻擊鄉聚。莽遣司命大將軍孔仁部豫州，納言大將軍嚴尤、秩宗大將軍陳茂擊荊州，各從吏士百餘人，乘船從渭入河，至華陰乃出乘傳，到部募士。尤謂茂曰：「遣將不與兵符，必先請而後動，是猶紲韓盧而責之獲也。」〔一〕","sentenceOrder":231},
  {"id":"s_work_han_thu_118_232","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「紲，繫也。韓盧，古韓國之名犬也。黑色曰盧。」","sentenceOrder":232},
  {"id":"s_work_han_thu_118_233","chapterId":"ch_work_han_thu_118","textTraditional":"夏，蝗從東方來，蜚蔽天，〔一〕至長安，入未央宮，緣殿閣。莽發吏民設購賞捕擊。","sentenceOrder":233},
  {"id":"s_work_han_thu_118_234","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「蜚，古飛字也。」","sentenceOrder":234},
  {"id":"s_work_han_thu_118_235","chapterId":"ch_work_han_thu_118","textTraditional":"莽以天下穀貴，欲厭之，〔一〕為大倉，置衛交戟，名曰「政始掖門」。","sentenceOrder":235},
  {"id":"s_work_han_thu_118_236","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「厭音一葉反。」","sentenceOrder":236},
  {"id":"s_work_han_thu_118_237","chapterId":"ch_work_han_thu_118","textTraditional":"流民入關者數十萬人，乃置養贍官稟食之。〔一〕使者監領，與小吏共盜其稟，飢死者十七八。先是，莽使中黃門王業領長安巿買，賤取於民，民甚患之。業以省費為功，賜爵附城。莽聞城中飢饉，以問業。業曰：「皆流民也。」乃巿所賣粱飰肉羹，持入視莽，〔二〕曰：「居民食咸如此。」莽信之。","sentenceOrder":237},
  {"id":"s_work_han_thu_118_238","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「稟，給也。食讀曰飤。」","sentenceOrder":238},
  {"id":"s_work_han_thu_118_239","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「視讀曰示。」","sentenceOrder":239},
  {"id":"s_work_han_thu_118_240","chapterId":"ch_work_han_thu_118","textTraditional":"冬，無鹽索盧恢等舉兵反城。〔一〕廉丹、王匡攻拔之，斬首萬餘級。莽遣中郎將奉璽書勞丹、匡，進爵為公，封吏士有功者十餘人。","sentenceOrder":240},
  {"id":"s_work_han_thu_118_241","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「索盧，姓也。恢，名也。反城，據城以反也。一曰，反音幡。今語賊猶曰幡城。索音先各反。」","sentenceOrder":241},
  {"id":"s_work_han_thu_118_242","chapterId":"ch_work_han_thu_118","textTraditional":"赤眉別校董憲等眾數萬人在梁郡，王匡欲進擊之，廉丹以為新拔城罷勞，〔一〕當且休士養威。匡不聽，引兵獨進，丹隨之。合戰成昌，〔二〕兵敗，匡走。丹使吏持其印韍符節付匡曰：「小兒可走，吾不可！」遂止，戰死。校尉汝雲、王隆等二十餘人別鬥，聞之，皆曰：「廉公已死，吾誰為生？」馳奔賊，皆戰死。〔三〕莽傷之，下書曰：「惟公多擁選士精兵，眾郡駿馬倉穀帑藏皆得自調，〔四〕忽於詔策，離其威節，騎馬呵譟，〔五〕為狂刃所害，烏呼哀哉！賜諡曰果公。」","sentenceOrder":242},
  {"id":"s_work_han_thu_118_243","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「罷讀曰疲。」","sentenceOrder":243},
  {"id":"s_work_han_thu_118_244","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「成昌，地名也。」","sentenceOrder":244},
  {"id":"s_work_han_thu_118_245","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「犇，古奔字也。」","sentenceOrder":245},
  {"id":"s_work_han_thu_118_246","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「謂發取也，音徒釣反。」","sentenceOrder":246},
  {"id":"s_work_han_thu_118_247","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「忽謂怠忘也。譟，群呼也，音先到反。」","sentenceOrder":247},
  {"id":"s_work_han_thu_118_248","chapterId":"ch_work_han_thu_118","textTraditional":"國將哀章謂莽曰：「皇祖考黃帝之時，中黃直為將，破殺蚩尤。今臣居中黃直之位，願平山東。」莽遣章馳東，與太師匡并力。又遣大將軍陽浚守敖倉，司徒王尋將十餘萬屯雒陽填南宮，〔一〕大司馬董忠養士習射中軍北壘，大司空王邑兼三公之職。司徒尋初發長安，宿霸昌廄，〔二〕亡其黃鉞。尋士房揚素狂直，乃哭曰：「此經所謂『喪其齊斧』者也！」〔三〕自劾去。莽擊殺揚。","sentenceOrder":248},
  {"id":"s_work_han_thu_118_249","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「填音竹刃反。」","sentenceOrder":249},
  {"id":"s_work_han_thu_118_250","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「霸昌觀之廄也。三輔黃圖曰在城外也。」","sentenceOrder":250},
  {"id":"s_work_han_thu_118_251","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　應劭曰：「齊，利也。亡其利斧，言無以復斷斬也。」師古曰：「此易巽卦上九爻辭。」","sentenceOrder":251},
  {"id":"s_work_han_thu_118_252","chapterId":"ch_work_han_thu_118","textTraditional":"四方盜賊往往數萬人攻城邑，殺二千石以下。太師王匡等戰數不利。莽知天下潰畔，事窮計迫，乃議遣風俗大夫司國憲等分行天下，〔一〕除井田奴婢山澤六筦之禁，即位以來詔令不便於民者皆收還之。待見未發，會世祖與兄齊武王伯升、宛人李通等〔二〕帥舂陵子弟數千人，招致新巿平林朱鮪、陳牧等合攻拔棘陽。是時嚴尤、陳茂破下江兵，成丹、王常等數千人別走，入南陽界。","sentenceOrder":252},
  {"id":"s_work_han_thu_118_253","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「行音下更反。」","sentenceOrder":253},
  {"id":"s_work_han_thu_118_254","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「世祖謂光武皇帝。」","sentenceOrder":254},
  {"id":"s_work_han_thu_118_255","chapterId":"ch_work_han_thu_118","textTraditional":"十一月，有星孛于張，東南行，五日不見。莽數召問太史令宗宣，諸術數家皆繆對，言天文安善，群賊且滅。莽差以自安。","sentenceOrder":255},
  {"id":"s_work_han_thu_118_256","chapterId":"ch_work_han_thu_118","textTraditional":"四年正月，漢兵得下江王常等以為助兵，擊前隊大夫甄阜、屬正梁丘賜，皆斬之，殺其眾數萬人。初，京師聞青、徐賊眾數十萬人，訖無文號旌旗表識，〔一〕咸怪異之。好事者竊言：「此豈如古三皇無文書號諡邪？」〔二〕莽亦心怪，以問群臣，群臣莫對。唯嚴尤曰：「此不足怪也。自黃帝、湯、武行師，必待部曲旌旗號令，今此無有者，直飢寒群盜，犬羊相聚，不知為之耳。」莽大說，〔三〕群臣盡服。及後漢兵劉伯升起，皆稱將軍，攻城略地，既殺甄阜，移書稱說。莽聞之憂懼。","sentenceOrder":256},
  {"id":"s_work_han_thu_118_257","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「文謂文章；號謂大位號也。一曰，號謂號令也。識讀與幟同，音（忒）〔式〕志反。」","sentenceOrder":257},
  {"id":"s_work_han_thu_118_258","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「欲其事成，故云然也。」","sentenceOrder":258},
  {"id":"s_work_han_thu_118_259","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「說讀曰悅。」","sentenceOrder":259},
  {"id":"s_work_han_thu_118_260","chapterId":"ch_work_han_thu_118","textTraditional":"漢兵乘勝遂圍宛城。初，世祖族兄聖公先在平林兵中。三月辛巳朔，平林、新巿、下江兵將王常、朱鮪等共立聖公為帝，改年為更始元年，拜置百官。莽聞之愈恐。欲外視自安，〔一〕乃染其須髮，進所徵天下淑女杜陵史氏女為皇后，聘黃金三萬斤，車馬奴婢雜帛珍寶以巨萬計。莽親迎於前殿兩階間，成同牢之禮于上西堂。備和嬪、美御、和人三，位視公；嬪人九，視卿；美人二十七，視大夫；御人八十一，視元士：凡百二十人，皆佩印韍，執弓韣。〔二〕封皇后父諶為和平侯，拜為寧始將軍，諶子二人皆侍中。是日，大風發屋折木。群臣上壽曰：「乃庚子雨水灑道，辛丑清靚無塵，〔三〕其夕穀風迅疾，從東北來。〔四〕辛丑，巽之宮日也。巽為風為順，后誼明，母道得，溫和慈惠之化也。易曰：『受茲介福，于其王母。』〔五〕禮曰：『承天之慶，萬福無疆。』〔六〕諸欲依廢漢火劉，皆沃灌雪除，殄滅無餘雜矣。百穀豐茂，庶草蕃殖，〔七〕元元驩喜，兆民賴福，天下幸甚！」莽日與方士涿郡昭君等於後宮考驗方術，縱淫樂焉。大赦天下，然猶曰：「故漢氏舂陵侯群子劉伯升與其族人婚姻黨與，妄流言惑眾，悖畔天命，及手害更始將軍廉丹、前隊大夫甄阜、屬正梁丘賜，及北狄胡虜逆輿（泊）〔洎〕南僰虜若豆、孟遷，不用此書。〔八〕有能捕得此人者，皆封為上公，食邑萬戶，賜寶貨五千萬。」","sentenceOrder":260},
  {"id":"s_work_han_thu_118_261","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「視讀曰示。」","sentenceOrder":261},
  {"id":"s_work_han_thu_118_262","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「禮記月令『仲春之月玄鳥至之日，以太牢祠于高禖，天子親往，后妃率九嬪御，乃禮天子所御。帶以弓韣，授以弓矢，于高禖之前』。韣，弓衣也。帶之者，求男子之祥也，故莽依放之焉。韣音獨。」","sentenceOrder":262},
  {"id":"s_work_han_thu_118_263","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「靚即靜字也。」","sentenceOrder":263},
  {"id":"s_work_han_thu_118_264","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「穀風即谷風。」","sentenceOrder":264},
  {"id":"s_work_han_thu_118_265","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「晉卦六二爻也。介，大也。王母，君母。」","sentenceOrder":265},
  {"id":"s_work_han_thu_118_266","chapterId":"ch_work_han_thu_118","textTraditional":"〔六〕　師古曰：「禮之祝詞。」","sentenceOrder":266},
  {"id":"s_work_han_thu_118_267","chapterId":"ch_work_han_thu_118","textTraditional":"〔七〕　師古曰：「蕃，滋也。殖，生也。」","sentenceOrder":267},
  {"id":"s_work_han_thu_118_268","chapterId":"ch_work_han_thu_118","textTraditional":"〔八〕　師古曰：「輿，匈奴單于名也。洎，及也。若豆、孟遷，蠻僰之名也。言伯升已下，孟遷以上，不在赦令之限也。」","sentenceOrder":268},
  {"id":"s_work_han_thu_118_269","chapterId":"ch_work_han_thu_118","textTraditional":"又詔：「太師王匡、國將哀章、司命孔仁、兗州牧壽良、卒正王閎、揚州牧李聖亟進所部州郡兵〔一〕凡三十萬眾，迫措青、徐盜賊。〔二〕納言將軍嚴尤、秩宗將軍陳茂、車騎將軍王巡、左隊大夫王吳亟進所部州郡兵凡十萬眾，迫措前隊醜虜。明告以生活丹青之信，〔三〕復迷惑不解散，皆并力合擊，殄滅之矣！大司空隆新公，宗室戚屬，前以虎牙將軍東指則反虜破壞，西擊則逆賊靡碎，〔四〕此乃新室威寶之臣也。如黠賊不解散，將遣大司空將百萬之師征伐劋絕之矣！」〔五〕遣七公幹士隗囂等七十二人分下赦令曉諭云。囂等既出，因逃亡矣。","sentenceOrder":269},
  {"id":"s_work_han_thu_118_270","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「亟，急也。」","sentenceOrder":270},
  {"id":"s_work_han_thu_118_271","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「措讀與笮同，音莊客反。下亦放此。」","sentenceOrder":271},
  {"id":"s_work_han_thu_118_272","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「生活，謂來降者不殺之也。丹青之信，言明著也。」","sentenceOrder":272},
  {"id":"s_work_han_thu_118_273","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「靡，散也，音武皮反。」","sentenceOrder":273},
  {"id":"s_work_han_thu_118_274","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「劋，截也，音（予）〔子〕小反。」","sentenceOrder":274},
  {"id":"s_work_han_thu_118_275","chapterId":"ch_work_han_thu_118","textTraditional":"四月，世祖與王常等別攻潁川，下昆陽、郾、定陵。〔一〕莽聞之愈恐，遣大司空王邑馳傳之雒陽，〔二〕與司徒王尋發眾郡兵百萬，號曰「虎牙五威兵」，平定山東。得顓封爵，政決於邑，除用徵諸明兵法六十三家術者，各持圖書，受器械，備軍吏。傾府庫以遣邑，多齎珍寶猛獸，欲視饒富，用怖山東。〔三〕邑至雒陽，州郡各選精兵，牧守自將，定會者四十二萬人，餘在道不絕，車甲士馬之盛，自古出師未嘗有也。","sentenceOrder":275},
  {"id":"s_work_han_thu_118_276","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「三縣之名也。郾音一扇反。」","sentenceOrder":276},
  {"id":"s_work_han_thu_118_277","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「傳音張戀反。」","sentenceOrder":277},
  {"id":"s_work_han_thu_118_278","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「視讀曰示。」","sentenceOrder":278},
  {"id":"s_work_han_thu_118_279","chapterId":"ch_work_han_thu_118","textTraditional":"六月，邑與司徒尋發雒陽，欲至宛，道出潁川，過昆陽。昆陽時已降漢，漢兵守之。嚴尤、陳茂與二公會，二公縱兵圍昆陽。嚴尤曰：「稱尊號者在宛下，宜亟進。〔一〕彼破，諸城自定矣。」邑曰：「百萬之師，所過當滅，今屠此城，喋血而進，〔二〕前歌後舞，顧不快邪！」遂圍城數十重。城中請降，不許。嚴尤又曰：「『歸師勿遏，圍城為之闕』，〔三〕可如兵法，使得逸出，以怖宛下。」邑又不聽。會世祖悉發郾、定陵兵數千人來救昆陽，尋、邑易之，〔四〕自將萬餘人行陳，〔五〕敕諸營皆按部毋得動，獨迎，與漢兵戰，不利。大軍不敢擅相救，漢兵乘勝殺尋。昆陽中兵出並戰，邑走，軍亂。（天）〔大〕風蜚瓦，〔六〕雨如注水，大眾崩壞號謼，〔七〕虎豹股栗，〔八〕士卒奔走，各還歸其郡。邑獨與所將長安勇敢數千人還雒陽。關中聞之震恐，盜賊並起。","sentenceOrder":279},
  {"id":"s_work_han_thu_118_280","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「亟，急也。」","sentenceOrder":280},
  {"id":"s_work_han_thu_118_281","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「喋音牒。」","sentenceOrder":281},
  {"id":"s_work_han_thu_118_282","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「此兵法之言也。遏，遮也。闕，不合也。」","sentenceOrder":282},
  {"id":"s_work_han_thu_118_283","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「輕易之也。易音亦豉反。」","sentenceOrder":283},
  {"id":"s_work_han_thu_118_284","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「巡行軍陳也。行音下更反。」","sentenceOrder":284},
  {"id":"s_work_han_thu_118_285","chapterId":"ch_work_han_thu_118","textTraditional":"〔六〕　師古曰：「蜚，古飛字。」","sentenceOrder":285},
  {"id":"s_work_han_thu_118_286","chapterId":"ch_work_han_thu_118","textTraditional":"〔七〕　師古曰：「謼音火故反。」","sentenceOrder":286},
  {"id":"s_work_han_thu_118_287","chapterId":"ch_work_han_thu_118","textTraditional":"〔八〕　師古曰：「言戰懼甚。」","sentenceOrder":287},
  {"id":"s_work_han_thu_118_288","chapterId":"ch_work_han_thu_118","textTraditional":"又聞漢兵言，莽鴆殺孝平帝。莽乃會公卿以下於王路堂，開所為平帝請命金縢之策，泣以視群臣。〔一〕命明學男張邯稱說其德及符命事，因曰：「易言：『伏戎于莽，升其高陵，三歲不興。』〔二〕『莽』，皇帝之名。『升』謂劉伯升。『高陵』謂高陵侯子翟義也。言劉升、翟義為伏戎之兵於新皇帝世，猶殄滅不興也。」群臣皆稱萬歲。又令東方檻車傳送數人，言「劉伯升等皆行大戮」。（臣）〔民〕知其詐也。","sentenceOrder":288},
  {"id":"s_work_han_thu_118_289","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「視讀曰示。」","sentenceOrder":289},
  {"id":"s_work_han_thu_118_290","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「同人卦九三爻辭也。莽，平草也。言伏兵戎於草莽之中，升高陵而望，不敢前進，至于三歲不能起也。」","sentenceOrder":290},
  {"id":"s_work_han_thu_118_291","chapterId":"ch_work_han_thu_118","textTraditional":"先是，衛將軍王涉素養道士西門君惠。君惠好天文讖記，為涉言：「星孛掃宮室，劉氏當復興，國師公姓名是也。」涉信其言，以語大司馬董忠，數俱至國師殿中廬道語星宿，〔一〕國師不應。後涉特往，對歆涕泣言：「誠欲與公共安宗族，〔二〕奈何不信涉也！」歆因為言天文人事，東方必成。涉曰：「新都哀侯小被病，功顯君素耆酒，〔三〕疑帝本非我家子也。〔四〕董公主中軍精兵，涉領宮衛，伊休侯主殿中，如同心合謀，共劫持帝，東降南陽天子，可以全宗族；不者，俱夷滅矣！」伊休侯者，歆長子也，為侍中五官中郎將，莽素愛之。歆怨莽殺其三子，又畏大禍至，遂與涉、忠謀，欲發。歆曰：「當待太白星出，乃可。」忠以司中大贅起武侯孫伋亦主兵，復與伋謀。伋歸家，顏色變，不能食。妻怪問之，語其狀。妻以告弟雲陽陳邯，邯欲告之。七月，伋與邯俱告，莽遣使者分召忠等。時忠方講兵都肄，〔五〕護軍王咸謂忠謀久不發，恐漏泄，不如遂斬使者，勒兵入。忠不聽，遂與歆、涉會省戶下。莽令{帶足}惲責問，皆服。中黃門各拔刃將忠等送廬，忠拔劍欲自刎，侍中王望傳言大司馬反，黃門持劍共格殺之。省中相驚傳，勒兵至郎署，皆拔刃張弩。更始將軍史諶行諸署，〔六〕告郎吏曰：「大司馬有狂病，發，已誅。」皆令弛兵。〔七〕莽欲以厭凶，〔八〕使虎賁以斬馬劍挫忠，〔九〕盛以竹器，傳曰「反虜出」。下書赦大司馬官屬吏士為忠所詿誤，謀反未發覺者。收忠宗族，以醇醯毒藥、尺白刃叢（僰）〔棘〕并一坎而埋之。劉歆、王涉皆自殺。莽以二人骨肉舊臣，惡其內潰，〔一０〕故隱其誅。伊休侯疊又以素謹，歆訖不告，〔一一〕但免侍中中郎將，更為中散大夫。後日殿中鉤盾土山僊人掌旁有白頭公青衣，〔一二〕郎吏見者私謂之國師公。衍功侯喜素善卦，莽使筮之，曰：「憂兵火。」莽曰：「小兒安得此左道？是乃予之皇祖叔父子僑欲來迎我也。」","sentenceOrder":291},
  {"id":"s_work_han_thu_118_292","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「廬者，宿止之處。道謂說之也。」","sentenceOrder":292},
  {"id":"s_work_han_thu_118_293","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「誠，實也。」","sentenceOrder":293},
  {"id":"s_work_han_thu_118_294","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「耆讀曰嗜。」","sentenceOrder":294},
  {"id":"s_work_han_thu_118_295","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　如淳曰：「言莽母洛薄嗜酒，淫逸得莽耳，非王氏子也。設此詐欲以自別不受誅。」","sentenceOrder":295},
  {"id":"s_work_han_thu_118_296","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「肄，習也，大習兵也。肄音亦二反。」","sentenceOrder":296},
  {"id":"s_work_han_thu_118_297","chapterId":"ch_work_han_thu_118","textTraditional":"〔六〕　師古曰：「行音下更反。」","sentenceOrder":297},
  {"id":"s_work_han_thu_118_298","chapterId":"ch_work_han_thu_118","textTraditional":"〔七〕　師古曰：「弛，放也。」","sentenceOrder":298},
  {"id":"s_work_han_thu_118_299","chapterId":"ch_work_han_thu_118","textTraditional":"〔八〕　師古曰：「厭，當也，音一葉反。」","sentenceOrder":299},
  {"id":"s_work_han_thu_118_300","chapterId":"ch_work_han_thu_118","textTraditional":"〔九〕　師古曰：「挫讀曰剉，音千臥反。」","sentenceOrder":300},
  {"id":"s_work_han_thu_118_301","chapterId":"ch_work_han_thu_118","textTraditional":"〔一０〕師古曰：「王涉，骨肉也。劉歆，舊臣。」","sentenceOrder":301},
  {"id":"s_work_han_thu_118_302","chapterId":"ch_work_han_thu_118","textTraditional":"〔一一〕師古曰：「訖猶竟也。歆竟不以所謀告之。」","sentenceOrder":302},
  {"id":"s_work_han_thu_118_303","chapterId":"ch_work_han_thu_118","textTraditional":"〔一二〕鄭氏曰：「僊人以掌承（露）承（盛）〔露盤〕也。」","sentenceOrder":303},
  {"id":"s_work_han_thu_118_304","chapterId":"ch_work_han_thu_118","textTraditional":"莽軍師外破，大臣內畔，左右亡所信，不能復遠念郡國，欲謼邑與計議。〔一〕崔發曰：「邑素小心，今失大眾而徵，恐其執節引決，宜有以大慰其意。」於是莽遣發馳傳諭邑：〔二〕「我年老毋適子，〔三〕欲傳邑以天下。敕亡得謝，見勿復道。」邑到，以為大司馬。大長秋張邯為大司徒，崔發為大司空，司中壽容苗訢為國師，同說侯林為衛將軍。莽憂懣不能食，〔四〕亶飲酒，啗鰒魚。〔五〕讀軍書倦，因馮几寐，不復就枕矣。〔六〕性好時日小數，及事迫急，亶為厭勝。遣使壞渭陵、延陵園門罘罳，曰：「毋使民復思也。」又以墨洿色其周垣。〔七〕號將至曰「歲宿」，申水為「助將軍」，右庚「刻木校尉」，前丙「燿金都尉」，又曰：「執大斧，伐枯木；流大水，滅發火。」如此屬不可勝記。","sentenceOrder":304},
  {"id":"s_work_han_thu_118_305","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「謼音呼。」","sentenceOrder":305},
  {"id":"s_work_han_thu_118_306","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「謂諭告之。傳音張戀反。」","sentenceOrder":306},
  {"id":"s_work_han_thu_118_307","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「適讀曰嫡。」","sentenceOrder":307},
  {"id":"s_work_han_thu_118_308","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「懣音滿，又音悶。」","sentenceOrder":308},
  {"id":"s_work_han_thu_118_309","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「亶音但。下亦類此。鰒，海魚也，音雹。」","sentenceOrder":309},
  {"id":"s_work_han_thu_118_310","chapterId":"ch_work_han_thu_118","textTraditional":"〔六〕　師古曰：「馮讀曰憑。」","sentenceOrder":310},
  {"id":"s_work_han_thu_118_311","chapterId":"ch_work_han_thu_118","textTraditional":"〔七〕　師古曰：「洿染之變其舊色也。洿音一故反。」","sentenceOrder":311},
  {"id":"s_work_han_thu_118_312","chapterId":"ch_work_han_thu_118","textTraditional":"秋，太白星流入太微，燭地如月光。","sentenceOrder":312},
  {"id":"s_work_han_thu_118_313","chapterId":"ch_work_han_thu_118","textTraditional":"成紀隗崔兄弟共劫大尹李育，〔一〕以兄子隗囂為大將軍，攻殺雍州牧陳慶、安定卒正王旬，并其眾，移書郡縣，數莽罪惡萬於桀紂。","sentenceOrder":313},
  {"id":"s_work_han_thu_118_314","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「成紀，隴西之縣。」","sentenceOrder":314},
  {"id":"s_work_han_thu_118_315","chapterId":"ch_work_han_thu_118","textTraditional":"是月，析人鄧曄、于匡起兵南鄉百餘人。〔一〕時析宰將兵數千屯鄡亭，備武關。〔二〕曄、匡謂宰曰：「劉帝已立，君何不知命也！」宰請降，盡得其眾。曄自稱輔漢左將軍，匡右將軍，拔析、丹水，攻武關，都尉朱萌降。進攻右隊大夫宋綱，殺之，西拔湖。〔三〕莽愈憂，不知所出。崔發言：「周禮及春秋左氏，國有大災，則哭以厭之。〔四〕故易稱『先號咷而後笑』。〔五〕宜呼嗟告天以求救。」莽自知敗，乃率群臣至南郊，陳其符命本末，仰天曰：「皇天既命授臣莽，何不殄滅眾賊？即令臣莽非是，願下雷霆誅臣莽！」因搏心大哭，氣盡，伏而叩頭。又作告天策，自陳功勞，千餘言。諸生小民會旦夕哭，為設飧粥，〔六〕甚悲哀及能誦策文者除以為郎，至五千餘人。{帶足}惲將領之。","sentenceOrder":315},
  {"id":"s_work_han_thu_118_316","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「析，南陽之縣。南鄉，析縣之鄉名。析音先歷反。」","sentenceOrder":316},
  {"id":"s_work_han_thu_118_317","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「鄡音口堯反。」","sentenceOrder":317},
  {"id":"s_work_han_thu_118_318","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「湖，弘農之縣也，本屬京兆。」","sentenceOrder":318},
  {"id":"s_work_han_thu_118_319","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「周禮春官之屬女巫氏之職曰：『凡邦之大災，歌哭而請。』哭者所以告哀也。春秋左氏傳宣十二年『楚子圍鄭，旬有七日，鄭人卜行成，不吉；卜臨于太宮，且巷出車，吉。國人大臨，守陴者皆哭。』故發引之以為言也。厭音一葉反。」","sentenceOrder":319},
  {"id":"s_work_han_thu_118_320","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「同人九五爻辭。號咷，哭也。咷音逃。」","sentenceOrder":320},
  {"id":"s_work_han_thu_118_321","chapterId":"ch_work_han_thu_118","textTraditional":"〔六〕　師古曰：「飧，古飡字，音千安反。」","sentenceOrder":321},
  {"id":"s_work_han_thu_118_322","chapterId":"ch_work_han_thu_118","textTraditional":"莽拜將軍九人，皆以虎為號，號曰「九虎」，將北軍精兵數萬人東，內其妻子宮中以為質。時省中黃金萬斤者為一匱，尚有六十匱，黃門、鉤盾、臧府、中尚方處處各有數匱。長樂御府、中御府及都內、平準帑藏錢帛珠玉財物甚眾，〔一〕莽愈愛之，賜九虎士人四千錢。眾重怨，無鬥意。〔二〕九虎至華陰回谿，距隘，北從河南至山。于匡持數千弩，乘堆挑戰。鄧曄將二萬餘人從閿鄉南出棗街、作姑，〔三〕破其一部，北出九虎後擊之。六虎敗走。史熊、王況詣闕歸死，莽使使責死者安在，皆自殺；其四虎亡。〔四〕三虎郭欽、陳翬、成重收散卒，保京師倉。〔五〕","sentenceOrder":322},
  {"id":"s_work_han_thu_118_323","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「御府有令丞，少府之屬官也，掌珍物。中御府者，皇后之府藏也。平準令丞屬大司農，亦珍貨所在也。」","sentenceOrder":323},
  {"id":"s_work_han_thu_118_324","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「重音直用反。」","sentenceOrder":324},
  {"id":"s_work_han_thu_118_325","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「閿讀與聞同。作姑，邪道所由也。」","sentenceOrder":325},
  {"id":"s_work_han_thu_118_326","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「六人敗走，二人詣闕自殺，四人亡。」","sentenceOrder":326},
  {"id":"s_work_han_thu_118_327","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「九人之中，六人敗走，三人保倉也。京師倉在華陰灌北渭口也。翬音暉。」","sentenceOrder":327},
  {"id":"s_work_han_thu_118_328","chapterId":"ch_work_han_thu_118","textTraditional":"鄧曄開武關迎漢，丞相司直李松將二千餘人至湖，與曄等共攻京師倉，未下。曄以弘農掾王憲為校尉，將數百人北度渭，入左馮翊界，降城略地。李松遣偏將軍韓臣等徑西至新豐，與莽波水將軍戰，波水走。韓臣等追奔，遂至長門宮。王憲北至頻陽，所過迎降。〔一〕大姓櫟陽申碭、下邽王大皆率眾隨憲。屬縣斄嚴春、〔二〕茂陵董喜、藍田王孟、槐里汝臣、盩厔王扶、陽陵嚴本、杜陵屠門少之屬〔三〕，眾皆數千人，假號稱漢將。","sentenceOrder":328},
  {"id":"s_work_han_thu_118_329","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「所至之處，人皆來迎而降附也。」","sentenceOrder":329},
  {"id":"s_work_han_thu_118_330","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「屬縣，三輔諸縣也。斄屬右扶風。斄讀與邰同。其人姓嚴，名春。」","sentenceOrder":330},
  {"id":"s_work_han_thu_118_331","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「姓屠門，名少。」","sentenceOrder":331},
  {"id":"s_work_han_thu_118_332","chapterId":"ch_work_han_thu_118","textTraditional":"時李松、鄧曄以為京師小小倉尚未可下，何況長安城，當須更始帝大兵到。即引軍至華陰，治攻具。而長安旁兵四會城下，聞天水隗氏兵方到，皆爭欲先入城，貪立大功鹵掠之利。","sentenceOrder":332},
  {"id":"s_work_han_thu_118_333","chapterId":"ch_work_han_thu_118","textTraditional":"莽遣使者分赦城中諸獄囚徒，皆授兵，殺豨飲其血，與誓曰：「有不為新室者，社鬼記之！」更始將軍史諶將度渭橋，皆散走。諶空還。眾兵發掘莽妻子父祖冢，燒其棺槨及九廟、明堂、辟雍，火照城中。或謂莽曰：「城門卒，東方人，不可信。」莽更發越騎士為衛，門置六百人，各一校尉。","sentenceOrder":333},
  {"id":"s_work_han_thu_118_334","chapterId":"ch_work_han_thu_118","textTraditional":"十月戊申朔，兵從宣平城門入，民間所謂都門也。〔一〕張邯行城門，逢兵見殺。〔二〕王邑、王林、王巡、{帶足}惲等分將兵距擊北闕下。漢兵貪莽封力戰者七百餘人。〔三〕會日暮，官府邸第盡奔亡。二日己酉，城中少年朱弟、張魚等恐見鹵掠，趨讙並和，〔四〕燒作室門，斧敬法闥，〔五〕謼曰：「反虜王莽，何不出降？」〔六〕火及掖廷承明，黃皇室主所居也。莽避火宣室前殿，火輒隨之。宮人婦女謕謼曰：「當奈何！」時莽紺袀服，〔七〕帶璽韍，持虞帝匕首。天文郎桉栻於前，〔八〕日時加某，莽旋席隨斗柄而坐，曰：「天生德於予，漢兵其如予何！」〔九〕莽時不食，少氣困矣。","sentenceOrder":334},
  {"id":"s_work_han_thu_118_335","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「長安城東出北頭第一門。」","sentenceOrder":335},
  {"id":"s_work_han_thu_118_336","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「行音下更反。」","sentenceOrder":336},
  {"id":"s_work_han_thu_118_337","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「獲莽當得封，故貪之而力戰。」","sentenceOrder":337},
  {"id":"s_work_han_thu_118_338","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「眾群行讙而自相和也。和音呼臥反。」","sentenceOrder":338},
  {"id":"s_work_han_thu_118_339","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「敬法，殿名也。闥，小門也。謂斧斫之也。」","sentenceOrder":339},
  {"id":"s_work_han_thu_118_340","chapterId":"ch_work_han_thu_118","textTraditional":"〔六〕　師古曰：「謼音火故反。其下亦同。」","sentenceOrder":340},
  {"id":"s_work_han_thu_118_341","chapterId":"ch_work_han_thu_118","textTraditional":"〔七〕　師古曰：「謕，古啼字也。紺，深青而揚赤色也。袀，純也。純為紺服也。袀音均，又弋旬反。」","sentenceOrder":341},
  {"id":"s_work_han_thu_118_342","chapterId":"ch_work_han_thu_118","textTraditional":"〔八〕　師古曰：「栻，所以占時日。天文郎，今之用栻者也。音式。」","sentenceOrder":342},
  {"id":"s_work_han_thu_118_343","chapterId":"ch_work_han_thu_118","textTraditional":"〔九〕　師古曰：「論語稱孔子：『天生德於予，桓魋其如予何？』故莽引之以為言也。」","sentenceOrder":343},
  {"id":"s_work_han_thu_118_344","chapterId":"ch_work_han_thu_118","textTraditional":"三日庚戌，晨旦明，群臣扶掖莽，自前殿南下椒除，〔一〕西出白虎門，和新公王揖奉車待門外。莽就車，之漸臺，欲阻池水，猶抱持符命、威斗，公卿大夫、侍中、黃門郎從官尚千餘人隨之。王邑晝夜戰，罷極，〔二〕士死傷略盡，馳入宮，間關至漸臺，〔三〕見其子侍中睦解衣冠欲逃，邑叱之令還，父子共守莽。軍人入殿中，謼曰：「反虜王莽安在？」有美人出房曰：「在漸臺。」眾兵追之，圍數百重。臺上亦弓弩與相射，稍稍落去。矢盡，無以復射，短兵接。王邑父（平）〔子〕、{帶足}惲、王巡戰死，莽入室。下餔時，眾兵上臺，王揖、趙博、苗訢、唐尊、王盛、中常侍王參等皆死臺上。商人杜吳殺莽，取其綬。校尉東海公賓就，故大行治禮，〔四〕見吳問綬主所在。曰：「室中西北陬間。」〔五〕就識，斬莽首。軍人分裂莽身，支節肌骨臠分，爭相殺者數十人。〔六〕公賓就持莽首詣王憲。憲自稱漢大將軍，城中兵數十萬皆屬焉，舍東宮，〔七〕妻莽後宮，乘其車服。","sentenceOrder":344},
  {"id":"s_work_han_thu_118_345","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　服虔曰：「邪行閣道下者也。」師古曰：「除，殿陛之道也。椒，取芬香之名也。」","sentenceOrder":345},
  {"id":"s_work_han_thu_118_346","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「罷讀曰疲。」","sentenceOrder":346},
  {"id":"s_work_han_thu_118_347","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「間關猶言崎嶇展轉也。」","sentenceOrder":347},
  {"id":"s_work_han_thu_118_348","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「公賓，姓也。就，名也。以先經治禮，故識天子綬也。」","sentenceOrder":348},
  {"id":"s_work_han_thu_118_349","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「陬，隅也，音子侯反，又音鄒。」","sentenceOrder":349},
  {"id":"s_work_han_thu_118_350","chapterId":"ch_work_han_thu_118","textTraditional":"〔六〕　師古曰：「三輔舊事云，臠，切千段也。」","sentenceOrder":350},
  {"id":"s_work_han_thu_118_351","chapterId":"ch_work_han_thu_118","textTraditional":"〔七〕　師古曰：「舍，止宿也。」","sentenceOrder":351},
  {"id":"s_work_han_thu_118_352","chapterId":"ch_work_han_thu_118","textTraditional":"六日癸丑，李松、鄧曄入長安，將軍趙萌、申屠建亦至，以王憲得璽綬不輒上，多挾宮女，建天子鼓旗，收斬之。傳莽首詣更始，縣宛市，百姓共提擊之，〔一〕或切食其舌。","sentenceOrder":352},
  {"id":"s_work_han_thu_118_353","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「提，擲也，音徒計反。」","sentenceOrder":353},
  {"id":"s_work_han_thu_118_354","chapterId":"ch_work_han_thu_118","textTraditional":"莽揚州牧李聖、司命孔仁兵敗山東，聖格死，仁將其眾降，已而歎曰：「吾聞食人食者死其事。」拔劍自刺死。及曹部監杜普、陳定大尹沈意、九江連率賈萌皆守郡不降，為漢兵所誅。賞都大尹王欽及郭欽守京師倉，聞莽死，乃降，更始義之，皆封為侯。太師王匡、國將哀章降雒陽，傳詣宛，斬之。嚴尤、陳茂敗昆陽下，走至沛郡譙，自稱漢將，召會吏民。尤為稱說王莽篡位天時所亡聖漢復興狀，茂伏而涕泣。聞故漢鍾武侯劉聖聚眾汝南稱尊號，尤、茂降之。以尤為大司馬，茂為丞相。十餘日敗，尤、茂并死。郡縣皆舉城降，天下悉歸漢。","sentenceOrder":354},
  {"id":"s_work_han_thu_118_355","chapterId":"ch_work_han_thu_118","textTraditional":"初，申屠建嘗事崔發為詩，〔一〕建至，發降之。後復稱說〔二〕，建令丞相劉賜斬發以徇。史諶、王延、王林、王吳、趙閎亦降，復見殺。初，諸假號兵人人望封侯。申屠建既斬王憲，又揚言三輔黠共殺其主。吏民惶恐，屬縣屯聚，建等不能下，馳白更始。","sentenceOrder":355},
  {"id":"s_work_han_thu_118_356","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「就發學詩。」","sentenceOrder":356},
  {"id":"s_work_han_thu_118_357","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「妄言符命，不順漢。」","sentenceOrder":357},
  {"id":"s_work_han_thu_118_358","chapterId":"ch_work_han_thu_118","textTraditional":"二年二月，更始到長安，下詔大赦，非王莽子，他皆除其罪，故王氏宗族得全。三輔悉平，更始都長安，居長樂宮。府藏完具，獨未央宮燒攻莽三日，死則案堵復故。更始至，歲餘政教不行。明年夏，赤眉樊崇等眾數十萬人入關，立劉盆子，稱尊號，攻更始，更始降之。赤眉遂燒長安宮室市里，害更始。民飢餓相食，死者數十萬，長安為虛，〔一〕城中無人行。宗廟園陵皆發掘，唯霸陵、杜陵完。六月，世祖即位，然後宗廟社稷復立，天下艾安。〔二〕","sentenceOrder":358},
  {"id":"s_work_han_thu_118_359","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「虛讀曰墟。」","sentenceOrder":359},
  {"id":"s_work_han_thu_118_360","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「艾讀曰乂。」","sentenceOrder":360},
  {"id":"s_work_han_thu_118_361","chapterId":"ch_work_han_thu_118","textTraditional":"贊曰：王莽始起外戚，折節力行，以要名譽，宗族稱孝，師友歸仁。及其居位輔政，成、哀之際，勤勞國家，直道而行，動見稱述。豈所謂「在家必聞，在國必聞」，「色取仁而行違」者邪？〔一〕莽既不仁而有佞邪之材，又乘四父歷世之權，遭漢中微，國統三絕，而太后壽考為之宗主，故得肆其姦慝，以成篡盜之禍。〔二〕推是言之，亦天時，非人力之致矣。及其竊位南面，處非所據，顛覆之勢險於桀紂，而莽晏然自以黃、虞復出也。乃始恣睢，奮其威詐，〔三〕滔天虐民，窮凶惡極，〔四〕毒流諸夏，亂延蠻貉，猶未足逞其欲焉。是以四海之內，囂然喪其樂生之心，〔五〕中外憤怨，遠近俱發，城池不守，支體分裂，遂令天下城邑為虛，〔六〕丘壟發掘，害遍生民，辜及朽骨，自書傳所載亂臣賊子無道之人，考其禍敗，未有如莽之甚者也。昔秦燔詩書以立私議，莽誦六藝以文姦言，〔七〕同歸誅塗，俱用滅亡，皆炕龍絕氣，非命之運，〔八〕紫色〈圭黽〉聲，餘分閏位，〔九〕聖王之驅除云爾！〔一０〕","sentenceOrder":361},
  {"id":"s_work_han_thu_118_362","chapterId":"ch_work_han_thu_118","textTraditional":"〔一〕　師古曰：「論語載孔子對子張之言也。不仁之人假仁者之色，而所行則違之。朋黨比周，故能在家在國皆有名譽。故贊引之。」","sentenceOrder":362},
  {"id":"s_work_han_thu_118_363","chapterId":"ch_work_han_thu_118","textTraditional":"〔二〕　師古曰：「肆，放也，極也。」","sentenceOrder":363},
  {"id":"s_work_han_thu_118_364","chapterId":"ch_work_han_thu_118","textTraditional":"〔三〕　師古曰：「睢音呼季反。」","sentenceOrder":364},
  {"id":"s_work_han_thu_118_365","chapterId":"ch_work_han_thu_118","textTraditional":"〔四〕　師古曰：「滔，漫也。」","sentenceOrder":365},
  {"id":"s_work_han_thu_118_366","chapterId":"ch_work_han_thu_118","textTraditional":"〔五〕　師古曰：「囂然，眾口愁貌也。音五高反。」","sentenceOrder":366},
  {"id":"s_work_han_thu_118_367","chapterId":"ch_work_han_thu_118","textTraditional":"〔六〕　師古曰：「虛讀曰墟。」","sentenceOrder":367},
  {"id":"s_work_han_thu_118_368","chapterId":"ch_work_han_thu_118","textTraditional":"〔七〕　師古曰：「以六經之事文飾姦言。」","sentenceOrder":368},
  {"id":"s_work_han_thu_118_369","chapterId":"ch_work_han_thu_118","textTraditional":"〔八〕　服虔曰：「易曰『亢龍有悔』，謂無德而居高位也。」蘇林曰：「非命，非天命之命也。」","sentenceOrder":369},
  {"id":"s_work_han_thu_118_370","chapterId":"ch_work_han_thu_118","textTraditional":"〔九〕　應劭曰：「紫，間色；〈圭黽〉，邪音也。」服虔曰：「言莽不得正王之命，如歲月之餘分為閏也。」師古曰：「〈圭黽〉者，樂之淫聲，非正曲也。近之學者，便謂〈圭黽〉之鳴，已失其義。又欲改此贊〈圭黽〉聲為蠅聲，引詩『匪雞則鳴，蒼蠅之聲』，尤穿鑿矣。」","sentenceOrder":370},
  {"id":"s_work_han_thu_118_371","chapterId":"ch_work_han_thu_118","textTraditional":"〔一０〕蘇林曰：「聖王，光武也。為光武驅除也。」師古曰：「言驅逐蠲除，以待聖人也。」","sentenceOrder":371},
  {"id":"s_work_han_thu_118_372","chapterId":"ch_work_han_thu_118","textTraditional":"校勘記","sentenceOrder":372},
  {"id":"s_work_han_thu_118_373","chapterId":"ch_work_han_thu_118","textTraditional":"四一五五頁一五行　莽遣昭君兄子和親侯王歙誘呼（嘗）〔當〕至塞下，　景祐、殿、局本都作「當」，此誤。","sentenceOrder":373},
  {"id":"s_work_han_thu_118_374","chapterId":"ch_work_han_thu_118","textTraditional":"四一六一頁一三行　予將（新）〔親〕築焉。　景祐、殿本都作「親」。王先謙說作「親」是。","sentenceOrder":374},
  {"id":"s_work_han_thu_118_375","chapterId":"ch_work_han_thu_118","textTraditional":"四一六二頁一０行　波音（波）〔彼〕皮反。　景祐、殿本都作「彼」，此誤。","sentenceOrder":375},
  {"id":"s_work_han_thu_118_376","chapterId":"ch_work_han_thu_118","textTraditional":"四一七０頁　二行　平原女子遲昭平能說（經博）〔博經〕以八投，　王念孫說，「經博」當為「博經」，故服注云「博奕經，以八箭投之」。","sentenceOrder":376},
  {"id":"s_work_han_thu_118_377","chapterId":"ch_work_han_thu_118","textTraditional":"四一八０頁　二行　識讀與幟同，音（忒）〔式〕志反。　景祐、殿本都作「式」。","sentenceOrder":377},
  {"id":"s_work_han_thu_118_378","chapterId":"ch_work_han_thu_118","textTraditional":"四一八一頁　二行　及北狄胡虜逆輿（泊）〔洎〕南僰虜若豆、孟遷，　景祐、殿、局本都作「洎」，此誤。","sentenceOrder":378},
  {"id":"s_work_han_thu_118_379","chapterId":"ch_work_han_thu_118","textTraditional":"四一八二頁　八行　劋，截也，音（予）〔子〕小反。　景祐、殿本都作「子」，此誤。","sentenceOrder":379},
  {"id":"s_work_han_thu_118_380","chapterId":"ch_work_han_thu_118","textTraditional":"四一八三頁　七行　（天）〔大〕風蜚瓦，　殿、局本都作「大」。王先謙說作「大」是。","sentenceOrder":380},
  {"id":"s_work_han_thu_118_381","chapterId":"ch_work_han_thu_118","textTraditional":"四一八四頁　六行　（臣）〔民〕知其詐也。　景祐、殿、局本都作「民」。王先謙說作「民」是。","sentenceOrder":381},
  {"id":"s_work_han_thu_118_382","chapterId":"ch_work_han_thu_118","textTraditional":"四一八五頁　八行　叢（僰）〔棘〕　景祐、殿、局本都作「棘」，此誤。","sentenceOrder":382},
  {"id":"s_work_han_thu_118_383","chapterId":"ch_work_han_thu_118","textTraditional":"四一八六頁　八行　僊人以掌承（露）承（盛）〔露盤〕也。　景祐、殿本都作「遷人以掌承承露盤」，此誤。","sentenceOrder":383},
  {"id":"s_work_han_thu_118_384","chapterId":"ch_work_han_thu_118","textTraditional":"四一九一頁一三行　王邑父（平）〔子〕、　景祐、殿本都作「子」。王先謙說「平」字誤。","sentenceOrder":384},
  {"id":"s_work_han_thu_119_1","chapterId":"ch_work_han_thu_119","textTraditional":"師古曰：「自敘漢書以後分為下卷。」","sentenceOrder":1},
  {"id":"s_work_han_thu_119_2","chapterId":"ch_work_han_thu_119","textTraditional":"班氏之先，與楚同姓，令尹子文之後也。子文初生，棄於瞢中，而虎乳之。〔一〕楚人謂乳「穀」，謂虎「於檡」，〔二〕故名穀於檡，字子文。楚人謂虎「班」，其子以為號。〔三〕秦之滅楚，遷晉、代之間，因氏焉。〔四〕","sentenceOrder":2},
  {"id":"s_work_han_thu_119_3","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「瞢，雲瞢澤也。春秋左氏傳曰『楚若敖娶於〈云阝〉，生鬥伯比。若敖卒，從其母畜於〈云阝〉，淫於〈云阝〉子之女，生子文焉。〈云阝〉夫人使棄諸瞢中，獸乳之。〈云阝〉子田，見之，懼而歸，夫人以告，遂使收之。』瞢與夢同，並音莫風反，又音莫鳳反。」","sentenceOrder":3},
  {"id":"s_work_han_thu_119_4","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　如淳曰：「穀音構。牛羊乳汁曰構。」師古曰：「穀讀如本字，又音乃苟反。於音烏。檡字或作菟，並音塗。」","sentenceOrder":4},
  {"id":"s_work_han_thu_119_5","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「子文之子鬥班，亦為楚令尹。」","sentenceOrder":5},
  {"id":"s_work_han_thu_119_6","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　師古曰：「遂以班為姓。」","sentenceOrder":6},
  {"id":"s_work_han_thu_119_7","chapterId":"ch_work_han_thu_119","textTraditional":"始皇之末，班壹避墬於樓煩，〔一〕致馬牛羊數千群。值漢初定，與民無禁，當孝惠、高后時，以財雄邊，〔二〕出入弋獵，旌旗鼓吹，年百餘歲，以壽終，故北方多以「壹」為字者。〔三〕","sentenceOrder":7},
  {"id":"s_work_han_thu_119_8","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「墬，古地字。樓煩，鴈門之縣。」","sentenceOrder":8},
  {"id":"s_work_han_thu_119_9","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「國家不設衣服車旗之禁，故班氏以多財而為邊地之雄豪。」","sentenceOrder":9},
  {"id":"s_work_han_thu_119_10","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「馬邑人聶壹之類也。今流俗書本多改此傳壹字為懿，非也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_119_11","chapterId":"ch_work_han_thu_119","textTraditional":"壹生孺。孺為任俠，州郡歌之。孺生長，官至上谷守。長生回，以茂材為長子令。〔一〕回生況，舉孝廉為郎，積功勞，至上河農都尉，〔二〕大司農奏課連最，入為左曹越騎校尉。成帝之初，女為婕妤，致仕就第，貲累千金，徙昌陵。昌陵後罷，大臣名家皆占數于長安。〔三〕","sentenceOrder":11},
  {"id":"s_work_han_thu_119_12","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「上黨之縣。長讀如本字。」","sentenceOrder":12},
  {"id":"s_work_han_thu_119_13","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「上河，地名。農都尉者，典農事。」","sentenceOrder":13},
  {"id":"s_work_han_thu_119_14","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「占，度也。自隱度家之（曰）〔口〕數而著名籍也。占音之贍反。」","sentenceOrder":14},
  {"id":"s_work_han_thu_119_15","chapterId":"ch_work_han_thu_119","textTraditional":"況生三子：伯、斿、稚。伯少受詩於師丹。大將軍王鳳薦伯宜勸學，召見宴昵殿，〔一〕容貌甚麗，誦說有法，拜為中常侍。時上方鄉學，〔二〕鄭寬中、張禹朝夕入說尚書、論語於金華殿中，〔三〕詔伯受焉。既通大義，又講異同於許商，遷奉車都尉。數年，金華之業絕，出與王、許子弟為群，在於綺襦紈褲之間，非其好也。〔四〕","sentenceOrder":15},
  {"id":"s_work_han_thu_119_16","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　張晏曰：「親戚宴飲會同之殿。」","sentenceOrder":16},
  {"id":"s_work_han_thu_119_17","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「鄉讀曰嚮。」","sentenceOrder":17},
  {"id":"s_work_han_thu_119_18","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「金華殿在未央宮。」","sentenceOrder":18},
  {"id":"s_work_han_thu_119_19","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　晉灼曰：「白綺之襦，冰紈之褲也。」師古曰：「紈，素也。綺，今細綾也。並貴戚子弟之服。」","sentenceOrder":19},
  {"id":"s_work_han_thu_119_20","chapterId":"ch_work_han_thu_119","textTraditional":"家本北邊，志節忼慨，數求使匈奴。河平中，單于來朝，上使伯持節迎於塞下。會定襄大姓石、李群輩報怨，殺追捕吏，〔一〕伯上狀，因自請願試守期月。〔二〕上遣侍中中郎將王舜馳傳代伯護單于，〔三〕并奉璽書印綬，即拜伯為定襄太守。〔四〕定襄聞伯素貴，年少，自請治劇，畏其下車作威，吏民竦息。伯至，請問耆老父祖故人有舊恩者，〔五〕迎延滿堂，日為供具，〔六〕執子孫禮。郡中益弛。〔七〕諸所賓禮皆名豪，懷恩醉酒，共諫伯宜頗攝錄盜賊，具言本謀亡匿處。伯曰：「是所望於父師矣。」〔八〕乃召屬縣長吏，選精進掾史，〔九〕分部收捕，〔一０〕及它隱伏，旬日盡得。郡中震栗，咸稱神明。〔一一〕歲餘，上徵伯。伯上書願過故郡上父祖冢。有詔，太守都尉以下會。〔一二〕因召宗族，各以親疏加恩施，散數百金。北州以為榮，長老紀焉。〔一三〕道病中風，〔一四〕既至，以侍中光祿大夫養病，〔一五〕賞賜甚厚，數年未能起。","sentenceOrder":20},
  {"id":"s_work_han_thu_119_21","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「報私怨而殺人，吏追捕之，又殺吏。」","sentenceOrder":21},
  {"id":"s_work_han_thu_119_22","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「欲守定襄太守。期音基。」","sentenceOrder":22},
  {"id":"s_work_han_thu_119_23","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「傳音張戀反。」","sentenceOrder":23},
  {"id":"s_work_han_thu_119_24","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　師古曰：「即，就也，就其所居而拜。」","sentenceOrder":24},
  {"id":"s_work_han_thu_119_25","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　師古曰：「請，召也。」","sentenceOrder":25},
  {"id":"s_work_han_thu_119_26","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　師古曰：「酒食之具也。供音居用反。」","sentenceOrder":26},
  {"id":"s_work_han_thu_119_27","chapterId":"ch_work_han_thu_119","textTraditional":"〔七〕　師古曰：「弛，解也。見伯不用威刑，故自解縱。」","sentenceOrder":27},
  {"id":"s_work_han_thu_119_28","chapterId":"ch_work_han_thu_119","textTraditional":"〔八〕　師古曰：「齒為諸父，尊之如師，故曰父師。」","sentenceOrder":28},
  {"id":"s_work_han_thu_119_29","chapterId":"ch_work_han_thu_119","textTraditional":"〔九〕　師古曰：「精明而進趨也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_119_30","chapterId":"ch_work_han_thu_119","textTraditional":"〔一０〕師古曰：「分音扶問反。」","sentenceOrder":30},
  {"id":"s_work_han_thu_119_31","chapterId":"ch_work_han_thu_119","textTraditional":"〔一一〕師古曰：「〈桌，中“一改仌”〉，古栗字。」","sentenceOrder":31},
  {"id":"s_work_han_thu_119_32","chapterId":"ch_work_han_thu_119","textTraditional":"〔一二〕師古曰：「同赴其所。」","sentenceOrder":32},
  {"id":"s_work_han_thu_119_33","chapterId":"ch_work_han_thu_119","textTraditional":"〔一三〕師古曰：「紀，記也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_119_34","chapterId":"ch_work_han_thu_119","textTraditional":"〔一四〕師古曰：「中，傷也，為風所傷。」","sentenceOrder":34},
  {"id":"s_work_han_thu_119_35","chapterId":"ch_work_han_thu_119","textTraditional":"〔一五〕師古曰：「受其秩奉而在家自養也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_119_36","chapterId":"ch_work_han_thu_119","textTraditional":"會許皇后廢，班婕妤供養東宮，〔一〕進侍者李平為婕妤，而趙飛燕為皇后，伯遂稱篤。久之，上出過臨候伯，伯惶恐，起視事〔二〕。","sentenceOrder":36},
  {"id":"s_work_han_thu_119_37","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「元后，成帝母。」","sentenceOrder":37},
  {"id":"s_work_han_thu_119_38","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「眡，古視字。」","sentenceOrder":38},
  {"id":"s_work_han_thu_119_39","chapterId":"ch_work_han_thu_119","textTraditional":"自大將軍薨後，〔一〕富平、定陵侯張放、淳于長等始愛幸，出為微行，行則同輿執轡；入侍禁中，設宴飲之會，及趙、李諸侍中皆引滿舉白，〔二〕談笑大噱。〔三〕時乘輿幄坐張畫屏風，〔四〕畫紂醉踞妲己作長夜之樂。上以伯新起，數目禮之，〔五〕因顧指畫而問伯：「紂為無道，至於是虖？」伯對曰：「書云『乃用婦人之言』，〔六〕何有踞肆於朝？〔七〕所謂眾惡歸之，不如是之甚者也。」〔八〕上曰：「苟不若此，此圖何戒？」伯曰：「『沈湎于酒』，微子所以告去也；〔九〕『式號式謼』，大雅所以流連也。〔一０〕詩書淫亂之戒，其原皆在於酒。」上乃謂然歎曰：「吾久不見班生，今日復聞讜言！」〔一一〕放等不懌，〔一二〕稍自引起更衣，因罷出。時長信庭林表適使來，聞見之。〔一三〕","sentenceOrder":39},
  {"id":"s_work_han_thu_119_40","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「王鳳。」","sentenceOrder":40},
  {"id":"s_work_han_thu_119_41","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　服虔曰：「舉滿桮，有餘白瀝者，罰之也。」孟康曰：「舉白，見驗飲酒盡不也。」師古曰：「謂引取滿觴而飲，飲訖，舉觴告白盡不也。一說，白者，罰爵之名也。飲有不盡者，則以此爵罰之。魏文侯與大夫飲酒，令曰：『不釂者，浮以大白。』於是公乘不仁舉白浮君者也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_119_42","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「关，古笑字也。噱噱，笑聲也。音其略反。或曰，噱謂唇口之中，大笑則見，此說非。」","sentenceOrder":42},
  {"id":"s_work_han_thu_119_43","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　師古曰：「坐音材臥反。」","sentenceOrder":43},
  {"id":"s_work_han_thu_119_44","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　師古曰：「目視而敬之。」","sentenceOrder":44},
  {"id":"s_work_han_thu_119_45","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　師古曰：「今文尚書泰誓之辭。」","sentenceOrder":45},
  {"id":"s_work_han_thu_119_46","chapterId":"ch_work_han_thu_119","textTraditional":"〔七〕　師古曰：「肆，放也，陳也。」","sentenceOrder":46},
  {"id":"s_work_han_thu_119_47","chapterId":"ch_work_han_thu_119","textTraditional":"〔八〕　師古曰：「論語稱孔子曰：『紂之不善，不如是之甚也。是以君子惡居下流，天下之惡皆歸焉。』故伯引此為言。」","sentenceOrder":47},
  {"id":"s_work_han_thu_119_48","chapterId":"ch_work_han_thu_119","textTraditional":"〔九〕　師古曰：「微子，殷之卿士，封於微，爵稱子也。殷紂錯亂天命，微子作誥，告箕子、比干而去紂。其誥曰：『用沈酗于酒，用亂敗厥德于下。我其發出狂，吾家耄遜于荒。』事見尚書微子篇。」","sentenceOrder":48},
  {"id":"s_work_han_thu_119_49","chapterId":"ch_work_han_thu_119","textTraditional":"〔一０〕師古曰：「大雅蕩之詩曰：『式號式謼，俾晝作夜。』言醉酒號呼，以晝為夜也。流連，言作詩之人嗟歎，而泣涕流連也。而說者乃以流連為荒亡，蓋失之矣。大雅所以流連，不謂飲酒之人也。謼音火故反。」","sentenceOrder":49},
  {"id":"s_work_han_thu_119_50","chapterId":"ch_work_han_thu_119","textTraditional":"〔一一〕師古曰：「讜言，善言也，音黨。」","sentenceOrder":50},
  {"id":"s_work_han_thu_119_51","chapterId":"ch_work_han_thu_119","textTraditional":"〔一二〕師古曰：「懌，悅也，音亦。」","sentenceOrder":51},
  {"id":"s_work_han_thu_119_52","chapterId":"ch_work_han_thu_119","textTraditional":"〔一三〕孟康曰：「長信，太后宮名也。庭林表，宮中婦人官名也。」師古曰：「長信宮庭之林表也。林表官名耳，庭非官稱也。」","sentenceOrder":52},
  {"id":"s_work_han_thu_119_53","chapterId":"ch_work_han_thu_119","textTraditional":"後上朝東宮，太后泣曰：「帝間顏色瘦黑，〔一〕班侍中本大將軍所舉，宜寵異之，益求其比，以輔聖德。〔二〕宜遣富平侯且就國。」上曰：「諾。」車騎將軍王音聞之，以風丞相御史〔三〕奏富平侯罪過，上乃出放為邊都尉。後復徵入，太后與上書曰：「前所道尚未效，〔四〕富平侯反復來，其能默虖？」〔五〕上謝曰：「請今奉詔。」是時許商為少府，師丹為光祿勳，上於是引商、丹入為光祿大夫，伯遷水衡都尉，與兩師並侍中，〔六〕皆秩中二千石。每朝東宮，常從；及有大政，俱使諭指於公卿。上亦稍厭游宴，復修經書之業，太后甚悅。丞相方進復奏，富平侯竟就國。會伯病卒，年三十八，朝廷愍惜焉。","sentenceOrder":53},
  {"id":"s_work_han_thu_119_54","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「間謂比日也。」","sentenceOrder":54},
  {"id":"s_work_han_thu_119_55","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「比，類也，音必寐反。」","sentenceOrder":55},
  {"id":"s_work_han_thu_119_56","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「風讀曰諷。」","sentenceOrder":56},
  {"id":"s_work_han_thu_119_57","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　張晏曰：「謂上所言『班侍中本大將軍所舉，宜寵異之』。」","sentenceOrder":57},
  {"id":"s_work_han_thu_119_58","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　如淳曰：「富平侯張放復來，太后安能默然不以為言。」","sentenceOrder":58},
  {"id":"s_work_han_thu_119_59","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　如淳曰：「兩師，許商、師丹。」","sentenceOrder":59},
  {"id":"s_work_han_thu_119_60","chapterId":"ch_work_han_thu_119","textTraditional":"斿博學有俊材，左將軍（師）〔史〕丹舉賢良方正，以對策為議郎，遷諫大夫、右曹中郎將，與劉向校祕書。每奏事，〔一〕斿以選受詔進讀群書。〔二〕上器其能，賜以祕書之副。時書不布，〔三〕自東平思王以叔父求太史公、諸子書，大將軍白不許。語在東平王傳。〔四〕斿亦早卒，有子曰嗣，顯名當世。","sentenceOrder":60},
  {"id":"s_work_han_thu_119_61","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「斿每奏校書之事。」","sentenceOrder":61},
  {"id":"s_work_han_thu_119_62","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「於天子前讀書。」","sentenceOrder":62},
  {"id":"s_work_han_thu_119_63","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「謂不出之於群下。」","sentenceOrder":63},
  {"id":"s_work_han_thu_119_64","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　師古曰：「此言東平王求書不得，而斿獲賜祕書，明見寵異。」","sentenceOrder":64},
  {"id":"s_work_han_thu_119_65","chapterId":"ch_work_han_thu_119","textTraditional":"穉少為黃門郎中常侍，方直自守。成帝季年，立定陶王為太子，數遣中盾請問近臣，〔一〕穉獨不敢答。〔二〕哀帝即位，出穉為西河屬國都尉，遷廣平相。","sentenceOrder":65},
  {"id":"s_work_han_thu_119_66","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「盾讀曰允。百官表云詹事之屬官也。漢（書）〔舊〕儀云秩四百石，主徼巡宮中。」","sentenceOrder":66},
  {"id":"s_work_han_thu_119_67","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「言其慎。」","sentenceOrder":67},
  {"id":"s_work_han_thu_119_68","chapterId":"ch_work_han_thu_119","textTraditional":"王莽少與穉兄弟同列友善，兄事斿而弟畜穉。〔一〕斿之卒也，修緦麻，賻賵甚厚。〔二〕平帝即位，太后臨朝，莽秉政，方欲文致太平，〔三〕使使者分行風俗，采頌聲，〔四〕而穉無所上。〔五〕琅邪太守公孫閎言災害於公府，大司空甄豐遣屬馳至兩郡諷吏民〔六〕，而劾閎空造不祥，穉絕嘉應，嫉害聖政，皆不道。太后曰：「不宣德美，宜與言災害者異罰。且後宮賢家，我所哀也。」〔七〕閎獨下獄誅。穉懼，上書陳恩謝罪，願歸相印，入補延陵園郎，太后許焉。食故祿終身。由是班氏不顯莽朝，亦不罹咎。〔八〕","sentenceOrder":68},
  {"id":"s_work_han_thu_119_69","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「事斿如兄，遇穉如弟。」","sentenceOrder":69},
  {"id":"s_work_han_thu_119_70","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「送終者布帛曰賻，車馬曰賵。賻音附。賵音芳鳳反。」","sentenceOrder":70},
  {"id":"s_work_han_thu_119_71","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「言欲以文教致太平。」","sentenceOrder":71},
  {"id":"s_work_han_thu_119_72","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　師古曰：「行音下更反。」","sentenceOrder":72},
  {"id":"s_work_han_thu_119_73","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　師古曰：「不稱符瑞及歌頌。」","sentenceOrder":73},
  {"id":"s_work_han_thu_119_74","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　師古曰：「遣言祥應而隱除災害。」","sentenceOrder":74},
  {"id":"s_work_han_thu_119_75","chapterId":"ch_work_han_thu_119","textTraditional":"〔七〕　師古曰：「班婕妤有賢德，故哀閔其家。」","sentenceOrder":75},
  {"id":"s_work_han_thu_119_76","chapterId":"ch_work_han_thu_119","textTraditional":"〔八〕　師古曰：「罹。遭也。」","sentenceOrder":76},
  {"id":"s_work_han_thu_119_77","chapterId":"ch_work_han_thu_119","textTraditional":"初，成帝性寬，進入直言，是以王音、翟方進等繩法舉過，〔一〕而劉向、杜鄴、王章、朱雲之徒肆意犯上，〔二〕故自帝師安昌侯，諸舅大將軍兄弟及公卿大夫、後宮外屬史許之家有貴寵者，莫不被文傷詆。〔三〕唯谷永嘗言「建始、河平之際，許、班之貴，傾動前朝，熏灼四方，賞賜無量，空虛內臧，女寵至極，不可尚矣；今之後起，天所不饗，什倍於前。」永指以駮譏趙、李，亦無間云。〔四〕","sentenceOrder":77},
  {"id":"s_work_han_thu_119_78","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「論天子之過失。」","sentenceOrder":78},
  {"id":"s_work_han_thu_119_79","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「肆，極也。」","sentenceOrder":79},
  {"id":"s_work_han_thu_119_80","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「詆，毀也，音丁禮反。」","sentenceOrder":80},
  {"id":"s_work_han_thu_119_81","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　師古曰：「雖谷永嘗有此言，而意專在趙、李耳。自餘劉向之徒，又皆不論班氏也。間，非也，音居莧反。」","sentenceOrder":81},
  {"id":"s_work_han_thu_119_82","chapterId":"ch_work_han_thu_119","textTraditional":"穉生彪。彪字叔皮，幼與從兄嗣共遊學，家有賜書，內足於財，好古之士自遠方至，父黨揚子雲以下莫不造門。〔一〕","sentenceOrder":82},
  {"id":"s_work_han_thu_119_83","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「造，至也，音千到反。」","sentenceOrder":83},
  {"id":"s_work_han_thu_119_84","chapterId":"ch_work_han_thu_119","textTraditional":"嗣雖修儒學，然貴老嚴之術。〔一〕桓生欲借其書，〔二〕嗣報曰：「若夫嚴子者，絕聖棄智，修生保真，清虛澹泊，歸之自然〔三〕，獨師友造化，而不為世俗所役者也。漁釣於一壑，則萬物不奸其志；〔四〕栖遲於一丘，則天下不易其樂。不絓聖人之罔，〔五〕不齅驕君之餌，〔六〕蕩然肆志，談者不得而名焉，〔七〕故可貴也。今吾子已貫仁誼之羈絆，繫名聲之韁鎖，〔八〕伏周、孔之軌躅〔九〕，馳顏、閔之極摯，〔一０〕既繫攣於世教矣，何用大道為自眩曜？〔一一〕昔有學步於邯鄲者。曾未得其髣彿，又復失其故步，遂匍匐而歸耳！〔一二〕恐似此類，故不進。」〔一三〕嗣之行己持論如此。","sentenceOrder":84},
  {"id":"s_work_han_thu_119_85","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「老，老子也。嚴，莊周也。」","sentenceOrder":85},
  {"id":"s_work_han_thu_119_86","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「桓譚。」","sentenceOrder":86},
  {"id":"s_work_han_thu_119_87","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「澹泊，安靜也。澹音徒濫反。泊音步各反，又音魄。」","sentenceOrder":87},
  {"id":"s_work_han_thu_119_88","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　師古曰：「奸，犯也，音干。」","sentenceOrder":88},
  {"id":"s_work_han_thu_119_89","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　師古曰：「絓讀與挂同。聖人謂周、孔也。」","sentenceOrder":89},
  {"id":"s_work_han_thu_119_90","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　應劭曰：「齅音六畜之畜。」師古曰：「齅，古嗅字也。餌謂爵祿。君所以制使其臣，亦猶釣魚之設餌也。」","sentenceOrder":90},
  {"id":"s_work_han_thu_119_91","chapterId":"ch_work_han_thu_119","textTraditional":"〔七〕　師古曰：「肆，放也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_119_92","chapterId":"ch_work_han_thu_119","textTraditional":"〔八〕　師古曰：「韁，如馬韁也，音薑。」","sentenceOrder":92},
  {"id":"s_work_han_thu_119_93","chapterId":"ch_work_han_thu_119","textTraditional":"〔九〕　鄭氏曰：「躅，跡也。三輔謂牛蹄處為躅。」師古曰：「躅音丈欲反。」","sentenceOrder":93},
  {"id":"s_work_han_thu_119_94","chapterId":"ch_work_han_thu_119","textTraditional":"〔一０〕劉德曰：「摯，至也，人行之所極至。」","sentenceOrder":94},
  {"id":"s_work_han_thu_119_95","chapterId":"ch_work_han_thu_119","textTraditional":"〔一一〕師古曰：「言用老子、莊周之道何為？但欲以名自炫曜耳。眩音州縣之縣。」","sentenceOrder":95},
  {"id":"s_work_han_thu_119_96","chapterId":"ch_work_han_thu_119","textTraditional":"〔一二〕師古曰：「匍音扶。匐音蒲北反。」","sentenceOrder":96},
  {"id":"s_work_han_thu_119_97","chapterId":"ch_work_han_thu_119","textTraditional":"〔一三〕師古曰：「言不與其書。」","sentenceOrder":97},
  {"id":"s_work_han_thu_119_98","chapterId":"ch_work_han_thu_119","textTraditional":"叔皮唯聖人之道然後盡心焉。〔一〕年二十，遭王莽敗，世祖即位於冀州。時隗囂據壟擁眾，招輯英俊，〔二〕而公孫述稱帝於蜀漢，天下雲擾，〔三〕大者連州郡，小者據縣邑。囂問彪曰：「往者周亡，戰國並爭，天下分裂，數世然後乃定，其抑者從橫之事復起於今乎？〔四〕將承運迭興在於一人也？〔五〕願先生論之。」對曰：「周之廢興與漢異。昔周立爵五等，諸侯從政，〔六〕本根既微，枝葉強大，〔七〕故其末流有從橫之事，其勢然也。漢家承秦之制，並立郡縣，主有專己之威，臣無百年之柄，至於成帝，假借外家，〔八〕哀、平短祚，國嗣三絕，危自上起，傷不及下。故王氏之貴，傾擅朝廷，能竊號位，而不根於民。〔九〕是以即真之後，天下莫不引領而歎，十餘年間，外內騷擾，遠近俱發，假號雲合，咸稱劉氏，不謀而同辭。方今雄桀帶州城者，皆無七國世業之資。詩云：『皇矣上帝，臨下有赫，鑒觀四方，求民之莫。』〔一０〕今民皆謳吟思漢，鄉仰劉氏，已可知矣。」〔一一〕囂曰：「先生言周、漢之勢，可也，至於但見愚民習識劉氏姓號之故，而謂漢家復興，疏矣！昔秦失其鹿，劉季逐而掎之，〔一二〕時民復知漢虖！」既感囂言，又愍狂狡之不息，乃著王命論以救時難。其辭曰：","sentenceOrder":98},
  {"id":"s_work_han_thu_119_99","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　張晏曰：「固不欲言父諱，舉其字耳。」","sentenceOrder":99},
  {"id":"s_work_han_thu_119_100","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「輯與集同。」","sentenceOrder":100},
  {"id":"s_work_han_thu_119_101","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「言盜賊擾亂如雲而起。」","sentenceOrder":101},
  {"id":"s_work_han_thu_119_102","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　師古曰：「抑，語辭。」","sentenceOrder":102},
  {"id":"s_work_han_thu_119_103","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　師古曰：「迭，互也，音大結反。」","sentenceOrder":103},
  {"id":"s_work_han_thu_119_104","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　師古曰：「言諸侯之國各別為政。」","sentenceOrder":104},
  {"id":"s_work_han_thu_119_105","chapterId":"ch_work_han_thu_119","textTraditional":"〔七〕　師古曰：「本根謂王室也。枝葉謂諸侯。」","sentenceOrder":105},
  {"id":"s_work_han_thu_119_106","chapterId":"ch_work_han_thu_119","textTraditional":"〔八〕　師古曰：「假音工暇反。借音子夜反。」","sentenceOrder":106},
  {"id":"s_work_han_thu_119_107","chapterId":"ch_work_han_thu_119","textTraditional":"〔九〕　師古曰：「言無據援。」","sentenceOrder":107},
  {"id":"s_work_han_thu_119_108","chapterId":"ch_work_han_thu_119","textTraditional":"〔一０〕師古曰：「大雅皇矣之詩也。皇，大也。上帝，天也。莫，定也。言大矣天之視下，赫然甚明，監察眾國，求人所定而授之。」","sentenceOrder":108},
  {"id":"s_work_han_thu_119_109","chapterId":"ch_work_han_thu_119","textTraditional":"〔一一〕師古曰：「鄉讀曰嚮。」","sentenceOrder":109},
  {"id":"s_work_han_thu_119_110","chapterId":"ch_work_han_thu_119","textTraditional":"〔一二〕師古曰：「掎，偏持其足也。音居蟻反。」","sentenceOrder":110},
  {"id":"s_work_han_thu_119_111","chapterId":"ch_work_han_thu_119","textTraditional":"昔在帝堯之禪曰：「咨爾舜，天之曆數在爾躬。」舜亦以命禹。〔一〕臮于稷〈契，中“大改卄”〉，咸佐唐虞，〔二〕光濟四海，奕世載德，〔三〕至于湯武，而有天下。雖其遭遇異時，禪代不同，至于應天順民，其揆一也。〔四〕是故劉氏承堯之祚，氏族之世，著乎春秋。〔五〕唐據火德，而漢紹之，始起沛澤，則神母夜號，以章赤帝之符。由是言之，帝王之祚，必有明聖顯懿之德，豐功厚利積絫之業，〔六〕然後精誠通於神明，流澤加於生民，故能為鬼神所福饗，天下所歸往，未見運世無本，功德不紀，〔七〕而得屈起在此位者也。〔八〕世俗見高祖興於布衣，不達其故，以為適遭暴亂，得奮其劍，游說之士至比天下於逐鹿，幸捷而得之，不知神器有命，不可以智力求也。〔九〕悲夫！此世所以多亂臣賊子者也。若然者，豈徒闇於天道哉？又不睹之於人事矣！","sentenceOrder":111},
  {"id":"s_work_han_thu_119_112","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「事見論語。」","sentenceOrder":112},
  {"id":"s_work_han_thu_119_113","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「〈契，中“大改卄”〉讀與卨同，字本作偰。」","sentenceOrder":113},
  {"id":"s_work_han_thu_119_114","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「載，乘也。言相因不絕。」","sentenceOrder":114},
  {"id":"s_work_han_thu_119_115","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　師古曰：「言堯舜以文德相禪，湯武以征伐代興，各上應天命，下順人心。」","sentenceOrder":115},
  {"id":"s_work_han_thu_119_116","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　師古曰：「謂士會歸晉，其處者為劉氏。」","sentenceOrder":116},
  {"id":"s_work_han_thu_119_117","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　師古曰：「絫，古累宇。」","sentenceOrder":117},
  {"id":"s_work_han_thu_119_118","chapterId":"ch_work_han_thu_119","textTraditional":"〔七〕　師古曰：「不紀，不為人所記。」","sentenceOrder":118},
  {"id":"s_work_han_thu_119_119","chapterId":"ch_work_han_thu_119","textTraditional":"〔八〕　師古曰：「屈起，特起也。屈音其勿反。」","sentenceOrder":119},
  {"id":"s_work_han_thu_119_120","chapterId":"ch_work_han_thu_119","textTraditional":"〔九〕　劉德曰：「神器，璽也。」李奇曰：「帝王賞罰之柄也。」師古曰：「李說是也。」","sentenceOrder":120},
  {"id":"s_work_han_thu_119_121","chapterId":"ch_work_han_thu_119","textTraditional":"夫餓饉流隸，飢寒道路，〔一〕思有裋褐之褻，儋石之畜，〔二〕所願不過一金，然終於轉死溝壑。何則？貧窮亦有命也。況虖天子之貴，四海之富，神明之祚，可得而妄處哉？故雖遭罹阨會，竊其權柄，〔三〕勇如信、布，彊如梁、籍，成如王莽，然卒潤鑊伏質，亨醢分裂，〔四〕又況幺{麻骨}，尚不及數子，〔五〕而欲闇奸天位者虖！〔六〕是故駑蹇之乘不騁千里之塗，燕雀之疇不奮六翮之用，楶梲之材不荷棟梁之任，〔七〕斗筲之子不秉帝王之重。〔八〕易曰「鼎折足，覆公餗」，〔九〕不勝其任也。","sentenceOrder":121},
  {"id":"s_work_han_thu_119_122","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「隸，賤隸。」","sentenceOrder":122},
  {"id":"s_work_han_thu_119_123","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「褻謂親身之衣也，音先列反。一說云衣破壞之餘曰褻。儋石，解在蒯通傳，音丁濫反。畜讀曰蓄。」","sentenceOrder":123},
  {"id":"s_work_han_thu_119_124","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「罹亦遭也。音離。」","sentenceOrder":124},
  {"id":"s_work_han_thu_119_125","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　師古曰：「質，鍖也，伏於鍖上而斬之也。鍖音竹林反。」","sentenceOrder":125},
  {"id":"s_work_han_thu_119_126","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　鄭氏曰：「{麻骨}音麼，小也。」晉灼曰：「此骨偏{麻骨}之{麻骨}也。」師古曰：「鄭音是也。幺、{麻骨}，皆微小之稱也。幺音一堯反。麼音莫可反。骨偏{麻骨}自音麻，與此義不相合。晉說失之。」","sentenceOrder":126},
  {"id":"s_work_han_thu_119_127","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　師古曰：「奸音干。」","sentenceOrder":127},
  {"id":"s_work_han_thu_119_128","chapterId":"ch_work_han_thu_119","textTraditional":"〔七〕　師古曰：「楶即薄櫨，所謂枅也。梲，梁上短柱也。楶音節，字亦或作節。梲音之說反。」","sentenceOrder":128},
  {"id":"s_work_han_thu_119_129","chapterId":"ch_work_han_thu_119","textTraditional":"〔八〕　師古曰：「斗筲，言小器也，解在公孫劉田傳。筲音山交反。」","sentenceOrder":129},
  {"id":"s_work_han_thu_119_130","chapterId":"ch_work_han_thu_119","textTraditional":"〔九〕　師古曰：「鼎卦九四爻辭也。餗，食也，音速。」","sentenceOrder":130},
  {"id":"s_work_han_thu_119_131","chapterId":"ch_work_han_thu_119","textTraditional":"當秦之末，豪桀共推陳嬰而王之，嬰母止之曰：「自吾為子家婦，而世貧賤，〔一〕卒富貴不祥，不如以兵屬人，〔二〕事成少受其利，不成禍有所歸。」嬰從其言，而陳氏以寧。王陵之母亦見項氏之必亡，而劉氏之將興也。是時陵為漢將，而母獲於楚，有漢使來，陵母見之，謂曰：「願告吾子，漢王長者，必得天下，子謹事之，無有二心。」遂對漢使伏劍而死，以固勉陵。其後果定於漢，陵為宰相封侯。夫以匹婦之明，〔三〕猶能推事理之致，探禍福之機，而全宗祀於無窮，垂策書於春秋，〔四〕而況大丈夫之事虖！是故窮達有命，吉凶由人，嬰母知廢，陵母知興，審此四者，帝王之分決矣〔五〕。","sentenceOrder":131},
  {"id":"s_work_han_thu_119_132","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「而，汝也。」","sentenceOrder":132},
  {"id":"s_work_han_thu_119_133","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「屬，委也，音之欲反。」","sentenceOrder":133},
  {"id":"s_work_han_thu_119_134","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「凡言匹夫匹婦，謂凡庶之人，一夫一婦當相配匹。」","sentenceOrder":134},
  {"id":"s_work_han_thu_119_135","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　師古曰：「春秋，史書記事之總稱。」","sentenceOrder":135},
  {"id":"s_work_han_thu_119_136","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　師古曰：「分音扶問反。」","sentenceOrder":136},
  {"id":"s_work_han_thu_119_137","chapterId":"ch_work_han_thu_119","textTraditional":"蓋在高祖，其興也有五：〔一〕一曰帝堯之苗裔，二曰體貌多奇異，三曰神武有徵應，四曰寬明而仁恕，五曰知人善任使。加之以信誠好謀，達於聽受，見善如不及，用人如由己，從諫如順流，趣時如嚮赴；〔二〕當食吐哺，納子房之策；拔足揮洗，揖酈生之說；寤戍卒之言，斷懷土之情；〔三〕高四皓之名，割肌膚之愛；〔四〕舉韓信於行陳，收陳平於亡命，英雄陳力，群策畢舉：此高祖之大略，所以成帝業也。若乃靈瑞符應，又可略聞矣。初劉媼任高祖而夢與神遇，〔五〕震電晦冥，有龍蛇之怪。及其長而多靈，有異於眾，是以王、武感物而折券，呂公睹形而進女；秦皇東游以厭其氣，呂后望雲而知所處；〔六〕始受命則白蛇分，西入關則五星聚。故淮陰、留侯謂之天授，非人力也。","sentenceOrder":137},
  {"id":"s_work_han_thu_119_138","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「王命論敘高祖之德，及班氏漢書敘目所稱引，事皆具見本書，不須更解，以穢篇籍。其有辭句隱互，尋覽難知者，則具釋焉。浮汎之說蓋無取也。」","sentenceOrder":138},
  {"id":"s_work_han_thu_119_139","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「嚮讀曰響。如響之赴聲也。」","sentenceOrder":139},
  {"id":"s_work_han_thu_119_140","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「洛陽近沛，高祖來都關中，故云斷懷土之情也。斷音丁喚反。」","sentenceOrder":140},
  {"id":"s_work_han_thu_119_141","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　晉灼曰：「不立戚夫人子。」","sentenceOrder":141},
  {"id":"s_work_han_thu_119_142","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　師古曰：「任謂懷任也。」","sentenceOrder":142},
  {"id":"s_work_han_thu_119_143","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　師古曰：「厭音一葉反。」","sentenceOrder":143},
  {"id":"s_work_han_thu_119_144","chapterId":"ch_work_han_thu_119","textTraditional":"歷古今之得失，驗行事之成敗，稽帝王之世運，考五者之所謂，取舍不厭斯位，符瑞不同斯度，〔一〕而苟昧於權利，越次妄據，〔二〕外不量力，內不知命，則必喪保家之主，失天年之壽，遇折足之凶，伏鈇鉞之誅。〔三〕英雄誠知覺寤，畏若禍戒，〔四〕超然遠覽，淵然深識，收陵、嬰之明分，絕信、布之覬覦，〔五〕距逐鹿之瞽說，審神器之有授，毋貪不可幾，為二母之所咲，〔六〕則福祚流于子孫，天祿其永終矣。","sentenceOrder":144},
  {"id":"s_work_han_thu_119_145","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　劉德曰：「厭，當也。」師古曰：「音一涉反。」","sentenceOrder":145},
  {"id":"s_work_han_thu_119_146","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「昧，貪也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_119_147","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「鈇音方于反。」","sentenceOrder":147},
  {"id":"s_work_han_thu_119_148","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　師古曰：「若，順也。」","sentenceOrder":148},
  {"id":"s_work_han_thu_119_149","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　師古曰：「分音扶問反。覬音冀。覦音踰。」","sentenceOrder":149},
  {"id":"s_work_han_thu_119_150","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　師古曰：「不可幾，謂不可庶幾而望也。一說，幾讀曰冀。」","sentenceOrder":150},
  {"id":"s_work_han_thu_119_151","chapterId":"ch_work_han_thu_119","textTraditional":"知隗囂終不寤，乃避墬於河西。〔一〕河西大將軍竇融嘉其美德，訪問焉。〔二〕舉茂材，為徐令，以病去官。後數應三公之召。仕不為祿，所如不合；〔三〕學不為人，博而不俗；言不為華，述而不作。","sentenceOrder":151},
  {"id":"s_work_han_thu_119_152","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「墬，古地字。」","sentenceOrder":152},
  {"id":"s_work_han_thu_119_153","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「每事皆與謀。」","sentenceOrder":153},
  {"id":"s_work_han_thu_119_154","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「如，往也。不苟得祿，故所往之處，不合其意。」","sentenceOrder":154},
  {"id":"s_work_han_thu_119_155","chapterId":"ch_work_han_thu_119","textTraditional":"有子曰固，弱冠而孤，〔一〕作幽通之賦，以致命遂志。〔二〕其辭曰：","sentenceOrder":155},
  {"id":"s_work_han_thu_119_156","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「謂年二十也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_119_157","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　劉德曰：「致，極也。陳吉凶性命，遂明己之意。」","sentenceOrder":157},
  {"id":"s_work_han_thu_119_158","chapterId":"ch_work_han_thu_119","textTraditional":"系高頊之玄冑兮，氏中葉之炳靈，〔一〕繇凱風而蟬蛻兮，雄朔野以颺聲。〔二〕皇十紀而鴻漸兮，有羽儀於上京。〔三〕巨滔天而泯夏兮，考遘愍以行謠，〔四〕終保己而貽則兮，里上仁之所廬。〔五〕懿前烈之純淑兮，窮與達其必濟，〔六〕咨孤矇之眇眇兮，將圮絕而罔階，〔七〕豈余身之足殉兮？愇世業之可懷。〔八〕","sentenceOrder":158},
  {"id":"s_work_han_thu_119_159","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　應劭曰：「系，連也。冑，緒也。言己高陽顓頊之連緒也。顓頊北方水位，故稱玄。中葉，謂令尹子文也。虎乳，故曰炳靈。」","sentenceOrder":159},
  {"id":"s_work_han_thu_119_160","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　應劭曰：「凱風，南風也。朔，北方也。言先祖自楚遷北，若蟬之蛻也。」師古曰：「繇讀與由同。由，從也。蛻音稅。颺讀與揚同。」","sentenceOrder":160},
  {"id":"s_work_han_thu_119_161","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　應劭曰：「十紀，漢十世也。」張晏曰：「易曰『鴻漸于陸，其羽可以為儀』。成帝時，班況女為婕妤，父子並在京師為朝臣也。」晉灼曰：「皇，漢皇也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_119_162","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　應劭曰：「巨，王莽字巨君也。」張晏曰：「彪遇王莽之敗，憂思歌謠也。」師古曰：「滔，漫也，言不畏天也。泯，滅也。夏，諸夏也。考，班固自言其父也。遘，遇也。愍，憂也。徒歌曰謠。」","sentenceOrder":162},
  {"id":"s_work_han_thu_119_163","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　師古曰：「言其父遭時濁亂，以道自安，終遺盛法而處仁者所居也。論語稱孔子曰：『里仁為美，擇不處仁，焉得智？』故引以為辭。」","sentenceOrder":163},
  {"id":"s_work_han_thu_119_164","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　師古曰：「固自言美前人之餘業，窮則獨善，達能兼濟也。濟合韻音子齊反。」","sentenceOrder":164},
  {"id":"s_work_han_thu_119_165","chapterId":"ch_work_han_thu_119","textTraditional":"〔七〕　師古曰：「眇眇，微細也。圮，毀也。固自言孤弱，懼將毀絕先人之跡，無階路以自成。」","sentenceOrder":165},
  {"id":"s_work_han_thu_119_166","chapterId":"ch_work_han_thu_119","textTraditional":"〔八〕　師古曰：「殉，營也。愇字與韙同。韙，是也。懷，思也。愇音于匪反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_119_167","chapterId":"ch_work_han_thu_119","textTraditional":"靖潛處以永思兮，經日月而彌遠，匪黨人之敢拾兮，庶斯言之不玷。〔一〕魂煢煢與神交兮，精誠發於宵寐，夢登山而迥眺兮，覿幽人之髣彿，〔二〕〈扌監〉葛藟而授余兮，眷峻谷曰勿隧。〔三〕昒昕寤而仰思兮，心蒙蒙猶未察，〔四〕黃神邈而靡質兮，儀遺讖以臆對。〔五〕曰乘高而遌神兮，道遐通而不迷，〔六〕葛綿綿於樛木兮，詠南風以為綏，〔七〕蓋惴惴之臨深兮，乃二雅之所祗。〔八〕既誶爾以吉象兮，又申之以炯戒：〔九〕盍孟晉以迨群兮？辰焂忽其不再。〔一０〕","sentenceOrder":167},
  {"id":"s_work_han_thu_119_168","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　（師古）〔蘇林〕曰：「拾音負拾之拾。」應劭曰：「拾，更也。自謙不敢與鄉人更進也。」師古曰：「靖，古靜字也。拾音其業反。玷，缺也。更音工衡反。」","sentenceOrder":168},
  {"id":"s_work_han_thu_119_169","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　張晏曰：「幽人，神人也。」師古曰；「覿，見也，音迪。」","sentenceOrder":169},
  {"id":"s_work_han_thu_119_170","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「〈扌監〉，執取也。言入峻谷者當攀葛藟，可以免於顛墜，猶處時俗者當據道義，然後得用自立。故設此喻，託以夢也。葛藟，蔓也。一說，藟，葛屬也。葛之與藟，皆有蔓焉。〈扌監〉音攬。其字從手。藟音力水反。」","sentenceOrder":170},
  {"id":"s_work_han_thu_119_171","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　孟康曰：「昒昕，早旦也。覺寤思念，未知其吉凶也。」師古曰：「昒音忽。昕音欣。」","sentenceOrder":171},
  {"id":"s_work_han_thu_119_172","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　應劭曰：「黃帝善占夢，久遠無從得問，準其讖書，以意求其象也。賈誼曰『讖言其度』。」應劭曰：「臆，胸臆也。」師古曰：「對，合韻音丁忽反。」","sentenceOrder":172},
  {"id":"s_work_han_thu_119_173","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　師古曰：「登山見神，故曰乘高也。遌，遇也，音五故反，又音五各反。」","sentenceOrder":173},
  {"id":"s_work_han_thu_119_174","chapterId":"ch_work_han_thu_119","textTraditional":"〔七〕　應劭曰：「周南國風其詩曰：『南有樛木，葛藟纍之，樂只君子，福履綏之。』師古曰：「樛木，下垂之木也。綏，安也。樛音居虯反。纍音力追反。」","sentenceOrder":174},
  {"id":"s_work_han_thu_119_175","chapterId":"ch_work_han_thu_119","textTraditional":"〔八〕　師古曰：「詩小雅小宛之篇曰：『惴惴小心，如臨于谷。』惴惴，恐懼之貌也。小旻篇曰：『戰戰兢兢，如臨深淵，如履薄冰。』言恐墜陷也。故云二雅之所祗。惴音之瑞反。」","sentenceOrder":175},
  {"id":"s_work_han_thu_119_176","chapterId":"ch_work_han_thu_119","textTraditional":"〔九〕　師古曰：「誶，告也。炯，明也。誶音碎。炯音公迥反。」","sentenceOrder":176},
  {"id":"s_work_han_thu_119_177","chapterId":"ch_work_han_thu_119","textTraditional":"〔一０〕服虔曰：「盍，何不也。孟，勉也。晉，進也。迨，及也。何不早進仕以及輩也？」師古曰：「辰，時也。焂忽，疾也。言時疾過，不再來也。焂音式六反。」","sentenceOrder":177},
  {"id":"s_work_han_thu_119_178","chapterId":"ch_work_han_thu_119","textTraditional":"承靈訓其虛徐兮，竚盤桓而且俟，〔一〕惟天墬之無窮兮，鱻生民之脢在。〔二〕紛屯亶與蹇連兮，何艱多而智寡！〔三〕上聖寤而後拔兮，豈群黎之所御！〔四〕昔衛叔之御昆兮，昆為寇而喪予。〔五〕管彎弧欲斃讎兮，讎作后而成己。〔六〕變化故而相詭兮，孰云豫其終始！〔七〕雍造怨而先賞兮，丁繇惠而被戮；〔八〕〈桌，中“一改仌”〉取弔于逌吉兮，王膺慶於所慼。〔九〕畔回宂其若茲兮，北叟頗識其倚伏。〔一０〕單治裏而外凋兮，張修襮而內逼，〔一一〕欥中龢為庶幾兮，顏與冉又不得。〔一二〕溺招路以從己兮，謂孔氏猶未可，安慆慆而不萉兮，卒隕身虖世禍。〔一三〕游聖門而靡救兮，顧覆醢其何補？〔一四〕固行行其必凶兮，免盜亂為賴道；〔一五〕形氣發于根柢兮，柯葉彙而靈茂。〔一六〕恐网蜽之責景兮，慶未得其云已。〔一七〕","sentenceOrder":178},
  {"id":"s_work_han_thu_119_179","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　孟康曰：「虛徐，懷疑也。」張晏曰：「佇，久也。俟，待也。」","sentenceOrder":179},
  {"id":"s_work_han_thu_119_180","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　晉灼曰：「鱻，古鮮字也。」應劭曰：「脢，無幾也。」師古曰：「墬，古地字也。鱻，少也。言天地長久而人壽短促也。鱻音先踐反。」","sentenceOrder":180},
  {"id":"s_work_han_thu_119_181","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　孟康曰：「世艱難多，智者少，故遇禍也。」師古曰：「易屯卦六二爻辭曰『屯如亶如』，蹇卦六四爻辭曰『往蹇來連』，皆謂險難之時也。亶音竹延反。連音力善反。」","sentenceOrder":181},
  {"id":"s_work_han_thu_119_182","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　師古曰：「黎，眾也。言上聖之人猶遇紛難，睹機能寤，然後自拔。文王羑里，孔子於匡是也。至於眾庶，豈能豫禦之哉？」","sentenceOrder":182},
  {"id":"s_work_han_thu_119_183","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　孟康曰：「御，迎也。昆，兄也。衛叔武迎兄成公，成公令前驅，射殺之。」師古曰：「御音五駕反。衛叔，解在五行志。」","sentenceOrder":183},
  {"id":"s_work_han_thu_119_184","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　師古曰：「謂管仲射桓公中帶鉤，桓公反國，以為相也。」","sentenceOrder":184},
  {"id":"s_work_han_thu_119_185","chapterId":"ch_work_han_thu_119","textTraditional":"〔七〕　師古曰：「詭，違也。」","sentenceOrder":185},
  {"id":"s_work_han_thu_119_186","chapterId":"ch_work_han_thu_119","textTraditional":"〔八〕　師古曰：「雍，雍齒也。丁，丁公也。繇讀與由同。」","sentenceOrder":186},
  {"id":"s_work_han_thu_119_187","chapterId":"ch_work_han_thu_119","textTraditional":"〔九〕　應劭曰：「〈桌，中“一改仌”〉，孝景姬也，有子而以妒見廢。王，宣帝王婕也，以無子為憂，而以謹敕得母元帝也。」師古曰：「逌，古攸字也。攸亦所也。」","sentenceOrder":187},
  {"id":"s_work_han_thu_119_188","chapterId":"ch_work_han_thu_119","textTraditional":"〔一０〕師古曰：「畔，亂貌也。回宂，轉旋之意也。叟，老人稱也。淮南子曰：『北塞上之人，其馬無故亡入胡中，人皆弔之。其父曰：「此何詎不為福？」居數月，其馬將胡駿馬而歸，人皆賀之。對曰：「此何詎不為禍？」家富馬良，其子好騎，墯而折髀，人皆弔之。對曰：「此何詎不為福？」居一年，胡夷大入，丁壯者皆控弦而戰，塞上之人死者十九，此獨以跛之故，父子相保。』老子德經曰：『禍兮福所倚，福兮禍所伏。』故頗識其倚伏。倚音於綺反。」","sentenceOrder":188},
  {"id":"s_work_han_thu_119_189","chapterId":"ch_work_han_thu_119","textTraditional":"〔一一〕應劭曰：「單，單豹也，靜居其所，以理五內，處深山，為虎所食。張，張毅也，外修恭敬，斯徒馬圉皆與亢禮，不勝其勞，內熱而死。」師古曰：「襮，表也。單音善。襮音布谷反。」","sentenceOrder":189},
  {"id":"s_work_han_thu_119_190","chapterId":"ch_work_han_thu_119","textTraditional":"〔一二〕師古曰：「欥，古聿字也。龢，古和字也。聿，曰也。曰中和之道可以庶幾免於禍難，而顏回早死，冉耕惡疾，為善之人又不得其報也。」","sentenceOrder":190},
  {"id":"s_work_han_thu_119_191","chapterId":"ch_work_han_thu_119","textTraditional":"〔一三〕鄧展曰：「慆慆，亂貌也。萉，避也。」師古曰：「溺，桀溺也。路，子路也。論語稱『長沮、桀溺耦而耕，孔子過之，使子路問津焉。桀溺曰：「子，孔丘之徒歟？」對曰：「然。」曰：「慆慆者，天下皆是也。而誰以易之？且而與其從避人之士，豈若從避世之士哉？』言天下皆亂，汝將用誰變易之乎？避人之士謂孔子，避世之士溺自謂也。而子路安之，卒不能避，乃遇蒯瞶之亂，身死敵也。慆音土高反。萉音扶味反，字本作腓，其音同。」","sentenceOrder":191},
  {"id":"s_work_han_thu_119_192","chapterId":"ch_work_han_thu_119","textTraditional":"〔一四〕師古曰：「禮記曰：『孔子哭子路於中庭。既哭，進使者而問故。使者曰；「醢之矣。」遂命覆醢。』賦言子路游於聖人之門，而孔子不能救之以免於難，雖為覆醢，無所補益。」","sentenceOrder":192},
  {"id":"s_work_han_thu_119_193","chapterId":"ch_work_han_thu_119","textTraditional":"〔一五〕師古曰：「論語稱『閔子侍側，誾誾如也；子路，行行如也。子樂，曰：「若由也，不得其死然。」』又稱『子路曰：「君子尚勇乎？」曰：「君子義以為上。君子有勇而無義為亂，小人有勇而無義為盜。」』賦言子路稟行行之性，其凶必也，所以免為於亂盜者，賴聞道於孔子也。行行，剛強之貌。行音胡浪反。」","sentenceOrder":193},
  {"id":"s_work_han_thu_119_194","chapterId":"ch_work_han_thu_119","textTraditional":"〔一六〕師古曰：「柢，本也。彙，盛也。靈，善也。言草木本根氣強，則枝葉盛而善美；人之先祖有大功德，則胤緒亦蕃昌也。柢音丁計反。茂合韻音莫口反。」","sentenceOrder":194},
  {"id":"s_work_han_thu_119_195","chapterId":"ch_work_han_thu_119","textTraditional":"〔一七〕師古曰：「慶，發語辭，讀與羌同。已，止也。莊子云：『网兩問景曰：「曩子行，今子止，曩子坐，今子起，何其無持操歟？」景曰：「吾有待而然。吾所待，又有待而然。」』賦言景之行止皆隨於形，草木枝葉各稟根柢，人之餘慶資以積善，亦猶此也。」","sentenceOrder":195},
  {"id":"s_work_han_thu_119_196","chapterId":"ch_work_han_thu_119","textTraditional":"黎淳耀于高辛兮，羋彊大於南汜；〔一〕嬴取威於百儀兮，姜本支虖三止：〔二〕既仁得其信然兮，卬天路而同軌。〔二〕東厸虐而殲仁兮，王合位虖三五；〔四〕戎女烈而喪孝兮，伯徂歸於龍虎：〔五〕發還師以成性兮，重醉行而自耦。〔六〕震鱗漦于夏庭兮，匝三正而滅（周）〔姬〕；〔七〕巽羽化于宣宮兮，彌五辟而成災。〔八〕","sentenceOrder":196},
  {"id":"s_work_han_thu_119_197","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　應劭曰：「黎，楚之先也。（醇）〔淳〕，美也。高辛，帝嚳之號。羋，楚姓。汜，（崖）〔涯〕也。」師古曰：「言黎在高辛之時為火正，有美光耀，故其後嗣霸有楚國於南方也。汜，江水之別也，音祀。召南之詩曰『江有汜』。羋音弭。」","sentenceOrder":197},
  {"id":"s_work_han_thu_119_198","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　應劭曰：「嬴，秦姓也，伯益之後也。伯益為虞，有儀鳥獸百物之功，秦所由取威於六國也。姜，齊姓也。止，禮也。齊，伯夷之後。伯夷為秩宗，典天地人鬼之禮也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_119_199","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　劉德曰：「人道既然，仰視天道，又同法也。」師古曰：「仁得，謂求仁而得仁。卬讀曰仰。」","sentenceOrder":199},
  {"id":"s_work_han_thu_119_200","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　應劭曰：「東厸，紂也。殲，盡也。王，武王也。欲合五位三所，即國語歲日月星辰之所在也。」師古曰：「厸，古鄰字也。仁即三仁也。國語稱泠州鳩對景王曰：『昔武王伐殷，歲在鶉火，月在天駟，日在析木之津，辰在斗杓，星在天黿。星與日辰之位皆在北維，顓頊之所建也，我姬氏出自天黿。又析木者，有建星及牽牛焉，則我皇妣大姜之姓。伯陵之後，逢公之所憑神也。歲之所在，則我有周之分野也。月之所在，辰為農祥也，我太祖后稷之所經緯也。王欲合是五位三所而用之。』五位，謂歲日月辰星也。三所，謂逢公所憑神，周分野所在，后稷所經緯也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_119_201","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　孟康曰；「伯，晉文公也。歲在卯出，歷十九年，過一周，歲在酉入；卯為龍，酉為虎也。」師古曰：「戎女，驪戎之女，謂驪姬也。烈，酷也。孝謂太子申生也。伯讀曰霸，言文公霸諸侯也。徂，往也。言以龍往出，以（獸）〔虎〕歸入也。」","sentenceOrder":201},
  {"id":"s_work_han_thu_119_202","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　師古曰：「發，武王名也。性，命也。武王初觀兵於孟津，八百諸侯不期而會，皆曰紂可伐矣。武王曰：『爾未知天性。』還師二年，紂殺比干，囚箕子，武王乃伐克之，於是成天命也。重謂重耳，晉文公名也。耦，合也。文公初出奔至齊，齊桓公妻之，有馬二十乘。文公欲安之，齊姜乃與子犯謀，醉而遣之。後遂反國，與時會也。」","sentenceOrder":202},
  {"id":"s_work_han_thu_119_203","chapterId":"ch_work_han_thu_119","textTraditional":"〔七〕　應劭曰：「易震為龍，鱗蟲之長也。漦，沬也。」師古曰：「謂褒姒也，解在五行志。三正，歷夏、殷、周也。漦音丑之反。正音之盈反。」","sentenceOrder":203},
  {"id":"s_work_han_thu_119_204","chapterId":"ch_work_han_thu_119","textTraditional":"〔八〕　應劭曰：「易巽為雞，羽蟲也。宣帝時，未央宮路軨廄中雌雞化為雄，元后統政之祥也。至平帝，歷五世而王莽篡位。」","sentenceOrder":204},
  {"id":"s_work_han_thu_119_205","chapterId":"ch_work_han_thu_119","textTraditional":"道悠長而世短兮，敻冥默而不周，〔一〕胥仍物而鬼諏兮，乃窮宙而達幽。〔二〕媯巢姜於孺筮兮，旦算祀于挈龜。〔三〕宣、曹興敗於下夢兮，魯、衛名諡於銘謠。〔四〕妣聆呱而刻石兮，許相理而鞠條。〔五〕道混成而自然兮，術同原而分流。〔六〕神先心以定命兮，命隨行以消息。〔七〕斡流遷其不濟兮，故遭罹而贏縮〔八〕。三欒同於一體兮，雖移盈然不忒。〔九〕洞參差其紛錯兮，斯眾兆之所惑。〔一０〕周、賈盪而貢憤兮，齊死生與禍福，〔一一〕抗爽言以矯情兮，信畏犧而忌服。〔一二〕","sentenceOrder":205},
  {"id":"s_work_han_thu_119_206","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　劉德曰：「敻，遠也。周，至也。冥默，玄深不可通至也。」","sentenceOrder":206},
  {"id":"s_work_han_thu_119_207","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　應劭曰：「胥，須也。仍，因也。諏，謀也。易曰：『人謀鬼謀，百姓與能。』往古來今曰宙。聖人須因卜筮，然後謀鬼神，極古今，通幽微也。」","sentenceOrder":207},
  {"id":"s_work_han_thu_119_208","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　應劭曰：「媯，陳姓也。巢，居也。姜，齊姓也。孺，少也。陳完少時，其父厲公使周史卜，得居有齊國之卦也。」李奇曰：「算，數也。祀，年也。周公卜居洛，得世三十，年七百也。」師古曰；「挈，刻也。詩大雅綿綿之篇曰『爰挈我龜』，言刻開之，灼而卜之。挈音口計反。」","sentenceOrder":208},
  {"id":"s_work_han_thu_119_209","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　應劭曰：「周宣王牧人夢眾魚與旟旐之祥，而中興。曹伯陽國人夢眾君子立于社宮，謀亡曹，而曹亡也。」孟康曰：「魯文成之世，童謠言『稠父喪勞，宋父以驕』。後昭公名稠，遂死於野井。定公名宋，即位而驕。衛靈公掘地得石槨，其銘曰『靈公』，遂以為諡。」","sentenceOrder":209},
  {"id":"s_work_han_thu_119_210","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　應劭曰：「妣，叔向之母也。石，叔向之子也。聽其啼聲刻，知其後必滅羊舌氏。許負相周亞夫，從理入口，當餓死。鞠，窮也。條，亞夫所封也。」師古曰：「鞠，告也。」","sentenceOrder":210},
  {"id":"s_work_han_thu_119_211","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　師古曰：「大道混壹，歸於自然，人之所趨雖有流別，本則同耳。」","sentenceOrder":211},
  {"id":"s_work_han_thu_119_212","chapterId":"ch_work_han_thu_119","textTraditional":"〔七〕　師古曰：「言神明之道，雖在人心之前已定命矣，然亦隨其所行，以致禍福。」","sentenceOrder":212},
  {"id":"s_work_han_thu_119_213","chapterId":"ch_work_han_thu_119","textTraditional":"〔八〕　師古曰：「斡，轉也。言人之生，各有遭遇，不能必濟，免於困厄，各隨其所逢以致贏虧也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_119_214","chapterId":"ch_work_han_thu_119","textTraditional":"〔九〕　孟康曰：「晉大夫欒書，書子黶，黶子盈。書賢而覆黶，黶惡而害盈也。」師古曰：「欒書，欒武子也。黶，欒桓子也。盈，欒懷子也。春秋左氏傳稱秦伯問於士鞅曰：『晉大夫其誰先亡？』對曰：『其欒氏乎！欒黶汰虐以甚，猶可以免。其在盈乎！武子之德在人，如周人之思邵公，愛其甘棠，況其子乎？欒黶死，盈之善未能及人。武子所施沒矣，黶之惡實彰，將於是乎在。』其後至襄公二十一年，終為范宣子所逐，而出奔楚，自楚適齊。二十三年，自齊入于晉，晉人遂滅欒氏也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_119_215","chapterId":"ch_work_han_thu_119","textTraditional":"〔一０〕師古曰：「眾兆，兆庶也。」","sentenceOrder":215},
  {"id":"s_work_han_thu_119_216","chapterId":"ch_work_han_thu_119","textTraditional":"〔一一〕孟康曰：「莊周、賈誼也。貢，惑也。憤，亂也。放盪惑亂死生禍福之正也。」","sentenceOrder":216},
  {"id":"s_work_han_thu_119_217","chapterId":"ch_work_han_thu_119","textTraditional":"〔一二〕孟康曰：「莊周不欲為犧牛，賈誼惡忌服鳥也。」師古曰：「抗，舉也。爽，差也。謂二人雖舉言齊死生，壹禍福，而心實不然，是差謬也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_119_218","chapterId":"ch_work_han_thu_119","textTraditional":"所貴聖人之至論兮，順天性而斷誼。〔一〕物有欲而不居兮，亦有惡而不避，〔二〕守孔約而不貳兮，乃輶德而無累。〔三〕三仁殊而一致兮，夷、惠舛而齊聲。〔四〕木偃息以蕃魏兮，申重繭以存荊。〔五〕紀焚躬以衛上兮，皓頤志而弗營。〔六〕侯屮木之區別兮，苟能實而必榮。要沒世而不朽兮，乃先民之所程。〔七〕","sentenceOrder":218},
  {"id":"s_work_han_thu_119_219","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「斷誼，謂以誼斷之。斷音丁喚反。」","sentenceOrder":219},
  {"id":"s_work_han_thu_119_220","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「言富貴人之所欲，不以其道則君子不居；死亡人之所惡，處得其節則君子不避也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_119_221","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「孔，甚也。輶，輕也。言守其甚約，執心不貳，舉德至輕，無所累惑，斯為可矣。詩大雅烝人之篇曰：『德輶如毛，人鮮克舉之。』輶音弋九反，又音猶。」","sentenceOrder":221},
  {"id":"s_work_han_thu_119_222","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　師古曰：「三仁，紂賢臣也。論語稱『微子去之，箕子為之奴，比干諫而死』。孔子曰：『殷有三仁焉。』夷，伯夷也。惠，柳下惠也。論語又稱『逸人伯夷、叔齊、虞仲、夷逸、朱張、柳下惠、少連』。賦言微子、箕子、比干所行各異，而並稱仁。伯夷不義武王伐殷，至于不食周粟而死。柳下惠三黜不去，戀父母之邦。志執乖舛，俱有令名。」","sentenceOrder":222},
  {"id":"s_work_han_thu_119_223","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　師古曰：「木，段干木也。客居魏，魏文侯敬而禮之，過其閭未嘗不軾也。秦欲伐魏，或諫曰：『魏君賢者是禮，國人稱（人）〔仁〕，未可圖也。』秦遂止兵。申謂申包胥。荊即楚也。繭，足下傷起如繭也。楚昭王時，吳師入郢，昭王出奔。申包胥如秦乞師，踰越險阻，曾繭重胝，立於秦庭，號哭七日。秦哀公出師救楚，而敗吳師。昭王反國，將賞包胥。包胥辭曰：『吾所以重繭為君耳，非為身也。』逃不受賞。」","sentenceOrder":223},
  {"id":"s_work_han_thu_119_224","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　師古曰：「紀，紀信也，脫漢王於難而為項羽所燒。皓，四皓也，處商洛深山，高祖求之不得，自養其志，無所營屈。」","sentenceOrder":224},
  {"id":"s_work_han_thu_119_225","chapterId":"ch_work_han_thu_119","textTraditional":"〔七〕　應劭曰：「侯，維也。」張晏曰：「苟能有仁義之道，必有榮名也。」師古曰：「侯，發語辭也。爾雅曰：『伊、惟，侯也。』程，正也。言人之操行，所尚不同，立德立言，期于不朽，亦猶蘭蕙松栝，各有本性，馨烈材幹，並擅貞芳。此乃古昔賢人以為正道也。論語稱子夏曰『君子之道，譬諸草木，區以別矣』，故賦引之。」","sentenceOrder":225},
  {"id":"s_work_han_thu_119_226","chapterId":"ch_work_han_thu_119","textTraditional":"觀天罔之紘覆兮，實棐諶而相順，〔一〕謨先聖之大繇兮，亦厸德而助信。〔二〕虞韶美而儀鳳兮，孔忘味於千載。〔三〕素文信而底麟兮，漢賓祚于異代。〔四〕精通靈而感物兮，神動氣而入微。養游睇而猿號兮，李虎發而石開。〔五〕非精誠其焉通兮，苟無實其孰信！〔六〕操末技猶必然兮，矧湛躬於道真！〔七〕","sentenceOrder":226},
  {"id":"s_work_han_thu_119_227","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　應劭曰：「棐，輔也。諶，誠也。相，助也。」師古曰：「尚書大誥曰：『天棐諶辭。』詩大雅蕩之篇曰：『天生烝人，其命匪諶。』易上繫辭曰：『天之所助者，順也。』賦言天道惟誠是輔，唯順是助，故引以為辭也。棐讀與匪同。諶音上林反。」","sentenceOrder":227},
  {"id":"s_work_han_thu_119_228","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　劉德曰：「厸，近也。」師古曰：「謨，謀也。繇，道也。厸，古鄰字。詩小雅巧言之篇曰：『秩秩大繇，聖人謨之。』論語稱孔子曰：『德不孤，必有鄰。』易上繫辭曰：『人之所助者信也。』賦言若能謀聖人之大道，有德者必為同志所依，履信者必獲他人之助。謨音摹，又音莫。」","sentenceOrder":228},
  {"id":"s_work_han_thu_119_229","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「韶，舜樂名也。虞書舜典曰：『簫韶九成，鳳皇來儀。』論語云。『孔子在齊聞韶，三月不知肉味。』賦言孔子去舜千歲也。」","sentenceOrder":229},
  {"id":"s_work_han_thu_119_230","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　應劭曰：「底，致也。孔子作春秋素王之文，有視明禮修之信，而致麟。漢封其後為褒成，又紹嘉公係殷後，為二代之客。」","sentenceOrder":230},
  {"id":"s_work_han_thu_119_231","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　師古曰：「養，養由基也，楚之善射者。游睇，流眄也。楚王使由基射猿，操弓而眄之，猿抱木而號，知其必見中也。李，李廣也，夜遇石，以為猛獸而射之，中石沒羽也。」","sentenceOrder":231},
  {"id":"s_work_han_thu_119_232","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　師古曰：「信，合韻音新。」","sentenceOrder":232},
  {"id":"s_work_han_thu_119_233","chapterId":"ch_work_han_thu_119","textTraditional":"〔七〕　師古曰：「矧，況也。湛讀曰眈。躬，親也。射者微技，猶能精誠感於猿石，況立身種德，親眈大道而不倦者乎！」","sentenceOrder":233},
  {"id":"s_work_han_thu_119_234","chapterId":"ch_work_han_thu_119","textTraditional":"登孔、顥而上下兮，緯群龍之所經，〔一〕朝貞觀而夕化兮，猶諠己而遺形，〔二〕若胤彭而偕老兮，訴來哲以通情。〔三〕","sentenceOrder":234},
  {"id":"s_work_han_thu_119_235","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　應劭曰：「顥，太顥也。孔，孔子也。群龍喻群聖也。自伏羲下訖孔子，終始天道備矣。」孟康曰：「孔，甚也。顥，大也。聖人作經，賢者緯之也。」師古曰：「應說孔、顥，是也。孟說經緯，是也。顥音胡老反。」","sentenceOrder":235},
  {"id":"s_work_han_thu_119_236","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　應劭曰：「貞，正也。觀，見也。諠，忘也。易曰：『天地之道，貞觀者也。』」張晏曰：「言朝觀大道而夕死可也。」師古曰：「形己尚可遺忘，況外物者哉？誼音許元反，又音許遠反。」","sentenceOrder":236},
  {"id":"s_work_han_thu_119_237","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「彭，彭祖也。老，老耼也。言有繼續彭祖之志，升躡老耼之跡者，則可與言至道而通情也。」","sentenceOrder":237},
  {"id":"s_work_han_thu_119_238","chapterId":"ch_work_han_thu_119","textTraditional":"亂曰：天造屮昧，立性命兮，〔一〕復心弘道，惟賢聖兮。〔二〕渾元運物，流不處兮，〔三〕","sentenceOrder":238},
  {"id":"s_work_han_thu_119_239","chapterId":"ch_work_han_thu_119","textTraditional":"保身遺名，民之表兮。舍生取誼，亦道用兮，〔四〕憂傷夭物，忝莫痛兮！〔五〕昊爾太素，","sentenceOrder":239},
  {"id":"s_work_han_thu_119_240","chapterId":"ch_work_han_thu_119","textTraditional":"曷渝色兮？〔六〕尚粵其幾，淪神域兮！〔七〕","sentenceOrder":240},
  {"id":"s_work_han_thu_119_241","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　應劭曰：「天道始造萬物，草創於冥昧之中，皆立其性命也。」師古曰：「易屯卦彖辭曰『天造草昧』，故賦引之。」","sentenceOrder":241},
  {"id":"s_work_han_thu_119_242","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　應劭曰：「易曰：『復其見天地之心乎！』論語曰：『人能弘道。』」師古曰：「復音扶目反。」","sentenceOrder":242},
  {"id":"s_work_han_thu_119_243","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「渾元，天地之氣也。處，止也。渾音胡昆反。」","sentenceOrder":243},
  {"id":"s_work_han_thu_119_244","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　應劭曰：「孟子曰：『生，我所欲也；義，我所欲也。二者不可得兼，舍生而取義也。』」師古曰：「舍，置也。」","sentenceOrder":244},
  {"id":"s_work_han_thu_119_245","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　晉灼曰：「忝，沒也，言死莫痛於是也。」師古曰：「此說非也。忝，辱也。言不達性命，自取憂傷，為物所夭，既辱且痛，莫過於是。」","sentenceOrder":245},
  {"id":"s_work_han_thu_119_246","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　服虔曰：「守死善道，不染流俗，是為浩爾太素，何有變渝者哉？」師古曰：「渝音踰。」","sentenceOrder":246},
  {"id":"s_work_han_thu_119_247","chapterId":"ch_work_han_thu_119","textTraditional":"〔七〕　應劭曰：「尚，上也，粵，於也。易曰：『知幾，其神乎！』淪，入也。」師古曰：「尚，庶幾也，願也。」","sentenceOrder":247},
  {"id":"s_work_han_thu_119_248","chapterId":"ch_work_han_thu_119","textTraditional":"永平中為郎，典校祕書，專篤志於博學，以著述為業。或譏以無功，又感東方朔、揚雄自諭以不遭蘇、張、范、蔡之時，曾不折之以正道，明君子之所守，故聊復應焉。其辭曰：","sentenceOrder":248},
  {"id":"s_work_han_thu_119_249","chapterId":"ch_work_han_thu_119","textTraditional":"賓戲主人曰：「蓋聞聖人有壹定之論，列士有不易之分，亦云名而已矣。〔一〕故太上有立德，其次有立功。夫德不得後身而特盛，功不得背時而獨章，是以聖喆之治，棲棲皇皇，〔二〕孔席不煗，墨突不黔。〔三〕由此言之，取舍者昔人之上務，著作者前列之餘事耳。〔四〕今吾子幸游帝王之世，躬帶冕之服，〔五〕浮英華，湛道德，〔六〕矕龍虎之文，舊矣。〔七〕卒不能攄首尾，奮翼鱗，振拔洿塗，跨騰風雲，〔八〕使見之者景駭，聞之者嚮震。〔九〕徒樂枕經籍書，紆體衡門，〔一０〕上無所蔕，下無所根。獨攄意虖宇宙之外，銳思於豪芒之內，潛神默記，恆以年歲。〔一一〕然而器不賈於當己，用不效於一世，〔一二〕　雖馳辯如濤波，摛藻如春華，〔一三〕猶無益於殿最。〔一四〕意者，且運朝夕之策，定合會之計，使存有顯號，亡有美諡，不亦優虖？」","sentenceOrder":249},
  {"id":"s_work_han_thu_119_250","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　如淳曰：「唯貴得名也。」","sentenceOrder":250},
  {"id":"s_work_han_thu_119_251","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「不安之意也。」","sentenceOrder":251},
  {"id":"s_work_han_thu_119_252","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　師古曰：「孔，孔子；墨，墨翟也。突，灶突也。黔，黑也。言志在明道，不暇安居。」","sentenceOrder":252},
  {"id":"s_work_han_thu_119_253","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　劉德曰：「取者，施行道德；舍者，守靜無為也。」","sentenceOrder":253},
  {"id":"s_work_han_thu_119_254","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　師古曰：「帶，大帶也。冕，冠也。」","sentenceOrder":254},
  {"id":"s_work_han_thu_119_255","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　師古曰：「湛讀曰沈。英華，謂名譽也。言外則有美名善譽，內則履道崇德也。」","sentenceOrder":255},
  {"id":"s_work_han_thu_119_256","chapterId":"ch_work_han_thu_119","textTraditional":"〔七〕　孟康曰：「矕，被也。易曰『大人虎變，其文炳也』，言文章之盛久也。」晉灼曰：「矕，視也。言目厭見其文久矣。」師古曰：「尋其下句，孟說是也。矕音莫限反。」","sentenceOrder":256},
  {"id":"s_work_han_thu_119_257","chapterId":"ch_work_han_thu_119","textTraditional":"〔八〕　師古曰：「攄，申也。洿，停水也。塗，泥也。以龍為喻也。洿音一故反，又音烏。」","sentenceOrder":257},
  {"id":"s_work_han_thu_119_258","chapterId":"ch_work_han_thu_119","textTraditional":"〔九〕　師古曰：「嚮讀曰響。見景則駭，聞嚮則震。合韻音之人反。」","sentenceOrder":258},
  {"id":"s_work_han_thu_119_259","chapterId":"ch_work_han_thu_119","textTraditional":"〔一０〕師古曰：「紆，屈也。衡門，橫一木於門上。」","sentenceOrder":259},
  {"id":"s_work_han_thu_119_260","chapterId":"ch_work_han_thu_119","textTraditional":"〔一一〕如淳曰：「恒音亘竟之亘。」師古曰：「宇宙之外，言宏廣也。豪芒之內，喻纖微也。恒音工贈反。」","sentenceOrder":260},
  {"id":"s_work_han_thu_119_261","chapterId":"ch_work_han_thu_119","textTraditional":"〔一二〕劉德曰：「賈，讎也。」師古曰：「當己，謂及己身尚在，猶言當年也。賈音古，又音工暇反。讎音上究反。」","sentenceOrder":261},
  {"id":"s_work_han_thu_119_262","chapterId":"ch_work_han_thu_119","textTraditional":"〔一三〕師古曰：「大波曰濤。摛，布也。藻，文辭也。」","sentenceOrder":262},
  {"id":"s_work_han_thu_119_263","chapterId":"ch_work_han_thu_119","textTraditional":"〔一四〕師古曰：「殿音丁見反。」","sentenceOrder":263},
  {"id":"s_work_han_thu_119_264","chapterId":"ch_work_han_thu_119","textTraditional":"主人逌爾而咲曰：〔一〕「若賓之言，斯所謂見勢利之華，闇道德之實，守穾奧之熒燭，未卬天庭而睹白日也。〔二〕曩者王塗蕪穢，周失其御，侯伯方軌，戰國橫騖，於是七雄虓闞，分裂諸夏，〔三〕龍戰而虎爭。游說之徒，風颺電激，並起而救之，〔四〕其餘猋飛景附，煜霅其間者，蓋不可勝載。〔五〕當此之時，搦朽摩鈍，鈆刀皆能壹斷，〔六〕是故魯連飛一矢而蹶千金，虞卿以顧眄而捐相印也。〔七〕夫啾發投曲，感耳之聲，合之律度，淫〈圭黽〉而不可聽者，非韶、夏之樂也；〔八〕因勢合變，偶時之會，風移俗易，乖忤而不可通者，非君子之法也。〔九〕及至從人合之，衡人散之，〔一０〕亡命漂說，羇旅騁辭，〔一一〕商鞅挾三術以鑽孝公，李斯奮時務而要始皇，〔一二〕彼皆躡風雲之會，履顛沛之勢，〔一三〕據徼乘邪以求一日之富貴，〔一四〕朝為榮華，夕而焦瘁，〔一五〕福不盈眥，禍（益）〔溢〕於世，〔一六〕凶人且以自悔，況吉士而是賴虖！〔一七〕且功不可以虛成，名不可以偽立，韓設辯以徼君，呂行詐以賈國。〔一八〕說難既酋，其身乃囚；秦貨既貴，厥宗亦隧。〔一九〕是故仲尼抗浮雲之志，孟軻養浩然之氣，〔二０〕彼豈樂為迂闊哉？道不可以貳也。〔二一〕方今大漢洒埽群穢，夷險芟荒，〔二二〕廓帝紘，恢皇綱，基隆於羲、農，規廣於黃、唐；其君天下也，炎之如日，威之如神，函之如海，養之如春。〔二三〕是以六合之內，莫不同原共流，沐浴玄德，〔二四〕稟卬太和，枝附葉著，〔二五〕譬猶屮木之殖山林，鳥魚之毓川澤，〔二六〕得氣者蕃滋，失時者苓落，〔二七〕參天墬而施化，豈云人事之厚薄哉？〔二八〕今子處皇世而論戰國，耀所聞而疑所覿，〔二九〕欲從旄敦而度高虖泰山，懷氿濫而測深虖重淵，亦未至也。」〔三０〕","sentenceOrder":264},
  {"id":"s_work_han_thu_119_265","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「逌，古攸字也。攸，咲貌也。」","sentenceOrder":265},
  {"id":"s_work_han_thu_119_266","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　應劭曰：「爾雅，東南隅謂之穾，西南隅謂之奧。」師古曰：「穾、奧，室中之二隅也。熒燭，熒熒小光之燭也。卬讀曰仰。穾音烏了反，其字從穴夭聲也。」","sentenceOrder":266},
  {"id":"s_work_han_thu_119_267","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　應劭曰：「七雄，秦及六國也。」師古曰：「虓音呼交反。闞音呼敢反。」","sentenceOrder":267},
  {"id":"s_work_han_thu_119_268","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　師古曰：「颺讀與揚同。」","sentenceOrder":268},
  {"id":"s_work_han_thu_119_269","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　師古曰：「猋，疾風也。煜霅，光貌也。煜音于及反。霅音下甲反。煜又音育。」","sentenceOrder":269},
  {"id":"s_work_han_thu_119_270","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　師古曰：「搦，按也，音女角反。斷音丁煥反。」","sentenceOrder":270},
  {"id":"s_work_han_thu_119_271","chapterId":"ch_work_han_thu_119","textTraditional":"〔七〕　應劭曰：「魯連，齊人也。齊圍燕，燕將保於聊城。魯連係帛書於矢射與之，為陳利害。燕將得之，泣而自殺。譏切魏新垣衍，使不尊秦為帝。秦時圍邯鄲，為卻五十里，趙遂以安。趙王以千金為魯連壽，不受。魏齊為秦所購，迫急走趙，趙相虞卿與齊有故，然愍其窮，於是解相印，間行與奔魏公子無忌也。」李奇曰：「蹶，蹋也，距也。」師古曰：「蹶音厥，又音其月反。」","sentenceOrder":271},
  {"id":"s_work_han_thu_119_272","chapterId":"ch_work_han_thu_119","textTraditional":"〔八〕　李奇曰：「〈圭黽〉，不正之音也。」師古曰：「啾發，啾啾小聲而發也。投曲，趣合屈曲也。感耳。動應眾庶之耳也。然而不合律度，君子所不聽也。淫〈圭黽〉，非正之聲也，不謂〈圭黽〉黽之鳴也。啾音子由反。」","sentenceOrder":272},
  {"id":"s_work_han_thu_119_273","chapterId":"ch_work_han_thu_119","textTraditional":"〔九〕　師古曰：「雖偶當時之會，而不可以移風易俗。」","sentenceOrder":273},
  {"id":"s_work_han_thu_119_274","chapterId":"ch_work_han_thu_119","textTraditional":"〔一０〕師古曰：「從音子庸反。」","sentenceOrder":274},
  {"id":"s_work_han_thu_119_275","chapterId":"ch_work_han_thu_119","textTraditional":"〔一一〕師古曰：「漂，浮也，音匹遙反。」","sentenceOrder":275},
  {"id":"s_work_han_thu_119_276","chapterId":"ch_work_han_thu_119","textTraditional":"〔一二〕應劭曰：「王、霸、富國強兵，為三術也。」師古曰：「王一也，霸二也，富國強兵三也。」","sentenceOrder":276},
  {"id":"s_work_han_thu_119_277","chapterId":"ch_work_han_thu_119","textTraditional":"〔一三〕師古曰：「顛沛，僵仆也。」","sentenceOrder":277},
  {"id":"s_work_han_thu_119_278","chapterId":"ch_work_han_thu_119","textTraditional":"〔一四〕師古曰：「徼，要也。據可以要迎之時也。徼音工堯反。徼字或作激。激，發也。」","sentenceOrder":278},
  {"id":"s_work_han_thu_119_279","chapterId":"ch_work_han_thu_119","textTraditional":"〔一五〕師古曰：「焦音在消反。瘁與悴同。」","sentenceOrder":279},
  {"id":"s_work_han_thu_119_280","chapterId":"ch_work_han_thu_119","textTraditional":"〔一六〕李奇曰：「當富貴之間，視不滿目，故言不盈眥也。」","sentenceOrder":280},
  {"id":"s_work_han_thu_119_281","chapterId":"ch_work_han_thu_119","textTraditional":"〔一七〕師古曰：「賴，利也。」","sentenceOrder":281},
  {"id":"s_work_han_thu_119_282","chapterId":"ch_work_han_thu_119","textTraditional":"〔一八〕師古曰：「賈，市賈也，音古。」","sentenceOrder":282},
  {"id":"s_work_han_thu_119_283","chapterId":"ch_work_han_thu_119","textTraditional":"〔一九〕應劭曰：「酋音酋豪之酋。酋，雄也。說難，韓非書篇名也。呂不韋效千金於秦，立子楚為王，封十萬戶侯，以陰事自殺也。」師古曰：「呂不韋初見子楚在趙，而云『此奇貨可居』，故班氏謂子楚為秦貨耳。安說效千金乎？應說失之矣。」","sentenceOrder":283},
  {"id":"s_work_han_thu_119_284","chapterId":"ch_work_han_thu_119","textTraditional":"〔二０〕張晏曰：「孔子云『不義而富且貴，於我如浮雲。』孟子曰：『我善養吾浩然之氣，而無害，則塞乎天地之間也。』」師古曰：「浩然，純壹之氣也。」","sentenceOrder":284},
  {"id":"s_work_han_thu_119_285","chapterId":"ch_work_han_thu_119","textTraditional":"〔二一〕師古曰：「迂，遠也，音于。」","sentenceOrder":285},
  {"id":"s_work_han_thu_119_286","chapterId":"ch_work_han_thu_119","textTraditional":"〔二二〕師古曰：「洒音所蟹反，汛也。汛音信。」","sentenceOrder":286},
  {"id":"s_work_han_thu_119_287","chapterId":"ch_work_han_thu_119","textTraditional":"〔二三〕師古曰：「函，容也，讀與含同。」","sentenceOrder":287},
  {"id":"s_work_han_thu_119_288","chapterId":"ch_work_han_thu_119","textTraditional":"〔二四〕師古曰：「原，水泉之本也。流者，其末流也。」","sentenceOrder":288},
  {"id":"s_work_han_thu_119_289","chapterId":"ch_work_han_thu_119","textTraditional":"〔二五〕師古曰：「卬讀曰仰。著音直略反。」","sentenceOrder":289},
  {"id":"s_work_han_thu_119_290","chapterId":"ch_work_han_thu_119","textTraditional":"〔二六〕師古曰：「殖，生也，長也。毓與育同。」","sentenceOrder":290},
  {"id":"s_work_han_thu_119_291","chapterId":"ch_work_han_thu_119","textTraditional":"〔二七〕師古曰：「苓與零同。」","sentenceOrder":291},
  {"id":"s_work_han_thu_119_292","chapterId":"ch_work_han_thu_119","textTraditional":"〔二八〕師古曰：「墬，古地字。」","sentenceOrder":292},
  {"id":"s_work_han_thu_119_293","chapterId":"ch_work_han_thu_119","textTraditional":"〔二九〕師古曰：「覿，見也，音徒歷反。」","sentenceOrder":293},
  {"id":"s_work_han_thu_119_294","chapterId":"ch_work_han_thu_119","textTraditional":"〔三０〕應劭曰：「爾雅，前高曰旄丘，如覆敦者敦丘，側出曰氿泉，正出曰濫泉。」師古曰：「敦音丁回反。度音徒各反。氿音軌。」","sentenceOrder":294},
  {"id":"s_work_han_thu_119_295","chapterId":"ch_work_han_thu_119","textTraditional":"賓曰：「若夫鞅、斯之倫，衰周之凶人，既聞命矣。敢問上古之士，處身行道，輔世成名，可述於後者，默而已虖？」","sentenceOrder":295},
  {"id":"s_work_han_thu_119_296","chapterId":"ch_work_han_thu_119","textTraditional":"主人曰：「何為其然也！昔咎繇謨虞，箕子訪周，〔一〕言通帝王，謀合聖神；殷說夢發於傅巖，周望兆動於渭濱，〔二〕齊甯激聲於康衢，漢良受書於邳沂，〔三〕皆俟命而神交，匪詞言之所信，〔四〕故能建必然之策，展無窮之勳也。近者陸子優繇，新語以興；〔五〕董生下帷，發藻儒林；劉向司籍，辯章舊聞；揚雄覃思，法言、大玄：〔六〕皆及時君之門闈，究先聖之壼奧，〔七〕婆娑虖術藝之場，休息虖篇籍之囿，以全其質而發其文，用納虖聖聽，列炳於後人，斯非其亞與！〔八〕若乃夷抗行於首陽，惠降志於辱仕，〔九〕顏耽樂於簞瓢，孔終篇於西狩，〔一０〕聲盈塞於天淵，真吾徒之師表也。且吾聞之：壹陰壹陽，天墬之方；〔一一〕乃文乃質，王道之綱；有同有異，聖喆之常。故曰：慎修所志，守爾天符，委命共己，味道之腴，〔一二〕神之聽之，名其舍諸！〔一三〕賓又不聞龢氏之璧韞於荊石，〔一四〕隨侯之珠藏於蜯蛤虖？〔一五〕歷世莫眡，不知其將含景耀，吐英精，曠千載而流夜光也。應龍潛於潢汙，魚黿媟之，〔一六〕不睹其能奮靈德，合風雲，超忽荒，而躆顥蒼也〔一七〕。故夫泥蟠而天飛者，應龍之神也；先賤而後貴者，龢、隨之珍也；時闇而久章者，君子之真也。〔一八〕若乃牙、曠清耳於管絃，離婁眇目於豪分；〔一九〕逢蒙絕技於弧矢，班輸榷巧於斧斤；〔二０〕良樂軼能於相馭，烏獲抗力於千鈞；〔二一〕龢、鵲發精於鍼石，研、桑心計於無垠。〔二二〕僕亦不任廁技於彼列，故密爾自娛於斯文。」〔二三〕","sentenceOrder":296},
  {"id":"s_work_han_thu_119_297","chapterId":"ch_work_han_thu_119","textTraditional":"〔一〕　師古曰：「訪亦謀。」","sentenceOrder":297},
  {"id":"s_work_han_thu_119_298","chapterId":"ch_work_han_thu_119","textTraditional":"〔二〕　師古曰：「說，傅說也。解已在前。望謂太公望，即呂尚也。釣於渭水，文王將出獵，卜之，曰：『所得非龍非螭、非豹非羆，乃帝王之輔。』果遇呂尚於渭陽，與語大悅，曰：『吾太公望子久矣。』故號曰太公望。」","sentenceOrder":298},
  {"id":"s_work_han_thu_119_299","chapterId":"ch_work_han_thu_119","textTraditional":"〔三〕　鄭氏曰：「五達曰康，四達曰衢。」晉灼曰：「沂，崖也。下邳水之崖也。」師古曰：「齊甯，甯戚也。聲激，謂叩角所歌也。沂音牛斤反。」","sentenceOrder":299},
  {"id":"s_work_han_thu_119_300","chapterId":"ch_work_han_thu_119","textTraditional":"〔四〕　師古曰：「信合韻音新。」","sentenceOrder":300},
  {"id":"s_work_han_thu_119_301","chapterId":"ch_work_han_thu_119","textTraditional":"〔五〕　鄭氏曰：「優繇，不仕也。」師古曰：「繇讀與由同。」","sentenceOrder":301},
  {"id":"s_work_han_thu_119_302","chapterId":"ch_work_han_thu_119","textTraditional":"〔六〕　師古曰：「覃，大也，深也。」","sentenceOrder":302},
  {"id":"s_work_han_thu_119_303","chapterId":"ch_work_han_thu_119","textTraditional":"〔七〕　應劭曰：「宮中門謂之闈，宮中巷謂之壼。」師古曰：「壼音苦本反。」","sentenceOrder":303},
  {"id":"s_work_han_thu_119_304","chapterId":"ch_work_han_thu_119","textTraditional":"〔八〕　師古曰：「亞，次也。與讀曰歟。」","sentenceOrder":304},
  {"id":"s_work_han_thu_119_305","chapterId":"ch_work_han_thu_119","textTraditional":"〔九〕　師古曰：「夷，伯夷也。惠，柳下惠也。辱仕謂為士師三黜也。」","sentenceOrder":305},
  {"id":"s_work_han_thu_119_306","chapterId":"ch_work_han_thu_119","textTraditional":"〔一０〕師古曰：「謂作春秋止於獲麟也。狩合韻音守。」","sentenceOrder":306},
  {"id":"s_work_han_thu_119_307","chapterId":"ch_work_han_thu_119","textTraditional":"〔一一〕師古曰：「墬，古地字。」","sentenceOrder":307},
  {"id":"s_work_han_thu_119_308","chapterId":"ch_work_han_thu_119","textTraditional":"〔一二〕師古曰：「共讀曰恭。腴，肥也。」","sentenceOrder":308},
  {"id":"s_work_han_thu_119_309","chapterId":"ch_work_han_thu_119","textTraditional":"〔一三〕師古曰：「舍，廢也。諸，之也。言修志委命，則明神聽之，祐以福祿，自然有名，永不廢也。」","sentenceOrder":309},
  {"id":"s_work_han_thu_119_310","chapterId":"ch_work_han_thu_119","textTraditional":"〔一四〕師古曰：「龢，古和字也。韞亦臧也，音於粉反。」","sentenceOrder":310},
  {"id":"s_work_han_thu_119_311","chapterId":"ch_work_han_thu_119","textTraditional":"〔一五〕師古曰：「蜯即蚌字也，音平項反。蛤音工合反。」","sentenceOrder":311},
  {"id":"s_work_han_thu_119_312","chapterId":"ch_work_han_thu_119","textTraditional":"〔一六〕師古曰：「應龍，龍有翼者。潢汙，停水也。媟謂侮狎之也。潢音黃。汙音烏。」","sentenceOrder":312},
  {"id":"s_work_han_thu_119_313","chapterId":"ch_work_han_thu_119","textTraditional":"〔一七〕師古曰：「躆，以足據持也。顥，顥天也。元氣顥汙，故曰顥天。其色蒼蒼，故曰蒼天。躆音戟。」","sentenceOrder":313},
  {"id":"s_work_han_thu_119_314","chapterId":"ch_work_han_thu_119","textTraditional":"〔一八〕師古曰：「時闇，有時而闇也。」","sentenceOrder":314},
  {"id":"s_work_han_thu_119_315","chapterId":"ch_work_han_thu_119","textTraditional":"〔一九〕師古曰：「牙，伯牙也。曠，師曠也。離婁，明目者也。眇，細視也。」","sentenceOrder":315},
  {"id":"s_work_han_thu_119_316","chapterId":"ch_work_han_thu_119","textTraditional":"〔二０〕師古曰：「逢蒙，古善射者也。班輸即魯公輸班也。一說，班，魯班也，與公輸氏為二人也，皆有巧藝也。古樂府云：『誰能為此器。公輸與魯班。』榷，專也，一曰競也。榷音角。」","sentenceOrder":316},
  {"id":"s_work_han_thu_119_317","chapterId":"ch_work_han_thu_119","textTraditional":"〔二一〕師古曰：「良，王良也。樂，伯樂也。軼與逸同。相，相馬也。馭，善馭也。烏獲，壯士也。」","sentenceOrder":317},
  {"id":"s_work_han_thu_119_318","chapterId":"ch_work_han_thu_119","textTraditional":"〔二二〕孟康曰：「研，古之善計也。桑，桑弘羊也。」師古曰：「和，秦醫和也。鵲，扁鵲也。研，計研也，一號計倪，亦曰計然。垠，厓也。」","sentenceOrder":318},
  {"id":"s_work_han_thu_119_319","chapterId":"ch_work_han_thu_119","textTraditional":"〔二三〕師古曰：「密，靜也，安也。」","sentenceOrder":319},
  {"id":"s_work_han_thu_119_320","chapterId":"ch_work_han_thu_119","textTraditional":"校勘記","sentenceOrder":320},
  {"id":"s_work_han_thu_119_321","chapterId":"ch_work_han_thu_119","textTraditional":"四一九八頁一０行　自隱度家之（曰）〔口〕數　景祐、殿本都作「口」，此誤。","sentenceOrder":321},
  {"id":"s_work_han_thu_119_322","chapterId":"ch_work_han_thu_119","textTraditional":"四二０三頁　六行　左將軍（師）〔史〕丹　景祐、殿本都作「史丹」。王先謙說非「師丹」。","sentenceOrder":322},
  {"id":"s_work_han_thu_119_323","chapterId":"ch_work_han_thu_119","textTraditional":"四二０三頁一六行　漢（書）〔舊〕儀云秩四百石，　景祐、殿本都作「舊」，此誤。","sentenceOrder":323},
  {"id":"s_work_han_thu_119_324","chapterId":"ch_work_han_thu_119","textTraditional":"四二一五頁　四行　（師古）〔蘇林〕曰：　景祐、殿本都作「蘇林」，此誤。","sentenceOrder":324},
  {"id":"s_work_han_thu_119_325","chapterId":"ch_work_han_thu_119","textTraditional":"四二一五頁一０行　應劭曰：　王先謙說兩「應劭」有一誤。","sentenceOrder":325},
  {"id":"s_work_han_thu_119_326","chapterId":"ch_work_han_thu_119","textTraditional":"四二一九頁　二行　匝三正而滅（周）〔姬〕；　文選作「姬」，與下「災」字協韻。此蓋涉注文而誤。","sentenceOrder":326},
  {"id":"s_work_han_thu_119_327","chapterId":"ch_work_han_thu_119","textTraditional":"四二一九頁　三行　（醇）〔淳〕，美也。汜，（崖）〔涯〕也。　殿本作「淳」「涯」。王先謙說殿本是。","sentenceOrder":327},
  {"id":"s_work_han_thu_119_328","chapterId":"ch_work_han_thu_119","textTraditional":"四二一九頁一四行　以（獸）〔虎〕歸入也。　殿本作「虎」。","sentenceOrder":328},
  {"id":"s_work_han_thu_119_329","chapterId":"ch_work_han_thu_119","textTraditional":"四二二二頁一四行　國人稱（人）〔仁〕，　景祐、殿、局本都作「仁」，此誤。","sentenceOrder":329},
  {"id":"s_work_han_thu_119_330","chapterId":"ch_work_han_thu_119","textTraditional":"四二二七頁一三行　禍（益）〔溢〕於世，　景祐、殿本都作「溢」。王先謙說「益」字誤。","sentenceOrder":330},
  {"id":"s_work_han_thu_120_1","chapterId":"ch_work_han_thu_120","textTraditional":"固以為唐虞三代，詩書所及，世有典籍，故雖堯舜之盛，必有典謨之篇，然後揚名於後世，冠德於百王，〔一〕故曰「巍巍乎其有成功，煥乎其有文章也！」〔二〕漢紹堯運，以建帝業，至於六世，史臣乃追述功德，私作本紀，〔三〕編於百王之末，廁於秦、項之列。太初以後，闕而不錄，故探篹前記，綴輯所聞，〔四〕以述漢書，起元高祖，終于孝平王莽之誅，十有二世，二百三十年，綜其行事，旁貫五經，上下洽通，〔五〕為春秋考紀、表、志、傳，凡百篇。〔六〕其敘曰：〔七〕","sentenceOrder":1},
  {"id":"s_work_han_thu_120_2","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「德為百王之上也。」","sentenceOrder":2},
  {"id":"s_work_han_thu_120_3","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「此篇論語載孔子美堯舜之言也。」","sentenceOrder":3},
  {"id":"s_work_han_thu_120_4","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「謂武帝時司馬遷作史記。」","sentenceOrder":4},
  {"id":"s_work_han_thu_120_5","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「篹與撰同。輯與集同。」","sentenceOrder":5},
  {"id":"s_work_han_thu_120_6","chapterId":"ch_work_han_thu_120","textTraditional":"〔五〕　師古曰：「固所撰諸表序及志，經典之義在於是也。」","sentenceOrder":6},
  {"id":"s_work_han_thu_120_7","chapterId":"ch_work_han_thu_120","textTraditional":"〔六〕　師古曰：「春秋考紀，謂帝紀也。而俗之學者不詳此文，乃云漢書一名春秋考紀，蓋失之矣。」","sentenceOrder":7},
  {"id":"s_work_han_thu_120_8","chapterId":"ch_work_han_thu_120","textTraditional":"〔七〕　師古曰：「自『皇矣漢祖』以下諸敘，皆班固自論撰漢書意，此亦依放史記之敘目耳。史遷則云為某事作某本紀、某列傳。班固謙，不言（然）〔作〕而改言述，蓋避作者之謂聖，而取述者之謂明也。但後之學者不曉此為漢書敘目，見有述字，因謂此文追述漢書之事，乃呼為『漢書述』，失之遠矣。摯虞尚有此惑，其餘曷足怪乎！」","sentenceOrder":8},
  {"id":"s_work_han_thu_120_9","chapterId":"ch_work_han_thu_120","textTraditional":"皇矣漢祖，纂堯之緒，實天生德，聰明神武。秦人不綱，罔漏于楚，〔一〕爰茲發跡，斷蛇奮旅。神母告符，朱旗乃舉，粵蹈秦郊，嬰來稽首。革命創制，三章是紀，應天順民，五星同晷。〔二〕項氏畔換，黜我巴、漢，〔三〕西土宅心，戰士憤怨。〔四〕乘釁而運，席卷三秦，割據河山，保此懷民。〔五〕股肱蕭、曹，社稷是經，爪牙信、布，腹心良、平，龔行天罰，赫赫明明。述高紀第一。","sentenceOrder":9},
  {"id":"s_work_han_thu_120_10","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「言秦失綱維，故高祖因時而起。罔漏于楚，謂項羽雖有害虐之心，終免於患也。一說，楚王陳涉初起，後又破滅也。」","sentenceOrder":10},
  {"id":"s_work_han_thu_120_11","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「晷，景也。」","sentenceOrder":11},
  {"id":"s_work_han_thu_120_12","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　孟康曰：「畔，反也。換，易也。不用義帝要，換易與高祖漢中也。」師古曰：「此說非也。畔換，強恣之貌，猶言跋扈也。詩大雅皇矣篇曰『無然畔換』。」","sentenceOrder":12},
  {"id":"s_work_han_thu_120_13","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　劉德曰：「宅，居也。西方人皆居心於高祖，猶係心也。書曰『惟眾宅心』。」晉灼曰：「西土，關西也。高祖入關，約法三章，秦民大悅，皆宅心高祖。」","sentenceOrder":13},
  {"id":"s_work_han_thu_120_14","chapterId":"ch_work_han_thu_120","textTraditional":"〔五〕　師古曰：「保，安也。懷民，懷德之人也。」","sentenceOrder":14},
  {"id":"s_work_han_thu_120_15","chapterId":"ch_work_han_thu_120","textTraditional":"孝惠短世，高后稱制，罔顧天顯，呂宗以敗。〔一〕述惠紀第二，高后紀第三。","sentenceOrder":15},
  {"id":"s_work_han_thu_120_16","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　劉德曰：「罔，無也。顧，念也。顯，明也。言呂氏無念天之明道者，徒念王諸呂，以至於敗亡。」","sentenceOrder":16},
  {"id":"s_work_han_thu_120_17","chapterId":"ch_work_han_thu_120","textTraditional":"太宗穆穆，允恭玄默，化民以躬，帥下以德。農不供貢，罪不收孥，〔一〕宮不新館，陵不崇墓。〔二〕我德如風，民應如屮，〔三〕國富刑清，登我漢道。〔四〕述文紀第四。","sentenceOrder":17},
  {"id":"s_work_han_thu_120_18","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　張晏曰：「除民田租之稅，是不供貢也。」","sentenceOrder":18},
  {"id":"s_work_han_thu_120_19","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「墓，合韻音謨。」","sentenceOrder":19},
  {"id":"s_work_han_thu_120_20","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「論語稱孔子曰：『君子之德風，小人之德屮也。』故引以為辭。」","sentenceOrder":20},
  {"id":"s_work_han_thu_120_21","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「登，成也。」","sentenceOrder":21},
  {"id":"s_work_han_thu_120_22","chapterId":"ch_work_han_thu_120","textTraditional":"孝景蒞政，諸侯方命，〔一〕克伐七國，王室以定。匪怠匪荒，務在農桑，著于甲令，民用寧康。〔二〕述景紀第五。","sentenceOrder":22},
  {"id":"s_work_han_thu_120_23","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　孟康曰：「尚書云『方命圮族』，言鯀之惡，壞其族類。吳楚七國亦然。」","sentenceOrder":23},
  {"id":"s_work_han_thu_120_24","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「甲令，即景紀令甲也。」","sentenceOrder":24},
  {"id":"s_work_han_thu_120_25","chapterId":"ch_work_han_thu_120","textTraditional":"世宗曄曄，思弘祖業，〔一〕疇咨熙載，髦俊並作。〔二〕厥作伊何？百蠻是攘，〔三〕恢我疆宇，外博四荒。〔四〕武功既抗，亦迪斯文，〔五〕憲章六學，統壹聖真。封禪郊祀，登秩百神；協律改正，饗茲永年。〔六〕述武紀第六。","sentenceOrder":25},
  {"id":"s_work_han_thu_120_26","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「曄曄，盛貌也。」","sentenceOrder":26},
  {"id":"s_work_han_thu_120_27","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「疇，誰也。咨，謀也。熙，興也。載，事也。謀於眾賢，誰（能）〔可〕任用，故能興其事業也。作，起也。」","sentenceOrder":27},
  {"id":"s_work_han_thu_120_28","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「攘，卻也。」","sentenceOrder":28},
  {"id":"s_work_han_thu_120_29","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「恢，廣也。博，大也。」","sentenceOrder":29},
  {"id":"s_work_han_thu_120_30","chapterId":"ch_work_han_thu_120","textTraditional":"〔五〕　劉德曰：「迪，進也。」","sentenceOrder":30},
  {"id":"s_work_han_thu_120_31","chapterId":"ch_work_han_thu_120","textTraditional":"〔六〕　張晏曰：「改正謂從建寅之月也。」","sentenceOrder":31},
  {"id":"s_work_han_thu_120_32","chapterId":"ch_work_han_thu_120","textTraditional":"孝昭幼沖，冢宰惟忠。燕、蓋譸張，實叡實聰，〔一〕罪人斯得，邦家和同。述昭紀第七。","sentenceOrder":32},
  {"id":"s_work_han_thu_120_33","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　如淳曰：「譸音輈。」應劭曰：「譸張，誑也。」","sentenceOrder":33},
  {"id":"s_work_han_thu_120_34","chapterId":"ch_work_han_thu_120","textTraditional":"中宗明明，夤用刑名，〔一〕時舉傅納，聽斷惟精。〔二〕柔遠能邇，燀燿威靈，〔三〕龍荒幕朔，莫不來庭。〔四〕丕顯祖烈，尚於有成。〔五〕述宣紀第八。","sentenceOrder":34},
  {"id":"s_work_han_thu_120_35","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　鄧展曰：「夤，敬也。」","sentenceOrder":35},
  {"id":"s_work_han_thu_120_36","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　李奇曰：「時，是也。於是時也，選用賢者。」師古曰：「傅讀曰敷。虞書舜典曰『敷納以言』。敷，陳也，謂有陳言者則納而用之。」","sentenceOrder":36},
  {"id":"s_work_han_thu_120_37","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「虞書舜典曰『柔遠能邇』。柔，安也。能，善也。故引之云。燀，熾也，音充善反。」","sentenceOrder":37},
  {"id":"s_work_han_thu_120_38","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　孟康曰：「謂白龍堆荒服沙幕也。」師古曰：「龍，匈奴祭天龍城，非謂白龍堆也。朔，北方也。」","sentenceOrder":38},
  {"id":"s_work_han_thu_120_39","chapterId":"ch_work_han_thu_120","textTraditional":"〔五〕　師古曰：「丕，大也。烈，業也。」","sentenceOrder":39},
  {"id":"s_work_han_thu_120_40","chapterId":"ch_work_han_thu_120","textTraditional":"孝元翼翼，高明柔克，〔一〕賓禮故老，優繇亮直。〔二〕外割禁囿，內損御服，離宮不衛，山陵不邑。〔三〕閹尹之啙，穢我明德。〔四〕述元紀第九。","sentenceOrder":40},
  {"id":"s_work_han_thu_120_41","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「翼翼，敬也。尚書洪範云『高明柔克』，謂人雖有高明之度，而當執柔，乃能成德也。敘言元帝有柔克之姿也。」","sentenceOrder":41},
  {"id":"s_work_han_thu_120_42","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「故老謂貢禹、薛廣德也。優繇謂寬容也。亮直謂朱雲也。繇讀與由同。」","sentenceOrder":42},
  {"id":"s_work_han_thu_120_43","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　張晏曰：「不徙民著縣也。」","sentenceOrder":43},
  {"id":"s_work_han_thu_120_44","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　如淳曰：「任弘恭、石顯使為政，以病其治也。」師古曰：「謂宦人為閹者，言其精氣奄閉不泄也，一曰（王）〔主〕奄閉門者。尹，正也。啙與疵同。」","sentenceOrder":44},
  {"id":"s_work_han_thu_120_45","chapterId":"ch_work_han_thu_120","textTraditional":"孝成煌煌，臨朝有光，威儀之盛，如圭如璋。壼闈恣趙，朝政在王，〔一〕炎炎燎火，亦允不陽。〔二〕述成紀第十。","sentenceOrder":45},
  {"id":"s_work_han_thu_120_46","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「趙謂趙皇后及昭儀也。王謂外家王鳳、王音等。」","sentenceOrder":46},
  {"id":"s_work_han_thu_120_47","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　張晏曰：「天子盛威，若燎火之陽，今委政王氏，不炎熾矣。」師古曰：「允，信也。」","sentenceOrder":47},
  {"id":"s_work_han_thu_120_48","chapterId":"ch_work_han_thu_120","textTraditional":"孝哀彬彬，克〈扌監〉威神，〔一〕彫落洪支，底剭鼎臣。〔二〕婉孌董公，惟亮天功，大過之困，實橈實凶。〔三〕述哀紀第十一。","sentenceOrder":48},
  {"id":"s_work_han_thu_120_49","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「彬彬，文質備也。言哀帝忿孝成之時權在臣下，故自〈扌監〉持其威神也。〈扌監〉，執取也，其字從手。」","sentenceOrder":49},
  {"id":"s_work_han_thu_120_50","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　服虔曰：「彫落洪支，廢退王氏也。底，致也。周禮有屋誅，誅大臣於屋下，不露也。易曰『鼎折足，其形渥，凶』，謂誅朱博、王嘉之屬也。」晉灼曰：「剭，刑也。」師古曰：「剭者，厚刑，謂重誅也，音握。服言屋下，失其義也。」","sentenceOrder":50},
  {"id":"s_work_han_thu_120_51","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　應劭曰：「以董賢為三公，乃欲共成天功也。易大過卦『棟橈，凶』，言以小材而為棟梁，不堪其任，至於折橈而凶也。」師古曰：「婉孌，美貌。亮，助也。尚書舜典曰『夤亮天功』，故引之也。橈，曲也，音女教反。」","sentenceOrder":51},
  {"id":"s_work_han_thu_120_52","chapterId":"ch_work_han_thu_120","textTraditional":"孝平不造，新都作宰，不周不伊，喪我四海。〔一〕述平紀第十二。","sentenceOrder":52},
  {"id":"s_work_han_thu_120_53","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「造，成也。遭家業不成。周頌曰『閔予小子，遭家不造』，故引之也。言其自號（寧）〔宰〕衡，而無周公、伊尹之忠也。」","sentenceOrder":53},
  {"id":"s_work_han_thu_120_54","chapterId":"ch_work_han_thu_120","textTraditional":"漢初受命，諸侯並政，制自項氏，十有八姓。述異姓諸侯王表第一。","sentenceOrder":54},
  {"id":"s_work_han_thu_120_55","chapterId":"ch_work_han_thu_120","textTraditional":"太祖元勳，啟立輔臣，支庶藩屏，侯王並尊。述諸侯王表第二。","sentenceOrder":55},
  {"id":"s_work_han_thu_120_56","chapterId":"ch_work_han_thu_120","textTraditional":"侯王之祉，祚及宗子，公族蕃滋，支葉碩茂。〔一〕述王子侯表第三。","sentenceOrder":56},
  {"id":"s_work_han_thu_120_57","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「茂，合韻音莫口反。」","sentenceOrder":57},
  {"id":"s_work_han_thu_120_58","chapterId":"ch_work_han_thu_120","textTraditional":"受命之初，贊功剖符，奕世弘業，爵土乃昭。〔一〕述高惠高后孝文功臣侯表第四。","sentenceOrder":58},
  {"id":"s_work_han_thu_120_59","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「贊功，佐命之功也。奕，大也。」","sentenceOrder":59},
  {"id":"s_work_han_thu_120_60","chapterId":"ch_work_han_thu_120","textTraditional":"景征吳楚，武興師旅，後昆承平，亦有紹土。〔一〕述景武昭宣元成哀功臣侯表第五。","sentenceOrder":60},
  {"id":"s_work_han_thu_120_61","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「言景、武之時以軍功，故封侯者多，昭、宣以後雖承平，尚有以勳獲爵土者。」","sentenceOrder":61},
  {"id":"s_work_han_thu_120_62","chapterId":"ch_work_han_thu_120","textTraditional":"亡德不報，爰存二代，〔一〕宰相外戚，昭韙見戒。〔二〕述外戚恩澤侯表第六。","sentenceOrder":62},
  {"id":"s_work_han_thu_120_63","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　應劭曰：「二代，二王後也。」師古曰：「二代，謂殷、周也。言德澤深遠，故至漢朝其子孫又受茅土，以奉祭祀。」","sentenceOrder":63},
  {"id":"s_work_han_thu_120_64","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　張晏曰：「韙，是也。明其是者，戒其非也。」","sentenceOrder":64},
  {"id":"s_work_han_thu_120_65","chapterId":"ch_work_han_thu_120","textTraditional":"漢迪於秦，有革有因，〔一〕觕舉僚職，並列其人。〔二〕述百官公卿表第七。","sentenceOrder":65},
  {"id":"s_work_han_thu_120_66","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　劉德曰：「迪，至也。」","sentenceOrder":66},
  {"id":"s_work_han_thu_120_67","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　晉灼曰：「觕音麄觕之觕。」師古曰：「觕角才戶反，謂大略也。」","sentenceOrder":67},
  {"id":"s_work_han_thu_120_68","chapterId":"ch_work_han_thu_120","textTraditional":"篇章博舉，通于上下，略差名號，九品之敘。述古今人表第八。","sentenceOrder":68},
  {"id":"s_work_han_thu_120_69","chapterId":"ch_work_han_thu_120","textTraditional":"元元本本，數始於一，〔一〕產氣黃鍾，造計秒忽。〔二〕八音七始，五聲六律，〔三〕度量權衡，曆算逌出。〔四〕官失學微，六家分乖，〔五〕壹彼壹此，庶研其幾。述律曆志第一。","sentenceOrder":69},
  {"id":"s_work_han_thu_120_70","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　張晏曰：「數之元本，起於初九之一也。」","sentenceOrder":70},
  {"id":"s_work_han_thu_120_71","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　劉德曰：「秒，禾芒也。忽，蜘蛛網細者也。」師古曰：「秒音眇，其字從禾。」","sentenceOrder":71},
  {"id":"s_work_han_thu_120_72","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　劉德曰：「七始，天地四方人之始也。」師古曰：「解在禮樂志。」","sentenceOrder":72},
  {"id":"s_work_han_thu_120_73","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「逌，古攸字也。攸，所也。」","sentenceOrder":73},
  {"id":"s_work_han_thu_120_74","chapterId":"ch_work_han_thu_120","textTraditional":"〔五〕　劉德曰：「六家，謂黃帝、顓頊、夏、殷、周、魯曆也。」","sentenceOrder":74},
  {"id":"s_work_han_thu_120_75","chapterId":"ch_work_han_thu_120","textTraditional":"上天下澤，春雷奮作，〔一〕先王觀象，爰制禮樂。厥後崩壞，鄭衛荒淫，風流民化，湎湎紛紛。〔二〕略存大綱，以統舊文。述禮樂志第二。","sentenceOrder":75},
  {"id":"s_work_han_thu_120_76","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　劉德曰：「兌下乾上履，坤下震上豫。履，禮也。豫，樂也。取易象制禮作樂。」師古曰：「易象曰『上天下澤履，雷出地奮豫』，故具引其文。」","sentenceOrder":76},
  {"id":"s_work_han_thu_120_77","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「言上風既流，下人則化也。湎湎，流移也。紛紛，雜亂也。湎音莫踐反。」","sentenceOrder":77},
  {"id":"s_work_han_thu_120_78","chapterId":"ch_work_han_thu_120","textTraditional":"靁電皆至，天威震耀，五刑之作，是則是效，〔一〕威實輔德，刑亦助教。季世不詳，背本爭末，〔二〕吳、孫狙詐，申、商酷烈。〔三〕漢章九法，太宗改作，〔四〕輕重之差，世有定籍。述刑法志第三。","sentenceOrder":78},
  {"id":"s_work_han_thu_120_79","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　劉德曰：「震下離上，噬嗑，利用獄。雷電，取象天威也。」師古曰：「易象辭曰『雷電，噬嗑，先王以明罰敕法』，故引之。」","sentenceOrder":79},
  {"id":"s_work_han_thu_120_80","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「不詳謂不盡用刑之理也。周書呂刑曰『告爾詳刑』。」","sentenceOrder":80},
  {"id":"s_work_han_thu_120_81","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「狙音千豫反。」","sentenceOrder":81},
  {"id":"s_work_han_thu_120_82","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　張晏曰：「改，除肉刑也。」","sentenceOrder":82},
  {"id":"s_work_han_thu_120_83","chapterId":"ch_work_han_thu_120","textTraditional":"厥初生民，食貨惟先。割制廬井，定爾土田，什一供貢，下富上尊。商以足用，茂遷有無，貨自龜貝，至此五銖。揚搉古今，監世盈虛。〔一〕述食貨志第四。","sentenceOrder":83},
  {"id":"s_work_han_thu_120_84","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「揚，舉也。搉，引也。揚搉者，舉而引之，陳其趣也。搉音居學反。」","sentenceOrder":84},
  {"id":"s_work_han_thu_120_85","chapterId":"ch_work_han_thu_120","textTraditional":"昔在上聖，昭事百神，類帝禋宗，望秩山川，明德惟馨，永世豐年。季末淫祀，營信巫史，〔一〕大夫臚岱，侯伯僭畤，〔二〕放誕之徒，緣間而起。〔三〕瞻前顧後，正其終始。述郊祀志第五。","sentenceOrder":85},
  {"id":"s_work_han_thu_120_86","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　鄧展曰：「營，惑也。」","sentenceOrder":86},
  {"id":"s_work_han_thu_120_87","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　鄭氏曰：「臚岱，季氏旅於太山是也。」應劭曰：「僭畤，秦文公造（四）〔西〕畤祭天是也。」師古曰：「旅，陳也。臚亦陳也。臚旅聲相近，其義一耳。」","sentenceOrder":87},
  {"id":"s_work_han_thu_120_88","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「謂方士言神仙之術也。」","sentenceOrder":88},
  {"id":"s_work_han_thu_120_89","chapterId":"ch_work_han_thu_120","textTraditional":"炫炫上天，縣象著明，〔一〕日月周輝，星辰垂精。百官立法，宮室混成，〔二〕降應王政，景以燭形。〔三〕三季之後，厥事放紛，〔四〕舉其占應，覽故考新。述天文志第六。","sentenceOrder":89},
  {"id":"s_work_han_thu_120_90","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「炫炫，光耀之貌，音胡眄反。縣，古懸字。」","sentenceOrder":90},
  {"id":"s_work_han_thu_120_91","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　張晏曰：「星辰有宮室百官，各應其象以見咎徵也。」","sentenceOrder":91},
  {"id":"s_work_han_thu_120_92","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　張晏曰：「王政失於此，星辰變於彼，猶景之象形。」","sentenceOrder":92},
  {"id":"s_work_han_thu_120_93","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「三季，三代之末也。放，失也。紛，亂也。」","sentenceOrder":93},
  {"id":"s_work_han_thu_120_94","chapterId":"ch_work_han_thu_120","textTraditional":"河圖命庖，洛書賜禹，八卦成列，九疇逌敘。〔一〕世代寔寶，光演文武，春秋之占，咎徵是舉。告往知來，王事之表。述五行志第七。","sentenceOrder":94},
  {"id":"s_work_han_thu_120_95","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　李奇曰：「河圖即八卦也。洛書即洪範九疇也。」師古曰：「庖，庖犧也。逌，古攸字。」","sentenceOrder":95},
  {"id":"s_work_han_thu_120_96","chapterId":"ch_work_han_thu_120","textTraditional":"坤作墬勢，高下九則，〔一〕自昔黃、唐，經略萬國，（變）〔燮〕定東西，疆理南北。〔二〕三代損益，降及秦、漢，革剗五等，制立郡縣。〔三〕略表山川，彰其剖判。述地理志第八。","sentenceOrder":96},
  {"id":"s_work_han_thu_120_97","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　張晏曰：「易曰『地勢坤』。」劉德曰：「九則，九州土田上中下九等也。」師古曰：「墬，古地字。易象曰：『地勢坤，君子以厚德載物。』高下謂地形也。一曰，地之肥瘠。」","sentenceOrder":97},
  {"id":"s_work_han_thu_120_98","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「（變）〔燮〕和也。疆理謂立封疆而統理之。」","sentenceOrder":98},
  {"id":"s_work_han_thu_120_99","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　晉灼曰：「剗音剗削之剗。」師古曰：「音初限反。」","sentenceOrder":99},
  {"id":"s_work_han_thu_120_100","chapterId":"ch_work_han_thu_120","textTraditional":"夏乘四載，百川是導。〔一〕唯河為囏，災及後代。商竭周移，秦決南涯，〔二〕自茲拒漢，北亡八支。〔三〕文陻棗野，武作瓠歌，〔四〕成有平年，後遂滂沱。〔五〕爰及溝渠，利我國家。述溝洫志第九。","sentenceOrder":100},
  {"id":"s_work_han_thu_120_101","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「四載，解在溝洫志。」","sentenceOrder":101},
  {"id":"s_work_han_thu_120_102","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　服虔曰：「河竭而商亡。移亦河移徙也。」如淳曰：「秦始皇本紀決河灌大梁，遂滅之，通為溝，入淮、泗。」","sentenceOrder":102},
  {"id":"s_work_han_thu_120_103","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　服虔曰：「本有九河，今塞，餘有一也。」","sentenceOrder":103},
  {"id":"s_work_han_thu_120_104","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　服虔曰：「陻音因。文帝塞河於酸棗也。」張晏曰：「河決瓠子，武帝親臨，悼功不成而作歌。」","sentenceOrder":104},
  {"id":"s_work_han_thu_120_105","chapterId":"ch_work_han_thu_120","textTraditional":"〔五〕　劉德曰：「成帝治河已平，改元曰河平元年。」","sentenceOrder":105},
  {"id":"s_work_han_thu_120_106","chapterId":"ch_work_han_thu_120","textTraditional":"虙羲畫卦，書契後作，〔一〕虞夏商周，孔纂其業，篹書刪詩，綴禮正樂，〔二〕彖系大易，因史立法。〔三〕六學既登，遭世罔弘，〔四〕群言紛亂，諸子相騰。〔五〕秦人是滅，漢修其缺，劉向司籍，九流以別。〔六〕爰著目錄，略序洪烈。〔七〕述藝文志第十。","sentenceOrder":106},
  {"id":"s_work_han_thu_120_107","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「虙讀與伏同。」","sentenceOrder":107},
  {"id":"s_work_han_thu_120_108","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「篹與撰同。」","sentenceOrder":108},
  {"id":"s_work_han_thu_120_109","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「謂修春秋定帝王之文。」","sentenceOrder":109},
  {"id":"s_work_han_thu_120_110","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「罔，無也。無能弘大正道也。」","sentenceOrder":110},
  {"id":"s_work_han_thu_120_111","chapterId":"ch_work_han_thu_120","textTraditional":"〔五〕　師古曰：「騰，馳也。」","sentenceOrder":111},
  {"id":"s_work_han_thu_120_112","chapterId":"ch_work_han_thu_120","textTraditional":"〔六〕　應劭曰：「儒、道、陰陽、法、名、墨、從橫、雜、農，凡九家。」","sentenceOrder":112},
  {"id":"s_work_han_thu_120_113","chapterId":"ch_work_han_thu_120","textTraditional":"〔七〕　師古曰：「洪，大也。烈，業也。」","sentenceOrder":113},
  {"id":"s_work_han_thu_120_114","chapterId":"ch_work_han_thu_120","textTraditional":"上嫚下暴，惟盜是伐，〔一〕勝、廣熛起，梁、籍扇烈。〔二〕赫赫炎炎，遂焚咸陽，宰割諸夏，命立侯王，誅嬰放懷，詐虐以亡。述陳勝項籍傳第一。","sentenceOrder":114},
  {"id":"s_work_han_thu_120_115","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「易上繫辭云：『小人而乘君子之器，盜思奪之矣；上嫚下暴，盜思伐之矣。』引此言者，謂秦胡亥之時。」","sentenceOrder":115},
  {"id":"s_work_han_thu_120_116","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「飛火曰熛。扇，熾也。烈，猛也。言陳勝初起而項羽（益）〔烈〕盛也。熛音必遙反。」","sentenceOrder":116},
  {"id":"s_work_han_thu_120_117","chapterId":"ch_work_han_thu_120","textTraditional":"張、陳之交，斿如父子，攜手〈辶彖〉秦，拊翼俱起。〔一〕據國爭權，還為豺虎，〔二〕耳（諫）〔謀〕甘公，作漢藩輔。述張耳陳餘傳第二。","sentenceOrder":117},
  {"id":"s_work_han_thu_120_118","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　應劭曰：「〈辶彖〉，逃也。」師古曰：「〈辶彖〉，古遯字也。拊翼，以雞為喻，言知將旦，則鼓擊其翼而鳴也。」","sentenceOrder":118},
  {"id":"s_work_han_thu_120_119","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「言反相吞噬也。」","sentenceOrder":119},
  {"id":"s_work_han_thu_120_120","chapterId":"ch_work_han_thu_120","textTraditional":"三枿之起，本根既朽，〔一〕枯楊生華，曷惟其舊！〔二〕橫雖雄材，伏于海隝，沐浴尸鄉，北面奉首，旅人慕殉，義過黃鳥。〔三〕述魏豹田儋韓信傳第三。","sentenceOrder":120},
  {"id":"s_work_han_thu_120_121","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　劉德曰：「詩云『包有三枿』。爾雅曰『烈、枿，餘也』。謂木斫髡而復枿生也。喻魏、齊、韓皆滅而復起，若髡木更生也。」師古曰：「枿音五葛反。」","sentenceOrder":121},
  {"id":"s_work_han_thu_120_122","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　應劭曰：「易云『枯楊生華』，暫貴之意也。曷惟其舊，言不能久也。」師古曰：「枯楊生華，大過卦九五爻辭也。舊，合韻音臼。」","sentenceOrder":122},
  {"id":"s_work_han_thu_120_123","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　劉德曰：「黃鳥之詩刺秦穆公要人從死，言今橫不要而有從者，故曰過之。」","sentenceOrder":123},
  {"id":"s_work_han_thu_120_124","chapterId":"ch_work_han_thu_120","textTraditional":"信惟餓隸，布實黥徒，越亦狗盜，芮尹江湖。〔一〕雲起龍襄，化為侯王，〔二〕割有齊、楚，跨制淮、梁。〔三〕綰自同閈，鎮我北疆，〔四〕德薄位尊，非胙惟殃。吳克忠信，胤嗣乃長。述韓彭英盧吳傳第四。","sentenceOrder":124},
  {"id":"s_work_han_thu_120_125","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　張晏曰：「吳芮為番陽令，在江湖之間。尹，主也。」","sentenceOrder":125},
  {"id":"s_work_han_thu_120_126","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「襄，舉也。」","sentenceOrder":126},
  {"id":"s_work_han_thu_120_127","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　張晏曰：「韓信前王齊，徙楚。英布王淮南，彭越王梁也。」","sentenceOrder":127},
  {"id":"s_work_han_thu_120_128","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　應劭曰：「閈音扞。盧綰與高祖同里，楚名里門為閈。」師古曰：「左氏傳云『高其閈閎』，舊通語耳，非專楚也。」","sentenceOrder":128},
  {"id":"s_work_han_thu_120_129","chapterId":"ch_work_han_thu_120","textTraditional":"賈廑從旅，為鎮淮、楚。〔一〕澤王琅邪，權激諸呂。濞之受吳，疆土踰矩，〔二〕雖戒東南，終用齊斧。〔三〕述荊燕吳傳第五。","sentenceOrder":129},
  {"id":"s_work_han_thu_120_130","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　張晏曰：「劉賈晚乃從軍也。」晉灼曰：「廑，無幾也。」師古曰：「二說皆非也。廑，古以為勤字。言賈從軍，有勤勞也。」","sentenceOrder":130},
  {"id":"s_work_han_thu_120_131","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「矩，法制也。」","sentenceOrder":131},
  {"id":"s_work_han_thu_120_132","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　張晏曰：「齊斧，越斧也，以整齊天下也。」晉灼曰：「雖戒勿反而反，竟用此斧於吳也。」師古曰：「易云『喪其齊斧』，故引以為辭。」","sentenceOrder":132},
  {"id":"s_work_han_thu_120_133","chapterId":"ch_work_han_thu_120","textTraditional":"太上四子：伯兮早夭，仲氏王代，斿宅于楚。〔一〕戊實淫〈垂夬〉，平陸乃紹。〔二〕其在于京，奕世宗正，〔三〕劬勞王室，用侯陽成。子政博學，三世成名，〔四〕述楚元王傳第六。","sentenceOrder":133},
  {"id":"s_work_han_thu_120_134","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「詩衛風云『伯兮朅兮』，鄁風又曰『仲氏任只』。此序方論高祖兄伯及仲，故引二句為之辭也。」","sentenceOrder":134},
  {"id":"s_work_han_thu_120_135","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「楚王戊為薄太后服姦，削東海郡，遂與吳共反而誅。景帝更立平陸侯禮，續元王之後也。」","sentenceOrder":135},
  {"id":"s_work_han_thu_120_136","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「正，合韻音征。」","sentenceOrder":136},
  {"id":"s_work_han_thu_120_137","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「謂劉德、劉向、劉歆，俱有名聞。」","sentenceOrder":137},
  {"id":"s_work_han_thu_120_138","chapterId":"ch_work_han_thu_120","textTraditional":"季氏之詘，辱身毀節，信于上將，議臣震栗。〔一〕欒公哭梁，田叔殉趙，見危授命，誼動明主。布歷燕、齊，叔亦相魯，民思其政，或金或社。〔二〕述季布欒布田叔傳第七。","sentenceOrder":138},
  {"id":"s_work_han_thu_120_139","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　張晏曰：「申意於上將。上將，樊噲也，欲以十萬眾橫行匈奴中，布曰：『噲可斬也。』時議臣皆恐。」師古曰：「信讀曰申。」","sentenceOrder":139},
  {"id":"s_work_han_thu_120_140","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　李奇曰：「魯人愛田叔，死，送之以金。齊貴欒布，為生立社。」","sentenceOrder":140},
  {"id":"s_work_han_thu_120_141","chapterId":"ch_work_han_thu_120","textTraditional":"高祖八子，二帝六王。三趙不辜，淮厲自亡，燕靈絕嗣，齊悼特昌。掩有東土，自岱徂海，支庶分王，前後九子。六國誅斃，適齊亡祀。城陽、濟北，後承我國。〔一〕赳赳景王，匡漢社稷。〔二〕述高五王傳第八。","sentenceOrder":141},
  {"id":"s_work_han_thu_120_142","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　張晏曰：「濟北王志，吳楚反後徙王菑川。元朔中，齊國絕，悼惠王後唯有城陽、菑川，武帝乃割臨菑環悼惠王冢，以與菑川，令奉祀也。」師古曰：「適讀曰嫡。」","sentenceOrder":142},
  {"id":"s_work_han_thu_120_143","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「赳赳，武貌，音糾。」","sentenceOrder":143},
  {"id":"s_work_han_thu_120_144","chapterId":"ch_work_han_thu_120","textTraditional":"猗與元勳，包漢舉信，〔一〕鎮守關中，足食成軍，營都立宮，定制修文。平陽玄默，繼而弗革，〔二〕民用作歌，化我淳德。漢之宗臣，是謂相國。述蕭何曹參傳第九。","sentenceOrder":144},
  {"id":"s_work_han_thu_120_145","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　劉德曰：「包，取也。」師古曰：「包漢，謂勸高祖且王漢中也。舉信，舉韓信也。信合韻音新。」","sentenceOrder":145},
  {"id":"s_work_han_thu_120_146","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「革，改也。言曹參為相，守靜無為，一遵蕭何約束，不變改也。」","sentenceOrder":146},
  {"id":"s_work_han_thu_120_147","chapterId":"ch_work_han_thu_120","textTraditional":"留侯襲秦，作漢腹心，〔一〕圖折武關，解阨鴻門。〔二〕推齊銷印，敺致越、信；〔三〕招賓四老，惟寧嗣君。陳公擾攘，歸漢乃安，〔四〕斃范亡項，走狄擒韓，〔五〕六奇既設，我罔艱難。〔六〕安國廷爭，致仕杜門。絳侯矯矯，誅呂尊文。亞夫守節，吳楚有勳。述張陳王周傳第十。","sentenceOrder":147},
  {"id":"s_work_han_thu_120_148","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　劉德曰：「襲秦，椎始皇於博狼沙中。」","sentenceOrder":148},
  {"id":"s_work_han_thu_120_149","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「圖折武關，謂從沛公入武關，說令為疑兵，又啗秦將以利，勸因其怠懈擊之類也。」","sentenceOrder":149},
  {"id":"s_work_han_thu_120_150","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「敺與驅同。越，彭越也。信亦韓信也。謂於垓下圍項羽時也。信合韻音新。」","sentenceOrder":150},
  {"id":"s_work_han_thu_120_151","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「攘音人養反。」","sentenceOrder":151},
  {"id":"s_work_han_thu_120_152","chapterId":"ch_work_han_thu_120","textTraditional":"〔五〕　師古曰：「走狄謂解平城之圍也。禽韓，偽游雲夢也。」","sentenceOrder":152},
  {"id":"s_work_han_thu_120_153","chapterId":"ch_work_han_thu_120","textTraditional":"〔六〕　師古曰：「罔，無也。」","sentenceOrder":153},
  {"id":"s_work_han_thu_120_154","chapterId":"ch_work_han_thu_120","textTraditional":"舞陽鼓刀，滕公廄騶，〔一〕潁陰商販，曲周庸夫，攀龍附鳳，並乘天衢。〔二〕述樊酈滕灌傅靳周傳第十一。","sentenceOrder":154},
  {"id":"s_work_han_thu_120_155","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「鼓刀謂屠狗也。」","sentenceOrder":155},
  {"id":"s_work_han_thu_120_156","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「乘，登也。」","sentenceOrder":156},
  {"id":"s_work_han_thu_120_157","chapterId":"ch_work_han_thu_120","textTraditional":"北平志古，司秦柱下，〔一〕定漢章程，律度之緒。建平質直，犯上干色；〔二〕廣阿之廑，食厥舊德。〔三〕故安執節，責通請錯，蹇蹇帝臣，匪躬之故。〔四〕述張周趙任申屠傳第十二。","sentenceOrder":157},
  {"id":"s_work_han_thu_120_158","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「志，記也，謂多記古事也。司，主也。」","sentenceOrder":158},
  {"id":"s_work_han_thu_120_159","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「周昌先封建成侯，蓋謂此也。平字當為成，傳寫誤耳。」","sentenceOrder":159},
  {"id":"s_work_han_thu_120_160","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　張晏曰：「任敖也。吏遇呂后不謹，敖擊傷主吏也。」師古曰：「廑亦勤字也。易訟卦六三爻辭曰『食舊德』，食猶饗也。」","sentenceOrder":160},
  {"id":"s_work_han_thu_120_161","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「易蹇卦六二爻辭曰『王臣蹇蹇，匪躬之故』。此言申屠嘉召責鄧通，請誅朝錯，皆不為己身，實有蹇蹇之節也。」","sentenceOrder":161},
  {"id":"s_work_han_thu_120_162","chapterId":"ch_work_han_thu_120","textTraditional":"食其監門，長揖漢王，畫襲陳留，進收敖倉，塞隘杜津，王基以張。〔一〕賈作行人，百越來賓，從容風議，博我以文。〔二〕敬繇役夫，遷京定都，〔三〕內強關中，外和匈奴。叔孫奉常，與時抑揚，稅介免冑，禮義是創。〔四〕或悊或謀，觀國之光。〔五〕述酈陸朱婁叔孫傳第十三。〔六〕","sentenceOrder":162},
  {"id":"s_work_han_thu_120_163","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「杜亦塞也。謂說令塞白馬津。」","sentenceOrder":163},
  {"id":"s_work_han_thu_120_164","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　李奇曰：「作新語也。」師古曰：「論語稱顏回喟然歎曰『夫子博我以文』，謂以文章開博我也。此言陸賈嘗之越也。從音千容反。風讀曰諷。」","sentenceOrder":164},
  {"id":"s_work_han_thu_120_165","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「繇讀與由同。言劉敬由戍卒而來納說。」","sentenceOrder":165},
  {"id":"s_work_han_thu_120_166","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「稅，舍也。介，甲也。創，始造之也。創，合韻音初良反。」","sentenceOrder":166},
  {"id":"s_work_han_thu_120_167","chapterId":"ch_work_han_thu_120","textTraditional":"〔五〕　師古曰：「詩小雅小旻之篇曰『或悊或謀』，言有智者，有謀者。易觀卦六四爻辭曰『觀國之光，利用賓于王』。故合而為言。」","sentenceOrder":167},
  {"id":"s_work_han_thu_120_168","chapterId":"ch_work_han_thu_120","textTraditional":"〔六〕　師古曰：「本傳作朱、劉，終書其賜姓也。此言朱、婁，本其舊族耳。」","sentenceOrder":168},
  {"id":"s_work_han_thu_120_169","chapterId":"ch_work_han_thu_120","textTraditional":"淮南僭狂，二子受殃。安辯而邪，賜頑以荒，敢行稱亂，窘世薦亡。〔一〕述淮南衡山濟北傳第十四。","sentenceOrder":169},
  {"id":"s_work_han_thu_120_170","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「窘，仍也。薦讀曰荐。荐，再也。長遷死雍，其子安又自殺也。」","sentenceOrder":170},
  {"id":"s_work_han_thu_120_171","chapterId":"ch_work_han_thu_120","textTraditional":"蒯通壹說，三雄是敗，覆酈驕韓，田橫顛沛。被之拘係，乃成患害。〔一〕充、躬罔極，交亂弘大。〔二〕述蒯伍江息夫傳第十五。","sentenceOrder":171},
  {"id":"s_work_han_thu_120_172","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「言伍被初不從王反，王繫其父母，乃進邪謀，終以遇害也。」","sentenceOrder":172},
  {"id":"s_work_han_thu_120_173","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「小雅青蠅之詩云『讒言罔極，交亂四國』。此敘言江充、息夫躬之惡，引以為辭也。」","sentenceOrder":173},
  {"id":"s_work_han_thu_120_174","chapterId":"ch_work_han_thu_120","textTraditional":"萬石溫溫，幼寤聖君，〔一〕宜爾子孫，夭夭伸伸，〔二〕慶社于齊，不言動民。〔三〕衛、直、周、張，淑慎其身。〔四〕述萬石衛直周張傳第十六。","sentenceOrder":174},
  {"id":"s_work_han_thu_120_175","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　鄧展曰：「爾雅『寤、逢，遇也』。」師古曰：「此說非也。言萬石幼而恭謹，感寤高祖，以見識拔也。爾雅云『遻，遇（之）也』，非謂寤也。詩小雅小宛之篇曰『溫溫恭人』。」","sentenceOrder":175},
  {"id":"s_work_han_thu_120_176","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「詩周南螽斯之篇曰『宜爾子孫振振兮』，論語稱孔子『燕居，伸伸如也，夭夭如也』，謂和舒之貌。此言萬石子孫既多，又皆和睦，故引以為辭也。夭音於驕反。」","sentenceOrder":176},
  {"id":"s_work_han_thu_120_177","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　鄧展曰：「慶為齊相，齊為立社也。」","sentenceOrder":177},
  {"id":"s_work_han_thu_120_178","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「衛詩燕燕之篇曰『終溫且惠，淑慎其身』。淑，善也。引此詩言以美四人也。」","sentenceOrder":178},
  {"id":"s_work_han_thu_120_179","chapterId":"ch_work_han_thu_120","textTraditional":"孝文三王，代孝二梁，〔一〕懷折亡嗣，孝乃尊光。〔二〕內為母弟，外扞吳楚，怙寵矜功，僭欲失所，思心既霿，牛禍告妖。〔三〕帝庸親親，厥國五分，〔四〕德不堪寵，四支不傳。〔五〕述文三王傳第十七。","sentenceOrder":179},
  {"id":"s_work_han_thu_120_180","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「代孝王參及梁孝王武、梁懷王揖。」","sentenceOrder":180},
  {"id":"s_work_han_thu_120_181","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「折謂夭也。孝亦謂梁孝王也。」","sentenceOrder":181},
  {"id":"s_work_han_thu_120_182","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「霿，僭霿也，音莫候反。解在五行志。」","sentenceOrder":182},
  {"id":"s_work_han_thu_120_183","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「庸，用也。用親親之道，故分梁為五國，立孝王男五人為王。太子買為梁王，次子明為濟川王，彭離為濟東王，定為山陽王，不識為濟陰王。」","sentenceOrder":183},
  {"id":"s_work_han_thu_120_184","chapterId":"ch_work_han_thu_120","textTraditional":"〔五〕　晉灼曰：「（子）〔支〕，父母之四支也。」師古曰：「此說非也。謂孝王支子四人封為王者皆絕於身，不傳胤嗣，唯梁恭王買有後耳。其事具在本傳。」","sentenceOrder":184},
  {"id":"s_work_han_thu_120_185","chapterId":"ch_work_han_thu_120","textTraditional":"賈生矯矯，弱冠登朝。〔一〕遭文叡聖，屢抗其疏，暴秦之戒，三代是據。建設藩屏，以強守圉，〔二〕吳楚合從，賴誼之慮。〔三〕述賈誼傳第十八。","sentenceOrder":185},
  {"id":"s_work_han_thu_120_186","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「矯矯，高舉之貌也，合韻音驕。」","sentenceOrder":186},
  {"id":"s_work_han_thu_120_187","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「圉合韻音御。」","sentenceOrder":187},
  {"id":"s_work_han_thu_120_188","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「勸文帝大封梁、淮陽。梁卒距吳楚，不得令西也。從音子庸反。」","sentenceOrder":188},
  {"id":"s_work_han_thu_120_189","chapterId":"ch_work_han_thu_120","textTraditional":"子絲慷慨，激辭納說，〔一〕〈扌監〉轡正席，顯陳成敗。〔二〕錯之瑣材，智小謀大，〔三〕禍如發機，先寇受害。〔四〕述爰盎朝錯傳第十九。","sentenceOrder":189},
  {"id":"s_work_han_thu_120_190","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「爰盎字絲。此加子者，子是嘉稱，以偶句耳。」","sentenceOrder":190},
  {"id":"s_work_han_thu_120_191","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「〈扌監〉，執取也。其字從手，亦或作{臨手}。」","sentenceOrder":191},
  {"id":"s_work_han_thu_120_192","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「易下繫辭曰：『德薄而位尊，智小而謀大，力少而任重，鮮不及矣。』此敘言朝錯所以及禍。」","sentenceOrder":192},
  {"id":"s_work_han_thu_120_193","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「發機，言其速也。吳楚未敗之前，錯已誅死。」","sentenceOrder":193},
  {"id":"s_work_han_thu_120_194","chapterId":"ch_work_han_thu_120","textTraditional":"釋之典刑，國憲以平。馮公矯魏，增主之明。〔一〕長孺剛直，義形於色，下折淮南，上正元服。〔二〕莊之推賢，於茲為德。述張馮汲鄭傳第二十。","sentenceOrder":194},
  {"id":"s_work_han_thu_120_195","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　張晏曰：「矯辭以免魏尚也。」師古曰：「張說非也。矯，正也，正言其事。」","sentenceOrder":195},
  {"id":"s_work_han_thu_120_196","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰；「淮南王謀反，憚黯正直。武帝不冠不見黯。故云下折淮南，上正元服也。元，首也，故謂冠為元服。」","sentenceOrder":196},
  {"id":"s_work_han_thu_120_197","chapterId":"ch_work_han_thu_120","textTraditional":"榮如辱如，有機有樞，〔一〕自下摩上，惟德之隅。〔二〕賴依忠正，君子采諸。〔三〕述賈鄒枚路傳第二十一。","sentenceOrder":197},
  {"id":"s_work_han_thu_120_198","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　劉德曰：「易曰『樞機之發，榮辱之主也』。」張晏曰：「乍榮乍辱，如辭也。」","sentenceOrder":198},
  {"id":"s_work_han_thu_120_199","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「詩大雅抑之篇曰『抑抑威儀，惟德之隅』，言有廉隅也。此敘言賈山直詞刺上，亦為方正也。一曰，隅謂得道德之一隅也。」","sentenceOrder":199},
  {"id":"s_work_han_thu_120_200","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「諸，之也。」","sentenceOrder":200},
  {"id":"s_work_han_thu_120_201","chapterId":"ch_work_han_thu_120","textTraditional":"魏其翩翩，好節慕聲，〔一〕灌夫矜勇，武安驕盈，凶德相挻，禍敗用成。〔二〕安國壯趾，王恢兵首，〔三〕彼若天命，此近人咎。〔四〕述竇田灌韓傳第二十二。","sentenceOrder":201},
  {"id":"s_work_han_thu_120_202","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「翩翩，自喜之貌。」","sentenceOrder":202},
  {"id":"s_work_han_thu_120_203","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「挻謂柔挻也，音式延反。」","sentenceOrder":203},
  {"id":"s_work_han_thu_120_204","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　孟康曰：「易『壯于趾，征凶』。安國臨當為丞相，墮車，蹇。後為將，多所傷失而憂死。此為不宜征行而有凶也。」師古曰：「『壯于趾』，大壯初九爻辭也。壯，傷也。趾，足也。直謂墮車蹇耳，不言不宜征行也。」","sentenceOrder":204},
  {"id":"s_work_han_thu_120_205","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「彼，韓安國也。此，王恢也。壯趾，天命也。謀兵，人咎也。」","sentenceOrder":205},
  {"id":"s_work_han_thu_120_206","chapterId":"ch_work_han_thu_120","textTraditional":"景十三王，承文之慶。〔一〕魯恭館室，江都訬輕；〔二〕趙敬險詖，中山淫醟；〔三〕長沙寂漠，廣川亡聲；膠東不亮，常山驕盈。〔四〕四國絕祀，河間賢明，〔五〕禮樂是修，為漢宗英。述景十三王傳第二十三。","sentenceOrder":206},
  {"id":"s_work_han_thu_120_207","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「言景帝庸主耳，所以子皆得王者，由文帝之德慶流子孫也。慶合韻音卿。」","sentenceOrder":207},
  {"id":"s_work_han_thu_120_208","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「訬謂輕狡也，音初教反。」","sentenceOrder":208},
  {"id":"s_work_han_thu_120_209","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「詖，辯也，一曰佞也。醟，酗酒也，音詠，合韻音榮。」","sentenceOrder":209},
  {"id":"s_work_han_thu_120_210","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「亮，信也。聞淮南謀反，作戰具守備，後辭及之，發病死，是為不信於漢朝。」","sentenceOrder":210},
  {"id":"s_work_han_thu_120_211","chapterId":"ch_work_han_thu_120","textTraditional":"〔五〕　李奇曰：「臨江哀王閼、臨江閔王榮、膠西于王端、清河哀王乘皆無子，國除。」","sentenceOrder":211},
  {"id":"s_work_han_thu_120_212","chapterId":"ch_work_han_thu_120","textTraditional":"李廣恂恂，實獲士心，控弦貫石，威動北鄰，〔一〕躬戰七十，遂死于軍。敢怨衛青，見討去病。陵不引決，忝世滅姓。〔二〕蘇武信節，不詘王命。〔三〕述李廣蘇建傳第二十四。","sentenceOrder":212},
  {"id":"s_work_han_thu_120_213","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「北鄰謂匈奴也。」","sentenceOrder":213},
  {"id":"s_work_han_thu_120_214","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「忝，辱也。」","sentenceOrder":214},
  {"id":"s_work_han_thu_120_215","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「信讀曰申。」","sentenceOrder":215},
  {"id":"s_work_han_thu_120_216","chapterId":"ch_work_han_thu_120","textTraditional":"長平桓桓，上將之元，〔一〕薄伐獫允，恢我朔邊，〔二〕戎車七征，衝輣閑閑，〔三〕合圍單于，北登闐顏。票騎冠軍，猋勇紛紜，〔四〕長驅六舉，電擊雷震，〔五〕飲馬翰海，封狼居山，西規大河，列郡祈連。述衛青霍去病傳第二十五。","sentenceOrder":216},
  {"id":"s_work_han_thu_120_217","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「桓桓，武貌也。元，首也。」","sentenceOrder":217},
  {"id":"s_work_han_thu_120_218","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「恢，廣也。」","sentenceOrder":218},
  {"id":"s_work_han_thu_120_219","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　鄧展曰：「輣，兵車名也。」師古曰：「輣音彭。」","sentenceOrder":219},
  {"id":"s_work_han_thu_120_220","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「如猋之勇，紛紜然盛也。」","sentenceOrder":220},
  {"id":"s_work_han_thu_120_221","chapterId":"ch_work_han_thu_120","textTraditional":"〔五〕　師古曰：「六舉，凡六出擊匈奴也。震合韻音之人反。」","sentenceOrder":221},
  {"id":"s_work_han_thu_120_222","chapterId":"ch_work_han_thu_120","textTraditional":"〔六〕　張晏曰：「置郡至祈連山。」","sentenceOrder":222},
  {"id":"s_work_han_thu_120_223","chapterId":"ch_work_han_thu_120","textTraditional":"抑抑仲舒，再相諸侯，〔一〕身修國治，致仕縣車，下帷覃思，論道屬書，〔二〕讜言訪對，為世純儒。〔三〕述董仲舒傳第二十六。","sentenceOrder":223},
  {"id":"s_work_han_thu_120_224","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「爾雅云『抑抑，密也』。」","sentenceOrder":224},
  {"id":"s_work_han_thu_120_225","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「屬音之欲反。」","sentenceOrder":225},
  {"id":"s_work_han_thu_120_226","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「讜，善言也。訪對，謂對所訪也。讜音黨。」","sentenceOrder":226},
  {"id":"s_work_han_thu_120_227","chapterId":"ch_work_han_thu_120","textTraditional":"文豔用寡，子虛烏有，寓言淫麗，託風終始，〔一〕多識博物，有可觀采，蔚為辭宗，賦頌之首。〔二〕述司馬相如傳第二十七。","sentenceOrder":227},
  {"id":"s_work_han_thu_120_228","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「寓，寄也。風讀曰諷。」","sentenceOrder":228},
  {"id":"s_work_han_thu_120_229","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「蔚，文綵盛也，音鬱。」","sentenceOrder":229},
  {"id":"s_work_han_thu_120_230","chapterId":"ch_work_han_thu_120","textTraditional":"平津斤斤，晚躋金門，〔一〕既登爵位，祿賜頤賢，〔二〕布衾疏食，用儉飭身。〔三〕卜式耕牧，以求其志，忠寤明君，乃爵乃試。兒生亹亹，束髮修學，〔四〕偕列名臣，從政輔治。述公孫弘卜式兒寬傳第二十八。","sentenceOrder":230},
  {"id":"s_work_han_thu_120_231","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「斤斤，明察也。躋，升也。金門，金馬門也。」","sentenceOrder":231},
  {"id":"s_work_han_thu_120_232","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「頤，養也，謂引招賢人而養之。」","sentenceOrder":232},
  {"id":"s_work_han_thu_120_233","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「飭，整也，讀與敕同。」","sentenceOrder":233},
  {"id":"s_work_han_thu_120_234","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「亹亹，勉也。」","sentenceOrder":234},
  {"id":"s_work_han_thu_120_235","chapterId":"ch_work_han_thu_120","textTraditional":"張湯遂達，用事任職，媚茲一人，日旰忘食，〔一〕既成寵祿，亦羅咎慝。安世溫良，塞淵其德，〔二〕子孫遵業，全祚保國。述張湯傳第二十九。","sentenceOrder":235},
  {"id":"s_work_han_thu_120_236","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「詩大雅下武之篇曰『媚茲一人，應侯慎德』。一人，天子也。媚，愛也。此敘言張湯見愛於武帝。」","sentenceOrder":236},
  {"id":"s_work_han_thu_120_237","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「詩鄁風燕燕之篇曰『仲氏任只，其心塞淵』。淵，深也。塞，實也。謂其德既實且深也。此敘言子孺亦有之。」","sentenceOrder":237},
  {"id":"s_work_han_thu_120_238","chapterId":"ch_work_han_thu_120","textTraditional":"杜周治文，唯上淺深，〔一〕用取世資，幸而免身。延年寬和，列于名臣。欽用材謀，有異厥倫。〔二〕述杜周傳第三十。","sentenceOrder":238},
  {"id":"s_work_han_thu_120_239","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「言觀天子之意。」","sentenceOrder":239},
  {"id":"s_work_han_thu_120_240","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「倫，類也。言異其本類。」","sentenceOrder":240},
  {"id":"s_work_han_thu_120_241","chapterId":"ch_work_han_thu_120","textTraditional":"博望杖節，收功大夏；貳師秉鉞，身釁胡社。〔一〕致死為福，每生作禍。〔二〕述張騫李廣利傳第三十一。","sentenceOrder":241},
  {"id":"s_work_han_thu_120_242","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　李奇曰：「李廣利，胡殺之以血塗社也。」師古曰：「釁者，以血祭耳，非塗之血也。」","sentenceOrder":242},
  {"id":"s_work_han_thu_120_243","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「每，貪也。張騫致死封侯，李廣利求生而死也。」","sentenceOrder":243},
  {"id":"s_work_han_thu_120_244","chapterId":"ch_work_han_thu_120","textTraditional":"烏呼史遷，薰胥以刑！〔一〕幽而發憤，乃思乃精，錯綜群言，古今是經，勒成一家，大略孔明。〔二〕述司馬遷傳第三十二。","sentenceOrder":244},
  {"id":"s_work_han_thu_120_245","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　晉灼曰：「齊、韓、魯詩作薰。薰，帥也，從人得罪相坐之刑也。」師古曰：「晉說近是矣。詩小雅雨無正之篇曰『若此無罪，淪胥以鋪』。胥，相也。鋪，遍也。言無罪之人，遇於亂政，橫相牽率，遍得罪也。韓詩淪字作薰。薰者，謂相薰蒸，亦漸及之義耳。此敘言史遷因坐李陵，橫得罪也。」","sentenceOrder":245},
  {"id":"s_work_han_thu_120_246","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「孔，甚也。」","sentenceOrder":246},
  {"id":"s_work_han_thu_120_247","chapterId":"ch_work_han_thu_120","textTraditional":"孝武六子，昭、齊亡嗣。〔一〕燕剌謀逆，廣陵祝詛。昌邑短命，昏賀失據。戾園不幸，宣承天序。〔二〕述武五子傳第三十三。","sentenceOrder":247},
  {"id":"s_work_han_thu_120_248","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　如淳曰：「昭帝及齊王無嗣也。」師古曰：「嗣合韻音祚，」","sentenceOrder":248},
  {"id":"s_work_han_thu_120_249","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「序合韻音似豫反。」","sentenceOrder":249},
  {"id":"s_work_han_thu_120_250","chapterId":"ch_work_han_thu_120","textTraditional":"六世耽耽，其欲浟浟，〔一〕文武方作，是庸四克。〔二〕助、偃、淮南，數子之德，不忠其身，善謀於國。〔三〕述嚴朱吾丘主父徐嚴終王賈傳第三十四。","sentenceOrder":250},
  {"id":"s_work_han_thu_120_251","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「六（者）謂武帝也。易頤卦六四爻辭曰『虎視耽耽，其欲浟浟』。耽耽，威視之貌也。浟浟，欲利之貌也。耽音丁含反。浟音滌。今易浟字作逐。」","sentenceOrder":251},
  {"id":"s_work_han_thu_120_252","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　晉灼曰：「方，並也。」師古曰：「言並任文武之臣，是用克開四方也。」","sentenceOrder":252},
  {"id":"s_work_han_thu_120_253","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「淮南，謂淮南王安諫武帝不宜興兵討越也。」","sentenceOrder":253},
  {"id":"s_work_han_thu_120_254","chapterId":"ch_work_han_thu_120","textTraditional":"東方贍辭，詼諧倡優，〔一〕譏苑扞偃，正諫舉郵，〔二〕懷肉汙殿，弛張沈浮。述東方朔傳第三十五。","sentenceOrder":254},
  {"id":"s_work_han_thu_120_255","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「詼音恢。」","sentenceOrder":255},
  {"id":"s_work_han_thu_120_256","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「郵與尤同。尤，過也。」","sentenceOrder":256},
  {"id":"s_work_han_thu_120_257","chapterId":"ch_work_han_thu_120","textTraditional":"葛繹內寵，屈氂王子。〔一〕千秋時發，宜春舊仕。〔二〕敞、義依霍，庶幾云已。〔三〕弘惟政事，萬年容己。咸睡厥誨，孰為不子？述公孫劉田楊王蔡陳鄭傳第三十六。","sentenceOrder":257},
  {"id":"s_work_han_thu_120_258","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「公孫賀妻，衛皇后姊，故云內寵也。」","sentenceOrder":258},
  {"id":"s_work_han_thu_120_259","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　張晏曰：「千秋訟衛太子冤，發言值時也。」師古曰：「宜春侯，王訢也。」","sentenceOrder":259},
  {"id":"s_work_han_thu_120_260","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　如淳曰：「若此人等無益於治，可為庶幾而已也。」師古曰：「敞，楊敞。義，蔡義。」","sentenceOrder":260},
  {"id":"s_work_han_thu_120_261","chapterId":"ch_work_han_thu_120","textTraditional":"王孫臝葬，建乃斬將。雲廷訐禹，福逾刺鳳，〔一〕是謂狂狷，敞近其衷。〔二〕述楊胡朱梅云傳第三十七。","sentenceOrder":261},
  {"id":"s_work_han_thu_120_262","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「逾，遠也。」","sentenceOrder":262},
  {"id":"s_work_han_thu_120_263","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「衷，中也。論語稱孔子曰『不得中行而與之，必也狂狷乎！』此言朱雲以上蓋狂狷耳，云敞之操近於中行也。衷音竹仲反。」","sentenceOrder":263},
  {"id":"s_work_han_thu_120_264","chapterId":"ch_work_han_thu_120","textTraditional":"博陸堂堂，受遺武皇，〔一〕擁毓孝昭，末命導揚。〔二〕遭家不造，立帝廢王，權定社稷，配忠阿衡。懷祿耽寵，漸化不詳，陰妻之逆，至子而亡。〔三〕秺侯狄孥，虔恭忠信，〔四〕奕世載德，貤于子孫。〔五〕述霍光金日磾傳第三十八。","sentenceOrder":264},
  {"id":"s_work_han_thu_120_265","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「論語稱孔子曰『堂堂乎張也』，蓋美子張儀形盛也，故引之。」","sentenceOrder":265},
  {"id":"s_work_han_thu_120_266","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　劉德曰：「武帝臨終之命，（也）〔霍〕光能導達顯揚也。」","sentenceOrder":266},
  {"id":"s_work_han_thu_120_267","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「陰謂覆蔽之也。」","sentenceOrder":267},
  {"id":"s_work_han_thu_120_268","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「匈奴休屠王之子，故曰狄孥。秺音妒。信，合韻音新。」","sentenceOrder":268},
  {"id":"s_work_han_thu_120_269","chapterId":"ch_work_han_thu_120","textTraditional":"〔五〕　師古曰：「貤，延也，音弋豉反。」","sentenceOrder":269},
  {"id":"s_work_han_thu_120_270","chapterId":"ch_work_han_thu_120","textTraditional":"兵家之策，惟在不戰。營平皤皤，立功立論，〔一〕以不濟可，上諭其信。〔二〕武賢父子，虎臣之俊。述趙充國辛慶忌傳第三十九。","sentenceOrder":270},
  {"id":"s_work_han_thu_120_271","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「皤皤，白髮貌也，音蒲何反。」","sentenceOrder":271},
  {"id":"s_work_han_thu_120_272","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「春秋左氏傳晏子對齊景公曰：『君所謂可，而有不焉；臣獻其不，以成其可。』此敘言宣帝令擊西羌，充國不從，固上屯田之策也。」","sentenceOrder":272},
  {"id":"s_work_han_thu_120_273","chapterId":"ch_work_han_thu_120","textTraditional":"義陽樓蘭，長羅昆彌，安遠日逐，義成郅支。陳湯誕節，救在三悊；〔一〕會宗勤事，疆外之桀。述傅常鄭甘陳段傳第四十。","sentenceOrder":273},
  {"id":"s_work_han_thu_120_274","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　鄭氏曰：「三悊，謂劉向、谷永、耿育皆訟救湯也。」師古曰：「誕節，言其放縱不拘也。」","sentenceOrder":274},
  {"id":"s_work_han_thu_120_275","chapterId":"ch_work_han_thu_120","textTraditional":"不疑膚敏，應變當理，〔一〕辭霍不婚，逡遁致仕。〔二〕疏克有終，散金娛老。定國之祚，于其仁考。廣德、當、宣，近於知恥。〔三〕述雋疏于薛平彭傳第四十一。","sentenceOrder":275},
  {"id":"s_work_han_thu_120_276","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　劉德曰：「膚，美也。敏，疾也。言於闕下卒變，定方遂詐，非衛太子也。」師古曰：「詩大雅文王之篇曰『殷士膚敏』，謂微子也，故引以為辭。」","sentenceOrder":276},
  {"id":"s_work_han_thu_120_277","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「遁讀與巡同。」","sentenceOrder":277},
  {"id":"s_work_han_thu_120_278","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　晉灼曰：「當宣帝時始仕，至元帝時以歲惡民流，便乞骸骨去。此為知恥。」師古曰：「此說非也。當為平當也。宣，彭宣也。言廣德、平當、彭宣三人不苟于祿位，並為知恥也。本傳贊曰：『薛廣德保懸車之榮，平當逡巡有恥，彭宣見險而止：異乎苟患失之者矣。』」","sentenceOrder":278},
  {"id":"s_work_han_thu_120_279","chapterId":"ch_work_han_thu_120","textTraditional":"四皓遯秦，古之逸民，不營不拔，嚴平、鄭真。〔一〕吉困于賀，涅而不緇；禹既黃髮，以德來仕。〔二〕舍惟正身，勝死善道；郭欽、蔣詡，近遯之好。〔三〕述王貢兩龔鮑傳第四十二。","sentenceOrder":279},
  {"id":"s_work_han_thu_120_280","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　應劭曰：「爵祿不能營其志，威武不能屈其身也。易曰『不可榮以祿』，又曰『確乎不可拔也』。」","sentenceOrder":280},
  {"id":"s_work_han_thu_120_281","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「論語稱孔子曰：『不曰白乎？涅而不緇。』涅，汙泥也。可以染皂。緇，黑色也。言天性潔白者，雖處汙涅之中，其色不變也。緇，合韻音側仕反。」","sentenceOrder":281},
  {"id":"s_work_han_thu_120_282","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　應劭曰：「易曰『好遯君子吉』，言遭暴亂之世，好以和順遯去，不離其害也。」","sentenceOrder":282},
  {"id":"s_work_han_thu_120_283","chapterId":"ch_work_han_thu_120","textTraditional":"扶陽濟濟，聞詩聞禮。玄成退讓，仍世作相。〔一〕漢之宗廟，叔孫是謨，革自孝元，諸儒變度。〔二〕國之誕章，博載其路。〔三〕述韋賢傳第四十三。","sentenceOrder":283},
  {"id":"s_work_han_thu_120_284","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「仍，（類）〔頻〕也。」","sentenceOrder":284},
  {"id":"s_work_han_thu_120_285","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　如淳曰：「造迭毀之（義）〔議〕也。」師古曰：「謨，謀也，合韻音慕。」","sentenceOrder":285},
  {"id":"s_work_han_thu_120_286","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「誕，大也。謂憲章之大者，故廣載之。」","sentenceOrder":286},
  {"id":"s_work_han_thu_120_287","chapterId":"ch_work_han_thu_120","textTraditional":"高平師師，惟辟作威，圖黜凶害，天子是毗。〔一〕博陽不伐，含弘光大，天誘其衷，慶流苗裔。述魏相丙吉傳第四十四。","sentenceOrder":287},
  {"id":"s_work_han_thu_120_288","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　鄧展曰：「師師，相師法也。」師古曰：「尚書洪範云『惟辟作威』，言威權者，唯人君得作之耳。詩小雅節南山之篇曰：『尹氏太師，惟周之氐，秉國之鈞，四方是維，天子是毗。』言大臣之職，輔佐天子者也。此敘言魏相欲崇君道而黜私權，故引書詩以為言也。」","sentenceOrder":288},
  {"id":"s_work_han_thu_120_289","chapterId":"ch_work_han_thu_120","textTraditional":"占往知來，幽贊神明，〔一〕苟非其人，道不虛行。〔二〕學微術昧，或見仿佛，疑殆匪闕，違眾迕世，〔三〕淺為尤悔，深作敦害。〔四〕述眭兩夏侯京翼李傳第四十五。","sentenceOrder":289},
  {"id":"s_work_han_thu_120_290","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「易上繫辭曰『神以知來，知以藏往』，言蓍卦之德兼神知也。說卦曰『昔者聖人之作易也，幽贊於神明而生蓍』，言欲深致神明之道，助以成教，故為蓍卜也。」","sentenceOrder":290},
  {"id":"s_work_han_thu_120_291","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「下繫之辭也。言人能弘道，非其人則不能傳。」","sentenceOrder":291},
  {"id":"s_work_han_thu_120_292","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「論語稱孔子曰：『多聞闕疑，慎言其餘則寡尤；多見闕殆，慎行其餘則寡悔。』殆，危也。謂有疑則闕之也。此敘言術士不闕疑殆，故遭禍難也。」","sentenceOrder":292},
  {"id":"s_work_han_thu_120_293","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「尤，過也。敦，厚也。」","sentenceOrder":293},
  {"id":"s_work_han_thu_120_294","chapterId":"ch_work_han_thu_120","textTraditional":"廣漢尹京，克聰克明；延壽作翊，既和且平。矜能訐上，俱陷極刑。翁歸承風，帝揚厥聲。〔一〕敞；亦平平，文雅自贊；〔二〕尊實赳赳，邦家之彥；〔三〕章死非罪，士民所歎。述趙尹韓張兩王傳第四十六。","sentenceOrder":294},
  {"id":"s_work_han_thu_120_295","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　張晏曰：「受任為右扶風，卒，宣帝下詔褒揚，賜金百斤。」","sentenceOrder":295},
  {"id":"s_work_han_thu_120_296","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「平讀曰便。便，辯也。贊，助也，以文雅助治（述）〔術〕也。一說，贊，進也，以文雅自進也。」","sentenceOrder":296},
  {"id":"s_work_han_thu_120_297","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「赳赳，材勁貌也，音糾。」","sentenceOrder":297},
  {"id":"s_work_han_thu_120_298","chapterId":"ch_work_han_thu_120","textTraditional":"寬饒正色，國之司直。豐繄好剛，輔亦慕直。〔一〕皆陷狂狷，不典不式。〔二〕崇執言責，隆持官守。〔三〕寶曲定陵，並有立志。〔四〕述蓋諸葛劉鄭毋將孫何傳第四十七。〔五〕","sentenceOrder":298},
  {"id":"s_work_han_thu_120_299","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「繄，是也，音烏奚反。」","sentenceOrder":299},
  {"id":"s_work_han_thu_120_300","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「典，經也。式，法也。」","sentenceOrder":300},
  {"id":"s_work_han_thu_120_301","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　如淳曰：「崇為尚書僕射，是言責之官也。哀帝及傅太后欲封從弟商，崇諫不聽也。」晉灼曰：「隆諫武庫兵不宜以給董賢家，此為持官守也。」","sentenceOrder":301},
  {"id":"s_work_han_thu_120_302","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　鄧展曰：「孫寶曲橈定陵侯淳于長也。」晉灼曰：「何並斬侍中王林卿奴，是立志也。」","sentenceOrder":302},
  {"id":"s_work_han_thu_120_303","chapterId":"ch_work_han_thu_120","textTraditional":"〔五〕　師古曰：「本傳毋將隆在孫寶下。今此敘云毋將孫何，是敘誤也。」","sentenceOrder":303},
  {"id":"s_work_han_thu_120_304","chapterId":"ch_work_han_thu_120","textTraditional":"長倩懙懙，覿霍不舉，〔一〕遇宣乃拔，傅元作輔，不圖不慮，見躓石、許。〔二〕述蕭望之傳第四十八。","sentenceOrder":304},
  {"id":"s_work_han_thu_120_305","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　蘇林曰：「懙懙，行步安舒也。」師古曰：「不肯露索而見霍光，故不得大官也。懙音弋於反。」","sentenceOrder":305},
  {"id":"s_work_han_thu_120_306","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「詩小雅雨無正之篇云『旻天疾威，不慮不圖』也。慮，思也。圖，謀也。言幽王見天之威，不思謀也。此敘言望之思謀不詳，卒為石顯及許史所顛躓也。躓音竹二反。」","sentenceOrder":306},
  {"id":"s_work_han_thu_120_307","chapterId":"ch_work_han_thu_120","textTraditional":"子明光光，發跡西疆，列於禦侮，厥子亦良。述馮奉世傳第四十九。","sentenceOrder":307},
  {"id":"s_work_han_thu_120_308","chapterId":"ch_work_han_thu_120","textTraditional":"宣之四子，淮陽聰敏，〔一〕舅氏蘧蒢，幾陷大理。〔二〕楚孝惡疾，東平失軌，〔三〕中山凶短，母歸戎里。〔四〕元之二王，孫後大宗，〔五〕昭而不穆，大命更登。〔六〕述宣元六王傳第五十。","sentenceOrder":308},
  {"id":"s_work_han_thu_120_309","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「敏，疾也，合韻音美。」","sentenceOrder":309},
  {"id":"s_work_han_thu_120_310","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「蘧蒢，口柔，觀人顏色而為辭佞者也。言淮陽憲王舅張博為諂辭，幾陷王於大罪也。蘧音渠。蒢音除。幾音鉅依反。」","sentenceOrder":310},
  {"id":"s_work_han_thu_120_311","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「惡疾謂眚病也。軌，法則也。」","sentenceOrder":311},
  {"id":"s_work_han_thu_120_312","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　張晏曰：「戎氏女歸戎氏之里也。」","sentenceOrder":312},
  {"id":"s_work_han_thu_120_313","chapterId":"ch_work_han_thu_120","textTraditional":"〔五〕　孟康曰：「謂哀、平帝。」","sentenceOrder":313},
  {"id":"s_work_han_thu_120_314","chapterId":"ch_work_han_thu_120","textTraditional":"〔六〕　鄧展曰：「昭而不穆，有父無子。」張晏曰：「大命，帝位也。」師古曰：「更音工衡反。」","sentenceOrder":314},
  {"id":"s_work_han_thu_120_315","chapterId":"ch_work_han_thu_120","textTraditional":"樂安褏褏，古之文學，〔一〕民具爾瞻，困于二司。〔二〕安昌貨殖，朱雲作娸。〔三〕博山惇慎，受莽之疚。〔四〕述匡張孔馬傳第五十一。","sentenceOrder":315},
  {"id":"s_work_han_thu_120_316","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「褏褏，盛貌也，音弋（敘）〔救〕反。學，合韻音下教反。」","sentenceOrder":316},
  {"id":"s_work_han_thu_120_317","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「詩小雅節南山之篇曰『赫赫師尹，民具爾瞻』，言師尹之任，位尊職重，下所瞻望，而乃為不善乎，深責之也。此敘言匡衡失德，不終相位，故引以為辭耳。二司者，司隸校尉王尊劾奏衡追奏石顯揚著先帝任用傾覆之臣，司隸校尉王駿劾奏衡專地盜土也。司，合韻音先寺反。」","sentenceOrder":317},
  {"id":"s_work_han_thu_120_318","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　晉灼曰：「娸，醜也。」師古曰：「朱雲廷言欲斬張禹，是為醜惡之娸，音欹，合韻音丘吏反。」","sentenceOrder":318},
  {"id":"s_work_han_thu_120_319","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「疚，病也。孔光後更曲意從莽之欲，以病其德行也。」","sentenceOrder":319},
  {"id":"s_work_han_thu_120_320","chapterId":"ch_work_han_thu_120","textTraditional":"樂昌篤實，不橈不詘，遘閔既多，是用廢黜。〔一〕武陽殷勤，輔導副君，既忠且謀，饗茲舊勳。高武守正，因用濟身。〔二〕述王商、史丹、傅喜傳第五十二。","sentenceOrder":320},
  {"id":"s_work_han_thu_120_321","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「詩鄁柏舟曰『遘閔既多，受侮不少』。遘，遇也。閔，病也。謂見病害甚眾也。此敘言王商深為王鳳所排陷也。」","sentenceOrder":321},
  {"id":"s_work_han_thu_120_322","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「言傅喜不阿附傅太后，故得免禍。」","sentenceOrder":322},
  {"id":"s_work_han_thu_120_323","chapterId":"ch_work_han_thu_120","textTraditional":"高陽文法，揚鄉武略，政事之材，道德惟薄，位過厥任，鮮終其祿。〔一〕博之翰音，鼓妖先作。〔二〕述薛宣朱博傳第五十三。","sentenceOrder":323},
  {"id":"s_work_han_thu_120_324","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「鮮，少也，音先踐反。」","sentenceOrder":324},
  {"id":"s_work_han_thu_120_325","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　劉德曰：「易曰『翰音登于天，貞凶』。上九處非其位，亢極，故『何可長也？』位在上高，故曰翰音。博拜時聞有鼓聲也。」師古曰：「『翰音登于天』，中孚卦上九爻辭也。翰音高飛而且鳴，喻居非其位，聲過其實也。」","sentenceOrder":325},
  {"id":"s_work_han_thu_120_326","chapterId":"ch_work_han_thu_120","textTraditional":"高陵修儒，任刑養威，用合時宜，器周世資。義得其勇，如虎如貔，進不跬步，宗為鯨鯢。〔一〕述翟方進傳第五十四。","sentenceOrder":326},
  {"id":"s_work_han_thu_120_327","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「半步曰跬，音空橤反。」","sentenceOrder":327},
  {"id":"s_work_han_thu_120_328","chapterId":"ch_work_han_thu_120","textTraditional":"統微政缺，災眚屢發。永陳厥咎，戒在三七。鄴指丁、傅，略窺占術。述谷永杜鄴傳第五十五。","sentenceOrder":328},
  {"id":"s_work_han_thu_120_329","chapterId":"ch_work_han_thu_120","textTraditional":"哀、平之卹，丁、傅、莽、賢。武、嘉戚之，乃喪厥身。高樂廢黜，咸列貞臣。述何武王嘉師丹傳第五十六。","sentenceOrder":329},
  {"id":"s_work_han_thu_120_330","chapterId":"ch_work_han_thu_120","textTraditional":"淵哉若人！實好斯文。初擬相如，獻賦黃門，輟而覃思，草法篹玄，〔一〕斟酌六經，放易象論，〔二〕潛于篇籍，以章厥身。〔三〕述揚雄傳第五十七。","sentenceOrder":330},
  {"id":"s_work_han_thu_120_331","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「輟，止也。篹與撰同。言止不復作賦，草創法言及撰太玄經也。」","sentenceOrder":331},
  {"id":"s_work_han_thu_120_332","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「放音甫往反。論，論語也。」","sentenceOrder":332},
  {"id":"s_work_han_thu_120_333","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「章，明也。」","sentenceOrder":333},
  {"id":"s_work_han_thu_120_334","chapterId":"ch_work_han_thu_120","textTraditional":"獷獷亡秦，滅我聖文，〔一〕漢存其業，六學析分。是綜是理，是綱是紀，師徒彌散，著其終始。〔二〕述儒林傳第五十八。","sentenceOrder":334},
  {"id":"s_work_han_thu_120_335","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「獷獷，麤惡之貌。言無親也。獷音穬，又音九永反。」","sentenceOrder":335},
  {"id":"s_work_han_thu_120_336","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「散謂分派也。」","sentenceOrder":336},
  {"id":"s_work_han_thu_120_337","chapterId":"ch_work_han_thu_120","textTraditional":"誰毀誰譽，譽其有試。〔一〕泯泯群黎，化成良吏。〔二〕淑人君子，時同功異。沒世遺愛，民有餘思。述循吏傳第五十九。","sentenceOrder":337},
  {"id":"s_work_han_thu_120_338","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「論語稱孔子曰：『吾之於人，誰毀誰譽，如有所譽，其有所試。』此敘言人之從政，可試而知，故引以為辭也。」","sentenceOrder":338},
  {"id":"s_work_han_thu_120_339","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「黎，眾也。言群眾無知，從吏之化而成俗也。」","sentenceOrder":339},
  {"id":"s_work_han_thu_120_340","chapterId":"ch_work_han_thu_120","textTraditional":"上替下陵，姦軌不勝，猛政橫作，刑罰用興。曾是強圉，掊克為雄，〔一〕報虐以威，殃亦凶終。〔二〕述酷吏傳第六十。","sentenceOrder":340},
  {"id":"s_work_han_thu_120_341","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「詩大雅蕩之篇曰『曾是強圉，曾是掊克』。強圉，強梁禦善也。掊克，好聚斂，克害人也。言任用此人為虐於下也。掊音平侯反。」","sentenceOrder":341},
  {"id":"s_work_han_thu_120_342","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「尚書呂刑曰『皇帝哀矜庶戮之不辜，報虐以威』，言哀閔不辜之人橫被殺戮，乃報答為虐者以威而誅絕也。」","sentenceOrder":342},
  {"id":"s_work_han_thu_120_343","chapterId":"ch_work_han_thu_120","textTraditional":"四民食力，罔有兼業，大不淫侈，細不匱乏，蓋均無貧，遵王之法。〔一〕靡法靡度，民肆其詐，〔二〕偪上并下，荒殖其貨。〔三〕侯服玉食，敗俗傷化。〔四〕述貨殖傳第六十一。","sentenceOrder":343},
  {"id":"s_work_han_thu_120_344","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「論語稱孔子曰『蓋均無貧』，言為政平均不相陵奪，則無貧匱之人也，故引之。」","sentenceOrder":344},
  {"id":"s_work_han_thu_120_345","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「肆，極也。」","sentenceOrder":345},
  {"id":"s_work_han_thu_120_346","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「荒，大也。」","sentenceOrder":346},
  {"id":"s_work_han_thu_120_347","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　張晏曰：「玉食，珍食也。」","sentenceOrder":347},
  {"id":"s_work_han_thu_120_348","chapterId":"ch_work_han_thu_120","textTraditional":"開國承家，有法有制，家不臧甲，國不專殺。〔一〕矧乃齊民，作威作惠，〔二〕如台不匡，禮法是謂！〔三〕述游俠傳第六十二。","sentenceOrder":348},
  {"id":"s_work_han_thu_120_349","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「殺，合韻音所例反。」","sentenceOrder":349},
  {"id":"s_work_han_thu_120_350","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「矧，況也。齊民，齊等之人也。」","sentenceOrder":350},
  {"id":"s_work_han_thu_120_351","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　如淳曰：「台，我也。我，國家也。」師古曰：「匡，正也。台音怡。」","sentenceOrder":351},
  {"id":"s_work_han_thu_120_352","chapterId":"ch_work_han_thu_120","textTraditional":"彼何人斯，竊此富貴！營損高明，作戒後世。〔一〕述佞幸傳第六十三。","sentenceOrder":352},
  {"id":"s_work_han_thu_120_353","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「詩小雅巧言之篇，刺讒人也。其詩曰：『彼何人斯？居河之麋。』賤而惡之也。此敘亦深疾佞幸之人。故引詩文以譏之。營，惑也。」","sentenceOrder":353},
  {"id":"s_work_han_thu_120_354","chapterId":"ch_work_han_thu_120","textTraditional":"於惟帝典，戎夷猾夏；〔一〕周宣攘之，亦列風雅。〔二〕宗幽既昏，淫於褒女，〔三〕戎敗我驪，遂亡酆鄗。〔四〕大漢初定，匈奴強盛，圍我平城，寇侵邊境。〔五〕至于孝武，爰赫斯怒，王師雷起，霆擊朔野。〔六〕宣承其末，乃施洪德，震我威靈，五世來服。〔七〕王莽竊命，是傾是覆，備其變理，為世典式。述匈奴傳第六十四。","sentenceOrder":354},
  {"id":"s_work_han_thu_120_355","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「於，歎辭也。帝典，虞書舜典也。載舜命咎繇作士，戒之曰：『蠻夷猾夏。』猾，亂也。夏，諸夏也。於讀曰烏。」","sentenceOrder":355},
  {"id":"s_work_han_thu_120_356","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「攘，卻也。」","sentenceOrder":356},
  {"id":"s_work_han_thu_120_357","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「宗幽，幽王居宗周也。」","sentenceOrder":357},
  {"id":"s_work_han_thu_120_358","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　張晏曰：「申侯與戎共伐周，敗於驪山下，遂殺幽王。平王東徙都成周。」","sentenceOrder":358},
  {"id":"s_work_han_thu_120_359","chapterId":"ch_work_han_thu_120","textTraditional":"〔五〕　師古曰：「境合韻音竟。」","sentenceOrder":359},
  {"id":"s_work_han_thu_120_360","chapterId":"ch_work_han_thu_120","textTraditional":"〔六〕　師古曰：「霆，疾雷也，音廷。」","sentenceOrder":360},
  {"id":"s_work_han_thu_120_361","chapterId":"ch_work_han_thu_120","textTraditional":"〔七〕　師古曰：「自宣至平凡五帝。」","sentenceOrder":361},
  {"id":"s_work_han_thu_120_362","chapterId":"ch_work_han_thu_120","textTraditional":"西南外夷，種別域殊。南越尉佗，自王番禺，攸攸外寓，閩越、東甌。〔一〕爰洎朝鮮，燕之外區。漢興柔遠，與爾剖符。〔二〕皆恃其岨，乍臣乍驕，孝武行師，誅滅海隅。述西南夷兩越朝鮮傳第六十五。","sentenceOrder":362},
  {"id":"s_work_han_thu_120_363","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「攸攸，遠貌。」","sentenceOrder":363},
  {"id":"s_work_han_thu_120_364","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「柔，安也。剖符，謂封之也。」","sentenceOrder":364},
  {"id":"s_work_han_thu_120_365","chapterId":"ch_work_han_thu_120","textTraditional":"西戎即序，夏后是表。〔一〕周穆觀兵，荒服不旅。〔二〕漢武勞神，圖遠甚勤。王師驒驒，致誅大宛。〔三〕姼姼公主，乃女烏孫，〔四〕使命乃通，條支之瀕。〔五〕昭、宣承業，都護是立，總督城郭，三十有六，修奉朝貢，各以其職。述西城傳第六十六。","sentenceOrder":365},
  {"id":"s_work_han_thu_120_366","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　張晏曰：「表，外也。禹就敘以為外國也。」師古曰：「此說非也。表，明也，明以德化也。」","sentenceOrder":366},
  {"id":"s_work_han_thu_120_367","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　張晏曰：「觀，示也。旅，陳也。犬戎終王而朝周，穆王以不享征之，是以荒服不陳於廷也。」","sentenceOrder":367},
  {"id":"s_work_han_thu_120_368","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　鄭氏曰：「驒驒，盛也。」師古曰：「此說非也。小雅四牡之詩曰：『四牡騑騑，驒驒駱馬。』驒驒，喘息之貌。馬勞則喘，此敘言漢遠征西域，人馬疲弊也。驒音它丹反。」","sentenceOrder":368},
  {"id":"s_work_han_thu_120_369","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　孟康曰：「姼音題。姼姼、惕惕，愛也。」師古曰：「此說非也。姼音上支反。姼姼，好貌也。魏詩葛屨之篇曰『好人提提』，音義同耳。女，妻也，音乃據反。言漢以好女配烏孫也。」","sentenceOrder":369},
  {"id":"s_work_han_thu_120_370","chapterId":"ch_work_han_thu_120","textTraditional":"〔五〕　師古曰：「瀕，涯也，音頻，又音賓。」","sentenceOrder":370},
  {"id":"s_work_han_thu_120_371","chapterId":"ch_work_han_thu_120","textTraditional":"詭矣禍福，刑于外戚。〔一〕高后首命，呂宗顛覆。薄姬〈礈，去辶〉魏，宗文產德。〔二〕竇后違意，考盤于代。〔三〕王氏仄微，世武作嗣。子夫既興，扇而不終。〔四〕鉤弋憂傷，孝昭以登。上官幼尊，類禡厥宗。〔五〕史娣、王悼，身遇不祥，及宣饗國，二族後光。恭哀產元，夭而不遂。邛成乘序，履尊三世。〔六〕飛燕之妖，禍成厥妹。丁、傅僭恣，自求凶害。中山無辜，乃喪馮、衛。〔七〕惠張、景薄，武陳、宣霍，成許、哀傅，平王之作，事雖歆羨，非天所度〔八〕。怨咎若茲，如何不恪！〔九〕述外戚傳第六十七。","sentenceOrder":371},
  {"id":"s_work_han_thu_120_372","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「詭，違也。言禍福相違，終始不一也。」","sentenceOrder":372},
  {"id":"s_work_han_thu_120_373","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　如淳曰：「薄姬在魏，許負相，當生天子。魏豹聞負言，不與漢，遂禽而死也。」師古曰：「〈礈，去辶〉，古墜字。」","sentenceOrder":373},
  {"id":"s_work_han_thu_120_374","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「詩衛風曰『考盤在澗』。考，成也。盤，樂也。此敘言竇姬初欲適趙，而向代，違其本意，卒以成樂也。」","sentenceOrder":374},
  {"id":"s_work_han_thu_120_375","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「扇，熾也。」","sentenceOrder":375},
  {"id":"s_work_han_thu_120_376","chapterId":"ch_work_han_thu_120","textTraditional":"〔五〕　應劭曰：「詩云『是類是禡』。禮，將征伐，告天而祭謂之類，告以事類也。至所征伐之地，表而祭之謂之禡。禡者，馬也。馬者兵之首，故祭其先神也。言上官后雖幼尊貴，家族以惡逆誅滅也。」師古曰：「禡音莫暇反。」","sentenceOrder":376},
  {"id":"s_work_han_thu_120_377","chapterId":"ch_work_han_thu_120","textTraditional":"〔六〕　張晏曰：「至成帝乃崩也。」師古曰：「乘序，謂登至尊之處也。」","sentenceOrder":377},
  {"id":"s_work_han_thu_120_378","chapterId":"ch_work_han_thu_120","textTraditional":"〔七〕　師古曰：「馮昭儀，中山孝王母也，為傅氏所陷。衛姬，中山孝王后也，為王莽所滅。」","sentenceOrder":378},
  {"id":"s_work_han_thu_120_379","chapterId":"ch_work_han_thu_120","textTraditional":"〔八〕　師古曰：「作，起也。度，居也。言惠帝至平帝王皇后七人，時雖處尊位，人心羨慕，以非天意所居，故終用不昌也。度音徒各反。」","sentenceOrder":379},
  {"id":"s_work_han_thu_120_380","chapterId":"ch_work_han_thu_120","textTraditional":"〔九〕　師古曰：「恪，敬也。」","sentenceOrder":380},
  {"id":"s_work_han_thu_120_381","chapterId":"ch_work_han_thu_120","textTraditional":"元后娠母，月精見表。〔一〕遭成之逸，政自諸舅。〔二〕陽平作威，誅加卿宰。〔三〕成都煌煌，假我明光。〔四〕曲陽（攜攜）〔歊歊〕，亦朱其堂。〔五〕新都亢極，作亂以亡。述元后傳第六十八。","sentenceOrder":381},
  {"id":"s_work_han_thu_120_382","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　師古曰：「娠音身。」","sentenceOrder":382},
  {"id":"s_work_han_thu_120_383","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「言成帝貪自逸樂，而委政於王氏。」","sentenceOrder":383},
  {"id":"s_work_han_thu_120_384","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　師古曰：「謂王商及王章也。」","sentenceOrder":384},
  {"id":"s_work_han_thu_120_385","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　師古曰：「煌煌，熾貌。」","sentenceOrder":385},
  {"id":"s_work_han_thu_120_386","chapterId":"ch_work_han_thu_120","textTraditional":"〔五〕　師古曰：「（攜攜）〔歊歊〕，氣盛也，音許驕反。」","sentenceOrder":386},
  {"id":"s_work_han_thu_120_387","chapterId":"ch_work_han_thu_120","textTraditional":"咨爾賊臣，篡漢滔天，行驕夏癸，虐烈商辛。〔一〕偽稽黃、虞，繆稱典文，〔二〕眾怨神怒，惡復誅臻。〔三〕百王之極，究其姦昏。述王莽傳第六十九。","sentenceOrder":387},
  {"id":"s_work_han_thu_120_388","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　張晏曰：「桀名癸，紂名辛。」","sentenceOrder":388},
  {"id":"s_work_han_thu_120_389","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　師古曰：「稽，考也。」","sentenceOrder":389},
  {"id":"s_work_han_thu_120_390","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　張晏曰：「復，周也。臻，至也。十二歲歲星一復，莽稱帝十三歲而見誅也。左氏傳曰『美惡周必復』。」師古曰：「復音扶目反。」","sentenceOrder":390},
  {"id":"s_work_han_thu_120_391","chapterId":"ch_work_han_thu_120","textTraditional":"凡漢書，敘帝皇，〔一〕列官司，建侯王。〔二〕準天地，統陰陽，〔三〕闡元極，步三光。〔四〕分州域，物土疆，〔五〕窮人理，該萬方。〔六〕緯六經，綴道綱，〔七〕總百氏，贊篇章。〔八〕函雅故，通古今，〔九〕正文字，惟學林。〔一０〕述敘傳第七十。","sentenceOrder":391},
  {"id":"s_work_han_thu_120_392","chapterId":"ch_work_han_thu_120","textTraditional":"〔一〕　張晏曰：「十二紀也。」","sentenceOrder":392},
  {"id":"s_work_han_thu_120_393","chapterId":"ch_work_han_thu_120","textTraditional":"〔二〕　張晏曰：「百官表及諸侯王表也。」","sentenceOrder":393},
  {"id":"s_work_han_thu_120_394","chapterId":"ch_work_han_thu_120","textTraditional":"〔三〕　張晏曰：「準天地，天文志也。統，合也。陰陽，五行志也。」","sentenceOrder":394},
  {"id":"s_work_han_thu_120_395","chapterId":"ch_work_han_thu_120","textTraditional":"〔四〕　張晏曰：「闡，大也。元，始也。極，至也。三光，日月星也。大推上極元始以來，及星辰度數，謂律曆志。」","sentenceOrder":395},
  {"id":"s_work_han_thu_120_396","chapterId":"ch_work_han_thu_120","textTraditional":"〔五〕　張晏曰：「地理及溝洫志也。」","sentenceOrder":396},
  {"id":"s_work_han_thu_120_397","chapterId":"ch_work_han_thu_120","textTraditional":"〔六〕　張晏曰：「人理，古今人表。萬方，謂郊祀志有日月星辰天下山川人鬼之神。」","sentenceOrder":397},
  {"id":"s_work_han_thu_120_398","chapterId":"ch_work_han_thu_120","textTraditional":"〔七〕　張晏曰：「藝文志也。」","sentenceOrder":398},
  {"id":"s_work_han_thu_120_399","chapterId":"ch_work_han_thu_120","textTraditional":"〔八〕　師古曰：「贊，明也。」","sentenceOrder":399},
  {"id":"s_work_han_thu_120_400","chapterId":"ch_work_han_thu_120","textTraditional":"〔九〕　張晏曰：「包含雅訓之故，及古今之語。」","sentenceOrder":400},
  {"id":"s_work_han_thu_120_401","chapterId":"ch_work_han_thu_120","textTraditional":"〔一０〕師古曰：「信惟文學之林藪也。凡此總說帝紀、表、志、列傳，備有天地鬼神人事，政治道德，術藝文章。汎而言之，盡在漢書耳，亦不皆如張氏所說也。」","sentenceOrder":401},
  {"id":"s_work_han_thu_120_402","chapterId":"ch_work_han_thu_120","textTraditional":"校勘記","sentenceOrder":402},
  {"id":"s_work_han_thu_120_403","chapterId":"ch_work_han_thu_120","textTraditional":"四二三六頁　四行　不言（然）〔作〕而改言述，　景祐本作「作」。","sentenceOrder":403},
  {"id":"s_work_han_thu_120_404","chapterId":"ch_work_han_thu_120","textTraditional":"四二三八頁　三行　誰（能）〔可〕任用，　景祐、殿本都作「可」。王先謙說作「可」是。","sentenceOrder":404},
  {"id":"s_work_han_thu_120_405","chapterId":"ch_work_han_thu_120","textTraditional":"四二三九頁　八行　一曰（王）〔主〕奄閉門者。　景祐、殿本都作「主」，此誤。","sentenceOrder":405},
  {"id":"s_work_han_thu_120_406","chapterId":"ch_work_han_thu_120","textTraditional":"四二四０頁　六行　言其自號（寧）〔宰〕衡，景祐、殿、局本都作「宰」，此誤。","sentenceOrder":406},
  {"id":"s_work_han_thu_120_407","chapterId":"ch_work_han_thu_120","textTraditional":"四二四三頁四行秦文公造（四）〔西〕畤祭天是也。殿本作「西」。王先謙說作「西」是。","sentenceOrder":407},
  {"id":"s_work_han_thu_120_408","chapterId":"ch_work_han_thu_120","textTraditional":"四二四三頁一六行（變）〔燮〕定東西，錢大昭說「變」當作「燮」。按景祐、殿、局本都作「燮」。注同。","sentenceOrder":408},
  {"id":"s_work_han_thu_120_409","chapterId":"ch_work_han_thu_120","textTraditional":"四二四五頁一一行言陳勝初起而項羽（益）〔烈〕盛也。景祐、殿本都作「烈」。","sentenceOrder":409},
  {"id":"s_work_han_thu_120_410","chapterId":"ch_work_han_thu_120","textTraditional":"四二四五頁一二行耳（諫）〔謀〕甘公，錢大昭說「諫」當作「謀」。按景祐、殿本都作「謀」。","sentenceOrder":410},
  {"id":"s_work_han_thu_120_411","chapterId":"ch_work_han_thu_120","textTraditional":"四二五一頁四行遻，遇（之）也。景祐、殿本都無「之」字。","sentenceOrder":411},
  {"id":"s_work_han_thu_120_412","chapterId":"ch_work_han_thu_120","textTraditional":"四二五二頁二行（子）〔支〕，父母之四支也。殿本作「支」。王先謙說作「支」是。","sentenceOrder":412},
  {"id":"s_work_han_thu_120_413","chapterId":"ch_work_han_thu_120","textTraditional":"四二五七頁一五行六（者）謂武帝也。王先謙說「六者」當為「六世」。按景祐本無「者」字。","sentenceOrder":413},
  {"id":"s_work_han_thu_120_414","chapterId":"ch_work_han_thu_120","textTraditional":"四二五九頁五行武帝臨終之命，（也）〔霍〕光能導達顯揚也。殿本「也」作「霍」。王先謙說殿本是。","sentenceOrder":414},
  {"id":"s_work_han_thu_120_415","chapterId":"ch_work_han_thu_120","textTraditional":"四二六一頁一行仍，（類）〔頻〕也。景祐、殿本都作「頻」，此誤。","sentenceOrder":415},
  {"id":"s_work_han_thu_120_416","chapterId":"ch_work_han_thu_120","textTraditional":"四二六一頁二行造迭毀之（義）〔議〕也。景祐本作「義」，殿本作「議」。王先謙說作「議」是。","sentenceOrder":416},
  {"id":"s_work_han_thu_120_417","chapterId":"ch_work_han_thu_120","textTraditional":"四二六二頁五行以文雅助治（述）〔術〕也。景祐、殿、局本都作「術」，此誤。","sentenceOrder":417},
  {"id":"s_work_han_thu_120_418","chapterId":"ch_work_han_thu_120","textTraditional":"四二六三頁一六行音弋（敘）〔救〕反。景祐、殿本都作「救」，此誤。","sentenceOrder":418},
  {"id":"s_work_han_thu_120_419","chapterId":"ch_work_han_thu_120","textTraditional":"四二七〇頁七行曲陽（攜攜）〔歊歊〕，景祐、殿本都作「歊」，此誤。","sentenceOrder":419},
];

export const hanThuOverrides: Record<string, Record<string, [string, string, string]>> = {};
